INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 1, 'ในเริ่มแรกนั้นพระเจ้าทรงเนรมิตสร้างฟ้าและแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 2, 'แผ่นดินโลกนั้นก็ปราศจากรูปร่างและว่างเปล่าอยู่ ความมืดอยู่เหนือผิวน้ํา และพระวิญญาณของพระเจ้าปกอยู่เหนือผิวน้ํานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 3, 'พระเจ้าตรัสว่า “จงให้มีความสว่าง” แล้วความสว่างก็เกิดขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 4, 'พระเจ้าทรงเห็นว่าความสว่างนั้นดี และพระเจ้าทรงแยกความสว่างนั้นออกจากความมืด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 5, 'พระเจ้าทรงเรียกความสว่างนั้นว่าวัน และพระองค์ทรงเรียกความมืดนั้นว่าคืน มีเวลาเย็นและเวลาเช้าเป็นวันที่หนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 6, 'พระเจ้าตรัสว่า “จงให้มีพื้นอากาศในระหว่างน้ํา และจงให้พื้นอากาศนั้นแยกน้ําออกจากน้ํา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 7, 'พระเจ้าทรงสร้างพื้นอากาศ และทรงแยกน้ําซึ่งอยู่ใต้พื้นอากาศจากน้ําซึ่งอยู่เหนือพื้นอากาศ ก็เป็นดังนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 8, 'พระเจ้าทรงเรียกพื้นอากาศว่าฟ้า มีเวลาเย็นและเวลาเช้าเป็นวันที่สอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 9, 'พระเจ้าตรัสว่า “จงให้น้ําที่อยู่ใต้ฟ้ารวบรวมเข้าอยู่แห่งเดียวกัน และจงให้ที่แห้งปรากฏขึ้น” ก็เป็นดังนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 10, 'พระเจ้าทรงเรียกที่แห้งว่าแผ่นดิน และที่น้ํารวบรวมเข้าอยู่แห่งเดียวกันว่าทะเล พระเจ้าทรงเห็นว่าดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 11, 'พระเจ้าตรัสว่า “จงให้แผ่นดินเกิดต้นหญ้า ต้นผักที่มีเมล็ด และต้นไม้ที่ออกผลที่มีเมล็ดในผลตามชนิดของมันบนแผ่นดิน” ก็เป็นดังนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 12, 'แผ่นดินก็เกิดต้นหญ้า ต้นผักที่มีเมล็ดตามชนิดของมัน และต้นไม้ที่ออกผลที่มีเมล็ดในผลตามชนิดของมัน พระเจ้าทรงเห็นว่าดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 13, 'มีเวลาเย็นและเวลาเช้าเป็นวันที่สาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 14, 'พระเจ้าตรัสว่า “จงให้มีดวงสว่างบนพื้นฟ้าอากาศเพื่อแยกวันออกจากคืน และเพื่อใช้เป็นหมายสําคัญ และที่กําหนดฤดู วันและปีต่างๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 15, 'และจงให้เป็นดวงสว่างบนพื้นฟ้าอากาศเพื่อส่องสว่างบนแผ่นดินโลก” ก็เป็นดังนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 16, 'พระเจ้าได้ทรงสร้างดวงสว่างใหญ่สองดวง ให้ดวงสว่างที่ใหญ่กว่านั้นครองกลางวัน และให้ดวงที่เล็กกว่าครองกลางคืน พระองค์ทรงสร้างดวงดาวต่างๆด้วยเช่นกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 17, 'พระเจ้าทรงตั้งดวงสว่างเหล่านี้ไว้บนพื้นฟ้าอากาศเพื่อส่องสว่างบนแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 18, 'เพื่อครองกลางวันและครองกลางคืน และเพื่อแยกความสว่างออกจากความมืด พระเจ้าทรงเห็นว่าดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 19, 'มีเวลาเย็นและเวลาเช้าเป็นวันที่สี่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 20, 'พระเจ้าตรัสว่า “จงให้น้ําอุดมบริบูรณ์ไปด้วยสัตว์ที่มีชีวิตแหวกว่ายไปมา และให้มีนกบินไปมาบนพื้นฟ้าอากาศเหนือแผ่นดินโลก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 21, 'พระเจ้าได้ทรงสร้างปลาวาฬใหญ่ บรรดาสัตว์ที่มีชีวิตแหวกว่ายไปมาตามชนิดของมันเกิดขึ้นบริบูรณ์ในน้ํานั้น และบรรดาสัตว์ที่มีปีกตามชนิดของมัน พระเจ้าทรงเห็นว่าดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 22, 'พระเจ้าได้ทรงอวยพรสัตว์เหล่านั้นว่า “จงมีลูกดกและทวีมากขึ้น ให้น้ําในทะเลบริบูรณ์ไปด้วยสัตว์ และจงให้นกทวีมากขึ้นบนแผ่นดิน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 23, 'มีเวลาเย็นและเวลาเช้าเป็นวันที่ห้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 24, 'พระเจ้าตรัสว่า “จงให้แผ่นดินโลกเกิดสัตว์ที่มีชีวิตตามชนิดของมัน สัตว์ใช้งาน สัตว์เลื้อยคลาน และสัตว์ป่าบนแผ่นดินโลกตามชนิดของมัน” ก็เป็นดังนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 25, 'พระเจ้าได้ทรงสร้างสัตว์ป่าบนแผ่นดินโลกตามชนิดของมัน สัตว์ใช้งานตามชนิดของมัน และบรรดาสัตว์ที่เลื้อยคลานบนแผ่นดินโลกตามชนิดของมัน แล้วพระเจ้าทรงเห็นว่าดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 26, 'และพระเจ้าตรัสว่า “จงให้พวกเราสร้างมนุษย์ตามแบบฉายาของพวกเรา ตามอย่างพวกเรา และให้พวกเขาครอบครองฝูงปลาในทะเล ฝูงนกในอากาศ และสัตว์ใช้งาน ให้ครอบครองทั่วทั้งแผ่นดินโลก และบรรดาสัตว์เลื้อยคลานที่คลานไปมาบนแผ่นดินโลก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 27, 'ดังนั้นพระเจ้าได้ทรงสร้างมนุษย์ตามแบบพระฉายาของพระองค์ พระองค์ได้ทรงสร้างมนุษย์ขึ้นตามแบบพระฉายาของพระเจ้า พระองค์ได้ทรงสร้างพวกเขาให้เป็นชายและหญิง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 28, 'พระเจ้าได้ทรงอวยพรพวกเขา และพระเจ้าตรัสแก่พวกเขาว่า “จงมีลูกดกและทวีมากขึ้น จนเต็มแผ่นดิน จงมีอํานาจเหนือแผ่นดินนั้น และครอบครองฝูงปลาในทะเล ฝูงนกในอากาศ และบรรดาสัตว์ที่มีชีวิตที่เคลื่อนไหวบนแผ่นดินโลก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 29, 'พระเจ้าตรัสว่า “ดูเถิด เราให้บรรดาต้นผักที่มีเมล็ดซึ่งอยู่ทั่วพื้นแผ่นดินโลก และบรรดาต้นไม้ซึ่งมีเมล็ดในผลแก่เจ้า ให้เป็นอาหารแก่เจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 30, 'สําหรับบรรดาสัตว์ป่าบนแผ่นดินโลก บรรดานกในอากาศ และบรรดาสัตว์ที่เลื้อยคลานที่มีชีวิตบนแผ่นดินโลก เราให้บรรดาพืชผักเขียวสดเป็นอาหาร” ก็เป็นดังนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 31, 'พระเจ้าทอดพระเนตรบรรดาสิ่งที่พระองค์ได้ทรงสร้าง และดูเถิด เป็นสิ่งที่ดียิ่งนัก มีเวลาเย็นและเวลาเช้าเป็นวันที่หก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 1, 'ดังนี้ฟ้าและแผ่นดินโลกและบรรดาบริวารก็ถูกสร้างขึ้นให้สําเร็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 2, 'ในวันที่เจ็ดพระเจ้าก็เสร็จงานของพระองค์ซึ่งพระองค์ได้ทรงสร้างมาแล้วนั้น และในวันที่เจ็ดพระองค์ทรงพักการงานทั้งสิ้นของพระองค์ซึ่งพระองค์ได้ทรงสร้างมาแล้วนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 3, 'พระเจ้าทรงอวยพระพรวันที่เจ็ดและทรงตั้งวันนี้ไว้เป็นวันบริสุทธิ์ เพราะในวันนั้นพระองค์ได้ทรงหยุดพักจากการงานทั้งสิ้นของพระองค์ซึ่งพระเจ้าได้ทรงเนรมิตสร้างไว้แล้วนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 4, 'เรื่องราวของฟ้าและแผ่นดินโลกเมื่อถูกเนรมิตสร้างนั้นเป็นดังนี้ ในวันที่พระเยโฮวาห์พระเจ้าได้ทรงสร้างแผ่นดินโลกและฟ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 5, 'บรรดาต้นไม้ตามท้องทุ่งยังไม่เกิดขึ้นบนแผ่นดินโลก และบรรดาผักตามท้องทุ่งยังไม่งอกขึ้นเลย เพราะพระเยโฮวาห์พระเจ้ายังไม่ให้ฝนตกบนแผ่นดินโลก และยังไม่มีมนุษย์ที่จะทําไร่ไถนา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 6, 'แต่มีหมอกขึ้นมาจากแผ่นดินโลก ทําให้พื้นแผ่นดินเปียกทั่วไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 7, 'พระเยโฮวาห์พระเจ้าทรงปั้นมนุษย์ด้วยผงคลีดิน ทรงระบายลมปราณแห่งชีวิตเข้าทางจมูกของเขา และมนุษย์จึงเกิดเป็นจิตวิญญาณมีชีวิตอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 8, 'พระเยโฮวาห์พระเจ้าทรงปลูกสวนแห่งหนึ่งไว้ในเอเดนทางทิศตะวันออก และพระองค์ได้ทรงให้มนุษย์ซึ่งพระองค์ได้ทรงปั้นมานั้นอาศัยอยู่ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 9, 'แล้วพระเยโฮวาห์พระเจ้าทรงให้บรรดาต้นไม้ที่งามน่าดูและที่เหมาะสําหรับเป็นอาหารงอกขึ้นบนแผ่นดินโลก มีต้นไม้แห่งชีวิตอยู่ท่ามกลางสวนด้วย และมีต้นไม้แห่งความรู้ดีและรู้ชั่ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 10, 'มีแม่น้ําสายหนึ่งไหลออกจากเอเดนรดสวนนั้น จากที่นั่นได้แยกออกเป็นแม่น้ําสี่สาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 11, 'ชื่อของแม่น้ําสายที่หนึ่งคือปิโชน ซึ่งไหลรอบแผ่นดินฮาวิลาห์ ที่นั่นมีแร่ทองคํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 12, 'ทองคําที่แผ่นดินนั้นเป็นทองคําเนื้อดี มียางไม้หอม และพลอยสีน้ําข้าว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 13, 'ชื่อแม่น้ําสายที่สองคือกีโฮน แม่น้ําสายนี้ได้ไหลรอบแผ่นดินเอธิโอเปีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 14, 'ชื่อแม่น้ําสายที่สามคือไทกริส ซึ่งได้ไหลไปทางทิศตะวันออกของแผ่นดินอัสซีเรีย และแม่น้ําสายที่สี่คือยูเฟรติส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 15, 'พระเยโฮวาห์พระเจ้าจึงทรงนํามนุษย์ไปอยู่ในสวนเอเดนให้ดูแลและรักษาสวน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 16, 'พระเยโฮวาห์พระเจ้าจึงทรงมีพระดํารัสสั่งมนุษย์นั้นว่า “บรรดาต้นไม้ทุกอย่างในสวนเจ้ากินได้ทั้งหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 17, 'แต่ต้นไม้แห่งความรู้ดีและรู้ชั่วเจ้าอย่ากินผลจากต้นนั้นเป็นอันขาด เพราะว่าเจ้ากินในวันใด เจ้าจะตายแน่ในวันนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 18, 'พระเยโฮวาห์พระเจ้าตรัสว่า “ซึ่งมนุษย์นั้นอยู่คนเดียวก็ไม่เหมาะ เราจะสร้างผู้อุปถัมภ์ให้เขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 19, 'พระเยโฮวาห์พระเจ้าทรงปั้นบรรดาสัตว์ในท้องทุ่ง และบรรดานกในอากาศจากดิน แล้วจึงพามายังอาดัมเพื่อดูว่าเขาจะเรียกชื่อพวกมันว่าอะไร อาดัมได้เรียกชื่อบรรดาสัตว์ที่มีชีวิตอย่างไร สัตว์ก็มีชื่ออย่างนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 20, 'อาดัมได้ตั้งชื่อบรรดาสัตว์ใช้งาน บรรดานกในอากาศ และบรรดาสัตว์ในท้องทุ่ง แต่ว่าสําหรับอาดัมยังไม่พบผู้อุปถัมภ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 21, 'แล้วพระเยโฮวาห์พระเจ้าทรงกระทําให้อาดัมหลับสนิท และเขาได้หลับสนิท พระองค์จึงทรงชักกระดูกซี่โครงอันหนึ่งของเขาออกมา และทรงกระทําให้เนื้อที่ซี่โครงติดกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 22, 'กระดูกซี่โครงซึ่งพระเยโฮวาห์พระเจ้าได้ทรงชักจากชายนั้น พระองค์ทรงสร้างให้เป็นหญิงคนหนึ่ง และทรงนําเธอมาให้ชายนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 23, 'อาดัมจึงว่า “บัดนี้ นี่เป็นกระดูกจากกระดูกของเรา และเนื้อจากเนื้อของเรา จะต้องเรียกเธอว่าหญิง เพราะว่าหญิงนี้ออกมาจากชาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 24, 'เหตุฉะนั้นผู้ชายจะจากบิดามารดาของเขา และจะไปผูกพันอยู่กับภรรยา และเขาทั้งสองจะเป็นเนื้ออันเดียวกัน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 25, 'เขาทั้งสองยังเปลือยกายอยู่ ผู้ชายและภรรยาของเขายังไม่มีความอาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 1, 'งูนั้นเป็นสัตว์ที่ฉลาดกว่าบรรดาสัตว์ในท้องทุ่งซึ่งพระเยโฮวาห์พระเจ้าได้ทรงสร้างไว้ มันกล่าวแก่หญิงนั้นว่า “จริงหรือที่พระเจ้าตรัสว่า ‘เจ้าอย่ากินผลจากต้นไม้ทุกชนิดในสวนนี้’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 2, 'หญิงนั้นจึงกล่าวแก่งูว่า “ผลของต้นไม้ชนิดต่างๆในสวนนี้เรากินได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 3, 'แต่ผลของต้นไม้ต้นหนึ่งซึ่งอยู่ท่ามกลางสวน พระเจ้าตรัสว่า ‘เจ้าอย่ากินหรือแตะต้องมัน มิฉะนั้นเจ้าจะตาย’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 4, 'งูจึงกล่าวแก่หญิงนั้นว่า “เจ้าจะไม่ตายแน่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 5, 'เพราะว่าพระเจ้าทรงทราบว่า เจ้ากินผลไม้นั้นวันใด ตาของเจ้าจะสว่างขึ้นวันนั้น และเจ้าจะเป็นเหมือนพระที่รู้ดีรู้ชั่ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 6, 'เมื่อหญิงนั้นเห็นว่า ต้นไม้นั้นเหมาะสําหรับเป็นอาหารและมันงามน่าดู และต้นไม้ต้นนั้นเป็นที่น่าปรารถนาเพื่อให้เกิดปัญญา หญิงจึงเก็บผลไม้นั้นแล้วกินเข้าไป แล้วส่งให้สามีของนางด้วย และเขาได้กิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 7, 'ตาของเขาทั้งสองก็สว่างขึ้น เขาจึงรู้ว่าเขาเปลือยกายอยู่ และเขาทั้งสองก็เอาใบมะเดื่อมาเย็บเป็นเครื่องปกปิดอวัยวะส่วนล่างของเขาไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 8, 'ในเวลาเย็นวันนั้นเขาทั้งสองได้ยินพระสุรเสียงของพระเยโฮวาห์พระเจ้าเสด็จดําเนินอยู่ในสวน อาดัมและภรรยาของเขาซ่อนตัวจากพระพักตร์ของพระเยโฮวาห์พระเจ้าท่ามกลางต้นไม้ต่างๆในสวนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 9, 'พระเยโฮวาห์พระเจ้าทรงเรียกอาดัมและตรัสแก่เขาว่า “เจ้าอยู่ที่ไหน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 10, 'เขาทูลว่า “ข้าพระองค์ได้ยินพระสุรเสียงของพระองค์ในสวน และข้าพระองค์ก็กลัว เพราะว่าข้าพระองค์เปลือยกายอยู่ ข้าพระองค์จึงได้ซ่อนตัวเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 11, 'พระองค์ตรัสว่า “ใครได้บอกเจ้าว่าเจ้าเปลือยกายอยู่ เจ้าได้กินผลจากต้นไม้นั้น ซึ่งเราสั่งเจ้าไว้ว่าเจ้าอย่ากินแล้วหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 12, 'ชายนั้นทูลว่า “หญิงซึ่งพระองค์ทรงประทานให้อยู่กับข้าพระองค์นั้น นางได้ส่งผลจากต้นไม้ ข้าพระองค์จึงรับประทาน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 13, 'พระเยโฮวาห์พระเจ้าตรัสแก่หญิงนั้นว่า “เจ้าทําอะไรลงไป” หญิงนั้นทูลว่า “งูล่อลวงข้าพระองค์ ข้าพระองค์จึงรับประทาน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 14, 'พระเยโฮวาห์พระเจ้าตรัสแก่งูนั้นว่า “เพราะเหตุที่เจ้าได้กระทําเช่นนี้ เจ้าถูกสาปแช่งมากกว่าบรรดาสัตว์ใช้งาน และบรรดาสัตว์ในท้องทุ่ง เจ้าจะเลื้อยไปด้วยท้องของเจ้า และเจ้าจะกินผงคลีดินตลอดวันเวลาในชีวิตของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 15, 'เราจะให้เจ้ากับหญิงนี้เป็นปฏิปักษ์กัน ทั้งเชื้อสายของเจ้ากับเชื้อสายของนาง เชื้อสายของนางจะกระทําให้หัวของเจ้าฟกช้ํา และเจ้าจะกระทําให้ส้นเท้าของท่านฟกช้ํา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 16, 'พระองค์ตรัสแก่หญิงนั้นว่า “เราจะเพิ่มความทุกข์ยากให้มากขึ้นแก่เจ้าและการตั้งครรภ์ของเจ้า เจ้าจะคลอดบุตรด้วยความเจ็บปวด เจ้ายังต้องการสามีของเจ้า และเขาจะปกครองเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 17, 'พระองค์ตรัสแก่อาดัมว่า “เพราะเหตุเจ้าได้ฟังเสียงของภรรยาเจ้า และได้กินผลจากต้นไม้ ซึ่งเราได้สั่งเจ้าว่า เจ้าอย่ากินผลจากต้นนั้น แผ่นดินจึงต้องถูกสาปแช่งเพราะตัวเจ้า เจ้าจะต้องหากินบนแผ่นดินนั้นด้วยความทุกข์ยากตลอดวันเวลาในชีวิตของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 18, 'แผ่นดินจะงอกต้นไม้ที่มีหนามและผักที่มีหนามแก่เจ้า และเจ้าจะกินผักในท้องทุ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 19, 'เจ้าจะต้องหากินด้วยเหงื่อไหลโซมหน้าจนกว่าเจ้ากลับไปเป็นดิน เพราะเจ้ามาจากดิน เจ้าเป็นผงคลีดิน และเจ้าจะกลับไปเป็นผงคลีดิน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 20, 'อาดัมเรียกชื่อภรรยาของเขาว่าเอวา เพราะว่านางเป็นมารดาของบรรดาประชาชาติที่มีชีวิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 21, 'พระเยโฮวาห์พระเจ้าทรงทําเสื้อคลุมด้วยหนังสัตว์แก่อาดัมและภรรยาและสวมใส่ให้เขาทั้งสอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 22, 'พระเยโฮวาห์พระเจ้าตรัสว่า “ดูเถิด มนุษย์กลายมาเป็นเหมือนผู้หนึ่งในพวกเราที่รู้จักความดีและความชั่ว บัดนี้เกรงว่าเขาจะยื่นมือไปหยิบผลจากต้นไม้แห่งชีวิตมากินด้วยกัน และมีชีวิตนิรันดร์ตลอดไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 23, 'เหตุฉะนั้นพระเยโฮวาห์พระเจ้าจึงทรงให้เขาออกไปจากสวนเอเดน เพื่อทําไร่ไถนาจากที่ดินที่เขากําเนิดมานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 24, 'ดังนั้นพระองค์ทรงไล่มนุษย์ออกไป ทรงตั้งพวกเครูบไว้ทางทิศตะวันออกของสวนเอเดน และตั้งดาบเพลิงซึ่งหมุนได้รอบทิศทาง เพื่อป้องกันทางเข้าไปสู่ต้นไม้แห่งชีวิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 1, 'อาดัมได้ร่วมรู้กับเอวาภรรยาของเขา นางได้ตั้งครรภ์ และคลอดบุตรชื่อคาอิน จึงกล่าวว่า “ข้าพเจ้าได้รับชายคนหนึ่งจากพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 2, 'นางได้คลอดบุตรอีกครั้งหนึ่งซึ่งเป็นน้องชายของเขาชื่ออาแบล อาแบลเป็นคนเลี้ยงแกะ แต่คาอินเป็นคนทําไร่ไถนา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 3, 'อยู่มาวันหนึ่งปรากฏว่า คาอินได้นําผลไม้จากไร่นามาเป็นเครื่องบูชาถวายพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 4, 'เช่นกันอาแบลได้นําผลแรกจากฝูงแกะของเขาและไขมันของแกะ พระเยโฮวาห์ทรงพอพระทัยต่ออาแบลและเครื่องบูชาของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 5, 'แต่พระองค์ไม่ทรงพอพระทัยต่อคาอินและเครื่องบูชาของเขา และคาอินได้โกรธแค้นยิ่งนัก สีหน้าหม่นหมองไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 6, 'พระเยโฮวาห์ได้ตรัสแก่คาอินว่า “ทําไมเจ้าถึงโกรธแค้น และทําไมสีหน้าเจ้าหม่นหมองไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 7, 'ถ้าเจ้าทําดี เจ้าจะไม่เป็นที่ยอมรับหรอกหรือ ถ้าเจ้าทําไม่ดี บาปก็ซุ่มอยู่ที่ประตู มันปรารถนาในตัวเจ้า และเจ้าจะครอบครองมัน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 8, 'คาอินพูดกับอาแบลน้องชายของเขา ต่อมาเมื่อเขาทั้งสองอยู่ในที่นาด้วยกัน คาอินได้ลุกขึ้นต่อสู้อาแบลน้องชายของเขาและฆ่าเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 9, 'พระเยโฮวาห์ตรัสแก่คาอินว่า “อาแบลน้องชายของเจ้าอยู่ที่ไหน” เขาทูลว่า “ข้าพระองค์ไม่ทราบ ข้าพระองค์เป็นผู้ดูแลน้องชายหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 10, 'พระองค์ตรัสว่า “เจ้าทําอะไรไป เสียงร้องของโลหิตน้องชายของเจ้าร้องจากดินถึงเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 11, 'บัดนี้เจ้าถูกสาปแช่งจากแผ่นดินแล้ว ซึ่งได้อ้าปากรับโลหิตน้องชายของเจ้าจากมือเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 12, 'เมื่อเจ้าทําไร่ไถนา มันจะไม่เกิดผลแก่เจ้าเหมือนเดิม เจ้าจะต้องพเนจรร่อนเร่ไปมาในโลก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 13, 'คาอินทูลแด่พระเยโฮวาห์ว่า “โทษของข้าพระองค์หนักเหลือที่ข้าพระองค์จะแบกรับได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 14, 'ดูเถิด วันนี้พระองค์ได้ทรงขับไล่ข้าพระองค์จากพื้นแผ่นดินโลก ข้าพระองค์จะถูกซ่อนไว้จากพระพักตร์ของพระองค์ และข้าพระองค์จะพเนจรร่อนเร่ไปมาในโลก จากนั้นทุกคนที่พบข้าพระองค์จะฆ่าข้าพระองค์เสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 15, 'พระเยโฮวาห์ตรัสแก่เขาว่า “เหตุฉะนั้นใครก็ตามที่ฆ่าคาอิน จะรับโทษถึงเจ็ดเท่า” แล้วเกรงว่าใครที่พบเขาจะฆ่าเขา พระเยโฮวาห์จึงทรงประทับตราที่ตัวคาอิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 16, 'คาอินได้ออกไปจากพระพักตร์ของพระเยโฮวาห์ และอาศัยอยู่เมืองโนดทางด้านทิศตะวันออกของเอเดน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 17, 'คาอินได้ร่วมรู้กับภรรยาของเขา นางได้ตั้งครรภ์ และคลอดบุตรชื่อเอโนค เขาสร้างเมืองขึ้นมาเมืองหนึ่งและเรียกชื่อเมืองนั้นตามชื่อบุตรชายของเขาว่าเอโนค');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 18, 'เอโนคให้กําเนิดบุตรชื่ออิราด อิราดให้กําเนิดบุตรชื่อเมหุยาเอล เมหุยาเอลให้กําเนิดบุตรชื่อเมธูซาเอล เมธูซาเอลให้กําเนิดบุตรชื่อลาเมค');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 19, 'ลาเมคได้ภรรยาสองคน คนหนึ่งมีชื่อว่าอาดาห์ อีกคนหนึ่งมีชื่อว่าศิลลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 20, 'นางอาดาห์คลอดบุตรชื่อว่ายาบาล เขาเป็นต้นตระกูลของคนที่อาศัยอยู่ในเต็นท์และคนที่เลี้ยงสัตว์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 21, 'น้องชายของเขามีชื่อว่ายูบาล เขาเป็นต้นตระกูลของบรรดาคนที่ดีดพิณเขาคู่และเป่าขลุ่ย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 22, 'นางศิลลาห์คลอดบุตรด้วยชื่อว่าทูบัลคาอิน ซึ่งเป็นผู้สอนบรรดาช่างฝีมือทําเครื่องทองเหลืองและเหล็ก ทูบัลคาอินมีน้องสาวชื่อว่านาอามาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 23, 'ลาเมคพูดกับภรรยาทั้งสองของเขาว่า “อาดาห์และศิลลาห์ จงฟังเสียงของเรา ภรรยาทั้งสองของลาเมค จงเชื่อฟังถ้อยคําของเรา เพราะเราได้ฆ่าคนๆหนึ่งที่ทําให้เราบาดเจ็บ ชายหนุ่มที่ทําอันตรายแก่เรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 24, 'ถ้าผู้ที่ฆ่าคาอินจะได้รับโทษเป็นเจ็ดเท่า แล้วผู้ที่ฆ่าลาเมคจะได้รับโทษเจ็ดสิบเจ็ดเท่าเป็นแน่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 25, 'อาดัมได้ร่วมรู้กับภรรยาของเขาอีกครั้งหนึ่ง นางได้คลอดบุตรชายคนหนึ่ง และเรียกชื่อของเขาว่าเสท นางพูดว่า “เพราะว่าพระเจ้าทรงโปรดให้ข้าพเจ้ามีเชื้อสายอีกคนหนึ่งแทนอาแบล ผู้ซึ่งถูกคาอินฆ่าตาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 26, 'ฝ่ายเสทกําเนิดบุตรชายคนหนึ่งด้วย เขาเรียกชื่อของเขาว่าเอโนช ตั้งแต่นั้นมามนุษย์เริ่มต้นที่จะร้องเรียกพระนามของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 1, 'นี้เป็นหนังสือลําดับพงศ์พันธุ์ของอาดัม ในวันที่พระเจ้าได้ทรงสร้างมนุษย์นั้น พระองค์ทรงสร้างตามแบบพระฉายาของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 2, 'พระองค์ทรงสร้างให้เป็นผู้ชายและผู้หญิง และทรงอวยพระพรแก่เขา และทรงเรียกชื่อเขาทั้งสองว่าอาดัม ในวันที่เขาถูกสร้างขึ้นนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 3, 'และอาดัมอยู่มาได้หนึ่งร้อยสามสิบปี และให้กําเนิดบุตรชายคนหนึ่งมีรูปร่างหน้าตาคล้ายคลึงกันกับเขา และเรียกชื่อของเขาว่าเสท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 4, 'ตั้งแต่อาดัมให้กําเนิดเสทแล้ว ก็มีอายุต่อไปอีกแปดร้อยปี และเขาให้กําเนิดบุตรชายและบุตรสาวหลายคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 5, 'รวมอายุที่อาดัมมีชีวิตอยู่ได้เก้าร้อยสามสิบปีและเขาได้สิ้นชีวิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 6, 'เสทอยู่มาได้ร้อยห้าปี และให้กําเนิดบุตรชื่อเอโนช');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 7, 'ตั้งแต่เสทให้กําเนิดเอโนชแล้ว ก็มีอายุต่อไปอีกแปดร้อยเจ็ดปี และให้กําเนิดบุตรชายและบุตรสาวหลายคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 8, 'รวมอายุของเสทได้เก้าร้อยสิบสองปีและเขาได้สิ้นชีวิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 9, 'เอโนชอยู่มาได้เก้าสิบปี และให้กําเนิดบุตรชื่อเคนัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 10, 'ตั้งแต่เอโนชให้กําเนิดเคนันแล้ว ก็มีอายุต่อไปอีกแปดร้อยสิบห้าปี และให้กําเนิดบุตรชายและบุตรสาวหลายคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 11, 'รวมอายุของเอโนชได้เก้าร้อยห้าปีและเขาได้สิ้นชีวิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 12, 'เคนันอยู่มาได้เจ็ดสิบปี และให้กําเนิดบุตรชื่อมาหะลาเลล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 13, 'ตั้งแต่เคนันให้กําเนิดมาหะลาเลลแล้ว ก็มีอายุต่อไปอีกแปดร้อยสี่สิบปี และให้กําเนิดบุตรชายและบุตรสาวหลายคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 14, 'รวมอายุของเคนันได้เก้าร้อยสิบปีและเขาได้สิ้นชีวิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 15, 'มาหะลาเลลอยู่มาได้หกสิบห้าปี และให้กําเนิดบุตรชื่อยาเรด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 16, 'ตั้งแต่มาหะลาเลลให้กําเนิดยาเรดแล้ว ก็มีอายุต่อไปอีกแปดร้อยสามสิบปี และให้กําเนิดบุตรชายและบุตรสาวหลายคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 17, 'รวมอายุของมาหะลาเลลได้แปดร้อยเก้าสิบห้าปีและเขาได้สิ้นชีวิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 18, 'ยาเรดอยู่มาได้ร้อยหกสิบสองปี และให้กําเนิดบุตรชื่อเอโนค');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 19, 'ตั้งแต่ยาเรดให้กําเนิดเอโนคแล้ว ก็มีอายุต่อไปอีกแปดร้อยปี และให้กําเนิดบุตรชายและบุตรสาวหลายคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 20, 'รวมอายุของยาเรดได้เก้าร้อยหกสิบสองปีและเขาได้สิ้นชีวิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 21, 'เอโนคอยู่มาได้หกสิบห้าปี และให้กําเนิดบุตรชื่อเมธูเสลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 22, 'ตั้งแต่เอโนคให้กําเนิดเมธูเสลาห์แล้ว ก็ดําเนินกับพระเจ้าสามร้อยปี และให้กําเนิดบุตรชายและบุตรสาวหลายคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 23, 'รวมอายุของเอโนคได้สามร้อยหกสิบห้าปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 24, 'เอโนคได้ดําเนินกับพระเจ้า และหายไป เพราะพระเจ้าทรงรับเขาไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 25, 'เมธูเสลาห์อยู่มาได้ร้อยแปดสิบเจ็ดปี และให้กําเนิดบุตรชื่อลาเมค');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 26, 'ตั้งแต่เมธูเสลาห์ให้กําเนิดลาเมคแล้ว ก็มีอายุต่อไปอีกเจ็ดร้อยแปดสิบสองปี และให้กําเนิดบุตรชายและบุตรสาวหลายคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 27, 'รวมอายุของเมธูเสลาห์ได้เก้าร้อยหกสิบเก้าปีและเขาได้สิ้นชีวิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 28, 'ลาเมคอยู่มาได้ร้อยแปดสิบสองปี และให้กําเนิดบุตรชายคนหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 29, 'เขาเรียกชื่อบุตรชายว่า โนอาห์ กล่าวว่า “คนนี้จะเป็นที่ปลอบประโลมใจเราเกี่ยวกับการงานของเรา และความเหนื่อยยากของมือเรา เพราะเหตุแผ่นดินที่พระเยโฮวาห์ได้ทรงสาปแช่งนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 30, 'ตั้งแต่ลาเมคให้กําเนิดโนอาห์แล้ว ก็มีอายุต่อไปอีกห้าร้อยเก้าสิบห้าปี และให้กําเนิดบุตรชายและบุตรสาวหลายคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 31, 'รวมอายุของลาเมคได้เจ็ดร้อยเจ็ดสิบเจ็ดปีและเขาได้สิ้นชีวิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 32, 'โนอาห์มีอายุได้ห้าร้อยปี และโนอาห์ให้กําเนิดบุตรชื่อเชม ฮาม และยาเฟท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 1, 'ต่อมาเมื่อมนุษย์เริ่มทวีมากขึ้นบนพื้นแผ่นดินโลก และพวกเขาให้กําเนิดบุตรสาวหลายคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 2, 'บุตรชายทั้งหลายของพระเจ้าเห็นว่าบุตรสาวทั้งหลายของมนุษย์สวยงาม และพวกเขารับเธอทั้งหลายไว้เป็นภรรยาตามชอบใจของพวกเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 3, 'พระเยโฮวาห์ตรัสว่า “วิญญาณของเราจะไม่วิงวอนกับมนุษย์ตลอดไป เพราะเขาเป็นแต่เนื้อหนัง อายุของเขาจะเพียงแค่ร้อยยี่สิบปี”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 4, 'ในคราวนั้นมีพวกมนุษย์ยักษ์บนแผ่นดินโลก แล้วภายหลังเมื่อบุตรชายทั้งหลายของพระเจ้าเข้าหาบุตรสาวทั้งหลายของมนุษย์ และเธอทั้งหลายคลอดบุตรให้แก่พวกเขา บุตรเหล่านั้นเป็นคนมีอํานาจมาก ตั้งแต่สมัยโบราณเป็นคนมีชื่อเสียง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 5, 'และพระเจ้าทรงเห็นว่าความชั่วของมนุษย์มีมากบนแผ่นดินโลก และเจตนาทุกอย่างแห่งความคิดทั้งหลายในใจของเขาล้วนแต่ชั่วร้ายอย่างเดียวเสมอไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 6, 'พระเยโฮวาห์ทรงโทมนัสที่พระองค์ได้ทรงสร้างมนุษย์บนแผ่นดินโลก และกระทําให้พระองค์ทรงเศร้าโศกภายในพระทัยของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 7, 'พระเยโฮวาห์ตรัสว่า “เราจะทําลายมนุษย์ที่เราได้สร้างมาจากพื้นแผ่นดินโลก ทั้งมนุษย์และสัตว์และสัตว์เลื้อยคลานและนกในอากาศ เพราะว่าเราเสียใจที่เราได้สร้างพวกเขามา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 8, 'แต่โนอาห์เป็นที่โปรดปรานในสายพระเนตรของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 9, 'ต่อไปนี้คือพงศ์พันธุ์ของโนอาห์ โนอาห์เป็นคนชอบธรรมและดีรอบคอบในสมัยของท่าน และโนอาห์ดําเนินกับพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 10, 'โนอาห์ให้กําเนิดบุตรชายสามคน ชื่อเชม ฮาม และยาเฟท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 11, 'ดังนั้นมนุษย์โลกจึงชั่วช้าต่อพระพักตร์พระเจ้า และแผ่นดินโลกก็เต็มไปด้วยความอํามหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 12, 'พระเจ้าทอดพระเนตรบนแผ่นดินโลก และดูเถิด แผ่นดินโลกก็ชั่วช้า เพราะว่าบรรดาเนื้อหนังได้กระทําการชั่วช้าบนแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 13, 'พระเจ้าตรัสแก่โนอาห์ว่า “ต่อหน้าเราบรรดาเนื้อหนังก็มาถึงวาระสุดท้ายแล้ว เพราะว่าแผ่นดินโลกเต็มไปด้วยความอํามหิตเพราะพวกเขา และดูเถิด เราจะทําลายพวกเขาพร้อมกับแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 14, 'เจ้าจงต่อนาวาด้วยไม้สนโกเฟอร์ เจ้าจงทําเป็นห้องๆในนาวา และยาทั้งข้างในข้างนอกด้วยชัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 15, 'เจ้าจงต่อนาวาตามนี้ นาวายาวสามร้อยศอก กว้างห้าสิบศอก และสูงสามสิบศอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 16, 'เจ้าจงทําช่องในนาวา และให้อยู่ข้างบนขนาดศอกหนึ่ง และเจ้าจงตั้งประตูที่ด้านข้างนาวา เจ้าจงทําเป็นชั้นล่าง ชั้นที่สองและชั้นที่สาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 17, 'ดูเถิด เราเองเป็นผู้กระทําให้น้ําท่วมบนแผ่นดินโลก เพื่อทําลายบรรดาเนื้อหนังใต้ฟ้าที่มีลมปราณแห่งชีวิต และทุกสิ่งบนแผ่นดินโลกจะตายสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 18, 'แต่เราจะตั้งพันธสัญญาของเราไว้กับเจ้า และเจ้าจงเข้าอยู่ในนาวา ทั้งเจ้า บุตรชาย ภรรยาและบุตรสะใภ้ของเจ้าพร้อมกับเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 19, 'เจ้าจงนําสัตว์ทั้งปวงที่มีชีวิตทั้งตัวผู้และตัวเมียทุกชนิดอย่างละคู่เข้าไปในนาวาเพื่อรักษาชีวิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 20, 'นกตามชนิดของมัน และสัตว์ใช้งานตามชนิดของมัน สัตว์เลื้อยคลานตามชนิดของมัน อย่างละคู่จะมาหาเจ้าเพื่อรักษาชีวิตไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 21, 'เจ้าจงหาอาหารทุกอย่างที่กินได้ และสะสมไว้สําหรับเจ้า และมันจะเป็นอาหารสําหรับเจ้าและสัตว์ทั้งปวง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 22, 'โนอาห์ได้กระทําตามทุกสิ่งที่พระเจ้าทรงบัญชาแก่ท่าน ดังนั้นท่านจึงกระทํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 1, 'และพระเยโฮวาห์ตรัสแก่โนอาห์ว่า “เจ้าและครอบครัวทั้งหมดจงเข้าไปในนาวา เพราะว่าเราเห็นว่า เจ้าชอบธรรมต่อหน้าเราในชั่วอายุนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 2, 'เจ้าจงเอาสัตว์ทั้งปวงที่สะอาดทั้งตัวผู้และตัวเมียอย่างละเจ็ดตัว และสัตว์ทั้งปวงที่ไม่สะอาดทั้งตัวผู้และตัวเมียอย่างละคู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 3, 'นกในอากาศทั้งตัวผู้และตัวเมียอย่างละเจ็ดตัวด้วย เพื่อรักษาชีวิตไว้ให้สืบเชื้อสายบนพื้นแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 4, 'เพราะว่าอีกเจ็ดวันเราจะบันดาลให้ฝนตกบนแผ่นดินโลกสี่สิบวันสี่สิบคืน และสิ่งที่มีชีวิตทั้งปวงที่เราสร้างมานั้นเราจะทําลายเสียจากพื้นแผ่นดินโลก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 5, 'โนอาห์ได้กระทําตามทุกสิ่งที่พระเยโฮวาห์ทรงบัญชาแก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 6, 'เมื่อน้ําท่วมบนแผ่นดินโลกโนอาห์มีอายุได้หกร้อยปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 7, 'โนอาห์ทั้งบุตรชาย ภรรยาและบุตรสะใภ้ทั้งหลายจึงเข้าไปในนาวาเพราะเหตุน้ําท่วม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 8, 'สัตว์ทั้งปวงที่สะอาดและสัตว์ทั้งปวงที่ไม่สะอาดและฝูงนกและบรรดาสัตว์ที่เลื้อยคลานบนแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 9, 'ได้เข้าไปหาโนอาห์ในนาวาเป็นคู่ๆทั้งตัวผู้และตัวเมีย ตามที่พระเจ้าได้ทรงบัญชาไว้แก่โนอาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 10, 'ต่อมาอีกเจ็ดวันน้ําก็ท่วมบนแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 11, 'เมื่อโนอาห์มีชีวิตอยู่ได้หกร้อยปี ในเดือนที่สอง วันที่สิบเจ็ดของเดือนนั้น ในวันเดียวกันนั้นเอง น้ําพุทั้งหลายที่อยู่ที่ลึกใต้บาดาลก็พลุ่งขึ้นมา และช่องฟ้าก็เปิดออก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 12, 'ฝนตกบนแผ่นดินโลกสี่สิบวันสี่สิบคืน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 13, 'ในวันเดียวกันนั้นเองโนอาห์และบุตรชายของโนอาห์ คือเชม ฮาม และยาเฟท ภรรยาของโนอาห์ และบุตรสะใภ้ทั้งสามได้เข้าไปในนาวา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 14, 'เขาเหล่านั้นและสัตว์ป่าทั้งปวงตามชนิดของมัน และสัตว์ใช้งานทั้งปวงตามชนิดของมัน และบรรดาสัตว์เลื้อยคลานที่คลานไปมาบนแผ่นดินโลกตามชนิดของมัน และนกทั้งปวงตามชนิดของมัน คือบรรดานกทุกชนิดที่มีลักษณะแตกต่างกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 15, 'สัตว์ทั้งปวงที่มีลมปราณแห่งชีวิตได้เข้าไปหาโนอาห์ในนาวาเป็นคู่ๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 16, 'สัตว์ทั้งปวงที่เข้าไปนั้นได้เข้าไปทั้งตัวผู้และตัวเมียตามที่พระเจ้าได้ทรงบัญชาแก่ท่าน และพระเยโฮวาห์ทรงปิดประตูให้ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 17, 'น้ําได้ท่วมแผ่นดินโลกสี่สิบวัน และน้ําก็ทวีมากขึ้นและหนุนนาวาให้สูงเหนือแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 18, 'น้ําไหลเชี่ยวและทวีมากยิ่งขึ้นบนแผ่นดินโลก และนาวาลอยบนผิวน้ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 19, 'น้ําไหลเชี่ยวทวีมากยิ่งขึ้นบนแผ่นดินโลก และน้ําก็ท่วมภูเขาสูงทุกแห่งทั่วใต้ฟ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 20, 'น้ําไหลเชี่ยวท่วมเหนือภูเขาสิบห้าศอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 21, 'บรรดาเนื้อหนังที่เคลื่อนไหวบนแผ่นดินโลก ทั้งนก สัตว์ใช้งาน สัตว์ป่า และสัตว์เลื้อยคลานที่คลานไปมาบนแผ่นดินโลก และมนุษย์ทั้งปวงก็ตายสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 22, 'มนุษย์ทั้งปวงผู้ซึ่งมีลมปราณแห่งชีวิตเข้าออกทางจมูก สิ่งสารพัดที่อยู่บนบกตายสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 23, 'สิ่งที่มีชีวิตทั้งปวงที่อยู่บนพื้นแผ่นดินโลกถูกทําลาย ทั้งมนุษย์ สัตว์ใช้งาน สัตว์เลื้อยคลาน และนกในอากาศ และทุกสิ่งถูกทําลายจากแผ่นดินโลก เหลืออยู่แต่โนอาห์และทุกสิ่งที่อยู่กับท่านในนาวา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 24, 'น้ําไหลเชี่ยวบนแผ่นดินโลกเป็นเวลาหนึ่งร้อยห้าสิบวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 1, 'พระเจ้าทรงระลึกถึงโนอาห์ บรรดาสัตว์ที่มีชีวิตและสัตว์ใช้งานทั้งปวงที่อยู่กับท่านในนาวา และพระเจ้าทรงทําให้ลมพัดมาเหนือแผ่นดินโลก และน้ําทั้งปวงก็ลดลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 2, 'น้ําพุทั้งหลายที่อยู่ใต้บาดาลและช่องฟ้าทั้งปวงก็ปิด และฝนที่ตกจากฟ้าก็หยุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 3, 'น้ําก็ค่อยๆลดลงจากแผ่นดินโลก และล่วงไปร้อยห้าสิบวันแล้วน้ําก็ลดลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 4, 'ณ เดือนที่เจ็ดวันที่สิบเจ็ดนาวาก็ค้างอยู่บนเทือกเขาอารารัต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 5, 'น้ําก็ค่อยๆลดลงจนถึงเดือนที่สิบ ในเดือนที่สิบ ณ วันที่หนึ่งของเดือนนั้น ยอดภูเขาต่างๆโผล่ขึ้นมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 6, 'ต่อจากนั้นอีกสี่สิบวัน โนอาห์ก็เปิดช่องในนาวาที่ท่านได้ทําไว้นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 7, 'ท่านปล่อยนกกาตัวหนึ่ง ซึ่งมันบินไปมาจนกระทั่งน้ําลดแห้งจากแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 8, 'ท่านจึงปล่อยนกเขาตัวหนึ่งด้วยเพื่อจะรู้ว่าน้ําได้ลดลงจากพื้นแผ่นดินโลกหรือยัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 9, 'แต่นกเขาไม่พบที่ที่จะจับอาศัยอยู่ได้เพราะน้ํายังท่วมทั่วพื้นแผ่นดินโลกอยู่ มันจึงได้กลับมาหาท่านในนาวา ดังนั้นท่านจึงยื่นมือออกไปจับนกเขาเข้ามาไว้ด้วยกันในนาวา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 10, 'ท่านคอยอยู่อีกเจ็ดวัน ท่านจึงปล่อยนกเขาไปจากนาวาอีกครั้งหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 11, 'ในเวลาเย็นนกเขาก็กลับมายังท่าน ดูเถิด มันคาบใบมะกอกเทศเขียวสดมา ดังนั้นโนอาห์จึงรู้ว่า น้ําได้ลดลงจากแผ่นดินโลกแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 12, 'ท่านคอยอยู่อีกเจ็ดวัน และปล่อยนกเขาออกไป แล้วมันไม่กลับมาหาท่านอีกเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 13, 'ต่อมาปีที่หกร้อยเอ็ดเดือนที่หนึ่งวันที่หนึ่งของเดือนนั้นน้ําก็แห้งจากแผ่นดินโลก โนอาห์ก็เปิดหลังคาของนาวาและมองดู ดูเถิด พื้นแผ่นดินแห้งแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 14, 'ในเดือนที่สองวันที่ยี่สิบเจ็ดของเดือนนั้นแผ่นดินโลกก็แห้งสนิท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 15, 'พระเจ้าตรัสแก่โนอาห์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 16, '“จงออกไปจากนาวา ทั้งเจ้า ภรรยา บุตรชาย และบุตรสะใภ้ทั้งหลายของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 17, 'จงพาสัตว์ที่มีชีวิตทั้งปวงที่อยู่ด้วยกันกับเจ้า คือบรรดาเนื้อหนัง ทั้งนก สัตว์ใช้งาน และสัตว์เลื้อยคลานทั้งปวงที่คลานไปมาบนแผ่นดินโลกให้ออกมา เพื่อพวกมันจะทวีมากขึ้นบนแผ่นดินโลก และมีลูกดกทวีมากขึ้นบนแผ่นดินโลก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 18, 'โนอาห์จึงออกไป พร้อมทั้งบุตรชาย ภรรยา และบุตรสะใภ้ทั้งหลายที่อยู่กับท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 19, 'สัตว์ป่าทั้งปวง บรรดาสัตว์เลื้อยคลาน นกทั้งปวง และทุกสิ่งที่คลานไปมาบนแผ่นดินโลกตามชนิดของพวกมันออกไปจากนาวา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 20, 'โนอาห์ก็สร้างแท่นบูชาแด่พระเยโฮวาห์ และเอาบรรดาสัตว์ที่สะอาดและบรรดานกที่สะอาดถวายเป็นเครื่องเผาบูชาที่แท่นนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 21, 'พระเยโฮวาห์ได้ดมกลิ่นหอมหวาน และพระเยโฮวาห์ทรงดําริในพระทัยว่า “เราจะไม่สาปแช่งแผ่นดินอีกเพราะเหตุมนุษย์ ด้วยว่าเจตนาในใจของเขาล้วนแต่ชั่วร้ายตั้งแต่เด็กมา เราจะไม่ประหารสิ่งทั้งปวงที่มีชีวิตอีกเหมือนอย่างที่เราได้กระทําแล้วนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 22, 'ในขณะที่โลกยังดํารงอยู่นั้น จะมีฤดูหว่านฤดูเก็บเกี่ยว เวลาเย็นเวลาร้อน ฤดูร้อนฤดูหนาว กลางวันกลางคืนต่อไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 1, 'พระเจ้าทรงอวยพระพรแก่โนอาห์และบุตรชายทั้งหลายของท่าน และตรัสแก่พวกเขาว่า “จงมีลูกดก และทวีมากขึ้นจนเต็มแผ่นดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 2, 'สัตว์ป่าทั้งปวงบนแผ่นดินโลก บรรดานกในอากาศ สิ่งทั้งปวงที่คลานไปมาบนแผ่นดินโลก และบรรดาปลาในทะเล จะเกรงกลัวพวกเจ้าและหวาดกลัวต่อพวกเจ้า พวกมันจะถูกมอบอยู่ในมือพวกเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 3, 'สิ่งทั้งปวงที่มีชีวิตเคลื่อนไหวไปมาจะเป็นอาหารของพวกเจ้า เช่นเดียวกับพืชผักเขียวสด เรายกทุกสิ่งให้แก่พวกเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 4, 'แต่เนื้อกับชีวิตของมัน คือเลือดของมัน พวกเจ้าอย่ากินเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 5, 'โลหิตเจ้าที่เป็นชีวิตของเจ้าเราจะเรียกเอาแน่นอน เราจะเรียกเอาจากชีวิตของสัตว์ป่าทั้งปวงและจากมือมนุษย์ เราจะเรียกเอาชีวิตมนุษย์จากมือพี่น้องของตนทุกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 6, 'ผู้ใดทําให้โลหิตของมนุษย์ไหล ผู้อื่นจะทําให้ผู้นั้นโลหิตไหล เพราะว่าพระเจ้าทรงสร้างมนุษย์ตามแบบพระฉายาของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 7, 'เจ้าจงมีลูกดกทวีมากขึ้นอุดมบริบูรณ์ในแผ่นดินโลกและทวีมากขึ้นในนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 8, 'พระเจ้าจึงตรัสแก่โนอาห์และบุตรชายทั้งหลายที่อยู่กับท่านว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 9, '“ดูเถิด เราตั้งพันธสัญญาของเรากับพวกเจ้าและกับเชื้อสายของเจ้าสืบไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 10, 'และกับสัตว์ที่มีชีวิตทั้งปวงที่อยู่กับเจ้า ทั้งนก สัตว์ใช้งาน และบรรดาสัตว์ป่าบนแผ่นดินโลกที่อยู่กับเจ้า สัตว์ทั้งปวงที่ออกจากนาวา รวมทั้งบรรดาสัตว์ป่าบนแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 11, 'เราจะตั้งพันธสัญญาของเราไว้กับพวกเจ้าว่า จะไม่มีการทําลายบรรดาเนื้อหนังโดยน้ําท่วมอีก จะไม่มีน้ํามาท่วมทําลายโลกอีกต่อไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 12, 'พระเจ้าตรัสว่า “นี่เป็นหมายสําคัญแห่งพันธสัญญาซึ่งเราตั้งไว้ระหว่างเรากับพวกเจ้า และสัตว์ที่มีชีวิตทั้งปวงที่อยู่กับเจ้า ในทุกชั่วอายุตลอดไปเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 13, 'เราได้ตั้งรุ้งของเราไว้ที่เมฆและมันจะเป็นหมายสําคัญแห่งพันธสัญญาระหว่างเรากับแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 14, 'และต่อมาเมื่อเราให้มีเมฆเหนือแผ่นดินโลก จะเห็นรุ้งที่เมฆนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 15, 'และเราจะระลึกถึงพันธสัญญาของเราซึ่งมีระหว่างเรากับพวกเจ้าและสิ่งที่มีชีวิตทั้งปวงแห่งบรรดาเนื้อหนัง และน้ําจะไม่มาท่วมทําลายบรรดาเนื้อหนังอีกต่อไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 16, 'จะมีรุ้งที่เมฆและเราจะมองดูมันเพื่อเราจะระลึกถึงพันธสัญญานิรันดร์ ระหว่างพระเจ้ากับสิ่งทั้งปวงที่มีชีวิตแห่งบรรดาเนื้อหนังที่อยู่บนแผ่นดินโลก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 17, 'และพระเจ้าตรัสแก่โนอาห์ว่า “นี่เป็นหมายสําคัญแห่งพันธสัญญาซึ่งเราได้ตั้งไว้ระหว่างเรากับบรรดาเนื้อหนังบนแผ่นดินโลก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 18, 'บุตรชายของโนอาห์ที่ได้ออกจากนาวา คือเชม ฮาม และยาเฟท และฮามเป็นบิดาของคานาอัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 19, 'นี่เป็นบุตรชายสามคนของโนอาห์ และมนุษย์ที่กระจัดกระจายออกไปทั่วโลกมาจากคนเหล่านี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 20, 'โนอาห์เริ่มเป็นชาวสวนและเขาทําสวนองุ่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 21, 'ท่านได้ดื่มเหล้าองุ่นจนเมา และท่านก็เปลือยกายอยู่ในเต็นท์ของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 22, 'ฮาม บิดาของคานาอัน เห็นบิดาของตนเปลือยกายอยู่ จึงบอกพี่น้องทั้งสองคนของเขาที่อยู่ภายนอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 23, 'เชมกับยาเฟทเอาผ้าผืนหนึ่งพาดบ่าของเขาทั้งสองคนเดินหันหลังเข้าไปปกปิดกายบิดาของพวกเขาที่เปลือยอยู่ และมิได้หันหน้าดูกายบิดาของพวกเขาที่เปลือยอยู่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 24, 'โนอาห์สร่างเมาแล้วจึงรู้ว่าบุตรชายสุดท้องของเขาได้ทําอะไรแก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 25, 'ท่านพูดว่า “คานาอันจงถูกสาปแช่ง และเขาจะเป็นทาสแห่งทาสทั้งหลายของพี่น้องของเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 26, 'ท่านพูดว่า “สรรเสริญพระเยโฮวาห์พระเจ้าของเชม และคานาอันจะเป็นทาสของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 27, 'พระเจ้าจะทรงเพิ่มพูนยาเฟทและเขาจะอาศัยอยู่ในเต็นท์ของเชม และคานาอันจะเป็นทาสของเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 28, 'หลังจากน้ําท่วมโนอาห์มีชีวิตต่อไปอีกสามร้อยห้าสิบปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 29, 'รวมอายุของโนอาห์ได้เก้าร้อยห้าสิบปีและท่านได้สิ้นชีวิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 1, 'ต่อไปนี้เป็นพงศ์พันธุ์ของบุตรชายทั้งหลายของโนอาห์ คือเชม ฮาม และยาเฟท และพวกเขากําเนิดบุตรชายหลายคนหลังน้ําท่วม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 2, 'บุตรชายทั้งหลายของยาเฟทชื่อโกเมอร์ มาโกก มีเดีย ยาวาน ทูบัล เมเชค และทิราส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 3, 'บุตรชายทั้งหลายของโกเมอร์ชื่ออัชเคนัส รีฟาท และโทการมาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 4, 'บุตรชายทั้งหลายของยาวานชื่อเอลีชาห์ ทารชิช คิทธิม และโดดานิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 5, 'จากเชื้อสายเหล่านี้ อาณาเขตของชนชาติทั้งหลายได้แบ่งแยกตามดินแดนต่างๆของพวกเขา แต่ละคนตามภาษาของเขา ตามครอบครัวของพวกเขา ตามชาติของพวกเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 6, 'บุตรชายทั้งหลายของฮามชื่อคูช มิสรายิม พูต และคานาอัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 7, 'บุตรชายทั้งหลายของคูชชื่อเส-บา ฮาวิลาห์ สับทาห์ ราอามาห์ และสับเทคา และบุตรชายทั้งหลายของราอามาห์ชื่อเชบา และเดดาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 8, 'คูชให้กําเนิดบุตรชื่อนิมโรด เขาเริ่มเป็นคนมีอํานาจมากบนแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 9, 'เขาเป็นพรานที่มีกําลังมากต่อพระพักตร์พระเยโฮวาห์ ดังนั้นจึงว่า “เหมือนกับนิมโรดพรานที่มีกําลังมากต่อพระพักตร์พระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 10, 'การเริ่มต้นอาณาจักรของเขาคือเมืองบาเบล เมืองเอเรก เมืองอัคคัด และเมืองคาลเนห์ในแผ่นดินของชินาร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 11, 'ฝ่ายอัสชูรจึงออกไปจากแผ่นดินของชินาร์นั้น และสร้างเมืองนีนะเวห์ เมืองเรโหโบทและเมืองคาลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 12, 'และเมืองเรเสนซึ่งอยู่ระหว่างเมืองนีนะเวห์กับเมืองคาลาห์ เมืองนี้เป็นเมืองใหญ่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 13, 'มิสรายิมให้กําเนิดบุตรชื่อลูดิม อานามิม เลหะบิม นัฟทูฮิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 14, 'ปัทรุสิม คัสลูฮิม (ผู้ซึ่งออกมาจากเขาคือคนฟีลิสติม) และคัฟโทริม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 15, 'คานาอันให้กําเนิดบุตรหัวปีชื่อไซดอนและเฮท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 16, 'และคนเยบุส คนอาโมไรต์ คนเกอร์กาชี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 17, 'คนฮีไวต์ คนอารกี คนสินี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 18, 'คนอารวัด คนเศเมอร์ และคนฮามัท และภายหลังนั้นครอบครัวต่างๆของคนคานาอันก็กระจัดกระจายออกไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 19, 'เขตแดนของคนคานาอันจากเมืองไซดอน ไปทางเมืองเก-ราร์ จนถึงเมืองกาซา ไปทางเมืองโสโดม เมืองโกโมราห์ เมืองอัดมาห์ และเมืองเศโบยิมจนถึงเมืองลาชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 20, 'นี่เป็นบุตรชายทั้งหลายของฮาม ตามครอบครัวของพวกเขา ตามภาษาของพวกเขา ตามแผ่นดินของพวกเขาและตามชาติของพวกเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 21, 'เช่นเดียวกัน เชมซึ่งเป็นบรรพบุรุษของบรรดาชนเอเบอร์ เขาเป็นน้องชายของยาเฟทพี่คนโต เขาก็ให้กําเนิดบุตรหลายคนด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 22, 'บุตรของเชมชื่อเอลาม อัสชูร อารฟัคชาด ลูด และอารัม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 23, 'บุตรอารัมชื่ออูส ฮุล เกเธอร์ และมัช');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 24, 'อารฟัคชาดให้กําเนิดบุตรชื่อเชลาห์ และเชลาห์ให้กําเนิดบุตรชื่อเอเบอร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 25, 'เอเบอร์ให้กําเนิดบุตรชายสองคน คนหนึ่งชื่อเปเลก เพราะในสมัยของเขาแผ่นดินถูกแบ่งแยก และน้องชายของเขาชื่อโยกทาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 26, 'โยกทานให้กําเนิดบุตรชื่ออัลโมดัด เชเลฟ ฮาซาร-มาเวท และเยราห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 27, 'ฮาโดรัม อุซาล ดิคลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 28, 'โอบาล อาบีมาเอล เชบา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 29, 'โอฟีร์ ฮาวิลาห์ และโยบับ คนเหล่านี้เป็นบุตรชายทั้งหลายของโยกทาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 30, 'ที่อยู่อาศัยของพวกเขาเริ่มจากเมืองเมชาไปทางเสฟาร์เทือกเขาทางทิศตะวันออก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 31, 'นี่เป็นบุตรชายทั้งหลายของเชม ตามครอบครัวของพวกเขา ตามภาษาของพวกเขา ตามแผ่นดินของพวกเขาและตามชาติของพวกเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 32, 'นี่เป็นครอบครัวต่างๆของบุตรชายทั้งหลายของโนอาห์ ตามพงศ์พันธุ์ของพวกเขา ตามชาติของพวกเขา และจากคนเหล่านี้ประชาชาติทั้งหลายถูกแบ่งแยกในแผ่นดินโลกภายหลังน้ําท่วม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 1, 'ทั่วแผ่นดินโลกมีภาษาเดียวและมีสําเนียงเดียวกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 2, 'และต่อมาเมื่อพวกเขาเดินทางจากทิศตะวันออกก็พบที่ราบในแผ่นดินชินาร์และพวกเขาอาศัยอยู่ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 3, 'แล้วพวกเขาต่างคนต่างก็พูดกันว่า “มาเถิด ให้พวกเราทําอิฐและเผามันให้แข็ง” พวกเขาจึงมีอิฐใช้ต่างหินและมียางมะตอยใช้ต่างปูนสอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 4, 'เขาทั้งหลายพูดว่า “มาเถิด ให้พวกเราสร้างเมืองขึ้นเมืองหนึ่งและก่อหอให้ยอดของมันไปถึงฟ้าสวรรค์ และให้พวกเราสร้างชื่อเสียงของพวกเราไว้ เพื่อว่าพวกเราจะไม่กระจัดกระจายไปทั่วพื้นแผ่นดินโลก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 5, 'และพระเยโฮวาห์เสด็จลงมาทอดพระเนตรเมืองและหอนั้นซึ่งบุตรทั้งหลายของมนุษย์ได้ก่อสร้างขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 6, 'แล้วพระเยโฮวาห์ตรัสว่า “ดูเถิด คนเหล่านี้เป็นอันหนึ่งอันเดียวกัน และพวกเขาทั้งปวงมีภาษาเดียว พวกเขาเริ่มทําเช่นนี้แล้ว ประเดี๋ยวจะไม่มีอะไรหยุดยั้งพวกเขาได้ในสิ่งที่พวกเขาคิดจะทํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 7, 'มาเถิด ให้พวกเราลงไปและทําให้ภาษาของเขาวุ่นวายที่นั่น เพื่อไม่ให้พวกเขาพูดเข้าใจกันได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 8, 'ดังนั้นพระเยโฮวาห์จึงทรงทําให้เขากระจัดกระจายจากที่นั่นไปทั่วพื้นแผ่นดิน พวกเขาก็เลิกสร้างเมืองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 9, 'เหตุฉะนั้นจึงเรียกชื่อเมืองนั้นว่า บาเบล เพราะว่าที่นั่นพระเยโฮวาห์ทรงทําให้ภาษาของทั่วโลกวุ่นวาย และ ณ จากที่นั่นพระเยโฮวาห์ได้ทรงทําให้พวกเขากระจัดกระจายออกไปทั่วพื้นแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 10, 'ต่อไปนี้เป็นพงศ์พันธุ์ของเชม เชมมีอายุได้ร้อยปีและให้กําเนิดบุตรชื่ออารฟัคชาด หลังน้ําท่วมสองปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 11, 'หลังจากเชมให้กําเนิดอารฟัคชาดแล้วก็มีอายุต่อไปอีกห้าร้อยปี และให้กําเนิดบุตรชายและบุตรสาวหลายคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 12, 'อารฟัคชาดมีอายุได้สามสิบห้าปีและให้กําเนิดบุตรชื่อเชลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 13, 'หลังจากอารฟัคชาดให้กําเนิดเชลาห์แล้วก็มีอายุต่อไปอีกสี่ร้อยสามปี และให้กําเนิดบุตรชายและบุตรสาวหลายคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 14, 'เชลาห์มีอายุได้สามสิบปีและให้กําเนิดบุตรชื่อเอเบอร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 15, 'หลังจากเชลาห์ให้กําเนิดเอเบอร์แล้วก็มีอายุต่อไปอีกสี่ร้อยสามปี และให้กําเนิดบุตรชายและบุตรสาวหลายคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 16, 'เอเบอร์มีอายุได้สามสิบสี่ปีและให้กําเนิดบุตรชื่อเปเลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 17, 'หลังจากเอเบอร์ให้กําเนิดเปเลกแล้วก็มีอายุต่อไปอีกสี่ร้อยสามสิบปี และให้กําเนิดบุตรชายและบุตรสาวหลายคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 18, 'เปเลกมีอายุได้สามสิบปีและให้กําเนิดบุตรชื่อเรอู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 19, 'หลังจากเปเลกให้กําเนิดเรอูแล้วก็มีอายุต่อไปอีกสองร้อยเก้าปี และให้กําเนิดบุตรชายและบุตรสาวหลายคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 20, 'เรอูมีอายุได้สามสิบสองปีและให้กําเนิดบุตรชื่อเสรุก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 21, 'หลังจากเรอูให้กําเนิดเสรุกแล้วก็มีอายุต่อไปอีกสองร้อยเจ็ดปี และให้กําเนิดบุตรชายและบุตรสาวหลายคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 22, 'เสรุกมีอายุได้สามสิบปีและให้กําเนิดบุตรชื่อนาโฮร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 23, 'หลังจากเสรุกให้กําเนิดนาโฮร์แล้วก็มีอายุต่อไปอีกสองร้อยปี และให้กําเนิดบุตรชายและบุตรสาวหลายคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 24, 'นาโฮร์มีอายุได้ยี่สิบเก้าปีและให้กําเนิดบุตรชื่อเทราห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 25, 'หลังจากนาโฮร์ให้กําเนิดเทราห์แล้วก็มีอายุต่อไปอีกร้อยสิบเก้าปี และให้กําเนิดบุตรชายและบุตรสาวหลายคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 26, 'เทราห์มีอายุได้เจ็ดสิบปีและให้กําเนิดบุตรชื่ออับราม นาโฮร์ และฮาราน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 27, 'ต่อไปนี้เป็นพงศ์พันธุ์ของเทราห์ เทราห์ให้กําเนิดอับราม นาโฮร์ และฮาราน และฮารานให้กําเนิดบุตรชื่อโลท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 28, 'ฮารานได้สิ้นชีวิตก่อนเทราห์ผู้เป็นบิดาของเขาในแผ่นดินที่เขาบังเกิด ในเมืองเออร์ของชาวเคลเดีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 29, 'อับรามและนาโฮร์ต่างก็ได้ภรรยา ภรรยาของอับรามมีชื่อว่าซาราย และภรรยาของนาโฮร์มีชื่อว่ามิลคาห์ผู้เป็นบุตรีของฮาราน ผู้เป็นบิดาของมิลคาห์และบิดาของอิสคาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 30, 'แต่นางซารายได้เป็นหมัน นางหามีบุตรไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 31, 'เทราห์ก็พาอับรามบุตรชายของเขากับโลทบุตรชายของฮารานผู้เป็นหลานชายของเขาและนางซาราย บุตรสะใภ้ของเขาผู้เป็นภรรยาของอับรามบุตรชายของเขา เขาทั้งหลายออกจากเมืองเออร์ของชาวเคลเดีย จะเข้าไปยังแผ่นดินคานาอัน พวกเขามาถึงเมืองฮารานแล้วก็อาศัยอยู่ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 32, 'รวมอายุเทราห์ได้สองร้อยห้าปี และเทราห์ก็ได้สิ้นชีวิตในเมืองฮาราน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 1, 'พระเยโฮวาห์ได้ตรัสแก่อับรามแล้วว่า “เจ้าจงออกไปจากประเทศของเจ้า จากญาติพี่น้องของเจ้า และจากบ้านบิดาของเจ้า ไปยังแผ่นดินที่เราจะชี้ให้เจ้าเห็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 2, 'เราจะทําให้เจ้าเป็นชนชาติใหญ่ชนชาติหนึ่ง เราจะอวยพรเจ้า ทําให้เจ้ามีชื่อเสียงใหญ่โต และเจ้าจะเป็นแหล่งพระพร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 3, 'เราจะอวยพรผู้ที่อวยพรเจ้า และสาปแช่งผู้ที่สาปแช่งเจ้า บรรดาครอบครัวทั่วแผ่นดินโลกจะได้รับพระพรเพราะเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 4, 'ดังนั้นอับรามจึงออกไปตามที่พระเยโฮวาห์ได้ตรัสแก่ท่านและโลทก็ไปกับท่าน อับรามมีอายุได้เจ็ดสิบห้าปีขณะเมื่อท่านออกจากเมืองฮาราน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 5, 'อับรามพานางซารายภรรยาของท่าน โลทบุตรของน้องชายท่าน บรรดาทรัพย์สิ่งของของพวกเขาที่ได้สะสมไว้ และผู้คนทั้งหลายที่ได้ไว้ที่เมืองฮาราน พวกเขาออกไปเพื่อเข้าไปยังแผ่นดินคานาอัน และพวกเขาไปถึงแผ่นดินคานาอัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 6, 'อับรามเดินผ่านแผ่นดินนั้นจนถึงสถานที่เมืองเชเคม คือที่ราบโมเรห์ คราวนั้นชาวคานาอันยังอยู่ในแผ่นดินนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 7, 'พระเยโฮวาห์ทรงปรากฏแก่อับรามและตรัสว่า “เราจะให้แผ่นดินนี้แก่เชื้อสายของเจ้า” อับรามจึงสร้างแท่นบูชาที่นั่นถวายแด่พระเยโฮวาห์ ผู้ทรงปรากฏแก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 8, 'ท่านย้ายไปจากที่นั่นมาถึงภูเขาลูกหนึ่งทางทิศตะวันออกของเมืองเบธเอลแล้วตั้งเต็นท์ของท่าน โดยเมืองเบธเอลอยู่ทางทิศตะวันตกและเมืองอัยอยู่ทางทิศตะวันออก ณ ที่นั่นท่านสร้างแท่นบูชาแด่พระเยโฮวาห์ และร้องออกพระนามของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 9, 'และอับรามก็ยังคงเดินทางเรื่อยไป ไปทางทิศใต้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 10, 'เกิดการกันดารอาหารที่แผ่นดิน อับรามได้ลงไปยังอียิปต์เพื่ออาศัยอยู่ที่นั่น เพราะว่าการกันดารอาหารในแผ่นดินนั้นมากยิ่งนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 11, 'ต่อมาเมื่อท่านใกล้จะเข้าอียิปต์ ท่านจึงพูดกับนางซารายภรรยาของท่านว่า “ดูเถิด บัดนี้ข้าพเจ้ารู้ว่าเจ้าเป็นหญิงรูปงามน่าดู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 12, 'เพราะฉะนั้นต่อมาเมื่อคนอียิปต์จะเห็นเจ้า พวกเขาจะพูดว่า ‘นี่เป็นภรรยาของเขา’ และพวกเขาจะฆ่าข้าพเจ้าเสีย แต่พวกเขาจะไว้ชีวิตเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 13, 'กรุณาพูดว่าเจ้าเป็นน้องสาวของข้าพเจ้า เพื่อข้าพเจ้าจะอยู่อย่างสุขสบายเพราะเห็นแก่เจ้า และข้าพเจ้าจะมีชีวิตเพราะเหตุเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 14, 'ต่อมาเมื่ออับรามเข้าไปในอียิปต์แล้ว คนอียิปต์เห็นว่าหญิงคนนี้รูปงามยิ่งนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 15, 'พวกเจ้านายของฟาโรห์เห็นนางด้วยเช่นกัน และทูลยกย่องนางต่อพระพักตร์ฟาโรห์ และหญิงนั้นจึงถูกนําเข้าไปอยู่ในวังของฟาโรห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 16, 'ฟาโรห์ได้โปรดปรานอับรามมากเพราะเห็นแก่นาง ท่านได้แกะ วัว ลาตัวผู้ ทาส ทาสี ลาตัวเมีย และอูฐจํานวนมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 17, 'และพระเยโฮวาห์ทรงทําให้เกิดภัยพิบัติแก่ฟาโรห์และราชวงศ์ของท่านด้วยภัยพิบัติร้ายแรงต่างๆ เพราะเหตุนางซารายภรรยาของอับราม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 18, 'ฟาโรห์จึงเรียกอับรามมาและตรัสว่า “ทําไมเจ้าจึงทําเช่นนี้แก่เรา ทําไมเจ้าไม่บอกเราว่านางเป็นภรรยาของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 19, 'ทําไมเจ้าว่า ‘เธอเป็นน้องสาวของข้าพระองค์’ ดังนั้นเราเกือบจะรับนางมาเป็นภรรยาของเรา ฉะนั้นบัดนี้จงดูภรรยาของเจ้า จงรับนางไปและออกไปตามทางของเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 20, 'ฟาโรห์จึงรับสั่งพวกคนใช้เรื่องท่าน และพวกเขาจึงนําท่าน ภรรยาและสิ่งสารพัดที่ท่านมีอยู่ออกไปเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 1, 'อับรามจึงขึ้นไปจากอียิปต์ ท่านและภรรยาของท่านและสิ่งสารพัดที่ท่านมีอยู่พร้อมกับโลท เข้าไปทางทิศใต้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 2, 'อับรามก็มั่งคั่งสมบูรณ์ด้วยฝูงสัตว์ เงินและทองเป็นอันมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 3, 'ท่านเดินทางต่อไปจากทิศใต้จนถึงเมืองเบธเอล ถึงสถานที่ที่เต็นท์ของท่านเคยตั้งอยู่คราวก่อน ระหว่างเมืองเบธเอลกับเมืองอัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 4, 'จนถึงสถานที่ตั้งแท่นบูชาซึ่งเมื่อก่อนท่านเคยสร้างไว้ที่นั่น และอับรามร้องออกพระนามของพระเยโฮวาห์ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 5, 'โลทซึ่งไปกับอับรามมีฝูงแพะแกะ ฝูงวัวและเต็นท์เช่นกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 6, 'แผ่นดินไม่กว้างขวางพอที่พวกเขาจะอาศัยอยู่ด้วยกันได้ เพราะทรัพย์สิ่งของของพวกเขามีอยู่มาก ดังนั้นพวกเขาจึงไม่สามารถอยู่ด้วยกันได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 7, 'เกิดมีการวิวาทกันระหว่างคนเลี้ยงสัตว์ของอับรามกับคนเลี้ยงสัตว์ของโลท ขณะนั้นคนคานาอันและคนเปริสซียังอาศัยอยู่ที่แผ่นดินนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 8, 'อับรามจึงพูดกับโลทว่า “กรุณาอย่าให้มีการวิวาทกันเลยระหว่างเรากับเจ้า และระหว่างคนเลี้ยงสัตว์ของเรากับคนเลี้ยงสัตว์ของเจ้า เพราะเราทั้งสองเป็นญาติกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 9, 'แผ่นดินทั้งหมดอยู่ตรงหน้าเจ้ามิใช่หรือ โปรดจงแยกไปจากเราเถิด ถ้าเจ้าไปทางซ้ายมือเราจะไปทางขวามือ หรือถ้าเจ้าไปทางขวามือเราจะไปทางซ้ายมือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 10, 'โลทเงยหน้าขึ้นแลดูและเห็นว่าบรรดาที่ราบลุ่มของแม่น้ําจอร์แดนมีน้ําบริบูรณ์อยู่ทุกแห่ง เหมือนพระอุทยานของพระเยโฮวาห์ เหมือนกับแผ่นดินอียิปต์ไปทางเมืองโศอาร์ ก่อนที่พระเยโฮวาห์ทรงทําลายเมืองโสโดมและเมืองโกโมราห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 11, 'ดังนั้นโลทจึงเลือกบรรดาที่ราบลุ่มของแม่น้ําจอร์แดน โลทเดินทางไปทิศตะวันออกและเขาทั้งสองจึงแยกจากกันไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 12, 'อับรามอาศัยอยู่ในแผ่นดินคานาอัน โลทอาศัยอยู่ในเมืองต่างๆที่ราบลุ่มและตั้งเต็นท์ใกล้เมืองโสโดม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 13, 'แต่ชาวเมืองโสโดมเป็นคนชั่วช้าและเป็นคนบาปต่อพระพักตร์พระเยโฮวาห์เป็นอันมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 14, 'ภายหลังที่โลทแยกจากท่านไปแล้วพระเยโฮวาห์ตรัสแก่อับรามว่า “จงเงยหน้าขึ้นแลดูและมองดูจากสถานที่ที่เจ้าอยู่นี้ไปทางทิศเหนือ ทิศใต้ ทิศตะวันออกและทิศตะวันตก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 15, 'เพราะว่าแผ่นดินทั้งหมดซึ่งเจ้าเห็นนี้เราจะยกให้เจ้าและเชื้อสายของเจ้าตลอดไปเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 16, 'เราจะกระทําให้เชื้อสายของเจ้าเหมือนอย่างผงคลีดิน ดังนั้นถ้าผู้ใดสามารถนับผงคลีดินได้ก็จะนับเชื้อสายของเจ้าได้เช่นกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 17, 'จงลุกขึ้นเดินไปทั่วแผ่นดินทางด้านยาวด้านกว้าง เพราะเราจะยกให้เจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 18, 'ดังนั้นอับรามจึงยกเต็นท์มาและอาศัยอยู่ที่ราบของมัมเร ซึ่งอยู่ในเฮโบรนและสร้างแท่นบูชาต่อพระเยโฮวาห์ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 1, 'และต่อมาในสมัยของอัมราเฟลกษัตริย์เมืองชินาร์ อารีโอคกษัตริย์เมืองเอลลาสาร์ เคโดร์ลาโอเมอร์กษัตริย์เมืองเอลาม และทิดาลกษัตริย์แห่งประชาชาติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 2, 'กษัตริย์เหล่านี้ได้ทําสงครามสู้รบกับเบรากษัตริย์เมืองโสโดม บิรชากษัตริย์เมืองโกโมราห์ ชินาบกษัตริย์เมืองอัดมาห์ เชเมเบอร์กษัตริย์เมืองเศโบยิม และกษัตริย์เมืองเบลาคือเมืองโศอาร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 3, 'บรรดากษัตริย์เหล่านี้รวมทัพกัน ณ ที่หุบเขาสิดดิมซึ่งคือทะเลเกลือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 4, 'กษัตริย์เหล่านี้ยอมขึ้นแก่กษัตริย์เคโดร์ลาโอเมอร์สิบสองปี และในปีที่สิบสามกษัตริย์เหล่านี้ก็กบฏ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 5, 'และในปีที่สิบสี่กษัตริย์เคโดร์ลาโอเมอร์และบรรดากษัตริย์ที่อยู่กับท่านยกมาตีคนเรฟาอิมที่เมืองอัชทาโรท คารนาอิม คนศูซิมที่เมืองฮาม และคนเอมิมที่เมืองชาเวห์ คีริยาธาอิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 6, 'ชาวโฮรีที่ภูเขาเสอีร์ซึ่งเป็นของพวกเขา จนถึงเมืองเอลปารานซึ่งอยู่ใกล้ถิ่นทุรกันดาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 7, 'กษัตริย์เหล่านี้กลับมาถึงเมืองเอนมิสปัทซึ่งคือเมืองคาเดช และยกมาตีแผ่นดินทั้งสิ้นของคนอามาเลข และคนอาโมไรต์ที่อาศัยอยู่ ณ เมืองฮาซาโซนทามาร์ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 8, 'และกษัตริย์เมืองโสโดม กษัตริย์เมืองโกโมราห์ กษัตริย์เมืองอัดมาห์ กษัตริย์เมืองเศโบยิม และกษัตริย์เมืองเบลา (คือเมืองโศอาร์) ก็ออกไปทําสงครามสู้รบกับกษัตริย์เหล่านั้น ณ ที่หุบเขาสิดดิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 9, 'กับเคโดร์ลาโอเมอร์กษัตริย์เมืองเอลาม ทิดาลกษัตริย์แห่งประชาชาติ อัมราเฟลกษัตริย์เมืองชินาร์ และอารีโอคกษัตริย์เมืองเอลลาสาร์ กษัตริย์สี่องค์ต่อห้าองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 10, 'ที่หุบเขาสิดดิมมีบ่อยางมะตอยเต็มไปหมด เหล่ากษัตริย์เมืองโสโดมและเมืองโกโมราห์ได้หนีมาและตกลงไปที่นั่น และส่วนผู้ที่เหลืออยู่ก็หนีไปยังภูเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 11, 'กษัตริย์เหล่านั้นจึงเก็บบรรดาทรัพย์สิ่งของและเสบียงอาหารทั้งสิ้นของเมืองโสโดมและเมืองโกโมราห์แล้วก็ไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 12, 'และได้จับโลทบุตรชายของน้องชายอับรามผู้ซึ่งอาศัยอยู่ในเมืองโสโดมและทรัพย์สิ่งของของเขาแล้วจากไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 13, 'แล้วมีคนหนึ่งที่หนีมานั้นได้บอกให้อับรามชาวฮีบรู เพราะว่าท่านอาศัยอยู่ที่ราบของมัมเรคนอาโมไรต์ พี่น้องของเอชโคล์และพี่น้องของอาเนอร์ คนเหล่านี้เป็นพันธมิตรกับอับราม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 14, 'เมื่ออับรามได้ยินว่าหลานชายของท่านถูกจับไปเป็นเชลย ท่านจึงนําคนชํานาญศึกที่เกิดในบ้านท่าน จํานวนสามร้อยสิบแปดคน และตามไปทันที่เมืองดาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 15, 'ท่านจึงแยกคนของท่าน ทั้งท่านและคนใช้ของท่านออกเป็นกองๆในกลางคืน ก็เข้าตีและไล่ตามจนถึงเมืองโฮบาห์ซึ่งอยู่ทางด้านซ้ายเมืองดามัสกัส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 16, 'และท่านนําบรรดาทรัพย์สิ่งของกลับคืนมาหมด ทั้งนําโลทหลานชายของท่าน ทรัพย์สิ่งของของเขา ผู้หญิง และประชาชนกลับมาด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 17, 'หลังจากท่านกลับจากการฆ่ากษัตริย์เคโดร์ลาโอเมอร์และกษัตริย์ทั้งหลายที่ร่วมกําลังกันนั้นแล้ว กษัตริย์เมืองโสโดมก็ออกมารับท่าน ณ ที่หุบเขาชาเวห์ ซึ่งคือหุบเขาของกษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 18, 'เมลคีเซเดคกษัตริย์เมืองซาเล็มได้นําขนมปังและน้ําองุ่นมาให้ และท่านก็เป็นปุโรหิตของพระเจ้าผู้สูงสุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 19, 'ท่านก็อวยพรแก่อับรามว่า “ขอให้พระเจ้าผู้สูงสุดผู้ทรงเป็นเจ้าของฟ้าสวรรค์และแผ่นดินโลกโปรดให้อับรามได้รับพรเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 20, 'และจงสรรเสริญแด่พระเจ้าผู้สูงสุดผู้ได้ทรงมอบศัตรูทั้งหลายของเจ้าไว้ในมือของเจ้า” และอับรามก็ยกหนึ่งในสิบจากข้าวของทั้งหมดถวายแก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 21, 'กษัตริย์เมืองโสโดมตรัสแก่อับรามว่า “ขอคืนคนให้แก่เราและทรัพย์สิ่งของนั้นเจ้าจงเอาไปเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 22, 'อับรามกล่าวแก่กษัตริย์เมืองโสโดมว่า “ข้าพเจ้าได้ยกมือของข้าพเจ้าต่อพระเยโฮวาห์พระเจ้าผู้สูงสุด ผู้ทรงเป็นเจ้าของฟ้าสวรรค์และแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 23, 'ว่าข้าพเจ้าจะไม่รับเอาเส้นด้ายหรือสายรัดรองเท้าและข้าพเจ้าจะไม่รับเอาสิ่งใดๆที่เป็นของท่าน เกรงว่าท่านจะกล่าวว่า ‘เราได้กระทําให้อับรามมั่งมี’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 24, 'เว้นแต่สิ่งที่คนหนุ่มได้กินและส่วนของคนทั้งหลายซึ่งไปกับข้าพเจ้าคืออาเนอร์ เอชโคล์ และมัมเร ให้พวกเขารับส่วนของพวกเขาเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 1, 'ภายหลังเหตุการณ์เหล่านี้พระดํารัสของพระเยโฮวาห์มาถึงอับรามด้วยนิมิตว่า “อับราม อย่ากลัวเลย เราเป็นโล่ของเจ้าและเป็นบําเหน็จยิ่งใหญ่ของเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 2, 'อับรามทูลว่า “ข้าแต่องค์พระผู้เป็นเจ้าพระเจ้า พระองค์จะทรงโปรดประทานอะไรแก่ข้าพระองค์ ด้วยว่าข้าพระองค์ยังไม่มีบุตร และคนต้นเรือนแห่งครัวเรือนของข้าพระองค์คนนี้แหละคือเอลีเยเซอร์ชาวเมืองดามัสกัส”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 3, 'อับรามทูลว่า “ดูเถิด พระองค์มิได้ทรงประทานเชื้อสายให้แก่ข้าพระองค์ และดูเถิด คนหนึ่งที่เกิดในบ้านข้าพระองค์เป็นผู้รับมรดกของข้าพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 4, 'ดูเถิด พระดํารัสของพระเยโฮวาห์มาถึงท่านว่า “คนนี้จะไม่ได้เป็นผู้รับมรดกของเจ้า แต่ผู้ที่จะออกมาจากบั้นเอวของเจ้าจะเป็นผู้รับมรดกของเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 5, 'พระองค์จึงนําท่านออกมากลางแจ้งและตรัสว่า “จงมองดูฟ้าและนับดวงดาวทั้งหลาย ถ้าเจ้าสามารถนับมันได้” และพระองค์ตรัสแก่ท่านว่า “เชื้อสายของเจ้าจะเป็นเช่นนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 6, 'ท่านเชื่อในพระเยโฮวาห์ และพระองค์ทรงนับว่าเป็นความชอบธรรมแก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 7, 'พระองค์ตรัสแก่ท่านว่า “เราคือเยโฮวาห์ที่ได้พาเจ้าออกจากเมืองเออร์ของชาวเคลเดีย เพื่อยกดินแดนนี้ให้เป็นมรดกแก่เจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 8, 'ท่านทูลว่า “ข้าแต่องค์พระผู้เป็นเจ้าพระเจ้า ข้าพระองค์จะรู้ได้อย่างไรว่าข้าพระองค์จะได้ดินแดนนี้เป็นมรดก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 9, 'พระองค์ตรัสแก่ท่านว่า “จงเอาวัวตัวเมียอายุสามปี แพะตัวเมียอายุสามปี แกะตัวผู้อายุสามปี นกเขาตัวหนึ่งและนกพิราบหนุ่มตัวหนึ่งมาให้เรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 10, 'ท่านจึงนําบรรดาสัตว์เหล่านี้มาและผ่ากลางตัวมันวางข้างละซีกตรงกัน แต่นกทั้งหลายนั้นท่านหาได้ผ่าไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 11, 'เมื่อฝูงเหยี่ยวลงมาที่ซากสัตว์เหล่านั้น อับรามก็ไล่มันไปเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 12, 'เมื่อดวงอาทิตย์ใกล้จะตก อับรามก็นอนหลับสนิท และดูเถิด ความหวาดกลัวความหดหู่ใจอย่างยิ่งก็ทับถมท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 13, 'พระองค์ตรัสแก่อับรามว่า “จงรู้แน่เถิดว่าเชื้อสายของเจ้าจะเป็นคนต่างด้าวในแผ่นดินที่ไม่ใช่ของพวกเขาและจะรับใช้พวกนั้น พวกนั้นจะกดขี่ข่มเหงพวกเขาสี่ร้อยปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 14, 'เช่นกันเราจะพิพากษาประเทศนั้นซึ่งพวกเขาจะรับใช้ และต่อมาพวกเขาจะออกมาพร้อมกับทรัพย์สิ่งของเป็นอันมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 15, 'เจ้าจะไปตามบรรพบุรุษของเจ้าโดยผาสุก ในเวลาชรามากเจ้าจะถูกฝังไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 16, 'แต่ในชั่วอายุที่สี่พวกเขาจะกลับมาที่นี่อีกครั้ง เพราะว่าความชั่วช้าของคนอาโมไรต์ยังไม่ครบถ้วน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 17, 'ต่อมาเมื่อดวงอาทิตย์ตกและค่ํามืด ดูเถิด เตาที่ควันพลุ่งอยู่และคบเพลิงได้เลื่อนลอยมาที่ระหว่างกลางซีกสัตว์เหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 18, 'ในวันเดียวกันนั้นพระเยโฮวาห์ทรงกระทําพันธสัญญากับอับรามว่า “เราได้ยกแผ่นดินนี้แก่เชื้อสายของเจ้าแล้ว ตั้งแต่แม่น้ําอียิปต์ไปจนถึงแม่น้ําใหญ่ คือแม่น้ํายูเฟรติส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 19, 'ทั้งแผ่นดินของคนเคไนต์ คนเคนัส คนขัดโมไนต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 20, 'คนฮิตไทต์ คนเปริสซี คนเรฟาอิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 21, 'คนอาโมไรต์ คนคานาอัน คนเกอร์กาชี และคนเยบุส”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 1, 'นางซารายภรรยาของอับรามไม่มีบุตรให้ท่าน และนางมีหญิงสาวใช้ชาวอียิปต์คนหนึ่งซึ่งมีชื่อว่าฮาการ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 2, 'นางซารายจึงพูดกับอับรามว่า “ดูเถิด บัดนี้พระเยโฮวาห์ไม่ให้ข้าพเจ้ามีบุตร ขอท่านกรุณาเข้าไปหาสาวใช้ของข้าพเจ้า บางทีข้าพเจ้าอาจจะได้บุตรโดยนาง” และอับรามก็ฟังเสียงนางซาราย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 3, 'ภายหลังอับรามอาศัยอยู่ในแผ่นดินคานาอันได้สิบปีแล้ว นางซารายภรรยาของอับรามก็ยกฮาการ์คนอียิปต์สาวใช้ของตนให้เป็นภรรยาของอับรามสามีของนาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 4, 'ท่านเข้าไปหานางฮาการ์ นางก็ตั้งครรภ์ เมื่อนางรู้ว่านางตั้งครรภ์แล้ว นางก็ดูหมิ่นนายผู้หญิงของนางในใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 5, 'นางซารายจึงพูดกับอับรามว่า “ให้ความผิดของข้าพเจ้าตกอยู่กับท่านเถิด ข้าพเจ้าให้สาวใช้ของข้าพเจ้าไว้ในอ้อมอกของท่าน เมื่อนางรู้ว่านางตั้งครรภ์แล้วนางก็ดูหมิ่นข้าพเจ้าในใจของนาง ขอพระเยโฮวาห์ทรงพิพากษาระหว่างข้าพเจ้ากับท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 6, 'แต่อับรามพูดกับนางซารายว่า “ดูเถิด สาวใช้ของเจ้าอยู่ในมือของเจ้า จงกระทําแก่เขาตามที่เจ้าเห็นควร” เมื่อนางซารายเคี่ยวเข็ญหญิงนั้น หญิงนั้นจึงหนีไปให้พ้นหน้าของนาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 7, 'ทูตสวรรค์ของพระเยโฮวาห์พบหญิงนั้นที่น้ําพุในถิ่นทุรกันดาร คือที่น้ําพุในทางที่จะไปเมืองชูร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 8, 'ทูตนั้นจึงพูดว่า “ฮาการ์สาวใช้ของนางซาราย เจ้ามาจากไหนและเจ้าจะไปไหน” นางจึงทูลว่า “ข้าพระองค์หนีมาให้พ้นหน้าจากนางซารายนายผู้หญิงของข้าพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 9, 'ทูตสวรรค์ของพระเยโฮวาห์กล่าวแก่นางว่า “จงกลับไปหานายผู้หญิงของเจ้า และยอมอยู่ใต้อํานาจของเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 10, 'แล้วทูตสวรรค์ของพระเยโฮวาห์กล่าวแก่หญิงนั้นว่า “เราจะให้เชื้อสายของเจ้าทวีมากขึ้น เพราะว่าจะมีคนจํานวนมากมายจนนับไม่ถ้วน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 11, 'ทูตสวรรค์ของพระเยโฮวาห์กล่าวแก่นางว่า “ดูเถิด เจ้ามีครรภ์แล้วและจะคลอดบุตรชายคนหนึ่ง จะเรียกชื่อของเขาว่า อิชมาเอล เพราะว่าพระเยโฮวาห์ทรงรับฟังความทุกข์ของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 12, 'เขาจะเป็นคนป่า มือของเขาจะต่อสู้คนทั้งปวงและมือคนทั้งปวงจะต่อสู้เขา และเขาจะอาศัยอยู่ตรงหน้าบรรดาพี่น้องของเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 13, 'นางจึงเรียกพระนามของพระเยโฮวาห์ผู้ตรัสแก่นางว่า “พระองค์พระเจ้าผู้ทรงทอดพระเนตรข้าพระองค์” เพราะนางพูดว่า “ข้าพระองค์ได้เห็นพระองค์ที่นี่ ผู้ทรงทอดพระเนตรข้าพระองค์ด้วยหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 14, 'เหตุฉะนั้นจึงเรียกชื่อบ่อน้ําว่า เบเออลาไฮรอย ดูเถิด อยู่ระหว่างเมืองคาเดชกับเมืองเบเรด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 15, 'นางฮาการ์คลอดบุตรชายคนหนึ่งให้แก่อับราม อับรามจึงเรียกชื่อบุตรชายของท่านซึ่งนางฮาการ์คลอดออกมาว่า อิชมาเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 16, 'เมื่อนางฮาการ์คลอดอิชมาเอลให้แก่อับรามนั้น อับรามอายุได้แปดสิบหกปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 1, 'เมื่ออายุอับรามได้เก้าสิบเก้าปี พระเยโฮวาห์ทรงปรากฏแก่อับรามและตรัสแก่ท่านว่า “เราเป็นพระเจ้า ผู้ทรงมหิทธิฤทธิ์ จงดําเนินอยู่ต่อหน้าเราและเจ้าจงเป็นคนดีรอบคอบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 2, 'เราจะทําพันธสัญญาของเราระหว่างเรากับเจ้า และจะให้เจ้าทวีมากขึ้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 3, 'อับรามก็ซบหน้าลงถึงดินและพระเจ้าทรงมีพระราชปฏิสันถารกับท่านว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 4, '“สําหรับเรา ดูเถิด นี่เป็นพันธสัญญาของเรากับเจ้า และเจ้าจะเป็นบิดาของประชาชาติมากมาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 5, 'ชื่อของเจ้าจะไม่เรียกว่า อับราม อีกต่อไป แต่เจ้าจะมีชื่อว่า อับราฮัม เพราะเราจะกระทําให้เจ้าเป็นบิดาของประชาชาติมากมาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 6, 'เราจะกระทําให้เจ้ามีลูกดกทวีมากขึ้น เราจะกระทําให้เจ้าเป็นชนหลายชาติ กษัตริย์หลายองค์จะเกิดมาจากเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 7, 'เราจะตั้งพันธสัญญาของเราระหว่างเรากับเจ้าและเชื้อสายของเจ้าที่มาภายหลังเจ้าตลอดชั่วอายุของเขาให้เป็นพันธสัญญานิรันดร์ เป็นพระเจ้าองค์เดียวแก่เจ้าและเชื้อสายของเจ้าที่มาภายหลังเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 8, 'เราจะให้แผ่นดินที่เจ้าอาศัยอยู่เป็นคนต่างด้าวนี้ คือบรรดาแผ่นดินคานาอันแก่เจ้าและเชื้อสายของเจ้าที่มาภายหลังเจ้าให้เป็นกรรมสิทธิ์นิรันดร์ และเราจะเป็นพระเจ้าของพวกเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 9, 'พระเจ้าตรัสแก่อับราฮัมว่า “เหตุฉะนั้นเจ้าและเชื้อสายของเจ้าที่มาภายหลังเจ้าตลอดชั่วอายุของพวกเขาจะรักษาพันธสัญญาของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 10, 'นี่เป็นพันธสัญญาของเราซึ่งเจ้าจะรักษาระหว่างเรากับเจ้าและเชื้อสายของเจ้าที่มาภายหลังเจ้า คือเด็กผู้ชายทุกคนในท่ามกลางพวกเจ้าจะเข้าสุหนัต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 11, 'เจ้าจะเข้าสุหนัตตัดหนังหุ้มปลายองคชาตของเจ้า และมันจะเป็นหมายสําคัญแห่งพันธสัญญาระหว่างเรากับเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 12, 'ผู้ชายที่มีอายุแปดวันจะเข้าสุหนัตในท่ามกลางพวกเจ้า เด็กผู้ชายทุกคนตลอดชั่วอายุของพวกเจ้า ผู้ชายที่เกิดในบ้านหรือเอาเงินซื้อมาจากคนต่างด้าวใดๆซึ่งมิใช่เชื้อสายของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 13, 'ผู้ชายที่เกิดในบ้านของเจ้าและผู้ชายที่เอาเงินซื้อมาจําเป็นต้องเข้าสุหนัต และพันธสัญญาของเราจะอยู่ที่เนื้อของเจ้า เป็นพันธสัญญานิรันดร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 14, 'เด็กผู้ชายที่มิได้เข้าสุหนัต คือผู้ที่มิได้เข้าสุหนัตตัดหนังหุ้มปลายองคชาตของเขา ชีวิตนั้นจะถูกตัดขาดจากชนชาติของเขา เขาได้ละเมิดพันธสัญญาของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 15, 'และพระเจ้าตรัสแก่อับราฮัมว่า “สําหรับซารายภรรยาของเจ้า เจ้าจะไม่เรียกชื่อนางว่า ซาราย แต่จะเรียกชื่อนางว่า ซาราห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 16, 'เราจะอวยพรแก่นางและให้บุตรชายคนหนึ่งแก่เจ้ากับนางด้วย ใช่ เราจะอวยพรนาง นางจะเป็นมารดาของชนหลายชาติ กษัตริย์ของชนหลายชาติจะมาจากนาง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 17, 'ดังนั้นอับราฮัมจึงซบหน้าลงหัวเราะคิดในใจของท่านว่า “ชายผู้มีอายุหนึ่งร้อยปีจะให้กําเนิดบุตรได้หรือ ซาราห์ผู้มีอายุได้เก้าสิบปีแล้วจะคลอดบุตรหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 18, 'อับราฮัมทูลพระเจ้าว่า “โอ ขอให้อิชมาเอลมีชีวิตอยู่ต่อพระพักตร์ของพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 19, 'พระเจ้าตรัสว่า “ซาราห์ภรรยาของเจ้าจะคลอดบุตรชายคนหนึ่งแก่เจ้าเป็นแน่ เจ้าจะเรียกชื่อของเขาว่า อิสอัค และเราจะตั้งพันธสัญญาของเรากับเขาและกับเชื้อสายของเขาที่มาภายหลังเขาให้เป็นพันธสัญญานิรันดร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 20, 'สําหรับอิชมาเอลนั้นเราได้ฟังเจ้าแล้ว ดูเถิด เราได้อวยพรเขาและจะกระทําให้เขามีลูกดกทวีมากขึ้นอุดมบริบูรณ์อย่างยิ่ง เขาจะให้กําเนิดเจ้านายสิบสององค์และเราจะกระทําให้เขาเป็นชนชาติใหญ่ชนชาติหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 21, 'แต่พันธสัญญาของเรา เราจะตั้งไว้กับอิสอัคซึ่งซาราห์จะคลอดให้แก่เจ้าปีหน้าในเวลานี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 22, 'พระองค์มีพระราชปฏิสันถารกับท่านเสร็จแล้ว พระเจ้าก็เสด็จขึ้นไปจากอับราฮัม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 23, 'อับราฮัมจึงเอาอิชมาเอลบุตรชายของท่าน บรรดาคนทั้งปวงที่เกิดในบ้านของท่านและบรรดาคนทั้งปวงที่ได้ซื้อมาด้วยเงินของท่าน คือผู้ชายทุกคนท่ามกลางคนที่อยู่ในบ้านของอับราฮัม ให้เข้าสุหนัตตัดหนังหุ้มปลายองคชาตของพวกเขาในวันนั้นตามที่พระเจ้าตรัสไว้แก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 24, 'เมื่อท่านเข้าสุหนัตตัดหนังหุ้มปลายองคชาตของท่าน อับราฮัมมีอายุเก้าสิบเก้าปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 25, 'และอิชมาเอลบุตรชายของท่านมีอายุสิบสามปีเมื่อเขาเข้าสุหนัตตัดหนังหุ้มปลายองคชาตของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 26, 'อับราฮัมและอิชมาเอลบุตรชายของท่านเข้าสุหนัตในวันเดียวกันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 27, 'บรรดาผู้ชายในบ้านของท่าน ทั้งที่เกิดในบ้านของท่านและซื้อมาด้วยเงินจากคนต่างด้าวก็เข้าสุหนัตพร้อมกับท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 1, 'พระเยโฮวาห์ทรงปรากฏแก่เขาที่ราบของมัมเร และเขานั่งอยู่ที่ประตูเต็นท์ในเวลาแดดร้อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 2, 'เขาจึงเงยหน้าขึ้นมองดู และดูเถิด มีชายสามคนยืนอยู่ข้างเขา เมื่อเขาเห็นท่านเหล่านั้นจึงวิ่งจากประตูเต็นท์ไปต้อนรับท่านเหล่านั้นและก้มหน้าของเขาลงถึงดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 3, 'และพูดว่า “เจ้านายของข้าพเจ้า ถ้าบัดนี้ข้าพเจ้าเป็นที่โปรดปรานในสายตาของท่าน ขอท่านโปรดอย่าผ่านไปจากผู้รับใช้ของท่านเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 4, 'ข้าพเจ้าขอความกรุณาจากท่านยอมให้เอาน้ํานิดหน่อยมาล้างเท้าของท่าน และให้ท่านทั้งหลายพักใต้ต้นไม้เถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 5, 'ข้าพเจ้าจะไปเอาอาหารหน่อยหนึ่งมาให้และขอให้ท่านชื่นใจเถิด หลังจากนั้นจึงค่อยออกเดินทาง เพราะว่าท่านมายังผู้รับใช้ของท่านแล้ว” ท่านเหล่านั้นจึงว่า “จงทําตามที่เจ้ากล่าวเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 6, 'อับราฮัมรีบเข้าไปในเต็นท์หานางซาราห์และพูดว่า “จงรีบเอาแป้งละเอียดสามถังมานวดแล้วทําขนมบนเตา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 7, 'อับราฮัมจึงวิ่งไปที่ฝูงสัตว์เอาลูกวัวอ่อนและดีตัวหนึ่งมอบให้ชายหนุ่มคนหนึ่งและเขาก็รีบปรุงเป็นอาหาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 8, 'เขาเอาเนยข้น น้ํานมและลูกวัวซึ่งเขาได้ปรุงแล้วนั้นมาวางไว้ต่อหน้าท่านเหล่านั้น และเขายืนอยู่ข้างท่านเหล่านั้นใต้ต้นไม้แล้วท่านเหล่านั้นได้รับประทาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 9, 'ท่านเหล่านั้นจึงกล่าวแก่เขาว่า “ซาราห์ภรรยาของเจ้าอยู่ที่ไหน” และเขาพูดว่า “ดูเถิด อยู่ในเต็นท์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 10, 'ท่านจึงกล่าวว่า “เราจะกลับมาหาเจ้าแน่นอนตามเวลาแห่งชีวิต และดูเถิด ซาราห์ภรรยาของเจ้าจะมีบุตรชายคนหนึ่ง” ซาราห์ได้ฟังอยู่ที่ประตูเต็นท์ซึ่งอยู่ข้างหลังท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 11, 'อับราฮัมและซาราห์ก็มีอายุแก่ชรามากแล้ว และนางซาราห์ตามปกติของผู้หญิงก็หมดแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 12, 'ฉะนั้นนางซาราห์จึงหัวเราะในใจพูดว่า “ข้าพเจ้าแก่แล้ว นายของข้าพเจ้าก็แก่ด้วย ข้าพเจ้าจะมีความยินดีอีกหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 13, 'พระเยโฮวาห์ตรัสกับอับราฮัมว่า “ทําไมนางซาราห์หัวเราะพูดว่า ‘ข้าพเจ้าจะคลอดบุตรคนหนึ่งซึ่งข้าพเจ้าแก่แล้วจริงๆหรือ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 14, 'มีสิ่งใดที่ยากเกินไปสําหรับพระเยโฮวาห์หรือ เมื่อถึงเวลากําหนดเราจะกลับมาหาเจ้าตามเวลาแห่งชีวิต และซาราห์จะมีบุตรชายคนหนึ่ง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 15, 'ดังนั้นนางซาราห์ปฏิเสธว่า “ข้าพระองค์มิได้หัวเราะ” เพราะนางกลัว และพระองค์ตรัสว่า “ไม่ใช่ แต่เจ้าหัวเราะ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 16, 'บุรุษเหล่านั้นก็ลุกขึ้นจากที่นั่นและมองไปทางเมืองโสโดม อับราฮัมไปกับท่านเหล่านั้นเพื่อตามไปส่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 17, 'พระเยโฮวาห์ตรัสว่า “เราจะซ่อนสิ่งซึ่งเรากระทําจากอับราฮัมหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 18, 'ด้วยว่าอับราฮัมจะเป็นประชาชาติใหญ่โตและมีกําลังมากอย่างแน่นอน และบรรดาประชาชาติทั้งหลายในแผ่นดินโลกจะได้รับพระพรเพราะเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 19, 'เพราะว่าเรารู้จักเขา เขาจะสั่งลูกหลานและครอบครัวของเขาที่สืบมา พวกเขาจะรักษาพระมรรคาของพระเยโฮวาห์ เพื่อทําความเที่ยงธรรมและความยุติธรรม เพื่อพระเยโฮวาห์จะประทานแก่อับราฮัมตามสิ่งซึ่งพระองค์ได้ตรัสไว้เกี่ยวกับเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 20, 'พระเยโฮวาห์ตรัสว่า “เพราะเสียงร้องของเมืองโสโดมและเมืองโกโมราห์ดังมากและเพราะบาปของพวกเขาก็หนักเหลือเกิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 21, 'เราจะลงไปเดี๋ยวนี้ดูว่าพวกเขากระทําตามเสียงร้องทั้งสิ้นซึ่งมาถึงเราหรือไม่ ถ้าไม่ เราจะรู้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 22, 'บุรุษเหล่านั้นหันหน้าจากที่นั่นไปทางเมืองโสโดม แต่อับราฮัมยังยืนอยู่ต่อพระพักตร์พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 23, 'อับราฮัมเข้ามาใกล้ทูลว่า “พระองค์จะทรงทําลายคนชอบธรรมพร้อมกับคนชั่วด้วยหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 24, 'บางทีมีคนชอบธรรมห้าสิบคนในเมืองนั้น พระองค์จะทรงทําลายและไม่ละเว้นเมืองนั้นเพราะคนชอบธรรมห้าสิบคนที่อยู่ในนั้นด้วยหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 25, 'ขอพระองค์อย่ากระทําเช่นนี้เลย ที่จะฆ่าคนชอบธรรมพร้อมกับคนชั่ว และให้คนชอบธรรมเหมือนอย่างคนชั่ว ให้การนั้นอยู่ห่างไกลจากพระองค์ ผู้พิพากษาของทั่วแผ่นดินโลกจะไม่กระทําการยุติธรรมหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 26, 'พระเยโฮวาห์ตรัสว่า “ถ้าเราพบคนชอบธรรมในท่ามกลางเมืองโสโดมห้าสิบคน เราจะละเว้นทั้งเมืองเพราะเห็นแก่พวกเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 27, 'อับราฮัมทูลตอบว่า “ดูเถิด กรุณาเถิด ข้าพระองค์มีเจตนาทูลต่อองค์พระผู้เป็นเจ้า ซึ่งข้าพระองค์เป็นเพียงผงคลีดินและขี้เถ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 28, 'บางทีคนชอบธรรมห้าสิบคนจะขาดไปห้าคน พระองค์จะทรงทําลายเมืองนั้นทั้งเมืองเพราะขาดห้าคนหรือ” พระองค์ตรัสว่า “ถ้าเราพบสี่สิบห้าคนที่นั่น เราจะไม่ทําลายเมืองนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 29, 'เขายังทูลต่อพระองค์อีกครั้งว่า “บางทีจะพบสี่สิบคนที่นั่น” และพระองค์ตรัสว่า “เราจะไม่กระทําเพราะเห็นแก่สี่สิบคน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 30, 'เขาทูลต่อพระองค์ว่า “โอ ขอทรงโปรดอย่าให้องค์พระผู้เป็นเจ้าทรงพระพิโรธเลย และข้าพระองค์จะกราบทูล บางทีจะพบสามสิบคนที่นั่น” และพระองค์ตรัสว่า “เราจะไม่กระทําถ้าเราพบสามสิบคนที่นั่น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 31, 'เขาทูลว่า “ดูเถิด กรุณาเถิด ข้าพระองค์มีเจตนาทูลต่อองค์พระผู้เป็นเจ้า บางทีจะพบยี่สิบคนที่นั่น” และพระองค์ตรัสว่า “เราจะไม่ทําลายเมืองนั้นเพราะเห็นแก่ยี่สิบคน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 32, 'เขาทูลว่า “โอ ขอทรงโปรดอย่าให้องค์พระผู้เป็นเจ้าทรงพระพิโรธเลย และข้าพระองค์จะยังกราบทูลครั้งนี้ครั้งเดียว บางทีจะพบสิบคนที่นั่น” และพระองค์ตรัสว่า “เราจะไม่ทําลายเมืองนั้นเพราะเห็นแก่สิบคน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 33, 'เมื่อพระองค์ทรงมีพระราชปฏิสันถารกับอับราฮัมจบลงแล้ว พระเยโฮวาห์ได้เสด็จไปและอับราฮัมก็กลับไปที่อยู่ของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 1, 'ทูตสวรรค์สององค์มาถึงเมืองโสโดมในเวลาเย็น โลทได้นั่งอยู่ที่ประตูเมืองโสโดม เมื่อโลทเห็นแล้วก็ลุกขึ้นไปพบทูตเหล่านั้นและได้ก้มหน้าของเขาลงถึงดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 2, 'แล้วเขากล่าวว่า “ดูเถิด เจ้านายของข้าพเจ้า ข้าพเจ้าขอวิงวอนท่านโปรดกรุณาแวะไปบ้านผู้รับใช้ของท่าน ค้างแรมคืนนี้ ล้างเท้าของท่าน แล้วท่านจะได้ตื่นแต่เช้าเดินทางต่อไป” ทูตเหล่านั้นกล่าวว่า “อย่าเลย แต่พวกเราจะค้างแรมที่ถนนในคืนนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 3, 'เขาได้รบเร้าทูตเหล่านั้นอย่างมาก ทูตเหล่านั้นจึงแวะเข้าไปในบ้านของเขา และเขาจึงจัดการเลี้ยงทูตเหล่านั้น ทําขนมปังไร้เชื้อและทูตเหล่านั้นจึงรับประทาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 4, 'แต่ก่อนที่ทูตเหล่านั้นเข้านอน พวกผู้ชายเมืองนั้นคือพวกผู้ชายชาวเมืองโสโดม ทั้งแก่และหนุ่ม ทุกคนจากทุกสารทิศ มาล้อมเรือนนั้นไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 5, 'พวกเขาเรียกโลทและพูดกับเขาว่า “ผู้ชายเหล่านั้นซึ่งมาหาท่านคืนนี้อยู่ที่ไหน จงนําเขาเหล่านั้นออกมาให้พวกเราเพื่อพวกเราจะได้ร่วมรู้กับเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 6, 'โลทก็ออกทางประตูไปหาพวกนั้นและปิดประตูหลังจากที่เขาออกไปแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 7, 'และกล่าวว่า “พี่น้องทั้งหลาย ข้าพเจ้าขอวิงวอนท่าน อย่ากระทําชั่วช้าเช่นนี้เลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 8, 'ดูเถิด ข้าพเจ้ามีบุตรสาวสองคนซึ่งไม่เคยร่วมรู้กับชายเลย ข้าพเจ้าขอวิงวอนท่าน ขอให้ข้าพเจ้านําพวกเธอออกมาให้ท่าน ให้ท่านกระทําแก่พวกเธอตามที่เห็นชอบในสายตาของท่านเถิด เพียงแต่อย่ากระทําอะไรแก่ชายเหล่านี้เลย เพราะเหตุว่าพวกเขาเหล่านี้เข้ามาอยู่ใต้ร่มชายคาของข้าพเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 9, 'พวกเขาพูดว่า “ถอยไป” และพวกเขาพูดอีกว่า “คนนี้เข้ามาอาศัยอยู่และเขาจะมาตั้งตัวเป็นผู้พิพากษา บัดนี้เราจะทําการชั่วร้ายกับท่านยิ่งกว่าคนเหล่านั้น” พวกเขาจึงผลักคนนั้นโดยแรงคือโลทนั่นเอง และเข้ามาใกล้เพื่อพังประตู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 10, 'แต่ทูตเหล่านั้นจึงยื่นมือออกไปดึงโลทเข้ามาในบ้านและปิดประตู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 11, 'ทูตเหล่านั้นทําให้พวกผู้ชายที่อยู่ประตูบ้านนั้นตาบอดทั้งผู้ใหญ่และผู้น้อย ดังนั้นพวกเขาจึงหาประตูจนเหนื่อย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 12, 'ทูตเหล่านั้นจึงพูดกับโลทว่า “ที่นี่มีใครอีกไหม จงพาบุตรเขย บุตรชาย บุตรสาว และสิ่งใดๆของเจ้าที่อยู่ในเมืองนี้ออกจากที่นี่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 13, 'เพราะพวกเราจะทําลายสถานที่แห่งนี้เพราะว่าเสียงร้องของพวกเขาดังมากยิ่งขึ้นต่อพระพักตร์พระเยโฮวาห์ และพระเยโฮวาห์ทรงส่งพวกเรามาทําลายมันเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 14, 'โลทจึงออกไปพูดกับบุตรเขยของเขาซึ่งได้แต่งงานกับบุตรสาวของเขาว่า “ลุกขึ้น เจ้าจงออกไปจากสถานที่นี้ เพราะพระเยโฮวาห์จะทรงทําลายเมืองนี้” แต่บุตรเขยของเขากลับดูเหมือนว่าเขาพูดล้อเล่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 15, 'เมื่อรุ่งเช้าทูตสวรรค์เหล่านั้นจึงเร่งเร้าโลทว่า “จงลุกขึ้น พาภรรยาของเจ้า และบุตรสาวทั้งสองของเจ้า ซึ่งอยู่ที่นี่ไปเสีย เกรงว่าพวกเจ้าจะถูกทําลายพร้อมกับความชั่วช้าของเมืองนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 16, 'ขณะที่เขายังรีรออยู่ ทูตเหล่านั้นจึงคว้าจับมือเขา มือภรรยาของเขาและมือบุตรสาวทั้งสองของเขา พระเยโฮวาห์ทรงมีความเมตตาต่อเขา ทูตเหล่านั้นจึงนําเขาออกมาและให้เขาอยู่ที่นอกเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 17, 'ต่อมาเมื่อทูตเหล่านั้นนําพวกเขาออกมาภายนอกแล้ว ทูตพูดว่า “จงหนีเอาชีวิตรอด อย่าได้เหลียวหลังมาดูหรือพักอยู่ที่ราบลุ่มทั้งหลาย จงหนีไปที่ภูเขาเกรงว่าเจ้าจะถูกทําลาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 18, 'โลทจึงกล่าวแก่ทูตเหล่านั้นว่า “โอ เจ้านายของข้าพเจ้า อย่าให้เป็นอย่างนั้นเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 19, 'ดูเถิด ผู้รับใช้ของท่านได้รับพระกรุณาในสายตาของท่านและท่านมีความเมตตาอย่างยิ่ง ซึ่งท่านได้สําแดงต่อข้าพเจ้าในการช่วยชีวิตข้าพเจ้า ข้าพเจ้าไม่สามารถหนีไปยังภูเขาได้ เกรงว่าสิ่งชั่วร้ายจะมาถึงตัวข้าพเจ้าและข้าพเจ้าจะตายเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 20, 'ดูเถิด กรุณาเถิด เมืองนี้อยู่ใกล้ที่จะหนีไปถึงได้และเป็นเมืองเล็ก โอ โปรดให้ข้าพเจ้าหนีไปที่นั่น (เป็นเมืองเล็กๆมิใช่หรือ) และชีวิตของข้าพเจ้าจะรอด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 21, 'ทูตกล่าวแก่เขาว่า “ดูเถิด เรายอมรับเจ้าเกี่ยวกับเรื่องนี้ด้วยว่าเราจะไม่ทําลายล้างเมืองนี้ซึ่งเจ้าได้กล่าวถึง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 22, 'เจ้าจงรีบหนีไปที่นั่น เพราะเราไม่สามารถกระทําอะไรได้จนกว่าเจ้าไปถึงที่นั่น” เหตุฉะนั้นจึงเรียกชื่อเมืองนั้นว่าโศอาร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 23, 'เมื่อโลทเข้าไปยังเมืองโศอาร์ ตะวันก็ขึ้นมาเหนือแผ่นดินโลกแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 24, 'ดังนั้นพระเยโฮวาห์ทรงให้กํามะถันและไฟจากพระเยโฮวาห์ตกมาจากฟ้าสวรรค์ลงมาบนเมืองโสโดมและเมืองโกโมราห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 25, 'พระองค์ทรงทําลายล้างเมืองทั้งหลายเหล่านั้น บรรดาที่ราบลุ่ม ชาวเมืองทั้งปวงและสิ่งที่งอกขึ้นมาบนแผ่นดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 26, 'แต่ภรรยาของเขาผู้ตามข้างหลังเขาเหลียวกลับไปมองดูและนางจึงกลายเป็นเสาเกลือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 27, 'อับราฮัมลุกขึ้นตั้งแต่เช้าตรู่ไปยังสถานที่ที่ท่านเคยยืนต่อพระพักตร์พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 28, 'ท่านมองไปทางเมืองโสโดม เมืองโกโมราห์และดินแดนที่ราบลุ่มทั้งหลาย และดูเถิด ก็เห็นควันจากแผ่นดินนั้นพลุ่งขึ้นเหมือนควันจากเตาไฟใหญ่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 29, 'ต่อมาเมื่อพระเจ้าทรงทําลายเมืองทั้งหลายในที่ราบลุ่มแล้วนั้น พระเจ้าทรงระลึกถึงอับราฮัม และส่งโลทออกไปจากท่ามกลางการทําลายล้าง เมื่อพระองค์ทรงทําลายล้างเมืองทั้งหลายซึ่งโลทอาศัยอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 30, 'โลทขึ้นไปจากเมืองโศอาร์ไปอาศัยอยู่บนภูเขาพร้อมกับบุตรสาวสองคนของเขา เพราะเขากลัวที่อาศัยในเมืองโศอาร์ เขาจึงไปอาศัยอยู่ในถ้ําทั้งเขากับบุตรสาวสองคนของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 31, 'บุตรสาวหัวปีพูดกับน้องสาวว่า “บิดาของเราแก่แล้วและไม่มีชายใดในแผ่นดินโลกเข้ามาหาพวกเราตามธรรมเนียมของทั่วโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 32, 'มาเถิด พวกเราจงให้บิดาของพวกเราดื่มเหล้าองุ่น และพวกเราจะนอนกับท่าน เพื่อพวกเราจะสงวนเชื้อสายของบิดาพวกเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 33, 'ในคืนวันนั้นพวกเธอจึงให้บิดาของพวกเธอดื่มเหล้าองุ่น บุตรสาวหัวปีเข้าไปนอนกับบิดาของเธอ และเขาไม่สังเกตว่าเธอมานอนด้วยเมื่อไรและเธอลุกขึ้นไปเมื่อไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 34, 'ต่อมาวันรุ่งขึ้นบุตรสาวหัวปีพูดกับน้องสาวว่า “ดูเถิด เมื่อคืนนี้เราได้นอนกับบิดาของเรา พวกเราจงให้ท่านดื่มเหล้าองุ่นในคืนนี้อีก และเจ้าจงเข้าไปนอนกับท่านเพื่อพวกเราจะสงวนเชื้อสายของบิดาพวกเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 35, 'พวกเธอจึงให้บิดาของพวกเธอดื่มเหล้าองุ่นในคืนวันนั้นด้วย น้องสาวก็ลุกขึ้นไปนอนกับเขา และเขาไม่สังเกตว่าเธอมานอนด้วยเมื่อไรและเธอลุกขึ้นไปเมื่อไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 36, 'ดังนั้น บุตรสาวทั้งสองของโลทก็ตั้งครรภ์กับบิดาของพวกเธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 37, 'บุตรสาวหัวปีคลอดบุตรชายคนหนึ่งและเรียกชื่อของเขาว่า โมอับ เขาเป็นบรรพบุรุษของคนโมอับมาจนถึงทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 38, 'ส่วนน้องสาว เธอคลอดบุตรชายคนหนึ่งด้วยและเรียกชื่อของเขาว่า เบน-อัมมี เขาเป็นบรรพบุรุษของคนอัมโมนมาจนถึงทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 1, 'อับราฮัมเดินทางจากที่นั่นไปยังดินแดนทางใต้ อาศัยอยู่ระหว่างเมืองคาเดชและเมืองชูร์ และอาศัยอยู่ในเมืองเก-ราร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 2, 'อับราฮัมบอกถึงนางซาราห์ภรรยาของตนว่า “นางเป็นน้องสาวของข้าพเจ้า” อาบีเมเลคกษัตริย์แห่งเมืองเก-ราร์จึงใช้คนมานํานางซาราห์ไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 3, 'แต่พระเจ้าเสด็จมาหาอาบีเมเลคทางพระสุบินในเวลากลางคืนและตรัสกับท่านว่า “ดูเถิด เจ้าเป็นเหมือนคนตาย เพราะหญิงนั้นซึ่งเจ้านํามา ด้วยว่านางเป็นภรรยาของผู้อื่นแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 4, 'แต่อาบีเมเลคยังไม่ได้เข้าใกล้นาง ท่านจึงทูลว่า “ข้าแต่องค์พระผู้เป็นเจ้า พระองค์จะประหารชนชาติที่ชอบธรรมด้วยหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 5, 'เขาบอกแก่ข้าพระองค์มิใช่หรือว่า ‘นางเป็นน้องสาวของข้าพเจ้า’ และแม้แต่นางเองก็ว่า ‘เขาเป็นพี่ชายของข้าพเจ้า’ ข้าพระองค์กระทําดังนี้ด้วยจิตใจอันซื่อตรงและด้วยมือที่บริสุทธิ์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 6, 'พระเจ้าตรัสกับท่านในพระสุบินว่า “แท้จริงเรารู้แล้วว่าเจ้ากระทําดังนี้ด้วยจิตใจอันซื่อตรง เราจึงยับยั้งเจ้าไม่ให้ทําบาปต่อเรา เหตุฉะนั้นเราไม่ยอมให้เจ้าถูกต้องนางนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 7, 'ฉะนั้นบัดนี้จงคืนภรรยาให้แก่ชายนั้น เพราะเขาเป็นผู้พยากรณ์ เขาจะอธิษฐานเพื่อเจ้าแล้วเจ้าจะมีชีวิตอยู่ ถ้าเจ้าไม่คืนนางนั้น เจ้าจงรู้ว่าเจ้าจะตายเป็นแน่ ทั้งเจ้าและทุกคนที่เป็นของเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 8, 'เหตุฉะนั้นอาบีเมเลคตื่นบรรทมตั้งแต่เช้าตรู่ ทรงเรียกบรรดาข้าราชการของท่าน และทรงรับสั่งเรื่องทั้งหมดนี้ให้พวกเขาฟัง และคนเหล่านั้นก็กลัวยิ่งนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 9, 'ดังนั้นอาบีเมเลคทรงเรียกอับราฮัมมาและตรัสกับท่านว่า “เจ้าได้กระทําอะไรแก่พวกเรา เราได้กระทําผิดอะไรต่อเจ้า ที่เจ้านําบาปใหญ่โตมายังเราและราชอาณาจักรของเรา เจ้าได้กระทําสิ่งซึ่งไม่ควรกระทําแก่เรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 10, 'อาบีเมเลคตรัสกับอับราฮัมว่า “เจ้าคิดอะไรเจ้าจึงได้กระทําสิ่งนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 11, 'อับราฮัมทูลว่า “เพราะข้าพระองค์คิดว่าไม่มีความเกรงกลัวพระเจ้าในสถานที่นี่เป็นแน่ พวกเขาจะฆ่าข้าพระองค์เพราะเห็นแก่ภรรยาของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 12, 'ยิ่งกว่านั้นนางเป็นน้องสาวของข้าพระองค์จริงๆ นางเป็นบุตรสาวของบิดาข้าพระองค์ แต่ไม่ใช่บุตรสาวของมารดาข้าพระองค์ และนางได้มาเป็นภรรยาของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 13, 'ต่อมาเมื่อพระเจ้าทรงโปรดให้ข้าพระองค์ต้องเร่ร่อนจากบ้านบิดาของข้าพระองค์ ข้าพระองค์จึงพูดกับนางว่า ‘นี่เป็นความกรุณาซึ่งเจ้าจะสําแดงต่อข้าพเจ้า ในสถานที่ทุกๆแห่งที่เราจะไปนั้นขอให้กล่าวถึงข้าพเจ้าว่า เขาเป็นพี่ชายของดิฉัน’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 14, 'อาบีเมเลคจึงทรงนําแกะ วัวและทาสชายหญิง และประทานให้แก่อับราฮัม แล้วทรงคืนซาราห์ภรรยาของอับราฮัมให้ท่านไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 15, 'แล้วอาบีเมเลคตรัสว่า “ดูเถิด แผ่นดินของเราก็อยู่ต่อหน้าเจ้า เจ้าจะอาศัยอยู่ที่ไหนก็ได้ตามใจชอบ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 16, 'พระองค์ตรัสกับซาราห์ว่า “ดูเถิด เราให้เงินหนึ่งพันแผ่นแก่พี่ชายของเจ้า ดูเถิด พี่ชายจะคลุมตาเจ้าต่อหน้าทุกคนที่อยู่กับเจ้าและคนทั้งปวง” นางก็ถูกติเตียนด้วยถ้อยคําเหล่านี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 17, 'เพราะฉะนั้น อับราฮัมก็อธิษฐานต่อพระเจ้า พระเจ้าทรงรักษาอาบีเมเลค และมเหสีของพระองค์และทาสหญิงให้หาย และเขาเหล่านั้นก็มีบุตร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 18, 'เพราะว่าพระเยโฮวาห์ได้ทรงปิดครรภ์สตรีในราชสํานักของอาบีเมเลคทุกคน เพราะเรื่องซาราห์ภรรยาอับราฮัม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 1, 'พระเยโฮวาห์ทรงเยี่ยมซาราห์เหมือนที่พระองค์ตรัสไว้ และพระเยโฮวาห์ทรงกระทําแก่ซาราห์ดังที่พระองค์ทรงตรัสไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 2, 'เพราะซาราห์ตั้งครรภ์ และคลอดบุตรชายคนหนึ่งให้อับราฮัมเมื่อท่านชรา ตามเวลาซึ่งพระเจ้าได้ตรัสกับท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 3, 'อับราฮัมตั้งชื่อบุตรชายที่เกิดแก่ท่าน ผู้ซึ่งซาราห์คลอดให้ท่านนั้นว่า อิสอัค');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 4, 'แล้วอับราฮัมได้ให้อิสอัคบุตรชายของตนเข้าสุหนัตเมื่อมีอายุแปดวัน ดังที่พระเจ้าทรงบัญชาแก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 5, 'อับราฮัมมีอายุหนึ่งร้อยปีเมื่ออิสอัคบุตรชายเกิดแก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 6, 'นางซาราห์กล่าวว่า “พระเจ้าทรงกระทําให้ข้าพเจ้าหัวเราะ ดังนั้นทุกคนที่ได้ฟังจะพลอยหัวเราะกับข้าพเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 7, 'นางกล่าวอีกว่า “ใครจะพูดกับอับราฮัมได้ว่าซาราห์จะให้ลูกอ่อนกินนม เพราะข้าพเจ้าก็ได้คลอดบุตรชายคนหนึ่งให้ท่านเมื่อท่านชราแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 8, 'เด็กนั้นก็เติบโตขึ้นและหย่านมและอับราฮัมจัดการเลี้ยงใหญ่ในวันนั้นเมื่ออิสอัคหย่านม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 9, 'แต่ซาราห์เห็นบุตรชายของฮาการ์คนอียิปต์ซึ่งนางคลอดให้อับราฮัม กําลังหัวเราะเล่นอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 10, 'นางจึงพูดกับอับราฮัมว่า “ไล่ทาสหญิงคนนี้กับบุตรชายของนางไปเสียเถิด เพราะว่าบุตรชายของทาสหญิงคนนี้จะเป็นผู้รับมรดกร่วมกับอิสอัคบุตรชายของข้าพเจ้าไม่ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 11, 'อับราฮัมกลุ้มใจมาก เพราะเรื่องบุตรชายของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 12, 'แต่พระเจ้าตรัสกับอับราฮัมว่า “เจ้าอย่าโศกเศร้าในสายตาของเจ้าเพราะเรื่องเด็กนั้น และเพราะทาสหญิงของเจ้าเลย ทุกสิ่งที่ซาราห์กล่าวกับเจ้า เจ้าก็จงฟังเสียงของนางเถิด เพราะเขาจะเรียกเชื้อสายของเจ้าทางสายอิสอัค');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 13, 'ส่วนบุตรชายของทาสหญิงนั้น เราจะกระทําให้เป็นชนชาติหนึ่งด้วย เพราะเขาเป็นเชื้อสายของเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 14, 'อับราฮัมจึงลุกขึ้นแต่เช้ามืด ให้ขนมปังและน้ําหนึ่งถุงหนังแก่ฮาการ์ ใส่บ่าให้นางพร้อมกับเด็กนั้นแล้วส่งนางออกไป นางก็จากไปและพเนจรไปในถิ่นทุรกันดารแห่งเบเออร์เชบา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 15, 'และน้ําในถุงหนังนั้นก็หมดไป นางก็วางเด็กนั้นไว้ใต้พุ่มไม้แห่งหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 16, 'แล้วนางก็ไปนั่งลงห่างออกไปตรงหน้าเด็กนั้น ประมาณเท่ากับระยะลูกธนูตก เพราะนางพูดว่า “อย่าให้ข้าเห็นความตายของเด็กนั้นเลย” นางก็นั่งอยู่ตรงหน้าเด็กนั้นแล้วตะเบ็งเสียงร้องไห้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 17, 'พระเจ้าทรงสดับเสียงร้องของเด็กนั้น และทูตสวรรค์ของพระเจ้าจึงเรียกฮาการ์จากฟ้าสวรรค์กล่าวกับนางว่า “ฮาการ์ เจ้าเป็นอะไรไป อย่ากลัวเลย เพราะว่าพระเจ้าทรงสดับเสียงของเด็ก ณ ที่ที่เขาอยู่นั้นแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 18, 'ลุกขึ้นอุ้มเด็กนั้น เอามือจับเขาไว้ให้แน่น เพราะเราจะทําให้เขาเป็นชาติใหญ่ชาติหนึ่ง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 19, 'แล้วพระเจ้าทรงเบิกตาของนาง นางก็เห็นบ่อน้ําแห่งหนึ่ง จึงไปเติมน้ําเต็มถุงหนังและให้เด็กนั้นดื่ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 20, 'พระเจ้าทรงสถิตกับเด็กนั้น เขาเติบโตขึ้น อาศัยอยู่ในถิ่นทุรกันดาร และเป็นนักธนู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 21, 'เขาอาศัยอยู่ในถิ่นทุรกันดารแห่งปาราน มารดาก็หาภรรยาคนหนึ่งจากประเทศอียิปต์ให้เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 22, 'และต่อมาในคราวนั้น อาบีเมเลคและฟีโคล์ผู้บัญชาการทหารของพระองค์ พูดกับอับราฮัมว่า “พระเจ้าทรงสถิตกับท่านในทุกสิ่งที่ท่านกระทํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 23, 'เพราะฉะนั้นบัดนี้จงปฏิญาณในพระนามพระเจ้าให้แก่เราที่นี่ว่า ท่านจะไม่ประพฤติการคดโกงต่อเรา หรือโอรสของเรา หรือต่อหลานของเรา แต่ดังที่เราภักดีต่อท่าน ท่านจงภักดีต่อเราและต่อแผ่นดินซึ่งท่านอาศัยอยู่นี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 24, 'อับราฮัมก็ทูลว่า “ข้าพเจ้ายอมปฏิญาณ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 25, 'อับราฮัมก็ร้องทุกข์ต่ออาบีเมเลค เรื่องบ่อน้ําที่ข้าราชการอาบีเมเลคยึดเอาไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 26, 'อาบีเมเลคตรัสว่า “เราไม่รู้ว่าใครทําอย่างนี้ ทั้งท่านก็มิได้บอกเรา เราก็ยังไม่ได้ยินเรื่องจนวันนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 27, 'อับราฮัมจึงนําแกะและวัวมาถวายแก่อาบีเมเลค ทั้งสองฝ่ายก็ทําพันธสัญญากัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 28, 'อับราฮัมได้แยกลูกแกะตัวเมียจากฝูงไว้ต่างหากเจ็ดตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 29, 'อาบีเมเลคตรัสถามอับราฮัมว่า “ลูกแกะตัวเมียเจ็ดตัวที่ท่านแยกไว้ต่างหากนั้นหมายความว่าอะไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 30, 'ท่านทูลว่า “ขอพระองค์รับลูกแกะตัวเมียเจ็ดตัวนี้จากมือข้าพระองค์ เพื่อจะได้เป็นพยานแก่ข้าพระองค์ว่า ข้าพระองค์ได้ขุดบ่อน้ํานี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 31, 'เหตุฉะนี้ท่านจึงเรียกที่นั้นว่า เบเออร์เชบา เพราะว่าทั้งสองได้ปฏิญาณกันไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 32, 'ทั้งสองกระทําพันธสัญญากันที่เบเออร์เชบาดังนี้แหละ แล้วอาบีเมเลคและฟีโคล์ผู้บัญชาการทหารของพระองค์ได้ลุกขึ้นแล้วก็กลับไปยังแผ่นดินของชาวฟีลิสเตีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 33, 'อับราฮัมปลูกต้นแทมริสก์ไว้ที่เบเออร์เชบา และนมัสการออกพระนามพระเยโฮวาห์พระเจ้านิรันดร์ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 34, 'อับราฮัมอาศัยอยู่ในแผ่นดินชาวฟีลิสเตียหลายวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 1, 'และต่อมาภายหลังเหตุการณ์เหล่านี้ พระเจ้าทรงลองใจอับราฮัม และตรัสกับท่านว่า “อับราฮัม” ท่านทูลว่า “ดูเถิด ข้าพระองค์อยู่ที่นี่ พระเจ้าข้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 2, 'พระองค์ตรัสว่า “จงพาบุตรชายของเจ้าคืออิสอัค บุตรชายคนเดียวของเจ้าผู้ที่เจ้ารักไปยังแผ่นดินโมริยาห์ และถวายเขาที่นั่นเป็นเครื่องเผาบูชา บนภูเขาลูกหนึ่งซึ่งเราจะบอกแก่เจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 3, 'อับราฮัมจึงลุกขึ้นแต่เช้ามืด ผูกอานลาของท่านพาคนใช้หนุ่มไปกับท่านด้วยสองคนกับอิสอัคบุตรชายของท่าน ท่านตัดฟืนสําหรับเครื่องเผาบูชา แล้วลุกขึ้นเดินทางไปยังที่ซึ่งพระเจ้าทรงตรัสแก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 4, 'พอถึงวันที่สามอับราฮัมเงยหน้าขึ้นแลเห็นที่นั้นแต่ไกล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 5, 'อับราฮัมจึงพูดกับคนใช้หนุ่มของท่านว่า “อยู่กับลาที่นี่เถิด เรากับเด็กชายจะเดินไปนมัสการที่โน้น แล้วจะกลับมาพบเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 6, 'อับราฮัมเอาฟืนสําหรับเครื่องเผาบูชาใส่บ่าอิสอัคบุตรชายของตน ถือไฟและมีดแล้วพ่อลูกไปด้วยกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 7, 'อิสอัคพูดกับอับราฮัมบิดาว่า “บิดาเจ้าข้า” และท่านตอบว่า “ลูกเอ๋ย พ่ออยู่ที่นี่” ลูกจึงว่า “นี่ไฟและฟืน แต่ลูกแกะสําหรับเครื่องเผาบูชาอยู่ที่ไหน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 8, 'อับราฮัมตอบว่า “ลูกเอ๋ย พระเจ้าจะทรงจัดเตรียมลูกแกะสําหรับพระองค์เองไว้ให้เป็นเครื่องเผาบูชา” พ่อลูกทั้งสองก็เดินต่อไปด้วยกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 9, 'เขาทั้งสองมาถึงที่ซึ่งพระเจ้าตรัสบอกท่านไว้ อับราฮัมก็สร้างแท่นบูชาที่นั่น เรียงฟืนเป็นระเบียบ แล้วมัดอิสอัคบุตรชายวางไว้บนแท่นบูชาบนฟืน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 10, 'แล้วอับราฮัมก็ยื่นมือจับมีดจะฆ่าบุตรชาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 11, 'แต่ทูตสวรรค์ของพระเยโฮวาห์เรียกท่านจากฟ้าสวรรค์ว่า “อับราฮัม อับราฮัม” และท่านตอบว่า “ข้าพระองค์อยู่ที่นี่ พระเจ้าข้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 12, 'และพระองค์ตรัสว่า “อย่าแตะต้องเด็กนั้นหรือกระทําอะไรแก่เขาเลย เพราะบัดนี้เรารู้แล้วว่าเจ้ายําเกรงพระเจ้า ด้วยเห็นว่าเจ้ามิได้หวงบุตรชายของเจ้า คือบุตรชายคนเดียวของเจ้าจากเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 13, 'อับราฮัมเงยหน้าขึ้นมองดู และดูเถิด ข้างหลังท่านมีแกะผู้ตัวหนึ่ง เขาของมันติดอยู่ในพุ่มไม้ทึบ อับราฮัมก็ไปจับแกะผู้ตัวนั้นมาถวายเป็นเครื่องเผาบูชาแทนบุตรชายของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 14, 'อับราฮัมจึงเรียกสถานที่นั้นว่า เยโฮวาห์ยิเรห์ อย่างที่เขาพูดกันทุกวันนี้ว่า “ที่ภูเขาของพระเยโฮวาห์นั้น พระองค์ทรงทอดพระเนตร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 15, 'ทูตสวรรค์ของพระเยโฮวาห์เรียกอับราฮัมครั้งที่สองมาจากฟ้าสวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 16, 'และตรัสว่า “พระเยโฮวาห์ตรัสว่า เราปฏิญาณโดยตัวเราเองว่าเพราะเจ้ากระทําอย่างนี้และมิได้หวงบุตรชายของเจ้า คือบุตรชายคนเดียวของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 17, 'เราจะอวยพรเจ้าแน่ เราจะทวีเชื้อสายของเจ้าให้มากขึ้น ดังดวงดาวในท้องฟ้า และดังเม็ดทรายบนฝั่งทะเล เชื้อสายของเจ้าจะได้ประตูเมืองศัตรูของเจ้าเป็นกรรมสิทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 18, 'ประชาชาติทั้งหลายทั่วโลกจะได้พรเพราะเชื้อสายของเจ้า เพราะว่าเจ้าได้เชื่อฟังเสียงของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 19, 'อับราฮัมจึงกลับไปหาคนใช้หนุ่มของท่าน เขาก็ลุกขึ้นแล้วพากันกลับไปยังเมืองเบเออร์เชบา อับราฮัมก็อาศัยอยู่ที่เบเออร์เชบา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 20, 'และต่อมาภายหลังเหตุการณ์เหล่านี้ มีคนมาบอกอับราฮัมว่า “ดูเถิด มิลคาห์บังเกิดบุตรให้แก่นาโฮร์น้องชายของท่านด้วยแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 21, 'คือฮูสบุตรหัวปี บูสน้องชายของเขา เคมูเอลบิดาของอารัม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 22, 'เคเสด ฮาโซ ปิลดาช ยิดลาฟ และเบธูเอล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 23, 'เบธูเอลให้กําเนิดบุตรสาวชื่อเรเบคาห์ ทั้งแปดนี้มิลคาห์บังเกิดให้นาโฮร์ น้องชายของอับราฮัม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 24, 'และภรรยาน้อยของเขาที่ชื่อเรอูมาห์ ก็ได้บังเกิดเตบาห์ กาฮัม ทาหาช และมาอาคาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 1, 'ซาราห์มีอายุหนึ่งร้อยยี่สิบเจ็ดปี ซาราห์มีชีวิตถึงอายุนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 2, 'แล้วซาราห์ก็สิ้นชีวิตที่เมืองคีริยาทอารบา คือเมืองเฮโบรน ในแผ่นดินคานาอัน อับราฮัมไว้ทุกข์ให้ซาราห์และร้องไห้คิดถึงนาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 3, 'อับราฮัมยืนขึ้นหน้าศพพูดกับลูกหลานของเฮทว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 4, '“ข้าพเจ้าเป็นคนต่างด้าวและเป็นคนมาอาศัยอยู่ท่ามกลางท่าน ขอท่านให้ที่ดินท่ามกลางท่านเป็นสุสาน เพื่อข้าพเจ้าจะได้ฝังผู้ตายของข้าพเจ้าให้พ้นสายตาไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 5, 'ลูกหลานของเฮทตอบอับราฮัมว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 6, '“นายเจ้าข้า โปรดฟังพวกเรา ท่านเป็นเจ้านายจากพระเจ้าท่ามกลางเรา ขอให้ฝังผู้ตายของท่านในอุโมงค์ฝังศพที่ดีที่สุดของเราเถิด ไม่มีผู้ใดในพวกเราที่จะหวงสุสานของเขาไว้ไม่ให้ท่าน หรือขัดขวางท่านมิให้ฝังผู้ตายของท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 7, 'อับราฮัมก็ลุกขึ้นกราบลงต่อหน้าลูกหลานของเฮทชาวแผ่นดินนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 8, 'และพูดกับพวกเขาว่า “ถ้าท่านยินยอมให้ข้าพเจ้าฝังผู้ตายของข้าพเจ้าให้พ้นสายตาไปแล้ว ขอฟังข้าพเจ้าเถิด และวิงวอนเอโฟรนบุตรชายโศหาร์เพื่อข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 9, 'ขอให้เขาให้ถ้ํามัคเป-ลาห์ ซึ่งเขาถือกรรมสิทธิ์นั้นแก่ข้าพเจ้า มันอยู่ที่ปลายนาของเขา ขอให้เขาขายให้ข้าพเจ้าเต็มตามราคาให้เป็นกรรมสิทธิ์สําหรับใช้เป็นสุสานท่ามกลางหมู่พวกท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 10, 'ฝ่ายเอโฟรนอาศัยอยู่ท่ามกลางลูกหลานของเฮท เอโฟรนคนฮิตไทต์จึงตอบอับราฮัมให้บรรดาลูกหลานของเฮทผู้ที่เข้าไปที่ประตูเมืองของเขาฟังว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 11, '“อย่าเลย นายเจ้าข้า โปรดฟังข้าพเจ้า ข้าพเจ้าให้นานั้นแก่ท่านและให้ถ้ําที่อยู่ในนานั้นแก่ท่าน ด้วยข้าพเจ้าให้แก่ท่านต่อหน้าลูกหลานประชาชนของข้าพเจ้า ขอเชิญฝังผู้ตายของท่านเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 12, 'อับราฮัมก็กราบลงต่อหน้าชาวแผ่นดินนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 13, 'และท่านพูดกับเอโฟรนให้ชาวแผ่นดินนั้นฟังว่า “แต่ถ้าท่านยินยอมให้แล้ว ขอฟังข้าพเจ้า ข้าพเจ้าจะจ่ายค่านานั้น ขอรับเงินจากข้าพเจ้าเถิด และข้าพเจ้าจะได้ฝังผู้ตายของข้าพเจ้าที่นั่น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 14, 'เอโฟรนตอบอับราฮัมว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 15, '“นายเจ้าข้า ขอฟังข้าพเจ้าเถิด ที่ดินแปลงนี้มีราคาเป็นเงินสี่ร้อยเชเขล สําหรับท่านกับข้าพเจ้าก็ไม่เท่าไร ฝังผู้ตายของท่านเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 16, 'อับราฮัมก็ฟังคําของเอโฟรน แล้วอับราฮัมก็ชั่งเงินให้เอโฟรนตามจํานวนที่เขาบอกให้ลูกหลานของเฮทฟังแล้ว คือเงินสี่ร้อยเชเขลตามน้ําหนักที่พวกพ่อค้าใช้กันในเวลานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 17, 'นาของเอโฟรนในมัคเป-ลาห์ ซึ่งอยู่หน้ามัมเร มีนากับถ้ําซึ่งอยู่ในนั้น และต้นไม้ทั้งสิ้นซึ่งอยู่ในนาตลอดทั่วบริเวณนั้น จึงได้ขาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 18, 'ให้แก่อับราฮัมเป็นกรรมสิทธิ์ต่อหน้าลูกหลานของเฮท คือต่อหน้าบรรดาผู้ที่เข้าไปที่ประตูเมืองของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 19, 'ต่อมาอับราฮัมก็ฝังศพนางซาราห์ภรรยาของตน ในถ้ําที่นามัคเป-ลาห์หน้ามัมเร คือเมืองเฮโบรน ในแผ่นดินคานาอัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 20, 'นาและถ้ําซึ่งอยู่ในนั้นลูกหลานของเฮทยอมขายให้แก่อับราฮัมเป็นกรรมสิทธิ์เพื่อใช้เป็นสุสาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 1, 'ฝ่ายอับราฮัมก็ชราแล้ว มีอายุมากทีเดียว และพระเยโฮวาห์ทรงอวยพระพรอับราฮัมทุกประการ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 2, 'อับราฮัมพูดกับคนใช้ของท่านที่มีอาวุโสที่สุดในบ้าน ผู้ดูแลทรัพย์สมบัติทุกอย่างของท่านว่า “เอามือเจ้าวางไว้ใต้ขาอ่อนของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 3, 'แล้วเราจะให้เจ้าปฏิญาณในพระนามพระเยโฮวาห์พระเจ้าแห่งฟ้าสวรรค์และพระเจ้าแห่งแผ่นดินโลก ว่าเจ้าจะไม่หาภรรยาให้บุตรชายของเราจากบุตรสาวของคนคานาอัน ที่เราอาศัยอยู่ท่ามกลางเขานี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 4, 'แต่เจ้าจะไปยังประเทศและหมู่ญาติของเราเพื่อหาภรรยาคนหนึ่งให้แก่อิสอัคบุตรชายของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 5, 'คนใช้ก็เรียนท่านว่า “หากว่าหญิงนั้นจะไม่เต็มใจมากับข้าพเจ้ายังแผ่นดินนี้ ถ้าเช่นนั้นข้าพเจ้ามิต้องนําบุตรชายของท่านกลับไปยังแผ่นดินซึ่งท่านจากมานั้นหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 6, 'อับราฮัมพูดกับเขาว่า “ระวังอย่าพาบุตรชายของเรากลับไปที่นั่นอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 7, 'พระเยโฮวาห์พระเจ้าแห่งฟ้าสวรรค์ ผู้ทรงนําเรามาจากบ้านบิดาเรา และจากแผ่นดินแห่งญาติของเรา พระองค์ตรัสกับเราและทรงปฏิญาณกับเราว่า ‘เราจะมอบแผ่นดินนี้ให้แก่เชื้อสายของเจ้า’ พระองค์จะทรงใช้ทูตสวรรค์ของพระองค์ไปข้างหน้าเจ้า เจ้าจงหาภรรยาคนหนึ่งให้บุตรชายของเราจากที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 8, 'ถ้าหญิงนั้นไม่เต็มใจมากับเจ้า เจ้าก็จะพ้นจากคําปฏิญาณของเรานี้ แต่เจ้าอย่าพาบุตรชายของเรากลับไปที่นั่นก็แล้วกัน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 9, 'คนใช้จึงเอามือของเขาวางใต้ขาอ่อนของอับราฮัมนายของตน และปฏิญาณต่อท่านตามเรื่องนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 10, 'คนใช้นําอูฐสิบตัวของนายมาแล้วออกเดินทางไป ด้วยว่าข้าวของทั้งสิ้นของนายเขาอยู่ในอํานาจของเขา เขาลุกขึ้นไปยังเมโสโปเตเมีย ถึงเมืองของนาโฮร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 11, 'เขาให้อูฐคุกเข่าลงที่ริมบ่อน้ําข้างนอกเมืองเวลาเย็น ซึ่งเป็นเวลาที่ผู้หญิงออกมาตักน้ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 12, 'เขาอธิษฐานว่า “โอ ข้าแต่พระเยโฮวาห์พระเจ้าของอับราฮัมนายของข้าพระองค์ ขอทรงประทานความสําเร็จแก่ข้าพระองค์ในวันนี้ และขอทรงสําแดงความเมตตาแก่อับราฮัมนายของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 13, 'ดูเถิด ข้าพระองค์กําลังยืนอยู่ที่ริมบ่อน้ํา และบรรดาบุตรสาวของชาวเมืองนี้กําลังออกมาตักน้ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 14, 'ขอให้หญิงสาวคนที่ข้าพระองค์จะพูดกับนางว่า ‘โปรดลดเหยือกของนางลงให้ข้าพเจ้าดื่มน้ํา’ และนางนั้นจะว่า ‘เชิญดื่มเถิดและข้าพเจ้าจะให้น้ําอูฐของท่านกินด้วย’ ให้คนนั้นเป็นคนที่พระองค์ทรงกําหนดสําหรับอิสอัคผู้รับใช้ของพระองค์ อย่างนี้ข้าพระองค์จะทราบได้ว่า พระองค์ทรงสําแดงความเมตตาแก่นายของข้าพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 15, 'และต่อมาเมื่อเขาอธิษฐานยังไม่ทันเสร็จ ดูเถิด เรเบคาห์ ผู้ที่เกิดแก่เบธูเอลบุตรชายของนางมิลคาห์ภรรยาของนาโฮร์น้องชายของอับราฮัม ก็แบกเหยือกน้ําของนางเดินออกมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 16, 'หญิงสาวนั้นงามมาก เป็นหญิงพรหมจารียังไม่มีชายใดร่วมรู้กับนาง นางก็ลงไปที่บ่อน้ําเติมน้ําเต็มเหยือกแล้วก็ขึ้นมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 17, 'คนใช้นั้นก็วิ่งไปต้อนรับนาง แล้วพูดว่า “ขอน้ําจากเหยือกของนางให้ข้าพเจ้าดื่มสักหน่อย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 18, 'นางตอบว่า “นายเจ้าข้า เชิญดื่มเถิด” แล้วนางก็รีบลดเหยือกน้ําของนางลงมาถือไว้แล้วให้เขาดื่ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 19, 'เมื่อให้เขาดื่มเสร็จแล้ว นางจึงว่า “ข้าพเจ้าจะตักน้ําให้อูฐของท่านกินจนอิ่มด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 20, 'นางรีบเทน้ําในเหยือกของนางใส่รางแล้ววิ่งไปตักน้ําที่บ่ออีก นางตักน้ําให้อูฐทั้งหมดของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 21, 'ชายนั้นเพ่งดูนางเงียบๆเพื่อตรึกตรองดูว่าพระเยโฮวาห์ทรงให้การเดินทางของตนบังเกิดผลหรือไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 22, 'และต่อมาเมื่ออูฐกินน้ําเสร็จแล้ว ชายนั้นก็ให้ตุ้มหูทองคําหนักครึ่งเชเขล และกําไลสําหรับข้อมือนางคู่หนึ่งทองหนักสิบเชเขล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 23, 'และพูดว่า “ขอบอกข้าพเจ้าว่านางเป็นบุตรสาวของใคร ในบ้านบิดาของนางนั้นมีที่ให้พวกเราพักอาศัยบ้างไหม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 24, 'นางตอบเขาว่า “ข้าพเจ้าเป็นบุตรสาวของเบธูเอลบุตรชายของนางมิลคาห์ซึ่งนางบังเกิดให้กับนาโฮร์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 25, 'นางพูดเสริมว่า “เรามีทั้งฟางและเสบียงพอ และมีที่ให้พักด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 26, 'ชายนั้นก็ก้มศีรษะลงนมัสการพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 27, 'และอธิษฐานว่า “สรรเสริญแด่พระเยโฮวาห์พระเจ้าของอับราฮัมนายของข้าพระองค์ ผู้มิได้ทรงทอดทิ้งความกรุณา และความจริงของพระองค์ต่อนาย ส่วนข้าพระองค์นั้นพระเยโฮวาห์ทรงนํามาตามทางจนถึงบ้านหมู่ญาติของนายข้าพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 28, 'แล้วหญิงสาวนั้นก็วิ่งไปบอกคนในครอบครัวของมารดาถึงเรื่องเหล่านี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 29, 'เรเบคาห์มีพี่ชายคนหนึ่งชื่อ ลาบัน ลาบันวิ่งไปหาชายคนนั้นที่บ่อน้ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 30, 'และต่อมาเมื่อท่านเห็นตุ้มหูและกําไลที่ข้อมือน้องสาว และเมื่อท่านได้ยินคําของเรเบคาห์น้องสาวว่า “ชายนั้นพูดกับข้าพเจ้าอย่างนี้” ท่านก็ไปหาชายนั้น และดูเถิด เขากําลังยืนอยู่กับอูฐที่บ่อน้ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 31, 'ท่านพูดว่า “ท่านผู้รับพระพรของพระเยโฮวาห์ เชิญเข้ามาเถิด ท่านยืนอยู่ข้างนอกทําไม เพราะข้าพเจ้าเตรียมบ้านและเตรียมที่สําหรับอูฐแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 32, 'ชายนั้นจึงเข้าไปในบ้าน ลาบันก็แก้อูฐของเขา ให้ฟางและอาหารสําหรับอูฐ ให้น้ําล้างเท้าเขาและคนที่มากับเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 33, 'แล้วจัดอาหารมาเลี้ยงเขา แต่เขาว่า “ข้าพเจ้าจะไม่รับประทาน จนกว่าข้าพเจ้าจะพูดถึงธุระที่ข้าพเจ้าได้รับมอบหมายมานั้นให้ท่านฟังเสียก่อน” ลาบันก็ว่า “เชิญพูดเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 34, 'เขาจึงพูดว่า “ข้าพเจ้าเป็นคนใช้ของอับราฮัม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 35, 'พระเยโฮวาห์ทรงอวยพระพรแก่นายข้าพเจ้าอย่างมากมาย ท่านก็เจริญขึ้น และพระองค์ทรงประทานฝูงแพะแกะ และฝูงวัว เงินและทอง คนใช้ชายหญิง อูฐและลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 36, 'และนางซาราห์ภรรยานายข้าพเจ้าได้บังเกิดบุตรชายคนหนึ่งให้แก่นายเมื่อนางแก่แล้ว และนายก็ยกทรัพย์สมบัติทั้งหมดให้บุตร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 37, 'นายให้ข้าพเจ้าปฏิญาณว่า ‘เจ้าอย่าหาภรรยาให้แก่บุตรชายของเราจากบุตรสาวของคนคานาอัน ซึ่งเราอาศัยอยู่ในแผ่นดินของเขานี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 38, 'แต่เจ้าจงไปยังบ้านบิดาของเราและไปยังหมู่ญาติของเรา และหาภรรยาคนหนึ่งให้แก่บุตรชายของเรา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 39, 'ข้าพเจ้าพูดกับนายว่า ‘หญิงนั้นอาจจะไม่ยอมมากับข้าพเจ้า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 40, 'แต่ท่านพูดกับข้าพเจ้าว่า ‘พระเยโฮวาห์ผู้ซึ่งเราดําเนินอยู่ต่อพระองค์จะทรงใช้ทูตสวรรค์ของพระองค์ไปกับเจ้า และให้ทางของเจ้าบังเกิดผล และเจ้าจะหาภรรยาคนหนึ่งให้บุตรชายของเราจากหมู่ญาติของเรา และจากบ้านบิดาของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 41, 'แล้วเจ้าจะพ้นจากคําปฏิญาณของเรา เมื่อเจ้ามาถึงหมู่ญาติของเราแล้ว ถ้าเขาไม่ยอมให้หญิงนั้น เจ้าก็พ้นจากคําปฏิญาณของเรา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 42, 'วันนี้ข้าพเจ้ามาถึงบ่อน้ําและทูลว่า ‘โอ ข้าแต่พระเยโฮวาห์พระเจ้าของอับราฮัมนายของข้าพระองค์ ถ้าบัดนี้พระองค์ทรงโปรดให้ทางที่ข้าพระองค์ไปนั้นเกิดผล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 43, 'ดูเถิด ข้าพระองค์กําลังยืนอยู่ที่บ่อน้ํา และต่อมาเมื่อสาวพรหมจารีออกมาตักน้ํา และข้าพระองค์พูดกับนางด้วยว่า “ขอน้ําให้ข้าพเจ้าดื่มจากเหยือกน้ําของนางสักหน่อย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 44, 'และนางจะตอบข้าพระองค์ว่า “เชิญดื่มเถิด และข้าพเจ้าจะตักน้ําให้อูฐของท่านด้วย” ให้ผู้นั้นเป็นหญิงที่พระเยโฮวาห์ทรงกําหนดตัวไว้สําหรับบุตรชายของนายข้าพระองค์’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 45, 'เมื่อข้าพเจ้าอธิษฐานในใจไม่ทันขาดคํา ดูเถิด นางเรเบคาห์แบกเหยือกน้ําของนางเดินออกมา นางลงไปตักน้ําที่บ่อน้ํา ข้าพเจ้าพูดกับนางว่า ‘ขอน้ําให้ข้าพเจ้าดื่มหน่อย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 46, 'นางก็รีบลดเหยือกน้ําจากบ่าของนางและว่า ‘เชิญดื่มเถิด แล้วข้าพเจ้าจะให้น้ําแก่อูฐของท่านด้วย’ ข้าพเจ้าจึงดื่ม และนางก็ตักน้ําให้อูฐกินด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 47, 'แล้วข้าพเจ้าถามนางว่า ‘นางเป็นบุตรสาวของใคร’ นางตอบว่า ‘เป็นบุตรสาวของเบธูเอลบุตรชายของนาโฮร์ ซึ่งนางมิลคาห์กําเนิดให้แก่เขา’ ข้าพเจ้าจึงใส่ตุ้มหูที่หน้าของนางแล้วสวมกําไลที่ข้อมือนาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 48, 'แล้วข้าพเจ้าก็ก้มศีรษะลงนมัสการพระเยโฮวาห์ และถวายสรรเสริญแด่พระเยโฮวาห์พระเจ้าของอับราฮัมนายข้าพเจ้า ผู้ทรงนําข้าพเจ้ามาตามทางที่ถูก เพื่อหาบุตรสาวของน้องชายนายให้บุตรชายของนาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 49, 'บัดนี้ถ้าท่านยอมแสดงความเมตตาและจริงใจต่อนายข้าพเจ้าแล้ว ขอกรุณาบอกข้าพเจ้า ถ้ามิฉะนั้นก็ขอบอกข้าพเจ้า เพื่อข้าพเจ้าจะหันไปทางขวาหรือซ้าย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 50, 'ลาบันและเบธูเอลจึงตอบว่า “สิ่งนี้มาจากพระเยโฮวาห์ เราจะพูดดีหรือร้ายกับท่านก็ไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 51, 'ดูเถิด เรเบคาห์ก็อยู่ต่อหน้าท่าน พานางไปเถิด และให้นางเป็นภรรยาบุตรชายนายของท่านดังที่พระเยโฮวาห์ตรัสแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 52, 'และต่อมาเมื่อคนใช้ของอับราฮัมได้ยินถ้อยคําของท่านทั้งสอง ก็กราบลงถึงดินนมัสการพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 53, 'แล้วคนใช้ก็นําเอาเครื่องเงินและเครื่องทอง พร้อมกับเสื้อผ้ามอบให้แก่เรเบคาห์ เขายังมอบของอันมีค่าให้แก่พี่ชายและมารดาของนางด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 54, 'แล้วพวกเขาก็รับประทานและดื่ม คือเขากับคนที่มากับเขา และค้างคืนที่นั่น และพวกเขาลุกขึ้นในเวลาเช้า คนใช้นั้นก็กล่าวว่า “ขอให้ข้าพเจ้ากลับไปหานายข้าพเจ้าเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 55, 'พี่ชายและมารดาของนางว่า “ขอให้หญิงสาวอยู่กับเราสักหน่อยก่อน อย่างน้อยสักสิบวันแล้วนางจะไปก็ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 56, 'แต่ชายนั้นพูดกับพวกเขาว่า “อย่าหน่วงข้าพเจ้าไว้เลย เพราะพระเยโฮวาห์ทรงให้ทางของข้าพเจ้าเกิดผลแล้ว ขอให้ข้าพเจ้าออกเดินทางเพื่อข้าพเจ้าจะได้กลับไปหานายข้าพเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 57, 'พวกเขาว่า “เราจะเรียกหญิงสาวมาถามดู”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 58, 'พวกเขาก็เรียกเรเบคาห์มาหา และพูดกับนางว่า “เจ้าจะไปกับชายคนนี้หรือไม่” นางตอบว่า “ข้าพเจ้าจะไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 59, 'พวกเขาจึงส่งเรเบคาห์น้องสาวกับพี่เลี้ยงของนางไปพร้อมกับคนใช้ของอับราฮัม และคนของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 60, 'พวกเขาอวยพรเรเบคาห์ และกล่าวแก่นางว่า “น้องสาวเอ๋ย ขอให้เจ้าเป็นมารดาคนนับแสนนับล้าน และขอให้เชื้อสายของเจ้าได้ประตูเมืองของคนที่เกลียดชังเจ้าเป็นกรรมสิทธิ์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 61, 'แล้วเรเบคาห์และเหล่าสาวใช้ของนางก็ขึ้นอูฐไปกับชายนั้น คนใช้ก็พาเรเบคาห์ไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 62, 'ฝ่ายอิสอัคมาจากบ่อน้ําลาไฮรอย เพราะท่านไปอาศัยอยู่ทางใต้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 63, 'เวลาเย็นอิสอัคออกไปไตร่ตรองที่ทุ่งนาและท่านก็เงยหน้าขึ้นมองไป และดูเถิด มีอูฐเดินมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 64, 'เรเบคาห์เงยหน้าขึ้น เมื่อแลเห็นอิสอัคนางก็ลงจากอูฐ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 65, 'เพราะนางได้พูดกับคนใช้นั้นว่า “ชายคนโน้นที่กําลังเดินผ่านทุ่งนามาหาเรานั้นคือใคร” คนใช้นั้นตอบว่า “นายของข้าพเจ้าเอง” นางจึงหยิบผ้าคลุมหน้ามาคลุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 66, 'คนใช้บอกให้อิสอัคทราบทุกอย่างที่เขาได้กระทําไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 67, 'อิสอัคก็พานางเข้ามาในเต็นท์ของนางซาราห์มารดาของท่านและรับเรเบคาห์ไว้ นางก็เป็นภรรยาของท่าน และท่านก็รักนาง อิสอัคก็ได้รับความปลอบประโลมภายหลังที่มารดาของท่านสิ้นชีวิตแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 1, 'อับราฮัมได้ภรรยาอีกคนหนึ่งชื่อเคทูราห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 2, 'นางก็คลอดบุตรให้แก่ท่านชื่อศิมราน โยกชาน เมดาน มีเดียน อิชบากและชูอาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 3, 'โยกชานให้กําเนิดบุตรชื่อเชบาและเดดาน บุตรชายของเดดาน คืออัสชูริม เลทูชิมและเลอุมมิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 4, 'บุตรชายของมีเดียนคือ เอฟาห์ เอเฟอร์ ฮาโนค อาบีดาและเอลดาอาห์ ทั้งหมดนี้เป็นลูกหลานของนางเคทูราห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 5, 'อับราฮัมได้มอบทรัพย์สมบัติทั้งหมดแก่อิสอัค');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 6, 'แต่อับราฮัมให้ของขวัญแก่บุตรชายทั้งหลายของพวกภรรยาน้อยของท่าน และให้พวกเขาแยกไปจากอิสอัคบุตรชายของท่าน ไปทางทิศตะวันออกยังประเทศตะวันออก เมื่อท่านยังมีชีวิตอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 7, 'อายุแห่งชีวิตของอับราฮัม คือหนึ่งร้อยเจ็ดสิบห้าปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 8, 'อับราฮัมสิ้นลมหายใจเมื่อแก่หง่อมแล้ว และเป็นคนชรามีอายุมาก และถูกรวบรวมไว้กับบรรพบุรุษของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 9, 'อิสอัคและอิชมาเอลบุตรชายของท่านก็ฝังท่านไว้ในถ้ํามัคเป-ลาห์ ในนาของเอโฟรนบุตรชายของโศหาร์คนฮิตไทต์ซึ่งอยู่หน้ามัมเร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 10, 'เป็นนาที่อับราฮัมซื้อมาจากลูกหลานของเฮท เขาก็ฝังอับราฮัมไว้ที่นั่น อยู่กับซาราห์ภรรยาของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 11, 'และต่อมาหลังจากที่อับราฮัมสิ้นชีวิตแล้ว พระเจ้าทรงอวยพระพรแก่อิสอัคบุตรชายของท่าน อิสอัคอาศัยอยู่ริมบ่อน้ําลาไฮรอย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 12, 'ต่อไปนี้เป็นพงศ์พันธุ์ของอิชมาเอล บุตรชายของอับราฮัม ซึ่งนางฮาการ์คนอียิปต์สาวใช้ของนางซาราห์กําเนิดให้แก่อับราฮัม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 13, 'ต่อไปนี้เป็นชื่อบรรดาบุตรชายของอิชมาเอล ตามชื่อ ตามพงศ์พันธุ์ คือเนบาโยทเป็นบุตรหัวปีของอิชมาเอล เคดาร์ อัดบีเอล มิบสัม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 14, 'มิชมา ดูมาห์ มัสสา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 15, 'ฮาดาร์ เทมา เยทูร์ นาฟิชและเคเดมาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 16, 'คนเหล่านี้เป็นบุตรชายของอิชมาเอล ชื่อเหล่านี้เป็นชื่อของพวกเขาตามเมือง และตามค่ายของเขา เจ้านายสิบสองคนตามตระกูลของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 17, 'อายุแห่งชีวิตของอิชมาเอล คือหนึ่งร้อยสามสิบเจ็ดปี ท่านสิ้นลมหายใจและถูกรวบรวมไว้กับบรรพบุรุษของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 18, 'พวกเขาอาศัยอยู่ตั้งแต่เมืองฮาวิลาห์จนถึงเมืองชูร์ ซึ่งอยู่หน้าอียิปต์ไปทางทิศแผ่นดินอัสซีเรีย และเขาสิ้นชีวิตอยู่ตรงหน้าบรรดาพี่น้องของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 19, 'ต่อไปนี้เป็นพงศ์พันธุ์ของอิสอัคบุตรชายของอับราฮัม คืออับราฮัมให้กําเนิดบุตรชื่ออิสอัค');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 20, 'อิสอัคมีอายุสี่สิบปีเมื่อท่านได้ภรรยาคือ เรเบคาห์บุตรสาวของเบธูเอลคนซีเรียชาวเมืองปัดดานอารัม น้องสาวของลาบันคนซีเรีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 21, 'อิสอัคอธิษฐานต่อพระเยโฮวาห์เพื่อภรรยาของท่าน เพราะนางเป็นหมัน พระเยโฮวาห์ประทานตามคําอธิษฐานของท่าน เรเบคาห์ภรรยาของท่านก็ตั้งครรภ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 22, 'เด็กก็เบียดเสียดกันอยู่ในครรภ์ของนาง นางจึงพูดว่า “ถ้าเป็นเช่นนี้ ข้าพเจ้าจะทําอะไรดี” นางจึงไปทูลถามพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 23, 'พระเยโฮวาห์ตรัสกับนางว่า “ชนสองชาติอยู่ในครรภ์ของเจ้า และประชาชนสองพวกที่เกิดจากบั้นเอวของเจ้าจะต้องแยกกัน พวกหนึ่งจะมีกําลังมากกว่าอีกพวกหนึ่ง พี่จะปรนนิบัติน้อง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 24, 'เมื่อกําหนดคลอดของนางมาถึงแล้ว ดูเถิด มีลูกแฝดอยู่ในครรภ์ของนาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 25, 'คนแรกคลอดออกมาตัวแดงมีขนอยู่ทั่วตัวหมด เขาจึงตั้งชื่อว่า เอซาว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 26, 'ภายหลังน้องชายของเขาก็คลอดออกมา มือของเขาจับส้นเท้าของเอซาวไว้ เขาจึงตั้งชื่อว่า ยาโคบ เมื่อนางคลอดลูกแฝดนั้น อิสอัคมีอายุได้หกสิบปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 27, 'เด็กชายทั้งสองนั้นโตขึ้น เอซาวก็เป็นพรานที่ชํานาญ เป็นชาวทุ่ง ฝ่ายยาโคบเป็นคนเงียบๆอาศัยอยู่ในเต็นท์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 28, 'อิสอัครักเอซาว เพราะท่านรับประทานเนื้อที่เขาล่ามา แต่นางเรเบคาห์รักยาโคบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 29, 'และยาโคบต้มผักอยู่ เอซาวกลับมาจากท้องทุ่งแล้วรู้สึกอ่อนกําลัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 30, 'เอซาวพูดกับยาโคบว่า “ขอผักแดงนั้นให้ข้ากินเถิด เพราะเราอ่อนกําลัง” เพราะฉะนั้นเขาจึงได้ชื่อว่า เอโดม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 31, 'ยาโคบว่า “ขายสิทธิบุตรหัวปีของพี่ให้ข้าพเจ้าก่อนในวันนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 32, 'เอซาวว่า “ดูเถิด ข้ากําลังจะตายอยู่แล้ว สิทธิบุตรหัวปีจะเป็นประโยชน์อะไรแก่ข้าเล่า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 33, 'ยาโคบว่า “ปฏิญาณให้ข้าพเจ้าก่อนในวันนี้” เอซาวจึงปฏิญาณให้กับเขา และขายสิทธิบุตรหัวปีของตนแก่ยาโคบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 34, 'ยาโคบจึงให้ขนมปังและถั่วแดงต้มแก่เอซาว เขาก็กินและดื่ม แล้วลุกไป ดังนี้เอซาวก็ดูหมิ่นสิทธิบุตรหัวปีของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 1, 'เกิดกันดารอาหารในแผ่นดินนั้น นอกเหนือจากการกันดารอาหารครั้งก่อนในสมัยอับราฮัม และอิสอัคไปหาอาบีเมเลคกษัตริย์แห่งชาวฟีลิสเตียที่เมืองเก-ราร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 2, 'พระเยโฮวาห์ทรงปรากฏแก่ท่านและตรัสว่า “อย่าลงไปอียิปต์เลย จงอาศัยในแผ่นดินซึ่งเราจะบอกเจ้าเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 3, 'จงอาศัยอยู่ในแผ่นดินนี้ แล้วเราจะอยู่กับเจ้าและอวยพรเจ้า เพราะว่าเราจะให้แผ่นดินเหล่านี้ทั้งหมดแก่เจ้าและแก่เชื้อสายของเจ้า เราจะทําให้คําปฏิญาณซึ่งเราได้ปฏิญาณไว้กับอับราฮัมบิดาของเจ้านั้นสําเร็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 4, 'เราจะทวีเชื้อสายของเจ้าให้มากขึ้นดังดาวบนฟ้าและจะให้แผ่นดินเหล่านี้ทั้งหมดแก่เชื้อสายของเจ้า ประชาชาติทั้งหลายในโลกจะได้รับพรก็เพราะเชื้อสายของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 5, 'เพราะว่าอับราฮัมได้เชื่อฟังเสียงของเราและได้รักษาคํากําชับของเรา บัญญัติของเรา กฎเกณฑ์ของเรา และราชบัญญัติของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 6, 'อิสอัคจึงอาศัยอยู่ในเมืองเก-ราร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 7, 'คนเมืองนั้นจึงถามท่านเรื่องภรรยาของท่าน ท่านจึงว่า “เธอเป็นน้องสาวของข้าพเจ้า” เพราะท่านกลัวที่จะพูดว่า “เธอเป็นภรรยาของข้าพเจ้า” คิดไปว่า “มิฉะนั้นแล้วคนเมืองนี้จะฆ่าข้าพเจ้าเพื่อแย่งเอาเรเบคาห์” เพราะว่านางมีรูปงาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 8, 'และต่อมาเมื่อท่านอยู่ที่นั่นนานแล้ว อาบีเมเลคกษัตริย์ชาวฟีลิสเตียทอดพระเนตรตามช่องพระแกล และดูเถิด เห็นอิสอัคกําลังหยอกเล่นกับเรเบคาห์ภรรยาของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 9, 'อาบีเมเลคจึงเรียกอิสอัคมาเฝ้า และตรัสว่า “ดูเถิด นางเป็นภรรยาของเจ้าแน่แล้ว ทําไมเจ้าจึงพูดว่า ‘เธอเป็นน้องสาวของข้าพระองค์’” อิสอัคทูลพระองค์ว่า “เพราะข้าพระองค์คิดว่า ‘มิฉะนั้นข้าจะตายเพราะนาง’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 10, 'อาบีเมเลคตรัสว่า “ท่านทําอะไรแก่พวกเรา ดังนี้ประชาชนคนหนึ่งอาจจะเข้าไปนอนกับภรรยาของเจ้าง่ายๆ แล้วเจ้าจะนําความผิดมาสู่พวกเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 11, 'อาบีเมเลคจึงทรงรับสั่งประชาชนทั้งปวงว่า “ผู้ใดแตะต้องชายคนนี้หรือภรรยาของเขาจะต้องถูกประหารชีวิตเป็นแน่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 12, 'อิสอัคได้หว่านพืชในแผ่นดินนั้น ในปีเดียวกันนั้นก็เก็บผลได้หนึ่งร้อยเท่า พระเยโฮวาห์ทรงอวยพระพรแก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 13, 'อิสอัคก็จําเริญมีกําไรทวียิ่งขึ้นจนท่านเป็นคนมั่งมีมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 14, 'ด้วยว่าท่านมีฝูงแพะแกะ และฝูงวัวเป็นกรรมสิทธิ์และมีบริวารมากมาย ชาวฟีลิสเตียจึงอิจฉาท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 15, 'ฝ่ายชาวฟีลิสเตียได้อุดและเอาดินถมบ่อทุกบ่อ ซึ่งคนใช้ของบิดาท่านขุดไว้ในสมัยอับราฮัมบิดาของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 16, 'อาบีเมเลคตรัสกับอิสอัคว่า “ไปเสียจากเราเถิด เพราะท่านมีกําลังมากกว่าพวกเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 17, 'อิสอัคจึงออกจากที่นั่น ไปตั้งเต็นท์อยู่ที่หุบเขาเก-ราร์และอาศัยอยู่ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 18, 'อิสอัคขุดบ่อน้ําซึ่งขุดไว้ในสมัยของอับราฮัมบิดาของท่านอีก เพราะหลังจากที่อับราฮัมได้สิ้นชีพแล้วชาวฟีลิสเตียได้อุดเสีย แล้วท่านก็ตั้งชื่อตามชื่อที่บิดาของท่านตั้งไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 19, 'และคนใช้ของอิสอัคขุดในหุบเขาและพบบ่อน้ําพุพลุ่งขึ้นมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 20, 'คนเลี้ยงสัตว์ของเมืองเก-ราร์ก็มาทะเลาะกับคนเลี้ยงสัตว์ของอิสอัคอ้างว่า “น้ํานั้นเป็นของเรา” ท่านจึงเรียกชื่อบ่อนั้นว่า เอเสก เพราะเขาทั้งหลายมาทะเลาะกับท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 21, 'แล้วพวกเขาก็ขุดบ่อน้ําอีกบ่อหนึ่ง และทะเลาะกันเรื่องบ่อนั้นด้วย ท่านจึงเรียกชื่อบ่อนั้นว่า สิตนาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 22, 'ท่านย้ายจากที่นั่นไปขุดอีกบ่อหนึ่ง แล้วเขาก็มิได้ทะเลาะกันเรื่องบ่อนั้น ท่านจึงเรียกชื่อบ่อนั้นว่า เรโหโบท ท่านกล่าวว่า “เพราะบัดนี้พระเยโฮวาห์ทรงประทานที่อยู่แก่เรา และเราจะทวีมากขึ้นในแผ่นดินนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 23, 'และท่านก็ออกจากที่นั่นไปยังเมืองเบเออร์เชบา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 24, 'พระเยโฮวาห์ทรงปรากฏแก่ท่านในคืนเดียวกันนั้น ตรัสว่า “เราเป็นพระเจ้าของอับราฮัม บิดาของเจ้า อย่ากลัวเลย ด้วยว่าเราอยู่กับเจ้าและจะอวยพรเจ้า และทวีเชื้อสายของเจ้าให้มากขึ้นเพราะเห็นแก่อับราฮัมผู้รับใช้ของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 25, 'ท่านจึงสร้างแท่นบูชาที่นั่น และนมัสการออกพระนามพระเยโฮวาห์ และตั้งเต็นท์ของท่านที่นั่น แล้วคนใช้ของอิสอัคขุดบ่อน้ําที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 26, 'ฝ่ายอาบีเมเลคออกจากเมืองเก-ราร์พร้อมกับอาฮุสซัทสหายคนหนึ่งของพระองค์ กับฟีโคล์ผู้บัญชาการทหารของพระองค์ไปหาท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 27, 'อิสอัคทูลถามเขาทั้งหลายว่า “ไฉนท่านจึงมาหาข้าพเจ้าเมื่อท่านเกลียดชังข้าพเจ้าและขับไล่ข้าพเจ้าไปจากท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 28, 'พวกเขาตอบว่า “เราเห็นชัดเจนแล้วว่าพระเยโฮวาห์ทรงสถิตกับท่าน เราจึงว่า ขอให้กระทําปฏิญาณระหว่างท่านและเราทั้งหลาย และขอให้เรากระทําพันธสัญญากับท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 29, 'เพื่อว่าท่านจะไม่ทําอันตรายแก่เรา ดังที่เรามิได้แตะต้องท่านและไม่ได้กระทําสิ่งใดแก่ท่านเว้นแต่การดี และได้ส่งท่านไปอย่างสันติ บัดนี้ท่านเป็นผู้ที่พระเยโฮวาห์ทรงอวยพระพร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 30, 'ท่านจึงจัดการเลี้ยงให้แก่พวกเขา และเขาก็ได้กินและดื่ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 31, 'ครั้นรุ่งเช้าทั้งสองฝ่ายก็ตื่นแต่เช้ามืด กระทําปฏิญาณต่อกัน และอิสอัคไปส่งพวกเขา พวกเขาก็จากท่านไปอย่างสันติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 32, 'และต่อมาในวันนั้นเองคนใช้ของอิสอัคมาบอกท่านถึงเรื่องบ่อน้ําซึ่งเขาได้ขุดและกล่าวแก่ท่านว่า “เราพบน้ําแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 33, 'ท่านเรียกบ่อนั้นว่า เชบา เมืองนั้นจึงมีชื่อว่า เบเออร์เชบา จนทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 34, 'เอซาวมีอายุสี่สิบปีเมื่อท่านรับยูดิธบุตรสาวของเบเออรีคนฮิตไทต์และบาเสมัทบุตรสาวของเอโลนคนฮิตไทต์เป็นภรรยา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 35, 'หญิงเหล่านั้นทําให้อิสอัคและเรเบคาห์มีใจโศกเศร้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 1, 'และต่อมาเมื่ออิสอัคชราแล้ว ตามัวจนมองไม่เห็น ท่านก็เรียกเอซาวบุตรชายคนโตของท่านมาและกล่าวแก่เขาว่า “ลูกเอ๋ย” เขาตอบว่า “ดูเถิด ข้าพเจ้าอยู่ที่นี่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 2, 'ท่านว่า “ดูเถิด บัดนี้พ่อแก่แล้ว จะถึงวันตายเมื่อไรก็ไม่รู้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 3, 'ฉะนั้นบัดนี้เจ้าจงเอาอาวุธของเจ้า คือแล่งธนูและคันธนูออกไปที่ท้องทุ่ง หาเนื้อมาให้พ่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 4, 'และจัดอาหารอร่อยอย่างที่พ่อชอบนั้น และนํามาให้พ่อกิน เพื่อจิตวิญญาณของพ่อจะได้อวยพรแก่เจ้าก่อนพ่อตาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 5, 'เมื่ออิสอัคพูดกับเอซาวบุตรชายนั้น นางเรเบคาห์ได้ยิน เอซาวก็ออกไปท้องทุ่งเพื่อล่าเนื้อมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 6, 'นางเรเบคาห์จึงพูดกับยาโคบบุตรชายของนางว่า “ดูเถิด แม่ได้ยินบิดาของเจ้าพูดกับเอซาวพี่ชายของเจ้าว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 7, '‘จงนําเนื้อมาให้พ่อและจัดอาหารอร่อยให้พ่อกิน และเราจะอวยพรเจ้าต่อพระพักตร์พระเยโฮวาห์ก่อนพ่อตาย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 8, 'เพราะฉะนั้น ลูกเอ๋ย บัดนี้จงฟังเสียงของแม่ตามที่แม่สั่งเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 9, 'บัดนี้ไปที่ฝูงแพะแกะ นําลูกแพะดีๆสองตัวมาให้แม่ แม่จะเอามันปรุงอาหารอร่อยให้บิดาเจ้าอย่างที่ท่านชอบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 10, 'และเจ้าจะต้องนําไปให้บิดาเจ้ารับประทาน เพื่อว่าท่านจะอวยพรเจ้าก่อนท่านสิ้นชีวิต”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 11, 'ยาโคบพูดกับนางเรเบคาห์มารดาของตนว่า “ดูเถิด เอซาวพี่ชายของข้าพเจ้าเป็นคนมีขนดก และข้าพเจ้าเป็นคนเกลี้ยงเกลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 12, 'บิดาของข้าพเจ้าคงจะคลําตัวข้าพเจ้า และข้าพเจ้าจะดูเหมือนว่าเป็นผู้หลอกลวงท่าน แล้วข้าพเจ้าจะนําการสาปแช่งมาเหนือข้าพเจ้าเอง หาใช่นําพรมาไม่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 13, 'มารดาของเขาพูดกับเขาว่า “ลูกเอ๋ย ขอให้การสาปแช่งของเจ้าตกอยู่กับแม่เถิด ฟังเสียงของแม่เท่านั้น ไปเอาลูกแพะมาให้แม่เถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 14, 'เขาจึงไปจับเอามาให้มารดาของตน มารดาของเขาได้จัดอาหารอร่อยอย่างที่บิดาของเขาชอบนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 15, 'แล้วนางเรเบคาห์นําเสื้ออย่างดีที่สุดของเอซาว บุตรชายคนโตของนาง ซึ่งอยู่กับนางในเรือนมาสวมให้ยาโคบบุตรชายคนเล็กของนาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 16, 'นางเอาหนังลูกแพะหุ้มมือและคอที่เกลี้ยงเกลาของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 17, 'แล้วนางก็มอบอาหารอร่อยและขนมปัง ซึ่งนางจัดทํานั้นไว้ในมือของยาโคบบุตรชายของนาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 18, 'เขาจึงเข้าไปหาบิดาของตนและพูดว่า “บิดาเจ้าข้า” และท่านว่า “พ่ออยู่นี่ ลูกเอ๋ย เจ้าคือใคร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 19, 'ยาโคบตอบบิดาของตนว่า “ลูกเป็นเอซาวบุตรหัวปีของท่าน ลูกทําตามที่ท่านสั่งลูกแล้ว เชิญลุกขึ้นนั่งรับประทานเนื้อที่ลูกหามาเถิด เพื่อจิตวิญญาณของท่านจะได้อวยพรแก่ลูก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 20, 'แต่อิสอัคพูดกับบุตรชายของตนว่า “ลูกเอ๋ย เจ้าทําอย่างไรจึงพบมันเร็วนัก” บุตรจึงตอบว่า “เพราะว่าพระเยโฮวาห์พระเจ้าของท่านนํามันมาให้แก่ลูก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 21, 'แล้วอิสอัคจึงพูดกับยาโคบว่า “ลูกเอ๋ย มาใกล้ๆ พ่อจะได้คลําดูเจ้า เพื่อจะได้รู้ว่าเจ้าเป็นเอซาวบุตรชายของพ่อแน่หรือไม่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 22, 'ยาโคบจึงเข้าไปใกล้อิสอัคบิดาของตน อิสอัคคลําตัวเขาแล้วพูดว่า “เสียงก็เป็นเสียงของยาโคบ แต่มือเป็นมือของเอซาว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 23, 'ท่านก็ไม่ได้สังเกต เพราะมือของเขามีขนดกเหมือนมือเอซาวพี่ชายของเขา ท่านจึงอวยพรแก่เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 24, 'ท่านถามว่า “เจ้าเป็นเอซาวบุตรชายของพ่อจริงหรือ” เขาตอบว่า “ใช่ครับ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 25, 'ท่านจึงว่า “นําแกงมาให้พ่อ พ่อจะได้กินเนื้อที่บุตรชายของพ่อหามา เพื่อจิตวิญญาณของพ่อจะอวยพรเจ้า” ยาโคบจึงนํามันมาให้ท่าน ท่านก็รับประทาน ยาโคบนําน้ําองุ่นมาให้ท่านและท่านก็ดื่ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 26, 'แล้วอิสอัคบิดาของเขาจึงพูดกับเขาว่า “ลูกเอ๋ย เข้ามาใกล้และจุบพ่อ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 27, 'เขาจึงเข้ามาใกล้และจุบท่าน และท่านก็ดมกลิ่นที่เสื้อของเขา และอวยพรเขาว่า “ดูซิ กลิ่นลูกชายข้าเหมือนกลิ่นท้องทุ่ง ซึ่งพระเยโฮวาห์ทรงอวยพระพร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 28, 'ดังนั้นขอพระเจ้าทรงประทานน้ําค้างจากฟ้าแก่เจ้า และประทานความอุดมสมบูรณ์ของแผ่นดินทั้งข้าวและน้ําองุ่นมากมายแก่เจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 29, 'ขอให้ชนชาติทั้งหลายรับใช้เจ้า และให้ประชาชาติกราบไหว้เจ้า ขอให้เป็นเจ้านายเหนือพี่น้อง และบุตรชายมารดาของเจ้ากราบไหว้เจ้า ผู้ใดสาปแช่งเจ้าก็ขอให้ผู้นั้นถูกสาปและผู้ใดอวยพรเจ้าก็ขอให้ผู้นั้นได้รับพร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 30, 'และต่อมาพออิสอัคอวยพรยาโคบเสร็จแล้ว เมื่อยาโคบพึ่งออกไปจากหน้าอิสอัคบิดา เอซาวพี่ชายก็กลับจากการล่าเนื้อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 31, 'และเขาเตรียมอาหารอร่อยนํามาให้บิดาด้วย และพูดกับบิดาว่า “ขอท่านลุกขึ้นรับประทานเนื้อที่ลูกชายหามา เพื่อจิตวิญญาณของท่านจะได้อวยพรลูก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 32, 'อิสอัคบิดาพูดกับเขาว่า “เจ้าคือใคร” เขาตอบว่า “ข้าพเจ้าคือเอซาวบุตรชายของท่าน เป็นบุตรหัวปีของท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 33, 'อิสอัคก็ตัวสั่นมากพูดว่า “ใครเล่า คือผู้นั้นอยู่ที่ไหน ที่ไปล่าเนื้อ แล้วนํามาให้พ่อ พ่อกินหมดแล้วก่อนเจ้ามาถึงและพ่ออวยพรเขาแล้ว เป็นที่แน่ว่าผู้นั้นจะได้รับพร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 34, 'เมื่อเอซาวได้ยินคํากล่าวของบิดาก็ร้องออกมาเสียงดังด้วยความขมขื่น และพูดกับบิดาว่า “โอ บิดาเจ้าข้า ขออวยพรข้าพเจ้า ขออวยพรข้าพเจ้าด้วยเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 35, 'แต่ท่านพูดว่า “น้องชายเจ้าเข้ามาหลอกพ่อ และเอาพรของเจ้าไปเสียแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 36, 'เอซาวพูดว่า “เขามีชื่อว่ายาโคบก็ถูกต้องแล้วมิใช่หรือ เพราะว่าเขาแกล้งให้ข้าพเจ้าเสียเปรียบสองครั้งแล้ว เขาเอาสิทธิบุตรหัวปีของข้าพเจ้าไป และดูเถิด คราวนี้เขาเอาพรของข้าพเจ้าไปอีกด้วย” แล้วเขาพูดว่า “ท่านมิได้สงวนพรไว้ให้ข้าพเจ้าบ้างหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 37, 'อิสอัคตอบเอซาวว่า “ดูเถิด พ่อตั้งให้เขาเป็นนายเหนือเจ้า และมอบบรรดาพี่น้องของเขาให้เป็นคนใช้ของเขา ทั้งข้าวและน้ําองุ่นพ่อก็จัดให้เขา ลูกเอ๋ย พ่อจะทําอะไรให้เจ้าได้อีกเล่า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 38, 'เอซาวพูดกับบิดาว่า “บิดาเจ้าข้า ท่านมีพรแต่เพียงพรเดียวเท่านั้นหรือ โอ บิดาเจ้าข้า ขออวยพรลูก ขออวยพรลูกด้วยเถิด” แล้วเอซาวก็ตะเบ็งเสียงร้องไห้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 39, 'อิสอัคบิดาของเขาจึงตอบเขาว่า “ดูเถิด เจ้าจะได้อาศัยอยู่ในแผ่นดินอันอุดมบริบูรณ์ มีน้ําค้างลงมาจากฟ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 40, 'แต่เจ้าจะมีชีวิตอยู่ด้วยดาบและเจ้าจะรับใช้น้องชายของเจ้า แต่ต่อมาเมื่อเจ้ามีกําลังขึ้นเจ้าจะหักแอกของน้องเสียจากคอของตน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 41, 'ฝ่ายเอซาวก็เกลียดชังยาโคบเพราะเหตุพรที่บิดาได้ให้แก่เขานั้น เอซาวรําพึงในใจว่า “วันไว้ทุกข์พ่อใกล้เข้ามาแล้ว หลังจากนั้นข้าจะฆ่ายาโคบน้องชายของข้าเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 42, 'แต่คําของเอซาวบุตรชายคนโตไปถึงหูของนางเรเบคาห์ นางให้คนไปเรียกยาโคบบุตรชายคนเล็กของนางมา และพูดกับเขาว่า “ดูเถิด เอซาวพี่ชายของเจ้าปลอบใจตนเองด้วยแผนการจะฆ่าเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 43, 'เพราะฉะนั้น ลูกเอ๋ย บัดนี้ฟังเสียงของแม่เถิด จงลุกขึ้นหนีไปหาลาบันพี่ชายของแม่ที่เมืองฮาราน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 44, 'และอยู่กับเขาชั่วคราวจนกว่าความเกรี้ยวกราดของพี่ชายเจ้าจะคลายลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 45, 'จนกว่าความโกรธของพี่ชายเจ้าจะคลายลง และเขาลืมสิ่งที่เจ้าได้ทําแก่เขา แล้วแม่จะส่งคนให้ไปพาเจ้ากลับมาจากที่นั่น แม่ต้องสูญเสียลูกทั้งสองคนในวันเดียวกันทําไมเล่า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 46, 'นางเรเบคาห์พูดกับอิสอัคว่า “ข้าพเจ้าเบื่อชีวิตของข้าพเจ้าเหลือเกิน เพราะบุตรสาวของคนเฮท ถ้ายาโคบแต่งงานกับบุตรสาวคนเฮท ซึ่งเป็นหญิงแผ่นดินนี้ ชีวิตข้าพเจ้าจะเป็นประโยชน์อะไรแก่ข้าพเจ้าเล่า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 1, 'แล้วอิสอัคก็เรียกยาโคบมาอวยพรให้ และกําชับเขาว่า “เจ้าอย่าแต่งงานกับหญิงคานาอัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 2, 'แต่ลุกขึ้นไปเมืองปัดดานอารัม ไปยังบ้านเบธูเอลบิดาของแม่เจ้า ที่นั่นเจ้าจงแต่งงานกับบุตรสาวคนหนึ่งของลาบันพี่ชายแม่ของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 3, 'ขอพระเจ้าผู้ทรงมหิทธิฤทธิ์ทรงอวยพระพรแก่เจ้า และโปรดให้เจ้ามีลูกดกทวียิ่งขึ้น จนได้เป็นมวลชนชาติทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 4, 'ขอพระองค์ทรงประทานพรของอับราฮัมแก่เจ้า และแก่เชื้อสายของเจ้าด้วย เพื่อเจ้าจะได้รับแผ่นดินนี้เป็นมรดกซึ่งเจ้าอาศัยอยู่เป็นคนต่างด้าว ซึ่งพระเจ้าได้ประทานแก่อับราฮัมแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 5, 'อิสอัคก็ส่งยาโคบไป ยาโคบก็ไปปัดดานอารัมไปหาลาบัน บุตรชายของเบธูเอลคนซีเรียพี่ชายของนางเรเบคาห์ มารดาของยาโคบและเอซาว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 6, 'ฝ่ายเอซาวเมื่อเห็นว่าอิสอัคอวยพรยาโคบ และส่งเขาไปยังปัดดานอารัมเพื่อหาภรรยาจากที่นั่น และเห็นว่าเมื่ออิสอัคอวยพรเขานั้นท่านกําชับเขาว่า “เจ้าอย่าแต่งงานกับหญิงคานาอันเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 7, 'และเห็นว่ายาโคบเชื่อฟังบิดามารดา และไปยังปัดดานอารัม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 8, 'เมื่อเอซาวเห็นว่าหญิงคานาอันไม่เป็นที่พอใจอิสอัคบิดาของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 9, 'เอซาวจึงไปหาอิชมาเอลและรับมาหะลัทบุตรสาวของอิชมาเอลบุตรชายของอับราฮัมน้องสาวของเนบาโยทมาเป็นภรรยา นอกเหนือภรรยาซึ่งเขามีอยู่แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 10, 'ยาโคบออกจากเมืองเบเออร์เชบาเดินไปยังเมืองฮาราน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 11, 'เขามาถึงที่แห่งหนึ่ง และพักอยู่ที่นั่นในคืนนั้น เพราะดวงอาทิตย์ตกแล้ว เขาเอาหินจากที่นั่นมาเป็นหมอนหนุนศีรษะ แล้วนอนลงที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 12, 'เขาฝัน และดูเถิด มีบันไดอันหนึ่งตั้งขึ้นบนแผ่นดินโลก ยอดถึงฟ้าสวรรค์ ดูเถิด ทูตสวรรค์ทั้งหลายของพระเจ้ากําลังขึ้นลงอยู่บนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 13, 'และดูเถิด พระเยโฮวาห์ประทับยืนอยู่เหนือบันได และตรัสว่า “เราคือเยโฮวาห์พระเจ้าของอับราฮัม บรรพบุรุษของเจ้า และพระเจ้าของอิสอัค แผ่นดินซึ่งเจ้านอนอยู่นั้นเราจะให้แก่เจ้าและเชื้อสายของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 14, 'เชื้อสายของเจ้าจะเป็นเหมือนผงคลีบนแผ่นดิน และเจ้าจะแผ่กว้างออกไปทางทิศตะวันตกและทิศตะวันออก ทางทิศเหนือและทิศใต้ บรรดาครอบครัวทั่วแผ่นดินโลกจะได้รับพรเพราะเจ้าและเพราะเชื้อสายของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 15, 'ดูเถิด เราอยู่กับเจ้า และจะพิทักษ์รักษาเจ้าทุกแห่งหนที่เจ้าไป และจะนําเจ้ากลับมายังแผ่นดินนี้ เพราะเราจะไม่ทอดทิ้งเจ้าจนกว่าเราจะได้ทําสิ่งซึ่งเราพูดกับเจ้าไว้นั้นแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 16, 'ยาโคบตื่นขึ้นและพูดว่า “พระเยโฮวาห์ทรงสถิต ณ ที่นี้แน่ทีเดียว แต่ข้าหารู้ไม่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 17, 'เขากลัวและพูดว่า “สถานที่นี้น่านับถือ สถานที่นี้มิใช่อย่างอื่น แต่เป็นพระนิเวศของพระเจ้าและประตูฟ้าสวรรค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 18, 'ยาโคบจึงลุกขึ้นแต่เช้ามืด เอาก้อนหินที่ทําหมอนหนุนศีรษะ ตั้งขึ้นเป็นเสาสําคัญ และเทน้ํามันบนยอดเสานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 19, 'เขาเรียกสถานที่นั้นว่า เบธเอล แต่ก่อนเมืองนั้นชื่อ ลูส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 20, 'แล้วยาโคบปฏิญาณว่า “ถ้าพระเจ้าจะทรงอยู่กับข้าพระองค์ และจะทรงพิทักษ์รักษาในทางที่ข้าพระองค์ไป และจะประทานอาหารให้ข้าพระองค์รับประทาน และเสื้อผ้าให้ข้าพระองค์สวม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 21, 'จนข้าพระองค์กลับมาบ้านบิดาของข้าพระองค์โดยสันติภาพแล้ว พระเยโฮวาห์จะทรงเป็นพระเจ้าของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 22, 'และก้อนหินซึ่งข้าพระองค์ตั้งไว้เป็นเสาสําคัญ จะเป็นพระนิเวศของพระเจ้า และทุกสิ่งที่พระองค์ทรงประทานแก่ข้าพระองค์ ข้าพระองค์จะถวายหนึ่งในสิบแด่พระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 1, 'ยาโคบเดินทางมาถึงแผ่นดินของประชาชนชาวตะวันออก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 2, 'เขาก็มองไป และเห็นบ่อน้ําบ่อหนึ่งในทุ่งนา ดูเถิด มีฝูงแกะสามฝูงนอนอยู่ข้างบ่อนั้น เพราะคนเลี้ยงแกะเคยตักน้ําจากบ่อนั้นให้ฝูงแกะกิน และหินใหญ่ก็ปิดปากบ่อนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 3, 'และฝูงแกะมาพร้อมกันที่นั่น แล้วคนเลี้ยงแกะก็กลิ้งหินออกจากปากบ่อตักน้ําให้ฝูงแกะกิน แล้วเอาหินปิดปากบ่อนั้นเสียดังเดิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 4, 'ยาโคบถามเขาทั้งหลายว่า “พี่น้องเอ๋ย ท่านมาจากไหน” เขาตอบว่า “เรามาจากเมืองฮาราน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 5, 'ยาโคบจึงถามเขาทั้งหลายว่า “ท่านรู้จักลาบันบุตรชายนาโฮร์หรือไม่” เขาตอบว่า “รู้จัก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 6, 'ยาโคบถามเขาทั้งหลายว่า “ลาบันสบายดีหรือ” เขาตอบว่า “สบายดี ดูเถิด บุตรสาวของเขาชื่อราเชลกําลังมาพร้อมกับฝูงแกะ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 7, 'ยาโคบจึงว่า “ดูเถิด เวลานี้ยังวันอยู่มาก ยังไม่ถึงเวลาที่จะให้ฝูงแพะแกะมารวมกัน จงเอาน้ําให้แกะเหล่านี้กินแล้วให้ไปกินหญ้าอีก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 8, 'แต่เขาทั้งหลายตอบว่า “เราทําไม่ได้ จนกว่าแกะทุกๆฝูงจะมาพร้อมกัน และเขากลิ้งหินออกจากปากบ่อน้ําก่อน แล้วเราจึงจะเอาน้ําให้ฝูงแกะกิน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 9, 'เมื่อยาโคบกําลังพูดกับเขาทั้งหลายอยู่ ราเชลก็มาถึงพร้อมกับฝูงแกะของบิดา เพราะนางเป็นผู้เลี้ยงมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 10, 'และต่อมาครั้นยาโคบแลเห็นราเชลบุตรสาวของลาบันพี่ชายมารดาของตน และฝูงแกะของลาบันพี่ชายมารดาของตน ยาโคบก็เข้าไปกลิ้งหินออกจากปากบ่อน้ํา เอาน้ําให้ฝูงแกะของลาบันพี่ชายมารดาของตนกิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 11, 'ยาโคบจุบราเชลแล้วร้องไห้ด้วยเสียงดัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 12, 'ยาโคบบอกราเชลว่าเขาเป็นหลานบิดาของนาง และเป็นบุตรชายของนางเรเบคาห์ นางก็วิ่งไปบอกบิดาของนาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 13, 'ต่อมาครั้นลาบันได้ยินข่าวถึงยาโคบบุตรชายน้องสาวของตน เขาก็วิ่งไปพบและกอดจุบยาโคบและพามาบ้านของเขา ยาโคบก็เล่าเรื่องเหล่านี้ทั้งหมดให้ลาบันฟัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 14, 'ลาบันจึงพูดกับเขาว่า “เจ้าเป็นกระดูกและเนื้อของเราแท้ๆ” ยาโคบก็พักอยู่กับเขาเดือนหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 15, 'แล้วลาบันพูดกับยาโคบว่า “เพราะเจ้าเป็นหลานของเรา จึงไม่ควรที่เจ้าจะทํางานให้เราเปล่าๆ เจ้าจะเรียกค่าจ้างเท่าไร จงบอกมาเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 16, 'ลาบันมีบุตรสาวสองคน พี่สาวชื่อเลอาห์ น้องสาวชื่อราเชล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 17, 'นางสาวเลอาห์นั้นตายิบหยี แต่นางสาวราเชลนั้นสละสลวยและงามน่าดู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 18, 'ยาโคบก็รักนางสาวราเชล และพูดว่า “ข้าพเจ้าจะรับใช้การงานให้ท่านเจ็ดปี เพื่อได้ราเชลบุตรสาวคนเล็กของท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 19, 'ลาบันจึงว่า “ให้เรายกบุตรสาวให้เจ้านั้นดีกว่าจะยกให้คนอื่น จงอยู่กับเราเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 20, 'ยาโคบก็รับใช้อยู่เจ็ดปีเพื่อได้นางสาวราเชล เห็นเป็นเหมือนน้อยวันเพราะความรักที่เขามีต่อนาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 21, 'ยาโคบบอกลาบันว่า “เวลาที่กําหนดไว้ก็ครบแล้ว ขอให้ภรรยาข้าพเจ้าเถิด เพื่อข้าพเจ้าจะได้เข้าไปหาเธอ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 22, 'ลาบันจึงเชิญบรรดาชาวบ้านมาพร้อมกัน แล้วจัดการเลี้ยง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 23, 'และต่อมาครั้นเวลาค่ํา ลาบันก็พาเลอาห์บุตรสาวของตนมามอบให้แก่ยาโคบ และยาโคบก็เข้าไปหานาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 24, 'ลาบันยกศิลปาห์สาวใช้ของตนให้เป็นสาวใช้ของนางเลอาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 25, 'และต่อมาพอรุ่งขึ้น ดูเถิด เป็นนางเลอาห์ ยาโคบจึงกล่าวแก่ลาบันว่า “ลุงทําอะไรกับข้าพเจ้าเล่า ข้าพเจ้ารับใช้ลุงเพื่อได้ราเชลมิใช่หรือ ทําไมลุงจึงล่อลวงข้าพเจ้าเล่า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 26, 'ลาบันจึงตอบว่า “ในแผ่นดินเราไม่มีธรรมเนียมที่จะยกน้องสาวให้ก่อนพี่หัวปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 27, 'ขอให้ครบเจ็ดวันของหญิงนี้ก่อน แล้วเราจะยกคนนั้นให้ด้วย เพื่อตอบแทนที่เจ้าจะได้รับใช้ลุงอีกเจ็ดปี”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 28, 'ยาโคบก็ยอม และรอจนครบเจ็ดวันของนางแล้วลาบันก็ยกราเชลบุตรสาวให้เป็นภรรยาด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 29, 'ลาบันยกบิลฮาห์สาวใช้ของตนให้เป็นสาวใช้ของนางราเชล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 30, 'ฝ่ายยาโคบก็เข้าไปหาราเชลด้วย และเขารักราเชลมากกว่าเลอาห์ เขาจึงรับใช้ลาบันต่อไปอีกเจ็ดปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 31, 'เมื่อพระเยโฮวาห์ทรงเห็นว่ายาโคบชังเลอาห์ พระองค์จึงทรงเปิดครรภ์ของนาง แต่ราเชลนั้นเป็นหมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 32, 'นางเลอาห์ตั้งครรภ์คลอดบุตรเป็นชาย และตั้งชื่อว่ารูเบน ด้วยนางว่า “เพราะพระเยโฮวาห์ทอดพระเนตรความทุกข์ใจของข้าพเจ้าแน่ๆ บัดนี้สามีจึงจะรักข้าพเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 33, 'นางเลอาห์ตั้งครรภ์คลอดบุตรเป็นชายอีกคนหนึ่งและว่า “เหตุพระเยโฮวาห์ทรงได้ยินว่าข้าพเจ้าเป็นที่ชัง พระองค์จึงทรงประทานบุตรชายคนนี้ให้แก่ข้าพเจ้าด้วย” นางตั้งชื่อเขาว่า สิเมโอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 34, 'นางตั้งครรภ์และคลอดบุตรเป็นชายอีกคนหนึ่ง และกล่าวว่า “ครั้งนี้สามีจะสนิทสนมกับข้าพเจ้า เพราะข้าพเจ้าได้คลอดบุตรเป็นชายสามคนให้เขาแล้ว” เหตุนี้จึงตั้งชื่อเขาว่า เลวี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 35, 'นางตั้งครรภ์และคลอดบุตรเป็นชายอีกคนหนึ่ง นางกล่าวว่า “ครั้งนี้ข้าพเจ้าจะสรรเสริญพระเยโฮวาห์” เหตุนี้นางจึงตั้งชื่อเขาว่า ยูดาห์ ต่อไปนางก็หยุดมีบุตร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 1, 'เมื่อนางราเชลเห็นว่าตนไม่มีบุตรกับยาโคบ ราเชลก็อิจฉาพี่สาว และพูดกับยาโคบว่า “ขอให้ข้าพเจ้ามีบุตรด้วย หาไม่ข้าพเจ้าจะตาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 2, 'ยาโคบโกรธนางราเชล เขาจึงว่า “เราเป็นเหมือนพระเจ้า ผู้ไม่ให้เจ้ามีผู้บังเกิดจากครรภ์หรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 3, 'นางจึงบอกว่า “ดูเถิด บิลฮาห์สาวใช้ของข้าพเจ้า จงเข้าไปหานางเถิด นางจะได้มีบุตรเลี้ยงไว้ที่ตักของข้าพเจ้า เพื่อข้าพเจ้าจะได้มีบุตรด้วยอาศัยหญิงคนนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 4, 'นางจึงยกบิลฮาห์สาวใช้ของตนให้เป็นภรรยาของยาโคบ ยาโคบก็เข้าไปหานาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 5, 'บิลฮาห์ก็ตั้งครรภ์และคลอดบุตรชายให้แก่ยาโคบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 6, 'นางราเชลว่า “พระเจ้าได้ทรงตัดสินเรื่องข้าพเจ้า และได้ทรงสดับฟังเสียงทูลของข้าพเจ้าจึงประทานบุตรชายแก่ข้าพเจ้า” เหตุฉะนี้นางจึงตั้งชื่อบุตรนั้นว่า ดาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 7, 'บิลฮาห์สาวใช้ของนางราเชลตั้งครรภ์อีก และคลอดบุตรชายคนที่สองให้แก่ยาโคบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 8, 'นางราเชลจึงว่า “ข้าพเจ้าปล้ําสู้กับพี่สาวของข้าพเจ้าเสียใหญ่โต และข้าพเจ้าได้ชัยชนะแล้ว” นางจึงให้ชื่อบุตรนั้นว่า นัฟทาลี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 9, 'เมื่อนางเลอาห์เห็นว่าตนหยุดคลอดบุตร นางจึงยกศิลปาห์สาวใช้ของตนให้เป็นภรรยาของยาโคบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 10, 'ศิลปาห์สาวใช้ของเลอาห์ก็คลอดบุตรชายให้แก่ยาโคบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 11, 'นางเลอาห์ว่า “กองทหารกําลังมา” จึงตั้งชื่อบุตรนั้นว่า กาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 12, 'แล้วศิลปาห์สาวใช้ของเลอาห์ ก็คลอดบุตรชายคนที่สองให้แก่ยาโคบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 13, 'นางเลอาห์ก็ว่า “ข้าพเจ้ามีความสุขเพราะพวกบุตรสาวจะเรียกข้าพเจ้าว่าเป็นสุข” นางจึงตั้งชื่อบุตรนั้นว่า อาเชอร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 14, 'ในฤดูเกี่ยวข้าวสาลี รูเบนออกไปที่นาพบมะเขือดูดาอิม จึงเก็บผลมาให้นางเลอาห์มารดา ราเชลจึงพูดกับเลอาห์ว่า “ขอมะเขือดูดาอิมของบุตรชายของพี่ให้ฉันบ้าง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 15, 'นางเลอาห์ตอบนางว่า “ที่น้องแย่งสามีของฉันไปแล้วนั้นยังน้อยไปหรือจึงจะมาเอามะเขือดูดาอิมของบุตรชายฉันด้วย” ราเชลตอบว่า “ฉะนั้นถ้าให้มะเขือดูดาอิมของบุตรชายแก่ฉัน คืนวันนี้เขาจะไปนอนกับพี่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 16, 'และยาโคบกลับมาจากนาเวลาเย็น นางเลอาห์ก็ออกไปต้อนรับเขาบอกว่า “จงเข้ามาหาฉันเถิด เพราะฉันให้มะเขือดูดาอิมของบุตรชายเป็นสินจ้างท่านแล้ว” คืนวันนั้นยาโคบก็นอนกับนาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 17, 'พระเจ้าทรงสดับฟังนางเลอาห์ นางก็ตั้งครรภ์ และคลอดบุตรชายคนที่ห้าให้แก่ยาโคบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 18, 'ฝ่ายนางเลอาห์พูดว่า “พระเจ้าทรงประทานสินจ้างนั้นให้แก่ข้าพเจ้า เพราะข้าพเจ้ายกหญิงคนใช้ให้สามี” นางจึงตั้งชื่อบุตรนั้นว่า อิสสาคาร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 19, 'นางเลอาห์ก็ตั้งครรภ์อีก และคลอดบุตรชายคนที่หกให้แก่ยาโคบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 20, 'แล้วนางเลอาห์จึงว่า “พระเจ้าทรงประทานของดีให้ข้าพเจ้า บัดนี้สามีจะอาศัยอยู่กับข้าพเจ้า เพราะข้าพเจ้าได้ให้บุตรชายแก่เขาหกคนแล้ว” นางจึงตั้งชื่อบุตรนั้นว่า เศบูลุน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 21, 'ต่อมาภายหลังนางก็คลอดบุตรสาวคนหนึ่งตั้งชื่อว่า ดีนาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 22, 'พระเจ้าทรงระลึกถึงนางราเชล และพระเจ้าทรงสดับฟังนาง ทรงเปิดครรภ์ของนาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 23, 'นางก็ตั้งครรภ์คลอดบุตรเป็นชาย จึงกล่าวว่า “พระเจ้าทรงโปรดยกความอดสูของข้าพเจ้าไปเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 24, 'นางจึงตั้งชื่อบุตรนั้นว่า โยเซฟ กล่าวว่า “พระเยโฮวาห์จะทรงโปรดเพิ่มบุตรชายอีกคนหนึ่งให้ข้าพเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 25, 'และต่อมาเมื่อนางราเชลคลอดโยเซฟแล้ว ยาโคบก็พูดกับลาบันว่า “ขอให้ข้าพเจ้ากลับไปบ้านเกิดและแผ่นดินของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 26, 'ขอมอบภรรยากับบุตรให้ข้าพเจ้า ซึ่งข้าพเจ้าได้ทํางานรับใช้ท่านเพื่อเขาแล้ว และให้ข้าพเจ้าไปเถิด เพราะท่านรู้ว่าข้าพเจ้าได้รับใช้ท่านแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 27, 'แต่ลาบันตอบเขาว่า “ถ้าลุงเป็นที่พอใจเจ้าแล้ว จงอยู่ต่อเถิด เพราะลุงเรียนรู้จากประสบการณ์ว่าพระเยโฮวาห์ได้ทรงอวยพรเราเพราะเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 28, 'และเขาพูดว่า “เจ้าจะเรียกค่าจ้างเท่าไรก็บอกมาเถิด ลุงจะให้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 29, 'ยาโคบตอบเขาว่า “ข้าพเจ้ารับใช้ลุงอย่างไร และสัตว์ของลุงอยู่กับข้าพเจ้าอย่างไร ลุงก็ทราบอยู่แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 30, 'เพราะว่าก่อนข้าพเจ้ามานั้นลุงมีแต่น้อย แต่บัดนี้ก็มีทวีขึ้นเป็นอันมาก ตั้งแต่ข้าพเจ้ามาถึง พระเยโฮวาห์ได้ทรงอวยพระพรแก่ลุง และบัดนี้เมื่อไรข้าพเจ้าจะบํารุงครอบครัวของตนเองได้บ้างเล่า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 31, 'ลาบันจึงถามว่า “ลุงควรจะให้อะไรเจ้า” ยาโคบตอบว่า “ลุงไม่ต้องให้อะไรข้าพเจ้าดอก แต่หากว่าลุงจะทําสิ่งนี้แก่ข้าพเจ้า ข้าพเจ้าจะเลี้ยงระวังสัตว์ของลุงต่อไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 32, 'คือวันนี้ข้าพเจ้าจะไปตรวจดูฝูงสัตว์ของลุงทั้งฝูง ข้าพเจ้าจะคัดแกะที่มีจุดและด่างทุกตัวออกจากฝูง และคัดแกะดําทุกตัวออกจากฝูงแกะ และแพะด่างกับที่มีจุดออกจากฝูงแพะ ให้สัตว์เหล่านี้เป็นค่าจ้างของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 33, 'ดังนั้นความชอบธรรมของข้าพเจ้าจะเป็นคําตอบของข้าพเจ้าในเวลาภายหน้า คือเมื่อลุงมาตรวจดูค่าจ้างของข้าพเจ้า ถ้าพบตัวไม่มีจุดและที่ไม่ด่างอยู่ในฝูงแพะและตัวที่ไม่ดําในฝูงแกะ ก็ให้ถือเสียว่าข้าพเจ้ายักยอกสัตว์เหล่านี้มา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 34, 'ลาบันจึงตอบว่า “ดูเถิด ลุงตกลงตามที่เจ้าพูดนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 35, 'วันนั้นเขาก็คัดแพะตัวผู้ที่ลายและที่ด่าง และแพะตัวเมียที่มีจุดและที่ด่าง แพะที่ขาวบ้างทั้งหมดและแกะดําทั้งหมด มามอบให้บุตรชายของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 36, 'เขาแยกสัตว์ออกไปทั้งหมดห่างจากยาโคบเป็นระยะทางสามวัน ฝูงสัตว์ของลาบันที่เหลืออยู่นั้นยาโคบก็เลี้ยงไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 37, 'ยาโคบเอากิ่งไม้สดจากต้นไค้ ต้นเสลา และต้นเกาลัด มาปอกเปลือกออกเป็นรอยขาวๆให้เห็นไม้สีขาว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 38, 'เขาวางไม้ที่ปอกเปลือกไว้ในร่องตรงหน้าฝูงสัตว์คือในรางน้ําที่ฝูงสัตว์มากินน้ํา เพื่อเมื่อมันมากินน้ํา มันจะตั้งท้อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 39, 'ฝูงสัตว์ก็ตั้งท้องตรงหน้าไม้นั้น ดังนั้นฝูงสัตว์จึงมีลูกที่มีลายมีจุดและด่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 40, 'ยาโคบก็แยกลูกแกะและให้ฝูงแพะแกะนั้นอยู่ตรงหน้าแกะที่มีลาย และแกะดําทุกตัวในฝูงของลาบัน แต่ฝูงแพะแกะของตนนั้นอยู่ต่างหาก ไม่ให้ปะปนกับฝูงสัตว์ของลาบัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 41, 'อยู่มาเมื่อสัตว์ที่แข็งแรงในฝูงจะตั้งท้อง ยาโคบก็จัดไม้วางไว้ที่รางน้ําให้ฝูงสัตว์เห็นเพื่อให้มันตั้งท้องกลางไม้นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 42, 'และเมื่อสัตว์อ่อนแอ ยาโคบก็ไม่ใส่ไม้นั้นไว้ เหตุฉะนั้นสัตว์ที่อ่อนแอจึงตกเป็นของลาบัน แต่สัตว์ที่แข็งแรงเป็นของยาโคบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 43, 'ยาโคบก็มั่งมีมากขึ้น มีฝูงแพะแกะฝูงใหญ่ คนใช้ชายหญิง และฝูงอูฐฝูงลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 1, 'ยาโคบได้ยินบุตรชายของลาบันพูดว่า “ยาโคบได้แย่งทรัพย์ของบิดาเราไปหมด เขาได้ทรัพย์สมบัติทั้งหมดนี้มาจากบิดาเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 2, 'ยาโคบได้สังเกตดูสีหน้าของลาบัน และดูเถิด เห็นว่าไม่เหมือนแต่ก่อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 3, 'พระเยโฮวาห์ตรัสสั่งยาโคบว่า “จงกลับไปยังแผ่นดินบิดาและญาติพี่น้องของเจ้าเถิด และเราจะอยู่กับเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 4, 'ยาโคบก็ให้คนไปเรียกนางราเชลและนางเลอาห์ให้มาที่ทุ่งนาที่เลี้ยงฝูงสัตว์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 5, 'แล้วบอกนางทั้งสองว่า “ข้าพเจ้าเห็นว่าสีหน้าบิดาเจ้าไม่เหมือนแต่ก่อน แต่พระเจ้าของบิดาข้าพเจ้าทรงสถิตอยู่กับข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 6, 'เจ้าทั้งสองรู้แล้วว่าข้าพเจ้ารับใช้บิดาของเจ้าด้วยเต็มกําลัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 7, 'บิดาของเจ้ายังโกงข้าพเจ้า และเปลี่ยนค่าจ้างของข้าพเจ้าเสียสิบครั้งแล้ว แต่พระเจ้ามิได้ทรงอนุญาตให้เขาทําความเสียหายแก่ข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 8, 'ถ้าบิดาบอกว่า ‘สัตว์ที่มีจุดจะเป็นค่าจ้างของเจ้า’ สัตว์ทุกตัวก็มีลูกมีจุด และถ้าบิดาบอกว่า ‘สัตว์ตัวที่ลายเป็นค่าจ้างของเจ้า’ สัตว์ทุกตัวก็มีลูกลายหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 9, 'ดังนี้แหละพระเจ้าจึงทรงยกสัตว์ของบิดาเจ้าประทานให้แก่ข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 10, 'ครั้นมาในฤดูที่สัตว์เหล่านั้นตั้งท้อง ข้าพเจ้าแหงนหน้าขึ้นดู ก็เห็นในความฝันว่า ดูเถิด แพะตัวผู้ที่สมจรกับฝูงสัตว์นั้นเป็นแพะลาย แพะจุด และแพะลายเป็นแถบๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 11, 'ในความฝันนั้นทูตสวรรค์ของพระเจ้าเรียกข้าพเจ้าว่า ‘ยาโคบเอ๋ย’ ข้าพเจ้าตอบว่า ‘ข้าพเจ้าอยู่ที่นี่ พระเจ้าข้า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 12, 'พระองค์ตรัสว่า ‘เงยหน้าขึ้นดู แพะตัวผู้ทุกตัวที่สมจรกับฝูงสัตว์นั้น เป็นสัตว์ลายและมีจุดและลายเป็นแถบๆ เพราะเราเห็นทุกสิ่งที่ลาบันทํากับเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 13, 'เราเป็นพระเจ้าแห่งเบธเอลที่เจ้าเจิมเสาสําคัญไว้และปฏิญาณต่อเรา บัดนี้จงลุกขึ้นออกจากแผ่นดินนี้ และกลับไปยังแผ่นดินพี่น้องของเจ้า’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 14, 'นางราเชลกับนางเลอาห์จึงตอบเขาว่า “เรายังมีส่วนทรัพย์มรดกในบ้านบิดาเราอีกหรือไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 15, 'บิดานับเราเหมือนคนต่างด้าวมิใช่หรือ เพราะบิดาขายเรา ทั้งยังกินเงินของเราเกือบหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 16, 'ทรัพย์สมบัติทั้งปวงที่พระเจ้าทรงเอามาจากบิดาของเรา นั่นแหละเป็นของของเรากับลูกหลานของเรา บัดนี้พระเจ้าตรัสสั่งท่านอย่างไร ก็ขอให้ทําอย่างนั้นเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 17, 'ดังนั้น ยาโคบจึงลุกขึ้นให้บุตรภรรยาขึ้นขี่อูฐ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 18, 'แล้วเขาต้อนสัตว์เลี้ยงทั้งหมดของเขาไป ขนข้าวของทั้งสิ้นที่เขาได้กําไรมา สัตว์เลี้ยงที่เป็นกรรมสิทธิ์ของเขา ที่เขาหามาได้ในเมืองปัดดานอารัม เพื่อเดินทางกลับไปหาอิสอัคบิดาของเขาในแผ่นดินคานาอัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 19, 'และลาบันออกไปตัดขนแกะ ฝ่ายนางราเชลก็ลักรูปเคารพของบิดาไปด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 20, 'ฝ่ายยาโคบก็หลบหนีไปมิได้บอกลาบันชาวซีเรียให้รู้ว่าตนจะหนีไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 21, 'ยาโคบเอาทรัพย์สมบัติทั้งหมดลุกขึ้นหนีข้ามแม่น้ําบ่ายหน้าไปยังถิ่นเทือกเขากิเลอาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 22, 'ครั้นถึงวันที่สาม มีคนไปบอกลาบันว่ายาโคบหนีไปแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 23, 'ลาบันก็พาญาติพี่น้องออกติดตามไปเจ็ดวันก็ทันยาโคบในถิ่นเทือกเขากิเลอาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 24, 'แต่ในกลางคืนพระเจ้าทรงมาปรากฏแก่ลาบันคนซีเรียในความฝัน ตรัสแก่เขาว่า “จงระวังตัว อย่าพูดดีหรือร้ายแก่ยาโคบเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 25, 'แล้วลาบันตามมาทันยาโคบ ยาโคบตั้งเต็นท์อยู่ที่ถิ่นเทือกเขา ส่วนลาบันกับญาติพี่น้องตั้งอยู่ถิ่นเทือกเขากิเลอาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 26, 'ลาบันกล่าวกับยาโคบว่า “เจ้าทําอะไรเล่า หนีพาบุตรสาวของเรามา ไม่บอกให้เรารู้ ทําเหมือนเชลยที่จับได้ด้วยดาบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 27, 'เหตุไฉนเจ้าได้หลบหนีมาอย่างลับๆและแอบมาโดยไม่บอกให้เรารู้ ถ้าเรารู้เราก็จะจัดส่งเจ้าไปด้วยความร่าเริงยินดี โดยให้มีการขับร้องด้วยรํามะนาและพิณเขาคู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 28, 'ทําไมเจ้าไม่ยอมให้เราจุบลาบุตรชายและบุตรสาวของเราเล่า นี่เจ้าทําอย่างโง่เขลาแท้ๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 29, 'เรามีกําลังพอที่จะทําอันตรายแก่เจ้าได้ แต่ในเวลากลางคืนวานนี้พระเจ้าแห่งบิดาเจ้ามาตรัสห้ามเราไว้ว่า ‘จงระวังตัว อย่าพูดดีหรือร้ายแก่ยาโคบเลย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 30, 'บัดนี้ แม้ว่าเจ้าจะไปเพราะคิดถึงบ้านบิดามาก ทําไมจึงลักพระของเรามาด้วยเล่า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 31, 'ยาโคบจึงตอบลาบันว่า “เพราะว่าข้าพเจ้ากลัว ข้าพเจ้าจึงว่า ‘บางทีท่านจะริบบุตรสาวของท่านคืนจากข้าพเจ้าเสีย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 32, 'ส่วนพระของท่านนั้นถ้าพบที่คนไหน ก็อย่าไว้ชีวิตผู้นั้นเลย ค้นดูต่อหน้าญาติพี่น้องของเรา ท่านพบสิ่งใดที่เป็นของท่านกับข้าพเจ้า ก็เอาไปเถิด” เพราะยาโคบไม่รู้ว่านางราเชลได้ลักรูปเหล่านั้นมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 33, 'ลาบันจึงเข้าไปในเต็นท์ของยาโคบ เต็นท์ของนางเลอาห์และเต็นท์สาวใช้ทั้งสองคนนั้น แต่หาไม่พบ จึงออกจากเต็นท์ของนางเลอาห์ แล้วเข้าไปในเต็นท์ของนางราเชล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 34, 'ส่วนนางราเชลเอารูปเคารพเหล่านั้นซ่อนไว้ในกูบอูฐและนั่งทับไว้ ลาบันได้ค้นดูทั่วเต็นท์ก็หาไม่พบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 35, 'นางราเชลก็พูดกับบิดาของตนว่า “ขอนายอย่าโกรธเลยที่ข้าพเจ้าลุกขึ้นต้อนรับไม่ได้ ด้วยว่าธรรมดาที่ผู้หญิงเคยมีกําลังเป็นอยู่กับข้าพเจ้า” ลาบันก็ค้นดูแล้ว แต่ไม่พบรูปเคารพนั้นเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 36, 'ส่วนยาโคบก็โกรธและต่อว่าลาบัน ยาโคบกล่าวกับลาบันว่า “ข้าพเจ้าทําการละเมิดต่อท่านประการใด ข้าพเจ้าทําบาปอะไรท่านจึงรีบติดตามข้าพเจ้ามาดังนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 37, 'ท่านค้นดูของของข้าพเจ้าทั้งหมดแล้ว ท่านพบอะไรที่เป็นของมาจากบ้านของท่าน ก็เอามาตั้งไว้ที่นี่ตรงหน้าญาติพี่น้องทั้งสองฝ่าย ให้เขาตัดสินความระหว่างเราทั้งสอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 38, 'ข้าพเจ้าอยู่กับท่านมายี่สิบปีแล้ว แกะตัวเมียและแพะตัวเมียมิได้แท้งลูก และแกะตัวผู้ในฝูงของท่าน ข้าพเจ้าก็มิได้กินเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 39, 'ที่สัตว์ร้ายกัดฉีกกินเสีย ข้าพเจ้าก็มิได้นํามาให้ท่าน ข้าพเจ้าเองสู้ใช้ให้ ที่ถูกขโมยไปในเวลากลางวันหรือกลางคืน ท่านก็หักจากข้าพเจ้าทั้งนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 40, 'ข้าพเจ้าเคยเป็นเช่นนี้ เวลากลางวัน แดดก็เผาข้าพเจ้า เวลากลางคืนน้ําค้างแข็งก็ผลาญข้าพเจ้า แล้วข้าพเจ้านอนไม่หลับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 41, 'ข้าพเจ้าอาศัยอยู่ในเรือนของท่านเช่นนี้ยี่สิบปีแล้ว ข้าพเจ้าได้รับใช้ท่านสิบสี่ปีเพื่อได้บุตรสาวสองคนของท่าน และรับใช้ท่านหกปีเพื่อได้ฝูงสัตว์ของท่าน ท่านยังได้เปลี่ยนค่าจ้างของข้าพเจ้าสิบครั้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 42, 'ถ้าแม้นพระเจ้าของบิดาข้าพเจ้า พระเจ้าของอับราฮัมและซึ่งอิสอัคยําเกรง ไม่ทรงสถิตอยู่กับข้าพเจ้าแล้ว ครั้งนี้ท่านจะให้ข้าพเจ้าไปตัวเปล่าเป็นแน่ พระเจ้าทรงเห็นความทุกข์ใจของข้าพเจ้าและการงานตรากตรําที่มือข้าพเจ้าทํา จึงทรงห้ามท่านเมื่อคืนวานนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 43, 'แล้วลาบันตอบยาโคบว่า “บุตรสาวเหล่านี้ก็เป็นบุตรสาวของเรา เด็กเหล่านี้ก็เป็นเด็กของเรา ฝูงสัตว์ทั้งฝูงนี้ก็เป็นฝูงสัตว์ของเรา ของทั้งสิ้นที่เจ้าเห็นก็เป็นของเรา วันนี้เราจะกระทําอะไรแก่บุตรสาวของเราหรือแก่เด็กๆที่เกิดมาจากเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 44, 'ฉะนั้นมาเถิด บัดนี้ให้เราทําพันธสัญญา ทั้งเรากับเจ้า ให้เป็นพยานระหว่างเรากับเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 45, 'ฝ่ายยาโคบก็เอาศิลาก้อนหนึ่งตั้งไว้เป็นเสาสําคัญ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 46, 'แล้วยาโคบจึงพูดกับญาติพี่น้องว่า “เก็บก้อนหินมา” เขาเก็บก้อนหินมากองสุมไว้ แล้วก็กินเลี้ยงกันที่กองหินนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 47, 'ลาบันจึงตั้งชื่อกองหินนั้นว่า เยการ์สหดูธา แต่ยาโคบตั้งชื่อว่า กาเลเอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 48, 'ลาบันกล่าวว่า “วันนี้กองหินนี้จะเป็นพยานระหว่างเรากับเจ้า” เหตุฉะนี้เขาจึงตั้งชื่อว่า กาเลเอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 49, 'และมิสปาห์ เพราะเขากล่าวว่า “พระเยโฮวาห์ทรงเฝ้าอยู่ระหว่างเรากับเจ้า เมื่อเราจากกันไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 50, 'ถ้าเจ้าข่มเหงบุตรสาวของเรา หรือถ้าเจ้าได้ภรรยาอื่นนอกจากบุตรสาวของเรา ถึงไม่มีใครอยู่กับเราด้วย จงรู้เถิดว่า พระเจ้าทรงเป็นพยานระหว่างเรากับเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 51, 'ลาบันบอกยาโคบว่า “จงดูกองหินและเสาหินนี้ที่เราได้ตั้งไว้ระหว่างเรากับเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 52, 'หินกองนี้เป็นพยาน และเสานั้นก็เป็นพยานว่า เราจะไม่ข้ามกองหินนี้ไปหาเจ้า และเจ้าจะไม่ข้ามกองหินนี้และเสานี้มาหาเรา เพื่อทําอันตรายกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 53, 'ให้พระเจ้าของอับราฮัมและพระเจ้าของนาโฮร์ ซึ่งเป็นพระเจ้าของบิดาของท่านทรงตัดสินความระหว่างเรา” ยาโคบก็ปฏิญาณโดยอ้างถึงผู้ที่อิสอัคบิดาของตนยําเกรง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 54, 'แล้วยาโคบถวายเครื่องบูชาบนถิ่นเทือกเขา และเรียกญาติพี่น้องของตนมารับประทานขนมปัง พวกเขารับประทานขนมปังและอยู่บนถิ่นเทือกเขาตลอดคืนวันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 55, 'ลาบันตื่นขึ้นแต่เช้ามืด จุบหลานและบุตรสาว อวยพรแก่พวกเขา แล้วลาบันก็ออกเดินทางกลับไปบ้าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 1, 'ยาโคบก็เดินทางไปแล้วเหล่าทูตสวรรค์ของพระเจ้าพบเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 2, 'เมื่อยาโคบเห็นทูตสวรรค์เหล่านั้นเขาจึงว่า “นี่เป็นกองทัพของพระเจ้า” เขาจึงเรียกสถานที่นั้นว่า มาหะนาอิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 3, 'ยาโคบส่งผู้สื่อสารหลายคนล่วงหน้าไปหาเอซาวพี่ชายของตนที่แผ่นดินเสอีร์ที่เมืองเอโดมตั้งอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 4, 'และสั่งเขาว่า “จงไปบอกเอซาวนายของเราว่า ยาโคบผู้รับใช้ของท่านกล่าวดังนี้ ‘ข้าพเจ้าไปอาศัยอยู่กับลาบันจนบัดนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 5, 'ข้าพเจ้ามีฝูงวัว ฝูงลา ฝูงแพะแกะ มีคนใช้ชายหญิง ข้าพเจ้าใช้คนมาเรียนนายของข้าพเจ้าเพื่อข้าพเจ้าจะได้รับความกรุณาในสายตาของท่าน’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 6, 'ผู้สื่อสารนั้นกลับมาบอกยาโคบว่า “ข้าพเจ้าไปพบเอซาวพี่ชายของท่านแล้ว เขากําลังจะมาพบท่านด้วย มีพวกผู้ชายมากับเขาสี่ร้อยคน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 7, 'ยาโคบมีความกลัวและเป็นทุกข์ยิ่งนัก เขาจึงแบ่งคนทั้งหลายที่มาด้วยเขา และฝูงแพะแกะ ฝูงวัว ฝูงอูฐ ออกเป็นสองพวก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 8, 'คิดว่า “ถ้าเอซาวมาตีพวกหนึ่ง อีกพวกหนึ่งที่เหลือจะหนีไปได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 9, 'ยาโคบอธิษฐานว่า “โอ พระเจ้าของอับราฮัมปู่ของข้าพระองค์ และพระเจ้าของอิสอัคบิดาของข้าพระองค์ ข้าแต่พระเยโฮวาห์ผู้ตรัสสั่งข้าพระองค์ไว้ว่า ‘กลับไปยังแผ่นดินและยังญาติพี่น้องของเจ้า และเราจะกระทําการดีแก่เจ้านั้น’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 10, 'ข้าพระองค์ไม่สมควรจะรับบรรดาพระกรุณาและความจริงแม้เล็กน้อยที่สุด ที่พระองค์ได้ทรงโปรดสําแดงแก่ผู้รับใช้ของพระองค์ ด้วยว่าข้าพระองค์ข้ามแม่น้ําจอร์แดนนี้เมื่อมีแต่ไม้เท้า และบัดนี้ข้าพระองค์มีผู้คนเป็นสองพวก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 11, 'ขอพระองค์ทรงโปรดช่วยข้าพระองค์ให้พ้นจากเงื้อมมือพี่ชายข้าพระองค์ คือจากเงื้อมมือของเอซาว เพราะข้าพระองค์กลัวเขา เกรงว่าเขาจะมาตีข้าพระองค์ ทั้งมารดากับลูกด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 12, 'แต่พระองค์ตรัสไว้แล้วว่า ‘เราจะกระทําการดีแก่เจ้าและทําให้เชื้อสายของเจ้าดุจเม็ดทรายที่ทะเล ซึ่งจะมากมายจนนับไม่ถ้วน’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 13, 'คืนวันนั้นยาโคบพักอยู่ที่นั่นและคัดเอาของที่มีอยู่นั้นให้เป็นของกํานัลแก่เอซาวพี่ชายของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 14, 'คือแพะตัวเมียสองร้อย แพะตัวผู้ยี่สิบ แกะตัวเมียสองร้อย และแกะตัวผู้ยี่สิบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 15, 'อูฐแม่ลูกอ่อนสามสิบกับลูกวัวตัวเมียสี่สิบ วัวตัวผู้สิบ ลาตัวเมียยี่สิบ และลูกลาสิบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 16, 'ยาโคบมอบสิ่งเหล่านี้ไว้ในความดูแลของคนใช้ แต่ละฝูงอยู่ต่างหาก และสั่งพวกคนใช้ว่า “ล่วงหน้าไปก่อนเรา และให้หมู่สัตว์นี้เว้นระยะห่างกันหน่อย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 17, 'ยาโคบสั่งหมู่ที่ขึ้นหน้าว่า “เมื่อเอซาวพี่ชายของเรามาพบเจ้าและถามเจ้าว่า ‘เจ้าเป็นคนของใคร เจ้าไปไหน และของที่อยู่ข้างหน้าเจ้านี้เป็นของใคร’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 18, 'เจ้าจงตอบว่า ‘ของเหล่านี้เป็นของยาโคบผู้รับใช้ของท่าน เป็นของกํานัลส่งมาให้เอซาวนายของข้าพเจ้า และดูเถิด ยาโคบตามมาข้างหลัง’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 19, 'ยาโคบสั่งหมู่ที่สองและหมู่ที่สาม และบรรดาผู้ที่ติดตามหมู่เหล่านั้นทํานองเดียวกันว่า “เมื่อเจ้าพบเอซาว จงกล่าวแก่เขาเช่นเดียวกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 20, 'และเสริมว่า ‘ดูเถิด ยาโคบผู้รับใช้ของท่านกําลังตามมาข้างหลังพวกเรา’” เพราะยาโคบคิดว่า “ข้าจะระงับความโกรธของเอซาวได้ด้วยของกํานัลที่ส่งล่วงหน้าไป และภายหลังข้าจะเห็นหน้าเขา บางทีเขาจะยอมรับข้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 21, 'ดังนั้น ของกํานัลต่างๆจึงล่วงหน้าไปก่อนเขา ส่วนตัวเขาคืนนั้นยังค้างอยู่ในค่าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 22, 'กลางคืนนั้นเอง ยาโคบก็ลุกขึ้น พาภรรยาทั้งสอง สาวใช้ทั้งสองและบุตรชายสิบเอ็ดคนข้ามลําธารชื่อยับบอกไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 23, 'ยาโคบส่งครอบครัวข้ามลําธารไป และส่งของทั้งหมดของตนข้ามไปด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 24, 'ยาโคบอยู่ที่นั่นแต่ผู้เดียว มีบุรุษผู้หนึ่งมาปล้ํากับเขาจนเวลารุ่งสาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 25, 'เมื่อบุรุษผู้นั้นเห็นว่าจะเอาชนะยาโคบไม่ได้ ก็ถูกต้องที่ข้อต่อสะโพกของยาโคบ ข้อต่อสะโพกของยาโคบก็เคล็ด เมื่อปล้ําสู้กันอยู่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 26, 'บุรุษนั้นจึงว่า “ปล่อยให้เราไปเถิดเพราะใกล้สว่างแล้ว” แต่ยาโคบตอบว่า “ข้าพเจ้าไม่ยอมให้ท่านไป นอกจากท่านจะอวยพรแก่ข้าพเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 27, 'บุรุษผู้นั้นจึงถามยาโคบว่า “เจ้าชื่ออะไร” ยาโคบตอบว่า “ข้าพเจ้าชื่อยาโคบ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 28, 'บุรุษนั้นจึงว่า “เขาจะไม่เรียกเจ้าว่ายาโคบต่อไป แต่จะเรียกว่า อิสราเอล เพราะเจ้าเหมือนเจ้าชายได้สู้กับพระเจ้าและมนุษย์ และได้ชัยชนะ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 29, 'ยาโคบจึงถามบุรุษผู้นั้นว่า “ขอท่านบอกข้าพเจ้าว่าท่านชื่ออะไร” แต่บุรุษนั้นกล่าวว่า “เหตุไฉนเจ้าจึงถามชื่อเรา” แล้วก็อวยพรยาโคบที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 30, 'ยาโคบจึงเรียกสถานที่นั้นว่า เปนีเอล กล่าวว่า “เพราะข้าพเจ้าได้เห็นพระพักตร์พระเจ้า แล้วยังมีชีวิตอยู่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 31, 'เมื่อยาโคบผ่านเปนูเอล ดวงอาทิตย์ขึ้นแล้วเขาเดินโขยกเขยกไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 32, 'เหตุฉะนี้ คนอิสราเอลจึงไม่กินเส้นเอ็นที่สะโพก ซึ่งอยู่ที่ข้อต่อสะโพกนั้นจนทุกวันนี้ เพราะพระองค์ทรงถูกต้องข้อต่อสะโพกของยาโคบตรงเส้นเอ็นที่สะโพก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 1, 'ยาโคบเงยหน้าขึ้นดู และดูเถิด เอซาวกําลังมาพร้อมกับพวกผู้ชายสี่ร้อยคน ยาโคบจึงแบ่งลูกๆให้นางเลอาห์ นางราเชลและสาวใช้ทั้งสอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 2, 'เขาให้สาวใช้ทั้งสองกับลูกอยู่ข้างหน้า ถัดมานางเลอาห์กับลูก ส่วนนางราเชลกับโยเซฟอยู่ท้ายสุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 3, 'ตัวเขาเองเดินออกหน้าไปก่อน กราบลงถึงดินเจ็ดหน จนเข้ามาใกล้พี่ชายของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 4, 'แต่เอซาววิ่งออกไปต้อนรับเขา กอดและซบหน้าลงที่คอจุบเขา ต่างก็ร้องไห้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 5, 'เอซาวก็เงยหน้าขึ้นแลเห็นพวกผู้หญิงกับลูกๆจึงถามว่า “คนที่อยู่กับเจ้านี้คือใคร” ยาโคบตอบว่า “คือลูกๆที่พระเจ้าโปรดประทานให้แก่ข้าพเจ้าผู้รับใช้ของท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 6, 'แล้วสาวใช้ทั้งสองคนกับลูกๆก็เข้ามาใกล้และกราบลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 7, 'นางเลอาห์กับลูกของเขาก็เข้ามาใกล้และกราบลงด้วย ภายหลังโยเซฟและนางราเชลก็เข้ามาใกล้และกราบลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 8, 'เอซาวถามว่า “ขบวนผู้คนและฝูงสัตว์ทั้งหมดที่เราพบนี้มีความหมายอย่างไร” ยาโคบตอบว่า “เพื่อข้าพเจ้าจะได้รับความกรุณาในสายตาของนายข้าพเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 9, 'เอซาวพูดว่า “น้องเอ๋ย ข้ามีพออยู่แล้ว เก็บของๆเจ้าไว้เองเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 10, 'ยาโคบตอบว่า “มิได้ ข้าพเจ้าขอร้องท่านเถิด ถ้าข้าพเจ้าได้รับความกรุณาในสายตาของท่านแล้วขอรับของกํานัลนั้นจากมือข้าพเจ้า เพราะเหตุว่าข้าพเจ้าได้เห็นหน้าท่านก็เหมือนเห็นพระพักตร์ของพระเจ้า และท่านได้โปรดข้าพเจ้าแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 11, 'ข้าพเจ้าอ้อนวอน ขอท่านรับของขวัญที่นํามาให้ท่าน เพราะพระเจ้าทรงโปรดกรุณาข้าพเจ้าและข้าพเจ้าก็มีพอเพียงแล้ว” เขาอ้อนวอนและเอซาวจึงรับไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 12, 'เอซาวพูดว่า “ให้เราเดินทางไปกันเถิด ให้เราไปกันและข้าจะนําหน้าเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 13, 'แต่ยาโคบตอบเขาว่า “นายท่านย่อมทราบอยู่แล้วว่าเด็กๆนั้นอ่อนแอ และข้าพเจ้ายังมีฝูงแพะแกะและโคที่มีลูกอ่อนยังกินนมอยู่ ถ้าจะต้อนให้เดินเกินไปสักวันหนึ่งฝูงสัตว์ก็จะตายหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 14, 'ขอนายท่านล่วงหน้าผู้รับใช้ของท่านไปก่อนเถิด ข้าพเจ้าจะตามไปช้าๆตามกําลังของสัตว์ซึ่งอยู่ข้างหน้าข้าพเจ้าและตามที่เด็กๆทนได้ จนกว่าข้าพเจ้าจะไปพบนายท่านที่เสอีร์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 15, 'เอซาวจึงกล่าวว่า “บัดนี้ขอให้คนที่มากับเราไปกับเจ้าบ้าง” ยาโคบตอบว่า “มีความจําเป็นอะไรหรือ ขอให้ข้าพเจ้าได้รับความกรุณาในสายตาของนายท่านเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 16, 'ในวันนั้น เอซาวก็กลับไปทางเสอีร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 17, 'ส่วนยาโคบเดินทางไปถึงสุคคท เขาสร้างบ้านอยู่ที่นั่น และสร้างเพิงให้สัตว์ของเขา ฉะนั้นจึงเรียกที่นั้นว่า สุคคท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 18, 'เมื่อยาโคบเดินทางจากปัดดานอารัมก็มาถึงเมืองเชเลมซึ่งเป็นเมืองของเชเคมในแผ่นดินคานาอัน เขาตั้งเต็นท์อยู่หน้าเมืองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 19, 'ยาโคบซื้อที่ดินแปลงหนึ่งที่ตั้งเต็นท์อยู่นั้น จากบุตรชายของฮาโมร์บิดาของเชเคมเป็นเงินหนึ่งร้อยเหรียญ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 20, 'ยาโคบสร้างแท่นบูชาที่นั่น เรียกแท่นนั้นว่า เอลเอโลเฮอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 1, 'ฝ่ายดีนาห์บุตรสาวของนางเลอาห์ซึ่งนางบังเกิดให้กับยาโคบนั้นออกไปเยี่ยมผู้หญิงในแผ่นดินนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 2, 'เมื่อเชเคมบุตรชายฮาโมร์คนฮีไวต์ผู้เป็นเจ้าเมืองเห็นนางสาวดีนาห์ เขาก็เอานางไปหลับนอนและทําอนาจารต่อนาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 3, 'จิตใจของเชเคมก็ผูกพันอยู่กับนางสาวดีนาห์บุตรสาวยาโคบ และเขารักนางพูดจาเล้าโลมเอาใจนาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 4, 'เชเคมจึงพูดกับฮาโมร์บิดาของตนว่า “จงขอหญิงสาวนี้ให้เป็นภรรยาข้าพเจ้าเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 5, 'ยาโคบได้ยินข่าวว่าผู้นั้นทําการอนาจารกับนางสาวดีนาห์บุตรสาวของตน เวลานั้นพวกบุตรชายของท่านอยู่กับฝูงสัตว์ที่ในนา ยาโคบจึงนิ่งคอยจนพวกบุตรชายกลับมาบ้าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 6, 'ฮาโมร์บิดาของเชเคมก็ไปหายาโคบเพื่อปรึกษากับท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 7, 'เมื่อพวกบุตรชายของยาโคบได้ยินข่าวนั้นก็กลับมาจากนา ต่างก็โศกเศร้าและโกรธยิ่งนักเพราะเชเคมได้กระทําความโง่เขลาในพวกอิสราเอล โดยข่มขืนบุตรสาวของยาโคบ ซึ่งเป็นการไม่สมควร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 8, 'ฮาโมร์ก็ปรึกษากับพวกเขาว่า “จิตใจเชเคมบุตรชายของเรานี้ผูกพันรักใคร่บุตรสาวของท่านมาก ขอหญิงนั้นเป็นภรรยาบุตรชายของเราเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 9, 'และเชิญพวกท่านจงทําการสมรสกับพวกเรา ยกบุตรสาวของท่านให้พวกเรา และรับบุตรสาวของเราให้พวกท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 10, 'ท่านทั้งหลายจะได้อยู่กับพวกเรา แผ่นดินนี้จะอยู่ตรงหน้าท่าน จงอาศัยเป็นที่ค้าขายและจงได้สมบัติมากในแผ่นดินนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 11, 'เชเคมบอกบิดาและพวกพี่ชายของหญิงนั้นว่า “จงเห็นแก่ข้าพเจ้าเถิด และท่านจะเรียกเท่าไร ข้าพเจ้าก็จะให้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 12, 'ท่านจะเอาเงินสินสอดและของขวัญสักเท่าไรก็ตามใจ ท่านจะเรียกเท่าไร ข้าพเจ้าจะให้ แต่ขอยกหญิงนั้นเป็นภรรยาข้าพเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 13, 'ฝ่ายบุตรชายของยาโคบก็ตอบแก่เชเคมและฮาโมร์บิดาของเชเคมเป็นกลอุบาย เพราะเหตุเขาทําอนาจารแก่นางสาวดีนาห์น้องสาวนั้น จึงกล่าวว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 14, 'โดยบอกเขาว่า “เราทําสิ่งนี้ไม่ได้ คือยกน้องสาวของเราให้แก่คนที่ยังไม่ได้เข้าสุหนัตนั้น เพราะจะเป็นที่อับอายขายหน้าแก่เรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 15, 'แต่เราจะยอมดังนี้ ถ้าท่านจะยอมเป็นเหมือนพวกเรา โดยให้ผู้ชายทุกคนของท่านเข้าสุหนัต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 16, 'เราจึงจะยอมยกบุตรสาวของเราให้แก่พวกท่าน และเราจะรับบุตรสาวของพวกท่านเป็นภรรยาของพวกเรา และเราจะอยู่กับท่านและจะเป็นชนชาติเดียวกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 17, 'แต่ถ้าท่านทั้งหลายไม่ฟังคําเรา ไม่เข้าสุหนัต เราจะเอาบุตรสาวของเราไปเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 18, 'ถ้อยคําของเขาเป็นที่พอใจฮาโมร์ และเชเคมบุตรชายของฮาโมร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 19, 'หนุ่มคนนั้นไม่รีรอที่จะทําตาม เพราะเขามีความรักใคร่ในบุตรสาวของยาโคบ เขาเป็นคนน่าเคารพนับถือมากกว่าใครๆในครอบครัวของบิดา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 20, 'ฮาโมร์กับเชเคมบุตรชายจึงออกไปที่ประตูเมือง และปรึกษากับชาวเมืองนั้นว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 21, '“คนเหล่านี้เป็นมิตรกับพวกเรา เพราะฉะนั้นจงให้เขาอาศัยค้าขายในแผ่นดินนี้ เพราะดูเถิด แผ่นดินนี้กว้างขวางพอให้เขาอยู่ได้ ให้เรารับบุตรสาวของเขาเป็นภรรยาพวกเราและยกบุตรสาวของเราให้เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 22, 'เพียงแต่เราที่เป็นชายทุกคนจะยอมเข้าสุหนัตเหมือนเขา ถ้ายอมกระทําดังนั้นพวกนั้นจะอาศัยอยู่เป็นชนชาติเดียวกับเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 23, 'ฝูงสัตว์เลี้ยงและทรัพย์สมบัติของเขา กับฝูงสัตว์ทั้งสิ้นของเขาก็จะเป็นของเราด้วยมิใช่หรือ ขอแต่ให้เรายอมกระทําดังนั้นเขาจะยอมอยู่กับเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 24, 'บรรดาชาวเมืองที่ออกไปจากประตูเมืองก็เห็นชอบด้วยฮาโมร์และเชเคมบุตรชาย และผู้ชายทั้งปวงที่ออกไปจากประตูเมืองก็เข้าสุหนัต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 25, 'ครั้นอยู่มาถึงวันที่สาม เมื่อคนเหล่านั้นกําลังเจ็บอยู่ บุตรชายสองคนของยาโคบชื่อสิเมโอนและเลวี เป็นพี่ชายนางสาวดีนาห์ ก็ถือดาบเข้าไปในเมืองด้วยใจกล้าหาญฆ่าผู้ชายในเมืองนั้นเสียสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 26, 'เขาฆ่าฮาโมร์และเชเคมบุตรชายเสียด้วยคมดาบ และพานางสาวดีนาห์ออกจากบ้านเชเคมไปเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 27, 'พวกบุตรชายของยาโคบเข้าไปตามบ้านคนตาย และปล้นเมืองนั้น เพราะคนเหล่านั้นได้ทําอนาจารต่อน้องสาวของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 28, 'เขาริบเอาฝูงแกะ ฝูงวัว ฝูงลา และข้าวของทั้งปวงในเมืองและในนาไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 29, 'เอาทรัพย์สมบัติทั้งหมดของเขาไป และจับบุตรภรรยาของคนเหล่านั้นไปเป็นเชลย และริบของในบ้านไปเสียทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 30, 'ฝ่ายยาโคบจึงพูดกับสิเมโอนและเลวีว่า “เจ้าทําให้เราลําบากใจ โดยทําให้เราเป็นที่เกลียดชังแก่คนแผ่นดินนี้ คือคนคานาอันกับคนเปริสซี เรามีผู้คนน้อยนัก เขาทั้งหลายจะรุมกันมาฆ่าเราเสีย จะทําให้เราและครอบครัวพินาศสิ้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 31, 'แต่เขาตอบว่า “มันจะทํากับน้องสาวเราเหมือนหญิงแพศยาได้หรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 1, 'พระเจ้าตรัสแก่ยาโคบว่า “จงลุกขึ้นแล้วขึ้นไปยังเบธเอล และอาศัยอยู่ที่นั่น ทําแท่นที่นั่นบูชาพระเจ้าผู้สําแดงพระองค์แก่เจ้าเมื่อเจ้าหนีไปจากหน้าเอซาวพี่ชายของเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 2, 'ดังนั้นยาโคบจึงบอกครอบครัวของตน และคนทั้งปวงที่อยู่ด้วยกันว่า “จงทิ้งพระต่างด้าวที่อยู่ท่ามกลางเจ้าเสียให้หมด ชําระตัว และเปลี่ยนเครื่องนุ่งห่ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 3, 'และให้พวกเราลุกขึ้นแล้วขึ้นไปยังเบธเอล ที่นั่นข้าจะทําแท่นบูชาแด่พระเจ้า ผู้ทรงตอบข้าในวันที่ข้ามีความทุกข์ใจ และทรงอยู่กับข้าในทางที่ข้าไปนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 4, 'คนทั้งหลายเอาพระต่างด้าวทั้งหมดที่มีอยู่ กับตุ้มหูที่หูของเขามาให้ยาโคบ ยาโคบก็ซ่อนไว้ใต้ต้นโอ๊กที่อยู่ใกล้เมืองเชเคม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 5, 'พวกเขาก็ยกเดินไป เมืองต่างๆที่อยู่รอบข้างต่างมีความเกรงกลัวพระเจ้า ชาวเมืองจึงมิได้ไล่ตามบรรดาบุตรชายของยาโคบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 6, 'ดังนั้นยาโคบมาถึงตําบลลูส คือเบธเอล ซึ่งอยู่ในแผ่นดินคานาอัน ทั้งตัวเขาและทุกคนที่อยู่กับเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 7, 'ที่นั่นยาโคบสร้างแท่นบูชาไว้ และเรียกตําบลนั้นว่าเอลเบธเอล เหตุว่าที่นั่นพระเจ้าทรงสําแดงพระองค์แก่ยาโคบ เมื่อครั้งยาโคบหนีไปจากหน้าพี่ชาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 8, 'ฝ่ายพี่เลี้ยงของนางเรเบคาห์ ชื่อเดโบราห์ก็ถึงแก่ความตาย เขาฝังศพไว้ใต้ต้นโอ๊กใต้เบธเอล เขาเรียกต้นไม้นั้นว่า อัลโลนบาคูท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 9, 'เมื่อยาโคบออกจากปัดดานอารัมพระเจ้าก็ทรงสําแดงพระองค์แก่ยาโคบอีก และทรงอวยพรเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 10, 'พระเจ้าตรัสแก่เขาว่า “เจ้ามีชื่อว่ายาโคบ เขาจะไม่เรียกเจ้าว่ายาโคบต่อไปแต่จะมีชื่อว่าอิสราเอล” ดังนั้นพระองค์จึงเรียกเขาว่า อิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 11, 'พระเจ้าตรัสแก่เขาว่า “เราเป็นพระเจ้าผู้ทรงมหิทธิฤทธิ์ เจ้าจงเกิดผู้คนทวีมากขึ้น ประชาชาติหนึ่งและหลายประชาชาติจะเกิดมาจากเจ้า กษัตริย์หลายองค์จะออกมาจากบั้นเอวของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 12, 'แผ่นดินที่เราให้แก่อับราฮัมและอิสอัคแล้วเราจะให้แก่เจ้า และเราจะให้แผ่นดินนี้แก่เชื้อสายของเจ้าที่มาภายหลังเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 13, 'พระเจ้าเสด็จขึ้นไปจากยาโคบ ณ ที่ที่พระองค์ตรัสแก่เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 14, 'ยาโคบก็ปักเสาสําคัญไว้ที่นั่นที่พระองค์ตรัสแก่ตน เป็นเสาหิน เขาก็เอาเครื่องดื่มบูชาเทลงบนเสา และเทน้ํามันบนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 15, 'ยาโคบเรียกตําบลที่พระเจ้าตรัสแก่ตนว่า เบธเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 16, 'เขาทั้งหลายไปจากเบธเอลใกล้จะถึงเอฟราธาห์ นางราเชลจะคลอดบุตรก็เจ็บครรภ์นัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 17, 'ต่อมาขณะที่นางเจ็บครรภ์นัก หญิงผดุงครรภ์บอกนางว่า “อย่ากลัว ท่านจะได้บุตรชายคนนี้ด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 18, 'อยู่มาเมื่อชีวิตใกล้ดับ (เพราะนางถึงแก่ความตาย) นางเรียกบุตรนั้นว่า เบนโอนี แต่บิดาเรียกเขาว่า เบนยามิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 19, 'นางราเชลก็สิ้นชีวิต เขาฝังศพไว้ริมทางที่จะไปบ้านเอฟราธาห์ซึ่งคือเบธเลเฮม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 20, 'ยาโคบเอาเสาหินปักไว้ ณ ที่ฝังศพซึ่งเป็นเสาหิน ณ ที่ฝังศพนางราเชลจนทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 21, 'อิสราเอลก็ยกเดินต่อไปอีกไปตั้งเต็นท์อยู่เลยหอคอยแห่งเอเดอร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 22, 'อยู่มาเมื่ออิสราเอลอาศัยอยู่ที่แผ่นดินนั้น รูเบนไปนอนกับนางบิลฮาห์ ภรรยาน้อยของบิดา อิสราเอลก็ได้ยินเรื่องนี้ ฝ่ายบุตรชายของยาโคบมีสิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 23, 'บุตรชายของนางเลอาห์ชื่อ รูเบน เป็นบุตรหัวปีของยาโคบ สิเมโอน เลวี ยูดาห์ อิสสาคาร์และเศบูลุน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 24, 'บุตรชายของนางราเชลชื่อ โยเซฟ และเบนยามิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 25, 'บุตรชายของนางบิลฮาห์ สาวใช้ของนางราเชลชื่อ ดาน และนัฟทาลี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 26, 'บุตรชายของนางศิลปาห์ สาวใช้ของนางเลอาห์ชื่อ กาด และอาเชอร์ คนเหล่านี้เป็นบุตรชายของยาโคบ ซึ่งเกิดที่ปัดดานอารัม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 27, 'ฝ่ายยาโคบกลับมาหาอิสอัคบิดาของตนที่มัมเร คือที่เมืองอารบา คือเฮโบรน ที่อับราฮัมและอิสอัคเคยอาศัยก่อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 28, 'อิสอัคมีอายุหนึ่งร้อยแปดสิบปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 29, 'อิสอัคก็สิ้นลมหายใจ ท่านชราและแก่หง่อมมากเมื่อสิ้นชีวิต และไปอยู่ร่วมบรรพบุรุษของท่าน เอซาวและยาโคบบุตรชายของตนก็นําท่านไปฝังเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 1, 'ต่อไปนี้เป็นพงศ์พันธุ์ของเอซาวคือเอโดม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 2, 'เอซาวได้หญิงคนคานาอันมาเป็นภรรยา คืออาดาห์บุตรสาวเอโลนคนฮิตไทต์ และโอโฮลีบามาห์ บุตรสาวอานาห์ผู้เป็นบุตรสาวศิเบโอนคนฮีไวต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 3, 'กับบาเสมัท บุตรสาวอิชมาเอลเป็นน้องสาวของเนบาโยท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 4, 'ฝ่ายนางอาดาห์คลอดบุตรให้เอซาวชื่อเอลีฟัส นางบาเสมัทคลอดบุตรชื่อเรอูเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 5, 'และนางโอโฮลีบามาห์คลอดบุตรชื่อเยอูช ยาลาม และโคราห์ คนเหล่านี้เป็นบุตรชายของเอซาวที่เกิดในแผ่นดินคานาอัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 6, 'เอซาวพาภรรยาบุตรชายหญิงและคนทั้งปวงในครอบครัวของตน กับฝูงสัตว์ บรรดาสัตว์ใช้งาน และทรัพย์สิ่งของทั้งหมดที่ได้มาในแผ่นดินคานาอัน หันจากหน้ายาโคบน้องชายไปที่เมืองอื่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 7, 'เพราะทรัพย์สมบัติของทั้งสองมีมาก จะอยู่ด้วยกันมิได้ ดินแดนที่เขาอาศัยนั้นไม่พอให้เขาเลี้ยงฝูงสัตว์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 8, 'เอซาวจึงไปอยู่ในถิ่นเทือกเขาเสอีร์ เอซาวคือเอโดม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 9, 'ต่อไปนี้เป็นพงศ์พันธุ์ของเอซาว บิดาคนเอโดม ชาวเมืองเทือกเขาเสอีร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 10, 'ชื่อบุตรชายของเอซาว คือเอลีฟัสบุตรชายนางอาดาห์ ภรรยาเอซาว เรอูเอลบุตรชายนางบาเสมัท ภรรยาเอซาว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 11, 'ฝ่ายบุตรชายของเอลีฟัสชื่อเทมาน โอมาร์ เศโฟ กาทาม และเคนัส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 12, 'ทิมนาเป็นภรรยาน้อยของเอลีฟัสบุตรชายเอซาว นางคลอดบุตรให้เอลีฟัสชื่ออามาเลข คนเหล่านี้เป็นบุตรชายของอาดาห์ภรรยาเอซาว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 13, 'ต่อไปนี้เป็นบุตรชายของเรอูเอล คือนาหาท เศ-ราห์ ชัมมาห์ และมิสซาห์ คนเหล่านี้เป็นบุตรชายของบาเสมัทภรรยาของเอซาว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 14, 'ต่อไปนี้เป็นบุตรชายภรรยาของเอซาว คือนางโอโฮลีบามาห์ บุตรสาวของอานาห์ผู้เป็นบุตรสาวศิเบโอน นางคลอดบุตรให้เอซาวชื่อเยอูช ยาลาม และโคราห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 15, 'ต่อไปนี้เป็นเจ้านายในบรรดาบุตรชายของเอซาว บรรดาบุตรชายของเอลีฟัส บุตรชายหัวปีของเอซาว คือเจ้านายเทมาน เจ้านายโอมาร์ เจ้านายเศโฟ เจ้านายเคนัส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 16, 'เจ้านายโคราห์ เจ้านายกาทาม เจ้านายอามาเลข คนเหล่านี้เป็นเจ้านายของเอลีฟัสในแผ่นดินเอโดม พวกเขาเป็นลูกหลานของนางอาดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 17, 'ต่อไปนี้เป็นบุตรชายของเรอูเอลผู้เป็นบุตรชายของเอซาว คือเจ้านายนาหาท เจ้านายเศ-ราห์ เจ้านายชัมมาห์และเจ้านายมิสซาห์ คนเหล่านี้เป็นเจ้านายของเรอูเอลในแผ่นดินเอโดม พวกเขาเป็นลูกหลานของนางบาเสมัทภรรยาของเอซาว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 18, 'ต่อไปนี้เป็นบุตรชายของนางโอโฮลีบามาห์ภรรยาของเอซาว คือเจ้านายเยอูช เจ้านายยาลาม และเจ้านายโคราห์ คนเหล่านี้เป็นเจ้านายเกิดจากนางโอโฮลีบามาห์บุตรสาวของอานาห์ ภรรยาเอซาว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 19, 'คนเหล่านี้เป็นบุตรชายของเอซาวคือเอโดมและคนเหล่านี้เป็นเจ้านายของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 20, 'ต่อไปนี้เป็นบุตรชายของเสอีร์คนโฮรี ชาวแผ่นดินนั้นคือโลทาน โชบาล ศิเบโอน อานาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 21, 'ดีโชน เอเซอร์และดีชาน คนเหล่านี้เป็นเจ้านายของคนโฮรี ผู้เป็นบุตรของเสอีร์ในแผ่นดินเอโดม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 22, 'บุตรชายโลทานชื่อโฮรีและเฮมาม และน้องสาวของโลทานชื่อทิมนา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 23, 'ต่อไปนี้เป็นบุตรของโชบาล คืออัลวาน มานาฮาท เอบาล เซโฟ และโอนัม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 24, 'ต่อไปนี้เป็นบุตรของศิเบโอนคืออัยยาห์ และอานาห์ อานาห์นั้นเป็นผู้ที่ได้พบฝูงล่อในถิ่นทุรกันดาร เมื่อเลี้ยงฝูงลาของศิเบโอนบิดาของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 25, 'ต่อไปนี้เป็นบุตรของอานาห์ คือดีโชน และโอโฮลีบามาห์ผู้เป็นบุตรสาวของอานาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 26, 'ต่อไปนี้เป็นบุตรของดีโชน คือเฮมดาน เอชบาน อิธราน และเคราน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 27, 'ต่อไปนี้เป็นบุตรของเอเซอร์ คือบิลฮาน ศาวาน และอาขาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 28, 'ต่อไปนี้เป็นบุตรของดีชาน คืออูสและอารัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 29, 'ต่อไปนี้เป็นเจ้านายของคนโฮรี คือเจ้านายโลทาน เจ้านายโชบาล เจ้านายศิเบโอน เจ้านายอานาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 30, 'เจ้านายดีโชน เจ้านายเอเซอร์ เจ้านายดีชาน คนเหล่านี้เป็นเจ้านายของคนโฮรีตามพวกเจ้านายของเขาในแผ่นดินเสอีร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 31, 'ต่อไปนี้เป็นกษัตริย์ที่ครอบครองในแผ่นดินเอโดม ก่อนที่คนอิสราเอลมีกษัตริย์ครอบครอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 32, 'เบลาบุตรชายเบโอร์ครอบครองในเอโดม เมืองหลวงของท่านชื่อดินฮาบาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 33, 'เมื่อเบลาสิ้นพระชนม์แล้ว โยบับบุตรชายเศ-ราห์ชาวเมืองโบสราห์ขึ้นครอบครองแทน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 34, 'เมื่อโยบับสิ้นพระชนม์แล้ว หุชามชาวแผ่นดินของคนเทมานขึ้นครอบครองแทน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 35, 'เมื่อหุชามสิ้นพระชนม์แล้ว ฮาดัดบุตรชายของเบดัดผู้รบชนะคนมีเดียนในทุ่งแห่งโมอับขึ้นครอบครองแทน เมืองหลวงของท่านชื่ออาวีท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 36, 'เมื่อฮาดัดสิ้นพระชนม์แล้ว สัมลาห์ชาวเมืองมัสเรคาห์ขึ้นครอบครองแทน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 37, 'เมื่อสัมลาห์สิ้นพระชนม์แล้ว ซาอูลชาวเมืองเรโหโบทอยู่ที่แม่น้ําขึ้นครอบครองแทน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 38, 'เมื่อซาอูลสิ้นพระชนม์แล้ว บาอัลฮานันบุตรชายอัคโบร์ขึ้นครอบครองแทน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 39, 'เมื่อบาอัลฮานันบุตรชายอัคโบร์สิ้นพระชนม์แล้ว ฮาดาร์ขึ้นครอบครองแทน เมืองหลวงของท่านชื่อปาอู และมเหสีของท่านมีพระนามว่า เมเหทาเบล ธิดาของมัทเรด ธิดาของเมซาหับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 40, 'ต่อไปนี้เป็นชื่อเจ้านายของเอซาว ตามครอบครัว ตามที่ ตามชื่อ คือเจ้านายทิมนา เจ้านายอัลวาห์ เจ้านายเยเธท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 41, 'เจ้านายโอโฮลีบามาห์ เจ้านายเอลาห์ เจ้านายปิโนน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 42, 'เจ้านายเคนัส เจ้านายเทมาน เจ้านายมิบซาร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 43, 'เจ้านายมักดีเอล และเจ้านายอิราม คนเหล่านี้เป็นเจ้านายของเอโดม คือเอซาวบิดาของคนเอโดม ตามที่อยู่ของท่าน ในแผ่นดินที่เป็นกรรมสิทธิ์ของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 1, 'ฝ่ายยาโคบมาอยู่ในดินแดนที่บิดาของท่านเคยอาศัยเป็นคนต่างด้าวนั้นคือ แผ่นดินคานาอัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 2, 'ต่อไปนี้เป็นประวัติพงศ์พันธุ์ของยาโคบ เมื่อโยเซฟอายุได้สิบเจ็ดปีไปเลี้ยงสัตว์อยู่กับพวกพี่ชาย เด็กหนุ่มนั้นอยู่กับบุตรชายของนางบิลฮาห์และกับบุตรชายของนางศิลปาห์ภรรยาบิดาของตน โยเซฟเอาความผิดของพี่ชายมาเล่าให้บิดาฟัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 3, 'ฝ่ายอิสราเอลรักโยเซฟมากกว่าบุตรทั้งหมดของท่าน เพราะโยเซฟเป็นบุตรชายที่เกิดมาเมื่อบิดาแก่แล้ว บิดาทําเสื้อยาวหลากสีให้แก่โยเซฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 4, 'เมื่อพวกพี่ชายเห็นว่าบิดารักโยเซฟมากกว่าบรรดาพี่ชาย ก็ชังโยเซฟ และพูดดีกับเขาไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 5, 'คราวหนึ่งโยเซฟฝัน แล้วเล่าให้พวกพี่ชายฟัง พวกพี่ชายยิ่งชังโยเซฟมากขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 6, 'โยเซฟเล่าว่า “ฟังความฝันซึ่งข้าพเจ้าฝันเห็นซิ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 7, 'ดูเถิด พวกเรากําลังมัดฟ่อนข้าวอยู่ในนา ทันใดนั้น ฟ่อนข้าวของข้าพเจ้าตั้งขึ้นยืนตรง และดูเถิด ฟ่อนข้าวของพวกพี่ๆมาแวดล้อมกราบไหว้ฟ่อนข้าวของข้าพเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 8, 'พวกพี่ชายจึงถามโยเซฟว่า “เจ้าจะปกครองเรากระนั้นหรือ เจ้าจะมีอํานาจครอบครองเราหรือ” พวกพี่ชายก็ยิ่งชังโยเซฟมากขึ้นอีกเพราะความฝัน และเพราะคําของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 9, 'ต่อมาโยเซฟก็ฝันอีก จึงเล่าให้พวกพี่ชายฟังว่า “ดูเถิด ข้าพเจ้าฝันอีกครั้งหนึ่ง เห็นดวงอาทิตย์ดวงจันทร์ และดาวสิบเอ็ดดวงกําลังกราบไหว้ข้าพเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 10, 'เมื่อเล่าให้บิดาและพวกพี่ชายฟัง บิดาก็ว่ากล่าวโยเซฟว่า “ความฝันที่เจ้าได้ฝันเห็นนั้นหมายความว่าอะไร เรากับมารดาและพวกพี่ชายของเจ้าจะมาซบหน้าลงถึงดินกราบไหว้เจ้ากระนั้นหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 11, 'พวกพี่ชายอิจฉาโยเซฟ บิดาก็นิ่งตรองเรื่องนี้อยู่แต่ในใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 12, 'ฝ่ายพวกพี่ชายพากันไปเลี้ยงแพะแกะของบิดาที่เมืองเชเคม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 13, 'อิสราเอลจึงพูดกับโยเซฟว่า “พี่ชายของเจ้าเลี้ยงแพะแกะอยู่ที่เมืองเชเคมมิใช่หรือ มาพ่อจะใช้เจ้าไปหาพี่ชาย” โยเซฟตอบว่า “ข้าพเจ้าพร้อมแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 14, 'บิดาจึงพูดกับเขาว่า “เราขอร้องเจ้าให้ไปดูพี่ชายของเจ้าและฝูงสัตว์ซิว่า สบายดีหรือไม่ แล้วกลับมาบอกพ่อ” บิดาใช้เขาไปจากที่ราบเฮโบรน เขาก็มายังเมืองเชเคม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 15, 'ดูเถิด ชายคนหนึ่งพบโยเซฟเดินไปเดินมาในท้องนาจึงถามว่า “เจ้าหาอะไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 16, 'โยเซฟตอบว่า “ข้าพเจ้าหาพี่ชายของข้าพเจ้า โปรดบอกข้าพเจ้าทีว่า เขาเลี้ยงสัตว์อยู่ที่ไหน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 17, 'คนนั้นตอบว่า “เขาไปแล้วเพราะเราได้ยินเขาพูดกันว่า ‘ให้เราไปเมืองโดธานกันเถิด’” โยเซฟตามไปพบพวกพี่ชายที่เมืองโดธาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 18, 'เมื่อพวกพี่ชายเห็นโยเซฟแต่ไกลยังมาไม่ถึง เขาก็พากันคิดปองร้ายจะฆ่าเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 19, 'เขาพูดกันว่า “ดูเถิด เจ้าช่างฝันมานี่แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 20, 'ฉะนั้น มาเถิด บัดนี้ให้พวกเราฆ่ามันเสีย แล้วทิ้งลงไว้ในบ่อบ่อหนึ่ง เราจะว่า ‘สัตว์ร้ายกัดกินมันเสีย’ แล้วเราจะดูว่าความฝันนั้นจะเป็นจริงได้อย่างไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 21, 'ฝ่ายรูเบนพอได้ยินดังนั้น ก็อยากช่วยโยเซฟให้พ้นมือพวกพี่ชายจึงพูดว่า “เราอย่าฆ่ามันเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 22, 'รูเบนเตือนเขาว่า “อย่าทําให้โลหิตไหล จงทิ้งมันในบ่อนี้ในถิ่นทุรกันดาร อย่าแตะต้องน้องเลย” ทั้งนี้เพื่อจะช่วยน้องให้พ้นมือเขา แล้วจะได้ส่งกลับไปยังบิดา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 23, 'ต่อมา ครั้นโยเซฟมาถึงพวกพี่ชาย เขาก็จับโยเซฟถอดเสื้อออกเสีย คือเสื้อยาวหลากสีที่สวมอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 24, 'แล้วเอาโยเซฟไปทิ้งลงในบ่อ บ่อนั้นว่างเปล่าไม่มีน้ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 25, 'ขณะที่นั่งรับประทานอยู่เขาเงยหน้าขึ้น ดูเถิด เห็นหมู่คนอิชมาเอลมาจากเมืองกิเลอาด มีฝูงอูฐบรรทุกยางไม้ พิมเสนและมดยอบ เดินทางลงไปยังอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 26, 'ยูดาห์จึงพูดกับพี่น้องว่า “หากเราฆ่าน้องและซ่อนโลหิตไว้จะมีประโยชน์อันใดเล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 27, 'มาเถิด ให้เราขายน้องแก่พวกอิชมาเอลโดยไม่แตะต้องเขา เพราะเขาก็เป็นน้องและเป็นเลือดเนื้อของเราเหมือนกัน” พี่น้องทั้งปวงก็พอใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 28, 'ขณะนั้นพวกพ่อค้าชาวมีเดียนกําลังผ่านมา พวกพี่ชายก็ฉุดโยเซฟขึ้นจากบ่อ ขายโยเซฟให้แก่คนอิชมาเอลเป็นเงินยี่สิบเหรียญ คนอิชมาเอลก็พาโยเซฟไปยังอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 29, 'ฝ่ายรูเบนเมื่อกลับมาถึงบ่อนั้น และดูเถิด โยเซฟมิได้อยู่ในบ่อนั้น จึงฉีกเสื้อผ้าของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 30, 'แล้วกลับไปหาพวกน้องบอกว่า “เด็กนั้นหายไปเสียแล้ว แล้วข้าพเจ้าจะไปที่ไหนเล่า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 31, 'พวกเขาก็เอาเสื้อของโยเซฟมา และฆ่าลูกแพะผู้ตัวหนึ่ง จุ่มเสื้อของโยเซฟลงในเลือด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 32, 'แล้วก็ส่งเสื้อยาวหลากสีนั้นไปยังบิดา บอกว่า “พวกเราได้พบเสื้อตัวนี้ ขอพ่อจงพิจารณาดูว่าใช่เสื้อลูกของพ่อหรือไม่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 33, 'บิดารู้จักแล้วร้องว่า “นี่เป็นเสื้อลูกเรา สัตว์ร้ายกัดกินเขาเสียแล้ว โยเซฟย่อยยับเสียแล้วเป็นแน่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 34, 'ยาโคบก็ฉีกเสื้อผ้าเอาผ้ากระสอบคาดเอว ไว้ทุกข์ให้บุตรชายหลายวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 35, 'ฝ่ายบุตรชายหญิงทั้งหมดก็พากันมาปลอบโยนบิดา แต่ท่านไม่ยอมรับการปลอบโยนกล่าวว่า “เราจะโศกเศร้าถึงลูกเราจนกว่าเราจะตามลงไปยังหลุมฝังศพ” บิดาของเขาร้องไห้คิดถึงเขาดังนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 36, 'แล้วคนมีเดียนก็ขายโยเซฟในอียิปต์ไว้กับโปทิฟาร์ข้าราชสํานักของฟาโรห์ ผู้บัญชาการทหารรักษาพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 1, 'ต่อมา ครั้งนั้นยูดาห์ลงไปจากพวกพี่น้อง ไปอาศัยอยู่กับคนอดุลลัมคนหนึ่งชื่อฮีราห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 2, 'ยูดาห์เห็นบุตรสาวของคนคานาอันคนหนึ่งที่นั่น บิดาหญิงนั้นชื่อชูอาห์ จึงแต่งงานกับหญิงนั้นและเข้าไปหานาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 3, 'หญิงนั้นก็ตั้งครรภ์คลอดบุตรชาย บิดาจึงตั้งชื่อว่า เอร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 4, 'หญิงนั้นก็ตั้งครรภ์อีกคลอดบุตรชาย ตั้งชื่อว่า โอนัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 5, 'นางตั้งครรภ์อีกคลอดบุตรชาย ตั้งชื่อว่า เช-ลาห์ นางอยู่ที่เคซิบเมื่อนางให้กําเนิดเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 6, 'ยูดาห์ก็ได้หาหญิงคนหนึ่งชื่อทามาร์ให้เป็นภรรยาเอร์บุตรหัวปีของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 7, 'เอร์บุตรหัวปีของยูดาห์เป็นคนชั่วในสายพระเนตรของพระเยโฮวาห์ พระเยโฮวาห์จึงทรงประหารเขาเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 8, 'ยูดาห์จึงบอกโอนันว่า “เข้าไปหาภรรยาพี่ชายของเจ้าเถิด และแต่งงานกับนาง เพื่อจะได้สืบเชื้อสายพี่ชายไว้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 9, 'โอนันรู้ว่าเชื้อสายจะไม่ได้นับเป็นของตน ต่อมา เมื่อเขาเข้าไปหาภรรยาของพี่ชาย จึงทําให้น้ํากามตกดินเสียด้วยเกรงว่าจะสืบเชื้อสายให้แก่พี่ชาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 10, 'สิ่งที่โอนันกระทํานั้นไม่เป็นที่พอพระทัยพระเยโฮวาห์ พระองค์จึงทรงประหารชีวิตเขาเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 11, 'ยูดาห์จึงบอกทามาร์บุตรสะใภ้ว่า “กลับไปเป็นหญิงม่ายที่บ้านบิดาจนกว่าเช-ลาห์บุตรชายของเราจะโต” ยูดาห์กลัวว่าเขาจะตายเสียเหมือนพี่ชาย นางทามาร์จึงไปอาศัยอยู่ในบ้านบิดา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 12, 'อยู่มาภรรยาของยูดาห์ ผู้เป็นบุตรสาวชูอาห์ก็ตาย เมื่อยูดาห์ค่อยบรรเทาความโศก จึงขึ้นไปหาคนตัดขนแกะของตนที่บ้านทิมนาท กับเพื่อนชื่อฮีราห์ เป็นคนอดุลลัม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 13, 'มีคนมาบอกนางทามาร์ว่า “ดูเถิด พ่อสามีของเจ้าไปบ้านทิมนาทจะตัดขนแกะ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 14, 'นางจึงผลัดเสื้อสําหรับหญิงม่ายออกเสีย เอาผ้าคลุมหน้าห่มตัวไว้ไปนั่งอยู่ที่สถานที่กลางแจ้ง ริมทางที่จะไปบ้านทิมนาท ด้วยนางเห็นว่าเช-ลาห์โตขึ้นแล้ว แต่นางยังมิได้เป็นภรรยาของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 15, 'เมื่อยูดาห์เห็นนางก็คิดว่าเป็นหญิงโสเภณี เพราะนางได้เอาผ้าคลุมหน้าไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 16, 'ยูดาห์จึงได้เข้าไปพูดกับหญิงริมทางนั้นว่า “มาเถิด ให้เราเข้านอนด้วย” (เพราะไม่ทราบว่านางเป็นสะใภ้ของตน) นางจึงว่า “ท่านจะให้อะไรสําหรับการที่เข้าหาข้าพเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 17, 'ยูดาห์ตอบว่า “เราจะส่งลูกแพะจากฝูงมาให้เจ้าตัวหนึ่ง” นางก็ถามว่า “ท่านจะให้ของมัดจําไว้ก่อนจนกว่าจะส่งลูกแพะนั้นมาได้ไหม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 18, 'ยูดาห์ถามว่า “เจ้าจะเอาอะไรเป็นของมัดจํา” นางจึงตอบว่า “จะขอแหวนตรากับเชือก ทั้งไม้พลองที่มือท่านด้วย” ยูดาห์ก็ให้ และเข้าไปหานาง นางก็ตั้งครรภ์กับเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 19, 'นางจึงลุกขึ้นไปเสียและเอาผ้าคลุมหน้านั้นออก นุ่งห่มเสื้อผ้าสําหรับหญิงม่ายอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 20, 'ฝ่ายยูดาห์ฝากลูกแพะมากับเพื่อนคนอดุลลัมให้ไถ่ของมัดจําจากมือหญิงนั้น แต่เขาหานางไม่พบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 21, 'เขาจึงถามคนที่อยู่ตําบลนั้นว่า “หญิงโสเภณีอยู่ที่สถานที่กลางแจ้งริมทางนี้ไปไหน” เขาตอบว่า “หญิงโสเภณีที่นี่ไม่มี”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 22, 'เพื่อนก็กลับไปบอกยูดาห์ว่า “ข้าพเจ้าหาไม่พบ ทั้งชาวตําบลนั้นก็ว่า ‘หญิงโสเภณีที่นี่ไม่มี’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 23, 'ยูดาห์จึงว่า “ให้หญิงนั้นเก็บของนั้นไว้เถิด มิฉะนั้นเราจะละอายใจ ดูเถิด เราฝากลูกแพะตัวนี้ไปให้ แต่ท่านก็หาหญิงนั้นไม่พบ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 24, 'อยู่มาอีกประมาณสามเดือน มีคนมาบอกยูดาห์ว่า “ทามาร์บุตรสะใภ้ของท่านเป็นหญิงแพศยา ยิ่งกว่านั้นอีก ดูเถิด นางมีครรภ์เพราะการแพศยาแล้ว” ยูดาห์จึงสั่งว่า “พานางออกมานี่จับคลอกไฟเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 25, 'เมื่อเขากําลังพานางออกมา นางก็ส่งคนไปหาพ่อสามีบอกว่า “ข้าพเจ้ามีครรภ์กับคนที่เป็นเจ้าของสิ่งนี้” และนางว่า “ขอท่านพิจารณาดูแหวนตรา เชือก และไม้พลองเหล่านี้ว่าเป็นของผู้ใด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 26, 'ยูดาห์รับไปพิจารณาดูรู้แล้วก็ว่า “หญิงคนนี้ชอบธรรมยิ่งกว่าเรา เหตุว่าเรามิได้ยกเขาให้แก่เช-ลาห์บุตรชายของเรา” ฝ่ายยูดาห์ก็มิได้ร่วมรู้กับนางอีกต่อไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 27, 'อยู่มาเมื่อถึงเวลากําหนดคลอดบุตร ดูเถิด ก็มีลูกแฝดอยู่ในครรภ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 28, 'ต่อมาเมื่อจะคลอดนั้นบุตรคนหนึ่งยื่นมือออกมาก่อน หญิงผดุงครรภ์จึงเอาด้ายแดงผูกไว้ที่ข้อมือและกล่าวว่า “คนนี้คลอดก่อน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 29, 'ต่อมาเมื่อบุตรนั้นหดมือเข้าไป ดูเถิด บุตรอีกคนหนึ่งก็คลอดออกมาก่อน หญิงผดุงครรภ์จึงร้องว่า “เจ้าแหวกออกมาได้อย่างไร เจ้าได้แหวกออกมา” เหตุฉะนี้จึงเรียกบุตรนั้นว่า เปเรศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 30, 'ภายหลังน้องชายเปเรศที่มีด้ายแดงผูกข้อมือนั้นก็คลอด จึงให้ชื่อว่า เศ-ราห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 1, 'โยเซฟถูกพาลงไปยังอียิปต์แล้วโปทิฟาร์ข้าราชสํานักของฟาโรห์ ผู้บัญชาการทหารรักษาพระองค์ เป็นคนอียิปต์ ซื้อโยเซฟไว้จากมือคนอิชมาเอลผู้พาเขาลงมาที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 2, 'พระเยโฮวาห์ทรงสถิตอยู่กับโยเซฟ โยเซฟจึงเจริญรวดเร็ว เขาอยู่ในบ้านคนอียิปต์นายของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 3, 'นายก็เห็นว่าพระเยโฮวาห์ทรงสถิตอยู่กับโยเซฟ และพระเยโฮวาห์ทรงโปรดให้การงานทุกอย่างที่กระทําเจริญขึ้นมากในมือของโยเซฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 4, 'โยเซฟได้รับความกรุณาในสายตาของนายและรับใช้ท่าน นายก็ตั้งให้ดูแลการงานในบ้านของท่าน และทุกสิ่งที่ท่านครอบครองอยู่ท่านก็มอบไว้ในมือของโยเซฟทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 5, 'ต่อมาตั้งแต่โปทิฟาร์ตั้งโยเซฟให้เป็นผู้ดูแลการงานในบ้าน และทรัพย์สิ่งของทั้งปวงของท่านแล้ว พระเยโฮวาห์ก็ได้ทรงอํานวยพระพรให้แก่ครอบครัวของคนอียิปต์นั้นเพราะเห็นแก่โยเซฟ ทั้งพระเยโฮวาห์ทรงอวยพรให้สิ่งของทั้งปวงซึ่งเขามีอยู่ในบ้านและในนาให้เจริญขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 6, 'นายได้มอบของสารพัดไว้ในมือโยเซฟ มิได้เอาใจใส่สิ่งของอะไรเลย เว้นแต่อาหารการกิน โยเซฟนั้นเป็นคนรูปงามและเป็นที่โปรดปราน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 7, 'อยู่มาภายหลังเหตุการณ์เหล่านี้ภรรยาของนายมองดูโยเซฟด้วยความเสน่หาและชวนว่า “มานอนกับเราเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 8, 'แต่โยเซฟไม่ยอม จึงตอบแก่ภรรยาของนายว่า “คิดดูเถิด นายก็มิได้ห่วงสิ่งใดซึ่งอยู่ในบ้านเรือน ได้มอบของทุกอย่างที่มีอยู่ไว้ในมือข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 9, 'ในบ้านนี้ไม่มีใครใหญ่กว่าข้าพเจ้า นายมิได้หวงสิ่งใดจากข้าพเจ้า ยกเสียแต่ตัวท่านเพราะเป็นภรรยาของนาย ข้าพเจ้าจะทําความผิดใหญ่หลวงนี้อันเป็นบาปต่อพระเจ้าอย่างไรได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 10, 'ต่อมาแม้นางชวนโยเซฟวันแล้ววันเล่า โยเซฟก็ไม่ยอมฟังนาง ไม่ว่าจะนอนกับนางหรืออยู่ด้วยกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 11, 'อยู่มาคราวนั้นโยเซฟเข้าไปในบ้านเพื่อทําธุระการงานของเขา ไม่มีชายประจําบ้านคนใดอยู่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 12, 'นางก็คว้าเสื้อผ้าโยเซฟเหนี่ยวรั้งไว้ แล้วพูดว่า “มานอนอยู่กับเราเถิด” แต่โยเซฟทิ้งเสื้อผ้าไว้ในมือนางหนีไปข้างนอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 13, 'ต่อมาเมื่อนางเห็นว่าโยเซฟทิ้งเสื้อผ้าไว้ในมือของนาง หนีไปข้างนอกแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 14, 'นางก็ร้องเรียกชายประจําบ้านของตนมาบอกว่า “ดูซิ นายเอาคนชาติฮีบรูมาไว้ทําความหยาบคายแก่เรา มันเข้ามาหาจะนอนกับข้า แต่ข้าร้องเสียงดัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 15, 'อยู่มาเมื่อมันได้ยินข้าร้องขึ้น มันก็ทิ้งเสื้อผ้าไว้กับข้าหนีไปข้างนอก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 16, 'แล้วนางก็เก็บเสื้อผ้าไว้ใกล้ตัวจนนายกลับมาบ้าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 17, 'แล้วนางก็บอกกับนายดังนี้ว่า “อ้ายบ่าวชาติฮีบรูที่ท่านนํามาไว้นั้นเข้ามาหาจะทําหยาบคายแก่ข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 18, 'ต่อมาเมื่อข้าพเจ้าร้องขึ้นมันก็ทิ้งเสื้อผ้าไว้กับข้าพเจ้าหนีไปข้างนอก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 19, 'ต่อมาครั้นนายได้ฟังคําภรรยาบอกว่า “บ่าวของท่านทํากับข้าพเจ้าดังนั้น” ก็โกรธนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 20, 'จึงเอาโยเซฟไปจําไว้ในคุกที่ที่ขังนักโทษหลวง โยเซฟก็ต้องจําอยู่ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 21, 'แต่ว่าพระเยโฮวาห์ทรงสถิตอยู่กับโยเซฟ และทรงสําแดงพระเมตตาแก่เขา ทรงให้เขาเป็นที่โปรดปรานในสายตาของผู้คุมเรือนจํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 22, 'ผู้คุมเรือนจําก็มอบนักโทษทั้งปวงที่ในเรือนจําไว้ในความดูแลของโยเซฟ การงานที่ทําในที่นั้นทุกอย่างโยเซฟเป็นผู้กระทํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 23, 'ผู้คุมเรือนจําไม่ได้เอาใจใส่การงานใดๆที่โยเซฟดูแล เพราะเหตุพระเยโฮวาห์ทรงสถิตอยู่กับท่าน และการงานใดๆที่ท่านกระทําพระเยโฮวาห์ก็ทรงโปรดให้เจริญ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 1, 'ต่อมาภายหลังเหตุการณ์เหล่านี้พนักงานน้ําองุ่นของกษัตริย์แห่งอียิปต์ และพนักงานขนมของพระองค์ทําผิดต่อเจ้านาย คือกษัตริย์แห่งอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 2, 'ฟาโรห์ทรงกริ้วข้าราชการทั้งสองนั้น คือหัวหน้าพนักงานน้ําองุ่น และหัวหน้าพนักงานขนม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 3, 'จึงให้จําคุกไว้ในบ้านของผู้บัญชาการทหารรักษาพระองค์ในคุกที่โยเซฟติดอยู่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 4, 'ผู้บัญชาการทหารรักษาพระองค์สั่งโยเซฟให้รับใช้สองคนนั้น โยเซฟก็ปรนนิบัติเขา พนักงานทั้งสองติดคุกอยู่พักหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 5, 'คืนหนึ่งข้าราชการทั้งสองนั้นฝันไป คือพนักงานน้ําองุ่นและพนักงานขนมของกษัตริย์อียิปต์ที่ต้องจําอยู่ในคุกนั้น ต่างคนต่างฝันคนละเรื่อง ความฝันของต่างคนก็มีความหมายต่างกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 6, 'ครั้นเวลาเช้า โยเซฟเข้ามาหา เห็นข้าราชการทั้งสองนั้น ดูเถิด เขามีหน้าโศกเศร้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 7, 'จึงถามข้าราชการของฟาโรห์ที่ถูกจําอยู่ในคุกที่บ้านนายของตนว่า “ทําไมวันนี้ท่านจึงหน้าเศร้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 8, 'เขาตอบว่า “เราทั้งสองฝันไปและไม่มีผู้ใดจะแก้ฝันได้” โยเซฟบอกเขาว่า “พระเจ้าเท่านั้นแก้ฝันได้มิใช่หรือ ขอท่านเล่าให้ข้าพเจ้าฟังเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 9, 'หัวหน้าพนักงานน้ําองุ่นก็เล่าความฝันของตนให้โยเซฟฟังว่า “ดูเถิด เราฝันเห็นเถาองุ่นอยู่ตรงหน้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 10, 'เถาองุ่นนั้นมีสามกิ่ง พองอกใบอ่อนดอกตูม ก็มีดอกบานออกมา และช่อองุ่นก็สุก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 11, 'ถ้วยของฟาโรห์อยู่ในมือเรา แล้วเราเก็บลูกองุ่นนั้นบีบให้น้ําลงในถ้วยของฟาโรห์ และวางถ้วยนั้นในพระหัตถ์ของฟาโรห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 12, 'โยเซฟบอกข้าราชการนั้นว่า “ขอแก้ฝันดังนี้ คือกิ่งสามกิ่งนั้นได้แก่สามวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 13, 'ภายในสามวันฟาโรห์จะทรงยกศีรษะของท่านขึ้น และจะทรงตั้งท่านไว้ในตําแหน่งเหมือนแต่ก่อน ท่านจะได้ถวายถ้วยนั้นแก่ฟาโรห์อีก ดังที่ได้กระทํามาแต่ก่อนเมื่อเป็นพนักงานน้ําองุ่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 14, 'เมื่อท่านมีความสุขแล้วขอให้ระลึกถึงข้าพเจ้าและแสดงความเมตตาปรานีแก่ข้าพเจ้า ช่วยทูลฟาโรห์ให้ข้าพเจ้าได้ออกจากบ้านนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 15, 'เพราะอันที่จริงเขาลักข้าพเจ้ามาจากแคว้นฮีบรู และที่นี่ก็เหมือนกันข้าพเจ้าไม่ได้ทําผิดอะไรที่ควรต้องติดคุกใต้ดินนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 16, 'เมื่อหัวหน้าพนักงานขนมเห็นว่า คําแก้ความฝันนั้นดี จึงเล่าให้โยเซฟฟังว่า “เราฝันด้วย ดูเถิด เห็นมีกระจาดขนมขาวสามใบ ตั้งอยู่บนศีรษะเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 17, 'ในกระจาดใบบนนั้นมีขนมสารพัดสําหรับฟาโรห์ แล้วมีนกมากินของในกระจาดที่ตั้งอยู่บนศีรษะเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 18, 'โยเซฟตอบว่า “ขอแก้ฝันดังนี้ คือกระจาดสามใบนั้นได้แก่สามวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 19, 'ภายในสามวันฟาโรห์จะทรงยกศีรษะของท่านขึ้นให้พ้นตัว และแขวนท่านไว้ที่ต้นไม้ ฝูงนกจะมากินเนื้อท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 20, 'ครั้นถึงวันที่สามเป็นวันเฉลิมพระชนมพรรษาของฟาโรห์ พระองค์จึงทรงจัดการเลี้ยงข้าราชการทั้งปวงของพระองค์ แล้วทรงยกศีรษะหัวหน้าพนักงานน้ําองุ่น และหัวหน้าพนักงานขนมเข้ามาอยู่ท่ามกลางพวกข้าราชการ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 21, 'ฝ่ายหัวหน้าพนักงานน้ําองุ่นนั้นได้รับการแต่งตั้งในตําแหน่งเดิม เขาก็วางถ้วยในพระหัตถ์ของฟาโรห์เช่นแต่ก่อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 22, 'ส่วนหัวหน้าพนักงานขนมนั้นให้แขวนคอเสีย สมจริงดังที่โยเซฟแก้ฝันไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 23, 'แต่หัวหน้าพนักงานน้ําองุ่นนั้นมิได้ระลึกถึงโยเซฟ กลับลืมเขาเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 1, 'ครั้นอยู่มาอีกสองปีเต็ม ฟาโรห์ก็สุบิน และดูเถิด พระองค์ทรงยืนอยู่ที่ริมฝั่งแม่น้ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 2, 'ดูเถิด มีวัวเจ็ดตัวอ้วนพีงามน่าดูขึ้นมาจากแม่น้ํานั้น กินหญ้าอยู่ในทุ่งหญ้าแห่งหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 3, 'แล้วดูเถิด มีวัวอีกเจ็ดตัวซูบผอมน่าเกลียดตามขึ้นมาจากแม่น้ํา มายืนอยู่กับวัวอื่นๆที่ริมฝั่งแม่น้ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 4, 'วัวที่ซูบผอมน่าเกลียดก็กินวัวอ้วนพีงามน่าดูเจ็ดตัวนั้นเสีย แล้วฟาโรห์ก็ตื่นบรรทม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 5, 'พระองค์ก็บรรทมหลับไปและสุบินครั้งที่สอง และดูเถิด ต้นข้าวต้นเดียวมีรวงเจ็ดรวงเป็นข้าวเมล็ดเต่งงามดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 6, 'แล้วดูเถิด มีรวงข้าวเจ็ดรวงงอกขึ้นมาภายหลัง เป็นข้าวลีบและเกรียมเพราะลมตะวันออก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 7, 'รวงข้าวลีบเจ็ดรวงนั้นได้กลืนกินรวงข้าวเมล็ดเต่งงามดีเจ็ดรวงนั้นเสีย แล้วฟาโรห์ก็ตื่นบรรทม และดูเถิด รู้ว่าเป็นพระสุบิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 8, 'ครั้นต่อมาเวลารุ่งเช้าพระองค์มีพระทัยวุ่นวาย จึงรับสั่งให้เรียกโหรและปราชญ์ทั้งปวงของอียิปต์มาเฝ้า แล้วฟาโรห์ทรงเล่าพระสุบินให้เขาฟัง แต่ไม่มีผู้ใดทูลแก้พระสุบินนั้นถวายแก่ฟาโรห์ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 9, 'ครั้งนั้นหัวหน้าพนักงานน้ําองุ่นจึงทูลฟาโรห์ว่า “วันนี้ข้าพระองค์ระลึกถึงความผิดพลั้งของข้าพระองค์ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 10, 'คือฟาโรห์ทรงพระพิโรธแก่ข้าราชการของพระองค์ และทรงจําข้าพระองค์ไว้ในคุกที่บ้านผู้บัญชาการทหารรักษาพระองค์ ทั้งข้าพระองค์กับหัวหน้าพนักงานขนม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 11, 'ข้าพระองค์ทั้งสองฝันในคืนเดียวกัน ทั้งข้าพระองค์และเขา ความฝันของต่างคนมีความหมายต่างกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 12, 'มีชายหนุ่มชาติฮีบรูคนหนึ่งเป็นบ่าวของผู้บัญชาการทหารรักษาพระองค์ อยู่ที่นั่นด้วยกันกับข้าพระองค์ทั้งสอง และข้าพระองค์ทั้งสองเล่าความฝันให้เขาฟัง ชายนั้นก็แก้ฝันให้ข้าพระองค์ทั้งสอง เขาแก้ฝันให้แต่ละคนตามความฝันของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 13, 'และต่อมาที่เขาแก้ฝันให้ข้าพระองค์ทั้งสองอย่างไรก็เป็นไปอย่างนั้น คือฟาโรห์ทรงตั้งข้าพระองค์ไว้ในตําแหน่งเดิม แต่ฝ่ายเขานั้นถูกแขวนคอเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 14, 'ฟาโรห์จึงรับสั่งให้เรียกโยเซฟมา เขาก็รีบไปเบิกตัวโยเซฟออกมาจากคุกใต้ดิน โยเซฟโกนหนวดผลัดเสื้อผ้าแล้วก็เข้าเฝ้าฟาโรห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 15, 'ฟาโรห์ตรัสแก่โยเซฟว่า “เราฝันไป และหามีผู้ใดแก้ฝันได้ไม่ เราได้ยินถึงเจ้าว่าเจ้าสามารถเข้าใจความฝันเพื่อแก้ฝันนั้นได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 16, 'โยเซฟจึงทูลตอบฟาโรห์ว่า “การแก้ฝันมิได้อยู่ที่ข้าพระองค์ พระเจ้าต่างหากจะประทานคําตอบอันเป็นสุขแก่ฟาโรห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 17, 'ฟาโรห์จึงตรัสแก่โยเซฟว่า “ในความฝันของเรานั้น ดูเถิด เรายืนอยู่ที่ฝั่งแม่น้ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 18, 'และดูเถิด มีวัวเจ็ดตัวอ้วนพีงามน่าดูขึ้นมาจากแม่น้ํา กินหญ้าอยู่ในทุ่งหญ้าแห่งหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 19, 'แล้วดูเถิด วัวอีกเจ็ดตัวตามขึ้นมาไม่งาม น่าเกลียดมากและซูบผอม เราไม่เคยเห็นมีวัวเลวอย่างนี้ทั่วแผ่นดินอียิปต์เลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 20, 'วัวที่ซูบผอมไม่งามนั้นกินวัวอ้วนพีเจ็ดตัวแรกนั้นเสียหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 21, 'เมื่อกินหมดแล้วหามีใครรู้ว่ามันกินเข้าไปไม่ เพราะยังผอมอยู่เหมือนแต่ก่อน แล้วเราก็ตื่นขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 22, 'เราเห็นในความฝันของเรา ดูเถิด ต้นข้าวต้นหนึ่ง มีรวงเจ็ดรวงงอกขึ้นมา เป็นข้าวเมล็ดเต่งและงามดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 23, 'และดูเถิด ข้าวอีกเจ็ดรวงงอกขึ้นมาภายหลังเป็นข้าวเหี่ยวลีบ และเกรียมเพราะลมตะวันออก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 24, 'รวงข้าวลีบนั้นกลืนกินรวงข้าวดีเจ็ดรวงนั้นเสีย เราเล่าความฝันนี้ให้โหรฟัง แต่ไม่มีใครสามารถอธิบายให้เราได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 25, 'โยเซฟจึงทูลฟาโรห์ว่า “พระสุบินของฟาโรห์มีความหมายอันเดียวกัน พระเจ้าทรงสําแดงให้ฟาโรห์ทราบถึงสิ่งที่พระองค์จะทรงกระทํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 26, 'วัวอ้วนพีเจ็ดตัวนั้นคือเจ็ดปี และรวงข้าวดีเจ็ดรวงนั้นก็คือเจ็ดปี เป็นความฝันอันเดียวกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 27, 'วัวเจ็ดตัวซูบผอมน่าเกลียดที่ขึ้นมาภายหลังคือเจ็ดปี กับรวงข้าวเจ็ดรวงลีบและเกรียมเพราะลมตะวันออกนั้น คือเจ็ดปีที่กันดารอาหาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 28, 'นี่คือสิ่งที่ข้าพระองค์ทูลฟาโรห์ คือพระเจ้าทรงสําแดงให้ฟาโรห์รู้สิ่งที่พระองค์จะทรงกระทํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 29, 'ดูเถิด จะมีอาหารบริบูรณ์ทั่วประเทศอียิปต์ถึงเจ็ดปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 30, 'หลังจากนั้นจะบังเกิดการกันดารอาหารอีกเจ็ดปี จนจะลืมความอุดมสมบูรณ์ในประเทศอียิปต์เสีย การกันดารอาหารจะล้างผลาญแผ่นดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 31, 'ทําให้จําความอุดมสมบูรณ์ในแผ่นดินไม่ได้ เพราะเหตุการกันดารอาหารที่เกิดขึ้นตามหลังนี้ ด้วยว่าการกันดารอาหารนั้นจะรุนแรงนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 32, 'ที่ฟาโรห์สุบินสองครั้งนั้น ก็หมายว่าสิ่งนั้นพระเจ้าทรงกําหนดไว้แล้ว และพระเจ้าจะทรงให้บังเกิดในเร็วๆนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 33, 'เพราะฉะนั้นบัดนี้ขอฟาโรห์เลือกคนที่มีความคิดดี มีปัญญา ตั้งให้ดูแลประเทศอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 34, 'ขอฟาโรห์ทําดังนี้และให้คนนั้นจัดพนักงานไว้ทั่วแผ่นดิน และเก็บผลหนึ่งในห้าส่วนแห่งประเทศอียิปต์ไว้ตลอดเจ็ดปีที่อุดมสมบูรณ์นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 35, 'ให้คนเหล่านั้นรวบรวมอาหารในปีที่อุดมเหล่านั้นซึ่งจะมาถึงนั้นไว้ และสะสมข้าวด้วยอํานาจของฟาโรห์ไว้และให้เก็บอาหารไว้ในเมืองต่างๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 36, 'อาหารนี้จะได้เป็นเสบียงสํารองในแผ่นดินสําหรับเจ็ดปีที่กันดารอาหาร ซึ่งจะเกิดขึ้นในประเทศอียิปต์ เพื่อแผ่นดินจะไม่พินาศเสียไปเพราะกันดารอาหาร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 37, 'ข้อเสนอนี้เป็นที่เห็นชอบในสายพระเนตรของฟาโรห์ และในสายตาของข้าราชการทั้งปวงของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 38, 'ฟาโรห์ตรัสกับบรรดาข้าราชการว่า “เราจะหาคนที่มีพระวิญญาณของพระเจ้าอยู่ในตัวเหมือนคนนี้ได้หรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 39, 'ฟาโรห์จึงตรัสกับโยเซฟว่า “เพราะพระเจ้าได้ทรงสําแดงเรื่องนี้ทั้งสิ้นแก่ท่าน จะหาผู้ใดที่มีความคิดดีและมีปัญญาเหมือนท่านก็ไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 40, 'ท่านจะดูแลราชสํานักของเรา และประชาชนทั้งหลายของเราจะปฏิบัติตามคําของท่าน เว้นแต่ฝ่ายพระที่นั่งเท่านั้นเราจะเป็นใหญ่กว่าท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 41, 'ฟาโรห์ตรัสกับโยเซฟว่า “ดูเถิด เราตั้งท่านให้ดูแลทั่วประเทศอียิปต์แล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 42, 'ฟาโรห์ทรงถอดธํามรงค์ตราออกจากพระหัตถ์ของพระองค์ สวมที่มือโยเซฟ กับให้สวมเสื้อผ้าป่านเนื้อละเอียด และสวมสร้อยทองคําให้ที่คอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 43, 'ให้โยเซฟใช้รถหลวงคันที่สองซึ่งฟาโรห์มีอยู่ และมีคนร้องประกาศข้างหน้าท่านว่า “คุกเข่าลงเถิด” ดังนี้แหละ พระองค์ทรงตั้งท่านให้ดูแลทั่วประเทศอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 44, 'ฟาโรห์จึงตรัสกับโยเซฟว่า “เราคือฟาโรห์ ไม่มีคนทั่วแผ่นดินอียิปต์จะยกมือยกเท้าได้เว้นแต่ท่านจะอนุญาต”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 45, 'ฟาโรห์เรียกนามโยเซฟว่า ศาเฟนาทปาเนอาห์ และประทานอาเสนัทบุตรสาวโปทิเฟรา ปุโรหิตเมืองโอนให้เป็นภรรยา โยเซฟก็ออกไปสํารวจทั่วประเทศอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 46, 'เมื่อโยเซฟเข้าเฝ้าฟาโรห์กษัตริย์แห่งอียิปต์นั้น ท่านอายุได้สามสิบปี แล้วโยเซฟก็ออกจากที่เข้าเฝ้าฟาโรห์เที่ยวไปทั่วประเทศอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 47, 'ในเจ็ดปีที่อุดมสมบูรณ์นั้น แผ่นดินก็ออกผลมากมาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 48, 'โยเซฟรวบรวมอาหารทั้งเจ็ดปีซึ่งมีอยู่ในประเทศอียิปต์ไว้หมด สะสมอาหารไว้ในเมืองต่างๆ ผลที่เกิดขึ้นในนารอบเมืองใดๆก็เก็บไว้ในเมืองนั้นๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 49, 'โยเซฟสะสมข้าวไว้ดุจเม็ดทรายในทะเลมากมายจนต้องหยุดคิดบัญชี เพราะนับไม่ถ้วน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 50, 'ก่อนถึงปีกันดารอาหาร มีบุตรชายสองคนเกิดแก่โยเซฟ ซึ่งนางอาเสนัทบุตรสาวโปทิเฟราปุโรหิตเมืองโอนบังเกิดให้ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 51, 'โยเซฟเรียกบุตรหัวปีว่า มนัสเสห์ กล่าวว่า “เพราะว่าพระเจ้าทรงโปรดให้ข้าพเจ้าลืมความยากลําบากทั้งปวง และวงศ์วานทั้งสิ้นของบิดาเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 52, 'บุตรที่สองท่านเรียกชื่อว่า เอฟราอิม “เพราะว่าพระเจ้าทรงโปรดให้ข้าพเจ้ามีเชื้อสายทวีขึ้นในแผ่นดินที่ข้าพเจ้าได้รับความทุกข์ใจ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 53, 'เจ็ดปีที่อุดมสมบูรณ์ในประเทศอียิปต์ก็ล่วงไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 54, 'จึงเกิดกันดารอาหารเจ็ดปี ดั่งที่โยเซฟกล่าวไว้ การกันดารอาหารนั้นเกิดทั่วแผ่นดินทั้งหลาย แต่ทั่วประเทศอียิปต์ยังมีอาหารอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 55, 'เมื่อชาวอียิปต์อดอยากอาหาร ประชาชนก็ร้องทูลขออาหารต่อฟาโรห์ ฟาโรห์ก็รับสั่งแก่ชาวอียิปต์ทั้งหลายว่า “ไปหาโยเซฟ ท่านบอกอะไร ก็จงทําตาม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 56, 'การกันดารอาหารแผ่ไปทั่วพื้นแผ่นดินโลก โยเซฟก็เปิดฉางออกขายข้าวแก่ชาวอียิปต์ และการกันดารอาหารในแผ่นดินอียิปต์รุนแรงมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 57, 'และประเทศทั้งปวงก็มายังประเทศอียิปต์หาโยเซฟเพื่อซื้อข้าว เพราะการกันดารอาหารร้ายแรงในทุกประเทศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 1, 'เมื่อยาโคบรู้ว่ามีข้าวในอียิปต์ ยาโคบจึงพูดกับพวกบุตรชายของตนว่า “มานั่งมองดูกันอยู่ทําไมเล่า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 2, 'ท่านพูดว่า “ดูเถิด เราได้ยินว่ามีข้าวในอียิปต์ ลงไปซื้อข้าวจากที่นั่นมาให้พวกเรา เพื่อพวกเราจะได้มีชีวิตและไม่อดตาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 3, 'พี่ชายของโยเซฟสิบคนก็ลงไปซื้อข้าวที่อียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 4, 'แต่เบนยามินน้องชายของโยเซฟนั้นยาโคบไม่ให้ไปกับพวกพี่ชาย ด้วยท่านกล่าวว่า “เกรงว่าอาจจะเกิดอันตรายแก่เขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 5, 'บรรดาบุตรชายของอิสราเอลก็ไปซื้อข้าวพร้อมกับคนทั้งหลายที่ไป เพราะการกันดารอาหารก็เกิดในแผ่นดินคานาอัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 6, 'ฝ่ายโยเซฟเป็นผู้สําเร็จราชการแผ่นดิน ท่านเป็นผู้ที่ขายข้าวให้แก่บรรดาประชาชนแห่งแผ่นดิน พวกพี่ชายของโยเซฟก็มากราบไหว้ท่าน ก้มหน้าลงถึงดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 7, 'โยเซฟเห็นพวกพี่ชายของตนและรู้จักเขาแต่ทําเป็นไม่รู้จักเขา และพูดจาดุดันกับเขา ท่านถามเขาว่า “พวกเจ้ามาจากไหน” เขาตอบว่า “มาจากแผ่นดินคานาอันเพื่อซื้ออาหาร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 8, 'โยเซฟรู้จักพวกพี่ชาย แต่พวกพี่หารู้จักท่านไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 9, 'โยเซฟระลึกถึงความฝันที่ท่านเคยฝันถึงพวกพี่ๆ และกล่าวแก่พวกเขาว่า “พวกเจ้าเป็นคนสอดแนม แอบมาดูจุดอ่อนของบ้านเมือง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 10, 'พวกเขาจึงตอบท่านว่า “นายเจ้าข้า มิใช่เช่นนั้น แต่ข้าพเจ้าผู้รับใช้ของท่านมาซื้ออาหาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 11, 'ข้าพเจ้าทั้งหลายเป็นบุตรชายร่วมบิดาเดียวกัน เป็นคนสัตย์จริง ผู้รับใช้ของท่านมิใช่คนสอดแนม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 12, 'โยเซฟบอกเขาอีกว่า “มิใช่ แต่พวกเจ้ามาเพื่อดูจุดอ่อนของบ้านเมือง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 13, 'พวกพี่จึงตอบว่า “ข้าพเจ้าทั้งหลายผู้รับใช้ของท่านเป็นพี่น้องสิบสองคน เป็นบุตรชายร่วมบิดาเดียวกันอยู่ในแผ่นดินคานาอัน ดูเถิด วันนี้น้องสุดท้องยังอยู่กับบิดา แต่น้องอีกคนหนึ่งเสียไปแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 14, 'โยเซฟตอบเขาว่า “ที่เราว่า ‘พวกเจ้าเป็นคนสอดแนม’ นั้นจริงแน่ๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 15, 'พวกเจ้าจะถูกทดลองดังนี้ โดยพระชนม์ฟาโรห์พวกเจ้าจะไปจากที่นี่ไม่ได้ เว้นแต่น้องชายสุดท้องมาที่นี่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 16, 'พวกเจ้าต้องอยู่ในคุกก่อน ให้คนหนึ่งในพวกเจ้าไปพาน้องชายมา เพื่อพิสูจน์ถ้อยคําของเจ้าว่าเจ้าพูดจริงหรือไม่ มิฉะนั้นโดยพระชนม์ฟาโรห์ พวกเจ้าเป็นคนสอดแนมแน่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 17, 'แล้วโยเซฟก็ขังพวกพี่ชายไว้ด้วยกันในคุกสามวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 18, 'ในวันที่สามโยเซฟบอกเขาว่า “ทําดังนี้แล้วจะรอดชีวิต เพราะเรายําเกรงพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 19, 'ถ้าพวกเจ้าเป็นคนสัตย์จริง จงให้คนหนึ่งในพวกเจ้าถูกจําอยู่ที่ห้องเล็กในคุก คนอื่นนําข้าวไปเพื่อบรรเทาการกันดารอาหารที่บ้านของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 20, 'แล้วพาน้องชายสุดท้องมาหาเรา ดังนั้นจึงจะเห็นได้ว่าพวกเจ้าพูดจริง แล้วพวกเจ้าจะไม่ตาย” พวกพี่ชายก็ทําดังนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 21, 'พวกพี่ชายจึงพูดกันว่า “ที่จริงเรามีความผิดเรื่องน้องชายเรา เพราะเราได้เห็นความทุกข์ใจของน้องเมื่อเขาอ้อนวอนเราแต่แล้วมิได้ฟัง เพราะฉะนั้นความทุกข์ใจทั้งนี้จึงบังเกิดแก่เรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 22, 'ฝ่ายรูเบนพูดกับน้องทั้งหลายว่า “ข้าห้ามเจ้าแล้วมิใช่หรือว่า ‘อย่าทําบาปผิดต่อเด็กนั้น’ แต่พวกเจ้าไม่ฟัง เหตุฉะนั้น ดูเถิด การพิพากษาเรื่องโลหิตของน้องจึงมาถึง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 23, 'พวกพี่ชายไม่รู้ว่าโยเซฟฟังออก เพราะว่าท่านพูดกับเขาโดยใช้ล่าม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 24, 'โยเซฟก็หันไปจากเขาและร้องไห้ แล้วกลับมาพูดกับเขาอีก และเอาสิเมโอนออกมามัดไว้ต่อหน้าต่อตาพวกเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 25, 'แล้วโยเซฟบัญชาให้ใส่ข้าวในถุงของพี่ชายให้เต็มและใส่เงินของแต่ละคนไว้ในกระสอบของทุกคน และให้เสบียงไปกินกลางทาง ท่านก็ทําต่อเขาดังนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 26, 'พวกเขาบรรทุกข้าวใส่หลังลาแล้วก็ออกเดินทางไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 27, 'ครั้นคนหนึ่งเปิดกระสอบออกจะเอาข้าวให้ลากิน ณ ที่หยุดพัก ดูเถิด เขาก็เห็นเงินของเขาอยู่ที่ปากกระสอบนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 28, 'ผู้นั้นจึงบอกแก่พี่น้องว่า “เงินของข้าพเจ้ากลับคืนมา ดูเถิด เงินนั้นอยู่ที่ปากกระสอบของข้าพเจ้า” พี่น้องตกใจกลัวจนตัวสั่น พูดกันว่า “ที่พระเจ้าทรงกระทําดังนี้แก่เราจะเป็นอย่างไรหนอ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 29, 'เขาก็กลับไปหายาโคบบิดาของเขาในแผ่นดินคานาอัน แล้วเล่าเรื่องทั้งหมดที่เกิดขึ้นแก่ตนให้บิดาฟังว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 30, '“ท่านผู้นั้นที่เป็นเจ้านายของประเทศพูดจาดุดันกับพวกข้าพเจ้า เหมาเอาว่าพวกข้าพเจ้าเป็นผู้สอดแนมดูบ้านเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 31, 'พวกข้าพเจ้าเรียนท่านว่า ‘ข้าพเจ้าทั้งหลายเป็นคนสัตย์จริง หาได้เป็นคนสอดแนมไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 32, 'ข้าพเจ้าทั้งหลายเป็นบุตรชายร่วมบิดาเดียวกัน มีพี่น้องสิบสองคน น้องคนหนึ่งเสียไปแล้ว น้องสุดท้องยังอยู่กับบิดาในแผ่นดินคานาอัน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 33, 'แล้วท่านผู้เป็นเจ้านายของประเทศนั้นตอบแก่เราว่า ‘เพื่อเราจะรู้ว่าพวกเจ้าเป็นคนสัตย์จริง คือให้คนหนึ่งในพวกพี่น้องอยู่กับเรา พวกเจ้าเอาข้าวไปเพื่อบรรเทาการกันดารอาหารที่บ้านของเจ้า แล้วออกเดินทางไปเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 34, 'แล้วจงพาน้องชายสุดท้องมาหาเรา เราจึงจะรู้แน่ว่าพวกเจ้ามิได้เป็นคนสอดแนม แต่เป็นคนสัตย์จริง แล้วเราจะปล่อยพี่ชายไป พวกเจ้ายังจะได้ค้าขายในประเทศนี้’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 35, 'และต่อมาครั้นพวกเขาแก้กระสอบข้าวออก ดูเถิด เห็นห่อเงินของแต่ละคนอยู่ในกระสอบของตน เมื่อเวลาพวกเขากับบิดาเห็นห่อเงินดังนั้นก็กลัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 36, 'ฝ่ายยาโคบบิดาของเขาจึงว่า “พวกเจ้าทําให้เราพลัดพรากจากลูกของเรา โยเซฟก็เสียไปแล้ว สิเมโอนก็เสียไปแล้ว แล้วพวกเจ้ายังจะเอาเบนยามินไปอีกคน สิ่งเหล่านี้ทั้งหมดทําให้เรามีความทุกข์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 37, 'รูเบนจึงบอกบิดาของตนว่า “ถ้าลูกไม่พาเบนยามินกลับมาให้พ่อ พ่อจงเอาบุตรชายทั้งสองคนของลูกฆ่าเสีย จงมอบเบนยามินไว้ในความดูแลของลูกเถิด แล้วลูกจะนําเขากลับมาหาพ่ออีก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 38, 'ยาโคบบอกว่า “ลูกของเราจะไม่ลงไปกับเจ้า เพราะพี่ชายของเขาก็ตายเสียแล้ว เหลือแต่เบนยามินคนเดียว ถ้าเกิดอันตรายแก่เขาในเวลาเดินทางไปกับเจ้า เจ้าจะพาผมหงอกของเราลงสู่หลุมฝังศพด้วยความทุกข์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 1, 'การกันดารอาหารในแผ่นดินร้ายแรงยิ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 2, 'และต่อมาเมื่อครอบครัวยาโคบกินข้าวที่ได้มาจากประเทศอียิปต์หมดแล้ว บิดาเขาจึงบอกแก่บุตรชายว่า “ไปซื้ออาหารมาอีกหน่อย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 3, 'แต่ยูดาห์ตอบบิดาว่า “ท่านกําชับพวกลูกอย่างเด็ดขาดว่า ‘ถ้าไม่ได้พาน้องชายมาด้วย พวกเจ้าจะไม่เห็นหน้าเราอีก’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 4, 'ถ้าพ่อใช้ให้น้องชายไปกับพวกลูก ลูกจะลงไปซื้ออาหารให้พ่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 5, 'แต่ถ้าแม้พ่อไม่ให้น้องไป พวกลูกจะไม่ลงไป เพราะเจ้านายท่านบัญชาแก่พวกลูกว่า ‘ถ้าไม่ได้พาน้องชายมาด้วย พวกเจ้าจะไม่เห็นหน้าเราอีก’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 6, 'อิสราเอลจึงว่า “เหตุไฉนเจ้าจึงไปบอกท่านว่ามีน้องชายอีกคนหนึ่ง ทําให้เราได้รับความช้ําใจเช่นนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 7, 'เขาจึงตอบว่า “เจ้านายท่านซักไซ้ไต่ถามถึงพวกลูก และญาติพี่น้องของพวกลูกว่า ‘บิดายังอยู่หรือ เจ้ามีน้องชายอีกหรือเปล่า’ พวกลูกก็ตอบตามคําถามนั้น จะล่วงรู้ได้อย่างไรว่าท่านจะสั่งว่า ‘พาน้องชายของเจ้ามา’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 8, 'ยูดาห์จึงพูดกับอิสราเอลบิดาของเขาว่า “ขอพ่อให้เด็กนั้นไปกับข้าพเจ้า เราจะได้ลุกขึ้นออกเดินทางไปเพื่อจะได้มีชีวิตและไม่ตาย ทั้งพวกลูกและพ่อกับลูกอ่อนทั้งหลายของเราด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 9, 'ลูกรับประกันน้องคนนี้ พ่อจะเรียกร้องให้ลูกรับผิดชอบก็ได้ ถ้าลูกไม่นําเขากลับมาหาพ่อและส่งเขาต่อหน้าพ่อ ก็ขอให้ลูกรับผิดต่อพ่อตลอดไปเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 10, 'ด้วยว่าถ้าพวกลูกไม่ช้าอยู่เช่นนี้ ก็จะได้กลับมาเป็นครั้งที่สองแล้วเป็นแน่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 11, 'ฝ่ายอิสราเอลบิดาของพวกเขาจึงบอกบุตรชายทั้งหลายว่า “ถ้าอย่างนั้นให้ทําดังนี้ คือเอาผลิตผลอย่างดีที่สุดที่มีในแผ่นดินนี้ คือพิมเสนบ้าง น้ําผึ้งบ้าง ยางไม้และมดยอบ ลูกนัทและลูกอัลมันด์ ใส่ภาชนะไปเป็นของกํานัลแก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 12, 'เอาเงินติดมือเจ้าไปสองเท่า คือเงินที่ติดมาในปากกระสอบของเจ้านั้นก็ให้ติดมือกลับไปด้วย เพราะบางทีเขาเผลอไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 13, 'จงพาน้องชายของเจ้าด้วย แล้วลุกขึ้นกลับไปหาท่านนั้นอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 14, 'ขอพระเจ้าผู้ทรงมหิทธิฤทธิ์โปรดกรุณาพวกเจ้าต่อหน้าท่านนั้น เพื่อท่านจะปล่อยพี่ชายกับเบนยามินกลับมา หากว่าเราจะต้องพลัดพรากจากบุตรไปก็ตามเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 15, 'คนเหล่านั้นก็เอาของกํานัลและเงินสองเท่าติดมือไปพร้อมกับเบนยามิน แล้วลุกขึ้นพากันเดินทางลงไปยังประเทศอียิปต์ และเข้าเฝ้าโยเซฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 16, 'เมื่อโยเซฟเห็นเบนยามินมากับพี่ชาย ท่านจึงสั่งคนต้นเรือนว่า “จงพาคนเหล่านี้เข้าไปในบ้าน ให้ฆ่าสัตว์และจัดโต๊ะไว้ เพราะคนเหล่านี้จะมารับประทานด้วยกันกับเราในเวลาเที่ยง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 17, 'คนต้นเรือนก็ทําตามคําโยเซฟสั่ง และพาคนเหล่านั้นเข้าไปในบ้านโยเซฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 18, 'คนเหล่านั้นก็กลัวเพราะเขาพาเข้าไปในบ้านโยเซฟ จึงพูดกันว่า “เพราะเหตุเงินที่ติดมาในกระสอบของเราครั้งก่อนนั้น เขาจึงพาพวกเรามาที่นี่ เพื่อท่านจะหาเหตุใส่เราจับกุมเรา จับเราเป็นทาส ทั้งจะริบเอาลาด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 19, 'พวกเขาเข้าไปหาคนต้นเรือนของโยเซฟ และพูดกับเขาที่ประตูบ้าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 20, 'และกล่าวว่า “โอ นายเจ้าข้า ข้าพเจ้าทั้งหลายลงมาครั้งก่อนเพื่อซื้ออาหาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 21, 'และต่อมาครั้นข้าพเจ้าทั้งหลายไปถึงที่พัก เราเปิดกระสอบของเราออก และดูเถิด เงินของแต่ละคนก็อยู่ในปากกระสอบของตน เงินนั้นยังอยู่ครบน้ําหนัก ข้าพเจ้าจึงได้นําเงินนั้นติดมือกลับมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 22, 'ข้าพเจ้าเอาเงินอีกส่วนหนึ่งติดมือมาเพื่อจะซื้ออาหารอีก เงินที่อยู่ในกระสอบของเรานั้นผู้ใดใส่ไว้ข้าพเจ้าไม่ทราบเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 23, 'คนต้นเรือนจึงตอบว่า “จงเป็นสุขเถิด อย่ากลัวเลย พระเจ้าของท่านและพระเจ้าของบิดาท่านบันดาลให้มีทรัพย์อยู่ในกระสอบเพื่อท่าน เงินของท่านนั้นเราได้รับแล้ว” คนต้นเรือนก็พาสิเมโอนออกมาหาเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 24, 'คนต้นเรือนพาคนเหล่านั้นเข้าไปในบ้านของโยเซฟ แล้วเอาน้ําให้เขา เขาก็ล้างเท้าและคนต้นเรือนจัดหญ้าฟางให้ลาเขากิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 25, 'พวกพี่ชายก็จัดเตรียมของกํานัลไว้คอยท่าโยเซฟซึ่งจะมาในเวลาเที่ยง เพราะเขาได้ยินว่าเขาจะรับประทานอาหารกันที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 26, 'เมื่อโยเซฟกลับมาบ้าน เขาก็ยกของกํานัลที่ติดมือนั้นมาให้โยเซฟในบ้านแล้วกราบลงถึงดินต่อท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 27, 'โยเซฟถามถึงทุกข์สุขของเขาและกล่าวว่า “บิดาของเจ้าผู้ชราที่พวกเจ้ากล่าวถึงครั้งก่อนนั้นสบายดีหรือ บิดายังมีชีวิตอยู่หรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 28, 'เขาตอบว่า “บิดาของข้าพเจ้าผู้รับใช้ของท่านอยู่สบายดี ท่านยังมีชีวิตอยู่” แล้วเขาก็น้อมลงกราบไหว้อีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 29, 'โยเซฟเงยหน้าดูเห็นเบนยามินน้องชายมารดาเดียวกัน แล้วถามว่า “คนนี้เป็นน้องชายสุดท้องที่พวกเจ้าบอกแก่เราครั้งก่อนหรือ” โยเซฟกล่าวว่า “ลูกเอ๋ย ขอให้พระเจ้าทรงเมตตาแก่เจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 30, 'แล้วโยเซฟรีบไป เพราะรักน้องจนกลั้นน้ําตาไว้ไม่ได้ ท่านก็หาที่ที่จะร้องไห้ ท่านจึงเข้าไปในห้องร้องไห้อยู่ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 31, 'โยเซฟล้างหน้าแล้วกลับออกมาแข็งใจกลั้นน้ําตาสั่งว่า “ยกอาหารมาเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 32, 'พวกคนใช้ก็ยกส่วนของโยเซฟมาตั้งไว้เฉพาะท่าน ส่วนของพี่น้องก็เฉพาะพี่น้อง ส่วนของคนอียิปต์ที่จะมารับประทานด้วยนั้นก็เฉพาะเขา เพราะคนอียิปต์จะไม่รับประทานอาหารร่วมกับคนฮีบรู ด้วยว่าสิ่งนั้นเป็นสิ่งที่พึงรังเกียจสําหรับคนอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 33, 'พวกพี่น้องก็นั่งตรงหน้าโยเซฟ เรียงตั้งแต่พี่ใหญ่ผู้มีสิทธิบุตรหัวปี ลงมาจนถึงน้องสุดท้องตามวัย พี่น้องทั้งหลายมองดูตากันด้วยความประหลาดใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 34, 'แล้วโยเซฟก็ส่งของรับประทานให้พี่น้องเหล่านั้นต่อหน้าท่าน แต่ของที่ส่งให้เบนยามินนั้นมากกว่าของพี่ชายถึงห้าเท่า พวกเขาก็กินดื่มกับโยเซฟจนสําราญใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 1, 'โยเซฟสั่งคนต้นเรือนของท่านว่า “จัดอาหารใส่กระสอบของคนเหล่านี้ให้เต็มตามที่จะขนไปได้ และเอาเงินของเขาใส่ไว้ในปากกระสอบของทุกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 2, 'ใส่ถ้วยของเรา คือถ้วยเงินนั้นไว้ในปากกระสอบของคนสุดท้องกับเงินค่าข้าวของเขาด้วย” คนต้นเรือนก็ทําตามคําที่โยเซฟสั่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 3, 'ครั้นเวลารุ่งเช้าคนต้นเรือนก็ให้คนเหล่านั้นออกเดินไปพร้อมกับลาของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 4, 'เมื่อพี่น้องออกไปจากเมืองยังไม่สู้ไกลนักโยเซฟสั่งคนต้นเรือนว่า “ลุกขึ้นไปตามคนเหล่านั้น เมื่อไปทันแล้วให้ถามพวกเขาว่า ‘ทําไมพวกเจ้าจึงทําความชั่วตอบความดีเล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 5, 'ถ้วยนี้เป็นถ้วยเฉพาะที่เจ้านายของข้าใช้ดื่ม และใช้ทํานายมิใช่หรือ เจ้าทําเช่นนี้ผิดมาก’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 6, 'คนต้นเรือนตามพวกเขาไปทัน แล้วว่าแก่พี่น้องตามคําที่โยเซฟบอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 7, 'คนเหล่านั้นจึงตอบเขาว่า “เหตุไฉนเจ้านายของข้าพเจ้าจึงว่าอย่างนี้ พระเจ้าไม่ทรงโปรดให้ผู้รับใช้ของท่านกระทําเรื่องเช่นนี้เลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 8, 'ดูเถิด เงินที่ข้าพเจ้าพบในปากกระสอบของข้าพเจ้านั้น ข้าพเจ้ายังได้นํามาจากแผ่นดินคานาอันคืนแก่ท่าน ข้าพเจ้าทั้งหลายจะลักเงินทองไปจากบ้านนายของท่านได้อย่างไรเล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 9, 'หากท่านพบของนั้นที่ใครในพวกข้าพเจ้าผู้รับใช้ของท่านก็ให้ผู้นั้นตายเถิด และข้าพเจ้าทั้งหลายจะเป็นทาสเจ้านายของข้าพเจ้าด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 10, 'คนต้นเรือนจึงว่า “บัดนี้ให้เป็นไปตามคําที่ท่านว่า ถ้าเราพบของนั้นที่ผู้ใด ผู้นั้นจะต้องเป็นทาสของเรา แต่ท่านทั้งหลายหามีความผิดไม่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 11, 'พวกเขาทุกคนจึงรีบยกกระสอบของตนวางลงบนดินและเปิดกระสอบของตนออก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 12, 'คนต้นเรือนก็ค้นดูตั้งแต่คนหัวปีจนถึงคนสุดท้อง ก็พบถ้วยนั้นในกระสอบของเบนยามิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 13, 'พวกเขาก็ฉีกเสื้อผ้าของตน และบรรทุกขึ้นหลังลากลับมายังเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 14, 'ฝ่ายยูดาห์กับพวกพี่น้องก็มาบ้านโยเซฟ โยเซฟยังอยู่ที่นั่น พวกเขากราบลงถึงดินต่อหน้าท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 15, 'โยเซฟจึงถามเขาว่า “พวกเจ้าทําอะไรนี่ พวกเจ้าไม่รู้หรือว่าคนอย่างเราทํานายได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 16, 'ยูดาห์ตอบว่า “ข้าพเจ้าทั้งหลายจะตอบอย่างไรกับนายของข้าพเจ้า ข้าพเจ้าจะพูดอย่างไร หรือข้าพเจ้าจะแก้ตัวอย่างไรได้ พระเจ้าทรงทราบความชั่วช้าของพวกข้าพเจ้าผู้รับใช้ของท่านแล้ว ข้าแต่ท่าน ดูเถิด พวกข้าพเจ้าเป็นทาสของท่าน ทั้งข้าพเจ้าทั้งหลายกับคนที่เขาพบถ้วยอยู่นั้นด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 17, 'แต่โยเซฟตอบว่า “พระเจ้าไม่ทรงโปรดให้เรากระทําเช่นนั้น เฉพาะคนที่เขาพบถ้วยในมือนั้นจะเป็นทาสของเรา ส่วนพวกเจ้าจงกลับไปหาบิดาโดยสันติสุขเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 18, 'ยูดาห์จึงเข้าไปใกล้โยเซฟ เรียนว่า “โอ นายเจ้าข้า ข้าพเจ้าผู้รับใช้ของท่านขอกราบเรียนท่านสักคําหนึ่ง ขอท่านอย่าได้ถือโกรธข้าพเจ้าผู้รับใช้ของท่านเลย เพราะท่านก็เป็นเหมือนฟาโรห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 19, 'นายของข้าพเจ้าถามข้าพเจ้าทั้งหลายผู้รับใช้ของท่านว่า ‘เจ้ายังมีบิดาหรือน้องชายอยู่หรือ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 20, 'พวกข้าพเจ้าตอบนายของข้าพเจ้าว่า ‘ข้าพเจ้าทั้งหลายมีบิดาที่ชราแล้ว มีบุตรคนหนึ่งเกิดเมื่อบิดาชรา เป็นน้องเล็ก พี่ชายของเด็กนั้นตายเสียแล้ว บุตรของมารดานั้นยังอยู่แต่คนนี้คนเดียวและบิดารักเด็กคนนี้มาก’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 21, 'แล้วท่านสั่งข้าพเจ้าทั้งหลายผู้รับใช้ของท่านว่า ‘พาน้องคนนั้นมาที่นี่ให้เราดู’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 22, 'ข้าพเจ้าทั้งหลายเรียนนายของข้าพเจ้าว่า ‘เด็กหนุ่มคนนี้จะพรากจากบิดาไม่ได้เพราะถ้าจากบิดาไป บิดาจะตาย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 23, 'ท่านบอกข้าพเจ้าทั้งหลายผู้รับใช้ของท่านว่า ‘ถ้าเจ้าทั้งหลายไม่พาน้องชายสุดท้องมาด้วยกัน เจ้าจะไม่เห็นหน้าเราอีกเลย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 24, 'และต่อมาครั้นข้าพเจ้าไปหาบิดาผู้รับใช้ของท่านแล้ว ข้าพเจ้าทั้งหลายก็นําถ้อยคําของนายของข้าพเจ้าไปเล่าให้บิดาฟัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 25, 'และบิดาของข้าพเจ้าทั้งหลายสั่งว่า ‘จงกลับไปอีกซื้ออาหารมาให้พวกเราหน่อย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 26, 'ข้าพเจ้าทั้งหลายว่า ‘เราลงไปไม่ได้ ถ้าน้องชายสุดท้องไปด้วยเราจึงจะลงไป เพราะเราจะเห็นหน้าท่านนั้นไม่ได้ เว้นแต่น้องชายสุดท้องอยู่กับเรา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 27, 'บิดาผู้รับใช้ของท่านจึงบอกข้าพเจ้าทั้งหลายว่า ‘เจ้ารู้ว่าภรรยาของเราคลอดบุตรชายให้เราสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 28, 'บุตรคนหนึ่งก็จากเราไปแล้ว เราจึงว่า “สัตว์ร้ายกัดกินเขาเสียเป็นแน่” เราไม่ได้เห็นบุตรนั้นจนบัดนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 29, 'ถ้าพวกเจ้าเอาเด็กคนนี้ไปจากเราด้วย และเขาเป็นอันตรายขึ้น พวกเจ้าก็จะทําให้เราซึ่งมีผมหงอกลงสู่หลุมฝังศพด้วยความทุกข์’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 30, 'เหตุฉะนั้นบัดนี้เมื่อข้าพเจ้ากลับไปหาบิดาผู้รับใช้ของท่าน และเด็กหนุ่มนั้นมิได้กลับไปกับข้าพเจ้า เพราะชีวิตของท่านติดอยู่กับชีวิตของเด็ก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 31, 'และต่อมาเมื่อบิดาเห็นว่าเด็กนั้นไม่อยู่กับพวกข้าพเจ้า บิดาก็จะตาย ผู้รับใช้ของท่านจะเป็นเหตุให้บิดาผู้รับใช้ของท่านผู้มีผมหงอกลงสู่หลุมฝังศพด้วยความทุกข์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 32, 'เพราะข้าพเจ้าผู้รับใช้ของท่านรับประกันน้องไว้ต่อบิดาของข้าพเจ้าว่า ‘ถ้าข้าพเจ้าไม่พาน้องกลับมาหาบิดา ข้าพเจ้าจะรับผิดต่อบิดาตลอดไป’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 33, 'เพราะฉะนั้นบัดนี้ขอโปรดให้ข้าพเจ้าผู้รับใช้ของท่านอยู่แทนน้องโดยเป็นทาสของนายของข้าพเจ้า ขอให้น้องกลับไปกับพวกพี่ของตนเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 34, 'ด้วยว่าถ้าน้องมิได้อยู่กับข้าพเจ้า ข้าพเจ้าจะกลับไปหาบิดาของข้าพเจ้าอย่างไรได้ น่ากลัวว่าจะเห็นเหตุร้ายอุบัติขึ้นแก่บิดาข้าพเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 1, 'โยเซฟอดกลั้นต่อหน้าบรรดาผู้ที่ยืนอยู่ต่อไปอีกมิได้ ท่านก็ร้องสั่งว่า “ให้ทุกคนออกไปเสียเถิด” จึงไม่มีผู้ใดยืนอยู่กับท่านด้วย ขณะที่โยเซฟแจ้งให้พี่น้องรู้จักตัวท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 2, 'แล้วโยเซฟร้องไห้เสียงดัง คนอียิปต์ทั้งหลายและคนในสํานักพระราชวังฟาโรห์ก็ได้ยิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 3, 'โยเซฟบอกพวกพี่น้องของตนว่า “เราคือโยเซฟ บิดาเรายังมีชีวิตอยู่หรือ” ฝ่ายพวกพี่น้องไม่รู้ที่จะตอบประการใดเพราะตกใจกลัวที่เผชิญหน้ากับโยเซฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 4, 'โยเซฟจึงบอกพี่น้องของตนว่า “เชิญเข้ามาใกล้เราเถิด” เขาก็เข้ามาใกล้แล้วโยเซฟว่า “เราคือโยเซฟน้องที่พี่ขายมายังอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 5, 'ฉะนั้นบัดนี้อย่าเสียใจไปเลย อย่าโกรธตัวเองที่ขายเรามาที่นี่ เพราะว่าพระเจ้าทรงใช้เราให้มาก่อนหน้าพี่เพื่อจะได้ช่วยชีวิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 6, 'เพราะมีการกันดารอาหารในแผ่นดินสองปีแล้ว ยังอีกห้าปีจะทํานาหรือเกี่ยวข้าวไม่ได้เลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 7, 'พระเจ้าทรงใช้เรามาก่อนพี่ เพื่อสงวนหมู่คนจากพวกพี่ไว้บนแผ่นดิน และช่วยชีวิตของพี่ไว้ด้วยการช่วยให้พ้นอันใหญ่หลวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 8, 'ฉะนั้นบัดนี้มิใช่พี่เป็นผู้ให้เรามาที่นี่ แต่พระเจ้าทรงให้มา พระองค์ทรงโปรดให้เราเป็นเหมือนบิดาแก่ฟาโรห์ เป็นเจ้าในราชวังทั้งสิ้น และเป็นผู้ครอบครองประเทศอียิปต์ทั้งหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 9, 'เจ้าจงรีบขึ้นไปหาบิดาเราบอกท่านว่า ‘โยเซฟบุตรชายของท่านพูดดังนี้ว่า “พระเจ้าทรงโปรดให้ลูกเป็นเจ้าเหนืออียิปต์ทั้งสิ้น ขอลงมาหาลูก อย่าได้ช้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 10, 'พ่อจะได้อาศัยอยู่ในแผ่นดินโกเชน และพ่อจะได้อยู่ใกล้ลูก ทั้งตัวพ่อกับลูกหลานและฝูงแพะแกะ ฝูงวัว และทรัพย์ทั้งหมดของพ่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 11, 'ลูกจะบํารุงรักษาพ่อที่นั่น ด้วยยังจะกันดารอาหารอีกห้าปี มิฉะนั้นพ่อและครอบครัวของพ่อและผู้คนที่พ่อมีอยู่จะยากจนไป”’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 12, 'ดูเถิด นัยน์ตาพี่และนัยน์ตาของเบนยามินน้องชายของข้าพเจ้าได้เห็นว่าเป็นปากของข้าพเจ้าเองที่ได้พูดกับพี่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 13, 'พี่จงเล่าให้บิดาของเราฟังถึงยศศักดิ์ที่ข้าพเจ้ามีอยู่ในอียิปต์และที่พี่ได้เห็นนั้นทุกประการ พี่จงรีบพาบิดาเราลงมาที่นี่เถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 14, 'โยเซฟกอดคอเบนยามินผู้น้องแล้วร้องไห้ เบนยามินก็กอดคอโยเซฟร้องไห้เหมือนกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 15, 'ยิ่งกว่านั้นโยเซฟจึงจุบพี่ชายทั้งปวงและร้องไห้ หลังจากนั้นพี่น้องของท่านก็สนทนากับโยเซฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 16, 'ข่าวว่า “พี่น้องของโยเซฟมา” ไปถึงราชวังฟาโรห์ ฟาโรห์กับข้าราชการของพระองค์ก็พากันยินดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 17, 'ฟาโรห์รับสั่งกับโยเซฟว่า “พูดกับพี่น้องของท่านว่า ‘ทําดังนี้ คือเอาของบรรทุกสัตว์กลับไปแผ่นดินคานาอัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 18, 'พาบิดาและครอบครัวของเจ้ามาหาเรา เราจะประทานของดีที่สุดในแผ่นดินอียิปต์ให้พวกเจ้า พวกเจ้าจะได้รับประทานผลอันอุดมบริบูรณ์ของประเทศนี้’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 19, 'เราสั่งเจ้าแล้ว จงทําดังนี้ เอารถบรรทุกจากประเทศอียิปต์ไปรับเด็กเล็กๆและภรรยาของเจ้ากับนําบิดาของเจ้ามา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 20, 'อย่าเสียดายทรัพย์สมบัติเลย เพราะของดีที่สุดทั่วประเทศอียิปต์เป็นของเจ้าแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 21, 'บรรดาบุตรของอิสราเอลก็ทําตาม โยเซฟจัดรถบรรทุกให้เขาตามรับสั่งของฟาโรห์ กับให้เสบียงรับประทานตามทาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 22, 'โยเซฟให้เสื้อผ้าคนละสํารับ แต่ให้เงินแก่เบนยามินสามร้อยเหรียญกับเสื้อห้าสํารับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 23, 'โยเซฟฝากของต่อไปนี้ให้บิดา คือลาสิบตัวบรรทุกของดีที่สุดในประเทศอียิปต์ และลาตัวเมียอีกสิบตัวบรรทุกข้าว ขนมปัง และเสบียงอาหารสําหรับให้บิดารับประทานตามทาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 24, 'ดังนั้นโยเซฟส่งพี่น้องไป แล้วเขาก็ออกไป แล้วท่านสั่งเขาว่า “จงระวังให้ดีอย่าได้วิวาทกันตามทาง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 25, 'พวกพี่น้องก็พากันขึ้นไปจากอียิปต์เข้าไปในแผ่นดินคานาอันไปหายาโคบบิดาของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 26, 'บอกบิดาว่า “โยเซฟยังมีชีวิตอยู่ ท่านเป็นผู้ครอบครองประเทศอียิปต์ทั้งหมด” แต่จิตใจยาโคบงงงันเพราะยังไม่เชื่อเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 27, 'เขาจึงเล่าคําของโยเซฟให้บิดาฟังทุกประการ คือคําที่โยเซฟสั่งพวกเขาไว้ เมื่อยาโคบเห็นรถบรรทุกที่โยเซฟส่งมารับตน จิตใจของท่านก็ฟื้นแช่มชื่นขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 28, 'อิสราเอลจึงว่า “เราอิ่มใจแล้ว โยเซฟลูกเรายังมีชีวิตอยู่ เราจะไปเห็นลูกก่อนเราตาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 1, 'อิสราเอลเดินทางไปพร้อมกับทรัพย์ทั้งหมด มาถึงเมืองเบเออร์เชบา และถวายเครื่องบูชาแด่พระเจ้าของอิสอัคบิดาของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 2, 'พระเจ้าตรัสแก่อิสราเอลโดยนิมิตในเวลากลางคืนว่า “ยาโคบ ยาโคบเอ๋ย” ยาโคบทูลว่า “ข้าพระองค์อยู่ที่นี่พระเจ้าข้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 3, 'พระองค์จึงตรัสว่า “เราคือพระเจ้า คือพระเจ้าของบิดาเจ้า อย่ากลัวที่จะลงไปยังอียิปต์เพราะเราจะให้เจ้าเป็นประชาชาติใหญ่ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 4, 'เราจะลงไปกับเจ้าถึงอียิปต์ และเราจะพาเจ้าขึ้นมาอีกด้วยแน่ และโยเซฟจะวางมือบนตาเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 5, 'ยาโคบก็ยกไปจากเบเออร์เชบา บรรดาบุตรชายอิสราเอลก็พายาโคบบิดาขึ้นรถบรรทุกที่ฟาโรห์ส่งมารับไปกับลูกหลานเล็กๆและภรรยาของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 6, 'เขาพาฝูงสัตว์ของตนและทรัพย์ที่เขาได้มาในแผ่นดินคานาอันนั้นไปอียิปต์ ทั้งยาโคบกับบรรดาเชื้อสายของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 7, 'คือลูกหลานชายหญิงและเชื้อสายทั้งหมดของท่านเข้าไปในอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 8, 'ต่อไปนี้เป็นชื่อลูกหลานของอิสราเอลที่เข้าไปในอียิปต์ ทั้งยาโคบและบุตรชายของท่านคือ รูเบน บุตรหัวปีของยาโคบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 9, 'และบุตรชายของรูเบน คือ ฮาโนค ปัลลู เฮสโรน และคารมี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 10, 'บุตรชายของสิเมโอน คือ เยมูเอล ยามีน โอหาด ยาคีน และโศหาร์ กับชาอูล บุตรชายของหญิงคนคานาอัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 11, 'บุตรชายของเลวี คือ เกอร์โชน โคฮาท และเมรารี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 12, 'บุตรชายของยูดาห์คือ เอร์ โอนัน เช-ลาห์ เปเรศ เศ-ราห์ แต่เอร์และโอนันได้ถึงแก่ความตายในแผ่นดินคานาอัน บุตรชายของเปเรศคือ เฮสโรน และฮามูล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 13, 'บุตรชายของอิสสาคาร์ คือ โทลา ปูวาห์ โยบ และชิมโรน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 14, 'บุตรชายของเศบูลุน คือ เสเรด เอโลน และยาเลเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 15, 'พวกเหล่านี้เป็นบุตรชายของนางเลอาห์ ซึ่งนางคลอดให้ยาโคบในปัดดานอารัม กับบุตรสาวชื่อ ดีนาห์ บุตรชายหญิงหมดด้วยกันมีสามสิบสามคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 16, 'บุตรชายของกาด คือ ศิฟีโอน ฮักกี ชูนี เอสโบน เอรี อาโรดี และอาเรลี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 17, 'บุตรชายของอาเชอร์ คือ ยิมนาห์ อิชอูอาห์ อิชวี และเบรียาห์ กับเสราห์น้องสาวของเขา และบุตรชายของเบรียาห์คือ เฮเบอร์และมัลคีเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 18, 'พวกเหล่านี้เป็นบุตรชายของนางศิลปาห์ ผู้ที่ลาบันยกให้แก่นางเลอาห์บุตรสาวของตน และบุตรสิบหกคนนี้นางคลอดให้ยาโคบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 19, 'บุตรชายของนางราเชลภรรยายาโคบคือ โยเซฟและเบนยามิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 20, 'มนัสเสห์กับเอฟราอิม เกิดแก่โยเซฟในแผ่นดินอียิปต์ ซึ่งนางอาเสนัทบุตรสาวของโปทิเฟรา ปุโรหิตเมืองโอนคลอดให้ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 21, 'บุตรชายของเบนยามินคือ เบลา เบเคอร์ อัชเบล เก-รา นาอามาน เอไฮ โรช มุปปิม หุปปิม และอาร์ด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 22, 'พวกเหล่านี้เป็นบุตรชายของนางราเชลที่เกิดแก่ยาโคบ มีสิบสี่คนด้วยกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 23, 'บุตรชายของดานคือ หุชิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 24, 'บุตรชายของนัฟทาลีคือ ยาเซเอล กูนี เยเซอร์ และชิลเลม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 25, 'พวกเหล่านี้เป็นบุตรชายของนางบิลฮาห์ ผู้ที่ลาบันยกให้แก่นางราเชลบุตรสาวของตน และบุตรเจ็ดคนนี้นางคลอดให้ยาโคบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 26, 'บรรดาคนของยาโคบซึ่งออกมาจากบั้นเอวของท่านที่เข้ามาในอียิปต์นั้น ไม่นับภรรยาของบุตรชายยาโคบ มีหกสิบหกคนด้วยกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 27, 'บุตรชายของโยเซฟซึ่งเกิดแก่ท่านในอียิปต์มีสองคน นับคนทั้งปวงในครอบครัวของยาโคบที่เข้ามาในอียิปต์ได้เจ็ดสิบคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 28, 'ยาโคบให้ยูดาห์ล่วงหน้าไปหาโยเซฟเพื่อจะนําหน้าไปยังเมืองโกเชน แล้วพวกเขาก็มาถึงแผ่นดินโกเชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 29, 'โยเซฟก็จัดรถม้าของตนขึ้นไปยังเมืองโกเชนรับอิสราเอลบิดาของตน พอเห็นบิดาท่านก็กอดคอบิดาไว้ร้องไห้เป็นเวลานาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 30, 'อิสราเอลพูดกับโยเซฟว่า “เดี๋ยวนี้พ่อจะตายก็ตามเถิด เพราะพ่อได้เห็นหน้าเจ้าแล้วและรู้ว่าเจ้ายังมีชีวิตอยู่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 31, 'โยเซฟจึงบอกพี่น้องและครอบครัวของบิดาว่า “เราจะขึ้นไปแสดงแก่ฟาโรห์และทูลแก่พระองค์ว่า ‘พี่น้องและครอบครัวของบิดาผู้เคยอยู่ในแผ่นดินคานาอันนั้นมาหาข้าพระองค์แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 32, 'คนเหล่านั้นเป็นผู้เลี้ยงแกะมีอาชีพเลี้ยงสัตว์ เขาพาฝูงแพะแกะ ฝูงวัวกับทรัพย์สมบัติของเขาทั้งสิ้นมาด้วย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 33, 'และต่อมาเมื่อฟาโรห์จะรับสั่งให้ท่านเข้าเฝ้าและจะถามว่า ‘พวกเจ้าเคยทํามาหาเลี้ยงชีพอย่างไร’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 34, 'ท่านทั้งหลายจงทูลว่า ‘การทํามาหาเลี้ยงชีพของผู้รับใช้ของพระองค์นั้นเกี่ยวข้องกับพวกสัตว์ใช้งานตั้งแต่เป็นเด็กมาจนทุกวันนี้ ทั้งข้าพระองค์ทั้งหลายและบรรพบุรุษของข้าพระองค์ด้วย’ เพื่อท่านทั้งหลายจะได้อาศัยอยู่ในแผ่นดินโกเชน เหตุว่าคนเลี้ยงแพะแกะทุกคนนั้นเป็นที่พึงรังเกียจสําหรับชาวอียิปต์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 1, 'โยเซฟเข้าไปทูลฟาโรห์ว่า “บิดาและพี่น้องของข้าพระองค์กับฝูงแพะแกะฝูงวัวและทรัพย์สมบัติของเขาทั้งสิ้นมาจากแผ่นดินคานาอันแล้ว ดูเถิด พวกเขาอยู่ในแผ่นดินโกเชน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 2, 'โยเซฟเลือกคนจากหมู่พี่น้อง คือผู้ชายห้าคนพาไปเฝ้าฟาโรห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 3, 'ฟาโรห์ตรัสถามพี่น้องของโยเซฟว่า “พวกเจ้าเคยทํามาหาเลี้ยงชีพอย่างไร” เขาทูลฟาโรห์ว่า “ผู้รับใช้ของพระองค์เป็นผู้เลี้ยงแพะแกะ ทั้งพวกข้าพระองค์และบรรพบุรุษของพวกข้าพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 4, 'เขาทูลฟาโรห์อีกว่า “พวกข้าพระองค์มาอาศัยอยู่ในแผ่นดินนี้เพราะไม่มีทุ่งหญ้าจะเลี้ยงสัตว์ของข้าพระองค์ผู้รับใช้ของพระองค์ เพราะเหตุว่าในแผ่นดินคานาอันนั้นกันดารอาหารนัก เหตุฉะนี้บัดนี้ ขอโปรดให้ข้าพระองค์ผู้รับใช้ของพระองค์อาศัยอยู่ในแผ่นดินโกเชนเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 5, 'ฟาโรห์จึงตรัสแก่โยเซฟว่า “บิดาและพี่น้องของท่านมาหาท่านแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 6, 'ท่านมีประเทศอียิปต์อยู่ต่อหน้า ให้บิดาและพี่น้องของท่านตั้งหลักแหล่งอยู่ในแผ่นดินดีที่สุดคือให้เขาอยู่แผ่นดินโกเชน แล้วในพวกพี่น้องนั้น ถ้าท่านรู้ว่าผู้ใดเป็นคนมีความสามารถ จงตั้งผู้นั้นให้เป็นหัวหน้ากองเลี้ยงสัตว์ของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 7, 'โยเซฟก็พายาโคบบิดาของท่านเข้าเฝ้าฟาโรห์ ยาโคบก็ถวายพระพรแก่ฟาโรห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 8, 'ฟาโรห์จึงตรัสถามยาโคบว่า “อายุท่านได้เท่าไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 9, 'ยาโคบทูลตอบฟาโรห์ว่า “ข้าพระองค์ดํารงชีวิตสัญจรอยู่นับได้ร้อยสามสิบปี ชีวิตของข้าพระองค์สั้นและมีความลําบาก ไม่เท่าอายุบรรพบุรุษของข้าพระองค์ในวันที่ดํารงชีวิตสัญจรอยู่นั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 10, 'ยาโคบถวายพระพรแก่ฟาโรห์ แล้วทูลลาไปจากฟาโรห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 11, 'ฝ่ายโยเซฟให้บิดาและพวกพี่น้องของตนอยู่และถือกรรมสิทธิ์ที่ดินในประเทศอียิปต์ ในแผ่นดินที่ดีที่สุดคือ ในแผ่นดินราเมเสส ตามรับสั่งของฟาโรห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 12, 'โยเซฟเลี้ยงดูบิดาและพวกพี่น้องรวมทั้งครอบครัวของบิดา ให้มีอาหารรับประทานตามจํานวนคนในครอบครัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 13, 'และทั่วแผ่นดินขาดอาหารเพราะการกันดารอาหารร้ายแรง จนแผ่นดินอียิปต์และแผ่นดินคานาอันทั้งสิ้นหิวโหยเพราะการกันดารอาหาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 14, 'โยเซฟรวบรวมเงินทั้งหมดที่ได้จากการขายข้าวในประเทศอียิปต์และแผ่นดินคานาอัน และโยเซฟนําเงินนั้นไปไว้ในราชวังฟาโรห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 15, 'เมื่อเงินในประเทศอียิปต์และแผ่นดินคานาอันหมดแล้ว ชาวอียิปต์ทั้งปวงมากราบเรียนโยเซฟว่า “ขออาหารให้พวกข้าพเจ้าเถิด เหตุใดพวกข้าพเจ้าจะต้องอดตายต่อหน้าท่านเพราะเงินหมดเล่า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 16, 'โยเซฟจึงบอกว่า “ถ้าเงินหมดแล้วจงเอาฝูงสัตว์ของเจ้ามาและเราจะให้ข้าวแลกกับสัตว์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 17, 'เขาก็นําฝูงสัตว์มาให้โยเซฟ โยเซฟก็ให้อาหารแก่เขาแลกกับม้า แพะแกะ ฝูงวัวและลา ในปีนั้นท่านจ่ายอาหารแลกกับสัตว์ต่างๆของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 18, 'เมื่อปีนั้นสิ้นสุดลงแล้ว เขาก็มาหาท่านในปีที่สองกราบเรียนท่านว่า “พวกข้าพเจ้าจะไม่ปิดบังเรื่องนี้ไว้จากนายของข้าพเจ้าว่า เงินของข้าพเจ้าหมดแล้วและฝูงสัตว์ของข้าพเจ้าก็เป็นของนายแล้วด้วย ข้าพเจ้าไม่มีสิ่งใดเหลือในสายตาของท่านเลย เว้นแต่ตัวข้าพเจ้ากับที่ดินเท่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 19, 'เหตุใดข้าพเจ้าทั้งหลายจะต้องอดตายต่อหน้าต่อตาท่านเล่า ทั้งตัวข้าพเจ้ากับที่ดินของข้าพเจ้าทั้งหลายด้วย ขอท่านโปรดซื้อพวกข้าพเจ้ากับที่ดินแลกกับอาหาร ข้าพเจ้าทั้งหลายกับที่ดินจะเป็นทาสของฟาโรห์ ขอท่านโปรดให้เมล็ดข้าวแก่พวกข้าพเจ้า เพื่อข้าพเจ้าทั้งหลายจะมีชีวิตอยู่ได้และไม่ตายเพื่อที่ดินนั้นจะไม่รกร้างไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 20, 'โยเซฟก็ซื้อที่ดินทั้งหมดในอียิปต์ให้แก่ฟาโรห์ เพราะคนอียิปต์ทุกคนขายไร่นาของตนเนื่องจากการกันดารอาหารรุนแรงต่อเขายิ่งนัก เพราะฉะนั้นแผ่นดินจึงตกเป็นของฟาโรห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 21, 'ส่วนประชาชนเหล่านั้นโยเซฟให้เขาย้ายไปอยู่ที่เมืองต่างๆทั่วประเทศอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 22, 'เว้นแต่ที่ดินของพวกปุโรหิตเท่านั้นโยเซฟไม่ได้ซื้อ เพราะปุโรหิตได้รับส่วนแบ่งจากฟาโรห์ และดํารงชีวิตอาศัยตามส่วนที่ฟาโรห์พระราชทาน เหตุฉะนี้เขาจึงไม่ได้ขายที่ดินของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 23, 'โยเซฟชี้แจงแก่ประชาชนทั้งปวงว่า “ดูเถิด วันนี้เราซื้อตัวพวกเจ้ากับที่ดินของเจ้าให้เป็นของฟาโรห์แล้ว นี่เราจะให้เมล็ดข้าวแก่พวกเจ้าและพวกเจ้าจงเอาไปหว่านเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 24, 'และต่อมาเมื่อได้ผลแล้วจงถวายส่วนหนึ่งในห้าส่วนแก่ฟาโรห์ เก็บสี่ส่วนไว้เป็นของตน สําหรับใช้เป็นเมล็ดข้าวบ้าง เป็นอาหารสําหรับเจ้าและครอบครัวกับเด็กเล็กบ้าง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 25, 'คนทั้งหลายก็กล่าวว่า “ท่านช่วยชีวิตข้าพเจ้าไว้ ขอให้ข้าพเจ้าทั้งหลายได้รับความกรุณาในสายตาของนายข้าพเจ้าเถิด ข้าพเจ้าทั้งหลายยอมเป็นทาสของฟาโรห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 26, 'โยเซฟตั้งเป็นกฎหมายในประเทศอียิปต์ตราบเท่าทุกวันนี้ว่า ให้ฟาโรห์ได้ส่วนหนึ่งในห้าส่วน เว้นแต่ที่ดินของปุโรหิตเท่านั้นไม่ตกเป็นของฟาโรห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 27, 'พวกอิสราเอลอาศัยอยู่ในประเทศอียิปต์ ณ แผ่นดินโกเชน เขามีทรัพย์สมบัติที่นั่น และมีลูกหลานทวีขึ้นมากมาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 28, 'ยาโคบมีชีวิตอยู่ในแผ่นดินอียิปต์สิบเจ็ดปี รวมอายุยาโคบได้ร้อยสี่สิบเจ็ดปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 29, 'เวลาที่อิสราเอลจะสิ้นชีพก็ใกล้เข้ามาแล้ว ท่านจึงเรียกโยเซฟบุตรชายท่านมาสั่งว่า “ถ้าเดี๋ยวนี้เราได้รับความกรุณาในสายตาของเจ้า เราขอร้องให้เจ้าเอามือของเจ้าวางไว้ใต้ขาอ่อนของเรา และปฏิบัติต่อเราด้วยความเมตตากรุณาและจริงใจ ขอเจ้าโปรดอย่าฝังศพเราไว้ในอียิปต์เลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 30, 'แต่เราจะถูกฝังไว้กับบรรพบุรุษของเรา แล้วเจ้าจงนําเราออกจากอียิปต์ไปฝังไว้ ณ ที่ฝังศพบิดาเราเถิด” โยเซฟก็สัญญาว่า “ข้าพเจ้าจะกระทําตามที่ท่านสั่ง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 31, 'อิสราเอลจึงบอกว่า “จงปฏิญาณตัวให้เราด้วย” โยเซฟก็ปฏิญาณให้บิดา แล้วอิสราเอลก็กราบลงที่บนหัวนอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 1, 'และต่อมาภายหลังเหตุการณ์เหล่านี้มีคนเรียนโยเซฟว่า “ดูเถิด บิดาของท่านป่วย” โยเซฟก็พามนัสเสห์และเอฟราอิมบุตรชายทั้งสองของตนไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 2, 'มีคนบอกยาโคบว่า “ดูเถิด โยเซฟบุตรชายมาหาท่าน” อิสราเอลก็รวบรวมกําลังลุกขึ้นนั่งบนที่นอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 3, 'ยาโคบจึงพูดกับโยเซฟว่า “พระเจ้าผู้ทรงมหิทธิฤทธิ์ได้สําแดงพระองค์แก่พ่อที่ตําบลลูสในแผ่นดินคานาอัน และทรงอวยพระพรแก่พ่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 4, 'และตรัสแก่พ่อว่า ‘ดูเถิด เราจะให้เจ้ามีลูกดกทวียิ่งขึ้นและเราจะทําให้เจ้าเป็นชนชาติใหญ่ และจะยกแผ่นดินนี้ให้แก่เชื้อสายของเจ้าที่มาภายหลังเจ้าเป็นกรรมสิทธิ์เป็นนิตย์’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 5, 'ส่วนบุตรชายทั้งสองของเจ้าที่เกิดแก่เจ้าในประเทศอียิปต์ก่อนพ่อมาหาเจ้าในอียิปต์ก็เป็นบุตรของพ่อ เอฟราอิมและมนัสเสห์จะต้องเป็นของพ่อ เหมือนรูเบนและสิเมโอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 6, 'ส่วนบุตรของเจ้า ที่เกิดมาภายหลังเขาจะนับเป็นบุตรของเจ้า เขาจะได้ชื่อตามพี่ชายในการรับมรดกของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 7, 'และสําหรับพ่อเมื่อพ่อจากปัดดานมา นางราเชลซึ่งอยู่กับพ่อก็ได้สิ้นชีวิตในแผ่นดินคานาอันขณะอยู่ตามทางยังห่างจากเอฟราธาห์ แล้วพ่อได้ฝังศพเธอไว้ริมทางไปเอฟราธาห์คือเบธเลเฮม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 8, 'อิสราเอลเห็นบุตรชายทั้งสองของโยเซฟจึงถามว่า “นี่ใคร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 9, 'โยเซฟตอบบิดาของตนว่า “นี่เป็นบุตรชายของลูกที่พระเจ้าประทานแก่ลูกในแผ่นดินนี้” อิสราเอลจึงว่า “ขอเจ้าพาบุตรทั้งสองเข้ามาเพื่อพ่อจะได้ให้พรแก่เขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 10, 'คราวนั้นตาของอิสราเอลมืดมัวไปเพราะชรา มองอะไรไม่เห็น โยเซฟพาบุตรเข้ามาใกล้บิดา บิดาก็จุบกอดเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 11, 'อิสราเอลบอกโยเซฟว่า “แต่ก่อนพ่อคิดว่าจะไม่ได้เห็นหน้าเจ้า แต่ดูเถิด พระเจ้าทรงโปรดให้พ่อเห็นทั้งเชื้อสายของเจ้าด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 12, 'โยเซฟเอาบุตรออกมาจากระหว่างเข่าของท่าน แล้วกราบลงถึงดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 13, 'โยเซฟจูงบุตรทั้งสองเข้าไปใกล้บิดา มือขวาจับเอฟราอิมให้อยู่ข้างซ้ายอิสราเอล และมือซ้ายจับมนัสเสห์ให้อยู่ข้างขวาอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 14, 'ฝ่ายอิสราเอลก็เหยียดมือขวาออกวางบนศีรษะเอฟราอิมผู้เป็นน้อง และมือซ้ายวางไว้บนศีรษะมนัสเสห์ โดยตั้งใจเหยียดมือออกเช่นนั้น เพราะมนัสเสห์เป็นบุตรหัวปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 15, 'แล้วอิสราเอลกล่าวคําอวยพรแก่โยเซฟว่า “ขอพระเจ้าที่อับราฮัมและอิสอัคบิดาข้าพเจ้าดําเนินอยู่เฉพาะพระพักตร์นั้น ขอพระเจ้าผู้ทรงบํารุงเลี้ยงชีวิตข้าพเจ้าตั้งแต่เกิดมาจนวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 16, 'ขอทูตสวรรค์ที่ได้ช่วยข้าพเจ้าให้พ้นจากความชั่วร้ายทั้งสิ้น โปรดอวยพรแก่เด็กหนุ่มทั้งสองนี้ ให้เขาสืบชื่อของข้าพเจ้าและชื่อของอับราฮัมและชื่อของอิสอัคบิดาของข้าพเจ้าไว้และขอให้เขาเจริญขึ้นเป็นมวลชนบนแผ่นดินเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 17, 'ฝ่ายโยเซฟเมื่อเห็นบิดาวางมือข้างขวาบนศีรษะของเอฟราอิมก็ไม่พอใจ จึงจับมือบิดาจะยกจากศีรษะเอฟราอิมวางบนศีรษะมนัสเสห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 18, 'โยเซฟพูดกับบิดาของตนว่า “ไม่ถูก บิดาของข้าพเจ้า เพราะคนนี้เป็นหัวปี ขอท่านวางมือขวาบนศีรษะคนนี้เถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 19, 'บิดาก็ไม่ยอมจึงตอบว่า “พ่อรู้แล้ว ลูกเอ๋ย พ่อรู้แล้ว เขาจะเป็นคนตระกูลหนึ่งด้วย และเขาจะใหญ่โตด้วย แต่แท้จริงน้องชายจะใหญ่โตกว่าพี่ และเชื้อสายของน้องนั้นจะเป็นคนหลายประชาชาติด้วยกัน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 20, 'วันนั้นอิสราเอลก็ให้พรแก่ทั้งสองคนว่า “พวกอิสราเอลจะใช้ชื่อเจ้าให้พรว่า ‘ขอพระเจ้าทรงโปรดให้ท่านเป็นเหมือนเอฟราอิมและเหมือนมนัสเสห์เถิด’” อิสราเอลจึงให้เอฟราอิมเป็นใหญ่กว่ามนัสเสห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 21, 'อิสราเอลบอกโยเซฟว่า “ดูเถิด พ่อจะตายแล้ว แต่พระเจ้าจะทรงสถิตอยู่กับพวกเจ้าและจะพาพวกเจ้ากลับไปสู่แผ่นดินของบรรพบุรุษของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 22, 'ยิ่งกว่านั้นอีก พ่อจะยกส่วนหนึ่งที่พ่อตีได้จากมือคนอาโมไรต์ด้วยดาบและธนูของพ่อนั้นให้แก่เจ้าแทนที่จะให้พี่น้องของเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 1, 'ยาโคบเรียกบรรดาบุตรชายของตนมา สั่งว่า “พวกเจ้ามาชุมนุมกันแล้วเราจะบอกเหตุที่จะบังเกิดแก่เจ้าในยุคสุดท้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 2, 'บุตรชายของยาโคบเอ๋ย จงมาประชุมกันฟัง จงฟังคําอิสราเอลบิดาของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 3, 'รูเบนเอ๋ย เจ้าเป็นบุตรหัวปีของเรา เป็นกําลังและเป็นผลแรกแห่งเรี่ยวแรงของเรา เป็นยอดแห่งความมีเกียรติและยอดของความรุนแรง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 4, 'เจ้าไม่มั่นคงเหมือนดั่งน้ํา จึงเป็นยอดไม่ได้ ด้วยเจ้าล่วงเข้าไปถึงที่นอนบิดาของเจ้า เจ้าทําให้ที่นอนนั้นเป็นมลทิน เขาล่วงเข้าไปถึงที่นอนของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 5, 'สิเมโอนกับเลวีเป็นพี่น้องกัน เครื่องอาวุธร้ายกาจอยู่ในที่อาศัยของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 6, 'โอ จิตวิญญาณของเราเอ๋ย อย่าเข้าไปในที่ลึกลับของเขา ยศบรรดาศักดิ์ของเราเอ๋ย อย่าเข้าร่วมในที่ประชุมของเขาเลย เหตุว่าเขาฆ่าคนด้วยความโกรธ เขาทําลายกําแพงเมืองตามอําเภอใจเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 7, 'ให้ความโกรธอันรุนแรงของเขาเป็นที่แช่ง ให้ความโทโสดุร้ายของเขาเป็นที่สาปเถิด เราจะให้เขาแตกแยกกันในพวกยาโคบ จะให้เขาพลัดพรากไปในพวกอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 8, 'ยูดาห์เอ๋ย พวกพี่น้องจะสรรเสริญเจ้า มือของเจ้าจะจับคอของศัตรูของเจ้า บุตรทั้งหลายของบิดาจะกราบเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 9, 'ยูดาห์เป็นลูกสิงโต ลูกเอ๋ย เจ้าก็ได้ลุกขึ้นจากการจับสัตว์ เขาก้มลง เขาหมอบลงเหมือนสิงโตตัวผู้ และเหมือนสิงโตแก่ ใครจะแหย่เขาให้ลุกขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 10, 'ธารพระกรจะไม่ขาดไปจากยูดาห์ หรือผู้ทรงตั้งพระราชบัญญัติจะไม่ขาดไปจากหว่างเท้าของเขา จนกว่าชีโลห์จะมา และชนชาติทั้งหลายจะรวบรวมเข้ากับผู้นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 11, 'เขาผูกลาของเขาไว้ที่เถาองุ่น และผูกลูกลาของเขาไว้ที่เถาองุ่นดีที่สุด เขาซักผ้าของเขาด้วยน้ําองุ่น เขาซักเสื้อผ้าของเขาด้วยเลือดแห่งผลองุ่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 12, 'ตาเขาจะแดงด้วยน้ําองุ่น และฟันเขาขาวด้วยน้ํานม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 13, 'เศบูลุนจะอาศัยอยู่ที่ท่าเรือริมทะเล เขาจะเป็นท่าจอดเรือ เขตแดนของเขาจะต่อกันไปถึงเมืองไซดอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 14, 'ฝ่ายอิสสาคาร์เป็นตัวลามีกําลังมากหมอบลงกลางสัมภาระของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 15, 'เขาเห็นว่าที่พักดีและแผ่นดินสบาย จึงย่อบ่าของตนลงรับไว้ ยอมเป็นทาสรับใช้การงาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 16, 'ส่วนดานจะปกครองพลไพร่ของตน เหมือนเป็นตระกูลหนึ่งในอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 17, 'ดานจะเป็นงูอยู่ตามทาง เป็นงูพิษที่อยู่ในหนทางที่กัดส้นเท้าม้า ให้คนขี่ตกหงายลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 18, 'โอ ข้าแต่พระเยโฮวาห์ ข้าพระองค์รอคอยความรอดจากพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 19, 'ฝ่ายกาดนั้นจะมีกองทัพมาย่ํายีเขา แต่ในที่สุดเขาจะกลับตามไล่ตีกองทัพนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 20, 'อาหารบริบูรณ์จะเกิดจากอาเชอร์ และเขาจะผลิตเครื่องเสวยสําหรับกษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 21, 'นัฟทาลีเป็นกวางตัวเมียที่ปลดปล่อย เขากล่าวคําอันไพเราะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 22, 'โยเซฟเป็นกิ่งที่เกิดผลดก เป็นกิ่งที่เกิดผลดกอยู่ริมบ่อน้ํา มีกิ่งพาดข้ามกําแพง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 23, 'พวกพรานธนูได้ทําให้เขาทุกข์โศก ทั้งยิงและเกลียดชังเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 24, 'แต่ธนูของเขาเองยืนหยัดต่อสู้ ลําแขนของเขามีกําลังขึ้นโดยพระหัตถ์ของพระเจ้าผู้ทรงเดชานุภาพของยาโคบ (ผู้เลี้ยงแกะคือศิลาแห่งอิสราเอลมาจากพระองค์นั้น)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 25, 'โดยพระเจ้าของบิดาเจ้าผู้จะทรงช่วยเจ้า โดยพระองค์ทรงศักดานุภาพใหญ่ยิ่ง ผู้จะทรงอวยพระพรแก่เจ้าด้วยพรที่มาจากฟ้าเบื้องบน พรที่มาจากใต้ทะเลเบื้องล่าง พรที่มาจากนมและครรภ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 26, 'ส่วนพรที่มาจากบิดาของเจ้า มีมากกว่าพรที่มาจากบรรพบุรุษของเรา จนถึงที่สุดแห่งเนินเขาเนืองนิตย์ ขอพรเหล่านั้นอยู่บนศีรษะของโยเซฟ และอยู่เบื้องบนกระหม่อมศีรษะแห่งผู้ที่ต้องพรากจากพี่น้อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 27, 'ฝ่ายเบนยามินจะล่าเหยื่อเหมือนสุนัขป่า เวลาเช้าเขาจะกินเหยื่อเสีย เวลาเย็นเขาจะแบ่งปันของที่แย่งชิงไว้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 28, 'ทั้งหมดนี้เป็นตระกูลทั้งสิบสองของอิสราเอล นี่เป็นถ้อยคําที่บิดากล่าวไว้แก่เขาและอวยพรเขา ยาโคบให้พรแก่ทุกคนอย่างเหมาะสมกับแต่ละคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 29, 'ยาโคบกําชับเขาและกล่าวแก่เขาว่า “เราจะไปอยู่ร่วมกับบรรพบุรุษของเรา จงฝังเราไว้กับบรรพบุรุษของเราในถ้ําที่นาของเอโฟรนคนฮิตไทต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 30, 'ในถ้ําที่อยู่ในนาชื่อมัคเป-ลาห์ หน้ามัมเรในแผ่นดินคานาอัน ซึ่งอับราฮัมได้ซื้อกับนาของเอโฟรนคนฮิตไทต์ไว้เป็นกรรมสิทธิ์เพื่อใช้เป็นสุสาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 31, 'ณ ที่นั่น เขาฝังศพอับราฮัม และซาราห์ภรรยาของเขา ที่นั่นเขาได้ฝังศพอิสอัคและเรเบคาห์ภรรยาของเขา และที่นั่นเราฝังศพเลอาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 32, 'นากับถ้ําที่อยู่ในนานั้นเราซื้อจากลูกหลานของเฮท”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 33, 'เมื่อยาโคบสั่งบุตรชายของตนเสร็จแล้ว ก็ยกเท้าขึ้นบนที่นอน แล้วก็สิ้นลมหายใจ และถูกรวบรวมไปอยู่กับบรรพบุรุษของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 1, 'โยเซฟซบหน้าลงที่หน้าบิดาแล้วร้องไห้และจุบท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 2, 'โยเซฟบัญชาพวกหมอที่เป็นข้าราชการของตน ให้อาบยารักษาศพบิดาไว้ พวกหมอก็อาบยารักษาศพอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 3, 'เขาทําการอาบยารักษาศพนั้นถึงสี่สิบวัน จึงสําเร็จเวลาของการอาบยารักษาศพ ชาวอียิปต์ก็ไว้ทุกข์ให้อิสราเอลถึงเจ็ดสิบวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 4, 'เมื่อวันเวลาที่ไว้ทุกข์ให้ท่านผ่านพ้นไปแล้ว โยเซฟก็เรียนข้าราชสํานักของฟาโรห์ว่า “ถ้าบัดนี้ข้าพเจ้าได้รับความกรุณาในสายตาของท่าน ขอโปรดไปทูลที่พระกรรณของฟาโรห์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 5, 'บิดาให้เราปฏิญาณไว้ โดยกล่าวว่า ‘ดูเถิด พ่อจวนจะตายแล้ว จงเอาศพพ่อไปฝังไว้ในอุโมงค์ที่พ่อได้ขุดไว้สําหรับพ่อ ณ แผ่นดินคานาอัน’ เหตุฉะนั้นบัดนี้ขออนุญาตให้ข้าพเจ้าขึ้นไปฝังศพบิดาแล้วข้าพเจ้าจะกลับมาอีก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 6, 'ฟาโรห์ก็รับสั่งว่า “จงขึ้นไปฝังศพบิดาของท่านตามคําที่บิดาให้ท่านปฏิญาณไว้นั้นเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 7, 'โยเซฟจึงขึ้นไปฝังศพบิดา พวกข้าราชการของฟาโรห์ ผู้ใหญ่ในราชสํานักและบรรดาผู้ใหญ่ทั่วแผ่นดินอียิปต์ทั้งสิ้นก็ตามไปด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 8, 'กับครอบครัวทั้งหมดของโยเซฟ พวกพี่น้องและครอบครัวของบิดาท่านก็ไปด้วยเหมือนกัน เว้นแต่เด็กเล็กๆและฝูงแพะแกะฝูงวัวเท่านั้น เขาให้อยู่ในแผ่นดินโกเชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 9, 'มีขบวนราชรถ ขบวนม้าไปกับท่าน เป็นขบวนใหญ่มาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 10, 'เขาก็พากันมาถึงลานนวดข้าวแห่งอาทาด ซึ่งอยู่ฟากแม่น้ําจอร์แดนข้างโน้น ที่นั้นเขาร้องไห้คร่ําครวญเป็นอันมาก โยเซฟก็ไว้ทุกข์ให้บิดาเจ็ดวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 11, 'เมื่อชาวแผ่นดินนั้นคือคนคานาอันได้เห็นการไว้ทุกข์ที่ลานอาทาด เขาจึงพูดกันว่า “นี่เป็นการไว้ทุกข์ใหญ่ของชาวอียิปต์” เหตุฉะนั้นเขาจึงเรียกชื่อตําบลนั้นว่า อาเบลมิสราอิม ตําบลนั้นอยู่ฟากแม่น้ําจอร์แดนข้างโน้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 12, 'บุตรชายยาโคบกระทําตามคําที่ท่านสั่งเขาไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 13, 'คือบรรดาบุตรชายเชิญศพไปยังแผ่นดินคานาอัน แล้วฝังไว้ในถ้ําที่อยู่ในนาชื่อมัคเป-ลาห์ ซึ่งอับราฮัมซื้อไว้กับนาจากเอโฟรนคนฮิตไทต์เป็นกรรมสิทธิ์เพื่อใช้เป็นสุสาน อยู่หน้ามัมเร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 14, 'เมื่อฝังศพบิดาแล้ว โยเซฟก็กลับมายังอียิปต์ ทั้งท่านกับพวกพี่น้องและคนทั้งปวงที่ไปในงานฝังศพบิดาของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 15, 'เมื่อพวกพี่ชายของโยเซฟเห็นว่าบิดาสิ้นชีวิตแล้ว เขาจึงพูดว่า “บางทีโยเซฟจะชังพวกเรา และจะแก้แค้นพวกเราแน่นอนเพราะการประทุษร้ายที่พวกเราเคยกระทําแก่เขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 16, 'พวกพี่ก็ใช้คนไปเรียนโยเซฟว่า “บิดาท่านเมื่อก่อนจะสิ้นใจนั้นสั่งไว้ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 17, '‘พวกเจ้าจงเรียนโยเซฟว่า บัดนี้เราขอท่านโปรดให้อภัยการละเมิดและบาปของพวกพี่ชายที่ประทุษร้ายท่าน’ บัดนี้ขอท่านโปรดให้อภัยการละเมิดของข้าพเจ้าทั้งหลายผู้รับใช้ของพระเจ้าของบิดาท่าน” โยเซฟจึงร้องไห้เมื่อฟังพี่ชายเรียนดังนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 18, 'พี่ชายก็พากันมากราบลงต่อหน้าโยเซฟด้วยว่า “ดูเถิด ข้าพเจ้าทั้งหลายเป็นผู้รับใช้ของท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 19, 'โยเซฟจึงบอกเขาว่า “อย่ากลัวเลย เราเป็นดังพระเจ้าหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 20, 'สําหรับพวกท่าน พวกท่านคิดร้ายต่อเราก็จริง แต่ฝ่ายพระเจ้าทรงดําริให้เกิดผลดีอย่างที่บังเกิดขึ้นแล้วในวันนี้ คือช่วยชีวิตคนเป็นอันมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 21, 'ฉะนั้นบัดนี้พี่อย่ากลัวเลย เราจะบํารุงเลี้ยงพี่ทั้งบุตรด้วย” โยเซฟพูดปลอบโยนพวกพี่น้องและพูดอย่างกรุณาต่อเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 22, 'โยเซฟอาศัยอยู่ในอียิปต์ ทั้งท่านและครอบครัวบิดาของท่าน โยเซฟอายุยืนได้ร้อยสิบปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 23, 'โยเซฟได้เห็นลูกหลานเหลนของเอฟราอิม บุตรของมาคีร์ผู้เป็นบุตรชายของมนัสเสห์ก็เกิดมาบนเข่าของโยเซฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 24, 'โยเซฟจึงบอกพวกพี่น้องว่า “เราจวนจะตายแล้ว และพระเจ้าจะทรงเยี่ยมเยียนพวกท่านเป็นแน่ และจะพาพวกท่านออกไปจากประเทศนี้ให้ถึงแผ่นดินที่พระองค์ทรงปฏิญาณไว้กับอับราฮัม อิสอัคและยาโคบ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 25, 'โยเซฟก็ให้ลูกหลานของอิสราเอลปฏิญาณตัวว่า “พระเจ้าจะทรงเยี่ยมเยียนพวกท่านเป็นแน่แล้วท่านทั้งหลายต้องนํากระดูกของเราไปจากที่นี่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 26, 'โยเซฟสิ้นชีพเมื่ออายุได้ร้อยสิบปี เขาก็อาบยารักษาศพไว้แล้วบรรจุไว้ในโลงที่อียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 1, 'นี่แหละเป็นชื่อบุตรของอิสราเอลที่เข้ามาในประเทศอียิปต์ ท่านเหล่านี้กับทั้งครอบครัวของตนได้มากับยาโคบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 2, 'คือ รูเบน สิเมโอน เลวี และ ยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 3, 'อิสสาคาร์ เศบูลุน และ เบนยามิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 4, 'ดาน และนัฟทาลี กาดและอาเชอร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 5, 'คนทั้งปวงที่ออกมาจากบั้นเอวของยาโคบรวมเจ็ดสิบคนด้วยกัน ส่วนโยเซฟนั้นอยู่ที่ประเทศอียิปต์แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 6, 'แล้วโยเซฟกับพี่น้องทุกคน ทั้งบรรดาคนยุคนั้น ถึงแก่ความตายเสียหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 7, 'และบุตรของอิสราเอลมีลูกหลานมากและเพิ่มจํานวนขึ้นมาก พวกเขาทวีมากขึ้น และมีกําลังมากทีเดียว และแพร่หลายไปจนเต็มแผ่นดินนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 8, 'บัดนี้มีกษัตริย์องค์ใหม่ขึ้นครองราชสมบัติในประเทศอียิปต์ ซึ่งมิได้รู้จักกับโยเซฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 9, 'และพระองค์ทรงประกาศแก่ชนชาติของพระองค์ว่า “ดูเถิด ประชาชนชนชาติอิสราเอลมีมากกว่าและมีกําลังยิ่งกว่าเราอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 10, 'มาเถิด ให้เราใช้สติปัญญาในเรื่องพวกนี้กับเขา เกรงว่าเขาจะทวีมากขึ้น แล้วต่อมาเมื่อเกิดสงครามขึ้น เขาจะสมทบกับพวกข้าศึกของเราสู้รบกับเรา แล้วจะยกออกไปจากอาณาจักร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 11, 'เหตุฉะนั้น เขาจึงตั้งนายงานให้เบียดเบียนคนอิสราเอลด้วยงานตรากตรํา และเขาทั้งหลายสร้างเมืองเก็บราชสมบัติของฟาโรห์ คือเมืองปิธม และเมืองราอัมเสส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 12, 'แต่ยิ่งเบียดเบียนชนชาติอิสราเอล ชนชาติอิสราเอลก็ยิ่งทวีมากขึ้น และยิ่งแพร่หลายออกไป ชาวอียิปต์ก็ทุกข์ใจเนื่องด้วยชนชาติอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 13, 'ชาวอียิปต์จึงบังคับชนชาติอิสราเอลให้ทํางานหนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 14, 'และทําให้ชีวิตของเขาขมขื่นเพราะงานหนักที่เขากระทํานั้น เช่นทําปูนสอ ทําอิฐและทํางานต่างๆที่ทุ่งนา เขาถูกบังคับให้ทํางานหนักทุกชนิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 15, 'และกษัตริย์อียิปต์ทรงตรัสกับนางผดุงครรภ์ชาวฮีบรู ซึ่งคนหนึ่งชื่อชิฟราห์และอีกคนหนึ่งชื่อปูอาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 16, 'และพระองค์ตรัสว่า “เมื่อเจ้าไปทําคลอดให้แก่หญิงฮีบรู และเห็นเขาอยู่บนแผ่นศิลา ถ้าเป็นเด็กชายก็ให้ฆ่าเสีย แต่ถ้าเป็นเด็กหญิงก็ให้ไว้ชีวิต”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 17, 'แต่นางผดุงครรภ์ยําเกรงพระเจ้า จึงมิได้ทําตามที่กษัตริย์อียิปต์สั่งเขานั้น แต่ปล่อยให้บุตรชายรอดชีวิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 18, 'กษัตริย์อียิปต์จึงรับสั่งให้นางผดุงครรภ์เข้าเฝ้า และตรัสแก่เขาว่า “เหตุไฉนเจ้าจึงทําอย่างนี้ คือปล่อยให้เด็กชายรอดชีวิต”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 19, 'นางผดุงครรภ์จึงกราบทูลฟาโรห์ว่า “เพราะหญิงฮีบรูไม่เหมือนหญิงอียิปต์ เพราะเขามีกําลังมากจึงคลอดบุตรโดยเร็ว และนางผดุงครรภ์มาหาเขาไม่ทัน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 20, 'เพราะฉะนั้น พระเจ้าทรงโปรดปรานนางผดุงครรภ์นั้น พลไพร่ยิ่งทวีมากขึ้น และมีกําลังเข้มแข็งมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 21, 'และต่อมา เพราะนางผดุงครรภ์นั้นยําเกรงพระเจ้า พระองค์จึงได้ทรงให้เขาทั้งสองมีครอบครัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 22, 'ฝ่ายฟาโรห์จึงรับสั่งแก่บ่าวไพร่ทั้งปวงของพระองค์ว่า “บุตรชายทุกคนที่เกิดมาให้เอาไปทิ้งเสียในแม่น้ํา แต่บุตรสาวทุกคนให้รอดชีวิตอยู่ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 1, 'ยังมีชายวงศ์วานเลวีคนหนึ่ง ได้หญิงสาวคนเลวีมาเป็นภรรยา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 2, 'หญิงนั้นตั้งครรภ์และคลอดบุตรชาย และเมื่อนางเห็นว่าทารกเป็นเด็กที่มีรูปงาม นางจึงซ่อนทารกไว้ถึงสามเดือน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 3, 'ครั้นนางจะซ่อนทารกต่อไปอีกไม่ได้แล้วก็เอาตะกร้าสานด้วยต้นกก ยาด้วยยางมะตอยและชัน เอาทารกใส่ลงในตะกร้า แล้วนางนําไปวางไว้ที่กอปรือริมแม่น้ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 4, 'ส่วนพี่สาวยืนอยู่แต่ไกล คอยดูว่าจะมีเหตุการณ์อะไรเกิดขึ้นแก่น้อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 5, 'และพระราชธิดาของฟาโรห์ลงไปสรงที่แม่น้ํา และพวกสาวใช้เดินไปตามริมฝั่งแม่น้ํานั้น และเมื่อพระนางเห็นตะกร้าอยู่ระหว่างกอปรือ จึงสั่งให้สาวใช้ไปนํามา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 6, 'และเมื่อเปิดตะกร้านั้นออกก็เห็นทารก และดูเถิด ทารกนั้นกําลังร้องไห้ พระนางจึงทรงกรุณาทารกนั้น และตรัสว่า “นี่เป็นลูกชาวฮีบรู”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 7, 'พี่สาวทารกจึงทูลถามพระราชธิดาของฟาโรห์ว่า “จะให้หม่อมฉันไปหานางนมชาวฮีบรูมาเลี้ยงทารกนี้ให้พระนางไหม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 8, 'พระราชธิดาของฟาโรห์จึงมีรับสั่งแก่เธอว่า “ไปหาเถิด” หญิงสาวนั้นจึงไปเรียกมารดาของทารกนั้นมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 9, 'ฝ่ายพระราชธิดาของฟาโรห์จึงตรัสสั่งนางว่า “รับเด็กนี้ไปเลี้ยงไว้ให้เรา แล้วเราจะให้ค่าจ้างแก่เจ้า” นางจึงรับทารกไปเลี้ยงไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 10, 'แล้วทารกนั้นก็โตขึ้น และนางก็พาเขามาถวายพระราชธิดาของฟาโรห์ และเขากลายเป็นบุตรเลี้ยงของพระนาง และพระนางประทานชื่อว่า โมเสส และตรัสว่า “เพราะเราได้ฉุดเขาขึ้นมาจากน้ํา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 11, 'และต่อมาในวันเหล่านั้น ครั้นโมเสสเติบโตขึ้นแล้ว ท่านก็ออกไปหาพวกพี่น้อง และเห็นพวกเขาต้องทํางานตรากตรํา โมเสสเห็นคนอียิปต์คนหนึ่งกําลังตีคนฮีบรู ซึ่งเป็นชนชาติเดียวกันกับตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 12, 'ท่านก็มองดูซ้ายขวาและเมื่อท่านเห็นว่าไม่มีผู้ใดอยู่ที่นั่น ท่านจึงฆ่าคนอียิปต์นั้นเสีย แล้วซ่อนศพไว้ในทราย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 13, 'และเมื่อโมเสสออกไปอีกในวันรุ่งขึ้น ดูเถิด มีชาวฮีบรูสองคนต่อสู้กันอยู่ ท่านจึงกล่าวแก่คนที่ทําผิดนั้นว่า “ท่านตีพี่น้องของท่านเองทําไม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 14, 'และเขาตอบว่า “ใครแต่งตั้งท่านให้เป็นเจ้านาย และเป็นตุลาการปกครองพวกข้าพเจ้า ท่านตั้งใจจะฆ่าข้าพเจ้าเหมือนกับที่ได้ฆ่าคนอียิปต์คนนั้นหรือ” โมเสสจึงกลัว และนึกว่า “เรื่องนั้นได้ลือกันไปทั่วแล้วเป็นแน่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 15, 'เมื่อฟาโรห์ทรงได้ยินถึงเรื่องนี้ก็หาช่องที่จะประหารชีวิตโมเสสเสีย แต่โมเสสหนีจากพระพักตร์ของฟาโรห์ไปอาศัยอยู่ในแผ่นดินมีเดียน ท่านจึงนั่งลงที่ริมบ่อน้ําแห่งหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 16, 'ฝ่ายปุโรหิตของคนมีเดียนมีบุตรสาวเจ็ดคน หญิงเหล่านั้นก็มาตักน้ําใส่รางให้ฝูงแพะแกะของบิดากิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 17, 'และพวกเลี้ยงแกะมาไล่หญิงเหล่านั้น แต่โมเสสลุกขึ้นช่วยหญิงเหล่านั้น และให้ฝูงแพะแกะของเธอกินน้ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 18, 'และเมื่อหญิงเหล่านั้นกลับไปหาเรอูเอลบิดาของเธอ บิดาถามว่า “วันนี้ทําไมพวกเจ้าจึงกลับมาเร็ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 19, 'และเธอตอบว่า “มีคนอียิปต์คนหนึ่งช่วยพวกข้าพเจ้าให้พ้นจากมือของพวกเลี้ยงแกะ ทั้งยังตักน้ําให้พวกข้าพเจ้าและให้ฝูงแพะแกะกินด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 20, 'บิดาจึงถามบุตรสาวของท่านว่า “แล้วชายผู้นั้นอยู่ที่ไหน ทําไมจึงทิ้งเขาไว้ล่ะ ไปเชิญเขามาเพื่อจะรับประทานอาหารซิ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 21, 'โมเสสก็เต็มใจอาศัยอยู่กับเรอูเอล แล้วเรอูเอลก็ยกศิปโปราห์บุตรสาวให้แก่โมเสส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 22, 'นางก็คลอดบุตรชายคนหนึ่ง โมเสสจึงตั้งชื่อว่า เกอร์โชม เพราะท่านกล่าวว่า “ข้าพเจ้าเป็นคนต่างด้าวอาศัยอยู่ต่างประเทศ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 23, 'และต่อมา ครั้นเวลาล่วงมาช้านาน กษัตริย์อียิปต์ก็สิ้นพระชนม์ ชนชาติอิสราเอลก็เศร้าใจมากเพราะเหตุที่เขาเป็นทาส เขาจึงร้องคร่ําครวญ และเสียงร่ําร้องของเขาดังขึ้นไปถึงพระเจ้า ด้วยเหตุที่เป็นทาสนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 24, 'และพระเจ้าทรงสดับฟังเสียงคร่ําครวญของเขา พระเจ้าจึงทรงระลึกถึงพันธสัญญาของพระองค์กับอับราฮัม อิสอัค และยาโคบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 25, 'พระเจ้าจึงทอดพระเนตรชนชาติอิสราเอล แล้วพระเจ้าทรงเอาใจใส่พวกเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 1, 'ฝ่ายโมเสสเลี้ยงฝูงแพะแกะของเยโธรพ่อตาของเขา ผู้เป็นปุโรหิตของคนมีเดียน และท่านได้พาฝูงแพะแกะไปด้านหลังของถิ่นทุรกันดาร และมาถึงภูเขาของพระเจ้า คือโฮเรบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 2, 'ทูตสวรรค์ของพระเยโฮวาห์ก็ปรากฏแก่โมเสสในเปลวไฟซึ่งอยู่ท่ามกลางพุ่มไม้ โมเสสจึงมองดูและดูเถิด พุ่มไม้นั้นมีไฟลุกโชนอยู่ แต่พุ่มไม้นั้นมิได้ไหม้โทรมไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 3, 'โมเสสจึงกล่าวว่า “ข้าจะแวะเข้าไปดูสิ่งแปลกประหลาดนี้ ว่าเหตุไฉนพุ่มไม้จึงไม่ไหม้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 4, 'และเมื่อพระเยโฮวาห์ทอดพระเนตรเห็นเขาเดินเข้ามาดู พระเจ้าจึงตรัสแก่เขาออกมาจากท่ามกลางพุ่มไม้นั้นว่า “โมเสส โมเสส” และโมเสสทูลตอบว่า “ข้าพระองค์อยู่ที่นี่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 5, 'พระองค์จึงตรัสว่า “อย่าเข้ามาใกล้ที่นี่ จงถอดรองเท้าของเจ้าออกเสีย เพราะว่าที่ซึ่งเจ้ายืนอยู่นี้เป็นที่บริสุทธิ์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 6, 'แล้วพระองค์ตรัสอีกว่า “เราเป็นพระเจ้าของบิดาเจ้า เป็นพระเจ้าของอับราฮัม เป็นพระเจ้าของอิสอัค และเป็นพระเจ้าของยาโคบ” และโมเสสปิดหน้าเสีย เพราะกลัวไม่กล้ามองดูพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 7, 'และพระเยโฮวาห์ตรัสว่า “เราเห็นความทุกข์ของพลไพร่ของเราที่อยู่ในประเทศอียิปต์แล้ว และได้ยินเสียงร้องของเขา เพราะเหตุพวกนายงานของเขา ด้วยเรารู้ถึงความทุกข์ร้อนต่างๆของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 8, 'และเราลงมาเพื่อจะช่วยเขาให้รอดพ้นจากมือของชาวอียิปต์ และนําเขาออกจากประเทศนั้น ไปยังแผ่นดินที่อุดมกว้างขวาง เป็นแผ่นดินที่มีน้ํานมและน้ําผึ้งไหลบริบูรณ์ คือไปยังที่อยู่ของชาวคานาอัน คนฮิตไทต์ คนอาโมไรต์ คนเปริสซี คนฮีไวต์ และคนเยบุส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 9, 'เพราะฉะนั้น ดูเถิด บัดนี้คําร่ําร้องของชนชาติอิสราเอลมาถึงเราแล้ว ทั้งเราได้เห็นการข่มเหงซึ่งชาวอียิปต์กระทําต่อเขาแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 10, 'เพราะฉะนั้น จงมาเถิด บัดนี้เราจะใช้เจ้าไปเฝ้าฟาโรห์ เพื่อเจ้าจะได้พาพลไพร่ของเรา คือชนชาติอิสราเอล ออกจากอียิปต์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 11, 'ฝ่ายโมเสสจึงทูลพระเจ้าว่า “ข้าพระองค์เป็นผู้ใดเล่า ซึ่งข้าพระองค์จะไปเฝ้าฟาโรห์และจะนําชนชาติอิสราเอลออกจากอียิปต์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 12, 'พระองค์จึงตรัสว่า “เราจะอยู่กับเจ้าแน่ และนี่จะเป็นหมายสําคัญให้เจ้ารู้ว่าเราใช้ให้เจ้าไป คือเมื่อเจ้านําพลไพร่ออกจากอียิปต์แล้ว เจ้าทั้งหลายจะมาปรนนิบัติพระเจ้าบนภูเขานี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 13, 'และโมเสสทูลพระเจ้าว่า “ดูเถิด เมื่อข้าพระองค์ไปหาชนชาติอิสราเอล และบอกพวกเขาว่า ‘พระเจ้าแห่งบรรพบุรุษของท่านทั้งหลายทรงใช้ข้าพเจ้ามาหาท่าน’ และเขาจะพูดกับข้าพเจ้าว่า ‘พระองค์ทรงพระนามว่ากระไร’ ข้าพระองค์จะกล่าวแก่เขาอย่างไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 14, 'พระเจ้าจึงตรัสกับโมเสสว่า “เราเป็นผู้ซึ่งเราเป็น” แล้วพระองค์ตรัสว่า “เจ้าจงไปบอกชนชาติอิสราเอลว่า ‘เราเป็น ได้ทรงใช้ข้าพเจ้ามาหาท่านทั้งหลาย’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 15, 'พระเจ้าจึงตรัสกับโมเสสอีกว่า “เจ้าจงกล่าวแก่ชนชาติอิสราเอลว่าดังนี้ ‘พระเยโฮวาห์พระเจ้าแห่งบรรพบุรุษของท่าน คือพระเจ้าของอับราฮัม พระเจ้าของอิสอัคและพระเจ้าของยาโคบ ทรงใช้ให้ข้าพเจ้ามาหาท่าน’ นี่เป็นนามของเราตลอดไปเป็นนิตย์ และนี่เป็นที่ระลึกของเราตลอดทุกชั่วอายุ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 16, 'จงไปรวบรวมพวกผู้ใหญ่ของอิสราเอลให้มาประชุมพร้อมกัน แล้วกล่าวแก่เขาว่า ‘พระเยโฮวาห์พระเจ้าแห่งบรรพบุรุษของท่าน คือพระเจ้าของอับราฮัม ของอิสอัค และของยาโคบ ปรากฏแก่ข้าพเจ้า ตรัสว่า “แท้จริงเราลงมาเยี่ยมเจ้าทั้งหลายแล้ว และได้เห็นสิ่งซึ่งเขาได้กระทําแก่เจ้าในอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 17, 'และเราได้กล่าวไว้แล้วว่า เราจะพาเจ้าทั้งหลายไปให้พ้นจากความทุกข์ในประเทศอียิปต์ ไปยังแผ่นดินของชาวคานาอัน คนฮิตไทต์ คนอาโมไรต์ คนเปริสซี คนฮีไวต์และคนเยบุส ไปยังแผ่นดินซึ่งมีน้ํานมและน้ําผึ้งไหลบริบูรณ์”’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 18, 'และเขาก็จะเชื่อฟังคําของเจ้า แล้วพวกเจ้า ทั้งเจ้ากับพวกผู้ใหญ่ของคนอิสราเอล จงพากันไปเฝ้ากษัตริย์ของอียิปต์ และเจ้าจงทูลพระองค์ว่า ‘พระเยโฮวาห์พระเจ้าของคนฮีบรู ทรงปรากฏแก่ข้าพระองค์ทั้งหลาย บัดนี้ ขอได้โปรดให้ข้าพระองค์เดินทางไปในถิ่นทุรกันดารสักสามวันเพื่อจะถวายเครื่องบูชาแด่พระเยโฮวาห์พระเจ้าของเรา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 19, 'เรารู้แน่แล้วว่า กษัตริย์แห่งอียิปต์จะไม่ยอมให้พวกเจ้าไป แม้กระทั่งโดยหัตถ์อันทรงฤทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 20, 'และเราจะเหยียดมือของเราออกประหารอียิปต์ด้วยมหัศจรรย์ต่างๆของเราที่เราจะกระทําในท่ามกลางประเทศนั้น แล้วหลังจากนั้น กษัตริย์ก็จะยอมปล่อยพวกเจ้าไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 21, 'และเราจะให้พลไพร่นี้เป็นที่โปรดปรานในสายตาของชาวอียิปต์ และต่อมา เมื่อเจ้าทั้งหลายออกไปก็จะไม่ต้องไปมือเปล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 22, 'แต่ผู้หญิงทุกคนจะขอเครื่องเงินเครื่องทองและเสื้อผ้าจากเพื่อนบ้านของเขา และจากหญิงที่อาศัยอยู่ในเรือนของเขา และเจ้าจงเอาของเหล่านั้นไปแต่งให้บุตรชายหญิงของเจ้า และเจ้าจะได้ริบเอาสิ่งของของชาวอียิปต์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 1, 'โมเสสจึงทูลตอบว่า “แต่ ดูเถิด เขาจะไม่เชื่อข้าพระองค์ หรือฟังเสียงของข้าพระองค์เพราะเขาจะว่า ‘พระเยโฮวาห์มิได้ทรงปรากฏแก่ท่านเลย’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 2, 'พระเยโฮวาห์จึงตรัสกับโมเสสว่า “อะไรอยู่ในมือของเจ้า” และท่านทูลว่า “ไม้เท้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 3, 'และพระองค์ตรัสว่า “โยนลงที่พื้นดินเถิด” ท่านจึงโยนไม้เท้าลงบนพื้นดิน ไม้เท้านั้นก็กลายเป็นงู โมเสสก็หลบหนีจากงูไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 4, 'และพระเยโฮวาห์ตรัสกับโมเสสว่า “เอื้อมมือของเจ้าและจับหางงูไว้” ท่านก็เอื้อมมือของท่านและจับหางงู มันก็กลายเป็นไม้เท้าอยู่ในมือของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 5, '“เพื่อเขาทั้งหลายจะได้เชื่อว่า พระเยโฮวาห์พระเจ้าของบรรพบุรุษของเขา พระเจ้าของอับราฮัม พระเจ้าของอิสอัค และพระเจ้าของยาโคบ ได้ทรงปรากฏแก่เจ้าแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 6, 'และพระเยโฮวาห์ตรัสกับโมเสสอีกว่า “เอามือของเจ้าสอดไว้ที่อกของเจ้า” ท่านก็สอดมือของท่านไว้ที่อกของท่าน และเมื่อชักมือออก ดูเถิด มือของท่านก็เป็นโรคเรื้อน ขาวเหมือนหิมะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 7, 'พระองค์จึงตรัสว่า “เอามือของเจ้าสอดไว้ที่อกของเจ้าอีกครั้งหนึ่ง” โมเสสก็สอดมือของท่านเข้าอกของท่านอีก แล้วท่านชักมือออกมาจากอก และดูเถิด มือนั้นกลับกลายเป็นเหมือนเนื้อหนังส่วนอื่นของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 8, '“และต่อมา ถ้าเขาจะไม่เชื่อเจ้า และไม่ฟังเสียงแห่งหมายสําคัญแรก เขาก็จะเชื่อเสียงแห่งหมายสําคัญที่สอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 9, 'และต่อมา ถ้าเขาไม่เชื่อหมายสําคัญทั้งสองครั้งนี้ ทั้งไม่ฟังเสียงของเจ้า เจ้าจงตักน้ําในแม่น้ําและเทลงที่ดินแห้ง แล้วน้ําที่เจ้าตักมาจากแม่น้ํานั้นจะกลายเป็นเลือดบนดินแห้งนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 10, 'แต่โมเสสทูลพระเยโฮวาห์ว่า “โอ ข้าแต่องค์พระผู้เป็นเจ้าของข้าพระองค์ ข้าพระองค์มิใช่คนพูดคล่อง ทั้งในกาลก่อน และตั้งแต่เวลาที่พระองค์ตรัสกับผู้รับใช้ของพระองค์ แต่ข้าพระองค์เป็นคนพูดไม่คล่อง และพูดช้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 11, 'พระเยโฮวาห์จึงตรัสกับท่านว่า “ผู้ใดเล่าที่สร้างปากมนุษย์ หรือทําให้เป็นใบ้ หูหนวก ตาดี หรือตาบอด เราพระเยโฮวาห์เป็นผู้ทําไม่ใช่หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 12, 'เพราะฉะนั้น จงไปเถิด บัดนี้เราจะอยู่ที่ปากของเจ้า และจะสอนคําซึ่งเจ้าควรจะพูด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 13, 'แต่ท่านทูลว่า “โอ ข้าแต่องค์พระผู้เป็นเจ้าของข้าพระองค์ ขอทรงโปรดใช้ผู้อื่นไปเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 14, 'ฝ่ายพระเยโฮวาห์ทรงกริ้วต่อโมเสส พระองค์จึงตรัสว่า “เจ้ามีพี่ชายคืออาโรนคนเลวีไม่ใช่หรือ เรารู้แล้วว่าเขาเป็นคนพูดเก่ง และดูเถิด เขากําลังเดินทางมาพบเจ้าด้วย เมื่อเขาเห็นเจ้าเขาก็จะดีใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 15, 'เจ้าจะพูดกับเขา และบอกสิ่งซึ่งเขาควรจะพูด แล้วเราจะอยู่ที่ปากของเจ้า และปากของเขา และเราจะสอนเจ้าว่าควรจะทําประการใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 16, 'และเขาจะเป็นผู้พูดแก่พลไพร่แทนเจ้า และเขา คือเขาเองจะเป็นปากแทนเจ้า และเจ้าจะเป็นผู้แทนพระเจ้าแก่เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 17, 'เจ้าจงถือไม้เท้านี้ไว้ในมือของเจ้า สําหรับทําหมายสําคัญ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 18, 'โมเสสจึงกลับไปหาเยโธร พ่อตาของตน และบอกกับเขาว่า “ข้าพเจ้าขอลากลับไปหาพี่น้องของข้าพเจ้าซึ่งอยู่ในอียิปต์ เพื่อจะได้ดูว่าเขายังมีชีวิตอยู่หรือไม่” ฝ่ายเยโธรตอบโมเสสว่า “ไปโดยสันติภาพเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 19, 'พระเยโฮวาห์จึงตรัสกับโมเสสในแผ่นดินมีเดียนว่า “กลับไปอียิปต์ เพราะคนทั้งหมดที่หาช่องประหารชีวิตเจ้านั้นตายแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 20, 'โมเสสจึงให้ภรรยาและบุตรชายของตนขี่ลากลับไปยังแผ่นดินอียิปต์ ส่วนโมเสสก็ถือไม้เท้าของพระเจ้าในมือของท่านไปด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 21, 'พระเยโฮวาห์ตรัสกับโมเสสว่า “เมื่อเจ้ากลับไปถึงอียิปต์ จงกระทํามหัศจรรย์ต่างๆซึ่งเรามอบไว้ในมือของเจ้าแล้วนั้นต่อหน้าฟาโรห์ แต่เราจะทําให้ใจของฟาโรห์แข็งกระด้าง เพื่อเขาจะไม่ยอมให้พลไพร่ไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 22, 'และเจ้าจะทูลฟาโรห์ว่า ‘พระเยโฮวาห์ตรัสดังนี้ว่า คนอิสราเอลเป็นบุตรชายของเรา คือเป็นบุตรหัวปีของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 23, 'เราจึงบอกแก่เจ้าว่า “จงปล่อยบุตรของเราไป เพื่อเขาจะได้ปรนนิบัติเรา” และถ้าเจ้าไม่ยอมให้เขาไป ดูเถิด เราจะประหารชีวิตบุตรชายของเจ้า คือบุตรหัวปีของเจ้าเสีย’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 24, 'และต่อมา ณ ที่พักระหว่างทาง พระเยโฮวาห์เสด็จมาพบโมเสส และจะประหารชีวิตของท่านเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 25, 'ครั้งนั้นนางศิปโปราห์จึงเอาหินคมตัดหนังที่ปลายองคชาตบุตรชายของตนออกแล้วทิ้งไว้ที่เท้าของโมเสสกล่าวว่า “จริงนะ ท่านเป็นสามีผู้ทําให้โลหิตตก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 26, 'พระองค์จึงทรงละท่านไว้ นางจึงกล่าวว่า “ท่านเป็นสามีผู้ทําให้โลหิตตก” เนื่องจากการเข้าสุหนัต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 27, 'และพระเยโฮวาห์ตรัสกับอาโรนว่า “จงไปพบกับโมเสสในถิ่นทุรกันดาร” เขาก็ไปพบกับท่านที่ภูเขาของพระเจ้าและจุบท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 28, 'โมเสสจึงเล่าให้อาโรนฟังถึงพระดํารัสของพระเยโฮวาห์ทั้งหมด ผู้ซึ่งทรงใช้ตน และถึงหมายสําคัญทั้งปวงซึ่งพระองค์ได้ทรงบัญชาแก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 29, 'โมเสสกับอาโรนไปเรียกประชุมบรรดาผู้ใหญ่ของชนชาติอิสราเอลพร้อมกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 30, 'แล้วอาโรนจึงกล่าวถึงพระดํารัสทั้งหมดซึ่งพระเยโฮวาห์ตรัสแก่โมเสส และทําหมายสําคัญต่างๆนั้นท่ามกลางสายตาของพลไพร่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 31, 'ฝ่ายพลไพร่ก็เชื่อ และเมื่อเขาได้ยินว่าพระเยโฮวาห์เสด็จมาเยี่ยมเยียนชนชาติอิสราเอล และทอดพระเนตรเห็นความทุกข์ยากของเขาแล้ว เขาก็ก้มศีรษะลงและนมัสการ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 1, 'ต่อมาภายหลังโมเสสกับอาโรนเข้าเฝ้า และทูลฟาโรห์ว่า “พระเยโฮวาห์พระเจ้าของอิสราเอลตรัสดังนี้ว่า ‘จงปล่อยพลไพร่ของเราไป เพื่อเขาจะได้ทําการเลี้ยงนมัสการเราในถิ่นทุรกันดาร’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 2, 'ฟาโรห์จึงตรัสว่า “พระเยโฮวาห์นั้นเป็นผู้ใดเล่าเราจึงจะต้องเชื่อฟังเสียงของพระองค์และปล่อยคนอิสราเอลไป เราไม่รู้จักพระเยโฮวาห์ ทั้งเราจะไม่ยอมปล่อยคนอิสราเอลไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 3, 'เขาทั้งสองจึงทูลว่า “พระเจ้าของคนฮีบรูได้ทรงปรากฏกับข้าพระองค์ ขอโปรดให้ข้าพระองค์ทั้งหลายเดินทางไปในถิ่นทุรกันดารสามวัน และถวายเครื่องบูชาแด่พระเยโฮวาห์พระเจ้าของข้าพระองค์ เกรงว่าพระองค์จะทรงลงโทษพวกข้าพระองค์ด้วยโรคภัยหรือด้วยดาบ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 4, 'แล้วกษัตริย์แห่งอียิปต์ตรัสกับเขาว่า “เจ้าโมเสสกับอาโรน เจ้าจะให้พลไพร่ละทิ้งการงานของเขาเสียทําไม เจ้าจงกลับไปรับภาระงานของเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 5, 'และฟาโรห์ตรัสว่า “ดูเถิด พวกไพร่ในประเทศนี้มีมาก และเจ้าทั้งสองทําให้เขาหยุดภาระงานของเขาเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 6, 'ในวันนั้นเองฟาโรห์มีพระบัญชาสั่งนายงานและนายกองของพลไพร่ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 7, '“ตั้งแต่นี้ไป เจ้าอย่าให้ฟางแก่พวกไพร่สําหรับใช้ทําอิฐเหมือนแต่ก่อน แต่ให้เขาไปเที่ยวหาฟางเอาเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 8, 'ส่วนจํานวนอิฐซึ่งแต่ก่อนเกณฑ์ให้เขาทําเท่าไร เจ้าก็จงเกณฑ์ให้เขาทําเท่านั้น เจ้าอย่าได้หย่อนลง เพราะว่าเขาเกียจคร้าน เหตุฉะนั้นเขาจึงร้องว่า ‘ขอให้พวกข้าพระองค์ไปถวายเครื่องบูชาแด่พระเจ้าของพวกข้าพระองค์’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 9, 'จงจัดหางานให้เขาทําหนักกว่าแต่ก่อน เพื่อเขาจะทํางาน และไม่ฟังคําพูดเหลวไหล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 10, 'ฝ่ายนายงานและนายกองของพลไพร่ก็ออกไปและกล่าวแก่พลไพร่ว่า “ฟาโรห์รับสั่งดังนี้ว่า ‘เราจะไม่ยอมให้ฟางแก่พวกเจ้าเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 11, 'เจ้าจงไปหาฟางมาเอง ตามแต่จะหามาได้เถิด แต่งานของเจ้าที่เกณฑ์นั้นก็ไม่ลดหย่อนให้เลย’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 12, 'พลไพร่เหล่านั้นจึงแยกย้ายกันไปทั่วแผ่นดินอียิปต์เพื่อเก็บตอฟางมาแทนฟาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 13, 'นายงานก็เร่งรัดว่า “จงทํางาน คืองานประจําวันของเจ้า ให้เสร็จครบเหมือนเมื่อยังมีฟางอยู่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 14, 'นายกองของชนชาติอิสราเอล ซึ่งนายงานของฟาโรห์ตั้งให้เป็นผู้บังคับเขานั้น ก็ถูกโบยตีและถูกถามว่า “ทําไมหมู่นี้จึงไม่ได้อิฐที่เกณฑ์ไว้เต็มจํานวน ทั้งวานนี้และวันนี้ เหมือนแต่ก่อน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 15, 'นายกองของชนชาติอิสราเอลจึงมาร้องทูลต่อฟาโรห์ว่า “เหตุไฉนพระองค์จึงทรงกระทําดังนี้แก่พวกทาสของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 16, 'พวกเขากล่าวกับพวกเราว่า ‘ทําอิฐซิ’ แต่มิได้ให้ฟางแก่พวกทาสของพระองค์เลย และดูเถิด พวกทาสของพระองค์ถูกโบยตี แต่ข้าราชการของพระองค์เองเป็นฝ่ายผิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 17, 'แต่ฟาโรห์ตรัสว่า “พวกเจ้าเกียจคร้าน พวกเจ้าเกียจคร้าน พวกเจ้าจึงมาร้องว่า ‘ขอให้ข้าพระองค์ไปถวายเครื่องบูชาแด่พระเยโฮวาห์’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 18, 'เหตุฉะนั้นเจ้าจงไปทํางานเดี๋ยวนี้ ฟางนั้นจะไม่ให้พวกเจ้าเลย แต่จํานวนอิฐที่เกณฑ์ไว้นั้น พวกเจ้าจะต้องทํามาให้ครบจํานวน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 19, 'นายกองชนชาติอิสราเอลก็เห็นว่าตนมีปัญหาแล้ว หลังจากถูกสั่งว่า “ไม่ให้ลดหย่อนจํานวนอิฐที่ถูกเกณฑ์ให้ทําทุกๆวันลง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 20, 'ครั้นออกมาจากเฝ้าฟาโรห์ เขาพบโมเสสกับอาโรนยืนอยู่กลางทาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 21, 'เขาจึงกล่าวแก่เขาทั้งสองว่า “ขอพระเยโฮวาห์ทรงมองดูพวกท่านและพิพากษาเถิด เพราะท่านกระทําให้ชื่อของพวกข้าพเจ้าเป็นที่เกลียดชังในสายพระเนตรของฟาโรห์ และในสายตาของข้าราชการของพระองค์ เหมือนหนึ่งเอาดาบใส่มือเขาให้สังหารพวกข้าพเจ้าเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 22, 'โมเสสจึงกลับไปทูลพระเยโฮวาห์ว่า “ข้าแต่องค์พระผู้เป็นเจ้า เหตุไฉนพระองค์ทรงทําการร้ายแก่ชนชาตินี้ เหตุไฉนพระองค์จึงทรงใช้ข้าพระองค์มา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 23, 'เพราะว่าตั้งแต่ข้าพระองค์ไปเฝ้าฟาโรห์เพื่อทูลในพระนามของพระองค์แล้ว ฟาโรห์ก็ทําทารุณแก่ชนชาตินี้ ส่วนพระองค์ก็มิได้ทรงช่วยพลไพร่ของพระองค์ให้พ้นเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 1, 'พระเยโฮวาห์จึงตรัสกับโมเสสว่า “บัดนี้เจ้าจะได้เห็นเหตุการณ์ซึ่งเราจะกระทําแก่ฟาโรห์ คือด้วยมืออันทรงฤทธิ์ เขาจะปล่อยพลไพร่ไป และด้วยมืออันเข้มแข็ง เขาจะไล่พลไพร่ออกจากแผ่นดินของเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 2, 'พระเจ้าตรัสกับโมเสสว่า “เราคือพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 3, 'เราปรากฏแก่อับราฮัม แก่อิสอัค และแก่ยาโคบด้วยนามว่า พระเจ้าผู้ทรงมหิทธิฤทธิ์ แต่เรามิได้สําแดงให้เขารู้จักเราในนามพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 4, 'และเราได้ตั้งพันธสัญญาของเราไว้กับเขาทั้งหลายด้วยว่า จะยกแผ่นดินคานาอันให้แก่เขา เป็นแผ่นดินที่เขาเคยอาศัยอยู่ในฐานะคนต่างด้าว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 5, 'และเราได้ยินเสียงคร่ําครวญของชนชาติอิสราเอลด้วย ซึ่งชาวอียิปต์กักไว้ให้เป็นทาส และเราได้ระลึกถึงพันธสัญญาของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 6, 'เหตุฉะนี้จงกล่าวแก่ชนชาติอิสราเอลว่า ‘เราคือพระเยโฮวาห์ เราจะนําพวกเจ้าไปให้พ้นจากงานตรากตรําที่ชาวอียิปต์เกณฑ์ให้ทํา และจะให้พ้นจากการเป็นทาสเขา เราจะช่วยเจ้าให้พ้นด้วยแขนที่เหยียดออก และด้วยการพิพากษาอันใหญ่หลวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 7, 'เราจะรับพวกเจ้าเป็นพลไพร่ของเรา และเราจะเป็นพระเจ้าของพวกเจ้า พวกเจ้าจะรู้ว่า เราคือพระเยโฮวาห์พระเจ้าของเจ้า ผู้นําเจ้าไปให้พ้นจากงานตรากตรําที่ชาวอียิปต์เกณฑ์ให้ทํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 8, 'เราจะนําพวกเจ้าเข้าไปในแผ่นดิน ซึ่งเราได้ปฏิญาณไว้ว่าจะให้แก่อับราฮัม แก่อิสอัคและแก่ยาโคบ เราจะยกแผ่นดินนั้นให้แก่เจ้าเป็นมรดก เราคือพระเยโฮวาห์’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 9, 'โมเสสจึงนําความนั้นไปเล่าให้ชนชาติอิสราเอลฟัง แต่เขามิได้เชื่อฟังโมเสสเพราะระอาใจ และถูกเกณฑ์ให้ทําการหนักอย่างสาหัส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 10, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 11, '“จงเข้าไปเฝ้าฟาโรห์กษัตริย์แห่งอียิปต์ บอกให้ปล่อยชนชาติอิสราเอลไปจากแผ่นดินของเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 12, 'และโมเสสกราบทูลต่อพระพักตร์พระเยโฮวาห์ว่า “ดูเถิด แม้แต่ชนชาติอิสราเอลก็มิได้เชื่อฟังข้าพระองค์ ฟาโรห์จะฟังข้าพระองค์อย่างไร ข้าพระองค์เป็นคนมีริมฝีปากที่มิได้เข้าสุหนัต”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 13, 'พระเยโฮวาห์จึงตรัสแก่โมเสสและอาโรน ให้แจ้งแก่ชนชาติอิสราเอลและฟาโรห์กษัตริย์อียิปต์ว่า ให้พาชนชาติอิสราเอลออกจากแผ่นดินอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 14, 'คนเหล่านี้เป็นหัวหน้าในวงศ์วานบรรพบุรุษของเขา บุตรชายของรูเบนผู้เป็นบุตรหัวปีของอิสราเอล ชื่อฮาโนค ปัลลู เฮสโรน และคารมี คนเหล่านี้เป็นครอบครัวต่างๆของรูเบน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 15, 'บุตรชายของสิเมโอนชื่อเยมูเอล ยามีน โอหาด ยาคีน โศหาร์ และชาอูลผู้เป็นบุตรชายของหญิงชาวคานาอัน คนเหล่านี้เป็นครอบครัวต่างๆของสิเมโอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 16, 'และคนเหล่านี้เป็นชื่อบุตรชายของเลวีตามพงศ์พันธุ์ของเขาคือ เกอร์โชน โคฮาทและเมรารี เลวีนั้นมีอายุได้ร้อยสามสิบเจ็ดปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 17, 'บุตรชายของเกอร์โชนชื่อ ลิบนี และซิมอี ตามครอบครัวของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 18, 'บุตรชายของโคฮาทชื่อ อัมราม อิสฮาร์ เฮโบรน และอุสซีเอล โคฮาทมีอายุได้ร้อยสามสิบสามปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 19, 'บุตรชายของเมรารีชื่อ มาฮาลี และมูชี คนเหล่านี้เป็นครอบครัวต่างๆของเลวีตามพงศ์พันธุ์ของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 20, 'ฝ่ายอัมรามได้นางโยเคเบดน้องสาวบิดาของตนเป็นภรรยา แล้วนางให้กําเนิดบุตรแก่เขาชื่ออาโรนและโมเสส อัมรามมีอายุได้ร้อยสามสิบเจ็ดปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 21, 'บุตรชายของอิสฮาร์ชื่อ โคราห์ เนเฟก และศิครี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 22, 'บุตรชายของอุสซีเอลชื่อ มิชาเอล เอลซาฟาน และสิธรี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 23, 'ฝ่ายอาโรนได้นางเอลีเชบาบุตรสาวของอัมมีนาดับ น้องสาวของนาโชนเป็นภรรยา นางคลอดบุตรให้เขาชื่อ นาดับ อาบีฮู เอเลอาซาร์และอิธามาร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 24, 'บุตรชายของโคราห์ชื่อ อัสสีร์ เอลคานาห์ และอาบียาสาฟ คนเหล่านี้เป็นครอบครัวต่างๆของคนโคราห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 25, 'ฝ่ายเอเลอาซาร์บุตรชายอาโรน ได้รับบุตรสาวคนหนึ่งของปูทิเอลเป็นภรรยา นางคลอดบุตรให้เขาชื่อ ฟีเนหัส คนเหล่านี้เป็นหัวหน้าบรรพบุรุษของคนเลวีตามครอบครัวของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 26, 'อาโรนและโมเสสสองคนนี้แหละ คือผู้ที่พระเยโฮวาห์ได้ตรัสว่า “จงพาชนชาติอิสราเอลออกจากแผ่นดินอียิปต์ตามหมู่ตามกองของเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 27, 'สองคนนี้แหละเป็นผู้ที่กราบทูลฟาโรห์กษัตริย์ของอียิปต์เพื่อพาชนชาติอิสราเอลออกจากอียิปต์ คือโมเสสและอาโรนนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 28, 'และต่อมาในวันที่พระเยโฮวาห์ตรัสกับโมเสสในแผ่นดินอียิปต์นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 29, 'พระเยโฮวาห์ตรัสกับโมเสสว่า “เราคือพระเยโฮวาห์ เจ้าจงบอกฟาโรห์กษัตริย์ของอียิปต์ตามข้อความทั้งสิ้นซึ่งเราได้บอกแก่เจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 30, 'ฝ่ายโมเสสกราบทูลต่อพระพักตร์พระเยโฮวาห์ว่า “ดูเถิด ข้าพระองค์เป็นคนมีริมฝีปากที่มิได้เข้าสุหนัต ที่ไหนฟาโรห์จะเชื่อฟังข้าพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 1, 'พระเยโฮวาห์จึงตรัสกับโมเสสว่า “ดูซี เราได้ตั้งเจ้าไว้เป็นดังพระเจ้าต่อฟาโรห์ และอาโรนพี่ชายของเจ้าจะเป็นผู้พยากรณ์แทนเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 2, 'เจ้าจงบอกข้อความทั้งหมดที่เราสั่งเจ้า แล้วอาโรนพี่ชายของเจ้าจะบอกแก่ฟาโรห์ให้ปล่อยชนชาติอิสราเอลออกไปจากแผ่นดินของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 3, 'เราจะทําให้ใจของฟาโรห์แข็งกระด้างไป และเราจะกระทําหมายสําคัญและมหัศจรรย์ของเราให้ทวีมากขึ้นในประเทศอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 4, 'แต่ฟาโรห์จะไม่เชื่อฟังเจ้า เพื่อเราจะยกมือของเราขึ้นเหนือประเทศอียิปต์ และจะพาพลโยธาของเรา และชนชาติอิสราเอลพลไพร่ของเราให้พ้นจากแผ่นดินอียิปต์ด้วยการพิพากษาอันใหญ่หลวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 5, 'และชาวอียิปต์จะรู้ว่าเราคือพระเยโฮวาห์ เมื่อเราได้ยกมือขึ้นเหนืออียิปต์ และพาชนชาติอิสราเอลออกจากพวกเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 6, 'โมเสสและอาโรนก็กระทําตามนั้น คือกระทําตามที่พระเยโฮวาห์ทรงบัญชาเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 7, 'เมื่อเขาทั้งสองไปทูลฟาโรห์นั้น โมเสสมีอายุแปดสิบปี และอาโรนมีอายุแปดสิบสามปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 8, 'พระเยโฮวาห์ตรัสกับโมเสสและอาโรนว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 9, '“เมื่อฟาโรห์สั่งเจ้าว่า ‘จงแสดงอัศจรรย์พิสูจน์งานของเจ้า’ เจ้าจงพูดกับอาโรนว่า ‘เอาไม้เท้าของท่านโยนลงต่อหน้าฟาโรห์’ และไม้เท้านั้นจะกลายเป็นงู”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 10, 'โมเสสกับอาโรนจึงเข้าไปเฝ้าฟาโรห์ เขากระทําตามที่พระเยโฮวาห์ทรงบัญชา อาโรนโยนไม้เท้าของท่านลงต่อหน้าฟาโรห์และต่อหน้าข้าราชการทั้งปวง ไม้เท้านั้นก็กลายเป็นงู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 11, 'ฝ่ายฟาโรห์ก็เรียกพวกนักปราชญ์ และพวกนักวิทยากลมาด้วย พวกนักแสดงกลแห่งอียิปต์จึงทําได้เหมือนกันด้วยเล่ห์กลของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 12, 'ด้วยว่าเขาต่างคนต่างโยนไม้เท้าลง ไม้เท้าเหล่านั้นก็กลายเป็นงู แต่ไม้เท้าของอาโรนกลืนไม้เท้าของพวกเขาเสียทั้งหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 13, 'และพระองค์ทรงทําให้พระทัยของฟาโรห์แข็งกระด้างเพื่อฟาโรห์หายอมเชื่อฟังเขาทั้งสองไม่ เหมือนที่พระเยโฮวาห์ได้ตรัสไว้แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 14, 'พระเยโฮวาห์ตรัสกับโมเสสว่า “ใจของฟาโรห์แข็งกระด้าง ไม่ยอมปล่อยให้พลไพร่ไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 15, 'เจ้าจงถือไม้เท้าที่กลายเป็นงูไปเฝ้าฟาโรห์ในเวลาเช้า ดูเถิด เขาไปที่แม่น้ํา เจ้าจงยืนคอยเขาอยู่ที่ริมฝั่งแม่น้ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 16, 'และเจ้าจงกล่าวแก่เขาว่า ‘พระเยโฮวาห์พระเจ้าของชาวฮีบรูตรัสสั่งให้ข้าพระองค์มาเฝ้าโดยมีพระดํารัสว่า “จงปล่อยพลไพร่ของเราเพื่อเขาจะไปปรนนิบัติเราในถิ่นทุรกันดาร ดูเถิด จนบัดนี้เจ้าก็ยังหาได้เชื่อฟังไม่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 17, 'พระเยโฮวาห์ตรัสดังนี้ว่า “เจ้าจะทราบว่า เราคือพระเยโฮวาห์ด้วยอาศัยการกระทําดังนี้ ดูเถิด เราจะเอาไม้เท้าที่ถือไว้นั้นฟาดน้ําในแม่น้ํา น้ํานั้นจะกลายเป็นเลือด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 18, 'ปลาซึ่งอยู่ในแม่น้ําจะตาย และแม่น้ําจะเหม็น ชาวอียิปต์จะดื่มน้ําในแม่น้ําไม่ได้”’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 19, 'พระเยโฮวาห์ตรัสสั่งโมเสสว่า “จงบอกอาโรนว่า ‘เอาไม้เท้าของท่านชี้ไปเหนือน้ําทั้งหลายแห่งอียิปต์ คือเหนือลําคลอง แม่น้ํา บึง และสระทั้งหมดของเขา เพื่อน้ําจะกลายเป็นเลือดและจะมีเลือดทั่วแผ่นดินอียิปต์ ทั้งที่อยู่ในภาชนะไม้และภาชนะหิน’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 20, 'โมเสสกับอาโรนก็กระทําตามที่พระเยโฮวาห์บัญชา คือท่านได้ยกไม้เท้าขึ้นตีน้ําในแม่น้ําต่อสายพระเนตรของฟาโรห์ และท่ามกลางสายตาของพวกข้าราชการของฟาโรห์ แล้วน้ําในแม่น้ําก็กลายเป็นเลือดทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 21, 'ปลาที่อยู่ในแม่น้ําก็ตาย แม่น้ําก็เหม็น และชาวอียิปต์ก็ดื่มน้ําในแม่น้ํานั้นไม่ได้ มีเลือดทั่วแผ่นดินอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 22, 'แต่พวกนักแสดงกลแห่งอียิปต์ก็กระทําได้เหมือนกันอาศัยเล่ห์กลของเขา และพระทัยของฟาโรห์ก็แข็งกระด้าง ฟาโรห์หาเชื่อฟังท่านทั้งสองไม่ เหมือนที่พระเยโฮวาห์ได้ตรัสไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 23, 'ฟาโรห์เสด็จกลับเข้าในวัง มิได้เอาพระทัยใส่ในเหตุการณ์ครั้งนี้เหมือนกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 24, 'ชาวอียิปต์ทั้งปวงก็พากันขุดหลุมตามริมแม่น้ําหาน้ําดื่ม เพราะเขาดื่มน้ําในแม่น้ําไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 25, 'ครบกําหนดเจ็ดวันนับตั้งแต่พระเยโฮวาห์ทรงบันดาลให้แม่น้ําเป็นเลือด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 1, 'พระเยโฮวาห์ตรัสกับโมเสสว่า “ไปหาฟาโรห์บอกเขาว่า ‘พระเยโฮวาห์ตรัสดังนี้ว่า “จงปล่อยพลไพร่ของเราเพื่อเขาจะได้ไปปรนนิบัติเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 2, 'ถ้าท่านไม่ยอมให้เขาไป ดูเถิด เราจะให้ฝูงกบขึ้นมารังควานทั่วเขตแดนของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 3, 'ฝูงกบจะเต็มไปทั้งแม่น้ํา จะขึ้นมาอยู่ในวัง ในห้องบรรทม และบนแท่นบรรทมของท่าน ในเรือนข้าราชการ ตามตัวพลเมือง ในเตาปิ้งขนมและในอ่างขยําแป้งของท่านด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 4, 'ฝูงกบนั้นจะขึ้นมาที่ตัวฟาโรห์ ที่ตัวพลเมืองและที่ตัวข้าราชการทั้งปวงของท่าน”’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 5, 'แล้วพระเยโฮวาห์ตรัสกับโมเสสว่า “จงบอกอาโรนว่า ‘ให้เหยียดมือที่ถือไม้เท้าออกเหนือลําคลอง เหนือแม่น้ํา และเหนือบึงให้ฝูงกบขึ้นมาบนแผ่นดินอียิปต์’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 6, 'อาโรนก็เหยียดมือออกเหนือพื้นน้ําทั้งหลายในอียิปต์ ฝูงกบก็ขึ้นมาเต็มแผ่นดินอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 7, 'ฝ่ายพวกนักแสดงกลก็ทําตามเล่ห์กลของเขา ให้มีฝูงกบขึ้นมาบนแผ่นดินอียิปต์เหมือนกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 8, 'ฟาโรห์จึงตรัสเรียกโมเสสกับอาโรนมาว่า “จงกราบทูลวิงวอนขอพระเยโฮวาห์ทรงบันดาลให้ฝูงกบไปเสียจากเรา และจากพลเมืองของเรา แล้วเราจะยอมปล่อยให้บ่าวไพร่เหล่านั้นไปเพื่อเขาจะถวายเครื่องบูชาแด่พระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 9, 'โมเสสจึงทูลฟาโรห์ว่า “ข้าพระองค์ได้รับเกียรติมาก เวลาใดที่ข้าพระองค์ควรวิงวอนเพื่อพระองค์ ข้าราชบริพาร และพลเมืองของพระองค์ เพื่อให้ทรงทําลายฝูงกบไปเสียจากพระองค์และราชสํานักให้อยู่ในแม่น้ําเท่านั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 10, 'ฟาโรห์ตรัสตอบว่า “พรุ่งนี้” โมเสสจึงทูลว่า “ให้เป็นไปตามคําตรัสของพระองค์ เพื่อพระองค์จะได้ทราบว่าไม่มีผู้ใดเหมือนพระเยโฮวาห์พระเจ้าของข้าพระองค์ทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 11, 'ฝูงกบจะไปจากพระองค์ จากราชสํานัก จากข้าราชการและพลเมืองของพระองค์ เหลืออยู่เฉพาะแต่ในแม่น้ําเท่านั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 12, 'โมเสสกับอาโรนทูลลาไปจากฟาโรห์ แล้วโมเสสร้องทูลพระเยโฮวาห์เรื่องฝูงกบที่พระองค์ได้ทรงให้มาทรมานฟาโรห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 13, 'พระเยโฮวาห์ทรงกระทําตามคําทูลขอของโมเสส ฝูงกบเหล่านั้นก็ตายเกลื่อนบ้านเรือน เกลื่อนหมู่บ้านและทุ่งนา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 14, 'เขาก็เก็บซากกบไว้เป็นกองๆ แผ่นดินก็เหม็นตลบไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 15, 'แต่เมื่อฟาโรห์ทรงเห็นว่าความเดือดร้อนลดน้อยลงแล้ว ก็กลับมีพระทัยแข็งกระด้าง ไม่ยอมเชื่อฟังโมเสสและอาโรน เหมือนที่พระเยโฮวาห์ได้ตรัสไว้แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 16, 'พระเยโฮวาห์จึงตรัสกับโมเสสว่า “บอกอาโรนว่า ‘จงเหยียดไม้เท้าออกและตีฝุ่นดินให้กลายเป็นเหาทั่วประเทศอียิปต์’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 17, 'เขาทั้งสองก็กระทําตาม ด้วยว่าอาโรนเหยียดมือออกยกไม้เท้าและตีฝุ่นดิน ก็กลายเป็นเหามาอยู่ในมนุษย์และสัตว์ ฝุ่นดินทั้งหมดกลายเป็นเหาทั่วประเทศอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 18, 'ฝ่ายพวกนักแสดงกลก็พยายามใช้เล่ห์กลของเขา เพื่อทําให้เกิดเหา แต่ก็ทําไม่ได้ เหาพากันมาอยู่ในมนุษย์และสัตว์ทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 19, 'พวกนักแสดงกลจึงทูลฟาโรห์ว่า “นี่เป็นนิ้วพระหัตถ์พระเจ้า” ฝ่ายฟาโรห์มีพระทัยแข็งกระด้าง หาเชื่อฟังเขาไม่ เหมือนที่พระเยโฮวาห์ได้ตรัสไว้แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 20, 'พระเยโฮวาห์ตรัสกับโมเสสว่า “ลุกขึ้นแต่เช้าไปคอยเฝ้าฟาโรห์ ดูเถิด ฟาโรห์จะมายังแม่น้ํา แล้วบอกฟาโรห์ว่า ‘พระเยโฮวาห์ตรัสดังนี้ว่า “จงปล่อยพลไพร่ของเราเพื่อเขาจะไปปรนนิบัติเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 21, 'ถ้าแม้ไม่ปล่อยพลไพร่ของเราไป ดูเถิด เราจะใช้ให้ฝูงเหลือบมาตอมกายของเจ้า ตอมข้าราชการและพลเมืองของเจ้าด้วย ในราชสํานัก บ้านเรือนของชาวอียิปต์ และพื้นดินที่เขาอยู่นั้นจะเต็มไปด้วยฝูงเหลือบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 22, 'ในวันนั้นเราจะแยกแผ่นดินโกเชน ที่พลไพร่ของเราอาศัยอยู่นั้นออก มิให้มีฝูงเหลือบที่นั่น เพื่อเจ้าจะได้รู้ว่าเราคือพระเยโฮวาห์ สถิตอยู่ท่ามกลางแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 23, 'เราจะแบ่งเขตแดนในระหว่างชนชาติของเรากับชนชาติของเจ้า หมายสําคัญนี้จะบังเกิดขึ้นในวันพรุ่งนี้”’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 24, 'แล้วพระเยโฮวาห์ก็ทรงกระทําดังนั้น เหลือบฝูงใหญ่ยิ่งนักเข้าไปในพระราชวังของฟาโรห์ ในเรือนข้าราชการ และทั่วแผ่นดินอียิปต์ แผ่นดินได้รับความเสียหายเพราะเหตุฝูงเหลือบนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 25, 'ฟาโรห์จึงตรัสเรียกโมเสสกับอาโรนมา รับสั่งว่า “จงไปถวายเครื่องบูชาแด่พระเจ้าของเจ้าในเขตแผ่นดินนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 26, 'โมเสสทูลว่า “การกระทําเช่นนั้นหาควรไม่ เพราะข้าพระองค์ทั้งหลายจะต้องถวายเครื่องบูชาซึ่งเป็นสิ่งที่น่าเกลียดสําหรับชาวอียิปต์แด่พระเยโฮวาห์พระเจ้าของข้าพระองค์ ดูเถิด ข้าพระองค์ทั้งหลายจะถวายเครื่องบูชาซึ่งเป็นสิ่งที่น่าเกลียดสําหรับชาวอียิปต์ต่อหน้าต่อตาเขา แล้วเขาจะไม่เอาก้อนหินขว้างข้าพระองค์ทั้งหลายหรอกหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 27, 'ข้าพระองค์ทั้งหลายจะเดินทางไปในถิ่นทุรกันดารสักสามวันถวายเครื่องบูชาแด่พระเยโฮวาห์พระเจ้าของพวกข้าพระองค์ ตามที่พระองค์จะทรงบัญชาพวกข้าพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 28, 'ฟาโรห์จึงรับสั่งว่า “เราจะปล่อยพวกเจ้าไป เพื่อพวกเจ้าจะได้ถวายเครื่องบูชาแด่พระเยโฮวาห์พระเจ้าของเจ้าในถิ่นทุรกันดาร แต่ว่าพวกเจ้าอย่าไปให้ไกลนัก จงวิงวอนเพื่อเราด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 29, 'โมเสสจึงทูลว่า “ดูเถิด พอข้าพระองค์ทูลลาพระองค์ไป และข้าพระองค์จะอธิษฐานทูลพระเยโฮวาห์ ขอให้ฝูงเหลือบไปเสียจากฟาโรห์ จากข้าราชการและจากพลเมืองในเวลาพรุ่งนี้ แต่ขอฟาโรห์อย่าทรงทํากลับกลอกอีกโดยไม่ยอมปล่อยบ่าวไพร่ให้ไปถวายเครื่องบูชาแด่พระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 30, 'โมเสสทูลลาฟาโรห์ไปแล้วก็อธิษฐานต่อพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 31, 'พระเยโฮวาห์ทรงกระทําตามคําทูลขอของโมเสส พระองค์ทรงให้ฝูงเหลือบไปเสียจากฟาโรห์ จากข้าราชการและจากพลเมืองของพระองค์ มิได้เหลืออยู่สักตัวเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 32, 'ฝ่ายฟาโรห์ก็กลับมีพระทัยแข็งกระด้างในคราวนี้อีก มิได้ทรงปล่อยบ่าวไพร่นั้นไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 1, 'ขณะนั้นพระเยโฮวาห์จึงตรัสกับโมเสสว่า “ไปเข้าเฝ้าฟาโรห์บอกฟาโรห์ว่า ‘พระเยโฮวาห์พระเจ้าของคนฮีบรูตรัสดังนี้ว่า “จงปล่อยให้พลไพร่ของเราไป เพื่อเขาจะได้ปรนนิบัติเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 2, 'ด้วยว่าถ้าเจ้าไม่ยอมปล่อยให้ไป และยังหน่วงเหนี่ยวเขาไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 3, 'ดูเถิด หัตถ์ของพระเยโฮวาห์จะอยู่บนฝูงสัตว์ของเจ้าซึ่งอยู่ในทุ่งนา ฝูงม้า ฝูงลา ฝูงอูฐ ฝูงวัว และฝูงแกะ จะทําให้เป็นโรคระบาดร้ายแรงขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 4, 'และพระเยโฮวาห์จะทรงกระทําต่อฝูงสัตว์ของชนชาติอิสราเอลต่างกับฝูงสัตว์ของชาวอียิปต์ สัตว์ของคนอิสราเอลจะไม่ต้องตายเลย”’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 5, 'พระเยโฮวาห์ทรงกําหนดเวลาไว้ว่า “พรุ่งนี้พระเยโฮวาห์จะทรงกระทําสิ่งนี้ในแผ่นดิน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 6, 'รุ่งขึ้นพระเยโฮวาห์ก็ทรงกระทําสิ่งนั้น ฝูงสัตว์ของชาวอียิปต์ตายหมด แต่สัตว์ของชาติอิสราเอลไม่ตายสักตัวเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 7, 'ฟาโรห์ทรงใช้คนไปดู และดูเถิด สัตว์ของคนอิสราเอลไม่ตายสักตัวเดียว แต่พระทัยของฟาโรห์ก็แข็งกระด้าง พระองค์ไม่ยอมปล่อยให้บ่าวไพร่ไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 8, 'พระเยโฮวาห์จึงตรัสแก่โมเสสและอาโรนว่า “เจ้าจงกําขี้เถ้าจากเตาให้เต็มกํามือแล้วให้โมเสสซัดขึ้นไปในอากาศในสายตาของฟาโรห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 9, 'และมันจะกลายเป็นฝุ่นปลิวไปทั่วแผ่นดินอียิปต์ทําให้เกิดเป็นฝีแตกลามทั้งตัวคนและสัตว์ทั่วแผ่นดินอียิปต์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 10, 'เขาทั้งสองจึงนําขี้เถ้าจากเตาไปยืนอยู่ต่อพระพักตร์ฟาโรห์ และโมเสสก็ซัดขี้เถ้าขึ้นไปในท้องฟ้า ขี้เถ้านั้นก็กลายเป็นฝีแตกลามไปทั้งตัวคนและสัตว์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 11, 'ฝ่ายพวกนักแสดงกลก็ไม่สามารถยืนอยู่ต่อหน้าโมเสสเพราะเหตุฝีนั้น เพราะนักแสดงกลและชาวอียิปต์ทั้งปวง ก็เป็นฝีด้วยเหมือนกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 12, 'แต่พระเยโฮวาห์ทรงทําให้พระทัยของฟาโรห์แข็งกระด้าง ฟาโรห์ไม่ยอมเชื่อฟังโมเสสและอาโรน เหมือนที่พระเยโฮวาห์ได้ตรัสกับโมเสสไว้แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 13, 'พระเยโฮวาห์ตรัสกับโมเสสว่า “จงตื่นแต่เช้าไปยืนต่อหน้าฟาโรห์บอกเขาว่า ‘พระเยโฮวาห์พระเจ้าของคนฮีบรูตรัสดังนี้ว่า “จงปล่อยพลไพร่ของเราเพื่อเขาจะไปปรนนิบัติเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 14, 'ด้วยว่าคราวนี้เราจะบันดาลให้เกิดภัยพิบัติทั้งหมดแก่จิตใจเจ้า และแก่ข้าราชการ และแก่พลเมืองของเจ้า เพื่อเจ้าจะได้รู้แน่ว่า ทั่วโลกไม่มีผู้ใดจะเปรียบกับเราได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 15, 'เพราะเดี๋ยวนี้เราจะเหยียดมือของเราออกเพื่อจะฟาดเจ้าและประชาชนของเจ้าด้วยภัยพิบัติ และเจ้าจะถูกตัดออกไปจากแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 16, 'และเพราะเหตุนี้เราให้เจ้ามีตําแหน่งสูง ก็เพื่อจะแสดงฤทธานุภาพของเราโดยเจ้าและเพื่อให้นามของเราถูกประกาศออกไปทั่วโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 17, 'เจ้ายังถือทิฐิต่อสู้พลไพร่ของเรา เจ้าจึงไม่ยอมปล่อยเขาไปหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 18, 'ดูเถิด พรุ่งนี้ประมาณเวลานี้ เราจะทําให้ลูกเห็บตกลงมาอย่างหนัก อย่างที่ไม่เคยมีในอียิปต์ ตั้งแต่เริ่มสร้างบ้านเมืองมาจนบัดนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 19, 'เหตุฉะนั้น บัดนี้จงต้อนฝูงสัตว์ และทุกสิ่งที่เจ้ามีอยู่ในทุ่งนาให้เข้าที่กําบัง เพราะคนทุกคนและสัตว์ทุกตัวที่อยู่ในทุ่งนาที่มิได้เข้ามาอยู่ในบ้านจะถูกลูกเห็บตายหมด”’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 20, 'บรรดาข้าราชการของฟาโรห์ที่เกรงกลัวพระดํารัสของพระเยโฮวาห์ก็ให้ทาสและสัตว์ของตนกลับเข้าบ้าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 21, 'แต่ผู้ที่ไม่นับถือพระดํารัสของพระเยโฮวาห์ก็ยังคงปล่อยให้ทาสและสัตว์ของตนอยู่ในทุ่งนา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 22, 'พระเยโฮวาห์ตรัสกับโมเสสว่า “จงชูมือขึ้นยังท้องฟ้า เพื่อลูกเห็บจะได้ตกลงมาทั่วแผ่นดินอียิปต์ บนมนุษย์ บนสัตว์และบนผักหญ้าทุกอย่างซึ่งอยู่ในทุ่งนาทั่วแผ่นดินอียิปต์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 23, 'โมเสสก็ชูไม้เท้าของตนขึ้นยังท้องฟ้าแล้วพระเยโฮวาห์ทรงบันดาลให้มีเสียงฟ้าร้อง มีลูกเห็บ และไฟตกลงมาบนแผ่นดิน และพระเยโฮวาห์ทรงบันดาลให้ลูกเห็บตกบนแผ่นดินอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 24, 'มีลูกเห็บและลูกเห็บปนไฟตกหนักยิ่งนักอย่างที่ไม่เคยมีทั่วแผ่นดินอียิปต์ ตั้งแต่เริ่มตั้งเป็นประเทศมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 25, 'สิ่งทั้งปวงที่อยู่ในทุ่งนาทั่วแผ่นดินอียิปต์ ก็ถูกลูกเห็บทําลายเสียสิ้นทั้งคนและสัตว์ ลูกเห็บยังทําลายผักและต้นไม้ทุกอย่างที่อยู่ในทุ่งนาหักโค่นลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 26, 'เว้นแต่ที่แผ่นดินโกเชน ที่ชนชาติอิสราเอลอยู่นั้น หามีลูกเห็บตกไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 27, 'ฟาโรห์จึงทรงใช้คนไปเรียกโมเสสและอาโรนมาเฝ้า แล้วตรัสว่า “ครั้งนี้เราทําบาปแน่แล้ว พระเยโฮวาห์ทรงชอบธรรม เราและชนชาติของเรานั้นก็ชั่ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 28, 'ขอทูลวิงวอนพระเยโฮวาห์ (เพราะภัยพิบัติเสียที) ให้เลิกมีฟ้าร้องและลูกเห็บ และเราจะปล่อยพวกท่านไป และพวกท่านจะไม่ถูกกักต่อไปอีก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 29, 'โมเสสทูลฟาโรห์ว่า “ทันทีที่ข้าพระองค์ออกไปจากกรุงนี้แล้วข้าพระองค์จะยกมือทูลพระเยโฮวาห์ เสียงฟ้าร้องก็จะเงียบ และจะไม่มีลูกเห็บตกอีก เพื่อพระองค์จะได้ทราบว่าโลกนี้เป็นของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 30, 'แต่ฝ่ายพระองค์และข้าราชการนั้น ข้าพระองค์ทราบว่า พระองค์จะยังไม่ยําเกรงพระเยโฮวาห์พระเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 31, 'ต้นป่านและต้นข้าวบาร์เลย์ถูกทําลายเสีย เพราะต้นข้าวบาร์เลย์ก็กําลังออกรวง และต้นป่านก็ออกดอกแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 32, 'ส่วนข้าวสาลีและข้าวไรนั้นมิได้ถูกทําลาย เพราะยังไม่งอกขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 33, 'โมเสสทูลลาฟาโรห์ไปจากกรุง และก็ยกมือขึ้นทูลพระเยโฮวาห์ เสียงฟ้าร้องกับลูกเห็บนั้นก็หยุด ฝนก็มิได้ตกบนแผ่นดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 34, 'เมื่อฟาโรห์เห็นว่า ฝน ลูกเห็บและฟ้าร้องนั้นหยุดแล้ว พระองค์ก็กลับทรงกระทําผิดบาปต่อไปอีก พระทัยแข็งกระด้าง ทั้งพระองค์และข้าราชการ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 35, 'พระทัยของฟาโรห์แข็งกระด้างและไม่ยอมปล่อยชนชาติอิสราเอลไปจริง เหมือนที่พระเยโฮวาห์ได้ตรัสไว้กับโมเสส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 1, 'พระเยโฮวาห์จึงตรัสกับโมเสสว่า “จงเข้าไปหาฟาโรห์ เพราะเราได้ทําให้ใจของฟาโรห์ และใจของข้าราชการแข็งกระด้าง เพื่อเราจะได้แสดงหมายสําคัญเหล่านี้ของเราต่อหน้าพวกเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 2, 'เพื่อเจ้าจะได้เล่าเหตุการณ์ที่เราได้กระทําแก่ชาวอียิปต์ให้ลูกหลานฟัง รวมทั้งหมายสําคัญซึ่งเราได้กระทําท่ามกลางพวกเขา เพื่อพวกเจ้าจะได้รู้ว่าเราคือพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 3, 'โมเสสและอาโรนจึงเข้าไปเฝ้าฟาโรห์ทูลฟาโรห์ว่า “พระเยโฮวาห์พระเจ้าของคนฮีบรูตรัสดังนี้ว่า ‘เจ้าจะขัดขืนไม่ยอมอ่อนน้อมต่อเรานานสักเท่าใด จงปล่อยพลไพร่ของเราเพื่อเขาจะไปปรนนิบัติเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 4, 'มิฉะนั้นถ้าเจ้าไม่ยอมปล่อยพลไพร่ของเราไป ดูเถิด พรุ่งนี้เราจะให้ตั๊กแตนเข้ามาในเขตแดนของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 5, 'ฝูงตั๊กแตนนั้นจะปกคลุมพื้นแผ่นดินจนแลไม่เห็นพื้นดิน และสิ่งที่เหลือจากลูกเห็บทําลาย มันจะกิน และต้นไม้ทุกต้นซึ่งงอกขึ้นให้เจ้าในทุ่งนานั้น มันจะกินเสียหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 6, 'มันจะเข้าไปในราชสํานัก ในบ้านเรือนของข้าราชการ และในบ้านเรือนของบรรดาชาวอียิปต์จนเต็มหมด อย่างที่บิดาและปู่ทวด ตั้งแต่เกิดมาจนทุกวันนี้ ไม่เคยเห็นเช่นนี้เลย’” แล้วโมเสสก็กลับออกไปจากฟาโรห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 7, 'บรรดาข้าราชการของฟาโรห์ทูลฟาโรห์ว่า “คนนี้จะเป็นบ่วงแร้วดักเราไปนานสักเท่าใด ขอทรงพระกรุณาปลดปล่อยคนเหล่านั้นให้ไปปรนนิบัติพระเยโฮวาห์พระเจ้าของเขาเถิด พระองค์ยังไม่ทรงทราบหรือว่าอียิปต์กําลังพินาศแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 8, 'โมเสสและอาโรนถูกนําตัวเข้ามาเฝ้าฟาโรห์อีก พระองค์จึงตรัสแก่เขาว่า “ไปปรนนิบัติพระเยโฮวาห์พระเจ้าของเจ้า แต่ใครจะไปบ้าง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 9, 'โมเสสทูลว่า “ข้าพระองค์จะต้องพากันไปทั้งคนหนุ่มและคนแก่ บุตรชายและบุตรสาวและฝูงแพะแกะ และฝูงวัว เพราะข้าพระองค์ทั้งหลายต้องมีเทศกาลเลี้ยงถวายพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 10, 'ฟาโรห์ตรัสกับเขาทั้งสองว่า “ถ้าเรายอมให้เจ้าไปกับบุตรด้วย ก็ให้พระเยโฮวาห์ทรงสถิตอยู่กับพวกเจ้าเถิด ระวังตัวให้ดีเถิด เจ้ากําลังมุ่งไปในทางทุจริตเสียแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 11, 'อนุญาตไม่ได้ จงพาเฉพาะแต่ผู้ชายไปปรนนิบัติพระเยโฮวาห์ เพราะเจ้าปรารถนาเช่นนี้เท่านั้น” แล้วโมเสสกับอาโรนก็ถูกขับไล่ออกไปเสียจากพระพักตร์ของฟาโรห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 12, 'พระเยโฮวาห์จึงตรัสกับโมเสสว่า “จงเหยียดมือออกเหนือประเทศอียิปต์ให้ฝูงตั๊กแตนมาเหนือแผ่นดินอียิปต์ ให้กินผักทั่วไปของแผ่นดินซึ่งเหลือจากลูกเห็บทําลาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 13, 'โมเสสจึงยื่นไม้เท้าออกเหนือแผ่นดินอียิปต์ พระเยโฮวาห์ก็ทรงบันดาลให้ลมตะวันออกพัดมาเหนือพื้นแผ่นดินทั้งกลางวันและกลางคืนตลอดวันนั้น ครั้นเวลารุ่งเช้า ลมตะวันออกก็พัดหอบฝูงตั๊กแตนมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 14, 'ฝูงตั๊กแตนลงทั่วแผ่นดินอียิปต์ และจับอยู่ทั่วเขตแดนอียิปต์ทั้งหมด มันรุนแรงมาก แต่ก่อนไม่เคยมีตั๊กแตนอย่างนี้เลย และต่อไปข้างหน้าจะหามีอย่างนั้นอีกไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 15, 'เพราะมันปกคลุมพื้นแผ่นดินจนแลมืดไป มันกินผักในแผ่นดินทุกอย่าง และผลไม้ทุกอย่างซึ่งเหลือจากลูกเห็บทําลาย ไม่มีพืชใบเขียวเหลือเลย ไม่ว่าต้นไม้หรือผักในทุ่ง ทั่วแผ่นดินอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 16, 'ฟาโรห์จึงรีบให้คนไปตามโมเสสและอาโรนเข้าเฝ้า แล้วฟาโรห์ตรัสว่า “เราได้ทําบาปต่อพระเยโฮวาห์พระเจ้าของเจ้า และต่อเจ้าทั้งสองด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 17, 'เหตุฉะนั้นบัดนี้ขอเจ้ายกโทษบาปให้เราครั้งนี้สักครั้งเถิด และวิงวอนขอพระเยโฮวาห์พระเจ้าของเจ้า เพื่อพระองค์จะได้ทรงโปรดให้ความตายนี้พ้นไปจากเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 18, 'โมเสสก็ไปจากฟาโรห์ และทูลวิงวอนพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 19, 'พระเยโฮวาห์จึงทรงบันดาลให้ลมพายุพัดกลับมาจากทิศตะวันตกหอบฝูงตั๊กแตนไปตกในทะเลแดง จนไม่มีตั๊กแตนเหลือเลยสักตัวเดียวตลอดเขตแดนอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 20, 'แต่พระเยโฮวาห์ทรงทําให้พระทัยของฟาโรห์แข็งกระด้างเพื่อพระองค์จะไม่ยอมปล่อยชนชาติอิสราเอลไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 21, 'พระเยโฮวาห์ตรัสกับโมเสสว่า “จงชูมือของเจ้าขึ้นสู่ท้องฟ้า เพื่อจะให้มีความมืดทั่วแผ่นดินอียิปต์ เป็นความมืดจนจับคลําได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 22, 'โมเสสจึงชูมือขึ้นสู่ท้องฟ้า แล้วก็เกิดมีความมืดทึบทั่วไปในแผ่นดินอียิปต์ตลอดสามวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 23, 'เขามองกันไม่เห็น ไม่มีใครลุกไปจากที่ของเขาสามวัน แต่บรรดาชนชาติอิสราเอลนั้นมีแสงสว่างอยู่ในที่อาศัยของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 24, 'ฟาโรห์จึงให้ตามตัวโมเสสเข้าเฝ้า ตรัสว่า “พวกเจ้าจงไปปรนนิบัติพระเยโฮวาห์เถิด เพียงแต่ให้ฝูงแกะและฝูงวัวอยู่ ส่วนเด็กไปกับเจ้าได้ด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 25, 'ฝ่ายโมเสสจึงทูลว่า “พระองค์ต้องให้เรามีเครื่องบูชาและเครื่องเผาบูชาไปด้วย เพื่อพวกข้าพระองค์จะได้บูชาต่อพระเยโฮวาห์พระเจ้าของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 26, 'ข้าพระองค์ต้องนําฝูงสัตว์ไปด้วย ขาดไม่ได้สักกีบเดียว เพราะว่าจะต้องเอาสัตว์จากฝูงเหล่านั้นไปถวายพระเยโฮวาห์พระเจ้าของข้าพระองค์ และข้าพระองค์ยังไม่ทราบว่าจะต้องการสัตว์ตัวใดถวายพระเยโฮวาห์ จนกว่าเราจะถึงที่นั่น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 27, 'แต่พระเยโฮวาห์ทรงทําให้พระทัยฟาโรห์แข็งกระด้าง พระองค์จึงไม่ยอมปล่อยเขาไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 28, 'ฟาโรห์รับสั่งแก่โมเสสว่า “ไปให้พ้นจากเรา ระวังตัวให้ดีเถอะ อย่ามาเห็นหน้าเราอีกเลยเพราะถ้าเจ้าเห็นหน้าเราวันใด เจ้าจะต้องตายวันนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 29, 'โมเสสจึงทูลว่า “พระองค์ตรัสถูกแล้ว ข้าพระองค์จะไม่มาเห็นพระพักตร์ของพระองค์อีกเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 1, 'พระเยโฮวาห์ตรัสกับโมเสสว่า “เราจะนําภัยพิบัติมาสู่ฟาโรห์และอียิปต์อีกอย่างเดียว หลังจากนั้นเขาจะปล่อยพวกเจ้าไปจากที่นี่ เมื่อเขาให้พวกเจ้าไปคราวนี้ เขาจะขับไล่พวกเจ้าออกไปทีเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 2, 'บัดนี้เจ้าจงสั่งให้ประชาชนทั้งปวง ให้ผู้ชายผู้หญิงทุกคน ขอเครื่องเงินเครื่องทองจากเพื่อนบ้านของตน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 3, 'พระเยโฮวาห์ทรงบันดาลให้ประชาชนเป็นที่โปรดปรานในสายตาของชาวอียิปต์ นอกจากนี้บุรุษผู้นั้นคือโมเสสก็ยิ่งใหญ่มากในแผ่นดินอียิปต์ ทั้งในสายตาข้าราชการของฟาโรห์และในสายตาพลเมืองทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 4, 'โมเสสประกาศว่า “พระเยโฮวาห์ตรัสดังนี้ว่า ‘เวลาประมาณเที่ยงคืน เราจะออกไปท่ามกลางอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 5, 'และพวกลูกหัวปีทั้งหมดในแผ่นดินอียิปต์ ตั้งแต่ราชบุตรหัวปีของฟาโรห์ ผู้ประทับบนพระที่นั่ง จนถึงบุตรหัวปีของทาสหญิง ซึ่งอยู่หลังหินโม่แป้ง ทั้งลูกหัวปีของสัตว์เดียรัจฉานด้วยจะต้องตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 6, 'แล้วจะมีการพิลาปร้องไห้ทั่วแผ่นดินอียิปต์อย่างที่ไม่เคยมีมาก่อน และต่อไปภายหน้าก็จะไม่มีอีกเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 7, 'ฝ่ายคนหรือสัตว์ของชนชาติอิสราเอลทั้งปวงจะไม่มีแม้แต่เสียงสุนัขขู่ เพื่อให้ทราบว่าพระเยโฮวาห์ทรงกระทําต่อชาวอียิปต์ต่างกับชนชาติอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 8, 'ข้าราชการของพระองค์จะลงมาหาเรากราบลงต่อหน้าเรากล่าวว่า “ขอท่านกับพรรคพวกไปเสียจากที่นี่เถิด” หลังจากนั้นเราก็จะออกไป’” โมเสสทูลลาฟาโรห์ไปด้วยความโกรธยิ่งนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 9, 'แล้วพระเยโฮวาห์ตรัสตอบโมเสสว่า “ฟาโรห์จะไม่เชื่อฟังเจ้า เพื่อมหัศจรรย์ของเราจะได้เพิ่มขึ้นอีกในแผ่นดินอียิปต์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 10, 'โมเสสกับอาโรนก็ได้กระทําบรรดามหัศจรรย์เหล่านั้นต่อพระพักตร์ฟาโรห์ และพระเยโฮวาห์ทรงกระทําให้พระทัยของฟาโรห์แข็งกระด้างไป ท่านจึงไม่ยอมปล่อยชนชาติอิสราเอลให้ออกไปจากแผ่นดินของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 1, 'พระเยโฮวาห์ตรัสกับโมเสสและอาโรนในประเทศอียิปต์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 2, '“ให้เดือนนี้เป็นเดือนเริ่มต้นสําหรับเจ้าทั้งหลาย ให้เป็นเดือนแรกในปีใหม่สําหรับพวกเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 3, 'จงสั่งชุมนุมคนอิสราเอลทั้งหมดว่า ในวันที่สิบเดือนนี้ ให้ผู้ชายทุกคนเตรียมลูกแกะ ครอบครัวละตัวตามเรือนบรรพบุรุษของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 4, 'ถ้าครอบครัวใดมีคนน้อยกินลูกแกะตัวหนึ่งไม่หมด ก็ให้รวมกับเพื่อนบ้านที่อยู่ใกล้เคียงกันเตรียมลูกแกะตัวหนึ่งตามจํานวนคนตามที่เขาจะกินได้กี่มากน้อย ให้นับจํานวนคนที่จะกินลูกแกะนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 5, 'ลูกแกะของเจ้าต้องปราศจากตําหนิเป็นตัวผู้อายุไม่เกินหนึ่งขวบ เจ้าจงเอามาจากฝูงแกะ หรือฝูงแพะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 6, 'จงเก็บไว้ให้ดีถึงวันที่สิบสี่เดือนนี้ แล้วในเย็นวันนั้นให้ที่ประชุมของคนอิสราเอลทั้งหมดฆ่าลูกแกะของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 7, 'แล้วเอาเลือดทาที่ไม้วงกบประตูทั้งสองข้าง และไม้ข้างบน ณ เรือนที่เขาเลี้ยงกันนั้นด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 8, 'ในคืนวันนั้นให้เขากินเนื้อปิ้ง กับขนมปังไร้เชื้อและผักรสขม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 9, 'เนื้อที่ยังดิบหรือเนื้อต้มอย่ากินเลย แต่จงปิ้งทั้งหัวและขา และเครื่องในด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 10, 'จงกินให้หมดอย่าให้มีเศษเหลือจนถึงเวลาเช้า เศษเหลือถึงเวลาเช้าก็ให้เผาเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 11, 'เจ้าทั้งหลายจงเลี้ยงกันดังนี้ คือให้คาดเอว สวมรองเท้า และถือไม้เท้าไว้ และรีบกินโดยเร็ว การเลี้ยงนี้เป็นปัสกาของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 12, 'เพราะในคืนวันนั้น เราจะผ่านไปในประเทศอียิปต์ และเราจะประหารลูกหัวปีทั้งหมดในประเทศอียิปต์ ทั้งของมนุษย์และของสัตว์ และเราจะพิพากษาลงโทษพระทั้งปวงของอียิปต์ เราคือพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 13, 'แต่เลือดที่บ้านที่เจ้าทั้งหลายอยู่นั้น จะเป็นหมายสําคัญสําหรับเจ้า เมื่อเราเห็นเลือดนั้นเราจะผ่านเว้นเจ้าทั้งหลายไป จะไม่มีภัยพิบัติทําลายเจ้า ขณะที่เราประหารประเทศอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 14, 'วันนั้นจะเป็นวันที่ระลึกสําหรับเจ้า ให้เจ้าทั้งหลายถือไว้เป็นเทศกาลแด่พระเยโฮวาห์ตลอดชั่วอายุของเจ้า เจ้าจงฉลองเทศกาลนี้และถือเป็นกฎถาวร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 15, 'เจ้าทั้งหลายจงกินขนมปังไร้เชื้อให้ครบเจ็ดวัน วันแรกจงชําระบ้านเจ้าให้ปราศจากเชื้อ ถ้าผู้ใดขืนกินขนมปังที่มีเชื้อตั้งแต่วันแรกจนถึงวันที่เจ็ด ผู้นั้นจะต้องถูกตัดขาดจากอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 16, 'ในวันแรกนั้นให้มีการประชุมบริสุทธิ์ และในวันที่เจ็ดนั้นจะเป็นวันประชุมอันบริสุทธิ์แก่ท่าน ในวันเหล่านั้นอย่าให้ผู้ใดทํางานเลย เว้นไว้แต่การจัดเตรียมอาหารสําหรับรับประทาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 17, 'เจ้าทั้งหลายจงถือเทศกาลกินขนมปังไร้เชื้อ เพราะในวันนั้นเราได้นําพลโยธาของเจ้าทั้งหลายออกไปจากแผ่นดินอียิปต์ เหตุฉะนี้ เจ้าจงฉลองวันนั้นและถือเป็นกฎถาวรตลอดชั่วอายุของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 18, 'ในตอนเย็นวันที่สิบสี่เดือนแรก เจ้าทั้งหลายจงกินขนมปังไร้เชื้อจนถึงเวลาเย็นวันที่ยี่สิบเอ็ดของเดือนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 19, 'ในเจ็ดวันนั้นอย่าให้พบเชื้อในบ้านของเจ้าเลย เพราะว่าถ้าผู้ใดที่เป็นคนต่างด้าวก็ดีหรือคนเกิดในเมืองก็ดี ขืนกินสิ่งใดๆที่มีเชื้อ ผู้นั้นจะต้องถูกตัดขาดจากที่ชุมนุมของอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 20, 'อย่ากินสิ่งใดที่มีเชื้อ ในที่อาศัยของเจ้า เจ้าจงกินแต่ขนมปังไร้เชื้อเท่านั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 21, 'แล้วโมเสสเรียกบรรดาพวกผู้ใหญ่ของคนอิสราเอลมาพร้อมกันสั่งว่า “ท่านทั้งหลายจงไปเอาลูกแกะตามครอบครัวของท่านมาฆ่าเป็นลูกแกะปัสกา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 22, 'เอาต้นหุสบกําหนึ่งจุ่มลงในเลือดที่อยู่ในอ่าง แล้วป้ายเลือดนั้นไว้ที่ไม้ข้างบน และไม้วงกบประตูทั้งสองข้างด้วยเลือดที่อยู่ในอ่าง อย่าให้ผู้ใดออกไปพ้นประตูบ้านของตนจนถึงรุ่งเช้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 23, 'เพราะพระเยโฮวาห์จะเสด็จผ่านไปเพื่อจะได้ประหารคนอียิปต์ เมื่อพระองค์ทรงเห็นเลือดที่ไม้ประตูข้างบนและที่ไม้วงกบประตูทั้งสองข้าง พระเยโฮวาห์จะทรงผ่านเว้นประตูนั้น ไม่ทรงยอมให้ผู้สังหารเข้าไปในบ้านท่าน เพื่อจะประหารท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 24, 'ท่านทั้งหลายจงถือพิธีนี้ให้เป็นกฎถาวรของท่านและของลูกหลานท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 25, 'ต่อมาครั้นท่านไปถึงแผ่นดินซึ่งพระเยโฮวาห์จะทรงประทานแก่ท่านตามที่ได้ทรงสัญญาไว้แล้วนั้น ท่านจงถือพิธีนี้ไว้ปฏิบัติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 26, 'ครั้นสืบไปภายหน้าเมื่อลูกหลานของท่านถามว่า ‘พิธีนี้หมายความว่ากระไร’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 27, 'ท่านทั้งหลายจงตอบว่า ‘เป็นการถวายสัตวบูชาปัสกาแด่พระเยโฮวาห์ ผู้ทรงผ่านเว้นบ้านของชนชาติอิสราเอลในอียิปต์ เมื่อพระองค์ทรงประหารคนอียิปต์ แต่ไว้ชีวิตครอบครัวของเราทั้งหลาย’” พลไพร่ทั้งปวงก็กราบลงนมัสการ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 28, 'แล้วคนชาติอิสราเอลก็ไปทําตามคําสั่งทุกประการ พระเยโฮวาห์ทรงรับสั่งกับโมเสสและอาโรนอย่างไร เขาทั้งหลายก็กระทําตามทุกประการ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 29, 'ต่อมาในเวลาเที่ยงคืน พระเยโฮวาห์ทรงประหารบุตรหัวปีทุกคนในประเทศอียิปต์ ตั้งแต่พระราชบุตรหัวปีของฟาโรห์ผู้ประทับบนพระที่นั่ง จนถึงบุตรหัวปีของเชลยที่อยู่ในคุกใต้ดิน ทั้งลูกหัวปีของสัตว์เลี้ยงทุกตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 30, 'ฟาโรห์กับข้าราชการ และชาวอียิปต์ทั้งปวงตื่นขึ้นในตอนกลางคืน มีเสียงร้องไห้คร่ําครวญดังทั่วทั้งอียิปต์ เนื่องด้วยไม่มีบ้านใดเลยที่ไม่มีคนตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 31, 'ฟาโรห์จึงตรัสเรียกโมเสสกับอาโรนให้มาเฝ้าในคืนวันนั้น ตรัสว่า “เจ้าทั้งสองกับทั้งชนชาติอิสราเอลจงยกออกไปจากประชาชนของเราเถิด ไปปรนนิบัติพระเยโฮวาห์ตามที่ได้พูดไว้นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 32, 'เอาฝูงแพะแกะและฝูงวัวของเจ้าไปด้วยตามที่เจ้าได้พูดไว้แล้ว ไปและอวยพรให้เราด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 33, 'ฝ่ายชาวอียิปต์ก็เร่งรัดให้พลไพร่นั้นออกไปจากประเทศโดยเร็ว เพราะเขาพูดว่า “พวกเราตายกันหมดแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 34, 'พลไพร่นั้นเอาก้อนแป้งดิบที่ยังมิได้ใส่เชื้อกับอ่างขยําแป้ง ห่อผ้าใส่บ่าแบกไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 35, 'ชนชาติอิสราเอลกระทําตามคําสั่งของโมเสสคือ ขอเครื่องเงิน เครื่องทองและเครื่องนุ่งห่มจากชาวอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 36, 'และพระเยโฮวาห์ทรงบันดาลให้พลไพร่นั้นเป็นที่โปรดปรานในสายตาของชาวอียิปต์ เขาจึงให้สิ่งของทั้งปวงตามที่เขาขอ เขาจึงได้ริบเอาสิ่งของต่างๆของชาวอียิปต์เสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 37, 'ชนชาติอิสราเอลยกเดินออกจากเมืองราเมเสสไปถึงเมืองสุคคท นับแต่ผู้ชายได้ประมาณหกแสนคน เด็กต่างหาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 38, 'มีฝูงชนชาติอื่นเป็นจํานวนมากติดตามไปด้วยพร้อมทั้งฝูงสัตว์ คือฝูงแพะแกะ และวัวจํานวนมากมาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 39, 'เขาเอาก้อนแป้งไร้เชื้อซึ่งนํามาจากอียิปต์นั้น ปิ้งเป็นขนมไร้เชื้อ เพราะเขาถูกเร่งรัดให้ออกจากอียิปต์ จึงไม่ทันเตรียมเสบียง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 40, 'ชนชาติอิสราเอลอยู่ในอียิปต์เป็นเวลาสี่ร้อยสามสิบปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 41, 'ครั้นสิ้นสี่ร้อยสามสิบปีแล้ว ในวันนั้นเองพลโยธาทั้งหมดของพระเยโฮวาห์ก็ยกออกจากประเทศอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 42, 'คืนวันนั้นเป็นคืนที่ควรจดจําไว้เป็นที่ระลึกอย่างยิ่งถึงพระเยโฮวาห์ ด้วยทรงนําเขาออกจากประเทศอียิปต์ คืนวันนั้นจึงเป็นคืนของพระเยโฮวาห์ที่ชนชาติอิสราเอลทั้งปวงถือเป็นที่ระลึกตลอดชั่วอายุของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 43, 'พระเยโฮวาห์ตรัสกับโมเสสและอาโรนว่า “ระเบียบพิธีปัสกาเป็นดังนี้ คืออย่าให้คนต่างชาติกินเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 44, 'ส่วนทาสซึ่งนายเอาเงินซื้อมา เมื่อให้ทาสนั้นเข้าสุหนัตแล้วจึงให้เขากินได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 45, 'ส่วนแขกหรือลูกจ้างอย่าให้กินเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 46, 'ให้กินปัสกาแต่ในบ้าน อย่าเอาเนื้อไปนอกบ้าน และอย่าหักกระดูกของมันเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 47, 'ให้ชุมนุมคนอิสราเอลทั้งปวงถือและปฏิบัติตามพิธีนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 48, 'เมื่อมีคนต่างด้าวมาอาศัยอยู่กับเจ้า และใคร่จะถือปัสกาถวายพระเยโฮวาห์ ก็ให้ชายพวกนั้นเข้าสุหนัตเสียก่อนทุกคนแล้วจึงให้เขามาใกล้ และถือพิธีนั้นได้ เขาจึงจะเป็นเหมือนคนเกิดในแผ่นดินนั้น แต่ผู้ใดที่ยังมิได้เข้าสุหนัต อย่าให้เข้าร่วมกินเลี้ยงในพิธีปัสกานั้นเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 49, 'พระราชบัญญัติสําหรับคนเกิดในเมืองและคนต่างด้าวซึ่งอาศัยอยู่ด้วยกันกับเจ้าทั้งหลายจะต้องเป็นอันเดียวกัน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 50, 'คนอิสราเอลทั้งปวงก็ปฏิบัติตามทุกประการ พระเยโฮวาห์รับสั่งแก่โมเสสและอาโรนอย่างไร พวกเขาก็กระทําอย่างนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 51, 'วันนั้นแหละพระเยโฮวาห์ทรงนําชนชาติอิสราเอลออกจากประเทศอียิปต์ แยกเป็นกระบวนพลโยธา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 1, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 2, '“จงถวายลูกหัวปีทั้งปวงแก่เรา คือทุกสิ่งของชนชาติอิสราเอลที่ออกจากครรภ์ครั้งแรก จะเป็นมนุษย์หรือสัตว์ สิ่งนั้นเป็นของของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 3, 'โมเสสจึงกล่าวแก่ประชาชนว่า “จงระลึกถึงวันนี้ที่ท่านทั้งหลายออกมาจากอียิปต์ จากเรือนทาส เพราะพระเยโฮวาห์ทรงนําท่านทั้งหลายออกจากที่นั่นด้วยฤทธิ์พระหัตถ์ อย่ากินขนมปังที่มีเชื้อเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 4, 'ท่านทั้งหลายยกออกไปในวันนี้ในเดือนอาบีบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 5, 'ครั้นพระเยโฮวาห์ทรงนําพวกท่านมาถึงแผ่นดินของคนคานาอัน คนฮิตไทต์ คนอาโมไรต์ คนฮีไวต์ และคนเยบุส ที่พระองค์ทรงปฏิญาณไว้กับบรรพบุรุษของท่านว่า จะยกแผ่นดินนี้ให้พวกท่าน เป็นแผ่นดินที่มีน้ํานมและน้ําผึ้งไหลบริบูรณ์ ท่านทั้งหลายจงถือพิธีนี้ในเดือนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 6, 'จงกินขนมปังไร้เชื้อเป็นเวลาเจ็ดวัน และวันที่เจ็ดจงมีเทศกาลเลี้ยงถวายพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 7, 'จงกินขนมปังไร้เชื้อให้ครบกําหนดเจ็ดวัน อย่าให้เห็นขนมปังซึ่งมีเชื้อ หรือให้เห็นเชื้อขนมปังในเขตของพวกท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 8, 'ในวันนั้นจงบอกบุตรของท่านว่า ‘ที่ได้ทําดังนี้ก็เพราะเหตุการณ์ซึ่งพระเยโฮวาห์ได้ทรงกระทําสําหรับเรา ขณะเมื่อเราออกจากอียิปต์’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 9, 'สําหรับท่านพิธีนี้จะเป็นดังรอยสําคัญที่มือของท่าน และดังเครื่องระลึกระหว่างนัยน์ตาของท่าน เพื่อพระราชบัญญัติของพระเยโฮวาห์จะได้อยู่ในปากของท่าน เพราะพระเยโฮวาห์ได้ทรงนําพวกท่านออกมาจากอียิปต์ด้วยพระหัตถ์อันทรงฤทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 10, 'เพราะฉะนั้น พวกท่านจงปฏิบัติตามกฎพิธีนี้ตามกําหนดทุกๆปีไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 11, 'เมื่อพระเยโฮวาห์ทรงนําท่านไปยังแผ่นดินของคนคานาอัน ดังที่พระองค์ได้ทรงปฏิญาณไว้กับท่านและบรรพบุรุษของท่านว่า จะทรงยกแผ่นดินนั้นให้แก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 12, 'ทุกอย่างที่เบิกครรภ์ครั้งแรกนั้น ท่านจงแยกถวายแด่พระเยโฮวาห์ และลูกสัตว์หัวปีตัวผู้ที่เกิดจากสัตว์ใช้งานของท่าน จงเป็นของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 13, 'จงเอาลูกแกะไถ่ลูกลาหัวปี ถ้าไม่ไถ่จงหักคอมันเสีย จงไถ่บุตรหัวปีทั้งหลายของมนุษย์ไว้ทั้งหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 14, 'ต่อไปภายหน้า เมื่อบุตรของท่านจะถามว่า ‘ทําไมจึงทําอย่างนี้’ จงเล่าให้เขาฟังว่า ‘พระเยโฮวาห์ทรงนําพวกเราออกจากอียิปต์ จากเรือนทาสด้วยฤทธิ์พระหัตถ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 15, 'ต่อมาครั้นพระทัยของฟาโรห์ดื้อไม่ยอมปล่อยให้พวกเราไป พระเยโฮวาห์จึงทรงประหารลูกหัวปีทั้งหลายในประเทศอียิปต์ ทั้งลูกหัวปีของมนุษย์และลูกหัวปีของสัตว์ด้วย เหตุฉะนี้ เราจึงถวายบรรดาสัตว์หัวปีตัวผู้ที่เบิกครรภ์ครั้งแรกแด่พระเยโฮวาห์ แต่บุตรหัวปีทั้งหลายของเรา เราก็ไถ่ไว้’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 16, 'พิธีนี้จะเป็นดังรอยสําคัญที่มือของท่าน และดังเครื่องหมายระหว่างนัยน์ตาของท่าน เพราะพระเยโฮวาห์ได้ทรงนําพวกเราออกจากอียิปต์ด้วยฤทธิ์พระหัตถ์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 17, 'ต่อมาเมื่อฟาโรห์ปล่อยพลไพร่ไปแล้ว พระเจ้ามิได้ทรงนําเขาไปทางแผ่นดินของชาวฟีลิสเตีย แม้ว่าจะเป็นทางใกล้ เพราะพระเจ้าตรัสว่า “เกรงว่าเมื่อพลไพร่ไปเผชิญสงครามเข้า เขาจะเปลี่ยนใจและกลับไปยังอียิปต์เสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 18, 'พระเจ้าจึงทรงนําเขาอ้อมไปทางถิ่นทุรกันดารยังทะเลแดง ชนชาติอิสราเอลก็ออกไปจากแผ่นดินอียิปต์มีอาวุธพร้อมที่จะทําสงคราม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 19, 'โมเสสเอากระดูกของโยเซฟไปด้วย เพราะโยเซฟให้ชนชาติอิสราเอลปฏิญาณไว้ว่า “พระเจ้าจะเสด็จมาเยี่ยมท่านทั้งหลายเป็นแน่ แล้วท่านจงเอากระดูกของเราไปจากที่นี่ด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 20, 'คนอิสราเอลยกออกจากเมืองสุคคท ไปตั้งค่ายที่ตําบลเอธามบริเวณชายถิ่นทุรกันดาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 21, 'พระเยโฮวาห์เสด็จนําทางพวกเขาในเวลากลางวันด้วยเสาเมฆ และตอนกลางคืนด้วยเสาเพลิง ให้เขามีแสงสว่างเพื่อจะได้เดินทางได้ทั้งกลางวันและกลางคืน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 22, 'เสาเมฆในเวลากลางวันและเสาเพลิงในเวลากลางคืน พระองค์มิได้ให้คลาดจากเบื้องหน้าพลไพร่เลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 1, 'พระเยโฮวาห์รับสั่งแก่โมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 2, '“จงสั่งชนชาติอิสราเอลให้ย้อนกลับไปยังค่ายหน้าตําบลปีหะหิโรท ระหว่างมิกดลและทะเล หน้าตําบลบาอัลเซโฟน แล้วตั้งค่ายตรงนั้นใกล้ทะเล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 3, 'ฟาโรห์จะกล่าวถึงชนชาติอิสราเอลว่า ‘พวกเขาติดอยู่บนบก ถิ่นทุรกันดารนั้นกั้นเขาไว้แล้ว’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 4, 'เราจะบันดาลให้ใจฟาโรห์แข็งกระด้างไป ฟาโรห์จะไล่ตามมา แล้วเราจะได้รับเกียรติยศเพราะฟาโรห์และบรรดาพลโยธาของเขา แล้วชาวอียิปต์จะรู้ว่าเราคือพระเยโฮวาห์” เขาทั้งหลายก็กระทําตามรับสั่งนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 5, 'เมื่อกษัตริย์อียิปต์ทราบความว่าบ่าวไพร่เหล่านั้นหนีไปแล้ว พระดําริของฟาโรห์และความคิดของข้าราชการก็เปลี่ยนไปจากที่มีต่อบ่าวไพร่นั้น เขาจึงว่า “ทําไมเราจึงทําเช่นนี้ ไฉนเราจึงได้ปล่อยพวกอิสราเอลไปให้พ้นจากการรับใช้เราเล่า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 6, 'ฝ่ายฟาโรห์ก็จัดราชรถ และนําพลโยธาไปด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 7, 'ท่านเอารถรบอย่างดีหกร้อยคัน กับรถรบทั้งหมดในอียิปต์ มีทหารประจําอยู่ทุกคัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 8, 'พระเยโฮวาห์ทรงให้พระทัยของฟาโรห์กษัตริย์แห่งอียิปต์แข็งกระด้างไป ท่านจึงไล่ตามชนชาติอิสราเอล และชนชาติอิสราเอลนั้นเดินทางไปโดยมีพระหัตถ์ของพระเจ้าคุ้มครองอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 9, 'ชาวอียิปต์ไล่ตามไปมีทั้งม้าและรถรบทั้งหมดของฟาโรห์และทหารม้า กองทัพของท่านมาทันชนชาติอิสราเอลที่ตั้งค่ายอยู่ริมทะเล ใกล้ตําบลปีหะหิโรท หน้าตําบลบาอัลเซโฟน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 10, 'เมื่อฟาโรห์เข้ามาใกล้ ชนชาติอิสราเอลก็เงยหน้าขึ้นดู และดูเถิด ชาวอียิปต์ยกติดตามมา เขาก็มีความกลัวยิ่งนัก คนอิสราเอลจึงร้องทูลพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 11, 'เขาบอกโมเสสว่า “หลุมฝังศพในอียิปต์ไม่มีหรือ ท่านจึงพาเราออกมาให้ตายในถิ่นทุรกันดาร ทําไมหนอท่านจึงทําเช่นนี้คือพาเราออกมาจากอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 12, 'พวกเราบอกท่านในอียิปต์แล้วมิใช่หรือว่า ‘ปล่อยพวกเราแต่ลําพัง ให้พวกเรารับใช้ชาวอียิปต์เถิด’ เพราะการรับใช้ชาวอียิปต์นั้น ก็ยังดีกว่าที่จะมาตายในถิ่นทุรกันดาร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 13, 'โมเสสจึงเตือนพลไพร่ว่า “อย่ากลัวเลย มั่นคงไว้ คอยดูความรอดที่จะมาจากพระเยโฮวาห์ ซึ่งพระองค์จะประทานให้แก่ท่านทั้งหลายในวันนี้ ด้วยคนอียิปต์ซึ่งท่านทั้งหลายเห็นในวันนี้ แต่นี้ไปจะไม่ได้เห็นอีกเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 14, 'พระเยโฮวาห์จะทรงรบแทนท่านทั้งหลาย ท่านทั้งหลายจงสงบอยู่เถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 15, 'พระเยโฮวาห์ตรัสกับโมเสสว่า “เหตุไฉนเจ้าจึงมาร้องทุกข์ต่อเรา จงสั่งชนชาติอิสราเอลให้เดินต่อไปข้างหน้าเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 16, 'ฝ่ายเจ้าจงยกไม้เท้าของเจ้า แล้วยื่นมือของเจ้าออกไปเหนือทะเล ทําให้ทะเลนั้นแยกออก เพื่อคนอิสราเอลจะได้เดินบนดินแห้งกลางทะเลแล้วข้ามไปได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 17, 'ดูเถิด ส่วนเราก็จะบันดาลให้ใจชาวอียิปต์แข็งกระด้างไล่ตามมา แล้วเราจะได้รับเกียรติเพราะฟาโรห์ พลโยธา รถรบ และพลม้าทั้งหมดของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 18, 'เมื่อเราได้รับเกียรติเพราะฟาโรห์ รถรบและพลม้าของเขาแล้ว ชาวอียิปต์ก็จะรู้ว่าเรานี่แหละคือพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 19, 'ฝ่ายทูตสวรรค์ของพระเจ้าซึ่งนําพลโยธาอิสราเอลนั้นกลับไปอยู่ข้างหลัง และเสาเมฆซึ่งอยู่ข้างหน้า ก็กลับมาตั้งอยู่ข้างหลังเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 20, 'คือเสานั้นมาอยู่ระหว่างค่ายของชาติอียิปต์และค่ายของชนชาติอิสราเอล และเป็นเมฆมืดแก่ชาวอียิปต์ แต่มีแสงส่องสว่างในเวลากลางคืนแก่ชนชาติอิสราเอล ทั้งสองฝ่ายมิได้เข้าใกล้กันตลอดคืน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 21, 'โมเสสยื่นมือของท่านออกไปเหนือทะเล และพระเยโฮวาห์ก็ทรงบันดาลให้ลมทิศตะวันออกพัดโหมไล่น้ําทะเลตลอดคืน ทําให้ทะเลกลายเป็นดินแห้ง น้ําแยกออกจากกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 22, 'ชนชาติอิสราเอลก็พากันเดินบนดินแห้งกลางทะเล ส่วนน้ํานั้นตั้งเป็นเหมือนกําแพงสําหรับเขา ทั้งทางขวาและทางซ้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 23, 'คนอียิปต์ก็ไล่ตามเขาเข้าไปกลางทะเล ทั้งกองม้าและราชรถ และพลม้าทั้งปวงของฟาโรห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 24, 'ครั้นในเวลาย่ํารุ่ง พระเยโฮวาห์ทอดพระเนตรจากเสาเพลิงและเสาเมฆทรงเห็นพลโยธาอียิปต์ ก็ทรงบันดาลให้กองทัพอียิปต์เกิดโกลาหล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 25, 'พระองค์ทรงกระทําให้ล้อรถฝืดจนแล่นไปแทบไม่ไหว คนอียิปต์จึงพูดกันว่า “ให้เราหนีไปจากหน้าคนอิสราเอลเถิด เพราะพระเยโฮวาห์ทรงต่อสู้กับคนอียิปต์แทนเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 26, 'ขณะนั้นพระเยโฮวาห์ตรัสกับโมเสสว่า “จงยื่นมือออกไปเหนือทะเล เพื่อให้น้ําทะเลไหลกลับคืนมาท่วมคนอียิปต์ ทั้งรถรบและพลม้าของเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 27, 'โมเสสจึงยื่นมือออกไปเหนือทะเล ครั้นรุ่งเช้าทะเลก็กลับไหลดังเก่า คนอียิปต์พากันหนีกระแสน้ํา แต่พระเยโฮวาห์ทรงสลัดคนอียิปต์ลงกลางทะเล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 28, 'น้ําก็กลับท่วมพลรถและพลม้า คือพลโยธาทั้งหมดของฟาโรห์ซึ่งไล่ตามเขาเข้าไปในทะเล ไม่เหลือสักคนเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 29, 'ฝ่ายชนชาติอิสราเอลเดินไปตามดินแห้งกลางท้องทะเล น้ําตั้งขึ้นเหมือนกําแพงสําหรับเขาทั้งทางขวาและทางซ้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 30, 'ดังนี้ในวันนั้นพระเยโฮวาห์ทรงโปรดช่วยให้คนอิสราเอลรอดจากเงื้อมมือคนอียิปต์ อิสราเอลเห็นศพคนอียิปต์อยู่ที่ชายทะเล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 31, 'อิสราเอลเห็นกิจการใหญ่ ซึ่งพระเยโฮวาห์ได้ทรงกระทําแก่คนอียิปต์ พลไพร่นั้นก็เกรงกลัวพระเยโฮวาห์ เขาทั้งหลายเชื่อถือพระเยโฮวาห์และเชื่อโมเสสผู้รับใช้ของพระองค์ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 1, 'ขณะนั้นโมเสสกับชนชาติอิสราเอลร้องเพลงบทนี้ ถวายพระเยโฮวาห์ว่า “ข้าพเจ้าจะร้องเพลงถวายพระเยโฮวาห์ เพราะพระองค์ทรงได้ชัยชนะอย่างใหญ่หลวง พระองค์ทรงกวาดม้าและพลม้าลงในทะเล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 2, 'พระเยโฮวาห์ทรงเป็นกําลังและเป็นบทเพลงแห่งข้าพเจ้า พระองค์ทรงเป็นผู้ช่วยให้ข้าพเจ้ารอด พระองค์นี่แหละเป็นพระเจ้าของข้าพเจ้า ข้าพเจ้าจะสรรเสริญพระองค์ ทรงเป็นพระเจ้าของบรรพบุรุษของข้าพเจ้า ข้าพเจ้าจะยกย่องสรรเสริญพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 3, 'พระเยโฮวาห์ทรงเป็นนักรบ พระนามของพระองค์คือ พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 4, 'พระองค์ทรงเหวี่ยงรถรบ และโยนพลโยธาของฟาโรห์ลงในทะเล นายทหารรถรบชั้นยอดของฟาโรห์ก็จมในทะเลแดง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 5, 'น้ําท่วมเขา เขาจมลงในทะเลที่ลึกประดุจก้อนหิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 6, 'โอ ข้าแต่พระเยโฮวาห์ พระหัตถ์ขวาของพระองค์ทรงอานุภาพยิ่ง โอ ข้าแต่พระเยโฮวาห์ พระหัตถ์ขวาของพระองค์ฟาดศัตรูแหลกเป็นชิ้นๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 7, 'ด้วยเดชานุภาพอันยิ่งใหญ่ของพระองค์ พระองค์ทรงคว่ําปฏิปักษ์ของพระองค์เสีย พระองค์ทรงใช้พระพิโรธของพระองค์เผาผลาญเขาเสียอย่างตอฟาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 8, 'โดยลมที่ระบายจากช่องพระนาสิกน้ําก็ท่วมสูงขึ้นไป น้ําก็ท่วมท้นสูงขึ้น น้ําก็แข็งขึ้นในท้องทะเล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 9, 'พวกข้าศึกกล่าวว่า ‘เราจะติดตาม เราจะจับให้ทัน เราจะริบสิ่งของมาแบ่งปันกัน เราจึงจะพอใจที่ได้กระทํากับพวกนั้นดังประสงค์ เราจะชักดาบออก มือเราจะทําลายเขาเสีย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 10, 'พระองค์ทรงบันดาลให้ลมพัดมา น้ําทะเลก็ท่วมเขามิด เขาจมลงในกระแสน้ําอันไหลแรงนั้นเหมือนตะกั่ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 11, 'โอ ข้าแต่พระเยโฮวาห์ ในบรรดาพระทั้งปวงองค์ไหนจะเป็นเหมือนพระองค์เล่า องค์ไหนจะเหมือนพระองค์ผู้ทรงประกอบด้วยความบริสุทธิ์อันรุ่งเรือง และน่าเกรงขามเนื่องด้วยการสรรเสริญ และการมหัศจรรย์ที่พระองค์ทรงกระทํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 12, 'พระองค์ทรงเหยียดพระหัตถ์ขวาออก แผ่นดินก็กลืนพวกเขาเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 13, 'พระองค์ทรงนําชนชาติ ซึ่งพระองค์ทรงไถ่ไว้ด้วยพระเมตตาของพระองค์ พระองค์ทรงพาเขามาถึงที่สถิตอันบริสุทธิ์ของพระองค์ ด้วยพระเดชานุภาพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 14, 'ชนชาติทั้งหลายจะได้ยิน แล้วจะพากันหวาดกลัว ชาวประเทศฟีลิสเตียจะรู้สึกเสียวสยอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 15, 'ครั้งนั้นพวกเจ้านายในเมืองเอโดมก็จะพากันหวาดกลัว และพวกหัวหน้าในเมืองโมอับก็จะสะทกสะท้าน ชาวเมืองคานาอันทั้งปวงก็จะระส่ําระสายไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 16, 'ความรู้สึกเสียวสยอง และความตกใจกลัวจะอุบัติขึ้นในใจของเขา เนื่องด้วยฤทธานุภาพแห่งพระกรของพระองค์ เขาจะหยุดนิ่งอยู่เหมือนก้อนหิน โอ ข้าแต่พระเยโฮวาห์ จนพลไพร่ของพระองค์ผ่านพ้นไป จนชนชาติซึ่งพระองค์ทรงไถ่ไว้แล้วผ่านไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 17, 'พระองค์จะทรงนําเขาเข้ามา และทรงตั้งเขาไว้บนภูเขาซึ่งเป็นมรดกของพระองค์ โอ ข้าแต่พระเยโฮวาห์ เป็นสถานที่ซึ่งพระองค์ทรงสร้างไว้ เพื่อเป็นที่สถิตของพระองค์ โอ ข้าแต่องค์พระผู้เป็นเจ้า สถานบริสุทธิ์ซึ่งพระหัตถ์ของพระองค์สถาปนาไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 18, 'พระเยโฮวาห์จะทรงครอบครองอยู่เป็นนิตย์นิรันดร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 19, 'เพราะเมื่อกองม้าของฟาโรห์กับราชรถ และพลม้าของท่านลงไปในทะเล พระเยโฮวาห์ก็ทรงให้น้ําทะเลไหลกลับมาท่วมเสีย แต่ชนชาติอิสราเอลเดินไปบนดินแห้งกลางทะเลนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 20, 'ฝ่ายมิเรียมหญิงผู้พยากรณ์ พี่สาวของอาโรนก็ถือรํามะนา และหญิงทั้งปวงก็ถือรํามะนาเดินตาม พร้อมเต้นรําไปด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 21, 'มิเรียมจึงร้องนําว่า “จงร้องเพลงถวายพระเยโฮวาห์เถิด เพราะพระองค์ทรงได้ชัยชนะอย่างใหญ่หลวง พระองค์ทรงกวาดม้าและพลม้าให้ตกลงไปในทะเล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 22, 'ต่อมาโมเสสนําพวกอิสราเอลออกจากทะเลแดงไปยังถิ่นทุรกันดารชูร์ เดินไปในถิ่นทุรกันดารสามวัน ก็มิได้พบน้ําเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 23, 'ครั้นมาถึงตําบลมาราห์ เขาก็กินน้ําที่ตําบลมาราห์นั้นไม่ได้ เพราะน้ําขม เหตุฉะนั้นจึงตั้งชื่อว่ามาราห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 24, 'และพลไพร่นั้นก็พากันบ่นต่อว่าโมเสสว่า “พวกเราจะเอาอะไรดื่ม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 25, 'โมเสสก็ร้องทูลพระเยโฮวาห์ พระเยโฮวาห์จึงทรงชี้ให้ท่านเห็นต้นไม้ต้นหนึ่ง เมื่อโยนต้นไม้นั้นลงในน้ํา น้ําก็จืด ณ ที่นั้นพระองค์ทรงประทานกฎเกณฑ์ และกฎไว้ และทรงลองใจเขาที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 26, 'พระองค์ตรัสว่า “ถ้าเจ้าทั้งหลายฟังพระสุรเสียงของพระเยโฮวาห์พระเจ้าของเจ้าอย่างขะมักเขม้น และกระทําสิ่งที่ถูกต้องในสายพระเนตรของพระองค์ เงี่ยหูฟังพระบัญญัติของพระองค์ และรักษากฎเกณฑ์ของพระองค์ทุกประการ แล้วโรคต่างๆซึ่งเราบันดาลให้เกิดแก่ชาวอียิปต์นั้น เราจะไม่ให้บังเกิดแก่พวกเจ้าเลย เพราะเราคือพระเยโฮวาห์เป็นผู้รักษาเจ้าให้หาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 27, 'พวกเขามาถึงตําบลเอลิม ที่มีบ่อน้ําพุสิบสองบ่อ มีต้นอินทผลัมเจ็ดสิบต้น พวกเขาจึงตั้งค่ายใกล้บ่อน้ํานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 1, 'พวกเขายกไปจากเอลิม และในวันที่สิบห้าเดือนที่สอง นับตั้งแต่เวลายกออกจากแผ่นดินอียิปต์ ชุมนุมชนชาติอิสราเอลทั้งหมดก็มาถึงถิ่นทุรกันดารสีน ซึ่งอยู่ระหว่างตําบลเอลิมกับภูเขาซีนาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 2, 'ชุมนุมชนชาติอิสราเอลทั้งปวงก็พากันบ่นต่อโมเสสและอาโรนในถิ่นทุรกันดาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 3, 'คนอิสราเอลกล่าวแก่ท่านทั้งสองว่า “พวกข้าพเจ้าตายเสียด้วยพระหัตถ์ของพระเยโฮวาห์ตั้งแต่อยู่ในประเทศอียิปต์ ขณะเมื่อนั่งอยู่ใกล้หม้อเนื้อและรับประทานอาหารอิ่มหนําจะดีกว่า นี่ท่านกลับนําพวกข้าพเจ้าออกมาในถิ่นทุรกันดารอย่างนี้ เพื่อจะให้ชุมนุมชนทั้งหมดหิวตายเท่านั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 4, 'แล้วพระเยโฮวาห์ได้ตรัสกับโมเสสว่า “ดูเถิด เราจะให้อาหารตกลงมาจากท้องฟ้าดุจฝนสําหรับพวกเจ้า ให้พลไพร่ออกไปเก็บทุกวันพอกินเฉพาะวันหนึ่งๆ เพื่อเราจะได้ลองใจว่าเขาจะดําเนินตามราชบัญญัติของเราหรือไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 5, 'ต่อมาในวันที่หก เมื่อเขาเตรียมของที่เก็บมา อาหารนั้นก็จะเพิ่มเป็นสองเท่าของที่เขาเก็บทุกวัน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 6, 'โมเสสกับอาโรนจึงบอกชนชาติอิสราเอลทั้งปวงว่า “ในเวลาเย็นท่านทั้งหลายจะได้รู้ว่าพระเยโฮวาห์เป็นผู้ทรงนําพวกท่านออกจากประเทศอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 7, 'ในเวลาเช้าพวกท่านจะได้เห็นสง่าราศีแห่งพระเยโฮวาห์ เพราะคําบ่นต่อว่าของพวกท่านต่อพระเยโฮวาห์ พระองค์ทรงสดับแล้ว เราทั้งสองเป็นผู้ใดเล่า พวกท่านจึงมาบ่นต่อว่าเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 8, 'โมเสสกล่าวว่า “ในเวลาเย็นพระเยโฮวาห์จะประทานเนื้อให้ท่านรับประทานและในเวลาเช้าพวกท่านจะมีอาหารรับประทานจนอิ่ม เพราะพระเยโฮวาห์ทรงสดับคําบ่นของท่านต่อพระองค์ เราทั้งสองนี้เป็นผู้ใดเล่า พวกท่านมิได้บ่นต่อว่าเรา แต่ได้บ่นต่อว่าพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 9, 'โมเสสจึงกล่าวแก่อาโรนว่า “จงบอกชุมนุมชนชาติอิสราเอลทั้งปวงว่า ‘เข้ามาใกล้พระพักตร์พระเยโฮวาห์ เพราะพระองค์ทรงสดับคําบ่นของท่านแล้ว’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 10, 'ต่อมาขณะที่อาโรนกล่าวแก่บรรดาชุมนุมชนอิสราเอลอยู่นั้น เขาทั้งหลายมองไปทางถิ่นทุรกันดาร แล้วดูเถิด สง่าราศีของพระเยโฮวาห์ปรากฏอยู่ในเมฆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 11, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 12, '“เราได้ยินคําบ่นของชนชาติอิสราเอลแล้ว จงกล่าวแก่เขาว่า ‘ในเวลาเย็น พวกเจ้าจะได้กินเนื้อ ทั้งในเวลาเช้า เจ้าจะได้อาหารกินจนอิ่ม แล้วเจ้าจะรู้ว่า เราคือพระเยโฮวาห์พระเจ้าของพวกเจ้า’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 13, 'ครั้นถึงเวลาเย็นฝูงนกคุ่มบินมาเต็มค่าย ในเวลาเช้าก็มีน้ําค้างตกรอบค่ายที่พัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 14, 'เมื่อน้ําค้างระเหยไปแล้ว ดูเถิด สิ่งหนึ่งเหมือนเกล็ดเล็กๆเท่าเม็ดน้ําค้างแข็งอยู่ที่พื้นดินในถิ่นทุรกันดารนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 15, 'เมื่อชนชาติอิสราเอลเห็นจึงพูดกันว่า “นี่คือมานา” เพราะเขาไม่ทราบว่าเป็นสิ่งใด โมเสสจึงบอกเขาว่า “นี่แหละเป็นอาหารที่พระเยโฮวาห์ประทานให้พวกท่านรับประทาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 16, 'นี่เป็นสิ่งที่พระเยโฮวาห์ทรงบัญชาไว้ว่า ‘ให้ทุกคนเก็บเท่าที่พอรับประทานอิ่ม ให้เก็บคนละโอเมอร์ ตามจํานวนคนมากน้อย ซึ่งพักอยู่ในเต็นท์ของตน’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 17, 'ชนชาติอิสราเอลก็กระทําตาม บางคนเก็บมาก บางคนเก็บน้อย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 18, 'แต่เมื่อเขาใช้โอเมอร์ตวงคนที่เก็บได้มากก็ไม่มีเหลือ และคนที่เก็บได้น้อยก็หาขาดไม่ ทุกคนเก็บได้เท่าที่คนหนึ่งรับประทานพอดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 19, 'โมเสสจึงสั่งว่า “อย่าให้ผู้ใดเก็บเหลือไว้จนรุ่งเช้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 20, 'แต่เขามิได้เชื่อฟังโมเสส บางคนเก็บส่วนหนึ่งไว้จนรุ่งเช้า อาหารนั้นก็เน่าเป็นหนอนและบูดเหม็น โมเสสจึงโกรธคนเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 21, 'เขาเก็บกันทุกๆเช้าเท่าที่คนหนึ่งรับประทานพอดี แต่พอแดดออกร้อนจัดแล้วอาหารนั้นก็ละลายไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 22, 'อยู่มาเมื่อถึงวันที่หก เขาเก็บอาหารสองเท่า คือคนละสองโอเมอร์ บรรดาหัวหน้าของชุมนุมชนจึงมารายงานต่อโมเสส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 23, 'โมเสสบอกเขาว่า “พระเยโฮวาห์ทรงพระบัญชาว่า ‘พรุ่งนี้เป็นวันหยุดงาน เป็นสะบาโต วันบริสุทธิ์ของพระเยโฮวาห์ วันนี้จะปิ้งอะไรก็ให้ปิ้ง จะต้มอะไรก็ต้มเสีย และส่วนที่เหลือทั้งหมดจงเก็บไว้จนถึงวันรุ่งขึ้น’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 24, 'เมื่อเขาเก็บไว้จนถึงวันรุ่งขึ้นตามโมเสสสั่ง อาหารนั้นก็มิได้บูดเหม็นเป็นหนอนเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 25, 'โมเสสจึงบอกว่า “วันนี้จงกินอาหารนั้น เพราะว่าวันนี้เป็นวันสะบาโตของพระเยโฮวาห์ วันนี้ท่านจะไม่พบอาหารอย่างนั้นในทุ่งเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 26, 'จงเก็บหกวัน แต่ในวันที่เจ็ดซึ่งเป็นสะบาโตจะไม่มีเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 27, 'อยู่มาเมื่อวันที่เจ็ดมีบางคนออกไปเก็บ แต่ไม่ได้พบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 28, 'พระเยโฮวาห์ตรัสกับโมเสสว่า “พวกเจ้าจะขัดขืนบัญญัติและราชบัญญัติของเรานานสักเท่าไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 29, 'ดูซิ พระเยโฮวาห์ทรงกําหนดวันสะบาโตให้เจ้า คือในวันที่หก พระองค์จึงประทานอาหารให้พอรับประทานสองวัน ให้ทุกคนพักอยู่ในที่ของตน อย่าให้ผู้ใดออกจากที่พักในวันที่เจ็ดนั้นเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 30, 'เหตุฉะนั้นพลไพร่ทั้งปวงจึงได้พักงานในวันที่เจ็ด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 31, 'เหล่าวงศ์วานของอิสราเอลเรียกชื่ออาหารนั้นว่า มานา เป็นเม็ดขาวเหมือนเมล็ดผักชี มีรสเหมือนขนมแผ่นประสมน้ําผึ้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 32, 'โมเสสกล่าวว่า “พระเยโฮวาห์มีรับสั่งว่า ‘จงตวงมานาโอเมอร์หนึ่ง เก็บไว้ตลอดชั่วอายุของเจ้า เพื่อเขาทั้งหลายจะได้เห็นอาหารซึ่งเราเลี้ยงเจ้าในถิ่นทุรกันดารนี้ เมื่อเรานําพวกเจ้าออกจากแผ่นดินอียิปต์’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 33, 'โมเสสบอกอาโรนว่า “เอาหม้อลูกหนึ่ง ตวงมานาให้เต็มโอเมอร์หนึ่ง เก็บไว้ต่อพระพักตร์พระเยโฮวาห์ ตลอดชั่วอายุของท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 34, 'อาโรนก็วางมานานั้นลงหน้าหีบพระโอวาท เพื่อรักษาไว้ตามพระดํารัสที่พระเยโฮวาห์ทรงบัญชาแก่โมเสส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 35, 'ชนชาติอิสราเอลได้กินมานาสี่สิบปีจนเขามาถึงเมืองที่จะอาศัยอยู่ พวกเขากินมานาจนมาถึงชายแดนแผ่นดินคานาอัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 36, 'หนึ่งโอเมอร์เท่ากับหนึ่งในสิบของเอฟาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 1, 'ชุมนุมชนชาติอิสราเอลทั้งหมด ยกออกจากถิ่นทุรกันดารสีน ไปเป็นระยะๆตามพระบัญชาของพระเยโฮวาห์และมาตั้งค่ายที่เรฟีดิม ที่นั่นไม่มีน้ําให้พลไพร่ดื่ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 2, 'เหตุฉะนั้นพลไพร่จึงกล่าวหาโมเสสว่า “ให้น้ําพวกข้าดื่มซิ” โมเสสจึงบอกเขาว่า “พวกเจ้าหาเรื่องเราทําไม เหตุไฉนพวกเจ้าจึงบังอาจลองดีกับพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 3, 'พลไพร่กระหายน้ําที่ตําบลนั้น จึงบ่นต่อโมเสสว่า “ทําไมท่านจึงพาพวกข้า ทั้งบุตรและฝูงสัตว์ของข้า ออกมาจากประเทศอียิปต์ให้อดน้ําตาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 4, 'โมเสสจึงร้องทูลพระเยโฮวาห์ว่า “ข้าพระองค์จะทําอย่างไรกับชนชาตินี้ดี เขาเกือบจะเอาหินขว้างข้าพระองค์ให้ตายอยู่แล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 5, 'พระเยโฮวาห์จึงตรัสกับโมเสสว่า “จงเดินล่วงหน้าพลไพร่ไปและนําพวกผู้ใหญ่บางคนของอิสราเอลไปด้วย ให้ถือไม้เท้าที่เจ้าใช้ตีแม่น้ํานั้นไปด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 6, 'ดูเถิด เราจะยืนอยู่ต่อหน้าเจ้าที่นั่นบนศิลาที่ภูเขาโฮเรบ เจ้าจงตีศิลานั้น แล้วน้ําจะไหลออกมาจากศิลาให้พลไพร่ดื่ม” โมเสสก็ทําดังนั้นท่ามกลางสายตาพวกผู้ใหญ่ของอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 7, 'โมเสสเรียกชื่อตําบลนั้นว่า มัสสาห์ และเมรีบาห์ ด้วยเหตุว่า คนอิสราเอลกล่าวหาตน ณ ที่นั้น และลองดีกับพระเยโฮวาห์ว่า “พระเยโฮวาห์ทรงสถิตอยู่ท่ามกลางพวกข้าพเจ้าจริงหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 8, 'ครั้งนั้น คนอามาเลขยกมารบกับคนอิสราเอลที่ตําบลเรฟีดิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 9, 'โมเสสสั่งโยชูวาว่า “จงเลือกชายฉกรรจ์ฝ่ายเราออกไปสู้รบกับพวกอามาเลข พรุ่งนี้เราจะยืนถือไม้เท้าของพระเจ้าอยู่บนยอดภูเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 10, 'โยชูวาก็ทําตามคําสั่งของโมเสส ออกสู้รบกับพวกอามาเลข ส่วนโมเสส อาโรน และเฮอร์ ก็ขึ้นไปบนยอดภูเขานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 11, 'ต่อมาโมเสสยกมือขึ้นเมื่อไร อิสราเอลก็ได้เปรียบเมื่อนั้น ท่านลดมือลงเมื่อไร พวกอามาเลขก็เป็นต่อเมื่อนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 12, 'แต่มือของโมเสสเมื่อยล้า เขาทั้งสองก็นําก้อนหินมาวางไว้ให้โมเสส ท่านนั่ง อาโรนกับเฮอร์ก็ช่วยยกมือท่านขึ้นคนละข้าง มือของท่านก็ชูอยู่จนตะวันตกดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 13, 'ฝ่ายโยชูวาปราบอามาเลขกับพลไพร่ของเขาพ่ายแพ้ไปด้วยคมดาบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 14, 'พระเยโฮวาห์ตรัสกับโมเสสว่า “จงเขียนข้อความต่อไปนี้ลงไว้ในหนังสือเพื่อเป็นที่ระลึก ทั้งเล่าให้โยชูวาฟังคือว่าเราจะลบล้างชื่อชนชาติอามาเลขไม่ให้ปรากฏในความทรงจําของพลไพร่ภายใต้ฟ้านี้เลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 15, 'โมเสสจึงสร้างแท่นเรียกชื่อว่า เยโฮวาห์นิสสี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 16, 'กล่าวว่า “เพราะพระเยโฮวาห์ได้ทรงปฏิญาณว่าพระเยโฮวาห์จะทรงกระทําสงครามกับอามาเลขต่อไปทุกชั่วอายุ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 1, 'เมื่อเยโธร ปุโรหิตแห่งมีเดียน พ่อตาของโมเสส ได้ยินถึงกิจการทั้งหลายที่พระเจ้าทรงกระทําเพื่อโมเสส และอิสราเอลพลไพร่ของพระองค์ว่า พระเยโฮวาห์ทรงนําอิสราเอลออกจากอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 2, 'เยโธรพ่อตาของโมเสสจึงพาศิปโปราห์ภรรยาของโมเสสซึ่งโมเสสได้ส่งกลับไปแต่คราวก่อนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 3, 'พร้อมกับบุตรชายทั้งสองคนของนาง คนหนึ่งชื่อเกอร์โชม เพราะโมเสสกล่าวว่า “ข้าพเจ้าเป็นคนต่างด้าวอาศัยอยู่ต่างประเทศ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 4, 'อีกคนหนึ่งชื่อเอลีเยเซอร์ เพราะท่านกล่าวว่า “พระเจ้าของบิดาข้าพเจ้าเป็นผู้อุปถัมภ์ของข้าพเจ้า และทรงให้ข้าพเจ้ารอดจากพระแสงดาบของฟาโรห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 5, 'เยโธรพ่อตาของโมเสส พาภรรยาและบุตรชายทั้งสองคนนั้นมาหาโมเสสที่ในถิ่นทุรกันดารที่เขาตั้งค่ายอยู่ที่ภูเขาของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 6, 'ท่านบอกโมเสสว่า “เราคือเยโธรพ่อตาของท่านพาภรรยากับบุตรชายทั้งสองของนางมาหาท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 7, 'โมเสสออกไปต้อนรับพ่อตากราบลงและจุบท่าน ท่านทั้งสองไต่ถามถึงทุกข์สุขซึ่งกันและกันแล้วพากันเข้าไปในเต็นท์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 8, 'โมเสสเล่าให้พ่อตาฟังถึงเหตุการณ์ทุกประการซึ่งพระเยโฮวาห์ทรงกระทํากับฟาโรห์ และแก่ชาวอียิปต์เพราะทรงเห็นแก่พวกอิสราเอล ทั้งความทุกข์ยากลําบากทั้งปวงซึ่งเกิดขึ้นแก่คนอิสราเอลในระหว่างทาง และพระเยโฮวาห์ได้ทรงช่วยเขาให้พ้นภัยอย่างไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 9, 'เยโธรก็มีความยินดีที่ได้ทราบพระกรุณาทั้งสิ้นซึ่งพระเยโฮวาห์ได้ทรงสําแดงแก่คนอิสราเอล เมื่อพระองค์ทรงช่วยเขาให้รอดพ้นจากเงื้อมมือชาวอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 10, 'เยโธรจึงกล่าวว่า “สาธุการแด่พระเยโฮวาห์ผู้ทรงช่วยท่านทั้งหลายให้รอดจากเงื้อมมือชาวอียิปต์ และจากหัตถ์ของฟาโรห์ และทรงช่วยพลไพร่ให้พ้นจากมือของชาวอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 11, 'บัดนี้เราทราบว่าพระเยโฮวาห์ทรงเป็นใหญ่กว่าพระทั้งปวง ใหญ่กว่าพระเหล่านั้นที่ได้กระทําต่อชนชาติอิสราเอลอย่างทะนง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 12, 'เยโธรพ่อตาของโมเสสก็นําเครื่องเผาบูชา และเครื่องสัตวบูชาถวายแด่พระเจ้า ฝ่ายอาโรนกับบรรดาผู้ใหญ่แห่งอิสราเอลมารับประทานเลี้ยงกับพ่อตาของโมเสสเฉพาะพระพักตร์พระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 13, 'ต่อมาวันรุ่งขึ้น โมเสสออกนั่งพิจารณาพิพากษาความให้พลไพร่ พลไพร่ก็ยืนห้อมล้อมโมเสสตั้งแต่เช้าจนเย็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 14, 'เมื่อพ่อตาของโมเสสเห็นงานทั้งปวงที่โมเสสกระทําเพื่อพลไพร่เช่นนั้น จึงกล่าวว่า “นี่ท่านใช้วิธีอะไรปฏิบัติกับพลไพร่เล่า เหตุไรท่านจึงนั่งทํางานอยู่แต่ผู้เดียว และพลไพร่ทั้งปวงก็ยืนล้อมท่านตั้งแต่เช้าจนเย็น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 15, 'โมเสสจึงตอบพ่อตาว่า “เพราะพลไพร่มาหาข้าพเจ้า เพื่อขอให้ทูลถามพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 16, 'เมื่อเขามีการโต้เถียงกันก็มาหาข้าพเจ้า ข้าพเจ้าก็ตัดสินความระหว่างเขากับเพื่อนบ้าน สอนเขาให้รู้จักกฎเกณฑ์ของพระเจ้าและพระราชบัญญัติของพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 17, 'ฝ่ายพ่อตาของโมเสสจึงกล่าวแก่ท่านว่า “ท่านทําอย่างนี้ไม่ดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 18, 'ทั้งท่านและพลไพร่ที่มาหาท่านนั้นจะอ่อนระอาใจ เพราะภาระอันหนักนี้เหลือกําลังของท่าน ท่านไม่สามารถที่จะทําแต่ผู้เดียวได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 19, 'ฟังเสียงของเราบ้าง เราจะให้คําแนะนําแก่ท่าน และขอให้พระเจ้าทรงสถิตอยู่กับท่าน ท่านจงเป็นผู้แทนของพลไพร่ต่อพระเจ้า นําความกราบทูลพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 20, 'ท่านจงสั่งสอนเขาให้รู้กฎและพระราชบัญญัติต่างๆ และแสดงให้เขารู้จักทางที่เขาต้องดําเนินชีวิตและสิ่งที่ต้องปฏิบัติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 21, 'ยิ่งกว่านั้น ท่านจงเลือกคนที่สามารถจากพวกพลไพร่ คือคนที่ยําเกรงพระเจ้า ไว้ใจได้และเกลียดสินบน แต่งตั้งคนอย่างนี้ไว้เป็นผู้ปกครองคน พันคนบ้าง ร้อยคนบ้าง ห้าสิบคนบ้าง สิบคนบ้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 22, 'ให้เขาพิพากษาความของพลไพร่อยู่เสมอ ส่วนคดีใหญ่ๆก็ให้เขานํามาแจ้งต่อท่าน แต่คดีเล็กๆน้อยๆให้เขาตัดสินเอง การงานของท่านจะเบาลง และพวกเขาจะแบกภาระร่วมกับท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 23, 'ถ้าทําดังนี้และพระเจ้าทรงบัญชาแล้ว ท่านก็จะสามารถทนได้ พลไพร่ทั้งปวงนี้ก็จะไปยังที่อาศัยของเขาด้วยความสงบสุข”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 24, 'โมเสสก็ฟังเสียงของพ่อตา และทําตามที่เขาแนะนําทุกประการ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 25, 'โมเสสจึงได้เลือกคนที่สามารถจากคนอิสราเอลทั้งปวงตั้งให้เป็นหัวหน้าพลไพร่ เป็นผู้ปกครองคนพันคนบ้าง ร้อยคนบ้าง ห้าสิบคนบ้าง สิบคนบ้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 26, 'คนเหล่านั้นพิพากษาความของพลไพร่อยู่เสมอ แต่คดียากๆเขานําไปแจ้งโมเสส ส่วนคดีเล็กๆน้อยๆเขาตัดสินเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 27, 'โมเสสส่งพ่อตาของตนกลับไป พ่อตาก็กลับไปยังเมืองของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 1, 'ในเดือนที่สามนับตั้งแต่ชนชาติอิสราเอลออกจากแผ่นดินอียิปต์ ในวันนั้นเขามาถึงถิ่นทุรกันดารซีนาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 2, 'เมื่อยกออกจากตําบลเรฟีดิม มาถึงถิ่นทุรกันดารซีนาย พวกเขาก็ตั้งค่ายอยู่ในถิ่นทุรกันดาร ชาวอิสราเอลตั้งค่ายอยู่ที่หน้าภูเขานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 3, 'โมเสสขึ้นไปเฝ้าพระเจ้า พระเยโฮวาห์ตรัสจากภูเขานั้นว่า “บอกวงศ์วานยาโคบและชนชาติอิสราเอลดังนี้ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 4, '‘พวกเจ้าได้เห็นกิจการซึ่งเรากระทํากับชาวอียิปต์แล้ว และที่เราเทิดชูเจ้าขึ้น ดุจดังด้วยปีกนกอินทรี เพื่อนําเจ้ามาถึงเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 5, 'เหตุฉะนั้นบัดนี้ถ้าเจ้าเชื่อฟังเสียงเรา และรักษาพันธสัญญาของเราไว้ เจ้าจะเป็นทรัพย์อันประเสริฐของเรา ยิ่งกว่าชาติทั้งปวง เพราะแผ่นดินทั้งสิ้นเป็นของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 6, 'เจ้าทั้งหลายจะเป็นอาณาจักรแห่งปุโรหิต และเป็นชนชาติบริสุทธิ์สําหรับเรา’ นี่เป็นถ้อยคําที่เจ้าต้องบอกให้ชนชาติอิสราเอลฟัง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 7, 'โมเสสจึงมาเรียกประชุมพวกผู้ใหญ่ของพลไพร่ แล้วเล่าข้อความเหล่านี้ที่พระเยโฮวาห์ทรงบัญชาท่านให้เขาฟังทุกประการ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 8, 'บรรดาพลไพร่ก็ตอบพร้อมกันว่า “สิ่งทั้งปวงที่พระเยโฮวาห์ตรัสนั้น ข้าพเจ้าทั้งหลายจะกระทําตาม” โมเสสจึงนําถ้อยคําของพลไพร่ไปกราบทูลพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 9, 'พระเยโฮวาห์ตรัสกับโมเสสว่า “ดูเถิด เราจะมาหาเจ้าในเมฆหนาทึบ เพื่อพลไพร่จะได้ยินขณะที่เราพูดกับเจ้า แล้วจะได้เชื่อเจ้าตลอดไป” โมเสสนําคําของพลไพร่นั้นกราบทูลพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 10, 'พระเยโฮวาห์จึงรับสั่งกับโมเสสว่า “ไปบอกให้พลไพร่ชําระตัวให้บริสุทธิ์ในวันนี้และพรุ่งนี้ ให้เขาซักเสื้อผ้าเสียให้สะอาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 11, 'เตรียมตัวไว้ให้พร้อมในวันที่สาม เพราะในวันที่สามนั้นพระเยโฮวาห์จะเสด็จลงมาบนภูเขาซีนายท่ามกลางสายตาของพลไพร่ทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 12, 'จงกําหนดเขตให้พลไพร่อยู่รอบภูเขา แล้วกําชับเขาว่า ‘เจ้าทั้งหลายจงระวังตัวให้ดีอย่าล่วงล้ําเขตขึ้นไปหรือถูกต้องเชิงภูเขานั้น ผู้ใดถูกภูเขาต้องมีโทษถึงตายเป็นแน่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 13, 'อย่าใช้มือฆ่าผู้นั้นเลย ให้เอาหินขว้างหรือยิงเสีย จะเป็นสัตว์ก็ดีหรือเป็นมนุษย์ก็ดี อย่าไว้ชีวิต’ เมื่อได้ยินเสียงแตรเป่ายาว ให้เขาทั้งหลายมายังภูเขานั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 14, 'โมเสสลงจากภูเขามายังพลไพร่ แล้วพลไพร่ชําระตัวให้บริสุทธิ์และซักเสื้อผ้าให้สะอาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 15, 'แล้วท่านกล่าวแก่พลไพร่ว่า “ท่านทั้งหลายจงเตรียมตัวไว้ให้พร้อมในวันที่สาม อย่าเข้าใกล้ภรรยาของท่านเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 16, 'อยู่มาพอถึงรุ่งเช้าวันที่สาม ก็บังเกิดฟ้าร้องฟ้าแลบ มีเมฆอันหนาทึบปกคลุมภูเขานั้นไว้กับมีเสียงแตรดังสนั่น จนคนทั้งปวงที่อยู่ค่ายต่างก็พากันกลัวจนตัวสั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 17, 'โมเสสก็นําประชาชนออกจากค่ายไปเฝ้าพระเจ้า พวกเขามายืนอยู่ที่เชิงภูเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 18, 'ภูเขาซีนายมีควันกลุ้มหุ้มอยู่ทั่วไปเพราะพระเยโฮวาห์เสด็จลงมาบนภูเขานั้นโดยอาศัยเพลิง ควันไฟพลุ่งขึ้นเหมือนควันจากเตาใหญ่ ภูเขาก็สะท้านหวั่นไหวไปหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 19, 'เมื่อเสียงแตรยิ่งดังขึ้น โมเสสก็กราบทูล พระเจ้าก็ตรัสตอบด้วยพระสุรเสียง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 20, 'พระเยโฮวาห์เสด็จลงมาบนยอดภูเขาซีนาย พระเยโฮวาห์ทรงเรียกโมเสสให้ขึ้นไปบนยอดเขา โมเสสก็ขึ้นไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 21, 'พระเยโฮวาห์ตรัสสั่งโมเสสว่า “เจ้าจงลงไปกําชับพลไพร่ เกรงว่าเขาจะล่วงล้ําเข้ามาถึงพระเยโฮวาห์ เพราะอยากเห็น แล้วเขาจะพินาศเสียเป็นจํานวนมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 22, 'อีกประการหนึ่ง พวกปุโรหิตที่เข้ามาเฝ้าพระเยโฮวาห์นั้นให้เขาชําระตัวให้บริสุทธิ์ ด้วยเกรงว่าพระเยโฮวาห์จะทรงลงโทษเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 23, 'ฝ่ายโมเสสกราบทูลพระเยโฮวาห์ว่า “พลไพร่ขึ้นมาบนภูเขาซีนายไม่ได้เพราะพระองค์ทรงสั่งข้าพระองค์ทั้งหลายว่า ‘จงกั้นเขตรอบภูเขานั้น ชําระให้เป็นที่บริสุทธิ์’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 24, 'พระเยโฮวาห์จึงตรัสกับโมเสสว่า “ลงไปเถิด แล้วกลับขึ้นมาอีก พาอาโรนขึ้นมาด้วย แต่อย่าให้พวกปุโรหิตและพลไพร่ล่วงล้ําขึ้นมาถึงพระเยโฮวาห์ เกรงว่าพระองค์จะลงโทษเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 25, 'โมเสสก็ลงไปบอกพลไพร่ตามนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 1, 'พระเจ้าตรัสพระวจนะทั้งสิ้นต่อไปนี้ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 2, '“เราคือพระเยโฮวาห์พระเจ้าของเจ้า ผู้ได้นําเจ้าออกจากแผ่นดินอียิปต์คือจากเรือนทาส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 3, 'อย่ามีพระอื่นใดนอกเหนือจากเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 4, 'อย่าทํารูปเคารพสลักสําหรับตนเป็นรูปสิ่งหนึ่งสิ่งใด ซึ่งมีอยู่ในฟ้าเบื้องบน หรือซึ่งมีอยู่ที่แผ่นดินเบื้องล่าง หรือซึ่งมีอยู่ในน้ําใต้แผ่นดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 5, 'อย่ากราบไหว้หรือปรนนิบัติรูปเหล่านั้น เพราะเราคือพระเยโฮวาห์พระเจ้าของเจ้าเป็นพระเจ้าที่หวงแหน ให้โทษเพราะความชั่วช้าของบิดาตกทอดไปถึงลูกหลานของผู้ที่ชังเราจนถึงสามชั่วสี่ชั่วอายุคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 6, 'แต่แสดงความเมตตาต่อคนที่รักเรา และรักษาบัญญัติของเรา จนถึงพันชั่วอายุคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 7, 'อย่าออกพระนามพระเยโฮวาห์พระเจ้าของเจ้าอย่างไร้ประโยชน์ เพราะผู้ที่ออกพระนามพระองค์อย่างไร้ประโยชน์นั้น พระเยโฮวาห์จะทรงถือว่าไม่มีโทษก็หามิได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 8, 'จงระลึกถึงวันสะบาโต ถือเป็นวันบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 9, 'จงทําการงานทั้งสิ้นของเจ้าหกวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 10, 'แต่วันที่เจ็ดนั้นเป็นสะบาโตของพระเยโฮวาห์พระเจ้าของเจ้า ในวันนั้นอย่ากระทําการงานใดๆ ไม่ว่าเจ้าเอง หรือบุตรชาย บุตรสาวของเจ้า หรือทาสทาสีของเจ้า หรือสัตว์ใช้งานของเจ้า หรือแขกที่อาศัยอยู่ในประตูเมืองของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 11, 'เพราะในหกวันพระเยโฮวาห์ทรงสร้างฟ้า และแผ่นดิน ทะเล และสรรพสิ่งซึ่งมีอยู่ในที่เหล่านั้น แต่ในวันที่เจ็ดทรงพัก เพราะฉะนั้นพระเยโฮวาห์ทรงอวยพระพรวันสะบาโต และทรงตั้งวันนั้นไว้เป็นวันบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 12, 'จงให้เกียรติแก่บิดามารดาของเจ้า เพื่ออายุของเจ้าจะได้ยืนนานบนแผ่นดิน ซึ่งพระเยโฮวาห์พระเจ้าของเจ้าประทานให้แก่เจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 13, 'อย่าฆ่าคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 14, 'อย่าล่วงประเวณีผัวเมียเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 15, 'อย่าลักทรัพย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 16, 'อย่าเป็นพยานเท็จใส่ร้ายเพื่อนบ้าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 17, 'อย่าโลภครัวเรือนของเพื่อนบ้าน อย่าโลภภรรยาของเพื่อนบ้าน หรือทาสทาสีของเขา หรือวัว ลาของเขา หรือสิ่งใดๆซึ่งเป็นของของเพื่อนบ้าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 18, 'คนทั้งหลายเมื่อได้ยิน ได้เห็นฟ้าร้อง ฟ้าแลบ เสียงแตร และควันที่พลุ่งขึ้นจากภูเขาเช่นนั้น ต่างก็ยืนตัวสั่นอยู่แต่ไกล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 19, 'เขาจึงกล่าวแก่โมเสสว่า “ท่านจงนําความมาเล่าเถิด พวกข้าพเจ้าจะฟัง แต่อย่าให้พระเจ้าตรัสกับพวกข้าพเจ้าเลย เกรงว่าข้าพเจ้าจะตาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 20, 'โมเสสจึงกล่าวแก่พลไพร่ว่า “อย่ากลัวเลย เพราะว่าพระเจ้าเสด็จมาเพื่อลองใจท่านทั้งหลาย เพื่อพวกท่านจะได้ยําเกรงพระองค์ และจะได้ไม่ทําบาป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 21, 'พลไพร่ยืนอยู่แต่ไกล แต่โมเสสเข้าไปใกล้ความมืดทึบที่พระเจ้าทรงสถิตอยู่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 22, 'พระเยโฮวาห์ตรัสกับโมเสสว่า “บอกชนชาติอิสราเอลดังนี้ว่า ‘เจ้าทั้งหลายได้เห็นแล้วว่า เราพูดกับพวกเจ้าจากท้องฟ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 23, 'เจ้าอย่าทํารูปพระด้วยเงินไว้สําหรับบูชาเทียมเท่ากับเรา หรือทํารูปพระด้วยทองคําสําหรับตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 24, 'จงใช้ดินก่อแท่นบูชาสําหรับเรา และบนแท่นนั้นจงใช้แกะและวัวของเจ้าเป็นเครื่องเผาบูชา และเป็นสันติบูชาแก่เรา ในทุกตําบลที่เราให้ระลึกถึงนามของเรา เราจะมาหาเจ้าและอวยพรเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 25, 'ถ้าจะก่อแท่นบูชาด้วยศิลาสําหรับเรา อย่าก่อด้วยศิลาที่ตกแต่งแล้ว เพราะถ้าเจ้าใช้เครื่องมือตกแต่งศิลานั้น เจ้าก็จะทําให้ศิลานั้นเป็นมลทิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 26, 'และเจ้าอย่าเดินตามขั้นบันไดขึ้นไปยังแท่นบูชาของเรา เพื่อว่าการเปลือยเปล่าของเจ้าจะไม่ได้ถูกเปิดเผยเสียที่นั่น’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 1, '“ต่อไปนี้เป็นคําตัดสินซึ่งเจ้าต้องประกาศให้เขาทั้งหลายทราบไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 2, 'ถ้าเจ้าจะซื้อคนฮีบรูไว้เป็นทาส เขาจะต้องปรนนิบัติเจ้าหกปี แต่ปีที่เจ็ดเขาจะได้เป็นอิสระโดยไม่ต้องเสียค่าไถ่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 3, 'ถ้าทาสได้มาแต่ผู้เดียวจงปล่อยเขาไปแต่ผู้เดียว ถ้าเขามีภรรยาต้องปล่อยภรรยาของเขาไปด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 4, 'ถ้านายหาภรรยาให้เขา และภรรยานั้นเกิดบุตรชายก็ดี บุตรสาวก็ดีด้วยกัน ภรรยากับบุตรนั้นจะเป็นคนของนาย เขาจะเป็นอิสระได้แต่ตัวผู้เดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 5, 'ถ้าทาสนั้นมากล่าวเป็นที่เข้าใจชัดเจนว่า ‘ข้าพเจ้ารักนายและลูกเมียของข้าพเจ้า ข้าพเจ้าไม่อยากออกไปเป็นไทย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 6, 'ให้นายพาทาสนั้นไปถึงพวกผู้พิพากษา พาเขาไปที่ประตูหรือไม้วงกบประตู แล้วให้นายเจาะหูเขาด้วยเหล็กหมาด เขาก็จะอยู่ปรนนิบัตินายต่อไปจนชีวิตหาไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 7, 'ถ้าคนใดขายบุตรสาวเป็นทาสี หญิงนั้นจะมิได้เป็นอิสระเหมือนทาส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 8, 'ถ้าหญิงนั้นไม่เป็นที่พอใจของนายที่รับเธอไว้เป็นภรรยา ต้องยอมให้คนอื่นไถ่เธอไป แต่ไม่มีสิทธิ์จะขายหญิงนั้นให้แก่ชาวต่างประเทศ เพราะมิได้สัตย์ซื่อต่อหญิงนั้นแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 9, 'ถ้านายยกหญิงนั้นให้เป็นภรรยาบุตรชายของตน ก็ให้เขาปฏิบัติต่อหญิงนั้นดุจเป็นบุตรสาวของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 10, 'ถ้าเขาหาหญิงอื่นมาเป็นภรรยา อย่าให้เขาลดอาหารการกิน เสื้อผ้าและประเพณีผัวเมียกับคนเก่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 11, 'ถ้าเขามิได้กระทําตามประการใดในสามประการนี้แก่เธอ หญิงนั้นจะไปเสียก็ได้โดยไม่ต้องมีค่าไถ่ ไม่ต้องเสียเงิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 12, 'ผู้ใดทุบตีคนหนึ่งให้ตาย ผู้นั้นจําต้องรับโทษถึงตายเป็นแน่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 13, 'ถ้าผู้ใดมิได้เจตนาฆ่าเขา แต่เขาตายเพราะพระเจ้าทรงปล่อยให้ตายด้วยมือของผู้นั้น เราจะตั้งตําบลหนึ่งไว้ให้เขาหนีไปที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 14, 'แต่ถ้าผู้ใดเจตนาหักหลังฆ่าเพื่อนบ้าน ก็ให้ดึงตัวเขาไปจากแท่นบูชาของเราเพื่อลงโทษให้ถึงตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 15, 'ผู้ใดทุบตีบิดามารดาของตน ผู้นั้นจะต้องถูกปรับโทษถึงตายเป็นแน่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 16, 'ผู้ใดลักคนไปขายก็ดี หรือมีผู้พบคนที่ถูกลักไปอยู่ในมือของผู้นั้นก็ดี ผู้ลักนั้นจะต้องถูกปรับโทษถึงตายเป็นแน่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 17, 'ผู้ใดแช่งด่าบิดามารดาของตน ผู้นั้นต้องถูกปรับโทษถึงตายเป็นแน่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 18, 'ถ้ามีผู้วิวาทกัน และฝ่ายหนึ่งเอาหินขว้างหรือชก แต่อีกฝ่ายหนึ่งไม่ถึงแก่ความตาย เพียงแต่เจ็บป่วยต้องนอนพัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 19, 'ถ้าผู้ที่บาดเจ็บนั้นลุกขึ้น ถือไม้เท้าเดินออกไปได้อีก ผู้ตีนั้นก็พ้นโทษ แต่เขาจะต้องเสียค่าป่วยการ และค่ารักษาบาดแผลจนหายเป็นปกติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 20, 'ถ้าผู้ใดทุบตีทาสชายหญิงของตนด้วยไม้จนตายคามือ ผู้นั้นต้องถูกปรับโทษเป็นแน่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 21, 'หากว่าทาสนั้นมีชีวิตต่อไปได้วันหนึ่ง หรือสองวันจึงตาย นายก็ไม่ต้องถูกปรับโทษ เพราะทาสนั้นเป็นดังเงินของนาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 22, 'ถ้ามีผู้ชายตีกัน แล้วบังเอิญไปถูกผู้หญิงมีครรภ์ทําให้แท้งลูก แต่หญิงนั้นไม่เป็นอันตราย ต้องปรับผู้นั้นตามแต่สามีของหญิงนั้นจะเรียกร้องเอาจากเขา และเขาจะต้องเสียตามที่พวกผู้พิพากษาจะตัดสิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 23, 'ถ้าหากว่าเป็นเหตุให้เกิดอันตรายประการใด ก็ให้วินิจฉัยดังนี้ คือชีวิตแทนชีวิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 24, 'ตาแทนตา ฟันแทนฟัน มือแทนมือ เท้าแทนเท้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 25, 'รอยไหม้แทนรอยไหม้ แผลแทนแผล รอยช้ําแทนรอยช้ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 26, 'ถ้าผู้ใดตีนัยน์ตาของทาสชายหญิงให้บอดไป เขาต้องปล่อยทาสผู้นั้นให้เป็นไทยเนื่องด้วยนัยน์ตาของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 27, 'ถ้าผู้ใดทําให้ฟันทาสชายหญิงหลุดไป เขาต้องปล่อยทาสผู้นั้นเป็นไทยเนื่องด้วยฟันของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 28, 'ถ้าวัวขวิดชายหรือหญิงถึงตายจงเอาหินขว้างวัวนั้นให้ตายเป็นแน่ และอย่ากินเนื้อของมันเลย แต่เจ้าของวัวตัวนั้นไม่มีโทษ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 29, 'แต่ถ้าวัวนั้นเคยขวิดคนมาก่อน และมีผู้มาเตือนให้เจ้าของทราบ แต่เจ้าของมิได้กักขังมันไว้ มันจึงได้ขวิดชายหรือหญิงถึงตาย ให้เอาหินขว้างวัวนั้นเสียให้ตายและให้ลงโทษเจ้าของถึงตายด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 30, 'ถ้าจะเรียกร้องเอาค่าไถ่จากผู้นั้น เขาต้องเสียค่าไถ่แทนชีวิตของเขาตามที่ได้เรียกร้อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 31, 'หากวัวนั้นขวิดบุตรชายและบุตรสาว ก็จงปรับโทษตามคําตัดสินข้อนี้ดุจกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 32, 'ถ้าวัวนั้นขวิดทาสชายหญิงของผู้ใด เจ้าของวัวต้องให้เงินแก่นายของทาสนั้นสามสิบเชเขล แล้วต้องเอาหินขว้างวัวนั้นให้ตายเสียด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 33, 'ถ้าผู้ใดเปิดบ่อหรือขุดบ่อแต่มิได้ปิดไว้ แล้วมีวัวหรือลาตกลงไปตายในบ่อนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 34, 'เจ้าของบ่อต้องให้ค่าชดใช้เขา ต้องเสียเงินค่าสัตว์นั้นให้แก่เจ้าของ ซากสัตว์ที่ตายนั้นจะตกเป็นของเจ้าของบ่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 35, 'ถ้าวัวของผู้ใดขวิดวัวของผู้อื่นให้ตาย เขาต้องขายวัวที่เป็นอยู่แล้วมาแบ่งเงินกัน และวัวที่ตายนั้นให้แบ่งกันด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 36, 'หรือถ้ารู้แล้วว่าวัวนั้นเคยขวิดมาก่อน แต่เจ้าของมิได้กักขังไว้ เจ้าของต้องใช้วัวแทนวัว และวัวที่ตายนั้นก็ตกเป็นของตัว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 1, '“ถ้าผู้ใดลักวัวหรือแกะไปฆ่าหรือขาย ให้ผู้นั้นใช้วัวห้าตัวแทนวัวหนึ่งตัวและแกะสี่ตัวแทนแกะตัวหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 2, 'ถ้าผู้ใดเห็นขโมยกําลังขุดช่องเข้าไปแล้วตีขโมยนั้นตาย ไม่ต้องทําให้โลหิตตกเพราะการตีคนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 3, 'ถ้าดวงอาทิตย์ขึ้นแล้ว ต้องทําให้โลหิตตกเพราะการตีคนนั้น แต่ผู้ร้ายนั้นต้องให้ค่าชดใช้ ถ้าเขาไม่มีอะไรจะใช้ให้ ต้องขายตัวเขาเป็นค่าของที่ลักไปนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 4, 'ถ้าจับของที่ลักไปนั้นได้อยู่ในมือของเขาจะเป็นวัวก็ดี หรือลาก็ดี หรือแกะก็ดี ซึ่งยังเป็นอยู่ ขโมยนั้นต้องให้ค่าชดใช้เป็นสองเท่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 5, 'ถ้าผู้ใดปล่อยให้สัตว์กินของในนา หรือในสวนองุ่นเสียไป หรือปล่อยสัตว์ของตน แล้วมันไปกินในนาของผู้อื่น เขาต้องให้ค่าชดใช้ โดยให้ของที่ดีที่สุดในนาของตน และของที่ดีที่สุดในสวนองุ่นของตนเป็นค่าเสียหาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 6, 'ถ้าจุดไฟที่กองหนาม และไฟลามไปติดกองข้าว หรือติดต้นข้าวซึ่งมิได้เกี่ยว หรือติดทุ่งนาให้ไหม้เสีย ผู้ที่จุดไฟนั้นต้องใช้ค่าเสียหายเต็มจํานวน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 7, 'ถ้าผู้ใดฝากเงินหรือสิ่งของไว้กับเพื่อนบ้านแล้วของนั้นถูกขโมยลักไปจากเรือนผู้นั้น ถ้าจับขโมยได้ ขโมยต้องใช้แทนเป็นสองเท่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 8, 'ถ้าจับขโมยไม่ได้ จงนําเจ้าของเรือนมาถึงพวกผู้พิพากษาเพื่อจะดูว่ามือของตนเองได้ลักสิ่งของของเพื่อนบ้านนั้นหรือไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 9, 'ในคดีฟ้องร้องทุกอย่าง จะเป็นเรื่องวัว ลา แกะ หรือเสื้อผ้า หรือเรื่องสิ่งของใดๆที่หายไป ถ้ามีคนมาอ้างว่าสิ่งนี้สิ่งนั้นเป็นของตน จงนําคดีของคู่ความนั้นไปถึงพวกผู้พิพากษา พวกผู้พิพากษานั้นจะตัดสินว่าผู้ใดผิด ผู้นั้นจะต้องใช้ค่าชดใช้เป็นสองเท่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 10, 'ถ้าผู้ใดฝากลาหรือวัว หรือแกะ หรือสัตว์ใดๆไว้กับเพื่อนบ้าน และสัตว์นั้นเกิดตายลงหรือเป็นอันตราย หรือมีผู้ไล่ต้อนไปจากบ้านนั้นโดยไม่มีใครเห็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 11, 'ต้องให้ผู้รับฝากนั้นปฏิญาณตัวต่อเพื่อนบ้านต่อพระพักตร์พระเยโฮวาห์เพื่อดูว่า มือของเขาลักของของเพื่อนบ้านนั้นจริงหรือไม่ แล้วเจ้าของนั้นจะต้องยินยอม ผู้รับฝากนั้นไม่ต้องให้ค่าชดใช้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 12, 'แต่ถ้าสัตว์นั้นถูกลักไป ขณะเมื่อผู้รับฝากอยู่ด้วย ผู้รับฝากต้องให้ค่าชดใช้แก่เจ้าของ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 13, 'ถ้ามีสัตว์ร้ายมากัดฉีกสัตว์นั้นตาย จงเอาซากมาให้ตรวจดูเป็นหลักฐาน แล้วผู้รับฝากไม่ต้องให้ค่าชดใช้แทนสัตว์ถูกกัดฉีกนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 14, 'ถ้าผู้ใดยืมสิ่งใดๆไปจากเพื่อนบ้านแล้วเกิดเป็นอันตราย หรือตายระหว่างเวลาที่เจ้าของไม่อยู่ ผู้ยืมต้องให้ค่าชดใช้เต็มตามจํานวนเป็นแน่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 15, 'แต่ถ้าเจ้าของอยู่ด้วย ผู้ยืมไม่ต้องให้ค่าชดใช้ ถ้าเป็นของเช่า ให้คิดแต่ค่าเช่าเท่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 16, 'ถ้าผู้ใดล่อลวงหญิงพรหมจารีที่ยังไม่มีคู่หมั้นและนอนร่วมกับหญิงนั้น ผู้นั้นจะต้องเสียเงินสินสอด และต้องรับหญิงนั้นเป็นภรรยาของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 17, 'ถ้าบิดาไม่ยอมอย่างเด็ดขาดที่จะยกหญิงนั้นให้เป็นภรรยา เขาก็ต้องเสียเงินเท่าสินสอดตามธรรมเนียมสู่ขอหญิงพรหมจารีนั้นดุจกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 18, 'สําหรับหญิงแม่มด เจ้าอย่าให้รอดชีวิตอยู่เลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 19, 'ผู้ใดร่วมประเวณีกับสัตว์ ผู้นั้นจะต้องถูกลงโทษถึงตายเป็นแน่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 20, 'ผู้ใดถวายบูชาแก่พระต่างๆเว้นแต่พระเยโฮวาห์องค์เดียว ผู้นั้นต้องถูกทําลายเสียสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 21, 'เจ้าอย่าบีบบังคับหรือข่มเหงคนต่างด้าวเลย เพราะเจ้าทั้งหลายเคยเป็นคนต่างด้าวอยู่ในประเทศอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 22, 'อย่าข่มเหงหญิงม่ายหรือลูกกําพร้าพ่อเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 23, 'ถ้าเจ้าข่มเหงเขาโดยวิธีใดก็ตาม และเขาร้องทุกข์ถึงเรา เราจะฟังคําร้องทุกข์ของเขาแน่ๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 24, 'ความโกรธของเราจะพลุ่งขึ้น และเราจะประหารเจ้าด้วยดาบ ภรรยาของเจ้าจะต้องเป็นม่าย และบุตรของเจ้าจะต้องเป็นกําพร้าพ่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 25, 'ถ้าเจ้าให้พลไพร่ของเราคนใดที่เป็นคนจนและอยู่กับเจ้ายืมเงินไป อย่าถือว่าตนเป็นเจ้าหนี้ และอย่าคิดดอกเบี้ยจากเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 26, 'ถ้าเจ้าได้รับเสื้อคลุมของเพื่อนบ้านไว้เป็นของประกัน จงคืนของนั้นให้เขาก่อนตะวันตกดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 27, 'เพราะเขามีเสื้อคลุมตัวนั้นตัวเดียวเป็นเครื่องปกคลุมร่างกาย มิฉะนั้นเวลานอนเขาจะเอาอะไรห่มเล่า ต่อมาเมื่อเขาทูลร้องทุกข์ต่อเรา เราจะสดับฟังเพราะเราเป็นผู้มีเมตตากรุณา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 28, 'อย่าด่าผู้เป็นพระ หรือสาปแช่งผู้ปกครองชนชาติของเจ้าเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 29, 'อย่าชักช้าที่จะนําพืชผลและน้ําผลไม้อันแรกของเจ้ามาถวายพระเจ้า จงถวายบุตรชายหัวปีของเจ้าให้แก่เรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 30, 'สําหรับวัวและแพะแกะของเจ้า จงทําดังนั้นเหมือนกัน ให้ลูกมันอยู่กับแม่เจ็ดวัน ถึงวันที่แปดจงพามาถวายแก่เรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 31, 'เจ้าทั้งหลายเป็นคนบริสุทธิ์อุทิศแก่เรา เหตุฉะนั้นเนื้อสัตว์ที่ถูกกัดตายในทุ่งนา เจ้าอย่ากินเลย จงทิ้งให้สุนัขกินเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 1, '“อย่านําเรื่องเท็จไปเล่าต่อๆกัน อย่าร่วมมือเป็นพยานใส่ร้ายกับคนชั่ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 2, 'อย่าทําชั่วตามอย่างคนจํานวนมากที่เขาทํากันนั้นเลย อย่าอ้างพยานลําเอียงเข้าข้างหมู่มาก จะทําให้ขาดความยุติธรรมไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 3, 'ทั้งอย่าลําเอียงเข้าข้างคนจนในคดีของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 4, 'ถ้าเจ้าพบวัวหรือลาของศัตรูหลงมา จงพาไปส่งคืนให้เจ้าของจงได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 5, 'ถ้าเห็นลาของผู้ที่เกลียดชังเจ้าล้มลงเพราะบรรทุกของหนัก อย่าได้เมินเฉยเสีย จงช่วยเขายกมันขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 6, 'เจ้าอย่าบิดเบือนคําพิพากษาให้ผิดไปจากความยุติธรรมที่คนจนควรได้รับในคดีของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 7, 'เจ้าจงหลีกให้ห่างไกลจากการใส่ความคนอื่น อย่าประหารชีวิตคนที่ปราศจากความผิดและคนชอบธรรม เพราะเราจะไม่ยกโทษให้คนชั่ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 8, 'อย่ารับสินบนเลย เพราะว่าสินบนทําให้คนตาดีกลายเป็นคนตาบอดไป และพลิกคดีของคนชอบธรรมเสียได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 9, 'เจ้าอย่าข่มเหงคนต่างด้าวเพราะเจ้ารู้จักใจคนต่างด้าวแล้ว เพราะว่าเจ้าทั้งหลายก็เคยเป็นคนต่างด้าวในประเทศอียิปต์มาก่อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 10, 'จงหว่านพืชและเกี่ยวเก็บผลในนาของเจ้าตลอดหกปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 11, 'แต่ปีที่เจ็ดนั้นจงงดเสีย ปล่อยให้นานั้นว่างอยู่ เพื่อให้คนจนในชนชาติของเจ้าเก็บกิน ส่วนที่เหลือนอกนั้นก็ให้สัตว์ป่ากิน ส่วนสวนองุ่นและสวนมะกอกเทศเจ้าจงกระทําเช่นเดียวกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 12, 'จงทําการงานของเจ้าหกวัน แต่ในวันที่เจ็ดนั้นจงหยุดงาน เพื่อวัว ลาของเจ้าจะได้พัก และลูกชายทาสีของเจ้า กับคนต่างด้าวจะได้พักผ่อนให้สดชื่นด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 13, 'สิ่งทั้งปวงที่เราสั่งเจ้าไว้นั้นจงระวังถือให้ดี และอย่าออกชื่อพระอื่นเลย อย่าให้ได้ยินชื่อของพระเหล่านั้นออกจากปากของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 14, 'จงถือเทศกาลถวายแก่เราปีละสามครั้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 15, 'จงถือเทศกาลกินขนมปังไร้เชื้อตามเวลาที่กําหนดไว้ (ในเดือนอาบีบ อันเป็นเดือนซึ่งเราบัญชาไว้ เจ้าจงกินขนมปังไร้เชื้อเจ็ดวันตามที่เราสั่งเจ้าไว้แล้ว เพราะในเดือนนั้นเจ้าออกจากอียิปต์ อย่าให้ผู้ใดมาเฝ้าเรามือเปล่าเลย)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 16, 'จงถือเทศกาลเลี้ยงฉลองการเก็บเกี่ยว ถวายพืชผลแรกที่เกิดจากแรงงานของเจ้า ซึ่งเจ้าได้หว่านพืชลงในนา เจ้าจงถือเทศกาลเลี้ยงฉลองการเก็บพืชผลปลายปี เมื่อเจ้าเก็บพืชผลจากทุ่งนาอันเป็นผลงานของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 17, 'ให้ผู้ชายทั้งปวงเข้าเฝ้าองค์พระผู้เป็นเจ้าพระเจ้าปีละสามครั้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 18, 'อย่าถวายเลือดจากเครื่องบูชาของเรา พร้อมกับขนมปังมีเชื้อ หรือปล่อยให้มีไขมันในเครื่องบูชาของเราเหลืออยู่จนถึงรุ่งเช้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 19, 'พืชผลอันดีเลิศซึ่งได้เก็บครั้งแรกจากไร่นาของเจ้านั้นจงนํามาถวายในพระนิเวศพระเยโฮวาห์พระเจ้าของเจ้า อย่าต้มเนื้อลูกแพะด้วยน้ํานมของแม่มันเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 20, 'ดูเถิด เราใช้ทูตสวรรค์องค์หนึ่งเดินนําหน้าพวกเจ้าเพื่อคอยระวังรักษาพวกเจ้าตามทาง นําไปถึงที่ซึ่งเราได้เตรียมไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 21, 'จงเอาใจใส่ทูตนั้นและเชื่อฟังเสียงของเขา อย่าฝ่าฝืนเขาเพราะเขาจะไม่ยกโทษการละเมิดให้เจ้าเลย ด้วยว่าเขากระทําในนามของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 22, 'แต่ถ้าเจ้าทั้งหลายเชื่อฟังเสียงของเขาจริงๆ และทําทุกสิ่งตามที่เราสั่งไว้ เราจะเป็นศัตรูต่อศัตรูของพวกเจ้า และจะเป็นปฏิปักษ์ต่อปฏิปักษ์ของพวกเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 23, 'ด้วยว่าทูตสวรรค์ของเราจะไปข้างหน้าพวกเจ้า และจะนําพวกเจ้าไปถึงคนอาโมไรต์ คนฮิตไทต์ คนเปริสซี คนคานาอัน คนฮีไวต์ และคนเยบุส แล้วเราจะตัดคนเหล่านั้นออกเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 24, 'อย่ากราบไหว้พระของเขา หรือปรนนิบัติหรือทําตามแบบอย่างที่พวกเขากระทํา แต่จงทําลายรูปเคารพของเขา และทุบเสาศักดิ์สิทธิ์ของเขาเสียให้แหลกละเอียด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 25, 'จงปรนนิบัติพระเยโฮวาห์พระเจ้าของเจ้า แล้วพระองค์จะทรงอวยพรแก่อาหารและน้ําของเจ้า เราจะบันดาลให้โรคต่างๆหายไปจากท่ามกลางพวกเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 26, 'จะไม่มีการแท้งลูก หรือเป็นหมันในดินแดนของเจ้า เราจะให้เจ้ามีอายุยืนนาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 27, 'เราจะบันดาลให้เกิดความสยดสยองขึ้นก่อนหน้าพวกเจ้า เราจะทําลายชาวเมืองทั้งปวงที่พวกเจ้าไปเผชิญหน้านั้น เราจะให้พวกศัตรูทั้งปวงหันหลังหนีพวกเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 28, 'เราจะใช้ให้ฝูงต่อล่วงหน้าไปก่อนพวกเจ้า จะขับไล่คนฮีไวต์ คนคานาอัน คนฮิตไทต์ไปให้พ้นหน้าพวกเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 29, 'เราจะไม่ไล่เขาไปให้พ้นหน้าพวกเจ้าในระยะปีเดียว เกรงว่าแผ่นดินจะรกร้างไปและสัตว์ป่าจะทวีจํานวนขึ้นต่อสู้กับพวกเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 30, 'แต่เราจะไล่เขาไปให้พ้นหน้าพวกเจ้าทีละเล็กละน้อยจนพวกเจ้าทวีจํานวนมากขึ้น แล้วได้รับมอบดินแดนนั้นเป็นกรรมสิทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 31, 'เราจะกําหนดเขตแดนของพวกเจ้าไว้ตั้งแต่ทะเลแดงจนถึงทะเลของชาวฟีลิสเตีย ตั้งแต่ถิ่นทุรกันดารจนจดแม่น้ํา เพราะเราจะมอบชาวเมืองนั้นไว้ในมือของพวกเจ้าให้พวกเจ้าไล่เขาไปเสียให้พ้นหน้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 32, 'พวกเจ้าอย่าทําพันธสัญญากับเขา หรือกับพระของเขาเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 33, 'เขาจะอาศัยในดินแดนของเจ้าไม่ได้ เกรงว่าเขาจะชักจูงให้เจ้ากระทําบาปต่อเรา เพราะว่าถ้าพวกเจ้าปรนนิบัติพระของเขา เรื่องนี้ก็จะเป็นบ่วงแร้วดักเจ้าเป็นแน่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 1, 'พระองค์ตรัสกับโมเสสว่า “เจ้ากับอาโรน นาดับ และอาบีฮู กับพวกผู้ใหญ่เจ็ดสิบคนของอิสราเอลจงขึ้นมาเฝ้าพระเยโฮวาห์ แล้วนมัสการอยู่แต่ไกล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 2, 'ให้เฉพาะโมเสสผู้เดียวเข้ามาใกล้พระเยโฮวาห์ ส่วนคนอื่นๆอย่าให้เข้ามาใกล้และอย่าให้ประชาชนขึ้นมากับโมเสสเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 3, 'โมเสสจึงนําพระวจนะของพระเยโฮวาห์และคําตัดสินทั้งสิ้นมาชี้แจงให้ประชาชนทราบ ประชาชนทั้งปวงก็ตอบเป็นเสียงเดียวกันว่า “พระวจนะทั้งหมดซึ่งพระเยโฮวาห์ตรัสไว้นั้น พวกเราจะกระทําตาม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 4, 'โมเสสจึงจารึกพระวจนะของพระเยโฮวาห์ไว้ทุกคํา แล้วตื่นขึ้นแต่เช้าจัดแจงสร้างแท่นบูชาขึ้นที่เชิงภูเขา ปักเสาหินขึ้นสิบสองก้อนตามจํานวนตระกูลทั้งสิบสองของอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 5, 'ท่านใช้ให้หนุ่มๆชนชาติอิสราเอลถวายเครื่องเผาบูชาและถวายวัวเป็นเครื่องสันติบูชาแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 6, 'โมเสสเก็บเลือดวัวครึ่งหนึ่งไว้ในชาม อีกครึ่งหนึ่งประพรมที่แท่นบูชานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 7, 'ท่านถือหนังสือพันธสัญญาอ่านให้ประชาชนฟัง พวกเขากล่าวว่า “บรรดาสิ่งที่พระเยโฮวาห์ตรัสไว้นั้นพวกเราจะกระทําตาม และเราจะเชื่อฟัง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 8, 'โมเสสก็เอาเลือดพรมประชาชนและกล่าวว่า “ดูเถิด นี่เป็นเลือดแห่งพันธสัญญา ซึ่งพระเยโฮวาห์กระทํากับเจ้าตามพระวจนะทั้งหมดนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 9, 'ครั้งนั้นโมเสสกับอาโรน นาดับและอาบีฮู และพวกผู้ใหญ่เจ็ดสิบคนของอิสราเอลขึ้นไปอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 10, 'เขาทั้งหลายได้เห็นพระเจ้าแห่งอิสราเอล และพื้นที่รองพระบาทเป็นดุจพลอยไพทูรย์สุกใสเหมือนท้องฟ้าทีเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 11, 'พระองค์มิได้ลงโทษบรรดาหัวหน้าชนชาติอิสราเอล เขาทั้งหลายได้เห็นพระเจ้าและได้กินและดื่ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 12, 'พระเยโฮวาห์ตรัสกับโมเสสว่า “ขึ้นมาหาเราบนภูเขาแล้วคอยอยู่ที่นั่น เราจะให้แผ่นศิลาอันมีราชบัญญัติ และข้อบัญญัติซึ่งเราจารึกไว้เพื่อเก็บไว้สอนเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 13, 'โมเสสจึงลุกขึ้นพร้อมกับโยชูวาผู้รับใช้ โมเสสขึ้นไปบนภูเขาของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 14, 'และกล่าวแก่พวกผู้ใหญ่เหล่านั้นว่า “คอยเราอยู่ที่นี่จนกว่าเราจะกลับมาหาพวกท่านอีก ดูเถิด อาโรนและเฮอร์อยู่กับพวกท่าน ใครมีเรื่องราวอะไรก็จงมาหาท่านทั้งสองนี้เถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 15, 'แล้วโมเสสขึ้นไปบนภูเขา เมฆก็คลุมภูเขาไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 16, 'สง่าราศีของพระเยโฮวาห์มาอยู่บนภูเขาซีนาย เมฆนั้นปกคลุมภูเขาอยู่หกวัน ครั้นวันที่เจ็ดพระองค์ทรงเรียกโมเสสจากหมู่เมฆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 17, 'สง่าราศีของพระเยโฮวาห์ปรากฏแก่ตาชนชาติอิสราเอลเหมือนเปลวไฟไหม้อยู่บนยอดภูเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 18, 'โมเสสเข้าไปในหมู่เมฆนั้นและขึ้นไปบนภูเขา โมเสสอยู่บนภูเขานั้นสี่สิบวันสี่สิบคืน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 1, 'ฝ่ายพระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 2, '“จงสั่งชนชาติอิสราเอลให้นําของมาถวายแก่เรา ของนั้นให้รับมาจากทุกๆคนที่เต็มใจถวาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 3, 'ของถวายซึ่งเจ้าจะต้องรับจากเขาคือ ทองคํา เงิน ทองเหลือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 4, 'ด้ายสีฟ้า สีม่วง สีแดงเข้ม ผ้าป่านเนื้อละเอียดและขนแพะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 5, 'หนังแกะตัวผู้ย้อมสีแดง หนังของแบดเจอร์ และไม้กระถินเทศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 6, 'น้ํามันเติมประทีป เครื่องเทศปรุงน้ํามันสําหรับเจิม และปรุงเครื่องหอม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 7, 'พลอยสีน้ําข้าวและพลอยสําหรับฝังในเอโฟดและทับทรวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 8, 'แล้วให้เขาสร้างสถานบริสุทธิ์ถวายแก่เรา เพื่อเราจะได้อยู่ท่ามกลางพวกเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 9, 'แบบอย่างพลับพลาและเครื่องทั้งปวงของพลับพลานั้น เจ้าจงทําตามที่เราแจ้งไว้แก่เจ้านี้ทุกประการ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 10, 'ให้เขาทําหีบใบหนึ่งด้วยไม้กระถินเทศ ยาวสองศอกคืบ กว้างศอกคืบ และสูงศอกคืบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 11, 'หีบนั้นหุ้มด้วยทองคําบริสุทธิ์ทั้งด้านในและด้านนอก แล้วทํากระจังคาดรอบหีบนั้นด้วยทองคํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 12, 'ให้หล่อห่วงทองคําสี่ห่วงสําหรับหีบนั้น ติดไว้ที่มุมทั้งสี่ ด้านนี้สองห่วงและด้านนั้นสองห่วง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 13, 'ให้ทําคานหามด้วยไม้กระถินเทศหุ้มด้วยทองคํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 14, 'แล้วสอดคานหามเข้าที่ห่วงข้างหีบสําหรับใช้ยกหามหีบนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 15, 'ไม้คานหามให้สอดไว้ในห่วงของหีบ อย่าถอดออกเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 16, 'พระโอวาทที่เราจะให้แก่เจ้าจงเก็บไว้ในหีบนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 17, 'แล้วจงทําพระที่นั่งกรุณาด้วยทองคําบริสุทธิ์ ยาวสองศอกคืบ กว้างศอกคืบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 18, 'จงทําเครูบทองคําสองรูป โดยใช้ฝีค้อนทําตั้งไว้ที่ปลายพระที่นั่งกรุณาทั้งสองข้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 19, 'ทําเครูบไว้ที่ปลายพระที่นั่งกรุณาข้างละรูป ทําเครูบนั้นและให้ตอนปลายทั้งสองข้างติดเป็นเนื้อเดียวกับพระที่นั่งกรุณา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 20, 'ให้เครูบกางปีกออกไว้เบื้องบน ปกพระที่นั่งกรุณาไว้ด้วยปีก และให้หันหน้าเข้าหากัน ให้เครูบหันหน้ามาตรงพระที่นั่งกรุณา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 21, 'แล้วจงตั้งพระที่นั่งกรุณานั้นไว้บนหีบ จงบรรจุพระโอวาทซึ่งเราจะให้ไว้แก่เจ้าไว้ในหีบนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 22, 'ณ ที่นั้น เราจะอยู่ให้เจ้าเข้าเฝ้า และจะสนทนากับเจ้าจากเหนือพระที่นั่งกรุณาระหว่างกลางเครูบทั้งสองซึ่งตั้งอยู่บนหีบพระโอวาท เราจะสนทนากับเจ้าทุกเรื่องซึ่งเราจะสั่งเจ้าให้ประกาศแก่ชนชาติอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 23, 'แล้วจงเอาไม้กระถินเทศมาทําโต๊ะตัวหนึ่ง ยาวสองศอก กว้างหนึ่งศอก และสูงศอกคืบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 24, 'เจ้าจงหุ้มโต๊ะนั้นด้วยทองคําบริสุทธิ์ และทํากระจังทองคํารอบโต๊ะนั้นด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 25, 'ประกับโต๊ะนั้นทําให้กว้างหนึ่งฝ่ามือโดยรอบ แล้วทํากระจังทองคําประกอบให้รอบประกับนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 26, 'จงทําห่วงทองคําสี่ห่วงติดไว้ที่มุมขาโต๊ะทั้งสี่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 27, 'ห่วงนั้นให้ติดชิดกับประกับ เพื่อเอาไว้สอดคานหาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 28, 'เจ้าจงทําคานหามด้วยไม้กระถินเทศ หุ้มด้วยทองคํา ให้หามโต๊ะด้วยไม้นี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 29, 'เจ้าจงทําจานและช้อน คนโท และอ่างน้ําที่ใช้สําหรับรินเครื่องดื่มบูชา สิ่งเหล่านี้เจ้าจงทําด้วยทองคําบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 30, 'และเจ้าจงวางขนมปังหน้าพระพักตร์ไว้บนโต๊ะนั้นต่อหน้าเราเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 31, 'เจ้าจงทําคันประทีปอันหนึ่งด้วยทองคําบริสุทธิ์ จงใช้ฝีค้อนทําคันประทีป ให้ทั้งลําตัว กิ่ง ดอก ดอกตูม และกลีบติดเป็นเนื้อเดียวกันกับคันประทีปนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 32, 'ให้มีกิ่งหกกิ่ง แยกออกจากลําคันประทีปนั้นข้างละสามกิ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 33, 'กิ่งหนึ่งมีดอกเหมือนดอกอัลมันด์สามดอก ทุกๆดอกให้มีดอกตูมและกลีบ อีกกิ่งหนึ่งให้มีดอกสามดอกเหมือนดอกอัลมันด์ ทุกๆดอกให้มีดอกตูมและกลีบ ให้เป็นดังนี้ทั้งหกกิ่งซึ่งยื่นออกจากลําคันประทีป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 34, 'สําหรับลําคันประทีปนั้นให้มีดอกสี่ดอกเหมือนดอกอัลมันด์ ทั้งดอกตูมและกลีบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 35, 'ใต้กิ่งทุกๆคู่ทั้งหกกิ่งที่ลําคันประทีปนั้น ให้มีดอกตูมเป็นเนื้อเดียวกันกับคันประทีป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 36, 'ดอกตูมและกิ่งทําให้เป็นเนื้อเดียวกันกับคันประทีป ให้ทุกส่วนเป็นเนื้อเดียวกันด้วยทองคําบริสุทธิ์ที่ใช้ค้อนทํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 37, 'จงทําตะเกียงเจ็ดดวงสําหรับคันประทีปนั้น แล้วจุดตะเกียงให้ส่องแสงตรงไปหน้าคันประทีป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 38, 'ตะไกรตัดไส้ตะเกียง และถาดใส่ตะไกรให้ทําด้วยทองคําบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 39, 'คันประทีปกับเครื่องใช้ทุกอย่างให้ทําด้วยทองคําบริสุทธิ์หนึ่งตะลันต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 40, 'จงระวังทําสิ่งเหล่านี้ตามแบบอย่างที่เราแจ้งแก่เจ้าบนภูเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 1, '“นอกจากนั้น เจ้าจงทําพลับพลาด้วยม่านสิบผืน ทําด้วยผ้าป่านเนื้อละเอียด และผ้าทอด้วยด้ายย้อมสีฟ้า สีม่วง สีแดงเข้ม กับให้มีภาพเครูบฝีมือช่างออกแบบไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 2, 'ม่านผืนหนึ่งให้ยาวยี่สิบแปดศอก กว้างสี่ศอก ม่านทุกผืนให้เท่ากัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 3, 'ม่านห้าผืนให้เกี่ยวติดกัน และอีกห้าผืนนั้นก็ให้เกี่ยวติดกันด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 4, 'จงทําหูม่านด้วยด้ายสีฟ้าติดไว้ตามขอบม่านด้านนอกสุดชุดที่หนึ่ง และตามขอบม่านด้านนอกสุดชุดที่สอง จงติดหูไว้เหมือนกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 5, 'ม่านผืนหนึ่งให้ทําหูห้าสิบหู และตามขอบม่านชุดที่สอง ให้ทําหูห้าสิบหูให้ตรงกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 6, 'จงทําขอทองคําห้าสิบขอสําหรับใช้เกี่ยวม่าน เพื่อให้เป็นพลับพลาเดียวกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 7, 'จงทําม่านด้วยขนแพะ สําหรับเป็นเต็นท์คลุมพลับพลาชั้นนอกอีกสิบเอ็ดผืน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 8, 'ม่านผืนหนึ่งให้ทํายาวสามสิบศอก กว้างสี่ศอก ทั้งสิบเอ็ดผืนให้เท่ากัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 9, 'ม่านห้าผืนให้เกี่ยวติดกันต่างหากและม่านอีกหกผืนให้เกี่ยวติดกันต่างหากเช่นกัน และม่านผืนที่หกนั้นจงให้ห้อยซ้อนลงมาข้างหน้าพลับพลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 10, 'ทําหูห้าสิบหูติดกับขอบม่านด้านนอกสุดชุดที่หนึ่ง และหูห้าสิบหูติดกับขอบม่านด้านนอกสุดชุดที่สอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 11, 'แล้วทําขอทองเหลืองห้าสิบขอ เกี่ยวขอเข้าที่หู เกี่ยวให้ติดเป็นเต็นท์หลังเดียวกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 12, 'ม่านเต็นท์ส่วนที่เกินอยู่ คือชายม่านครึ่งหนึ่งที่เหลืออยู่นั้น จงให้ห้อยลงมาด้านหลังพลับพลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 13, 'ส่วนม่านคลุมพลับพลา ซึ่งยาวเกินไปข้างละหนึ่งศอกนั้น ให้ห้อยลงมาข้างๆพลับพลาทั้งข้างนี้และข้างโน้น สําหรับใช้กําบัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 14, 'เครื่องดาดเต็นท์ข้างบน เจ้าจงทําด้วยหนังแกะตัวผู้ ย้อมสีแดงชั้นหนึ่ง และคลุมด้วยหนังของแบดเจอร์อีกชั้นหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 15, 'ไม้กรอบสําหรับทําฝาพลับพลานั้น ให้ใช้ไม้กระถินเทศตั้งตรงขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 16, 'ไม้กรอบนั้นให้ยาวแผ่นละสิบศอก กว้างศอกคืบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 17, 'ให้มีเดือยกรอบละสองเดือย เดือยกรอบหนึ่งมีไม้ประกับติดกับเดือยอีกกรอบหนึ่ง ไม้กรอบพลับพลาทั้งหมดให้ทําอย่างนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 18, 'เจ้าจงทําไม้กรอบพลับพลาดังนี้ ด้านใต้ให้ทํายี่สิบแผ่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 19, 'จงทําฐานรองรับด้วยเงินสี่สิบฐานสําหรับไม้กรอบยี่สิบแผ่น ใต้ไม้กรอบแผ่นหนึ่งให้มีฐานรองรับแผ่นละสองฐาน สําหรับสวมเดือยสองอัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 20, 'ด้านที่สองของพลับพลาข้างทิศเหนือนั้น ให้ใช้ไม้กรอบยี่สิบแผ่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 21, 'และทําฐานเงินรองรับสี่สิบฐาน ใต้กรอบให้ทําฐานแผ่นละสองฐาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 22, 'ส่วนด้านหลังทิศตะวันตกของพลับพลา ให้ทําไม้กรอบหกแผ่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 23, 'และทําอีกสองแผ่นสําหรับมุมพลับพลาด้านหลัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 24, 'ไม้กรอบนั้นข้างล่างให้แยกกัน แต่ตอนบนยอดให้ติดกันที่ห่วงแรกทั้งสองแห่ง ให้กระทําดังนี้ก็จะทําให้เกิดมุมสองมุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 25, 'คือรวมเป็นไม้กรอบแปดแผ่นด้วยกัน และฐานเงินสิบหกอัน ใต้กรอบไม้ให้มีฐานรองรับแผ่นละสองฐาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 26, 'เจ้าจงทํากลอนด้วยไม้กระถินเทศห้าอัน สําหรับไม้กรอบฝาพลับพลาด้านหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 27, 'และกลอนอีกห้าอันสําหรับขัดไม้กรอบฝาพลับพลาอีกด้านหนึ่ง และกลอนอีกห้าอันสําหรับขัดไม้กรอบฝาพลับพลาด้านหลัง คือด้านตะวันตก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 28, 'กลอนตัวกลางคืออยู่ตอนกลางของไม้กรอบสําหรับขัดฝาร้อยให้ติดกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 29, 'จงหุ้มไม้กรอบเหล่านั้นด้วยทองคํา และทําห่วงไม้กรอบด้วยทองคําสําหรับร้อยกลอน และกลอนนั้นให้หุ้มด้วยทองคํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 30, 'พลับพลานั้น เจ้าจงจัดตั้งไว้ตามแบบอย่างที่เราได้แจ้งแก่เจ้าแล้วที่บนภูเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 31, 'จงทําม่านผืนหนึ่ง ทอด้วยด้ายสีฟ้า สีม่วง สีแดงเข้ม และด้วยผ้าป่านเนื้อละเอียด ให้มีภาพเครูบฝีมือช่างออกแบบไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 32, 'ม่านนั้นให้แขวนไว้ด้วยขอทองคําที่เสาไม้กระถินเทศสี่เสาที่หุ้มด้วยทองคํา และซึ่งตั้งอยู่บนฐานเงินสี่อัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 33, 'ม่านนั้นให้เขาแขวนไว้กับขอสําหรับเกี่ยวม่าน แล้วเอาหีบพระโอวาทเข้ามาไว้ข้างในภายในม่าน และม่านนั้นจะเป็นที่แบ่งพลับพลาระหว่างที่บริสุทธิ์กับที่บริสุทธิ์ที่สุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 34, 'พระที่นั่งกรุณานั้นให้ตั้งไว้บนหีบพระโอวาทในที่บริสุทธิ์ที่สุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 35, 'จงตั้งโต๊ะไว้ข้างนอกม่าน และจงตั้งคันประทีปไว้ด้านใต้ในพลับพลาตรงข้ามกับโต๊ะ เจ้าจงตั้งโต๊ะไว้ทางด้านเหนือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 36, 'เจ้าจงทําบังตาที่ประตูเต็นท์นั้นด้วยด้ายสีฟ้า สีม่วง สีแดงเข้ม และด้วยผ้าป่านเนื้อละเอียดประกอบด้วยฝีมือช่างด้ายสี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 37, 'จงทําเสาห้าต้นด้วยไม้กระถินเทศสําหรับติดบังตาที่ประตูแล้วหุ้มเสานั้นด้วยทองคํา ขอแขวนเสาจงทําด้วยทองคํา แล้วหล่อฐานทองเหลืองห้าฐานสําหรับรองรับเสานั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 1, '“เจ้าจงทําแท่นบูชาด้วยไม้กระถินเทศให้ยาวห้าศอก กว้างห้าศอก ให้เป็นแท่นสี่เหลี่ยมจัตุรัส สูงสามศอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 2, 'จงทําเชิงงอนติดไว้ทั้งสี่มุมของแท่น ให้เป็นชิ้นเดียวกันกับแท่น และจงหุ้มแท่นด้วยทองเหลือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 3, 'เจ้าจงทําหม้อสําหรับใส่ขี้เถ้า พลั่ว ชาม ขอเกี่ยวเนื้อและถาดรองไฟ คือเครื่องใช้สําหรับแท่นทั้งหมด เจ้าจงทําด้วยทองเหลือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 4, 'แล้วเอาทองเหลืองทําตาข่ายประดับแท่นนั้น กับทําห่วงทองเหลืองติดที่มุมทั้งสี่ของตาข่าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 5, 'ตาข่ายนั้นให้อยู่ใต้กระจังของแท่น และให้ห้อยอยู่ตั้งแต่กลางแท่นลงมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 6, 'ไม้คานหามแท่นให้ทําด้วยไม้กระถินเทศและหุ้มด้วยทองเหลือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 7, 'ไม้คานหามนั้นให้สอดไว้ในห่วง ในเวลาหามไม้คานหามจะอยู่ข้างแท่นข้างละอัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 8, 'แท่นนั้นทําด้วยไม้กระดาน แต่ข้างในแท่นกลวงตามแบบที่แจ้งแก่เจ้าแล้วที่ภูเขา จงให้เขาทําอย่างนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 9, 'เจ้าจงสร้างลานพลับพลา ให้รั้วด้านใต้มีผ้าบังลานนั้นทําด้วยผ้าป่านเนื้อละเอียดยาวหนึ่งร้อยศอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 10, 'ให้มีเสายี่สิบต้นกับฐานทองเหลืองรองรับเสายี่สิบฐาน ขอติดเสาและราวยึดเสานั้น ให้ทําด้วยเงิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 11, 'ทํานองเดียวกัน ด้านทิศเหนือให้มีผ้าบังยาวร้อยศอก เหมือนกันกับเสายี่สิบต้น และฐานทองเหลืองยี่สิบฐาน ขอติดเสาและราวยึดเสานั้น ให้ทําด้วยเงิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 12, 'ตามส่วนกว้างของลานด้านตะวันตก ให้มีผ้าบังยาวห้าสิบศอก กับเสาสิบต้น และฐานรองรับเสาสิบฐาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 13, 'ส่วนกว้างของลานด้านตะวันออก ให้ยาวห้าสิบศอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 14, 'ผ้าบังด้านริมประตูข้างหนึ่งให้ยาวสิบห้าศอก มีเสาสามต้น และฐานรองรับเสาสามฐาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 15, 'อีกข้างหนึ่งให้มีผ้าบังยาวสิบห้าศอก มีเสาสามต้น และฐานรองรับเสาสามฐาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 16, 'ให้มีผ้าบังตาที่ประตูลานยาวยี่สิบศอก ผ้าสีฟ้า สีม่วง สีแดงเข้ม และผ้าป่านเนื้อละเอียด ประกอบด้วยฝีมือของช่างด้ายสี กับเสาสี่ต้นและฐานรองรับเสาสี่ฐาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 17, 'เสาล้อมรอบลานทั้งหมด ให้มีราวสําหรับยึดเสาให้ติดต่อกันทําด้วยเงิน และให้ทําขอด้วยเงิน ฐานรองรับเสานั้นทําด้วยทองเหลือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 18, 'ด้านยาวของลานนั้นจะเป็นร้อยศอก ด้านกว้างห้าสิบศอก สูงห้าศอก กั้นด้วยผ้าป่านเนื้อละเอียด และมีฐานทองเหลือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 19, 'เครื่องใช้สอยทั้งปวงของพลับพลาพร้อมทั้งหลักหมุดของพลับพลา กับหลักหมุดสําหรับรั้วที่กั้นลานทั้งหมด ให้ทําด้วยทองเหลือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 20, 'เจ้าจงสั่งชนชาติอิสราเอลให้นําน้ํามันมะกอกเทศบริสุทธิ์ที่คั้นไว้นั้นมาสําหรับเติมประทีป เพื่อจะให้ประทีปนั้นส่องสว่างอยู่เสมอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 21, 'ในพลับพลาแห่งชุมนุมข้างนอกม่านซึ่งอยู่หน้าหีบพระโอวาท ให้อาโรนและบุตรชายของอาโรน ดูแลประทีปนั้นอยู่เฉพาะพระพักตร์พระเยโฮวาห์ ตั้งแต่เวลาพลบค่ําจนถึงรุ่งเช้า ให้เป็นกฎเกณฑ์เนืองนิตย์ที่ชนชาติอิสราเอลต้องปฏิบัติตามชั่วอายุของเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 1, '“จงนําอาโรนพี่ชายของเจ้ากับบุตรชายของเขาแยกออกมาจากหมู่ชนชาติอิสราเอลให้มาอยู่ใกล้เจ้า เพื่อจะให้ปรนนิบัติเราในตําแหน่งปุโรหิต คือทั้งอาโรนกับบุตรชายของอาโรน คือนาดับ อาบีฮู เอเลอาซาร์ กับอิธามาร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 2, 'แล้วให้ทําเครื่องยศบริสุทธิ์สําหรับอาโรนพี่ชายของเจ้าให้สมเกียรติ และงดงาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 3, 'ให้กล่าวแก่คนทั้งปวงผู้เฉลียวฉลาดซึ่งเราได้บันดาลให้เขามีจิตใจอันประกอบด้วยสติปัญญานั้น ให้เขาทําเครื่องยศสําหรับสถาปนาอาโรนให้ปรนนิบัติเราในตําแหน่งปุโรหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 4, 'ให้เขาทําเครื่องยศดังต่อไปนี้คือทับทรวง เสื้อเอโฟด เสื้อคลุม เสื้อปัก ผ้ามาลาและรัดประคด และให้เขาทําเครื่องยศบริสุทธิ์สําหรับอาโรนพี่ชายของเจ้าและบุตรชายของเขา เพื่อจะให้ปรนนิบัติเราในตําแหน่งปุโรหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 5, 'ให้เขาเหล่านั้นรับเอาทองคํา ด้ายสีฟ้า สีม่วง สีแดงเข้ม และผ้าป่านเนื้อละเอียด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 6, 'ให้เขาทําเอโฟดด้วยทองคํา ด้วยด้ายสีฟ้า สีม่วง สีแดงเข้มและผ้าป่านเนื้อละเอียด ตัดด้วยฝีมือช่างออกแบบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 7, 'แถบที่ผูกบ่าของเอโฟดนั้น ให้ติดกับริมตอนบนทั้งสองชิ้น เพื่อจะติดเป็นอันเดียวกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 8, 'รัดประคดทออย่างประณีต สําหรับคาดทับเอโฟด ให้ทําด้วยฝีมืออย่างเดียวกัน และใช้วัตถุอย่างเดียวกับเอโฟด คือทําด้วยทองคํา ด้ายสีฟ้า สีม่วง สีแดงเข้ม และผ้าป่านเนื้อละเอียด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 9, 'แล้วให้ใช้พลอยสีน้ําข้าวสองแผ่น สําหรับจารึกชื่อบุตรของอิสราเอลไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 10, 'ที่พลอยแผ่นหนึ่งให้จารึกชื่อหกชื่อ และแผ่นที่สองก็ให้จารึกชื่อไว้อีกหกชื่อที่เหลืออยู่ตามกําเนิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 11, 'ให้ช่างแกะจารึกชื่อเหล่าบุตรอิสราเอลไว้ที่พลอยทั้งสองแผ่นนั้น เช่นอย่างแกะตราแล้วฝังไว้บนกระเปาะทองคําซึ่งมีลวดลายละเอียด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 12, 'พลอยทั้งสองแผ่นนั้นให้ติดไว้กับเอโฟดบนบ่าทั้งสองข้าง พลอยนั้นจะเป็นที่ระลึกถึงบรรดาบุตรแห่งอิสราเอล และอาโรนจะแบกชื่อเขาทั้งหลายไว้บนบ่าทั้งสองเฉพาะพระพักตร์พระเยโฮวาห์เป็นที่ระลึก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 13, 'เจ้าจงทํากระเปาะทองคํามีลวดลายละเอียด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 14, 'กับทําสร้อยสองสายด้วยทองคําบริสุทธิ์ เป็นสร้อยถักเกลียวแล้วติดไว้ที่กระเปาะนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 15, 'จงทําทับทรวงแห่งการพิพากษา ด้วยฝีมือช่างออกแบบฝีมือเหมือนทําเอโฟดคือทําด้วยทองคํา ด้ายสีฟ้า สีม่วง สีแดงเข้มและผ้าป่านเนื้อละเอียด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 16, 'ให้ทําทับทรวงเป็นรูปสี่เหลี่ยมจัตุรัส พับทบกลาง ยาวคืบหนึ่ง กว้างคืบหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 17, 'จงฝังพลอยสี่แถวบนทับทรวงนั้น แถวที่หนึ่งฝังทับทิม บุษราคัมและพลอยสีแดงเข้ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 18, 'แถวที่สองฝังมรกต ไพทูรย์ และเพชร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 19, 'แถวที่สามฝังนิล โมรา และพลอยสีม่วง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 20, 'แถวที่สี่ฝังพลอยเขียว พลอยสีน้ําข้าวและหยก พลอยทั้งหมดนี้ให้ฝังในลวดลายอันละเอียดที่ทําด้วยทองคํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 21, 'พลอยเหล่านั้นให้มีชื่อเหล่าบุตรอิสราเอลสิบสองชื่อจารึกไว้เหมือนแกะตรา จะมีชื่อตระกูลทุกตระกูลตามลําดับสิบสองตระกูล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 22, 'และเจ้าจงทําสร้อยถักเกลียวด้วยทองคําบริสุทธิ์สําหรับทับทรวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 23, 'และเจ้าจงทําห่วงทองคําสองห่วงติดไว้ที่มุมบนทั้งสองของทับทรวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 24, 'ส่วนสร้อยที่ทําด้วยทองคํานั้น ให้เกี่ยวด้วยห่วงที่มุมทับทรวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 25, 'และปลายสร้อยอีกสองข้าง ให้ติดกับกระเปาะที่มีลวดลายละเอียดทั้งสอง ให้ติดไว้ข้างหน้าที่แถบยึดเอโฟดทั้งสองข้างบนบ่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 26, 'จงทําห่วงทองคําสองอันติดไว้ที่มุมล่างทั้งสองข้างของทับทรวงข้างในที่ติดเอโฟด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 27, 'จงทําห่วงสองอันด้วยทองคําใส่ไว้ริมเอโฟดเบื้องหน้า ใต้แถบที่ตะเข็บเหนือรัดประคดซึ่งทอด้วยฝีมือประณีตของเอโฟด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 28, 'ให้ผูกทับทรวงนั้นติดกับเอโฟดด้วย ใช้ด้ายถักสีฟ้าร้อยผูกที่ห่วง ให้ทับทรวงทับรัดประคดที่ทําด้วยฝีมือประณีตของเอโฟด เพื่อมิให้ทับทรวงหลุดไปจากเอโฟด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 29, 'อาโรนจึงจะมีชื่อเหล่าบุตรอิสราเอลจารึกไว้ที่ทับทรวงแห่งการพิพากษาติดไว้ที่หัวใจของตน ให้เป็นที่ระลึกต่อพระพักตร์พระเยโฮวาห์เสมอ เมื่อเขาเข้าไปในที่บริสุทธิ์นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 30, 'จงใส่อูริมและทูมมิมไว้ในทับทรวงแห่งการพิพากษา และของสองสิ่งนี้จะอยู่ที่หัวใจของอาโรนเมื่อเข้าเฝ้าพระเยโฮวาห์ อาโรนจะรับภาระการพิพากษาเหล่าบุตรอิสราเอลไว้ที่หัวใจของตนเสมอเฉพาะพระพักตร์พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 31, 'เจ้าจงทําเสื้อคลุมให้เข้าชุดกับเอโฟดด้วยผ้าสีฟ้าล้วน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 32, 'ให้ทําช่องคอกลางผืนเสื้อ แล้วขลิบรอบคอด้วยผ้าทอ เช่นเดียวกับคอเสื้อทหาร เพื่อจะมิให้ขาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 33, 'ที่ชายล่างของเสื้อคลุมให้ปักรูปทับทิม ใช้ด้ายสีฟ้า สีม่วง สีแดงเข้มรอบชายเสื้อ และติดลูกพรวนทองคําสลับกับผลทับทิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 34, 'ลูกพรวนทองคําลูกหนึ่ง ผลทับทิมผลหนึ่ง ลูกพรวนทองคําอีกลูกหนึ่ง ผลทับทิมอีกผลหนึ่งรอบชายล่างของเสื้อคลุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 35, 'อาโรนจะสวมเสื้อตัวนั้นเมื่อทํางานปรนนิบัติ และจะได้ยินเสียงลูกพรวนเมื่อเข้าเฝ้าพระเยโฮวาห์ในที่บริสุทธิ์ และเมื่อเดินออกมา ด้วยเกรงว่าเขาจะต้องตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 36, 'เจ้าจงทําแผ่นทองคําบริสุทธิ์จารึกคําว่า ‘บริสุทธิ์แด่พระเยโฮวาห์’ ไว้เหมือนอย่างแกะตรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 37, 'และเจ้าจงเอาด้ายถักสีฟ้า ผูกแผ่นทองคํานั้นไว้บนมาลาให้อยู่ที่ข้างมาลาด้านหน้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 38, 'แผ่นทองคํานั้นจะอยู่ที่หน้าผากของอาโรน และอาโรนจะรับความชั่วช้าอันเกิดแก่ชนชาติอิสราเอลเนื่องจากของถวายอันบริสุทธิ์ ซึ่งนํามาชําระให้เป็นของถวายอันบริสุทธิ์ และแผ่นทองคํานั้นให้อยู่ที่หน้าผากของอาโรนเสมอ เพื่อสิ่งของเหล่านั้นจะเป็นที่โปรดปรานต่อพระพักตร์พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 39, 'จงทอเสื้อให้เป็นลวดลาย ด้วยป่านเนื้อละเอียด ส่วนผ้ามาลานั้น จงทําด้วยผ้าป่านเนื้อละเอียด และทํารัดประคดด้วยฝีมือช่างด้ายสี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 40, 'จงทําเสื้อ รัดประคดและมาลาสําหรับบุตรชายทั้งหลายของอาโรนให้สมเกียรติและงดงาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 41, 'จงแต่งอาโรนพี่ชายของเจ้าและบุตรชายทั้งหลายของเขาด้วยเครื่องยศ แล้วเจิมและสถาปนาและชําระเขาให้บริสุทธิ์ เพื่อจะให้ปรนนิบัติเราในตําแหน่งปุโรหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 42, 'จงเย็บกางเกงให้เขาเหล่านั้นด้วยผ้าป่านเพื่อจะปกปิดกายที่เปลือยของเขา ให้ยาวตั้งแต่เอวจนถึงต้นขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 43, 'ให้อาโรนกับบุตรชายทั้งหลายของเขาสวมเมื่อเข้าไปในพลับพลาแห่งชุมนุม และเมื่อเข้าใกล้แท่นจะปรนนิบัติ ณ ที่บริสุทธิ์ เกลือกว่าเขาจะก่อความชั่วช้าและถึงตาย เรื่องนี้ให้เป็นกฎเกณฑ์เนืองนิตย์ที่เขาและเชื้อสายของเขาที่มาภายหลังเขาจะต้องปฏิบัติตาม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 1, '“ต่อไปนี้เป็นการซึ่งเจ้าควรกระทําเพื่อชําระตัวเขาทั้งหลายให้บริสุทธิ์ เพื่อเขาจะปรนนิบัติเราในตําแหน่งปุโรหิต คือจงเอาวัวหนุ่มตัวหนึ่งและแกะตัวผู้สองตัวซึ่งปราศจากตําหนิ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 2, 'ขนมปังไร้เชื้อ ขนมไร้เชื้อคลุกน้ํามันและขนมแผ่นบางไร้เชื้อทาน้ํามัน ขนมเหล่านี้จงทําด้วยยอดแป้งข้าวสาลี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 3, 'แล้วจงใส่ขนมปังต่างๆเหล่านั้นไว้ในกระบุงเดียวกัน จงนํามาในกระบุงพร้อมกับวัวตัวผู้ และลูกแกะตัวผู้สองตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 4, 'จงนําอาโรนและบุตรชายทั้งหลายของเขามาที่ประตูพลับพลาแห่งชุมนุม แล้วจงชําระตัวเขาทั้งหลายด้วยน้ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 5, 'จงสวมเครื่องยศให้อาโรน คือเสื้อในกับเสื้อเอโฟด กับเอโฟดและทับทรวง และเอารัดประคดที่ทอด้วยฝีมือประณีต สําหรับใช้กับเอโฟดนั้นคาดเอวไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 6, 'จงสวมมาลาที่ศีรษะของอาโรน และจงสวมมงกุฎบริสุทธิ์ทับมาลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 7, 'จงเอาน้ํามันเจิมเทลงบนศีรษะของเขา และเจิมตั้งเขาไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 8, 'จงนําบุตรชายทั้งหลายของเขามาและสวมเสื้อให้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 9, 'แล้วจงเอารัดประคดคาดเอวเขาไว้ ทั้งตัวอาโรนเองและบุตรชายของเขา และคาดมาลาให้เขา แล้วเขาก็จะรับตําแหน่งเป็นปุโรหิตตามกฎเกณฑ์เนืองนิตย์ ดังนี้แหละ เจ้าจงสถาปนาอาโรนและบุตรชายทั้งหลายของเขาไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 10, 'เจ้าจงนําวัวตัวผู้มาที่หน้าพลับพลาแห่งชุมนุม ให้อาโรนกับบุตรชายของเขาเอามือวางลงบนหัววัวตัวผู้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 11, 'แล้วจงฆ่าวัวตัวผู้นั้นต่อพระพักตร์พระเยโฮวาห์ที่ประตูพลับพลาแห่งชุมนุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 12, 'จงเอานิ้วมือจุ่มเลือดวัวตัวผู้นั้น ทาไว้ที่เชิงงอนริมแท่นบ้าง ส่วนเลือดที่เหลือทั้งหมดจงเทไว้ที่เชิงแท่นบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 13, 'เจ้าจงเอาไขมันทั้งหมดที่หุ้มเครื่องใน พังผืดที่ติดอยู่กับตับและไตทั้งสองกับไขมันที่ติดไตนั้นมาเผาบนแท่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 14, 'แต่เนื้อกับหนัง และมูลของวัวตัวผู้นั้นจงเผาไฟเสียข้างนอกค่าย ทั้งนี้เป็นเครื่องบูชาไถ่บาป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 15, 'เจ้าจงนําแกะผู้ตัวหนึ่งมาให้อาโรนกับบุตรชายเขาเอามือของตนวางบนหัวแกะตัวผู้นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 16, 'แล้วจงฆ่าแกะตัวนั้นเสีย เอาเลือดพรมรอบๆแท่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 17, 'จงชําแหละแกะตัวนั้นออกเป็นท่อนๆและเครื่องในกับขาจงล้างน้ําวางไว้กับเนื้อและหัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 18, 'แล้วจงเผาแกะตัวนั้นทั้งตัวบนแท่นบูชา เป็นเครื่องเผาบูชาถวายแด่พระเยโฮวาห์ เป็นกลิ่นพอพระทัย เป็นเครื่องบูชาด้วยไฟถวายแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 19, 'เจ้าจงนําแกะตัวผู้อีกตัวหนึ่งมา แล้วให้อาโรนกับบุตรชายเขาเอามือของตนวางบนหัวแกะผู้ตัวนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 20, 'แล้วท่านจงฆ่าแกะตัวนั้นเสีย เอาเลือดส่วนหนึ่งเจิมที่ปลายใบหูข้างขวาของอาโรน และที่ปลายใบหูข้างขวาของบุตรชายของเขาทุกคน และที่หัวแม่มือข้างขวา และที่หัวแม่เท้าข้างขวาของเขาบ้าง แล้วจงเอาเลือดที่เหลือพรมรอบๆแท่นบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 21, 'จงเอาเลือดส่วนหนึ่งที่อยู่บนแท่นและน้ํามันเจิมนั้นพรมอาโรนและเครื่องยศของเขา จงพรมบุตรชายทั้งหลายของเขา และเครื่องยศของบุตรชายเหล่านั้นด้วย อาโรนและเครื่องยศของเขาจะบริสุทธิ์รวมทั้งบุตรชายของเขาและเครื่องยศของเขาด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 22, 'เจ้าจงเอาไขมันแกะตัวผู้และหางที่เป็นไขมัน กับไขมันที่ติดเครื่องใน และพังผืดที่ติดอยู่กับตับ กับไตทั้งสองและไขมันที่ติดอยู่กับไต กับโคนขาข้างขวาด้วย เพราะเป็นแกะใช้สําหรับการสถาปนา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 23, 'กับขนมปังก้อนหนึ่งและขนมปังคลุกน้ํามันแผ่นหนึ่ง และขนมปังบางแผ่นหนึ่งจากกระบุงขนมปังไร้เชื้อ ซึ่งอยู่ต่อพระพักตร์พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 24, 'แล้วจงวางสิ่งเหล่านั้นไว้ในมือของอาโรน และในมือบุตรชายของเขา ให้แกว่งไปแกว่งมาเป็นเครื่องบูชาแกว่งถวายต่อพระพักตร์พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 25, 'แล้วจงรับสิ่งเหล่านี้จากมือของเขานําไปเผาบนแท่นบูชาเป็นเครื่องเผาบูชา เป็นกลิ่นที่พอพระทัยต่อพระพักตร์พระเยโฮวาห์ เป็นเครื่องบูชาด้วยไฟถวายแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 26, 'จงเอาเนื้อที่อกแกะตัวผู้ซึ่งเป็นแกะสถาปนาอาโรน แล้วให้แกว่งไปแกว่งมาเป็นเครื่องบูชาแกว่งถวายต่อพระพักตร์พระเยโฮวาห์ และนั่นจะเป็นส่วนของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 27, 'และจงเอาเนื้อที่อกแกะตัวผู้ซึ่งเป็นเครื่องบูชาแกว่งนั้นไว้ และเนื้อโคนขาอันเป็นส่วนยกให้แก่ปุโรหิตซึ่งแกว่งไปแกว่งมา และซึ่งเป็นของถวายจากแกะใช้สําหรับการสถาปนา ด้วยเป็นส่วนของอาโรนและบุตรชายเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 28, 'นั่นแหละเป็นส่วนซึ่งอาโรนและบุตรชายเขาจะได้รับจากชนชาติอิสราเอลเป็นกฎเกณฑ์เนืองนิตย์ เพราะเป็นส่วนที่ยกให้แก่ปุโรหิต และชนชาติอิสราเอลจะยกให้จากเครื่องสันติบูชา เป็นเครื่องบูชาของเขาถวายแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 29, 'เครื่องยศบริสุทธิ์ของอาโรนจะเป็นของบุตรชายของเขาต่อๆไป ให้เขาสวมเมื่อเขารับการเจิม และได้รับการสถาปนาไว้ในตําแหน่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 30, 'จงให้บุตรชายซึ่งจะเป็นปุโรหิตแทนเขานั้นสวมเครื่องยศเหล่านั้นครบเจ็ดวัน ขณะที่เขามายังพลับพลาแห่งชุมนุมเพื่อปรนนิบัติในที่บริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 31, 'จงต้มเนื้อแกะตัวผู้สําหรับการสถาปนาในที่บริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 32, 'แล้วให้อาโรนกับบุตรชายของเขากินเนื้อแกะตัวผู้นั้น และขนมปังซึ่งอยู่ในกระบุงที่ประตูพลับพลาแห่งชุมนุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 33, 'ให้เขากินของซึ่งนํามาบูชาลบมลทิน เพื่อจะสถาปนาและชําระเขาเหล่านั้นให้บริสุทธิ์ แต่คนภายนอกอย่าให้รับประทาน เพราะเป็นของบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 34, 'และถ้าแม้เนื้อที่ใช้ในพิธีสถาปนา และขนมปังนั้นยังเหลืออยู่จนรุ่งเช้าบ้าง ก็ให้เผาส่วนที่เหลือนั้นด้วยไฟเสีย อย่าให้รับประทานเพราะเป็นของบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 35, 'ดังนั้นแหละ เจ้าจงกระทําให้แก่อาโรน และบุตรชายเขาตามคําที่เราได้บัญชาเจ้าไว้ จงทําพิธีสถาปนาเขาให้ครบเจ็ดวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 36, 'จงนําวัวผู้ตัวหนึ่งมาถวายทุกๆวัน เป็นเครื่องบูชาไถ่บาป เพื่อทําการลบมลทินและจงชําระแท่นบูชา ด้วยทําการลบมลทินของแท่นนั้น จงเจิมแท่นนั้นเพื่อจะชําระให้บริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 37, 'จงทําการลบมลทินแท่นนั้นครบเจ็ดวัน และชําระแท่นนั้นให้บริสุทธิ์ แล้วแท่นนั้นจะบริสุทธิ์ที่สุด สิ่งหนึ่งสิ่งใดที่ถูกต้องแท่นนั้นก็จะบริสุทธิ์ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 38, 'ต่อไปนี้เป็นสิ่งซึ่งเจ้าต้องถวายบนแท่นนั้นทุกวันเสมอไป คือลูกแกะสองตัว อายุหนึ่งขวบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 39, 'จงนําลูกแกะตัวหนึ่งมาบูชาเวลาเช้า และนําลูกแกะอีกตัวหนึ่งมาบูชาเวลาเย็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 40, 'พร้อมกับลูกแกะตัวที่หนึ่งนั้น จงถวายยอดแป้งหนึ่งในสิบเอฟาห์คลุกกับน้ํามันที่คั้นไว้นั้นหนึ่งในสี่ฮิน และน้ําองุ่นหนึ่งในสี่ฮินคู่กัน เป็นเครื่องดื่มบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 41, 'จงถวายลูกแกะอีกตัวหนึ่งนั้นในเวลาเย็น ถวายธัญญบูชาและเครื่องดื่มบูชาคู่กันด้วย เหมือนอย่างในเวลาเช้า ให้เป็นกลิ่นพอพระทัย เป็นเครื่องบูชาด้วยไฟถวายแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 42, 'นี่จะเป็นเครื่องเผาบูชาเนืองนิตย์ตลอดชั่วอายุของเจ้า ที่ประตูพลับพลาแห่งชุมนุมเฉพาะพระพักตร์พระเยโฮวาห์ ที่ที่เราจะพบเจ้าทั้งหลายและสนทนากับเจ้าที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 43, 'ที่นั่นเราจะพบกับชนชาติอิสราเอล และพลับพลานั้นจะรับการชําระให้บริสุทธิ์ด้วยสง่าราศีของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 44, 'เราจะชําระพลับพลาแห่งชุมนุมและแท่นบูชาไว้เป็นที่บริสุทธิ์ และเราจะชําระอาโรนและบุตรชายเขาให้บริสุทธิ์ด้วย เพื่อเขาจะปรนนิบัติเราในตําแหน่งปุโรหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 45, 'เราจะสถิตอยู่ท่ามกลางชนชาติอิสราเอล และจะเป็นพระเจ้าของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 46, 'เขาจะรู้ว่าเราคือพระเยโฮวาห์พระเจ้าของเขา ผู้ได้นําเขาออกจากแผ่นดินอียิปต์ เพื่อเราจะสถิตอยู่ท่ามกลางเขาทั้งหลาย เราคือพระเยโฮวาห์พระเจ้าของเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 1, '“เจ้าจงสร้างแท่นสําหรับเผาเครื่องหอม จงทําแท่นนั้นด้วยไม้กระถินเทศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 2, 'ให้ยาวศอกหนึ่ง กว้างศอกหนึ่ง เป็นรูปสี่เหลี่ยมจัตุรัส และสูงสองศอก เชิงงอนมุมแท่นนั้นให้เป็นไม้ท่อนเดียวกับแท่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 3, 'และจงหุ้มแท่นด้วยทองคําบริสุทธิ์ ทั้งด้านบนและด้านข้างทุกด้าน และเชิงงอนด้วย และจงทํากระจังทองคําล้อมรอบแท่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 4, 'จงทําห่วงทองคําสองห่วง ติดไว้ใต้กระจังด้านละห่วงตรงกันข้าม ห่วงนั้นสําหรับสอดใส่ไม้คานหาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 5, 'ไม้คานหามนั้นจงทําด้วยไม้กระถินเทศหุ้มด้วยทองคํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 6, 'จงตั้งแท่นนั้นไว้ข้างนอกม่านซึ่งอยู่ใกล้หีบพระโอวาท ข้างหน้าพระที่นั่งกรุณาซึ่งอยู่เหนือหีบพระโอวาท ที่ที่เราจะพบกับเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 7, 'จงให้อาโรนเผาเครื่องหอมบนแท่นนั้นทุกเวลาเช้า เมื่อเขาแต่งประทีปก็จงเผาเครื่องหอมด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 8, 'และในเวลาเย็นเมื่ออาโรนจุดประทีป ให้เผาเครื่องหอมบนแท่น เป็นเครื่องหอมเนืองนิตย์ต่อพระพักตร์พระเยโฮวาห์ตลอดชั่วอายุของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 9, 'แต่เครื่องหอมอย่างที่ห้าม อย่าได้เผาบนแท่นนั้นเลย หรือเผาเครื่องเผาบูชา หรือเครื่องธัญญบูชา หรือเทเครื่องดื่มบูชาบนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 10, 'ให้อาโรนทําการบูชาไถ่บาปที่เชิงงอนปีละหนด้วยเลือดของเครื่องบูชาไถ่บาปลบมลทิน ให้เขาทําการลบมลทินแท่นนั้นปีละหนตลอดชั่วอายุของเจ้า แท่นนั้นจะบริสุทธิ์ที่สุดแด่พระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 11, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 12, '“เมื่อเจ้าจะจดสํามะโนครัวชนชาติอิสราเอลจงให้เขาต่างนําทรัพย์สินมาถวายพระเยโฮวาห์ เป็นค่าไถ่ชีวิต เมื่อเจ้านับจํานวนเขา เพื่อจะมิได้เกิดภัยพิบัติขึ้นในหมู่พวกเขาเมื่อเจ้านับเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 13, 'ทุกคนที่ขึ้นทะเบียนสํามะโนครัว จะต้องถวายของอย่างนี้ คือเงินครึ่งเชเขลตามเชเขลของสถานบริสุทธิ์ (เชเขลหนึ่งมียี่สิบเก-ราห์) ครึ่งเชเขลเป็นเงินถวายแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 14, 'ทุกๆคนที่ขึ้นทะเบียนสํามะโนครัว อายุตั้งแต่ยี่สิบปีขึ้นไป ให้นําเงินมาถวายพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 15, 'เมื่อเจ้าทั้งหลายนําเงินมาถวายพระเยโฮวาห์ เพื่อจะได้ไถ่ชีวิตของเจ้าทั้งหลายนั้น สําหรับคนมั่งมีก็อย่าถวายเกินและสําหรับคนจนก็อย่าถวายน้อยกว่าครึ่งเชเขล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 16, 'จงเก็บเงินค่าไถ่จากชนชาติอิสราเอล และจงกําหนดเงินไว้ใช้จ่ายในพลับพลาแห่งชุมนุม เพื่อเป็นที่ระลึกแก่ชนชาติอิสราเอลต่อพระพักตร์พระเยโฮวาห์ สําหรับการไถ่ชีวิตของเจ้าทั้งหลาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 17, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 18, '“เจ้าจงทําขันทองเหลืองและพานรองขันทองเหลืองด้วย สําหรับล้างชําระ จงตั้งขันนั้นไว้ระหว่างพลับพลาแห่งชุมนุมและแท่นบูชา แล้วจงตักน้ําใส่ไว้ในขันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 19, 'ให้อาโรนและบุตรชายของเขาใช้ล้างมือและเท้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 20, 'เมื่อเขาจะเข้าไปในพลับพลาแห่งชุมนุม เขาจะต้องชําระด้วยน้ําเพื่อจะไม่ตาย หรือเมื่อเขาเข้ามาใกล้แท่นทําการปรนนิบัติ เพื่อถวายเครื่องบูชาด้วยไฟแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 21, 'จงให้เขาล้างมือและเท้าเพื่อจะมิได้ตาย และให้เป็นกฎเกณฑ์เนืองนิตย์ประจําตัวเขา คืออาโรนกับเชื้อสายของเขาตลอดชั่วอายุของเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 22, 'ยิ่งกว่านั้น พระเยโฮวาห์ยังตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 23, '“จงเอาเครื่องเทศพิเศษคือมดยอบน้ํา ซึ่งหนักห้าร้อยเชเขล และอบเชยหอมครึ่งจํานวนคือสองร้อยห้าสิบเชเขล และตะไคร้สองร้อยห้าสิบเชเขล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 24, 'และการบูรห้าร้อยเชเขล ตามเชเขลของสถานบริสุทธิ์ และน้ํามันมะกอกเทศหนึ่งฮิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 25, 'เจ้าจงเอาสิ่งเหล่านี้มาทําเป็นน้ํามันเจิมอันบริสุทธิ์ เป็นน้ําหอมปรุงตามศิลปช่างปรุงน้ํามันนั้น จะเป็นน้ํามันเจิมอันบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 26, 'แล้วจงเอาน้ํามันเจิมพลับพลาแห่งชุมนุมและหีบพระโอวาทด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 27, 'โต๊ะและเครื่องใช้ประจําโต๊ะ คันประทีปกับเครื่องใช้ประจําคันประทีป และแท่นเผาเครื่องหอม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 28, 'แท่นเครื่องเผาบูชาและเครื่องใช้ประจําแท่น ทั้งขันและพานรองขันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 29, 'จงชําระให้บริสุทธิ์ เพื่อจะได้บริสุทธิ์ที่สุด และอะไรมาถูกสิ่งเหล่านั้นก็บริสุทธิ์ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 30, 'อนึ่งจงเจิมอาโรนและบุตรชายเขา และสถาปนาเขาไว้ให้ปรนนิบัติเราในตําแหน่งปุโรหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 31, 'ท่านจงกล่าวแก่ชนชาติอิสราเอลว่า ‘นี่แหละ เป็นน้ํามันเจิมอันบริสุทธิ์สําหรับเราตลอดชั่วอายุของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 32, 'น้ํามันนี้อย่าให้เจิมคนสามัญเลย และอย่าผสมทําน้ํามันอื่นเหมือนอย่างน้ํามันนี้ น้ํามันนี้เป็นน้ํามันบริสุทธิ์ เจ้าทั้งหลายจงถือไว้เป็นบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 33, 'ผู้ใดจะผสมน้ํามันอย่างนี้ หรือผู้ใดจะใช้ชโลมคนต่างด้าว ผู้นั้นจะถูกตัดขาดจากชนชาติของเขา’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 34, 'พระเยโฮวาห์ตรัสกับโมเสสว่า “จงเอาเครื่องเทศคือยางไม้ ชะมด และมหาหิงค์ ผสมกับกํายานบริสุทธิ์ ให้เท่าๆกันทุกอย่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 35, 'จงผสมเครื่องหอมปรุงตามศิลปช่างปรุงเจือด้วยเกลือให้เป็นของบริสุทธิ์และศักดิ์สิทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 36, 'จงเอาส่วนหนึ่งมาตําให้ละเอียด และวางอีกส่วนหนึ่งไว้หน้าหีบพระโอวาทในพลับพลาแห่งชุมนุมที่เราจะพบกับเจ้า เครื่องหอมนั้นเจ้าจงถือว่าบริสุทธิ์ที่สุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 37, 'เครื่องหอมที่เจ้ากระทําตามส่วนที่ผสมนั้น เจ้าอย่าทําใช้เอง ให้ถือว่านี่เป็นเครื่องหอมบริสุทธิ์แด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 38, 'ผู้ใดทําเครื่องเช่นนี้ไว้ใช้สูดดม ผู้นั้นต้องถูกตัดขาดจากชนชาติของเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 1, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 2, '“ดูซี เราได้ออกชื่อเบซาเลล ผู้เป็นบุตรชายอุรี ผู้เป็นบุตรชายเฮอร์แห่งตระกูลยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 3, 'และได้ให้เขาประกอบด้วยพระวิญญาณของพระเจ้าคือให้เขามีสติปัญญา ความเข้าใจและความรู้ในวิชาการทุกอย่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 4, 'จะได้คิดออกแบบอย่างประณีตในการทําเครื่องทองคํา เงิน และทองเหลือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 5, 'เจียระไนพลอยต่างๆสําหรับฝังในกระเปาะและแกะสลักไม้ได้ คือประกอบวิชาการทุกอย่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 6, 'และดูเถิด เราได้ตั้งผู้ช่วยอีกคนหนึ่ง ชื่อโอโฮลีอับ บุตรชายอาหิสะมัคแห่งตระกูลดาน และสําหรับคนทั้งปวงผู้เฉลียวฉลาดเราได้บันดาลให้เขามีจิตใจอันประกอบด้วยสติปัญญา เพื่อเขาจะได้ทําสิ่งสารพัดซึ่งเราได้สั่งเจ้าไว้นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 7, 'คือพลับพลาแห่งชุมนุม หีบพระโอวาทและพระที่นั่งกรุณา ซึ่งอยู่บนหีบพระโอวาท และเครื่องใช้ทุกอย่างสําหรับพลับพลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 8, 'โต๊ะกับเครื่องใช้สําหรับโต๊ะ คันประทีปบริสุทธิ์กับเครื่องใช้สําหรับคันประทีป และแท่นเครื่องหอม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 9, 'แท่นเครื่องเผาบูชากับเครื่องใช้ประจําแท่น ขันกับพานรองขันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 10, 'เสื้อยศเย็บด้วยฝีมือประณีต คือเสื้อยศอันบริสุทธิ์ของอาโรนปุโรหิต และเสื้อยศของบุตรชายของเขา เพื่อจะได้สวมปฏิบัติในตําแหน่งปุโรหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 11, 'และน้ํามันเจิมกับเครื่องหอมสําหรับที่บริสุทธิ์ ที่เราบัญชาเจ้านั้นให้เขากระทําตามทุกประการ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 12, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 13, '“จงสั่งชนชาติอิสราเอลว่า ‘เจ้าทั้งหลายจงรักษาวันสะบาโตของเราไว้ เพราะนี่จะเป็นหมายสําคัญระหว่างเรากับเจ้าตลอดชั่วอายุของเจ้า เพื่อเจ้าจะได้รู้ว่าเราคือพระเยโฮวาห์ ผู้ได้กระทําเจ้าให้บริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 14, 'เหตุฉะนี้ เจ้าทั้งหลายจงรักษาวันสะบาโตไว้ เพราะเป็นวันบริสุทธิ์สําหรับเจ้า ทุกคนที่กระทําให้วันนั้นเป็นมลทินจะต้องถูกประหารให้ตายเป็นแน่ เพราะผู้ใดก็ตามทําการงานในวันนั้น ผู้นั้นต้องถูกตัดขาดจากท่ามกลางชนชาติของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 15, 'จงทํางานแต่ในกําหนดหกวัน แต่ในวันที่เจ็ดเป็นวันสะบาโต เป็นวันหยุดพักสงบ เป็นวันบริสุทธิ์แด่พระเยโฮวาห์ ผู้ใดทํางานในวันสะบาโตนั้นต้องถูกลงโทษถึงตายเป็นแน่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 16, 'เหตุฉะนี้ ชนชาติอิสราเอลจงรักษาวันสะบาโตไว้ คือถือวันสะบาโตตลอดชั่วอายุของเขาเป็นพันธสัญญาเนืองนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 17, 'เป็นหมายสําคัญระหว่างเรากับชนชาติอิสราเอลว่า ในหกวันพระเยโฮวาห์ได้ทรงสร้างฟ้าสวรรค์และแผ่นดินโลก แต่ในวันที่เจ็ดพระองค์ได้ทรงงดการงานไว้ และได้ทรงหย่อนพระทัยในวันนั้น’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 18, 'เมื่อพระองค์ตรัสแก่โมเสสบนภูเขาซีนายเสร็จแล้ว พระองค์ได้ประทานแผ่นพระโอวาทสองแผ่น เป็นแผ่นศิลาจารึกด้วยนิ้วพระหัตถ์ของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 1, 'เมื่อพลไพร่เห็นโมเสสล่าช้าอยู่ ไม่ลงมาจากภูเขาจึงได้พากันมาหาอาโรน เรียนว่า “ลุกขึ้น ขอท่านสร้างพระให้แก่พวกข้าพเจ้า ซึ่งจะนําพวกข้าพเจ้าไป ด้วยว่าโมเสสคนนี้ที่ได้นําข้าพเจ้าออกมาจากประเทศอียิปต์เป็นอะไรไปเสียแล้ว ข้าพเจ้าไม่ทราบ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 2, 'ฝ่ายอาโรนได้กล่าวแก่เขาว่า “จงปลดตุ้มหูทองคําออกจากหูภรรยา และหูบุตรชายหญิงของเจ้าทั้งหลายแล้วนํามาให้เราเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 3, 'พลไพร่ทั้งปวงจึงได้ปลดตุ้มหูทองคําจากหูของตนมามอบให้กับอาโรน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 4, 'เมื่ออาโรนได้รับทองคําจากมือเขาแล้ว จึงใช้เครื่องมือสลักหล่อรูปเป็นวัวหนุ่ม แล้วเขาทั้งหลายประกาศว่า “โอ อิสราเอล สิ่งเหล่านี้แหละเป็นพระของเจ้า ซึ่งนําเจ้าออกจากแผ่นดินอียิปต์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 5, 'เมื่ออาโรนได้ยินดังนั้นแล้วจึงสร้างแท่นบูชาไว้ตรงหน้ารูปวัวหนุ่มนั้น แล้วอาโรนประกาศว่า “พรุ่งนี้จะเป็นวันเทศกาลเลี้ยงถวายพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 6, 'ครั้นรุ่งขึ้นเขาตื่นขึ้นแต่เช้ามืด ถวายเครื่องเผาบูชา และนําเครื่องสันติบูชามา พลไพร่ก็นั่งลงกินและดื่มแล้วก็ลุกขึ้นเล่นสนุกกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 7, 'ฝ่ายพระเยโฮวาห์ตรัสกับโมเสสว่า “เจ้าลงไปเถิด ด้วยว่าชนชาติของเจ้าซึ่งเจ้าได้นําออกจากแผ่นดินอียิปต์นั้น ได้ทําความเสื่อมเสียมากแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 8, 'เขาได้หันเหออกจากทางซึ่งเราสั่งเขาไว้อย่างรวดเร็ว คือหล่อรูปวัวขึ้นรูปหนึ่งสําหรับตน และกราบไหว้รูปนั้น และถวายสัตวบูชาแก่รูปนั้นและกล่าวว่า ‘โอ อิสราเอล สิ่งเหล่านี้แหละเป็นพระของเจ้า ซึ่งนําเจ้าออกจากแผ่นดินอียิปต์’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 9, 'แล้วพระเยโฮวาห์ตรัสกับโมเสสว่า “เราเห็นพลไพร่นี้แล้ว ดูเถิด เขาเป็นชนชาติคอแข็ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 10, 'ฉะนั้นบัดนี้เจ้าจงปล่อยเราตามลําพัง เพื่อความพิโรธของเราจะเดือดพลุ่งขึ้นต่อเขาและเพื่อเราจะผลาญทําลายเขาเสีย ส่วนเจ้าเราจะให้เป็นประชาชาติใหญ่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 11, 'ฝ่ายโมเสสก็วิงวอนกราบทูลพระเยโฮวาห์พระเจ้าของท่านว่า “ข้าแต่พระเยโฮวาห์ ไฉนพระองค์จึงทรงพระพิโรธอย่างแรงกล้าต่อพลไพร่ของพระองค์ ซึ่งพระองค์ทรงนําออกมาจากแผ่นดินอียิปต์ ด้วยฤทธานุภาพอันใหญ่ยิ่ง และด้วยพระหัตถ์อันทรงฤทธิ์ของพระองค์เล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 12, 'เหตุไฉนจะให้ชนชาวอียิปต์กล่าวว่า ‘พระองค์ทรงนําเขาออกมาเพื่อจะทรงทําร้ายเขา เพื่อจะประหารชีวิตเขาที่ภูเขาและทําลายเขาเสียจากพื้นแผ่นดินโลก’ ขอพระองค์ทรงหันกลับเสียจากความพิโรธอันแรงกล้าของพระองค์ และทรงกลับพระทัยอย่าทําอันตรายแก่พลไพร่ของพระองค์เอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 13, 'ขอพระองค์ได้ทรงระลึกถึงอับราฮัม อิสอัค และอิสราเอลผู้รับใช้ของพระองค์ เป็นผู้ซึ่งพระองค์ได้ทรงปฏิญาณด้วยพระองค์เองแก่เขาเหล่านั้นไว้ว่า ‘เราจะให้เชื้อสายของเจ้าทวีขึ้นดุจดวงดาวในท้องฟ้า และแผ่นดินนี้ทั้งหมดซึ่งเราสัญญาไว้แล้ว เราจะยกให้แก่เชื้อสายของเจ้า และเขาจะรับไว้เป็นมรดกตลอดไป’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 14, 'แล้วพระเยโฮวาห์จึงทรงกลับพระทัย มิได้ทรงทําอันตรายอย่างที่พระองค์ทรงดําริว่าจะกระทําแก่พลไพร่ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 15, 'ฝ่ายโมเสสกลับลงมาจากภูเขาถือแผ่นศิลาพระโอวาทมาสองแผ่น ซึ่งจารึกทั้งสองด้าน จารึกทั้งด้านนี้และด้านนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 16, 'แผ่นศิลาเหล่านั้นเป็นงานจากฝีพระหัตถ์ของพระเจ้า และอักษรที่จารึกนั้นเป็นลายพระหัตถ์ของพระเจ้า สลักไว้บนแผ่นศิลานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 17, 'เมื่อโยชูวาได้ยินเสียงพลไพร่อื้ออึงอยู่เขาจึงเรียนโมเสสว่า “ที่ค่ายมีเสียงเหมือนเกิดสงคราม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 18, 'ฝ่ายโมเสสตอบว่า “ที่เราได้ยินมิใช่เสียงอื้ออึงของคนที่มีชัยชนะ และมิใช่เสียงคนที่แพ้ แต่เป็นเสียงคนร้องเพลงกัน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 19, 'ต่อมาพอโมเสสเข้ามาใกล้ค่าย ได้เห็นรูปวัวหนุ่มและคนเต้นรํา โทสะของโมเสสก็เดือดพลุ่งขึ้น ท่านโยนแผ่นศิลาทิ้งตกแตกเสียที่เชิงภูเขานั่นเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 20, 'แล้วท่านเอารูปวัวหนุ่มที่พลไพร่ทําไว้นั้นเผาเสีย และบดเป็นผงโรยลงในน้ํา และบังคับให้ชนชาติอิสราเอลดื่มน้ํานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 21, 'โมเสสจึงถามอาโรนว่า “พลไพร่นี้กระทําอะไรแก่ท่านเล่า ท่านจึงนําบาปอันใหญ่นี้มาสู่พวกเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 22, 'ฝ่ายอาโรนตอบว่า “อย่าให้ความโกรธของเจ้านายของข้าพเจ้าเดือดพลุ่งขึ้นเลย ท่านก็รู้จักพลไพร่พวกนี้แล้วว่า เขาเอนเอียงไปในทางชั่ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 23, 'เขามาร้องขอข้าพเจ้าว่า ‘ขอจงทําพระให้พวกข้าพเจ้า ซึ่งจะนําพวกข้าพเจ้าไป ด้วยว่าโมเสสคนนี้ที่ได้นําพวกข้าพเจ้าออกจากแผ่นดินอียิปต์นั้นเกิดอะไรขึ้นกับเขา ข้าพเจ้าไม่ทราบ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 24, 'แล้วข้าพเจ้าตอบแก่เขาว่า ‘ผู้ใดมีทองคําให้ปลดออกมา’ เขาก็มอบทองคําให้แก่ข้าพเจ้า และข้าพเจ้าจึงโยนลงไปในไฟแล้ววัวนี้ก็ออกมา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 25, 'เมื่อโมเสสเห็นประชาชนแสดงออกถึงการเปลือยเปล่าเสียแล้ว (เพราะว่าอาโรนปล่อยให้เขาเปลือยเปล่าจนน่าละอายท่ามกลางพวกศัตรู)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 26, 'แล้วโมเสสยืนอยู่ที่ประตูค่ายร้องว่า “ผู้ใดอยู่ฝ่ายพระเยโฮวาห์ให้ผู้นั้นมาหาเราเถิด” ฝ่ายลูกหลานของเลวีได้มาหาโมเสสพร้อมกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 27, 'โมเสสจึงกล่าวแก่เขาว่า “พระเยโฮวาห์พระเจ้าของอิสราเอลตรัสสั่งดังนี้ว่า ‘จงเอาดาบสะพายทุกคนแล้วจงไปมาตามประตูต่างๆทั่วค่าย ทุกๆคนจงฆ่าพี่น้องและมิตรสหายและเพื่อนบ้านของตัวเอง’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 28, 'ฝ่ายลูกหลานของเลวีก็ทําตามโมเสสสั่ง และพลไพร่ประมาณสามพันคนตายลงในวันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 29, 'ด้วยโมเสสกล่าวไว้แล้วว่า “ในวันนี้ท่านทั้งหลายจงสถาปนาตัวเองรับใช้พระเยโฮวาห์ จงให้ทุกคนสู้รบกับบุตรชายและพี่น้องของตน เพื่อวันนี้พระองค์จะได้อํานวยพระพรแก่ท่านทั้งหลาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 30, 'ครั้นวันรุ่งขึ้น โมเสสจึงกล่าวแก่พลไพร่ว่า “ท่านทั้งหลายทําบาปอันใหญ่ยิ่ง แต่บัดนี้เราจะขึ้นไปเฝ้าพระเยโฮวาห์ ชะรอยเราจะทําการลบมลทินบาปของท่านได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 31, 'โมเสสจึงกลับไปเฝ้าพระเยโฮวาห์ทูลว่า “โอ พระเจ้าข้า พลไพร่นี้ทําบาปอันใหญ่ยิ่ง เขาทําพระด้วยทองคําสําหรับตัวเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 32, 'แต่บัดนี้ขอพระองค์โปรดยกโทษบาปของเขา ถ้าหาไม่ ขอพระองค์ทรงลบชื่อของข้าพระองค์เสียจากทะเบียนที่พระองค์ทรงจดไว้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 33, 'ฝ่ายพระเยโฮวาห์ตรัสกับโมเสสว่า “ผู้ใดทําบาปต่อเราแล้วเราจะลบชื่อผู้นั้นเสียจากทะเบียนของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 34, 'ฉะนั้นบัดนี้ จงไปเถอะ นําพลไพร่ไปยังที่ซึ่งเราบอกแก่เจ้าแล้ว ดูเถิด ทูตสวรรค์ของเราจะนําหน้าเจ้า แต่ว่าในวันนั้นเมื่อเราจะพิพากษาเขา เราจะลงโทษเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 35, 'ฝ่ายพระเยโฮวาห์ทรงบันดาลให้ภัยพิบัติเกิดขึ้นแก่พลไพร่ เพราะเหตุเขาทํารูปวัวหนุ่มซึ่งอาโรนทํานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 1, 'พระเยโฮวาห์ตรัสกับโมเสสว่า “ไปเถิด จงยกไปจากที่นี่ เจ้ากับพลไพร่ซึ่งเจ้านําขึ้นมาจากแผ่นดินอียิปต์ ไปยังแผ่นดินซึ่งเราปฏิญาณกับอับราฮัม อิสอัค และยาโคบว่า ‘แผ่นดินนั้นเราจะให้แก่เชื้อสายของเจ้า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 2, 'เราจะใช้ทูตสวรรค์องค์หนึ่งนําหน้าเจ้าไป และจะไล่คนคานาอัน คนอาโมไรต์ คนฮิตไทต์ คนเปริสซี คนฮีไวต์ คนเยบุส ออกเสียจากที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 3, 'จงนําไปถึงแผ่นดินซึ่งมีน้ํานมและน้ําผึ้งไหลบริบูรณ์ แต่เราจะไม่ขึ้นไปกับพวกเจ้า เกรงว่าเราจะทําลายล้างพวกเจ้าเสียกลางทาง เพราะว่าเจ้าเป็นชนชาติคอแข็ง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 4, 'เมื่อพลไพร่ได้ยินข่าวร้ายนั้นเขามีความโศกเศร้า และไม่มีผู้ใดใส่เครื่องประดับเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 5, 'เพราะพระเยโฮวาห์ตรัสกับโมเสสว่า “จงกล่าวแก่ชนชาติอิสราเอลว่า ‘เจ้าทั้งหลายเป็นชนชาติคอแข็ง ถ้าเราจะขึ้นไปกับเจ้าเพียงครู่เดียว เราก็จะทําลายล้างเจ้าเสีย ฉะนั้นบัดนี้ จงถอดเครื่องประดับออกเสียเพื่อเราจะรู้ว่า ควรจะกระทําอย่างไรกับเจ้า’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 6, 'ฝ่ายชนชาติอิสราเอลก็ถอดเครื่องประดับออกตอนที่เขาอยู่แถบภูเขาโฮเรบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 7, 'ฝ่ายโมเสสตั้งพลับพลาหลังหนึ่งไว้ข้างนอกไกลจากค่าย และเรียกว่าพลับพลาแห่งชุมนุม ต่อมาทุกคนซึ่งปรารถนาจะเข้าเฝ้าพระเยโฮวาห์ก็ออกไปยังพลับพลาแห่งชุมนุม ซึ่งตั้งอยู่นอกบริเวณค่าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 8, 'และต่อมาเมื่อไรที่โมเสสออกไปยังพลับพลานั้น พลไพร่ทั้งปวงก็จะลุกขึ้นยืนอยู่ที่ประตูเต็นท์ของตน มองดูโมเสสจนท่านเข้าไปในพลับพลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 9, 'ครั้นโมเสสเข้าไปในพลับพลาแล้ว เสาเมฆก็ลอยลงมาตั้งอยู่ที่ประตูพลับพลา แล้วพระเยโฮวาห์ก็ตรัสสนทนากับโมเสส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 10, 'เวลาพลไพร่ทั้งปวงเห็นเสาเมฆนั้นตั้งอยู่ที่ประตูพลับพลาเมื่อไร ทุกคนก็จะลุกขึ้นยืนนมัสการอยู่ที่ประตูเต็นท์ของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 11, 'ดังนี้แหละพระเยโฮวาห์ตรัสกับโมเสสสองต่อสอง เหมือนมิตรสหายสนทนากัน แล้วโมเสสก็กลับไปยังค่าย แต่โยชูวาผู้รับใช้หนุ่ม ผู้เป็นบุตรชายของนูน มิได้ออกไปจากพลับพลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 12, 'โมเสสกราบทูลพระเยโฮวาห์ว่า “ดูเถิด พระองค์ได้ตรัสสั่งข้าพระองค์ว่า ‘จงนําพลไพร่นี้ขึ้นไป’ แต่พระองค์มิได้แจ้งให้ข้าพระองค์ทราบว่า จะใช้ผู้ใดขึ้นไปกับข้าพระองค์ แม้กระนั้นพระองค์ก็ยังตรัสกับข้าพระองค์ว่า ‘เรารู้จักเจ้าตามชื่อของเจ้า และเจ้าก็ได้รับความกรุณาในสายตาของเราด้วย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 13, 'ฉะนั้นบัดนี้ ข้าพระองค์ทูลวิงวอนต่อพระองค์ ถ้าแม้ข้าพระองค์ได้รับพระกรุณาในสายพระเนตรของพระองค์แล้ว ขอทรงโปรดสําแดงพระมรรคาของพระองค์ให้ข้าพระองค์เห็นในกาลบัดนี้ เพื่อข้าพระองค์จะรู้จักพระองค์ แล้วจะรับพระกรุณาในสายพระเนตรของพระองค์ และขอทรงถือว่าชนชาตินี้เป็นพลไพร่ของพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 14, 'ฝ่ายพระองค์ตรัสว่า “เราเองจะไปกับเจ้า และให้เจ้าได้พัก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 15, 'ฝ่ายโมเสสจึงกราบทูลพระองค์ว่า “ถ้าพระองค์มิได้เสด็จไปกับข้าพระองค์ ก็ขออย่านําพวกข้าพระองค์ขึ้นไปจากที่นี่เลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 16, 'ทําอย่างไรจะทราบได้ตรงนี้ว่า ข้าพระองค์และพลไพร่ของพระองค์ได้รับพระกรุณาในสายพระเนตรของพระองค์แล้ว ก็เมื่อพระองค์เสด็จไปกับพวกข้าพระองค์ด้วยมิใช่หรือ ดังนี้ เราทั้งหลายทั้งข้าพระองค์และพลไพร่ของพระองค์จึงจะแยกออกจากชนชาติทั้งปวงที่อยู่บนพื้นแผ่นดินโลก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 17, 'ฝ่ายพระเยโฮวาห์ตรัสกับโมเสสว่า “เราจะกระทําสิ่งที่เจ้ากล่าวถึงนี้ด้วยเพราะว่าเจ้าได้รับความกรุณาในสายตาของเราแล้ว และเรารู้จักเจ้าตามชื่อของเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 18, 'โมเสสจึงกราบทูลว่า “ขอทรงโปรดสําแดงสง่าราศีของพระองค์แก่ข้าพระองค์เถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 19, 'พระองค์จึงตรัสตอบว่า “เราจะให้คุณความดีของเราประจักษ์แจ้งต่อหน้าเจ้า และเราจะประกาศนามของเราคือ เยโฮวาห์ ให้ประจักษ์ต่อหน้าเจ้า เราประสงค์จะโปรดปรานผู้ใด เราก็จะโปรดปรานผู้นั้น และเราประสงค์จะเมตตาแก่ผู้ใด เราก็จะเมตตาผู้นั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 20, 'พระองค์จึงตรัสว่า “เจ้าจะเห็นหน้าของเราไม่ได้ เพราะมนุษย์เห็นหน้าเราแล้วจะมีชีวิตอยู่ไม่ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 21, 'พระเยโฮวาห์ตรัสอีกว่า “ดูเถิด มีที่แห่งหนึ่งอยู่ใกล้เรา เจ้าจงไปยืนอยู่บนศิลานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 22, 'แล้วขณะเมื่อสง่าราศีของเรากําลังผ่านไป เราจะซ่อนเจ้าไว้ในช่องศิลาและจะบังเจ้าไว้ด้วยมือเราจนกว่าเราจะผ่านไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 23, 'เมื่อเราเอามือของเราออกแล้ว เจ้าจะเห็นหลังของเรา แต่หน้าของเราเจ้าจะมิได้เห็น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 1, 'พระเยโฮวาห์ตรัสกับโมเสสว่า “จงสกัดศิลาอีกสองแผ่นเหมือนเดิมแล้วเราจะจารึกคําเหมือนในแผ่นเก่าที่เจ้าทําแตกนั้นให้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 2, 'จงเตรียมให้พร้อมเวลาเช้า แล้วจงขึ้นมาบนภูเขาซีนายแต่เช้า จงคอยเฝ้าเราบนยอดภูเขานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 3, 'อย่าให้ผู้ใดขึ้นมาด้วย และอย่าให้ผู้ใดมาอยู่ตลอดทั่วทั้งภูเขา อย่าให้ฝูงแพะแกะ ฝูงวัวกินหญ้าอยู่หน้าภูเขานี้เลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 4, 'ฝ่ายโมเสสจึงสกัดศิลาสองแผ่นเหมือนสองแผ่นแรก แล้วท่านก็ตื่นแต่เช้าขึ้นไปบนภูเขาซีนายตามรับสั่งของพระเยโฮวาห์ถือศิลาไปสองแผ่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 5, 'ฝ่ายพระเยโฮวาห์เสด็จลงมาในเมฆ และโมเสสยืนอยู่กับพระองค์ที่นั่น และออกพระนามพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 6, 'พระเยโฮวาห์เสด็จผ่านไปข้างหน้าท่าน ตรัสว่า “พระเยโฮวาห์ พระเยโฮวาห์พระเจ้า ผู้ทรงพระกรุณา ทรงกอปรด้วยพระคุณ ทรงกริ้วช้า และบริบูรณ์ด้วยความเมตตาและความจริง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 7, 'ผู้ทรงสําแดงความเมตตาต่อมนุษย์กระทั่งพันชั่วอายุ ผู้ทรงโปรดยกโทษความชั่วช้า การละเมิดและบาปของเขาเสีย แต่จะทรงถือว่าไม่มีโทษก็หามิได้ และให้โทษเพราะความชั่วช้าของบิดาตกทอดไปถึงลูกหลานสามชั่วสี่ชั่วอายุคน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 8, 'ฝ่ายโมเสสจึงรีบกราบลงที่พื้นดินนมัสการ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 9, 'แล้วทูลว่า “โอ ข้าแต่องค์พระผู้เป็นเจ้า ถ้าแม้ข้าพระองค์ได้รับพระกรุณาในสายพระเนตรของพระองค์ ข้าพระองค์ทูลวิงวอนต่อพระองค์ ขอองค์พระผู้เป็นเจ้าของข้าพระองค์โปรดเสด็จไปท่ามกลางพวกข้าพระองค์เพราะเป็นชนชาติคอแข็งดื้อดึง และขอทรงโปรดยกโทษความชั่วช้าและความบาปของพวกข้าพระองค์ และโปรดรับพวกข้าพระองค์เป็นมรดกของพระองค์ด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 10, 'ฝ่ายพระองค์ตรัสว่า “ดูเถิด เราจะทําพันธสัญญาไว้ เราจะทําการมหัศจรรย์ต่อหน้าชนชาติของเจ้าทุกคน ซึ่งไม่มีผู้ใดกระทําในประชาชาติใดทั่วพิภพ และประชาชนทั้งปวงซึ่งเจ้าอยู่ท่ามกลางเขานั้น จะเห็นกิจการของพระเยโฮวาห์ เพราะการซึ่งเราจะทําต่อเจ้านั้นจะเป็นสิ่งที่น่ากลัวยิ่งนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 11, 'จงถือตามคําซึ่งเราบัญชาเจ้าในวันนี้ ดูเถิด เราจะไล่คนอาโมไรต์ คนคานาอัน คนฮิตไทต์ คนเปริสซี คนฮีไวต์ และคนเยบุส ไปให้พ้นหน้าเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 12, 'จงระวังตัวให้ดี อย่ากระทําพันธสัญญากับชาวเมืองซึ่งเจ้าจะไปถึงนั้น เกรงว่าจะเป็นบ่วงแร้วดักพวกเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 13, 'แต่เจ้าทั้งหลายจงทําลายแท่นบูชาและทุบเสาอันศักดิ์สิทธิ์ของเขาให้แหลกละเอียด และโค่นเสารูปเคารพของเขาเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 14, 'เจ้าอย่านมัสการพระอื่นเลย เพราะพระเยโฮวาห์ผู้ทรงพระนามว่าหวงแหนเป็นพระเจ้าผู้ทรงหวงแหน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 15, 'เกรงว่าเจ้าจะทําพันธสัญญากับชาวเมืองนั้น และเมื่อเขาเล่นชู้กับพระของเขา และถวายสัตวบูชาแก่บรรดาพระนั้น เขาจะเชิญพวกเจ้าไปร่วมด้วย และพวกเจ้าจะไปกินของที่เขาถวายบูชานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 16, 'เกรงว่าเจ้าจะรับบุตรสาวของเขามาเป็นภรรยาบุตรชายของเจ้า และบุตรสาวของเขานั้นจะไปเล่นชู้กับพระของเขา และชักชวนให้บุตรชายของเจ้าไปเล่นชู้กับพระนั้นด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 17, 'เจ้าอย่าหล่อรูปพระไว้สําหรับตัวเองเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 18, 'เจ้าทั้งหลายจงถือเทศกาลกินขนมปังไร้เชื้อ จงกินขนมปังไร้เชื้อให้ครบเจ็ดวันตามกําหนดในเดือนอาบีบตามที่เราบัญชาเจ้า เพราะเจ้าออกจากอียิปต์ในเดือนอาบีบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 19, 'ทุกสิ่งซึ่งออกจากครรภ์ครั้งแรกเป็นของเรา คือสัตว์ตัวผู้ทั้งหมดของเจ้า ลูกหัวปีของวัวและของแกะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 20, 'ส่วนลูกลาหัวปีนั้นเจ้าจงนําลูกแกะมาไถ่ไว้ ถ้าแม้เจ้ามิได้ไถ่ก็จงหักคอมันเสีย บุตรชายหัวปีทั้งหลายของพวกเจ้านั้นจะต้องไถ่ไว้ด้วย อย่าให้ผู้ใดมาเฝ้าเรามือเปล่าเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 21, 'เจ้าจงทําการงานในกําหนดหกวัน แต่วันที่เจ็ดจงพัก แม้ว่าในฤดูไถนาและฤดูเกี่ยวข้าวก็จงพัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 22, 'จงถือเทศกาลสัปดาห์ คือเทศกาลเลี้ยงฉลองผลต้นฤดูเกี่ยวข้าวสาลี และถือเทศกาลเลี้ยงฉลองการเก็บผลิตผลในปลายปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 23, 'บรรดาผู้ชายทั้งหลายของพวกเจ้าต้องมาประชุมกันต่อพระพักตร์องค์พระผู้เป็นเจ้าพระเจ้า คือพระเจ้าแห่งอิสราเอลปีละสามครั้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 24, 'เพราะเราจะขับไล่ชนชาติทั้งหลายออกไปให้พ้นหน้าพวกเจ้าและจะขยายเขตแดนเมืองของเจ้าให้กว้างออกไป เมื่อพวกเจ้าจะขึ้นไปเฝ้าพระเยโฮวาห์พระเจ้าของเจ้าปีละสามครั้งนั้น จะไม่มีใครอยากได้แผ่นดินของเจ้าเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 25, 'อย่าถวายเลือดบูชาพร้อมกับขนมปังมีเชื้อ และเครื่องบูชาอันเกี่ยวกับเทศกาลเลี้ยงปัสกานั้น อย่าให้เหลือไว้จนถึงวันรุ่งขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 26, 'จงคัดพืชผลแรกจากผลรุ่นแรกในไร่นามาถวายในพระนิเวศพระเยโฮวาห์พระเจ้าของเจ้า อย่าต้มเนื้อลูกแพะด้วยน้ํานมแม่ของมันเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 27, 'พระเยโฮวาห์ตรัสกับโมเสสว่า “คําเหล่านี้จงเขียนไว้ เพราะเราทําพันธสัญญาไว้กับเจ้าและพวกอิสราเอลตามข้อความเหล่านี้แล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 28, 'ฝ่ายโมเสสเฝ้าพระเยโฮวาห์อยู่ที่นั่นสี่สิบวันสี่สิบคืน มิได้รับประทานอาหารหรือน้ําเลย และท่านจารึกคําพันธสัญญาไว้ที่แผ่นศิลา คือพระบัญญัติสิบประการ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 29, 'อยู่ต่อมาโมเสสได้ลงมาจากภูเขาซีนาย ถือแผ่นพระโอวาทสองแผ่นมาด้วย เวลาที่ลงมาจากภูเขานั้นโมเสสก็ไม่ทราบว่า ผิวหน้าของตนทอแสงเนื่องด้วยพระเจ้าทรงสนทนากับท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 30, 'เมื่ออาโรนและคนอิสราเอลทั้งปวงมองดูโมเสส ดูเถิด ผิวหน้าของท่านทอแสง และเขาก็กลัวไม่กล้าเข้ามาใกล้ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 31, 'ฝ่ายโมเสสเรียกเขามา แล้วอาโรนกับบรรดาประมุขของชุมนุมก็กลับมาหาโมเสสและท่านสนทนากับเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 32, 'แล้วภายหลังคนอิสราเอลทั้งหลายเข้ามาใกล้ โมเสสจึงให้บัญญัติแก่เขาตามที่พระเยโฮวาห์ตรัสแก่ท่านทุกข้อบนภูเขาซีนาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 33, 'เมื่อท่านพูดจบแล้วก็ใช้ผ้าคลุมหน้าไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 34, 'แต่เมื่อไรที่โมเสสเข้าเฝ้าทูลต่อพระพักตร์พระเยโฮวาห์ ท่านก็ปลดผ้านั้นออกเสีย จนกว่าจะกลับออกมา แล้วท่านออกมาเล่าให้คนอิสราเอลฟังตามที่ท่านรับพระบัญชามาแล้วนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 35, 'และคนอิสราเอลดูหน้าของโมเสสคือเห็นผิวหน้าของโมเสสทอแสง ฝ่ายโมเสสใช้ผ้าคลุมหน้าไว้อีกทุกครั้ง จนกว่าจะเข้าไปทูลพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 1, 'ฝ่ายโมเสสให้ชุมนุมชนอิสราเอลทั้งหมดประชุมกันกล่าวแก่เขาว่า “ต่อไปนี้เป็นสิ่งซึ่งพระเยโฮวาห์บัญชาให้ท่านทั้งหลายกระทํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 2, 'จงทํางานในกําหนดหกวัน แต่วันที่เจ็ดให้ท่านถือเป็นวันบริสุทธิ์ เป็นวันสะบาโตแด่พระเยโฮวาห์ สําหรับใช้พัก ผู้ใดทํางานในวันนั้นต้องถูกลงโทษถึงตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 3, 'ในวันสะบาโตนั้นอย่าก่อไฟเลย ทั่วตลอดที่อาศัยของท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 4, 'โมเสสได้กล่าวแก่ชุมนุมชนอิสราเอลทั้งหมดว่า “ต่อไปนี้เป็นสิ่งซึ่งพระเยโฮวาห์ทรงบัญชาว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 5, 'ท่านทั้งหลายจงนําของจากของที่มีอยู่มาถวายพระเยโฮวาห์ ผู้ใดมีน้ําใจกว้างขวางให้ผู้นั้นนําของมาถวายพระเยโฮวาห์ คือทองคํา เงิน และทองเหลือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 6, 'ผ้าสีฟ้า สีม่วง สีแดงเข้ม ผ้าป่านเนื้อละเอียด และขนแพะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 7, 'หนังแกะตัวผู้ย้อมสีแดง หนังของแบดเจอร์และไม้กระถินเทศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 8, 'น้ํามันเติมตะเกียง เครื่องเทศสําหรับเจือน้ํามันเจิม และปรุงเครื่องหอมสําหรับการเผาถวาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 9, 'พลอยสีน้ําข้าวและพลอยต่างๆสําหรับฝังทําเอโฟดและทับทรวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 10, 'จงให้ทุกคนที่เฉลียวฉลาดในหมู่พวกท่าน พากันมาทําสิ่งทั้งปวงซึ่งพระเยโฮวาห์ทรงบัญชาให้ทําแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 11, 'คือพลับพลา เต็นท์ และผ้าคลุมพลับพลา ขอเกี่ยวและไม้กรอบ กลอน เสา และฐานรองรับเสาของพลับพลานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 12, 'หีบและไม้คานหามหีบ พระที่นั่งกรุณากับม่านบังตา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 13, 'โต๊ะกับไม้คานหามโต๊ะ เครื่องใช้ทั้งปวงสําหรับโต๊ะ และขนมปังหน้าพระพักตร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 14, 'คันประทีปที่ให้แสงสว่างกับเครื่องอุปกรณ์ และตะเกียง และน้ํามันเติมตะเกียง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 15, 'แท่นเผาเครื่องหอมกับไม้คานหามแท่นนั้น น้ํามันเจิม และเครื่องหอมสําหรับเผาถวาย และม่านบังตาสําหรับประตูที่ประตูพลับพลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 16, 'แท่นเครื่องเผาบูชากับตาข่ายทองเหลือง ไม้คานหามและเครื่องใช้ทั้งปวงของแท่น ขันกับพานรองขันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 17, 'ผ้าม่านสําหรับกั้นลานพลับพลากับเสา และฐานรองรับเสา และผ้าม่านสําหรับประตูลาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 18, 'หลักหมุดสําหรับพลับพลา และหลักหมุดสําหรับลานพลับพลาพร้อมกับเชือก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 19, 'เสื้อยศเย็บด้วยฝีมือประณีตสําหรับแต่งเวลาปรนนิบัติในที่บริสุทธิ์ คือเสื้อยศบริสุทธิ์สําหรับอาโรนปุโรหิต และเสื้อยศสําหรับบุตรชายของท่าน เพื่อใช้ปฏิบัติในตําแหน่งปุโรหิต”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 20, 'แล้วชุมนุมชนอิสราเอลทั้งหมดก็แยกย้ายกันจากโมเสสไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 21, 'ทุกคนที่มีใจปรารถนา และที่มีใจสมัครก็นําสิ่งของมาถวายพระเยโฮวาห์สําหรับพลับพลาแห่งชุมนุมและการปรนนิบัติทั้งหลาย และสําหรับเครื่องยศบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 22, 'เขาจึงพากันมาทั้งชายและหญิง บรรดาผู้มีน้ําใจสมัครนํามาซึ่งเข็มกลัด ตุ้มหู แหวนตราและกําไล เป็นทองรูปพรรณทั้งนั้น คือทุกคนนําทองคํามาแกว่งไปแกว่งมาถวายพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 23, 'ส่วนทุกคนที่มีด้ายสีฟ้า สีม่วง สีแดงเข้ม หรือที่มีผ้าป่านเนื้อละเอียด ขนแพะ หนังแกะตัวผู้ย้อมสีแดง และหนังของแบดเจอร์ก็เอาของเหล่านั้นมาถวาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 24, 'ทุกคนที่มีเงินหรือทองเหลืองจะถวายก็นํามาถวายพระเยโฮวาห์ และทุกคนที่มีไม้กระถินเทศใช้การได้ก็นําไม้นั้นมาถวาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 25, 'ส่วนผู้หญิงทั้งปวงที่ชํานาญก็ปั่นด้ายด้วยมือของตน แล้วนําด้ายซึ่งปั่นนั้นมาถวายทั้งสีฟ้า สีม่วง สีแดงเข้ม และเส้นป่านปั่นอย่างดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 26, 'ฝ่ายบรรดาผู้หญิงที่มีใจปรารถนาก็ปั่นขนแพะด้วยความชํานาญ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 27, 'บรรดาประมุขก็นําพลอยสีน้ําข้าวและพลอยต่างๆมาสําหรับฝังทําเอโฟด และทับทรวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 28, 'กับเครื่องเทศและน้ํามันเติมตะเกียง น้ํามันเจิม และน้ํามันปรุงเครื่องหอมสําหรับเผาบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 29, 'คนอิสราเอลทั้งชายหญิงทุกคนที่มีใจสมัครนําของถวายสําหรับการงานต่างๆ ซึ่งพระเยโฮวาห์ทรงบัญชาโมเสสไว้ให้กระทําก็นําของมาตามอําเภอใจถวายแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 30, 'โมเสสจึงกล่าวแก่คนอิสราเอลว่า “ดูก่อนท่าน พระเยโฮวาห์ได้ทรงออกชื่อเบซาเลลบุตรชายอุรี ผู้เป็นบุตรชายของเฮอร์ตระกูลยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 31, 'และพระองค์ได้ทรงให้ผู้นั้นประกอบด้วยพระวิญญาณของพระเจ้าให้มีสติปัญญาและความเข้าใจ และความรู้ในการช่างฝีมือทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 32, 'เพื่อจะคิดประดิษฐ์ลวดลายอย่างฉลาด ทําด้วยทองคําและเงินและทองเหลือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 33, 'และเจียระไนพลอยต่างๆสําหรับฝังในกระเปาะ และการแกะสลักไม้ คือให้มีฝีมือดีเลิศทุกอย่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 34, 'อนึ่งพระองค์ทรงดลใจให้ผู้นั้นมีน้ําใจที่จะสอนคนอื่นได้ด้วย พร้อมด้วยโอโฮลีอับบุตรชายอาหิสะมัคตระกูลดาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 35, 'คนทั้งสองนี้พระองค์ทรงประทานสติปัญญาแก่จิตใจของเขาให้มีความสามารถในการที่จะกระทํางานได้ทุกอย่าง เช่นการช่างฝีมือ การช่างออกแบบ และการช่างด้ายสี คือสีฟ้า สีม่วง สีแดงเข้มและเส้นป่านปั่นอย่างดี และช่างทอ คือทําการช่างฝีมือได้ทุกอย่าง และเป็นช่างออกแบบอย่างฉลาดด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 1, 'ฝ่ายเบซาเลล และโอโฮลีอับ กับคนทั้งปวงที่เฉลียวฉลาด ซึ่งพระเยโฮวาห์ทรงประทานสติปัญญาและความเข้าใจให้พอที่จะทําการทุกอย่างในการสร้างสถานบริสุทธิ์ ตามที่พระเยโฮวาห์ทรงบัญชาไว้แล้วทุกประการ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 2, 'โมเสสจึงเรียกเบซาเลลและโอโฮลีอับ กับคนทั้งปวงที่เฉลียวฉลาดซึ่งพระเยโฮวาห์ทรงประทานสติปัญญาให้แก่จิตใจของเขา และใจของเขาปรารถนาให้มาทํางาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 3, 'คนเหล่านี้ได้รับของถวายทั้งหมดนั้นจากโมเสสที่คนอิสราเอลนํามาถวายเพื่อนําไปทําสถานบริสุทธิ์ พลไพร่ยังนําของที่สมัครใจจะถวายมาถวายอีกทุกๆเวลาเช้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 4, 'ฝ่ายคนทั้งปวงที่เฉลียวฉลาดซึ่งทํางานต่างๆที่สถานบริสุทธิ์นั้นมาถึงแล้ว ต่างก็หยุดทํางานในหน้าที่ของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 5, 'พากันมาเรียนโมเสสว่า “พลไพร่นําของมาถวายมากเกินความต้องการที่จะใช้ในงานนั้นๆซึ่งพระเยโฮวาห์ทรงบัญชาให้กระทํา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 6, 'โมเสสจึงสั่งให้ประกาศไปทั่วค่ายว่า “อย่าให้ชายหญิงนําของสําหรับทําสถานบริสุทธิ์มาถวายอีกเลย” เหตุฉะนั้นพลไพร่จึงยับยั้งไม่นําของมาถวายอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 7, 'เพราะของที่เขามีอยู่แล้วก็พอสําหรับงานทั้งปวงนั้น และยังมีเหลืออีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 8, 'บรรดาช่างผู้เฉลียวฉลาดได้ทําพลับพลาด้วยม่านสิบผืน ด้วยผ้าป่านเนื้อละเอียด ด้วยด้ายสีฟ้า สีม่วง สีแดงเข้ม มีรูปเครูบฝีมือช่างออกแบบไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 9, 'ม่านผืนหนึ่งยาวยี่สิบแปดศอก กว้างสี่ศอก ม่านทุกผืนเท่ากัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 10, 'ม่านห้าผืนเขาทําให้เกี่ยวติดกัน และอีกห้าผืนนั้นเกี่ยวติดกันด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 11, 'เขาทําหูด้วยด้ายสีฟ้า ติดไว้ตามขอบม่านด้านนอกสุดชุดที่หนึ่ง และตามขอบม่านด้านนอกสุดชุดที่สองก็ทําหูไว้เหมือนกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 12, 'ม่านผืนหนึ่งเขาทําหูห้าสิบหู และตามขอบม่านชุดที่สองเขาก็ทําหูห้าสิบหูให้ตรงกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 13, 'และเขาทําขอทองคําห้าสิบขอ สําหรับใช้เกี่ยวม่านเพื่อให้พลับพลาเป็นชิ้นเดียวกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 14, 'เขาทําม่านด้วยขนแพะสําหรับเป็นเต็นท์คลุมพลับพลาอีกสิบเอ็ดผืน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 15, 'ม่านผืนหนึ่งยาวสามสิบศอก กว้างสี่ศอก ทั้งสิบเอ็ดผืนเท่ากัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 16, 'เขาเกี่ยวม่านห้าผืนให้ติดกันต่างหาก และม่านอีกหกผืนก็เกี่ยวติดกันอีกต่างหาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 17, 'และเขาทําหูห้าสิบหูติดกับม่านด้านนอกสุดชุดที่หนึ่ง และเขาทําหูห้าสิบหูติดกับขอบม่านด้านนอกสุดชุดที่สอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 18, 'เขาทําขอทองเหลืองห้าสิบขอเกี่ยวขอเข้าที่หูให้ติดต่อเป็นเต็นท์หลังเดียวกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 19, 'เขาทําเครื่องดาดเต็นท์ด้วยหนังแกะตัวผู้ย้อมสีแดงชั้นหนึ่ง และคลุมทับด้วยหนังของแบดเจอร์อีกชั้นหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 20, 'เขาทําไม้กรอบสําหรับพลับพลาด้วยไม้กระถินเทศยกตั้งขึ้นตรงๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 21, 'ไม้กรอบนั้นยาวแผ่นละสิบศอก กว้างศอกคืบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 22, 'มีเดือยกรอบละสองเดือย เดือยกรอบหนึ่งมีไม้ประกับติดกับเดือยอีกกรอบหนึ่ง เขาได้ทําไม้กรอบพลับพลาทั้งหมดอย่างนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 23, 'เขาทําไม้กรอบพลับพลาดังนี้ ด้านใต้เขาใช้ยี่สิบแผ่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 24, 'เขาทําฐานด้วยเงินสี่สิบฐานสําหรับไม้กรอบยี่สิบแผ่น ใต้ไม้กรอบแผ่นหนึ่งมีฐานรองรับแผ่นละสองฐานสําหรับสวมเดือยสองอัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 25, 'ด้านที่สองของพลับพลาข้างทิศเหนือนั้นเขาทําไม้กรอบยี่สิบแผ่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 26, 'เขาทําฐานเงินรองรับสี่สิบฐาน ใต้ไม้กรอบมีฐานแผ่นละสองฐาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 27, 'ส่วนด้านหลังทิศตะวันตกของพลับพลาเขาทําไม้กรอบหกแผ่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 28, 'เขาทําไม้กรอบอีกสองแผ่นสําหรับมุมพลับพลาด้านหลัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 29, 'ไม้กรอบนั้นข้างล่างให้แยกกัน แต่ตอนบนยอดติดต่อกันที่ห่วงแรก เขาทําอย่างนี้ทําให้เกิดมุมสองมุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 30, 'คือรวมเป็นไม้กรอบแปดแผ่นด้วยกันและฐานเงินสิบหกอัน ใต้ไม้กรอบมีฐานแผ่นละสองฐาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 31, 'เขาทํากลอนด้วยไม้กระถินเทศห้าอันสําหรับขัดไม้กรอบฝาพลับพลาด้านหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 32, 'และกลอนอีกห้าอันสําหรับขัดไม้กรอบฝาพลับพลาอีกด้านหนึ่ง และกลอนอีกห้าอันสําหรับขัดไม้กรอบฝาพลับพลาด้านตะวันตก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 33, 'เขาทํากลอนตัวกลางให้ร้อยตอนกลางของไม้กรอบสําหรับขัดฝาตั้งแต่มุมหนึ่งไปจดอีกมุมหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 34, 'เขาหุ้มไม้กรอบเหล่านั้นด้วยทองคํา และทําห่วงกรอบด้วยทองคําสําหรับร้อยกลอน และกลอนนั้นเขาหุ้มด้วยทองคําเช่นกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 35, 'เขาทําม่านนั้นด้วยด้ายสีฟ้า สีม่วง สีแดงเข้ม และด้วยผ้าป่านเนื้อละเอียด มีภาพเครูบฝีมือช่างออกแบบไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 36, 'เขาทําเสาไม้กระถินเทศสี่เสาหุ้มด้วยทองคํา ขอติดเสานั้นก็เป็นทองคํา เขาหล่อฐานเงินสี่อันสําหรับรองรับเสานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 37, 'และเขาทําบังตาที่ประตูพลับพลานั้นด้วยด้ายสีฟ้า สีม่วง สีแดงเข้ม และผ้าป่านเนื้อละเอียดประกอบด้วยฝีมือช่างปัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 38, 'และทําเสาห้าต้นสําหรับม่านนั้นพร้อมด้วยขอเกี่ยว บัวคว่ําและราวยึดเสานั้นหุ้มด้วยทองคํา แต่ฐานห้าฐานสําหรับรองรับเสานั้นทําด้วยทองเหลือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 1, 'เบซาเลลทําหีบด้วยไม้กระถินเทศ ยาวสองศอกคืบ กว้างศอกคืบ และสูงศอกคืบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 2, 'หีบนั้นเขาหุ้มด้วยทองคําบริสุทธิ์ ทั้งข้างในและข้างนอก และได้ทํากระจังรอบหีบนั้นด้วยทองคํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 3, 'เขาหล่อห่วงทองคําสี่ห่วงติดไว้ที่มุมทั้งสี่ ด้านนี้สองห่วงและด้านนั้นสองห่วง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 4, 'เขาทําคานหามด้วยไม้กระถินเทศหุ้มด้วยทองคํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 5, 'เขาสอดคานหามเข้าที่ห่วงข้างหีบสําหรับใช้ยกหีบนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 6, 'แล้วเขาทําพระที่นั่งกรุณาด้วยทองคําบริสุทธิ์ ยาวสองศอกคืบ กว้างศอกคืบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 7, 'เขาทําเครูบทองคําสองรูป โดยใช้ค้อนทํา ตั้งไว้ที่ปลายพระที่นั่งกรุณาทั้งสองข้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 8, 'เขาทําเครูบไว้ที่ปลายพระที่นั่งกรุณาข้างละรูป เขาทําเครูบนั้นตอนปลายทั้งสองข้างเป็นเนื้อเดียวกับพระที่นั่งกรุณา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 9, 'ให้เครูบกางปีกออกเบื้องบน ปกพระที่นั่งกรุณาไว้ด้วยปีก และให้หันหน้าเข้าหากัน คือให้เครูบหันหน้ามาตรงพระที่นั่งกรุณา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 10, 'เขาเอาไม้กระถินเทศทําโต๊ะตัวหนึ่ง ยาวสองศอก กว้างหนึ่งศอก และสูงศอกคืบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 11, 'เขาหุ้มโต๊ะนั้นด้วยทองคําบริสุทธิ์ และทํากระจังทองคํารอบโต๊ะนั้นด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 12, 'เขาทําประกับขอบโต๊ะนั้นกว้างหนึ่งฝ่ามือโดยรอบ แล้วทํากระจังทองคําประกอบรอบประกับนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 13, 'เขาหล่อห่วงทองคําสี่อันติดไว้ที่มุมโต๊ะทั้งสี่ตรงขาโต๊ะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 14, 'ห่วงนั้นติดชิดกับกระจัง สําหรับสอดคานหามโต๊ะนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 15, 'เขาทําคานหามด้วยไม้กระถินเทศหุ้มด้วยทองคําสําหรับหามโต๊ะนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 16, 'และเขาทําเครื่องใช้สําหรับโต๊ะนั้นมี จาน ช้อน กับอ่างน้ําและคนโทที่ใช้รินเครื่องดื่มบูชา ซึ่งทําด้วยทองคําบริสุทธิ์ทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 17, 'เขาทําคันประทีปอันหนึ่งด้วยทองคําบริสุทธิ์ เขาใช้ฝีค้อนทําคันประทีป ให้ทั้งลําตัว กิ่ง ดอก ดอกตูม และกลีบติดเป็นเนื้อเดียวกันกับคันประทีปนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 18, 'มีกิ่งหกกิ่งแยกออกจากลําคันประทีปนั้นข้างละสามกิ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 19, 'แต่ละกิ่งมีดอกเหมือนดอกอัลมันด์สามดอก ทุกๆดอกมีดอกตูมและกลีบ เป็นดังนี้ทั้งหกกิ่ง ซึ่งยื่นออกจากลําคันประทีป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 20, 'สําหรับลําคันประทีปนั้นมีดอกสี่ดอกเหมือนดอกอัลมันด์ ทั้งดอกตูมและกลีบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 21, 'ใต้กิ่งทุกๆคู่ทั้งหกกิ่งที่ลําคันประทีปนั้น ให้มีดอกตูมเป็นเนื้อเดียวกันกับคันประทีป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 22, 'ดอกตูมและกิ่งเป็นเนื้อเดียวกันกับคันประทีป ทําทุกส่วนเป็นเนื้อเดียวกันด้วยทองคําบริสุทธิ์และใช้ค้อนทํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 23, 'เขาทําตะเกียงเจ็ดดวงสําหรับคันประทีปนั้น ตะไกรตัดไส้ตะเกียง และถาดใส่ตะไกรด้วยทองคําบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 24, 'คันประทีปและเครื่องใช้ทั้งหมดสําหรับคันประทีปนั้น เขาทําด้วยทองคําบริสุทธิ์หนักหนึ่งตะลันต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 25, 'เขาสร้างแท่นบูชาสําหรับเผาเครื่องหอมด้วยไม้กระถินเทศ ยาวศอกหนึ่ง กว้างศอกหนึ่ง เป็นรูปสี่เหลี่ยมจัตุรัส และสูงสองศอก เชิงงอนที่มุมแท่นนั้นก็เป็นไม้ท่อนเดียวกันกับแท่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 26, 'เขาหุ้มแท่นนั้นด้วยทองคําบริสุทธิ์ ทั้งด้านบนและด้านข้างทั้งสี่ด้าน และเชิงงอนด้วย และเขาทํากระจังทองคํารอบแท่นนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 27, 'เขาทําห่วงทองคําสองห่วงติดไว้ใต้กระจังทั้งสองด้าน ตรงข้ามกัน เป็นที่สําหรับสอดใส่ไม้คานหาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 28, 'เขาทําไม้คานหามนั้นด้วยไม้กระถินเทศหุ้มด้วยทองคํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 29, 'เขาปรุงน้ํามันเจิมอันบริสุทธิ์ และปรุงเครื่องหอมบริสุทธิ์ด้วยเครื่องเทศตามศิลปของช่างปรุง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 1, 'เขาทําแท่นเครื่องเผาบูชาด้วยไม้กระถินเทศ ยาวห้าศอก กว้างห้าศอก เป็นแท่นสี่เหลี่ยมจัตุรัส สูงสามศอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 2, 'เขาทําเชิงงอนติดไว้ทั้งสี่มุมของแท่นนั้น เชิงงอนนั้นเป็นไม้ชิ้นเดียวกันกับแท่นบูชา เขาหุ้มแท่นด้วยทองเหลือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 3, 'เขาทําเครื่องใช้บนแท่นนั้นทุกอย่าง คือหม้อ พลั่ว ชาม ขอเกี่ยวเนื้อ และถาดรองไฟ เครื่องใช้สําหรับแท่นทั้งหมดนั้นเขาทําด้วยทองเหลือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 4, 'และเขาเอาทองเหลืองทําเป็นตาข่ายประดับแท่นนั้นให้อยู่ใต้กระจังของแท่น และห้อยอยู่ตั้งแต่กลางแท่นลงมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 5, 'เขาหล่อห่วงสี่ห่วงติดที่มุมทั้งสี่ของตาข่ายทองเหลืองสําหรับสอดไม้คานหาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 6, 'เขาทําไม้คานหามด้วยไม้กระถินเทศและหุ้มด้วยทองเหลือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 7, 'เขาสอดไม้คานหามนั้นไว้ในห่วงที่ข้างแท่นสําหรับหาม เขาทําแท่นนั้นด้วยไม้กระดานให้ข้างในกลวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 8, 'เขาทําขันทองเหลืองและพานรองขันทองเหลืองจากกระจกเงาของบรรดาผู้หญิงที่ปรนนิบัติ ณ ประตูพลับพลาแห่งชุมนุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 9, 'และเขาทําลานไว้ด้วย ให้รั้วด้านใต้มีผ้าบัง ทําด้วยผ้าป่านเนื้อละเอียด ยาวร้อยศอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 10, 'มีเสายี่สิบต้นกับฐานทองเหลืองรองรับเสายี่สิบฐาน ขอติดเสาและราวยึดเสานั้นทําด้วยเงิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 11, 'ด้านเหนือมีผ้าบังยาวร้อยศอก กับเสายี่สิบต้นและฐานทองเหลืองยี่สิบฐาน ขอติดเสาและราวยึดเสานั้นทําด้วยเงิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 12, 'ส่วนด้านตะวันตกมีผ้าบังยาวห้าสิบศอก กับเสาสิบต้น และฐานรองรับเสาสิบฐาน ขอติดเสาและราวยึดเสาทําด้วยเงิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 13, 'ด้านตะวันออกใช้ผ้ายาวห้าสิบศอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 14, 'ผ้าบังด้านริมประตูข้างหนึ่งยาวสิบห้าศอก มีเสาสามต้นและฐานรองรับเสาสามฐาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 15, 'และอีกข้างหนึ่ง ริมประตูข้างนี้และข้างโน้น มีผ้าบังยาวสิบห้าศอก มีเสาสามต้นและฐานรองรับเสาสามฐาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 16, 'ผ้าบังลานโดยรอบนั้นทําด้วยผ้าป่านเนื้อละเอียด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 17, 'ฐานรองรับเสานั้นทําด้วยทองเหลือง ขอติดเสาและราวยึดเสาเป็นเงิน และบัวคว่ําของเสานั้นหุ้มด้วยเงิน และเสาทุกต้นของลานมีราวยึดเสาทําด้วยเงิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 18, 'ม่านบังตาที่ประตูลานนั้นปักด้วยฝีมือของช่างปัก เป็นสีฟ้า สีม่วง สีแดงเข้มและผ้าป่านเนื้อละเอียด ยาวยี่สิบศอก สูงห้าศอก เสมอกับผ้าบังลาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 19, 'มีเสาสี่ต้นกับฐานรองรับเสาสี่ฐานเป็นทองเหลือง ขอติดเสาทําด้วยเงิน และส่วนที่หุ้มบัวคว่ํากับราวยึดเสาเป็นเงิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 20, 'หลักหมุดทุกหลักของพลับพลาและของลานรอบพลับพลานั้นทําด้วยทองเหลือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 21, 'นี่แหละเป็นบัญชีสิ่งของที่ใช้ในพลับพลา คือพลับพลาพระโอวาท ซึ่งเขาทั้งหลายนับตามคําสั่งของโมเสส มีคนเลวีจัดทําตามบัญชาของอิธามาร์บุตรชายอาโรนปุโรหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 22, 'ส่วนเบซาเลลบุตรชายอุรีผู้เป็นบุตรชายของเฮอร์แห่งตระกูลยูดาห์ ทําสิ่งสารพัดซึ่งพระเยโฮวาห์ได้ทรงบัญชาโมเสสแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 23, 'ผู้ร่วมงานกับเขาคือ โอโฮลีอับ บุตรชายอาหิสะมัคแห่งตระกูลดาน เป็นช่างฝีมือ ช่างออกแบบและช่างด้ายสีใช้ด้ายสีฟ้า สีม่วง สีแดงเข้ม และผ้าป่านเนื้อละเอียด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 24, 'ทองคําทั้งหมดซึ่งเขาใช้ในการสร้างที่บริสุทธิ์นั้น คือทองคําที่เขานํามาถวาย มีน้ําหนักยี่สิบเก้าตะลันต์เจ็ดร้อยสามสิบเชเขล ตามเชเขลแห่งสถานบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 25, 'เงินตามจํานวนชุมนุมชนได้นับไว้ รวมเป็นหนึ่งร้อยตะลันต์กับหนึ่งพันเจ็ดร้อยเจ็ดสิบห้าเชเขล ตามเชเขลแห่งสถานบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 26, 'คนละเบคา คือครึ่งเชเขลตามเชเขลของสถานบริสุทธิ์ อันเก็บมาจากทุกคนที่ไปจดทะเบียนสํามะโนครัว คือนับตั้งแต่อายุยี่สิบปีขึ้นไปรวมหกแสนสามพันห้าร้อยห้าสิบคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 27, 'เงินหนึ่งร้อยตะลันต์นั้น เขาใช้หล่อทําฐานรองรับเสาของสถานบริสุทธิ์และฐานของม่าน ฐานร้อยฐานเป็นเงินหนึ่งร้อยตะลันต์ คือฐานละหนึ่งตะลันต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 28, 'แต่เงินหนึ่งพันเจ็ดร้อยเจ็ดสิบห้าเชเขลนั้นเขาใช้ทําขอสําหรับเสาและหุ้มบัวคว่ําของเสานั้น และทําราวยึดเสาด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 29, 'ทองเหลืองเขานํามาถวายหนักเจ็ดสิบตะลันต์ กับสองพันสี่ร้อยเชเขล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 30, 'ทองเหลืองนั้นเขาใช้ทําฐานประตูพลับพลาแห่งชุมนุมและทําแท่นทองเหลือง และตาข่ายทองเหลืองประดับแท่นและทําเครื่องใช้ทั้งหมดของแท่นนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 31, 'ทําฐานล้อมรอบลานและฐานที่ประตูลาน หลักหมุดทั้งหมดของพลับพลาและหลักหมุดรอบลานนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 1, 'ด้ายสีฟ้า สีม่วง สีแดงเข้มนั้น เขาใช้ทําเสื้อยศเย็บด้วยฝีมือประณีตสําหรับใส่เวลาปรนนิบัติในที่บริสุทธิ์ และได้ทําเครื่องยศบริสุทธิ์สําหรับอาโรน ตามที่พระเยโฮวาห์ทรงบัญชาแก่โมเสส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 2, 'เขาทําเอโฟดด้วยทองคํา ด้วยด้ายสีฟ้า สีม่วง สีแดงเข้ม และผ้าป่านเนื้อละเอียด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 3, 'เขาตีทองใบแผ่ออกเป็นแผ่นบางๆแล้วตัดเป็นเส้นๆเพื่อจะทอเข้ากับด้ายสีฟ้า เข้ากับด้ายสีม่วง เข้ากับด้ายสีแดงเข้ม และเข้ากับเส้นป่านอย่างดีด้วยฝีมือช่างชํานาญ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 4, 'เขาทําแถบติดไว้ที่บ่าเพื่อโยงเอโฟด ให้ติดกับริมตอนบนทั้งสองชิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 5, 'รัดประคดทออย่างประณีตสําหรับคาดทับเอโฟดนั้น เขาทําด้วยวัตถุอย่างเดียวกันและฝีมืออย่างเดียวกับเอโฟด คือทําด้วยทองคํา ด้ายสีฟ้า สีม่วง สีแดงเข้ม และผ้าป่านเนื้อละเอียดตามที่พระเยโฮวาห์ทรงบัญชาแก่โมเสส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 6, 'เขาเอาพลอยสีน้ําข้าวฝังไว้ในกระเปาะทองคําซึ่งมีลวดลายละเอียด และแกะอย่างแกะตรา เป็นชื่อบุตรอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 7, 'แล้วเขาติดไว้กับเอโฟดบนแถบบ่านั้นเพื่อให้พลอยนั้นเป็นที่ระลึกถึงบรรดาบุตรแห่งอิสราเอล ตามที่พระเยโฮวาห์ทรงบัญชาแก่โมเสส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 8, 'เขาทําทับทรวงด้วยฝีมือช่างออกแบบให้ฝีมือเหมือนกับทําเอโฟด คือทําด้วยทองคํา ด้ายสีฟ้า สีม่วง สีแดงเข้ม และผ้าป่านเนื้อละเอียด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 9, 'เขาทําทับทรวงเป็นรูปสี่เหลี่ยมจัตุรัส พับทบกลาง ยาวคืบหนึ่ง กว้างคืบหนึ่ง เป็นสองทบด้วยกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 10, 'เขาฝังพลอยสี่แถวบนทับทรวงนั้น แถวที่หนึ่งฝังทับทิม บุษราคัมและพลอยสีแดงเข้ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 11, 'แถวที่สองฝังมรกต ไพทูรย์และเพชร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 12, 'แถวที่สามฝังนิล โมราและพลอยสีม่วง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 13, 'แถวที่สี่ฝังพลอยเขียว พลอยสีน้ําข้าว และหยก พลอยทั้งหมดนี้เขาได้ฝังในกระเปาะลวดลายละเอียดทําด้วยทองคํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 14, 'พลอยเหล่านั้นมีชื่อเหล่าบุตรอิสราเอลสิบสองชื่อ จารึกไว้เหมือนแกะตรา มีชื่อตระกูลทุกตระกูลตามลําดับสิบสองตระกูล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 15, 'เขาทําสร้อยถักเกลียวด้วยทองคําบริสุทธิ์สําหรับทับทรวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 16, 'และเขาทั้งหลายทํากระเปาะลวดลายละเอียดด้วยทองคําสองอัน และห่วงทองคําสองห่วง ติดไว้ที่ปลายทั้งสองของทับทรวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 17, 'เขาทั้งหลายสอดสร้อยที่ทําด้วยทองคํานั้นในห่วงที่ปลายทับทรวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 18, 'และปลายสร้อยอีกสองข้างนั้น เขาทั้งหลายทําติดกับกระเปาะลวดลายละเอียดทั้งสอง ให้ติดไว้ข้างหน้าที่แถบยึดเอโฟดทั้งสองข้างบนบ่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 19, 'เขาทั้งหลายทําห่วงทองคําสองอันติดไว้ที่ขอบด้านล่างทั้งสองของทับทรวงข้างในติดเอโฟด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 20, 'และเขาทั้งหลายทําห่วงสองอันด้วยทองคํา ใส่ไว้ริมเอโฟดด้านหน้า ใต้แถบที่ตะเข็บเหนือรัดประคดที่ทอด้วยฝีมือประณีตของเอโฟด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 21, 'และเขาทั้งหลายผูกทับทรวงนั้นติดกับเอโฟดด้วย ใช้ด้ายถักสีฟ้าร้อยผูกที่ห่วง ให้ทับทรวงทับรัดประคดซึ่งทอด้วยฝีมือประณีตของเอโฟด เพื่อมิให้ทับทรวงหลุดไปจากเอโฟด ตามที่พระเยโฮวาห์ทรงบัญชาแก่โมเสส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 22, 'เขาทําเสื้อคลุมเข้าชุดกับเอโฟดด้วยด้ายสีฟ้าล้วนเป็นฝีมือทอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 23, 'และช่องกลางผืนเสื้อนั้น เขาทําเป็นคอเสื้อเช่นเดียวกับคอเสื้อทหารและมีขลิบรอบคอเพื่อมิให้ขาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 24, 'ที่ชายเสื้อคลุม เขาทั้งหลายปักเป็นรูปลูกทับทิม ใช้ด้ายสีฟ้า สีม่วง สีแดงเข้ม และผ้าป่านเนื้อละเอียด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 25, 'เขาทั้งหลายทําลูกพรวนด้วยทองคําบริสุทธิ์แล้วติดลูกพรวนระหว่างผลทับทิมรอบชายเสื้อคลุมนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 26, 'คือลูกพรวนลูกหนึ่ง ผลทับทิมผลหนึ่ง และลูกพรวนอีกลูกหนึ่ง ผลทับทิมอีกผลหนึ่งสลับกันดังนี้ รอบชายเสื้อคลุมนั้น สําหรับสวมเวลาปรนนิบัติพระองค์ ตามที่พระเยโฮวาห์ทรงบัญชาแก่โมเสส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 27, 'เขาทั้งหลายทําเสื้อด้วยผ้าป่านเนื้อละเอียดของช่างทอผ้าสําหรับอาโรนและสําหรับบุตรชายของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 28, 'และทํามาลาด้วยผ้าป่านเนื้อละเอียด และมาลางามด้วยผ้าป่านเนื้อละเอียด และทํากางเกงด้วยผ้าป่านเนื้อละเอียด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 29, 'และทํารัดประคดด้วยผ้าป่านปั่นเนื้อละเอียด และปักด้วยด้ายสีฟ้า สีม่วง สีแดงเข้ม ด้วยฝีมือช่างปัก ตามที่พระเยโฮวาห์ทรงบัญชาแก่โมเสส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 30, 'เขาทั้งหลายทําแผ่นมงกุฎบริสุทธิ์ด้วยทองคําบริสุทธิ์จารึกคําว่า “บริสุทธิ์แด่พระเยโฮวาห์” ไว้เหมือนอย่างแกะตรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 31, 'แล้วเขาเอาด้ายถักสีฟ้าผูกแผ่นทองคํานั้นไว้บนมาลา ตามที่พระเยโฮวาห์ทรงบัญชาแก่โมเสส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 32, 'ดังนี้แหละเขาทํางานสําหรับพลับพลาของเต็นท์แห่งชุมนุมให้สําเร็จทุกประการ พระเยโฮวาห์ทรงบัญชาแก่โมเสสไว้อย่างไร คนอิสราเอลก็กระทําอย่างนั้นทุกประการ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 33, 'เขาจึงได้นําพลับพลามามอบไว้กับโมเสส ทั้งเต็นท์และเครื่องใช้ทั้งปวงคือ ขอ ไม้กรอบ กลอน เสา และฐานรองรับเสา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 34, 'เครื่องดาดพลับพลาข้างบนทําด้วยหนังแกะตัวผู้ย้อมสีแดง และหนังของแบดเจอร์ และม่านสําหรับบังตา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 35, 'หีบพระโอวาทกับไม้คานหามของหีบนั้น และพระที่นั่งกรุณา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 36, 'โต๊ะกับเครื่องใช้ทั้งหมดบนโต๊ะนั้น และขนมปังหน้าพระพักตร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 37, 'คันประทีปบริสุทธิ์กับตะเกียง คือตะเกียงที่เข้าที่และเครื่องใช้ทั้งหมดของคันประทีปนั้นและน้ํามันสําหรับเติมตะเกียง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 38, 'แท่นทองคํา น้ํามันเจิม เครื่องหอมสําหรับเผาบูชา และผ้าบังตาสําหรับประตูพลับพลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 39, 'แท่นบูชาทองเหลือง กับตาข่ายทองเหลืองสําหรับแท่นนั้น ไม้คานหามและเครื่องใช้ทั้งหมดของแท่น ขันกับพานรองขัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 40, 'ม่านบังลาน เสากับฐานรองรับ ผ้าบังตาประตูลาน เชือกและหลักหมุดสําหรับลาน และเครื่องใช้ทั้งหมดของการปรนนิบัติที่พลับพลา สําหรับเต็นท์แห่งชุมนุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 41, 'เสื้อยศเย็บด้วยฝีมือประณีตสําหรับสวมในเวลาปรนนิบัติในที่บริสุทธิ์ เครื่องยศบริสุทธิ์สําหรับอาโรนปุโรหิต เครื่องยศสําหรับบุตรชายอาโรน สําหรับใช้สวมในเวลาปฏิบัติตําแหน่งปุโรหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 42, 'สิ่งสารพัดที่พระเยโฮวาห์ทรงบัญชาแก่โมเสสแล้ว ชนชาติอิสราเอลกระทําให้สําเร็จทุกประการ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 43, 'โมเสสจึงตรวจดูงานทั้งปวง และดูเถิด พระเยโฮวาห์ทรงบัญชาไว้อย่างไร เขาก็ทําเสร็จสิ้นทุกอย่าง โมเสสจึงอวยพรแก่เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 1, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 2, '“ในวันที่หนึ่งของเดือนแรก จงตั้งพลับพลาแห่งเต็นท์ของชุมนุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 3, 'จงตั้งหีบพระโอวาทไว้ในพลับพลาและกั้นม่านบังหีบนั้นไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 4, 'จงยกโต๊ะเข้ามาตั้งไว้ และจัดเครื่องบนโต๊ะไว้ตามที่ของมัน แล้วจงนําคันประทีปนั้นเข้ามาและจุดไฟที่ตะเกียงนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 5, 'จงตั้งแท่นบูชาทองคําสําหรับเผาเครื่องหอมตรงหน้าหีบพระโอวาท แล้วติดม่านบังตาของประตูพลับพลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 6, 'จงตั้งแท่นสําหรับเครื่องเผาบูชาไว้ตรงหน้าประตูพลับพลาแห่งเต็นท์ของชุมนุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 7, 'จงตั้งขันไว้ระหว่างเต็นท์แห่งชุมนุมกับแท่นบูชา แล้วจงตักน้ําใส่ไว้ในขันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 8, 'จงตั้งข้างฝาลานไว้รอบพลับพลา และติดม่านบังตาไว้ที่ประตูลานนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 9, 'จงเอาน้ํามันเจิม เจิมพลับพลากับสิ่งสารพัดซึ่งอยู่ในพลับพลานั้น และชําระพลับพลากับเครื่องใช้ทั้งหมดให้บริสุทธิ์ แล้วพลับพลานั้นจะบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 10, 'จงเจิมแท่นสําหรับเครื่องเผาบูชาด้วย และเครื่องใช้ทั้งหมดบนแท่นนั้น และชําระแท่นนั้นให้บริสุทธิ์ แท่นนั้นจะบริสุทธิ์ที่สุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 11, 'จงเจิมขันทั้งพานรองขันด้วย และชําระให้บริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 12, 'แล้วจงนําอาโรน และบุตรชายของเขามาที่ประตูพลับพลาแห่งชุมนุม ใช้น้ําล้างชําระตัวเขาเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 13, 'จงนําเสื้อผ้ายศบริสุทธิ์สวมให้อาโรน แล้วเจิมและชําระเขาให้บริสุทธิ์ เพื่อเขาจะปรนนิบัติเราในตําแหน่งปุโรหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 14, 'แล้วจงนําบุตรชายอาโรนมาด้วยและสวมเสื้อยศให้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 15, 'จงเจิมเขาเช่นเจิมบิดาของเขา เพื่อเขาจะปรนนิบัติเราในตําแหน่งปุโรหิต การเจิมนั้นจะเป็นการเจิมแต่งตั้งเขาไว้เป็นปุโรหิตเนืองนิตย์ตลอดชั่วอายุของเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 16, 'พระเยโฮวาห์ทรงบัญชาแก่โมเสสให้กระทําสิ่งใด ท่านก็กระทําสิ่งนั้นทุกประการ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 17, 'ต่อมาในวันที่หนึ่งเดือนแรกของปีที่สองท่านติดตั้งพลับพลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 18, 'โมเสสติดตั้งพลับพลาขึ้น คือวางฐานและตั้งไม้กรอบขึ้นไว้ สอดไม้กลอนและตั้งเสาขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 19, 'ท่านกางผ้าเต็นท์ทับบนพลับพลา แล้วเอาเครื่องดาดคลุมบนเต็นท์ ตามที่พระเยโฮวาห์ทรงบัญชาแก่โมเสส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 20, 'ท่านเก็บพระโอวาทไว้ในหีบนั้นและสอดไม้คานหามไว้ในหีบนั้น และตั้งพระที่นั่งกรุณาไว้บนหีบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 21, 'แล้วท่านนําหีบเข้าไปไว้ในพลับพลา และกั้นม่านบังตาบังหีบพระโอวาทนั้นไว้ ตามที่พระเยโฮวาห์ทรงบัญชาแก่โมเสส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 22, 'ท่านตั้งโต๊ะไว้ในเต็นท์แห่งชุมนุมทางทิศเหนือของพลับพลานอกม่านนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 23, 'แล้วจัดขนมปังไว้บนโต๊ะเป็นระเบียบต่อพระพักตร์พระเยโฮวาห์ ตามที่พระเยโฮวาห์ทรงบัญชาโมเสสไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 24, 'และท่านตั้งคันประทีปไว้ในเต็นท์แห่งชุมนุมทางทิศใต้ของพลับพลาตรงหน้าโต๊ะนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 25, 'แล้วก็จุดไฟตะเกียงต่อพระพักตร์พระเยโฮวาห์ ตามที่พระเยโฮวาห์ทรงบัญชาแก่โมเสส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 26, 'ท่านตั้งแท่นทองคําไว้ในเต็นท์แห่งชุมนุมตรงหน้าม่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 27, 'และเผาเครื่องหอมบนแท่นนั้น ตามที่พระเยโฮวาห์ทรงบัญชาแก่โมเสส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 28, 'ท่านกั้นม่านบังตาที่ประตูพลับพลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 29, 'ท่านตั้งแท่นสําหรับเครื่องเผาบูชาไว้ตรงประตูพลับพลาแห่งเต็นท์ของชุมนุม แล้วถวายเครื่องเผาบูชาและเครื่องธัญญบูชาบนแท่นนั้น ตามที่พระเยโฮวาห์ทรงบัญชาแก่โมเสส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 30, 'ท่านตั้งขันไว้ระหว่างเต็นท์แห่งชุมนุมกับแท่นบูชา แล้วใส่น้ําไว้ในขันสําหรับชําระล้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 31, 'โมเสสกับอาโรน และบุตรชายของท่าน ล้างมือและเท้าที่ขันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 32, 'เวลาเขาทั้งหลายเข้าไปในเต็นท์แห่งชุมนุม หรือเข้าไปใกล้แท่นนั้นเมื่อไร เขาก็ชําระล้างเสียก่อน ตามที่พระเยโฮวาห์ทรงบัญชาแก่โมเสส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 33, 'ท่านกั้นบริเวณลานรอบพลับพลาและแท่นนั้น แล้วกั้นม่านบังตาที่ตรงประตูลาน โมเสสก็จัดการนั้นให้เสร็จสิ้นไปทุกประการ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 34, 'ในขณะนั้นมีเมฆมาปกคลุมเต็นท์แห่งชุมนุมไว้ และสง่าราศีของพระเยโฮวาห์ก็ปรากฏอยู่เต็มพลับพลานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 35, 'โมเสสเข้าไปในเต็นท์แห่งชุมนุมไม่ได้เพราะเมฆปกคลุมอยู่ และสง่าราศีของพระเยโฮวาห์ก็อยู่เต็มพลับพลานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 36, 'ตลอดการเดินทางของเขา เมฆนั้นถูกยกขึ้นจากพลับพลาเมื่อใด ชนชาติอิสราเอลก็ยกเดินต่อไปทุกครั้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 37, 'แต่หากว่าเมฆนั้นมิได้ถูกยกขึ้นไป เขาก็ไม่ออกเดินทางเลย จนกว่าจะถึงวันที่เมฆนั้นจะถูกยกขึ้นไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 38, 'เพราะตลอดทางที่เขายกเดินไปนั้น ในกลางวันเมฆของพระเยโฮวาห์ทรงสถิตอยู่เหนือพลับพลา และในตอนกลางคืนมีไฟสถิตอยู่เหนือพลับพลานั้นประจักษ์แก่ตาของวงศ์วานอิสราเอลทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 1, 'พระเยโฮวาห์ทรงเรียกโมเสสตรัสกับท่านจากพลับพลาแห่งชุมนุมว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 2, '“จงพูดกับคนอิสราเอลและกล่าวแก่เขาว่า เมื่อคนใดในพวกท่านนําเครื่องบูชามาถวายพระเยโฮวาห์ ให้นําสัตว์เลี้ยงอันเป็นเครื่องบูชาของท่านมาจากฝูงวัวหรือฝูงแพะแกะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 3, 'ถ้าเครื่องบูชาของเขาเป็นเครื่องเผาบูชามาจากฝูงวัว ก็ให้เขานําสัตว์ตัวผู้ที่ไม่มีตําหนิ ให้เขานําเครื่องบูชานั้นมาที่ประตูพลับพลาแห่งชุมนุมด้วยความเต็มใจต่อพระพักตร์พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 4, 'ให้เขาเอามือวางบนหัวสัตว์ซึ่งเป็นเครื่องเผาบูชานั้น และเครื่องเผาบูชานั้นจะเป็นที่ทรงโปรดปรานเพื่อทําการลบมลทินของผู้นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 5, 'แล้วให้เขาฆ่าวัวตัวผู้นั้นต่อพระพักตร์พระเยโฮวาห์ แล้วพวกปุโรหิต คือบุตรชายของอาโรน จะถวายเลือด และเอาเลือดมาประพรมที่แท่นและรอบแท่นบูชา ซึ่งอยู่ตรงประตูพลับพลาแห่งชุมนุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 6, 'และให้เขาถลกหนังเครื่องเผาบูชานั้นออกเสีย แล้วตัดเป็นท่อนๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 7, 'และบุตรชายของอาโรนผู้เป็นปุโรหิตจะก่อไฟที่แท่น และเรียงฟืนบนไฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 8, 'และพวกปุโรหิต คือบุตรชายของอาโรน จะวางท่อนเนื้อ หัว และไขมันสัตว์ตามลําดับไว้บนฟืนบนไฟที่แท่นบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 9, 'แต่ให้เขาเอาน้ําล้างเครื่องในและขาสัตว์เสีย แล้วปุโรหิตจึงเผาของทั้งหมดบนแท่นเป็นเครื่องเผาบูชา เป็นเครื่องบูชาด้วยไฟ เป็นกลิ่นที่พอพระทัยแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 10, 'ถ้าของถวายที่ผู้ใดจะใช้เป็นเครื่องเผาบูชามาจากฝูงแกะหรือฝูงแพะ ให้ผู้นั้นเลือกเอาสัตว์ตัวผู้ที่ไม่มีตําหนิ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 11, 'ให้เขาฆ่าสัตว์นั้นเสียที่แท่นบูชาข้างด้านเหนือต่อพระพักตร์พระเยโฮวาห์ และพวกปุโรหิต คือบุตรชายของอาโรน จะเอาเลือดสัตว์นั้นประพรมที่แท่นและรอบแท่นบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 12, 'ให้เขาฟันสัตว์นั้นเป็นท่อนๆทั้งหัวและไขมันด้วย และปุโรหิตจะวางเครื่องเหล่านี้ตามลําดับไว้บนฟืนบนไฟที่แท่นบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 13, 'แต่เครื่องในกับขานั้นผู้ถวายบูชาจะล้างเสียด้วยน้ํา และให้ปุโรหิตเอาเครื่องทั้งหมดเหล่านี้เผาบูชาด้วยกันบนแท่น เป็นเครื่องเผาบูชา คือเป็นเครื่องบูชาด้วยไฟ เป็นกลิ่นที่พอพระทัยแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 14, 'ถ้าผู้ใดจะนํานกมาถวายเป็นเครื่องเผาบูชาแด่พระเยโฮวาห์ ก็ให้ผู้นั้นนําของบูชาที่เป็นนกเขาหรือนกพิราบหนุ่มมาถวาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 15, 'จงให้ปุโรหิตนํานกนั้นมาที่แท่น บิดหัวเสียแล้วเผาบูชาบนแท่น ให้เลือดไหลออกมาข้างๆแท่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 16, 'และให้ฉีกกระเพาะข้าวและถอนขนนกออกเสีย ทิ้งลงริมแท่นด้านตะวันออกในที่ที่ทิ้งมูลเถ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 17, 'และให้เขาฉีกปีกอย่าให้ขาดจากตัว และปุโรหิตจะเผานกนั้นบนแท่นที่กองฟืนบนไฟ เป็นเครื่องเผาบูชา คือเป็นเครื่องบูชาด้วยไฟ เป็นกลิ่นที่พอพระทัยแด่พระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 1, '“เมื่อผู้ใดนําธัญญบูชามาเป็นเครื่องบูชาถวายแด่พระเยโฮวาห์ ก็ให้ผู้นั้นนํายอดแป้งมาถวาย ให้เขาเทน้ํามันลงที่แป้งและใส่กํายานด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 2, 'แล้วนํามาให้พวกปุโรหิต คือบุตรชายของอาโรน ผู้ถวายบูชาจะหยิบยอดแป้งคลุกน้ํามันกํามือหนึ่งกับกํายานทั้งหมดออก และปุโรหิตจะเผาเครื่องบูชาส่วนนี้เป็นที่ระลึกบนแท่น คือบูชาด้วยไฟ เป็นกลิ่นที่พอพระทัยแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 3, 'ส่วนธัญญบูชาที่เหลืออยู่นั้นจะเป็นของอาโรนและบุตรชายของเขา เป็นส่วนบริสุทธิ์อย่างยิ่งจากเครื่องบูชาด้วยไฟถวายแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 4, 'เมื่อท่านนําธัญญบูชาเป็นขนมอบในเตาอบมาถวายเป็นเครื่องบูชา ให้เป็นขนมไร้เชื้อทําด้วยยอดแป้งคลุกน้ํามัน หรือขนมแผ่นไร้เชื้อทาน้ํามัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 5, 'และถ้าท่านนําธัญญบูชาเป็นขนมปิ้งบนกระทะ ก็ให้เป็นขนมทําด้วยยอดแป้งไร้เชื้อคลุกน้ํามัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 6, 'ท่านจงหักขนมนั้นเป็นชิ้นๆเทน้ํามันราด เป็นธัญญบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 7, 'ถ้าเครื่องบูชาของท่านเป็นธัญญบูชาทอดด้วยกระทะ ให้ทําด้วยยอดแป้งคลุกน้ํามัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 8, 'ท่านจงนําธัญญบูชาซึ่งทําด้วยสิ่งเหล่านี้มาถวายแด่พระเยโฮวาห์ เมื่อนํามาให้ปุโรหิตแล้วปุโรหิตจะนํามาถึงแท่นบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 9, 'และปุโรหิตจะนําส่วนที่ระลึกออกจากธัญญบูชา และเผาเสียบนแท่น เป็นเครื่องบูชาด้วยไฟ เป็นกลิ่นที่พอพระทัยแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 10, 'ส่วนธัญญบูชาที่เหลืออยู่นั้นตกเป็นของอาโรนและของบุตรชายท่าน เป็นส่วนบริสุทธิ์อย่างยิ่งจากเครื่องบูชาด้วยไฟถวายแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 11, 'บรรดาธัญญบูชาซึ่งนํามาถวายแด่พระเยโฮวาห์นั้นอย่าให้มีเชื้อ เจ้าอย่าเผาเชื้อหรือน้ําผึ้งเป็นเครื่องบูชาด้วยไฟถวายแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 12, 'ถ้าเจ้าจะนําสิ่งทั้งสองนี้เป็นผลรุ่นแรกมาถวายแด่พระเยโฮวาห์ก็ได้ แต่อย่าเผาถวายบนแท่นให้เป็นกลิ่นที่พอพระทัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 13, 'เจ้าจงปรุงบรรดาธัญญบูชาด้วยใส่เกลือ เจ้าอย่าให้เกลือแห่งพันธสัญญากับพระเจ้าของเจ้าขาดเสียจากธัญญบูชาของเจ้า เจ้าจงถวายเกลือพร้อมกับบรรดาเครื่องบูชาของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 14, 'ถ้าเจ้าถวายธัญญบูชาเป็นผลรุ่นแรกแด่พระเยโฮวาห์ ธัญญบูชาอันเป็นผลรุ่นแรกนั้นเจ้าจงถวายรวงใหม่ๆย่างไฟให้แห้ง บดเมล็ดให้ละเอียด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 15, 'เจ้าจงใส่น้ํามันและวางเครื่องกํายานไว้บนนั้น เป็นธัญญบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 16, 'ปุโรหิตจะเอาส่วนหนึ่งของเมล็ดที่บด น้ํามันและเครื่องกํายานเผาถวายเป็นส่วนที่ระลึก เป็นเครื่องบูชาด้วยไฟถวายแด่พระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 1, '“ถ้าผู้หนึ่งผู้ใดถวายเครื่องบูชาเป็นสันติบูชา ถ้าเขาถวายวัวผู้หรือวัวเมียจากฝูง ให้เขาถวายสัตว์ตัวที่ไม่มีตําหนิต่อพระพักตร์พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 2, 'ให้เขาเอามือวางบนหัวของสัตว์ตัวที่จะถวาย และจงฆ่าเสียที่ประตูพลับพลาแห่งชุมนุม พวกปุโรหิต คือบุตรชายของอาโรน จะเอาเลือดประพรมที่แท่นและรอบแท่นบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 3, 'จากเครื่องบูชาที่ถวายเป็นสันติบูชา เป็นเครื่องบูชาด้วยไฟถวายแด่พระเยโฮวาห์ ผู้ถวายจะนําไขมันที่ติดกับเครื่องในและไขมันที่อยู่ในเครื่องในทั้งหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 4, 'และไตทั้งสองลูกกับไขมันที่ติดอยู่ตรงบั้นเอวนั้น และให้เอาพังผืดที่ติดอยู่เหนือตับนั้นออกเสียพร้อมกับไต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 5, 'บุตรชายอาโรนจะเผาเสียบนแท่นบูชาบนเครื่องเผาบูชาซึ่งอยู่บนฟืนบนไฟ เป็นเครื่องบูชาด้วยไฟ เป็นกลิ่นที่พอพระทัยแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 6, 'ถ้าผู้ใดนําเครื่องบูชาที่เป็นสันติบูชามาถวายแด่พระเยโฮวาห์ เป็นสัตว์ตัวผู้หรือตัวเมียที่ได้มาจากฝูงแพะแกะ ก็อย่าให้สัตว์นั้นมีตําหนิ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 7, 'ถ้าเขาจะถวายลูกแกะเป็นเครื่องบูชาก็ให้เขานํามาถวายต่อพระพักตร์พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 8, 'ให้เขาเอามือวางบนหัวของสัตว์ที่จะถวายนั้นและให้ฆ่าเสียที่หน้าพลับพลาแห่งชุมนุม และบุตรชายอาโรนจะเอาเลือดประพรมที่แท่นและรอบแท่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 9, 'จากเครื่องบูชาที่ถวายเป็นสันติบูชา คือบูชาด้วยไฟถวายแด่พระเยโฮวาห์ ให้เขาถวายไขมัน หางที่เป็นไขมันทั้งหมดตัดชิดกระดูกสันหลังและไขมันที่หุ้มเครื่องใน กับไขมันที่อยู่ในเครื่องในทั้งหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 10, 'และไตทั้งสองลูกกับไขมันที่ติดอยู่ตรงบั้นเอวนั้น และให้เอาพังผืดที่ติดอยู่เหนือตับนั้นออกเสียพร้อมกับไต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 11, 'และปุโรหิตจะเอาสิ่งเหล่านี้เผาบนแท่น เป็นอาหารเผาด้วยไฟถวายแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 12, 'ถ้าเครื่องบูชาของเขาเป็นแพะก็ให้เขานํามาถวายต่อพระพักตร์พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 13, 'ให้เขาเอามือวางบนหัวของมันและฆ่ามันเสียที่หน้าพลับพลาแห่งชุมนุม และบุตรชายของอาโรนจะเอาเลือดประพรมที่แท่นและรอบแท่นบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 14, 'แล้วให้เขาเอาสิ่งเหล่านี้จากแพะตัวนั้นเป็นเครื่องบูชา เป็นเครื่องบูชาด้วยไฟถวายแด่พระเยโฮวาห์ คือไขมันที่หุ้มเครื่องใน และไขมันที่อยู่ในเครื่องใน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 15, 'และไตทั้งสองลูกกับไขมันที่ติดอยู่ตรงบั้นเอวนั้น และให้เอาพังผืดที่ติดอยู่เหนือตับนั้นออกเสียพร้อมกับไต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 16, 'และปุโรหิตจะเผาสิ่งเหล่านี้บนแท่นเป็นอาหารเผาไฟ เป็นกลิ่นที่พอพระทัย ไขมันทั้งหมดเป็นของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 17, 'ให้เป็นกฎเกณฑ์เนืองนิตย์ตลอดชั่วอายุของเจ้าในที่ที่เจ้าอาศัยอยู่ทั่วๆไปว่า เจ้าอย่ารับประทานไขมันหรือเลือด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 1, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 2, '“จงกล่าวแก่คนอิสราเอลว่า ถ้าผู้หนึ่งผู้ใดกระทําผิดสิ่งใดซึ่งพระเยโฮวาห์ได้ทรงบัญชามิให้กระทํา โดยเขามิได้เจตนากระทําสิ่งเหล่านั้นประการหนึ่งประการใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 3, 'ถ้าปุโรหิตที่ได้รับการเจิมไว้เป็นผู้กระทําบาป เป็นเหตุให้พลไพร่หลงทําบาปไปด้วย เหตุด้วยบาปที่เขาได้กระทําไป ก็ให้เขานําวัวหนุ่มซึ่งไม่มีตําหนิมาถวายแด่พระเยโฮวาห์เป็นเครื่องบูชาไถ่บาป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 4, 'ให้เขานําวัวนั้นมาที่ประตูพลับพลาแห่งชุมนุมต่อพระพักตร์พระเยโฮวาห์ และให้เขาเอามือวางบนหัววัวตัวนั้นและให้ฆ่ามันเสียต่อพระพักตร์พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 5, 'และปุโรหิตผู้ได้รับการเจิมแล้วจะนําเลือดวัวนั้นมาที่พลับพลาแห่งชุมนุมบ้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 6, 'ปุโรหิตจะเอานิ้วจุ่มลงในเลือด และประพรมเลือดนั้นที่หน้าม่านสถานบริสุทธิ์เจ็ดครั้งต่อพระพักตร์พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 7, 'และปุโรหิตจะเอาเลือดเล็กน้อยเจิมที่เชิงงอนของแท่นเผาเครื่องหอมซึ่งอยู่ในพลับพลาแห่งชุมนุมต่อพระพักตร์พระเยโฮวาห์ ส่วนเลือดวัวที่เหลืออยู่นั้นเขาจะเทลงที่ฐานแท่นเผาเครื่องเผาบูชาซึ่งอยู่ที่ประตูพลับพลาแห่งชุมนุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 8, 'และเขาจะเอาไขมันทั้งหมดออกเสียจากวัวตัวที่เป็นเครื่องบูชาไถ่บาปนี้ คือไขมันที่หุ้มเครื่องในและไขมันที่ติดอยู่กับเครื่องในทั้งหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 9, 'และไตทั้งสองลูกกับไขมันที่ติดอยู่ตรงบั้นเอวนั้น และให้เอาพังผืดที่ติดอยู่เหนือตับนั้นออกเสียพร้อมกับไต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 10, 'ให้เอาออกเช่นเดียวกับเอาออกจากวัวที่ถวายเป็นสันติบูชา และปุโรหิตจะเผาสิ่งเหล่านี้บนแท่นเครื่องเผาบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 11, 'แต่หนังของวัวพร้อมกับเนื้อวัวทั้งหมด หัว ขา เครื่องในและมูลของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 12, 'คือวัวทั้งตัวนี้ ให้เอาออกไปเสียจากค่ายถึงที่สะอาดที่ทิ้งมูลเถ้าและให้สุมไฟเผาเสีย ที่ทิ้งมูลเถ้าอยู่ที่ไหนก็ให้เผาที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 13, 'ถ้าชุมนุมชนอิสราเอลทั้งหมดกระทําผิดโดยไม่รู้ตัวและความผิดนั้นยังไม่ปรากฏแจ้งแก่ที่ประชุม และเขาได้กระทําสิ่งหนึ่งสิ่งใดซึ่งพระเยโฮวาห์บัญชามิให้กระทํา เขาก็มีความผิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 14, 'เมื่อความผิดที่เขาได้กระทํานั้นเป็นที่ประจักษ์ขึ้น ให้ที่ประชุมถวายวัวหนุ่มตัวหนึ่งเป็นเครื่องบูชาไถ่บาป ให้นําวัวนั้นมาที่หน้าพลับพลาแห่งชุมนุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 15, 'และผู้ใหญ่ของชุมนุมชนจะเอามือวางบนหัวของวัวนั้นต่อพระพักตร์พระเยโฮวาห์ และให้ฆ่าวัวตัวนั้นเสียต่อพระพักตร์พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 16, 'แล้วปุโรหิตผู้รับการเจิมจะนําเลือดของวัวมาที่พลับพลาแห่งชุมนุมบ้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 17, 'และปุโรหิตจะเอานิ้วจุ่มลงในเลือดและประพรมที่หน้าม่านเจ็ดครั้งต่อพระพักตร์พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 18, 'และปุโรหิตจะเอาเลือดสักหน่อยเจิมที่เชิงงอนของแท่นบูชาซึ่งอยู่ในพลับพลาแห่งชุมนุมต่อพระพักตร์พระเยโฮวาห์ ส่วนเลือดที่เหลืออยู่นั้น เขาจะเทลงที่ฐานแท่นเครื่องเผาบูชาซึ่งอยู่ที่ประตูพลับพลาแห่งชุมนุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 19, 'และเขาจะเอาไขมันออกจากวัวนั้นหมด นําไปเผาเสียบนแท่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 20, 'เขาจะกระทําดังนี้แก่วัวตัวนี้ เขาได้กระทํากับวัวตัวที่ถวายเป็นเครื่องบูชาไถ่บาปอย่างไร ก็ให้เขากระทําแก่วัวตัวนี้อย่างนั้น ดังนี้ปุโรหิตจะทําการลบมลทินของชุมนุมชนแล้วเขาทั้งหลายจะได้รับการอภัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 21, 'แล้วเขาจะนําวัวออกไปนอกค่าย และเผาเสียอย่างกับเผาวัวตัวก่อน เป็นเครื่องบูชาไถ่บาปของที่ประชุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 22, 'ถ้าผู้ครอบครองกระทําความบาป กระทําสิ่งซึ่งพระเยโฮวาห์พระเจ้าของเขาทรงบัญชามิให้กระทําโดยไม่รู้ตัว เขาก็มีความผิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 23, 'เมื่อเขารู้ตัวว่ากระทําผิดดังนั้นแล้ว ก็ให้เขานําลูกแพะตัวผู้ที่ไม่มีตําหนิตัวหนึ่งมาเป็นเครื่องบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 24, 'ให้เขาเอามือวางบนหัวแพะ และให้ฆ่าแพะเสียในที่ที่เขาฆ่าสัตว์เป็นเครื่องเผาบูชาต่อพระพักตร์พระเยโฮวาห์ นี่เป็นเครื่องบูชาไถ่บาป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 25, 'ปุโรหิตจะเอานิ้วจุ่มเลือดเครื่องบูชาไถ่บาปบ้าง นําไปเจิมที่เชิงงอนบนแท่นเครื่องเผาบูชา และเทเลือดที่เหลืออยู่นั้นที่ฐานของแท่นเครื่องเผาบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 26, 'และเขาจะเผาไขมันทั้งหมดบนแท่น เช่นเดียวกับเผาไขมันเครื่องสันติบูชา ดังนี้แหละปุโรหิตจะทําการลบมลทินแทนผู้กระทําผิดนั้น และเขาจะได้รับการอภัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 27, 'ถ้าพลไพร่สามัญคนหนึ่งคนใดกระทําความผิดโดยมิได้เจตนาคือกระทําสิ่งหนึ่งสิ่งใดซึ่งพระเยโฮวาห์ทรงบัญชามิให้เขากระทํา เขาก็มีความผิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 28, 'เมื่อเขารู้ตัวว่ากระทําผิดดังนั้นแล้ว ก็ให้เขานําลูกแพะตัวเมียตัวหนึ่งซึ่งไม่มีตําหนิมาเป็นเครื่องบูชาไถ่บาปที่เขาได้กระทําไปนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 29, 'และเขาจะเอามือวางบนหัวของเครื่องบูชาไถ่บาป และฆ่าเครื่องบูชาไถ่บาปนั้นในที่ที่เขาถวายเครื่องเผาบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 30, 'ปุโรหิตจะเอานิ้วจุ่มเลือดแพะนั้นไปเจิมที่เชิงงอนของแท่นเครื่องเผาบูชา และเทเลือดส่วนที่เหลือลงที่ฐานของแท่นนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 31, 'และเขาจะเอาไขมันออกเสียให้หมดอย่างที่เอาไขมันออกเสียจากเครื่องสันติบูชา และปุโรหิตจะเผาไขมันนั้นบนแท่น เป็นกลิ่นที่พอพระทัยแด่พระเยโฮวาห์ และปุโรหิตจะทําการลบมลทินของเขาและเขาจะได้รับการอภัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 32, 'ถ้าเขานําลูกแกะมาเป็นเครื่องบูชาไถ่บาปก็ให้เขานําลูกแกะตัวเมียไม่มีตําหนิมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 33, 'เขาจะเอามือวางบนหัวของเครื่องบูชาไถ่บาปและฆ่าเสียเป็นเครื่องบูชาไถ่บาปในที่ที่เขาฆ่าเครื่องเผาบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 34, 'และปุโรหิตจะเอานิ้วจุ่มเลือดเครื่องบูชาไถ่บาปนั้นบ้าง นําไปเจิมที่เชิงงอนของแท่นเครื่องเผาบูชา และเทเลือดที่เหลือนั้นลงที่ฐานของแท่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 35, 'และเขาจะเอาไขมันทั้งหมดออกเสียอย่างที่เอาไขมันของลูกแกะออกจากเครื่องสันติบูชา และปุโรหิตจะเผาไขมันบนแท่นเหมือนเครื่องบูชาด้วยไฟถวายแด่พระเยโฮวาห์ และปุโรหิตจะทําการลบมลทินของเขาซึ่งเขาได้กระทําผิด และเขาจะได้รับการอภัย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 1, '“ถ้าผู้ใดกระทําความผิดในข้อที่ได้ยินเสียงแห่งการสาบานตัวและเป็นพยาน และแม้ว่าเขาเป็นพยานโดยที่เขาเห็นหรือรู้เรื่องก็ตาม แต่เขาไม่ยอมให้การเป็นพยาน เขาต้องรับโทษความชั่วช้าของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 2, 'หรือผู้หนึ่งผู้ใดแตะต้องสิ่งที่เป็นมลทิน จะเป็นซากสัตว์ป่าที่มลทิน หรือซากสัตว์เลี้ยงที่มลทิน หรือซากสัตว์เลื้อยคลานที่เป็นมลทิน โดยไม่ทันรู้ตัว เขาจึงเป็นคนมีมลทิน เขาก็มีความผิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 3, 'หรือถ้าเขาแตะต้องมลทินของคน จะเป็นสิ่งใดๆซึ่งเป็นมลทิน อันเป็นสิ่งที่กระทําให้คนนั้นเป็นมลทิน โดยเขาไม่รู้ตัว เมื่อเขารู้แล้ว เขาก็มีความผิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 4, 'หรือถ้าคนหนึ่งคนใดเผลอตัวกล่าวคําสาบานด้วยริมฝีปากว่าจะกระทําชั่วหรือดี หรือเผลอตัวกล่าวคําสาบานใดๆ และเขากระทําโดยไม่ทันรู้ตัว เมื่อเขารู้สึกตัวแล้วในประการใดก็ตาม เขาก็มีความผิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 5, 'เมื่อผู้หนึ่งผู้ใดกระทําความผิดใดๆที่กล่าวมานี้ ก็ให้เขาสารภาพความผิดที่เขาได้กระทํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 6, 'และให้เขานําเครื่องบูชาไถ่การละเมิดมาถวายแด่พระเยโฮวาห์ เพราะบาปซึ่งเขาได้กระทํานั้น เครื่องบูชานั้นจะเป็นสัตว์ตัวเมียจากฝูง คือลูกแกะหรือลูกแพะ ก็เป็นเครื่องบูชาไถ่บาปได้ ดังนี้ปุโรหิตจะทําการลบมลทินแทนผู้ที่กระทําผิดนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 7, 'ถ้าเขาไม่สามารถถวายลูกแกะตัวหนึ่ง ก็ให้เขานํานกเขาสองตัวหรือนกพิราบหนุ่มสองตัว มาเป็นเครื่องบูชาถวายพระเยโฮวาห์ไถ่การละเมิด นกตัวหนึ่งเป็นเครื่องบูชาไถ่บาป และนกอีกตัวหนึ่งเป็นเครื่องเผาบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 8, 'ให้เขานํานกทั้งสองนี้มาให้ปุโรหิต ปุโรหิตก็ถวายนกตัวหนึ่งเป็นเครื่องบูชาไถ่บาปก่อน ให้เขาบิดหัวนกหลุดจากคอแต่อย่าให้ขาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 9, 'และปุโรหิตจะเอาเลือดเครื่องบูชาไถ่บาปประพรมที่ข้างแท่นเสียบ้าง ส่วนเลือดที่เหลืออยู่นั้นจะรีดให้ไหลออกที่ฐานแท่น นี่เป็นเครื่องบูชาไถ่บาป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 10, 'แล้วเขาจะถวายนกตัวที่สองเป็นเครื่องเผาบูชาตามลักษณะ และปุโรหิตจะทําการลบมลทินของเขาซึ่งเขาได้กระทําไปและเขาจะได้รับการอภัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 11, 'แต่ถ้าเขาไม่สามารถที่จะนํานกเขาสองตัวหรือนกพิราบหนุ่มสองตัวมา ก็ให้เขานําเครื่องบูชาไถ่บาปซึ่งเขาได้กระทํานั้นมา คือยอดแป้งหนึ่งในสิบเอฟาห์เอามาเป็นเครื่องบูชาไถ่บาป อย่าใส่น้ํามัน หรือใส่เครื่องกํายานในแป้ง เพราะเป็นเครื่องบูชาไถ่บาป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 12, 'ให้เขานําแป้งมาให้ปุโรหิตและปุโรหิตจะเอาแป้งกํามือหนึ่งเป็นส่วนที่ระลึก และเผาเสียบนแท่นเหมือนเครื่องเผาบูชาด้วยไฟถวายแด่พระเยโฮวาห์ เป็นเครื่องบูชาไถ่บาป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 13, 'และปุโรหิตจะทําการลบมลทินของเขาเพราะบาปซึ่งเขาได้กระทําในเรื่องหนึ่งเรื่องใดที่กล่าวมานี้ และเขาจะได้รับการอภัย และส่วนที่เหลือนั้นจะเป็นของปุโรหิต เช่นเดียวกับธัญญบูชา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 14, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 15, '“ถ้าผู้ใดทําการละเมิดและทําบาปโดยไม่รู้ตัวในเรื่องของบริสุทธิ์แห่งพระเยโฮวาห์ ให้ผู้นั้นนําแกะตัวผู้ที่ปราศจากตําหนิจากฝูงเป็นเครื่องบูชาไถ่การละเมิดถวายแด่พระเยโฮวาห์ ให้เจ้าตีราคาเป็นเงินเชเขลตามเชเขลของสถานบริสุทธิ์ เป็นเครื่องบูชาไถ่การละเมิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 16, 'และให้ผู้นั้นชดใช้ของบริสุทธิ์ที่ขาดไป และเพิ่มอีกหนึ่งในห้าของราคาสิ่งที่ขาดไปนั้น นํามามอบให้แก่ปุโรหิต และปุโรหิตจะทําการลบมลทินของเขาด้วยแกะผู้ที่ถวายเป็นเครื่องบูชาไถ่การละเมิด และเขาจะได้รับการอภัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 17, 'ถ้าผู้ใดกระทําผิด คือกระทําสิ่งที่พระเยโฮวาห์ทรงบัญชามิให้กระทํา ถึงแม้ว่าเขากระทําโดยไม่รู้เท่าถึงการณ์ เขาก็มีความผิดจะต้องรับโทษความชั่วช้าของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 18, 'ให้ผู้นั้นนําแกะตัวผู้ที่ปราศจากตําหนิมาจากฝูงมาถึงปุโรหิต ให้เจ้าตีราคา เป็นราคาเครื่องบูชาไถ่การละเมิด และให้ปุโรหิตทําการลบมลทินของเขาตามความผิดซึ่งเขาได้กระทําโดยไม่รู้เท่าถึงการณ์นั้นและเขาจะได้รับการอภัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 19, 'เป็นเครื่องบูชาไถ่การละเมิด เพราะเขาได้กระทําการละเมิดต่อพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 1, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 2, '“ถ้าผู้หนึ่งผู้ใดทําบาปและทําการละเมิดต่อพระเยโฮวาห์ ด้วยการมุสาต่อเพื่อนบ้านของเขาในสิ่งที่ฝากเขาให้เก็บรักษาไว้หรือในเรื่องมิตรภาพ หรือในสิ่งที่ใช้ความรุนแรงไปแย่งชิงมา หรือได้หลอกลวงเพื่อนบ้านของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 3, 'หรือพบสิ่งที่หายไปแล้วแต่ไม่ยอมรับ สาบานตนเป็นความเท็จ ในข้อเหล่านี้ถ้าผู้ใดกระทําก็เป็นความผิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 4, 'ก็ให้ผู้ที่กระทําผิดมีโทษเพราะความผิดของเขา ให้ผู้นั้นคืนของที่ได้มาจากการชิงมานั้นเสีย หรือสิ่งใดที่เขาได้มาด้วยการหลอกลวง หรือสิ่งที่ฝากเขาไว้ หรือสิ่งสูญหายที่เขาได้พบเข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 5, 'หรือสิ่งใดๆที่ได้สาบานเท็จไว้ เขาต้องคืนให้เต็มตามจํานวน และจงเพิ่มอีกหนึ่งในห้าและมอบให้แก่เจ้าของในวันที่เขาถวายเครื่องบูชาไถ่การละเมิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 6, 'ให้ผู้นั้นนําแกะตัวผู้ที่ไม่มีตําหนิมาจากฝูงเป็นเครื่องบูชาไถ่การละเมิดถวายแด่พระเยโฮวาห์มามอบให้ปุโรหิต ให้เจ้าตีราคาเอง เป็นราคาเครื่องบูชาไถ่การละเมิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 7, 'และให้ปุโรหิตทําการลบมลทินของเขาต่อพระพักตร์พระเยโฮวาห์ และเขาจะได้รับการอภัยในทุกสิ่งที่เขาได้กระทําไปซึ่งเป็นการละเมิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 8, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 9, '“จงบัญชาแก่อาโรนและบุตรชายของเขาว่า ต่อไปนี้เป็นพระราชบัญญัติเรื่องเครื่องเผาบูชา เครื่องเผาบูชานั้นจะต้องเผาอยู่บนแท่นตลอดคืนจนรุ่งเช้า จงให้ไฟบนแท่นเผาเครื่องบูชาลุกอยู่เรื่อยไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 10, 'ให้ปุโรหิตสวมเสื้อผ้าป่านและสวมกางเกงผ้าป่านและให้ตักมูลเถ้าออกจากไฟที่ไหม้เครื่องเผาบูชาอยู่บนแท่นนําไปไว้ข้างแท่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 11, 'ให้ถอดเสื้อที่สวมอยู่ออกแล้วสวมเสื้ออีกตัวหนึ่ง นํามูลเถ้าออกไปนอกค่ายยังที่สะอาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 12, 'ให้รักษาไฟที่บนแท่นให้ลุกอยู่ อย่าให้ดับเลยทีเดียว ให้ปุโรหิตใส่ฟืนทุกเช้าและให้เรียงเครื่องเผาบูชาให้เป็นระเบียบไว้บนแท่น และเผาไขมันของเครื่องสันติบูชาบนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 13, 'ต้องรักษาให้ไฟติดอยู่บนแท่นเรื่อยไป อย่าให้ดับเป็นอันขาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 14, 'ต่อไปนี้เป็นพระราชบัญญัติของการถวายธัญญบูชา ให้บุตรชายอาโรนถวายเครื่องบูชานี้ต่อพระพักตร์พระเยโฮวาห์ที่หน้าแท่นบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 15, 'ให้ปุโรหิตคนหนึ่งหยิบยอดแป้งกํามือหนึ่งมาจากธัญญบูชา คลุกน้ํามันและเครื่องกํายานทั้งหมดซึ่งอยู่บนธัญญบูชา และเผาส่วนนี้บนแท่นเป็นที่ระลึก เป็นกลิ่นที่พอพระทัยแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 16, 'ส่วนที่เหลืออยู่ให้อาโรนและบุตรชายของเขารับประทาน ให้รับประทานกับขนมปังไร้เชื้อในที่บริสุทธิ์ ให้รับประทานในลานของพลับพลาแห่งชุมนุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 17, 'อย่าใส่เชื้อในขนมนั้นแล้วปิ้ง เราได้ให้ส่วนนี้เป็นส่วนเครื่องบูชาด้วยไฟของเราอันตกแก่เขาเป็นสิ่งบริสุทธิ์ที่สุด เช่นเดียวกับเครื่องบูชาไถ่บาป และเครื่องบูชาไถ่การละเมิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 18, 'ให้บุตรชายทั้งหลายของอาโรนรับประทานสิ่งนี้ เป็นกฎเกณฑ์ถาวรตลอดชั่วอายุของเจ้าจากเครื่องบูชาด้วยไฟของพระเยโฮวาห์ ผู้ใดที่ถูกต้องสิ่งเหล่านี้จะบริสุทธิ์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 19, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 20, '“ต่อไปนี้เป็นเครื่องบูชาที่อาโรนและบุตรชายทั้งหลายของเขาจะต้องถวายแด่พระเยโฮวาห์ในวันที่เขารับการเจิม คือยอดแป้งหนึ่งในสิบเอฟาห์เป็นธัญญบูชาประจํา ให้ถวายตอนเช้าครึ่งหนึ่ง ตอนเย็นครึ่งหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 21, 'ให้คลุกกับน้ํามันให้เข้ากันดีแล้วทอดบนเหล็ก ทําเป็นแผ่นเหมือนธัญญบูชาแล้วถวายเป็นกลิ่นที่พอพระทัยแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 22, 'ให้ปุโรหิตจากบรรดาบุตรชายของอาโรนผู้รับการเจิมตั้งแทนเขาถวายสิ่งนี้ เป็นกฎเกณฑ์สืบไปเนืองนิตย์แด่พระเยโฮวาห์ ให้เผาเครื่องบูชาทั้งหมดเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 23, 'ธัญญบูชาของปุโรหิตทุกรายให้เผาเสียให้หมด อย่าให้รับประทาน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 24, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 25, '“จงกล่าวแก่อาโรนและบุตรชายของเขาว่า ต่อไปนี้เป็นพระราชบัญญัติของการถวายเครื่องบูชาไถ่บาป ให้ฆ่าสัตว์ที่เป็นเครื่องบูชาไถ่บาปในที่ที่ฆ่าสัตว์อันเป็นเครื่องเผาบูชาต่อพระพักตร์พระเยโฮวาห์ เป็นของบริสุทธิ์ที่สุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 26, 'ให้ปุโรหิตผู้ถวายเครื่องบูชาไถ่บาปรับประทานสัตว์นั้น ให้เขารับประทานในที่บริสุทธิ์ ในลานพลับพลาแห่งชุมนุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 27, 'อะไรที่แตะต้องเนื้อสัตว์นั้นจะบริสุทธิ์ และเมื่อประพรมมีเลือดติดเสื้อ ก็ให้ซักเสื้อส่วนที่ติดเลือดนั้นในที่บริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 28, 'จงทําลายภาชนะดินที่ใช้ต้มเนื้อนั้นเสีย ถ้าต้มในภาชนะทองเหลืองก็ให้ขัดและล้างเสียด้วยน้ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 29, 'ผู้ชายทุกคนที่เป็นปุโรหิตรับประทานได้ เป็นของบริสุทธิ์ที่สุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 30, 'แต่เครื่องบูชาไถ่บาป ซึ่งปุโรหิตนําเลือดเข้าไปในพลับพลาแห่งชุมนุม เพื่อทําการลบมลทินในที่บริสุทธิ์นั้น อย่ารับประทานเลย ต้องเผาไฟเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 1, '“เช่นเดียวกันนี่เป็นพระราชบัญญัติเรื่องเครื่องบูชาไถ่การละเมิด เป็นสิ่งบริสุทธิ์ที่สุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 2, 'ให้ฆ่าสัตว์อันเป็นเครื่องบูชาไถ่การละเมิดในที่ที่ฆ่าสัตว์อันเป็นเครื่องเผาบูชา และให้เอาเลือดสัตว์นั้นประพรมที่แท่นและรอบแท่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 3, 'และให้เอาไขมันของสัตว์นั้นถวายบูชาเสียทั้งหมดด้วย หางที่เป็นไขมัน ไขมันที่หุ้มเครื่องใน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 4, 'และไตทั้งสองลูกกับไขมันที่ติดอยู่ตรงบั้นเอวนั้น และให้เอาพังผืดที่ติดอยู่เหนือตับนั้นออกเสียพร้อมกับไต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 5, 'ให้ปุโรหิตเผาสิ่งเหล่านี้บนแท่นเป็นเครื่องบูชาด้วยไฟถวายแด่พระเยโฮวาห์ เป็นเครื่องบูชาไถ่การละเมิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 6, 'ผู้ชายทุกคนที่เป็นปุโรหิตรับประทานได้ ให้รับประทานในสถานบริสุทธิ์ เป็นของบริสุทธิ์ที่สุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 7, 'เครื่องบูชาไถ่การละเมิดก็เหมือนเครื่องบูชาไถ่บาป มีพระราชบัญญัติอย่างเดียวกัน ปุโรหิตผู้ใช้เครื่องบูชาทําการลบมลทินจะได้เครื่องบูชานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 8, 'ปุโรหิตคนใดถวายเครื่องเผาบูชาของผู้ใด ปุโรหิตผู้นั้นย่อมได้หนังของเครื่องเผาบูชาที่ตนถวาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 9, 'เครื่องธัญญบูชาทุกอย่างที่ปิ้งในเตาอบ และสิ่งทั้งหมดซึ่งเตรียมในกระทะหรือที่เหล็ก ให้ตกเป็นของปุโรหิตผู้ถวายของเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 10, 'ธัญญบูชาทุกอย่างที่เคล้าน้ํามันหรือไม่เคล้าจะตกเป็นของบุตรชายอาโรนทั่วกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 11, 'ต่อไปนี้เป็นพระราชบัญญัติเรื่องเครื่องสันติบูชาซึ่งผู้หนึ่งผู้ใดนํามาถวายแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 12, 'ถ้าเขาถวายเป็นเครื่องโมทนาพระคุณ ก็ให้เขาถวายขนมไร้เชื้อคลุกน้ํามัน ขนมแผ่นไร้เชื้อทาน้ํามัน ขนมยอดแป้งคลุกน้ํามันให้ดีพร้อมกับเครื่องบูชาโมทนา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 13, 'นอกจากขนมเหล่านี้ให้เขานําขนมปังใส่เชื้อมาถวายเป็นส่วนของเครื่องบูชา พร้อมกับเครื่องสันติบูชาที่ถวายเป็นการโมทนาพระคุณ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 14, 'ให้เขาถวายของบูชาเหล่านี้ส่วนหนึ่งจากทั้งหมดแด่พระเยโฮวาห์ ซึ่งเป็นส่วนยกให้แก่ปุโรหิตผู้เอาเลือดสันติบูชาประพรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 15, 'ส่วนเนื้อสัตว์เครื่องสันติบูชาเพื่อโมทนาพระคุณนั้น เขาจะต้องรับประทานเสียในวันทําการถวายบูชา อย่าเหลือไว้จนวันรุ่งเช้าเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 16, 'แต่ถ้าเครื่องบูชานั้นเป็นเครื่องบูชาปฏิญาณ หรือเป็นเครื่องบูชาตามใจสมัคร ให้เขารับประทานเสียในวันทําการถวายบูชา และในวันรุ่งขึ้นเขายังรับประทานส่วนที่เหลือได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 17, 'ส่วนเนื้อของเครื่องบูชาที่เหลือถึงวันที่สามให้เผาเสียด้วยไฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 18, 'ถ้าเอาเนื้อสัตว์อันเป็นเครื่องสันติบูชามารับประทานในวันที่สาม ก็จะไม่เป็นที่พอพระทัยเลย และผู้ที่ถวายนั้นจะไม่เป็นที่โปรดปรานด้วย แต่จะเป็นการกระทําที่น่าสะอิดสะเอียน และผู้ที่รับประทานนั้นจะต้องได้รับโทษความชั่วช้าของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 19, 'เนื้อที่ไปถูกของที่เป็นมลทินใดๆ อย่ารับประทาน จงเผาเสียด้วยไฟ บุคคลที่สะอาดทุกคนรับประทานเนื้อได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 20, 'แต่ผู้ใดรับประทานเนื้อสัตวบูชาอันเป็นเครื่องสันติบูชาแด่พระเยโฮวาห์โดยที่ตนยังมีมลทินติดตัวอยู่ ผู้นั้นจะต้องถูกตัดขาดจากพลไพร่ของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 21, 'ยิ่งกว่านั้นอีกถ้าผู้ใดแตะต้องสิ่งมลทินใดๆ ไม่ว่าจะเป็นมลทินของคน หรือสัตว์มลทินใดๆ หรือสิ่งมลทินที่น่าสะอิดสะเอียนใดๆ และผู้นั้นมารับประทานเนื้อสัตวบูชาอันเป็นเครื่องสันติบูชาแด่พระเยโฮวาห์ ผู้นั้นจะต้องถูกตัดขาดจากพลไพร่ของตน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 22, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 23, '“จงกล่าวแก่คนอิสราเอลว่า เจ้าทั้งหลายอย่ารับประทานไขมันของวัว ของแกะหรือของแพะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 24, 'ไขมันของสัตว์ที่ตายเอง และไขมันของสัตว์ที่สัตว์กัดตายจะนําไปใช้อย่างอื่นก็ได้ แต่อย่ารับประทานเลยเป็นอันขาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 25, 'ด้วยผู้ใดก็ตามรับประทานไขมันสัตว์อันเป็นเครื่องบูชาด้วยไฟถวายแด่พระเยโฮวาห์ ผู้ที่รับประทานนั้นจะต้องถูกตัดขาดจากพลไพร่ของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 26, 'ยิ่งกว่านั้นอีกเจ้าอย่ารับประทานเลือดเลยทีเดียว ไม่ว่าเลือดของสัตว์ปีกหรือเลือดสัตว์ในที่ใดๆที่เจ้าอาศัยอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 27, 'ผู้ใดก็ตามที่รับประทานเลือดในลักษณะใดลักษณะหนึ่ง ผู้นั้นจะต้องถูกตัดขาดจากพลไพร่ของตน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 28, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 29, '“จงกล่าวแก่คนอิสราเอลว่า ผู้ใดจะถวายเครื่องบูชาอันเป็นสันติบูชาแด่พระเยโฮวาห์ ให้ผู้นั้นนําเครื่องบูชาของเขามาถวายแด่พระเยโฮวาห์จากเครื่องบูชาอันเป็นสันติบูชาของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 30, 'ให้เขานําเครื่องถวายบูชาด้วยไฟแด่พระเยโฮวาห์มาด้วยมือของตนเอง ให้เขานําไขมันมาพร้อมกับเนื้ออกนั้น เพื่อเอาเนื้ออกนั้นแกว่งไปแกว่งมาเป็นเครื่องบูชาแกว่งถวายต่อพระพักตร์พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 31, 'ให้ปุโรหิตเผาไขมันเสียบนแท่นบูชา แต่เนื้ออกนั้นจะตกเป็นของอาโรนและบุตรชายของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 32, 'แต่โคนขาข้างขวาของสัตว์นั้นเจ้าจงให้ปุโรหิตเป็นส่วนถวายจากเครื่องบูชาแห่งสันติบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 33, 'บุตรชายอาโรนผู้ถวายเลือดแห่งสันติบูชาและไขมันจะได้รับโคนขาข้างขวาเป็นส่วนของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 34, 'เพราะว่าเนื้ออกที่แกว่งถวาย และเนื้อโคนขาที่ถวายนั้นเราได้เอาจากคนอิสราเอลจากเครื่องสันติบูชาของเขา และเราได้มอบให้แก่อาโรนปุโรหิตและบุตรชายของเขาเป็นกฎเกณฑ์อันถาวรจากคนอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 35, 'นี่เป็นส่วนจากการเจิมอาโรนและการเจิมบุตรชายของเขา ได้จากเครื่องบูชาด้วยไฟถวายแด่พระเยโฮวาห์ มอบหมายให้แก่เขาทั้งหลายในวันที่เขาทั้งหลายถูกถวายให้ปรนนิบัติพระเยโฮวาห์ในตําแหน่งปุโรหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 36, 'ซึ่งพระเยโฮวาห์ทรงบัญชาคนอิสราเอลให้มอบสิ่งเหล่านี้แก่เขาทั้งหลาย ในวันที่เขาทั้งหลายได้รับการเจิมเป็นปุโรหิต เป็นกฎเกณฑ์อันถาวรตลอดชั่วอายุของเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 37, 'ทั้งหมดนี้เป็นพระราชบัญญัติเรื่องเครื่องเผาบูชา เครื่องธัญญบูชา เครื่องบูชาไถ่บาป เครื่องบูชาไถ่การละเมิด เครื่องสถาปนาบูชา และเครื่องสันติบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 38, 'ซึ่งพระเยโฮวาห์ทรงบัญชาโมเสสบนภูเขาซีนาย ในวันที่พระองค์ทรงบัญชาคนอิสราเอลให้นําเครื่องบูชามาถวายแด่พระเยโฮวาห์ในถิ่นทุรกันดารซีนาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 1, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 2, '“จงนําอาโรนและบุตรชายของเขามาพร้อมกับเสื้อยศ น้ํามันเจิม วัวอันเป็นเครื่องบูชาไถ่บาป แกะผู้สองตัว กระบุงขนมปังไร้เชื้อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 3, 'และจงเรียกชุมนุมชนทั้งหมดให้ประชุมกันที่ประตูพลับพลาแห่งชุมนุม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 4, 'และโมเสสก็กระทําดังที่พระเยโฮวาห์ทรงบัญชาแก่ท่าน และชุมนุมชนก็ประชุมกันที่ประตูพลับพลาแห่งชุมนุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 5, 'โมเสสกล่าวแก่ชุมนุมชนว่า “ต่อไปนี้เป็นสิ่งซึ่งพระเยโฮวาห์ทรงบัญชาให้กระทํา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 6, 'โมเสสก็นําอาโรนและบุตรชายทั้งหลายของเขามาชําระกายด้วยน้ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 7, 'แล้วสวมเสื้อให้และคาดรัดประคดให้ แล้วสวมเสื้อคลุมยาวให้ และสวมเอโฟดให้เขา เอารัดประคดทออย่างประณีตสําหรับคาดทับเอโฟดคาดเอวให้ ผูกเอโฟดให้ติดตัวเขาไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 8, 'และโมเสสสวมทับทรวงให้อาโรน และใส่อูริมกับทูมมิมไว้ในทับทรวงนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 9, 'และสวมผ้ามาลาไว้บนศีรษะ และติดแผ่นทองคําอันเป็นมงกุฎบริสุทธิ์ที่ผ้ามาลาด้านหน้า ดังที่พระเยโฮวาห์ทรงบัญชาโมเสสไว้นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 10, 'แล้วโมเสสนําน้ํามันเจิมมาเจิมพลับพลาและทุกสิ่งที่อยู่ในนั้น ชําระให้เป็นของบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 11, 'และท่านเอาน้ํามันเจิมประพรมบนแท่นเจ็ดครั้ง เจิมแท่นและเจิมภาชนะประจําแท่นทั้งหมด เจิมขันและพานรองขันเพื่อชําระให้เป็นของบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 12, 'และท่านเทน้ํามันเจิมลงบนศีรษะของอาโรนบ้าง แล้วเจิมเขาไว้เพื่อชําระให้บริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 13, 'และโมเสสก็นําบุตรชายอาโรนเข้ามาสวมเสื้อแล้วคาดรัดประคดให้ และสวมมาลาให้ ดังที่พระเยโฮวาห์ทรงบัญชาโมเสสไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 14, 'แล้วท่านจึงนําวัวตัวผู้อันเป็นเครื่องบูชาไถ่บาปเข้ามา อาโรนและบุตรชายทั้งหลายของเขาก็เอามือของตนวางบนหัววัวอันเป็นเครื่องบูชาไถ่บาปนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 15, 'โมเสสก็ฆ่าวัวตัวนั้นเสีย เอานิ้วจุ่มเลือดไปเจิมที่เชิงงอนรอบแท่น ชําระแท่นให้บริสุทธิ์แล้วเทเลือดที่ฐานของแท่น ถวายแท่นไว้เป็นสิ่งบริสุทธิ์ เพื่อทําการลบมลทินของแท่นนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 16, 'และท่านนําไขมันทั้งหมดที่อยู่กับเครื่องในและพังผืดเหนือตับ และไตสองลูกพร้อมกับไขมันแล้วโมเสสก็เผาสิ่งเหล่านี้เสียบนแท่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 17, 'แต่วัวและหนังวัว กับเนื้อและมูลของมัน ท่านเผาเสียด้วยไฟข้างนอกค่าย ดังที่พระเยโฮวาห์ทรงบัญชาโมเสสไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 18, 'แล้วท่านก็นําแกะผู้อันเป็นเครื่องเผาบูชาเข้ามา อาโรนกับบุตรชายทั้งหลายของเขาก็เอามือของตนวางบนหัวของแกะผู้นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 19, 'โมเสสก็ฆ่าแกะนั้นเสีย เอาเลือดประพรมที่แท่นและรอบแท่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 20, 'เมื่อท่านฟันแกะออกเป็นท่อนๆ โมเสสก็เผาหัวและแกะที่เป็นท่อนๆกับไขมันเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 21, 'เมื่อเอาน้ําล้างเครื่องในและขาแกะแล้ว โมเสสก็เผาแกะทั้งตัวบนแท่น เป็นเครื่องเผาบูชา เป็นกลิ่นที่พอพระทัย เป็นเครื่องบูชาด้วยไฟถวายแด่พระเยโฮวาห์ ดังที่พระเยโฮวาห์ทรงบัญชาโมเสส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 22, 'ท่านจึงนําแกะผู้อีกตัวหนึ่งนั้นเข้ามาคือแกะตัวผู้ที่เป็นเครื่องสถาปนา และอาโรนกับบุตรชายทั้งหลายของเขาก็เอามือของตนวางบนหัวของแกะผู้นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 23, 'โมเสสก็ฆ่าแกะนั้นเสีย เอาเลือดเจิมที่ปลายหูข้างขวาของอาโรน และที่นิ้วหัวแม่มือขวาของเขา และที่นิ้วหัวแม่เท้าขวาของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 24, 'แล้วนําบุตรชายทั้งหลายของอาโรนเข้ามา และโมเสสเอาเลือดเจิมที่ปลายหูข้างขวา ที่นิ้วหัวแม่มือข้างขวา ที่นิ้วหัวแม่เท้าข้างขวาของเขา และโมเสสเอาเลือดประพรมที่แท่นและรอบแท่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 25, 'แล้วท่านจึงนําไขมันและหางที่เป็นไขมัน และไขมันทั้งหมดที่อยู่กับเครื่องใน และพังผืดเหนือตับและไตสองลูกกับไขมันที่ติดอยู่ และโคนขาข้างขวา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 26, 'และท่านหยิบขนมไร้เชื้อหนึ่งก้อนจากกระบุงขนมปังไร้เชื้อ ซึ่งอยู่ต่อพระพักตร์พระเยโฮวาห์ และหยิบขนมคลุกน้ํามันก้อนหนึ่ง และขนมแผ่นแผ่นหนึ่ง วางของเหล่านี้ไว้บนไขมัน และบนโคนขาข้างขวา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 27, 'ท่านเอาสิ่งเหล่านี้วางไว้ในมือของอาโรน และมือของบุตรชายทั้งหลายของเขา และให้แกว่งไปแกว่งมาเป็นเครื่องบูชาแกว่งถวายต่อพระพักตร์พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 28, 'แล้วโมเสสก็รับของเหล่านั้นมาจากมือของเขาทั้งหลายและเผาเสียบนแท่นบนเครื่องเผาบูชา เป็นเครื่องสถาปนาบูชา เป็นกลิ่นที่พอพระทัย เป็นเครื่องบูชาด้วยไฟถวายแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 29, 'และโมเสสเอาเนื้ออกแกว่งไปแกว่งมาเป็นเครื่องแกว่งถวายต่อพระพักตร์พระเยโฮวาห์ นี่เป็นแกะตัวผู้สถาปนาส่วนของโมเสส ดังที่พระเยโฮวาห์ทรงบัญชาโมเสส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 30, 'แล้วโมเสสนําน้ํามันเจิมและเลือดซึ่งอยู่บนแท่น ประพรมบนอาโรนและเครื่องยศของเขา และบนบุตรชายทั้งหลาย กับบนเครื่องยศของบุตรชายทั้งหลายของเขา ดังนี้แหละท่านก็ชําระอาโรนกับเครื่องยศของเขาให้บริสุทธิ์ บุตรชายทั้งหลายของเขากับเครื่องยศของบุตรชายนั้นด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 31, 'โมเสสสั่งอาโรนและบุตรชายทั้งหลายของเขาว่า “จงต้มเนื้อเสียที่ประตูพลับพลาแห่งชุมนุม และรับประทานเสียที่นั่นกับขนมปังซึ่งอยู่ในกระบุงเครื่องสถาปนาบูชา ดังที่ข้าพเจ้าบัญชาท่านว่า อาโรนและบุตรชายทั้งหลายของเขาจะรับประทาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 32, 'เนื้อและขนมปังที่เหลือนั้นท่านจงเผาเสียด้วยไฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 33, 'และท่านทั้งหลายอย่าออกไปนอกประตูพลับพลาแห่งชุมนุมตลอดเจ็ดวัน จนกว่าวันกําหนดสถาปนาของท่านจะครบ เพราะที่จะสถาปนาท่านนั้นก็กินเวลาเจ็ดวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 34, 'สิ่งที่ได้กระทําในวันนี้ พระเยโฮวาห์ทรงบัญชาให้กระทําเพื่อลบมลทินของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 35, 'ท่านจงอยู่ที่ประตูพลับพลาแห่งชุมนุมทั้งกลางวันและกลางคืนตลอดเจ็ดวัน กระทํากิจที่พระเยโฮวาห์ทรงกําชับไว้ เกลือกว่าท่านจะต้องถึงตาย เพราะนี่เป็นสิ่งที่ข้าพเจ้าได้รับบัญชามา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 36, 'อาโรนกับบุตรชายทั้งหลายของเขาได้กระทําตามที่พระเยโฮวาห์ทรงบัญชาทางโมเสสทุกประการ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 1, 'ต่อมาวันที่แปดโมเสสก็เรียกอาโรนและบุตรชายทั้งหลายของเขา และพวกผู้ใหญ่ของอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 2, 'และท่านกล่าวแก่อาโรนว่า “จงนําลูกวัวตัวหนึ่งเป็นเครื่องบูชาไถ่บาป และแกะผู้ตัวหนึ่งเป็นเครื่องเผาบูชา ทั้งสองอย่าให้มีตําหนิ จงถวายบูชาต่อพระพักตร์พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 3, 'และกล่าวแก่คนอิสราเอลว่า ‘จงเอาลูกแพะผู้ตัวหนึ่งเป็นเครื่องบูชาไถ่บาป และลูกวัวตัวหนึ่งกับลูกแกะตัวหนึ่ง ทั้งสองให้มีอายุหนึ่งขวบ ปราศจากตําหนิเป็นเครื่องเผาบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 4, 'และเอาวัวผู้ตัวหนึ่งและแกะผู้ตัวหนึ่งเป็นสันติบูชาถวายต่อพระพักตร์พระเยโฮวาห์ และเอาธัญญบูชาคลุกน้ํามันมาถวาย เพราะว่าพระเยโฮวาห์จะทรงปรากฏแก่ท่านในวันนี้’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 5, 'เขาทั้งหลายก็นําสิ่งที่โมเสสบัญชานั้นมาที่หน้าพลับพลาแห่งชุมนุม และชุมนุมชนทั้งหมดก็เข้ามาใกล้ ยืนอยู่ต่อพระพักตร์พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 6, 'โมเสสกล่าวว่า “นี่เป็นสิ่งซึ่งพระเยโฮวาห์ทรงบัญชาให้ท่านทั้งหลายกระทํา และสง่าราศีของพระเยโฮวาห์จะปรากฏแก่ท่านทั้งหลาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 7, 'แล้วโมเสสจึงสั่งอาโรนว่า “จงเข้าไปใกล้แท่นบูชา ถวายเครื่องบูชาไถ่บาป และเครื่องเผาบูชาของท่านเสีย และทําการลบมลทินบาปของตัวท่านกับพลไพร่ทั้งหลาย และจงนําเครื่องถวายบูชาของพลไพร่มา และทําการลบมลทินบาปของเขา ดังที่พระเยโฮวาห์ทรงบัญชา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 8, 'อาโรนจึงเข้าไปใกล้แท่นบูชาและฆ่าลูกวัวอันเป็นเครื่องบูชาไถ่บาปซึ่งเป็นของเพื่อตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 9, 'และบุตรชายอาโรนก็นําเลือดมาให้เขา เขาก็เอานิ้วจุ่มเลือดไปเจิมเชิงงอนของแท่น และเทเลือดลงที่ฐานแท่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 10, 'ส่วนไขมันและไต กับพังผืดเหนือตับจากเครื่องบูชาไถ่บาปนั้น เขาเผาเสียบนแท่น ดังที่พระเยโฮวาห์ทรงบัญชาโมเสส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 11, 'เขาก็เผาเนื้อและหนังเสียด้วยไฟที่ภายนอกค่าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 12, 'เขาฆ่าสัตว์เครื่องเผาบูชา แล้วบุตรชายอาโรนก็นําเลือดมาให้เขา เขาจึงเอาเลือดนั้นประพรมที่แท่นและรอบแท่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 13, 'และบุตรชายทั้งหลายของอาโรนก็ส่งเครื่องเผาบูชาทีละท่อนกับหัวมาให้อาโรน อาโรนก็เผาสิ่งเหล่านี้บนแท่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 14, 'อาโรนจึงล้างเครื่องในและขาสัตว์และเผาเสียบนเครื่องเผาบูชาที่บนแท่นบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 15, 'แล้วอาโรนก็นําเครื่องบูชาของพลไพร่มาถวาย คือนําแพะซึ่งเป็นเครื่องบูชาไถ่บาปซึ่งเป็นของเพื่อพลไพร่มาฆ่าเสียบูชาไถ่บาป ดังเครื่องบูชาไถ่บาปครั้งก่อนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 16, 'และเขาก็ถวายเครื่องเผาบูชาถวายตามลักษณะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 17, 'และเขาก็ถวายธัญญบูชาโดยหยิบมากํามือหนึ่งเผาเสียบนแท่นนอกเหนือเครื่องเผาบูชาประจําเวลาเช้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 18, 'เขาฆ่าวัวผู้ด้วย และแกะผู้เป็นเครื่องสันติบูชาสําหรับพลไพร่ และบุตรชายอาโรนนําเลือดมาให้อาโรน อาโรนก็เอาเลือดประพรมที่แท่นและรอบแท่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 19, 'และนําไขมันวัวและไขมันแกะ กับหางที่เป็นไขมัน และไขมันที่หุ้มเครื่องใน และไตกับพังผืดเหนือตับมาให้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 20, 'และเขาทั้งหลายวางไขมันไว้บนเนื้ออก และอาโรนก็เผาไขมันเสียบนแท่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 21, 'ส่วนเนื้ออกและเนื้อโคนขาข้างขวานั้น อาโรนแกว่งไปแกว่งมาเป็นเครื่องบูชาแกว่งถวายต่อพระพักตร์พระเยโฮวาห์ ดังที่โมเสสบัญชาไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 22, 'แล้วอาโรนยกมือขึ้นอวยพรพลไพร่ และอาโรนก็ลงมาจากการถวายเครื่องบูชาไถ่บาป เครื่องเผาบูชาและสันติบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 23, 'โมเสสกับอาโรนจึงเข้าไปในพลับพลาแห่งชุมนุม เมื่อเขาทั้งสองออกมา เขาก็อวยพรพลไพร่ และสง่าราศีของพระเยโฮวาห์ก็ปรากฏแก่พลไพร่ทั้งมวล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 24, 'เปลวเพลิงพลุ่งออกมาต่อพระพักตร์พระเยโฮวาห์ เผาเครื่องเผาบูชาและไขมันซึ่งอยู่บนแท่น เมื่อพลไพร่ทั้งหลายเห็นก็โห่ร้องและซบหน้าลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 1, 'ฝ่ายนาดับกับอาบีฮูบุตรชายของอาโรน ต่างนํากระถางไฟของเขามาและเอาไฟใส่ในนั้นแล้วใส่เครื่องหอมลง เอาไฟที่ผิดรูปแบบมาเผาถวายบูชาต่อพระพักตร์พระเยโฮวาห์ ซึ่งพระองค์มิได้ทรงบัญชาให้เขากระทําเช่นนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 2, 'ไฟก็พุ่งขึ้นมาจากพระเยโฮวาห์ ไหม้เขาทั้งสองและเขาก็ตายต่อพระพักตร์พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 3, 'โมเสสจึงบอกอาโรนว่า “พระเยโฮวาห์ตรัสดังนี้ว่า ‘เราจะสําแดงความบริสุทธิ์ของเราท่ามกลางผู้ที่อยู่ใกล้เรา เขาจะถวายสง่าราศีแก่เราต่อหน้าพลไพร่ทั้งปวง’” และอาโรนก็นิ่งอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 4, 'โมเสสเรียกมิชาเอลและเอลซาฟาน บุตรชายของอุสซีเอล อาของอาโรน บอกเขาว่า “จงเข้ามาใกล้ หามเอาพี่น้องของเจ้าออกไปเสียนอกค่ายจากหน้าสถานบริสุทธิ์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 5, 'เขาก็เข้ามาใกล้หามศพทั้งเสื้อออกไปไว้นอกค่ายตามที่โมเสสสั่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 6, 'และโมเสสกล่าวแก่อาโรนและเอเลอาซาร์และอิธามาร์ บุตรชายอาโรนว่า “ท่านทั้งหลายอย่าปล่อยผมห้อย หรือฉีกเสื้อผ้าของท่าน เกลือกว่าท่านจะต้องตายและเกลือกว่าพระพิโรธจะตกเหนือชุมนุมชนทั้งหมด แต่พี่น้องของท่านคือวงศ์วานอิสราเอลทั้งมวล จะไว้ทุกข์เพราะพระเยโฮวาห์ทรงให้บังเกิดการเผาไหม้ก็ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 7, 'และอย่าออกไปจากประตูพลับพลาแห่งชุมนุม เกลือกว่าท่านต้องตาย เพราะว่าน้ํามันเจิมแห่งพระเยโฮวาห์อยู่เหนือท่านทั้งหลาย” และเขาทั้งหลายก็กระทําตามคําของโมเสส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 8, 'พระเยโฮวาห์ตรัสกับอาโรนว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 9, '“เมื่อตัวเจ้าหรือบุตรชายของเจ้าจะเข้าไปในพลับพลาแห่งชุมนุม อย่าดื่มเหล้าองุ่นหรือสุราเกลือกว่าเจ้าจะต้องตาย ทั้งนี้ให้เป็นกฎเกณฑ์ถาวรอยู่ตลอดชั่วอายุของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 10, 'เจ้าจงแยกของบริสุทธิ์จากของไม่บริสุทธิ์และของมลทินจากของไม่มลทิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 11, 'และเจ้าจะต้องสอนพลไพร่อิสราเอลให้ทราบถึงกฎเกณฑ์ทั้งมวลซึ่งพระเยโฮวาห์ได้ตรัสแก่เขาทั้งหลายทางโมเสส”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 12, 'โมเสสกล่าวแก่อาโรนและเอเลอาซาร์ และอิธามาร์ บุตรชายของเขาผู้ที่เหลืออยู่ว่า “จงเอาธัญญบูชาซึ่งเหลือจากการบูชาด้วยไฟถวายแด่พระเยโฮวาห์ มารับประทานที่ริมแท่นบูชาไม่ใส่เชื้อ เพราะเป็นของบริสุทธิ์ที่สุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 13, 'ท่านจงรับประทานในที่บริสุทธิ์เพราะเป็นส่วนของท่าน และส่วนของบุตรชายของท่าน จากเครื่องบูชาด้วยไฟถวายแด่พระเยโฮวาห์ เพราะข้าพเจ้าได้รับบัญชาดังนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 14, 'แต่เนื้ออกที่แกว่งถวาย และเนื้อโคนขาที่ถวายแล้วนั้น ท่านจงรับประทานในที่สะอาด ทั้งตัวท่านและบุตรชายบุตรสาวของท่านก็รับประทานได้ เพราะเป็นส่วนที่ได้มาจากสันติบูชาของคนอิสราเอล อันตกอยู่กับท่านทั้งบุตรชายทั้งหลายของท่านด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 15, 'เนื้อโคนขาที่ถวายและเนื้ออกที่แกว่งถวายเขาจะนํามาบูชาพร้อมกับเครื่องไขมันที่บูชาด้วยไฟ เพื่อแกว่งเป็นเครื่องบูชาแกว่งถวายต่อพระพักตร์พระเยโฮวาห์ สิ่งเหล่านี้เป็นของท่านและบุตรชายทั้งหลายของท่าน ให้เป็นกฎเกณฑ์เนืองนิตย์ ดังที่พระเยโฮวาห์ทรงบัญชาไว้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 16, 'ฝ่ายโมเสสได้พยายามไต่ถามถึงเรื่องแพะซึ่งเป็นเครื่องบูชาไถ่บาป และดูเถิด แพะตัวนั้นถูกเผาเสียแล้ว ท่านจึงโกรธเอเลอาซาร์และอิธามาร์บุตรชายของอาโรนที่เหลืออยู่ ท่านว่าเขาว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 17, '“เหตุไฉนท่านจึงมิได้รับประทานเครื่องบูชาไถ่บาปในที่บริสุทธิ์ ในเมื่อเป็นของบริสุทธิ์ที่สุด และพระเจ้าได้ประทานของเหล่านั้นให้แก่ท่านเพื่อท่านจะได้รับความชั่วช้าของชุมนุมชน เพื่อทําการลบมลทินบาปของเขาทั้งหลายต่อพระพักตร์พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 18, 'ดูเถิด เลือดสัตว์นั้นก็มิได้นําเข้ามายังที่บริสุทธิ์ที่ห้องชั้นใน ท่านควรจะได้รับประทานสิ่งเหล่านี้ในที่บริสุทธิ์ ดังที่ข้าพเจ้าได้บัญชาแล้วนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 19, 'อาโรนจึงกล่าวแก่โมเสสว่า “ดูเถิด วันนี้เขาได้ถวายเครื่องบูชาไถ่บาปและเครื่องเผาบูชาของเขาต่อพระพักตร์พระเยโฮวาห์แล้ว และเหตุการณ์เหล่านี้ก็ตกที่ข้าพเจ้าแล้ว ถ้าวันนี้ข้าพเจ้าได้รับประทานเครื่องบูชาไถ่บาป จะเป็นที่โปรดปรานในสายพระเนตรของพระเยโฮวาห์หรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 20, 'เมื่อโมเสสได้ฟังดังนั้น ท่านก็พอใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 1, 'พระเยโฮวาห์ตรัสกับโมเสสและอาโรนว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 2, '“จงกล่าวแก่คนอิสราเอลว่า ต่อไปนี้เป็นสัตว์ที่มีชีวิตในบรรดาสัตว์ในโลกซึ่งเจ้าจะรับประทานได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 3, 'บรรดาสัตว์ที่แยกกีบและมีกีบผ่าและสัตว์เคี้ยวเอื้อง เจ้ารับประทานได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 4, 'อย่างไรก็ตามสัตว์ต่อไปนี้ที่เคี้ยวเอื้องหรือแยกกีบ เจ้าก็อย่ารับประทาน อูฐ เพราะมันเคี้ยวเอื้องแต่ไม่แยกกีบ เป็นสัตว์มลทินแก่เจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 5, 'ตัวกระจงผาเพราะว่ามันเป็นสัตว์เคี้ยวเอื้องแต่ไม่แยกกีบ เป็นสัตว์มลทินแก่เจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 6, 'กระต่าย เพราะว่ามันเป็นสัตว์เคี้ยวเอื้องแต่ไม่แยกกีบ เป็นสัตว์มลทินแก่เจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 7, 'หมูเพราะมันเป็นสัตว์แยกกีบและมีกีบผ่าแต่ไม่เคี้ยวเอื้อง จึงเป็นสัตว์มลทินแก่เจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 8, 'อย่ารับประทานเนื้อของสัตว์เหล่านี้เลย และเจ้าอย่าแตะต้องซากของมัน มันเป็นของมลทินแก่เจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 9, 'สัตว์ที่อยู่ในน้ําทั้งหมดเหล่านี้เจ้ารับประทานได้ ของทุกอย่างซึ่งอยู่ในน้ําที่มีครีบและมีเกล็ด จะอยู่ในทะเลหรือในแม่น้ําก็ตาม เจ้ารับประทานได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 10, 'แต่ทุกอย่างในทะเลและในแม่น้ํา ทุกอย่างที่เคลื่อนไหวในน้ํา และสิ่งมีชีวิตใดๆซึ่งอยู่ในน้ํา ไม่มีครีบและเกล็ด สัตว์เหล่านี้เป็นสิ่งที่พึงรังเกียจแก่เจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 11, 'สัตว์เหล่านี้ยังคงเป็นสิ่งที่พึงรังเกียจแก่เจ้า เจ้าอย่ารับประทานเนื้อของมัน แต่ให้เจ้าถือว่าซากของมันเป็นที่พึงรังเกียจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 12, 'อะไรก็ตามที่อยู่ในน้ําไม่มีครีบและเกล็ด เป็นสิ่งที่พึงรังเกียจแก่เจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 13, 'ต่อไปนี้เป็นนกซึ่งให้เจ้าถือว่าเป็นสิ่งที่พึงรังเกียจท่ามกลางนกทั้งหลาย นกเหล่านี้รับประทานไม่ได้ มันเป็นสิ่งที่พึงรังเกียจ คือนกอินทรี นกแร้งหนวดแพะ นกออก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 14, 'นกเหยี่ยวหางยาว นกเหยี่ยวดําตามชนิดของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 15, 'นกกาตามชนิดของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 16, 'นกเค้าแมว นกเค้าโมง นกนางนวล เหยี่ยวนกเขาตามชนิดของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 17, 'นกเค้าแมวเล็ก นกอ้ายงั่ว นกทึดทือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 18, 'นกอีโก้ง นกกระทุง นกแร้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 19, 'นกกระสาดํา นกกระสาตามชนิดของมัน นกหัวขวาน และค้างคาว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 20, 'แมลงมีปีกซึ่งคลานสี่ขา เป็นสัตว์ที่พึงรังเกียจแก่เจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 21, 'แต่ในบรรดาแมลงมีปีกที่คลานสี่ขานี้ เจ้าจะรับประทานจําพวกที่มีขาพับใช้กระโดดไปบนดินได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 22, 'ในจําพวกแมลงต่อไปนี้เจ้ารับประทานได้ ตั๊กแตนวัยบินตามชนิดของมัน จิ้งหรีดโกร่งตามชนิดของมัน จักจั่นตามชนิดของมัน และตั๊กแตนตามชนิดของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 23, 'แต่แมลงมีปีกอย่างอื่นซึ่งมีสี่ขา เป็นสัตว์ที่พึงรังเกียจแก่เจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 24, 'สิ่งเหล่านั้นจะกระทําให้เจ้ามลทินได้ คือผู้หนึ่งผู้ใดแตะต้องซากของมันจะต้องมลทินไปถึงเวลาเย็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 25, 'ผู้ใดถือซากสัตว์ส่วนใดๆไปต้องซักเสื้อผ้าของตน และมลทินไปจนถึงเวลาเย็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 26, 'ซากของสัตว์ทั้งปวงที่แยกกีบและไม่มีกีบผ่า ไม่เคี้ยวเอื้องเป็นสัตว์มลทินแก่เจ้า ผู้ใดแตะต้องสัตว์เหล่านี้จะมลทิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 27, 'ในบรรดาสัตว์สี่เท้าทุกอย่างซึ่งเดินด้วยขยุ้มเท้าเป็นสัตว์มลทินแก่เจ้า ผู้ใดแตะต้องซากสัตว์นี้จะต้องมลทินไปถึงเวลาเย็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 28, 'ผู้ใดนําซากมันไปจะต้องซักเสื้อผ้าของตน และมลทินไปจนถึงเวลาเย็น เป็นสัตว์มลทินแก่เจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 29, 'ในบรรดาสัตว์ที่เลื้อยคลานไปบนดิน ชนิดต่อไปนี้เป็นสัตว์มลทินแก่เจ้า คือ อีเห็น หนู เหี้ยตามชนิดของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 30, 'จิ้งจก ตะกวด แย้ จิ้งเหลนและกิ้งก่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 31, 'ในบรรดาสัตว์เลื้อยคลาน ชนิดเหล่านี้เป็นมลทินแก่เจ้า ผู้ใดแตะต้องเมื่อมันตายแล้ว ผู้นั้นจะมลทินไปถึงเวลาเย็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 32, 'และเมื่อมันตายตกทับสิ่งใด สิ่งนั้นก็เป็นมลทิน ไม่ว่าจะเป็นสิ่งที่เป็นไม้ หรือเสื้อผ้า หรือหนังสัตว์ หรือกระสอบ หรือภาชนะใดๆที่ใช้เพื่อประโยชน์อย่างใด จะต้องแช่น้ํา และจะมลทินไปจนถึงเวลาเย็น ต่อไปก็นับว่าสะอาดได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 33, 'และถ้ามันตกลงไปในภาชนะดิน สิ่งที่อยู่ในภาชนะนั้นจะมลทิน จงทุบภาชนะนั้นเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 34, 'อาหารในภาชนะนั้นที่รับประทานได้ซึ่งมีน้ําปนอยู่ก็เป็นมลทิน และน้ําดื่มทั้งสิ้นซึ่งจะดื่มได้จากภาชนะอย่างนี้จะมลทิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 35, 'ถ้าส่วนใดของซากสัตว์ตกใส่สิ่งใดๆ สิ่งนั้นๆก็มลทิน ไม่ว่าเป็นเตาอบหรือเตา ต้องทุบเสีย เป็นมลทิน และเป็นของมลทินแก่เจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 36, 'อย่างไรก็ตามน้ําพุหรือน้ําในแอ่งเก็บน้ําเป็นของสะอาด แต่สิ่งใดที่แตะต้องซากสัตว์นั้นจะมลทิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 37, 'ถ้าส่วนใดของซากตกใส่เมล็ดพืชที่ใช้หว่าน พืชนั้นนับว่าสะอาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 38, 'แต่ถ้าเอาเมล็ดพืชนั้นแช่น้ําไว้ และซากสัตว์ส่วนใดตกใส่น้ํานั้นก็เป็นมลทินแก่เจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 39, 'ถ้าสัตว์ซึ่งเจ้าจะรับประทานได้นั้นตายเอง ผู้ที่แตะต้องซากสัตว์นั้นจะมลทินไปจนถึงเวลาเย็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 40, 'และผู้ใดที่รับประทานซากนั้นจะต้องซักเสื้อผ้าของเขาเสียและเป็นมลทินไปจนถึงเวลาเย็น ผู้ใดที่จับถือซากนั้นไปก็ต้องซักเสื้อผ้าของตน และเป็นมลทินไปจนถึงเวลาเย็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 41, 'บรรดาสัตว์เลื้อยคลานที่ไปบนแผ่นดินเป็นสิ่งพึงรังเกียจ อย่ารับประทาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 42, 'สิ่งใดที่เลื้อยไปด้วยท้อง หรือสิ่งที่เดินสี่ขา หรือสิ่งที่มีหลายขา ทุกสิ่งที่คลานไปบนแผ่นดิน เจ้าอย่ารับประทาน เพราะเป็นสิ่งพึงรังเกียจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 43, 'เจ้าอย่ากระทําให้ตัวเองเป็นที่พึงรังเกียจด้วยสัตว์เลื้อยคลานใดๆ อย่าทําตัวให้เป็นมลทินไปด้วยสัตว์เหล่านี้เลย เกรงว่าเจ้าจะเป็นมลทินไปด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 44, 'เพราะเราคือพระเยโฮวาห์พระเจ้าของเจ้า จงชําระตัวไว้ให้บริสุทธิ์ เพราะเราบริสุทธิ์ เจ้าอย่าทําตัวให้เป็นมลทินไปด้วยสัตว์อย่างใดอย่างหนึ่งซึ่งคลานไปบนแผ่นดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 45, 'เพราะเราคือพระเยโฮวาห์ผู้นําเจ้าออกจากแผ่นดินอียิปต์ เพื่อเป็นพระเจ้าของเจ้า เพราะฉะนั้นเจ้าจึงต้องบริสุทธิ์ เพราะเราบริสุทธิ์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 46, 'เหล่านี้เป็นพระราชบัญญัติกล่าวถึงเรื่องสัตว์และนก และสิ่งมีชีวิตที่เคลื่อนไหวไปมาในน้ํา และสัตว์ทุกชนิดที่เลื้อยคลานบนแผ่นดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 47, 'เพื่อให้สังเกตความแตกต่างระหว่างสิ่งที่เป็นมลทินและสิ่งที่ไม่เป็นมลทิน และระหว่างสัตว์ที่มีชีวิตรับประทานได้ และสัตว์มีชีวิตที่รับประทานไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 1, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 2, '“จงกล่าวแก่คนอิสราเอลว่า ถ้าหญิงคนใดมีครรภ์คลอดบุตรเป็นชาย นางต้องเป็นมลทินเจ็ดวัน นางจะเป็นมลทินอย่างเดียวกับมลทินเวลาที่นางมีประจําเดือน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 3, 'ในวันที่แปดให้ตัดหนังปลายองคชาตของเด็กนั้นเสียเพื่อเป็นการเข้าสุหนัต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 4, 'ให้นางคอยอยู่อีกสามสิบสามวันด้วยเรื่องโลหิตชําระของนาง อย่าให้นางแตะต้องของบริสุทธิ์อันใด หรือเข้าไปในสถานบริสุทธิ์ จนกว่าจะครบวันชําระของนาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 5, 'แต่ถ้านางคลอดบุตรเป็นหญิง นางจะมลทินไปสองสัปดาห์ อย่างเดียวกับเรื่องการมีประจําเดือน และนางจะต้องคอยอยู่หกสิบหกวัน ด้วยเรื่องโลหิตชําระของนาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 6, 'และเมื่อวันชําระของนางครบแล้ว ไม่ว่าเป็นกําหนดของบุตรชายหรือบุตรสาว ให้นางไปหาปุโรหิตที่ประตูพลับพลาแห่งชุมนุม นําลูกแกะอายุหนึ่งขวบตัวหนึ่งไปเป็นเครื่องเผาบูชาและนกพิราบหนุ่มตัวหนึ่งหรือนกเขาตัวหนึ่งเป็นเครื่องบูชาไถ่บาป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 7, 'ให้ปุโรหิตนําถวายต่อพระพักตร์พระเยโฮวาห์ และทําการลบมลทินให้นาง แล้วนางจะสะอาดในเรื่องโลหิตของนางตก นี่เป็นพระราชบัญญัติกล่าวด้วยเรื่องการคลอดบุตร ไม่ว่าเป็นชายหรือหญิง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 8, 'และถ้านางไม่สามารถหาลูกแกะตัวหนึ่งได้ก็ให้นางนํานกเขาสองตัวหรือนกพิราบหนุ่มสองตัว ตัวหนึ่งเป็นเครื่องเผาบูชาและอีกตัวหนึ่งเป็นเครื่องบูชาไถ่บาป และให้ปุโรหิตทําการลบมลทินให้นาง แล้วนางจะสะอาด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 1, 'พระเยโฮวาห์ตรัสกับโมเสสและอาโรนว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 2, '“ถ้าผู้ใดเกิดอาการบวมหรือเป็นสะเก็ดนูนแดงหรือด่างขึ้นที่ผิวหนัง แล้วผิวหนังของเขาเป็นโรคเรื้อน ก็ให้พาผู้นั้นมาหาอาโรนปุโรหิต หรือมาหาบุตรชายคนหนึ่งคนใดของเขาที่เป็นปุโรหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 3, 'ให้ปุโรหิตตรวจผิวหนังตรงที่เป็นโรค ถ้าขนในที่นั้นเปลี่ยนเป็นสีขาวและเห็นว่าโรคนั้นอยู่ลึกกว่าผิวหนังลงไป นับว่าเป็นโรคเรื้อน เมื่อปุโรหิตตรวจเขาเสร็จแล้วให้ประกาศว่าเขาเป็นมลทิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 4, 'ถ้าผิวหนังตรงที่ด่างขึ้นนั้นขาว และปรากฏว่ากินไม่ลึกไปกว่าผิวหนัง และขนในบริเวณนั้นก็ไม่เปลี่ยนเป็นสีขาว ให้ปุโรหิตกักตัวผู้ป่วยไว้เจ็ดวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 5, 'และให้ปุโรหิตตรวจเขาอีกในวันที่เจ็ด ดูเถิด ถ้าตามสายตาของเขาเห็นว่าโรคนั้นทรงอยู่ไม่ลามออกไปในผิวหนัง ก็ให้ปุโรหิตกักตัวเขาต่อไปอีกเจ็ดวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 6, 'พอถึงวันที่เจ็ดให้ปุโรหิตตรวจเขาอีกครั้งหนึ่ง ดูเถิด ถ้าโรคนั้นจางลง และโรคมิได้ลามออกไปในผิวหนัง ก็ให้ปุโรหิตประกาศว่า เขาสะอาดแล้ว เขาเป็นสะเก็ดนูนแดงเท่านั้น ให้เขาซักเสื้อผ้าแล้วเขาก็จะสะอาดได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 7, 'แต่ถ้าหากว่าภายหลังจากที่เขาสําแดงตัวแก่ปุโรหิตเพื่อรับการชําระแล้วนั้นปรากฏว่า ที่เป็นสะเก็ดนูนแดงลามออกไปในผิวหนัง เขาต้องกลับไปหาปุโรหิตอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 8, 'ให้ปุโรหิตทําการตรวจ ดูเถิด ถ้าสะเก็ดนูนแดงนั้นลามออกไปในผิวหนัง ก็ให้ปุโรหิตประกาศว่าเขาเป็นมลทิน เขาเป็นโรคเรื้อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 9, 'ถ้าผู้ใดเป็นโรคเรื้อนก็ให้พาเขามาหาปุโรหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 10, 'และให้ปุโรหิตตรวจดูตัวเขา ดูเถิด ถ้ามีบริเวณบวมสีขาวเกิดขึ้นที่ผิวหนัง ซึ่งทําให้ขนที่นั่นเปลี่ยนเป็นสีขาว และมีเนื้อแผลสดในที่ที่บวมนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 11, 'แสดงว่าเป็นโรคเรื้อนเรื้อรังที่ผิวหนัง ให้ปุโรหิตประกาศว่าเขามลทิน อย่ากักตัวเขาไว้ เพราะว่าเขาเป็นมลทิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 12, 'ถ้าโรคเรื้อนนั้นลามไปตามผิวหนังตามที่ปุโรหิตเห็นก็ปรากฏว่าลามไปตามผิวหนังทั่วตัวผู้ป่วยตั้งแต่ศีรษะจนถึงเท้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 13, 'ปุโรหิตต้องตรวจดู และดูเถิด ถ้าเรื้อนนั้นแผ่ไปทั่วตัว ให้ปุโรหิตประกาศว่าเขาสะอาดด้วยโรคของเขาแล้วตัวของเขาเผือก เขาสะอาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 14, 'ถ้ามีเนื้อแผลสดปรากฏขึ้นมาเมื่อไร เขาก็เป็นมลทิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 15, 'ให้ปุโรหิตตรวจดูที่เนื้อแผลสดและประกาศว่าเขาเป็นมลทิน เพราะเนื้อแผลสดนั้นทําให้มลทิน เขาเป็นโรคเรื้อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 16, 'หรือถ้าเนื้อแผลสดนั้นเปลี่ยนไปอีกกลายเป็นสีขาว ให้เขามาหาปุโรหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 17, 'และให้ปุโรหิตตรวจเขา และดูเถิด ถ้าโรคนั้นกลายเป็นโรคเผือก ให้ปุโรหิตประกาศว่า คนที่เป็นโรคนั้นสะอาด เขาสะอาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 18, 'ถ้าที่ร่างกายคือผิวหนังของคนใดมีแผลฝีซึ่งหายแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 19, 'ถ้าที่แผลเป็นนั้นมีสีขาวบวมขึ้นมาหรือมีที่ด่างขึ้นสีแดงเรื่อๆปรากฏ ก็ให้ผู้นั้นไปสําแดงตัวต่อปุโรหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 20, 'และปุโรหิตจะตรวจดู ดูเถิด ถ้าที่เป็นนั้นลึกกว่าผิวหนัง และขนที่บริเวณนั้นเปลี่ยนเป็นสีขาว ให้ปุโรหิตประกาศว่าเขาเป็นมลทิน โรคนั้นเป็นโรคเรื้อน มันพุขึ้นมาที่แผลฝี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 21, 'แต่ถ้าปุโรหิตตรวจดูแล้ว และดูเถิด ขนที่นั่นก็ไม่เปลี่ยนเป็นสีขาว และเป็นไม่ลึกกว่าผิวหนังแต่จาง ให้ปุโรหิตกักตัวเขาไว้เจ็ดวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 22, 'ถ้าโรคนั้นลามออกไปในผิวหนัง ก็ให้ปุโรหิตประกาศว่าเขาเป็นมลทิน เขาเป็นโรคแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 23, 'แต่ถ้าที่ด่างขึ้นนั้นคงที่อยู่ไม่ลามออกไป ก็เป็นแต่เพียงแผลเป็นของฝี ให้ปุโรหิตประกาศว่าเขาสะอาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 24, 'หรือเมื่อส่วนของร่างกายคือผิวหนังถูกไฟลวกและเนื้อแผลสดที่ตรงนั้นเป็นที่ด่างขึ้นสีแดงเรื่อๆหรือสีขาว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 25, 'ให้ปุโรหิตตรวจดู และดูเถิด ถ้าขนในบริเวณนั้นเปลี่ยนเป็นสีขาวและปรากฏว่าเป็นลึกกว่าผิวหนังก็เป็นโรคเรื้อน มันพุขึ้นมาที่แผลไฟลวก และให้ปุโรหิตประกาศว่าเขาเป็นมลทิน เขาเป็นโรคเรื้อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 26, 'แต่ถ้าปุโรหิตตรวจดู และดูเถิด ขนในที่ด่างขึ้นนั้นไม่เปลี่ยนเป็นสีขาว และเป็นไม่ลึกกว่าผิวหนัง แต่จาง ให้ปุโรหิตกักตัวเขาไว้เจ็ดวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 27, 'พอถึงวันที่เจ็ดก็ให้ปุโรหิตตรวจดูเขา ถ้าที่เป็นนั้นลามออกไปในผิวหนัง ก็ให้ปุโรหิตประกาศว่าเขาเป็นมลทิน เขาเป็นโรคเรื้อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 28, 'ถ้าที่ด่างขึ้นนั้นคงที่อยู่ ไม่ลามออกไปในผิวหนัง แต่จาง บวมเพราะไฟลวก ให้ปุโรหิตประกาศว่าเขาสะอาด เพราะมันเป็นเพียงแผลเป็นของไฟลวก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 29, 'ถ้าชายหรือหญิงคนใดมีโรคที่ศีรษะหรือที่เครา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 30, 'ให้ปุโรหิตตรวจดูโรคนั้น และดูเถิด ถ้าเป็นลึกกว่าผิวหนัง และผมตรงนั้นเหลืองและบาง ให้ปุโรหิตประกาศว่าเขาเป็นมลทิน เขาเป็นโรคคัน เป็นโรคเรื้อนที่ศีรษะหรือที่เครา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 31, 'และถ้าปุโรหิตตรวจดูโรคคันนั้น และดูเถิด เป็นไม่ลึกกว่าผิวหนัง และไม่มีผมดําอยู่ในบริเวณนั้น ให้ปุโรหิตกักตัวบุคคลที่เป็นโรคคันนั้นไว้เจ็ดวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 32, 'พอถึงวันที่เจ็ดก็ให้ปุโรหิตตรวจโรคนั้น ดูเถิด ถ้าอาการคันนั้นไม่ลามออกไป และไม่มีขนเหลืองในบริเวณนั้น และปรากฏว่าอาการคันไม่ลึกกว่าผิวหนัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 33, 'ก็ให้คนนั้นโกนผมเสีย แต่อย่าโกนตรงบริเวณที่คัน ให้ปุโรหิตกักตัวบุคคลที่เป็นโรคคันนั้นไว้อีกเจ็ดวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 34, 'พอถึงวันที่เจ็ดก็ให้ปุโรหิตตรวจดูตรงที่คัน ดูเถิด ถ้าที่คันนั้นไม่ลามออกไปในผิวหนัง และปรากฏว่าเป็นไม่ลึกไปกว่าผิวหนัง ให้ปุโรหิตประกาศว่าเขาสะอาด ให้เขาซักเสื้อผ้า แล้วจะสะอาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 35, 'แต่ถ้าเขาชําระตัวแล้ว ยังปรากฏว่าโรคคันนั้นลามออกไปในผิวหนัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 36, 'ก็ให้ปุโรหิตตรวจเขา และดูเถิด ถ้าโรคคันนั้นลามออกไปในผิวหนังแล้ว ปุโรหิตไม่จําเป็นต้องมองหาขนสีเหลือง เขาเป็นมลทินแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 37, 'แต่ถ้าตามสายตาของเขาโรคคันนั้นระงับแล้ว และมีผมดํางอกอยู่ในบริเวณนั้น โรคคันนั้นหายแล้ว เขาก็สะอาด และให้ปุโรหิตประกาศว่า เขาสะอาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 38, 'เมื่อผู้ชายหรือผู้หญิงมีที่ด่างขึ้นที่ผิวหนัง คือที่ด่างขึ้นสีขาว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 39, 'ให้ปุโรหิตตรวจเขา ดูเถิด ถ้าที่ด่างขึ้นที่ผิวกายนั้นเป็นสีขาวหม่น นั่นเป็นเกลื้อนที่พุขึ้นในผิวหนัง เขาสะอาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 40, 'ถ้าชายคนใดมีผมร่วงจากศีรษะ เขาเป็นคนศีรษะล้าน แต่เขาสะอาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 41, 'ถ้าชายคนใดมีผมที่หน้าผากและที่ขมับร่วง หน้าผากของเขาล้าน แต่เขาสะอาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 42, 'แต่ถ้าตรงบริเวณศีรษะล้านหรือหน้าผากล้าน มีบริเวณเป็นโรคสีแดงเรื่อๆ เขาเป็นเรื้อนพุขึ้นที่ศีรษะล้านหรือที่หน้าผากล้านนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 43, 'ให้ปุโรหิตตรวจดูเขา ดูเถิด ถ้าโรคบวมนั้นสีแดงเรื่อๆอยู่ที่ศีรษะล้านหรือที่หน้าผากล้านของเขา เหมือนกับโรคเรื้อนที่ปรากฏตามผิวหนัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 44, 'ชายผู้นั้นเป็นโรคเรื้อน เขาเป็นมลทิน ปุโรหิตต้องประกาศว่า เขาเป็นมลทิน โรคของเขาอยู่ที่ศีรษะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 45, 'ให้บุคคลที่เป็นโรคเรื้อนสวมเสื้อผ้าที่ขาด และให้ปล่อยผม และให้เขาปิดริมฝีปากบนไว้ แล้วร้องไปว่า ‘มลทิน มลทิน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 46, 'เขาจะเป็นมลทินอยู่ตลอดเวลาที่เขาเป็นโรค เขาเป็นมลทิน เขาจะต้องอยู่แต่ลําพังภายนอกค่าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 47, 'เมื่อในเครื่องแต่งกายมีโรคเรื้อน ไม่ว่าจะเป็นเครื่องแต่งกายขนสัตว์หรือผ้าป่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 48, 'อยู่ที่ด้ายเส้นยืนหรือเส้นพุ่ง อยู่ที่ผ้าป่านหรือผ้าขนสัตว์ หรืออยู่ในหนัง หรือสิ่งใดๆที่ทําด้วยหนัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 49, 'ถ้าโรคนั้นทําให้เครื่องแต่งกายมีสีเขียวๆหรือแดงๆที่ด้ายเส้นยืนหรือเส้นพุ่งที่หนังหรือสิ่งใดๆที่ทําด้วยหนัง นั่นเป็นโรคเรื้อน จะต้องนําไปแสดงต่อปุโรหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 50, 'และให้ปุโรหิตตรวจโรคนั้น และให้กักสิ่งที่เป็นโรคนั้นไว้เจ็ดวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 51, 'พอถึงวันที่เจ็ดก็ให้ตรวจดูโรคนั้นอีก ถ้าโรคนั้นลามไปในเสื้อผ้าเครื่องแต่งกาย ไม่ว่าที่ด้ายเส้นยืนหรือเส้นพุ่ง เป็นที่หนังสัตว์ หรือสิ่งใดที่ทําด้วยหนังสัตว์ โรคนั้นเป็นโรคเรื้อนอย่างร้าย นับว่าเป็นมลทิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 52, 'ให้ปุโรหิตเผาเครื่องแต่งกายนั้นเสีย ไม่ว่าเป็นโรคที่ด้ายเส้นยืนหรือเส้นพุ่ง เป็นที่ผ้าขนสัตว์หรือผ้าป่าน หรือสิ่งใดๆที่ทําด้วยหนังสัตว์ เพราะเป็นโรคเรื้อนที่ร้าย จึงให้เผาเสียในไฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 53, 'และถ้าปุโรหิตนั้นตรวจดู และดูเถิด โรคนั้นมิได้ลามไปในเสื้อ ทั้งที่ด้ายเส้นยืนหรือเส้นพุ่ง หรือในสิ่งใดที่ทําด้วยหนังสัตว์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 54, 'ก็ให้ปุโรหิตบัญชาให้เขาซักตัวที่เป็นโรคนั้นเสีย และให้กักไว้อีกเจ็ดวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 55, 'เมื่อซักแล้วก็ให้ปุโรหิตตรวจดูตัวที่เป็นโรคนั้นอีก ดูเถิด ถ้าบริเวณที่เป็นโรคไม่เปลี่ยนสี แม้ว่าโรคนั้นไม่ลามไป ก็เป็นมลทิน เจ้าจงเอาใส่ในไฟเผาเสีย ไม่ว่าบริเวณที่เป็นโรคเรื้อนนั้นจะอยู่ข้างในหรือข้างนอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 56, 'ถ้าปุโรหิตตรวจดูเมื่อซักแล้ว และดูเถิด โรคนั้นจาง ก็ให้ฉีกบริเวณนั้นออกเสียจากเสื้อหรือหนังสัตว์ หรือเส้นยืนหรือเส้นพุ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 57, 'ถ้าปรากฏขึ้นอีกในเครื่องแต่งกายไม่ว่าที่ด้ายเส้นยืนหรือเส้นพุ่ง หรือในสิ่งใดๆที่ทําด้วยหนังสัตว์ โรคนั้นลามไปแล้ว เจ้าจงเผาสิ่งที่เป็นโรคนั้นด้วยไฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 58, 'ถ้าเสื้อทั้งที่ด้ายเส้นยืนหรือเส้นพุ่ง หรือสิ่งใดๆที่ทําด้วยหนังสัตว์ ซึ่งเมื่อซักแล้วโรคนั้นหมดไป ก็ให้ซักอีกเป็นครั้งที่สอง สะอาดได้แล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 59, 'นี่เป็นพระราชบัญญัติว่าด้วยโรคเรื้อนในเสื้อที่ทําด้วยขนสัตว์หรือผ้าป่าน ไม่ว่าเป็นที่ด้ายเส้นยืนหรือเส้นพุ่ง หรือเป็นที่สิ่งใดๆที่ทําด้วยหนังสัตว์ เพื่อให้พิจารณาว่าอย่างใดสะอาด อย่างใดเป็นมลทิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 1, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 2, '“ต่อไปนี้จะเป็นพระราชบัญญัติเรื่องคนเป็นโรคเรื้อนในวันชําระตัวของเขา ให้พาเขามาหาปุโรหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 3, 'และให้ปุโรหิตออกไปนอกค่าย และให้ปุโรหิตทําการตรวจ ดูเถิด ถ้าผู้ป่วยหายจากโรคเรื้อนแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 4, 'ก็ให้ปุโรหิตบัญชาเขาให้จัดของสําหรับผู้จะรับการชําระ คือนกสะอาดที่มีชีวิตสองตัว ไม้สนสีดาร์ กับด้ายสีแดง และต้นหุสบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 5, 'ให้ปุโรหิตบัญชาให้ฆ่านกตัวหนึ่งในภาชนะดินข้างบนน้ําไหล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 6, 'สําหรับนกตัวที่ยังเป็นอยู่นั้น ให้ปุโรหิตเอานกตัวที่ยังเป็นอยู่กับไม้สนสีดาร์ ด้ายสีแดง ต้นหุสบ จุ่มเข้าไปในเลือดของนกที่ถูกฆ่าข้างบนน้ําไหล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 7, 'และให้ปุโรหิตประพรมคนที่จะรับการชําระจากโรคเรื้อนนั้นเจ็ดครั้ง แล้วประกาศว่า เขาสะอาด และให้ปล่อยนกตัวที่ยังมีชีวิตนั้นไปในท้องทุ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 8, 'และให้ผู้ที่รับการชําระนั้นซักเสื้อผ้าของตน และให้โกนผมกับขนทั้งหมดเสีย และอาบน้ํา เขาก็จะสะอาด ต่อจากนั้นก็ให้เขาเข้าค่ายได้ แต่ให้นอนอยู่นอกเต็นท์ของเขาเจ็ดวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 9, 'พอวันที่เจ็ดให้เขาโกนผมจากศีรษะของเขาให้หมด ให้เขาโกนเคราและโกนขนคิ้ว คือโกนให้หมด แล้วให้ซักเสื้อผ้า และอาบน้ํา เขาก็จะสะอาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 10, 'ในวันที่แปดให้เขาเอาลูกแกะผู้สองตัวปราศจากตําหนิ และลูกแกะเมียอายุหนึ่งขวบตัวหนึ่งปราศจากตําหนิ และยอดแป้งคลุกน้ํามันสามในสิบเอฟาห์เป็นธัญญบูชา กับน้ํามันลกหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 11, 'ให้ปุโรหิตผู้ทําการชําระ นําผู้ที่รับการชําระกับสิ่งของเหล่านี้มาต่อพระพักตร์พระเยโฮวาห์ที่ประตูพลับพลาแห่งชุมนุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 12, 'ให้ปุโรหิตนําลูกแกะผู้นั้นตัวหนึ่งไปถวายเป็นเครื่องบูชาไถ่การละเมิดพร้อมกับน้ํามันลกหนึ่ง ให้แกว่งไปแกว่งมาเป็นเครื่องบูชาแกว่งถวายต่อพระพักตร์พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 13, 'ให้ปุโรหิตฆ่าลูกแกะนั้นในที่ที่เขาฆ่าสัตว์อันเป็นเครื่องบูชาไถ่บาปและสัตว์อันเป็นเครื่องเผาบูชาในที่บริสุทธิ์ เพราะว่าเครื่องบูชาไถ่การละเมิดก็เหมือนเครื่องบูชาไถ่บาป เป็นของที่ตกแก่ปุโรหิต เป็นของบริสุทธิ์ที่สุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 14, 'ปุโรหิตจะนําเลือดของเครื่องบูชาไถ่การละเมิดมาบ้าง และปุโรหิตจะเจิมที่ปลายหูข้างขวาของผู้ที่รับการชําระ และเจิมที่นิ้วหัวแม่มือขวาและที่นิ้วหัวแม่เท้าขวาของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 15, 'และปุโรหิตจะนําน้ํามันหนึ่งลกนั้นมาบ้าง เทใส่ฝ่ามือซ้ายของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 16, 'และเอานิ้วมือขวาจิ้มน้ํามันซึ่งอยู่ในมือซ้าย ประพรมน้ํามันด้วยนิ้วของเขาเจ็ดครั้งต่อพระพักตร์พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 17, 'ส่วนน้ํามันที่เหลืออยู่ในมือนั้น ปุโรหิตจะเอามาบ้าง เจิมที่ปลายหูขวาของผู้ที่รับการชําระ และที่นิ้วหัวแม่มือขวาและที่นิ้วหัวแม่เท้าขวา ทับบนเลือดเครื่องบูชาไถ่การละเมิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 18, 'ส่วนน้ํามันที่ยังเหลืออยู่ในมือของปุโรหิตนั้น เขาจะเจิมศีรษะของผู้รับการชําระ แล้วปุโรหิตจะทําการลบมลทินของเขาต่อพระพักตร์พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 19, 'ปุโรหิตจะถวายเครื่องบูชาไถ่บาป เพื่อทําการลบมลทินของผู้รับการชําระให้พ้นจากมลทินของเขา ภายหลังปุโรหิตจะฆ่าสัตว์อันเป็นเครื่องเผาบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 20, 'และปุโรหิตจะถวายเครื่องเผาบูชาและธัญญบูชาบนแท่น ปุโรหิตจะทําการลบมลทินของเขาดังนี้ และเขาก็จะสะอาดได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 21, 'ถ้าผู้นั้นเป็นคนยากจนและไม่สามารถจะหามาได้เท่านั้น ก็ให้เขานําลูกแกะตัวหนึ่งเป็นเครื่องบูชาไถ่การละเมิดเพื่อแกว่งไปแกว่งมา กระทําการลบมลทินของเขา และนํายอดแป้งหนึ่งในสิบเอฟาห์คลุกกับน้ํามัน เป็นธัญญบูชากับน้ํามันลกหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 22, 'พร้อมกับนกเขาสองตัว หรือนกพิราบหนุ่มสองตัว ตามที่เขาสามารถหามาได้ นกตัวหนึ่งเป็นเครื่องบูชาไถ่บาป นกอีกตัวหนึ่งเป็นเครื่องเผาบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 23, 'ในวันที่แปดให้เขานํามามอบให้แก่ปุโรหิตเพื่อการชําระของตนที่ประตูพลับพลาแห่งชุมนุมถวายต่อพระพักตร์พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 24, 'และปุโรหิตจะนําลูกแกะที่เป็นเครื่องบูชาไถ่การละเมิดและน้ํามันลกหนึ่งนั้น และปุโรหิตจะแกว่งไปแกว่งมาเป็นเครื่องบูชาแกว่งถวายต่อพระพักตร์พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 25, 'และเขาจะฆ่าลูกแกะเครื่องบูชาไถ่การละเมิด และปุโรหิตจะเอาเลือดของเครื่องบูชาไถ่การละเมิดมาบ้าง เจิมที่ปลายหูข้างขวาของผู้รับการชําระ และที่นิ้วหัวแม่มือขวา กับที่นิ้วหัวแม่เท้าขวาของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 26, 'แล้วปุโรหิตจะเทน้ํามันใส่ฝ่ามือซ้ายของตนบ้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 27, 'และเอาน้ํามันที่อยู่ในมือซ้ายนั้นประพรมด้วยนิ้วมือขวาเจ็ดครั้งต่อพระพักตร์พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 28, 'และปุโรหิตจะเอาน้ํามันที่อยู่ในมือเจิมที่ปลายหูข้างขวาของผู้รับการชําระ และที่หัวแม่มือขวากับหัวแม่เท้าขวาของเขา ตรงที่ที่เจิมด้วยเลือดของเครื่องบูชาไถ่การละเมิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 29, 'น้ํามันที่เหลืออยู่ในมือของปุโรหิตนั้น เขาจะเจิมศีรษะของผู้ที่รับการชําระ ทําการลบมลทินของเขาต่อพระพักตร์พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 30, 'และเขาจะถวายนกเขาหรือนกพิราบหนุ่มตัวหนึ่งตามที่เขาสามารถหามาได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 31, 'คือตามที่เขาสามารถหามาได้ให้ถวายนกตัวหนึ่งเป็นเครื่องบูชาไถ่บาป นกอีกตัวหนึ่งเป็นเครื่องเผาบูชา พร้อมกับธัญญบูชา และปุโรหิตจะทําการลบมลทินของผู้รับการชําระต่อพระพักตร์พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 32, 'นี่เป็นพระราชบัญญัติสําหรับผู้ที่เป็นโรคเรื้อนไม่สามารถหาเครื่องบูชาเพื่อการชําระของตนได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 33, 'พระเยโฮวาห์ตรัสกับโมเสสและอาโรนว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 34, '“เมื่อเจ้าเข้าไปในแผ่นดินคานาอัน ซึ่งเราให้แก่เจ้าเป็นกรรมสิทธิ์นั้น และเราจะใส่โรคเรื้อนเข้าที่เรือนหลังหนึ่งหลังใดในแผ่นดินที่เจ้าถือกรรมสิทธิ์นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 35, 'ผู้ใดที่ถือกรรมสิทธิ์ของเรือนนั้นจะต้องมาบอกแก่ปุโรหิตว่า ‘ข้าพเจ้าเห็นโรคอะไรอย่างหนึ่งเกิดในเรือนของข้าพเจ้า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 36, 'แล้วปุโรหิตจะบัญชาให้เขาขนของออกจากเรือนให้หมด ก่อนที่ปุโรหิตจะเข้าไปตรวจโรค เกรงว่าของทุกอย่างที่อยู่ในเรือนนั้นจะถูกประกาศว่า มลทิน ต่อจากนั้นปุโรหิตจึงจะเข้าไปตรวจดูเรือน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 37, 'และปุโรหิตจะตรวจดูโรค ดูเถิด ถ้าโรคนั้นอยู่ที่ผนังของเรือนเป็นรอยสีเขียวๆแดงๆและปรากฏว่าอยู่ลึกกว่าผิว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 38, 'แล้วปุโรหิตจะออกจากเรือนไปอยู่ที่ประตูเรือนแล้วปิดเรือนเสียเจ็ดวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 39, 'พอถึงวันที่เจ็ดปุโรหิตจะกลับมาตรวจดูอีก ดูเถิด ถ้าโรคนั้นลามไปในผนังเรือน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 40, 'แล้วปุโรหิตจะบัญชาให้เอาหินก้อนที่ติดโรคนั้นออกเสียนําไปโยนทิ้งในที่มลทินภายนอกเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 41, 'และสั่งให้ขูดข้างในเรือนทั่วๆไป ผงปูนที่ขูดออกมานั้นให้นําไปทิ้งเสียในที่มลทินภายนอกเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 42, 'แล้วให้หาหินอื่นมาแทนหินก้อนที่นําออกไป และเอาปูนอื่นมาโบกผนังเรือนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 43, 'เมื่อเขาเอาหินออก ขูดเรือนและโบกปูนใหม่แล้ว ยังเกิดโรคขึ้นในเรือนนั้นอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 44, 'แล้วปุโรหิตจะไปตรวจดู ดูเถิด ถ้าโรคนั้นลามไปในเรือน เป็นโรคเรื้อนอย่างร้ายในเรือน เรือนนั้นก็เป็นมลทิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 45, 'ให้เขาพังเรือนนั้นลง หิน ไม้และปูนที่ทําเรือนนั้นให้ขนไปทิ้งเสียในที่ที่มลทินภายนอกเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 46, 'ยิ่งกว่านั้นอีกเมื่อเรือนปิดอยู่ มีผู้ใดเข้าไป ผู้นั้นจะเป็นมลทินจนถึงเวลาเย็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 47, 'ผู้ใดที่นอนลงในเรือนนั้นต้องซักเสื้อผ้าของเขา และผู้ที่รับประทานในเรือนนั้นต้องซักเสื้อผ้าของเขาด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 48, 'แต่ปุโรหิตมาทําการตรวจ ดูเถิด เมื่อโบกปูนใหม่แล้ว โรคนั้นมิได้ลามไปในเรือนแล้ว ปุโรหิตจะประกาศว่าเรือนนั้นสะอาด เพราะโรคหายแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 49, 'และเพื่อจะชําระเรือนนั้นให้เขานํานกสองตัวกับไม้สนสีดาร์ ด้ายสีแดง และต้นหุสบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 50, 'ให้ฆ่านกตัวหนึ่งในภาชนะดินข้างบนน้ําที่ไหล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 51, 'เอาไม้สนสีดาร์ ต้นหุสบและด้ายสีแดง พร้อมกับนกตัวที่ยังมีชีวิตอยู่จุ่มลงในเลือดนกที่ได้ฆ่าและในน้ําที่ไหลนั้น แล้วประพรมเรือนนั้นเจ็ดครั้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 52, 'ดังนี้เขาจะได้ชําระเรือนด้วยเลือดนก ด้วยน้ําไหลและด้วยนกที่มีชีวิต ด้วยไม้สนสีดาร์ ต้นหุสบ และด้ายสีแดง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 53, 'ให้เขาปล่อยนกที่มีชีวิตออกไปจากเมืองยังท้องทุ่ง ดังนี้แหละเขาจะได้ทําการลบมลทินของเรือน และเรือนนั้นก็สะอาด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 54, 'นี่เป็นพระราชบัญญัติเกี่ยวกับโรคเรื้อนต่างๆ โรคคัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 55, 'โรคเรื้อนในเครื่องแต่งกายหรือในเรือน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 56, 'ที่บวมหรือเป็นสะเก็ดนูนแดง หรือที่ด่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 57, 'เพื่อจะแสดงว่าเมื่อไรจึงเรียกว่ามลทิน เมื่อไรเรียกว่าสะอาด นี่เป็นพระราชบัญญัติเรื่องโรคเรื้อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 1, 'พระเยโฮวาห์ตรัสกับโมเสสและอาโรนว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 2, '“จงกล่าวแก่คนอิสราเอลว่า เมื่อผู้ใดมีสิ่งไหลออกจากร่างกาย เพราะเหตุสิ่งที่ไหลออกนั้น เขาเป็นมลทิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 3, 'ต่อไปนี้เป็นกฎเกี่ยวด้วยเรื่องมลทินของเขาเนื่องด้วยสิ่งที่ไหลออก ร่างกายของเขาจะมีสิ่งไหลออกหรือสิ่งที่ไหลออกคั่งอยู่ในร่างกายของเขาก็ดี เรื่องนี้เป็นมลทินแก่เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 4, 'เตียงนอนซึ่งผู้ใดที่มีสิ่งไหลออกขึ้นไปนอน เตียงนั้นก็เป็นมลทิน ทุกสิ่งที่เขารองนั่งก็เป็นมลทิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 5, 'ผู้ใดที่แตะต้องเตียงของเขาต้องซักเสื้อผ้าของตนและอาบน้ํา และจะเป็นมลทินไปจนถึงเวลาเย็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 6, 'ผู้ใดไปนั่งบนสิ่งที่ผู้มีสิ่งไหลออกได้นั่งก่อน ผู้นั้นต้องซักเสื้อผ้าของตนและอาบน้ํา และจะเป็นมลทินไปจนถึงเวลาเย็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 7, 'ผู้ใดไปแตะต้องร่างกายของผู้ที่มีสิ่งไหลออก ผู้นั้นต้องซักเสื้อผ้าของตนและอาบน้ํา และเป็นมลทินไปจนถึงเวลาเย็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 8, 'และถ้าผู้ใดที่มีสิ่งไหลออกนั้นถ่มน้ําลายรดผู้ที่สะอาดเข้า ผู้ที่ถูกน้ําลายรดต้องซักเสื้อผ้าและอาบน้ํา และเป็นมลทินไปจนถึงเวลาเย็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 9, 'และอานใดๆซึ่งผู้มีสิ่งไหลออกนั่งอยู่ อานนั้นก็เป็นมลทิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 10, 'ผู้หนึ่งผู้ใดแตะต้องสิ่งที่รองเขาอยู่นั้น ผู้นั้นจะเป็นมลทินไปจนถึงเวลาเย็น และผู้ใดที่หยิบถือสิ่งนั้นต้องซักเสื้อผ้าของตัวและอาบน้ํา และเป็นมลทินไปจนถึงเวลาเย็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 11, 'ผู้ที่มีสิ่งไหลออกแตะต้องผู้ใดด้วยมือที่มิได้ล้าง ผู้ถูกแตะต้องนั้นต้องซักเสื้อผ้าของตัวและอาบน้ํา และเป็นมลทินไปจนถึงเวลาเย็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 12, 'ภาชนะดินซึ่งผู้มีสิ่งไหลออกแตะต้องให้ทุบเสีย และภาชนะไม้ทุกอย่างก็ให้ชําระเสียด้วยน้ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 13, 'เมื่อผู้มีสิ่งไหลออกได้ชําระสิ่งไหลออกของเขาแล้ว เขาต้องนับการชําระของเขาให้ครบเจ็ดวัน และเขาต้องซักเสื้อผ้าและอาบน้ําที่ไหล เขาจึงจะสะอาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 14, 'ในวันที่แปดให้เขานํานกเขาสองตัว หรือนกพิราบหนุ่มสองตัวมาต่อพระพักตร์พระเยโฮวาห์ที่ประตูพลับพลาแห่งชุมนุม และมอบของเหล่านั้นให้แก่ปุโรหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 15, 'ให้ปุโรหิตถวายบูชา คือถวายนกตัวหนึ่งเป็นเครื่องถวายบูชาไถ่บาป และนกอีกตัวหนึ่งเป็นเครื่องเผาบูชา และปุโรหิตจะทําการลบมลทินของเขาต่อพระพักตร์พระเยโฮวาห์ ด้วยเรื่องสิ่งไหลออกของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 16, 'ชายคนใดมีน้ํากามไหลออก ให้เขาอาบน้ํา และเป็นมลทินไปจนถึงเวลาเย็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 17, 'เครื่องแต่งกายทุกชิ้นและผิวหนังทุกส่วนที่น้ํากามไหลรดต้องชําระเสียในน้ํา และเป็นมลทินไปจนถึงเวลาเย็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 18, 'ชายคนใดร่วมหลับนอนกับหญิงคนใด และมีน้ํากามไหลออกทั้งสองจะต้องอาบน้ํา และเป็นมลทินไปจนถึงเวลาเย็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 19, 'เมื่อสตรีมีสิ่งไหลออกเป็นโลหิตประจําเดือน เธอจะต้องอยู่ต่างหากเจ็ดวัน และผู้ใดแตะต้องเธอ จะต้องเป็นมลทินไปจนถึงเวลาเย็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 20, 'และทุกสิ่งที่เธอนอนทับในเวลาที่เธอต้องแยกออกนั้นก็เป็นมลทิน สิ่งใดที่เธอไปนั่งทับสิ่งนั้นก็เป็นมลทิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 21, 'ผู้ใดไปแตะต้องที่นอนของเธอ ผู้นั้นต้องซักเสื้อผ้าและอาบน้ํา และเป็นมลทินไปจนถึงเวลาเย็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 22, 'และผู้หนึ่งผู้ใดแตะต้องสิ่งใดๆที่เธอนั่ง ผู้นั้นต้องซักเสื้อผ้าและอาบน้ํา และเป็นมลทินไปจนถึงเวลาเย็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 23, 'สิ่งที่เธอนั่งทับจะเป็นที่นอนหรือสิ่งใดก็ดี เมื่อผู้ใดไปแตะต้องเข้า ผู้นั้นจะเป็นมลทินไปจนถึงเวลาเย็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 24, 'ถ้าชายใดไปร่วมหลับนอนกับเธอและมลทินของเธอมาติดที่ชายนั้น ชายนั้นจะเป็นมลทินไปเจ็ดวัน เขาไปนอนที่เตียงใด เตียงนั้นก็เป็นมลทิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 25, 'ถ้าสตรีใดมีโลหิตไหลออกหลายวัน ไม่ใช่เป็นเวลาที่เธอต้องอยู่ต่างหากนั้น หรือถ้าเธอมีโลหิตไหลออกเลยกําหนดที่เธอต้องอยู่ต่างหากนั้น ทุกวันที่มีโลหิตไหลออกเธอจะเป็นมลทิน เธอจะเป็นมลทินอย่างเดียวกับเวลาที่เธอต้องอยู่ต่างหากนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 26, 'ที่นอนทุกหลังที่เธอนอนเมื่อวันเธอมีสิ่งไหลออก ที่นอนนั้นเป็นดังที่นอนในเวลาที่เธอต้องอยู่ต่างหากนั้น และทุกสิ่งที่เธอนั่งทับจะเป็นมลทิน อย่างเดียวกับมลทินในเวลาที่เธอต้องอยู่ต่างหากนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 27, 'ผู้ใดแตะต้องสิ่งเหล่านั้น ผู้นั้นก็เป็นมลทินด้วย เขาต้องซักเสื้อผ้าและอาบน้ํา และเป็นมลทินไปจนถึงเวลาเย็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 28, 'แต่ถ้าเธอชําระสิ่งไหลออกของเธอแล้ว ให้เธอนับเองให้ครบเจ็ดวัน ต่อจากนั้นเธอจึงจะสะอาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 29, 'และในวันที่แปดให้เธอนํานกเขาสองตัว หรือนกพิราบหนุ่มสองตัวไปให้ปุโรหิตที่ประตูพลับพลาแห่งชุมนุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 30, 'และปุโรหิตจะถวายนกตัวหนึ่งเป็นเครื่องบูชาไถ่บาป และนกอีกตัวหนึ่งเป็นเครื่องเผาบูชา และปุโรหิตจะทําการลบมลทินให้เธอต่อพระพักตร์พระเยโฮวาห์ ด้วยเรื่องสิ่งไหลออกที่เป็นมลทินของเธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 31, 'ดังนี้แหละพวกเจ้าจะให้คนอิสราเอลแยกจากมลทินของเขาทั้งหลาย เกลือกว่าเขาจะต้องตายด้วยมลทินของเขา เมื่อเขาทําให้พลับพลาของเราที่อยู่ท่ามกลางเขาเป็นมลทินไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 32, 'นี่เป็นพระราชบัญญัติเรื่องผู้มีสิ่งไหลออกและชายที่มีน้ํากามไหลออก ซึ่งกระทําให้ตัวเป็นมลทิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 33, 'และเกี่ยวกับสตรีที่ป่วยด้วยมลทินของเธอ คือทั้งนี้เกี่ยวกับผู้ที่มีสิ่งไหลออกไม่ว่าชายหรือหญิง และเกี่ยวกับชายผู้ร่วมหลับนอนกับหญิงผู้มีมลทิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 1, 'พระเยโฮวาห์ตรัสกับโมเสสหลังจากที่บุตรชายทั้งสองของอาโรนสิ้นชีวิต คือเมื่อเขากระทําบูชาถวายต่อพระพักตร์พระเยโฮวาห์และถึงแก่ความตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 2, 'และพระเยโฮวาห์ตรัสกับโมเสสว่า “เจ้าจงบอกอาโรนพี่ชายว่า อย่าเข้าไปในสถานที่บริสุทธิ์ที่อยู่ในม่านหน้าพระที่นั่งกรุณาซึ่งอยู่บนหลังหีบ ตลอดทุกเวลา เพื่อเขาจะไม่ตาย เพราะว่าเราจะปรากฏในเมฆเหนือพระที่นั่งกรุณา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 3, 'แต่อาโรนจะเข้ามาในที่บริสุทธิ์ได้ดังนี้ คือให้เอาวัวหนุ่มตัวหนึ่งไปเป็นเครื่องบูชาไถ่บาป และแกะผู้ตัวหนึ่งเป็นเครื่องเผาบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 4, 'ให้เขาสวมเสื้อป่านบริสุทธิ์และสวมกางเกงผ้าป่าน คาดรัดประคดผ้าป่าน และสวมผ้ามาลาป่าน นี่เป็นเครื่องแต่งกายบริสุทธิ์ เขาจะต้องอาบน้ําแล้วจึงสวม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 5, 'และให้เขานําแพะผู้สองตัวเป็นเครื่องบูชาไถ่บาปกับแกะผู้ตัวหนึ่งเป็นเครื่องเผาบูชาจากชุมนุมชนอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 6, 'และอาโรนจะถวายวัวเป็นเครื่องบูชาไถ่บาปของตนเอง และจะทําการลบมลทินบาปตนเองและครอบครัวของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 7, 'แล้วเขาจะนําแพะสองตัวนั้นไปถวายต่อพระพักตร์พระเยโฮวาห์ที่ประตูพลับพลาแห่งชุมนุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 8, 'และอาโรนจะจับฉลากแพะสองตัวนั้น ฉลากหนึ่งตกเป็นของพระเยโฮวาห์ และอีกฉลากหนึ่งเพื่อแพะรับบาป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 9, 'แพะตัวที่ฉลากตกเป็นของพระเยโฮวาห์นั้น อาโรนจะนํามาถวายเป็นเครื่องบูชาไถ่บาป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 10, 'แต่แพะอีกตัวหนึ่งซึ่งฉลากตกเพื่อเป็นแพะรับบาปนั้น จะนําถวายต่อพระพักตร์พระเยโฮวาห์เป็นสัตว์เป็น เพื่อทําการลบมลทินบาปให้ตกที่มัน แล้วจะได้เอามันไปปล่อยเสียในถิ่นทุรกันดารเป็นแพะรับบาป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 11, 'อาโรนจะถวายวัวเป็นเครื่องไถ่บาปของตน และจะทําการลบมลทินบาปตนเอง กับครอบครัวของตน เขาจะฆ่าวัวเป็นเครื่องบูชาไถ่บาปของเขาเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 12, 'และอาโรนจะเอากระถางไฟที่มีถ่านลุกอยู่เต็มมาจากแท่นบูชาต่อพระพักตร์พระเยโฮวาห์ และเครื่องหอมทุบละเอียดสองกํามือนําเข้าไปภายในม่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 13, 'แล้วเอาเครื่องหอมนั้นใส่ไฟถวายต่อพระพักตร์พระเยโฮวาห์ ให้ควันเครื่องหอมขึ้นคลุมพระที่นั่งกรุณาซึ่งอยู่เหนือหีบพระโอวาท เพื่อเขาจะไม่ตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 14, 'เขาจะเอาเลือดวัวมาประพรมด้วยนิ้วมือของตนบนพระที่นั่งกรุณาข้างตะวันออก แล้วจะประพรมเลือดที่หน้าพระที่นั่งกรุณาเจ็ดครั้งด้วยนิ้วของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 15, 'แล้วอาโรนจะฆ่าแพะอันเป็นเครื่องบูชาไถ่บาปสําหรับประชาชน และนําเลือดแพะเข้าไปภายในม่าน และเอาเลือดแพะไปกระทําเช่นเดียวกับกระทําเลือดวัว คือประพรมบนพระที่นั่งกรุณาและที่ข้างหน้าพระที่นั่งกรุณานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 16, 'ดังนี้แหละเขาจะทําการลบมลทินของสถานที่บริสุทธิ์นั้นเพราะเหตุมลทินของคนอิสราเอลและเพราะเหตุการละเมิด เพราะบาปทั้งสิ้นของเขา และอาโรนจะกระทําต่อพลับพลาแห่งชุมนุมซึ่งอยู่กับเขาท่ามกลางมลทินของประชาชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 17, 'อย่าให้มีผู้ใดอยู่ในพลับพลาแห่งชุมนุมเมื่ออาโรนเข้าไปทําการลบมลทินในสถานที่บริสุทธิ์นั้น จนกว่าเขาจะออกมาและทําการลบมลทินสําหรับตัวเขาและสําหรับครอบครัวของเขาและสําหรับบรรดาชุมนุมชนอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 18, 'และอาโรนจะออกไปยังแท่นซึ่งอยู่ต่อพระพักตร์พระเยโฮวาห์ และทําการลบมลทินแท่นนั้น เขาจะเอาเลือดวัวเลือดแพะเจิมที่เชิงงอนของแท่นโดยรอบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 19, 'และเอานิ้วจุ่มเลือดประพรมบนแท่นนั้นเจ็ดครั้ง และชําระกระทําให้แท่นบริสุทธิ์พ้นจากมลทินของคนอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 20, 'เมื่ออาโรนเสร็จการลบมลทินของสถานที่บริสุทธิ์ และพลับพลาแห่งชุมนุมและแท่นบูชาแล้ว เขาจะนําแพะตัวที่เป็นอยู่ออกมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 21, 'และอาโรนจะเอามือทั้งสองวางบนหัวแพะที่มีชีวิตนั้น และกล่าวคําสารภาพบรรดาความชั่วช้าของคนอิสราเอล และการละเมิดทั้งหมด และบาปทั้งสิ้นให้ตกลงบนหัวแพะนั้น และให้คนที่เตรียมมือไว้พร้อมแล้วมานําแพะไปปล่อยเสียในถิ่นทุรกันดาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 22, 'แพะนั้นจะแบกความชั่วช้าทั้งหมดไปยังที่เปลี่ยว แล้วเขาก็ปล่อยให้แพะนั้นเข้าไปในถิ่นทุรกันดาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 23, 'แล้วอาโรนจะเข้ามาในพลับพลาแห่งชุมนุม เขาจะเปลื้องเครื่องแต่งกายผ้าป่านชุดที่แต่งเข้าไปในสถานที่บริสุทธิ์ออกเสียเก็บไว้ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 24, 'และเขาจะชําระตัวในน้ําในที่บริสุทธิ์แล้วสวมเครื่องแต่งกายของตน และเดินออกมาถวายเครื่องเผาบูชาของตน และเครื่องเผาบูชาของประชาชน และทําการลบมลทินของตนเองกับประชาชนทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 25, 'เขาจะเอาไขมันของเครื่องบูชาไถ่บาปไปเผาเสียบนแท่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 26, 'ผู้ที่นําแพะซึ่งเป็นแพะรับบาปนั้นจะต้องซักเสื้อผ้าของตนและอาบน้ํา แล้วต่อมาจึงจะเข้าในค่ายได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 27, 'เขาจะเอาวัวซึ่งเป็นเครื่องบูชาไถ่บาป และแพะซึ่งเป็นเครื่องบูชาไถ่บาป ที่อาโรนเอาเลือดไปทําการลบมลทินสถานบริสุทธิ์นั้นไปเสียข้างนอกค่าย และเขาจะเผาเนื้อหนังและมูลเสียด้วยไฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 28, 'ผู้ที่ทําการเผาก็ต้องซักเสื้อผ้าของตนและอาบน้ํา ภายหลังเขาจึงจะกลับเข้าค่ายได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 29, 'ให้เป็นกฎเกณฑ์ถาวรแก่เจ้าทั้งหลายว่า ในวันที่สิบเดือนที่เจ็ด เจ้าต้องถ่อมใจลง ไม่กระทําการงานสิ่งใด ทั้งตัวชาวเมืองเองหรือคนต่างด้าวที่อาศัยอยู่ท่ามกลางเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 30, 'เพราะว่าในวันนั้นปุโรหิตจะกระทําการลบมลทินบาปของเจ้า และชําระเจ้า เจ้าจะสะอาดต่อพระพักตร์พระเยโฮวาห์ พ้นจากบาปทั้งสิ้นของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 31, 'เป็นวันสะบาโตให้เจ้าทั้งหลายหยุดพักสงบ และเจ้าต้องถ่อมใจลง ทั้งนี้ให้เป็นกฎเกณฑ์ถาวรตลอดไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 32, 'ปุโรหิตผู้ที่ถูกเจิม และถูกสถาปนาให้ปรนนิบัติในตําแหน่งปุโรหิตแทนบิดาของตน จะต้องทําการลบมลทินโดยสวมเสื้อป่าน คือเครื่องยศอันบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 33, 'ให้เขาทําการลบมลทินแก่สถานที่บริสุทธิ์ และเขาจะทําการลบมลทินให้แก่พลับพลาแห่งชุมนุม และให้แก่แท่น และเขาจะทําการลบมลทินให้แก่ปุโรหิตและประชาชนทั้งหมดในชุมนุมชนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 34, 'ทั้งนี้ให้เป็นกฎเกณฑ์ถาวรแก่เจ้าทั้งหลาย ให้ทําการลบมลทินบาปเพื่อคนอิสราเอลปีละครั้ง เพราะบาปทั้งสิ้นของเขา” และเขาก็กระทําตามที่พระเยโฮวาห์ทรงบัญชากับโมเสสไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 1, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 2, '“จงกล่าวแก่อาโรนและบุตรชายทั้งหลายของเขา และแก่บรรดาคนอิสราเอลว่า ต่อไปนี้เป็นสิ่งซึ่งพระเยโฮวาห์ได้ทรงบัญชาไว้ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 3, 'ถ้าคนใดในวงศ์วานอิสราเอลฆ่าวัวหรือลูกแกะ หรือแพะในค่าย หรือฆ่าภายนอกค่าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 4, 'และมิได้นํามาที่ประตูพลับพลาแห่งชุมนุมเพื่อถวายเป็นของบูชาแด่พระเยโฮวาห์ที่หน้าพลับพลาแห่งพระเยโฮวาห์ ผู้นั้นต้องมีโทษด้วยมีบาปเรื่องเลือด คือเขาทําให้เลือดตก ผู้นั้นจะต้องถูกตัดขาดจากชนชาติของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 5, 'ทั้งนี้เพื่อประสงค์ให้คนอิสราเอลนําเครื่องถวายซึ่งเขาฆ่าที่พื้นทุ่งมาถวายแด่พระเยโฮวาห์มายังปุโรหิตที่ประตูพลับพลาแห่งชุมนุม และเอาสัตว์นั้นเป็นสันติบูชาถวายแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 6, 'และปุโรหิตจะเอาเลือดสัตว์นั้นประพรมบนแท่นบูชาพระเยโฮวาห์ที่ประตูพลับพลาแห่งชุมนุม และเผาไขมันให้เป็นกลิ่นที่พอพระทัยถวายแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 7, 'เขาก็จะไม่ถวายบูชาแก่ภูตผีปีศาจอีกต่อไปซึ่งเขาทั้งหลายเล่นชู้นั้น ให้เรื่องนี้เป็นกฎเกณฑ์แก่เขาตลอดชั่วอายุของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 8, 'และเจ้าจงกล่าวแก่เขาว่า วงศ์วานอิสราเอลคนใดหรือคนต่างด้าวคนใดผู้อาศัยอยู่ในหมู่พวกเจ้า ผู้ถวายเครื่องเผาบูชาหรือเครื่องสัตวบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 9, 'และมิได้นําเครื่องบูชานั้นมาที่ประตูพลับพลาแห่งชุมนุมเพื่อถวายแด่พระเยโฮวาห์ ผู้นั้นจะต้องถูกตัดขาดจากชนชาติของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 10, 'ถ้าผู้ใดก็ตามในวงศ์วานอิสราเอลหรือในพวกคนต่างด้าวที่อาศัยอยู่ท่ามกลางเจ้ารับประทานเลือดในลักษณะใดลักษณะหนึ่ง เราจะตั้งหน้าของเราต่อสู้ผู้รับประทานเลือดนั้น และจะตัดเขาออกเสียจากชนชาติของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 11, 'เพราะว่าชีวิตของเนื้อหนังอยู่ในเลือด เราได้ให้เลือดแก่เจ้าเพื่อใช้บนแท่น เพื่อกระทําการลบมลทินบาปแห่งจิตวิญญาณของเจ้า เพราะว่าเลือดเป็นที่ทําการลบมลทินบาปแห่งจิตวิญญาณ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 12, 'เพราะฉะนั้นเราจึงได้พูดกับคนอิสราเอลว่า ในพวกเจ้าอย่าให้คนใดรับประทานเลือดเลย หรือคนต่างด้าวผู้อาศัยท่ามกลางเจ้าก็อย่าได้รับประทานเลือด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 13, 'คนอิสราเอลคนใดหรือคนต่างด้าวที่อาศัยอยู่ท่ามกลางเจ้า ไปล่าสัตว์หรือนกเพื่อนํามารับประทานก็ให้หลั่งเลือดออกแล้วเอาฝุ่นกลบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 14, 'เพราะว่าชีวิตของเนื้อหนังทั้งปวงอยู่ในเลือด เลือดของสิ่งใดก็คือชีวิตของสิ่งนั้นเอง เพราะฉะนั้นเราจึงได้กล่าวแก่ลูกหลานอิสราเอลว่า เจ้าอย่ารับประทานเลือดของเนื้อหนังใดๆเลย เพราะว่าชีวิตของเนื้อหนังทั้งปวงคือเลือดนั่นเอง ผู้ใดก็ตามรับประทานเลือดนั้นก็ต้องถูกตัดขาดเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 15, 'และทุกคนไม่ว่าชาวเมืองหรือคนต่างด้าว ผู้รับประทานสัตว์ที่ตายเองหรือสัตว์ที่ถูกสัตว์อื่นกัดตาย ต้องซักเสื้อผ้าและอาบน้ํา และเป็นมลทินอยู่จนถึงเวลาเย็น แล้วจึงจะสะอาดได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 16, 'แต่ถ้าเขาไม่ซักเสื้อผ้าหรืออาบน้ํา เขาต้องรับโทษความชั่วช้าของเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 1, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 2, '“จงกล่าวแก่คนอิสราเอลว่า เราคือพระเยโฮวาห์พระเจ้าของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 3, 'เจ้าทั้งหลายอย่ากระทําดังที่เขากระทํากันในแผ่นดินอียิปต์ซึ่งเจ้าเคยอาศัยอยู่นั้น และเจ้าอย่ากระทําดังที่เขากระทํากันในแผ่นดินคานาอัน ซึ่งเรากําลังพาเจ้าไปนั้น เจ้าอย่าดําเนินตามกฎของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 4, 'เจ้าทั้งหลายจงกระทําตามคําตัดสินของเราและรักษากฎของเราและดําเนินตาม เราคือพระเยโฮวาห์พระเจ้าของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 5, 'เพราะฉะนั้นเจ้าทั้งหลายจึงต้องรักษากฎเกณฑ์ของเรา และคําตัดสินของเรา ด้วยการกระทําตามนั่นแหละ มนุษย์จึงจะมีชีวิตอยู่ได้ เราคือพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 6, 'อย่าให้ผู้ใดในพวกเจ้าเข้าใกล้ญาติสนิทของตนเพื่อเปิดกายที่เปลือยเปล่าของเขา เราคือพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 7, 'เจ้าอย่าเปิดกายที่เปลือยเปล่าของบิดาเจ้าหรือกายที่เปลือยเปล่าของมารดาเจ้า นางเป็นมารดาของเจ้า เจ้าอย่าเปิดกายที่เปลือยเปล่าของนางเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 8, 'เจ้าอย่าเปิดกายที่เปลือยเปล่าของภรรยาของบิดาเจ้า เพราะเป็นกายที่เปลือยเปล่าของบิดาเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 9, 'เจ้าอย่าเปิดกายที่เปลือยเปล่าของพี่สาวหรือน้องสาวของเจ้า คือบุตรสาวของบิดาเจ้า หรือบุตรสาวของมารดาเจ้า ไม่ว่าเธอจะเกิดที่บ้านหรือเกิดต่างแดนก็ตาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 10, 'เจ้าอย่าเปิดกายที่เปลือยเปล่าของบุตรสาวของบุตรชายเจ้า หรือกายที่เปลือยเปล่าของบุตรสาวของบุตรสาวเจ้า เพราะว่ากายที่เปลือยเปล่าของเขาก็เป็นกายที่เปลือยเปล่าของเจ้าเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 11, 'เจ้าอย่าเปิดกายที่เปลือยเปล่าของบุตรสาวของภรรยาของบิดาเจ้า ซึ่งเกิดจากบิดาเจ้าเอง เพราะว่าเธอเป็นพี่สาวหรือน้องสาวของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 12, 'เจ้าอย่าเปิดกายที่เปลือยเปล่าของพี่สาวหรือน้องสาวของบิดาเจ้า เพราะเธอเป็นญาติผู้หญิงที่ใกล้ชิดของบิดาเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 13, 'เจ้าอย่าเปิดกายที่เปลือยเปล่าของพี่สาวหรือน้องสาวของมารดาเจ้า เพราะเธอเป็นญาติผู้หญิงที่ใกล้ชิดของมารดาเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 14, 'เจ้าอย่าเปิดกายที่เปลือยเปล่าของพี่ชายหรือน้องชายของบิดาเจ้า คือเจ้าอย่าเข้าหาภรรยาของเขา เพราะเธอเป็นป้าของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 15, 'เจ้าอย่าเปิดกายที่เปลือยเปล่าของลูกสะใภ้ของเจ้า เธอเป็นภรรยาบุตรชายเจ้า เจ้าอย่าเปิดกายที่เปลือยเปล่าของเธอเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 16, 'เจ้าอย่าเปิดกายที่เปลือยเปล่าของภรรยาของพี่ชายหรือน้องชายของเจ้า เพราะเป็นกายที่เปลือยเปล่าของพี่น้องผู้ชายของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 17, 'เจ้าอย่าเปิดกายที่เปลือยเปล่าของผู้หญิงคนใดคนหนึ่งและของบุตรสาวของนาง และเจ้าอย่านําบุตรสาวของบุตรชายของนาง หรือบุตรสาวของบุตรสาวของนางไปเปิดกายที่เปลือยเปล่า เพราะว่าพวกเธอเป็นญาติผู้หญิงที่ใกล้ชิดของนาง เป็นการชั่วร้ายนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 18, 'และเจ้าอย่าพาภรรยาไปหาพี่สาวหรือน้องสาวของนางเพื่อจะก่อกวนและเปิดกายที่เปลือยเปล่าของเธอ ขณะเมื่อภรรยายังมีชีวิตอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 19, 'และเจ้าอย่าเข้าใกล้ผู้หญิงคนใดคนหนึ่งเพื่อเปิดกายที่เปลือยเปล่าของนาง ตราบใดที่นางยังถูกแยกไว้ต่างหากเพราะมลทินของนาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 20, 'เจ้าอย่าร่วมหลับนอนกับภรรยาของเพื่อนบ้านของเจ้า กระทําให้ตัวเจ้าลามกอนาจารกับนาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 21, 'เจ้าอย่าถวายเชื้อสายของเจ้าให้พระโมเลคด้วยให้ลุยไฟ และอย่ากระทําให้พระนามพระเจ้าของเจ้าเสื่อมเกียรติ เราคือพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 22, 'เจ้าอย่าร่วมหลับนอนกับผู้ชายใช้ต่างผู้หญิง เป็นสิ่งที่น่าสะอิดสะเอียน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 23, 'เจ้าอย่าสมสู่กับสัตว์เดียรัจฉาน กระทําตนให้ลามกอนาจาร หรืออย่าให้หญิงคนใดยอมตัวสมสู่กับสัตว์เดียรัจฉาน ดังนี้เป็นเรื่องกามวิปลาส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 24, 'เจ้าทั้งหลายอย่ากระทําตัวให้ลามกอนาจารด้วยสิ่งเหล่านี้เลย เพราะว่าบรรดาประชาชาติที่เราได้ไล่ไปเสียต่อหน้าเจ้านั้น กระทําบรรดาความลามกอนาจารอย่างนี้เอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 25, 'และแผ่นดินนั้นก็ลามก เราจึงต้องลงโทษความชั่วช้าแก่แผ่นดินนั้น และแผ่นดินก็สํารอกเอาพลเมืองของตนออกเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 26, 'เหตุฉะนั้นเจ้าทั้งหลายจะต้องรักษากฎเกณฑ์ของเราและคําตัดสินของเรา และอย่ากระทําสิ่งที่น่าสะอิดสะเอียนเหล่านี้ ไม่ว่าจะเป็นผู้ใดในชาติของเจ้าเองหรือคนต่างด้าวใดๆที่อาศัยอยู่ในหมู่พวกเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 27, '(ประชาชนในแผ่นดินผู้อยู่ก่อนเจ้าได้กระทําบรรดาสิ่งที่น่าสะอิดสะเอียนเหล่านี้ ดังนั้นแผ่นดินจึงเป็นมลทิน)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 28, 'เกลือกว่าเมื่อเจ้าทั้งหลายทําให้แผ่นดินเป็นลามก แผ่นดินก็จะสํารอกเจ้าออก ดังที่แผ่นดินได้สํารอกประชาชาติที่อยู่ก่อนเจ้าออกไปนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 29, 'เพราะผู้ใดก็ตามกระทําสิ่งที่น่าสะอิดสะเอียนใดๆเหล่านี้ ผู้กระทําสิ่งเหล่านี้จะต้องถูกตัดขาดจากชนชาติของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 30, 'เหตุฉะนั้นเจ้าทั้งหลายจงรักษากฎของเรา เจ้าอย่าประพฤติตามธรรมเนียมอันน่าสะอิดสะเอียนเหล่านี้ ซึ่งเขาประพฤติกันมาก่อนเจ้า และอย่าทําตัวเจ้าให้เป็นมลทินด้วยสิ่งเหล่านี้ เราคือพระเยโฮวาห์พระเจ้าของเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 1, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 2, '“จงกล่าวแก่บรรดาชุมนุมชนอิสราเอลว่า เจ้าทั้งหลายจงเป็นคนบริสุทธิ์ เพราะเราคือพระเยโฮวาห์พระเจ้าของเจ้าเป็นผู้บริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 3, 'เจ้าทุกคนต้องเคารพมารดาและบิดาของตน และเจ้าต้องรักษาบรรดาสะบาโตของเรา เราคือพระเยโฮวาห์พระเจ้าของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 4, 'อย่าให้ผู้ใดกลับนับถือรูปเคารพ หรือหล่อพระไว้เป็นรูปเคารพสําหรับตน เราคือพระเยโฮวาห์พระเจ้าของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 5, 'เมื่อเจ้าถวายสันติบูชาแด่พระเยโฮวาห์ จงถวายด้วยความเต็มใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 6, 'เจ้าจงรับประทานเครื่องบูชานั้นเสียในวันที่เจ้าถวายบูชาหรือในวันรุ่งขึ้น ถ้ามีส่วนใดเหลืออยู่จนวันที่สาม จงเผาไฟเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 7, 'ถ้าเอาเครื่องบูชานั้นมารับประทานในวันที่สามก็เป็นที่น่าสะอิดสะเอียน ไม่เป็นที่โปรดปรานเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 8, 'เพราะฉะนั้นทุกคนที่รับประทานเครื่องบูชานั้นต้องรับโทษความชั่วช้าของเขา เพราะเขาได้ลบหลู่สิ่งบริสุทธิ์ของพระเยโฮวาห์ ผู้นั้นจะต้องถูกตัดขาดจากชนชาติของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 9, 'เมื่อเจ้าทั้งหลายเกี่ยวข้าวในนา อย่าเกี่ยวเก็บข้าวที่ขอบนาให้หมด เมื่อเกี่ยวแล้วก็อย่าเก็บข้าวที่ตก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 10, 'อย่าเก็บผลที่สวนองุ่นให้หมด เจ้าอย่าเก็บองุ่นที่ตกในสวนของเจ้า จงเหลือไว้ให้คนยากจนและคนต่างด้าวบ้าง เราคือพระเยโฮวาห์พระเจ้าของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 11, 'เจ้าอย่าลักทรัพย์ หรือโกงหรือมุสาต่อกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 12, 'อย่าสาบานออกนามของเราเป็นความเท็จ หรือกระทําให้พระนามพระเจ้าของเจ้าเป็นที่เหยียดหยาม เราคือพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 13, 'เจ้าอย่าฉ้อโกงเพื่อนบ้านหรือปล้นเขา อย่าให้ค่าจ้างของลูกจ้างค้างอยู่กับเจ้าจนถึงรุ่งเช้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 14, 'เจ้าอย่าแช่งคนหูหนวก หรือวางของให้คนตาบอดสะดุด แต่เจ้าจงยําเกรงพระเจ้าของเจ้า เราคือพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 15, 'เจ้าอย่าพิพากษาด้วยความอยุติธรรม เจ้าอย่าลําเอียงเข้าข้างคนจนหรือเห็นแก่หน้าผู้เป็นใหญ่ แต่เจ้าจงพิพากษาเพื่อนบ้านของเจ้าด้วยความชอบธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 16, 'อย่าเทียวขึ้นเทียวล่องคอยส่อเสียดท่ามกลางชนชาติของตน และอย่าปองร้ายต่อเลือดของเพื่อนบ้าน เราคือพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 17, 'อย่าเกลียดชังพี่น้องของเจ้าอยู่ในใจ แต่เจ้าจงตักเตือนเพื่อนบ้านของเจ้า เพื่อเจ้าจะไม่ต้องรับโทษเพราะเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 18, 'เจ้าอย่าแก้แค้นหรือผูกพยาบาทลูกหลานญาติพี่น้องของเจ้า แต่เจ้าจงรักเพื่อนบ้านเหมือนรักตนเอง เราคือพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 19, 'เจ้าจงรักษากฎเกณฑ์ของเรา เจ้าอย่าประสมสัตว์ของเจ้ากับสัตว์ประเภทอื่น เจ้าอย่าหว่านพืชปนกันสองชนิดในนาของเจ้า อย่าใช้เครื่องแต่งกายที่ทําด้วยขนสัตว์ปนด้วยป่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 20, 'ถ้าผู้ใดเข้านอนกับผู้หญิงที่เป็นทาสี ที่ชายอีกคนหนึ่งสู่ขอไว้แล้วแต่ยังมิได้ไถ่ถอนหรือปล่อยเป็นอิสระ ต้องลงโทษเธอ แต่อย่าให้ถึงตาย เพราะว่าทาสีนั้นยังไม่เป็นอิสระ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 21, 'แต่ให้ผู้นั้นนําเครื่องบูชาไถ่การละเมิดสําหรับตัวเขาถวายแด่พระเยโฮวาห์ที่ประตูพลับพลาแห่งชุมนุม คือแกะผู้ตัวหนึ่งเป็นเครื่องบูชาไถ่การละเมิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 22, 'และปุโรหิตจะทําการลบมลทินบาปของเขาด้วยถวายแกะผู้นั้นเป็นเครื่องบูชาไถ่การละเมิดต่อพระพักตร์พระเยโฮวาห์ เพราะบาปซึ่งเขาได้กระทําไป และให้เขาได้รับการอภัยบาปที่เขาได้กระทําไปนั้นเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 23, 'เมื่อเจ้าเข้าไปในแผ่นดินและปลูกต้นไม้ทุกชนิดที่มีผลเป็นอาหาร ผลที่ได้นั้นต้องเป็นผลที่ถือว่ามิได้เข้าสุหนัต สามปีเป็นผลที่ถือว่ามิได้เข้าสุหนัตแก่เจ้า เจ้าอย่ารับประทานเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 24, 'และปีที่สี่ ผลที่ได้ทั้งหมดจะเป็นของบริสุทธิ์เพื่อใช้ในการสรรเสริญพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 25, 'แต่ในปีที่ห้าเจ้าจงรับประทานผลไม้นั้นได้ เพื่อจะบังเกิดผลทวีขึ้นเพื่อเจ้า เราคือพระเยโฮวาห์พระเจ้าของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 26, 'เจ้าอย่ารับประทานเนื้อสัตว์ที่มีเลือดในเนื้อนั้น เจ้าอย่าเป็นหมอผีหรือเป็นหมอดู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 27, 'เจ้าอย่ากันผมที่จอนหูหรือกันริมเคราของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 28, 'เจ้าอย่าเชือดเนื้อของเจ้าเพราะเหตุมีคนตาย หรือสักเป็นเครื่องหมายใดๆลงที่ตัวเจ้า เราคือพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 29, 'อย่าทําบุตรสาวของตนให้เป็นคนลามกด้วยให้เป็นหญิงโสเภณี เกลือกว่าแผ่นดินนั้นจะเป็นถิ่นโสเภณี และแผ่นดินจะเต็มด้วยความลามก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 30, 'เจ้าจงถือรักษาสะบาโตทั้งหลายของเรา และแสดงความเคารพต่อสถานบริสุทธิ์ของเรา เราคือพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 31, 'อย่าไปหาคนทรงหรือพ่อมดแม่มด อย่าเที่ยวค้นหา ให้ตนมลทินไปเพราะเขาเลย เราคือพระเยโฮวาห์พระเจ้าของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 32, 'เจ้าจงลุกขึ้นคํานับคนผมหงอก และเคารพต่อหน้าคนชรา และจงยําเกรงพระเจ้าของเจ้า เราคือพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 33, 'เมื่อคนต่างด้าวอาศัยอยู่กับเจ้าในแผ่นดินของเจ้า อย่าข่มเหงเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 34, 'คนต่างด้าวที่อาศัยอยู่กับเจ้านั้นก็เหมือนกับชาวเมืองของเจ้า เจ้าจงรักเขาเหมือนกับรักตัวเอง เพราะว่าเจ้าเคยเป็นคนต่างด้าวในแผ่นดินอียิปต์ เราคือพระเยโฮวาห์พระเจ้าของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 35, 'เจ้าอย่ากระทําผิดในการพิพากษา ในการวัดความยาว หรือชั่งน้ําหนักหรือนับจํานวน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 36, 'เจ้าจงใช้ตาชั่งเที่ยงตรง ลูกตุ้มเที่ยงตรง เอฟาห์เที่ยงตรง และฮินเที่ยงตรง เราคือพระเยโฮวาห์พระเจ้าของเจ้า ผู้ได้พาเจ้าออกมาจากแผ่นดินอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 37, 'ดังนี้แหละเจ้าจงรักษากฎเกณฑ์ทั้งหมดของเราและคําตัดสินของเราทั้งสิ้นและกระทําตาม เราคือพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 1, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 2, '“จงกล่าวแก่คนอิสราเอลซ้ําอีกว่า คนอิสราเอลคนใดหรือคนต่างด้าวคนใดที่อาศัยอยู่ในอิสราเอล ผู้ที่มอบเชื้อสายของตนให้แก่พระโมเลค ผู้นั้นต้องมีโทษถึงตายเป็นแน่ ให้ประชาชนแห่งแผ่นดินเอาหินขว้างเขาเสียให้ตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 3, 'และเราจะตั้งหน้าของเราต่อสู้ผู้นั้น และจะตัดเขาออกเสียจากท่ามกลางชนชาติของตน เพราะว่าเขาได้มอบเชื้อสายของเขาแก่พระโมเลค กระทําให้สถานบริสุทธิ์ของเราเป็นมลทิน และลบหลู่นามบริสุทธิ์ของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 4, 'และถ้าประชาชนในแผ่นดินนั้นไม่เอาใจใส่ที่จะฆ่าคนนั้นเมื่อเขาให้เชื้อสายแก่พระโมเลค');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 5, 'เราจะตั้งหน้าของเราต่อสู้ผู้นั้น และต่อสู้กับครอบครัวของเขา และจะตัดเขาและผู้ใดที่ทําตามเขาในการเล่นชู้กับพระโมเลคออกเสียจากชนชาติของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 6, 'ผู้ที่หันไปหาคนทรงเจ้าเข้าผีหรือพวกพ่อมดหมอผี เล่นชู้กับเขา เราจะตั้งหน้าของเราต่อสู้ผู้นั้นและจะตัดเขาออกเสียจากชนชาติของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 7, 'เหตุฉะนั้นเจ้าจงชําระตัวให้บริสุทธิ์ เพราะเราคือพระเยโฮวาห์พระเจ้าของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 8, 'จงรักษากฎเกณฑ์ของเราและกระทําตาม เราคือพระเยโฮวาห์ผู้ตั้งเจ้าไว้ให้บริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 9, 'เพราะว่าทุกคนที่แช่งบิดาหรือมารดาของตนจะต้องมีโทษถึงตายเป็นแน่ เขาได้แช่งบิดาหรือมารดาของเขา ให้โลหิตของผู้นั้นตกอยู่บนผู้นั้นเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 10, 'ถ้าผู้ใดร่วมประเวณีกับภรรยาของผู้อื่น คือเขาได้ร่วมประเวณีกับภรรยาของเพื่อนบ้าน ต้องให้ผู้ร่วมประเวณีทั้งชายและหญิงนั้นมีโทษถึงตายเป็นแน่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 11, 'ผู้ชายที่หลับนอนกับภรรยาของบิดาตนก็ได้เปิดกายที่เปลือยเปล่าของบิดาตน ทั้งสองคนนั้นจะต้องถูกประหารให้ตายอย่างแน่นอน ให้โลหิตของผู้นั้นตกอยู่บนผู้นั้นเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 12, 'ถ้าผู้ใดเข้านอนกับลูกสะใภ้ ต้องให้ทั้งสองคนนั้นมีโทษถึงตายเป็นแน่ เพราะเขาได้กระทํากามวิปลาส ให้โลหิตของผู้นั้นตกอยู่บนผู้นั้นเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 13, 'ถ้าชายคนใดคนหนึ่งหลับนอนกับผู้ชายด้วยกันเหมือนอย่างที่เขาหลับนอนกับผู้หญิง ทั้งสองคนก็ได้กระทําสิ่งที่น่าสะอิดสะเอียน ทั้งสองคนนั้นจะต้องถูกประหารให้ตายอย่างแน่นอน ให้โลหิตของผู้นั้นตกอยู่บนผู้นั้นเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 14, 'และถ้าชายใดได้ภรรยาและได้มารดาของนางมาเป็นภรรยาด้วย นี่เป็นเรื่องชั่วนัก ให้เผาทั้งชายนั้นและหญิงทั้งสองนั้นเสียด้วยไฟ เพื่อว่าจะไม่มีความชั่วร้ายในหมู่พวกเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 15, 'ถ้าชายใดสมสู่กับสัตว์เดียรัจฉาน ต้องให้ชายคนนั้นมีโทษถึงตายเป็นแน่ และเจ้าจงฆ่าสัตว์เดียรัจฉานนั้นเสียให้ตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 16, 'ถ้าหญิงคนใดเข้าใกล้สัตว์เดียรัจฉาน และเข้านอนกับมัน เจ้าจงฆ่าหญิงนั้นและสัตว์เดียรัจฉานนั้นเสียให้ตาย ทั้งสองต้องมีโทษถึงตายเป็นแน่ ให้โลหิตของผู้นั้นตกอยู่บนผู้นั้นเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 17, 'ถ้าชายใดพาพี่สาวหรือน้องสาวของตน คือบุตรสาวของบิดา หรือบุตรสาวของมารดา และดูการเปลือยกายของเธอและเธอก็ดูการเปลือยกายของเขา นี่เป็นสิ่งที่น่าอายมาก เขาจะต้องถูกตัดขาดท่ามกลางสายตาของชนชาติของเขา เพราะเขาได้เปิดกายที่เปลือยเปล่าของพี่สาวน้องสาวของเขา เขาต้องรับโทษความชั่วช้าของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 18, 'ถ้าชายใดเข้านอนกับหญิงผู้มีประจําเดือน และเปิดกายที่เปลือยเปล่าของเธอ เขาได้กระทําให้แหล่งโลหิตของเธอเปิด ส่วนเธอก็เปิดแหล่งโลหิตของเธอ เขาทั้งสองจะต้องถูกตัดขาดจากชนชาติของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 19, 'เจ้าอย่าเปิดกายที่เปลือยเปล่าของพี่สาวหรือน้องสาวมารดาเจ้า หรือพี่สาวน้องสาวของบิดาเจ้า เพราะผู้นั้นได้เปิดกายที่เปลือยเปล่าของญาติสนิท เขาจะต้องรับโทษความชั่วช้าของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 20, 'ถ้าชายคนใดคนหนึ่งหลับนอนกับภรรยาของลุง เขาได้เปิดกายที่เปลือยเปล่าของลุง ทั้งสองจะต้องรับโทษบาปของเขา เขาจะต้องตายโดยไม่มีบุตร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 21, 'ถ้าชายคนใดคนหนึ่งเอาภรรยาของพี่ชายหรือน้องชายไป ก็เป็นการมลทิน เขาได้เปิดกายที่เปลือยเปล่าของพี่ชายหรือน้องชาย เขาเหล่านั้นจะต้องไม่มีบุตร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 22, 'เพราะฉะนั้นเจ้าจงรักษากฎเกณฑ์ทั้งสิ้นของเรา และคําตัดสินทั้งสิ้นของเราและกระทําตาม เพื่อว่าแผ่นดินซึ่งเรานําเจ้าให้มาอยู่นั้นจะมิได้สํารอกเจ้าให้ออกไปเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 23, 'และเจ้าอย่าดําเนินตามธรรมเนียมของประชาชาติที่เราไล่ไปเสียให้พ้นหน้าเจ้า ด้วยว่าเขาทั้งหลายได้ประพฤติผิดในสิ่งทั้งปวงเหล่านี้ เราจึงเกลียดชังเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 24, 'แต่เราได้บอกเจ้าแล้วว่า เจ้าทั้งหลายจะได้รับแผ่นดินนี้เป็นมรดก เราจะให้แก่เจ้าเป็นกรรมสิทธิ์ เป็นแผ่นดินที่มีน้ํานมและน้ําผึ้งไหลบริบูรณ์ เราคือพระเยโฮวาห์พระเจ้าของเจ้า ผู้ได้แยกเจ้าออกจากชนชาติทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 25, 'เหตุฉะนั้นเจ้าจงแยกแยะความแตกต่างระหว่างสัตว์สะอาดและสัตว์มลทิน ระหว่างนกมลทินและนกสะอาด เจ้าอย่ากระทําตัวให้เป็นสิ่งที่น่าสะอิดสะเอียนด้วยสัตว์หรือนกหรือสิ่งมีชีวิตในลักษณะใดๆ ที่เลื้อยคลานอยู่บนดิน ซึ่งเราได้แยกให้เจ้าแล้วว่าเป็นสิ่งมลทิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 26, 'เจ้าต้องบริสุทธิ์สําหรับเรา เพราะเราคือพระเยโฮวาห์บริสุทธิ์ และได้แยกเจ้าออกจากชนชาติทั้งหลายเพื่อเจ้าจะเป็นของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 27, 'ชายหรือหญิงคนใดที่เป็นคนทรงหรือพ่อมดแม่มด จะต้องมีโทษถึงตายเป็นแน่ จงเอาหินขว้างให้ตาย ให้โลหิตของผู้นั้นตกอยู่บนผู้นั้นเอง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 1, 'พระเยโฮวาห์ตรัสกับโมเสสว่า “จงกล่าวแก่บรรดาปุโรหิต คือลูกหลานของอาโรนและสั่งเขาว่า อย่าให้ผู้ใดกระทําตัวให้มลทินด้วยเรื่องศพในหมู่ประชาชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 2, 'เว้นแต่ญาติที่สนิทที่สุดคือ มารดา บิดา บุตรชายหญิง พี่ชายน้องชาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 3, 'หรือพี่สาวน้องสาวพรหมจารี ผู้ที่ยังสนิทกับเขา เพราะเธอยังไม่มีสามี เขาจึงยอมตัวเป็นมลทินเพราะเธอได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 4, 'อย่าให้เขามีมลทินคือกระทําให้ตนเองเป็นมลทิน เพราะเหตุเขาเป็นผู้ใหญ่ในหมู่ชนชาติของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 5, 'ห้ามมิให้เขาทั้งหลายโกนศีรษะ หรือกันริมเครา หรือเชือดเนื้อตัวเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 6, 'พวกปุโรหิตต้องเป็นคนบริสุทธิ์ต่อพระเจ้าของตน และไม่กระทําให้พระนามของพระเจ้าเป็นที่เหยียดหยาม เพราะเขาทั้งหลายถวายเครื่องบูชาด้วยไฟแด่พระเยโฮวาห์ และพระกระยาหารแห่งพระเจ้าของเขาทั้งหลาย เพราะฉะนั้นเขาทั้งหลายจึงต้องบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 7, 'ปุโรหิตจะแต่งงานกับหญิงโสเภณีหรือหญิงที่มีมลทินไม่ได้ หรือจะแต่งงานกับหญิงที่หย่าจากสามีก็ไม่ได้ เพราะปุโรหิตจะต้องบริสุทธิ์แด่พระเจ้าของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 8, 'เจ้าจงชําระเขาให้บริสุทธิ์ เพราะเขาถวายพระกระยาหารแห่งพระเจ้าของเจ้า เขาจะต้องบริสุทธิ์สําหรับเจ้า เพราะเราคือพระเยโฮวาห์ผู้ชําระเจ้าทั้งหลายให้บริสุทธิ์ เราบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 9, 'บุตรสาวของปุโรหิตคนใด ถ้าเธอกระทําตัวให้มลทินโดยไปเป็นหญิงโสเภณีก็กระทําให้บิดาเป็นมลทิน จะต้องเผาเธอเสียด้วยไฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 10, 'และผู้ที่เป็นมหาปุโรหิตในหมู่พวกพี่น้อง ผู้ถูกเจิมที่ศีรษะด้วยน้ํามัน และผู้ที่ได้รับการสถาปนาที่จะสวมเสื้อยศ อย่าปล่อยผม หรือฉีกเสื้อผ้าของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 11, 'อย่าให้เขาเข้าไปถูกต้องศพหรือกระทําตัวให้มลทิน แม้ว่าศพนั้นเป็นบิดาหรือมารดาของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 12, 'อย่าให้เขาออกไปจากสถานบริสุทธิ์ หรือกระทําสถานบริสุทธิ์ของพระเจ้าให้เป็นมลทิน เพราะว่าการสถาปนาด้วยน้ํามันเจิมของพระเจ้าอยู่บนตัวเขา เราคือพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 13, 'เขาจะต้องมีภรรยาเป็นหญิงพรหมจารี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 14, 'อย่าให้เขาแต่งงานกับหญิงม่าย แม่ร้าง หญิงที่มีมลทิน หรือหญิงโสเภณี เขาจะต้องหาหญิงพรหมจารีในชนชาติของเขามาเป็นภรรยา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 15, 'เพื่อเขาจะมิได้กระทําให้เชื้อสายของเขาในหมู่ชนชาติของเขาเป็นมลทิน เพราะเราคือพระเยโฮวาห์ผู้ตั้งเขาไว้ให้บริสุทธิ์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 16, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 17, '“จงกล่าวแก่อาโรนว่า ผู้ใดก็ตามในเชื้อสายของเจ้าตลอดชั่วอายุที่มีตําหนิพิการใดๆ อย่าให้ผู้นั้นเข้าไปถวายพระกระยาหารแห่งพระเจ้าของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 18, 'เพราะว่าผู้ใดที่มีตําหนิจะเข้าใกล้ไม่ได้ ไม่ว่าเป็นคนตาบอดหรือเป็นคนง่อย หรือที่หน้ามีแผลเป็น หรือแขนขายาวเกิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 19, 'หรือมีเท้าพิการหรือมือพิการ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 20, 'คนหลังค่อม คนแคระ คนเสียตา คนเป็นขี้กลากหรือหิด หรือคนมีลูกอัณฑะฝ่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 21, 'ผู้ใดในเชื้อสายของอาโรนปุโรหิตที่มีตําหนิ อย่าให้เข้ามาถวายเครื่องบูชาด้วยไฟแด่พระเยโฮวาห์ เพราะว่าเขาเป็นคนมีตําหนิ อย่าให้เขาเข้ามาใกล้ถวายพระกระยาหารแห่งพระเจ้าของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 22, 'เขาจะรับประทานพระกระยาหารแห่งพระเจ้าของเขาได้ ทั้งของที่บริสุทธิ์ที่สุด และของบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 23, 'แต่อย่าให้เขาเข้ามาใกล้ม่านหรือใกล้แท่น เพราะเขามีตําหนิ เพื่อเขาจะไม่กระทําให้สถานบริสุทธิ์ของเราเป็นมลทิน เพราะเราคือพระเยโฮวาห์ผู้ตั้งเขาไว้ให้บริสุทธิ์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 24, 'โมเสสจึงบอกอาโรนและลูกหลานของอาโรนและบรรดาคนอิสราเอลดังนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 1, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 2, '“จงบอกอาโรนกับลูกหลานของเขาให้ออกห่างเสียจากสิ่งบริสุทธิ์ของคนอิสราเอล เพื่อว่าเขาทั้งหลายจะมิได้ลบหลู่นามบริสุทธิ์ของเราด้วยสิ่งที่เขาทั้งหลายถวายแก่เรา เราคือพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 3, 'จงกล่าวแก่เขาทั้งหลายว่า ‘คนใดก็ตามในเชื้อสายของเจ้าตลอดชั่วอายุเข้าใกล้ของบริสุทธิ์ ซึ่งคนอิสราเอลถวายแด่พระเยโฮวาห์ ขณะที่เขามีมลทินอยู่ คนนั้นจะต้องถูกตัดขาดให้พ้นหน้าเรา เราคือพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 4, 'อย่าให้เชื้อสายอาโรนคนใดที่เป็นโรคเรื้อนหรือมีสิ่งไหลออกมารับประทานของบริสุทธิ์ ให้รอจนกว่าเขาสะอาดแล้วก่อน ผู้ใดแตะต้องสิ่งที่มลทินโดยแตะต้องศพหรือผู้ที่มีน้ํากามไหลออก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 5, 'หรือผู้ใดที่แตะต้องสิ่งเลื้อยคลาน ซึ่งกระทําให้เขามลทิน หรือแตะต้องคนซึ่งอาจทําให้เขามลทิน ไม่ว่าจะเป็นมลทินชนิดใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 6, 'บุคคลผู้แตะต้องสิ่งเหล่านี้ ต้องมลทินไปจนถึงเวลาเย็น และจะรับประทานสิ่งบริสุทธิ์ไม่ได้ นอกจากเขาจะอาบน้ําชําระตัวเสียก่อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 7, 'เมื่อดวงอาทิตย์ตกเขาก็สะอาด ภายหลังเขาจึงรับประทานสิ่งบริสุทธิ์ได้เพราะสิ่งเหล่านั้นเป็นอาหารของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 8, 'สิ่งใดที่ตายเอง หรือถูกสัตว์กัดตาย อย่ารับประทาน เขาจะเป็นมลทินด้วยสิ่งเหล่านี้ เราคือพระเยโฮวาห์’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 9, 'เพราะฉะนั้นเขาทั้งหลายต้องรักษากฎของเรา เกลือกว่าเขาจะต้องรับโทษบาปเพราะสิ่งนั้นและจะต้องตาย เมื่อเขากระทําสิ่งนั้นให้เป็นมลทิน เราคือพระเยโฮวาห์ผู้ที่ตั้งเขาไว้ให้บริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 10, 'อย่าให้คนภายนอกรับประทานสิ่งบริสุทธิ์ ผู้ที่มาอาศัยอยู่กับปุโรหิตหรือลูกจ้างอย่าให้รับประทานสิ่งบริสุทธิ์นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 11, 'แต่ถ้าปุโรหิตคนหนึ่งซื้อทาสมาด้วยเงินเป็นทรัพย์ของตน ทาสนั้นจะรับประทานก็ได้ และผู้ที่เกิดในครัวเรือนของปุโรหิตรับประทานอาหารนั้นได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 12, 'ถ้าบุตรสาวของปุโรหิตไปแต่งงานกับคนภายนอก เธอก็รับประทานของถวายแห่งสิ่งบริสุทธิ์นั้นไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 13, 'แต่ถ้าบุตรสาวของปุโรหิตเป็นหญิงม่ายหรือแม่ร้างและไม่มีบุตร และกลับมาอยู่ที่เรือนของบิดาอย่างเมื่อเธอยังสาว เธอรับประทานอาหารของบิดาได้ แต่คนภายนอกรับประทานไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 14, 'ถ้าคนใดรับประทานสิ่งบริสุทธิ์โดยมิได้เจตนา เขาจะต้องเพิ่มค่าของนั้นหนึ่งในห้า และมอบแก่ปุโรหิตพร้อมกับสิ่งบริสุทธิ์นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 15, 'อย่าให้ปุโรหิตกระทําสิ่งบริสุทธิ์ของคนอิสราเอลที่นํามาถวายแด่พระเยโฮวาห์ให้เป็นมลทิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 16, 'ซึ่งจะกระทําให้เขาได้รับโทษความชั่วช้าด้วยมีการละเมิดที่รับประทานสิ่งบริสุทธิ์ เพราะเราคือพระเยโฮวาห์ผู้ตั้งเขาไว้ให้บริสุทธิ์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 17, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 18, '“จงกล่าวแก่อาโรนและลูกหลานของอาโรน และแก่คนอิสราเอลทั้งหมดว่า เมื่อคนในวงศ์วานอิสราเอลหรือคนต่างด้าวในอิสราเอลผู้ใดถวายเครื่องบูชาสําหรับบรรดาเครื่องปฏิญาณ และบรรดาเครื่องบูชาด้วยใจสมัครของตน ซึ่งถวายบูชาแด่พระเยโฮวาห์เป็นเครื่องเผาบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 19, 'เจ้าจงถวายด้วยความเต็มใจ คือสัตว์ตัวผู้ปราศจากตําหนิ คือโค หรือแกะ หรือแพะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 20, 'เจ้าอย่าถวายสิ่งใดๆที่มีตําหนิ เพราะจะไม่เป็นที่โปรดปราน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 21, 'เมื่อคนใดถวายเครื่องสันติบูชาแด่พระเยโฮวาห์ เพื่อทําตามคําปฏิญาณหรือถวายด้วยใจสมัคร เป็นสัตว์ที่ได้มาจากฝูงวัว หรือฝูงแพะแกะ สัตว์นั้นต้องไม่มีตําหนิจึงจะเป็นที่โปรดปราน อย่าให้สัตว์นั้นมีที่ติเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 22, 'สัตว์ที่ตาบอดหรือพิการ หรือมีแผล หรือมีสิ่งไหลออกหรือเป็นขี้กลากหรือเป็นหิด เจ้าอย่านํามาถวายแด่พระเยโฮวาห์ หรือนํามาเป็นเครื่องบูชาด้วยไฟที่บนแท่นถวายแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 23, 'วัวหรือลูกแกะที่มีอวัยวะยาวเกินไปหรือสั้นเกินไปสักส่วนหนึ่ง ท่านจะนํามาถวายเป็นเครื่องบูชาด้วยใจสมัครก็ได้ แต่ถ้าเป็นเครื่องบูชาปฏิญาณก็ไม่เป็นที่โปรดปราน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 24, 'สัตว์ตัวใดที่ช้ําหรือถูกทุบหรือฉีกขาดหรือมีรอยตัด เจ้าอย่านํามาถวายแด่พระเยโฮวาห์ให้เป็นเครื่องบูชาในแผ่นดินของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 25, 'เจ้าอย่านําสัตว์ซึ่งได้มาจากคนต่างด้าวถวายเป็นพระกระยาหารแห่งพระเจ้าของเจ้า เพราะสัตว์นั้นมีตําหนิด้วยถูกทําให้พิการจึงไม่เป็นที่โปรดปราน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 26, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 27, '“เมื่อวัวหรือแกะหรือแพะเกิดมา ให้อยู่กับแม่เจ็ดวัน ตั้งแต่วันที่แปดเป็นต้นไปจะใช้เป็นเครื่องบูชาด้วยไฟถวายแด่พระเยโฮวาห์ก็เป็นที่โปรดปราน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 28, 'แม้ว่าแม่สัตว์นั้นจะเป็นวัวหรือแกะก็ดี เจ้าอย่าฆ่ามันพร้อมกับลูกของมันในวันเดียวกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 29, 'เมื่อเจ้าถวายเครื่องสัตวบูชาเป็นเครื่องบูชาโมทนาพระคุณแด่พระเยโฮวาห์ เจ้าจงถวายเครื่องสัตวบูชานั้นด้วยความเต็มใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 30, 'จงรับประทานเครื่องบูชานั้นในวันถวายเครื่องบูชา อย่าเหลือไว้จนรุ่งเช้าเลย เราคือพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 31, 'เพราะฉะนั้นเจ้าจงรักษาบัญญัติของเราและกระทําตาม เราคือพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 32, 'เจ้าอย่าลบหลู่นามบริสุทธิ์ของเรา แต่ให้เราเป็นผู้บริสุทธิ์ในหมู่คนอิสราเอล เราคือพระเยโฮวาห์ผู้ตั้งเจ้าไว้ให้บริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 33, 'ผู้นําเจ้าออกจากแผ่นดินอียิปต์เพื่อเป็นพระเจ้าของเจ้า เราคือพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 1, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 2, '“จงกล่าวแก่คนอิสราเอลว่า เทศกาลเลี้ยงตามกําหนดแด่พระเยโฮวาห์ ซึ่งเจ้าจะต้องประกาศว่าเป็นการประชุมบริสุทธิ์ คือเทศกาลเลี้ยงตามกําหนดของเรานั้นมีดังนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 3, 'จงทําการงานในหกวัน แต่วันที่เจ็ดนั้นเป็นสะบาโตแห่งการหยุดพักสงบ เป็นวันประชุมบริสุทธิ์ เจ้าอย่าทําการงานใดๆ เป็นสะบาโตแด่พระเยโฮวาห์ตามที่อยู่ทั่วไปของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 4, 'ต่อไปนี้เป็นเทศกาลเลี้ยงตามกําหนดแด่พระเยโฮวาห์ เป็นการประชุมบริสุทธิ์ ซึ่งเจ้าจะต้องประกาศตามเวลากําหนดให้เขาทราบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 5, 'ในเวลาเย็นวันที่สิบสี่เดือนที่หนึ่งเป็นวันเทศกาลปัสกาของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 6, 'และในวันที่สิบห้าเดือนเดียวกัน เป็นเทศกาลกินขนมปังไร้เชื้อถวายแด่พระเยโฮวาห์ ให้เจ้ารับประทานขนมปังไร้เชื้อเจ็ดวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 7, 'ในวันต้นเจ้าจงมีการประชุมบริสุทธิ์ เจ้าอย่าทํางานหนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 8, 'แต่เจ้าจงถวายเครื่องบูชาด้วยไฟแด่พระเยโฮวาห์ให้ครบเจ็ดวัน ในวันที่เจ็ดเป็นวันประชุมบริสุทธิ์ เจ้าอย่าทํางานหนัก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 9, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 10, '“จงกล่าวแก่คนอิสราเอลว่า เมื่อเจ้ามาถึงแผ่นดินซึ่งเราให้เจ้า และเกี่ยวพืชผลของแผ่นดินนั้น เจ้าจงเอาฟ่อนข้าวที่เกี่ยวในรุ่นแรกนําไปให้ปุโรหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 11, 'และปุโรหิตจะนําฟ่อนข้าวนั้น แกว่งไปแกว่งมาถวายต่อพระพักตร์พระเยโฮวาห์ เพื่อเจ้าจะเป็นที่โปรดปราน รุ่งขึ้นหลังวันสะบาโตปุโรหิตจะแกว่งถวาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 12, 'ในวันที่เจ้าแกว่งถวายฟ่อนข้าว เจ้าจงถวายลูกแกะผู้อายุหนึ่งขวบไม่มีตําหนิเป็นเครื่องเผาบูชาถวายแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 13, 'และเครื่องธัญญบูชาที่คู่กันนั้น คือยอดแป้งสองในสิบเอฟาห์คลุกกับน้ํามัน เผาด้วยไฟถวายแด่พระเยโฮวาห์เป็นกลิ่นพอพระทัย และเครื่องดื่มบูชาที่คู่กันคือน้ําองุ่นหนึ่งในสี่ฮิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 14, 'เจ้าอย่ารับประทานขนมปังหรือข้าวคั่วข้าวสดจนกว่าจะถึงวันเดียวกันนี้ คือกว่าเจ้าจะนําเครื่องบูชาถวายแด่พระเจ้าของเจ้า ทั้งนี้เป็นกฎเกณฑ์ถาวรตลอดชั่วอายุของเจ้าในที่อยู่ของเจ้าทั่วไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 15, 'เจ้าทั้งหลายจงนับตั้งแต่วันรุ่งขึ้นหลังวันสะบาโต จากวันที่เจ้าทั้งหลายได้นําฟ่อนข้าวแกว่งถวายครบเจ็ดวันสะบาโต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 16, 'นับไปให้ได้ห้าสิบวัน จนถึงวันถัดวันสะบาโตที่เจ็ดแล้ว เจ้าจงถวายธัญญบูชาใหม่แด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 17, 'จงนําขนมปังสองก้อนทําด้วยแป้งสองในสิบเอฟาห์จากที่อาศัยของเจ้ามาแกว่งถวาย ให้ทําด้วยยอดแป้งใส่เชื้อปิ้ง เป็นผลรุ่นแรกถวายแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 18, 'พร้อมกับขนมปังนั้นเจ้าจงนําลูกแกะเจ็ดตัวอายุหนึ่งขวบปราศจากตําหนิ วัวหนุ่มตัวหนึ่ง แกะผู้สองตัว มาเป็นเครื่องเผาบูชาถวายแด่พระเยโฮวาห์ พร้อมกับธัญญบูชาและเครื่องดื่มบูชาอันเป็นคู่กัน ให้เป็นเครื่องบูชาด้วยไฟ เป็นกลิ่นพอพระทัยถวายแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 19, 'เจ้าจงถวายลูกแพะตัวหนึ่งเป็นเครื่องบูชาไถ่บาป และลูกแกะอายุหนึ่งขวบสองตัวเป็นเครื่องสันติบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 20, 'ให้ปุโรหิตแกว่งไปแกว่งมาถวายพร้อมกับขนมปังซึ่งเป็นผลรุ่นแรกเป็นเครื่องแกว่งถวายต่อพระพักตร์พระเยโฮวาห์ พร้อมกับลูกแกะสองตัว จะเป็นสิ่งบริสุทธิ์แด่พระเยโฮวาห์สําหรับปุโรหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 21, 'และในวันเดียวกันนั้น เจ้าจงประกาศว่าเจ้าจงมีการประชุมบริสุทธิ์แก่เจ้า เจ้าอย่าทํางานหนัก ทั้งนี้เป็นกฎเกณฑ์ถาวรทั่วไปในที่อาศัยของเจ้าตลอดชั่วอายุของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 22, 'และเมื่อเจ้าเกี่ยวข้าวในแผ่นดินของเจ้า เจ้าอย่าเกี่ยวไปที่ขอบนาให้หมด และอย่าเก็บข้าวที่เกี่ยวตก เจ้าจงทิ้งไว้ให้คนยากจน และคนต่างด้าว เราคือพระเยโฮวาห์พระเจ้าของเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 23, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 24, '“จงกล่าวแก่คนอิสราเอลว่า ในวันที่หนึ่งของเดือนที่เจ็ด เจ้าทั้งหลายจงถือเป็นวันสะบาโต เป็นวันประชุมบริสุทธิ์ประกาศเป็นที่ระลึกด้วยเสียงแตร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 25, 'เจ้าอย่าทํางานหนัก และเจ้าจงนําเครื่องบูชาด้วยไฟถวายแด่พระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 26, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 27, '“ในวันที่สิบของเดือนที่เจ็ดนี้เป็นวันทําการลบมลทิน จะเป็นวันประชุมบริสุทธิ์แก่เจ้า และเจ้าต้องถ่อมใจลง และนําเครื่องบูชาด้วยไฟถวายแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 28, 'ในวันเดียวกันนั้นเจ้าอย่าทํางานใดๆ เพราะเป็นวันทําการลบมลทิน ที่จะทําการลบมลทินของเจ้าต่อพระพักตร์พระเยโฮวาห์พระเจ้าของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 29, 'ในวันเดียวกันนั้น ผู้ใดก็ตามไม่ถ่อมใจลง ผู้นั้นจะต้องถูกตัดขาดจากท่ามกลางชนชาติของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 30, 'และในวันเดียวกันนี้ถ้าผู้ใดทํางานใดๆ เราจะทําลายผู้นั้นเสียจากท่ามกลางชนชาติของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 31, 'เจ้าอย่าทํางานสิ่งใดเลย ทั้งนี้เป็นกฎเกณฑ์ถาวรตลอดชั่วอายุของเจ้าทั่วไปในที่อาศัยของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 32, 'จะเป็นวันสะบาโตสําหรับหยุดพักสงบแก่เจ้า และเจ้าจงถ่อมใจลง เริ่มแต่เวลาเย็นในวันที่เก้าของเดือน เจ้าต้องรักษาวันสะบาโตจากเวลาเย็นถึงเวลาเย็น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 33, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 34, '“จงกล่าวแก่คนอิสราเอลว่า ในวันที่สิบห้าเดือนที่เจ็ดนี้ เป็นวันเทศกาลอยู่เพิงถวายแด่พระเยโฮวาห์สิ้นเจ็ดวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 35, 'จะมีการประชุมบริสุทธิ์ในวันแรก เจ้าอย่าทํางานหนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 36, 'ในเจ็ดวันเจ้าจงถวายบูชากระทําด้วยไฟแด่พระเยโฮวาห์ และในวันที่แปดจะเป็นวันประชุมอันบริสุทธิ์แก่เจ้า และเจ้าจงถวายเครื่องบูชากระทําด้วยไฟแด่พระเยโฮวาห์ เป็นประชุมอันศักดิ์สิทธิ์ และเจ้าทั้งหลายอย่าทํางานหนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 37, 'นี้แหละเป็นเทศกาลเลี้ยงของพระเยโฮวาห์ ซึ่งเจ้าต้องประกาศเป็นวันประชุมอันบริสุทธิ์ เพื่อให้นําถวายแด่พระเยโฮวาห์ซึ่งเครื่องบูชาด้วยไฟ เครื่องเผาบูชาและธัญญบูชา ทั้งเครื่องสัตวบูชาและเครื่องดื่มบูชาตามวันกําหนดนั้นๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 38, 'นอกเหนือวันสะบาโตแห่งพระเยโฮวาห์ และนอกเหนือของถวายของเจ้า และนอกเหนือเครื่องปฏิญาณทั้งหลายของเจ้า และนอกเหนือเครื่องบูชาด้วยใจสมัครทั้งหลายของเจ้า ซึ่งเจ้านํามาถวายแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 39, 'แล้วในวันที่สิบห้าของเดือนที่เจ็ดเมื่อเจ้าได้เก็บพืชผลที่ได้จากแผ่นดินนั้นเข้ามาแล้ว เจ้าจงมีเทศกาลเลี้ยงแห่งพระเยโฮวาห์เจ็ดวัน ในวันแรกจะเป็นวันสะบาโต และในวันที่แปดจะเป็นวันสะบาโต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 40, 'ในวันแรกเจ้าจงนํามาซึ่งผลจากต้นมะงั่ว ใบอินทผลัม กิ่งไม้ที่มีใบมาก กิ่งต้นหลิวแห่งธารน้ํา และเจ้าจงปีติยินดีอยู่เจ็ดวันต่อพระพักตร์พระเยโฮวาห์พระเจ้าของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 41, 'เจ้าจงถือเป็นเทศกาลเลี้ยงปีละเจ็ดวันถวายแด่พระเยโฮวาห์ ทั้งนี้เป็นกฎเกณฑ์ถาวรตลอดชั่วอายุของเจ้า เจ้าจงถือเทศกาลเลี้ยงนี้ในเดือนที่เจ็ด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 42, 'เจ้าจงอยู่ในเพิงเจ็ดวัน ทุกคนที่เกิดในวงศ์วานพวกอิสราเอลให้เข้าอยู่ในเพิง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 43, 'เพื่อตลอดชั่วอายุของเจ้าจะได้ทราบว่า เมื่อเราพาคนอิสราเอลออกจากแผ่นดินอียิปต์นั้นเราได้ให้เขาอยู่ในเพิง เราคือพระเยโฮวาห์พระเจ้าของเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 44, 'ดังนี้แหละโมเสสจึงได้ประกาศให้คนอิสราเอลทราบถึงเทศกาลเลี้ยงตามกําหนดของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 1, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 2, '“เจ้าจงบัญชาแก่คนอิสราเอลให้นําน้ํามันอย่างบริสุทธิ์สกัดจากมะกอกเทศเพื่อเติมประทีป เพื่อให้ตะเกียงลุกอยู่เสมอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 3, 'ภายในพลับพลาแห่งชุมนุมข้างนอกม่านหีบพระโอวาทนั้น ให้อาโรนจัดประทีปให้เป็นระเบียบตั้งแต่เวลาเย็นจนเวลาเช้าเสมอต่อพระพักตร์พระเยโฮวาห์ ทั้งนี้ให้เป็นกฎเกณฑ์ถาวรตลอดชั่วอายุของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 4, 'ให้อาโรนจัดประทีปให้เป็นระเบียบอยู่บนคันประทีปบริสุทธิ์เสมอต่อพระพักตร์พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 5, 'และเจ้าจงเอายอดแป้ง ปิ้งขนมปังสิบสองก้อน แต่ละก้อนใช้แป้งสองในสิบเอฟาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 6, 'เจ้าจงจัดขนมปังนั้นวางบนโต๊ะบริสุทธิ์ต่อพระพักตร์พระเยโฮวาห์ เป็นสองแถวๆละหกก้อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 7, 'และเจ้าจงเอาเครื่องกํายานบริสุทธิ์ใส่ไว้แต่ละแถว เพื่อจะคู่กับขนมปังเป็นส่วนที่ระลึก เป็นเครื่องบูชากระทําด้วยไฟถวายแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 8, 'ทุกๆวันสะบาโตให้อาโรนจัดไว้ให้เป็นระเบียบถวายต่อพระพักตร์พระเยโฮวาห์เสมอ ในนามของคนอิสราเอลเป็นพันธสัญญาเนืองนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 9, 'ขนมปังนี้ตกเป็นของอาโรนและบุตรชายของเขา ให้เขารับประทานได้ในที่บริสุทธิ์ เพราะเป็นส่วนบริสุทธิ์ที่สุดที่ได้จากเครื่องบูชากระทําด้วยไฟถวายแด่พระเยโฮวาห์เป็นกฎเกณฑ์เนืองนิตย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 10, 'ครั้งนั้นมีชายคนหนึ่งเป็นบุตรชายของหญิงคนอิสราเอล ซึ่งบิดาเป็นชาวอียิปต์ ออกไปท่ามกลางคนอิสราเอล และบุตรชายของหญิงอิสราเอลทะเลาะกับชายอิสราเอลคนหนึ่งในค่าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 11, 'และบุตรชายหญิงอิสราเอลคนนั้นได้เหยียดหยามพระนามของพระเยโฮวาห์และได้แช่งด่า เขาจึงนําตัวมาให้โมเสส (มารดาของเขาชื่อเชโลมิทบุตรสาวของดิบรีคนตระกูลดาน)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 12, 'เขาจึงจองจําชายคนนั้นไว้จนกว่าน้ําพระทัยของพระเยโฮวาห์จะเป็นที่กระจ่างต่อเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 13, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 14, '“จงนําผู้ที่แช่งด่านั้นออกมาจากค่าย ให้บรรดาผู้ที่ได้ยินคําแช่งด่าเอามือของตนวางไว้บนศีรษะของเขา และให้บรรดาชุมนุมชนเอาหินขว้างเขาให้ตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 15, 'และจงกล่าวแก่คนอิสราเอลว่า ผู้ใดแช่งด่าพระเจ้าของเขา ผู้นั้นจะต้องได้รับโทษบาป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 16, 'ผู้ใดที่เหยียดหยามพระนามของพระเยโฮวาห์จะต้องถูกโทษถึงตายเป็นแน่ และให้ชุมนุมชนทั้งหมดเอาหินขว้างเขา คนต่างด้าวหรือชาวเมืองก็ดี เมื่อเขาเหยียดหยามพระนามของพระเยโฮวาห์ จะต้องถูกโทษถึงตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 17, 'ผู้ที่ฆ่าคนตาย จะต้องถูกโทษถึงตายเป็นแน่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 18, 'ผู้ใดที่ฆ่าสัตว์ต้องชดใช้สิ่งนั้น สัตว์แทนสัตว์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 19, 'ถ้าผู้ใดกระทําให้เพื่อนบ้านเสียโฉม เขากระทําให้เสียโฉมอย่างไร ก็ให้กระทําแก่เขาอย่างนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 20, 'กระดูกหักแทนกระดูกหัก ตาแทนตา ฟันแทนฟัน เขากระทําให้เสียโฉมอย่างไร เขาก็ต้องถูกทําให้เสียโฉมอย่างนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 21, 'ผู้ใดที่ฆ่าสัตว์ต้องเสียค่าชดใช้ และผู้ใดที่ฆ่าคนให้ผู้นั้นถูกโทษถึงตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 22, 'เจ้าจงมีพระราชบัญญัติอย่างเดียวกันสําหรับคนต่างด้าว และสําหรับชาวเมือง เพราะเราคือพระเยโฮวาห์พระเจ้าของเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 23, 'โมเสสก็บอกแก่คนอิสราเอลให้เขาพาคนที่แช่งด่านั้นออกมาจากค่าย และเอาหินขว้างเขา คนอิสราเอลกระทําดังนี้ตามที่พระเยโฮวาห์ทรงบัญชาโมเสสไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 1, 'พระเยโฮวาห์ตรัสกับโมเสสที่ภูเขาซีนายว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 2, '“จงกล่าวแก่คนอิสราเอลว่า เมื่อเจ้าทั้งหลายเข้าแผ่นดินที่เราให้เจ้านั้น จงให้แผ่นดินนั้นถือสะบาโตแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 3, 'เจ้าจงหว่านพืชในนาของเจ้าหกปี และจงลิดแขนงสวนองุ่นของเจ้าและเก็บผลหกปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 4, 'แต่ในปีที่เจ็ดนั้นเป็นปีสะบาโตแห่งการหยุดพักผ่อนสําหรับแผ่นดิน เป็นปีสะบาโตแด่พระเยโฮวาห์ เจ้าอย่าหว่านพืชในนา หรือลิดแขนงสวนองุ่นของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 5, 'สิ่งใดที่งอกขึ้นมาเอง เจ้าอย่าเก็บเกี่ยว องุ่นอันเกิดอยู่ที่เถาอันเจ้ามิได้ตกแต่งก็อย่าเก็บ ให้เป็นปีที่แผ่นดินหยุดพักสงบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 6, 'แผ่นดินในปีสะบาโตนั้นจะยังพืชผลให้แก่เจ้าทั้งหลาย คือแก่ตัวเจ้าเอง แก่ทาสชายทาสหญิงของเจ้า แก่ลูกจ้างของเจ้า และแก่คนต่างด้าวที่อยู่กับเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 7, 'พืชผลแห่งแผ่นดินทั้งสิ้น จะเป็นอาหารของสัตว์เลี้ยงของเจ้า และของสัตว์ป่าที่อยู่ในแผ่นดินของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 8, 'เจ้าจงนับปีสะบาโตเจ็ดปีคือเจ็ดคูณเจ็ดปี เวลาปีสะบาโตเจ็ดปีจึงเป็นสี่สิบเก้าปีแก่เจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 9, 'เจ้าจงให้เป่าแตรดังสนั่นในวันที่สิบเดือนที่เจ็ด เจ้าจงให้เป่าแตรทั่วแผ่นดินในวันทําการลบมลทิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 10, 'เจ้าจงถือปีที่ห้าสิบไว้เป็นปีบริสุทธิ์ และประกาศอิสรภาพแก่บรรดาคนที่อาศัยอยู่ทั่วแผ่นดินของเจ้า ให้เป็นปีเสียงแตรแก่เจ้า ให้ทุกคนกลับไปยังภูมิลําเนาอันเป็นทรัพย์สินของตน และกลับไปสู่ครอบครัวของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 11, 'ปีที่ห้าสิบนั้นเป็นปีเสียงแตรของเจ้า ในปีนั้นเจ้าอย่าหว่านพืชหรือเกี่ยวเก็บผลที่เกิดขึ้นมาเอง หรือเก็บองุ่นจากเถาที่มิได้ตกแต่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 12, 'เพราะเป็นปีเสียงแตร จะเป็นปีบริสุทธิ์แก่เจ้า เจ้าจงรับประทานพืชผลที่งอกมาจากนาในปีนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 13, 'ในปีเสียงแตรนี้ให้ทุกคนกลับไปสู่ภูมิลําเนาอันเป็นทรัพย์สินของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 14, 'ถ้าเจ้าขายนาให้เพื่อนบ้านก็ดี หรือซื้อจากเพื่อนบ้านก็ดี เจ้าอย่าโกงกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 15, 'ตามจํานวนปีหลังจากปีเสียงแตร เจ้าจงซื้อนาจากเพื่อนบ้านของเจ้าและให้เขาขายแก่เจ้าตามจํานวนปีที่ปลูกพืชได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 16, 'ถ้ามากปีก็ต้องเพิ่มราคาสูงขึ้น ถ้าน้อยปีเจ้าจงลดราคาให้ต่ําลง เพราะที่เขาขายนั้นเขาก็ขายตามจํานวนปีที่ปลูกพืช');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 17, 'เจ้าอย่าโกงกัน แต่เจ้าจงยําเกรงพระเจ้าของเจ้า เพราะเราคือพระเยโฮวาห์พระเจ้าของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 18, 'เพราะฉะนั้นเจ้าจงกระทําตามกฎเกณฑ์ของเรา และรักษาคําตัดสินของเราและปฏิบัติตาม ดังนั้นเจ้าจะอาศัยอยู่ในแผ่นดินนั้นอย่างปลอดภัยได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 19, 'แผ่นดินจะอํานวยผลให้เจ้าได้รับประทานอย่างอิ่มหนํา และอาศัยอยู่อย่างปลอดภัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 20, 'ถ้าเจ้าจะพูดว่า ‘ดูเถิด ถ้าเราทั้งหลายหว่านหรือเกี่ยวพืชผลของเราไม่ได้ ในปีที่เจ็ดเราจะเอาอะไรรับประทาน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 21, 'เราจะบัญชาพรของเราให้มีเหนือเจ้าในปีที่หก เพื่อจะมีพืชผลพอสําหรับสามปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 22, 'เมื่อเจ้าหว่านในปีที่แปดเจ้าจะรับประทานของเก่าของเจ้าจนปีที่เก้า เมื่อเจ้าได้พืชผลใหม่เข้ามาเจ้าก็ยังรับประทานพืชผลเก่าของเจ้าอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 23, 'เจ้าทั้งหลายจะขายที่ดินของเจ้าให้ขาดไม่ได้เพราะว่าดินนั้นเป็นของเรา เพราะเจ้าเป็นคนต่างด้าวและเป็นคนอาศัยอยู่กับเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 24, 'ทั่วไปในแผ่นดินที่เจ้ายึดถืออยู่ เจ้าจงให้มีการไถ่ถอนที่ดินคืน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 25, 'ถ้าพี่น้องของเจ้ายากจนลงและขายที่ดินส่วนหนึ่งของเขา หากว่ามีผู้ใดในพี่น้องของเขามาไถ่ถอนที่นั้น ก็จงให้เขาไถ่ถอนที่ซึ่งพี่น้องของเขาขายไปนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 26, 'ถ้าชายคนนั้นไม่มีญาติมาไถ่ถอนให้ และตัวเขาสามารถจะไถ่ถอนเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 27, 'ก็จงให้คนที่จะไถ่นับปีทั้งหลายที่เขาขายไป และเงินที่เหลือนั้นจงคืนให้แก่คนที่เขาขายให้และคนไถ่ก็เข้าอยู่ในที่ดินของเขาได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 28, 'แต่ถ้าเขาไม่สามารถที่จะไถ่คืนมา ที่ดินที่เขาได้ขายไปจะคงอยู่ในมือของผู้ซื้อจนถึงปีเสียงแตร และในปีเสียงแตรนี้ ที่ดินจะออกไปและเขาจะได้ที่ดินของเขากลับคืน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 29, 'ถ้าผู้ใดขายเรือนซึ่งอยู่ในเมืองที่มีกําแพง เมื่อขายไปแล้วให้เขาไถ่ถอนคืนได้ภายในหนึ่งปีแรก ให้เขามีสิทธิ์ในการไถ่ถอนคืนได้หนึ่งปีเต็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 30, 'ถ้าในเวลาหนึ่งปีเต็มเขาไม่ทําการไถ่ถอน ก็ให้จัดการเสียให้เป็นการแน่นอนว่า ผู้ที่ซื้อไปมีสิทธิ์เหนือเรือนที่อยู่ในเมืองที่มีกําแพงนั้นสิทธิ์ขาดแล้ว ตลอดชั่วอายุของเขา ในปีเสียงแตรเขาก็ไม่ต้องคืนให้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 31, 'แต่เรือนในชนบทที่ไม่มีกําแพงล้อมให้นับเข้าเป็นพวกเดียวกับท้องนาในประเทศนั้น คือไถ่ถอนคืนได้ และจะต้องคืนกลับให้เจ้าของเดิมในปีเสียงแตร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 32, 'แต่อย่างไรก็ตามเมืองของคนเลวี หรือบ้านในเมืองที่เขาถือกรรมสิทธิ์ คนเลวีจะไถ่ถอนคืนได้ทุกเวลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 33, 'ถ้าผู้ใดซื้อของจากคนเลวี เรือนซึ่งถูกขายไปนั้นกับเมืองที่เขาถือกรรมสิทธิ์ต้องกลับคืนในปีเสียงแตร เพราะเรือนทั้งหลายในหัวเมืองของพวกเลวีก็เป็นกรรมสิทธิ์ของเขาท่ามกลางพวกอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 34, 'แต่ทุ่งนาที่ล้อมรอบหัวเมืองทั้งหลายของพวกเขานั้นจะขายไม่ได้ เพราะว่าเป็นกรรมสิทธิ์ถาวรของเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 35, 'ถ้าพี่น้องของเจ้ายากจนลงและเลี้ยงตัวเองอยู่กับเจ้าไม่ได้ เจ้าจะต้องชูกําลังเขา ถึงเขาเป็นคนต่างด้าวหรือคนอาศัย เพื่อเขาจะอาศัยอยู่กับเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 36, 'อย่าเอาดอกเบี้ยหรือเงินเพิ่มอะไรจากเขา แต่จงยําเกรงพระเจ้า เพื่อว่าพี่น้องของเจ้าจะอยู่ใกล้ชิดกับเจ้าได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 37, 'เจ้าอย่าให้เขายืมเงินด้วยคิดดอกเบี้ย หรืออย่าให้อาหารเพื่อเอากําไรจากเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 38, 'เราคือพระเยโฮวาห์พระเจ้าของเจ้า ซึ่งนําเจ้าออกจากแผ่นดินอียิปต์ เพื่อยกแผ่นดินคานาอันให้แก่เจ้า และที่จะเป็นพระเจ้าของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 39, 'ถ้าพี่น้องที่อยู่ใกล้ชิดกับเจ้ายากจนลง และขายตัวให้แก่เจ้า เจ้าอย่าให้เขาทํางานเหมือนทาส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 40, 'ให้เขาอยู่กับเจ้าอย่างลูกจ้างหรือคนที่อาศัยอยู่ด้วย ให้เขาปรนนิบัติเจ้าไปถึงปีเสียงแตร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 41, 'แล้วเขาและลูกหลานของเขาจะออกไปจากเจ้ากลับไปสู่ครอบครัวของเขา และกลับไปอยู่ในที่ดินของบิดาของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 42, 'เพราะว่าเขาทั้งหลายเป็นทาสของเราที่เราพาออกจากแผ่นดินอียิปต์ เขาจะขายตัวเป็นทาสไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 43, 'เจ้าอย่าข่มขี่เขาให้ลําบาก แต่จงยําเกรงพระเจ้าของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 44, 'ส่วนทาสชายหญิงซึ่งจะมีได้นั้น เจ้าจะซื้อทาสชายหญิงจากท่ามกลางบรรดาประชาชาติที่อยู่ข้างเคียงเจ้าก็ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 45, 'ยิ่งกว่านั้นเจ้าจะซื้อจากคนต่างด้าวที่อาศัยอยู่ในหมู่พวกเจ้าทั้งครอบครัวของเขาซึ่งเป็นคนเกิดในแผ่นดินของเจ้า และเขาจะตกเป็นทรัพย์สินของเจ้าก็ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 46, 'เจ้าจะทําพินัยกรรมยกเขาให้แก่ลูกหลานของเจ้า ให้เป็นมรดกแก่เขาเป็นกรรมสิทธิ์ เจ้าใช้เขาได้อย่างทาสเป็นนิตย์ก็ได้ แต่เจ้าทั้งหลายอย่าปกครองพี่น้องคนอิสราเอลด้วยความรุนแรง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 47, 'ถ้าคนต่างด้าวหรือคนที่อาศัยอยู่กับเจ้ามั่งมีขึ้น และพี่น้องของเจ้าที่อยู่ใกล้ชิดกับเขายากจนลง และขายตัวให้แก่คนต่างด้าวหรือผู้ที่อาศัยอยู่กับเจ้านั้น หรือขายให้แก่ญาติคนหนึ่งคนใดของคนต่างด้าวนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 48, 'เมื่อเขาขายตัวแล้วก็ให้มีการไถ่ถอน คือพี่น้องคนหนึ่งคนใดของเขาทําการไถ่ถอนเขาได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 49, 'หรือลุงหรือลูกพี่ลูกน้องจะทําการไถ่ถอนเขาก็ได้ หรือญาติสนิทของครอบครัวของเขาจะไถ่ถอนเขาก็ได้ หรือถ้าเขามีความสามารถ เขาจะไถ่ถอนตัวเองก็ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 50, 'จงให้ผู้ที่ขายตัวนับปีทั้งหลายที่ขายตัวกับผู้ที่ซื้อตัวเขาไป ว่าเขาได้ขายตัวกี่ปีจนถึงปีเสียงแตร ค่าตัวของเขาเป็นค่าตามจํานวนปีเหล่านั้น เวลาที่เขาอยู่กับเจ้าของตัวเขานั้นคิดตามเวลาของลูกจ้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 51, 'ถ้ามีเวลาอีกหลายปี เขาต้องชําระเงินคืนเท่ากับเงินที่ถูกซื้อมา นับเป็นค่าไถ่ถอนตัวเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 52, 'ถ้ายังเหลือน้อยปีจะถึงปีเสียงแตร ก็ให้ผู้ขายตัวคิดกับผู้ซื้อตัวไว้เป็นราคาค่าไถ่ของเขานั้น และตามจํานวนปีเหล่านั้น เขาจะคืนเงินให้กับผู้ซื้อตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 53, 'ผู้ขายตัวนั้นจะต้องอยู่กับผู้ซื้อตัวดังลูกจ้างที่จ้างเป็นปี อย่าให้นายปกครองเขาอย่างกดขี่ในสายตาของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 54, 'ถ้าเขาไม่ไถ่ถอนตามที่กล่าวมานี้ก็ให้ปล่อยเขาในปีเสียงแตร ทั้งเขาพร้อมกับลูกของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 55, 'สําหรับเรา คนอิสราเอลเป็นทาสของเรา เขาเป็นทาสของเราที่เราพาออกจากแผ่นดินอียิปต์ เราคือพระเยโฮวาห์พระเจ้าของเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 1, '“เจ้าทั้งหลายอย่ากระทํารูปเคารพหรือรูปแกะสลักสําหรับตัว หรือตั้งเสาศักดิ์สิทธิ์ และเจ้าทั้งหลายอย่าตั้งสิ่งใดๆที่เป็นรูปสัณฐานสิ่งหนึ่งสิ่งใดด้วยศิลาไว้ในแผ่นดินของเจ้า เพื่อแก่การกราบไหว้ เพราะเราคือพระเยโฮวาห์พระเจ้าของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 2, 'เจ้าจงถือรักษาสะบาโตทั้งหลายของเรา และแสดงความเคารพต่อสถานบริสุทธิ์ของเรา เราคือพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 3, 'ถ้าเจ้าทั้งหลายดําเนินตามกฎเกณฑ์ของเราและรักษาบัญญัติของเราและกระทําตาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 4, 'เราจะประทานฝนตามฤดูแก่เจ้า และแผ่นดินจะเกิดพืชผลและต้นไม้ในทุ่งจะบังเกิดผล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 5, 'และเวลานวดข้าวจะเนิ่นนานถึงฤดูเก็บผลองุ่น และฤดูเก็บผลองุ่นจะเนิ่นนานไปถึงฤดูหว่าน และเจ้าจะรับประทานอาหารอย่างอิ่มหนํา และอยู่ในแผ่นดินของเจ้าอย่างปลอดภัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 6, 'เราจะให้มีความสงบสุขในแผ่นดิน เจ้าทั้งหลายจะนอนลง และไม่มีผู้ใดที่จะทําให้เจ้ากลัว เราจะกําจัดสัตว์ร้ายจากแผ่นดินและดาบจะไม่ผ่านแผ่นดินของเจ้าเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 7, 'เจ้าจะขับไล่ศัตรูของเจ้า และเขาทั้งหลายจะล้มลงต่อหน้าเจ้าด้วยดาบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 8, 'พวกเจ้าห้าคนจะขับไล่ศัตรูร้อยคนและพวกเจ้าร้อยคนจะขับไล่ศัตรูหมื่นคนให้กระจัดกระจายไป และศัตรูของเจ้าจะล้มลงด้วยดาบต่อหน้าเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 9, 'เพราะเราจะคิดถึงเจ้า จะกระทําให้เจ้ามีลูกดกและทวีมากขึ้น และตั้งพันธสัญญาของเราไว้กับเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 10, 'เจ้าจะได้รับประทานของที่สะสมไว้นาน และเจ้าจะต้องเอาของเก่าออกไปเพราะเหตุของใหม่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 11, 'และเราจะตั้งพลับพลาของเราไว้ท่ามกลางเจ้าทั้งหลาย และจิตใจของเราจะไม่เกลียดเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 12, 'เราจะดําเนินในหมู่พวกเจ้า และจะเป็นพระเจ้าของเจ้า และเจ้าจะเป็นพลไพร่ของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 13, 'เราคือพระเยโฮวาห์พระเจ้าของเจ้า ผู้นําเจ้าออกจากแผ่นดินอียิปต์ เพื่อเจ้าจะมิได้เป็นทาสของเขา เราได้หักคานแอกของเจ้าออกเสีย เพื่อให้เจ้ายืนตัวตรงได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 14, 'แต่ถ้าเจ้ามิได้เชื่อฟังเรา และจะไม่กระทําตามบัญญัติทั้งหมดเหล่านี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 15, 'ถ้าเจ้าปฏิเสธกฎเกณฑ์ของเรา และใจของเจ้าเกลียดชังต่อคําตัดสินของเรา เจ้าจึงไม่กระทําตามบัญญัติทั้งสิ้นของเรา แต่ทําลายพันธสัญญาของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 16, 'เราก็จะกระทําดังนี้แก่เจ้า คือเราจะตั้งความหวาดกลัวต่อหน้าเจ้า ความผ่ายผอม และความเจ็บไข้ ซึ่งทําให้นัยน์ตาทรุดโทรม และกระทําให้จิตใจเศร้าหมอง เจ้าทั้งหลายจะหว่านพืชไว้เสียเปล่า เพราะศัตรูของเจ้าจะมากิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 17, 'เราจะตั้งหน้าของเราต่อสู้เจ้า เจ้าจะล้มตายต่อหน้าศัตรูของเจ้าทั้งหลาย คนที่เกลียดชังเจ้าจะปกครองอยู่เหนือเจ้า เจ้าจะหลบหนีไปทั้งที่ไม่มีใครไล่ติดตาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 18, 'ถ้าเจ้าทั้งหลายยังไม่เชื่อฟังเราเพราะสิ่งทั้งปวงเหล่านี้ เราจึงจะลงโทษเจ้าทั้งหลายให้ทวีขึ้นอีกเจ็ดเท่าเพราะการบาปของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 19, 'เราจะทําลายความเห่อเหิมในกําลังอํานาจของเจ้า เราจะกระทําให้ฟ้าสวรรค์ของเจ้าเหมือนเหล็ก และพื้นดินของเจ้าเหมือนทองเหลือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 20, 'เจ้าทั้งหลายจะเปลืองกําลังเสียเปล่าๆ เพราะว่าแผ่นดินของเจ้าจะไม่มีพืชผล และต้นไม้ในแผ่นดินก็จะไม่บังเกิดผล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 21, 'ถ้าเจ้ายังดําเนินขัดแย้งเราอยู่และไม่เชื่อฟังเรา เราจะนําภัยพิบัติให้ทวีอีกเจ็ดเท่ามายังเจ้าตามการบาปทั้งหลายของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 22, 'เราจะปล่อยสัตว์ป่าเข้ามาท่ามกลางพวกเจ้าด้วย มันจะแย่งชิงลูกหลานของเจ้า และทําลายสัตว์ใช้งานของเจ้า และทําให้เจ้าเหลือน้อย และถนนหลวงของเจ้าก็จะร้างเปล่าไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 23, 'และถ้าด้วยสิ่งเหล่านี้เจ้ายังไม่หันมาหาเรา และยังดําเนินการขัดแย้งเราอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 24, 'แล้วเราจะดําเนินการขัดแย้งเจ้าทั้งหลายด้วย และจะลงโทษแก่เจ้าให้ทวีอีกเจ็ดเท่าเพราะการบาปทั้งหลายของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 25, 'เราจะนําดาบมาเหนือเจ้า ซึ่งลงโทษเจ้าตามพันธสัญญา ถ้าเจ้าเข้ามารวมกันอยู่ในเมือง เราจะนําโรคร้ายมาในหมู่พวกเจ้า และเจ้าจะตกอยู่ในมือของศัตรู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 26, 'เมื่อเราทําลายเสบียงอาหารของเจ้า ผู้หญิงสิบคนจะปิ้งขนมของเจ้าด้วยเตาอบอันเดียว แล้วเอาขนมมาชั่งให้เจ้า เจ้าจะรับประทานแต่จะไม่อิ่ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 27, 'แล้วถ้าเป็นอย่างนี้แล้ว เจ้ายังไม่เชื่อฟังเรา แต่ดําเนินการขัดแย้งเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 28, 'เราจะดําเนินการขัดแย้งเจ้าอย่างรุนแรง และเราเองจะลงโทษแก่เจ้าให้ทวีอีกเจ็ดเท่าเพราะการบาปทั้งหลายของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 29, 'เจ้าจะกินเนื้อบุตรชายของเจ้า และเจ้าจะกินเนื้อบุตรสาวของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 30, 'เราจะทําลายปูชนียสถานสูงทั้งหลายของเจ้า และตัดทําลายรูปเคารพทั้งหลายของเจ้า และโยนศพของเจ้าลงเหนือซากรูปเคารพของเจ้า และจิตใจของเราจะเกลียดชังเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 31, 'เราจะให้เมืองของเจ้าถูกทิ้งไว้เสียเปล่า และจะกระทําให้สถานบริสุทธิ์ของเจ้ารกร้างไป และเราจะไม่ดมกลิ่นอันหอมหวานของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 32, 'และเราจะนําแผ่นดินนั้นไปสู่การรกร้างและศัตรูของเจ้าที่อาศัยอยู่ในนั้นจะตกตะลึงกับแผ่นดินนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 33, 'และเราจะให้พวกเจ้ากระจัดกระจายไปอยู่ท่ามกลางประชาชาติ และเราจะชักดาบออกมาไล่ตามเจ้า และแผ่นดินของเจ้าจะรกร้าง และเมืองของเจ้าจะถูกทิ้งเสียเปล่าๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 34, 'แผ่นดินจะชื่นชมกับสะบาโตเหล่านั้นของมันตราบเท่าที่แผ่นดินนั้นยังว่างเปล่าอยู่ และเจ้าต้องไปอยู่ในแผ่นดินของศัตรู ซึ่งขณะนั้นแผ่นดินก็จะได้หยุดพัก และชื่นชมกับสะบาโตเหล่านั้นของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 35, 'ตราบเท่าที่แผ่นดินยังว่างเปล่าอยู่ มันก็จะได้หยุดพัก เพราะมิได้หยุดพักในสะบาโตของพวกเจ้าขณะเมื่อเจ้าอาศัยอยู่ในแผ่นดินนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 36, 'ส่วนพวกเจ้าทั้งหลายที่ยังเหลืออยู่เราจะให้เขามีใจอ่อนแอในแผ่นดินของศัตรู จนเสียงใบไม้ไหวจะไล่ตามเขา และเขาจะหนีเหมือนคนหนีจากดาบ และเขาจะล้มลงทั้งที่ไม่มีคนไล่ติดตาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 37, 'และเขาทั้งหลายจะล้มลงทับกันและกัน เหมือนคนหนีดาบทั้งที่ไม่มีคนตามมา และเจ้าจะไม่มีกําลังต่อต้านศัตรูของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 38, 'เจ้าทั้งหลายจะพินาศท่ามกลางบรรดาประชาชาติและแผ่นดินของศัตรูของเจ้าจะกินเจ้าเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 39, 'ส่วนเจ้าทั้งหลายที่เหลืออยู่จะทรุดโทรมไปในแผ่นดินศัตรูของเจ้านั้นเพราะความชั่วช้าของตน และเพราะความชั่วช้าของบรรพบุรุษของตน เขาจะต้องทรุดโทรมไปอย่างบรรพบุรุษด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 40, 'แต่ถ้าเขาทั้งหลายสารภาพความชั่วช้าของเขา และความชั่วช้าของบรรพบุรุษ ซึ่งเขาทั้งหลายกระทําการละเมิดต่อเรา ด้วยการละเมิดของเขานั้น และที่ได้ดําเนินการขัดแย้งเราด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 41, 'และเราจึงดําเนินการขัดแย้งเขาทั้งหลายด้วย และได้นําเขาเข้าแผ่นดินแห่งศัตรูของเขา ถ้าเมื่อนั้นจิตใจอันมิได้เข้าสุหนัตของเขาทั้งหลายถ่อมลงแล้ว และเขายอมรับโทษเพราะความชั่วช้าของเขาแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 42, 'เราจึงจะระลึกถึงพันธสัญญาของเราซึ่งมีต่อยาโคบ และพันธสัญญาของเราซึ่งมีต่ออิสอัค และพันธสัญญาของเราซึ่งมีต่ออับราฮัม และเราจะระลึกถึงแผ่นดินนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 43, 'แต่แผ่นดินจะต้องถูกละไว้จากเขาและจะได้ชื่นชมกับสะบาโตเหล่านั้นของมันขณะที่มันยังว่างเปล่าอยู่โดยไม่มีพวกเขาทั้งหลาย เขาทั้งหลายจะยอมรับการลงโทษในความชั่วช้าของเขา เพราะเขาได้รังเกียจคําตัดสินของเรา และเพราะจิตใจของเขาเกลียดชังกฎเกณฑ์ของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 44, 'ถึงเพียงนั้นก็ดี เมื่อเขาทั้งหลายอยู่ในแผ่นดินศัตรูของเขา เราจะไม่ละทิ้งเขา เราจะไม่เกลียดชังเขาถึงกับจะทําลายเขาเสียให้หมดทีเดียว และทําลายพันธสัญญาซึ่งมีกับเขาเสีย เพราะเราคือพระเยโฮวาห์พระเจ้าของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 45, 'เพราะเห็นแก่เขาเราจะรําลึกถึงพันธสัญญาซึ่งมีต่อบรรพบุรุษของเขา ผู้ซึ่งเราได้พาเขาออกมาจากแผ่นดินอียิปต์ท่ามกลางสายตาของบรรดาประชาชาติ เพื่อเราจะได้เป็นพระเจ้าของเขา เราคือพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 46, 'สิ่งเหล่านี้เป็นกฎเกณฑ์และคําตัดสิน และพระราชบัญญัติ ซึ่งพระเยโฮวาห์ทรงกระทําไว้ระหว่างพระองค์กับชนชาติอิสราเอลบนภูเขาซีนายโดยมือโมเสส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 1, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 2, '“จงกล่าวแก่คนอิสราเอลว่า เมื่อผู้ใดปฏิญาณเป็นพิเศษไว้ บุคคลผู้ที่ถูกปฏิญาณไว้นั้นเป็นของพระเยโฮวาห์ ตามราคาของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 3, 'ให้เจ้ากําหนดราคาดังนี้ ผู้ชายอายุตั้งแต่ยี่สิบถึงหกสิบปีจะเป็นค่าเงินห้าสิบเชเขลตามเชเขลของสถานบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 4, 'ถ้าผู้นั้นเป็นผู้หญิง ให้เจ้ากําหนดราคาเป็นค่าเงินสามสิบเชเขล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 5, 'ถ้าผู้นั้นอายุห้าขวบถึงยี่สิบปี ให้เจ้ากําหนดราคาผู้ชายเป็นค่าเงินยี่สิบเชเขล และผู้หญิงสิบเชเขล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 6, 'ถ้าผู้นั้นอายุหนึ่งเดือนถึงห้าขวบ ให้เจ้ากําหนดราคาผู้ชายเป็นค่าเงินห้าเชเขล ให้เจ้ากําหนดราคาผู้หญิงเป็นเงินสามเชเขล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 7, 'ถ้าเป็นบุคคลอายุตั้งแต่หกสิบปีขึ้นไป ให้เจ้ากําหนดราคาผู้ชายเป็นค่าเงินสิบห้าเชเขลและผู้หญิงเป็นสิบเชเขล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 8, 'แต่ถ้าผู้นั้นเป็นคนจนมีน้อยกว่าค่าตัวก็ให้เขาไปหาปุโรหิต ให้ปุโรหิตกําหนดราคาตามกําลังของผู้ที่ปฏิญาณ ปุโรหิตจะกําหนดราคาของคนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 9, 'ถ้าเป็นสัตว์อย่างที่มนุษย์นํามาถวายพระเยโฮวาห์ สิ่งใดๆที่มนุษย์ถวายแด่พระเยโฮวาห์ถือว่าเป็นของบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 10, 'อย่าให้เขานําอะไรมาแทนหรือเปลี่ยน เอาดีมาเปลี่ยนไม่ดี หรือเอาไม่ดีมาเปลี่ยนดี ถ้าเขาทําการเปลี่ยนสัตว์ ทั้งตัวที่นํามาเปลี่ยนและตัวที่ถูกเปลี่ยนจะต้องบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 11, 'ถ้าเป็นสัตว์มลทินซึ่งไม่พึงนํามาถวายแด่พระเยโฮวาห์ ให้ผู้นั้นนําสัตว์ตัวนั้นไปหาปุโรหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 12, 'แล้วปุโรหิตจะตีค่าว่าเป็นของดีของไม่ดี ท่านผู้เป็นปุโรหิตกําหนดราคาเท่าใดก็ให้เป็นเท่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 13, 'แต่ถ้าเขาจะมาไถ่สัตว์นั้นก็ให้เขาเพิ่มอีกหนึ่งในห้าของราคาที่ตีไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 14, 'เมื่อคนใดถวายเรือนของตนไว้เป็นของบริสุทธิ์แด่พระเยโฮวาห์ ปุโรหิตต้องกําหนดราคาตามดีไม่ดี ปุโรหิตกําหนดราคาเท่าใดก็ให้เป็นเท่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 15, 'ถ้าผู้ที่ถวายเรือนไว้ประสงค์จะไถ่เรือนของเขา ก็ให้ผู้นั้นเพิ่มเงินอีกหนึ่งในห้าของราคาเรือนที่ตีไว้ แล้วเรือนนั้นจึงตกเป็นของเขาได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 16, 'ถ้าผู้ใดถวายที่ดินส่วนหนึ่งแด่พระเยโฮวาห์ซึ่งเป็นมรดกตกแก่เขา ให้เจ้ากําหนดราคาของที่ดินตามจํานวนเมล็ดพืชที่หว่านลงในดินนั้น ถ้าที่นาใช้เมล็ดข้าวบาร์เลย์หนึ่งโฮเมอร์ ให้กําหนดราคาเป็นเงินห้าสิบเชเขล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 17, 'ถ้าเขาถวายนาในปีเสียงแตร ก็ให้คงเต็มราคาที่เจ้ากําหนด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 18, 'แต่ถ้าเขาถวายที่นาภายหลังปีเสียงแตร ก็ให้ปุโรหิตคํานวณค่าเงินตามจํานวนปีที่เหลืออยู่กว่าจะถึงปีเสียงแตร ให้หักเสียจากราคาที่เจ้ากําหนด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 19, 'ถ้าผู้ที่ถวายนาประสงค์จะไถ่นานั้นก็ให้เขาเพิ่มค่าเงินอีกหนึ่งในห้าของกําหนดราคาที่ตีไว้ แล้วนานั้นจะเป็นของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 20, 'แต่ถ้าเขาไม่ประสงค์ที่จะไถ่นาหรือเขาได้ขายนานั้นให้แก่อีกคนหนึ่งแล้ว ก็อย่าให้ไถ่อีกเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 21, 'แต่นานั้นเมื่อออกไปในปีเสียงแตรก็เป็นของบริสุทธิ์แด่พระเยโฮวาห์ ดุจนาที่ตั้งถวายจึงเป็นของปุโรหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 22, 'ถ้าคนใดซื้อนามาถวายแด่พระเยโฮวาห์ ซึ่งไม่ใช่ส่วนมรดกที่ตกเป็นกรรมสิทธิ์ของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 23, 'ปุโรหิตจะคํานวณค่านานับจนถึงปีเสียงแตร ในวันนั้นเจ้าของนาต้องถวายเงินเท่ากําหนดค่านาที่ตีไว้ เป็นสิ่งบริสุทธิ์แด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 24, 'พอถึงปีเสียงแตรนานั้นต้องกลับไปตกแก่ผู้ที่ขายให้เขาซึ่งเป็นเจ้าของเดิม ตามมรดกที่ตกมาเป็นของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 25, 'การกําหนดราคาทุกอย่างจะต้องเป็นไปตามค่าเงินเชเขลของสถานบริสุทธิ์ ยี่สิบเก-ราห์เป็นหนึ่งเชเขล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 26, 'แต่ลูกสัตว์หัวปีนั้นอย่าให้ใครนํามาถวาย เพราะที่เป็นสัตว์หัวปีก็ตกเป็นของพระเยโฮวาห์แล้ว วัวก็ดี แกะก็ดี เป็นของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 27, 'ถ้าเป็นสัตว์มลทินจงให้เขาซื้อคืนตามกําหนดราคาของเจ้า โดยเพิ่มหนึ่งในห้าของกําหนดราคาที่ตีไว้ ถ้าเขาไม่ไถ่ก็ให้ขายเสียตามกําหนดราคาที่ตีไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 28, 'แต่สิ่งใดที่ถวายแด่พระเยโฮวาห์ เป็นสิ่งที่เขามีอยู่ ไม่ว่าเป็นคนหรือสัตว์ หรือที่นาอันเป็นมรดกตกแก่เขาจะขายหรือไถ่ไม่ได้เลย เพราะสิ่งที่ถวายแล้วเป็นสิ่งบริสุทธิ์ที่สุดแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 29, 'ทุกสิ่งที่ถูกถวายแล้ว คือสิ่งที่ต้องทําลายเสียจากมนุษย์ อย่าให้ไถ่ถอน แต่ต้องถูกฆ่าเสียแน่นอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 30, 'สิบชักหนึ่งทั้งสิ้นที่ได้จากแผ่นดิน เป็นพืชที่ได้จากแผ่นดินก็ดี หรือผลจากต้นไม้ก็ดี เป็นของพระเยโฮวาห์ เป็นสิ่งบริสุทธิ์แด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 31, 'ถ้าคนใดประสงค์จะไถ่สิบชักหนึ่งส่วนใดของเขา เขาต้องเพิ่มอีกหนึ่งในห้าของสิบชักหนึ่งนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 32, 'และสิบชักหนึ่งที่ได้มาจากฝูงวัว หรือฝูงแพะแกะ คือสัตว์หนึ่งในสิบตัวที่ลอดใต้ไม้เท้าของผู้เลี้ยง จะเป็นสิ่งบริสุทธิ์แด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 33, 'อย่าให้พิจารณาว่าดีหรือไม่ดี อย่าให้เขาสับเปลี่ยน ถ้าเขาสับเปลี่ยน ทั้งตัวที่นํามาเปลี่ยนกับตัวที่ถูกเปลี่ยนเป็นของบริสุทธิ์ ไถ่ไม่ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 34, 'เหล่านี้เป็นบทบัญญัติที่พระเยโฮวาห์ทรงบัญญัติไว้กับโมเสสสําหรับคนอิสราเอลบนภูเขาซีนาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 1, 'ณ วันที่หนึ่งเดือนที่สองปีที่สองตั้งแต่เขาทั้งหลายออกจากประเทศอียิปต์ พระเยโฮวาห์ตรัสกับโมเสสในพลับพลาแห่งชุมนุม ณ ถิ่นทุรกันดารซีนายว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 2, '“เจ้าจงนับชุมนุมชนอิสราเอลทั้งหมดตามครอบครัวตามเรือนบรรพบุรุษตามจํานวนรายชื่อผู้ชายเรียงตัวทุกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 3, 'ตั้งแต่อายุได้ยี่สิบปีขึ้นไปบรรดาคนที่ออกรบได้ในกองทัพพวกอิสราเอล เจ้ากับอาโรนจงจัดตั้งเขาทั้งหลายไว้เป็นกองๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 4, 'และจงมีคนอยู่ด้วยเจ้าจากทุกตระกูล ทุกคนนั้นให้เป็นหัวหน้าในเรือนบรรพบุรุษของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 5, 'และเหล่านี้คือชื่อชายทั้งปวงที่จะยืนอยู่กับเจ้าคือ เอลีซูร์บุตรชายเชเดเออร์ จากตระกูลรูเบน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 6, 'เชลูมิเอลบุตรชายซูริชัดดัย จากตระกูลสิเมโอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 7, 'นาโชนบุตรชายอัมมีนาดับ จากตระกูลยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 8, 'เนธันเอลบุตรชายศุอาร์ จากตระกูลอิสสาคาร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 9, 'เอลีอับบุตรชายเฮโลน จากตระกูลเศบูลุน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 10, 'จากลูกหลานของโยเซฟ มีเอลีชามาบุตรชายอัมมีฮูด จากตระกูลเอฟราอิม และกามาลิเอลบุตรชายเปดาซูร์ จากตระกูลมนัสเสห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 11, 'อาบีดันบุตรชายกิเดโอนี จากตระกูลเบนยามิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 12, 'อาหิเยเซอร์บุตรชายอัมมีชัดดัย จากตระกูลดาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 13, 'ปากีเอลบุตรชายโอคราน จากตระกูลอาเชอร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 14, 'เอลียาสาฟบุตรชายเดอูเอล จากตระกูลกาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 15, 'อาหิราบุตรชายเอนัน จากตระกูลนัฟทาลี”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 16, 'คนเหล่านี้เป็นคนที่ชุมนุมชนเลือกให้เป็นประมุขแห่งตระกูลของบรรพบุรุษของเขา เป็นหัวหน้าคนอิสราเอลที่นับเป็นพันๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 17, 'โมเสสและอาโรนได้นําคนเหล่านี้ที่ระบุชื่อมาแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 18, 'และในวันที่หนึ่งเดือนที่สองคนเหล่านี้ก็เรียกประชุมชนทั้งหมด เข้ามาขึ้นทะเบียนตามครอบครัวและตามเรือนบรรพบุรุษ ตามจํานวนรายชื่อเรียงตัวคนทั้งปวงที่มีอายุตั้งแต่ยี่สิบปีขึ้นไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 19, 'ตามที่พระเยโฮวาห์ตรัสสั่งโมเสสไว้ ท่านจึงนับคนที่ถิ่นทุรกันดารซีนายดังนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 20, 'คนรูเบนบุตรหัวปีของอิสราเอล โดยพงศ์พันธุ์ของเขา ตามครอบครัว ตามเรือนบรรพบุรุษ ตามจํานวนรายชื่อผู้ชายเรียงตัวทุกคน ที่มีอายุตั้งแต่ยี่สิบปีขึ้นไปที่ออกรบได้ทั้งหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 21, 'จํานวนคนในตระกูลรูเบนเป็นสี่หมื่นหกพันห้าร้อยคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 22, 'คนสิเมโอน โดยพงศ์พันธุ์ของเขา ตามครอบครัว ตามเรือนบรรพบุรุษ ทุกคนที่เขานับตามจํานวนรายชื่อผู้ชายเรียงตัวทุกคน ที่มีอายุตั้งแต่ยี่สิบปีขึ้นไปที่ออกรบได้ทั้งหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 23, 'จํานวนคนในตระกูลสิเมโอนเป็นห้าหมื่นเก้าพันสามร้อยคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 24, 'คนกาด โดยพงศ์พันธุ์ของเขา ตามครอบครัว ตามเรือนบรรพบุรุษ ตามจํานวนรายชื่อคนที่มีอายุตั้งแต่ยี่สิบปีขึ้นไปที่ออกรบได้ทั้งหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 25, 'จํานวนคนในตระกูลกาดเป็นสี่หมื่นห้าพันหกร้อยห้าสิบคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 26, 'คนยูดาห์ โดยพงศ์พันธุ์ของเขา ตามครอบครัว ตามเรือนบรรพบุรุษ ตามจํานวนรายชื่อคนที่มีอายุตั้งแต่ยี่สิบปีขึ้นไปที่ออกรบได้ทั้งหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 27, 'จํานวนคนในตระกูลยูดาห์เป็นเจ็ดหมื่นสี่พันหกร้อยคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 28, 'คนอิสสาคาร์ โดยพงศ์พันธุ์ของเขา ตามครอบครัว ตามเรือนบรรพบุรุษ ตามจํานวนรายชื่อคนที่มีอายุตั้งแต่ยี่สิบปีขึ้นไปที่ออกรบได้ทั้งหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 29, 'จํานวนคนในตระกูลอิสสาคาร์เป็นห้าหมื่นสี่พันสี่ร้อยคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 30, 'คนเศบูลุน โดยพงศ์พันธุ์ของเขา ตามครอบครัว ตามเรือนบรรพบุรุษ ตามจํานวนรายชื่อคนที่มีอายุตั้งแต่ยี่สิบปีขึ้นไปที่ออกรบได้ทั้งหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 31, 'จํานวนคนในตระกูลเศบูลุนเป็นห้าหมื่นเจ็ดพันสี่ร้อยคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 32, 'จากลูกหลานของโยเซฟ คือคนเอฟราอิม โดยพงศ์พันธุ์ของเขา ตามครอบครัว ตามเรือนบรรพบุรุษ ตามจํานวนรายชื่อคนที่มีอายุตั้งแต่ยี่สิบปีขึ้นไปที่ออกรบได้ทั้งหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 33, 'จํานวนคนตระกูลเอฟราอิมเป็นสี่หมื่นห้าร้อยคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 34, 'คนมนัสเสห์ โดยพงศ์พันธุ์ของเขา ตามครอบครัว ตามเรือนบรรพบุรุษ ตามจํานวนรายชื่อคนที่มีอายุตั้งแต่ยี่สิบปีขึ้นไปที่ออกรบได้ทั้งหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 35, 'จํานวนคนในตระกูลมนัสเสห์เป็นสามหมื่นสองพันสองร้อยคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 36, 'คนเบนยามิน โดยพงศ์พันธุ์ของเขา ตามครอบครัว ตามเรือนบรรพบุรุษ ตามจํานวนรายชื่อคนที่มีอายุตั้งแต่ยี่สิบปีขึ้นไปที่ออกรบได้ทั้งหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 37, 'จํานวนคนในตระกูลเบนยามินเป็นสามหมื่นห้าพันสี่ร้อยคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 38, 'คนดาน โดยพงศ์พันธุ์ของเขา ตามครอบครัว ตามเรือนบรรพบุรุษ ตามจํานวนรายชื่อคนที่มีอายุตั้งแต่ยี่สิบปีขึ้นไปที่ออกรบได้ทั้งหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 39, 'จํานวนคนในตระกูลดานเป็นหกหมื่นสองพันเจ็ดร้อยคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 40, 'คนอาเชอร์ โดยพงศ์พันธุ์ของเขา ตามครอบครัว ตามเรือนบรรพบุรุษ ตามจํานวนรายชื่อคนที่มีอายุตั้งแต่ยี่สิบปีขึ้นไปที่ออกรบได้ทั้งหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 41, 'จํานวนคนในตระกูลอาเชอร์เป็นสี่หมื่นหนึ่งพันห้าร้อยคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 42, 'คนนัฟทาลี โดยพงศ์พันธุ์ของเขา ตามครอบครัว ตามเรือนบรรพบุรุษ ตามจํานวนรายชื่อคนที่มีอายุตั้งแต่ยี่สิบปีขึ้นไปที่ออกรบได้ทั้งหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 43, 'จํานวนคนในตระกูลนัฟทาลีเป็นห้าหมื่นสามพันสี่ร้อยคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 44, 'จํานวนคนเหล่านี้เป็นคนที่โมเสสกับอาโรน และประมุขทั้งสิบสองคนของคนอิสราเอล ผู้แทนเรือนบรรพบุรุษของตนได้นับไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 45, 'ฉะนั้นจํานวนคนอิสราเอลทั้งหมดที่นับตามเรือนบรรพบุรุษ ตามจํานวนคนที่มีอายุตั้งแต่ยี่สิบปีขึ้นไปทุกคนในอิสราเอลซึ่งออกรบได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 46, 'จํานวนคนทั้งหมดที่นับนั้นเป็นหกแสนสามพันห้าร้อยห้าสิบคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 47, 'แต่มิได้นับคนเลวีตามตระกูลบรรพบุรุษของตนรวมด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 48, 'เพราะพระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 49, '“เฉพาะตระกูลเลวีเจ้าอย่านับและอย่าทําสํามะโนครัวไว้ในคนอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 50, 'แต่เจ้าจงตั้งคนเลวีไว้สําหรับพลับพลาพระโอวาท สําหรับบรรดาเครื่องใช้กับทุกสิ่งที่เกี่ยวข้องกับพลับพลา ให้เขาขนพลับพลาและบรรดาเครื่องใช้ กับปฏิบัติงานพลับพลานั้นและตั้งเต็นท์อยู่รอบพลับพลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 51, 'เมื่อจะยกพลับพลาไปคนเลวีจะต้องรื้อพลับพลาลง และเมื่อจะตั้งพลับพลาขึ้นก็ให้คนเลวีเป็นผู้จัดตั้ง ผู้อื่นเข้ามาใกล้พลับพลา ผู้นั้นต้องถูกโทษถึงตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 52, 'ให้คนอิสราเอลตั้งเต็นท์ตามที่ของตนแต่ละพวก และแต่ละคนตามค่ายของตน และแต่ละคนตามธงตระกูลของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 53, 'แต่ให้คนเลวีตั้งเต็นท์รอบพลับพลาพระโอวาท เพื่อมิให้พระพิโรธเกิดเหนือชุมนุมชนอิสราเอล ให้ตระกูลเลวีปฏิบัติงานพลับพลาพระโอวาท”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 54, 'คนอิสราเอลก็กระทําดังนั้น เขาทั้งหลายกระทําตามที่พระเยโฮวาห์ทรงบัญชาโมเสสไว้ทุกประการ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 1, 'พระเยโฮวาห์ตรัสกับโมเสสและอาโรนว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 2, '“ให้คนอิสราเอลตั้งค่ายอยู่ตามธงของตนทุกคน ตามธงตราเรือนบรรพบุรุษของตน ให้ตั้งเต็นท์หันหน้าเข้าหาพลับพลาแห่งชุมนุมทุกด้าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 3, 'พวกที่ตั้งค่ายด้านตะวันออกทางดวงอาทิตย์ขึ้น ให้เป็นของธงค่ายยูดาห์ตามกองของเขา นาโชนบุตรชายอัมมีนาดับจะเป็นนายกองของคนยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 4, 'พลโยธาที่นับไว้นี้มีเจ็ดหมื่นสี่พันหกร้อยคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 5, 'ให้ตระกูลอิสสาคาร์ตั้งค่ายเรียงถัดมา เนธันเอลบุตรชายศุอาร์จะเป็นนายกองของคนอิสสาคาร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 6, 'พลโยธาที่นับไว้นี้มีห้าหมื่นสี่พันสี่ร้อยคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 7, 'ให้ตระกูลเศบูลุนเรียงถัดยูดาห์ไป เอลีอับบุตรชายเฮโลนจะเป็นนายกองของคนเศบูลุน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 8, 'พลโยธาที่นับไว้นี้มีห้าหมื่นเจ็ดพันสี่ร้อยคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 9, 'จํานวนชนทั้งหมดที่นับเข้าในค่ายยูดาห์ตามกองของเขาเป็นหนึ่งแสนแปดหมื่นหกพันสี่ร้อยคน เมื่อออกเดินคนเหล่านี้จะยกไปก่อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 10, 'ให้ธงค่ายของรูเบนตั้งทางทิศใต้ตามกองของเขา เอลีซูร์บุตรชายเชเดเออร์จะเป็นนายกองของคนรูเบน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 11, 'พลโยธาที่นับไว้นี้มีสี่หมื่นหกพันห้าร้อยคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 12, 'ให้ตระกูลสิเมโอนตั้งค่ายเรียงถัดมา เชลูมิเอลบุตรชายซูริชัดดัยจะเป็นนายกองของคนสิเมโอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 13, 'พลโยธาที่นับไว้นี้มีห้าหมื่นเก้าพันสามร้อยคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 14, 'ให้ตระกูลกาดเรียงถัดรูเบนไป เอลียาสาฟบุตรชายเรอูเอลจะเป็นนายกองของคนกาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 15, 'พลโยธาที่นับไว้นี้มีสี่หมื่นห้าพันหกร้อยห้าสิบคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 16, 'จํานวนคนทั้งหมดที่นับเข้าในค่ายรูเบนตามกองของเขาเป็นหนึ่งแสนห้าหมื่นหนึ่งพันสี่ร้อยห้าสิบคน เมื่อออกเดินคนเหล่านี้จะเป็นพวกที่สอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 17, 'แล้วให้ยกพลับพลาแห่งชุมนุมเดินตามไป ให้ค่ายคนเลวีอยู่กลางกระบวนค่าย เขาตั้งค่ายอยู่อันดับใดก็ให้ออกเดินไปตามอันดับนั้น ทุกค่ายตามอันดับตามธงตระกูลของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 18, 'ให้ธงค่ายของเอฟราอิมตั้งทางทิศตะวันตกตามกองของเขา เอลีชามาบุตรชายอัมมีฮูดจะเป็นนายกองของคนเอฟราอิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 19, 'พลโยธาที่นับไว้นี้มีสี่หมื่นห้าร้อยคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 20, 'ให้คนตระกูลมนัสเสห์เรียงถัดมา กามาลิเอลบุตรชายเปดาซูร์จะเป็นนายกองของคนมนัสเสห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 21, 'พลโยธาที่นับไว้นี้มีสามหมื่นสองพันสองร้อยคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 22, 'ให้ตระกูลเบนยามินเรียงถัดเอฟราอิมไป อาบีดันบุตรชายกิเดโอนีจะเป็นนายกองของคนเบนยามิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 23, 'พลโยธาที่นับไว้นี้มีสามหมื่นห้าพันสี่ร้อยคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 24, 'จํานวนคนทั้งหมดที่นับเข้าในค่ายเอฟราอิมตามกองของเขาเป็นหนึ่งแสนแปดพันหนึ่งร้อยคน เมื่อออกเดินคนเหล่านี้จะเป็นพวกที่สาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 25, 'ให้ธงค่ายของดานตั้งทางทิศเหนือตามกองของเขา อาหิเยเซอร์บุตรชายอัมมีชัดดัยจะเป็นนายกองของคนดาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 26, 'พลโยธาที่นับไว้นี้มีหกหมื่นสองพันเจ็ดร้อยคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 27, 'ให้ตระกูลอาเชอร์ตั้งค่ายเรียงถัดมา ปากีเอลบุตรชายโอครานจะเป็นนายกองของคนอาเชอร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 28, 'พลโยธาที่นับไว้นี้มีสี่หมื่นหนึ่งพันห้าร้อยคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 29, 'ให้ตระกูลนัฟทาลีเรียงถัดดานไป อาหิราบุตรชายเอนันจะเป็นนายกองของคนนัฟทาลี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 30, 'พลโยธาที่นับไว้นี้มีห้าหมื่นสามพันสี่ร้อยคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 31, 'จํานวนคนทั้งหมดที่นับเข้าในค่ายดาน เป็นหนึ่งแสนห้าหมื่นเจ็ดพันหกร้อยคน เมื่อออกเดินคนเหล่านี้จะเป็นพวกสุดท้าย เดินตามธงตระกูลของตน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 32, 'คนเหล่านี้เป็นชนชาติอิสราเอลที่นับตามเรือนบรรพบุรุษ คนทั้งหมดที่อยู่ในค่ายนับตามกองมีหกแสนสามพันห้าร้อยห้าสิบคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 33, 'แต่มิได้นับพวกเลวีรวมเข้าในคนอิสราเอล ตามที่พระเยโฮวาห์ทรงบัญชาโมเสส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 34, 'คนอิสราเอลก็กระทําดังนั้น เขาทั้งหลายตั้งค่ายอยู่ตามธง และยกออกเดินไปทุกคนตามครอบครัวของตน ตามเรือนบรรพบุรุษของตน ตามที่พระเยโฮวาห์ทรงบัญชาโมเสสไว้ทุกประการ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 1, 'ต่อไปนี้เป็นพงศ์พันธุ์ของอาโรนและโมเสสครั้งเมื่อพระเยโฮวาห์ตรัสกับโมเสสบนภูเขาซีนาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 2, 'ชื่อบุตรชายของอาโรนมีดังนี้ นาดับบุตรหัวปี อาบีฮู เอเลอาซาร์และอิธามาร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 3, 'นี่แหละเป็นชื่อบุตรชายของอาโรนที่ได้เจิมไว้เป็นปุโรหิต เป็นผู้ที่ท่านสถาปนาไว้ให้ปฏิบัติในตําแหน่งปุโรหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 4, 'แต่นาดับและอาบีฮูตายต่อพระพักตร์พระเยโฮวาห์ เมื่อเขาเอาไฟที่ผิดรูปแบบมาถวายบูชาต่อพระพักตร์พระเยโฮวาห์ที่ถิ่นทุรกันดารซีนาย และต่างก็ไม่มีบุตร ดังนั้นเอเลอาซาร์และอิธามาร์จึงได้ปรนนิบัติในตําแหน่งปุโรหิตอยู่ในสายตาของอาโรนบิดาของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 5, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 6, '“จงนําตระกูลเลวีเข้ามาใกล้ และตั้งเขาไว้ต่อหน้าอาโรนปุโรหิต ให้เขาปรนนิบัติอาโรน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 7, 'เขาจะปฏิบัติหน้าที่แทนอาโรนและแทนชุมนุมชนทั้งหมดหน้าพลับพลาแห่งชุมนุม ขณะเขาปฏิบัติงานที่พลับพลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 8, 'เขาจะดูแลบรรดาเครื่องใช้ของพลับพลาแห่งชุมนุม และปฏิบัติหน้าที่แทนคนอิสราเอล เมื่อเขาปฏิบัติงานที่พลับพลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 9, 'จงมอบคนเลวีไว้กับอาโรนและกับบุตรชายทั้งหลายของอาโรน เขาทั้งหลายรับเลือกจากคนอิสราเอลมอบไว้กับอาโรนแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 10, 'เจ้าจงแต่งตั้งอาโรนและบุตรชายทั้งหลายของอาโรนให้ปฏิบัติงานตามตําแหน่งปุโรหิต แต่คนอื่นที่เข้ามาใกล้จะต้องถูกลงโทษถึงตาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 11, 'และพระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 12, '“ดูเถิด เราเองได้เลือกคนเลวีจากคนอิสราเอลแทนบรรดาบุตรหัวปีท่ามกลางคนอิสราเอลที่คลอดจากครรภ์มารดาก่อน คนเลวีจะเป็นของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 13, 'เพราะบรรดาบุตรหัวปีเป็นของเรา ในวันที่เราได้ประหารชีวิตบุตรหัวปีทั้งหลายในประเทศอียิปต์นั้น เราได้เลือกบรรดาบุตรหัวปีในอิสราเอล ทั้งมนุษย์และสัตว์เดียรัจฉานไว้เป็นของเรา ทั้งหลายเหล่านี้ต้องเป็นของเรา เราคือพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 14, 'พระเยโฮวาห์ตรัสกับโมเสสที่ถิ่นทุรกันดารซีนายว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 15, '“จงนับคนเลวีตามเรือนบรรพบุรุษและตามครอบครัว คือท่านจงนับผู้ชายทุกคนที่มีอายุตั้งแต่เดือนหนึ่งขึ้นไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 16, 'โมเสสจึงได้นับเขาทั้งหลายตามพระดํารัสของพระเยโฮวาห์ดังที่พระองค์ตรัสสั่งไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 17, 'ต่อไปนี้เป็นชื่อบุตรชายของเลวี คือเกอร์โชน โคฮาท และเมรารี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 18, 'ชื่อบุตรชายของเกอร์โชนตามครอบครัว คือลิบนีและชิเมอี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 19, 'บุตรชายของโคฮาทตามครอบครัว คืออัมราม อิสฮาร์ เฮโบรน และอุสซีเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 20, 'และบุตรชายของเมรารีตามครอบครัว คือมาห์ลี และมูชี นี่เป็นครอบครัวคนเลวี ตามเรือนบรรพบุรุษของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 21, 'วงศ์เกอร์โชนมีครอบครัวลิบนีและครอบครัวชิเมอี เหล่านี้เป็นครอบครัวเกอร์โชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 22, 'จํานวนคนทั้งหลาย คือจํานวนผู้ชายทั้งหมดที่มีอายุตั้งแต่เดือนหนึ่งขึ้นไปเป็นเจ็ดพันห้าร้อยคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 23, 'ครอบครัวเกอร์โชนนั้นจะต้องตั้งค่ายอยู่ข้างหลังพลับพลาด้านตะวันตก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 24, 'มีเอลียาสาฟบุตรชายลาเอลเป็นหัวหน้าเรือนบรรพบุรุษของเกอร์โชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 25, 'งานที่วงศ์เกอร์โชนปฏิบัติในพลับพลาแห่งชุมนุมมีงานพลับพลา งานเต็นท์พร้อมกับเครื่องคลุมเต็นท์ และม่านประตูพลับพลาแห่งชุมนุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 26, 'ม่านบังลานและม่านประตูลาน ซึ่งอยู่รอบพลับพลาและแท่นบูชา รวมทั้งเชือกโยงทั้งงานสารพัดที่เกี่ยวกับสิ่งเหล่านี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 27, 'วงศ์โคฮาทมีครอบครัวอัมราม ครอบครัวอิสฮาร์ ครอบครัวเฮโบรน ครอบครัวอุสซีเอล เหล่านี้เป็นครอบครัวโคฮาท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 28, 'ตามจํานวนผู้ชายทั้งหมดที่มีอายุตั้งแต่เดือนหนึ่งขึ้นไปเป็นแปดพันหกร้อยคน เป็นคนปฏิบัติหน้าที่สถานบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 29, 'บรรดาครอบครัวลูกหลานของโคฮาทจะตั้งค่ายอยู่ทางด้านใต้ของพลับพลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 30, 'มีเอลีซาฟานบุตรชายอุสซีเอลเป็นหัวหน้าเรือนบรรพบุรุษของครอบครัวโคฮาท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 31, 'คนเหล่านี้มีหน้าที่ดูแลหีบพระโอวาท โต๊ะ คันประทีป แท่นบูชาทั้งสองและเครื่องใช้ต่างๆของสถานบริสุทธิ์ ซึ่งปุโรหิตใช้ปฏิบัติงานและม่าน ทั้งงานสารพัดที่เกี่ยวกับสิ่งเหล่านี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 32, 'เอเลอาซาร์บุตรชายของอาโรนปุโรหิตเป็นนายใหญ่เหนือหัวหน้าของคนเลวีและตรวจตราผู้ที่มีหน้าที่ปฏิบัติสถานบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 33, 'วงศ์เมรารีมีครอบครัวมาห์ลี และครอบครัวมูชี เหล่านี้เป็นครอบครัวเมรารี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 34, 'จํานวนคนทั้งหลายคือจํานวนผู้ชายทั้งหมดที่มีอายุตั้งแต่หนึ่งเดือนขึ้นไปเป็นหกพันสองร้อยคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 35, 'และศุรีเอลบุตรชายอาบีฮาอิลเป็นหัวหน้าเรือนบรรพบุรุษของครอบครัวเมรารี คนเหล่านี้จะตั้งค่ายอยู่ด้านเหนือของพลับพลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 36, 'งานที่กําหนดให้แก่ลูกหลานเมรารีคืองานดูแลไม้กรอบพลับพลา ไม้กลอน ไม้เสา ฐานรองและเครื่องประกอบสิ่งเหล่านี้ทั้งหมด ทั้งงานสารพัดที่เกี่ยวกับสิ่งเหล่านี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 37, 'และเสารอบลาน พร้อมกับฐานรอง หลักหมุดและเชือกโยง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 38, 'และบุคคลที่จะตั้งค่ายอยู่หน้าพลับพลาด้านตะวันออกหน้าพลับพลาแห่งชุมนุม ด้านที่ดวงอาทิตย์ขึ้น มีโมเสสและอาโรนกับลูกหลานของท่าน มีหน้าที่ดูแลการปรนนิบัติภายในสถานบริสุทธิ์และบรรดากิจการที่พึงกระทําเพื่อคนอิสราเอล และผู้ใดอื่นที่เข้ามาใกล้จะต้องถูกลงโทษถึงตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 39, 'บรรดาคนที่นับเข้าในคนเลวี ซึ่งโมเสสและอาโรนได้นับตามพระดํารัสของพระเยโฮวาห์ เป็นบรรดาผู้ชายทั้งหมดตามครอบครัวที่มีอายุตั้งแต่หนึ่งเดือนขึ้นไปเป็นสองหมื่นสองพันคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 40, 'และพระเยโฮวาห์ตรัสกับโมเสสว่า “จงนับบุตรชายหัวปีทั้งหลายของคนอิสราเอล ที่มีอายุตั้งแต่หนึ่งเดือนขึ้นไป จงจดจํานวนรายชื่อไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 41, 'เจ้าจงกันพวกเลวีไว้ให้เรา (เราคือพระเยโฮวาห์) ทั้งนี้เพื่อแทนบรรดาบุตรหัวปีท่ามกลางคนอิสราเอล และให้สัตว์ทั้งปวงของคนเลวีแทนสัตว์หัวปีทั้งหลายของคนอิสราเอล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 42, 'ดังนั้นโมเสสจึงได้นับบรรดาบุตรหัวปีท่ามกลางคนอิสราเอล ตามที่พระเยโฮวาห์ตรัสสั่งท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 43, 'บุตรชายหัวปีทั้งหลายตามจํานวนชื่อที่นับได้ ซึ่งมีอายุตั้งแต่หนึ่งเดือนขึ้นไป มีสองหมื่นสองพันสองร้อยเจ็ดสิบสามคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 44, 'และพระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 45, '“จงเอาคนเลวีแทนบุตรหัวปีทั้งหมดของคนอิสราเอล และเอาสัตว์ทั้งหลายของคนเลวีแทนสัตว์ของคนอิสราเอล คนเลวีจะเป็นของเรา เราคือพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 46, 'สําหรับเป็นค่าไถ่บุตรหัวปีของคนอิสราเอลจํานวนสองร้อยเจ็ดสิบสามคนที่เกินจํานวนผู้ชายคนเลวีนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 47, 'เจ้าจงเก็บคนละห้าเชเขล คือจงเก็บตามเชเขลของสถานบริสุทธิ์ (เชเขลหนึ่งมียี่สิบเก-ราห์)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 48, 'และมอบเงินซึ่งต้องเสียเป็นค่าไถ่ของคนที่เกินเหล่านั้นให้ไว้แก่อาโรนและลูกหลานของท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 49, 'โมเสสจึงเก็บเงินค่าไถ่จากคนเหล่านั้นที่เกินกว่าจํานวนคนที่คนเลวีไถ่ไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 50, 'คือท่านเก็บเงินจากบุตรหัวปีของคนอิสราเอล เป็นเงินจํานวนหนึ่งพันสามร้อยหกสิบห้าเชเขล นับตามเชเขลของสถานบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 51, 'และโมเสสได้นําเอาเงินค่าไถ่ให้แก่อาโรนและลูกหลานของอาโรน ตามพระดํารัสของพระเยโฮวาห์ ดังที่พระเยโฮวาห์ทรงบัญชาโมเสสไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 1, 'พระเยโฮวาห์ตรัสกับโมเสสและอาโรนว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 2, '“จงทําสํามะโนครัวลูกหลานโคฮาท จากคนเลวี ตามครอบครัวและตามเรือนบรรพบุรุษ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 3, 'จากคนที่มีอายุสามสิบปีถึงห้าสิบปี ทุกคนที่เข้าปฏิบัติงานได้ เพื่อทํางานในพลับพลาแห่งชุมนุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 4, 'นี่เป็นงานที่ลูกหลานโคฮาทจะกระทําในพลับพลาแห่งชุมนุม คืองานที่กระทําต่อสิ่งบริสุทธิ์ที่สุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 5, 'เมื่อจะเคลื่อนย้ายค่ายไป อาโรนและบุตรชายของท่านจะเข้าไปข้างใน และปลดม่านกําบังออกเอาคลุมหีบพระโอวาทไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 6, 'แล้วเอาหนังของแบดเจอร์คลุม และเอาผ้าสีฟ้าล้วนคลุมบนนั้น และสอดคานหาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 7, 'และเอาผ้าสีฟ้าปูลงบนโต๊ะสําหรับขนมปังหน้าพระพักตร์แล้ววางจานและช้อน อ่างน้ําและคนโทที่รินเครื่องดื่มบูชา และขนมปังหน้าพระพักตร์เป็นนิตย์ก็ให้วางอยู่บนผ้าสีฟ้านั้นด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 8, 'แล้วเอาผ้าสีแดงคลุม บนนี้เอาหนังของแบดเจอร์คลุมอีก แล้วสอดคานหาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 9, 'แล้วให้เขาเอาผ้าสีฟ้าคลุมคันประทีปที่ใช้จุด คลุมตะเกียง ตะไกรตัดไส้ตะเกียง ถาดใส่ตะไกร และบรรดาภาชนะใส่น้ํามันเติมตะเกียง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 10, 'เอาหนังของแบดเจอร์ห่อตะเกียงและเครื่องประกอบทั้งหมด แล้วใส่ไว้บนโครงหาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 11, 'ให้เขาเอาผ้าสีฟ้ามาคลุมแท่นทองคํา เอาหนังของแบดเจอร์คลุมไว้ แล้วสอดคานหาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 12, 'และให้เขาเอาผ้าสีฟ้าห่อภาชนะเครื่องใช้ซึ่งใช้อยู่ในสถานบริสุทธิ์และคลุมเสียด้วยหนังของแบดเจอร์ และใส่ไว้บนโครงหาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 13, 'ให้เอาขี้เถ้าออกจากแท่นบูชา เอาผ้าสีม่วงคลุมแท่นเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 14, 'เอาภาชนะประจําแท่นทั้งหมดซึ่งเป็นเครื่องใช้ประจําแท่น มีกระถางไฟ ขอเกี่ยวเนื้อ พลั่ว ชาม และภาชนะประจําแท่นทั้งสิ้นวางไว้ข้างบน แล้วเอาหนังของแบดเจอร์คลุม และสอดคานหาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 15, 'เมื่ออาโรนและบุตรชายคลุมสถานบริสุทธิ์และคลุมบรรดาเครื่องใช้ของสถานบริสุทธิ์เสร็จแล้ว เมื่อถึงเวลาเคลื่อนย้ายค่ายลูกหลานโคฮาทจึงจะเข้ามาหาม แต่เขาต้องไม่แตะต้องของบริสุทธิ์เหล่านั้นเกลือกว่าเขาจะต้องตาย สิ่งเหล่านี้แหละที่เป็นของประจําพลับพลาแห่งชุมนุมซึ่งลูกหลานของโคฮาทจะต้องหาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 16, 'แล้วเอเลอาซาร์บุตรชายของอาโรนปุโรหิตจะต้องดูแลน้ํามันสําหรับตะเกียง เครื่องหอม เครื่องธัญญบูชาประจําวัน และน้ํามันเจิม และดูแลพลับพลาทั้งหมดกับบรรดาสิ่งของในพลับพลานั้น คือสถานบริสุทธิ์และเครื่องประกอบด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 17, 'พระเยโฮวาห์ตรัสกับโมเสสและอาโรนว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 18, '“อย่าตัดตระกูลครอบครัวคนโคฮาทออกเสียจากคนเลวี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 19, 'แต่จงกระทําแก่เขาเพื่อจะให้มีชีวิตและไม่ตาย เมื่อเขาทั้งหลายเข้ามาใกล้ของบริสุทธิ์ที่สุดเหล่านั้น คืออาโรนและบุตรชายทั้งหลายของอาโรนจะเข้าไปตั้งเขาทั้งหลายไว้ตามงานและภาระของเขาทุกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 20, 'แต่อย่าให้คนโคฮาทเข้าไปมองของบริสุทธิ์แม้แต่อึดใจเดียวเกลือกว่าเขาจะต้องตาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 21, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 22, '“จงทําสํามะโนครัวลูกหลานเกอร์โชน ตามเรือนบรรพบุรุษตามครอบครัวของเขาด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 23, 'เจ้าจงนับคนที่มีอายุตั้งแต่สามสิบปีถึงห้าสิบปี ทุกคนที่เข้าปฏิบัติงานได้ เพื่อทํางานในพลับพลาแห่งชุมนุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 24, 'ต่อไปนี้เป็นการงานของครอบครัวเกอร์โชน คืองานปรนนิบัติและงานแบกภาระ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 25, 'ให้เขาทั้งหลายขนม่านพลับพลา และขนพลับพลาแห่งชุมนุมพร้อมกับผ้าคลุมและหนังของแบดเจอร์ที่คลุมอยู่ข้างบน และผ้าม่านสําหรับบังประตูพลับพลาแห่งชุมนุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 26, 'และม่านบังลาน และม่านทางเข้าประตูลานซึ่งอยู่รอบพลับพลาและแท่นบูชา และเชือกโยง และเครื่องใช้สอยทั้งสิ้น เขาจะต้องทํางานที่ควรกระทําทุกอย่างที่เกี่ยวกับสิ่งเหล่านี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 27, 'ให้อาโรนและบุตรชายทั้งหลายของอาโรนบังคับบัญชาบุตรชายทั้งหลายของเกอร์โชนเรื่องทุกสิ่งที่เขาจะต้องขน และงานทุกอย่างที่เขาจะต้องกระทํา และเจ้าจะต้องกําหนดทุกสิ่งที่เขาจะต้องขน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 28, 'นี่เป็นการงานของครอบครัวคนเกอร์โชนในพลับพลาแห่งชุมนุม และอิธามาร์บุตรชายของอาโรนปุโรหิตจะบังคับดูแลงานของคนเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 29, 'ฝ่ายคนเมรารีนั้น เจ้าจงนับเขาตามครอบครัวตามเรือนบรรพบุรุษ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 30, 'เจ้าจงนับคนที่มีอายุสามสิบปีขึ้นไปถึงห้าสิบปี ทุกคนที่เข้าปฏิบัติงานได้เพื่อทํางานในพลับพลาแห่งชุมนุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 31, 'และต่อไปนี้เป็นสิ่งที่กําหนดให้เขาขน งานทั้งหมดของเขาในการปรนนิบัติพลับพลาแห่งชุมนุม คือไม้กรอบพลับพลา ไม้กลอน ไม้เสาและฐานรอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 32, 'เสารอบลานพร้อมกับฐานรอง หลักหมุดและเชือกโยง เครื่องใช้และเครื่องประกอบสิ่งเหล่านี้ทั้งหมด เจ้าจงกําหนดชื่อสิ่งของที่เขาต้องหาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 33, 'นี่เป็นการงานของครอบครัวคนเมรารี เป็นงานทั้งหมดของเขาในการปรนนิบัติพลับพลาแห่งชุมนุม ในบังคับบัญชาของอิธามาร์บุตรชายของอาโรนปุโรหิต”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 34, 'โมเสสและอาโรนและบรรดาหัวหน้าของชุมนุมชนได้นับคนโคฮาท ตามครอบครัวและตามเรือนบรรพบุรุษ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 35, 'ทุกคนที่มีอายุตั้งแต่สามสิบปีขึ้นไปถึงห้าสิบปีที่เข้าปฏิบัติงานได้เพื่อทํางานในพลับพลาแห่งชุมนุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 36, 'และจํานวนคนตามครอบครัวของเขาเป็นสองพันเจ็ดร้อยห้าสิบคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 37, 'นี่แหละเป็นจํานวนคนในครอบครัวของโคฮาท บรรดาผู้ปฏิบัติงานในพลับพลาแห่งชุมนุม ซึ่งโมเสสและอาโรนได้นับไว้ตามที่พระเยโฮวาห์ตรัสสั่งโดยโมเสส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 38, 'จํานวนคนในลูกหลานเกอร์โชน ตามครอบครัวตามเรือนบรรพบุรุษ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 39, 'ทุกคนที่มีอายุตั้งแต่สามสิบปีขึ้นไปถึงห้าสิบปีที่เข้าปฏิบัติงานได้ เพื่อทํางานในพลับพลาแห่งชุมนุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 40, 'จํานวนคนตามครอบครัวตามเรือนบรรพบุรุษ เป็นสองพันหกร้อยสามสิบคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 41, 'นี่เป็นจํานวนคนในครอบครัวคนเกอร์โชน บรรดาผู้ปฏิบัติงานในพลับพลาแห่งชุมนุม ซึ่งโมเสสและอาโรนได้นับไว้ตามพระดํารัสของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 42, 'จํานวนคนในครอบครัวคนเมรารี ตามครอบครัวตามเรือนบรรพบุรุษ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 43, 'ทุกคนที่มีอายุตั้งแต่สามสิบปีขึ้นไปถึงห้าสิบปีที่เข้าปฏิบัติงานได้ เพื่อทํางานในพลับพลาแห่งชุมนุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 44, 'จํานวนคนตามครอบครัวของเขาเป็นสามพันสองร้อยคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 45, 'นี่แหละเป็นจํานวนคนที่นับได้ในครอบครัวคนเมรารี ซึ่งโมเสสและอาโรนได้นับไว้ตามที่พระเยโฮวาห์ตรัสสั่งโดยโมเสส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 46, 'บรรดาคนเลวีที่นับได้ ผู้ที่โมเสสและอาโรนและบรรดาหัวหน้าของคนอิสราเอลได้นับไว้ ตามครอบครัวตามเรือนบรรพบุรุษ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 47, 'ทุกคนที่มีอายุตั้งแต่สามสิบปีถึงห้าสิบปีที่เข้าปฏิบัติงานและทํางานขนภาระได้ในพลับพลาแห่งชุมนุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 48, 'จํานวนคนที่นับได้นั้นเป็นแปดพันห้าร้อยแปดสิบคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 49, 'เขาทั้งหลายได้ถูกนับตามที่พระเยโฮวาห์ตรัสสั่งทางโมเสส ให้ทุกคนทํางานปรนนิบัติหรืองานขนของเขา ดังนี้แหละโมเสสได้นับเขาไว้ตามที่พระเยโฮวาห์ทรงบัญชาโมเสส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 1, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 2, '“จงบัญชาคนอิสราเอลให้สั่งบรรดาคนโรคเรื้อน และทุกคนที่มีสิ่งไหลออก และคนใดที่มลทินเพราะการถูกซากศพให้ไปนอกค่าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 3, 'เจ้าจงสั่งทั้งผู้ชายและผู้หญิงให้ไปนอกค่าย เพื่อมิให้เขากระทําให้ค่ายของเขาซึ่งเราสถิตอยู่ท่ามกลางนั้นเป็นมลทิน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 4, 'และคนอิสราเอลก็กระทําตาม และสั่งคนเหล่านั้นให้ไปนอกค่าย พระเยโฮวาห์ตรัสสั่งโมเสสไว้ประการใด คนอิสราเอลก็กระทําตามอย่างนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 5, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 6, '“จงกล่าวแก่คนอิสราเอลว่า ผู้ชายก็ดีหรือผู้หญิงก็ดีกระทําบาปอย่างที่มนุษย์กระทํา คือประพฤติการละเมิดต่อพระเยโฮวาห์ และผู้นั้นมีความผิดแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 7, 'ก็ให้ผู้นั้นสารภาพความผิดที่เขาได้กระทํา และให้เขาคืนสิ่งที่ละเมิดซึ่งเขาได้มานั้นเต็มตามเดิม ทั้งเพิ่มอีกหนึ่งในห้าส่วนให้แก่เจ้าของเดิมผู้ที่เขาได้กระทําการละเมิดต่อนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 8, 'แต่ถ้าคนนั้นไม่มีพี่น้องที่จะรับของคืนก็ให้ถวายของที่คืนนั้นแด่พระเยโฮวาห์ทางปุโรหิตรวมทั้งแกะผู้สําหรับบูชาลบมลทินบาป ซึ่งเขาต้องบูชาลบมลทินบาปของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 9, 'และของบริสุทธิ์ที่คนอิสราเอลนํามาถวายทุกสิ่งอันนํามาให้แก่ปุโรหิตก็ตกเป็นของปุโรหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 10, 'สิ่งบริสุทธิ์ของทุกคนให้ตกเป็นของปุโรหิตและทุกสิ่งที่เขานําไปถวายปุโรหิตก็ต้องตกเป็นของปุโรหิต”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 11, 'และพระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 12, '“จงกล่าวแก่คนอิสราเอลว่า ถ้าภรรยาของผู้ชายคนใดหลงประพฤตินอกใจสามี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 13, 'มีชายอื่นมานอนร่วมกับนางพ้นตาสามีของนาง แม้นางได้กระทําตัวให้เป็นมลทินแล้ว แต่ไม่มีใครรู้เห็นและยังไม่มีพยาน เพราะจับไม่ได้คาที่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 14, 'จิตหึงหวงก็มาสิงสามี เขาจึงหึงหวงภรรยาของเขา และภรรยาได้กระทําตัวให้มลทิน หรือจิตหึงหวงมาสิงสามี เขาจึงหึงหวงภรรยาของเขา แม้ว่าภรรยามิได้กระทําตัวให้มลทิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 15, 'ก็ให้ชายผู้นั้นพาภรรยาของตนไปหาปุโรหิต นําเครื่องบูชาสําหรับภรรยาไป มีแป้งข้าวบาร์เลย์หนึ่งในสิบเอฟาห์ อย่าให้เขาเทน้ํามันหรือใส่กํายานในแป้งนั้น เพราะเป็นธัญญบูชาเรื่องความหึงหวง เป็นธัญญบูชาแห่งความรําลึกฟื้นให้ระลึกถึงความชั่วช้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 16, 'และปุโรหิตจะนํานางมาใกล้ให้เข้าเฝ้าพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 17, 'และปุโรหิตจะเอาน้ําบริสุทธิ์ที่ใส่ภาชนะดิน ปุโรหิตจะเอาผงคลีที่พื้นพลับพลาใส่ในน้ํานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 18, 'และปุโรหิตจะให้นางเข้าเฝ้าพระเยโฮวาห์ และแก้มวยผมของนางออก และส่งธัญญบูชาแห่งความรําลึกให้นางถือไว้ อันเป็นธัญญบูชาแห่งความหึงหวง แล้วปุโรหิตจะถือน้ําแห่งความขมขื่นที่นําการสาปแช่งนั้นไว้เอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 19, 'แล้วปุโรหิตจะให้นางสาบานตัวว่า ‘ถ้าไม่มีชายใดมานอนกับเจ้า หรือเจ้าไม่หันเหไปกระทํามลทิน เมื่อเจ้ายังอยู่ในอํานาจของสามี ก็ให้เจ้าพ้นเสียจากน้ําแห่งความขมขื่นที่นําการสาปแช่งนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 20, 'แต่ถ้าเจ้าได้หลงไปแม้เจ้าอยู่ในอํานาจของสามีและได้กระทําตัวเองให้เป็นมลทินและชายอื่นนอกจากสามีได้เข้านอนด้วยแล้ว’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 21, 'ก็ให้ปุโรหิตกระทําให้หญิงนั้นกล่าวคําสาบานแห่งการสาปแช่ง และปุโรหิตจะกล่าวแก่ผู้หญิงนั้นว่า ‘ขอให้พระเยโฮวาห์ทรงกระทําเจ้าให้เป็นคําสาปแช่ง และเป็นคําสาบานท่ามกลางชนชาติของเจ้า ในเมื่อพระเยโฮวาห์กระทําให้โคนขาเจ้าลีบและกระทําท้องเจ้าให้ป่องแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 22, 'ขอให้น้ําแห่งคําสาปแช่งนี้เข้าในตัวเจ้ากระทําให้ท้องเจ้าป่อง และกระทําให้โคนขาเจ้าลีบไป’ และนางนั้นจะต้องกล่าวว่า ‘เอเมน เอเมน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 23, 'แล้วปุโรหิตจะเขียนคําสาปนี้ลงในหนังสือ และลบความนั้นออกเสียด้วยน้ําแห่งความขมขื่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 24, 'แล้วให้หญิงนั้นดื่มน้ําแห่งความขมขื่นที่นําการสาปแช่ง แล้วน้ําที่นําการสาปแช่งนั้นจะเข้าไปในตัวนางเป็นความเฝื่อนฝาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 25, 'และปุโรหิตจะเอาธัญญบูชาแห่งความหึงหวงออกจากมือนาง แกว่งไปแกว่งมาถวายธัญญบูชานั้นต่อพระพักตร์พระเยโฮวาห์ แล้วนําไปถวายที่แท่นบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 26, 'และปุโรหิตจะหยิบธัญญบูชากํามือหนึ่งเป็นส่วนที่ระลึก แล้วเผาเสียบนแท่นบูชา แล้วจึงให้หญิงนั้นดื่มน้ํานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 27, 'เมื่อให้หญิงนั้นดื่มน้ําแล้ว ต่อมา ถ้านางกระทําตัวให้มลทินและประพฤตินอกใจสามี น้ําที่นําการสาปแช่งนั้นจะเข้าในตัวนางเป็นความเฝื่อนฝาด ท้องจะป่องและโคนขาจะลีบไป และหญิงนั้นจะเป็นคําสาปแช่งท่ามกลางชนชาติของนาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 28, 'ถ้าหญิงนั้นมิได้มีมลทิน แต่บริสุทธิ์ นางจะพ้นความผิดและตั้งครรภ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 29, 'นี่เป็นพระราชบัญญัติเรื่องความหึงหวงเมื่อภรรยาแม้จะอยู่ในอํานาจของสามีได้หลงไปกระทําตนให้มีมลทิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 30, 'หรือเมื่อจิตหึงหวงสิงผู้ชาย และเขาหึงหวงภรรยาของเขา แล้วเขาต้องให้นางไปเข้าเฝ้าพระเยโฮวาห์ และปุโรหิตจะปฏิบัติต่อนางตามพระราชบัญญัตินี้ทุกประการ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 31, 'ผู้ชายจึงจะพ้นความชั่วช้า แต่ผู้หญิงจะต้องรับโทษความชั่วช้าของนาง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 1, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 2, '“จงกล่าวแก่คนอิสราเอลว่า เมื่อผู้ชายก็ดี ผู้หญิงก็ดี ปลีกตัวด้วยการกระทําสัตย์ปฏิญาณ คือปฏิญาณเป็นนาศีร์ คือปลีกตัวออกถวายแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 3, 'ก็ให้ผู้นั้นปลีกตัวออกจากเหล้าองุ่นและสุรา เขาต้องไม่ดื่มน้ําส้มที่ได้จากเหล้าองุ่นหรือสุรา ไม่ดื่มน้ําองุ่นหรือรับประทานองุ่น ไม่ว่าสดหรือแห้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 4, 'ตลอดเวลาที่เขาปลีกตัวออกมานั้น เขาต้องไม่รับประทานสิ่งใดที่ได้จากต้นองุ่น แม้เป็นเมล็ดหรือเปลือกองุ่นก็ดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 5, 'ตลอดเวลาที่เขาปฏิญาณปลีกตัวออกมานั้น อย่าให้มีดโกนถูกศีรษะของเขา เขาต้องบริสุทธิ์จนกว่าจะสิ้นกําหนดเวลาที่เขาปลีกตัวออกมาถวายแด่พระเยโฮวาห์ เขาจะต้องไว้ผมยาว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 6, 'ตลอดเวลาที่เขาปลีกตัวออกมาถวายแด่พระเยโฮวาห์ เขาต้องไม่เข้าใกล้ศพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 7, 'อย่าทําตัวให้มีมลทินด้วยบิดามารดาหรือพี่น้องชายหญิงที่ตาย เพราะที่เขาปลีกตัวออกมาถวายแด่พระเจ้านั้นเป็นพันธนะของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 8, 'ตลอดเวลาที่เขาปลีกตัวออกมา เขาต้องบริสุทธิ์แด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 9, 'และถ้ามีคนมาตายอยู่ใกล้ตัวเขาปัจจุบันทันด่วน ศีรษะของเขาที่ชําระให้บริสุทธิ์ไว้ก็เป็นมลทินเสียแล้ว เขาต้องโกนศีรษะของเขาในวันชําระตัวคือในวันที่เจ็ดนั้นเขาต้องโกนศีรษะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 10, 'ในวันที่แปดเขาต้องนํานกเขาสองตัวหรือนกพิราบหนุ่มสองตัวไปให้ปุโรหิตที่ประตูพลับพลาแห่งชุมนุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 11, 'และปุโรหิตจะถวายบูชาตัวหนึ่งเป็นเครื่องบูชาไถ่บาป อีกตัวหนึ่งถวายเป็นเครื่องเผาบูชา ลบมลทินให้เขา เพราะเขาได้กระทําผิดเหตุเรื่องศพ และเขาต้องชําระศีรษะให้บริสุทธิ์ในวันนั้นอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 12, 'และให้เขาปลีกตัวออกถวายแด่พระเยโฮวาห์ตลอดเวลาการปลีกตัวของเขา และนําลูกแกะอายุหนึ่งขวบมาเป็นเครื่องบูชาไถ่การละเมิด แต่เวลาก่อนนั้นนับไม่ได้ เพราะการปฏิญาณปลีกตัวของเขานั้นมีมลทินเสียแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 13, 'เมื่อเวลาปลีกตัวของเขาครบแล้ว พระราชบัญญัติของพวกนาศีร์มีดังนี้ ให้นําเขามาที่ประตูพลับพลาแห่งชุมนุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 14, 'ให้เขาถวายเครื่องบูชาแด่พระเยโฮวาห์ คือลูกแกะผู้อายุขวบหนึ่งที่ปราศจากตําหนิเป็นเครื่องเผาบูชา และลูกแกะเมียอายุขวบหนึ่งที่ปราศจากตําหนิเป็นเครื่องบูชาไถ่บาป และแกะผู้ตัวหนึ่งที่ปราศจากตําหนิเป็นเครื่องสันติบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 15, 'และขนมปังไร้เชื้อกระจาดหนึ่ง ขนมทําด้วยยอดแป้งคลุกน้ํามัน ขนมแผ่นไร้เชื้อทาน้ํามันพร้อมกับเครื่องธัญญบูชาและเครื่องดื่มบูชาที่คู่กัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 16, 'และปุโรหิตจะนําของเหล่านี้ถวายต่อพระพักตร์พระเยโฮวาห์ แล้วถวายเครื่องบูชาไถ่บาปและเครื่องเผาบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 17, 'และปุโรหิตจะถวายแกะผู้เป็นเครื่องสันติบูชาแด่พระเยโฮวาห์ พร้อมกับขนมปังไร้เชื้อกระจาดหนึ่ง ปุโรหิตจะถวายธัญญบูชาและเครื่องดื่มบูชาที่คู่กันด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 18, 'และผู้เป็นนาศีร์จะโกนศีรษะแห่งการปลีกตัวนั้นที่ประตูพลับพลาแห่งชุมนุม และนําเอาผมที่ศีรษะแห่งการปลีกตัวนั้นไปใส่ไฟที่อยู่ใต้เครื่องสันติบูชาเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 19, 'เมื่อผู้เป็นนาศีร์โกนผมแห่งการปลีกตัวเสร็จแล้ว ปุโรหิตจะนําเนื้อสันขาหน้าของแกะตัวผู้ที่ต้มแล้ว กับขนมไร้เชื้อก้อนหนึ่งจากกระจาด และขนมแผ่นไร้เชื้อแผ่นหนึ่งวางไว้ในมือทั้งสองของผู้เป็นนาศีร์นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 20, 'แล้วปุโรหิตจะนําของเหล่านั้นแกว่งไปแกว่งมาเป็นเครื่องบูชาแกว่งถวายต่อพระพักตร์พระเยโฮวาห์ เป็นส่วนบริสุทธิ์ที่กันไว้สําหรับปุโรหิต พร้อมกับเนื้ออกที่แกว่งถวาย และเนื้อโคนขาที่ถวายแล้ว ต่อจากนี้ผู้เป็นนาศีร์ก็ดื่มน้ําองุ่นได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 21, 'นี่เป็นพระราชบัญญัติของผู้เป็นนาศีร์ผู้ปฏิญาณ และเครื่องบูชาของเขาที่ถวายแด่พระเยโฮวาห์ในการปลีกตัว นอกจากสิ่งอื่นๆที่เขาถวายได้ ดังนั้นแหละเขาต้องกระทําตามพระราชบัญญัติของการปลีกตัวออกไปเป็นนาศีร์ ตามที่เขาได้ปฏิญาณไว้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 22, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 23, '“จงกล่าวแก่อาโรนและบุตรชายทั้งหลายของอาโรนว่า ท่านทั้งหลายจงอวยพรแก่คนอิสราเอลดังต่อไปนี้ คือว่าแก่เขาทั้งหลายว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 24, 'ขอพระเยโฮวาห์ทรงอํานวยพระพรแก่ท่าน และพิทักษ์รักษาท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 25, 'ขอพระเยโฮวาห์ทรงให้พระพักตร์ของพระองค์ทอแสงแก่ท่าน และทรงพระกรุณาท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 26, 'ขอพระเยโฮวาห์ทรงมีสีพระพักตร์แช่มชื่นต่อท่านและประทานสันติสุขแก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 27, 'ดังนั้นแหละให้เขาประทับนามของเราเหนือคนอิสราเอล และเราจะได้อวยพรแก่เขาทั้งหลาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 1, 'เมื่อวันที่โมเสสจัดตั้งพลับพลาเสร็จ และได้เจิมและได้ชําระพลับพลากับบรรดาเครื่องใช้สอยประจําพลับพลาให้บริสุทธิ์ และได้เจิมและชําระแท่นบูชากับภาชนะประจําทั้งหมดให้บริสุทธิ์แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 2, 'บรรดาประมุขของคนอิสราเอล หัวหน้าเรือนบรรพบุรุษ คือประมุขของตระกูลต่างๆ ผู้อยู่เหนือผู้ที่ขึ้นทะเบียนไว้ ได้เข้ามาถวายของ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 3, 'และได้นําของบูชามาถวายต่อพระพักตร์พระเยโฮวาห์ มีเกวียนประทุนหกเล่มกับวัวหกคู่ ประมุขสองคนนําเกวียนเล่มหนึ่งและวัวคนละตัว ถวายเสียที่หน้าพลับพลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 4, 'แล้วพระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 5, '“จงรับของเหล่านี้ไว้จากเขาเพื่อจะได้ใช้ในการปรนนิบัติที่พลับพลาแห่งชุมนุม จงมอบไว้กับคนเลวีแก่ทุกคนตามงานปรนนิบัติของเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 6, 'โมเสสจึงนําเกวียนและวัวไปมอบให้แก่คนเลวี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 7, 'ท่านให้เกวียนสองเล่มกับวัวสองคู่แก่บุตรชายทั้งหลายของเกอร์โชนตามงานปรนนิบัติของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 8, 'ท่านมอบเกวียนสี่เล่มและวัวสี่คู่ให้แก่บุตรชายทั้งหลายของเมรารีตามงานปรนนิบัติของเขา ซึ่งเป็นตามคําชี้แจงของอิธามาร์บุตรชายอาโรนปุโรหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 9, 'แต่ท่านมิได้มอบอะไรให้แก่บุตรชายของโคฮาท เพราะงานปรนนิบัติของเขาเป็นงานที่ต้องหามสิ่งของบริสุทธิ์บนบ่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 10, 'และบรรดาประมุขก็นําของบูชามาเพื่องานมอบถวายแท่นบูชาในวันที่ทําพิธีเจิมแท่นบูชานั้น และพวกประมุขต่างก็ถวายเครื่องบูชาของตนหน้าแท่นบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 11, 'พระเยโฮวาห์ตรัสกับโมเสสว่า “ให้พวกประมุขมาถวายเครื่องบูชาของเขาวันละคนในงานมอบถวายแท่นบูชา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 12, 'ผู้ที่ถวายเครื่องบูชาในวันแรกคือนาโชนบุตรชายอัมมีนาดับแห่งตระกูลยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 13, 'ของถวายของเขาคือจานเงินหนึ่งใบหนักหนึ่งร้อยสามสิบเชเขล และชามเงินหนึ่งใบหนักเจ็ดสิบเชเขลตามเชเขลของสถานบริสุทธิ์ ภาชนะทั้งสองนี้มียอดแป้งคลุกน้ํามันเต็มเพื่อเป็นธัญญบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 14, 'ช้อนทองคําลูกหนึ่งหนักสิบเชเขล มีเครื่องหอมสําหรับเผาเต็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 15, 'วัวหนุ่มตัวหนึ่ง แกะผู้ตัวหนึ่ง ลูกแกะอายุหนึ่งขวบตัวหนึ่ง เป็นเครื่องเผาบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 16, 'ลูกแพะผู้ตัวหนึ่งเป็นเครื่องบูชาไถ่บาป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 17, 'วัวผู้สองตัว แกะผู้ห้า แพะผู้ห้า ลูกแกะอายุหนึ่งขวบห้า เป็นเครื่องสันติบูชา สิ่งเหล่านี้เป็นของถวายของนาโชนบุตรชายของอัมมีนาดับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 18, 'วันที่สองเนธันเอลบุตรชายศุอาร์ประมุขของตระกูลอิสสาคาร์ถวายของ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 19, 'เขาถวายของถวายของเขาเป็นจานเงินหนึ่งใบหนักหนึ่งร้อยสามสิบเชเขล ชามเงินหนึ่งใบหนักเจ็ดสิบเชเขลตามเชเขลของสถานบริสุทธิ์ ภาชนะทั้งสองนี้มียอดแป้งคลุกน้ํามันเต็มเพื่อเป็นธัญญบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 20, 'ช้อนทองคําลูกหนึ่งหนักสิบเชเขล มีเครื่องหอมสําหรับเผาเต็ม');
