INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 53, 'วัวผู้สองตัว แกะผู้ห้า แพะผู้ห้า ลูกแกะอายุหนึ่งขวบห้า เป็นเครื่องสันติบูชา สิ่งเหล่านี้เป็นของถวายของเอลีชามาบุตรชายของอัมมีฮูด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 54, 'วันที่แปดกามาลิเอลบุตรชายเปดาซูร์ประมุขของคนมนัสเสห์ถวายของ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 55, 'ของถวายของเขาคือจานเงินหนึ่งใบหนักหนึ่งร้อยสามสิบเชเขล ชามเงินหนึ่งใบหนักเจ็ดสิบเชเขลตามเชเขลของสถานบริสุทธิ์ ภาชนะทั้งสองนี้มียอดแป้งคลุกน้ํามันเต็มเพื่อเป็นธัญญบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 56, 'ช้อนทองคําลูกหนึ่งหนักสิบเชเขล มีเครื่องหอมสําหรับเผาเต็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 57, 'วัวหนุ่มตัวหนึ่ง แกะผู้ตัวหนึ่ง ลูกแกะอายุหนึ่งขวบตัวหนึ่ง เป็นเครื่องเผาบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 58, 'ลูกแพะผู้ตัวหนึ่งเป็นเครื่องบูชาไถ่บาป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 59, 'วัวผู้สองตัว แกะผู้ห้า แพะผู้ห้า ลูกแกะอายุหนึ่งขวบห้า เป็นเครื่องสันติบูชา สิ่งเหล่านี้เป็นของถวายของกามาลิเอลบุตรชายของเปดาซูร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 60, 'วันที่เก้าอาบีดันบุตรชายกิเดโอนีประมุขของคนเบนยามินถวายของ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 61, 'ของถวายของเขาคือจานเงินหนึ่งใบหนักหนึ่งร้อยสามสิบเชเขล ชามเงินหนึ่งใบหนักเจ็ดสิบเชเขลตามเชเขลของสถานบริสุทธิ์ ภาชนะทั้งสองนี้มียอดแป้งคลุกน้ํามันเต็มเพื่อเป็นธัญญบูชา');
