INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 65, 'วัวผู้สองตัว แกะผู้ห้า แพะผู้ห้า ลูกแกะอายุหนึ่งขวบห้า เป็นเครื่องสันติบูชา สิ่งเหล่านี้เป็นของถวายของอาบีดันบุตรชายของกิเดโอนี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 66, 'วันที่สิบอาหิเยเซอร์บุตรชายอัมมีชัดดัยประมุขของคนดานถวายของ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 67, 'ของถวายของเขาคือจานเงินหนึ่งใบหนักหนึ่งร้อยสามสิบเชเขล ชามเงินหนึ่งใบหนักเจ็ดสิบเชเขลตามเชเขลของสถานบริสุทธิ์ ภาชนะทั้งสองนี้มียอดแป้งคลุกน้ํามันเต็มเพื่อเป็นธัญญบูชา');
