INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 71, 'วัวผู้สองตัว แกะผู้ห้า แพะผู้ห้า ลูกแกะอายุหนึ่งขวบห้า เป็นเครื่องสันติบูชา สิ่งเหล่านี้เป็นของถวายของอาหิเยเซอร์บุตรชายของอัมมีชัดดัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 72, 'วันที่สิบเอ็ดปากีเอลบุตรชายโอครานประมุขของคนอาเชอร์ถวายของ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 73, 'ของถวายของเขาคือจานเงินหนึ่งใบหนักหนึ่งร้อยสามสิบเชเขล ชามเงินหนึ่งใบหนักเจ็ดสิบเชเขลตามเชเขลของสถานบริสุทธิ์ ภาชนะทั้งสองนี้มียอดแป้งคลุกน้ํามันเต็มเพื่อเป็นธัญญบูชา');
