INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 77, 'วัวผู้สองตัว แกะผู้ห้า แพะผู้ห้า ลูกแกะอายุหนึ่งขวบห้า เป็นเครื่องสันติบูชา สิ่งเหล่านี้เป็นของถวายของปากีเอลบุตรชายของโอคราน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 78, 'วันที่สิบสองอาหิราบุตรชายเอนันประมุขของคนนัฟทาลีถวายของ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 79, 'ของถวายของเขาคือจานเงินหนึ่งใบหนักหนึ่งร้อยสามสิบเชเขล ชามเงินหนึ่งใบหนักเจ็ดสิบเชเขลตามเชเขลของสถานบริสุทธิ์ ภาชนะทั้งสองนี้มียอดแป้งคลุกน้ํามันเต็มเพื่อเป็นธัญญบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 80, 'ช้อนทองคําลูกหนึ่งหนักสิบเชเขล มีเครื่องหอมสําหรับเผาเต็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 81, 'วัวหนุ่มตัวหนึ่ง แกะผู้ตัวหนึ่ง ลูกแกะอายุหนึ่งขวบตัวหนึ่ง เป็นเครื่องเผาบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 82, 'ลูกแพะผู้ตัวหนึ่งเป็นเครื่องบูชาไถ่บาป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 83, 'วัวผู้สองตัว แกะผู้ห้า แพะผู้ห้า ลูกแกะอายุหนึ่งขวบห้า เป็นเครื่องสันติบูชา สิ่งเหล่านี้เป็นของถวายของอาหิราบุตรชายของเอนัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 84, 'ต่อไปนี้เป็นของถวายในงานมอบถวายแท่นบูชาจากประมุขของคนอิสราเอล ในวันที่มีพิธีเจิมแท่นบูชานั้นคือจานเงินสิบสองใบ ชามเงินสิบสองใบ ช้อนทองคําสิบสองคัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 85, 'จานเงินหนึ่งใบหนักหนึ่งร้อยสามสิบเชเขล และชามหนึ่งใบหนักเจ็ดสิบเชเขล เงินที่ทําภาชนะทั้งหมดหนักสองพันสี่ร้อยเชเขล ตามเชเขลของสถานบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 86, 'ช้อนทองคําสิบสองลูก มีเครื่องหอมสําหรับเผาเต็ม หนักลูกละสิบเชเขลตามเชเขลของสถานบริสุทธิ์ ทองคําที่ทําช้อนทั้งหมดหนักหนึ่งร้อยยี่สิบเชเขล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 87, 'สัตว์สําหรับเครื่องเผาบูชา มีวัวผู้สิบสองตัว แกะผู้สิบสอง ลูกแกะอายุหนึ่งขวบสิบสอง พร้อมกับเครื่องธัญญบูชาคู่กัน และแพะผู้สิบสองตัวสําหรับเป็นเครื่องบูชาไถ่บาป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 88, 'สัตว์ทั้งหมดที่ถวายเป็นเครื่องสันติบูชา มีวัวผู้ยี่สิบสี่ แกะผู้หกสิบ แพะผู้หกสิบ และลูกแกะอายุหนึ่งขวบหกสิบ นี่แหละเป็นของถวายในงานมอบถวายแท่นบูชาเมื่อได้กระทําการเจิมแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 89, 'เมื่อโมเสสได้เข้าไปในพลับพลาแห่งชุมนุมเพื่อจะกราบทูลพระองค์ ท่านได้ยินพระสุรเสียงตรัสกับท่านมาจากพระที่นั่งกรุณา ซึ่งอยู่บนหีบพระโอวาทท่ามกลางเครูบทั้งสอง และพระสุรเสียงนั้นได้สนทนากับท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 1, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 2, '“จงกล่าวแก่อาโรนว่า เมื่อจะตั้งตะเกียงให้ตะเกียงทั้งเจ็ดส่องแสงข้างหน้าคันประทีป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 3, 'และอาโรนได้กระทําดังนั้น ท่านได้ตั้งตะเกียงให้ส่องแสงออกด้านหน้าคันประทีป ตามที่พระเยโฮวาห์ตรัสสั่งกับโมเสส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 4, 'ฝีมือที่ทําคันประทีปเป็นดังนี้ เป็นทองคําใช้ค้อนทุบ ตั้งแต่ฐานขึ้นไปถึงดอกเป็นฝีค้อน ตามแบบอย่างที่พระเยโฮวาห์สําแดงแก่โมเสส เขาจึงทําคันประทีปดังนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 5, 'และพระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 6, '“จงยกคนเลวีออกจากคนอิสราเอลและชําระเขาทั้งหลายเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 7, 'เจ้าจงชําระเขาดังนี้ จงเอาน้ําชําระมาประพรมเขา ให้เขาโกนตลอดทั้งตัว ให้ซักเสื้อผ้าและชําระตัวให้สะอาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 8, 'แล้วให้เขาทั้งหลายนําวัวหนุ่มตัวหนึ่ง กับเครื่องธัญญบูชาคู่กัน คือยอดแป้งคลุกน้ํามัน และเจ้าจงนําวัวหนุ่มอีกตัวหนึ่งเป็นเครื่องบูชาไถ่บาป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 9, 'แล้วจงพาคนเลวีมาหน้าพลับพลาแห่งชุมนุม และให้คนอิสราเอลมาชุมนุมพร้อมกันหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 10, 'เมื่อเจ้านําคนเลวีมากราบทูลต่อพระพักตร์พระเยโฮวาห์ ให้คนอิสราเอลเอามือของเขาวางบนคนเลวี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 11, 'และให้อาโรนถวายคนเลวีต่อพระพักตร์พระเยโฮวาห์ให้เป็นเครื่องบูชาแกว่งถวายจากประชาชนอิสราเอล เพื่อเขาจะได้ทํางานปรนนิบัติพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 12, 'แล้วคนเลวีจะเอามือของตนวางบนหัววัวผู้ทั้งสอง เจ้าจงเอาตัวหนึ่งมาถวายเป็นเครื่องบูชาไถ่บาป และอีกตัวหนึ่งให้เป็นเครื่องเผาบูชาแด่พระเยโฮวาห์ เพื่อลบมลทินบาปของคนเลวี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 13, 'เจ้าจงตั้งคนเลวีให้คอยรับใช้อาโรนและบุตรชายทั้งหลายของอาโรน และจงถวายเขาทั้งหลายให้เป็นเครื่องบูชาแกว่งถวายแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 14, 'ฉะนี้แหละเจ้าจงแยกคนเลวีออกจากคนอิสราเอล และคนเลวีจะเป็นของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 15, 'ตั้งแต่นั้นไปคนเลวีจะเข้าปฏิบัติงานที่พลับพลาแห่งชุมนุม ในเมื่อเจ้าได้ชําระเขาและกระทําเป็นเครื่องบูชาแกว่งถวายเขาไว้แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 16, 'เพราะเขาทั้งหมดถูกแยกออกจากคนอิสราเอล และมอบไว้แก่เรา เราได้รับเขามาเป็นของเราแล้วแทนทุกคนที่เกิดจากครรภ์มารดาก่อนคือ แทนบุตรหัวปีของประชาชนอิสราเอลทั้งหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 17, 'เพราะว่าลูกหัวปีทั้งหมดของคนอิสราเอลเป็นของเรา ทั้งคนและสัตว์ ในวันที่เราได้สังหารบรรดาลูกหัวปีในแผ่นดินอียิปต์ เราได้เลือกเขาไว้เป็นของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 18, 'และเราได้เลือกคนเลวีแทนบุตรหัวปีทั้งหมดของคนอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 19, 'และเราได้ให้คนเลวีจากคนอิสราเอลไว้กับอาโรนและบุตรชายของอาโรน ให้ปฏิบัติงานแทนคนอิสราเอลที่พลับพลาแห่งชุมนุม และทําการลบมลทินให้คนอิสราเอล เพื่อว่าจะไม่มีภัยพิบัติบังเกิดแก่คนอิสราเอล เมื่อคนอิสราเอลเข้ามาใกล้สถานบริสุทธิ์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 20, 'โมเสสและอาโรนและชุมนุมชนอิสราเอลทั้งหมดได้กระทําต่อคนเลวีดังนั้น ตามที่พระเยโฮวาห์ตรัสสั่งโมเสสในเรื่องคนเลวีทุกประการ คนอิสราเอลก็กระทําดังนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 21, 'คนเลวีได้ชําระตนให้สิ้นบาป และซักเสื้อผ้าของตน และอาโรนก็ถวายเขาเป็นเครื่องบูชาแกว่งถวายต่อพระพักตร์พระเยโฮวาห์ และอาโรนทําการลบมลทินชําระเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 22, 'แต่นั้นมาคนเลวีก็เข้าไปปฏิบัติในพลับพลาแห่งชุมนุม ในการรับใช้อาโรนและบุตรชายของอาโรน ตามที่พระเยโฮวาห์ตรัสสั่งโมเสสเรื่องคนเลวี เขาจึงได้กระทําอย่างนั้นแก่เขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 23, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 24, '“เรื่องนี้เกี่ยวกับคนเลวี ให้คนเลวีที่มีอายุตั้งแต่ยี่สิบห้าปีขึ้นไป เข้าไปปฏิบัติงานในพลับพลาแห่งชุมนุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 25, 'พออายุได้ห้าสิบปีให้เขาหยุดปฏิบัติ ไม่ต้องทํางานต่อไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 26, 'แต่ให้เขาช่วยพี่น้องในพลับพลาแห่งชุมนุมดูแลการงาน ไม่ต้องลงมือทําเอง เจ้าจงกระทําเช่นนี้แก่คนเลวีเมื่อกําหนดงานให้เขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 1, 'ในเดือนที่หนึ่งปีที่สองตั้งแต่เขาทั้งหลายออกจากแผ่นดินอียิปต์ พระเยโฮวาห์ตรัสกับโมเสสที่ถิ่นทุรกันดารซีนายว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 2, '“ให้คนอิสราเอลถือเทศกาลปัสกาตามเวลาที่กําหนดไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 3, 'คือเดือนนี้ในวันขึ้นสิบสี่ค่ํา เวลาเย็น เจ้าทั้งหลายจงถือเทศกาลปัสกาตามเวลาที่กําหนดนั้น เจ้าจงกระทําตามกฎเกณฑ์และพิธีต่างๆทั้งสิ้นของเทศกาลนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 4, 'โมเสสจึงบอกคนอิสราเอลให้ถือเทศกาลปัสกา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 5, 'เขาทั้งหลายได้ถือเทศกาลปัสกาในเดือนที่หนึ่งวันขึ้นสิบสี่ค่ําเวลาเย็นที่ถิ่นทุรกันดารซีนาย ที่พระเยโฮวาห์ตรัสสั่งโมเสสทุกประการ คนอิสราเอลก็กระทําตามอย่างนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 6, 'และมีผู้ชายบางคนที่มีมลทินเพราะถูกต้องศพ จึงถือปัสกาในวันนั้นไม่ได้ เขาจึงมาอยู่ต่อหน้าโมเสสและอาโรนในวันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 7, 'เขาเหล่านั้นกล่าวแก่ท่านว่า “เรามีมลทินเพราะได้ถูกต้องศพ ทําไมจึงห้ามมิให้เราถวายเครื่องบูชาของพระเยโฮวาห์ตามวันกําหนดท่ามกลางคนอิสราเอล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 8, 'และโมเสสบอกเขาว่า “จงคอยอยู่ก่อนเพื่อเราจะฟังดูว่า พระเยโฮวาห์จะตรัสสั่งอย่างไรเรื่องท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 9, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 10, '“จงกล่าวแก่คนอิสราเอลว่า ถ้าผู้ใดในพวกเจ้าหรือในเชื้อสายของเจ้ามีมลทินเพราะถูกต้องศพ หรือไปทางไกลก็ให้ผู้นั้นถือปัสกาแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 11, 'ให้ถือปัสกาในเดือนที่สองวันขึ้นสิบสี่ค่ําเวลาเย็น ให้เขากินขนมปังไร้เชื้อและผักรสขม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 12, 'เขาทั้งหลายต้องไม่ให้อะไรเหลือจนวันรุ่งขึ้น และไม่หักกระดูกแกะปัสกา ให้กระทําตามกฎในเรื่องถือเทศกาลปัสกาทุกประการ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 13, 'แต่คนที่สะอาดและมิได้อยู่ในระหว่างการเดินทางแต่งดไม่ถือเทศกาลปัสกา ผู้นั้นจะต้องถูกตัดขาดจากท่ามกลางชนชาติของเขา เพราะเขามิได้นําเครื่องบูชาของพระเยโฮวาห์มาถวายตามกําหนดเวลา ผู้นั้นจะต้องได้รับโทษบาปของเขาเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 14, 'ถ้าคนต่างด้าวมาอาศัยอยู่ท่ามกลางเจ้าทั้งหลาย ใคร่จะถือเทศกาลปัสกาแด่พระเยโฮวาห์ตามกฎของเทศกาลปัสกาและตามลักษณะก็ให้เขาถือได้ เจ้าจงมีกฎอย่างเดียวสําหรับทั้งคนต่างด้าวและชาวเมือง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 15, 'ในวันที่จัดตั้งพลับพลานั้นมีเมฆมาปกคลุมพลับพลาไว้ คือเต็นท์พระโอวาท เวลาเย็นเมฆนั้นก็อยู่เหนือพลับพลาปรากฏเหมือนเพลิงจนรุ่งเช้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 16, 'เป็นอย่างนั้นเสมอมา มีเมฆคลุมกลางวัน แต่กลางคืนปรากฏเหมือนเพลิง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 17, 'เมื่อไรเมฆลอยขึ้นจากพลับพลา ภายหลังนั้นพวกอิสราเอลก็ยกเดินไป ครั้นเมฆนั้นลอยหยุดอยู่ที่ใด คนอิสราเอลก็ตั้งค่ายอยู่ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 18, 'คนอิสราเอลออกเดินตามพระดํารัสของพระเยโฮวาห์ และเขาตั้งค่ายตามพระดํารัสของพระเยโฮวาห์ ตราบใดที่เมฆพักอยู่เหนือพลับพลาเขาก็ยังตั้งค่ายอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 19, 'แม้เมื่อเมฆอยู่เหนือพลับพลานานหลายวัน คนอิสราเอลก็ปฏิบัติตามพระบัญชาของพระเยโฮวาห์ ไม่ยกเดินไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 20, 'เมื่อเมฆอยู่เหนือพลับพลาน้อยวัน ตามพระดํารัสของพระเยโฮวาห์ เขาก็ยังอยู่ในค่าย แล้วตามพระดํารัสของพระเยโฮวาห์เขาก็ยกออกเดินทาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 21, 'เมื่อเมฆคงอยู่ตั้งแต่เย็นจนเช้า ครั้นเมฆลอยขึ้นในตอนเช้าเขาก็ยกออกเดิน ไม่ว่าเป็นกลางวันหรือกลางคืนก็ตาม เมื่อเมฆลอยขึ้นเขาก็ยกออกเดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 22, 'ไม่ว่าเมฆจะคงอยู่เหนือพลับพลาสองวัน หรือเดือนหนึ่งหรือปีหนึ่ง คนอิสราเอลก็อยู่ในค่ายนานเท่านั้น มิได้ยกออกไป แต่เมื่อเมฆลอยขึ้นเมื่อใด เขาก็ยกออกไปเมื่อนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 23, 'เขาตั้งค่ายอยู่ตามพระดํารัสของพระเยโฮวาห์ และเขายกออกเดินตามพระดํารัสของพระเยโฮวาห์ เขาทั้งหลายก็ปฏิบัติงานของพระเยโฮวาห์ ตามพระดํารัสที่พระเยโฮวาห์ตรัสสั่งโมเสส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 1, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 2, '“จงทําแตรเงินสองคันด้วยใช้ค้อนทุบ เจ้าจงใช้แตรนั้นเรียกชุมนุมและใช้รื้อย้ายค่าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 3, 'เมื่อเป่าแตรทั้งสองนั้นก็ให้ชุมนุมชนทั้งหมดมาประชุมพร้อมกันกับเจ้าที่ประตูพลับพลาแห่งชุมนุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 4, 'ถ้าเป่าแตรคันเดียวให้พวกประมุขผู้เป็นหัวหน้าคนอิสราเอลที่นับเป็นพันๆมาประชุมกับเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 5, 'เมื่อเป่าแตรปลุกให้บรรดาค่ายที่ตั้งอยู่ด้านตะวันออกยกออกเดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 6, 'เมื่อเป่าแตรปลุกหนที่สองให้บรรดาค่ายที่อยู่ด้านใต้ยกออกเดิน เมื่อใดจะให้ยกออกเดินก็ให้เป่าแตรปลุก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 7, 'แต่เมื่อจะให้คนทั้งปวงมาประชุมพร้อมกัน จงเป่าแตร แต่อย่าทําเสียงปลุก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 8, 'ให้บุตรชายของอาโรนคือปุโรหิตเป็นคนเป่าแตร แตรนี้จะเป็นกฎถาวรตลอดชั่วอายุของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 9, 'และเมื่อเจ้าทั้งหลายจะไปทําศึกในแผ่นดินของเจ้าสู้ศัตรูผู้มาบีบบังคับเจ้า ก็ให้เป่าแตรทําเสียงปลุก และเจ้าจะเป็นที่ระลึกต่อพระพักตร์พระเยโฮวาห์พระเจ้าของเจ้า และเจ้าจะได้พ้นจากศัตรูของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 10, 'ในวันที่เจ้าทั้งหลายมีความยินดี และในงานเทศกาลและในวันต้นเดือนของเจ้า เจ้าจงเป่าแตรเหนือเครื่องเผาบูชาและเหนือสัตวบูชาอันเป็นเครื่องสันติบูชา เป็นที่ให้พระเจ้าของเจ้าระลึกถึงเจ้า เราเป็นพระเยโฮวาห์พระเจ้าของเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 11, 'ต่อมาวันที่ยี่สิบเดือนที่สองปีที่สองทรงให้เมฆนั้นขึ้นจากพลับพลาพระโอวาท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 12, 'คนอิสราเอลก็ยกเดินทางไปจากถิ่นทุรกันดารซีนาย และเมฆนั้นมายั้งอยู่ที่ถิ่นทุรกันดารปาราน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 13, 'เขาทั้งหลายได้ยกออกเดินไปเป็นครั้งแรกตามพระดํารัสของพระเยโฮวาห์ที่ตรัสสั่งโมเสส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 14, 'ธงค่ายของคนยูดาห์ออกเดินไปเป็นกองๆก่อน มีนาโชนบุตรชายอัมมีนาดับเป็นผู้นําพลโยธา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 15, 'เนธันเอลบุตรชายศุอาร์นําพลโยธาตระกูลคนอิสสาคาร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 16, 'และเอลีอับบุตรชายเฮโลนนําพลโยธาตระกูลคนเศบูลุน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 17, 'เมื่อรื้อพลับพลาลงแล้ว บรรดาบุตรชายของเกอร์โชนและบุตรชายของเมรารีผู้แบกหามพลับพลานั้นก็ยกเดินไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 18, 'ธงค่ายของคนรูเบนออกเดินไปเป็นกองๆ เอลีซูร์บุตรชายเชเดเออร์เป็นผู้นําพลโยธา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 19, 'เชลูมิเอลบุตรชายซูริชัดดัยนําพลโยธาตระกูลคนสิเมโอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 20, 'เอลียาสาฟบุตรชายเดอูเอลนําพลโยธาตระกูลคนกาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 21, 'แล้วคนโคฮาทก็ยกออกเดินแบกหามสถานบริสุทธิ์ ก่อนที่พวกนี้ไปถึง เขาก็ตั้งพลับพลาเสร็จแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 22, 'ธงค่ายคนเอฟราอิมออกเดินไปเป็นกองๆ มีเอลีชามาบุตรชายอัมมีฮูดนําพลโยธา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 23, 'กามาลิเอลบุตรชายเปดาซูร์นําพลโยธาตระกูลคนมนัสเสห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 24, 'อาบีดันบุตรชายกิเดโอนีนําพลโยธาตระกูลคนเบนยามิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 25, 'แล้วธงค่ายคนดานเป็นพวกระวังท้ายของค่ายทั้งหมด ได้ยกออกเดินไปเป็นกองๆ มีอาหิเยเซอร์บุตรชายอัมมีชัดดัยนําพลโยธา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 26, 'ปากีเอลบุตรชายโอครานนําพลโยธาตระกูลคนอาเชอร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 27, 'อาหิราบุตรชายเอนันนําพลโยธาตระกูลคนนัฟทาลี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 28, 'นี่เป็นอันดับการเดินทางของคนอิสราเอลตามเหล่าพลโยธาของเขา เมื่อเขายกออกเดินไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 29, 'โมเสสพูดกับโฮบับบุตรชายเรกูเอลคนมีเดียนพ่อตาของโมเสสว่า “เราทั้งหลายออกเดินไปสู่ที่ซึ่งพระเยโฮวาห์ตรัสไว้ว่า ‘เราจะยกให้แก่เจ้าทั้งหลาย’ เชิญไปกับเราเถิด และเราทั้งหลายจะทําดีแก่ท่าน เพราะพระเยโฮวาห์ทรงสัญญาให้ของดีแก่คนอิสราเอล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 30, 'แต่เขาตอบโมเสสว่า “เราจะไม่ไป เราจะกลับไปเมืองของเรา ยังวงศ์ญาติของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 31, 'และโมเสสว่า “ขออย่าพรากจากเราไปเลย ท่านทราบอยู่แล้วว่า เราต้องตั้งค่ายอยู่ในถิ่นทุรกันดาร และท่านจะได้เป็นดังนัยน์ตาของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 32, 'ถ้าท่านไปกับเราทั้งหลาย พระเยโฮวาห์ทรงกระทําดีอะไรแก่เรา เราจะกระทําอย่างนั้นแก่ท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 33, 'เขาทั้งหลายก็ออกเดินจากภูเขาของพระเยโฮวาห์ระยะทางสามวัน หีบพันธสัญญาของพระเยโฮวาห์นําหน้าเขาไปสามวันเพื่อหาที่พักให้เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 34, 'เขาทั้งหลายยกค่ายไปเมื่อไร เมฆของพระเยโฮวาห์ก็อยู่เหนือเขาในกลางวันเมื่อนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 35, 'ต่อมาเมื่อหีบยกออกเดินเมื่อไร โมเสสกราบทูลว่า “ข้าแต่พระเยโฮวาห์ ขอทรงลุกขึ้นเถิด ให้ศัตรูทั้งหลายของพระองค์กระจัดกระจายไป ให้ผู้ที่ชังพระองค์หลีกหนีพระองค์ไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 36, 'เมื่อหีบยับยั้งท่านกราบทูลว่า “โอ ข้าแต่พระเยโฮวาห์ ขอเสด็จกลับมาสู่คนอิสราเอลที่นับเป็นพันๆเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 1, 'เมื่อประชาชนบ่น พระเยโฮวาห์ทรงไม่พอพระทัย พระเยโฮวาห์ทรงสดับแล้วทรงพระพิโรธ มีไฟของพระเยโฮวาห์มาไหม้อยู่ท่ามกลางเขา เผาค่ายรอบนอกเสียบ้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 2, 'แล้วคนทั้งหลายจึงร้องต่อโมเสส และเมื่อโมเสสได้อธิษฐานต่อพระเยโฮวาห์ ไฟก็ดับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 3, 'เขาจึงเรียกชื่อตําบลนั้นว่าทาเบราห์ เพราะไฟของพระเยโฮวาห์มาไหม้อยู่ท่ามกลางเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 4, 'คนที่ปะปนมากับเขาทั้งหลายเป็นคนโลภมาก ทั้งคนอิสราเอลก็ร้องไห้คร่ําครวญอีกว่า “ผู้ใดจะให้เนื้อเรากิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 5, 'เราระลึกถึงปลาที่เราเคยกินในอียิปต์โดยไม่ต้องซื้อ ทั้งแตงกวา แตงโม ต้นกระเทียม หอมใหญ่ หัวกระเทียม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 6, 'บัดนี้จิตใจของเราก็เหี่ยวแห้งลง ไม่มีอะไรให้เราดูเลยนอกจากมานานี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 7, 'มานานั้นเหมือนเมล็ดผักชี สีเหมือนยางไม้หอม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 8, 'ประชาชนก็เที่ยวออกไปเก็บมาโม่หรือตําในครกและใส่หม้อต้มทําขนม รสของมานาเหมือนรสน้ํามันสด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 9, 'กลางคืนเมื่อน้ําค้างตกมาเหนือค่าย มานาก็ตกมาด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 10, 'โมเสสได้ยินประชาชนร้องไห้ไปทั่วครอบครัวทั้งหลาย ต่างคนต่างอยู่ที่ประตูเต็นท์ของตน พระเยโฮวาห์ทรงกริ้วยิ่งนัก โมเสสก็ไม่พอใจด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 11, 'โมเสสจึงกราบทูลพระเยโฮวาห์ว่า “ไฉนพระองค์จึงให้ผู้รับใช้ของพระองค์ลําบากลําบนเช่นนี้ เหตุใดข้าพระองค์ไม่เป็นที่โปรดปรานในสายพระเนตรของพระองค์ พระองค์จึงทรงวางภาระของชนชาติทั้งหมดนี้ลงบนข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 12, 'ข้าพระองค์ตั้งครรภ์คนเหล่านี้มาหรือ ข้าพระองค์ให้กําเนิดคนเหล่านี้มาหรือ พระองค์จึงตรัสแก่ข้าพระองค์ว่า ‘จงอุ้มเขาไว้ในอกของเจ้าอย่างพ่อบุญธรรมอุ้มลูกแดงนํามาสู่แผ่นดินที่พระองค์ปฏิญาณจะให้แก่บรรพบุรุษของเขา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 13, 'ข้าพระองค์จะได้เนื้อมาจากไหนให้คนทั้งหมดนี้ เพราะเขาร้องไห้ต่อข้าพระองค์ว่า ‘ขอเนื้อให้เรากิน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 14, 'ข้าพระองค์ไม่สามารถหอบอุ้มคนเหล่านี้แต่ลําพังได้ เป็นภาระหนักเกินแก่ข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 15, 'ถ้าพระองค์จะทรงปฏิบัติแก่ข้าพระองค์อย่างนี้แล้ว ข้าพระองค์ทูลวิงวอนต่อพระองค์ ถ้าข้าพระองค์เป็นที่โปรดปรานในสายพระเนตรของพระองค์ ขอทรงประหารข้าพระองค์เสียทันทีเถิด อย่าให้ข้าพระองค์แลเห็นความชั่วร้ายของข้าพระองค์เลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 16, 'พระเยโฮวาห์ตรัสกับโมเสสว่า “จงรวบรวมพวกผู้ใหญ่ในอิสราเอลให้เราเจ็ดสิบคน เป็นคนที่เจ้าทราบว่าเป็นผู้ใหญ่ในประชาชนและเป็นเจ้าหน้าที่เหนือเขาทั้งหลาย จงพาเขามาที่พลับพลาแห่งชุมนุมให้เขายืนอยู่พร้อมกับเจ้าที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 17, 'เราจะลงมาสนทนากับเจ้าที่นั่น และเราจะเอาวิญญาณที่มีอยู่บนเจ้ามาใส่บนคนเหล่านั้นเสียบ้าง ให้เขาทั้งหลายแบกภาระของชนชาตินี้ด้วยกันกับเจ้า เพื่อเจ้าจะมิได้ทนแบกอยู่แต่ลําพัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 18, 'และจงกล่าวแก่คนทั้งปวงว่า ‘ท่านทั้งหลายจงชําระตัวให้บริสุทธิ์สําหรับพรุ่งนี้ ท่านจะได้รับประทานเนื้อ เพราะท่านร้องไห้ต่อพระกรรณของพระเยโฮวาห์ว่า “ผู้ใดจะให้เนื้อเรากิน เมื่อเราอยู่ในอียิปต์เราก็สุขสบาย” เพราะเหตุนี้พระเยโฮวาห์จะทรงประทานเนื้อให้ท่านทั้งหลายรับประทาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 19, 'ท่านจะมิได้รับประทานวันเดียว หรือสองวัน หรือห้าวัน หรือสิบวัน หรือยี่สิบวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 20, 'แต่หนึ่งเดือนเต็ม จนเนื้อจะล้นออกมาทางรูจมูกของท่าน จนท่านเอือม เพราะท่านได้ทอดทิ้งพระเยโฮวาห์ผู้อยู่ท่ามกลางท่านทั้งหลาย และได้ร้องไห้ต่อพระองค์กล่าวว่า “ไฉนเราจึงได้ออกมาจากอียิปต์”’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 21, 'แต่โมเสสกราบทูลว่า “คนที่ข้าพระองค์อยู่ท่ามกลางเขานั้นเป็นทหารราบหกแสนคน และพระองค์ตรัสว่า ‘เราจะให้เนื้อเขาทั้งหลายกินครบเดือนหนึ่ง’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 22, 'จะเอาฝูงแพะแกะฝูงวัวมาฆ่าให้เขาให้พอเขากินหรือ จะรวบรวมปลาทั้งหมดในทะเลให้เขาให้พอเขากินหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 23, 'พระเยโฮวาห์ตรัสกับโมเสสว่า “พระหัตถ์ของพระเยโฮวาห์สั้นไปหรือ บัดนี้เจ้าจะเห็นว่าคําของเราจะสําเร็จเพื่อเจ้าจริงหรือไม่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 24, 'โมเสสก็ออกไปบอกแก่คนทั้งปวงถึงพระดํารัสของพระเยโฮวาห์ และท่านได้รวบรวมพวกผู้ใหญ่ในประชาชนได้เจ็ดสิบคน แต่งตั้งเขาไว้ให้ยืนรอบพลับพลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 25, 'แล้วพระเยโฮวาห์เสด็จลงมาในเมฆและตรัสกับโมเสส และเอาวิญญาณที่มีอยู่บนโมเสสบ้างใส่บนพวกผู้ใหญ่เจ็ดสิบคนนั้น และต่อมาเมื่อวิญญาณอยู่บนเขาทั้งหลายแล้ว เขาทั้งหลายก็พยากรณ์ แต่เขาทั้งหลายก็ไม่ทําอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 26, 'ยังมีสองคนที่อยู่ในค่าย คนหนึ่งชื่อเอลดาด อีกคนหนึ่งชื่อเมดาด และวิญญาณอยู่บนเขา เขาเป็นคนที่ได้ลงทะเบียนไว้ แต่ไม่ได้มาที่พลับพลา เขาพยากรณ์ในค่าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 27, 'มีชายหนุ่มคนหนึ่งวิ่งมาบอกโมเสสว่า “เอลดาดและเมดาดกําลังพยากรณ์อยู่ในค่าย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 28, 'และโยชูวาบุตรชายนูนเป็นผู้รับใช้ของโมเสส เป็นคนหนุ่ม มากล่าวว่า “โมเสสเจ้านายของข้าพเจ้า ขอห้ามเขาเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 29, 'แต่โมเสสบอกเขาว่า “ท่านเจ็บร้อนแทนเราหรือ เราใคร่ให้ประชาชนของพระเยโฮวาห์เป็นผู้พยากรณ์ทุกคน และใคร่ให้พระเยโฮวาห์ทรงใส่วิญญาณของพระองค์ไว้บนเขาเหล่านั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 30, 'โมเสสและพวกผู้ใหญ่ของคนอิสราเอลก็กลับไปค่าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 31, 'มีลมพัดมาจากพระเยโฮวาห์พาฝูงนกคุ่มมาจากทะเล ให้มาตกอยู่ที่ข้างค่ายรอบค่ายทุกทิศห่างออกไปเป็นหนทางเดินวันหนึ่ง สูงพ้นพื้นดินประมาณสองศอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 32, 'วันนั้นประชาชนก็ลุกขึ้นเที่ยวจับนกคุ่มทั้งวันและคืนและตลอดวันรุ่งขึ้นด้วย คนที่จับได้น้อยที่สุดได้ถึงสิบโฮเมอร์ แล้วเขาเอามาวางตากทั่วค่าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 33, 'เมื่อเนื้อยังติดฟันเขาทั้งหลายอยู่ ยังรับประทานไม่ทันหมด พระเยโฮวาห์ทรงกริ้วประชาชนยิ่งนัก พระเยโฮวาห์ก็ทรงประหารประชาชนเสียด้วยภัยพิบัติอย่างร้ายแรง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 34, 'เขาจึงเรียกชื่อตําบลนั้นว่า ขิบโรทหัทธาอาวาห์ เพราะที่นั่นเขาฝังศพคนทั้งปวงที่โลภมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 35, 'ประชาชนได้ยกเดินจากขิบโรทหัทธาอาวาห์ถึงฮาเซโรทและยับยั้งที่ฮาเซโรท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 1, 'มิเรียมและอาโรนได้พูดติโมเสส เหตุหญิงคนเอธิโอเปียที่ท่านได้แต่งงานด้วย เพราะโมเสสได้แต่งงานกับหญิงคนเอธิโอเปียคนหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 2, 'เขาทั้งสองกล่าวว่า “พระเยโฮวาห์ตรัสทางโมเสสคนเดียวเท่านั้นจริงหรือ พระองค์ไม่ตรัสทางเราบ้างหรือ” พระเยโฮวาห์ทรงได้ยิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 3, '(โมเสสเป็นคนถ่อมใจมากยิ่งกว่าคนทั้งปวงที่พื้นแผ่นดิน)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 4, 'ทันใดนั้นพระเยโฮวาห์ตรัสกับโมเสสและอาโรนกับมิเรียมว่า “เจ้าทั้งสามจงออกมาที่พลับพลาแห่งชุมนุม” เขาทั้งสามก็ออกมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 5, 'พระเยโฮวาห์ก็เสด็จลงมาในเสาเมฆ ประทับยืนที่ประตูพลับพลาแห่งชุมนุม ทรงเรียกอาโรนและมิเรียม เขาทั้งสองก็มาข้างหน้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 6, 'พระองค์ตรัสว่า “จงฟังถ้อยคําของเรา ถ้าจะมีผู้พยากรณ์ท่ามกลางเจ้าทั้งหลาย เราพระเยโฮวาห์จะสําแดงตัวแก่ผู้นั้นเป็นนิมิต เราจะพูดกับเขาทางฝัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 7, 'สําหรับโมเสสผู้รับใช้ของเราก็ไม่เป็นเช่นนั้น ในวงศ์วานทั้งหมดของเราเขาสัตย์ซื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 8, 'เราพูดกับเขาปากต่อปากอย่างชัดเจน ไม่พูดเร้นลับ และเขาเห็นสัณฐานของพระเยโฮวาห์ ไฉนเจ้าไม่กลัวที่จะพูดติโมเสสผู้รับใช้ของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 9, 'พระเยโฮวาห์ทรงกริ้วเขามาก แล้วเสด็จไปเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 10, 'เมื่อเมฆลอยพ้นพลับพลาไป ดูเถิด มิเรียมก็เป็นโรคเรื้อน ขาวดุจหิมะ อาโรนหันไปดูมิเรียมและดูเถิด นางเป็นโรคเรื้อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 11, 'และอาโรนพูดกับโมเสสว่า “อนิจจา เจ้านายของข้าพเจ้า ขออย่าลงโทษบาปเราทั้งสองที่ได้กระทําความเขลาและบาปเช่นนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 12, 'ขออย่าให้มิเรียมเป็นเหมือนคนที่ตายแล้ว ดุจคนที่คลอดจากครรภ์มารดามีเนื้อกุดไปครึ่งหนึ่ง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 13, 'และโมเสสได้ร้องทูลพระเยโฮวาห์ว่า “โอ ข้าแต่พระเจ้า ขอพระองค์ทรงรักษานาง ข้าพระองค์ทูลวิงวอนต่อพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 14, 'แต่พระเยโฮวาห์ตรัสกับโมเสสว่า “ถ้าพ่อของนางถ่มน้ําลายรดหน้านาง นางจะละอายอยู่เจ็ดวันมิใช่หรือ จงกักนางไว้นอกค่ายเจ็ดวัน ภายหลังจึงให้กลับเข้ามาได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 15, 'ดังนั้นมิเรียมจึงถูกกักอยู่นอกค่ายเจ็ดวัน และประชาชนก็มิได้ยกเดินไปจนกว่ามิเรียมกลับเข้ามาอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 16, 'แล้วภายหลังประชาชนก็ยกเดินจากตําบลฮาเซโรทไปตั้งค่ายอยู่ที่ถิ่นทุรกันดารปาราน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 1, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 2, '“จงส่งคนไปสอดแนมดูที่แผ่นดินคานาอันที่เราให้แก่คนอิสราเอลนั้น จงส่งคนจากตระกูลของบรรพบุรุษตระกูลละคน ให้ทุกคนเป็นหัวหน้าในตระกูลนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 3, 'โมเสสจึงใช้เขาไปจากถิ่นทุรกันดารปารานตามพระดํารัสของพระเยโฮวาห์ ทุกคนเป็นหัวหน้าในคนอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 4, 'ต่อไปนี้เป็นชื่อของคนเหล่านั้น ชัมมูอาบุตรชายศักเกอร์เป็นตระกูลรูเบน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 5, 'ชาฟัทบุตรชายโฮรีเป็นตระกูลสิเมโอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 6, 'คาเลบบุตรชายเยฟุนเนห์เป็นตระกูลยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 7, 'อิกาลบุตรชายโยเซฟเป็นตระกูลอิสสาคาร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 8, 'โฮเชยาบุตรชายนูนเป็นตระกูลเอฟราอิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 9, 'ปัลทีบุตรชายราฟูเป็นตระกูลเบนยามิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 10, 'กัดเดียลบุตรชายโสดีเป็นตระกูลเศบูลุน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 11, 'ตระกูลโยเซฟคือตระกูลมนัสเสห์มีกัดดีบุตรชายสุสี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 12, 'อัมมีเอลบุตรชายเกมัลลีเป็นตระกูลดาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 13, 'เสธูร์บุตรชายมีคาเอลเป็นตระกูลอาเชอร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 14, 'นาบีบุตรชายโวฟสีเป็นตระกูลนัฟทาลี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 15, 'เกอูเอลบุตรชายมาคีเป็นตระกูลกาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 16, 'ชื่อเหล่านี้เป็นชื่อคนที่โมเสสใช้ไปสอดแนมที่แผ่นดินนั้น และโมเสสเรียกชื่อโฮเชยาบุตรชายนูนว่า โยชูวา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 17, 'โมเสสใช้เขาทั้งหลายไปสอดแนมที่แผ่นดินคานาอัน และสั่งเขาทั้งหลายว่า “จงขึ้นไปทางใต้นี้แล้วขึ้นไปตามภูเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 18, 'ตรวจดูแผ่นดินนั้นว่าเป็นอย่างไร และว่าคนที่อยู่ในแผ่นดินนั้นมีกําลังแข็งแรงหรืออ่อนแอ มีคนน้อยหรือมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 19, 'ดูว่าแผ่นดินที่เขาอาศัยอยู่เป็นอย่างไรบ้าง เป็นแผ่นดินที่ดีหรือเลวอย่างไร และบ้านเมืองที่เขาอาศัยอยู่เป็นอย่างไร เป็นเต็นท์หรือเป็นป้อมปราการที่เข้มแข็ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 20, 'ดูว่าแผ่นดินอุดมหรือจืด มีป่าไม้หรือเปล่า ท่านทั้งหลายจงมีใจกล้าหาญ และนําผลไม้ที่เมืองนั้นกลับมาบ้างด้วย” เวลานั้นเป็นฤดูผลองุ่นสุกรุ่นแรก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 21, 'คนเหล่านั้นจึงขึ้นไปสอดแนมแผ่นดิน ตั้งแต่ถิ่นทุรกันดารศิน จนถึงเรโหบ ที่ทางเข้าเมืองฮามัท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 22, 'เขาขึ้นไปทางใต้ถึงเมืองเฮโบรน และอาหิมาน เชชัย และทัลมัย คือคนอานาคอยู่ที่นั่น (เมืองเฮโบรนนี้เขาสร้างมาก่อนเมืองโศอันในอียิปต์ได้เจ็ดปี)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 23, 'เขาทั้งหลายมาถึงลําธารเอชโคล์ ที่นั่นเขาตัดองุ่นกิ่งหนึ่งมีองุ่นพวงหนึ่ง สองคนใช้ไม้คานหามมา เขาเก็บผลทับทิมและมะเดื่อมาบ้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 24, 'เขาเรียกที่นั่นว่าห้วยเอชโคล์เพราะพวงผลองุ่นซึ่งคนอิสราเอลได้ตัดมาจากที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 25, 'ล่วงมาสี่สิบวันเขาทั้งหลายก็กลับมาจากการไปสอดแนมที่แผ่นดินนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 26, 'เขาทั้งหลายกลับมาถึงโมเสสและอาโรน และมาถึงชุมนุมชนอิสราเอลในถิ่นทุรกันดารปารานที่คาเดช เขาเล่าเรื่องให้ท่านทั้งสองและบรรดาคนอิสราเอลฟัง และให้ดูผลไม้แห่งแผ่นดินนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 27, 'เขาทั้งหลายเล่าให้โมเสสฟังว่า “ข้าพเจ้าทั้งหลายได้ไปถึงแผ่นดินซึ่งท่านใช้ไป มีน้ํานมและน้ําผึ้งไหลบริบูรณ์ที่นั่นจริง และนี่เป็นผลไม้ของเมืองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 28, 'แต่คนที่อยู่ในเมืองนั้นมีกําลังมากและเมืองของเขาก็ใหญ่โตมีกําแพงล้อมรอบ นอกจากนั้นข้าพเจ้าทั้งหลายยังเห็นคนอานาคที่นั่นด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 29, 'คนอามาเลขอยู่ในแผ่นดินทางใต้ คนฮิตไทต์ คนเยบุส และคนอาโมไรต์อยู่บนภูเขา คนคานาอันอาศัยอยู่ที่ริมทะเล และตามฝั่งแม่น้ําจอร์แดน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 30, 'แต่คาเลบได้ให้คนทั้งปวงเงียบต่อหน้าโมเสสกล่าวว่า “ให้เราขึ้นไปทันทีและยึดเมืองนั้น เพราะพวกเรามีกําลังสามารถที่จะเอาชัยชนะได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 31, 'ฝ่ายคนทั้งปวงที่ขึ้นไปสอดแนมด้วยกันกล่าวว่า “เราไม่สามารถสู้คนเหล่านั้นได้ เพราะเขามีกําลังมากกว่าเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 32, 'และเขาได้กล่าวร้ายเรื่องแผ่นดินที่เขาได้ไปสอดแนมมาเล่าให้คนอิสราเอลฟังว่า “แผ่นดินที่เราได้ไปสืบดูตลอดแล้วนั้นเป็นแผ่นดินที่กินคนซึ่งอยู่ในนั้น บรรดาชาวเมืองที่เราเห็นเป็นคนรูปร่างใหญ่โต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 33, 'ที่นั่นเราเห็นพวกมนุษย์ยักษ์ คือบุตรของคนอานาคซึ่งมาจากพวกมนุษย์ยักษ์ เราเป็นเหมือนตั๊กแตนในสายตาของเรา ในสายตาของเขาก็เหมือนกัน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 1, 'แล้วบรรดาชุมนุมชนนั้นก็ร้องลั่นขึ้นมา ประชาชนร้องไห้ในคืนวันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 2, 'บรรดาคนอิสราเอลได้บ่นว่าโมเสสและอาโรน ชุมนุมชนทั้งหมดกล่าวแก่ท่านว่า “ให้เราตายเสียที่แผ่นดินอียิปต์ หรือให้เราตายเสียที่ถิ่นทุรกันดารนี้ก็ดีกว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 3, 'พระเยโฮวาห์นําเราเข้ามาในประเทศนี้ให้ตายด้วยดาบทําไมเล่า ลูกเมียของเราต้องตกเป็นเหยื่อ ที่เราจะกลับไปอียิปต์ไม่ดีกว่าหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 4, 'เขาพูดแก่กันและกันว่า “ให้เราตั้งคนหนึ่งขึ้นเป็นหัวหน้าแล้วกลับไปยังอียิปต์เถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 5, 'โมเสสกับอาโรนได้ซบหน้าลงถึงพื้นดินต่อหน้าที่ประชุมทั้งหมดของชุมนุมชนอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 6, 'และโยชูวาบุตรชายนูนกับคาเลบบุตรชายเยฟุนเนห์ เป็นผู้ที่ได้ร่วมไปสอดแนมที่แผ่นดินนั้น ได้ฉีกเสื้อผ้าของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 7, 'และกล่าวแก่บรรดาชุมนุมชนอิสราเอลว่า “แผ่นดินที่เราได้เที่ยวสอดแนมดูตลอดนั้นเป็นแผ่นดินที่ดีเหลือเกิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 8, 'ถ้าพระเยโฮวาห์พอพระทัยในพวกเรา พระองค์จะทรงนําเราเข้าไปในแผ่นดินนี้ และทรงประทานแก่เรา เป็นแผ่นดินที่มีน้ํานมและน้ําผึ้งไหลบริบูรณ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 9, 'ขอแต่อย่าให้พวกเรากบฏต่อพระเยโฮวาห์เท่านั้น อย่ากลัวชาวแผ่นดินนั้น เพราะเขาทั้งหลายเป็นขนมของเราแล้ว ร่มฤทธิ์ของเขาก็สูญไปแล้ว พระเยโฮวาห์สถิตฝ่ายเรา อย่ากลัวเขาเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 10, 'แต่ชุมนุมชนทั้งหมดนั้นพูดกันว่าให้เอาก้อนหินขว้างเขาเสีย ขณะนั้นสง่าราศีของพระเยโฮวาห์ปรากฏที่พลับพลาแห่งชุมนุมต่อหน้าบรรดาคนอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 11, 'และพระเยโฮวาห์ตรัสกับโมเสสว่า “ชนชาตินี้จะสบประมาทเรานานสักเท่าใด แม้ว่าเราได้กระทําหมายสําคัญต่างๆท่ามกลางเขามาแล้ว เขาทั้งหลายจะไม่เชื่อเรานานเท่าใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 12, 'เราจะประหารเขาเสียด้วยโรคร้ายและตัดเขาเสียจากการสืบมรดก เราจะกระทําให้เจ้าเป็นประเทศใหญ่โตและแข็งแรงกว่าเขาอีก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 13, 'แต่โมเสสได้กราบทูลพระเยโฮวาห์ว่า “ชาวอียิปต์จะได้ยินเรื่องนี้ (เพราะพระองค์ทรงพาชาตินี้ออกมาจากท่ามกลางเขาด้วยฤทธานุภาพของพระองค์)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 14, 'ชาวอียิปต์จะเล่าความนั้นแก่ชาวประเทศนี้ ข้าแต่พระเยโฮวาห์ เขาทั้งหลายได้ยินว่าพระองค์สถิตท่ามกลางชนชาตินี้ ข้าแต่พระเยโฮวาห์ เขาได้เห็นพระพักตร์ของพระองค์ เมฆของพระองค์ตั้งอยู่เหนือเขาทั้งหลาย พระองค์ทรงนําเขาในเวลากลางวันด้วยเสาเมฆ และในกลางคืนด้วยเสาเพลิง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 15, 'บัดนี้ถ้าพระองค์จะทรงประหารชนชาตินี้ดุจคนๆเดียว ประเทศทั้งหลายที่ได้ยินกิตติศัพท์ถึงพระองค์จะพูดกันว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 16, '‘เพราะพระเยโฮวาห์ไม่สามารถพาชนชาตินี้ไปถึงแผ่นดินที่พระองค์ทรงปฏิญาณไว้แก่เขานั้น พระองค์จึงทรงประหารเขาเสียที่ในถิ่นทุรกันดาร’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 17, 'บัดนี้ข้าพระองค์ทูลวิงวอน ขอพระองค์ทรงบันดาลให้ฤทธิ์อํานาจขององค์พระผู้เป็นเจ้าให้ใหญ่ยิ่งดังพระสัญญาที่ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 18, '‘พระเยโฮวาห์ทรงพระพิโรธช้า ทรงอุดมในความเมตตา ทรงโปรดยกโทษความชั่วช้าและให้อภัยการละเมิด แต่ถือว่าไม่มีโทษหามิได้ ให้โทษเพราะความชั่วช้าของบิดาตกทอดไปถึงลูกหลานสามชั่วสี่ชั่วอายุ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 19, 'ขอทรงประทานอภัยความชั่วช้าของชนชาตินี้ตามความยิ่งใหญ่แห่งความเมตตาของพระองค์ ดังที่พระองค์ทรงประทานอภัยชนชาตินี้ตั้งแต่อียิปต์จนบัดนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 20, 'แล้วพระเยโฮวาห์จึงตรัสว่า “เราให้อภัยตามคําของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 21, 'แต่แท้จริง เรามีชีวิตอยู่แน่ฉันใด และบรรดาโลกจะเต็มไปด้วยสง่าราศีของพระเยโฮวาห์แน่ฉันใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 22, 'คนทั้งหลายที่ได้เห็นสง่าราศีของเรา และได้เห็นการอัศจรรย์ต่างๆที่เราได้กระทําในอียิปต์และในถิ่นทุรกันดาร และยังได้ทดลองเรามาตั้งสิบครั้ง และยังมิได้ฟังเสียงของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 23, 'คนเหล่านี้จะมิได้เห็นแผ่นดินที่เราปฏิญาณไว้กับปู่ย่าตายายของเขาฉันนั้น คนทั้งปวงที่สบประมาทเราจะไม่ได้เห็นแผ่นดินนั้นสักคนเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 24, 'แต่ส่วนคาเลบผู้รับใช้ของเรา เพราะมีจิตใจต่างกันและได้ตามเรามาอย่างเต็มที่ เราก็จะได้นําเขาไปถึงแผ่นดินที่เขาได้ไปมาและเชื้อสายของเขาจะได้กรรมสิทธิ์เมืองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 25, '(พวกอามาเลขและพวกคานาอันอยู่ที่หว่างเขา) พรุ่งนี้เจ้าจงกลับไปในถิ่นทุรกันดารตามทางถึงทะเลแดง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 26, 'พระเยโฮวาห์ตรัสกับโมเสสและอาโรนว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 27, '“เราจะทนชุมนุมชนชั่วร้ายนี้บ่นต่อเรานานสักเท่าใด เราได้ยินเสียงบ่นของคนอิสราเอลซึ่งเขาบ่นว่าเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 28, 'เจ้าจงกล่าวแก่เขาว่า พระเยโฮวาห์ตรัสว่า ‘เรามีชีวิตอยู่แน่ฉันใด เราจะกระทําสิ่งที่เจ้าทั้งหลายบ่นให้เราได้ยินแก่เจ้าฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 29, 'ซากศพของเจ้าจะตกหล่นอยู่ในถิ่นทุรกันดารนี้ จํานวนคนทั้งหมดของเจ้านับตั้งแต่อายุยี่สิบปีขึ้นไป ผู้ใดที่บ่นว่าเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 30, 'จะไม่มีสักคนหนึ่งที่มาถึงแผ่นดินที่เราปฏิญาณว่าจะให้เจ้าอาศัยอยู่ เว้นแต่คาเลบบุตรชายเยฟุนเนห์และโยชูวาบุตรชายนูน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 31, 'แต่ลูกเล็กที่เจ้าทั้งหลายว่าจะเป็นเหยื่อนั้นเราจะพาเขาทั้งหลายเข้าไป และเขาจะรู้จักแผ่นดินที่เจ้าทั้งหลายได้สบประมาท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 32, 'ส่วนเจ้าทั้งหลาย ศพของเจ้าจะตกหล่นอยู่ในถิ่นทุรกันดารนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 33, 'ลูกหลานของเจ้าทั้งหลายจะพเนจรอยู่ในถิ่นทุรกันดารถึงสี่สิบปี เขาจะทนโทษการเล่นชู้ของเจ้า จนกว่าจํานวนซากศพของเจ้าจะอยู่ในถิ่นทุรกันดารนี้ครบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 34, 'ตามจํานวนวันที่เจ้าเข้าไปสอดแนมในแผ่นดินนั้นซึ่งมีสี่สิบวัน วันหนึ่งจะเป็นปีหนึ่ง เจ้าทั้งหลายจะรับโทษความชั่วช้าของเจ้าอยู่สี่สิบปี เจ้าทั้งหลายจะทราบถึงการฝ่าฝืนคําสัญญาของเรา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 35, 'เราผู้เป็นพระเยโฮวาห์ได้ลั่นวาจาแล้ว เราจะกระทําดังนั้นแก่บรรดาชุมนุมชนที่ชั่วร้ายซึ่งร่วมกันคิดต่อสู้เรา เขาจะสิ้นสุดลงในถิ่นทุรกันดาร เขาจะตายอยู่ที่นั่น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 36, 'คนที่โมเสสใช้ไปสอดแนมที่แผ่นดิน ผู้ที่กลับมาเล่าความใส่ร้ายแผ่นดินนั้น ซึ่งกระทําให้บรรดาชุมนุมชนบ่นว่าโมเสส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 37, 'คนที่มารายงานความร้ายเรื่องแผ่นดินนั้นได้ตายเสียด้วยโรคภัยต่อพระพักตร์พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 38, 'แต่โยชูวาบุตรชายนูน และคาเลบบุตรชายเยฟุนเนห์ในหมู่คนที่ไปสอดแนมที่แผ่นดินยังมีชีวิตอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 39, 'และโมเสสเล่าข้อความนี้ให้คนอิสราเอลทั้งหมดฟัง ประชาชนก็ร้องไห้โศกเศร้ายิ่งนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 40, 'และคนทั้งปวงได้ลุกขึ้นแต่เช้า ขึ้นไปยังที่สูงบนภูเขากล่าวว่า “ดูเถิด เราทั้งหลายมาอยู่ที่นี่แล้ว เราจะเข้าไปยังที่ซึ่งพระเยโฮวาห์ทรงสัญญาไว้ เพราะเราได้กระทําผิดแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 41, 'แต่โมเสสกล่าวว่า “เหตุไฉนท่านขัดขืนพระดํารัสของพระเยโฮวาห์ การนี้จะไม่สําเร็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 42, 'อย่าขึ้นไปเลย เพราะพระเยโฮวาห์มิได้อยู่ท่ามกลางท่าน เกลือกว่าท่านทั้งหลายจะล้มตายอยู่ต่อหน้าศัตรู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 43, 'เพราะคนอามาเลขและคนคานาอันอยู่ข้างหน้าท่าน ท่านจะล้มลงด้วยดาบ เพราะท่านได้หันกลับจากการตามพระเยโฮวาห์ พระเยโฮวาห์จะไม่สถิตท่ามกลางท่านทั้งหลาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 44, 'แต่เขาทั้งหลายยังบังอาจขึ้นไปยังที่สูงบนเนินเขา แต่หีบพันธสัญญาแห่งพระเยโฮวาห์และโมเสสมิได้ออกจากค่าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 45, 'แล้วคนอามาเลขและคนคานาอันที่อยู่บนเนินเขานั้นได้ลงมาขับไล่เขาให้พ่ายแพ้จนไปถึงตําบลโฮรมาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 1, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 2, '“จงกล่าวแก่คนอิสราเอลว่า เมื่อเจ้าทั้งหลายจะเข้าในแผ่นดินที่เจ้าจะเข้าอาศัยอยู่ ซึ่งเราให้แก่เจ้านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 3, 'ถ้าผู้ใดจะนําเครื่องบูชาจากฝูงวัวหรือจากฝูงแพะแกะไปถวายพระเยโฮวาห์เป็นเครื่องบูชาด้วยไฟ คือเครื่องเผาบูชา หรือเครื่องสัตวบูชาทําตามคําปฏิญาณ หรือเป็นเครื่องบูชาด้วยใจสมัคร หรือในการเลี้ยงตามกําหนด กระทําให้มีกลิ่นที่พอพระทัยแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 4, 'ก็ให้ผู้ที่นําเครื่องบูชานั้นนําธัญญบูชาถวายแด่พระเยโฮวาห์ คือยอดแป้งหนึ่งในสิบเอฟาห์คลุกกับน้ํามันหนึ่งในสี่ฮิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 5, 'และเจ้าจงจัดน้ําองุ่นหนึ่งในสี่ฮินสําหรับลูกแกะทุกตัว เป็นเครื่องดื่มบูชาคู่กับเครื่องเผาบูชาคู่กับเครื่องสัตวบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 6, 'หรือสําหรับแกะผู้ตัวหนึ่งเจ้าจงจัดธัญญบูชาด้วยยอดแป้งสองในสิบเอฟาห์คลุกน้ํามันหนึ่งในสามฮิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 7, 'และสําหรับเป็นเครื่องดื่มบูชา เจ้าจงถวายน้ําองุ่นหนึ่งในสามฮิน ให้เป็นกลิ่นที่พอพระทัยแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 8, 'เมื่อเจ้าจัดวัวผู้เป็นเครื่องเผาบูชา หรือเป็นเครื่องสัตวบูชาทําตามคําปฏิญาณ หรือให้เป็นสันติบูชาแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 9, 'ก็ให้นําธัญญบูชามียอดแป้งสามในสิบเอฟาห์คลุกน้ํามันครึ่งฮินมาบูชาพร้อมกับวัวผู้นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 10, 'และให้นําเครื่องดื่มบูชามีน้ําองุ่นครึ่งฮินให้เป็นการบูชาด้วยไฟ เป็นกลิ่นที่พอพระทัยแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 11, 'จงกระทําอย่างนี้สําหรับวัวผู้หรือแกะผู้ทุกตัว หรือสําหรับลูกแกะหรือลูกแพะทุกตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 12, 'ตามจํานวนสัตว์ที่จัดมา จงกระทําตามส่วนนี้แก่สัตว์ทุกๆตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 13, 'บรรดาชาวพื้นเมืองต้องกระทําอย่างนี้ทุกคน เมื่อจะถวายเครื่องบูชาด้วยไฟ เป็นกลิ่นที่พอพระทัยแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 14, 'ถ้าคนต่างด้าวที่มาอาศัยอยู่กับเจ้า หรือคนหนึ่งคนใดท่ามกลางเจ้าตลอดชั่วอายุของเจ้าใคร่จะถวายเครื่องบูชาด้วยไฟ เป็นกลิ่นที่พอพระทัยแด่พระเยโฮวาห์ ก็ให้เขาทั้งหลายกระทําเหมือนเจ้าทั้งหลายได้กระทํานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 15, 'จะต้องมีกฎอย่างเดียวกันสําหรับชุมนุมชนและสําหรับคนต่างด้าวผู้มาอาศัยอยู่กับเจ้า เป็นกฎถาวรตลอดชั่วอายุของเจ้า คือเจ้าเป็นอย่างใด คนต่างด้าวก็เป็นอย่างนั้นต่อพระพักตร์พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 16, 'จะต้องมีพระราชบัญญัติอย่างเดียวกันและลักษณะอย่างเดียวกันสําหรับเจ้าและสําหรับคนต่างด้าวที่มาอาศัยอยู่กับเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 17, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 18, '“จงกล่าวแก่คนอิสราเอลว่า เมื่อเจ้าทั้งหลายมาถึงแผ่นดินที่เราจะพาเจ้าไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 19, 'และเมื่อเจ้ารับประทานอาหารแห่งแผ่นดินนั้น เจ้าจงนําเครื่องบูชาถวายแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 20, 'จงเอาแป้งเปียกผลแรกทําขนมก้อนหนึ่งถวายเป็นเครื่องบูชา เป็นเครื่องบูชาที่ได้จากลานนวดข้าว เจ้าจงถวายเช่นว่านี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 21, 'จงเอาแป้งเปียกผลแรกถวายเป็นเครื่องบูชาแด่พระเยโฮวาห์ตลอดชั่วอายุของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 22, 'ถ้าเจ้าทั้งหลายได้ประพฤติผิดมิได้รักษาพระบัญญัติเหล่านี้ทุกประการ ซึ่งพระเยโฮวาห์ตรัสสั่งแก่โมเสส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 23, 'ทุกประการซึ่งพระเยโฮวาห์ทรงบัญชาไว้ทางโมเสส ตั้งแต่วันที่พระเยโฮวาห์ประทานพระบัญชาแก่โมเสส และต่อๆไปตลอดชั่วอายุของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 24, 'แล้วถ้าประชาชนได้กระทําผิดโดยไม่เจตนา โดยที่ชุมนุมชนไม่รู้เห็น ชุมนุมชนทั้งหมดต้องถวายวัวหนุ่มตัวหนึ่งเป็นเครื่องเผาบูชา ให้เป็นกลิ่นที่พอพระทัยแด่พระเยโฮวาห์ พร้อมกับธัญญบูชาและเครื่องดื่มบูชาคู่กันตามลักษณะ และถวายลูกแพะผู้ตัวหนึ่งเป็นเครื่องบูชาไถ่บาป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 25, 'และให้ปุโรหิตทําการลบมลทินบาปให้แก่ชุมนุมชนอิสราเอลทั้งหมด และเขาทั้งหลายจะได้รับอภัยโทษ เพราะเป็นการผิดโดยไม่เจตนา และเขาจะนําเครื่องบูชาของเขามาถวายด้วยไฟแด่พระเยโฮวาห์ และถวายเครื่องบูชาไถ่บาปต่อพระพักตร์พระเยโฮวาห์ เพราะความผิดโดยไม่เจตนาของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 26, 'และชุมนุมชนอิสราเอลทั้งหมดจะได้รับอภัยโทษ พร้อมกับคนต่างด้าวผู้อยู่ท่ามกลางเขาทั้งหลาย เพราะว่าพลเมืองทั้งหมดเกี่ยวพันกับความผิดนั้นอันเกิดขึ้นโดยไม่เจตนา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 27, 'ถ้าบุคคลคนหนึ่งคนใดกระทําผิดโดยไม่รู้ตัว ก็ให้ผู้นั้นเอาแพะเมียอายุขวบหนึ่งไปเป็นเครื่องบูชาไถ่บาป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 28, 'และให้ปุโรหิตกระทําการลบมลทินบาปต่อพระพักตร์พระเยโฮวาห์ให้บุคคลนั้น ผู้กระทําผิดเมื่อเขากระทําบาปโดยไม่รู้ตัว เพื่อทําการลบมลทินบาปเขาเสีย และเขาจะได้รับอภัยโทษ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 29, 'ให้เจ้ามีพระราชบัญญัติอย่างเดียวสําหรับผู้กระทําผิดโดยไม่รู้ตัว คือคนอิสราเอลผู้เป็นชาวพื้นเมืองและผู้เป็นคนต่างด้าวที่อยู่ท่ามกลางเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 30, 'แต่บุคคลที่บังอาจกระทําการใดๆโดยพลการ ไม่ว่าเขาจะเกิดในแผ่นดินนั้นหรือเป็นคนต่างด้าวก็ดี ผู้นั้นเหยียดหยามพระเยโฮวาห์ ผู้นั้นจะต้องถูกตัดขาดจากชนชาติของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 31, 'เพราะเขาได้สบประมาทพระดํารัสของพระเยโฮวาห์และละเมิดพระบัญญัติของพระองค์ ผู้นั้นจะต้องถูกตัดขาดอย่างสิ้นเชิง ให้เขารับโทษความชั่วช้าของตน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 32, 'ขณะเมื่อคนอิสราเอลอยู่ในถิ่นทุรกันดาร เขาพบคนหนึ่งไปเก็บฟืนในวันสะบาโต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 33, 'ผู้ที่พบเขาเก็บฟืนก็พาเขามาหาโมเสสและอาโรน และมาหาชุมนุมชนทั้งหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 34, 'เขาจึงจําคนนั้นไว้ เพราะยังไม่แจ้งว่าจะกระทําอย่างไรแก่เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 35, 'และพระเยโฮวาห์ตรัสกับโมเสสว่า “ชายผู้นั้นต้องถูกโทษถึงตายเป็นแน่ ชุมนุมชนทั้งหมดต้องเอาหินขว้างเขาที่นอกค่าย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 36, 'และชุมนุมชนทั้งหมดจึงพาเขามานอกค่าย และเอาหินขว้างเขาจนตาย ตามที่พระเยโฮวาห์ทรงบัญชาโมเสส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 37, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 38, '“จงพูดกับคนอิสราเอลและสั่งเขาให้ทําพู่ที่มุมชายเสื้อตลอดชั่วอายุของเขา ให้เอาด้ายสีฟ้าติดพู่ที่มุมทุกมุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 39, 'เพื่อเจ้าจะมองดูพู่นั้น และจดจําพระบัญญัติทั้งสิ้นของพระเยโฮวาห์ และปฏิบัติตาม เพื่อเจ้าจะไม่กระทําอะไรตามความพอใจพอตาของเจ้าซึ่งเจ้ามักหลงตามนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 40, 'เพื่อว่าเจ้าจะจดจําและกระทําตามบัญญัติทั้งสิ้นของเรา และเป็นคนบริสุทธิ์แด่พระเจ้าของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 41, 'เราคือพระเยโฮวาห์พระเจ้าของเจ้าผู้นําเจ้าออกจากแผ่นดินอียิปต์ เพื่อเป็นพระเจ้าของเจ้า เราคือพระเยโฮวาห์พระเจ้าของเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 1, 'โคราห์ บุตรชายอิสฮาร์ ผู้เป็นบุตรชายโคฮาท ผู้เป็นบุตรชายเลวี กับดาธานและอาบีรัม บุตรชายเอลีอับ กับโอนบุตรชายเปเลท บุตรชายรูเบน พาคนไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 2, 'และไปยืนต่อหน้าโมเสส พร้อมกับคนอิสราเอลจํานวนหนึ่ง เป็นเจ้านายของชุมนุมชนมีสองร้อยห้าสิบคนที่เลือกมาจากที่ประชุม เป็นคนมีชื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 3, 'และเขาทั้งหลายมาประชุมกันต่อโมเสสต่ออาโรน กล่าวแก่ท่านทั้งสองว่า “ท่านทําเกินเหตุไป เพราะว่าชุมนุมชนทั้งหมดก็บริสุทธิ์ทุกๆคน และพระเยโฮวาห์ทรงสถิตท่ามกลางเขา เหตุใดท่านจึงผยองขึ้นเหนือชุมนุมชนของพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 4, 'ครั้นโมเสสได้ยินก็ซบหน้าลงถึงดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 5, 'ท่านจึงพูดกับโคราห์และพรรคพวกทั้งหมดของเขาว่า “พรุ่งนี้เช้าพระเยโฮวาห์จะทรงสําแดงให้เห็นว่า ผู้ใดเป็นของพระองค์และใครเป็นคนบริสุทธิ์ และจะทรงให้ผู้นั้นเข้าใกล้พระองค์ ผู้ใดที่พระองค์ทรงเลือก พระองค์จะทรงให้เข้าไปใกล้พระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 6, 'จงกระทําอย่างนี้ ให้โคราห์และพรรคพวกทั้งหมดของเขานํากระถางไฟมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 7, 'จงเอาไฟใส่และใส่เครื่องหอมต่อพระพักตร์พระเยโฮวาห์ในวันพรุ่งนี้ ผู้ใดที่พระเยโฮวาห์ทรงเลือกก็จะเป็นคนบริสุทธิ์ บุตรชายของเลวีเอ๋ย ท่านทั้งหลายได้กระทําเกินเหตุไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 8, 'และโมเสสพูดกับโคราห์ว่า “พวกท่านผู้เป็นบุตรชายของเลวีจงฟัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 9, 'เป็นการเล็กน้อยสําหรับท่านอยู่หรือซึ่งพระเจ้าแห่งอิสราเอลได้แยกท่านออกจากชุมนุมชนอิสราเอล เพื่อนําท่านให้มาใกล้พระองค์ ให้ปฏิบัติงานในพลับพลาของพระเยโฮวาห์และยืนอยู่ต่อหน้าชุมนุมชนเพื่อปรนนิบัติเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 10, 'และพระองค์ทรงนําท่านมาใกล้พระองค์รวมทั้งพี่น้องทั้งสิ้นของท่าน คือลูกหลานของเลวี ท่านทั้งหลายแสวงหาตําแหน่งปุโรหิตด้วยหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 11, 'เพราะฉะนั้นที่ท่านและพรรคพวกทั้งหมดของท่านได้ประชุมกันก็เป็นการต่อสู้พระเยโฮวาห์ ส่วนอาโรนเป็นอะไรเล่าที่ท่านได้บ่นว่าเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 12, 'โมเสสใช้ให้ไปเรียกดาธานและอาบีรัมบุตรชายเอลีอับ เขาทั้งสองว่า “เราจะไม่ขึ้นไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 13, 'เป็นการเล็กน้อยอยู่หรือที่ท่านนําพวกเราจากแผ่นดินที่มีน้ํานมและน้ําผึ้งไหลบริบูรณ์ เพื่อจะฆ่าพวกเราเสียในถิ่นทุรกันดาร และท่านจะได้ตั้งตัวขึ้นเป็นเจ้านายเหนือพวกเราด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 14, 'ยิ่งกว่านั้นอีกท่านมิได้นําพวกเราเข้าไปยังแผ่นดินที่มีน้ํานมและน้ําผึ้งไหลบริบูรณ์ มิได้ให้พวกเรารับที่นาหรือสวนองุ่นเป็นมรดก ท่านจะควักตาคนเหล่านี้ออกเสียหรือ เราจะไม่ขึ้นไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 15, 'โมเสสโกรธมากและกราบทูลพระเยโฮวาห์ว่า “ขออย่าทรงโปรดปรานเครื่องบูชาของเขาเลย ข้าพระองค์มิได้เอาลาของเขามาสักตัวหนึ่ง และข้าพระองค์มิได้ทําอันตรายเขาสักคนเดียว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 16, 'และโมเสสพูดกับโคราห์ว่า “ตัวท่านและพรรคพวกทั้งหมดของท่านจงเข้าเฝ้าพระเยโฮวาห์ในวันพรุ่งนี้ ทั้งตัวท่าน พรรคพวกของท่านและอาโรน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 17, 'ให้ทุกคนนํากระถางไฟของตนไป ใส่เครื่องหอมในนั้น ให้ทุกคนนํากระถางไฟเข้าเฝ้าพระเยโฮวาห์ มีกระถางไฟสองร้อยห้าสิบด้วยกัน ตัวท่านด้วย และอาโรน ต่างจงเอากระถางไฟของตนไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 18, 'ดังนั้นทุกคนจึงนํากระถางไฟของเขา ต่างเอาไฟใส่และเอาเครื่องหอมใส่ และเข้าไปยืนอยู่ที่ประตูพลับพลาแห่งชุมนุมพร้อมกับโมเสสและอาโรน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 19, 'โคราห์ก็ร่วมชุมนุมชนทั้งหมดที่ประตูพลับพลาแห่งชุมนุมประจัญหน้าเขาทั้งสอง และสง่าราศีของพระเยโฮวาห์ก็ปรากฏต่อบรรดาชุมนุมชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 20, 'พระเยโฮวาห์ตรัสกับโมเสสและอาโรนว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 21, '“จงแยกตัวออกเสียจากชุมนุมชนนี้ เพื่อเราจะผลาญเขาเสียในพริบตาเดียว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 22, 'เขาทั้งสองซบหน้าลงถึงดินกราบทูลว่า “โอ ข้าแต่พระเจ้า ผู้ทรงเป็นพระเจ้าแห่งจิตวิญญาณของมนุษย์ทั้งสิ้น เมื่อคนเดียวกระทําผิด พระองค์จะทรงพระพิโรธแก่ชุมนุมชนทั้งหมดหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 23, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 24, '“จงกล่าวแก่ชุมนุมชนว่า จงออกไปให้ห่างจากเต็นท์ของโคราห์ ดาธาน และอาบีรัม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 25, 'แล้วโมเสสลุกขึ้นไปหาดาธานและอาบีรัมและพวกผู้ใหญ่แห่งอิสราเอลก็ตามท่านไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 26, 'โมเสสจึงกล่าวแก่ชุมนุมชนนั้นว่า “ท่านทั้งหลายออกไปเสียให้ห่างจากเต็นท์ของคนชั่วเหล่านี้ อย่าแตะต้องอะไรของเขาเลย เกลือกว่าท่านทั้งหลายจะต้องถูกกวาดไปกับบรรดาการบาปของเขาด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 27, 'ดังนั้นเขาทั้งหลายก็ออกไปให้ห่างจากเต็นท์ของโคราห์ ดาธาน และอาบีรัม และดาธานกับอาบีรัมออกมายืนอยู่ที่ประตูเต็นท์ของตน พร้อมกับภรรยา บุตรชายและลูกเล็กๆของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 28, 'และโมเสสพูดว่า “ดังนี้แหละท่านทั้งหลายจะได้ทราบว่า พระเยโฮวาห์ใช้ให้ข้ามากระทําการทั้งสิ้นนี้ ข้ามิได้กระทําตามอําเภอใจข้าเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 29, 'ถ้าคนเหล่านี้ตายอย่างคนธรรมดาทั้งปวง หรือเหตุการณ์อย่างคนธรรมดามาเยี่ยมเยียนเขา ก็หมายว่าพระเยโฮวาห์มิได้ทรงใช้ข้ามา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 30, 'แต่ถ้าพระเยโฮวาห์บันดาลอะไรใหม่เกิดขึ้นและแผ่นธรณีอ้าปากกลืนคนเหล่านี้เข้าไปพร้อมกับข้าวของทั้งหมดของเขา และเขาทั้งหลายลงไปสู่แดนคนตายทั้งเป็น ท่านทั้งหลายจงทราบเถิดว่า คนเหล่านี้ได้สบประมาทพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 31, 'ต่อมาเมื่อท่านกล่าวบรรดาคําเหล่านี้จบ แผ่นดินใต้ที่เขาเหล่านั้นยืนอยู่ก็แยกออก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 32, 'และแผ่นธรณีก็อ้าปากออกกลืนเขาทั้งหลายกับครอบครัว และบรรดาคนของโคราห์และข้าวของทั้งหมดของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 33, 'ดังนั้นเขาทั้งหลายพร้อมกับข้าวของทั้งหมดของเขาลงไปสู่แดนคนตายทั้งเป็น และแผ่นดินก็งับเขาไว้และเขาทั้งหลายก็พินาศเสียจากท่ามกลางที่ประชุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 34, 'อิสราเอลทั้งหมดที่อยู่รอบเขาได้ยินเสียงร้องของเขาก็หนีไป เพราะเขากล่าวว่า “เกลือกว่าธรณีจะกลืนเราเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 35, 'และไฟออกมาจากพระเยโฮวาห์ เผาผลาญคนทั้งสองร้อยห้าสิบที่ได้ถวายเครื่องหอมนั้นเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 36, 'แล้วพระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 37, '“จงบอกเอเลอาซาร์บุตรชายอาโรนปุโรหิต ให้เอากระถางไฟออกเสียจากเปลวเพลิง และเจ้าจงกระจายก้อนไฟออกห่างๆกัน เพราะกระถางไฟเหล่านั้นบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 38, 'คือกระถางไฟของคนเหล่านี้ที่ได้กระทําบาปจนถึงเสียชีวิตนั้น จงตีแผ่ทําเป็นแผ่นคลุมแท่นบูชา เพราะได้ถวายกระถางเหล่านั้นต่อพระพักตร์พระเยโฮวาห์ จึงเป็นสิ่งบริสุทธิ์ ดังนั้นสิ่งเหล่านี้จะเป็นหมายสําคัญแก่คนอิสราเอล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 39, 'ดังนั้นเอเลอาซาร์ปุโรหิตจึงนํากระถางไฟทองเหลือง ซึ่งผู้ที่ถูกไฟเผานําไปบูชา มาตีแผ่ออกเป็นแผ่นคลุมแท่นบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 40, 'ให้เป็นเครื่องเตือนใจคนอิสราเอล เพื่อว่าคนสามัญผู้ที่มิใช่เป็นเชื้อสายของอาโรน จะมิได้เข้าไปเผาเครื่องหอมถวายต่อพระพักตร์พระเยโฮวาห์ เกลือกว่าจะเป็นอย่างโคราห์และพรรคพวกของเขา ดังที่พระเยโฮวาห์ตรัสกับเอเลอาซาร์ทางโมเสส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 41, 'พอรุ่งขึ้นบรรดาชุมนุมชนอิสราเอลก็บ่นว่าโมเสสและอาโรนว่า “ท่านได้ประหารชีวิตคนของพระเยโฮวาห์เสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 42, 'ต่อมาเมื่อชุมนุมชนมาประชุมประจัญหน้าโมเสสและอาโรน เขาหันหน้ามาสู่พลับพลาแห่งชุมนุม และดูเถิด เมฆมาคลุมพลับพลานั้น และสง่าราศีของพระเยโฮวาห์ก็ปรากฏ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 43, 'โมเสสกับอาโรนจึงมาหน้าพลับพลาแห่งชุมนุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 44, 'และพระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 45, '“จงออกไปเสียจากท่ามกลางประชุมชนนี้ เพื่อเราจะผลาญเขาทั้งหลายเสียในพริบตาเดียว” และท่านทั้งสองก็ซบหน้าลงถึงดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 46, 'โมเสสพูดกับอาโรนว่า “จงเอากระถางไฟ เอาไฟจากแท่นบูชาใส่ไว้ แล้วใส่เครื่องหอมรีบนําไปที่ชุมนุมชน ทําการลบมลทินบาปของชุมนุมชนนั้นเสีย เพราะพระพิโรธพลุ่งออกมาจากพระเยโฮวาห์แล้ว ภัยพิบัติได้บังเกิดขึ้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 47, 'อาโรนจึงนํากระถางไฟดังที่โมเสสบอกวิ่งเข้าไปท่ามกลางที่ประชุม และดูเถิด ภัยพิบัติได้บังเกิดขึ้นแก่ประชาชนแล้ว และท่านได้ใส่เครื่องหอมและทําการลบมลทินบาปของประชาชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 48, 'ท่านได้ยืนอยู่ระหว่างคนตายกับคนเป็น และภัยพิบัตินั้นก็ถูกระงับแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 49, 'บรรดาคนที่ตายด้วยภัยพิบัติมีหนึ่งหมื่นสี่พันเจ็ดร้อยคน ไม่นับคนที่ตายด้วยเรื่องของโคราห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 50, 'เมื่อภัยพิบัติถูกระงับแล้ว อาโรนก็กลับไปหาโมเสสที่ประตูพลับพลาแห่งชุมนุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 1, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 2, '“จงพูดกับคนอิสราเอลและเอาไม้เท้ามาจากเขา เรือนบรรพบุรุษละอันจากประมุขทุกคนตามเรือนบรรพบุรุษ เป็นไม้เท้าสิบสองอัน เขียนชื่อชายเจ้าของไม้ไว้บนไม้เท้าทุกอัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 3, 'เขียนชื่อของอาโรนไว้บนไม้เท้าของคนเลวี เพราะจะมีไม้เท้าอันเดียวสําหรับหัวหน้าเรือนบรรพบุรุษหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 4, 'จงวางไม้เท้าเหล่านั้นไว้ในพลับพลาแห่งชุมนุม ต่อหน้าพระโอวาทที่ที่เราพบกับเจ้าทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 5, 'และต่อมาไม้เท้าของชายผู้ที่เราโปรดเลือกนั้นจะงอก เช่นนี้เราจะกระทําให้เสียงบ่นของคนอิสราเอล ซึ่งเขาบ่นต่อเจ้าสงบลงเสียจากเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 6, 'โมเสสจึงสั่งคนอิสราเอล และประมุขของท่านทุกคนก็มอบไม้เท้าแก่ท่านคนละอันตามเรือนบรรพบุรุษ เป็นไม้เท้าสิบสองอัน และไม้เท้าของอาโรนก็อยู่ในไม้เท้าเหล่านั้นด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 7, 'และโมเสสวางไม้เท้าเหล่านั้นต่อพระพักตร์พระเยโฮวาห์ที่ในพลับพลาพระโอวาท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 8, 'อยู่มาวันรุ่งขึ้นโมเสสได้เข้าไปในพลับพลาพระโอวาท ดูเถิด ไม้เท้าของอาโรนสําหรับวงศ์วานเลวีได้งอก มีดอกตูมและดอกบาน และเกิดผลอัลมันด์สุกบ้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 9, 'แล้วโมเสสนําไม้เท้าทั้งหมดจากที่ตรงพระพักตร์พระเยโฮวาห์มายังคนอิสราเอลทั้งหมด เขาได้ตรวจดู และทุกคนก็นําไม้เท้าของตนไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 10, 'พระเยโฮวาห์ตรัสกับโมเสสว่า “จงนําไม้เท้าของอาโรนกลับไปวางไว้ต่อหน้าพระโอวาท เก็บไว้เป็นหมายสําคัญสําหรับเตือนพวกกบฏ เพื่อเจ้าจะให้เขาทั้งหลายยุติการบ่นว่าเรา เพื่อเขาจะไม่ต้องตาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 11, 'โมเสสก็กระทําเช่นนี้ พระเยโฮวาห์ตรัสสั่งท่านอย่างไร ท่านก็กระทําอย่างนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 12, 'และคนอิสราเอลพูดกับโมเสสว่า “ดูเถิด เราพินาศ เราถึงหายนะ เราถึงหายนะหมดแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 13, 'ผู้ใดที่มาใกล้พลับพลาแห่งพระเยโฮวาห์ต้องตาย เราจะต้องตายหมดหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 1, 'ดังนั้นพระเยโฮวาห์ตรัสกับอาโรนว่า “เจ้าและบุตรชายของเจ้า และวงศ์วานบิดาของเจ้าจะต้องรับโทษความชั่วช้าเนื่องด้วยสถานบริสุทธิ์ ทั้งเจ้าและบุตรชายของเจ้าจะต้องรับโทษความชั่วช้าเนื่องด้วยหน้าที่ปุโรหิตของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 2, 'และจงนําพี่น้องของเจ้ามาใกล้เจ้า ซึ่งเป็นตระกูลเลวี ตระกูลบิดาของเจ้า เพื่อเขาจะสมทบกับเจ้า และปรนนิบัติเจ้า ขณะที่เจ้าและบุตรชายปรนนิบัติอยู่ต่อหน้าพลับพลาพระโอวาท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 3, 'เขาทั้งหลายจะคอยรับใช้เจ้า และรับใช้บรรดาหน้าที่ต่างๆของพลับพลา แต่อย่าให้เข้าใกล้เครื่องใช้ของสถานบริสุทธิ์หรือแท่นบูชา เกลือกว่าเขาทั้งหลายและเจ้าจะต้องตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 4, 'เขาทั้งหลายจะสมทบกับพวกเจ้า และคอยรับใช้อยู่ที่พลับพลาแห่งชุมนุม ในงานปรนนิบัติทั้งสิ้นของพลับพลา และอย่าให้ผู้อื่นใดมาใกล้เจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 5, 'พวกเจ้าต้องคอยรับใช้ในหน้าที่ของสถานบริสุทธิ์ และหน้าที่ของแท่นบูชา เพื่อพระพิโรธจะไม่เกิดขึ้นแก่คนอิสราเอลอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 6, 'และดูเถิด เราได้เลือกคนเลวีพี่น้องของเจ้าออกจากคนอิสราเอล เป็นของประทานแก่เจ้าถวายแด่พระเยโฮวาห์ เพื่อให้ปฏิบัติงานของพลับพลาแห่งชุมนุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 7, 'ทั้งเจ้าและบุตรชายจงคอยรับใช้ในหน้าที่ปุโรหิต เพื่องานทุกอย่างที่เกี่ยวข้องกับแท่นบูชาและสิ่งที่อยู่ภายในม่าน เจ้าต้องอยู่ปฏิบัติงาน เราให้ตําแหน่งปุโรหิตแก่เจ้าเป็นของประทานสําหรับงานปฏิบัติ และผู้ใดอื่นที่เข้ามาใกล้ต้องให้ถึงแก่ความตาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 8, 'แล้วพระเยโฮวาห์ตรัสกับอาโรนว่า “ดูเถิด เราได้ให้เครื่องบูชาของเราส่วนหนึ่งแก่เจ้า คือบรรดาของถวายของคนอิสราเอล เราให้แก่เจ้าส่วนหนึ่งและแก่ลูกหลานของเจ้าเป็นกฎถาวรเพราะเหตุพวกเจ้าได้รับการเจิมแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 9, 'ในบรรดาของบริสุทธิ์ที่สุดส่วนซึ่งไม่ได้เผาไฟที่เป็นของของเจ้ามีดังนี้ บรรดาของถวายของเขา บรรดาธัญญบูชาของเขา บรรดาเครื่องบูชาไถ่บาปของเขา บรรดาเครื่องบูชาไถ่การละเมิดของเขา ซึ่งเขาถวายแก่เรา จะเป็นของบริสุทธิ์ที่สุดแก่เจ้าและแก่ลูกหลานของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 10, 'เจ้าจงรับประทานสิ่งเหล่านี้ในที่บริสุทธิ์ที่สุด ผู้ชายทุกคนรับประทานได้ เป็นของบริสุทธิ์แก่เจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 11, 'สิ่งต่อไปนี้ก็เป็นของเจ้าด้วย คือของให้ที่เขาถวาย บรรดาเครื่องบูชาแกว่งถวายของคนอิสราเอล เราได้ให้ไว้แก่เจ้าและแก่บุตรชายหญิงซึ่งอยู่กับเจ้าเป็นกฎเกณฑ์ถาวร ทุกคนที่สะอาดที่อยู่ในครอบครัวของเจ้ารับประทานได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 12, 'น้ํามันที่ดีที่สุดทั้งหมด และน้ําองุ่นที่ดีที่สุด และเมล็ดพืชทั้งหมด และผลรุ่นแรกที่เขาถวายแด่พระเยโฮวาห์ เราให้แก่เจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 13, 'ผลสุกรุ่นแรกของของทุกอย่างซึ่งอยู่ในแผ่นดิน ที่เขานํามาถวายพระเยโฮวาห์ จะเป็นของเจ้า ทุกคนที่สะอาดอยู่ในครอบครัวของเจ้ารับประทานได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 14, 'บรรดาของมอบถวายในอิสราเอลจะเป็นของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 15, 'บรรดาเนื้อหนังที่เบิกครรภ์ ไม่ว่ามนุษย์หรือสัตว์ ซึ่งเขาถวายแด่พระเยโฮวาห์จะเป็นของเจ้า แต่อย่างไรก็ตาม บุตรหัวปีของมนุษย์เจ้าจะต้องไถ่ไว้ เจ้าต้องไถ่ลูกหัวปีของบรรดาสัตว์ทั้งปวงที่มลทินด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 16, 'และค่าไถ่ พออายุได้หนึ่งเดือนเจ้าก็ต้องไถ่ ให้เจ้ากําหนดว่าเป็นเงินห้าเชเขลตามเชเขลของสถานบริสุทธิ์ ซึ่งเป็นยี่สิบเก-ราห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 17, 'แต่ลูกหัวปีของวัว หรือลูกหัวปีของแกะ หรือลูกหัวปีของแพะ เจ้าไม่ต้องไถ่เพราะเป็นของบริสุทธิ์ เจ้าจงเอาเลือดของมันพรมบนแท่นบูชา และเอาไขมันของมันเผาเป็นเครื่องบูชาด้วยไฟ ให้เป็นกลิ่นที่พอพระทัยแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 18, 'แต่เนื้อของมันจะเป็นของเจ้า เช่นเดียวกับเนื้ออกที่แกว่งถวายหรือเนื้อโคนขาขวาเป็นของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 19, 'บรรดาเครื่องบูชาบริสุทธิ์ที่คนอิสราเอลมอบถวายแด่พระเยโฮวาห์ เราให้แก่เจ้าและแก่บุตรชายหญิงซึ่งอยู่กับเจ้า เป็นกฎเกณฑ์ถาวร เป็นพันธสัญญาเกลือเป็นนิตย์ต่อพระพักตร์พระเยโฮวาห์สําหรับเจ้า และเชื้อสายของเจ้าด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 20, 'และพระเยโฮวาห์ตรัสกับอาโรนว่า “เจ้าจะไม่ได้รับมรดกในแผ่นดินของเขา ทั้งเจ้าจะไม่มีส่วนอันใดกับเขาเลย เราเป็นส่วนแบ่งของเจ้าและเป็นมรดกของเจ้าท่ามกลางคนอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 21, 'ดูเถิด เราให้บรรดาสิบชักหนึ่งในอิสราเอลแก่คนเลวีเป็นมรดก เป็นค่าตอบแทนงานที่เขาปฏิบัติ คืองานปฏิบัติที่พลับพลาแห่งชุมนุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 22, 'ตั้งแต่นี้ต่อไปคนอิสราเอลจะมิได้เข้ามาใกล้พลับพลาแห่งชุมนุม เกลือกว่าเขาจะรับโทษบาปและจะต้องตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 23, 'แต่คนเลวีจะต้องปฏิบัติงานของพลับพลาแห่งชุมนุม และเขาจะต้องรับโทษความชั่วช้าของเขา จะเป็นกฎเกณฑ์ถาวรตลอดชั่วอายุของเจ้า เขาจะไม่มีส่วนมรดกท่ามกลางคนอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 24, 'เพราะว่าส่วนสิบชักหนึ่งของคนอิสราเอล ซึ่งนํามาถวายแด่พระเยโฮวาห์ เราได้ให้แก่คนเลวีเป็นมรดก เพราะฉะนั้นเราจึงได้บอกเขาว่า ‘เขาจะไม่มีส่วนมรดกท่ามกลางคนอิสราเอล’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 25, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 26, '“ยิ่งกว่านั้น เจ้าจงกล่าวแก่คนเลวีว่า ‘เมื่อพวกเจ้ารับสิบชักหนึ่งจากคนอิสราเอล ซึ่งเราให้แก่เจ้าอันมาจากเขาเป็นมรดกของเจ้านั้น เจ้าจงนําสิบชักหนึ่งของสิบชักหนึ่งที่เจ้าได้มานั้นถวายแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 27, 'และส่วนถวายของเจ้านั้นจะนับเหมือนหนึ่งเป็นพืชที่ได้มาจากลานนวดข้าว และเหมือนส่วนที่เต็มเปี่ยมจากบ่อย่ําองุ่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 28, 'เพราะฉะนั้นเจ้าต้องนําของบูชาจากสิบชักหนึ่งทั้งสิ้นของเจ้าถวายแด่พระเยโฮวาห์ คือสิบชักหนึ่งที่เจ้ารับจากคนอิสราเอลนั้น จากส่วนได้นี้พวกเจ้าจงมอบของถวายแด่พระเยโฮวาห์แก่อาโรนปุโรหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 29, 'จากบรรดาของที่พวกเจ้าได้รับ เจ้าจงนําเครื่องถวายทุกสิ่งที่ต้องถวายแด่พระเยโฮวาห์ จากบรรดาของดีที่สุดนั้นคือส่วนของที่บริสุทธิ์’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 30, 'ฉะนั้นเจ้าจงพูดกับเขาว่า ‘เมื่อเจ้าได้ถวายส่วนที่ดีที่สุดแล้ว ให้คนเลวีนับส่วนที่เหลืออยู่เป็นเหมือนหนึ่งพืชที่ได้มาจากลานนวดข้าวและเป็นผลได้จากบ่อย่ําองุ่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 31, 'และเจ้าจะรับประทานส่วนนั้น ณ ที่ใดๆก็ได้ ทั้งตัวเจ้าและครอบครัวของเจ้า เพราะว่าเป็นรางวัลตอบแทนงานปฏิบัติของเจ้าในพลับพลาแห่งชุมนุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 32, 'เมื่อเจ้าได้ถวายส่วนที่ดีที่สุดแล้วเจ้าจะหามีโทษบาปโดยของถวายนั้นไม่ และเจ้าอย่าทําสิ่งบริสุทธิ์ของคนอิสราเอลให้มลทินเกลือกว่าเจ้าจะต้องตาย’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 1, 'พระเยโฮวาห์ตรัสกับโมเสสและอาโรนว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 2, '“ต่อไปนี้เป็นกฎพระราชบัญญัติซึ่งพระเยโฮวาห์ได้ทรงบัญชาว่า จงบอกคนอิสราเอลให้นําวัวตัวเมียสีแดงไม่พิการซึ่งไม่มีตําหนิ และยังไม่เคยเข้าเทียมแอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 3, 'และเจ้าจงให้วัวนั้นแก่เอเลอาซาร์ปุโรหิต และให้เอาวัวนั้นไปนอกค่ายฆ่าเสียต่อหน้าเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 4, 'และเอเลอาซาร์ปุโรหิตจะเอานิ้วมือจุ่มเลือดวัวพรมที่ข้างหน้าพลับพลาแห่งชุมนุมเจ็ดครั้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 5, 'และให้มีคนเผาวัวตัวเมียนั้นเสียในสายตาของเขา คือเขาจะต้องเผาหนัง เนื้อ และเลือด กับมูลของมันเสียให้หมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 6, 'และปุโรหิตจะเอาไม้สนสีดาร์ ต้นหุสบกับด้ายสีแดงโยนเข้าไปในไฟที่เผาวัวตัวเมียนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 7, 'แล้วปุโรหิตจะซักเสื้อผ้าของตน และชําระร่างกายเสียในน้ํา ภายหลังจึงเข้าไปในค่ายและปุโรหิตนั้นจึงเป็นมลทินอยู่จนถึงเวลาเย็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 8, 'ผู้ใดที่ทําการเผาวัวตัวเมียต้องซักเสื้อผ้าและชําระร่างกายของตนเสียในน้ํา และเขาจะเป็นมลทินอยู่จนถึงเวลาเย็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 9, 'ให้ชายคนที่สะอาดเก็บขี้เถ้าวัวตัวเมียนั้น นําไปไว้นอกค่ายในที่สะอาด และให้เก็บขี้เถ้านั้นไว้ทําเป็นน้ําแห่งการแยกตั้งไว้สําหรับที่ชุมนุมชนอิสราเอลเพื่อเป็นการชําระล้างบาปออกเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 10, 'และคนที่เก็บขี้เถ้าของวัวตัวเมียต้องซักเสื้อผ้าของตน และเขาจะเป็นมลทินอยู่จนถึงเวลาเย็น จะเป็นอย่างนี้แก่คนอิสราเอล และแก่คนต่างด้าวผู้อาศัยอยู่ท่ามกลางเขา เป็นกฎเกณฑ์ถาวร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 11, 'ผู้ที่แตะต้องศพของผู้ใดก็ตามต้องเป็นมลทินอยู่เจ็ดวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 12, 'ในวันที่สามเขาต้องชําระตัวด้วยน้ํา แล้วในวันที่เจ็ดเขาจะสะอาด แต่ถ้าเขาไม่ชําระตัวในวันที่สาม ในวันที่เจ็ดเขาจะสะอาดไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 13, 'ผู้ใดก็ตามแตะต้องคนตาย คือร่างกายของคนที่ตายแล้ว และมิได้ชําระตนให้บริสุทธิ์ ผู้นั้นก็กระทําให้พลับพลาของพระเยโฮวาห์มีมลทิน คนนั้นจะต้องถูกตัดขาดจากอิสราเอล เพราะน้ําแห่งการแยกตั้งไว้ไม่ได้พรมถูกตัวเขา เขาจะเป็นมลทิน มลทินยังค้างอยู่ที่เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 14, 'ต่อไปนี้เป็นพระราชบัญญัติเรื่องคนตายในเต็นท์ ทุกคนที่เข้ามาในเต็นท์ และสารพัดที่อยู่ในเต็นท์ จะเป็นมลทินไปเจ็ดวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 15, 'ภาชนะทุกลูกที่ไม่มีฝาปิดต้องเป็นมลทิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 16, 'คนใดที่อยู่ในพื้นทุ่งไปแตะต้องคนที่ถูกดาบตาย หรือแตะต้องศพ หรือกระดูกคน หรือหลุมศพ จะเป็นมลทินไปเจ็ดวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 17, 'สําหรับคนที่เป็นมลทินนี้ จงเอาขี้เถ้าจากการเผาวัวตัวเมียในการบูชาไถ่บาป และเอาน้ําที่ไหลเติมเข้าไปปนในภาชนะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 18, 'ให้คนสะอาดเอากิ่งหุสบจุ่มน้ํานั้นประพรมที่เต็นท์และเครื่องใช้สอยทั้งสิ้น และบนตัวคนที่อยู่ที่นั่นและบนตัวคนที่แตะต้องกระดูกหรือคนถูกฆ่าหรือคนตายหรือหลุมศพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 19, 'ให้คนสะอาดประพรมคนที่เป็นมลทินในวันที่สามและวันที่เจ็ด อย่างนี้พอวันที่เจ็ดเขาจะทําให้คนนั้นสะอาด และเขาต้องซักเสื้อผ้าและอาบน้ํา พอถึงเวลาเย็นเขาจะสะอาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 20, 'แต่คนที่เป็นมลทินและไม่ชําระตัวให้บริสุทธิ์ คนนั้นจะต้องถูกตัดขาดจากท่ามกลางที่ชุมนุม เพราะเขาได้กระทําให้สถานบริสุทธิ์ของพระเยโฮวาห์เป็นมลทิน คือว่าน้ําแห่งการแยกตั้งไว้ไม่ได้พรมถูกตัวเขา เขาจึงเป็นมลทิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 21, 'และให้เป็นกฎเกณฑ์แก่พวกเขาอยู่เนืองนิตย์ ผู้ที่ประพรมน้ําแห่งการแยกตั้งไว้จะต้องซักเสื้อผ้าของตน และผู้ที่แตะต้องน้ําแห่งการแยกตั้งไว้จะเป็นมลทินจนถึงเวลาเย็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 22, 'และสิ่งใดที่ผู้เป็นมลทินแตะต้อง สิ่งนั้นจะเป็นมลทิน และผู้ที่แตะต้องสิ่งนั้นจะเป็นมลทินจนถึงเวลาเย็น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 1, 'ชุมนุมชนทั้งหมดของคนอิสราเอลเข้ามาในถิ่นทุรกันดารศินในเดือนที่หนึ่ง ประชาชนพักอยู่ในคาเดช มิเรียมก็สิ้นชีวิตและฝังไว้ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 2, 'ครั้งนั้นชุมนุมชนไม่มีน้ํา เขาประชุมกันว่าโมเสสและอาโรน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 3, 'ประชาชนตัดพ้อต่อว่าโมเสสว่า “เมื่อพี่น้องเราตายต่อพระพักตร์พระเยโฮวาห์นั้น เราตายเสียด้วยก็ดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 4, 'ท่านพาชุมนุมชนของพระเยโฮวาห์มาในถิ่นทุรกันดารนี้ให้ตายเสียที่นี่ทั้งตัวเราและสัตว์ของเราทําไม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 5, 'และทําไมท่านจึงให้เราออกจากอียิปต์ นําเรามายังที่เลวทรามนี้ เป็นที่ซึ่งไม่มีพืช ไม่มีมะเดื่อ องุ่นหรือทับทิม และไม่มีน้ําดื่ม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 6, 'แล้วโมเสสและอาโรนออกจากที่ประชุมไปที่ประตูพลับพลาแห่งชุมนุมและซบหน้าลง และสง่าราศีของพระเยโฮวาห์ปรากฏแก่เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 7, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 8, '“จงเอาไม้เท้าและเรียกประชุมชุมนุมชน ทั้งเจ้าและอาโรนพี่ชายของเจ้า และบอกหินต่อหน้าต่อตาประชาชนให้หินหลั่งน้ํา ดังนั้นเจ้าจะเอาน้ําออกจากหินให้เขา ดังนั้นแหละเจ้าจะให้น้ําแก่ชุมนุมชนและสัตว์ดื่ม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 9, 'โมเสสก็นําไม้เท้าไปจากหน้าพระพักตร์พระเยโฮวาห์ ดังที่พระองค์ทรงบัญชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 10, 'โมเสสกับอาโรนก็เรียกชุมนุมชนให้ไปพร้อมกันที่หิน โมเสสกล่าวแก่เขาว่า “เจ้าผู้กบฏจงฟัง ณ บัดนี้จะให้เราเอาน้ําออกจากหินนี้ให้พวกเจ้าดื่มหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 11, 'และโมเสสก็ยกมือขึ้นตีหินนั้นสองครั้งด้วยไม้เท้า และน้ําก็ไหลออกมามากมาย ชุมนุมชนและสัตว์ของเขาก็ได้ดื่มน้ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 12, 'พระเยโฮวาห์ตรัสกับโมเสสและอาโรนว่า “เพราะเจ้ามิได้เชื่อเราจึงมิได้กระทําให้เราเป็นที่บริสุทธิ์ในสายตาของคนอิสราเอล เพราะฉะนั้นเจ้าจึงจะมิได้นําชุมนุมชนนี้เข้าไปในแผ่นดินซึ่งเราได้ให้แก่เขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 13, 'น้ํานั้นคือน้ําเมรีบาห์ เพราะว่าคนอิสราเอลได้ต่อว่าพระเยโฮวาห์ และพระองค์ทรงสําแดงความบริสุทธิ์ท่ามกลางเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 14, 'โมเสสได้ส่งผู้สื่อสารจากคาเดชไปถึงกษัตริย์แห่งเอโดมว่า “พี่น้องซึ่งเป็นคนอิสราเอลกล่าวดังนี้ว่า ท่านก็ทราบถึงบรรดาความทุกข์ยากที่เกิดขึ้นแก่เราแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 15, 'ว่าบรรพบุรุษของเราลงไปยังอียิปต์ และเราอยู่ในอียิปต์ช้านาน และชาวอียิปต์ได้ข่มเหงเราและบรรพบุรุษของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 16, 'และเมื่อเราร้องทูลพระเยโฮวาห์ พระองค์ทรงสดับเสียงของเรา และได้ส่งทูตสวรรค์องค์หนึ่งนําเราออกจากอียิปต์ และดูเถิด เรามาอยู่ในคาเดชเป็นเมืองที่อยู่ชิดพรมแดนของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 17, 'ขอให้เรายกผ่านเขตแดนของท่าน เราจะไม่ผ่านไร่นาหรือสวนองุ่นของท่าน เราจะไม่ดื่มน้ําจากบ่อ เราจะเดินไปตามทางหลวง เราจะไม่หันไปทางขวามือหรือทางซ้ายมือ จนกว่าเราจะผ่านพ้นเขตแดนของท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 18, 'แต่เอโดมกล่าวแก่ท่านว่า “ท่านจะยกผ่านไปไม่ได้เกลือกว่าเราจะยกออกมาสู้ท่านด้วยดาบ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 19, 'และคนอิสราเอลพูดกับกษัตริย์แห่งเอโดมว่า “เราจะขึ้นไปตามทางหลวง ถ้าเราดื่มน้ําของท่านไม่ว่าตัวเราหรือสัตว์ เราจะชําระเงินให้ ขอให้เราเดินผ่านไป เราไม่ต้องการอะไรอีก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 20, 'แต่ท่านตอบว่า “เจ้าจะยกผ่านไปไม่ได้” แล้วเอโดมก็ยกพลเป็นอันมากมาต่อสู้เขาทั้งหลายด้วยมืออันเข้มแข็ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 21, 'เช่นนี้แหละเอโดมปฏิเสธไม่ให้อิสราเอลยกผ่านพรมแดนของท่าน ดังนั้นอิสราเอลจึงหันไปจากท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 22, 'และชุมนุมชนอิสราเอลทั้งหมดเดินทางจากคาเดชมาถึงภูเขาโฮร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 23, 'ที่ภูเขาโฮร์นี้พระเยโฮวาห์ตรัสกับโมเสสและอาโรนริมเขตแดนแผ่นดินเอโดมว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 24, '“อาโรนจะต้องถูกรวบไปอยู่กับพวกของเขา เพราะเขาจะไม่ได้เข้าไปในแผ่นดินซึ่งเรายกให้แก่คนอิสราเอล เพราะเจ้าทั้งสองกบฏต่อคําสั่งของเราที่น้ําเมรีบาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 25, 'จงนําอาโรนและเอเลอาซาร์บุตรชายของเขา นําเขาขึ้นมาบนภูเขาโฮร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 26, 'จงถอดเสื้อของอาโรนสวมให้แก่เอเลอาซาร์บุตรชายของเขา และอาโรนจะถูกรวบไปอยู่กับพวกของเขา เขาจะตายที่นั่น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 27, 'โมเสสก็กระทําตามที่พระเยโฮวาห์ทรงบัญชา และพวกท่านก็ขึ้นไปบนภูเขาโฮร์ท่ามกลางสายตาของชุมนุมชนทั้งหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 28, 'และโมเสสถอดเสื้อผ้าของอาโรน และสวมให้แก่เอเลอาซาร์บุตรชายของเขา และอาโรนก็สิ้นชีวิตอยู่ที่ยอดภูเขานั้น แล้วโมเสสและเอเลอาซาร์ลงมาจากภูเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 29, 'เมื่อบรรดาชุมนุมชนเห็นว่าอาโรนสิ้นชีวิตเสียแล้ว วงศ์วานอิสราเอลทั้งหมดก็ร้องไห้ไว้ทุกข์ให้อาโรนอยู่สามสิบวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 1, 'เมื่อกษัตริย์เมืองอาราด ชาวคานาอันผู้อยู่ทางภาคใต้ ได้ยินว่าอิสราเอลกําลังยกมาตามทางที่พวกสอดแนมใช้นั้น ท่านต่อสู้กับคนอิสราเอลและจับไปเป็นเชลยได้บ้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 2, 'และคนอิสราเอลปฏิญาณไว้กับพระเยโฮวาห์ว่า “ถ้าพระองค์จะทรงมอบชนชาตินี้ไว้ในมือข้าพระองค์แน่แล้ว ข้าพระองค์จะทําลายบ้านเมืองเขาเสียให้สิ้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 3, 'และพระเยโฮวาห์ทรงสดับเสียงของคนอิสราเอลและมอบชาวคานาอันไว้ เขาก็ทําลายชาวคานาอันและบ้านเมืองของเขาเสียสิ้น จึงได้เรียกชื่อตําบลนั้นว่าโฮรมาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 4, 'เขาทั้งหลายออกเดินจากภูเขาโฮร์ตามทางที่ไปทะเลแดงเพื่อจะอ้อมแผ่นดินเอโดม ประชาชนท้อใจมากเพราะเหตุหนทาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 5, 'และประชาชนก็บ่นว่าพระเจ้าและว่าโมเสสว่า “ทําไมพาเราออกจากอียิปต์มาตายในถิ่นทุรกันดาร เพราะไม่มีอาหารและไม่มีน้ํา เราเบื่ออาหารอันไร้ค่านี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 6, 'และพระเยโฮวาห์ก็ทรงให้งูแมวเซามาในหมู่ประชาชน งูก็กัดประชาชน และคนอิสราเอลตายมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 7, 'และประชาชนมาหาโมเสสกล่าวว่า “เราทั้งหลายได้กระทําบาปเพราะเราทั้งหลายได้บ่นว่าพระเยโฮวาห์และบ่นว่าท่าน ขอทูลแด่พระเยโฮวาห์ ขอพระองค์ทรงนํางูไปจากเราเสีย” ดังนั้นโมเสสจึงอธิษฐานเพื่อประชาชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 8, 'และพระเยโฮวาห์ตรัสกับโมเสสว่า “จงทํางูแมวเซาตัวหนึ่งติดไว้ที่เสา และต่อมาทุกคนที่ถูกงูกัดเมื่อเขามองดู เขาจะยังมีชีวิตอยู่ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 9, 'ดังนั้นโมเสสจึงทํางูทองเหลืองตัวหนึ่ง และติดไว้ที่เสา แล้วต่อมาถ้างูกัดคนใด ถ้าเขามองดูงูทองเหลืองนั้น เขาก็มีชีวิตอยู่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 10, 'และคนอิสราเอลก็ยกออกเดินไปตั้งค่ายอยู่ที่โอโบท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 11, 'และเขาออกเดินจากโอโบทไปตั้งค่ายอยู่ที่อิเยอาบาริม อยู่ในถิ่นทุรกันดาร ตรงข้ามโมอับ ทางทิศตะวันขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 12, 'เขายกออกจากที่นั่นมาตั้งค่ายอยู่ที่หุบเขาเศเรด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 13, 'เขายกออกจากที่นั่นไปตั้งอยู่ฟากแม่น้ําอารโนนข้างโน้น ซึ่งอยู่ในถิ่นทุรกันดารที่ยืดมาจากพรมแดนของคนอาโมไรต์ เพราะว่าแม่น้ําอารโนนเป็นพรมแดนของโมอับ ระหว่างโมอับกับคนอาโมไรต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 14, 'ดังนั้นในหนังสือสงครามของพระเยโฮวาห์จึงมีว่า “พระองค์ทรงชนะที่ทะเลแดง และลุ่มแม่น้ําอารโนน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 15, 'และที่เชิงลาดของที่ลุ่มเหล่านั้นซึ่งยืดไปจนถึงที่ตั้งเมืองอาร์ และพาดพิงไปถึงพรมแดนโมอับ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 16, 'จากที่นั่นเขาออกเดินต่อไปถึงเมืองเบเออร์ ซึ่งเป็นบ่อน้ําที่พระเยโฮวาห์ตรัสกับโมเสสว่า “จงรวบรวมประชาชนเข้าด้วยกัน เราจะให้น้ําแก่เขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 17, 'แล้วอิสราเอลจึงร้องเพลงนี้ว่า “โอ บ่อน้ําเอ๋ย จงมีน้ําพลุ่งขึ้นมา ให้เรามาร้องเพลงกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 18, 'เป็นบ่อน้ําที่เจ้านายได้ขุดไว้ เป็นบ่อที่ขุนนางของประชาชนเจาะไว้ ด้วยคทาและไม้เท้าของผู้ทรงตั้งพระราชบัญญัติ” และจากถิ่นทุรกันดารนั้นไป เขาก็มาถึงมัทธานาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 19, 'และจากมัทธานาห์ถึงตําบลนาหะลีเอล และจากนาหะลีเอลถึงตําบลบาโมท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 20, 'และจากบาโมทถึงหุบเขาซึ่งอยู่ในท้องถิ่นโมอับข้างยอดเขาปิสกาห์ซึ่งมองลงมาเห็นเยชิโมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 21, 'แล้วอิสราเอลส่งผู้สื่อสารไปหาสิโหนกษัตริย์คนอาโมไรต์กล่าวว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 22, '“ขอให้ข้าพเจ้าผ่านแผ่นดินของท่าน พวกเราจะไม่เลี้ยวเข้าไปในนาหรือในสวนองุ่น เราจะไม่ดื่มน้ําจากบ่อ เราจะเดินไปตามทางหลวงจนเราได้ผ่านพรมแดนเมืองของท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 23, 'แต่สิโหนไม่ยอมให้อิสราเอลยกผ่านพรมแดนของท่าน สิโหนรวบรวมพลทั้งหมดของท่านยกออกสู้รบกับอิสราเอลในถิ่นทุรกันดาร และท่านมาถึงยาฮาสรบกับอิสราเอลที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 24, 'และอิสราเอลได้ประหารท่านเสียด้วยคมดาบ ยึดเอาแผ่นดินของท่านจากแม่น้ําอารโนนจนถึงแถวยับบอก ไกลไปจนถึงแดนคนอัมโมนเพราะว่าพรมแดนของคนอัมโมนเข้มแข็ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 25, 'และอิสราเอลยึดเมืองเหล่านี้ทั้งหมด และอิสราเอลเข้าตั้งอยู่ในบรรดาหัวเมืองของคนอาโมไรต์ ในเฮชโบน และตามชนบททั้งหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 26, 'เพราะว่าเฮชโบนเป็นเมืองหลวงของสิโหนกษัตริย์ของคนอาโมไรต์ ผู้ที่ต่อสู้กับกษัตริย์ชาวโมอับองค์ก่อน และยึดได้แผ่นดินของท่านทั้งสิ้นไกลไปถึงแม่น้ําอารโนน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 27, 'เพราะฉะนั้นนักร้องบทสุภาษิตจึงร้องว่า “มาที่เฮชโบน ให้สร้างและสถาปนาเมืองแห่งสิโหนขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 28, 'เพราะว่ามีไฟออกไปจากเฮชโบน มีเปลวไฟออกไปจากเมืองแห่งสิโหน ได้ทําลายเมืองอาร์ของโมอับ เจ้าของแห่งปูชนียสถานสูงของแม่น้ําอารโนน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 29, 'โมอับเอ๋ย วิบัติแก่เจ้า โอ ชนชาติแห่งพระเคโมชเอ๋ย เจ้าต้องพินาศ พระเคโมชได้มอบทั้งบุตรชายของตนที่หลบภัยแล้วกับบุตรสาวของตน ให้เป็นเชลยของสิโหนกษัตริย์คนอาโมไรต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 30, 'เราทั้งหลายได้ยิงเขาทั้งปวง เฮชโบนพินาศจนถึงดีโบน เราได้กวาดล้างถึงโนฟาห์เสียคือถึงเมเดบา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 31, 'ดังนั้นอิสราเอลได้อาศัยอยู่ในแผ่นดินคนอาโมไรต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 32, 'และโมเสสใช้คนไปสอดแนมเมืองยาเซอร์ และเขาทั้งหลายได้ยึดชนบทของเมืองนั้น และขับไล่คนอาโมไรต์ที่อยู่ที่นั่นเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 33, 'แล้วเขาก็เลี้ยวยกเดินไปตามทางเมืองบาชาน และโอกกษัตริย์เมืองบาชานก็ออกมา ทั้งตัวท่านกับพลไพร่ทั้งสิ้นของท่าน เพื่อสู้รบกับเขาที่เอเดรอี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 34, 'แต่พระเยโฮวาห์ตรัสกับโมเสสว่า “อย่ากลัวเขาเลย เพราะเราได้มอบเขาไว้ในมือของเจ้าแล้ว ทั้งบรรดาพลไพร่ของเขา และแผ่นดินของเขา และเจ้าจะกระทําแก่เขาอย่างเจ้าได้กระทําแก่สิโหนกษัตริย์คนอาโมไรต์ผู้อยู่ที่เฮชโบน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 35, 'ดังนั้นเขาทั้งหลายจึงฆ่าโอกและโอรสของท่านเสีย ทั้งประชาชนทั้งสิ้นของท่าน ไม่มีเหลือให้ท่านสักคนเดียว และเขาทั้งหลายก็เข้ายึดแผ่นดินของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 1, 'แล้วคนอิสราเอลก็ยกออกไปตั้งค่ายอยู่ ณ ที่ราบโมอับซึ่งอยู่ฟากแม่น้ําจอร์แดนข้างนี้ใกล้เมืองเยรีโค');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 2, 'ฝ่ายบาลาคบุตรชายศิปโปร์ได้เห็นการทั้งปวงซึ่งอิสราเอลได้กระทําต่อคนอาโมไรต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 3, 'ทั้งโมอับก็ครั่นคร้ามต่อชนชาตินั้นนักหนา เพราะเขามีคนมากด้วยกัน โมอับกลัวคนอิสราเอลลานทีเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 4, 'โมอับจึงพูดกับพวกผู้ใหญ่ของเมืองมีเดียนว่า “คนเหล่านี้จะมาเลียกินสารพัดที่ล้อมรอบเราอยู่หมด เหมือนวัวเลียกินหญ้าในนา” บาลาคบุตรชายศิปโปร์เป็นกษัตริย์เมืองโมอับในเวลานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 5, 'ท่านใช้ผู้สื่อสารไปยังบาลาอัมบุตรชายเบโอร์ที่เปโธร์ใกล้แม่น้ําในแผ่นดินอันเป็นบ้านเกิดเมืองนอนของท่าน โดยกล่าวว่า “ดูเถิด ชนชาติหนึ่งออกมาจากอียิปต์ ดูเถิด เขาทั้งหลายเข้าแผ่คลุมพื้นแผ่นดินโลก กําลังพักอยู่ตรงข้ามข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 6, 'ฉะนั้น ขอเชิญมาเถิด บัดนี้ขอสาปแช่งชนชาตินี้ให้แก่ข้าพเจ้า เพราะเขาเข้มแข็งกว่าข้าพเจ้ามาก ชะรอยข้าพเจ้าจะสามารถรบชนะเขาและขับไล่เขาออกไปจากแผ่นดินได้ เพราะข้าพเจ้าทราบอยู่ว่า ถ้าท่านอวยพรแก่ผู้ใด ผู้นั้นจะเป็นไปตามพรนั้น และท่านสาปแช่งผู้ใด ผู้นั้นก็ถูกสาปแช่ง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 7, 'ดังนั้นพวกผู้ใหญ่ของเมืองโมอับกับพวกผู้ใหญ่ของเมืองมีเดียนก็ถือค่าการทําอาถรรพ์นั้นออกไป ครั้นเขาทั้งหลายมาถึงบาลาอัม ก็บอกคําของบาลาคแก่เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 8, 'บาลาอัมกล่าวแก่คนเหล่านั้นว่า “คืนนี้จงค้างที่นี่ก่อน เมื่อพระเยโฮวาห์ตรัสอย่างไรแก่ข้าแล้ว ข้าจึงจะนําคํานั้นมาแจ้งแก่ท่านทั้งหลาย” ดังนั้นเจ้าเมืองแห่งโมอับจึงยับยั้งอยู่กับบาลาอัม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 9, 'และพระเจ้าเสด็จมาหาบาลาอัมตรัสว่า “คนที่มาอยู่กับเจ้าคือผู้ใด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 10, 'บาลาอัมทูลพระเจ้าว่า “บาลาคบุตรชายศิปโปร์กษัตริย์เมืองโมอับได้ใช้เขาทั้งหลายมาแจ้งแก่ข้าพระองค์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 11, '‘ดูเถิด ชนชาติหนึ่งออกจากอียิปต์มาแผ่คลุมพื้นแผ่นดินโลก ขอเชิญมาเถิด ขอสาปแช่งเขาทั้งหลายให้แก่ข้าพเจ้า ชะรอยข้าพเจ้าจะรบชนะเขาและขับไล่เขาออกไปได้’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 12, 'พระเจ้าตรัสกับบาลาอัมว่า “เจ้าอย่าไปกับเขาทั้งหลาย เจ้าอย่าแช่งชนชาตินั้น เพราะเขาทั้งหลายเป็นคนที่ได้รับพร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 13, 'รุ่งเช้าบาลาอัมก็ลุกขึ้นกล่าวแก่เจ้านายของบาลาคว่า “จงกลับไปแผ่นดินของท่านเถิด เพราะพระเยโฮวาห์ทรงปฏิเสธมิให้เราไปกับท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 14, 'เพราะฉะนั้นเจ้านายแห่งโมอับก็ลุกขึ้นกลับไปหาบาลาคกล่าวว่า “บาลาอัมปฏิเสธไม่ยอมมากับเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 15, 'บาลาคได้ส่งพวกเจ้านายไปอีกครั้งหนึ่ง มีจํานวนมากกว่า และมีเกียรติยศมากกว่ารุ่นก่อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 16, 'เขาทั้งหลายมาถึงบาลาอัมกล่าวแก่ท่านว่า “บาลาคบุตรชายศิปโปร์กล่าวดังนี้ว่า ‘ขออย่าให้มีอะไรขัดขวางท่านที่จะไปหาข้าพเจ้าเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 17, 'เพราะข้าพเจ้าจะให้เกียรติแก่ท่านอย่างสูงแน่ ท่านจะให้ข้าพเจ้าทําอะไรให้ ข้าพเจ้าจะกระทําตาม ขอเชิญมาสาปแช่งชนชาตินี้ให้แก่ข้าพเจ้า’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 18, 'แต่บาลาอัมได้ตอบคนใช้ของบาลาคว่า “แม้ว่าบาลาคจะให้เงินและทองเต็มบ้านเต็มเรือนของท่านแก่ข้าพเจ้า ข้าพเจ้าจะกระทําอะไรนอกเหนือพระบัญชาของพระเยโฮวาห์พระเจ้าของข้าพเจ้าไม่ได้ ไม่ว่าเล็กหรือใหญ่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 19, 'ฉะนั้นบัดนี้ขอท่านยับยั้งอยู่ที่นี่สักคืนหนึ่งก่อนด้วย เพื่อข้าพเจ้าจะทราบว่าพระเยโฮวาห์จะตรัสเพิ่มเติมประการใดแก่ข้าพเจ้าบ้าง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 20, 'และพระเจ้าเสด็จมาหาบาลาอัมในกลางคืนตรัสแก่เขาว่า “ถ้ามีผู้ชายมาเรียกเจ้าจงลุกขึ้นไปกับเขา แต่เจ้าจงกระทําตามที่เราสั่งเจ้าเท่านั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 21, 'ดังนั้นรุ่งเช้าบาลาอัมก็ลุกขึ้นผูกอานลา ไปกับเจ้านายแห่งโมอับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 22, 'แต่พระเจ้าทรงกริ้วต่อบาลาอัมเพราะเขาไป ดังนั้นทูตสวรรค์ของพระเยโฮวาห์มายืนเป็นผู้สกัดทางบาลาอัมไว้ ฝ่ายบาลาอัมขี่ลามีคนใช้สองคนไปกับเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 23, 'เมื่อลานั้นเห็นทูตสวรรค์ของพระเยโฮวาห์ถือดาบยืนอยู่ในหนทาง ลาก็เลี้ยวออกนอกทาง เข้าไปในทุ่งนา บาลาอัมจึงตีลาให้กลับไปทางเดิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 24, 'แล้วทูตสวรรค์ของพระเยโฮวาห์มายืนอยู่ในทางแคบระหว่างสวนองุ่น มีกําแพงทั้งสองข้างทาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 25, 'เมื่อลาเห็นทูตสวรรค์ของพระเยโฮวาห์มันก็ดันไปติดกําแพง หนีบเท้าของบาลาอัมเข้ากับกําแพง บาลาอัมก็ตีลาอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 26, 'แล้วทูตสวรรค์ของพระเยโฮวาห์ก็เดินไปข้างหน้ายืนอยู่ในที่แคบ ไม่มีทางที่จะหลีกไปข้างขวาหรือข้างซ้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 27, 'เมื่อลาเห็นทูตสวรรค์ของพระเยโฮวาห์มันก็หมอบลง บาลาอัมยังคงนั่งอยู่บนหลัง บาลาอัมก็โกรธ จึงเอาไม้เท้าของเขาตีลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 28, 'แล้วพระเยโฮวาห์เปิดปากลา มันจึงพูดกับบาลาอัมว่า “ข้าพเจ้าได้กระทําอะไรแก่ท่าน ท่านจึงได้ตีข้าพเจ้าถึงสามครั้ง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 29, 'บาลาอัมพูดกับลาว่า “เพราะเจ้าได้แกล้งเรา เราอยากจะมีดาบอยู่ในมือเดี๋ยวนี้ เราจะได้ฆ่าเจ้าเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 30, 'ลาก็พูดกับบาลาอัมว่า “ข้าพเจ้าไม่ใช่ลาของท่านที่ท่านขับขี่อยู่ทุกวันตลอดชีวิตจนบัดนี้ดอกหรือ ข้าพเจ้าได้เคยกระทําเช่นนี้แก่ท่านหรือ” บาลาอัมก็บอกว่า “ไม่เคย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 31, 'แล้วพระเยโฮวาห์ทรงเบิกตาบาลาอัม เขาจึงเห็นทูตสวรรค์ของพระเยโฮวาห์ถือดาบยืนอยู่ในหนทาง บาลาอัมก็ก้มศีรษะซบหน้าลงกราบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 32, 'และทูตสวรรค์ของพระเยโฮวาห์พูดกับบาลาอัมว่า “ทําไมเจ้าจึงตีลาของเจ้าถึงสามครั้ง ดูเถิด เรามาห้ามเจ้า เพราะการประพฤติของเจ้าขัดขืนเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 33, 'ลาได้เห็นเราและหลีกไปต่อหน้าเราถึงสามครั้ง ถ้ามันมิได้หลีกไปจากเรา เราจะได้ฆ่าเจ้าเสียแล้วเมื่อตะกี้นี้แน่ และให้ลารอดตายไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 34, 'แล้วบาลาอัมพูดกับทูตสวรรค์ของพระเยโฮวาห์ว่า “ข้าพเจ้าได้กระทําบาป เพราะข้าพเจ้าไม่ทราบว่าท่านยืนอยู่ในหนทางกั้นข้าพเจ้า ฉะนั้นบัดนี้ถ้าท่านไม่เห็นชอบ ข้าพเจ้าจะกลับไปเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 35, 'แล้วทูตสวรรค์ของพระเยโฮวาห์พูดกับบาลาอัมว่า “จงไปกับชายเหล่านั้นเถิด แต่เจ้าจงพูดเฉพาะคําที่เราให้เจ้าพูด” ดังนั้นบาลาอัมก็ไปกับเจ้านายของบาลาคต่อไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 36, 'เมื่อบาลาคได้ยินว่าบาลาอัมมาแล้ว ท่านจึงออกไปรับบาลาอัมที่เมืองโมอับที่สุดปลายพรมแดนซึ่งเกิดขึ้นด้วยแม่น้ําอารโนน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 37, 'บาลาคพูดกับบาลาอัมว่า “เราได้อุตส่าห์ใช้คนไปเชิญท่านมามิใช่หรือ เหตุไฉนท่านไม่มาหาเราเล่า เราไม่สามารถที่จะให้เกียรติแก่ท่านหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 38, 'บาลาอัมพูดกับบาลาคว่า “ดูเถิด ข้าพเจ้ามาหาท่านแล้ว บัดนี้ข้าพเจ้าจะกล่าวอะไรได้เล่า คําซึ่งพระเจ้าใส่ปากข้าพเจ้า ข้าพเจ้าต้องกล่าว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 39, 'แล้วบาลาอัมไปกับบาลาคถึงตําบลคีริยาทหุโซท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 40, 'ณ ที่นั่นบาลาคเอาวัวและแกะถวายบูชา แล้วส่งไปให้บาลาอัมและเจ้านายที่อยู่กับเขาบ้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 41, 'ต่อมารุ่งขึ้นบาลาคก็พาบาลาอัมขึ้นไปยังปูชนียสถานสูงของพระบาอัล จากที่นั่นก็ได้เห็นประชาชนส่วนที่อยู่ใกล้ที่สุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 1, 'บาลาอัมพูดกับบาลาคว่า “ท่านจงสร้างแท่นบูชาให้ข้าพเจ้าที่นี่เจ็ดแท่น และจัดวัวผู้เจ็ดตัว แกะผู้เจ็ดตัวให้ข้าพเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 2, 'บาลาคก็กระทําตามคําของบาลาอัม บาลาคและบาลาอัมเอาวัวผู้ตัวหนึ่งแกะผู้ตัวหนึ่งกระทําบูชาที่แท่นบูชาทุกแท่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 3, 'แล้วบาลาอัมพูดกับบาลาคว่า “จงยืนอยู่ใกล้เครื่องเผาบูชาของท่านแล้วข้าพเจ้าจะไป ชะรอยพระเยโฮวาห์จะเสด็จมาหาข้าพเจ้า และสิ่งใดที่พระองค์สําแดงแก่ข้าพเจ้า ข้าพเจ้าจะบอกท่าน” แล้วเขาก็ขึ้นไปยังที่สูง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 4, 'พระเจ้าทรงพบกับบาลาอัม และบาลาอัมกราบทูลพระองค์ว่า “ข้าพระองค์ได้จัดแท่นบูชาเจ็ดแท่น ทั้งได้จัดวัวผู้ตัวหนึ่งและแกะผู้ตัวหนึ่งบูชาอยู่ทุกแท่น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 5, 'พระเยโฮวาห์ทรงใส่ถ้อยคําในปากของบาลาอัมและตรัสว่า “จงกลับไปหาบาลาคแล้วจงพูดอย่างนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 6, 'บาลาอัมจึงกลับไปหาบาลาค และดูเถิด บาลาคกับบรรดาเจ้านายแห่งโมอับยืนอยู่ที่ข้างเครื่องเผาบูชาของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 7, 'บาลาอัมได้กล่าวกลอนภาษิตของเขาว่า “บาลาคได้พาข้าพเจ้ามาจากอารัม ท่านกษัตริย์ของโมอับได้พาข้าพเจ้ามาจากภูเขาทางตะวันออก กล่าวว่า ‘มาเถิด มาแช่งยาโคบเพื่อข้าพเจ้า มาเถิด มาประณามอิสราเอล’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 8, 'ข้าพเจ้าจะแช่งผู้ที่พระเจ้าไม่ทรงแช่งได้อย่างไร ข้าพเจ้าจะประณามผู้ที่พระเยโฮวาห์ไม่ทรงประณามได้อย่างไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 9, 'เพราะข้าพเจ้าได้ดูเขาจากยอดผา จากเนินสูงข้าพเจ้าได้เห็นเขาแน่ะ ดูเถิด ชนชาติหนึ่งอยู่ลําพังและมิได้นับเข้าในหมู่ประชาชาติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 10, 'ใครจะนับผงคลีดินของยาโคบได้ หรือนับหนึ่งในสี่ของอิสราเอลได้ ขอให้ข้าพเจ้าตายอย่างคนชอบธรรม และขอให้สุดปลายชีวิตของข้าพเจ้าเหมือนอย่างของเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 11, 'แล้วบาลาคพูดกับบาลาอัมว่า “ท่านได้กระทําอะไรแก่เราเล่า เราเชิญท่านให้มาแช่งพวกศัตรูของเรา ดูเถิด ท่านไม่ได้กระทําอะไรแก่เขานอกจากอวยพรเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 12, 'เขาจึงตอบว่า “ข้าพเจ้าไม่ต้องระวังที่จะกล่าวคําซึ่งพระเยโฮวาห์ใส่ในปากข้าพเจ้าหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 13, 'บาลาคพูดกับเขาว่า “เชิญท่านไปอีกที่หนึ่งกับข้าพเจ้าเถิด ซึ่งท่านจะดูเขาจากที่นั่นได้ ท่านจะเห็นเพียงส่วนที่ใกล้ที่สุด และจะไม่เห็นคนทั้งหมด จากที่นั่นท่านจงแช่งเขาทั้งหลายให้ข้าพเจ้าเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 14, 'แล้วบาลาคก็พาบาลาอัมมาถึงนาของโศฟิม ขึ้นถึงยอดเขาปิสกาห์ สร้างแท่นบูชาเจ็ดแท่น และจัดวัวผู้ตัวหนึ่งและแกะผู้ตัวหนึ่งบูชาอยู่บนทุกแท่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 15, 'บาลาอัมพูดกับบาลาคว่า “จงยืนอยู่ข้างเครื่องเผาบูชาของท่านเถิด ขณะที่ข้าพเจ้าไปพบพระเยโฮวาห์ตรงโน้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 16, 'แล้วพระเยโฮวาห์ทรงพบบาลาอัมและทรงใส่ถ้อยคําในปากของเขาตรัสว่า “จงกลับไปหาบาลาค และจงพูดอย่างนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 17, 'บาลาอัมก็กลับมาหาบาลาค ดูเถิด เขายืนอยู่ข้างเครื่องเผาบูชาของท่าน มีเจ้านายแห่งโมอับยืนอยู่กับท่าน บาลาคจึงถามเขาว่า “พระเยโฮวาห์ตรัสว่ากระไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 18, 'บาลาอัมก็ได้กล่าวกลอนภาษิตของเขาว่า “บาลาค ลุกขึ้นเถิดและคอยฟัง บุตรชายของศิปโปร์ จงฟังข้าพเจ้าเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 19, 'พระเจ้ามิใช่มนุษย์จึงมิได้มุสา และมิได้เป็นบุตรของมนุษย์จึงไม่ต้องกลับใจ ที่พระองค์ตรัสไปแล้ว พระองค์ก็จะมิทรงกระทําตามหรือ ที่พระองค์ทรงลั่นวาจาแล้ว จะไม่ทรงกระทําให้สําเร็จหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 20, 'ดูเถิด ข้าพเจ้าได้รับพระบัญชาให้อวยพร พระองค์ได้ทรงอํานวยพร และข้าพเจ้าจะเรียกกลับไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 21, 'พระองค์ได้ทอดพระเนตรว่าไม่มีความชั่วช้าในยาโคบ และทรงเห็นว่าไม่มีความชั่วร้ายในอิสราเอล พระเยโฮวาห์พระเจ้าของเขาอยู่กับเขา และเสียงโห่ร้องถวายพรพระมหากษัตริย์อยู่ท่ามกลางเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 22, 'พระเจ้าทรงนําพวกเขาออกจากอียิปต์ พระองค์ทรงเป็นเสมือนพลังแห่งม้ายูนิคอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 23, 'ไม่มีการถือลางต่อต้านยาโคบ ไม่มีการทํานายต่อต้านอิสราเอล ถึงเวลาแล้วยาโคบและอิสราเอลก็จะได้รับคําบอกว่า ‘พระเจ้าจะทรงกระทําอะไร’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 24, 'ดูเถิด ชนชาติหนึ่งซึ่งลุกขึ้นอย่างสิงโตผู้ยิ่งใหญ่ และยืนขึ้นอย่างสิงโตหนุ่ม ไม่ยอมนอนจนกว่าจะกินเหยื่อเสีย และดื่มเลือดของสิ่งที่ฆ่าตาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 25, 'แล้วบาลาคจึงพูดกับบาลาอัม “อย่าแช่งเขาเลย ทั้งอย่าอวยพรแก่เขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 26, 'แต่บาลาอัมตอบบาลาคว่า “ข้าพเจ้าไม่ได้บอกท่านแล้วหรือว่า ‘ทุกสิ่งที่พระเยโฮวาห์ตรัส ข้าพเจ้าจะต้องกระทําตาม’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 27, 'บาลาคจึงพูดกับบาลาอัมว่า “มาเถิด ข้าพเจ้าจะพาท่านไปอีกที่หนึ่ง ชะรอยพระเจ้าจะทรงโปรดให้ท่านแช่งเขาเพื่อข้าพเจ้าจากที่นั่น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 28, 'บาลาคก็พาบาลาอัมไปถึงยอดเขาเปโอร์ ซึ่งมองลงมาเห็นเยชิโมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 29, 'แล้วบาลาอัมบอกกับบาลาคว่า “จงสร้างแท่นบูชาที่นี่เจ็ดแท่นให้ข้าพเจ้า จัดวัวผู้เจ็ดตัวและแกะผู้เจ็ดตัวให้ข้าพเจ้าที่นี่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 30, 'บาลาคจึงกระทําตามที่บาลาอัมได้บอก และถวายบูชาวัวผู้ตัวหนึ่งและแกะผู้ตัวหนึ่งบนแท่นทุกแท่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 1, 'เมื่อบาลาอัมเห็นว่าพระเยโฮวาห์ทรงพอพระทัยที่จะให้อวยพรแก่อิสราเอล บาลาอัมก็หาได้ไปแสวงหาลางอย่างครั้งก่อนๆไม่ แต่มุ่งหน้าตรงไปยังถิ่นทุรกันดาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 2, 'บาลาอัมเงยหน้าดูเห็นอิสราเอลอยู่เป็นค่ายๆตามตระกูล แล้วพระวิญญาณของพระเจ้ามาอยู่บนเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 3, 'เขาจึงกล่าวกลอนภาษิตของเขาว่า “คําพยากรณ์ของบาลาอัมบุตรชายเบโอร์ คําพยากรณ์ของชายที่หูตาแจ้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 4, 'คําพยากรณ์ของผู้ที่ได้ยินพระวจนะของพระเจ้า ผู้เห็นนิมิตขององค์ผู้ทรงมหิทธิฤทธิ์ ได้ล้มลงจนเกิดความมึนงง แต่ตาไม่มีสิ่งใดบัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 5, 'โอ ยาโคบเอ๋ย เต็นท์ของท่านช่างงามเหลือเกิน โอ อิสราเอลเอ๋ย ค่ายของท่านก็งาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 6, 'เหมือนหุบเขาที่ยืดไปไกล เหมือนสวนซึ่งอยู่ข้างแม่น้ํา เหมือนต้นกฤษณาซึ่งพระเยโฮวาห์ทรงปลูกไว้ เหมือนต้นสนสีดาร์ที่อยู่ข้างลําน้ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 7, 'น้ําจะไหลออกจากถังของเขา และเชื้อสายของเขาจะมีอยู่ตามลําน้ําเป็นอันมาก กษัตริย์ของเขาจะสูงกว่ากษัตริย์อากัก ราชอาณาจักรของเขาจะรุ่งเรือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 8, 'พระเจ้าผู้ทรงนําเขาออกมาจากอียิปต์ ทรงเป็นเสมือนพลังแห่งม้ายูนิคอน เขาจะกินประชาชาติซึ่งเป็นศัตรูเสีย และหักกระดูกของศัตรูเหล่านั้น และแทงเขาทั้งหลายทะลุด้วยลูกศร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 9, 'เขาหมอบลงและนอนลงอย่างสิงโต เขาเหมือนสิงโตผู้ยิ่งใหญ่ ใครเล่าจะมาปลุกให้เขาลุกขึ้น ผู้ใดที่อวยพรแก่ท่าน ขอให้เขาได้รับพร ผู้ใดที่แช่งท่าน ขอให้เขาได้รับคําแช่ง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 10, 'บาลาคก็โกรธบาลาอัม จึงตบมือ แล้วบาลาคพูดกับบาลาอัมว่า “เราเชิญท่านมาให้แช่งศัตรูของเรา และดูเถิด ท่านได้อวยพรแก่เขาถึงสามครั้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 11, 'ฉะนั้นบัดนี้ จงหนีไปยังที่อยู่ของท่านเถิด เราได้กล่าวว่า เราจะให้เกียรติแก่ท่านแน่แท้ แต่ดูเถิด พระเยโฮวาห์ทรงขัดขวางมิให้ท่านได้รับเกียรติ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 12, 'แต่บาลาอัมพูดกับบาลาคว่า “ข้าพเจ้ามิได้บอกผู้สื่อสารซึ่งท่านใช้ให้ไปหาข้าพเจ้านั้นแล้วหรือว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 13, '‘แม้ว่าบาลาคจะให้เงินและทองเต็มบ้านเต็มเรือนของเขาแก่ข้าพเจ้า ข้าพเจ้าจะกระทําอะไรนอกเหนือพระบัญชาของพระเยโฮวาห์ไม่ได้ ที่จะทําตามใจข้าพเจ้าไม่ว่าดีหรือชั่ว พระเยโฮวาห์ตรัสประการใด ข้าพเจ้าจะพูดอย่างนั้น’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 14, 'ดูเถิด บัดนี้ข้าพเจ้าจะกลับไปสู่ชนชาติของข้าพเจ้า มาเถิด ข้าพเจ้าจะสําแดงให้ท่านทราบว่า ชนชาตินี้จะกระทําประการใดแก่ชนชาติของท่านในวันข้างหน้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 15, 'เขาก็กล่าวกลอนภาษิตของเขาว่า “คําพยากรณ์ของบาลาอัมบุตรชายเบโอร์ คําพยากรณ์ของชายผู้ที่หูตาแจ้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 16, 'คําพยากรณ์ของผู้ที่ได้ยินพระวจนะของพระเจ้า และทราบถึงพระปัญญาของพระองค์ผู้สูงสุด ผู้เห็นนิมิตขององค์ผู้ทรงมหิทธิฤทธิ์ ได้ล้มลงจนเกิดความมึนงง แต่ตาไม่มีสิ่งใดบัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 17, 'ข้าพเจ้าจะเห็นเขา แต่ไม่ใช่อย่างเดี๋ยวนี้ ข้าพเจ้าจะดูเขา แต่ไม่ใช่อย่างใกล้ๆนี้ ดาวดวงหนึ่งจะเดินออกมาจากยาโคบ และธารพระกรอันหนึ่งจะขึ้นมาจากอิสราเอล จะตีเขตแดนของโมอับและทําลายบรรดาลูกหลานของเสท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 18, 'ฝ่ายเอโดมจะตกเป็นของคนอื่น เสอีร์จะตกเป็นของศัตรูของเขาด้วย ฝ่ายอิสราเอลได้แสดงวีรกรรมแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 19, 'ผู้หนึ่งที่ออกมาจากยาโคบจะครอบครอง และชาวเมืองที่รอดตาย ผู้นั้นจะทําลายเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 20, 'แล้วบาลาอัมมองดูคนอามาเลข และกล่าวกลอนภาษิตของเขาว่า “อามาเลขเป็นประชาชาติที่หนึ่ง แต่ในที่สุดจะถึงซึ่งการทําลายอันถาวร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 21, 'และเขามองดูคนเคไนต์ และกล่าวกลอนภาษิตของเขาว่า “ที่อาศัยของท่านเข้มแข็งมาก และรังของท่านก็วางอยู่ในศิลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 22, 'แต่อย่างไรก็ตามคนเคไนต์ก็ต้องถูกกวาดล้าง อีกนานเท่าใดเล่า พวกอัสชูรจะมากวาดเจ้าไปเป็นเชลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 23, 'และบาลาอัมกล่าวกลอนภาษิตของเขาว่า “อนิจจาเอ๋ย เมื่อพระเจ้าทรงกระทําเช่นนี้ใครจะมีชีวิตอยู่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 24, 'แต่กําปั่นจะมาจากเขตแดนเมืองคิทธิมทําลายอัสชูรและเอเบอร์ และเขาจะถูกทําลายอันถาวรด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 25, 'แล้วบาลาอัมก็ลุกขึ้นกลับไปที่อยู่ของเขา และบาลาคก็ไปตามทางของตนด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 1, 'เมื่ออิสราเอลพักอยู่ในเมืองชิทธิม ประชาชนก็ได้เริ่มเล่นชู้กับหญิงชาวโมอับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 2, 'หญิงเหล่านี้ก็เชิญประชาชนให้ไปกระทําบูชาต่อพระของนาง ประชาชนก็รับประทานและกราบไหว้พระของนาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 3, 'ดังนั้นอิสราเอลก็เข้าถือพระบาอัลเปโอร์ และพระเยโฮวาห์ทรงพระพิโรธต่ออิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 4, 'และพระเยโฮวาห์ตรัสกับโมเสสว่า “จงนําหัวหน้าทั้งหลายของประชาชนแขวนตากแดดไว้ต่อพระพักตร์พระเยโฮวาห์ เพื่อว่าพระพิโรธอันเกรี้ยวกราดของพระเยโฮวาห์จะหันเหไปจากอิสราเอลเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 5, 'และโมเสสบอกพวกผู้วินิจฉัยของอิสราเอลว่า “ท่านทุกคนจงฆ่าคนของท่านที่เข้าถือพระบาอัลเปโอร์เสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 6, 'และดูเถิด มีชายอิสราเอลคนหนึ่งพาหญิงคนมีเดียนคนหนึ่งเข้ามาในหมู่พี่น้องของเขาต่อสายตาของโมเสส และท่ามกลางสายตาของชุมนุมชนทั้งหมดของคนอิสราเอล ซึ่งกําลังร้องไห้อยู่หน้าประตูพลับพลาแห่งที่ชุมนุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 7, 'ครั้นฟีเนหัสบุตรชายเอเลอาซาร์ บุตรชายของอาโรนปุโรหิตเห็นดังนั้นก็ลุกขึ้นไปจากชุมนุมชน มือถือทวน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 8, 'ติดตามชายอิสราเอลคนนั้นเข้าไปในเต็นท์ และแทงทะลุเขาทั้งคู่ ทั้งชายอิสราเอลและหญิงคนนั้น ท้องของนางก็ทะลุ แล้วภัยพิบัติในคนอิสราเอลก็สงบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 9, 'แต่อย่างไรก็ตาม คนที่ตายด้วยภัยพิบัติมีสองหมื่นสี่พันคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 10, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 11, '“ฟีเนหัส บุตรชายเอเลอาซาร์ บุตรชายอาโรนปุโรหิต ได้ยับยั้งความกริ้วของเราต่อคนอิสราเอล ในการที่เขามีความกระตือรือร้นเพราะเห็นแก่เราในท่ามกลางประชาชน ดังนั้นเราจึงมิได้เผาผลาญคนอิสราเอลเสียด้วยความหึงหวงของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 12, 'ดังนั้นจงกล่าวว่า ‘ดูเถิด เราให้พันธสัญญาสันติสุขแก่เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 13, 'พันธสัญญานั้นจะเป็นของเขา และของเชื้อสายของเขาที่มาภายหลังเขา เป็นพันธสัญญาแห่งตําแหน่งปุโรหิตอันถาวร เพราะเขามีความกระตือรือร้นเพื่อพระเจ้าของเขา และได้ทําการลบมลทินบาปคนอิสราเอล’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 14, 'ชื่อของชายอิสราเอลคนที่ถูกฆ่าร่วมกับหญิงชาวมีเดียนคนนั้น ชื่อศิมรี บุตรชายของสาลู เจ้านายของครอบครัวสําคัญในตระกูลสิเมโอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 15, 'และชื่อของหญิงชาวมีเดียนผู้ถูกฆ่า คือคสบี บุตรสาวของศูร์ ผู้เป็นหัวหน้าตระกูลและครอบครัวสําคัญในมีเดียน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 16, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 17, '“จงรบกวนคนมีเดียน และสู้รบกับเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 18, 'เพราะเขารบกวนเจ้าด้วยอุบาย ซึ่งเขาล่อเจ้าในเรื่องเปโอร์ และในเรื่องนางคสบี บุตรสาวเจ้านายแห่งมีเดียน ผู้เป็นน้องสาวของพวกเขา ผู้ที่ถูกฆ่าตายในวันที่บังเกิดภัยพิบัติด้วยเรื่องเปโอร์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 1, 'ต่อมาภายหลังภัยพิบัตินั้นพระเยโฮวาห์ตรัสกับโมเสสและเอเลอาซาร์บุตรชายอาโรนปุโรหิตว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 2, '“จงทําสํามะโนครัวชุมนุมชนอิสราเอลทั้งหมด อายุตั้งแต่ยี่สิบปีขึ้นไปตามเรือนบรรพบุรุษของเขาทั้งหมดในอิสราเอล ผู้ที่จะเข้าสงครามได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 3, 'โมเสสกับเอเลอาซาร์ปุโรหิต ปราศรัยกับเขาทั้งหลาย ณ ที่ราบโมอับ ริมแม่น้ําจอร์แดนใกล้เมืองเยรีโคว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 4, '“จงทําสํามะโนครัวประชาชน อายุตั้งแต่ยี่สิบปีขึ้นไป” ตามที่พระเยโฮวาห์ทรงบัญชาโมเสสและคนอิสราเอล ผู้ที่ออกจากแผ่นดินอียิปต์คือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 5, 'รูเบน บุตรชายหัวปีของอิสราเอล บุตรของรูเบน คือฮาโนค คนครอบครัวฮาโนค ปัลลู คนครอบครัวปัลลู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 6, 'เฮสโรน คนครอบครัวเฮสโรน คารมี คนครอบครัวคารมี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 7, 'เหล่านี้เป็นครอบครัวของคนรูเบน มีจํานวนสี่หมื่นสามพันเจ็ดร้อยสามสิบคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 8, 'และบุตรชายของปัลลู คือเอลีอับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 9, 'บุตรชายของเอลีอับคือ เนมูเอล ดาธาน และอาบีรัม นี่คือดาธานและอาบีรัมที่เลือกจากชุมนุมชน เป็นผู้ขัดขวางโมเสสและอาโรนในพรรคพวกโคราห์ เมื่อเขาขัดขวางพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 10, 'และแผ่นธรณีได้อ้าปากออกกลืนเขาพร้อมกับโคราห์ เมื่อพรรคพวกนั้นถึงตาย เมื่อไฟเผาผลาญเสียสองร้อยห้าสิบคนและเขาทั้งหลายเป็นเรื่องเตือนใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 11, 'แต่บุตรของโคราห์นั้นหาได้ตายไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 12, 'บุตรชายของสิเมโอนตามครอบครัวของเขา คือเนมูเอล คนครอบครัวเนมูเอล ยามีน คนครอบครัวยามีน ยาคีน คนครอบครัวยาคีน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 13, 'เศ-ราห์ คนครอบครัวเศ-ราห์ ชาอูล คนครอบครัวชาอูล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 14, 'เหล่านี้เป็นครอบครัวของคนสิเมโอน มีจํานวนสองหมื่นสองพันสองร้อยคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 15, 'บุตรของกาด ตามครอบครัวของเขา คือเศโฟน คนครอบครัวเศโฟน ฮักกี คนครอบครัวฮักกี ชูนี คนครอบครัวชูนี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 16, 'โอสนี คนครอบครัวโอสนี เอรี คนครอบครัวเอรี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 17, 'อาโรด คนครอบครัวอาโรด อาเรลี คนครอบครัวอาเรลี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 18, 'เหล่านี้เป็นครอบครัวของบุตรของกาด ตามจํานวนของเขามีสี่หมื่นห้าร้อยคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 19, 'บุตรชายของยูดาห์คือ เอร์และโอนัน เอร์กับโอนันตายเสียในแผ่นดินคานาอัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 20, 'และบุตรชายของยูดาห์ตามครอบครัวของเขา คือเช-ลาห์ คนครอบครัวเช-ลาห์ เปเรศ คนครอบครัวเปเรศ เศ-ราห์ คนครอบครัวเศ-ราห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 21, 'และบุตรชายของเปเรศคือ เฮสโรน คนครอบครัวเฮสโรน ฮามูล คนครอบครัวฮามูล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 22, 'เหล่านี้เป็นครอบครัวของยูดาห์ ตามจํานวนของเขามีเจ็ดหมื่นหกพันห้าร้อยคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 23, 'บุตรชายของอิสสาคาร์ตามครอบครัวของเขา คือโทลา คนครอบครัวโทลา ปูวาห์ คนครอบครัวปูวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 24, 'ยาชูบ คนครอบครัวยาชูบ ชิมโรน คนครอบครัวชิมโรน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 25, 'เหล่านี้เป็นครอบครัวของอิสสาคาร์ ตามจํานวนของเขามีหกหมื่นสี่พันสามร้อยคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 26, 'บุตรชายของเศบูลุนตามครอบครัวของเขา คือเสเรด คนครอบครัวเสเรด เอโลน คนครอบครัวเอโลน ยาเลเอล คนครอบครัวยาเลเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 27, 'เหล่านี้เป็นครอบครัวของคนเศบูลุน ตามจํานวนของเขามีหกหมื่นห้าร้อยคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 28, 'บุตรชายของโยเซฟตามครอบครัวของเขา คือมนัสเสห์และเอฟราอิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 29, 'บุตรชายของมนัสเสห์ คือมาคีร์ คนครอบครัวมาคีร์ มาคีร์ให้กําเนิดบุตรชื่อกิเลอาด กิเลอาด คนครอบครัวกิเลอาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 30, 'บุตรชายของกิเลอาด คืออีเยเซอร์ คนครอบครัวอีเยเซอร์ เฮเลค คนครอบครัวเฮเลค');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 31, 'และอัสรีเอล คนครอบครัวอัสรีเอล เชเคม คนครอบครัวเชเคม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 32, 'และเชมิดา คนครอบครัวเชมิดา เฮเฟอร์ คนครอบครัวเฮเฟอร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 33, 'ส่วนเศโลเฟหัดบุตรชายเฮเฟอร์ไม่มีบุตรชายมีแต่บุตรสาว ชื่อบุตรสาวของเศโลเฟหัดคือ มาลาห์ โนอาห์ โฮกลาห์ มิลคาห์และทีรซาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 34, 'เหล่านี้เป็นครอบครัวของมนัสเสห์ และจํานวนของเขามีห้าหมื่นสองพันเจ็ดร้อยคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 35, 'ต่อไปนี้เป็นบุตรชายของเอฟราอิมตามครอบครัวของเขาคือ ชูเธลาห์ คนครอบครัวชูเธลาห์ เบเคอร์ คนครอบครัวเบเคอร์ ทาหาน คนครอบครัวทาหาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 36, 'บุตรชายของชูเธลาห์คือ เอราน คนครอบครัวเอราน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 37, 'เหล่านี้เป็นครอบครัวของบุตรชายเอฟราอิม ตามจํานวนของเขา มีสามหมื่นสองพันห้าร้อยคน เหล่านี้เป็นบุตรชายของโยเซฟตามครอบครัวของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 38, 'บุตรชายของเบนยามินตามครอบครัวของเขา คือ เบลา คนครอบครัวเบลา อัชเบล คนครอบครัวอัชเบล อาหิรัม คนครอบครัวอาหิรัม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 39, 'ชูฟาม คนครอบครัวชูฟาม หุฟาม คนครอบครัวหุฟาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 40, 'และบุตรชายของเบลา คืออาร์ดและนาอามาน อาร์ด คนครอบครัวอาร์ด นาอามาน คนครอบครัวนาอามาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 41, 'เหล่านี้เป็นบุตรชายของเบนยามินตามครอบครัวของเขา และจํานวนของเขาเป็นสี่หมื่นห้าพันหกร้อยคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 42, 'ต่อไปนี้เป็นบุตรชายของดานตามครอบครัวของเขา คือชูฮัม คนครอบครัวชูฮัม นี่เป็นครอบครัวของดานตามครอบครัวของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 43, 'ครอบครัวทั้งหมดของคนชูฮัมตามจํานวนของเขา มีหกหมื่นสี่พันสี่ร้อยคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 44, 'บุตรของอาเชอร์ตามครอบครัวของเขา คืออิมนาห์ คนครอบครัวอิมนาห์ อิชวี คนครอบครัวอิชวี เบรียาห์ คนครอบครัวเบรียาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 45, 'บุตรชายของเบรียาห์คือ เฮเบอร์ คนครอบครัวเฮเบอร์ มัลคีเอล คนครอบครัวมัลคีเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 46, 'บุตรสาวของอาเชอร์ คือเสราห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 47, 'เหล่านี้เป็นครอบครัวของบุตรชายอาเชอร์ตามจํานวนของเขา มีห้าหมื่นสามพันสี่ร้อยคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 48, 'บุตรชายของนัฟทาลีตามครอบครัวของเขา คือยาเซเอล คนครอบครัวยาเซเอล กูนี คนครอบครัวกูนี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 49, 'เยเซอร์ คนครอบครัวเยเซอร์ ชิลเลม คนครอบครัวชิลเลม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 50, 'เหล่านี้เป็นครอบครัวของนัฟทาลีตามครอบครัวของเขา และตามจํานวนของเขามีสี่หมื่นห้าพันสี่ร้อยคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 51, 'จํานวนคนอิสราเอล มีหกแสนหนึ่งพันเจ็ดร้อยสามสิบคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 52, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 53, '“ให้แบ่งแผ่นดินนั้นเป็นมรดกแก่คนเหล่านี้ตามจํานวนรายชื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 54, 'มรดกส่วนใหญ่ก็ให้แบ่งแก่คนตระกูลใหญ่ และมรดกส่วนน้อยก็ให้แบ่งแก่คนตระกูลย่อม ทุกตระกูลจะได้รับส่วนมรดกตามจํานวนคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 55, 'แต่ให้จับฉลากแบ่งแผ่นดินนั้น ให้เขาได้รับมรดกตามรายชื่อตระกูลของบรรพบุรุษของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 56, 'ให้จับฉลากแบ่งมรดกของเขานั้นตามส่วนตระกูลใหญ่และตระกูลย่อม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 57, 'ต่อไปนี้เป็นคนเลวีที่นับตามครอบครัวของเขา คือเกอร์โชน คนครอบครัวเกอร์โชน โคฮาท คนครอบครัวโคฮาท เมรารี คนครอบครัวเมรารี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 58, 'ต่อไปนี้เป็นครอบครัวของเลวี คือคนครอบครัวลิบนี คนครอบครัวเฮโบรน คนครอบครัวมาห์ลี คนครอบครัวมูชี คนครอบครัวโคราห์ และโคฮาทให้กําเนิดบุตรชื่ออัมราม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 59, 'ภรรยาของอัมรามคือโยเคเบดบุตรสาวของเลวีเกิดแก่เลวีที่อียิปต์ และนางคลอดบุตรให้อัมรามชื่อ อาโรนและโมเสส และมิเรียมพี่สาวของเขาทั้งสอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 60, 'และอาโรนให้กําเนิดบุตรชื่อนาดับ อาบีฮู เอเลอาซาร์ และอิธามาร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 61, 'แต่นาดับและอาบีฮูนั้นได้เสียชีวิต เมื่อเขาบูชาด้วยไฟที่ผิดรูปแบบต่อพระพักตร์พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 62, 'และจํานวนของเขาเป็นสองหมื่นสามพันคน เป็นผู้ชายทุกคนอายุตั้งแต่หนึ่งเดือนขึ้นไป เพราะเขามิได้นับรวมไว้ในคนอิสราเอล เพราะไม่มีมรดกให้แก่เขาท่ามกลางคนอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 63, 'จํานวนคนเหล่านี้โมเสสและเอเลอาซาร์ปุโรหิตได้นับไว้ ครั้งเมื่อนับคนอิสราเอล ณ ที่ราบโมอับ ริมแม่น้ําจอร์แดนใกล้เมืองเยรีโค');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 64, 'แต่ตามรายชื่อเหล่านี้ไม่มีชายสักคนหนึ่งซึ่งโมเสสและอาโรนปุโรหิตได้นับไว้ครั้งเมื่อนับคนอิสราเอลในถิ่นทุรกันดารซีนาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 65, 'เพราะพระเยโฮวาห์ตรัสเรื่องเขาเหล่านั้นว่า “เขาจะต้องตายแน่ในถิ่นทุรกันดาร” ไม่มีชายสักคนหนึ่งเหลืออยู่นอกจากคาเลบบุตรชายเยฟุนเนห์และโยชูวาบุตรชายนูน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 1, 'ครั้งนั้นบุตรสาวทั้งหลายของเศโลเฟหัดบุตรชายของเฮเฟอร์ ผู้เป็นบุตรชายของกิเลอาด ผู้เป็นบุตรชายของมาคีร์ ผู้เป็นบุตรชายของมนัสเสห์ จากครอบครัวต่างๆของมนัสเสห์บุตรชายของโยเซฟเข้ามาใกล้ ชื่อบุตรสาวทั้งหลายของเขาคือ มาลาห์ โนอาห์ โฮกลาห์ มิลคาห์ และทีรซาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 2, 'และเขาทั้งหลายมายืนอยู่ต่อหน้าโมเสสและต่อหน้าเอเลอาซาร์ปุโรหิต และต่อหน้าประมุข และต่อหน้าบรรดาชุมนุมชนที่ประตูพลับพลาแห่งชุมนุม กล่าวว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 3, '“บิดาของเราตายเสียในถิ่นทุรกันดาร ท่านมิได้อยู่ในพวกที่ส้องสุมกันต่อสู้พระเยโฮวาห์ในพรรคพวกโคราห์ แต่ท่านเสียชีวิตเพราะบาปของตน และท่านไม่มีบุตรชายเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 4, 'เหตุใดจึงลบชื่อบิดาของเราจากครอบครัวของท่าน เพราะเหตุที่ท่านไม่มีบุตรชายเลย ขอให้เรามีกรรมสิทธิ์ที่ดินท่ามกลางพี่น้องบิดาของเราด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 5, 'โมเสสได้นําเรื่องของเขากราบทูลต่อพระพักตร์พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 6, 'และพระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 7, '“บุตรสาวของเศโลเฟหัดพูดถูกต้องแล้ว เจ้าจงให้กรรมสิทธิ์ที่ดินเป็นมรดกท่ามกลางพี่น้องบิดาของเขา และกระทําให้มรดกบิดาของเขาตกทอดมาถึงเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 8, 'เจ้าจงกล่าวแก่คนอิสราเอลว่า ‘ถ้าผู้ชายคนหนึ่งตายและไม่มีบุตรชาย เจ้าจงให้มรดกของเขาตกไปยังบุตรสาวของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 9, 'และถ้าเขาไม่มีบุตรสาว เจ้าจงให้มรดกของเขาแก่พี่น้องของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 10, 'และถ้าเขาไม่มีพี่น้อง เจ้าจงให้มรดกของเขาแก่พี่น้องบิดาของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 11, 'และถ้าบิดาของเขาไม่มีพี่น้อง เจ้าจงให้มรดกของเขาแก่ญาติถัดตัวเขาไปในครอบครัวของเขา ให้ผู้นั้นถือกรรมสิทธิ์ได้ ให้เป็นกฎเกณฑ์แห่งคําตัดสินแก่ประชาชนอิสราเอล ดังที่พระเยโฮวาห์ทรงบัญชาโมเสสไว้’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 12, 'พระเยโฮวาห์ตรัสกับโมเสสว่า “จงขึ้นไปบนภูเขาอาบาริมนี้ และมองดูแผ่นดินซึ่งเรามอบให้แก่คนอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 13, 'และเมื่อเจ้าได้เห็นแล้ว เจ้าจะถูกรวบไปอยู่กับประชาชนของเจ้า อย่างอาโรนพี่ชายของเจ้าได้ถูกรวบไปนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 14, 'เพราะว่าเจ้าทั้งสองกบฏต่อบัญชาของเราในถิ่นทุรกันดารศินระหว่างที่ชุมนุมชนได้โต้แย้งขึ้น เจ้ามิได้นับถือเราต่อหน้าต่อตาเขาทั้งหลายที่น้ํานั้น” นี่คือน้ําเมรีบาห์แห่งคาเดชในถิ่นทุรกันดารศิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 15, 'โมเสสกราบทูลพระเยโฮวาห์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 16, '“ขอพระเยโฮวาห์พระเจ้าแห่งจิตวิญญาณมนุษย์ทั้งปวงทรงแต่งตั้งชายผู้หนึ่งไว้เหนือชุมนุมชนนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 17, 'ผู้ซึ่งจะเข้านอกออกในต่อหน้าเขา ผู้ซึ่งจะนําเขาเข้าออก เพื่อว่าชุมนุมชนของพระเยโฮวาห์จะมิได้เหมือนกับฝูงแกะที่ไม่มีผู้เลี้ยง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 18, 'และพระเยโฮวาห์ตรัสกับโมเสสว่า “จงนําโยชูวาบุตรชายนูนผู้มีพระวิญญาณอยู่ภายในเขามา จงเอามือของเจ้าวางบนเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 19, 'ตั้งเขาไว้ต่อหน้าเอเลอาซาร์ปุโรหิตและต่อหน้าชุมนุมชนทั้งหมด และเจ้าจงกําชับเขาท่ามกลางสายตาของชุมนุมชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 20, 'เจ้าจงให้เกียรติยศอย่างของเจ้าแก่เขาบ้าง เพื่อให้ชุมนุมชนอิสราเอลทั้งหมดเชื่อฟังเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 21, 'และเขาจะยืนอยู่ต่อหน้าเอเลอาซาร์ปุโรหิต ผู้ซึ่งจะทูลถามเพื่อเขาตามหลักตัดสินของอูริมต่อพระพักตร์พระเยโฮวาห์ และคนทั้งปวงจะออกไปและเข้ามาตามคําของปุโรหิต ทั้งเขากับคนทั้งปวงในอิสราเอลนั้นคือชุมนุมชนทั้งหมด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 22, 'และโมเสสกระทําตามที่พระเยโฮวาห์ทรงบัญชาท่าน ท่านจึงนําโยชูวาให้มายืนต่อหน้าเอเลอาซาร์ปุโรหิต และต่อหน้าชุมนุมชนทั้งหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 23, 'และท่านเอามือวางบนโยชูวา และกําชับเขา ตามที่พระเยโฮวาห์ตรัสสั่งทางโมเสส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 1, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 2, '“จงบัญชาคนอิสราเอลและกล่าวแก่เขาว่า ของบูชาของเรา อาหารของเราซึ่งเป็นของบูชาด้วยไฟ เป็นกลิ่นที่พอพระทัย เจ้าทั้งหลายจงเอาใจใส่ที่จะถวายบูชาแก่เราตามกาลกําหนด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 3, 'และเจ้าจงกล่าวแก่เขาว่า นี่เป็นเครื่องบูชาด้วยไฟซึ่งเจ้าทั้งหลายควรถวายแด่พระเยโฮวาห์ คือลูกแกะอายุหนึ่งขวบไม่มีตําหนิสองตัว เป็นเครื่องบูชาเนืองนิตย์ทุกวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 4, 'เจ้าจงถวายลูกแกะเป็นเครื่องบูชาในตอนเช้าตัวหนึ่ง และลูกแกะอีกตัวหนึ่งนั้นเจ้าจงถวายบูชาเวลาเย็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 5, 'และยอดแป้งหนึ่งในสิบเอฟาห์เป็นธัญญบูชา คลุกกับน้ํามันสกัดหนึ่งในสี่ฮิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 6, 'เป็นเครื่องเผาบูชาเนืองนิตย์ ซึ่งได้บัญชาตั้งไว้ที่ภูเขาซีนายเป็นกลิ่นที่พอพระทัย เป็นเครื่องบูชาด้วยไฟถวายแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 7, 'ส่วนเครื่องดื่มบูชาคู่กันนั้นให้ถวายหนึ่งในสี่ฮินกับแกะตัวหนึ่ง ในที่บริสุทธิ์เจ้าจงเทเครื่องดื่มบูชาซึ่งเป็นเหล้าองุ่นถวายแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 8, 'ลูกแกะอีกตัวหนึ่งเจ้าจงถวายบูชาเวลาเย็น เจ้าจงถวายบูชาด้วยไฟเช่นเดียวกับธัญญบูชาของเวลาเช้า และเช่นเดียวกับเครื่องดื่มบูชาที่คู่กัน เป็นกลิ่นที่พอพระทัยพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 9, 'ในวันสะบาโตลูกแกะอายุหนึ่งขวบสองตัวที่ไม่มีตําหนิ และยอดแป้งสองในสิบเอฟาห์คลุกกับน้ํามันให้เป็นธัญญบูชา และเครื่องดื่มบูชาคู่กัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 10, 'นี่เป็นเครื่องเผาบูชาทุกวันสะบาโตนอกเหนือเครื่องเผาบูชาเนืองนิตย์และเครื่องดื่มบูชาคู่กัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 11, 'เวลาต้นเดือนทุกเดือน เจ้าทั้งหลายจงถวายเครื่องเผาบูชาแด่พระเยโฮวาห์ คือวัวหนุ่มสองตัว แกะผู้ตัวหนึ่ง ลูกแกะหนึ่งขวบไม่มีตําหนิเจ็ดตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 12, 'สําหรับวัวตัวหนึ่งจงเอายอดแป้งสามในสิบเอฟาห์คลุกกับน้ํามันสําหรับเป็นธัญญบูชา และสําหรับแกะผู้ตัวหนึ่งนั้นจงเอายอดแป้งสองในสิบเอฟาห์คลุกกับน้ํามันเป็นธัญญบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 13, 'สําหรับลูกแกะทุกตัวจงเอายอดแป้งหนึ่งในสิบเอฟาห์คลุกกับน้ํามันเป็นธัญญบูชา ให้เป็นเครื่องเผาบูชาเป็นกลิ่นที่พอพระทัย เป็นเครื่องบูชาด้วยไฟถวายแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 14, 'ส่วนเครื่องดื่มบูชาคู่กันนั้น สําหรับวัวผู้ตัวหนึ่งจงเอาน้ําองุ่นครึ่งฮิน สําหรับแกะผู้ตัวหนึ่งจงเอาหนึ่งในสามฮิน สําหรับลูกแกะตัวหนึ่งจงเอาหนึ่งในสี่ฮิน นี่เป็นเครื่องเผาบูชาประจําเดือน ทุกเดือนตลอดปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 15, 'และเอาลูกแพะผู้ตัวหนึ่งเป็นเครื่องบูชาไถ่บาปถวายแด่พระเยโฮวาห์ ให้นํามาบูชานอกเหนือเครื่องเผาบูชาเนืองนิตย์และเครื่องดื่มบูชาคู่กัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 16, 'เดือนที่หนึ่งวันที่สิบสี่เป็นปัสกาของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 17, 'และวันที่สิบห้าของเดือนนี้เป็นวันการเลี้ยง จงรับประทานขนมปังไร้เชื้อเจ็ดวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 18, 'ในวันต้นให้มีการประชุมบริสุทธิ์ เจ้าทั้งหลายอย่ากระทํางานหนักในวันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 19, 'แต่จงถวายบูชาด้วยไฟ เป็นเครื่องเผาบูชาแด่พระเยโฮวาห์ คือเอาวัวหนุ่มสองตัว แกะผู้ตัวหนึ่ง และลูกแกะอายุหนึ่งขวบเจ็ดตัว ดูให้ดีว่าไม่มีตําหนิ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 20, 'และเอายอดแป้งคลุกน้ํามันเป็นธัญญบูชาของสัตว์เหล่านี้ สําหรับวัวผู้ตัวหนึ่งเจ้าจงถวายสามในสิบเอฟาห์ และสําหรับแกะผู้ตัวหนึ่งสองในสิบเอฟาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 21, 'สําหรับลูกแกะตัวหนึ่งๆในลูกแกะเจ็ดตัวนั้น จงเอาแป้งหนึ่งในสิบเอฟาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 22, 'และเอาแพะผู้ตัวหนึ่งเป็นเครื่องบูชาไถ่บาปเพื่อทําการลบมลทินบาปของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 23, 'เจ้าจงถวายเครื่องบูชาเหล่านี้ นอกเหนือเครื่องเผาบูชาตอนเช้า ซึ่งเป็นเครื่องบูชาเนืองนิตย์นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 24, 'ในทํานองเดียวกัน เจ้าจงถวายเครื่องบูชาทุกวันตลอดทั้งเจ็ดวัน คือถวายอาหารเป็นเครื่องบูชาด้วยไฟ เป็นกลิ่นที่พอพระทัยพระเยโฮวาห์ จงถวายบูชานอกเหนือเครื่องเผาบูชาเนืองนิตย์ และเครื่องดื่มบูชาคู่กัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 25, 'และในวันที่เจ็ดพวกเจ้าจงมีการประชุมบริสุทธิ์ เจ้าอย่าทํางานหนักในวันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 26, 'ในวันถวายผลรุ่นแรก เมื่อเจ้าเอาข้าวใหม่มาเป็นธัญญบูชาถวายแด่พระเยโฮวาห์ในเทศกาลสัปดาห์นั้น เจ้าจงมีการประชุมบริสุทธิ์ เจ้าอย่าทํางานหนักในวันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 27, 'แต่จงถวายเครื่องเผาบูชาให้เป็นกลิ่นพอพระทัยแด่พระเยโฮวาห์ คือถวายวัวหนุ่มสองตัว แกะผู้ตัวหนึ่ง ลูกแกะอายุหนึ่งขวบเจ็ดตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 28, 'และถวายยอดแป้งคลุกน้ํามันเป็นธัญญบูชา คือสําหรับวัวตัวหนึ่งถวายแป้งสามในสิบเอฟาห์ สําหรับแกะผู้หนึ่งตัวนั้นสองในสิบเอฟาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 29, 'สําหรับลูกแกะเจ็ดตัว ตัวละหนึ่งในสิบเอฟาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 30, 'พร้อมกับลูกแพะผู้ตัวหนึ่งสําหรับลบมลทินของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 31, 'นอกจากเครื่องเผาบูชาเนืองนิตย์และธัญญบูชาคู่กันนั้น เจ้าจงถวายเครื่องบูชาเหล่านี้และเครื่องดื่มบูชาคู่กันด้วย (ดูให้ดีว่าให้ปราศจากตําหนิ)”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 1, '“ในวันที่หนึ่งเดือนที่เจ็ดเจ้าจงมีการประชุมบริสุทธิ์ เจ้าอย่าทํางานหนัก เป็นวันให้เจ้าทั้งหลายเป่าแตร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 2, 'เจ้าจงถวายเครื่องเผาบูชา เป็นกลิ่นที่พอพระทัยพระเยโฮวาห์ คือถวายวัวหนุ่มตัวหนึ่ง แกะผู้ตัวหนึ่ง ลูกแกะอายุหนึ่งขวบไม่มีตําหนิเจ็ดตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 3, 'และถวายยอดแป้งคลุกน้ํามันเป็นธัญญบูชา คือสําหรับวัวผู้นั้นจงถวายแป้งสามในสิบเอฟาห์ สําหรับแกะผู้ตัวนั้นสองในสิบเอฟาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 4, 'ลูกแกะเจ็ดตัว ตัวละหนึ่งในสิบเอฟาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 5, 'และถวายลูกแพะผู้ตัวหนึ่งเป็นเครื่องบูชาไถ่บาป เพื่อลบมลทินบาปของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 6, 'นอกเหนือเครื่องเผาบูชาในแต่ละเดือนและธัญญบูชาคู่กันและเครื่องเผาบูชาประจําวันคู่กับธัญญบูชา และเครื่องดื่มบูชาคู่กัน ตามลักษณะเครื่องบูชาเหล่านี้ เป็นกลิ่นที่พอพระทัย เป็นเครื่องบูชาด้วยไฟถวายแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 7, 'ในวันที่สิบเดือนที่เจ็ดนี้ เจ้าทั้งหลายจงมีการประชุมบริสุทธิ์ เจ้าต้องถ่อมใจลง อย่าทําการงานสิ่งใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 8, 'แต่เจ้าจงถวายเครื่องเผาบูชาแด่พระเยโฮวาห์ ให้เป็นกลิ่นที่พอพระทัย คือถวายวัวหนุ่มตัวหนึ่ง แกะผู้ตัวหนึ่ง ลูกแกะอายุหนึ่งขวบเจ็ดตัว เจ้าอย่าให้มีตําหนิ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 9, 'และยอดแป้งคลุกน้ํามันเป็นธัญญบูชา สําหรับวัวตัวนั้นถวายแป้งสามในสิบเอฟาห์ สําหรับแกะผู้ตัวหนึ่งนั้นสองในสิบเอฟาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 10, 'สําหรับลูกแกะเจ็ดตัวนั้น ตัวละหนึ่งในสิบเอฟาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 11, 'และถวายลูกแพะผู้ตัวหนึ่งเป็นเครื่องบูชาไถ่บาป นอกเหนือเครื่องบูชาไถ่บาปลบมลทินและเครื่องเผาบูชาเนืองนิตย์ซึ่งคู่กับธัญญบูชา และเครื่องดื่มบูชาคู่กัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 12, 'ในวันที่สิบห้าเดือนที่เจ็ดเจ้าทั้งหลายจงมีการประชุมบริสุทธิ์ เจ้าอย่าทํางานหนัก และเจ้าจงมีการเลี้ยงเจ็ดวันแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 13, 'เจ้าจงถวายเครื่องเผาบูชา เครื่องบูชาด้วยไฟ เป็นกลิ่นที่พอพระทัยพระเยโฮวาห์ คือวัวหนุ่มสิบสามตัว แกะผู้สองตัว ลูกแกะอายุหนึ่งขวบสิบสี่ตัว สัตว์เหล่านี้อย่าให้มีตําหนิ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 14, 'และถวายยอดแป้งคลุกน้ํามันเป็นธัญญบูชาคู่กัน สําหรับวัวสิบสามตัว ตัวหนึ่งถวายแป้งสามในสิบเอฟาห์ สําหรับแกะผู้สองตัว ตัวละสองในสิบเอฟาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 15, 'สําหรับลูกแกะสิบสี่ตัว ตัวละหนึ่งในสิบเอฟาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 16, 'และถวายลูกแพะผู้ตัวหนึ่งเป็นเครื่องบูชาไถ่บาป นอกเหนือเครื่องเผาบูชาเนืองนิตย์ ซึ่งคู่กับธัญญบูชาและเครื่องดื่มบูชาคู่กัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 17, 'ในวันที่สองจงถวายวัวหนุ่มสิบสองตัว แกะผู้สองตัว ลูกแกะอายุหนึ่งขวบไม่มีตําหนิสิบสี่ตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 18, 'กับธัญญบูชาและเครื่องดื่มบูชาคู่กันนั้นสําหรับวัว แกะผู้ และลูกแกะนั้นตามจํานวนตามลักษณะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 19, 'และถวายลูกแพะผู้ตัวหนึ่งเป็นเครื่องบูชาไถ่บาป นอกเหนือเครื่องเผาบูชาเนืองนิตย์ ซึ่งคู่กับธัญญบูชาและเครื่องดื่มบูชาคู่กัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 20, 'ในวันที่สามจงถวายวัวสิบเอ็ดตัว แกะผู้สองตัว ลูกแกะอายุหนึ่งขวบไม่มีตําหนิสิบสี่ตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 21, 'กับธัญญบูชาและเครื่องดื่มบูชาคู่กันนั้น สําหรับวัว แกะผู้ และลูกแกะนั้น ตามจํานวนตามลักษณะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 22, 'และถวายแพะผู้ตัวหนึ่งเป็นเครื่องบูชาไถ่บาป นอกเหนือเครื่องเผาบูชาเนืองนิตย์ ซึ่งคู่กับธัญญบูชาและเครื่องดื่มบูชาคู่กัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 23, 'ในวันที่สี่จงถวายวัวสิบตัว แกะผู้สองตัว ลูกแกะอายุหนึ่งขวบไม่มีตําหนิสิบสี่ตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 24, 'กับธัญญบูชาและเครื่องดื่มบูชาคู่กันนั้น สําหรับวัว แกะผู้ และลูกแกะนั้น ตามจํานวนตามลักษณะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 25, 'และถวายลูกแพะผู้ตัวหนึ่งเป็นเครื่องบูชาไถ่บาป นอกเหนือเครื่องเผาบูชาเนืองนิตย์ ซึ่งคู่กับธัญญบูชาและเครื่องดื่มบูชาคู่กัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 26, 'ในวันที่ห้าจงถวายวัวเก้าตัว แกะผู้สองตัว ลูกแกะอายุหนึ่งขวบไม่มีตําหนิสิบสี่ตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 27, 'กับธัญญบูชาและเครื่องดื่มบูชาคู่กันนั้น สําหรับวัว แกะผู้ และลูกแกะนั้น ตามจํานวนตามลักษณะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 28, 'และถวายแพะผู้ตัวหนึ่งเป็นเครื่องบูชาไถ่บาป นอกเหนือเครื่องเผาบูชาเนืองนิตย์ ซึ่งคู่กับธัญญบูชาและเครื่องดื่มบูชาคู่กัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 29, 'ในวันที่หกจงถวายวัวแปดตัว แกะผู้สองตัว ลูกแกะอายุหนึ่งขวบไม่มีตําหนิสิบสี่ตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 30, 'กับธัญญบูชาและเครื่องดื่มบูชาคู่กันนั้น สําหรับวัว แกะผู้ และลูกแกะนั้น ตามจํานวนตามลักษณะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 31, 'และถวายแพะผู้ตัวหนึ่งเป็นเครื่องบูชาไถ่บาป นอกเหนือเครื่องเผาบูชาเนืองนิตย์ ซึ่งคู่กับธัญญบูชาและเครื่องดื่มบูชาคู่กัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 32, 'ในวันที่เจ็ดเจ้าจงถวายวัวเจ็ดตัว แกะผู้สองตัว ลูกแกะอายุหนึ่งขวบไม่มีตําหนิสิบสี่ตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 33, 'กับธัญญบูชาและเครื่องดื่มบูชาคู่กันนั้น สําหรับวัว แกะผู้ และลูกแกะนั้น ตามจํานวนตามลักษณะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 34, 'และถวายแพะผู้ตัวหนึ่งเป็นเครื่องบูชาไถ่บาป นอกเหนือเครื่องเผาบูชาเนืองนิตย์ ซึ่งคู่กับธัญญบูชาและเครื่องดื่มบูชาคู่กัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 35, 'ในวันที่แปดเจ้าจงมีการประชุมอันศักดิ์สิทธิ์ เจ้าอย่าทํางานหนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 36, 'แต่เจ้าจงถวายเครื่องเผาบูชา เครื่องบูชาด้วยไฟ เป็นกลิ่นที่พอพระทัยพระเยโฮวาห์ คือวัวผู้ตัวหนึ่ง แกะผู้ตัวหนึ่ง ลูกแกะอายุหนึ่งขวบไม่มีตําหนิเจ็ดตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 37, 'และถวายธัญญบูชาและเครื่องดื่มบูชาคู่กันนั้น สําหรับวัว แกะผู้ และลูกแกะนั้น ตามจํานวนตามลักษณะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 38, 'และถวายแพะผู้ตัวหนึ่งเป็นเครื่องบูชาไถ่บาป นอกเหนือเครื่องเผาบูชาเนืองนิตย์ ซึ่งคู่กับธัญญบูชาและเครื่องดื่มบูชาคู่กัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 39, 'สิ่งเหล่านี้เจ้าทั้งหลายจงถวายแด่พระเยโฮวาห์ตามเทศกาลกําหนดของเจ้า เพิ่มเข้ากับการถวายตามคําปฏิญาณของเจ้า และการถวายด้วยใจสมัครของเจ้า เป็นเครื่องเผาบูชาของเจ้า เครื่องธัญญบูชาของเจ้า เครื่องดื่มบูชาของเจ้า และเครื่องสันติบูชาของเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 40, 'และโมเสสได้บอกคนอิสราเอลตามที่พระเยโฮวาห์ได้ทรงบัญชาท่านไว้ทุกประการ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 1, 'โมเสสได้พูดกับหัวหน้าตระกูลเกี่ยวกับคนอิสราเอลว่า “นี่เป็นสิ่งที่พระเยโฮวาห์ได้ทรงบัญชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 2, 'เมื่อชายผู้ใดปฏิญาณไว้กับพระเยโฮวาห์ หรือให้สัตย์สาบานผูกมัดตัวไว้ด้วยคําสัญญาอย่างหนึ่งอย่างใด อย่าให้เขาเสียวาจา เขาต้องกระทําตามคําที่ออกจากปากของเขาทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 3, 'หรือเมื่อสตรีคนหนึ่งคนใดปฏิญาณไว้แด่พระเยโฮวาห์ และผูกมัดตัวเองไว้ด้วยคําสัญญา เมื่อเธอยังสาวอยู่ในเรือนของบิดา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 4, 'และบิดาของเธอได้ยินคําที่เธอปฏิญาณไว้และคําสัญญาที่เธอผูกมัดตัวเอง แต่มิได้พูดอะไรกับเธอ ก็ให้คําที่ปฏิญาณไว้นั้นทั้งสิ้นคงอยู่ และให้คําสัญญาที่ผูกมัดเธอไว้นั้นทุกอย่างคงอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 5, 'แต่ถ้าบิดาของเธอคัดค้านในวันที่เขาได้ยินนั้น การที่เธอปฏิญาณไว้ก็ดี คําสัญญาที่ผูกมัดเธอไว้ก็ดี ย่อมไม่คงอยู่ และพระเยโฮวาห์จะทรงอภัยให้แก่เธอ เพราะบิดาของเธอได้คัดค้านเธอไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 6, 'และถ้านางแต่งงานมีสามีแล้ว สิ่งที่นางปฏิญาณไว้หรือกล่าวด้วยริมฝีปากที่ไม่ทันคิดซึ่งผูกมัดนาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 7, 'ฝ่ายสามีก็ได้ยินแล้ว และในวันที่ได้ยินเขาก็มิได้พูดอะไรกับนาง สิ่งที่นางปฏิญาณไว้นั้นและคําสัญญาที่ผูกมัดนางย่อมคงอยู่ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 8, 'แต่ถ้าในวันนั้นที่สามีมาได้ยินนางและเขาคัดค้าน ก็ทําให้คําที่นางปฏิญาณไว้นั้นเป็นโมฆะ ทั้งคํากล่าวด้วยริมฝีปากที่ไม่ทันคิดของนาง ซึ่งผูกมัดนางนั้นก็เป็นโมฆะด้วย และพระเยโฮวาห์จะทรงอภัยให้แก่นาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 9, 'แต่คําปฏิญาณที่หญิงม่ายหรือแม่ร้างกระทําไว้หรือคําใดที่นางพูดผูกมัดตนเอง คําพูดนั้นย่อมคงอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 10, 'และถ้านางปฏิญาณไว้ในบ้านสามีของนาง หรือให้สัญญาด้วยสัตย์สาบานผูกมัดตนเองไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 11, 'และสามีของนางได้ยินแล้ว แต่ไม่ว่าอะไรแก่นาง และไม่คัดค้านนาง คําปฏิญาณของนางทั้งสิ้นย่อมคงอยู่ และคําสัญญาทุกอย่างซึ่งนางผูกมัดตัวเองย่อมคงอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 12, 'แต่ถ้าสามีของนางได้กระทําให้ไม่คงอยู่หรือเป็นโมฆะในวันที่เขาได้ยินแล้ว สิ่งใดที่ออกจากริมฝีปากของนางเกี่ยวด้วยคําปฏิญาณหรือเกี่ยวด้วยคําสัญญาของนางย่อมไม่คงอยู่ สามีของนางได้กระทําให้เป็นโมฆะ และพระเยโฮวาห์จะทรงอภัยให้แก่นาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 13, 'คําปฏิญาณหรือคําสัตย์สาบานผูกมัดทั้งสิ้นที่ทําให้นางถ่อมใจ สามีของนางย่อมให้คงอยู่หรือให้เป็นโมฆะได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 14, 'แต่ถ้าสามีของนางไม่กล่าวสิ่งใดแก่นางวันแล้ววันเล่า เขาย่อมกระทําให้คําปฏิญาณและคําสัญญาทั้งสิ้นของนาง ซึ่งจะตกแก่นางให้คงอยู่ เพราะเขาไม่พูดสิ่งใดในวันที่เขาได้ยิน เขาจึงกระทําให้คงอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 15, 'แต่ถ้าภายหลังที่เขาได้ยินแล้วมากระทําให้ไม่คงอยู่หรือเป็นโมฆะ เขาย่อมต้องรับโทษความชั่วช้าของนาง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 16, 'ข้อความเหล่านี้เป็นกฎเกณฑ์ซึ่งพระเยโฮวาห์ทรงบัญชาโมเสสไว้ เป็นเรื่องระหว่างชายกับภรรยาของเขา เรื่องระหว่างบิดากับบุตรสาว ขณะเมื่อเธอยังสาวอยู่ ยังอยู่ในเรือนบิดาของเธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 1, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 2, '“จงแก้แค้นคนมีเดียนเพื่อคนอิสราเอล แล้วภายหลังเจ้าจะถูกรวบให้ไปอยู่กับประชาชนของเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 3, 'และโมเสสกล่าวกับประชาชนว่า “จงเตรียมคนบางคนในพวกเจ้าให้พร้อมด้วยอาวุธเพื่อทําสงคราม แล้วยกไปสู้พวกมีเดียนเพื่อกระทําการแก้แค้นของพระเยโฮวาห์ต่อคนมีเดียน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 4, 'เจ้าจงส่งคนจากตระกูลอิสราเอลทั้งหมดตระกูลละพันคนเข้าทําสงคราม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 5, 'ดังนั้นเขาจึงจัดคนจากอิสราเอลที่นับเป็นพันๆนั้นตระกูลละพันคน เป็นคนหมื่นสองพันพร้อมสรรพด้วยอาวุธเพื่อเข้าสงคราม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 6, 'และโมเสสส่งคนตระกูลละพันคนออกไปทําสงคราม ทั้งคนเหล่านั้นกับฟีเนหัสบุตรชายเอเลอาซาร์ปุโรหิตไปทําสงคราม พร้อมกับเครื่องใช้อันบริสุทธิ์ และมีแตรปลุกอยู่ในมือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 7, 'เขาทําสงครามต่อสู้คนมีเดียนดังที่พระเยโฮวาห์ทรงบัญชาโมเสสและได้ฆ่าผู้ชายเสียทุกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 8, 'เขาได้ประหารชีวิตบรรดากษัตริย์คนมีเดียนพร้อมกับคนอื่นที่เขาฆ่าเสีย มีเอวี เรเคม ศูร์ เฮอร์ และเรบา กษัตริย์ทั้งห้าแห่งคนมีเดียน และได้ประหารชีวิตบาลาอัมบุตรชายเบโอร์เสียด้วยดาบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 9, 'และคนอิสราเอลได้จับสตรีชาวมีเดียนทั้งหมดมาเป็นเชลย พร้อมกับพวกเด็กเล็กทั้งหลาย และกวาดเอาฝูงวัวฝูงแพะแกะและข้าวของทั้งปวงไปสิ้น เป็นทรัพย์ที่ปล้นได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 10, 'และเอาไฟเผาบรรดาเมืองที่อาศัยของเขา และเผาค่ายทั้งสิ้นของเขาเสียด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 11, 'แล้วเก็บบรรดาของที่ริบได้และทรัพย์ที่ปล้นได้ทั้งคนและสัตว์ไปเสียสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 12, 'แล้วเขานําเชลยและทรัพย์สินที่ปล้นได้กับของที่ริบได้ทั้งหมดมายังโมเสส และเอเลอาซาร์ปุโรหิต และชุมนุมชนอิสราเอลที่ค่าย ณ ที่ราบโมอับ ริมแม่น้ําจอร์แดนใกล้เมืองเยรีโค');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 13, 'โมเสสและเอเลอาซาร์ปุโรหิตและบรรดาประมุขแห่งชุมนุมชนออกไปต้อนรับเขานอกค่าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 14, 'และโมเสสโกรธพวกนายทหาร คือนายพันและนายร้อยผู้กลับจากการทําสงคราม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 15, 'โมเสสพูดกับเขาทั้งหลายว่า “ท่านทั้งหลายได้ไว้ชีวิตพวกผู้หญิงทั้งหมดหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 16, 'ดูเถิด โดยคําปรึกษาของบาลาอัม หญิงเหล่านี้ได้กระทําให้คนอิสราเอลหลงกระทําการละเมิดต่อพระเยโฮวาห์ในเรื่องเปโอร์ และภัยพิบัติจึงได้เกิดขึ้นท่ามกลางชุมนุมชนของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 17, 'ฉะนั้นบัดนี้จงประหารชีวิตเด็กผู้ชายเสียทุกคน และประหารชีวิตผู้หญิงซึ่งได้เคยนอนร่วมกับชายเสียทุกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 18, 'แต่จงไว้ชีวิตเด็กผู้หญิงที่ยังไม่เคยนอนร่วมกับชายไว้สําหรับท่านทั้งหลายเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 19, 'จงอยู่ภายนอกค่ายเจ็ดวัน ท่านผู้ใดที่ได้ฆ่าคน และท่านผู้ใดที่ได้แตะต้องผู้ที่ถูกฆ่า จงชําระตัวและเชลยของตัวในวันที่สามและวันที่เจ็ด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 20, 'ท่านต้องชําระเครื่องแต่งกายทุกชิ้น เครื่องหนังสัตว์ทุกชิ้น และเครื่องขนแพะทั้งหมดและเครื่องที่ทําด้วยไม้ทุกชิ้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 21, 'และเอเลอาซาร์ปุโรหิตได้กล่าวแก่ทหารผู้ออกไปทําสงครามว่า “นี่เป็นกฎพระราชบัญญัติซึ่งพระเยโฮวาห์ได้บัญชาโมเสส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 22, 'เฉพาะทองคํา เงิน ทองเหลือง เหล็ก ดีบุก และตะกั่ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 23, 'ทุกสิ่งที่ทนไฟได้ เจ้าทั้งหลายจงลนเสียด้วยไฟ แล้วจะสะอาด ถึงอย่างไรก็จะต้องชําระล้างให้บริสุทธิ์ด้วยน้ําแห่งการแยกตั้งไว้ และทุกสิ่งที่ทนไฟไม่ได้ท่านต้องให้ผ่านน้ํานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 24, 'ท่านต้องซักเสื้อผ้าของท่านในวันที่เจ็ด และท่านจะสะอาด ภายหลังท่านจึงจะเข้ามาในค่ายได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 25, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 26, '“เจ้าและเอเลอาซาร์ปุโรหิตกับบรรดาหัวหน้าของชุมนุมชน จงนับสิ่งของที่ได้มาทั้งคนและสัตว์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 27, 'และแบ่งสิ่งของเหล่านั้นออกเป็นสองส่วน ให้ทหารผู้ออกไปทําสงครามส่วนหนึ่ง และให้บรรดาชุมนุมชนนี้อีกส่วนหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 28, 'และจงชักส่วนหนึ่งจากทหารที่ออกไปทําสงครามเป็นของถวายแด่พระเยโฮวาห์ ห้าร้อยชักหนึ่ง ทั้งคนและวัว และลาและฝูงแพะแกะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 29, 'จงเอาจากครึ่งส่วนของเขา มอบให้แก่เอเลอาซาร์ปุโรหิตเป็นเครื่องบูชาแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 30, 'และจากครึ่งส่วนของคนอิสราเอลนั้น เจ้าจงนําห้าสิบชักหนึ่งจากคน ฝูงวัว ฝูงลา และฝูงแพะแกะ และสัตว์ทั้งหมด มอบให้แก่คนเลวีผู้ดูแลพลับพลาของพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 31, 'และโมเสสกับเอเลอาซาร์ปุโรหิตได้กระทําตามที่พระเยโฮวาห์ทรงบัญชาแก่โมเสส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 32, 'บรรดาทรัพย์ที่ปล้นได้อันเหลือจากสิ่งที่ทหารริบมาได้นั้น คือ แกะหกแสนเจ็ดหมื่นห้าพันตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 33, 'วัวเจ็ดหมื่นสองพันตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 34, 'ลาหกหมื่นหนึ่งพันตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 35, 'และคน คือผู้หญิงที่ยังไม่เคยนอนร่วมกับชาย ทั้งหมดมีสามหมื่นสองพันคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 36, 'และในครึ่งส่วนได้ของคนที่ออกไปทําสงคราม มีแกะสามแสนสามหมื่นเจ็ดพันห้าร้อยตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 37, 'และส่วนแกะที่เป็นของพระเยโฮวาห์มีหกร้อยเจ็ดสิบห้าตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 38, 'มีวัวสามหมื่นหกพันตัว วัวอันเป็นส่วนของพระเยโฮวาห์เจ็ดสิบสองตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 39, 'มีลาสามหมื่นห้าร้อยตัว ซึ่งเป็นส่วนของพระเยโฮวาห์หกสิบเอ็ดตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 40, 'ส่วนคนนั้นมีหนึ่งหมื่นหกพัน ซึ่งเป็นส่วนของพระเยโฮวาห์สามสิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 41, 'โมเสสได้มอบส่วนที่ชักมาซึ่งเป็นของถวายแด่พระเยโฮวาห์นั้นแก่เอเลอาซาร์ปุโรหิตตามที่พระเยโฮวาห์ทรงบัญชาไว้กับโมเสส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 42, 'จากครึ่งส่วนของคนอิสราเอลซึ่งโมเสสได้แบ่งมาจากส่วนที่ทหารไปทําสงครามได้มานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 43, '(ครึ่งส่วนของชุมนุมชน คือ แกะสามแสนสามหมื่นเจ็ดพันห้าร้อยตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 44, 'วัวสามหมื่นหกพันตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 45, 'ลาสามหมื่นห้าร้อยตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 46, 'และคนหนึ่งหมื่นหกพันคน)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 47, 'จากครึ่งส่วนของคนอิสราเอลนั้นโมเสสได้เอาส่วนห้าสิบชักหนึ่ง ทั้งคนและสัตว์ มอบให้แก่คนเลวีผู้ดูแลพลับพลาของพระเยโฮวาห์ ดังที่พระเยโฮวาห์ทรงบัญชาโมเสสไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 48, 'แล้วนายทหารผู้บังคับกองพันทั้งปวง คือนายพันนายร้อยได้เข้ามาใกล้โมเสส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 49, 'และกล่าวแก่โมเสสว่า “คนใช้ของท่านได้ตรวจนับทหารผู้อยู่ใต้บังคับบัญชาของข้าพเจ้าทั้งหลายแล้วไม่มีคนหายไปสักคนเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 50, 'และข้าพเจ้าทั้งหลายได้นําส่วนที่ถวายแด่พระเยโฮวาห์ ซึ่งต่างคนต่างได้มา คือ สิ่งที่ทําด้วยทองคํา มีกําไลขาและสร้อยคอ แหวนตรา ตุ้มหู และกําไล เพื่อทําการลบมลทินบาปของพวกเราทั้งหลายต่อพระพักตร์พระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 51, 'โมเสสและเอเลอาซาร์ปุโรหิตก็รับบรรดาสิ่งของที่ทําด้วยทองคําจากเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 52, 'และทองคําทั้งสิ้นจากเครื่องถวายซึ่งเขาได้ถวายแด่พระเยโฮวาห์ จากนายพันและนายร้อย มีน้ําหนักหนึ่งหมื่นหกพันเจ็ดร้อยห้าสิบเชเขล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 53, '(ทหารเหล่านั้นต่างคนต่างได้เก็บข้าวของของข้าศึกมา)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 54, 'โมเสสและเอเลอาซาร์ปุโรหิตได้รับทองคําจากนายพันนายร้อย นํามาในพลับพลาแห่งชุมนุม เป็นที่ระลึกแก่คนอิสราเอลต่อพระพักตร์พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 1, 'คนรูเบนและคนกาดมีฝูงวัวเป็นอันมาก เขาได้เห็นแผ่นดินยาเซอร์และแผ่นดินกิเลอาด ดูเถิด ที่นั่นเป็นที่เหมาะแก่ฝูงสัตว์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 2, 'ดังนั้นคนกาดและคนรูเบนจึงมาหาโมเสสและเอเลอาซาร์ปุโรหิตและประมุขของชุมนุมชนกล่าวว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 3, '“อาทาโรท ดีโบน ยาเซอร์ นิมราห์ เฮชโบน เอเลอาเลห์ เสบาม เนโบ และเบโอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 4, 'เป็นแผ่นดินซึ่งพระเยโฮวาห์ทรงทําลายต่อหน้าคนอิสราเอล เป็นแผ่นดินเหมาะกับฝูงสัตว์ และข้าพเจ้าทั้งหลายคนใช้ของท่านมีฝูงวัว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 5, 'และเขาทั้งหลายกล่าวว่า “ถ้าข้าพเจ้าทั้งหลายได้รับความกรุณาในสายตาของท่าน ขอมอบแผ่นดินนี้เป็นกรรมสิทธิ์แก่คนใช้ของท่าน ขออย่าพาข้าพเจ้าทั้งหลายข้ามแม่น้ําจอร์แดนไปเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 6, 'แต่โมเสสพูดกับคนกาดและคนรูเบนว่า “ควรให้พี่น้องของท่านไปทําสงคราม ฝ่ายพวกท่านจะยับยั้งอยู่ที่นี่อย่างนั้นหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 7, 'ทําไมท่านทั้งหลายกระทําให้จิตใจของคนอิสราเอลท้อถอยที่จะยกข้ามไปยังแผ่นดินซึ่งพระเยโฮวาห์ได้ทรงประทานแก่เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 8, 'บิดาของท่านทั้งหลายได้กระทําเช่นนี้ เมื่อเราใช้เขาไปจากคาเดชบารเนียให้สอดแนมดูแผ่นดินนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 9, 'เมื่อเขาขึ้นไปยังหุบเขาเอชโคล์ และได้เห็นแผ่นดินนั้นแล้ว เขาก็กระทําให้จิตใจคนอิสราเอลท้อถอยที่จะยกเข้าไปในแผ่นดินซึ่งพระเยโฮวาห์ได้ทรงประทานแก่เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 10, 'ในวันนั้นพระเยโฮวาห์ทรงกริ้วเขานัก พระองค์ทรงตั้งสัตย์ปฏิญาณไว้ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 11, '‘แน่ทีเดียวที่ทุกคนซึ่งยกออกจากอียิปต์อายุตั้งแต่ยี่สิบปีขึ้นไป จะมิได้เห็นแผ่นดินซึ่งเราได้ตั้งสัตย์ปฏิญาณที่จะมอบให้อับราฮัม อิสอัค และยาโคบ เพราะเขาทั้งหลายมิได้ตามเราด้วยใจจริง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 12, 'เว้นแต่คาเลบบุตรชายเยฟุนเนห์คนเคนัสและโยชูวาบุตรชายนูน เพราะว่าเขาทั้งสองตามพระเยโฮวาห์ด้วยใจจริง’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 13, 'และความกริ้วโกรธของพระเยโฮวาห์ก็พลุ่งขึ้นต่ออิสราเอล พระองค์จึงทรงให้เขาเร่ร่อนอยู่ในถิ่นทุรกันดารสี่สิบปี จนชั่วอายุที่กระทําชั่วในสายพระเนตรของพระเยโฮวาห์ถูกผลาญไปหมดสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 14, 'และดูเถิด ท่านได้เติบโตขึ้นมาแทนบิดาของท่าน เป็นเชื้อสายคนบาปที่จะทวีพระพิโรธของพระเยโฮวาห์ต่ออิสราเอลให้มากยิ่งขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 15, 'เพราะว่าถ้าท่านทั้งหลายหันจากการตามพระองค์ พระองค์จะทรงทอดทิ้งเขาทั้งหลายในถิ่นทุรกันดารอีก และท่านทั้งหลายจะทําลายชนชาติทั้งหมดนี้เสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 16, 'แล้วเขาทั้งหลายเข้ามาใกล้ท่านกล่าวว่า “ข้าพเจ้าทั้งหลายจะสร้างคอกสําหรับฝูงแพะแกะที่นี่ และสร้างเมืองสําหรับลูกเด็กเล็กๆทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 17, 'แต่เราทั้งหลายจะถืออาวุธพร้อมที่จะไปข้างหน้าคนอิสราเอล จนกว่าเราทั้งหลายจะนําเขาไปถึงที่ของเขา เด็กเล็กของเราจะได้อยู่ในเมืองที่มีกําแพงล้อมรอบเพราะกลัวชาวแผ่นดินนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 18, 'เราทั้งหลายจะไม่ยอมกลับบ้านจนกว่าคนอิสราเอลจะได้รับมรดกของเขาทุกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 19, 'เพราะเราจะมิได้รับมรดกกับเขาซึ่งอยู่ฟากแม่น้ําจอร์แดนข้างโน้นและนอกออกไป เพราะว่ามรดกที่ตกทอดมาถึงเราอยู่ฟากแม่น้ําจอร์แดนข้างตะวันออกนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 20, 'โมเสสจึงกล่าวแก่เขาทั้งหลายว่า “ถ้าท่านทั้งหลายจะกระทําเช่นนี้ คือหยิบอาวุธขึ้นเข้าสู่สงครามต่อพระพักตร์พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 21, 'และคนของท่านที่ถืออาวุธทุกคนจะข้ามแม่น้ําจอร์แดนไปต่อพระพักตร์พระเยโฮวาห์ จนกว่าพระองค์จะทรงขับไล่ศัตรูให้พ้นพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 22, 'และแผ่นดินนั้นจะพ่ายแพ้ต่อพระพักตร์พระเยโฮวาห์แล้ว ภายหลังท่านจึงจะกลับและพ้นจากพันธะที่มีต่อพระเยโฮวาห์และอิสราเอล และแผ่นดินนี้จะตกเป็นกรรมสิทธิ์ของท่านต่อพระพักตร์พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 23, 'แต่ถ้าท่านทั้งหลายมิได้กระทําเช่นนี้ ดูเถิด ท่านทั้งหลายได้กระทําบาปต่อพระเยโฮวาห์ จงรู้แน่เถิดว่า บาปของท่านก็จะตามทัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 24, 'จงสร้างเมืองสําหรับเด็กเล็กๆทั้งหลายของท่าน และสร้างคอกสําหรับแพะแกะของท่าน และกระทําตามคําที่ออกจากปากของท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 25, 'และคนกาดกับคนรูเบนกล่าวแก่โมเสสว่า “คนใช้ของท่านจะกระทําดังที่เจ้านายของข้าพเจ้าบัญชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 26, 'เด็กเล็กๆทั้งหลาย ภรรยาทั้งหลาย ฝูงสัตว์และสัตว์ใช้งานทั้งหมดของเรา จะอยู่ที่นี่ในเมืองกิเลอาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 27, 'แต่คนใช้ของท่านทุกคนผู้มีอาวุธทําสงครามจะข้ามไปเพื่อสู้รบต่อพระพักตร์พระเยโฮวาห์ ดังที่เจ้านายของข้าพเจ้าสั่ง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 28, 'เกี่ยวกับเรื่องเขาทั้งหลายนี้โมเสสจึงออกคําสั่งแก่เอเลอาซาร์ปุโรหิตและแก่โยชูวาบุตรชายนูน และแก่หัวหน้าตระกูลของคนอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 29, 'และโมเสสกล่าวแก่เขาว่า “ถ้าคนกาดและคนรูเบน ทุกคนผู้มีอาวุธที่จะทําสงครามต่อพระพักตร์พระเยโฮวาห์ จะข้ามแม่น้ําจอร์แดนไปพร้อมกับท่านทั้งหลาย และแผ่นดินนั้นจะพ่ายแพ้ต่อหน้าท่านแล้ว ท่านจงมอบแผ่นดินกิเลอาดให้เป็นกรรมสิทธิ์แก่เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 30, 'แต่ถ้าเขาไม่ถืออาวุธข้ามไปกับท่าน เขาจะต้องได้ส่วนแผ่นดินคานาอันร่วมกับท่านเป็นกรรมสิทธิ์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 31, 'คนกาดกับคนรูเบนตอบว่า “พระเยโฮวาห์ตรัสกับคนใช้ของท่านอย่างไร เราทั้งหลายจะกระทําอย่างนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 32, 'เราจะถืออาวุธข้ามไปต่อพระพักตร์พระเยโฮวาห์สู่แผ่นดินคานาอัน และที่ดินมรดกของเรานั้นจะคงอยู่ฟากแม่น้ําจอร์แดนข้างนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 33, 'โมเสสได้มอบดินแดนเหล่านี้แก่คนกาด และแก่คนรูเบน และแก่ครึ่งหนึ่งของตระกูลมนัสเสห์บุตรชายโยเซฟ คืออาณาจักรของสิโหนกษัตริย์แห่งคนอาโมไรต์ และอาณาจักรของโอกกษัตริย์แห่งบาชาน ทั้งแผ่นดินและหัวเมืองตลอดพรมแดน คือหัวเมืองใหญ่ในแผ่นดินนี้ตลอดประเทศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 34, 'และคนกาดก็สร้างเมืองดีโบน อาทาโรท อาโรเออร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 35, 'อัทโรท โชฟาน ยาเซอร์ โยกเบฮาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 36, 'เบธนิมราห์ และเบธฮาราน ให้เป็นเมืองมีกําแพงล้อมรอบ และสร้างคอกให้แกะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 37, 'และคนรูเบนก็สร้างเมืองเฮชโบน เอเลอาเลห์ คีริยาธาอิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 38, 'เนโบ และบาอัลเมโอน (ชื่อเหล่านี้ต้องเปลี่ยนใหม่) และสิบมาห์ และตั้งชื่อใหม่ให้แก่เมืองที่เขาสร้างขึ้นนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 39, 'และคนมาคีร์บุตรชายมนัสเสห์เข้าไปยึดเมืองกิเลอาด และขับไล่พวกอาโมไรต์ซึ่งอยู่ในเมืองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 40, 'และโมเสสยกกิเลอาดให้แก่มาคีร์บุตรชายมนัสเสห์และเขาก็เข้าตั้งอยู่ในเมืองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 41, 'และยาอีร์บุตรชายมนัสเสห์ยกไปยึดเมืองเล็กๆของเขาเหล่านั้น และเรียกชื่อว่าฮาโวทยาอีร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 42, 'และโนบาห์ไปยึดเคนาทและชนบทของเมืองนี้ และเรียกว่าเมืองโนบาห์ตามชื่อของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 1, 'ต่อไปนี้เป็นเรื่องระยะทางเดินของคนอิสราเอล เมื่อเขาออกเดินจากแผ่นดินอียิปต์เป็นหมวดหมู่ภายใต้การนําของโมเสสและอาโรน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 2, 'โมเสสได้จดสถานที่ที่เขาออกเดินทีละระยะๆตามพระบัญชาของพระเยโฮวาห์ ต่อไปนี้เป็นระยะตามสถานที่ที่เขาออกเดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 3, 'เขาทั้งหลายพากันเดินจากราเมเสสในเดือนต้น ในวันที่สิบห้าของเดือนต้นนั้น ถัดวันปัสกาไปวันหนึ่งคนอิสราเอลก็ออกเดินด้วยชูมือแห่งชัยชนะท่ามกลางสายตาของชาวอียิปต์ทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 4, 'ขณะนั้นชาวอียิปต์กําลังฝังศพลูกหัวปีทั้งหลายของตน เป็นผู้ที่พระเยโฮวาห์ทรงประหารชีวิตท่ามกลางพวกเขา พระเยโฮวาห์ทรงลงโทษพระทั้งหลายของเขาด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 5, 'ดังนั้นคนอิสราเอลจึงยกเดินจากราเมเสส และตั้งค่ายที่สุคคท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 6, 'และเขาทั้งหลายยกเดินจากสุคคท และตั้งค่ายที่เอธามซึ่งอยู่ชายถิ่นทุรกันดาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 7, 'และเขาทั้งหลายยกเดินจากเอธาม หันกลับไปยังปีหะหิโรท ซึ่งอยู่ตรงหน้าบาอัลเซโฟน และเขาตั้งค่ายที่หน้าเมืองมิกดล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 8, 'และเขาทั้งหลายยกเดินจากหน้าปีหะหิโรท ข้ามกลางทะเลเข้าไปในถิ่นทุรกันดาร และเขาทั้งหลายเดินในถิ่นทุรกันดารเอธามระยะทางสามวัน และมาตั้งค่ายที่มาราห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 9, 'และเขายกเดินจากมาราห์มาถึงเอลิม ที่เอลิมมีน้ําพุสิบสองแห่งและต้นอินทผลัมเจ็ดสิบต้น และเขาตั้งค่ายที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 10, 'เขายกเดินจากเอลิมมาตั้งค่ายที่ทะเลแดง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 11, 'และเขายกเดินจากทะเลแดงมาตั้งค่ายอยู่ในถิ่นทุรกันดารสีน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 12, 'และเขายกเดินจากถิ่นทุรกันดารสีนมาตั้งค่ายที่โดฟคาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 13, 'และเขายกเดินจากโดฟคาห์และตั้งค่ายที่อาลูช');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 14, 'และเขายกเดินจากอาลูชและตั้งค่ายที่เรฟีดิม ที่นั่นไม่มีน้ําให้ประชาชนดื่ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 15, 'และเขายกเดินจากเรฟีดิมและตั้งค่ายในถิ่นทุรกันดารซีนาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 16, 'และเขายกเดินจากถิ่นทุรกันดารซีนายมาตั้งค่ายที่ขิบโรทหัทธาอาวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 17, 'และเขาออกเดินจากขิบโรทหัทธาอาวาห์มาตั้งค่ายที่ฮาเซโรท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 18, 'และเขายกเดินจากฮาเซโรท และตั้งค่ายที่ริทมาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 19, 'และเขายกเดินจากริทมาห์ และตั้งค่ายที่ริมโมนเปเรศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 20, 'และเขายกเดินจากริมโมนเปเรศ และตั้งค่ายที่ลิบนาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 21, 'และเขายกเดินจากลิบนาห์ และตั้งค่ายที่ริสสาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 22, 'และเขายกเดินจากริสสาห์ และตั้งค่ายที่เคเฮลาธาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 23, 'และเขายกเดินจากเคเฮลาธาห์และตั้งค่ายที่ภูเขาเชเฟอร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 24, 'และเขายกเดินจากภูเขาเชเฟอร์ และตั้งค่ายที่ฮาราดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 25, 'และเขายกเดินจากฮาราดาห์ และตั้งค่ายที่มักเฮโลท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 26, 'และเขายกเดินจากมักเฮโลทและตั้งค่ายที่ทาหัท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 27, 'และเขายกเดินจากทาหัท และตั้งค่ายที่เทราห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 28, 'และเขายกเดินจากเทราห์ และตั้งค่ายที่มิทคาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 29, 'และเขายกเดินจากมิทคาห์และตั้งค่ายที่ฮัชโมเนาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 30, 'และเขายกเดินจากฮัชโมเนาห์ และตั้งค่ายที่โมเสโรท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 31, 'และเขายกเดินจากโมเสโรท และตั้งค่ายที่เบเนยาอะคัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 32, 'และเขายกเดินจากเบเนยาอะคันและตั้งค่ายที่โฮร์ฮักกีดกาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 33, 'และเขายกเดินจากโฮร์ฮักกีดกาด และตั้งค่ายที่โยทบาธาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 34, 'และเขายกเดินจากโยทบาธาห์ และตั้งค่ายที่อับโรนาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 35, 'และเขายกเดินจากอับโรนาห์ และตั้งค่ายที่เอซีโอนเกเบอร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 36, 'และเขายกเดินจากเอซีโอนเกเบอร์ และตั้งค่ายในถิ่นทุรกันดารศิน คือคาเดช');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 37, 'และยกเดินจากคาเดชและตั้งค่ายที่ภูเขาโฮร์ ริมแผ่นดินเอโดม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 38, 'และอาโรนปุโรหิตได้ขึ้นบนภูเขาโฮร์ตามพระบัญชาของพระเยโฮวาห์และสิ้นชีวิตที่นั่น ในวันที่หนึ่งเดือนที่ห้าปีที่สี่สิบนับตั้งแต่วันที่คนอิสราเอลยกออกจากประเทศอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 39, 'เมื่ออาโรนสิ้นชีวิตที่ภูเขาโฮร์นั้น มีอายุหนึ่งร้อยยี่สิบสามปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 40, 'และกษัตริย์เมืองอาราด ชาวคานาอัน ผู้ที่อยู่ทางภาคใต้ในแผ่นดินคานาอัน ได้ยินข่าวว่าคนอิสราเอลยกมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 41, 'และเขายกเดินจากภูเขาโฮร์และตั้งค่ายที่ศัลโมนาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 42, 'และเขายกเดินจากศัลโมนาห์ และตั้งค่ายที่ปูโนน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 43, 'และเขายกเดินจากปูโนน และตั้งค่ายที่โอโบท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 44, 'และเขายกเดินจากโอโบท มาตั้งค่ายที่อิเยอาบาริม ในดินแดนโมอับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 45, 'และเขาออกเดินจากไอยิม และตั้งค่ายที่ดีโบนกาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 46, 'และเขายกเดินจากดีโบนกาด และตั้งค่ายที่อัลโมนดิบลาธาอิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 47, 'และเขายกเดินจากอัลโมนดิบลาธาอิม และตั้งค่ายในภูเขาอาบาริมหน้าเนโบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 48, 'และเขายกเดินจากภูเขาอาบาริม และตั้งค่าย ณ ที่ราบโมอับ ริมแม่น้ําจอร์แดนใกล้เมืองเยรีโค');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 49, 'เขาตั้งค่ายอยู่ริมแม่น้ําจอร์แดนตั้งแต่เบธเยชิโมท ไกลไปจนถึงอาเบลชิทธิม ณ ที่ราบโมอับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 50, 'และพระเยโฮวาห์ตรัสกับโมเสส ณ ที่ราบโมอับ ริมแม่น้ําจอร์แดนใกล้เมืองเยรีโคว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 51, '“จงกล่าวแก่คนอิสราเอลว่า เมื่อเจ้าข้ามแม่น้ําจอร์แดนเข้าไปในแผ่นดินคานาอัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 52, 'เจ้าจงขับไล่ชาวเมืองนั้นออกเสียทั้งหมดให้พ้นหน้าเจ้า และทําลายศิลารูปแกะสลักของเขาเสียให้สิ้น และทําลายรูปเคารพที่หล่อของเขาเสียให้สิ้น และทําลายบรรดาปูชนียสถานสูงของเขาเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 53, 'และเจ้าจงขับชาวแผ่นดินนั้นออก และเข้าไปตั้งอยู่ในนั้น เพราะเราได้ให้แผ่นดินนั้นให้เจ้าถือกรรมสิทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 54, 'เจ้าทั้งหลายจงจับฉลากมรดกที่ดินนั้นตามครอบครัวของเจ้า ครอบครัวที่ใหญ่เจ้าจงให้มรดกส่วนใหญ่ ครอบครัวที่ย่อมเจ้าจงให้มรดกส่วนน้อย ดินผืนใดที่ฉลากตกแก่คนใด ก็เป็นของคนนั้น เจ้าจงรับมรดกตามตระกูลของบรรพบุรุษของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 55, 'แต่ถ้าเจ้าทั้งหลายมิได้ขับไล่ชาวเมืองนั้นออกเสียให้พ้นหน้าเจ้า ต่อมาผู้ที่เจ้าให้เหลืออยู่นั้นก็จะเป็นอย่างเสี้ยนในนัยน์ตาของเจ้า และเป็นอย่างหนามอยู่ที่สีข้างของเจ้า และเขาทั้งหลายจะรบกวนเจ้าในแผ่นดินที่เจ้าเข้าอาศัยอยู่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 56, 'และต่อมาเราจะกระทําแก่เจ้าทั้งหลายดังที่เราคิดจะกระทําแก่เขาทั้งหลายนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 1, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 2, '“จงบัญชาคนอิสราเอลว่า เมื่อเจ้าเข้าไปในแผ่นดินคานาอัน (อันเป็นแผ่นดินที่เราให้แก่เจ้าเป็นมรดก คือแผ่นดินคานาอันตามเขตพรมแดนทั้งหมด) นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 3, 'เขตด้านใต้ของเจ้านับจากถิ่นทุรกันดารศินตามด้านเอโดม และอาณาเขตด้านใต้ของเจ้านั้นนับจากปลายทะเลเกลือทางด้านตะวันออก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 4, 'และอาณาเขตของเจ้าจะเลี้ยวไปทางใต้เนินสูงอัครับบิม ข้ามไปยังศิน ไปสุดลงที่ด้านใต้คาเดชบารเนีย เรื่อยไปถึงฮาซารัดดาร์ผ่านเรื่อยไปถึงอัสโมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 5, 'และอาณาเขตจะเลี้ยวจากอัสโมนถึงแม่น้ําอียิปต์ไปสิ้นสุดลงที่ทะเล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 6, 'อาณาเขตตะวันตกเจ้าจะได้ทะเลใหญ่และฝั่งทะเลนั้น นี่จะเป็นเขตด้านตะวันตกของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 7, 'ต่อไปนี้เป็นอาณาเขตด้านเหนือของเจ้า คือจากทะเลใหญ่เจ้าจงทําเครื่องหมายเรื่อยไปถึงภูเขาโฮร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 8, 'จากภูเขาโฮร์เจ้าจงทําเครื่องหมายเรื่อยไปจนถึงทางเข้าเมืองฮามัท และปลายสุดของอาณาเขตด้านนี้คือเศดัด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 9, 'แล้วอาณาเขตจะยื่นไปถึงศิโฟรน ไปสิ้นสุดที่ฮาซาเรนัน นี่เป็นอาณาเขตด้านเหนือของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 10, 'เจ้าจงทําเครื่องหมายอาณาเขตด้านตะวันออกของเจ้าจากฮาซาเรนันถึงเชฟาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 11, 'และอาณาเขตจะลงมาจากเชฟามถึงริบลาห์ข้างตะวันออกของเมืองอายิน และอาณาเขตจะลงมาถึงไหล่ทะเลคินเนเรททางด้านตะวันออก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 12, 'และอาณาเขตจะลงมาถึงแม่น้ําจอร์แดนสุดลงที่ทะเลเกลือ นี่เป็นแผ่นดินของเจ้าตามอาณาเขตโดยรอบ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 13, 'โมเสสบัญชาคนอิสราเอลกล่าวว่า “นี่เป็นแผ่นดินที่เจ้าทั้งหลายจะได้จับฉลากรับเป็นมรดก ซึ่งพระเยโฮวาห์ทรงบัญชาว่า ให้ยกให้แก่ทั้งเก้าตระกูลกับอีกครึ่งตระกูล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 14, 'เพราะว่าตระกูลคนรูเบนตามเรือนบรรพบุรุษ และตระกูลคนกาดตามเรือนบรรพบุรุษได้รับมรดกของเขาแล้ว คนครึ่งตระกูลมนัสเสห์ก็ได้รับมรดกของเขาแล้วด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 15, 'ทั้งสองตระกูลและครึ่งตระกูลนั้นได้รับมรดกของเขาที่ฟากแม่น้ําจอร์แดนข้างนี้ใกล้เมืองเยรีโคด้านตะวันออก ทางดวงอาทิตย์ขึ้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 16, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 17, '“ต่อไปนี้เป็นชื่อบุคคลที่จะแบ่งดินแดนแก่เจ้าทั้งหลาย คือเอเลอาซาร์ปุโรหิต และโยชูวาบุตรชายนูน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 18, 'ท่านจงนําประมุขของคนทุกตระกูลไป แบ่งดินแดนเพื่อเป็นมรดก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 19, 'ต่อไปนี้เป็นชื่อของประมุขเหล่านั้น คาเลบบุตรชายเยฟุนเนห์ จากตระกูลยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 20, 'เชมูเอลบุตรชายอัมมีฮูด จากตระกูลคนสิเมโอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 21, 'เอลีดาดบุตรชายคิสโลน จากตระกูลเบนยามิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 22, 'จากตระกูลคนดานมีประมุขคนหนึ่ง ชื่อบุคคีบุตรชายโยกลี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 23, 'จากลูกหลานของโยเซฟ จากตระกูลคนมนัสเสห์ มีประมุขชื่อฮันนีเอลบุตรชายเอโฟด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 24, 'และจากตระกูลคนเอฟราอิมมีประมุขคนหนึ่งชื่อเคมูเอลบุตรชายชิฟทาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 25, 'จากตระกูลคนเศบูลุนมีประมุขคนหนึ่งชื่อเอลีซาฟานบุตรชายปารนาค');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 26, 'จากตระกูลคนอิสสาคาร์ มีประมุขคนหนึ่งชื่อปัลทีเอลบุตรชายอัสซาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 27, 'และจากตระกูลคนอาเชอร์มีประมุขคนหนึ่งชื่ออาหิฮูดบุตรชายเชโลมี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 28, 'จากตระกูลคนนัฟทาลีมีประมุขคนหนึ่งชื่อเปดาเฮลบุตรชายอัมมีฮูด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 29, 'บุคคลเหล่านี้เป็นคนที่พระเยโฮวาห์ทรงบัญชาให้แบ่งมรดกให้คนอิสราเอลในแผ่นดินคานาอัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 1, 'พระเยโฮวาห์ตรัสกับโมเสส ณ ที่ราบโมอับ ริมแม่น้ําจอร์แดนใกล้เมืองเยรีโคว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 2, '“จงบัญชาคนอิสราเอล ให้เขายกเมืองให้คนเลวีได้อาศัยอยู่จากมรดกที่เขาได้รับนั้นบ้าง และยกทุ่งหญ้ารอบๆเมืองนั้นให้คนเลวีด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 3, 'ให้เมืองนั้นเป็นของเขาเพื่อจะได้อาศัยอยู่ ให้ทุ่งหญ้าเพื่อฝูงสัตว์และทรัพย์สิ่งของและสัตว์ทั้งสิ้นของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 4, 'ทุ่งหญ้าของเมืองที่เจ้ายกให้แก่คนเลวีนั้นให้มีเขตจากกําแพงเมืองและห่างออกไปหนึ่งพันศอกโดยรอบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 5, 'และเจ้าจงวัดภายนอกเมืองสองพันศอกเป็นด้านตะวันออก สองพันศอกเป็นด้านใต้ สองพันศอกเป็นด้านตะวันตก สองพันศอกเป็นด้านเหนือ ให้ตัวเมืองอยู่กลาง นี่เป็นทุ่งหญ้าประจําเมืองเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 6, 'เมืองซึ่งเจ้าจะยกให้แก่คนเลวี คือ เมืองลี้ภัยหกเมือง ซึ่งเจ้าจะอนุญาตให้คนฆ่าคนหนีไปอยู่ และเจ้าจงเพิ่มให้เขาอีกสี่สิบสองเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 7, 'เมืองทั้งหมดที่เจ้ายกให้คนเลวีเป็นสี่สิบแปดหัวเมือง มีทุ่งหญ้าตามเมืองด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 8, 'และหัวเมืองที่เจ้าจะให้เขาจากกรรมสิทธิ์ของคนอิสราเอลนั้น จากตระกูลใหญ่เจ้าก็เอาเมืองมากหน่อย จากตระกูลย่อมเจ้าก็เอาเมืองน้อยหน่อย ทุกตระกูลตามส่วนของมรดกซึ่งเขาได้รับ ให้ยกให้แก่คนเลวี”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 9, 'พระเยโฮวาห์ตรัสกับโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 10, '“จงกล่าวแก่คนอิสราเอลว่า เมื่อเจ้าทั้งหลายข้ามแม่น้ําจอร์แดน เข้าในแผ่นดินคานาอัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 11, 'เจ้าจงเลือกเมืองให้เป็นเมืองลี้ภัยสําหรับเจ้า เพื่อคนที่ได้ฆ่าคนโดยมิได้เจตนาจะหลบหนีไปอยู่ที่นั่นก็ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 12, 'ให้เมืองเหล่านั้นเป็นเมืองลี้ภัยจากผู้ที่อาฆาต เพื่อมิให้คนฆ่าคนจะต้องตายก่อนที่เขาจะยืนต่อหน้าชุมนุมชนเพื่อรับการพิพากษา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 13, 'และเมืองที่เจ้ายกไว้นั้นให้เป็นเมืองลี้ภัยหกเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 14, 'เจ้าจงให้ทางฟากแม่น้ําจอร์แดนข้างนี้สามเมือง และอีกสามเมืองในแผ่นดินคานาอัน ให้เป็นเมืองลี้ภัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 15, 'ทั้งหกเมืองนี้ให้เป็นเมืองลี้ภัยของคนอิสราเอลและสําหรับคนต่างด้าว และสําหรับคนที่อาศัยอยู่ท่ามกลางเขา เพื่อคนหนึ่งคนใดที่ได้ฆ่าเขาโดยมิได้เจตนาจะได้หลบหนีไปที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 16, 'ถ้าผู้ใดตีเขาด้วยเครื่องมือเหล็กจนคนนั้นถึงตาย ผู้นั้นเป็นฆาตกร ให้ประหารชีวิตฆาตกรนั้นเสียเป็นแน่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 17, 'ผู้ใดทุบเขาให้ล้มลงด้วยก้อนหินในมือขนาดฆ่าคนได้ และเขาถึงตาย ผู้นั้นเป็นฆาตกร ให้ประหารชีวิตฆาตกรนั้นเสียเป็นแน่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 18, 'หรือผู้ใดใช้อาวุธไม้ที่อยู่ในมือขนาดฆ่าคนได้ตีเขาล้มลงและคนนั้นถึงตาย ผู้นั้นเป็นฆาตกร ให้ประหารชีวิตฆาตกรนั้นเสียเป็นแน่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 19, 'ให้ผู้อาฆาตโลหิตเองเป็นผู้ประหารชีวิตฆาตกรนั้น ถ้าผู้อาฆาตพบเขาเมื่อใดก็ให้ประหารชีวิตเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 20, 'แต่ถ้าผู้ใดแทงเขาด้วยความเกลียดชัง หรือซุ่มคอยขว้างเขาจนเขาตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 21, 'หรือเพราะเป็นศัตรูกันชกเขาล้มลง จนเขาตาย ให้ประหารชีวิตผู้ที่ชกเขานั้นเสียเป็นแน่ ด้วยว่าเขาเป็นฆาตกร เมื่อผู้อาฆาตโลหิตพบเขาเมื่อใด ก็ให้ประหารชีวิตฆาตกรนั้นเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 22, 'แต่ถ้าผู้ใดโดยมิได้เป็นศัตรูกันแทงเขาทันที หรือเอาอะไรขว้างเขาโดยมิได้คอยซุ่มดักอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 23, 'หรือใช้ก้อนหินขนาดฆ่าคนได้ขว้างถูกเขาเข้าโดยมิได้เห็น และเขาถึงตาย และเขามิได้เป็นศัตรู และมิได้มุ่งทําร้ายเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 24, 'ก็ให้ชุมนุมชนตัดสินความระหว่างผู้ฆ่าและผู้อาฆาตโลหิตตามคําตัดสินนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 25, 'ให้ชุมนุมชนช่วยผู้ฆ่าให้พ้นจากมือผู้อาฆาตโลหิต ให้ชุมนุมชนพาตัวเขากลับไปถึงเมืองลี้ภัยซึ่งเขาได้หนีไปอยู่นั้น ให้เขาอยู่ที่นั่นจนกว่ามหาปุโรหิตผู้ได้ถูกเจิมไว้ด้วยน้ํามันบริสุทธิ์ถึงแก่ความตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 26, 'แต่ถ้าผู้ฆ่าคนออกไปพ้นเขตเมืองลี้ภัย ซึ่งเขาหนีเข้าไปอยู่ในเวลาใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 27, 'และผู้อาฆาตโลหิตพบเขานอกเขตเมืองลี้ภัย และผู้อาฆาตโลหิตได้ฆ่าผู้ฆ่าคนนั้นเสีย ผู้อาฆาตโลหิตจะไม่มีความผิดเนื่องด้วยโลหิตตกของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 28, 'เพราะว่าชายผู้นั้นต้องอยู่ในเขตเมืองลี้ภัยจนมหาปุโรหิตถึงแก่ความตาย ภายหลังเมื่อมหาปุโรหิตถึงแก่ความตายแล้ว ผู้ฆ่าคนนั้นจะกลับไปยังแผ่นดินที่เขาถือกรรมสิทธิ์อยู่ก็ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 29, 'สิ่งเหล่านี้ควรเป็นกฎเกณฑ์แห่งคําตัดสินของเจ้าตลอดชั่วอายุของเจ้าในที่อาศัยทั้งปวงของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 30, 'ผู้ใดฆ่าเขาตาย ให้ประหารชีวิตฆาตกรนั้นเสียตามปากของพยาน แต่อย่าประหารชีวิตผู้ใดด้วยมีพยานปากเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 31, 'ยิ่งกว่านั้นอีก เจ้าอย่ารับค่าไถ่ชีวิตของฆาตกรผู้มีความผิดถึงตายนั้น แต่เขาต้องตายแน่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 32, 'และเจ้าอย่ารับค่าไถ่คนที่หลบหนีไปยังเมืองลี้ภัยเพื่อให้กลับมาอยู่ในแผ่นดินของเขาก่อนที่มหาปุโรหิตสิ้นชีวิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 33, 'ดังนั้นเจ้าจึงไม่กระทําให้แผ่นดินที่เจ้าทั้งหลายอาศัยอยู่มีมลทิน เพราะว่าโลหิตทําให้แผ่นดินเป็นมลทิน และไม่มีสิ่งใดที่จะชําระแผ่นดินให้หมดมลทินที่เกิดขึ้นเพราะโลหิตตกในแผ่นดินนั้นได้ นอกจากโลหิตของผู้ที่ทําให้โลหิตตก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 34, 'เจ้าอย่ากระทําให้เกิดมลทินในแผ่นดินที่เจ้าอาศัยอยู่ ที่เราอยู่ท่ามกลาง เพราะว่าเราคือพระเยโฮวาห์อยู่ท่ามกลางคนอิสราเอล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 1, 'หัวหน้าครอบครัวคนกิเลอาด บุตรชายของมาคีร์ ผู้เป็นบุตรชายของมนัสเสห์ ครอบครัวต่างๆของบุตรชายโยเซฟ เข้ามาใกล้และพูดต่อหน้าโมเสสและต่อหน้าประมุข คือบรรดาหัวหน้าคนอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 2, 'เขาพูดว่า “พระเยโฮวาห์ได้บัญชาเจ้านายของข้าพเจ้าให้จับฉลากยกแผ่นดินให้เป็นมรดกแก่คนอิสราเอล และเจ้านายของข้าพเจ้าได้รับบัญชาจากพระเยโฮวาห์ให้ยกมรดกของเศโลเฟหัดพี่น้องของเราแก่บุตรสาวของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 3, 'ถ้าเธอทั้งหลายแต่งงานกับบุตรชายทั้งหลายของคนอิสราเอลตระกูลอื่นแล้ว ส่วนมรดกของบรรพบุรุษของเราจะเพิ่มให้กับมรดกของคนตระกูลที่เธอไปอยู่ด้วย เพราะฉะนั้นจึงเป็นการที่นํามรดกไปจากส่วนที่เป็นของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 4, 'และเมื่อถึงปีเสียงแตรของคนอิสราเอล มรดกที่เป็นส่วนของเธอก็จะถูกยกไปเพิ่มเข้ากับส่วนของตระกูลที่เธอไปอยู่ด้วย จึงเป็นการที่นําส่วนมรดกของเธอไปจากส่วนมรดกของตระกูลบิดาของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 5, 'และโมเสสบัญชาคนอิสราเอลตามพระดํารัสของพระเยโฮวาห์ว่า “ตระกูลคนโยเซฟพูดถูกต้องแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 6, 'นี่คือสิ่งที่พระเยโฮวาห์ทรงบัญชาเกี่ยวกับบุตรสาวของเศโลเฟหัด ซึ่งว่า ‘จงให้เธอแต่งงานกับใครที่เธอพอใจ แต่เธอต้องแต่งงานกับคนภายในครอบครัวตระกูลบิดาของเธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 7, 'ดังนี้แหละส่วนมรดกของคนอิสราเอลจะไม่ถูกโยกย้ายจากตระกูลหนึ่งไปให้อีกตระกูลหนึ่ง คนอิสราเอลทุกคนต้องอยู่ในที่มรดกแห่งตระกูลบรรพบุรุษของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 8, 'และบุตรสาวทุกคนผู้รับกรรมสิทธิ์มรดกในตระกูลคนอิสราเอลตระกูลใด ให้เป็นภรรยาของคนใดคนหนึ่งในครอบครัวในตระกูลบิดาของตน เพื่อคนอิสราเอลทุกคนจะถือกรรมสิทธิ์มรดกของบิดาของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 9, 'ดังนั้นจะไม่มีมรดกที่ถูกโยกย้ายจากตระกูลหนึ่งไปยังอีกตระกูลหนึ่ง เพราะว่าคนอิสราเอลแต่ละตระกูลควรคงอยู่ในที่มรดกของตน’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 10, 'พระเยโฮวาห์ทรงบัญชาโมเสสอย่างไร บุตรสาวทั้งหลายของเศโลเฟหัดก็กระทําอย่างนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 11, 'เพราะว่ามาลาห์ ทีรซาห์ โฮกลาห์ มิลคาห์ และโนอาห์ บุตรสาวของเศโลเฟหัด ได้แต่งงานกับบุตรชายทั้งหลายของพี่น้องแห่งบิดาของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 12, 'เธอได้แต่งงานกับครอบครัวคนมนัสเสห์บุตรชายของโยเซฟ และส่วนมรดกของเธอก็คงอยู่ในตระกูลแห่งครอบครัวบิดาของเธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 13, 'ข้อความเหล่านี้เป็นบทบัญญัติและคําตัดสินซึ่งพระเยโฮวาห์ได้ทรงบัญชาทางโมเสสแก่คนอิสราเอล ณ ที่ราบโมอับ ริมแม่น้ําจอร์แดนใกล้เมืองเยรีโค');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 1, 'ข้อความต่อไปนี้เป็นคําที่โมเสสกล่าวแก่คนอิสราเอลทั้งปวงที่ในถิ่นทุรกันดารฟากแม่น้ําจอร์แดนข้างนี้ คือในที่ราบข้างหน้าทะเลแดงระหว่างปารานและโทเฟล ลาบัน ฮาเซโรท และดีซาหับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 2, '(หนทางจากโฮเรบตามทางภูเขาเสอีร์จนถึงคาเดชบารเนียนั้นเป็นทางเดินสิบเอ็ดวัน)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 3, 'อยู่มาในวันที่หนึ่งเดือนที่สิบเอ็ดปีที่สี่สิบโมเสสได้กล่าวแก่คนอิสราเอล ตามบรรดาพระดํารัสที่พระเยโฮวาห์ทรงประทานแก่ท่าน เป็นพระบัญญัติให้แก่เขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 4, 'หลังจากที่ท่านได้ฆ่าสิโหนกษัตริย์คนอาโมไรต์ ที่อยู่เมืองเฮชโบน และโอกกษัตริย์เมืองบาชาน ผู้ซึ่งอยู่ในอัชทาโรท ณ ตําบลเอเดรอีนั้นแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 5, 'โมเสสได้เริ่มอธิบายพระราชบัญญัตินี้ที่ในแผ่นดินโมอับฟากแม่น้ําจอร์แดนข้างนี้ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 6, '“พระเยโฮวาห์พระเจ้าของเราได้ตรัสสั่งเราทั้งหลายที่โฮเรบว่า ‘เจ้าทั้งหลายได้พักที่ภูเขานี้นานพอแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 7, 'เจ้าทั้งหลายจงหันไปเดินตามทางที่ไปยังแดนเทือกเขาของคนอาโมไรต์ และที่ใกล้เคียงกันในที่ราบ และในแดนเทือกเขา และในหุบเขา ในทางใต้ และที่ฝั่งทะเล แผ่นดินของคนคานาอัน และที่เลบานอน จนถึงแม่น้ําใหญ่ คือแม่น้ํายูเฟรติส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 8, 'ดูเถิด เราได้ตั้งแผ่นดินนั้นไว้ตรงหน้าเจ้าทั้งหลาย เจ้าทั้งหลายจงเข้าไปยึดครองแผ่นดินซึ่งพระเยโฮวาห์ทรงปฏิญาณกับบรรพบุรุษของเจ้า คืออับราฮัม อิสอัค และยาโคบ ว่าจะให้แก่เขาทั้งหลายและแก่เชื้อสายของเขาที่มาภายหลังเขาด้วย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 9, 'ครั้งนั้นข้าพเจ้าได้บอกท่านทั้งหลายว่า ‘ข้าพเจ้าผู้เดียวแบกพวกท่านทั้งหลายไม่ไหว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 10, 'พระเยโฮวาห์พระเจ้าของท่านได้ทรงให้ท่านทั้งหลายทวีมากขึ้น และดูเถิด ทุกวันนี้พวกท่านทั้งหลายมีจํานวนมากดุจดวงดาวทั้งหลายในท้องฟ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 11, '(ขอพระเยโฮวาห์พระเจ้าแห่งบรรพบุรุษของท่านทั้งหลายทรงกระทําให้ท่านทั้งหลายทวีขึ้นพันเท่าและทรงอํานวยพระพรแก่ท่าน ดังที่พระองค์ได้ทรงสัญญาไว้แก่ท่านทั้งหลายแล้วนั้น)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 12, 'ข้าพเจ้าคนเดียวจะแบกท่านทั้งหลายผู้เป็นภาระและเป็นความยากลําบากและการทุ่มเถียงของท่านทั้งหลายอย่างไรได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 13, 'จงเลือกคนที่มีปัญญา มีความเข้าใจและมีชื่อตามตระกูลของท่านทั้งหลาย และข้าพเจ้าจะตั้งเขาให้เป็นหัวหน้าของท่านทั้งหลาย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 14, 'ท่านทั้งหลายได้ตอบข้าพเจ้าว่า ‘สิ่งที่ท่านกล่าวนั้นดีแล้ว ควรที่ข้าพเจ้าทั้งหลายจะกระทํา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 15, 'ข้าพเจ้าจึงได้เลือกหัวหน้าจากทุกตระกูล ซึ่งเป็นคนมีปัญญาและมีชื่อ ตั้งไว้เป็นใหญ่เหนือท่านทั้งหลาย ให้เป็นนายพัน นายร้อย นายห้าสิบ นายสิบ และพนักงานต่างๆตามตระกูลของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 16, 'ครั้งนั้นข้าพเจ้าได้กล่าวกําชับพวกตุลาการของท่านทั้งหลายว่า ‘จงพิจารณาคดีของพี่น้องและตัดสินความตามยุติธรรมระหว่างชายคนหนึ่งและพี่น้องของตน หรือคนต่างด้าวที่อาศัยอยู่กับท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 17, 'ท่านทั้งหลายอย่าลําเอียงในการพิพากษา จงฟังผู้ใหญ่และผู้น้อยให้เหมือนกัน ท่านทั้งหลายอย่ากลัวหน้ามนุษย์เลย เพราะการพิพากษานั้นเป็นการของพระเจ้า และคดีใดที่ยากเกินไปสําหรับท่านจงนํามาให้ข้าพเจ้า ข้าพเจ้าจะพิจารณาเอง’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 18, 'ครั้งนั้นข้าพเจ้าได้สั่งท่านทั้งหลายถึงบรรดาสิ่งที่ท่านทั้งหลายควรกระทํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 19, 'เราได้ออกไปจากโฮเรบเดินทะลุถิ่นทุรกันดารใหญ่อันเป็นที่น่ากลัวตามที่ท่านทั้งหลายได้เห็นนั้น เดินไปตามแดนเทือกเขาของคนอาโมไรต์ ดังที่พระเยโฮวาห์พระเจ้าของเราได้ตรัสสั่งเราไว้ และเรามาถึงคาเดชบารเนีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 20, 'และข้าพเจ้าได้กล่าวแก่ท่านทั้งหลายว่า ‘ท่านทั้งหลายมาถึงแดนเทือกเขาของคนอาโมไรต์แล้ว เป็นที่ซึ่งพระเยโฮวาห์พระเจ้าของเราประทานแก่เราทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 21, 'ดูเถิด พระเยโฮวาห์พระเจ้าของพวกท่านได้ทรงตั้งแผ่นดินนั้นไว้ตรงหน้าท่านแล้ว จงขึ้นไปยึดแผ่นดินนั้น ดังที่พระเยโฮวาห์พระเจ้าของบรรพบุรุษของพวกท่านได้ตรัสสั่งไว้ อย่ากลัวหรืออย่าตกใจไปเลย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 22, 'แล้วท่านทั้งหลายทุกคนได้เข้ามาหาข้าพเจ้าพูดว่า ‘ให้เราทั้งหลายใช้คนไปก่อนเราและสอดแนมดูแผ่นดินนั้นแทนเรา นําข่าวเรื่องทางที่เราจะต้องขึ้นไป และเรื่องหัวเมืองที่เราจะไปนั้นมาให้เรา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 23, 'เรื่องนั้นข้าพเจ้าเห็นดีด้วย ข้าพเจ้าจึงได้เลือกสิบสองคนมาจากท่านทั้งหลายตระกูลละคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 24, 'แล้วคนเหล่านั้นได้หันไปขึ้นแดนเทือกเขา มาถึงหุบเขาเอชโคล์ และสอดแนมดูที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 25, 'เขาทั้งหลายได้เก็บผลไม้เมืองนั้นติดมือมาให้เราทั้งหลายและนําข่าวมาให้เราว่า ‘ที่ซึ่งพระเยโฮวาห์พระเจ้าของเราประทานแก่เรานั้นเป็นแผ่นดินที่ดี’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 26, 'แต่กระนั้นท่านทั้งหลายก็ไม่ยอมขึ้นไป กลับขัดขืนพระบัญชาของพระเยโฮวาห์พระเจ้าของท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 27, 'และท่านทั้งหลายได้บ่นอยู่ในเต็นท์ของตน และว่า ‘เพราะพระเยโฮวาห์ทรงชังพวกเรา พระองค์จึงทรงพาเราทั้งหลายออกมาจากแผ่นดินอียิปต์ จะได้มอบเราไว้ในมือคนอาโมไรต์เพื่อจะทําลายเราเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 28, 'เราทั้งหลายจะขึ้นไปที่ไหนเล่า พวกพี่น้องของเราได้ทําจิตใจของเราให้ฝ่อท้อถอยไปโดยที่ว่า “คนเหล่านั้นใหญ่กว่าและสูงกว่าพวกเราอีก เมืองเหล่านั้นก็ใหญ่มีกําแพงสูงเทียมฟ้า และยิ่งกว่านั้นเราได้เห็นพวกคนอานาคอยู่ที่นั่นด้วย”’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 29, 'แล้วข้าพเจ้าจึงได้พูดกับท่านทั้งหลายว่า ‘อย่าครั่นคร้ามหรือกลัวเขาเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 30, 'พระเยโฮวาห์พระเจ้าของท่านผู้นําหน้าท่านทั้งหลาย พระองค์จะทรงต่อสู้เผื่อท่านทั้งหลาย ดังที่พระองค์ได้ทรงกระทําให้แก่ท่านทั้งหลายในอียิปต์ต่อหน้าต่อตาท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 31, 'และในถิ่นทุรกันดาร ซึ่งในที่นั้นพวกท่านได้เห็นพระเยโฮวาห์พระเจ้าของท่านทรงอุ้มชูพวกท่าน ดังพ่ออุ้มลูกชายของตน ตลอดทางที่ท่านได้ไปนั้น จนท่านทั้งหลายได้มาถึงที่นี่’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 32, 'แต่อย่างไรก็ตาม ท่านทั้งหลายมิได้เชื่อพระเยโฮวาห์พระเจ้าของท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 33, 'ผู้ได้ทรงนําทางข้างหน้าท่าน เพื่อจะหาที่ให้ท่านทั้งหลายตั้งเต็นท์ของท่าน เป็นไฟในกลางคืน เพื่อโปรดให้ท่านทั้งหลายเห็นทางที่ควรจะไป และเป็นเมฆในกลางวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 34, 'พระเยโฮวาห์ได้ทรงสดับเสียงคําพูดของท่านทั้งหลาย จึงทรงกริ้วและปฏิญาณว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 35, '‘แท้จริงจะไม่มีผู้ใดในยุคที่ชั่วนี้สักคนเดียวที่จะได้เห็นแผ่นดินดีนั้น ที่เราได้ปฏิญาณว่าจะให้แก่บรรพบุรุษของเจ้าทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 36, 'เว้นแต่คาเลบบุตรชายเยฟุนเนห์ เขาจะเห็นแผ่นดินนั้น และเราจะให้แผ่นดินที่เขาได้เหยียบนั้นแก่เขาและแก่ลูกหลาน เพราะเขาได้ตามพระเยโฮวาห์อย่างสุดใจ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 37, 'เพราะเหตุท่านทั้งหลายพระเยโฮวาห์ก็ทรงพระพิโรธเราด้วย ตรัสว่า ‘เจ้าจะไม่ได้เข้าไปในที่นั้นด้วยเหมือนกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 38, 'แต่โยชูวาบุตรชายนูนผู้ยืนอยู่ตรงหน้าเจ้า จะได้เข้าไป จงสนับสนุนเขาเพราะเขาจะพาคนอิสราเอลไปถือกรรมสิทธิ์พื้นดินนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 39, 'ยิ่งกว่านั้นเด็กเล็กของเจ้าทั้งหลายที่เจ้าทั้งหลายว่าจะตกเป็นเหยื่อ และบุตรของเจ้าที่ในวันนี้ยังไม่รู้จักผิดและชอบ จะได้เข้าไปที่นั่น เราจะให้แผ่นดินนั้นแก่เขา และเขาจะถือกรรมสิทธิ์อยู่ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 40, 'แต่ฝ่ายเจ้าทั้งหลายจงกลับเดินเข้าถิ่นทุรกันดาร ตามทางที่ไปสู่ทะเลแดงเถิด’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 41, 'ครั้งนั้นท่านทั้งหลายได้ตอบข้าพเจ้าว่า ‘เราทั้งหลายได้กระทําบาปต่อพระเยโฮวาห์แล้ว เราทั้งหลายจะขึ้นไปสู้รบตามบรรดาพระดํารัสที่พระเยโฮวาห์พระเจ้าของเราทั้งหลายได้ตรัสสั่งนั้น’ และท่านทั้งหลายได้คาดอาวุธเตรียมตัวไว้ทุกคน คิดว่าที่จะขึ้นไปยังแดนเทือกเขานั้นเป็นเรื่องง่าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 42, 'พระเยโฮวาห์ตรัสสั่งข้าพเจ้าว่า ‘จงกล่าวแก่คนทั้งหลายนั้นว่า อย่าขึ้นไปสู้รบเลย เกรงว่าเจ้าทั้งหลายจะแพ้ศัตรู เพราะเรามิได้อยู่ท่ามกลางเจ้าทั้งหลาย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 43, 'ข้าพเจ้าจึงได้กล่าวแก่ท่านดังนั้น และท่านทั้งหลายไม่ฟัง แต่ได้ขัดขืนพระบัญชาของพระเยโฮวาห์ มีใจองอาจและได้ขึ้นไปที่แดนเทือกเขานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 44, 'และคนอาโมไรต์ที่อยู่ในแดนเทือกเขานั้น ได้ออกมาต่อสู้และไล่ตีท่านทั้งหลายดุจฝูงผึ้งไล่ และได้ฆ่าท่านทั้งหลายในตําบลเสอีร์จนถึงโฮรมาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 45, 'และท่านทั้งหลายกลับมาร้องไห้ต่อพระพักตร์พระเยโฮวาห์ แต่พระเยโฮวาห์มิได้ทรงฟังเสียงร้องหรือเงี่ยพระกรรณสดับท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 46, 'ท่านทั้งหลายจึงพักอยู่ที่คาเดชหลายวันตามวันที่ท่านทั้งหลายได้อยู่นั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 1, '“ครั้งนั้นเราทั้งหลายได้หันกลับและเดินเข้าถิ่นทุรกันดารตามทางที่ไปสู่ทะเลแดงตามที่พระเยโฮวาห์สั่งข้าพเจ้า และเราทั้งหลายได้เดินเวียนภูเขาเสอีร์หลายวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 2, 'แล้วพระเยโฮวาห์ตรัสสั่งข้าพเจ้าว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 3, '‘เจ้าทั้งหลายได้เดินเวียนที่แดนเทือกเขานี้นานพอแล้ว จงหันไปเดินทางทิศเหนือเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 4, 'และจงบัญชาคนทั้งปวงว่า เจ้าทั้งหลายจวนจะเดินผ่านเขตแดนเมืองพี่น้องของเจ้า คือลูกหลานของเอซาวที่อยู่ตําบลเสอีร์แล้ว และเขาทั้งหลายจะกลัวพวกเจ้า ฉะนั้นเจ้าทั้งหลายจงระวังตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 5, 'อย่าต่อสู้เขา เพราะเราจะไม่ให้ที่ของเขาแก่เจ้าเลย จะไม่ให้ที่ดินแม้เพียงฝ่าเท้าเหยียบได้ ด้วยว่าภูเขาเสอีร์นั้นเราได้ให้เอซาวยึดครองแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 6, 'เจ้าทั้งหลายจงเอาเงินซื้อเสบียงอาหารจากเขาเพื่อจะได้กิน และจงเอาเงินซื้อน้ําจากเขาด้วยเพื่อจะได้ดื่ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 7, 'เพราะพระเยโฮวาห์พระเจ้าของพวกเจ้าได้อํานวยพระพรแก่บรรดาการที่มือของพวกเจ้าได้กระทํา พระองค์ทรงทราบทางที่เจ้าได้เดินในถิ่นทุรกันดารใหญ่นี้ พระเยโฮวาห์พระเจ้าของพวกเจ้าได้อยู่กับเจ้าสี่สิบปีนี้แล้ว พวกเจ้ามิได้ขัดสนสิ่งใดเลย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 8, 'แล้วเราทั้งหลายได้เดินเลยไปจากพี่น้องของเราพวกลูกหลานเอซาวผู้อยู่ที่เสอีร์ ไปจากทางที่ราบจากเอลัทและจากเอซีโอนเกเบอร์ และเราได้เลี้ยวไปเดินตามทางถิ่นทุรกันดารโมอับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 9, 'และพระเยโฮวาห์ได้ตรัสกับข้าพเจ้าว่า ‘เจ้าทั้งหลายอย่าราวีพวกโมอับหรือสู้รบกับเขาเลย เพราะเราจะไม่ให้ที่ของเขาแก่เจ้าเพื่อยึดครอง ด้วยเราได้ให้ที่ตําบลอาร์นั้นแก่ลูกหลานของโลทให้ปกครองแล้ว’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 10, 'แต่ก่อนคนเอมิมอยู่ที่นั่นเป็นชนชาติใหญ่และมากและสูงอย่างคนอานาค');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 11, 'คนเหล่านี้ได้นับว่าเป็นพวกมนุษย์ยักษ์ เหมือนคนอานาค แต่คนโมอับเรียกชื่อพวกนี้ว่าเอมิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 12, 'เมื่อก่อนพวกโฮรีได้อยู่ที่เสอีร์ด้วย แต่ลูกหลานเอซาวได้มาอยู่แทนเขา และได้ทําลายเขาเสียให้พ้นหน้า และได้อาศัยอยู่ในที่ของเขาเหมือนพวกอิสราเอลได้กระทําแก่เมืองที่พระเยโฮวาห์ประทานให้เขายึดครองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 13, 'ข้าพเจ้ากล่าวว่า ‘บัดนี้เจ้าทั้งหลายจงยกเดินข้ามลําธารเศเรด’ เราทั้งหลายจึงข้ามลําธารเศเรด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 14, 'และนับตั้งแต่เรามาจากคาเดชบารเนีย จนถึงได้ข้ามลําธารเศเรดนั้นได้สามสิบแปดปีจนสิ้นยุคนั้น คือคนทั้งหลายที่จะออกทัพได้นั้นตายหมดจากท่ามกลางค่าย ตามที่พระเยโฮวาห์ทรงปฏิญาณกับเขาไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 15, 'แท้จริงพระหัตถ์พระเยโฮวาห์ได้ทรงต่อสู้เขา เพื่อทรงทําลายเขาจากท่ามกลางค่ายจนเขาทั้งหลายสูญสิ้นหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 16, 'ต่อมาเมื่อคนที่ออกทัพได้มาตายเสียหมดจากท่ามกลางคนเหล่านั้นแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 17, 'พระเยโฮวาห์ได้ตรัสแก่ข้าพเจ้าว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 18, '‘วันนี้เจ้าทั้งหลายจะเดินข้ามตําบลอาร์เขตแดนของคนโมอับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 19, 'และเมื่อเข้าใกล้แนวหน้าของคนอัมโมนอย่าราวีหรือรบกับเขาเลย เพราะเราจะไม่ให้ที่อยู่ของลูกหลานคนอัมโมนแก่เจ้าให้ยึดครองเลย ด้วยเราได้ให้ที่นั่นแก่ลูกหลานของโลทเป็นผู้ยึดครองแล้ว’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 20, '(ทั้งที่นั่นก็นับว่าเป็นแผ่นดินของพวกมนุษย์ยักษ์ แต่ก่อนมนุษย์ยักษ์ได้อยู่ในนั้น แต่คนอัมโมนได้เรียกชื่อของเขาว่าศัมซุมมิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 21, 'คนเหล่านั้นใหญ่และมากและสูงอย่างคนอานาค แต่พระเยโฮวาห์ได้ทรงทําลายเขาเสียให้พ้นหน้า และพวกอัมโมนได้เข้ายึดที่ของเขาและตั้งอยู่แทน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 22, 'เหมือนพระองค์ได้ทรงกระทําให้แก่พวกลูกหลานเอซาวผู้อยู่ที่เสอีร์ เมื่อพระองค์ทรงทําลายพวกโฮรีเสียให้พ้นหน้า และเขาได้ยึดที่ของพวกโฮรีแล้วตั้งอยู่แทนจนทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 23, 'ส่วนชาวอิฟวาห์ที่อยู่ในเฮเซริมจนถึงอาซาห์ คนคัฟโทร์ซึ่งมาจากตําบลคัฟโทร์ ก็ได้ทําลายเขาและตั้งอยู่แทน)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 24, '‘พวกเจ้าจงลุกขึ้นเดินทางไปข้ามลุ่มแม่น้ําอารโนน ดูเถิด เราได้มอบสิโหนชาวอาโมไรต์ผู้เป็นกษัตริย์เมืองเฮชโบน และเมืองของเขาไว้ในมือของพวกเจ้า เจ้าทั้งหลายจงตั้งต้นยึดเมืองนั้นและสู้รบกับเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 25, 'ตั้งแต่วันนี้ไปเราจะให้ชนชาติทั้งหลายทั่วใต้ฟ้าครั่นคร้ามต่อพวกเจ้าและกลัวเจ้า คนต่างชาติผู้จะได้ยินข่าวเรื่องเจ้าจะกลัวตัวสั่นและมีความระทมเพราะเจ้า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 26, 'ฉะนั้นข้าพเจ้าจึงใช้ผู้สื่อสารจากถิ่นทุรกันดารเคเดโมทไปเฝ้าสิโหนกษัตริย์เมืองเฮชโบนนั้น ทูลถ้อยคําอันสันติว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 27, '‘ขอให้ข้าพเจ้าเดินข้ามแผ่นดินของท่าน ข้าพเจ้าจะเดินไปตามทางหลวง จะไม่เลี้ยวไปทางขวามือหรือซ้ายมือเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 28, 'ขอท่านได้ขายเสบียงเอาเงินของข้าพเจ้า เพื่อข้าพเจ้าจะได้กิน และขอขายน้ําเอาเงินของข้าพเจ้า เพื่อข้าพเจ้าจะได้ดื่ม ขอให้ข้าพเจ้าเดินเท้าข้ามประเทศของท่านเท่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 29, '(ดุจพวกลูกหลานเอซาวที่อยู่ตําบลเสอีร์ และพวกโมอับที่อยู่ตําบลอาร์ ได้กระทําแก่ข้าพเจ้านั้น) จนข้าพเจ้าข้ามแม่น้ําจอร์แดนเข้าไปในแผ่นดินที่พระเยโฮวาห์พระเจ้าของข้าพเจ้าทั้งหลายได้ทรงประทานแก่ข้าพเจ้า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 30, 'แต่สิโหนกษัตริย์เมืองเฮชโบน ไม่ยอมให้เราทั้งหลายข้ามประเทศของท่าน เพราะพระเยโฮวาห์พระเจ้าของพวกท่านได้ทรงกระทําจิตใจของสิโหนให้กระด้าง กระทําใจของท่านให้แข็งไป เพื่อจะได้ทรงมอบเขาไว้ในมือของพวกท่าน ดังเป็นอยู่ทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 31, 'และพระเยโฮวาห์ตรัสกับข้าพเจ้าว่า ‘ดูเถิด เราได้เริ่มมอบสิโหนและเมืองของเขาไว้กับเจ้า จงตั้งต้นเข้ายึดครองที่นั่นเพื่อเจ้าจะได้แผ่นดินของเขาเป็นกรรมสิทธิ์’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 32, 'แล้วสิโหนยกออกมาต่อสู้กับเรา ทั้งท่านและพลโยธาทั้งหลายของท่านที่ตําบลยาฮาส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 33, 'และพระเยโฮวาห์พระเจ้าของเราทั้งหลายได้ทรงมอบท่านไว้ต่อหน้าเรา และเราได้ตีทําลายท่านกับโอรสและพลโยธาทั้งหลายของท่านเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 34, 'ครั้งนั้นเราได้ยึดเมืองทั้งปวงของท่าน และเราได้ทําลายเสียสิ้น คือผู้ชายผู้หญิงและเด็กทั้งหลายในทุกเมือง ไม่ให้มีเหลือเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 35, 'แต่ฝูงสัตว์เราได้ยึดมาเป็นของเรา ทั้งของริบได้ในเมืองเหล่านั้นที่เราตีมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 36, 'ตั้งแต่อาโรเออร์ที่อยู่ริมลุ่มแม่น้ําอารโนนและตั้งแต่เมืองที่อยู่ในลุ่มแม่น้ํานั้นจนถึงเมืองกิเลอาด ไม่มีเมืองใดที่ต่อต้านเราได้ พระเยโฮวาห์พระเจ้าของเราได้ทรงมอบทั้งหมดไว้แก่เรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 37, 'แต่ท่านทั้งหลายมิได้เข้าใกล้แผ่นดินคนอัมโมน คือฝั่งแม่น้ํายับบอกและเมืองที่อยู่บนภูเขา และที่ใดๆซึ่งพระเยโฮวาห์พระเจ้าของเราตรัสห้ามเรานั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 1, '“เราทั้งหลายจึงได้หันไปขึ้นทางสู่เมืองบาชาน แล้วโอกกษัตริย์เมืองบาชานก็ออกมาสู้รบกับเรา ตัวโอกเองและพลโยธาทั้งหมดของท่านมารบกับเราที่ตําบลเอเดรอี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 2, 'แต่พระเยโฮวาห์ตรัสกับข้าพเจ้าว่า ‘เจ้าอย่ากลัวเขาเลย เพราะเราจะมอบเขากับพลโยธาทั้งหมดของเขาและแผ่นดินของเขาไว้ในมือของเจ้า เจ้าจะกระทําแก่เขาเหมือนเจ้าได้กระทําแก่สิโหนกษัตริย์ของคนอาโมไรต์ซึ่งอยู่ตําบลเฮชโบนนั้น’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 3, 'พระเยโฮวาห์พระเจ้าของเราจึงได้ทรงมอบไว้ในมือของเรา ทั้งโอกกษัตริย์เมืองบาชาน และพลโยธาทั้งหลายของท่าน และเราทั้งหลายได้ฆ่าตีเขาจนไม่มีเหลือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 4, 'ครั้งนั้นเราทั้งหลายได้ตีเอาบ้านเมืองทั้งหลายของเขาจนไม่มีเหลือสักเมืองเดียวซึ่งเราไม่ได้ยึดมารวมหกสิบเมือง ดินแดนอารโกบทั้งหมด ซึ่งเป็นราชอาณาจักรของโอกกษัตริย์เมืองบาชาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 5, 'บรรดาเมืองเหล่านี้เป็นเมืองที่มีกําแพงสูงโดยรอบ มีประตู มีดาลประตู และยังมีเมืองอีกมากที่ไม่มีกําแพง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 6, 'เราได้ตีทําลายสิ้น ได้ทําลายทุกๆเมืองเสียสิ้น รวมทั้งผู้ชายผู้หญิงและเด็กทั้งหลาย เหมือนเราได้กระทํากับสิโหนกษัตริย์เมืองเฮชโบนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 7, 'แต่ฝูงสัตว์ทั้งหมด และของริบได้ในเมืองเหล่านั้นเราได้ยึดมาเป็นของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 8, 'ครั้งนั้นเราได้ยึดแผ่นดินเสียจากมือของกษัตริย์ทั้งสองของคนอาโมไรต์ ผู้อยู่ฟากแม่น้ําจอร์แดนข้างนี้ ตั้งแต่ลุ่มแม่น้ําอารโนนถึงภูเขาเฮอร์โมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 9, '(ภูเขาเฮอร์โมนนั้นชาวไซดอนเรียกชื่อว่าสีรีออน และชาวอาโมไรต์เรียกชื่อว่าเสนีร์)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 10, 'คือเมืองทั้งหลายในที่ราบสูง และกิเลอาดทั้งหมด และบาชานทั้งหมด จนถึงสาเลคาห์และเอเดรอี ซึ่งเป็นหัวเมืองแห่งราชอาณาจักรโอกในเมืองบาชาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 11, 'ด้วยยังเหลืออยู่แต่โอกกษัตริย์เมืองบาชานซึ่งเป็นพวกมนุษย์ยักษ์ ดูเถิด เตียงนอนของท่านทําด้วยเหล็ก เตียงนอนนั้นไม่อยู่ที่เมืองรับบาห์แห่งคนอัมโมนดอกหรือ ยาวตั้งเก้าศอก กว้างสี่ศอกขนาดศอกคนเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 12, 'แผ่นดินนี้ที่เรายึดครองได้ครั้งนั้น คือตั้งแต่อาโรเออร์ ซึ่งอยู่ริมลุ่มแม่น้ําอารโนน และแดนเทือกเขากิเลอาดครึ่งหนึ่ง กับหัวเมืองทั้งหลายเหล่านั้น เราก็ได้ให้แก่คนรูเบนและคนกาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 13, 'ส่วนกิเลอาดที่ยังเหลืออยู่กับเมืองบาชานทั้งหมด ซึ่งเป็นราชอาณาจักรของโอก คือดินแดนอารโกบทั้งหมด เราก็ได้ให้ไว้กับครึ่งหนึ่งของคนตระกูลมนัสเสห์ ทั้งหมดเมืองบาชานนั้นเรียกว่าดินแดนของพวกมนุษย์ยักษ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 14, 'ยาอีร์คนมนัสเสห์ก็ตีได้ดินแดนอารโกบทั้งหมด จนถึงเขตแดนเมืองชาวเกชูร์ และเมืองมาอาคาห์ และได้เรียกชื่อเมืองเหล่านั้นตามชื่อของตนว่า บาชานฮาโวทยาอีร์ จนถึงทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 15, 'เมืองกิเลอาดนั้นเราให้แก่มาคีร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 16, 'แก่คนรูเบนและคนกาดนั้นเราให้ตําบลตั้งแต่กิเลอาดถึงลุ่มแม่น้ําอารโนน ถือเอากลางลุ่มน้ําเป็นแดนเรื่อยมาถึงแม่น้ํายับบอกอันเป็นแดนของคนอัมโมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 17, 'ทั้งแถบที่ราบด้วย มีแม่น้ําจอร์แดนเป็นพรมแดน ตั้งแต่ทะเลคินเนเรทจนถึงทะเลแห่งที่ราบ คือทะเลเค็ม ที่อัชโดดปิสกาห์ ซึ่งอยู่ทิศตะวันออก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 18, 'ครั้งนั้นข้าพเจ้าได้บัญชาท่านทั้งหลายว่า ‘พระเยโฮวาห์พระเจ้าของท่านได้ทรงให้ท่านทั้งหลายยึดครองแผ่นดินนี้ ทแกล้วทหารทั้งสิ้นของท่าน จงถืออาวุธยกข้ามไปก่อนคนอิสราเอลผู้เป็นพี่น้องของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 19, 'แต่ภรรยาของท่าน บุตรเล็กๆทั้งหลายของท่านกับฝูงสัตว์ของท่าน (เพราะข้าพเจ้าทราบอยู่แล้วว่า ท่านทั้งหลายมีฝูงสัตว์เป็นอันมาก) จงอยู่ในเขตเมืองที่เรายกให้นั้นก่อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 20, 'กว่าพระเยโฮวาห์จะโปรดให้พี่น้องของท่านได้หยุดพักเหมือนได้ประทานแก่ท่านแล้ว จนเขาทั้งหลายจะยึดครองแผ่นดินซึ่งพระเยโฮวาห์พระเจ้าของท่านประทานแก่เขาที่ฟากแม่น้ําจอร์แดนข้างโน้นแล้ว ท่านทั้งหลายต่างจึงจะกลับมายังที่อยู่ของตน ซึ่งข้าพเจ้าได้ให้แก่ท่านทั้งหลาย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 21, 'ครั้งนั้นข้าพเจ้าได้สั่งโยชูวาว่า ‘นัยน์ตาของท่านได้เห็นบรรดากิจการซึ่งพระเยโฮวาห์พระเจ้าของท่านได้ทรงกระทําแก่กษัตริย์ทั้งสองนั้นแล้ว ดังนั้นพระเยโฮวาห์จะทรงกระทําแก่อาณาจักรทั้งปวงซึ่งท่านจะข้ามไปอยู่เช่นเดียวกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 22, 'ท่านอย่าได้กลัวเขาเลย เพราะพระเยโฮวาห์พระเจ้าของท่าน พระองค์นั้นทรงสู้รบเพื่อท่าน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 23, 'ครั้งนั้นข้าพเจ้าได้อ้อนวอนพระเยโฮวาห์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 24, '‘โอ ข้าแต่องค์พระผู้เป็นเจ้าพระเจ้า พระองค์เพิ่งทรงสําแดงอานุภาพและฤทธิ์พระหัตถ์ของพระองค์แก่ผู้รับใช้ของพระองค์ เพราะมีพระเจ้าองค์ไหนเล่าในสวรรค์หรือในแผ่นดินโลกซึ่งสามารถกระทําตามพระราชกิจ และการอิทธิฤทธิ์ดังพระองค์ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 25, 'ขอพระองค์ทรงโปรดอนุญาตให้ข้าพระองค์ข้ามไปดูแผ่นดินอันดีที่อยู่ฟากแม่น้ําจอร์แดนข้างโน้น ดูแดนเทือกเขางดงามและเลบานอนด้วย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 26, 'แต่พระเยโฮวาห์ได้ทรงพระพิโรธต่อข้าพเจ้า เพราะท่านทั้งหลายเป็นเหตุ พระองค์จึงมิได้ทรงโปรดฟังข้าพเจ้า และพระเยโฮวาห์ตรัสกับข้าพเจ้าว่า ‘พอแล้ว เจ้าอย่าได้พูดกับเราด้วยเรื่องนี้ต่อไปเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 27, 'เจ้าจงขึ้นไปถึงยอดเขาปิสกาห์ และเพ่งตาของเจ้าดูทิศตะวันตก ทิศเหนือ ทิศใต้ และทิศตะวันออก และดูแผ่นดินนั้นด้วยนัยน์ตาของเจ้า เพราะเจ้าจะข้ามแม่น้ําจอร์แดนนี้ไปไม่ได้เลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 28, 'แต่เจ้าจงกําชับโยชูวา จงสนับสนุนและชูใจของเขาให้เข้มแข็ง เพราะเขาจะต้องนําหน้าชนชาตินี้ข้ามไป และจะให้เขาทั้งหลายเข้าถือกรรมสิทธิ์ในแผ่นดินที่เจ้าแลเห็นนั้น’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 29, 'ฉะนั้นเราทั้งหลายจึงยับยั้งอยู่ในหุบเขาตรงหน้าเบธเปโอร์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 1, '“ฉะนั้นบัดนี้ โอ คนอิสราเอลทั้งหลาย จงฟังกฎเกณฑ์และคําตัดสินซึ่งข้าพเจ้าสอนท่านทั้งหลาย จงประพฤติตามเพื่อท่านทั้งหลายจะมีชีวิตอยู่ และเข้าไปยึดครองแผ่นดินซึ่งพระเยโฮวาห์พระเจ้าแห่งบรรพบุรุษของท่านประทานแก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 2, 'ท่านทั้งหลายอย่าเสริมเติมคําที่ข้าพเจ้าได้บัญชาท่านไว้และอย่าตัดออก เพื่อท่านทั้งหลายจะรักษาพระบัญญัติของพระเยโฮวาห์พระเจ้าของท่าน ซึ่งข้าพเจ้าได้บัญชาท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 3, 'นัยน์ตาของท่านทั้งหลายได้เห็นการซึ่งพระเยโฮวาห์ทรงกระทํา เพราะเหตุพระบาอัลเปโอร์แล้ว ด้วยว่าพระเยโฮวาห์พระเจ้าของท่านทั้งหลายได้ทรงทําลายบรรดาคนที่ติดตามพระบาอัลเปโอร์จากท่ามกลางท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 4, 'แต่ท่านทั้งหลายผู้ได้ยึดพระเยโฮวาห์พระเจ้าของท่านทั้งหลายมั่นคงอยู่ ทุกคนได้มีชีวิตอยู่ถึงวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 5, 'ดูเถิด ข้าพเจ้าได้สั่งสอนกฎเกณฑ์และคําตัดสินแก่ท่าน ดังที่พระเยโฮวาห์พระเจ้าของข้าพเจ้าได้ทรงบัญชาข้าพเจ้าไว้ เพื่อท่านทั้งหลายจะกระทําตามในแผ่นดินซึ่งท่านทั้งหลายกําลังเข้าไปยึดครองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 6, 'จงรักษากฎเหล่านั้นและกระทําตาม เพราะนี่เป็นสติปัญญาของท่านทั้งหลายและความเข้าใจของท่านทั้งหลายท่ามกลางสายตาของชนชาติทั้งหลาย ซึ่งจะได้ยินถึงกฎเกณฑ์เหล่านี้แล้วเขาจะกล่าวว่า ‘แน่ทีเดียวประชาชาติใหญ่นี้เป็นชนชาติที่มีปัญญาและความเข้าใจ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 7, 'เพราะมีประชาชาติใหญ่ชาติใดเล่าซึ่งมีพระเจ้าอยู่ใกล้ตน อย่างกับพระเยโฮวาห์พระเจ้าของพวกเราทรงอยู่ใกล้เราในสิ่งสารพัดเมื่อเราร้องทูลต่อพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 8, 'และมีประชาชาติใหญ่ชาติใดเล่า ซึ่งมีกฎเกณฑ์และคําตัดสินอันชอบธรรมอย่างกับพระราชบัญญัติทั้งหมดนี้ ซึ่งข้าพเจ้าได้ตั้งไว้ต่อหน้าท่านทั้งหลายในวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 9, 'แต่จงระวังตัว และรักษาจิตวิญญาณของตัวให้ดี เกรงว่าพวกท่านจะลืมสิ่งซึ่งนัยน์ตาได้เห็นนั้น และเกรงว่าสิ่งเหล่านั้นจะหันไปเสียจากใจของท่านตลอดวันคืนแห่งชีวิตของพวกท่าน จงสอนเรื่องเหล่านี้ให้แก่ลูกของพวกท่านและหลานของพวกท่านว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 10, 'ในวันนั้นที่พวกท่านได้ยืนอยู่ต่อพระพักตร์พระเยโฮวาห์พระเจ้าของพวกท่านที่โฮเรบ พระเยโฮวาห์ตรัสกับข้าพเจ้าว่า ‘จงรวบรวมประชาชนให้เข้ามาต่อหน้าเรา เพื่อเราจะให้เขาได้ยินคําของเรา เพื่อเขาทั้งหลายจะได้ฝึกตนที่จะยําเกรงเราตลอดวันคืนที่เขามีชีวิตอยู่ในโลก และเพื่อว่าเขาจะได้สอนลูกหลานของเขาด้วย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 11, 'ท่านทั้งหลายได้เข้ามาใกล้ยืนอยู่ที่เชิงภูเขา และภูเขานั้นมีเพลิงลุกขึ้นถึงท้องฟ้า มีความมืด เมฆ และความมืดคลุ้มคลุมอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 12, 'แล้วพระเยโฮวาห์ตรัสกับท่านทั้งหลายออกมาจากท่ามกลางเพลิง ท่านทั้งหลายได้ยินสําเนียงพระวจนะ แต่ไม่เห็นรูปสัณฐาน มีแต่ได้ยินพระสุรเสียงเท่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 13, 'และพระองค์ทรงประกาศพันธสัญญาของพระองค์แก่ท่าน ซึ่งพระองค์ทรงบัญชาให้ท่านทั้งหลายปฏิบัติตามคือ พระบัญญัติสิบประการ และพระองค์ทรงจารึกพระบัญญัตินั้นไว้บนศิลาสองแผ่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 14, 'ในครั้งนั้นพระเยโฮวาห์ทรงบัญชาให้ข้าพเจ้าสั่งสอนกฎเกณฑ์และคําตัดสินแก่ท่านทั้งหลาย เพื่อท่านทั้งหลายจะได้กระทําตามในแผ่นดินซึ่งท่านกําลังจะข้ามไปยึดครองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 15, 'เหตุฉะนั้นท่านทั้งหลายจงระวังตัวให้ดี เพราะในวันนั้นพวกท่านไม่เห็นสัณฐานอันใด เมื่อพระเยโฮวาห์ตรัสกับท่านทั้งหลายที่โฮเรบจากท่ามกลางเพลิง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 16, 'เกรงว่าท่านทั้งหลายจะหลงทํารูปเคารพแกะสลักสําหรับตัวท่านทั้งหลายเป็นสัณฐานสิ่งหนึ่งสิ่งใด เป็นรูปตัวผู้หรือตัวเมีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 17, 'เหมือนสัตว์เดียรัจฉานอย่างใดในโลก เหมือนนกที่มีปีกบินไปในอากาศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 18, 'เหมือนสิ่งใดๆที่คลานอยู่บนดิน เหมือนปลาอย่างใดที่อยู่ในน้ําใต้แผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 19, 'เกรงว่าพวกท่านเงยหน้าขึ้นดูท้องฟ้าและเมื่อท่านเห็นดวงอาทิตย์ ดวงจันทร์ และดวงดาว คือบริวารของท้องฟ้า พวกท่านจะถูกเหนี่ยวรั้งให้นมัสการและปรนนิบัติสิ่งเหล่านั้น เป็นสิ่งซึ่งพระเยโฮวาห์พระเจ้าของพวกท่านทรงแบ่งแก่ชนชาติทั้งหลายทั่วใต้ฟ้าทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 20, 'แต่พระเยโฮวาห์ทรงเลือกท่านทั้งหลายและนําท่านออกมาจากเตาเหล็ก คือจากอียิปต์ ให้เป็นประชาชนในกรรมสิทธิ์ของพระองค์ อย่างที่เป็นอยู่ทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 21, 'ยิ่งกว่านั้น เพราะท่านทั้งหลายเป็นเหตุ พระเยโฮวาห์ทรงพระพิโรธต่อข้าพเจ้า และทรงปฏิญาณว่าข้าพเจ้าจะไม่ได้ข้ามแม่น้ําจอร์แดน และข้าพเจ้าจะไม่ได้เข้าไปในแผ่นดินดีซึ่งพระเยโฮวาห์พระเจ้าของท่านทั้งหลายประทานแก่ท่านให้เป็นมรดก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 22, 'แต่ข้าพเจ้าจะตายเสียในแผ่นดินนี้ ข้าพเจ้าจะไม่ได้ข้ามแม่น้ําจอร์แดน แต่ท่านทั้งหลายจะได้ข้ามไป และถือแผ่นดินดีนั้นเป็นกรรมสิทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 23, 'จงระวังตัวให้ดี เกรงว่าท่านทั้งหลายจะลืมพันธสัญญาของพระเยโฮวาห์พระเจ้าของท่านทั้งหลาย ซึ่งพระองค์ทรงกระทําไว้แก่ท่าน และสร้างรูปเคารพสลักเป็นสัณฐานสิ่งหนึ่งสิ่งใดซึ่งพระเยโฮวาห์พระเจ้าของท่านทั้งหลายทรงห้ามไว้นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 24, 'เพราะว่าพระเยโฮวาห์พระเจ้าของท่านเป็นเพลิงที่เผาผลาญ เป็นพระเจ้าผู้ทรงหวงแหน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 25, 'เมื่อพวกท่านมีลูกและมีหลานและได้อยู่ในแผ่นดินนั้นมาช้านาน และท่านกระทําตัวให้เสื่อมทรามโดยการทํารูปเคารพสลักเป็นสัณฐานสิ่งใด และกระทําชั่วในสายพระเนตรพระเยโฮวาห์พระเจ้าของท่านทั้งหลาย ซึ่งเป็นการยั่วยุให้พระองค์ทรงกริ้วโกรธ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 26, 'ข้าพเจ้าขออัญเชิญฟ้าและดินมาเป็นพยานกล่าวโทษท่านในวันนี้ว่า ท่านทั้งหลายจะพินาศอย่างสิ้นเชิงจากแผ่นดิน ซึ่งท่านทั้งหลายกําลังจะข้ามแม่น้ําจอร์แดนไปยึดครองนั้น ท่านจะไม่ได้อยู่ในแผ่นดินนั้นนาน แต่ท่านจะถูกทําลายอย่างสิ้นเชิง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 27, 'และพระเยโฮวาห์จะทรงกระทําให้ท่านทั้งหลายกระจัดกระจายไปอยู่ท่ามกลางชนชาติทั้งหลาย และท่านทั้งหลายจะเหลือจํานวนน้อยในท่ามกลางประชาชาติซึ่งพระเยโฮวาห์ทรงขับไล่ให้ท่านเข้าไปอยู่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 28, 'ณ ที่นั่นท่านทั้งหลายจะปรนนิบัติพระที่ทําด้วยไม้และศิลา เป็นงานที่มือคนทําไว้ ซึ่งไม่ดู ไม่ฟัง ไม่รับประทาน ไม่ดมกลิ่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 29, 'แต่ ณ ที่นั่นแหละท่านทั้งหลายจะแสวงหาพระเยโฮวาห์พระเจ้าของท่าน ถ้าพวกท่านค้นหาพระองค์ด้วยสุดจิตและสุดใจ พวกท่านจะพบพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 30, 'เมื่อพวกท่านมีความทุกข์ลําบาก ซึ่งสิ่งสารพัดเหล่านี้มาถึงท่าน ในกาลภายหลัง ถ้าพวกท่านจะกลับมาหาพระเยโฮวาห์พระเจ้าของท่าน และเชื่อฟังพระสุรเสียงของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 31, '(เพราะว่าพระเยโฮวาห์พระเจ้าของท่านทั้งหลายเป็นพระเจ้าผู้ทรงกอปรด้วยพระเมตตา) พระองค์จะไม่ทรงละทิ้งหรือทําลายท่านทั้งหลาย หรือลืมพันธสัญญาซึ่งพระองค์ทรงกระทําไว้กับบรรพบุรุษของท่านโดยการปฏิญาณ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 32, 'เพราะบัดนี้จงถามดูเถอะว่า ในกาลวันที่ล่วงมาแล้วนั้น คือวันที่อยู่ก่อนท่านทั้งหลาย ตั้งแต่วันที่พระเจ้าทรงสร้างมนุษย์ไว้บนโลก และถามดูจากฟ้าข้างนี้ถึงฟ้าข้างโน้นว่า เคยมีเรื่องใหญ่โตอย่างนี้เกิดขึ้นบ้างหรือ หรือเคยได้ยินถึงเรื่องอย่างนี้บ้างหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 33, 'มีชนชาติใดได้ยินพระสุรเสียงของพระเจ้าตรัสออกมาจากท่ามกลางเพลิง ดังที่ท่านได้ยินและยังมีชีวิตอยู่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 34, 'หรือมีพระเจ้าองค์ใดได้ทรงเพียรพยายามไปนําประชาชาติหนึ่งจากท่ามกลางอีกประชาชาติหนึ่งด้วยการลองใจ ด้วยการทําหมายสําคัญ ด้วยการมหัศจรรย์ ด้วยการสงคราม ด้วยพระหัตถ์ทรงฤทธิ์ และด้วยพระกรที่ทรงเหยียดออก และด้วยเหตุน่ากลัวยิ่ง ตามสิ่งสารพัดซึ่งพระเยโฮวาห์พระเจ้าของท่านทั้งหลายทรงกระทําเพื่อท่านในอียิปต์ต่อหน้าต่อตาท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 35, 'ที่ได้ทรงสําแดงแก่ท่านทั้งหลายนั้นก็เพื่อท่านจะได้ทราบว่า พระเยโฮวาห์ทรงเป็นพระเจ้า นอกจากพระองค์แล้ว ไม่มีพระเจ้าอื่นใดอีกเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 36, 'พระองค์ทรงโปรดให้พวกท่านได้ยินพระสุรเสียงของพระองค์จากฟ้าสวรรค์ เพื่อว่าท่านจะอยู่ในวินัยปกครอง พระองค์ทรงโปรดให้ท่านเห็นเพลิงใหญ่ของพระองค์ในโลก และพวกท่านได้ยินพระวจนะของพระองค์จากกองเพลิง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 37, 'และเพราะพระองค์ทรงรักบรรพบุรุษของพวกท่าน จึงทรงเลือกเชื้อสายของเขาที่มาภายหลังเขา และทรงพาท่านออกจากอียิปต์ท่ามกลางสายพระเนตรของพระองค์ ด้วยเดชานุภาพยิ่งใหญ่ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 38, 'ทรงขับไล่ประชาชาติที่ใหญ่กว่าและมีกําลังมากกว่าพวกท่านเสียให้พ้นหน้าท่าน และนําท่านเข้ามา และทรงประทานแผ่นดินของเขาให้แก่ท่านเป็นมรดกดังทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 39, 'เหตุฉะนั้นจงทราบเสียในวันนี้ และตรึกตรองอยู่ในใจว่า พระเยโฮวาห์ทรงเป็นพระเจ้าในฟ้าสวรรค์เบื้องบนและบนแผ่นดินเบื้องล่าง หามีพระเจ้าอื่นใดอีกไม่เลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 40, 'เพราะฉะนั้นพวกท่านจงรักษากฎเกณฑ์และพระบัญญัติของพระองค์ ซึ่งข้าพเจ้าได้บัญชาแก่ท่านในวันนี้ เพื่อท่านและลูกหลานที่เกิดมาภายหลังท่านจะไปดีมาดี และวันคืนของท่านจะยืนนานอยู่ในแผ่นดิน ซึ่งพระเยโฮวาห์พระเจ้าของพวกท่านประทานแก่ท่านเป็นนิตย์นั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 41, 'แล้วโมเสสกําหนดหัวเมืองทางดวงอาทิตย์ขึ้นฟากแม่น้ําจอร์แดนข้างนี้สามหัวเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 42, 'เพื่อผู้ใดที่ฆ่าคนจะได้หลบหนีไปอยู่ที่นั่น คือผู้ที่ฆ่าเพื่อนบ้านโดยมิได้เจตนา โดยมิได้เกลียดชังเขาแต่ก่อน และเมื่อหนีไปอยู่ในเมืองเหล่านี้เมืองใดเมืองหนึ่งก็จะรอดชีวิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 43, 'หัวเมืองเหล่านี้คือเมืองเบเซอร์อยู่ในถิ่นทุรกันดารบนที่ราบสูงสําหรับคนรูเบน และเมืองราโมทที่กิเลอาดสําหรับคนกาด และเมืองโกลานในบาชานสําหรับคนมนัสเสห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 44, 'ต่อไปนี้เป็นพระราชบัญญัติที่โมเสสได้ตั้งไว้ต่อหน้าคนอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 45, 'เหล่านี้เป็นพระโอวาท เป็นกฎเกณฑ์และคําตัดสินซึ่งโมเสสกล่าวแก่คนอิสราเอลเมื่อเขาออกจากอียิปต์แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 46, 'ฟากแม่น้ําจอร์แดนข้างนี้ที่หุบเขาตรงข้ามเบธเปโอร์ ในแผ่นดินของสิโหนกษัตริย์คนอาโมไรต์ ผู้อยู่ที่เฮชโบนซึ่งโมเสสและคนอิสราเอลได้ตีพ่ายไปครั้งเมื่อออกมาจากอียิปต์แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 47, 'คนอิสราเอลได้เข้ายึดแผ่นดินของท่านและแผ่นดินของโอกกษัตริย์เมืองบาชาน เป็นกษัตริย์สององค์ของคนอาโมไรต์ ผู้อยู่ทางดวงอาทิตย์ขึ้นฟากแม่น้ําจอร์แดนข้างนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 48, 'ตั้งแต่อาโรเออร์ที่อยู่ริมลุ่มแม่น้ําอารโนน ไปจนถึงภูเขาสีออน คือเฮอร์โมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 49, 'รวมกับที่ราบทั้งหมด ซึ่งอยู่ฟากตะวันออกของแม่น้ําจอร์แดนข้างนี้ จนถึงทะเลแห่งที่ราบ ที่น้ําพุแห่งปิสกาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 1, 'โมเสสได้เรียกคนอิสราเอลทั้งหมดเข้ามาแล้วกล่าวแก่เขาทั้งหลายว่า “โอ คนอิสราเอลทั้งหลาย จงฟังกฎเกณฑ์และคําตัดสิน ซึ่งข้าพเจ้ากล่าวให้เข้าหูของท่านทั้งหลายในวันนี้ เพื่อท่านทั้งหลายจะได้เรียนรู้ รักษาไว้และกระทําตาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 2, 'พระเยโฮวาห์พระเจ้าของเราทรงกระทําพันธสัญญากับเราทั้งหลายที่โฮเรบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 3, 'มิใช่พระเยโฮวาห์จะทรงกระทําพันธสัญญานี้กับบรรพบุรุษของเราทั้งหลาย แต่ทรงกระทํากับเรา คือเราทั้งหลายผู้มีชีวิตอยู่ที่นี่ในวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 4, 'พระเยโฮวาห์ตรัสกับท่านทั้งหลายที่ภูเขานั้นจากท่ามกลางเพลิงหน้าต่อหน้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 5, '(ครั้งนั้นข้าพเจ้ายืนอยู่ระหว่างพระเยโฮวาห์กับท่านทั้งหลาย เพื่อจะประกาศพระวจนะของพระเยโฮวาห์แก่ท่านทั้งหลาย เพราะท่านทั้งหลายกลัวเพลิง จึงมิได้ขึ้นไปบนภูเขา) พระองค์ตรัสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 6, '‘เราคือพระเยโฮวาห์พระเจ้าของเจ้า ผู้ได้นําเจ้าออกจากแผ่นดินอียิปต์ออกจากเรือนทาส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 7, 'อย่ามีพระอื่นใดนอกเหนือจากเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 8, 'อย่าทํารูปเคารพสลักสําหรับตนเป็นรูปสิ่งหนึ่งสิ่งใด ซึ่งมีอยู่ในฟ้าเบื้องบน หรือซึ่งมีอยู่ที่แผ่นดินเบื้องล่าง หรือซึ่งมีอยู่ในน้ําใต้แผ่นดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 9, 'อย่ากราบไหว้หรือปรนนิบัติรูปเหล่านั้น เพราะเราคือพระเยโฮวาห์พระเจ้าของเจ้า เป็นพระเจ้าที่หวงแหน ให้โทษเพราะความชั่วช้าของบิดาตกทอดไปถึงลูกหลานของผู้ที่ชังเราจนถึงสามชั่วสี่ชั่วอายุคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 10, 'แต่แสดงความเมตตาต่อคนที่รักเรา และรักษาบัญญัติของเรา จนถึงพันชั่วอายุคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 11, 'อย่าออกพระนามพระเยโฮวาห์พระเจ้าของเจ้าอย่างไร้ประโยชน์ เพราะผู้ที่ออกพระนามพระองค์อย่างไร้ประโยชน์นั้น พระเยโฮวาห์จะทรงถือว่าไม่มีโทษก็หามิได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 12, 'จงถือวันสะบาโต ถือเป็นวันบริสุทธิ์ ดังที่พระเยโฮวาห์พระเจ้าของเจ้าทรงบัญชาไว้แก่เจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 13, 'จงทําการงานทั้งสิ้นของเจ้าหกวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 14, 'แต่วันที่เจ็ดนั้นเป็นสะบาโตของพระเยโฮวาห์พระเจ้าของเจ้า ในวันนั้นอย่ากระทําการงานใดๆ ไม่ว่าเจ้าเอง หรือบุตรชาย บุตรสาวของเจ้า หรือทาสทาสีของเจ้า หรือวัวของเจ้า หรือลาของเจ้า หรือสัตว์ใช้งานของเจ้า หรือแขกที่อาศัยอยู่ในประตูเมืองของเจ้า เพื่อทาสทาสีของเจ้าจะได้หยุดพักอย่างเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 15, 'จงระลึกว่าเจ้าเคยเป็นทาสอยู่ในแผ่นดินอียิปต์ และพระเยโฮวาห์พระเจ้าของเจ้าได้พาเจ้าออกมาจากที่นั่นด้วยพระหัตถ์อันทรงฤทธิ์ และด้วยพระกรที่เหยียดออก เหตุฉะนี้พระเยโฮวาห์พระเจ้าของเจ้าได้ทรงบัญชาให้เจ้ารักษาวันสะบาโต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 16, 'จงให้เกียรติแก่บิดามารดาของเจ้า ดังที่พระเยโฮวาห์พระเจ้าของเจ้าทรงบัญชาเจ้าไว้ เพื่อเจ้าจะมีชีวิตยืนนาน และเจ้าจะไปดีมาดีในแผ่นดินซึ่งพระเยโฮวาห์พระเจ้าของเจ้าประทานให้แก่เจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 17, 'อย่าฆ่าคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 18, 'อย่าล่วงประเวณีผัวเมียเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 19, 'อย่าลักทรัพย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 20, 'อย่าเป็นพยานเท็จใส่ร้ายเพื่อนบ้าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 21, 'อย่าอยากได้ภรรยาของเพื่อนบ้าน และอย่าโลภครัวเรือนของเพื่อนบ้าน คือไร่นาของเขา หรือทาสทาสีของเขา หรือวัว ลาของเขา หรือสิ่งใดๆซึ่งเป็นของของเพื่อนบ้าน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 22, 'พระวจนะเหล่านี้พระเยโฮวาห์ได้ตรัสแก่ชุมนุมชนทั้งปวงของท่านที่ภูเขา ออกมาจากท่ามกลางเพลิง เมฆและความมืดคลุ้มหนาทึบ ด้วยพระสุรเสียงอันดัง และมิได้ทรงเพิ่มเติมสิ่งใดอีก และพระองค์ทรงจารึกไว้บนแผ่นศิลาสองแผ่นและประทานแก่ข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 23, 'ต่อมาเมื่อท่านทั้งหลายได้ยินพระสุรเสียงออกมาจากท่ามกลางความมืดนั้น (ขณะเมื่อภูเขานั้นมีเพลิงลุกอยู่) ท่านทั้งหลายเข้ามาใกล้ข้าพเจ้า คือหัวหน้าตระกูลของท่านทั้งหมด และพวกผู้ใหญ่ของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 24, 'และท่านทั้งหลายกล่าวว่า ‘ดูเถิด พระเยโฮวาห์พระเจ้าของเราได้ทรงสําแดงสง่าราศีและความใหญ่ยิ่งของพระองค์ และเราได้ยินพระสุรเสียงของพระองค์จากท่ามกลางเพลิง ในวันนี้เราได้เห็นพระเจ้าตรัสกับมนุษย์ และมนุษย์ยังคงชีวิตอยู่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 25, 'ฉะนั้นบัดนี้เราทั้งหลายจะต้องตายเสียทําไม เพราะเพลิงใหญ่ยิ่งนี้จะเผาผลาญเรา ถ้าเราได้ยินพระสุรเสียงของพระเยโฮวาห์พระเจ้าของเราอีก เราก็จะต้องตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 26, 'เพราะในบรรดามนุษย์ทั้งหลายใครเล่า ผู้ได้ยินพระสุรเสียงของพระเจ้าผู้ทรงพระชนม์ ตรัสออกมาจากท่ามกลางเพลิงอย่างที่เราได้ยินและยังมีชีวิตอยู่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 27, 'ท่านจงเข้าไปใกล้ และฟังทุกสิ่งซึ่งพระเยโฮวาห์พระเจ้าของเราตรัส และนําพระวจนะทั้งสิ้นที่พระเยโฮวาห์พระเจ้าของเราตรัสแก่ท่านนั้นมากล่าวแก่เราทั้งหลาย และเราทั้งหลายจะฟังและกระทําตาม’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 28, 'เมื่อท่านทั้งหลายพูดกับข้าพเจ้านั้น พระเยโฮวาห์ทรงสดับเสียงแห่งถ้อยคําของท่านทั้งหลาย และพระเยโฮวาห์ตรัสกับข้าพเจ้าว่า ‘เราได้ยินเสียงแห่งถ้อยคําของชนชาติซึ่งเขาพูดกับเจ้าแล้ว สารพัดซึ่งเขาพูดกับเจ้าเช่นนั้นก็ดีอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 29, 'โอ อยากให้มีจิตใจเช่นนี้อยู่เสมอไปหนอ คือที่จะยําเกรงเราและรักษาบัญญัติทั้งสิ้นของเรา เขาทั้งหลายก็จะสุขเจริญอยู่ตลอดชั่วลูกหลานของเขาเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 30, 'จงกลับไปบอกแก่เขาว่า “เจ้าจงกลับไปเต็นท์ของเจ้าทุกคนเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 31, 'แต่ตัวเจ้าจงยืนอยู่ที่นี่ใกล้เรา และเราจะบอกข้อบัญญัติและกฎเกณฑ์และคําตัดสินทั้งสิ้นแก่เจ้า ซึ่งเจ้าจะต้องสอนเขาทั้งหลายเพื่อเขาทั้งหลายจะกระทําตามในแผ่นดินซึ่งเราให้เขายึดครองนั้น’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 32, 'เหตุฉะนั้นท่านทั้งหลายจงระวังที่จะกระทําดังที่พระเยโฮวาห์พระเจ้าของท่านทั้งหลายได้ทรงบัญชาไว้นั้น ท่านทั้งหลายอย่าหันไปทางขวามือหรือทางซ้ายเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 33, 'ท่านจงดําเนินตามวิถีทางทั้งสิ้นซึ่งพระเยโฮวาห์พระเจ้าของท่านได้ทรงบัญชาท่านไว้ เพื่อท่านจะมีชีวิตอยู่และเพื่อท่านจะไปดีมาดี และมีชีวิตยืนนานอยู่ในแผ่นดินซึ่งท่านจะยึดครองนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 1, '“ต่อไปนี้เป็นพระบัญญัติ กฎเกณฑ์และคําตัดสินซึ่งพระเยโฮวาห์พระเจ้าของท่านทั้งหลายทรงบัญชาให้สอนท่าน เพื่อท่านทั้งหลายจะได้กระทําตามในแผ่นดินซึ่งท่านจะข้ามไปยึดครองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 2, 'เพื่อว่าพวกท่านจะได้ยําเกรงพระเยโฮวาห์พระเจ้าของท่านโดยรักษากฎเกณฑ์และพระบัญญัติของพระองค์ทั้งสิ้น ซึ่งข้าพเจ้าบัญชาท่าน ทั้งตัวท่านและลูกหลานของท่าน ตลอดวันคืนแห่งชีวิตของท่านเพื่อว่าวันคืนของพวกท่านจะได้ยืนยาว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 3, 'โอ คนอิสราเอลทั้งหลาย เหตุฉะนั้นขอจงฟัง และจงระวังที่จะกระทําตามเพื่อพวกท่านจะไปดีมาดี และเพื่อท่านทั้งหลายจะทวีมากยิ่งนักในแผ่นดินที่มีน้ํานมและน้ําผึ้งไหลบริบูรณ์ ดังที่พระเยโฮวาห์พระเจ้าแห่งบรรพบุรุษของท่านได้ทรงสัญญากับท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 4, 'โอ คนอิสราเอล จงฟังเถิด พระเยโฮวาห์พระเจ้าของเราทั้งหลายเป็นพระเยโฮวาห์เดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 5, 'พวกท่านจงรักพระเยโฮวาห์ผู้เป็นพระเจ้าของท่าน ด้วยสุดจิตสุดใจของท่าน และด้วยสิ้นสุดกําลังของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 6, 'และจงให้ถ้อยคําที่ข้าพเจ้าบัญชาพวกท่านในวันนี้อยู่ในใจของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 7, 'และพวกท่านจงอุตส่าห์สอนถ้อยคําเหล่านี้แก่ลูกหลานของท่าน เมื่อท่านนั่งอยู่ในเรือน เดินอยู่ตามทาง และนอนลงหรือลุกขึ้น จงพูดถึงถ้อยคํานี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 8, 'จงเอาถ้อยคําเหล่านี้พันไว้ที่มือของท่านเป็นหมายสําคัญ และจงเป็นดังเครื่องหมายระหว่างนัยน์ตาของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 9, 'และเขียนไว้ที่เสาประตูเรือน และที่ประตูของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 10, 'เมื่อพระเยโฮวาห์พระเจ้าของพวกท่านจะพาท่านมาถึงแผ่นดินซึ่งพระองค์ทรงปฏิญาณไว้กับบรรพบุรุษของท่าน คือแก่อับราฮัม อิสอัค และยาโคบ ว่าจะให้แก่ท่าน มีหัวเมืองใหญ่โตและดีซึ่งท่านไม่ได้สร้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 11, 'และเรือนที่มีของดีเต็ม ซึ่งพวกท่านมิได้สะสมไว้ และบ่อขังน้ํา ที่ท่านมิได้ขุด และสวนองุ่นกับต้นมะกอกเทศ ซึ่งท่านมิได้ปลูกไว้ และเมื่อท่านได้รับประทานก็อิ่มหนํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 12, 'แล้วจงระวังกลัวว่าพวกท่านจะลืมพระเยโฮวาห์ผู้ทรงพาท่านออกจากแผ่นดินอียิปต์ออกจากเรือนทาสนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 13, 'พวกท่านจงยําเกรงพระเยโฮวาห์พระเจ้าของท่าน ท่านจงปรนนิบัติพระองค์ และปฏิญาณโดยออกพระนามของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 14, 'ท่านทั้งหลายอย่าติดตามพระอื่น ซึ่งเป็นพระของชนชาติทั้งหลายที่อยู่ล้อมรอบท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 15, '(เพราะว่าพระเยโฮวาห์พระเจ้าของพวกท่าน ผู้ทรงสถิตท่ามกลางท่าน เป็นพระเจ้าหวงแหน) กลัวว่าพระเยโฮวาห์พระเจ้าของพวกท่านจะทรงพระพิโรธต่อท่าน และทําลายท่านเสียจากพื้นแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 16, 'อย่าทดลองพระเยโฮวาห์พระเจ้าของท่านทั้งหลาย ดังที่ได้ทดลองพระองค์ที่มัสสาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 17, 'ท่านทั้งหลายจงอุตส่าห์รักษาพระบัญญัติของพระเยโฮวาห์พระเจ้าของท่าน และพระโอวาทของพระองค์และกฎเกณฑ์ของพระองค์ ซึ่งพระองค์ทรงบัญชาท่านไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 18, 'พวกท่านจงกระทําสิ่งที่ถูกต้องและที่ประเสริฐในสายพระเนตรพระเยโฮวาห์ เพื่อพวกท่านจะมีสวัสดิภาพ และเพื่อท่านจะได้เข้าไปครอบครองแผ่นดินที่ดีซึ่งพระเยโฮวาห์ทรงปฏิญาณไว้กับบรรพบุรุษของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 19, 'โดยขับไล่ศัตรูทั้งสิ้นของท่านออกไปให้พ้นหน้าพวกท่าน ดังที่พระเยโฮวาห์ทรงบัญชาไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 20, 'เมื่อเวลาต่อไปบุตรชายของท่านจะถามท่านว่า ‘พระโอวาท กฎเกณฑ์และคําตัดสินซึ่งพระเยโฮวาห์พระเจ้าของเราทั้งหลาย ได้บัญชาท่านทั้งหลายไว้นั้นมีความหมายว่ากระไร’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 21, 'แล้วท่านจะตอบบุตรชายของท่านว่า ‘เราเป็นทาสของฟาโรห์อยู่ในอียิปต์ และพระเยโฮวาห์ได้ทรงพาเราออกมาจากอียิปต์ด้วยพระหัตถ์อันทรงฤทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 22, 'และพระเยโฮวาห์ทรงสําแดงหมายสําคัญและการมหัศจรรย์ทั้งที่ใหญ่โตและที่ร้ายเหนืออียิปต์และเหนือฟาโรห์ ตลอดจนทั้งราชวงศ์ของท่าน ต่อหน้าต่อตาเราทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 23, 'แล้วพระองค์ได้ทรงพาเราออกมาจากที่นั่น เพื่อจะทรงนําเราเข้าไปในแผ่นดิน ซึ่งพระองค์ทรงปฏิญาณว่าจะประทานแก่บรรพบุรุษของเรา และประทานแผ่นดินนั้นแก่เรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 24, 'พระเยโฮวาห์ทรงบัญชาให้เรากระทําตามกฎเกณฑ์เหล่านี้ทั้งสิ้น คือให้ยําเกรงพระเยโฮวาห์พระเจ้าของเรา เพื่อเป็นผลดีแก่เราเสมอ เพื่อพระองค์จะทรงรักษาชีวิตของเราไว้ให้คงอยู่ ดังทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 25, 'ถ้าเราทั้งหลายจะระวังที่จะกระทําตามพระบัญญัติทั้งสิ้นนี้ต่อพระพักตร์พระเยโฮวาห์พระเจ้าของเรา ดังที่พระองค์ทรงบัญชาเราไว้ ก็จะเป็นความชอบธรรมแก่เราทั้งหลาย’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 1, '“เมื่อพระเยโฮวาห์พระเจ้าของท่านทั้งหลายจะทรงพาท่านเข้าในแผ่นดินซึ่งท่านทั้งหลายกําลังจะเข้ายึดครอง และกวาดไล่ประชาชาติหลายชาติให้ออกไปพ้นหน้าท่าน คือคนฮิตไทต์ คนเกอร์กาชี คนอาโมไรต์ คนคานาอัน คนเปริสซี คนฮีไวต์ และคนเยบุส เป็นเจ็ดประชาชาติซึ่งใหญ่โตกว่าและมีกําลังมากกว่าท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 2, 'และเมื่อพระเยโฮวาห์พระเจ้าของท่านจะทรงมอบเขาทั้งหลายไว้ต่อหน้าท่าน พวกท่านจะต้องตีเขาให้พ่ายแพ้ไปนั้น และทําลายเขาให้สิ้นทีเดียว อย่าได้กระทําพันธสัญญาใดๆกับเขาเลยและอย่ามีความเมตตาต่อเขาด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 3, 'พวกท่านอย่าทําการแต่งงานกับพวกเขา อย่ายกบุตรสาวของท่านให้แก่บุตรชายของเขา หรือรับบุตรสาวของเขามาให้แก่บุตรชายของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 4, 'เพราะว่าพวกเขาจะทําให้บุตรชายของพวกท่านหันเหไปจากการติดตามเรา ไปปฏิบัติพระอื่นๆ พระเยโฮวาห์จะทรงพระพิโรธต่อท่านทั้งหลายและจะทรงทําลายท่านเสียโดยเร็ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 5, 'แต่จงกระทําแก่เขาทั้งหลายอย่างนี้ ท่านทั้งหลายจงทําลายแท่นบูชาของเขาเสีย และหักทําลายเสาศักดิ์สิทธิ์ของเขาเสีย จงโค่นเสารูปเคารพของเขาลงเสีย และเผารูปเคารพแกะสลักของเขาเสียด้วยไฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 6, 'เพราะว่าพวกท่านเป็นชนชาติบริสุทธิ์สําหรับพระเยโฮวาห์พระเจ้าของท่าน พระเยโฮวาห์พระเจ้าของท่านทรงเลือกท่านออกจากชนชาติทั้งหลายที่อยู่บนพื้นโลก ให้มาเป็นชนชาติในกรรมสิทธิ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 7, 'ที่พระเยโฮวาห์ทรงรักและทรงเลือกท่านทั้งหลายนั้น มิใช่เพราะท่านทั้งหลายมีจํานวนมากกว่าประชาชนชาติอื่น ด้วยว่าในบรรดาชนชาติทั้งหลาย ท่านเป็นจํานวนน้อยที่สุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 8, 'แต่เพราะพระเยโฮวาห์ทรงรักท่านทั้งหลาย และพระองค์ทรงรักษาคําปฏิญาณซึ่งพระองค์ทรงปฏิญาณไว้กับบรรพบุรุษของท่านทั้งหลาย พระเยโฮวาห์จึงทรงพาท่านทั้งหลายออกมาด้วยพระหัตถ์อันทรงฤทธิ์ และทรงไถ่ท่านทั้งหลายให้พ้นจากเรือนทาส จากหัตถ์ฟาโรห์กษัตริย์อียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 9, 'เหตุฉะนี้พึงทราบเถิดว่า พระเยโฮวาห์พระเจ้าของพวกท่านเป็นพระเจ้า เป็นพระเจ้าสัตย์ซื่อ ผู้ทรงรักษาพันธสัญญาและความเมตตาต่อบรรดาผู้ที่รักพระองค์และรักษาพระบัญญัติของพระองค์ถึงพันชั่วอายุคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 10, 'และทรงตอบแทนผู้ที่เกลียดชังพระองค์ต่อหน้าเขาเองด้วยทรงทําลายเขาเสีย พระองค์จะไม่ทรงลดหย่อนโทษผู้ที่เกลียดชังพระองค์ พระองค์จะทรงตอบแทนต่อหน้าเขาเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 11, 'เหตุฉะนี้พวกท่านจงระวังที่จะกระทําตามพระบัญญัติ กฎเกณฑ์ และคําตัดสินซึ่งข้าพเจ้าได้บัญชาท่านในวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 12, 'ต่อมาถ้าท่านทั้งหลายเชื่อฟังคําตัดสินเหล่านี้ รักษาและกระทําตาม พระเยโฮวาห์พระเจ้าของพวกท่านจะทรงกระทําตามพันธสัญญาและความเมตตากับท่าน ซึ่งพระองค์ทรงปฏิญาณไว้กับบรรพบุรุษของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 13, 'พระองค์จะทรงรักท่าน อวยพระพรแก่ท่านให้จําเริญทวียิ่งขึ้น พระองค์จะทรงอํานวยพระพรผู้บังเกิดจากครรภ์ของพวกท่าน และผลแห่งพื้นดินของท่าน ทั้งข้าว น้ําองุ่น และน้ํามันของท่านทั้งหลาย ให้ลูกวัวและลูกแพะแกะของท่านทวีขึ้นในแผ่นดิน ซึ่งพระองค์ทรงปฏิญาณแก่บรรพบุรุษของท่านที่จะให้แก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 14, 'ท่านทั้งหลายจะได้รับพระพรเหนือชนชาติทั้งหลายหมด จะไม่มีชายหรือหญิงเป็นหมันท่ามกลางท่าน หรือในหมู่สัตว์เลี้ยงของท่านด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 15, 'และพระเยโฮวาห์จะทรงยกความเจ็บไข้ทั้งสิ้นไปเสียจากพวกท่าน และโรคร้ายอย่างในอียิปต์ซึ่งท่านได้ทราบนั้น พระองค์จะไม่ทรงให้เกิดแก่ท่าน แต่จะทรงให้เกิดแก่ทุกคนที่เกลียดชังพวกท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 16, 'พวกท่านจงทําลายชนชาติทั้งหลายซึ่งพระเยโฮวาห์พระเจ้าของพวกท่านจะทรงมอบให้ท่าน อย่าให้นัยน์ตาของท่านมีเมตตาต่อเขาเลย พวกท่านอย่าปฏิบัติพระของเขา เพราะการอย่างนั้นจะเป็นบ่วงดักท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 17, 'ถ้าท่านทั้งหลายจะนึกในใจว่า ‘ประชาชาติเหล่านี้โตกว่าเรา เราจะขับไล่เขาอย่างไรได้’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 18, 'ท่านทั้งหลายอย่ากลัวเขาเลย แต่จงระลึกถึงการที่พระเยโฮวาห์พระเจ้าของท่านกระทําต่อฟาโรห์และต่อชาวอียิปต์ทั้งสิ้นนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 19, 'การทดลองใหญ่ยิ่งซึ่งนัยน์ตาท่านได้เห็นแล้ว ทั้งหมายสําคัญ การมหัศจรรย์ พระหัตถ์ทรงฤทธิ์ และพระกรที่เหยียดออก ซึ่งพระเยโฮวาห์พระเจ้าของท่านได้ทรงใช้พาท่านทั้งหลายออกมา พระเยโฮวาห์พระเจ้าของท่านทั้งหลายจะทรงกระทําต่อชนชาติทั้งหลายที่ท่านกลัวอย่างนั้นแหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 20, 'ยิ่งกว่านั้นอีกพระเยโฮวาห์พระเจ้าของท่านทั้งหลายจะทรงใช้ฝูงต่อมาท่ามกลางเขา จนกว่าผู้ที่เหลืออยู่และซ่อนตัวหลบจากท่านจะถูกทําลายสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 21, 'พวกท่านอย่าวิตกเพราะเขา ด้วยว่าพระเยโฮวาห์พระเจ้าของพวกท่านอยู่ท่ามกลางท่าน ทรงเป็นพระเจ้ายิ่งใหญ่ที่น่ากลัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 22, 'พระเยโฮวาห์พระเจ้าของพวกท่านจะกวาดไล่ประชาชาติเหล่านี้ให้พ้นหน้าท่านทีละเล็กทีละน้อย ท่านอย่ากําจัดเขาเสียทันที กลัวว่าสัตว์ทุ่งจะเพิ่มขึ้นแก่ท่านมากไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 23, 'แต่พระเยโฮวาห์พระเจ้าของท่านจะทรงมอบเขาไว้ให้ท่านทั้งหลาย และจะกระทําให้เขาเกิดโกลาหลใหญ่จนเขาทั้งหลายจะพินาศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 24, 'และพระองค์จะทรงมอบกษัตริย์ของเขาไว้ในมือของท่าน และท่านทั้งหลายจะกระทําให้ชื่อของเขาพินาศไปจากใต้ฟ้า จะไม่มีผู้ใดต่อต้านท่านทั้งหลายได้ จนกว่าท่านจะทําลายเขาเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 25, 'ท่านทั้งหลายจงเผารูปแกะสลักอันเป็นรูปพระทั้งหลายของเขาเสียด้วยไฟ ท่านทั้งหลายอย่าปรารถนาอยากได้เงินหรือทองซึ่งปิดรูปพระอยู่นั้น หรือนําไปเป็นของท่าน เกรงว่าท่านจะติดกับดักอยู่ภายในนั้นเอง เพราะว่านั่นเป็นสิ่งที่น่าสะอิดสะเอียนต่อพระเยโฮวาห์พระเจ้าของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 26, 'พวกท่านอย่านําสิ่งพึงรังเกียจเข้าไปในเรือนของท่าน กลัวว่าท่านจะเป็นที่ต้องห้ามเหมือนของนั้น พวกท่านจงรังเกียจและเกลียดมันอย่างที่สุด ด้วยเป็นของที่ต้องห้าม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 1, '“บัญญัติทั้งสิ้นซึ่งข้าพเจ้าบัญชาท่านในวันนี้นั้น ท่านทั้งหลายจงระวังกระทําตาม เพื่อท่านทั้งหลายจะมีชีวิตและทวีมากขึ้น และเข้าไปยึดครองแผ่นดินซึ่งพระเยโฮวาห์ทรงปฏิญาณกับบรรพบุรุษของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 2, 'ท่านทั้งหลายจงระลึกถึงทางซึ่งพระเยโฮวาห์พระเจ้าของท่านทรงนําท่านอยู่ในถิ่นทุรกันดารถึงสี่สิบปี เพื่อพระองค์จะทรงกระทําให้ท่านถ่อมใจและทดลองให้ทราบว่าจิตใจของท่านเป็นอย่างไร ดูว่าท่านจะรักษาพระบัญญัติของพระองค์หรือไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 3, 'พระองค์ทรงกระทําให้ท่านถ่อมใจ และปล่อยท่านให้หิว และเลี้ยงท่านด้วยมานา ซึ่งท่านเองหรือบรรพบุรุษของท่านก็ไม่ทราบว่าเป็นอะไร เพื่อพระองค์จะทรงกระทําให้ท่านตระหนักแก่ใจว่า มนุษย์จะบํารุงชีวิตด้วยอาหารสิ่งเดียวก็หามิได้ แต่มนุษย์จะมีชีวิตอยู่ได้ด้วยพระวจนะทุกคําซึ่งออกมาจากพระโอษฐ์ของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 4, 'ในเวลาสี่สิบปีนั้น เสื้อผ้าของท่านก็ไม่ขาดวิ่น และเท้าของท่านก็ไม่บวม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 5, 'ท่านทั้งหลายจงพิจารณาอยู่ในใจเถอะว่า พระเยโฮวาห์พระเจ้าของท่านทั้งหลายทรงตีสอนท่าน เหมือนกับบิดาตีสอนบุตรของตนเช่นกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 6, 'เหตุฉะนั้นท่านจงรักษาพระบัญญัติของพระเยโฮวาห์พระเจ้าของท่าน โดยดําเนินตามพระมรรคาของพระองค์และเกรงกลัวพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 7, 'เพราะพระเยโฮวาห์พระเจ้าของท่านจะทรงพาท่านเข้าไปในแผ่นดินที่ดี เป็นแผ่นดินที่มีธารน้ํา น้ําพุ และน้ําบาดาลไหลออกมากลางหุบเขาและเนินเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 8, 'แผ่นดินที่มีข้าวสาลีและข้าวบาร์เลย์ เถาองุ่น ต้นมะเดื่อ ต้นทับทิม เป็นแผ่นดินที่มีน้ํามันมะกอกเทศและน้ําผึ้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 9, 'เป็นแผ่นดินที่ท่านจะรับประทานอาหารอย่างอุดมซึ่งท่านจะไม่ขาดสิ่งใดเลย เป็นแผ่นดินที่ศิลาเป็นเหล็ก และท่านจะขุดทองเหลืองได้จากภูเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 10, 'เมื่อท่านได้รับประทานอิ่มหนําแล้ว ท่านจงสรรเสริญพระเยโฮวาห์พระเจ้าของพวกท่านในเรื่องแผ่นดินอันดี ซึ่งพระองค์ประทานแก่ท่านนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 11, 'ท่านทั้งหลายจงระวังตัวอย่าลืมพระเยโฮวาห์พระเจ้าของท่าน โดยไม่รักษาพระบัญญัติ และคําตัดสินและกฎเกณฑ์ของพระองค์ ซึ่งข้าพเจ้าได้บัญชาท่านในวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 12, 'เกรงว่าเมื่อท่านได้รับประทานอิ่มหนํา ได้สร้างบ้านเรือนดีๆและได้อาศัยอยู่ในนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 13, 'และเมื่อฝูงวัวและฝูงแพะแกะของท่านทวีขึ้น มีเงินทองมากขึ้น และบรรดาซึ่งท่านมีอยู่ก็ทวีขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 14, 'จิตใจของท่านทั้งหลายจะผยองขึ้น และท่านทั้งหลายก็ลืมพระเยโฮวาห์พระเจ้าของท่านทั้งหลาย ผู้ทรงนําท่านทั้งหลายออกจากแผ่นดินอียิปต์ ออกจากเรือนทาส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 15, 'ผู้ทรงนําท่านมาตลอดถิ่นทุรกันดารใหญ่น่ากลัว ซึ่งมีงูแมวเซาและแมงป่อง และดินแห้งแล้งไม่มีน้ํา ผู้ทรงประทานน้ําจากหินแข็งให้แก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 16, 'ผู้ทรงเลี้ยงท่านทั้งหลายด้วยมานาในถิ่นทุรกันดาร ซึ่งบรรพบุรุษของท่านไม่ทราบ เพื่อว่าพระองค์จะทรงกระทําให้ท่านถ่อมใจและทดลองท่าน เพื่อกระทําให้เกิดประโยชน์แก่ท่านในบั้นปลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 17, 'เกรงว่าท่านจะนึกในใจว่า ‘กําลังและเรี่ยวแรงของข้านําทรัพย์มีค่านี้มาให้’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 18, 'ท่านทั้งหลายจงจําพระเยโฮวาห์พระเจ้าของท่านทั้งหลาย เพราะว่าพระองค์ทรงเป็นผู้ให้กําลังแก่ท่านที่จะได้ทรัพย์สมบัตินี้ เพื่อว่าพระองค์จะทรงดํารงพันธสัญญาซึ่งพระองค์ทรงกระทําโดยปฏิญาณต่อบรรพบุรุษของท่าน ดังวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 19, 'และถ้าท่านลืมพระเยโฮวาห์พระเจ้าของท่าน ไปดําเนินตามพระอื่นและปฏิบัตินมัสการพระเหล่านั้น ข้าพเจ้าขอเตือนท่านจริงๆในวันนี้ว่าท่านจะต้องพินาศเป็นแน่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 20, 'อย่างกับบรรดาประชาชาติซึ่งพระเยโฮวาห์ทรงกระทําให้พินาศไปต่อหน้าท่าน ท่านทั้งหลายจะพินาศอย่างนั้นแหละ เพราะท่านไม่เชื่อฟังพระสุรเสียงของพระเยโฮวาห์พระเจ้าของท่านทั้งหลาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 1, '“โอ คนอิสราเอล จงฟังเถิด ท่านกําลังจะข้ามแม่น้ําจอร์แดนไปในวันนี้ เพื่อจะเข้าไปยึดครองประชาชาติที่ใหญ่กว่าและมีกําลังมากกว่าท่าน ทั้งเมืองที่ใหญ่มีกําแพงสูงเทียมฟ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 2, 'ประชาชนที่สูงใหญ่ เป็นลูกหลานของคนอานาค ผู้ที่ท่านทั้งหลายรู้จักแล้ว และผู้ที่ท่านได้ยินเขาพูดว่า ‘ใครจะยืนหยัดต่อสู้กับลูกหลานของอานาคได้’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 3, 'วันนี้ท่านทั้งหลายจงเข้าใจเถอะว่า ผู้ที่ไปข้างหน้าท่านนั้นคือพระเยโฮวาห์พระเจ้าของท่าน พระองค์จะทรงทําลายเขาดังเพลิงเผาผลาญและทรงกระทําให้เขาพ่ายแพ้ต่อหน้าท่าน ดังนั้นท่านจะได้ขับไล่เขาออกไป กระทําให้เขาพินาศโดยเร็ว ดังที่พระเยโฮวาห์ทรงตรัสไว้กับท่านทั้งหลายแล้วนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 4, 'เมื่อพระเยโฮวาห์พระเจ้าของท่านได้ขับไล่เขาออกไปต่อหน้าท่านทั้งหลายแล้ว ท่านทั้งหลายอย่านึกในใจว่า ‘เพราะความชอบธรรมของข้าพระเยโฮวาห์จึงทรงนําข้ามาให้ยึดครองแผ่นดินนี้’ แต่เพราะความชั่วของประชาชาติเหล่านี้ พระเยโฮวาห์จึงทรงขับไล่เขาออกไปต่อหน้าท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 5, 'ซึ่งท่านทั้งหลายกําลังเข้าไปยึดครองแผ่นดินนี้นั้น มิใช่เพราะความชอบธรรมของท่านหรือความสัตย์ธรรมในใจของท่าน แต่เป็นเพราะความชั่วของประชาชาตินี้ ซึ่งพระเยโฮวาห์พระเจ้าของท่านต้องขับไล่เขาออกเสียต่อหน้าท่านทั้งหลาย และเพื่อว่าพระองค์จะทรงให้เป็นจริงตามพระวจนะซึ่งพระเยโฮวาห์ทรงปฏิญาณต่อบรรพบุรุษของท่าน คือต่ออับราฮัม ต่ออิสอัค และต่อยาโคบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 6, 'เพราะฉะนั้นท่านทั้งหลายจงเข้าใจเถิดว่า ซึ่งพระเยโฮวาห์พระเจ้าของท่านประทานแผ่นดินดีนี้ให้ท่านยึดครองนั้น มิใช่เพราะความชอบธรรมของท่าน เพราะว่าท่านทั้งหลายเป็นชนชาติคอแข็ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 7, 'จงจําไว้และอย่าลืมเสียว่าพวกท่านได้กระทําให้พระเยโฮวาห์พระเจ้าของท่านทรงพระพิโรธที่ในถิ่นทุรกันดาร ตั้งแต่วันที่ท่านออกจากแผ่นดินอียิปต์ กระทั่งท่านมาถึงที่นี่ ท่านมักกบฏต่อพระเยโฮวาห์อยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 8, 'แม้ว่าที่โฮเรบท่านก็กระทําให้พระเยโฮวาห์ทรงพระพิโรธ และพระเยโฮวาห์ก็ทรงกริ้วมากถึงกับจะทําลายท่านทั้งหลายเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 9, 'เมื่อข้าพเจ้าขึ้นไปบนภูเขาเพื่อจะรับแผ่นศิลา เป็นแผ่นศิลาพันธสัญญาซึ่งพระเยโฮวาห์กระทําไว้กับท่าน ข้าพเจ้าอยู่บนภูเขาสี่สิบวันสี่สิบคืน ข้าพเจ้าไม่ได้รับประทานอาหารหรือดื่มน้ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 10, 'และพระเยโฮวาห์ได้ประทานแผ่นศิลาสองแผ่นที่จารึกด้วยนิ้วพระหัตถ์ของพระเจ้าให้แก่ข้าพเจ้า บนศิลานั้นมีพระวจนะทั้งสิ้นซึ่งพระเยโฮวาห์ได้ตรัสกับท่านทั้งหลายบนภูเขาจากท่ามกลางเพลิงในวันที่ประชุมกันอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 11, 'ต่อมาเมื่อสิ้นสี่สิบวันสี่สิบคืนแล้ว พระเยโฮวาห์ประทานแผ่นศิลาสองแผ่น เป็นแผ่นศิลาพันธสัญญา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 12, 'แล้วพระเยโฮวาห์ตรัสกับข้าพเจ้าว่า ‘จงลุกขึ้นลงไปจากที่นี่โดยเร็วเถิด เพราะชนชาติของเจ้าซึ่งเจ้านําออกจากอียิปต์ได้หลงกระทําผิด เขาได้หันเสียจากทางซึ่งเราบัญชาเขาไว้นั้นอย่างรวดเร็ว เขาได้หล่อรูปเคารพไว้สําหรับตัวเขาทั้งหลาย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 13, 'ยิ่งกว่านั้นอีกพระเยโฮวาห์ยังตรัสกับข้าพเจ้าว่า ‘เราได้เห็นชนชาตินี้แล้ว และดูเถิด เขาทั้งหลายเป็นชนชาติคอแข็ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 14, 'ขออย่าทักท้วงเรา ให้เราทําลายเขา และลบชื่อของเขาเสียจากใต้ฟ้า และเราจะตั้งเจ้าให้เป็นประชาชาติที่มีกําลังกว่าและใหญ่กว่าเขา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 15, 'ข้าพเจ้าจึงกลับลงมาจากภูเขา และภูเขานั้นก็มีเพลิงลุกอยู่ และศิลาพันธสัญญาสองแผ่นนั้นก็อยู่ในมือทั้งสองของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 16, 'ดูเถิด เมื่อข้าพเจ้ามองดูก็แลเห็นท่านทั้งหลายกระทําบาปต่อพระเยโฮวาห์พระเจ้าของท่านทั้งหลายแล้ว ท่านทั้งหลายได้หล่อรูปลูกวัวไว้สําหรับท่าน ท่านได้หันจากพระมรรคาซึ่งพระเยโฮวาห์ได้บัญชาแก่ท่านอย่างรวดเร็ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 17, 'ข้าพเจ้าจึงยกศิลาทั้งสองแผ่นเหวี่ยงเสียจากมือทั้งสองของข้าพเจ้าและทําศิลาให้แตกต่อหน้าต่อตาของท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 18, 'แล้วข้าพเจ้าก็ทรุดกราบลงต่อพระพักตร์พระเยโฮวาห์อย่างครั้งก่อนสี่สิบวันสี่สิบคืน มิได้รับประทานอาหารหรือดื่มน้ํา เพราะเหตุบาปทั้งสิ้นที่ท่านทั้งหลายได้กระทํา คือได้ประพฤติอย่างชั่วช้าในสายพระเนตรของพระเยโฮวาห์ ซึ่งเป็นการยั่วยุให้พระองค์ทรงกริ้วโกรธ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 19, 'เพราะข้าพเจ้ากลัวพระพิโรธและความไม่พอพระทัยอย่างรุนแรงซึ่งพระเยโฮวาห์ทรงมีต่อท่าน พระองค์ก็จะทรงทําลายท่านอยู่แล้ว แต่พระเยโฮวาห์ทรงฟังข้าพเจ้าในครั้งนั้นด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 20, 'พระเยโฮวาห์ทรงพระพิโรธต่ออาโรนมากจะทําลายเขาอยู่แล้ว ในครั้งนั้นข้าพเจ้าก็อธิษฐานเผื่ออาโรนด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 21, 'แล้วข้าพเจ้าจึงเอาสิ่งที่บาปหนานั้น คือรูปลูกวัวซึ่งท่านสร้างขึ้นนั้นเผาเสียด้วยไฟ แล้วทุบแล้วบดให้เป็นผงละเอียดอย่างกับฝุ่น แล้วข้าพเจ้าก็โยนผงนั้นลงไปในลําธารซึ่งไหลลงมาจากภูเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 22, 'ท่านทั้งหลายได้กระทําให้พระเยโฮวาห์ทรงพระพิโรธที่ทาเบราห์ และที่มัสสาห์ และที่ขิบโรทหัทธาอาวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 23, 'และเมื่อพระเยโฮวาห์ทรงใช้ท่านไปจากคาเดชบารเนีย ตรัสว่า ‘จงขึ้นไปยึดครองแผ่นดินนั้นซึ่งเราได้ให้แก่เจ้า’ และท่านก็กบฏต่อพระบัญญัติของพระเยโฮวาห์พระเจ้าของท่าน ไม่ยอมเชื่อพระองค์ หรือเชื่อฟังพระสุรเสียงของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 24, 'ท่านทั้งหลายได้กบฏต่อพระเยโฮวาห์เสมอตั้งแต่วันที่ข้าพเจ้ารู้จักท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 25, 'ข้าพเจ้าจึงกราบลงต่อพระพักตร์พระเยโฮวาห์สี่สิบวันสี่สิบคืนนี้ อย่างข้าพเจ้ากราบลงครั้งก่อนนั้น เพราะพระเยโฮวาห์ได้ตรัสว่าจะทรงทําลายท่านทั้งหลายเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 26, 'ข้าพเจ้าได้อธิษฐานต่อพระเยโฮวาห์ว่า ‘โอ ข้าแต่องค์พระผู้เป็นเจ้าพระเจ้า ขออย่าทรงทําลายประชาชนของพระองค์ และมรดกของพระองค์ ซึ่งพระองค์ทรงไถ่เขาทั้งหลายมาด้วยความยิ่งใหญ่ของพระองค์ เป็นคนที่พระองค์ทรงนําออกมาจากอียิปต์ด้วยพระหัตถ์อันทรงฤทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 27, 'ขอทรงระลึกถึงบรรดาผู้รับใช้ของพระองค์ คืออับราฮัม อิสอัค และยาโคบ ขออย่าทรงใส่พระทัยในความดื้อดึงความชั่วร้าย หรือบาปของชนชาตินี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 28, 'กลัวว่าชาวแผ่นดินซึ่งพระองค์ทรงพาข้าพระองค์ทั้งหลายจากมานั้นจะว่า เพราะพระเยโฮวาห์ไม่สามารถจะพาเขาทั้งหลายเข้าไปในแผ่นดินซึ่งพระองค์ทรงสัญญากับเขาไว้ และเพราะว่าพระองค์ทรงเกลียดชังเขา พระองค์จึงทรงพาเขาออกมาฆ่าเสียในถิ่นทุรกันดาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 29, 'เพราะว่าเขาทั้งหลายเป็นประชาชนของพระองค์และเป็นมรดกของพระองค์ ซึ่งพระองค์ทรงนําเขาออกมาด้วยเดชานุภาพยิ่งใหญ่และด้วยพระกรที่เหยียดออกของพระองค์’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 1, '“ครั้งนั้นพระเยโฮวาห์ตรัสกับข้าพเจ้าว่า ‘จงสกัดศิลาสองแผ่นให้เหมือนอย่างเดิม และขึ้นมาหาเราที่บนภูเขาและทําหีบไม้ไว้ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 2, 'และเราจะจารึกถ้อยคําที่อยู่ในแผ่นศิลาแผ่นเดิมที่เจ้าทําแตกเสียนั้น จงเก็บศิลานั้นไว้ในหีบไม้’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 3, 'ข้าพเจ้าจึงทําหีบด้วยไม้กระถินเทศ และสกัดศิลาสองแผ่นเหมือนอย่างเดิม ขึ้นไปบนภูเขา มีศิลาสองแผ่นอยู่ในมือของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 4, 'แล้วพระองค์จึงทรงจารึกพระบัญญัติสิบประการลงบนแผ่นศิลาอย่างครั้งก่อน ซึ่งเป็นพระวจนะที่พระเยโฮวาห์ตรัสกับพวกท่านบนภูเขาจากท่ามกลางเพลิงในวันที่ประชุมนั้น และพระเยโฮวาห์ทรงประทานแผ่นศิลานั้นแก่ข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 5, 'แล้วข้าพเจ้าก็กลับลงมาจากภูเขา และเก็บแผ่นศิลานั้นไว้ในหีบซึ่งข้าพเจ้าได้ทําขึ้นและแผ่นศิลาก็ยังอยู่ในหีบนั้น ดังที่พระเยโฮวาห์ทรงบัญชาข้าพเจ้าไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 6, 'คนอิสราเอลเดินทางจากเบเอโรทของคนยาอาคัน มาถึงโมเสราห์ อาโรนก็สิ้นชีวิตและฝังไว้ที่นั่น และเอเลอาซาร์บุตรชายของเขาจึงปฏิบัติหน้าที่ปุโรหิตแทนเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 7, 'เขาทั้งหลายเดินทางออกจากที่นั่นมาถึงกุดโกดาห์ และจากกุดโกดาห์ถึงโยทบาธาห์เป็นแผ่นดินที่มีแม่น้ําลําธารมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 8, 'ครั้งนั้นพระเยโฮวาห์ได้แยกตระกูลเลวี ให้หามหีบพันธสัญญาแห่งพระเยโฮวาห์ ให้เฝ้าพระเยโฮวาห์เพื่อปรนนิบัติพระองค์ และให้อํานวยพรในพระนามของพระองค์ จนถึงทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 9, 'เหตุฉะนี้คนเลวีจึงหามีส่วนแบ่งหรือมรดกกับพวกพี่น้องของตนไม่ พระเยโฮวาห์ทรงเป็นส่วนมรดกของเขา ดังที่พระเยโฮวาห์พระเจ้าของท่านทั้งหลายทรงสัญญากับเขานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 10, 'ข้าพเจ้าก็อยู่บนภูเขาอย่างครั้งก่อนสี่สิบวันสี่สิบคืน ครั้งนั้นพระเยโฮวาห์ทรงฟังข้าพเจ้าด้วย พระเยโฮวาห์ไม่พอพระทัยที่จะทําลายท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 11, 'พระเยโฮวาห์ตรัสกับข้าพเจ้าว่า ‘จงลุกขึ้นเดินทางนําหน้าประชาชนต่อไปเถิด เพื่อเขาทั้งหลายจะได้เข้าไปยึดแผ่นดินซึ่งเราปฏิญาณไว้แก่บรรพบุรุษว่าจะให้แก่เขานั้น’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 12, 'และบัดนี้ คนอิสราเอล พระเยโฮวาห์พระเจ้าของท่านทรงประสงค์ให้ท่านกระทําอย่างไร คือให้ยําเกรงพระเยโฮวาห์พระเจ้าของท่าน ให้ดําเนินตามพระมรรคาทั้งปวงของพระองค์ ให้รักพระองค์ ให้ปรนนิบัติพระเยโฮวาห์พระเจ้าของท่านด้วยสุดจิตสุดใจของท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 13, 'และให้รักษาพระบัญญัติและกฎเกณฑ์ของพระเยโฮวาห์ ซึ่งข้าพเจ้าบัญชาท่านในวันนี้ เพื่อประโยชน์ของท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 14, 'ดูเถิด ฟ้าสวรรค์และฟ้าสวรรค์อันสูงสุด และโลกกับบรรดาสิ่งสารพัดที่อยู่ในโลกเป็นของพระเยโฮวาห์พระเจ้าของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 15, 'แต่พระเยโฮวาห์ทรงฝังพระทัยในบรรพบุรุษของท่านและทรงรักเขา และทรงเลือกเชื้อสายของเขาที่มาภายหลังเขาคือ ท่านทั้งหลายจากชนชาติทั้งหลาย อย่างเป็นอยู่ทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 16, 'เพราะฉะนั้นจงเข้าสุหนัตหนังปลายหัวใจของท่านเสีย อย่าคอแข็งอีกต่อไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 17, 'เพราะว่าพระเยโฮวาห์พระเจ้าของท่านเป็นพระเจ้าของพระทั้งหลาย และเป็นจอมของเจ้าทั้งปวง เป็นพระเจ้าที่ยิ่งใหญ่ ทรงฤทธิ์และน่ากลัว ทรงปราศจากอคติ และมิได้ทรงเห็นแก่อามิษสินบน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 18, 'พระองค์ประทานความยุติธรรมแก่ลูกกําพร้าพ่อและหญิงม่าย และทรงรักคนต่างด้าวประทานอาหารและเครื่องนุ่งห่มแก่เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 19, 'เพราะฉะนั้นท่านจงมีความรักต่อคนต่างด้าว เพราะท่านทั้งหลายก็เป็นคนต่างด้าวในแผ่นดินอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 20, 'ท่านทั้งหลายจงยําเกรงพระเยโฮวาห์พระเจ้าของท่าน จงปรนนิบัติพระองค์และติดสนิทอยู่กับพระองค์ จงปฏิญาณด้วยออกพระนามของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 21, 'พระองค์ทรงเป็นที่สรรเสริญของท่านทั้งหลาย พระองค์ทรงเป็นพระเจ้าของท่าน ผู้ทรงกระทําการใหญ่และน่ากลัวซึ่งนัยน์ตาของท่านได้เห็นนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 22, 'บรรพบุรุษของท่านลงไปในอียิปต์เจ็ดสิบคน และบัดนี้พระเยโฮวาห์พระเจ้าของท่านทรงกระทําให้ท่านทั้งหลายมีมากดังดวงดาวในท้องฟ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 1, '“เหตุฉะนี้พวกท่านจงรักพระเยโฮวาห์พระเจ้าของท่าน จงรักษาพระดํารัสสั่ง กฎเกณฑ์ และคําตัดสิน และพระบัญญัติของพระองค์เสมอไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 2, 'ท่านทั้งหลายจงทราบในวันนี้ เพราะข้าพเจ้ามิได้กล่าวกับลูกหลานของท่านทั้งหลาย ผู้ไม่ได้รู้เรื่องหรือเห็นถึงวินัยของพระเยโฮวาห์พระเจ้าของท่าน ความยิ่งใหญ่ของพระองค์ พระหัตถ์อันทรงฤทธิ์ และพระกรที่เหยียดออกของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 3, 'ถึงการอัศจรรย์และถึงพระราชกิจของพระองค์ ซึ่งพระองค์ทรงกระทําในอียิปต์ต่อฟาโรห์กษัตริย์อียิปต์ และต่อแผ่นดินทั้งสิ้นของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 4, 'และซึ่งพระองค์ทรงกระทําต่อกองทัพอียิปต์ ต่อม้าของเขา และต่อรถรบของเขา และที่พระองค์ทรงกระทําให้น้ําในทะเลแดงท่วมเขาเมื่อเขาไล่ติดตามท่านทั้งหลาย และที่พระเยโฮวาห์ทรงทําลายเขาทั้งหลายจนทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 5, 'และที่พระองค์ทรงกระทําแก่ท่านทั้งหลายในถิ่นทุรกันดาร จนท่านทั้งหลายมาถึงที่นี่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 6, 'และที่ทรงกระทําต่อดาธาน และอาบีรัมบุตรชายของเอลีอับ บุตรชายของรูเบน คือแผ่นดินได้อ้าปากกลืนเขาเข้าไป ทั้งครัวเรือน เต็นท์ และบรรดาทรัพย์สินทุกอย่างที่อยู่กับพวกเขา ในท่ามกลางคนอิสราเอลทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 7, 'เพราะนัยน์ตาของท่านทั้งหลายได้เห็นพระราชกิจอันยิ่งใหญ่ทั้งหมดของพระเยโฮวาห์ซึ่งพระองค์ทรงกระทํานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 8, 'เหตุฉะนี้ท่านทั้งหลายจงรักษาบัญญัติทั้งสิ้นซึ่งข้าพเจ้าได้บัญชาแก่ท่านทั้งหลายในวันนี้ เพื่อท่านทั้งหลายจะเข้มแข็ง และเข้าไปยึดครองแผ่นดินซึ่งท่านทั้งหลายกําลังจะข้ามไปครอบครองนั้นมาเป็นกรรมสิทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 9, 'และเพื่อท่านจะมีชีวิตยืนนานในแผ่นดิน ซึ่งพระเยโฮวาห์ทรงปฏิญาณแก่บรรพบุรุษว่าจะให้แก่เขาและแก่เชื้อสายของเขา เป็นแผ่นดินที่มีน้ํานมและน้ําผึ้งไหลบริบูรณ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 10, 'เพราะว่าแผ่นดินซึ่งท่านทั้งหลายกําลังเข้าไปยึดครองนั้น ไม่เหมือนแผ่นดินอียิปต์ ซึ่งท่านได้จากมา ในที่นั้นท่านหว่านพืชและเอาเท้ารดน้ําเหมือนเป็นสวนผัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 11, 'แต่แผ่นดินซึ่งท่านจะไปยึดครองนั้น เป็นแผ่นดินที่มีเนินเขาและหุบเขา ซึ่งมีน้ําฝนจากฟ้ารดอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 12, 'เป็นแผ่นดินซึ่งพระเยโฮวาห์พระเจ้าของท่านทั้งหลายทรงดูแล พระเนตรของพระเยโฮวาห์พระเจ้าของท่านอยู่เหนือแผ่นดินนั้นเสมอ ตั้งแต่ต้นปีจนถึงสิ้นปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 13, 'ต่อมาถ้าท่านทั้งหลายจะเชื่อฟังบัญญัติของข้าพเจ้าซึ่งข้าพเจ้าบัญชาท่านไว้ในวันนี้ ให้รักพระเยโฮวาห์พระเจ้าของท่านทั้งหลายและปรนนิบัติพระองค์ด้วยสุดจิตสุดใจของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 14, '‘เราจะให้ฝนตกบนแผ่นดินของเจ้าตามฤดูกาล คือฝนต้นฤดูและฝนชุกปลายฤดู เพื่อเจ้าทั้งหลายจะได้เก็บพืชผล น้ําองุ่น และน้ํามัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 15, 'และเราจะให้หญ้าในทุ่งสําหรับฝูงสัตว์ของเจ้า และเจ้าจะได้รับประทานอิ่มหนํา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 16, 'จงระวังตัวอย่าให้จิตใจของท่านทั้งหลายลุ่มหลงและหันเหไปปรนนิบัตินมัสการพระอื่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 17, 'และพระเยโฮวาห์จึงทรงกริ้วต่อท่าน ปิดฟ้าสวรรค์ไม่ให้ฝนตก และแผ่นดินก็ไม่งอกพืชผล และท่านทั้งหลายจะพินาศจากแผ่นดินดีซึ่งพระเยโฮวาห์ประทานแก่ท่านนั้นเสียอย่างรวดเร็ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 18, 'เหตุฉะนั้นท่านทั้งหลายจงจดจําถ้อยคําเหล่านี้ของข้าพเจ้าไว้ในจิตในใจของท่านทั้งหลาย จงเอาถ้อยคําเหล่านี้พันไว้ที่มือของท่านเป็นหมายสําคัญ จงเป็นดังเครื่องหมายระหว่างนัยน์ตาของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 19, 'และท่านจงสอนถ้อยคําเหล่านี้แก่ลูกหลานของท่านทั้งหลาย จงพูดถึงถ้อยคําเหล่านี้เมื่อท่านนั่งอยู่ในเรือน และเมื่อท่านเดินอยู่ตามทาง เมื่อท่านนอนลงหรือลุกขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 20, 'ท่านจงเขียนคําเหล่านี้ไว้ที่เสาประตูเรือน และที่ประตูของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 21, 'เพื่ออายุของท่านและอายุของลูกหลานของท่านจะได้ยืนนานในแผ่นดิน ซึ่งพระเยโฮวาห์ทรงปฏิญาณที่จะประทานแก่บรรพบุรุษของท่าน ตราบเท่าบรรดาวันที่ฟ้าสวรรค์อยู่เหนือโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 22, 'เพราะถ้าท่านระวังที่จะกระทําตามบัญญัติทั้งปวงซึ่งข้าพเจ้าได้บัญชาท่าน คือรักพระเยโฮวาห์พระเจ้าของท่าน ดําเนินในพระมรรคาทั้งสิ้นของพระองค์ และติดสนิทอยู่กับพระองค์แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 23, 'พระเยโฮวาห์จะทรงขับไล่บรรดาประชาชาติเหล่านี้ให้ออกไปพ้นหน้าท่านทั้งหลาย แล้วท่านจะเข้ายึดครองแผ่นดินของประชาชาติที่ใหญ่กว่าและมีกําลังมากกว่าท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 24, 'ฝ่าเท้าของท่านทั้งหลายจะเหยียบลงที่ใด ที่นั่นจะเป็นของท่าน อาณาเขตของท่านจะเริ่มจากถิ่นทุรกันดารไปจนถึงเลบานอน และจากแม่น้ําคือแม่น้ํายูเฟรติสไปจนถึงทะเลตะวันตก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 25, 'จะไม่มีผู้ใดสามารถต่อต้านท่านได้ เพราะพระเยโฮวาห์พระเจ้าของท่านจะทรงกระทําให้ท่านทั้งหลายเป็นที่เกรงขาม และตกใจกลัวของแผ่นดินที่ท่านทั้งหลายจะเหยียบย่ําไป ตามที่พระองค์ทรงสัญญาไว้กับท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 26, 'ดูเถิด วันนี้ข้าพเจ้าได้นําคําอวยพรและคําสาปแช่งมาไว้ตรงหน้าท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 27, 'ถ้าท่านเชื่อฟังพระบัญญัติของพระเยโฮวาห์พระเจ้าของท่าน ซึ่งข้าพเจ้าบัญชาท่านในวันนี้ ท่านก็จะเป็นไปตามพรนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 28, 'ถ้าท่านไม่เชื่อฟังพระบัญญัติของพระเยโฮวาห์พระเจ้าของท่าน แต่หันเหไปเสียจากทางซึ่งข้าพเจ้าได้บัญชาท่านในวันนี้ ไปติดตามพระอื่นซึ่งท่านไม่รู้จัก ท่านก็จะเป็นไปตามคําสาปแช่งนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 29, 'และต่อมาเมื่อพระเยโฮวาห์พระเจ้าของท่านนําท่านเข้าไปในแผ่นดินซึ่งท่านจะเข้าไปยึดครองนั้น ท่านจงตั้งคําอวยพรไว้บนภูเขาเกริซิม และตั้งคําสาปแช่งไว้บนภูเขาเอบาล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 30, 'ภูเขาเหล่านี้อยู่ฟากแม่น้ําจอร์แดนข้างโน้น ไปตามทางที่ดวงอาทิตย์ตกในแผ่นดินคนคานาอัน ผู้อาศัยอยู่ในที่ราบตรงหน้ากิลกาลข้างที่ราบโมเรห์มิใช่หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 31, 'เพราะท่านทั้งหลายจะต้องข้ามแม่น้ําจอร์แดนไปยึดครองแผ่นดินซึ่งพระเยโฮวาห์พระเจ้าของท่านประทานแก่ท่าน และท่านจะยึดครองและอาศัยอยู่ในแผ่นดินนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 32, 'ท่านจงระวังที่จะรักษากฎเกณฑ์และคําตัดสินทั้งปวงซึ่งข้าพเจ้าตั้งไว้ต่อหน้าท่านทั้งหลายในวันนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 1, '“ต่อไปนี้เป็นกฎเกณฑ์และคําตัดสินซึ่งท่านจะต้องระวังที่จะกระทําตามในแผ่นดิน ซึ่งพระเยโฮวาห์พระเจ้าแห่งบรรพบุรุษของท่านประทานให้ท่านยึดครองตลอดวันคืนซึ่งท่านมีชีวิตอยู่ในโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 2, 'ท่านทั้งหลายจงทําลายบรรดาสถานที่ซึ่งประชาชาติที่ท่านจะยึดครองนั้นใช้เป็นที่ปรนนิบัติพระของเขา ซึ่งอยู่บนภูเขาสูงและบนเนินเขา และใต้ต้นไม้เขียวสดทุกต้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 3, 'ท่านจงรื้อแท่นบูชาของเขา และทุ่มเสาศักดิ์สิทธิ์ของเขาให้แตกเป็นชิ้นๆ และเผาเสารูปเคารพของเขาเสียด้วยไฟ ท่านจงฟันทําลายรูปแกะสลักอันเป็นรูปพระของเขาเสีย และลบชื่อของพระเหล่านั้นออกเสียจากที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 4, 'ท่านทั้งหลายอย่ากระทําดังนั้นแก่พระเยโฮวาห์พระเจ้าของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 5, 'ท่านจงแสวงหาสถานที่จากเขตแดนของบรรดาตระกูลของท่าน ซึ่งพระเยโฮวาห์พระเจ้าของท่านทั้งหลายจะทรงเลือก เพื่อสถาปนาพระนามของพระองค์ไว้ คือให้เป็นที่ประทับของพระองค์ ท่านทั้งหลายจงไปเฝ้าพระองค์ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 6, 'และท่านทั้งหลายจงนําเครื่องเผาบูชาและเครื่องสัตวบูชาของท่านไปที่นั่น ทั้งสิบชักหนึ่ง และเครื่องบูชาที่จะยื่นถวาย ทั้งเครื่องบูชาปฏิญาณ เครื่องบูชาตามใจสมัคร และผลรุ่นแรกที่ได้จากฝูงวัวและฝูงแพะแกะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 7, 'ท่านทั้งหลายจงรับประทานที่นั่นต่อพระพักตร์พระเยโฮวาห์พระเจ้าของท่าน ทั้งท่านและครอบครัวของท่านจงปีติร่าเริงในบรรดากิจการซึ่งมือท่านได้กระทํานั้น ซึ่งพระเยโฮวาห์พระเจ้าของท่านอวยพระพรแก่ท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 8, 'ท่านทั้งหลายอย่ากระทําตามบรรดากิจการที่เรากระทําอยู่ที่นี่ทุกวันนี้ คือทุกคนทําตามอะไรก็ตามที่ถูกต้องในสายตาของตนเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 9, 'เพราะว่าท่านทั้งหลายยังไปไม่ถึงที่หยุดพักและถึงมรดก ซึ่งพระเยโฮวาห์พระเจ้าของท่านประทานแก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 10, 'แต่เมื่อท่านข้ามแม่น้ําจอร์แดนไปแล้ว และอาศัยอยู่ในแผ่นดินซึ่งพระเยโฮวาห์พระเจ้าของท่านทั้งหลายประทานเป็นมรดกแก่ท่าน และเมื่อพระองค์โปรดให้ท่านพักพ้นศัตรูรอบข้างของท่านทั้งสิ้น ท่านจึงอยู่อย่างปลอดภัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 11, 'แล้วจงไปยังสถานที่ซึ่งพระเยโฮวาห์พระเจ้าของท่านจะทรงเลือกไว้ ให้พระนามของพระองค์ประทับที่นั่น จงนําบรรดาสิ่งต่างๆไปด้วยซึ่งข้าพเจ้าได้บัญชาท่านทั้งหลาย คือเครื่องเผาบูชา และเครื่องสัตวบูชาของท่าน ทั้งสิบชักหนึ่ง และเครื่องบูชาที่จะยื่นถวาย ทั้งบรรดาเครื่องบูชาปฏิญาณที่ดีที่สุดซึ่งท่านได้ปฏิญาณไว้ต่อพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 12, 'และท่านทั้งหลายจงปีติร่าเริงต่อพระพักตร์พระเยโฮวาห์พระเจ้าของท่าน ทั้งตัวท่านทั้งหลายและบุตรชายบุตรสาวของท่าน ทั้งทาสชายหญิงของท่านและคนเลวีซึ่งอยู่ภายในประตูเมืองของท่าน เพราะเขาไม่มีส่วนแบ่งหรือส่วนมรดกกับท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 13, 'ท่านทั้งหลายจงระวังให้ดีอย่าถวายเครื่องเผาบูชาตามที่ทุกแห่งซึ่งท่านเห็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 14, 'แต่จงถวายในสถานที่ซึ่งพระเยโฮวาห์จะทรงเลือกในท่ามกลางตระกูลหนึ่งของท่าน ท่านจงถวายเครื่องเผาบูชาของท่านที่นั่น และที่นั่นท่านจงกระทําทุกสิ่งที่ข้าพเจ้าได้บัญชาท่านไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 15, 'อย่างไรก็ตาม ท่านจะฆ่าสัตว์และรับประทานเนื้อในประตูเมืองทั้งหลายของท่านตามที่ท่านปรารถนาก็ได้ ตามซึ่งพระเยโฮวาห์พระเจ้าของท่านอํานวยพระพรประทานแก่ท่านทั้งหลาย ทั้งผู้ที่สะอาดและผู้ที่มลทินก็รับประทานได้ อย่างที่รับประทานเนื้อละมั่งและเนื้อกวาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 16, 'แต่ท่านทั้งหลายอย่ารับประทานเลือดสัตว์เลย ท่านจงเทลงบนพื้นดินเหมือนเทน้ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 17, 'ส่วนสิบชักหนึ่งของพืช หรือน้ําองุ่น หรือน้ํามัน หรือลูกคอกรุ่นแรกจากฝูงวัวหรือฝูงแพะแกะ หรือของถวายปฏิญาณตามที่ท่านปฏิญาณไว้ หรือของถวายตามใจสมัคร หรือของที่ท่านนํามายื่นถวาย ท่านทั้งหลายอย่ารับประทานภายในประตูเมืองของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 18, 'แต่ว่าท่านจงรับประทานของเหล่านี้ต่อพระพักตร์พระเยโฮวาห์พระเจ้าของท่าน ในสถานที่ซึ่งพระเยโฮวาห์พระเจ้าของท่านจะทรงเลือกไว้ ทั้งตัวท่านและบุตรชายบุตรสาวของท่าน ทาสชายหญิงของท่าน และคนเลวีผู้อยู่ภายในประตูเมืองของท่าน และท่านจงปีติร่าเริงต่อพระพักตร์พระเยโฮวาห์พระเจ้าของท่าน ในบรรดากิจการซึ่งมือท่านได้กระทํานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 19, 'ท่านจงระวังอย่าทอดทิ้งคนเลวีตราบเท่าวันที่ท่านอาศัยอยู่ในโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 20, 'เมื่อพระเยโฮวาห์พระเจ้าของท่านทรงขยายอาณาเขตของท่าน ดังที่พระองค์ทรงสัญญาไว้กับท่านแล้วนั้น และท่านกล่าวว่า ‘เราจะกินเนื้อสัตว์’ เพราะพวกท่านอยากรับประทานเนื้อสัตว์ ท่านจะรับประทานเนื้อตามใจปรารถนาของท่านได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 21, 'ถ้าสถานที่ซึ่งพระเยโฮวาห์พระเจ้าของท่านทรงเลือกไว้ เพื่อสถาปนาพระนามของพระองค์ที่นั่นนั้นห่างจากท่านเกินไป ท่านจงฆ่าสัตว์จากฝูงวัวฝูงแพะแกะของท่านเถอะ ซึ่งพระเยโฮวาห์ทรงประทานแก่ท่าน ดังที่ข้าพเจ้าบัญชาท่านไว้แล้วนั้น ท่านจงรับประทานในประตูเมืองของท่านตามที่ใจของท่านปรารถนาเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 22, 'ท่านจะรับประทานได้อย่างที่ท่านรับประทานเนื้อละมั่งหรือเนื้อกวาง ทั้งผู้ที่มลทินและผู้ที่สะอาดด้วยก็รับประทานได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 23, 'แต่พึงแน่ใจว่าท่านไม่รับประทานเลือดสัตว์เลย เพราะว่าเลือดเป็นชีวิตของมัน ท่านอย่ารับประทานชีวิตพร้อมกับเนื้อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 24, 'ท่านอย่ารับประทานเลือด แต่ท่านจงเทเลือดลงบนดินอย่างเทน้ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 25, 'ท่านอย่ารับประทานเลือด เพื่อท่านเองและลูกหลานของท่านที่มาภายหลังท่านจะจําเริญเป็นสุข เมื่อท่านกระทําสิ่งที่ถูกต้องตามสายพระเนตรของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 26, 'แต่สิ่งบริสุทธิ์ซึ่งเป็นส่วนกําหนดจากท่านและของปฏิญาณของท่านนั้น ท่านจงนําไปยังสถานที่ซึ่งพระเยโฮวาห์จะทรงเลือกไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 27, 'และถวายเครื่องเผาบูชาทั้งเนื้อและเลือดบนแท่นบูชาของพระเยโฮวาห์พระเจ้าของท่าน ท่านจงเทเลือดแห่งเครื่องสัตวบูชาลงบนแท่นบูชาของพระเยโฮวาห์พระเจ้าของท่าน แต่ส่วนเนื้อนั้นท่านรับประทานได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 28, 'จงระวังที่จะฟังบรรดาถ้อยคําเหล่านี้ซึ่งข้าพเจ้าได้บัญชาท่านไว้ เพื่อท่านเองและลูกหลานของท่านที่มาภายหลังท่านจะจําเริญเป็นนิตย์ เมื่อท่านกระทําสิ่งที่ประเสริฐและถูกต้องในสายพระเนตรของพระเยโฮวาห์พระเจ้าของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 29, 'เมื่อพระเยโฮวาห์พระเจ้าของท่านจะขจัดประชาชาติซึ่งท่านเข้าไปยึดครองนั้นออกไปให้พ้นหน้าท่าน และท่านก็ยึดครองเข้าอาศัยอยู่ในแผ่นดินนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 30, 'จงระวังตัวว่าท่านจะไม่หลงติดตามเขา ภายหลังจากที่เขาถูกทําลายต่อหน้าท่านแล้วนั้น และจะไม่ไต่ถามเรื่องพระของเขาโดยกล่าวว่า ‘ประชาชาตินี้นมัสการพระของเขาอย่างไร เพื่อเราจะกระทําด้วย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 31, 'ท่านอย่ากระทําอย่างนั้นแก่พระเยโฮวาห์พระเจ้าของท่านทั้งหลาย เพราะว่าสิ่งที่น่าสะอิดสะเอียนทุกอย่างซึ่งพระเยโฮวาห์ทรงเกลียดชัง พวกเขากระทําสิ่งนั้นต่อพระทั้งหลายของเขา แม้แต่บุตรชายและบุตรสาวของเขา เขาก็เผาด้วยไฟบูชาแก่พระของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 32, 'ทุกสิ่งที่ข้าพเจ้าบัญชาท่านไว้นั้น จงระวังที่จะกระทําตาม ท่านอย่าเพิ่มอะไรเข้าหรือตัดอะไรออกไปจากสิ่งเหล่านั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 1, '“ถ้าในหมู่พวกท่านมีผู้พยากรณ์หรือผู้ฝันเห็นเหตุการณ์เกิดขึ้น และสําแดงหมายสําคัญหรือการมหัศจรรย์แก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 2, 'และหมายสําคัญหรือการมหัศจรรย์ซึ่งเขาบอกท่านนั้นสําเร็จจริง ถ้าเขากล่าวว่า ‘ให้เราติดตามพระอื่นกันเถิด’ ซึ่งเป็นพระที่ท่านไม่รู้จัก ‘และให้เรามาปรนนิบัติพระนั้น’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 3, 'ท่านอย่าเชื่อฟังคําของผู้พยากรณ์หรือผู้ฝันเห็นเหตุการณ์คนนั้น เพราะพระเยโฮวาห์พระเจ้าของท่านลองใจท่านดู เพื่อให้ทรงทราบว่า ท่านทั้งหลายรักพระเยโฮวาห์พระเจ้าของท่านด้วยสุดจิตสุดใจของท่านหรือไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 4, 'ท่านทั้งหลายจงดําเนินตามพระเยโฮวาห์พระเจ้าของท่าน และยําเกรงพระองค์ และรักษาพระบัญญัติของพระองค์ และเชื่อฟังพระสุรเสียงของพระองค์ และท่านจงปรนนิบัติพระองค์ และติดสนิทอยู่กับพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 5, 'แต่ผู้พยากรณ์หรือผู้ฝันเห็นเหตุการณ์คนนั้นต้องมีโทษถึงตาย เพราะว่าเขาได้สั่งสอนให้กบฏต่อพระเยโฮวาห์พระเจ้าของท่าน ผู้ทรงนําท่านออกจากแผ่นดินอียิปต์ และทรงไถ่ท่านออกจากเรือนทาส เขากระทําให้ท่านทิ้งหนทางซึ่งพระเยโฮวาห์พระเจ้าของท่านบัญชาให้ท่านดําเนินตามเสีย ดังนั้นแหละท่านจะต้องล้างความชั่วเช่นนี้จากท่ามกลางท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 6, 'ถ้าพี่ชายน้องชายของท่านมารดาเดียวกันกับท่าน หรือบุตรชายบุตรสาวของท่าน หรือภรรยาที่อยู่ในอ้อมอกของท่าน หรือมิตรสหายร่วมใจของท่าน ชักชวนท่านอย่างลับๆว่า ‘ให้เราไปปรนนิบัติพระอื่นกันเถิด’ ซึ่งเป็นพระที่ท่านเองหรือบรรพบุรุษของท่านไม่รู้จัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 7, 'เป็นพระบางองค์ของชนชาติทั้งหลายซึ่งอยู่รอบท่าน ไม่ว่าใกล้หรือไกล จากสุดปลายแผ่นดินโลกข้างนี้ถึงที่สุดปลายโลกข้างโน้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 8, 'ท่านอย่ายอมตามหรือเชื่อฟังเขา อย่าให้นัยน์ตาของท่านเมตตาปรานีเขา ท่านอย่าไว้ชีวิตเขา หรืออย่าซ่อนเขาไว้เลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 9, 'ท่านจงประหารชีวิตเขาเสียเป็นแน่ ท่านควรลงมือก่อนในการทําโทษเขาถึงตาย และต่อไปให้บรรดาประชาชนร่วมมือด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 10, 'ท่านจงเอาหินขว้างเขาให้ตาย เพราะเขาแสวงหาช่องที่จะพาท่านไปจากพระเยโฮวาห์พระเจ้าของท่าน ผู้ทรงพาท่านออกจากแผ่นดินอียิปต์ออกจากเรือนทาส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 11, 'และคนอิสราเอลทั้งปวงจะฟังและยําเกรง ไม่กระทําความชั่วเช่นนี้ท่ามกลางท่านทั้งหลายอีกเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 12, 'ถ้าท่านทั้งหลายได้ยินว่า ในหัวเมืองหนึ่งหัวเมืองใดซึ่งพระเยโฮวาห์พระเจ้าของท่านประทานให้ท่านอาศัยอยู่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 13, 'มีบางคนที่เป็นลูกของเบลีอัลได้ออกไปจากท่ามกลางท่าน ชักชวนชาวเมืองนั้นว่า ‘ให้เราไปปรนนิบัติพระอื่นกันเถิด’ ซึ่งเป็นพระที่ท่านไม่รู้จัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 14, 'ท่านทั้งหลายจงสอบถามและอุตส่าห์ค้นหาและถามดูอย่างขะมักเขม้น และดูเถิด ถ้าเป็นความจริงและเป็นเรื่องแน่นอนว่า สิ่งที่น่าสะอิดสะเอียนนั้นมีคนกระทํากันอยู่ในหมู่พวกท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 15, 'ท่านจงฆ่าชาวเมืองนั้นเสียด้วยคมดาบ ทําลายเสียให้สิ้นเชิงด้วยคมดาบ ทั้งคนทั้งหลายที่อาศัยในเมืองนั้นและฝูงสัตว์ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 16, 'ท่านจงเก็บข้าวของทั้งสิ้นในเมืองนั้นไปกองไว้ที่กลางถนน และเผาเมืองนั้นกับบรรดาข้าวของในเมืองนั้นเสียด้วยไฟ เพื่อพระเยโฮวาห์พระเจ้าของท่าน ให้เมืองนั้นร้างอยู่เป็นนิตย์ อย่าสร้างขึ้นมาใหม่อีกเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 17, 'อย่าให้ของต้องห้ามนั้นมาติดพันมือของท่าน เพื่อว่าพระเยโฮวาห์จะทรงหันจากพระพิโรธยิ่งของพระองค์ และทรงสําแดงพระกรุณาคุณต่อท่าน และทรงเมตตาท่าน ให้ท่านทวีมากขึ้น ดังที่พระองค์ปฏิญาณไว้กับบรรพบุรุษของท่านนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 18, 'เมื่อท่านทั้งหลายเชื่อฟังพระสุรเสียงของพระเยโฮวาห์พระเจ้าของท่าน คือรักษาพระบัญญัติทั้งสิ้นของพระองค์ดังที่ข้าพเจ้าบัญชาท่านไว้ในวันนี้ และกระทําสิ่งที่ถูกต้องตามสายพระเนตรพระเยโฮวาห์พระเจ้าของท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 1, '“ท่านทั้งหลายเป็นบุตรของพระเยโฮวาห์พระเจ้าของท่าน ท่านอย่าเชือดเนื้อตัวเองหรือกระทําหน้าผากให้โล้นเพื่อคนตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 2, 'เพราะท่านทั้งหลายเป็นชนชาติบริสุทธิ์แด่พระเยโฮวาห์พระเจ้าของท่าน และพระเยโฮวาห์ทรงเลือกจากประชาชาติทั้งหลายที่อยู่บนพื้นโลกให้เป็นชนชาติในกรรมสิทธิ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 3, 'ท่านทั้งหลายอย่ารับประทานสิ่งพึงรังเกียจใดๆเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 4, 'สัตว์ที่รับประทานได้มีดังต่อไปนี้ คือ วัว แกะ แพะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 5, 'กวาง ละมั่ง อีเก้ง แพะป่า สมัน โคป่า และแกะป่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 6, 'ท่านรับประทานสัตว์ทุกชนิดที่แยกกีบและกีบผ่าออกเป็นสองและเคี้ยวเอื้องนั้นได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 7, 'อย่างไรก็ตามในจําพวกสัตว์ทั้งหลายที่เคี้ยวเอื้องหรือมีกีบผ่า ท่านอย่ารับประทานสัตว์ต่อไปนี้คือ อูฐ กระต่าย ตัวกระจงผา เพราะว่าสัตว์เหล่านี้เคี้ยวเอื้องแต่กีบไม่ผ่า จึงเป็นสัตว์มลทินแก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 8, 'และหมูด้วยเพราะหมูมีกีบผ่าแต่ไม่เคี้ยวเอื้อง จึงเป็นสัตว์มลทินแก่ท่าน ท่านอย่ารับประทานเนื้อของมัน และซากของมันท่านก็อย่าแตะต้อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 9, 'ในบรรดาสัตว์น้ําทั้งสิ้นท่านรับประทานสัตว์เหล่านี้ได้ คือ สัตว์ใดๆที่มีครีบและเกล็ด ท่านรับประทานได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 10, 'แต่สัตว์ใดๆที่ไม่มีครีบและเกล็ดท่านอย่ารับประทาน เป็นสัตว์มลทินแก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 11, 'นกสะอาดทุกชนิดท่านรับประทานได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 12, 'แต่นกเหล่านี้ท่านอย่ารับประทานคือ นกอินทรี นกแร้งหนวดแพะ นกออก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 13, 'นกเหยี่ยวหางยาว นกเหยี่ยวดํา นกแร้งตามชนิดของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 14, 'บรรดานกกาตามชนิดของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 15, 'นกเค้าแมว นกเค้าโมง นกนางนวล เหยี่ยวนกเขาตามชนิดของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 16, 'นกเค้าแมวเล็ก นกทึดทือ นกอีโก้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 17, 'นกกระทุง นกแร้ง และนกอ้ายงั่ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 18, 'นกกระสาดํา นกกระสาตามชนิดของมัน นกหัวขวาน และค้างคาว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 19, 'แมลงมีปีกทุกชนิดเป็นสัตว์มลทินแก่ท่าน อย่ารับประทานเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 20, 'สัตว์มีปีกที่สะอาดทุกชนิดท่านรับประทานได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 21, 'ท่านอย่ารับประทานสัตว์ชนิดใดที่ตายเอง ท่านจะให้แก่คนต่างด้าวที่อยู่ภายในประตูเมืองของท่านรับประทานก็ได้ หรือท่านจะขายให้แก่คนต่างประเทศก็ได้ เพราะว่าท่านเป็นชนชาติที่บริสุทธิ์แด่พระเยโฮวาห์พระเจ้าของท่านทั้งหลาย ท่านอย่าต้มลูกแพะด้วยน้ํานมแม่ของมันเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 22, 'ผลได้เป็นปีๆจากพืชในนาของท่านนั้น ท่านจงถวายสิบชักหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 23, 'ท่านจงรับประทานสิบชักหนึ่งที่ได้จากข้าวหรือน้ําองุ่นของท่าน หรือน้ํามันของท่าน และผลรุ่นแรกจากฝูงวัว และฝูงแพะแกะของท่าน ต่อพระพักตร์พระเยโฮวาห์พระเจ้าของท่านในสถานที่ซึ่งพระองค์จะทรงเลือกไว้ เพื่อให้พระนามของพระองค์สถิตที่นั่น เพื่อท่านทั้งหลายจะได้เรียนรู้ที่จะยําเกรงพระเยโฮวาห์พระเจ้าของท่านทั้งหลายเสมอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 24, 'ถ้าระยะทางไกลเกินไป ท่านไม่สามารถนําสิบชักหนึ่งมาได้ ในเมื่อพระเยโฮวาห์พระเจ้าของท่านอวยพรแก่ท่าน เพราะว่าสถานที่ซึ่งพระเยโฮวาห์พระเจ้าของท่านจะทรงเลือกเพื่อเป็นที่ตั้งพระนามของพระองค์นั้น อยู่ห่างไกลจากท่านเกินไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 25, 'ท่านจงขายของนั้นเอาเงิน และห่อเงินถือไว้ และไปยังสถานที่ซึ่งพระเยโฮวาห์พระเจ้าของท่านจะทรงเลือกไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 26, 'และเอาเงินนั้นซื้อสิ่งใดๆที่ท่านปรารถนา จะเป็นวัว แกะ หรือน้ําองุ่นหรือสุราและสิ่งใดๆที่ท่านปรารถนา และท่านจงรับประทานที่นั่นต่อพระพักตร์พระเยโฮวาห์พระเจ้าของท่าน และจงปีติร่าเริงทั้งตัวท่านและครอบครัวของท่านด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 27, 'ท่านทั้งหลายอย่าทอดทิ้งคนเลวีซึ่งอยู่ภายในประตูเมืองของท่าน เพราะเขาไม่มีส่วนแบ่งหรือมรดกกับท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 28, 'พอครบสามปีท่านทั้งหลายจงนําสิบชักหนึ่งทั้งหมดจากพืชผลที่ได้ในปีนั้น มาสะสมไว้ภายในประตูเมืองของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 29, 'คนเลวี (เพราะเขาไม่มีส่วนแบ่งหรือมรดกกับท่าน) และคนต่างด้าวและลูกกําพร้าพ่อและหญิงม่าย ผู้ซึ่งอยู่ภายในประตูเมืองของท่าน จะได้มารับประทานอย่างอิ่มหนํา เพื่อว่าพระเยโฮวาห์พระเจ้าของท่านจะทรงอํานวยพระพรแก่บรรดากิจการซึ่งมือของท่านทั้งหลายได้กระทํานั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 1, '“ทุกๆสิ้นเจ็ดปีท่านทั้งหลายต้องมีการปลดปล่อย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 2, 'ให้กระทําการปลดปล่อยดังนี้ เจ้าหนี้ทุกคนจะต้องยกสิ่งที่ตนให้เพื่อนบ้านยืมไปนั้นเสีย อย่าทวงสิ่งนั้นคืนจากเพื่อนบ้านหรือพี่น้องของตนเลย เพราะว่าได้ประกาศการปลดปล่อยของพระเยโฮวาห์แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 3, 'ท่านทั้งหลายจะทวงจากคนต่างประเทศคืนได้ แต่ถ้ามีสิ่งใดของท่านซึ่งอยู่กับพี่น้องก็ให้มือของท่านปล่อยไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 4, 'ยกเว้นเมื่อไม่มีคนยากจนในหมู่พวกท่านทั้งหลาย เพราะว่าพระเยโฮวาห์จะทรงอํานวยพระพรแก่ท่านในแผ่นดิน ซึ่งพระเยโฮวาห์พระเจ้าของท่านประทานให้ท่านเป็นมรดกยึดครองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 5, 'ถ้าท่านเพียงแต่เชื่อฟังพระสุรเสียงของพระเยโฮวาห์พระเจ้าของท่าน พึงระวังที่จะกระทําตามพระบัญญัติทั้งหลายซึ่งข้าพเจ้าได้บัญชาท่านในวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 6, 'เพราะพระเยโฮวาห์พระเจ้าของท่านจะทรงอํานวยพระพรท่านดังที่พระองค์สัญญาต่อท่านนั้น ท่านทั้งหลายจะให้ประชาชาติหลายชาติยืมของของท่าน แต่ท่านอย่ายืมของเขาเลย ท่านทั้งหลายจะปกครองอยู่เหนือหลายประชาชาติ แต่เขาทั้งหลายจะไม่ปกครองเหนือท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 7, 'ถ้าในท่ามกลางท่านทั้งหลายมีคนจนสักคนหนึ่งเป็นพี่น้องของท่านอยู่ภายในประตูเมืองใดๆ ในแผ่นดินซึ่งพระเยโฮวาห์พระเจ้าของท่านประทานแก่ท่าน ท่านอย่ามีใจแข็งหดมือของท่านไว้เสียต่อหน้าพี่น้องของท่านที่ยากจนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 8, 'แต่ท่านทั้งหลายจงยื่นมือของท่านอย่างใจกว้างให้เขา และให้เขายืมข้าวของพอแก่ความต้องการของเขา ไม่ว่าเป็นข้าวของสิ่งใดๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 9, 'จงระวังให้ดีเกรงว่าจะมีความคิดในจิตใจชั่วของท่านว่า ‘ปีที่เจ็ด ปีที่จะต้องปลดปล่อยมาถึงแล้ว’ และท่านก็มีแววตาอันชั่วร้ายต่อพี่น้องที่ขัดสนของท่าน ท่านจึงไม่ยอมให้อะไรเขาเลย และเขาจะร้องทูลพระเยโฮวาห์เรื่องท่าน บาปก็จะตกแก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 10, 'ท่านจงให้เขา และเมื่อให้เขาแล้วอย่ามีจิตคิดเสียดาย เพราะเหตุนี้พระเยโฮวาห์พระเจ้าของท่านจะทรงอํานวยพระพรแก่ท่านในบรรดากิจการทั้งสิ้นของท่าน ไม่ว่าท่านจะลงมือกระทําสิ่งใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 11, 'เพราะว่าคนจนจะไม่หมดไปจากแผ่นดิน เพราะฉะนั้นข้าพเจ้าจึงบัญชาท่านว่า ‘ท่านต้องยื่นมือให้อย่างใจกว้างต่อพี่น้องของท่าน คือต่อคนยากจนคนขัดสนซึ่งอยู่ในแผ่นดินของท่าน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 12, 'ถ้าพี่น้องของท่านซึ่งเป็นคนฮีบรูไม่ว่าชายหรือหญิง ที่เขาขายไว้แก่ท่าน จงให้ปรนนิบัติท่านหกปี เมื่อถึงปีที่เจ็ดก็ให้ปล่อยเขาเป็นอิสระพ้นไปจากท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 13, 'และเมื่อท่านปล่อยเขาเป็นอิสระไปจากท่าน ท่านอย่าปล่อยเขาไปมือเปล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 14, 'ท่านจงมีใจกว้างขวางจัดของให้แก่เขา เป็นของจากฝูงแพะแกะของท่าน จากลานนวดข้าวของท่าน และจากบ่อย่ําองุ่นของท่าน ท่านจงให้แก่เขาตามสมควรตามที่พระเยโฮวาห์พระเจ้าของท่านทรงอํานวยพระพรแก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 15, 'ท่านจงจําไว้ว่าท่านเคยเป็นทาสในแผ่นดินอียิปต์และพระเยโฮวาห์พระเจ้าของท่านได้ทรงไถ่ท่านไว้ เพราะฉะนั้นข้าพเจ้าจึงบัญชาเรื่องนี้แก่ท่านในวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 16, 'แต่ถ้าทาสนั้นจะกล่าวแก่ท่านว่า ‘ข้าพเจ้าจะไม่ไปจากท่าน’ เพราะเขารักท่านและครอบครัวของท่าน เพราะเขาอยู่กับท่านสบายดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 17, 'จงเอาเหล็กแทงใบหูของเขาให้ทะลุไปติดกับประตูเรือน ดังนี้เขาจะเป็นทาสของท่านตลอดไป ท่านจงกระทําเช่นนี้แก่ทาสหญิงด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 18, 'เมื่อท่านปล่อยเขาให้เป็นอิสระนั้นท่านอย่ารู้สึกหนักอกหนักใจ เพราะว่าเขาได้รับใช้ท่านมาหกปีด้วยมีค่าแรงมากกว่าลูกจ้างเป็นสองเท่า พระเยโฮวาห์พระเจ้าของท่านจะทรงอํานวยพระพรแก่ท่านในการทั้งปวงที่ท่านได้กระทํานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 19, 'สัตว์ตัวผู้หัวปีซึ่งเกิดในฝูงวัวหรือฝูงแพะแกะนั้น ท่านทั้งหลายจงถวายไว้แด่พระเยโฮวาห์พระเจ้าของท่าน ท่านอย่าใช้วัวหัวปีทํางาน หรือตัดขนจากแกะหัวปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 20, 'ท่านและครอบครัวของท่านจงรับประทานสัตว์หัวปีนั้นต่อพระพักตร์พระเยโฮวาห์พระเจ้าของท่านทุกๆปี ในสถานที่ซึ่งพระเยโฮวาห์จะทรงกําหนดไว้นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 21, 'แต่ถ้าสัตว์นั้นมีตําหนิใดๆคือขาเกหรือตาบอด หรือมีตําหนิเลวร้ายอย่างใด ท่านอย่าถวายบูชาแด่พระเยโฮวาห์พระเจ้าของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 22, 'ท่านจงรับประทานสัตว์นั้นภายในประตูเมืองของท่าน ทั้งผู้ที่มลทินและผู้ที่สะอาดด้วยก็รับประทานได้ ดังว่าเป็นละมั่งหรือกวาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 23, 'เพียงแต่ท่านอย่ารับประทานเลือดของมันเท่านั้น ท่านจงเทออกทิ้งบนดินเหมือนเทน้ํา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 1, '“ท่านจงถือเดือนอาบีบ ท่านทั้งหลายจงถือปัสกาแด่พระเยโฮวาห์พระเจ้าของท่าน เพราะว่าในเดือนอาบีบนั้นพระเยโฮวาห์พระเจ้าของท่านทรงนําท่านออกจากอียิปต์ในเวลากลางคืน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 2, 'และท่านจงถวายปัสกา เป็นเครื่องบูชาแด่พระเยโฮวาห์พระเจ้าของท่าน จากฝูงแพะแกะหรือฝูงวัว ณ ที่ซึ่งพระเยโฮวาห์จะทรงเลือกไว้ ให้พระนามของพระองค์ประทับที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 3, 'อย่ารับประทานขนมปังมีเชื้อกับปัสกา ตลอดเจ็ดวันท่านจงรับประทานขนมปังไร้เชื้อ เป็นขนมปังแห่งความทุกข์ใจ เพราะท่านรีบหนีออกมาจากแผ่นดินอียิปต์ เพื่อท่านจะระลึกถึงวันที่ท่านออกจากแผ่นดินอียิปต์นั้นตลอดชีวิตของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 4, 'ตลอดเจ็ดวันนั้นอย่าให้เห็นเชื้อขนมภายในอาณาเขตประเทศของท่าน หรือเนื้อสัตว์ซึ่งท่านได้บูชาในเวลาเย็นวันแรกเหลืออยู่ตลอดคืนจนเช้าวันรุ่งขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 5, 'ท่านทั้งหลายอย่าถวายปัสกาภายในประตูเมืองใดๆซึ่งพระเยโฮวาห์พระเจ้าของท่านทรงประทานแก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 6, 'แต่ท่านจงถวายปัสกา ณ สถานที่ซึ่งพระเยโฮวาห์พระเจ้าของท่านจะทรงเลือกไว้ให้พระนามของพระองค์ประทับที่นั่น ในเวลาเย็นเมื่อดวงอาทิตย์ตกแล้ว ในเวลาเดียวกับที่ท่านออกจากอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 7, 'ท่านจงทําให้สุกและรับประทานในสถานที่ซึ่งพระเยโฮวาห์พระเจ้าของท่านจะทรงเลือกไว้ พอรุ่งเช้าท่านจงกลับไปสู่เต็นท์ของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 8, 'ท่านจงรับประทานขนมปังไร้เชื้อหกวัน แต่ในวันที่เจ็ดเป็นประชุมอันศักดิ์สิทธิ์ถวายแด่พระเยโฮวาห์พระเจ้าของท่าน ในวันนั้นอย่ากระทําการงานใดๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 9, 'ท่านทั้งหลายจงนับให้ครบเจ็ดสัปดาห์ จงตั้งต้นนับให้ครบเจ็ดสัปดาห์เริ่มด้วยวันแรกที่ท่านเอาเคียวเกี่ยวข้าว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 10, 'ท่านทั้งหลายจงถือเทศกาลสัปดาห์ถวายแด่พระเยโฮวาห์พระเจ้าของท่าน ด้วยการถวายตามใจสมัครจากมือของท่าน ซึ่งท่านจะถวายแด่พระเยโฮวาห์พระเจ้าของท่าน ตามที่พระเยโฮวาห์พระเจ้าของท่านทรงอํานวยพระพรแก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 11, 'ท่านจงปีติร่าเริงต่อพระพักตร์พระเยโฮวาห์พระเจ้าของท่าน ทั้งตัวท่านและบุตรชายหญิงของท่าน ทั้งทาสชายหญิงของท่าน ทั้งคนเลวีซึ่งอยู่ภายในประตูเมืองของท่าน ทั้งคนต่างด้าว เด็กกําพร้าพ่อและหญิงม่ายซึ่งอยู่ท่ามกลางท่าน ณ สถานที่ซึ่งพระเยโฮวาห์พระเจ้าของท่านทรงเลือกไว้ให้พระนามของพระองค์ประทับที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 12, 'ท่านพึงจําไว้ว่าท่านเคยเป็นทาสในอียิปต์ ท่านพึงระวังที่จะปฏิบัติตามกฎเกณฑ์เหล่านี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 13, 'ท่านจงถือเทศกาลอยู่เพิงเจ็ดวัน เมื่อท่านเก็บรวบรวมพืชผลของท่านจากลานนวดข้าวและจากบ่อย่ําองุ่นของท่านแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 14, 'ในการเลี้ยงนั้นท่านจงปีติร่าเริง ทั้งท่านและบุตรชายหญิงของท่าน และทาสชายหญิงของท่าน ทั้งคนเลวีและคนต่างด้าว ทั้งเด็กกําพร้าพ่อและหญิงม่ายซึ่งอยู่ภายในประตูเมืองของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 15, 'ท่านจงถือเทศกาลนั้นแด่พระเยโฮวาห์พระเจ้าของท่านเจ็ดวัน ณ สถานที่ซึ่งพระเยโฮวาห์จะทรงเลือกไว้ เพราะว่าพระเยโฮวาห์พระเจ้าของท่านจะทรงอํานวยพระพรแก่พืชผลทั้งหลายของท่าน และแก่ผลงานทั้งสิ้นที่มือท่านกระทํา เพื่อว่าท่านจะมีแต่ความปีติยินดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 16, 'บรรดาผู้ชายทั้งสิ้นจะต้องเข้ามาเฝ้าพระเยโฮวาห์พระเจ้าของท่านปีละสามครั้ง ณ สถานที่ซึ่งพระองค์จะทรงเลือกไว้ คือ ณ เทศกาลกินขนมปังไร้เชื้อ เทศกาลสัปดาห์ และเทศกาลอยู่เพิง อย่าให้เขาไปเฝ้าพระเยโฮวาห์มือเปล่าๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 17, 'ให้ทุกคนถวายตามความสามารถของเขา ตามส่วนพระพรที่พระเยโฮวาห์พระเจ้าของท่านทั้งหลายประทานแก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 18, 'ท่านทั้งหลายจงเลือกตั้งผู้พิพากษาและเจ้าหน้าที่ตามบรรดาประตูเมืองของท่าน ซึ่งพระเยโฮวาห์พระเจ้าของท่านประทานแก่ท่าน ตามตระกูลคนของท่าน ให้เขาพิพากษาประชาชนตามความยุติธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 19, 'ท่านอย่ากระทําให้เสียความยุติธรรม อย่าลําเอียง อย่ารับสินบน เพราะว่าสินบนทําให้ตาของคนมีปัญญามืดมัวไป และกลับคดีของคนชอบธรรมเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 20, 'ท่านจงติดตามความยุติธรรมเท่านั้น เพื่อท่านจะมีชีวิตและสืบมรดกในแผ่นดิน ซึ่งพระเยโฮวาห์พระเจ้าของท่านประทานแก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 21, 'ท่านทั้งหลายอย่าปลูกต้นไม้ใดๆใช้เป็นเสารูปเคารพข้างแท่นบูชาพระเยโฮวาห์พระเจ้าของท่านซึ่งท่านจะสร้างไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 22, 'และท่านอย่าตั้งเสาศักดิ์สิทธิ์เป็นรูปเคารพ ซึ่งพระเยโฮวาห์พระเจ้าของท่านทรงรังเกียจ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 1, '“ท่านทั้งหลายอย่านําวัวผู้หรือแกะที่มีตําหนิหรือความพิการใดๆเป็นเครื่องบูชาแด่พระเยโฮวาห์พระเจ้าของท่าน เพราะเป็นสิ่งที่น่าสะอิดสะเอียนต่อพระเยโฮวาห์พระเจ้าของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 2, 'ภายในประตูเมืองใดๆของท่านทั้งหลายซึ่งพระเยโฮวาห์พระเจ้าของท่านประทานแก่ท่านนั้น ถ้าพบว่าในท่ามกลางพวกท่านมีชายหรือหญิงคนใดกระทําความชั่วในสายพระเนตรของพระเยโฮวาห์พระเจ้าของท่าน โดยละเมิดพันธสัญญาของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 3, 'และไปปรนนิบัติพระอื่น และนมัสการพระเหล่านั้น หรือดวงอาทิตย์ ดวงจันทร์ หรืออันใดที่เป็นบริวารท้องฟ้า ซึ่งข้าพเจ้าได้ห้ามไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 4, 'มีคนมาบอกท่านแล้วและท่านก็ได้ยิน และได้สอบถามอย่างขะมักเขม้น และดูเถิด ถ้าเป็นความจริงและเป็นเรื่องแน่นอนว่า สิ่งที่น่าสะอิดสะเอียนนั้นมีคนกระทํากันในอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 5, 'ท่านจงนําชายหรือหญิงผู้กระทําสิ่งที่ชั่วร้ายนั้นมาที่ประตูเมือง และท่านจงเอาหินขว้างชายหรือหญิงนั้นเสียให้ตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 6, 'ผู้ที่ถูกกล่าวโทษถึงตายนั้น ให้มีพยานสองหรือสามปากยืนยันว่าผู้นั้นมีความผิด จึงให้ปรับโทษถึงตายได้ อย่าลงโทษผู้ใดถึงตายด้วยพยานปากเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 7, 'ผู้ที่เป็นพยานต้องลงมือก่อนในการทําโทษเขาถึงตาย ต่อไปคนทั้งปวงจึงร่วมมือด้วยกัน ทั้งนี้เพื่อท่านทั้งหลายจะกําจัดความชั่วเสียจากท่ามกลางท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 8, 'ถ้าคดีใดเกิดขึ้นเป็นเรื่องยากที่จะตัดสินได้ว่า เป็นคดีฆ่าคนตายโดยเจตนาหรือไม่ เป็นคดีเกี่ยวด้วยการเกี่ยงกรรมสิทธิ์ในทรัพย์ เป็นคดีทําร้ายร่างกาย เป็นคดีใดๆซึ่งโต้แย้งกันภายในประตูเมืองของท่าน ท่านจงลุกขึ้นพากันไปยังสถานที่ซึ่งพระเยโฮวาห์พระเจ้าของท่านทรงเลือกไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 9, 'จงไปหาคนเลวีซึ่งเป็นปุโรหิต และไปหาผู้พิพากษาประจําการในสมัยนั้น ท่านจงปรึกษาหารือกับเขา และเขาจะชี้แจงให้ท่านทราบถึงคําตัดสิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 10, 'แล้วท่านจงกระทําตามคําแนะนําซึ่งเขาชี้แจงแก่ท่าน จากสถานที่ซึ่งพระเยโฮวาห์ทรงเลือกนั้น และท่านจงระวังกระทําตามทุกสิ่งซึ่งเขาแนะนําท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 11, 'ท่านจงกระทําตามคําแนะนําจากพระราชบัญญัติซึ่งเขาให้แก่ท่าน และกระทําตามคําตัดสินซึ่งเขาได้สั่งท่าน ท่านทั้งหลายอย่าหันเหไปจากคําตัดสินซึ่งเขาชี้แจงแก่ท่าน อย่าหันไปทางขวามือหรือซ้ายมือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 12, 'ผู้ใดที่บังอาจมิได้กระทําตาม คือไม่ได้เชื่อฟังปุโรหิตผู้ที่ยืนปรนนิบัติต่อพระพักตร์พระเยโฮวาห์พระเจ้าของท่านที่นั่น หรือเชื่อฟังผู้พิพากษา ผู้นั้นต้องตาย ทั้งนี้เพื่อท่านทั้งหลายจะกําจัดความชั่วเสียจากอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 13, 'และประชาชนทั้งหลายจะได้ยินและยําเกรง และมิได้ขัดขืนต่อไปอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 14, 'เมื่อท่านมาถึงแผ่นดินที่พระเยโฮวาห์พระเจ้าของท่านประทานแก่ท่าน และท่านถือกรรมสิทธิ์อาศัยอยู่ในแผ่นดินนั้น แล้วท่านจะกล่าวว่า ‘เราจะตั้งกษัตริย์ไว้เหนือเราเหมือนประชาชาติอื่นซึ่งอยู่รอบเรา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 15, 'ก็จงตั้งผู้ซึ่งพระเยโฮวาห์พระเจ้าของท่านทรงเลือกไว้ให้เป็นกษัตริย์เหนือท่าน คือตั้งผู้หนึ่งผู้ใดในพวกพี่น้องของท่านให้เป็นกษัตริย์เหนือท่าน ท่านอย่าตั้งคนต่างด้าวซึ่งมิใช่พี่น้องของท่านให้อยู่เหนือท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 16, 'แต่ว่าอย่าให้ผู้นั้นมีม้าของตนเองมากเกินไป หรือเป็นเหตุให้ประชาชนกลับไปอียิปต์เพื่อจะมีม้ามากๆ เพราะพระเยโฮวาห์ได้ตรัสกับท่านทั้งหลายแล้วว่า ‘เจ้าทั้งหลายจะไม่ได้กลับไปทางนั้นอีกเลย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 17, 'และอย่าให้ผู้นั้นมีภรรยามาก เกรงว่าจิตใจของเขาจะหันเหไปเสีย หรืออย่าให้มีเงินมีทองเป็นของตนอย่างมากมาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 18, 'เมื่อผู้นั้นนั่งบัลลังก์ในราชอาณาจักร ก็ให้ผู้นั้นคัดลอกพระราชบัญญัตินี้ไว้ในหนังสือเพื่อประโยชน์แก่ตนเอง จากหนังสือซึ่งอยู่ตรงหน้าพวกปุโรหิตที่เป็นคนเลวี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 19, 'ให้พระราชบัญญัตินั้นอยู่กับผู้นั้น และให้เขาอ่านอยู่เสมอตลอดชีวิตของตน เพื่อเขาจะได้เรียนรู้ที่จะยําเกรงพระเยโฮวาห์พระเจ้าของเขา โดยรักษาบรรดาถ้อยคําในพระราชบัญญัตินี้และกฎเกณฑ์เหล่านี้และกระทําตาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 20, 'เพื่อว่าจิตใจของเขาจะมิได้พองขึ้นสูงกว่าพี่น้องของตน และเพื่อเขาเองจะมิได้หันเหจากพระบัญญัติไปทางขวามือหรือทางซ้ายมือ เพื่อเขาจะได้ปกครองราชอาณาจักรของเขาอยู่ได้นาน ทั้งตนเองและลูกหลานของตนในอิสราเอล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 1, '“คนเลวีซึ่งเป็นปุโรหิตและตระกูลเลวีทั้งหมด จะไม่มีส่วนแบ่งหรือมรดกร่วมกับคนอิสราเอล เขาจะรับประทานเครื่องบูชาที่ถวายด้วยไฟแด่พระเยโฮวาห์และส่วนที่ตกเป็นของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 2, 'ฉะนั้นเขาจะไม่มีมรดกในหมู่พวกพี่น้องของเขา พระเยโฮวาห์ทรงเป็นมรดกของเขา ตามที่พระองค์ทรงสัญญาไว้แก่เขาแล้วนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 3, 'ให้ส่วนต่อไปนี้เป็นส่วนที่ปุโรหิตได้อันตกจากประชาชน คือส่วนที่ได้จากผู้ที่ถวายสัตวบูชา ไม่ว่าจะเป็นวัวผู้หรือแกะ ก็ให้เขามอบเนื้อสันขาหน้า เนื้อแก้มทั้งสองข้าง และเนื้อท้องให้แก่ปุโรหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 4, 'ผลรุ่นแรกของท่านคือ ผลข้าว ผลน้ําองุ่น ผลน้ํามัน และขนแกะรุ่นแรกที่ได้จากแกะของท่าน จงมอบให้แก่ปุโรหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 5, 'เพราะว่าพระเยโฮวาห์พระเจ้าของท่านได้เลือกเขาจากตระกูลชนทั้งสิ้นของท่าน ให้ยืนปรนนิบัติในพระนามพระเยโฮวาห์ ทั้งตัวเขาและลูกหลานของเขาสืบต่อกันไปเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 6, 'ถ้าคนเลวีคนใดมาจากประตูเมืองใดในอิสราเอลอันเป็นที่อยู่ของเขา จะมายังสถานที่ซึ่งพระเยโฮวาห์ทรงเลือกไว้ก็ให้เขามาได้ตามใจปรารถนา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 7, 'แล้วเขาจะปรนนิบัติในพระนามพระเยโฮวาห์พระเจ้าของเขา เช่นเดียวกับบรรดาคนเลวีพี่น้องของเขา ผู้ยืนปรนนิบัติต่อพระพักตร์พระเยโฮวาห์อยู่ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 8, 'ให้เขาได้ส่วนที่จะรับประทานเท่าๆกัน นอกเหนือจากส่วนที่เขาได้มาด้วยการขายทรัพย์สินของเขาเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 9, 'เมื่อท่านทั้งหลายเข้าไปในแผ่นดินซึ่งพระเยโฮวาห์พระเจ้าของท่านประทานแก่ท่าน ท่านอย่าเรียนรู้ที่จะกระทําตามสิ่งที่น่าสะอิดสะเอียนของประชาชาติเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 10, 'อย่าให้มีคนหนึ่งคนใดในหมู่พวกท่านซึ่งให้บุตรชายหรือบุตรสาวของเขาลุยไฟ อย่าให้ผู้ใดเป็นคนทํานาย เป็นหมอดู เป็นหมอจับยามดูเหตุการณ์ หรือเป็นนักวิทยาคม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 11, 'เป็นหมอผี เป็นคนทรง เป็นพ่อมดแม่มด หรือเป็นหมอพราย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 12, 'เพราะทุกคนที่กระทําสิ่งเหล่านี้ย่อมเป็นที่สะอิดสะเอียนแด่พระเยโฮวาห์ และด้วยเหตุจากการกระทําที่น่าสะอิดสะเอียนเหล่านี้ พระเยโฮวาห์พระเจ้าของท่านทั้งหลายจึงทรงขับไล่เขาออกไปจากเบื้องหน้าท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 13, 'ท่านทั้งหลายจงเป็นคนปราศจากตําหนิต่อพระพักตร์พระเยโฮวาห์พระเจ้าของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 14, 'เพราะว่าประชาชาติเหล่านี้ ซึ่งท่านกําลังจะยึดครองนั้นเชื่อฟังหมอดูและพวกโหร แต่ส่วนตัวท่านนั้น พระเยโฮวาห์พระเจ้าของท่านไม่ทรงยินยอมให้ท่านกระทําเช่นนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 15, 'พระเยโฮวาห์พระเจ้าของท่านจะโปรดให้ผู้พยากรณ์อย่างข้าพเจ้านี้เกิดขึ้นในหมู่พวกท่านจากพี่น้องของท่าน ท่านทั้งหลายจงตั้งใจฟังเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 16, 'อย่างที่ท่านปรารถนาจากพระเยโฮวาห์พระเจ้าของท่านที่โฮเรบในวันประชุมเมื่อท่านกล่าวว่า ‘อย่าให้ข้าพเจ้าได้ยินพระสุรเสียงของพระเยโฮวาห์พระเจ้าของข้าพเจ้า หรือได้เห็นเพลิงมหึมานี้อีกเลย เกรงว่าข้าพเจ้าจะตายเสีย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 17, 'และพระเยโฮวาห์ตรัสกับข้าพเจ้าว่า ‘ซึ่งเขาพูดมาเช่นนั้นก็ดีอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 18, 'เราจะโปรดให้บังเกิดผู้พยากรณ์อย่างเจ้าในหมู่พวกพี่น้องของเขา และเราจะใส่ถ้อยคําของเราในปากของเขา และเขาจะกล่าวบรรดาสิ่งที่เราบัญชาเขาไว้นั้นแก่ประชาชนทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 19, 'ต่อมาผู้ใดไม่เชื่อฟังถ้อยคําของเรา ซึ่งผู้พยากรณ์กล่าวในนามของเรา เราจะกําหนดโทษผู้นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 20, 'แต่ผู้พยากรณ์คนใดบังอาจกล่าวคําในนามของเราซึ่งเรามิได้บัญชาให้กล่าวหรือผู้นั้นกล่าวในนามของพระอื่น ผู้พยากรณ์นั้นต้องมีโทษถึงตาย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 21, 'และถ้าท่านนึกในใจว่า ‘ทําอย่างไรเราจึงจะรู้พระวจนะที่พระเยโฮวาห์ยังมิได้ตรัสนั้นได้’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 22, 'เมื่อผู้พยากรณ์กล่าวคําในพระนามของพระเยโฮวาห์ ถ้ามิได้เป็นไปจริงตามถ้อยคําของผู้กล่าว ถ้อยคํานั้นมิได้เป็นพระวจนะที่พระเยโฮวาห์ตรัส ผู้พยากรณ์นั้นบังอาจกล่าวเอง ท่านทั้งหลายอย่าเกรงกลัวเขาเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 1, '“เมื่อพระเยโฮวาห์พระเจ้าของท่านทั้งหลายทรงขจัดบรรดาประชาชาติ ผู้ซึ่งพระเยโฮวาห์พระเจ้าของท่านประทานแผ่นดินของเขาแก่ท่าน และท่านทั้งหลายยึดครองและเข้าไปอาศัยอยู่ในหัวเมืองและในบ้านเรือนของเขาเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 2, 'ท่านจงแยกเมืองไว้สามเมืองสําหรับพวกท่านทั้งหลายในท่ามกลางแผ่นดิน ซึ่งพระเยโฮวาห์พระเจ้าของท่านประทานแก่ท่านเป็นกรรมสิทธิ์นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 3, 'ท่านจงจัดเตรียมให้มีทาง และจงแบ่งอาณาเขตแผ่นดิน ซึ่งพระเยโฮวาห์พระเจ้าของท่านประทานแก่ท่านเป็นกรรมสิทธิ์นั้นออกเป็นสามส่วน เพื่อว่าผู้ใดที่ได้ฆ่าคนแล้วจะหลบหนีไปอยู่ในเมืองเหล่านั้นได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 4, 'ต่อไปนี้เป็นเรื่องของคนฆ่าคนผู้ที่หนีไปอยู่ในเมืองเหล่านั้นได้และรอดชีวิตอยู่ คือผู้ใดที่ได้ฆ่าเพื่อนบ้านของตนโดยมิได้เจตนา โดยมิได้เกลียดชังเขาแต่ก่อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 5, 'อาทิเช่น ชายคนหนึ่งเข้าไปในป่าพร้อมกับเพื่อนบ้านของเขาเพื่อจะตัดไม้ เมื่อเขาเหวี่ยงขวานเพื่อจะโค่นต้นไม้ลง หัวขวานหลุดจากด้ามถูกเพื่อนบ้านของเขาและคนนั้นก็ถึงตาย ก็ให้เขาหนีไปยังเมืองเหล่านี้เมืองใดเมืองหนึ่งและรอดตายได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 6, 'ด้วยเกรงว่าผู้อาฆาตโลหิตกําลังโกรธจัดจะไล่ตามชายผู้ฆ่าคนคนนั้นทัน เพราะหนทางไกลแล้วฆ่าเขาเสีย แม้ว่าชายผู้นั้นไม่มีโทษถึงตาย เพราะเขามิได้เกลียดชังเพื่อนบ้านของเขาแต่ก่อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 7, 'เพราะฉะนั้นข้าพเจ้าจึงบัญชาท่านว่า ให้ท่านจัดแยกหัวเมืองไว้สามหัวเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 8, 'และถ้าพระเยโฮวาห์พระเจ้าของท่านขยายอาณาเขตของท่าน ดังที่พระองค์ได้ทรงปฏิญาณไว้กับบรรพบุรุษของท่าน และประทานแผ่นดินทั้งสิ้นซึ่งพระองค์ทรงสัญญาจะประทานแก่บรรพบุรุษของท่านให้แก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 9, 'ถ้าท่านได้ระวังที่จะรักษาบัญญัติทั้งหมดนี้ซึ่งข้าพเจ้าได้บัญชาท่านในวันนี้ โดยที่ท่านทั้งหลายรักพระเยโฮวาห์พระเจ้าของท่าน และดําเนินอยู่ในพระมรรคาของพระองค์เสมอ แล้วท่านจงเพิ่มหัวเมืองอีกสามหัวเมืองนอกจากสามหัวเมืองเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 10, 'ด้วยเกรงว่าโลหิตที่ไร้ความผิดจะตกในแผ่นดินของท่าน ซึ่งพระเยโฮวาห์พระเจ้าของท่านประทานแก่ท่านเป็นมรดก และท่านทั้งหลายจึงต้องรับผิดชอบโลหิตนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 11, 'แต่ถ้าผู้ใดเกลียดชังเพื่อนบ้านของตน และซุ่มคอยดักเขาอยู่และได้ลอบตีเขาถึงแก่ความตาย แล้วชายผู้นั้นก็หนีเข้าไปในหัวเมืองเหล่านั้นเมืองใดเมืองหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 12, 'แล้วพวกผู้ใหญ่ในเมืองของชายผู้นั้นจะส่งคนให้ไปรับตัวชายผู้นั้นมาจากที่นั่น และส่งตัวเขาไว้ในมือผู้อาฆาตโลหิต เพื่อเขาจะต้องถูกโทษถึงตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 13, 'อย่าให้นัยน์ตาของท่านเมตตาสงสารเขาเลย แต่ท่านจงกําจัดความผิดอันเนื่องจากโลหิตที่ไร้ความผิดนั้นให้สิ้นไปจากอิสราเอล เพื่อท่านทั้งหลายจะได้ไปดีมาดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 14, 'ในเรื่องมรดกซึ่งท่านจะรับในแผ่นดินซึ่งพระเยโฮวาห์พระเจ้าของท่านประทานแก่ท่านเป็นกรรมสิทธิ์นั้น ท่านอย่าย้ายเสาเขตของเพื่อนบ้านของท่าน ซึ่งคนโบราณได้ปักไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 15, 'อย่าให้พยานปากเดียวยืนยันกล่าวโทษผู้หนึ่งผู้ใด ไม่ว่าในเรื่องความชั่วช้า หรือในเรื่องความผิดใดๆ ซึ่งเขาได้กระทําผิดไป แต่ต้องมีพยานสองหรือสามปาก คําพยานนั้นจึงจะเป็นที่เชื่อถือได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 16, 'ถ้ามีพยานเท็จกล่าวปรักปรําความผิดของคนหนึ่งคนใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 17, 'ก็ให้ทั้งสองฝ่ายที่ต่อสู้คดีกันนั้นเข้าเฝ้าพระเยโฮวาห์ ต่อหน้าปุโรหิตและผู้พิพากษาซึ่งประจําหน้าที่อยู่ในกาลนั้นๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 18, 'พวกผู้พิพากษาจะอุตส่าห์ไต่สวน และดูเถิด ถ้าพยานนั้นเป็นพยานเท็จกล่าวปรักปรําพี่น้องของตนเป็นความเท็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 19, 'ท่านจงกระทําต่อพยานคนนั้นดังที่เขาตั้งใจจะกระทําแก่พี่น้องของตน ดังนี้แหละท่านจะกําจัดความชั่วจากท่ามกลางท่านเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 20, 'คนอื่นๆจะได้ยินได้ฟังและยําเกรงไม่กระทําผิดเช่นนั้นท่ามกลางพวกท่านทั้งหลายอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 21, 'อย่าให้นัยน์ตาของท่านเมตตาสงสาร ควรให้ชีวิตแทนชีวิต ตาแทนตา ฟันแทนฟัน มือแทนมือ เท้าแทนเท้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 1, '“เมื่อท่านทั้งหลายจะยกไปทําสงครามกับพวกศัตรูของท่าน เห็นม้า รถรบ และกองทัพมากมายใหญ่โตกว่าของท่าน ท่านอย่ากลัวเขาเลย เพราะว่าพระเยโฮวาห์พระเจ้าของท่านทรงสถิตอยู่กับท่าน ผู้ทรงนําท่านขึ้นมาจากแผ่นดินอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 2, 'และเมื่อใกล้จะรบกัน ปุโรหิตจะออกมาอยู่ข้างหน้าและกล่าวแก่ประชาชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 3, 'และจะกล่าวว่า ‘โอ อิสราเอล จงฟังเถิด วันนี้ท่านมาใกล้ จะสู้รบกับศัตรูของท่าน อย่าให้ใจของท่านทั้งหลายวิตก อย่ากลัวหรือหวาดหวั่น หรือครั่นคร้ามต่อศัตรูเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 4, 'เพราะว่าพระเยโฮวาห์พระเจ้าของท่านเสด็จไปกับท่าน ทรงต่อสู้ศัตรูของท่านเพื่อท่าน จะประทานชัยชนะแก่ท่าน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 5, 'แล้วนายทหารจะพูดกับประชาชนว่า ‘ใครที่สร้างบ้านใหม่ และยังไม่ได้ทําพิธีถวายบ้านนั้น ให้ผู้นั้นกลับไปบ้านของตน เกรงว่าเขาจะตายเสียในสงคราม และคนอื่นจะถวายบ้านนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 6, 'ใครที่ปลูกสวนองุ่นและยังมิได้รับประทานผลจากสวนองุ่นนั้น ให้ผู้นั้นกลับไปบ้าน เกรงว่าเขาจะตายเสียในสงคราม และคนอื่นจะรับประทานผลองุ่นนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 7, 'ผู้ใดที่หมั้นหญิงไว้เป็นภรรยาแล้ว แต่ยังไม่ได้แต่งงานกัน ให้ผู้นั้นกลับไปบ้านของตน เกรงว่าเขาจะตายเสียในสงคราม และชายอื่นจะได้นางไปเสีย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 8, 'และนายทหารจะพูดกับประชาชนต่อไปอีกว่า ‘ผู้ใดที่อยู่ที่นี่มีจิตใจกลัวและวิตก ให้ผู้นั้นกลับไปบ้านของตนเสีย เกรงว่าจิตใจพี่น้องของเขาจะละลายไปเหมือนกับจิตใจของเขา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 9, 'เมื่อนายทหารพูดกับประชาชนจบลงแล้ว ก็ให้เลือกตั้งผู้บังคับบัญชากองต่างๆให้เป็นหัวหน้าประชาชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 10, 'เมื่อพวกท่านเข้าไปใกล้เมืองซึ่งท่านจะไปสู้รบนั้น จงเสนอหลักสันติภาพแก่เมืองนั้นก่อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 11, 'ถ้าเขาตอบท่านอย่างสันติและเปิดประตูเมืองให้แก่ท่าน ก็ให้ประชาชนทั้งปวงที่พบอยู่ในเมืองนั้นทํางานโยธาให้แก่ท่านและปรนนิบัติท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 12, 'ถ้าเมืองนั้นไม่ร่วมสันติกับท่าน แต่กลับออกมารบ ก็ให้ท่านเข้าล้อมตีเมืองนั้นได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 13, 'เมื่อพระเยโฮวาห์พระเจ้าประทานเมืองนั้นไว้ในมือท่านแล้ว ท่านจงฆ่าชายทุกคนเสียด้วยคมดาบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 14, 'แต่ผู้หญิงและเด็ก สัตว์และทุกสิ่งในเมืองนั้น คือของที่ริบไว้ทั้งหมด ท่านจงยึดเอาเป็นของตัว ท่านจงอิ่มใจในของที่ริบมาจากศัตรูของท่าน ซึ่งพระเยโฮวาห์พระเจ้าของท่านประทานแก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 15, 'ท่านทั้งหลายจงกระทําเช่นนี้แก่ทุกหัวเมืองที่อยู่ไกลจากท่าน ซึ่งไม่ใช่หัวเมืองของประชาชาติใกล้ๆนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 16, 'แต่ในหัวเมืองของชนชาติทั้งหลายนี้ ซึ่งพระเยโฮวาห์พระเจ้าของท่านประทานแก่ท่านเป็นมรดก ท่านอย่าไว้ชีวิตสิ่งใดๆที่หายใจได้เลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 17, 'แต่จงทําลายเขาเสียให้สิ้นเชิง คือคนฮิตไทต์ คนอาโมไรต์ คนคานาอัน คนเปริสซี คนฮีไวต์ และคนเยบุส ดังที่พระเยโฮวาห์พระเจ้าของท่านทรงบัญชาไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 18, 'เพื่อว่าเขาจะมิได้สอนท่านให้กระทําสิ่งที่น่าสะอิดสะเอียนทั้งสิ้นของเขาซึ่งเขาได้กระทําต่อพวกพระของเขา เพราะการกระทําเช่นนั้นเป็นการกระทําบาปต่อพระเยโฮวาห์พระเจ้าของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 19, 'เมื่อท่านล้อมหัวเมืองหนึ่งอยู่ช้านาน เพื่อจะสู้รบเอาหัวเมืองนั้น อย่าใช้ขวานฟันทําลายต้นไม้ของเมืองนั้นเสีย เพราะท่านทั้งหลายจะรับประทานผลจากต้นไม้นั้น อย่าโค่นลงเพื่อใช้ในการล้อมเมืองนั้นเลย (เพราะต้นไม้ในทุ่งนาเป็นชีวิตสําหรับมนุษย์)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 20, 'เฉพาะต้นไม้ที่ท่านทราบว่าไม่ใช้เป็นอาหาร ท่านจะทําลายและโค่นลงก็ได้ เพื่อจะใช้สร้างเครื่องล้อมเมืองซึ่งสู้รบกับท่าน จนกว่าเมืองนั้นจะแตก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 1, '“ในแผ่นดินซึ่งพระเยโฮวาห์พระเจ้าของท่านประทานให้ท่านเป็นกรรมสิทธิ์นั้น ถ้าพบศพคนที่ถูกฆ่าทิ้งอยู่กลางแจ้ง ไม่ทราบว่าผู้ใดฆ่าเขาตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 2, 'ก็ให้พวกผู้ใหญ่และผู้พิพากษาของท่านออกมาวัดดูระยะทางถึงเมืองต่างๆที่อยู่รอบๆศพผู้ตายนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 3, 'แล้วเมืองที่อยู่ใกล้ที่สุดกับศพผู้ตายนั้น ให้พวกผู้ใหญ่ของเมืองนั้นนําวัวตัวเมียตัวหนึ่งซึ่งยังไม่เคยใช้งาน และยังไม่เคยเทียมแอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 4, 'และให้พวกผู้ใหญ่ของเมืองนั้นนําวัวเมียตัวนั้นไปที่หุบเขาซึ่งมีน้ําไหล ซึ่งไม่มีใครไถหรือหว่านเลย และให้ตัดคอวัวเมียที่หุบเขานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 5, 'และปุโรหิตผู้เป็นลูกหลานของเลวีจะต้องเข้ามาใกล้ ด้วยพระเยโฮวาห์พระเจ้าของท่านได้ทรงเลือกเขาไว้ให้ปรนนิบัติพระองค์ และให้อวยพรในพระนามของพระเยโฮวาห์ ให้การวิวาทและการทําร้ายทุกเรื่องสิ้นสุดลงด้วยคําของปุโรหิตเหล่านี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 6, 'และพวกผู้ใหญ่ทุกคนของเมืองที่อยู่ใกล้ผู้ถูกฆ่าที่สุดนั้นจะล้างมือของเขาทั้งหลายเหนือวัวเมียซึ่งถูกตัดคอที่ในหุบเขานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 7, 'และเขาจะเป็นพยานว่า ‘มือของเราทั้งหลายมิได้กระทําให้โลหิตของชายผู้นี้ตก และตาของเราทั้งหลายก็มิได้แลเห็นโลหิตของเขาตก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 8, 'โอ ข้าแต่พระเยโฮวาห์ ขอทรงลบมลทินบาปของประชาชนชาวอิสราเอลของพระองค์ ผู้ซึ่งพระองค์ได้ทรงไถ่ไว้ ขออย่าทรงถือโทษประชาชนชาวอิสราเอลของพระองค์เนื่องด้วยโลหิตที่ไร้ความผิด’ และจะทรงอภัยโทษอันเนื่องจากโลหิตนี้ให้แก่เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 9, 'ดังนี้แหละท่านจะกําจัดความผิดอันเนื่องจากโลหิตที่ไร้ความผิดนั้นเสียจากท่ามกลางท่าน เมื่อท่านกระทําสิ่งที่ถูกต้องในสายพระเนตรของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 10, 'เมื่อท่านออกไปสู้รบกับศัตรูของท่าน และพระเยโฮวาห์พระเจ้าของท่านทรงมอบเขาไว้ในมือของท่านแล้ว และท่านจับเขามาเป็นเชลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 11, 'และท่านเห็นหญิงงามคนหนึ่งในหมู่เชลยนั้น และปรารถนาอยากได้มาเป็นภรรยาของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 12, 'ท่านจงพาหญิงมาไว้ที่เรือนของท่าน ให้นางโกนศีรษะและตัดเล็บมือเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 13, 'และให้นางเปลื้องเครื่องแต่งกายอย่างเชลยออกและให้อยู่ในเรือนของท่าน ให้ไว้ทุกข์ถึงบิดามารดาของนางหนึ่งเดือนเต็ม หลังจากนั้นท่านจึงจะเข้าไปหานางและเป็นสามีของนางได้ และให้นางเป็นภรรยาของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 14, 'ภายหลังถ้าท่านไม่พอใจนางนั้นเสียแล้ว จงปล่อยนางไปตามแต่นางจะพอใจไปไหน อย่าขายนางเอาเงิน อย่ากระทําให้นางเป็นสินค้า เพราะท่านได้หยามเกียรตินางแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 15, 'ถ้าชายคนหนึ่งมีภรรยาสองคน รักคนหนึ่ง ชังอีกคนหนึ่ง ภรรยาทั้งสองคือทั้งคนที่รักและคนที่ชังก็กําเนิดบุตรด้วยกัน และบุตรชายหัวปีเป็นบุตรของภรรยาคนที่ตนชัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 16, 'เมื่อถึงวันแบ่งทรัพย์สินให้แก่บุตรชายเป็นมรดกนั้น อย่าให้เขากระทําแก่บุตรชายของภรรยาคนที่ตนรักนั้นอย่างกับเป็นบุตรหัวปี แทนบุตรชายของภรรยาที่ตนชัง ซึ่งเป็นบุตรหัวปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 17, 'แต่เขาต้องยอมรับบุตรหัวปีคือบุตรชายของภรรยาคนที่ตนชัง โดยแบ่งข้าวของให้แก่บุตรหัวปีสองเท่า เพราะว่าคนนี้เป็นต้นกําลังของบิดา สิทธิของบุตรหัวปีเป็นของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 18, 'ถ้าชายคนใดมีบุตรชายที่ดื้อและไม่อยู่ในโอวาท ไม่เชื่อฟังเสียงของบิดาของตน หรือเสียงของมารดาของตน แม้ว่าบิดามารดาจะได้ตีสอน เขาก็ไม่ยอมฟัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 19, 'ให้บิดามารดาจับตัวเขาให้ออกมาหาพวกผู้ใหญ่ของเมืองนั้น ณ ประตูเมืองที่เขาอาศัยอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 20, 'และเขาจะพูดกับพวกผู้ใหญ่ของเมืองนั้นว่า ‘บุตรชายของเราคนนี้เป็นคนดื้อดึงและไม่อยู่ในโอวาท ไม่เชื่อฟังเสียงเรา เป็นคนตะกละและขี้เมา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 21, 'แล้วบรรดาผู้ชายในเมืองนั้นจะเอาหินขว้างเขาให้ตาย ดังนั้นท่านจะได้กําจัดความชั่วเสียจากท่ามกลางท่าน คนอิสราเอลทั้งปวงจะได้ยินและยําเกรง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 22, 'ถ้าคนใดได้กระทําความผิดอันมีโทษถึงตาย และเขาถูกประหารชีวิต และแขวนเขาไว้ที่ต้นไม้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 23, 'อย่าให้ศพค้างอยู่ที่ต้นไม้ข้ามคืน ท่านจงฝังเขาเสียในวันเดียวกันนั้น (ด้วยว่าผู้ที่ต้องถูกแขวนไว้บนต้นไม้ก็ต้องถูกสาปแช่งโดยพระเจ้า) ท่านอย่ากระทําให้แผ่นดินของท่านซึ่งพระเยโฮวาห์พระเจ้าของท่านประทานแก่ท่านให้เป็นมรดกนั้นเป็นมลทิน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 1, '“เมื่อท่านทั้งหลายเห็นวัวหรือแกะของพี่น้องของท่านหลงมาอย่านิ่งเฉยเสีย จงพาสัตว์เหล่านั้นกลับไปให้พี่น้องของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 2, 'ถ้าบ้านเขาอยู่ไม่ใกล้ หรือท่านไม่รู้จักตัวเขา จงนําสัตว์นั้นมาไว้ที่บ้านของท่านและให้อยู่กับท่านจนพี่น้องมาเที่ยวหา แล้วท่านจงมอบคืนให้เขาไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 3, 'ลาของพี่น้องท่านก็จงคืนให้เหมือนกัน เสื้อผ้าของพี่น้องท่านก็จงคืนให้เหมือนกัน สิ่งใดของพี่น้องที่หายไป และที่ท่านพบเข้าท่านจงคืนให้เหมือนกัน ท่านอย่านิ่งเฉยเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 4, 'ถ้าท่านเห็นลาหรือวัวของพี่น้องล้มอยู่ตามทาง อย่านิ่งเฉยเสีย ท่านจงช่วยพยุงสัตว์เหล่านั้นขึ้นอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 5, 'อย่าให้ผู้หญิงสวมใส่สิ่งที่เป็นของผู้ชาย และอย่าให้ผู้ชายคนใดคนหนึ่งสวมใส่เสื้อผ้าของผู้หญิง เพราะทุกคนที่กระทําเช่นนั้นก็เป็นที่สะอิดสะเอียนต่อพระเยโฮวาห์พระเจ้าของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 6, 'ถ้าท่านเผอิญไปพบรังนกอยู่ตามทาง บนต้นไม้หรือพื้นดิน มีลูกนกหรือไข่และแม่นกกกอยู่บนลูกนกหรือไข่นั้น ท่านอย่าเอาแม่นกกับลูกนกไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 7, 'ท่านจงปล่อยแม่นกไปเสีย แต่ลูกนกนั้นท่านจะเอาไปเป็นของท่านก็ได้ เพื่อท่านจะไปดีมาดี และท่านจะมีอายุยืนนาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 8, 'เมื่อท่านก่อเรือนใหม่ จงก่อขอบขึ้นกันไว้ที่ดาดฟ้าหลังคา เพื่อท่านจะมิได้นําโทษเนื่องด้วยโลหิตตกมาสู่เรือนนั้น เพราะมีคนพลัดตกลงมาจากหลังคาตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 9, 'อย่าเอาเมล็ดพืชหลายชนิดหว่านลงในสวนองุ่นของท่าน เกรงว่าทั้งพืชผลที่ท่านหว่านและผลองุ่นของสวนนั้นเป็นมลทิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 10, 'ท่านอย่าเอาวัวและลาเข้าเทียมไถด้วยกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 11, 'ท่านอย่าสวมเครื่องแต่งกายที่ทอด้วยผ้าหลายชนิด เช่นขนสัตว์ปนด้วยป่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 12, 'ท่านจงทําพู่ห้อยไว้ที่มุมทั้งสี่ของชายเสื้อคลุมของท่าน ซึ่งท่านใช้คลุมตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 13, 'ถ้าชายคนใดได้ภรรยา และได้เข้าหานาง แล้วเกิดเกลียดชังนาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 14, 'และหาเหตุว่าหญิงนั้นประพฤติสิ่งน่าอาย กระทําให้ชื่อเสียงของนางเสียหาย โดยกล่าวว่า ‘ข้ารับหญิงคนนี้มาเป็นภรรยา ครั้นข้าเข้าหานางก็เห็นว่านางมิได้เป็นพรหมจารี’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 15, 'บิดาของหญิงสาวคนนั้นและมารดาจะต้องนําของสําคัญอันเป็นพยานว่า หญิงนั้นเป็นพรหมจารีมาให้พวกผู้ใหญ่ของเมืองนั้นที่ประตูเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 16, 'และบิดาของหญิงสาวนั้นจะบอกกับพวกผู้ใหญ่ว่า ‘ข้าได้ยกลูกสาวของข้าให้เป็นภรรยาชายคนนี้ และเขากลับเกลียดชัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 17, 'ดูเถิด ชายผู้นี้หาเหตุกล่าวติเตียนว่า “ข้าพเจ้าไม่เห็นว่าบุตรสาวของท่านเป็นพรหมจารีเลย” นี่แหละเป็นของสําคัญว่าลูกสาวของข้าเป็นหญิงพรหมจารี’ แล้วเขาจะคลี่ผ้านั้นออกต่อหน้าพวกผู้ใหญ่ของเมืองนั้นให้เป็นพยาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 18, 'ให้พวกผู้ใหญ่ของเมืองนั้นจับชายคนนั้นมาเฆี่ยน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 19, 'และปรับเขาเป็นเงินหนึ่งร้อยเชเขล และมอบเงินนั้นให้แก่บิดาของหญิงสาว เพราะเขาทําให้หญิงพรหมจารีอิสราเอลคนหนึ่งเสียชื่อ หญิงนั้นจะเป็นภรรยาของเขาต่อไป เขาจะหย่าร้างไม่ได้เลยตลอดชีวิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 20, 'แต่ถ้าเรื่องนั้นเป็นความจริง และหาของสําคัญอันเป็นพยานว่า หญิงนั้นเป็นพรหมจารีสําหรับหญิงสาวนั้นไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 21, 'เขาจะพาหญิงสาวนั้นออกมานอกประตูเรือนบิดาของเธอ แล้วพวกผู้ชายในเมืองของเธอจะเอาหินขว้างเธอให้ตาย เพราะเธอได้กระทําความโง่เขลาในอิสราเอล คือเป็นหญิงโสเภณีในเรือนของบิดา ดังนี้แหละท่านจะกําจัดความชั่วออกจากท่ามกลางท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 22, 'ถ้าพบชายคนหนึ่งไปร่วมกับภรรยาของคนอื่น ทั้งสองคน คือชายที่ไปร่วมกับหญิงและหญิงคนนั้นจะต้องมีโทษถึงตาย ดังนี้แหละท่านจะกําจัดความชั่วจากอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 23, 'ถ้ามีหญิงพรหมจารีคนหนึ่งหมั้นไว้กับสามีแล้ว และมีชายคนหนึ่งไปพบเธอในเมือง และได้ร่วมกับเธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 24, 'ท่านจงพาเขาทั้งสองออกไปยังประตูเมืองนั้น และท่านจงขว้างเขาทั้งสองด้วยหินให้ตายเสีย หญิงสาวคนนั้นเพราะมิได้ร้องโวยวายขึ้นแม้ว่าจะอยู่ในเมือง ชายคนนั้นเพราะว่าเขาได้หยามเกียรติภรรยาของเพื่อนบ้าน ดังนี้แหละท่านทั้งหลายจะขจัดความชั่วเสียจากท่ามกลางท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 25, 'แต่ถ้าชายคนหนึ่งไปพบหญิงสาวที่คนอื่นหมั้นไว้แล้วที่กลางทุ่ง ชายคนนั้นจับตัวหญิงคนนั้นและได้ร่วมกับเธอ เฉพาะผู้ชายคนที่ร่วมกับเธอเท่านั้นจะต้องมีโทษถึงตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 26, 'แต่ท่านอย่าทําโทษหญิงสาวนั้นเลย ฝ่ายหญิงสาวนั้นไม่มีความผิดสิ่งใดที่จะต้องมีโทษถึงตาย เพราะคดีเรื่องนี้ก็เหมือนกับคดีเรื่องชายคนหนึ่งเข้าต่อสู้และฆ่าเพื่อนบ้านของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 27, 'เพราะชายนั้นพบเธอที่กลางทุ่ง แม้ว่าหญิงสาวที่เขาหมั้นไว้คนนั้นจะร้องขอความช่วยเหลือก็ไม่มีผู้ใดมาช่วยได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 28, 'ถ้าชายคนหนึ่งพบหญิงพรหมจารียังไม่มีคนหมั้น เขาจึงจับตัวเธอและได้ร่วมกับเธอมีผู้รู้เห็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 29, 'แล้วชายผู้ที่ได้ร่วมกับเธอนั้นจะต้องมอบเงินห้าสิบเชเขลให้แก่บิดาของหญิงสาวคนนั้น และเธอจะตกเป็นภรรยาของเขา เพราะเขาได้หยามเกียรติเธอ เขาจะหย่าร้างเธอไม่ได้ตลอดชีวิตของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 30, 'ห้ามมิให้ผู้ชายคนใดเอาภรรยาของบิดามาเป็นภรรยาของตน และห้ามมิให้เปิดผ้าของนางผู้เป็นของบิดา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 1, '“ชายคนใดได้รับบาดเจ็บที่ลูกอัณฑะหรืออวัยวะสืบพันธุ์ถูกตัดออก อย่าให้เข้าในที่ชุมนุมของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 2, 'ห้ามไม่ให้ลูกนอกกฎหมายเข้าในชุมนุมชนของพระเยโฮวาห์ อย่าให้ลูกหลานของเขาเข้าในชุมนุมชนของพระเยโฮวาห์จนถึงสิบชั่วอายุคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 3, 'อย่าให้คนอัมโมนหรือคนโมอับเข้าในชุมนุมชนของพระเยโฮวาห์ บุคคลที่เป็นลูกหลานของคนทั้งสองตระกูลนี้ห้ามไม่ให้เข้าในชุมนุมชนของพระเยโฮวาห์เลยจนถึงสิบชั่วอายุคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 4, 'เพราะว่าคนเหล่านี้มิได้มาต้อนรับท่านทั้งหลายตามทางด้วยขนมปังและน้ําเมื่อท่านออกจากอียิปต์ และเพราะว่าเขาได้จ้างบาลาอัมบุตรชายเบโอร์มาจากเปโธร์แห่งเมโสโปเตเมียให้สาปแช่งท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 5, 'อย่างไรก็ดีพระเยโฮวาห์พระเจ้าของท่านมิได้ฟังบาลาอัม แต่พระเยโฮวาห์พระเจ้าของท่านทรงเปลี่ยนคําสาปแช่งให้เป็นคําอวยพรท่าน เพราะว่าพระเยโฮวาห์พระเจ้าของท่านทรงรักท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 6, 'ท่านอย่าเสริมสันติภาพหรือความเจริญให้เขาตลอดชีวิตของท่านทั้งหลายเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 7, 'ท่านทั้งหลายอย่าเกลียดคนเอโดม เพราะเขาเป็นพี่น้องของท่าน ท่านอย่าเกลียดคนอียิปต์ เพราะท่านทั้งหลายเป็นคนต่างด้าวอยู่ในแผ่นดินของเขานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 8, 'เด็กๆชั่วอายุที่สามซึ่งเกิดกับคนเหล่านี้จะเข้าในชุมนุมชนของพระเยโฮวาห์ก็ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 9, 'เมื่อท่านออกไปสู้รบกับศัตรูของท่าน ท่านจงระวังตัวให้พ้นจากสิ่งชั่วทุกอย่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 10, 'ถ้าคนใดในพวกท่านไม่สะอาดด้วยเหตุการณ์ที่เกิดขึ้นในเวลากลางคืน เขาต้องไปอยู่นอกค่าย อย่าให้เขาเข้ามาในค่าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 11, 'แต่เมื่อถึงเวลาเย็นแล้วให้เขาอาบน้ําชําระตัว และเมื่อดวงอาทิตย์ตกแล้วเขาจะกลับเข้ามาในค่ายก็ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 12, 'ท่านทั้งหลายต้องมีที่ภายนอกค่าย เพื่อจะออกไปถึงได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 13, 'และท่านต้องมีไม้เสี้ยมรวมไว้กับเครื่องอาวุธ และเมื่อท่านนั่งลงในที่ข้างนอกนั้น ท่านจงใช้ไม้ขุดหลุมไว้ และหันไปกลบสิ่งปฏิกูลของท่านเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 14, 'เพราะว่าพระเยโฮวาห์พระเจ้าของท่านทรงดําเนินอยู่ท่ามกลางค่ายของท่าน เพื่อจะช่วยท่านให้พ้น และมอบศัตรูของท่านไว้ต่อหน้าท่าน เพราะฉะนั้นค่ายของท่านต้องบริสุทธิ์ เพื่อพระองค์จะไม่ทอดพระเนตรสิ่งโสโครกในหมู่พวกท่าน และเสด็จไปเสียจากท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 15, 'ถ้ามีทาสหนีจากนายของเขามาอยู่กับท่าน อย่าจับทาสนั้นไปส่งนายของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 16, 'จงให้ทาสนั้นอยู่กับท่าน อยู่ในหมู่พวกท่าน ให้อยู่ในที่ซึ่งเขาจะเลือกในประตูเมืองหนึ่งประตูเมืองใดตามความพอใจของเขา อย่ากดขี่ข่มเหงเขาเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 17, 'ผู้หญิงชาวอิสราเอลนั้น อย่าให้คนหนึ่งคนใดเป็นหญิงโสเภณี อย่าให้บุตรชายอิสราเอลคนหนึ่งคนใดเป็นกะเทย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 18, 'ท่านอย่านําค่าจ้างของหญิงโสเภณี หรือค่าซื้อขายสุนัข มาในพระนิเวศของพระเยโฮวาห์พระเจ้าของท่านเพื่อกระทําตามคําสัตย์ปฏิญาณใดๆ เพราะของทั้งสองอย่างนี้เป็นสิ่งที่น่าสะอิดสะเอียนต่อพระเยโฮวาห์พระเจ้าของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 19, 'ท่านอย่าให้พี่น้องของท่านยืมเงินเพื่อเอาดอกเบี้ย ไม่ว่าดอกเบี้ยเงินกู้ หรือดอกเบี้ยเครื่องบริโภค หรือดอกเบี้ยของสิ่งใดๆที่ให้ยืมเพื่อเอาดอกเบี้ย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 20, 'ท่านจะให้คนต่างด้าวยืมเพื่อเอาดอกเบี้ยก็ได้ แต่สําหรับพี่น้องของท่าน ท่านอย่าให้ยืมเพื่อเอาดอกเบี้ย เพื่อพระเยโฮวาห์พระเจ้าของท่านจะทรงอํานวยพระพรแก่ท่านในทุกสิ่งซึ่งมือท่านกระทําในแผ่นดิน ซึ่งท่านกําลังจะเข้าไปยึดครองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 21, 'เมื่อท่านปฏิญาณต่อพระเยโฮวาห์พระเจ้าของท่าน ท่านอย่าละเลยไม่ทําตามคําปฏิญาณนั้น เพราะว่าพระเยโฮวาห์พระเจ้าของท่านจะทรงเรียกเอาจากท่านเป็นแน่ และท่านจะมีบาป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 22, 'แต่ถ้าท่านงดไม่ปฏิญาณ ท่านก็จะไม่มีบาป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 23, 'ถ้อยคําที่ผ่านออกมาจากริมฝีปากของท่าน ท่านจงระวังที่จะรักษาและกระทําตาม เป็นเครื่องบูชาด้วยใจสมัคร ตามที่ท่านได้ปฏิญาณต่อพระเยโฮวาห์พระเจ้าของท่าน ซึ่งท่านสัญญาไว้ด้วยปากของท่านแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 24, 'เมื่อท่านเข้าไปในสวนองุ่นแห่งเพื่อนบ้านของท่าน ท่านจะรับประทานผลองุ่นให้อิ่มหนําตามที่ท่านปรารถนาก็ได้ แต่อย่าใส่ในภาชนะของท่านไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 25, 'เมื่อท่านเข้าไปในนาของเพื่อนบ้านของท่าน ท่านจะเอามือเด็ดรวงข้าวมาก็ได้ แต่ท่านจะใช้เคียวเกี่ยวข้าวของเพื่อนบ้านของท่านไม่ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 1, '“เมื่อชายคนใดคนหนึ่งมีภรรยาแต่งงานอยู่กินด้วยกันกับนาง และต่อมานางไม่เป็นที่ชอบในสายตาของสามีเพราะเขาพบสิ่งมลทินในตัวนาง ก็ให้เขาทําหนังสือหย่าใส่มือนาง แล้วไล่ออกจากเรือนไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 2, 'และนางก็ออกจากเรือนไปเสีย และถ้านางไปเป็นภรรยาของชายอีกคนหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 3, 'และสามีคนหลังนี้ชังนางจึงทําหนังสือหย่าใส่มือนางแล้วไล่นางออกจากเรือน หรือสามีคนหลังนี้ที่ได้นางเป็นภรรยาถึงแก่ความตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 4, 'สามีคนเดิมที่ได้ไล่นางไปนั้นจะรับนางหลังจากที่นางเป็นมลทินแล้วกลับมาเป็นภรรยาอีกไม่ได้ เพราะเป็นสิ่งที่น่าสะอิดสะเอียนต่อพระพักตร์พระเยโฮวาห์ ท่านทั้งหลายอย่ากระทําให้แผ่นดินซึ่งพระเยโฮวาห์พระเจ้าของท่านประทานแก่ท่านให้เป็นมรดกนั้นมีบาป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 5, 'เมื่อชายคนใดมีภรรยาใหม่ๆ อย่าให้ผู้นั้นต้องไปทัพ หรือทําราชการอย่างใด ให้เขาอยู่บ้านปีหนึ่งเพื่อเขาจะให้ภรรยาซึ่งเขาได้มานั้นมีความสุข');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 6, 'อย่าให้ผู้ใดยึดโม่หรือหินโม่ลูกที่ปฏิญาณไว้เป็นประกัน เพราะสิ่งที่ยึดเป็นประกันนั้นเขาใช้เลี้ยงชีพของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 7, 'ถ้าชายคนใดถูกเขาจับได้ว่าได้ลักพี่น้องคนอิสราเอลคนหนึ่งคนใดไปใช้เป็นทาสหรือขายเสีย ขโมยคนนั้นจะต้องมีโทษถึงตาย ดังนี้แหละท่านจะกําจัดความชั่วเสียจากท่ามกลางท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 8, 'ท่านทั้งหลายจงระวังเรื่องโรคเรื้อน จงระวังที่จะกระทําตามคําชี้แจงของปุโรหิตคนเลวี ดังที่ข้าพเจ้าได้บัญชาเขาไว้ ท่านจงระวังที่จะทําตามอย่างนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 9, 'จงระลึกถึงเรื่องที่พระเยโฮวาห์พระเจ้าของท่านกระทําแก่มิเรียมตามทาง เมื่อท่านทั้งหลายออกจากอียิปต์แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 10, 'เมื่อท่านทั้งหลายให้พี่น้องขอยืมสิ่งใด อย่าเข้าไปในเรือนของเขาและเอาสิ่งที่เขาใช้เป็นประกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 11, 'ท่านจงยืนอยู่ภายนอก และคนที่ยืมนั้นจะนําของประกันออกมาให้ท่านเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 12, 'ถ้าเขาเป็นคนยากจน อย่าเอาของประกันนั้นเก็บไว้จนข้ามคืน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 13, 'เมื่อดวงอาทิตย์ตกท่านจงเอาของประกันนั้นมาคืนให้เขา เพื่อเขาจะมีของคลุมตัวเมื่อเวลานอน และอวยพรแก่ท่าน นี่จะเป็นความชอบธรรมแก่ท่าน เฉพาะพระพักตร์พระเยโฮวาห์พระเจ้าของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 14, 'ท่านอย่าข่มขี่ลูกจ้างที่เป็นคนยากจนและขัดสน ไม่ว่าเขาจะเป็นพี่น้องของท่าน หรือคนต่างด้าวอยู่ในแผ่นดินภายในประตูเมืองของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 15, 'ท่านจงจ่ายเงินค่าจ้างวันนั้นให้แก่เขา ก่อนดวงอาทิตย์ตก เพราะเขาเป็นคนยากจน และมีใจจดจ่ออยู่ที่ค่าจ้างนั้น ด้วยเกรงว่าเขาจะกล่าวหาท่านต่อพระเยโฮวาห์ และจะเป็นความบาปแก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 16, 'อย่าให้บิดาต้องรับโทษถึงตายแทนบุตรของตน หรือให้บุตรต้องรับโทษถึงตายแทนบิดาของตน ให้ทุกคนรับโทษถึงตายเนื่องด้วยบาปของคนนั้นเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 17, 'ท่านทั้งหลายอย่าให้เสียความยุติธรรมซึ่งควรได้แก่คนต่างด้าว หรือควรได้แก่ลูกกําพร้าพ่อ และอย่ารับเสื้อผ้าของหญิงม่ายไว้เป็นประกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 18, 'แต่ท่านพึงจําไว้ว่า ท่านเคยเป็นทาสอยู่ในอียิปต์ และพระเยโฮวาห์พระเจ้าของท่านไถ่ท่านออกจากที่นั่น เพราะฉะนั้นข้าพเจ้าจึงบัญชาท่านให้กระทําเช่นนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 19, 'เมื่อท่านเกี่ยวข้าวในนาของท่าน และลืมฟ่อนข้าวไว้ในนาฟ่อนหนึ่ง อย่ากลับไปเอามาเลย ให้เป็นของคนต่างด้าว ลูกกําพร้าพ่อและหญิงม่าย เพื่อพระเยโฮวาห์พระเจ้าของท่านจะอวยพระพรแก่กิจการทั้งหลายแห่งมือของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 20, 'เมื่อท่านฟาดต้นมะกอกเทศ ท่านอย่าเก็บที่กิ่งเดิมซ้ําครั้งที่สอง ให้เหลือไว้สําหรับคนต่างด้าว ลูกกําพร้าพ่อและหญิงม่าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 21, 'เมื่อท่านเก็บผลองุ่นจากสวนองุ่นของท่าน ท่านอย่าไปเก็บเล็มอีก จงเหลือไว้สําหรับคนต่างด้าว ทั้งลูกกําพร้าพ่อและหญิงม่าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 22, 'ท่านจงจําไว้ว่า ท่านเคยเป็นทาสอยู่ในแผ่นดินอียิปต์ เพราะฉะนั้นข้าพเจ้าจึงบัญชาท่านให้กระทําเช่นนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 1, '“ถ้าสองคนเป็นความกันถึงโรงศาล เมื่อพวกผู้พิพากษาพิจารณาความของเขาทั้งสองแล้ว และประกาศความบริสุทธิ์ของฝ่ายถูก และกล่าวโทษฝ่ายผิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 2, 'ถ้าผู้ผิดสมควรถูกโบยก็ให้ผู้พิพากษาให้เขานอนลง แล้วกําหนดให้โบยต่อหน้ามากน้อยตามความผิดของผู้นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 3, 'ให้โบยเขาสี่สิบทีก็ได้ แต่อย่าให้เกินนั้นไปเลย เกรงว่าถ้าโบยเขาเกินนั้น พี่น้องของท่านก็เป็นที่ดูถูกของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 4, 'อย่าเอาตะกร้าครอบปากวัว เมื่อมันกําลังนวดข้าวอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 5, 'ถ้าพี่น้องอยู่ด้วยกัน และคนหนึ่งตายเสียหามีบุตรไม่ ภรรยาของผู้ที่ตายนั้นจะออกไปเป็นภรรยาของคนนอกไม่ได้ ให้พี่น้องของสามีนางเข้าไปหานางและรับหญิงนั้นมาเป็นภรรยา และทําหน้าที่ของสามีแก่นาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 6, 'บุตรหัวปีที่เกิดมากับหญิงคนนั้นให้สืบชื่อพี่น้องคนที่ตายไปนั้น เพื่อชื่อของเขาจะมิได้ลบไปจากอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 7, 'ถ้าชายคนนั้นไม่ประสงค์จะรับภรรยาของพี่น้องของเขา ก็ให้ภรรยาของพี่น้องของเขาไปหาพวกผู้ใหญ่ที่ประตูเมืองและกล่าวว่า ‘พี่น้องของสามีดิฉันไม่ยอมสืบชื่อของพี่น้องของเขาในอิสราเอล เขาไม่ยอมรับหน้าที่ของสามีของดิฉัน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 8, 'แล้วพวกผู้ใหญ่ของเมืองนั้นจะเรียกชายคนนั้นมาพูดกับเขา ถ้าเขายังยืนยันโดยกล่าวว่า ‘ข้าพเจ้าไม่ประสงค์จะรับนาง’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 9, 'แล้วนางนั้นจะเข้าไปใกล้ชายคนนั้นต่อหน้าพวกผู้ใหญ่ดึงเอารองเท้าของชายคนนั้นออกมาข้างหนึ่ง และถ่มน้ําลายรดหน้าชายนั้นแล้วกล่าวว่า ‘ต้องกระทําเช่นนี้กับผู้ชายที่ไม่ยอมสร้างครอบครัวของพี่น้องของตน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 10, 'ในอิสราเอลเขาจะเรียกชื่อครอบครัวนี้ว่า ‘วงศ์วานที่รองเท้าถูกดึงออก’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 11, 'ถ้าชายสองคนวิวาททุบตีกันและภรรยาของชายคนหนึ่งเข้ามาใกล้จะช่วยสามีของตนให้พ้นจากมือของผู้ที่ตี และนางยื่นมือออกเค้นของลับของผู้ชายคนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 12, 'ท่านจงตัดมือของนางทิ้งเสีย อย่าให้ตาของท่านสงสารนางเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 13, 'ท่านอย่ามีลูกตุ้มสําหรับตาชั่งต่างกันไว้ในถุง อันหนึ่งหนักอันหนึ่งเบา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 14, 'ในเรือนของท่านอย่าให้มีเครื่องตวงหลายชนิด ใหญ่อันหนึ่งเล็กอันหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 15, 'ท่านจงมีลูกตุ้มอันสมบูรณ์และเที่ยงตรงและมีถังตวงอันสมบูรณ์และเที่ยงตรง เพื่อว่าวันคืนของท่านจะยืนนานในแผ่นดินซึ่งพระเยโฮวาห์พระเจ้าของท่านประทานแก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 16, 'เพราะว่าทุกคนที่กระทําสิ่งเหล่านั้น และทุกคนที่กระทําสิ่งต่างๆอย่างไม่ชอบธรรมก็เป็นผู้ที่น่าสะอิดสะเอียนต่อพระเยโฮวาห์พระเจ้าของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 17, 'จงระลึกถึงการที่คนอามาเลขกระทําแก่ท่านทั้งหลายตามทางที่ท่านออกจากอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 18, 'เขาได้ออกมาพบท่านตามทาง และโจมตีพวกที่อยู่รั้งท้าย คือบรรดาคนที่อ่อนกําลังที่อยู่รั้งท้าย เมื่อท่านอ่อนเพลียเมื่อยล้า เขามิได้ยําเกรงพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 19, 'เพราะฉะนั้นเมื่อพระเยโฮวาห์พระเจ้าของท่านประทานให้ท่านหยุดพักจากบรรดาศัตรูที่อยู่รอบข้างแล้ว ในแผ่นดินที่พระเยโฮวาห์พระเจ้าของท่านประทานแก่ท่านเป็นมรดกให้เป็นกรรมสิทธิ์นั้น ท่านทั้งหลายจงลบล้างคนอามาเลขเสียจากความทรงจําภายใต้ฟ้า ท่านทั้งหลายอย่าลืมเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 1, '“เมื่อท่านทั้งหลายเข้าไปในแผ่นดินซึ่งพระเยโฮวาห์พระเจ้าของท่านประทานแก่ท่านเป็นมรดก และท่านเข้ายึดเป็นกรรมสิทธิ์ และอาศัยอยู่ในแผ่นดินนั้นแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 2, 'ท่านจงเอาผลแรกทั้งหมดจากดินซึ่งท่านเกี่ยวเก็บมาจากแผ่นดินของท่าน ซึ่งพระเยโฮวาห์พระเจ้าของท่านประทานแก่ท่าน จงนําผลนั้นใส่กระจาด นําไปยังที่ซึ่งพระเยโฮวาห์พระเจ้าของท่านจะทรงเลือกไว้ เพื่อให้พระนามของพระองค์ประทับที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 3, 'ท่านจงไปหาปุโรหิตผู้ประจําเวรอยู่ในเวลานั้น และกล่าวแก่เขาว่า ‘ข้าพเจ้ายอมรับในวันนี้แด่พระเยโฮวาห์พระเจ้าของท่านว่า ข้าพเจ้าได้เข้ามาในแผ่นดินซึ่งพระเยโฮวาห์ทรงปฏิญาณแก่บรรพบุรุษว่าจะประทานแก่เราทั้งหลาย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 4, 'แล้วปุโรหิตจะรับกระจาดไปจากมือของท่าน และวางไว้ที่หน้าแท่นบูชาแห่งพระเยโฮวาห์พระเจ้าของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 5, 'และท่านจงตอบสนองต่อพระพักตร์พระเยโฮวาห์พระเจ้าของท่านว่า ‘บิดาของข้าพระองค์เป็นชาวซีเรียที่กําลังพินาศอยู่ ท่านลงไปในอียิปต์และอาศัยอยู่ที่นั่นมีแต่จํานวนน้อย ที่นั่นท่านก็กลายเป็นประชาชาติหนึ่งใหญ่โตแข็งแรงและมีพลเมืองมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 6, 'และชาวอียิปต์ทําแก่เราอย่างเลวทราม และข่มใจเรา และทําให้เราทํางานหนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 7, 'แล้วเมื่อเราร้องทูลต่อพระเยโฮวาห์พระเจ้าแห่งบรรพบุรุษของเรา พระเยโฮวาห์ทรงสดับเสียงของเรา ทอดพระเนตรความทุกข์ใจของเรา การลําบากของเรา การถูกบีบคั้นของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 8, 'และพระเยโฮวาห์ทรงนําเราทั้งหลายออกจากอียิปต์ด้วยพระหัตถ์อันทรงฤทธิ์และด้วยพระกรที่เหยียดออก ด้วยความน่ากลัวยิ่ง ด้วยหมายสําคัญและการมหัศจรรย์ต่างๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 9, 'พระองค์ทรงนําเรามาที่นี่และประทานแผ่นดินนี้แก่เรา เป็นแผ่นดินที่มีน้ํานมและน้ําผึ้งไหลบริบูรณ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 10, 'โอ ข้าแต่พระเยโฮวาห์เจ้าข้า ดูเถิด บัดนี้ข้าพระองค์นําผลรุ่นแรกมาจากแผ่นดินนั้นซึ่งพระองค์ประทานแก่ข้าพระองค์’ และท่านจงวางสิ่งของนั้นต่อพระพักตร์พระเยโฮวาห์พระเจ้าของท่าน และกราบนมัสการต่อพระพักตร์พระเยโฮวาห์พระเจ้าของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 11, 'ท่านจงปีติร่าเริงด้วยของดีทุกสิ่งซึ่งพระเยโฮวาห์พระเจ้าของท่านประทานแก่ท่าน แก่ครอบครัวของท่าน แก่ตัวท่านเอง และคนเลวี และคนต่างด้าวที่อาศัยอยู่ในหมู่พวกท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 12, 'เมื่อท่านถวายสิบชักหนึ่งทั้งหลายจากผลไม้ของท่านเสร็จแล้วในปีที่สามอันเป็นปีสิบชักหนึ่ง คือให้สิบชักหนึ่งนั้นแก่คนเลวีและคนต่างด้าว ลูกกําพร้าพ่อและหญิงม่าย เพื่อเขาจะได้รับประทานให้อิ่มหนําภายในประตูเมืองของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 13, 'แล้วท่านจงทูลต่อพระพักตร์พระเยโฮวาห์พระเจ้าของท่านว่า ‘ข้าพระองค์ยกส่วนศักดิ์สิทธิ์ออกจากบ้านของข้าพระองค์แล้ว และยิ่งกว่านั้นข้าพระองค์ได้ให้แก่คนเลวีและคนต่างด้าว ลูกกําพร้าพ่อและหญิงม่าย ตามพระบัญญัติซึ่งพระองค์ทรงบัญชาไว้แก่ข้าพระองค์ทุกประการ ข้าพระองค์มิได้ละเมิดพระบัญญัติของพระองค์ในข้อใดเลย และข้าพระองค์มิได้ลืมเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 14, 'ข้าพระองค์มิได้รับประทานสิบชักหนึ่งเมื่อข้าพระองค์ไว้ทุกข์หรือยกส่วนใดออกไปเมื่อข้าพระองค์เป็นมลทิน หรืออุทิศส่วนใดเพื่อผู้ตาย แต่ข้าพระองค์ได้เชื่อฟังพระสุรเสียงของพระเยโฮวาห์พระเจ้าของข้าพระองค์ ข้าพระองค์ได้กระทําตามทุกสิ่งที่พระองค์ทรงบัญชาไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 15, 'ขอพระองค์ทอดพระเนตรจากสถานประทับบริสุทธิ์ของพระองค์คือจากสวรรค์ และขอทรงอํานวยพระพรแก่อิสราเอลประชาชนของพระองค์ และแก่ที่ดินซึ่งพระองค์ประทานแก่ข้าพระองค์ทั้งหลาย ดังที่พระองค์ทรงปฏิญาณไว้กับบรรพบุรุษของข้าพระองค์ เป็นแผ่นดินที่มีน้ํานมและน้ําผึ้งไหลบริบูรณ์’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 16, 'วันนี้พระเยโฮวาห์พระเจ้าของท่านทรงบัญชาท่าน ให้กระทําตามกฎเกณฑ์และคําตัดสินเหล่านี้ ฉะนั้นท่านจงระวังที่จะกระทําตามด้วยสุดจิตสุดใจของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 17, 'ในวันนี้ท่านได้ยอมรับแล้วว่า พระเยโฮวาห์เป็นพระเจ้าของท่าน และท่านจะดําเนินตามพระมรรคาของพระองค์ และรักษากฎเกณฑ์ พระบัญญัติ และคําตัดสินของพระองค์ และจะเชื่อฟังพระสุรเสียงของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 18, 'และในวันนี้พระเยโฮวาห์ทรงรับว่า ท่านทั้งหลายเป็นชนชาติในกรรมสิทธิ์ของพระองค์ ดังที่พระองค์ทรงสัญญาไว้กับท่าน และว่าท่านจะรักษาพระบัญญัติทั้งสิ้นของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 19, 'และว่าพระองค์จะทรงตั้งท่านให้สูงเหนือบรรดาประชาชาติซึ่งพระองค์ได้ทรงสร้าง ในเรื่องสรรเสริญ ชื่อเสียงและเกียรติยศ และว่าท่านจะเป็นชนชาติที่บริสุทธิ์แด่พระเยโฮวาห์พระเจ้าของท่าน ดังที่พระองค์ตรัสแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 1, 'โมเสสและพวกผู้ใหญ่ของคนอิสราเอลได้บัญชาประชาชนว่า “จงรักษาพระบัญญัติทั้งสิ้นซึ่งข้าพเจ้าบัญชาท่านทั้งหลายในวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 2, 'ในวันที่ท่านทั้งหลายจะข้ามแม่น้ําจอร์แดนเข้าสู่แผ่นดินซึ่งพระเยโฮวาห์พระเจ้าของท่านประทานแก่ท่าน ท่านจงตั้งศิลาก้อนใหญ่ๆขึ้น เอาปูนโบกเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 3, 'แล้วท่านจงจารึกบรรดาถ้อยคําของพระราชบัญญัตินี้ไว้บนนั้น เมื่อท่านข้ามไปเพื่อเข้าแผ่นดินซึ่งพระเยโฮวาห์พระเจ้าของท่านประทานแก่ท่าน เป็นแผ่นดินซึ่งมีน้ํานมและน้ําผึ้งไหลบริบูรณ์ ดังที่พระเยโฮวาห์พระเจ้าแห่งบรรพบุรุษของท่านได้ทรงสัญญาไว้กับท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 4, 'ฉะนั้นเมื่อท่านข้ามแม่น้ําจอร์แดนไปแล้ว บนภูเขาเอบาลท่านจงตั้งศิลาเหล่านี้ตามเรื่องที่ข้าพเจ้าบัญชาท่านในวันนี้ แล้วจงโบกเสียด้วยปูน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 5, 'และท่านจงสร้างแท่นบูชาแด่พระเยโฮวาห์พระเจ้าของท่านที่นั่น เป็นแท่นศิลา อย่าใช้เครื่องมือเหล็กสกัดศิลานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 6, 'ท่านจงสร้างแท่นบูชาแด่พระเยโฮวาห์พระเจ้าของท่านด้วยศิลาที่ไม่ต้องตกแต่ง และท่านจงถวายเครื่องเผาบูชาบนแท่นนั้นแด่พระเยโฮวาห์พระเจ้าของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 7, 'และท่านจงถวายสันติบูชา และรับประทานเสียที่นั่น และท่านจงปีติร่าเริงต่อพระพักตร์พระเยโฮวาห์พระเจ้าของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 8, 'และท่านจงจารึกบรรดาถ้อยคําของพระราชบัญญัตินี้บนศิลานั้นอย่างชัดเจน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 9, 'โมเสสและปุโรหิตคนเลวีได้กล่าวแก่คนอิสราเอลทั้งหลายว่า “โอ อิสราเอล จงเงียบและสดับตรับฟัง วันนี้ท่านทั้งหลายได้เป็นประชาชนของพระเยโฮวาห์พระเจ้าของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 10, 'เพราะฉะนั้นท่านจงเชื่อฟังพระสุรเสียงของพระเยโฮวาห์พระเจ้าของท่าน คือรักษาพระบัญญัติและกฎเกณฑ์ของพระองค์ ซึ่งข้าพเจ้าบัญชาท่านไว้ในวันนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 11, 'ในวันเดียวกันนั้นโมเสสได้กําชับประชาชนว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 12, '“เมื่อท่านทั้งหลายยกข้ามแม่น้ําจอร์แดนนั้นแล้ว ให้คนต่อไปนี้ยืนบนภูเขาเกริซิมกล่าวคําอวยพรแก่ประชาชน คือสิเมโอน เลวี ยูดาห์ อิสสาคาร์ โยเซฟและเบนยามิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 13, 'และให้คนต่อไปนี้ยืนแช่งอยู่บนภูเขาเอบาล คือรูเบน กาด อาเชอร์ เศบูลุน ดานและนัฟทาลี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 14, 'และให้คนเลวีกล่าวประกาศแก่คนอิสราเอลทั้งปวงด้วยเสียงดังว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 15, '‘ผู้ที่กระทํารูปเคารพเป็นรูปสลักหรือรูปหล่อ ซึ่งเป็นสิ่งที่น่าสะอิดสะเอียนต่อพระเยโฮวาห์ เป็นสิ่งที่ทําด้วยฝีมือช่าง และตั้งไว้ในที่ลับก็ให้ผู้นั้นถูกสาปแช่ง’ ให้ประชาชนทั้งปวงตอบและกล่าวว่า ‘เอเมน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 16, '‘ผู้ใดหมิ่นประมาทบิดาของตนหรือมารดาของตน ให้ผู้นั้นถูกสาปแช่ง’ ให้ประชาชนทั้งปวงกล่าวว่า ‘เอเมน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 17, '‘ผู้ใดที่ยักย้ายเสาเขตของเพื่อนบ้าน ให้ผู้นั้นถูกสาปแช่ง’ ให้ประชาชนทั้งปวงกล่าวว่า ‘เอเมน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 18, '‘ผู้ใดทําให้คนตาบอดหลงทาง ให้ผู้นั้นถูกสาปแช่ง’ ให้ประชาชนทั้งปวงกล่าวว่า ‘เอเมน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 19, '‘ผู้ใดทําให้เสียความยุติธรรมอันควรได้แก่คนต่างด้าว ลูกกําพร้าพ่อและหญิงม่าย ให้ผู้นั้นถูกสาปแช่ง’ ให้ประชาชนทั้งปวงกล่าวว่า ‘เอเมน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 20, '‘ผู้ใดร่วมหลับนอนกับภรรยาของบิดาตน เพราะเขาได้เปิดผ้าของนางผู้เป็นของบิดา ให้ผู้นั้นถูกสาปแช่ง’ ให้ประชาชนทั้งปวงกล่าวว่า ‘เอเมน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 21, '‘ผู้ใดสมสู่กับสัตว์เดียรัจฉานชนิดใดๆก็ตาม ให้ผู้นั้นถูกสาปแช่ง’ ให้ประชาชนทั้งปวงกล่าวว่า ‘เอเมน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 22, '‘ผู้ใดที่ร่วมหลับนอนกับพี่สาวหรือน้องสาว จะเป็นบุตรสาวของบิดา หรือบุตรสาวของมารดาของตนก็ตาม ให้ผู้นั้นถูกสาปแช่ง’ ให้ประชาชนทั้งปวงกล่าวว่า ‘เอเมน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 23, '‘ผู้ใดร่วมหลับนอนกับแม่ยายของตน ให้ผู้นั้นถูกสาปแช่ง’ ให้ประชาชนทั้งปวงกล่าวว่า ‘เอเมน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 24, '‘ผู้ใดฆ่าเพื่อนบ้านของตนอย่างลับๆ ให้ผู้นั้นถูกสาปแช่ง’ ให้ประชาชนทั้งปวงกล่าวว่า ‘เอเมน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 25, '‘ผู้ใดรับสินบนให้ฆ่าบุคคลที่มิได้กระทําผิด ให้ผู้นั้นถูกสาปแช่ง’ ให้ประชาชนทั้งปวงกล่าวว่า ‘เอเมน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 26, '‘ผู้ใดไม่ดํารงบรรดาถ้อยคําแห่งพระราชบัญญัตินี้โดยการกระทําตาม ให้ผู้นั้นถูกสาปแช่ง’ ให้ประชาชนทั้งปวงกล่าวว่า ‘เอเมน’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 1, '“ต่อมาถ้าท่านทั้งหลายเชื่อฟังพระสุรเสียงของพระเยโฮวาห์พระเจ้าของท่าน และระวังที่จะกระทําตามบรรดาพระบัญญัติของพระองค์ซึ่งข้าพเจ้าบัญชาท่านในวันนี้ พระเยโฮวาห์พระเจ้าของท่านจะทรงตั้งท่านไว้ให้สูงกว่าบรรดาประชาชาติทั้งหลายทั่วโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 2, 'บรรดาพระพรเหล่านี้จะตามมาทันท่าน ถ้าท่านทั้งหลายเชื่อฟังพระสุรเสียงของพระเยโฮวาห์พระเจ้าของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 3, 'ท่านทั้งหลายจะรับพระพรในเมือง ท่านทั้งหลายจะรับพระพรในทุ่งนา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 4, 'ผลแห่งตัวของท่าน ผลแห่งพื้นดินของท่านและผลแห่งสัตว์ของท่านจะรับพระพร คือฝูงวัวของท่านที่เพิ่มขึ้น ฝูงแกะของท่านที่เพิ่มลูกขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 5, 'กระจาดของท่าน และรางนวดแป้งของท่านจะรับพระพร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 6, 'ท่านจะรับพระพรเมื่อท่านเข้ามา และท่านจะรับพระพรเมื่อท่านออกไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 7, 'พระเยโฮวาห์จะทรงกระทําให้ศัตรูผู้ลุกขึ้นต่อสู้ท่านพ่ายแพ้ต่อหน้าท่าน เขาจะออกมาต่อสู้ท่านทางหนึ่ง และหนีให้พ้นหน้าท่านเจ็ดทาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 8, 'พระเยโฮวาห์จะทรงบัญชาพระพรให้แก่ยุ้งฉางของท่าน และบรรดากิจการที่มือท่านกระทํา และพระองค์จะทรงอํานวยพระพรแก่ท่านในแผ่นดินซึ่งพระเยโฮวาห์พระเจ้าของท่านประทานแก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 9, 'พระเยโฮวาห์จะทรงตั้งท่านให้เป็นชนชาติบริสุทธิ์แด่พระองค์ ดังที่พระองค์ทรงปฏิญาณแก่ท่านแล้ว ถ้าท่านรักษาพระบัญญัติของพระเยโฮวาห์พระเจ้าของท่าน และดําเนินในพระมรรคาของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 10, 'และชนชาติทั้งหลายในโลกจะเห็นว่าเขาเรียกท่านตามพระนามพระเยโฮวาห์ และเขาทั้งหลายจะเกรงกลัวท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 11, 'พระเยโฮวาห์จะทรงกระทําให้ท่านทั้งหลายอุดมสมบูรณ์ไปด้วยผลแห่งตัวของท่าน ผลของฝูงสัตว์ของท่าน และผลแห่งพื้นดินของท่าน ในแผ่นดินซึ่งพระเยโฮวาห์ทรงปฏิญาณแก่บรรพบุรุษว่าจะให้ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 12, 'พระเยโฮวาห์จะทรงเปิดคลังฟ้าอันดีของพระองค์ ประทานฝนแก่แผ่นดินของท่านตามฤดูกาล และทรงอํานวยพระพรแก่กิจการน้ํามือของท่าน และท่านจะให้ประชาชาติหลายประชาชาติขอยืม แต่ท่านจะไม่ขอยืมเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 13, 'ถ้าท่านเชื่อฟังพระบัญญัติของพระเยโฮวาห์พระเจ้าของท่าน ซึ่งข้าพเจ้าบัญชาท่านในวันนี้ และระวังที่จะกระทําตาม พระเยโฮวาห์จะทรงกระทําให้ท่านเป็นหัว ไม่ใช่เป็นหาง กระทําให้สูงขึ้นทางเดียว มิใช่ให้ต่ําลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 14, 'และท่านจะไม่หันเหไปจากถ้อยคําซึ่งข้าพเจ้าบัญชาท่านในวันนี้ โดยหันไปทางขวามือหรือทางซ้าย ไปติดตามปรนนิบัติพระอื่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 15, 'แต่ต่อมาถ้าท่านไม่เชื่อฟังพระสุรเสียงของพระเยโฮวาห์พระเจ้าของท่าน และไม่ระวังที่จะกระทําตามพระบัญญัติและกฎเกณฑ์ทั้งสิ้นของพระองค์ ซึ่งข้าพเจ้าบัญชาท่านในวันนี้ แล้วบรรดาคําสาปแช่งเหล่านี้จะตามมาทันท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 16, 'ท่านทั้งหลายจะรับคําสาปแช่งในเมือง ท่านทั้งหลายจะรับคําสาปแช่งในทุ่งนา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 17, 'กระจาดของท่านและรางนวดแป้งของท่านจะรับคําสาปแช่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 18, 'ผลแห่งตัวของท่าน ผลแห่งพื้นดินของท่าน ฝูงวัวของท่านที่เพิ่มขึ้น ฝูงแกะของท่านที่เพิ่มจะรับคําสาปแช่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 19, 'ท่านจะรับคําสาปแช่งเมื่อท่านเข้ามา และท่านจะรับคําสาปแช่งเมื่อท่านออกไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 20, 'พระเยโฮวาห์จะทรงบันดาลให้คําสาปแช่ง ความวุ่นวาย และการตําหนิมีขึ้นแก่บรรดากิจการที่มือท่านกระทําจนท่านจะถูกทําลายและพินาศอย่างรวดเร็ว เนื่องด้วยความชั่วซึ่งท่านได้กระทําเพราะท่านได้ทอดทิ้งเราเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 21, 'พระเยโฮวาห์จะทรงบันดาลให้โรคร้ายติดพันท่าน จนพระองค์จะทรงเผาผลาญท่านให้สิ้นเสียจากแผ่นดิน ซึ่งท่านเข้าไปยึดครองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 22, 'พระเยโฮวาห์จะทรงเฆี่ยนตีท่านด้วยความซูบผอม และด้วยความไข้ ความอักเสบ ความร้อนอย่างรุนแรง ด้วยดาบ ด้วยพายุร้อนกล้า ด้วยราขึ้น และสิ่งเหล่านี้จะติดตามท่านไปจนท่านพินาศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 23, 'และฟ้าสวรรค์ที่อยู่เหนือศีรษะของท่านจะเป็นทองเหลือง และแผ่นดินที่อยู่ใต้ท่านจะเป็นเหล็ก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 24, 'พระเยโฮวาห์จะทรงบันดาลให้ฝนในแผ่นดินของท่านเป็นฝุ่นและละออง ลงมาจากอากาศอยู่เหนือท่านทั้งหลายจนกว่าท่านจะถูกทําลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 25, 'พระเยโฮวาห์จะทรงกระทําให้ท่านพ่ายแพ้ต่อหน้าศัตรูของท่าน ท่านจะออกไปต่อสู้เขาทางเดียว แต่จะหนีให้พ้นหน้าเขาเจ็ดทาง และท่านทั้งหลายจะถูกถอนออกไปอยู่ตามบรรดาราชอาณาจักรทั่วโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 26, 'ซากศพของท่านทั้งหลายจะเป็นอาหารของนกทั้งหลายในอากาศ และสําหรับสัตว์ป่าในโลก และไม่มีผู้ใดขับไล่ฝูงสัตว์เหล่านั้นไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 27, 'พระเยโฮวาห์จะทรงเฆี่ยนตีท่านด้วยฝีอียิปต์ ด้วยริดสีดวงทวารขั้นรุนแรง ด้วยโรคลักปิดลักเปิด และด้วยโรคคัน ซึ่งจะรักษาไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 28, 'พระเยโฮวาห์จะทรงเฆี่ยนตีท่านด้วยโรควิกลจริต โรคตาบอด และให้จิตใจยุ่งเหยิง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 29, 'ท่านจะต้องคลําไปในเวลาเที่ยง เหมือนคนตาบอดคลําไปในความมืด และท่านจะไม่มีความเจริญในหนทางของท่าน ท่านจะถูกบีบคั้นและถูกปล้นอยู่เสมอ และจะไม่มีใครช่วยท่านได้เลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 30, 'ท่านจะหมั้นหญิงคนหนึ่งไว้เป็นภรรยา และชายอื่นจะเข้าไปร่วมหลับนอนกับนาง ท่านจะก่อสร้างเรือน แต่จะไม่ได้อาศัยอยู่ในนั้น ท่านจะปลูกสวนองุ่น แต่ท่านจะไม่ได้เก็บผลองุ่นนั้นเข้ามา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 31, 'คนจะฆ่าวัวของท่านต่อหน้าต่อตาท่าน ท่านจะมิได้รับประทานเนื้อวัวนั้น เขาจะมาแย่งชิงลาไปต่อหน้าต่อตาท่าน และเขาจะไม่เอากลับคืนมาให้ท่าน ฝูงแพะแกะของท่านจะต้องเอาไปให้ศัตรูของท่าน และจะไม่มีใครช่วยท่านได้เลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 32, 'เขาจะเอาบุตรชายและบุตรสาวของท่านไปให้แก่ประชาชาติอื่น ส่วนตาของท่านจะมองดูและมืดมัวลงด้วยความอาลัยอาวรณ์ตลอดเวลา อํานาจน้ํามือของท่านก็ไม่สามารถจะป้องกันได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 33, 'ชนชาติที่ท่านไม่เคยรู้จักมาแต่ก่อนจะมารับประทานพืชผลแห่งแผ่นดินของท่าน และกินผลงานทั้งปวงของท่าน เขาจะบีบคั้นและเหยียบย่ําท่านเสมอไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 34, 'ดังนั้นภาพที่ท่านเห็นจึงจะกระทําให้ท่านบ้าคลั่งไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 35, 'พระเยโฮวาห์จะทรงเฆี่ยนตีท่านด้วยฝีร้ายที่หัวเข่า และที่ขา ซึ่งท่านจะรักษาให้หายไม่ได้ เป็นตั้งแต่ฝ่าเท้าจนถึงกระหม่อมของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 36, 'พระเยโฮวาห์จะทรงนําท่าน และกษัตริย์ผู้ที่ท่านแต่งตั้งไว้เหนือท่านนั้น ไปยังประชาชาติซึ่งท่านและบรรพบุรุษของท่านไม่รู้จักมาก่อน ณ ที่นั้นท่านจะปรนนิบัติพระอื่นที่ทําด้วยไม้และด้วยหิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 37, 'ท่านจะเป็นที่น่าตกตะลึง เป็นคําภาษิต เป็นที่ครหาท่ามกลางชนชาติทั้งปวงที่พระเยโฮวาห์ทรงนําท่านไปนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 38, 'ท่านจะต้องเอาพืชไปหว่านไว้ในนามากและเก็บผลเข้ามาแต่น้อย เพราะตั๊กแตนจะกัดกินเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 39, 'ท่านจะปลูกและแต่งต้นองุ่น แต่ท่านจะไม่ได้ดื่มน้ําองุ่นหรือเก็บผลเข้ามา เพราะตัวหนอนจะกินมันเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 40, 'ท่านจะมีต้นมะกอกเทศอยู่ทั่วอาณาเขตของท่าน แต่ท่านจะไม่ได้น้ํามันมาชโลมตัวท่าน เพราะว่าผลมะกอกเทศของท่านจะร่วงหล่นเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 41, 'ท่านจะให้กําเนิดบุตรชายและบุตรสาว แต่จะไม่เป็นของท่าน เพราะเขาจะตกไปเป็นเชลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 42, 'ต้นไม้ทั้งหลายของท่านและผลจากพื้นดินของท่านนั้น ตั๊กแตนจะถือกรรมสิทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 43, 'คนต่างด้าวซึ่งอยู่ท่ามกลางท่าน จะสูงขึ้นไปเหนือท่านทุกทีๆ และท่านจะต่ําลงทุกทีๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 44, 'เขาจะให้ท่านทั้งหลายยืมของของเขาได้ และท่านจะไม่มีให้เขายืม เขาจะเป็นหัว และท่านจะเป็นหาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 45, 'ยิ่งกว่านั้นคําสาปแช่งทั้งหมดนี้จะตามหาท่าน และตามทันท่านจนกว่าท่านจะถูกทําลาย เพราะว่าท่านไม่เชื่อฟังพระสุรเสียงของพระเยโฮวาห์พระเจ้าของท่าน ที่จะรักษาพระบัญญัติและกฎเกณฑ์ของพระองค์ซึ่งพระองค์บัญชาท่านไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 46, 'สิ่งเหล่านี้จะเป็นหมายสําคัญและการมหัศจรรย์อยู่เหนือท่าน และเหนือเชื้อสายของท่านเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 47, 'เพราะท่านมิได้ปรนนิบัติพระเยโฮวาห์พระเจ้าของท่านด้วยความร่าเริงและใจยินดี เพราะเหตุมีสิ่งสารพัดบริบูรณ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 48, 'เพราะฉะนั้นท่านจึงต้องปรนนิบัติศัตรูของท่าน ซึ่งพระเยโฮวาห์จะทรงใช้มาต่อสู้ท่าน ด้วยความหิวและกระหาย เปลือยกายและขัดสนทุกอย่าง และพระองค์จะทรงวางแอกเหล็กบนคอของท่าน จนกว่าพระองค์จะทําลายท่านเสียสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 49, 'พระเยโฮวาห์จะทรงนําประชาชาติหนึ่งมาต่อสู้กับท่านจากทางไกล จากที่สุดปลายแผ่นดินโลก เร็วเหมือนนกอินทรีบินมา เป็นประชาชาติที่ท่านไม่รู้จักภาษาของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 50, 'เป็นประชาชาติที่มีหน้าตาดุร้าย คือผู้ซึ่งไม่เคารพคนแก่ และไม่โปรดปรานคนหนุ่มสาว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 51, 'และจะรับประทานผลของฝูงสัตว์ของท่าน และพืชผลจากพื้นดินของท่าน จนท่านจะถูกทําลาย ทั้งเขาจะไม่เหลือข้าว น้ําองุ่นหรือน้ํามัน ลูกวัว หรือลูกแกะอ่อนไว้ให้ท่าน จนกว่าเขาจะกระทําให้ท่านพินาศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 52, 'เขาจะล้อมท่านไว้ทุกประตูเมืองจนกําแพงสูงและเข้มแข็งซึ่งท่านไว้วางใจนั้นพังทลายลงทั่วแผ่นดินของท่าน คือเขาจะล้อมท่านไว้ทุกประตูเมืองทั่วแผ่นดินของท่านซึ่งพระเยโฮวาห์พระเจ้าของท่านประทานแก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 53, 'ท่านจะต้องรับประทานผลแห่งตัวของท่านเป็นอาหาร คือเนื้อบุตรชายและบุตรสาวของท่าน ผู้ซึ่งพระเยโฮวาห์พระเจ้าของท่านประทานแก่ท่าน ในการล้อมและในความทุกข์ลําบากซึ่งศัตรูของท่านมาทําให้ท่านทั้งหลายทุกข์ลําบากนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 54, 'ผู้ชายสํารวยและสําอางเหลือเกินในหมู่พวกท่านทั้งหลาย ตาเขาจะชั่วร้ายต่อพี่น้องของตน ต่อภรรยาที่อยู่ในอ้อมอกของตนและต่อลูกๆคนสุดท้ายที่เหลืออยู่กับตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 55, 'จนเขาจะไม่ยอมให้ใครกินเนื้อลูกของตนซึ่งกําลังกินอยู่ เพราะไม่มีอะไรเหลือให้เขาอีกแล้วในการล้อมและในความทุกข์ลําบาก ซึ่งศัตรูของท่านมาทําให้ท่านทั้งหลายทุกข์ลําบากทุกประตูเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 56, 'ผู้หญิงสํารวยและสําอางเหลือเกินในหมู่พวกท่าน ซึ่งไม่เคยย่างเท้าลงที่พื้นดินเพราะเป็นคนสําอางและสํารวยอย่างนั้น ตาเขาจะชั่วร้ายต่อสามีในอ้อมอกของเธอ และต่อบุตรชายและบุตรสาวของเธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 57, 'ต่อรกซึ่งเพิ่งออกมาจากหว่างขาของเธอ และต่อลูกแดงที่เพิ่งคลอด เพราะว่าเธอจะกินเป็นอาหารเงียบๆเพราะขัดสนทุกอย่าง ในการถูกล้อมและในความทุกข์ลําบาก ซึ่งศัตรูของท่านมาทําให้ท่านทั้งหลายทุกข์ลําบากทุกประตูเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 58, 'ถ้าท่านทั้งหลายไม่ระวังที่จะกระทําตามถ้อยคําทั้งสิ้นของพระราชบัญญัติซึ่งเขียนไว้ในหนังสือม้วนนี้ ที่จะให้ยําเกรงพระนามที่ทรงสง่าราศีและที่น่าสะพรึงกลัวนี้ คือพระนามพระเยโฮวาห์พระเจ้าของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 59, 'แล้วพระเยโฮวาห์จะทรงนํามาสู่ท่านและเชื้อสายของท่านด้วยภัยพิบัติอย่างผิดธรรมดา ภัยพิบัติร้ายแรงและช้านาน และความเจ็บไข้ต่างๆที่ร้ายแรงและช้านาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 60, 'ยิ่งกว่านั้นพระองค์จะทรงนําโรคทั้งหลายแห่งอียิปต์ ซึ่งท่านกลัวนั้นมาสู่ท่าน และมันจะติดพันท่านอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 61, 'เช่นเดียวกันโรคทุกอย่างและภัยพิบัติทุกอย่าง ซึ่งมิได้ระบุไว้ในหนังสือพระราชบัญญัตินี้ พระเยโฮวาห์จะทรงนํามายังท่าน จนกว่าท่านทั้งหลายจะถูกทําลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 62, 'ซึ่งพวกท่านทั้งหลายมีมากอย่างดวงดาวในท้องฟ้านั้น ท่านก็จะเหลือแต่จํานวนน้อย เพราะว่าท่านไม่เชื่อฟังพระสุรเสียงของพระเยโฮวาห์พระเจ้าของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 63, 'และต่อมาซึ่งพระเยโฮวาห์พอพระทัยที่จะทรงกระทําดีต่อท่านและอํานวยพระพรให้ท่านทวีมากขึ้นนั้น พระเยโฮวาห์ก็จะทรงพอพระทัยที่จะทรงทําให้ท่านพินาศและทําลายท่านเสียเช่นเดียวกัน ท่านจะต้องถูกเด็ดทิ้งไปเสียจากแผ่นดินซึ่งท่านกําลังจะเข้าไปยึดครองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 64, 'และพระเยโฮวาห์จะทรงกระทําให้ท่านทั้งหลายกระจัดกระจายไปท่ามกลางชนชาติทั้งหลาย ตั้งแต่ที่สุดปลายโลกข้างนี้ไปถึงข้างโน้น ณ ที่นั้นท่านจะปรนนิบัติพระอื่นๆ ซึ่งท่านและบรรพบุรุษของท่านไม่รู้จักคือ พระซึ่งทําด้วยไม้และศิลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 65, 'เมื่อท่านอยู่ท่ามกลางประชาชาติต่างๆนั้น ท่านจะไม่พบความสบายเลย ฝ่าเท้าของท่านจะไม่มีที่หยุดพัก เพราะพระเยโฮวาห์จะประทานให้ท่านมีจิตใจที่หวาดหวั่น มีตาที่มืดมัวลงและมีชีวิตที่ค่อยๆวอดลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 66, 'และชีวิตของท่านก็จะแขวนอยู่ข้างหน้าท่านอย่างสงสัย ท่านจะครั่นคร้ามอยู่ทั้งกลางวันและกลางคืน ไม่มีความแน่ใจในชีวิตของท่านเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 67, 'ในเวลาเช้าท่านจะกล่าวว่า ‘ถ้าเป็นเวลาเย็นก็จะดี’ และในเวลาเย็นท่านจะกล่าวว่า ‘ถ้าเป็นเวลาเช้าก็จะดี’ เพราะความครั่นคร้ามซึ่งมีอยู่ในจิตใจท่านนั้น และเพราะสิ่งที่ตาท่านจะเห็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 68, 'และพระเยโฮวาห์จะนําท่านกลับมาทางเรือถึงอียิปต์ เป็นการเดินทางซึ่งข้าพเจ้าได้กล่าวว่า ท่านจะไม่พบเห็นอีกเลย ณ ที่นั่นท่านจะต้องมอบตัวขายให้ศัตรูเป็นทาสชายและทาสหญิง แต่จะไม่มีผู้ใดซื้อท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 1, 'ต่อไปนี้เป็นถ้อยคําในพันธสัญญาซึ่งพระเยโฮวาห์ทรงบัญชาโมเสสให้กระทํากับคนอิสราเอลในแผ่นดินโมอับ นอกเหนือพันธสัญญาซึ่งพระองค์ทรงกระทํากับพวกเขาที่โฮเรบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 2, 'โมเสสเรียกบรรดาคนอิสราเอลมาและกล่าวแก่เขาว่า “ท่านทั้งหลายได้เห็นทุกสิ่งซึ่งพระเยโฮวาห์ทรงกระทําต่อหน้าต่อตาของท่านในแผ่นดินอียิปต์ ต่อฟาโรห์และต่อบรรดาข้าราชบริพารของท่าน และต่อประเทศของท่านทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 3, 'ทั้งการทดลองใหญ่ซึ่งนัยน์ตาของท่านได้เห็น ทั้งหมายสําคัญและการอัศจรรย์ยิ่งใหญ่เหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 4, 'แต่จนกระทั่งวันนี้พระเยโฮวาห์มิได้ประทานจิตใจที่เข้าใจ ตาที่มองเห็นได้ และหูที่ยินได้ให้แก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 5, '‘เราได้นําเจ้าอยู่ในถิ่นทุรกันดารสี่สิบปี เสื้อผ้าของเจ้ามิได้ขาดวิ่นไปจากเจ้า และรองเท้ามิได้ขาดหลุดไปจากเท้าของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 6, 'เจ้าทั้งหลายมิได้รับประทานขนมปัง เจ้ามิได้ดื่มน้ําองุ่นหรือสุรา เพื่อเจ้าจะได้รู้ว่า เราเป็นพระเยโฮวาห์พระเจ้าของเจ้า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 7, 'และเมื่อท่านมาถึงที่นี้ สิโหนกษัตริย์เมืองเฮชโบน และโอกกษัตริย์เมืองบาชาน ออกมาทําสงครามกับเรา แต่เราทั้งหลายก็ได้กระทําให้เขาพ่ายแพ้ไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 8, 'เราริบแผ่นดินของเขาและมอบให้เป็นมรดกแก่คนรูเบน คนกาด และคนครึ่งตระกูลมนัสเสห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 9, 'เพราะฉะนั้นจงระวังที่จะกระทําตามถ้อยคําแห่งพันธสัญญานี้ เพื่อท่านทั้งหลายจะจําเริญในบรรดากิจการซึ่งท่านกระทํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 10, 'ในวันนี้ท่านทั้งหลายทุกคนยืนอยู่ต่อพระพักตร์พระเยโฮวาห์พระเจ้าของท่าน คือบรรดาผู้หัวหน้าตระกูลทั้งหลาย พวกผู้ใหญ่ของท่าน และเจ้าหน้าที่ของท่าน บรรดาผู้ชายของอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 11, 'เด็กๆของท่าน ภรรยาของท่าน และคนต่างด้าวที่อยู่ในค่ายของท่าน ทั้งคนที่ตัดฟืนให้ท่าน และคนที่ตักน้ําให้ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 12, 'เพื่อท่านจะได้เข้ามาในพันธสัญญาแห่งพระเยโฮวาห์พระเจ้าของท่าน คือในพันธสัญญาที่ปฏิญาณไว้ ซึ่งพระเยโฮวาห์พระเจ้าของท่านทรงกระทํากับท่านในวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 13, 'เพื่อพระองค์จะทรงแต่งตั้งท่านทั้งหลายในวันนี้ให้เป็นประชาชนของพระองค์ และเพื่อพระองค์จะเป็นพระเจ้าของท่าน ดังที่พระองค์ทรงตรัสกับท่านนั้น และดังที่พระองค์ทรงปฏิญาณกับบรรพบุรุษของท่าน คือกับอับราฮัม กับอิสอัคและกับยาโคบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 14, 'ข้าพเจ้ามิได้กระทําพันธสัญญากับคําปฏิญาณนี้กับท่านเท่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 15, 'แต่กับผู้ที่ยืนอยู่กับเราทั้งหลายในวันนี้ ต่อพระพักตร์พระเยโฮวาห์พระเจ้าของเรา และกับผู้ที่ไม่ได้อยู่ที่นี่กับเราในวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 16, '(ท่านทราบอยู่แล้วว่า เราอาศัยอยู่ในแผ่นดินอียิปต์อย่างไร และเราทั้งหลายได้ผ่านท่ามกลางประชาชาติ ซึ่งท่านทั้งหลายผ่านพ้นอย่างไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 17, 'ท่านทั้งหลายได้เห็นสิ่งที่น่าสะอิดสะเอียนของเขาทั้งหลายแล้ว คือเห็นรูปเคารพที่ทําด้วยไม้ ด้วยหิน และด้วยเงินและทอง ซึ่งอยู่ท่ามกลางเขาทั้งหลาย)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 18, 'จงระวังให้ดี เกรงว่าจะมีชายหรือหญิงคนใด หรือครอบครัวใด หรือตระกูลใด ซึ่งในวันนี้จิตใจของเขาหันไปจากพระเยโฮวาห์พระเจ้าของเราไปปรนนิบัติพระของประชาชาติเหล่านั้น เกรงว่าท่ามกลางท่านจะมีรากซึ่งเกิดเป็นดีหมีและบอระเพ็ด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 19, 'และต่อมาเมื่อคนนั้นได้ยินถ้อยคําแห่งคําสาปแช่งนี้ จะนึกอวยพรตัวเองในใจว่า ‘แม้ข้าจะเดินด้วยความดื้อดึงตามใจของข้า ข้าก็จะเป็นสุข ไม่ว่าจะเอาการเมาเหล้าซ้อนความกระหายน้ํา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 20, 'พระเยโฮวาห์จะมิได้ทรงให้อภัยแก่คนนั้น แต่พระพิโรธของพระเยโฮวาห์และความหวงแหนของพระองค์จะพลุ่งขึ้นต่อชายคนนั้น และคําสาปแช่งทั้งสิ้นซึ่งเขียนไว้ในหนังสือม้วนนี้จะตกอยู่เหนือเขา และพระเยโฮวาห์จะทรงลบชื่อของเขาเสียจากใต้ฟ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 21, 'แล้วพระเยโฮวาห์จะทรงแยกเขาออกจากตระกูลคนอิสราเอลทั้งปวงให้ประสบหายนะตามคําสาปแช่งทั้งสิ้นของพันธสัญญา ซึ่งจารึกไว้ในหนังสือพระราชบัญญัตินี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 22, 'และคนชั่วอายุต่อมาคือลูกหลานซึ่งเกิดมาภายหลังท่าน และชนต่างด้าวซึ่งมาจากแผ่นดินที่อยู่ห่างไกล จะกล่าวเมื่อเขาเห็นภัยพิบัติต่างๆของแผ่นดินนั้นและโรคภัยซึ่งพระเยโฮวาห์ทรงบันดาลให้เป็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 23, 'คือแผ่นดินทั้งหมดเป็นกํามะถันและเป็นเกลือ และถูกเผาไฟ ไม่มีใครปลูกหว่าน และไม่มีอะไรงอกขึ้น เป็นที่ที่หญ้าไม่งอก เป็นการที่ถูกคว่ําอย่างโสโดมและโกโมราห์ เมืองอัดมาห์ เมืองเศโบยิม ซึ่งพระเยโฮวาห์ทรงคว่ําด้วยความกริ้วและพระพิโรธ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 24, 'เออ ประชาชาติทั้งหลายจะกล่าวว่า ‘ทําไมพระเยโฮวาห์ทรงกระทําเช่นนี้แก่แผ่นดินนี้ พระพิโรธมากมายเช่นนี้หมายความว่ากระไร’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 25, 'แล้วคนจะพูดกันว่า ‘เพราะเขาทอดทิ้งพันธสัญญาของพระเยโฮวาห์พระเจ้าของบรรพบุรุษของเขา ซึ่งพระองค์ทรงกระทําไว้กับเขาเมื่อพระองค์ทรงพาเขาออกจากแผ่นดินอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 26, 'ไปปรนนิบัตินมัสการพระอื่น เป็นพระซึ่งเขาไม่เคยรู้จัก และซึ่งพระองค์มิได้ประทานแก่เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 27, 'เพราะฉะนั้นพระพิโรธของพระเยโฮวาห์จึงพลุ่งขึ้นต่อแผ่นดินนี้ นําเอาบรรดาคําสาปแช่งซึ่งจารึกไว้ในหนังสือนี้มาถึง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 28, 'และพระเยโฮวาห์จึงทรงถอนรากเขาเสียจากแผ่นดินด้วยความกริ้ว พระพิโรธและความเดือดดาลอันมากมาย และทิ้งเขาไปในอีกแผ่นดินหนึ่ง ดังที่เป็นอยู่วันนี้’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 29, 'สิ่งลี้ลับทั้งปวงเป็นของพระเยโฮวาห์พระเจ้าของเราทั้งหลาย แต่สิ่งทรงสําแดงนั้นเป็นของเราทั้งหลาย และของลูกหลานของเราเป็นนิตย์ เพื่อเราจะกระทําตามถ้อยคําทั้งสิ้นของพระราชบัญญัตินี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 1, '“ต่อมาเมื่อบรรดาเหตุการณ์เหล่านี้ คือพระพรและคําสาปแช่งซึ่งข้าพเจ้ากล่าวไว้ต่อหน้าท่านมาถึงท่านทั้งหลายแล้ว และท่านทั้งหลายระลึกขึ้นได้ในเมื่อท่านทั้งหลายอยู่ท่ามกลางบรรดาประชาชาติ ซึ่งพระเยโฮวาห์พระเจ้าของท่านทรงขับไล่ท่านไปนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 2, 'และท่านก็หันกลับมาหาพระเยโฮวาห์พระเจ้าของท่าน ทั้งตัวท่านและลูกหลานของท่าน และเชื่อฟังพระสุรเสียงของพระองค์ในทุกสิ่งทุกอย่างซึ่งข้าพเจ้าได้บัญชาท่านในวันนี้ด้วยสุดจิตสุดใจของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 3, 'แล้วพระเยโฮวาห์พระเจ้าของท่านทั้งหลายจะทรงให้ท่านคืนสู่สภาพเดิมและทรงพระกรุณาต่อท่าน และจะรวบรวมพวกท่านทั้งหลายอีกจากชนชาติทั้งหลายซึ่งพระเยโฮวาห์พระเจ้าของท่านทรงให้ท่านทั้งหลายกระจายไปอยู่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 4, 'ถ้ามีคนของท่านที่ถูกขับไล่ไปอยู่สุดท้ายปลายสวรรค์ จากที่นั่นพระเยโฮวาห์พระเจ้าของท่านจะทรงรวบรวมท่านให้มา จากที่นั่นพระองค์จะทรงนําท่านกลับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 5, 'และพระเยโฮวาห์พระเจ้าของท่านจะนําท่านเข้ามาในแผ่นดิน ซึ่งบรรพบุรุษของท่านยึดครองเพื่อท่านจะได้ยึดครอง และพระองค์จะทรงกระทําดีแก่ท่าน และทวีมากขึ้นยิ่งกว่าบรรพบุรุษของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 6, 'แล้วพระเยโฮวาห์พระเจ้าของท่านจะทรงทําให้ใจของท่าน และใจของเชื้อสายของท่านเข้าสุหนัต เพื่อท่านจะได้รักพระเยโฮวาห์พระเจ้าของท่านด้วยสุดจิตสุดใจของท่าน เพื่อท่านทั้งหลายจะมีชีวิตอยู่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 7, 'และพระเยโฮวาห์พระเจ้าของท่านจะทรงให้คําสาปแช่งเหล่านี้ตกอยู่บนข้าศึกและผู้ที่เกลียดชังท่าน คือผู้ข่มเหงท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 8, 'และท่านทั้งหลายจะเชื่อฟังพระสุรเสียงของพระเยโฮวาห์อีก และกระทําตามพระบัญญัติทั้งสิ้นของพระองค์ ซึ่งข้าพเจ้าบัญชาท่านทั้งหลายในวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 9, 'พระเยโฮวาห์พระเจ้าของท่านจะทรงกระทําให้ท่านจําเริญมั่งคั่งอย่างยิ่งในบรรดากิจการที่มือท่านกระทํา ในผลแห่งตัวของท่าน และในผลแห่งฝูงสัตว์ของท่าน และในผลแห่งพื้นดินของท่าน เพราะพระเยโฮวาห์จะทรงปลื้มปีติที่จะให้ท่านจําเริญมั่งคั่งอีก ดังที่พระองค์ทรงปลื้มปีติในบรรพบุรุษของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 10, 'ถ้าท่านเชื่อฟังพระสุรเสียงแห่งพระเยโฮวาห์พระเจ้าของท่าน โดยรักษาพระบัญญัติและกฎเกณฑ์ของพระองค์ ซึ่งจารึกไว้ในหนังสือของพระราชบัญญัตินี้ ถ้าท่านทั้งหลายหันกลับมาหาพระเยโฮวาห์พระเจ้าของท่านด้วยสุดจิตสุดใจของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 11, 'เพราะว่าพระบัญญัติซึ่งข้าพเจ้าบัญชาท่านในวันนี้ ไม่ได้ปิดบังไว้จากท่าน และไม่ห่างเหินเกินไปด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 12, 'มิใช่พระบัญญัตินั้นอยู่บนสวรรค์แล้วท่านจะกล่าวว่า ‘ใครจะแทนเราขึ้นไปบนสวรรค์และนํามาให้เรา และกระทําให้เราได้ฟังและประพฤติตาม’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 13, 'มิใช่อยู่พ้นทะเล ซึ่งท่านจะกล่าวว่า ‘ใครจะข้ามทะเลไปแทนเราและนํามาให้เรา และกระทําให้เราได้ฟังและประพฤติตาม’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 14, 'แต่ถ้อยคํานั้นอยู่ใกล้ท่านทั้งหลายมาก อยู่ในปากของท่าน และอยู่ในใจของท่าน ฉะนั้นท่านจึงกระทําตามได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 15, 'จงดูเถิด ในวันนี้ข้าพเจ้าได้วางชีวิตและสิ่งดี ความตายและสิ่งร้ายไว้ต่อหน้าท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 16, 'คือในการที่ข้าพเจ้าได้บัญชาท่านในวันนี้ ให้รักพระเยโฮวาห์พระเจ้าของท่าน ให้ดําเนินในพระมรรคาทั้งหลายของพระองค์ และให้รักษาพระบัญญัติและกฎเกณฑ์และคําตัดสินของพระองค์ แล้วท่านจะมีชีวิตอยู่และทวีมากขึ้น และพระเยโฮวาห์พระเจ้าของท่านจะอํานวยพระพรแก่ท่านในแผ่นดินซึ่งท่านเข้าไปยึดครองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 17, 'แต่ถ้าใจของท่านหันเหไป และท่านมิได้ฟัง แต่ถูกลวงให้ไปนมัสการพระอื่นและปรนนิบัติพระนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 18, 'ข้าพเจ้าขอประกาศแก่ท่านทั้งหลายในวันนี้ว่า ท่านทั้งหลายจะพินาศเป็นแน่ ท่านจะไม่มีชีวิตอยู่นานในแผ่นดินซึ่งท่านกําลังจะยกข้ามแม่น้ําจอร์แดนเข้าไปยึดครองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 19, 'ข้าพเจ้าขออัญเชิญสวรรค์และโลกให้เป็นพยานต่อท่านในวันนี้ว่า ข้าพเจ้าตั้งชีวิตและความตาย พระพรและคําสาปแช่งไว้ต่อหน้าท่าน เพราะฉะนั้นท่านจงเลือกเอาข้างชีวิตเพื่อท่านและเชื้อสายของท่านจะได้มีชีวิตอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 20, 'ด้วยมีความรักต่อพระเยโฮวาห์พระเจ้าของท่าน เชื่อฟังพระสุรเสียงของพระองค์ และติดสนิทอยู่กับพระองค์ เพราะพระองค์ทรงเป็นชีวิตและความยืนนานของท่าน เพื่อท่านจะได้อยู่ในแผ่นดินซึ่งพระเยโฮวาห์ปฏิญาณแก่บรรพบุรุษของท่าน คือแก่อับราฮัม แก่อิสอัค และแก่ยาโคบ ว่าจะประทานแก่ท่านเหล่านั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 1, 'โมเสสยังกล่าวถ้อยคําเหล่านี้แก่คนอิสราเอลทุกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 2, 'และท่านกล่าวแก่เขาว่า “วันนี้ข้าพเจ้ามีอายุหนึ่งร้อยยี่สิบปีแล้ว ข้าพเจ้าจะออกไปและเข้ามาอีกไม่ไหวแล้ว พระเยโฮวาห์ตรัสกับข้าพเจ้าว่า ‘เจ้าจะไม่ได้ข้ามแม่น้ําจอร์แดนนี้’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 3, 'พระเยโฮวาห์พระเจ้าของท่านจะข้ามไปข้างหน้าท่านเอง พระองค์จะทรงทําลายประชาชาติเหล่านี้ให้พ้นหน้าท่าน เพื่อว่าท่านจะยึดครองเขานั้น โยชูวาจะข้ามไปนําหน้าท่านทั้งหลาย ดังที่พระเยโฮวาห์ตรัสไว้แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 4, 'พระเยโฮวาห์จะทรงกระทําแก่เขาอย่างที่พระองค์ได้ทรงกระทําแก่สิโหนและโอกกษัตริย์ของคนอาโมไรต์ และแก่แผ่นดินของเขา ผู้ที่พระองค์ทรงทําลายแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 5, 'แล้วพระเยโฮวาห์จะทรงมอบเขาไว้ต่อหน้าท่าน และท่านทั้งหลายจะกระทําแก่เขาตามบัญญัติทั้งสิ้นซึ่งข้าพเจ้าได้บัญชาท่านไว้แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 6, 'จงเข้มแข็งและกล้าหาญเถิด อย่ากลัวหรืออย่าครั่นคร้ามเขาเลย เพราะว่าผู้ที่ไปกับท่านคือพระเยโฮวาห์พระเจ้าของท่าน พระองค์จะไม่ทรงปล่อยท่านให้ล้มเหลวหรือทอดทิ้งท่านเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 7, 'แล้วโมเสสเรียกโยชูวาเข้ามาและกล่าวแก่ท่านท่ามกลางสายตาของบรรดาคนอิสราเอลว่า “จงเข้มแข็งและกล้าหาญเถิด เพราะท่านจะต้องไปกับชนชาตินี้เข้าไปในแผ่นดินซึ่งพระเยโฮวาห์ทรงปฏิญาณแก่บรรพบุรุษว่าจะประทานแก่เขา ท่านจงกระทําให้เขาได้แผ่นดินนั้นมาเป็นมรดก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 8, 'ผู้ที่ไปข้างหน้าคือพระเยโฮวาห์ พระองค์ทรงสถิตอยู่ด้วย พระองค์จะไม่ทรงปล่อยท่านให้ล้มเหลวหรือทอดทิ้งท่านเสีย อย่ากลัวและอย่าขยาดเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 9, 'โมเสสได้เขียนพระราชบัญญัตินี้ และมอบให้แก่ปุโรหิตลูกหลานของเลวี ผู้ซึ่งหามหีบพันธสัญญาของพระเยโฮวาห์ และแก่พวกผู้ใหญ่ทั้งปวงของคนอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 10, 'และโมเสสบัญชาเขาว่า “เมื่อครบทุกๆเจ็ดปี ตามเวลากําหนดปีปลดปล่อย ณ เทศกาลอยู่เพิง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 11, 'เมื่อคนอิสราเอลทั้งหลายมาประชุมพร้อมกันต่อพระพักตร์พระเยโฮวาห์พระเจ้าของท่าน ณ สถานที่ซึ่งพระองค์จะทรงเลือกไว้นั้น ท่านทั้งหลายจงอ่านพระราชบัญญัตินี้ให้คนอิสราเอลทั้งปวงฟัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 12, 'จงเรียกประชาชนให้มาประชุมกัน ทั้งชาย หญิง และเด็ก ทั้งคนต่างด้าวภายในประตูเมืองของท่าน เพื่อให้เขาได้ยินและเรียนรู้ที่จะยําเกรงพระเยโฮวาห์พระเจ้าของท่าน และให้ระวังที่จะกระทําตามถ้อยคําทั้งสิ้นของพระราชบัญญัตินี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 13, 'และเพื่อลูกหลานทั้งหลายของเขา ผู้ยังไม่ทราบจะได้ยินและเรียนรู้ที่จะยําเกรงพระเยโฮวาห์พระเจ้าของท่าน ตราบเท่าเวลาซึ่งท่านอยู่ในแผ่นดิน ซึ่งท่านกําลังจะยกข้ามแม่น้ําจอร์แดนไปยึดครองนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 14, 'และพระเยโฮวาห์ตรัสกับโมเสสว่า “ดูเถิด วันซึ่งเจ้าต้องตายก็ใกล้เข้ามาแล้ว จงเรียกโยชูวามา และเจ้าทั้งสองจงมาเฝ้าเราในพลับพลาแห่งชุมนุม เพื่อเราจะได้กําชับเขา” โมเสสและโยชูวาก็เข้าไปและเข้าเฝ้าพระองค์ในพลับพลาแห่งชุมนุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 15, 'และพระเยโฮวาห์ทรงปรากฏในเสาเมฆในพลับพลาแห่งชุมนุม และเสาเมฆนั้นอยู่ที่ประตูพลับพลาแห่งชุมนุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 16, 'และพระเยโฮวาห์ตรัสกับโมเสสว่า “ดูเถิด ตัวเจ้าจวนจะต้องหลับอยู่กับบรรพบุรุษของเจ้าแล้ว และชนชาตินี้จะลุกขึ้นและเล่นชู้กับพระของคนต่างด้าวแห่งแผ่นดินนี้ ในที่ที่เขาไปอยู่ท่ามกลางนั้น เขาทั้งหลายจะทอดทิ้งเราเสียและหักพันธสัญญาซึ่งเราได้กระทําไว้กับเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 17, 'แล้วในวันนั้นเราจะกริ้วต่อเขา และเราจะทอดทิ้งเขาเสียและซ่อนหน้าของเราเสียจากเขา เขาทั้งหลายจะถูกกลืน และสิ่งร้ายกับความลําบากเป็นอันมากจะมาถึงเขา ในวันนั้นเขาจึงจะกล่าวว่า ‘สิ่งร้ายเหล่านี้ตกแก่เรา เพราะพระเจ้าไม่ทรงสถิตท่ามกลางเราไม่ใช่หรือ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 18, 'ในวันนั้นเราจะซ่อนหน้าของเราเสียจากเขาเป็นแน่ ด้วยเหตุความชั่วทั้งหลายซึ่งเขาได้กระทํา เพราะเขาได้หันไปหาพระอื่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 19, 'เพราะฉะนั้นบัดนี้เจ้าทั้งสองจงเขียนบทเพลงนี้ และสอนคนอิสราเอลให้ร้องจนติดปาก เพื่อบทเพลงนี้จะเป็นพยานของเราปรักปรําคนอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 20, 'เพราะว่าเมื่อเราจะได้นําเขาเข้ามาในแผ่นดินซึ่งมีน้ํานมและน้ําผึ้งไหลบริบูรณ์ ซึ่งเราได้ปฏิญาณแก่บรรพบุรุษของเขา และเขาได้รับประทานอิ่มหนําและอ้วนพี เขาจะหันไปปรนนิบัติพระอื่น และหมิ่นประมาทเรา และผิดพันธสัญญาของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 21, 'และต่อมาเมื่อสิ่งร้ายและความลําบากหลายอย่างมาถึงเขาแล้ว เพลงบทนี้จะเผชิญหน้าเป็นพยาน เพราะว่าเพลงนี้จะอยู่ที่ปากเชื้อสายของเขาไม่มีวันลืม เพราะแม้แต่เวลานี้เองเรารู้ถึงความมุ่งหมายที่เขากําลังจะก่อขึ้นมาแล้ว ก่อนที่เราจะนําเขาเข้าไปในแผ่นดินซึ่งเราปฏิญาณไว้นั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 22, 'โมเสสจึงได้เขียนบทเพลงนี้ในวันเดียวกันนั้น และสอนให้แก่ประชาชนอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 23, 'พระองค์ตรัสสั่งโยชูวาบุตรชายนูนว่า “จงเข้มแข็งและกล้าหาญเถิด เพราะเจ้าจะนําคนอิสราเอลเข้าไปในแผ่นดินซึ่งเราปฏิญาณว่าจะให้แก่เขา เราจะอยู่กับเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 24, 'ต่อมาเมื่อโมเสสเขียนถ้อยคําของพระราชบัญญัตินี้ลงในหนังสือจนจบแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 25, 'โมเสสก็บัญชาคนเลวีผู้หามหีบพันธสัญญาแห่งพระเยโฮวาห์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 26, '“จงรับหนังสือพระราชบัญญัตินี้วางไว้ข้างหีบพันธสัญญาแห่งพระเยโฮวาห์พระเจ้าของท่าน ให้อยู่ที่นั่นเพื่อเป็นพยานปรักปรําท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 27, 'เพราะข้าพเจ้ารู้ว่า ท่านทั้งหลายเป็นคนมักกบฏและคอแข็ง ดูเถิด เมื่อข้าพเจ้ายังมีชีวิตอยู่กับท่านวันนี้ ท่านก็ยังกบฏต่อพระเยโฮวาห์ เมื่อข้าพเจ้าตายแล้วจะร้ายกว่านี้สักเท่าใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 28, 'ท่านจงเรียกประชุมพวกผู้ใหญ่ของทุกตระกูล และเจ้าหน้าที่ทั้งหมด เพื่อข้าพเจ้าจะได้กล่าวถ้อยคําเหล่านี้ให้เขาฟัง และอัญเชิญสวรรค์และโลกให้เป็นพยานปรักปรําเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 29, 'เพราะข้าพเจ้าทราบว่าเมื่อข้าพเจ้าตายแล้ว ท่านจะประพฤติตัวเสื่อมทรามอย่างที่สุด และหันเหไปจากทางซึ่งข้าพเจ้าได้บัญชาท่านไว้ ความชั่วร้ายจะตกแก่ท่านในวันข้างหน้า เพราะว่าท่านจะกระทําสิ่งที่ชั่วร้ายในสายพระเนตรของพระเยโฮวาห์ ซึ่งเป็นการยั่วยุให้พระองค์ทรงกริ้วโกรธด้วยการที่มือท่านกระทํา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 30, 'โมเสสก็ได้กล่าวถ้อยคําในบทเพลงต่อไปนี้ให้เข้าหูประชุมชนอิสราเอลทั้งหมดจนจบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 1, '“โอ ฟ้าสวรรค์ จงเงี่ยหูฟัง ข้าพเจ้าจะพูด โอ พิภพโลก ขอจงสดับถ้อยคําจากปากของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 2, 'ขอให้คําสอนของข้าพเจ้าหยดลงอย่างเม็ดฝน และคําปราศรัยของข้าพเจ้ากลั่นตัวลงอย่างน้ําค้าง อย่างฝนตกปรอยๆอยู่เหนือหญ้าอ่อน อย่างห่าฝนตกลงเหนือผักสด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 3, 'เพราะข้าพเจ้าจะประกาศพระนามของพระเยโฮวาห์ จงถวายความยิ่งใหญ่แด่พระเจ้าของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 4, 'พระองค์ทรงเป็นศิลา พระราชกิจของพระองค์ก็สมบูรณ์ พระมรรคาทั้งหลายของพระองค์ก็ยุติธรรม พระเจ้าที่เที่ยงธรรมและปราศจากความชั่วช้า พระองค์ทรงยุติธรรมและเที่ยงตรง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 5, 'เขาทั้งหลายประพฤติชั่วช้าแล้ว ตําหนิของเขาทั้งหลายหาใช่เป็นตําหนิของบุตรของพระองค์ เขาเป็นยุควิปลาสและคดโกง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 6, 'โอ ชนชาติโฉดเขลาและเบาความเอ๋ย ท่านจะตอบสนองพระเยโฮวาห์อย่างนี้ละหรือ พระองค์มิใช่พระบิดา ผู้ทรงไถ่ท่านไว้ดอกหรือ ผู้ทรงสรรค์ท่าน และตั้งท่านไว้แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 7, 'จงระลึกถึงโบราณกาล จงพิจารณาถึงจํานวนปีที่ผ่านมาหลายชั่วอายุคนแล้วนั้น จงถามบิดาของท่าน แล้วเขาจะสําแดงให้ท่านทราบ จงถามพวกผู้ใหญ่ของท่าน แล้วเขาจะบอกท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 8, 'เมื่อผู้สูงสุดประทานมรดกแก่บรรดาประชาชาติ เมื่อพระองค์ทรงแยกลูกหลานของอาดัม พระองค์ทรงกั้นเขตของชนชาติทั้งหลายตามจํานวนคนอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 9, 'เพราะว่าส่วนของพระเยโฮวาห์คือประชาชนของพระองค์ ยาโคบเป็นส่วนมรดกของพระองค์เอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 10, 'พระองค์ทรงพบเขาในแผ่นดินทุรกันดาร ในที่เปลี่ยวเปล่าซึ่งมีแต่เสียงเห่าหอน พระองค์ทรงนําเขาไปทั่ว และทรงสอนเขาอยู่ ทรงรักษาเขาไว้ดังแก้วพระเนตรของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 11, 'เหมือนนกอินทรีที่กวนรังของมัน กระพือปีกอยู่เหนือลูกโต กางปีกออกรองรับลูกไว้ให้เกาะอยู่บนปีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 12, 'พระเยโฮวาห์องค์เดียวก็ทรงนําเขามา ไม่มีพระต่างด้าวองค์ใดอยู่กับเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 13, 'พระองค์ทรงโปรดเขาให้ขี่ไปบนโลกส่วนสูง ให้เขากินพืชผลที่ได้จากนา พระองค์ทรงให้เขาดูดน้ําผึ้งจากศิลา และให้ดื่มน้ํามันจากหินแข็งกล้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 14, 'ให้ได้เนยข้นจากวัว และให้ได้น้ํานมจากแพะแกะ ได้ไขมันจากลูกแกะ และแกะผู้พันธุ์บาชาน และฝูงแพะ กับข้าวสาลีอย่างดีที่สุด และท่านได้ดื่มเลือดขององุ่น คือน้ําองุ่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 15, 'แต่เยชูรูนอ้วนพีขึ้นแล้วก็มีพยศ พอเจ้าอ้วนใหญ่ เนื้อหนานุ่มนิ่ม เขาทอดทิ้งพระเจ้าผู้สร้างเขามา แล้วดูหมิ่นศิลาแห่งความรอดของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 16, 'เขายั่วยุให้พระองค์ทรงอิจฉาด้วยพระต่างด้าว ด้วยสิ่งที่น่าสะอิดสะเอียนทั้งหลายเขาก็ยั่วยุให้พระองค์ทรงกริ้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 17, 'เขาบูชาพวกปีศาจแทนพระเจ้า บูชาพระซึ่งเขาไม่รู้จักมาก่อน บูชาพระใหม่ๆซึ่งเกิดมาเร็วๆนี้ ซึ่งบรรพบุรุษของท่านไม่เกรงกลัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 18, 'ท่านมิได้ใส่ใจในศิลาที่ให้กําเนิดท่านมา ท่านหลงลืมพระเจ้าซึ่งทรงปั้นท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 19, 'พระเยโฮวาห์ทอดพระเนตรและทรงชังเขา เพราะเหตุบุตรชายหญิงของพระองค์ได้ยั่วพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 20, 'และพระองค์ตรัสว่า ‘เราจะซ่อนหน้าของเราเสียจากเขา เราจะคอยดูว่าปลายทางของเขาจะเป็นอย่างไร เพราะเขาเป็นยุคที่ดื้อรั้น เป็นลูกเต้าที่ไม่มีความเชื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 21, 'เขาทําให้เราอิจฉาด้วยสิ่งที่ไม่ใช่พระเจ้า เขาได้ยั่วโทสะเราด้วยความไร้ประโยชน์ของเขา ดังนั้นเราจึงทําให้เขาอิจฉาผู้ที่ไม่ใช่ชนชาติ และจะยั่วโทสะเขาด้วยประชาชาติที่เขลาชาติหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 22, 'เพราะมีไฟก่อขึ้นด้วยเหตุความกริ้วของเรานั้น ไฟก็ไหม้ลุกลามไปจนถึงก้นลึกของนรก เผาแผ่นดินโลกและพืชผลในนั้น และก่อเพลิงติดรากภูเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 23, 'เราจะสุมสิ่งร้ายไว้บนเขาทั้งหลาย และปล่อยลูกธนูของเรามายิงเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 24, 'เขาจะซูบผอมไปเพราะความหิว ความร้อนอันแรงกล้าและการทําลายอันขมขื่นจะเผาผลาญเขาเสีย เราจะส่งฟันสัตว์ร้ายให้มาขบกับพิษของสัตว์เลื้อยคลานในผงคลี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 25, 'ภายนอกจะมีดาบและภายในจะมีความกลัวมาทําลายทั้งชายหนุ่มและหญิงพรหมจารี ทั้งเด็กที่ยังดูดนมและคนที่ผมหงอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 26, 'เราพูดแล้วว่า “เราจะให้เขากระจัดกระจายไปถึงมุมต่างๆ เราจะให้ชื่อของเขาสูญไปจากความทรงจําของมนุษย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 27, 'ถ้าหากว่าเราไม่กลัวความกริ้วโกรธของศัตรู เกรงว่าศัตรูจะประพฤติผิดไป กลัวว่าศัตรูทั้งหลายจะพูดว่า “กําลังมือของเราจะมีชัย พระเยโฮวาห์หาได้ทรงกระทํากิจการทั้งปวงนี้ไม่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 28, 'เพราะว่าเขาทั้งหลายเป็นประชาชาติที่ไม่ยอมฟังคําปรึกษา ในพวกเขาไม่มีความเข้าใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 29, 'โอ ถ้าเขาฉลาดแล้วเขาจะเข้าใจเรื่องนี้และทราบเรื่องสุดท้ายปลายมือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 30, 'คนเดียวจะไล่พันคนอย่างไรได้ สองคนจะทําให้หมื่นคนหนีได้อย่างไร นอกจากศิลาของเขาได้ขายเขาเสียแล้ว และพระเยโฮวาห์ได้ทรงทอดทิ้งเขาเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 31, 'เพราะศิลาของเขาไม่เหมือนศิลาของเรา แม้ศัตรูของเราก็ตัดสินอย่างนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 32, 'เพราะว่าเถาองุ่นของเขามาจากเถาเมืองโสโดม มาจากไร่เมืองโกโมราห์ ผลองุ่นของเขาเป็นดีหมี และองุ่นที่เป็นพวงๆก็ขมขื่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 33, 'น้ําองุ่นของเขาเป็นพิษของมังกร เป็นพิษอํามหิตของงูเห่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 34, 'เรื่องนี้มิได้สะสมไว้กับเราดอกหรือ ประทับตราไว้ในคลังของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 35, 'การแก้แค้นและการตอบสนองเป็นของเรา เท้าของเขาจะลื่นไถลไปตามกําหนดเวลา เพราะว่าวันแห่งหายนะของเขาอยู่ใกล้แค่เอื้อมแล้ว และสิ่งต่างๆที่จะเกิดขึ้นกับเขาก็จะมาโดยพลัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 36, 'เพราะพระเยโฮวาห์จะทรงพิพากษาประชาชนของพระองค์ และทรงเมตตาปรานีต่อผู้รับใช้ของพระองค์ เมื่อทอดพระเนตรกําลังของเขาสิ้นลง ไม่มีใครยังอยู่หรือเหลืออยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 37, 'แล้วพระองค์จะตรัสว่า “พระของเขาอยู่ที่ไหน ศิลาที่เขาพึ่งพานั้นอยู่ที่ไหนเล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 38, 'คือผู้ที่รับประทานไขมันของเครื่องสัตวบูชาของเขา และดื่มน้ําองุ่นที่เป็นเครื่องดื่มบูชาของเขา ให้บรรดาพระเหล่านั้นลุกขึ้นช่วย ให้พระเหล่านั้นเป็นผู้ป้องกันเจ้าซิ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 39, 'จงดูเถิด ตัวเรา คือเรานี่แหละเป็นผู้นั้น นอกจากเราไม่มีพระเจ้าอื่นใด เราฆ่าให้ตาย และเราก็ให้มีชีวิตอยู่ เราทําให้บาดเจ็บ และเราก็รักษาให้หาย ไม่มีผู้ใดจะช่วยให้พ้นมือเราได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 40, 'เพราะเราชูมือขึ้นถึงสวรรค์ และกล่าวว่า ดังที่เราดํารงอยู่เป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 41, 'ถ้าเราลับดาบอันวาววับของเรา และมือของเรายึดการพิพากษาไว้ เราจะแก้แค้นศัตรูของเรา และตอบแทนผู้ที่เกลียดเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 42, 'เราจะให้ลูกธนูของเราเมาโลหิต และดาบของเราจะกินเนื้อหนัง ด้วยโลหิตของผู้ที่ถูกฆ่าและของเชลย ตั้งแต่เริ่มแก้แค้นต่อศัตรู”’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 43, 'โอ ประชาชาติทั้งหลาย จงชื่นชมยินดีกับประชาชนของพระองค์ เพราะพระองค์จะแก้แค้นโลหิตแห่งพวกผู้รับใช้ของพระองค์แล้ว และจะทรงทําการแก้แค้นศัตรูของพระองค์ และจะทรงเมตตาปรานีทั้งแผ่นดินและประชาชนของพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 44, 'โมเสสได้มาเล่าบรรดาถ้อยคําของเพลงบทนี้ให้ประชาชนฟัง ทั้งตัวท่านพร้อมกับโฮเชยาบุตรชายนูน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 45, 'และเมื่อโมเสสเล่าคําเหล่านี้ทั้งหมดแก่บรรดาคนอิสราเอลจบแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 46, 'ท่านก็กล่าวแก่เขาว่า “จงใส่ใจในถ้อยคําทั้งหลายซึ่งข้าพเจ้ากล่าวแก่ท่านในวันนี้ เพื่อท่านจะได้บัญชาแก่ลูกหลานของท่าน เพื่อเขาจะได้ระวังที่จะกระทําตามถ้อยคําแห่งพระราชบัญญัตินี้ทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 47, 'เรื่องนี้ไม่ใช่เรื่องเล็กน้อยสําหรับท่านทั้งหลาย แต่เป็นเรื่องชีวิตของท่านทั้งหลาย และเรื่องนี้จะกระทําให้ท่านทั้งหลายมีชีวิตยืนนานในแผ่นดิน ซึ่งท่านทั้งหลายกําลังจะข้ามแม่น้ําจอร์แดนไปยึดครองนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 48, 'และพระเยโฮวาห์ตรัสกับโมเสสในวันนั้นเองว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 49, '“จงขึ้นไปบนภูเขาอาบาริม ถึงยอดเขาเนโบ ซึ่งอยู่ในแผ่นดินโมอับ ตรงข้ามเมืองเยรีโค และดูแผ่นดินคานาอัน ซึ่งเราให้แก่ประชาชนอิสราเอลเป็นกรรมสิทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 50, 'และสิ้นชีวิตเสียบนภูเขาซึ่งเจ้าขึ้นไปนั้น และถูกรวบไปอยู่กับญาติพี่น้องของเจ้า ดังอาโรนพี่ชายของเจ้าได้สิ้นชีวิตที่ภูเขาโฮร์ และถูกรวบไปอยู่กับประชาชนของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 51, 'เพราะเจ้าทั้งสองได้ละเมิดต่อเราท่ามกลางคนอิสราเอลที่น้ําเมรีบาห์คาเดชในถิ่นทุรกันดารศิน เพราะเจ้ามิได้เคารพเราว่าบริสุทธิ์ในหมู่คนอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 52, 'เพราะเจ้าจะได้เห็นแผ่นดินซึ่งอยู่ต่อหน้าเจ้า แต่เจ้าไม่ได้เข้าไปในแผ่นดินซึ่งเราให้แก่คนอิสราเอล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 1, 'ต่อไปนี้เป็นพรซึ่งโมเสสบุรุษของพระเจ้าได้อวยพรแก่คนอิสราเอลก่อนที่ท่านสิ้นชีวิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 2, 'ท่านกล่าวว่า “พระเยโฮวาห์เสด็จจากซีนาย และทรงรุ่งแจ้งจากเสอีร์มายังเขาทั้งหลาย พระองค์ทรงฉายรังสีจากภูเขาปาราน พระองค์เสด็จพร้อมกับวิสุทธิชนนับหมื่นๆ ที่พระหัตถ์เบื้องขวามีไฟเป็นพระราชบัญญัติแก่เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 3, 'แท้จริง พระองค์ทรงรักประชาชนของพระองค์ บรรดาวิสุทธิชนของพระองค์ก็อยู่ในพระหัตถ์ของพระองค์ และเขาทั้งหลายกราบลงที่พระบาทของพระองค์รับพระดํารัสของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 4, 'โมเสสบัญชาพระราชบัญญัติไว้แก่เรา เป็นกรรมสิทธิ์ของชุมนุมชนยาโคบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 5, 'พระองค์ทรงเป็นกษัตริย์ในเยชูรูน เมื่อหัวหน้าชนชาติชุมนุมกับคนอิสราเอลทุกตระกูล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 6, 'ขอให้รูเบนดํารงชีวิตอยู่ อย่าให้ตาย อย่าให้ผู้คนของเขามีน้อย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 7, 'ท่านกล่าวถึงพรสําหรับยูดาห์ดังนี้ว่า “ข้าแต่พระเยโฮวาห์ ขอทรงสดับเสียงของยูดาห์ ขอทรงนําเขาเข้ากับชนชาติของเขา มือของเขาได้ต่อสู้เพื่อตนเอง และพระองค์ทรงช่วยเขาให้พ้นจากปรปักษ์ของเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 8, 'ท่านกล่าวถึงเลวีว่า “ขอให้ทูมมิมและอูริมของพระองค์อยู่กับผู้บริสุทธิ์ของพระองค์ ผู้ที่พระองค์ทรงทดลองแล้วที่ตําบลมัสสาห์ ผู้ที่พระองค์ได้ต่อสู้แล้วที่น้ําเมรีบาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 9, 'ผู้กล่าวถึงบิดามารดาของเขาว่า ‘ข้าพเจ้ามิได้เห็นเขา’ เขาไม่จําพี่น้องของเขา และไม่รู้จักลูกของตนเอง เพราะว่าเขาปฏิบัติตามพระวจนะของพระองค์ และรักษาพันธสัญญาของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 10, 'เขาทั้งหลายจะสอนคําตัดสินของพระองค์แก่ยาโคบ และสอนพระราชบัญญัติของพระองค์แก่อิสราเอล เขาจะวางเครื่องหอมต่อพระพักตร์พระองค์ และถวายเครื่องเผาบูชาทั้งสิ้นบนแท่นบูชาของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 11, 'ข้าแต่พระเยโฮวาห์ ขอพระองค์ทรงอํานวยพระพรแก่ข้าวของของเขา และโปรดการงานที่มือเขาทํา ขอทรงตีทําลายบั้นเอวแห่งศัตรูของเขา คือผู้ที่เกลียดชังเขา อย่าให้ลุกขึ้นอีกได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 12, 'ท่านกล่าวเรื่องเบนยามินว่า “คนที่พระเยโฮวาห์ทรงรักจะอาศัยอยู่กับพระองค์อย่างปลอดภัย พระเยโฮวาห์จะทรงปกเขาไว้วันยังค่ํา และจะทรงประทับอยู่ระหว่างบ่าของเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 13, 'และท่านกล่าวถึงโยเซฟว่า “ขอให้แผ่นดินของเขาได้รับพระพรจากพระเยโฮวาห์ ให้ได้รับของประเสริฐที่สุดจากฟ้าสวรรค์ ทั้งน้ําค้างและจากบาดาลซึ่งหมอบอยู่ข้างล่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 14, 'ให้ได้รับผลประเสริฐที่สุดของดวงอาทิตย์ และพืชผลประเสริฐที่สุดที่ดวงจันทร์ให้บังเกิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 15, 'พร้อมกับผลอย่างงามที่สุดจากภูเขาดึกดําบรรพ์ และผลประเสริฐที่สุดจากเนินเขาที่อยู่ตลอดกาล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 16, 'และผลประเสริฐที่สุดของพิภพและสิ่งที่อยู่ในนั้น และพระกรุณาคุณของพระองค์ซึ่งประทับที่พุ่มไม้ ขอให้พรเหล่านี้ลงมาเหนือศีรษะของโยเซฟ และเหนือกระหม่อมของผู้ที่ถูกแยกจากพี่น้องของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 17, 'สง่าราศีของเขาเหมือนลูกวัวหัวปีของเขา เขาของเขาเหมือนเขาม้ายูนิคอน และด้วยเขานั้นเขาจะดันชนชาติทั้งหลายออกไปจนสุดปลายพิภพ คนเอฟราอิมนับหมื่นเป็นเช่นนี้ คนมนัสเสห์นับพันก็เหมือนกัน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 18, 'ท่านกล่าวถึงเศบูลุนว่า “เศบูลุนเอ๋ย จงปีติร่าเริงเมื่อท่านออกไป และอิสสาคาร์เอ๋ย จงปีติร่าเริงในเต็นท์ของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 19, 'เขาจะเรียกชนชาติทั้งหลายมาที่ภูเขา และถวายเครื่องสัตวบูชาแห่งความชอบธรรมที่นั่น เพราะเขาจะดูดความอุดมจากทะเลและได้ขุมทรัพย์ที่ซ่อนอยู่ในทราย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 20, 'ท่านกล่าวถึงกาดว่า “สาธุการแด่พระองค์ผู้ทรงขยายกาด กาดหมอบอยู่เหมือนกับสิงโต เขาทึ้งแขนและกระหม่อมบนศีรษะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 21, 'เขาเลือกแผ่นดินส่วนดีที่สุดเป็นของตน เพราะส่วนของผู้ทรงตั้งพระราชบัญญัติได้มีเก็บไว้ที่นั่นแล้ว และเขามาถึงหัวหน้าของชนชาตินี้ เขาได้กระทําตามความเที่ยงธรรมของพระเยโฮวาห์และตามคําตัดสินซึ่งมีต่ออิสราเอล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 22, 'และท่านกล่าวถึงดานว่า “ดานเป็นลูกสิงโตที่กระโดดมาจากเมืองบาชาน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 23, 'และท่านกล่าวถึงนัฟทาลีว่า “โอ นัฟทาลี ผู้อิ่มด้วยพระคุณและหนําด้วยพระพรของพระเยโฮวาห์ จงยึดครองทางตะวันตกและทางใต้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 24, 'และท่านกล่าวถึงอาเชอร์ว่า “ขอให้อาเชอร์ได้รับพระพรคือให้มีบุตรมากมาย ให้เขาเป็นที่โปรดปรานของพี่น้องของเขา และให้เขาจุ่มเท้าเขาลงในน้ํามัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 25, 'รองเท้าของท่านจะเป็นเหล็กและทองเหลือง วันคืนของท่านเป็นอย่างไร ขอให้กําลังของท่านเป็นอย่างนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 26, 'ไม่มีผู้ใดเหมือนพระเจ้าของเยชูรูน พระองค์เสด็จมาทางฟ้าสวรรค์เพื่อช่วยท่าน เสด็จมาเปี่ยมด้วยความโอ่อ่าตระการของพระองค์บนท้องฟ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 27, 'พระเจ้าผู้ดํารงเป็นนิตย์เป็นที่ลี้ภัยของท่าน และพระกรนิรันดร์รับรองท่านอยู่ พระองค์จะทรงผลักศัตรูให้ออกไปพ้นหน้าท่าน และจะตรัสว่า ‘ทําลายเสียเถอะ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 28, 'ดังนั้นแหละ อิสราเอลจึงจะอยู่อย่างปลอดภัยแต่ฝ่ายเดียว น้ําพุแห่งยาโคบจะอยู่ในแผ่นดินที่มีข้าวและน้ําองุ่น เออ ท้องฟ้าของพระองค์จะโปรยน้ําค้างลงมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 29, 'โอ อิสราเอล ท่านทั้งหลายเป็นสุขแท้ๆ ใครเหมือนท่านบ้าง โอ ชนชาติที่รอดมาด้วยพระเยโฮวาห์ทรงช่วย เป็นโล่ช่วยท่าน เป็นดาบแห่งความยอดเยี่ยมของท่าน ท่านจะพบว่าพวกศัตรูเป็นผู้มุสาทั้งสิ้น ท่านจะเหยียบย่ําไปบนปูชนียสถานสูงของเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 1, 'และโมเสสก็ขึ้นไปจากที่ราบโมอับถึงภูเขาเนโบ ถึงยอดเขาปิสกาห์ ซึ่งอยู่ตรงข้ามเมืองเยรีโค และพระเยโฮวาห์ทรงสําแดงให้ท่านเห็นแผ่นดินนั้นทั้งหมด คือกิเลอาดจนถึงดาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 2, 'ทั้งนัฟทาลีทั่วหมด เห็นแผ่นดินเอฟราอิม และมนัสเสห์ ทั่วแผ่นดินยูดาห์ ไกลไปถึงทะเลที่อยู่ไกลออกไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 3, 'ทั้งทางใต้และที่ลุ่มในหุบเขาแห่งเมืองเยรีโค เมืองต้นอินทผลัม ไกลไปจนถึงโศอาร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 4, 'และพระเยโฮวาห์ตรัสกับท่านว่า “นี่คือแผ่นดินซึ่งเราได้ปฏิญาณต่ออับราฮัม ต่ออิสอัค และต่อยาโคบ ว่า ‘เราจะให้แก่เชื้อสายของเจ้า’ เราให้เจ้าเห็นกับตา แต่เจ้าจะไม่ได้เข้าไปในแผ่นดินนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 5, 'เหตุฉะนั้นโมเสสผู้รับใช้ของพระเยโฮวาห์จึงสิ้นชีวิตที่นั่นในแผ่นดินโมอับ ตามพระดํารัสของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 6, 'และพระองค์ทรงฝังท่านไว้ในหุบเขาในแผ่นดินโมอับ ตรงข้ามเบธเปโอร์ จนถึงทุกวันนี้หามีผู้ใดรู้จักที่ฝังศพของท่านไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 7, 'เมื่อโมเสสสิ้นชีวิตนั้นท่านมีอายุหนึ่งร้อยยี่สิบปี นัยน์ตาของท่านมิได้มัวไป หรือกําลังของท่านก็ไม่ถอย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 8, 'และคนอิสราเอลร้องไห้ถึงโมเสสที่ราบโมอับสามสิบวัน แล้ววันที่ร้องไห้ไว้ทุกข์ถึงโมเสสก็สิ้นลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 9, 'โยชูวาบุตรชายนูนมีจิตใจอันประกอบด้วยสติปัญญา เพราะโมเสสได้เอามือของท่านวางบนเขา ดังนั้นประชาชนอิสราเอลจึงเชื่อฟังเขา และได้กระทําดังที่พระเยโฮวาห์ทรงบัญชาโมเสสไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 10, 'ตั้งแต่วันนั้นมาก็ไม่มีผู้พยากรณ์คนใดเกิดขึ้นในอิสราเอลเสมอโมเสส ผู้ซึ่งพระเยโฮวาห์ทรงรู้จักหน้าต่อหน้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 11, 'ไม่มีผู้ใดเสมอเหมือนท่านในเรื่องหมายสําคัญและการมหัศจรรย์ ซึ่งพระเยโฮวาห์ทรงใช้ท่านให้กระทําในแผ่นดินอียิปต์ ต่อฟาโรห์และต่อบรรดาข้าราชบริพารของฟาโรห์ และต่อแผ่นดินของท่านทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 12, 'และในเรื่องอํานาจยิ่งใหญ่และกิจการอันน่าเกรงกลัวและใหญ่โตทั้งสิ้นซึ่งโมเสสกระทําในสายตาของคนอิสราเอลทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 1, 'อยู่มาเมื่อโมเสสผู้รับใช้ของพระเยโฮวาห์สิ้นชีวิตแล้ว พระเยโฮวาห์ตรัสกับโยชูวาบุตรชายนูนผู้รับใช้ของโมเสสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 2, '“โมเสสผู้รับใช้ของเราสิ้นชีวิตแล้ว ฉะนั้นบัดนี้จงลุกขึ้น ยกข้ามแม่น้ําจอร์แดนนี้ ทั้งเจ้าและชนชาตินี้ทั้งหมดไปยังแผ่นดินซึ่งเรายกให้แก่เขาทั้งหลาย คือแก่คนอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 3, 'ทุกๆตําบลถิ่นที่ฝ่าเท้าของเจ้าทั้งหลายจะเหยียบลง เราได้ยกให้แก่เจ้าทั้งหลาย ดังที่เราได้ตรัสไว้กับโมเสส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 4, 'ตั้งแต่ถิ่นทุรกันดารและภูเขาเลบานอนนี้ไกลไปจนถึงแม่น้ําใหญ่ คือแม่น้ํายูเฟรติส แผ่นดินทั้งหมดของคนฮิตไทต์ ถึงทะเลใหญ่ทางทิศตะวันตก จะเป็นอาณาเขตของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 5, 'ไม่มีผู้ใดจะยืนหยัดต่อหน้าเจ้าได้ตลอดชีวิตของเจ้า เราอยู่กับโมเสสมาแล้วฉันใด เราจะอยู่กับเจ้าฉันนั้น เราจะไม่ละเลยหรือละทิ้งเจ้าเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 6, 'จงเข้มแข็งและกล้าหาญเถิด เพราะเจ้าจะกระทําให้ชนชาตินี้แบ่งมรดกในแผ่นดินนั้น ซึ่งเราปฏิญาณไว้กับบรรพบุรุษของเขาทั้งหลายว่าจะยกให้เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 7, 'เพียงแต่จงเข้มแข็งและกล้าหาญยิ่งเถิด ระวังที่จะกระทําตามพระราชบัญญัติทั้งหมดซึ่งโมเสสผู้รับใช้ของเราได้บัญชาเจ้าไว้นั้น อย่าหลีกเลี่ยงจากพระราชบัญญัตินั้นไปทางขวามือหรือทางซ้าย เพื่อว่าเจ้าจะไปในถิ่นฐานใด เจ้าจะได้รับความสําเร็จอย่างดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 8, 'อย่าให้หนังสือพระราชบัญญัตินี้ห่างเหินไปจากปากของเจ้า แต่เจ้าจงไตร่ตรองตามนั้นทั้งกลางวันและกลางคืน เพื่อเจ้าจะได้ระวังที่จะกระทําตามข้อความที่เขียนไว้นั้นทุกประการ แล้วเจ้าจะมีความจําเริญ และเจ้าจะสําเร็จผลเป็นอย่างดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 9, 'เราสั่งเจ้าไว้แล้วมิใช่หรือว่า จงเข้มแข็งและกล้าหาญเถิด อย่าตกใจหรือคร้ามกลัวเลย เพราะว่าเจ้าไปในถิ่นฐานใด พระเยโฮวาห์พระเจ้าของเจ้าทรงสถิตกับเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 10, 'แล้วโยชูวาบัญชาเจ้าหน้าที่ทั้งปวงของประชาชนว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 11, '“จงไปในค่ายสั่งประชาชนว่า จงเตรียมเสบียงอาหารไว้ เพราะว่าภายในสามวันท่านทั้งหลายจะต้องยกข้ามแม่น้ําจอร์แดนนี้ เพื่อเข้าไปยึดครองแผ่นดิน ซึ่งพระเยโฮวาห์พระเจ้าของท่านประทานแก่ท่านให้ยึดครอง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 12, 'แล้วโยชูวาพูดกับคนรูเบน คนกาด และคนตระกูลมนัสเสห์ครึ่งหนึ่งว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 13, '“จงจําคําที่โมเสสผู้รับใช้ของพระเยโฮวาห์บัญชาท่านทั้งหลายไว้ว่า พระเยโฮวาห์พระเจ้าของท่านทั้งหลายจัดที่พักให้ท่าน และประทานแผ่นดินนี้แก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 14, 'จงให้ภรรยาของท่านทั้งหลาย ลูกเล็กของท่าน และฝูงสัตว์ของท่านอยู่ในแผ่นดินซึ่งโมเสสยกให้ที่ฟากแม่น้ําจอร์แดนข้างนี้ แต่ผู้ชายที่ชํานาญศึกทั้งหลายในพวกท่านต้องถืออาวุธข้ามไปเป็นทัพหน้า เพื่อช่วยพี่น้องของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 15, 'จนกว่าพระเยโฮวาห์จะประทานที่พักให้แก่พี่น้องของท่าน ดังที่ประทานแก่ท่าน ทั้งให้เขาได้ยึดครองแผ่นดินซึ่งพระเยโฮวาห์พระเจ้าของท่านประทานแก่เขา แล้วท่านจึงจะกลับไปยังแผ่นดินที่ท่านยึดครองและถือไว้เป็นกรรมสิทธิ์ คือแผ่นดินซึ่งโมเสสผู้รับใช้ของพระเยโฮวาห์ได้ให้แก่พวกท่านฟากแม่น้ําจอร์แดนข้างนี้ทางดวงอาทิตย์ขึ้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 16, 'เขาทั้งหลายจึงตอบโยชูวาว่า “สิ่งสารพัดซึ่งท่านบัญชาแก่พวกเรา เราจะกระทําตาม ท่านจะให้พวกเราไปในที่ใดๆ เราจะไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 17, 'เราเชื่อฟังโมเสสในเรื่องทั้งปวงอย่างไร เราจะเชื่อฟังท่านอย่างนั้น ขอเพียงว่าพระเยโฮวาห์พระเจ้าของท่านทรงสถิตกับท่าน ดังที่พระองค์ได้สถิตกับโมเสสก็แล้วกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 18, 'ผู้ใดที่ขัดขืนคําบัญชาของท่าน และไม่เชื่อฟังถ้อยคําของท่าน ไม่ว่าท่านจะบัญชาเขาอย่างไร ผู้นั้นจะต้องถึงตาย ขอเพียงให้เข้มแข็งและกล้าหาญเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 1, 'ต่อมาโยชูวาบุตรชายนูนได้ใช้ชายสองคนจากเมืองชิทธิมเป็นการลับให้ไปสอดแนม กล่าวว่า “จงไปตรวจดูแผ่นดินนั้น และเมืองเยรีโคด้วย” คนทั้งสองก็ไป เข้าไปในเรือนของหญิงโสเภณีคนหนึ่งชื่อราหับ และพักอยู่ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 2, 'มีคนทูลกษัตริย์เมืองเยรีโคว่า “ดูเถิด มีชายอิสราเอลบางคนเข้ามาคืนนี้ เพื่อจะสอดแนมดูแผ่นดิน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 3, 'ฝ่ายกษัตริย์เมืองเยรีโคจึงใช้คนไปสั่งราหับว่า “จงส่งคนเหล่านั้นซึ่งมาหาเจ้าในบ้านของเจ้าออกมาให้เรา เพราะเขามาเพื่อจะสอดแนมดูทั่วแผ่นดินของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 4, 'แต่หญิงนั้นได้ซ่อนชายทั้งสองเสียแล้วจึงกล่าวว่า “มีผู้ชายมาหาข้าพเจ้าจริง แต่เขามาจากไหนข้าพเจ้าไม่ทราบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 5, 'ต่อมาเมื่อจะปิดประตูเมืองในเวลาพลบค่ํา คนเหล่านั้นก็ออกไปแล้ว เขาไปทางไหนข้าพเจ้าไม่ทราบ จงรีบตามเขาไปเถิด คงทันเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 6, 'แต่หญิงนั้นได้พาคนทั้งสองขึ้นบนหลังคาแล้วซ่อนตัวเขาไว้ใต้ต้นป่านซึ่งวางลําดับตากไว้ที่ดาดฟ้าบนหลังคานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 7, 'เขาทั้งหลายก็ไล่ตามคนทั้งสองไปทางแม่น้ําจอร์แดนจนถึงท่าข้าม พอคนที่ไล่ตามนั้นออกไปแล้วเขาก็ปิดประตูเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 8, 'เมื่อชายทั้งสองคนยังไม่นอนหญิงนั้นก็ขึ้นไปหาเขาบนหลังคา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 9, 'กล่าวแก่ชายนั้นว่า “ดิฉันทราบแล้วว่า พระเยโฮวาห์ประทานแผ่นดินนี้แก่พวกท่าน ความคร้ามกลัวต่อท่านได้ตกอยู่บนเราทั้งหลาย และบรรดาชาวแผ่นดินก็ครั่นคร้ามต่อท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 10, 'เพราะเราทั้งหลายได้ยินเรื่องที่พระเยโฮวาห์ทรงกระทําให้ทะเลแดงแห้งไปต่อหน้าท่านเมื่อท่านออกจากอียิปต์ และเรื่องการที่ท่านได้กระทําแก่กษัตริย์ทั้งสองของคนอาโมไรต์ ซึ่งอยู่ฟากแม่น้ําจอร์แดนข้างโน้น คือกษัตริย์สิโหนและโอก ผู้ซึ่งท่านทั้งหลายได้ทําลายเสียสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 11, 'เพราะเรื่องท่านนี้แหละ พอเราได้ยินข่าวนี้ จิตใจของเราก็ละลายไป ไม่มีความกล้าหาญเหลืออยู่ในสักคนหนึ่งเลย เพราะพระเยโฮวาห์พระเจ้าของท่านเป็นพระเจ้าของสวรรค์เบื้องบนและโลกเบื้องล่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 12, 'ฉะนั้นบัดนี้ขอท่านสาบานให้ดิฉันในพระนามพระเยโฮวาห์ว่า เมื่อดิฉันได้สําแดงความเมตตาต่อท่านแล้ว ท่านจะแสดงความเมตตาต่อเรือนบิดาของดิฉันและให้มีหมายสําคัญอันแน่นอนต่อกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 13, 'และขอไว้ชีวิตบิดามารดา พี่น้องชายหญิง และทุกคนที่เป็นของวงศ์ญาตินี้ ให้ชีวิตเรารอดจากตาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 14, 'ชายนั้นจึงตอบนางว่า “ชีวิตของเราเพื่อชีวิตของเจ้าน่ะหรือ ถ้าเจ้าไม่แพร่งพรายเรื่องของเรานี้แก่ผู้ใด เราจะมีความเมตตาและจริงใจต่อเจ้า เมื่อพระเยโฮวาห์ประทานแผ่นดินนี้แก่เรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 15, 'แล้วนางจึงเอาเชือกหย่อนเขาทั้งสองลงทางหน้าต่าง เพราะบ้านของนางตั้งอยู่ที่กําแพงเมือง นางอาศัยอยู่ในกําแพง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 16, 'นางจึงบอกเขาว่า “จงขึ้นไปบนภูเขา ด้วยเกรงว่าผู้ที่ไล่ตามจะพบเข้า จงซ่อนตัวอยู่สามวันจนกว่าผู้ที่ไล่ตามจะกลับ แล้วจึงค่อยออกเดินต่อไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 17, 'ชายนั้นจึงพูดกับนางว่า “ฝ่ายเราจะไม่ให้ผิดคําสาบานซึ่งเจ้าได้ให้เราสาบานนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 18, 'ดูเถิด เมื่อเรายกเข้ามาในแผ่นดินนี้ เจ้าจงเอาด้ายแดงนี้ผูกไว้ที่หน้าต่างซึ่งเจ้าหย่อนเราลงไปนั้น และเจ้าจงรวบรวมบิดามารดา พี่น้อง และครัวเรือนของบิดาทั้งสิ้นเข้ามาไว้ในบ้าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 19, 'ถ้ามีผู้ใดออกไปที่ถนนนอกประตูบ้าน ให้โลหิตของผู้นั้นตกบนศีรษะของผู้นั้นเอง ฝ่ายเราไม่มีความผิด แต่ถ้ามีคนหนึ่งคนใดยกมือขึ้นทําร้ายผู้ใดที่อยู่กับเจ้าในเรือน ให้โลหิตของคนนั้นตกบนศีรษะของเราเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 20, 'แต่ถ้าเจ้าแพร่งพรายเรื่องของเรานี้แก่ผู้ใด เราก็พ้นจากคําสาบานซึ่งเจ้าให้เราสาบานไว้นั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 21, 'นางจึงกล่าวว่า “ให้เป็นไปตามคําของท่านเถิด” แล้วนางก็ส่งคนทั้งสองนั้นไป เขาก็ไป นางจึงเอาด้ายแดงผูกไว้ที่หน้าต่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 22, 'คนทั้งสองออกไปแล้วปีนขึ้นไปบนภูเขาพักอยู่ที่นั่นสามวัน จนผู้ที่ไล่ตามกลับ เพราะผู้ที่ไล่ตามนั้นได้ค้นหาอยู่ตลอดทางก็ไม่พบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 23, 'ชายทั้งสองก็ลงจากภูเขาอีก และข้ามไปหาโยชูวาบุตรชายนูน แล้วเล่าเหตุการณ์ทั้งสิ้นซึ่งเกิดแก่ตนให้ฟัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 24, 'และเขากล่าวแก่โยชูวาว่า “พระเยโฮวาห์ทรงมอบแผ่นดินนั้นทั้งหมดไว้ในมือเราแน่นอนแล้ว และยิ่งกว่านั้นอีกบรรดาชาวบ้านชาวเมืองในแผ่นดินนี้ ก็มีใจครั่นคร้ามไป เพราะเราเป็นเหตุ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 1, 'ฝ่ายโยชูวาก็ตื่นแต่เช้า เขาทั้งหลายยกออกจากชิทธิมมาถึงแม่น้ําจอร์แดน ทั้งตัวท่านและคนอิสราเอลทั้งหมด เขาพักอยู่ที่นั่นก่อนจะข้ามไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 2, 'ครั้นล่วงมาได้สามวัน พวกเจ้าหน้าที่ก็ไปทั่วค่าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 3, 'แล้วบัญชาประชาชนว่า “เมื่อท่านเห็นหีบพันธสัญญาแห่งพระเยโฮวาห์พระเจ้าของท่าน และเห็นคนเลวีซึ่งเป็นปุโรหิตหามไป ก็ให้ยกออกจากที่ของท่านตามหีบนั้นไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 4, 'ทิ้งระยะของท่านไว้ให้ห่างจากหีบประมาณสองพันศอก อย่าเข้าไปใกล้หีบนั้น เพื่อท่านทั้งหลายจะได้รู้จักทางที่จะไป เพราะท่านยังไม่เคยผ่านทางนี้มาก่อน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 5, 'ฝ่ายโยชูวาจึงกล่าวแก่ประชาชนว่า “จงชําระตัวให้บริสุทธิ์เถิด เพราะว่าพรุ่งนี้พระเยโฮวาห์จะทรงกระทําการมหัศจรรย์ท่ามกลางท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 6, 'โยชูวาสั่งพวกปุโรหิตว่า “จงยกหีบพันธสัญญาข้ามไปข้างหน้าประชาชนทั้งปวง” เขาก็ยกหีบพันธสัญญาเดินไปข้างหน้าประชาชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 7, 'พระเยโฮวาห์ตรัสกับโยชูวาว่า “วันนี้เราจะเริ่มยกย่องเจ้าท่ามกลางสายตาของบรรดาอิสราเอล เพื่อเขาจะทราบว่า เราอยู่กับโมเสสมาแล้วอย่างไร เราจะอยู่กับเจ้าอย่างนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 8, 'และเจ้าจงสั่งปุโรหิตผู้หามหีบพันธสัญญาว่า ‘เมื่อท่านทั้งหลายมาริมแม่น้ําจอร์แดนจงหยุดยืนอยู่ในแม่น้ําจอร์แดน’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 9, 'และโยชูวากล่าวแก่คนอิสราเอลว่า “จงมาที่นี่เถิด และฟังพระดํารัสของพระเยโฮวาห์พระเจ้าของท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 10, 'และโยชูวากล่าวว่า “โดยเหตุนี้ท่านทั้งหลายจะได้ทราบว่า พระเจ้าผู้ทรงพระชนม์ได้ประทับอยู่ท่ามกลางท่านทั้งหลาย และว่าพระองค์จะทรงขับไล่คนคานาอัน คนฮิตไทต์ คนฮีไวต์ คนเปริสซี คนเกอร์กาชี คนอาโมไรต์ และคนเยบุสให้พ้นหน้าท่านทั้งหลายอย่างแน่นอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 11, 'ดูเถิด หีบพันธสัญญาแห่งองค์พระผู้เป็นเจ้าปิ่นสากลพิภพจะข้ามไปข้างหน้าท่านลงไปในแม่น้ําจอร์แดน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 12, 'ฉะนั้นบัดนี้จงเลือกคนสิบสองคนออกจากตระกูลอิสราเอลตระกูลละคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 13, 'และต่อมาทันทีที่เมื่อฝ่าเท้าของปุโรหิตผู้หามหีบแห่งพระเยโฮวาห์องค์พระผู้เป็นเจ้าแห่งแผ่นดินโลกทั้งสิ้น จะลงไปยืนอยู่ในแม่น้ําจอร์แดน น้ําในแม่น้ําจอร์แดนจะถูกตัดขาดจากน้ําที่ไหลมาจากข้างบน น้ํานั้นจะหยุดตั้งขึ้นเป็นกองเดียว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 14, 'ดังนั้นเมื่อประชาชนยกจากเต็นท์ของเขาทั้งหลาย เพื่อจะข้ามแม่น้ําจอร์แดน พร้อมกับปุโรหิตหามหีบพันธสัญญาไปข้างหน้าประชาชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 15, 'เมื่อคนหามหีบมาถึงแม่น้ําจอร์แดนและเท้าของปุโรหิตผู้หามหีบก้าวลงในริมแม่น้ําแล้ว (แม่น้ําจอร์แดนขึ้นท่วมฝั่งตลอดฤดูเกี่ยวข้าวเสมอ)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 16, 'น้ําที่ไหลมาจากข้างบนก็หยุดตั้งขึ้นและนูนขึ้นเป็นกองไกลออกไปยิ่งนักตั้งแต่เมืองอาดัม ซึ่งเป็นเมืองอยู่ข้างๆเมืองศาเรธาน และน้ําที่ไหลลงสู่ทะเลแห่งที่ราบ คือทะเลเค็มนั้นก็ขาดกันสิ้น แล้วประชาชนก็ข้ามไปที่ฝั่งตรงข้ามเมืองเยรีโค');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 17, 'และปุโรหิตผู้หามหีบพันธสัญญาของพระเยโฮวาห์ยืนมั่นอยู่บนดินแห้งกลางแม่น้ําจอร์แดน คนอิสราเอลทั้งหมดก็เดินข้ามไปบนดินแห้ง จนประชาชนข้ามแม่น้ําจอร์แดนไปหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 1, 'ต่อมาเมื่อประชาชนนั้นได้ข้ามแม่น้ําจอร์แดนเสร็จหมดแล้ว พระเยโฮวาห์ตรัสสั่งโยชูวาว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 2, '“จงเลือกชายสิบสองคนจากประชาชนตระกูลละคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 3, 'และบัญชาเขาว่า ‘จงไปเอาศิลาสิบสองก้อนจากที่นี่ที่กลางแม่น้ําจอร์แดน ตรงที่ซึ่งเท้าของปุโรหิตยืนมั่นอยู่นั้น ขนมาวางไว้ในที่ซึ่งท่านทั้งหลายจะนอนในคืนวันนี้’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 4, 'แล้วโยชูวาก็เลือกชายสิบสองคน ซึ่งท่านจัดตั้งจากประชาชนอิสราเอลตระกูลละคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 5, 'โยชูวาจึงสั่งเขาว่า “จงผ่านไปข้างหน้าหีบของพระเยโฮวาห์พระเจ้าของท่านลงไปกลางแม่น้ําจอร์แดน แล้วแบกศิลามาคนละก้อนตามจํานวนตระกูลคนอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 6, 'เพื่อว่าสิ่งนี้จะเป็นหมายสําคัญในหมู่พวกท่านทั้งหลาย ในเมื่อลูกหลานของท่านจะถามบิดาในเวลาต่อไปว่า ‘ศิลาเหล่านี้มีความหมายอะไร’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 7, 'แล้วท่านจงตอบพวกเขาว่า ‘น้ําที่จอร์แดนขาดจากกันต่อหน้าหีบพันธสัญญาแห่งพระเยโฮวาห์ เมื่อหีบนั้นข้ามแม่น้ําจอร์แดน น้ําในแม่น้ําจอร์แดนก็ขาดจากกัน ศิลาเหล่านี้จะเป็นที่รําลึกแก่ลูกหลานอิสราเอลเป็นนิตย์’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 8, 'คนอิสราเอลเหล่านั้นก็กระทําตามที่โยชูวาบัญชา และขนหินสิบสองก้อนมาจากกลางจอร์แดน ตามจํานวนตระกูลคนอิสราเอล ดังที่พระเยโฮวาห์ตรัสสั่งโยชูวา และเขาก็แบกมายังที่ซึ่งเขาพักอยู่ วางไว้ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 9, 'และโยชูวาได้ตั้งศิลาสิบสองก้อนไว้กลางแม่น้ําจอร์แดน ตรงที่ที่เท้าของปุโรหิตผู้หามหีบพันธสัญญายืนอยู่ และศิลาเหล่านั้นก็ยังอยู่จนทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 10, 'เพราะว่าปุโรหิตผู้หามหีบนั้นได้ยืนอยู่ที่กลางจอร์แดนกว่าสิ่งสารพัดจะสําเร็จ ตามซึ่งพระเยโฮวาห์บัญชาโยชูวาให้บอกประชาชน ตามซึ่งโมเสสได้บัญชาไว้กับโยชูวาทุกประการ แล้วประชาชนก็รีบข้ามไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 11, 'ต่อมาเมื่อประชาชนข้ามไปหมดแล้ว หีบแห่งพระเยโฮวาห์และปุโรหิตก็ข้ามไปต่อหน้าประชาชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 12, 'คนรูเบน คนกาด และคนมนัสเสห์ครึ่งตระกูลถืออาวุธนําหน้าคนอิสราเอลข้ามไปตามที่โมเสสได้สั่งเขาไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 13, 'มีคนถืออาวุธไว้พร้อมที่จะเข้าสงครามประมาณสี่หมื่นคนได้ข้ามไปต่อพระพักตร์พระเยโฮวาห์เพื่อทําศึก ไปถึงที่ราบเขตเมืองเยรีโค');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 14, 'ในวันนั้นพระเยโฮวาห์ทรงยกย่องโยชูวาท่ามกลางสายตาของคนอิสราเอลทั้งปวง เขาทั้งหลายก็ยําเกรงท่าน ดังที่เขาเคยยําเกรงโมเสสตลอดชีวิตของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 15, 'พระเยโฮวาห์ตรัสกับโยชูวาว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 16, '“จงบัญชาปุโรหิตผู้หามหีบพระโอวาทให้ขึ้นมาจากจอร์แดน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 17, 'โยชูวาจึงบัญชาแก่ปุโรหิตว่า “จงขึ้นมาจากจอร์แดนเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 18, 'ต่อมาเมื่อปุโรหิตผู้หามหีบพันธสัญญาแห่งพระเยโฮวาห์ขึ้นมาจากกลางจอร์แดน เมื่อฝ่าเท้าของปุโรหิตยกขึ้นเหยียบแผ่นดินแห้ง น้ําในจอร์แดนก็กลับมายังที่เก่าไหลท่วมฝั่งอย่างเดิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 19, 'ประชาชนได้ขึ้นจากจอร์แดนในวันที่สิบเดือนที่หนึ่ง ไปตั้งค่ายอยู่ที่กิลกาล ริมเขตเมืองเยรีโคข้างทิศตะวันออก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 20, 'และศิลาสิบสองก้อนซึ่งเขานําออกมาจากจอร์แดนนั้น โยชูวาก็ได้ตั้งไว้ที่กิลกาล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 21, 'ท่านจึงกล่าวแก่คนอิสราเอลว่า “เวลาภายหน้าเมื่อลูกหลานจะถามบิดาของเขาว่า ‘ศิลาเหล่านี้มีความหมายอะไร’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 22, 'แล้วท่านจงตอบแก่ลูกหลานให้ทราบว่า ‘อิสราเอลได้ข้ามจอร์แดนนี้บนดินแห้ง’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 23, 'เพราะว่าพระเยโฮวาห์พระเจ้าของท่านทั้งหลายกระทําให้แม่น้ําจอร์แดนแห้งไปเพื่อท่าน จนท่านข้ามไปได้หมด ดังที่พระเยโฮวาห์พระเจ้าของท่านกระทําแก่ทะเลแดง ทรงกระทําให้แห้งเพื่อเราทั้งหลาย จนเราข้ามไปหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 24, 'เพื่อชนชาติทั้งหลายทั่วพิภพจะได้ทราบว่าพระหัตถ์พระเยโฮวาห์นั้นทรงฤทธิ์ เพื่อท่านทั้งหลายจะยําเกรงพระเยโฮวาห์พระเจ้าของท่านเป็นนิตย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 1, 'ต่อมาเมื่อบรรดากษัตริย์ของคนอาโมไรต์ซึ่งอยู่ฟากจอร์แดนข้างตะวันตก และบรรดากษัตริย์ของคนคานาอัน ซึ่งอยู่ใกล้ทะเล ได้ยินว่าพระเยโฮวาห์ทรงบันดาลให้น้ําในจอร์แดนแห้งไปต่อหน้าคนอิสราเอล ให้เราข้ามฟากไปได้หมดแล้ว จิตใจของเขาก็ละลายไป ไม่มีกําลังใจในตัวอีกต่อไปเหตุเพราะคนอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 2, 'คราวนั้น พระเยโฮวาห์ตรัสกับโยชูวาว่า “จงทํามีดด้วยหินคมและให้คนอิสราเอลเข้าสุหนัตเป็นครั้งที่สอง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 3, 'โยชูวาจึงทํามีดด้วยหินคมและให้คนอิสราเอลเข้าสุหนัตที่เนินเขาแห่งหนังหุ้มปลายองคชาต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 4, 'นี่แหละเป็นเหตุซึ่งโยชูวาให้เขาเข้าสุหนัต ในบรรดาประชาชนผู้ออกมาจากอียิปต์พวกผู้ชาย คือทหารทั้งหมดสิ้นชีวิตเสียตามทางในถิ่นทุรกันดารหลังจากที่ออกจากอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 5, 'แม้ว่าประชาชนผู้ออกมาเหล่านั้นได้เข้าสุหนัตหมดทุกคนแล้ว แต่ประชาชนทุกคนที่เกิดมาใหม่ตามทางที่ในถิ่นทุรกันดารหลังจากที่ออกมาจากอียิปต์นั้น ยังไม่ได้เข้าสุหนัต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 6, 'เพราะว่าคนอิสราเอลเดินทางสี่สิบปีอยู่ในถิ่นทุรกันดารจนประชาชนทั้งสิ้น คือทหารที่ออกมาจากอียิปต์สิ้นชีวิตเสียหมด เพราะเขามิได้เชื่อฟังพระสุรเสียงของพระเยโฮวาห์ ผู้ซึ่งพระเยโฮวาห์ทรงปฏิญาณกับเขาว่า พระองค์จะไม่ทรงยอมให้เขาเห็นแผ่นดิน ซึ่งพระเยโฮวาห์ได้ปฏิญาณแก่บรรพบุรุษว่าจะประทานแก่เราทั้งหลาย เป็นแผ่นดินที่มีน้ํานมและน้ําผึ้งไหลบริบูรณ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 7, 'แต่บุตรของเขาซึ่งพระองค์ทรงให้แทนเขานั้น โยชูวาก็ได้ให้เข้าสุหนัต เพราะว่าเขายังไม่เข้าสุหนัต เพราะว่าเขาไม่เคยได้เข้าสุหนัตเมื่อมาตามทาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 8, 'ต่อมาเมื่อได้ให้ประชาชนเข้าสุหนัตเสร็จหมดแล้ว เขาก็พักอยู่ในที่อาศัยในค่ายจนกว่าจะหายเป็นปกติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 9, 'พระเยโฮวาห์ตรัสกับโยชูวาว่า “วันนี้เราได้กลิ้งความอดสูเพราะอียิปต์ไปให้พ้นเจ้าแล้ว” จึงเรียกชื่อตําบลนั้นว่ากิลกาลจนทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 10, 'ฝ่ายคนอิสราเอลได้ตั้งค่ายที่กิลกาล เขาถือเทศกาลปัสกาในวันที่สิบสี่ของเดือนนั้นเวลาเย็น ณ ที่ราบเมืองเยรีโค');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 11, 'วันรุ่งขึ้นหลังวันเทศกาลปัสกา วันนั้นเองเขาก็รับประทานผลอันเกิดจากแผ่นดิน คือขนมไร้เชื้อและข้าวคั่ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 12, 'ตั้งแต่วันรุ่งขึ้นมานาก็ขาดไป คือเมื่อเขาได้รับประทานผลจากแผ่นดิน คนอิสราเอลไม่มีมานาอีกเลย ในปีนั้นเขารับประทานผลจากแผ่นดินคานาอัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 13, 'ต่อมาเมื่อโยชูวาอยู่ข้างเมืองเยรีโค ท่านก็เงยหน้าขึ้นมองดู และดูเถิด มีชายคนหนึ่งชักดาบออกมาถือยืนอยู่ตรงหน้าท่าน โยชูวาเข้าไปหาชายนั้น กล่าวแก่เขาว่า “ท่านอยู่ฝ่ายเราหรืออยู่ฝ่ายศัตรู”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 14, 'ผู้นั้นจึงตอบว่า “มิใช่ ที่เรามานี้ก็มาเป็นจอมพลโยธาของพระเยโฮวาห์” ฝ่ายโยชูวาก็กราบลงถึงดินนมัสการแล้วถามว่า “เจ้านายของข้าพเจ้าท่านจะให้ผู้รับใช้ของท่านกระทําอะไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 15, 'และจอมพลโยธาของพระเยโฮวาห์จึงสั่งโยชูวาว่า “จงถอดรองเท้าออกจากเท้าของเจ้าเสีย เพราะว่าที่ซึ่งเจ้ายืนอยู่นี้เป็นที่บริสุทธิ์” โยชูวาก็กระทําตาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 1, 'เพราะเหตุคนอิสราเอลเมืองเยรีโคต้องถูกปิดไว้ ไม่มีคนเข้าออกได้เลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 2, 'พระเยโฮวาห์ตรัสกับโยชูวาว่า “ดูแน่ะ เราได้มอบเมืองเยรีโคไว้ในมือเจ้าแล้ว ทั้งกษัตริย์และทแกล้วทหาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 3, 'เจ้าทั้งหลายจงเดินขบวนรอบเมือง คือให้บรรดาทหารไปรอบเมืองครั้งหนึ่ง เจ้าจงทําเช่นนี้หกวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 4, 'ให้ปุโรหิตเจ็ดคนถือแตรเขาแกะตัวผู้เจ็ดคันนําหน้าหีบ และในวันที่เจ็ดนั้นเจ้าทั้งหลายจงเดินรอบเมืองเจ็ดครั้ง ให้ปุโรหิตเป่าแตรไปด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 5, 'และต่อมาเมื่อเขาเป่าเขาแกะตัวผู้เป็นเสียงยาว พอเจ้าได้ยินเสียงแตรนั้น ก็ให้ประชาชนทั้งปวงโห่ร้องขึ้นด้วยเสียงอันดัง กําแพงเมืองนั้นก็จะพังลงราบ และประชาชนจะขึ้นไปทุกคนต่างตรงไปข้างหน้าตน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 6, 'ฝ่ายโยชูวาบุตรชายนูนจึงเรียกปุโรหิตมาสั่งว่า “จงยกหีบพันธสัญญาขึ้นหามไป ให้ปุโรหิตเจ็ดคนถือแตรเขาแกะตัวผู้เจ็ดคันเดินนําหน้าหีบแห่งพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 7, 'และท่านสั่งประชาชนว่า “จงออกเดินรอบเมืองนั้น ให้ทหารถืออาวุธเดินข้างหน้าหีบแห่งพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 8, 'ต่อมาเมื่อโยชูวาบัญชาแก่ประชาชนแล้ว ปุโรหิตเจ็ดคนที่ถือเขาแกะตัวผู้เจ็ดคันก็เดินผ่านไปข้างหน้าต่อพระพักตร์พระเยโฮวาห์และเป่าแตรไปด้วย และมีหีบพันธสัญญาแห่งพระเยโฮวาห์ตามเขามา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 9, 'และทหารถืออาวุธเดินอยู่หน้าปุโรหิตผู้เป่าแตร และกองระวังหลังก็เดินตามหีบ ฝ่ายปุโรหิตนั้นก็เดินเรื่อยไปเป่าแตรอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 10, 'แต่โยชูวาบัญชาประชาชนว่า “ท่านอย่าโห่ร้อง อย่าให้ใครได้ยินเสียงของท่าน อย่าให้ถ้อยคําหลุดจากปากของท่านทั้งหลายเลย จนกว่าจะถึงวันที่ข้าพเจ้าบอกให้ท่านโห่ร้อง ท่านจึงโห่ร้องกัน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 11, 'หีบแห่งพระเยโฮวาห์จึงเวียนรอบเมืองดังนี้แหละ คือเวียนรอบหนึ่งเที่ยว เขาก็กลับเข้าค่าย นอนค้างคืนอยู่ในค่ายนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 12, 'โยชูวาตื่นขึ้นแต่เช้าและปุโรหิตก็ยกหีบแห่งพระเยโฮวาห์ขึ้นหาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 13, 'และปุโรหิตเจ็ดคนถือแตรเขาแกะตัวผู้เจ็ดคันเดินนําหน้าหีบแห่งพระเยโฮวาห์เรื่อยไปและเป่าแตรไปด้วย และทหารถืออาวุธก็เดินอยู่ข้างหน้าเขา และกองหลังก็เดินอยู่ข้างหลังหีบแห่งพระเยโฮวาห์ ฝ่ายปุโรหิตนั้นก็เดินเป่าแตรไปเรื่อยๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 14, 'และในวันที่สองเขาก็เดินรอบเมืองนั้นครั้งหนึ่งแล้วกลับเข้าค่ายอีก เขาทําเช่นนี้อยู่หกวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 15, 'ต่อมาในวันที่เจ็ดเขาลุกขึ้นแต่เช้าตรู่ เดินกระบวนรอบเมืองอย่างเคยเจ็ดครั้ง เฉพาะวันเดียวนั้นเขาได้เดินกระบวนรอบเมืองเจ็ดครั้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 16, 'อยู่มาในครั้งที่เจ็ด เมื่อปุโรหิตเป่าแตร โยชูวาบอกแก่ประชาชนว่า “จงโห่ร้องขึ้นเถิด เพราะพระเยโฮวาห์ทรงมอบเมืองให้แก่ท่านแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 17, 'เมืองนั้นและสารพัดในเมืองนั้นจะถูกสาปแช่งต่อพระเยโฮวาห์ เว้นแต่ราหับหญิงโสเภณีกับคนทั้งหลายที่อยู่ในเรือนของนางจะรอดชีวิต เพราะว่านางได้ซ่อนผู้สื่อสารที่พวกเราใช้ไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 18, 'แต่ส่วนท่านทั้งหลาย จงห่างไกลจากของที่ถูกสาปแช่งนั้น เกรงว่าเมื่อท่านทั้งหลายจะเก็บสิ่งที่ถูกสาปแช่งแล้วนั้นไว้บ้าง ท่านเองจะต้องถูกสาปแช่ง ทั้งจะทําให้ค่ายของคนอิสราเอลเป็นสิ่งที่ถูกสาปแช่ง และนําความทุกข์ลําบากมาสู่ค่าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 19, 'แต่บรรดาเงินและทอง และเครื่องใช้ที่ทําด้วยทองเหลืองและเหล็กเป็นของถวายแด่พระเยโฮวาห์ ให้นําเข้าไปไว้ในคลังของพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 20, 'เหตุฉะนั้นประชาชนก็โห่ร้องเมื่อปุโรหิตเป่าแตร ดังนั้นพอประชาชนได้ยินเสียงแตร เขาก็โห่ร้องดังและกําแพงก็พังลงราบ ประชาชนจึงขึ้นไปในเมืองทุกคนต่างตรงไปข้างหน้าตนและเข้ายึดเมืองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 21, 'แล้วเขาก็ทําลายสารพัดที่อยู่ในเมืองนั้นเสียสิ้นด้วยคมดาบ ทั้งชายและหญิง หนุ่มและแก่ ทั้งวัว แกะและลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 22, 'แต่โยชูวาได้สั่งชายสองคนผู้ที่ไปสอดแนมแผ่นดินนั้นว่า “จงเข้าไปในเรือนของหญิงโสเภณี และนําหญิงนั้นกับสารพัดซึ่งหญิงนั้นมีอยู่ออกมาดังที่ท่านได้สาบานแก่นางไว้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 23, 'ดังนั้นชายหนุ่มที่เป็นผู้สอดแนมก็เข้าไปนําราหับออกมา กับบิดามารดาและพี่น้องและสารพัดซึ่งเป็นของนาง และเขานําญาติพี่น้องทั้งหมดของนางออกมาให้ไปพักอยู่นอกค่ายของอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 24, 'ส่วนเมืองนั้นเขาก็จุดไฟเผาเสียทั้งสารพัดที่อยู่ในเมืองนั้น นอกจากเงินและทองและเครื่องใช้ที่ทําด้วยทองเหลืองและด้วยเหล็กนั้น เขานํามาไว้ในคลังในพระนิเวศของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 25, 'ส่วนราหับหญิงโสเภณี และครอบครัวบิดาของนาง และสารพัดที่เป็นของนาง โยชูวาได้ไว้ชีวิต และนางก็อาศัยอยู่ในอิสราเอลจนทุกวันนี้ เพราะว่านางซ่อนผู้สื่อสาร ซึ่งโยชูวาส่งไปสอดแนมเมืองเยรีโค');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 26, 'ในคราวนั้นโยชูวาให้คนทั้งหลายสาบานว่า “ผู้ใดที่ลุกขึ้นสร้างเมืองนี้ใหม่คือเมืองเยรีโค ก็ให้ผู้นั้นได้รับคําสาปแช่งเฉพาะพระพักตร์พระเยโฮวาห์ ผู้ใดวางรากลงก็ให้ผู้นั้นเสียบุตรหัวปี ผู้ใดตั้งประตูเมืองขึ้นก็ให้เสียบุตรสุดท้อง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 27, 'ดังนั้นแหละพระเยโฮวาห์ทรงสถิตอยู่กับโยชูวา และชื่อเสียงของท่านเลื่องลือไปตลอดแผ่นดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 1, 'แต่คนอิสราเอลได้ละเมิดในเรื่องของที่ถูกสาปแช่งนั้น เพราะอาคานบุตรชายคารมี ผู้เป็นบุตรชายศับดี ผู้เป็นบุตรชายเศ-ราห์ ตระกูลยูดาห์ ได้นําของที่ถูกสาปแช่งบางส่วนไปเป็นของตน และพระพิโรธของพระเยโฮวาห์ก็พลุ่งขึ้นต่อคนอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 2, 'ฝ่ายโยชูวาให้คนออกจากเยรีโคไปยังเมืองอัย ซึ่งอยู่ใกล้เบธาเวน ข้างทิศตะวันออกของเมืองเบธเอล บอกเขาว่า “จงขึ้นไปและสอดแนมดูเมืองนั้น” คนเหล่านั้นก็ขึ้นไปและสอดแนมดูที่เมืองอัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 3, 'และเขากลับมารายงานแก่โยชูวาว่า “ไม่ต้องให้ประชาชนทั้งหมดขึ้นไป ให้สักสองสามพันคนขึ้นไปตีเมืองอัยก็พอ ไม่ต้องให้ประชาชนทั้งหมดลําบากที่นั่นเลย เพราะเขามีคนน้อย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 4, 'เพราะฉะนั้นจึงมีประชาชนขึ้นไปที่นั่นเพียงสามพันคน แต่ต้องแตกหนีให้พ้นหน้าชาวเมืองอัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 5, 'ฝ่ายชาวเมืองอัยก็ฆ่าฟันคนเหล่านั้นตายประมาณสามสิบหกคน โดยขับไล่คนเหล่านั้นจากตรงหน้าประตูเมืองไปยังเชบาริมฟันเขาตามทางลง และจิตใจของประชาชนก็ละลายไปอย่างน้ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 6, 'ฝ่ายโยชูวาก็ฉีกเสื้อผ้าของตนซบหน้าลงถึงดินหน้าหีบแห่งพระเยโฮวาห์จนถึงเวลาเย็น ทั้งท่านกับพวกผู้ใหญ่ของคนอิสราเอล ต่างก็เอาผงคลีดินใส่ศีรษะของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 7, 'โยชูวากราบทูลว่า “โอ ข้าแต่องค์พระผู้เป็นเจ้าพระเจ้า อนิจจาเอ๋ย เป็นไฉนพระองค์จึงทรงนําชนชาตินี้ข้ามแม่น้ําจอร์แดนมา เพื่อจะมอบเราทั้งหลายไว้ในมือของคนอาโมไรต์ให้ทําลายเสีย พวกข้าพระองค์มีความเสียดายที่ไม่พอใจอยู่เพียงฟากแม่น้ําจอร์แดนข้างโน้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 8, 'โอ ข้าแต่องค์พระผู้เป็นเจ้า ข้าพระองค์จะทูลประการใดได้เล่าเมื่ออิสราเอลหันหลังหนีให้พ้นหน้าศัตรูเสียแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 9, 'เพราะว่าคนคานาอันกับผู้ที่อาศัยอยู่ในแผ่นดินนั้นคงจะได้ยิน แล้วคงจะยกมาตั้งล้อมพวกข้าพระองค์ และตัดชื่อของบรรดาข้าพระองค์เสียจากแผ่นดินโลก และพระองค์จะทรงกระทําประการใดต่อพระนามอันยิ่งใหญ่ของพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 10, 'ฝ่ายพระเยโฮวาห์ตรัสกับโยชูวาว่า “จงลุกขึ้นเถิด ไฉนเจ้าจึงซบหน้าลงดังนี้เล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 11, 'คนอิสราเอลได้กระทําบาป เขาได้ละเมิดพันธสัญญาซึ่งเราได้บัญชาเขาไว้ เขาได้ยักยอกของที่ถูกสาปแช่ง เขาได้ขโมยและปิดบัง และได้เอาของรวมไว้กับข้าวของของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 12, 'เพราะฉะนั้นคนอิสราเอลจึงยืนหยัดต่อสู้ศัตรูของตนไม่ได้ ได้หันหลังหนีต่อหน้าศัตรู เพราะเขากลายเป็นสิ่งที่ถูกสาปแช่ง เราจะไม่อยู่กับเจ้าทั้งหลายอีกต่อไป เว้นแต่เจ้าจะทําลายสิ่งของที่ถูกสาปแช่งเหล่านั้นเสียจากท่ามกลางพวกเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 13, 'จงลุกขึ้นชําระประชาชนให้บริสุทธิ์และกล่าวว่า ‘จงชําระตัวเสียเพื่อวันพรุ่งนี้ เพราะพระเยโฮวาห์พระเจ้าของคนอิสราเอลกล่าวเช่นนี้ว่า “โอ อิสราเอลเอ๋ย มีสิ่งของที่ถูกสาปแช่งอยู่ในหมู่พวกเจ้า เจ้าจะยืนหยัดต่อสู้ศัตรูของเจ้าไม่ได้จนกว่าเจ้าจะนําสิ่งของที่ถูกสาปแช่งนั้นออกเสียจากหมู่พวกเจ้า”’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 14, 'พอรุ่งเช้าเจ้าทั้งหลายจงเข้ามาทีละตระกูล ตระกูลใดที่พระเยโฮวาห์ทรงเลือกจับไว้ก็ต้องเข้ามาทีละครอบครัว ครอบครัวใดที่พระเยโฮวาห์ทรงเลือกจับไว้ก็ให้เข้ามาทีละครัวเรือน ครัวเรือนใดที่พระเยโฮวาห์ทรงเลือกจับไว้ ก็ให้เข้ามาทีละคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 15, 'ผู้ใดถูกจับว่ามีของที่ถูกสาปแช่งนั้น ก็ต้องถูกเผาเสียด้วยไฟ ทั้งตัวเขาและสารพัดที่เป็นของเขา เพราะเขาได้ละเมิดพันธสัญญาของพระเยโฮวาห์ และเพราะเขาได้กระทําความโง่เขลาในอิสราเอล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 16, 'โยชูวาจึงลุกขึ้นแต่เช้าตรู่ และนําคนอิสราเอลเข้ามาทีละตระกูล และตระกูลยูดาห์ทรงถูกเลือก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 17, 'จึงนําครอบครัวของยูดาห์เข้ามา และทรงเลือกครอบครัวเศ-ราห์ และนําครอบครัวเศ-ราห์มาทีละคน และศับดีทรงถูกเลือก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 18, 'และนําครัวเรือนของท่านเข้ามาทีละคน และคนที่ทรงถูกเลือกคืออาคานบุตรชายคารมี ผู้เป็นบุตรชายศับดี ผู้เป็นบุตรชายเศ-ราห์ ตระกูลยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 19, 'ฝ่ายโยชูวาจึงกล่าวแก่อาคานว่า “ลูกเอ๋ย จงถวายสง่าราศีแด่พระเยโฮวาห์พระเจ้าของอิสราเอล และจงสารภาพต่อพระองค์ จงบอกข้ามาว่าเจ้าได้กระทําอะไรไป อย่าปิดบังไว้จากข้าเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 20, 'และอาคานตอบโยชูวาว่า “เป็นความจริงแล้วที่ข้าพเจ้าได้กระทําบาปต่อพระเยโฮวาห์พระเจ้าของอิสราเอล ข้าพเจ้าได้กระทําดังนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 21, 'ในหมู่ของที่ริบมาข้าพเจ้าได้เห็นเสื้อคลุมงามตัวหนึ่งของเมืองบาบิโลน กับเงินสองร้อยเชเขล และทองคําแท่งหนึ่งหนักห้าสิบเชเขล ข้าพเจ้าก็โลภอยากได้ของเหล่านั้น ข้าพเจ้าจึงเอามา ดูเถิด ของเหล่านั้นซ่อนอยู่ใต้ดินในเต็นท์ของข้าพเจ้า เงินนั้นอยู่ข้างล่าง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 22, 'ฝ่ายโยชูวาก็ให้ผู้สื่อสารออกไปและเขาทั้งหลายก็วิ่งไปที่เต็นท์ ดูเถิด ของนั้นซ่อนอยู่ในเต็นท์ของเขา มีเงินอยู่ข้างล่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 23, 'เขาก็เอาออกมาจากกลางเต็นท์นําไปให้โยชูวาและคนอิสราเอลทั้งปวง แล้วเขาก็วางของเหล่านั้นลงต่อพระพักตร์พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 24, 'และโยชูวากับบรรดาคนอิสราเอลจึงพาอาคานบุตรชายเศ-ราห์ พร้อมกับเงิน เสื้อคลุมตัวนั้น และทองแท่งนั้น ทั้งบุตรชายหญิงของเขา ทั้งวัว ลา แพะแกะ และเต็นท์ของเขา ทุกสิ่งที่เขามีอยู่ และนําคนกับของทั้งหมดไปยังหุบเขาอาโคร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 25, 'และโยชูวากล่าวว่า “ทําไมเจ้าจึงนําความยากร้ายมาให้เรา พระเยโฮวาห์จะทรงนําความยากร้ายมาถึงเจ้าในวันนี้” และบรรดาคนอิสราเอลก็เอาหินขว้างเขาให้ตาย เผาเขาทั้งหลายด้วยไฟ เมื่อขว้างเขาด้วยก้อนหินแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 26, 'แล้วเอาหินถมกองทับเขาไว้เป็นกองใหญ่ยังอยู่จนทุกวันนี้ และพระเยโฮวาห์ก็ทรงหันกลับจากพระพิโรธอันแรงกล้าของพระองค์ เพราะฉะนั้นจนถึงทุกวันนี้เขายังเรียกที่นั้นว่าหุบเขาอาโคร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 1, 'พระเยโฮวาห์ตรัสกับโยชูวาว่า “อย่ากลัวหรือขยาดเลย จงนําทหารทั้งหมดไปกับเจ้า ลุกขึ้นไปยังเมืองอัยเถิด ดูเถิด เราได้มอบกษัตริย์เมืองอัยไว้ในมือเจ้าแล้ว พร้อมทั้งประชาชนของเขา เมืองของเขาและแผ่นดินของเขาด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 2, 'เจ้าจงกระทําแก่เมืองอัยและกษัตริย์ของเมืองนั้นเช่นเดียวกับที่เจ้ากระทํากับเมืองเยรีโคและกษัตริย์ของเมืองนั้น แต่ข้าวของและสัตว์ที่ริบมานั้น ตกเป็นของเจ้าได้ จงตั้งซุ่มไว้ที่ข้างหลังเมือง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 3, 'โยชูวาจึงลุกขึ้นพร้อมกับบรรดาทหารไปยังเมืองอัย และโยชูวาได้คัดทแกล้วทหารสามหมื่นคนให้ยกไปในเวลากลางคืน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 4, 'และท่านบัญชาเขาว่า “ดูเถิด ท่านจงซุ่มอยู่ข้างหลังเมือง อย่าให้ห่างไกลจากเมืองนัก และให้เตรียมตัวไว้พร้อมทุกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 5, 'ส่วนตัวเราและประชาชนทั้งหมดที่อยู่กับเราจะเข้าไปถึงตัวเมือง และต่อมาเมื่อเขาออกมาต่อสู้เราอย่างคราวก่อน เราก็จะถอยหนีให้พ้นหน้าเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 6, '(เขาจะตามเราออกมา) จนเราจะได้ลวงเขาให้ออกมาห่างจากตัวเมือง เพราะเขาจะพูดว่า ‘เขาทั้งหลายกําลังหนีจากเราอย่างคราวก่อน’ ฉะนี้เราจะหนีให้พ้นหน้าเขาเรื่อยมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 7, 'แล้วท่านทั้งหลายจงลุกจากที่ซุ่มซ่อนเข้ายึดเมืองนั้นไว้ เพราะพระเยโฮวาห์พระเจ้าของท่านจะทรงมอบเมืองนั้นไว้ในมือท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 8, 'และเมื่อท่านทั้งหลายเข้ายึดเมืองได้แล้ว ท่านจงจุดไฟเผาเมืองเสีย จงกระทําตามที่พระเยโฮวาห์ตรัสสั่ง ดูเถิด ข้าพเจ้าได้บัญชาท่านไว้แล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 9, 'แล้วโยชูวาก็ให้เขาไป เขาก็ออกไปยังที่ซุ่มอยู่ระหว่างเบธเอลกับเมืองอัย ทางทิศตะวันตกของเมืองอัย แต่คืนวันนั้นโยชูวานอนค้างอยู่กับประชาชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 10, 'โยชูวาตื่นขึ้นแต่เช้าตรู่ก็ออกตรวจประชาชน แล้วขึ้นไปพร้อมกับพวกผู้ใหญ่ของอิสราเอลนําหน้าประชาชนไปเมืองอัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 11, 'และบรรดาประชาชน คือทหารที่อยู่กับท่านทุกคน ก็ขึ้นไปแล้วรุกใกล้ตรงหน้าตัวเมืองเข้าไป และตั้งค่ายอยู่ด้านเหนือของเมืองอัย มีหุบเขาคั่นระหว่างเขากับเมืองอัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 12, 'และท่านจัดคนประมาณห้าพันคน ให้เขาแอบซุ่มอยู่ระหว่างเมืองเบธเอลกับเมืองอัย ทางทิศตะวันตกของตัวเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 13, 'ดังนั้นเขาทั้งหลายก็วางกําลังรบให้กองหลวงอยู่ด้านเหนือของเมือง และกองระวังหลังอยู่ด้านตะวันตกของเมือง ในคืนวันนั้นโยชูวานอนอยู่ในหุบเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 14, 'ต่อมาเมื่อกษัตริย์เมืองอัยเห็นดังนั้น ชาวเมืองก็รีบลุกขึ้นแต่เช้าตรู่ออกไปสู้รบกับอิสราเอล ณ ที่ปะทะกันหน้าที่ราบ ทั้งท่านและประชาชนทั้งหมดของท่าน แต่ท่านไม่ทราบว่ามีกองซุ่มคอยอยู่ต่อสู้ท่านข้างหลังเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 15, 'โยชูวากับอิสราเอลทั้งปวงจึงแสร้งทําเป็นแพ้ฝีมือต่อหน้าเขาแล้ว หนีตรงไปยังทางถิ่นทุรกันดาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 16, 'คนในเมืองอัยทั้งหมดก็ถูกเรียกให้ตามออกไป เมื่อเขาไล่ตามโยชูวาไปนั้น เขาก็ออกห่างจากเมืองไปทุกที');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 17, 'ไม่มีชายสักคนหนึ่งที่เหลืออยู่ในเมืองอัยหรือเมืองเบธเอล ที่มิได้ออกไปไล่ตามอิสราเอล เขาปล่อยให้เมืองเปิดอยู่ไล่ตามอิสราเอลไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 18, 'แล้วพระเยโฮวาห์ตรัสสั่งโยชูวาว่า “จงยื่นหอกซึ่งอยู่ในมือของเจ้าออกตรงไปยังเมืองอัย เพราะเราจะมอบเมืองนั้นไว้ในมือของเจ้า” แล้วโยชูวาก็ยื่นหอกซึ่งอยู่ในมือออกไปยังเมืองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 19, 'ทหารที่ซุ่มอยู่ก็ลุกออกจากที่ซ่อนอย่างรวดเร็ว พอโยชูวายื่นมือของท่านออก ทหารก็วิ่งตรงเข้าไปในเมืองและยึดเมืองไว้ แล้วเขาก็รีบจุดไฟเผาเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 20, 'เมื่อชาวเมืองอัยเหลียวหลังมาดู ดูเถิด ควันไฟที่ไหม้เมืองพลุ่งขึ้นไปยังท้องฟ้า เขาก็หมดกําลังที่จะหนีไปทางนี้หรือทางนั้น เพราะว่าประชาชนที่หนีไปทางถิ่นทุรกันดารหันกลับมาต่อสู้กับผู้ที่ไล่ตาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 21, 'และเมื่อโยชูวากับบรรดาอิสราเอลเห็นว่ากองซุ่มยึดเมืองได้แล้ว และควันไฟที่ไหม้เมืองพลุ่งขึ้น เขาก็หันกลับมาโจมตีชาวเมืองอัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 22, 'คนอื่นๆก็ออกมาจากเมืองสู้รบกับเขา กระทําให้เขาอยู่ระหว่างกลางอิสราเอล ผู้อยู่ข้างนี้บ้างข้างโน้นบ้าง และคนอิสราเอลก็โจมตีเขาจนไม่มีสักคนหนึ่งรอดชีวิตหรือหนีไปได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 23, 'แต่กษัตริย์เมืองอัยยังเป็นอยู่ ได้ถูกจับและคุมตัวมาหาโยชูวา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 24, 'ต่อมาเมื่ออิสราเอลไล่ฆ่าฟันชาวเมืองอัยทั้งหมดในทุ่งในถิ่นทุรกันดารที่เขาไล่ตามไปนั้น และคนเหล่านั้นล้มตายหมดด้วยคมดาบจนคนสุดท้าย บรรดาคนอิสราเอลก็กลับเข้าเมืองอัยโจมตีคนในเมืองด้วยคมดาบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 25, 'คนที่ล้มตายทั้งหมดวันนั้นทั้งชายและหญิงจํานวนหมื่นสองพันคน คือชาวเมืองอัยทั้งหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 26, 'เพราะโยชูวามิได้หดมือที่ถือหอกยื่นอยู่นั้น จนกว่าจะได้ผลาญชาวเมืองอัยพินาศสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 27, 'แต่คนอิสราเอลได้ริบเอาฝูงสัตว์และข้าวของของเมืองนั้นเป็นของตน ตามพระวจนะของพระเยโฮวาห์ ซึ่งทรงบัญชาไว้กับโยชูวา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 28, 'ดังนี้แหละโยชูวาจึงเผาเมืองอัยเสีย กระทําให้เป็นกองซากปรักหักพังอยู่เป็นนิตย์ คือเป็นที่รกร้างอยู่จนถึงทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 29, 'และท่านแขวนกษัตริย์เมืองอัยไว้ที่ต้นไม้จนถึงเวลาเย็น เมื่อดวงอาทิตย์ตกโยชูวาจึงบัญชาและเขาก็ปลดศพลงจากต้นไม้นําไปทิ้งไว้ที่ทางเข้าประตูเมือง แล้วเอาหินถมทับไว้เป็นกองใหญ่ซึ่งยังอยู่จนทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 30, 'แล้วโยชูวาได้สร้างแท่นบูชาในภูเขาเอบาลถวายแด่พระเยโฮวาห์พระเจ้าของอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 31, 'ดังที่โมเสสผู้รับใช้ของพระเยโฮวาห์บัญชาประชาชนอิสราเอล ตามที่จารึกไว้ในหนังสือพระราชบัญญัติของโมเสสว่า “แท่นบูชาทําด้วยหินมิได้ตกแต่ง ซึ่งไม่มีผู้ใดใช้เครื่องมือเหล็กถูกต้องเลย” แล้วเขาก็ถวายเครื่องเผาบูชาแด่พระเยโฮวาห์บนแท่นนั้น และถวายสันติบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 32, 'ณ ที่นั้นท่านคัดลอกพระราชบัญญัติของโมเสสบนหิน ซึ่งท่านได้เขียนไว้ต่อหน้าประชาชนอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 33, 'คนอิสราเอลทั้งหมด ทั้งคนต่างด้าวและคนที่เกิดในอิสราเอล พร้อมทั้งพวกผู้ใหญ่ เจ้าหน้าที่ และผู้พิพากษา ยืนอยู่ทั้งสองข้างของหีบต่อหน้าคนเลวีที่เป็นปุโรหิต ผู้ที่หามหีบพันธสัญญาของพระเยโฮวาห์ ครึ่งหนึ่งยืนอยู่ข้างหน้าภูเขาเกริซิม อีกครึ่งหนึ่งข้างหน้าภูเขาเอบาล ดังที่โมเสสผู้รับใช้ของพระเยโฮวาห์ได้บัญชาไว้ในครั้งแรกให้เขาทั้งหลายอวยพรแก่คนอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 34, 'ภายหลังท่านจึงอ่านบรรดาถ้อยคําในพระราชบัญญัติ เป็นคําอวยพรและคําสาปแช่ง ตามที่มีจารึกไว้ในหนังสือพระราชบัญญัติทุกประการ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 35, 'ไม่มีคําซึ่งโมเสสได้บัญชาไว้สักคําเดียวที่โยชูวามิได้อ่านต่อหน้าบรรดาชุมชนอิสราเอลพร้อมกับผู้หญิงกับเด็กๆ และคนต่างด้าวซึ่งอยู่ในหมู่พวกเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 1, 'ต่อมาเมื่อกษัตริย์ทั้งหลายที่อยู่ฟากแม่น้ําจอร์แดนข้างนี้ คือที่อยู่ในแดนเทือกเขา และในหุบเขา และตามฝั่งทะเลใหญ่ไปทั่วจนถึงภูเขาเลบานอน เป็นคนฮิตไทต์ คนอาโมไรต์ คนคานาอัน คนเปริสซี คนฮีไวต์ และคนเยบุสได้ยินข่าวนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 2, 'จึงพร้อมใจร่วมกําลังกันจะต่อสู้โยชูวาและอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 3, 'แต่เมื่อชาวกิเบโอนได้ยินข่าวการซึ่งโยชูวากระทําแก่เมืองเยรีโคและเมืองอัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 4, 'ฝ่ายเขาจึงทําอย่างฉลาด ทําเป็นทูต เอากระสอบที่เก่าบรรทุกบนลาของเขา กับถุงหนังที่เก่าขาดและปะไว้บรรจุน้ําองุ่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 5, 'สวมรองเท้าเก่าและปะไว้ และสวมเสื้อผ้าเก่า ส่วนเสบียงอาหารทั้งสิ้นก็แห้งมีราขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 6, 'เขาเดินทางมาหาโยชูวาที่ค่าย ณ เมืองกิลกาล กล่าวแก่ท่านและคนอิสราเอลว่า “พวกข้าพเจ้ามาจากประเทศที่ห่างไกล ฉะนั้นบัดนี้ขอทําพันธสัญญากับพวกข้าพเจ้าเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 7, 'แต่คนอิสราเอลกล่าวแก่คนฮีไวต์เหล่านั้นว่า “ชะรอยเจ้าอาศัยอยู่ในหมู่พวกเรา เราจะทําพันธสัญญากับเจ้าได้อย่างไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 8, 'เขากล่าวแก่โยชูวาว่า “ข้าพเจ้าทั้งหลายเป็นผู้รับใช้ของท่าน” และโยชูวากล่าวแก่เขาว่า “พวกเจ้าเป็นใครกัน และมาจากที่ไหน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 9, 'เขาตอบท่านว่า “เนื่องด้วยพระนามแห่งพระเยโฮวาห์พระเจ้าของท่าน ผู้รับใช้ของท่านมาจากประเทศที่ไกลมาก เราได้ยินถึงกิตติศัพท์ของพระองค์ และถึงบรรดาพระราชกิจที่พระองค์ทรงกระทําในอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 10, 'และได้ทราบถึงบรรดาสิ่งที่พระองค์ทรงกระทําต่อกษัตริย์คนอาโมไรต์ทั้งสองพระองค์ผู้อยู่ทางฟากแม่น้ําจอร์แดนข้างโน้น คือสิโหนกษัตริย์เมืองเฮชโบน และโอกกษัตริย์เมืองบาชานผู้อยู่ที่อัชทาโรท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 11, 'เหตุฉะนี้ พวกผู้ใหญ่และชาวเมืองทั้งหลายของเมืองข้าพเจ้าได้กล่าวแก่พวกข้าพเจ้าว่า ‘จงเอาเสบียงสําหรับเดินทางไปหาพวกเขาเรียนเขาว่า “พวกข้าพเจ้าทั้งหลายเป็นผู้รับใช้ของท่าน ฉะนั้นบัดนี้ขอทําพันธสัญญากับพวกข้าพเจ้าเถิด”’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 12, 'ขนมปังของพวกข้าพเจ้านี้ในวันที่ข้าพเจ้าออกมาหาท่าน ข้าพเจ้าเอาออกจากบ้านเมื่อยังร้อนๆ อยู่เพื่อใช้เป็นอาหารรับประทานตามทาง แต่บัดนี้ ดูเถิด แห้งและราขึ้นแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 13, 'ถุงนี้เมื่อข้าพเจ้าเติมน้ําองุ่นก็ยังใหม่อยู่ แต่ ดูเถิด มันขาดออก เสื้อผ้าและรองเท้าของข้าพเจ้าก็เก่า เพราะหนทางไกลมาก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 14, 'ฝ่ายคนเหล่านั้นก็รับเสบียงของเขาบ้าง แต่หาได้ทูลขอการแนะนําจากพระโอษฐ์ของพระเยโฮวาห์ไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 15, 'และโยชูวาก็กระทําสัญญาสันติภาพกับเขา และทําพันธสัญญากับเขา ให้ไว้ชีวิตพวกเขา และพวกประมุขของชุมนุมชนก็สาบานต่อเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 16, 'ต่อมาเมื่อได้กระทําพันธสัญญากับเขาล่วงมาได้สามวัน ก็ได้ยินว่าพวกเหล่านั้นเป็นชาวเมืองอยู่ในหมู่พวกตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 17, 'และคนอิสราเอลก็ออกเดินไปถึงเมืองของเขาในวันที่สาม เมืองของเขานั้นคือเมืองกิเบโอน เคฟีราห์ เบเอโรท และคีริยาทเยอาริม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 18, 'แต่คนอิสราเอลไม่ได้ฆ่าเขา เพราะว่าพวกประมุขของชุมนุมชนได้สาบานต่อเขาในพระนามพระเยโฮวาห์พระเจ้าของอิสราเอลแล้ว บรรดาชุมนุมชนก็บ่นต่อว่าพวกประมุข');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 19, 'แต่บรรดาประมุขได้กล่าวแก่ชุมนุมชนทั้งปวงว่า “เราได้สาบานต่อเขาในพระนามพระเยโฮวาห์พระเจ้าของอิสราเอล ฉะนั้นบัดนี้เราจะแตะต้องเขาไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 20, 'เราต้องกระทําแก่เขาอย่างนั้นโดยให้เขามีชีวิตอยู่ได้ เกรงว่าพระพิโรธจะตกลงเหนือเรา ตามคําสาบานซึ่งเราได้สาบานแก่เขานั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 21, 'และพวกประมุขก็กล่าวแก่เขาทั้งหลายว่า “ให้เขามีชีวิตอยู่เถิด แต่ให้เขาเป็นคนตัดฟืนและเป็นคนตักน้ําให้บรรดาชุมนุมชน” ดังที่พวกประชุมได้สัญญาไว้กับเขาแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 22, 'โยชูวาจึงเรียกคนเหล่านั้นมาและท่านกล่าวแก่เขาว่า “เหตุไฉนเจ้าทั้งหลายจึงหลอกลวงเราโดยกล่าวว่า ‘ข้าพเจ้าทั้งหลายอยู่ห่างไกลจากท่านมาก’ ในเมื่อเจ้าทั้งหลายอยู่ท่ามกลางเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 23, 'ฉะนั้นบัดนี้เจ้าทั้งหลายต้องรับคําสาปแช่งและพวกเจ้าจะไม่ขาดที่ต้องเป็นทาสอยู่ เป็นคนตัดฟืนและเป็นคนตักน้ําสําหรับพระนิเวศของพระเจ้าของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 24, 'เขาทั้งหลายตอบโยชูวาว่า “เพราะเขาได้บอกผู้รับใช้ของท่านอย่างแน่นอนว่า พระเยโฮวาห์พระเจ้าของท่านได้บัญชาโมเสสผู้รับใช้ของพระองค์ให้มอบแผ่นดินนี้ทั้งหมดแก่ท่าน และให้ทําลายชาวแผ่นดินให้พ้นหน้าท่าน เหตุฉะนั้นข้าพเจ้าทั้งหลายก็วิตกกลัวท่านทั้งหลายจะทําอันตรายแก่ชีวิตของข้าพเจ้า พวกข้าพเจ้าจึงกระทําอย่างนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 25, 'ดูเถิด บัดนี้ข้าพเจ้าทั้งหลายอยู่ในกํามือของท่าน จงกระทําแก่ข้าพเจ้าทั้งหลายตามที่ท่านเห็นชอบเห็นควรเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 26, 'โยชูวาจึงกระทําเช่นนั้น คือให้เขารอดจากมือคนอิสราเอล ไม่ให้ประหารชีวิตเขาเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 27, 'ในวันนั้นโยชูวาได้ตั้งเขาให้เป็นคนตัดฟืน และคนตักน้ําสําหรับชุมนุมชน และสําหรับแท่นบูชาของพระเยโฮวาห์สืบมาจนทุกวันนี้ ซึ่งอยู่ในสถานที่ซึ่งพระองค์ทรงเลือก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 1, 'ต่อมาเมื่ออาโดนีเซเดกกษัตริย์เมืองเยรูซาเล็มได้ยินว่า โยชูวาได้ยึดเมืองอัย และทําลายเมืองนั้นเสียอย่างสิ้นเชิงแล้ว ท่านได้กระทําต่อเมืองอัยและกษัตริย์ของเมืองนี้อย่างเดียวกับที่ได้กระทําต่อเมืองเยรีโคและกษัตริย์ของเมืองนั้น และทราบด้วยว่า ชาวเมืองกิเบโอนได้กระทําสันติภาพกับอิสราเอลและอยู่ท่ามกลางพวกเขาแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 2, 'ท่านก็คร้ามกลัวเป็นอย่างยิ่ง เพราะว่ากิเบโอนเป็นเมืองใหญ่เสมอเมืองหลวงและใหญ่กว่าเมืองอัย และบุรุษชาวเมืองนั้นก็ล้วนแต่ฉกรรจ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 3, 'เหตุฉะนี้อาโดนีเซเดกกษัตริย์เมืองเยรูซาเล็มจึงให้ไปหาโฮฮัมกษัตริย์เมืองเฮโบรนและปิรามกษัตริย์เมืองยารมูท และยาเฟียกษัตริย์เมืองลาคีช และเดบีร์กษัตริย์เมืองเอกโลน เรียนว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 4, '“ขอเชิญท่านมาหาข้าพเจ้า และช่วยข้าพเจ้าตีเมืองกิเบโอนเถิด เพราะว่าเมืองนั้นได้กระทําสันติภาพกับโยชูวาและคนอิสราเอล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 5, 'ฝ่ายกษัตริย์ของอาโมไรต์ทั้งห้าองค์ คือ กษัตริย์เมืองเยรูซาเล็ม กษัตริย์เมืองเฮโบรน กษัตริย์เมืองยารมูท กษัตริย์เมืองลาคีช และกษัตริย์เมืองเอกโลน ได้รวบรวมกําลังของตน และยกขึ้นไปพร้อมกับกองทัพทั้งหลาย ตั้งค่ายต่อสู้เมืองกิเบโอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 6, 'ฝ่ายชาวเมืองกิเบโอนจึงใช้คนไปหาโยชูวาที่ค่ายในกิลกาล กล่าวว่า “ขอท่านอย่าได้หย่อนมือจากผู้รับใช้ของท่านเลย ขอเร่งขึ้นมาช่วยข้าพเจ้าให้รอดและช่วยข้าพเจ้าทั้งหลาย เพราะว่าบรรดากษัตริย์ของคนอาโมไรต์ ซึ่งอยู่ในแดนเทือกเขา ได้รวมกําลังกันต่อสู้ข้าพเจ้าทั้งหลาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 7, 'ฝ่ายโยชูวาจึงขึ้นไปจากกิลกาล ทั้งท่านและบรรดาพลรบด้วย และทแกล้วทหารทั้งหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 8, 'พระเยโฮวาห์ตรัสแก่โยชูวาว่า “อย่ากลัวเขาเลย เพราะเราได้มอบเขาไว้ในมือเจ้าแล้ว จะไม่มีผู้ใดในพวกเขาสักคนเดียวที่จะยืนหยัดต่อสู้เจ้าได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 9, 'เหตุฉะนั้นโยชูวายกเข้าโจมตีพวกนั้นทันที โดยขึ้นไปตลอดคืนจากกิลกาล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 10, 'พระเยโฮวาห์ทรงกระทําให้เขาสะดุ้งแตกตื่นต่อหน้าพวกอิสราเอล พระองค์ได้ทรงฆ่าเขาเสียมากมายที่กิเบโอน และไล่ติดตามเขาไปในทางที่ขึ้นไปถึงเบธโฮโรน และตามฆ่าเขาจนถึงเมืองอาเซคาห์ และเมืองมักเคดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 11, 'ต่อมาขณะเมื่อเขาหนีไปข้างหน้าพวกอิสราเอลลงไปตามทางเบธโฮโรนนั้น พระเยโฮวาห์ทรงโยนลูกเห็บใหญ่ๆลงมาจากฟ้า ตลอดถึงเมืองอาเซคาห์ เขาทั้งหลายก็ตาย ผู้ที่ตายด้วยลูกเห็บนั้นก็มากกว่าผู้ที่คนอิสราเอลฆ่าเสียด้วยดาบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 12, 'แล้วโยชูวาก็กราบทูลพระเยโฮวาห์ในวันที่พระเยโฮวาห์ทรงมอบคนอาโมไรต์ต่อหน้าคนอิสราเอลนั้น และท่านได้กล่าวท่ามกลางสายตาของคนอิสราเอลว่า “ดวงอาทิตย์เอ๋ย เจ้าจงหยุดนิ่งตรงเมืองกิเบโอน และดวงจันทร์เอ๋ย เจ้าจงหยุดอยู่ตรงหุบเขาอัยยาโลน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 13, 'ดวงอาทิตย์ก็หยุดนิ่ง และดวงจันทร์ก็ตั้งเฉยอยู่จนประชาชนได้แก้แค้นศัตรูของเขาเสร็จ เรื่องนี้มิได้จารึกไว้ในหนังสือยาชาร์ดอกหรือ ดวงอาทิตย์หยุดนิ่งอยู่กลางท้องฟ้า หาได้รีบตกไปตามเวลาประมาณวันหนึ่งไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 14, 'วันที่พระเยโฮวาห์ทรงสดับฟังเสียงของมนุษย์อย่างกับวันนั้นทั้งในสมัยก่อนหรือในสมัยต่อมาไม่มีอีกแล้ว เพราะว่าพระเยโฮวาห์ทรงต่อสู้เพื่ออิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 15, 'แล้วโยชูวากับบรรดาคนอิสราเอลก็กลับมาสู่ค่ายที่กิลกาล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 16, 'กษัตริย์ทั้งห้านั้นหนีไปซ่อนตัวอยู่ในถ้ํามักเคดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 17, 'มีคนไปบอกโยชูวาว่า “มีคนพบกษัตริย์ทั้งห้าซ่อนตัวอยู่ในถ้ําที่มักเคดาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 18, 'โยชูวาจึงกล่าวว่า “จงกลิ้งก้อนหินใหญ่ปิดปากถ้ําเสีย และวางยามให้เฝ้ารักษาไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 19, 'แต่ท่านทั้งหลายอย่าคอยอยู่เลย จงติดตามศัตรูของท่านเถิด จงเข้าโจมตีกองระวังหลัง อย่าให้กลับเข้าในเมืองของเขาได้ เพราะว่าพระเยโฮวาห์พระเจ้าของท่านได้มอบเขาทั้งหลายไว้ในมือของท่านแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 20, 'ต่อมาเมื่อโยชูวากับคนอิสราเอลฆ่าพวกเหล่านั้นเสียเป็นอันมากจนหมดแล้ว ส่วนผู้ที่เหลืออยู่ก็หนีกลับเข้าไปในเมืองที่มีกําแพงล้อม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 21, 'ประชาชนทั้งปวงก็กลับมาหาโยชูวา ณ ค่ายที่มักเคดาห์โดยสันติภาพทุกคน หามีผู้ใดกล้ากระดิกลิ้นถึงคนอิสราเอลต่อไปไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 22, 'แล้วโยชูวาจึงว่า “จงเปิดปากถ้ําคุมกษัตริย์ทั้งห้านั้นออกจากถ้ํามาหาเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 23, 'เขาก็กระทําตาม จึงคุมกษัตริย์ทั้งห้าออกจากถ้ํามาหาท่าน มีกษัตริย์เมืองเยรูซาเล็ม กษัตริย์เมืองเฮโบรน กษัตริย์เมืองยารมูท กษัตริย์เมืองลาคีช และกษัตริย์เมืองเอกโลน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 24, 'ต่อมาเมื่อเขาพากษัตริย์เหล่านั้นมายังโยชูวา โยชูวาจึงเรียกบรรดาคนอิสราเอลมาและสั่งหัวหน้าของทหารผู้ที่ออกไปรบพร้อมกับท่านว่า “จงเข้ามาใกล้เถิด เอาเท้าเหยียบคอกษัตริย์เหล่านี้” แล้วเขาก็เข้ามาใกล้และเอาเท้าเหยียบที่คอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 25, 'และโยชูวากล่าวแก่เขาว่า “อย่ากลัวหรือขยาดเลย จงเข้มแข็งและกล้าหาญเถิด เพราะว่าพระเยโฮวาห์จะทรงกระทําแก่บรรดาศัตรูของท่านซึ่งท่านสู้รบอย่างนี้แหละ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 26, 'ภายหลังโยชูวาก็ได้ประหารชีวิตกษัตริย์ทั้งห้าเสีย แล้วแขวนไว้ที่ต้นไม้ห้าต้น และแขวนอยู่บนต้นไม้เช่นนั้นจนเวลาเย็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 27, 'ต่อมาเมื่อถึงเวลาดวงอาทิตย์ตก โยชูวาได้บัญชาและเขาก็ปลดศพลงจากต้นไม้และทิ้งไว้ในถ้ําซึ่งกษัตริย์เหล่านั้นได้ซ่อนตัวอยู่ และเอาหินใหญ่ๆปิดปากถ้ํานั้นไว้ ซึ่งยังอยู่จนกระทั่งวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 28, 'ในวันนั้นโยชูวายึดเมืองมักเคดาห์ได้ ได้ประหารเมืองนั้นเสียด้วยคมดาบ ทั้งกษัตริย์ของเมืองนั้น ท่านได้ทําลายเขาเสียอย่างสิ้นเชิง รวมทุกชีวิตที่อยู่ในเมือง ไม่มีเหลือสักคนเดียว และท่านได้กระทําแก่กษัตริย์มักเคดาห์อย่างที่ท่านได้กระทําแก่กษัตริย์เมืองเยรีโค');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 29, 'แล้วโยชูวาและบรรดาคนอิสราเอลก็ยกกองทัพจากเมืองมักเคดาห์มาถึงลิบนาห์ และเข้าสู้รบกับเมืองลิบนาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 30, 'พระเยโฮวาห์ได้ทรงมอบเมืองนั้นและกษัตริย์ของเมืองไว้ในมือคนอิสราเอล และท่านได้ประหารเมืองนั้นด้วยคมดาบและทุกคนที่อยู่ในเมืองนั้น ท่านไม่ให้เหลือสักคนเดียวในเมืองนั้น และท่านได้กระทําต่อกษัตริย์ของเมืองนั้นอย่างที่ท่านได้กระทําต่อกษัตริย์เมืองเยรีโค');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 31, 'และโยชูวาออกจากเมืองลิบนาห์พร้อมกับอิสราเอลทั้งหมดไปยังลาคีช แล้วล้อมเมืองไว้และเข้าโจมตีเมืองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 32, 'และพระเยโฮวาห์ทรงมอบเมืองลาคีชไว้ในมือคนอิสราเอล และท่านก็ได้ยึดเมืองนั้นในวันที่สอง และประหารเสียด้วยคมดาบ ทุกคนที่อยู่ในเมืองนั้น ดังที่ท่านได้กระทําแก่เมืองลิบนาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 33, 'ครั้งนั้นโฮรามกษัตริย์เมืองเกเซอร์ได้ขึ้นมาช่วยเมืองลาคีช และโยชูวาได้ประหารเขาและคนของเขาเสีย จนไม่เหลือให้เขาสักคนเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 34, 'โยชูวากับคนอิสราเอลทั้งปวงได้ยกออกจากลาคีชไปยังเมืองเอกโลน ได้เข้าล้อมและโจมตีเมืองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 35, 'และเขาก็ตีได้ในวันนั้นเองและฆ่าฟันทุกคนเสียด้วยคมดาบ จนทําลายเขาเสียสิ้นในวันนั้น ดังที่ท่านได้กระทําแก่เมืองลาคีช');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 36, 'โยชูวากับคนอิสราเอลทั้งปวงก็ขึ้นจากเมืองเอกโลนไปยังเมืองเฮโบรน เข้าโจมตีเมืองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 37, 'ยึดเมืองนั้นแล้วก็ประหารกษัตริย์และชนบททั้งหมดของเมืองนั้น กับทุกคนที่อยู่ในเมืองนั้นเสียด้วยคมดาบ ท่านไม่ให้เหลือสักคนเดียว ดังที่ท่านได้กระทําต่อเมืองเอกโลน และได้ทําลายเมืองนั้น และทุกคนที่อยู่ในเมืองนั้นเสียสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 38, 'แล้วโยชูวากับคนอิสราเอลทั้งปวงกลับมายังเมืองเดบีร์ เข้าโจมตีเมืองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 39, 'ท่านได้ยึดเมืองนั้นรวมทั้งกษัตริย์และชนบททั้งหมดของเมือง และได้ไปประหารเขาทั้งหลายเสียด้วยคมดาบ และได้ทําลายทุกคนที่อยู่ในเมืองนั้นเสียอย่างสิ้นเชิง ท่านไม่ให้เหลือสักคนเดียว ท่านได้กระทําแก่เมืองเฮโบรนอย่างไร ท่านก็ได้กระทําแก่เมืองเดบีร์และแก่กษัตริย์ของเมืองอย่างนั้น ดังทําแก่เมืองลิบนาห์และแก่กษัตริย์ของเมืองเช่นกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 40, 'โยชูวาก็ตีแผ่นดินนั้นให้พ่ายแพ้ไปหมด คือแดนเทือกเขา ในภาคใต้ ในหุบเขา และที่ลาด ทั้งกษัตริย์ทั้งหมดของเมืองเหล่านั้นด้วย ท่านไม่ให้เหลือสักคนเดียว แต่ได้ทําลายทุกสิ่งที่หายใจเสีย ดังที่พระเยโฮวาห์พระเจ้าของคนอิสราเอลได้ทรงบัญชาไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 41, 'โยชูวาได้กระทําให้เขาพ่ายแพ้ตั้งแต่เมืองคาเดชบารเนียจนถึงเมืองกาซา และทั่วประเทศโกเชนจนถึงเมืองกิเบโอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 42, 'โยชูวาก็ยึดตัวกษัตริย์เหล่านี้พร้อมทั้งพื้นดินของเขาทั้งหมดในคราวเดียวกัน เพราะว่าพระเยโฮวาห์พระเจ้าของคนอิสราเอลได้ทรงสู้รบเพื่ออิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 43, 'แล้วโยชูวาพร้อมกับบรรดาคนอิสราเอลก็ยกกลับมายังค่ายที่กิลกาล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 1, 'ต่อมาเมื่อยาบินกษัตริย์เมืองฮาโซร์ได้ยินข่าวนี้ จึงใช้คนไปหาโยบับกษัตริย์เมืองมาโดนและไปหากษัตริย์เมืองชิมโรน และกษัตริย์เมืองอัคชาฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 2, 'และกษัตริย์ซึ่งอยู่ในแดนเทือกเขาตอนเหนือ และที่อยู่ในที่ราบใต้เมืองคินเนเรท และในหุบเขา และในบริเวณชายแดนของโดร์ทางทิศตะวันตก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 3, 'และไปหาคนคานาอันทางทิศตะวันออกและทิศตะวันตก คนอาโมไรต์ คนฮิตไทต์ คนเปริสซี และคนเยบุสในแดนเทือกเขา และคนฮีไวต์อยู่เชิงเขาเฮอร์โมนในแผ่นดินมิสเปห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 4, 'กษัตริย์เหล่านี้ก็ยกออกมากับบรรดาพลโยธาเป็นกองทัพมหึมา มีจํานวนดังเม็ดทรายที่ชายทะเล มีม้าและรถรบมากมายด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 5, 'กษัตริย์เหล่านี้ได้ร่วมกําลังกันเข้าและมาตั้งค่ายอยู่ที่ลําห้วยเมโรม เพื่อจะสู้รบกับอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 6, 'และพระเยโฮวาห์ตรัสกับโยชูวาว่า “อย่ากลัวเขาเลย เพราะว่าพรุ่งนี้ในเวลาเดียวกันนี้ เราจะมอบเขาไว้หมดต่อหน้าอิสราเอลให้ถูกประหาร เอ็นน่องม้าของเขาให้เจ้าตัดเสีย และรถรบของเขา เจ้าจงเผาไฟเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 7, 'ฝ่ายโยชูวาก็ยกพลทั้งหลายเข้าโจมตีเขาทันทีที่ห้วยน้ําเมโรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 8, 'และพระเยโฮวาห์ทรงมอบเขาไว้ในมืออิสราเอล ผู้ประหารเขาและไล่ตามเขาไปจนถึงมหาไซดอนและถึงมิสเรโฟทมาอิม และถึงหุบเขามิสเปห์ด้านตะวันออก ได้ประหารเขาเสียจนไม่ให้เหลือสักคนเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 9, 'โยชูวาได้กระทําแก่เขาตามที่พระเยโฮวาห์ตรัสสั่งไว้ คือได้ตัดเอ็นน่องม้าและเผารถรบเสียด้วยไฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 10, 'ขณะนั้นโยชูวากลับมายึดเมืองฮาโซร์ และประหารกษัตริย์เมืองนั้นเสียด้วยดาบ เพราะว่าแต่ก่อนนี้ฮาโซร์เป็นหัวหน้าแห่งราชอาณาจักรเหล่านั้นทั้งหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 11, 'เขาได้ประหารบรรดาชาวเมืองนั้นเสียด้วยคมดาบ และทําลายเสียสิ้น สิ่งที่หายใจได้ไม่มีเหลือเลย และท่านก็เผาเมืองฮาโซร์เสียด้วยไฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 12, 'โยชูวายึดบรรดาหัวเมืองของกษัตริย์เหล่านั้นพร้อมกับกษัตริย์ทั้งหมด และประหารเสียด้วยคมดาบ ทําลายเขาสิ้น ดังที่โมเสสผู้รับใช้ของพระเยโฮวาห์ได้บัญชาไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 13, 'แต่เมืองต่างๆที่อยู่บนเนินเขา อิสราเอลมิได้เผา เว้นแต่เมืองฮาโซร์เมืองเดียวที่โยชูวาเผาเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 14, 'สิ่งของต่างๆที่ริบได้จากเมืองเหล่านี้ ทั้งฝูงสัตว์ คนอิสราเอลได้ยึดเป็นของของตน แต่เขาได้ประหารมนุษย์ทุกคนเสียด้วยคมดาบ จนทําลายเสียสิ้น สิ่งใดที่หายใจได้เขาไม่ให้เหลืออยู่เลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 15, 'พระเยโฮวาห์ทรงบัญชาโมเสสผู้รับใช้ของพระองค์อย่างไร โมเสสก็บัญชาโยชูวาอย่างนั้น และโยชูวาก็กระทําตาม ท่านไม่ได้เว้นที่จะทําทุกอย่างซึ่งพระเยโฮวาห์ทรงบัญชาโมเสสไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 16, 'โยชูวายึดแผ่นดินนั้นทั้งสิ้นคือแดนเทือกเขา และภาคใต้ทั้งหมด และแผ่นดินโกเชนทั้งหมด และในหุบเขา ในที่ราบ และแดนเทือกเขาของอิสราเอล และในหุบเขาของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 17, 'ตั้งแต่ภูเขาฮาลักที่สูงเรื่อยขึ้นไปถึงเสอีร์ ไกลไปจนถึงบาอัลกาดในหุบเขาเลบานอนเชิงภูเขาเฮอร์โมน ท่านได้จับบรรดากษัตริย์แห่งเมืองเหล่านั้นมาประหารชีวิตเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 18, 'โยชูวาทําศึกสงครามกับบรรดากษัตริย์เหล่านี้อยู่เป็นเวลานาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 19, 'ไม่มีสักเมืองหนึ่งที่กระทําสันติภาพกับคนอิสราเอล นอกจากคนฮีไวต์ ซึ่งเป็นชาวเมืองกิเบโอน เขาต้องทําศึกสงครามตีมาทั้งนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 20, 'เพราะเป็นมาจากพระเยโฮวาห์ที่ทรงให้เขามีใจแข็งกระด้างเข้าต่อสู้ทําสงครามกับอิสราเอล เพื่อพระองค์จะได้ทรงทําลายเขาเสียสิ้น และเขาไม่ได้รับความกรุณา แต่พระองค์ต้องทําลายล้างเขาเสียสิ้น ดังที่พระเยโฮวาห์บัญชาไว้กับโมเสส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 21, 'คราวนั้นโยชูวาได้มาขจัดคนอานาคออกจากแดนเทือกเขา จากเฮโบรน จากเดบีร์ จากอานาบ และจากทั่วแดนเทือกเขาแห่งยูดาห์ และจากทั่วแดนเทือกเขาแห่งอิสราเอล โยชูวาได้ทําลายคนเหล่านี้เสียสิ้นพร้อมทั้งเมืองทั้งหลายของพวกเขาด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 22, 'ไม่มีคนอานาคเหลืออยู่ในแผ่นดินของประชาชนอิสราเอล เว้นแต่ในกาซา กัทและอัชโดด ที่ยังมีเหลืออยู่บ้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 23, 'ดังนั้นแหละ โยชูวาได้ยึดแผ่นดินทั้งสิ้นตามสารพัดที่พระเยโฮวาห์ได้ตรัสไว้กับโมเสส และโยชูวาให้เป็นมรดกแก่คนอิสราเอลตามส่วนแบ่งของแต่ละตระกูล และแผ่นดินนั้นก็สงบจากการศึกสงคราม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 1, 'ต่อไปนี้เป็นกษัตริย์แห่งแผ่นดินนั้นซึ่งประชาชนอิสราเอลได้กระทําให้แพ้ไป และได้ยึดครองแผ่นดินฟากแม่น้ําจอร์แดนข้างโน้นทางดวงอาทิตย์ขึ้น จากที่ลุ่มแม่น้ําอารโนนถึงภูเขาเฮอร์โมน และที่ราบซึ่งอยู่ด้านตะวันออกทั้งหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 2, 'คือสิโหนกษัตริย์คนอาโมไรต์ผู้อยู่ที่เฮชโบน และปกครองจากอาโรเออร์ ซึ่งอยู่ ณ ริมลุ่มแม่น้ําอารโนน และจากกลางที่ลุ่มไกลไปจนถึงแม่น้ํายับบอก เขตแดนคนอัมโมน คือครึ่งหนึ่งของกิเลอาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 3, 'และแถบที่ราบถึงทะเลคินเนเรทข้างตะวันออก และตรงทางไปยังเบธเยชิโมทไปถึงทะเลแห่งที่ราบ คือทะเลเค็มข้างตะวันออก จากด้านใต้มาจนถึงที่อัชโดดปิสกาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 4, 'และเขตแดนของโอกกษัตริย์เมืองบาชาน เป็นพวกมนุษย์ยักษ์ที่เหลืออยู่ อยู่ที่อัชทาโรท และเอเดรอี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 5, 'และปกครองที่ภูเขาเฮอร์โมน และสาเลคาห์ และทั่วบาชาน ถึงเขตแดนคนเกชูร์และคนมาอาคาห์ และปกครองครึ่งหนึ่งของแดนกิเลอาด ถึงเขตแดนของสิโหนกษัตริย์เมืองเฮชโบน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 6, 'โมเสสผู้รับใช้ของพระเยโฮวาห์และคนอิสราเอลได้กระทําให้เขาพ่ายแพ้ไป และโมเสสผู้รับใช้ของพระเยโฮวาห์ได้มอบแผ่นดินตอนนี้ให้แก่คนรูเบน คนกาด และคนครึ่งตระกูลมนัสเสห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 7, 'ต่อไปนี้เป็นกษัตริย์แห่งแผ่นดินซึ่งโยชูวากับคนอิสราเอลได้ทําให้พ่ายแพ้อยู่ฟากแม่น้ําจอร์แดนข้างนี้ทางทิศตะวันตก ตั้งแต่บาอัลกาดในหุบเขาเลบานอน ถึงภูเขาฮาลัก ที่สูงเรื่อยขึ้นไปถึงเสอีร์ ซึ่งโยชูวามอบให้แก่ตระกูลคนอิสราเอลให้ถือเป็นกรรมสิทธิ์ตามส่วนแบ่งของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 8, 'คือที่ดินในแดนเทือกเขา ในหุบเขา ในที่ราบ ในที่ลาด ในถิ่นทุรกันดารและในภาคใต้ เป็นแผ่นดินของคนฮิตไทต์ คนอาโมไรต์ คนคานาอัน คนเปริสซี คนฮีไวต์และคนเยบุส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 9, 'คือกษัตริย์เมืองเยรีโคองค์หนึ่ง กษัตริย์เมืองอัยที่อยู่ข้างเบธเอลองค์หนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 10, 'กษัตริย์เมืองเยรูซาเล็มองค์หนึ่ง กษัตริย์เมืองเฮโบรนองค์หนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 11, 'กษัตริย์เมืองยารมูทองค์หนึ่ง กษัตริย์เมืองลาคีชองค์หนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 12, 'กษัตริย์เมืองเอกโลนองค์หนึ่ง กษัตริย์เมืองเกเซอร์องค์หนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 13, 'กษัตริย์เมืองเดบีร์องค์หนึ่ง กษัตริย์เมืองเกเดอร์องค์หนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 14, 'กษัตริย์เมืองโฮรมาห์องค์หนึ่ง กษัตริย์เมืองอาราดองค์หนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 15, 'กษัตริย์เมืองลิบนาห์องค์หนึ่ง กษัตริย์เมืองอดุลลัมองค์หนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 16, 'กษัตริย์เมืองมักเคดาห์องค์หนึ่ง กษัตริย์เมืองเบธเอลองค์หนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 17, 'กษัตริย์เมืองทัปปูวาห์องค์หนึ่ง กษัตริย์เมืองเฮเฟอร์องค์หนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 18, 'กษัตริย์เมืองอาเฟกองค์หนึ่ง กษัตริย์เมืองลาชาโรนองค์หนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 19, 'กษัตริย์เมืองมาโดนองค์หนึ่ง กษัตริย์เมืองฮาโซร์องค์หนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 20, 'กษัตริย์เมืองชิมโรนเมโรนองค์หนึ่ง กษัตริย์เมืองอัคชาฟองค์หนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 21, 'กษัตริย์เมืองทาอานาคองค์หนึ่ง กษัตริย์เมืองเมกิดโดองค์หนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 22, 'กษัตริย์เมืองเคเดชองค์หนึ่ง กษัตริย์เมืองโยกเนอัมในคารเมลองค์หนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 23, 'กษัตริย์เมืองโดร์ในบริเวณชายแดนของโดร์องค์หนึ่ง กษัตริย์ของประชาชาติต่างๆในกิลกาลองค์หนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 24, 'กษัตริย์เมืองทีรซาห์องค์หนึ่ง รวมทั้งหมดเป็นกษัตริย์สามสิบเอ็ดองค์ด้วยกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 1, 'เมื่อโยชูวาชราลงมีอายุมากแล้ว พระเยโฮวาห์ก็ตรัสกับท่านว่า “เจ้าชราลงมีอายุมากแล้ว แต่แผ่นดินที่จะต้องยึดครองนั้นยังมีอีกมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 2, 'ต่อไปนี้เป็นแผ่นดินที่ยังเหลืออยู่ คือ ท้องถิ่นฟีลิสเตียทั้งหมด และท้องถิ่นของคนเกชูร์ทั้งหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 3, 'ตั้งแต่ชิโหร์ซึ่งอยู่หน้าอียิปต์ เหนือขึ้นไปถึงเขตแดนเอโครน นับกันว่าเป็นของคนคานาอัน ผู้ครอบครองฟีลิสเตียมีอยู่ห้าคนด้วยกัน คือ ผู้ครอบครองเมืองกาซา เมืองอัชโดด เมืองอัชเคโลน เมืองกัท และเมืองเอโครน และเมืองของคนอิฟวาห์ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 4, 'ซึ่งอยู่ทิศใต้คือแผ่นดินทั้งสิ้นของคนคานาอัน และเขตเมอาราห์ ซึ่งเป็นของชาวไซดอนถึงเมืองอาเฟก ถึงเขตแดนของคนอาโมไรต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 5, 'และแผ่นดินของชาวเกบาลและเลบานอนทั้งหมด ไปทางที่ดวงอาทิตย์ขึ้น จากบาอัลกาดที่อยู่เชิงภูเขาเฮอร์โมน ถึงทางเข้าเมืองฮามัท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 6, 'ชาวแดนเทือกเขาทั้งหมดจากเลบานอนจนถึงมิสเรโฟทมาอิม และคนไซดอนทั้งหมด เราจะขับไล่เขาทั้งหลายออกไปให้พ้นหน้าคนอิสราเอลเอง เพียงแต่เจ้าจงจับฉลากแบ่งดินแดนเหล่านั้นให้เป็นมรดกแก่อิสราเอล ดังที่เราบัญชาเจ้าไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 7, 'ฉะนั้นบัดนี้จงแบ่งแผ่นดินนี้ออกให้เป็นมรดกแก่คนเก้าตระกูลรวมกับคนมนัสเสห์ครึ่งตระกูลด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 8, 'ส่วนมนัสเสห์อีกครึ่งตระกูล คนรูเบน และคนกาดได้รับส่วนมรดกของเขา ซึ่งโมเสสได้มอบให้ทางฟากแม่น้ําจอร์แดนข้างโน้นด้านตะวันออก ส่วนที่โมเสสผู้รับใช้ของพระเยโฮวาห์มอบให้เขาคือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 9, 'ตั้งแต่อาโรเออร์ ซึ่งอยู่ริมลุ่มแม่น้ําอารโนน และเมืองที่อยู่กลางลุ่มแม่น้ํานี้ และที่ราบเมเดบาตลอดจนถึงดีโบน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 10, 'และหัวเมืองทั้งสิ้นของสิโหนกษัตริย์คนอาโมไรต์ ผู้ซึ่งครอบครองอยู่ในเฮชโบน ไกลออกไปจนถึงเขตแดนคนอัมโมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 11, 'กับเขตกิเลอาดและท้องถิ่นของคนเกชูร์และคนมาอาคาห์ และภูเขาเฮอร์โมนทั้งหมด และเมืองบาชานทั้งสิ้นจนถึงเมืองสาเลคาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 12, 'ตลอดราชอาณาจักรของโอกในบาชาน ผู้ครอบครองอยู่ในอัชทาโรทและในเอเดรอี ท่านเป็นพวกมนุษย์ยักษ์ที่เหลืออยู่ เมืองเหล่านี้โมเสสรบชนะ และได้ขับไล่ให้ออกไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 13, 'แต่คนอิสราเอลยังหาได้ขับไล่คนเกชูร์หรือคนมาอาคาห์ให้ออกไปไม่ แต่คนเกชูร์กับคนมาอาคาห์ยังอาศัยอยู่ในหมู่คนอิสราเอลจนทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 14, 'เฉพาะตระกูลเลวีตระกูลเดียวโมเสสหาได้มอบมรดกให้ไม่ ของบูชาด้วยไฟที่ถวายแด่พระเยโฮวาห์พระเจ้าของอิสราเอลเป็นมรดกของเขา ดังที่พระองค์ตรัสไว้แก่เขาแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 15, 'และโมเสสได้มอบส่วนมรดกให้แก่ตระกูลคนรูเบนตามครอบครัวของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 16, 'ดังนั้นเขตแดนของเขาจึงตั้งแต่อาโรเออร์ซึ่งอยู่ริมลุ่มแม่น้ําอารโนนและเมืองซึ่งอยู่กลางลุ่มแม่น้ํานั้นและที่ราบเมืองเมเดบาทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 17, 'ทั้งเมืองเฮชโบน รวมกับหัวเมืองทั้งสิ้นซึ่งอยู่บนที่ราบนั้น คือดีโบน และบาโมทบาอัล และเบธบาอัลเมโอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 18, 'กับยาฮาส และเคเดโมท และเมฟาอาท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 19, 'และคีริยาธาอิม และสิบมาห์และเศเรทชาหาร์ซึ่งอยู่บนเนินเขาแห่งหุบเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 20, 'กับเบธเปโอร์ และที่อัชโดดปิสกาห์ และเมืองเบธเยชิโมท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 21, 'คือหัวเมืองทั้งสิ้นซึ่งอยู่บนที่ราบ และทั้งราชอาณาจักรทั้งหมดของสิโหนกษัตริย์คนอาโมไรต์ผู้ครอบครองอยู่ในเฮชโบน ซึ่งโมเสสได้กระทําให้พ่ายแพ้พร้อมกับเจ้านายของมีเดียน คือ เอวี เรเคม ศูร์ และเฮอร์ กับเรบา เป็นเจ้านายซึ่งขึ้นแก่กษัตริย์สิโหนผู้พํานักอยู่ในแผ่นดินนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 22, 'อนึ่งคนอิสราเอลได้ฆ่าบาลาอัมบุตรชายเบโอร์ผู้เป็นคนทํานายเสียด้วยดาบพร้อมกับคนอื่นที่เขาได้ฆ่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 23, 'อาณาเขตของคนรูเบนคือแม่น้ําจอร์แดนเป็นพรมแดน นี่เป็นมรดกของคนรูเบนตามครอบครัว รวมทั้งหัวเมืองและชนบทด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 24, 'โมเสสได้มอบมรดกให้แก่ตระกูลกาด คือคนกาดตามครอบครัวของเขาด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 25, 'อาณาเขตของเขาคือยาเซอร์และหัวเมืองกิเลอาดทั้งหมด และครึ่งหนึ่งของแผ่นดินคนอัมโมนถึงอาโรเออร์ซึ่งอยู่หน้าเมืองรับบาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 26, 'ตั้งแต่เมืองเฮชโบน จนถึงเมืองรามัทมิสเปห์และเบโทนิม และตั้งแต่มาหะนาอิมจนถึงเขตแดนเดบีร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 27, 'ในหว่างเขา มีเมืองเบธฮารัม เบธนิมราห์ สุคคทและซาโฟน ราชอาณาจักรส่วนที่เหลือของสิโหนกษัตริย์เมืองเฮชโบนนั้น มีแม่น้ําจอร์แดนเป็นพรมแดน จดทะเลคินเนเรทตอนปลายข้างล่าง ด้านตะวันออกของแม่น้ําจอร์แดนข้างโน้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 28, 'นี่เป็นมรดกของคนกาดตามครอบครัวของเขา รวมทั้งหัวเมืองและชนบทด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 29, 'อนึ่งโมเสสได้มอบมรดกให้แก่คนมนัสเสห์ครึ่งตระกูล เป็นส่วนแบ่งที่ได้กับคนมนัสเสห์ครึ่งตระกูลตามครอบครัวของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 30, 'อาณาเขตของเขาทั้งหลายเริ่มตั้งแต่มาหะนาอิมตลอดบาชานทั้งสิ้น คือราชอาณาจักรทั้งสิ้นของโอกกษัตริย์เมืองบาชาน และหัวเมืองทั้งหมดของยาอีร์ มีหกสิบหัวเมืองด้วยกันอยู่ในบาชาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 31, 'และกิเลอาดครึ่งหนึ่ง และเมืองอัชทาโรทกับเมืองเอเดรอี หัวเมืองของราชอาณาจักรโอกในบาชาน หัวเมืองเหล่านี้เป็นส่วนแบ่งของคนมาคีร์บุตรชายมนัสเสห์ เป็นของครึ่งหนึ่งของคนมาคีร์ ตามครอบครัวของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 32, 'เหล่านี้เป็นดินแดนต่างๆซึ่งโมเสสได้แบ่งปันให้เป็นมรดก ณ ที่ราบโมอับ ฟากแม่น้ําจอร์แดนข้างโน้นทิศตะวันออกของเมืองเยรีโค');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 33, 'แต่โมเสสมิได้มอบมรดกให้แก่คนตระกูลเลวี พระเยโฮวาห์พระเจ้าของอิสราเอลเป็นมรดกของเขา ดังที่พระองค์ตรัสไว้กับเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 1, 'ต่อไปนี้เป็นดินแดนต่างๆซึ่งประชาชนอิสราเอลได้รับเป็นมรดกในแผ่นดินคานาอัน ซึ่งเอเลอาซาร์ปุโรหิตและโยชูวาบุตรชายนูน และหัวหน้าบรรพบุรุษของตระกูลต่างๆแห่งคนอิสราเอลได้แจกจ่ายให้เป็นมรดกแก่เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 2, 'มรดกนี้เขาจับฉลากแบ่งกันในระหว่างคนเก้าตระกูลครึ่ง ตามที่พระเยโฮวาห์ทรงบัญชาทางโมเสส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 3, 'เพราะโมเสสได้ให้มรดกแก่คนสองตระกูลครึ่งทางฟากแม่น้ําจอร์แดนข้างโน้นแล้ว แต่ท่านหาได้แบ่งส่วนมรดกให้แก่พวกเลวีไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 4, 'เพราะว่าลูกหลานของโยเซฟมีสองตระกูล คือมนัสเสห์และเอฟราอิม และพวกเลวีหาได้มีส่วนแบ่งในแผ่นดินนั้นไม่ ได้แต่หัวเมืองที่จะเข้าอาศัยอยู่ กับลานทุ่งหญ้ารอบเมืองสําหรับฝูงสัตว์และทรัพย์สินของเขาเท่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 5, 'คนอิสราเอลได้กระทําตามที่พระเยโฮวาห์ทรงบัญชาไว้กับโมเสส เขาแบ่งที่ดินกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 6, 'ขณะนั้นคนยูดาห์มาหาโยชูวา ณ เมืองกิลกาล และคาเลบบุตรชายเยฟุนเนห์ชาวเคนัสได้กล่าวแก่ท่านว่า “ท่านทราบเรื่องซึ่งพระเยโฮวาห์ตรัสกับโมเสสบุรุษของพระเจ้าที่คาเดชบารเนียเกี่ยวกับท่านและข้าพเจ้าแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 7, 'เมื่อโมเสสผู้รับใช้ของพระเยโฮวาห์ใช้ให้ข้าพเจ้าไปจากคาเดชบารเนีย เพื่อสอดแนมดูแผ่นดิน ข้าพเจ้ามีอายุสี่สิบปี ข้าพเจ้าได้นําข่าวมาแจ้งแก่ท่านตามความคิดเห็นของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 8, 'แต่ส่วนพี่น้องซึ่งขึ้นไปพร้อมกับข้าพเจ้าได้กระทําให้จิตใจของประชาชนละลายไป แต่ข้าพเจ้าได้ติดตามพระเยโฮวาห์พระเจ้าของข้าพเจ้าอย่างสุดใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 9, 'ในวันนั้นโมเสสได้ปฏิญาณว่า ‘แท้จริงแผ่นดินซึ่งเท้าของท่านได้เหยียบย่ําไปนั้นจะตกเป็นมรดกของท่าน และของลูกหลานของท่านสืบไปเป็นนิตย์ เพราะว่าท่านได้ติดตามพระเยโฮวาห์พระเจ้าของข้าพเจ้าอย่างสุดใจ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 10, 'และบัดนี้ ดูเถิด พระเยโฮวาห์ยังทรงให้ข้าพเจ้ามีชีวิตอยู่ตลอดสี่สิบห้าปีนี้ ดังที่พระองค์ตรัส ตั้งแต่พระเยโฮวาห์ตรัสเช่นนี้แก่โมเสส เมื่อคนอิสราเอลเดินทางอยู่ในถิ่นทุรกันดาร และบัดนี้ ดูเถิด วันนี้ข้าพเจ้ามีอายุแปดสิบห้าปีแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 11, 'วันนี้ข้าพเจ้ายังมีกําลังแข็งแรงเช่นเดียวกับวันที่โมเสสใช้ให้ข้าพเจ้าไป กําลังของข้าพเจ้าในการทําศึกสงครามหรือออกไปและเข้ามาเดี๋ยวนี้ก็เป็นเหมือนครั้งนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 12, 'ฉะนั้นบัดนี้ขอมอบแดนเทือกเขานี้ ซึ่งพระเยโฮวาห์ตรัสในวันนั้นให้แก่ข้าพเจ้า เพราะท่านได้ยินในวันนั้นแล้วว่าคนอานาคอยู่ที่นั่น มีหัวเมืองใหญ่ที่มีกําแพงล้อมอย่างเข้มแข็ง ชะรอยพระเยโฮวาห์จะทรงสถิตกับข้าพเจ้า ข้าพเจ้าก็จะขับไล่เขาออกไปได้ ดังที่พระเยโฮวาห์ตรัสไว้แล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 13, 'แล้วโยชูวาก็อวยพรแก่ท่านและยกเมืองเฮโบรนให้คาเลบบุตรชายเยฟุนเนห์เป็นมรดก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 14, 'เฮโบรนจึงตกเป็นมรดกแก่คาเลบบุตรชายเยฟุนเนห์คนเคนัสจนทุกวันนี้ เพราะว่าท่านติดตามพระเยโฮวาห์พระเจ้าของอิสราเอลอย่างสุดใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 15, 'เมืองเฮโบรนนั้นแต่เดิมมีชื่อว่าคีริยาทอารบา อารบาคนนี้เป็นคนใหญ่โตในคนอานาค แผ่นดินจึงได้สงบจากการศึกสงคราม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 1, 'ที่ดินส่วนของตระกูลคนยูดาห์ตามครอบครัวของเขานั้น ด้านใต้ถึงพรมแดนเมืองเอโดม คือถึงถิ่นทุรกันดารศินเป็นที่สุดปลายเขตด้านใต้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 2, 'พรมแดนทางทิศใต้นั้นตั้งแต่ต้นจากปลายทะเลเค็ม คือตั้งแต่อ่าวซึ่งไปทางทิศใต้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 3, 'ยื่นไปทางด้านใต้ของมาอาเลอัครับบิม ผ่านเรื่อยไปถึงศิน แล้วขึ้นไปทางด้านใต้เมืองคาเดชบารเนีย ตามทางเมืองเฮสโรน ขึ้นไปถึงเมืองอัดดาร์เลี้ยวไปถึงคารคา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 4, 'ผ่านเรื่อยไปถึงอัสโมนยื่นออกไปถึงแม่น้ําอียิปต์มาสิ้นสุดลงที่ทะเล ที่กล่าวนี้จะเป็นพรมแดนด้านใต้ของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 5, 'พรมแดนด้านตะวันออกคือทะเลเค็มขึ้นไปถึงปากแม่น้ําจอร์แดน และพรมแดนด้านเหนือตั้งแต่อ่าวที่ทะเลตรงปากแม่น้ําจอร์แดน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 6, 'และพรมแดนนั้นยื่นไปถึงเบธฮกลาห์ผ่านไปตามด้านเหนือของเมืองเบธอาราบาห์ และพรมแดนยื่นต่อไปถึงก้อนหินโบฮันบุตรชายรูเบน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 7, 'และพรมแดนยื่นไปถึงเดบีร์จากหุบเขาอาโคร์ ตรงไปทางทิศเหนือเลี้ยวไปหาเมืองกิลกาล ซึ่งอยู่ตรงข้ามทางข้ามเขาที่ชื่ออดุมมิม ซึ่งอยู่ทางด้านใต้ของแม่น้ํา และพรมแดนก็ผ่านไปถึงน้ําพุเอนเชเมช ไปสิ้นสุดลงที่เอนโรเกล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 8, 'แล้วพรมแดนก็ยื่นไปตามหุบเขาบุตรชายของฮินโนมถึงไหล่เขาด้านใต้ของเมืองคนเยบุส คือเยรูซาเล็ม แล้วพรมแดนก็ยื่นไปถึงยอดภูเขาซึ่งอยู่หน้าหุบเขาฮินโนมทางด้านตะวันตก ที่หุบเขาแห่งพวกมนุษย์ยักษ์ด้านเหนือสุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 9, 'แล้วพรมแดนก็ยื่นไปจากยอดภูเขาถึงน้ําพุแห่งลําห้วยเนฟโทอาห์ จากที่นั่นก็มาถึงหัวเมืองแห่งภูเขาเอโฟรน แล้วพรมแดนก็เลี้ยวโค้งไปหาเมืองบาอาลาห์ คือเมืองคีริยาทเยอาริม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 10, 'แล้วพรมแดนก็เลี้ยวโค้งจากบาอาลาห์ไปทางทิศตะวันตกถึงภูเขาเสอีร์ ผ่านไปตามไหล่เขายาอาริมด้านเหนือ คือเคสะโลน ลงไปถึงเมืองเบธเชเมชผ่านเมืองทิมนาห์ไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 11, 'แล้วพรมแดนก็ยื่นออกไปจากทางไหล่เนินเขาด้านเหนือของเมืองเอโครน แล้วก็โค้งไปหาเมืองชิกเคโรนผ่านไปถึงภูเขาบาอาลาห์ ออกไปถึงเมืองยับเนเอล และพรมแดนก็มาสิ้นสุดลงที่ทะเล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 12, 'พรมแดนด้านตะวันตก คือทะเลใหญ่ตามฝั่งทะเล นี่เป็นพรมแดนล้อมรอบคนยูดาห์ตามครอบครัวของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 13, 'ตามพระดํารัสของพระเยโฮวาห์ที่ตรัสแก่โยชูวา ท่านยกที่ดินส่วนหนึ่งในเขตของคนยูดาห์ให้แก่คาเลบบุตรชายเยฟุนเนห์ คือเมืองอารบาที่เรียกเมืองเฮโบรน อารบาเป็นบิดาของอานาค');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 14, 'และคาเลบได้ขับไล่บุตรชายทั้งสามของอานาคออกจากที่นั่น คือเชชัย อาหิมานและทัลมัย ผู้เป็นบุตรของอานาค');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 15, 'และท่านขึ้นไปจากที่นั่นจะต่อสู้กับชาวเมืองเดบีร์ เมืองเดบีร์เดิมมีชื่อว่า คีริยาทเสเฟอร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 16, 'และคาเลบกล่าวว่า “ผู้ใดโจมตีเมืองคีริยาทเสเฟอร์และยึดได้ เราจะยกอัคสาห์บุตรสาวของเราให้เป็นภรรยา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 17, 'และโอทนีเอลบุตรชายเคนัส น้องชายของคาเลบตีเมืองนั้นได้ ท่านจึงยกอัคสาห์บุตรสาวของตนให้เป็นภรรยา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 18, 'อยู่มาเมื่อแต่งงานกันแล้วนางจึงชวนสามีให้ขอที่นาต่อบิดา นางก็ลงจากหลังลา และคาเลบถามนางว่า “เจ้าต้องการอะไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 19, 'นางตอบว่า “ขอของขวัญให้ลูกสักอย่างหนึ่งเถิด เมื่อพ่อให้ลูกมาอยู่ในแผ่นดินภาคใต้แล้ว ลูกขอน้ําพุด้วย” คาเลบก็ยกน้ําพุบนและน้ําพุล่างให้แก่นาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 20, 'ต่อไปนี้เป็นมรดกของตระกูลคนยูดาห์ตามครอบครัวของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 21, 'หัวเมืองที่เป็นของตระกูลคนยูดาห์ ซึ่งอยู่ทางทิศใต้สุดทางพรมแดนเอโดม คือเมืองขับเซเอล เอเดอร์ และยากูร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 22, 'คีนาห์ ดีโมนาห์ อาดาดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 23, 'เคเดช ฮาโซร์ อิทนาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 24, 'ศิฟ เทเลม เบอาโลท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 25, 'ฮาโซร์ ฮาดัททาห์ เคริโอท เฮสโรน คือเมืองฮาโซร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 26, 'อามัม เชมา โมลาดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 27, 'ฮาซารกัดดาห์ เฮชโมน เบธเปเลท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 28, 'ฮาซารชูอาล เบเออร์เชบา บิซิโอธิยาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 29, 'บาอาลาห์ ไอยิม เอเซม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 30, 'เอลโทลัด เคสีล โฮรมาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 31, 'ศิกลาก มัดมันนาห์ สันสันนาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 32, 'เลบาโอท ชิลฮิม อายินและเมืองริมโมน รวมทั้งหมดเป็นยี่สิบเก้าหัวเมืองกับชนบทของเมืองนั้นๆด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 33, 'ในหุบเขามีเมืองเอชทาโอล โศราห์ อัชนาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 34, 'ศาโนอาห์ เอนกันนิม ทัปปูวาห์ เอนาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 35, 'ยารมูท อดุลลัม โสโคห์ อาเซคาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 36, 'ชาอาราอิม อดีธาอิม เกเดราห์ เกเดโรธาอิม รวมเป็นสิบสี่หัวเมืองกับชนบทของเมืองนั้นๆด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 37, 'เมืองเศนัน ฮาดัสสาห์ มิกดัลกาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 38, 'ดิเลอัน มิสเปห์ โยกเธเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 39, 'ลาคีช โบสคาท เอกโลน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 40, 'คับโบน ลามัม คิทลิช');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 41, 'เกเดโรท เบธดาโกน นาอามาห์และเมืองมักเคดาห์ รวมเป็นสิบหกหัวเมืองกับชนบทของเมืองนั้นๆด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 42, 'ลิบนาห์ เอเธอร์ อาชัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 43, 'ยิฟทาห์ อัชนาห์ เนซีบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 44, 'เคอีลาห์ อัคซีบ มาเรชาห์ รวมเป็นเก้าหัวเมืองกับชนบทของเมืองนั้นๆด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 45, 'เอโครน กับหัวเมืองและชนบทของเมืองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 46, 'จากกรุงเอโครนถึงทะเล และบรรดาเมืองที่อยู่ริมเมืองอัชโดดกับชนบทของเมืองนั้นๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 47, 'อัชโดด กับหัวเมืองและชนบทของเมืองนั้น กาซา กับหัวเมืองและชนบทของเมืองนั้นจนถึงแม่น้ําอียิปต์ และทะเลใหญ่พร้อมกับฝั่งชายทะเล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 48, 'และในแดนเทือกเขา คือ ชามีร์ ยาททีร์ โสโคห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 49, 'ดานนาห์ คีริยาทสันนาห์ คือเมืองเดบีร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 50, 'อานาบ เอชเทโมห์ อานิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 51, 'โกเชน โฮโลน กิโลห์ รวมเป็นสิบเอ็ดหัวเมืองกับชนบทของเมืองนั้นๆด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 52, 'อาหรับ ดูมาห์ เอชาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 53, 'ยานิม เบธทัปปูวาห์ อาเฟคาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 54, 'ฮุมทาห์ คีริยาทอารบา คือเมืองเฮโบรน และเมืองศิโยร์ รวมเป็นเก้าหัวเมืองกับชนบทของเมืองนั้นๆด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 55, 'มาโอน คารเมล ศิฟ ยุทธาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 56, 'ยิสเรเอล โยกเดอัม ศาโนอาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 57, 'คาอิน กิเบอาห์ และทิมนาห์ รวมเป็นสิบหัวเมืองกับชนบทของเมืองนั้นๆด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 58, 'ฮัลฮูล เบธซูร์ เกโดร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 59, 'มาอาราท เบธาโนท และเมืองเอลเทโคน รวมเป็นหกหัวเมืองกับชนบทของเมืองนั้นๆด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 60, 'คีริยาทบาอัล คือเมืองคีริยาทเยอาริม และรับบาห์ รวมเป็นสองหัวเมืองกับชนบทของเมืองนั้นๆด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 61, 'เมืองที่ในถิ่นทุรกันดาร คือเบธอาราบาห์ มิดดีน เสคะคาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 62, 'นิบชาน เมืองเกลือ และเอนเกดี รวมเป็นหกหัวเมืองกับชนบทของเมืองนั้นๆด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 63, 'แต่คนเยบุสซึ่งเป็นชาวเมืองเยรูซาเล็มนั้น ประชาชนยูดาห์หาได้ขับไล่ไปไม่ ดังนั้นแหละคนเยบุสจึงอาศัยอยู่กับประชาชนยูดาห์ที่เมืองเยรูซาเล็มจนถึงทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 1, 'ที่ดินตามฉลากของลูกหลานโยเซฟนั้นเริ่มจากแม่น้ําจอร์แดนใกล้ๆเมืองเยรีโค ทิศตะวันออกของน้ําแห่งเยรีโคเข้าไปในถิ่นทุรกันดารขึ้นไปจากเยรีโคเข้าไปในแดนเทือกเขาเบธเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 2, 'จากเมืองเบธเอลไปยังเมืองลูส ผ่านเรื่อยไปถึงเมืองอาทาโรท ยังเขตของคนอารคี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 3, 'แล้วลงไปทางทิศตะวันตกถึงเขตของคนยาฟเลที ไกลไปจนเขตเมืองเบธโฮโรนล่างถึงเมืองเกเซอร์ไปสิ้นสุดลงที่ทะเล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 4, 'ลูกหลานของโยเซฟ คือคนมนัสเสห์และคนเอฟราอิม ได้รับมรดกของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 5, 'เขตของคนเอฟราอิมตามครอบครัวของเขาเป็นดังนี้ พรมแดนมรดกของเขาด้านตะวันออก เริ่มแต่เมืองอาทาโรทอัดดาร์ ไกลไปจนถึงเบธโฮโรนบน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 6, 'และพรมแดนยื่นไปถึงทะเลทางทิศเหนือคือเมืองมิคเมธัท ทางด้านตะวันออกพรมแดนโค้งมาหาเมืองทาอานัทชีโลห์ แล้วผ่านพ้นเมืองนี้ไปทางตะวันออกของเมืองยาโนอาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 7, 'แล้วลงไปจากยาโนอาห์ ถึงเมืองอาทาโรทและเมืองนาอาราห์ ไปจดเมืองเยรีโคสิ้นสุดลงที่แม่น้ําจอร์แดน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 8, 'จากทัปปูวาห์พรมแดนลงไปทางทิศตะวันตกถึงแม่น้ําคานาห์ไปสิ้นสุดลงที่ทะเล นี่เป็นดินแดนมรดกของตระกูลคนเอฟราอิมตามครอบครัวของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 9, 'รวมทั้งหัวเมืองซึ่งแบ่งแยกไว้ให้คนเอฟราอิมในดินแดนมรดกของคนมนัสเสห์ คือบรรดาหัวเมืองเหล่านั้นกับชนบทของเมืองนั้นๆด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 10, 'ถึงอย่างไรก็ตามเขาหาได้ขับไล่คนคานาอันซึ่งอาศัยอยู่ในเมืองเกเซอร์ให้ออกไปไม่ ดังนั้นคนคานาอันจึงอาศัยอยู่ในหมู่คนเอฟราอิมถึงทุกวันนี้ แต่ก็ตกเป็นทาสถูกเกณฑ์ให้ทํางานโยธา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 1, 'ที่ดินตามฉลากเป็นอย่างนี้ที่ตกแก่ตระกูลมนัสเสห์ เพราะเป็นบุตรหัวปีของโยเซฟ ส่วนมาคีร์บุตรหัวปีของมนัสเสห์ บิดาของกิเลอาด ได้รับเมืองกิเลอาดและเมืองบาชานเป็นส่วนแบ่ง เพราะว่าเขาเป็นทหาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 2, 'และที่ดินตามฉลากตกแก่คนมนัสเสห์ที่เหลืออยู่ตามครอบครัว คือคนอาบีเยเซอร์ คนเฮเลค คนอัสรีเอล คนเชเคม คนเฮเฟอร์ และคนเชมิดา บุคคลเหล่านี้เป็นบุตรชายของมนัสเสห์ ผู้เป็นบุตรชายของโยเซฟ ตามครอบครัวของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 3, 'ฝ่ายเศโลเฟหัดบุตรชายของเฮเฟอร์ บุตรชายของกิเลอาด บุตรชายของมาคีร์ บุตรชายของมนัสเสห์ไม่มีบุตรผู้ชาย มีแต่บุตรสาว และต่อไปนี้เป็นชื่อบุตรสาวของเขาคือ มาลาห์ โนอาห์ โฮกลาห์ มิลคาห์ และทีรซาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 4, 'เขาเข้ามาหาเอเลอาซาร์ปุโรหิตและโยชูวาบุตรชายนูนและต่อหน้าบรรดาประมุขแล้วกล่าวว่า “พระเยโฮวาห์ได้ทรงบัญชาโมเสสไว้ว่า ให้ข้าพเจ้าทั้งหลายรับส่วนมรดกในหมู่ญาติพี่น้องของข้าพเจ้าทั้งหลายได้” ดังนั้นท่านจึงให้มรดกแก่คนเหล่านี้ในหมู่พี่น้องของบิดาของเขา ตามพระบัญญัติแห่งพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 5, 'ดังนี้แหละส่วนที่ตกแก่คนมนัสเสห์จึงมีสิบส่วน นอกเหนือดินแดนกิเลอาดและบาชานซึ่งอยู่ฟากแม่น้ําจอร์แดนข้างโน้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 6, 'เพราะว่าบุตรสาวของมนัสเสห์ก็ได้รับมรดกพร้อมกับบุตรชายของท่านด้วย แผ่นดินกิเลอาดนั้นได้ตกเป็นส่วนของบุตรชายมนัสเสห์ที่เหลืออยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 7, 'เขตแดนของมนัสเสห์ตั้งต้นจากอาเชอร์จนถึงมิคเมธัท ซึ่งอยู่ทางทิศตะวันออกของเมืองเชเคมแล้ว พรมแดนก็ยื่นไปทางมือขวาถึงที่ของชาวเมืองเอนทัปปูวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 8, 'แผ่นดินเมืองทัปปูวาห์เป็นของมนัสเสห์ แต่ตัวเมืองทัปปูวาห์ซึ่งอยู่ที่พรมแดนของมนัสเสห์นั้นเป็นของคนเอฟราอิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 9, 'แล้วพรมแดนก็ลงไปถึงแม่น้ําคานาห์ หัวเมืองเหล่านี้ซึ่งอยู่ทางทิศใต้แม่น้ําในท่ามกลางหัวเมืองของมนัสเสห์นั้นเป็นของเอฟราอิม แล้วพรมแดนของมนัสเสห์ก็ขึ้นไปทางด้านเหนือของแม่น้ําไปสิ้นสุดลงที่ทะเล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 10, 'แผ่นดินทางด้านใต้เป็นของเอฟราอิม และแผ่นดินทางด้านเหนือเป็นของมนัสเสห์ มีทะเลเป็นพรมแดน ทางเหนือจดดินแดนอาเชอร์ และทางทิศตะวันออกจดอิสสาคาร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 11, 'ในเขตอิสสาคาร์และในอาเชอร์นั้น มนัสเสห์ยังมีเมืองเบธชานกับชนบทของเมืองนั้น และเมืองอิบเลอัมกับชนบทของเมืองนั้น และชาวเมืองโดร์กับชนบทของเมืองนั้น และชาวเมืองเอนโดร์กับชนบทของเมืองนั้น และชาวเมืองทาอานาคกับชนบทของเมืองนั้น และชาวเมืองเมกิดโดกับชนบทของเมืองนั้น คือภูเขาทั้งสามยอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 12, 'แต่คนมนัสเสห์ยังขับไล่ชาวเมืองเหล่านั้นไม่ได้ ด้วยคนคานาอันยังขืนอาศัยอยู่ในแผ่นดินนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 13, 'ต่อมาเมื่อคนอิสราเอลเข้มแข็งขึ้นแล้ว ก็ได้เกณฑ์คนคานาอันให้ทํางานโยธา และมิได้ขับไล่ให้เขาออกไปเสียทีเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 14, 'คนโยเซฟได้พูดกับโยชูวาว่า “เหตุไฉนท่านจึงแบ่งให้ข้าพเจ้ามีแต่ส่วนเดียวเป็นมรดก แม้ว่าข้าพเจ้ามีคนมากมาย เพราะว่าพระเยโฮวาห์ได้ทรงอวยพระพรแก่พวกข้าพเจ้ามาจนบัดนี้แล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 15, 'ฝ่ายโยชูวาตอบเขาว่า “ถ้าเจ้ามีคนมากมาย และถ้าแดนเทือกเขาของคนเอฟราอิมเป็นที่แคบไปสําหรับเจ้า พวกเจ้าจงเข้าไปในป่าแผ้วถางเอาเอง ที่ในแผ่นดินของคนเปริสซีและพวกมนุษย์ยักษ์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 16, 'คนโยเซฟพูดว่า “แดนเทือกเขานี้ไม่พอสําหรับพวกเรา บรรดาคนคานาอันซึ่งอยู่ในบริเวณหุบเขามีรถรบทําด้วยเหล็ก ทั้งที่อยู่ในเบธชานกับชนบทของเมืองนั้น กับที่อยู่ในหุบเขายิสเรเอล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 17, 'แล้วโยชูวาจึงกล่าวแก่วงศ์วานโยเซฟ คือเอฟราอิมและมนัสเสห์ว่า “ท่านทั้งหลายเป็นพวกที่มีคนมากและมีกําลังมหาศาล ท่านจะมีส่วนแบ่งแต่ส่วนเดียวก็หามิได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 18, 'แดนเทือกเขาเหล่านั้นจะเป็นของพวกท่าน ถึงแม้ว่าเป็นป่าดอนท่านจงแผ้วถางและยึดครองไปจนสุดเขตเถิด แม้ว่าคนคานาอันจะมีรถรบทําด้วยเหล็กและเป็นคนเข้มแข็ง ท่านทั้งหลายก็จะขับไล่เขาออกไปได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 1, 'ฝ่ายชุมนุมชนอิสราเอลทั้งสิ้นก็มาประชุมกันที่ชีโลห์ และตั้งพลับพลาแห่งชุมนุมขึ้นที่นั่น แผ่นดินนั้นก็ตกอยู่ในการครอบครองของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 2, 'ยังมีประชาชนอิสราเอลอีกเจ็ดตระกูลที่ยังมิได้รับมรดกเป็นส่วนแบ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 3, 'ดังนั้นโยชูวาจึงกล่าวแก่คนอิสราเอลว่า “ท่านทั้งหลายจะรอช้าอยู่อีกเท่าใด จึงจะเข้าไปยึดครองที่ดินซึ่งพระเยโฮวาห์พระเจ้าของบรรพบุรุษของท่านประทานแก่ท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 4, 'จงเลือกคนตระกูลละสามคน แล้วข้าพเจ้าจะใช้คนเหล่านั้นไปท่องเที่ยวขึ้นล่องอยู่ที่แผ่นดินนั้น ให้เขียนแนวเขตที่ดินที่จะมอบเป็นมรดก และกลับมาหาข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 5, 'ให้เขาแบ่งออกเป็นเจ็ดส่วน ให้คนยูดาห์คงอยู่ในดินแดนของเขาทางภาคใต้ และวงศ์วานโยเซฟให้คงอยู่ในดินแดนของเขาทางภาคเหนือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 6, 'ให้ท่านทั้งหลายเขียนแนวเขตที่ดินเป็นเจ็ดส่วน แล้วนําแนวเขตที่ดินนั้นมาให้ข้าพเจ้าที่นี่ และข้าพเจ้าจะจับฉลากให้ท่านที่นี่ ต่อพระพักตร์พระเยโฮวาห์พระเจ้าของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 7, 'แต่คนเลวีไม่มีส่วนแบ่งในหมู่พวกท่านทั้งหลาย ด้วยตําแหน่งปุโรหิตของพระเยโฮวาห์เป็นมรดกของเขาแล้ว คนกาด และคนรูเบน กับตระกูลมนัสเสห์ครึ่งหนึ่งก็ได้รับมรดกของเขาทางฟากแม่น้ําจอร์แดนข้างโน้นด้านตะวันออก ซึ่งโมเสสผู้รับใช้ของพระเยโฮวาห์ได้มอบให้แก่เขาทั้งหลายแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 8, 'ฝ่ายคนเหล่านั้นก็ขึ้นออกไปเดินทาง และโยชูวากําชับพวกที่จะเขียนแนวเขตที่ดินว่า “จงเที่ยวขึ้นเที่ยวล่องในแผ่นดิน และเขียนแนวเขตที่ดินนั้นแล้วกลับมาหาข้าพเจ้า ข้าพเจ้าจะจับฉลากให้ท่านต่อพระพักตร์พระเยโฮวาห์ที่ชีโลห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 9, 'ดังนั้นคนเหล่านั้นก็ท่องเที่ยวไปมาที่แผ่นดิน แล้วเขียนเป็นหนังสือแนวเขตเมืองต่างๆแบ่งเป็นเจ็ดส่วนแล้วกลับมาหาโยชูวา ณ ค่ายที่ชีโลห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 10, 'แล้วโยชูวาก็จับฉลากให้เขาที่ชีโลห์ต่อพระพักตร์พระเยโฮวาห์ โยชูวาก็ได้จัดแบ่งที่ดินให้แก่ประชาชนอิสราเอลที่นั่นตามส่วนแบ่งของแต่ละตระกูล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 11, 'จับได้ฉลากของตระกูลคนเบนยามินตามครอบครัวของเขาขึ้นมา และอาณาเขตที่เป็นส่วนของเขาอยู่ระหว่างคนยูดาห์ และคนโยเซฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 12, 'ทางด้านเหนือพรมแดนของเขาเริ่มต้นที่แม่น้ําจอร์แดน และพรมแดนก็ยื่นขึ้นไปถึงไหล่เขาตอนเหนือของเมืองเยรีโค แล้วขึ้นไปทางแดนเทือกเขาทางทิศตะวันตก และไปสิ้นสุดที่ถิ่นทุรกันดารเบธาเวน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 13, 'จากที่นั่นพรมแดนก็ยื่นไปทางทิศใต้ตรงไปเมืองลูสไปยังไหล่เขาที่เมืองลูส คือเมืองเบธเอล แล้วพรมแดนก็ลงไปถึงอาทาโรทอัดดาร์บนภูเขาซึ่งอยู่ทางทิศใต้ของเมืองเบธโฮโรนล่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 14, 'แล้วพรมแดนก็ยื่นไปอีกทิศหนึ่งโค้งไปทางทิศใต้ด้านทะเล จากภูเขาซึ่งอยู่ทิศใต้ตรงข้ามเมืองเบธโฮโรน และไปสิ้นสุดลงที่คีริยาทบาอัล คือคีริยาทเยอาริม เป็นเมืองที่เป็นของคนยูดาห์ นี่แหละเป็นพรมแดนด้านตะวันตก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 15, 'และด้านใต้นั้นเริ่มต้นที่ชานเมืองคีริยาทเยอาริม และพรมแดนก็ยื่นจากที่นั่นไปยังทางตะวันตกถึงน้ําพุเนฟโทอาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 16, 'แล้วพรมแดนก็ยื่นลงไปสุดเขตภูเขาซึ่งอยู่ตรงหน้าหุบเขาแห่งบุตรชายของฮินโนม ซึ่งอยู่ทางปลายเหนือสุดของหุบเขาแห่งพวกมนุษย์ยักษ์ แล้วก็ลงไปที่หุบเขาฮินโนมใต้ไหล่เขาของคนเยบุสแล้วลงไปถึงเมืองเอนโรเกล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 17, 'แล้วโค้งไปทางทิศเหนือตรงไปถึงเอนเชเมช จากที่นั่นก็ตรงไปยังเกลีโลท ซึ่งอยู่ตรงข้ามกับทางข้ามเขาชื่ออดุมมิม แล้วลงไปยังก้อนหินโบฮันบุตรชายของรูเบน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 18, 'แล้วผ่านไปทางทิศเหนือถึงไหล่เขาตรงข้ามอาราบาห์แล้วลงไปสู่อาราบาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 19, 'แล้วพรมแดนก็ผ่านไปทางทิศเหนือถึงไหล่เขาที่เบธฮกลาห์ และพรมแดนไปสิ้นสุดลงที่อ่าวด้านเหนือของทะเลเค็มที่ปลายใต้ของแม่น้ําจอร์แดน นี่เป็นพรมแดนด้านใต้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 20, 'แม่น้ําจอร์แดนกั้นเป็นพรมแดนทางตะวันออก นี่เป็นมรดกของคนเบนยามินตามครอบครัวของเขา มีพรมแดนดังนี้ล้อมรอบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 21, 'ฝ่ายหัวเมืองของตระกูลคนเบนยามินตามครอบครัวของเขา คือเมืองเยรีโค เบธฮกลาห์ หุบเขาเคซีส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 22, 'เบธอาราบาห์ เศมาราอิม เบธเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 23, 'อัฟวิม ปาราห์ โอฟราห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 24, 'เคฟารัมโมนี โอฟนี เกบา รวมเป็นสิบสองหัวเมืองกับชนบทของเมืองนั้นๆด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 25, 'กิเบโอน รามาห์ เบเอโรท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 26, 'มิสเปห์ เคฟีราห์ โมซาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 27, 'เรเคม อิรเปเอล ทาระลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 28, 'เศลา เอเลฟ เยบุส คือเยรูซาเล็ม กิเบอัทและคีริยาท รวมเป็นสิบสี่หัวเมืองกับชนบทของเมืองนั้นๆด้วย นี่เป็นมรดกของคนเบนยามินตามครอบครัวของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 1, 'ฉลากที่สองออกมาเป็นของสิเมโอน เพื่อคนตระกูลสิเมโอนตามครอบครัวของเขา มรดกของเขาอยู่ท่ามกลางมรดกของคนยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 2, 'มีเมืองเหล่านี้เป็นมรดก คือเบเออร์เชบา เชบา โมลาดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 3, 'ฮาซารชูอาล บาลาห์ เอเซม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 4, 'เอลโทลัด เบธูล โฮรมาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 5, 'ศิกลาก เบธมารคาโบท ฮาซารสูสาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 6, 'เบธเลบาโอท และเมืองชารุเฮน รวมเป็นสิบสามหัวเมืองกับชนบทของเมืองนั้นๆด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 7, 'อายิน ริมโมน เอเธอร์ อาชัน รวมเป็นสี่หัวเมืองกับชนบทของเมืองนั้นๆด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 8, 'รวมทั้งบรรดาชนบทที่อยู่รอบหัวเมืองเหล่านี้ไกลออกไปจนถึงเมืองบาอาลัทเบเออร์ เมืองรามาห์ที่ภาคใต้ เหล่านี้เป็นมรดกของตระกูลคนสิเมโอนตามครอบครัวของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 9, 'มรดกของคนสิเมโอนเป็นดินแดนในส่วนแบ่งของคนยูดาห์ เพราะว่าส่วนของคนยูดาห์นั้นใหญ่เกินไป คนสิเมโอนจึงได้รับมรดกอยู่ท่ามกลางมรดกของคนยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 10, 'ฉลากที่สามขึ้นมาเป็นของคนเศบูลุนตามครอบครัวของเขา และอาณาเขตที่เป็นมรดกของเขาก็ยื่นออกไปถึงสาริด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 11, 'แล้วพรมแดนของเขายื่นออกไปทางด้านทะเล เรื่อยไปจนถึงมาราลาห์ และมาจดเมืองดับเบเชท แล้วมาถึงแม่น้ําที่อยู่ตรงหน้าโยกเนอัม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 12, 'จากสาริดพรมแดนยื่นไปอีกทิศหนึ่งทางด้านตะวันออกตรงทางดวงอาทิตย์ขึ้น ถึงพรมแดนเมืองคิสโลททาโบร์ แล้วยื่นไปถึงเมืองดาเบรัท แล้วขึ้นไปถึงเมืองยาเฟีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 13, 'จากที่นั่นพรมแดนผ่านไปทางตะวันออกถึงเมืองกัธเฮเฟอร์ และถึงเมืองเอทคาซิน เรื่อยไปจนถึงริมโมนมิโทอาร์ พรมแดนก็ไปถึงเมืองเนอาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 14, 'และทางทิศเหนือพรมแดนโค้งเข้ามาถึงเมืองฮันนาโธน และสิ้นสุดลงที่หุบเขายิฟทาห์เอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 15, 'และเมืองขัทตาท นาหะลาล ชิมโรน อิดาลาห์ และเมืองเบธเลเฮม รวมเป็นสิบสองหัวเมืองกับชนบทของเมืองนั้นๆด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 16, 'นี่เป็นมรดกของคนเศบูลุนตามครอบครัวของเขา คือหัวเมืองต่างๆกับชนบทของเมืองนั้นๆด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 17, 'ฉลากที่สี่ออกมาเป็นของอิสสาคาร์ เพื่อคนอิสสาคาร์ตามครอบครัวของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 18, 'อาณาเขตของเขารวมเมืองยิสเรเอล เคสุลโลท ชูเนม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 19, 'ฮาฟาราอิม ชิโยน อานาหะราท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 20, 'รับบีท คีชิโอน เอเบส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 21, 'เรเมท เอนกันนิม เอนหัดดาห์ เบธปัสเซส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 22, 'และพรมแดนยังจดเมืองทาโบร์ ชาหะซุมาห์ เบธเชเมช และพรมแดนนี้ไปสิ้นสุดลงที่แม่น้ําจอร์แดน รวมเป็นสิบหกหัวเมืองกับชนบทของเมืองนั้นๆด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 23, 'นี่เป็นมรดกของตระกูลคนอิสสาคาร์ตามครอบครัวของเขา คือทั้งหัวเมืองและชนบทของเมืองนั้นๆด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 24, 'ฉลากที่ห้าออกมาเป็นของตระกูลคนอาเชอร์ตามครอบครัวของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 25, 'อาณาเขตของเขารวมเมืองเฮลขัท ฮาลี เบเทน อัคชาฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 26, 'อาลัมเมเลค อามาด มิชอาล ทางทิศตะวันออกจดคารเมล และเมืองชิโหลิบนาท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 27, 'แล้วเลี้ยวไปทางดวงอาทิตย์ขึ้นไปยังเบธดาโกนจดเขตเศบูลุนและหุบเขายิฟทาห์เอล ไปทางด้านเหนือถึงเมืองเบธเอเมคและเนอีเอลเรื่อยไปทางด้านซ้ายถึงเมืองคาบูล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 28, 'เฮโบรน เรโหบ ฮัมโมน คานาห์ ไกลไปถึงมหาไซดอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 29, 'แล้วพรมแดนก็เลี้ยวไปถึงรามาห์ ไปถึงเมืองที่มีกําแพงล้อมรอบชื่อไทระ แล้วพรมแดนก็เลี้ยวไปถึงเมืองโฮสาห์ไปสิ้นสุดลงที่ทะเล จากฝั่งทะเลไปถึงอัคซีบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 30, 'อุมมาห์ อาเฟก และเรโหบ รวมเป็นยี่สิบสองหัวเมืองกับชนบทของเมืองนั้นๆด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 31, 'นี่เป็นมรดกของตระกูลคนอาเชอร์ตามครอบครัวของเขา ทั้งหัวเมืองกับชนบทของเมืองนั้นๆด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 32, 'ฉลากที่หกออกมาเป็นของคนนัฟทาลี เพื่อคนนัฟทาลีตามครอบครัวของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 33, 'อาณาเขตของเขาเริ่มจากเฮเลฟ จากอาโลนไปถึงศานันนิม และอาดามี เนเขบ และยับเนเอลไกลไปจนถึงเมืองลัคคูม และสิ้นสุดลงที่แม่น้ําจอร์แดน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 34, 'แล้วพรมแดนก็เลี้ยวไปทางด้านตะวันตกถึงเมืองอัสโนททาโบร์ จากที่นั่นไปถึงหุกกอกจดเขตเศบูลุนทางทิศใต้ และเขตอาเชอร์ทางทิศตะวันตก และเขตยูดาห์ทางดวงอาทิตย์ขึ้นที่แม่น้ําจอร์แดน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 35, 'เมืองที่มีกําแพงล้อมคือเมืองศิดดิม เศอร์ ฮัมมัท รัคคัท คินเนเรท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 36, 'อาดามาห์ รามาห์ ฮาโซร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 37, 'เคเดช เอเดรอี เอนฮาโซร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 38, 'ยิโรน มิกดัลเอล โฮเรม เบธานาท และเบธเชเมช รวมเป็นสิบเก้าหัวเมืองกับชนบทของเมืองนั้นๆด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 39, 'นี่เป็นมรดกของตระกูลคนนัฟทาลีตามครอบครัวของเขา ทั้งหัวเมืองกับชนบทของเมืองนั้นๆด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 40, 'ฉลากที่เจ็ดก็ออกมาเป็นของตระกูลคนดานตามครอบครัวของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 41, 'และอาณาเขตที่เป็นมรดกของเขา รวมเมืองโศราห์ เอชทาโอล อิรเชเมช');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 42, 'ชาอาลับบิน อัยยาโลน ยิทลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 43, 'เอโลน ทิมนาห์ เอโครน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 44, 'เอลเทเคห์ กิบเบโธน และบาอาลัท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 45, 'เยฮุด เบเนเบราค กัทริมโมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 46, 'เมยารโคน และรัคโคนและพรมแดนตรงเมืองยัฟฟา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 47, 'อาณาเขตคนดานน้อยไปสําหรับพวกเขา คนดานจึงขึ้นไปสู้รบกับเมืองเลเชม เมื่อยึดได้ก็ประหารเสียด้วยคมดาบ จึงยึดครองที่ดินและตั้งอยู่ที่นั่น เรียกเมืองเลเชมว่าดาน ตามชื่อของดานบรรพบุรุษของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 48, 'นี่เป็นมรดกของตระกูลคนดานตามครอบครัวของเขา ทั้งหัวเมืองกับชนบทของเมืองนั้นๆด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 49, 'เมื่อได้แบ่งดินแดนส่วนต่างๆของแผ่นดินนั้นเป็นมรดกเสร็จสิ้นแล้ว คนอิสราเอลก็ได้มอบส่วนมรดกในหมู่พวกเขาให้แก่โยชูวาบุตรชายนูน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 50, 'ตามบัญชาของพระเยโฮวาห์เขาก็ได้ยกเมืองที่ท่านขอไว้ให้แก่ท่าน คือเมืองทิมนาทเสราห์ในแดนเทือกเขาแห่งเอฟราอิม ท่านก็เสริมสร้างเมืองนั้นเสียใหม่และเข้าอยู่ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 51, 'ที่กล่าวมานี้เป็นมรดกที่เอเลอาซาร์ปุโรหิตกับโยชูวาบุตรชายนูน และหัวหน้าบรรพบุรุษของตระกูลต่างๆแห่งคนอิสราเอลจับฉลากแบ่งให้เป็นมรดกที่ชีโลห์ต่อพระพักตร์พระเยโฮวาห์ ณ ประตูพลับพลาแห่งชุมนุม ดังนี้แหละเขาทั้งหลายก็ทําการแบ่งปันแผ่นดินสําเร็จลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 1, 'แล้วพระเยโฮวาห์ตรัสกับโยชูวาว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 2, '“จงกล่าวแก่คนอิสราเอลว่า ‘จงกําหนดตั้งเมืองลี้ภัย ซึ่งเราได้พูดกับเจ้าทั้งหลายทางโมเสสแล้วนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 3, 'เพื่อว่าผู้ฆ่าคนที่ได้ฆ่าคนใดโดยมิได้เจตนาหรือไม่จงใจจะได้หนีไปอยู่ที่นั่น เมืองเหล่านี้จะได้เป็นที่ลี้ภัยของเจ้าเพื่อให้พ้นจากผู้อาฆาตโลหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 4, 'ให้ผู้นั้นหนีไปยังเมืองเหล่านี้เมืองใดเมืองหนึ่ง และยืนอยู่ที่ทางเข้าประตูเมืองนั้น และอธิบายเรื่องของตนให้แก่พวกผู้ใหญ่ในเมืองนั้นให้ทราบ แล้วเขาทั้งหลายจะนําผู้นั้นเข้าไปในเมือง กําหนดที่ให้อยู่แล้วผู้นั้นจะอยู่ที่นั่นในหมู่พวกเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 5, 'และถ้าผู้อาฆาตโลหิตไล่ตามเขาไป ผู้ใหญ่จะไม่มอบผู้ฆ่าคนนั้นไว้ในมือของผู้อาฆาตโลหิต เพราะว่าผู้นั้นได้ฆ่าเพื่อนบ้านของตนโดยไม่มีเจตนา มิได้เกลียดชังเขาแต่ก่อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 6, 'และผู้นั้นจะอาศัยอยู่ในเมืองนั้นจนกว่าเขาจะยืนต่อหน้าชุมนุมชนเพื่อรอรับการพิพากษา จนกว่ามหาปุโรหิตในเวลานั้นสิ้นชีวิต ผู้ฆ่าคนนั้นจึงจะกลับไปยังเมืองของตน ไปบ้านของตน ไปยังเมืองที่เขาจากมานั้นได้’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 7, 'ดังนั้นเขาจึงกําหนดตั้งเมืองเคเดชในกาลิลีในแดนเทือกเขานัฟทาลี และเมืองเชเคมในแดนเทือกเขาของเอฟราอิม และคีริยาทอารบา คือเฮโบรน ในแดนเทือกเขายูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 8, 'และทางฟากตะวันออกของแม่น้ําจอร์แดนข้างโน้นตรงเมืองเยรีโคนั้น เขาได้กําหนดเมืองเบเซอร์ในถิ่นทุรกันดารบนที่ราบจากที่ดินคนตระกูลรูเบน และเมืองราโมทในกิเลอาดจากที่ดินคนตระกูลกาด และเมืองโกลานในบาชานจากที่ดินคนตระกูลมนัสเสห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 9, 'หัวเมืองเหล่านี้เป็นเมืองที่กําหนดไว้ให้คนอิสราเอลทั้งหมด และให้คนต่างด้าวผู้อาศัยอยู่ในหมู่พวกเขา เพื่อว่าถ้าผู้ใดได้ฆ่าคนโดยมิได้เจตนาจะได้หนีไปที่นั่นได้ เพื่อว่าเขาจะไม่ต้องตายด้วยมือของผู้อาฆาตโลหิต จนกว่าเขาจะได้ยืนต่อหน้าชุมนุมชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 1, 'ขณะนั้นหัวหน้าบรรพบุรุษของคนเลวีมาหาเอเลอาซาร์ปุโรหิตและโยชูวาบุตรชายนูน และหัวหน้าบรรพบุรุษของตระกูลต่างๆของคนอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 2, 'และเขาได้กล่าวแก่ท่านเหล่านั้นในเมืองชีโลห์ในแผ่นดินคานาอันว่า “พระเยโฮวาห์ทรงบัญชาโดยทางโมเสสว่า ให้มอบหัวเมืองแก่เราทั้งหลายเพื่อจะได้อาศัยอยู่ ทั้งทุ่งหญ้าสําหรับฝูงสัตว์ของข้าพเจ้าทั้งหลาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 3, 'ดังนั้นแหละตามพระบัญชาของพระเยโฮวาห์ คนอิสราเอลจึงได้มอบเมืองและทุ่งหญ้าต่อไปนี้จากมรดกของเขาให้แก่คนเลวี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 4, 'ฉลากออกมาเป็นของครอบครัวคนโคฮาท ดังนั้นแหละ คนเลวีซึ่งเป็นลูกหลานของอาโรนปุโรหิต ได้รับหัวเมืองโดยจับฉลากสิบสามหัวเมือง จากตระกูลยูดาห์ ตระกูลสิเมโอน และตระกูลเบนยามิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 5, 'ส่วนคนโคฮาทที่เหลืออยู่ ได้รับหัวเมืองโดยจับฉลากสิบหัวเมือง จากครอบครัวของตระกูลเอฟราอิม จากตระกูลดาน และจากครึ่งตระกูลมนัสเสห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 6, 'คนเกอร์โชนได้รับหัวเมืองโดยจับฉลากสิบสามหัวเมือง จากครอบครัวของตระกูลอิสสาคาร์ จากตระกูลอาเชอร์ จากตระกูลนัฟทาลี และจากครึ่งตระกูลมนัสเสห์ในบาชาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 7, 'คนเมรารีตามครอบครัวของเขา ได้รับหัวเมืองสิบสองหัวเมือง จากตระกูลรูเบน ตระกูลกาด และตระกูลเศบูลุน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 8, 'หัวเมืองและทุ่งหญ้าเหล่านี้คนอิสราเอลได้จับฉลากให้แก่คนเลวีดังที่พระเยโฮวาห์ได้บัญชาโดยทางโมเสส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 9, 'เขาให้หัวเมืองต่อไปนี้จากตระกูลยูดาห์และตระกูลสิเมโอน ตามชื่อดังนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 10, 'เมืองเหล่านี้ตกเป็นของคนอาโรนคือ ครอบครัวโคฮาทครอบครัวหนึ่งซึ่งเป็นคนเลวีเพราะฉลากตกเป็นของเขาก่อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 11, 'เขาทั้งหลายให้เมืองอารบาแก่เขา อารบาเป็นบิดาของอานาค คือเมืองเฮโบรน อยู่ในแดนเทือกเขาของยูดาห์ รวมทั้งทุ่งหญ้ารอบเมืองนั้นด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 12, 'แต่ทุ่งนาและชนบทของเมืองนี้ได้ยกให้แก่คาเลบบุตรชายเยฟุนเนห์เป็นกรรมสิทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 13, 'เขาได้ให้เมืองเฮโบรนแก่ลูกหลานของอาโรนปุโรหิต อันเป็นเมืองลี้ภัยสําหรับผู้ฆ่าคนพร้อมทั้งทุ่งหญ้ารอบเมือง เมืองลิบนาห์พร้อมทุ่งหญ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 14, 'เมืองยาททีร์พร้อมทุ่งหญ้า เมืองเอชเทโมอาพร้อมทุ่งหญ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 15, 'เมืองโฮโลนพร้อมทุ่งหญ้า เมืองเดบีร์พร้อมทุ่งหญ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 16, 'เมืองอายินพร้อมทุ่งหญ้า เมืองยุทธาห์พร้อมทุ่งหญ้า เมืองเบธเชเมชพร้อมทุ่งหญ้า รวมเป็นเก้าหัวเมืองจากสองตระกูลนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 17, 'จากตระกูลเบนยามิน มีเมืองกิเบโอนพร้อมทุ่งหญ้า เมืองเกบาพร้อมทุ่งหญ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 18, 'เมืองอานาโธทพร้อมทุ่งหญ้า เมืองอัลโมนพร้อมทุ่งหญ้า รวมสี่หัวเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 19, 'หัวเมืองที่เป็นของลูกหลานอาโรนปุโรหิต รวมกันสิบสามหัวเมือง พร้อมกับทุ่งหญ้ารอบทุกเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 20, 'ส่วนคนโคฮาทที่เหลืออยู่ซึ่งเป็นครอบครัวคนโคฮาทของคนเลวีนั้น หัวเมืองที่เขาได้รับโดยฉลากมาจากตระกูลเอฟราอิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 21, 'เมืองที่เขาให้ คือเมืองเชเคม เป็นเมืองลี้ภัยของผู้ฆ่าคนพร้อมทุ่งหญ้าในแดนเทือกเขาของเอฟราอิม เมืองเกเซอร์พร้อมทุ่งหญ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 22, 'เมืองขิบซาอิมพร้อมทุ่งหญ้า เมืองเบธโฮโรนพร้อมทุ่งหญ้า รวมเป็นสี่หัวเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 23, 'และจากตระกูลดาน มีเมืองเอลเทเคห์พร้อมทุ่งหญ้า กิบเบโธนพร้อมทุ่งหญ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 24, 'อัยยาโลนพร้อมทุ่งหญ้า กัทริมโมนพร้อมทุ่งหญ้า รวมสี่หัวเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 25, 'และจากคนมนัสเสห์ครึ่งตระกูล มีเมืองทาอานาคพร้อมทุ่งหญ้า และกัทริมโมนพร้อมทุ่งหญ้า รวมเป็นสองหัวเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 26, 'หัวเมืองซึ่งเป็นของครอบครัวคนโคฮาทที่เหลืออยู่นั้น มีสิบหัวเมืองด้วยกัน พร้อมกับทุ่งหญ้ารอบทุกเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 27, 'เขาให้เมืองจากคนมนัสเสห์ครึ่งตระกูลแก่คนเกอร์โชน ครอบครัวหนึ่งของคนเลวี คือเมืองโกลานในบาชาน เป็นเมืองลี้ภัยของผู้ฆ่าคน พร้อมทุ่งหญ้า และเมืองเบเอชเท-ราห์พร้อมทุ่งหญ้า รวมเป็นสองหัวเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 28, 'และจากตระกูลอิสสาคาร์ มีเมืองคีชิโอนพร้อมทุ่งหญ้า ดาเบรัทพร้อมทุ่งหญ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 29, 'เมืองยารมูทพร้อมทุ่งหญ้า เอนกันนิมพร้อมทุ่งหญ้า รวมสี่หัวเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 30, 'และจากตระกูลอาเชอร์ มีเมืองมิชอาลพร้อมทุ่งหญ้า อับโดนพร้อมทุ่งหญ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 31, 'เมืองเฮลขัทพร้อมทุ่งหญ้า เมืองเรโหบพร้อมทุ่งหญ้า รวมสี่หัวเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 32, 'และจากตระกูลนัฟทาลี เมืองเคเดชในกาลิลี เป็นเมืองลี้ภัยของผู้ฆ่าคน พร้อมทุ่งหญ้า เมืองฮัมโมทโดร์พร้อมทุ่งหญ้า และเมืองคารทานพร้อมทุ่งหญ้า รวมสามหัวเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 33, 'หัวเมืองที่เป็นของคนเกอร์โชนตามครอบครัวนั้น รวมกันมีสิบสามหัวเมืองพร้อมกับทุ่งหญ้ารอบทุกเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 34, 'เขาให้หัวเมืองจากตระกูลเศบูลุนแก่ครอบครัวคนเมรารี คือคนเลวีที่เหลืออยู่ มีเมืองโยกเนอัมพร้อมทุ่งหญ้า เมืองคารทาห์พร้อมทุ่งหญ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 35, 'เมืองดิมนาห์พร้อมทุ่งหญ้า เมืองนาหะลาลพร้อมทุ่งหญ้า รวมสี่หัวเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 36, 'และจากตระกูลรูเบน มีเมืองเบเซอร์พร้อมทุ่งหญ้า เมืองยาฮาสพร้อมทุ่งหญ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 37, 'เมืองเคเดโมทพร้อมทุ่งหญ้า เมืองเมฟาอาทพร้อมทุ่งหญ้า รวมสี่หัวเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 38, 'และจากตระกูลกาด มีเมืองราโมทในกิเลอาด เป็นเมืองลี้ภัยของผู้ฆ่าคน พร้อมทุ่งหญ้า เมืองมาหะนาอิมพร้อมทุ่งหญ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 39, 'เมืองเฮชโบนพร้อมทุ่งหญ้า เมืองยาเซอร์พร้อมทุ่งหญ้า รวมทั้งหมดเป็นสี่หัวเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 40, 'เมืองซึ่งเป็นของคนเมรารีตามครอบครัว ซึ่งเป็นครอบครัวคนเลวีที่เหลืออยู่นั้น เมืองที่เป็นส่วนแบ่งของเขาทั้งหมดมีสิบสองหัวเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 41, 'หัวเมืองของคนเลวี ซึ่งอยู่ท่ามกลางกรรมสิทธิ์ของคนอิสราเอลนั้นรวมทั้งหมดมีสี่สิบแปดหัวเมืองพร้อมทุ่งหญ้าประจําเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 42, 'เมืองเหล่านี้แต่ละเมืองมีทุ่งหญ้าล้อมรอบ ทุกเมืองก็มีอย่างนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 43, 'ดังนี้แหละพระเยโฮวาห์ประทานแผ่นดินทั้งสิ้นแก่คนอิสราเอลดังที่พระองค์ทรงปฏิญาณว่าจะให้แก่บรรพบุรุษของเขา เมื่อเขาทั้งหลายยึดแล้วก็เข้าไปตั้งบ้านเมืองอยู่ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 44, 'และพระเยโฮวาห์ประทานให้เขามีความสงบอยู่ทุกด้าน ดังที่พระองค์ทรงปฏิญาณไว้กับบรรพบุรุษของเขา ไม่มีศัตรูสักคนเดียวยืนหยัดต่อสู้เขาได้ พระเยโฮวาห์ทรงมอบศัตรูของเขาให้อยู่ในกํามือของเขาทั้งสิ้นแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 45, 'สรรพสิ่งอันดีทุกอย่างซึ่งพระเยโฮวาห์ทรงตรัสกับวงศ์วานอิสราเอลนั้นก็ไม่ขาดสักสิ่งเดียว สําเร็จทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 1, 'คราวนั้นโยชูวาได้เรียกคนรูเบน คนกาด คนมนัสเสห์ครึ่งตระกูลมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 2, 'และกล่าวแก่เขาทั้งหลายว่า “ท่านทั้งหลายได้ทําทุกอย่างซึ่งโมเสสผู้รับใช้ของพระเยโฮวาห์บัญชาท่านไว้ และได้เชื่อฟังเสียงของข้าพเจ้าในสารพัดซึ่งข้าพเจ้าได้บัญชาท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 3, 'นานวันแล้วจนบัดนี้ ท่านมิได้ทอดทิ้งญาติพี่น้องของท่าน แต่ได้ระมัดระวังที่จะกระทําตามพระบัญชาของพระเยโฮวาห์พระเจ้าของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 4, 'บัดนี้พระเยโฮวาห์พระเจ้าของท่านได้โปรดให้พี่น้องของท่านหยุดพักแล้ว ดังที่พระองค์ทรงสัญญาไว้กับเขา ฉะนั้นบัดนี้ท่านจงกลับไปสู่เต็นท์ของท่านเถิด ไปสู่แผ่นดินซึ่งท่านถือกรรมสิทธิ์ ซึ่งโมเสสผู้รับใช้ของพระเยโฮวาห์ยกให้ท่านที่ฟากแม่น้ําจอร์แดนข้างโน้นนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 5, 'แต่จงระวังให้มากที่จะปฏิบัติตามพระบัญญัติและพระราชบัญญัติซึ่งโมเสสผู้รับใช้ของพระเยโฮวาห์บัญชาท่านไว้ คือที่จะรักพระเยโฮวาห์พระเจ้าของท่าน และดําเนินในพระมรรคาทั้งสิ้นของพระองค์ และรักษาพระบัญญัติของพระองค์ และติดสนิทอยู่กับพระองค์ และปรนนิบัติพระองค์ด้วยสุดจิตสุดใจของท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 6, 'โยชูวาจึงได้อวยพรเขาและส่งเขากลับไปยังเต็นท์ของเขาทุกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 7, 'ส่วนคนมนัสเสห์ครึ่งตระกูลนั้นโมเสสได้มอบให้เขาถือกรรมสิทธิ์ในเมืองบาชาน แต่อีกครึ่งตระกูลนั้นโยชูวามอบให้เขามีกรรมสิทธิ์ข้างเคียงกับพี่น้องของเขาที่ฟากแม่น้ําจอร์แดนข้างด้านตะวันตกนี้ และเมื่อโยชูวาส่งเขากลับไปยังเต็นท์ของตน ท่านได้อวยพรเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 8, 'กล่าวแก่เขาว่า “จงกลับไปยังเต็นท์ของท่านทั้งหลายพร้อมกับทรัพย์สมบัติมั่งคั่งมีฝูงสัตว์มากมาย มีเงิน ทองคํา ทองเหลือง และเหล็ก และเสื้อผ้าเป็นอันมาก จงแบ่งของที่ริบมาจากศัตรูของท่านให้แก่พี่น้องของท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 9, 'คนรูเบน คนกาดและคนมนัสเสห์ครึ่งตระกูลได้แยกจากคนอิสราเอลที่ชีโลห์ ซึ่งอยู่ในแผ่นดินคานาอันกลับไปอยู่ในแผ่นดินกิเลอาด เป็นแผ่นดินที่เขาถือกรรมสิทธิ์ซึ่งเขาได้เข้าตั้งอยู่ตามพระบัญชาของพระเยโฮวาห์โดยทางโมเสส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 10, 'และเมื่อเขาทั้งหลายมาถึงท้องถิ่นที่ใกล้แม่น้ําจอร์แดนที่อยู่ในแผ่นดินคานาอัน คนรูเบน คนกาด และคนมนัสเสห์ครึ่งตระกูล ได้สร้างแท่นบูชาแท่นหนึ่งที่ใกล้แม่น้ําจอร์แดน เป็นแท่นขนาดมหึมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 11, 'และคนอิสราเอลได้ยินคนพูดกัน “ดูเถิด คนรูเบน คนกาดและคนมนัสเสห์ครึ่งตระกูล ได้สร้างแท่นบูชาที่พรมแดนแผ่นดินคานาอันในท้องถิ่นใกล้แม่น้ําจอร์แดนในด้านที่เป็นของคนอิสราเอล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 12, 'และเมื่อคนอิสราเอลได้ยินเช่นนั้น ชุมนุมชนอิสราเอลทั้งหมดก็ไปรวมกันที่เมืองชีโลห์ เพื่อจะขึ้นไปทําสงครามกับเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 13, 'แล้วคนอิสราเอลจึงใช้ฟีเนหัสบุตรชายเอเลอาซาร์ปุโรหิตไปยังคนรูเบน คนกาด และคนมนัสเสห์ครึ่งตระกูลในแผ่นดินกิเลอาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 14, 'พร้อมกับประมุขสิบคน คนหนึ่งจากแต่ละตระกูลในอิสราเอล ทุกคนเป็นหัวหน้าเรือนบรรพบุรุษในคนอิสราเอลที่นับเป็นพันๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 15, 'เมื่อเขามาถึงคนรูเบน คนกาด และคนมนัสเสห์ครึ่งตระกูลในแผ่นดินกิเลอาด เขาก็กล่าวแก่พวกเหล่านั้นว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 16, '“ชุมนุมชนทั้งสิ้นของพระเยโฮวาห์กล่าวดังนี้ว่า ‘ท่านทั้งหลายได้กระทําการละเมิดอะไรเช่นนี้ต่อพระเจ้าของอิสราเอลหนอ ซึ่งในวันนี้ท่านทั้งหลายได้หันกลับจากติดตามพระเยโฮวาห์ โดยท่านได้สร้างแท่นบูชาสําหรับตัว เป็นการกบฏต่อพระเยโฮวาห์ในวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 17, 'ความชั่วช้าซึ่งเราทําที่เมืองเปโอร์นั้นยังไม่พอเพียงหรือ ซึ่งจนกระทั่งวันนี้เรายังชําระตัวของเราให้สะอาดไม่หมดเลย และซึ่งเป็นเหตุให้ภัยพิบัติเกิดแก่ชุมนุมชนของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 18, 'ในวันนี้ท่านทั้งหลายจะหันไปเสียจากการติดตามพระเยโฮวาห์หรือ ถ้าท่านทั้งหลายกบฏต่อพระเยโฮวาห์ในวันนี้ ในวันพรุ่งนี้พระองค์จะทรงกริ้วต่อชุมนุมชนอิสราเอลทั้งหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 19, 'แต่ถ้าแผ่นดินที่เป็นกรรมสิทธิ์ของท่านไม่สะอาด จงข้ามไปในแผ่นดินที่เป็นกรรมสิทธิ์ของพระเยโฮวาห์ซึ่งเป็นที่ตั้งแห่งพลับพลาของพระเยโฮวาห์ และมาถือกรรมสิทธิ์อยู่ท่ามกลางพวกเราเถิด ขอแต่เพียงอย่ากบฏต่อพระเยโฮวาห์ หรือกบฏต่อเรา โดยที่ท่านทั้งหลายสร้างแท่นบูชาสําหรับตัว นอกจากแท่นบูชาแห่งพระเยโฮวาห์พระเจ้าของเราทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 20, 'อาคานบุตรชายเศ-ราห์ได้กระทําการละเมิดในเรื่องของที่ถูกสาปแช่งนั้นไม่ใช่หรือ พระพิโรธก็ตกเหนือชุมนุมชนอิสราเอลทั้งสิ้น เขามิได้พินาศแต่คนเดียวในเรื่องความชั่วช้าของเขา’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 21, 'ขณะนั้นคนรูเบน คนกาดและคนมนัสเสห์ครึ่งตระกูลได้ตอบผู้หัวหน้าของคนอิสราเอลที่นับเป็นพันๆว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 22, '“พระเยโฮวาห์พระเจ้าของพระทั้งหลาย พระเยโฮวาห์พระเจ้าของพระทั้งหลาย พระองค์ทรงทราบ และอิสราเอลจะทราบเสียด้วย ถ้าว่าเป็นการกบฏหรือละเมิดต่อพระเยโฮวาห์ (ก็ขออย่าไว้ชีวิตพวกเราในวันนี้เลย)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 23, 'ที่ว่าเราได้สร้างแท่นบูชานั้นเพื่อหันจากติดตามพระเยโฮวาห์ หรือพวกเราได้สร้างไว้เพื่อถวายเครื่องเผาบูชา หรือธัญญบูชาหรือถวายสันติบูชาบนแท่นนั้น ขอพระเยโฮวาห์ทรงลงโทษเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 24, 'เปล่าเลย แต่พวกเราได้สร้างไว้ด้วยเกรงว่า ในเวลาต่อไปภายหน้าลูกหลานของท่านอาจจะกล่าวต่อลูกหลานของเราว่า ‘เจ้ามีส่วนเกี่ยวพันอะไรกับพระเยโฮวาห์พระเจ้าของอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 25, 'เพราะว่าพระเยโฮวาห์ทรงกําหนดแม่น้ําจอร์แดนเป็นพรมแดนระหว่างเรากับเจ้าทั้งหลายนะ คนรูเบนและคนกาดเอ๋ย พวกเจ้าไม่มีส่วนในพระเยโฮวาห์’ ดังนั้นแหละลูกหลานของท่านอาจกระทําให้ลูกหลานของเราทั้งหลายหยุดเกรงกลัวพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 26, 'เพราะฉะนั้นเราจึงว่า ‘ให้เราสร้างแท่นบัดนี้ มิใช่สําหรับถวายเครื่องเผาบูชาหรือเครื่องสัตวบูชาใดๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 27, 'แต่เพื่อเป็นพยานระหว่างเรากับท่านทั้งหลาย และระหว่างคนชั่วอายุต่อจากเราว่า เราทั้งหลายจะกระทําการปรนนิบัติพระเยโฮวาห์ต่อพระพักตร์ของพระองค์ ด้วยเครื่องเผาบูชา และเครื่องสัตวบูชา และเครื่องสันติบูชา ด้วยเกรงว่าลูกหลานของท่านจะกล่าวแก่ลูกหลานของเราในเวลาต่อไปว่า “เจ้าไม่มีส่วนในพระเยโฮวาห์”’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 28, 'และเราคิดว่า ถ้ามีใครพูดเช่นนี้กับเราหรือกับเชื้อสายของเราในเวลาข้างหน้า เราก็จะกล่าวว่า ‘ดูเถิด นั่นเป็นแท่นจําลองของแท่นแห่งพระเยโฮวาห์ บรรพบุรุษของเรากระทําไว้ มิใช่เพื่อถวายเครื่องเผาบูชาหรือเครื่องสัตวบูชา แต่เพื่อเป็นพยานระหว่างเรากับท่าน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 29, 'ขอพระเจ้าอย่ายอมให้เรากบฏต่อพระเยโฮวาห์เลย และหันจากติดตามพระเยโฮวาห์เสียในวันนี้ โดยสร้างแท่นอื่นสําหรับเครื่องเผาบูชา ธัญญบูชา เครื่องสัตวบูชา นอกจากแท่นพระเยโฮวาห์พระเจ้าของเราซึ่งตั้งอยู่ที่หน้าพลับพลาของพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 30, 'เมื่อฟีเนหัสปุโรหิตและประมุขของชุมนุมชน และหัวหน้าคนอิสราเอลที่นับเป็นพันๆที่อยู่ด้วยกันนั้นได้ยินถ้อยคําที่คนรูเบน คนกาด และคนมนัสเสห์กล่าว ก็รู้สึกเป็นที่พอใจมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 31, 'ฟีเนหัสบุตรชายของเอเลอาซาร์ปุโรหิตจึงกล่าวแก่คนรูเบน คนกาด และคนมนัสเสห์ว่า “วันนี้เราทราบแล้วว่าพระเยโฮวาห์ทรงสถิตท่ามกลางพวกเรา เพราะท่านทั้งหลายมิได้กระทําการละเมิดต่อพระเยโฮวาห์ ท่านได้ช่วยให้ชนอิสราเอลพ้นจากพระหัตถ์ของพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 32, 'แล้วฟีเนหัสบุตรชายเอเลอาซาร์ปุโรหิต และประมุขทั้งหลายก็กลับจากคนรูเบน และคนกาด จากแผ่นดินกิเลอาดไปยังแผ่นดินคานาอัน ไปหาคนอิสราเอลแจ้งข่าวให้เขาทราบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 33, 'รายงานนั้นเป็นที่พอใจคนอิสราเอล และคนอิสราเอลก็สรรเสริญพระเจ้า และไม่พูดถึงเรื่องที่จะกระทําสงครามกับเขา เพื่อทําลายแผ่นดินซึ่งคนรูเบนและคนกาดได้อาศัยอยู่นั้นอีกเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 34, 'คนรูเบนและคนกาดเรียกแท่นนั้นว่า แอด เพราะว่า แท่นนั้นเป็นพยานในระหว่างเราว่า พระเยโฮวาห์เป็นพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 1, 'ต่อมาอีกนานเมื่อพระเยโฮวาห์โปรดให้อิสราเอลสงบจากการศึกศัตรูทั้งหลายที่ล้อมรอบ และโยชูวามีอายุชราลงมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 2, 'โยชูวาก็เรียกบรรดาคนอิสราเอล ทั้งพวกผู้ใหญ่ ผู้หัวหน้า ผู้พิพากษา และเจ้าหน้าที่และกล่าวแก่เขาทั้งหลายว่า “ข้าพเจ้าแก่และมีอายุมากแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 3, 'ท่านทั้งหลายได้เห็นสารพัดซึ่งพระเยโฮวาห์พระเจ้าของท่านได้กระทําต่อบรรดาประชาชาติเหล่านี้เพื่อเห็นแก่ท่าน เพราะว่าพระเยโฮวาห์พระเจ้าของท่านได้ทรงสู้รบเพื่อท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 4, 'ดูเถิด ประชาชาติที่เหลืออยู่นั้น ข้าพเจ้าได้จับฉลากแบ่งให้เป็นมรดกแก่ตระกูลของท่าน รวมกับประชาชาติทั้งสิ้นซึ่งข้าพเจ้าได้ขจัดออกเสีย ตั้งแต่แม่น้ําจอร์แดนจนถึงทะเลใหญ่ทางทิศตะวันตก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 5, 'พระเยโฮวาห์พระเจ้าของท่านจะทรงผลักดันเขาออกไปให้พ้นหน้าท่าน และทรงขับไล่เขาให้ออกไปพ้นสายตาของท่าน และท่านจะได้ยึดครองแผ่นดินของเขา ดังที่พระเยโฮวาห์พระเจ้าของท่านทรงสัญญาไว้ต่อท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 6, 'เพราะฉะนั้นจงมีความกล้าในการที่จะรักษาและกระทําตามสิ่งสารพัดซึ่งเขียนไว้ในหนังสือพระราชบัญญัติของโมเสส เพื่อจะไม่ได้หันไปทางขวามือหรือทางซ้ายมือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 7, 'เพื่อว่าท่านจะมิได้ปะปนกับประชาชาติเหล่านี้ ซึ่งเหลืออยู่ท่ามกลางท่าน หรือออกชื่อพระของเขา หรือปฏิญาณในนามพระของเขา หรือปรนนิบัติพระนั้น หรือกราบลงนมัสการพระนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 8, 'แต่ท่านจงติดสนิทอยู่กับพระเยโฮวาห์พระเจ้าของท่านดังที่กระทําอยู่จนทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 9, 'เพราะว่าพระเยโฮวาห์ทรงขับไล่ประชาชาติที่ใหญ่โตและแข็งแรงออกไปให้พ้นหน้าท่าน ส่วนท่านเองก็ยังไม่มีผู้ใดต่อต้านท่านได้จนถึงวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 10, 'พวกท่านคนเดียวจะขับไล่หนึ่งพันคนให้หนีไป เพราะว่าพระเยโฮวาห์พระเจ้าของท่านต่อสู้เพื่อท่านดังที่พระองค์ทรงสัญญาไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 11, 'เพราะฉะนั้นจงระวังตัวให้ดีที่จะรักพระเยโฮวาห์พระเจ้าของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 12, 'เพราะว่าถ้าท่านหันกลับและเข้าร่วมกับประชาชาติเหล่านี้ที่เหลืออยู่ในหมู่พวกท่านโดยแต่งงานกับเขา คือท่านแต่งงานกับหญิงของเขา และเขาแต่งงานกับหญิงของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 13, 'ท่านจงทราบเป็นแน่เถิดว่า พระเยโฮวาห์พระเจ้าของท่านจะไม่ทรงขับไล่ประชาชาติเหล่านี้ออกไปให้พ้นหน้าท่าน แต่เขาจะเป็นบ่วงและเป็นกับดักท่าน เป็นหอกข้างแคร่เป็นหนามยอกตา จนกว่าท่านจะพินาศไปจากแผ่นดินที่ดีนี้ ซึ่งพระเยโฮวาห์พระเจ้าของท่านประทานแก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 14, 'ดูเถิด วันนี้ข้าพเจ้ากําลังจะเป็นไปตามทางของโลกแล้ว ท่านทุกคนได้ทราบอย่างสุดจิตสุดใจของท่านแล้วว่า ไม่มีสักสิ่งเดียวซึ่งพระเยโฮวาห์พระเจ้าของท่านตรัสเกี่ยวกับท่านแล้วล้มเหลวไป สําเร็จหมดทุกอย่าง ไม่มีสักอย่างเดียวที่ล้มเหลว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 15, 'สิ่งสารพัดที่ดีซึ่งพระเยโฮวาห์พระเจ้าของท่านสัญญาเกี่ยวกับท่านได้สําเร็จเพื่อท่านฉันใด พระเยโฮวาห์ก็จะทรงนําสิ่งสารพัดที่ร้ายมาถึงท่าน จนกว่าพระองค์จะทําลายท่านเสียจากแผ่นดินอันดีนี้ ซึ่งพระเยโฮวาห์พระเจ้าของท่านประทานแก่ท่านเช่นเดียวกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 16, 'ถ้าท่านทั้งหลายละเมิดพันธสัญญาแห่งพระเยโฮวาห์พระเจ้าของท่าน ซึ่งพระองค์ทรงบัญชาท่านไว้และไปปรนนิบัติพระอื่น และกราบลงนมัสการพระนั้น แล้วพระพิโรธของพระเยโฮวาห์จะพลุ่งขึ้นต่อท่าน แล้วท่านจะพินาศไปอย่างรวดเร็วจากแผ่นดินที่ดี ซึ่งพระเยโฮวาห์พระเจ้าของท่านประทานแก่ท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 1, 'แล้วโยชูวาก็รวบรวมบรรดาตระกูลคนอิสราเอลมาที่เชเคม แล้วเรียกพวกผู้ใหญ่ ผู้หัวหน้า ผู้พิพากษา และเจ้าหน้าที่ของอิสราเอล แล้วเขาก็มาปรากฏตัวต่อพระพักตร์พระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 2, 'แล้วโยชูวากล่าวกับประชาชนทั้งสิ้นว่า “พระเยโฮวาห์พระเจ้าของอิสราเอลตรัสดังนี้ว่า ‘ในกาลดึกดําบรรพ์บรรพบุรุษของเจ้าอยู่ฟากแม่น้ําข้างโน้น คือเทราห์ บิดาของอับราฮัมและของนาโฮร์ และเขาปรนนิบัติพระอื่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 3, 'แล้วเราได้นําบิดาของเจ้าคืออับราฮัมมาจากฟากแม่น้ําข้างโน้น และนําเขามาตลอดแผ่นดินคานาอัน กระทําให้เชื้อสายของเขามีมากมาย เราให้อิสอัคแก่เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 4, 'เราให้ยาโคบและเอซาวแก่อิสอัค และเราได้ให้แดนเทือกเขาเสอีร์แก่เอซาวเป็นกรรมสิทธิ์ แต่ยาโคบและลูกหลานของเขาได้ลงไปในอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 5, 'และเราได้ใช้โมเสสกับอาโรนมา และเราได้ให้ภัยพิบัติเกิดแก่อียิปต์ด้วยสิ่งที่เรากระทําท่ามกลางเขานั้น และภายหลังเราได้นําเจ้าทั้งหลายออกมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 6, 'แล้วเราก็นําบรรพบุรุษของเจ้าออกจากอียิปต์และเจ้าทั้งหลายมาถึงทะเล และชาวอียิปต์ได้ไล่ตามบรรพบุรุษของเจ้าทั้งหลายด้วยรถรบและพลม้ามาถึงทะเลแดง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 7, 'และเมื่อเขาร้องทูลต่อพระเยโฮวาห์ พระองค์ก็บันดาลให้ความมืดเกิดขึ้นระหว่างเจ้าทั้งหลายและชาวอียิปต์ และกระทําให้ทะเลท่วมมิดเขา นัยน์ตาของเจ้าทั้งหลายได้เห็นสิ่งที่เรากระทําในอียิปต์ และเจ้าทั้งหลายอยู่ในถิ่นทุรกันดารช้านาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 8, 'และเราก็นําเจ้าทั้งหลายมาที่แผ่นดินของคนอาโมไรต์ซึ่งอยู่ที่ฟากแม่น้ําจอร์แดนข้างโน้น เขาสู้รบกับเจ้าทั้งหลาย และเราได้มอบเขาไว้ในมือของเจ้า และเจ้าทั้งหลายยึดครองแผ่นดินของเขาและเราก็ทําลายเขาให้พ้นหน้าเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 9, 'คราวนั้นบาลาคบุตรชายศิปโปร์กษัตริย์เมืองโมอับได้ลุกขึ้นต่อสู้กับอิสราเอล เขาใช้ให้ไปตามบาลาอัมบุตรชายเบโอร์มาให้แช่งเจ้าทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 10, 'แต่เราไม่ฟังบาลาอัม เพราะฉะนั้นเขาจึงอวยพรเจ้าทั้งหลายเรื่อยไป ดังนั้นเราจึงช่วยเจ้าให้พ้นมือของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 11, 'และเจ้าทั้งหลายข้ามแม่น้ําจอร์แดน มาที่เมืองเยรีโค และชาวเมืองเยรีโคต่อสู้กับเจ้า และคนอาโมไรต์ คนเปริสซี คนคานาอัน คนฮิตไทต์ คนเกอร์กาชี คนฮีไวต์ และคนเยบุส และเราได้มอบเขาไว้ในมือของเจ้าทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 12, 'และเราได้ใช้ตัวต่อไปข้างหน้าเจ้าทั้งหลาย ซึ่งขับไล่กษัตริย์ทั้งสองของชาวอาโมไรต์ไปเสียให้พ้นหน้าเจ้า ไม่ใช่ด้วยดาบหรือด้วยธนูของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 13, 'เราได้ยกแผ่นดินซึ่งเจ้าไม่ได้เหนื่อยกายบนนั้น และยกเมืองซึ่งเจ้าทั้งหลายไม่ต้องสร้างให้แก่เจ้าและเจ้าทั้งหลายได้เข้าอยู่ เจ้าได้กินผลของสวนองุ่นและสวนมะกอกเทศซึ่งเจ้าไม่ต้องปลูก’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 14, 'เหตุฉะนั้น บัดนี้จงยําเกรงพระเยโฮวาห์และปรนนิบัติพระองค์ด้วยความจริงใจและด้วยความจริง จงทิ้งพระเหล่านั้นซึ่งบรรพบุรุษของท่านได้เคยปรนนิบัติที่ฟากแม่น้ําข้างโน้น และในอียิปต์เสีย และท่านทั้งหลายจงปรนนิบัติพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 15, 'และถ้าท่านไม่เต็มใจที่จะปรนนิบัติพระเยโฮวาห์ ท่านทั้งหลายจงเลือกเสียในวันนี้ว่าท่านจะปรนนิบัติผู้ใด จะปรนนิบัติพระซึ่งอยู่ฟากแม่น้ําข้างโน้นที่บรรพบุรุษของท่านได้เคยปรนนิบัติ หรือพระของคนอาโมไรต์ในแผ่นดินซึ่งท่านอาศัยอยู่ แต่ส่วนข้าพเจ้าและครอบครัวของข้าพเจ้า เราจะปรนนิบัติพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 16, 'ฝ่ายประชาชนทั้งหลายจึงตอบว่า “ขอพระเจ้าอย่ายอมให้ข้าพเจ้าทั้งหลายละทิ้งพระเยโฮวาห์ไปปรนนิบัติพระอื่นเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 17, 'เพราะพระเยโฮวาห์พระเจ้าของข้าพเจ้าทั้งหลาย พระองค์นั้นทรงนําข้าพเจ้าทั้งหลายและบรรพบุรุษของข้าพเจ้าขึ้นมาจากแผ่นดินอียิปต์ และออกจากเรือนทาสนั้น และเป็นผู้ทรงกระทําหมายสําคัญยิ่งใหญ่ทั้งหลายท่ามกลางสายตาของพวกข้าพเจ้า และทรงคุ้มครองข้าพเจ้าทั้งหลายไว้ตลอดทางที่ข้าพเจ้าได้เดินไป และท่ามกลางชนชาติทั้งหลายซึ่งพวกข้าพเจ้าผ่านไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 18, 'และพระเยโฮวาห์ทรงขับไล่ชนชาติทั้งหลายออกไปให้พ้นหน้าข้าพเจ้า คือคนอาโมไรต์ผู้ซึ่งอยู่ในแผ่นดินนั้น เพราะฉะนั้นข้าพเจ้าทั้งหลายจะปรนนิบัติพระเยโฮวาห์ด้วย เพราะว่าพระองค์ทรงเป็นพระเจ้าของข้าพเจ้าทั้งหลาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 19, 'แต่โยชูวากล่าวแก่ประชาชนว่า “ท่านทั้งหลายจะปรนนิบัติพระเยโฮวาห์ไม่ได้ ด้วยว่าพระองค์ทรงเป็นพระเจ้าบริสุทธิ์ พระองค์ทรงเป็นพระเจ้าหวงแหน พระองค์จะไม่ทรงอภัยการละเมิดหรือความบาปของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 20, 'ถ้าท่านทั้งหลายละทิ้งพระเยโฮวาห์ไปปรนนิบัติพระอื่น แล้วพระองค์จะทรงหันกลับและกระทําอันตรายแก่ท่าน และผลาญท่านเสีย หลังจากที่พระองค์ทรงกระทําดีต่อท่านแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 21, 'และประชาชนกล่าวแก่โยชูวาว่า “หามิได้ แต่ข้าพเจ้าทั้งหลายจะปรนนิบัติพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 22, 'แล้วโยชูวากล่าวแก่ประชาชนว่า “ท่านทั้งหลายเป็นพยานปรักปรําตนเองว่า ท่านได้เลือกพระเยโฮวาห์ เพื่อปรนนิบัติพระองค์นะ” และเขากล่าวว่า “ข้าพเจ้าทั้งหลายเป็นพยาน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 23, 'ท่านจึงกล่าวว่า “เพราะฉะนั้น บัดนี้จงทิ้งพระอื่นซึ่งอยู่ในหมู่พวกท่านนั้นเสีย และโน้มจิตใจของท่านเข้าหาพระเยโฮวาห์พระเจ้าของอิสราเอล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 24, 'และประชาชนกล่าวแก่โยชูวาว่า “ข้าพเจ้าทั้งหลายจะปรนนิบัติพระเยโฮวาห์พระเจ้าของข้าพเจ้า และเชื่อฟังพระสุรเสียงของพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 25, 'ดังนั้นโยชูวาก็ได้กระทําพันธสัญญากับประชาชน และวางกฎเกณฑ์และกฎให้แก่เขาในวันนั้นที่เมืองเชเคม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 26, 'และโยชูวาก็จารึกถ้อยคําเหล่านี้ไว้ในหนังสือพระราชบัญญัติของพระเจ้า และท่านได้เอาก้อนหินใหญ่ตั้งไว้ที่ใต้ต้นโอ๊กที่ในสถานบริสุทธิ์แห่งพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 27, 'และโยชูวากล่าวแก่ประชาชนทั้งปวงว่า “ดูเถิด ศิลาก้อนนี้จะเป็นพยานปรักปรําเรา เพราะศิลานี้ได้ยินพระวจนะทั้งสิ้นแห่งพระเยโฮวาห์ซึ่งตรัสแก่เรา จึงจะเป็นพยานปรักปรําท่าน เกลือกว่าท่านจะปฏิเสธพระเจ้าของท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 28, 'แล้วโยชูวาก็ปล่อยให้ประชาชนกลับไปยังที่มรดกของตนทุกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 29, 'อยู่มาภายหลังเหตุการณ์เหล่านี้โยชูวาบุตรชายนูนผู้รับใช้ของพระเยโฮวาห์ก็สิ้นชีวิต มีอายุหนึ่งร้อยสิบปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 30, 'และเขาก็ฝังท่านไว้ในที่ดินมรดกของท่านที่เมืองทิมนาทเสราห์ ซึ่งอยู่ในแดนเทือกเขาแห่งเอฟราอิม ทิศเหนือของยอดเขากาอัช');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 31, 'คนอิสราเอลได้ปรนนิบัติพระเยโฮวาห์ตลอดสมัยของโยชูวา และตลอดสมัยของพวกผู้ใหญ่ผู้มีอายุยืนนานกว่าโยชูวา ผู้ซึ่งได้ทราบถึงบรรดาพระราชกิจซึ่งพระเยโฮวาห์ทรงกระทําเพื่ออิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 32, 'กระดูกของโยเซฟซึ่งชนอิสราเอลนํามาจากอียิปต์นั้น เขาฝังไว้ที่เมืองเชเคม ในส่วนที่ดินซึ่งยาโคบซื้อไว้จากลูกหลานของฮาโมร์บิดาของเชเคมเป็นเงินหนึ่งร้อยแผ่น ที่นี้ตกเป็นมรดกของลูกหลานโยเซฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 33, 'และเอเลอาซาร์บุตรชายของอาโรนก็สิ้นชีวิต และเขาฝังศพท่านไว้ในเนินเขาซึ่งเป็นของฟีเนหัสบุตรชายของท่าน ซึ่งได้มอบไว้ให้เขาในแดนเทือกเขาเอฟราอิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 1, 'อยู่มาเมื่อโยชูวาสิ้นชีพแล้ว คนอิสราเอลทูลถามพระเยโฮวาห์ว่า “ใครในพวกข้าพระองค์ทั้งหลายจะขึ้นไปก่อนเพื่อสู้รบกับคนคานาอัน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 2, 'พระเยโฮวาห์ตรัสว่า “ยูดาห์จะขึ้นไป ดูเถิด เราได้มอบแผ่นดินนั้นไว้ในมือเขาแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 3, 'ยูดาห์จึงพูดกับสิเมโอนพี่ของตนว่า “จงขึ้นไปกับฉันในเขตแดนที่กําหนดให้แก่ฉัน เพื่อเราจะได้สู้รบกับคนคานาอัน และฉันจะไปร่วมรบในเขตแดนที่กําหนดให้แก่ท่านนั้นด้วย” สิเมโอนก็ไปกับเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 4, 'แล้วยูดาห์ก็ขึ้นไป และพระเยโฮวาห์ทรงมอบคนคานาอันและคนเปริสซีไว้ในมือของเขา และเขาก็ประหารคนที่เมืองเบเซกหนึ่งหมื่นคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 5, 'และเขาทั้งหลายพบอาโดนีเบเซกในเมืองเบเซก และสู้รบกับท่าน เขาได้ประหารคนคานาอันและคนเปริสซี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 6, 'อาโดนีเบเซกหนีไป แต่พวกเขาตามจับได้และได้ตัดนิ้วหัวแม่มือ และนิ้วหัวแม่เท้าของท่านออกเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 7, 'อาโดนีเบเซกกล่าวว่า “มีกษัตริย์เจ็ดสิบองค์ที่หัวแม่มือและหัวแม่เท้าของเขาถูกตัดออก เก็บเศษอาหารอยู่ใต้โต๊ะของเรา เรากระทําแก่เขาอย่างไร พระเจ้าก็ทรงกระทําแก่เราอย่างนั้น” เขาทั้งหลายก็คุมตัวท่านมาที่กรุงเยรูซาเล็ม และท่านก็สิ้นชีวิตที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 8, 'และคนยูดาห์ได้เข้าโจมตีเมืองเยรูซาเล็มและยึดเมืองได้ จึงฆ่าฟันชาวเมืองเสียด้วยคมดาบ และเอาไฟเผาเมืองเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 9, 'ภายหลังคนยูดาห์ได้ลงไปสู้รบกับคนคานาอันผู้ซึ่งตั้งอยู่ในแดนเทือกเขา ในภาคใต้ และในหุบเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 10, 'และยูดาห์ได้ไปสู้รบกับคนคานาอันผู้อยู่ในเฮโบรน (เมืองเฮโบรนนั้นแต่ก่อนมีชื่อว่าคีริยาทอารบา) และเขาทั้งหลายได้ประหารเชชัย อาหิมาน และทัลมัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 11, 'เขาทั้งหลายยกจากที่นั่นไปสู้รบกับชาวเมืองเดบีร์ เมืองเดบีร์นั้นแต่ก่อนมีชื่อว่าคีริยาทเสเฟอร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 12, 'และคาเลบกล่าวว่า “ใครโจมตีเมืองคีริยาทเสเฟอร์และยึดได้ เราจะยกอัคสาห์บุตรสาวของเราให้เป็นภรรยา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 13, 'และโอทนีเอลบุตรชายเคนัส น้องชายของคาเลบตีเมืองนั้นได้ ท่านจึงยกอัคสาห์บุตรสาวของตนให้เป็นภรรยา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 14, 'อยู่มาเมื่อแต่งงานกันแล้วนางจึงชวนสามีให้ขอที่นาต่อบิดา นางก็ลงจากหลังลา และคาเลบถามนางว่า “เจ้าต้องการอะไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 15, 'นางจึงตอบท่านว่า “ขอของขวัญให้ลูกสักอย่างหนึ่งเถิด เมื่อพ่อให้ลูกมาอยู่ในแผ่นดินภาคใต้แล้ว ลูกขอน้ําพุด้วย” และคาเลบก็ยกน้ําพุบนและน้ําพุล่างให้แก่นาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 16, 'คนเคไนต์พ่อตาของโมเสสได้ขึ้นไปจากเมืองดงอินทผลัม พร้อมกับคนยูดาห์มาถึงถิ่นทุรกันดารยูดาห์ซึ่งอยู่ในภาคใต้ใกล้อาราด และเขาก็เข้าไปตั้งอยู่กับชนชาตินั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 17, 'และยูดาห์ก็ยกไปร่วมกับสิเมโอนพี่ของเขาประหารคนคานาอันซึ่งอยู่ในเมืองเศฟัทและทําลายเมืองนั้นเสียอย่างสิ้นเชิง ชื่อเมืองนั้นจึงเรียกว่าโฮรมาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 18, 'ยูดาห์ได้ยึดเมืองกาซาพร้อมทั้งอาณาเขต และเมืองอัชเคโลนพร้อมทั้งอาณาเขต และเมืองเอโครนพร้อมทั้งอาณาเขตไว้ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 19, 'และพระเยโฮวาห์ทรงสถิตกับยูดาห์ เขาจึงขับไล่ชาวแดนเทือกเขาออกไป แต่จะขับไล่ชาวเมืองที่อยู่ในหุบเขานั้นไม่ได้ เพราะพวกเหล่านั้นมีรถรบเหล็ก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 20, 'เมืองเฮโบรนนั้นเขายกให้คาเลบดังที่โมเสสได้กล่าวไว้ คาเลบจึงขับไล่บุตรชายทั้งสามคนของอานาคออกไปเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 21, 'แต่คนเบนยามินมิได้ขับไล่คนเยบุสผู้อยู่ในเยรูซาเล็มให้ออกไป ดังนั้นคนเยบุสจึงอาศัยอยู่กับคนเบนยามินในเยรูซาเล็มจนถึงทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 22, 'อนึ่งวงศ์วานของโยเซฟได้ขึ้นไปสู้รบเมืองเบธเอลด้วย และพระเยโฮวาห์ทรงสถิตกับพวกเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 23, 'วงศ์วานโยเซฟได้ใช้คนไปสอดแนมเมืองเบธเอล (แต่ก่อนเมืองนี้ชื่อ ลูส)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 24, 'และผู้สอดแนมเห็นชายคนหนึ่งเดินออกมาจากเมือง จึงพูดกับเขาว่า “ขอชี้ทางเข้าเมืองนี้ให้แก่เรา และเราจะปรานีเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 25, 'ชายคนนั้นก็ชี้ทางเข้าเมืองให้และเขาประหารเมืองนั้น ทําลายเสียด้วยคมดาบ แต่เขาปล่อยให้ชายคนนั้นและครอบครัวทั้งสิ้นของเขารอดไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 26, 'ชายคนนั้นก็เข้าไปในแผ่นดินของคนฮิตไทต์และสร้างเมืองขึ้นเมืองหนึ่ง เรียกชื่อว่าเมืองลูส ซึ่งเป็นชื่ออยู่จนทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 27, 'มนัสเสห์มิได้ขับไล่ชาวเมืองเบธชานและชาวชนบทของเมืองนั้นให้ออกไป หรือชาวเมืองทาอานาคกับชาวชนบทของเมืองนั้น หรือชาวเมืองโดร์กับชาวชนบทของเมืองนั้น หรือชาวเมืองอิบเลอัมกับชาวชนบทของเมืองนั้น หรือชาวเมืองเมกิดโดกับชาวชนบทของเมืองนั้น แต่คนคานาอันยังขืนอาศัยอยู่ในแผ่นดินนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 28, 'อยู่มาเมื่อคนอิสราเอลมีกําลังเข้มแข็งขึ้นก็บังคับคนคานาอันให้ทํางานโยธา แต่มิได้ขับไล่ให้เขาออกไปเสียอย่างสิ้นเชิง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 29, 'และเอฟราอิมมิได้ขับไล่คนคานาอันผู้อาศัยอยู่ในเมืองเกเซอร์ให้ออกไป แต่คนคานาอันยังอาศัยอยู่ในเมืองเกเซอร์ท่ามกลางเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 30, 'เศบูลุนมิได้ขับไล่ชาวเมืองคิทโรน หรือชาวเมืองนาหะโลล แต่คนคานาอันได้อาศัยอยู่ท่ามกลางเขาและถูกเกณฑ์ให้ทํางานโยธา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 31, 'อาเชอร์มิได้ขับไล่ชาวเมืองอัคโค หรือชาวเมืองไซดอน หรือชาวเมืองอัคลาบ หรือชาวเมืองอัคซีบ หรือชาวเมืองเฮลบาห์ หรือชาวเมืองอาฟิก หรือชาวเมืองเรโหบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 32, 'แต่คนอาเชอร์ได้อาศัยอยู่ท่ามกลางคนคานาอันชาวแผ่นดินนั้น เพราะว่าเขาทั้งหลายมิได้ขับไล่ให้ออกไปเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 33, 'นัฟทาลีมิได้ขับไล่ชาวเมืองเบธเชเมช หรือชาวเมืองเบธานาท แต่อาศัยอยู่ในหมู่คนคานาอันชาวแผ่นดินนั้น แต่อย่างไรก็ดีชาวเมืองเบธเชเมช และชาวเมืองเบธานาทก็ถูกเกณฑ์ให้ทํางานโยธา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 34, 'คนอาโมไรต์ได้ขับดันคนดานให้กลับเข้าไปในแดนเทือกเขา ไม่ยอมให้ลงมายังหุบเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 35, 'คนอาโมไรต์ยังขืนอาศัยอยู่ที่ภูเขาเฮเรสในเมืองอัยยาโลน และในเมืองชาอัลบิม แต่มือของวงศ์วานโยเซฟเหนือกว่ามือเขาทั้งหลาย เขาจึงถูกเกณฑ์ให้ทํางานโยธา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 36, 'อาณาเขตของคนอาโมไรต์ตั้งต้นแต่ทางข้ามเขาอัครับบิมตั้งแต่ศิลาเรื่อยขึ้นไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 1, 'ฝ่ายทูตสวรรค์องค์หนึ่งของพระเยโฮวาห์ได้ขึ้นไปจากกิลกาลถึงโบคิม และกล่าวว่า “เราได้ให้เจ้าทั้งหลายขึ้นไปจากอียิปต์ และได้นําเจ้าเข้ามาในแผ่นดินซึ่งเราปฏิญาณไว้แก่บรรพบุรุษของเจ้า และเรากล่าวว่า ‘เราจะไม่หักพันธสัญญาที่เราได้มีไว้กับเจ้าเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 2, 'และเจ้าทั้งหลายอย่าทําพันธสัญญากับชาวแผ่นดินนี้ เจ้าต้องทําลายแท่นบูชาของเขาเสีย’ แต่เจ้ามิได้เชื่อฟังเสียงของเรา เจ้าทําอะไรเช่นนี้เล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 3, 'ฉะนั้นเรากล่าวด้วยว่า ‘เราจะไม่ขับไล่เขาเหล่านั้นออกไปให้พ้นหน้าเจ้า แต่เขาจะเป็นเช่นหนามอยู่ที่สีข้างของเจ้า และพระของเขาจะเป็นบ่วงดักเจ้า’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 4, 'อยู่มาเมื่อทูตสวรรค์ของพระเยโฮวาห์กล่าวคําเหล่านี้แก่บรรดาคนอิสราเอลแล้วประชาชนก็ส่งเสียงร้องไห้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 5, 'และเขาเรียกที่ตําบลนั้นว่า โบคิม และเขาทั้งหลายได้ถวายสัตวบูชาแด่พระเยโฮวาห์ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 6, 'เมื่อโยชูวาปล่อยประชาชนไปแล้วคนอิสราเอลต่างก็เข้าไปอยู่ในมรดกที่ดินของตนเพื่อยึดครอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 7, 'ประชาชนทั้งหลายได้ปรนนิบัติพระเยโฮวาห์ตลอดสมัยของโยชูวา และตลอดสมัยของพวกผู้ใหญ่ผู้มีอายุยืนนานกว่าโยชูวา ผู้ซึ่งได้เห็นปวงมหกิจซึ่งพระเยโฮวาห์ได้ทรงกระทําเพื่ออิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 8, 'โยชูวาบุตรชายนูนผู้รับใช้ของพระเยโฮวาห์สิ้นชีวิตเมื่ออายุได้หนึ่งร้อยสิบปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 9, 'และเขาทั้งหลายก็ฝังท่านไว้ในที่ดินมรดกของท่านที่เมืองทิมนาทเฮเรส ในแดนเทือกเขาแห่งเอฟราอิม ทิศเหนือของยอดเขากาอัช');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 10, 'และยุครุ่นนั้นทั้งสิ้นก็ถูกรวบไปอยู่กับบรรพบุรุษของเขา อีกยุคหนึ่งก็เกิดขึ้นตามมา เขาไม่รู้จักพระเยโฮวาห์หรือรู้พระราชกิจซึ่งพระองค์ได้ทรงกระทําเพื่ออิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 11, 'คนอิสราเอลก็กระทําชั่วในสายพระเนตรของพระเยโฮวาห์ และปรนนิบัติพระบาอัล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 12, 'เขาได้ละทิ้งพระเยโฮวาห์พระเจ้าแห่งบรรพบุรุษของเขา ผู้ทรงนําเขาออกมาจากแผ่นดินอียิปต์ และเขาทั้งหลายติดตามพระอื่นซึ่งเป็นพระของชนชาติทั้งหลายที่อยู่ล้อมรอบเขา กราบไหว้พระเหล่านั้น กระทําให้พระเยโฮวาห์ทรงพระพิโรธ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 13, 'เขาทั้งหลายละทิ้งพระเยโฮวาห์ไปปรนนิบัติพระบาอัล และพวกพระอัชทาโรท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 14, 'ดังนั้นพระพิโรธของพระเยโฮวาห์จึงพลุ่งขึ้นต่ออิสราเอล พระองค์จึงทรงมอบเขาไว้ในมือพวกปล้นผู้ปล้นเขา และทรงขายเขาไว้ในมือของบรรดาศัตรูที่อยู่รอบเขาทั้งหลาย ดังนั้นเขาทั้งหลายจึงต่อต้านพวกศัตรูของเขาทั้งหลายต่อไปไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 15, 'เขาทั้งหลายออกไปรบเมื่อไร พระหัตถ์ของพระเยโฮวาห์ก็ต่อต้านเขา กระทําให้เขาพ่ายแพ้ ดังที่พระเยโฮวาห์ได้ตรัสไว้แล้ว และดังที่พระเยโฮวาห์ทรงปฏิญาณไว้กับเขา และเขาทั้งหลายก็มีความทุกข์ยิ่งนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 16, 'อย่างไรก็ตามพระเยโฮวาห์ทรงให้เกิดผู้วินิจฉัย ผู้ช่วยเขาทั้งหลายให้พ้นมือของผู้ที่ปล้นเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 17, 'แต่เขาทั้งหลายก็ยังไม่เชื่อฟังผู้วินิจฉัยทั้งหลายของเขา เพราะเขาทั้งหลายเล่นชู้กับพระอื่นและกราบไหว้พระอื่น ไม่ช้าเขาก็หันไปเสียจากทางซึ่งบรรพบุรุษของเขาได้ดําเนิน ผู้ได้เชื่อฟังพระบัญญัติของพระเยโฮวาห์ แต่เขาทั้งหลายมิได้กระทําตาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 18, 'พระเยโฮวาห์ทรงตั้งผู้วินิจฉัยขึ้นเมื่อไร พระเยโฮวาห์ก็ทรงสถิตกับผู้วินิจฉัยนั้นเมื่อนั้น และพระองค์ทรงช่วยเขาทั้งหลายให้พ้นจากเงื้อมมือของศัตรูตลอดชีวิตของผู้วินิจฉัยนั้น เพราะพระเยโฮวาห์ทรงกลับพระทัยสงสารเขาทั้งหลาย เมื่อทรงฟังเสียงคร่ําครวญของเขาเนื่องด้วยผู้ข่มเหงและบีบบังคับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 19, 'แต่อยู่มาเมื่อผู้วินิจฉัยนั้นสิ้นชีวิต เขาทั้งหลายก็หันกลับประพฤติชั่วร้ายเสียยิ่งกว่าบิดาของเขา หลงไปติดตามปรนนิบัติและกราบไหว้พระอื่น เขามิได้เคยงดเว้นการกระทําของเขาหรือหายจากทางดื้อดึงของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 20, 'ดังนั้นพระพิโรธของพระเยโฮวาห์จึงพลุ่งขึ้นต่ออิสราเอล และพระองค์ตรัสว่า “เพราะประชาชนนี้ได้ละเมิดต่อพันธสัญญา ซึ่งเราได้บัญชาไว้กับบรรพบุรุษของเขา และไม่ยอมฟังเสียงของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 21, 'ดังนั้นตั้งแต่นี้ต่อไปเราจะไม่ขับไล่ประชาชาติใดในบรรดาประชาชาติซึ่งโยชูวาทิ้งไว้เมื่อเขาสิ้นชีวิตนั้นให้พ้นหน้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 22, 'เพื่อเราจะใช้ประชาชาติเหล่านั้นทั้งสิ้นทดสอบอิสราเอลว่า เขาจะรักษาพระมรรคาของพระเยโฮวาห์และดําเนินตามอย่างบรรพบุรุษของเขาหรือไม่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 23, 'ดังนั้นพระเยโฮวาห์ทรงปล่อยประชาชาติเหล่านั้นไว้ ไม่ทรงขับไล่ให้ออกไปเสียโดยเร็ว และพระองค์มิได้ทรงมอบเขาทั้งหลายไว้ในมือของโยชูวา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 1, 'ต่อไปนี้เป็นประชาชาติที่พระเยโฮวาห์ทรงให้เหลือไว้ เพื่อใช้ทดสอบบรรดาคนอิสราเอล คือคนอิสราเอลคนใดซึ่งยังไม่เคยประสบสงครามทั้งหลายในคานาอัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 2, 'แต่เพียงทรงให้เชื้อสายคนอิสราเอลเข้าใจเรื่องการสงคราม เพื่ออย่างน้อยพระองค์จะได้ทรงสอนแก่ผู้ที่ยังไม่ทราบมาก่อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 3, 'คือเจ้านายทั้งห้าของคนฟีลิสเตีย คนคานาอันทั้งหมด ชาวไซดอน และคนฮีไวต์ผู้อาศัยอยู่บนภูเขาเลบานอน ตั้งแต่ภูเขาบาอัลเฮอร์โมนจนถึงทางเข้าเมืองฮามัท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 4, 'เหลือคนเหล่านี้อยู่เพื่อทดสอบคนอิสราเอลเพื่อให้ทราบว่า อิสราเอลจะเชื่อฟังพระบัญญัติของพระเยโฮวาห์ ซึ่งพระองค์ทรงบัญชาไว้กับบรรพบุรุษของเขาโดยโมเสสนั้นหรือไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 5, 'ดังนั้นแหละคนอิสราเอลจึงอาศัยอยู่ในหมู่คนคานาอัน คนฮิตไทต์ คนอาโมไรต์ คนเปริสซี คนฮีไวต์ และคนเยบุส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 6, 'เขาไปสู่ขอบุตรสาวชนเหล่านั้นมาเป็นภรรยา และยกบุตรสาวของตนให้แก่บุตรชายของคนเหล่านั้น และได้ปรนนิบัติพระของเขาเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 7, 'คนอิสราเอลได้กระทําชั่วในสายพระเนตรของพระเยโฮวาห์ ลืมพระเยโฮวาห์พระเจ้าของตนเสีย ไปปรนนิบัติพระบาอัลและเสารูปเคารพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 8, 'เพราะฉะนั้นพระพิโรธของพระเยโฮวาห์ก็พลุ่งขึ้นต่ออิสราเอล และพระองค์ทรงขายเขาไว้ในมือคูชันริชาธาอิมกษัตริย์เมืองเมโสโปเตเมีย และคนอิสราเอลได้ปฏิบัติคูชันริชาธาอิมแปดปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 9, 'แต่เมื่อคนอิสราเอลร้องทูลพระเยโฮวาห์ พระเยโฮวาห์ทรงให้เกิดผู้ช่วยแก่คนอิสราเอล ผู้ได้ช่วยเขาทั้งหลายให้รอด คือโอทนีเอลบุตรชายเคนัส น้องชายของคาเลบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 10, 'พระวิญญาณของพระเยโฮวาห์ทรงสถิตกับโอทนีเอล และท่านจึงวินิจฉัยคนอิสราเอล และออกไปกระทําสงคราม และพระเยโฮวาห์ทรงมอบคูชันริชาธาอิมกษัตริย์เมืองเมโสโปเตเมียไว้ในมือของท่าน และมือของท่านชนะคูชันริชาธาอิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 11, 'ดังนั้นแผ่นดินจึงได้หยุดพักสงบอยู่สี่สิบปี แล้วโอทนีเอลบุตรชายเคนัสก็สิ้นชีวิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 12, 'และคนอิสราเอลกระทําชั่วในสายพระเนตรของพระเยโฮวาห์อีก พระเยโฮวาห์จึงทรงเสริมกําลังเอกโลนกษัตริย์เมืองโมอับเพื่อต่อสู้อิสราเอล เพราะว่าเขาทั้งหลายได้ประพฤติชั่วในสายพระเนตรของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 13, 'ท่านจึงได้ให้คนอัมโมนและคนอามาเลขมาสมทบ ยกไปโจมตีอิสราเอล และได้ยึดเมืองดงอินทผลัมไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 14, 'และคนอิสราเอลจึงปฏิบัติเอกโลนกษัตริย์เมืองโมอับอยู่ถึงสิบแปดปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 15, 'แต่เมื่อคนอิสราเอลร้องทูลพระเยโฮวาห์ พระเยโฮวาห์ทรงให้เกิดผู้ช่วยคนหนึ่งแก่เขาทั้งหลาย ชื่อเอฮูด บุตรชายเก-รา คนเบนยามิน คนถนัดมือซ้าย คนอิสราเอลให้ท่านเป็นผู้นําส่วยไปมอบแก่เอกโลนกษัตริย์เมืองโมอับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 16, 'เอฮูดได้ทําดาบสองคมไว้ประจําตัวเล่มหนึ่งยาวศอกหนึ่ง เหน็บไว้ใต้ผ้าที่ต้นขาขวา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 17, 'เขาก็นําส่วยไปมอบแก่เอกโลนกษัตริย์เมืองโมอับ ฝ่ายเอกโลนเป็นคนอ้วนมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 18, 'และเมื่อเอฮูดมอบส่วยเสร็จแล้ว ท่านจึงไปส่งคนที่หาบหามส่วยนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 19, 'แล้วตัวท่านกลับไปจากรูปเคารพสลักที่อยู่ใกล้กิลกาลทูลว่า “โอ ข้าแต่กษัตริย์ ข้าพระองค์มีข้อราชการลับที่จะกราบทูลให้ทรงทราบ” กษัตริย์จึงมีบัญชาว่า “เงียบๆ” บรรดามหาดเล็กที่เฝ้าอยู่ก็ทูลลาออกไปหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 20, 'และเอฮูดก็เข้าไปเฝ้าท่าน ขณะนั้นท่านประทับอยู่ลําพังในห้องเย็นชั้นบนของท่าน และเอฮูดทูลว่า “ข้าพระองค์มีพระดํารัสจากพระเจ้าถวายพระองค์” ท่านจึงลุกขึ้นจากพระที่นั่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 21, 'เอฮูดก็ยื่นมือซ้ายชักดาบนั้นออกจากต้นขาขวาแทงเข้าไปในท้องของเอกโลน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 22, 'ดาบจมเข้าไปหมดทั้งด้าม ไขมันหุ้มดาบไว้ ท่านก็ชักดาบออกจากท้องของท่านไม่ได้ แล้วของโสโครกออกมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 23, 'แล้วเอฮูดออกไปที่เฉลียงปิดทวารห้องชั้นบน ลั่นกุญแจเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 24, 'เมื่อเอฮูดไปแล้วมหาดเล็กก็เข้ามา ดูเถิด เมื่อเขาเห็นว่าทวารห้องชั้นบนปิดใส่กุญแจอยู่ เขาทั้งหลายคิดว่า “พระองค์ท่านกําลังทรงปล่อยทุกข์อยู่ที่ในห้องเย็น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 25, 'เมื่อคอยอยู่ช้านานจนรําคาญ ดูเถิด ไม่เห็นมีใครเปิดทวารห้องชั้นบน เขาจึงเอากุญแจมาไขเปิดออก ดูเถิด เห็นเจ้านายของตนนอนสิ้นชีวิตอยู่บนพื้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 26, 'เมื่อเขาต่างก็คอยกันอยู่นั้นเอฮูดก็หนีไปพ้นรูปเคารพหินสลักรอดมาได้ถึงเสอีราห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 27, 'ต่อมาเมื่อท่านมาถึงแล้วจึงเป่าแตรขึ้นในแดนเทือกเขาเอฟราอิม แล้วคนอิสราเอลก็ยกลงไปกับท่านจากแดนเทือกเขาและท่านนําเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 28, 'ท่านจึงสั่งเขาว่า “จงตามเรามาเถิด เพราะพระเยโฮวาห์ทรงมอบศัตรูของท่าน คือชนโมอับไว้ในมือของท่านแล้ว” เขาทั้งหลายจึงลงตามท่านไป และยึดท่าข้ามแม่น้ําจอร์แดนสกัดคนโมอับไว้ไม่ยอมให้ใครข้ามไปได้สักคนเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 29, 'ในคราวนั้นเขาประหารคนโมอับเสียประมาณหนึ่งหมื่นคนล้วนแต่คนฉกรรจ์และล่ําสันทั้งสิ้น ไม่พ้นไปได้สักคนเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 30, 'โมอับจึงพ่ายแพ้อยู่ใต้มือของอิสราเอลในวันนั้น และแผ่นดินนั้นก็ได้หยุดพักสงบอยู่แปดสิบปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 31, 'ภายหลังเอฮูด มีชัมการ์บุตรชายอานาทผู้ใช้ประตักวัวฆ่าคนฟีลิสเตียเสียหกร้อยคน ท่านก็เป็นผู้ช่วยอิสราเอลให้รอดด้วยเหมือนกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 1, 'ครั้นเอฮูดสิ้นชีวิตแล้ว คนอิสราเอลก็ประพฤติชั่วในสายพระเนตรของพระเยโฮวาห์อีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 2, 'พระเยโฮวาห์จึงทรงขายเขาไว้ในมือของยาบินกษัตริย์เมืองคานาอัน ผู้ครอบครองอยู่ ณ กรุงฮาโซร์ แม่ทัพของท่านชื่อสิเสรา ผู้ซึ่งอาศัยอยู่ที่เมืองฮาโรเชทของคนต่างชาติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 3, 'แล้วคนอิสราเอลก็ร้องทุกข์ถึงพระเยโฮวาห์ เพราะว่ากษัตริย์ยาบินมีรถรบเหล็กเก้าร้อยคัน และได้บีบบังคับคนอิสราเอลอย่างร้ายถึงยี่สิบปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 4, 'คราวนั้นผู้พยากรณ์หญิงคนหนึ่งชื่อเดโบราห์ ภรรยาของลัปปิโดท เป็นผู้วินิจฉัยคนอิสราเอลสมัยนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 5, 'นางเคยนั่งอยู่ใต้ต้นอินทผลัมเดโบราห์ที่อยู่ระหว่างรามาห์และเบธเอลในแดนเทือกเขาเอฟราอิม และคนอิสราเอลก็ขึ้นมาหานางที่นั่นเพื่อให้ชําระความ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 6, 'นางใช้คนไปเรียกบาราคบุตรชายอาบีโนอัม ให้มาจากเคเดชนัฟทาลีและกล่าวแก่เขาว่า “พระเยโฮวาห์พระเจ้าของอิสราเอลมิได้ทรงบัญชาท่านหรือว่า ‘ไปซิรวบรวมพลไว้ที่ภูเขาทาโบร์ จงเกณฑ์จากคนนัฟทาลีและคนเศบูลุนหนึ่งหมื่นคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 7, 'และเราจะชักนําสิเสราแม่ทัพของยาบินให้มาพบกับเจ้าที่แม่น้ําคีโชน พร้อมกับรถรบและกองทหารของเขา และเราจะมอบเขาไว้ในมือของเจ้า’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 8, 'บาราคจึงตอบนางว่า “ถ้าแม้นางไปกับข้าพเจ้า ข้าพเจ้าจะไป แต่ถ้าแม้นางไม่ไปกับข้าพเจ้า ข้าพเจ้าก็ไม่ไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 9, 'นางจึงตอบว่า “ดิฉันจะไปกับท่านแน่ แต่ว่าทางที่ท่านไปนั้นจะไม่นําท่านไปถึงศักดิ์ศรี เพราะว่าพระเยโฮวาห์จะขายสิเสราไว้ในมือของหญิงคนหนึ่ง” แล้วนางเดโบราห์ก็ลุกขึ้นไปกับบาราคถึงเมืองเคเดช');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 10, 'บาราคจึงเรียกเศบูลุนกับนัฟทาลีให้ไปที่เคเดช มีคนหนึ่งหมื่นเดินตามขึ้นไป และนางเดโบราห์ก็ไปด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 11, 'มีชายคนหนึ่งชื่อเฮเบอร์คนเคไนต์ คือจากลูกหลานของโฮบับพ่อตาของโมเสส ได้แยกออกจากคนเคไนต์ทั้งหลาย มาตั้งเต็นท์อยู่ไกลออกไปถึงที่ราบศานันนิม ซึ่งอยู่ใกล้เมืองเคเดช');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 12, 'เมื่อมีคนไปแจ้งแก่สิเสราว่าบาราคบุตรชายอาบีโนอัมขึ้นไปที่ภูเขาทาโบร์แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 13, 'สิเสราก็เรียกรถรบทั้งหมดของท่านออกมา เป็นรถเหล็กเก้าร้อยคัน รวมกับเหล่าทหารทั้งหมดที่ไปด้วย ยกไปจากเมืองฮาโรเชทของคนต่างชาติไปถึงแม่น้ําคีโชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 14, 'นางเดโบราห์จึงกล่าวแก่บาราคว่า “ลุกขึ้นเถิด เพราะว่านี่เป็นวันที่พระเยโฮวาห์ทรงมอบสิเสราไว้ในมือของท่าน พระเยโฮวาห์เสด็จนําหน้าท่านไปมิใช่หรือ” บาราคจึงลงไปจากภูเขาทาโบร์พร้อมกับทหารหนึ่งหมื่นคนติดตามท่านไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 15, 'พระเยโฮวาห์ทรงกระทําให้สิเสราพร้อมกับรถรบทั้งสิ้นของท่านและกองทัพทั้งหมดของท่าน แตกตื่นพ่ายแพ้ด้วยคมดาบต่อหน้าบาราค แล้วสิเสราก็ลงจากรถรบวิ่งหนีไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 16, 'และบาราคได้ไล่ติดตามรถรบทั้งหลายและกองทัพไปจนถึงฮาโรเชทของคนต่างชาติ และกองทัพทั้งหมดของสิเสราก็ล้มตายด้วยคมดาบ ไม่เหลือสักคนเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 17, 'ฝ่ายสิเสราวิ่งหนีไปถึงเต็นท์ของยาเอล ภรรยาของเฮเบอร์คนเคไนต์ เพราะว่ายาบินกษัตริย์เมืองฮาโซร์เป็นไมตรีกันกับวงศ์วานเฮเบอร์คนเคไนต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 18, 'ยาเอลจึงออกไปต้อนรับสิเสรา เรียนว่า “เจ้านายของดิฉันเจ้าข้า เชิญแวะเข้ามา เชิญแวะเข้ามาพักกับดิฉัน อย่ากลัวอะไรเลย” สิเสราจึงแวะเข้าไปในเต็นท์ และนางก็เอาผ้าห่มมาคลุมตัวให้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 19, 'ท่านจึงพูดกับนางว่า “ขอน้ําให้เรากินสักหน่อยเพราะเรากระหายน้ํา” นางก็เปิดถุงน้ํานมให้ท่านดื่ม และเอาผ้าคลุมท่านไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 20, 'สิเสราจึงบอกแก่นางอีกว่า “ขอยืนเฝ้าที่ประตูเต็นท์ ถ้ามีผู้ใดมาถามว่า ‘มีใครมาพักที่นี่บ้างหรือ’ จงบอกว่า ‘ไม่มี’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 21, 'แต่ยาเอลภรรยาของเฮเบอร์หยิบหลักขึงเต็นท์ ถือค้อนเดินย่องเข้ามา ตอกหลักเข้าที่ขมับของสิเสราทะลุติดดิน ขณะเมื่อสิเสรากําลังหลับสนิทอยู่เพราะความเหน็ดเหนื่อย แล้วสิเสราก็สิ้นชีวิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 22, 'และดูเถิด บาราคไล่ติดตามสิเสรามาถึง ยาเอลก็ออกไปต้อนรับเรียนท่านว่า “เชิญเข้ามาเถิด ดิฉันจะชี้ให้ท่านเห็นคนที่ท่านค้นหาอยู่นั้น” พอบาราคก็เข้าไปในเต็นท์แล้ว ดูเถิด สิเสรานอนสิ้นชีวิตอยู่ มีหลักเต็นท์ในขมับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 23, 'ดังนี้แหละในวันนั้นพระเจ้าทรงกระทําให้ยาบินกษัตริย์คานาอันนอบน้อมต่อหน้าคนอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 24, 'และมือของคนอิสราเอลก็กระทําต่อยาบินกษัตริย์เมืองคานาอันหนักขึ้นทุกที จนเขาทั้งหลายได้ทําลายยาบินกษัตริย์เมืองคานาอันเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 1, 'แล้วนางเดโบราห์กับบาราคบุตรชายอาบีโนอัมจึงร้องเพลงในวันนั้นว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 2, '“จงสรรเสริญพระเยโฮวาห์เพราะพระองค์ทรงแก้แค้นคนอิสราเอลเมื่อประชาชนสมัครใจช่วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 3, 'โอ บรรดากษัตริย์ ขอทรงสดับ โอ เจ้านายทั้งหลาย ขอจงเงี่ยหูฟัง ข้าพเจ้านี่แหละจะร้องเพลงถวายพระเยโฮวาห์ ข้าพเจ้าจะร้องเพลงสรรเสริญพระเยโฮวาห์พระเจ้าของอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 4, 'ข้าแต่พระเยโฮวาห์ เมื่อพระองค์เสด็จออกจากเสอีร์ เมื่อพระองค์เสด็จจากท้องถิ่นเอโดม แผ่นดินก็หวาดหวั่นไหว ท้องฟ้าก็ปล่อยลงมา เออ เมฆก็ปล่อยฝนลงมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 5, 'ภูเขาก็ละลายต่อพระพักตร์พระเยโฮวาห์ รวมทั้งภูเขาซีนายต่อพระพักตร์พระเยโฮวาห์พระเจ้าของอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 6, 'ในสมัยชัมการ์บุตรชายอานาท สมัยยาเอล ทางหลวงก็หยุดชะงัก ผู้สัญจรไปมาก็หลบไปเดินตามทางซอย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 7, 'ชาวไร่ชาวนาในอิสราเอลก็หยุดยั้ง เขาหยุดยั้งจนดิฉันเดโบราห์ขึ้นมา จนดิฉันขึ้นมาเป็นอย่างมารดาอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 8, 'เมื่อเลือกนับถือพระใหม่ สงครามก็ประชิดเข้ามาถึงประตูเมือง เห็นมีโล่หรือหอกสักอันหนึ่งในพลอิสราเอลสี่หมื่นคนหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 9, 'จิตใจของข้าพเจ้านิยมชมชอบในบรรดาเจ้าเมืองของอิสราเอล ผู้อาสาสมัครท่ามกลางประชาชน จงถวายสาธุการแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 10, 'บรรดาท่านผู้ที่ขี่ลาเผือก จงบอกกล่าวให้ทราบเถิด ทั้งท่านผู้ที่นั่งพิพากษาและท่านที่สัญจรไปมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 11, 'คนที่รอดพ้นจากเสียงนักธนู ณ ที่ตักน้ํา เขากล่าวถึงกิจการอันชอบธรรมของพระเยโฮวาห์ คือกิจการอันชอบธรรมต่อชาวไร่ชาวนาในอิสราเอล แล้วชนชาติของพระเยโฮวาห์ก็เดินไปที่ประตูเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 12, 'ตื่นเถิด ตื่นเถิด เดโบราห์เอ๋ย ตื่นเถิด ตื่นมาร้องเพลง ลุกขึ้นเถิด บาราค บุตรชายอาบีโนอัมเอ๋ย พาพวกเชลยของท่านไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 13, 'ครั้งนั้นพระองค์ทรงกระทําให้ผู้ที่เหลืออยู่ปกครองพวกขุนนางของประชาชน พระเยโฮวาห์ทรงกระทําให้ข้าพเจ้าปกครองผู้มีกําลัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 14, 'ผู้ที่มีรากอยู่ในอามาเลขได้ลงมาจากเอฟราอิม เขาเดินตามท่านนะ เบนยามินท่ามกลางประชาชนของท่าน ผู้บังคับบัญชาเดินลงมาจากมาคีร์และผู้บันทึกรายงานของจอมพลออกมาจากเศบูลุน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 15, 'เจ้านายทั้งหลายของอิสสาคาร์มากับเดโบราห์ และอิสสาคาร์กับบาราคด้วย เขาเร่งติดตามท่านไปในหุบเขา มีความตั้งใจอย่างยิ่งเพื่อกองพลคนรูเบน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 16, 'ไฉนท่านจึงรั้งรออยู่ที่คอกแกะเพื่อจะฟังเสียงปี่ที่เขาเป่าให้แกะฟัง เพื่อกองพลคนรูเบนมีการพิจารณาความมุ่งหมายของจิตใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 17, 'กิเลอาดอยู่ฟากแม่น้ําจอร์แดนข้างโน้น ส่วนดานอาศัยอยู่กับเรือกําปั่นทําไมเล่า อาเชอร์นั่งเฉยอยู่ที่ฝั่งทะเลตั้งบ้านเรือนอยู่ตามท่าจอดเรือของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 18, 'เศบูลุนกับนัฟทาลีเป็นคนที่เสี่ยงชีวิตเข้าสู่ความตาย ณ ที่สูงในสนามรบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 19, 'พอบรรดากษัตริย์มาถึงก็รบกัน บรรดากษัตริย์คานาอันก็รบที่ทาอานาคริมห้วงน้ําเมกิดโดโดยมิได้ริบเงินเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 20, 'ดวงดาวก็สู้รบจากสวรรค์จากวิถีของมัน มันทั้งหลายรบกับสิเสรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 21, 'แม่น้ําคีโชนพัดกวาดเขาไปเสีย คือแม่น้ําคีโชน แม่น้ําโบราณนั้น โอ จิตของข้าพเจ้าเอ๋ย เจ้าได้เหยียบย่ําด้วยกําลังแข็งขัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 22, 'แล้วเสียงกีบม้าก็กระทบแรงโดยม้าของเขาวิ่งควบไป ม้าที่มีอํานาจใหญ่โตวิ่งควบไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 23, 'ทูตสวรรค์ของพระเยโฮวาห์กล่าวว่า ‘จงสาปแช่งเมโรสเถิด จงสาปแช่งชาวเมืองให้หนัก เพราะเขาไม่ได้ออกมาช่วยพระเยโฮวาห์ คือช่วยพระเยโฮวาห์สู้ผู้มีกําลังมาก’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 24, 'หญิงที่น่าสรรเสริญมากที่สุดก็คือยาเอลภรรยาของเฮเบอร์คนเคไนต์ เป็นหญิงที่น่าสรรเสริญมากที่สุดที่อยู่เต็นท์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 25, 'เขาขอน้ํา นางก็ให้น้ํานม นางเอาเนยข้นใส่ชามหลวงมายื่นให้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 26, 'นางเอื้อมมือหยิบหลักเต็นท์ ข้างมือขวาของนางฉวยตะลุมพุก นางตอกสิเสราเข้าทีหนึ่ง นางบี้ศีรษะของสิเสรา นางตีทะลุขมับของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 27, 'เขาจมลง เขาล้ม เขานอนที่เท้าของนาง ที่เท้าของนางเขาจมลง เขาล้ม เขาจมลงที่ไหน ที่นั่นเขาล้มลงตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 28, 'มารดาของสิเสรามองออกไปตามช่องหน้าต่าง นางมองไปตามบานเกล็ด ร้องว่า ‘ทําไมหนอ รถรบของเขาจึงมาช้าเหลือเกิน ทําไมล้อรถรบของเขาจึงเนิ่นช้าอยู่’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 29, 'บรรดาสตรีผู้ฉลาดของนางจึงตอบนาง เปล่าดอก นางนึกตอบเอาเองว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 30, '‘เขาทั้งหลายยังไม่พบและยังไม่แบ่งของที่ริบมาได้หรือ หญิงคนหนึ่งหรือสองคนได้แก่ชายคนหนึ่ง สิ่งของหลากสีที่ริบมาเป็นของสิเสรา ของหลากสีที่ปักลวดลาย ของหลากสีที่ปักลวดลายสองหน้าสําหรับพันคอของข้าเป็นของที่ริบ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 31, 'โอ ข้าแต่พระเยโฮวาห์ ขอศัตรูทั้งปวงของพระองค์พินาศสิ้นดังนี้ แต่ขอให้ผู้ที่รักพระองค์เปรียบดังดวงอาทิตย์เมื่อโผล่ขึ้นด้วยอานุภาพ” และแผ่นดินก็หยุดพักสงบอยู่สี่สิบปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 1, 'และคนอิสราเอลก็ได้กระทําชั่วในสายพระเนตรของพระเยโฮวาห์ และพระเยโฮวาห์ทรงมอบเขาไว้ในมือของคนมีเดียนเจ็ดปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 2, 'และมือของคนมีเดียนก็มีชัยชนะต่ออิสราเอล เพราะเหตุคนมีเดียน ประชาชนอิสราเอลจึงต้องทําที่หลบซ่อนซึ่งอยู่ในภูเขาให้แก่ตนเอง คือถ้ํา และที่กําบังที่เข้มแข็ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 3, 'เพราะว่าคนอิสราเอลหว่านพืชเมื่อไร คนมีเดียนและคนอามาเลขและชาวตะวันออกก็ขึ้นมาสู้รบกับเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 4, 'เขามาตั้งค่ายไว้แล้วทําลายพืชผลแห่งแผ่นดินเสีย ไกลไปถึงเมืองกาซา ไม่ให้มีเครื่องบริโภคเหลือในอิสราเอลเลย ไม่ว่าแกะ หรือวัว หรือลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 5, 'เพราะว่าคนเหล่านั้นจะขึ้นมาพร้อมทั้งฝูงสัตว์และเต็นท์ เขามาเหมือนตั๊กแตนเป็นฝูงๆ ทั้งคนและอูฐก็นับไม่ถ้วน เมื่อเขาเข้ามา เขาก็ทําลายแผ่นดินเสียอย่างนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 6, 'พวกอิสราเอลจึงตกต่ําลงมากเพราะคนมีเดียน คนอิสราเอลก็ร้องทุกข์ถึงพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 7, 'ต่อมาเมื่อคนอิสราเอลร้องทุกข์ถึงพระเยโฮวาห์ เพราะคนมีเดียน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 8, 'พระเยโฮวาห์ก็ทรงใช้ผู้พยากรณ์คนหนึ่งให้มาหาคนอิสราเอล ผู้นั้นพูดกับเขาทั้งหลายว่า “พระเยโฮวาห์พระเจ้าของอิสราเอลตรัสดังนี้ว่า ‘เราได้นําพวกเจ้าขึ้นมาจากอียิปต์ นําเจ้าออกมาจากเรือนทาส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 9, 'และเราได้ช่วยเจ้าให้พ้นจากเงื้อมมือของชาวอียิปต์ และให้พ้นจากมือของบรรดาผู้ที่บีบบังคับเจ้า และขับไล่เขาให้ออกไปเสียให้พ้นหน้าเจ้า และมอบแผ่นดินของเขาให้แก่เจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 10, 'และเราบอกกับเจ้าว่า “เราคือพระเยโฮวาห์พระเจ้าของเจ้า เจ้าอย่าเกรงกลัวพระของคนอาโมไรต์ ในแผ่นดินของเขาซึ่งเจ้าอาศัยอยู่นั้น” แต่เจ้าทั้งหลายหาได้เชื่อฟังเสียงของเราไม่’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 11, 'ฝ่ายทูตสวรรค์องค์หนึ่งของพระเยโฮวาห์มานั่งอยู่ที่ใต้ต้นโอ๊กที่ตําบลโอฟราห์ ซึ่งเป็นของโยอาช คนอาบีเยเซอร์ ฝ่ายกิเดโอนบุตรชายของท่านกําลังนวดข้าวสาลีอยู่ในบ่อย่ําองุ่นเพื่อซ่อนให้พ้นตาคนมีเดียน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 12, 'ทูตสวรรค์ของพระเยโฮวาห์ปรากฏแก่กิเดโอนพูดกับเขาว่า “เจ้าบุรุษผู้กล้าหาญเอ๋ย พระเยโฮวาห์ทรงสถิตกับเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 13, 'กิเดโอนจึงทูลท่านผู้นั้นว่า “โอ ท่านเจ้าข้า ถ้าพระเยโฮวาห์ทรงสถิตกับพวกเราแล้ว ไฉนเหตุเหล่านี้จึงเกิดขึ้นแก่เราเล่า และการอัศจรรย์ทั้งหลายของพระองค์ซึ่งบรรพบุรุษเคยเล่าให้เราฟังว่า ‘พระเยโฮวาห์ทรงนําเราออกจากอียิปต์มิใช่หรือ’ แต่สมัยนี้พระเยโฮวาห์ทรงทอดทิ้งเราเสียแล้ว และทรงมอบเราไว้ในมือของพวกมีเดียน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 14, 'และพระเยโฮวาห์ทรงหันมาหาเขาตรัสว่า “จงไปช่วยคนอิสราเอลให้พ้นจากเงื้อมมือพวกมีเดียนด้วยกําลังของเจ้านี่แหละ เราใช้เจ้าให้ไปแล้ว มิใช่หรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 15, 'กิเดโอนจึงกราบทูลว่า “โอ ข้าแต่องค์พระผู้เป็นเจ้า ข้าพระองค์จะช่วยอิสราเอลได้อย่างไร ดูเถิด ครอบครัวของข้าพระองค์ต่ําต้อยที่สุดในคนมนัสเสห์ และตัวข้าพระองค์ก็เป็นคนเล็กน้อยที่สุดในวงศ์วานบิดาของข้าพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 16, 'พระเยโฮวาห์ตรัสกับเขาว่า “แต่เราจะอยู่กับเจ้าแน่ และเจ้าจะได้โจมตีคนมีเดียนอย่างกับตีคนคนเดียว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 17, 'เขาก็ทูลพระองค์ว่า “ถ้าบัดนี้ข้าพระองค์ได้รับพระกรุณาในสายพระเนตรของพระองค์ ขอทรงโปรดสําแดงหมายสําคัญอย่างหนึ่งแก่ข้าพระองค์ว่า พระองค์เองตรัสกับข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 18, 'ขอพระองค์อย่าเสด็จไปเสียจากที่นี่จนกว่าข้าพระองค์จะกลับมาหาพระองค์ และนําของมาตั้งถวายต่อพระพักตร์” และพระองค์ตรัสว่า “เราจะคอยอยู่จนกว่าเจ้าจะกลับมาอีก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 19, 'กิเดโอนก็กลับเข้าบ้าน จัดลูกแพะตัวหนึ่งกับแป้งเอฟาห์หนึ่งทําขนมไร้เชื้อ เขาเอาเนื้อใส่กระจาด ส่วนน้ําแกงใส่ในหม้อ นําสิ่งเหล่านี้มาถวายพระองค์ที่ใต้ต้นโอ๊ก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 20, 'และทูตสวรรค์ของพระเจ้าบอกเขาว่า “จงเอาเนื้อและขนมไร้เชื้อวางไว้บนศิลานี้ เทน้ําแกงราดของเหล่านั้น” กิเดโอนก็กระทําตาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 21, 'แล้วทูตสวรรค์ของพระเยโฮวาห์ก็เอาปลายไม้ที่ถืออยู่แตะต้องเนื้อและขนมไร้เชื้อ และมีไฟลุกขึ้นมาจากศิลาไหม้เนื้อและขนมไร้เชื้อจนหมด และทูตสวรรค์ของพระเยโฮวาห์ก็หายไปพ้นสายตาของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 22, 'กิเดโอนก็ทราบว่าเป็นทูตสวรรค์องค์หนึ่งของพระเยโฮวาห์จริง และกิเดโอนพูดว่า “โอ องค์พระผู้เป็นเจ้าพระเจ้าเจ้าข้า บัดนี้ข้าพระองค์ได้เห็นทูตสวรรค์องค์หนึ่งของพระเยโฮวาห์ต่อหน้าต่อตา อนิจจาเอ๋ย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 23, 'แต่พระเยโฮวาห์ตรัสกับกิเดโอนว่า “สันติภาพจงมีอยู่แก่เจ้า เจ้าอย่ากลัวเลย เพราะเจ้าจะไม่ตาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 24, 'ฝ่ายกิเดโอนก็สร้างแท่นบูชาแท่นหนึ่งถวายพระเยโฮวาห์ที่นั่น และเรียกตําบลนั้นว่า พระเยโฮวาห์ชาโลม ทุกวันนี้แท่นนั้นก็ยังอยู่ที่โอฟราห์ ซึ่งเป็นของคนอาบีเยเซอร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 25, 'อยู่มาในคืนวันนั้นพระเยโฮวาห์ตรัสสั่งกิเดโอนว่า “จงเอาวัวหนุ่มของบิดา คือวัวผู้ตัวที่สองที่มีอายุเจ็ดปีมา ไปพังแท่นพระบาอัลซึ่งบิดาของเจ้ามีอยู่นั้นลงเสีย จงโค่นเสารูปเคารพซึ่งอยู่ข้างๆแท่นเสียด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 26, 'และสร้างแท่นบูชาถวายแด่พระเยโฮวาห์พระเจ้าของเจ้าที่บนป้อมนี้ ใช้ก้อนหินก่อให้เป็นระเบียบ แล้วนําวัวตัวที่สองนั้นฆ่าเสียถวายเป็นเครื่องเผาบูชา เผาด้วยไม้เสารูปเคารพซึ่งเจ้าโค่นมานั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 27, 'กิเดโอนจึงนําคนใช้สิบคนไปกระทําตามที่พระเยโฮวาห์ตรัสสั่งแก่เขา แต่เพราะกิเดโอนกลัวครอบครัวบิดาของตนและกลัวชาวเมือง จนไม่กล้าทํากลางวันจึงกระทําในเวลากลางคืน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 28, 'เมื่อชาวเมืองตื่นขึ้นในเช้าตรู่วันรุ่งขึ้น ดูเถิด แท่นบูชาพระบาอัลพังทลาย และเสารูปเคารพที่อยู่ข้างๆก็ถูกโค่นลง และมีวัวผู้ตัวที่สองวางบูชาอยู่บนแท่นที่สร้างขึ้นใหม่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 29, 'เขาจึงพูดกันและกันว่า “ใครทําอย่างนี้นะ” เมื่อเขาได้สืบถามแล้ว เขาทั้งหลายจึงกล่าวว่า “กิเดโอนบุตรชายของโยอาชได้กระทําสิ่งนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 30, 'แล้วชาวเมืองจึงบอกโยอาชว่า “จงมอบลูกของเจ้านั้นมาให้ประหารชีวิตเสีย เพราะเขาได้พังแท่นของพระบาอัลและโค่นเสารูปเคารพที่อยู่ข้างแท่นนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 31, 'แต่โยอาชได้ตอบคนที่มาฟ้องนั้นว่า “ท่านทั้งหลายจะเป็นพยานแทนพระบาอัลหรือ จะสู้ความแทนหรือ ผู้ใดที่เป็นทนายแทนพระบาอัลจะต้องถูกประหารชีวิตเช้านี้แหละ ถ้าพระบาอัลเป็นพระแท้ก็ให้สู้คดีเองเถิด เพราะมีคนมาพังแท่นของท่านลง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 32, 'วันนั้นเขาจึงตั้งชื่อท่านว่า เยรุบบาอัล ใจความว่า “ให้บาอัลสู้คดีเอง” เพราะเขาพังแท่นของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 33, 'ครั้งนั้นบรรดาคนมีเดียน และคนอามาเลข และชาวตะวันออกก็รวมกันยกทัพข้ามไปตั้งค่ายอยู่ในหุบเขายิสเรเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 34, 'แต่พระวิญญาณของพระเยโฮวาห์ทรงสถิตกับกิเดโอน ท่านก็เป่าแตร เรียกคนอาบีเยเซอร์ให้มาติดตามท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 35, 'และท่านส่งผู้สื่อสารไปทั่วมนัสเสห์ เรียกให้เขายกติดตามท่านไปด้วย และท่านส่งผู้สื่อสารไปยังอาเชอร์ เศบูลุน และนัฟทาลี คนเหล่านี้ก็ขึ้นมาปะทะข้าศึกด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 36, 'กิเดโอนจึงทูลพระเจ้าว่า “ถ้าพระองค์จะช่วยอิสราเอลให้พ้นด้วยมือของข้าพระองค์ ดังที่พระองค์ตรัสแล้วนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 37, 'ดูเถิด ข้าพระองค์ได้วางกลุ่มขนแกะไว้ที่ลานนวดข้าว แม้มีน้ําค้างเฉพาะที่กลุ่มขนแกะเท่านั้น ส่วนที่พื้นดินโดยรอบนั้นแห้ง ข้าพระองค์ก็จะทราบว่า พระองค์จะทรงช่วยอิสราเอลให้พ้นด้วยมือของข้าพระองค์ ดังที่พระองค์ตรัสนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 38, 'ก็เป็นไปดังนั้น เมื่อกิเดโอนตื่นขึ้นในวันรุ่งเช้าก็บีบกลุ่มขนแกะ เขาบีบได้น้ําค้างจากกลุ่มขนแกะจนเต็มชาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 39, 'แล้วกิเดโอนจึงทูลพระเจ้าว่า “ขออย่าให้พระพิโรธพลุ่งขึ้นต่อข้าพระองค์ ขอข้าพระองค์ทูลอีกสักครั้งเดียว ขอข้าพระองค์ทดลองด้วยกลุ่มขนแกะนี้อีกครั้งหนึ่งเถิด คราวนี้ขอให้แห้งเฉพาะที่กลุ่มขนแกะ ส่วนที่พื้นดินนั้นให้มีน้ําค้างโดยทั่วไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 40, 'ในคืนวันนั้นพระเจ้าก็ทรงกระทําตามที่ขอ คือกลุ่มขนแกะนั้นแห้งอยู่ แต่มีน้ําค้างอยู่ทั่วพื้นดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 1, 'เยรุบบาอัล คือกิเดโอน และบรรดาคนที่อยู่กับท่านก็ลุกขึ้นตั้งแต่เช้าตรู่ไปตั้งค่ายอยู่ที่ริมน้ําพุฮาโรด ฝ่ายค่ายของพวกมีเดียนอยู่ทางเหนือของเขา อยู่ในหุบเขาที่ภูเขาโมเรห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 2, 'พระเยโฮวาห์ตรัสกับกิเดโอนว่า “คนที่อยู่กับเจ้ายังมีมากเกินที่เราจะมอบคนมีเดียนไว้ในมือของเขา เกรงว่าอิสราเอลจะทะนงตัวต่อเรา โดยกล่าวว่า ‘มือของเราเองได้ช่วยเราให้พ้น’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 3, 'เพราะฉะนั้นบัดนี้จงประกาศให้เข้าหูคนทั้งปวงว่า ‘ผู้ใดที่กลัวและสั่นเทิ้มอยู่ ก็ให้ผู้นั้นกลับเสีย และไปจากภูเขากิเลอาดโดยเร็ว’” และมีคนกลับไปสองหมื่นสองพันคน และยังเหลืออยู่หนึ่งหมื่นคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 4, 'พระเยโฮวาห์ตรัสกับกิเดโอนว่า “ประชาชนยังมากอยู่ จงพาเขาลงไปที่น้ําและเราจะทําการทดสอบเขาให้เจ้าที่นั่น ผู้ที่เราจะบอกเจ้าว่า ‘ให้คนนี้ไปกับเจ้า’ ผู้นั้นต้องไปกับเจ้า ผู้ที่เราบอกว่า ‘คนนี้อย่าให้ไป’ ผู้นั้นไม่ต้องไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 5, 'ท่านจึงพาประชาชนลงไปที่น้ํา พระเยโฮวาห์ตรัสกับกิเดโอนว่า “ทุกคนที่ใช้ลิ้นเลียน้ําดังสุนัข จงรวมเขาไว้พวกหนึ่ง ทุกคนที่คุกเข่าลงดื่มน้ํา จงรวมไว้อีกพวกหนึ่งดุจกัน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 6, 'จํานวนคนที่ใช้มือวักน้ําขึ้นเลียมีสามร้อยคน แต่ประชาชนนอกนั้นคุกเข่าลงดื่มน้ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 7, 'พระเยโฮวาห์ตรัสกับกิเดโอนว่า “เราจะช่วยเจ้าทั้งหลายให้พ้นด้วยจํานวนคนสามร้อยที่เลียน้ํานั้น และมอบคนมีเดียนไว้ในมือของเจ้า นอกนั้นให้กลับไปบ้านเมืองของตนทุกคน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 8, 'ประชาชนจึงถือเสบียงและแตรไว้ และท่านสั่งให้อิสราเอลที่เหลืออยู่กลับไปยังเต็นท์ของตนทุกคน แต่ให้สามร้อยคนนั้นอยู่ และค่ายของมีเดียนก็อยู่ข้างล่างท่านในหุบเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 9, 'อยู่มาในคืนวันนั้นพระเยโฮวาห์ตรัสกับท่านว่า “จงลุกขึ้น ลงไปยังค่ายเถิด ด้วยเรามอบเขาไว้ในมือของเจ้าแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 10, 'แต่ถ้าเจ้ากลัวไม่กล้าลงไป จงพาปูราห์คนใช้ของเจ้าไปด้วยให้ถึงค่ายนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 11, 'เจ้าจะได้ยินว่าเขาพูดอะไรกัน ภายหลังมือของเจ้าจะมีกําลังขึ้นที่จะลงไปตีค่ายนั้น” ท่านจึงไปกับปูราห์คนใช้ของท่าน ไปถึงทหารถืออาวุธด้านนอกซึ่งอยู่ในค่าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 12, 'ฝ่ายคนมีเดียน และคนอามาเลข กับบรรดาชาวตะวันออก นอนอยู่ตามหุบเขาเหมือนตั๊กแตนเป็นฝูงๆ ฝูงอูฐของเขาก็นับไม่ถ้วน มากดุจเม็ดทรายที่ฝั่งทะเล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 13, 'ครั้นกิเดโอนแอบมา ดูเถิด มีชายคนหนึ่งเล่าความฝันให้เพื่อนฟังว่า “ดูเถิด เราฝันเรื่องหนึ่ง ดูเถิด มีขนมข้าวบาร์เลย์ก้อนหนึ่งกลิ้งเข้ามาในค่ายของพวกมีเดียน มาถึงเต็นท์โดนเต็นท์ทําให้เต็นท์ล้มลง พลิกขึ้น แล้วก็ราบไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 14, 'เพื่อนของเขาจึงตอบว่า “นี่ไม่ใช่อื่นไกลเลย นอกจากดาบของกิเดโอนบุตรชายโยอาชบุรุษของอิสราเอล พระเจ้าได้ทรงมอบพวกมีเดียน และกองทัพทั้งสิ้นไว้ในมือของเขาแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 15, 'เมื่อกิเดโอนได้ยินเขาเล่าความฝันและคําแก้ฝันเช่นนั้นแล้ว ท่านก็นมัสการ และกลับไปสู่ค่ายอิสราเอลสั่งว่า “จงลุกขึ้นเถิด เพราะว่าพระเยโฮวาห์ทรงมอบกองทัพคนมีเดียนไว้ในมือของท่านทั้งหลายแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 16, 'ท่านจึงแบ่งคนสามร้อยนั้นออกเป็นสามกองให้ถือแตรทุกคน และถือหม้อเปล่า มีคบเพลิงอยู่ข้างในหม้อนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 17, 'และท่านสั่งเขาว่า “จงคอยดูเรา แล้วให้ทําเหมือนกัน และดูเถิด เมื่อเราไปถึงค่ายด้านนอกแล้ว เรากระทําอย่างไรก็จงกระทําอย่างนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 18, 'ขณะเมื่อเราเป่าแตร คือตัวเรากับบรรดาคนที่อยู่กับเรา เจ้าจงเป่าแตรรับให้รอบค่ายทั้งหมดแล้วร้องว่า ‘ดาบของพระเยโฮวาห์และของกิเดโอน’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 19, 'กิเดโอนกับทหารหนึ่งร้อยคนที่อยู่กับท่านก็มาถึงด้านนอกค่ายในเวลาต้นยามกลาง พึ่งพลัดเวรยามใหม่ เขาก็เป่าแตรขึ้นและต่อยหม้อซึ่งอยู่ในมือให้แตก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 20, 'ทหารทั้งสามกองก็เป่าแตรและต่อยหม้อ มือซ้ายถือคบเพลิง มือขวาถือแตรจะเป่า และเขาร้องขึ้นว่า “ดาบของพระเยโฮวาห์และของกิเดโอน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 21, 'ต่างก็ยืนอยู่ตามที่ของตนเรียงรายรอบค่าย บรรดากองทัพก็ร้องอื้ออึงวิ่งหนีไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 22, 'เมื่อเขาเป่าแตรทั้งสามร้อยอันนั้น พระเยโฮวาห์ทรงบันดาลให้เขาฆ่าฟันกันทั่วทุกกอง กองทัพก็แตกตื่นหนีไปถึงตําบลเบธชิทธาห์ทางไปเมืองเศเรราห์ไกลไปจนถึงเขตเมืองอาเบลเมโฮลาห์ที่ตําบลทับบาท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 23, 'คนอิสราเอลถูกเรียกออกมาจากนัฟทาลี และจากอาเชอร์ และจากทั่วมนัสเสห์ และพร้อมกันติดตามพวกมีเดียนไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 24, 'และกิเดโอนก็ใช้ผู้สื่อสารออกไปทั่วแดนเทือกเขาเอฟราอิม ประกาศว่า “จงลงมารบพวกมีเดียน และยึดแควทั้งหลาย ไกลไปถึงตําบลเบธบาราห์ และแม่น้ําจอร์แดนด้วย” เขาก็เรียกบรรดาทหารเอฟราอิมออกมา เขาทั้งหลายยึดแควถึงเบธบาราห์ และแม่น้ําจอร์แดนไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 25, 'จับโอเรบและเศเอบเจ้านายสองคนของพวกมีเดียนได้ เขาฆ่าโอเรบเสียที่ศิลาโอเรบ และฆ่าเศเอบเสียที่บ่อย่ําองุ่นชื่อเศเอบ แล้วก็ไล่ติดตามพวกมีเดียนไป และเขานําเอาศีรษะโอเรบและเศเอบมาให้กิเดโอนที่ฟากแม่น้ําจอร์แดนข้างโน้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 1, 'คนเอฟราอิมจึงพูดกับท่านว่า “ทําไมท่านจึงกระทําแก่เราอย่างนี้ คือเมื่อท่านยกไปต่อสู้พวกมีเดียนนั้น ท่านก็ไม่ได้เชิญเราให้ไปรบด้วย” และเขาทั้งหลายก็ต่อว่าท่านอย่างรุนแรง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 2, 'ท่านจึงตอบเขาทั้งหลายว่า “สิ่งที่เราทํามาแล้วจะเปรียบเทียบกับสิ่งที่ท่านทั้งหลายทําแล้วได้หรือ ผลองุ่นที่ชาวเอฟราอิมเก็บเล็มก็ยังดีกว่าผลองุ่นที่อาบีเยเซอร์เก็บเกี่ยวมิใช่หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 3, 'พระเจ้าประทานโอเรบและเศเอบ เจ้านายมีเดียนไว้ในมือของท่าน ข้าพเจ้าสามารถกระทําอะไรที่จะเทียบกับท่านได้เล่า” เมื่อท่านพูดอย่างนี้ เขาทั้งหลายก็หายโกรธ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 4, 'กิเดโอนก็มาที่แม่น้ําจอร์แดนและข้ามไป ทั้งท่านและทหารสามร้อยคนที่อยู่ด้วย ถึงจะอ่อนเปลี้ยแต่ก็ยังติดตามไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 5, 'ท่านจึงพูดกับชาวเมืองสุคคทว่า “ขอขนมปังให้คนที่ติดตามเรามาบ้าง เพราะเขาอ่อนเปลี้ย เรากําลังไล่ติดตามเศบาห์และศัลมุนนากษัตริย์แห่งมีเดียน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 6, 'เจ้านายของเมืองสุคคทจึงตอบว่า “มือของเศบาห์และของศัลมุนนาอยู่ในมือเจ้าแล้วหรือ เราจึงจะเอาขนมปังมาเลี้ยงกองทัพของเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 7, 'กิเดโอนจึงกล่าวว่า “ถ้าอย่างนั้นเมื่อพระเยโฮวาห์มอบเศบาห์และศัลมุนนาไว้ในมือเราแล้ว เราจะเอาหนามใหญ่แห่งถิ่นทุรกันดาร และหนามย่อยมานวดเนื้อเจ้าทั้งหลาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 8, 'ท่านก็ออกจากที่นั่นขึ้นไปยังเมืองเปนูเอล และพูดกับเขาในทํานองเดียวกัน ชาวเมืองเปนูเอลก็ตอบท่านอย่างเดียวกับที่ชาวเมืองสุคคทตอบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 9, 'ท่านจึงพูดกับชาวเมืองเปนูเอลด้วยว่า “เมื่อเรากลับมาด้วยสันติภาพ เราจะพังป้อมนี้ลงเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 10, 'ฝ่ายเศบาห์และศัลมุนนาอาศัยอยู่ที่คารโครกับกองทัพมีทหารหนึ่งหมื่นห้าพันคน เป็นกองทัพชาวตะวันออกที่เหลืออยู่ทั้งหมด เพราะว่าผู้ที่ถือดาบล้มตายเสียหนึ่งแสนสองหมื่นคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 11, 'กิเดโอนขึ้นไปตามทางสัญจรของคนที่อาศัยในเต็นท์ ทิศตะวันออกของเมืองโนบาห์และเมืองโยกเบฮาห์เข้าโจมตีกองทัพได้แล้ว เพราะว่ากองทัพคิดว่าพ้นภัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 12, 'เศบาห์และศัลมุนนาก็หนีไป กิเดโอนก็ไล่ติดตามไปจับเศบาห์กับศัลมุนนากษัตริย์พวกมีเดียนทั้งสององค์ได้ และทํากองทัพทั้งหมดให้แตกตื่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 13, 'ฝ่ายกิเดโอนบุตรชายโยอาชก็กลับจากการศึกก่อนดวงอาทิตย์ขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 14, 'จับชายหนุ่มชาวเมืองสุคคทได้คนหนึ่ง จึงซักถามเขา ชายคนนี้ก็เขียนชื่อเจ้านายและพวกผู้ใหญ่ของเมืองสุคคทให้ รวมเจ็ดสิบเจ็ดคนด้วยกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 15, 'กิเดโอนจึงมาหาชาวเมืองสุคคทกล่าวว่า “จงมาดูเศบาห์และศัลมุนนา ซึ่งเมื่อก่อนเจ้าเยาะเย้ยเราว่า ‘มือของเศบาห์และของศัลมุนนาอยู่ในมือเจ้าแล้วหรือ เราจะได้เลี้ยงทหารที่เหน็ดเหนื่อยของเจ้าด้วยขนมปัง’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 16, 'กิเดโอนก็จับพวกผู้ใหญ่ในเมืองเอาหนามใหญ่แห่งถิ่นกันดาร และหนามย่อยด้วย มาสั่งสอนชาวเมืองสุคคท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 17, 'ท่านก็พังป้อมเมืองเปนูเอล และประหารชีวิตชาวเมืองเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 18, 'ท่านจึงถามเศบาห์และศัลมุนนาว่า “คนที่เจ้าฆ่าเสียที่ทาโบร์เป็นคนแบบไหน” เขาตอบว่า “ท่านเป็นอย่างไร เขาก็เป็นอย่างนั้น เป็นเหมือนราชบุตรทุกคน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 19, 'กิเดโอนจึงกล่าวว่า “คนเหล่านั้นเป็นพี่น้องท้องเดียวกันกับเรา พระเยโฮวาห์ทรงพระชนม์อยู่แน่ฉันใด ถ้าเจ้าไว้ชีวิตเขา เราก็จะไม่ประหารชีวิตเจ้าแน่ฉันนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 20, 'แล้วท่านสั่งเยเธอร์บุตรหัวปีของท่านว่า “จงลุกขึ้นฆ่าเขาทั้งสองเสีย” แต่หนุ่มคนนั้นไม่ยอมชักดาบออก ด้วยว่าเขากลัว เพราะเขายังหนุ่มอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 21, 'ฝ่ายเศบาห์กับศัลมุนนาจึงว่า “ท่านลุกขึ้นฟันเราเองซิ เป็นผู้ใหญ่เท่าใดกําลังก็แข็งเท่านั้น” กิเดโอนก็ลุกขึ้นฆ่าเศบาห์และศัลมุนนาเสีย แล้วเก็บเครื่องประดับที่คออูฐของเขาไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 22, 'ครั้งนั้นคนอิสราเอลก็เรียนกิเดโอนว่า “ขอจงปกครองพวกข้าพเจ้าทั้งหลายเถิด ทั้งตัวท่านและลูกหลานของท่านสืบไปด้วย เพราะว่าท่านได้ช่วยเราทั้งหลายให้พ้นจากมือของมีเดียน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 23, 'กิเดโอนจึงตอบเขาทั้งหลายว่า “เราจะไม่ปกครองท่านทั้งหลาย และบุตรชายของเราก็จะไม่ปกครองท่านทั้งหลาย พระเยโฮวาห์จะทรงปกครองท่านทั้งหลายเอง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 24, 'กิเดโอนก็บอกคนเหล่านั้นว่า “เราจะขอสิ่งหนึ่งจากท่านทั้งหลาย คือขอให้ทุกคนถวายตุ้มหูซึ่งริบมาได้นั้น” (ด้วยว่าคนเหล่านั้นมีตุ้มหูทองคําเพราะเป็นชนอิชมาเอล)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 25, 'เขาก็เรียนตอบท่านว่า “เราทั้งหลายเต็มใจจะให้” เขาก็ปูผ้าลง วางตุ้มหูซึ่งริบมาได้นั้นไว้ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 26, 'ตุ้มหูทองคําซึ่งท่านขอได้นั้นมีน้ําหนักหนึ่งพันเจ็ดร้อยเชเขลทองคํา นอกจากนี้ยังมีเครื่องประดับ จี้และฉลององค์สีม่วงซึ่งกษัตริย์พวกมีเดียนทรง ทั้งเครื่องผูกคออูฐด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 27, 'กิเดโอนก็เอาทองคํานี้ทําเป็นรูปเอโฟดเก็บไว้ที่เมืองของท่านคือโอฟราห์ และบรรดาคนอิสราเอลก็เล่นชู้กับรูปนี้กระทําให้เป็นบ่วงดักกิเดโอนและวงศ์วานของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 28, 'ดังนี้แหละพวกมีเดียนก็พ่ายแพ้ต่อหน้าคนอิสราเอล ไม่อาจยกศีรษะขึ้นอีกได้เลย และแผ่นดินก็พักสงบอยู่ในสมัยของกิเดโอนถึงสี่สิบปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 29, 'ฝ่ายเยรุบบาอัลบุตรชายของโยอาชก็ไปอาศัยอยู่ในบ้านของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 30, 'กิเดโอนมีบุตรชายเกิดจากบั้นเอวของท่านเจ็ดสิบคน เพราะท่านมีภรรยาหลายคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 31, 'เมียน้อยของกิเดโอนที่อยู่ ณ เมืองเชเคมก็คลอดบุตรชายให้ท่านคนหนึ่งด้วย ท่านตั้งชื่อว่าอาบีเมเลค');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 32, 'กิเดโอนบุตรชายของโยอาชมีอายุชราลงมากก็สิ้นชีวิต เขาฝังท่านไว้ที่เมืองโอฟราห์ของคนอาบีเยเซอร์ ในอุโมงค์ฝังศพโยอาชบิดาของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 33, 'อยู่มาเมื่อกิเดโอนสิ้นชีวิตแล้ว คนอิสราเอลก็หันกลับอีก และเล่นชู้กับพระบาอัล ถือว่าบาอัลเบรีทเป็นพระของเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 34, 'คนอิสราเอลมิได้ระลึกถึงพระเยโฮวาห์พระเจ้าของตน ผู้ทรงช่วยเขาให้พ้นมือศัตรูทั้งหลายรอบด้าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 35, 'เขามิได้แสดงความเมตตาแก่ครอบครัวเยรุบบาอัล คือกิเดโอน เป็นการตอบแทนความดีทั้งสิ้นซึ่งกิเดโอนได้กระทําแก่คนอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 1, 'ฝ่ายอาบีเมเลคบุตรชายเยรุบบาอัลก็ขึ้นไปหาญาติของมารดาที่เมืองเชเคม แล้วพูดกับเขาและกับครอบครัวที่บ้านของตาว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 2, '“ขอบอกความนี้ให้เข้าหูบรรดาชาวเมืองเชเคมเถิดว่า ‘จะให้บุตรชายเยรุบบาอัลทั้งเจ็ดสิบคนครอบครองท่านทั้งหลายดี หรือจะให้ผู้เดียวปกครองดี’ ขอระลึกไว้ด้วยว่า ตัวข้าพเจ้านี้เป็นกระดูกและเนื้อเดียวกับท่านทั้งหลาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 3, 'ฝ่ายญาติของมารดาของเขาก็กล่าวคําทั้งหมดเหล่านี้ให้เข้าหูบรรดาชาวเชเคม จิตใจของชาวเมืองก็เอนเอียงเข้าข้างอาบีเมเลค ด้วยเขากล่าวกันว่า “เขาเป็นญาติของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 4, 'เขาจึงเอาเงินเจ็ดสิบแผ่นออกจากวิหารพระบาอัลเบรีทมอบให้อาบีเมเลค อาบีเมเลคก็เอาเงินนั้นไปจ้างนักเลงหัวไม้ไว้ติดตามตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 5, 'เขาจึงไปที่บ้านบิดาของเขาที่เมืองโอฟราห์ฆ่าพี่น้องของตน คือบุตรชายเยรุบบาอัลทั้งเจ็ดสิบคนที่ศิลาแผ่นเดียว เหลือแต่โยธามบุตรชายสุดท้องของเยรุบบาอัล เพราะเขาซ่อนตัวเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 6, 'ชาวเมืองเชเคมและชาววงศ์วานมิลโลทั้งสิ้นก็มาประชุมพร้อมกัน ตั้งอาบีเมเลคให้เป็นกษัตริย์ที่ข้างที่ราบแห่งเสาสําคัญที่อยู่ในเมืองเชเคม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 7, 'เมื่อมีคนไปบอกโยธาม เขาก็ขึ้นไปยืนอยู่บนยอดภูเขาเกริซิม แผดเสียงร้องให้เขาทั้งหลายฟังว่า “ชาวเมืองเชเคมเอ๋ย ขอจงฟังข้าพเจ้า เพื่อพระเจ้าจะทรงฟังเสียงของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 8, 'ครั้งหนึ่งต้นไม้ต่างๆได้ออกไปเจิมตั้งต้นไม้ต้นหนึ่งไว้เป็นกษัตริย์ เขาจึงไปเชิญต้นมะกอกเทศว่า ‘เชิญท่านปกครองเราเถิด’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 9, 'แต่ต้นมะกอกเทศตอบเขาว่า ‘จะให้เราทิ้งน้ํามันของเรา ซึ่งเขาใช้ถวายเกียรติแด่พระเจ้าและแก่มนุษย์ เพื่อไปกวัดแกว่งอยู่เหนือต้นไม้ทั้งปวงหรือ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 10, 'แล้วต้นไม้เหล่านั้นจึงไปพูดกับต้นมะเดื่อว่า ‘เชิญท่านมาปกครองเหนือเราเถิด’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 11, 'แต่ต้นมะเดื่อตอบเขาว่า ‘จะให้เราทิ้งรสหวานและผลดีของเราเสีย และไปกวัดแกว่งอยู่เหนือต้นไม้ทั้งหลายหรือ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 12, 'ต้นไม้เหล่านั้นก็ไปพูดกับเถาองุ่นว่า ‘เชิญท่านมาปกครองเหนือเราเถิด’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 13, 'แต่เถาองุ่นกล่าวแก่เขาว่า ‘จะให้เราทิ้งน้ําองุ่นของเรา อันเป็นที่ชื่นใจพระเจ้าและมนุษย์ ไปกวัดแกว่งอยู่เหนือต้นไม้ทั้งหลายหรือ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 14, 'บรรดาต้นไม้ก็ไปพูดกับต้นหนามว่า ‘เชิญท่านมาปกครองเหนือเราเถิด’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 15, 'ต้นหนามจึงตอบต้นไม้เหล่านั้นว่า ‘ถ้าแม้ท่านทั้งหลายจะเจิมตั้งเราให้เป็นกษัตริย์ของเจ้าทั้งหลายจริงๆ จงมาอาศัยใต้ร่มของเราเถิด มิฉะนั้นก็ให้ไฟเกิดจากต้นหนามเผาผลาญต้นสนสีดาร์เลบานอนเสีย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 16, 'ฉะนั้นบัดนี้ซึ่งเจ้าทั้งหลายตั้งอาบีเมเลคเป็นกษัตริย์นั้น ถ้าทําด้วยความจริงใจและเที่ยงธรรม และถ้าได้กระทําให้เหมาะต่อเยรุบบาอัลและครอบครัวของท่าน สมกับความดีที่มือท่านได้กระทําไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 17, '(ด้วยว่าบิดาของเราได้รบพุ่งเพื่อเจ้าทั้งหลาย และเสี่ยงชีวิตช่วยเจ้าทั้งหลายให้พ้นจากมือพวกมีเดียน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 18, 'แต่ในวันนี้เจ้าทั้งหลายได้ลุกขึ้นประทุษร้ายต่อครอบครัวบิดาของเรา ได้ฆ่าบุตรชายทั้งเจ็ดสิบคนของท่านเสียบนศิลาแผ่นเดียว แล้วตั้งอาบีเมเลคบุตรชายของสาวคนใช้ขึ้นเป็นกษัตริย์ปกครองเหนือชาวเชเคม เพราะว่าเขาเป็นญาติของเจ้าทั้งหลาย)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 19, 'ถ้าเจ้าทั้งหลายได้กระทําด้วยความจริงใจและเที่ยงธรรมต่อเยรุบบาอัลและครอบครัวของท่านในวันนี้ ก็จงชื่นชมในอาบีเมเลคเถิด และให้เขามีความชื่นชมยินดีในเจ้าทั้งหลายด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 20, 'แต่ถ้าไม่เป็นอย่างนั้น ก็ขอให้ไฟออกมาจากอาบีเมเลค เผาผลาญชาวเมืองเชเคมและวงศ์วานมิลโล และให้ไฟออกมาจากชาวเมืองเชเคมและจากวงศ์วานมิลโลเผาผลาญอาบีเมเลคเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 21, 'โยธามก็รีบหนีไปยังเบเออร์อาศัยอยู่ที่นั่น เพราะกลัวอาบีเมเลคพี่ชายของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 22, 'เมื่ออาบีเมเลคครอบครองอิสราเอลอยู่ได้สามปีแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 23, 'พระเจ้าทรงใช้วิญญาณชั่วเข้าแทรกระหว่างอาบีเมเลคกับชาวเมืองเชเคม ชาวเมืองเชเคมก็ทรยศต่ออาบีเมเลค');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 24, 'เพื่อความทารุณที่เขาได้กระทําแก่บุตรชายเจ็ดสิบคนของเยรุบบาอัลจะสนอง และโลหิตของคนเหล่านั้นจะได้ตกแก่อาบีเมเลค พี่น้องผู้ได้ประหารเขาและตกแก่ชาวเมืองเชเคม ผู้เสริมกําลังมืออาบีเมเลคให้ฆ่าพี่น้องของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 25, 'ชาวเมืองเชเคมได้วางคนซุ่มซ่อนไว้คอยดักอาบีเมเลคที่บนยอดภูเขา เขาก็ปล้นคนทั้งปวงที่ผ่านไปมาทางนั้น และมีคนบอกอาบีเมเลคให้ทราบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 26, 'ฝ่ายกาอัลบุตรชายเอเบดกับญาติของเขาเข้าไปในเมืองเชเคม ชาวเชเคมไว้เนื้อเชื่อใจกาอัล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 27, 'จึงพากันออกไปในสวนองุ่นเก็บผลมาย่ํา ทําการเลี้ยงสมโภชในวิหารพระของเขา เขารับประทานและดื่ม และแช่งด่าอาบีเมเลคด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 28, 'กาอัลบุตรชายเอเบดจึงกล่าวว่า “อาบีเมเลคคือใคร และเราชาวเชเคมเป็นใครกันจึงต้องมาปรนนิบัติเขา เขาเป็นบุตรชายของเยรุบบาอัลมิใช่หรือ และเศบุลเป็นเจ้าหน้าที่ของเขามิใช่หรือ จงปรนนิบัติคนฮาโมร์บิดาของเชเคมเถิด เราจะปรนนิบัติอาบีเมเลคทําไมเล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 29, 'ถ้าคนเมืองนี้อยู่ใต้ปกครองเรานะ เราจะถอดอาบีเมเลคเสีย” เขาจึงท้าอาบีเมเลคว่า “จงเพิ่มกองทัพของท่านขึ้นแล้วออกมาเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 30, 'พอเศบุลเจ้าเมืองได้ยินถ้อยคําของกาอัลบุตรชายเอเบดก็โกรธ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 31, 'จึงส่งผู้สื่อสารไปยังอาบีเมเลคอย่างลับๆกล่าวว่า “ดูเถิด กาอัลบุตรชายเอเบดและญาติของเขามาที่เมืองเชเคม ดูเถิด พวกเขายุแหย่เมืองนั้นให้ต่อสู้กับท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 32, 'ฉะนั้นบัดนี้ขอท่านจงลุกขึ้นในเวลากลางคืน ทั้งท่านและคนที่อยู่กับท่าน ไปซุ่มคอยอยู่ในทุ่งนา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 33, 'รุ่งเช้าพอดวงอาทิตย์ขึ้นท่านจงลุกขึ้นแต่เช้าตรู่ รีบรุกเข้าเมือง และดูเถิด เมื่อกาอัลกับกองทัพออกมาต่อสู้ท่าน ท่านจงกระทําแก่เขาตามแต่โอกาสจะอํานวย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 34, 'ฝ่ายอาบีเมเลค และกองทัพทั้งสิ้นที่อยู่กับท่านก็ลุกขึ้นในเวลากลางคืน แบ่งออกเป็นสี่กองไปซุ่มคอยสู้เมืองเชเคม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 35, 'กาอัลบุตรชายเอเบดก็ออกไปยืนอยู่ที่ทางเข้าประตูเมือง อาบีเมเลคก็ลุกขึ้นพร้อมกับกองทัพที่อยู่กับท่าน ออกมาจากที่ซุ่มซ่อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 36, 'และเมื่อกาอัลเห็นกองทัพ จึงพูดกับเศบุลว่า “ดูเถิด กองทัพกําลังเคลื่อนลงมาจากยอดภูเขา” เศบุลตอบเขาว่า “ท่านเห็นเงาภูเขาเป็นคนไปกระมัง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 37, 'กาอัลพูดขึ้นอีกว่า “ดูซิ กองทัพกําลังออกมาจากกลางแผ่นดินกองหนึ่ง และกองทัพอีกกองหนึ่งกําลังออกมาจากทางที่ราบเมโอเนนิม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 38, 'เศบุลก็กล่าวแก่กาอัลว่า “ปากของท่านอยู่ที่ไหนเดี๋ยวนี้ ท่านผู้ที่กล่าวว่า ‘อาบีเมเลคคือผู้ใด ที่เราต้องปรนนิบัติ’ คนเหล่านี้เป็นคนที่ท่านหมิ่นประมาทมิใช่หรือ จงยกออกไปสู้รบกับเขาเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 39, 'กาอัลก็เดินนําหน้ากองทัพเชเคมออกไปต่อสู้กับอาบีเมเลค');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 40, 'อาบีเมเลคก็ขับไล่กาอัลหนีไป มีคนถูกบาดเจ็บล้มตายเป็นอันมาก จนถึงทางเข้าประตูเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 41, 'ฝ่ายอาบีเมเลคก็อาศัยอยู่ที่อารูมาห์ และเศบุลก็ขับไล่กาอัลกับญาติของเขาออกไปไม่ให้อยู่ที่เชเคมต่อไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 42, 'ต่อมารุ่งขึ้น มีชาวเมืองออกไปที่ทุ่งนา อาบีเมเลคก็ทราบเรื่อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 43, 'ท่านจึงแบ่งคนของท่านออกเป็นสามกอง ซุ่มคอยอยู่ที่ทุ่งนา ท่านมองดู ดูเถิด คนออกมาจากในเมือง ท่านจึงลุกขึ้นประหารเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 44, 'ส่วนอาบีเมเลคกับทหารที่อยู่ด้วยก็รุกไปยืนอยู่ที่ทางเข้าประตูเมือง ฝ่ายทหารอีกสองกองก็รุกเข้าโจมตีคนทั้งหมดที่ในทุ่งนาประหารเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 45, 'อาบีเมเลคโจมตีเมืองนั้นตลอดวันยังค่ํา ยึดเมืองนั้นได้ และฆ่าฟันประชาชนที่อยู่ในเมืองนั้นเสีย ทั้งทําลายเมืองนั้นเสียด้วย แล้วก็หว่านเกลือลงไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 46, 'เมื่อบรรดาชาวบ้านหอเชเคมได้ยินเช่นนั้น ก็หนีเข้าไปอยู่ในป้อมในวิหารของพระเบรีท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 47, 'มีคนไปเรียนอาบีเมเลคว่า บรรดาชาวบ้านหอเชเคมไปซ่องสุมกันอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 48, 'อาบีเมเลคก็ขึ้นไปบนภูเขาศัลโมน ทั้งท่านกับบรรดาคนที่อยู่ด้วย อาบีเมเลคถือขวานตัดกิ่งไม้ใส่บ่าแบกมา ท่านจึงบอกคนที่อยู่ด้วยว่า “เจ้าเห็นข้าทําอะไร จงรีบไปทําอย่างข้าเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 49, 'ดังนั้นคนทั้งปวงก็ตัดกิ่งไม้แบกตามอาบีเมเลคไปสุมไว้ ณ ที่ป้อม แล้วก็จุดไฟเผาป้อมนั้น ชาวบ้านหอเชเคมก็ตายหมดด้วย ทั้งชายและหญิงประมาณหนึ่งพันคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 50, 'อาบีเมเลคไปยังเมืองเธเบศตั้งค่ายประชิดเมืองเธเบศไว้ และยึดเมืองนั้นได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 51, 'แต่ในเมืองมีหอรบแห่งหนึ่ง ประชาชนเมืองนั้นทั้งสิ้นก็หนีเข้าไปอยู่ในหอทั้งผู้ชายและผู้หญิง ปิดประตูขังตนเองเสีย เขาก็ขึ้นไปบนหลังคาหอรบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 52, 'อาบีเมเลคยกมาถึงหอรบนี้ ได้ต่อสู้กัน จนเข้ามาใกล้ประตูหอรบได้ จะเอาไฟเผา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 53, 'มีหญิงคนหนึ่งเอาหินโม่ชิ้นบนทุ่มศีรษะอาบีเมเลค กะโหลกศีรษะของท่านแตก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 54, 'ท่านจึงรีบร้องบอกคนหนุ่มที่ถืออาวุธของท่านว่า “เอาดาบฟันเราเสียเพื่อคนจะไม่กล่าวว่า ‘ผู้หญิงคนหนึ่งฆ่าเขาตาย’” ชายหนุ่มของท่านคนนั้นก็แทงท่านทะลุถึงแก่ความตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 55, 'เมื่อคนอิสราเอลเห็นว่าอาบีเมเลคสิ้นชีวิตแล้ว ต่างคนก็กลับไปยังที่ของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 56, 'ดังนี้แหละพระเจ้าทรงสนองความชั่วที่อาบีเมเลคได้กระทําต่อบิดาของตนที่ได้ฆ่าพี่น้องเจ็ดสิบคนของตนเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 57, 'และพระเจ้าทรงกระทําให้บรรดาความชั่วร้ายของชาวเชเคมกลับตกบนศีรษะของเขาทั้งหลายเอง คําสาปแช่งของโยธามบุตรชายเยรุบบาอัลก็ตกอยู่บนเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 1, 'ต่อจากอาบีเมเลคมีคนขึ้นมาช่วยอิสราเอลให้พ้นชื่อโทลาบุตรชายของปูวาห์ผู้เป็นบุตรชายของโดโด คนอิสสาคาร์ และเขาอยู่ที่เมืองชามีร์ในแดนเทือกเขาเอฟราอิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 2, 'ท่านวินิจฉัยอิสราเอลอยู่ยี่สิบสามปี แล้วท่านก็สิ้นชีวิต เขาฝังศพท่านไว้ที่เมืองชามีร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 3, 'ต่อมายาอีร์คนกิเลอาดได้ขึ้นมาและท่านวินิจฉัยอิสราเอลอยู่ยี่สิบสองปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 4, 'ท่านมีบุตรชายสามสิบคน ขี่ลูกลาสามสิบตัว และมีเมืองอยู่สามสิบหัวเมืองเรียกว่าเมืองฮาโวทยาอีร์จนทุกวันนี้ ซึ่งอยู่ในแผ่นดินกิเลอาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 5, 'ยาอีร์ก็สิ้นชีวิตและถูกฝังไว้ที่เมืองคาโมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 6, 'คนอิสราเอลก็กระทําชั่วในสายพระเนตรของพระเยโฮวาห์อีก ไปปรนนิบัติพระบาอัล พระอัชทาโรท พวกพระของเมืองซีเรีย พวกพระของเมืองไซดอน พวกพระของเมืองโมอับ พวกพระของคนอัมโมน พวกพระของคนฟีลิสเตีย และละทิ้งพระเยโฮวาห์เสีย หาได้ปรนนิบัติพระองค์ไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 7, 'และพระพิโรธของพระเยโฮวาห์ก็พลุ่งขึ้นต่ออิสราเอล จึงทรงขายเขาไว้ในมือของคนฟีลิสเตียและในมือของคนอัมโมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 8, 'เขาได้ข่มเหงและบีบบังคับคนอิสราเอลในปีนั้น คือคนอิสราเอลทั้งปวงที่อยู่ฟากแม่น้ําจอร์แดนข้างโน้นในแผ่นดินของคนอาโมไรต์ ซึ่งอยู่ในกิเลอาดสิบแปดปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 9, 'ทั้งคนอัมโมนได้ข้ามแม่น้ําจอร์แดนไปต่อสู้กับยูดาห์และต่อสู้กับเบนยามิน และต่อสู้กับวงศ์วานเอฟราอิม ดังนั้นอิสราเอลจึงเดือดร้อนอย่างยิ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 10, 'และคนอิสราเอลร้องทุกข์ต่อพระเยโฮวาห์ว่า “ข้าพระองค์ทั้งหลายได้กระทําบาปต่อพระองค์ เพราะว่าข้าพระองค์ได้ทอดทิ้งพระเจ้าของข้าพระองค์เสีย และปรนนิบัติพระบาอัล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 11, 'และพระเยโฮวาห์ตรัสกับคนอิสราเอลว่า “เรามิได้ช่วยเจ้าให้พ้นจากชาวอียิปต์ จากคนอาโมไรต์ จากคนอัมโมน และจากคนฟีลิสเตียหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 12, 'ทั้งคนไซดอน คนอามาเลข และชาวมาโอนได้บีบบังคับเจ้า เจ้าได้ร้องทุกข์ถึงเราและเราได้ช่วยเจ้าให้พ้นมือเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 13, 'แม้กระนั้นเจ้าทั้งหลายยังได้ละทิ้งเรา และปรนนิบัติพระอื่น ฉะนี้เราจึงจะไม่ช่วยเจ้าทั้งหลายให้พ้นอีกต่อไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 14, 'จงไปร้องทุกข์ต่อพระซึ่งเจ้าทั้งหลายได้เลือกเถิด ให้พระเหล่านั้นช่วยเจ้าให้พ้นในยามทุกข์เดือดร้อนนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 15, 'และคนอิสราเอลกราบทูลพระเยโฮวาห์ว่า “ข้าพระองค์ทั้งหลายได้กระทําบาปแล้ว ขอพระองค์ทรงกระทําตามที่พระองค์ทรงเห็นชอบ ข้าพระองค์ขอวิงวอนเพียงว่า ขอทรงช่วยข้าพระองค์ให้พ้นในวันนี้เถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 16, 'ดังนั้นเขาทั้งหลายจึงเลิกถือพระอื่น และปรนนิบัติพระเยโฮวาห์ ฝ่ายพระองค์ทรงเดือดร้อนพระทัยด้วยความทุกข์เข็ญของอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 17, 'ฝ่ายคนอัมโมนก็ถูกเรียกให้มาพร้อมกัน เขาได้ตั้งค่ายในกิเลอาด และคนอิสราเอลก็มาพร้อมกันตั้งค่ายอยู่ที่มิสเปห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 18, 'และประชาชนกับพวกประมุขของคนกิเลอาดพูดกันว่า “ผู้ใดที่จะเป็นคนแรกที่จะเข้าต่อสู้กับคนอัมโมน ผู้นั้นจะเป็นหัวหน้าของชาวกิเลอาดทั้งหมด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 1, 'เยฟธาห์คนกิเลอาดเป็นทแกล้วทหาร แต่เป็นบุตรชายของหญิงแพศยา กิเลอาดให้กําเนิดบุตรชื่อเยฟธาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 2, 'ภรรยาแท้ของกิเลอาดคลอดบุตรชายหลายคน และเมื่อพวกบุตรเหล่านั้นโตขึ้นแล้ว จึงผลักไสเยฟธาห์ออกไปเสียโดยกล่าวว่า “เจ้าจะมีส่วนในมรดกของครอบครัวบิดาเราไม่ได้ เพราะเจ้าเป็นลูกของหญิงคนอื่น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 3, 'เยฟธาห์จึงหนีจากพี่น้องของตนไปอาศัยอยู่ที่แผ่นดินโทบ พวกนักเลงก็มั่วสุมอยู่กับเยฟธาห์และติดตามเขาไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 4, 'ต่อมาภายหลังคนอัมโมนได้ทําสงครามกับคนอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 5, 'และเมื่อคนอัมโมนทําสงครามกับอิสราเอลนั้น พวกผู้ใหญ่ของเมืองกิเลอาดได้ไปเพื่อจะพาเยฟธาห์มาจากแผ่นดินโทบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 6, 'เขากล่าวแก่เยฟธาห์ว่า “จงมาเป็นหัวหน้าของเรา เพื่อเราจะได้ต่อสู้กับคนอัมโมน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 7, 'แต่เยฟธาห์กล่าวแก่พวกผู้ใหญ่ของกิเลอาดว่า “ท่านไม่ได้เกลียดข้าพเจ้า และขับไล่ข้าพเจ้าเสียจากครอบครัวบิดาของข้าพเจ้าดอกหรือ เมื่อคราวทุกข์ยากท่านจะมาหาข้าพเจ้าทําไมเล่า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 8, 'พวกผู้ใหญ่ของกิเลอาดจึงกล่าวแก่เยฟธาห์ว่า “เหตุที่เรากลับมาหาท่าน ณ บัดนี้ ก็ด้วยต้องการให้ท่านไปกับเราสู้รบกับคนอัมโมน แล้วมาเป็นหัวหน้าของเราที่จะปกครองชาวกิเลอาดทั้งปวง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 9, 'เยฟธาห์จึงกล่าวแก่พวกผู้ใหญ่ของกิเลอาดว่า “ถ้าท่านให้ข้าพเจ้ากลับบ้านเพื่อทําศึกกับคนอัมโมน และถ้าพระเยโฮวาห์ทรงมอบเขาไว้ต่อหน้าข้าพเจ้า ข้าพเจ้าจะได้เป็นหัวหน้าของท่านหรือเปล่า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 10, 'พวกผู้ใหญ่ของกิเลอาดจึงตอบเยฟธาห์ว่า “พระเยโฮวาห์ทรงเป็นพยานระหว่างเรา เราจะกระทําตามที่ท่านสั่งทุกประการ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 11, 'เยฟธาห์จึงไปกับพวกผู้ใหญ่ของกิเลอาด และประชาชนก็ตั้งท่านให้เป็นหัวหน้าและเป็นประมุขของเขา แล้วเยฟธาห์ก็กล่าวคําที่ตกลงกันทั้งสิ้นต่อพระพักตร์พระเยโฮวาห์ที่เมืองมิสเปห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 12, 'เยฟธาห์จึงส่งผู้สื่อสารไปยังกษัตริย์คนอัมโมนถามว่า “ท่านมีเรื่องอะไรกับข้าพเจ้า ท่านจึงยกมาต่อสู้กับแผ่นดินของข้าพเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 13, 'กษัตริย์คนอัมโมนตอบผู้สื่อสารของเยฟธาห์ว่า “เพราะว่าเมื่ออิสราเอลยกออกมาจากอียิปต์ได้ยึดแผ่นดินของเราไป ตั้งแต่แม่น้ําอารโนนถึงแม่น้ํายับบอกและถึงแม่น้ําจอร์แดน ฉะนั้นบัดนี้ขอคืนแผ่นดินเหล่านั้นเสียโดยดี”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 14, 'และเยฟธาห์ก็ส่งผู้สื่อสารไปหากษัตริย์คนอัมโมนอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 15, 'ให้กล่าวว่า “เยฟธาห์กล่าวดังนี้ว่า อิสราเอลมิได้ยึดแผ่นดินของโมอับ หรือแผ่นดินของคนอัมโมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 16, 'แต่เมื่ออิสราเอลออกจากอียิปต์ เขาได้เดินไปทางถิ่นทุรกันดารถึงทะเลแดง และมาถึงคาเดช');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 17, 'อิสราเอลจึงส่งผู้สื่อสารไปยังกษัตริย์เอโดมกล่าวว่า ‘ข้าพเจ้าขออนุญาตยกผ่านแผ่นดินของท่านไป’ แต่กษัตริย์เอโดมไม่ฟัง และก็ได้ส่งคําขอเช่นเดียวกันไปยังกษัตริย์เมืองโมอับด้วย แต่ท่านก็ไม่ตกลง ดังนั้นอิสราเอลจึงยับยั้งอยู่ที่คาเดช');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 18, 'แล้วเขาก็เดินไปในถิ่นทุรกันดารอ้อมแผ่นดินเอโดม และแผ่นดินโมอับ และมาทางด้านตะวันออกของแผ่นดินโมอับ และตั้งค่ายอยู่ที่ฟากแม่น้ําอารโนนข้างโน้น แต่เขามิได้เข้าไปในเขตแดนของโมอับ เพราะว่าแม่น้ําอารโนนเป็นพรมแดนของโมอับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 19, 'อิสราเอลจึงส่งผู้สื่อสารไปหาสิโหนกษัตริย์คนอาโมไรต์ กษัตริย์กรุงเฮชโบน อิสราเอลเรียนท่านว่า ‘ขอให้พวกข้าพเจ้ายกผ่านแผ่นดินของท่านไปยังสถานที่ของข้าพเจ้า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 20, 'แต่สิโหนไม่วางใจที่จะให้อิสราเอลยกผ่านเขตแดนของตน ฉะนั้นสิโหนจึงได้รวบรวมประชาชนทั้งหมดของท่าน ตั้งค่ายอยู่ที่ยาฮาส และสู้รบกับอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 21, 'และพระเยโฮวาห์พระเจ้าของอิสราเอลทรงมอบสิโหนและประชาชนทั้งหมดของท่านไว้ในมืออิสราเอล คนอิสราเอลก็โจมตีเขา อิสราเอลจึงยึดครองแผ่นดินทั้งสิ้นของคนอาโมไรต์ผู้ซึ่งเป็นชาวเมืองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 22, 'และเขายึดเขตแดนทั้งหมดของคนอาโมไรต์ตั้งแต่แม่น้ําอารโนนถึงแม่น้ํายับบอก และตั้งแต่ถิ่นทุรกันดารถึงแม่น้ําจอร์แดน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 23, 'ดังนั้นพระเยโฮวาห์พระเจ้าของอิสราเอลจึงขับไล่คนอาโมไรต์ออกเสียต่อหน้าอิสราเอลประชาชนของพระองค์ ฝ่ายท่านจะมาถือเอาเป็นกรรมสิทธิ์เช่นนั้นหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 24, 'ท่านไม่ถือกรรมสิทธิ์สิ่งซึ่งพระเคโมชพระของท่านมอบให้ท่านยึดครองดอกหรือ พระเยโฮวาห์พระเจ้าของเราขับไล่ผู้ใดไปให้พ้นหน้าเรา เราก็ยึดครองที่ของผู้นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 25, 'ฝ่ายท่านจะดีกว่าบาลาคบุตรชายศิปโปร์กษัตริย์เมืองโมอับหรือ ท่านเคยแข่งขันกับอิสราเอลหรือ ท่านเคยต่อสู้กับเขาทั้งหลายหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 26, 'เมื่ออิสราเอลอาศัยอยู่ในกรุงเฮชโบนและชนบทของกรุงนั้น และในเมืองอาโรเออร์และชนบทของเมืองนั้น และอยู่ในบรรดาหัวเมืองที่ตั้งอยู่ตามฝั่งแม่น้ําอารโนนถึงสามร้อยปี ทําไมท่านไม่เรียกคืนเสียภายในเวลานั้นเล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 27, 'ฉะนี้ข้าพเจ้าจึงมิได้กระทําความผิดต่อท่าน แต่ท่านได้กระทําความผิดต่อข้าพเจ้าในการที่ทําสงครามกับข้าพเจ้า ขอพระเยโฮวาห์จอมผู้พิพากษาเป็นผู้ทรงพิพากษาระหว่างคนอิสราเอลและคนอัมโมนในวันนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 28, 'แต่กษัตริย์ของคนอัมโมนมิได้เชื่อฟังในคําของเยฟธาห์ซึ่งท่านส่งไปให้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 29, 'พระวิญญาณของพระเยโฮวาห์ก็มาสถิตกับเยฟธาห์ ท่านจึงยกผ่านกิเลอาดและมนัสเสห์และผ่านมิสเปห์แห่งกิเลอาด และจากมิสเปห์แห่งกิเลอาด ท่านยกผ่านต่อไปถึงที่คนอัมโมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 30, 'และเยฟธาห์สาบานต่อพระเยโฮวาห์ว่า “ถ้าพระองค์ทรงมอบคนอัมโมนไว้ในมือของข้าพระองค์แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 31, 'อะไรก็ตามที่ออกมาจากประตูเรือนของข้าพระองค์เพื่อต้อนรับข้าพระองค์เมื่อข้าพระองค์กลับมาจากคนอัมโมนนั้นด้วยความสงบแล้ว สิ่งนั้นจะต้องเป็นของของพระเยโฮวาห์ และข้าพระองค์จะถวายสิ่งนั้นเป็นเครื่องเผาบูชา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 32, 'แล้วเยฟธาห์จึงยกข้ามไปสู้รบกับคนอัมโมน และพระเยโฮวาห์ทรงมอบเขาไว้ในมือของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 33, 'และท่านได้ประหารเขาจากอาโรเออร์จนถึงที่ใกล้ๆเมืองมินนิทรวมยี่สิบหัวเมือง และไกลไปจนถึงที่ราบแห่งสวนองุ่น ผู้คนล้มตายมาก คนอัมโมนจึงพ่ายแพ้ต่อหน้าคนอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 34, 'แล้วเยฟธาห์ก็กลับมาบ้านที่มิสเปห์ ดูเถิด บุตรสาวของท่านถือรํามะนาเต้นโลดออกมาต้อนรับท่าน เธอเป็นบุตรคนเดียว นอกจากบุตรสาวคนนี้ท่านไม่มีบุตรชายและบุตรสาวเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 35, 'และต่อมาเมื่อท่านเห็นเธอแล้ว ท่านก็ฉีกเสื้อผ้าของท่าน กล่าวว่า “อนิจจา ลูกสาวเอ๋ย เจ้าให้พ่อแย่แล้ว เพราะเจ้าเป็นเหตุให้พ่อเดือดร้อนมากยิ่ง เพราะพ่อได้อ้าปากกล่าวต่อพระเยโฮวาห์ไว้แล้ว จะคืนคําก็ไม่ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 36, 'เธอจึงพูดกับพ่อว่า “คุณพ่อขา เมื่อคุณพ่อออกปากสัญญากับพระเยโฮวาห์ไว้อย่างไร ขอคุณพ่อกระทํากับลูกตามคําที่ออกจากปากของคุณพ่อเถิด เพราะพระเยโฮวาห์ได้ทรงแก้แค้นคนอัมโมนศัตรูเพื่อคุณพ่อแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 37, 'และเธอพูดกับบิดาของเธอว่า “ขอให้ลูกอย่างนี้เถิด ขอปล่อยลูกไว้สักสองเดือน ลูกจะได้จากบ้านและลงไปบนภูเขา ร้องไห้คร่ําครวญถึงความเป็นพรหมจารีของลูก ลูกกับเพื่อนๆของลูก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 38, 'ท่านจึงตอบว่า “ไปเถิด” และท่านก็ปล่อยเธอไปสองเดือน เธอก็ออกไป เธอและพวกเพื่อนของเธอแล้วร้องไห้คร่ําครวญถึงความเป็นพรหมจารีของเธอบนภูเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 39, 'อยู่มาเมื่อครบสองเดือนแล้ว เธอก็กลับมาหาบิดาของเธอ และท่านก็กระทํากับเธอตามคําสาบานที่ได้สาบานไว้ เธอยังไม่เคยร่วมรู้กับชายใดเลย และก็เป็นธรรมเนียมในอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 40, 'คือที่บุตรสาวชาวอิสราเอลไปร้องไห้ไว้ทุกข์ให้บุตรสาวของเยฟธาห์คนกิเลอาดปีละสี่วัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 1, 'ฝ่ายคนเอฟราอิมมาพร้อมกันข้ามไปทางเหนือ พูดกับเยฟธาห์ว่า “เหตุใดท่านยกข้ามไปรบคนอัมโมน แต่ไม่เรียกเราไปด้วย เราจะจุดไฟเผาเรือนทับท่านเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 2, 'เยฟธาห์จึงตอบเขาว่า “ข้าพเจ้ากับประชาชนติดการศึกใหญ่กับคนอัมโมน เมื่อข้าพเจ้าเรียกท่านให้ช่วย ท่านไม่ได้ช่วยเราให้พ้นมือเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 3, 'เมื่อข้าพเจ้าเห็นว่าท่านไม่ช่วยข้าพเจ้าแล้ว ข้าพเจ้าก็เสี่ยงชีวิตของข้าพเจ้าข้ามไปรบกับคนอัมโมน และพระเยโฮวาห์ทรงมอบเขาไว้ในมือของข้าพเจ้า วันนี้ท่านจะขึ้นมาทําศึกกับข้าพเจ้าด้วยเหตุอันใด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 4, 'เยฟธาห์จึงรวบรวมบรรดาชาวกิเลอาดสู้รบกับคนเอฟราอิม คนกิเลอาดก็ประหารคนเอฟราอิม เพราะเขากล่าวว่า “เจ้าชาวกิเลอาด เจ้าเป็นคนหลบหนีของชาวเอฟราอิมท่ามกลางคนเอฟราอิมและมนัสเสห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 5, 'ชาวกิเลอาดก็เข้ายึดท่าข้ามแม่น้ําจอร์แดนไว้ไม่ให้คนเอฟราอิมข้าม เมื่อคนเอฟราอิมที่หลบหนีคนใดมาบอกว่า “ขอให้ข้ามไปทีเถิด” คนกิเลอาดจะถามเขาว่า “เจ้าเป็นคนเอฟราอิมหรือ” เมื่อเขาตอบว่า “เปล่า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 6, 'เขาจะบอกว่า “จงว่าคําว่าชิบโบเลท” คนนั้นจะว่า “สิบโบเลท” เพราะคนเอฟราอิมออกเสียงคํานี้ไม่ชัด เขาจึงจับคนนั้นและฆ่าเสียที่ท่าข้ามแม่น้ําจอร์แดน คราวนั้นมีคนเอฟราอิมตายสี่หมื่นสองพันคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 7, 'เยฟธาห์วินิจฉัยอิสราเอลอยู่หกปี แล้วเยฟธาห์ชาวกิเลอาดก็สิ้นชีวิตและถูกฝังไว้ในหัวเมืองหนึ่งในกิเลอาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 8, 'ถัดเยฟธาห์มาคืออิบซานแห่งเบธเลเฮมได้วินิจฉัยอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 9, 'ท่านมีบุตรชายสามสิบคน และบุตรสาวสามสิบคน ท่านให้แต่งงานกับคนนอกตระกูลของท่าน และท่านนําบุตรีสามสิบคนของคนนอกตระกูลมาให้แก่บุตรชายของท่าน ท่านวินิจฉัยอิสราเอลอยู่เจ็ดปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 10, 'แล้วอิบซานก็สิ้นชีวิตถูกฝังไว้ที่เบธเลเฮม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 11, 'ถัดท่านมา เอโลนคนเศบูลุนวินิจฉัยอิสราเอล และท่านวินิจฉัยอิสราเอลสิบปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 12, 'แล้วเอโลนคนเศบูลุนก็สิ้นชีวิต และถูกฝังไว้ที่อัยยาโลนในเขตแดนของคนเศบูลุน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 13, 'ถัดท่านมา อับโดนบุตรชายฮิลเลลชาวปิราโธนวินิจฉัยอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 14, 'ท่านมีบุตรชายสี่สิบคน และหลานชายสามสิบคน ขี่ลาเจ็ดสิบตัว ท่านวินิจฉัยอิสราเอลอยู่แปดปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 15, 'แล้วอับโดนบุตรชายฮิลเลลชาวปิราโธนก็สิ้นชีวิตถูกฝังไว้ที่ปิราโธนในเขตแดนของเอฟราอิมในแดนเทือกเขาของคนอามาเลข');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 1, 'คนอิสราเอลก็กระทําชั่วในสายพระเนตรของพระเยโฮวาห์อีก พระเยโฮวาห์จึงทรงมอบเขาไว้ในมือของคนฟีลิสเตียสี่สิบปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 2, 'มีชายคนหนึ่งเป็นชาวโศราห์คนครอบครัวดาน ชื่อมาโนอาห์ ภรรยาของท่านเป็นหมันไม่มีบุตรเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 3, 'ทูตสวรรค์ของพระเยโฮวาห์มาปรากฏแก่นางนั้น กล่าวแก่นางว่า “ดูเถิด บัดนี้เจ้าเป็นหมันไม่มีบุตร แต่เจ้าจะตั้งครรภ์คลอดบุตรเป็นชาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 4, 'ฉะนั้นบัดนี้จงระวัง อย่าดื่มเหล้าองุ่น หรือเมรัย และอย่ารับประทานของมลทิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 5, 'เพราะดูเถิด เจ้าจะตั้งครรภ์และคลอดบุตรเป็นชาย อย่าให้มีดโกนถูกศีรษะของเขา เพราะเด็กคนนี้จะเป็นพวกนาศีร์แด่พระเจ้าตั้งแต่อยู่ในครรภ์ เขาจะเป็นคนเริ่มช่วยคนอิสราเอลให้พ้นจากเงื้อมมือของคนฟีลิสเตีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 6, 'ฝ่ายหญิงนั้นจึงไปบอกสามีว่า “มีบุรุษผู้หนึ่งของพระเจ้ามาหาดิฉัน ใบหน้าของท่านเหมือนใบหน้าทูตสวรรค์ของพระเจ้า น่ากลัวนัก ดิฉันไม่ได้ถามท่านว่าท่านมาจากไหน และท่านก็ไม่บอกชื่อของท่านแก่ดิฉัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 7, 'แต่ท่านบอกดิฉันว่า ‘ดูเถิด เจ้าจะตั้งครรภ์และคลอดบุตรชาย ฉะนั้นอย่าดื่มเหล้าองุ่นหรือเมรัย อย่ารับประทานของมลทิน เพราะเด็กนั้นจะเป็นพวกนาศีร์แด่พระเจ้าตั้งแต่อยู่ในครรภ์จนวันตาย’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 8, 'แล้วมาโนอาห์ก็วิงวอนพระเยโฮวาห์ทูลว่า “โอ ข้าแต่องค์พระผู้เป็นเจ้า ขอบุรุษของพระเจ้าผู้ซึ่งพระองค์ทรงใช้มานั้นปรากฏแก่ข้าพระองค์ทั้งสองอีกครั้งหนึ่ง สั่งสอนข้าพระองค์ว่า ข้าพระองค์ควรกระทําอย่างไรแก่เด็กที่จะเกิดมานั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 9, 'และพระเจ้าทรงฟังเสียงของมาโนอาห์ และทูตสวรรค์ของพระเจ้ามาหาหญิงนั้นอีกเมื่อนางนั่งอยู่ในทุ่งนา แต่มาโนอาห์สามีของนางไม่ได้อยู่ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 10, 'นางก็รีบวิ่งไปบอกสามีว่า “ดูเถิด บุรุษผู้ที่ปรากฏแก่ดิฉันวันนั้นได้มาปรากฏแก่ดิฉันอีก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 11, 'มาโนอาห์ก็ลุกขึ้นตามภรรยาไป เมื่อมาถึงบุรุษผู้นั้นเขาจึงว่า “ท่านเป็นบุรุษผู้ที่พูดกับผู้หญิงคนนี้หรือ” ผู้นั้นตอบว่า “เราเป็นผู้นั้นแหละ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 12, 'มาโนอาห์จึงกล่าวว่า “บัดนี้ขอให้ถ้อยคําของท่านเป็นความจริง ข้าพเจ้าทั้งสองควรสั่งสอนเด็กคนนั้นอย่างไร และข้าพเจ้าทั้งสองควรกระทําต่อเขาอย่างไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 13, 'และทูตสวรรค์ของพระเยโฮวาห์บอกแก่มาโนอาห์ว่า “บรรดาสิ่งที่เราได้บอกแก่หญิงแล้วนั้นให้นางระวังให้ดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 14, 'อย่าให้รับประทานสิ่งใดที่ได้มาจากเถาองุ่น อย่าให้นางดื่มเหล้าองุ่นหรือเมรัย อย่ารับประทานของมลทิน สิ่งใดที่เราบัญชานางไว้ให้นางปฏิบัติตามทุกประการ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 15, 'มาโนอาห์กล่าวแก่ทูตสวรรค์ของพระเยโฮวาห์ว่า “ขอท่านรออยู่ก่อน ข้าพเจ้าทั้งสองจะไปเตรียมลูกแพะตัวหนึ่งให้ท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 16, 'ทูตสวรรค์ของพระเยโฮวาห์บอกมาโนอาห์ว่า “ถึงเจ้าจะให้เรารอ เราจะไม่รับประทานอาหารของเจ้า แต่ถ้าเจ้าจะจัดเครื่องเผาบูชา เจ้าจงถวายแด่พระเยโฮวาห์” เพราะว่ามาโนอาห์ไม่ทราบว่าท่านผู้นั้นเป็นทูตสวรรค์องค์หนึ่งของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 17, 'มาโนอาห์ถามทูตสวรรค์ของพระเยโฮวาห์ว่า “ท่านชื่ออะไร เพื่อเมื่อเป็นจริงตามถ้อยคําของท่าน เราจะได้ให้เกียรติแก่ท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 18, 'ทูตสวรรค์ของพระเยโฮวาห์บอกมาโนอาห์ว่า “ถามชื่อเราทําไม ชื่อของเราเป็นที่ซ่อนเร้นอยู่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 19, 'มาโนอาห์ก็เอาลูกแพะกับธัญญบูชามาถวายบูชาบนศิลาแด่พระเยโฮวาห์ และทูตสวรรค์นั้นกระทําการมหัศจรรย์ มาโนอาห์และภรรยาก็มองดู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 20, 'และอยู่มาเมื่อเปลวไฟจากแท่นบูชาพลุ่งขึ้นไปสวรรค์ ทูตสวรรค์ของพระเยโฮวาห์ก็ขึ้นไปตามเปลวไฟแห่งแท่นบูชา ขณะเมื่อมาโนอาห์และภรรยาคอยดูอยู่ และเขาทั้งสองก็ซบหน้าลงถึงดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 21, 'ทูตสวรรค์ของพระเยโฮวาห์ไม่ปรากฏแก่มาโนอาห์หรือแก่ภรรยาของเขาอีกเลย แล้วมาโนอาห์จึงทราบว่าผู้นั้นเป็นทูตสวรรค์องค์หนึ่งของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 22, 'และมาโนอาห์พูดกับภรรยาของตนว่า “เราจะตายเป็นแน่ เพราะเราได้เห็นพระเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 23, 'แต่ภรรยาบอกเขาว่า “ถ้าพระเยโฮวาห์ทรงหมายจะฆ่าเราเสีย พระองค์คงจะไม่รับเครื่องเผาบูชาและธัญญบูชาจากมือของเรา หรือทรงสําแดงสิ่งทั้งปวงเหล่านี้แก่เรา หรือประกาศเรื่องเช่นนี้แก่เรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 24, 'ผู้หญิงนั้นก็คลอดบุตรชายคนหนึ่งเรียกชื่อว่าแซมสัน เด็กนั้นก็เติบโตขึ้น และพระเยโฮวาห์ทรงอํานวยพระพรแก่เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 25, 'และพระวิญญาณของพระเยโฮวาห์ก็ทรงเริ่มเร้าใจเขาที่ค่ายดานระหว่างโศราห์กับเอชทาโอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 1, 'แซมสันได้ลงไปยังเมืองทิมนาห์ และได้เห็นผู้หญิงคนฟีลิสเตียคนหนึ่งที่เมืองทิมนาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 2, 'แล้วท่านจึงขึ้นมาบอกบิดามารดาของตนว่า “ข้าพเจ้าเห็นผู้หญิงคนฟีลิสเตียคนหนึ่งที่เมืองทิมนาห์ ฉะนั้นไปขอเขาให้เป็นภรรยาข้าพเจ้าที”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 3, 'แต่บิดาและมารดาของท่านกล่าวแก่ท่านว่า “ไม่มีผู้หญิงสักคนหนึ่งในท่ามกลางบุตรสาวแห่งญาติพี่น้องของเจ้า หรือในท่ามกลางชนชาติของเราหรือ เจ้าจึงไปรับภรรยาจากคนฟีลิสเตียที่ไม่เข้าสุหนัต” แต่แซมสันกล่าวแก่บิดาว่า “ไปขอหญิงนั้นให้ข้าพเจ้าที เพราะเธอเป็นที่พอใจข้าพเจ้ามาก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 4, 'บิดามารดาของท่านไม่ทราบว่าเรื่องนี้เป็นมาจากพระเยโฮวาห์ เพราะพระองค์ทรงหาช่องโอกาสที่จะต่อสู้คนฟีลิสเตีย ครั้งนั้นคนฟีลิสเตียมีอํานาจเหนืออิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 5, 'ฝ่ายแซมสันก็ลงไปที่เมืองทิมนาห์กับบิดามารดาของตน แซมสันมาถึงสวนองุ่นของทิมนาห์ ดูเถิด มีสิงโตหนุ่มตัวหนึ่งคํารามเข้าใส่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 6, 'พระวิญญาณของพระเยโฮวาห์ก็ทรงสถิตกับแซมสันอย่างมาก ท่านจึงฉีกสิงโตออกอย่างคนฉีกลูกแพะ ทั้งที่ไม่มีอะไรในมือ แต่ท่านมิได้บอกให้บิดาหรือมารดาของท่านทราบว่าท่านได้ทําอะไรไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 7, 'แซมสันก็ลงไปพูดจากับหญิงคนนั้น เธอเป็นที่พอใจแก่แซมสันมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 8, 'ต่อมาภายหลังแซมสันก็กลับไปเพื่อรับเธอมา ท่านก็แวะไปดูซากสิงโต และดูเถิด มีผึ้งฝูงหนึ่งทํารังอยู่ในซากสิงโตนั้น มีน้ําผึ้งด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 9, 'แซมสันก็ยื่นมือกวาดเอารวงผึ้งมาเดินรับประทานไปพลาง จนมาถึงบิดามารดา ท่านจึงแบ่งให้บิดามารดารับประทานด้วย แต่ท่านมิได้บอกว่าน้ําผึ้งนั้นมาจากซากสิงโต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 10, 'ฝ่ายบิดาของท่านก็ลงไปหาหญิงคนนั้น และแซมสันจัดการเลี้ยงที่นั่น ดังที่คนหนุ่มๆเขากระทํากัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 11, 'และต่อมาเมื่อประชาชนเห็นท่านแล้ว จึงนําเพื่อนสามสิบคนให้มาอยู่ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 12, 'แซมสันกล่าวแก่เขาว่า “ให้ข้าทายปริศนาเจ้าสักข้อหนึ่งเถิด ถ้าทายได้ก่อนจบการเลี้ยงเจ็ดวันนี้ ข้าจะให้เสื้อป่านสามสิบชุด และเสื้อสามสิบชุดด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 13, 'แต่ถ้าเจ้าทั้งหลายทายไม่ได้ เจ้าต้องให้เสื้อป่านสามสิบชุดกับเสื้อสามสิบชุดแก่ข้า” เขาก็ตอบท่านว่า “ทายมาเถิด เราจะฟัง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 14, 'ฝ่ายแซมสันจึงกล่าวแก่เขาว่า “มีของกินได้ออกมาจากตัวผู้กินเขา มีของหวานออกมาจากตัวที่แข็งแรง” ในสามวันเขาก็ยังแก้ปริศนานี้ไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 15, 'ต่อมาพอถึงวันที่เจ็ดเขาจึงไปอ้อนวอนภรรยาของแซมสันว่า “จงลวงสามีของเจ้าให้แก้ปริศนานี้ให้เราฟัง มิฉะนั้นเราจะเอาไฟเผาเจ้ากับบ้านครอบครัวบิดาของเจ้าเสีย เจ้าเชิญเรามาหวังจะทําให้เรายากจนหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 16, 'ภรรยาของแซมสันไปร้องไห้กับแซมสันว่า “ท่านเกลียดฉัน ท่านไม่รักฉัน ท่านทายปริศนาแก่ชาวเมืองของฉัน และท่านก็ไม่แก้ปริศนาให้ฉันฟัง” แซมสันจึงบอกว่า “ดูเถิด พ่อแม่ของข้า ข้ายังไม่บอกเลย จะบอกเจ้าอย่างไรได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 17, 'เธอร้องไห้กับแซมสันตลอดเจ็ดวันซึ่งเป็นวันเลี้ยงกันนั้น และต่อมาในวันที่เจ็ดแซมสันก็ต้องแก้ปริศนาให้เธอฟัง เพราะเธอกวนท่านมากนัก และนางก็บอกแก้ปริศนาให้ชาวบ้านของนาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 18, 'พอวันที่เจ็ดก่อนดวงอาทิตย์ตกชาวเมืองจึงบอกแซมสันว่า “มีอะไรหวานกว่าน้ําผึ้ง มีอะไรแข็งแรงกว่าสิงโต” แซมสันจึงบอกเขาว่า “ถ้าเจ้าไม่เอาแม่วัวของข้าช่วยไถ เจ้าคงจะแก้ปริศนาของข้าไม่ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 19, 'และพระวิญญาณของพระเยโฮวาห์ก็ทรงสถิตกับแซมสันอย่างมาก ท่านจึงลงไปที่อัชเคโลนฆ่าชาวเมืองนั้นเสียสามสิบคน ริบเอาข้าวของและมอบเสื้อให้ผู้ที่แก้ปริศนา แล้วให้กลับไปบ้านของบิดาด้วยความโกรธอย่างมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 20, 'ส่วนภรรยาของแซมสันนั้นก็ยกให้แก่เพื่อนซึ่งเป็นเพื่อนเจ้าบ่าวนั้นเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 1, 'ครั้นล่วงมาหลายวันถึงฤดูเกี่ยวข้าวสาลี แซมสันก็เอาลูกแพะตัวหนึ่งไปเยี่ยมภรรยาพูดว่า “ข้าพเจ้าจะเข้าไปหาภรรยาของข้าพเจ้าที่ในห้อง” แต่พ่อตาไม่ยอมให้ท่านเข้าไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 2, 'พ่อตาจึงว่า “ข้าเข้าใจจริงๆว่าเจ้าเกลียดชังนางเหลือเกิน ข้าจึงยกนางให้แก่เพื่อนของเจ้าไป น้องสาวของนางก็สวยกว่านางมิใช่หรือ ขอจงรับน้องแทนพี่เถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 3, 'แซมสันจึงพูดเรื่องพวกเขาว่า “คราวนี้ข้าพเจ้าจะมีโทษน้อยกว่าคนฟีลิสเตีย ถึงแม้ว่าข้าพเจ้าจะทําร้ายพวกเขาเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 4, 'แซมสันจึงออกไปจับสุนัขจิ้งจอกสามร้อยตัว ผูกหางติดกันเป็นคู่ๆ แล้วเอาคบเพลิงผูกติดไว้ระหว่างหางทุกๆคู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 5, 'พอจุดคบเพลิงแล้วก็ปล่อยเข้าไปในนาของคนฟีลิสเตียที่ข้าวยังตั้งรวงอยู่ ไฟก็ไหม้ฟ่อนข้าว และข้าวที่ยังตั้งรวงอยู่นั้น ทั้งสวนองุ่นและต้นมะกอกเทศด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 6, 'คนฟีลิสเตียจึงถามว่า “ใครทําอย่างนี้” เขาตอบว่า “แซมสันบุตรเขยชาวทิมนาห์ เพราะว่าพ่อตาเอาภรรยาของแซมสันยกให้เพื่อนเสีย” ชาวฟีลิสเตียก็ขึ้นมาเผานางกับบิดาของนางเสียด้วยไฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 7, 'แซมสันจึงบอกพวกเหล่านั้นว่า “เมื่อเจ้าทั้งหลายทําอย่างนี้ ข้าจะต้องแก้แค้นเจ้าก่อน แล้วข้าจึงจะเลิก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 8, 'แล้วแซมสันก็ฟันคนเหล่านั้นเสียแหลกทีเดียวจนเขาตายเสียเป็นอันมาก แล้วแซมสันก็เข้าไปอาศัยอยู่ที่ช่องศิลาเอตาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 9, 'ฝ่ายคนฟีลิสเตียก็ขึ้นไปตั้งค่ายอยู่ในเขตยูดาห์ และกระจายกันเข้าโจมตีเมืองเลฮี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 10, 'พวกคนยูดาห์จึงถามว่า “ท่านทั้งหลายขึ้นมารบกับเราทําไม” พวกเหล่านั้นตอบว่า “เราขึ้นมามัดแซมสัน เพื่อจะได้กระทําแก่เขาอย่างที่เขาได้กระทําแก่เรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 11, 'คนยูดาห์สามพันคนลงไปที่ช่องศิลาเอตาม และกล่าวแก่แซมสันว่า “ท่านไม่ทราบหรือว่าคนฟีลิสเตียเป็นผู้ครอบครองเรา ท่านได้กระทําอะไรแก่เราเช่นนี้” แซมสันจึงตอบเขาว่า “เขาได้กระทําแก่ข้าพเจ้าอย่างไร ข้าพเจ้าก็ต้องกระทําแก่เขาอย่างนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 12, 'คนเหล่านั้นจึงพูดกับแซมสันว่า “เราจะลงมามัดท่านเพื่อมอบท่านไว้ในมือของคนฟีลิสเตีย” แซมสันจึงบอกเขาว่า “ขอปฏิญาณให้ซีว่าพวกท่านเองจะไม่ทําร้ายข้าพเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 13, 'เขาทั้งหลายจึงตอบท่านว่า “เราจะไม่ทําร้ายท่าน เราจะมัดท่านมอบไว้ในมือของเขาเท่านั้น เราจะไม่ฆ่าท่านเสีย” เขาจึงเอาเชือกพวนใหม่สองเส้นมัดแซมสันไว้ และพาขึ้นมาจากศิลานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 14, 'เมื่อท่านมาถึงเลฮีแล้วคนฟีลิสเตียก็ร้องอึกทึกมาพบท่าน และพระวิญญาณของพระเยโฮวาห์ก็ทรงสถิตกับแซมสันอย่างมาก เชือกพวนที่ผูกแขนของท่านก็เป็นประดุจป่านที่ไหม้ไฟ เครื่องจองจํานั้นก็หลุดออกจากมือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 15, 'ท่านมาพบกระดูกขากรรไกรลาสดๆอันหนึ่งจึงยื่นมือหยิบมา และฆ่าคนเหล่านั้นเสียหนึ่งพันคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 16, 'แซมสันกล่าวว่า “ด้วยขากรรไกรลา เป็นกองซ้อนกอง ด้วยขากรรไกรลา ข้าได้ฆ่าคนหนึ่งพันเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 17, 'อยู่มาเมื่อท่านกล่าวเช่นนั้นแล้วก็โยนกระดูกขากรรไกรลาทิ้งไป ท่านจึงเรียกชื่อตําบลนั้นว่า รามาทเลฮี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 18, 'แซมสันกระหายน้ํามาก จึงร้องทุกข์ถึงพระเยโฮวาห์ว่า “การช่วยให้พ้นอันยิ่งใหญ่พระองค์ประทานให้สําเร็จด้วยมือผู้รับใช้ของพระองค์ บัดนี้ข้าพระองค์จะตายเพราะอดน้ําอยู่แล้ว และตกอยู่ในมือของผู้ไม่เข้าสุหนัตมิใช่หรือพระเจ้าข้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 19, 'พระเจ้าจึงทรงเปิดช่องที่กระดูกขากรรไกรลาให้น้ําไหลออกมาจากที่นั้น ท่านก็ได้ดื่มและจิตวิญญาณก็สดชื่นฟื้นขึ้นอีก เพราะฉะนั้นที่แห่งนั้นท่านจึงเรียกชื่อว่า เอนหักโคร์ อยู่ที่เลฮีจนถึงทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 20, 'และท่านวินิจฉัยอิสราเอลในสมัยของคนฟีลิสเตียยี่สิบปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 1, 'แซมสันไปที่เมืองกาซาพบหญิงแพศยาคนหนึ่งก็เข้าไปนอนด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 2, 'มีคนไปบอกชาวกาซาว่า “แซมสันมาที่นี่แล้ว” เขาก็ล้อมที่นั้นไว้และคอยซุ่มที่ประตูเมืองตลอดคืน เขาซุ่มเงียบอยู่คืนยังรุ่งกล่าวว่า “ให้เรารออยู่จนรุ่งเช้าแล้วเราจะฆ่าเขาเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 3, 'แต่แซมสันนอนอยู่จนถึงเที่ยงคืน พอถึงเที่ยงคืนท่านก็ลุกขึ้น ยกประตูเมืองรวมทั้งเสาสองต้น พร้อมทั้งดาลประตูใส่บ่าแบกไปถึงยอดภูเขาซึ่งอยู่ตรงหน้าเมืองเฮโบรน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 4, 'อยู่มาภายหลัง แซมสันไปรักผู้หญิงคนหนึ่งที่หุบเขาเมืองโสเรก ชื่อเดลิลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 5, 'เจ้านายฟีลิสเตียก็ขึ้นไปหานางพูดกับนางว่า “จงลวงเขาเพื่อดูว่ากําลังมหาศาลของเขาอยู่ที่ไหน ทําอย่างไรเราจึงจะมีกําลังเหนือเขา เพื่อเราจะได้มัดเขาให้หมดฤทธิ์ เราทุกคนจะให้เงินเจ้าคนละพันหนึ่งร้อยแผ่น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 6, 'เดลิลาห์จึงพูดกับแซมสันว่า “ขอบอกฉันหน่อยเถอะว่า กําลังมหาศาลของท่านอยู่ที่ไหน จะมัดท่านไว้อย่างไรท่านจึงจะหมดฤทธิ์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 7, 'แซมสันจึงบอกนางว่า “ถ้าเขามัดข้าด้วยสายธนูสดที่ยังไม่แห้งเจ็ดเส้น ข้าจะอ่อนเพลีย เหมือนกับชายอื่นๆ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 8, 'แล้วเจ้านายฟีลิสเตียก็เอาสายธนูสดที่ยังไม่แห้งเจ็ดเส้นมาให้นาง นางก็เอามามัดท่านไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 9, 'นางจัดคนให้ซุ่มอยู่ที่ห้องชั้นในกับนาง นางก็บอกท่านว่า “แซมสันจ๋า คนฟีลิสเตียมาจับท่านแล้ว” แซมสันก็ดึงสายธนูที่มัดนั้นขาดเหมือนเชือกป่านขาดเมื่อได้กลิ่นไฟ เรื่องกําลังของท่านจึงยังไม่แจ้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 10, 'เดลิลาห์พูดกับแซมสันว่า “ดูเถิด ท่านหลอกฉัน และท่านมุสาต่อฉัน บัดนี้ขอบอกฉันหน่อยเถอะว่า จะมัดท่านอย่างไรจึงจะอยู่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 11, 'ท่านก็ตอบนางว่า “ถ้าเอาเชือกใหม่ที่ยังไม่เคยใช้มามัดข้า ข้าก็จะอ่อนกําลังเหมือนชายอื่น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 12, 'เดลิลาห์จึงเอาเชือกใหม่มัดท่านไว้แล้วบอกท่านว่า “แซมสันจ๋า คนฟีลิสเตียมาจับท่านแล้ว” และคนซุ่มคอยอยู่ในห้องชั้นใน แต่ท่านก็ดึงเชือกออกจากแขนเหมือนดึงเส้นด้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 13, 'เดลิลาห์พูดกับแซมสันว่า “ท่านหลอกฉันเรื่อยมาจนถึงเดี๋ยวนี้ ท่านมุสาต่อฉัน บอกฉันเถอะว่า จะมัดท่านอย่างไรจึงจะอยู่” ท่านจึงบอกนางว่า “ถ้าเจ้าเอาผมทั้งเจ็ดแหยมของข้าทอเข้ากับด้ายเส้นยืน กระทกด้วยฟืมให้แน่น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 14, 'เดลิลาห์จึงเอาผมทั้งเจ็ดแหยมทอเข้ากับด้ายเส้นยืนกระทกด้วยฟืมให้แน่น แล้วนางบอกท่านว่า “แซมสันจ๋า คนฟีลิสเตียมาจับท่านแล้ว” ท่านก็ตื่นขึ้นดึงฟืม หูกและด้ายเส้นยืนไปหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 15, 'นางจึงพูดกับแซมสันว่า “ท่านพูดได้อย่างไรว่า ‘ข้ารักเจ้า’ เมื่อจิตใจของท่านไม่ได้อยู่กับฉันเลย ท่านหลอกฉันสามครั้งแล้ว และท่านมิได้บอกฉันจริงๆว่ากําลังมหาศาลของท่านอยู่ที่ไหน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 16, 'อยู่มาเมื่อนางพูดคาดคั้นท่านวันแล้ววันเล่า และชักชวนท่านอยู่ทุกวัน จิตใจของแซมสันก็เบื่อแทบจะตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 17, 'จึงบอกความจริงในใจของท่านแก่นางจนสิ้นว่า “มีดโกนยังไม่เคยถูกศีรษะของข้า เพราะข้าเป็นพวกนาศีร์แด่พระเจ้าตั้งแต่อยู่ในครรภ์ของมารดา ถ้าโกนผมข้าเสีย กําลังก็จะหมดไปจากข้า ข้าก็จะอ่อนเพลียเหมือนชายอื่น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 18, 'เมื่อเดลิลาห์เห็นว่าท่านบอกความจริงในใจแก่นางจนสิ้นแล้ว นางจึงใช้คนไปเรียกเจ้านายฟีลิสเตียว่า “ขอจงขึ้นมาอีกครั้งเดียว เพราะเขาบอกความจริงในใจแก่ฉันจนสิ้นแล้ว” แล้วเจ้านายฟีลิสเตียก็ขึ้นมาหานางถือเงินมาด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 19, 'นางก็ให้แซมสันนอนอยู่บนตักของนาง แล้วนางก็เรียกชายคนหนึ่งให้มาโกนผมเจ็ดแหยมออกจากศีรษะของท่าน นางก็ตั้งต้นรบกวนแซมสัน กําลังของแซมสันก็หมดไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 20, 'นางจึงบอกว่า “แซมสันจ๋า คนฟีลิสเตียมาจับท่านแล้ว” ท่านก็ตื่นขึ้นจากหลับบอกว่า “ข้าจะออกไปอย่างครั้งก่อนๆ และสลัดตัวให้หลุดไป” ท่านหาทราบไม่ว่าพระเยโฮวาห์ได้ทรงละท่านไปเสียแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 21, 'คนฟีลิสเตียก็มาจับท่านทะลวงตาของท่านเสีย นําท่านลงมาที่กาซา เอาตรวนทองเหลืองล่ามไว้ และให้ท่านโม่แป้งอยู่ที่ในเรือนจํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 22, 'ตั้งแต่โกนผมแล้ว ผมที่ศีรษะของท่านก็ค่อยๆงอกขึ้นมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 23, 'ฝ่ายเจ้านายฟีลิสเตียประชุมกันเพื่อถวายเครื่องสัตวบูชายิ่งใหญ่แก่พระดาโกนพระของเขาทั้งหลายและชื่นชมยินดี เพราะเขากล่าวว่า “พระของเราได้มอบแซมสันศัตรูของเราไว้ในมือเราแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 24, 'เมื่อประชาชนเห็นแซมสันก็สรรเสริญพระของตนว่า “พระของเราได้มอบศัตรูผู้ทําลายแผ่นดินของเราไว้ในมือของเรา และเขาฆ่าพวกเราเสียเป็นอันมาก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 25, 'ต่อมาเมื่อจิตใจของเขาร่าเริงเต็มที่แล้ว เขาจึงพูดว่า “จงเรียกแซมสันมาเล่นตลกให้เราดู” เขาจึงไปเรียกแซมสันออกมาจากเรือนจํา แซมสันก็มาเล่นตลกต่อหน้าเขา เขาพาท่านมายืนอยู่ระหว่างเสา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 26, 'แซมสันจึงบอกเด็กที่จูงมือตนมาว่า “ขอพาข้าให้ไปคลําเสาที่รองรับตึกนี้อยู่ ข้าจะได้พิงเสานั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 27, 'มีผู้ชายและผู้หญิงอยู่เต็มตึกนั้น เจ้านายฟีลิสเตียก็อยู่ที่นั่นทั้งหมด นอกจากนั้นยังมีชายหญิงประมาณสามพันคนบนหลังคาตึก ดูแซมสันเล่นตลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 28, 'ฝ่ายแซมสันก็ร้องทูลต่อพระเยโฮวาห์ว่า “โอ ข้าแต่องค์พระผู้เป็นเจ้าพระเจ้า ขอทรงระลึกถึงข้าพระองค์ ขอประทานกําลังแก่ข้าพระองค์ครั้งนี้อีกครั้งเดียว โอ ข้าแต่พระเจ้า เพื่อในเวลานี้ข้าพระองค์จะได้แก้แค้นคนฟีลิสเตียเพื่อตาทั้งสองข้างของข้าพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 29, 'แซมสันก็กอดเสากลางสองต้นที่รองรับตึกนั้นไว้และพักพิงที่เสานั้น มือขวายันเสาต้นหนึ่ง มือซ้ายยันเสาอีกต้นหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 30, 'แซมสันกล่าวว่า “ขอให้ข้าตายกับคนฟีลิสเตียเถิด” แล้วก็โน้มตัวลงด้วยกําลังทั้งสิ้นของตน ตึกนั้นก็พังทับเจ้านายและประชาชนทุกคนที่อยู่ในนั้น ดังนั้นคนที่ท่านฆ่าตายเมื่อท่านตายนี้ก็มากกว่าคนที่ท่านฆ่าตายเมื่อท่านยังมีชีวิตอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 31, 'แล้วพี่น้องและบรรดาครอบครัวบิดาของท่านก็ลงมารับศพของท่านและขึ้นไปฝังไว้ระหว่างโศราห์กับเอชทาโอล ในที่ฝังศพของมาโนอาห์บิดาของท่าน ท่านได้วินิจฉัยอิสราเอลอยู่ยี่สิบปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 1, 'มีชายคนหนึ่งเป็นชาวแดนเทือกเขาเอฟราอิม ชื่อมีคาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 2, 'เขาพูดกับมารดาของเขาว่า “เงินหนึ่งพันหนึ่งร้อยแผ่น ซึ่งมีคนลักไปจากแม่และแม่ก็ได้สาปแช่ง และพูดเข้าหูลูกนั้น ดูเถิด เงินนั้นอยู่ที่ลูก ลูกเอาไปเอง” มารดาของเขาจึงพูดว่า “ขอพระเยโฮวาห์ทรงอํานวยพระพรให้ลูกของแม่เถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 3, 'เขาจึงนําเงินหนึ่งพันหนึ่งร้อยแผ่นนั้นมาคืนให้แก่มารดา และมารดาของเขาพูดว่า “เงินนี้แม่ได้ถวายแล้วแด่พระเยโฮวาห์จากมือแม่เพื่อลูกให้ทําเป็นรูปแกะสลักและรูปหล่อ บัดนี้แม่จึงคืนให้แก่ลูก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 4, 'เมื่อมีคาห์คืนเงินให้แก่มารดาแล้ว มารดาก็นําเงินสองร้อยแผ่นมอบให้กับช่างเงิน ทําเป็นรูปแกะสลักและรูปหล่อ รูปนั้นอยู่ในบ้านของมีคาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 5, 'มีคาห์คนนี้มีเรือนพระหลังหนึ่ง เขาทํารูปเอโฟด และเทราฟิม และแต่งตั้งให้บุตรชายคนหนึ่งของเขาเป็นปุโรหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 6, 'ในสมัยนั้นยังไม่มีกษัตริย์ในอิสราเอล ทุกคนทําตามอะไรก็ตามที่ถูกต้องในสายตาของตนเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 7, 'มีชายหนุ่มคนหนึ่งชาวบ้านเบธเลเฮมในยูดาห์ ครอบครัวยูดาห์ เป็นพวกเลวี อาศัยอยู่ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 8, 'ชายนั้นเดินออกจากบ้านเบธเลเฮมในยูดาห์ เที่ยวหาที่เพื่อพักอาศัย เมื่อเขาเดินทางไปนั้นก็มาถึงแดนเทือกเขาเอฟราอิมถึงบ้านของมีคาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 9, 'มีคาห์จึงพูดกับเขาว่า “ท่านมาจากไหน” เขาตอบว่า “ข้าพเจ้าเป็นพวกเลวีชาวบ้านเบธเลเฮมในยูดาห์ ข้าพเจ้าเดินทางเที่ยวหาที่พักอาศัย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 10, 'มีคาห์จึงกล่าวแก่เขาว่า “จงอยู่กับข้าพเจ้าเถิด เป็นอย่างบิดาและปุโรหิตของข้าพเจ้าก็แล้วกัน ข้าพเจ้าจะจ่ายเงินให้ปีละสิบเชเขล ให้เครื่องแต่งตัวสํารับหนึ่ง และอาหารรับประทานด้วย” เลวีคนนั้นจึงเข้าไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 11, 'เลวีคนนั้นก็พอใจที่จะอยู่กับชายคนนั้น และชายหนุ่มคนนั้นก็เป็นเหมือนลูกของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 12, 'มีคาห์ก็แต่งตั้งเลวีคนนั้นและชายหนุ่มคนนั้นก็เป็นปุโรหิตของเขา และอยู่ในบ้านของมีคาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 13, 'มีคาห์กล่าวว่า “บัดนี้ข้าพเจ้าทราบแล้วว่า พระเยโฮวาห์จะทรงให้ข้าพเจ้าอยู่เย็นเป็นสุข เพราะว่าข้าพเจ้ามีเลวีคนหนึ่งเป็นปุโรหิต”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 1, 'ในสมัยนั้นไม่มีกษัตริย์ในอิสราเอล และในสมัยนั้นคนตระกูลดานยังเที่ยวหาที่ดินอันจะเป็นมรดกของตนเพื่อจะได้พักอาศัย เพราะจนบัดนั้นแล้วมรดกในหมู่คนตระกูลอิสราเอลยังไม่ตกแก่เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 2, 'ดังนั้นคนดานจึงส่งคนห้าคนจากจํานวนทั้งหมดเป็นชายฉกรรจ์ในครอบครัวของตน มาจากโศราห์และจากเอชทาโอล ไปสอดแนมดูแผ่นดินและตรวจดูแผ่นดินนั้น และเขาทั้งหลายพูดแก่เขาว่า “จงไปตรวจดูแผ่นดินนั้น” เขาก็มาถึงแดนเทือกเขาเอฟราอิม ยังบ้านของมีคาห์และอาศัยอยู่ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 3, 'เมื่อเขาอยู่ใกล้บ้านของมีคาห์ เขาก็จําเสียงเลวีหนุ่มคนนั้นได้ จึงแวะเข้าไปถามว่า “ใครพาท่านมาที่นี่ ท่านทําอะไรในที่นี้ ท่านทํางานอะไรที่นี่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 4, 'เขาตอบคนเหล่านั้นว่า “มีคาห์ทําแก่ข้าพเจ้าอย่างนี้อย่างนี้ เขาจ้างข้าพเจ้า ข้าพเจ้าจึงเป็นปุโรหิตของเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 5, 'คนเหล่านั้นก็พูดกับเขาว่า “ได้โปรดทูลถามพระเจ้าให้หน่อยเถิด เพื่อเราจะทราบว่าทางที่เราจะออกเดินไปนี้จะสําเร็จหรือไม่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 6, 'ปุโรหิตนั้นจึงตอบเขาทั้งหลายว่า “จงไปเป็นสุขเถิด หนทางที่ท่านไปจะอยู่ต่อพระพักตร์พระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 7, 'ชายทั้งห้าคนก็จากไปถึงเมืองลาอิช เห็นประชาชนที่อยู่ที่เมืองนั้น เห็นชาวเมืองอยู่อย่างไร้กังวลตามลักษณะคนไซดอน อย่างสงบ ไม่หวาดระแวงอะไร และในแผ่นดินนั้นไม่มีผู้พิพากษาที่จะให้เขาอับอายในเรื่องใดๆ เขาอยู่ห่างไกลจากคนไซดอน ไม่มีเรื่องเกี่ยวข้องกับคนอื่นเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 8, 'เมื่อคนทั้งห้ากลับมาถึงญาติพี่น้องที่โศราห์และเอชทาโอล ญาติพี่น้องจึงถามเขาว่า “เจ้าจะว่าอะไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 9, 'เขาตอบว่า “จงลุกขึ้น ให้เราไปรบกับเขาเถิด เพราะเราได้เห็นแผ่นดินนั้นแล้ว และดูเถิด เป็นแผ่นดินดีจริงๆ ท่านทั้งหลายจะไม่ทําอะไรเลยหรือ อย่าชักช้าที่จะไปกันและเข้ายึดครองแผ่นดินนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 10, 'เมื่อท่านทั้งหลายไปแล้วจะพบประชาชนที่ไม่หวาดระแวงอะไร เออแผ่นดินก็กว้างขวาง พระเจ้าทรงมอบไว้ในมือของท่านทั้งหลายแล้ว เป็นสถานที่ซึ่งไม่ขาดสิ่งใดที่มีในโลก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 11, 'คนครอบครัวดานหกร้อยคนพร้อมสรรพด้วยเครื่องอาวุธทําสงครามยกทัพออกจากโศราห์และเอชทาโอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 12, 'เขาทั้งหลายยกขึ้นไปตั้งค่ายอยู่ที่คีริยาทเยอาริมในยูดาห์ เพราะเหตุนี้เขาจึงเรียกที่นั่นว่า มาหะเนห์ดาน จนถึงทุกวันนี้ ดูเถิด เมืองนี้อยู่ด้านหลังคีริยาทเยอาริม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 13, 'เขาก็ผ่านจากที่นั่นไปยังแดนเทือกเขาเอฟราอิมมาถึงบ้านของมีคาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 14, 'แล้วชายทั้งห้าคนที่ไปสอดแนมดูเมืองลาอิชก็บอกแก่พี่น้องของตนว่า “ท่านทราบไหมว่าในบ้านเหล่านี้มีรูปเอโฟด เทราฟิม รูปแกะสลัก และรูปหล่อ ฉะนั้นบัดนี้ขอใคร่ครวญว่าท่านทั้งหลายจะทําประการใด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 15, 'เขาทั้งหลายก็แวะเข้าบ้านของเลวีหนุ่มคนนั้น คือที่บ้านของมีคาห์ถามดูทุกข์สุขของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 16, 'ฝ่ายคนดานทั้งหกร้อยคนถืออาวุธทําสงคราม ยืนอยู่ที่ทางเข้าประตูรั้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 17, 'ชายทั้งห้าคนที่ออกไปสอดแนมดูบ้านเมืองก็เดินเข้าไปนําเอารูปแกะสลัก รูปเอโฟด เทราฟิม และรูปหล่อไป ฝ่ายปุโรหิตก็ยืนอยู่ที่ทางเข้าประตูรั้วกับทหารถืออาวุธทําสงครามหกร้อยคนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 18, 'เมื่อคนเหล่านี้เข้าไปในบ้านของมีคาห์ นําเอารูปแกะสลัก รูปเอโฟด เทราฟิม และรูปหล่อนั้น ปุโรหิตถามเขาว่า “นั่นท่านทําอะไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 19, 'คนเหล่านั้นจึงตอบเขาว่า “เงียบๆ ไว้เอามือปิดปากเสีย มากับเราเถิด มาเป็นบิดาและปุโรหิตของเรา จะเป็นปุโรหิตในบ้านของชายคนเดียวดี หรือว่าจะเป็นปุโรหิตของตระกูลหนึ่งและครอบครัวหนึ่งในอิสราเอลดี”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 20, 'ใจของปุโรหิตก็ยินดี เขาจึงเอารูปเอโฟด เทราฟิม และรูปแกะสลัก เดินไปในหมู่ประชาชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 21, 'แล้วเขาก็กลับออกเดินไปให้เด็ก ทั้งฝูงสัตว์และข้าวของเดินไปข้างหน้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 22, 'เมื่อไปห่างจากบ้านมีคาห์แล้ว คนที่อยู่ในบ้านใกล้เคียงกับบ้านของมีคาห์ก็ร่วมติดตามไปทันคนดานเข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 23, 'จึงตะโกนเรียกคนดาน เขาก็หันกลับมาพูดกับมีคาห์ว่า “เป็นอะไรเล่า เจ้าจึงยกคนมามากมายอย่างนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 24, 'เขาตอบว่า “ท่านทั้งหลายนําพระของข้าพเจ้าซึ่งข้าพเจ้าสร้างขึ้นและนําปุโรหิตออกมาเสีย ข้าพเจ้าจะมีอะไรเหลืออยู่เล่า ท่านทั้งหลายยังจะมาถามข้าพเจ้าอีกว่า ‘เป็นอะไรเล่า’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 25, 'คนดานจึงตอบเขาว่า “อย่าให้เราได้ยินเสียงของเจ้าเลย เกลือกว่าคนขี้โมโหจะเล่นงานเจ้าเข้า เจ้าและครอบครัวของเจ้าก็จะเสียชีวิตเปล่าๆ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 26, 'ฝ่ายคนดานก็เดินต่อไป เมื่อมีคาห์เห็นว่าเขาเหล่านั้นมีกําลังมากกว่า จึงหันกลับเดินทางไปบ้านของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 27, 'คนดานนําเอาสิ่งที่มีคาห์สร้างขึ้น และนําปุโรหิตซึ่งเป็นของเขามาด้วย ก็เดินทางมาถึงลาอิช มาถึงประชาชนที่อยู่อย่างสงบและมั่นคง จึงประหารคนเหล่านั้นด้วยคมดาบและเอาไฟเผาเมืองเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 28, 'ไม่มีผู้ใดมาช่วยเหลือ เพราะเขาอยู่ไกลจากเมืองไซดอน และไม่ได้ทําการเกี่ยวข้องกับคนอื่น อยู่ในหุบเขาซึ่งอยู่ใกล้กับเมืองเบธเรโหบ คนเหล่านั้นก็สร้างเมืองขึ้น และอาศัยอยู่ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 29, 'เขาตั้งชื่อเมืองนั้นว่าดาน ตามชื่อดานบรรพบุรุษของเขา ผู้ซึ่งเกิดกับอิสราเอล แต่ตอนแรกเมืองนั้นชื่อว่าลาอิช');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 30, 'คนดานก็ตั้งรูปแกะสลักไว้ ส่วนโยนาธานบุตรชายเกอร์โชม บุตรชายของมนัสเสห์ ทั้งท่านและบรรดาบุตรชายของเขาก็เป็นปุโรหิตให้แก่คนตระกูลดานจนถึงสมัยที่แผ่นดินตกไปเป็นเชลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 31, 'เขาได้ตั้งรูปแกะสลักซึ่งมีคาห์ได้ทําไว้นั้นขึ้นนานตลอดเวลาที่พระนิเวศของพระเจ้าอยู่ที่ชีโลห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 1, 'อยู่มาในสมัยนั้น เมื่อไม่มีกษัตริย์ในอิสราเอล มีคนเลวีคนหนึ่งอาศัยอยู่ที่แดนเทือกเขาเอฟราอิม แถบที่ไกลออกไปโน้น เขาได้หญิงคนหนึ่งจากเบธเลเฮมในยูดาห์มาเป็นภรรยาน้อย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 2, 'ภรรยาน้อยนั้นเล่นชู้จึงทิ้งสามีเสียกลับไปอยู่บ้านบิดาของนางที่เบธเลเฮมในยูดาห์ อยู่ที่นั่นสักสี่เดือน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 3, 'สามีของนางก็ลุกขึ้นไปตามนาง เพื่อไปพูดกับนางด้วยจิตเมตตาและจะพานางกลับ เขาพาคนใช้คนหนึ่งและลาคู่หนึ่งไปด้วย นางพาเขาเข้าในบ้านบิดาของนาง เมื่อบิดาของผู้หญิงเห็นเข้าก็มีความยินดีต้อนรับเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 4, 'พ่อตาของเขาคือบิดาของผู้หญิงหน่วงเหนี่ยวเขา และเขาพักอยู่ด้วยสามวัน เขาก็กินและดื่ม และพักนอนอยู่ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 5, 'อยู่มาถึงวันที่สี่เขาทั้งหลายก็ตื่นขึ้นแต่เช้ามืด และคนนั้นลุกขึ้นจะออกเดิน แต่พ่อของผู้หญิงพูดกับบุตรเขยของเขาว่า “จงรับประทานอาหารอีกสักหน่อยหนึ่งให้ชื่นใจแล้วภายหลังจึงค่อยออกเดิน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 6, 'ชายสองคนนั้นก็นั่งลงรับประทานและดื่มด้วยกัน และบิดาของผู้หญิงก็บอกชายนั้นว่า “จงค้างอีกสักคืนเถิด กระทําจิตใจให้เบิกบาน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 7, 'เมื่อชายคนนั้นลุกขึ้นจะออกเดิน พ่อตาก็ชักชวนไว้ จนเขาต้องพักอยู่ที่นั่นอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 8, 'ในวันที่ห้าเขาก็ตื่นแต่เช้าตรู่เพื่อจะออกเดินทางไป บิดาของหญิงนั้นพูดว่า “ขอให้ชื่นใจเถิด” เขาทั้งสองก็อยู่จนเวลาบ่ายรับประทานอยู่ด้วยกันอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 9, 'เมื่อชายคนนั้นและภรรยาน้อยกับคนใช้ลุกขึ้นจะออกเดิน พ่อตาของเขาคือบิดาของผู้หญิงก็บอกเขาว่า “ดูเถิด นี่ก็บ่ายใกล้ค่ําแล้ว ขอค้างอยู่อีกคืนหนึ่งเถิด ดูเถิด จะสิ้นวันอยู่แล้ว พักนอนที่นี่เถิด เพื่อใจของเจ้าจะเบิกบาน พรุ่งนี้เช้าขอเจ้าตื่นแต่เช้าเพื่อออกเดินทาง เจ้าจะได้ไปบ้าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 10, 'แต่ชายคนนั้นไม่ยอมค้างอีกคืนหนึ่ง เขาจึงลุกขึ้นออกเดินทางไปจนถึงตรงข้ามกับเมืองเยบุส คือเยรูซาเล็ม เขามีลาสองตัวที่มีอาน และภรรยาน้อยก็ไปด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 11, 'เมื่อเขามาใกล้เมืองเยบุสก็บ่ายมากแล้ว คนใช้จึงเรียนนายของเขาว่า “มาเถิด ให้เราแวะเข้าไปพักในเมืองของคนเยบุสเถิด ค้างคืนอยู่ในเมืองนี้แหละ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 12, 'นายของเขาตอบว่า “เราจะไม่แวะเข้าไปในเมืองของคนต่างด้าว ผู้ที่ไม่ใช่คนอิสราเอล เราจะผ่านไปถึงเมืองกิเบอาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 13, 'เขาจึงบอกคนใช้ว่า “มาเถิด ให้เราเข้าไปใกล้ที่เหล่านี้แห่งหนึ่ง และค้างอยู่ที่กิเบอาห์หรือที่รามาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 14, 'เขาจึงเดินทางผ่านไป เมื่อเขามาใกล้กิเบอาห์ซึ่งเป็นของคนเบนยามินดวงอาทิตย์ก็ตกแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 15, 'เขาจึงแวะเข้าไปจะค้างคืนที่เมืองกิเบอาห์ เขาก็แวะเข้าไปนั่งอยู่ที่ถนนในเมืองนั้น เพราะไม่มีใครเชิญให้เขาเข้าไปค้างในบ้าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 16, 'ดูเถิด มีชายแก่คนหนึ่งเข้ามาเมื่อเลิกจากงานนาเป็นเวลาเย็นแล้ว เขาเป็นชาวแดนเทือกเขาเอฟราอิมมาอาศัยอยู่ในเมืองกิเบอาห์ แต่ชาวเมืองนั้นเป็นคนเบนยามิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 17, 'เมื่อเขาเงยหน้าขึ้นเห็นผู้เดินทางคนนั้นนั่งอยู่ที่ถนนในเมือง ชายแก่คนนั้นก็ถามว่า “ท่านจะไปไหนและมาจากไหน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 18, 'ชายคนนั้นจึงตอบเขาว่า “เราเดินทางจากเบธเลเฮมในยูดาห์ จะไปที่แดนเทือกเขาเอฟราอิมแถบที่ไกลออกไปโน้นซึ่งข้าพเจ้ามาจากที่นั่น ข้าพเจ้าไปเบธเลเฮมในยูดาห์มา และข้าพเจ้าจะกลับไปพระนิเวศพระเยโฮวาห์ ไม่มีใครเชิญข้าพเจ้าเข้าไปพักในบ้าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 19, 'ฟางและอาหารที่จะเลี้ยงลา พวกเราก็มีพร้อมแล้ว ทั้งอาหารและน้ําองุ่นที่เลี้ยงตนทั้งเลี้ยงหญิงคนนี้ และชายหนุ่มที่อยู่กับพวกผู้รับใช้ของท่านก็มีอยู่แล้ว ไม่ขาดสิ่งใดเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 20, 'ชายแก่คนนั้นจึงพูดว่า “ขอท่านเป็นสุขสบายเถิด ถ้าท่านขาดสิ่งใด ข้าพเจ้าขอเป็นธุระทั้งสิ้น ขอแต่อย่านอนที่ถนนนี้เลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 21, 'เขาจึงพาชายคนนั้นเข้าไปในบ้าน เอาอาหารให้ลา ต่างก็ล้างเท้าของตน และรับประทานอาหารและดื่ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 22, 'เมื่อเขากําลังทําให้จิตใจเบิกบาน ดูเถิด ชาวเมืองนั้นที่เป็นลูกของเบลีอัลมาล้อมเรือนไว้ ทุบประตู ร้องบอกชายแก่ผู้เป็นเจ้าของบ้านว่า “ส่งชายที่เข้ามาอยู่ในบ้านของแกมาให้เราสังวาส”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 23, 'ชายผู้เป็นเจ้าของบ้านก็ออกไปพูดกับเขาว่า “อย่าเลย พี่น้องของข้าพเจ้า ขออย่ากระทําการร้ายเช่นนี้เลย เมื่อชายคนนี้มาอาศัยบ้านของข้าพเจ้าแล้ว ขออย่ากระทําสิ่งที่โง่เขลานี้เลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 24, 'ดูเถิด นี่ มีลูกสาวพรหมจารีคนหนึ่งและเมียน้อยของเขา ข้าพเจ้าจะพาออกมาให้ท่านเดี๋ยวนี้ จงกระทําหยามเกียรติหรือทําอะไรแก่พวกเขาตามชอบใจเถิด แต่ขออย่าทําลามกกับชายคนนี้เลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 25, 'แต่คนเหล่านั้นไม่ยอมฟังเสียง ชายคนนั้นจึงฉวยภรรยาน้อยของตนผลักนางออกไปให้เขา เขาก็ร่วมรู้ทําทารุณตลอดคืนจนรุ่งเช้า พอรุ่งสางๆ เขาทั้งหลายก็ปล่อยนางไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 26, 'พอแจ้งผู้หญิงนั้นก็กลับมาล้มลงที่ประตูบ้านซึ่งนายของตนพักอยู่ จนสว่างดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 27, 'รุ่งเช้านายของนางก็ลุกขึ้นเมื่อเปิดประตูบ้าน จะออกเดินทาง ดูเถิด ผู้หญิงซึ่งเป็นภรรยาน้อยของเขาก็นอนอยู่ที่ประตูบ้าน มือเหยียดออกไปถึงธรณีประตู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 28, 'เขาจึงบอกนางว่า “ลุกขึ้นไปกันเถิด” แต่ก็ไม่มีคําตอบ เขาจึงเอานางขึ้นหลังลา ชายนั้นก็ลุกขึ้นเดินทางไปบ้านของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 29, 'เมื่อถึงบ้านแล้ว ก็เอามีดฟันศพภรรยาน้อยออกเป็นท่อนๆพร้อมกับกระดูก สิบสองท่อนด้วยกันส่งไปทั่วเขตแดนอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 30, 'ทุกคนที่เห็นก็พูดว่า “เรื่องอย่างนี้ไม่มีใครเคยเห็นตั้งแต่สมัยคนอิสราเอลยกออกจากแผ่นดินอียิปต์จนถึงวันนี้ จงตรึกตรองปรึกษากันดู แล้วก็ว่ากันไปเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 1, 'คนอิสราเอลทั้งหมดตั้งแต่ดานถึงเบเออร์เชบา ทั้งแผ่นดินกิเลอาดก็ออกมา ชุมนุมชนนั้นได้ประชุมกันเป็นใจเดียวกันต่อพระเยโฮวาห์ที่เมืองมิสเปห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 2, 'หัวหน้าประชาชนทั้งสิ้นคือของตระกูลคนอิสราเอลทั้งหมด เข้ามาปรากฏตัวในที่ประชุมแห่งประชาชนของพระเจ้า มีทหารราบถือดาบสี่แสนคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 3, '(ครั้งนั้นคนเบนยามินได้ยินว่าคนอิสราเอลได้ขึ้นไปยังมิสเปห์) ประชาชนอิสราเอลกล่าวว่า “ขอบอกเรามาว่า เรื่องชั่วร้ายนี้เกิดขึ้นมาอย่างไรกัน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 4, 'คนเลวีซึ่งเป็นสามีของหญิงผู้ที่ถูกฆ่านั้นกล่าวตอบว่า “ข้าพเจ้าและภรรยาน้อยของข้าพเจ้ามาถึงเมืองกิเบอาห์ซึ่งเป็นของคนเบนยามิน เพื่อจะค้างคืนที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 5, 'เวลากลางคืนผู้ชายในเมืองกิเบอาห์ก็ลุกขึ้นล้อมบ้านที่ข้าพเจ้าพักอยู่ เขาหมายจะฆ่าข้าพเจ้าเสีย เขาข่มขืนภรรยาน้อยของข้าพเจ้าจนตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 6, 'ข้าพเจ้าจึงนําศพภรรยาน้อยของข้าพเจ้ามาฟันออกเป็นท่อนๆ ส่งไปทั่วประเทศที่เป็นมรดกของอิสราเอล เพราะพวกเขาได้กระทําการลามกและความโง่เขลาในอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 7, 'ดูเถิด ท่านผู้เป็นคนอิสราเอลทั้งหลาย จงให้คําปรึกษาและความเห็น ณ ที่นี่เถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 8, 'ประชาชนทุกคนก็ลุกขึ้นกล่าวเป็นใจเดียวกันว่า “พวกเราจะไม่กลับไปเต็นท์ของเรา เราจะไม่กลับไปเรือนของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 9, 'แต่บัดนี้เราจะกระทํากับกิเบอาห์ดังนี้ เราจะจับฉลากยกขึ้นไปสู้รบกับเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 10, 'เราจะเลือกคนอิสราเอลทุกตระกูลคัดเอาร้อยละสิบคน พันละร้อย หมื่นละพัน ให้ไปหาเสบียงอาหารมาให้ประชาชน เพื่อเขาทั้งหลายจะตอบสนองบรรดาความโง่เขลาซึ่งพวกกิเบอาห์กระทําขึ้นในอิสราเอล เมื่อเขาทั้งหลายมาถึงเมืองกิเบอาห์ของคนเบนยามิน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 11, 'คนอิสราเอลทั้งปวงก็ร่วมยกไปสู้เมืองนั้นเป็นพรรคพวกใจเดียวกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 12, 'ตระกูลคนอิสราเอลก็ส่งคนไปทั่วตระกูลคนเบนยามินบอกว่า “ทําไมการชั่วช้านี้จึงเกิดขึ้นมาได้ในหมู่พวกท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 13, 'เหตุฉะนั้นบัดนี้จงมอบชายลูกแห่งเบลีอัลในเมืองกิเบอาห์มาให้เราประหารชีวิตเสียจะได้กําจัดความชั่วเสียจากคนอิสราเอล” แต่คนเบนยามินไม่ยอมฟังเสียงคนอิสราเอลพี่น้องของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 14, 'คนเบนยามินก็ออกมาจากบรรดาหัวเมืองเข้าไปสู่กิเบอาห์พร้อมกันเพื่อยกออกไปกระทําสงครามกับคนอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 15, 'คราวนั้นคนเบนยามินรวมจํานวนทหารถือดาบออกจากบรรดาหัวเมืองได้สองหมื่นหกพันคน นอกจากชาวเมืองกิเบอาห์ ซึ่งนับทหารที่คัดเลือกแล้วได้เจ็ดร้อยคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 16, 'ในจํานวนทั้งหมดนี้มีคนที่คัดเลือกแล้วเจ็ดร้อยคนถนัดมือซ้ายทุกคนเอาสลิงเหวี่ยงก้อนหินให้ถูกเส้นผมได้ไม่ผิดเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 17, 'จํานวนคนอิสราเอลที่ถือดาบ ไม่นับคนเบนยามิน ได้สี่แสนคน เหล่านี้เป็นทหารทุกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 18, 'คนอิสราเอลก็ลุกขึ้นไปยังพระนิเวศของพระเจ้า และทูลถามพระเจ้าว่า “ผู้ใดในพวกข้าพระองค์ที่จะขึ้นไปสู้รบกับคนเบนยามินก่อน” พระเยโฮวาห์ตรัสว่า “ให้ยูดาห์ขึ้นไปก่อน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 19, 'รุ่งเช้าคนอิสราเอลก็ลุกขึ้นตั้งค่ายต่อสู้เมืองกิเบอาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 20, 'คนอิสราเอลออกไปสู้รบกับคนเบนยามิน และคนอิสราเอลได้วางพลเรียงรายต่อสู้เขาที่เมืองกิเบอาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 21, 'ในวันนั้นคนเบนยามินออกมาจากเมืองกิเบอาห์ ฆ่าฟันคนอิสราเอล ล้มตายสองหมื่นสองพันคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 22, 'แต่ประชาชนคือผู้ชายชาวอิสราเอลยังหนุนใจกันและวางพลเรียงรายอีกครั้งในที่ซึ่งเขาวางพลในวันแรก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 23, '(และคนอิสราเอลก็ขึ้นไปร้องไห้คร่ําครวญต่อพระพักตร์พระเยโฮวาห์จนถึงเวลาเย็น เขาทั้งหลายทูลถามพระเยโฮวาห์ว่า “สมควรที่ข้าพระองค์จะเข้าประชิดรบกับคนเบนยามินพี่น้องของข้าพระองค์อีกหรือไม่” พระเยโฮวาห์ตรัสว่า “ไปสู้เขาเถิด”)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 24, 'คนอิสราเอลจึงยกเข้าประชิดคนเบนยามินในวันที่สอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 25, 'และในวันที่สองนั้นเบนยามินก็ยกออกไปจากกิเบอาห์ ฆ่าฟันคนอิสราเอลล้มตายอีกหนึ่งหมื่นแปดพันคน ทุกคนเป็นทหารถือดาบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 26, 'แล้วบรรดาคนอิสราเอลคือกองทัพทั้งหมดได้ขึ้นไปที่พระนิเวศของพระเจ้าและร้องไห้คร่ําครวญ เขานั่งเฝ้าพระเยโฮวาห์ ณ ที่นั่น และอดอาหารจนเวลาเย็น ถวายเครื่องเผาบูชาและสันติบูชาต่อพระพักตร์พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 27, 'คนอิสราเอลจึงทูลถามพระเยโฮวาห์ (เพราะในสมัยนั้น หีบพันธสัญญาของพระเจ้าอยู่ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 28, 'และฟีเนหัสบุตรชายเอเลอาซาร์ ผู้เป็นบุตรชายอาโรน ก็ปรนนิบัติอยู่หน้าหีบนั้นในสมัยนั้น) เขาทูลถามว่า “สมควรที่ข้าพระองค์จะยังยกไปสู้รบกับเบนยามินพี่น้องของข้าพระองค์อีกครั้งหนึ่ง หรือควรจะหยุดเสีย” และพระเยโฮวาห์ตรัสว่า “จงยกขึ้นไปเถิด เพราะว่าพรุ่งนี้เราจะมอบเขาไว้ในมือของเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 29, 'ดังนั้น อิสราเอลจึงซุ่มคนไว้รอบเมืองกิเบอาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 30, 'และประชาชนอิสราเอลก็ขึ้นไปสู้รบกับคนเบนยามินในวันที่สาม และวางพลเรียงรายต่อสู้เมืองกิเบอาห์อย่างคราวก่อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 31, 'คนเบนยามินก็ยกออกมาสู้รบกับประชาชน ถูกลวงให้ห่างออกไปจากตัวเมือง เขาก็เริ่มฆ่าฟันประชาชนอย่างคราวก่อน คือตามถนนซึ่งสายหนึ่งไปยังพระนิเวศของพระเจ้า อีกสายหนึ่งไปกิเบอาห์ และที่กลางทุ่งแจ้ง อิสราเอลล้มตายประมาณสามสิบคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 32, 'คนเบนยามินกล่าวกันว่า “เขาแพ้เราอย่างคราวก่อน” แต่คนอิสราเอลว่า “ให้เราถอย นําเขาออกห่างจากเมืองไปถึงถนนหลวง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 33, 'คนอิสราเอลทั้งหมดก็ลุกออกจากที่ของตนเรียงรายเข้าไปที่บาอัลทามาร์ ส่วนคนอิสราเอลที่คอยซุ่มอยู่ก็ออกจากที่ของตนคือออกจากทุ่งหญ้าแห่งเมืองกิเบอาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 34, 'จากบรรดาคนอิสราเอลมีทหารที่คัดเลือกแล้วหนึ่งหมื่นคนรุกเข้าเมืองกิเบอาห์ การสงครามกําลังทรหด คนเบนยามินไม่ทราบว่าเหตุร้ายกําลังมาใกล้ตนแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 35, 'พระเยโฮวาห์ทรงให้คนเบนยามินพ่ายแพ้คนอิสราเอล ในวันนั้นคนอิสราเอลทําลายคนเบนยามินเสียสองหมื่นห้าพันหนึ่งร้อยคน ทุกคนเหล่านี้เป็นทหารถือดาบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 36, 'ดังนั้นคนเบนยามินจึงเห็นว่าเขาแพ้แล้ว คนอิสราเอลทําเป็นล่าถอยต่อเบนยามิน เพราะเขาวางใจคนที่เขาให้ซุ่มอยู่รอบเมืองกิเบอาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 37, 'คนที่ซุ่มอยู่ก็รีบรุกเข้าไปในเมืองกิเบอาห์ ทหารที่ซุ่มอยู่นั้นก็รุกออกมาประหารเมืองทั้งหมดนั้นเสียด้วยคมดาบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 38, 'คนอิสราเอลและคนที่ซุ่มซ่อนอยู่นัดให้อาณัติสัญญาณว่า ถ้าเห็นควันกลุ่มใหญ่พลุ่งขึ้นมาจากในเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 39, 'ก็ให้คนอิสราเอลหันกลับเข้ามารบ ฝ่ายเบนยามินได้เริ่มฆ่าคนอิสราเอลได้สักสามสิบคนก็พูดว่า “เขาต้องล้มตายต่อหน้าเราอย่างคราวก่อนแน่แล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 40, 'แต่อาณัติสัญญาณเป็นควันไฟลุกพลุ่งขึ้นมาจากในเมือง คนเบนยามินก็เหลียวหลังมาดู ดูเถิด ทั้งเมืองก็มีควันพลุ่งขึ้นถึงท้องฟ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 41, 'คนอิสราเอลก็หันกลับ คนเบนยามินก็ท้อแท้ เพราะเขาเห็นว่าเหตุร้ายมาใกล้เขาแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 42, 'เขาจึงหันหลังให้คนอิสราเอลหนีเข้าไปทางถิ่นทุรกันดาร แต่สงครามติดตามเขาไปอย่างหนัก คนที่ออกมาจากเมืองก็ทําลายเขาที่อยู่ท่ามกลาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 43, 'เขาทั้งหลายล้อมคนเบนยามิน และขับไล่เขาไปและชนะเขาอย่างง่าย จนไปถึงที่ตรงข้ามเมืองกิเบอาห์ทางดวงอาทิตย์ขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 44, 'คนเบนยามินล้มตายหนึ่งหมื่นแปดพันคน ทุกคนเป็นทแกล้วทหาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 45, 'เขาก็หันกลับหนีเข้าไปในถิ่นทุรกันดารถึงศิลาริมโมน คนอิสราเอลฆ่าเขาตายตามถนนหลวงห้าพันคน และติดตามอย่างกระชั้นชิดไปถึงกิโดม และฆ่าเขาตายสองพันคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 46, 'คนเบนยามินที่ล้มตายในวันนั้น เป็นทหารถือดาบสองหมื่นห้าพันคน ทุกคนเป็นทแกล้วทหาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 47, 'แต่มีทหารหกร้อยคนหันกลับหนีเข้าไปในถิ่นทุรกันดารถึงศิลาริมโมน และไปอาศัยอยู่ที่ศิลาริมโมนสี่เดือน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 48, 'คนอิสราเอลก็หันกลับไปสู้คนเบนยามินอีก และได้ประหารเขาเสียด้วยคมดาบ ทั้งชาวเมืองและฝูงสัตว์และบรรดาสิ่งที่เขาเห็น ยิ่งกว่านั้นบรรดาเมืองที่เขาพบเขาก็เอาไฟเผาเสียทั้งหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 1, 'ฝ่ายคนอิสราเอลได้สาบานไว้ที่มิสเปห์ว่า “พวกเราไม่มีใครสักคนเดียวที่จะให้บุตรสาวของตนแต่งงานกับคนเบนยามิน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 2, 'และประชาชนก็มาที่พระนิเวศของพระเจ้า นั่งอยู่ต่อพระพักตร์พระเจ้าจนเวลาเย็น เขาทั้งหลายก็ร้องไห้คร่ําครวญหนักหนา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 3, 'เขากล่าวว่า “โอ พระเยโฮวาห์พระเจ้าแห่งอิสราเอล ทําไมเหตุการณ์อย่างนี้จึงเกิดขึ้นในอิสราเอล ซึ่งวันนี้จะมีคนอิสราเอลขาดไปตระกูลหนึ่ง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 4, 'อยู่มารุ่งขึ้นประชาชนก็ลุกขึ้นแต่เช้าตรู่ และสร้างแท่นบูชาแท่นหนึ่ง ถวายเครื่องเผาบูชาและเครื่องสันติบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 5, 'และคนอิสราเอลกล่าวว่า “คนใดในบรรดาตระกูลของอิสราเอลที่มิได้ขึ้นมาประชุมต่อพระเยโฮวาห์” เพราะเขาได้สาบานไว้แข็งแรงถึงผู้ที่มิได้มาประชุมต่อพระเยโฮวาห์ที่มิสเปห์ว่า “ผู้นั้นจะต้องถูกโทษถึงตายเป็นแน่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 6, 'และประชาชนอิสราเอลก็เสียใจกับเบนยามินน้องของตน กล่าวว่า “วันนี้ตระกูลหนึ่งถูกตัดขาดจากอิสราเอลเสียแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 7, 'เราจะทําอย่างไรเรื่องหาภรรยาให้คนที่ยังเหลืออยู่ ฝ่ายเราก็ได้สาบานในพระนามพระเยโฮวาห์แล้วว่า เราจะไม่ยอมยกบุตรสาวของเราให้เป็นภรรยาของเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 8, 'เขาทั้งหลายถามขึ้นว่า “มีตระกูลใดในอิสราเอลที่มิได้ขึ้นมาเฝ้าพระเยโฮวาห์ที่มิสเปห์” ดูเถิด ไม่มีคนใดจากยาเบชกิเลอาดมาประชุมที่ค่ายเลยสักคนเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 9, 'เพราะว่าเมื่อเขานับจํานวนประชาชนอยู่นั้น ดูเถิด ไม่มีชาวเมืองยาเบชกิเลอาดอยู่ที่นั่นเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 10, 'ดังนั้นชุมนุมชนจึงส่งทหารผู้กล้าหาญที่สุดหนึ่งหมื่นสองพันคนแล้วบัญชาเขาว่า “จงไปฆ่าชาวยาเบชกิเลอาดเสียด้วยคมดาบ ทั้งผู้หญิงและพวกเด็กๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 11, 'เจ้าทั้งหลายจงกระทําอย่างนี้ คือจงฆ่าผู้ชายทุกคนเสียให้หมด พร้อมกับผู้หญิงทุกคนที่ได้หลับนอนกับผู้ชายแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 12, 'ในหมู่ชาวยาเบชกิเลอาดนั้นเขาพบหญิงพรหมจารีสี่ร้อยคนผู้ที่ยังไม่เคยร่วมหลับนอนกับชายใดๆเลย เขาจึงพาหญิงเหล่านั้นมาที่ค่ายชีโลห์ซึ่งอยู่ในแผ่นดินคานาอัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 13, 'ชุมนุมชนทั้งหมดก็ส่งข่าวไปที่คนเบนยามินซึ่งอยู่ที่ศิลาริมโมน ประกาศข่าวสงบสุข');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 14, 'คนเบนยามินก็กลับมาในคราวนั้น แล้วเขาก็มอบผู้หญิงที่เขาไว้ชีวิตในหมู่ผู้หญิงแห่งยาเบชกิเลอาด แต่ก็ไม่พอแก่กัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 15, 'ประชาชนก็สงสารเบนยามิน เพราะว่าพระเยโฮวาห์ทรงกระทําให้เขาขาดไปตระกูลหนึ่งจากตระกูลอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 16, 'พวกผู้ใหญ่ของชุมนุมชนนั้นจึงกล่าวว่า “เมื่อพวกผู้หญิงในเบนยามินถูกทําลายเสียหมดเช่นนี้แล้ว เราจะทําอย่างไรเรื่องหาภรรยาให้คนที่ยังเหลืออยู่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 17, 'เขาทั้งหลายกล่าวว่า “ต้องมีมรดกให้แก่คนเบนยามินที่รอดตาย เพื่อว่าคนตระกูลหนึ่งจะมิได้ลบล้างเสียจากอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 18, 'แต่เราจะยกบุตรสาวของเราให้เป็นภรรยาเขาก็ไม่ได้” เพราะคนอิสราเอลได้สาบานไว้ว่า “ผู้ใดให้หญิงแก่เบนยามินเป็นภรรยาขอให้ถูกสาปแช่งเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 19, 'ดังนั้นเขาจึงกล่าวว่า “ดูเถิด ทุกปีมีเทศกาลถวายพระเยโฮวาห์ที่ชีโลห์ ในสถานที่ซึ่งอยู่เหนือเบธเอล ทางทิศตะวันออกของถนนขึ้นจากเบธเอลถึงเชเคม และอยู่ใต้เลโบนาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 20, 'เขาจึงบัญชาสั่งคนเบนยามินว่า “จงไปซุ่มอยู่ในสวนองุ่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 21, 'คอยเฝ้าดูอยู่ และดูเถิด ถ้าบุตรสาวชาวชีโลห์ออกมาเต้นรําในพิธีเต้นรํา จงออกมาจากสวนองุ่น ฉุดเอาบุตรสาวชาวชีโลห์คนละคนไปเป็นภรรยาของตน แล้วให้กลับไปแผ่นดินเบนยามินเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 22, 'ถ้าบิดาหรือพี่น้องของหญิงเหล่านั้นมาร้องทุกข์ต่อเรา เราจะบอกเขาว่า ‘ขอโปรดยินยอมเพราะเห็นแก่เราเถิด ในเวลาสงครามเราไม่ได้ผู้หญิงให้พอแก่ทุกคน ทั้งท่านทั้งหลายเองก็ไม่ได้ให้แก่เขา ถ้ามิฉะนั้นบัดนี้พวกท่านก็จะมีโทษ’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 23, 'คนเบนยามินก็กระทําตาม ต่างก็ได้ภรรยาไปตามจํานวน คือได้หญิงเต้นรําที่เขาไปฉุดมา เขาก็กลับไปอยู่ในที่ดินมรดกของเขา สร้างเมืองขึ้นใหม่และอาศัยอยู่ในนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 24, 'ครั้งนั้นประชาชนอิสราเอลก็กลับจากที่นั่นไปยังตระกูลและครอบครัวของตน ต่างก็ยกกลับไปสู่ดินแดนมรดกของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 25, 'ในสมัยนั้นไม่มีกษัตริย์ในอิสราเอล ทุกคนทําตามอะไรก็ตามที่ถูกต้องในสายตาของตนเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 1, 'อยู่มาในสมัยเมื่อผู้วินิจฉัยครอบครองอยู่นั้นเกิดกันดารอาหารขึ้นในแผ่นดิน มีชายคนหนึ่งเป็นชาวเมืองเบธเลเฮมในยูดาห์ไปอาศัยอยู่ในแผ่นดินโมอับ คือตัวเขาพร้อมกับภรรยาและบุตรชายสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 2, 'ชายคนนั้นชื่อเอลีเมเลค ภรรยาชื่อนาโอมี บุตรชายสองคนชื่อมาห์โลนและคิลิโอน เป็นชาวเอฟราธาห์ มาจากเมืองเบธเลเฮมในยูดาห์ เขาทั้งหลายเดินทางเข้าไปในแผ่นดินโมอับและอาศัยอยู่ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 3, 'แต่เอลีเมเลคสามีของนางนาโอมีสิ้นชีวิตเสีย ทิ้งนางไว้กับบุตรชายทั้งสอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 4, 'บุตรชายสองคนนี้ก็ได้หญิงชาวโมอับมาเป็นภรรยา คนหนึ่งชื่อโอรปาห์ อีกคนหนึ่งชื่อรูธ เขาทั้งหลายอยู่ที่นั่นประมาณสิบปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 5, 'แล้วมาห์โลนและคิลิโอนทั้งสองคนก็สิ้นชีวิต หญิงคนนั้นก็ต้องเปล่าเปลี่ยวเพราะเหตุสามีและบุตรชายทั้งสองของนางต้องล้มหายตายจากไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 6, 'แล้วนางนั้นพร้อมกับลูกสะใภ้ทั้งสองก็ลุกขึ้นออกเดินทางจากแผ่นดินโมอับ เพราะว่าเมื่ออยู่ในแผ่นดินโมอับนั้น นางได้ยินข่าวว่า พระเยโฮวาห์ได้ทรงเยี่ยมเยียนชนชาติของพระองค์และประทานอาหารแก่เขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 7, 'นางจึงออกจากตําบลที่นางอยู่พร้อมกับบุตรสะใภ้ทั้งสอง เดินตามทางกลับไปยังแผ่นดินยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 8, 'แต่นาโอมีกล่าวแก่บุตรสะใภ้ทั้งสองของนางว่า “ไปเถิด ขอให้ต่างคนต่างกลับไปบ้านมารดาของตน ขอพระเยโฮวาห์ทรงพระเมตตาต่อเจ้าทั้งสอง ดังที่เจ้าได้เมตตาต่อผู้ที่ตายไปแล้วและต่อแม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 9, 'ขอพระเยโฮวาห์ทรงโปรดให้เจ้ามีความสงบ ขอให้ต่างก็ได้เข้าอยู่ในเรือนของสามี” แล้วนาโอมีก็จุบลูกสะใภ้ทั้งสอง ต่างก็ส่งเสียงร้องไห้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 10, 'นางทั้งสองจึงพูดกับแม่สามีว่า “อย่าเลย เราทั้งสองจะกลับไปกับแม่ไปถึงชนชาติของแม่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 11, 'แต่นาโอมีตอบว่า “ลูกสาวของแม่เอ๋ย จงกลับไปเสียเถอะ จะไปกับแม่ทําไมเล่า แม่ยังจะมีบุตรชายในครรภ์ให้เป็นสามีของเจ้าหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 12, 'ลูกสาวของแม่เอ๋ย กลับไปเสียเถอะ กลับไปตามทางของเจ้า แม่แก่เกินที่จะมีสามีแล้ว หากแม่จะว่าแม่ยังมีความหวังอยู่ ถ้าแม่จะมีสามีคืนวันนี้และให้กําเนิดบุตรชาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 13, 'แล้วเจ้าจะรออยู่จนบุตรชายนั้นเติบโตได้หรือ เจ้าจะอดใจไม่แต่งงานหรือ อย่าเลยลูกสาวของแม่เอ๋ย แม่มีความขมขื่นมากเพราะเห็นแก่เจ้า ที่พระหัตถ์ของพระเยโฮวาห์ได้กระทําแก่แม่ถึงเพียงนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 14, 'แล้วต่างก็ส่งเสียงร้องไห้อีก โอรปาห์ก็จุบลาแม่สามี แต่รูธยังเกาะแม่สามีอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 15, 'นาโอมีจึงว่า “ดูเถิด พี่สะใภ้ของเจ้ากลับไปหาชนชาติของเขาและหาพระของเขาแล้ว จงกลับไปตามพี่สะใภ้ของเจ้าเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 16, 'แต่รูธตอบว่า “ขอแม่อย่าวิงวอนให้ฉันจากแม่หรือเลิกติดตามแม่ไปเลย เพราะแม่จะไปไหนฉันจะไปด้วย และแม่จะอาศัยอยู่ที่ไหนฉันก็จะอยู่ที่นั่นด้วย ญาติของแม่จะเป็นญาติของฉัน และพระเจ้าของแม่ก็จะเป็นพระเจ้าของฉัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 17, 'แม่ตายที่ไหนฉันจะตายที่นั่น และจะขอให้ฝังฉันไว้ที่นั่นด้วย ถ้ามีอะไรมาพรากฉันจากแม่นอกจากความตาย ก็ขอพระเยโฮวาห์ทรงลงโทษฉัน และให้หนักยิ่งกว่า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 18, 'เมื่อนาโอมีเห็นว่ารูธตั้งใจจะไปด้วยจริงๆแล้ว นางก็ไม่พูดอะไรอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 19, 'ดังนั้นทั้งสองนางก็พากันไปจนถึงเมืองเบธเลเฮม ต่อมาเมื่อนางทั้งสองมาถึงเบธเลเฮมแล้ว ชาวเมืองทั้งสิ้นก็พากันแตกตื่นเพราะเหตุนางทั้งสอง จึงพูดขึ้นว่า “นี่แน่ะหรือ นางนาโอมี”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 20, 'นาโอมีตอบเขาว่า “ขออย่าเรียกฉันว่านาโอมีเลย ขอเรียกฉันว่ามาราเถอะ เพราะว่าองค์ผู้ทรงมหิทธิฤทธิ์ได้ทรงกระทําแก่ฉันอย่างขมขื่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 21, 'เมื่อฉันจากเมืองนี้ไป ฉันมีทุกอย่างครบบริบูรณ์ พระเยโฮวาห์ทรงพาฉันกลับมาตัวเปล่า เมื่อพระเยโฮวาห์ทรงให้ฉันทุกข์ใจดังนี้ และองค์ผู้ทรงมหิทธิฤทธิ์ให้ฉันต้องประสบเหตุร้ายเช่นนี้จะเรียกฉันว่านาโอมีทําไมเล่า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 22, 'ดังนั้นนาโอมีจึงกลับมา และรูธลูกสะใภ้ชาวโมอับก็กลับมาด้วย ผู้กลับมาจากแผ่นดินโมอับ และเขาทั้งสองมายังเมืองเบธเลเฮมในต้นฤดูเกี่ยวข้าวบาร์เลย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 1, 'ฝ่ายนาโอมีนั้นมีญาติข้างสามีคนหนึ่ง เป็นคนมั่งมี ครอบครัวเดียวกับเอลีเมเลค ชื่อโบอาส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 2, 'และรูธชาวโมอับจึงพูดกับนาโอมีว่า “บัดนี้ขอให้ฉันไปที่ทุ่งนา เพื่อจะเก็บรวงข้าวตกตามหลังผู้ที่มีสายตากรุณาต่อฉัน” นาโอมีตอบนางว่า “ลูกสาวของแม่เอ๋ย จงไปเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 3, 'นางก็ออกเดินตามหลังคนเกี่ยวเพื่อคอยเก็บข้าวตก เผอิญเข้าไปในนาของโบอาส ซึ่งเป็นญาติของเอลีเมเลค');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 4, 'ดูเถิด โบอาสมาจากเบธเลเฮม พูดกับคนเกี่ยวข้าวว่า “ขอพระเยโฮวาห์ทรงสถิตอยู่กับเจ้าเถิด” เขาทั้งหลายตอบว่า “ขอพระเยโฮวาห์ทรงอํานวยพระพรแก่ท่านเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 5, 'โบอาสจึงถามคนใช้ผู้คอยควบคุมคนเกี่ยวข้าวนั้นว่า “หญิงสาวคนนี้เป็นคนของใคร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 6, 'คนใช้ซึ่งเป็นผู้ควบคุมคนเกี่ยวข้าวจึงตอบว่า “นางเป็นหญิงชาวโมอับ กลับมาจากแผ่นดินโมอับพร้อมกับนาโอมี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 7, 'นางพูดว่า ‘ขออนุญาตให้ดิฉันเดินตามคนเกี่ยวคอยเก็บข้าวตกระหว่างฟ่อนข้าวเถอะค่ะ’ นางก็มาเก็บข้าวตกตั้งแต่เวลาเช้าจนบัดนี้ เว้นแต่ได้พักหน่อยหนึ่งที่เรือน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 8, 'แล้วโบอาสจึงพูดกับรูธว่า “ลูกสาวเอ๋ย ขอฟังหน่อย อย่าไปเก็บข้าวที่นาอื่น หรือทิ้งนานี้ไปเสียเลย จงอยู่ใกล้ๆสาวใช้ของฉัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 9, 'ตาของเจ้าจงมองดูตามนาที่เขากําลังเก็บเกี่ยวกันอยู่ แล้วก็จงติดตามเขาไป ฉันได้สั่งพวกหนุ่มๆมิให้รบกวนเจ้าแล้วมิใช่หรือ เมื่อเจ้ากระหายน้ําก็เชิญไปที่หม้อน้ํา ดื่มน้ําซึ่งคนหนุ่มๆตักไว้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 10, 'รูธก็ซบหน้าน้อมตัวลงถึงดินและพูดว่า “ทําไมดิฉันจึงได้รับความกรุณาในสายตาของท่าน ท่านจึงเอาใจใส่ดิฉันในเมื่อดิฉันเป็นแต่เพียงคนต่างด้าว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 11, 'แต่โบอาสตอบนางว่า “ทุกอย่างที่เจ้าได้ปฏิบัติต่อแม่สามีของเจ้าตั้งแต่สามีของเจ้าสิ้นชีวิตแล้วนั้น มีคนมาเล่าให้ฉันฟังหมดแล้ว และเขาบอกด้วยว่า เจ้ายอมจากบิดามารดาและบ้านเกิดเมืองนอนของเจ้า มาอยู่กับชนชาติที่เจ้าไม่รู้จักมาก่อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 12, 'ขอพระเยโฮวาห์ทรงตอบแทนการงานของเจ้าตามที่เจ้าได้กระทํามาแล้วนั้นเถิด และขอให้พระเยโฮวาห์พระเจ้าของชนชาติอิสราเอลซึ่งเจ้าเข้ามาวางใจอยู่ใต้ปีกของพระองค์นั้น จงทรงปูนบําเหน็จอันบริบูรณ์แก่เจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 13, 'รูธจึงกล่าวว่า “เจ้านายของดิฉัน ขอให้ดิฉันได้รับความกรุณาในสายตาของท่าน เพราะท่านได้ปลอบใจดิฉัน และเพราะท่านได้กล่าวคําที่แสดงความเมตตากรุณาต่อหญิงคนใช้ของท่าน ถึงแม้ดิฉันไม่เป็นเหมือนคนหนึ่งในพวกหญิงคนใช้ของท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 14, 'โบอาสก็บอกนางว่า “พอถึงเวลารับประทานอาหารเชิญมานี่เถิด มารับประทานขนมปังบ้าง และเอาอาหารมาจิ้มน้ําส้มเถิด” นางจึงนั่งลงข้างๆพวกคนเกี่ยวข้าว โบอาสจึงส่งข้าวคั่วให้ และนางก็รับประทานจนอิ่ม และยังเหลือไว้บ้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 15, 'เมื่อนางลุกขึ้นไปเก็บข้าว โบอาสก็บัญชาชายหนุ่มของท่านว่า “จงยอมให้นางเก็บข้าวตกระหว่างฟ่อนข้าวเถอะ อย่าได้ตําหนินางเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 16, 'จงดึงข้าวออกจากฟ่อนทิ้งไว้ให้นางเก็บบ้าง อย่าว่านางเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 17, 'นางก็เที่ยวเก็บข้าวที่ตกในนาจนถึงเวลาเย็น แล้วก็ฟาดข้าวที่เก็บมาได้นั้น ได้ข้าวบาร์เลย์ประมาณเอฟาห์หนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 18, 'นางยกข้าวนั้นขึ้นและเข้าไปในเมือง แม่สามีก็เห็นข้าวที่นางได้เก็บมานั้น และนางเอาอาหารที่เหลือเมื่อนางรับประทานอิ่มแล้วนั้นให้แก่แม่สามีด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 19, 'แม่สามีจึงกล่าวแก่นางว่า “วันนี้ลูกไปเก็บข้าวตกที่ไหนมา ลูกไปทํางานที่ไหน ขอให้ชายที่เอาใจใส่ลูกได้รับพระพรเถิด” นางจึงบอกแก่แม่สามีให้ทราบว่านางไปทํางานกับผู้ใด นางว่า “ผู้ชายที่ฉันไปทํางานด้วยในวันนี้นั้นชื่อโบอาส”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 20, 'นาโอมีจึงพูดกับบุตรสะใภ้ว่า “ขอพระเยโฮวาห์ทรงอํานวยพระพรแก่เขาเถิด พระกรุณาของพระองค์ไม่เคยขาดจากผู้ที่ยังมีชีวิตอยู่หรือผู้ที่สิ้นชีวิตไปแล้ว” นาโอมีกล่าวแก่นางด้วยว่า “ชายคนนั้นเป็นญาติของเรา เขาเป็นญาติสนิทคนหนึ่งของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 21, 'รูธชาวโมอับกล่าวว่า “นอกจากนั้นเขายังพูดกับฉันว่า ‘เจ้าจงอยู่ใกล้ๆคนใช้หนุ่มของฉันจนกว่าเขาจะเกี่ยวข้าวของฉันเสร็จ’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 22, 'นาโอมีพูดกับรูธบุตรสะใภ้ว่า “ดีแล้ว ลูกสาวของแม่เอ๋ย ที่เจ้าจะไปทํางานกับสาวใช้ของเขา เพื่อว่าเขาจะไม่พบเจ้าในนาอื่น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 23, 'ดังนั้นนางจึงอยู่ใกล้ๆสาวใช้ของโบอาสเที่ยวเก็บข้าวตกจนสิ้นฤดูเกี่ยวข้าวบาร์เลย์และข้าวสาลี และนางก็อาศัยอยู่กับแม่สามี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 1, 'นาโอมีแม่สามีของนางพูดกับนางว่า “ลูกสาวของแม่เอ๋ย ถ้าแม่จะหาที่พึ่งพักให้เจ้า เพื่อเจ้าจะได้มีความสุขไม่ควรหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 2, 'โบอาสผู้ที่เจ้าไปกับพวกสาวใช้ของเขานั้น เป็นญาติของเรามิใช่หรือ ดูเถิด คืนวันนี้เขาจะซัดข้าวบาร์เลย์ที่ลานนวดข้าว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 3, 'จงอาบน้ํา ทาน้ํามันสวมเครื่องแต่งกายแล้วลงไปที่ลานนวดข้าว แต่อย่าให้ท่านเห็นตัวจนกว่าท่านจะรับประทานและดื่มเสร็จแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 4, 'เขานอนที่ไหนจงสังเกตไว้ให้ดีแล้วจงไปเปิดผ้าคลุมเท้าขึ้นและจงนอนที่นั่น ต่อไปท่านจะบอกเจ้าเองว่าเจ้าจะต้องทําประการใด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 5, 'นางตอบว่า “แม่ว่าอย่างไร ฉันจะกระทําตามทุกอย่าง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 6, 'ดังนั้นนางจึงลงไปยังลานนวดข้าว และกระทําตามที่แม่สามีบอกทุกอย่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 7, 'เมื่อโบอาสรับประทานและดื่มจนสําราญใจแล้ว ท่านก็ไปนอนอยู่ที่ปลายกองข้าว แล้วนางก็ย่องเข้ามาเปิดผ้าคลุมเท้าของท่านขึ้น และนอนลงที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 8, 'ต่อมาพอถึงเที่ยงคืนชายคนนั้นก็ตกใจตื่นพลิกตัว ดูเถิด มีผู้หญิงมานอนอยู่ที่เท้าของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 9, 'ท่านจึงถามว่า “เจ้าเป็นใคร” นางตอบว่า “ดิฉันคือรูธหญิงคนใช้ของท่านค่ะ ขอให้ท่านกางชายเสื้อของท่านห่มหญิงคนใช้ของท่านด้วย เพราะท่านเป็นญาติสนิทถัดมา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 10, 'ท่านจึงว่า “ลูกสาวเอ๋ย ขอพระเยโฮวาห์ทรงอํานวยพระพรแก่เจ้าเถิด คุณของเจ้าครั้งหลังนี้ก็ใหญ่ยิ่งกว่าครั้งก่อน ด้วยว่าเจ้ามิได้ไปหาคนหนุ่ม ไม่ว่าจนหรือมั่งมี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 11, 'บัดนี้ ลูกสาวเอ๋ย เจ้าอย่ากลัวเลย สิ่งที่เจ้าขอร้องเราจะกระทําตามทุกอย่าง บรรดาผู้หลักผู้ใหญ่ของเมืองเราทราบดีอยู่ว่าเจ้าเป็นผู้หญิงที่ดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 12, 'และก็เป็นความจริงด้วยที่ฉันเป็นญาติสนิท แต่ยังมีญาติอีกคนหนึ่งที่สนิทกว่าฉัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 13, 'คืนนี้เจ้าจงค้างที่นี่ก่อน พรุ่งนี้เช้า ถ้าเขาจะทําหน้าที่ญาติสนิทเพื่อเจ้าก็ดีแล้ว ให้เขาทําหน้าที่ญาติสนิทเถอะ แต่ถ้าเขาไม่เต็มใจที่จะทําหน้าที่ญาติสนิทที่ถัดมาเพื่อเจ้า พระเยโฮวาห์ทรงพระชนม์อยู่แน่ฉันใด ฉันจะทําหน้าที่ญาติสนิทที่ถัดมาเพื่อเจ้าแน่ฉันนั้น จงนอนลงเถิดจนกว่าจะรุ่งเช้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 14, 'ดังนั้นนางจึงนอนอยู่ที่เท้าของท่านจนรุ่งเช้า แต่นางลุกขึ้นก่อนคนจะจําหน้ากันได้ เพราะท่านคิดว่า “อย่าให้ใครทราบว่ามีผู้หญิงมาที่ลานนวดข้าว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 15, 'ท่านพูดว่า “จงเอาผ้าคลุมที่เจ้าใช้อยู่นั้นคลี่ออก” นางก็คลี่ผ้าคลุมออก ท่านก็ตวงข้าวบาร์เลย์หกทะนานให้นางแบกไป แล้วก็เข้าไปในเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 16, 'เมื่อนางมาถึง แม่สามีจึงถามว่า “เป็นใครหนอ ลูกสาวของแม่เอ๋ย” แล้วนางก็เล่าตามที่ท่านได้กระทําต่อนางให้แม่สามีฟังทุกอย่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 17, 'และนางว่า “ท่านให้ข้าวบาร์เลย์หกทะนานนี้แก่ฉัน ท่านว่า ‘เจ้าอย่ากลับไปหาแม่สามีมือเปล่าเลย’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 18, 'แม่สามีจึงว่า “ลูกสาวของแม่เอ๋ย จงคอยอยู่ก่อน จนกว่าจะทราบว่าเรื่องจะลงเอยอย่างไร เพราะว่าท่านจะไม่หยุดเลยจนกว่าท่านจะจัดการเรื่องนี้ให้เสร็จในวันนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 1, 'โบอาสก็ขึ้นไปที่ประตูเมืองและนั่งอยู่ที่นั่น ดูเถิด ญาติสนิทคนที่ถัดมาซึ่งโบอาสกล่าวถึงก็เดินผ่านมา โบอาสจึงกล่าวว่า “โอ คนเช่นนี้ แวะมานั่งที่นี่ก่อนเถิด” เขาก็แวะมานั่งลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 2, 'ท่านจึงไปเชิญพวกผู้ใหญ่ในเมืองนั้นมาสิบคนกล่าวว่า “เชิญนั่งที่นี่เถิด” เขาทั้งหลายก็นั่งลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 3, 'ท่านจึงพูดกับญาติสนิทที่ถัดมานั้นว่า “นาซึ่งเป็นส่วนของเอลีเมเลคญาติของเรานั้น นาโอมีผู้ที่กลับมาจากแผ่นดินโมอับอยากจะขายเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 4, 'ข้าพเจ้าคิดว่า ข้าพเจ้าควรบอกให้ท่านทราบ และขอบอกว่า ขอท่านซื้อไว้ต่อหน้าพลเมืองและต่อหน้าพวกผู้ใหญ่ของชาวเมืองเรา ถ้าท่านอยากจะไถ่ไว้ก็จงไถ่เถิด แต่ถ้าท่านไม่ไถ่จงบอกข้าพเจ้า ข้าพเจ้าจะได้ทราบ นอกจากท่านแล้วไม่มีใครมีสิทธิ์ไถ่ได้ ข้าพเจ้ามีสิทธิ์ถัดท่านไป” ผู้นั้นจึงบอกโบอาสว่า “ข้าพเจ้าจะไถ่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 5, 'แล้วโบอาสบอกว่า “ในวันที่ท่านซื้อที่นาจากมือนาโอมีนั้น ท่านก็จะได้รูธชาวโมอับภรรยาของผู้ตายด้วย เพื่อจะจรรโลงนามของผู้ตายไว้กับมรดกของเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 6, 'ญาติสนิทที่ถัดมาคนนั้นตอบว่า “ข้าพเจ้าจะไถ่เพื่อตนเองอย่างนั้นไม่ได้ จะทําให้มรดกข้าพเจ้าเสียไป ท่านจงเอาสิทธิในการไถ่ของข้าพเจ้าไปจัดการเองเถิด เพราะข้าพเจ้าไถ่ไม่ได้แล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 7, 'ต่อไปนี้เป็นธรรมเนียมในอิสราเอลสมัยก่อนเกี่ยวกับการไถ่และการแลกเปลี่ยน คือเพื่อจะรับรองการตกลงกัน คนหนึ่งจะถอดรองเท้าของเขาเองยื่นให้อีกคนหนึ่ง นี่เป็นธรรมเนียมของการแสดงสักขีพยานในอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 8, 'ดังนั้นเมื่อญาติสนิทคนถัดมากล่าวแก่โบอาสว่า “ท่านจงซื้อเสียเองเถิด” เขาก็ถอดรองเท้าออก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 9, 'แล้วโบอาสจึงกล่าวแก่พวกผู้ใหญ่และประชาชนทั้งปวงว่า “ท่านทั้งหลายเป็นพยานในวันนี้ว่า ข้าพเจ้าได้ซื้อทรัพย์สินทั้งหมดของเอลีเมเลค และทรัพย์สินทั้งหมดของคิลิโอนและมาห์โลนจากมือนาโอมีแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 10, 'ยิ่งกว่านั้นรูธชาวโมอับภรรยาของมาห์โลนข้าพเจ้าก็ได้ไถ่ไว้ให้เป็นภรรยาของข้าพเจ้า เพื่อจะจรรโลงนามของผู้ตายไว้กับมรดกของเขา เพื่อนามของผู้ตายจะไม่ต้องถูกตัดออกจากพวกพี่น้องของเขา และจากประตูบ้านเกิดเมืองนอนของเขา ท่านทั้งหลายเป็นพยานแล้วในวันนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 11, 'ประชาชนทั้งปวงที่อยู่ที่ประตูเมืองและพวกผู้ใหญ่กล่าวว่า “เราทั้งหลายเป็นพยานแล้ว ขอพระเยโฮวาห์ทรงกระทําให้หญิงนั้นที่กําลังจะเข้ามาในเรือนของท่านเหมือนนางราเชลและนางเลอาห์ ผู้ซึ่งช่วยกันสร้างวงศ์วานอิสราเอล ขอให้ท่านจงจําเริญอยู่ในเอฟราธาห์และมีชื่อเสียงในเบธเลเฮม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 12, 'ขอให้วงศ์วานของท่านเหมือนวงศ์วานของเปเรศซึ่งทามาร์คลอดให้แก่ยูดาห์ เนื่องด้วยเชื้อสายซึ่งพระเยโฮวาห์จะประทานแก่ท่านโดยผู้หญิงคนนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 13, 'ดังนั้นโบอาสก็รับรูธมาเป็นภรรยาของท่าน และท่านก็เข้าหานางและพระเยโฮวาห์ประทานให้นางตั้งครรภ์คลอดบุตรชายคนหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 14, 'ฝ่ายพวกผู้หญิงก็พูดกับนาโอมีว่า “สาธุการแด่พระเยโฮวาห์ พระองค์มิได้ทรงละทิ้งเจ้าไว้ให้ปราศจากญาติที่ถัดมา ขอให้ทารกนี้มีชื่อเสียงเลื่องลือไปในอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 15, 'ให้เด็กคนนี้เป็นผู้ชุบชีวิตของเจ้าและเลี้ยงดูเจ้าเมื่อชรา เพราะว่าเด็กคนนี้เกิดมาจากลูกสะใภ้ที่รักเจ้า ผู้ประเสริฐกว่าบุตรชายเจ็ดคน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 16, 'แล้วนาโอมีก็รับเด็กนั้นมาอุ้มไว้แนบอก และรับเป็นผู้เลี้ยงดูแลเด็กคนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 17, 'หญิงชาวบ้านข้างเคียงก็ให้ชื่อเด็กนั้น พูดกันว่า “มีบุตรชายคนหนึ่งเกิดให้แก่นาโอมี” เขาตั้งชื่อเด็กคนนั้นว่า โอเบด ผู้เป็นบิดาของเจสซี ซึ่งเป็นบิดาของดาวิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 18, 'ต่อไปนี้เป็นพงศ์พันธุ์ของเปเรศ เปเรศให้กําเนิดบุตรชื่อเฮสโรน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 19, 'เฮสโรนให้กําเนิดบุตรชื่อราม รามให้กําเนิดบุตรชื่ออัมมีนาดับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 20, 'อัมมีนาดับให้กําเนิดบุตรชื่อนาโชน นาโชนให้กําเนิดบุตรชื่อสัลโมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 21, 'สัลโมนให้กําเนิดบุตรชื่อโบอาส โบอาสให้กําเนิดบุตรชื่อโอเบด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 22, 'โอเบดให้กําเนิดบุตรชื่อเจสซี และเจสซีให้กําเนิดบุตรชื่อดาวิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 1, 'มีชายคนหนึ่งเป็นชาวรามาธาอิมโซฟิม แห่งแดนเทือกเขาเอฟราอิม ชื่อเอลคานาห์ บุตรชายเยโรฮัม ผู้เป็นบุตรชายเอลีฮู ผู้เป็นบุตรชายโทหุ ผู้เป็นบุตรชายศูฟ คนเอฟราอิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 2, 'ท่านมีภรรยาสองคน คนหนึ่งชื่อฮันนาห์ อีกคนหนึ่งชื่อเปนินนาห์ เปนินนาห์มีบุตร แต่ฮันนาห์ไม่มีบุตร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 3, 'ฝ่ายชายผู้นี้เคยขึ้นไปจากเมืองของตนทุกปี ไปนมัสการและถวายสัตวบูชาแด่พระเยโฮวาห์จอมโยธาที่เมืองชีโลห์ ที่นั่นมีบุตรชายสองคนของเอลีชื่อโฮฟนีและฟีเนหัส ผู้เป็นปุโรหิตแห่งพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 4, 'ในวันที่เอลคานาห์ถวายสัตวบูชา ท่านก็ได้แบ่งส่วนให้แก่เปนินนาห์ภรรยาของท่านและแก่บุตรชายบุตรสาวทุกคนของนาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 5, 'ท่านแบ่งให้ฮันนาห์สองส่วน เพราะท่านรักฮันนาห์มาก แต่พระเยโฮวาห์ทรงปิดครรภ์ของนางเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 6, 'ปรปักษ์ของนางก็ยั่วเย้านางอย่างรุนแรง เพื่อกระทําให้นางระคายเคืองที่พระเยโฮวาห์ทรงปิดครรภ์ของนางเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 7, 'เหตุการณ์ก็เป็นอยู่ดังนี้ปีแล้วปีเล่า เมื่อนางขึ้นไปยังพระนิเวศของพระเยโฮวาห์คราวใด ปรปักษ์ของนางก็เคยยั่วเย้านาง เพราะฉะนั้นนางฮันนาห์จึงร้องไห้ไม่รับประทานอาหาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 8, 'และเอลคานาห์สามีของนางจึงถามนางว่า “ฮันนาห์ เธอร้องไห้ทําไม และเหตุใดเธอจึงไม่รับประทานอาหาร และทําไมจิตใจของเธอจึงโศกเศร้า สําหรับเธอฉันไม่ดีกว่าบุตรชายสิบคนหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 9, 'หลังจากที่ได้รับประทานอาหารและดื่มที่เมืองชีโลห์แล้ว ฮันนาห์ก็ลุกขึ้น ฝ่ายเอลีปุโรหิตนั่งอยู่ที่เก้าอี้ข้างเสาประตูพระวิหารของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 10, 'นางเป็นทุกข์ร้อนใจมากอธิษฐานต่อพระเยโฮวาห์ร้องไห้คร่ําครวญ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 11, 'นางก็ปฏิญาณไว้ว่า “โอ ข้าแต่พระเยโฮวาห์จอมโยธา ถ้าพระองค์จะทอดพระเนตรความทุกข์ใจของหญิงผู้รับใช้ของพระองค์จริงๆ และยังระลึกถึงข้าพระองค์ และยังไม่ลืมหญิงผู้รับใช้ของพระองค์ แต่จะทรงประทานบุตรชายแก่หญิงผู้รับใช้ของพระองค์สักคนหนึ่งแล้ว ข้าพระองค์จะถวายเขาไว้แด่พระเยโฮวาห์ตลอดชีวิตของเขา และมีดโกนจะไม่แตะต้องศีรษะของเขาเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 12, 'อยู่มาเมื่อนางยังอธิษฐานต่อพระพักตร์พระเยโฮวาห์อยู่นั้น เอลีก็สังเกตดูปากของนาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 13, 'ฝ่ายฮันนาห์นั้นนางพูดแต่ในใจ ริมฝีปากของนางมุบมิบเท่านั้น ไม่ได้ยินเสียงของนาง เพราะเหตุนี้เอลีจึงสําคัญว่านางมึนเมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 14, 'เอลีจึงพูดกับนางว่า “เธอจะเมาไปนานสักเท่าใด ทิ้งเหล้าองุ่นเสียเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 15, 'แต่ฮันนาห์ตอบว่า “มิใช่เช่นนั้นเจ้าค่ะ ดิฉันเป็นหญิงที่มีทุกข์หนัก ดิฉันมิได้ดื่มเหล้าองุ่นหรือเมรัย แต่ดิฉันระบายความในใจของดิฉันออกต่อพระพักตร์พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 16, 'ขออย่าถือว่าหญิงผู้รับใช้ของท่านเป็นลูกสาวของเบลีอัล ที่ดิฉันพูดตลอดมานั้นก็พูดด้วยความกระวนกระวายและความทุรนทุรายมาก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 17, 'แล้วเอลีก็ตอบว่า “จงกลับไปเป็นสุขเถิด ขอพระเจ้าแห่งอิสราเอลโปรดประทานตามที่เจ้าได้อธิษฐานทูลขอต่อพระองค์นั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 18, 'และนางก็กล่าวว่า “ขอให้หญิงผู้รับใช้ของท่านได้รับความกรุณาในสายตาของท่านเถิด” แล้วหญิงนั้นก็ไปตามทางของนางและรับประทานอาหาร และสีหน้าของนางก็ไม่เศร้าหมองอีกต่อไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 19, 'เขาทั้งหลายลุกขึ้นแต่เช้าตรู่ นมัสการต่อพระพักตร์พระเยโฮวาห์ แล้วเขาทั้งหลายก็กลับไปบ้านที่รามาห์ และเอลคานาห์ก็ร่วมรู้กับฮันนาห์ภรรยาของตน และพระเยโฮวาห์ทรงระลึกถึงนาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 20, 'และอยู่มาเมื่อถึงกาลกําหนดฮันนาห์ก็ตั้งครรภ์คลอดบุตรชายคนหนึ่ง และนางเรียกชื่อเด็กนั้นว่า ซามูเอล เพราะนางกล่าวว่า “ดิฉันทูลขอมาจากพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 21, 'ฝ่ายเอลคานาห์ และทุกคนในครอบครัวของท่านขึ้นไปถวายสัตวบูชาประจําปีแด่พระเยโฮวาห์ และทําตามคําปฏิญาณของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 22, 'แต่ฮันนาห์มิได้ขึ้นไปด้วยเพราะนางบอกสามีว่า “ฉันจะไม่ไปจนกว่าเด็กคนนี้หย่านมแล้ว ฉันจะพาเขาขึ้นไป เพื่อเขาจะได้ปรากฏตัวต่อพระพักตร์พระเยโฮวาห์ และอยู่ที่นั่นตลอดไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 23, 'เอลคานาห์สามีบอกนางว่า “จงทําตามที่เธอเห็นชอบเถิด รออยู่จนให้เขาหย่านม ขอเพียงให้พระดํารัสของพระเยโฮวาห์สําเร็จเถิด” นางนั้นก็คอยอยู่และให้บุตรชายกินนมของตัวจนนางให้เขาหย่านม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 24, 'และเมื่อนางให้เขาหย่านมแล้ว นางก็พาเขาขึ้นไปพร้อมกับวัวผู้สามตัว แป้งหนึ่งเอฟาห์ และน้ําองุ่นหนึ่งขวดหนัง และนางก็นําเขามาที่พระนิเวศของพระเยโฮวาห์ที่เมืองชีโลห์ และเด็กนั้นก็ยังเล็กอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 25, 'แล้วเขาทั้งหลายก็ฆ่าวัวผู้ตัวนั้นและนําเด็กมาหาเอลี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 26, 'นางก็กล่าวว่า “โอ ท่านเจ้าข้า ท่านมีชีวิตอยู่แน่ฉันใด ท่านเจ้าข้า ดิฉันเป็นผู้หญิงที่ยืนอยู่ที่นี่ต่อหน้าท่าน และอธิษฐานต่อพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 27, 'ดิฉันอธิษฐานขอเด็กคนนี้และพระเยโฮวาห์ประทานตามคําทูลขอของดิฉัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 28, 'เพราะฉะนั้นดิฉันจึงให้ยืมเขาไว้แด่พระเยโฮวาห์ด้วย ตราบใดที่เขามีชีวิตอยู่ ดิฉันจะให้ยืมเขาไว้แด่พระเยโฮวาห์” และเขาก็นมัสการพระเยโฮวาห์ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 1, 'นางฮันนาห์ได้อธิษฐานและกล่าวว่า “จิตใจของข้าพเจ้าชื่นชมในพระเยโฮวาห์ ในพระเยโฮวาห์เขาของข้าพเจ้าถูกเชิดชูขึ้น ปากของข้าพเจ้าก็อ้ากว้างเข้าใส่ศัตรูของข้าพเจ้า เพราะข้าพเจ้าเปรมปรีดิ์ในความรอดของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 2, 'ไม่มีผู้ใดบริสุทธิ์ดังพระเยโฮวาห์ ไม่มีผู้ใดนอกเหนือพระองค์ ไม่มีศิลาใดเหมือนพระเจ้าของข้าพเจ้าทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 3, 'อย่าพูดโอหังอีกต่อไปเลย อย่าให้ความจองหองออกมาจากปากของเจ้าเลย เพราะพระเยโฮวาห์ทรงเป็นพระเจ้าของความรู้ การกระทําทั้งหลายพระองค์ทรงเป็นผู้ชั่งตรวจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 4, 'คันธนูของผู้มีกําลังก็หัก แต่ผู้ที่ซวนเซก็ได้กําลังมาคาดเอว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 5, 'บรรดาคนที่เคยกินอิ่มก็ต้องออกรับจ้างหากิน แต่คนที่เคยหิวก็หยุดหิว คนที่เป็นหมันกําเนิดบุตรเจ็ดคน แต่นางที่มีบุตรมากก็เหี่ยวแห้งไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 6, 'พระเยโฮวาห์ทรงประหารและทรงให้มีชีวิต พระองค์ทรงนําลงไปถึงแดนคนตายและก็นําขึ้นมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 7, 'พระเยโฮวาห์ทรงกระทําให้ยากจนและทรงกระทําให้มั่งคั่ง พระองค์ทรงกระทําให้ต่ําลงและพระองค์ทรงยกขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 8, 'พระองค์ทรงยกคนยากจนขึ้นจากผงคลี พระองค์ทรงยกคนขอทานขึ้นจากกองขยะ กระทําให้เขานั่งร่วมกับเจ้านาย และได้ที่นั่งอันมีเกียรติเป็นมรดก เพราะว่าเสาแห่งพิภพเป็นของพระเยโฮวาห์ พระองค์ทรงวางพิภพไว้บนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 9, 'พระองค์จะทรงดูแลย่างเท้าของวิสุทธิชนของพระองค์ แต่คนชั่วจะต้องนิ่งอยู่ในความมืด เพราะว่ามนุษย์จะชนะด้วยกําลังของตนก็หาไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 10, 'ศัตรูของพระเยโฮวาห์จะแตกเป็นชิ้นๆ พระองค์จะทรงเอาฟ้าร้องในสวรรค์ต่อสู้เขา พระเยโฮวาห์จะทรงพิพากษาที่สุดปลายพิภพ พระองค์จะทรงประทานกําลังแก่กษัตริย์ของพระองค์ และจะทรงยกย่องเขาของผู้ที่พระองค์ทรงเจิมไว้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 11, 'แล้วเอลคานาห์ก็กลับไปบ้านที่รามาห์ และเด็กนั้นก็ปรนนิบัติพระเยโฮวาห์ต่อหน้าเอลีปุโรหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 12, 'ฝ่ายบุตรชายทั้งสองของเอลีเป็นลูกของเบลีอัล เขามิได้รู้จักพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 13, 'ธรรมเนียมของปุโรหิตที่มีต่อประชาชนเป็นอย่างนี้ เมื่อมีประชาชนคนใดถวายเครื่องสัตวบูชา คนใช้ของปุโรหิตจะเข้ามา มือถือขอเกี่ยวเนื้อสามง่าม ขณะเมื่อเนื้อกําลังต้มอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 14, 'เขาจะเอาขอเกี่ยวเนื้อแทงเข้าไปในกระทะ หรือหม้อหู หรือหม้อขนาดใหญ่ หรือหม้อธรรมดา ขอเกี่ยวเนื้อติดอะไรขึ้นมา ปุโรหิตก็เอาสิ่งนั้นไปเป็นของตน ที่เมืองชีโลห์เขาก็กระทําเช่นนั้นแก่คนอิสราเอลทุกคนที่มาที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 15, 'ยิ่งกว่านั้นอีก ก่อนที่เขาเผาไขมัน คนใช้ของปุโรหิตเคยเข้ามากล่าวแก่ชายผู้กระทําบูชานั้นว่า “ขอเนื้อไปให้ปุโรหิตทอด ท่านไม่รับเนื้อต้มจากเจ้า ท่านต้องการเนื้อดิบ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 16, 'และถ้าชายคนนั้นกล่าวแก่เขาว่า “ขอให้เขาเผาไขมันเสียก่อน แล้วจงเอาไปตามชอบใจเถิด” เขาจะตอบว่า “ไม่ได้ เจ้าต้องให้เดี๋ยวนี้ ถ้าไม่ให้ข้าก็จะเอาไปโดยใช้กําลัง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 17, 'ดังนี้แหละบาปของคนหนุ่มทั้งสองนั้นจึงใหญ่หลวงนักต่อพระพักตร์พระเยโฮวาห์ เพราะว่าคนเหล่านั้นได้ดูหมิ่นของถวายแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 18, 'แต่ซามูเอลปรนนิบัติอยู่ต่อพระพักตร์พระเยโฮวาห์ เป็นเด็ก คนที่คาดเอวด้วยเอโฟดผ้าป่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 19, 'ฝ่ายมารดาเคยเย็บเสื้อเล็กๆนํามาให้เขาทุกปี เมื่อนางขึ้นไปพร้อมกับสามีเพื่อถวายเครื่องบูชาประจําปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 20, 'แล้วเอลีเคยอวยพรเอลคานาห์และภรรยาของเขา กล่าวว่า “ขอพระเยโฮวาห์ประทานเชื้อสายแก่ท่านโดยหญิงคนนี้ แทนคนที่นางให้ยืมไว้แด่พระเยโฮวาห์” แล้วเขาทั้งหลายก็กลับบ้านของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 21, 'และพระเยโฮวาห์ทรงเยี่ยมเยียนฮันนาห์ และนางก็ได้ตั้งครรภ์คลอดบุตรเป็นชายสามหญิงสอง และกุมารซามูเอลก็เติบโตขึ้นเฉพาะพระพักตร์พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 22, 'ฝ่ายเอลีชรามากแล้ว และท่านได้ยินถึงเรื่องราวทั้งสิ้นที่บุตรชายทั้งสองของท่านกระทําแก่คนอิสราเอล เช่นว่าเขาเข้าหาหญิงที่ปรนนิบัติอยู่ที่ทางเข้าพลับพลาแห่งชุมนุมด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 23, 'และท่านก็ว่ากล่าวเขาทั้งสองว่า “ทําไมเจ้าจึงกระทําเช่นนั้น เพราะเราได้ยินจากประชาชนทั้งปวงถึงความชั่วซึ่งเจ้ากระทํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 24, 'ลูกเราเอ๋ย อย่าทําเลย เพราะเรื่องที่เราได้ยินไม่ดีเลย ลูกทําให้ประชาชนของพระเยโฮวาห์ทําการละเมิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 25, 'ถ้ามนุษย์คนใดกระทําผิดต่อมนุษย์ด้วยกัน ผู้วินิจฉัยจะวินิจฉัยให้เขา แต่ถ้ามนุษย์กระทําบาปต่อพระเยโฮวาห์ ใครจะทูลขอเพื่อเขาได้เล่า” แต่เขาทั้งสองหาได้ฟังเสียงบิดาของเขาไม่ เพราะว่าเป็นน้ําพระทัยของพระเยโฮวาห์ที่จะทรงประหารเขาเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 26, 'ฝ่ายกุมารซามูเอลก็เติบโตขึ้นและเป็นที่ชอบมากขึ้นเฉพาะพระเยโฮวาห์และต่อหน้าคนทั้งปวงด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 27, 'ครั้งนั้นมีบุรุษของพระเจ้ามาหาเอลี กล่าวแก่ท่านว่า “พระเยโฮวาห์ตรัสดังนี้ว่า ‘เราได้เผยเราเองให้แจ้งแก่เรือนบรรพบุรุษเจ้า เมื่อเขาทั้งหลายอยู่ในอียิปต์ใต้บังคับวงศ์วานของฟาโรห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 28, 'และเราได้เลือกเขาออกจากตระกูลอิสราเอลทั้งหมดให้เป็นปุโรหิตของเรา เพื่อจะขึ้นไปถวายที่แท่นบูชาของเรา เพื่อเผาเครื่องหอม เพื่อสวมเอโฟดต่อหน้าเรา และเราได้มอบบรรดาของที่บูชาด้วยไฟซึ่งคนอิสราเอลนํามาถวายนั้นแก่เรือนบรรพบุรุษของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 29, 'เหตุใดเจ้าจึงเหยียบย่ําเครื่องสัตวบูชาของเรา และของที่เขาถวายตามบัญชาของเราในที่อาศัยของเรา และให้เกียรติแก่บุตรชายทั้งสองของเจ้าเหนือเรา และกระทําให้ตัวของเจ้าทั้งหลายอ้วนพี ด้วยส่วนที่ดีที่สุดจากของถวายทุกรายจากอิสราเอลชนชาติของเรา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 30, 'เพราะฉะนั้นพระเยโฮวาห์พระเจ้าของอิสราเอลจึงตรัสว่า ‘เราพูดโดยความจริงว่าวงศ์วานของเจ้าและวงศ์วานบิดาของเจ้าจะดําเนินต่อหน้าเราอยู่เป็นนิตย์’ แต่บัดนี้พระเยโฮวาห์ทรงประกาศว่า ‘ขอให้การนั้นห่างไกลจากเรา เพราะว่าผู้ที่ให้เกียรติแก่เรา เราจะให้เกียรติ และบรรดาผู้ที่ดูหมิ่นเรา ผู้นั้นจะถูกดูหมิ่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 31, 'ดูเถิด วาระนั้นจะมาถึงอยู่แล้วที่เราจะตัดแขนของเจ้าออก และตัดแขนของวงศ์วานบิดาของเจ้าออก เพื่อจะไม่มีคนชราสักคนเดียวในวงศ์วานของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 32, 'แล้วเจ้าจะเห็นศัตรูในที่อาศัยของเรา คือในความมั่งคั่งทั้งสิ้นที่พระเจ้าจะทรงประทานแก่อิสราเอล และจะไม่มีคนชราในวงศ์วานของเจ้าเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 33, 'คนของเจ้าซึ่งเรามิได้ตัดขาดเสียจากแท่นบูชาของเรานั้น จะมีชีวิตอยู่เพื่อทําร้ายดวงตาของเจ้า และทําให้ใจของเจ้าเศร้าโศก และบรรดาผลอันเพิ่มพูนในวงศ์วานของเจ้าจะตายในวัยอันเบ่งบานของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 34, 'และสิ่งนี้จะเป็นหมายสําคัญแก่เจ้า ซึ่งจะบังเกิดแก่บุตรชายทั้งสองของเจ้า คือโฮฟนีและฟีเนหัส ทั้งสองจะสิ้นชีวิตในวันเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 35, 'และเราจะให้ปุโรหิตผู้สัตย์ซื่อของเราเกิดขึ้นมา ซึ่งจะกระทําตามสิ่งที่มีอยู่ในจิตในใจของเรา และเราจะสร้างวงศ์วานมั่นคงให้เขา และเขาจะดําเนินอยู่ต่อหน้าผู้ที่เราเจิมไว้เป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 36, 'และต่อมาทุกคนที่ยังเหลืออยู่ในวงศ์วานของเจ้าจะมากราบไหว้เขาขอเงินเหรียญหนึ่งและขนมปังก้อนหนึ่ง และจะกล่าวว่า “ขอท่านกรุณาตั้งข้าพเจ้าไว้ในตําแหน่งปุโรหิตสักทีหนึ่งเถิด เพื่อข้าพเจ้าจะได้รับประทานอาหารสักหน่อยหนึ่ง”’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 1, 'ฝ่ายกุมารซามูเอลปรนนิบัติพระเยโฮวาห์อยู่ต่อหน้าเอลี ในสมัยนั้นพระดํารัสของพระเยโฮวาห์มีมาแต่น้อย ไม่มีนิมิตบ่อยนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 2, 'อยู่มาครั้งนั้นเอลีนอนอยู่ในที่นอนของตน ตาของท่านเริ่มมืดมัว มองอะไรไม่เห็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 3, 'ตะเกียงของพระเจ้ายังไม่ดับ ซามูเอลนอนอยู่ในพระวิหารของพระเยโฮวาห์ ที่ที่หีบของพระเจ้าอยู่ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 4, 'พระเยโฮวาห์ทรงเรียกซามูเอลและซามูเอลทูลตอบว่า “ข้าพเจ้าอยู่นี่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 5, 'เขาจึงวิ่งไปหาเอลีและว่า “ข้าพเจ้าอยู่นี่ ด้วยท่านร้องเรียกข้าพเจ้า” แต่เอลีตอบว่า “เราไม่ได้เรียกเจ้า จงกลับไปนอนอีก” เขาก็ไปนอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 6, 'และพระเยโฮวาห์ทรงเรียกขึ้นอีกว่า “ซามูเอลเอ๋ย” และซามูเอลก็ลุกขึ้นไปหาเอลีกล่าวว่า “ข้าพเจ้าอยู่นี่ ด้วยท่านร้องเรียกข้าพเจ้า” แต่เอลีตอบว่า “ลูกเอ๋ย เรามิได้เรียกเจ้า จงนอนอีก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 7, 'ฝ่ายซามูเอลไม่เคยรู้จักพระเยโฮวาห์ และยังไม่เคยทรงสําแดงพระดํารัสของพระเยโฮวาห์แก่เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 8, 'และพระเยโฮวาห์ทรงเรียกซามูเอลอีกเป็นครั้งที่สาม ซามูเอลก็ลุกขึ้นไปหาเอลีกล่าวว่า “ข้าพเจ้าอยู่นี่ ด้วยท่านร้องเรียกข้าพเจ้า” แล้วเอลีจึงหยั่งรู้ว่าพระเยโฮวาห์ทรงเรียกเด็กนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 9, 'เพราะฉะนั้นเอลีจึงพูดกับซามูเอลว่า “จงไปนอนเสียเถิด ถ้าพระองค์ทรงเรียกเจ้า เจ้าจงทูลว่า ‘พระเยโฮวาห์เจ้าข้า ขอพระองค์ตรัสเถิด เพราะผู้รับใช้ของพระองค์คอยฟังอยู่’” ซามูเอลจึงกลับไปนอนในที่ของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 10, 'และพระเยโฮวาห์เสด็จมาประทับยืนอยู่ ทรงเรียกอย่างครั้งก่อนๆว่า “ซามูเอล ซามูเอลเอ๋ย” และซามูเอลทูลตอบว่า “ขอตรัสเถิด เพราะผู้รับใช้ของพระองค์คอยฟังอยู่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 11, 'แล้วพระเยโฮวาห์ตรัสกับซามูเอลว่า “ดูเถิด เราจะทําสิ่งหนึ่งในอิสราเอล หูของทุกคนผู้ที่ได้ยินจะซ่าทั้งสองข้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 12, 'ในวันนั้นเราจะกระทําให้สิ่งสารพัดที่เรากล่าวไว้เกี่ยวด้วยเรื่องวงศ์วานของเอลีให้สําเร็จเสียต่อเอลี ตั้งแต่ต้นจนถึงที่สุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 13, 'ดังนั้นเราจึงบอกเขาว่า เราจะลงโทษวงศ์วานของเขาเป็นนิตย์ เพราะความชั่วช้าซึ่งเขารู้แล้ว เพราะบุตรชายทั้งสองของเขาประพฤติเลวร้าย และเขาก็มิได้ห้ามปราม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 14, 'เพราะฉะนั้นเราจึงปฏิญาณต่อวงศ์วานของเอลีว่า ความชั่วช้าของวงศ์วานเอลีนั้นจะลบล้างเสียด้วยเครื่องสัตวบูชา และของถวายไม่ได้เป็นนิตย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 15, 'ซามูเอลนอนอยู่จนรุ่งเช้า เขาเปิดประตูพระนิเวศของพระเยโฮวาห์ และซามูเอลก็กลัวไม่กล้าบอกนิมิตนั้นแก่เอลี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 16, 'เอลีก็เรียกซามูเอลมากล่าวว่า “ซามูเอล บุตรของข้าเอ๋ย” และซามูเอลตอบว่า “ข้าพเจ้าอยู่นี่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 17, 'และเอลีถามว่า “เรื่องอะไรนะที่พระเยโฮวาห์ทรงบอกเจ้า ขออย่าปิดบังไว้จากเราเลย ถ้าเจ้าปิดบังสิ่งใดไว้จากเราในเรื่องทั้งสิ้นที่พระองค์ทรงบอกแก่เจ้าก็ขอพระเจ้าทรงลงโทษเจ้าและให้หนักยิ่งกว่า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 18, 'ดังนั้นซามูเอลจึงบอกทุกอย่างแก่เอลี ไม่ได้ปิดบังอะไรไว้จากท่านเลย และเอลีว่า “คือพระเยโฮวาห์เอง ขอพระองค์ทรงกระทําตามสิ่งที่พระองค์ทรงเห็นชอบเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 19, 'และซามูเอลก็เติบโตขึ้น และพระเยโฮวาห์ทรงสถิตกับท่าน มิให้วาจาของท่านตกไปเปล่าแต่สักคําเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 20, 'และชนอิสราเอลทั้งปวง ตั้งแต่ดานถึงเบเออร์เชบาก็ทราบว่า ซามูเอลได้รับการแต่งตั้งให้เป็นผู้พยากรณ์ของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 21, 'และพระเยโฮวาห์ทรงปรากฏอีกที่ชีโลห์ เพราะพระเยโฮวาห์ทรงสําแดงพระองค์แก่ซามูเอลที่ชีโลห์ โดยพระดํารัสของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 1, 'และถ้อยคําของซามูเอลมาถึงคนอิสราเอลทั้งปวง ฝ่ายคนอิสราเอลได้ยกกองทัพออกไปสู้รบกับคนฟีลิสเตีย ได้ตั้งค่ายอยู่ข้างเอเบนเอเซอร์ และคนฟีลิสเตียตั้งค่ายอยู่ในอาเฟก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 2, 'คนฟีลิสเตียได้จัดพลเป็นแนวเข้าต่อสู้กับอิสราเอล และเมื่อสงครามได้ขยายวงออกไป อิสราเอลก็พ่ายแพ้ต่อหน้าคนฟีลิสเตีย ผู้ได้ฆ่าคนเสียประมาณสี่พันคนในสนามรบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 3, 'และเมื่อกองทัพกลับมาสู่ค่าย พวกผู้ใหญ่ของอิสราเอลก็กล่าวว่า “ทําไมพระเยโฮวาห์จึงทรงให้เราพ่ายแพ้ต่อหน้าคนฟีลิสเตียในวันนี้ ขอเราไปนําหีบพันธสัญญาแห่งพระเยโฮวาห์มาให้เราจากเมืองชีโลห์เถิด เพื่อว่าหีบนั้นจะมาท่ามกลางเราและจะช่วยเราให้พ้นจากมือศัตรูของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 4, 'เขาจึงใช้คนไปที่เมืองชีโลห์ เพื่อนําหีบพันธสัญญาแห่งพระเยโฮวาห์จอมโยธา ผู้ประทับระหว่างพวกเครูบ มาจากชีโลห์ บุตรชายทั้งสองของเอลี คือโฮฟนีและฟีเนหัส ก็อยู่กับหีบพันธสัญญาแห่งพระเจ้าที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 5, 'เมื่อหีบพันธสัญญาแห่งพระเยโฮวาห์เข้ามาในค่ายแล้ว คนอิสราเอลทั้งสิ้นก็โห่ร้องเสียงดังจนแผ่นดินก้องไปด้วยเสียงนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 6, 'และเมื่อคนฟีลิสเตียได้ยินเสียงโห่ร้องดังเช่นนั้น เขาก็กล่าวว่า “เสียงโห่ร้องอึกทึกครึกโครมในค่ายของคนฮีบรูนั้นหมายความว่าอะไรกัน” และเขาทราบว่าหีบแห่งพระเยโฮวาห์เข้ามาในค่ายแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 7, 'คนฟีลิสเตียก็กลัวเพราะเขากล่าวว่า “พระเจ้าได้เสด็จมาในค่ายแล้ว” และเขากล่าวว่า “วิบัติแก่เราทั้งหลาย เพราะแต่ก่อนไม่เคยเกิดเรื่องอย่างนี้เลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 8, 'วิบัติแก่เราทั้งหลาย ใครจะช่วยเราให้พ้นจากพระหัตถ์ของบรรดาพระอันทรงฤทธานุภาพนี้ได้ พระเหล่านี้เป็นผู้ที่ฆ่าฟันชาวอียิปต์ด้วยภัยพิบัตินานาชนิดในถิ่นทุรกันดาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 9, 'โอ คนฟีลิสเตียเอ๋ย จงกล้าหาญเถิด จงกระทําตัวเป็นลูกผู้ชาย เพื่อว่าเจ้าจะไม่เป็นทาสของคนฮีบรู ดังที่เขาเคยเป็นทาสเจ้า จงกระทําตัวให้เป็นลูกผู้ชายและเข้ารบ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 10, 'เพราะฉะนั้นคนฟีลิสเตียจึงสู้รบและอิสราเอลก็พ่ายแพ้ ต่างก็หนีไปยังเต็นท์ของตน ครั้งนั้นมีการฆ่าฟันกันมาก เพราะทหารราบของอิสราเอลตายเสียสามหมื่นคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 11, 'และหีบแห่งพระเจ้าก็ถูกยึดไป และบุตรชายทั้งสองของเอลี คือโฮฟนีและฟีเนหัสก็ถูกฆ่าตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 12, 'ผู้ชายคนเบนยามินคนหนึ่งวิ่งไปจากแนวรบมาถึงชีโลห์ในวันเดียวกัน เสื้อผ้าขาดและดินก็อยู่บนศีรษะของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 13, 'เมื่อเขามาถึงนั้น ดูเถิด เอลีอยู่บนที่นั่งข้างถนนคอยเฝ้าอยู่ เพราะจิตใจของท่านหวั่นด้วยเรื่องหีบแห่งพระเจ้า และเมื่อชายคนนั้นเข้ามาในเมืองและบอกข่าว ชาวเมืองทั้งสิ้นก็ร้องขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 14, 'เมื่อเอลีได้ยินเสียงร้องเช่นนั้นก็ถามว่า “นั่นเสียงอะไรกันโกลาหล” แล้วชายคนนั้นก็รีบเข้ามาบอกเอลี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 15, 'ฝ่ายเอลีมีอายุเก้าสิบแปดปี ตาของท่านมืดมัว มองอะไรไม่เห็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 16, 'ชายคนนั้นบอกเอลีว่า “ข้าพเจ้าเป็นคนที่มาจากแนวรบ ข้าพเจ้าหนีมาจากแนวรบวันนี้” เอลีก็ถามว่า “ลูกเอ๋ย เป็นอย่างไรบ้าง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 17, 'ผู้ที่ส่งข่าวนั้นก็ตอบว่า “อิสราเอลได้หนีไปต่อหน้าต่อตาคนฟีลิสเตียไปแล้ว มีการฆ่าฟันกันมากท่ามกลางประชาชน บุตรชายทั้งสองของท่าน คือโฮฟนีและฟีเนหัสก็ตาย และหีบแห่งพระเจ้าถูกยึดไปเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 18, 'ต่อมาเมื่อเขากล่าวถึงหีบแห่งพระเจ้า เอลีก็หงายหลังจากที่นั่งที่อยู่ข้างประตู คอของท่านก็หัก และท่านสิ้นชีวิตแล้ว เพราะท่านชรามากและตัวก็หนัก ท่านได้วินิจฉัยคนอิสราเอลอยู่สี่สิบปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 19, 'ฝ่ายบุตรสะใภ้ของท่าน คือภรรยาของฟีเนหัสมีครรภ์กําลังจะคลอดบุตร และเมื่อนางได้ยินข่าวว่า เขายึดหีบแห่งพระเจ้าไป และพ่อสามีและสามีของนางก็สิ้นชีวิต นางก็โน้มตัวลงและคลอดบุตร เพราะความเจ็บปวดบังเกิดขึ้นแก่นาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 20, 'เมื่อนางกําลังจะตายนั้น พวกผู้หญิงที่เฝ้านางอยู่ได้บอกนางว่า “อย่ากลัวเลย เพราะเจ้าคลอดลูกผู้ชายคนหนึ่ง” แต่นางไม่ตอบไม่ฟัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 21, 'นางให้ชื่อเด็กนั้นว่า อีคาโบด กล่าวว่า “สง่าราศีพรากไปจากอิสราเอลแล้ว” เพราะเขายึดหีบแห่งพระเจ้าไป และเพราะเรื่องพ่อสามีและสามีของนาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 22, 'และนางกล่าวว่า “สง่าราศีได้พรากจากอิสราเอลแล้ว เพราะเขายึดหีบแห่งพระเจ้าไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 1, 'คนฟีลิสเตียยึดหีบแห่งพระเจ้าและนําไปจากเอเบนเอเซอร์ถึงเมืองอัชโดด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 2, 'เมื่อคนฟีลิสเตียยึดหีบแห่งพระเจ้าไปนั้น เขานําเข้าไปไว้ในนิเวศของพระดาโกน และวางไว้ข้างพระดาโกน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 3, 'และเมื่อประชาชนชาวอัชโดดตื่นเช้าในวันรุ่งขึ้น ดูเถิด พระดาโกนได้ล้มหน้าคว่ําลงมายังพื้นดินตรงหน้าหีบแห่งพระเยโฮวาห์ เขาทั้งหลายจึงยกพระดาโกนขึ้นตั้งไว้ในที่เดิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 4, 'แต่เมื่อเขาทั้งหลายตื่นเช้าในวันรุ่งขึ้น ดูเถิด พระดาโกนก็ล้มหน้าคว่ําลงมายังพื้นดินตรงหน้าหีบแห่งพระเยโฮวาห์ เศียรของพระดาโกนและฝ่ามือทั้งสองก็ถูกตัดออกอยู่ที่ธรณีประตู เหลืออยู่แต่ลําตัวพระดาโกน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 5, 'เพราะเหตุนี้เองปุโรหิตของพระดาโกนและผู้ที่เข้าไปในนิเวศของพระดาโกน จึงไม่เหยียบธรณีประตูนิเวศพระดาโกนที่เมืองอัชโดดจนถึงทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 6, 'พระหัตถ์ของพระเยโฮวาห์อยู่เหนือประชาชนอัชโดดอย่างหนัก พระองค์ทรงทําลายเขาและทรงเฆี่ยนเขาด้วยริดสีดวงทวารขั้นรุนแรง ทั้งชาวอัชโดดและเขตแดนของชาวเมืองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 7, 'และเมื่อชาวเมืองอัชโดดเห็นอย่างนั้น เขาทั้งหลายกล่าวว่า “อย่าให้หีบแห่งพระเจ้าของอิสราเอลอยู่กับเราเลย เพราะว่าพระหัตถ์ของพระองค์อยู่เหนือเรา และเหนือพระดาโกนพระของเราอย่างหนัก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 8, 'เขาจึงใช้คนไปเรียกประชุมเจ้านายทั้งสิ้นของฟีลิสเตีย และกล่าวว่า “เราจะกระทําอะไรกับหีบแห่งพระเจ้าของอิสราเอลดี” เขาทั้งหลายตอบว่า “ให้เรานําหีบแห่งพระเจ้าของอิสราเอลอ้อมไปยังเมืองกัท” เพราะฉะนั้นเขาจึงนําหีบแห่งพระเจ้าของอิสราเอลไปที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 9, 'แต่เมื่อเขาทั้งหลายนําหีบอ้อมไปเมืองนั้นแล้ว พระหัตถ์ของพระเยโฮวาห์ก็ต่อสู้เมืองนั้นกระทําให้เกิดการทําลายอย่างหนัก และทรงเฆี่ยนชาวเมืองนั้นทั้งเด็กและผู้ใหญ่ คือให้เกิดริดสีดวงทวารขั้นรุนแรงขึ้นที่ส่วนลับของเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 10, 'เขาจึงส่งหีบแห่งพระเจ้าไปยังเมืองเอโครน และอยู่มาเมื่อหีบแห่งพระเจ้ามาถึงเมืองเอโครน ชาวเมืองเอโครนร้องว่า “เขาได้นําหีบแห่งพระเจ้าของอิสราเอลมาให้เรา เพื่อจะฆ่าเราและประชาชนของเราเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 11, 'เพราะฉะนั้นเขาจึงส่งคนไปให้เรียกประชุมเจ้านายทั้งหมดของคนฟีลิสเตีย และกล่าวว่า “จงส่งหีบแห่งพระเจ้าของอิสราเอลไปเสียให้หีบนั้นกลับไปยังที่เดิม เพื่อหีบนั้นจะไม่ได้ฆ่าเราหรือประชาชนของเราเสีย” เพราะว่ามีการทําลายล้างอย่างน่ากลัวแพร่ไปทั่วเมืองนั้น พระหัตถ์ของพระเจ้าก็อยู่ที่นั่นอย่างหนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 12, 'คนที่ไม่ตายก็เป็นริดสีดวงทวารขั้นรุนแรง และเสียงร้องของชาวเมืองนั้นก็ขึ้นไปยังฟ้าสวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 1, 'หีบแห่งพระเยโฮวาห์อยู่ในถิ่นคนฟีลิสเตียเจ็ดเดือน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 2, 'คนฟีลิสเตียก็เชิญพวกปุโรหิตและพวกโหรมา กล่าวว่า “เราจะกระทําอย่างไรกับหีบแห่งพระเยโฮวาห์ดี ขอบอกเราว่าจะส่งหีบไปยังที่เดิมด้วยอะไรดี”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 3, 'เขาทั้งหลายตอบว่า “ถ้าท่านทั้งหลายจะส่งหีบแห่งพระเจ้าของอิสราเอลไป ก็อย่าส่งไปเปล่า ถึงอย่างไรก็ขอส่งเครื่องบูชาไถ่การละเมิดไปด้วย แล้วท่านทั้งหลายจะหายโรค และท่านทั้งหลายจะทราบด้วยว่า เหตุใดพระหัตถ์นี้จึงไม่หันไปเสียจากท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 4, 'และเขากล่าวว่า “จัดอะไรเป็นเครื่องบูชาไถ่การละเมิดเล่า ที่เราจะต้องถวายให้พระองค์” เขาทั้งหลายตอบว่า “ลูกริดสีดวงทวารทองคําขั้นรุนแรงห้าลูกกับหนูทองคําห้าตัว ตามจํานวนเจ้านายแห่งคนฟีลิสเตีย เพราะว่าโรคอย่างเดียวกันนั้นติดต่อท่านทั้งหลายและเจ้านายด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 5, 'เพราะฉะนั้นท่านต้องทํารูปริดสีดวงทวารขั้นรุนแรงของท่านและรูปหนูของท่านซึ่งทําลายแผ่นดิน และท่านทั้งหลายจงถวายสง่าราศีแด่พระเจ้าของอิสราเอล ชะรอยพระองค์จะทรงเบาพระหัตถ์ของพระองค์จากท่านทั้งหลาย ทั้งจากพระของท่านและแผ่นดินของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 6, 'ทําไมท่านจึงกระทําให้จิตใจของท่านแข็งกระด้างไปอย่างที่ชาวอียิปต์และฟาโรห์ได้กระทําจิตใจของเขาให้แข็งกระด้างนั้น เมื่อพระองค์ทรงกระทําเหตุการณ์สู้เขาทั้งหลายแล้ว เขาทั้งหลายก็ต้องปล่อยให้ประชาชนไปมิใช่หรือ แล้วเขาทั้งหลายก็จากไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 7, 'ฉะนั้นบัดนี้จงเตรียมเกวียนใหม่เล่มหนึ่งมาเทียมเข้ากับแม่วัวคู่หนึ่งซึ่งยังไม่เคยเข้าเทียมแอกเลย จงเอาแม่วัวมาเทียมเกวียนแล้วพรากลูกๆของมันกลับไปบ้านเสียให้พ้นจากมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 8, 'จงนําหีบแห่งพระเยโฮวาห์มาวางไว้บนเกวียน และวางเครื่องทองคําซึ่งท่านทั้งหลายถวายให้พระองค์เป็นเครื่องบูชาไถ่การละเมิดไว้ในหีบที่อยู่ข้างๆ แล้วก็ปล่อยให้มันไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 9, 'และคอยดู ถ้าไปตามทางถึงแผ่นดินของมันเอง คือทางไปเมืองเบธเชเมช พระองค์ก็เป็นผู้ทรงให้เกิดความชั่วร้ายอย่างใหญ่หลวงนี้แก่เรา แต่ถ้าไม่เช่นนั้น เราจะได้ทราบว่าไม่ใช่พระหัตถ์ของพระองค์ที่กระทําต่อเรา เป็นโอกาสที่บังเอิญเกิดขึ้นแก่เราเอง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 10, 'คนเหล่านั้นก็กระทําตาม นําเอาแม่วัวคู่หนึ่งเทียมเข้ากับเกวียน แล้วขังลูกๆของมันไว้ที่บ้าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 11, 'และเขาก็วางหีบแห่งพระเยโฮวาห์ไว้บนเกวียนพร้อมกับหีบหนูทองคําและรูปริดสีดวงทวารขั้นรุนแรงของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 12, 'แม่วัวก็เดินตรงไปตามทางที่ไปเมืองเบธเชเมช ไปตามทางหลวง เดินพลางร้องพลางไม่เลี้ยวขวาหรือเลี้ยวซ้าย และบรรดาเจ้านายแห่งคนฟีลิสเตียก็ตามมันไปจนถึงพรมแดนเมืองเบธเชเมช');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 13, 'ฝ่ายชาวเมืองเบธเชเมชกําลังเกี่ยวข้าวสาลีอยู่ที่หุบเขา และเมื่อเขาเงยหน้าขึ้นและเห็นหีบ เขาก็ชื่นชมยินดีที่ได้เห็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 14, 'เกวียนนั้นได้เข้ามาในนาของโยชูวาชาวเบธเชเมชและหยุดอยู่ที่นั่น มีหินใหญ่ก้อนหนึ่งอยู่ที่นั่น เขาจึงผ่าไม้เกวียนเป็นฟืน และเอาแม่วัวเป็นเครื่องเผาบูชาถวายแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 15, 'และคนเลวีก็เชิญหีบแห่งพระเยโฮวาห์ลง และหีบที่อยู่ข้างๆซึ่งมีเครื่องทองคํา วางไว้บนก้อนหินใหญ่นั้น และชาวเบธเชเมชก็ถวายเครื่องเผาบูชาและถวายเครื่องสัตวบูชาแด่พระเยโฮวาห์ในวันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 16, 'และเมื่อเจ้านายทั้งห้าของคนฟีลิสเตียได้เห็นแล้วเขาก็กลับไปยังเมืองเอโครนในวันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 17, 'ต่อไปนี้เป็นรูปริดสีดวงทวารทองคําขั้นรุนแรงซึ่งคนฟีลิสเตียถวายเป็นเครื่องบูชาไถ่การละเมิดถวายแด่พระเยโฮวาห์ รูปหนึ่งสําหรับเมืองอัชโดด เมืองกาซารูปหนึ่ง เมืองอัชเคโลนรูปหนึ่ง เมืองกัทรูปหนึ่ง เมืองเอโครนรูปหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 18, 'รูปหนูทองคําก็เช่นเดียวกัน ตามจํานวนเมืองของฟีลิสเตียที่เป็นเมืองของเจ้านายทั้งห้า ทั้งเมืองที่มีป้อมปราการและชนบทที่ไม่มีกําแพงเมือง จนถึงหินก้อนใหญ่แห่งอาเบล ซึ่งเขาวางหีบของพระเยโฮวาห์ลงไว้นั้น หินนั้นก็ยังอยู่จนทุกวันนี้ ที่ในทุ่งนาของโยชูวาชาวเบธเชเมช');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 19, 'พระองค์จึงทรงประหารชาวเบธเชเมช เพราะว่าเขาทั้งหลายได้มองข้างในหีบแห่งพระเยโฮวาห์ พระองค์ได้ทรงประหารเสียห้าหมื่นเจ็ดสิบคน และประชาชนก็ไว้ทุกข์ เพราะว่าพระเยโฮวาห์ทรงประหารประชาชนเสียเป็นอันมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 20, 'แล้วชาวเบธเชเมชจึงกล่าวว่า “ผู้ใดสามารถยืนอยู่ต่อพระพักตร์พระเยโฮวาห์พระเจ้าบริสุทธิ์องค์นี้ได้ พระองค์จะเสด็จไปจากเราไปหาผู้ใดดี”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 21, 'ดังนั้นเขาจึงส่งผู้สื่อสารไปยังชาวเมืองคีริยาทเยอาริมกล่าวว่า “คนฟีลิสเตียได้คืนหีบแห่งพระเยโฮวาห์มาแล้ว ขอลงมาเชิญหีบขึ้นไปอยู่กับท่านเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 1, 'ชาวคีริยาทเยอาริมได้มาเชิญหีบแห่งพระเยโฮวาห์ขึ้นไปถึงเรือนของอาบีนาดับซึ่งอยู่บนเนินเขา และเขาทั้งหลายก็ชําระเอเลอาซาร์บุตรชายของเขาให้บริสุทธิ์เพื่อให้ดูแลหีบแห่งพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 2, 'อยู่มานับแต่วันที่หีบนั้นอยู่ที่คีริยาทเยอาริมก็เป็นเวลาช้านานตั้งยี่สิบปี และบรรดาวงศ์วานอิสราเอลทั้งสิ้นก็คร่ําครวญถึงพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 3, 'แล้วซามูเอลพูดกับวงศ์วานอิสราเอลทั้งสิ้นว่า “ถ้าท่านทั้งหลายจะกลับมาหาพระเยโฮวาห์ด้วยสิ้นสุดใจของท่าน จงทิ้งพระต่างด้าวและพระอัชทาโรทเสียจากท่ามกลางท่านทั้งหลาย และเตรียมใจของท่านให้ตรงต่อพระเยโฮวาห์ และปรนนิบัติแต่พระองค์เท่านั้น พระองค์จะทรงช่วยท่านให้พ้นจากมือของคนฟีลิสเตีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 4, 'คนอิสราเอลจึงทิ้งพระบาอัลและพระอัชทาโรท และเขาทั้งหลายปรนนิบัติแต่พระเยโฮวาห์เท่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 5, 'แล้วซามูเอลกล่าวว่า “จงประชุมคนอิสราเอลทั้งสิ้นที่เมืองมิสเปห์และข้าพเจ้าจะอธิษฐานต่อพระเยโฮวาห์เพื่อท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 6, 'เขาทั้งหลายจึงประชุมกันที่มิสเปห์ และตักน้ํามาเทออกถวายต่อพระพักตร์พระเยโฮวาห์ และอดอาหารในวันนั้นและกล่าวที่นั่นว่า “เราทั้งหลายได้กระทําบาปต่อพระเยโฮวาห์” และซามูเอลก็วินิจฉัยคนอิสราเอลที่เมืองมิสเปห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 7, 'เมื่อคนฟีลิสเตียได้ยินว่าคนอิสราเอลได้ประชุมกันที่เมืองมิสเปห์ เจ้านายแห่งฟีลิสเตียก็ยกขึ้นไปต่อสู้กับอิสราเอล และเมื่อคนอิสราเอลได้ยินเช่นนั้นเขาก็กลัวคนฟีลิสเตีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 8, 'และคนอิสราเอลร้องต่อซามูเอลว่า “อย่าหยุดร้องทูลพระเยโฮวาห์พระเจ้าของเราเพื่อเราทั้งหลาย เพื่อขอพระองค์ทรงช่วยเราให้พ้นจากมือของคนฟีลิสเตีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 9, 'ซามูเอลก็เอาลูกแกะอ่อนที่ยังกินนมอยู่ตัวหนึ่งมาถวายเป็นเครื่องเผาบูชาทั้งตัวแด่พระเยโฮวาห์ และซามูเอลร้องทูลต่อพระเยโฮวาห์เพื่อคนอิสราเอล และพระเยโฮวาห์ทรงสดับฟังท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 10, 'ขณะที่ซามูเอลถวายเครื่องเผาบูชาอยู่นั้น คนฟีลิสเตียก็เข้ามาใกล้จะสู้รบกับอิสราเอล แต่พระเยโฮวาห์ทรงให้ฟ้าร้องเสียงดังยิ่งนักในวันนั้นสู้กับคนฟีลิสเตีย กระทําให้คนฟีลิสเตียสับสนอลหม่าน จึงพ่ายแพ้แก่อิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 11, 'คนอิสราเอลก็ออกจากมิสเปห์ติดตามคนฟีลิสเตียและฆ่าฟันเขา จนไปถึงเมืองเบธคาร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 12, 'แล้วซามูเอลก็เอาศิลาก้อนหนึ่งตั้งไว้ระหว่างมิสเปห์และเชน เรียกชื่อศิลานั้นว่า เอเบนเอเซอร์ เพราะท่านกล่าวว่า “พระเยโฮวาห์ทรงช่วยพวกเราจนบัดนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 13, 'ดังนั้นคนฟีลิสเตียจึงพ่ายแพ้ไม่เข้ามาในดินแดนอิสราเอลอีก และพระหัตถ์แห่งพระเยโฮวาห์ก็ต่อสู้คนฟีลิสเตียตลอดชีวิตของซามูเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 14, 'หัวเมืองที่คนฟีลิสเตียได้ยึดไปจากอิสราเอลนั้น ก็ได้กลับคืนมายังอิสราเอล ตั้งแต่เมืองเอโครนถึงเมืองกัทและอิสราเอลก็ได้ตีดินแดนของหัวเมืองเหล่านี้คืนมาจากมือของคนฟีลิสเตีย ครั้งนั้นมีสันติภาพระหว่างอิสราเอลและคนอาโมไรต์ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 15, 'ซามูเอลได้วินิจฉัยคนอิสราเอลอยู่ตลอดชีวิตของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 16, 'และท่านก็เที่ยวไปโดยรอบทุกปีเป็นประจํา ไปถึงเมืองเบธเอล กิลกาล และมิสเปห์ และท่านก็วินิจฉัยคนอิสราเอลในบรรดาเมืองเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 17, 'แล้วท่านจะกลับมายังเมืองรามาห์ เพราะว่าบ้านของท่านอยู่ที่นั่น ท่านก็วินิจฉัยคนอิสราเอลที่นั่นด้วย ท่านได้สร้างแท่นบูชาถวายแด่พระเยโฮวาห์ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 1, 'อยู่มาเมื่อซามูเอลแก่แล้ว ท่านได้ตั้งพวกบุตรชายของท่านให้วินิจฉัยอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 2, 'บุตรหัวปีของท่านชื่อโยเอล และคนที่สองชื่ออาบียาห์ ทั้งสองเป็นผู้วินิจฉัยในเมืองเบเออร์เชบา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 3, 'แต่บุตรชายของท่านมิได้ดําเนินในทางของท่าน ได้เลี่ยงไปหากําไร เขารับสินบนและบิดเบือนความยุติธรรมเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 4, 'และบรรดาพวกผู้ใหญ่ของอิสราเอลก็พากันมาหาซามูเอลที่เมืองรามาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 5, 'และเรียนท่านว่า “ดูเถิด ท่านชราแล้ว และบุตรชายของท่านมิได้ดําเนินในทางของท่าน บัดนี้ขอท่านได้กําหนดตั้งกษัตริย์ให้วินิจฉัยพวกเราอย่างประชาชาติทั้งหลายเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 6, 'แต่เมื่อเขาพูดว่า “ขอตั้งกษัตริย์ให้วินิจฉัยเราทั้งหลาย” ก็กระทําให้ซามูเอลไม่พอใจ และซามูเอลได้ทูลอธิษฐานต่อพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 7, 'และพระเยโฮวาห์ทรงตอบซามูเอลว่า “จงฟังเสียงประชาชนในเรื่องทั้งสิ้นที่เขาทั้งหลายขอต่อเจ้า เพราะว่าเขามิได้ละทิ้งเจ้า แต่เขาทั้งหลายได้ละทิ้งเรา ไม่ให้เราครอบครองเหนือเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 8, 'ตามการกระทําทั้งสิ้นซึ่งเขาได้กระทําตั้งแต่วันที่เรานําเขาออกมาจากอียิปต์จนถึงวันนี้ คือเขาได้ละทิ้งเราและปรนนิบัติพระอื่น เขาจึงกระทําเช่นเดียวกันต่อเจ้าด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 9, 'เหตุฉะนั้นบัดนี้จงฟังเสียงของเขา ขอแต่จงคอยทักท้วงเขา และสําแดงให้ทราบถึงวิธีการของกษัตริย์ผู้ที่จะครอบครองเขาทั้งหลาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 10, 'ซามูเอลจึงเอาพระดํารัสทั้งสิ้นของพระเยโฮวาห์มาบอกกล่าวแก่ประชาชนผู้ร้องขอให้ท่านตั้งกษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 11, 'ท่านกล่าวว่า “นี่เป็นวิธีการของกษัตริย์ผู้ที่จะครอบครองเหนือเจ้า กษัตริย์จะเกณฑ์บุตรชายทั้งหลายของเจ้าและกําหนดให้ประจํารถรบ และให้เป็นพลม้า และให้วิ่งหน้ารถรบของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 12, 'แล้วพระองค์จะตั้งเขาให้เป็นนายพัน นายห้าสิบของพระองค์ ให้บางคนไถที่ดินของพระองค์และเกี่ยวข้าว และทําศาสตราวุธ และเครื่องใช้ของรถรบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 13, 'พระองค์จะนําบุตรสาวของเจ้าไปเป็นผู้ปรุงเครื่องหอม ทําครัวและปิ้งขนม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 14, 'พระองค์จะเอานา สวนองุ่นและสวนมะกอกเทศที่ดีที่สุดของเจ้าให้แก่ข้าราชการของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 15, 'พระองค์จะชักหนึ่งในสิบของพืชผลและผลองุ่นของท่านให้แก่มหาดเล็กและข้าราชการของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 16, 'พระองค์จะเอาคนใช้ผู้ชายและคนใช้ผู้หญิง และคนหนุ่มๆที่ดีที่สุดของท่าน และลาของท่านให้ไปทํางานของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 17, 'พระองค์จะชักหนึ่งในสิบของฝูงสัตว์ของท่าน และท่านทั้งหลายจะเป็นทาสของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 18, 'ในวันนั้นท่านจะร้องทุกข์เพราะกษัตริย์ของท่าน ผู้ซึ่งท่านทั้งหลายได้เลือกนั้น แต่พระเยโฮวาห์จะไม่สดับท่านในวันนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 19, 'แต่ประชาชนปฏิเสธไม่เชื่อฟังเสียงของซามูเอล เขาทั้งหลายกล่าวว่า “เราไม่ยอม แต่เราจะต้องมีกษัตริย์ปกครองเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 20, 'เพื่อเราจะเป็นเหมือนประชาชาติทั้งหลายด้วย และเพื่อกษัตริย์ของเราจะวินิจฉัยเรา และนําหน้าเราไปและรบศึกให้เรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 21, 'และเมื่อซามูเอลได้ยินถ้อยคําทั้งสิ้นของประชาชน ท่านก็นําไปทูลพระเยโฮวาห์ให้ทรงทราบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 22, 'และพระเยโฮวาห์ตรัสกับซามูเอลว่า “จงฟังเสียงของเขาทั้งหลายเถิด และจงตั้งกษัตริย์องค์หนึ่งให้เขา” แล้วซามูเอลจึงกล่าวแก่คนอิสราเอลว่า “ให้ทุกคนกลับไปยังเมืองของตน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 1, 'มีชายคนหนึ่งคนเบนยามินชื่อคีช บุตรชายของอาบีเอล ผู้เป็นบุตรชายของเศโรร์ บุตรชายของเบโครัท บุตรชายของอาฟิยาห์ คนเบนยามิน เป็นคนร่ํารวย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 2, 'ท่านมีบุตรชายคนหนึ่งชื่อซาอูล เป็นคนหนุ่มที่ดีที่สุด รูปงาม ไม่มีชายคนใดในหมู่คนอิสราเอลที่จะงามกว่าเขา เขาสูงกว่าประชาชนทั้งหลายตั้งแต่บ่าขึ้นไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 3, 'ฝ่ายฝูงแม่ลาของคีชบิดาของซาอูลหายไป คีชจึงกล่าวแก่ซาอูลบุตรชายของตนว่า “ลุกขึ้นเอาคนใช้คนหนึ่งไปกับเจ้า เพื่อไปหาลา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 4, 'เขาทั้งสองก็ผ่านแดนเทือกเขาแห่งเอฟราอิม ผ่านเข้าแผ่นดินชาลิชา เขาหาลาไม่พบ เขาก็ผ่านข้ามแผ่นดินชาอาลิม แต่ลาไม่อยู่ที่นั่น แล้วเขาผ่านเข้าแผ่นดินของคนเบนยามิน แต่ก็หาลาไม่พบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 5, 'เมื่อเขามาถึงแผ่นดินศูฟ ซาอูลจึงพูดกับคนใช้ผู้ซึ่งอยู่กับท่านว่า “มาเถิด ให้เรากลับไป เกรงว่าบิดาของข้าจะเลิกกังวลเรื่องลา และมาร้อนใจด้วยเรื่องของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 6, 'แต่คนใช้ตอบท่านว่า “ดูเถิด มีคนของพระเจ้าคนหนึ่งในเมืองนี้ เป็นคนที่เขานับถือกันมาก สิ่งที่ท่านกล่าวนั้นเป็นไปตามที่กล่าวนั้นทุกอย่าง ขอให้เราไปที่นั่น ชะรอยท่านจะบอกเราถึงทางซึ่งเราควรดําเนิน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 7, 'แล้วซาอูลพูดกับคนใช้ของท่านว่า “แต่ดูเถิด ถ้าเราไปเราจะเอาอะไรไปให้ชายผู้นั้น เพราะขนมปังในย่ามของเราก็หมดแล้ว เราไม่มีของขวัญที่จะนําไปให้แก่คนของพระเจ้า เรามีอะไรบ้าง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 8, 'คนใช้ตอบซาอูลอีกว่า “ดูเถิด ผมมีเงินอยู่หนึ่งเสี้ยวเชเขลและผมจะให้แก่คนของพระเจ้าเพื่อจะบอกหนทางให้แก่เรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 9, '(ในอิสราเอลสมัยเดิม เมื่อคนใดจะไปทูลถามพระเจ้า เขากล่าวว่า “มาเถิด ให้เราไปหาผู้ทํานายกัน” เพราะผู้ที่ในสมัยนี้เราเรียกว่าผู้พยากรณ์นั้น ในสมัยเดิมเขาเรียกว่าผู้ทํานาย)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 10, 'และซาอูลจึงพูดกับคนใช้ของท่านว่า “พูดดีนี่มาให้เราไปกันเถิด” เขาทั้งสองขึ้นไปที่เมืองซึ่งคนของพระเจ้าอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 11, 'ขณะเมื่อเขาขึ้นภูเขาไปยังเมืองนั้น เขาพบพวกผู้หญิงสาวออกมาตักน้ํา จึงถามว่า “ผู้ทํานายอยู่ที่นี่หรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 12, 'เธอทั้งหลายตอบว่า “อยู่นี่ ดูเถิด ท่านเพิ่งขึ้นหน้าท่านไป จงรีบเข้าเถิด ท่านเพิ่งมาในเมืองเมื่อกี้นี้ เพราะว่าวันนี้ประชาชนทําการถวายสัตวบูชา ณ ปูชนียสถานสูง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 13, 'พอท่านทั้งสองเข้าไปถึงในเมือง ท่านทั้งสองจะพบก่อนที่ผู้ทํานายขึ้นไปรับประทานอาหาร ณ ปูชนียสถานสูง เพราะว่าประชาชนจะไม่รับประทานจนกว่าท่านจะมาถึง เพราะท่านจะต้องมาอวยพรแก่เครื่องสัตวบูชา ภายหลังผู้ที่ได้รับเชิญจึงรับประทาน ฉะนั้นบัดนี้จงขึ้นไปเถิด ท่านทั้งสองจะพบทันที”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 14, 'เขาทั้งสองก็ขึ้นไปยังเมืองนั้น ขณะเมื่อเขาเข้าไปในเมือง ดูเถิด ซามูเอลกําลังเดินออกมาตรงหน้าเขาทั้งสอง จะขึ้นไปยังปูชนียสถานสูงนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 15, 'พระเยโฮวาห์ได้ตรัสในหูของซามูเอลแล้วในวันก่อนวันที่ซาอูลมาถึงว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 16, '“พรุ่งนี้เวลาประมาณเท่านี้ เราจะส่งชายผู้หนึ่งซึ่งมาจากดินแดนเบนยามิน เจ้าจงเจิมเขาให้เป็นเจ้าเหนืออิสราเอลประชาชนของเรา เขาจะช่วยประชาชนของเราให้พ้นจากมือคนฟีลิสเตีย เพราะเราได้มองดูประชาชนของเราแล้ว ด้วยเสียงร้องทุกข์ของเขามาถึงเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 17, 'เมื่อซามูเอลเห็นซาอูลเข้าแล้ว พระเยโฮวาห์ทรงบอกท่านว่า “ดูเถิด นี่เป็นชายคนที่เราได้พูดกับเจ้าแล้วนั้น เขาเป็นผู้ที่จะปกครองเหนือประชาชนของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 18, 'แล้วซาอูลก็เข้ามาใกล้ซามูเอลที่ประตูและกล่าวว่า “ขอบอกข้าพเจ้าหน่อยว่า บ้านของผู้ทํานายอยู่ที่ไหน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 19, 'ซามูเอลตอบซาอูลว่า “ฉันเป็นผู้ทํานาย จงเดินขึ้นหน้าฉันไปยังปูชนียสถานสูงนั้น เพราะในวันนี้ท่านจะรับประทานอาหารกับฉัน และพรุ่งนี้เช้าฉันจึงจะให้ท่านไป และฉันจะบอกทุกอย่างที่ข้องอยู่ในใจของท่านแก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 20, 'ส่วนเรื่องลาของท่านที่หายไปสามวันแล้วนั้น อย่าเอาใจใส่เลย เพราะเขาพบแล้ว ความปรารถนาของคนอิสราเอลนั้นมุ่งหมายเอาใครเล่า ไม่ใช่ตัวท่านและวงศ์วานทั้งสิ้นของบิดาท่านดอกหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 21, 'ซาอูลตอบว่า “ข้าพเจ้าไม่ใช่คนเบนยามินดอกหรือ เป็นตระกูลเล็กน้อยที่สุดในอิสราเอล และครอบครัวของข้าพเจ้าไม่ใช่ครอบครัวที่ด้อยที่สุดในตระกูลเบนยามินดอกหรือ ทําไมท่านจึงพูดกับข้าพเจ้าอย่างนี้เล่า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 22, 'แล้วซามูเอลก็พาซาอูลกับคนใช้ของท่านเข้าไปในห้องโถงให้นั่งในตอนต้นที่นั่งสําหรับผู้ที่รับเชิญ ซึ่งมีประมาณสามสิบคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 23, 'และซามูเอลพูดกับคนครัวว่า “จงนําส่วนที่ฉันได้มอบให้ ซึ่งฉันบอกว่า ‘เก็บไว้ต่างหาก’ นั้นมา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 24, 'คนครัวจึงนําเอาส่วนขาและส่วนบนนั้นมาวางไว้ที่ข้างหน้าซาอูล และซามูเอลกล่าวว่า “ดูเถิด สิ่งที่ได้เก็บไว้ก็วางอยู่ต่อหน้าท่าน จงรับประทานเถิด เพราะว่าเก็บไว้ให้แก่ท่านจนถึงชั่วโมงที่กําหนดไว้ ตั้งแต่ฉันกล่าวว่า ‘ฉันได้เชิญประชาชนมาแล้ว’” ซาอูลจึงรับประทานกับซามูเอลในวันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 25, 'และเมื่อเขาทั้งหลายลงมาจากปูชนียสถานสูงเข้ามาในเมือง ซามูเอลสนทนากับซาอูลบนดาดฟ้าหลังคาบ้าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 26, 'และเขาทั้งสองตื่นแต่เช้าตรู่ และอยู่มาเมื่อสว่างแล้ว ซามูเอลก็เรียกซาอูลผู้อยู่บนดาดฟ้าว่า “จงลุกขึ้นเถิด เพื่อฉันจะส่งท่านไปตามทางของท่าน” ซาอูลก็ลุกขึ้น ท่านทั้งสองก็เดินออกไปที่ถนน ทั้งท่านและซามูเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 27, 'เมื่อเขาทั้งหลายกําลังลงมาที่ชานเมือง ซามูเอลจึงพูดกับซาอูลว่า “จงบอกคนใช้ให้เดินล่วงหน้าเราไปก่อน (และเขาก็เดินพ้นไป) ท่านจงหยุดที่นี่ก่อน เพื่อฉันจะได้แจ้งพระดํารัสของพระเจ้าให้ท่านทราบ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 1, 'แล้วซามูเอลก็หยิบขวดน้ํามันเทลงบนศีรษะของซาอูล และจุบท่านแล้วกล่าวว่า “พระเยโฮวาห์ทรงเจิมท่านไว้ให้เป็นเจ้านายเหนือมรดกของพระองค์แล้วมิใช่หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 2, 'เมื่อท่านจากฉันไปในวันนี้ ท่านจะพบชายสองคนริมที่ฝังศพของนางราเชลในเขตแดนเบนยามินที่เศลซาห์ และเขาทั้งสองจะบอกท่านว่า ‘ลาซึ่งท่านไปหานั้นพบแล้ว ดูเถิด บัดนี้บิดาของท่านเลิกกังวลเรื่องลาแล้ว และร้อนใจเรื่องของท่าน กล่าวว่า “เราจะทําอย่างไรเรื่องบุตรชายของเราดี”’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 3, 'และท่านจะเดินเลยที่นั่นไปถึงที่ราบตําบลทาโบร์ ที่นั่นชายสามคนซึ่งกําลังขึ้นไปเฝ้าพระเจ้าที่เบธเอลจะพบท่าน คนหนึ่งอุ้มลูกแพะสามตัว อีกคนหนึ่งถือขนมปังสามก้อน และอีกคนหนึ่งถือถุงหนังน้ําองุ่นถุงหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 4, 'เขาทั้งหลายจะคํานับท่านและมอบขนมปังให้ท่านสองก้อน ซึ่งท่านจะรับจากมือของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 5, 'ต่อจากนั้นท่านจะมาถึงภูเขาของพระเจ้า ที่นั่นมีกองทหารรักษาการของคนฟีลิสเตีย อยู่มาเมื่อท่านมาถึงเมืองนั้น ท่านจะพบผู้พยากรณ์หมู่หนึ่งกําลังลงมาจากปูชนียสถานสูง ถือพิณใหญ่ รํามะนา ปี่ พิณเขาคู่ นําหน้ามา กําลังพยากรณ์เรื่อยมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 6, 'แล้วพระวิญญาณของพระเยโฮวาห์จะมาสถิตกับท่าน และท่านจะพยากรณ์กับคนเหล่านั้น เปลี่ยนเป็นคนละคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 7, 'เมื่อหมายสําคัญเหล่านี้เกิดแก่ท่านแล้ว จงกระทําอะไรตามแต่มีโอกาสเถิด เพราะพระเจ้าทรงสถิตกับท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 8, 'และท่านจงลงไปที่กิลกาลก่อนฉัน และดูเถิด ฉันจะลงมาหาท่านเพื่อจะถวายเครื่องเผาบูชา และถวายสัตว์เป็นเครื่องสันติบูชา ท่านจงคอยอยู่ที่นั่นเจ็ดวันจนฉันมาหาท่าน และสําแดงแก่ท่านว่าท่านควรจะกระทําอะไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 9, 'เมื่อซาอูลหันหลังไปจะจากซามูเอล พระเจ้าทรงประทานจิตใจอีกอย่างหนึ่งแก่ท่าน และหมายสําคัญเหล่านี้ทั้งหมดเกิดขึ้นในวันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 10, 'เมื่อเขาทั้งสองมาถึงภูเขานั้น ดูเถิด ผู้พยากรณ์หมู่หนึ่งพบกับท่าน และพระวิญญาณของพระเจ้าสถิตกับท่าน และท่านก็พยากรณ์อยู่ในหมู่พวกเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 11, 'และต่อมาเมื่อคนทั้งหลายที่รู้จักท่านมาก่อนเห็นว่า ดูเถิด ท่านพยากรณ์อยู่กับพวกผู้พยากรณ์ ประชาชนเหล่านั้นก็พูดกันและกันว่า “อะไรหนอเกิดขึ้นแก่บุตรชายของคีช ซาอูลอยู่ในจําพวกผู้พยากรณ์ด้วยหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 12, 'ชายคนหนึ่งอยู่ที่นั่นตอบว่า “และบิดาของเขาทั้งหลายคือใคร” ดังนั้นจึงเป็นคําภาษิตว่า “ซาอูลอยู่ในจําพวกผู้พยากรณ์ด้วยหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 13, 'เมื่อท่านพยากรณ์สิ้นลงแล้ว ท่านก็มายังปูชนียสถานสูง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 14, 'ฝ่ายลุงของซาอูลจึงถามซาอูลกับคนใช้ว่า “เจ้าไปไหนมา” และท่านตอบว่า “ไปหาลา และเมื่อเราเห็นว่าเราไม่พบลานั้นแล้ว เราจึงไปหาซามูเอล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 15, 'ลุงของซาอูลกล่าวว่า “ซามูเอลบอกอะไรแก่เจ้าบ้าง ขอเล่าให้ฟัง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 16, 'และซาอูลตอบลุงของท่านว่า “เขาบอกเราแจ่มแจ้งว่าพบลาแล้ว” แต่เรื่องราวที่เกี่ยวกับราชอาณาจักร ซึ่งซามูเอลกล่าวถึงนั้นท่านไม่ได้บอกสิ่งใดเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 17, 'ฝ่ายซามูเอลจึงเรียกประชาชนมาประชุมต่อพระเยโฮวาห์ที่มิสเปห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 18, 'และท่านกล่าวแก่คนอิสราเอลว่า “พระเยโฮวาห์พระเจ้าแห่งอิสราเอลตรัสดังนี้ว่า ‘เราได้นําอิสราเอลออกจากอียิปต์ และเราได้ช่วยเจ้าทั้งหลายให้พ้นจากมือของชาวอียิปต์ และจากมือของราชอาณาจักรทั้งหลาย และของคนเหล่านั้นที่บีบบังคับเจ้า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 19, 'แต่วันนี้ท่านละทิ้งพระเจ้าของท่านผู้ซึ่งช่วยท่านให้พ้นจากบรรดาความยากลําบากและความทุกข์ร้อน และท่านทั้งหลายกล่าวว่า ‘เราไม่ยอม แต่ขอตั้งกษัตริย์ไว้เหนือเรา’ เพราะฉะนั้นบัดนี้ท่านทั้งหลายจงเข้าเฝ้าพระเยโฮวาห์ตามตระกูลของท่าน และตามคนที่นับเป็นพันๆของท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 20, 'แล้วซามูเอลก็นําตระกูลอิสราเอลทุกตระกูลเข้ามาใกล้ และจับฉลากได้ตระกูลเบนยามิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 21, 'ท่านก็นําตระกูลเบนยามินเข้ามาใกล้ตามครอบครัว จับฉลากได้ครอบครัวมัตรี และจับฉลากได้ซาอูลบุตรชายคีช แต่เมื่อเขาหาซาอูลก็หาไม่พบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 22, 'เขาจึงทูลถามพระเยโฮวาห์ต่อไปว่า “ชายคนนั้นมาที่นี่หรือยัง” และพระเยโฮวาห์ตรัสว่า “ดูเถิด เขาซ่อนตัวอยู่ที่กองสัมภาระ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 23, 'เขาทั้งหลายจึงวิ่งไปพาท่านมาจากที่นั่น และเมื่อท่านยืนอยู่ท่ามกลางประชาชน ท่านก็สูงกว่าประชาชนทุกคนจากบ่าขึ้นไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 24, 'ซามูเอลจึงกล่าวแก่ประชาชนทั้งปวงว่า “ท่านเห็นผู้ที่พระเยโฮวาห์ทรงเลือกไว้แล้วหรือ ในท่ามกลางประชาชนไม่มีใครเหมือนท่าน” และประชาชนจึงร้องเสียงดังว่า “ขอกษัตริย์ทรงพระเจริญ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 25, 'แล้วซามูเอลจึงบอกกับประชาชนให้ทราบถึงสิทธิและหน้าที่ของตําแหน่งกษัตริย์ และท่านบันทึกไว้ในหนังสือ และวางถวายต่อพระพักตร์พระเยโฮวาห์ แล้วซามูเอลก็ให้ประชาชนกลับไปยังบ้านของตนทุกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 26, 'ซาอูลก็กลับไปยังบ้านของท่านที่กิเบอาห์ด้วย และมีพวกนักรบซึ่งพระเจ้าทรงดลจิตใจไปกับท่านด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 27, 'แต่มีลูกแห่งเบลีอัลบางคนกล่าวว่า “ชายคนนี้จะช่วยเราให้พ้นได้อย่างไร” และเขาทั้งหลายก็ดูหมิ่นท่าน ไม่นําเครื่องบรรณาการมาถวาย แต่ท่านก็นิ่งเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 1, 'ฝ่ายนาหาชคนอัมโมนได้ยกขึ้นไปตั้งค่ายสู้เมืองยาเบชกิเลอาด บรรดาชาวเมืองยาเบชจึงพูดกับนาหาชว่า “ขอทําพันธสัญญากับพวกข้าพเจ้าทั้งหลายและข้าพเจ้าทั้งหลายจะยอมปรนนิบัติท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 2, 'แต่นาหาชคนอัมโมนกล่าวแก่เขาทั้งหลายว่า “เราจะกระทําพันธสัญญากับเจ้าทั้งหลายตามเงื่อนไขต่อไปนี้ คือเราจะทะลวงตาขวาของเจ้าเสียทุกคนให้เป็นที่อัปยศแก่คนอิสราเอลทั้งปวง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 3, 'ฝ่ายพวกผู้ใหญ่แห่งเมืองยาเบชกล่าวแก่ท่านว่า “ขอผ่อนผันให้ข้าพเจ้าสักเจ็ดวัน เพื่อข้าพเจ้าจะได้ส่งผู้สื่อสารไปให้ทั่วขอบเขตอิสราเอล แล้วถ้าไม่มีคนใดช่วยข้าพเจ้าทั้งหลายให้พ้นได้ ข้าพเจ้าทั้งหลายจะยอมมอบตัวไว้ให้แก่ท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 4, 'เมื่อผู้สื่อสารมาถึงกิเบอาห์เมืองของซาอูล เขาทั้งหลายก็รายงานเรื่องราวให้เข้าหูของประชาชน และประชาชนทั้งปวงก็ร้องไห้เสียงดัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 5, 'ดูเถิด ซาอูลต้อนฝูงวัวกลับมาจากทุ่ง และซาอูลถามว่า “ประชาชนเป็นอะไรไปเขาจึงร้องไห้” ดังนั้นเขาจึงเรียนท่านให้ทราบถึงข่าวของพวกยาเบช');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 6, 'เมื่อท่านได้ยินถ้อยคําเหล่านี้พระวิญญาณของพระเจ้าก็สถิตกับซาอูล และความโกรธของท่านเกิดขึ้นอย่างรุนแรง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 7, 'ท่านจึงเอาวัวมาคู่หนึ่งฟันออกเป็นท่อนๆ ส่งไปทั่วเขตแดนทั้งสิ้นของอิสราเอลโดยมือของผู้สื่อสาร กล่าวว่า “ผู้หนึ่งผู้ใดที่ไม่ออกมาตามซาอูลและซามูเอล จะกระทําอย่างนี้แก่วัวของเขา” และความเกรงกลัวพระเยโฮวาห์ก็มาเหนือประชาชน เขาทั้งหลายพากันออกมาเป็นใจเดียวกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 8, 'เมื่อซาอูลตรวจพลอยู่ที่เบเซก นับคนอิสราเอลได้สามแสนคน และชายคนยูดาห์ได้สามหมื่นคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 9, 'เขาจึงบอกแก่ผู้สื่อสารที่มานั้นว่า “ท่านทั้งหลายจงบอกแก่ชาวยาเบชกิเลอาดว่า ‘พรุ่งนี้เวลาแดดร้อนท่านทั้งหลายจะได้รับการช่วยให้พ้น’” เมื่อผู้สื่อสารกลับมาบอกพวกยาเบช เขาทั้งหลายก็มีความยินดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 10, 'ดังนั้นชาวยาเบชจึงว่า “พรุ่งนี้เราจะมอบตัวของเราไว้ให้แก่ท่าน ท่านจงกระทําแก่เราตามที่ท่านเห็นควรทุกอย่าง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 11, 'พอวันรุ่งขึ้นซาอูลก็จัดพลออกเป็นสามกองทัพ ยกเข้ามากลางค่ายในยามสาม และฆ่าฟันคนอัมโมนเสียจนเวลาแดดจัด ต่อมา ผู้ที่เหลืออยู่ก็กระจัดกระจายไป รวมกันไม่ได้สักคู่เดียวเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 12, 'แล้วประชาชนจึงเรียนซามูเอลว่า “คนที่พูดว่า ‘ซาอูลจะปกครองเหนือพวกเราหรือ’ นั้น มีใครบ้าง จงนําคนเหล่านั้นออกมา เราจะได้ฆ่าเขาเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 13, 'แต่ซาอูลกล่าวว่า “ในวันนี้อย่าให้ผู้ใดถูกประหารชีวิตเลย เพราะว่าวันนี้เป็นวันที่พระเยโฮวาห์ทรงช่วยคนอิสราเอลให้พ้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 14, 'แล้วซามูเอลจึงกล่าวแก่ประชาชนว่า “มาเถิด ให้เราพากันไปยังกิลกาล และรื้อฟื้นเรื่องราชอาณาจักรที่นั่นอีก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 15, 'ประชาชนทั้งปวงจึงขึ้นไปยังกิลกาล และที่นั่นเขาทั้งหลายก็ตั้งซาอูลเป็นกษัตริย์ต่อพระพักตร์พระเยโฮวาห์ที่กิลกาล แล้วที่นั่นเขาทั้งหลายถวายสัตว์เป็นเครื่องสันติบูชาต่อพระพักตร์พระเยโฮวาห์ ซาอูลกับประชาชนอิสราเอลทั้งปวงก็ชื่นชมยินดีอย่างยิ่งที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 1, 'ซามูเอลจึงกล่าวแก่คนอิสราเอลทั้งปวงว่า “ดูเถิด ข้าพเจ้าได้ฟังเสียงของท่านทุกเรื่องซึ่งท่านได้บอกข้าพเจ้า และได้แต่งตั้งกษัตริย์เหนือท่านทั้งหลายแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 2, 'และบัดนี้ ดูเถิด กษัตริย์ก็ดําเนินอยู่ต่อหน้าท่าน ส่วนข้าพเจ้าก็ชราผมหงอกแล้ว และดูเถิด บุตรชายของข้าพเจ้าก็อยู่กับท่านทั้งหลาย และข้าพเจ้าดําเนินอยู่ต่อหน้าท่านตั้งแต่หนุ่มๆมาจนทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 3, 'ดูเถิด ข้าพเจ้าอยู่ที่นี่ ขอท่านเป็นพยานปรักปรําข้าพเจ้าต่อพระพักตร์พระเยโฮวาห์ และต่อหน้าท่านที่พระองค์ทรงเจิมไว้ ข้าพเจ้าได้ริบวัวของผู้ใดบ้างหรือ หรือข้าพเจ้าเอาลาของผู้ใดไปบ้าง หรือข้าพเจ้าได้ฉ้อผู้ใด ข้าพเจ้าได้บีบบังคับใครบ้าง ข้าพเจ้าได้รับสินบนจากมือของผู้ใดซึ่งจะกระทําให้ตาของข้าพเจ้าบอดไป ขอกล่าวมาและข้าพเจ้าจะคืนให้แก่ท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 4, 'เขาทั้งหลายกล่าวว่า “ท่านมิได้ฉ้อเรา หรือบีบบังคับเรา หรือรับสิ่งใดไปจากมือของผู้ใด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 5, 'ท่านก็กล่าวแก่เขาทั้งหลายว่า “พระเยโฮวาห์ทรงเป็นพยานต่อท่าน และท่านที่พระองค์ทรงเจิมไว้ก็เป็นพยานในวันนี้ว่า ท่านไม่พบสิ่งใดในมือของข้าพเจ้า” และเขาทั้งหลายกล่าวว่า “พระองค์ทรงเป็นพยานแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 6, 'และซามูเอลก็กล่าวแก่ประชาชนว่า “พระเยโฮวาห์ทรงเป็นผู้แต่งตั้งโมเสสกับอาโรน และทรงนําบรรพบุรุษของท่านขึ้นมาจากแผ่นดินอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 7, 'ฉะนั้นบัดนี้ขอท่านทั้งหลายจงยืนนิ่งอยู่ ข้าพเจ้าจะขอเสนอคดีของท่านต่อพระพักตร์พระเยโฮวาห์ เกี่ยวด้วยบรรดาพระราชกิจอันชอบธรรมของพระเยโฮวาห์ ซึ่งพระองค์ทรงกระทําแก่ท่านทั้งหลายและแก่บรรพบุรุษของท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 8, 'เมื่อยาโคบเข้าไปในอียิปต์ และบรรพบุรุษของท่านร้องต่อพระเยโฮวาห์ พระเยโฮวาห์ก็ทรงใช้โมเสสกับอาโรน ผู้ได้นําบรรพบุรุษของท่านออกจากอียิปต์ และทําให้เขามาอาศัยอยู่ในที่นี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 9, 'แต่เขาทั้งหลายลืมพระเยโฮวาห์พระเจ้าของเขาเสีย พระองค์จึงทรงขายเขาไว้ในมือของสิเสรา แม่ทัพแห่งเมืองฮาโซร์ และมอบไว้ในมือของคนฟีลิสเตีย และไว้ในมือของกษัตริย์แห่งเมืองโมอับ และเขาเหล่านั้นก็ต่อสู้บรรพบุรุษของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 10, 'และเขาทั้งหลายร้องทูลต่อพระเยโฮวาห์ว่า ‘ข้าพระองค์ทั้งหลายได้กระทําบาปแล้ว เพราะว่าข้าพระองค์ทั้งหลายได้ละทิ้งพระเยโฮวาห์ ไปปรนนิบัติพระบาอัลและพระอัชทาโรท แต่บัดนี้ขอพระองค์ทรงช่วยข้าพระองค์ทั้งหลายให้พ้นมือศัตรูของข้าพระองค์ และข้าพระองค์ทั้งหลายจะปรนนิบัติพระองค์’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 11, 'และพระเยโฮวาห์ทรงใช้เยรุบบาอัล และเบดาน และเยฟธาห์ และซามูเอล และช่วยท่านทั้งหลายให้พ้นจากมือศัตรูทุกด้าน และท่านทั้งหลายอาศัยอยู่อย่างปลอดภัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 12, 'และเมื่อท่านทั้งหลายเห็นนาหาชกษัตริย์คนอัมโมนมาต่อสู้ท่านทั้งหลาย ท่านทั้งหลายกล่าวแก่ข้าพเจ้าว่า ‘ไม่ได้ แต่ต้องมีกษัตริย์ปกครองเหนือเรา’ ถึงแม้ว่าพระเยโฮวาห์พระเจ้าของท่านเป็นพระมหากษัตริย์ของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 13, 'ฉะนั้นบัดนี้จงดูกษัตริย์ที่ท่านทั้งหลายได้เลือก ผู้ซึ่งท่านทั้งหลายได้ร้องขอ ดูเถิด พระเยโฮวาห์ทรงตั้งกษัตริย์ไว้เหนือท่านแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 14, 'ถ้าท่านทั้งหลายจะยําเกรงพระเยโฮวาห์ และปรนนิบัติพระองค์ และเชื่อฟังพระสุรเสียงของพระองค์ และไม่กบฏต่อพระบัญชาของพระเยโฮวาห์ ท่านทั้งหลายและกษัตริย์ผู้ปกครองเหนือท่านจึงจะเป็นผู้ติดตามพระเยโฮวาห์พระเจ้าของท่านทั้งหลายต่อไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 15, 'แต่ถ้าท่านทั้งหลายไม่เชื่อฟังพระสุรเสียงของพระเยโฮวาห์ แต่กบฏต่อพระบัญชาของพระเยโฮวาห์ แล้วพระหัตถ์ของพระเยโฮวาห์จะต่อสู้ท่านทั้งหลายเหมือนเคยต่อสู้บรรพบุรุษของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 16, 'เพราะฉะนั้นบัดนี้ท่านทั้งหลายจงยืนนิ่งอยู่ คอยดูเหตุการณ์ยิ่งใหญ่ต่อไปนี้ ซึ่งพระเยโฮวาห์จะทรงกระทําต่อหน้าต่อตาของท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 17, 'วันนี้เป็นฤดูเกี่ยวข้าวสาลีไม่ใช่หรือ ข้าพเจ้าจะร้องทูลต่อพระเยโฮวาห์ และพระองค์จะทรงส่งฟ้าร้องและฝน เพื่อท่านทั้งหลายจะรับรู้และเห็นเองว่า ความชั่วของท่านนั้นใหญ่โตเพียงใด ซึ่งท่านได้กระทําในสายพระเนตรของพระเยโฮวาห์ ในการที่ได้ขอให้มีกษัตริย์สําหรับท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 18, 'ซามูเอลจึงร้องทูลต่อพระเยโฮวาห์ และพระเยโฮวาห์ทรงส่งฟ้าร้องและฝนมาในวันนั้น ประชาชนทั้งหลายก็เกรงกลัวพระเยโฮวาห์และซามูเอลยิ่งนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 19, 'และประชาชนทั้งหลายเรียนซามูเอลว่า “ขอท่านอธิษฐานต่อพระเยโฮวาห์พระเจ้าของท่านเผื่อผู้รับใช้ทั้งหลายของท่าน เพื่อเราทั้งหลายจะไม่ถึงตาย เพราะเราได้เพิ่มความชั่วนี้เข้ากับบาปทั้งสิ้นของเรา คือขอให้มีกษัตริย์สําหรับเราทั้งหลาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 20, 'และซามูเอลกล่าวแก่ประชาชนว่า “อย่ากลัวเลย ท่านทั้งหลายได้กระทําความชั่วนี้ทั้งสิ้นจริงๆแล้ว แต่ท่านทั้งหลายอย่าหันไปเสียจากการติดตามพระเยโฮวาห์ แต่จงปรนนิบัติพระเยโฮวาห์ด้วยสิ้นสุดใจของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 21, 'และอย่าหันเหไปติดตามสิ่งไม่มีสาระ ซึ่งไม่เป็นประโยชน์ หรือไม่ช่วยให้พ้น เพราะเป็นสิ่งไม่มีสาระ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 22, 'เพราะพระเยโฮวาห์จะไม่ละทิ้งประชาชนของพระองค์ ด้วยเห็นแก่พระนามใหญ่ยิ่งของพระองค์ เพราะพระเยโฮวาห์ทรงพอพระทัยแล้วที่จะกระทําให้ท่านเป็นประชาชนของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 23, 'ยิ่งกว่านั้นส่วนข้าพเจ้าขอพระเจ้าอย่ายอมให้ข้าพเจ้ากระทําบาปต่อพระเยโฮวาห์เลยด้วยการหยุดอธิษฐานเพื่อท่านทั้งหลาย แต่ข้าพเจ้าจะสอนทางที่ดีและที่ถูกให้ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 24, 'จงยําเกรงพระเยโฮวาห์เท่านั้น ปรนนิบัติพระองค์ด้วยความจริงด้วยสิ้นสุดใจของท่าน จงพิเคราะห์ถึงมหกิจซึ่งพระองค์ได้ทรงกระทําแก่ท่านแล้วนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 25, 'แต่ถ้าท่านทั้งหลายขืนกระทําความชั่วอยู่ ท่านจะต้องพินาศ ทั้งตัวท่านทั้งหลายเองและกษัตริย์ของท่านด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 1, 'ซาอูลขึ้นครองราชสมบัติแล้วหนึ่งปี และเมื่อพระองค์ทรงปกครองอิสราเอลเป็นเวลาสองปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 2, 'ซาอูลจึงทรงคัดเลือกชายอิสราเอลสามพันคน สองพันคนอยู่กับซาอูลที่มิคมาชและที่แดนเทือกเขาเบธเอล อีกหนึ่งพันคนนั้นอยู่กับโยนาธานที่เมืองกิเบอาห์แห่งคนเบนยามิน ประชาชนนอกนั้นพระองค์ก็ปล่อยให้กลับเต็นท์ของตนทุกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 3, 'โยนาธานได้ตีกองทหารรักษาการของคนฟีลิสเตียซึ่งอยู่ที่เกบาพ่ายแพ้ไป คนฟีลิสเตียได้ยินถึงเรื่องนั้น และซาอูลก็เป่าแตรทั่วแผ่นดินนั้นว่า “ขอให้คนฮีบรูทั้งหลายได้ยิน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 4, 'และคนอิสราเอลทั้งปวงได้ยินเขากล่าวว่า ซาอูลได้รบชนะกองทหารรักษาการของคนฟีลิสเตีย และคนอิสราเอลก็เป็นที่เกลียดชังของคนฟีลิสเตียเป็นอย่างยิ่ง ประชาชนได้ถูกเรียกออกมาให้สมทบกับซาอูลที่กิลกาล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 5, 'และคนฟีลิสเตียชุมนุมกันเพื่อจะต่อสู้คนอิสราเอล มีรถรบสามหมื่น และพลม้าหกพัน และกองทหารนั้นก็มากมายเหมือนเม็ดทรายที่ฝั่งทะเล เขาก็ยกขึ้นมาตั้งค่ายอยู่ที่มิคมาช ทางตะวันออกของเบธาเวน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 6, 'เมื่อคนอิสราเอลเห็นว่าตกอยู่ในที่คับขัน (เพราะประชาชนถูกบีบคั้นอย่างหนัก) แล้วประชาชนก็ซ่อนตัวอยู่ในถ้ํา และในพุ่มไม้หนาทึบ ในซอกหิน ในอุโมงค์และในบ่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 7, 'พวกฮีบรูบางคนได้ข้ามแม่น้ําจอร์แดนไปยังดินแดนกาดและกิเลอาด แต่ฝ่ายซาอูลพระองค์ยังประทับอยู่ที่กิลกาล และประชาชนทั้งหมดติดตามพระองค์ไปด้วยตัวสั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 8, 'พระองค์ทรงคอยอยู่เจ็ดวันตามเวลาที่ซามูเอลกําหนดไว้ แต่ซามูเอลมิได้มาที่กิลกาล ประชาชนก็แตกกระจายไปจากพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 9, 'ดังนั้นซาอูลจึงตรัสว่า “จงนําเครื่องเผาบูชามาให้เราที่นี่ และเครื่องสันติบูชาด้วย” และพระองค์ก็ได้ถวายเครื่องเผาบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 10, 'ต่อมาพอพระองค์ถวายเครื่องเผาบูชาเสร็จ ดูเถิด ซามูเอลก็มาถึง ซาอูลก็เสด็จออกไปต้อนรับและทรงคํานับท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 11, 'ซามูเอลถามว่า “ท่านได้กระทําอะไรไปแล้วนี่” และซาอูลตรัสตอบว่า “เพราะเหตุว่าข้าพเจ้าเห็นประชาชนแตกกระจายไปจากข้าพเจ้า และท่านก็มิได้มาภายในวันที่กําหนดไว้ และคนฟีลิสเตียก็ได้ชุมนุมกันที่มิคมาช');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 12, 'ข้าพเจ้าจึงว่า ‘บัดนี้ คนฟีลิสเตียจะยกมารบกับข้าพเจ้าที่กิลกาล และข้าพเจ้ายังมิได้ทูลขอพระกรุณาแห่งพระเยโฮวาห์’ ข้าพเจ้าจึงข่มตัวเอง และได้ถวายเครื่องเผาบูชา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 13, 'และซามูเอลกล่าวแก่ซาอูลว่า “ท่านได้กระทําการที่โง่เขลาเสียแล้ว ท่านมิได้รักษาพระบัญชาแห่งพระเยโฮวาห์พระเจ้าของท่าน ซึ่งพระองค์ทรงบัญชาท่านไว้ เพราะพระเยโฮวาห์จะได้ทรงสถาปนาราชอาณาจักรของท่านเหนืออิสราเอลเป็นนิตย์แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 14, 'แต่บัดนี้ราชอาณาจักรของท่านจะไม่ยั่งยืน พระเยโฮวาห์ทรงหาชายอีกคนหนึ่งตามชอบพระทัยพระองค์แล้ว และพระเยโฮวาห์ทรงบัญชาชายผู้นั้นให้เป็นเจ้านายเหนือชนชาติของพระองค์ เพราะท่านมิได้รักษาสิ่งซึ่งพระเยโฮวาห์ทรงบัญชาท่านไว้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 15, 'และซามูเอลก็ลุกขึ้นไปจากกิลกาลถึงกิเบอาห์แห่งคนเบนยามิน และซาอูลทรงนับพลซึ่งอยู่กับพระองค์ได้ประมาณหกร้อยคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 16, 'ซาอูลกับโยนาธานราชโอรสของพระองค์ และพลที่อยู่กับพระองค์ก็อยู่ในกิเบอาห์แห่งคนเบนยามิน แต่คนฟีลิสเตียตั้งค่ายอยู่ที่มิคมาช');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 17, 'มีกองปล้นออกมาจากค่ายคนฟีลิสเตียสามกอง กองหนึ่งหันตรงไปยังโอฟราห์ยังแผ่นดินชูอัล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 18, 'อีกกองหนึ่งหันตรงไปยังเบธโฮโรน และอีกกองหนึ่งหันตรงไปยังพรมแดนซึ่งอยู่เหนือหุบเขาเสโบอิมตรงถิ่นทุรกันดาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 19, 'คราวนั้นจะหาช่างเหล็กทั่วแผ่นดินอิสราเอลก็ไม่มี เพราะคนฟีลิสเตียกล่าวว่า “เกรงว่าพวกฮีบรูจะทําดาบหรือหอกใช้เอง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 20, 'แต่คนอิสราเอลทุกคนลงไปยังฟีลิสเตียเพื่อลับเหล็กไถ ผาล ขวานและจอบของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 21, 'ถึงอย่างนั้นพวกเขาก็มีตะไบสําหรับจอบ ผาล สามง่าม ขวาน และลับประตัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 22, 'เพราะฉะนั้นเมื่อถึงวันทําศึกจะหาดาบหรือหอกในมือของพลที่อยู่กับซาอูลและโยนาธานก็ไม่ได้ แต่ซาอูลกับโยนาธานราชโอรสของพระองค์มี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 23, 'และกองทหารรักษาการของคนฟีลิสเตียยกไปถึงทางที่ข้ามไปเมืองมิคมาช');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 1, 'อยู่มาวันหนึ่งโยนาธานราชโอรสของซาอูลกล่าวกับคนหนุ่มที่ถือเครื่องอาวุธของท่านว่า “มาเถิด ให้เราข้ามไปยังกองทหารรักษาการของคนฟีลิสเตียข้างโน้น” แต่หาได้ทูลพระบิดาของตนให้ทราบไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 2, 'ซาอูลทรงพักอยู่ที่ชานเมืองกิเบอาห์ใต้ต้นทับทิม ซึ่งอยู่ที่ตําบลมิโกรน พลซึ่งอยู่ด้วยมีประมาณหกร้อยคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 3, 'กับอาหิยาห์บุตรชายอาหิทูบพี่ชายของอีคาโบด บุตรชายของฟีเนหัสผู้เป็นบุตรชายของเอลีปุโรหิตแห่งพระเยโฮวาห์ที่เมืองชีโลห์ เขาถือเอโฟดไป และพวกพลไม่ทราบว่าโยนาธานไปแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 4, 'ตามทางข้ามเขาที่โยนาธานหาช่องที่จะข้ามไปยังค่ายของฟีลิสเตียนั้น มียอดหินแหลมอยู่ฟากทางข้างนี้ และมียอดหินแหลมอยู่ฟากทางข้างโน้น ยอดหนึ่งมีชื่อว่าโบเซส อีกยอดหนึ่งชื่อเสเนห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 5, 'หินแหลมยอดหนึ่งโผล่ขึ้นข้างเหนือหน้ามิคมาช และอีกยอดหนึ่งโผล่ขึ้นข้างใต้หน้ากิเบอาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 6, 'โยนาธานกล่าวกับคนหนุ่มที่ถือเครื่องอาวุธของท่านว่า “มาเถิด ให้เราข้ามไปยังกองทหารรักษาการของคนเหล่านั้นที่มิได้เข้าสุหนัต บางทีพระเยโฮวาห์จะทรงประกอบกิจเพื่อเรา เพราะว่าไม่มีสิ่งใดที่ขัดขวางพระเยโฮวาห์ได้ในการที่พระองค์จะทรงช่วยให้พ้นไม่ว่าโดยคนมากหรือน้อย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 7, 'ผู้ถือเครื่องอาวุธของท่านจึงตอบท่านว่า “จงกระทําทุกสิ่งที่จิตใจของท่านอยากกระทํา หันไปเถิด ดูเถิด ข้าพเจ้าอยู่กับท่าน ตามแต่จิตใจของท่านจะว่าอย่างไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 8, 'แล้วโยนาธานกล่าวว่า “ดูเถิด เราจะข้ามไปหาคนเหล่านั้น และจะสําแดงตัวของเราให้เขาเห็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 9, 'ถ้าเขาจะกล่าวแก่เราว่า ‘จงคอยอยู่จนกว่าเราจะมาหาเจ้า’ แล้วเราจะยืนนิ่งอยู่ในที่ของเรา และเราจะไม่ไปหาเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 10, 'แต่ถ้าเขาว่า ‘จงขึ้นมาหาเราเถิด’ แล้วเราจึงจะขึ้นไป เพราะพระเยโฮวาห์ทรงมอบเขาไว้ในมือเราแล้ว จะให้เรื่องนี้เป็นสัญญาณแก่เรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 11, 'ทั้งสองจึงสําแดงตัวให้กองทหารรักษาการคนฟีลิสเตียเห็น และคนฟีลิสเตียกล่าวว่า “ดูเถิด พวกฮีบรูออกมาจากรูที่ซ่อนตัวอยู่แล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 12, 'และคนที่กองทหารรักษาการจึงร้องบอกโยนาธานและผู้ถือเครื่องอาวุธของท่านว่า “จงขึ้นมาหาเรา แล้วเราจะแจ้งให้เจ้าทราบสักเรื่องหนึ่ง” และโยนาธานบอกผู้ถือเครื่องอาวุธของท่านว่า “จงตามข้าขึ้นมา เพราะพระเยโฮวาห์ได้ทรงมอบเขาไว้ในมืออิสราเอลแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 13, 'แล้วโยนาธานก็คลานขึ้นไปและผู้ถือเครื่องอาวุธของท่านก็ตามไปด้วย คนเหล่านั้นก็ล้มตายหน้าโยนาธาน และผู้ถือเครื่องอาวุธก็ฆ่าเขาทั้งหลายตามท่านไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 14, 'การฆ่าฟันครั้งแรกที่โยนาธานและผู้ถือเครื่องอาวุธของท่านได้กระทํานั้น มีประมาณยี่สิบคน อย่างในระยะทางครึ่งรอยไถในนาสักสองไร่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 15, 'และบังเกิดการสั่นสะท้านในค่าย ในทุ่งนาและในหมู่ประชาชนทั้งหมด กองทหารนั้นและถึงกองปล้นก็ตกใจตัวสั่น แผ่นดินได้ไหว กระทําให้เกิดการสั่นสะท้านมากยิ่งนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 16, 'ยามของซาอูลที่อยู่ ณ กิเบอาห์แห่งคนเบนยามินก็มองดูอยู่ และดูเถิด มวลชนก็สลายไป วิ่งตีกันไปมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 17, 'แล้วซาอูลจึงรับสั่งแก่พลที่อยู่กับท่านว่า “จงนับดูว่าผู้ใดได้ไปจากเราบ้าง” และเมื่อเขานับดูแล้ว ดูเถิด โยนาธานและผู้ถือเครื่องอาวุธของท่านไม่อยู่ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 18, 'และซาอูลรับสั่งกับอาหิยาห์ว่า “จงนําหีบของพระเจ้ามาที่นี่” เพราะคราวนั้นหีบของพระเจ้าอยู่กับคนอิสราเอลด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 19, 'อยู่มาเมื่อซาอูลตรัสกับปุโรหิต เสียงโกลาหลในค่ายฟีลิสเตียก็เพิ่มขึ้นเรื่อยๆ ซาอูลจึงตรัสกับปุโรหิตว่า “หดมือไว้ก่อน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 20, 'ซาอูลกับบรรดาพลที่อยู่ด้วยก็รวมกันเข้าไปทําศึก และดูเถิด ดาบของทุกคนก็ต่อสู้เพื่อนของตน มีความสับสนอลหม่านอย่างยิ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 21, 'ฝ่ายคนฮีบรูซึ่งเคยอยู่กับคนฟีลิสเตียก่อนเวลานั้น คือผู้ที่ไปอาศัยอยู่กับพวกเขาในค่ายจากชนบทรอบๆ เขาทั้งหลายกลับมาเข้ากับคนอิสราเอลผู้อยู่ฝ่ายซาอูลและโยนาธาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 22, 'ในทํานองเดียวกัน คนอิสราเอลทุกคนที่ซ่อนตัวอยู่ที่แดนเทือกเขาเอฟราอิม เมื่อได้ยินว่าคนฟีลิสเตียกําลังหนี พวกเหล่านี้ก็ไล่ติดตามเขาไปทําศึกด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 23, 'พระเยโฮวาห์ทรงช่วยอิสราเอลให้พ้นในวันนั้น และสงครามก็ผ่านตลอดเมืองเบธาเวนเลยไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 24, 'และคนอิสราเอลต้องทุกข์ยากในวันนั้น เพราะซาอูลได้ทรงให้ประชาชนสาบานไว้ว่า “ถ้าผู้ใดรับประทานอาหารก่อนเวลาเย็นวันนี้ ก่อนเราแก้แค้นศัตรูแล้ว ให้ผู้นั้นถูกสาปแช่ง” เพราะฉะนั้นพวกพลจึงไม่รับประทานอาหารเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 25, 'และชาวแผ่นดินทุกคนก็เข้ามาในป่า มีน้ําผึ้งอยู่ตามพื้นทุ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 26, 'เมื่อประชาชนเข้าไปในป่านั้น ดูเถิด น้ําผึ้งก็กําลังย้อยอยู่ แต่ไม่มีคนใดเอามือใส่ปาก เพราะเขากลัวคําสาบาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 27, 'แต่โยนาธานไม่ได้ยินคําสาบานของพระราชบิดาที่ทรงให้ประชาชนสาบาน จึงเอาปลายไม้ที่ถืออยู่แหย่ที่รังผึ้ง แล้วก็เอามือของท่านใส่ปาก ตาก็แจ่มใสขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 28, 'มีชายคนหนึ่งเรียนว่า “พระราชบิดาของท่านบังคับให้พวกพลสาบานว่า ‘ผู้ใดที่รับประทานอาหารในวันนี้ให้ผู้นั้นถูกสาปแช่ง’” และพวกพลก็อ่อนเพลีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 29, 'แล้วโยนาธานจึงกล่าวว่า “บิดาของข้ากระทําให้แผ่นดินลําบาก ดูซิว่าตาของข้าแจ่มแจ้งเพียงไร เพราะข้าได้รับประทานน้ําผึ้งนี้แต่เล็กน้อย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 30, 'ถ้าวันนี้พวกพลได้กินของที่ริบมาจากศัตรูซึ่งเขาหามาได้อย่างอิ่มหนําจะดีกว่านี้สักเท่าใด เพราะขณะนี้การฆ่าฟันคนฟีลิสเตียก็จะมากกว่ามิใช่หรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 31, 'ในวันนั้นเขาทั้งหลายฆ่าฟันคนฟีลิสเตียจากมิคมาชถึงอัยยาโลน และพวกพลก็อ่อนเพลียนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 32, 'และพวกพลก็วิ่งเข้าหาของที่ริบได้ เอาแกะและวัวและลูกวัวมาฆ่าเสีย ณ ที่นั้นเอง และพวกพลก็กินเนื้อพร้อมกับเลือด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 33, 'แล้วเขาก็ไปทูลซาอูลว่า “ดูเถิด พวกพลกําลังทําบาปต่อพระเยโฮวาห์ โดยรับประทานพร้อมกับเลือด” และซาอูลจึงรับสั่งว่า “พวกเจ้าได้ละเมิดแล้ว วันนี้จงกลิ้งก้อนหินใหญ่มาให้เรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 34, 'และซาอูลตรัสว่า “ท่านจงกระจายกันไปท่ามกลางพวกพลและบอกเขาว่า ‘ให้ทุกคนนําวัวหรือแกะของตัวมาฆ่าเสียที่นี่แล้วรับประทาน อย่ากระทําบาปต่อพระเยโฮวาห์ด้วยรับประทานพร้อมกับเลือด’” คืนนั้นทุกคนก็นําวัวมาและฆ่าเสียที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 35, 'และซาอูลก็สร้างแท่นบูชาถวายแด่พระเยโฮวาห์ เป็นแท่นบูชาแท่นแรกซึ่งพระองค์สร้างถวายแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 36, 'แล้วซาอูลรับสั่งว่า “ให้เราลงไปตามคนฟีลิสเตียทั้งกลางคืน แล้วริบข้าวของของเขาเสียจนรุ่งเช้า อย่าให้เหลือสักคนเดียวเลย” และเขาทั้งหลายตอบว่า “จงกระทําตามที่พระองค์ทรงเห็นชอบทุกประการเถิด” แต่ปุโรหิตกล่าวว่า “ให้เราเข้ามาเฝ้าพระเจ้าที่นี่เถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 37, 'และซาอูลก็ทูลถามพระเจ้าว่า “สมควรที่ข้าพระองค์จะติดตามคนฟีลิสเตียหรือไม่ พระองค์จะทรงมอบเขาทั้งหลายไว้ในมือของอิสราเอลหรือ” แต่ในวันนั้นพระองค์มิได้ทรงตอบท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 38, 'และซาอูลจึงตรัสว่า “มาที่นี่เถิด ท่านทั้งหลายที่เป็นประมุขของคนอิสราเอลพึงทราบและเห็นว่าบาปนี้ได้เกิดขึ้นอย่างไรในวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 39, 'เพราะว่าพระเยโฮวาห์ผู้ทรงช่วยอิสราเอล ทรงพระชนม์อยู่แน่ฉันใด แม้ความผิดนั้นอยู่ที่โยนาธานบุตรชายของข้า เขาก็จะต้องตายเป็นแน่ฉันนั้น” แต่ไม่มีชายสักคนหนึ่งที่อยู่ในหมู่ประชาชนทั้งหมดนั้นตอบพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 40, 'แล้วพระองค์จึงตรัสกับอิสราเอลทั้งปวงว่า “พวกท่านทั้งหลายอยู่ฝ่ายหนึ่ง เราและโยนาธานบุตรชายของเราจะอยู่อีกฝ่ายหนึ่ง” และประชาชนทูลซาอูลว่า “ขอจงกระทําตามที่พระองค์ทรงเห็นชอบเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 41, 'ดังนั้นซาอูลจึงทูลพระเยโฮวาห์พระเจ้าแห่งอิสราเอลว่า “ขอทรงสําแดงฝ่ายถูก” ข้างฝ่ายซาอูลและโยนาธานถูกฉลาก แต่ฝ่ายประชาชนรอดไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 42, 'แล้วซาอูลรับสั่งว่า “จับฉลากระหว่างเรากับโยนาธานบุตรชายของเรา” และโยนาธานถูกฉลาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 43, 'แล้วซาอูลจึงตรัสกับโยนาธานว่า “เจ้าได้กระทําอะไร จงบอกเรามา” โยนาธานก็ทูลว่า “ข้าพระองค์ได้ชิมน้ําผึ้งที่ติดปลายไม้เท้าซึ่งอยู่ในมือของข้าพระองค์เล็กน้อยเท่านั้น และดูเถิด ข้าพระองค์ต้องตาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 44, 'และซาอูลตรัสว่า “ขอพระเจ้าทรงลงโทษและให้หนักยิ่งกว่า โยนาธาน เจ้าจะต้องตายแน่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 45, 'แล้วประชาชนจึงทูลซาอูลว่า “โยนาธานควรจะถึงตายหรือ เขาเป็นผู้ที่ได้นําให้มีชัยใหญ่ยิ่งนี้ในอิสราเอล ขอพระเจ้าอย่ายอมให้เป็นเช่นนั้นเลย พระเยโฮวาห์ทรงพระชนม์อยู่แน่ฉันใด เส้นผมของท่านสักเส้นหนึ่งจะไม่ตกถึงดินฉันนั้น เพราะในวันนี้ท่านได้กระทําศึกด้วยกันกับพระเจ้า” ประชาชนไถ่โยนาธานไว้ ท่านจึงไม่ถึงตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 46, 'แล้วซาอูลก็เลิกทัพไม่ติดตามคนฟีลิสเตีย และคนฟีลิสเตียกลับไปยังที่อยู่ของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 47, 'เมื่อซาอูลได้รับตําแหน่งกษัตริย์เหนืออิสราเอลนั้น พระองค์ได้ทรงต่อสู้บรรดาศัตรูทุกด้าน ต่อสู้กับโมอับ กับชนอัมโมน กับเอโดม กับบรรดากษัตริย์แห่งโศบาห์ และกับคนฟีลิสเตีย ไม่ว่าพระองค์จะหันไปทางไหน พระองค์ก็ทรงกระทําให้เขาพ่ายแพ้ไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 48, 'พระองค์ทรงรวบรวมกองทัพ และทรงโจมตีพวกอามาเลข และทรงช่วยคนอิสราเอลให้พ้นจากมือของบรรดาผู้ที่เข้าปล้นเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 49, 'ฝ่ายโอรสของซาอูล มีโยนาธาน อิชวี มัลคีชูวา และชื่อธิดาทั้งสองของพระองค์คือ คนหัวปีชื่อเมราบ และชื่อผู้น้องคือมีคาล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 50, 'ชื่อมเหสีของซาอูลคืออาหิโนอัม บุตรสาวของอาหิมาอัส และชื่อแม่ทัพของพระองค์ คืออับเนอร์ บุตรชายเนอร์ ลุงของซาอูล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 51, 'คีชเป็นบิดาของซาอูล และเนอร์ผู้เป็นบิดาของอับเนอร์ เป็นบุตรชายของอาบีเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 52, 'ตลอดรัชกาลของซาอูลมีสงครามอย่างรุนแรงกับคนฟีลิสเตียอยู่เสมอ เมื่อซาอูลทรงเห็นผู้ใดเป็นคนแข็งแรงหรือเป็นคนแกล้วกล้า ก็ทรงนํามาไว้ใช้ใกล้พระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 1, 'ซามูเอลก็เรียนซาอูลว่า “พระเยโฮวาห์ทรงใช้ให้ข้าพเจ้ามาเจิมท่านเป็นกษัตริย์เหนืออิสราเอลประชาชนของพระองค์ เพราะฉะนั้นบัดนี้ขอท่านฟังเสียงพระวจนะของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 2, 'พระเยโฮวาห์จอมโยธาตรัสดังนี้ว่า ‘เราจะลงโทษอามาเลขในการที่สกัดทางอิสราเอลเมื่อเขาออกจากอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 3, 'บัดนี้ท่านจงไปโจมตีอามาเลข และทําลายบรรดาที่เขามีนั้นเสียให้สิ้นเชิง อย่าปรานีเขาเลย จงฆ่าเสียทั้งผู้ชายผู้หญิง ทั้งทารกและเด็กที่ยังดูดนม ทั้งวัว แกะ อูฐและลา’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 4, 'ดังนั้นซาอูลจึงรวบรวมพวกพลและตรวจพลที่ตําบลเทลาอิม ได้ทหารราบสองแสนคนและคนยูดาห์หนึ่งหมื่นคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 5, 'ซาอูลก็ทรงยกกองทัพมายังเมืองแห่งหนึ่งของคนอามาเลข และตั้งซุ่มอยู่ในหุบเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 6, 'และซาอูลตรัสแก่คนเคไนต์ว่า “ไปเถิด จงแยกไปเสีย ลงไปเสียจากคนอามาเลข เกรงว่าเราจะทําลายพวกท่านไปพร้อมกับเขา เพราะท่านทั้งหลายได้แสดงความเมตตาต่อคนอิสราเอลทั้งหลายเมื่อเขายกออกมาจากอียิปต์” ดังนั้นคนเคไนต์ก็แยกออกไปจากคนอามาเลข');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 7, 'และซาอูลก็ทรงกระทําให้คนอามาเลขพ่ายแพ้ ตั้งแต่เมืองฮาวิลาห์ไกลไปจนถึงเมืองชูร์ ซึ่งอยู่ด้านหน้าอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 8, 'ทรงจับอากักกษัตริย์ของคนอามาเลขได้ทั้งเป็น และได้ฆ่าฟันประชาชนเสียอย่างสิ้นเชิงด้วยคมดาบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 9, 'แต่ซาอูลและประชาชนได้ไว้ชีวิตอากัก และที่ดีที่สุดของแกะกับวัวและสัตว์อ้วนพีกับลูกแกะ และสิ่งดีๆทั้งหมด ไม่ยอมทําลายเสียอย่างสิ้นเชิง ทุกสิ่งที่เขาดูถูกและไร้ค่า เขาก็ทําลายเสียสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 10, 'แล้วพระวจนะแห่งพระเยโฮวาห์มายังซามูเอลว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 11, '“เราเสียใจแล้วที่เราได้ตั้งซาอูลเป็นกษัตริย์ เพราะเขาได้หันกลับเสียจากการตามเรา และไม่ได้กระทําตามบัญญัติของเรา” และซามูเอลก็โศกเศร้าจึงร้องทูลต่อพระเยโฮวาห์คืนยังรุ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 12, 'และซามูเอลลุกขึ้นแต่เช้าตรู่เพื่อจะไปหาซาอูลในเช้าวันนั้น และมีคนไปเรียนซามูเอลว่า “ซาอูลเสด็จมาที่ภูเขาคารเมล และดูเถิด ทรงมาสร้างที่ระลึกของพระองค์แล้วก็หันและผ่านเรื่อยไปจนลงไปถึงกิลกาล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 13, 'และซามูเอลก็มาหาซาอูล และซาอูลเรียนท่านว่า “ขอพระเยโฮวาห์อวยพระพรท่านเถิด ข้าพเจ้าได้ปฏิบัติตามพระบัญญัติของพระเยโฮวาห์แล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 14, 'และซามูเอลกล่าวว่า “ถ้าอย่างนั้นเสียงแกะที่ร้องเข้าหูข้าพเจ้ากับเสียงวัวที่ข้าพเจ้าได้ยินหมายความว่ากระไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 15, 'ซาอูลตอบว่า “เขาทั้งหลายได้นํามาจากคนอามาเลข เพราะพวกพลได้ไว้ชีวิตแกะและวัวที่ดีที่สุด เพื่อเป็นเครื่องสัตวบูชาแด่พระเยโฮวาห์พระเจ้าของท่าน นอกจากนั้นเราทั้งหลายก็ได้ทําลายเสียสิ้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 16, 'แล้วซามูเอลจึงเรียนซาอูลว่า “ให้รอก่อน ข้าพเจ้าจะขอเรียนท่านว่า พระเยโฮวาห์ตรัสกับข้าพเจ้าอย่างไรคืนนี้” และซาอูลก็เรียนท่านว่า “จงกล่าวไปเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 17, 'และซามูเอลเรียนว่า “แม้ท่านเป็นแต่ผู้เล็กน้อยในสายตาของท่านเอง ท่านก็ได้รับแต่งตั้งให้เป็นประมุขของบรรดาตระกูลอิสราเอล และพระเยโฮวาห์ก็ทรงเจิมท่านไว้เป็นกษัตริย์เหนืออิสราเอลมิใช่หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 18, 'และพระเยโฮวาห์ทรงใช้ให้ท่านออกไปประกอบกิจ ตรัสว่า ‘จงไปทําลายคนอามาเลขคนบาปหนาเสียให้สิ้นเชิง และต่อสู้กับเขาจนกว่าเขาจะถูกผลาญเสียหมด’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 19, 'เหตุใดท่านจึงไม่เชื่อฟังพระสุรเสียงของพระเยโฮวาห์ แต่ไปฉกฉวยทรัพย์สิ่งของต่างๆ และกระทําชั่วในสายพระเนตรของพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 20, 'และซาอูลเรียนซามูเอลว่า “ข้าพเจ้าได้เชื่อฟังพระสุรเสียงของพระเยโฮวาห์แล้ว ข้าพเจ้าได้ไปประกอบกิจตามที่พระเยโฮวาห์ทรงใช้ข้าพเจ้าไป ข้าพเจ้าได้คุมตัวอากักกษัตริย์แห่งคนอามาเลขมา และข้าพเจ้าก็ได้ทําลายคนอามาเลขเสียอย่างสิ้นเชิง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 21, 'แต่พวกพลได้เก็บส่วนของทรัพย์เชลยรวมทั้งแกะและวัว ส่วนที่ดีที่สุดจากของซึ่งกําหนดให้ทําลายเสียให้สิ้นเชิงนั้น เพื่อนํามาเป็นเครื่องสัตวบูชาแด่พระเยโฮวาห์พระเจ้าของท่านที่ในเมืองกิลกาล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 22, 'และซามูเอลกล่าวว่า “พระเยโฮวาห์ทรงพอพระทัยในเครื่องเผาบูชา และเครื่องสัตวบูชามากเท่ากับการที่จะเชื่อฟังพระสุรเสียงของพระเยโฮวาห์หรือ ดูเถิด ที่จะเชื่อฟังก็ดีกว่าเครื่องสัตวบูชา และซึ่งจะสดับฟังก็ดีกว่าไขมันของบรรดาแกะผู้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 23, 'เพราะการกบฏก็เป็นเหมือนบาปแห่งการถือฤกษ์ถือยาม และความดื้อดึงก็เป็นเหมือนความชั่วช้าและการไหว้รูปเคารพ เพราะเหตุที่ท่านทอดทิ้งพระวจนะของพระเยโฮวาห์ พระองค์จึงทรงถอดท่านออกจากตําแหน่งกษัตริย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 24, 'และซาอูลเรียนซามูเอลว่า “ข้าพเจ้าได้กระทําบาปแล้ว เพราะข้าพเจ้าได้ละเมิดพระบัญญัติของพระเยโฮวาห์และคําของท่าน เพราะข้าพเจ้าเกรงกลัวประชาชนและยอมฟังเสียงของเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 25, 'เพราะฉะนั้นบัดนี้ขอท่านโปรดอภัยบาปของข้าพเจ้า และขอกลับไปกับข้าพเจ้า เพื่อข้าพเจ้าจะได้นมัสการพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 26, 'และซามูเอลเรียนซาอูลว่า “ข้าพเจ้าจะไม่กลับไปกับท่าน เพราะท่านทอดทิ้งพระวจนะของพระเยโฮวาห์ และพระเยโฮวาห์ทรงถอดท่านจากเป็นกษัตริย์เหนืออิสราเอล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 27, 'พอซามูเอลหันจะไป ซาอูลก็ได้ยึดชายเสื้อของท่านไว้และเสื้อนั้นก็ขาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 28, 'และซามูเอลเรียนท่านว่า “ในวันนี้พระเยโฮวาห์ได้ทรงฉีกราชอาณาจักรอิสราเอลเสียจากท่านแล้ว และทรงมอบให้แก่ผู้อื่นที่ดีกว่าท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 29, 'ยิ่งกว่านี้ผู้ทรงเป็นกําลังของอิสราเอลจะไม่มุสาหรือกลับใจ เพราะว่าพระองค์หาใช่มนุษย์ที่จะกลับใจไม่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 30, 'ฝ่ายซาอูลจึงเรียนว่า “ข้าพเจ้าได้กระทําบาปแล้ว แต่บัดนี้ขอท่านให้เกียรติแก่ข้าพเจ้า ต่อหน้าพวกผู้ใหญ่ของประชาชนของข้าพเจ้า และต่อหน้าคนอิสราเอล ขอกลับไปกับข้าพเจ้าเพื่อข้าพเจ้าจะได้นมัสการพระเยโฮวาห์พระเจ้าของท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 31, 'ซามูเอลจึงกลับตามซาอูลไป และซาอูลก็นมัสการพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 32, 'แล้วซามูเอลกล่าวว่า “ท่านทั้งหลายจงนําอากักกษัตริย์ของคนอามาเลขมาให้ข้าพเจ้า” และอากักก็เข้ามาหาท่านด้วยหน้าตาเบิกบาน อากักกล่าวว่า “ความขมขื่นแห่งความตายก็ผ่านพ้นไปแน่แล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 33, 'ฝ่ายซามูเอลกล่าวว่า “ดาบของท่านได้กระทําให้ผู้หญิงไร้บุตรฉันใด มารดาของท่านจะไร้บุตรในหมู่พวกผู้หญิงทั้งหลายฉันนั้น” และซามูเอลก็ฟันอากักเสียเป็นท่อนๆต่อพระพักตร์พระเยโฮวาห์ที่ในกิลกาล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 34, 'ฝ่ายซามูเอลก็ไปรามาห์ และซาอูลก็เสด็จขึ้นไปยังวังของพระองค์ที่กิเบอาห์แห่งซาอูล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 35, 'และซามูเอลไม่มาพบซาอูลอีกจนวันสิ้นชีพ แต่ซามูเอลได้โศกเศร้าเพราะซาอูล และพระเยโฮวาห์ทรงกลับพระทัยที่ได้ทรงกระทําให้ซาอูลเป็นกษัตริย์เหนืออิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 1, 'พระเยโฮวาห์ตรัสกับซามูเอลว่า “เจ้าจะเป็นทุกข์เรื่องซาอูลนานเท่าใดเล่า เมื่อเราถอดเขาจากเป็นกษัตริย์เหนืออิสราเอลแล้ว จงเติมน้ํามันให้เต็มเขาสัตว์ของเจ้า แล้วก็ไปเถอะ เราจะใช้เจ้าไปหาเจสซีชาวเบธเลเฮม เพราะว่าในหมู่พวกบุตรชายของเขาเราจัดเตรียมกษัตริย์องค์หนึ่งไว้แล้วสําหรับเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 2, 'ซามูเอลก็กราบทูลว่า “ข้าพระองค์จะไปอย่างไรได้ ถ้าซาอูลได้ยินเขาคงฆ่าข้าพระองค์เสีย” และพระเยโฮวาห์ตรัสว่า “จงนําวัวตัวเมียไปกับเจ้าตัวหนึ่ง และกล่าวว่า ‘ข้าพเจ้ามาถวายสัตวบูชาแด่พระเยโฮวาห์’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 3, 'จงเชิญเจสซีมาที่การถวายสัตวบูชานั้น แล้วเราจะสําแดงให้เจ้ารู้ว่าเจ้าควรจะกระทําประการใด เจ้าจงเจิมให้เราผู้ซึ่งเราจะบอกชื่อแก่เจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 4, 'ซามูเอลก็กระทําตามที่พระเยโฮวาห์ทรงบัญชา และมาที่เบธเลเฮม พวกผู้ใหญ่ของเมืองนั้นก็ตัวสั่นออกมาหาท่านกล่าวว่า “ท่านมาอย่างสันติหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 5, 'และซามูเอลตอบว่า “มาอย่างสันติ เรามาถวายสัตวบูชาแด่พระเยโฮวาห์ จงชําระตัวของท่านให้บริสุทธิ์ และขอเชิญมาที่การถวายสัตวบูชากับเรา” และซามูเอลก็ชําระตัวเจสซีและบุตรชายทั้งหลายของท่านให้บริสุทธิ์ และเชิญเขาเหล่านั้นให้ไปยังการถวายสัตวบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 6, 'อยู่มาเมื่อเขาทั้งหลายมาแล้วท่านก็มองเห็นเอลีอับจึงคิดว่า “ผู้ที่พระองค์ทรงให้เจิมไว้ก็อยู่ต่อพระพักตร์พระเยโฮวาห์แน่แล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 7, 'แต่พระเยโฮวาห์ตรัสกับซามูเอลว่า “อย่ามองดูที่รูปร่างหน้าตาหรือที่ความสูงแห่งร่างกายของเขา ด้วยเราไม่ยอมรับเขา เพราะพระเยโฮวาห์ทอดพระเนตรไม่เหมือนกับที่มนุษย์ดู ด้วยว่ามนุษย์ดูที่รูปร่างภายนอก แต่พระเยโฮวาห์ทอดพระเนตรจิตใจ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 8, 'แล้วเจสซีก็เรียกอาบีนาดับให้เดินผ่านหน้าซามูเอล ท่านกล่าวว่า “พระเยโฮวาห์มิได้ทรงเลือกผู้นี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 9, 'แล้วเจสซีให้ชัมมาห์เดินผ่านไป และท่านก็กล่าวว่า “พระเยโฮวาห์มิได้ทรงเลือกผู้นี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 10, 'แล้วเจสซีให้บุตรชายทั้งเจ็ดคนเดินผ่านหน้าซามูเอล และซามูเอลบอกกับเจสซีว่า “พระเยโฮวาห์มิได้ทรงเลือกคนเหล่านี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 11, 'แล้วซามูเอลกล่าวแก่เจสซีว่า “บุตรชายของท่านอยู่ที่นี่หมดแล้วหรือ” เจสซีตอบว่า “ยังมีคนสุดท้องอีกคนหนึ่ง ดูเถิด เขากําลังเลี้ยงแกะอยู่” และซามูเอลกล่าวแก่เจสซีว่า “จงใช้คนไปตามเขามา เพราะเราจะไม่ยอมนั่งจนกว่าเขาจะมาที่นี่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 12, 'เจสซีก็ใช้คนไปนําเขามา ฝ่ายเขาเป็นคนผิวแดงๆ มีใบหน้าสวยและรูปร่างงามน่าดู และพระเยโฮวาห์ตรัสว่า “จงลุกขึ้นเจิมตั้งเขาไว้ เพราะเป็นคนนี้แหละ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 13, 'ซามูเอลจึงนําขวดเขาน้ํามันและเจิมตั้งเขาไว้ท่ามกลางพี่ชายของเขา และพระวิญญาณของพระเยโฮวาห์ก็สวมทับดาวิดตั้งแต่วันนั้นเป็นต้นไป และซามูเอลก็ลุกขึ้นกลับไปยังรามาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 14, 'ฝ่ายพระวิญญาณของพระเยโฮวาห์ก็พรากจากซาอูล และวิญญาณชั่วจากพระเยโฮวาห์ก็ทรมานซาอูล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 15, 'และพวกมหาดเล็กของซาอูลก็กราบทูลว่า “ดูเถิด บัดนี้วิญญาณชั่วจากพระเจ้ากําลังทรมานพระองค์อยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 16, 'ขอเจ้านายของข้าพระองค์ทั้งหลาย จงบัญชาผู้รับใช้ของพระองค์ผู้ที่อยู่ต่อพระพักตร์พระองค์ให้หาคนที่มีฝีมือในการดีดพิณเขาคู่ และต่อมาเมื่อวิญญาณชั่วจากพระเจ้าสิงพระองค์ ก็ให้เขาดีดพิณเขาคู่แล้วพระองค์จะหายดี”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 17, 'ซาอูลก็รับสั่งผู้รับใช้ของพระองค์ว่า “จงไปหาชายคนหนึ่งที่ดีดพิณได้ดีมาให้เรา นําเขามาหาเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 18, 'คนหนึ่งในพวกผู้รับใช้ทูลว่า “ดูเถิด ข้าพระองค์เห็นบุตรชายคนหนึ่งของเจสซีชาวเบธเลเฮม เป็นผู้มีฝีมือในการดีดพิณ เป็นคนกล้าหาญ เป็นนักรบ เฉลียวฉลาดในกิจการงาน และเป็นคนมีหน้าตาดีและพระเยโฮวาห์ทรงสถิตกับเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 19, 'เพราะฉะนั้นซาอูลจึงส่งผู้สื่อสารไปยังเจสซีกล่าวว่า “จงให้ดาวิดบุตรชายของท่านผู้อยู่กับแกะนั้นมาหาเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 20, 'และเจสซีก็จัดลาตัวหนึ่งบรรทุกขนมปัง และถุงหนังใส่น้ําองุ่นถุงหนึ่ง กับลูกแพะตัวหนึ่ง ฝากไปกับดาวิดบุตรชายของท่านให้ถวายซาอูล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 21, 'ดาวิดก็มาเฝ้าซาอูลและเข้ารับราชการ ซาอูลก็ทรงรักดาวิดมาก ดาวิดก็ได้เป็นคนถือเครื่องอาวุธของซาอูล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 22, 'และซาอูลทรงส่งข่าวไปยังเจสซีว่า “เราขอร้องให้ท่าน โปรดอนุญาตให้ดาวิดมายืนอยู่เบื้องหน้าเราเถิด เพราะเขาเป็นที่โปรดปรานในสายตาของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 23, 'อยู่มาเมื่อวิญญาณชั่วจากพระเจ้ามาสิงซาอูลเมื่อไร ดาวิดก็หยิบพิณเขาคู่ใช้มือดีดถวาย ซาอูลก็ทรงชุ่มชื่นขึ้นและหายดี และวิญญาณชั่วก็พรากจากพระองค์ไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 1, 'ฝ่ายคนฟีลิสเตียก็รวบรวมกองทัพเพื่อจะทําสงคราม เขามาชุมนุมกันอยู่ที่ตําบลโสโคห์ ซึ่งเป็นเขตยูดาห์ และตั้งค่ายอยู่ระหว่างตําบลโสโคห์กับตําบลอาเซคาห์ที่เอเฟสดัมมิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 2, 'และซาอูลกับคนอิสราเอลก็ชุมนุมกัน และตั้งค่ายอยู่ที่หุบเขาเอลาห์ และวางแนวไว้ต่อสู้กับคนฟีลิสเตีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 3, 'คนฟีลิสเตียยืนอยู่ที่ภูเขาข้างหนึ่ง และคนอิสราเอลยืนอยู่ที่ภูเขาอีกข้างหนึ่ง มีหุบเขาคั่นกลาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 4, 'มีผู้หนึ่งชื่อโกลิอัทเป็นยอดทหารได้ออกมาจากค่ายคนฟีลิสเตีย เป็นชาวเมืองกัท สูงหกศอกคืบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 5, 'เขาสวมหมวกทองเหลืองไว้ที่ศีรษะ และสวมเสื้อเกราะ เสื้อเกราะนั้นหนักห้าพันเชเขลเป็นทองเหลือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 6, 'และสวมสนับแข้งทองเหลืองที่ขา และมีหอกทองเหลืองแขวนอยู่ที่บ่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 7, 'ด้ามหอกนั้นเหมือนไม้กระพั่นทอผ้า ตัวหอกหนักหกร้อยเชเขลเป็นเหล็ก ทหารถือโล่ของเขาเดินออกหน้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 8, 'เขาออกมายืนตะโกนไปทางแนวอิสราเอลว่า “เจ้าทั้งหลายออกมาทําศึกทําไมเล่า ข้าเป็นคนฟีลิสเตียไม่ใช่หรือ เจ้าก็เป็นข้ารับใช้ของซาอูลไม่ใช่หรือ จงเลือกคนแทนพวกเจ้า ให้เขาลงมาหาข้านี่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 9, 'ถ้าเขาสามารถสู้รบและฆ่าตัวข้าได้ พวกเราจะยอมเป็นข้าของพวกเจ้า แต่ถ้าข้าชนะเขาและฆ่าเขาตาย แล้วพวกเจ้าต้องเป็นข้าของพวกเรา และรับใช้เรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 10, 'และคนฟีลิสเตียคนนั้นกล่าวว่า “วันนี้ข้าขอท้ากองทัพอิสราเอล จงส่งคนมาสู้กันเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 11, 'เมื่อซาอูลและคนอิสราเอลทั้งสิ้นได้ยินถ้อยคําของคนฟีลิสเตียคนนั้น เขาทั้งหลายก็ท้อใจและกลัวมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 12, 'ฝ่ายดาวิดเป็นบุตรชายของชาวเอฟราธาห์คนหนึ่งแห่งเมืองเบธเลเฮมในยูดาห์ ชื่อเจสซี ผู้มีบุตรชายแปดคน ในรัชกาลของซาอูล ชายคนนี้เป็นคนแก่แล้วเป็นคนอายุมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 13, 'บุตรชายใหญ่สามคนของเจสซีก็ตามซาอูลไปทําศึกแล้ว ชื่อของบุตรชายสามคนที่ไปทําศึกนั้นคือ บุตรหัวปีเอลีอับ คนถัดมาอาบีนาดับ และคนที่สามชัมมาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 14, 'ดาวิดเป็นบุตรสุดท้อง พี่ชายทั้งสามคนก็ตามซาอูลไปแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 15, 'แต่ดาวิดกลับจากซาอูลไปเลี้ยงแกะของบิดาที่เบธเลเฮม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 16, 'คนฟีลิสเตียคนนั้นได้ออกมายืนอยู่ทั้งเช้าและเย็นตั้งสี่สิบวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 17, 'เจสซีสั่งดาวิดบุตรชายของตนว่า “ข้าวคั่วนี้เอฟาห์หนึ่ง และขนมปังสิบก้อนนี้ อันจัดไว้ให้พวกพี่ชายของเจ้า จงเอาไปให้พี่ชายของเจ้าที่ค่ายเร็วๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 18, 'และจงนําเนยแข็งสิบชิ้นนี้ไปให้แก่ผู้บังคับกองพันของเขาด้วย ดูว่าพี่ชายของเจ้าทุกข์สุขอย่างไร แล้วรับของฝากมาจากเขาบ้าง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 19, 'ฝ่ายซาอูลกับเขาทั้งหลายและคนอิสราเอลทั้งปวง อยู่ที่หุบเขาเอลาห์สู้รบกับคนฟีลิสเตียอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 20, 'ดาวิดจึงลุกขึ้นแต่เช้ามืด และทิ้งแกะไว้กับผู้ดูแลนําเสบียงอาหารเดินทางไปตามที่เจสซีได้บัญชาแก่เขา และเขาก็มาถึงเขตค่ายขณะเมื่อกองทัพกําลังยกออกไปสู่แนวรบพลางร้องกราวศึก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 21, 'คนอิสราเอลกับคนฟีลิสเตียก็ยกมาจะปะทะกันกองทัพปะทะกองทัพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 22, 'ดาวิดก็มอบสัมภาระไว้กับผู้ดูแลกองสัมภาระ และวิ่งไปที่แนวรบไปทักทายพี่ชายของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 23, 'เมื่อเขากําลังพูดกันอยู่ ดูเถิด คนฟีลิสเตียชาวเมืองกัท ยอดทหารที่ชื่อโกลิอัทออกมาจากแนวรบฟีลิสเตีย กล่าวท้าอย่างแต่ก่อนและดาวิดก็ได้ยิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 24, 'เมื่อบรรดาคนอิสราเอลเห็นชายคนนั้นก็วิ่งหนีเขาไป กลัวเขามาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 25, 'คนอิสราเอลพูดว่า “เจ้าเคยเห็นคนที่ออกมานั้นหรือ เขาออกมาท้าทายอิสราเอลแท้ๆ ถ้าใครฆ่าเขาได้ กษัตริย์จะพระราชทานทรัพย์ให้เขามากมาย และจะมอบราชธิดาให้ด้วย และกระทําให้วงศ์วานบิดาของเขาเป็นคนยกเว้นการเกณฑ์ในอิสราเอล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 26, 'และดาวิดกล่าวแก่ชายคนที่ยืนอยู่ข้างเขาว่า “เขาจะทําอย่างไรแก่คนที่ฆ่าคนฟีลิสเตียคนนี้ได้ และนําเอาความเหยียดหยามอิสราเอลไปเสีย คนฟีลิสเตียผู้มิได้เข้าสุหนัตคนนี้คือใครเล่า เขาจึงมาท้าทายกองทัพของพระเจ้าผู้ทรงพระชนม์อยู่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 27, 'ประชาชนก็ตอบเขาอย่างเดียวกันว่า “ผู้ที่ฆ่าเขาได้ก็จะได้รับดังที่กล่าวมาแล้วนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 28, 'ฝ่ายเอลีอับพี่ชายหัวปีได้ยินคําที่ดาวิดพูดกับชายคนนั้น เอลีอับก็โกรธดาวิดกล่าวว่า “เจ้าลงมาทําไม เจ้าทิ้งแกะไม่กี่ตัวที่ถิ่นทุรกันดารไว้กับใคร ข้ารู้ถึงความทะเยอทะยานของเจ้า และความคิดชั่วของเจ้า เพราะเจ้าลงมาเพื่อจะมาดูเขารบกัน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 29, 'ดาวิดจึงตอบว่า “ผมได้ทําอะไรไปแล้วเล่า ไม่มีเหตุผลหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 30, 'เขาจึงหันไปหาคนอื่นเสีย และพูดอย่างเดียวกัน และประชาชนก็ตอบแก่เขาอย่างคราวก่อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 31, 'เมื่อเขาทั้งหลายได้ยินคําที่ดาวิดพูด เขาทั้งหลายก็เล่าความให้ซาอูลทราบ ซาอูลจึงใช้คนให้มาตามดาวิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 32, 'ดาวิดก็ทูลซาอูลว่า “อย่าให้จิตใจของผู้ใดฝ่อไปเพราะชายคนนั้นเลย ผู้รับใช้ของพระองค์จะไปสู้รบกับคนฟีลิสเตียคนนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 33, 'และซาอูลกล่าวแก่ดาวิดว่า “เจ้าไม่สามารถที่จะไปสู้รบกับชายฟีลิสเตียคนนั้นดอก เพราะเจ้าเป็นแต่เด็กหนุ่ม และเขาเป็นทหารชํานาญศึกมาตั้งแต่หนุ่มๆแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 34, 'แต่ดาวิดทูลซาอูลว่า “ผู้รับใช้ของพระองค์เคยดูแลแพะแกะของบิดา และเมื่อมีสิงโตหรือหมีมาเอาลูกแกะตัวหนึ่งไปจากฝูง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 35, 'ข้าพระองค์ก็ไล่ตามฆ่ามัน และช่วยลูกแกะนั้นให้พ้นมาจากปากของมัน ถ้ามันลุกขึ้นต่อสู้ข้าพระองค์ ข้าพระองค์ก็จับหนวดเคราของมัน และทุบตีมันจนตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 36, 'ผู้รับใช้ของพระองค์ได้ฆ่าสิงโตและหมีนั้นมาแล้ว คนฟีลิสเตียผู้มิได้เข้าสุหนัตคนนี้ก็เป็นเหมือนสัตว์เหล่านั้นตัวหนึ่ง ด้วยเขาได้ท้าทายกองทัพของพระเจ้าผู้ทรงพระชนม์อยู่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 37, 'และดาวิดทูลต่อไปว่า “พระเยโฮวาห์ผู้ทรงช่วยข้าพระองค์ให้พ้นจากเท้าของสิงโตและจากเท้าของหมี จะทรงช่วยข้าพระองค์ให้พ้นจากมือของคนฟีลิสเตียคนนี้” และซาอูลจึงตรัสแก่ดาวิดว่า “จงไปเถอะ และพระเยโฮวาห์จะทรงสถิตอยู่กับเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 38, 'แล้วซาอูลก็ทรงเอาเครื่องอาวุธของพระองค์สวมให้ดาวิด ทรงสวมหมวกทองเหลืองบนศีรษะของเขา และสวมเสื้อเกราะให้เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 39, 'และดาวิดก็คาดดาบทับเครื่องอาวุธ เขาลองเดินดูก็เห็นว่าใช้ไม่ได้ เพราะเขาไม่ชิน แล้วดาวิดจึงทูลซาอูลว่า “ข้าพระองค์จะสวมเครื่องเหล่านี้ไปไม่ได้ เพราะว่าข้าพระองค์ไม่ชิน” ดาวิดจึงปลดออกเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 40, 'แล้วจึงถือไม้เท้าไว้ และเลือกก้อนหินเกลี้ยงจากลําธารได้ห้าก้อน จึงใส่ในย่ามผู้เลี้ยงแกะของเขาในถุงของเขาและมือถือสลิงอยู่ เขาก็เข้าไปใกล้คนฟีลิสเตียคนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 41, 'คนฟีลิสเตียนั้นก็ออกมาใกล้ดาวิด พร้อมกับคนถือโล่เดินออกหน้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 42, 'เมื่อคนฟีลิสเตียมองไปรอบๆ และเห็นดาวิดก็ดูถูกเขา เพราะเขาเป็นแต่คนหนุ่ม ผิวแดงๆ และมีใบหน้างดงาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 43, 'คนฟีลิสเตียจึงพูดกับดาวิดว่า “ข้าเป็นหมาหรือเจ้าจึงถือไม้เท้ามาหาข้า” และคนฟีลิสเตียคนนั้นก็แช่งด่าดาวิดออกนามพระของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 44, 'คนฟีลิสเตียพูดกับดาวิดว่า “มาหาข้านี่ ข้าจะเอาเนื้อของเจ้าให้นกในอากาศกับสัตว์ในทุ่งกิน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 45, 'แล้วดาวิดก็พูดกับคนฟีลิสเตียคนนั้นว่า “ท่านมาหาข้าพเจ้าด้วยดาบ ด้วยหอกและด้วยโล่ แต่ข้าพเจ้ามาหาท่านในพระนามแห่งพระเยโฮวาห์จอมโยธา พระเจ้าแห่งกองทัพอิสราเอล ผู้ซึ่งท่านได้ท้าทายนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 46, 'ในวันนี้พระเยโฮวาห์จะทรงมอบท่านไว้ในมือข้าพเจ้า และข้าพเจ้าจะประหารท่าน และตัดศีรษะของท่านเสีย และในวันนี้ข้าพเจ้าจะให้ศพของกองทัพฟีลิสเตียแก่นกในอากาศและแก่สัตว์ป่า เพื่อทั้งพิภพนี้จะทราบว่ามีพระเจ้าพระองค์หนึ่งในอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 47, 'และชุมนุมชนนี้ทั้งสิ้นจะทราบว่าพระเยโฮวาห์มิได้ทรงช่วยด้วยดาบหรือด้วยหอก เพราะว่าการรบเป็นของพระเยโฮวาห์ พระองค์จะทรงมอบท่านไว้ในมือของเราทั้งหลาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 48, 'อยู่มาเมื่อคนฟีลิสเตียคนนั้นลุกขึ้นเข้ามาใกล้เพื่อปะทะดาวิด ดาวิดก็วิ่งเข้าหาแนวรบเพื่อปะทะกับคนฟีลิสเตียคนนั้นอย่างรวดเร็ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 49, 'และดาวิดเอามือล้วงเข้าไปในย่ามหยิบหินก้อนหนึ่งออกมา แล้วเหวี่ยงหินก้อนนั้นด้วยสายสลิง ถูกคนฟีลิสเตียคนนั้นที่หน้าผาก ก้อนหินจมเข้าไปในหน้าผาก เขาก็ล้มหน้าคว่ําลงที่ดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 50, 'ดังนั้นดาวิดก็ชนะคนฟีลิสเตียคนนั้นด้วยสลิงและก้อนหินก้อนหนึ่ง และคว่ําคนฟีลิสเตียคนนั้นลง และฆ่าเขาเสีย ดาวิดไม่มีดาบอยู่ในมือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 51, 'ดังนั้นแล้วดาวิดจึงวิ่งไปยืนอยู่เหนือคนฟีลิสเตียคนนั้น หยิบดาบของเขาชักออกจากฝักฆ่าเขาเสียและตัดศีรษะของเขาออกเสียด้วยดาบเล่มนั้น เมื่อคนฟีลิสเตียเห็นว่ายอดทหารของเขาตายเสียแล้วก็พากันหนีไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 52, 'คนอิสราเอลกับคนยูดาห์ก็ลุกขึ้นโห่ร้องไล่ติดตามคนฟีลิสเตียไกลไปจนถึงหุบเขาและถึงประตูเมืองเอโครน ทหารฟีลิสเตียที่บาดเจ็บจึงล้มลงตามทางจากชาอาราอิม ไกลไปจนถึงเมืองกัทและเมืองเอโครน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 53, 'และคนอิสราเอลก็กลับมาจากการไล่ติดตามคนฟีลิสเตีย และมาปล้นค่ายของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 54, 'ดาวิดก็นําศีรษะของคนฟีลิสเตียคนนั้นมาที่กรุงเยรูซาเล็ม แต่เขาเอาเครื่องอาวุธของเขาไว้ที่เต็นท์ของตนแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 55, 'เมื่อซาอูลทรงเห็นดาวิดออกไปต่อสู้กับคนฟีลิสเตีย จึงตรัสถามอับเนอร์แม่ทัพของพระองค์ว่า “อับเนอร์ ชายหนุ่มคนนี้เป็นลูกของใคร” และอับเนอร์ทูลว่า “โอ ข้าแต่กษัตริย์ พระองค์ทรงพระชนม์อยู่แน่ฉันใด ข้าพระองค์ไม่ทราบ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 56, 'กษัตริย์จึงรับสั่งว่า “ไปสืบถามดูว่า เจ้าหนุ่มคนนั้นเป็นลูกของใคร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 57, 'เมื่อดาวิดกลับมาจากการฆ่าคนฟีลิสเตีย อับเนอร์ก็มาพาตัวเขาเข้าไปเฝ้าซาอูลถือศีรษะของคนฟีลิสเตียคนนั้นไปด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 58, 'ซาอูลจึงตรัสถามเขาว่า “เจ้าหนุ่มเอ๋ย เจ้าเป็นลูกของใคร” และดาวิดทูลว่า “ข้าพระองค์เป็นบุตรของเจสซีชาวเบธเลเฮมผู้รับใช้ของพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 1, 'อยู่มาเมื่อดาวิดทูลซาอูลเสร็จแล้ว จิตใจของโยนาธานก็ผูกสมัครรักใคร่กับจิตใจของดาวิด และโยนาธานก็รักเขาเหมือนรักชีวิตของตนเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 2, 'และวันนั้นซาอูลก็ทรงกักตัวเขาไว้ ไม่ยอมให้เขากลับไปบ้านบิดาของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 3, 'แล้วโยนาธานก็กระทําพันธสัญญากับดาวิด เพราะท่านรักเขาเหมือนรักชีวิตของตนเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 4, 'โยนาธานก็ถอดเสื้อคลุมออกมอบให้แก่ดาวิดพร้อมทั้งเครื่องแต่งตัว ดาบ คันธนู และเข็มขัดด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 5, 'และดาวิดก็ออกไปประพฤติตัวอย่างเฉลียวฉลาดไม่ว่าซาอูลจะใช้เขาไป ณ ที่ใด ดังนั้นซาอูลจึงทรงตั้งเขาให้อยู่เหนือนักรบทั้งหลาย เขาก็เป็นที่ยอมรับในสายตาประชาชน และในสายตาข้าราชการทั้งปวงของซาอูลด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 6, 'อยู่มาเมื่อดาวิดกลับมาจากการฆ่าคนฟีลิสเตียนั้นกําลังเดินทางอยู่ พวกผู้หญิงก็ออกมาจากบรรดาหัวเมืองอิสราเอล ร้องเพลงและเต้นรําต้อนรับกษัตริย์ซาอูล ด้วยรํามะนา ด้วยความเบิกบานสําราญใจ และด้วยเครื่องดนตรี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 7, 'และเมื่อพวกผู้หญิงเต้นรํารื่นเริงกันอยู่นั้นก็ขับร้องรับกันว่า “ซาอูลฆ่าคนเป็นพันๆ และดาวิดฆ่าคนเป็นหมื่นๆ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 8, 'ซาอูลทรงกริ้วนัก คําที่ร้องกันนั้นไม่เป็นที่พอพระทัยพระองค์เลย พระองค์ตรัสว่า “เขาสรรเสริญดาวิดว่าฆ่าคนเป็นหมื่นๆ ส่วนเราเขาว่าฆ่าแต่เพียงเป็นพันๆ ดาวิดจะได้อะไรอีกเล่านอกจากราชอาณาจักร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 9, 'ซาอูลก็ทรงใช้สายตาจับดาวิดตั้งแต่วันนั้นเป็นต้นไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 10, 'อยู่มาในวันรุ่งขึ้นวิญญาณชั่วจากพระเจ้าก็เข้าสิงซาอูล ซาอูลก็ทรงพยากรณ์อยู่ในวังของพระองค์ ดาวิดก็กําลังดีดพิณอย่างที่เคยดีดถวายทุกวันมา ซาอูลทรงถือหอกอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 11, 'และซาอูลก็ทรงพุ่งหอก ด้วยนึกว่า “ข้าจะปักดาวิดให้ติดกับผนังเสีย” แต่ดาวิดก็หนีไปจากพระพักตร์พระองค์ได้ถึงสองครั้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 12, 'ซาอูลก็ทรงกลัวดาวิด เพราะว่าพระเยโฮวาห์ทรงสถิตกับเขา แต่ทรงพรากจากซาอูลแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 13, 'ดังนั้นซาอูลจึงรับสั่งให้ย้ายดาวิดไปให้พ้นพระพักตร์ ตั้งเป็นผู้บังคับการกองพัน และเขาได้เข้าออกอยู่ต่อหน้าประชาชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 14, 'ดาวิดกระทําอย่างเฉลียวฉลาดในทุกประการ และพระเยโฮวาห์ทรงสถิตกับเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 15, 'เมื่อซาอูลทรงเห็นว่าดาวิดได้กระทําอย่างเฉลียวฉลาดยิ่ง ก็ทรงเกรงกลัวดาวิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 16, 'แต่คนอิสราเอลและคนยูดาห์ทั้งสิ้นรักดาวิด เพราะเขาเข้าออกต่อหน้าเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 17, 'ฝ่ายซาอูลจึงรับสั่งกับดาวิดว่า “ดูเถิด นี่คือบุตรสาวคนโตของเราชื่อเมราบ เราจะมอบนางให้เป็นภรรยาของเจ้า ขอแต่เจ้าจงเป็นคนกล้าหาญและสู้ศึกของพระเยโฮวาห์เท่านั้น” เพราะซาอูลทรงดําริว่า “อย่าให้มือของเราแตะต้องเขาเลย ให้มือคนฟีลิสเตียแตะต้องเขาดีกว่า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 18, 'ดาวิดทูลซาอูลว่า “ในอิสราเอลข้าพระองค์คือผู้ใด ชีวิตของข้าพระองค์คืออะไร หรือเรือนบรรพบุรุษของข้าพระองค์คือผู้ใด ที่ข้าพระองค์ควรจะเป็นราชบุตรเขยของกษัตริย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 19, 'แต่อยู่มา เมื่อถึงเวลาที่จะทรงยกเมราบราชธิดาของซาอูลให้เป็นภรรยาของดาวิด นางก็ถูกยกให้เป็นภรรยาของอาดรีเอลชาวเมโหลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 20, 'ฝ่ายมีคาลราชธิดาของซาอูลนั้นรักดาวิด มีคนเอาเรื่องไปทูลซาอูล เรื่องนี้เป็นที่พอพระทัยพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 21, 'ซาอูลทรงดําริว่า “ให้เรายกนางให้แก่เขา นางจะได้เป็นกับดักเขา และมือของคนฟีลิสเตียจะได้ต่อสู้เขา” ดังนั้นซาอูลจึงรับสั่งแก่ดาวิดว่า “วันนี้เจ้าจะเป็นบุตรเขยของเราเช่นเดียวกัน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 22, 'ซาอูลทรงบัญชามหาดเล็กว่า “จงพูดเป็นส่วนตัวกับดาวิดว่า ‘ดูเถิด กษัตริย์พอพระทัยในตัวท่าน และบรรดามหาดเล็กของพระองค์ก็รักท่าน เพราะฉะนั้นบัดนี้จงเป็นบุตรเขยของกษัตริย์เถิด’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 23, 'และมหาดเล็กของซาอูลพูดเรื่องนี้ให้ดาวิดฟัง ดาวิดก็ถามว่า “ท่านทั้งหลายเห็นว่า ที่จะเป็นบุตรเขยของกษัตริย์นั้นเป็นเรื่องเล็กน้อยอยู่หรือ ด้วยข้าพเจ้าเป็นแต่คนจน และไม่มีชื่อเสียงอะไรเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 24, 'และมหาดเล็กของซาอูลจึงทูลว่า “ดาวิดพูดอย่างนั้นอย่างนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 25, 'ซาอูลจึงรับสั่งว่า “เจ้าจงพูดเช่นนี้แก่ดาวิดว่า ‘กษัตริย์ไม่มีพระประสงค์จะเอาค่าสินสอดเลย นอกจากหนังปลายองคชาตของคนฟีลิสเตียสักหนึ่งร้อย เพื่อพระองค์จะทรงแก้แค้นศัตรูของกษัตริย์’” ฝ่ายซาอูลทรงดําริว่าจะให้ดาวิดตายเสียด้วยมือของคนฟีลิสเตีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 26, 'และเมื่อมหาดเล็กกล่าวคําเหล่านั้นให้ดาวิดฟัง ก็เป็นที่พอใจดาวิดที่จะเป็นบุตรเขยของกษัตริย์ และเวลาที่กําหนดไว้ยังไม่หมดไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 27, 'ดาวิดก็ลุกขึ้นไปพร้อมกับคนของเขา ได้ฆ่าคนฟีลิสเตียเสียสองร้อยคน และดาวิดก็นําหนังปลายองคชาตของคนเหล่านั้นมาถวายแด่กษัตริย์ครบจํานวน เพื่อเขาจะเป็นบุตรเขยของกษัตริย์ ซาอูลจึงยกมีคาลพระราชธิดาของพระองค์ให้เป็นภรรยาของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 28, 'ซาอูลทรงเห็นและทราบว่าพระเยโฮวาห์ทรงสถิตกับดาวิด และมีคาลพระราชธิดาของซาอูลก็รักเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 29, 'ซาอูลทรงเกรงกลัวดาวิดมากยิ่งขึ้น ดังนั้นซาอูลจึงเป็นศัตรูของดาวิดเรื่อยมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 30, 'บรรดาเจ้านายแห่งคนฟีลิสเตียก็ออกมาทําสงคราม ต่อมาเมื่อเขาทั้งหลายออกมาแล้ว ดาวิดก็ได้กระทําอย่างเฉลียวฉลาดมากกว่าบรรดาข้าราชการของซาอูล ชื่อเสียงของเขาจึงโด่งดังมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 1, 'ซาอูลตรัสกับโยนาธานราชบุตรและกับบรรดาผู้รับใช้ของพระองค์ว่าให้เขาทั้งหลายฆ่าดาวิดเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 2, 'แต่โยนาธานราชบุตรของซาอูลพอใจในดาวิดมาก และโยนาธานก็บอกดาวิดว่า “ซาอูลเสด็จพ่อของข้าพเจ้าหาช่องจะฆ่าท่านเสีย เพราะฉะนั้นบัดนี้ ขอจงระวังตัวให้ดีจนพรุ่งนี้เช้า จงอยู่เสียในที่ลับซ่อนตัวไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 3, 'และข้าพเจ้าจะออกไปยืนอยู่ข้างๆเสด็จพ่อในทุ่งนาที่ท่านอยู่ และข้าพเจ้าจะกราบทูลเสด็จพ่อด้วยเรื่องของท่าน ถ้าข้าพเจ้ารู้เรื่องอะไรจะบอกให้ทราบ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 4, 'โยนาธานกล่าวชมดาวิดให้ซาอูลราชบิดาฟังทูลว่า “ขอกษัตริย์อย่าทรงกระทําบาปต่อดาวิดผู้รับใช้ของพระองค์เลย เพราะเขาหาได้กระทําบาปสิ่งใดต่อพระองค์ไม่ และการงานของเขาก็เป็นงานปฏิบัติพระองค์อย่างดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 5, 'เพราะเขาเสี่ยงชีวิตของตน และประหารคนฟีลิสเตียนั้น และพระเยโฮวาห์ทรงกระทําให้มีการช่วยให้พ้นอย่างใหญ่หลวงเพื่ออิสราเอลทั้งปวง พระองค์ทรงเห็นแล้วและทรงชื่นชมยินดี แต่ไฉนพระองค์จึงจะกระทําบาปต่อโลหิตที่ไร้ความผิด ด้วยการฆ่าดาวิดเสียอย่างปราศจากเหตุผล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 6, 'ซาอูลก็ทรงฟังเสียงของโยนาธานและซาอูลจึงปฏิญาณว่า “พระเยโฮวาห์ทรงพระชนม์อยู่แน่ฉันใด ดาวิดจะไม่ต้องถูกประหารชีวิตเลยฉันนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 7, 'และโยนาธานก็เรียกดาวิด และโยนาธานแจ้งให้เขาทราบถึงสิ่งเหล่านี้ทั้งสิ้น และโยนาธานนําดาวิดเข้าเฝ้าซาอูล และเขาได้เข้าเฝ้าซาอูลอย่างแต่ก่อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 8, 'สงครามได้เกิดขึ้นอีก ดาวิดก็ออกไปต่อสู้กับคนฟีลิสเตีย และได้ฆ่าฟันเสียเป็นอันมาก เขาทั้งหลายจึงหนีไปเสียจากเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 9, 'แล้ววิญญาณชั่วจากพระเยโฮวาห์ก็เข้ามาสิงซาอูล เมื่อพระองค์ประทับในวังของพระองค์ ทรงหอกอยู่ และดาวิดก็กําลังดีดพิณถวาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 10, 'และซาอูลทรงพุ่งหอกหมายปักดาวิดให้ติดฝาผนัง แต่เขาก็หลบหนีพระพักตร์ซาอูลไป ซาอูลจึงทรงพุ่งหอกติดผนัง และดาวิดก็หลบหนีรอดไปได้ในคืนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 11, 'ซาอูลทรงใช้ผู้สื่อสารไปที่บ้านของดาวิดเพื่อเฝ้าดูเขา และเพื่อจะฆ่าเขาเสียในเวลาเช้า แต่มีคาลภรรยาของดาวิดบอกดาวิดว่า “ถ้าคืนนี้ท่านไม่ช่วยชีวิตของตนให้พ้น พรุ่งนี้ท่านจะถูกฆ่าตาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 12, 'มีคาลจึงหย่อนดาวิดลงทางหน้าต่าง และเขาก็หนีรอดไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 13, 'มีคาลได้นํารูปเคารพมาวางไว้บนเตียงนอน และวางหมอนขนแพะไว้ที่ศีรษะ เอาผ้าห่มคลุมไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 14, 'เมื่อซาอูลส่งผู้สื่อสารไปจับดาวิด มีคาลตอบว่า “ท่านไม่สบาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 15, 'แล้วซาอูลส่งผู้สื่อสารนั้นให้ไปดูดาวิดอีก สั่งว่า “จงนําเขามาหาเราทั้งเตียง เพื่อเราจะได้ฆ่าเขาเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 16, 'เมื่อผู้สื่อสารเข้ามา ดูเถิด รูปเคารพก็อยู่ในเตียง พร้อมกับหมอนขนแพะอยู่ที่ศีรษะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 17, 'ซาอูลรับสั่งถามมีคาลว่า “ไฉนเจ้าจึงหลอกลวงเรา และปล่อยศัตรูของเราไปเสีย เขาจึงรอดพ้นไป” และมีคาลทูลตอบซาอูลว่า “เขาพูดกับหม่อมฉันว่า ‘ปล่อยให้ข้าพเจ้าไปเถิด จะให้ข้าพเจ้าฆ่าเธอทําไมเล่า’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 18, 'ฝ่ายดาวิดก็หนีรอดไป เขามาหาซามูเอลที่เมืองรามาห์ และเล่าทุกเรื่องที่ซาอูลได้ทรงกระทําแก่เขาให้ซามูเอลฟัง เขาและซามูเอลก็ไปอยู่เสียที่นาโยท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 19, 'มีคนไปทูลซาอูลว่า “ดูเถิด ดาวิดอยู่ที่นาโยทในเมืองรามาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 20, 'ซาอูลก็รับสั่งให้ผู้สื่อสารไปจับดาวิด และเมื่อเขาไปเห็นหมู่ผู้พยากรณ์กําลังพยากรณ์อยู่ และซามูเอลยืนเป็นหัวหน้าเขาทั้งหลาย พระวิญญาณของพระเจ้าก็มาสถิตกับผู้สื่อสารของซาอูล และเขาทั้งหลายก็พยากรณ์ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 21, 'เมื่อมีคนไปทูลซาอูล พระองค์ก็ทรงใช้ผู้สื่อสารอื่นไป และคนเหล่านั้นก็พยากรณ์ด้วย ซาอูลทรงใช้ให้ผู้สื่อสารไปครั้งที่สาม เขาทั้งหลายก็พยากรณ์ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 22, 'ซาอูลก็เสด็จไปที่รามาห์เอง มาถึงบ่อน้ําใหญ่ที่ในเมืองเสคู และรับสั่งถามว่า “ซามูเอลกับดาวิดอยู่ที่ไหน” มีคนทูลว่า “ดูเถิด เขาทั้งสองอยู่ที่นาโยทในเมืองรามาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 23, 'พระองค์จึงเสด็จไปที่นั่นยังนาโยทในเมืองรามาห์ และพระวิญญาณของพระเจ้าทรงสถิตกับพระองค์ด้วย ทรงดําเนินพลางพยากรณ์พลางจนเสด็จถึงนาโยทที่เมืองรามาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 24, 'พระองค์ทรงถอดฉลองพระองค์ออกด้วย และก็ทรงพยากรณ์ต่อหน้าซามูเอล และบรรทมเปลือยกายอยู่ตลอดวันนั้นและตลอดคืนนั้น ดังนั้นเขาจึงพูดกันว่า “ซาอูลอยู่ในจําพวกผู้พยากรณ์ด้วยหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 1, 'ดาวิดก็หนีจากนาโยทในเมืองรามาห์ และมาหาโยนาธานกล่าวว่า “ข้าพเจ้าได้กระทําสิ่งใด อะไรเป็นความชั่วช้าของข้าพเจ้า และข้าพเจ้าได้กระทําความผิดบาปอันใดต่อเสด็จพ่อของท่าน พระองค์จึงได้แสวงหาชีวิตของข้าพเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 2, 'และโยนาธานจึงตอบเขาว่า “ขอพระเจ้าอย่ายอมให้เป็นเช่นนั้นเลย ท่านจะไม่ตาย ดูเถิด เสด็จพ่อจะมิได้ทรงกระทําการใหญ่น้อยสิ่งใดโดยมิให้ข้าพเจ้ารู้ ทําไมเสด็จพ่อจะปิดบังเรื่องนี้จากข้าพเจ้าเล่า คงไม่เป็นเช่นนั้นแน่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 3, 'ดาวิดจึงปฏิญาณยิ่งกว่านั้นอีกและกล่าวว่า “เสด็จพ่อของท่านทรงทราบอย่างแน่นอนว่า ข้าพเจ้าได้รับความกรุณาในสายตาของท่าน และพระองค์ตรัสว่า ‘อย่าให้โยนาธานรู้เรื่องนี้เลย เกรงว่าเขาจะเศร้าใจ’ พระเยโฮวาห์ทรงพระชนม์อยู่แน่ฉันใด และท่านมีชีวิตอยู่แน่ฉันใด ความจริงมีอยู่ว่า ระหว่างข้าพเจ้ากับความตายก็ยังเหลืออีกเพียงก้าวเดียวฉันนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 4, 'โยนาธานจึงพูดกับดาวิดว่า “จิตใจท่านปรารถนาอะไร ข้าพเจ้าจะทําตามเพื่อท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 5, 'ดาวิดจึงกล่าวกับโยนาธานว่า “ดูเถิด พรุ่งนี้เป็นวันขึ้นหนึ่งค่ํา ข้าพเจ้าไม่ควรขาดที่จะนั่งร่วมโต๊ะเสวยกับกษัตริย์ แต่ขอโปรดให้ข้าพเจ้าไปซ่อนตัวอยู่ที่ในทุ่งนาจนถึงเย็นวันที่สาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 6, 'ถ้าเสด็จพ่อของท่านเห็นข้าพเจ้าขาดไป ก็ขอโปรดทูลพระองค์ว่า ‘ดาวิดได้วิงวอนขอลาข้าพระองค์รีบกลับไปเมืองเบธเลเฮมเมืองของตน เพราะที่นั่นทั้งครอบครัวทําการถวายสัตวบูชาประจําปี’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 7, 'ถ้าพระองค์รับสั่งว่า ‘ดีแล้ว’ ผู้รับใช้ของท่านก็ดีไป แต่ถ้าพระองค์ทรงกริ้ว ก็ขอทราบเถิดว่า พระองค์ดําริการร้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 8, 'เพราะฉะนั้นขอท่านกรุณากระทําแก่ผู้รับใช้ของท่านด้วยใจจงรัก เพราะท่านได้กระทําพันธสัญญาแห่งพระเยโฮวาห์กับผู้รับใช้ของท่านแล้ว แต่ถ้าความชั่วช้ามีอยู่ในข้าพเจ้า ขอท่านฆ่าข้าพเจ้าเสียเองเถิด เพราะท่านจะนําข้าพเจ้าไปให้เสด็จพ่อของท่านทําไม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 9, 'โยนาธานจึงกล่าวว่า “ขอให้สิ่งนั้นอยู่ห่างไกลจากท่านเถิด เพราะถ้าข้าพเจ้าทราบว่าเสด็จพ่อคิดร้ายต่อท่าน ข้าพเจ้าจะไม่ไปบอกท่านหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 10, 'แล้วดาวิดก็กล่าวแก่โยนาธานว่า “ถ้าเสด็จพ่อของท่านตอบท่านอย่างดุดัน ใครจะบอกแก่ข้าพเจ้าได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 11, 'และโยนาธานบอกดาวิดว่า “มาเถิด ให้เราเข้าไปในทุ่งนา” เขาทั้งสองจึงเข้าไปในทุ่งนา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 12, 'และโยนาธานกล่าวแก่ดาวิดว่า “โอ พระเยโฮวาห์พระเจ้าแห่งอิสราเอล เมื่อข้าพเจ้าได้หยั่งดูเสด็จพ่อของข้าพเจ้าในวันพรุ่งนี้ประมาณเวลานี้ หรือในวันที่สาม ดูเถิด ถ้ามีอะไรดีต่อดาวิด และข้าพเจ้าจะไม่ใช้คนไปบอกท่านทีเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 13, 'ขอพระเยโฮวาห์ทรงลงโทษแก่โยนาธานและให้หนักยิ่งกว่า แต่ถ้าเสด็จพ่อพอพระทัยที่จะทําร้ายท่าน ข้าพเจ้าจะบอกท่านให้ทราบ และส่งให้ท่านหนีไปให้พ้นภัย ขอพระเยโฮวาห์ทรงสถิตกับท่าน อย่างที่พระองค์ทรงสถิตกับเสด็จพ่อของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 14, 'ถ้าข้าพเจ้ายังมีชีวิตอยู่ต่อไป ขอท่านสําแดงความเมตตาแห่งพระเยโฮวาห์ต่อข้าพเจ้า เพื่อข้าพเจ้าจะไม่ต้องตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 15, 'ขออย่าตัดความกรุณาของท่านที่มีต่อวงศ์วานของข้าพเจ้าเป็นนิตย์ ในเมื่อพระเยโฮวาห์ทรงกําจัดศัตรูทุกคนของดาวิดเสียจากพื้นพิภพแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 16, 'โยนาธานจึงทําพันธสัญญากับวงศ์วานของดาวิดว่า “ขอพระเยโฮวาห์ทรงแก้แค้นต่อศัตรูของดาวิดเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 17, 'และโยนาธานก็ให้ดาวิดปฏิญาณอีกครั้งหนึ่งโดยความรักของท่านที่มีต่อเขา เพราะท่านรักเขาเหมือนรักชีวิตของตนเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 18, 'แล้วโยนาธานจึงพูดกับดาวิดว่า “พรุ่งนี้เป็นวันขึ้นหนึ่งค่ํา และเขาจะเห็นว่าท่านขาดไป เพราะที่นั่งของท่านจะว่างอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 19, 'เมื่อท่านอยู่สามวันแล้ว ท่านจงลงไปโดยเร็ว ไปยังที่ที่ท่านได้ซ่อนตัวอยู่ ในวันแห่งการกระทํานั้น และคอยอยู่ข้างศิลาเอเซล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 20, 'ข้าพเจ้าจะยิงลูกธนูสามลูกไปข้างๆที่นั่น อย่างกับว่าข้าพเจ้ายิงเป้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 21, 'และดูเถิด ข้าพเจ้าจะใช้เด็กไปสั่งว่า ‘จงไปหาลูกธนู’ ถ้าข้าพเจ้าพูดกับเด็กนั้นว่า ‘ดูเถิด ลูกธนูอยู่ทางข้างนี้ของเจ้า ไปเอามา’ แล้วขอท่านเข้ามา เพราะพระเยโฮวาห์ทรงพระชนม์แน่ฉันใด ท่านก็ปลอดภัยแล้ว ไม่มีอันตรายอันใดฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 22, 'แต่ถ้าข้าพเจ้าพูดกับเด็กหนุ่มนั้นว่า ‘ดูเถิด ลูกธนูอยู่ข้างหน้าเจ้าโน้น’ ท่านจงไปเถิด เพราะว่าพระเยโฮวาห์ได้ทรงส่งท่านไปแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 23, 'ส่วนเรื่องที่ท่านและข้าพเจ้าได้พูดกันนั้น ดูเถิด พระเยโฮวาห์ทรงเป็นพยานระหว่างท่านและข้าพเจ้าเป็นนิตย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 24, 'ดาวิดจึงซ่อนตัวอยู่ในทุ่งนา และเมื่อถึงวันขึ้นหนึ่งค่ํา กษัตริย์ก็ประทับเสวยพระกระยาหาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 25, 'กษัตริย์ประทับบนพระที่นั่งของพระองค์อย่างที่เคยทรงกระทํา คือประทับที่พระที่นั่งข้างๆฝาผนัง โยนาธานยืนอยู่และอับเนอร์นั่งอยู่ข้างซาอูล แต่ที่ของดาวิดก็ว่างอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 26, 'อย่างไรก็ดีในวันนั้นซาอูลมิได้ตรัสประการใด เพราะทรงดําริว่า “ดาวิดคงเกิดเหตุบางอย่าง เขาคงมลทิน เขาคงมลทินแน่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 27, 'อยู่มาวันรุ่งขึ้น คือวันที่สองของเดือน ที่ของดาวิดก็ว่างอยู่ และซาอูลก็ตรัสกับโยนาธานราชบุตรของพระองค์ว่า “ทําไมบุตรเจสซีมิได้มารับประทานอาหาร ทั้งวานนี้และวันนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 28, 'โยนาธานทูลตอบซาอูลว่า “ดาวิดได้วิงวอนขอลาข้าพระองค์ไปยังบ้านเบธเลเฮม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 29, 'เขาว่า ‘ข้าพเจ้าขอร้องให้ท่านอนุญาตให้ข้าพเจ้าไป เพราะครอบครัวของข้าพเจ้ามีการถวายสัตวบูชาในเมือง และพี่ชายของข้าพเจ้าสั่งให้ข้าพเจ้าไปที่นั่น บัดนี้ถ้าข้าพเจ้าได้รับความกรุณาในสายตาของท่าน ข้าพเจ้าก็ขอร้องให้ท่านอนุญาตให้ข้าพเจ้าไปเยี่ยมพี่ชายของข้าพเจ้า’ ด้วยเหตุนี้เขาจึงมิได้มาที่โต๊ะของกษัตริย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 30, 'แล้วความกริ้วของซาอูลก็พลุ่งขึ้นต่อโยนาธาน พระองค์ตรัสกับท่านว่า “เจ้า ลูกของหญิงกบฏและวิปลาส เราไม่รู้หรือว่าเจ้าเลือกบุตรเจสซีมาให้ความอับอายแก่เจ้าเองและให้ความอับอายแก่ความเปลือยเปล่าแห่งแม่ของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 31, 'ตราบใดที่ลูกของเจสซีมีชีวิตอยู่บนพื้นดิน ตัวเจ้าหรือราชอาณาจักรของเจ้าก็จะตั้งอยู่ไม่ได้ เพราะฉะนั้นจงใช้คนไปตามเขามาให้เรา เพราะเขาจะต้องตายแน่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 32, 'แล้วโยนาธานจึงทูลตอบซาอูลพระราชบิดาของท่านว่า “ทําไมเขาจะต้องถูกประหาร เขาได้กระทําผิดสิ่งใดพระเจ้าข้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 33, 'แต่ซาอูลได้ทรงพุ่งหอกใส่ท่านเพื่อจะฆ่าท่าน ดังนั้นโยนาธานจึงทราบว่า พระราชบิดาของท่านหมายฆ่าดาวิดเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 34, 'โยนาธานจึงลุกขึ้นจากโต๊ะด้วยความโกรธยิ่งนัก มิได้รับประทานอาหารในวันที่สองของเดือนนั้น เพราะท่านเศร้าใจด้วยเรื่องดาวิด เพราะว่าพระราชบิดาของท่านได้หยามหน้าดาวิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 35, 'ต่อมารุ่งเช้าขึ้นโยนาธานก็ออกไปที่ทุ่งนาตามที่นัดหมายไว้กับดาวิด มีเด็กไปด้วยคนหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 36, 'และท่านสั่งเด็กนั้นว่า “จงวิ่งไปหาลูกธนูที่เรายิงไป” เมื่อเด็กนั้นวิ่งไป โยนาธานก็ยิงธนูลูกหนึ่งขึ้นหน้าไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 37, 'และเมื่อเด็กนั้นมาถึงที่ที่ลูกธนูซึ่งโยนาธานยิงไปนั้น โยนาธานก็ร้องสั่งเด็กนั้นว่า “ลูกธนูอยู่ข้างหน้าโน้นไม่ใช่หรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 38, 'และโยนาธานร้องสั่งเด็กนั้นว่า “จงรีบไปโดยเร็วอย่าหยุดอยู่” เด็กของโยนาธานก็ไปเก็บลูกธนู และกลับมาหานายของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 39, 'แต่เด็กนั้นไม่ทราบเรื่อง โยนาธานและดาวิดเท่านั้นที่ทราบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 40, 'และโยนาธานก็มอบอาวุธของท่านให้เด็กนั้น และบอกเขาว่า “ไป จงแบกสิ่งเหล่านี้ไปในเมือง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 41, 'เมื่อเด็กนั้นไปแล้ว ดาวิดก็ลุกขึ้นมาจากที่ที่อยู่ทิศใต้ ซบหน้าลงถึงดิน แล้วกราบลงสามครั้ง และทั้งสองก็จุบกัน และร้องไห้กัน จนดาวิดร้องมากเหลือเกิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 42, 'โยนาธานจึงกล่าวกับดาวิดว่า “ขอจงไปเป็นสุขเถิด เพราะเราทั้งสองได้ปฏิญาณไว้แล้วในพระนามแห่งพระเยโฮวาห์ว่า ‘พระเยโฮวาห์จะทรงเป็นพยานระหว่างข้าพเจ้าและท่าน และระหว่างเชื้อสายของข้าพเจ้ากับเชื้อสายของท่านสืบไปเป็นนิตย์’” ดาวิดก็ลุกขึ้นจากไป และโยนาธานก็เข้าไปในเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 1, 'แล้วดาวิดก็มายังเมืองโนบมาหาอาหิเมเลคปุโรหิต และอาหิเมเลคตัวสั่นอยู่เมื่อพบดาวิดจึงพูดกับท่านว่า “ทําไมท่านจึงมาคนเดียว และไม่มีผู้ใดมากับท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 2, 'ดาวิดจึงพูดกับอาหิเมเลคปุโรหิตว่า “กษัตริย์ทรงบัญชาข้าพเจ้าให้ทําเรื่องหนึ่งรับสั่งแก่ข้าพเจ้าว่า ‘อย่าบอกเรื่องซึ่งเราใช้เจ้าไปกระทํานั้นแก่ผู้ใดให้รู้เลย และด้วยเรื่องซึ่งเรามอบหมายแก่เจ้านั้น’ ข้าพเจ้าได้นัดหมายไว้กับพวกผู้รับใช้ ณ ที่แห่งหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 3, 'ฉะนั้นบัดนี้ท่านมีอะไรติดมืออยู่บ้างเล่า ขอมอบขนมปังไว้ในมือข้าพเจ้าสักห้าก้อน หรืออะไรๆที่มีที่นี่ก็ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 4, 'ปุโรหิตนั้นตอบดาวิดว่า “ข้าพเจ้าไม่มีขนมปังธรรมดาติดมือเลย แต่มีขนมปังบริสุทธิ์ ขอแต่คนหนุ่มได้อยู่ห่างจากผู้หญิงมาแล้วก็แล้วกัน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 5, 'และดาวิดก็ตอบท่านปุโรหิตว่า “ที่จริง ตั้งแต่เราออกไปปฏิบัติงาน ผู้หญิงก็ถูกกันไว้ให้ห่างจากเราทั้งหลายประมาณสามวัน และภาชนะของคนหนุ่มก็บริสุทธิ์ และขนมปังนั้นเป็นอย่างธรรมดาอยู่แล้ว ถึงแม้ว่าขนมปังนั้นถูกชําระให้บริสุทธิ์ในภาชนะแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 6, 'ดังนั้นปุโรหิตจึงมอบขนมปังบริสุทธิ์ให้แก่ดาวิด เพราะที่นั่นไม่มีขนมปังอื่นนอกจากขนมปังหน้าพระพักตร์ ซึ่งเก็บมาจากหน้าพระพักตร์พระเยโฮวาห์ เพื่อวางขนมปังใหม่ในวันที่เก็บเอาขนมปังเก่านั้นออกไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 7, 'ในวันนั้นมีชายคนหนึ่งอยู่ที่นั่นเป็นผู้รับใช้ของซาอูล มีธุระต้องเฝ้าพระเยโฮวาห์อยู่ เขาชื่อโดเอก คนเอโดม เป็นหัวหน้าคนเลี้ยงสัตว์ของซาอูล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 8, 'และดาวิดกล่าวแก่อาหิเมเลคว่า “ท่านไม่มีหอกหรือดาบติดมืออยู่สักเล่มหนึ่งหรือ ด้วยข้าพเจ้ามิได้นําดาบหรือเครื่องอาวุธติดมาเลย เพราะราชการของกษัตริย์เป็นการด่วน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 9, 'ปุโรหิตนั้นจึงกล่าวว่า “ดาบของโกลิอัทคนฟีลิสเตีย ซึ่งท่านฆ่าเสียที่หุบเขาเอลาห์นั้น ดูเถิด ยังห่อผ้าอยู่ที่ข้างหลังเอโฟด ถ้าท่านต้องการดาบนั้นจงเอาไปเถิด นอกจากเล่มนั้นแล้วก็ไม่มีดาบอื่นอีก” และดาวิดกล่าวว่า “ไม่มีดาบอื่นเหมือนดาบเล่มนั้นแล้ว ขอให้ข้าพเจ้าเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 10, 'และดาวิดก็ลุกขึ้นในวันนั้นหนีจากพระพักตร์ซาอูลไปหาอาคีชกษัตริย์เมืองกัท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 11, 'และมหาดเล็กของอาคีชทูลพระองค์ว่า “ดาวิดคนนี้ไม่ใช่หรือที่เป็นกษัตริย์ของแผ่นดินนั้น เขามิได้ร้องรําทําเพลงรับกันหรือว่า ‘ซาอูลฆ่าคนเป็นพันๆ และดาวิดฆ่าคนเป็นหมื่นๆ’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 12, 'และดาวิดก็จําถ้อยคําเหล่านี้ไว้ในใจและกลัวอาคีชกษัตริย์เมืองกัทอย่างมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 13, 'ท่านจึงเปลี่ยนอากัปกิริยาต่อหน้าเขาทั้งหลาย และกระทําตนเป็นคนบ้าในมือเขา เที่ยวกาไว้ที่ประตูรั้ว และปล่อยให้น้ําลายไหลลงเปรอะเครา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 14, 'อาคีชจึงสั่งผู้รับใช้ของท่านว่า “ดูเถิด เจ้าเห็นว่าคนนั้นบ้า แล้วเจ้าพาเขามาหาเราทําไม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 15, 'เราขาดคนบ้าหรือ เจ้าจึงพาคนนี้มาทําบ้าให้เราดู คนอย่างนี้ควรเข้ามาในนิเวศของเราหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 1, 'ดาวิดก็จากที่นั่นหนีไปอยู่ที่ถ้ําอดุลลัม เมื่อพี่ชายของท่านและวงศ์วานบิดาของท่านทั้งสิ้นได้ยินเรื่องเขาก็ลงไปหาท่านที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 2, 'แล้วทุกคนที่มีความทุกข์ยาก และทุกคนที่มีหนี้สิน และทุกคนที่ไม่มีความพอใจก็พากันมาหาท่าน และท่านก็เป็นหัวหน้าของเขาทั้งหลาย มีคนมาอยู่กับท่านประมาณสี่ร้อยคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 3, 'ดาวิดก็ออกจากที่นั่นไปยังเมืองมิสเปห์ในแผ่นดินโมอับ และท่านทูลกษัตริย์เมืองโมอับว่า “ขอโปรดให้บิดามารดาของข้าพเจ้ามาอยู่กับพระองค์เถิด จนกว่าข้าพเจ้าจะทราบว่าพระเจ้าจะทรงกระทําประการใดเพื่อข้าพเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 4, 'และท่านก็นําบิดามารดามาเฝ้ากษัตริย์แห่งโมอับ และท่านทั้งสองก็อาศัยอยู่กับกษัตริย์ตลอดเวลาที่ดาวิดอยู่ในที่กําบังเข้มแข็ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 5, 'แล้วผู้พยากรณ์กาดกล่าวแก่ดาวิดว่า “ท่านอย่าอยู่ในที่กําบังเข้มแข็งนี้เลย จงออกไปและเข้าในแผ่นดินยูดาห์เถิด” ดาวิดก็ไปและมาอยู่ในป่าเฮเรท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 6, 'ฝ่ายซาอูลทรงได้ยินว่ามีผู้พบดาวิดและคนที่อยู่กับท่าน (เวลานั้นซาอูลประทับที่เมืองกิเบอาห์ใต้ต้นไม้แห่งหนึ่งที่รามาห์ ทรงหอกอยู่ และบรรดาผู้รับใช้ของพระองค์ก็ยืนอยู่รอบพระองค์)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 7, 'และซาอูลตรัสกับผู้รับใช้ที่ยืนอยู่รอบพระองค์ว่า “เจ้าทั้งหลายพวกคนเบนยามิน จงฟังเถิด บุตรของเจสซีจะให้นาและสวนองุ่นแก่เจ้าทั้งหลายหรือ จะตั้งเจ้าทั้งหลายให้เป็นผู้บังคับการกองพันกองร้อยหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 8, 'เจ้าทั้งหลายจึงได้คิดกบฏต่อเรา ไม่มีใครแจ้งแก่เราเลย เมื่อลูกของเราทําพันธไมตรีกับบุตรของเจสซีนั้น ไม่มีผู้ใดร่วมทุกข์กับเรา หรือแจ้งแก่เราว่า ลูกของเราปลุกปั่นผู้รับใช้ของเราให้ต่อสู้เรา คอยซุ่มดักเราอยู่อย่างทุกวันนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 9, 'โดเอกคนเอโดมซึ่งตั้งไว้ให้อยู่เหนือพวกผู้รับใช้ของซาอูลจึงทูลตอบว่า “ข้าพระองค์เห็นบุตรเจสซีมาที่เมืองโนบมาหาอาหิเมเลคบุตรอาหิทูบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 10, 'แล้วเขาก็ทูลถามพระเยโฮวาห์ให้ท่าน และให้เสบียงอาหาร และให้ดาบของโกลิอัทคนฟีลิสเตียแก่ท่านไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 11, 'แล้วกษัตริย์ก็ใช้ให้ไปเรียกอาหิเมเลคปุโรหิต บุตรชายอาหิทูบ และวงศ์วานบิดาของท่านทั้งสิ้น ผู้เป็นปุโรหิตเมืองโนบ ทุกคนก็มาหากษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 12, 'และซาอูลตรัสว่า “บุตรอาหิทูบเอ๋ย จงฟังเถิด” เขาทูลตอบว่า “เจ้านายของข้าพระองค์ ข้าพระองค์อยู่ที่นี่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 13, 'และซาอูลตรัสแก่เขาว่า “ทําไมเจ้าจึงร่วมกันกบฏต่อเรา ทั้งเจ้าและบุตรของเจสซี ในการที่เจ้าได้ให้ขนมปังและดาบแก่เขา และได้ทูลถามพระเจ้าให้เขา เขาจึงลุกขึ้นต่อสู้เรา และคอยซุ่มดักเราอยู่อย่างทุกวันนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 14, 'และอาหิเมเลคทูลตอบกษัตริย์ว่า “ในบรรดาข้าราชการผู้รับใช้ของพระองค์ มีผู้ใดเล่าที่จะสัตย์ซื่ออย่างดาวิด พระราชบุตรเขยของกษัตริย์ ผู้บังคับบัญชาทหารราชองครักษ์ และเป็นผู้มีเกียรติในพระราชสํานักของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 15, 'แล้วข้าพระองค์ได้ทูลขอพระเจ้าเพื่อเขาจริงหรือ เปล่าเลย ขอกษัตริย์อย่าทรงกล่าวโทษสิ่งใดต่อผู้รับใช้ของพระองค์ หรือวงศ์วานของบิดาของข้าพระองค์ทั้งสิ้น เพราะผู้รับใช้ของพระองค์ไม่ทราบเรื่องนี้เลย ไม่ว่ามากหรือน้อย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 16, 'กษัตริย์ตรัสว่า “อาหิเมเลค เจ้าจะต้องตายแน่ ทั้งเจ้าและวงศ์วานบิดาของเจ้าทั้งสิ้นด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 17, 'และกษัตริย์ก็รับสั่งแก่ทหารราบผู้ยืนเฝ้าอยู่ว่า “จงหันมาประหารปุโรหิตเหล่านี้ของพระเยโฮวาห์เสีย เพราะว่ามือของเขาอยู่กับดาวิดด้วย เขารู้แล้วว่ามันหนีไป แต่ไม่แจ้งให้เรารู้” แต่ข้าราชการผู้รับใช้ของกษัตริย์ไม่ยอมลงมือฟันปุโรหิตของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 18, 'แล้วกษัตริย์จึงตรัสกับโดเอกว่า “เจ้าจงหันไปฟันปุโรหิตเหล่านั้น” โดเอกคนเอโดมก็หันไปฟันบรรดาปุโรหิต ในวันนั้นเขาฆ่าบุคคลที่สวมเอโฟดผ้าป่านเสียแปดสิบห้าคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 19, 'และเมืองโนบ เมืองของพวกปุโรหิต เขาประหารเสียด้วยคมดาบ ฆ่าเสียด้วยคมดาบทั้งผู้ชาย ผู้หญิง เด็ก และเด็กที่ยังดูดนม วัว ลา และแกะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 20, 'แต่บุตรชายคนหนึ่งของอาหิเมเลค บุตรชายอาหิทูบ ชื่ออาบียาธาร์ได้รอดพ้นและหนีตามดาวิดไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 21, 'อาบียาธาร์ก็บอกดาวิดว่าซาอูลได้ประหารปุโรหิตของพระเยโฮวาห์เสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 22, 'ดาวิดจึงพูดกับอาบียาธาร์ว่า “ในวันนั้นเมื่อโดเอกคนเอโดมอยู่ที่นั่น เรารู้แล้วว่า เขาจะต้องทูลซาอูลแน่ เราเป็นต้นเหตุแห่งความตายของบุคคลทั้งสิ้นในวงศ์วานบิดาของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 23, 'จงอยู่เสียกับเราเถิด อย่ากลัวเลย เพราะผู้ที่แสวงหาชีวิตของท่านก็แสวงหาชีวิตของเราด้วย ท่านอยู่กับเราก็จะพ้นภัย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 1, 'แล้วพวกเขาบอกดาวิดว่า “ดูเถิด คนฟีลิสเตียกําลังรบเมืองเคอีลาห์อยู่และปล้นเอาข้าวที่ลาน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 2, 'ดาวิดจึงทูลถามพระเยโฮวาห์ว่า “ควรที่ข้าพระองค์จะไปต่อสู้กับคนฟีลิสเตียเหล่านี้หรือไม่” และพระเยโฮวาห์ตรัสกับดาวิดว่า “จงไปต่อสู้คนฟีลิสเตียและช่วยเมืองเคอีลาห์ให้พ้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 3, 'แต่คนของดาวิดเรียนท่านว่า “ดูเถิด เราอยู่ในยูดาห์นี่ก็ยังกลัวอยู่ ถ้าเราขึ้นไปยังเคอีลาห์สู้รบกับกองทัพของฟีลิสเตียเราจะยิ่งกลัวมากขึ้นเท่าใด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 4, 'แล้วดาวิดก็ทูลถามพระเยโฮวาห์อีก และพระเยโฮวาห์ตรัสตอบท่านว่า “จงลุกขึ้นลงไปยังเคอีลาห์เถิด เพราะเราจะมอบคนฟีลิสเตียไว้ในมือของเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 5, 'และดาวิดกับคนของท่านก็ไปยังเคอีลาห์ต่อสู้กับคนฟีลิสเตีย นําเอาสัตว์เลี้ยงของเขาไป และฆ่าฟันเขาทั้งหลายเสียเป็นอันมาก ดังนั้นแหละดาวิดก็ได้ช่วยชาวเมืองเคอีลาห์ให้พ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 6, 'อยู่มาเมื่ออาบียาธาร์บุตรชายของอาหิเมเลคหนีไปหาดาวิดที่เมืองเคอีลาห์นั้น เขาถือเอโฟดลงมาด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 7, 'มีคนไปทูลซาอูลว่า ดาวิดมาที่เคอีลาห์แล้ว ซาอูลจึงตรัสว่า “พระเจ้าทรงมอบเขาไว้ในมือเราแล้ว เพราะที่เขาเข้าไปในเมืองที่มีประตูและดาล เขาก็ขังตัวเองไว้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 8, 'และซาอูลทรงให้เรียกพลทั้งปวงเข้าสงคราม ให้ลงไปยังเคอีลาห์เพื่อล้อมดาวิดกับคนของท่านไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 9, 'ดาวิดทราบว่าซาอูลทรงคิดร้ายต่อท่าน ท่านจึงพูดกับอาบียาธาร์ปุโรหิตว่า “จงนําเอาเอโฟดมาที่นี่เถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 10, 'ดาวิดกราบทูลว่า “โอ ข้าแต่พระเยโฮวาห์พระเจ้าแห่งอิสราเอล ผู้รับใช้ของพระองค์ได้ยินแน่ว่า ซาอูลหาช่องที่จะมายังเคอีลาห์เพื่อทําลายเมืองนี้เพราะข้าพระองค์เป็นเหตุ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 11, 'ประชาชนชาวเคอีลาห์จะมอบข้าพระองค์ไว้ในมือท่านหรือ ซาอูลจะเสด็จลงมาดังที่ผู้รับใช้ของพระองค์ได้ยินนั้นหรือ โอ ข้าแต่พระเยโฮวาห์พระเจ้าแห่งอิสราเอล ขอพระองค์ทรงบอกผู้รับใช้ของพระองค์เถิด” และพระเยโฮวาห์ตรัสว่า “เขาจะลงมา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 12, 'แล้วดาวิดจึงกราบทูลว่า “ประชาชนชาวเคอีลาห์จะมอบข้าพระองค์และคนของข้าพระองค์ไว้ในมือของซาอูลหรือ” และพระเยโฮวาห์ตรัสว่า “เขาทั้งหลายจะมอบเจ้าไว้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 13, 'แล้วดาวิดกับคนของท่านซึ่งมีประมาณหกร้อยคนก็ลุกขึ้นไปเสียจากเคอีลาห์ และเขาทั้งหลายก็ไปตามแต่ที่เขาจะไปได้ เมื่อมีคนไปทูลซาอูลว่า ดาวิดหนีไปจากเคอีลาห์แล้ว ซาอูลก็ทรงเลิกการติดตาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 14, 'และดาวิดก็อยู่ในถิ่นทุรกันดารตามที่กําบังเข้มแข็งและอยู่ในแดนเทือกเขาแห่งถิ่นทุรกันดารศิฟ และซาอูลก็ทรงแสวงหาท่านทุกวัน แต่พระเจ้ามิได้มอบท่านไว้ในมือของซาอูล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 15, 'และดาวิดเห็นว่าซาอูลได้ทรงออกมาแสวงหาชีวิตของท่าน ดาวิดอยู่ในถิ่นทุรกันดารศิฟที่ป่าไม้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 16, 'และโยนาธานราชบุตรของซาอูลได้ลุกขึ้นไปหาดาวิดที่ป่าไม้ และสนับสนุนมือของท่านให้เข้มแข็งขึ้นในพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 17, 'โยนาธานพูดกับท่านว่า “อย่ากลัวเลย เพราะว่ามือของซาอูลเสด็จพ่อของข้าพเจ้าจะหาท่านไม่พบ ท่านจะได้เป็นกษัตริย์เหนืออิสราเอล และข้าพเจ้าจะเป็นอุปราช ซาอูลเสด็จพ่อของข้าพเจ้าก็ทราบเรื่องนี้ด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 18, 'และทั้งสองก็กระทําพันธสัญญาต่อพระพักตร์พระเยโฮวาห์ ดาวิดยังค้างอยู่ที่ป่าไม้ และโยนาธานก็กลับไปวัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 19, 'ฝ่ายชาวศิฟได้ขึ้นไปหาซาอูลที่กิเบอาห์ทูลว่า “ดาวิดได้ซ่อนตัวอยู่ท่ามกลางพวกข้าพระองค์ ในที่กําบังเข้มแข็งที่ป่าไม้ บนเนินเขาฮาคีลาห์ ซึ่งอยู่ใต้เยชิโมนมิใช่หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 20, 'โอ ข้าแต่กษัตริย์ เพราะฉะนั้นบัดนี้ขอเสด็จลงไปตามสุดพระทัยปรารถนาที่จะลงไป ฝ่ายพวกข้าพระองค์จะมอบเขาไว้ในหัตถ์ของกษัตริย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 21, 'และซาอูลตรัสว่า “ขอพระเยโฮวาห์ทรงอํานวยพระพรแก่พวกท่าน เพราะพวกท่านปรานีเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 22, 'จงไปหาดูให้แน่นอนยิ่งขึ้น ดูให้รู้ว่าเขาอยู่ที่ไหน ใครเห็นเขาที่นั่นบ้าง เพราะมีคนบอกเราว่า เขาฉลาดนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 23, 'เพราะฉะนั้นจงไปสังเกตดูที่ซุ่มว่าเขาซ่อนตัวอยู่ที่ไหน และกลับมาเอาเนื้อความแน่นอนมาบอกเรา แล้วเราจะไปกับท่าน ต่อมาถ้าเขาอยู่ในเขตแผ่นดิน เราจะค้นหาเขาในบรรดาคนยูดาห์ที่นับเป็นพันๆ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 24, 'เขาทั้งหลายก็ลุกขึ้นไปยังศิฟก่อนซาอูล ฝ่ายดาวิดกับคนของท่านอยู่ในถิ่นทุรกันดารมาโอนในที่ราบใต้เยชิโมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 25, 'ซาอูลกับคนของพระองค์ก็แสวงหาท่าน มีคนบอกดาวิด ท่านจึงลงไปยังศิลาและอยู่ในถิ่นทุรกันดารมาโอน เมื่อซาอูลทรงได้ยินดังนั้นก็ทรงติดตามดาวิดไปในถิ่นทุรกันดารมาโอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 26, 'ซาอูลเสด็จไปฟากภูเขาข้างนี้ ดาวิดกับคนของท่านอยู่ฟากภูเขาข้างโน้น ดาวิดก็รีบหนีจากพระพักตร์ซาอูล เพราะซาอูลกับคนของพระองค์มาล้อมรอบดาวิดกับคนของท่านเพื่อจะจับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 27, 'แต่มีผู้สื่อสารคนหนึ่งมาทูลซาอูลว่า “ขอรีบเสด็จกลับ เพราะคนฟีลิสเตียยกกองทัพมาบุกรุกแผ่นดิน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 28, 'ซาอูลจึงเสด็จกลับจากการไล่ตามดาวิดไปรบกับฟีลิสเตีย เขาจึงเรียกที่นั้นว่าเส-ลาฮามาเลคอท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 29, 'ดาวิดก็ขึ้นไปจากที่นั่นไปอาศัยอยู่ในที่กําบังเข้มแข็งแห่งเอนเกดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 1, 'อยู่มาเมื่อซาอูลเสด็จกลับจากการไล่ตามคนฟีลิสเตียแล้ว มีคนมาทูลว่า “ดูเถิด ดาวิดอยู่ในถิ่นทุรกันดารเมืองเอนเกดี”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 2, 'แล้วซาอูลก็ทรงนําพลที่คัดเลือกจากบรรดาคนอิสราเอลแล้วสามพันคนไปแสวงหาดาวิดกับคนของท่านที่หินเลียงผา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 3, 'และพระองค์เสด็จมาที่คอกแกะริมทาง มีถ้ําอยู่ถ้ําหนึ่งที่นั่น และซาอูลก็เสด็จเข้าไปปล่อยทุกข์ ฝ่ายดาวิดกับคนของท่านนั่งอยู่ที่ส่วนลึกที่สุดของถ้ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 4, 'คนของดาวิดก็เรียนท่านว่า “ดูเถิด วันนี้เป็นวันที่พระเยโฮวาห์ตรัสกับท่านว่า ‘ดูเถิด เราจะมอบศัตรูของเจ้าไว้ในมือของเจ้า เพื่อเจ้าจะได้ทํากับเขาตามที่เจ้าเห็นควร’” แล้วดาวิดก็ลุกขึ้นเข้าไปตัดชายฉลองพระองค์ของซาอูลอย่างลับๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 5, 'ต่อมาภายหลังใจของดาวิดก็ตําหนิตัวท่านเอง เพราะท่านได้ตัดชายฉลองพระองค์ของซาอูล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 6, 'ท่านว่าแก่คนของท่านว่า “ขอพระเยโฮวาห์ทรงห้ามไม่ให้ข้าพเจ้ากระทําสิ่งนี้ต่อเจ้านายของข้าพเจ้า ซึ่งเป็นผู้ที่พระเยโฮวาห์ทรงเจิมตั้งไว้ คือที่จะเหยียดมือออกต่อสู้กับท่าน ด้วยว่าท่านเป็นผู้ที่พระเยโฮวาห์ทรงเจิมไว้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 7, 'ดาวิดก็ห้ามผู้รับใช้ของท่านด้วยถ้อยคําเหล่านี้ และไม่ยอมให้เขาทั้งหลายทําร้ายซาอูล และซาอูลก็ทรงลุกขึ้นออกจากถ้ําเสด็จไปตามทางของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 8, 'ภายหลังดาวิดก็ลุกขึ้นด้วย และออกไปจากถ้ําร้องทูลซาอูลว่า “ข้าแต่กษัตริย์เจ้านายของข้าพระองค์” และเมื่อซาอูลทรงเหลียวดู ดาวิดก็ก้มลงถึงดินกราบไหว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 9, 'และดาวิดทูลซาอูลว่า “ไฉนพระองค์ทรงฟังถ้อยคําของคนที่กล่าวว่า ‘ดูเถิด ดาวิดแสวงหาที่จะทําร้ายพระองค์’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 10, 'ดูเถิด วันนี้พระเนตรของพระองค์ประจักษ์แล้วว่า พระเยโฮวาห์ทรงมอบพระองค์ในวันนี้ไว้ในมือของข้าพระองค์ที่ในถ้ํา และบางคนได้ขอให้ข้าพระองค์ประหารพระองค์เสีย แต่ข้าพระองค์ก็ได้ไว้พระชนม์ของพระองค์ ข้าพระองค์พูดว่า ‘ข้าพเจ้าจะไม่ยื่นมือออกทําร้ายเจ้านายของข้าพเจ้า เพราะพระองค์เป็นผู้ที่พระเยโฮวาห์ทรงเจิมไว้’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 11, 'ยิ่งกว่านั้นเสด็จพ่อของข้าพระองค์ขอได้ดูชายฉลองพระองค์ในมือของข้าพระองค์ โดยเหตุที่ว่าข้าพระองค์ได้ตัดชายฉลองพระองค์ออก และมิได้ประหารพระองค์เสีย ขอพระองค์ทรงทราบและทรงเห็นเถิดว่า ในมือของข้าพระองค์ไม่มีความชั่วร้ายหรือการละเมิด ข้าพระองค์มิได้กระทําบาปต่อพระองค์ แม้ว่าพระองค์จะล่าชีวิตของข้าพระองค์เพื่อจะเอาชีวิตข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 12, 'ขอพระเยโฮวาห์ทรงพิพากษาระหว่างข้าพระองค์และพระองค์ ขอพระเยโฮวาห์ทรงแก้แค้นแทนข้าพระองค์ต่อพระองค์ แต่มือของข้าพระองค์จะไม่กระทําอะไรต่อพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 13, 'ดังสุภาษิตของคนในสมัยโบราณว่า ‘ความชั่วร้ายก็ออกมาจากคนชั่ว’ แต่มือของข้าพระองค์จะไม่กระทําอะไรต่อพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 14, 'กษัตริย์แห่งอิสราเอลออกมาตามผู้ใด พระองค์ไล่ตามผู้ใด ไล่ตามสุนัขที่ตายแล้ว ไล่ตามตัวหมัด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 15, 'เพราะฉะนั้นขอพระเยโฮวาห์ทรงเป็นผู้พิพากษา และขอทรงประทานคําพิพากษาระหว่างข้าพระองค์และพระองค์ และทอดพระเนตร และขอว่าความฝ่ายข้าพระองค์ และขอทรงช่วยข้าพระองค์ให้พ้นหัตถ์ของพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 16, 'อยู่มาเมื่อดาวิดทูลคําเหล่านี้ต่อซาอูลแล้ว ซาอูลตรัสว่า “ดาวิดบุตรของข้าเอ๋ย นั่นเป็นเสียงของเจ้าหรือ” ซาอูลก็ทรงส่งเสียงกันแสง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 17, 'พระองค์ตรัสกับดาวิดว่า “เจ้าชอบธรรมยิ่งกว่าข้า เพราะเจ้าตอบแทนข้าด้วยความดี ในเมื่อข้าได้ตอบแทนเจ้าด้วยความร้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 18, 'เจ้าได้ประกาศในวันนี้แล้วว่า เจ้าได้กระทําความดีต่อข้าอย่างไร ในการที่เจ้ามิได้ประหารข้าเสียในเมื่อพระเยโฮวาห์ทรงมอบข้าไว้ในมือของเจ้าแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 19, 'เพราะถ้าผู้ใดพบศัตรูของตน เขาจะยอมให้ปลอดภัยไปหรือ ดังนั้นขอพระเยโฮวาห์ทรงกระทําดีแก่เจ้าสนองการที่เจ้าได้กระทําแก่ข้าในวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 20, 'บัดนี้ ดูเถิด ข้าประจักษ์แล้วว่า เจ้าจะเป็นกษัตริย์แน่ และราชอาณาจักรอิสราเอลจะสถาปนาอยู่ในมือของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 21, 'เพราะฉะนั้นบัดนี้จงปฏิญาณให้แก่ข้าในพระนามของพระเยโฮวาห์ว่า เจ้าจะไม่ตัดเชื้อสายรุ่นหลังของข้าเสีย และเจ้าจะไม่ทําลายชื่อของข้าเสียจากวงศ์วานบิดาของข้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 22, 'ดาวิดก็ปฏิญาณให้แก่ซาอูล แล้วซาอูลก็เสด็จกลับพระราชวัง และดาวิดกับคนของท่านก็ขึ้นไปยังที่กําบังเข้มแข็ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 1, 'ฝ่ายซามูเอลก็สิ้นชีวิตและคนอิสราเอลทั้งปวงก็ประชุมกันไว้ทุกข์ให้ท่าน และเขาทั้งหลายก็ฝังศพท่านไว้ในบ้านของท่านที่รามาห์ และดาวิดก็ลุกขึ้นลงไปยังถิ่นทุรกันดารปาราน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 2, 'มีชายคนหนึ่งในมาโอน มีการงานอยู่ในคารเมล ชายผู้นั้นมั่งมีมาก มีแกะสามพันและแพะหนึ่งพัน ท่านตัดขนแกะของท่านอยู่ที่คารเมล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 3, 'ชื่อของชายคนนั้นคือนาบาล และชื่อภรรยาของท่านคืออาบีกายิล นางมีความเข้าใจเรื่องต่างๆ เป็นอย่างดีและมีหน้าตาสวยงาม แต่ชายคนนั้นมีความประพฤติชั่วช้าเลวทราม เป็นวงศ์วานของคาเลบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 4, 'ดาวิดอยู่ในถิ่นทุรกันดารได้ยินว่านาบาลกําลังตัดขนแกะของเขาอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 5, 'ดาวิดจึงใช้ชายหนุ่มสิบคน และดาวิดสั่งชายหนุ่มเหล่านั้นว่า “จงขึ้นไปที่คารเมลไปหานาบาล และคํานับเขาในนามของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 6, 'ท่านทั้งหลายจงกล่าวคําคํานับเขาเช่นนี้ว่า ‘สันติภาพจงมีแก่ท่าน สันติภาพจงมีแก่วงศ์วานของท่าน และสันติภาพจงมีแก่บรรดาสิ่งที่ท่านมี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 7, 'ข้าพเจ้าได้ยินว่าท่านมีคนตัดขนแกะ ฝ่ายผู้เลี้ยงแกะของท่านนั้นอยู่กับเรา เรามิได้กระทําอันตรายเขาเลย และเขาก็มิได้ขาดอะไรไปตลอดเวลาที่เขาอยู่ในคารเมล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 8, 'ขอให้ถามพวกคนหนุ่มของท่าน ดูเถิด เขาทั้งหลายจะสําแดงให้ท่านทราบเอง เพราะฉะนั้นขอให้คนหนุ่มทั้งหลายของข้าพเจ้าได้รับความกรุณาในสายตาของท่าน เพราะเรามาในวันดี ข้าพเจ้าขอร้องท่านโปรดให้สิ่งที่ตกมาถึงมือของท่านแก่พวกผู้รับใช้ของท่านและแก่ดาวิดบุตรของท่าน’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 9, 'เมื่อพวกคนหนุ่มของดาวิดมาถึงก็กล่าวบรรดาคําเหล่านั้นแก่นาบาลในนามของดาวิด และเขาทั้งหลายก็คอยอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 10, 'และนาบาลตอบคนรับใช้ของดาวิดว่า “ดาวิดคือผู้ใด บุตรของเจสซีคือผู้ใด สมัยนี้มีคนใช้เป็นอันมากที่หนีไปจากนายของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 11, 'ควรหรือที่ข้าจะนําขนมปังของข้า และน้ําของข้า และเนื้อของข้า ซึ่งข้าได้ฆ่าเสียสําหรับคนตัดขนแกะของข้า มอบให้แก่คนซึ่งมาจากที่ไหนข้าก็ไม่รู้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 12, 'พวกคนหนุ่มของดาวิดก็หันกลับ และมาบอกเรื่องราวทั้งสิ้นนี้แก่ดาวิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 13, 'และดาวิดสั่งคนของท่านว่า “ทุกคนจงเอาดาบคาดเอวไว้” และทุกคนก็เอาดาบคาดเอวของตน และดาวิดก็เอาดาบคาดเอวด้วย และมีคนติดตามดาวิดไปประมาณสี่ร้อยคน ส่วนอีกสองร้อยคนอยู่เฝ้ากองสัมภาระ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 14, 'แต่มีคนหนุ่มคนหนึ่งไปบอกนางอาบีกายิลภรรยาของนาบาลว่า “ดูเถิด ดาวิดส่งผู้สื่อสารมาจากถิ่นทุรกันดารเพื่อจะคํานับนายของเรา และนายกลับดุว่าคนเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 15, 'แต่คนเหล่านั้นเคยดีต่อเรามาก และเราไม่ต้องถูกทําร้ายอย่างใดเลย และไม่ขาดสิ่งไรตราบใดที่เราไปกับเขาเมื่อเราอยู่ในทุ่งนา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 16, 'เขาเป็นเหมือนกําแพงของเราทั้งกลางคืนและกลางวัน ตลอดเวลาที่เราเลี้ยงแกะอยู่กับเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 17, 'ฉะนั้นบัดนี้ขอท่านทราบเรื่องนี้และพิจารณาว่าท่านควรจะกระทําประการใด เพราะเขาคงมุ่งร้ายต่อนายของเรา และต่อครัวเรือนทั้งสิ้นของนาย นายนั้นเป็นลูกของเบลีอัล ใครจะพูดด้วยก็ไม่ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 18, 'แล้วนางอาบีกายิลก็รีบจัดขนมปังสองร้อยก้อน และน้ําองุ่นสองถุงหนัง และแกะที่ทําเสร็จแล้วห้าตัว และข้าวคั่วห้าถัง และองุ่นแห้งร้อยช่อ และขนมมะเดื่อสองร้อยแผ่นบรรทุกหลังลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 19, 'นางก็สั่งคนรับใช้ของนางว่า “จงรีบไปก่อนเรา ดูเถิด เราจะตามเจ้าไป” แต่นางมิได้บอกนาบาลสามีของนาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 20, 'เมื่อนางขี่ลาลงมา มีสันเขาบังฝ่ายนางอยู่ ดูเถิด ดาวิดกับคนของท่านก็ลงมาทางนาง และนางก็พบเขาทั้งหลายเข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 21, 'ดาวิดกล่าวไว้แล้วว่า “ข้าได้เฝ้าทุกสิ่งที่คนนี้มีอยู่ในถิ่นทุรกันดารเสียเปล่า ไม่มีสิ่งใดของเขาขาดไปเลย และเขายังกระทําความชั่วต่อข้าตอบแทนความดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 22, 'ถ้าถึงแสงอรุณของรุ่งเช้าข้ายังปล่อยให้คนใดที่ปัสสาวะรดกําแพงได้ในบรรดาคนของเขานั้นให้เหลืออยู่ ก็ขอพระเจ้าทรงลงโทษศัตรูทั้งหลายของดาวิดอย่างนั้น และให้หนักยิ่งกว่านั้นอีก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 23, 'เมื่อนางอาบีกายิลเห็นดาวิด นางก็รีบลงจากหลังลา ซบหน้าลงต่อดาวิดกราบลงถึงดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 24, 'นางกราบลงที่เท้าของดาวิดกล่าวว่า “เจ้านายของดิฉันเจ้าข้า ความชั่วช้านั้นอยู่ที่ดิฉันแต่ผู้เดียว ขอให้หญิงผู้รับใช้ของท่านได้พูดให้ท่านฟัง ขอท่านได้โปรดฟังเสียงหญิงผู้รับใช้ของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 25, 'ขอเจ้านายของดิฉันอย่าได้เอาความกับคนของเบลีอัลคนนี้เลยคือนาบาล เพราะเขาเป็นอย่างที่ชื่อของเขาบอก นาบาลเป็นชื่อของเขา และความโง่เขลาก็อยู่กับเขา แต่ดิฉันหญิงผู้รับใช้ของท่านหาได้เห็นพวกคนหนุ่มของเจ้านายซึ่งท่านได้ใช้ไปนั้นไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 26, 'เหตุฉะนั้นบัดนี้เจ้านายของดิฉัน พระเยโฮวาห์ทรงพระชนม์อยู่แน่ฉันใด และท่านมีชีวิตอยู่แน่ฉันใด ด้วยว่าพระเยโฮวาห์ทรงกระทําให้ท่านระงับเสียจากการทําให้โลหิตตก และจากการแก้แค้นด้วยมือของท่านเอง เพราะฉะนั้นขอให้ศัตรูของท่านและบรรดาผู้ที่กระทําร้ายต่อเจ้านายของดิฉันจงเป็นอย่างนาบาล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 27, 'ของกํานัลเหล่านี้ซึ่งหญิงผู้รับใช้ของท่านได้นํามาให้เจ้านายของดิฉันขอมอบแก่บรรดาคนหนุ่ม ซึ่งติดตามเจ้านายของดิฉัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 28, 'ได้โปรดอภัยการละเมิดของหญิงผู้รับใช้ของท่านเถิด เพราะพระเยโฮวาห์จะทรงกระทําให้เจ้านายของดิฉันเป็นวงศ์วานที่มั่นคงอย่างแน่นอน ด้วยว่าเจ้านายของดิฉันทําสงครามอยู่ฝ่ายพระเยโฮวาห์ ตราบใดที่ท่านมีชีวิตอยู่จะหาความชั่วที่ตัวท่านไม่ได้เลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 29, 'แม้มีคนลุกขึ้นไล่ตามท่านและแสวงหาชีวิตของท่าน ชีวิตของเจ้านายของดิฉันจะผูกมัดอยู่กับกลุ่มชีวิตซึ่งอยู่ในพระเยโฮวาห์พระเจ้าของท่าน แต่ชีวิตศัตรูของท่านจะถูกเหวี่ยงออกไปดั่งออกไปจากรังสลิง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 30, 'และต่อมาเมื่อพระเยโฮวาห์จะทรงกระทําแก่เจ้านายของดิฉันแล้ว ตามบรรดาความดีซึ่งพระองค์ทรงลั่นวาจาเกี่ยวกับท่าน และทรงตั้งท่านไว้เป็นเจ้านายเหนืออิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 31, 'เจ้านายของดิฉันจะไม่มีเหตุที่ต้องเศร้าใจหรือระกําใจ เพราะได้กระทําให้โลหิตเขาตกด้วยไม่มีสาเหตุ หรือเพราะเจ้านายของดิฉันทําการแก้แค้นเสียเอง และเมื่อพระเยโฮวาห์ทรงกระทําความดีแก่เจ้านายของดิฉันแล้ว ก็ขอระลึกถึงหญิงผู้รับใช้ของท่านบ้าง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 32, 'ดาวิดจึงกล่าวแก่อาบีกายิลว่า “สาธุการแด่พระเยโฮวาห์พระเจ้าแห่งอิสราเอล ผู้ทรงใช้เจ้าให้มาพบเราในวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 33, 'ขอให้ความสุขุมของเจ้ารับพระพร และขอให้ตัวเจ้าได้รับพระพร เพราะเจ้าได้ป้องกันเราในวันนี้ให้พ้นจากการทําให้โลหิตตก และจากการแก้แค้นด้วยมือของเราเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 34, 'เพราะพระเยโฮวาห์พระเจ้าแห่งอิสราเอล ผู้ทรงระงับเราเสียจากการกระทําร้ายเจ้า ทรงพระชนม์อยู่แน่ฉันใด ถ้าเจ้ามิได้รีบมาพบเราเสีย เมื่อถึงแสงอรุณของรุ่งเช้าจะไม่มีคนที่ปัสสาวะรดกําแพงได้เหลือแก่นาบาลเลยเป็นแน่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 35, 'แล้วดาวิดก็รับบรรดาสิ่งที่นางนํามาจากมือของนาง และดาวิดกล่าวแก่นางว่า “จงกลับไปยังบ้านเรือนของเจ้าด้วยสันติภาพเถิด ดูเถิด เราได้ฟังเสียงของเจ้าแล้ว และเราก็ยอมรับเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 36, 'และอาบีกายิลก็กลับไปหานาบาล และดูเถิด ท่านกําลังมีการเลี้ยงใหญ่ในบ้านของท่านอย่างการเลี้ยงของกษัตริย์ และจิตใจของนาบาลก็ร่าเริงอยู่ เพราะท่านมึนเมามาก นางจึงมิได้บอกอะไรให้ท่านทราบ ไม่ว่ามากหรือน้อย จนเวลารุ่งเช้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 37, 'และต่อมาในเวลาเช้า เมื่อเหล้าองุ่นสร่างจากนาบาลไปแล้ว ภรรยาของท่านก็เล่าเหตุการณ์เหล่านี้ให้ฟัง และจิตใจของท่านก็ตายเสียภายใน และท่านกลายเป็นดังก้อนหิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 38, 'อยู่มาอีกประมาณสิบวันพระเยโฮวาห์ทรงประหารนาบาลและท่านก็สิ้นชีวิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 39, 'เมื่อดาวิดได้ยินว่านาบาลสิ้นชีวิตแล้ว ท่านจึงว่า “สาธุการแด่พระเยโฮวาห์ ผู้ทรงแก้แค้นการเหยียดหยามที่ข้าพระองค์ได้รับจากมือของนาบาล และทรงป้องกันผู้รับใช้ของพระองค์ไม่ให้ทําความชั่ว พระเยโฮวาห์ทรงตอบแทนการกระทําชั่วของนาบาลให้ตกบนศีรษะของเขาเอง” แล้วดาวิดก็ส่งคนไปสู่ขออาบีกายิลให้มาเป็นภรรยาของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 40, 'และเมื่อผู้รับใช้ของดาวิดมาถึงอาบีกายิลที่คารเมล เขาทั้งหลายก็พูดกับนางว่า “ดาวิดได้ให้เราทั้งหลายมานําเธอไปให้เป็นภรรยาของท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 41, 'และนางก็ลุกขึ้นซบหน้าลงถึงดินกล่าวว่า “ดูเถิด หญิงผู้รับใช้ของท่านเป็นผู้รับใช้ที่จะล้างเท้าให้แก่ผู้รับใช้แห่งเจ้านายของดิฉัน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 42, 'อาบีกายิลก็รีบลุกขึ้นขี่ลาตัวหนึ่งพร้อมกับสาวใช้ปรนนิบัติเธออีกห้าคน นางตามผู้สื่อสารของดาวิดไป และได้เป็นภรรยาของดาวิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 43, 'ดาวิดยังได้รับนางอาหิโนอัมชาวยิสเรเอลมาด้วย และทั้งสองก็เป็นภรรยาของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 44, 'ซาอูลได้ทรงยกมีคาลราชธิดาของพระองค์ ผู้เป็นภรรยาของดาวิด ให้แก่ปัลทีบุตรชายลาอิชชาวกัลลิมแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 1, 'ชาวศิฟมาหาซาอูลที่เมืองกิเบอาห์ทูลว่า “ดาวิดซ่อนตัวอยู่บนเขาฮาคีลาห์ ซึ่งอยู่ตรงหน้าเยชิโมนมิใช่หรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 2, 'ซาอูลจึงทรงลุกขึ้นลงไปที่ถิ่นทุรกันดารศิฟ พร้อมกับชายอิสราเอลที่คัดเลือกแล้วสามพันคน เพื่อแสวงหาดาวิดในถิ่นทุรกันดารศิฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 3, 'และซาอูลทรงตั้งค่ายอยู่ที่เขาฮาคีลาห์ ซึ่งอยู่ข้างถนนซึ่งอยู่ตรงหน้าเยชิโมน แต่ดาวิดยังคงอยู่ในถิ่นทุรกันดาร และท่านเห็นว่าซาอูลเสด็จมาหาท่านที่ในถิ่นทุรกันดาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 4, 'เพราะฉะนั้นดาวิดส่งผู้สอดแนมออกไป จึงทราบว่าซาอูลทรงยกมาแน่แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 5, 'แล้วดาวิดก็ลุกขึ้นมายังที่ซึ่งซาอูลทรงตั้งค่ายอยู่ และดาวิดก็เห็นที่ที่ซาอูลบรรทมพร้อมกับอับเนอร์บุตรชายเนอร์แม่ทัพ ซาอูลบรรทมอยู่กลางเขตค่าย ฝ่ายกองทัพก็ตั้งค่ายอยู่รอบพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 6, 'แล้วดาวิดก็พูดกับอาหิเมเลคคนฮิตไทต์ และกับอาบีชัยบุตรชายของนางเศรุยาห์ น้องชายของโยอาบว่า “ผู้ใดจะลงไปในค่ายของซาอูลกับเราบ้าง” อาบีชัยตอบว่า “ข้าพเจ้าจะลงไปกับท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 7, 'ดาวิดและอาบีชัยจึงลงไปที่กองทัพในเวลากลางคืน และดูเถิด ซาอูลบรรทมอยู่กลางเขตค่าย หอกของพระองค์ปักอยู่ที่ที่ดินตรงพระเศียร อับเนอร์กับพวกพลก็นอนล้อมพระองค์อยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 8, 'อาบีชัยพูดกับดาวิดว่า “ในวันนี้พระเจ้าทรงมอบศัตรูของท่านไว้ในมือของท่านแล้ว ฉะนั้นบัดนี้ขอให้ข้าพเจ้าแทงเขาด้วยหอกให้ติดดิน ครั้งเดียวก็พอ และข้าพเจ้าไม่ต้องแทงเขาครั้งที่สอง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 9, 'แต่ดาวิดบอกอาบีชัยว่า “ขออย่าทําลายพระองค์เลย เพราะผู้ใดเล่าจะเหยียดมือออกต่อสู้ผู้ซึ่งพระเยโฮวาห์ทรงเจิมไว้ และจะไม่มีความผิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 10, 'และดาวิดกล่าวว่า “พระเยโฮวาห์ทรงพระชนม์อยู่แน่ฉันใด พระเยโฮวาห์จะทรงฆ่าพระองค์ท่านเอง หรือจะถึงวันกําหนดที่พระองค์ต้องสิ้นพระชนม์ หรือพระองค์จะเสด็จเข้าสงครามและพินาศเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 11, 'ขอพระเยโฮวาห์ทรงห้ามปรามข้าพเจ้าไม่ให้เหยียดมือออกต่อสู้ผู้ที่พระเยโฮวาห์ทรงเจิมไว้ บัดนี้จงเอาหอกที่อยู่ตรงพระเศียรกับเหยือกน้ํา และให้เราไปกันเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 12, 'ดาวิดจึงเอาหอกและเหยือกน้ําจากที่พระเศียรของซาอูล และเขาทั้งสองก็ออกไป ไม่มีใครเห็น ไม่มีใครทราบ และไม่มีคนใดตื่น เพราะเขาหลับสนิททุกคน เพราะพระเยโฮวาห์ทรงบันดาลให้เขาหลับสนิท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 13, 'และดาวิดก็ข้ามไปอีกฟากหนึ่งไปยืนอยู่บนยอดเขาไกลออกไป มีที่ว่างกว้างใหญ่ระหว่างทั้งสองฝ่าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 14, 'ดาวิดก็ตะโกนเรียกพวกพลและเรียกอับเนอร์บุตรชายเนอร์ว่า “อับเนอร์เอ๋ย ท่านไม่ตอบหรือ” แล้วอับเนอร์ตอบว่า “ใครนั่นที่มาร้องเรียกกษัตริย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 15, 'และดาวิดตอบอับเนอร์ว่า “ท่านไม่ใช่ผู้ชายแกล้วกล้าดอกหรือ ในอิสราเอลมีใครเหมือนท่านบ้าง ทําไมท่านไม่เฝ้ากษัตริย์เจ้านายของท่านไว้ให้ดี เพราะมีคนหนึ่งเข้าไปจะทําลายกษัตริย์เจ้านายของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 16, 'ที่ท่านกระทําเช่นนี้ไม่ดีแน่ พระเยโฮวาห์ทรงพระชนม์อยู่แน่ฉันใด ท่านสมควรตายเพราะท่านมิได้เฝ้าเจ้านายของท่านไว้ให้ดี ผู้ที่พระเยโฮวาห์ทรงเจิมไว้ บัดนี้ตรวจดูทีว่า หอกของกษัตริย์อยู่ที่ไหน และเหยือกน้ําที่ตรงพระเศียรนั้นอยู่ที่ไหน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 17, 'ซาอูลทรงจําสําเนียงดาวิดได้จึงตรัสว่า “ดาวิดบุตรของข้าเอ๋ย นี่เป็นเสียงของเจ้าหรือ” และดาวิดทูลว่า “โอ ข้าแต่กษัตริย์ เจ้านายของข้าพระองค์ เป็นเสียงข้าพระองค์พ่ะย่ะค่ะ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 18, 'และท่านทูลต่อไปว่า “ไฉนเจ้านายของข้าพระองค์จึงไล่ตามผู้รับใช้ของพระองค์ ข้าพระองค์ได้กระทําอะไรไป มือข้าพระองค์ผิดอย่างไรเล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 19, 'เพราะฉะนั้นบัดนี้ขอกษัตริย์เจ้านายของข้าพระองค์ทรงฟังเสียงผู้รับใช้ของพระองค์ ถ้าพระเยโฮวาห์ทรงปลุกปั่นพระองค์ให้ต่อสู้ข้าพระองค์ ขอพระเยโฮวาห์ให้ได้รับเครื่องถวาย แต่ถ้าเป็นบุตรทั้งหลายของมนุษย์ยุก็ขอให้คนนั้นเป็นที่สาปแช่งต่อพระพักตร์พระเยโฮวาห์ เพราะเขาได้ขับไล่ข้าพระองค์ออกไปในวันนี้มิให้ได้ส่วนมรดกของพระเยโฮวาห์ โดยกล่าวว่า ‘จงไปปรนนิบัติพระอื่น’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 20, 'เพราะฉะนั้นบัดนี้ ขออย่าให้โลหิตของข้าพระองค์ตกถึงดินต่อพระพักตร์พระเยโฮวาห์ เพราะกษัตริย์แห่งอิสราเอลได้ออกมาหาชีวิตหมัดตัวเดียว ดังผู้หนึ่งไล่ตามนกกระทาอยู่บนภูเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 21, 'แล้วซาอูลตรัสว่า “ข้าได้กระทําบาปแล้ว ดาวิดบุตรของเราเอ๋ย จงกลับไปเถิด ด้วยว่าเราจะไม่ทําร้ายเจ้าอีกต่อไป เพราะในวันนี้ชีวิตของเราก็ประเสริฐในสายตาของเจ้า ดูเถิด เราประพฤติตัวเป็นคนเขลาและได้กระทําผิดอย่างเหลือหลาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 22, 'และดาวิดทูลว่า “ข้าแต่กษัตริย์ ดูเถิด หอกของกษัตริย์อยู่ที่นี่ ขอรับสั่งให้คนหนุ่มคนหนึ่งมารับไปจากที่นี่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 23, 'พระเยโฮวาห์ทรงประทานรางวัลแก่ทุกคนตามความชอบธรรมและความสัตย์ซื่อของเขา เพราะในวันนี้พระเยโฮวาห์ทรงมอบพระองค์ไว้ในมือของข้าพระองค์แล้ว แต่ข้าพระองค์มิได้เหยียดมือออกต่อสู้ผู้ที่พระเยโฮวาห์ทรงเจิมไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 24, 'ดูเถิด ชีวิตของพระองค์นั้นประเสริฐในสายตาของข้าพระองค์ในวันนี้ฉันใด ก็ขอให้ชีวิตของข้าพระองค์ประเสริฐในสายพระเนตรของพระเยโฮวาห์ฉันนั้น และขอพระองค์ทรงช่วยข้าพระองค์ให้พ้นจากบรรดาความทุกข์ลําบากทั้งสิ้นด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 25, 'แล้วซาอูลจึงตรัสกับดาวิดว่า “ดาวิดบุตรของเราเอ๋ย ขอพระเจ้าทรงอวยพรเจ้า เจ้าจะกระทําสิ่งที่ยิ่งใหญ่และจะสําเร็จแน่” ดาวิดจึงไปตามทางของท่าน และซาอูลก็เสด็จกลับสู่ราชสํานักของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 1, 'ดาวิดนึกในใจว่า “ข้าคงจะพินาศสักวันหนึ่งด้วยมือของซาอูล ไม่มีสิ่งใดดีกว่าที่ข้าจะหนีไปอยู่ที่แผ่นดินคนฟีลิสเตีย แล้วซาอูลก็จะทรงเลิกไม่ติดตามข้าอีกภายในพรมแดนอิสราเอล และข้าจะรอดพ้นจากมือของท่านได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 2, 'ดาวิดจึงลุกขึ้นยกข้ามไป ทั้งตัวท่านและคนที่อยู่กับท่านหกร้อยคนด้วยกัน ไปหาอาคีชบุตรชายมาโอค กษัตริย์เมืองกัท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 3, 'และดาวิดก็อาศัยอยู่กับอาคีชที่เมืองกัท คือตัวท่านและคนของท่าน ทุกคนมีครัวเรือนไปด้วย ทั้งดาวิดพร้อมกับภรรยาสองคน คืออาหิโนอัมชาวยิสเรเอล และอาบีกายิลชาวคารเมลภรรยาของนาบาล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 4, 'และเมื่อมีคนไปทูลซาอูลว่า ดาวิดได้หนีไปเมืองกัทแล้ว พระองค์ก็มิได้แสวงหาท่านอีกต่อไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 5, 'แล้วดาวิดจึงทูลอาคีชว่า “ถ้าบัดนี้ข้าพระองค์ได้รับพระกรุณาในสายพระเนตรของพระองค์ ขอทรงให้เขามอบที่ในหัวเมืองแก่ข้าพระองค์สักแห่งหนึ่ง เพื่อข้าพระองค์จะได้อาศัยอยู่ที่นั่น ไฉนผู้รับใช้ของพระองค์จะอยู่ในราชธานีกับพระองค์เล่า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 6, 'ในวันนั้นอาคีชทรงมอบเมืองศิกลากให้ ศิกลากจึงเป็นหัวเมืองขึ้นแก่กษัตริย์ยูดาห์จนถึงทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 7, 'ระยะเวลาที่ดาวิดอาศัยอยู่ในแผ่นดินฟีลิสเตียนั้นเป็นหนึ่งปีกับสี่เดือน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 8, 'ฝ่ายดาวิดกับคนของท่านก็ขึ้นไปปล้นชาวเกชูร์ คนเกซไรต์และคนอามาเลข เพราะประชาชาติเหล่านี้เป็นชาวแผ่นดินนั้นตั้งแต่สมัยโบราณ ไกลไปจนถึงเมืองชูร์ถึงแผ่นดินอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 9, 'ดาวิดก็โจมตีแผ่นดินนั้น ไม่ไว้ชีวิตผู้ชายหรือผู้หญิง แต่ริบแกะ วัว ลา อูฐ และเสื้อผ้า แล้วกลับมาหาอาคีช');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 10, 'อาคีชถามว่า “วันนี้ท่านไปปล้นผู้ใดมา” ดาวิดก็ทูลว่า “ปล้นถิ่นใต้ที่แผ่นดินยูดาห์ ปล้นถิ่นใต้ที่คนเยราเมเอล และปล้นถิ่นใต้คนเคไนต์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 11, 'ดาวิดมิได้ไว้ชีวิตผู้ชายหรือผู้หญิง ที่จะนําข่าวมาที่เมืองกัทโดยคิดว่า “เกรงว่าเขาจะบอกเรื่องของเราและกล่าวว่า ‘ดาวิดได้ทําอย่างนั้นๆ และนี่จะเป็นวิธีการขณะที่ท่านอาศัยอยู่ในแผ่นดินฟีลิสเตีย’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 12, 'อาคีชทรงวางพระทัยในดาวิดด้วยทรงดําริว่า “เขาได้กระทําให้อิสราเอลชนชาติของเขาเกลียดอย่างที่สุด เพราะฉะนั้นเขาจึงเป็นผู้รับใช้ของเราได้ตลอดไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 1, 'อยู่มาในครั้งนั้นคนฟีลิสเตียได้รวบรวมกําลังเพื่อทําสงครามสู้รบกับอิสราเอล และอาคีชตรัสกับดาวิดว่า “จงเข้าใจเถิดว่า ท่านกับคนของท่านจะออกทัพไปกับเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 2, 'ดาวิดทูลอาคีชว่า “ดีทีเดียวพ่ะย่ะค่ะ พระองค์จะได้ทราบว่าผู้รับใช้ของพระองค์จะกระทําอะไรได้บ้าง” และอาคีชรับสั่งกับดาวิดว่า “ดีแล้ว เราจะให้ท่านเป็นองครักษ์ของเราตลอดชีพ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 3, 'ฝ่ายซามูเอลได้สิ้นชีพแล้ว และคนอิสราเอลทั้งปวงก็ไว้ทุกข์ให้ท่าน และฝังศพท่านไว้ในเมืองรามาห์ ซึ่งเป็นเมืองของท่านเอง และซาอูลทรงกําจัดคนทรงและพ่อมดแม่มดเสียจากแผ่นดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 4, 'คนฟีลิสเตียก็ชุมนุมกันและมาตั้งค่ายอยู่ที่ชูเนม และซาอูลทรงรวบรวมอิสราเอลทั้งสิ้นและเขาทั้งหลายตั้งค่ายอยู่ที่กิลโบอา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 5, 'เมื่อซาอูลทอดพระเนตรกองทัพของคนฟีลิสเตียก็กลัว และพระทัยของพระองค์ก็หวั่นไหวมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 6, 'และเมื่อซาอูลทูลถามพระเยโฮวาห์ พระเยโฮวาห์มิได้ทรงตอบพระองค์ ไม่ว่าด้วยความฝัน หรือด้วยอูริม หรือด้วยผู้พยากรณ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 7, 'ซาอูลจึงรับสั่งกับมหาดเล็กของพระองค์ว่า “จงออกไปหาหญิงที่เป็นคนทรง เพื่อเราจะได้ไปหาและถามเขาดู” และมหาดเล็กก็กราบทูลว่า “ดูเถิด มีหญิงคนทรงคนหนึ่งอยู่ที่บ้านเอนโดร์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 8, 'ซาอูลจึงปลอมพระองค์และทรงฉลองพระองค์อย่างอื่นเสด็จออกไปพร้อมกับชายสองคนไปหาหญิงคนทรงในเวลากลางคืน พระองค์ตรัสว่า “ขอทํานายให้ฉันโดยวิญญาณของคนตาย ฉันจะออกชื่อผู้ใดก็ให้เรียกผู้นั้นขึ้นมา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 9, 'หญิงคนนั้นจึงทูลตอบพระองค์ว่า “ดูเถิด ท่านทราบแล้วว่าซาอูลทรงกระทําอะไร ที่ได้ขจัดคนทรงและพ่อมดแม่มดเสียจากแผ่นดิน ทําไมท่านจึงมาวางกับดักชีวิตของข้าพเจ้าเล่า เพื่อทําให้ข้าพเจ้าถูกประหาร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 10, 'แต่ซาอูลทรงปฏิญาณกับหญิงนั้นในพระนามของพระเยโฮวาห์ว่า “พระเยโฮวาห์ทรงพระชนม์อยู่แน่ฉันใด เจ้าจะไม่ถูกโทษเพราะเรื่องนี้แน่ฉันนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 11, 'หญิงนั้นจึงทูลถามว่า “ท่านจะให้ข้าพเจ้าเรียกใครขึ้นมา” ซาอูลตรัสว่า “เรียกซามูเอลขึ้นมาให้ฉัน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 12, 'และเมื่อหญิงคนนั้นเห็นซามูเอล จึงร้องเสียงดัง และหญิงนั้นกราบทูลซาอูลว่า “ไฉนพระองค์จึงทรงล่อลวงหม่อมฉัน พระองค์คือซาอูล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 13, 'กษัตริย์ตรัสแก่นางว่า “อย่ากลัวเลย เจ้าได้เห็นอะไร” และหญิงนั้นกราบทูลซาอูลว่า “หม่อมฉันเห็นเทพยเจ้าองค์หนึ่งเสด็จขึ้นมาจากแผ่นดิน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 14, 'พระองค์ถามนางว่า “รูปร่างของเขาเป็นอย่างไร” และนางตอบว่า “เป็นผู้ชายแก่ขึ้นมา มีเสื้อคลุมกายอยู่” ซาอูลก็ทรงเข้าใจว่าเป็นซามูเอล พระองค์ทรงโน้มพระกายลงถึงดินกราบไหว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 15, 'แล้วซามูเอลพูดกับซาอูลว่า “ท่านรบกวนเราด้วยเรียกเราขึ้นมาทําไม” ซาอูลทรงตอบว่า “ข้าพเจ้ามีความทุกข์หนัก เพราะคนฟีลิสเตียกําลังมาทําสงครามกับข้าพเจ้า และพระเจ้าทรงหันจากข้าพเจ้าเสียแล้ว มิได้ทรงตอบข้าพเจ้าอีกเลย ไม่ว่าโดยผู้พยากรณ์ หรือโดยความฝัน เพราะฉะนั้นข้าพเจ้าจึงขอเรียกท่านขึ้นมาเพื่อท่านจะได้แจ้งว่า ข้าพเจ้าจะกระทําประการใดดี”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 16, 'และซามูเอลตอบว่า “ในเมื่อพระเยโฮวาห์ทรงหันจากท่านเสียแล้ว และเป็นศัตรูของท่าน ท่านจะมาถามข้าพเจ้าทําไมเล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 17, 'พระเยโฮวาห์ได้ทรงกระทําแก่ท่านอย่างที่พระองค์ตรัสบอกทางข้าพเจ้าแล้วนั้น เพราะพระเยโฮวาห์ทรงฉีกราชอาณาจักรนั้นออกเสียจากมือของท่าน และทรงมอบให้แก่คนใกล้เคียง คือดาวิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 18, 'เพราะท่านมิได้เชื่อฟังพระสุรเสียงของพระเยโฮวาห์ มิได้กระทําตามพระพิโรธของพระองค์ที่ทรงมีต่ออามาเลข ฉะนั้นพระเยโฮวาห์จึงทรงกระทําสิ่งนี้แก่ท่านในวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 19, 'ยิ่งกว่านั้นอีกพระเยโฮวาห์จะทรงมอบอิสราเอลพร้อมกับตัวท่านไว้ในมือของคนฟีลิสเตีย พรุ่งนี้ตัวท่านพร้อมกับบุตรชายทั้งหลายของท่านจะอยู่กับเรา และพระเยโฮวาห์จะทรงมอบกองทัพอิสราเอลไว้ในมือของคนฟีลิสเตียด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 20, 'แล้วซาอูลก็ทรงล้มลงเหยียดยาวบนพื้นดินในทันที กลัวยิ่งนักเพราะถ้อยคําของซามูเอล และไม่มีกําลังเหลืออยู่ในพระองค์ เพราะไม่ได้เสวยพระกระยาหารมาตลอดวันหนึ่งกับคืนหนึ่งแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 21, 'หญิงนั้นก็เข้ามาหาซาอูล และเมื่อนางเห็นว่าพระองค์ตกพระทัยมาก จึงทูลว่า “ดูเถิด หญิงผู้รับใช้ของพระองค์ก็ยอมเชื่อฟังรับสั่งของพระองค์ ยอมเสี่ยงชีวิต และยอมฟังพระดํารัสที่พระองค์ตรัสสั่งทุกประการ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 22, 'เพราะฉะนั้นบัดนี้ขอพระองค์จงฟังเสียงหญิงผู้รับใช้ของพระองค์บ้าง ขอหม่อมฉันได้ถวายพระกระยาหารต่อพระพักตร์พระองค์สักหน่อยหนึ่ง ขอพระองค์เสวย เพื่อพระองค์จะทรงมีพระกําลังเมื่อกลับตามทางของพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 23, 'พระองค์ก็ทรงปฏิเสธ รับสั่งว่า “ไม่กิน” แต่มหาดเล็กกับหญิงนั้นอ้อนวอนพระองค์ พระองค์ก็ทรงฟังเสียงของเขา พระองค์ทรงลุกขึ้นจากพื้นดินประทับบนเตียง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 24, 'หญิงนั้นมีลูกวัวอ้วนอยู่ในบ้านตัวหนึ่ง ก็รีบฆ่าเสีย เอาแป้งมานวดปิ้งทําขนมปังไร้เชื้อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 25, 'นางก็นํามาถวายแก่ซาอูลและทรงเสวยกับให้มหาดเล็ก เขารับประทาน แล้วก็ทรงลุกขึ้นเสด็จกลับไปในคืนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 1, 'ฝ่ายคนฟีลิสเตียชุมนุมกําลังทั้งสิ้นอยู่ที่อาเฟก และคนอิสราเอลก็ตั้งค่ายอยู่ที่น้ําพุซึ่งอยู่ในเมืองยิสเรเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 2, 'เจ้านายฟีลิสเตียเดินผ่านไปตามกองร้อยและกองพัน แต่ดาวิดกับคนของท่านก็ผ่านไปเป็นกองหลังกับอาคีช');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 3, 'แล้วเจ้านายของคนฟีลิสเตียกล่าวว่า “พวกฮีบรูเหล่านี้มาทําอะไรที่นี่” และอาคีชก็รับสั่งแก่เจ้านายคนฟีลิสเตียว่า “นี่คือดาวิดมหาดเล็กซาอูลกษัตริย์อิสราเอลไม่ใช่หรือ เขาอยู่กับเรามาเป็นวันเป็นปีแล้ว ตั้งแต่วันที่เขาหนีมาหาข้าพเจ้า ข้าพเจ้ายังไม่พบความผิดในตัวเขาเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 4, 'แต่เจ้านายฟีลิสเตียโกรธพระองค์ และเจ้านายฟีลิสเตียทูลพระองค์ว่า “ขอส่งชายคนนั้นกลับไป เพื่อให้เขากลับไปยังที่ที่พระองค์กําหนดให้เขาอยู่ และอย่าให้เขาลงไปรบพร้อมกับเรา เกรงว่าเมื่อเรารบกัน เขาจะเป็นศัตรูของเรา เพราะว่าชายคนนี้จะคืนดีกับเจ้านายของเขาได้อย่างไร มิใช่ด้วยศีรษะของคนที่นี่ดอกหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 5, 'ดาวิดคนนี้มิใช่หรือ ซึ่งเขาร้องรําทําเพลงรับกันว่า ‘ซาอูลฆ่าคนเป็นพันๆและดาวิดฆ่าคนเป็นหมื่นๆ’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 6, 'อาคีชจึงเรียกดาวิดเข้ามารับสั่งแก่ท่านว่า “พระเยโฮวาห์ทรงพระชนม์อยู่แน่ฉันใด ท่านได้ปฏิบัติตนเป็นคนซื่อตรง และในการที่ท่านออกทัพและยกทัพกลับร่วมกับเราก็เป็นที่ประเสริฐในสายตาของเรา เพราะเราไม่เห็นความชั่วร้ายในตัวท่านตั้งแต่วันที่ท่านมาอยู่กับเราจนถึงวันนี้ แต่อย่างไรก็ตามเจ้านายทั้งหลายไม่เห็นชอบในเรื่องท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 7, 'ฉะนั้นขอท่านกลับไปเสีย จงไปอย่างสันติเถิด เพื่อไม่ให้เป็นที่ขัดใจเจ้านายฟีลิสเตียทั้งหลาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 8, 'และดาวิดก็ทูลอาคีชว่า “แต่ข้าพระองค์ได้กระทําสิ่งใด หรือพระองค์ได้พบสิ่งใดในผู้รับใช้ของพระองค์ ตั้งแต่วันที่ข้าพระองค์เข้ามารับราชการจนบัดนี้ว่า ข้าพระองค์ไม่ควรจะไปรบกับศัตรูของกษัตริย์เจ้านายของข้าพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 9, 'อาคีชก็รับสั่งตอบดาวิดว่า “เราทราบแล้วว่าในสายตาของเราท่านดีอย่างทูตสวรรค์องค์หนึ่งของพระเจ้า แต่บรรดาเจ้านายแห่งฟีลิสเตียกล่าวว่า ‘อย่าให้เขาขึ้นไปกับเราในการรบนี้เลย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 10, 'เมื่อเป็นอย่างนี้ ขอท่านลุกขึ้นแต่เช้าพร้อมกับพวกพลแห่งนายของท่าน คือคนที่มากับท่าน เมื่อพวกท่านลุกขึ้นในเวลาเช้ามืด พอมีแสงก็จงออกเดิน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 11, 'ดาวิดกับคนของท่านจึงลุกขึ้นตั้งแต่มืดเพื่อออกเดินในตอนเช้า กลับไปยังแผ่นดินฟีลิสเตีย แต่คนฟีลิสเตียขึ้นไปยังยิสเรเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 1, 'อยู่มาในวันที่สามเมื่อดาวิดกับคนของท่านมาถึงเมืองศิกลากปรากฏว่าคนอามาเลขได้มาปล้นทางภาคใต้กับปล้นศิกลากแล้ว เขาชนะศิกลากและเผาเสียด้วยไฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 2, 'และจับผู้หญิงกับทุกคนที่อยู่ในนั้นไปเป็นเชลยทั้งผู้ใหญ่และเด็ก ไม่ได้ฆ่าผู้ใดเลย แต่กวาดต้อนไปตามทางของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 3, 'เมื่อดาวิดกับคนของท่านมาที่ตัวเมือง ดูเถิด เมืองนั้นถูกเผาด้วยไฟ และภรรยากับบุตรชายบุตรสาวของเขาก็ถูกกวาดไปเป็นเชลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 4, 'แล้วดาวิดกับประชาชนที่อยู่กับท่านก็ร้องไห้เสียงดังจนเขาไม่มีกําลังจะร้องไห้อีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 5, 'อาหิโนอัมชาวยิสเรเอล และอาบีกายิลภรรยาของนาบาลชาวคารเมล ภรรยาทั้งสองของดาวิดก็ถูกกวาดไปเป็นเชลยด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 6, 'และดาวิดก็เป็นทุกข์หนักเพราะประชาชนพูดกันว่าจะขว้างท่านเสียด้วยก้อนหินด้วยจิตใจของประชาชนต่างก็ขมขื่นมาก เพราะบุตรชายและบุตรสาวของเขา แต่ดาวิดก็มีกําลังขึ้นในพระเยโฮวาห์พระเจ้าของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 7, 'ดาวิดจึงพูดกับอาบียาธาร์ปุโรหิตบุตรชายของอาหิเมเลคว่า “ขอนําเอโฟดมาให้ข้าพเจ้า” อาบียาธาร์ก็นําเอโฟดมาให้ดาวิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 8, 'และดาวิดทูลถามพระเยโฮวาห์ว่า “สมควรที่ข้าพระองค์จะติดตามกองปล้นนี้หรือ ข้าพระองค์จะขับทันเขาหรือ” พระองค์ตอบท่านว่า “จงติดตามเถิด เจ้าจะไปทันเขาแน่ และจะเอาสิ่งสารพัดกลับคืนแน่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 9, 'ดาวิดก็ยกออกติดตามพร้อมกับคนที่อยู่กับท่านหกร้อยนั้น และเขามาถึงลําธารเบโสร์ คนที่ล้าหลังก็พักอยู่ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 10, 'แต่ดาวิดติดตามต่อไป ทั้งตัวท่านและคนสี่ร้อย สองร้อยที่อ่อนเพลียเกินที่จะข้ามลําธารเบโสร์ก็หยุดพักอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 11, 'เขาทั้งหลายพบชาวอียิปต์คนหนึ่งอยู่ที่กลางแจ้ง จึงนําเขามาหาดาวิด ให้ขนมปังและเขาก็รับประทานและให้น้ําเขาดื่ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 12, 'และให้ขนมมะเดื่อแผ่นหนึ่งกับช่อองุ่นแห้งสองช่อ เมื่อเขารับประทานแล้ว จิตใจของเขาก็ฟื้นขึ้น เพราะเขาไม่ได้รับประทานขนมปังหรือดื่มน้ํามาสามวันสามคืนแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 13, 'และดาวิดถามเขาว่า “เจ้าเป็นคนพวกไหน และเจ้ามาจากไหน” เขาตอบว่า “ข้าพเจ้าเป็นคนหนุ่มชาวอียิปต์ เป็นคนใช้ของคนอามาเลขคนหนึ่ง เมื่อสามวันมาแล้วข้าพเจ้าป่วย นายข้าพเจ้าจึงทิ้งข้าพเจ้าไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 14, 'เรามาปล้นที่ถิ่นใต้ของคนเคเรธี และปล้นที่ส่วนของยูดาห์ และที่ถิ่นใต้ของคาเลบ และเราเผาเมืองศิกลากเสียด้วยไฟ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 15, 'ดาวิดถามเขาว่า “เจ้าจะพาเราลงไปถึงกองปล้นนี้หรือไม่” เขาตอบว่า “ขอปฏิญาณแก่ข้าพเจ้าในพระนามของพระเจ้าว่า จะไม่ฆ่าข้าพเจ้า และท่านจะไม่มอบข้าพเจ้าไว้ในมือนายของข้าพเจ้า ข้าพเจ้าจึงจะพาท่านไปที่กองปล้นนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 16, 'เมื่อเขาพาท่านลงไปแล้ว ดูเถิด ก็พบเขาทั้งหลายแผ่กันอยู่เต็มดินไปหมด ต่างกินและดื่มและเต้นรําเพราะเขาริบได้ข้าวของมากมายมาจากแผ่นดินฟีลิสเตียและจากแผ่นดินยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 17, 'และดาวิดก็ฆ่าฟันเขาตั้งแต่โพล้เพล้จนถึงเวลาเย็นของวันรุ่งขึ้น ไม่มีชายคนใดหนีรอดไปได้สักคนเดียว เว้นแต่ชายสี่ร้อยคนซึ่งขี่อูฐหนีไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 18, 'ดาวิดได้สิ่งของต่างๆที่คนอามาเลขริบคืนมาทั้งหมด และดาวิดช่วยภรรยาทั้งสองของท่านรอดได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 19, 'ไม่มีอะไรขาดจากท่านไปเลย ไม่ว่าเล็กหรือใหญ่ บุตรชายหรือบุตรสาว ในสิ่งที่ริบไปหรือสิ่งที่เขาเหล่านั้นเอาไป ดาวิดได้คืนมาหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 20, 'ดาวิดยังจับได้บรรดาฝูงแพะแกะฝูงวัว และเขาไล่ต้อนฝูงสัตว์ไปข้างหน้าท่านกล่าวว่า “นี่เป็นส่วนหนึ่งของดาวิดริบมา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 21, 'แล้วดาวิดกลับมายังคนสองร้อยผู้ที่อ่อนเพลียเกินที่จะตามดาวิดไป ซึ่งให้พักอยู่ที่ลําธารเบโสร์ และเขาก็ออกไปต้อนรับดาวิดและต้อนรับประชาชนที่อยู่กับท่าน เมื่อดาวิดเข้ามาใกล้ประชาชน ท่านก็คํานับเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 22, 'คนชั่วและคนของเบลีอัลทั้งสิ้นในพวกพลที่ติดตามดาวิดไปจึงกล่าวว่า “เพราะเขาไม่ไปกับเรา เราจะไม่ให้สิ่งที่เราริบมาได้แก่เขาเลย นอกจากให้ต่างคนมาพาภรรยาและบุตรของเขาไปก็แล้วกัน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 23, 'แต่ดาวิดกล่าวว่า “พี่น้องทั้งหลายของข้าพเจ้าเอ๋ย ท่านอย่าทําอย่างนั้นกับสิ่งซึ่งพระเยโฮวาห์ทรงมอบแก่เรา ผู้ได้ทรงพิทักษ์รักษาเราไว้ และทรงมอบกองปล้นซึ่งมาต่อสู้กับเราไว้ในมือของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 24, 'ในเรื่องนี้ใครจะฟังเสียงของท่าน เพราะคนที่ลงไปรบได้ส่วนแบ่งของเขาอย่างไร คนที่เฝ้ากองสัมภาระอยู่ก็ควรได้ส่วนแบ่งอย่างนั้น ให้เขาทั้งหลายรับส่วนแบ่งเหมือนกัน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 25, 'ตั้งแต่นั้นเป็นต้นไป ดาวิดก็ตั้งข้อนี้ให้เป็นกฎเกณฑ์และกฎแก่อิสราเอลจนทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 26, 'เมื่อดาวิดมาถึงเมืองศิกลากแล้ว ก็ส่งของที่ริบได้นั้นส่วนหนึ่งไปให้เพื่อน ซึ่งเป็นพวกผู้ใหญ่ในยูดาห์กล่าวว่า “ดูเถิด นี่เป็นของขวัญฝากมาให้ท่านซึ่งเป็นส่วนของของริบจากศัตรูของพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 27, 'คือแก่คนที่อยู่ในเบธเอล ในราโมททางภาคใต้ ในยาททีร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 28, 'ในอาโรเออร์ ในสิฟโมท ในเอชเทโมอา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 29, 'ในราคาล ในหัวเมืองของคนเยราเมเอล ในหัวเมืองของคนเคไนต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 30, 'ในโฮรมาห์ ในโคราชาน ในอาธาค');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 31, 'ในเฮโบรน คือให้แก่ทุกตําบลที่ดาวิดกับคนของท่านได้เคยไปๆมาๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 1, 'ฝ่ายคนฟีลิสเตียก็ต่อสู้กับคนอิสราเอล และคนอิสราเอลก็หนีไปให้พ้นหน้าคนฟีลิสเตีย ล้มตายอยู่ที่บนภูเขากิลโบอา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 2, 'และคนฟีลิสเตียก็ไล่ทันซาอูลกับพวกราชโอรส และคนฟีลิสเตียก็ฆ่าโยนาธาน อาบีนาดับ และมัลคีชูวาราชโอรสของซาอูลเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 3, 'การรบหนักก็ประชิดซาอูลเข้าไป นักธนูมาพบพระองค์เข้า พระองค์ก็บาดเจ็บสาหัสด้วยฝีมือของนักธนู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 4, 'แล้วซาอูลรับสั่งคนถืออาวุธของพระองค์ว่า “จงชักดาบออก แทงเราเสียให้ทะลุเถิด เกรงว่าคนที่มิได้เข้าสุหนัตเหล่านี้จะเข้ามาแทงเราทะลุ เป็นการลบหลู่เรา” แต่ผู้ถืออาวุธไม่ยอมกระทําตาม เพราะเขากลัวมาก ซาอูลจึงทรงชักดาบของพระองค์ออกทรงล้มทับดาบนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 5, 'และเมื่อผู้ถืออาวุธเห็นว่าซาอูลสิ้นพระชนม์แล้ว เขาก็ล้มทับดาบของเขาเองตายด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 6, 'ดังนั้น ซาอูลก็สิ้นพระชนม์ ราชโอรสทั้งสาม และผู้ถืออาวุธของพระองค์ก็สิ้นชีวิต ตลอดจนคนของพระองค์ทั้งสิ้นก็ตายเสียในวันเดียวกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 7, 'เมื่อคนอิสราเอลซึ่งอยู่ฟากหุบเขาข้างโน้น และผู้ที่อยู่ฟากแม่น้ําจอร์แดนข้างโน้นเห็นคนอิสราเอลหนีไป และเห็นว่าซาอูลกับราชโอรสของพระองค์สิ้นชีพแล้ว เขาก็ทิ้งบ้านเมืองของเขาเสียหลบหนีไป คนฟีลิสเตียก็เข้ามาอาศัยอยู่ในนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 8, 'อยู่มาในวันรุ่งขึ้น เมื่อคนฟีลิสเตียมาปลดเสื้อผ้าจากคนที่ถูกฆ่า ก็พบพระศพซาอูลและราชโอรสทั้งสามอยู่บนภูเขากิลโบอา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 9, 'พวกเขาตัดพระเศียรของซาอูล และถอดเครื่องอาวุธของพระองค์ออก ส่งผู้สื่อสารออกไปทั่วแผ่นดินฟีลิสเตีย เพื่อประกาศข่าวนี้ในเรือนรูปเคารพ และในท่ามกลางประชาชนของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 10, 'เขาเอาเครื่องอาวุธของพระองค์บรรจุไว้ในวิหารของพระอัชทาโรท และมัดพระศพของพระองค์ไว้กับกําแพงเมืองเบธชาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 11, 'แต่เมื่อชาวยาเบชกิเลอาดได้ยินว่าคนฟีลิสเตียกระทําอย่างนั้นกับซาอูล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 12, 'ชายที่กล้าหาญทุกคนก็ลุกขึ้นเดินคืนยังรุ่งไปปลดพระศพของซาอูล และศพราชโอรสทั้งสามลงเสียจากกําแพงเมืองเบธชาน และมาที่เมืองยาเบช ถวายพระเพลิงเสียที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 13, 'เขาก็เก็บอัฐิไปฝังไว้ที่ใต้ต้นไม้แห่งหนึ่งในยาเบช และอดอาหารเจ็ดวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 1, 'อยู่มาหลังจากที่ซาอูลสิ้นพระชนม์แล้ว เมื่อดาวิดกลับจากการฆ่าฟันคนอามาเลข ดาวิดพักอยู่ที่ศิกลากได้สองวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 2, 'พอถึงวันที่สาม ดูเถิด มีชายคนหนึ่งมาจากค่ายของซาอูล สวมเสื้อผ้าขาดและมีผงคลีดินอยู่บนศีรษะ เมื่อเขามาถึงดาวิด ก็ซบหน้าลงถึงดินกระทําความเคารพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 3, 'ดาวิดถามเขาว่า “เจ้ามาจากไหน” เขาตอบท่านว่า “ข้าพเจ้ารอดมาจากค่ายอิสราเอล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 4, 'ดาวิดถามเขาว่า “ขอบอกฉันหน่อยว่า เหตุการณ์เป็นไปอย่างไรบ้าง” และเขาตอบว่า “ประชาชนหนีจากการรบไปแล้ว มีคนล้มและถึงความตายมากมาย ซาอูลและโยนาธานราชโอรสก็สิ้นพระชนม์ด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 5, 'ดาวิดจึงถามชายหนุ่มที่บอกนั้นว่า “เจ้าทราบได้อย่างไรว่า ซาอูลและโยนาธานราชโอรสของท่านสิ้นพระชนม์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 6, 'ชายหนุ่มผู้ที่บอกท่านนั้นจึงตอบว่า “บังเอิญข้าพเจ้ามาที่ภูเขากิลโบอา ดูเถิด ซาอูลทรงยืนพิงหอกของพระองค์อยู่ และดูเถิด รถรบและทหารม้าก็ใกล้พระองค์เข้ามา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 7, 'เมื่อพระองค์ทรงเหลียวมาแลเห็นข้าพเจ้า พระองค์ตรัสเรียกข้าพเจ้า และข้าพเจ้าทูลตอบว่า ‘ข้าพระองค์อยู่ที่นี่พ่ะย่ะค่ะ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 8, 'พระองค์ตรัสถามข้าพเจ้าว่า ‘เจ้าคือใคร’ ข้าพเจ้าทูลตอบพระองค์ว่า ‘ข้าพระองค์เป็นคนอามาเลข’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 9, 'พระองค์ตรัสสั่งข้าพเจ้าว่า ‘จงมายืนข้างเราและฆ่าเราเสีย เราทนทุกข์ทรมานมากเพราะชีวิตของเรายังอยู่’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 10, 'ข้าพเจ้าจึงเข้าไปยืนข้างพระองค์ และประหารพระองค์เสีย เพราะข้าพเจ้าแน่ใจว่าเมื่อพระองค์ทรงล้มแล้วก็จะไม่ดํารงพระชนม์ได้อีก และข้าพเจ้าก็ถอดมงกุฎซึ่งอยู่บนพระเศียร และกําไลซึ่งอยู่ที่พระกร และข้าพเจ้าก็นํามาที่นี่เพื่อมอบแด่เจ้านายของข้าพเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 11, 'แล้วดาวิดฉีกเสื้อของท่าน และทุกคนที่อยู่กับท่านก็กระทําเช่นเดียวกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 12, 'และเขาทั้งหลายไว้ทุกข์และร้องไห้และอดอาหารอยู่จนเวลาเย็น ให้ซาอูล และโยนาธานราชโอรส และประชาชนของพระเยโฮวาห์ และวงศ์วานอิสราเอล เพราะเขาทั้งหลายต้องล้มตายด้วยดาบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 13, 'และดาวิดถามคนหนุ่มที่บอกท่านว่า “เจ้ามาจากไหน” เขาตอบว่า “ข้าพเจ้าเป็นบุตรของคนต่างด้าว ผู้เป็นคนอามาเลข”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 14, 'ดาวิดถามเขาว่า “ทําไมเจ้ามิได้เกรงกลัวในการที่ยื่นมือออกทําลายผู้ที่พระเยโฮวาห์ทรงเจิมไว้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 15, 'แล้วดาวิดก็เรียกคนหนึ่งในหมู่ชายหนุ่มเข้ามาบอกว่า “ไปซิ ฆ่าเขาเสีย” และเขาก็ฆ่าชายคนนั้นตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 16, 'ดาวิดกล่าวแก่ชายนั้นว่า “ให้โลหิตของเจ้าตกบนศีรษะของเจ้าเอง เพราะปากของเจ้าเป็นพยานปรักปรําตัวเจ้าเองว่า ‘ข้าพเจ้าได้ฆ่าผู้ที่พระเยโฮวาห์ทรงเจิมไว้’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 17, 'ดาวิดก็ครวญคร่ําตามคําคร่ําครวญต่อไปนี้ เพื่อซาอูลและโยนาธานราชโอรส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 18, '(และท่านกล่าวว่า ควรจะสอนคนยูดาห์ให้รู้จักใช้คันธนู ดูเถิด คําคร่ําครวญนั้นบันทึกไว้ในหนังสือยาชาร์) ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 19, '“ศักดิ์ศรีของอิสราเอลถูกประหารเสียแล้วบนที่สูงของท่าน วีรบุรุษก็ล้มตายเสียแล้วหนอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 20, 'อย่าบอกเรื่องนี้ในเมืองกัท อย่าประกาศเรื่องนี้ในถนนเมืองอัชเคโลน เกรงว่าบุตรสาวคนฟีลิสเตียจะร่าเริง เกรงว่าบุตรสาวของผู้ที่มิได้เข้าสุหนัตจะเริงโลด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 21, 'เทือกเขากิลโบอาเอ๋ย ขออย่ามีน้ําค้างหรือฝนบนเจ้าหรือทุ่งนาที่ให้ของถวาย เพราะว่าที่นั่นโล่ของวีรบุรุษถูกทอดทิ้งแล้ว โล่ของซาอูลเหมือนกับว่าพระองค์มิได้เจิมไว้ด้วยน้ํามัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 22, 'คันธนูของโยนาธานมิได้หันกลับมาจากโลหิตของผู้ที่ถูกฆ่า จากไขมันของผู้ที่มีกําลัง และดาบของซาอูลก็มิได้กลับมาเปล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 23, 'ซาอูลและโยนาธานเป็นที่รักและน่ารักเมื่อทรงพระชนม์อยู่ และเมื่อมรณาแล้วทั้งสองไม่แยกจากกัน ทั้งสองก็เร็วกว่านกอินทรี ทั้งสองแข็งแรงกว่าสิงโต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 24, 'บุตรสาวของอิสราเอลเอ๋ย จงร้องไห้เพื่อซาอูล ผู้ทรงประดับเจ้าอย่างโอ่อ่าด้วยผ้าสีแดงเข้ม และผู้ทรงประดับอาภรณ์ทองคําเหนือเครื่องแต่งกายของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 25, 'วีรบุรุษก็ล้มลงเสียแล้วหนอท่ามกลางศึกสงคราม โอ โยนาธาน ท่านถูกสังหารอยู่บนที่สูงของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 26, 'พี่โยนาธานเอ๋ย ข้าพเจ้าเป็นทุกข์เพื่อท่าน ท่านเป็นที่ชื่นใจของข้าพเจ้ามาก ความรักของท่านที่มีต่อข้าพเจ้านั้นประหลาดเหลือยิ่งกว่าความรักของสตรี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 27, 'วีรบุรุษก็ล้มลงเสียแล้วหนอ และเครื่องยุทโธปกรณ์ก็พินาศไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 1, 'ครั้นเรื่องนี้สิ้นไปแล้ว ดาวิดจึงทูลถามพระเยโฮวาห์ว่า “สมควรที่ข้าพระองค์จะขึ้นไปยังหัวเมืองหนึ่งหัวเมืองใดในยูดาห์หรือไม่” และพระเยโฮวาห์ตรัสตอบท่านว่า “จงขึ้นไปเถิด” ดาวิดทูลว่า “ควรที่ข้าพระองค์จะขึ้นไปที่ใด” พระองค์ตรัสว่า “เมืองเฮโบรน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 2, 'ดาวิดจึงขึ้นไปที่นั้นพร้อมกับภรรยาทั้งสองของท่านด้วยคือ อาหิโนอัมชาวยิสเรเอลและอาบีกายิลภรรยาของนาบาลชาวคารเมล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 3, 'และดาวิดก็นําคนที่อยู่กับท่านขึ้นไป ทุกคนพาครอบครัวไปด้วย และเขาทั้งหลายก็อยู่ในหัวเมืองของเฮโบรน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 4, 'และคนยูดาห์ก็พากันมาเจิมตั้งดาวิดไว้เป็นกษัตริย์เหนือวงศ์วานยูดาห์ เมื่อมีคนมาทูลดาวิดว่า “ชาวยาเบชกิเลอาดเป็นผู้ที่ฝังพระศพซาอูลไว้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 5, 'ดาวิดก็มีรับสั่งให้ผู้สื่อสารไปหาชาวยาเบชกิเลอาดนั้น พูดกับเขาว่า “ขอพระเยโฮวาห์ทรงอํานวยพระพรแก่ท่านทั้งหลาย ในการที่ท่านทั้งหลายได้สําแดงความเมตตาอย่างนี้ต่อซาอูลเจ้านายของท่าน และได้ฝังพระศพพระองค์ไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 6, 'บัดนี้ขอพระเยโฮวาห์ทรงสําแดงความกรุณาและความจริงแก่ท่าน และข้าพเจ้าจะกระทําความดีต่อท่านทั้งหลายเพราะท่านได้กระทําการนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 7, 'เพราะฉะนั้น บัดนี้ขอให้มือของท่านทั้งหลายเข้มแข็ง และขอให้ท่านกล้าหาญเถิด เพราะว่าซาอูลเจ้านายของท่านสิ้นพระชนม์เสียแล้ว และวงศ์วานยูดาห์ได้เจิมตั้งข้าพเจ้าไว้เป็นกษัตริย์เหนือเขาทั้งหลาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 8, 'ฝ่ายอับเนอร์บุตรชายเนอร์แม่ทัพของกองทัพซาอูลได้พาอิชโบเชทราชโอรสของซาอูลข้ามไปที่เมืองมาหะนาอิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 9, 'และได้สถาปนาท่านให้เป็นกษัตริย์เหนือเมืองกิเลอาด และคนอาเชอร์ และคนยิสเรเอล และคนเอฟราอิม และคนเบนยามิน และคนอิสราเอลทั้งหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 10, 'เมื่ออิชโบเชทราชโอรสของซาอูลเริ่มปกครองเหนืออิสราเอลนั้นมีพระชนมายุสี่สิบพรรษา ทรงครอบครองอยู่สองปี แต่วงศ์วานยูดาห์ก็ติดตามดาวิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 11, 'เวลาที่ดาวิดทรงเป็นกษัตริย์เหนือวงศ์วานยูดาห์ในเฮโบรนนั้นเป็นจํานวนเจ็ดปีกับหกเดือน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 12, 'อับเนอร์บุตรชายเนอร์และพวกข้าราชการทหารของอิชโบเชทราชโอรสของซาอูลได้ออกจากมาหะนาอิมไปยังเมืองกิเบโอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 13, 'และโยอาบบุตรชายนางเศรุยาห์กับพวกข้าราชการทหารของดาวิดก็ออกไปพบกับเขาที่สระเมืองกิเบโอน และเขาทั้งหลายก็นั่งอยู่ที่ขอบสระ พวกหนึ่งอยู่ที่ขอบสระข้างนี้ อีกพวกหนึ่งข้างโน้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 14, 'อับเนอร์จึงพูดกับโยอาบว่า “ขอให้พวกคนหนุ่มลุกขึ้นรบเล่นกันให้เราดูเถิด” และโยอาบตอบว่า “ให้เขาลุกขึ้นเล่นซี”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 15, 'เขาก็ลุกขึ้นไปตามที่นับไว้ฝ่ายเบนยามินและฝ่ายอิชโบเชทราชโอรสของซาอูลมีสิบสองคน และข้าราชการทหารของดาวิดก็มีสิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 16, 'ต่างก็จับศีรษะคู่ต่อสู้ และปักดาบเข้าที่สีข้างของคู่ต่อสู้ ล้มตายด้วยกันหมด เขาจึงเรียกที่นั่นว่า เฮลขัทฮัสซูริม ซึ่งอยู่ในกิเบโอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 17, 'การสู้รบในวันนั้นดุเดือดยิ่งนัก อับเนอร์และพวกคนอิสราเอลก็พ่ายแพ้ต่อหน้าข้าราชการทหารของดาวิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 18, 'บุตรชายทั้งสามของนางเศรุยาห์ก็อยู่ที่นั่น คือ โยอาบ อาบีชัย และอาสาเฮล ฝ่ายอาสาเฮลนั้นฝีเท้าเร็วอย่างกับละมั่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 19, 'และอาสาเฮลก็ไล่ตามอับเนอร์ไป เมื่อตามไปนั้นก็มิได้เลี้ยวทางขวามือหรือทางซ้ายมือจากการไล่ตามอับเนอร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 20, 'อับเนอร์เหลียวมาดูจึงพูดว่า “นั่นอาสาเฮลหรือ” เขาตอบว่า “ข้าเอง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 21, 'อับเนอร์จึงบอกเขาว่า “จงเลี้ยวไปทางขวาหรือทางซ้าย และจับเอาคนหนุ่มคนใดคนหนึ่ง แล้วก็ริบเอาอาวุธของเขาไป” แต่อาสาเฮลไม่เลี้ยวจากไล่ตามอับเนอร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 22, 'อับเนอร์จึงบอกอาสาเฮลอีกครั้งหนึ่งว่า “จงหันกลับจากตามข้าเสียเถิด จะให้ข้าฟาดเจ้าให้ล้มลงดินทําไมเล่า แล้วข้าจะเงยหน้าขึ้นดูโยอาบพี่ของเจ้าได้อย่างไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 23, 'แต่เขาก็ปฏิเสธไม่ยอมหันกลับ เพราะฉะนั้นอับเนอร์ก็เอาโคนหอกแทงท้องอาสาเฮล หอกก็ทะลุออกข้างหลังของเขา เขาก็ล้มลงตายอยู่ที่นั่น และอยู่มาทุกคนซึ่งมาเห็นที่ที่อาสาเฮลล้มตายอยู่ก็ยืนนิ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 24, 'แต่โยอาบกับอาบีชัยไล่ตามอับเนอร์ไป ดวงอาทิตย์ก็ตกเมื่อเขามาถึงเนินเขาอัมมาห์ ซึ่งอยู่ตรงกียาห์ตามทางที่จะไปถิ่นทุรกันดารเมืองกิเบโอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 25, 'และคนเบนยามินก็รวมกันตามอับเนอร์ไปเป็นกลุ่มเดียวกันตั้งอยู่ที่ยอดเขาแห่งหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 26, 'แล้วอับเนอร์ร้องถามโยอาบว่า “จะให้ดาบกินเรื่อยไปหรือ ท่านไม่ทราบหรือว่าตอนปลายมือก็ขม อีกนานสักเท่าใดท่านจึงจะสั่งคนของท่านให้หยุดไล่ตามพี่น้องของเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 27, 'และโยอาบจึงกล่าวว่า “พระเจ้าทรงพระชนม์อยู่แน่ฉันใด ถ้าท่านไม่พูดขึ้นพวกทหารก็จะเลิกไล่ตามพวกพี่น้องของเขาพรุ่งนี้เช้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 28, 'โยอาบจึงเป่าแตรขึ้น คนทั้งปวงก็หยุด ไม่ไล่ตามอิสราเอลอีก และไม่สู้รบกันอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 29, 'อับเนอร์กับคนของท่านก็เดินทางตลอดคืนนั้นในที่ราบ เขาข้ามแม่น้ําจอร์แดนและเดินไปตามหุบเขาบิทโรน เขาก็มาถึงมาหะนาอิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 30, 'โยอาบก็กลับจากไล่ตามอับเนอร์ และเมื่อท่านรวบรวมพลเข้าด้วยกันแล้ว ข้าราชการทหารของดาวิดก็ขาดไปสิบเก้าคนไม่นับอาสาเฮล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 31, 'แต่ข้าราชการทหารของดาวิดได้ฆ่าคนเบนยามินและคนของอับเนอร์ตายไปสามร้อยหกสิบคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 32, 'และเขาก็ยกศพอาสาเฮลไปฝังไว้ในอุโมงค์บิดาของเขาซึ่งอยู่ที่เมืองเบธเลเฮม โยอาบและคนของท่านก็เดินทางตลอดคืนไปสว่างที่เมืองเฮโบรน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 1, 'มีสงครามระหว่างวงศ์วานของซาอูลกับวงศ์วานของดาวิดอยู่นาน และดาวิดก็เข้มแข็งยิ่งขึ้น ฝ่ายวงศ์วานของซาอูลก็เสื่อมกําลังลงทุกที');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 2, 'ดาวิดทรงมีราชโอรสเกิดหลายองค์ที่เมืองเฮโบรน ราชโอรสหัวปีชื่อ อัมโนน บุตรนางอาหิโนอัมชาวยิสเรเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 3, 'คนที่สองชื่อ คิเลอาบ บุตรนางอาบีกายิลภรรยาของนาบาลชาวคารเมล และคนที่สามชื่อ อับซาโลม บุตรชายนางมาอาคาห์ราชธิดาของทัลมัยกษัตริย์เมืองเกชูร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 4, 'คนที่สี่ชื่อ อาโดนียาห์ บุตรชายนางฮักกีท คนที่ห้าชื่อ เชฟาทิยาห์ บุตรชายนางอาบีทัล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 5, 'และคนที่หกชื่อ อิทเรอัม บุตรนางเอกลาห์ภรรยาของดาวิด ราชโอรสเหล่านี้เกิดแก่ดาวิดที่เมืองเฮโบรน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 6, 'อยู่มาเมื่อมีการต่อสู้ระหว่างวงศ์วานของซาอูลกับวงศ์วานของดาวิดนั้น อับเนอร์ได้กระทําตัวให้เข้มแข็งยิ่งขึ้นในวงศ์วานของซาอูล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 7, 'ฝ่ายซาอูลนั้นมีนางสนมคนหนึ่งชื่อริสปาห์บุตรสาวของอัยยาห์ และอิชโบเชทจึงตรัสกับอับเนอร์ว่า “เหตุใดท่านจึงเข้าหานางสนมของเสด็จพ่อของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 8, 'ฝ่ายอับเนอร์ก็โกรธอิชโบเชทเพราะถ้อยคํานี้มาก จึงทูลว่า “ข้าพระองค์เป็นหัวสุนัขหรือ ซึ่งทุกวันนี้ข้าพระองค์ได้ต่อต้านยูดาห์โดยสําแดงความเมตตาต่อวงศ์วานของซาอูลเสด็จพ่อของพระองค์ และต่อพี่น้องและต่อมิตรสหายของเสด็จพ่อของพระองค์ มิได้มอบพระองค์ไว้ในมือของดาวิด วันนี้พระองค์ยังหาความต่อข้าพระองค์ด้วยเรื่องผู้หญิงคนนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 9, 'ถ้าข้าพระองค์จะมิได้กระทําเพื่อดาวิดให้สําเร็จดังที่พระเยโฮวาห์ทรงปฏิญาณไว้ต่อท่านแล้ว ก็ขอพระเจ้าทรงลงโทษอับเนอร์และให้หนักยิ่งกว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 10, 'คือข้าพระองค์จะย้ายราชอาณาจักรจากวงศ์วานของซาอูล และสถาปนาบัลลังก์ของดาวิดเหนืออิสราเอลและเหนือยูดาห์ ตั้งแต่ดานถึงเบเออร์เชบา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 11, 'และอิชโบเชทก็หาทรงสามารถตอบอับเนอร์สักคําเดียวอีกไม่ เพราะพระองค์ทรงกลัวเกรงอับเนอร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 12, 'อับเนอร์ก็ส่งผู้สื่อสารแทนตนไปยังดาวิดทูลว่า “แผ่นดินนี้เป็นของผู้ใด” และทูลอีกว่า “ขอทรงทําพันธสัญญากับข้าพระองค์ และดูเถิด มือของข้าพระองค์จะอยู่ฝ่ายพระองค์ และนําอิสราเอลทั้งสิ้นมามอบแด่พระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 13, 'ดาวิดตรัสว่า “ดีแล้ว เราจะกระทําพันธสัญญากับท่าน แต่เราขอจากท่านสักอย่างหนึ่งคือว่า เมื่อท่านจะมาเห็นหน้าเราอีก ขอท่านนํามีคาลบุตรสาวของซาอูลมาให้เราก่อน มิฉะนั้นท่านจะมิได้เห็นหน้าเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 14, 'แล้วดาวิดก็ส่งผู้สื่อสารไปยังอิชโบเชทราชโอรสของซาอูลว่า “ขอมอบมีคาลภรรยาของข้าพเจ้าแก่ข้าพเจ้า ผู้ซึ่งข้าพเจ้าได้หมั้นไว้ด้วยหนังปลายองคชาตของคนฟีลิสเตียหนึ่งร้อยชิ้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 15, 'อิชโบเชทจึงทรงให้คนไปพามีคาลมาจากสามีของเธอ คือปัลทีเอลบุตรชายของลาอิช');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 16, 'แต่สามีของเธอก็เดินพลางร้องไห้พลางไปกับเธอจนถึงตําบลบาฮูริม แล้วอับเนอร์จึงบอกเขาว่า “กลับไปเสียเถิด” และเขาก็กลับไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 17, 'อับเนอร์จึงปรึกษากับพวกผู้ใหญ่ของอิสราเอลว่า “เมื่อก่อนนี้ท่านทั้งหลายใคร่ให้ดาวิดเป็นกษัตริย์เหนือท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 18, 'บัดนี้จงให้เป็นจริงเถิด เพราะพระเยโฮวาห์ทรงตรัสเรื่องดาวิดว่า ‘เราจะช่วยอิสราเอลประชาชนของเราด้วยมือของดาวิดผู้รับใช้ของเรา ให้พ้นจากมือของคนฟีลิสเตีย และให้พ้นจากมือศัตรูทั้งสิ้นของเขา’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 19, 'อับเนอร์ก็พูดกับคนเบนยามินด้วย และอับเนอร์ก็ไปทูลดาวิดที่เมืองเฮโบรนถึงบรรดาสิ่งต่างๆที่อิสราเอล และวงศ์วานทั้งสิ้นของเบนยามินเห็นสมควรที่จะกระทํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 20, 'อับเนอร์จึงมาเฝ้าดาวิดที่เมืองเฮโบรนพร้อมกับคนอีกยี่สิบคน ดาวิดทรงจัดการเลี้ยงอับเนอร์กับคนที่อยู่กับท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 21, 'และอับเนอร์ทูลดาวิดว่า “ข้าพระองค์จะลุกขึ้นกลับไป และจะรวบรวมคนอิสราเอลทั้งสิ้นมายังกษัตริย์เจ้านายของข้าพระองค์ เพื่อเขาทั้งหลายจะกระทําพันธสัญญากับพระองค์ และเพื่อพระองค์จะทรงปกครองให้กว้างขวางตามชอบพระทัยของพระองค์” ดาวิดก็ทรงส่งอับเนอร์กลับไป และเขาก็ไปโดยสันติภาพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 22, 'ดูเถิด ขณะนั้นข้าราชการทหารของดาวิดกับโยอาบกลับมาจากการไปปล้นและนําสิ่งของที่ริบได้มากมายนั้นมาด้วย แต่อับเนอร์มิได้อยู่กับดาวิดที่เฮโบรนแล้ว เพราะพระองค์ทรงส่งท่านกลับไป และท่านก็ไปโดยสันติภาพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 23, 'เมื่อโยอาบกับกองทัพทั้งสิ้นที่อยู่กับท่านมาถึง ก็มีคนบอกโยอาบว่า “อับเนอร์บุตรเนอร์มาเฝ้ากษัตริย์ และพระองค์ทรงให้เขากลับไป เขาก็กลับไปโดยสันติภาพ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 24, 'แล้วโยอาบเข้าไปเฝ้ากษัตริย์ทูลว่า “พระองค์ทรงกระทําอะไรเช่นนั้น ดูเถิด อับเนอร์มาเฝ้าพระองค์ ไฉนพระองค์จึงปล่อยเขาไป เขาก็หลุดมือไปแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 25, 'พระองค์ทรงทราบแล้วว่าอับเนอร์บุตรเนอร์มาเพื่อล่อลวงพระองค์ และเพื่อทราบถึงการเสด็จเข้าออกของพระองค์ และเพื่อทราบทุกสิ่งทุกอย่างที่พระองค์ทรงกระทํา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 26, 'เมื่อโยอาบออกมาจากการเข้าเฝ้าดาวิด จึงส่งผู้สื่อสารไปตามอับเนอร์ เขาทั้งหลายก็นําท่านกลับมาจากบ่อน้ําชื่อสีราห์ แต่ดาวิดหาทรงทราบเรื่องไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 27, 'และเมื่ออับเนอร์กลับมาถึงเฮโบรนแล้ว โยอาบก็พาท่านหลบเข้าไปที่กลางประตูเมืองเพื่อจะพูดกับท่านเป็นการลับ และโยอาบแทงท้องของท่านเสียที่นั่น ท่านก็สิ้นชีวิต โยอาบแก้แค้นโลหิตของอาสาเฮลน้องชายของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 28, 'ภายหลังเมื่อดาวิดทรงได้ยินเรื่องนี้ พระองค์ตรัสว่า “ตัวเราและราชอาณาจักรของเราปราศจากความผิดสืบไปเป็นนิตย์ต่อพระพักตร์พระเยโฮวาห์ด้วยเรื่องโลหิตของอับเนอร์บุตรเนอร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 29, 'ขอให้โทษนั้นตกเหนือศีรษะของโยอาบ และเหนือวงศ์วานบิดาของเขาทั้งสิ้น ขออย่าให้คนที่มีสิ่งไหลออก คนที่เป็นโรคเรื้อน คนที่ถือไม้เท้า คนที่ถูกประหารด้วยดาบ หรือคนขาดขนมปัง ขาดจากวงศ์วานของโยอาบ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 30, 'นี่แหละโยอาบกับอาบีชัยน้องชายของเขาได้ฆ่าอับเนอร์ เพราะอับเนอร์ได้ฆ่าอาสาเฮลน้องชายของเขาเมื่อรบกันที่กิเบโอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 31, 'แล้วดาวิดก็ตรัสกับโยอาบ และประชาชนทุกคนที่อยู่กับพระองค์ว่า “จงฉีกเสื้อผ้าของท่านทั้งหลาย และเอาผ้ากระสอบคาดเอวไว้ และจงไว้ทุกข์ให้อับเนอร์” และกษัตริย์ดาวิดเสด็จตามแคร่หามศพอับเนอร์ไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 32, 'เขาก็ฝังศพอับเนอร์ไว้ที่เฮโบรน และกษัตริย์ก็ส่งพระสุรเสียงกันแสง ณ ที่ฝังศพของอับเนอร์ และประชาชนทั้งปวงก็ร้องไห้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 33, 'และกษัตริย์ทรงคร่ําครวญด้วยเรื่องอับเนอร์ว่า “ควรหรือที่อับเนอร์จะตายอย่างคนโง่ตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 34, 'มือของท่านก็มิได้ถูกมัด เท้าของท่านก็มิได้ติดตรวน ท่านได้ล้มลงเหมือนอย่างคนล้มลงต่อหน้าคนชั่วร้าย” และประชาชนทั้งปวงก็ร้องไห้ถึงอับเนอร์อีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 35, 'แล้วประชาชนทั้งปวงก็มาทูลชวนเชิญให้ดาวิดเสวยพระกระยาหารเมื่อเวลายังวันอยู่ แต่ดาวิดทรงสาบานว่า “ถ้าเราลิ้มรสขนมปังหรือสิ่งใดๆก่อนดวงอาทิตย์ตก ขอพระเจ้าทรงทําโทษเราและให้หนักยิ่งกว่า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 36, 'ประชาชนทั้งปวงสังเกตเห็นเช่นนั้นก็พอใจ ดังที่ประชาชนทั้งปวงพอใจทุกสิ่งที่กษัตริย์ทรงกระทํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 37, 'ประชาชนทั้งสิ้นและชนอิสราเอลทั้งปวงจึงเข้าใจในวันนั้นว่าไม่เป็นพระประสงค์ของกษัตริย์ที่จะให้ฆ่าอับเนอร์บุตรชายเนอร์เสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 38, 'กษัตริย์ตรัสกับข้าราชการของพระองค์ว่า “ท่านไม่ทราบหรือว่า วันนี้เจ้านายและคนสําคัญยิ่งคนหนึ่งสิ้นชีวิตในอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 39, 'แม้เราได้รับการเจิมเป็นกษัตริย์แล้ว เราก็อ่อนกําลังในวันนี้ ชายเหล่านี้ซึ่งเป็นบุตรของนางเศรุยาห์หนักแก่เราเกินไป ขอพระเยโฮวาห์ทรงสนองผู้กระทําผิดตามความผิดของเขาเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 1, 'เมื่ออิชโบเชทราชโอรสของซาอูลทรงได้ยินว่าอับเนอร์สิ้นชีวิตเสียที่เฮโบรนแล้ว พระหัตถ์ของพระองค์ก็อ่อนลง และอิสราเอลทั้งปวงก็เป็นทุกข์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 2, 'ฝ่ายราชโอรสของซาอูลยังมีชายอีกสองคนเป็นหัวหน้าของกองปล้น คนหนึ่งชื่อบาอานาห์ อีกคนหนึ่งชื่อเรคาบ ทั้งสองเป็นบุตรชายของริมโมน คนเบนยามินชาวเมืองเบเอโรท (เพราะว่าเบเอโรทก็นับเข้าเป็นของเบนยามินด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 3, 'ชาวเบเอโรทหนีไปยังเมืองกิททาอิม และอาศัยอยู่ที่นั่นจนทุกวันนี้)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 4, 'โยนาธานราชโอรสของซาอูล มีบุตรชายคนหนึ่งเป็นง่อย เมื่อมีข่าวเรื่องซาอูลกับโยนาธานมาจากยิสเรเอลนั้น เด็กคนนี้มีอายุห้าขวบ พี่เลี้ยงก็อุ้มลุกขึ้นหนีไป อยู่มาเมื่อเธอรีบหนีไปนั้นเด็กนั้นก็หล่นลงและเป็นง่อย ท่านชื่อเมฟีโบเชท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 5, 'ฝ่ายบุตรชายทั้งสองของริมโมน ชาวเบเอโรท ที่ชื่อเรคาบและบาอานาห์นั้นได้ออกเดินทาง พอแดดออกจัดก็มาถึงตําหนักของอิชโบเชท ขณะเมื่อพระองค์กําลังบรรทมพักเที่ยง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 6, 'และเขาเข้าไปกลางตําหนัก ทําเหมือนจะขนข้าวสาลีและเขาก็แทงพระอุทรพระองค์ เรคาบและบาอานาห์พี่ชายก็หนีไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 7, 'และเมื่อเขาทั้งสองเข้าไปในตําหนักนั้น พระองค์บรรทมหลับอยู่บนพระแท่นบรรทมในห้องบรรทม เขาก็ทุบตีพระองค์และประหารพระองค์ และตัดพระเศียรของพระองค์เสีย นําพระเศียรนั้นเดินทางไปทางที่ราบทั้งกลางคืน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 8, 'และเขานําพระเศียรของอิชโบเชทไปถวายดาวิดที่เมืองเฮโบรน เขาทั้งสองกราบทูลกษัตริย์ว่า “ดูเถิด ศีรษะของอิชโบเชทบุตรของซาอูลศัตรูของพระองค์ ผู้แสวงหาชีวิตของพระองค์ พระเยโฮวาห์ทรงแก้แค้นแทนกษัตริย์เจ้านายของข้าพระองค์ในวันนี้เหนือซาอูลและเชื้อสายของซาอูล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 9, 'แต่ดาวิดตรัสตอบเรคาบและบาอานาห์พี่ชาย บุตรชายของริมโมนชาวเบเอโรทว่า “พระเยโฮวาห์ทรงพระชนม์อยู่แน่ฉันใด คือพระองค์ผู้ทรงไถ่ชีวิตของเราจากบรรดาความทุกข์ยาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 10, 'เมื่อผู้หนึ่งผู้ใดบอกเราว่า ‘ดูเถิด ซาอูลสิ้นพระชนม์แล้ว’ และคิดว่าตนนําข่าวดีมา เราก็จับคนนั้นฆ่าเสียที่ศิกลาก ซึ่งคนนั้นคิดว่าเราจะให้รางวัลแก่เขาสําหรับข่าวนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 11, 'ยิ่งกว่านั้นเท่าใดเมื่อคนชั่วได้ฆ่าคนชอบธรรมที่ในบ้านและบนที่นอนของคนชอบธรรมนั้น ฉะนั้นบัดนี้เราจะไม่เรียกร้องโลหิตของเขาจากมือของเจ้าทั้งสองหรือ และทําลายเจ้าเสียจากพิภพ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 12, 'และดาวิดก็ทรงบัญชาคนหนุ่มของพระองค์ และพวกเขาก็พาเขาทั้งสองไปฆ่าเสียตัดมือตัดเท้าออก แขวนศพนั้นไว้เหนือสระในเมืองเฮโบรน แต่เขานําพระเศียรของอิชโบเชทไปฝังไว้ในที่ฝังศพของอับเนอร์ในเมืองเฮโบรน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 1, 'และบรรดาตระกูลคนอิสราเอลก็มาหาดาวิดที่เมืองเฮโบรนทูลว่า “ดูเถิด ข้าพระองค์ทั้งหลายเป็นกระดูกและเนื้อของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 2, 'ในอดีตเมื่อซาอูลเป็นกษัตริย์ปกครองเหนือเหล่าข้าพระองค์ พระองค์ทรงเป็นผู้นําอิสราเอลออกไปและเข้ามา และพระเยโฮวาห์ตรัสแก่พระองค์ว่า ‘เจ้าจะเลี้ยงดูอิสราเอลประชาชนของเรา และเจ้าจะเป็นเจ้าเหนือคนอิสราเอล’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 3, 'ดังนั้นพวกผู้ใหญ่ของคนอิสราเอลก็มาเฝ้ากษัตริย์ที่เมืองเฮโบรน และกษัตริย์ดาวิดทรงกระทําพันธสัญญากับเขาทั้งหลายที่เมืองเฮโบรนต่อพระพักตร์พระเยโฮวาห์ และเขาทั้งหลายก็เจิมตั้งดาวิดให้เป็นกษัตริย์เหนืออิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 4, 'ดาวิดมีพระชนมายุสามสิบพรรษาเมื่อเริ่มการปกครอง และพระองค์ทรงปกครองอยู่สี่สิบปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 5, 'ทรงปกครองเหนือยูดาห์ที่เฮโบรนเจ็ดปีหกเดือน และที่กรุงเยรูซาเล็มทรงปกครองเหนือบรรดาอิสราเอลและยูดาห์อีกสามสิบสามปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 6, 'กษัตริย์และคนของพระองค์ได้ยกทัพไปยังเยรูซาเล็ม รบกับคนเยบุส ชาวแผ่นดินนั้นผู้ที่กล่าวกับดาวิดว่า “แกยกเข้ามาที่นี่ไม่ได้ดอก คนตาบอดและคนง่อยก็จะป้องกันไว้ได้” ด้วยคิดว่า “ดาวิดคงเข้ามาที่นี่ไม่ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 7, 'แต่อย่างไรก็ตาม ดาวิดทรงยึดที่กําบังเข้มแข็งชื่อศิโยนได้ คือเมืองของดาวิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 8, 'ในวันนั้นดาวิดตรัสว่า “ผู้ใดจะขึ้นไปตามทางน้ําไหลและโจมตีคนเยบุส คนง่อยและคนตาบอด ผู้ซึ่งจิตใจของดาวิดเกลียดชัง ผู้นั้นจะเป็นผู้บัญชาการทหาร” เพราะฉะนั้นเขาจึงว่ากันว่า “อย่าให้คนตาบอดและคนง่อยเข้ามาในพระนิเวศ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 9, 'ดาวิดก็ทรงประทับอยู่ในที่กําบังเข้มแข็ง และเรียกที่นั้นว่า เมืองของดาวิด และดาวิดทรงสร้างเมืองรอบตั้งแต่มิลโลเข้าไปข้างใน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 10, 'และดาวิดทรงเจริญยิ่งๆขึ้นไปเพราะว่าพระเยโฮวาห์พระเจ้าจอมโยธาทรงสถิตกับพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 11, 'ฮีรามกษัตริย์เมืองไทระได้ส่งผู้สื่อสารมาหาดาวิด และได้ส่งไม้สนสีดาร์ พวกช่างไม้และพวกช่างก่อมาสร้างพระราชวังของดาวิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 12, 'และดาวิดทรงทราบว่า พระเยโฮวาห์ทรงสถาปนาพระองค์ให้เป็นกษัตริย์เหนืออิสราเอล และพระองค์ได้ทรงยกย่องราชอาณาจักรของพระองค์ด้วยเห็นแก่อิสราเอลประชาชนของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 13, 'ภายหลังที่พระองค์เสด็จจากเฮโบรน ดาวิดทรงได้นางสนมและมเหสีจากเยรูซาเล็มเพิ่มขึ้นอีก และบังเกิดราชโอรสและราชธิดาแก่ดาวิดอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 14, 'ต่อไปนี้เป็นชื่อของผู้ที่บังเกิดกับพระองค์ในเยรูซาเล็ม คือ ชัมมูอา โชบับ นาธัน ซาโลมอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 15, 'อิบฮาร์ เอลีชูอา เนเฟก ยาเฟีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 16, 'เอลีชามา เอลียาดา และเอลีเฟเลท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 17, 'เมื่อคนฟีลิสเตียได้ยินข่าวว่าดาวิดได้รับการเจิมเป็นกษัตริย์เหนืออิสราเอล คนฟีลิสเตียทั้งปวงก็ขึ้นไปแสวงหาดาวิด แต่ดาวิดทรงได้ยินข่าวนั้นจึงลงไปยังที่กําบังเข้มแข็ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 18, 'ฝ่ายคนฟีลิสเตียยกขึ้นมาและขยายแนวออกที่หุบเขาเรฟาอิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 19, 'และดาวิดทรงทูลถามพระเยโฮวาห์ว่า “ควรที่ข้าพระองค์จะยกขึ้นไปสู้รบกับคนฟีลิสเตียหรือ พระองค์จะทรงมอบเขาไว้ในมือข้าพระองค์หรือไม่” และพระเยโฮวาห์ทรงตอบดาวิดว่า “จงขึ้นไปเถิด เพราะเราจะมอบคนฟีลิสเตียไว้ในมือของเจ้าเป็นแน่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 20, 'ดาวิดเสด็จมายังบาอัลเปราซิม และดาวิดทรงชนะคนฟีลิสเตียที่นั่น พระองค์ตรัสว่า “พระเยโฮวาห์ทรงทะลวงข้าศึกของข้าพเจ้าดังกระแสน้ําที่พุ่งใส่” เพราะฉะนั้นจึงเรียกชื่อตําบลนั้นว่า บาอัลเปราซิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 21, 'และคนฟีลิสเตียได้ทิ้งรูปเคารพที่นั่น ดาวิดกับข้าราชการของพระองค์ก็เผาเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 22, 'คนฟีลิสเตียยกขึ้นมาอีกและขยายแนวอยู่ในหุบเขาเรฟาอิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 23, 'และเมื่อดาวิดทูลถามพระเยโฮวาห์ พระองค์ตรัสว่า “เจ้าอย่าขึ้น จงอ้อมไปข้างหลังของเขา และโจมตีเขาตรงข้ามกับหมู่ต้นหม่อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 24, 'และเมื่อเจ้าได้ยินเสียงกระบวนทัพเดินอยู่ที่ยอดหมู่ต้นหม่อนเจ้าจงรีบรุกไป เพราะพระเยโฮวาห์เสด็จไปข้างหน้าเพื่อจะโจมตีกองทัพของคนฟีลิสเตีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 25, 'และดาวิดทรงกระทําตามที่พระเยโฮวาห์ทรงบัญชาไว้ และได้โจมตีคนฟีลิสเตียจากเกบาถึงเกเซอร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 1, 'ดาวิดทรงรวบรวมบรรดาคนอิสราเอลที่คัดเลือกแล้วอีกครั้งหนึ่งได้สามหมื่นคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 2, 'และดาวิดก็ทรงลุกขึ้นไปกับประชาชนทั้งสิ้นที่อยู่กับพระองค์จากบาอาเลยูดาห์ เพื่อทรงนําหีบของพระเจ้าขึ้นมาจากที่นั่น ซึ่งเรียกตามพระนามคือพระนามของพระเยโฮวาห์จอมโยธาผู้ประทับระหว่างพวกเครูบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 3, 'และเขาทั้งหลายก็เอาเกวียนใหม่บรรทุกหีบของพระเจ้าและนําออกมาจากเรือนของอาบีนาดับซึ่งอยู่เมืองกิเบอาห์ และอุสซาห์กับอาหิโย บุตรชายทั้งหลายของอาบีนาดับก็ขับเกวียนใหม่เล่มนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 4, 'และนําออกมาจากเรือนของอาบีนาดับซึ่งอยู่เมืองกิเบอาห์ เกวียนบรรจุหีบของพระเจ้าไป และอาหิโยเดินนําหน้าหีบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 5, 'ดาวิดกับวงศ์วานอิสราเอลทั้งสิ้นก็ร่าเริงกันอยู่ต่อพระพักตร์พระเยโฮวาห์ด้วยใช้เครื่องดนตรีทุกชนิดซึ่งทําด้วยไม้สนสามใบ คือพิณเขาคู่และพิณใหญ่ รํามะนา กรับ และฉาบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 6, 'และเมื่อมาถึงลานนวดข้าวของนาโคน อุสซาห์ก็เหยียดมือออกจับหีบของพระเจ้าไว้เพราะวัวสะดุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 7, 'และพระพิโรธของพระเยโฮวาห์ก็เกิดขึ้นกับอุสซาห์ และพระเจ้าทรงประหารเขาเสียที่นั่นเพราะความผิดพลาดนั้น และเขาก็สิ้นชีวิตอยู่ข้างหีบของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 8, 'และดาวิดก็ไม่ทรงพอพระทัย เพราะพระเยโฮวาห์ทรงทลายออกมาเหนืออุสซาห์ จึงเรียกที่ตรงนั้นว่า เปเรศอุสซาห์ จนถึงทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 9, 'ในวันนั้นดาวิดก็ทรงกลัวพระเยโฮวาห์ และพระองค์ตรัสว่า “หีบของพระเยโฮวาห์จะมาถึงข้าได้อย่างไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 10, 'ดังนั้นดาวิดจึงไม่ยอมที่จะนําหีบของพระเยโฮวาห์เข้าไปในเมืองของดาวิดให้อยู่กับตน แต่ดาวิดได้ทรงนําไปที่บ้านของโอเบดเอโดมชาวกัท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 11, 'หีบของพระเยโฮวาห์ก็ค้างอยู่ที่บ้านของโอเบดเอโดมชาวกัทสามเดือน และพระเยโฮวาห์ทรงอํานวยพระพรแก่โอเบดเอโดมและครัวเรือนของเขาทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 12, 'มีคนไปกราบทูลกษัตริย์ดาวิดว่า “พระเยโฮวาห์ทรงอํานวยพระพรแก่ครัวเรือนของโอเบดเอโดม และทุกสิ่งที่เป็นของเขาเนื่องด้วยหีบของพระเจ้า” ดังนั้นดาวิดจึงเสด็จไปนําหีบของพระเจ้าขึ้นมาจากบ้านของโอเบดเอโดม ถึงเมืองดาวิดด้วยความชื่นชมยินดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 13, 'และเมื่อผู้ที่หามหีบของพระเยโฮวาห์เดินไปได้หกก้าว ดาวิดก็ทรงถวายวัวกับลูกวัวอ้วน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 14, 'และดาวิดก็ทรงรําถวายต่อพระพักตร์พระเยโฮวาห์ด้วยสุดกําลังของพระองค์ และดาวิดมีเอโฟดผ้าป่านคาดอยู่ที่พระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 15, 'ดังนั้นแหละดาวิดและวงศ์วานอิสราเอลทั้งสิ้นด้วยได้นําหีบของพระเยโฮวาห์ขึ้นมาด้วยเสียงโห่ร้องและด้วยเสียงเป่าแตร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 16, 'และขณะเมื่อหีบของพระเยโฮวาห์เข้ามาถึงเมืองดาวิด มีคาลราชธิดาของซาอูลก็มองออกที่ช่องหน้าต่าง เห็นกษัตริย์ดาวิดกระโดดโลดเต้นรําถวายต่อพระพักตร์พระเยโฮวาห์ และนางก็มีใจหมิ่นประมาท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 17, 'เขาทั้งหลายนําหีบของพระเยโฮวาห์เข้ามา ตั้งไว้ในที่กําหนดภายในพลับพลาซึ่งดาวิดได้ทรงสร้างขึ้นไว้ และดาวิดก็ทรงถวายเครื่องเผาบูชาและเครื่องสันติบูชาต่อพระพักตร์พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 18, 'และเมื่อดาวิดทรงกระทําการถวายเครื่องเผาบูชาและสันติบูชาสําเร็จแล้ว พระองค์ก็ทรงถวายอวยพรประชาชนในพระนามของพระเยโฮวาห์จอมโยธา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 19, 'และทรงแจกขนมปังคนละแผ่น เนื้อคนละก้อน และขนมองุ่นแห้งคนละแผ่นแก่ประชาชนทั้งปวง คือประชาชนอิสราเอลทั้งหมดทั้งผู้หญิงผู้ชาย แล้วประชาชนทั้งหลายต่างก็กลับไปยังบ้านของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 20, 'และดาวิดก็ทรงกลับไปอวยพรแก่ราชวงศ์ของพระองค์ แต่มีคาลราชธิดาของซาอูลได้ออกมาพบดาวิดและทูลว่า “วันนี้กษัตริย์แห่งอิสราเอลได้รับเกียรติยศอย่างยิ่งใหญ่ทีเดียวนะเพคะ ที่ทรงถอดฉลองพระองค์วันนี้ท่ามกลางสายตาของพวกสาวใช้ของข้าราชการ เหมือนกับคนถ่อยแก้ผ้าอย่างไม่มีความละอาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 21, 'และดาวิดตรัสตอบมีคาลว่า “เป็นงานที่ถวายต่อพระพักตร์พระเยโฮวาห์ผู้ทรงเลือกเราไว้แทนเสด็จพ่อของเจ้า และแทนราชวงศ์ทั้งสิ้นของพระองค์ท่าน ทรงแต่งตั้งให้เราเป็นเจ้าเหนืออิสราเอลประชาชนของพระเยโฮวาห์ และเราจึงจะร่าเริงต่อพระพักตร์พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 22, 'เราจะถ่อมตัวของเราลงยิ่งกว่านี้อีกให้ปรากฏแก่ตาของเราเองว่าเป็นคนต่ํา แต่โดยพวกสาวใช้ที่เจ้าพูดถึงนั้น เราจะเป็นผู้ที่เขาถือว่ามีเกียรติ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 23, 'เพราะฉะนั้นมีคาลราชธิดาของซาอูลก็ไม่มีบุตรจนถึงวันสิ้นชีพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 1, 'อยู่มาเมื่อกษัตริย์ประทับในพระราชวังของพระองค์ และพระเยโฮวาห์ทรงโปรดให้พระองค์พักจากการรบศึกรอบด้าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 2, 'กษัตริย์ตรัสกับนาธันผู้พยากรณ์ว่า “ดูซิ เราอยู่ในบ้านทําด้วยไม้สนสีดาร์ แต่หีบของพระเจ้าอยู่ในผ้าม่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 3, 'และนาธันทูลกษัตริย์ว่า “ขอเชิญทรงกระทําทั้งสิ้นตามพระประสงค์ของพระองค์ เพราะพระเยโฮวาห์ทรงสถิตกับพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 4, 'แต่อยู่มาในคืนวันนั้นเอง พระวจนะของพระเยโฮวาห์มาถึงนาธันว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 5, '“จงไปบอกดาวิดผู้รับใช้ของเราว่า ‘พระเยโฮวาห์ตรัสดังนี้ว่า เจ้าจะสร้างนิเวศให้เราอยู่หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 6, 'เราไม่เคยอยู่ในนิเวศนับแต่วันที่เราพาคนอิสราเอลออกจากอียิปต์จนกระทั่งวันนี้ แต่เราก็ดําเนินท่ามกลางเต็นท์และพลับพลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 7, 'ในที่ต่างๆที่เราได้ดําเนินกับชนชาติอิสราเอลทั้งหมด เราได้เคยพูดสักคํากับตระกูลของอิสราเอลตระกูลใด ผู้ที่เราบัญชาให้เขาเลี้ยงดูอิสราเอลประชาชนของเราหรือว่า “ทําไมเจ้ามิได้สร้างนิเวศด้วยไม้สนสีดาร์ให้แก่เรา”’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 8, 'เพราะฉะนั้นบัดนี้เจ้าจงกล่าวแก่ดาวิดผู้รับใช้ของเราว่า ‘พระเยโฮวาห์จอมโยธาตรัสดังนี้ว่า เราเอาเจ้ามาจากทุ่งหญ้า จากการตามฝูงแพะแกะ เพื่อให้เจ้าเป็นเจ้าเหนืออิสราเอลประชาชนของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 9, 'เราได้อยู่กับเจ้าไม่ว่าเจ้าไปที่ไหน และได้ขจัดบรรดาศัตรูของเจ้าให้พ้นหน้าเจ้า และเรากระทําให้เจ้ามีชื่อเสียงใหญ่โต อย่างกับชื่อเสียงของผู้ใหญ่ในโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 10, 'และเราจะกําหนดที่หนึ่งให้อิสราเอลประชาชนของเรา และเราจะปลูกฝังเขาไว้ เพื่อเขาทั้งหลายจะได้อยู่ในที่ของเขาเอง และไม่ต้องถูกกวนใจอีก และคนชั่วจะไม่ข่มเหงเขาอีกดังแต่ก่อนมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 11, 'ตั้งแต่สมัยเมื่อเราตั้งผู้วินิจฉัยเหนืออิสราเอลประชาชนของเรา และเราให้เจ้าพ้นจากการรบศึกรอบด้าน ยิ่งกว่านั้นอีกพระเยโฮวาห์ตรัสแก่เจ้าว่าพระเยโฮวาห์จะทรงให้เจ้ามีราชวงศ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 12, 'เมื่อวันของเจ้าครบแล้ว และเจ้านอนพักอยู่กับบรรพบุรุษของเจ้า เราจะให้เชื้อสายของเจ้าที่มาภายหลังเจ้าเกิดขึ้นผู้ซึ่งเกิดมาจากบั้นเอวของเจ้าเอง และเราจะสถาปนาอาณาจักรของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 13, 'เขาจะเป็นผู้สร้างนิเวศเพื่อนามของเรา และเราจะสถาปนาบัลลังก์แห่งราชอาณาจักรของเขาให้อยู่เป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 14, 'เราจะเป็นบิดาของเขา และเขาจะเป็นบุตรของเรา ถ้าเขากระทําความชั่วช้า เราจะตีสอนเขาด้วยไม้เรียวของมนุษย์ ด้วยการเฆี่ยนแห่งบุตรทั้งหลายของมนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 15, 'แต่ความเมตตาของเราจะไม่พรากไปจากเขาเสีย ดังที่เราพรากไปจากซาอูล ซึ่งเราได้ถอดเสียให้พ้นหน้าเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 16, 'ราชวงศ์ของเจ้าและอาณาจักรของเจ้าจะดํารงอยู่ต่อหน้าเจ้าอย่างมั่นคงเป็นนิตย์ และบัลลังก์ของเจ้าจะถูกสถาปนาไว้เป็นนิตย์’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 17, 'นาธันก็กราบทูลดาวิดตามถ้อยคําเหล่านี้ทั้งสิ้นและตามนิมิตนี้ทั้งหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 18, 'แล้วกษัตริย์ดาวิดจึงเสด็จเข้าไปนั่งเฝ้าพระเยโฮวาห์ และกราบทูลว่า “โอ ข้าแต่องค์พระผู้เป็นเจ้าพระเจ้า ข้าพระองค์เป็นผู้ใดเล่า และวงศ์วานของข้าพระองค์เป็นผู้ใดพระองค์จึงทรงนําข้าพระองค์มาไกลถึงเพียงนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 19, 'โอ ข้าแต่องค์พระผู้เป็นเจ้าพระเจ้า แต่นี่ก็เป็นสิ่งเล็กน้อยในสายพระเนตรของพระองค์ และพระองค์ทรงลั่นพระวาจาถึงราชวงศ์ของผู้รับใช้พระองค์ในอนาคตอันไกลที่จะมาถึงนั้น โอ ข้าแต่องค์พระผู้เป็นเจ้าพระเจ้า และนี่เป็นธรรมดาของมนุษย์หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 20, 'ดาวิดจะกราบทูลประการใดอีกต่อพระองค์ได้เล่า ข้าแต่องค์พระผู้เป็นเจ้าพระเจ้า พระองค์ทรงรู้จักผู้รับใช้ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 21, 'ที่พระองค์ทรงกระทําสิ่งใหญ่โตนี้ทั้งสิ้น เพื่อให้ผู้รับใช้ของพระองค์ทราบก็เพราะเหตุพระวจนะของพระองค์ และตามชอบพระทัยของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 22, 'โอ ข้าแต่พระเยโฮวาห์พระเจ้า ฉะนั้นพระองค์ทรงยิ่งใหญ่ ไม่มีผู้ใดเหมือนพระองค์ ไม่มีพระเจ้านอกเหนือพระองค์ ตามสิ่งสารพัดที่หูของข้าพระองค์ทั้งหลายได้ยินมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 23, 'ประชาชนในโลกนี้จะเหมือนอิสราเอลประชาชนของพระองค์ ซึ่งพระเจ้าเสด็จไปทรงไถ่มาให้เป็นประชาชนของพระองค์ กระทําให้พระนามของพระองค์มีเกียรติ และทรงกระทําสิ่งที่ใหญ่เพื่อเจ้าทั้งหลาย และทรงกระทําสิ่งน่าสะพรึงกลัวเพื่อแผ่นดินของพระองค์ ต่อหน้าประชาชนของพระองค์ คือชนชาติซึ่งพระองค์ทรงไถ่ออกจากอียิปต์เพื่อพระองค์ จากบรรดาประชาชาติ และบรรดาพระของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 24, 'ด้วยว่าพระองค์ทรงสถาปนาอิสราเอลประชาชนของพระองค์ไว้ให้เป็นประชาชนเพื่อพระองค์เองเป็นนิตย์ ข้าแต่พระเยโฮวาห์ พระองค์ก็ทรงเป็นพระเจ้าของเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 25, 'โอ ข้าแต่พระเยโฮวาห์พระเจ้า บัดนี้พระวาทะซึ่งพระองค์ทรงลั่นออกมาเกี่ยวกับผู้รับใช้ของพระองค์ และเกี่ยวกับราชวงศ์ของเขา ขอทรงดํารงซึ่งพระวาทะนั้นให้ถาวรเป็นนิตย์ และทรงกระทําดังที่พระองค์ทรงลั่นพระวาจาไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 26, 'ขอพระนามของพระองค์เป็นที่สรรเสริญอยู่เป็นนิตย์ว่า ‘พระเยโฮวาห์จอมโยธาทรงเป็นพระเจ้าเหนืออิสราเอล’ และราชวงศ์ดาวิดผู้รับใช้ของพระองค์จะดํารงอยู่ต่อพระพักตร์พระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 27, 'โอ ข้าแต่พระเยโฮวาห์จอมโยธาพระเจ้าของอิสราเอล เพราะว่าพระองค์ได้ทรงสําแดงแก่ผู้รับใช้ของพระองค์ว่า ‘เราจะสร้างราชวงศ์ให้เจ้า’ เพราะฉะนั้นผู้รับใช้ของพระองค์จึงกล้าหาญที่จะวิงวอนด้วยคําอธิษฐานนี้ต่อพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 28, 'โอ ข้าแต่องค์พระผู้เป็นเจ้าพระเจ้า บัดนี้พระองค์ทรงเป็นพระเจ้า และบรรดาพระวาทะของพระองค์เป็นความจริง และพระองค์ทรงสัญญาจะพระราชทานสิ่งดีนี้แก่ผู้รับใช้ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 29, 'เพราะฉะนั้น บัดนี้ขอโปรดให้เป็นที่พอพระทัยพระองค์ที่จะอํานวยพระพรแก่ราชวงศ์ผู้รับใช้ของพระองค์ เพื่อให้ดํารงอยู่ต่อพระพักตร์พระองค์เป็นนิตย์ โอ ข้าแต่องค์พระผู้เป็นเจ้าพระเจ้า พระองค์ทรงลั่นพระวาจาเช่นนั้นแล้ว และด้วยพระพรของพระองค์ก็ขอให้ราชวงศ์ผู้รับใช้ของพระองค์ได้อยู่เย็นเป็นสุขเป็นนิตย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 1, 'อยู่มาภายหลัง ดาวิดทรงโจมตีคนฟีลิสเตีย และปราบปรามได้ และดาวิดทรงยึดเมืองเมเธกฮัมมาห์ได้จากมือคนฟีลิสเตีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 2, 'พระองค์ทรงชนะโมอับ ทรงวัดเขาด้วยเชือกวัด คือบังคับให้เรียงตัวเข้าแถวนอนลงที่พื้นดิน ทรงวัดดูแล้วให้ประหารเสียสองแถว และไว้ชีวิตเต็มหนึ่งแถว คนโมอับก็เป็นไพร่ของดาวิด และได้นําเครื่องบรรณาการมาถวาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 3, 'ดาวิดทรงรบชนะฮาดัดเอเซอร์โอรสเรโหบ กษัตริย์เมืองโศบาห์ เมื่อเสด็จไปฟื้นอํานาจของพระองค์ที่แม่น้ํายูเฟรติส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 4, 'และดาวิดทรงยึดรถรบหนึ่งพันคัน พลม้าเจ็ดร้อยคน ทหารราบสองหมื่นคน และดาวิดรับสั่งให้ตัดเอ็นขาม้ารถรบเสียให้หมด เหลือไว้ให้พอแก่รถรบหนึ่งร้อยคัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 5, 'และเมื่อคนซีเรียชาวเมืองดามัสกัสมาช่วยฮาดัดเอเซอร์กษัตริย์เมืองโศบาห์ ดาวิดทรงประหารคนซีเรียเสียสองหมื่นสองพันคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 6, 'แล้วดาวิดทรงตั้งทหารประจําป้อมไว้เหนือคนซีเรียชาวเมืองดามัสกัสหลายกอง และคนซีเรียก็เป็นพลไพร่ของดาวิด และนําเครื่องบรรณาการไปถวาย พระเยโฮวาห์ทรงประทานชัยชนะแก่ดาวิดไม่ว่าจะไปรบ ณ ที่ใดๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 7, 'และดาวิดทรงนําโล่ทองคําที่ข้าราชการทหารของฮาดัดเอเซอร์ถือนั้นไปยังกรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 8, 'และกษัตริย์ดาวิดทรงริบทองเหลืองเป็นอันมากไปจากเมืองเบทาห์ และเมืองเบโรธัยหัวเมืองของฮาดัดเอเซอร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 9, 'เมื่อโทอิกษัตริย์เมืองฮามัทได้ยินว่าดาวิดรบชนะกองทัพทั้งสิ้นของฮาดัดเอเซอร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 10, 'โทอิก็ส่งโยรัมโอรสของตนไปเฝ้ากษัตริย์ดาวิด ถวายพระพรและแสดงความยินดีที่ดาวิดทรงรบชนะฮาดัดเอเซอร์ เพราะว่าฮาดัดเอเซอร์เคยทําสงครามกับโทอิ และโยรัมได้นําเครื่องเงิน เครื่องทองคํา และเครื่องทองเหลืองไปถวาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 11, 'สิ่งเหล่านี้ กษัตริย์ดาวิดทรงนํามอบถวายแด่พระเยโฮวาห์ พร้อมกับบรรดาเงินและทองคําซึ่งพระองค์ทรงได้มาจากบรรดาประชาชาติที่พระองค์ทรงรบชนะและยึดครอง และทรงนํามามอบถวาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 12, 'คือได้มาจากซีเรีย โมอับ คนอัมโมน คนฟีลิสเตีย อามาเลข และจากของที่ริบมาจากฮาดัดเอเซอร์โอรสของเรโหบ กษัตริย์เมืองโศบาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 13, 'เมื่อดาวิดเสด็จกลับจากการประหารคนซีเรียเสียในหุบเขาเกลือหนึ่งหมื่นแปดพันคน พระนามของพระองค์ก็เลื่องลือไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 14, 'และพระองค์ทรงตั้งทหารประจําป้อมขึ้นเหนือเมืองเอโดม พระองค์ทรงตั้งทหารประจําป้อมในเอโดมทั่วไปหมด และคนเอโดมทั้งสิ้นจึงเป็นพลไพร่ของดาวิด และพระเยโฮวาห์ทรงประทานชัยชนะแก่ดาวิดไม่ว่าจะเสด็จไปรบ ณ ที่ใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 15, 'ดังนั้นดาวิดจึงทรงปกครองเหนืออิสราเอลทั้งสิ้น และดาวิดทรงให้ความยุติธรรมและความเที่ยงธรรมแก่ชนชาติของพระองค์ทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 16, 'และโยอาบบุตรชายนางเศรุยาห์เป็นแม่ทัพ และเยโฮชาฟัทบุตรชายอาหิลูดเป็นเจ้ากรมสารบรรณ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 17, 'ศาโดกบุตรชายอาหิทูบและอาหิเมเลคบุตรชายอาบียาธาร์เป็นปุโรหิต และเสไรอาห์เป็นราชเลขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 18, 'และเบไนยาห์บุตรชายเยโฮยาดาเป็นผู้บังคับบัญชาคนเคเรธีและคนเปเลท และบรรดาราชโอรสของดาวิดเป็นประมุข');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 1, 'ดาวิดรับสั่งว่า “วงศ์วานของซาอูลนั้นมีเหลืออยู่บ้างหรือ เพื่อเราจะสําแดงความเมตตาแก่ผู้นั้นโดยเห็นแก่โยนาธาน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 2, 'มีมหาดเล็กในวงศ์วานซาอูลคนหนึ่งชื่อศิบา เขาก็เรียกให้มาเฝ้าดาวิดและกษัตริย์ตรัสกับเขาว่า “เจ้าคือศิบาหรือ” เขาทูลตอบว่า “ข้าพระองค์คือศิบา พ่ะย่ะค่ะ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 3, 'กษัตริย์จึงตรัสว่า “ไม่มีใครในวงศ์วานซาอูลยังเหลืออยู่บ้างหรือ เพื่อเราจะได้แสดงความเมตตาของพระเจ้าต่อเขา” ศิบากราบทูลกษัตริย์ว่า “ยังมีโอรสของโยนาธานเหลืออยู่คนหนึ่ง เท้าของเขาเป็นง่อยพ่ะย่ะค่ะ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 4, 'กษัตริย์ตรัสถามเขาว่า “เขาอยู่ที่ไหน” ศิบาจึงกราบทูลกษัตริย์ว่า “ดูเถิด เขาอยู่ในเรือนของมาคีร์บุตรอัมมีเอลในเมืองโลเดบาร์ พ่ะย่ะค่ะ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 5, 'แล้วกษัตริย์ดาวิดรับสั่งให้คนไปนําเขามาจากเรือนของมาคีร์บุตรชายอัมมีเอลที่โลเดบาร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 6, 'เมฟีโบเชทโอรสของโยนาธานราชโอรสของซาอูลได้มาเฝ้าดาวิดและซบหน้าลงกราบถวายบังคม และดาวิดตรัสว่า “เมฟีโบเชทเอ๋ย” เขาทูลตอบว่า “ดูเถิด ผู้รับใช้ของพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 7, 'และดาวิดตรัสกับท่านว่า “อย่ากลัวเลย เพราะเราจะสําแดงความเมตตาต่อท่านเพื่อเห็นแก่โยนาธานบิดาของท่าน และเราจะมอบที่ดินทั้งหมดของซาอูลราชบิดาของท่านคืนแก่ท่าน และท่านจงรับประทานอาหารอยู่ที่โต๊ะของเราเสมอไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 8, 'และท่านก็กราบถวายบังคมและทูลว่า “ผู้รับใช้ของพระองค์เป็นผู้ใดเล่า ซึ่งพระองค์จะทอดพระเนตรสุนัขตายอย่างข้าพระองค์นี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 9, 'แล้วกษัตริย์ตรัสเรียกศิบามหาดเล็กของซาอูล และตรัสแก่เขาว่า “บรรดาสิ่งของที่เป็นของซาอูลและของวงศ์วานทั้งสิ้นของท่าน เราได้มอบให้แก่โอรสเจ้านายของเจ้าแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 10, 'ตัวเจ้าและพวกบุตรชายของเจ้าและเหล่าคนใช้ของเจ้า ต้องทํานาให้เขา และนําผลพืชที่ได้นั้นเข้ามา เพื่อโอรสแห่งเจ้านายของเจ้าจะได้มีอาหารรับประทาน แต่เมฟีโบเชทโอรสแห่งเจ้านายของเจ้านั้น จะรับประทานอาหารที่โต๊ะของเราเสมอไป” ฝ่ายศิบามีบุตรชายสิบห้าคนกับคนใช้ยี่สิบคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 11, 'แล้วศิบาจึงกราบทูลกษัตริย์ว่า “ตามที่กษัตริย์เจ้านายของข้าพระองค์บัญชาผู้รับใช้ของพระองค์นั้น ผู้รับใช้ของพระองค์จะกระทํา” กษัตริย์ได้ตรัสว่า “เมฟีโบเชทจงรับประทานที่โต๊ะเสวยของเรา อย่างกับเป็นโอรสของกษัตริย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 12, 'เมฟีโบเชทมีบุตรชายเล็กคนหนึ่งชื่อมีคา ทุกคนที่อาศัยอยู่ในเรือนของศิบาก็ได้เป็นมหาดเล็กของเมฟีโบเชท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 13, 'ดังนั้นเมฟีโบเชทจึงอยู่ในเยรูซาเล็ม เพราะท่านรับประทานที่โต๊ะของกษัตริย์เสมอ เท้าของท่านเป็นง่อยทั้งสองข้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 1, 'อยู่มาภายหลังกษัตริย์แห่งคนอัมโมนก็สิ้นพระชนม์ และฮานูนราชโอรสได้เสวยราชสมบัติแทน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 2, 'ดาวิดจึงตรัสว่า “เราจะแสดงความเมตตาต่อฮานูนราชโอรสของนาหาช ดังที่บิดาของเขาแสดงความเมตตาต่อเรา” ดาวิดจึงส่งพวกข้าราชการของพระองค์ไปเล้าโลมท่านเกี่ยวด้วยเรื่องราชบิดาของท่าน และข้าราชการของดาวิดก็เข้ามาในแผ่นดินของคนอัมโมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 3, 'แต่บรรดาเจ้านายของคนอัมโมนทูลฮานูนเจ้านายของตนว่า “พระองค์ดําริว่าดาวิดส่งผู้เล้าโลมมาหาพระองค์ เพราะนับถือพระราชบิดาของพระองค์เช่นนั้นหรือ ดาวิดมิได้ส่งข้าราชการมาเพื่อตรวจเมืองและสอดแนมดู และเพื่อจะคว่ําเมืองนี้เสียดอกหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 4, 'ฮานูนจึงจับข้าราชการของดาวิดมาโกนเคราออกเสียครึ่งหนึ่งและตัดเครื่องแต่งกายของเขาออกเสียที่ตรงกลางตรงสะโพก แล้วปล่อยตัวไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 5, 'เมื่อมีคนไปกราบทูลดาวิดให้ทรงทราบ พระองค์ก็รับสั่งให้คนไปรับข้าราชการเหล่านั้น เพราะว่าเขาทั้งหลายได้รับความอับอายมาก และกษัตริย์ตรัสว่า “จงพักอยู่ที่เมืองเยรีโคจนกว่าเคราของท่านทั้งหลายจะขึ้นแล้วจึงค่อยกลับมา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 6, 'เมื่อคนอัมโมนเห็นว่าเขาทั้งหลายเป็นที่เกลียดชังแก่ดาวิด คนอัมโมนจึงส่งคนไปจ้างคนซีเรียชาวเมืองเบธเรโหบ และคนซีเรียชาวเมืองโศบาห์ เป็นทหารราบจํานวนสองหมื่นคน จากกษัตริย์เมืองมาอาคาห์หนึ่งพันคน และชาวเมืองอิชโทบหนึ่งหมื่นสองพันคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 7, 'เมื่อดาวิดทรงได้ยินเช่นนั้นจึงรับสั่งโยอาบและพลโยธาคนแกล้วกล้าทั้งสิ้นให้ไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 8, 'ฝ่ายคนอัมโมนก็ยกออกมาและจัดทัพไว้ที่ทางเข้าประตูเมือง ฝ่ายคนซีเรียชาวเมืองโศบาห์และชาวเมืองเรโหบ กับคนเมืองอิชโทบ และเมืองมาอาคาห์อยู่ที่ชนบทกลางแจ้งต่างหาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 9, 'เมื่อโยอาบเห็นว่าการศึกนี้ขนาบอยู่ทั้งข้างหน้าและข้างหลัง ท่านจึงคัดเอาบรรดาคนอิสราเอลที่สรรไว้แล้วจัดทัพเข้าสู้คนซีเรีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 10, 'ท่านมอบคนที่เหลืออยู่ไว้ในบังคับบัญชาของอาบีชัยน้องชายของท่าน และเขาก็จัดคนเหล่านั้นเข้าต่อสู้กับคนอัมโมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 11, 'ท่านกล่าวว่า “ถ้ากําลังคนซีเรียแข็งเหลือกําลังของเรา เจ้าจงยกไปช่วยเรา แต่ถ้ากําลังคนอัมโมนแข็งเกินกําลังของเจ้า เราจะยกมาช่วยเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 12, 'จงมีความกล้าหาญเถิด ให้เราเป็นลูกผู้ชายเพื่อชนชาติของเรา และเพื่อหัวเมืองแห่งพระเจ้าของเรา และขอพระเยโฮวาห์ทรงกระทําตามที่พระองค์ทรงเห็นชอบเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 13, 'ดังนั้น โยอาบกับประชาชนที่อยู่กับท่านก็ยกเข้าใกล้ต่อสู้กับคนซีเรีย ข้าศึกก็แตกหนีไปต่อหน้าเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 14, 'เมื่อคนอัมโมนเห็นว่าคนซีเรียหนีไปแล้ว เขาทั้งหลายก็หนีอาบีชัยเข้าไปในเมือง แล้วโยอาบก็กลับจากการสู้รบกับคนอัมโมนมายังกรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 15, 'ครั้นคนซีเรียเห็นว่าตนพ่ายแพ้ต่ออิสราเอลแล้ว จึงรวบรวมเข้าด้วยกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 16, 'ฝ่ายฮาดัดเอเซอร์ทรงใช้คนไปนําคนซีเรียผู้อยู่ฟากแม่น้ําข้างโน้นออกมา เขามายังตําบลเฮลาม มีโชบัคแม่ทัพของฮาดัดเอเซอร์เป็นผู้นําหน้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 17, 'เมื่อมีผู้กราบทูลดาวิดพระองค์ทรงรวบรวมอิสราเอลทั้งหมดข้ามแม่น้ําจอร์แดนมาถึงตําบลเฮลาม และคนซีเรียก็จัดทัพเข้าต่อสู้ดาวิดและได้รบกับพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 18, 'คนซีเรียก็หนีจากอิสราเอล และดาวิดทรงประหารคนซีเรียซึ่งเป็นทหารรถรบเจ็ดร้อยคนกับทหารม้าสี่หมื่นคนเสีย และประหารโชบัคแม่ทัพของเขาทั้งหลายให้สิ้นชีวิตเสียที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 19, 'และเมื่อบรรดากษัตริย์ซึ่งขึ้นกับฮาดัดเอเซอร์เห็นว่าตนพ่ายแพ้ต่อหน้าอิสราเอลแล้ว เขาก็ได้กระทําสันติภาพกับอิสราเอล และยอมเป็นผู้รับใช้คนอิสราเอล ดังนั้นคนซีเรียจึงกลัวไม่กล้าช่วยคนอัมโมนอีกต่อไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 1, 'และอยู่มาพอสิ้นปีแล้วเมื่อบรรดากษัตริย์ยกกองทัพออกไปรบ ดาวิดทรงใช้โยอาบพร้อมกับพวกข้าราชการและอิสราเอลทั้งหมด เขาไปกวาดล้างคนอัมโมนและล้อมเมืองรับบาห์ไว้ แต่ดาวิดประทับที่เยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 2, 'อยู่มาเวลาเย็นวันหนึ่งเมื่อดาวิดทรงลุกขึ้นจากพระแท่น และดําเนินอยู่บนดาดฟ้าหลังคาพระราชวัง ทอดพระเนตรจากหลังคาเห็นผู้หญิงคนหนึ่งอาบน้ําอยู่ หญิงคนนั้นสวยงามมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 3, 'ดาวิดทรงใช้คนไปไต่ถามเรื่องผู้หญิงคนนั้น คนหนึ่งมากราบทูลว่า “หญิงคนนี้ชื่อบัทเชบา บุตรสาวของเอลีอัม ภรรยาของอุรีอาห์คนฮิตไทต์มิใช่หรือพ่ะย่ะค่ะ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 4, 'ดาวิดก็ทรงใช้ผู้สื่อสารไปรับนางมา นางก็มาเฝ้าพระองค์ แล้วพระองค์ทรงร่วมหลับนอนกับนาง พอดีนางได้ชําระตัวให้สิ้นมลทินของนางแล้ว แล้วนางก็กลับไปเรือนของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 5, 'ผู้หญิงนั้นก็ตั้งครรภ์ นางจึงใช้คนไปกราบทูลดาวิดว่า “หม่อมฉันตั้งครรภ์แล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 6, 'ดาวิดทรงใช้คนไปบอกโยอาบว่า “จงส่งอุรีอาห์คนฮิตไทต์มาให้เรา” โยอาบก็ส่งตัวอุรีอาห์ไปให้ดาวิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 7, 'เมื่ออุรีอาห์เข้าเฝ้าพระองค์ ดาวิดรับสั่งถามว่าโยอาบเป็นอย่างไรบ้าง พวกพลเป็นอย่างไร การสงครามคืบหน้าไปอย่างไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 8, 'แล้วดาวิดรับสั่งอุรีอาห์ว่า “จงลงไปบ้านของเจ้า และล้างเท้าของเจ้าเสีย” อุรีอาห์ก็ออกไปจากพระราชวัง และมีคนนําของประทานจากกษัตริย์ตามไปให้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 9, 'แต่อุรีอาห์ได้นอนเสียที่ประตูพระราชวังพร้อมกับบรรดาข้าราชการของเจ้านายของเขา มิได้ลงไปที่บ้านของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 10, 'เมื่อมีคนกราบทูลดาวิดว่า “อุรีอาห์ไม่ได้ลงไปที่บ้านของเขาพ่ะย่ะค่ะ” ดาวิดรับสั่งแก่อุรีอาห์ว่า “เจ้ามิได้เดินทางมาดอกหรือ ทําไมจึงไม่ลงไปบ้านของเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 11, 'อุรีอาห์ทูลตอบดาวิดว่า “หีบพันธสัญญาและอิสราเอลกับยูดาห์อยู่ในทับอาศัย โยอาบเจ้านายของข้าพระองค์กับบรรดาข้าราชการของพระองค์ตั้งค่ายอยู่ที่พื้นทุ่ง ส่วนข้าพระองค์จะไปบ้าน ไปกิน ไปดื่ม และนอนกับภรรยาของข้าพระองค์เช่นนั้นหรือ พ่ะย่ะค่ะ พระองค์ทรงพระชนม์อยู่และจิตวิญญาณของพระองค์มีชีวิตอยู่แน่ฉันใด ข้าพระองค์จะไม่กระทําอย่างนี้เลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 12, 'แล้วดาวิดก็รับสั่งแก่อุรีอาห์ว่า “วันนี้ก็ค้างเสียที่นี่เถิด พรุ่งนี้เราจะให้เจ้าไป” อุรีอาห์ก็ค้างอยู่ในกรุงเยรูซาเล็มในวันนั้นและในวันรุ่งขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 13, 'ดาวิดทรงเชิญเขามา เขาก็มารับประทานและดื่มต่อพระพักตร์ และพระองค์ทรงกระทําให้เขามึนเมา ในเย็นวันนั้นเขาก็ออกไปนอนบนที่นอนกับข้าราชการของเจ้านายของเขา แต่มิได้ลงไปบ้าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 14, 'ต่อมาครั้นรุ่งเช้าดาวิดทรงอักษรถึงโยอาบและทรงฝากไปในมือของอุรีอาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 15, 'ในลายพระหัตถ์นั้นว่า “จงตั้งอุรีอาห์ให้เป็นกองหน้าเข้าสู้รบตรงที่ดุเดือดที่สุดแล้วล่าทัพกลับเสียเพื่อให้เขาถูกโจมตีให้ตาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 16, 'อยู่มาเมื่อโยอาบกําลังเฝ้าล้อมเมืองอยู่ ท่านจึงกําหนดให้อุรีอาห์ไปรบตรงที่ที่ท่านทราบว่ามีทหารเข้มแข็งมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 17, 'คนในเมืองก็ออกมาสู้รบกับโยอาบ มีคนตายบ้างคือข้าราชการบางคนของดาวิดได้ล้มตาย อุรีอาห์คนฮิตไทต์ก็ตายด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 18, 'โยอาบจึงส่งคนไปกราบทูลข่าวการรบทั้งสิ้นต่อดาวิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 19, 'ท่านได้สั่งผู้สื่อสารนั้นว่า “เมื่อเจ้ากราบทูลข่าวการรบต่อกษัตริย์เสร็จทุกประการแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 20, 'ถ้ากษัตริย์กริ้วและตรัสถามเจ้าว่า ‘ทําไมเจ้าทั้งหลายจึงยกเข้ารบใกล้เมืองนัก เจ้าไม่ทราบหรือว่าเขาจะยิงออกมาจากกําแพง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 21, 'ใครฆ่าอาบีเมเลคบุตรเยรุบเบเชท ไม่ใช่ผู้หญิงคนหนึ่งเอาหินโม่ท่อนบนทุ่มเขาจากกําแพงเมืองจนเขาตายเสียที่เมืองเธเบศดอกหรือ ทําไมเจ้าทั้งหลายจึงเข้าไปใกล้กําแพง’ แล้วเจ้าจงกราบทูลว่า ‘อุรีอาห์คนฮิตไทต์ผู้รับใช้ของพระองค์ก็ตายด้วย’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 22, 'ผู้สื่อสารก็ไป เขามาทูลต่อดาวิดถึงทุกอย่างที่โยอาบสั่งเขาให้มากราบทูล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 23, 'ผู้สื่อสารนั้นกราบทูลดาวิดว่า “ข้าศึกได้เปรียบต่อเรามาก และได้ออกมาสู้รบกับฝ่ายเราที่กลางทุ่ง แต่เราได้ขับไล่เขาเข้าไปถึงทางเข้าประตูเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 24, 'แล้วทหารธนูก็ยิงข้าราชการของพระองค์จากกําแพง ข้าราชการของกษัตริย์บางคนก็สิ้นชีวิต และอุรีอาห์คนฮิตไทต์ข้าราชการของพระองค์ก็สิ้นชีวิตด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 25, 'ดาวิดก็รับสั่งผู้สื่อสารนั้นว่า “เจ้าจงบอกโยอาบดังนี้ว่า ‘อย่าให้เรื่องนี้ทําให้ท่านลําบากใจ เพราะดาบย่อมสังหารไม่เลือกว่าคนนั้นหรือคนนี้ จงสู้รบหนักเข้าไปและตีเอาเมืองนั้นเสียให้ได้’ เจ้าจงหนุนน้ําใจท่านด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 26, 'เมื่อภรรยาของอุรีอาห์ได้ยินข่าวว่าอุรีอาห์สามีของตนสิ้นชีวิตแล้ว นางก็คร่ําครวญด้วยเรื่องสามีของนาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 27, 'เมื่อสิ้นการไว้ทุกข์แล้วดาวิดก็ส่งคนไปให้พานางมาที่พระราชวัง และนางก็ได้เป็นมเหสีของพระองค์ ประสูติโอรสองค์หนึ่งให้พระองค์ แต่สิ่งซึ่งดาวิดทรงกระทํานั้นไม่เป็นที่พอพระทัยพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 1, 'พระเยโฮวาห์ทรงใช้ให้นาธันไปหาดาวิด นาธันก็ไปเข้าเฝ้าและกราบทูลพระองค์ว่า “ในเมืองหนึ่งมีชายสองคน คนหนึ่งมั่งมี อีกคนหนึ่งยากจน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 2, 'คนมั่งมีนั้นมีแพะแกะและวัวเป็นอันมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 3, 'แต่คนจนนั้นไม่มีอะไรเลย เว้นแต่แกะตัวเมียตัวเดียวที่เขาซื้อมา ซึ่งเขาเลี้ยงไว้และอยู่กับเขา มันได้เติบโตขึ้นพร้อมกับบุตรของเขา กินอาหารร่วมและดื่มน้ําถ้วยเดียวกับเขา นอนในอกของเขา และเป็นเหมือนบุตรสาวของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 4, 'ฝ่ายคนมั่งมีคนนั้นมีแขกคนหนึ่งมาเยี่ยม เขาเสียดายที่จะเอาแพะแกะหรือวัวของตนมาทําอาหารเลี้ยงคนที่เดินทางมาเยี่ยมนั้น จึงเอาแกะตัวเมียของชายคนจนนั้นเตรียมเป็นอาหารให้แก่ชายที่มาเยี่ยมตน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 5, 'ดาวิดกริ้วชายคนนั้นมาก และรับสั่งแก่นาธันว่า “พระเยโฮวาห์ทรงพระชนม์อยู่แน่ฉันใด ผู้ชายที่กระทําเช่นนั้นจะต้องตายแน่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 6, 'และจะต้องคืนแกะให้สี่เท่า เพราะเขาได้กระทําอย่างนี้ และเพราะว่าเขาไม่มีเมตตาจิต”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 7, 'นาธันจึงทูลดาวิดว่า “พระองค์นั่นแหละคือชายคนนั้น พระเยโฮวาห์พระเจ้าแห่งอิสราเอลตรัสดังนี้ว่า ‘เราได้เจิมตั้งเจ้าไว้ให้เป็นกษัตริย์เหนืออิสราเอล และเราช่วยเจ้าให้พ้นจากมือของซาอูล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 8, 'และเราได้มอบวงศ์วานเจ้านายของเจ้าให้แก่เจ้า และได้มอบภรรยาเจ้านายของเจ้าไว้ในอกของเจ้า และมอบวงศ์วานอิสราเอลและวงศ์วานยูดาห์ให้แก่เจ้า ถ้าเท่านี้ยังน้อยไป เราจะเพิ่มให้อีกเท่านี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 9, 'ทําไมเจ้าดูหมิ่นพระบัญญัติของพระเยโฮวาห์กระทําชั่วในสายพระเนตรของพระองค์ เจ้าได้ฆ่าอุรีอาห์คนฮิตไทต์เสียด้วยดาบ เอาภรรยาของเขามาเป็นภรรยาของตน และได้สังหารเขาเสียด้วยดาบของคนอัมโมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 10, 'เพราะฉะนั้นบัดนี้ดาบนั้นจะไม่คลาดไปจากราชวงศ์ของเจ้า เพราะเจ้าได้ดูหมิ่นเรา เอาภรรยาของอุรีอาห์คนฮิตไทต์มาเป็นภรรยาของเจ้า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 11, 'พระเยโฮวาห์ตรัสดังนี้ว่า ‘ดูเถิด เราจะให้เหตุร้ายบังเกิดขึ้นกับเจ้าจากครัวเรือนของเจ้าเอง และเราจะเอาภรรยาของเจ้าไปต่อหน้าต่อตาเจ้า ยกไปให้แก่เพื่อนบ้านของเจ้า ผู้นั้นจะนอนร่วมกับภรรยาของเจ้าอย่างเปิดเผย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 12, 'เพราะเจ้าทําการนั้นอย่างลับๆ แต่เราจะกระทําการนี้ต่อหน้าอิสราเอลทั้งสิ้นและอย่างเปิดเผย’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 13, 'ดาวิดจึงรับสั่งกับนาธันว่า “เรากระทําบาปต่อพระเยโฮวาห์แล้ว” และนาธันกราบทูลดาวิดว่า “พระเยโฮวาห์ทรงให้อภัยบาปของพระองค์แล้ว พระองค์จะไม่ถึงแก่มรณา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 14, 'อย่างไรก็ตาม เพราะด้วยการกระทํานี้พระองค์ได้ให้พวกศัตรูของพระเยโฮวาห์มีโอกาสเหยียดหยามได้ ราชบุตรที่จะประสูติมานั้นจะต้องสิ้นชีวิต”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 15, 'แล้วนาธันก็กลับไปยังบ้านของตน แล้วพระเยโฮวาห์ทรงกระทําแก่บุตร ซึ่งภรรยาของอุรีอาห์บังเกิดกับดาวิด และพระกุมารนั้นก็ประชวรหนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 16, 'ดาวิดก็ทรงอ้อนวอนต่อพระเจ้าเพื่อพระกุมารนั้น และดาวิดทรงอดพระกระยาหาร และเข้าไปบรรทมบนพื้นดินคืนยังรุ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 17, 'บรรดาพวกผู้ใหญ่ในราชสํานักของพระองค์ก็ลุกขึ้นมายืนเข้าเฝ้าอยู่ หมายจะทูลเชิญให้พระองค์ทรงลุกจากพื้นดิน แต่พระองค์หาทรงยอมไม่ หรือหาทรงรับประทานกับเขาทั้งหลายไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 18, 'อยู่มาพอวันที่เจ็ดพระกุมารนั้นก็สิ้นพระชนม์ ส่วนข้าราชการของดาวิดก็กลัวไม่กล้ากราบทูลดาวิดว่าพระกุมารนั้นสิ้นชีวิตแล้ว เขาพูดกันว่า “ดูเถิด เมื่อพระกุมารนั้นทรงพระชนม์อยู่ เราทูลพระองค์ พระองค์หาทรงฟังเสียงของเราไม่ แล้วเราทั้งหลายอาจจะกราบทูลได้อย่างไรว่า พระกุมารนั้นสิ้นพระชนม์แล้ว พระองค์ก็จะกระทําอันตรายต่อพระองค์เอง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 19, 'แต่เมื่อดาวิดทอดพระเนตรเห็นข้าราชการกระซิบกระซาบกันอยู่ ดาวิดเข้าพระทัยว่าพระกุมารนั้นสิ้นพระชนม์แล้ว ดาวิดจึงรับสั่งถามข้าราชการของพระองค์ว่า “เด็กนั้นสิ้นชีวิตแล้วหรือ” เขาทูลตอบว่า “สิ้นชีวิตแล้วพ่ะย่ะค่ะ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 20, 'แล้วดาวิดทรงลุกขึ้นจากพื้นดิน ชําระพระกาย ชโลมพระองค์ และทรงเปลี่ยนฉลองพระองค์ ทรงดําเนินเข้าไปในพระนิเวศของพระเยโฮวาห์และทรงนมัสการ แล้วเสด็จไปสู่พระราชวังของพระองค์ รับสั่งให้นําพระกระยาหารมา เขาก็จัดพระกระยาหารให้พระองค์เสวย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 21, 'ข้าราชการจึงทูลถามพระองค์ว่า “เป็นไฉนพระองค์ทรงกระทําเช่นนี้ พระองค์ทรงอดพระกระยาหารและกันแสงเพื่อพระกุมารนั้นเมื่อทรงพระชนม์อยู่ แต่เมื่อพระกุมารนั้นสิ้นพระชนม์แล้ว พระองค์ก็ทรงลุกขึ้นเสวยพระกระยาหาร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 22, 'พระองค์รับสั่งว่า “เมื่อเด็กนั้นมีชีวิตอยู่ เราอดอาหารและร้องไห้ เพราะเราว่า ‘ใครจะทราบได้ว่าพระเจ้าจะทรงพระเมตตาเรา โปรดให้เด็กนั้นมีชีวิตอยู่หรือไม่’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 23, 'แต่เมื่อเขาสิ้นชีวิตแล้ว เราจะอดอาหารทําไม เราจะทําเด็กให้ฟื้นขึ้นมาอีกได้หรือ มีแต่เราจะตามทางเด็กนั้นไป เขาจะกลับมาหาเราหามิได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 24, 'ฝ่ายดาวิดทรงเล้าโลมใจบัทเชบามเหสีของพระองค์ และทรงเข้าไปร่วมหลับนอนกับพระนาง พระนางก็ประสูติบุตรชายคนหนึ่งเรียกชื่อว่าซาโลมอน และพระเยโฮวาห์ทรงรักซาโลมอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 25, 'และทรงใช้นาธันผู้พยากรณ์ไป ท่านจึงตั้งชื่อราชโอรสนั้นว่า เยดีดิยาห์ เพราะเห็นแก่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 26, 'ฝ่ายโยอาบสู้รบกับเมืองรับบาห์ของคนอัมโมน และยึดราชธานีไว้ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 27, 'และโยอาบได้ส่งผู้สื่อสารไปเฝ้าดาวิด ทูลว่า “ข้าพระองค์ได้สู้รบกับกรุงรับบาห์ และข้าพระองค์ตีได้เมืองที่มีแม่น้ํามากหลายนั้นแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 28, 'ฉะนั้นบัดนี้ขอพระองค์ทรงรวบรวมพลที่เหลือ เข้าตั้งค่ายตีเมืองนั้นให้ได้ เกลือกว่าถ้าข้าพระองค์ตีได้ ก็จะต้องเรียกชื่อเมืองนั้นตามชื่อของข้าพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 29, 'ดาวิดจึงทรงรวบรวมพลทั้งหลายเข้าด้วยกันยกไปยังเมืองรับบาห์ และต่อสู้จนยึดเมืองนั้นได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 30, 'ทรงริบมงกุฎจากเศียรกษัตริย์ของเมืองนั้น มงกุฎนั้นเป็นทองคําหนักหนึ่งตะลันต์ประดับด้วยเพชรพลอยต่างๆ และเขาก็สวมบนพระเศียรของดาวิด และพระองค์ทรงเก็บรวบรวมทรัพย์สมบัติของเมืองนั้นได้เป็นอันมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 31, 'ทรงควบคุมประชาชนที่อยู่ในเมืองนั้นให้ทํางานด้วยเลื่อย คราดเหล็กและขวานเหล็กและบังคับให้ทํางานที่เตาเผาอิฐ ได้ทรงกระทําเช่นนี้แก่บรรดาหัวเมืองของคนอัมโมนทั่วไป แล้วดาวิดก็เสด็จกลับไปกรุงเยรูซาเล็มพร้อมกับพลทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 1, 'ต่อมาภายหลังฝ่ายอับซาโลมราชโอรสของดาวิดมีขนิษฐาองค์หนึ่งรูปโฉมสะคราญชื่อทามาร์ และอัมโนนราชโอรสของดาวิดก็รักเธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 2, 'ด้วยเหตุทามาร์น้องหญิงนี้ จิตใจของอัมโนนก็ถูกทรมานจนถึงกับล้มป่วย ด้วยเหตุว่าเธอเป็นสาวพรหมจารี อัมโนนจึงรู้สึกว่าจะทําอะไรกับเธอก็ยากนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 3, 'แต่อัมโนนมีสหายคนหนึ่งชื่อโยนาดับบุตรชายของชิเมอาห์เชษฐาของดาวิด โยนาดับนั้นเป็นคนเจ้าปัญญา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 4, 'จึงทูลถามว่า “ข้าแต่ราชโอรสของกษัตริย์ ไฉนท่านจึงซึมเศร้าอยู่ทุกๆวัน จะไม่บอกให้ข้าพเจ้าทราบบ้างหรือ” อัมโนนตอบเขาว่า “ข้าพเจ้ารักทามาร์น้องหญิงของอับซาโลมอนุชาของข้าพเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 5, 'โยนาดับจึงทูลท่านว่า “ขอเชิญบรรทมบนพระแท่นแสร้งกระทําเป็นประชวร และเมื่อเสด็จพ่อมาเยี่ยมท่านขอกราบทูลว่า ‘ขอโปรดรับสั่งทามาร์น้องหญิงมาให้อาหารแก่ข้าพระองค์ ให้มาเตรียมอาหารต่อสายตาข้าพระองค์ เพื่อข้าพระองค์จะได้เห็น และได้รับประทานจากมือของเธอ’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 6, 'อัมโนนจึงบรรทมแสร้งทําเป็นประชวร เมื่อกษัตริย์เสด็จมาเยี่ยม อัมโนนก็ทูลกษัตริย์ว่า “ขอโปรดให้ทามาร์น้องหญิงมาทําขนมสักสองอันต่อสายตาข้าพระองค์ เพื่อข้าพระองค์จะได้รับประทานจากมือของเธอ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 7, 'ดาวิดทรงใช้คนไปหาทามาร์ที่วังรับสั่งว่า “ขอจงไปที่บ้านของอัมโนนพี่ของเจ้า และเตรียมอาหารให้เขารับประทาน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 8, 'ทามาร์ก็ไปยังวังของอัมโนนเชษฐาของเธอที่ที่เขาบรรทมอยู่ เธอก็หยิบแป้งมานวดทําขนมต่อสายตาของเชษฐาแล้วปิ้งขนมนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 9, 'และเธอก็ยกกระทะมาเทออกต่อหน้าเชษฐา แต่อัมโนนก็ไม่ทรงเสวย กล่าวว่า “ให้ทุกคนออกไปเสียให้พ้นเรา” ทุกคนก็ออกไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 10, 'อัมโนนก็รับสั่งกับทามาร์ว่า “จงเอาอาหารเข้ามาในห้องใน เพื่อพี่จะได้รับประทานจากมือของน้อง” ทามาร์ก็นําขนมที่เธอทํานั้นเข้าไปในห้องเพื่อให้แก่อัมโนนเชษฐา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 11, 'แต่เมื่อเธอนําขนมมาใกล้เพื่อให้ท่านรับประทาน ท่านก็จับมือเธอไว้รับสั่งว่า “น้องของพี่เข้ามานอนกับพี่เถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 12, 'เธอจึงตอบท่านว่า “ไม่ได้ดอกพระเชษฐา ขออย่าบังคับน้องเลย สิ่งอย่างนี้เขาไม่กระทํากันในอิสราเอล ขออย่ากระทําการโฉดเขลาอย่างนี้เลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 13, 'ฝ่ายหม่อมฉัน หม่อมฉันจะเอาความอายไปซ่อนไว้ที่ไหน ฝ่ายท่านเล่า ท่านจะเป็นเหมือนคนโฉดเขลาคนหนึ่งในอิสราเอล เพราะฉะนั้นบัดนี้ขอทูลกษัตริย์ พระองค์คงจะไม่หวงหม่อมฉันไว้ไม่ให้ท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 14, 'แต่ท่านก็หาฟังเสียงเธอไม่ ด้วยท่านมีกําลังมากกว่าจึงข่มขืน และนอนร่วมกับเธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 15, 'ต่อมาอัมโนนเกลียดชังเธอยิ่งนัก ความเกลียดชังครั้งนี้ก็มากยิ่งกว่าความรักซึ่งท่านได้รักเธอมาก่อน และอัมโนนรับสั่งกับเธอว่า “จงลุกขึ้นไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 16, 'แต่เธอตอบท่านว่า “อย่าเลยพระเชษฐา ที่จะขับไล่หม่อมฉันไปครั้งนี้นั้นก็เป็นความผิดใหญ่ยิ่งกว่าที่พระเชษฐาได้ทํากับน้องมาแล้ว” แต่ท่านหาได้เชื่อฟังเธอไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 17, 'ท่านจึงเรียกมหาดเล็กที่ปรนนิบัติอยู่สั่งว่า “จงไล่ผู้หญิงคนนี้ให้ออกไปพ้นหน้าของข้าแล้วปิดประตูใส่กลอนเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 18, 'เธอสวมเสื้อยาวหลากสีที่ราชธิดาพรหมจารีของกษัตริย์สวมกัน มหาดเล็กของท่านจึงไล่เธอออกไปและใส่กลอนประตูเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 19, 'ทามาร์ก็เอาขี้เถ้าใส่ที่ศีรษะของเธอ และฉีกเสื้อยาวหลากสีที่เธอสวมอยู่นั้นเสีย เอามือกุมศีรษะเดินพลางร้องครวญไปพลาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 20, 'อับซาโลมเชษฐาของเธอก็กล่าวกับเธอว่า “อัมโนนเชษฐาได้อยู่กับน้องหรือเปล่า แต่น้องเอ๋ย บัดนี้น้องจงนิ่งเสียเถิด เพราะเขาเป็นพี่ชายของเจ้า อย่าไปคิดถึงเรื่องนี้เลย” ฝ่ายทามาร์จึงอยู่อย่างเดียวดายในวังของอับซาโลมเชษฐา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 21, 'เมื่อกษัตริย์ดาวิดทรงได้ยินเรื่องเหล่านี้ทั้งสิ้น พระองค์ก็กริ้วยิ่งนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 22, 'แต่อับซาโลมมิได้ตรัสประการใดกับอัมโนนเลยไม่ว่าดีหรือร้าย เพราะอับซาโลมเกลียดชังอัมโนน เหตุที่ท่านได้ข่มขืนทามาร์น้องหญิงของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 23, 'ต่อมาอีกสองปีเต็ม อับซาโลมมีงานตัดขนแกะที่ตําบลบาอัลฮาโซร์ ซึ่งอยู่ใกล้เอฟราอิม และอับซาโลมได้เชิญโอรสทั้งสิ้นของกษัตริย์ไปในงานนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 24, 'อับซาโลมไปเฝ้ากษัตริย์ทูลว่า “ดูเถิด ข้าพระองค์มีงานตัดขนแกะ ขอเชิญกษัตริย์และมหาดเล็กของพระองค์ไปในงานนั้นกับข้าพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 25, 'แต่กษัตริย์ตรัสกับอับซาโลมว่า “ลูกเอ๋ย อย่าเลย อย่าให้พวกเราไปกันหมดเลย จะเป็นภาระแก่เจ้าเปล่าๆ” อับซาโลมคะยั้นคะยอพระองค์ ถึงกระนั้นพระองค์มิได้ยอมเสด็จ แต่ทรงอํานวยพระพรให้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 26, 'อับซาโลมจึงกราบทูลว่า “ถ้าไม่โปรดเสด็จก็ขออนุญาตให้พระเชษฐาอัมโนนไปด้วยกันเถิด” และกษัตริย์ตรัสถามว่า “ทําไมเขาต้องไปกับเจ้าด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 27, 'แต่อับซาโลมทูลคะยั้นคะยอจนพระองค์ทรงยอมให้อัมโนนและราชโอรสของกษัตริย์ทั้งสิ้นไปด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 28, 'แล้วอับซาโลมบัญชามหาดเล็กของท่านว่า “จงคอยดูว่าจิตใจของอัมโนนเพลิดเพลินด้วยเหล้าองุ่นเมื่อไร เมื่อเราสั่งเจ้าว่า ‘จงตีอัมโนน’ เจ้าทั้งหลายจงฆ่าเขาเสีย อย่ากลัวเลย เราบัญชาเจ้าแล้วมิใช่หรือ จงกล้าหาญและเป็นคนเก่งกล้าเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 29, 'และมหาดเล็กของอับซาโลมก็กระทํากับอัมโนนตามที่อับซาโลมได้บัญชาไว้ แล้วบรรดาราชโอรสของกษัตริย์ก็พากันลุกขึ้นทรงล่อของแต่ละองค์หนีไปสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 30, 'ต่อมาขณะเมื่อราชโอรสได้ดําเนินอยู่ตามทาง มีข่าวไปถึงดาวิดว่า “อับซาโลมได้ประหารราชโอรสของกษัตริย์หมดแล้ว ไม่เหลืออยู่สักองค์เดียว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 31, 'กษัตริย์ทรงลุกขึ้นฉีกฉลองพระองค์ และทรงบรรทมบนพื้นดิน บรรดาข้าราชการทั้งสิ้นสวมเสื้อผ้าฉีกขาดยืนเฝ้าอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 32, 'แต่โยนาดับบุตรชายชิเมอาห์เชษฐาของดาวิดกราบทูลว่า “ขออย่าให้เจ้านายของข้าพระองค์สําคัญผิดไปว่า เขาได้ประหารราชโอรสหนุ่มแน่นเหล่านั้นหมดแล้ว เพราะว่าอัมโนนสิ้นชีวิตแต่ผู้เดียว เพราะตามบัญชาของอับซาโลมเรื่องนี้ท่านตั้งใจไว้แต่ครั้งที่อัมโนนข่มขืนทามาร์น้องหญิงของท่านแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 33, 'ฉะนั้นบัดนี้ขอกษัตริย์เจ้านายของข้าพระองค์อย่าได้ร้อนพระทัย ด้วยสําคัญว่าราชโอรสทั้งหมดของกษัตริย์สิ้นชีวิต เพราะอัมโนนสิ้นชีพแต่ผู้เดียว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 34, 'แต่อับซาโลมได้หนีไป ฝ่ายทหารยามหนุ่มเงยหน้าขึ้นมองดู ดูเถิด ประชาชนเป็นอันมากกําลังมาทางข้างๆภูเขาซึ่งอยู่ข้างหลังเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 35, 'โยนาดับจึงกราบทูลกษัตริย์ว่า “ดูเถิด ราชโอรสของกษัตริย์กําลังดําเนินมาแล้ว ตามที่ผู้รับใช้ของพระองค์กราบทูลก็เป็นจริงดังนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 36, 'อยู่มาเมื่อเขาพูดจบลง ดูเถิด ราชโอรสของกษัตริย์ก็มาถึง และได้ร้องไห้เสียงดัง ฝ่ายกษัตริย์ก็กันแสง และบรรดาข้าราชการก็ร้องไห้สะอึกสะอื้นด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 37, 'อับซาโลมได้หนีไปเข้าเฝ้าทัลมัย โอรสของอัมมีฮูด กษัตริย์เมืองเกชูร์ แต่ดาวิดทรงไว้ทุกข์ให้ราชโอรสของพระองค์วันแล้ววันเล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 38, 'ฝ่ายอับซาโลมก็หนีไปยังเมืองเกชูร์ และทรงอยู่ที่นั่นสามปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 39, 'กษัตริย์ดาวิดก็ทรงตรอมพระทัยอาลัยถึงอับซาโลม เพราะการที่ทรงคิดถึงอัมโนนนั้นค่อยคลายลง ด้วยท่านสิ้นชีพแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 1, 'ฝ่ายโยอาบบุตรชายของนางเศรุยาห์ทราบว่า กษัตริย์อาลัยถึงอับซาโลม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 2, 'โยอาบจึงใช้คนไปยังเมืองเทโคอาพาหญิงที่ฉลาดมาจากที่นั่นคนหนึ่ง บอกนางว่า “ขอจงแสร้งทําเป็นคนไว้ทุกข์ สวมเสื้อของคนไว้ทุกข์ อย่าชโลมน้ํามัน แต่แสร้งทําเหมือนผู้หญิงที่ไว้ทุกข์ให้ผู้ตายมาหลายวันแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 3, 'จงเข้าไปเฝ้ากษัตริย์ กราบทูลข้อความนี้แก่พระองค์” แล้วโยอาบก็สอนคํากราบทูลให้หญิงนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 4, 'เมื่อหญิงชาวเทโคอามาเฝ้ากษัตริย์ นางก็ซบหน้าลงถึงดินถวายบังคมแล้วกราบทูลว่า “โอ ข้าแต่กษัตริย์ ขอพระกรุณาคุณเป็นที่พึ่ง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 5, 'กษัตริย์ตรัสถามหญิงนั้นว่า “เจ้ามีเรื่องอะไร” นางกราบทูลว่า “หม่อมฉันเป็นหญิงม่ายอย่างแท้จริง สามีตายเสียแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 6, 'สาวใช้ของพระองค์มีบุตรชายสองคน วิวาทกันที่ในทุ่งนา ไม่มีใครช่วยห้ามปราม บุตรชายคนหนึ่งจึงตีอีกคนหนึ่งตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 7, 'ดูเถิด หมู่ญาติทั้งสิ้นรุมกันมาหาสาวใช้ของพระองค์บอกว่า ‘จงมอบผู้ที่ฆ่าพี่ชายของตัวมาให้เรา เพื่อเราจะฆ่าเขาเสีย เพื่อแก้แค้นแทนพี่ชายที่เขาได้ฆ่าเสียนั้น จะได้ฆ่าผู้ที่รับมรดกเสียด้วย’ ดังว่าจะดับถ่านไฟของหม่อมฉันที่ยังเหลืออยู่นั้นเสีย ไม่ให้สามีของหม่อมฉันมีชื่อหรือมีเชื้อเหลืออยู่บนพื้นโลกเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 8, 'กษัตริย์จึงรับสั่งแก่หญิงคนนั้นว่า “ไปบ้านของเจ้าเถิด เราจะสั่งการเรื่องเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 9, 'หญิงชาวเทโคอาได้กราบทูลกษัตริย์ว่า “โอ ข้าแต่กษัตริย์เจ้านายของหม่อมฉัน ขอให้ความชั่วช้าตกอยู่กับหม่อมฉัน และกับวงศ์วานบิดาของหม่อมฉัน แต่กษัตริย์และราชบัลลังก์ของพระองค์อย่าให้มีโทษเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 10, 'กษัตริย์ตรัสว่า “ถ้ามีผู้ใดกล่าวอะไรแก่เจ้า จงพาเขามาหาเรา คนนั้นจะไม่แตะต้องเจ้าอีกเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 11, 'นางก็กราบทูลว่า “ข้าแต่พระองค์ ขอกษัตริย์ทรงระลึกถึงพระเยโฮวาห์พระเจ้าของพระองค์ เพื่อผู้อาฆาตโลหิตจะไม่กระทําการฆ่าอีกต่อไป เกรงว่าพวกเขาจะได้ทําลายบุตรชายของหม่อมฉัน” พระองค์ตรัสว่า “พระเยโฮวาห์ทรงพระชนม์อยู่แน่ฉันใด เส้นผมของบุตรชายของเจ้าสักเส้นเดียวจะไม่ตกลงถึงดิน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 12, 'แล้วหญิงนั้นกราบทูลว่า “ข้าแต่พระองค์ ขอสาวใช้ของพระองค์กราบทูลอีกสักคําหนึ่งแด่กษัตริย์เจ้านายของหม่อมฉัน” พระองค์ตรัสว่า “พูดไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 13, 'หญิงนั้นจึงกราบทูลว่า “เหตุใดพระองค์ทรงดําริจะกระทําอย่างนี้แก่ประชาชนของพระเจ้า ในการที่ตรัสเช่นนี้กษัตริย์ทรงกล่าวโทษพระองค์เอง ในประการที่กษัตริย์มิได้ทรงนําผู้ถูกเนรเทศกลับสู่พระราชสํานัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 14, 'คนเราจะต้องตายหมดด้วยกันทุกคน เป็นเหมือนน้ําที่หกบนแผ่นดิน จะเก็บรวมกลับคืนมาอีกไม่ได้ พระเจ้าไม่ทรงเลือกหน้าผู้ใด แต่ทรงดําริหาหนทางไม่ให้ผู้ที่ถูกเนรเทศต้องถูกทอดทิ้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 15, 'ฉะนั้นบัดนี้ที่หม่อมฉันมากราบทูลเรื่องนี้ต่อกษัตริย์เจ้านายของหม่อมฉัน เพราะประชาชนขู่หม่อมฉันให้กลัว และสาวใช้ของพระองค์คิดว่า ‘หม่อมฉันจะกราบทูลกษัตริย์ หวังว่ากษัตริย์จะโปรดตามคําขอของหญิงผู้รับใช้ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 16, 'ด้วยกษัตริย์จะทรงสดับฟัง และทรงช่วยหญิงผู้รับใช้ของพระองค์ให้พ้นจากมือของผู้ที่ตั้งใจทําลายหม่อมฉัน และบุตรชายของหม่อมฉันเสียจากมรดกของพระเจ้า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 17, 'และสาวใช้ของพระองค์คิดว่า ‘ขอให้พระดํารัสของกษัตริย์เจ้านายของหม่อมฉันเป็นที่ให้พํานัก’ เพราะกษัตริย์เจ้านายของหม่อมฉันเปรียบประดุจทูตสวรรค์องค์หนึ่งของพระเจ้าในการที่จะประจักษ์ความดีและความชั่ว ขอพระเยโฮวาห์พระเจ้าของพระองค์ทรงสถิตกับพระองค์เถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 18, 'แล้วกษัตริย์ทรงตอบหญิงนั้นว่า “สิ่งใดที่เราจะถามเจ้า เจ้าอย่าปิดบังนะ” ผู้หญิงนั้นกราบทูลว่า “ขอกษัตริย์เจ้านายของหม่อมฉันจงตรัสเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 19, 'กษัตริย์จึงตรัสถามว่า “ในเรื่องทั้งสิ้นนี้มือของโยอาบเกี่ยวข้องกับเจ้าด้วยหรือเปล่า” หญิงนั้นทูลตอบว่า “ข้าแต่กษัตริย์เจ้านายของหม่อมฉัน พระองค์ทรงพระชนม์อยู่แน่ฉันใด ไม่มีใครหลบหลีกพระดํารัสของกษัตริย์เจ้านายของหม่อมฉัน ไปทางขวาหรือทางซ้ายได้ โยอาบผู้รับใช้ของพระองค์นั่นแหละให้หม่อมฉันกราบทูล เขาเป็นผู้สอนคํากราบทูลแก่หม่อมฉันสาวใช้ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 20, 'โยอาบผู้รับใช้ของพระองค์ได้กระทําเช่นนี้ก็เพื่อจะเปลี่ยนโฉมหน้าของเหตุการณ์ แต่เจ้านายของหม่อมฉันทรงมีพระสติปัญญา ดังสติปัญญาแห่งทูตสวรรค์องค์หนึ่งของพระเจ้า ทรงทราบทุกสิ่งทุกอย่างที่อยู่บนพิภพ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 21, 'กษัตริย์ตรัสสั่งโยอาบว่า “ดูเถิด เราอนุมัติตามคําขอนี้แล้ว จงไปพาอับซาโลมชายหนุ่มคนนั้นกลับมา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 22, 'โยอาบก็ซบหน้าลงถึงดินและน้อมตัวลง แล้วโมทนาพระคุณกษัตริย์ โยอาบกราบทูลว่า “โอ ข้าแต่กษัตริย์เจ้านายของข้าพระองค์ วันนี้ผู้รับใช้ของพระองค์ทราบว่า ข้าพระองค์ได้รับพระกรุณาในสายพระเนตรของพระองค์ ในประการที่กษัตริย์ทรงทําให้บรรลุตามคําทูลขอของผู้รับใช้ของพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 23, 'โยอาบจึงลุกขึ้นไปยังเมืองเกชูร์และพาอับซาโลมมายังกรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 24, 'และกษัตริย์รับสั่งว่า “ให้เขาไปอยู่วังของเขาเถิด อย่าให้เข้าเฝ้าเรา” อับซาโลมก็ไปอยู่วังของท่าน มิได้เข้าเฝ้าเฉพาะพระพักตร์กษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 25, 'ในบรรดาอิสราเอลหามีผู้ใดรูปงามน่าชมอย่างอับซาโลมไม่ ในตัวท่านตั้งแต่ฝ่าเท้าจนถึงกระหม่อมไม่มีตําหนิเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 26, 'เมื่อท่านตัดผม (ท่านเคยตัดผมสิ้นปีทุกปี เพราะผมหนักแล้วท่านก็ตัดเสีย) ท่านก็ชั่งผมของท่านได้หนักสองร้อยเชเขลตามพิกัดหลวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 27, 'มีบุตรชายสามคนเกิดแก่อับซาโลมและบุตรสาวคนหนึ่งชื่อทามาร์ เธอเป็นหญิงที่หน้าตางดงาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 28, 'อับซาโลมประทับในกรุงเยรูซาเล็มได้สองปีเต็ม โดยมิได้เข้าเฝ้าเฉพาะพระพักตร์กษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 29, 'แล้วอับซาโลมก็ให้ไปตามโยอาบ จะใช้ให้เข้าไปเฝ้ากษัตริย์ แต่โยอาบไม่ยอมมาหาท่าน ท่านก็ใช้คนไปครั้งที่สอง แต่โยอาบก็ไม่มาเหมือนกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 30, 'ท่านจึงสั่งมหาดเล็กของท่านว่า “ดูซิ นาของโยอาบอยู่ถัดนาของเรา เขามีข้าวบาร์เลย์ที่นั่น จงเอาไฟเผาเสีย” มหาดเล็กของอับซาโลมก็ไปเอาไฟเผานา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 31, 'โยอาบก็ลุกขึ้นไปหาอับซาโลมที่วังของท่าน ถามท่านว่า “ทําไมมหาดเล็กของท่านจึงเอาไฟเผานาของหม่อมฉัน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 32, 'อับซาโลมตอบโยอาบว่า “ดูเถิด เราส่งคนไปบอกท่านว่า ‘มานี่เถิด เราจะส่งท่านไปหากษัตริย์ทูลว่า “ให้ข้าพระองค์มาจากเกชูร์ทําไม ข้าพระองค์ยังอยู่ที่นั่นก็ดีกว่า ฉะนั้นบัดนี้ขอให้เราได้เข้าเฝ้าเฉพาะพระพักตร์กษัตริย์”’ ถ้าเรามีความชั่วช้าประการใด ก็ขอพระองค์ทรงประหารเราเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 33, 'โยอาบจึงเข้าไปเฝ้ากษัตริย์กราบทูลพระองค์ พระองค์ก็ทรงเรียกอับซาโลม ท่านจึงเข้าไปเฝ้ากษัตริย์โน้มกายลงซบหน้าลงถึงดินต่อพระพักตร์กษัตริย์ กษัตริย์ก็ทรงจุบอับซาโลม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 1, 'อยู่มาภายหลังอับซาโลมได้เตรียมรถรบและม้ากับทหารวิ่งนําหน้าห้าสิบคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 2, 'อับซาโลมตื่นบรรทมแต่เช้าตรู่ไปประทับริมทางไปยังประตูเมือง ถ้าผู้ใดมีเรื่องที่จะถวายกษัตริย์ให้ทรงตัดสิน อับซาโลมก็เรียกผู้นั้น ถามว่า “เจ้ามาจากเมืองไหน” และเมื่อเขาทูลตอบว่า “ผู้รับใช้ของท่านเป็นคนตระกูลหนึ่งในอิสราเอล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 3, 'อับซาโลมจึงจะบอกเขาว่า “ดูซิ ข้อหาของเจ้าก็ดีและถูกต้อง แต่กษัตริย์มิได้ทรงตั้งผู้ใดไว้ฟังคดีของเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 4, 'อับซาโลมเคยกล่าวยิ่งกว่านั้นว่า “โอ ถ้าข้าเป็นผู้พิพากษาในแผ่นดินนี้ก็ดี เมื่อใครมีข้อหาหรือคดีจะได้มาหาข้า ข้าจะตัดสินให้ความยุติธรรมแก่เขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 5, 'เมื่อมีผู้ใดเข้ามาใกล้จะกราบถวายบังคมท่าน ท่านจะยื่นมือออกจับคนนั้นไว้และจุบเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 6, 'อับซาโลมกระทําอย่างนี้แก่บรรดาคนอิสราเอลผู้มาเฝ้ากษัตริย์เพื่อขอการพิพากษา อับซาโลมก็ลอบเอาใจคนอิสราเอลอย่างนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 7, 'ครั้นล่วงมาได้สี่สิบปี อับซาโลมกราบทูลกษัตริย์ว่า “ขอโปรดทรงอนุญาตให้ข้าพระองค์ไปทําตามคําปฏิญาณที่เมืองเฮโบรน ซึ่งข้าพระองค์ได้ปฏิญาณไว้ต่อพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 8, 'เพราะว่าผู้รับใช้ของพระองค์ได้ปฏิญาณไว้เมื่อครั้งอยู่ในเมืองเกชูร์ประเทศซีเรียว่า ‘ถ้าพระเยโฮวาห์ทรงโปรดนําข้าพระองค์มายังกรุงเยรูซาเล็มจริงแล้ว ข้าพระองค์จะปรนนิบัติพระเยโฮวาห์’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 9, 'กษัตริย์ตรัสตอบท่านว่า “จงไปเป็นสุขเถิด” ท่านก็ลุกขึ้นไปยังเมืองเฮโบรน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 10, 'แต่อับซาโลมได้ส่งผู้สื่อสารไปทั่วอิสราเอลทุกตระกูลว่า “ท่านทั้งหลายได้ยินเสียงแตรเมื่อไร จงกล่าวกันว่า ‘อับซาโลมเป็นกษัตริย์ที่กรุงเฮโบรน’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 11, 'มีชายสองร้อยคนไปกับอับซาโลมจากกรุงเยรูซาเล็ม เป็นคนที่ถูกเชิญให้ไป คนเหล่านี้ก็ไปกันเฉยๆ หาทราบเรื่องอะไรไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 12, 'ขณะเมื่ออับซาโลมถวายสัตวบูชาอยู่ ท่านส่งคนไปเชิญอาหิโธเฟลชาวกิโลห์ที่ปรึกษาของดาวิดมาจากนครของเขาคือกิโลห์ การที่คบคิดกันนั้นก็เพิ่มกําลังขึ้น คนที่มาฝักใฝ่อยู่กับอับซาโลมก็เพิ่มขึ้นเรื่อยๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 13, 'ผู้สื่อสารคนหนึ่งมาเฝ้าดาวิดกราบทูลว่า “ใจของคนอิสราเอลได้คล้อยตามอับซาโลมไปแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 14, 'แล้วดาวิดรับสั่งแก่บรรดาข้าราชการที่อยู่กับพระองค์ ณ เยรูซาเล็มว่า “จงลุกขึ้นให้เราหนีไปเถิด มิฉะนั้นเราจะหนีไม่พ้นจากอับซาโลมสักคนเดียว จงรีบไป เกรงว่าเขาจะตามเราทันโดยเร็วและนําเหตุร้ายมาถึงเรา และทําลายกรุงนี้เสียด้วยคมดาบ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 15, 'ข้าราชการของกษัตริย์จึงกราบทูลกษัตริย์ว่า “ดูเถิด ผู้รับใช้ของพระองค์พร้อมที่จะกระทําตามสิ่งซึ่งกษัตริย์เจ้านายของข้าพระองค์ตัดสินพระทัยทุกประการ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 16, 'กษัตริย์ก็เสด็จออกไปพร้อมกับบรรดาคนในราชสํานักของพระองค์ด้วย เว้นแต่นางสนมสิบคนกษัตริย์ได้ทรงละไว้ให้เฝ้าพระราชวัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 17, 'กษัตริย์ก็เสด็จออกไป พลทั้งสิ้นก็ตามพระองค์ไป และเสด็จประทับในสถานที่ที่อยู่ห่างไกล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 18, 'บรรดาข้าราชการทั้งสิ้นเดินผ่านพระองค์ไป บรรดาคนเคเรธีและคนเปเลทกับคนกัท หกร้อยคนที่ติดตามพระองค์มาจากเมืองกัท ได้เดินผ่านพระพักตร์กษัตริย์ไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 19, 'กษัตริย์จึงตรัสสั่งอิททัยคนกัทว่า “ทําไมเจ้าจึงไปกับเราด้วย จงกลับไปบ้านเมืองของเจ้าเถิดและไปอยู่กับกษัตริย์ เจ้าเป็นแต่คนต่างด้าว และถูกเนรเทศมาด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 20, 'เจ้าเพิ่งมาถึงเมื่อวานนี้ และวันนี้ควรที่เราจะให้เจ้าไปมากับเราหรือ ด้วยเราไม่ทราบว่าจะไปที่ไหน จงกลับไปเถิด พาพี่น้องของเจ้าไปด้วย ขอความเมตตาและความจริงจงมีกับเจ้าเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 21, 'แต่อิททัยทูลตอบกษัตริย์ว่า “พระเยโฮวาห์ทรงพระชนม์อยู่แน่ฉันใด และกษัตริย์เจ้านายของข้าพระองค์ทรงพระชนม์อยู่แน่ฉันใด กษัตริย์เจ้านายของข้าพระองค์เสด็จประทับที่ไหน จะสิ้นพระชนม์หรือทรงพระชนม์ ผู้รับใช้ของพระองค์ขอไปอยู่ที่นั้นด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 22, 'ดาวิดก็รับสั่งกับอิททัยว่า “จงผ่านไปเถิด” อิททัยชาวเมืองกัทจึงผ่านไปพร้อมกับบรรดาพรรคพวกของเขาทั้งผู้ใหญ่และเด็ก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 23, 'เมื่อพลทั้งหมดเดินผ่านไปเสีย ชาวเมืองนั้นทั้งสิ้นก็ร้องไห้เสียงดัง กษัตริย์ก็เสด็จข้ามลําธารขิดโรน และพลทั้งหมดก็ผ่านเข้าทางไปถิ่นทุรกันดาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 24, 'และดูเถิด ศาโดกก็มาด้วย พร้อมกับคนเลวีทั้งสิ้น หามหีบพันธสัญญาของพระเจ้ามา และเขาวางหีบของพระเจ้าลง ฝ่ายอาบียาธาร์ก็ขึ้นมาจนประชาชนออกจากเมืองไปหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 25, 'แล้วกษัตริย์ตรัสสั่งศาโดกว่า “จงหามหีบของพระเจ้ากลับเข้าไปในเมืองเถิด หากว่าเราเป็นที่โปรดปรานในสายพระเนตรพระเยโฮวาห์ พระองค์จะทรงโปรดนําเรากลับมาอีก และสําแดงให้ข้าพระองค์เห็นทั้งหีบนั้นกับที่ประทับของพระองค์ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 26, 'แต่ถ้าพระองค์ตรัสว่า ‘เราไม่พอใจเจ้า’ ดูเถิด เราอยู่ที่นี่ ขอพระองค์ทรงกระทํากับเราตามที่พระองค์ทรงโปรดเห็นชอบเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 27, 'กษัตริย์ตรัสกับศาโดกปุโรหิตด้วยว่า “ท่านเป็นผู้ทํานายหรือ จงกลับเข้าไปในเมืองโดยสันติภาพ พร้อมกับบุตรชายทั้งสองของท่าน คืออาหิมาอัสบุตรของท่าน และโยนาธานบุตรของอาบียาธาร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 28, 'ดูก่อนท่าน เราจะคอยอยู่ที่ที่ราบในถิ่นทุรกันดาร จนจะมีข่าวมาจากท่านให้เราทราบ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 29, 'ฝ่ายศาโดกกับอาบียาธาร์จึงหามหีบของพระเจ้ากลับไปยังกรุงเยรูซาเล็มและพักอยู่ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 30, 'ฝ่ายดาวิดเสด็จขึ้นไปตามทางขึ้นภูเขามะกอกเทศ เสด็จพลางกันแสงพลาง คลุมพระเศียรเสด็จโดยพระบาทเปล่า และประชาชนทั้งสิ้นที่อยู่กับพระองค์ก็คลุมศีรษะเดินขึ้นไปพลางร้องไห้พลาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 31, 'มีคนมากราบทูลดาวิดว่า “อาหิโธเฟลอยู่ในพวกคิดกบฏของอับซาโลมด้วย” ดาวิดกราบทูลว่า “โอ ข้าแต่พระเยโฮวาห์ ขอทรงโปรดให้คําปรึกษาของอาหิโธเฟลโง่เง่าไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 32, 'อยู่มาเมื่อดาวิดมาถึงยอดภูเขาซึ่งเป็นที่นมัสการพระเจ้า ดูเถิด หุชัยชาวอารคีได้เข้ามาเฝ้า มีเสื้อผ้าฉีกขาดและดินอยู่บนศีรษะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 33, 'ดาวิดตรัสกับเขาว่า “ถ้าเจ้าไปกับเรา เจ้าจะเป็นภาระแก่เรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 34, 'แต่ถ้าเจ้ากลับเข้าไปในเมืองและกล่าวกับอับซาโลมว่า ‘โอ ข้าแต่กษัตริย์ ข้าพระองค์ขอถวายตัวเป็นผู้รับใช้ของพระองค์ ดังที่ข้าพระองค์เป็นผู้รับใช้ของพระราชบิดาของพระองค์มาแต่กาลก่อนฉันใด ข้าพระองค์ขอเป็นผู้รับใช้ของพระองค์ฉันนั้น’ แล้วเจ้าจะกระทําให้คําปรึกษาของอาหิโธเฟลพ่ายแพ้ไปเพื่อเห็นแก่เรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 35, 'ศาโดกกับอาบียาธาร์ปุโรหิตก็อยู่กับเจ้าที่นั่นมิใช่หรือ สิ่งใดที่เจ้าได้ยินในพระราชวังจงบอกให้ศาโดกกับอาบียาธาร์ปุโรหิตทราบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 36, 'ดูเถิด บุตรชายสองคนของเขาก็อยู่ด้วย คืออาหิมาอัสบุตรศาโดก และโยนาธานบุตรอาบียาธาร์ ดังนั้นเมื่อท่านได้ยินเรื่องอะไรจงใช้เขามาบอกเราทุกเรื่องเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 37, 'หุชัยสหายของดาวิดจึงกลับเข้าไปในเมือง และอับซาโลมกําลังเสด็จเข้ากรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 1, 'เมื่อดาวิดเสด็จเลยยอดเขาไปหน่อยหนึ่ง ดูเถิด ศิบามหาดเล็กของเมฟีโบเชทก็เข้ามาเฝ้าพระองค์ มีลาคู่หนึ่งผูกอานพร้อม บรรทุกขนมปังสองร้อยก้อน องุ่นแห้งร้อยพวง และผลไม้ฤดูร้อนอีกร้อยหนึ่ง กับน้ําองุ่นหนึ่งถุงหนัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 2, 'กษัตริย์ตรัสกับศิบาว่า “เจ้านําสิ่งเหล่านี้มาทําไม” ศิบาทูลตอบว่า “ลาคู่นั้นเพื่อราชวงศ์จะได้ทรง ขนมปังและผลไม้ฤดูร้อนสําหรับชายหนุ่มรับประทาน และน้ําองุ่นเพื่อผู้ที่อ่อนเปลี้ยอยู่กลางถิ่นทุรกันดารจะได้ดื่ม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 3, 'กษัตริย์ตรัสว่า “บุตรเจ้านายของเจ้าอยู่ที่ไหนเล่า” ศิบากราบทูลกษัตริย์ว่า “ดูเถิด ท่านพักอยู่ในเยรูซาเล็ม เพราะท่านว่า ‘วันนี้วงศ์วานอิสราเอลจะคืนราชอาณาจักรบิดาของเราให้แก่เรา’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 4, 'แล้วกษัตริย์ตรัสกับศิบาว่า “ดูเถิด ทรัพย์สมบัติของเมฟีโบเชทก็ตกเป็นของเจ้าทั้งหมด” และศิบากราบทูลว่า “โอ ข้าแต่กษัตริย์เจ้านายของข้าพระองค์ ข้าพระองค์ขอทูลวิงวอนต่อพระองค์ด้วยความถ่อมใจ ขอทรงให้ข้าพระองค์ได้รับพระกรุณาในสายพระเนตรของพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 5, 'เมื่อกษัตริย์ดาวิดเสด็จมายังตําบลบาฮูริม ดูเถิด มีชายคนหนึ่งอยู่ในครอบครัววงศ์วานซาอูลชื่อชิเมอีบุตรชายเก-รา เขาออกมาเดินพลางด่าพลาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 6, 'และเอาหินขว้างดาวิดและขว้างบรรดาข้าราชการของกษัตริย์ดาวิด พวกพลและชายฉกรรจ์ทั้งสิ้นก็อยู่ข้างขวาและข้างซ้ายของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 7, 'ชิเมอีร้องด่ามาว่า “จงไปเสียให้พ้น เจ้าคนกระหายโลหิต เจ้าคนของเบลีอัล จงไปเสียให้พ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 8, 'พระเยโฮวาห์ได้ทรงสนองเจ้าในเรื่องโลหิตทั้งสิ้นแห่งวงศ์วานของซาอูลผู้ซึ่งเจ้าเข้าครองแทนอยู่นั้น และพระเยโฮวาห์ทรงมอบราชอาณาจักรไว้ในมืออับซาโลมบุตรของเจ้า ดูเถิด ความพินาศตกอยู่บนเจ้าแล้ว เพราะเจ้าเป็นคนกระหายโลหิต”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 9, 'อาบีชัยบุตรชายนางเศรุยาห์จึงกราบทูลกษัตริย์ว่า “ทําไมปล่อยให้สุนัขตายตัวนี้มาด่ากษัตริย์เจ้านายของข้าพระองค์ ขออนุญาตให้ข้าพระองค์ข้ามไปตัดหัวมันออกเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 10, 'แต่กษัตริย์ตรัสว่า “บุตรชายทั้งสองของนางเศรุยาห์เอ๋ย เรามีธุระอะไรกับเจ้า ถ้าเขาด่าเพราะพระเยโฮวาห์ตรัสสั่งเขาว่า ‘จงด่าดาวิด’ แล้วใครจะพูดว่า ‘ทําไมเจ้าจึงกระทําเช่นนี้’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 11, 'ดาวิดตรัสกับอาบีชัยและข้าราชการทั้งสิ้นของพระองค์ว่า “ดูเถิด ลูกของเราเองที่ได้ออกมาจากบั้นเอวของเรายังแสวงหาชีวิตของเรา ยิ่งกว่านั้น ทําไมกับคนเบนยามินคนนี้จะไม่กระทําเล่า ช่างเขาเถิด ให้เขาด่าไป เพราะพระเยโฮวาห์ทรงบอกเขาแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 12, 'บางทีพระเยโฮวาห์จะทอดพระเนตรความทุกข์ใจของเรา และพระเยโฮวาห์จะทรงสนองเราด้วยความดีเพราะเขาด่าเราในวันนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 13, 'ดาวิดจึงทรงดําเนินไปตามทางพร้อมกับพลของพระองค์ ฝ่ายชิเมอีก็เดินไปตามเนินเขาตรงข้าม เขาเดินพลางด่าพลาง เอาก้อนหินปาและเอาฝุ่นซัดใส่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 14, 'กษัตริย์กับพลทั้งปวงที่อยู่กับพระองค์ก็มารู้สึกเหนื่อยอ่อน จึงทรงพักผ่อนเอาแรง ณ ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 15, 'ฝ่ายอับซาโลมกับประชาชนทั้งสิ้น คือคนอิสราเอลก็มาถึงกรุงเยรูซาเล็ม และอาหิโธเฟลก็มาด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 16, 'และอยู่มาเมื่อหุชัยชาวอารคี สหายของดาวิดเข้าเฝ้าอับซาโลม หุชัยกราบทูลอับซาโลมว่า “ขอกษัตริย์ทรงพระเจริญ ขอกษัตริย์ทรงพระเจริญ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 17, 'และอับซาโลมตรัสกับหุชัยว่า “นี่หรือความเมตตาต่อสหายของท่าน ทําไมท่านไม่ไปกับสหายของท่านเล่า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 18, 'หุชัยกราบทูลอับซาโลมว่า “มิใช่พ่ะย่ะค่ะ พระเยโฮวาห์กับประชาชนเหล่านี้กับคนอิสราเอลทั้งสิ้นเลือกตั้งผู้ใดไว้ ข้าพระองค์ขอเป็นฝ่ายผู้นั้น ข้าพระองค์จะขออยู่กับผู้นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 19, 'อีกประการหนึ่งข้าพระองค์ควรจะปรนนิบัติผู้ใด มิใช่โอรสของท่านผู้นั้นดอกหรือ ข้าพระองค์ได้ปรนนิบัติต่อพระพักตร์เสด็จพ่อของพระองค์มาแล้วฉันใด ก็ขอปรนนิบัติต่อพระพักตร์พระองค์ฉันนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 20, 'อับซาโลมตรัสถามอาหิโธเฟลว่า “เราจะทําอย่างไรดี จงให้คําปรึกษาของท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 21, 'อาหิโธเฟลกราบทูลอับซาโลมว่า “จงเข้าหานางสนมของเสด็จพ่อของพระองค์ซึ่งเสด็จพ่อทิ้งไว้ให้เฝ้าพระราชวัง เมื่อคนอิสราเอลทั้งสิ้นได้ยินว่าพระองค์เป็นที่เกลียดชังของเสด็จพ่อแล้ว บรรดามือเหล่านั้นที่อยู่ฝ่ายพระองค์ก็จะเข้มแข็งขึ้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 22, 'เขาจึงกางเต็นท์ให้อับซาโลมไว้ที่บนดาดฟ้าหลังคา และอับซาโลมก็ทรงเข้าหานางสนมของพระราชบิดาของพระองค์ท่ามกลางสายตาของอิสราเอลทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 23, 'ในครั้งนั้นคําปรึกษาของอาหิโธเฟลที่ทูลถวายก็เหมือนกับว่าคนได้ทูลถามจากพระดํารัสของพระเจ้า คําปรึกษาทั้งสิ้นที่อาหิโธเฟลทูลถวายต่อดาวิดและอับซาโลมเป็นดังนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 1, 'และอาหิโธเฟลกราบทูลอับซาโลมว่า “ขอโปรดอนุญาตให้ข้าพระองค์เลือกทหารหนึ่งหมื่นสองพันคน ข้าพระองค์จะยกออกไปติดตามดาวิดคืนวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 2, 'ข้าพระองค์จะไปทันท่านเมื่อท่านยังเหนื่อยอ่อนอยู่และอ่อนกําลัง กระทําให้ท่านกลัวตัวสั่น พลทั้งปวงที่อยู่กับท่านก็จะหนีไป ข้าพระองค์จะฆ่าฟันแต่กษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 3, 'แล้วจะนําประชาชนทั้งสิ้นกลับมาเข้าฝ่ายพระองค์ เมื่อได้คนที่พระองค์มุ่งหาคนเดียวก็เหมือนได้ประชาชนกลับมาทั้งหมด แล้วประชาชนทั้งปวงก็จะอยู่เป็นผาสุก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 4, 'คําทูลนี้เป็นที่พอพระทัยอับซาโลม และบรรดาผู้ใหญ่แห่งอิสราเอลก็พอใจด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 5, 'อับซาโลมตรัสว่า “จงเรียกหุชัยคนอารคีเข้ามาด้วย เพื่อเราจะฟังเขาจะว่าอย่างไรเช่นกัน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 6, 'เมื่อหุชัยเข้ามาเฝ้าอับซาโลมแล้ว อับซาโลมจึงตรัสถามเขาว่า “อาหิโธเฟลว่าอย่างนี้แล้ว เราควรจะทําตามคําแนะนําของเขาหรือไม่ ถ้าไม่ ท่านจงพูดมา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 7, 'หุชัยจึงกราบทูลอับซาโลมว่า “คําปรึกษาซึ่งอาหิโธเฟลให้ในครั้งนี้ไม่ดี”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 8, 'หุชัยกราบทูลต่อไปว่า “พระองค์ทรงทราบแล้วว่า เสด็จพ่อและคนที่อยู่ด้วยเป็นทหารแข็งกล้า และเขาทั้งหลายกําลังโกรธเหมือนหมีที่ลูกถูกลักเอาไปในป่า นอกจากนั้นเสด็จพ่อของพระองค์ทรงชํานาญศึก ท่านคงไม่พักอยู่กับพวกพล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 9, 'ดูเถิด ถึงขณะนี้ท่านก็ซ่อนอยู่ในบ่อแห่งหนึ่ง หรือในที่หนึ่งที่ใด แล้วต่อมาเมื่อมีคนล้มตายในการสู้รบครั้งแรก ใครที่ได้ยินเรื่องก็จะกล่าวว่า ‘ทหารที่ติดตามอับซาโลมถูกฆ่าฟัน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 10, 'แม้คนที่กล้าหาญ ที่จิตใจเหมือนอย่างสิงโตก็จะละลายไปอย่างเต็มที่ เพราะอิสราเอลทั้งสิ้นทราบว่า เสด็จพ่อของพระองค์เป็นวีรบุรุษ และคนที่อยู่ก็เป็นทหารที่แข็งกล้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 11, 'แต่คําปรึกษาของข้าพระองค์มีว่า ขอพระองค์รวบรวมอิสราเอลทั้งสิ้นตั้งแต่ดานถึงเบเออร์เชบา ให้มากมายดั่งเม็ดทรายที่ทะเล แล้วพระองค์ก็เสด็จคุมทัพไปเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 12, 'เราทั้งหลายจะเข้ารบกับท่าน ณ ที่หนึ่งที่ใดที่พบกัน และเราจะเข้าโจมตีเหมือนน้ําค้างตกใส่พื้นดิน ตัวท่านและบรรดาคนที่อยู่กับท่านก็จะไม่มีเหลือสักคนหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 13, 'ยิ่งกว่านั้น ถ้าท่านจะถอยร่นเข้าไปในเมือง คนอิสราเอลทั้งสิ้นก็จะเอาเชือกมาลากเมืองนั้นลงไปที่ลุ่มแม่น้ํา จนกระทั่งก้อนกรวดสักก้อนหนึ่งก็ไม่มีให้เห็นที่นั่น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 14, 'อับซาโลมและคนอิสราเอลทั้งปวงว่า “คําปรึกษาของหุชัยคนอารคีดีกว่าคําปรึกษาของอาหิโธเฟล” เพราะพระเยโฮวาห์ทรงสถาปนาที่จะให้คําปรึกษาอันดีของอาหิโธเฟลพ่ายแพ้ เพื่อพระเยโฮวาห์จะทรงนําเหตุร้ายมายังอับซาโลม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 15, 'แล้วหุชัยจึงบอกศาโดกและอาบียาธาร์ปุโรหิตว่า “อาหิโธเฟลได้ให้คําปรึกษาอย่างนั้นอย่างนี้แก่อับซาโลมและพวกผู้ใหญ่ของอิสราเอล และข้าพเจ้าได้ให้คําปรึกษาอย่างนั้นอย่างนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 16, 'ฉะนั้นบัดนี้จงรีบส่งคนไปกราบทูลดาวิดว่า ‘คืนวันนี้อย่าพักอยู่ที่ที่ราบในถิ่นทุรกันดาร อย่างไรก็จงให้เสด็จข้ามไปเสีย เกรงว่ากษัตริย์และประชาชนทั้งสิ้นที่อยู่กับพระองค์จะถูกกลืนไปหมด’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 17, 'ฝ่ายโยนาธานและอาหิมาอัสกําลังคอยอยู่ที่เอนโรเกลแล้ว มีสาวใช้คนหนึ่งเคยไปบอกเรื่องแก่เขา แล้วเขาก็ไปกราบทูลกษัตริย์ดาวิด เพราะเขาไม่กล้าเข้ากรุงให้ใครเห็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 18, 'แต่มีเด็กหนุ่มคนหนึ่งเห็นเขาทั้งสอง จึงไปทูลอับซาโลม เขาทั้งสองก็รีบไปโดยเร็วจนถึงบ้านชายคนหนึ่งที่บาฮูริม เขามีบ่อน้ําอยู่ที่ลานบ้าน เขาทั้งสองจึงลงไปอยู่ในบ่อนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 19, 'หญิงแม่บ้านก็เอาผ้ามาปูปิดปากบ่อ แล้วก็เกลี่ยปลายข้าวตกอยู่บนนั้น ไม่มีใครทราบเรื่องเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 20, 'เมื่อข้าราชการของอับซาโลมมาถึงที่บ้านหญิงคนนี้ เขาก็ถามว่า “อาหิมาอัสกับโยนาธานอยู่ที่ไหน” หญิงนั้นก็ตอบเขาว่า “เขาข้ามลําธารน้ําไปแล้ว” เมื่อเขาเที่ยวหาไม่พบแล้วก็กลับไปยังกรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 21, 'อยู่มาเมื่อคนเหล่านั้นไปแล้ว ชายทั้งสองก็ขึ้นมาจากบ่อ ไปกราบทูลกษัตริย์ดาวิด เขาทูลดาวิดว่า “ขอทรงลุกขึ้น และรีบข้ามแม่น้ําไป เพราะอาหิโธเฟลได้ให้คําปรึกษาต่อสู้อย่างนั้นอย่างนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 22, 'ดาวิดก็ทรงลุกขึ้นพร้อมกับพวกพลทั้งสิ้นที่อยู่กับพระองค์และข้ามแม่น้ําจอร์แดน พอรุ่งเช้าก็ไม่มีเหลือสักคนหนึ่งที่ยังไม่ได้ข้ามแม่น้ําจอร์แดน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 23, 'เมื่ออาหิโธเฟลเห็นว่าเขาไม่กระทําตามคําปรึกษาของท่าน ก็ผูกอานลาขึ้นขี่กลับไปเรือนของตนที่อยู่ในเมืองของตน เมื่อสั่งครอบครัวเสียเสร็จแล้วก็ผูกคอตาย เขาจึงเอาศพฝังไว้ที่อุโมงค์บิดาของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 24, 'ฝ่ายดาวิดก็เสด็จมายังเมืองมาหะนาอิม และอับซาโลมก็ข้ามแม่น้ําจอร์แดนพร้อมกับคนอิสราเอลทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 25, 'อับซาโลมทรงตั้งอามาสาเป็นแม่ทัพแทนโยอาบ อามาสาเป็นบุตรของชายคนหนึ่งชื่ออิธราคนอิสราเอล ได้แต่งงานกับอาบีกายิลบุตรสาวของนาหาช น้องสาวของนางเศรุยาห์มารดาของโยอาบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 26, 'ฝ่ายคนอิสราเอลและอับซาโลมตั้งค่ายอยู่ในแผ่นดินกิเลอาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 27, 'อยู่มาเมื่อดาวิดเสด็จมาถึงมาหะนาอิม โชบีบุตรชายนาหาชชาวเมืองรับบาห์แห่งคนอัมโมน และมาคีร์บุตรชายอัมมีเอลชาวโลเดบาร์ และบารซิลลัยชาวกิเลอาดจากเมืองโรเกลิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 28, 'ได้ขนที่นอน อ่างน้ําและเครื่องภาชนะดิน ข้าวสาลี ข้าวบาร์เลย์ และแป้ง ข้าวคั่ว ถั่ว ถั่วยาง และถั่วแดง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 29, 'น้ําผึ้ง เนยข้น แกะ และเนยแข็งที่ได้มาจากฝูงสัตว์ ถวายแด่ดาวิด และให้พวกพลที่อยู่กับพระองค์รับประทาน เพราะเขาทั้งหลายกล่าวว่า “พวกพลหิวและอ่อนเพลียและกระหายอยู่ที่ในถิ่นทุรกันดาร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 1, 'ดาวิดจึงตรวจพลที่อยู่กับพระองค์ และทรงจัดตั้งนายพันนายร้อยให้ควบคุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 2, 'และดาวิดทรงจัดทัพออกไป ให้อยู่ในบังคับบัญชาของโยอาบหนึ่งในสาม และในบังคับของอาบีชัยน้องชายของโยอาบบุตรชายนางเศรุยาห์หนึ่งในสาม และอีกหนึ่งในสามอยู่ในบังคับบัญชาของอิททัยคนกัท และกษัตริย์ตรัสกับพวกพลว่า “เราจะไปกับท่านทั้งหลายด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 3, 'แต่พวกพลเหล่านั้นทูลว่า “ขอพระองค์อย่าเสด็จเลย เพราะถ้าข้าพระองค์ทั้งหลายจะหนีไป เขาทั้งหลายก็ไม่ไยดีอะไรหนักหนา ถ้าข้าพระองค์ทั้งหลายตายเสียสักครึ่งหนึ่ง เขาทั้งหลายก็ไม่ไยดีอะไร แต่พระองค์มีค่าเท่ากับพวกข้าพระองค์หนึ่งหมื่นคน เพราะฉะนั้นบัดนี้ขอพระองค์พร้อมที่จะส่งกองหนุนจากในเมืองจะดีกว่า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 4, 'กษัตริย์ตรัสกับเขาทั้งหลายว่า “ท่านทั้งหลายเห็นชอบอย่างไร เราจะกระทําตาม” กษัตริย์จึงทรงประทับที่ข้างประตูเมือง และบรรดาพลทั้งหลายเดินออกไปเป็นกองร้อยกองพัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 5, 'กษัตริย์รับสั่งโยอาบ อาบีชัย และอิททัยว่า “เบาๆมือกับชายหนุ่มนั้นด้วยเห็นแก่เราเถิด คือกับอับซาโลม” พวกพลทั้งสิ้นก็ได้ยินคํารับสั่งซึ่งกษัตริย์ประทานแก่บรรดาผู้บังคับบัญชาด้วยเรื่องอับซาโลม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 6, 'พวกพลจึงเคลื่อนออกไปในทุ่งเพื่อสู้รบกับคนอิสราเอล การสงครามนั้นทํากันในป่าเอฟราอิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 7, 'คนอิสราเอลก็พ่ายแพ้ต่อหน้าข้าราชการของดาวิด มีการฆ่าฟันกันอย่างหนักที่นั่น ทหารตายเสียสองหมื่นคนในวันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 8, 'การสงครามกระจายไปทั่วพื้นแผ่นดิน ในวันนั้นป่ากินคนเสียมากกว่าดาบกิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 9, 'และอับซาโลมไปพบข้าราชการของดาวิดเข้า อับซาโลมทรงล่ออยู่และล่อนั้นได้วิ่งเข้าไปใต้กิ่งต้นโอ๊กใหญ่ ศีรษะของท่านก็ติดกิ่งต้นโอ๊กแน่น เมื่อล่อนั้นวิ่งเลยไปแล้วท่านก็แขวนอยู่ระหว่างฟ้าและดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 10, 'มีชายคนหนึ่งมาเห็นเข้า จึงไปเรียนโยอาบว่า “ดูเถิด ข้าพเจ้าเห็นอับซาโลมแขวนอยู่ที่ต้นโอ๊ก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 11, 'โยอาบก็พูดกับชายที่บอกท่านว่า “ดูเถิด เจ้าเห็นเขาแล้ว ทําไมเจ้าไม่ฟันให้ตกดินเสียทีเดียวเล่า เราก็ยินดีที่จะให้รางวัลเงินสิบเหรียญกับสายรัดเอวเส้นหนึ่งให้เจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 12, 'แต่ชายคนนั้นเรียนโยอาบว่า “ถึงมือของข้าพเจ้าอุ้มเงินพันเหรียญอยู่ ข้าพเจ้าจะไม่ยื่นมือออกทําแก่ราชบุตรของกษัตริย์ เพราะว่าหูของพวกเราได้ยินพระบัญชาของกษัตริย์ที่ตรัสสั่งท่านและอาบีชัยกับอิททัยว่า ‘ขอจงป้องกันอับซาโลมชายหนุ่มนั้น’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 13, 'มิฉะนั้นข้าพเจ้ากระทําความผิดต่อชีวิตของตนเอง เพราะไม่มีอะไรจะปิดบังให้พ้นกษัตริย์ได้ แล้วตัวท่านเองก็คงใส่โทษข้าพเจ้าด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 14, 'โยอาบจึงว่า “เราไม่ควรเสียเวลากับเจ้าเช่นนี้” ท่านก็หยิบหลาวสามอันแทงเข้าไปที่หัวใจของอับซาโลมขณะที่ท่านยังมีชีวิตอยู่ที่ในต้นโอ๊ก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 15, 'ทหารหนุ่มสิบคนที่ถือเครื่องรบของโยอาบ ก็ล้อมอับซาโลมไว้ แล้วประหารชีวิตท่านเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 16, 'โยอาบก็เป่าแตร และกองทัพก็กลับจากการไล่ตามอิสราเอล เพราะโยอาบยับยั้งเขาทั้งหลายไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 17, 'เขาก็ยกศพอับซาโลมโยนลงไปในบ่อใหญ่ซึ่งอยู่ในป่า เอาหินกองทับไว้เป็นกองใหญ่มหึมา คนอิสราเอลทั้งสิ้นต่างก็หนีกลับไปเต็นท์ของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 18, 'เมื่ออับซาโลมยังมีชีวิตอยู่ ได้ตั้งเสาไว้เป็นที่ระลึกที่หุบเขาหลวง เพราะท่านกล่าวว่า “เราไม่มีบุตรชายที่จะสืบชื่อของเรา” ท่านเรียกเสานั้นตามชื่อของตน เขาเรียกกันว่าที่ระลึกแห่งอับซาโลมจนทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 19, 'อาหิมาอัสบุตรชายศาโดกกล่าวว่า “ขอให้ข้าพเจ้าวิ่งนําข่าวไปทูลกษัตริย์ว่า พระเยโฮวาห์ทรงช่วยพระองค์ให้แก้แค้นศัตรูของพระองค์แล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 20, 'โยอาบก็ตอบเขาว่า “ท่านอย่านําข่าวไปในวันนี้เลย ท่านจงนําข่าวในวันอื่นเถิด แต่วันนี้ท่านอย่านําข่าวเลย เพราะว่าโอรสของกษัตริย์สิ้นชีพแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 21, 'โยอาบก็สั่งคูชีว่า “จงนําข่าวไปกราบทูลกษัตริย์ตามสิ่งที่ท่านได้เห็น” คูชีก็กราบลงคํานับโยอาบแล้วก็วิ่งไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 22, 'อาหิมาอัสบุตรชายศาโดกจึงเรียนโยอาบอีกว่า “จะอย่างไรก็ช่างเถิด ขอให้ข้าพเจ้าวิ่งตามคูชีไปด้วย” โยอาบตอบว่า “ลูกเอ๋ย เจ้าจะวิ่งไปทําไม ด้วยว่าเจ้าไม่มีข่าวที่จะส่งไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 23, 'เขาตอบว่า “จะอย่างไรก็ช่างเถิด ข้าพเจ้าจะขอวิ่งไป” โยอาบจึงบอกเขาว่า “วิ่งไปเถอะ” และอาหิมาอัสก็วิ่งไปตามทางที่ราบ ขึ้นหน้าคูชีไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 24, 'ฝ่ายดาวิดประทับอยู่ระหว่างประตูเมืองทั้งสอง มีทหารยามขึ้นไปอยู่บนหลังคาซุ้มประตูที่กําแพงเมือง เมื่อเงยหน้าขึ้นมองดู เห็นชายคนหนึ่งวิ่งมาลําพัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 25, 'ทหารยามคนนั้นก็ร้องกราบทูลกษัตริย์ กษัตริย์ตรัสว่า “ถ้าเขามาลําพังก็คงคาบข่าวมา” ชายคนนั้นก็วิ่งเข้ามาใกล้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 26, 'ทหารยามเห็นชายอีกคนหนึ่งวิ่งมา ทหารยามก็ร้องบอกไปที่นายประตูเมืองว่า “ดูเถิด มีชายอีกคนหนึ่งวิ่งมาแต่ลําพัง” กษัตริย์ตรัสว่า “เขาคงนําข่าวมาด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 27, 'ทหารยามนั้นกราบทูลว่า “ข้าพระองค์คิดว่าคนที่วิ่งมาก่อนวิ่งเหมือนอาหิมาอัสบุตรศาโดก” และกษัตริย์ตรัสว่า “เขาเป็นคนดี เขามาด้วยข่าวดี”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 28, 'แล้วอาหิมาอัสร้องทูลกษัตริย์ว่า “ทุกสิ่งสงบแล้ว พ่ะย่ะค่ะ” เขาก็กราบกษัตริย์ซบหน้าลงถึงพื้นดินกราบทูลว่า “สาธุการแด่พระเยโฮวาห์พระเจ้าของพระองค์ พระองค์ได้ทรงมอบบรรดาผู้ที่ยกมือของเขาต่อสู้กับกษัตริย์เจ้านายของข้าพระองค์แล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 29, 'กษัตริย์ตรัสถามว่า “อับซาโลมชายหนุ่มนั้นเป็นสุขอยู่หรือ” อาหิมาอัสทูลตอบว่า “เมื่อโยอาบใช้ให้ผู้รับใช้ของกษัตริย์ คือผู้รับใช้ของพระองค์มานั้น ข้าพระองค์เห็นผู้คนสับสนกันใหญ่ แต่ไม่ทราบเหตุ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 30, 'กษัตริย์ตรัสว่า “จงหลีกมายืนตรงนี้” เขาจึงหลีกไปยืนนิ่งอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 31, 'ดูเถิด คูชีก็มาถึง และคูชีกราบทูลว่า “มีข่าวดีถวายแด่กษัตริย์เจ้านายของข้าพระองค์ เพราะในวันนี้พระเยโฮวาห์ทรงช่วยพระองค์ให้แก้แค้นบรรดาผู้ที่ลุกขึ้นต่อสู้พระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 32, 'กษัตริย์ตรัสถามคูชีว่า “อับซาโลมชายหนุ่มนั้นเป็นสุขอยู่หรือ” คูชีทูลตอบว่า “ขอให้ศัตรูของกษัตริย์เจ้านายของข้าพระองค์และบรรดาผู้ที่ลุกขึ้นกระทําอันตรายต่อพระองค์เป็นเหมือนชายหนุ่มผู้นั้นเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 33, 'กษัตริย์ทรงโทมนัสนัก เสด็จขึ้นไปบนห้องที่อยู่เหนือประตู และกันแสง เมื่อเสด็จไปพระองค์ตรัสว่า “โอ อับซาโลมบุตรของเรา บุตรของเรา อับซาโลมบุตรของเราเอ๋ย เราอยากจะตายแทนเจ้า โอ อับซาโลมบุตรของเรา บุตรของเราเอ๋ย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 1, 'เขาไปเรียนโยอาบว่า “ดูเถิด กษัตริย์กันแสงและไว้ทุกข์เพื่ออับซาโลม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 2, 'เพราะฉะนั้นชัยชนะในวันนั้นก็กลายเป็นการไว้ทุกข์ของประชาชนทั้งหลาย เพราะในวันนั้นประชาชนได้ยินว่า กษัตริย์ทรงโทมนัสเพราะพระราชบุตรของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 3, 'ในวันนั้นประชาชนได้แอบเข้ามาในเมืองอย่างกับคนหนีศึก แล้วอายแอบเข้ามา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 4, 'กษัตริย์ทรงคลุมพระพักตร์ของพระองค์ และกษัตริย์กันแสงเสียงดังว่า “โอ อับซาโลมบุตรของเราเอ๋ย โอ อับซาโลมบุตรของเรา บุตรของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 5, 'โยอาบก็เข้ามาในพระราชวังทูลกษัตริย์ว่า “วันนี้พระองค์ได้ทรงกระทําให้ข้าราชการทั้งสิ้นของพระองค์ ผู้ซึ่งวันนี้ได้อารักขาพระชนม์ของพระองค์ ทั้งชีวิตของราชบุตรและราชธิดา และชีวิตของบรรดามเหสี และชีวิตของสนมทั้งหลายของพระองค์ให้เขาได้รับความละอาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 6, 'เพราะว่าพระองค์ทรงรักศัตรูของพระองค์ และทรงเกลียดชังสหายของพระองค์ เพราะในวันนี้พระองค์ได้กระทําให้ประจักษ์แล้วว่า พระองค์ไม่ไยดีต่อนายทหารและบรรดาข้าราชการทั้งหลาย ในวันนี้ข้าพระองค์ทราบว่า ถ้าในวันนี้อับซาโลมยังมีชีวิตอยู่ และข้าพระองค์ทั้งหลายก็ตายสิ้น พระองค์ก็จะพอพระทัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 7, 'ฉะนั้น ขอพระองค์ทรงลุกขึ้น ณ บัดนี้ขอเสด็จออกไปตรัสให้ถึงใจข้าราชการทั้งหลาย เพราะข้าพระองค์ได้ปฏิญาณในพระนามพระเยโฮวาห์ว่า ถ้าพระองค์ไม่เสด็จจะไม่มีชายสักคนหนึ่งอยู่กับพระองค์ในคืนนี้ เรื่องนี้จะร้ายแรงยิ่งกว่าเหตุร้ายอื่นๆทั้งสิ้นซึ่งบังเกิดแก่พระองค์ตั้งแต่ยังทรงพระเยาว์จนบัดนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 8, 'กษัตริย์ก็ทรงลุกขึ้นประทับที่ประตูเมือง เขาไปบอกประชาชนทั้งหลายว่า “ดูเถิด กษัตริย์ประทับอยู่ที่ประตูเมือง” ประชาชนทั้งหลายก็มาเฝ้ากษัตริย์ ฝ่ายอิสราเอลนั้นต่างคนต่างก็หนีไปยังเต็นท์ของตนหมดแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 9, 'ประชาชนทั้งสิ้นก็หมางใจกันไปทั่วอิสราเอลทุกตระกูล กล่าวว่า “กษัตริย์เคยทรงช่วยเราให้พ้นจากมือศัตรูของเราและทรงช่วยเราให้พ้นจากมือคนฟีลิสเตีย บัดนี้พระองค์ทรงหนีอับซาโลมออกจากแผ่นดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 10, 'แต่อับซาโลมผู้ที่เราเจิมตั้งไว้เหนือเรานั้นก็สิ้นชีวิตเสียแล้วในสงคราม ฉะนั้นบัดนี้ ทําไมเจ้าไม่พูดอะไรบ้างเลยในเรื่องที่จะเชิญกษัตริย์ให้เสด็จกลับ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 11, 'กษัตริย์ดาวิดทรงใช้คนไปหาศาโดกและอาบียาธาร์ปุโรหิต รับสั่งว่า “ขอบอกพวกผู้ใหญ่ของคนยูดาห์ว่า ‘ทําไมท่านทั้งหลายจึงเป็นคนสุดท้ายที่จะเชิญกษัตริย์กลับพระราชวังของพระองค์ เมื่อถ้อยคําเหล่านี้มาจากอิสราเอลทั้งหลายถึงกษัตริย์ คือถึงราชวงศ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 12, 'ท่านทั้งหลายเป็นญาติของเรา เป็นกระดูกและเนื้อหนังของเรา ทําไมท่านจึงจะเป็นคนสุดท้ายที่จะเชิญกษัตริย์กลับ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 13, 'และจงบอกอามาสาว่า ‘ท่านมิได้เป็นกระดูกและเนื้อหนังของเราหรือ ถ้าท่านมิได้เป็นผู้บังคับบัญชากองทัพแทนโยอาบสืบต่อไป ขอพระเจ้าทรงลงโทษเรา และให้หนักยิ่งกว่านั้นอีก’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 14, 'พระองค์ก็ได้ชักจูงจิตใจของบรรดาคนยูดาห์ดังกับเป็นจิตใจของชายคนเดียว พวกเขาจึงส่งคนไปทูลกษัตริย์ว่า “ขอพระองค์เสด็จกลับพร้อมกับบรรดาข้าราชการทั้งหมดด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 15, 'กษัตริย์ก็เสด็จกลับและมายังแม่น้ําจอร์แดน และยูดาห์ก็พากันมาที่กิลกาลเพื่อรับเสด็จกษัตริย์และนํากษัตริย์เสด็จข้ามแม่น้ําจอร์แดน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 16, 'ชิเมอี บุตรชายเก-รา คนเบนยามินผู้มาจากบาฮูริม รีบลงมาพร้อมกับคนยูดาห์เพื่อจะรับเสด็จกษัตริย์ดาวิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 17, 'มีคนจากตระกูลเบนยามินพร้อมกับท่านหนึ่งพันคน และศิบามหาดเล็กในราชวงศ์ของซาอูล พร้อมกับบุตรชายสิบห้าคนกับคนใช้อีกยี่สิบคน ก็รีบมายังแม่น้ําจอร์แดนต่อพระพักตร์กษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 18, 'เขาทั้งหลายได้ข้ามท่าข้ามไปรับราชวงศ์ของกษัตริย์ และคอยปฏิบัติให้ชอบพระทัย ชิเมอี บุตรชายเก-รา ได้กราบลงต่อพระพักตร์กษัตริย์ขณะที่พระองค์เสด็จข้ามแม่น้ําจอร์แดน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 19, 'กราบทูลกษัตริย์ว่า “ขอเจ้านายของข้าพระองค์อย่าทรงถือโทษความชั่วช้าข้าพระองค์ และทรงจดจําความผิดที่ผู้รับใช้ของพระองค์ได้กระทําในวันที่กษัตริย์เจ้านายของข้าพระองค์สละกรุงเยรูซาเล็ม ขอกษัตริย์อย่าทรงจดจําไว้ในพระทัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 20, 'ด้วยผู้รับใช้ของพระองค์ได้ทราบแล้วว่าได้กระทําบาป เพราะฉะนั้น ดูเถิด ในวันนี้ข้าพระองค์ได้มาเป็นคนแรกในวงศ์วานโยเซฟที่ลงมารับเสด็จกษัตริย์เจ้านายของข้าพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 21, 'อาบีชัยบุตรชายนางเศรุยาห์จึงตอบว่า “ที่ชิเมอีกระทําเช่นนี้ไม่ควรจะถึงที่ตายดอกหรือ เพราะเขาได้ด่าผู้ที่เจิมตั้งของพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 22, 'แต่ดาวิดตรัสว่า “บุตรทั้งสองของนางเศรุยาห์เอ๋ย เรามีธุระอะไรกับท่าน ซึ่งในวันนี้ท่านจะมาเป็นปฏิปักษ์กับเรา ในวันนี้น่ะควรที่จะให้ใครมีโทษถึงตายในอิสราเอลหรือ ในวันนี้เราไม่ทราบดอกหรือว่า เราเป็นกษัตริย์ครอบครองอิสราเอล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 23, 'และกษัตริย์ตรัสกับชิเมอีว่า “เจ้าจะไม่ถึงตาย” แล้วกษัตริย์ก็ประทานคําปฏิญาณแก่เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 24, 'เมฟีโบเชท โอรสซาอูลก็ลงมารับเสด็จกษัตริย์ โดยมิได้แต่งเท้าหรือขลิบเครา หรือซักเสื้อผ้าของตนตั้งแต่วันที่กษัตริย์เสด็จจากไปจนวันที่เสด็จกลับมาโดยสันติภาพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 25, 'อยู่มาเมื่อเมฟีโบเชทมายังกรุงเยรูซาเล็มเพื่อจะรับเสด็จกษัตริย์ กษัตริย์ตรัสถามว่า “เมฟีโบเชท ทําไมท่านมิได้ไปกับเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 26, 'ท่านทูลตอบว่า “โอ ข้าแต่กษัตริย์เจ้านายของข้าพระองค์ มหาดเล็กของข้าพระองค์หลอกลวงข้าพระองค์ เพราะผู้รับใช้ของพระองค์บอกเขาว่า ‘ข้าจะผูกอานลาตัวหนึ่งเพื่อข้าจะได้ขี่ไปตามเสด็จกษัตริย์’ เพราะว่าผู้รับใช้ของพระองค์เป็นง่อย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 27, 'เขากลับไปทูลกษัตริย์เจ้านายของข้าพระองค์ใส่ร้ายผู้รับใช้ของพระองค์ แต่กษัตริย์เจ้านายของข้าพระองค์เหมือนทูตสวรรค์องค์หนึ่งของพระเจ้า เมื่อพระองค์ทรงเห็นสมควรจะกระทําประการใด ก็ขอทรงกระทําเถิด พ่ะย่ะค่ะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 28, 'เพราะว่าวงศ์วานราชบิดาของข้าพระองค์ทั้งสิ้นก็สมควรถึงตายต่อพระพักตร์กษัตริย์เจ้านายของข้าพระองค์ แต่พระองค์ก็ทรงแต่งตั้งผู้รับใช้ของพระองค์ไว้ในหมู่ผู้ที่รับประทานร่วมโต๊ะเสวยของพระองค์ ข้าพระองค์จะมีสิทธิประการใดเล่าที่จะร้องทูลอีกต่อกษัตริย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 29, 'กษัตริย์จึงตรัสกับท่านว่า “ท่านจะพูดเรื่องธุรกิจของท่านต่อไปทําไม เราตัดสินใจว่า ท่านกับศิบาจงแบ่งที่ดินกัน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 30, 'เมฟีโบเชทกราบทูลกษัตริย์ว่า “เมื่อกษัตริย์เจ้านายของข้าพระองค์ได้เสด็จกลับสู่พระราชสํานักโดยสันติภาพเช่นนี้แล้ว ก็ให้ศิบารับไปหมดเถิด พ่ะย่ะค่ะ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 31, 'ฝ่ายบารซิลลัย ชาวกิเลอาด ได้ลงมาจากโรเกลิม และไปกับกษัตริย์ข้ามแม่น้ําจอร์แดน เพื่อส่งพระองค์ข้ามแม่น้ําจอร์แดนไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 32, 'บารซิลลัยเป็นคนชรามากแล้ว อายุแปดสิบปี ท่านได้นําเสบียงอาหารมาถวายกษัตริย์ ขณะพระองค์ประทับที่มาหะนาอิม เพราะท่านเป็นคนมั่งมีมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 33, 'กษัตริย์จึงตรัสกับบารซิลลัยว่า “ข้ามมาอยู่กับเราเสียเถิด เราจะชุบเลี้ยงท่านให้อยู่กับเราที่กรุงเยรูซาเล็ม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 34, 'แต่บารซิลลัยทูลกษัตริย์ว่า “ข้าพระองค์จะอยู่ต่อไปได้อีกกี่ปี ที่ข้าพระองค์จะไปอยู่กับกษัตริย์ที่กรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 35, 'วันนี้ข้าพระองค์มีอายุแปดสิบปีแล้ว ข้าพระองค์จะสังเกตว่าอะไรเป็นที่พอใจและไม่พอใจได้หรือ ผู้รับใช้ของพระองค์จะลิ้มรสอร่อยของสิ่งที่กินและดื่มได้หรือ ข้าพระองค์จะฟังเสียงชายหญิงร้องเพลงได้หรือ ทําไมจะให้ผู้รับใช้ของพระองค์เป็นภาระเพิ่มแก่กษัตริย์เจ้านายของข้าพระองค์อีกเล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 36, 'ผู้รับใช้ของพระองค์จะตามเสด็จกษัตริย์ข้ามแม่น้ําจอร์แดนไปหน่อยเท่านั้น ไฉนกษัตริย์จะพระราชทานรางวัลเช่นนี้เล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 37, 'ขอให้ผู้รับใช้ของพระองค์กลับเพื่อไปตายที่ในเมืองของข้าพระองค์ และถูกฝังข้างๆที่ฝังศพของบิดามารดาของข้าพระองค์ ดูเถิด ขอทรงโปรดให้คิมฮามผู้รับใช้ของพระองค์ตามเสด็จกษัตริย์เจ้านายของข้าพระองค์ไป พระองค์จะโปรดเขาประการใดก็แล้วแต่ทรงเห็นควร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 38, 'กษัตริย์ตรัสตอบว่า “คิมฮามจงข้ามไปกับเรา เราจะกระทําคุณแก่เขาตามที่ท่านเห็นควร สิ่งใดที่ท่านปรารถนาให้เรากระทําแก่ท่าน เรายินดีกระทําตาม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 39, 'แล้วประชาชนทั้งสิ้นก็ข้ามแม่น้ําจอร์แดน เมื่อกษัตริย์เสด็จข้ามไปแล้วกษัตริย์ทรงจุบบารซิลลัย และทรงอวยพระพรแก่ท่าน ท่านก็กลับไปยังบ้านช่องของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 40, 'กษัตริย์เสด็จไปยังกิลกาล และคิมฮามก็ข้ามตามเสด็จไปด้วย ประชาชนยูดาห์ทั้งหมดกับประชาชนอิสราเอลครึ่งหนึ่งได้นํากษัตริย์ข้ามมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 41, 'แล้วดูเถิด คนอิสราเอลทั้งหมดมาเฝ้ากษัตริย์ กราบทูลกษัตริย์ว่า “ไฉนคนยูดาห์พี่น้องของเราจึงได้ลักพาพระองค์ไปเสีย พากษัตริย์และราชวงศ์ข้ามแม่น้ําจอร์แดนไปพร้อมกับบรรดาคนของดาวิดด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 42, 'ประชาชนยูดาห์ทั้งสิ้นจึงตอบประชาชนอิสราเอลว่า “เพราะกษัตริย์เป็นญาติสนิทกับเราท่านทั้งหลาย จะโกรธด้วยเรื่องนี้ทําไมเล่า เราได้อยู่กินสิ้นเปลืองพระราชทรัพย์ของกษัตริย์หรือ พระองค์ได้ให้รางวัลอะไรแก่เราหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 43, 'คนอิสราเอลก็ตอบคนยูดาห์ว่า “เรามีส่วนในกษัตริย์สิบส่วน และในดาวิดเราก็มีสิทธิมากกว่าท่าน ทําไมท่านจึงดูถูกเราเช่นนี้เล่า เราไม่ได้เป็นพวกแรกที่พูดเรื่องการนํากษัตริย์กลับดอกหรือ” แต่ถ้อยคําของคนยูดาห์รุนแรงกว่าถ้อยคําของคนอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 1, 'เผอิญที่นั่นมีคนของเบลีอัลอยู่คนหนึ่งชื่อเชบาบุตรชายบิครี คนเบนยามิน เขาได้เป่าแตรขึ้นกล่าวว่า “เราไม่มีส่วนในดาวิด เราไม่มีมรดกในบุตรของเจสซี โอ อิสราเอลเอ๋ย ให้ต่างคนต่างกลับไปเต็นท์ของตนเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 2, 'ดังนั้นพวกคนอิสราเอลทั้งหมดจึงถอนตัวจากดาวิด และไปตามเชบาบุตรชายบิครี แต่พวกคนยูดาห์ได้ติดตามกษัตริย์ของเขาอย่างมั่นคงจากแม่น้ําจอร์แดนไปถึงกรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 3, 'ดาวิดเสด็จกลับพระราชวังที่กรุงเยรูซาเล็ม กษัตริย์ก็รับสั่งให้นํานางสนมทั้งสิบคนที่พระองค์ทรงละไว้ให้เฝ้าพระราชวังนั้นไปรวมกักอยู่ในบ้านหลังหนึ่ง ทรงชุบเลี้ยงไว้แต่มิได้ทรงเข้าหาพวกนาง นางเหล่านั้นก็ต้องถูกกักให้มีชีวิตอยู่อย่างหญิงม่ายจนวันตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 4, 'กษัตริย์ตรัสสั่งอามาสาว่า “จงระดมพลยูดาห์ให้มาพร้อมกันที่นี่ภายในสามวัน ตัวท่านจงมาด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 5, 'อามาสาก็ออกไประดมคนยูดาห์ แต่เขาก็ทํางานล่าช้าเกินกําหนดที่พระองค์รับสั่งไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 6, 'ดาวิดตรัสกับอาบีชัยว่า “บัดนี้เชบาบุตรบิครีจะทําอันตรายแก่เรายิ่งกว่าอับซาโลม จงนําข้าราชการทหารของเจ้านายของท่านไปติดตาม เกรงว่าเขาจะหาเมืองที่มีป้อมได้และหนีพ้นเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 7, 'มีคนของโยอาบตามเขาไป และคนเคเรธี กับคนเปเลท กับทหารที่แข็งกล้าทั้งหมด และเขาทั้งหลายยกออกไปจากกรุงเยรูซาเล็มเพื่อไล่ตามเชบาบุตรชายบิครี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 8, 'เมื่อเขาทั้งหลายมาถึงศิลาใหญ่ที่อยู่ในเมืองกิเบโอน อามาสาก็มาพบกับเขาทั้งหลาย ฝ่ายโยอาบสวมเครื่องแต่งกายทหารมีเข็มขัดติดดาบที่อยู่ในฝักคาดอยู่ที่บั้นเอว เมื่อท่านเดินไปดาบก็ตกลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 9, 'โยอาบจึงถามอามาสาว่า “พี่ชายเอ๋ย สบายดีหรือ” และโยอาบก็เอามือขวาจับเคราอามาสาจะจุบเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 10, 'แต่อามาสาไม่ได้สังเกตเห็นดาบซึ่งอยู่ในมือของโยอาบ โยอาบจึงเอาดาบแทงท้องอามาสา ไส้ทะลักถึงดิน ไม่ต้องแทงครั้งที่สอง เขาก็ตายเสียแล้ว แล้วโยอาบกับอาบีชัยน้องชายก็ไล่ตามเชบาบุตรชายบิครีไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 11, 'ทหารหนุ่มคนหนึ่งของโยอาบมายืนอยู่ใกล้อามาสาพูดว่า “ผู้ใดเห็นชอบฝ่ายโยอาบและผู้ใดอยู่ฝ่ายดาวิดให้ผู้นั้นติดตามโยอาบไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 12, 'อามาสาก็นอนเกลือกโลหิตของตัวอยู่ที่ในทางหลวง เมื่อชายคนนั้นเห็นประชาชนทั้งสิ้นมาหยุดอยู่ เขาก็นําศพอามาสาจากทางหลวงไปทิ้งในทุ่งนาและเอาเสื้อผ้าปิดไว้ เพราะเขาเห็นว่าเมื่อใครมาก็เข้าไปหยุดอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 13, 'เมื่อเอาศพอามาสาออกจากทางหลวงแล้ว ประชาชนทั้งปวงก็ตามโยอาบเพื่อติดตามเชบาบุตรชายบิครี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 14, 'เชบาก็ผ่านคนอิสราเอลทุกตระกูลไปจนถึงตําบลอาเบล และเมืองเบธมาอาคาห์ และบรรดาคนบีไรต์ คนเหล่านั้นก็มารวมกันและติดตามเขาไปด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 15, 'พวกเขาก็มาถึงและล้อมเขาไว้ในตําบลอาเบลแขวงเมืองเบธมาอาคาห์ เขาทําเชิงเทินขึ้นที่ริมกําแพงเมือง ประชาชนทั้งหลายที่อยู่กับโยอาบก็ทะลวงกําแพงเพื่อจะให้พัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 16, 'มีหญิงฉลาดคนหนึ่งร้องออกมาจากในเมืองว่า “ขอฟังหน่อย ขอฟังหน่อย ขอบอกโยอาบให้มาที่นี่ ฉันอยากจะพูดด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 17, 'โยอาบก็เข้ามาใกล้หญิงนั้น นางนั้นก็พูดว่า “ท่านคือโยอาบหรือ” เขาตอบว่า “ใช่แล้ว” นางจึงเรียนท่านว่า “ขอท่านฟังถ้อยคําของสาวใช้ของท่านสักหน่อย” ท่านก็ตอบว่า “ฉันกําลังฟังอยู่แล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 18, 'นางก็พูดว่า “สมัยโบราณเขาพูดกันว่า ‘ให้เขาขอคําปรึกษาที่อาเบลเถิด’ แล้วเขาก็ตกลงกันได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 19, 'ฉันเป็นคนหนึ่งที่รักสงบและสัตย์ซื่อในอิสราเอล ท่านหาช่องที่จะทําลายเมือง อันเป็นเมืองแม่ในอิสราเอล ทําไมท่านจึงจะกลืนมรดกของพระเยโฮวาห์เสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 20, 'โยอาบจึงตอบว่า “ซึ่งฉันจะกลืนหรือทําลายนั้น ขอให้ห่างไกลจากฉัน ขอให้ห่างไกลทีเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 21, 'เรื่องนี้ไม่เป็นความจริง แต่มีชายคนหนึ่งจากแดนเทือกเขาเอฟราอิมชื่อเชบาบุตรบิครี ได้ยกมือของเขาขึ้นต่อสู้กษัตริย์ คือต่อสู้ดาวิด จงมอบเขามาแต่คนเดียว ฉันจะถอยทัพกลับจากเมืองนี้” หญิงนั้นจึงตอบโยอาบว่า “ดูเถิด เราจะโยนศีรษะของเขาข้ามกําแพงมาให้ท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 22, 'แล้วหญิงนั้นก็ไปหาประชาชนทั้งปวงด้วยปัญญาของนาง เขาทั้งหลายได้ตัดศีรษะของเชบาบุตรชายบิครีโยนออกมาให้โยอาบ โยอาบก็เป่าแตร พวกเขาจึงถอนตัวจากนครนั้นกลับไปยังเต็นท์ของตนทุกคน โยอาบก็กลับไปเฝ้ากษัตริย์ที่กรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 23, 'โยอาบเป็นผู้บังคับบัญชากองทัพทั้งหมดในอิสราเอล และเบไนยาห์บุตรชายเยโฮยาดาเป็นผู้บังคับบัญชากองคนเคเรธีและคนเปเลท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 24, 'และอาโดรัมดูแลคนงานโยธา เยโฮชาฟัทบุตรชายอาหิลูดเป็นเจ้ากรมสารบรรณ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 25, 'เชวาเป็นราชเลขา ศาโดกกับอาบียาธาร์เป็นปุโรหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 26, 'อิราคนยาอีร์เป็นประมุขของดาวิดด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 1, 'ในสมัยของดาวิดมีการกันดารอาหารอยู่สามปี ปีแล้วปีเล่า และดาวิดทรงอธิษฐานอ้อนวอนต่อพระเยโฮวาห์ พระเยโฮวาห์ตรัสว่า “เพราะเหตุซาอูลและวงศ์วานกระหายโลหิตของเขา เพราะเขาฆ่าคนกิเบโอน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 2, 'กษัตริย์จึงทรงเรียกคนกิเบโอนมาตรัสแก่เขา (ฝ่ายคนกิเบโอนนั้นไม่ใช่ประชาชนอิสราเอล แต่เป็นคนอาโมไรต์ที่ยังเหลืออยู่ ประชาชนอิสราเอลได้สาบานไว้แก่เขาทั้งหลายแล้ว แต่ซาอูลก็ทรงหาช่องที่จะสังหารเขาทั้งหลายเสีย เพราะความร้อนใจที่เห็นแก่คนอิสราเอลและคนยูดาห์)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 3, 'ดาวิดตรัสถามคนกิเบโอนว่า “เราจะกระทําอะไรให้แก่พวกท่านได้ เราจะทําอย่างไรจึงจะลบมลทินบาปเสียได้ เพื่อพวกท่านจะได้อวยพรแก่มรดกของพระเยโฮวาห์ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 4, 'คนกิเบโอนทูลตอบพระองค์ว่า “พวกข้าพระองค์จะไม่รับเงินหรือทองจากซาอูลและวงศ์วานของท่านนั้น ทั้งพวกข้าพระองค์ไม่จําเป็นให้พระองค์ประหารชีวิตอิสราเอลคนหนึ่งคนใด” พระองค์จึงตรัสว่า “แล้วพวกท่านจะให้เรากระทําอะไรแก่ท่านเล่า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 5, 'เขากราบทูลกษัตริย์ว่า “ชายผู้ที่เผาผลาญพวกข้าพระองค์ และวางแผนการทําลายพวกข้าพระองค์เพื่อมิให้พวกข้าพระองค์มีที่อยู่ในเขตแดนอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 6, 'ขอทรงมอบบุตรชายเจ็ดคนของท่านให้แก่พวกข้าพระองค์ เพื่อพวกข้าพระองค์จะได้แขวนเขาเสียต่อพระพักตร์พระเยโฮวาห์ที่กิเบอาห์แห่งซาอูลผู้เลือกสรรของพระเยโฮวาห์” และกษัตริย์ตรัสว่า “เราจะจัดเขามาให้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 7, 'แต่กษัตริย์ทรงไว้ชีวิตเมฟีโบเชท บุตรชายของโยนาธาน ราชโอรสของซาอูล ด้วยเหตุคําปฏิญาณระหว่างทั้งสองที่กระทําในพระนามพระเยโฮวาห์ คือระหว่างดาวิดกับโยนาธานราชโอรสของซาอูล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 8, 'แต่กษัตริย์นําเอาบุตรชายสองคนของนางริสปาห์บุตรสาวของอัยยาห์ซึ่งบังเกิดกับซาอูล ชื่ออารโมนีกับเมฟีโบเชท กับบุตรชายห้าคนของมีคาลราชธิดาของซาอูล ซึ่งพระนางมีกับอาดรีเอลบุตรชายบารซิลลัยชาวเมโหลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 9, 'พระองค์ทรงมอบคนเหล่านี้ไว้ในมือของคนกิเบโอน เขาทั้งหลายจึงแขวนคอทั้งเจ็ดไว้บนภูเขาต่อพระพักตร์พระเยโฮวาห์ และทั้งเจ็ดคนก็พินาศไปด้วยกัน เขาถูกฆ่าตายในสมัยฤดูเกี่ยวข้าว ในวันต้น คือวันแรกของการเกี่ยวข้าวบาร์เลย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 10, 'แล้วนางริสปาห์บุตรสาวของอัยยาห์ก็เอาผ้ากระสอบปูไว้บนก้อนหินสําหรับตนเอง ตั้งแต่ต้นฤดูเกี่ยวจนฝนจากท้องฟ้าตกบนเขาทั้งหลาย กลางวันนางก็ไม่ยอมให้นกมาเกาะ หรือกลางคืนก็ไม่ให้สัตว์ป่าทุ่งมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 11, 'มีคนกราบทูลดาวิดว่านางริสปาห์บุตรสาวของอัยยาห์นางสนมของซาอูลกระทําอย่างไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 12, 'ดาวิดก็เสด็จไปนําอัฐิของซาอูลและอัฐิของโยนาธานราชโอรสมาจากคนเมืองยาเบชกิเลอาด ผู้ที่ลักลอบเอาไปจากถนนเมืองเบธชาน ที่คนฟีลิสเตียได้แขวนพระองค์ทั้งสองไว้ ในเมื่อคนฟีลิสเตียประหารซาอูลบนเขากิลโบอา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 13, 'พระองค์ทรงนําอัฐิของซาอูลและอัฐิของโยนาธานราชโอรสขึ้นมาจากที่นั่น และรวบรวมกระดูกของผู้ที่ถูกแขวนไว้ให้ตายนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 14, 'และเขาก็ฝังอัฐิของซาอูลและของโยนาธานราชโอรสไว้ในแผ่นดินของเบนยามินในเมืองเศลาในอุโมงค์ของคีชบิดาของพระองค์ เขาทั้งหลายก็กระทําตามทุกอย่างที่กษัตริย์ทรงสั่งไว้ ครั้นต่อมาพระเจ้าก็ทรงสดับฟังคําอธิษฐานเพื่อแผ่นดินนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 15, 'คนฟีลิสเตียได้ทําสงครามกับคนอิสราเอลอีก ดาวิดก็ลงไปพร้อมกับบรรดาข้าราชการของพระองค์ และได้สู้รบกับคนฟีลิสเตีย และดาวิดก็ทรงอ่อนเพลีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 16, 'อิชบีเบโนบ บุตรชายคนหนึ่งของคนยักษ์ ถือหอกทองเหลืองหนักสามร้อยเชเขล มีดาบใหม่คาดเอว คิดจะสังหารดาวิดเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 17, 'แต่อาบีชัยบุตรชายนางเศรุยาห์เข้ามาช่วยพระองค์ไว้ และสู้รบกับคนฟีลิสเตียคนนั้นฆ่าเขาเสีย แล้วบรรดาประชาชนของดาวิดก็ปฏิญาณต่อพระองค์ว่า “ขอพระองค์อย่าเสด็จไปทําศึกพร้อมกับพวกข้าพระองค์ทั้งหลายอีกต่อไปเลย เกรงว่าพระองค์จะดับประทีปของอิสราเอลเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 18, 'อยู่มาภายหลังนี้ มีการรบกับคนฟีลิสเตียอีกที่เมืองโกบ คราวนั้นสิบเบคัยคนหุชาห์ได้ฆ่าสัฟบุตรชายคนหนึ่งของคนยักษ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 19, 'และมีการรบกับคนฟีลิสเตียที่เมืองโกบอีก เอลฮานันบุตรชายยาอาเรโอเรกิมชาวเบธเลเฮมได้ฆ่าน้องชายโกลิอัทชาวกัท ผู้มีหอกที่มีด้ามโตเท่าไม้กระพั่นทอผ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 20, 'มีการรบกันอีกที่เมืองกัท อันเป็นเมืองที่มีชายคนหนึ่งรูปร่างใหญ่โต มีนิ้วมือข้างละหกนิ้ว และนิ้วเท้าข้างละหกนิ้ว รวมกันยี่สิบสี่นิ้ว เขาก็บังเกิดแก่คนยักษ์นั้นด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 21, 'เมื่อเขาท้าทายอิสราเอล โยนาธานบุตรชายของชิเมอาเชษฐาของดาวิด ก็สังหารเขาเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 22, 'คนทั้งสี่นี้บังเกิดแก่คนยักษ์ในเมืองกัท เขาทั้งหลายล้มตายด้วยพระหัตถ์ของดาวิด และด้วยมือของข้าราชการของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 1, 'ในวันที่พระเยโฮวาห์ทรงช่วยดาวิดให้พ้นจากมือของศัตรูทั้งสิ้นของพระองค์ท่าน และให้พ้นจากพระหัตถ์ของซาอูล ดาวิดก็ถวายถ้อยคําของเพลงบทนี้แด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 2, 'พระองค์ท่านตรัสว่า “พระเยโฮวาห์ทรงเป็นศิลา ป้อมปราการ และผู้ช่วยให้รอดพ้นของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 3, 'เป็นพระเจ้าซึ่งทรงเป็นศิลาของข้าพเจ้า ข้าพเจ้าจะวางใจในพระองค์ พระองค์เป็นโล่และเป็นเขาแห่งความรอดของข้าพเจ้า เป็นที่กําบังเข้มแข็งและเป็นที่ลี้ภัยของข้าพเจ้า องค์พระผู้ช่วยของข้าพระองค์เจ้าข้า พระองค์ทรงช่วยข้าพระองค์ให้รอดจากความทารุณ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 4, 'ข้าพเจ้าร้องทูลต่อพระเยโฮวาห์ ผู้ทรงสมควรแก่การสรรเสริญ และข้าพเจ้าจะได้รับการช่วยให้พ้นจากศัตรูของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 5, 'เมื่อคลื่นแห่งความตายล้อมข้าพเจ้า กระแสแห่งคนอธรรมที่ท่วมทับข้าพเจ้าทําให้ข้าพเจ้ากลัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 6, 'ความเศร้าโศกแห่งนรกอยู่รอบตัวข้าพเจ้า บ่วงแห่งความตายขัดขวางข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 7, 'ในยามทุกข์ใจข้าพเจ้าร้องทูลต่อพระเยโฮวาห์ ข้าพเจ้าร้องทูลต่อพระเจ้าของข้าพเจ้า พระองค์ทรงสดับเสียงของข้าพเจ้าจากพระวิหารของพระองค์ และเสียงร้องของข้าพเจ้ามาถึงพระกรรณของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 8, 'แล้วแผ่นดินโลกก็สั่นสะเทือนและโคลงเคลง รากฐานของฟ้าสวรรค์ก็หวั่นไหวและสั่นสะเทือน เพราะพระองค์ทรงกริ้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 9, 'ควันออกไปตามช่องพระนาสิกของพระองค์ และเพลิงผลาญออกมาจากพระโอษฐ์ของพระองค์ ถ่านก็ติดเปลวไฟนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 10, 'พระองค์ทรงโน้มฟ้าสวรรค์ลงด้วย และเสด็จลงมา ความมืดทึบอยู่ใต้พระบาทของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 11, 'พระองค์ทรงเครูบตนหนึ่ง และทรงเหาะไป เออ เห็นพระองค์เสด็จโดยปีกของลม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 12, 'พระองค์ทรงกระทําความมืดเป็นพลับพลาอยู่รอบพระองค์ ที่รวบรวมบรรดาน้ําและเมฆทึบแห่งฟ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 13, 'ถ่านลุกเป็นเพลิงจากความสุกใสข้างหน้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 14, 'พระเยโฮวาห์ทรงคะนองกึกก้องจากฟ้าสวรรค์ และองค์ผู้สูงสุดก็เปล่งพระสุรเสียงของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 15, 'และพระองค์ทรงใช้ลูกธนูของพระองค์ออกมา ทําให้เขากระจายไป พระองค์ทรงปล่อยฟ้าแลบและทําให้เขาโกลาหล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 16, 'แล้วก็เห็นท้องธาร รากฐานของพิภพก็ปรากฏแจ้งตามการขนาบของพระเยโฮวาห์ ตามที่ลมพวยพุ่งจากช่องพระนาสิกของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 17, 'พระองค์ทรงเอื้อมมาจากที่สูงทรงจับข้าพเจ้า พระองค์ทรงดึงข้าพเจ้าออกมาจากน้ํามากหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 18, 'พระองค์ทรงช่วยข้าพเจ้าให้รอดพ้นจากศัตรูที่เข้มแข็งของข้าพเจ้า จากบรรดาผู้ที่เกลียดชังข้าพเจ้า เพราะเขามีกําลังมากกว่าข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 19, 'เขาขัดขวางข้าพเจ้าในวันที่ข้าพเจ้าประสบหายนะ แต่พระเยโฮวาห์ทรงเป็นที่พักพิงของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 20, 'พระองค์ทรงนําข้าพเจ้าออกมายังที่กว้างใหญ่ด้วย พระองค์ทรงช่วยข้าพเจ้าให้รอดพ้น เพราะพระองค์ทรงยินดีในข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 21, 'พระเยโฮวาห์ทรงประทานรางวัลแก่ข้าพเจ้าตามความชอบธรรมของข้าพเจ้า พระองค์ทรงตอบแทนข้าพเจ้าตามความสะอาดแห่งมือของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 22, 'เพราะข้าพเจ้ารักษาบรรดาพระมรรคาของพระเยโฮวาห์ และไม่ได้พรากจากพระเจ้าของข้าพเจ้าอย่างชั่วร้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 23, 'เพราะคําตัดสินทั้งสิ้นของพระองค์อยู่ต่อหน้าข้าพเจ้า และข้าพเจ้ามิได้หันจากกฎเกณฑ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 24, 'ต่อพระพักตร์พระองค์ข้าพเจ้าไร้ตําหนิ และข้าพเจ้ารักษาตัวไว้ให้พ้นจากความชั่วช้าของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 25, 'เพราะฉะนั้นพระเยโฮวาห์ทรงตอบแทนข้าพเจ้าตามความชอบธรรมของข้าพเจ้า ตามความสะอาดของข้าพเจ้าในสายพระเนตรของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 26, 'พระองค์ทรงสําแดงความเมตตาต่อผู้ที่เต็มไปด้วยความเมตตา พระองค์ทรงสําแดงพระองค์ไร้ตําหนิต่อผู้ที่ไร้ตําหนิ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 27, 'พระองค์ทรงสําแดงพระองค์บริสุทธิ์ต่อผู้ที่บริสุทธิ์ พระองค์ทรงสําแดงพระองค์เป็นปฏิปักษ์ต่อผู้ที่คดโกง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 28, 'พระองค์ทรงช่วยประชาชนที่ลําบากให้รอดพ้น แต่พระองค์ทอดพระเนตรผู้ที่ยโสเพื่อนําเขาให้ต่ําลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 29, 'โอ ข้าแต่พระเยโฮวาห์ พระองค์ทรงเป็นประทีปของข้าพระองค์ พระเยโฮวาห์จะทรงกระทําให้ความมืดของข้าพเจ้าสว่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 30, 'พ่ะย่ะค่ะ ข้าพระองค์ตะลุยกองทัพได้โดยพระองค์ โดยพระเจ้าของข้าพเจ้าข้าพเจ้ากระโดดข้ามกําแพงได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 31, 'ฝ่ายพระเจ้า พระมรรคาของพระองค์บริสุทธิ์หมดจด พระวจนะของพระเยโฮวาห์พิสูจน์แล้ว พระองค์ทรงเป็นดั้งของบรรดาผู้ที่วางใจในพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 32, 'เพราะผู้ใดเป็นพระเจ้านอกจากพระเยโฮวาห์ และผู้ใดเล่าเป็นศิลานอกจากพระเจ้าของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 33, 'พระเจ้าทรงเป็นป้อมเข้มแข็งของข้าพเจ้า และพระองค์ทรงทําให้ทางของข้าพเจ้าสมบูรณ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 34, 'พระองค์ทรงกระทําให้เท้าของข้าพเจ้าเหมือนอย่างตีนกวางตัวเมีย และทรงวางข้าพเจ้าไว้บนที่สูงของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 35, 'พระองค์ทรงหัดมือของข้าพเจ้าให้ทําสงคราม แขนของข้าพเจ้าจึงโก่งคันธนูเหล็กกล้าได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 36, 'พระองค์ประทานโล่แห่งความรอดของพระองค์ให้ข้าพระองค์ และซึ่งพระองค์ทรงน้อมพระทัยลงก็กระทําให้ข้าพระองค์เป็นใหญ่ขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 37, 'พระองค์ประทานที่กว้างขวางสําหรับเท้าของข้าพระองค์ เท้าของข้าพระองค์จึงไม่พลาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 38, 'ข้าพระองค์ไล่ตามศัตรูของข้าพระองค์และได้ทําลายเขาเสีย และไม่หันกลับจนกว่าเขาถูกผลาญเสียสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 39, 'ข้าพระองค์ผลาญเขา ข้าพระองค์แทงเขาทะลุ เขาจึงไม่สามารถลุกขึ้นอีกได้พ่ะย่ะค่ะ เขาล้มลงใต้เท้าของข้าพระองค์แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 40, 'เพราะพระองค์ทรงคาดเอวข้าพระองค์ไว้ด้วยกําลังเพื่อทําสงคราม พระองค์ทรงกระทําให้พวกที่ลุกขึ้นต่อสู้ข้าพระองค์จมลงใต้ข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 41, 'พระองค์ทรงโปรดประทานคอของศัตรูของข้าพระองค์แก่ข้าพระองค์ บรรดาผู้ที่เกลียดชังข้าพระองค์ ข้าพระองค์ก็ทําลายเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 42, 'เขามองหา แต่ไม่มีใครช่วยให้รอดได้ เขาร้องทูลต่อพระเยโฮวาห์ แต่พระองค์มิได้ทรงตอบเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 43, 'ข้าพระองค์ทุบตีเขาแหลกละเอียดอย่างผงคลีดิน ข้าพระองค์เหยียบเขาลงเหมือนโคลนตามถนน และกระจายเขาออกไปทั่ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 44, 'พระองค์ทรงช่วยข้าพระองค์ให้รอดพ้นจากการเกี่ยงแย่งประชาชนของข้าพระองค์ พระองค์ทรงรักษาข้าพระองค์ไว้ให้เป็นหัวหน้าของบรรดาประชาชาติ ชนชาติที่ข้าพระองค์ไม่เคยรู้จักก็จะปรนนิบัติข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 45, 'ชนต่างด้าวจะมาจํานนต่อข้าพระองค์ พอเขาได้ยินถึงข้าพระองค์เขาก็จะเชื่อฟังข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 46, 'ชนต่างด้าวเสียกําลังใจ และตัวสั่นออกมาจากที่กําบังของเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 47, 'พระเยโฮวาห์ทรงพระชนม์อยู่ และศิลาของข้าพระองค์เป็นที่สรรเสริญ พระเจ้าของศิลาแห่งความรอดของข้าพระองค์เป็นที่ยกย่อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 48, 'พระเจ้าเป็นผู้ทรงกระทําการแก้แค้นให้แก่ข้าพระองค์ และนําชนชาติทั้งหลายลงให้อยู่ใต้ข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 49, 'ผู้ทรงนําข้าพระองค์ออกมาจากศัตรูของข้าพระองค์พ่ะย่ะค่ะ พระองค์ทรงยกข้าพระองค์ให้เหนือผู้ที่ลุกขึ้นต่อสู้ข้าพระองค์ พระองค์ทรงช่วยข้าพระองค์ให้รอดพ้นจากคนทารุณ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 50, 'โอ ข้าแต่พระเยโฮวาห์ เพราะเหตุนี้ข้าพระองค์ขอขอบพระคุณพระองค์ในหมู่ประชาชาติทั้งหลาย และจะร้องเพลงสรรเสริญพระนามของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 51, 'พระองค์ทรงเป็นป้อมแห่งความรอดแก่กษัตริย์ของพระองค์ และทรงสําแดงความเมตตาแก่ผู้ที่ทรงเจิมของพระองค์ แก่ดาวิดและเชื้อสายของท่านเป็นนิตย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 1, 'ต่อไปนี้เป็นวาทะสุดท้ายของดาวิด ดาวิดบุตรชายเจสซีได้กล่าวและชายที่ได้รับการแต่งตั้งขึ้นให้สูงได้กล่าว คือผู้ที่ถูกเจิมตั้งไว้ของพระเจ้าแห่งยาโคบ นักแต่งสดุดีอย่างไพเราะของอิสราเอล ได้กล่าวดังนี้ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 2, '“โดยข้าพเจ้า พระวิญญาณของพระเยโฮวาห์ได้ตรัส พระวจนะของพระองค์อยู่ที่ลิ้นของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 3, 'พระเจ้าแห่งอิสราเอลทรงลั่นพระวาจา ศิลาแห่งอิสราเอลได้ตรัสกับข้าพเจ้าว่า ‘ผู้ที่ปกครองมนุษย์ต้องเป็นคนชอบธรรม คือปกครองด้วยความยําเกรงพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 4, 'เขาทอแสงเหมือนแสงอรุณ เมื่อดวงอาทิตย์ขึ้น คือรุ่งเช้าที่ไม่มีเมฆ ซึ่งเมื่อภายหลังฝน กระทําให้หญ้างอกออกจากดิน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 5, 'ถึงแม้ว่าวงศ์วานของข้าพเจ้าไม่เป็นเช่นนั้นกับพระเจ้าแล้ว แต่พระองค์ยังทรงกระทําพันธสัญญาเนืองนิตย์กับข้าพเจ้าไว้ อันเป็นระเบียบทุกอย่างและมั่นคง เพราะนี่เป็นความรอดและความปรารถนาทั้งสิ้นของข้าพเจ้า ถึงแม้ว่าพระองค์ไม่ทรงกระทําให้เจริญขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 6, 'แต่ลูกของเบลีอัลก็เป็นเหมือนหนามที่ต้องผลักไสไป เพราะว่าจะเอามือหยิบก็ไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 7, 'แต่คนที่แตะต้องมันต้องมีอาวุธที่ทําด้วยเหล็กและมีด้ามหอก และต้องเผาผลาญเสียให้สิ้นเชิงด้วยไฟในที่เดียวกัน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 8, 'ต่อไปนี้เป็นชื่อวีรบุรุษที่ดาวิดทรงมีอยู่ คือคนทัคโมนีผู้มีตําแหน่งสูง เป็นหัวหน้าพวกผู้บังคับบัญชา คืออาดีโนคนเอสนีย์ ท่านเหวี่ยงหอกเข้าแทงคนแปดร้อยคนซึ่งเขาได้ฆ่าเสียในครั้งเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 9, 'ในจํานวนวีรบุรุษสามคน คนที่รองคนนั้นมา คือเอเลอาซาร์บุตรชายโดโดคนอาโหอาห์ ท่านอยู่กับดาวิดเมื่อเขาทั้งหลายได้พูดหยามคนฟีลิสเตียซึ่งชุมนุมกันที่นั่นเพื่อสู้รบ และคนอิสราเอลก็ถอยทัพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 10, 'ท่านได้ลุกขึ้นฆ่าฟันคนฟีลิสเตียจนมือของท่านเมื่อยล้า มือของท่านเป็นเหน็บแข็งติดดาบ ในวันนั้นพระเยโฮวาห์ทรงกระทําให้ได้ชัยชนะอย่างใหญ่หลวง ทหารก็กลับตามท่านมาเพื่อปล้นข้าวของเท่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 11, 'รองท่านมาคือชัมมาห์ บุตรชายอาเกชาวฮาราร์ คนฟีลิสเตียมาชุมนุมกันเป็นกองทหาร เป็นที่ที่มีพื้นดินผืนหนึ่งมีถั่วแดงเต็มไปหมด พวกพลก็หนีคนฟีลิสเตียไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 12, 'แต่ท่านยืนมั่นอยู่ท่ามกลางพื้นดินผืนนั้น และป้องกันที่ดินนั้นไว้ และฆ่าฟันคนฟีลิสเตีย และพระเยโฮวาห์ได้ทรงประทานชัยชนะอย่างใหญ่หลวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 13, 'ในพวกทหารเอกสามสิบคนนั้นมีสามคนที่ลงมา และได้มาหาดาวิดที่ถ้ําอดุลลัมในฤดูเกี่ยวข้าว มีคนฟีลิสเตียกองหนึ่งตั้งค่ายอยู่ในหุบเขาเรฟาอิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 14, 'คราวนั้นดาวิดประทับในที่กําบังเข้มแข็ง และทหารประจําป้อมของฟีลิสเตียก็อยู่ที่เบธเลเฮม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 15, 'ดาวิดตรัสด้วยความอาลัยว่า “โอ ใครหนอจะส่งน้ําจากบ่อที่เบธเลเฮมซึ่งอยู่ข้างประตูเมืองมาให้เราดื่มได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 16, 'ทแกล้วทหารสามคนนั้นก็แหกค่ายคนฟีลิสเตียเข้าไป ตักน้ําที่บ่อเบธเลเฮมซึ่งอยู่ข้างประตูเมือง นํามาถวายแก่ดาวิด แต่ดาวิดหาทรงดื่มน้ํานั้นไม่ พระองค์ทรงเทออกถวายแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 17, 'และตรัสว่า “โอ ข้าแต่พระเยโฮวาห์ ซึ่งข้าพระองค์จะกระทําเช่นนี้ ก็ขอให้ห่างไกลจากข้าพระองค์ นี่คือโลหิตของผู้ที่ไปมาด้วยการเสี่ยงชีวิตของเขามิใช่หรือ” เพราะฉะนั้นพระองค์หาทรงดื่มไม่ ทแกล้วทหารทั้งสามได้กระทําสิ่งเหล่านี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 18, 'ฝ่ายอาบีชัยน้องชายของโยอาบบุตรชายนางเศรุยาห์ เป็นหัวหน้าของทั้งสามคนนั้น ท่านได้ยกหอกต่อสู้ทหารสามร้อยคน และฆ่าตายสิ้น และได้รับชื่อเสียงดังวีรบุรุษสามคนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 19, 'ท่านเป็นผู้ที่มีชื่อเสียงโด่งดังที่สุดในสามคนนั้นมิใช่หรือ ฉะนั้นได้เป็นผู้บังคับบัญชาของเขา แต่ท่านไม่มียศเท่ากับสามคนแรกนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 20, 'เบไนยาห์บุตรชายเยโฮยาดา เป็นบุตรชายของคนแข็งกล้าแห่งเมืองขับเซเอล เป็นคนประกอบมหกิจ ท่านได้ฆ่าคนดุจสิงโตของโมอับเสียสองคน ท่านได้ลงไปฆ่าสิงโตที่ในบ่อในวันที่หิมะตกด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 21, 'ท่านได้ฆ่าคนอียิปต์คนหนึ่งเป็นชายรูปร่างงาม คนอียิปต์นั้นถือหอกอยู่ แต่เบไนยาห์ถือไม้เท้าลงไปหาเขาและแย่งเอาหอกมาจากมือของคนอียิปต์คนนั้น และฆ่าเขาตายด้วยหอกของเขาเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 22, 'เบไนยาห์บุตรชายเยโฮยาดาได้กระทํากิจเหล่านี้และได้ชื่อเสียงดังวีรบุรุษสามคนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 23, 'ท่านมีชื่อเสียงโด่งดังกว่าสามสิบคนนั้น แต่ท่านไม่มียศเท่ากับสามคนแรกนั้น และดาวิดก็ทรงแต่งท่านให้เป็นผู้บังคับบัญชาทหารรักษาพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 24, 'อาสาเฮลน้องชายของโยอาบเป็นคนหนึ่งในสามสิบคนนั้น เอลฮานันบุตรชายของโดโดชาวเบธเลเฮม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 25, 'ชัมมาห์ชาวเมืองฮาโรด เอลีคาชาวเมืองฮาโรด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 26, 'เฮเลสคนปัลที อิราบุตรชายอิกเขชชาวเมืองเทโคอา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 27, 'อาบีเยเซอร์ชาวเมืองอานาโธท เมบุนนัยคนหุชาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 28, 'ศัลโมนชาวอาโหอาห์ มาหะรัยชาวเนโทฟาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 29, 'เฮเลบบุตรชายบาอานาห์ชาวเนโทฟาห์ อิททัยบุตรชายรีบัยชาวกิเบอาห์แห่งคนเบนยามิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 30, 'เบไนยาห์ชาวปิราโธน ฮิดดัยชาวลําธารกาอัช');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 31, 'อาบีอัลโบนคนอารบาห์ อัสมาเวทชาวบาฮูริม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 32, 'เอลียาบาชาวชาอัลโบน โยนาธานซึ่งเป็นคนหนึ่งในบรรดาบุตรชายของยาเชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 33, 'ชัมมาห์ชาวฮาราร์ อาหิยัมบุตรชายของชาราร์คนฮาราร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 34, 'เอลีเฟเลทบุตรชายอาหัสบัยบุตรชายของชาวมาอาคาห์ เอลีอัมบุตรชายอาหิโธเฟลชาวกิโลห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 35, 'เฮสโรชาวคารเมล ปารัยชาวอาราบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 36, 'อิกาลบุตรชายนาธันชาวโศบาห์ บานีคนกาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 37, 'เศเลกคนอัมโมน นาหะรัยชาวเบเอโรท คนถือเครื่องอาวุธของโยอาบบุตรชายนางเศรุยาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 38, 'อิราคนอิทไรต์ กาเรบคนอิทไรต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 39, 'อุรีอาห์คนฮิตไทต์ รวมสามสิบเจ็ดคนด้วยกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 1, 'พระพิโรธของพระเยโฮวาห์ได้เกิดขึ้นต่ออิสราเอลอีก เพื่อทรงต่อสู้เขาทั้งหลายจึงทรงดลใจดาวิดตรัสว่า “จงไปนับคนอิสราเอลและคนยูดาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 2, 'กษัตริย์จึงรับสั่งโยอาบ แม่ทัพซึ่งอยู่กับพระองค์ว่า “จงไปทั่วอิสราเอลทุกตระกูลตั้งแต่เมืองดานถึงเบเออร์เชบา และท่านจงนับจํานวนประชาชน เพื่อเราจะได้ทราบจํานวนรวมของประชาชน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 3, 'แต่โยอาบกราบทูลกษัตริย์ว่า “ขอพระเยโฮวาห์พระเจ้าของพระองค์ทรงให้มีประชาชนเพิ่มขึ้นอีกร้อยเท่าของที่มีอยู่ ขอกษัตริย์เจ้านายของข้าพระองค์ทรงทอดพระเนตรเห็น แต่ไฉนกษัตริย์เจ้านายของข้าพระองค์จึงพอพระทัยในเรื่องนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 4, 'แต่โยอาบและผู้บังคับบัญชากองทัพก็ต้องยอมจํานนต่อพระดํารัสของกษัตริย์ โยอาบกับบรรดาผู้บังคับบัญชาของกองทัพจึงออกไปจากพระพักตร์กษัตริย์ เพื่อจะนับประชาชนอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 5, 'เขาทั้งหลายข้ามแม่น้ําจอร์แดนไปและตั้งค่ายในเมืองอาโรเออร์ ด้านขวาของเมืองที่ตั้งอยู่กลางแม่น้ํากาดไปทางยาเซอร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 6, 'แล้วเขาทั้งหลายก็มายังกิเลอาดและมาถึงแผ่นดินตะทิมโหดฉิ และเขาทั้งหลายมาถึงเมืองดานยาอันอ้อมไปยังเมืองไซดอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 7, 'และมาถึงป้อมปราการเมืองไทระ และทั่วทุกหัวเมืองของคนฮีไวต์และของคนคานาอัน และเขาออกไปยังภาคใต้ของยูดาห์ที่เมืองเบเออร์เชบา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 8, 'เมื่อเขาไปทั่วแผ่นดินนั้นแล้ว เขาจึงมายังกรุงเยรูซาเล็ม เมื่อสิ้นเก้าเดือนกับยี่สิบวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 9, 'และโยอาบก็ถวายจํานวนประชาชนที่นับได้แด่กษัตริย์ ในอิสราเอลมีทหารแข็งกล้าแปดแสนคนผู้ซึ่งชักดาบ และคนยูดาห์มีห้าแสนคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 10, 'เมื่อได้นับจํานวนคนเสร็จแล้วพระทัยของดาวิดก็โทมนัส และดาวิดกราบทูลต่อพระเยโฮวาห์ว่า “ข้าพระองค์ได้กระทําบาปใหญ่ยิ่งในสิ่งซึ่งข้าพระองค์ได้กระทํานี้ โอ ข้าแต่พระเยโฮวาห์ แต่บัดนี้ขอพระองค์ทรงให้อภัยความชั่วช้าของผู้รับใช้ของพระองค์ เพราะข้าพระองค์กระทําการอย่างโง่เขลามาก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 11, 'และเมื่อดาวิดทรงลุกขึ้นในตอนเช้า พระวจนะของพระเยโฮวาห์ก็มายังกาดผู้พยากรณ์ผู้ทํานายของดาวิดว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 12, '“จงไปบอกดาวิดว่า พระเยโฮวาห์ตรัสดังนี้ว่า ‘เราเสนอเจ้าสามประการ จงเลือกเอาประการหนึ่งเพื่อเราจะได้กระทําให้แก่เจ้า’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 13, 'กาดจึงเข้าเฝ้าดาวิดและกราบทูลพระองค์ว่า “จะให้เกิดกันดารอาหารในแผ่นดินของพระองค์สิ้นเจ็ดปีหรือ หรือพระองค์จะยอมหนีศัตรูสิ้นเวลาสามเดือนด้วยเขาไล่ติดตาม หรือจะให้โรคระบาดเกิดขึ้นในแผ่นดินของพระองค์สิ้นสามวัน บัดนี้ขอพระองค์ทรงตรึกตรอง และตัดสินในพระทัยว่า จะให้คําตอบประการใด เพื่อข้าพระองค์จะนํากลับไปกราบทูลพระองค์ผู้ทรงใช้ข้าพระองค์มา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 14, 'ดาวิดจึงตรัสกับกาดว่า “เรามีความกระวนกระวายมาก ขอให้เราทั้งหลายตกเข้าไปอยู่ในพระหัตถ์ของพระเยโฮวาห์ เพราะพระกรุณาคุณของพระองค์ใหญ่ยิ่งนัก แต่ขออย่าให้เราตกเข้าไปในมือของมนุษย์เลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 15, 'ดังนั้นพระเยโฮวาห์จึงทรงให้โรคระบาดเกิดขึ้นในอิสราเอลตั้งแต่เวลาเช้าจนสิ้นเวลากําหนด และประชาชนที่ตายตั้งแต่เมืองดานถึงเบเออร์เชบามีเจ็ดหมื่นคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 16, 'และเมื่อทูตสวรรค์ยื่นมือออกเหนือกรุงเยรูซาเล็มจะทําลายเมืองนั้น พระเยโฮวาห์ทรงกลับพระทัยในเหตุร้ายนั้น ตรัสสั่งทูตสวรรค์ผู้กําลังทําลายประชาชนว่า “พอแล้ว ยับยั้งมือของเจ้าได้” ส่วนทูตสวรรค์ของพระเยโฮวาห์ก็อยู่ที่ลานนวดข้าวของอาราวนาห์คนเยบุส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 17, 'เมื่อดาวิดทอดพระเนตรทูตสวรรค์ผู้กําลังสังหารประชาชนนั้นพระองค์กราบทูลพระเยโฮวาห์ว่า “ดูเถิด ข้าพระองค์ได้กระทําบาปชั่วร้ายแล้ว แต่บรรดาแกะเหล่านี้ เขาได้กระทําอะไร ขอพระหัตถ์ของพระองค์อยู่เหนือข้าพระองค์และวงศ์วานบิดาของข้าพระองค์เถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 18, 'ในวันนั้นกาดก็เข้ามาเฝ้าดาวิด กราบทูลพระองค์ว่า “ขอเสด็จขึ้นไปสร้างแท่นบูชาถวายแด่พระเยโฮวาห์บนลานนวดข้าวของอาราวนาห์คนเยบุส”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 19, 'ดาวิดก็เสด็จขึ้นไปตามคําของกาดตามที่พระเยโฮวาห์ทรงบัญชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 20, 'เมื่ออาราวนาห์มองลงมา เห็นกษัตริย์และข้าราชการขึ้นมาหาตน อาราวนาห์ก็ออกไปถวายบังคมกษัตริย์ซบหน้าลงถึงดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 21, 'และอาราวนาห์กราบทูลว่า “ไฉนกษัตริย์เจ้านายของข้าพระองค์จึงเสด็จมาหาผู้รับใช้ของพระองค์” ดาวิดตรัสว่า “มาซื้อลานนวดข้าวจากท่าน เพื่อจะสร้างแท่นบูชาถวายแด่พระเยโฮวาห์ เพื่อโรคร้ายจะได้ระงับเสียจากประชาชน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 22, 'อาราวนาห์จึงกราบทูลดาวิดว่า “ขอกษัตริย์เจ้านายของข้าพระองค์จงรับสิ่งที่พระองค์ทรงเห็นชอบขึ้นถวาย ดูเถิด ที่นี่มีวัวสําหรับทําเครื่องเผาบูชา และเลื่อนนวดข้าวกับแอกสําหรับวัวเป็นฟืน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 23, 'ของทั้งสิ้นนี้อาราวนาห์ดุจดังกษัตริย์ขอถวายแด่กษัตริย์ และอาราวนาห์กราบทูลกษัตริย์ว่า “ขอพระเยโฮวาห์พระเจ้าของพระองค์จงโปรดปรานพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 24, 'แต่กษัตริย์ตรัสกับอาราวนาห์ว่า “หามิได้ แต่เราจะขอจ่ายเงินซื้อจากท่าน เราจะถวายเครื่องเผาบูชาแด่พระเยโฮวาห์พระเจ้าของเราโดยที่เราไม่เสียค่าอะไรเลยนั้นไม่ได้” ดาวิดจึงทรงซื้อลานนวดข้าวกับวัวเป็นเงินห้าสิบเชเขล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 25, 'ดาวิดก็ทรงสร้างแท่นบูชาถวายแด่พระเยโฮวาห์ที่นั่น และถวายเครื่องเผาบูชากับเครื่องสันติบูชา พระเยโฮวาห์ทรงสดับฟังคําอธิษฐานเพื่อแผ่นดินนั้น และโรคร้ายก็ระงับเสียจากอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 1, 'กษัตริย์ดาวิดมีพระชนมายุและทรงพระชรามากแล้ว แม้เขาจะห่มผ้าให้พระองค์มากก็ยังไม่อบอุ่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 2, 'เพราะฉะนั้นบรรดาข้าราชการของพระองค์จึงกราบทูลว่า “ขอเสาะหาหญิงสาวพรหมจารีมาถวายกษัตริย์เจ้านายของข้าพระองค์ และขอให้เธออยู่งานเฉพาะพระพักตร์พระองค์ และดูแลพระองค์ ให้เธอนอนในพระทรวงของพระองค์ เพื่อกษัตริย์เจ้านายของข้าพระองค์จะได้ทรงอบอุ่น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 3, 'เขาจึงได้แสวงหานางสาวที่สวยงามตลอดดินแดนอิสราเอล ได้พบนางสาวอาบีชากหญิงชาวชูเนม จึงได้นําเธอมาเฝ้ากษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 4, 'หญิงสาวคนนั้นงามยิ่งนัก เธอได้ดูแลกษัตริย์และอยู่ปรนนิบัติพระองค์ แต่กษัตริย์หาทรงร่วมกับเธอไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 5, 'ฝ่ายอาโดนียาห์ โอรสของพระนางฮักกีทได้ยกตัวเองขึ้นกล่าวว่า “เราเองจะเป็นกษัตริย์” และท่านได้เตรียมรถรบและพลม้า กับพลวิ่งนําหน้าห้าสิบคนไว้เพื่อตนเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 6, 'พระราชบิดาของท่านก็ไม่เคยขัดใจท่านด้วยถามว่า “ทําไมเจ้ากระทําเช่นนี้เช่นนั้น” ท่านเป็นชายงามด้วย ท่านเกิดมาถัดอับซาโลม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 7, 'ท่านได้ปรึกษากับโยอาบบุตรชายนางเศรุยาห์และกับอาบียาธาร์ปุโรหิต เขาทั้งสองก็ติดตามและช่วยเหลืออาโดนียาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 8, 'แต่ศาโดกปุโรหิต และเบไนยาห์บุตรชายเยโฮยาดา และนาธันผู้พยากรณ์กับชิเมอีและเรอี และพวกทแกล้วทหารของดาวิดมิได้อยู่ฝ่ายอาโดนียาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 9, 'อาโดนียาห์ได้ถวายแกะ วัว และสัตว์อ้วนพีเป็นเครื่องบูชา ณ ศิลาแห่งโศเฮเลทซึ่งอยู่ข้างๆเอนโรเกล และท่านได้เชิญพี่น้องทั้งสิ้นของท่าน คือราชโอรสของกษัตริย์ และประชาชนทั้งสิ้นแห่งยูดาห์ที่เป็นข้าราชการของกษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 10, 'แต่ท่านมิได้เชิญนาธันผู้พยากรณ์ หรือเบไนยาห์ หรือพวกทแกล้วทหาร หรือซาโลมอนอนุชาของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 11, 'แล้วนาธันก็ทูลพระนางบัทเชบาพระราชมารดาของซาโลมอนว่า “พระองค์ไม่ทรงได้ยินหรือว่า อาโดนียาห์ โอรสของพระนางฮักกีทได้ทรงราชย์แล้ว และดาวิดเจ้านายของข้าพระองค์ก็มิได้ทรงทราบเรื่อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 12, 'เพราะฉะนั้นบัดนี้ขอข้าพระองค์ถวายคําปรึกษา เพื่อพระองค์จะได้ทรงช่วยชีวิตของพระองค์ และชีวิตของซาโลมอนโอรสของพระองค์ไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 13, 'ขอเสด็จเข้าเฝ้ากษัตริย์ดาวิด และกราบทูลพระองค์ว่า ‘โอ กษัตริย์เจ้านายของหม่อมฉัน พระองค์ได้ทรงปฏิญาณกับสาวใช้ของพระองค์ไว้มิใช่หรือว่า “ซาโลมอนบุตรของเจ้าจะครองสมบัติต่อจากเราแน่นอน และจะนั่งบนบัลลังก์ของเรา” มิใช่หรือ ไฉนอาโดนียาห์จึงทรงครองเล่าเพคะ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 14, 'ดูเถิด ขณะที่พระองค์กราบทูลกษัตริย์อยู่ ข้าพระองค์จะตามเข้าไปเฝ้า และสนับสนุนคําตรัสของพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 15, 'แล้วพระนางบัทเชบาก็เข้าไปเฝ้ากษัตริย์ที่ห้องบรรทม กษัตริย์ทรงพระชรามาก และอาบีชากชาวชูเนมก็กําลังอยู่ปรนนิบัติกษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 16, 'เมื่อพระนางบัทเชบากราบถวายบังคมกษัตริย์แล้ว กษัตริย์ก็ตรัสถามว่า “เจ้าประสงค์สิ่งใด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 17, 'พระนางทูลพระองค์ว่า “ข้าแต่เจ้านายของข้าพระองค์ พระองค์ได้ทรงปฏิญาณในพระนามของพระเยโฮวาห์พระเจ้าของพระองค์ต่อสาวใช้ของพระองค์ว่า ‘ซาโลมอนบุตรของเจ้าจะครองสมบัติต่อจากเราแน่นอน และเขาจะนั่งบนบัลลังก์ของเรา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 18, 'ดูเถิด บัดนี้อาโดนียาห์ทรงราชย์แล้ว แม้ว่าพระองค์คือกษัตริย์เจ้านายของหม่อมฉันก็หาทรงทราบไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 19, 'ท่านได้ถวายวัว สัตว์อ้วนพีและแกะเป็นอันมาก และได้เชิญบรรดาโอรสของกษัตริย์ กับอาบียาธาร์ปุโรหิต กับโยอาบผู้บัญชาการกองทัพ แต่ซาโลมอนผู้รับใช้ของพระองค์ ท่านหาได้เชิญไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 20, 'โอ ข้าแต่กษัตริย์เจ้านายของหม่อมฉัน อิสราเอลทั้งสิ้นก็เพ่งดูพระองค์ เพื่อพระองค์จะตรัสแก่เขาว่า จะทรงให้ผู้ใดนั่งบนบัลลังก์ของกษัตริย์เจ้านายของหม่อมฉันแทนพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 21, 'มิฉะนั้นจะเป็นดังนี้ คือเมื่อกษัตริย์เจ้านายของหม่อมฉันล่วงลับไปอยู่กับบรรพบุรุษของพระองค์แล้ว หม่อมฉันและซาโลมอนบุตรของหม่อมฉันก็จะตกเป็นฝ่ายผิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 22, 'ดูเถิด ขณะเมื่อพระนางกําลังกราบทูลกษัตริย์อยู่ นาธันผู้พยากรณ์ก็เข้ามา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 23, 'เขาทั้งหลายจึงกราบทูลกษัตริย์ว่า “ดูเถิด นาธันผู้พยากรณ์” เมื่อนาธันเข้ามาต่อพระพักตร์กษัตริย์ เขาก็ซบหน้าลงถึงพื้นถวายคํานับกษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 24, 'และนาธันกราบทูลว่า “โอ ข้าแต่กษัตริย์เจ้านายของข้าพระองค์ พระองค์รับสั่งไว้หรือว่า ‘อาโดนียาห์จะครองต่อจากเรา และจะนั่งบนบัลลังก์ของเรา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 25, 'เพราะวันนี้ท่านได้ลงไปถวายวัว สัตว์อ้วนพีและแกะเป็นอันมาก และได้เชื้อเชิญบรรดาโอรสของกษัตริย์ ทั้งผู้บัญชาการกองทัพ และอาบียาธาร์ปุโรหิต และดูเถิด เขาทั้งหลายกําลังกินดื่มต่อหน้าท่านและกล่าวว่า ‘ขอกษัตริย์อาโดนียาห์ทรงพระเจริญ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 26, 'แต่ส่วนข้าพระองค์ผู้รับใช้ของพระองค์ และศาโดกปุโรหิต กับเบไนยาห์บุตรชายเยโฮยาดา และซาโลมอนผู้รับใช้ของพระองค์ท่านหาได้เชิญไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 27, 'เหตุการณ์ทั้งนี้บังเกิดขึ้นโดยกษัตริย์เจ้านายของข้าพระองค์หรือ และพระองค์มิได้ตรัสบอกแก่ผู้รับใช้ของพระองค์ว่า จะทรงให้ผู้ใดนั่งบนบัลลังก์ของกษัตริย์เจ้านายของข้าพระองค์ต่อจากพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 28, 'แล้วกษัตริย์ดาวิดตรัสตอบว่า “จงเรียกบัทเชบาให้มาหาเรา” พระนางก็เสด็จเข้ามาเฝ้าต่อพระพักตร์กษัตริย์ และประทับยืนอยู่ต่อพระพักตร์กษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 29, 'แล้วกษัตริย์ทรงปฏิญาณว่า “พระเยโฮวาห์ทรงพระชนม์อยู่แน่ฉันใด คือพระองค์ผู้ทรงไถ่ชีวิตของเราจากบรรดาความทุกข์ยาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 30, 'เราได้ปฏิญาณต่อเจ้าในพระนามพระเยโฮวาห์พระเจ้าแห่งอิสราเอลว่า ‘ซาโลมอนบุตรของเจ้าจะครองสมบัติต่อจากเราแน่นอน และเขาจะนั่งบนบัลลังก์ของเราแทนเรา’ เราก็จะกระทําอย่างนั้นวันนี้แหละ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 31, 'แล้วพระนางบัทเชบาก็ซบพระพักตร์ลงถึงดินถวายบังคมกษัตริย์ และกราบทูลว่า “ขอกษัตริย์ดาวิดเจ้านายของหม่อมฉันจงทรงพระเจริญเป็นนิตย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 32, 'กษัตริย์ดาวิดรับสั่งว่า “จงเรียกศาโดกปุโรหิต และนาธันผู้พยากรณ์ กับเบไนยาห์บุตรชายเยโฮยาดามาหาเรา” เขาทั้งหลายจึงเข้ามาเฝ้ากษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 33, 'และกษัตริย์ตรัสสั่งเขาทั้งหลายว่า “จงพาข้าราชการของเจ้านายของเจ้าไปจัดให้ซาโลมอนโอรสของเราขึ้นขี่ล่อของเรา และนําเขาลงไปที่กีโฮน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 34, 'และให้ศาโดกปุโรหิต และนาธันผู้พยากรณ์เจิมตั้งเขาไว้เป็นกษัตริย์เหนืออิสราเอลที่นั่น แล้วท่านทั้งหลายจงเป่าแตร และประกาศว่า ‘ขอกษัตริย์ซาโลมอนทรงพระเจริญ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 35, 'แล้วท่านทั้งหลายจงติดตามเขาขึ้นมา และเขาจะมานั่งบนบัลลังก์ของเรา เพราะว่าเขาจะได้เป็นกษัตริย์แทนเรา เราได้กําหนดตั้งเขาไว้ให้เป็นผู้ครอบครองเหนืออิสราเอลและเหนือยูดาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 36, 'และเบไนยาห์บุตรชายเยโฮยาดาได้กราบทูลตอบกษัตริย์ว่า “เอเมน ขอพระเยโฮวาห์พระเจ้าแห่งกษัตริย์เจ้านายของข้าพระองค์ตรัสดังนั้นเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 37, 'พระเยโฮวาห์ได้ทรงสถิตกับกษัตริย์เจ้านายของข้าพระองค์มาแล้วฉันใด ก็ขอทรงสถิตกับซาโลมอนฉันนั้น และขอทรงกระทําให้พระที่นั่งของพระองค์ใหญ่ยิ่งกว่าพระที่นั่งของกษัตริย์ดาวิดเจ้านายของข้าพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 38, 'ดังนั้นศาโดกปุโรหิต นาธันผู้พยากรณ์ และเบไนยาห์บุตรชายเยโฮยาดา และคนเคเรธีกับคนเปเลทได้ลงไปจัดให้ซาโลมอนประทับบนล่อพระที่นั่งของกษัตริย์ดาวิดและได้นําท่านมาถึงกีโฮน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 39, 'แล้วศาโดกปุโรหิตได้นําเขาสัตว์ที่บรรจุน้ํามันมาจากพลับพลา และเจิมตั้งซาโลมอนไว้ และเขาทั้งหลายก็เป่าแตร และประชาชนทั้งปวงกล่าวว่า “ขอกษัตริย์ซาโลมอนทรงพระเจริญ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 40, 'และประชาชนทั้งปวงก็ตามเสด็จไปเป่าปี่และเปรมปรีดิ์ด้วยความชื่นบานยิ่งนัก แผ่นดินก็แยกด้วยเสียงของเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 41, 'อาโดนียาห์และบรรดาแขกที่อยู่กับท่านเมื่อรับประทานเสร็จแล้วก็ได้ยินเสียงนั้น และเมื่อโยอาบได้ยินเสียงแตรก็พูดว่า “เสียงอึกทึกครึกโครมนี้ที่ในกรุงหมายความว่ากระไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 42, 'ขณะที่เขากําลังพูดอยู่ ดูเถิด โยนาธานบุตรชายอาบียาธาร์ปุโรหิตก็มาถึง และอาโดนียาห์ก็กล่าวว่า “เข้ามาเถิด เพราะเจ้าเป็นคนมีกําลังมากจึงนําข่าวดีมา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 43, 'โยนาธานกราบเรียนอาโดนียาห์ว่า “หามิได้ เพราะกษัตริย์ดาวิดเจ้านายของเราทั้งปวงได้ทรงกระทําให้ซาโลมอนเป็นกษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 44, 'และกษัตริย์ได้รับสั่งให้ศาโดกปุโรหิต นาธันผู้พยากรณ์ และเบไนยาห์บุตรชายเยโฮยาดา กับคนเคเรธีและคนเปเลทตามซาโลมอนไป และเขาทั้งหลายก็ได้จัดให้ซาโลมอนประทับบนล่อพระที่นั่งของกษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 45, 'และศาโดกปุโรหิต กับนาธันผู้พยากรณ์ได้เจิมตั้งท่านไว้ให้เป็นกษัตริย์ ณ กีโฮน และเขาทั้งหลายก็ขึ้นมาจากที่นั่นด้วยความเปรมปรีดิ์ เพราะฉะนั้นในกรุงจึงอึกทึกครึกโครม นี่เป็นเสียงที่ท่านทั้งหลายได้ยิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 46, 'ซาโลมอนได้ทรงประทับบนพระราชบัลลังก์ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 47, 'ยิ่งกว่านั้นอีกบรรดาข้าราชการของกษัตริย์ก็เข้าไปถวายพระพรแด่กษัตริย์ดาวิดเจ้านายของเราว่า ‘ขอพระเจ้าทรงกระทําให้พระนามของซาโลมอนบันลือไปยิ่งกว่าพระนามของพระองค์ และขอทรงกระทําให้บัลลังก์ของซาโลมอนใหญ่ยิ่งกว่าบัลลังก์ของพระองค์’ แล้วกษัตริย์ก็ทรงโน้มพระกายลงบนแท่นที่บรรทม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 48, 'และกษัตริย์ก็ตรัสด้วยว่า ‘สาธุการแด่พระเยโฮวาห์พระเจ้าของอิสราเอล ผู้ได้ทรงประทานให้มีคนหนึ่งนั่งบนบัลลังก์ของเราในวันนี้ ด้วยตาของเราเองได้เห็นแล้ว’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 49, 'แล้วบรรดาแขกทั้งปวงของอาโดนียาห์ก็กลัว และลุกขึ้น ต่างคนต่างไปตามทางของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 50, 'ฝ่ายอาโดนียาห์ก็กลัวซาโลมอน จึงลุกขึ้นไปจับเชิงงอนของแท่นบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 51, 'มีคนไปกราบทูลซาโลมอนว่า “ดูเถิด อาโดนียาห์กลัวกษัตริย์ซาโลมอน เพราะดูเถิด ท่านจับเชิงงอนที่แท่นบูชาอยู่กล่าวว่า ‘ขอกษัตริย์ซาโลมอนได้ปฏิญาณแก่ข้าพเจ้าในวันนี้ว่า พระองค์จะไม่ประหารผู้รับใช้ของพระองค์เสียด้วยดาบ’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 52, 'และซาโลมอนตรัสว่า “ถ้าแม้เขาสําแดงตัวได้ว่าเป็นคนที่สมควร ผมสักเส้นเดียวของเขาจะไม่ตกลงยังพื้นดิน แต่ถ้าพบความชั่วอยู่ในตัวเขา เขาจะต้องถึงแก่ความตาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 53, 'กษัตริย์ซาโลมอนตรัสสั่งให้คนไปนําท่านลงมาจากแท่นบูชา และท่านก็มากราบลงต่อกษัตริย์ซาโลมอน และซาโลมอนตรัสแก่ท่านว่า “จงกลับไปวังของท่านเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 1, 'เมื่อเวลาที่ดาวิดจะสิ้นพระชนม์ใกล้เข้ามา พระองค์ทรงกําชับซาโลมอนราชโอรสของพระองค์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 2, '“เรากําลังจะเป็นไปตามทางของโลกแล้ว จงเข้มแข็งและสําแดงตัวของเจ้าให้เป็นลูกผู้ชาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 3, 'และจงรักษาพระบัญชากําชับของพระเยโฮวาห์พระเจ้าของเจ้า คือดําเนินในบรรดาพระมรรคาของพระองค์ และรักษากฎเกณฑ์ของพระองค์ พระบัญญัติของพระองค์ คําตัดสินของพระองค์ และพระโอวาทของพระองค์ ดังที่ได้จารึกไว้ในพระราชบัญญัติของโมเสส เพื่อเจ้าจะได้จําเริญในบรรดาการซึ่งเจ้าได้กระทํา และในที่ใดๆที่เจ้าไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 4, 'เพื่อพระเยโฮวาห์จะได้รักษาพระวจนะของพระองค์ ซึ่งพระองค์ตรัสเกี่ยวกับเราว่า ‘ถ้าลูกหลานทั้งหลายของเจ้าระมัดระวังในวิถีทางทั้งหลายของเขา ที่จะดําเนินต่อหน้าเราด้วยความจริงอย่างสุดจิตสุดใจของเขา (พระองค์ตรัสว่า) ราชวงศ์จะไม่ขาดชายที่จะนั่งบนบัลลังก์ของอิสราเอล’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 5, 'ยิ่งกว่านั้นอีก เจ้าก็รู้อยู่แล้วว่า โยอาบบุตรนางเศรุยาห์ได้กระทําอะไรแก่เรา คือว่าเขาได้กระทําประการใดแก่ผู้บัญชาการทั้งสองแห่งกองทัพของอิสราเอล คือกระทําแก่อับเนอร์บุตรเนอร์ และแก่อามาสาบุตรเยเธอร์ที่โยอาบได้ฆ่าเสีย ทําให้โลหิตที่ตกในยามสงครามไหลในยามสันติ และวางโลหิตที่ตกในยามสงครามลงบนรัดประคดที่เอวของเขา และลงบนรองเท้าของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 6, 'เพราะฉะนั้นเจ้าจงกระทําให้เหมาะสมตามปัญญาของเจ้า อย่าปล่อยให้ศีรษะหงอกของเขาลงไปสู่แดนคนตายอย่างสันติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 7, 'แต่จงปฏิบัติด้วยความเมตตาต่อบุตรชายทั้งหลายของบารซิลลัยคนกิเลอาด จงยอมให้เขาอยู่ในหมู่คนที่รับประทานอยู่ที่โต๊ะของเจ้า เพราะว่าเมื่อเราหนีจากอับซาโลมพี่ชายของเจ้านั้น เขาทั้งหลายได้มาพบกับเราด้วยความเมตตาดังนั้นแหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 8, 'และดูเถิด มีชิเมอีบุตรเก-ราคนเบนยามินจากบ้านบาฮูริมอยู่กับเจ้าด้วย เขาเป็นผู้ด่าเราอย่างน่าสลดใจในวันที่เราเดินไปยังมาหะนาอิม แต่เขามาต้อนรับเราที่แม่น้ําจอร์แดน และเราจึงได้ปฏิญาณต่อเขาในพระนามพระเยโฮวาห์ว่า ‘เราจะไม่ประหารชีวิตเจ้าด้วยดาบ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 9, 'เพราะฉะนั้นบัดนี้เจ้าอย่าถือว่าเขาไม่มีความผิด เพราะเจ้าเป็นคนมีปัญญา เจ้าจะทราบว่าควรจะกระทําประการใดแก่เขา และเจ้าจงนําศีรษะหงอกของเขาลงไปสู่แดนคนตายพร้อมกับโลหิต”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 10, 'แล้วดาวิดก็บรรทมหลับไปอยู่กับบรรพบุรุษของพระองค์ และเขาก็ฝังพระศพไว้ในนครดาวิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 11, 'และเวลาที่ดาวิดทรงครอบครองอยู่เหนืออิสราเอลนั้นเป็นสี่สิบปี พระองค์ทรงครอบครองในเฮโบรนเจ็ดปี และพระองค์ทรงครอบครองในกรุงเยรูซาเล็มสามสิบสามปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 12, 'ดังนั้นแหละซาโลมอนจึงประทับบนพระที่นั่งของดาวิดราชบิดาของพระองค์ และราชอาณาจักรของพระองค์ก็ดํารงมั่นคงอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 13, 'แล้วอาโดนียาห์โอรสของพระนางฮักกีทได้เข้าเฝ้าพระนางบัทเชบาพระราชมารดาของซาโลมอน พระนางตรัสว่า “เจ้ามาอย่างสันติหรือ” ท่านทูลว่า “อย่างสันติขอรับ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 14, 'แล้วท่านทูลว่า “ข้าพระบาทมีเรื่องที่จะทูลพระองค์” พระนางตรัสว่า “จงพูดไปเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 15, 'ท่านจึงทูลว่า “พระองค์ทรงทราบแล้วว่าราชอาณาจักรนั้นเป็นของข้าพระบาท และว่าบรรดาชนอิสราเอลทั้งสิ้นก็หมายใจว่า ข้าพระบาทจะได้ครอบครอง อย่างไรก็ดี ราชอาณาจักรก็กลับกลายมาเป็นของพระอนุชาของข้าพระบาท ด้วยราชอาณาจักรเป็นของพระองค์จากพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 16, 'บัดนี้ข้าพระบาททูลขอแต่ประการเดียว ขอพระองค์อย่าได้ปฏิเสธเลย” พระนางตรัสต่อท่านว่า “จงพูดไปเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 17, 'และท่านทูลว่า “ขอพระองค์ทูลกษัตริย์ซาโลมอน (ท่านคงไม่ปฏิเสธพระองค์) คือทูลขออาบีชากชาวชูเนมให้เป็นชายาของข้าพระบาท”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 18, 'พระนางบัทเชบาตรัสว่า “ดีแล้ว เราจะทูลกษัตริย์แทนเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 19, 'พระนางบัทเชบาจึงเข้าเฝ้ากษัตริย์ซาโลมอน เพื่อทูลพระองค์ให้อาโดนียาห์ และกษัตริย์ทรงลุกขึ้นต้อนรับพระนาง และทรงคํานับพระนาง แล้วก็เสด็จประทับบนพระที่นั่งของพระองค์ รับสั่งให้นําพระแท่นมาถวายพระราชมารดา พระนางก็เสด็จประทับที่เบื้องขวาของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 20, 'แล้วพระนางตรัสว่า “แม่จะขอจากลูกสักประการหนึ่ง ขออย่าปฏิเสธแม่เลย” และกษัตริย์ตรัสกับพระนางว่า “ขอมาเถิด ลูกจะไม่ปฏิเสธเสด็จแม่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 21, 'พระนางตรัสว่า “ขอยกอาบีชากชาวชูเนมให้กับอาโดนียาห์เชษฐาของลูกให้เป็นชายาเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 22, 'กษัตริย์ซาโลมอนตรัสตอบพระราชมารดาของพระองค์ว่า “ไฉนเสด็จแม่จึงขออาบีชากชาวชูเนมให้แก่อาโดนียาห์เล่า น่าจะขอราชอาณาจักรให้เขาเสียด้วย เพราะเขาเป็นพระเชษฐาของลูก และฝ่ายเขามีอาบียาธาร์ปุโรหิตและโยอาบบุตรนางเศรุยาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 23, 'แล้วกษัตริย์ซาโลมอนทรงสาบานในพระนามของพระเยโฮวาห์ว่า “ถ้าถ้อยคํานี้ไม่เป็นเหตุให้อาโดนียาห์เสียชีวิตของเขาแล้ว ก็ขอพระเจ้าทรงลงโทษผมและให้หนักยิ่งกว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 24, 'เพราะฉะนั้นบัดนี้พระเยโฮวาห์ทรงพระชนม์อยู่แน่ฉันใด พระองค์ผู้ทรงสถาปนาผมไว้ และตั้งผมไว้บนบัลลังก์ของดาวิดราชบิดาของผม และทรงตั้งไว้เป็นราชวงศ์ ดังที่พระองค์ทรงสัญญาไว้ อาโดนียาห์จะต้องตายในวันนี้ฉันนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 25, 'ดังนั้นกษัตริย์ซาโลมอนจึงรับสั่งใช้เบไนยาห์บุตรชายเยโฮยาดา เขาก็ไปประหารชีวิตอาโดนียาห์เสีย และท่านก็ตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 26, 'ส่วนอาบียาธาร์ปุโรหิตนั้น กษัตริย์รับสั่งว่า “จงไปอยู่ที่อานาโธท ไปสู่ไร่นาของเจ้า เพราะเจ้าสมควรที่จะตาย แต่ในเวลานี้เราจะไม่ประหารชีวิตเจ้า เพราะว่าเจ้าหามหีบขององค์พระผู้เป็นเจ้าพระเจ้าไปข้างหน้าดาวิดราชบิดาของเรา และเพราะเจ้าได้เข้าส่วนในบรรดาความทุกข์ใจของราชบิดาเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 27, 'ซาโลมอนจึงทรงขับไล่อาบียาธาร์เสียจากหน้าที่ปุโรหิตของพระเยโฮวาห์ กระทําให้สําเร็จตามพระวจนะของพระเยโฮวาห์ซึ่งพระองค์ตรัสเกี่ยวกับวงศ์วานของเอลีที่เมืองชีโลห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 28, 'เมื่อข่าวนี้ทราบไปถึงโยอาบ เพราะแม้ว่าโยอาบมิได้สนับสนุนอับซาโลม ท่านได้สนับสนุนอาโดนียาห์ โยอาบก็หนีไปที่พลับพลาของพระเยโฮวาห์และจับเชิงงอนแท่นบูชาไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 29, 'เมื่อมีคนไปกราบทูลกษัตริย์ซาโลมอนว่า “โยอาบได้หนีไปที่พลับพลาของพระเยโฮวาห์ และดูเถิด เขาอยู่ข้างแท่นบูชานั้น” ซาโลมอนรับสั่งเบไนยาห์บุตรชายเยโฮยาดาตรัสว่า “จงไปประหารชีวิตเขาเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 30, 'เบไนยาห์ก็มายังพลับพลาของพระเยโฮวาห์พูดกับท่านว่า “กษัตริย์มีรับสั่งว่า จงออกมาเถิด” ท่านตอบว่า “ไม่ออกไป ข้าจะตายที่นี่” แล้วเบไนยาห์ก็นําความไปกราบทูลกษัตริย์อีกว่า “โยอาบพูดอย่างนี้ และเขาตอบข้าพระองค์อย่างนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 31, 'กษัตริย์ตรัสตอบเขาว่า “จงกระทําตามที่เขาบอก จงประหารเขาเสียและฝังเขาไว้ ทั้งนี้จะได้เอาโลหิตไร้ความผิดซึ่งโยอาบได้กระทําให้ไหลนั้นไปเสียจากเรา และจากวงศ์วานบิดาของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 32, 'พระเยโฮวาห์ทรงทําให้โลหิตของเขากลับมาตกบนศีรษะของเขาเอง เพราะว่าเขาได้โจมตีและฆ่าชายสองคนที่ชอบธรรมและดีกว่าตัวเขาด้วยดาบ โดยที่ดาวิดราชบิดาของเราหาทรงทราบไม่ คืออับเนอร์บุตรเนอร์ผู้บัญชาการกองทัพของอิสราเอล และอามาสาบุตรเยเธอร์ผู้บัญชาการกองทัพของยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 33, 'ดังนั้นต้องให้โลหิตของเขาทั้งสองตกบนศีรษะของโยอาบและบนศีรษะเชื้อสายของเขาเป็นนิตย์ แต่ส่วนดาวิดและเชื้อสายของพระองค์ และราชวงศ์ของพระองค์ และราชบัลลังก์ของพระองค์จะมีสันติภาพจากพระเยโฮวาห์อยู่เป็นนิตย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 34, 'แล้วเบไนยาห์บุตรชายเยโฮยาดาก็ขึ้นไปประหารชีวิตเขาเสีย และฝังเขาไว้ในบ้านของเขาเองซึ่งอยู่ในถิ่นทุรกันดาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 35, 'กษัตริย์ได้ทรงแต่งตั้งเบไนยาห์บุตรชายเยโฮยาดาเหนือกองทัพแทนโยอาบ และกษัตริย์ก็ทรงแต่งตั้งศาโดกผู้เป็นปุโรหิตไว้ในตําแหน่งของอาบียาธาร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 36, 'แล้วกษัตริย์ทรงใช้คนไปเรียกชิเมอีให้เข้ามาเฝ้า และตรัสกับเขาว่า “ท่านจงสร้างบ้านอยู่ในกรุงเยรูซาเล็มและอาศัยอยู่ที่นั่น อย่าออกจากที่นั่นไปที่ไหนเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 37, 'เพราะในวันที่ท่านออกไป และข้ามลําธารขิดโรนนั้น ท่านจงรู้เป็นแน่เถิดว่า ท่านจะต้องตายแน่ แล้วโลหิตของท่านจะต้องตกบนศีรษะของท่านเอง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 38, 'และชิเมอีทูลกษัตริย์ว่า “ที่พระองค์ตรัสนั้นก็ดีแล้ว ผู้รับใช้ของพระองค์จะกระทําตามที่กษัตริย์เจ้านายของข้าพระองค์ตรัสนั้น” ชิเมอีจึงได้อาศัยอยู่ในกรุงเยรูซาเล็มเป็นเวลานาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 39, 'ต่อมาเมื่อล่วงไปสามปีแล้วทาสสองคนของชิเมอีได้หลบหนีไปยังอาคีชโอรสของมาอาคาห์กษัตริย์เมืองกัท และเมื่อเขามาบอกชิเมอีว่า “ดูเถิด ทาสของท่านอยู่ในเมืองกัท”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 40, 'ชิเมอีก็ลุกขึ้นผูกอานขี่ลาไปเฝ้าอาคีชที่เมืองกัทเพื่อเสาะหาทาสของตน ชิเมอีได้ไปนําทาสของตนมาจากเมืองกัท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 41, 'และเมื่อมีผู้กราบทูลซาโลมอนว่าชิเมอีได้ไปจากกรุงเยรูซาเล็มถึงเมืองกัท และกลับมาแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 42, 'กษัตริย์ก็ทรงใช้ให้เรียกชิเมอีมาเฝ้าและตรัสกับเขาว่า “เราได้ให้ท่านปฏิญาณในพระนามของพระเยโฮวาห์มิใช่หรือ และได้ตักเตือนท่านแล้วว่า ‘ท่านจงรู้เป็นแน่ว่า ในวันที่ท่านออกไป ไม่ว่าไปที่ใดๆ ท่านจะต้องตายแน่’ และท่านก็ได้ตอบเราว่า ‘คําตรัสที่ข้าพระองค์ได้ยินนั้นก็ดีแล้ว’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 43, 'ทําไมท่านจึงไม่รักษาคําปฏิญาณไว้ต่อพระเยโฮวาห์ และรักษาคําบัญชาซึ่งเราได้กําชับท่านนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 44, 'กษัตริย์ตรัสกับชิเมอีว่า “ท่านเองรู้เรื่องเหตุร้ายทั้งสิ้นซึ่งอยู่ในใจของท่าน ซึ่งท่านได้กระทําต่อดาวิดราชบิดาของเรา เพราะฉะนั้นพระเยโฮวาห์จะทรงนําเหตุร้ายมาสนองเหนือศีรษะของท่านเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 45, 'แต่กษัตริย์ซาโลมอนจะได้รับพระพร และพระที่นั่งของดาวิดจะตั้งมั่นคงต่อพระพักตร์พระเยโฮวาห์อยู่เป็นนิตย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 46, 'แล้วกษัตริย์ทรงบัญชาเบไนยาห์บุตรชายเยโฮยาดาและเขาก็ออกไปประหารชีวิตชิเมอีเสีย ดังนั้นราชอาณาจักรก็ตั้งมั่นคงอยู่ในพระหัตถ์ของซาโลมอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 1, 'ซาโลมอนได้ทรงกระทําให้เป็นทองแผ่นเดียวกันกับฟาโรห์กษัตริย์แห่งอียิปต์ โดยได้ทรงรับราชธิดาของฟาโรห์ และทรงนําพระนางมาไว้ในนครของดาวิด จนพระองค์ทรงสร้างพระราชวังของพระองค์ และทรงสร้างพระนิเวศของพระเยโฮวาห์ และกําแพงรอบกรุงเยรูซาเล็มสําเร็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 2, 'อย่างไรก็ตาม ประชาชนได้ถวายสัตวบูชา ณ ปูชนียสถานสูง เพราะในเวลานั้นยังไม่ได้สร้างพระนิเวศเพื่อพระนามของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 3, 'ซาโลมอนทรงรักพระเยโฮวาห์ ทรงดําเนินตามกฎเกณฑ์ของดาวิดราชบิดาของพระองค์ เว้นแต่พระองค์ทรงถวายสัตวบูชาและเผาเครื่องหอม ณ ปูชนียสถานสูง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 4, 'และกษัตริย์เสด็จไปที่เมืองกิเบโอนเพื่อถวายเครื่องสัตวบูชาที่นั่น เพราะที่นั่นเป็นมหาปูชนียสถานสูง ซาโลมอนทรงถวายเครื่องเผาบูชาพันตัวบนแท่นบูชานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 5, 'พระเยโฮวาห์ทรงปรากฏแก่ซาโลมอนที่เมืองกิเบโอนเป็นพระสุบินในกลางคืน และพระเจ้าตรัสว่า “เจ้าอยากให้เราให้อะไรเจ้าก็จงขอเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 6, 'และซาโลมอนตรัสว่า “พระองค์ได้ทรงสําแดงความเมตตายิ่งใหญ่แก่ดาวิดพระราชบิดาผู้รับใช้ของพระองค์ เพราะว่าเสด็จพ่อดําเนินต่อพระพักตร์พระองค์ด้วยความจริงและความชอบธรรม ด้วยจิตใจเที่ยงตรงต่อพระองค์ และพระองค์ทรงรักษาความเมตตายิ่งใหญ่นี้ไว้เพื่อเสด็จพ่อ และได้ทรงประทานบุตรชายคนหนึ่งแก่เสด็จพ่อให้นั่งบนราชบัลลังก์ของท่านในวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 7, 'โอ ข้าแต่พระเยโฮวาห์พระเจ้าของข้าพระองค์ ถึงแม้ว่าข้าพระองค์เป็นแต่เด็ก บัดนี้พระองค์ทรงกระทําให้ผู้รับใช้ของพระองค์เป็นกษัตริย์แทนดาวิดเสด็จพ่อของข้าพระองค์ ข้าพระองค์ไม่ทราบว่าจะเข้านอกออกในอย่างไรถูก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 8, 'และผู้รับใช้ของพระองค์ก็อยู่ท่ามกลางประชาชนของพระองค์ ผู้ซึ่งพระองค์ทรงเลือกไว้ เป็นชนชาติใหญ่ ซึ่งจะนับหรือคํานวณประชาชนก็ไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 9, 'เพราะฉะนั้นขอพระองค์ทรงประทานความคิดความเข้าใจแก่ผู้รับใช้ของพระองค์เพื่อจะวินิจฉัยประชาชนของพระองค์ เพื่อข้าพระองค์จะประจักษ์ในความผิดแผกระหว่างดีและชั่ว เพราะว่าผู้ใดเล่าจะสามารถวินิจฉัยประชาชนใหญ่ของพระองค์นี้ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 10, 'ที่ซาโลมอนทูลขอเช่นนี้ก็เป็นที่พอพระทัยองค์พระผู้เป็นเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 11, 'พระเจ้าจึงตรัสกับซาโลมอนว่า “เพราะเจ้าได้ขอสิ่งนี้และมิได้ขอชีวิตยืนยาว หรือความมั่งคั่งหรือชีวิตของบรรดาศัตรูของเจ้าเพื่อตัวเจ้าเอง แต่เจ้าขอความเข้าใจเพื่อตัวเจ้าเองเพื่อให้ประจักษ์ในการวินิจฉัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 12, 'ดูเถิด เราจะกระทําตามคําของเจ้า ดูเถิด เราให้จิตใจอันประกอบด้วยปัญญาและความเข้าใจ เพื่อว่าจะไม่มีใครที่เป็นอยู่ก่อนเจ้าเหมือนเจ้า และจะไม่มีใครที่ขึ้นมาภายหลังเจ้าเหมือนเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 13, 'เราจะให้สิ่งที่เจ้าไม่ได้ขอแก่เจ้าด้วย ทั้งความมั่งคั่งและเกียรติยศ เพื่อว่าตลอดวันเวลาทั้งสิ้นของเจ้า จะไม่มีกษัตริย์องค์อื่นเปรียบเทียบกับเจ้าได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 14, 'และถ้าเจ้าจะดําเนินตามทางของเรา รักษากฎเกณฑ์ของเรา และบัญญัติของเราดังดาวิดบิดาของเจ้าได้ดําเนินนั้น เราก็จะให้วันเวลาของเจ้ายืนยาว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 15, 'และซาโลมอนก็ตื่นบรรทม และดูเถิด เป็นพระสุบิน แล้วพระองค์ก็เสด็จมาที่กรุงเยรูซาเล็ม และประทับยืนอยู่หน้าหีบพันธสัญญาของพระเยโฮวาห์ และถวายเครื่องเผาบูชาและเครื่องสันติบูชา และพระราชทานเลี้ยงแก่บรรดาข้าราชการของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 16, 'แล้วหญิงแพศยาสองคนมาเฝ้ากษัตริย์ และยืนอยู่ต่อพระพักตร์พระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 17, 'หญิงคนหนึ่งทูลว่า “โอ ข้าแต่เจ้านายของข้าพระองค์ ข้าพระองค์และผู้หญิงคนนี้อาศัยอยู่ในเรือนเดียวกัน และข้าพระองค์ก็คลอดบุตรคนหนึ่งขณะที่นางนั้นอยู่ในเรือน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 18, 'ต่อมาเมื่อข้าพระองค์คลอดบุตรได้สามวันแล้ว นางคนนี้ก็คลอดบุตรด้วย และข้าพระองค์ทั้งสองอยู่ด้วยกัน ไม่มีผู้ใดอยู่กับข้าพระองค์ทั้งสองในเรือนนั้น ข้าพระองค์ทั้งสองนั้นอยู่ในเรือนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 19, 'แล้วบุตรของหญิงคนนี้ก็ตายเสียในกลางคืน ด้วยเขานอนทับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 20, 'พอเที่ยงคืนนางก็ลุกขึ้น และเอาบุตรชายของข้าพระองค์ไปเสียจากข้างข้าพระองค์ ขณะที่สาวใช้ของพระองค์หลับอยู่ และวางเขาไว้ในอกของเธอ และเธอเอาบุตรของเธอที่ตายแล้วนั้นไว้ในอกของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 21, 'เมื่อข้าพระองค์ตื่นขึ้นในตอนเช้าเพื่อให้บุตรของข้าพระองค์กินนม ดูเถิด เขาตายเสียแล้ว แต่เมื่อข้าพระองค์พินิจดูในตอนเช้า ดูเถิด เด็กนั้นไม่ใช่บุตรชายที่ข้าพระองค์คลอดมา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 22, 'แต่หญิงอีกคนหนึ่งพูดว่า “ไม่ใช่ เด็กที่เป็น เป็นบุตรชายของฉัน เด็กที่ตายเป็นบุตรชายของเจ้า” หญิงคนที่หนึ่งพูดว่า “ไม่ใช่ เด็กที่ตายเป็นบุตรชายของเจ้า และเด็กที่เป็น เป็นบุตรชายของฉัน” เขาทั้งสองพูดกันดังนี้ต่อพระพักตร์กษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 23, 'แล้วกษัตริย์ตรัสว่า “คนหนึ่งพูดว่า ‘คนนี้เป็นบุตรชายของฉัน คือเด็กที่เป็นอยู่ และบุตรชายของเจ้าตายเสียแล้ว’ และอีกคนหนึ่งพูดว่า ‘ไม่ใช่ แต่บุตรชายของเจ้าตายเสียแล้ว และบุตรชายของฉันเป็นคนที่มีชีวิต’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 24, 'และกษัตริย์ตรัสว่า “เอาดาบมาให้เราเล่มหนึ่ง” เขาจึงเอาพระแสงดาบมาไว้ต่อพระพักตร์กษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 25, 'และกษัตริย์ตรัสว่า “จงแบ่งเด็กที่มีชีวิตนั้นออกเป็นสองท่อน และให้คนหนึ่งครึ่งหนึ่ง และอีกคนหนึ่งครึ่งหนึ่ง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 26, 'แล้วหญิงคนที่บุตรของตนยังมีชีวิตอยู่นั้นทูลกษัตริย์ เพราะว่าจิตใจของเธออาลัยในบุตรชายของเธอ เธอว่า “โอ ข้าแต่เจ้านายของข้าพระองค์ ขอทรงมอบเด็กที่มีชีวิตนั้นให้เขาไป และถึงอย่างไรก็ดีอย่าทรงฆ่าเสีย” แต่หญิงอีกคนหนึ่งว่า “อย่าให้ฉันเป็นเจ้าของหรือของฉัน ขอทรงแบ่งเถิดเพคะ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 27, 'แล้วกษัตริย์ตรัสตอบเขาว่า “จงให้เด็กที่มีชีวิตนั้นแก่คนนั้น อย่าฆ่าเสียเลย นางเป็นมารดาของเด็กนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 28, 'อิสราเอลทั้งปวงได้ยินเรื่องการพิพากษา ซึ่งกษัตริย์ประทานการพิพากษานั้น และเขาทั้งหลายก็เกรงกลัวกษัตริย์ เพราะเขาทั้งหลายประจักษ์ว่า พระสติปัญญาของพระเจ้าอยู่ในพระองค์ที่จะทรงวินิจฉัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 1, 'กษัตริย์ซาโลมอนเป็นกษัตริย์เหนืออิสราเอลทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 2, 'และคนต่อไปนี้เป็นข้าราชการผู้ใหญ่ของพระองค์คือ อาซาริยาห์บุตรชายศาโดกเป็นปุโรหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 3, 'เอลีโฮเรฟและอาหิยาห์บุตรชายชิชา เป็นราชเลขา เยโฮชาฟัทบุตรชายอาหิลูดเป็นเจ้ากรมสารบรรณ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 4, 'เบไนยาห์บุตรชายเยโฮยาดา เป็นผู้บัญชาการกองทัพ ศาโดกและอาบียาธาร์เป็นปุโรหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 5, 'อาซาริยาห์บุตรชายนาธันเป็นหัวหน้าข้าหลวง ศบุดบุตรชายนาธันเป็นข้าราชการผู้ใหญ่ และเป็นพระสหายของกษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 6, 'อาหิชาร์เป็นเจ้ากรมวัง และอาโดนีรัมบุตรชายอับดาเป็นผู้ควบคุมคนที่ทํางานโยธา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 7, 'ซาโลมอนทรงมีข้าหลวงสิบสองคนอยู่เหนืออิสราเอลทั้งปวง เป็นผู้จัดหาเสบียงอาหารสําหรับกษัตริย์และสําหรับกษัตริย์สํานัก ข้าหลวงคนหนึ่งจัดหาเสบียงอาหารสําหรับเดือนหนึ่งในหนึ่งปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 8, 'ต่อไปนี้เป็นชื่อของเขาคือ เบนเฮอร์ ประจําแดนเทือกเขาเอฟราอิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 9, 'เบนเดเคอร์ ประจําในมาคาสและในชาอัลบิม เบธเชเมช และเอโลนเบธฮานัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 10, 'เบนเฮเสด ประจําในอารุบโบท โสโคห์และแผ่นดินเฮเฟอร์ทั้งสิ้นขึ้นอยู่กับเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 11, 'เบนอาบีนาดับ ประจําในบริเวณโดร์ทั้งหมด เขามีทาฟัทธิดาของซาโลมอนเป็นชายา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 12, 'บาอานาบุตรชายอาหิลูด ประจําในทาอานาค เมกิดโดและเบธชานทั้งหมดซึ่งอยู่ข้างศาเรธานเชิงเมืองยิสเรเอล และตั้งแต่เบธชานถึงอาเบลเมโฮลาห์ไปจนถึงฝากข้างโน้นของโยกเนอัม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 13, 'เบนเกเบอร์ ประจําในราโมทกิเลอาด เขามีเมืองทั้งหลายของยาอีร์บุตรชายมนัสเสห์ซึ่งอยู่ในกิเลอาด และเขามีท้องถิ่นอารโกบ ซึ่งอยู่ในบาชาน หัวเมืองใหญ่หกสิบหัวเมือง ซึ่งมีกําแพงเมือง และดานทองเหลืองขึ้นอยู่แก่เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 14, 'อาหินาดับบุตรชายอิดโด ประจําในมาหะนาอิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 15, 'อาหิมาอัส ประจําในนัฟทาลี เขาก็เหมือนกันได้บาเสมัทธิดาของซาโลมอนเป็นชายา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 16, 'บาอานาห์บุตรชายหุชัย ประจําในอาเชอร์และเบอาโลท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 17, 'เยโฮชาฟัทบุตรชายปารูอาห์ ประจําในอิสสาคาร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 18, 'ชิเมอีบุตรชายเอลาห์ ประจําในเบนยามิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 19, 'เกเบอร์บุตรชายอุรี ประจําในแผ่นดินกิเลอาด ในแผ่นดินของสิโหนกษัตริย์ของคนอาโมไรต์และของโอกกษัตริย์แห่งเมืองบาชาน ท่านเป็นข้าหลวงคนเดียวที่ประจําในแผ่นดินนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 20, 'คนยูดาห์และคนอิสราเอลนั้นมีจํานวนมากมายดังเม็ดทรายชายทะเล เขาทั้งหลายกินและดื่มและมีจิตใจเบิกบาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 21, 'และซาโลมอนทรงปกครองเหนือราชอาณาจักรทั้งสิ้น ตั้งแต่แม่น้ําไปจนถึงแผ่นดินฟีลิสเตียและถึงพรมแดนอียิปต์ เขาทั้งหลายถวายส่วยอากร และปรนนิบัติซาโลมอนตลอดวันเวลาแห่งพระชนม์ชีพของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 22, 'เสบียงอาหารสําหรับซาโลมอนในวันหนึ่งนั้น คือยอดแป้งสามสิบโคระและแป้งหกสิบโคระ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 23, 'วัวอ้วนสิบตัว วัวจากทุ่งหญ้ายี่สิบตัว แกะหนึ่งร้อยตัว นอกจากนี้มีกวางตัวผู้ เนื้อสมัน อีเก้งและไก่อ้วน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 24, 'เพราะพระองค์ทรงครอบครองเหนือท้องถิ่นทั้งสิ้นฟากแม่น้ําข้างนี้ ตั้งแต่ทิฟสาห์ถึงอาซาห์ และทรงครอบครองเหนือบรรดากษัตริย์ที่อยู่ฟากแม่น้ําข้างนี้ และพระองค์ทรงมีสันติภาพอยู่ทุกด้านรอบพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 25, 'ยูดาห์และอิสราเอลก็อยู่อย่างปลอดภัย ทุกคนก็นั่งอยู่ใต้เถาองุ่นและใต้ต้นมะเดื่อของตน ตั้งแต่เมืองดานกระทั่งถึงเมืองเบเออร์เชบา ตลอดวันเวลาของซาโลมอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 26, 'ซาโลมอนยังมีคอกขังม้าเดี่ยวอีกสี่หมื่นสําหรับรถรบของพระองค์ และพลม้าหนึ่งหมื่นสองพันคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 27, 'และบรรดาข้าหลวงเหล่านั้นก็จัดเสบียงอาหารส่งกษัตริย์ซาโลมอน และเพื่อทุกคนที่มายังโต๊ะเสวยของกษัตริย์ซาโลมอน ต่างก็ส่งของตามเดือนของตน เขาทั้งหลายไม่ให้สิ่งหนึ่งสิ่งใดขาดไปเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 28, 'ทั้งข้าวบาร์เลย์และฟางข้าวสําหรับม้าและม้าอาชาไนย เขานํามายังสถานที่ของข้าหลวงเหล่านั้นตามที่ได้มีรับสั่งแก่ทุกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 29, 'และพระเจ้าทรงประทานสติปัญญาและความเข้าใจแก่ซาโลมอนอย่างเหลือประมาณ ทั้งพระทัยอันกว้างขวางดุจเม็ดทรายที่ชายทะเล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 30, 'และสติปัญญาของซาโลมอนล้ํากว่าสติปัญญาทั้งสิ้นของชาวตะวันออกและกว่าบรรดาสติปัญญาของอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 31, 'เพราะพระองค์ทรงมีสติปัญญาฉลาดกว่าคนอื่นทุกคน ทรงฉลาดกว่าเอธานคนเอสราห์ และเฮมาน คาลโคล์และดารดา บรรดาบุตรชายของมาโฮล และพระนามของพระองค์ก็เลื่องลือไปในทุกประชาชาติที่อยู่ล้อมรอบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 32, 'พระองค์ตรัสสุภาษิตสามพันข้อด้วย และบทเพลงของพระองค์มีหนึ่งพันห้าบท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 33, 'พระองค์ตรัสถึงต้นไม้ตั้งแต่ต้นสนสีดาร์ซึ่งอยู่ในเลบานอน จนถึงต้นหุสบซึ่งงอกออกมาจากกําแพง พระองค์ตรัสถึงสัตว์ป่าด้วย ทั้งบรรดานก สัตว์เลื้อยคลานและปลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 34, 'และคนมาจากชนชาติทั้งหลายเพื่อฟังสติปัญญาของซาโลมอน และมาจากบรรดากษัตริย์แห่งแผ่นดินโลก ผู้ได้ยินถึงสติปัญญาของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 1, 'ฝ่ายฮีรามกษัตริย์เมืองไทระได้ส่งข้าราชการของท่านมาเฝ้าซาโลมอน เมื่อท่านได้ยินว่าเขาได้เจิมตั้งพระองค์ไว้เป็นกษัตริย์แทนราชบิดาของพระองค์ เพราะฮีรามรักดาวิดอยู่เสมอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 2, 'และซาโลมอนได้ส่งพระดํารัสไปยังฮีรามว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 3, '“ท่านคงทราบอยู่แล้วว่าดาวิดราชบิดาของข้าพเจ้าสร้างพระนิเวศสําหรับพระนามของพระเยโฮวาห์พระเจ้าของพระองค์ไม่ได้ เพราะการสงครามซึ่งอยู่ล้อมรอบพระองค์ทุกด้าน จนกว่าพระเยโฮวาห์จะทรงปราบเขาเสียให้อยู่ใต้พระบาทของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 4, 'แต่บัดนี้พระเยโฮวาห์พระเจ้าของข้าพเจ้าทรงประทานให้ข้าพเจ้าได้หยุดพักรอบด้าน ปฏิปักษ์หรือเหตุร้ายก็ไม่มี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 5, 'ดูเถิด ข้าพเจ้าจึงประสงค์จะสร้างพระนิเวศสําหรับพระนามของพระเยโฮวาห์พระเจ้าของข้าพเจ้า ดังที่พระเยโฮวาห์ได้ตรัสไว้กับดาวิดราชบิดาของข้าพเจ้าว่า ‘บุตรชายของเจ้า ผู้ซึ่งเราจะตั้งไว้บนบัลลังก์แทนเจ้า จะสร้างพระนิเวศสําหรับนามของเรา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 6, 'เพราะฉะนั้นบัดนี้ขอท่านสั่งให้ตัดไม้สนสีดาร์แห่งเลบานอนเพื่อข้าพเจ้า และข้าราชการของข้าพเจ้าจะสมทบกับพวกข้าราชการของท่าน ข้าพเจ้าจะมอบเงินค่าจ้างข้าราชการของท่านแก่ท่านตามที่ท่านตั้งไว้ เพราะท่านคงทราบแล้วว่า ท่ามกลางเรานี้ไม่มีผู้ใดรู้จักตัดไม้เหมือนชาวไซดอน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 7, 'และอยู่มาเมื่อฮีรามได้ยินถ้อยคําของซาโลมอน ท่านก็ชื่นชมยินดียิ่งนักและว่า “สาธุการแด่พระเยโฮวาห์ในวันนี้ ผู้ทรงประทานบุตรชายที่ฉลาดองค์หนึ่งแก่ดาวิด ให้อยู่เหนือชนชาติใหญ่นี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 8, 'และฮีรามก็ใช้คนให้มายังซาโลมอนทูลว่า “ข้าพเจ้าได้พิจารณาสิ่งต่างๆซึ่งท่านส่งไปยังข้าพเจ้าแล้ว ข้าพเจ้าพร้อมที่จะกระทําสิ่งสารพัดตามที่ท่านปรารถนาในเรื่องไม้สนสีดาร์ และไม้สนสามใบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 9, 'ข้าราชการของข้าพเจ้าจะนําลงมาจากเลบานอนถึงทะเล และข้าพเจ้าจะผูกแพล่องมาตามทะเลถึงที่ที่ท่านจะกําหนดให้ และข้าพเจ้าจะให้แก้แพที่นั่น ขอท่านมารับเอา และขอท่านส่งเสบียงอาหารแก่สํานักวังของข้าพเจ้าก็แล้วกัน เป็นที่พอใจข้าพเจ้าแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 10, 'ฮีรามจึงได้จัดส่งไม้สนสีดาร์และไม้สนสามใบให้แก่ซาโลมอนตามที่พระองค์มีพระประสงค์ทุกประการ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 11, 'ฝ่ายซาโลมอนทรงประทานข้าวสาลีให้เป็นอาหารแก่สํานักวังของฮีรามสองหมื่นโคระและน้ํามันบริสุทธิ์ยี่สิบโคระ ซาโลมอนทรงประทานแก่ฮีรามเป็นปีๆไปอย่างนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 12, 'และพระเยโฮวาห์พระราชทานสติปัญญาแก่ซาโลมอน ดังที่พระองค์ทรงสัญญาไว้ และมีสันติภาพระหว่างฮีรามและซาโลมอน และทั้งสองก็ทรงกระทําสนธิสัญญากัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 13, 'กษัตริย์ซาโลมอนทรงเกณฑ์แรงงานจากชนอิสราเอลทั้งปวง คนที่ถูกเกณฑ์แรงนับได้สามหมื่นคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 14, 'และพระองค์ทรงใช้เขาไปยังเลบานอน เวรละหนึ่งหมื่นคนต่อเดือน เขาจะอยู่ที่เลบานอนเดือนหนึ่ง และอยู่บ้านสองเดือน และอาโดนีรัมเป็นผู้บังคับบัญชาพวกถูกเกณฑ์แรง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 15, 'ซาโลมอนมีคนขนของหนักเจ็ดหมื่นคน และคนสกัดหินในถิ่นเทือกเขาแปดหมื่นคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 16, 'นอกจากข้าราชการผู้ใหญ่ของซาโลมอนซึ่งเป็นผู้ดูแลการงานนี้ ก็มีอีกสามพันสามร้อยคนซึ่งเป็นผู้ปกครองดูแลประชาชนผู้ดําเนินงาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 17, 'กษัตริย์ทรงบัญชาและเขาทั้งหลายสกัดก้อนหินใหญ่มีค่าออกมา เพื่อวางรากฐานของพระนิเวศด้วยหินที่แต่งแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 18, 'ดังนั้นพนักงานก่อสร้างของซาโลมอน และพนักงานก่อสร้างของฮีราม และช่างสลักหินก็แต่งหินเหล่านั้น และเตรียมไม้และหินเพื่อสร้างพระนิเวศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 1, 'อยู่มาในปีที่สี่ร้อยแปดสิบหลังจากที่ชนอิสราเอลออกมาจากแผ่นดินอียิปต์ ในปีที่สี่แห่งการที่ซาโลมอนครอบครองอิสราเอล ในเดือนศิฟ ซึ่งเป็นเดือนที่สอง พระองค์ทรงเริ่มสร้างพระนิเวศของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 2, 'พระนิเวศซึ่งกษัตริย์ซาโลมอนทรงสร้างสําหรับพระเยโฮวาห์นั้น ยาวหกสิบศอก กว้างยี่สิบศอกและสูงสามสิบศอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 3, 'มุขหน้าห้องโถงของพระนิเวศนั้นยาวยี่สิบศอก เท่ากับด้านกว้างของพระนิเวศ และลึกเข้าไปหน้าพระนิเวศสิบศอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 4, 'และพระองค์ทรงสร้างหน้าต่างสําหรับพระนิเวศมีขอบสอบออกข้างนอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 5, 'พระองค์ทรงสร้างห้องติดผนังพระนิเวศอยู่รอบผนังของพระนิเวศ ทั้งที่ห้องโถงและที่ห้องหลัง และพระองค์ทรงสร้างห้องระเบียงโดยรอบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 6, 'ห้องชั้นล่างที่สุดกว้างห้าศอก ชั้นกลางกว้างหกศอก และชั้นที่สามกว้างเจ็ดศอก เพราะรอบด้านนอกของพระนิเวศพระองค์ทรงสร้างหยักบ่าไว้ที่ผนัง เพื่อว่าไม้รอดจะไม่ได้ทะลวงเข้าไปในผนังพระนิเวศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 7, 'เมื่อกําลังสร้าง พระนิเวศนั้นก็สร้างด้วยศิลา ซึ่งเตรียมมาจากบ่อศิลา เพราะฉะนั้นจึงไม่ได้ยินเสียงค้อนหรือขวานหรือเครื่องมือเหล็กใดๆในพระนิเวศ ขณะเมื่อทําการก่อสร้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 8, 'ทางเข้าห้องชั้นล่างอยู่ทางด้านขวาของตัวพระนิเวศ และคนขึ้นไปยังห้องชั้นกลางทางบันไดเวียน และขึ้นจากห้องชั้นกลางไปห้องชั้นที่สาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 9, 'พระองค์ทรงสร้างพระนิเวศดังนี้และทรงให้สําเร็จ และพระองค์ทรงสร้างเพดานของพระนิเวศ มีไม้คร่าวและกระดานเป็นไม้สนสีดาร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 10, 'พระองค์ทรงสร้างห้องรอบพระนิเวศสูงห้าศอก และติดกับตัวพระนิเวศด้วยกระดานไม้สนสีดาร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 11, 'และพระวจนะของพระเยโฮวาห์มาถึงซาโลมอนว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 12, '“เกี่ยวด้วยพระนิเวศนี้ซึ่งเจ้าสร้างอยู่ ถ้าเจ้าดําเนินตามกฎเกณฑ์ของเรา และประพฤติตามคําตัดสินของเรา และรักษาบัญญัติของเราทั้งสิ้นและดําเนินตาม เราก็จะกระทําถ้อยคําของเรากับเจ้าซึ่งเราพูดกับดาวิดบิดาของเจ้านั้นให้สําเร็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 13, 'และเราจะอยู่ในหมู่ชนอิสราเอล และจะไม่ทอดทิ้งอิสราเอลชนชาติของเราเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 14, 'ซาโลมอนได้ทรงสร้างพระนิเวศและทรงให้สําเร็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 15, 'พระองค์ทรงกรุผนังข้างในพระนิเวศด้วยกระดานไม้สนสีดาร์ ตั้งแต่พื้นพระนิเวศจนถึงไม้เพดาน พระองค์ทรงกรุข้างในด้วยไม้ และพระองค์ทรงปูปิดพื้นพระนิเวศด้วยไม้สนสามใบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 16, 'พระองค์ทรงสร้างอีกข้างหนึ่งของพระนิเวศยี่สิบศอกด้วยกระดานไม้สนสีดาร์จากพื้นถึงไม้เพดาน และพระองค์ทรงสร้างห้องนี้ภายใน ให้เป็นห้องหลัง คือที่บริสุทธิ์ที่สุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 17, 'ตัวพระนิเวศคือห้องโถงซึ่งอยู่ส่วนหน้านั้นยาวสี่สิบศอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 18, 'มีไม้สนสีดาร์ที่อยู่ข้างในพระนิเวศแกะเป็นรูปดอกตูมและดอกไม้บาน เป็นไม้สนสีดาร์ทั้งสิ้น ในที่นั่นแลไม่เห็นหินเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 19, 'พระองค์ทรงจัดเตรียมห้องหลังไว้ข้างในพระนิเวศ เพื่อจะวางหีบพันธสัญญาของพระเยโฮวาห์ไว้ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 20, 'ส่วนข้างในห้องหลังนั้นยาวยี่สิบศอก กว้างยี่สิบศอก และสูงยี่สิบศอก และพระองค์ทรงบุด้วยทองคําบริสุทธิ์ พระองค์ทรงกรุแท่นบูชาด้วยไม้สนสีดาร์ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 21, 'และซาโลมอนทรงบุข้างในพระนิเวศด้วยทองคําบริสุทธิ์ และพระองค์ทรงลากโซ่ทองคําข้ามข้างหน้าห้องหลัง และบุด้วยทองคํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 22, 'และพระองค์ทรงบุพระนิเวศทั้งหลังด้วยทองคํา จนพระนิเวศนั้นสําเร็จทั้งสิ้น แท่นบูชาทั้งแท่นที่เป็นของห้องหลัง พระองค์ก็ทรงบุด้วยทองคํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 23, 'ในห้องหลังพระองค์ทรงสร้างเครูบสองรูปด้วยไม้มะกอกเทศ สูงรูปละสิบศอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 24, 'ปีกข้างหนึ่งของเครูบยาวห้าศอก ปีกอีกข้างหนึ่งของเครูบยาวห้าศอก จากปลายปีกข้างหนึ่งไปถึงปลายปีกอีกข้างหนึ่งยาวสิบศอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 25, 'เครูบอีกรูปหนึ่งก็วัดได้สิบศอกด้วย เครูบทั้งสองมีขนาดเท่ากัน และรูปอย่างเดียวกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 26, 'ความสูงของเครูบรูปหนึ่งเป็นสิบศอก และเครูบอีกรูปหนึ่งก็เหมือนกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 27, 'พระองค์ทรงวางเครูบไว้ในส่วนชั้นในที่สุดของพระนิเวศ ปีกของเครูบนั้นกางออกเพื่อให้ปีกหนึ่งจดผนังข้างหนึ่ง และปีกของเครูบอีกรูปหนึ่งจดผนังอีกข้างหนึ่ง ส่วนปีกข้างอื่นก็มาจดกันตรงกลางพระนิเวศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 28, 'และพระองค์ทรงบุเครูบด้วยทองคํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 29, 'พระองค์ทรงสลักผนังของพระนิเวศนั้นโดยรอบ ด้วยรูปแกะสลักเป็นรูปเครูบ และต้นอินทผลัมและดอกไม้บานทั้งข้างในและข้างนอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 30, 'พื้นของพระนิเวศนั้น พระองค์ทรงบุด้วยทองคําทั้งข้างในและข้างนอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 31, 'สําหรับทางเข้าสู่ห้องหลัง พระองค์ทรงสร้างประตูด้วยไม้มะกอกเทศ กรอบประตูชิ้นบนและวงกบประตูรวมเข้าเป็นหนึ่งในห้าของขนาดของผนัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 32, 'พระองค์ทรงสร้างบานประตูทั้งสองด้วยไม้มะกอกเทศ แกะรูปเครูบ ต้นอินทผลัม และดอกไม้บาน ทรงบุด้วยทองคํา พระองค์ทรงแผ่ทองคําหุ้มเครูบและห้อมต้นอินทผลัม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 33, 'พระองค์ทรงสร้างวงกบประตูทางเข้าห้องโถงด้วยไม้มะกอกเทศ เป็นหนึ่งในสี่ของขนาดของผนัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 34, 'และประตูสองบานด้วยไม้สนสามใบ บานสองบานของบานประตูหนึ่งหมุนได้ และบานอีกสองบานของบานประตูหนึ่งก็หมุนได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 35, 'พระองค์ทรงแกะเครูบ ต้นอินทผลัมและดอกไม้บานบนบานประตูนั้น และพระองค์ทรงบุด้วยทองคําสม่ําเสมอกันบนงานแกะสลักนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 36, 'พระองค์ทรงสร้างลานภายในด้วยกําแพงหินสกัดสามชั้น และด้วยไม้สนสีดาร์ชั้นหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 37, 'ในปีที่สี่ก็ได้วางรากพระนิเวศของพระเยโฮวาห์ ในเดือนศิฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 38, 'และในปีที่สิบเอ็ดในเดือนบูล ซึ่งเป็นเดือนที่แปด พระนิเวศนั้นก็สําเร็จหมดทุกๆส่วน และสําเร็จตามรายการทั้งสิ้น พระองค์ทรงสร้างพระนิเวศนั้นเจ็ดปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 1, 'ซาโลมอนทรงสร้างพระราชวังของพระองค์สิบสามปี และพระองค์ทรงให้พระราชวังของพระองค์สําเร็จทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 2, 'พระองค์ทรงสร้างพระตําหนักพนาเลบานอน ยาวหนึ่งร้อยศอก กว้างห้าสิบศอกและสูงสามสิบศอก อยู่บนเสาไม้สนสีดาร์สี่แถว มีคานไม้สนสีดาร์อยู่บนเสา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 3, 'ชั้นบนมุงด้วยไม้สนสีดาร์บนห้อง ซึ่งอยู่บนเสาสี่สิบห้าห้อง แถวละสิบห้าห้อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 4, 'มีกรอบหน้าต่างสามแถบ หน้าต่างอยู่ตรงข้ามหน้าต่างทั้งสามแถว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 5, 'ประตูและหน้าต่างทั้งหมดมีกรอบสี่เหลี่ยม และหน้าต่างก็อยู่ตรงข้ามหน้าต่างทั้งสามแถว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 6, 'และพระองค์ทรงสร้างท้องพระโรงเสา ยาวห้าสิบศอกและกว้างสามสิบศอก มีมุขด้านหน้า และมีเสากับหลังคาข้างหน้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 7, 'และพระองค์ทรงสร้างท้องพระโรงพระที่นั่ง เป็นที่ซึ่งพระองค์ทรงให้คําพิพากษา คือท้องพระโรงวินิจฉัย ก็ทําทั้งห้องสําเร็จด้วยไม้สนสีดาร์ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 8, 'พระราชวังของพระองค์ซึ่งพระองค์จะทรงประทับอยู่นั้นมีลานอีกแห่งหนึ่งซึ่งอยู่ภายในท้องพระโรง ก็กระทําด้วยฝีมือช่างอย่างเดียวกัน ซาโลมอนได้ทรงสร้างวังเหมือนท้องพระโรงนี้สําหรับราชธิดาของฟาโรห์ ซึ่งพระองค์ทรงได้มาเป็นมเหสี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 9, 'ทั้งสิ้นเหล่านี้สร้างด้วยหินอันมีค่า สกัดออกมาตามขนาด ใช้เลื่อย เลื่อยทั้งด้านหลังและด้านหน้า ตั้งแต่ฐานถึงยอดผนัง และมีตั้งแต่ข้างนอกถึงลานใหญ่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 10, 'ฐานนั้นทําด้วยหินมีค่า หินก้อนมหึมา หินขนาดแปดและสิบศอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 11, 'ข้างบนก็เป็นหินมีค่า สกัดออกมาตามขนาด และไม้สนสีดาร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 12, 'กําแพงลานใหญ่มีหินสกัดสามชั้นโดยรอบ และไม้สนสีดาร์ชั้นหนึ่ง ลานชั้นในของพระนิเวศของพระเยโฮวาห์ก็มีเหมือนกัน ทั้งมุขพระนิเวศด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 13, 'กษัตริย์ซาโลมอนทรงใช้คนให้นําฮีรามมาจากเมืองไทระ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 14, 'ท่านเป็นบุตรชายของหญิงม่ายตระกูลนัฟทาลี และบิดาของท่านเป็นชายชาวเมืองไทระ เป็นช่างทองเหลือง และท่านประกอบด้วยสติปัญญา ความเข้าใจและฝีมือที่จะทํางานทุกอย่างด้วยทองเหลือง ท่านมาเฝ้ากษัตริย์ซาโลมอนและทํางานทั้งสิ้นของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 15, 'ท่านได้ทําเสาทองเหลืองสองเสา แต่ละเสาสูงสิบแปดศอก วัดขนาดเส้นรอบแต่ละเสาได้สิบสองศอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 16, 'ท่านทําบัวคว่ําหัวเสาสองอันด้วยทองเหลืองหล่อ เพื่อจะวางไว้บนยอดเสา บัวคว่ําหัวเสาอันหนึ่งสูงห้าศอก และความสูงของบัวคว่ําหัวเสาอีกอันหนึ่งก็ห้าศอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 17, 'แล้วมีตาข่ายเป็นตาหมากรุกด้วยมาลัยโซ่สําหรับบัวคว่ําที่อยู่บนหัวเสา เจ็ดอันสําหรับบัวคว่ําอันหนึ่ง และเจ็ดอันสําหรับบัวคว่ําอีกอันหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 18, 'ท่านทําเสานั้นพร้อมด้วยลูกทับทิม มีสองแถวล้อมทับตาข่ายผืนหนึ่ง เพื่อคลุมบัวคว่ําที่อยู่ยอดเสา และท่านก็ทําเช่นเดียวกันสําหรับบัวคว่ําอีกอันหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 19, 'ฝ่ายบัวคว่ําซึ่งอยู่บนยอดเสาที่อยู่ในมุขนั้นเป็นดอกลิลลี่ ขนาดสี่ศอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 20, 'บัวคว่ําซึ่งอยู่บนเสาสองต้นนั้นมีลูกทับทิมด้วย และอยู่เหนือคิ้วซึ่งอยู่ถัดตาข่าย มีลูกทับทิมสองร้อยลูกอยู่ล้อมรอบเป็นสองแถว บัวคว่ําอีกอันหนึ่งก็มีเหมือนกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 21, 'ท่านตั้งเสาไว้ที่มุขพระวิหาร ท่านตั้งเสาข้างขวาไว้ และเรียกชื่อว่ายาคีน และท่านตั้งเสาข้างซ้ายไว้ เรียกชื่อว่าโบอาส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 22, 'และบนยอดเสานั้นเป็นลายดอกลิลลี่ งานของเสาก็สําเร็จดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 23, 'แล้วท่านได้หล่อขันสาครเป็นขันกลม วัดจากขอบหนึ่งไปถึงอีกขอบหนึ่งได้สิบศอก สูงห้าศอก และวัดโดยรอบได้สามสิบศอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 24, 'ใต้ขอบเป็นลูกดอกตูม ในระยะหนึ่งศอกมีลูกดอกตูมสิบลูก อยู่รอบขันสาคร ดอกตูมอยู่สองแถวหล่อพร้อมกับเมื่อหล่อขันสาคร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 25, 'ขันสาครนั้นวางอยู่บนวัวสิบสองตัว หันหน้าไปทิศเหนือสามตัว หันหน้าไปทิศตะวันตกสามตัว หันหน้าไปทิศใต้สามตัว หันหน้าไปทิศตะวันออกสามตัว เขาวางขันสาครอยู่บนวัว ส่วนหลังทั้งหมดของวัวอยู่ด้านใน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 26, 'ขันสาครหนาหนึ่งคืบ ที่ขอบของขันทําเหมือนขอบถ้วยเหมือนอย่างดอกลิลลี่ บรรจุได้สองพันบัท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 27, 'ท่านทําแท่นทองเหลืองสิบอัน แท่นอันหนึ่งยาวสี่ศอก กว้างสี่ศอก สูงสามศอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 28, 'ท่านสร้างแท่นอย่างนี้ แท่นนี้มีแผง แผงนี้ฝังอยู่ในกรอบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 29, 'บนแผงที่ฝังอยู่ในกรอบนั้นมีรูปสิงโต วัว และเครูบ ข้างบนกรอบมีแท่นที่อยู่เหนือ และใต้สิงโตและวัวมีลวดลายเป็นมาลัยฝีค้อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 30, 'แล้วแท่นหนึ่งๆมีล้อทองเหลืองสี่ล้อ และมีเพลาทองเหลือง ที่มุมทั้งสี่มีที่หนุน ขันที่หนุนอันหนึ่งหล่อมีมาลัยห้อยข้างๆทุกข้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 31, 'ช่องเปิดอยู่ในบัวคว่ํา ซึ่งยื่นขึ้นไปหนึ่งศอก ช่องเปิดนั้นกลมอย่างที่เขาทําแท่น ลึกหนึ่งศอกคืบ ตรงช่องเปิดมีลายสลัก และแผงนั้นก็สี่เหลี่ยมไม่กลม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 32, 'ล้อทั้งสี่อยู่ใต้แผง เพลาล้อนั้นเป็นชิ้นเดียวกับแท่น ล้ออันหนึ่งสูงหนึ่งศอกคืบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 33, 'ล้อนั้นเขาทําเหมือนล้อรถรบ ทั้งเพลา ขอบล้อ ซี่ และดุมก็หล่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 34, 'แท่นหนึ่งๆมีที่หนุนอยู่ที่มุมทั้งสี่ ที่หนุนนี้หล่อเป็นชิ้นเดียวกับแท่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 35, 'ที่บนยอดแท่นมีแถบกลมยอดสูงคืบหนึ่ง และบนยอดแท่นนั้นมีกรอบและแผงติดเป็นอันเดียวกับแท่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 36, 'ที่พื้นกรอบและพื้นแผง ท่านสลักเป็นรูปเครูบ สิงโต และต้นอินทผลัม ตามที่ว่างของแต่ละสิ่ง มีลายมาลัยรอบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 37, 'ท่านได้ทําแท่นสิบแท่นตามอย่างนี้ หล่อเหมือนกันหมดทุกอัน ขนาดเดียวกันและรูปเดียวกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 38, 'ท่านทําขันทองเหลืองสิบลูก ขันลูกหนึ่งจุสี่สิบบัท ขนาดขันลูกหนึ่งสี่ศอก มีขันแท่นละลูกทั้งสิบแท่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 39, 'ท่านวางแท่นขันนั้นไว้ทางด้านขวาของพระนิเวศห้าแท่น และทางด้านซ้ายของพระนิเวศห้าแท่น และท่านวางขันสาครไว้ที่ด้านขวาพระนิเวศทางทิศตะวันออกเฉียงใต้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 40, 'ฮีรามได้ทําขัน พลั่วและชามด้วย ดังนั้นฮีรามก็เสร็จงานทั้งสิ้นซึ่งเขาต้องกระทําถวายกษัตริย์ซาโลมอนสําหรับพระนิเวศของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 41, 'เสาสองต้น คิ้วทั้งสองของบัวคว่ําที่อยู่บนยอดเสา และตาข่ายสองผืน ซึ่งคลุมคิ้วทั้งสองของบัวคว่ําซึ่งอยู่บนยอดเสา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 42, 'และลูกทับทิมสี่ร้อยสําหรับตาข่ายสองผืน ตาข่ายผืนหนึ่งมีลูกทับทิมสองแถว เพื่อคลุมคิ้วทั้งสองของบัวคว่ําซึ่งอยู่บนเสา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 43, 'แท่นสิบแท่น และขันสิบลูกซึ่งอยู่บนแท่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 44, 'และขันสาครลูกหนึ่ง และวัวสิบสองตัวที่อยู่ใต้ขันสาคร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 45, 'หม้อ พลั่ว และชาม ภาชนะทั้งสิ้นเหล่านี้ในพระนิเวศของพระเยโฮวาห์ ซึ่งฮีรามได้ทําถวายกษัตริย์ซาโลมอนเป็นของที่ทําด้วยทองเหลืองขัดมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 46, 'กษัตริย์ทรงหล่อสิ่งเหล่านี้ในที่ราบลุ่มของแม่น้ําจอร์แดน และในที่ดินโคลนระหว่างเมืองสุคคทและศาเรธาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 47, 'ซาโลมอนทรงหาได้ชั่งเครื่องใช้ทั้งหมดนี้ไม่ เพราะว่ามีมากด้วยกัน จึงมิได้หาน้ําหนักของทองเหลือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 48, 'ซาโลมอนได้ทรงกระทําเครื่องใช้ทั้งสิ้นซึ่งอยู่ในพระนิเวศของพระเยโฮวาห์ คือแท่นบูชาทองคํา และทรงทําโต๊ะขนมปังหน้าพระพักตร์ด้วยทองคํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 49, 'เชิงประทีปทําด้วยทองคําบริสุทธิ์อยู่ทางด้านขวาห้าอัน อยู่ทางด้านซ้ายห้าอัน ข้างหน้าห้องหลัง ดอกไม้ ตะเกียง และตะไกรตัดไส้ตะเกียงทําด้วยทองคํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 50, 'อ่าง ตะไกรตัดไส้ตะเกียง ชาม ช้อน และกระถางไฟทําด้วยทองคําบริสุทธิ์ และเดือยสําหรับประตูของส่วนชั้นในพระนิเวศ คือที่บริสุทธิ์ที่สุด และสําหรับประตูห้องโถงของพระวิหาร ก็ทําด้วยทองคํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 51, 'บรรดากิจการซึ่งกษัตริย์ซาโลมอนกระทําเกี่ยวด้วยพระนิเวศของพระเยโฮวาห์ก็ได้สําเร็จดังนี้ และซาโลมอนทรงนําบรรดาสิ่งซึ่งดาวิดราชบิดาทรงถวายไว้เข้ามา คือเครื่องเงิน เครื่องทองคํา และเครื่องใช้ต่างๆ และเก็บไว้ในคลังพระนิเวศของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 1, 'แล้วซาโลมอนทรงประชุมพวกผู้ใหญ่ของอิสราเอล และบรรดาหัวหน้าของตระกูล คือประมุขของบรรพบุรุษคนอิสราเอล ต่อพระพักตร์กษัตริย์ซาโลมอนในกรุงเยรูซาเล็ม เพื่อจะนําหีบพันธสัญญาของพระเยโฮวาห์ขึ้นมาจากนครดาวิด คือเมืองศิโยน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 2, 'และผู้ชายทั้งสิ้นของอิสราเอลก็ประชุมต่อพระพักตร์กษัตริย์ซาโลมอน ณ การเลี้ยงในเดือนเอธานิม ซึ่งเป็นเดือนที่เจ็ด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 3, 'พวกผู้ใหญ่ทั้งสิ้นของอิสราเอลมา และพวกปุโรหิตก็ยกหีบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 4, 'และเขาทั้งหลายนําหีบของพระเยโฮวาห์ และพลับพลาแห่งชุมนุม และเครื่องใช้บริสุทธิ์ทั้งสิ้นซึ่งอยู่ในพลับพลาขึ้นมา ของเหล่านี้บรรดาปุโรหิตและคนเลวีหามขึ้นมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 5, 'และกษัตริย์ซาโลมอน และชุมนุมชนอิสราเอลทั้งสิ้นที่ได้ประชุมกันต่อพระองค์ อยู่กับพระองค์ต่อหน้าหีบ ได้ถวายแกะและวัวมากมาย ซึ่งเขาจะนับหรือเอาจํานวนก็ไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 6, 'แล้วปุโรหิตก็นําหีบพันธสัญญาของพระเยโฮวาห์มายังที่ของหีบ ที่อยู่ในห้องหลังของพระนิเวศ คือในที่บริสุทธิ์ที่สุด ภายใต้ปีกเครูบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 7, 'เพราะว่าเครูบนั้นกางปีกออกเหนือที่ของหีบ เครูบจึงเป็นเครื่องคลุมเหนือหีบ และไม้คานหามของหีบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 8, 'พวกเขาดึงคานหามของหีบนั้นออกบ้าง จึงเห็นปลายคานหามได้จากที่บริสุทธิ์ที่สุด ซึ่งอยู่ข้างหน้าห้องหลัง แต่เขาจะเห็นจากข้างนอกไม่ได้ และคานหามก็ยังอยู่ที่นั่นจนทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 9, 'ไม่มีสิ่งใดในหีบนอกจากศิลาสองแผ่น ซึ่งโมเสสเก็บไว้ ณ โฮเรบ เมื่อพระเยโฮวาห์ทรงกระทําพันธสัญญากับชนอิสราเอล เมื่อเขาทั้งหลายออกมาจากแผ่นดินอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 10, 'และอยู่มาเมื่อปุโรหิตออกมาจากที่บริสุทธิ์ที่สุด เมฆมาเต็มพระนิเวศของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 11, 'ปุโรหิตจึงยืนปรนนิบัติอยู่ไม่ได้เพราะเมฆนั้น เพราะสง่าราศีของพระเยโฮวาห์เต็มพระนิเวศของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 12, 'แล้วซาโลมอนตรัสว่า “พระเยโฮวาห์ได้ตรัสว่า พระองค์จะประทับในความมืดทึบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 13, 'ข้าพระองค์ได้สร้างพระนิเวศอันเป็นที่ประทับสําหรับพระองค์ เป็นสถานที่ถาวรเพื่อพระองค์จะทรงสถิตอยู่เป็นนิตย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 14, 'แล้วกษัตริย์ก็หันมาและทรงให้พรแก่ชุมนุมชนอิสราเอลทั้งปวง (ขณะที่ชุมนุมชนอิสราเอลทั้งปวงยืนอยู่)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 15, 'พระองค์ตรัสว่า “สาธุการแด่พระเยโฮวาห์พระเจ้าแห่งอิสราเอล ผู้ทรงกระทําให้สําเร็จด้วยพระหัตถ์ของพระองค์ ตามที่พระองค์ตรัสไว้ด้วยพระโอษฐ์ต่อดาวิดราชบิดาของข้าพเจ้าว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 16, '‘ตั้งแต่วันที่เราได้นําอิสราเอลชนชาติของเราออกจากอียิปต์ เรามิได้เลือกเมืองหนึ่งเมืองใดในตระกูลอิสราเอลทั้งสิ้นเพื่อจะสร้างพระนิเวศ เพื่อนามของเราจะอยู่ที่นั่น แต่เราได้เลือกดาวิดให้อยู่เหนืออิสราเอลชนชาติของเรา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 17, 'ดาวิดราชบิดาของข้าพเจ้าทรงตั้งพระทัยแล้วที่จะสร้างพระนิเวศสําหรับพระนามแห่งพระเยโฮวาห์พระเจ้าของอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 18, 'แต่พระเยโฮวาห์ตรัสกับดาวิดราชบิดาของข้าพเจ้าว่า ‘ที่เจ้าตั้งใจสร้างพระนิเวศสําหรับนามของเรานั้น เจ้าก็ทําดีอยู่แล้ว ในเรื่องความตั้งใจของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 19, 'อย่างไรก็ตาม เจ้าจะไม่สร้างพระนิเวศ แต่บุตรชายของเจ้าผู้ซึ่งจะออกมาจากบั้นเอวของเจ้าจะสร้างพระนิเวศเพื่อนามของเรา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 20, 'บัดนี้พระเยโฮวาห์ทรงให้พระดํารัสของพระองค์ ซึ่งพระองค์ตรัสนั้นสําเร็จ เพราะข้าพเจ้าได้ขึ้นมาแทนดาวิดราชบิดาของข้าพเจ้า และนั่งอยู่บนบัลลังก์ของอิสราเอล ดังที่พระเยโฮวาห์ได้ทรงสัญญาไว้ และข้าพเจ้าได้สร้างพระนิเวศสําหรับพระนามของพระเยโฮวาห์พระเจ้าแห่งอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 21, 'ข้าพเจ้าได้กําหนดที่ไว้สําหรับหีบที่นั่นแล้ว ซึ่งพันธสัญญาของพระเยโฮวาห์อยู่ในนั้น ซึ่งพระองค์ได้ทรงกระทําไว้กับบรรพบุรุษของเรา เมื่อพระองค์ทรงนําเขาทั้งหลายออกมาจากแผ่นดินอียิปต์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 22, 'แล้วซาโลมอนประทับยืนหน้าแท่นบูชาของพระเยโฮวาห์ต่อหน้าชุมนุมชนอิสราเอลทั้งปวง และกางพระหัตถ์ของพระองค์ออกสู่ฟ้าสวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 23, 'และทูลว่า “ข้าแต่พระเยโฮวาห์พระเจ้าแห่งอิสราเอล ไม่มีพระเจ้าองค์ใดเหมือนพระองค์ ในฟ้าสวรรค์เบื้องบน หรือที่แผ่นดินเบื้องล่าง ผู้ทรงรักษาพันธสัญญา และทรงสําแดงความเมตตาแก่ผู้รับใช้ของพระองค์ ซึ่งดําเนินอยู่ต่อพระพักตร์พระองค์ด้วยสิ้นสุดใจของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 24, 'พระองค์ได้ทรงกระทํากับดาวิดบิดาของข้าพระองค์ ผู้รับใช้ของพระองค์ ตามบรรดาสิ่งซึ่งพระองค์ทรงสัญญาไว้แก่ท่าน พระองค์ตรัสด้วยพระโอษฐ์ของพระองค์ และพระองค์ได้ทรงกระทําให้สําเร็จในวันนี้ด้วยพระหัตถ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 25, 'ข้าแต่พระเยโฮวาห์พระเจ้าแห่งอิสราเอล เพราะฉะนั้นบัดนี้ขอทรงรักษาสิ่งที่พระองค์ทรงสัญญาไว้กับดาวิดผู้รับใช้ของพระองค์ราชบิดาของข้าพระองค์ว่า ‘เจ้าจะไม่ขาดชายผู้หนึ่งในสายตาของเราที่จะนั่งบนบัลลังก์แห่งอิสราเอล เพื่อว่าลูกหลานทั้งหลายของเจ้าจะระมัดระวังในวิถีทางของเขา ที่เขาจะดําเนินไปต่อหน้าเราอย่างที่เจ้าได้ดําเนินต่อหน้าเรานั้น’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 26, 'เพราะฉะนั้นบัดนี้ โอ ข้าแต่พระเจ้าแห่งอิสราเอล ขอพระวจนะของพระองค์จงดํารงอยู่ ซึ่งพระองค์ได้ตรัสกับผู้รับใช้ของพระองค์ คือดาวิดบิดาของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 27, 'แต่พระเจ้าจะทรงประทับที่แผ่นดินโลกหรือ ดูเถิด ฟ้าสวรรค์และฟ้าสวรรค์อันสูงที่สุดยังรับพระองค์อยู่ไม่ได้ พระนิเวศซึ่งข้าพระองค์ได้สร้างขึ้นจะรับพระองค์ไม่ได้ยิ่งกว่านั้นสักเท่าใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 28, 'แต่ขอพระองค์สนพระทัยในคําอธิษฐานของผู้รับใช้ของพระองค์ และในคําวิงวอนนี้ โอ ข้าแต่พระเยโฮวาห์พระเจ้าของข้าพระองค์ ขอทรงสดับเสียงร้องและคําอธิษฐานซึ่งผู้รับใช้ของพระองค์อธิษฐานต่อพระพักตร์พระองค์ในวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 29, 'เพื่อว่าพระเนตรของพระองค์จะทรงลืมอยู่เหนือพระนิเวศนี้ ทั้งกลางคืนและกลางวัน คือสถานที่ซึ่งพระองค์ได้ตรัสว่า ‘นามของเราจะอยู่ที่นั่น’ เพื่อว่าพระองค์จะทรงสดับคําอธิษฐาน ซึ่งผู้รับใช้ของพระองค์จะได้อธิษฐานตรงต่อสถานที่นี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 30, 'และขอพระองค์ทรงสดับคําวิงวอนของผู้รับใช้ของพระองค์ และของอิสราเอลชนชาติของพระองค์ เมื่อเขาอธิษฐานตรงต่อสถานที่นี้ ขอพระองค์ทรงสดับอยู่ในฟ้าสวรรค์ อันเป็นที่ประทับของพระองค์ และเมื่อพระองค์ทรงสดับแล้ว ก็ขอพระองค์ทรงประทานอภัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 31, 'เมื่อชายคนใดกระทําการละเมิดต่อเพื่อนบ้านของเขา และถูกบังคับให้ทําสัตย์สาบาน และเขามาให้คําสาบานต่อหน้าแท่นบูชาของพระองค์ในพระนิเวศนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 32, 'ขอพระองค์ทรงสดับในฟ้าสวรรค์ และขอทรงกระทําและทรงพิพากษาผู้รับใช้ทั้งหลายของพระองค์ กล่าวโทษผู้กระทําความผิด และทรงนําความประพฤติของเขาให้กลับตกบนศีรษะของตัวเขาเอง และขอทรงประกาศความบริสุทธิ์ของผู้ชอบธรรมสนองแก่เขาตามความชอบธรรมของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 33, 'เมื่ออิสราเอลชนชาติของพระองค์พ่ายแพ้ต่อหน้าศัตรู เพราะเขาได้กระทําบาปต่อพระองค์ ถ้าเขาหันกลับมาหาพระองค์อีก และยอมรับพระนามของพระองค์ และอธิษฐานและกระทําการวิงวอนต่อพระองค์ในพระนิเวศนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 34, 'ก็ขอพระองค์ทรงสดับในฟ้าสวรรค์ และประทานอภัยแก่บาปของอิสราเอลชนชาติของพระองค์ และขอทรงนําเขากลับมายังแผ่นดินซึ่งพระองค์ได้ทรงพระราชทานแก่บรรพบุรุษของเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 35, 'เมื่อฟ้าสวรรค์ปิดอยู่ และไม่มีฝน เพราะเขาทั้งหลายได้กระทําบาปต่อพระองค์ ถ้าเขาทั้งหลายได้อธิษฐานต่อสถานที่นี้ และยอมรับพระนามของพระองค์ และหันกลับเสียจากบาปของเขาทั้งหลาย เมื่อพระองค์ทรงให้เขาทั้งหลายรับความทุกข์ใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 36, 'ก็ขอพระองค์ทรงสดับในฟ้าสวรรค์ และขอทรงประทานอภัยบาปของผู้รับใช้ของพระองค์ และของอิสราเอลประชาชนของพระองค์ เมื่อพระองค์ทรงสอนทางดีแก่เขา ซึ่งเขาควรจะดําเนิน และขอทรงประทานฝนบนแผ่นดินของพระองค์ ซึ่งพระองค์ได้ทรงพระราชทานแก่ชนชาติของพระองค์เป็นมรดกนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 37, 'ถ้ามีการกันดารอาหารในแผ่นดิน ถ้ามีโรคระบาด ข้าวม้าน รากินข้าว หรือตั๊กแตนวัยบิน หรือตั๊กแตนวัยคลาน หรือถ้าศัตรูของเขาทั้งหลายล้อมเมืองของเขาไว้รอบด้าน จะเป็นภัยพิบัติอย่างใด หรือความเจ็บไข้อย่างใด มีขึ้นก็ดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 38, 'ไม่ว่าคําอธิษฐานอย่างใด หรือคําวิงวอนประการใดซึ่งประชาชนคนใด หรืออิสราเอลประชาชนของพระองค์ทั้งสิ้นทูล ต่างก็สํานึกถึงเรื่องภัยพิบัติแห่งจิตใจของเขาเอง และได้กางมือของเขาสู่พระนิเวศนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 39, 'ขอพระองค์ทรงสดับในฟ้าสวรรค์ อันเป็นที่ประทับของพระองค์ และพระราชทานอภัยและทรงกระทํา และทรงประทานแก่ทุกคนซึ่งพระองค์ทรงทราบจิตใจตามการประพฤติทั้งสิ้นของเขา (เพราะพระองค์คือพระองค์เท่านั้นที่ทรงทราบจิตใจแห่งบุตรทั้งหลายของมนุษย์)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 40, 'เพื่อว่าเขาทั้งหลายจะได้ยําเกรงพระองค์ตลอดวันเวลาที่เขาทั้งหลายอาศัยในแผ่นดิน ซึ่งพระองค์ทรงประทานแก่บรรพบุรุษของข้าพระองค์ทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 41, 'ยิ่งกว่านั้นอีกเกี่ยวกับชนต่างด้าว ผู้ซึ่งไม่ใช่อิสราเอลประชาชนของพระองค์ เมื่อเขามาจากประเทศเมืองไกล เพราะเห็นแก่พระนามของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 42, '(เพราะเขาทั้งหลายจะได้ยินถึงพระนามใหญ่ยิ่งของพระองค์ และถึงพระหัตถ์อันมหิทธิฤทธิ์ของพระองค์ และถึงพระกรที่เหยียดออกของพระองค์) เมื่อเขามาอธิษฐานตรงต่อพระนิเวศนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 43, 'ก็ขอพระองค์ทรงสดับในฟ้าสวรรค์อันเป็นที่ประทับของพระองค์ และขอทรงกระทําตามทุกสิ่งซึ่งชนต่างด้าวได้ทูลขอต่อพระองค์ เพื่อว่าชนชาติทั้งหลายแห่งแผ่นดินโลกจะรู้จักพระนามของพระองค์และเกรงกลัวพระองค์ ดังอิสราเอลประชาชนของพระองค์ยําเกรงพระองค์อยู่นั้น และเพื่อเขาทั้งหลายจะทราบว่า พระนิเวศนี้ซึ่งข้าพระองค์ได้สร้างไว้เขาเรียกกันด้วยพระนามของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 44, 'ถ้าประชาชนของพระองค์ออกไปทําสงครามต่อสู้ศัตรูของเขาทั้งหลาย จะเป็นโดยทางใดๆที่พระองค์ทรงใช้เขาออกไปก็ตาม และเขาทั้งหลายได้อธิษฐานต่อพระเยโฮวาห์ตรงต่อเมืองซึ่งพระองค์ทรงเลือกสรรไว้ และตรงต่อพระนิเวศซึ่งข้าพระองค์ได้สร้างสําหรับพระนามของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 45, 'ขอพระองค์ทรงสดับคําอธิษฐานของเขาและคําวิงวอนของเขาในฟ้าสวรรค์ และขอทรงให้สิทธิอันชอบธรรมของเขาคงอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 46, 'ถ้าเขาทั้งหลายกระทําบาปต่อพระองค์ (เพราะไม่มีมนุษย์สักคนหนึ่งซึ่งมิได้กระทําบาป) และพระองค์ทรงกริ้วต่อเขา และทรงมอบเขาไว้กับศัตรู เขาจึงถูกจับไปเป็นเชลยยังแผ่นดินของศัตรูนั้น ไม่ว่าไกลหรือใกล้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 47, 'แต่ถ้าเขาสํานึกผิดในใจในแผ่นดินซึ่งเขาได้ถูกจับไปเป็นเชลยและได้กลับใจ และได้ทําการวิงวอนต่อพระองค์ในแผ่นดินของผู้จับเขาไปเป็นเชลย ทูลว่า ‘ข้าพระองค์ทั้งหลายได้กระทําบาป และได้ประพฤติชั่วร้ายและได้กระทําความชั่ว’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 48, 'ถ้าเขาทั้งหลายกลับมาหาพระองค์ด้วยสุดจิตสุดใจของเขาในแผ่นดินแห่งศัตรูทั้งหลายของเขา ผู้ซึ่งจับเขาไปเป็นเชลย และอธิษฐานต่อพระองค์ตรงต่อแผ่นดินของเขา ซึ่งพระองค์ทรงประทานแก่บรรพบุรุษของเขาทั้งหลาย คือเมืองซึ่งพระองค์ได้ทรงเลือกสรรไว้ และพระนิเวศซึ่งข้าพระองค์ได้สร้างไว้เพื่อพระนามของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 49, 'ขอพระองค์ทรงสดับคําอธิษฐานและคําวิงวอนของเขาในฟ้าสวรรค์ อันเป็นที่ประทับของพระองค์ และขอทรงให้สิทธิอันชอบธรรมของเขาคงอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 50, 'และขอทรงประทานอภัยแก่ประชาชนของพระองค์ผู้ได้กระทําบาปต่อพระองค์ และทรงประทานอภัยต่อการละเมิดทั้งหลายของเขา ซึ่งเขาได้กระทําต่อพระองค์ และให้เขาเป็นที่เมตตาของคนเหล่านั้นที่จับเขาทั้งหลายไปเป็นเชลย เพื่อเขาทั้งหลายจะได้รับความเมตตาจากเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 51, 'เพราะว่าเขาทั้งหลายเป็นประชาชนของพระองค์ และเป็นมรดกของพระองค์ ซึ่งพระองค์ทรงนําออกมาจากอียิปต์ จากท่ามกลางเตาเหล็ก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 52, 'ขอพระเนตรของพระองค์จงลืมอยู่ต่อคําวิงวอนของผู้รับใช้ของพระองค์ และต่อคําวิงวอนของอิสราเอลประชาชนของพระองค์ ขอทรงสดับบรรดาเรื่องที่เขาทั้งหลายร้องต่อพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 53, 'เพราะพระองค์ทรงแยกเขาจากท่ามกลางชนชาติทั้งหลายของแผ่นดินโลก ให้เป็นมรดกของพระองค์ ตามซึ่งพระองค์ตรัสทางโมเสส ผู้รับใช้ของพระองค์ โอ ข้าแต่องค์พระผู้เป็นเจ้าพระเจ้า ในเมื่อพระองค์ทรงนําบรรพบุรุษของข้าพระองค์ทั้งหลายออกจากอียิปต์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 54, 'ครั้นซาโลมอนทรงจบคําอธิษฐาน และคําวิงวอนทั้งสิ้นนี้ต่อพระเยโฮวาห์แล้ว ก็ทรงลุกขึ้นจากหน้าแท่นบูชาของพระเยโฮวาห์ ที่ซึ่งทรงคุกเข่าพร้อมกับกางพระหัตถ์สู่ฟ้าสวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 55, 'และพระองค์ทรงประทับยืน และทรงให้พรแก่ชุมนุมชนอิสราเอลทั้งสิ้นด้วยเสียงดังว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 56, '“สาธุการแด่พระเยโฮวาห์ ผู้ทรงพระราชทานการหยุดพักแก่อิสราเอลประชาชนของพระองค์ ตามซึ่งพระองค์ทรงสัญญาไว้ทุกประการ พระสัญญาอันดีทั้งสิ้นของพระองค์ ซึ่งพระองค์ทรงสัญญาทางโมเสสผู้รับใช้ของพระองค์นั้นไม่ล้มเหลวสักคําเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 57, 'ขอพระเยโฮวาห์พระเจ้าของเราทั้งหลายสถิตกับเราดังที่พระองค์ได้สถิตกับบรรพบุรุษของเรา ขอพระองค์อย่าทรงละเราหรือทอดทิ้งเราเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 58, 'เพื่อพระองค์ทรงโน้มจิตใจของเราให้มาหาพระองค์ ที่จะดําเนินในทางทั้งสิ้นของพระองค์ และรักษาบรรดาพระบัญญัติของพระองค์ กฎเกณฑ์ของพระองค์ และคําตัดสินของพระองค์ ซึ่งพระองค์ทรงบัญญัติไว้แก่บรรพบุรุษของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 59, 'ขอให้ถ้อยคําเหล่านี้ของข้าพเจ้า ซึ่งข้าพเจ้าได้วิงวอนขอต่อพระพักตร์พระเยโฮวาห์ ให้อยู่ใกล้พระเยโฮวาห์พระเจ้าของพวกเราทั้งวันและคืน และขอให้สิทธิอันชอบธรรมของผู้รับใช้ของพระองค์คงอยู่ และให้สิทธิอันชอบธรรมของอิสราเอลประชาชนของพระองค์คงอยู่ ตามความต้องการแต่ละวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 60, 'เพื่อบรรดาชนชาติทั้งหลายแห่งแผ่นดินโลกจะทราบว่าพระเยโฮวาห์นั้นเป็นพระเจ้า ไม่มีองค์อื่นเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 61, 'เพราะฉะนั้นขอให้จิตใจของท่านทั้งหลายบริสุทธิ์ต่อพระเยโฮวาห์พระเจ้าของเรา คือที่จะดําเนินอยู่ในกฎเกณฑ์ของพระองค์ และรักษาพระบัญญัติของพระองค์ ดังในเวลานี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 62, 'แล้วกษัตริย์และชนอิสราเอลทั้งปวงที่อยู่กับพระองค์ได้ถวายเครื่องสัตวบูชาต่อพระพักตร์พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 63, 'และซาโลมอนได้ถวายเครื่องสันติบูชา ซึ่งพระองค์ทรงถวายแด่พระเยโฮวาห์ คือวัวสองหมื่นสองพันตัว และแกะหนึ่งแสนสองหมื่นตัว กษัตริย์และคนอิสราเอลทั้งปวงจึงอุทิศถวายพระนิเวศแห่งพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 64, 'ในวันเดียวกันนั้นกษัตริย์ทรงทําพิธีชําระส่วนกลางของลาน ซึ่งอยู่หน้าพระนิเวศของพระเยโฮวาห์ เพราะว่าที่นั่นพระองค์ได้ถวายเครื่องเผาบูชา และธัญญบูชา และส่วนไขมันของสันติบูชา เพราะว่าแท่นทองเหลืองซึ่งอยู่ต่อพระพักตร์พระเยโฮวาห์นั้นเล็กเกินไป ไม่พอรับเครื่องเผาบูชาและธัญญบูชา และส่วนไขมันของสันติบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 65, 'ซาโลมอนจึงทรงฉลองเทศกาลในเวลานั้น พร้อมกับอิสราเอลทั้งปวง เป็นชุมนุมมโหฬาร มีคนมาตั้งแต่ทางเข้าเมืองฮามัทจนถึงแม่น้ําแห่งอียิปต์ ต่อพระพักตร์พระเยโฮวาห์พระเจ้าของเรา เป็นเจ็ดวันและเจ็ดวันคือสิบสี่วัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 66, 'ในวันที่แปดพระองค์ทรงให้ประชาชนกลับ เขาทั้งหลายก็ถวายพระพรแด่กษัตริย์ และกลับไปสู่เต็นท์ของตน ด้วยจิตใจชื่นบานและยินดี เนื่องด้วยความดีทั้งสิ้นซึ่งพระเยโฮวาห์ทรงกระทําแก่ดาวิดผู้รับใช้ของพระองค์ และแก่อิสราเอลประชาชนของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 1, 'อยู่มาเมื่อซาโลมอนได้สร้างพระนิเวศของพระเยโฮวาห์และพระราชวังของกษัตริย์ และบรรดาสิ่งที่ซาโลมอนมีพระประสงค์จะสร้างนั้นสําเร็จแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 2, 'พระเยโฮวาห์ทรงปรากฏแก่ซาโลมอนเป็นครั้งที่สอง ดังที่พระองค์ทรงปรากฏแก่ท่านที่กิเบโอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 3, 'และพระเยโฮวาห์ตรัสกับท่านว่า “เราได้ยินคําอธิษฐานของเจ้าและคําวิงวอนของเจ้าซึ่งเจ้าได้กระทําต่อเรานั้นแล้ว เราได้รับพระนิเวศซึ่งเจ้าได้สร้างนี้ไว้เป็นสถานบริสุทธิ์และได้ประดิษฐานนามของเราไว้ที่นั่นเป็นนิตย์ ตาของเราและใจของเราจะอยู่ที่นั่นตลอดไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 4, 'และถ้าเจ้าดําเนินต่อหน้าเราดังดาวิดบิดาของเจ้าได้ดําเนินด้วยใจซื่อสัตย์ และด้วยความเที่ยงธรรม กระทําทุกอย่างตามที่เราได้บัญชาเจ้าไว้ และรักษากฎเกณฑ์ของเรา และคําตัดสินของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 5, 'แล้วเราจะสถาปนาราชบัลลังก์ของเจ้าเหนืออิสราเอลเป็นนิตย์ ดังที่เราได้สัญญากับดาวิดบิดาของเจ้าว่า ‘เจ้าจะไม่ขาดชายผู้หนึ่งบนบัลลังก์แห่งอิสราเอล’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 6, 'แต่ถ้าเจ้าหันไปจากการติดตามเรา ตัวเจ้าเองหรือลูกหลานของเจ้าก็ดี และมิได้รักษาบัญญัติของเราและกฎเกณฑ์ของเรา ซึ่งเราได้ตั้งไว้ต่อหน้าเจ้า แต่ไปปรนนิบัติพระอื่นและนมัสการพระนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 7, 'แล้วเราจะตัดอิสราเอลออกเสียจากแผ่นดินซึ่งเราได้ให้แก่เขาทั้งหลาย และพระนิเวศนี้ซึ่งเราได้กระทําให้เป็นสถานบริสุทธิ์เพื่อนามของเรา เราจะเหวี่ยงออกเสียจากสายตาของเรา และอิสราเอลจะเป็นคําภาษิตและคําครหาท่ามกลางชนชาติทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 8, 'และพระนิเวศนี้ ซึ่งสูงส่ง ทุกคนที่ผ่านไปจะประหลาดใจ และเขาจะเย้ยหยันและกล่าวว่า ‘เหตุไฉนพระเยโฮวาห์จึงได้กระทําดั่งนี้แก่แผ่นดินนี้ และแก่พระนิเวศนี้’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 9, 'แล้วเขาจะตอบว่า ‘เพราะว่าเขาทั้งหลายได้ทอดทิ้งพระเยโฮวาห์พระเจ้าของเขา ผู้ได้ทรงนําบรรพบุรุษของเขาออกจากแผ่นดินอียิปต์ และได้ยึดถือพระอื่น และนมัสการและปรนนิบัติพระนั้น เพราะฉะนั้นพระเยโฮวาห์ทรงนําเหตุร้ายทั้งสิ้นนี้มาเหนือเขาทั้งหลาย’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 10, 'อยู่มาเมื่อสิ้นยี่สิบปี ซึ่งซาโลมอนได้ทรงสร้างอาคารสองหลัง คือพระนิเวศของพระเยโฮวาห์ และพระราชวังของกษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 11, '(ฮีรามกษัตริย์เมืองไทระได้ส่งไม้สนสีดาร์ ไม้สนสามใบและทองคําให้แก่ซาโลมอนตามที่พระองค์มีพระประสงค์แล้ว) กษัตริย์ซาโลมอนจึงทรงประทานหัวเมืองในแผ่นดินกาลิลีให้แก่ฮีรามยี่สิบหัวเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 12, 'แต่เมื่อฮีรามเสด็จจากเมืองไทระเพื่อชมหัวเมืองซึ่งซาโลมอนประทานแก่ท่าน หัวเมืองเหล่านั้นไม่เป็นที่พอพระทัยท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 13, 'เพราะฉะนั้นท่านจึงว่า “พระอนุชาเอ๋ย เมืองซึ่งท่านประทานแก่ข้าพเจ้านั้นเป็นเมืองอะไรอย่างนี้” เขาจึงเรียกเมืองเหล่านั้นว่าแผ่นดินคาบูลจนทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 14, 'ฮีรามได้ส่งทองคําหนึ่งร้อยยี่สิบตะลันต์ให้แก่กษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 15, 'นี่เป็นเรื่องแรงงานเกณฑ์ ซึ่งกษัตริย์ซาโลมอนได้เกณฑ์เพื่อสร้างพระนิเวศของพระเยโฮวาห์ และพระราชวังของพระองค์ และป้อมมิลโล และกําแพงกรุงเยรูซาเล็ม และฮาโซร์ และเมกิดโด และเกเซอร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 16, 'ฟาโรห์กษัตริย์อียิปต์ได้ยกทัพขึ้นมายึดเมืองเกเซอร์และเอาไฟเผาเสีย และได้ฆ่าคนคานาอันซึ่งอยู่ในเมืองนั้น และได้ยกเมืองนั้นให้แก่ธิดาของท่านเป็นสินสมรสคือ มเหสีของซาโลมอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 17, 'ซาโลมอนจึงสร้างเกเซอร์ขึ้นใหม่ และสร้างเมืองเบธโฮโรนล่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 18, 'ทั้งเมืองบาอาลัทและเมืองทัดโมร์ในถิ่นทุรกันดารในแผ่นดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 19, 'ทั้งบรรดาหัวเมืองคลังหลวงที่ซาโลมอนมีอยู่ และหัวเมืองสําหรับรถรบของพระองค์ และหัวเมืองสําหรับพลม้าของพระองค์ และสิ่งใดๆซึ่งซาโลมอนมีพระประสงค์จะสร้างในกรุงเยรูซาเล็ม ในเลบานอน และทั่วแผ่นดินซึ่งอยู่ในอาณาจักรของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 20, 'ประชาชนทั้งปวงซึ่งเหลืออยู่จากคนอาโมไรต์ คนฮิตไทต์ คนเปริสซี คนฮีไวต์ และคนเยบุส ผู้ซึ่งไม่ใช่คนอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 21, 'ลูกหลานของเขาที่เหลืออยู่ในแผ่นดิน ซึ่งประชาชนอิสราเอลไม่สามารถจะทําลายให้สิ้นได้ บุคคลเหล่านี้ซาโลมอนทรงเกณฑ์ให้เป็นทาสอยู่จนทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 22, 'แต่ประชาชนอิสราเอลนั้น ซาโลมอนหาได้ทรงกระทําให้เป็นทาสไม่ เขาทั้งหลายเป็นทหาร เป็นข้าราชการ เป็นผู้บังคับบัญชาของพระองค์ เป็นนายทหารของพระองค์ เป็นผู้บังคับการรถรบของพระองค์และเป็นพลม้าของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 23, 'เหล่านี้เป็นเจ้าหน้าที่ชั้นผู้ใหญ่เหนือพระราชกิจของซาโลมอนจํานวนห้าร้อยห้าสิบคน เป็นผู้ดูแลประชาชนที่ทํางาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 24, 'แต่ธิดาของฟาโรห์ได้ขึ้นไปจากนครดาวิด ถึงพระตําหนักของพระนางเองซึ่งซาโลมอนได้สร้างให้พระนาง แล้วพระองค์จึงสร้างป้อมมิลโล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 25, 'ปีละสามครั้ง ซาโลมอนได้ทรงถวายเครื่องเผาบูชา และเครื่องสันติบูชาบนแท่นบูชา ซึ่งพระองค์ทรงสร้างถวายพระเยโฮวาห์ ทรงเผาเครื่องหอมบนแท่นบูชาต่อพระพักตร์พระเยโฮวาห์ ดังนั้นพระองค์จึงสร้างพระนิเวศจนสําเร็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 26, 'กษัตริย์ซาโลมอนทรงสร้างกองเรือกําปั่นที่เอซีโอนเกเบอร์ ซึ่งอยู่ใกล้เอโลท บนฝั่งทะเลแดงในแผ่นดินเอโดม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 27, 'และฮีรามได้ส่งข้าราชการและพลเรือผู้ซึ่งคุ้นเคยกับทะเลไปกับกองกําปั่นพร้อมกับข้าราชการของซาโลมอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 28, 'เขาทั้งหลายไปถึงเมืองโอฟีร์ และนําทองคํามาจากที่นั่น จํานวนสี่ร้อยยี่สิบตะลันต์และนํามาถวายกษัตริย์ซาโลมอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 1, 'เมื่อพระราชินีแห่งเชบาทรงได้ยินกิตติศัพท์แห่งซาโลมอนเกี่ยวกับพระนามของพระเยโฮวาห์ พระนางก็เสด็จมาทดลองพระองค์ด้วยปัญหายุ่งยากต่างๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 2, 'พระนางเสด็จมายังกรุงเยรูซาเล็ม พร้อมด้วยข้าราชบริพารมากมาย มีฝูงอูฐบรรทุกเครื่องเทศและทองคําเป็นอันมาก และเพชรพลอยต่างๆ และเมื่อพระนางเสด็จมาถึงซาโลมอนแล้ว พระนางก็ทูลเรื่องในพระทัยต่อพระองค์ทุกประการ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 3, 'และซาโลมอนตรัสตอบปัญหาของพระนางทั้งสิ้น ไม่มีสิ่งใดที่ซ่อนอยู่พ้นกษัตริย์ซึ่งพระองค์จะทรงอธิบายแก่พระนางไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 4, 'และเมื่อพระราชินีแห่งเชบาทรงเห็นพระสติปัญญาทั้งสิ้นของซาโลมอน และพระราชวังที่พระองค์ทรงสร้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 5, 'ทั้งอาหารที่โต๊ะเสวย กับการเข้าเฝ้าของบรรดาข้าราชการ และการปรนนิบัติรับใช้ของมหาดเล็กตลอดทั้งภูษาอาภรณ์ของเขา และพนักงานเชิญถ้วยของพระองค์ และการที่พระองค์เสด็จขึ้นไปในพระนิเวศของพระเยโฮวาห์ พระทัยของพระนางก็สลดลงทีเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 6, 'พระนางทูลกษัตริย์ว่า “ข่าวคราวซึ่งหม่อมฉันได้ยินในประเทศของหม่อมฉัน ถึงพระราชกิจและพระสติปัญญาของพระองค์เป็นความจริง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 7, 'แต่หม่อมฉันมิได้เชื่อถ้อยคํานั้น จนหม่อมฉันมาเฝ้า และตาของหม่อมฉันได้เห็นเอง และดูเถิด ที่เขาบอกแก่หม่อมฉันก็ไม่ถึงครึ่งหนึ่ง พระสติปัญญาและความมั่งคั่งของพระองค์ก็มากยิ่งกว่าข่าวคราวที่หม่อมฉันได้ยิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 8, 'บรรดาคนของพระองค์ก็เป็นสุข บรรดาข้าราชการเหล่านี้ของพระองค์ผู้อยู่งานประจําต่อพระพักตร์พระองค์ และฟังพระสติปัญญาของพระองค์ก็เป็นสุข');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 9, 'สาธุการแด่พระเยโฮวาห์พระเจ้าของพระองค์ ผู้ทรงพอพระทัยในพระองค์ และทรงแต่งตั้งพระองค์ไว้บนบัลลังก์แห่งอิสราเอล เพราะพระเยโฮวาห์ทรงรักอิสราเอลเป็นนิตย์พระองค์จึงทรงแต่งตั้งให้พระองค์เป็นกษัตริย์ เพื่อว่าพระองค์จะทรงอํานวยความยุติธรรมและความเที่ยงธรรม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 10, 'แล้วพระนางก็ถวายทองคําหนึ่งร้อยยี่สิบตะลันต์แด่กษัตริย์ ทั้งเครื่องเทศเป็นจํานวนมาก และเพชรพลอยต่างๆ ไม่มีเครื่องเทศมามากมายดังนี้อีก ดังที่พระราชินีแห่งเชบาถวายแด่กษัตริย์ซาโลมอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 11, 'ยิ่งกว่านั้นอีก กองกําปั่นของฮีรามซึ่งได้นําทองคํามาจากโอฟีร์ ได้นําไม้จันทน์แดงและเพชรพลอยต่างๆจํานวนมากหลายมาจากโอฟีร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 12, 'และกษัตริย์ทรงใช้ไม้จันทน์แดงทําเสาพระนิเวศแห่งพระเยโฮวาห์ และสําหรับพระราชวังของกษัตริย์ และทําพิณเขาคู่และพิณใหญ่สําหรับนักร้อง จนทุกวันนี้ก็ไม่เคยมีไม้จันทน์แดงมาหรือเห็นอย่างนี้อีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 13, 'กษัตริย์ซาโลมอนทรงพระราชทานทุกอย่างแก่พระราชินีแห่งเชบา ตามที่พระนางมีพระประสงค์ นอกจากสิ่งที่พระราชทานมาจากความอุดมสมบูรณ์ของกษัตริย์แล้ว สิ่งใดๆที่พระนางทูลขอ ซาโลมอนก็พระราชทาน ดังนั้น พระนางก็เสด็จกลับไปยังแผ่นดินของพระนาง พร้อมกับข้าราชการของพระนาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 14, 'น้ําหนักของทองคําที่นํามาส่งซาโลมอนในปีหนึ่งนั้นเป็นทองคําหกร้อยหกสิบหกตะลันต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 15, 'นอกเหนือจากทองคําซึ่งมาจากพ่อค้า และจากการค้าของพวกพ่อค้า และจากกษัตริย์ทั้งปวงของประเทศอาระเบีย และจากบรรดาเจ้าเมืองแห่งแผ่นดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 16, 'กษัตริย์ซาโลมอนทรงสร้างโล่ใหญ่สองร้อยอันด้วยทองคําทุบ โล่อันหนึ่งใช้ทองคําหกร้อยเชเขล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 17, 'และพระองค์ทรงสร้างโล่สามร้อยอันด้วยทองคําทุบ โล่อันหนึ่งใช้ทองคําสามมาเน และกษัตริย์ทรงเก็บโล่ไว้ในพระตําหนักพนาเลบานอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 18, 'กษัตริย์ทรงกระทําพระที่นั่งงาช้างขนาดใหญ่ด้วย และทรงบุด้วยทองคําอย่างงามที่สุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 19, 'พระที่นั่งนั้นมีบันไดหกขั้น พนักหลังของพระที่นั่งนั้นกลมข้างบน และสองข้างพระที่นั่งมีที่วางพระหัตถ์ มีสิงโตสองตัวยืนอยู่ข้างๆที่วางพระหัตถ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 20, 'มีสิงโตอีกสิบสองตัวยืนอยู่ที่นั่นบนหกขั้นบันไดทั้งสองข้าง เขาไม่เคยทําในราชอาณาจักรใดๆเหมือนอย่างนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 21, 'ภาชนะทั้งสิ้นสําหรับเครื่องดื่มของกษัตริย์ซาโลมอนทําด้วยทองคํา และภาชนะทั้งสิ้นของพระตําหนักพนาเลบานอนทําด้วยทองคําบริสุทธิ์ ไม่มีที่ทําด้วยเงินเลย เงินนั้นถือว่าเป็นของไม่มีค่าอะไรในสมัยของซาโลมอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 22, 'เพราะว่ากษัตริย์มีกองกําปั่นเมืองทารชิช เดินทะเลพร้อมกับกองกําปั่นของฮีราม กองกําปั่นเมืองทารชิชนําทองคํา เงิน งาช้าง ลิง และนกยูงมาสามปีต่อครั้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 23, 'ดังนี้แหละ กษัตริย์ซาโลมอนจึงได้เปรียบกว่าบรรดากษัตริย์อื่นๆแห่งแผ่นดินโลกในเรื่องสมบัติและสติปัญญา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 24, 'และทั่วทั้งโลกก็แสวงหาที่จะเข้าเฝ้าซาโลมอน เพื่อจะฟังพระสติปัญญาซึ่งพระเจ้าพระราชทานไว้ในใจของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 25, 'ทุกคนก็นําเครื่องบรรณาการของเขามา เป็นเครื่องทําด้วยเงิน เครื่องทําด้วยทองคํา เครื่องแต่งกาย เครื่องอาวุธ เครื่องเทศ ม้า และล่อ ตามจํานวนกําหนดทุกๆปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 26, 'ซาโลมอนทรงสะสมรถรบและพลม้า พระองค์ทรงมีรถรบหนึ่งพันสี่ร้อยคัน และพลม้าหนึ่งหมื่นสองพันคน ซึ่งพระองค์ทรงให้ประจําอยู่ที่หัวเมืองรถรบ และอยู่กับกษัตริย์ในกรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 27, 'และกษัตริย์ทรงกระทําให้เงินนั้นเป็นของสามัญในกรุงเยรูซาเล็มเหมือนก้อนหิน และทรงกระทําให้มีสนสีดาร์มากมายเหมือนไม้มะเดื่อแห่งหุบเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 28, 'ม้าอันเป็นสินค้าเข้าของซาโลมอนมาจากอียิปต์ พร้อมด้วยเส้นด้ายสําหรับผ้าป่าน และบรรดาพ่อค้าของกษัตริย์รับเส้นด้ายสําหรับผ้าป่านนั้นมาตามราคา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 29, 'จะนํารถรบคันหนึ่งเข้ามาจากอียิปต์ได้ในราคาหกร้อยเชเขลเงิน ม้าตัวหนึ่งหนึ่งร้อยห้าสิบ ดังนั้นโดยทางพวกพ่อค้าเขาก็ส่งออกไปยังบรรดากษัตริย์ทั้งปวงของคนฮิตไทต์ และบรรดากษัตริย์ของซีเรีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 1, 'แต่กษัตริย์ซาโลมอนทรงรักหญิงต่างด้าวหลายคน นอกจากธิดาของฟาโรห์ มีหญิงคนโมอับ คนอัมโมน คนเอโดม คนไซดอน และคนฮิตไทต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 2, 'เป็นของประชาชาติซึ่งพระเยโฮวาห์ตรัสกับคนอิสราเอลว่า “เจ้าทั้งหลายอย่าเข้าไปแต่งงานกับเขาทั้งหลาย หรืออย่าเข้ามาแต่งงานกับเจ้า เพราะเขาจะหันจิตใจของเจ้าไปตามพระของเขาเป็นแน่” ซาโลมอนทรงติดพันกับคนเหล่านี้ด้วยความรัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 3, 'พระองค์ทรงมีมเหสีเจ็ดร้อยคือเจ้าหญิง และนางห้ามสามร้อย และบรรดามเหสีของพระองค์ก็ทรงหันพระทัยของพระองค์ไปเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 4, 'เพราะอยู่มาเมื่อซาโลมอนทรงพระชราแล้ว มเหสีของพระองค์ได้หันพระทัยของพระองค์ให้ไปตามพระอื่น และพระทัยของพระองค์หาได้บริสุทธิ์ต่อพระเยโฮวาห์พระเจ้าของพระองค์ ดังพระทัยของดาวิดราชบิดาของพระองค์ไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 5, 'เพราะซาโลมอนทรงดําเนินตามพระอัชโทเรท พระแม่เจ้าของคนไซดอน และตามพระมิลโคมสิ่งที่น่าสะอิดสะเอียนของคนอัมโมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 6, 'ซาโลมอนจึงทรงกระทําชั่วในสายพระเนตรของพระเยโฮวาห์ และมิได้ทรงติดตามพระเยโฮวาห์อย่างเต็มกําลัง ดังดาวิดราชบิดาของพระองค์ได้ทรงกระทํามาแล้วนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 7, 'แล้วซาโลมอนได้ทรงสร้างปูชนียสถานสูงสําหรับพระเคโมช สิ่งที่น่าสะอิดสะเอียนของโมอับ ในภูเขาที่อยู่หน้ากรุงเยรูซาเล็ม และสําหรับพระโมเลค สิ่งที่น่าสะอิดสะเอียนของคนอัมโมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 8, 'และพระองค์จึงทรงกระทําดังนั้นเพื่อมเหสีต่างด้าวของพระองค์ทั้งสิ้น ผู้ที่ได้เผาเครื่องหอมและถวายเครื่องสัตวบูชาแก่บรรดาพระของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 9, 'พระเยโฮวาห์ทรงกริ้วต่อซาโลมอน เพราะพระทัยของท่านได้หันไปเสียจากพระเยโฮวาห์พระเจ้าแห่งอิสราเอล ผู้ได้ทรงปรากฏแก่ท่านสองครั้งแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 10, 'และได้ทรงบัญชาท่านเกี่ยวกับเรื่องนี้ ว่าท่านไม่ควรไปติดตามพระอื่น แต่ท่านมิได้รักษาพระบัญชาของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 11, 'เพราะฉะนั้นพระเยโฮวาห์ตรัสกับซาโลมอนว่า “เนื่องด้วยเจ้าได้กระทําเช่นนี้ และเจ้ามิได้รักษาพันธสัญญาของเรา และกฎเกณฑ์ของเรา ซึ่งเราได้บัญชาเจ้าไว้ เราจะฉีกอาณาจักรเสียจากเจ้าเป็นแน่และให้แก่ข้าราชการของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 12, 'กระนั้นก็ดีเพราะเห็นแก่ดาวิดบิดาของเจ้าเราจะไม่กระทําในวันเวลาของเจ้า แต่เราจะฉีกออกจากมือบุตรชายของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 13, 'อย่างไรก็ดี เราจะไม่ฉีกเสียหมดอาณาจักร แต่เราจะให้ตระกูลหนึ่งแก่บุตรชายของเจ้า เพื่อเห็นแก่ดาวิดผู้รับใช้ของเรา และเพื่อเห็นแก่เยรูซาเล็มซึ่งเราได้เลือกไว้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 14, 'พระเยโฮวาห์ทรงให้ปฏิปักษ์เกิดขึ้นต่อสู้ซาโลมอน คือฮาดัดคนเอโดม ท่านเป็นเชื้อสายราชวงศ์แห่งเอโดม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 15, 'เพราะอยู่มาเมื่อดาวิดอยู่ในเอโดม และโยอาบผู้บัญชาการกองทัพได้ขึ้นไปฝังผู้ที่ถูกฆ่า หลังจากเขาได้ฆ่าผู้ชายทุกคนในเอโดมเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 16, '(เพราะโยอาบและคนอิสราเอลทั้งสิ้นยังอยู่ที่นั่นหกเดือน จนกว่าเขาได้ฆ่าผู้ชายทุกคนในเอโดม)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 17, 'ฮาดัดได้หนีไปอียิปต์ พร้อมกับคนเอโดมบางคนผู้เป็นข้าราชการของบิดาของท่าน ครั้งนั้นฮาดัดยังเป็นเด็กเล็กๆอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 18, 'เขาทั้งหลายยกออกจากมีเดียนมายังปาราน และพาคนจากปารานมากับเขาและมาถึงอียิปต์ เฝ้าฟาโรห์กษัตริย์แห่งอียิปต์ ผู้ประทานเรือนหลังหนึ่งแก่เขา และกําหนดให้ได้รับปันเสบียงอาหาร และประทานที่ดินให้เขาด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 19, 'และฮาดัดเป็นที่โปรดปรานยิ่งในสายตาของฟาโรห์ ฟาโรห์จึงประทานน้องสาวของมเหสีของท่านเอง คือขนิษฐาของพระราชินีทาเปเนสให้เป็นภรรยาเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 20, 'และขนิษฐาของทาเปเนสก็ประสูติเกนูบัทให้ท่านเป็นบุตรชาย ผู้ซึ่งทาเปเนสให้หย่านมในวังของฟาโรห์ และเกนูบัทอยู่ในวังของฟาโรห์ในหมู่ราชโอรสของฟาโรห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 21, 'แต่เมื่อฮาดัดอยู่ในอียิปต์ได้ยินว่าดาวิดได้ล่วงลับไปอยู่กับบรรพบุรุษของพระองค์แล้ว และโยอาบผู้บัญชาการกองทัพก็สิ้นชีวิตแล้ว ฮาดัดจึงทูลฟาโรห์ว่า “ขอข้าพระองค์ทูลลาเพื่อข้าพระองค์จะกลับไปยังประเทศของข้าพระองค์เอง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 22, 'แต่ฟาโรห์ตรัสกับท่านว่า “ท่านอยู่กับเราขาดสิ่งใดหรือ ดูเถิด ท่านจึงเสาะหาที่จะกลับไปยังประเทศของท่าน” และท่านก็ทูลพระองค์ว่า “ไม่ขาดสิ่งใดพระเจ้าข้า แต่ขอให้ข้าพระองค์ไปเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 23, 'พระเจ้าได้ทรงให้ปฏิปักษ์เกิดขึ้นต่อสู้ท่านอีกคนหนึ่ง คือเรโซนบุตรชายของเอลียาดา ผู้ที่หนีไปจากฮาดัดเอเซอร์กษัตริย์แห่งโศบาห์เจ้านายของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 24, 'เมื่อดาวิดเข่นฆ่าชาวโศบาห์เขาก็รวบรวมผู้คนให้อยู่กับเขา กลายเป็นหัวหน้าของกองปล้น และเขาทั้งหลายก็ไปยังเมืองดามัสกัสอาศัยอยู่ที่นั่น และครอบครองเมืองดามัสกัส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 25, 'ท่านเป็นปฏิปักษ์ของอิสราเอลตลอดวันเวลาของซาโลมอน นอกจากเหตุร้ายที่ฮาดัดได้กระทํา และท่านเกลียดชังอิสราเอล และได้ปกครองอยู่เหนือซีเรีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 26, 'เยโรโบอัมบุตรชายเนบัท คนเอฟราอิม ชาวเมืองเศเรดาห์ข้าราชการคนหนึ่งของซาโลมอน มารดาชื่อเศรุวาห์เป็นหญิงม่าย ได้ยกมือขึ้นต่อสู้กษัตริย์ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 27, 'ต่อไปนี้เป็นสาเหตุที่ท่านยกมือขึ้นต่อสู้กษัตริย์ คือซาโลมอนทรงสร้างป้อมมิลโล และอุดช่องกําแพงนครของดาวิดราชบิดาของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 28, 'เยโรโบอัมเป็นทแกล้วทหาร เมื่อซาโลมอนทรงเห็นว่าชายหนุ่มคนนั้นเป็นคนขยัน พระองค์จึงให้ท่านดูแลเหนือแรงงานเกณฑ์ทั้งสิ้นของวงศ์วานโยเซฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 29, 'และอยู่มาในคราวนั้นเมื่อเยโรโบอัมออกไปจากกรุงเยรูซาเล็ม อาหิยาห์ผู้พยากรณ์ชาวชีโลห์ได้พบท่านที่กลางทาง อาหิยาห์สวมเสื้อใหม่ตัวหนึ่ง และคนทั้งสองก็อยู่ลําพังในทุ่งนา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 30, 'แล้วอาหิยาห์ก็จับเสื้อใหม่ที่สวมอยู่ฉีกออกเป็นสิบสองชิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 31, 'และท่านพูดกับเยโรโบอัมว่า “ท่านจงเอาไปสิบชิ้น เพราะพระเยโฮวาห์พระเจ้าแห่งอิสราเอลตรัสดังนี้ว่า ‘ดูเถิด เราจะฉีกอาณาจักรจากมือของซาโลมอน และจะให้เจ้าสิบตระกูล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 32, '(แต่เขาจะมีตระกูลหนึ่งเพื่อเห็นแก่ดาวิดผู้รับใช้ของเรา และเพื่อเห็นแก่เยรูซาเล็มเมืองซึ่งเราเลือกจากท่ามกลางตระกูลทั้งปวงของอิสราเอล)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 33, 'เพราะเขาทั้งหลายได้ทอดทิ้งเรา และได้นมัสการพระอัชโทเรท พระแม่เจ้าของชาวไซดอน เคโมชพระของโมอับ และมิลโคมพระของคนอัมโมน และมิได้ดําเนินในทางของเรา เพื่อจะกระทําสิ่งที่ถูกต้องในสายตาของเรา และรักษากฎเกณฑ์ของเรา และคําตัดสินของเรา อย่างกับดาวิดบิดาของเขาได้กระทํานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 34, 'ถึงกระนั้นก็ดี เราจะไม่เอาอาณาจักรทั้งหมดออกจากมือของเขา แต่เราจะกระทําให้เขาเป็นผู้ครอบครองอยู่ตลอดวันเวลาแห่งชีวิตของเขา เพราะเห็นแก่ดาวิดผู้รับใช้ของเราผู้ซึ่งเราได้เลือกไว้ เพราะเขาได้รักษาบัญญัติของเราและกฎเกณฑ์ของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 35, 'แต่เราจะเอาอาณาจักรออกจากมือบุตรชายของเขา และจะมอบให้เจ้าสิบตระกูล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 36, 'เรายังจะให้ตระกูลหนึ่งแก่บุตรชายของเขา เพื่อดาวิดผู้รับใช้ของเราจะมีประทีปดวงหนึ่งต่อหน้าเราในกรุงเยรูซาเล็มเสมอ เป็นเมืองซึ่งเราได้เลือกเพื่อประดิษฐานนามของเราไว้ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 37, 'เราจะเอาตัวเจ้า และเจ้าจะปกครองให้กว้างขวางตามชอบใจของเจ้า และเจ้าจะเป็นกษัตริย์เหนืออิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 38, 'และจะเป็นดังนี้ว่าถ้าเจ้าเชื่อฟังทุกสิ่งที่เราบัญชาแก่เจ้า และจะดําเนินในทางทั้งหลายของเรา และกระทําสิ่งที่ถูกต้องในสายตาของเรา โดยรักษากฎเกณฑ์ของเรา และบัญญัติของเราดังดาวิดผู้รับใช้ของเราได้กระทํา เราจะอยู่กับเจ้า และจะสร้างเจ้าให้เป็นราชวงศ์ที่มั่นคง ดังที่เราได้สร้างเพื่อดาวิดมาแล้ว และเราจะให้อิสราเอลแก่เจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 39, 'ด้วยเหตุนี้เราจะให้ความทุกข์ใจแก่เชื้อสายของดาวิด แต่ไม่เป็นนิตย์’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 40, 'ฉะนั้นซาโลมอนจึงทรงหาช่องจะประหารเยโรโบอัมเสีย แต่เยโรโบอัมได้ลุกขึ้นหนีเข้าไปในอียิปต์ ไปยังชิชักกษัตริย์อียิปต์ และอยู่ในอียิปต์จนถึงซาโลมอนสิ้นพระชนม์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 41, 'ส่วนพระราชกิจนอกนั้นของซาโลมอน และบรรดาสิ่งซึ่งพระองค์ทรงกระทํา และพระสติปัญญาของพระองค์มิได้บันทึกไว้ในหนังสือพระราชกิจของซาโลมอนหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 42, 'และเวลาที่ซาโลมอนทรงครอบครองในเยรูซาเล็มเหนืออิสราเอลทั้งสิ้นนั้น เป็นสี่สิบปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 43, 'และซาโลมอนก็ล่วงหลับไปอยู่กับบรรพบุรุษของพระองค์ และเขาฝังพระศพพระองค์ไว้ในนครของดาวิดราชบิดาของพระองค์ และเรโหโบอัมราชโอรสของพระองค์ก็ขึ้นครองแทน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 1, 'เรโหโบอัมได้ไปยังเมืองเชเคม เพราะอิสราเอลทั้งปวงได้มายังเชเคมเพื่อจะตั้งท่านให้เป็นกษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 2, 'และอยู่มาเมื่อเยโรโบอัมบุตรชายเนบัทได้ยินเรื่องนั้น เพราะท่านยังอยู่ในอียิปต์ (ที่ซึ่งท่านหนีไปจากพระพักตร์กษัตริย์ซาโลมอน เยโรโบอัมอาศัยอยู่ในอียิปต์)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 3, 'เขาทั้งหลายก็ใช้คนไปเรียกท่าน เยโรโบอัมกับชุมนุมชนอิสราเอลทั้งหมดได้มาทูลเรโหโบอัมว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 4, '“พระราชบิดาของพระองค์ได้กระทําให้แอกของข้าพระองค์หนักนัก เพราะฉะนั้นบัดนี้ขอทรงผ่อนการปรนนิบัติอย่างทุกข์หนักของพระราชบิดาของพระองค์ และแอกอันหนักของพระองค์เหนือข้าพระองค์ทั้งหลายให้เบาลงเสีย และข้าพระองค์ทั้งหลายจะปรนนิบัติพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 5, 'พระองค์ตรัสกับเขาว่า “จงกลับไปเสียสักสามวัน แล้วจึงมาหาเราอีก” ประชาชนจึงกลับไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 6, 'แล้วกษัตริย์เรโหโบอัมก็ทรงปรึกษากับบรรดาผู้เฒ่า ผู้อยู่งานประจําซาโลมอนราชบิดาของพระองค์ขณะเมื่อพระองค์ยังทรงพระชนม์อยู่ว่า “ท่านทั้งหลายจะแนะนําเราให้ตอบประชาชนนี้อย่างไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 7, 'เขาทั้งหลายทูลพระองค์ว่า “ถ้าพระองค์จะทรงเป็นผู้รับใช้ประชาชนนี้ในวันนี้และรับใช้พวกเขา และตรัสตอบคําดีแก่พวกเขา เขาทั้งหลายก็จะเป็นผู้รับใช้ของพระองค์เป็นนิตย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 8, 'แต่พระองค์ทรงทอดทิ้งคําปรึกษาซึ่งผู้เฒ่าถวายนั้นเสีย และไปปรึกษากับคนหนุ่มซึ่งเติบโตขึ้นมาพร้อมกับพระองค์ และอยู่งานประจําพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 9, 'และพระองค์ตรัสกับเขาทั้งหลายว่า “ท่านจะแนะนําเราอย่างไร เพื่อพวกเราจะตอบประชาชนนี้ ผู้ที่ทูลเราว่า ‘ขอทรงผ่อนแอกซึ่งพระราชบิดาของพระองค์วางอยู่เหนือข้าพระองค์ทั้งหลายให้เบาลง’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 10, 'และคนหนุ่มเหล่านั้นผู้ได้เติบโตมาพร้อมกับพระองค์ทูลพระองค์ว่า “พระองค์จงตรัสดังนี้แก่ประชาชนนี้ ผู้ทูลพระองค์ว่า ‘พระราชบิดาของพระองค์ได้กระทําให้แอกของข้าพระองค์ทั้งหลายหนัก แต่ขอพระองค์ทรงผ่อนแก่ข้าพระองค์ให้เบาลง’ นั้น พระองค์จงตรัสแก่เขาทั้งหลายอย่างนี้ว่า ‘นิ้วก้อยของเราก็หนากว่าเอวแห่งราชบิดาของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 11, 'ที่พระราชบิดาของเราวางแอกหนักบนท่านทั้งหลายก็ดีแล้ว เราจะเพิ่มให้แก่แอกของท่านทั้งหลายอีก พระราชบิดาของเราตีสอนท่านทั้งหลายด้วยไม้เรียว แต่เราจะตีสอนท่านทั้งหลายด้วยแส้แมงป่อง’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 12, 'เยโรโบอัมกับประชาชนทั้งปวงจึงเข้ามาเฝ้าเรโหโบอัมในวันที่สาม ดังที่กษัตริย์รับสั่งว่า “จงมาหาเราอีกในวันที่สาม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 13, 'และกษัตริย์ตรัสตอบประชาชนอย่างดุดัน ทรงทอดทิ้งคําปรึกษาซึ่งผู้เฒ่าได้ถวายนั้นเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 14, 'และตรัสกับเขาทั้งหลายตามคําปรึกษาของพวกคนหนุ่มว่า “พระราชบิดาของเราทําแอกของท่านทั้งหลายให้หนัก แต่เราจะเพิ่มให้แก่แอกของท่านทั้งหลายอีก พระราชบิดาของเราตีสอนท่านทั้งหลายด้วยไม้เรียว แต่เราจะตีสอนท่านทั้งหลายด้วยแส้แมงป่อง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 15, 'กษัตริย์จึงมิได้ฟังเสียงประชาชนเพราะเหตุการณ์นั้นเป็นมาแต่พระเยโฮวาห์ เพื่อพระองค์จะทรงกระทําให้พระวจนะของพระองค์ได้สําเร็จ ซึ่งพระเยโฮวาห์ตรัสโดยอาหิยาห์ชาวชีโลห์แก่เยโรโบอัมบุตรชายเนบัท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 16, 'และเมื่ออิสราเอลทั้งปวงเห็นว่ากษัตริย์มิได้ทรงฟังเขาทั้งหลาย ประชาชนก็ทูลตอบกษัตริย์ว่า “ข้าพระองค์ทั้งหลายมีส่วนอะไรในดาวิด ข้าพระองค์ทั้งหลายไม่มีส่วนมรดกในบุตรชายของเจสซี โอ อิสราเอลเอ๋ย กลับไปเต็นท์ของตนเถิด ข้าแต่ดาวิด จงดูแลราชวงศ์ของพระองค์เองเถิด” อิสราเอลจึงจากไปยังเต็นท์ของเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 17, 'แต่เรโหโบอัมทรงปกครองเหนือประชาชนอิสราเอล ผู้อาศัยอยู่ในหัวเมืองของยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 18, 'แล้วกษัตริย์เรโหโบอัมทรงใช้อาโดรัมนายงานเหนือแรงงานเกณฑ์ไป และอิสราเอลทั้งปวงก็เอาหินขว้างท่านถึงตาย แล้วกษัตริย์เรโหโบอัมก็ทรงรีบขึ้นรถรบของพระองค์ ทรงหนีไปยังกรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 19, 'อิสราเอลกบฏต่อราชวงศ์ของดาวิดจนทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 20, 'และอยู่มาเมื่ออิสราเอลทั้งปวงได้ยินว่าเยโรโบอัมได้กลับมาแล้ว เขาก็ใช้ให้ไปเชิญท่านมายังที่ประชุม แล้วก็ตั้งท่านให้เป็นกษัตริย์เหนืออิสราเอลทั้งปวง ไม่มีผู้ใดติดตามราชวงศ์ของดาวิด เว้นแต่ตระกูลยูดาห์เท่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 21, 'เมื่อเรโหโบอัมมายังกรุงเยรูซาเล็มแล้ว พระองค์ได้เรียกประชุมวงศ์วานยูดาห์ทั้งหมด และตระกูลเบนยามิน เป็นนักรบที่คัดเลือกแล้วหนึ่งแสนแปดหมื่นคน เพื่อจะสู้รบกับวงศ์วานอิสราเอล เพื่อจะเอาราชอาณาจักรคืนมาให้แก่เรโหโบอัมโอรสของซาโลมอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 22, 'แต่พระวจนะของพระเจ้ามายังเชไมอาห์คนของพระเจ้าว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 23, '“จงไปทูลเรโหโบอัมโอรสของซาโลมอนกษัตริย์แห่งยูดาห์ และบอกแก่วงศ์วานทั้งสิ้นของยูดาห์ และของเบนยามิน และแก่ประชาชนที่เหลืออยู่ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 24, '‘พระเยโฮวาห์ตรัสดังนี้ว่า เจ้าอย่าขึ้นไปสู้รบกับประชาชนอิสราเอลญาติพี่น้องของเจ้าเลย จงกลับไปยังบ้านของตนทุกคนเถิด เพราะสิ่งนี้เป็นมาจากเรา’” เหตุฉะนี้เขาจึงเชื่อฟังพระวจนะของพระเยโฮวาห์ และกลับไปบ้านเสียตามพระวจนะของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 25, 'แล้วเยโรโบอัมก็สร้างเมืองเชเคมในถิ่นเทือกเขาเอฟราอิม และอาศัยอยู่ที่นั่น และพระองค์ก็ออกไปจากที่นั่น ไปสร้างเมืองเปนูเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 26, 'และเยโรโบอัมรําพึงในใจว่า “คราวนี้ราชอาณาจักรจะหันกลับไปยังราชวงศ์ของดาวิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 27, 'ถ้าชนชาติเหล่านี้ขึ้นไปถวายเครื่องสัตวบูชาในพระนิเวศของพระเยโฮวาห์ที่กรุงเยรูซาเล็ม แล้วจิตใจของชนชาติเหล่านี้จะหันกลับไปยังเจ้านายของเขาทั้งหลาย คือหันไปยังเรโหโบอัมกษัตริย์แห่งยูดาห์ และเขาทั้งหลายจะฆ่าเราเสีย และกลับไปยังเรโหโบอัมกษัตริย์แห่งยูดาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 28, 'ดังนั้นกษัตริย์จึงทรงปรึกษา และได้ทรงสร้างลูกวัวสองตัวด้วยทองคํา และพระองค์ตรัสแก่ประชาชนว่า “ที่ท่านทั้งหลายขึ้นไปยังกรุงเยรูซาเล็มนานพออยู่แล้ว โอ อิสราเอลเอ๋ย จงดูพระของท่าน ดูเถิด พระองค์ผู้ทรงนําท่านทั้งหลายออกจากประเทศอียิปต์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 29, 'และพระองค์ก็ประดิษฐานไว้ที่เบธเอลรูปหนึ่ง และอีกรูปหนึ่งทรงประดิษฐานไว้ในเมืองดาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 30, 'และสิ่งนี้กลายเป็นความบาป เพราะว่าประชาชนได้ไปนมัสการรูปหนึ่ง คือที่เมืองดาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 31, 'แล้วพระองค์ได้ทรงสร้างนิเวศที่ปูชนียสถานสูง ทรงกําหนดตั้งปุโรหิตจากหมู่ประชาชนทั้งปวง ผู้มิได้เป็นคนเลวี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 32, 'และเยโรโบอัมทรงกําหนดเทศกาลเลี้ยงในวันที่สิบห้าของเดือนที่แปดเหมือนกับการเลี้ยงที่อยู่ในยูดาห์ และพระองค์ทรงถวายเครื่องสัตวบูชาบนแท่นบูชา พระองค์ทรงกระทําในเบธเอลดังนี้แหละ คือถวายเครื่องสัตวบูชาแก่รูปลูกวัวที่พระองค์ได้ทรงสร้างไว้นั้น และพระองค์ทรงสถาปนาปุโรหิตในเบธเอลประจําที่ปูชนียสถานสูงซึ่งพระองค์ทรงสร้างไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 33, 'พระองค์ทรงขึ้นไปยังแท่นบูชาซึ่งพระองค์ทรงสร้างไว้ที่เบธเอลในวันที่สิบห้าเดือนที่แปด ในเดือนซึ่งพระองค์ทรงดําริเอง และพระองค์ทรงกําหนดเทศกาลเลี้ยงสําหรับคนอิสราเอล และทรงถวายเครื่องบูชาบนแท่นและเผาเครื่องหอม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 1, 'และดูเถิด คนของพระเจ้าคนหนึ่งได้ออกมาจากยูดาห์โดยพระวจนะของพระเยโฮวาห์ไปยังที่เบธเอล เยโรโบอัมทรงยืนอยู่ที่แท่นเพื่อจะเผาเครื่องหอม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 2, 'และชายคนนั้นได้ร้องกล่าวโทษแท่นนั้นโดยพระวจนะของพระเยโฮวาห์ว่า “โอ แท่นบูชา แท่นบูชา พระเยโฮวาห์ตรัสดังนี้ว่า ‘ดูเถิด โอรสองค์หนึ่งจะประสูติมาในราชวงศ์ของดาวิดชื่อโยสิยาห์ และบนเจ้าแท่นนี้จะฆ่าปุโรหิตแห่งปูชนียสถานสูงผู้ซึ่งเผาเครื่องหอมบนเจ้า และเขาจะเผากระดูกคนบนเจ้า’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 3, 'และท่านก็ให้หมายสําคัญในวันเดียวกันนั้น กล่าวว่า “นี่เป็นหมายสําคัญที่พระเยโฮวาห์ได้ตรัสว่า ‘ดูเถิด เขาจะพังแท่นบูชาลงมา และมูลเถ้าซึ่งอยู่บนนั้นจะถูกเทออก’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 4, 'และอยู่มาเมื่อกษัตริย์เยโรโบอัมทรงสดับคํากล่าวของคนของพระเจ้า ซึ่งร้องกล่าวโทษแท่นนั้นที่เบธเอล พระองค์ก็เหยียดพระหัตถ์ออกจากที่แท่น กล่าวว่า “จงจับเขาไว้” และพระหัตถ์ของพระองค์ซึ่งเหยียดออกต่อเขานั้นก็เหี่ยวแห้งไป พระองค์จะชักกลับเข้าหาตัวอีกก็ไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 5, 'แท่นบูชาก็พังลงด้วย และมูลเถ้าก็ร่วงลงมาจากแท่น ตามหมายสําคัญซึ่งคนของพระเจ้าได้ให้ไว้โดยพระวจนะของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 6, 'และกษัตริย์ตรัสกับคนของพระเจ้าว่า “จงวิงวอนขอพระกรุณาแห่งพระพักตร์พระเยโฮวาห์พระเจ้าของท่าน ขอจงอธิษฐานเพื่อข้าพเจ้า ข้าพเจ้าจะชักมือกลับเข้าหาตัวได้อีก” และคนของพระเจ้าก็วิงวอนต่อพระเยโฮวาห์ และกษัตริย์ก็ทรงชักพระหัตถ์กลับเข้าหาพระองค์ได้อีกและเป็นเหมือนเดิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 7, 'และกษัตริย์ตรัสกับคนของพระเจ้าว่า “เชิญมาบ้านกับข้าพเจ้าเถิด และรับประทานด้วยกัน ข้าพเจ้าจะให้รางวัลแก่ท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 8, 'และคนของพระเจ้าทูลกษัตริย์ว่า “ถ้าท่านจะให้สักครึ่งราชสมบัติของท่าน ข้าพเจ้าจะไม่ไปกับท่าน และข้าพเจ้าจะไม่รับประทานขนมปังหรือดื่มน้ําในที่นี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 9, 'เพราะว่าพระวจนะของพระเยโฮวาห์บัญชาข้าพเจ้าไว้อย่างนั้นว่า ‘เจ้าอย่ากินขนมปังหรือดื่มน้ํา หรือกลับไปตามทางที่เจ้ามานั้น’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 10, 'ดังนั้นท่านจึงไปเสียอีกทางหนึ่ง และไม่กลับไปตามทางที่ท่านมายังเบธเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 11, 'มีผู้พยากรณ์แก่คนหนึ่งอาศัยอยู่ในเบธเอล และบุตรชายของเขาก็ได้มาบอกเขาถึงเรื่องราวทั้งสิ้นซึ่งคนของพระเจ้าได้กระทําในวันนั้นที่เบธเอล ถ้อยคําซึ่งท่านได้กล่าวแก่กษัตริย์ เขาทั้งหลายก็ได้เล่าให้บิดาของเขาฟังด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 12, 'และบิดาของเขาได้ถามเขาว่า “ท่านไปทางไหน” เพราะบุตรชายทั้งหลายของเขาได้เห็นทางซึ่งคนของพระเจ้าผู้มาจากยูดาห์ได้เดินไปนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 13, 'เขาจึงพูดกับบุตรชายของเขาว่า “จงผูกอานลาให้พ่อ” เขาทั้งหลายจึงผูกอานลาให้เขา แล้วเขาก็ขึ้นขี่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 14, 'เขาได้ไปตามคนของพระเจ้า และได้พบท่านนั่งอยู่ใต้ต้นโอ๊กต้นหนึ่ง เขาจึงพูดกับท่านว่า “ท่านเป็นคนของพระเจ้าซึ่งมาจากยูดาห์หรือ” ท่านก็ตอบว่า “ใช่แล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 15, 'เขาจึงตอบท่านว่า “เชิญมาบ้านกับข้าพเจ้าเถิด และมารับประทานอาหารบ้าง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 16, 'ท่านพูดว่า “ข้าพเจ้าจะกลับไปกับท่าน หรือเข้าไปพักกับท่านไม่ได้ ข้าพเจ้าจะไม่รับประทานอาหารหรือดื่มน้ํากับท่านในที่นี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 17, 'เพราะพระวจนะของพระเยโฮวาห์ตรัสกับข้าพเจ้าว่า ‘เจ้าอย่ารับประทานอาหารหรือดื่มน้ําที่นั่น หรือกลับโดยทางที่เจ้าได้มา’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 18, 'และเขาจึงพูดกับท่านว่า “ข้าพเจ้าก็เป็นผู้พยากรณ์อย่างที่ท่านเป็นนั้นด้วย มีทูตสวรรค์องค์หนึ่งมาบอกข้าพเจ้าโดยพระวจนะของพระเยโฮวาห์ว่า ‘จงนําเขากลับมากับเจ้ายังเรือนของเจ้า เพื่อเขาจะได้รับประทานอาหารและดื่มน้ํา’” แต่เขามุสาต่อท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 19, 'ดังนั้นท่านจึงไปกับเขา และได้รับประทานอาหารในเรือนของเขา และได้ดื่มน้ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 20, 'และต่อมาขณะที่พวกเขานั่งอยู่ที่โต๊ะ พระวจนะของพระเยโฮวาห์มายังผู้พยากรณ์ผู้ที่ได้นําท่านกลับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 21, 'และเขาร้องต่อคนของพระเจ้าผู้มาจากยูดาห์ว่า “พระเยโฮวาห์ตรัสดังนี้ว่า ‘เพราะเจ้าไม่เชื่อฟังพระโอษฐ์ของพระเยโฮวาห์ และมิได้รักษาพระบัญญัติซึ่งพระเยโฮวาห์พระเจ้าของเจ้าบัญชาเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 22, 'แต่เจ้าได้กลับมาและรับประทานอาหารและดื่มน้ําในที่ซึ่งพระเยโฮวาห์ตรัสกับเจ้าว่า “อย่ารับประทานอาหารหรือดื่มน้ํา” ศพของเจ้าจะมิได้ไปถึงอุโมงค์ของบรรพบุรุษของเจ้า’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 23, 'และอยู่มาหลังจากที่ท่านได้รับประทานอาหารและดื่มน้ําแล้ว เขาก็ผูกอานลาให้ผู้พยากรณ์ผู้ซึ่งเขาได้พากลับมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 24, 'และเมื่อท่านไป สิงโตก็ออกมาพบท่านที่ถนนและฆ่าท่านเสีย และศพของท่านก็ถูกทิ้งไว้ในถนน และลาตัวนั้นก็ยืนอยู่ข้างๆศพนั้น สิงโตก็ยืนอยู่ข้างๆศพด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 25, 'และดูเถิด มีคนผ่านไป และได้เห็นศพทิ้งอยู่ในถนน และสิงโตยืนอยู่ข้างศพนั้น เขาก็มาบอกกันในเมืองที่ที่ผู้พยากรณ์แก่อยู่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 26, 'และเมื่อผู้พยากรณ์ผู้ที่นําท่านกลับมาจากทางได้ยินเรื่องนั้น เขาพูดว่า “นั่นเป็นคนของพระเจ้าผู้ไม่เชื่อฟังพระวจนะของพระเยโฮวาห์ เพราะฉะนั้นพระเยโฮวาห์ได้ทรงมอบท่านไว้กับสิงโต ซึ่งได้ฉีกท่านและฆ่าท่านเสีย ตามคําซึ่งพระเยโฮวาห์ตรัสกับท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 27, 'เขาจึงพูดกับบุตรชายของเขาว่า “จงผูกอานลาให้พ่อ” แล้วเขาก็ผูกอานลาให้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 28, 'เขาจึงไปและพบศพนั้นทิ้งอยู่ในถนน และลากับสิงโตก็ยืนอยู่ข้างๆศพนั้น สิงโตมิได้กินศพนั้นหรือฉีกลานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 29, 'และผู้พยากรณ์ก็ยกศพคนของพระเจ้าและวางไว้บนลา นํากลับมายังเมืองของผู้พยากรณ์แก่ เพื่อไว้ทุกข์ให้และฝังท่านเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 30, 'และเขาวางศพนั้นในที่ฝังศพของตนเอง และเขาทั้งหลายก็ไว้ทุกข์ให้กล่าวว่า “อนิจจา พี่น้องเอ๋ย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 31, 'ต่อมาเมื่อได้ฝังท่านไว้แล้ว เขาจึงพูดกับบุตรชายของตนว่า “เมื่อเราตาย จงฝังเราไว้ในที่ฝังศพซึ่งฝังคนของพระเจ้าไว้นั้น จงวางกระดูกของเราไว้ข้างกระดูกของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 32, 'เพราะว่าคําพูดซึ่งท่านได้ร้องโดยพระวจนะของพระเยโฮวาห์กล่าวโทษแท่นบูชาในเบธเอล และต่อบรรดานิเวศแห่งปูชนียสถานสูงซึ่งอยู่ในหัวเมืองสะมาเรีย จะสําเร็จเป็นแน่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 33, 'ภายหลังสิ่งเหล่านี้ เยโรโบอัมมิได้หันกลับจากทางชั่วของพระองค์ แต่จากท่ามกลางประชาชนได้สถาปนาบางคนให้เป็นปุโรหิตประจําปูชนียสถานสูงนั้นอีก ผู้ใดที่พอใจเป็น พระองค์ก็แต่งตั้งเขาให้เป็นปุโรหิตประจําบรรดาปูชนียสถานสูง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 34, 'และสิ่งนี้กลายเป็นความบาปแก่ราชวงศ์เยโรโบอัม เพื่อจะตัดและทําลายราชวงศ์นั้นเสียจากพื้นแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 1, 'ครั้งนั้นอาบียาห์โอรสของเยโรโบอัมประชวร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 2, 'และเยโรโบอัมรับสั่งกับมเหสีของพระองค์ว่า “จงลุกขึ้นปลอมตัวของเธอ อย่าให้รู้ว่าเธอเป็นมเหสีของเยโรโบอัม และจงไปยังชีโลห์ ดูเถิด อาหิยาห์ผู้พยากรณ์อยู่ที่นั่น ผู้ได้กล่าวเรื่องฉันว่าฉันจะได้เป็นกษัตริย์เหนือชนชาตินี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 3, 'เธอจงเอาขนมปังสิบก้อน และขนมหวานบ้างและน้ําผึ้งไหหนึ่ง ไปหาท่าน ท่านจะบอกเธอว่าอะไรจะเกิดขึ้นกับเด็กนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 4, 'มเหสีของเยโรโบอัมก็กระทําดังนั้น พระนางลุกขึ้น เสด็จไปยังชีโลห์เสด็จมาถึงบ้านของอาหิยาห์ ฝ่ายอาหิยาห์มองไม่เห็น เพราะว่าตาของท่านแข็งด้วยอายุของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 5, 'พระเยโฮวาห์ตรัสกับอาหิยาห์ว่า “ดูเถิด มเหสีของเยโรโบอัมกําลังมาเพื่อจะถามเจ้าถึงเรื่องโอรสของเขา เพราะเด็กนั้นป่วย เจ้าจงบอกเธออย่างนี้ๆ เพราะเมื่อพระนางเสด็จเข้ามา พระนางก็แสร้งกระทําเป็นสตรีคนอื่น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 6, 'แต่เมื่ออาหิยาห์ได้ยินเสียงฝีพระบาทของพระนาง เมื่อพระนางเสด็จมาถึงประตู ท่านจึงพูดว่า “ขอเชิญพระมเหสีของเยโรโบอัมเสด็จเข้ามาข้างใน ไฉนพระองค์จึงทรงแสร้งกระทําเป็นคนอื่นเล่า เพราะข้าพระองค์ได้รับพระบัญชาให้ทูลข่าวอันน่าสลดใจแก่พระนาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 7, 'ขอเสด็จกลับไปทูลเยโรโบอัมว่า ‘พระเยโฮวาห์พระเจ้าแห่งอิสราเอลตรัสดังนี้ว่า เพราะเราได้เชิดชูเจ้าขึ้นจากประชาชน และได้กระทําให้เจ้าเป็นประมุขเหนืออิสราเอลประชาชนของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 8, 'และได้ฉีกราชอาณาจักรจากราชวงศ์ของดาวิดมาให้แก่เจ้า และถึงกระนั้นเจ้าก็ไม่เป็นเหมือนดาวิดผู้รับใช้ของเรา ผู้ได้รักษาบัญญัติทั้งหลายของเรา และติดตามเราด้วยสุดจิตใจของเขา กระทําสิ่งซึ่งเป็นที่ถูกต้องพอตาของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 9, 'แต่เจ้าได้กระทําชั่วยิ่งกว่าคนทั้งปวงที่อยู่ก่อนเจ้า และได้ไปสร้างพระอื่นและรูปหล่อและได้กระทําให้เราโกรธ และได้เหวี่ยงเราไว้เสียเบื้องหลังของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 10, 'เพราะฉะนั้น ดูเถิด เราจะนําเหตุร้ายมาเหนือราชวงศ์ของเยโรโบอัม และจะตัดคนที่ปัสสาวะรดกําแพงได้เสียจากเยโรโบอัม ทั้งคนที่ยังอยู่และเหลืออยู่ในอิสราเอล และจะผลาญคนที่เหลือในราชวงศ์เยโรโบอัมเสียอย่างสิ้นเชิง อย่างคนที่ขนมูลสัตว์ไปทิ้งจนหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 11, 'ผู้ใดในวงศ์เยโรโบอัมที่ตายในเมืองสุนัขจะกิน และผู้ใดที่ตายในทุ่ง นกในอากาศจะกิน เพราะพระเยโฮวาห์ทรงลั่นพระวาจาไว้’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 12, 'เพราะฉะนั้นขอเชิญเสด็จกลับไปยังพระตําหนักของพระนาง เมื่อพระบาทของพระองค์เข้าเมือง กุมารนั้นก็จะถึงแก่มรณา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 13, 'และอิสราเอลทั้งปวงจะไว้ทุกข์ให้เธอ และจะฝังศพเธอไว้ เพราะเธอผู้เดียวเท่านั้นในราชวงศ์เยโรโบอัมที่จะไปถึงหลุมศพ เพราะในราชวงศ์ของเยโรโบอัม ยังเห็นบางสิ่งในตัวเธอนั้นที่พอพระทัยพระเยโฮวาห์พระเจ้าแห่งอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 14, 'ยิ่งกว่านั้นอีก พระเยโฮวาห์จะทรงตั้งกษัตริย์อีกองค์หนึ่งเหนืออิสราเอลเพื่อพระองค์ ผู้ซึ่งจะตัดราชวงศ์ของเยโรโบอัมเสียในวันนี้ แต่นั่นอะไร ก็เป็นเวลานี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 15, 'เพราะพระเยโฮวาห์จะทรงตีอิสราเอล ดุจไม้อ้อสั่นอยู่ในน้ํา และจะทรงถอนรากอิสราเอลออกเสียจากแผ่นดินอันดีนี้ ซึ่งพระองค์ทรงยกให้แก่บรรพบุรุษของเขา และกระจายเขาไปฟากแม่น้ําข้างโน้น เพราะเขาทั้งหลายได้สร้างเสารูปเคารพของเขา เป็นเหตุให้พระเยโฮวาห์ทรงพระพิโรธ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 16, 'และพระองค์จะทรงมอบอิสราเอลไว้เพราะบาปทั้งหลายของเยโรโบอัม ซึ่งเขาได้กระทําบาปและกระทําให้อิสราเอลทําบาปด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 17, 'แล้วมเหสีของเยโรโบอัมทรงลุกขึ้นเสด็จออกไป และมาถึงเมืองทีรซาห์ และเมื่อพระนางเสด็จถึงธรณีทวาร กุมารก็ถึงแก่มรณา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 18, 'และอิสราเอลทั้งปวงก็ฝังศพเธอและไว้ทุกข์ให้เธอ ตามพระวจนะของพระเยโฮวาห์ ซึ่งพระองค์ตรัสโดยอาหิยาห์ผู้พยากรณ์ผู้รับใช้ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 19, 'ฝ่ายราชกิจนอกนั้นของเยโรโบอัมกล่าวถึงว่าพระองค์ทรงทําศึก และทรงครอบครองอย่างไรนั้น ดูเถิด ก็บันทึกไว้ในหนังสือพงศาวดารแห่งกษัตริย์ประเทศอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 20, 'เวลาที่เยโรโบอัมครอบครองนั้นเป็นยี่สิบสองปี และพระองค์ก็ล่วงหลับไปอยู่กับบรรพบุรุษของพระองค์ และนาดับราชโอรสของพระองค์ก็ขึ้นครองแทน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 21, 'ฝ่ายเรโหโบอัมราชโอรสของซาโลมอนทรงครอบครองอยู่ในยูดาห์ เมื่อเรโหโบอัมขึ้นครองนั้น มีพระชนมายุสี่สิบเอ็ดพรรษา และทรงครองในเยรูซาเล็มสิบเจ็ดปี เป็นนครซึ่งพระเยโฮวาห์ได้ทรงเลือกจากบรรดาตระกูลอิสราเอล เพื่อจะสถาปนาพระนามของพระองค์ที่นั่น พระราชมารดาของกษัตริย์มีพระนามว่านาอามาห์คนอัมโมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 22, 'และยูดาห์ได้กระทําชั่วในสายพระเนตรของพระเยโฮวาห์ และเขาทั้งหลายได้ยั่วยุให้พระองค์หวงแหนด้วยบาปทั้งหลายที่เขาได้กระทํา ซึ่งมากกว่าบาปทั้งสิ้นที่บรรพบุรุษของเขาได้กระทําเสียอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 23, 'เพราะเขาได้สร้างปูชนียสถานสูงด้วย และเสาศักดิ์สิทธิ์ และเสารูปเคารพสําหรับตัวเขาไว้บนเนินเขาสูงๆทุกเนิน และใต้ต้นไม้เขียวทุกต้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 24, 'และมีกะเทยในแผ่นดินนั้นด้วย และเขาได้กระทําตามบรรดาสิ่งที่น่าสะอิดสะเอียนของประชาชาติทั้งหลาย ซึ่งพระเยโฮวาห์ทรงขับไล่ออกไปให้พ้นหน้าประชาชนอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 25, 'ต่อมาในปีที่ห้าแห่งกษัตริย์เรโหโบอัม ชิชักกษัตริย์อียิปต์ได้ขึ้นมารบกรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 26, 'ท่านได้เก็บทรัพย์สมบัติในพระนิเวศของพระเยโฮวาห์ และทรัพย์สมบัติในพระราชวังของกษัตริย์ ท่านได้เก็บไปเสียทุกอย่าง และท่านได้เก็บโล่ทองคําซึ่งซาโลมอนได้สร้างนั้นไปหมดด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 27, 'และกษัตริย์เรโหโบอัมได้กระทําโล่ทองเหลืองแทนไว้ และมอบไว้ในมือของพวกทหารรักษาพระองค์ผู้เฝ้าทวารพระราชวัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 28, 'เมื่อกษัตริย์เสด็จเข้าไปยังพระนิเวศของพระเยโฮวาห์ ทหารรักษาพระองค์ก็ถือโล่ออก แล้วนํากลับไปเก็บไว้ในห้องทหารรักษาพระองค์ตามเดิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 29, 'ฝ่ายพระราชกิจนอกนั้นของเรโหโบอัม และสรรพสิ่งที่ทรงกระทํา มิได้บันทึกไว้ในหนังสือพงศาวดารแห่งกษัตริย์ประเทศยูดาห์หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 30, 'มีสงครามระหว่างเรโหโบอัมและเยโรโบอัมเสมอไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 31, 'และเรโหโบอัมก็ทรงล่วงหลับไปอยู่กับบรรพบุรุษของพระองค์ และเขาก็ฝังไว้กับบรรพบุรุษของพระองค์ในนครดาวิด พระนามของพระราชมารดาของพระองค์คือนาอามาห์คนอัมโมน และอาบียัมราชโอรสก็ขึ้นครองแทน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 1, 'ในปีที่สิบแปดแห่งรัชกาลกษัตริย์เยโรโบอัมบุตรชายเนบัท อาบียัมได้ขึ้นครองเหนือประเทศยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 2, 'พระองค์ทรงครองในเยรูซาเล็มสามปี พระนามของพระราชมารดาคือมาอาคาห์ธิดาของอาบีชาโลม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 3, 'พระองค์ดําเนินตามการบาปทุกอย่างซึ่งราชบิดาของพระองค์ได้กระทําต่อพระพักตร์พระองค์ และพระทัยของพระองค์ก็ไม่บริสุทธิ์ต่อพระเยโฮวาห์พระเจ้าของพระองค์ ดังพระทัยของดาวิดบรรพบุรุษของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 4, 'อย่างไรก็ดีเพื่อทรงเห็นแก่ดาวิดพระเยโฮวาห์พระเจ้าของพระองค์ทรงประทานประทีปแก่พระองค์ในเยรูซาเล็ม คือทรงตั้งราชโอรสแทน และเพื่อทรงสถาปนาเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 5, 'เพราะว่าดาวิดทรงกระทําสิ่งที่ถูกต้องในสายพระเนตรของพระเยโฮวาห์ และมิได้ทรงหันไปจากสิ่งใด ซึ่งพระเยโฮวาห์ทรงบัญชาแก่พระองค์ตลอดพระชนม์ชีพของพระองค์ นอกจากเรื่องอุรีอาห์คนฮิตไทต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 6, 'มีศึกระหว่างเรโหโบอัมกับเยโรโบอัมตลอดพระชนม์ชีพของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 7, 'ราชกิจนอกนั้นของอาบียัมและสรรพสิ่งซึ่งพระองค์ทรงกระทํา มิได้บันทึกไว้ในหนังสือพงศาวดารแห่งกษัตริย์ประเทศยูดาห์หรือ และมีการศึกระหว่างอาบียัมและเยโรโบอัม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 8, 'และอาบียัมก็ล่วงหลับไปอยู่กับบรรพบุรุษและเขาทั้งหลายก็ฝังพระศพพระองค์ไว้ในนครดาวิด และอาสาราชโอรสของพระองค์ก็ขึ้นครองแทน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 9, 'ในปีที่ยี่สิบแห่งรัชกาลเยโรโบอัมกษัตริย์ของอิสราเอล อาสาได้ขึ้นครองเหนือประเทศยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 10, 'และพระองค์ทรงครองอยู่ในกรุงเยรูซาเล็มสี่สิบเอ็ดปี พระราชมารดาของพระองค์คือมาอาคาห์ธิดาของอาบีชาโลม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 11, 'และอาสาทรงกระทําสิ่งที่ถูกต้องในสายพระเนตรพระเยโฮวาห์ ดั่งดาวิดบรรพบุรุษของพระองค์ได้ทรงกระทํานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 12, 'พระองค์ทรงกวาดล้างกะเทยเสียจากแผ่นดิน และรื้อถอนรูปเคารพทั้งสิ้น ซึ่งบรรพบุรุษได้กระทําไว้นั้นเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 13, 'และพระองค์ทรงถอดมาอาคาห์พระราชมารดาเสียจากตําแหน่งพระราชชนนี เพราะพระนางมีรูปเคารพน่าเกลียดน่าชังสร้างไว้ในเสารูปเคารพ และอาสาทรงฟันรูปเคารพของพระนางลง และทรงเผาเสียที่ลําธารขิดโรน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 14, 'แต่มิได้ทรงรื้อปูชนียสถานสูงเหล่านั้น ถึงอย่างนั้นพระทัยของอาสาก็บริสุทธิ์ต่อพระเยโฮวาห์ตลอดรัชสมัยของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 15, 'พระองค์ทรงนําเงิน ทองคําและเครื่องใช้ต่างๆ อันเป็นสัญญาถวายของราชบิดาของพระองค์ และของสัญญาถวายของพระองค์เองมายังพระนิเวศของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 16, 'มีการศึกระหว่างอาสาและบาอาชากษัตริย์แห่งอิสราเอล ตลอดสมัยของพระองค์ทั้งสอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 17, 'บาอาชากษัตริย์แห่งอิสราเอลได้ทรงยกไปต่อสู้กับยูดาห์ และได้สร้างเมืองรามาห์ เพื่อมิให้ผู้ใดเข้าไปเฝ้าหรือออกมาจากอาสากษัตริย์แห่งยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 18, 'แล้วอาสาทรงนําเงินและทองคํา ซึ่งเหลืออยู่ในทรัพย์สินแห่งพระนิเวศของพระเยโฮวาห์ และทรัพย์สินของพระราชวัง มอบไว้ในมือของข้าราชการของพระองค์ และกษัตริย์อาสาทรงใช้เขาไปเฝ้าเบนฮาดัดโอรสของทับริมโมน ผู้เป็นโอรสของเฮซีโอนกษัตริย์แห่งซีเรีย ผู้อยู่ในเมืองดามัสกัสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 19, '“มีพันธมิตรระหว่างข้าพระองค์และพระองค์ ระหว่างพระชนกของข้าพระองค์และพระชนกของพระองค์ ดูเถิด ข้าพระองค์ได้ส่งบรรณาการเป็นเงินและทองคํามายังพระองค์ ขอพระองค์เสด็จไปเลิกพันธมิตรกับบาอาชากษัตริย์แห่งอิสราเอลเสีย เพื่อเขาจะได้ยกทัพกลับไปเสียจากข้าพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 20, 'แล้วเบนฮาดัดก็ทรงฟังกษัตริย์อาสาและส่งผู้บังคับบัญชาทหารของพระองค์ไปรบหัวเมืองอิสราเอล และได้โจมตีเมืองอิโยน ดาน อาเบลเบธมาอาคาห์ และหมดท้องถิ่นคินเนเรท และหมดดินแดนนัฟทาลี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 21, 'และอยู่มาเมื่อบาอาชาทรงได้ยินแล้ว พระองค์ก็ทรงหยุดสร้างเมืองรามาห์ และพระองค์ประทับที่เมืองทีรซาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 22, 'แล้วกษัตริย์อาสาทรงประกาศไปทั่วยูดาห์ไม่เว้นผู้ใดเลย เขาทั้งหลายก็มารื้อเอาหินของเมืองรามาห์ และไม้ของเมืองนั้นซึ่งบาอาชาทรงสร้างค้างอยู่ กษัตริย์อาสาก็ทรงเอามาสร้างเมืองเกบาแห่งเบนยามินและเมืองมิสปาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 23, 'พระราชกิจนอกนั้นของอาสา ทั้งยุทธพลังทั้งสิ้นของพระองค์ และบรรดาสิ่งซึ่งพระองค์ทรงกระทํา และหัวเมืองซึ่งพระองค์ทรงสร้าง มิได้บันทึกไว้ในหนังสือพงศาวดารของกษัตริย์ประเทศยูดาห์หรือ แต่เมื่อทรงพระชราแล้วก็เกิดพระโรคขึ้นที่พระบาท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 24, 'และอาสาก็ทรงล่วงหลับไปอยู่กับบรรพบุรุษของพระองค์ และเขาฝังไว้กับบรรพบุรุษของพระองค์ที่ในนครดาวิดราชบิดาของพระองค์ และเยโฮชาฟัทราชโอรสของพระองค์ก็ขึ้นครองแทน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 25, 'นาดับราชโอรสของเยโรโบอัมได้เริ่มครองเหนืออิสราเอลในปีที่สองแห่งรัชกาลอาสากษัตริย์แห่งยูดาห์ และพระองค์ทรงครองเหนืออิสราเอลสองปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 26, 'พระองค์ทรงกระทําชั่วในสายพระเนตรของพระเยโฮวาห์ และทรงดําเนินในทางแห่งราชบิดาของพระองค์ และในบาปซึ่งพระองค์ทรงกระทําให้อิสราเอลทําบาปด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 27, 'บาอาชาบุตรชายอาหิยาห์วงศ์วานของอิสสาคาร์ คิดกบฏต่อพระองค์ และบาอาชาทรงประหารพระองค์เสียที่กิบเบโธน ซึ่งเป็นแดนเมืองของฟีลิสเตีย เพราะนาดับและคนอิสราเอลทั้งสิ้นกําลังล้อมเมืองกิบเบโธนอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 28, 'ดังนั้นบาอาชาจึงสําเร็จโทษพระองค์เสียในปีที่สามแห่งรัชกาลอาสากษัตริย์แห่งยูดาห์และขึ้นครองแทน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 29, 'ต่อมาพอพระองค์ทรงเป็นกษัตริย์ก็ทรงประหารราชวงศ์ของเยโรโบอัมเสียสิ้น ไม่มีผู้ใดของเยโรโบอัมรอดมาสักคนเดียวเลย พระองค์ทําลายเสียสิ้น ตามพระดํารัสแห่งพระเยโฮวาห์ซึ่งพระองค์ตรัสโดยอาหิยาห์ชาวชีโลห์ผู้รับใช้ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 30, 'เป็นเพราะบาปทั้งหลายซึ่งเยโรโบอัมได้ทรงกระทํา และซึ่งพระองค์ได้ทรงกระทําให้อิสราเอลทําบาปด้วย และเพราะพระองค์ทรงกระทําให้พระเยโฮวาห์พระเจ้าของอิสราเอลทรงพระพิโรธ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 31, 'ส่วนพระราชกิจนอกนั้นของนาดับ และบรรดาสิ่งซึ่งพระองค์ทรงกระทํา มิได้บันทึกไว้ในหนังสือพงศาวดารของกษัตริย์แห่งอิสราเอลหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 32, 'มีศึกระหว่างอาสาและบาอาชากษัตริย์แห่งอิสราเอลตลอดสมัยของพระองค์ทั้งสอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 33, 'ในปีที่สามแห่งรัชกาลอาสากษัตริย์แห่งยูดาห์ บาอาชาบุตรชายอาหิยาห์ได้ทรงเริ่มครอบครองเหนืออิสราเอลทั้งสิ้นที่เมืองทีรซาห์ และได้ทรงครอบครองอยู่ยี่สิบสี่ปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 34, 'พระองค์ทรงกระทําชั่วในสายพระเนตรของพระเยโฮวาห์ และดําเนินในมรรคาของเยโรโบอัม และในบาปซึ่งพระองค์ทรงกระทําให้อิสราเอลทําบาปด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 1, 'พระวจนะของพระเยโฮวาห์ได้มาถึงเยฮูบุตรชายฮานานีกล่าวโทษบาอาชาว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 2, '“ในเมื่อเราได้เชิดชูเจ้าขึ้นมาจากผงคลี และกระทําให้เจ้าเป็นประมุขเหนืออิสราเอลประชาชนของเรา และเจ้าได้ดําเนินตามมรรคาของเยโรโบอัม และได้กระทําให้อิสราเอลประชาชนของเราทําบาปด้วย กระทําให้เราโกรธด้วยบาปของเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 3, 'ดูเถิด เราจะกวาดล้างผู้อยู่ภายหลังบาอาชาและผู้อยู่ภายหลังราชวงศ์ของเขาเสียอย่างสิ้นเชิง และกระทําให้ราชวงศ์ของเจ้าเหมือนกับราชวงศ์ของเยโรโบอัมบุตรเนบัท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 4, 'ผู้ใดในราชวงศ์บาอาชาที่ตายในเมืองสุนัขจะกิน และผู้ใดที่ตายในทุ่งนา นกในอากาศจะกิน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 5, 'ส่วนพระราชกิจนอกนั้นของบาอาชา และบรรดาสิ่งที่พระองค์ได้กระทํา และยุทธพลังของพระองค์ มิได้บันทึกไว้ในหนังสือพงศาวดารแห่งกษัตริย์ประเทศอิสราเอลหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 6, 'และบาอาชาก็ล่วงหลับไปอยู่กับบรรพบุรุษของพระองค์ และเขาก็ฝังไว้ที่เมืองทีรซาห์ และเอลาห์ราชโอรสก็ขึ้นครองแทนพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 7, 'นอกจากนั้นพระวจนะของพระเยโฮวาห์ได้มาถึงโดยผู้พยากรณ์เยฮูบุตรชายฮานานีกล่าวโทษบาอาชาและเชื้อวงศ์ของพระองค์ ทั้งเรื่องความชั่วทั้งสิ้นซึ่งพระองค์กระทําในสายพระเนตรของพระเยโฮวาห์ ซึ่งเป็นการยั่วยุให้พระองค์ทรงกริ้วโกรธด้วยพระราชกิจจากพระหัตถ์ของพระองค์ ในการที่เหมือนกับราชวงศ์ของเยโรโบอัม และเพราะพระองค์ได้ทรงฆ่าเยโรโบอัมด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 8, 'ในปีที่ยี่สิบหกแห่งรัชกาลอาสากษัตริย์ของยูดาห์ เอลาห์โอรสบาอาชาทรงเริ่มขึ้นครองเหนืออิสราเอลในเมืองทีรซาห์ และทรงครอบครองอยู่สองปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 9, 'แต่ศิมรีข้าราชการของพระองค์ ผู้บัญชาการกองรถรบของพระองค์ครึ่งหนึ่ง ได้คิดกบฏต่อพระองค์เมื่อพระองค์ประทับที่เมืองทีรซาห์ พระองค์ทรงดื่มจนเมาในเรือนของอารซาผู้ครอบครองราชสํานักในทีรซาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 10, 'ศิมรีได้เข้ามาฟันพระองค์ล้มลง และประหารพระองค์เสีย ในปีที่ยี่สิบเจ็ดแห่งรัชกาลอาสากษัตริย์ของยูดาห์แล้วก็ขึ้นครองแทนพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 11, 'และอยู่มาเมื่อพระองค์ทรงเริ่มครองราชย์ ทันทีที่พระองค์เสด็จประทับบนราชบัลลังก์ พระองค์ทรงสังหารราชวงศ์ของบาอาชาเสียสิ้น พระองค์มิได้ทรงเหลือไว้สักคนหนึ่งที่ปัสสาวะรดกําแพงได้ ไม่ว่าจะเป็นญาติหรือมิตรสหายของบาอาชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 12, 'ศิมรีทรงทําลายราชวงศ์ของบาอาชาทั้งหมดดังนี้แหละ ตามพระวจนะของพระเยโฮวาห์ ซึ่งพระองค์ตรัสโดยเยฮูผู้พยากรณ์กล่าวโทษบาอาชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 13, 'เหตุด้วยบาปทั้งสิ้นของบาอาชา และบาปของเอลาห์ราชโอรสของพระองค์ ซึ่งพระองค์ทั้งสองได้กระทําบาป และซึ่งพระองค์ทั้งสองได้กระทําให้ชนอิสราเอลทําบาปด้วย กระทําให้พระเยโฮวาห์พระเจ้าแห่งอิสราเอลทรงกริ้วด้วยเรื่องความหยิ่งยโสของพระองค์ทั้งสองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 14, 'ส่วนพระราชกิจนอกนั้นของเอลาห์ และบรรดาสิ่งซึ่งพระองค์ทรงกระทํา มิได้บันทึกไว้ในหนังสือพงศาวดารแห่งกษัตริย์ประเทศอิสราเอลหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 15, 'ในปีที่ยี่สิบเจ็ดแห่งรัชกาลอาสากษัตริย์ประเทศยูดาห์ ศิมรีทรงครอบครองเจ็ดวัน ณ เมืองทีรซาห์ ฝ่ายพวกพลได้ตั้งค่ายรบเมืองกิบเบโธน ซึ่งเป็นของคนฟีลิสเตีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 16, 'และพวกพลซึ่งตั้งค่ายอยู่นั้นได้ยินเขากล่าวกันว่า “ศิมรีได้กบฏและท่านได้ปลงพระชนม์กษัตริย์เสียแล้ว” เพราะฉะนั้นอิสราเอลทั้งปวงก็สถาปนาอมรี ผู้บัญชาการกองทัพให้เป็นกษัตริย์เหนืออิสราเอลในวันนั้นที่ในค่าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 17, 'อมรีจึงเสด็จขึ้นไปจากกิบเบโธน และอิสราเอลทั้งปวงก็ขึ้นไปด้วย เขาทั้งหลายเข้าล้อมเมืองทีรซาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 18, 'และต่อมาเมื่อศิมรีทรงเห็นว่าเมืองนั้นถูกยึดแล้วก็เสด็จเข้าไปในพระราชวังแห่งราชสํานักและทรงเผาราชสํานักคลอก พระองค์เองสิ้นพระชนม์เสียในกองไฟนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 19, 'เหตุด้วยบาปทั้งหลายซึ่งพระองค์ทรงกระทําไว้ คือทรงกระทําชั่วในสายพระเนตรของพระเยโฮวาห์ ดําเนินอยู่ในมรรคาของเยโรโบอัม และด้วยเหตุบาปซึ่งพระองค์ทรงกระทํา คือทรงกระทําให้อิสราเอลทําบาปด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 20, 'ส่วนพระราชกิจนอกนั้นของศิมรีและการกบฏซึ่งพระองค์ทรงกระทํา มิได้บันทึกไว้ในหนังสือพงศาวดารแห่งกษัตริย์อิสราเอลหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 21, 'แล้วชนชาติอิสราเอลก็แบ่งออกเป็นสองส่วน ครึ่งหนึ่งของประชาชนติดตามทิบนีบุตรชายกีนัท เชิญท่านให้เป็นกษัตริย์ และอีกครึ่งหนึ่งติดตามอมรี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 22, 'แต่ประชาชนผู้ติดตามอมรีได้รบชนะประชาชนผู้ติดตามทิบนีบุตรชายกีนัท ทิบนีจึงสิ้นชีวิตและอมรีก็ขึ้นเป็นกษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 23, 'ในปีที่สามสิบเอ็ดแห่งรัชกาลอาสากษัตริย์แห่งยูดาห์ อมรีได้เริ่มต้นครอบครองอยู่เหนืออิสราเอล และทรงครอบครองอยู่สิบสองปี พระองค์ทรงครอบครองในเมืองทีรซาห์หกปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 24, 'พระองค์ทรงซื้อภูเขาสะมาเรียจากเชเมอร์เงินสองตะลันต์ และพระองค์ทรงเสริมภูเขานั้นให้เป็นป้อม และทรงขนานนามเมืองที่พระองค์ทรงสร้างนั้นว่าสะมาเรีย ตามชื่อของเชเมอร์ผู้เป็นเจ้าของภูเขานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 25, 'อมรีได้ทรงกระทําสิ่งที่ชั่วในสายพระเนตรพระเยโฮวาห์ และทรงกระทําเลวทรามกว่าบรรดากษัตริย์ที่อยู่มาก่อนพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 26, 'เพราะว่าพระองค์ทรงดําเนินตามมรรคาทั้งสิ้นของเยโรโบอัมบุตรชายเนบัท และตามบาปซึ่งพระองค์กระทําให้อิสราเอลทําบาปด้วย กระทําให้พระเยโฮวาห์พระเจ้าแห่งอิสราเอลทรงพระพิโรธด้วยความหยิ่งยโสของเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 27, 'ส่วนพระราชกิจนอกนั้นของอมรีซึ่งพระองค์ทรงกระทํา และยุทธพลังซึ่งพระองค์ทรงสําแดง มิได้บันทึกไว้ในหนังสือพงศาวดารแห่งกษัตริย์ประเทศอิสราเอลหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 28, 'และอมรีก็ล่วงหลับไปอยู่กับบรรพบุรุษของพระองค์ และเขาฝังไว้ในสะมาเรีย และอาหับราชโอรสของพระองค์ก็ขึ้นครองแทนพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 29, 'ในปีที่สามสิบแปดแห่งรัชกาลอาสากษัตริย์ของยูดาห์ อาหับราชโอรสของอมรีได้เริ่มครอบครองเหนืออิสราเอล และอาหับราชโอรสของอมรีได้ครองเหนืออิสราเอลในเมืองสะมาเรียยี่สิบสองปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 30, 'และอาหับโอรสของอมรีได้กระทําชั่วในสายพระเนตรของพระเยโฮวาห์มากยิ่งเสียกว่าบรรดากษัตริย์ที่อยู่ก่อนพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 31, 'และอยู่มาประหนึ่งว่าการที่พระองค์ดําเนินในบาปทั้งหลายของเยโรโบอัมบุตรชายเนบัทนั้นเป็นสิ่งเล็กน้อย พระองค์ทรงรับเยเซเบลพระราชธิดาของเอ็ทบาอัลกษัตริย์ของชาวไซดอนมาเป็นมเหสี และไปปรนนิบัติพระบาอัล และนมัสการพระนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 32, 'พระองค์ทรงสร้างแท่นบูชาพระบาอัลในพระนิเวศพระบาอัล ซึ่งพระองค์ได้ทรงสร้างไว้ในเมืองสะมาเรีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 33, 'และอาหับทรงสร้างเสารูปเคารพ อาหับทรงกระทําการที่กระทําให้พระเยโฮวาห์พระเจ้าแห่งอิสราเอลทรงพระพิโรธ มากยิ่งกว่าบรรดากษัตริย์แห่งอิสราเอลซึ่งอยู่มาก่อนพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 34, 'ในรัชกาลของพระองค์ฮีเอลชาวเบธเอลได้สร้างเมืองเยรีโค ท่านได้วางรากเมืองนั้นโดยต้องเสียอาบีรัมบุตรหัวปีของท่าน และตั้งประตูเมืองโดยต้องเสียเสกุบบุตรสุดท้องของท่าน ตามพระวจนะของพระเยโฮวาห์ ซึ่งพระองค์ตรัสโดยโยชูวาบุตรชายนูน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 1, 'ฝ่ายเอลียาห์ชาวทิชบีผู้ซึ่งตั้งอาศัยอยู่ในกิเลอาด ได้ทูลอาหับว่า “พระเยโฮวาห์พระเจ้าแห่งอิสราเอลผู้ซึ่งข้าพระองค์ปฏิบัติทรงพระชนม์อยู่แน่ฉันใด จะไม่มีน้ําค้างหรือฝนในปีเหล่านี้ นอกจากตามคําของข้าพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 2, 'แล้วพระวจนะของพระเยโฮวาห์มายังท่านว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 3, '“จงออกไปจากที่นี่และหันไปทางตะวันออก และซ่อนตัวอยู่ที่ข้างลําธารเครีท ซึ่งอยู่ฟากแม่น้ําจอร์แดนข้างนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 4, 'เจ้าจะดื่มน้ําจากลําธาร และเราได้บัญชาให้นกกาเลี้ยงเจ้าที่นั่น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 5, 'ท่านจึงไปและกระทําตามพระวจนะของพระเยโฮวาห์ ท่านไปอาศัยอยู่ที่ข้างลําธารเครีท ซึ่งอยู่ฟากแม่น้ําจอร์แดนข้างนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 6, 'และนกกาก็นําขนมปังและเนื้อมาให้ท่านในเวลาเช้า และนําขนมปังและเนื้อมาในเวลาเย็น และท่านก็ดื่มน้ําจากลําธาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 7, 'และต่อมาภายหลังลําธารก็แห้ง เพราะไม่มีฝนในแผ่นดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 8, 'และพระวจนะของพระเยโฮวาห์มายังท่านว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 9, '“ลุกขึ้นไปยังเมืองศาเรฟัทเถิด ซึ่งขึ้นแก่เมืองไซดอน และอาศัยอยู่ที่นั่น ดูเถิด เราได้บัญชาหญิงม่ายคนหนึ่งที่นั่นให้เลี้ยงเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 10, 'ท่านจึงลุกขึ้นไปยังเมืองศาเรฟัท และเมื่อมาถึงประตูเมือง ดูเถิด หญิงม่ายคนหนึ่งที่นั่นกําลังเก็บฟืน ท่านจึงเรียกนางว่า “ขอน้ําเล็กน้อยใส่ภาชนะมาให้ฉัน เพื่อฉันจะได้ดื่มน้ํา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 11, 'และขณะเมื่อนางจะไปเอาน้ํามา ท่านก็เรียกนางแล้วบอกว่า “ขอนําอาหารใส่มือมาให้ฉันสักหน่อยหนึ่ง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 12, 'และนางตอบว่า “พระเยโฮวาห์พระเจ้าของท่านทรงพระชนม์อยู่แน่ฉันใด ดิฉันไม่มีอะไรที่ปิ้งเสร็จ มีแต่แป้งสักกํามือหนึ่งในหม้อ และน้ํามันเล็กน้อยที่ในไห ดูเถิด ดิฉันกําลังเก็บฟืนสองท่อนเพื่อจะเข้าไปทําสําหรับตัวดิฉันและบุตรชายของดิฉัน เพื่อเราจะได้กินแล้วก็จะตาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 13, 'และเอลียาห์บอกนางว่า “อย่ากลัวเลย จงไปทําตามที่เจ้าพูด แต่จงทําขนมก้อนเล็กให้ฉันก่อน แล้วเอามาให้ฉัน ภายหลังจึงทําสําหรับตัวเจ้าและบุตรชายของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 14, 'เพราะพระเยโฮวาห์พระเจ้าของอิสราเอลตรัสดังนี้ว่า ‘แป้งในหม้อนั้นจะไม่หมดและน้ํามันในไหนั้นจะไม่ขาด จนกว่าจะถึงวันที่พระเยโฮวาห์ทรงส่งฝนลงมายังพื้นดิน’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 15, 'นางก็ไปกระทําตามคําของเอลียาห์ แล้วนาง ตัวท่านและครอบครัวของนางก็รับประทานอยู่หลายวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 16, 'แป้งในหม้อก็ไม่หมด น้ํามันในไหก็ไม่ขาด ตามพระวจนะของพระเยโฮวาห์ซึ่งตรัสทางเอลียาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 17, 'และอยู่มาภายหลังเหตุการณ์เหล่านี้ บุตรชายของหญิงคนนั้นผู้เป็นเจ้าของบ้านก็ล้มป่วย อาการป่วยนั้นก็สาหัส จนไม่มีลมหายใจเหลืออยู่แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 18, 'นางจึงกล่าวแก่เอลียาห์ว่า “โอ คนของพระเจ้า เจ้าข้า ฉันมีเรื่องอะไรเกี่ยวข้องกับท่าน ท่านได้มาหาฉันเพื่อฟื้นให้ทรงระลึกถึงความผิดของฉัน และกระทําให้บุตรชายของฉันตายหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 19, 'และท่านก็พูดกับนางว่า “เอาบุตรชายของเจ้ามาให้ฉันเถิด” ท่านก็นําเขาไปจากอกของนางอุ้มขึ้นไปที่ห้องชั้นบนที่ท่านอาศัยอยู่ และวางเขาไว้บนที่นอนของท่านเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 20, 'และท่านร้องทูลพระเยโฮวาห์ว่า “โอ ข้าแต่พระเยโฮวาห์พระเจ้าของข้าพระองค์ พระองค์ทรงนําเหตุร้ายมาถึงหญิงม่ายนี้ที่ข้าพระองค์อาศัยอยู่ด้วยทีเดียวหรือ โดยที่ทรงประหารบุตรชายของนางเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 21, 'แล้วท่านก็เหยียดตัวลงทับเด็กนั้นสามครั้ง และร้องทูลพระเยโฮวาห์ว่า “โอ ข้าแต่พระเยโฮวาห์พระเจ้าของข้าพระองค์ ขอชีวิตของเด็กคนนี้มาเข้าในตัวเขาอีก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 22, 'และพระเยโฮวาห์ทรงฟังเสียงของเอลียาห์ และชีวิตของเด็กนั้นมาเข้าในตัวเขาอีก และเขาก็ฟื้นขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 23, 'และเอลียาห์ก็อุ้มเด็กนั้น นําลงมาจากห้องชั้นบนเข้าไปในเรือน และมอบเขาให้แก่มารดาของเด็ก และเอลียาห์บอกว่า “ดูซิ บุตรของเจ้ายังมีชีวิตอยู่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 24, 'และหญิงนั้นพูดกับเอลียาห์ว่า “คราวนี้ดิฉันทราบแล้วว่า ท่านเป็นคนของพระเจ้า และพระวจนะของพระเยโฮวาห์ซึ่งอยู่ในปากของท่านเป็นความจริง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 1, 'และอยู่ต่อมาหลายวัน พระวจนะของพระเยโฮวาห์มาถึงเอลียาห์ในปีที่สามว่า “ไปซี และแสดงตัวของเจ้าต่ออาหับ และเราจะส่งฝนมาเหนือพื้นดิน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 2, 'เอลียาห์ก็ไปแสดงตัวต่ออาหับ การกันดารอาหารนั้นสาหัสมากในสะมาเรีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 3, 'และอาหับรับสั่งเรียกโอบาดีห์ผู้เป็นอธิบดีกรมวัง (ฝ่ายโอบาดีห์นั้นเกรงกลัวพระเยโฮวาห์ยิ่งนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 4, 'และเมื่อเยเซเบลขจัดผู้พยากรณ์ของพระเยโฮวาห์ออกไป โอบาดีห์ได้นําผู้พยากรณ์หนึ่งร้อยคนซ่อนไว้ตามถ้ําแห่งละห้าสิบคน และเลี้ยงเขาทั้งหลายด้วยขนมปังและน้ํา)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 5, 'และอาหับรับสั่งโอบาดีห์ว่า “จงไปให้ทั่วพื้นแผ่นดินไปหาธารน้ําพุ และไปให้ทั่วทุกลําธาร ชะรอยเราจะพบหญ้าและรักษาชีวิตม้าและล่อให้คงอยู่ได้ และไม่ต้องสูญเสียสัตว์ไปหมด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 6, 'ดังนั้นพวกเขาก็แบ่งดินแดนกันเพื่อจะออกไปค้น อาหับเสด็จไปทางหนึ่ง ฝ่ายโอบาดีห์ไปอีกทางหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 7, 'เมื่อโอบาดีห์กําลังไปตามทาง ดูเถิด เอลียาห์ได้พบเขา และโอบาดีห์ก็จําท่านได้จึงซบหน้าลงพูดว่า “เอลียาห์ เจ้านายของข้าพเจ้า เป็นตัวท่านเองจริงหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 8, 'และท่านก็ตอบเขาว่า “ตัวฉันเอง จงไปบอกเจ้านายของท่านว่า ‘ดูเถิด เอลียาห์อยู่ที่นี่’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 9, 'และเขากล่าวว่า “ข้าพเจ้าได้กระทําผิดประการใด ท่านจึงจะมอบผู้รับใช้ของท่านไว้ในพระหัตถ์ของอาหับให้ประหารข้าพเจ้าเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 10, 'พระเยโฮวาห์พระเจ้าของท่านทรงพระชนม์อยู่แน่ฉันใด ไม่มีประชาชาติหรือราชอาณาจักรใด ที่เจ้านายของข้าพเจ้ามิได้ส่งคนไปเสาะหาท่าน และเมื่อเขาทั้งหลายกราบทูลว่า ‘เขาไม่อยู่ที่นี่ พระเจ้าข้า’ พระองค์ก็ให้ประชาชาติหรือราชอาณาจักรปฏิญาณว่าเขาทั้งหลายมิได้พบท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 11, 'และคราวนี้ท่านกล่าวว่า ‘จงไปบอกเจ้านายของท่านว่า “ดูเถิด เอลียาห์อยู่ที่นี่”’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 12, 'อยู่มาพอข้าพเจ้าไปจากท่านแล้ว พระวิญญาณของพระเยโฮวาห์จะมาพาท่านไป ณ ที่ใดข้าพเจ้าก็ไม่ทราบ ฉะนั้นเมื่อข้าพเจ้าไปทูลอาหับ และพระองค์หาท่านไม่พบ พระองค์ก็จะทรงประหารข้าพเจ้าเสีย ถึงแม้ว่าข้าพเจ้าผู้รับใช้ของท่านยําเกรงพระเยโฮวาห์ตั้งแต่หนุ่มๆมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 13, 'ไม่มีผู้ใดเรียนเจ้านายของข้าพเจ้าดอกหรือว่า ข้าพเจ้าได้กระทําสิ่งใดเมื่อเยเซเบลประหารผู้พยากรณ์ของพระเยโฮวาห์เสีย และข้าพเจ้าได้ซ่อนผู้พยากรณ์หนึ่งร้อยคนของพระเยโฮวาห์ไว้ตามถ้ําแห่งละห้าสิบคน และเลี้ยงเขาด้วยขนมปังและน้ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 14, 'และคราวนี้ท่านบอกว่า ‘จงไปบอกเจ้านายของท่านว่า “ดูเถิด เอลียาห์อยู่ที่นี่”’ แล้วพระองค์จะทรงประหารข้าพเจ้าเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 15, 'และเอลียาห์กล่าวว่า “พระเยโฮวาห์จอมโยธาผู้ซึ่งข้าพเจ้าปฏิบัติอยู่ทรงพระชนม์อยู่แน่ฉันใด ข้าพเจ้าจะแสดงตัวของข้าพเจ้าแก่อาหับในวันนี้แน่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 16, 'โอบาดีห์จึงไปเฝ้าอาหับและทูลพระองค์ อาหับก็เสด็จไปพบเอลียาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 17, 'และอยู่มาเมื่ออาหับทอดพระเนตรเห็นเอลียาห์ อาหับก็ตรัสกับท่านว่า “นี่ตัวเจ้าหรือ เจ้าผู้ทําความลําบากให้อิสราเอล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 18, 'และท่านจึงทูลว่า “ข้าพระองค์มิได้กระทําความลําบากแก่อิสราเอล แต่พระองค์ได้กระทํา และราชวงศ์บิดาของพระองค์ เพราะว่าพวกพระองค์ได้ทอดทิ้งพระบัญญัติของพระเยโฮวาห์ และติดตามพระบาอัล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 19, 'เพราะฉะนั้นบัดนี้ขอทรงสั่งให้บรรดาชนอิสราเอลมาพบข้าพระองค์ที่ภูเขาคารเมล ทั้งผู้พยากรณ์ของพระบาอัลสี่ร้อยห้าสิบคนนั้น และผู้พยากรณ์ของเสารูปเคารพสี่ร้อยคนนั้น ผู้ซึ่งรับประทานที่โต๊ะเสวยของพระนางเยเซเบล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 20, 'อาหับจึงทรงส่งไปยังคนอิสราเอลทั้งปวง และชุมนุมผู้พยากรณ์ที่ภูเขาคารเมล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 21, 'และเอลียาห์ก็เข้ามาใกล้ประชาชนทั้งปวงกล่าวว่า “ท่านทั้งหลายจะขยักขย่อนอยู่ระหว่างสองฝ่ายนี้นานสักเท่าใด ถ้าพระเยโฮวาห์ทรงเป็นพระเจ้าจงติดตามพระองค์ แต่ถ้าพระบาอัลเป็น ก็จงตามท่านไปเถิด” และประชาชนไม่ตอบท่านสักคําเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 22, 'แล้วเอลียาห์พูดกับประชาชนว่า “ตัวข้าพเจ้า คือข้าพเจ้าแต่ผู้เดียวเป็นผู้พยากรณ์ของพระเยโฮวาห์ที่เหลืออยู่ แต่ผู้พยากรณ์พระบาอัลมีสี่ร้อยห้าสิบคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 23, 'ขอให้เขามอบวัวผู้แก่เราสองตัว แล้วขอให้เขาทั้งหลายเลือกวัวเป็นของเขาตัวหนึ่งฟันเป็นท่อนๆ วางไว้บนกองฟืนแต่อย่าใส่ไฟ และข้าพเจ้าจะเตรียมวัวผู้อีกตัวหนึ่งนั้นวางไว้บนฟืน และไม่ใส่ไฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 24, 'และท่านทั้งหลายจงร้องออกพระนามพระของท่าน และข้าพเจ้าจะร้องออกพระนามพระเยโฮวาห์ พระเจ้าองค์ที่ทรงตอบด้วยไฟ พระองค์นั้นแหละทรงเป็นพระเจ้า” และประชาชนทั้งปวงก็ตอบว่า “อย่างที่พูดก็ดีแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 25, 'แล้วเอลียาห์พูดกับผู้พยากรณ์ของพระบาอัลว่า “จงเลือกวัวผู้ตัวหนึ่งสําหรับท่านและตระเตรียมเสียก่อน เพราะพวกท่านมากคนด้วยกัน จงร้องออกพระนามพระของท่าน แต่อย่าใส่ไฟ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 26, 'เขาทั้งหลายก็เอาวัวผู้ที่เขานํามาให้และเขาทั้งหลายก็จัดเตรียมและร้องออกพระนามพระบาอัล ตั้งแต่เวลาเช้าจนเที่ยงกล่าวว่า “โอ ข้าแต่พระบาอัล ขอสดับพวกข้าพเจ้าเถิด” แต่ก็ไม่มีเสียงและไม่มีใครตอบ และเขาก็โขยกเขยกอยู่รอบแท่นซึ่งเขาได้สร้างขึ้นนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 27, 'ครั้นถึงเวลาเที่ยงเอลียาห์ก็เย้ยเขาทั้งหลายว่า “ร้องให้ดังๆซี เพราะท่านเป็นพระองค์หนึ่ง ท่านกําลังสนทนาอยู่ หรือท่านกําลังแอบซ่อนตัวอยู่ หรือท่านไปเที่ยว หรือชะรอยท่านกําลังหลับอยู่และจะต้องปลุก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 28, 'เขาทั้งหลายก็ร้องเสียงดัง และเชือดเฉือนตัวเองตามธรรมเนียมของเขาด้วยมีดและหลาว จนเลือดไหลพุ่งออกมาตามตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 29, 'และต่อมาเมื่อผ่านเที่ยงวันไปแล้ว เขาก็ทํานายจนถึงเวลาถวายบูชาตอนเย็น แต่ไม่มีเสียง ไม่มีใครตอบ ไม่มีใครฟัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 30, 'แล้วเอลียาห์พูดกับประชาชนทั้งปวงว่า “จงเข้ามาใกล้ข้าพเจ้า” และประชาชนทั้งปวงก็เข้ามาใกล้ท่าน และท่านก็ซ่อมแท่นบูชาของพระเยโฮวาห์ที่ถูกทําลายลงนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 31, 'เอลียาห์นําศิลาสิบสองก้อนมาตามจํานวนตระกูลของบุตรชายของยาโคบ ผู้ซึ่งพระวจนะของพระเยโฮวาห์มาถึงว่า “อิสราเอลจะเป็นชื่อของเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 32, 'และท่านได้สร้างแท่นบูชาด้วยศิลานั้นในพระนามของพระเยโฮวาห์ และท่านได้ขุดร่องรอบแท่นใหญ่พอจุเมล็ดพืชได้สองถัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 33, 'และท่านก็วางฟืนไว้เป็นระเบียบ และฟันวัวผู้นั้นเป็นท่อนๆ และวางไว้บนกองฟืน และท่านกล่าวว่า “จงเติมน้ําให้เต็มสี่ไห และเทลงบนเครื่องเผาบูชา และบนกองฟืน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 34, 'และท่านกล่าวว่า “จงกระทําครั้งที่สอง” และเขาก็กระทําครั้งที่สอง และท่านกล่าวว่า “จงกระทําครั้งที่สาม” และเขาก็กระทําครั้งที่สาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 35, 'และน้ําไหลรอบแท่นบูชา และท่านใส่น้ําเต็มร่อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 36, 'และอยู่มาเมื่อถึงเวลาถวายบูชาตอนเย็น เอลียาห์ผู้พยากรณ์ก็เข้ามาใกล้ทูลว่า “ข้าแต่พระเยโฮวาห์พระเจ้าแห่งอับราฮัม อิสอัคและอิสราเอล ขอให้ทราบเสียทั่วกันในวันนี้ว่า พระองค์คือพระเจ้าในอิสราเอล และข้าพระองค์เป็นผู้รับใช้ของพระองค์ และข้าพระองค์ได้กระทําบรรดาสิ่งเหล่านี้ตามพระดํารัสของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 37, 'ขอทรงฟังข้าพระองค์ โอ ข้าแต่พระเยโฮวาห์ ขอทรงฟังข้าพระองค์ เพื่อชนชาตินี้จะทราบว่า พระองค์คือพระเยโฮวาห์พระเจ้า และพระองค์ทรงหันจิตใจของเขาทั้งหลายกลับมาอีก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 38, 'แล้วไฟของพระเยโฮวาห์ก็ตกลงมาและไหม้เครื่องเผาบูชา และฟืนและหิน และผงคลีและเลียน้ําซึ่งอยู่ในร่อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 39, 'และเมื่อประชาชนทั้งปวงได้เห็น เขาก็ซบหน้าลงและร้องว่า “พระเยโฮวาห์พระองค์ทรงเป็นพระเจ้า พระเยโฮวาห์พระองค์ทรงเป็นพระเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 40, 'และเอลียาห์บอกเขาว่า “จงจับผู้พยากรณ์ของพระบาอัล อย่าให้หนีไปได้สักคนเดียว” และเขาทั้งหลายก็ไปจับเขามา และเอลียาห์ก็นําเขาลงไปที่ลําธารคีโชนและฆ่าเขาเสียที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 41, 'เอลียาห์ทูลอาหับว่า “ขอเชิญเสด็จขึ้นไปเสวยและดื่มเถิด เพราะมีเสียงฝนกระหึ่มมา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 42, 'อาหับก็เสด็จขึ้นไปเสวยและดื่ม และเอลียาห์ก็ขึ้นไปที่ยอดภูเขาคารเมล ท่านก็โน้มตัวลงถึงดิน ซบหน้าระหว่างเข่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 43, 'และท่านสั่งคนใช้ของท่านว่า “จงลุกขึ้นมองไปทางทะเล” เขาก็ลุกขึ้นมองและตอบว่า “ไม่มีอะไรเลย” และท่านบอกว่า “จงไปดูอีกเจ็ดครั้ง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 44, 'และอยู่มาเมื่อถึงครั้งที่เจ็ดเขาบอกว่า “ดูเถิด มีเมฆก้อนหนึ่งเล็กเท่าฝ่ามือคนขึ้นมาจากทะเล” และท่านก็บอกว่า “จงไปทูลอาหับว่า ‘ขอทรงเตรียมราชรถและเสด็จลงไปเพื่อพระองค์จะไม่ติดฝน’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 45, 'และอยู่มาอีกครู่หนึ่งท้องฟ้าก็มืดไปด้วยเมฆและลม และมีฝนหนัก อาหับก็ทรงรถเสด็จไปยังเมืองยิสเรเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 46, 'และพระหัตถ์ของพระเยโฮวาห์ทรงสถิตอยู่บนเอลียาห์ และท่านก็คาดเอวของท่านไว้ และวิ่งขึ้นหน้าอาหับไปถึงทางเข้าเมืองยิสเรเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 1, 'อาหับจึงบอกเยเซเบลตามการทั้งสิ้นซึ่งเอลียาห์ได้กระทํา และเรื่องที่ท่านได้ฆ่าผู้พยากรณ์ทั้งหมดเสียด้วยดาบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 2, 'แล้วเยเซเบลก็รับสั่งให้ผู้สื่อสารไปหาเอลียาห์ว่า “ถ้าพรุ่งนี้เวลานี้ เรามิได้กระทําชีวิตของเจ้าให้เหมือนอย่างชีวิตของคนเหล่านั้นแล้ว ก็ให้พระทั้งหลายลงโทษเรา และให้หนักยิ่งกว่า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 3, 'เมื่อท่านทราบแล้วก็ลุกขึ้นหนีไปเอาชีวิตรอด และมาถึงเบเออร์เชบาเขตประเทศยูดาห์ และละคนใช้ของท่านไว้ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 4, 'แต่ตัวท่านเองก็เดินเข้าถิ่นทุรกันดารไปเป็นระยะทางวันหนึ่งมานั่งอยู่ที่ใต้ต้นไม้จําพวกสนจูนิเปอร์ และท่านทูลขอให้ตัวท่านตายเสียที ว่า “พอแล้วพระองค์เจ้าข้า โอ ข้าแต่พระเยโฮวาห์ บัดนี้ขอเอาชีวิตของข้าพระองค์ไปเสีย เพราะข้าพระองค์ก็ไม่ดีไปกว่าบรรพบุรุษของข้าพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 5, 'และท่านก็นอนลงหลับอยู่ใต้ต้นไม้จําพวกสนจูนิเปอร์ ดูเถิด มีทูตสวรรค์องค์หนึ่งมาถูกต้องท่าน และพูดกับท่านว่า “ลุกขึ้นรับประทานซี”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 6, 'และท่านก็มองดู ดูเถิด ตรงที่ศีรษะของท่านมีขนมปังที่ปิ้งบนก้อนหินร้อนและมีไหน้ําใบหนึ่ง ท่านก็รับประทานและดื่ม และนอนลงอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 7, 'และทูตสวรรค์ของพระเยโฮวาห์ก็มาอีกเป็นครั้งที่สอง ถูกต้องท่านแล้วว่า “ลุกขึ้นรับประทานซี เพราะว่าทางเดินนั้นเกินกําลังของท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 8, 'และท่านก็ลุกขึ้นรับประทานและดื่ม และเดินไปด้วยกําลังของอาหารนั้นสี่สิบวันสี่สิบคืนถึงโฮเรบภูเขาของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 9, 'ที่นั่นท่านมาถึงถ้ําแห่งหนึ่งก็เข้าพักอยู่ และดูเถิด พระวจนะของพระเยโฮวาห์มาถึงท่าน และพระองค์ตรัสกับท่านว่า “เอลียาห์เอ๋ย เจ้าทําอะไรอยู่ที่นี่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 10, 'ท่านทูลว่า “ข้าพระองค์ร้อนรนเพื่อพระเยโฮวาห์พระเจ้าจอมโยธายิ่งนัก เพราะประชาชนอิสราเอลได้ทอดทิ้งพันธสัญญาของพระองค์ พังแท่นบูชาของพระองค์ลงเสีย และประหารผู้พยากรณ์ของพระองค์เสียด้วยดาบ และข้าพระองค์ ข้าพระองค์แต่ผู้เดียวเหลืออยู่ และเขาทั้งหลายแสวงหาชีวิตของข้าพระองค์เพื่อจะเอาไปเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 11, 'และพระองค์ตรัสว่า “จงออกไปเถิด ไปยืนอยู่บนภูเขาต่อพระพักตร์พระเยโฮวาห์” และดูเถิด พระเยโฮวาห์ทรงผ่านไป และลมใหญ่อันแรงกล้าได้พัดพังภูเขา และทําให้หินแตกเป็นก้อนๆต่อพระพักตร์พระเยโฮวาห์ แต่พระเยโฮวาห์มิได้สถิตในลมนั้น ภายหลังลมก็แผ่นดินไหว แต่พระเยโฮวาห์หาทรงสถิตในแผ่นดินไหวนั้นไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 12, 'ภายหลังแผ่นดินไหวก็เกิดไฟ แต่พระเยโฮวาห์หาทรงสถิตในไฟนั้นไม่ ภายหลังไฟก็มีเสียงเบาๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 13, 'และเมื่อเอลียาห์ได้ยิน ท่านก็เอาผ้าคลุมหน้าไว้ ออกไปยืนอยู่ที่ปากถ้ํา และดูเถิด มีเสียงมาถึงท่านว่า “เอลียาห์เอ๋ย เจ้าทําอะไรอยู่ที่นี่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 14, 'ท่านทูลว่า “ข้าพระองค์ร้อนรนเพื่อพระเยโฮวาห์พระเจ้าจอมโยธายิ่งนัก เพราะว่าประชาชนอิสราเอลได้ทอดทิ้งพันธสัญญาของพระองค์ พังแท่นบูชาของพระองค์ลงเสีย และประหารผู้พยากรณ์ของพระองค์เสียด้วยดาบ และข้าพระองค์ ข้าพระองค์แต่ผู้เดียวเหลืออยู่ และเขาทั้งหลายแสวงหาชีวิตของข้าพระองค์เพื่อจะเอาไปเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 15, 'และพระเยโฮวาห์ตรัสกับท่านว่า “ไปเถอะ จงกลับไปตามทางของเจ้าถึงถิ่นทุรกันดารดามัสกัส และเมื่อเจ้าไปถึงแล้ว เจ้าจงเจิมฮาซาเอลไว้ให้เป็นกษัตริย์เหนือประเทศซีเรีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 16, 'และเยฮูบุตรนิมซีนั้น เจ้าจงเจิมให้เป็นกษัตริย์เหนืออิสราเอล และเอลีชาบุตรชาฟัทชาวอาเบลเมโฮลาห์ เจ้าจงเจิมตั้งไว้ให้เป็นผู้พยากรณ์แทนเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 17, 'และต่อมาผู้ที่รอดจากดาบของฮาซาเอล เยฮูจะฆ่าเสีย และผู้ที่รอดจากดาบของเยฮู เอลีชาจะฆ่าเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 18, 'แต่เรายังมีเหลือเจ็ดพันคนไว้ในอิสราเอล คือทุกเข่าซึ่งมิได้คุกลงต่อพระบาอัล และทุกปากซึ่งมิได้จุบรูปนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 19, 'ท่านก็ออกไปจากที่นั่นพบเอลีชาบุตรชายชาฟัท ผู้กําลังไถนาอยู่ด้วยวัวสิบสองคู่เดินอยู่ข้างหน้าและท่านอยู่กับวัวคู่ที่สิบสอง เอลียาห์ก็ผ่านไปทิ้งเสื้อคลุมลงบนท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 20, 'ท่านก็ละวัวเหล่านั้นวิ่งตามเอลียาห์ไปและกล่าวว่า “ขอให้ข้าพเจ้าไปจุบลาบิดามารดาของข้าพเจ้าก่อน และข้าพเจ้าจะติดตามท่านไป” เอลียาห์จึงกล่าวกับเอลีชาว่า “กลับไปเถิด เพราะฉันได้ทําอะไรแก่ท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 21, 'และเอลีชาก็กลับจากติดตามเอลียาห์จับวัวคู่นั้นฆ่าเสียเอาเครื่องแอกต้มเนื้อวัว และให้แก่ประชาชนและเขาก็รับประทาน แล้วเอลีชาก็ลุกขึ้นตามเอลียาห์ไปและปรนนิบัติท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 1, 'เบนฮาดัดกษัตริย์ซีเรียได้ประชุมกองทัพทั้งปวงของท่าน มีกษัตริย์สามสิบสององค์ขึ้นกับท่าน ทั้งม้าและรถรบ และท่านก็ขึ้นไปล้อมสะมาเรีย สู้รบกับเมืองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 2, 'และท่านได้ส่งผู้สื่อสารเข้าไปในเมืองหาอาหับกษัตริย์อิสราเอล กล่าวแก่พระองค์ว่า “เบนฮาดัดว่าดังนี้ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 3, '‘เงินและทองคําของท่านเป็นของเรา บรรดาภรรยาและเด็กๆ ที่ดีที่สุดของท่านก็เป็นของเราด้วย’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 4, 'และกษัตริย์แห่งอิสราเอลทรงตอบไปว่า “โอ ข้าแต่กษัตริย์ เจ้านายของข้าพเจ้า ดังที่ท่านว่ามานั่นแหละ ข้าพเจ้าเป็นของท่าน ทั้งที่ข้าพเจ้ามีอยู่นั้นด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 5, 'บรรดาผู้สื่อสารได้กลับมาอีกกล่าวว่า “เบนฮาดัดกล่าวดังนี้ว่า ‘ข้าพเจ้าส่งข่าวมายังท่านว่า “จงส่งเงินและทองคําของท่าน ภรรยาและเด็กของท่านไปให้ข้าพเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 6, 'แต่ข้าพเจ้าจะส่งข้าราชการของข้าพเจ้าไปหาท่านพรุ่งนี้ประมาณเวลานี้ เขาทั้งหลายจะค้นวังของท่าน ทั้งบ้านเรือนข้าราชการของท่าน สิ่งใดที่เป็นที่ชอบตาของท่าน เขาจะหยิบเอาไป’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 7, 'แล้วกษัตริย์แห่งอิสราเอลก็เรียกประชุมพวกผู้ใหญ่ทั้งปวงของแผ่นดินตรัสว่า “ขอตรองดูเถิด ดูว่าชายผู้นี้หาช่องก่อความลําบาก เพราะเขาให้คนมารับเมียและลูกของฉัน ทั้งเงินและทองคําของฉัน และฉันก็มิได้ปฏิเสธเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 8, 'บรรดาผู้ใหญ่และประชาชนทั้งสิ้นก็ทูลพระองค์ว่า “ขออย่าทรงฟังหรือทรงยินยอมพ่ะย่ะค่ะ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 9, 'พระองค์จึงรับสั่งแก่ผู้สื่อสารของเบนฮาดัดว่า “จงไปทูลกษัตริย์ เจ้านายของข้าพเจ้าว่า ‘บรรดาสิ่งที่ท่านเอาจากผู้รับใช้ของท่านในครั้งแรกนั้น ข้าพเจ้าจะกระทําตาม แต่สิ่งนี้ข้าพเจ้าปฏิบัติตามไม่ได้’” และผู้สื่อสารก็จากไปและกลับมารายงาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 10, 'เบนฮาดัดส่งข่าวกลับมาว่า “ถ้าผงคลีแห่งสะมาเรียจะพอแก่คนที่ติดตามข้าพเจ้ามาสักคนละหยิบมือหนึ่ง ก็ขอให้พระทั้งหลายลงโทษข้าพเจ้าและให้หนักยิ่งกว่า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 11, 'และกษัตริย์แห่งอิสราเอลทรงตอบไปว่า “ขอทูลท่านว่า ‘ขอท่านผู้ที่สวมเกราะ อย่าอวดอ้างอย่างผู้ที่ถอดเกราะแล้วเลย’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 12, 'ต่อมาเมื่อเบนฮาดัดได้ยินข่าวนี้ขณะที่ดื่มอยู่กับบรรดากษัตริย์ทั้งหลายที่ในทับอาศัย ท่านก็สั่งข้าราชการของท่านว่า “จงเข้าประจําที่” และเขาทั้งหลายก็เข้าประจําที่เพื่อต่อสู้กับเมืองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 13, 'ดูเถิด ผู้พยากรณ์คนหนึ่งเข้ามาใกล้อาหับกษัตริย์แห่งอิสราเอลทูลว่า “พระเยโฮวาห์ตรัสดังนี้ว่า เจ้าเห็นกองทัพใหญ่นี้หรือ ดูเถิด เราจะมอบไว้ในมือของเจ้าในวันนี้ เจ้าจะได้รู้ว่าเราคือพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 14, 'และอาหับตรัสว่า “ทรงใช้ใครทํา” เขาทูลว่า “พระเยโฮวาห์ตรัสดังนี้ว่า ด้วยมือของมหาดเล็กของเจ้านายประจําจังหวัดทั้งหลาย” แล้วพระองค์ตรัสว่า “ใครจะเริ่มรบ” เขาทูลตอบว่า “พระองค์พ่ะย่ะค่ะ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 15, 'พระองค์จึงทรงจัดมหาดเล็กของเจ้านายประจําจังหวัดเหล่านั้นซึ่งมีสองร้อยสามสิบสองคนด้วยกัน และภายหลังทรงจัดพลทั้งหมดคือบรรดาคนอิสราเอลรวมพลเจ็ดพันคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 16, 'เขาทั้งหลายยกออกไปในเวลาเที่ยงวัน ฝ่ายเบนฮาดัดกําลังดื่มเมาอยู่ในทับอาศัย ทั้งท่านและกษัตริย์อีกสามสิบสององค์ที่ช่วยท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 17, 'พวกมหาดเล็กของเจ้านายประจําจังหวัดได้ยกออกไปก่อน เบนฮาดัดก็ส่งออกไป เขาทั้งหลายรายงานท่านว่า “มีคนยกออกมาจากสะมาเรีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 18, 'ท่านจึงว่า “ถ้าเขาออกมาด้วยสันติจงจับเขามาเป็นๆ หรือถ้าเขาออกมาทําศึกจงจับเขามาเป็นๆ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 19, 'คนเหล่านี้จึงออกไปจากเมืองคือพวกมหาดเล็กของเจ้านายประจําจังหวัด และกองทัพซึ่งติดตามคนเหล่านี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 20, 'และต่างก็ฆ่าคู่รบของตน คนซีเรียหนีและคนอิสราเอลไล่ติดตามเขาไป แต่เบนฮาดัดกษัตริย์แห่งซีเรียทรงม้าหนีไปกับทหารม้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 21, 'กษัตริย์แห่งอิสราเอลก็ออกไปโจมตีม้าและรถรบ และประหารชนซีเรียเสียอย่างใหญ่โต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 22, 'แล้วผู้พยากรณ์ผู้นั้นได้เข้ามาใกล้กษัตริย์แห่งอิสราเอลทูลพระองค์ว่า “มาเถิด ขอเสริมกําลังของพระองค์ และตรึกตรองดูว่าพระองค์จะทรงกระทําประการใด เพราะสิ้นปีนี้กษัตริย์แห่งซีเรียจะยกกองทัพมาสู้กับพระองค์อีก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 23, 'ข้าราชการของกษัตริย์แห่งซีเรียทูลท่านว่า “พระทั้งหลายของเขาเป็นพระแห่งภูเขา เขาทั้งหลายจึงแข็งกว่าเรา แต่ขอให้เราสู้รบกับเขาในที่ราบ แล้วเราจะต้องแข็งกว่าเขาแน่นอนทีเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 24, 'ขอกระทําอย่างนี้ ขอปลดกษัตริย์เสียทุกองค์จากตําแหน่งและตั้งนายทหารขึ้นแทน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 25, 'และเกณฑ์กองทัพเข้าแทนส่วนที่ล้มตายไปในคราวก่อน ม้าแทนม้า รถรบแทนรถรบ แล้วเราทั้งหลายจะสู้รบกับเขาในที่ราบ เราจะต้องแข็งกว่าเขาแน่นอนทีเดียว” และท่านก็ฟังเสียงของเขาทั้งหลายและกระทําตาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 26, 'และอยู่มาพอสิ้นปีแล้วเบนฮาดัดก็เกณฑ์ชนซีเรีย ยกขึ้นไปถึงเมืองอาเฟกเพื่อสู้รบกับอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 27, 'และประชาชนอิสราเอลก็ถูกเกณฑ์ และอยู่พร้อมกันหมด และยกออกไปต่อสู้กับเขา ประชาชนอิสราเอลตั้งค่ายตรงหน้าเขาเหมือนอย่างแพะสองฝูงเล็กๆ แต่คนซีเรียเต็มท้องทุ่งไปหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 28, 'และคนของพระเจ้าคนหนึ่งได้เข้าไปใกล้และทูลกษัตริย์แห่งอิสราเอลว่า “พระเยโฮวาห์ตรัสดังนี้ว่า เพราะคนซีเรียได้กล่าวว่า ‘พระเยโฮวาห์เป็นพระเจ้าแห่งภูเขา พระองค์มิได้เป็นพระเจ้าแห่งหุบเขา’ เพราะฉะนั้นเราจะมอบประชาชนหมู่ใหญ่นี้ไว้ในมือของเจ้า และเจ้าจะได้รู้ว่าเราคือพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 29, 'แล้วเขาก็ตั้งค่ายตรงข้ามกันอยู่เจ็ดวัน แล้วในวันที่เจ็ดก็ปะทะกัน ประชาชนอิสราเอลก็ฆ่าคนซีเรียซึ่งเป็นทหารราบเสียหนึ่งแสนคนในวันเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 30, 'เหลือนอกนั้นก็หนีเข้าเมืองอาเฟก และกําแพงเมืองล้มทับคนที่เหลือนอกนั้นเสียสองหมื่นเจ็ดพันคน เบนฮาดัดก็หนีไปด้วย และเข้าไปในห้องชั้นในที่ในเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 31, 'และข้าราชการของท่านมาทูลว่า “ดูเถิด เราได้ยินว่ากษัตริย์แห่งวงศ์วานอิสราเอลเป็นกษัตริย์ที่ทรงเมตตา ขอให้เราเอาผ้ากระสอบคาดเอว และเอาเชือกพันศีรษะของเรา และออกไปหากษัตริย์แห่งอิสราเอล ชะรอยท่านจะไว้ชีวิตของพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 32, 'เพราะฉะนั้นเขาจึงเอาผ้ากระสอบคาดเอวและเอาเชือกพันศีรษะ และเขาไปเฝ้ากษัตริย์แห่งอิสราเอลทูลว่า “เบนฮาดัดผู้รับใช้ของพระองค์สั่งมาว่า ‘ได้โปรดเถิด ขอให้ข้าพเจ้ารอดชีวิตอยู่’” และพระองค์ตรัสว่า “ท่านยังมีชีวิตหรือ ท่านเป็นน้องของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 33, 'ฝ่ายคนเหล่านั้นกําลังหาช่องอยู่แล้ว เขาทั้งหลายก็รีบตอบโดยเร็วว่า “พระเจ้าข้า เบนฮาดัดอนุชาของพระองค์” แล้วพระองค์ตรัสว่า “ไปเถอะและนําท่านมา” แล้วเบนฮาดัดก็ออกมาหาพระองค์ แล้วพระองค์ก็ให้ท่านขึ้นไปบนรถรบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 34, 'และเบนฮาดัดทูลว่า “หัวเมืองซึ่งบิดาของข้าพเจ้ายึดเอาไปจากราชบิดาของท่านนั้น ข้าพเจ้าขอคืนให้พระองค์ พระองค์จะสร้างถนนหนทางของพระองค์ในเมืองดามัสกัสก็ได้ อย่างที่บิดาข้าพเจ้าทําไว้ในสะมาเรีย” แล้วอาหับตรัสว่า “เราจะยอมให้ท่านไปตามพันธสัญญานี้” พระองค์จึงทําพันธสัญญากับท่าน และปล่อยท่านไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 35, 'มีชายคนหนึ่งในเหล่าศิษย์แห่งผู้พยากรณ์พูดกับเพื่อนของตนตามพระบัญชาของพระเยโฮวาห์ว่า “ได้โปรดเถอะ ขอตีฉันที” แต่ชายคนนั้นก็ปฏิเสธไม่ยอมตีท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 36, 'แล้วท่านจึงพูดกับเขาว่า “เพราะท่านไม่เชื่อฟังพระสุรเสียงของพระเยโฮวาห์ ดูเถิด พอท่านออกไปจากข้าพเจ้า สิงโตตัวหนึ่งจะสังหารท่าน” พอเขาจากท่านไป สิงโตตัวหนึ่งก็มาพบเขาและสังหารเขาเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 37, 'แล้วท่านไปพบชายอีกคนหนึ่ง และท่านว่า “ได้โปรดเถอะ ขอตีฉันที” ชายคนนั้นได้ตีท่านและทําให้ท่านฟกช้ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 38, 'ผู้พยากรณ์ผู้นั้นจึงจากไป และไปคอยพบกษัตริย์อยู่ที่หนทาง ใส่ขี้เถ้าบนหน้าปลอมตัวเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 39, 'พอกษัตริย์ทรงผ่านไป ท่านก็ร้องทูลกษัตริย์ว่า “ผู้รับใช้ของพระองค์เข้าไปในกลางศึก และดูเถิด ทหารคนหนึ่งหันมา และนําชายคนหนึ่งมาให้ข้าพระองค์ บอกว่า ‘จงระวังชายคนนี้ไว้นะ ถ้าเขาหลุดไปได้โดยเหตุใดๆ ชีวิตของท่านจะต้องแทนชีวิตของเขา หรือมิฉะนั้นท่านจะต้องเสียเงินตะลันต์หนึ่ง’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 40, 'และเมื่อข้าพระองค์ติดธุระอยู่ที่นี่ที่นั่น เขาก็หายไป” กษัตริย์แห่งอิสราเอลตรัสกับท่านว่า “โทษของเจ้าต้องเป็นอย่างนั้นแหละ เพราะเจ้าเองได้ตัดสินแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 41, 'แล้วท่านก็รีบเอาขี้เถ้าออกจากหน้าของตน และกษัตริย์แห่งอิสราเอลก็จําท่านได้ว่า เป็นผู้พยากรณ์คนหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 42, 'และท่านจึงทูลพระองค์ว่า “พระเยโฮวาห์ตรัสดังนี้ว่า เพราะเจ้าได้ปล่อยชายคนที่อยู่ในมือของเจ้า ผู้ซึ่งเราได้กําหนดให้ทําลายนั้น ชีวิตของเจ้าจะต้องแทนชีวิตของเขา และชนชาติของเจ้าแทนชนชาติของเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 43, 'และกษัตริย์แห่งอิสราเอลก็เสด็จเข้าไปในพระราชวังด้วยอารมณ์ขุ่นมัวและไม่พอพระทัยยิ่งนัก และเสด็จมาสะมาเรีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 1, 'และอยู่มาภายหลังเหตุการณ์เหล่านี้ นาโบทชาวยิสเรเอลมีสวนองุ่นอยู่ในยิสเรเอล ข้างพระราชวังของอาหับกษัตริย์แห่งสะมาเรีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 2, 'อาหับตรัสกับนาโบทว่า “จงให้สวนองุ่นของเจ้าแก่เราเถิด เพื่อเราจะได้ทําสวนผักเพราะอยู่ใกล้วังของเรา เราจะให้สวนองุ่นที่ดีกว่าเพื่อแลกสวนนี้ หรือถ้าเจ้าเห็นชอบ เราจะให้เงินสมกับราคาสวนนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 3, 'แต่นาโบททูลอาหับว่า “ขอพระเยโฮวาห์ทรงห้ามข้าพระองค์ในการที่จะยกมรดกของบรรพบุรุษให้แก่พระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 4, 'อาหับก็เสด็จเข้าในวังด้วยอารมณ์ขุ่นมัวและไม่พอพระทัยยิ่งนัก ด้วยเรื่องที่นาโบทชาวยิสเรเอลทูลตอบพระองค์ เพราะเขาได้กล่าวว่า “ข้าพระองค์จะไม่ให้มรดกแห่งบรรพบุรุษของข้าพระองค์แก่พระองค์” และพระองค์ก็เอนพระกายลงบนพระแท่น ทรงเบือนพระพักตร์ไม่เสวยพระกระยาหาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 5, 'แต่เยเซเบลมเหสีของพระองค์เข้ามาเฝ้าพระองค์ทูลถามพระองค์ว่า “ไฉนพระจิตของพระองค์จึงเสียพระทัย ไม่เสวยพระกระยาหาร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 6, 'และพระองค์ตรัสตอบพระนางว่า “เพราะเราได้พูดกับนาโบทชาวยิสเรเอลว่า ‘จงขายสวนองุ่นของเจ้าให้แก่เรา หรือมิฉะนั้นถ้าเจ้าพอใจ เราจะให้สวนองุ่นอีกแห่งหนึ่งแก่เจ้าเพื่อแลกกัน’ และเขาตอบว่า ‘ข้าพระองค์จะไม่ให้สวนองุ่นของข้าพระองค์แก่พระองค์’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 7, 'และเยเซเบลมเหสีของพระองค์ทูลพระองค์ว่า “พระองค์เป็นผู้ครอบครองราชอาณาจักรอิสราเอลอยู่หรือเพคะ เชิญเสด็จลุกขึ้นเสวยพระกระยาหารเถิด และให้พระทัยของพระองค์ร่าเริง หม่อมฉันจะมอบสวนองุ่นของนาโบทชาวยิสเรเอลให้แก่พระองค์เอง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 8, 'พระนางจึงทรงพระอักษรในพระนามของอาหับ ประทับตราของพระองค์ส่งไปยังพวกผู้ใหญ่และขุนนางผู้อยู่ในเมืองกับนาโบท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 9, 'พระนางทรงพระอักษรว่า “จงประกาศให้ถืออดอาหาร และตั้งนาโบทไว้ในที่สูงท่ามกลางประชาชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 10, 'และตั้งลูกแห่งเบลีอัลสองคนให้นั่งตรงข้ามกับเขา ให้ฟ้องเขาว่า ‘เจ้าได้แช่งพระเจ้าและกษัตริย์’ แล้วพาเขาออกไปและเอาหินขว้างเสียให้ตาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 11, 'และพวกผู้ชายของเมืองนั้น คือพวกผู้ใหญ่และขุนนางผู้อาศัยอยู่ในเมืองนั้น ได้กระทําตามที่เยเซเบลมีไปถึงพวกเขา ตามที่ปรากฏในลายพระหัตถ์ซึ่งพระนางทรงมีไปถึงเขานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 12, 'เขาได้ประกาศให้ถืออดอาหาร และได้ตั้งนาโบทไว้ในที่สูงท่ามกลางประชาชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 13, 'และลูกของเบลีอัลสองคนนั้นก็เข้ามา นั่งอยู่ตรงข้ามกับเขา และคนของเบลีอัลนั้นได้ฟ้องนาโบทต่อหน้าประชาชนกล่าวว่า “นาโบทได้แช่งพระเจ้าและกษัตริย์” เขาทั้งหลายจึงพานาโบทออกไปนอกเมือง และขว้างเขาถึงตายด้วยก้อนหิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 14, 'แล้วเขาก็ส่งข่าวไปทูลเยเซเบลว่า “นาโบทถูกขว้างด้วยหิน เขาตายแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 15, 'อยู่มาพอเยเซเบลทรงได้ยินว่านาโบทถูกขว้างด้วยหินตายแล้ว เยเซเบลจึงทูลอาหับว่า “ขอเชิญเสด็จลุกขึ้น ไปยึดสวนองุ่นของนาโบทชาวยิสเรเอล ซึ่งเขาได้ปฏิเสธไม่ขายให้แก่พระองค์ เพราะว่านาโบทไม่อยู่ เขาตายเสียแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 16, 'และอยู่มาพออาหับทรงได้ยินว่านาโบทตายแล้ว อาหับก็ทรงลุกขึ้นไปยังสวนองุ่นของนาโบทชาวยิสเรเอล เพื่อยึดถือเป็นกรรมสิทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 17, 'แล้วพระวจนะของพระเยโฮวาห์มาถึงเอลียาห์ชาวทิชบีว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 18, '“จงลุกขึ้นแล้วลงไปพบอาหับกษัตริย์แห่งอิสราเอล ผู้อยู่ในสะมาเรีย ดูเถิด เขาอยู่ในสวนองุ่นของนาโบท ที่เขาไปยึดเอาเป็นกรรมสิทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 19, 'เจ้าจงพูดกับเขาว่า ‘พระเยโฮวาห์ตรัสดังนี้ว่า ท่านได้ฆ่าและได้ยึดถือเอาเป็นกรรมสิทธิ์ด้วยหรือ’ และเจ้าจงพูดกับเขาว่า ‘พระเยโฮวาห์ตรัสดังนี้ว่า ในที่ซึ่งสุนัขเลียโลหิตของนาโบท สุนัขจะเลียโลหิตของเจ้าด้วย’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 20, 'อาหับตรัสกับเอลียาห์ว่า “โอ ศัตรูของข้าเอ๋ย เจ้าพบข้าแล้วหรือ” ท่านทูลตอบว่า “ข้าพระองค์พบพระองค์แล้ว เพราะว่าพระองค์ยอมขายพระองค์เพื่อกระทําสิ่งชั่วในสายพระเนตรของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 21, 'ดูเถิด เราจะนําเหตุร้ายมาเหนือเจ้า เราจะเอาคนชั่วอายุต่อจากเจ้าออกไปเสีย และจะขจัดคนที่ปัสสาวะรดกําแพงได้เสียจากอาหับ ทั้งคนที่ยังอยู่และเหลืออยู่ในอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 22, 'และเราจะกระทําให้ราชวงศ์ของเจ้าเหมือนราชวงศ์ของเยโรโบอัมบุตรเนบัท และเหมือนราชวงศ์ของบาอาชาบุตรอาหิยาห์ เพราะเจ้าได้กระทําให้เราโกรธ และเพราะเจ้าได้กระทําให้อิสราเอลทําบาปด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 23, 'และส่วนเยเซเบล พระเยโฮวาห์ตรัสว่า ‘สุนัขจะกินเยเซเบลข้างกําแพงยิสเรเอล’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 24, 'ผู้ใดในราชวงศ์อาหับที่ตายในเมือง สุนัขจะกิน และผู้อยู่ในราชวงศ์เขาที่ตายในทุ่งนา นกในอากาศจะกิน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 25, 'ไม่มีผู้ใดได้ขายตนเองเพื่อกระทําความชั่วในสายพระเนตรของพระเยโฮวาห์อย่างอาหับ ผู้ที่เยเซเบลมเหสีได้ยุแหย่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 26, 'พระองค์ทรงประพฤติอย่างน่าสะอิดสะเอียนเป็นอย่างยิ่งในการดําเนินตามรูปเคารพ ดังสิ่งทั้งปวงที่คนอาโมไรต์ได้กระทํา ซึ่งเป็นผู้ที่พระเยโฮวาห์ทรงขับไล่ออกไปให้พ้นหน้าประชาชนอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 27, 'และอยู่มาเมื่ออาหับทรงได้ยินพระวจนะเหล่านั้น พระองค์ก็ฉีกฉลองพระองค์ และทรงสวมผ้ากระสอบ และถืออดอาหาร ประทับในผ้ากระสอบ และทรงดําเนินไปมาอย่างค่อยๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 28, 'และพระวจนะของพระเยโฮวาห์มายังเอลียาห์ชาวทิชบีว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 29, '“เจ้าได้เห็นอาหับถ่อมตัวลงต่อหน้าเราแล้วหรือ เพราะเขาได้ถ่อมตัวลงต่อหน้าเรา เราจะไม่นําเหตุร้ายมาในสมัยของเขา แต่มาในสมัยบุตรชายของเขา เราจะนําเหตุร้ายมาเหนือราชวงศ์ของเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 1, 'ประเทศซีเรียและอิสราเอลไม่มีศึกสงครามกันอยู่สามปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 2, 'ต่อไปในปีที่สามเยโฮชาฟัทกษัตริย์แห่งยูดาห์เสด็จลงไปเฝ้ากษัตริย์แห่งอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 3, 'และกษัตริย์แห่งอิสราเอลตรัสถามบรรดาข้าราชการของพระองค์ว่า “ท่านทราบกันหรือไม่ว่าเมืองราโมทในกิเลอาดเป็นของเรา และเราได้นิ่งอยู่มิได้เอาออกมาจากมือของกษัตริย์แห่งซีเรีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 4, 'และพระองค์ตรัสกับเยโฮชาฟัทว่า “ท่านจะยกไปทําศึกที่ราโมทกิเลอาดกับข้าพเจ้าหรือ” และเยโฮชาฟัทตรัสกับกษัตริย์แห่งอิสราเอลว่า “ข้าพเจ้าก็เป็นอย่างที่ท่านเป็น ประชาชนของข้าพเจ้าก็เป็นดังประชาชนของท่าน ม้าของข้าพเจ้าก็เป็นดังม้าของท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 5, 'และเยโฮชาฟัทตรัสกับกษัตริย์แห่งอิสราเอลว่า “ขอสอบถามดูพระดํารัสของพระเยโฮวาห์วันนี้เถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 6, 'แล้วกษัตริย์แห่งอิสราเอลก็เรียกประชุมพวกผู้พยากรณ์ประมาณสี่ร้อยคน ตรัสกับเขาว่า “ควรที่เราจะไปตีราโมทกิเลอาดหรือ หรือเราไม่ควรไป” และเขาทั้งหลายทูลตอบว่า “ขอเชิญเสด็จขึ้นไปเถิด เพราะองค์พระผู้เป็นเจ้าจะทรงมอบไว้ในพระหัตถ์ของกษัตริย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 7, 'แต่เยโฮชาฟัททูลว่า “ที่นี่ไม่มีผู้พยากรณ์ของพระเยโฮวาห์อีกซึ่งเราจะสอบถามได้แล้วหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 8, 'และกษัตริย์แห่งอิสราเอลทูลเยโฮชาฟัทว่า “ยังมีชายอีกคนหนึ่งซึ่งเราจะให้ทูลถามพระเยโฮวาห์ได้คือ มีคายาห์บุตรอิมลาห์ แต่ข้าพเจ้าชังเขา เพราะเขาพยากรณ์แต่ความร้าย ไม่เคยพยากรณ์ความดีเกี่ยวกับข้าพเจ้าเลย” และเยโฮชาฟัททูลว่า “ขอกษัตริย์อย่าตรัสดังนั้นเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 9, 'แล้วกษัตริย์แห่งอิสราเอลจึงเรียกมหาดเล็กคนหนึ่งเข้ามาตรัสสั่งว่า “ไปพามีคายาห์บุตรอิมลาห์มาเร็วๆ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 10, 'ฝ่ายกษัตริย์แห่งอิสราเอลและเยโฮชาฟัทกษัตริย์แห่งยูดาห์ต่างประทับบนพระที่นั่ง ทรงฉลองพระองค์ ณ ช่องว่างตรงทางเข้าประตูเมืองสะมาเรีย และผู้พยากรณ์ทั้งปวงก็พยากรณ์ถวายอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 11, 'และเศเดคียาห์บุตรชายเคนาอะนาห์จึงเอาเหล็กทําเป็นเขาและพูดว่า “พระเยโฮวาห์ตรัสดังนี้ว่า ด้วยสิ่งเหล่านี้เจ้าจะผลักคนซีเรียไปจนเจ้าผลาญเขาทั้งหลายเสียสิ้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 12, 'และบรรดาผู้พยากรณ์ก็พยากรณ์อย่างนั้นทูลว่า “ขอเสด็จขึ้นไปราโมทกิเลอาดเถิด และมีชัยชนะ เพราะพระเยโฮวาห์จะทรงมอบเมืองนั้นไว้ในพระหัตถ์ของกษัตริย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 13, 'และผู้สื่อสารผู้ไปตามมีคายาห์ได้บอกท่านว่า “ดูเถิด ถ้อยคําของบรรดาผู้พยากรณ์ก็พูดสิ่งที่ดีแก่กษัตริย์เป็นปากเดียวกัน ขอให้ถ้อยคําของท่านเหมือนอย่างถ้อยคําของคนหนึ่งในพวกนั้น และพูดแต่สิ่งที่ดี”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 14, 'แต่มีคายาห์ตอบว่า “พระเยโฮวาห์ทรงพระชนม์อยู่แน่ฉันใด พระเยโฮวาห์ตรัสกับข้าพเจ้าอย่างไร ข้าพเจ้าจะต้องพูดอย่างนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 15, 'และเมื่อท่านมาเฝ้ากษัตริย์ กษัตริย์ตรัสถามท่านว่า “มีคายาห์ ควรที่เราจะไปตีราโมทกิเลอาดหรือ หรือเราไม่ควรไป” และท่านทูลตอบพระองค์ว่า “ขอเชิญเสด็จขึ้นไปและมีชัยชนะ พระเยโฮวาห์จะทรงมอบไว้ในพระหัตถ์ของกษัตริย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 16, 'แต่กษัตริย์ตรัสกับท่านว่า “เราได้ให้เจ้าปฏิญาณกี่ครั้งแล้วว่า เจ้าจะพูดกับเราแต่ความจริงในพระนามของพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 17, 'และท่านก็ทูลว่า “ข้าพระองค์ได้เห็นคนอิสราเอลทั้งปวงกระจัดกระจายอยู่บนภูเขาอย่างแกะที่ไม่มีผู้เลี้ยง และพระเยโฮวาห์ตรัสว่า ‘คนเหล่านี้ไม่มีนาย ให้เขาต่างกลับยังเรือนของตนโดยสันติภาพเถิด’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 18, 'กษัตริย์แห่งอิสราเอลจึงทูลเยโฮชาฟัทว่า “ข้าพเจ้ามิได้บอกท่านแล้วหรือว่า เขาจะไม่พยากรณ์สิ่งดีเกี่ยวกับข้าพเจ้าเลย แต่สิ่งร้ายต่างหาก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 19, 'และมีคายาห์ทูลว่า “ฉะนั้นขอสดับพระวจนะของพระเยโฮวาห์ ข้าพระองค์ได้เห็นพระเยโฮวาห์ประทับบนพระที่นั่งของพระองค์ และบรรดาบริวารแห่งฟ้าสวรรค์ยืนข้างๆพระองค์ ข้างขวาพระหัตถ์และข้างซ้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 20, 'และพระเยโฮวาห์ตรัสว่า ‘ผู้ใดจะเกลี้ยกล่อมอาหับเพื่อเขาจะขึ้นไปและล้มลงที่ราโมทกิเลอาด’ บ้างก็ทูลอย่างนี้ บ้างก็ทูลอย่างนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 21, 'แล้วมีวิญญาณดวงหนึ่งมาข้างหน้า เฝ้าต่อพระพักตร์พระเยโฮวาห์ทูลว่า ‘ข้าพระองค์จะเกลี้ยกล่อมเขาเอง’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 22, 'และพระเยโฮวาห์ตรัสกับเขาว่า ‘จะทําอย่างไร’ และเขาทูลว่า ‘ข้าพระองค์จะออกไป และจะเป็นวิญญาณมุสาอยู่ในปากของผู้พยากรณ์ของเขาทุกคน’ และพระองค์ตรัสว่า ‘เจ้าไปเกลี้ยกล่อมเขาได้ และเจ้าจะทําได้สําเร็จ จงไปทําเถิด’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 23, 'เพราะฉะนั้นบัดนี้ ดูเถิด พระเยโฮวาห์ทรงใส่วิญญาณมุสาในปากของเหล่าผู้พยากรณ์นี้ทั้งสิ้นของพระองค์ พระเยโฮวาห์ทรงตรัสเป็นความร้ายเกี่ยวกับพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 24, 'แล้วเศเดคียาห์บุตรชายเคนาอะนาห์ได้เข้ามาใกล้และตบแก้มมีคายาห์พูดว่า “พระวิญญาณของพระเยโฮวาห์ไปจากข้า พูดกับเจ้าได้อย่างไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 25, 'และมีคายาห์ตอบว่า “ดูเถิด เจ้าจะเห็นในวันนั้น เมื่อเจ้าเข้าไปในห้องชั้นในเพื่อจะซ่อนตัวเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 26, 'และกษัตริย์แห่งอิสราเอลตรัสว่า “จงจับมีคายาห์พาเขากลับไปมอบให้อาโมนผู้ว่าราชการเมืองและแก่โยอาชราชโอรสกษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 27, 'และว่า ‘กษัตริย์ตรัสดังนี้ว่า “เอาคนนี้จําคุกเสีย ให้อาหารแห่งความทุกข์กับน้ําแห่งความทุกข์ จนกว่าเราจะกลับมาโดยสันติภาพ”’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 28, 'และมีคายาห์ทูลว่า “ถ้าพระองค์เสด็จกลับมาโดยสันติภาพ พระเยโฮวาห์ก็มิได้ตรัสโดยข้าพระองค์” และท่านกล่าวว่า “โอ บรรดาชนชาติทั้งหลายเอ๋ย ขอจงฟังเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 29, 'กษัตริย์แห่งอิสราเอลกับเยโฮชาฟัทกษัตริย์แห่งยูดาห์จึงเสด็จขึ้นไปยังราโมทกิเลอาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 30, 'และกษัตริย์แห่งอิสราเอลตรัสกับเยโฮชาฟัทว่า “ข้าพเจ้าจะปลอมตัวเข้าทําศึก แต่ท่านจงสวมเครื่องทรงของท่าน” และกษัตริย์แห่งอิสราเอลก็ทรงปลอมพระองค์เข้าทําสงคราม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 31, 'ฝ่ายกษัตริย์ประเทศซีเรียทรงบัญชาแม่ทัพรถรบทั้งสามสิบสองคนว่า “อย่ารบกับทหารน้อยหรือใหญ่ แต่มุ่งเฉพาะกษัตริย์แห่งอิสราเอล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 32, 'และอยู่มาเมื่อผู้บัญชาการรถรบแลเห็นเยโฮชาฟัท เขาทั้งหลายก็ว่า “เป็นกษัตริย์อิสราเอลแน่แล้ว” เขาจึงหันเข้าไปสู้รบกับพระองค์และเยโฮชาฟัททรงร้องขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 33, 'และอยู่มาเมื่อผู้บัญชาการรถรบเห็นว่าไม่ใช่กษัตริย์แห่งอิสราเอล ก็หันกลับจากไล่ตามพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 34, 'แต่มีชายคนหนึ่งโก่งธนูยิงเดาไป ถูกกษัตริย์แห่งอิสราเอลเข้าระหว่างเกล็ดเกราะและแผ่นบังพระอุระ พระองค์จึงรับสั่งคนขับรถรบว่า “หันกลับเถอะ พาเราออกจากการรบ เพราะเราบาดเจ็บแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 35, 'วันนั้นการรบก็ดุเดือดขึ้น เขาก็หนุนกษัตริย์ไว้ในราชรถให้หันพระพักตร์เข้าสู่ชนซีเรีย จนเวลาเย็นพระองค์ก็สิ้นพระชนม์ และโลหิตที่บาดแผลก็ไหลออกนองท้องรถรบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 36, 'ประมาณดวงอาทิตย์ตกก็มีเสียงร้องทั่วกองทัพว่า “ทุกคนจงกลับไปเมืองของตัว และทุกคนจงกลับไปภูมิลําเนาของตัว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 37, 'ครั้นกษัตริย์สิ้นพระชนม์แล้วเขาก็นํามายังกรุงสะมาเรีย และฝังพระศพกษัตริย์ไว้ในสะมาเรีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 38, 'เขาล้างรถรบที่สระแห่งสะมาเรีย และสุนัขก็เลียโลหิตของพระองค์ เขาได้ล้างเกราะของพระองค์ ตามพระวจนะของพระเยโฮวาห์ซึ่งพระองค์ได้ตรัส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 39, 'ส่วนพระราชกิจนอกนั้นของอาหับ และบรรดาสิ่งซึ่งพระองค์ทรงกระทํา และพระราชวังงาช้างซึ่งพระองค์ทรงสร้างไว้ และหัวเมืองทั้งปวงที่พระองค์ทรงสร้าง มิได้บันทึกไว้ในหนังสือพงศาวดารแห่งกษัตริย์ประเทศอิสราเอลหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 40, 'อาหับทรงล่วงหลับไปอยู่กับบรรพบุรุษของพระองค์ และอาหัสยาห์ราชโอรสของพระองค์ก็ขึ้นครองแทน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 41, 'เยโฮชาฟัทราชโอรสของอาสาเริ่มขึ้นครองเหนือยูดาห์ในปีที่สี่แห่งรัชกาลอาหับกษัตริย์แห่งอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 42, 'เยโฮชาฟัทมีพระชนมายุสามสิบห้าพรรษาเมื่อทรงเริ่มขึ้นครอง และพระองค์ทรงครองในเยรูซาเล็มยี่สิบห้าปี พระราชมารดาของพระองค์มีพระนามว่า อาซูบาห์ธิดาของชิลหิ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 43, 'พระองค์ทรงดําเนินตามมรรคาของอาสาราชบิดาทุกประการ มิได้หันเหออกไปจากทางนั้น ทรงกระทําสิ่งที่ถูกต้องในสายพระเนตรพระเยโฮวาห์ แต่ปูชนียสถานสูงนั้นยังมิได้ถูกรื้อลง ประชาชนยังคงถวายเครื่องสัตวบูชาและเผาเครื่องหอมในปูชนียสถานสูงนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 44, 'เยโฮชาฟัททรงกระทําไมตรีกับกษัตริย์แห่งอิสราเอลด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 45, 'ส่วนพระราชกิจนอกนั้นของเยโฮชาฟัท และยุทธพลังที่พระองค์ทรงสําแดง และสงครามที่พระองค์ทรงกระทํา มิได้บันทึกไว้ในหนังสือพงศาวดารแห่งกษัตริย์ประเทศยูดาห์หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 46, 'และพวกกะเทยที่ยังเหลืออยู่คือผู้ที่ยังเหลือในสมัยของอาสาราชบิดานั้น พระองค์ก็ทรงกําจัดเสียจากแผ่นดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 47, 'ไม่มีกษัตริย์ในประเทศเอโดม แต่มีผู้ว่าราชการเป็นกษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 48, 'เยโฮชาฟัททรงต่อกําปั่นทารชิช เพื่อจะไปขนทองคําจากโอฟีร์ แต่กําปั่นนั้นไปไม่ถึงเพราะไปแตกเสียที่เอซีโอนเกเบอร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 49, 'แล้วอาหัสยาห์ราชโอรสของอาหับตรัสกับเยโฮชาฟัทว่า “ขอให้ข้าราชการของข้าพเจ้าไปในเรือกําปั่นกับข้าราชการของท่าน” แต่เยโฮชาฟัทไม่พอพระทัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 50, 'และเยโฮชาฟัททรงล่วงหลับไปอยู่กับบรรพบุรุษของพระองค์ และเขาฝังพระศพไว้กับบรรพบุรุษที่ในนครดาวิดบรรพบุรุษของพระองค์ และเยโฮรัมราชโอรสก็ขึ้นครองแทนพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 51, 'อาหัสยาห์ราชโอรสของอาหับทรงเริ่มครองเหนืออิสราเอลในสะมาเรียในปีที่สิบเจ็ดแห่งรัชกาลเยโฮชาฟัทกษัตริย์แห่งยูดาห์ และพระองค์ทรงครอบครองเหนืออิสราเอลสองปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 52, 'พระองค์ทรงกระทําชั่วในสายพระเนตรของพระเยโฮวาห์ และทรงดําเนินในมรรคาแห่งราชบิดาของพระองค์ และในมรรคาแห่งพระราชมารดาของพระองค์ และในมรรคาของเยโรโบอัมบุตรชายเนบัทผู้ทรงกระทําให้อิสราเอลทําบาปด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 53, 'พระองค์ทรงปรนนิบัติพระบาอัลและนมัสการพระนั้น และทรงกระทําให้พระเยโฮวาห์พระเจ้าแห่งอิสราเอลทรงพระพิโรธด้วยทุกวิธีที่ราชบิดาของพระองค์ทรงกระทําแล้วนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 1, 'หลังจากอาหับสิ้นพระชนม์แล้ว เมืองโมอับก็กบฏต่อคนอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 2, 'ฝ่ายอาหัสยาห์ทรงตกลงมาจากช่องพระแกลตาข่ายที่ห้องชั้นบนของพระองค์ในกรุงสะมาเรียและทรงประชวร จึงทรงใช้บรรดาผู้สื่อสารไป รับสั่งว่า “จงไปถามบาอัลเซบูบ พระแห่งเอโครนว่า เราจะหายจากความเจ็บป่วยนี้หรือไม่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 3, 'แต่ทูตสวรรค์ของพระเยโฮวาห์พูดกับเอลียาห์ชาวทิชบีว่า “จงลุกขึ้นไปพบบรรดาผู้สื่อสารของกษัตริย์แห่งสะมาเรีย และจงพูดกับเขาทั้งหลายว่า ‘เพราะไม่มีพระเจ้าในอิสราเอลแล้วหรือ ท่านจึงไปถามบาอัลเซบูบ พระแห่งเอโครน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 4, 'เพราะฉะนั้นบัดนี้พระเยโฮวาห์ตรัสดังนี้ว่า ‘เจ้าจะไม่ได้ลงมาจากที่นอนซึ่งเจ้าขึ้นไปนั้น แต่เจ้าจะต้องตายแน่’” แล้วเอลียาห์ก็ไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 5, 'ผู้สื่อสารนั้นก็กลับมาเฝ้าพระองค์ พระองค์ตรัสถามเขาทั้งหลายว่า “ทําไมพวกเจ้าจึงพากันกลับมา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 6, 'และเขาทั้งหลายทูลพระองค์ว่า “มีชายคนหนึ่งมาพบกับพวกข้าพระองค์ และพูดกับพวกข้าพระองค์ว่า ‘จงกลับไปหากษัตริย์ผู้ใช้ท่านมา และทูลพระองค์ว่า พระเยโฮวาห์ตรัสดังนี้ว่า เพราะไม่มีพระเจ้าในอิสราเอลแล้วหรือเจ้าจึงใช้คนไปถามบาอัลเซบูบพระแห่งเอโครน เพราะฉะนั้นเจ้าจะไม่ได้ลงมาจากที่นอนซึ่งเจ้าได้ขึ้นไปนั้น แต่เจ้าจะต้องตายแน่’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 7, 'พระองค์ตรัสถามเขาทั้งหลายว่า “คนที่ได้มาพบเจ้าและบอกสิ่งเหล่านี้แก่เจ้านั้นเป็นคนในลักษณะใด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 8, 'เขาทั้งหลายทูลตอบพระองค์ว่า “ท่านมีขนมากและมีหนังคาดเอวของท่านไว้” และพระองค์ตรัสว่า “เป็นเอลียาห์ชาวทิชบี”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 9, 'แล้วกษัตริย์ก็รับสั่งให้นายกองของทหารห้าสิบคนพร้อมกับทหารห้าสิบคนของเขาไปหาเอลียาห์ เขาได้ขึ้นไปหาท่าน ดูเถิด ท่านนั่งอยู่บนยอดภูเขา และนายกองห้าสิบคนนั้นกล่าวแก่ท่านว่า “คนแห่งพระเจ้าเอ๋ย กษัตริย์ตรัสดังนี้ว่า ‘ลงมา’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 10, 'แต่เอลียาห์ตอบนายกองห้าสิบคนว่า “ถ้าข้าเป็นคนแห่งพระเจ้า ก็ขอให้ไฟลงมาจากฟ้าสวรรค์เผาผลาญเจ้าและคนทั้งห้าสิบของเจ้าเถิด” แล้วไฟก็ลงมาจากฟ้าสวรรค์และเผาผลาญเขากับคนทั้งห้าสิบของเขาเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 11, 'พระองค์ก็รับสั่งให้นายกองของทหารห้าสิบคนพร้อมกับทหารห้าสิบคนของเขาอีกพวกหนึ่งไป และเขาก็กล่าวแก่ท่านว่า “โอ คนแห่งพระเจ้า กษัตริย์ตรัสดังนี้ว่า ‘ลงมาเร็วๆ’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 12, 'แต่เอลียาห์ตอบว่า “ถ้าข้าเป็นคนแห่งพระเจ้า ก็ขอให้ไฟลงมาจากฟ้าสวรรค์เผาผลาญเจ้าและคนทั้งห้าสิบของเจ้าเถิด” และไฟของพระเจ้าลงมาจากฟ้าสวรรค์และเผาผลาญเขากับคนทั้งห้าสิบของเขาเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 13, 'และพระองค์รับสั่งให้นายกองของทหารห้าสิบคนพวกที่สามไปพร้อมกับทหารห้าสิบคนของเขา และนายกองคนที่สามของทหารห้าสิบคนนั้นก็ขึ้นไป และมาคุกเข่าลงต่อหน้าเอลียาห์ และวิงวอนท่านว่า “โอ ข้าแต่คนแห่งพระเจ้า ข้าพเจ้าขออ้อนวอนต่อท่าน ขอได้โปรดให้ชีวิตของข้าพเจ้าและชีวิตของผู้รับใช้ของท่านห้าสิบคนนี้เป็นสิ่งประเสริฐในสายตาของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 14, 'ดูเถิด ไฟลงมาจากฟ้าสวรรค์และได้เผาผลาญนายกองห้าสิบทั้งสองคนก่อนหน้านั้นเสียพร้อมทั้งทหารห้าสิบคนของเขาด้วย แต่บัดนี้ขอให้ชีวิตของข้าพเจ้าเป็นสิ่งประเสริฐในสายตาของท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 15, 'แล้วทูตสวรรค์ของพระเยโฮวาห์กล่าวแก่เอลียาห์ว่า “จงลงไปกับเขาเถิด อย่ากลัวเขาเลย” ท่านก็ลุกขึ้นลงไปกับเขาเข้าเฝ้ากษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 16, 'และทูลพระองค์ว่า “พระเยโฮวาห์ตรัสดังนี้ว่า ‘เพราะเจ้าได้ส่งผู้สื่อสารไปยังบาอัลเซบูบพระแห่งเอโครน เพราะไม่มีพระเจ้าในอิสราเอลที่จะทูลถามพระวจนะของพระองค์อย่างนั้นหรือ เพราะฉะนั้นเจ้าจะไม่ได้ลงมาจากที่นอนซึ่งเจ้าได้ขึ้นไปนั้น แต่เจ้าจะต้องตายแน่’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 17, 'พระองค์ก็สิ้นชีวิตตามพระวจนะของพระเยโฮวาห์ซึ่งเอลียาห์กล่าวนั้น และเยโฮรัมก็ขึ้นครองแทน ในปีที่สองแห่งรัชกาลเยโฮรัมบุตรชายเยโฮชาฟัทกษัตริย์แห่งยูดาห์ เพราะพระองค์หามีโอรสไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 18, 'ส่วนพระราชกิจนอกนั้นของอาหัสยาห์ซึ่งพระองค์ทรงกระทํา มิได้บันทึกไว้ในหนังสือพงศาวดารแห่งกษัตริย์ประเทศอิสราเอลหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 1, 'และอยู่มาเมื่อถึงเวลาที่พระเยโฮวาห์จะทรงรับเอลียาห์ขึ้นไปสู่สวรรค์ด้วยลมหมุน เอลียาห์และเอลีชากําลังเดินทางจากหมู่บ้านกิลกาล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 2, 'และเอลียาห์พูดกับเอลีชาว่า “ขอท่านจงคอยอยู่ที่นี่ เพราะพระเยโฮวาห์ทรงใช้ข้าพเจ้าไปถึงเบธเอล” แต่เอลีชาว่า “พระเยโฮวาห์ทรงพระชนม์อยู่ และท่านเองมีชีวิตอยู่แน่ฉันใด ข้าพเจ้าจะไม่จากท่านไปฉันนั้น” ดังนั้นท่านทั้งสองก็ลงไปยังเบธเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 3, 'และเหล่าศิษย์แห่งผู้พยากรณ์ผู้อยู่ในเบธเอลได้ออกมาหาเอลีชาและบอกท่านว่า “ท่านทราบไหมว่า วันนี้พระเยโฮวาห์จะทรงรับอาจารย์ของท่านไปจากเป็นหัวหน้าท่าน” ท่านตอบว่า “ครับ ข้าพเจ้าทราบแล้ว เงียบๆไว้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 4, 'เอลียาห์พูดกับท่านว่า “เอลีชา ขอท่านคอยอยู่ที่นี่เถิด เพราะพระเยโฮวาห์ทรงใช้ข้าพเจ้าไปถึงเมืองเยรีโค” แต่ท่านตอบว่า “พระเยโฮวาห์ทรงพระชนม์อยู่และท่านเองมีชีวิตอยู่แน่ฉันใด ข้าพเจ้าจะไม่จากท่านไปฉันนั้น” เพราะฉะนั้นท่านทั้งสองจึงมายังเมืองเยรีโค');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 5, 'และเหล่าศิษย์แห่งผู้พยากรณ์ผู้อาศัยอยู่ในเมืองเยรีโคได้เข้ามาใกล้เอลีชาและพูดกับท่านว่า “ท่านทราบไหมว่า วันนี้พระเยโฮวาห์จะทรงรับอาจารย์ของท่านไปจากเป็นหัวหน้าท่าน” ท่านตอบว่า “ครับ ข้าพเจ้าทราบแล้ว เงียบๆไว้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 6, 'แล้วเอลียาห์จึงพูดกับท่านว่า “ขอท่านจงคอยอยู่ที่นี่ เพราะพระเยโฮวาห์ทรงใช้ข้าพเจ้าไปถึงแม่น้ําจอร์แดน” แต่ท่านว่า “พระเยโฮวาห์ทรงพระชนม์อยู่และท่านเองมีชีวิตอยู่แน่ฉันใด ข้าพเจ้าจะไม่จากท่านไปฉันนั้น” แล้วท่านทั้งสองก็เดินต่อไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 7, 'คนห้าสิบคนของเหล่าศิษย์แห่งผู้พยากรณ์ก็ไปเหมือนกันและยืนอยู่ตรงหน้าห่างจากท่านทั้งสอง ฝ่ายท่านทั้งสองยืนอยู่ที่แม่น้ําจอร์แดน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 8, 'เอลียาห์ก็เอาเสื้อคลุมของท่านม้วนเข้าแล้วฟาดลงที่น้ํานั้น น้ําก็แยกออกไปสองข้าง ท่านทั้งสองจึงเดินข้ามไปได้บนดินแห้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 9, 'และอยู่มาเมื่อท่านทั้งสองข้ามไปแล้ว เอลียาห์จึงพูดกับเอลีชาว่า “จงขอสิ่งที่อยากให้ข้าพเจ้าทําเพื่อท่านก่อนที่ข้าพเจ้าจะถูกรับไปจากท่าน” และเอลีชาตอบว่า “ขอให้ฤทธิ์เดชของท่านอยู่กับข้าพเจ้าเป็นสองเท่าเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 10, 'และท่านตอบว่า “ท่านขอสิ่งที่ยากนัก แต่ถ้าท่านเห็นข้าพเจ้าถูกรับขึ้นไปจากท่าน ท่านก็จะได้อย่างนั้น แต่ถ้าท่านไม่เห็น ก็จะไม่เป็นแก่ท่านอย่างนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 11, 'และอยู่มาเมื่อท่านทั้งสองยังเดินพูดกันต่อไป ดูเถิด รถเพลิงคันหนึ่งและม้าเพลิงได้แยกท่านทั้งสองออกจากกัน และเอลียาห์ได้ขึ้นไปโดยลมหมุนเข้าสวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 12, 'เอลีชาก็เห็น และท่านได้ร้องว่า “คุณพ่อของข้าพเจ้า คุณพ่อของข้าพเจ้า รถรบของอิสราเอลและพลม้าประจํา” และท่านก็ไม่ได้เห็นเอลียาห์อีกเลย แล้วท่านก็จับเสื้อของตนฉีกออกเป็นสองท่อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 13, 'แล้วท่านก็หยิบเสื้อคลุมของเอลียาห์ที่ตกลงมาจากเอลียาห์นั้น และกลับไปยืนอยู่ที่ฝั่งแม่น้ําจอร์แดน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 14, 'แล้วท่านก็เอาเสื้อคลุมของเอลียาห์ที่ตกลงมานั้นฟาดลงที่น้ํากล่าวว่า “พระเยโฮวาห์พระเจ้าแห่งเอลียาห์ทรงสถิตที่ใด” และเมื่อท่านฟาดลงที่น้ํา น้ําก็แยกออกไปสองข้าง และเอลีชาก็เดินข้ามไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 15, 'เมื่อเหล่าศิษย์แห่งผู้พยากรณ์ที่อยู่ ณ เมืองเยรีโค แลเห็นท่าน เขาทั้งหลายจึงว่า “ฤทธิ์เดชของเอลียาห์อยู่กับเอลีชา” และเขาทั้งหลายก็มาต้อนรับท่าน แล้วซบหน้าลงถึงดินต่อหน้าท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 16, 'เขาทั้งหลายกล่าวแก่ท่านว่า “ดูเถิด มีห้าสิบคนที่เป็นชายฉกรรจ์อยู่กับผู้รับใช้ของท่าน ขอจงไปเที่ยวหาอาจารย์ของท่าน บางทีพระวิญญาณแห่งพระเยโฮวาห์ได้รับท่านไปแล้วเหวี่ยงท่านลงมาที่ภูเขาหรือหุบเขาแห่งหนึ่งแห่งใดบ้าง” และท่านว่า “อย่าใช้เขาไปเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 17, 'แต่เมื่อเขาทั้งหลายชักชวนท่านจนท่านละอายแล้วท่านจึงว่า “ใช้ไปซี” เพราะฉะนั้นเขาจึงใช้ห้าสิบคนไป เขาทั้งหลายแสวงหาเอลียาห์อยู่สามวันก็ไม่พบท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 18, 'เขาทั้งหลายก็กลับมาหาเอลีชา (ขณะเมื่อท่านพักอยู่ที่เมืองเยรีโค) และท่านพูดกับเขาว่า “ข้ามิได้บอกท่านทั้งหลายแล้วหรือว่า ‘อย่าไปเลย’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 19, 'คนในเมืองพูดกับเอลีชาว่า “ดูเถิด ทําเลเมืองนี้ก็ร่าเริงดี ดังที่เจ้านายของข้าพเจ้าได้เห็นแล้ว แต่ทว่าน้ําไม่ดีและชาวแผ่นดินก็แท้งลูก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 20, 'ท่านพูดว่า “จงเอาชามใหม่มาใบหนึ่ง ใส่เกลือไว้ในนั้น” แล้วเขาทั้งหลายก็หามาให้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 21, 'แล้วท่านก็ไปที่น้ําพุ โยนเกลือลงในนั้นและกล่าวว่า “พระเยโฮวาห์ตรัสดังนี้ว่า เราได้กระทําน้ํานี้ให้ดีแล้ว ตั้งแต่นี้ไปจะไม่มีความตายหรือการแท้งลูกมาจากน้ํานี้อีก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 22, 'ฉะนั้นน้ําจึงดีมาจนถึงทุกวันนี้ จริงตามถ้อยคําซึ่งเอลีชาได้กล่าวนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 23, 'ท่านได้ขึ้นไปจากที่นั่นถึงเมืองเบธเอล และขณะเมื่อท่านขึ้นไปตามทางมีเด็กชายเล็กๆบางคนออกมาจากเมืองล้อเลียนท่านว่า “อ้ายหัวล้าน จงขึ้นไปเถิด อ้ายหัวล้าน จงขึ้นไปเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 24, 'ท่านก็เหลียวดู แล้วจึงแช่งเขาในพระนามพระเยโฮวาห์ และหมีตัวเมียสองตัวออกมาจากป่า ฉีกเด็กชายพวกนั้นเสียสี่สิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 25, 'จากที่นั่นท่านก็ขึ้นไปถึงภูเขาคารเมล และจากที่นั่นท่านก็หันกลับมายังสะมาเรีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 1, 'ในปีที่สิบแปดของรัชกาลเยโฮชาฟัทกษัตริย์แห่งยูดาห์ เยโฮรัมโอรสของอาหับได้เริ่มครอบครองเหนืออิสราเอล ณ กรุงสะมาเรีย และทรงครองอยู่สิบสองปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 2, 'พระองค์ทรงกระทําสิ่งที่ชั่วในสายพระเนตรของพระเยโฮวาห์ แต่ไม่เหมือนราชบิดาและราชมารดาของพระองค์ พระองค์ทรงทําลายเสาศักดิ์สิทธิ์แห่งพระบาอัล ซึ่งราชบิดาของพระองค์ทรงสร้างนั้นเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 3, 'แม้กระนั้นพระองค์ยังทรงเกาะติดอยู่กับบาปทั้งหลายของเยโรโบอัมบุตรชายเนบัท ซึ่งพระองค์ทรงกระทําให้อิสราเอลทําบาปด้วย พระองค์หาได้ทรงพรากจากบาปนั้นไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 4, 'ฝ่ายเมชากษัตริย์แห่งโมอับทรงเป็นผู้ดําเนินกิจการเลี้ยงแกะ และพระองค์ต้องถวายลูกแกะหนึ่งแสนตัว และแกะผู้หนึ่งแสนตัวพร้อมกับขนของมันให้แด่กษัตริย์อิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 5, 'แต่อยู่มาเมื่ออาหับสิ้นพระชนม์แล้ว กษัตริย์แห่งโมอับก็กบฏต่อกษัตริย์แห่งอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 6, 'กษัตริย์เยโฮรัมจึงกรีธาทัพออกจากสะมาเรียในครั้งนั้น และทรงเกณฑ์คนอิสราเอลทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 7, 'พระองค์ทรงส่งสารไปยังเยโฮชาฟัทกษัตริย์แห่งยูดาห์ว่า “กษัตริย์แห่งโมอับได้กบฏต่อข้าพเจ้า ท่านจะไปรบกับโมอับพร้อมกับข้าพเจ้าได้หรือไม่” และท่านว่า “เราจะไป เราก็เป็นดังที่ท่านเป็น และประชาชนของเราก็เป็นดังประชาชนของท่าน บรรดาม้าของเราก็เป็นดังม้าของท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 8, 'แล้วท่านว่า “เราจะขึ้นไปทางใด” เยโฮรัมทรงตอบไปว่า “ไปทางถิ่นทุรกันดารเมืองเอโดม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 9, 'กษัตริย์แห่งอิสราเอลจึงเสด็จไปพร้อมกับกษัตริย์แห่งยูดาห์ และกษัตริย์แห่งเอโดม และเมื่อทั้งสามกษัตริย์เสด็จอ้อมไปได้เจ็ดวันแล้วก็หาน้ําให้กองทัพและให้สัตว์ที่ติดตามมานั้นไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 10, 'แล้วกษัตริย์แห่งอิสราเอลจึงตรัสว่า “อนิจจาเอ๋ย พระเยโฮวาห์ทรงเรียกสามกษัตริย์นี้มาเพื่อจะมอบไว้ในมือของโมอับ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 11, 'และเยโฮชาฟัทตรัสว่า “ที่นี่ไม่มีผู้พยากรณ์ของพระเยโฮวาห์ เพื่อเราจะให้ทูลถามพระเยโฮวาห์หรือ” แล้วข้าราชการคนหนึ่งของกษัตริย์อิสราเอลจึงทูลว่า “เอลีชาบุตรชาฟัทอยู่ที่นี่พระเจ้าข้า เป็นผู้ที่เทน้ําใส่มือเอลียาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 12, 'และเยโฮชาฟัทตรัสว่า “พระวจนะแห่งพระเยโฮวาห์อยู่กับท่าน” กษัตริย์แห่งอิสราเอลและเยโฮชาฟัทและกษัตริย์แห่งเอโดมจึงเสด็จลงไปหาท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 13, 'และเอลีชาทูลกษัตริย์แห่งอิสราเอลว่า “ข้าพระองค์มีเรื่องอะไรเกี่ยวข้องกับพระองค์ เสด็จไปหาผู้พยากรณ์ของเสด็จพ่อและผู้พยากรณ์ของเสด็จแม่ของพระองค์เถิด” แต่กษัตริย์แห่งอิสราเอลตรัสกับท่านว่า “หามิได้ ด้วยพระเยโฮวาห์ทรงเป็นผู้เรียกกษัตริย์ทั้งสามนี้มาเพื่อมอบไว้ในมือของโมอับ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 14, 'และเอลีชาทูลว่า “พระเยโฮวาห์จอมโยธาซึ่งข้าพระองค์ปรนนิบัติทรงพระชนม์อยู่แน่ฉันใด ถ้าข้าพระองค์มิได้เคารพคารวะต่อพระพักตร์เยโฮชาฟัทกษัตริย์แห่งยูดาห์แล้ว ข้าพระองค์จะไม่มองพระพักตร์พระองค์หรือดูแลพระองค์เลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 15, 'ขอทรงนําผู้เล่นเครื่องสายมาให้ข้าพระองค์สักคนหนึ่ง” และต่อมาเมื่อผู้เล่นเครื่องสายบรรเลงแล้ว พระหัตถ์ของพระเยโฮวาห์ก็มาเหนือท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 16, 'และท่านทูลว่า “พระเยโฮวาห์ตรัสดังนี้ว่า ‘ทําหุบเขานี้ให้เป็นสระทั่วไปหมด’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 17, 'เพราะพระเยโฮวาห์ตรัสดังนี้ว่า ‘เจ้าทั้งหลายจะไม่เห็นลมและจะไม่เห็นฝน ถึงอย่างไรก็ดีหุบเขานั้นจะมีน้ําเต็มไปหมด เพื่อเจ้าจะได้ดื่ม ทั้งเจ้า ฝูงสัตว์เลี้ยงและสัตว์ใช้งานของเจ้า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 18, 'เรื่องอย่างนี้เป็นเรื่องเล็กน้อยในสายพระเนตรของพระเยโฮวาห์ พระองค์จะทรงมอบคนโมอับไว้ในมือของเจ้าด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 19, 'เจ้าจะโจมตีเมืองที่มีป้อมทุกเมือง และเมืองเอกทุกเมือง และจะโค่นต้นไม้ลงทุกต้น และจะจุกน้ําพุทุกแห่งเสีย และทําไร่นาที่ดีทุกแปลงให้เสียด้วยหิน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 20, 'และอยู่มาพอรุ่งเช้าประมาณเวลาถวายเครื่องธัญญบูชา ดูเถิด มีน้ํามาจากทางเมืองเอโดม จนแผ่นดินมีน้ําเต็มหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 21, 'และเมื่อคนโมอับทั้งหลายได้ยินว่าบรรดากษัตริย์ยกไปสู้รบกับตน คนที่มีอายุสวมเกราะและสูงขึ้นไปก็ได้รวบรวมกันเข้า และยกไปตั้งที่พรมแดน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 22, 'เมื่อเขาตื่นขึ้นในตอนเช้า และดวงอาทิตย์ส่องแสงอยู่บนน้ํา คนโมอับเห็นน้ําที่อยู่ตรงข้ามกับตนแดงอย่างโลหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 23, 'เขาทั้งหลายกล่าวว่า “นี่เป็นโลหิต บรรดากษัตริย์ได้สู้รบกันเอง และฆ่ากันเอง เพราะฉะนั้นบัดนี้ โมอับเอ๋ย มาริบเอาข้าวของของเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 24, 'แต่เมื่อเขามาถึงค่ายอิสราเอล คนอิสราเอลก็ลุกขึ้นต่อสู้กับคนโมอับจนเขาทั้งหลายหนีไป และเขาก็รุกหน้าเข้าไปในแผ่นดินฆ่าฟันคนโมอับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 25, 'เขาทั้งหลายได้ทลายหัวเมือง และต่างคนก็ต่างโยนหินเข้าไปในไร่นาที่ดีทุกแปลงจนเต็ม เขาจุกน้ําพุเสียทุกแห่ง และโค่นต้นไม้ดีๆเสียหมด จนในคีร์หะเรเชทมีแต่หินของเมืองเหลืออยู่ บรรดานักสลิงได้ล้อมเมืองไว้และโจมตีได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 26, 'เมื่อกษัตริย์แห่งโมอับทรงเห็นว่าจะสู้ไม่ได้ พระองค์ก็ทรงพาพลดาบเจ็ดร้อยคนจะตีฝ่าออกมาทางด้านกษัตริย์เมืองเอโดม แต่ออกมาไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 27, 'แล้วพระองค์ทรงนําโอรสหัวปี ผู้ซึ่งควรจะขึ้นครองแทนนั้น ถวายเป็นเครื่องเผาบูชาเสียที่บนกําแพง และมีพระพิโรธใหญ่ยิ่งต่อพวกอิสราเอล เขาทั้งหลายก็ยกถอยไปจากพระองค์และกลับบ้านเมืองของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 1, 'ภรรยาของคนหนึ่งในเหล่าศิษย์แห่งผู้พยากรณ์ร้องต่อเอลีชาว่า “ผู้รับใช้ของท่าน คือสามีของดิฉันสิ้นชีวิตเสียแล้ว และท่านก็ทราบอยู่แล้วว่าผู้รับใช้ของท่านเกรงกลัวพระเยโฮวาห์ แต่เจ้าหนี้ได้มาเพื่อนําเอาบุตรชายสองคนของดิฉันไปเป็นทาสของเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 2, 'และเอลีชาตอบนางว่า “บอกฉันมาซิว่าจะให้ฉันทําอะไรให้ เจ้ามีอะไรอยู่ในบ้านบ้าง” และนางตอบว่า “สาวใช้ของท่านไม่มีอะไรในบ้านนอกจากน้ํามันหนึ่งไห”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 3, 'แล้วท่านกล่าวว่า “จงออกไปนอกบ้าน ขอยืมภาชนะจากเพื่อนบ้านทุกคนของเจ้ามาเป็นภาชนะเปล่า อย่าให้น้อย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 4, 'แล้วจงเข้าไปในเรือน ปิดประตูขังตัวเจ้าและบุตรชายของเจ้าไว้ และจงเทน้ํามันใส่ภาชนะทั้งหมด เมื่อลูกหนึ่งๆเต็มแล้วก็ตั้งไว้ต่างหาก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 5, 'นางก็ลาไป และปิดประตูขังนางและบุตรชายของนางไว้ บุตรส่งภาชนะมาให้ และนางก็เทน้ํามัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 6, 'และอยู่มาเมื่อภาชนะเต็มหมดแล้วนางจึงบอกบุตรชายว่า “เอาภาชนะมาให้แม่อีกลูกหนึ่ง” และเขาตอบนางว่า “ไม่มีอีกแล้ว” แล้วน้ํามันก็หยุดไหล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 7, 'นางก็ไปเรียนให้คนของพระเจ้าทราบและท่านบอกว่า “ไปซี ขายน้ํามันเสียเอาเงินชําระหนี้ของเจ้า ที่เหลือนอกนั้นเจ้าและบุตรของเจ้าจงใช้เลี้ยงชีวิต”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 8, 'วันหนึ่งเอลีชาเดินต่อไปถึงเมืองชูเนม เป็นที่ที่หญิงมั่งมีคนหนึ่งอาศัยอยู่ และนางได้ชวนท่านให้รับประทานอาหาร ฉะนั้นเมื่อท่านผ่านทางนั้นไปเมื่อไร ท่านก็แวะเข้าไปรับประทานอาหารที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 9, 'และนางได้บอกสามีของนางว่า “ดูเถิด ดิฉันเห็นว่าชายคนนี้เป็นคนบริสุทธิ์ของพระเจ้า เดินผ่านบ้านเราอยู่เนืองๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 10, 'ขอให้เราทําห้องเล็กไว้บนกําแพง วางเตียง โต๊ะ เก้าอี้ และตะเกียงไว้ให้ท่าน เพื่อว่าเมื่อท่านมาหาเรา ท่านจะได้เข้าไปพักในห้องนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 11, 'วันหนึ่งท่านก็มาที่นั่น และแวะเข้าไปในห้องนั้น พักอยู่ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 12, 'ท่านจึงบอกเกหะซีคนใช้ของท่านว่า “ไปเรียกหญิงชาวชูเนมคนนี้มา” เมื่อเขาเรียกนาง นางก็มายืนอยู่ต่อหน้าท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 13, 'ท่านจึงบอกแก่เกหะซีว่า “จงบอกนางว่า ดูเถิด เธอลําบากมากมายอย่างนี้เพื่อเรา จะให้เราทําอะไรให้เธอบ้าง มีอะไรจะให้ทูลกษัตริย์เผื่อเธอหรือ หรือให้พูดอะไรกับผู้บัญชาการกองทัพ” นางตอบว่า “ดิฉันอยู่ในหมู่พวกพี่น้องของดิฉันค่ะ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 14, 'และท่านกล่าวว่า “ถ้าอย่างนั้นจะให้ทําอะไรเพื่อนาง” เกหะซีตอบว่า “แท้จริงนางไม่มีบุตรและสามีของนางก็แก่แล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 15, 'ท่านจึงบอกว่า “ไปเรียกเธอมา” และเมื่อเขาไปเรียกนาง นางก็มายืนอยู่ที่ประตู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 16, 'ท่านกล่าวว่า “ในฤดูนี้เมื่อครบกําหนดอุ้มท้อง เจ้าจะได้อุ้มบุตรชายคนหนึ่ง” และนางตอบว่า “ข้าแต่คนแห่งพระเจ้า เจ้านายของดิฉัน หามิได้ อย่ามุสาแก่สาวใช้ของท่านเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 17, 'แต่หญิงคนนั้นก็ตั้งครรภ์และคลอดบุตรชายคนหนึ่งในฤดูนั้นเมื่อครบกําหนดอุ้มท้องจริงตามที่เอลีชาบอกแก่นางไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 18, 'เมื่อเด็กนั้นโตขึ้น วันหนึ่งเขาออกไปหาบิดาของเขาในหมู่คนเกี่ยวข้าว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 19, 'เขาบอกบิดาของเขาว่า “โอยหัวของฉัน หัวของฉัน” บิดาจึงสั่งคนใช้ของเขาว่า “อุ้มเขาไปหาแม่ไป๊”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 20, 'และเมื่อเขาอุ้มมาให้มารดาของเด็ก เด็กนั้นก็นั่งอยู่บนตักมารดาจนเที่ยงวัน แล้วก็สิ้นชีวิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 21, 'นางจึงอุ้มขึ้นไปวางไว้บนที่นอนของคนแห่งพระเจ้า และปิดประตูเสียแล้วไปข้างนอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 22, 'นางก็ไปเรียกสามีของนางกล่าวว่า “ขอส่งคนใช้คนหนึ่งกับลาตัวหนึ่งมาให้ฉัน เพื่อฉันจะได้รีบไปหาคนแห่งพระเจ้า และกลับมาอีก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 23, 'และเขาถามว่า “จะไปหาท่านทําไมในวันนี้ ไม่ใช่วันขึ้นหนึ่งค่ําหรือวันสะบาโต” นางตอบว่า “ก็ดีอยู่แล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 24, 'นางก็ผูกอานลาและสั่งคนใช้ของนางว่า “จงเร่งลาไปเร็วๆ อย่าให้ฝีเท้าหย่อนลงได้นอกจากฉันสั่ง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 25, 'แล้วนางก็ออกเดิน และมาถึงคนแห่งพระเจ้าที่ภูเขาคารเมล อยู่มาเมื่อคนแห่งพระเจ้าเห็นนางมาแต่ไกล ท่านก็พูดกับเกหะซีคนใช้ของท่านว่า “ดูเถิด หญิงชาวชูเนมมาข้างโน้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 26, 'จงวิ่งไปรับนางทันที และกล่าวแก่นางว่า ‘นางสบายดีหรือ สามีสบายดีหรือ เด็กสบายดีหรือ’” และนางได้ตอบว่า “สบายดีค่ะ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 27, 'และเมื่อนางมายังภูเขาถึงคนแห่งพระเจ้าแล้ว นางก็เข้าไปกอดเท้าของท่าน เกหะซีจึงเข้ามาจะจับนางออกไป แต่คนแห่งพระเจ้าบอกว่า “ปล่อยเขาเถอะ เพราะนางมีใจทุกข์หนัก และพระเยโฮวาห์ทรงซ่อนเรื่องนี้จากฉัน หาได้ตรัสสําแดงแก่ฉันไม่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 28, 'แล้วนางจึงเรียนว่า “ดิฉันขอบุตรชายจากเจ้านายของดิฉันหรือคะ ดิฉันไม่ได้เรียนหรือว่า อย่าลวงดิฉันเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 29, 'ท่านจึงสั่งเกหะซีว่า “คาดเอวของเจ้าเข้า และถือไม้เท้าของเรา และไปเถอะ ถ้าเจ้าพบใคร อย่าสวัสดีกับเขา และถ้าใครสวัสดีกับเจ้าก็อย่าตอบ และจงวางไม้เท้าของเราบนหน้าของเด็กนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 30, 'แล้วมารดาของเด็กนั้นเรียนว่า “พระเยโฮวาห์ทรงพระชนม์อยู่และตัวท่านเองมีชีวิตอยู่แน่ฉันใด ดิฉันจะไม่พรากจากท่านไป” ดังนั้นท่านจึงลุกขึ้นตามนางไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 31, 'เกหะซีได้ล่วงหน้าไปก่อนและวางไม้เท้าบนหน้าของเด็กนั้น แต่ไม่มีเสียงหรืออาการรับรู้ใดๆ เขาจึงกลับมาพบท่านและเรียนท่านว่า “เด็กนั้นยังไม่ตื่น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 32, 'เมื่อเอลีชาเข้ามาในเรือน ดูเถิด ท่านเห็นเด็กนอนตายอยู่บนเตียงของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 33, 'ท่านจึงเข้าไปข้างในปิดประตูให้ทั้งสองอยู่ข้างในและได้อธิษฐานต่อพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 34, 'แล้วท่านขึ้นไปนอนทับเด็ก ให้ปากทับปาก ตาทับตา และมือทับมือ และเมื่อท่านเหยียดตัวของท่านบนเด็ก เนื้อของเด็กนั้นก็อุ่นขึ้นมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 35, 'แล้วท่านก็ลุกขึ้นอีกเดินไปเดินมาในเรือนนั้นครั้งหนึ่ง แล้วขึ้นไปเหยียดตัวของท่านบนเขา เด็กนั้นก็จามเจ็ดครั้ง และเด็กนั้นก็ลืมตาของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 36, 'แล้วท่านก็เรียกเกหะซีมาสั่งว่า “ไปเรียกหญิงชาวชูเนมคนนี้มา” เขาจึงไปเรียกนาง และเมื่อนางมาถึงท่านแล้วท่านว่า “จงอุ้มบุตรชายของเจ้าขึ้นเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 37, 'นางจึงเข้ามาซบหน้าลงที่เท้าของท่านกราบลงถึงดิน แล้วนางก็อุ้มบุตรชายของนางขึ้นออกไปข้างนอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 38, 'เอลีชามาถึงกิลกาลอีก เมื่อแผ่นดินเกิดกันดารอาหาร และเมื่อเหล่าศิษย์แห่งผู้พยากรณ์นั่งอยู่ต่อหน้าท่าน ท่านก็บอกกับคนใช้ของท่านว่า “จงตั้งหม้อลูกใหญ่และต้มข้าวให้แก่เหล่าศิษย์แห่งผู้พยากรณ์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 39, 'คนหนึ่งในพรรคออกไปเก็บผักที่ในทุ่งนา และพบไม้เถาป่าเถาหนึ่ง เขาเก็บได้น้ําเต้าป่าจนเต็มตัก กลับมาหั่นใส่ในหม้อข้าวต้มโดยไม่ทราบว่าเป็นผลอะไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 40, 'เขาก็เทออกให้คนเหล่านั้นรับประทาน ต่อมาขณะที่เขากําลังรับประทานข้าวต้มอยู่นั้น เขาร้องขึ้นว่า “โอ ท่าน คนแห่งพระเจ้า มีความตายอยู่ในหม้อนี้” และเขาก็รับประทานกันไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 41, 'ท่านก็ว่า “จงเอาแป้งมา” ท่านก็ใส่แป้งลงในหม้อ และบอกว่า “จงเทออกให้คนเหล่านั้นรับประทาน” และไม่มีอันตรายอยู่ในหม้อนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 42, 'มีชายคนหนึ่งมาจากบ้านบาอัลชาลิชาห์นําของมาให้คนแห่งพระเจ้า มีขนมปังเป็นผลแรกคือ ขนมข้าวบาร์เลย์ยี่สิบก้อน และรวงข้าวใหม่ใส่กระสอบของเขามาและเอลีชาว่า “จงให้แก่คนเหล่านั้นรับประทาน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 43, 'แต่คนใช้คนนี้ตอบว่า “ข้าพเจ้าจะตั้งอาหารเท่านี้ให้คนหนึ่งร้อยรับประทานได้อย่างไร” ท่านจึงสั่งซ้ําว่า “จงให้คนเหล่านั้นรับประทานเถิด เพราะพระเยโฮวาห์ตรัสสั่งดังนี้ว่า ‘เขาทั้งหลายจะได้รับประทานและยังเหลืออีก’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 44, 'เขาจึงตั้งอาหารไว้ต่อหน้าเขาทั้งหลาย เขาทั้งหลายก็รับประทาน และยังเหลืออยู่จริงตามพระวจนะของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 1, 'นาอามานผู้บัญชาการกองทัพของกษัตริย์ประเทศซีเรียเป็นคนสําคัญมากของกษัตริย์ เป็นคนมีเกียรติ เพราะว่าพระเยโฮวาห์ทรงนําชัยชนะมายังซีเรียโดยท่านนี้ ท่านเป็นวีรบุรุษด้วย แต่ท่านเป็นโรคเรื้อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 2, 'ฝ่ายคนซีเรียยกพวกไปปล้นครั้งหนึ่งนั้น ได้จับเด็กหญิงคนหนึ่งมาจากแผ่นดินอิสราเอลมาเป็นเชลย และเธอมาปรนนิบัติภรรยาของนาอามาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 3, 'เธอได้เรียนนายผู้หญิงของเธอว่า “อยากให้เจ้านายของดิฉันไปอยู่กับผู้พยากรณ์ผู้ซึ่งอยู่ในสะมาเรีย ท่านจะได้รักษาโรคเรื้อนของเจ้านายเสียให้หาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 4, 'นาอามานจึงไปทูลกษัตริย์เจ้านายของท่านว่า “สาวใช้จากแผ่นดินอิสราเอลพูดว่าอย่างนั้นๆ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 5, 'กษัตริย์แห่งซีเรียตรัสว่า “จงไปเถิด เราจะส่งสารไปยังกษัตริย์แห่งอิสราเอล” แล้วท่านก็ไป นําเงินหนักสิบตะลันต์ ทองคําหนักหกพันเชเขล และเสื้อสิบชุดไปด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 6, 'และท่านก็นําสารไปยังกษัตริย์แห่งอิสราเอลใจความว่า “เมื่อสารนี้มาถึงท่าน ดูเถิด ข้าพเจ้าได้ส่งนาอามานข้าราชการของข้าพเจ้ามา เพื่อขอให้ท่านรักษาเขาให้หายจากโรคเรื้อน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 7, 'และอยู่มาเมื่อกษัตริย์แห่งอิสราเอลทรงอ่านสารนั้นแล้ว พระองค์ก็ทรงฉีกฉลองพระองค์ตรัสว่า “เราเป็นพระเจ้าซึ่งจะให้ตายและให้มีชีวิตหรือ ชายคนนี้จึงส่งสารมาให้เรารักษาคนหนึ่งที่เป็นโรคเรื้อน ขอใคร่ครวญดูเถิดว่า เขาแสวงหาเหตุพิพาทกับเราอย่างไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 8, 'แต่เมื่อเอลีชาคนแห่งพระเจ้าได้ยินว่ากษัตริย์แห่งอิสราเอลได้ทรงฉีกฉลองพระองค์ จึงใช้คนไปทูลกษัตริย์ว่า “ไฉนพระองค์จึงทรงฉีกฉลองพระองค์ของพระองค์เสีย ขอให้เขามาหาข้าพระองค์เถิด เพื่อเขาจะได้ทราบว่า มีผู้พยากรณ์คนหนึ่งในอิสราเอล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 9, 'นาอามานจึงมาพร้อมกับบรรดาม้าและรถรบของท่าน มาหยุดอยู่ที่ประตูเรือนของเอลีชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 10, 'เอลีชาก็ส่งผู้สื่อสารมาเรียนท่านว่า “ขอจงไปชําระตัวในแม่น้ําจอร์แดนเจ็ดครั้ง และเนื้อของท่านจะกลับคืนเป็นอย่างเดิม และท่านจะสะอาด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 11, 'แต่นาอามานก็โกรธและไปเสีย บ่นว่า “ดูเถิด ข้าคิดว่าเขาจะออกมาหาข้าเป็นแน่ และมายืนอยู่และออกพระนามของพระเยโฮวาห์พระเจ้าของเขา แล้วโบกมือเหนือที่นั้นให้โรคเรื้อนหาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 12, 'อาบานาและฟารปาร์แม่น้ําเมืองดามัสกัสไม่ดีกว่าบรรดาลําน้ําแห่งอิสราเอลดอกหรือ ข้าจะชําระตัวในแม่น้ําเหล่านั้นและจะสะอาดไม่ได้หรือ” ท่านจึงหันตัวแล้วไปเสียด้วยความเดือดดาล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 13, 'แต่พวกข้าราชการของท่านเข้ามาใกล้และเรียนท่านว่า “คุณพ่อของข้าพเจ้า ถ้าท่านผู้พยากรณ์จะสั่งให้ท่านกระทําสิ่งใหญ่โตประการหนึ่ง ท่านจะไม่กระทําหรือ ถ้าเช่นนั้นเมื่อท่านผู้พยากรณ์กล่าวแก่ท่านว่า ‘จงไปล้างและสะอาดเถิด’ ควรท่านจะทํายิ่งขึ้นเท่าใด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 14, 'ท่านจึงลงไปจุ่มตัวเจ็ดครั้งในแม่น้ําจอร์แดนตามถ้อยคําของคนแห่งพระเจ้า และเนื้อของท่านก็กลับคืนเป็นอย่างเนื้อเด็กเล็กๆ และท่านก็สะอาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 15, 'แล้วท่านจึงกลับไปยังคนแห่งพระเจ้า ทั้งตัวท่านและพรรคพวกของท่าน และท่านมายืนอยู่ข้างหน้าเอลีชาและท่านกล่าวว่า “ดูเถิด บัดนี้ข้าพเจ้าทราบแล้วว่าไม่มีพระเจ้าทั่วไปในโลกนอกจากที่ในอิสราเอล เพราะฉะนั้นบัดนี้ขอท่านรับของกํานัลสักอย่างหนึ่งจากผู้รับใช้ของท่านเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 16, 'แต่ท่านตอบว่า “พระเยโฮวาห์ซึ่งข้าพเจ้าปรนนิบัติทรงพระชนม์อยู่แน่ฉันใด ข้าพเจ้าจะไม่รับสิ่งใดเลยฉันนั้น” และท่านก็ได้ชักชวนให้รับไว้แต่เอลีชาได้ปฏิเสธ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 17, 'แล้วนาอามานจึงกล่าวว่า “มิฉะนั้นขอท่านได้โปรดให้ดินบรรทุกล่อสักสองตัวให้แก่ผู้รับใช้ของท่านเถิด เพราะตั้งแต่นี้ไปผู้รับใช้ของท่านจะไม่ถวายเครื่องเผาบูชาหรือเครื่องสัตวบูชาแก่พระอื่น แต่จะถวายแด่พระเยโฮวาห์เท่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 18, 'ในเรื่องนี้ขอพระเยโฮวาห์ทรงโปรดให้อภัยแก่ผู้รับใช้ของท่าน ในเมื่อนายของข้าพเจ้าไปในนิเวศของพระริมโมนเพื่อจะนมัสการที่นั่น ทรงพิงอยู่ที่มือของข้าพเจ้า และข้าพเจ้าจะต้องโน้มคํานับในนิเวศของพระริมโมน เมื่อข้าพเจ้าโน้มตัวลงในนิเวศของพระริมโมนนั้น ขอพระเยโฮวาห์ทรงให้อภัยแก่ผู้รับใช้ของท่านในกรณีนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 19, 'เอลีชาจึงตอบท่านว่า “จงไปโดยสันติภาพเถิด” แต่เมื่อนาอามานออกไปได้ไม่ไกลนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 20, 'เกหะซีคนใช้ของเอลีชาคนแห่งพระเจ้าคิดว่า “ดูเถิด นายของข้าพเจ้าไม่ยอมรับจากมือของนาอามานคนซีเรียซึ่งของที่ท่านนํามา พระเยโฮวาห์ทรงพระชนม์อยู่แน่ฉันใด ข้าพเจ้าจะวิ่งตามไปเอามาจากเขาบ้าง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 21, 'เกหะซีจึงตามนาอามานไป และเมื่อนาอามานแลเห็นว่ามีคนวิ่งตามท่านมา ท่านก็ลงจากรถรบต้อนรับเขาพูดว่า “ทุกอย่างเรียบร้อยดีหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 22, 'เขาตอบว่า “เรียบร้อยดี นายของข้าพเจ้าใช้ข้าพเจ้ามา กล่าวว่า ‘ดูเถิด มีชายหนุ่มสองคนในเหล่าศิษย์แห่งผู้พยากรณ์ มาจากแดนเทือกเขาเอฟราอิม ขอท่านโปรดให้เงินแก่เขาทั้งหลายสักหนึ่งตะลันต์และเสื้อสักสองชุด’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 23, 'และนาอามานกล่าวว่า “ขอโปรดรับไปสองตะลันต์เถิด” ท่านก็เชิญชวนเขา และเอาเงินสองตะลันต์ใส่กระสอบผูกไว้ พร้อมกับเสื้อสองตัว ให้คนใช้สองคนแบกไป เขาก็แบกเดินขึ้นหน้าเกหะซีมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 24, 'เมื่อเขามาถึงภูเขา เกหะซีก็รับมาจากมือของเขาทั้งสอง เอาไปเก็บไว้ในเรือนและให้คนเหล่านั้นกลับ เขาทั้งสองก็จากไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 25, 'เกหะซีก็เข้าไปยืนอยู่ต่อหน้านายของตน และเอลีชาถามเขาว่า “เกหะซี เจ้าไปไหนมา” เขาตอบว่า “ผู้รับใช้ของท่านไม่ได้ไปไหน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 26, 'แต่ท่านกล่าวแก่เขาว่า “เมื่อชายคนนั้นหันมาจากรถรบต้อนรับเจ้านั้น จิตใจของเรามิได้ไปกับเจ้าดอกหรือ นั่นเป็นเวลาควรที่จะรับเงิน รับเสื้อผ้า สวนต้นมะกอกเทศ และสวนองุ่น แกะและวัว และคนใช้ชายหญิงหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 27, 'ฉะนั้นโรคเรื้อนของนาอามานจะติดอยู่ที่เจ้าและที่เชื้อสายของเจ้าเป็นนิตย์” เขาก็ออกไปจากหน้าท่านเป็นโรคเรื้อนขาวอย่างหิมะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 1, 'ฝ่ายเหล่าศิษย์แห่งผู้พยากรณ์กล่าวกับเอลีชาว่า “ดูเถิด สถานที่ซึ่งข้าพเจ้าทั้งหลายอยู่ใต้ความดูแลของท่านนั้นก็เล็กเกินไป ไม่พอแก่พวกเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 2, 'ขอให้เราไปที่แม่น้ําจอร์แดน ต่างคนต่างเอาไม้ท่อนหนึ่งมาสร้างที่อาศัยของเราที่นั่น” และท่านตอบว่า “ไปเถอะ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 3, 'แล้วคนหนึ่งกล่าวว่า “ขอท่านโปรดไปกับผู้รับใช้ของท่านด้วย” และท่านก็ตอบว่า “ข้าจะไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 4, 'ท่านก็ไปกับเขาทั้งหลาย และเมื่อเขามาถึงแม่น้ําจอร์แดนเขาก็โค่นต้นไม้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 5, 'ขณะที่คนหนึ่งฟันไม้อยู่ หัวขวานของเขาตกลงไปในน้ํา และเขาร้องขึ้นว่า “อนิจจา นายครับ ขวานนั้นผมขอยืมเขามา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 6, 'แล้วคนแห่งพระเจ้าถามว่า “ขวานนั้นตกที่ไหน” เมื่อเขาชี้ที่ให้ท่านแล้ว ท่านก็ตัดไม้อันหนึ่งทิ้งลงไปที่นั่น ทําให้ขวานเหล็กนั้นลอยขึ้นมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 7, 'และท่านบอกว่า “หยิบขึ้นมาซิ” เขาก็เอื้อมมือไปหยิบขึ้นมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 8, 'ฝ่ายกษัตริย์แห่งซีเรียรบพุ่งกับอิสราเอล พระองค์ปรึกษากับข้าราชการของพระองค์ว่า “เราจะตั้งค่ายของเราที่นั่นๆ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 9, 'แต่คนแห่งพระเจ้าส่งข่าวไปยังกษัตริย์แห่งอิสราเอลว่า “ขอพระองค์ทรงระวังอย่าผ่านมาทางนั้น เพราะคนซีเรียกําลังยกลงไปที่นั่น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 10, 'และกษัตริย์แห่งอิสราเอลทรงใช้ให้ไปยังสถานที่ซึ่งคนแห่งพระเจ้าบอกและเตือนให้ พระองค์จึงทรงระวังตัวได้ที่นั่นมิใช่เพียงครั้งสองครั้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 11, 'กษัตริย์แห่งซีเรียก็ไม่สบายพระทัยมากเพราะเรื่องนี้ พระองค์จึงทรงเรียกข้าราชการมาตรัสว่า “พวกท่านจะไม่บอกเราหรือว่า คนใดในพวกเราที่อยู่ฝ่ายกษัตริย์แห่งอิสราเอล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 12, 'ข้าราชการคนหนึ่งของพระองค์ทูลว่า “โอ ข้าแต่กษัตริย์ เจ้านายของข้าพระองค์ ไม่มีผู้ใดพระเจ้าข้า แต่เอลีชาผู้พยากรณ์ซึ่งอยู่ในอิสราเอลทูลบรรดาถ้อยคําซึ่งพระองค์ตรัสในห้องบรรทมของพระองค์ให้แก่กษัตริย์แห่งอิสราเอล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 13, 'พระองค์จึงตรัสว่า “จงไปหาดูว่า เขาอยู่ที่ไหน เพื่อเราจะใช้คนไปจับเขามา” มีคนทูลพระองค์ว่า “ดูเถิด เขาอยู่ในโดธาน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 14, 'พระองค์จึงทรงส่งม้า รถรบ และกองทัพใหญ่ เขาไปกันในกลางคืนและล้อมเมืองนั้นไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 15, 'เมื่อคนใช้ของคนแห่งพระเจ้าตื่นขึ้นเวลาเช้าตรู่และออกไป ดูเถิด กองทัพพร้อมกับม้าและรถรบก็ล้อมเมืองไว้ และคนใช้นั้นบอกท่านว่า “อนิจจา นายของข้าพเจ้า เราจะทําอย่างไรดี”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 16, 'ท่านตอบว่า “อย่ากลัวเลย เพราะฝ่ายเรามีมากกว่าฝ่ายเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 17, 'แล้วเอลีชาก็อธิษฐานว่า “ข้าแต่พระเยโฮวาห์ ขอทรงเบิกตาของเขาเพื่อเขาจะได้เห็น” และพระเยโฮวาห์ทรงเบิกตาของชายหนุ่มคนนั้น และเขาก็ได้เห็นและดูเถิด ที่ภูเขาก็เต็มไปด้วยม้า และรถรบเพลิงอยู่รอบเอลีชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 18, 'และเมื่อคนซีเรียลงมารบกับท่าน เอลีชาก็อธิษฐานต่อพระเยโฮวาห์ว่า “ขอทรงโปรดให้คนเหล่านี้ตาบอดไปเสีย” พระองค์จึงทรงให้เขาทั้งหลายตาบอดไปตามคําของเอลีชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 19, 'และเอลีชาบอกคนเหล่านั้นว่า “ไม่ใช่ทางนี้ และไม่ใช่เมืองนี้ จงตามข้ามา และข้าจะพาไปยังคนนั้นซึ่งเจ้าแสวงหา” และท่านก็พาเขาไปกรุงสะมาเรีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 20, 'และอยู่มาพอเข้าไปในกรุงสะมาเรีย เอลีชาก็ทูลว่า “ข้าแต่พระเยโฮวาห์ ขอทรงเบิกตาของคนเหล่านี้ เพื่อเขาจะเห็นได้” พระเยโฮวาห์จึงทรงเบิกตาของเขาทั้งหลายและเขาทั้งหลายก็เห็น และดูเถิด เขามาอยู่กลางกรุงสะมาเรีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 21, 'และเมื่อกษัตริย์แห่งอิสราเอลเห็นเขาเข้า จึงตรัสแก่เอลีชาว่า “บิดาของข้าพเจ้า จะให้ข้าพเจ้าฆ่าเขาเสียหรือ จะให้ข้าพเจ้าฆ่าเขาเสียหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 22, 'ท่านก็ทูลตอบว่า “ขอพระองค์อย่าทรงประหารเขาเสีย พระองค์จะประหารคนที่จับมาเป็นเชลยเสียด้วยดาบและด้วยธนูของพระองค์หรือ ขอทรงโปรดจัดอาหารและน้ําต่อหน้าเขา เพื่อให้เขารับประทานและดื่ม แล้วปล่อยให้เขาไปหาเจ้านายของเขาเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 23, 'พระองค์จึงทรงจัดการเลี้ยงใหญ่ให้เขา และเมื่อเขาได้กินและดื่มแล้วก็ทรงปล่อยเขาไป และเขาทั้งหลายได้กลับไปหาเจ้านายของตน และพวกซีเรียมิได้มาปล้นในแผ่นดินอิสราเอลอีกเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 24, 'และอยู่มาภายหลังเบนฮาดัดกษัตริย์แห่งซีเรียทรงจัดกองทัพทั้งสิ้นของพระองค์แล้วได้เสด็จขึ้นไปล้อมกรุงสะมาเรีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 25, 'มีการกันดารอาหารอย่างหนักในสะมาเรีย และดูเถิด พวกเขาล้อมอยู่จนหัวลาตัวหนึ่งเขาขายกันเป็นเงินแปดสิบเชเขล และมูลนกเขาครึ่งลิตรเป็นเงินห้าเชเขล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 26, 'ขณะที่กษัตริย์แห่งอิสราเอลทรงผ่านไปบนกําแพง มีผู้หญิงคนหนึ่งร้องทูลพระองค์ว่า “โอ ข้าแต่กษัตริย์ เจ้านายของข้าพระองค์ ขอทรงช่วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 27, 'พระองค์ตรัสว่า “ถ้าพระเยโฮวาห์มิได้ทรงช่วยเจ้า เราจะช่วยเจ้าได้จากไหน จากลานนวดข้าวหรือจากบ่อย่ําองุ่นหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 28, 'และกษัตริย์ทรงถามนางว่า “เจ้าเป็นอะไรไป” นางทูลตอบว่า “หญิงคนนี้บอกข้าพระองค์ว่า ‘เอาลูกชายของเจ้ามาให้เรากินเสียวันนี้เถิด และเราจะกินลูกชายของฉันวันพรุ่งนี้’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 29, 'เราจึงต้มลูกชายของข้าพระองค์และกิน และรุ่งขึ้นข้าพระองค์ก็พูดกับนางว่า ‘เอาลูกชายของเจ้ามา เพื่อเราจะกินเสีย’ และนางก็ซ่อนลูกชายของนางเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 30, 'และต่อมาเมื่อกษัตริย์ทรงได้ยินถ้อยคําของหญิงนั้น พระองค์ก็ฉีกฉลองพระองค์ พระองค์กําลังดําเนินอยู่บนกําแพง ประชาชนก็มองดู ดูเถิด พระองค์ทรงฉลองพระองค์ผ้ากระสอบอยู่แนบเนื้อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 31, 'และพระองค์ตรัสว่า “ถ้าศีรษะของเอลีชาบุตรชาฟัทยังอยู่บนเขาในวันนี้ ก็ขอพระเจ้าทรงลงโทษแก่เราและให้หนักยิ่งกว่า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 32, 'แต่เอลีชานั่งอยู่ในบ้านของท่าน และพวกผู้ใหญ่ก็นั่งอยู่ด้วย กษัตริย์ทรงใช้คนมาจากต่อเบื้องพระพักตร์พระองค์ แต่ก่อนที่ผู้สื่อสารจะมาถึง เอลีชาก็พูดกับพวกผู้ใหญ่ว่า “ท่านทั้งหลายเห็นหรือไม่เล่า ที่บุตรชายของฆาตกรคนนี้ใช้คนมาเอาศีรษะของข้าพเจ้า ดูเถิด เมื่อผู้สื่อสารมา จงปิดประตู และยึดประตูให้แน่นกันเขาไว้ เสียงเท้าของนายของเขาตามเขามามิใช่หรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 33, 'ขณะที่ท่านยังพูดกับเขาทั้งหลายอยู่ ดูเถิด ผู้สื่อสารลงมาหาท่าน และบอกว่า “ดูเถิด เหตุร้ายนี้มาจากพระเยโฮวาห์ ข้าพเจ้าจะรอคอยพระเยโฮวาห์อีกทําไม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 1, 'แต่เอลีชาบอกว่า “ขอฟังพระวจนะของพระเยโฮวาห์ พระเยโฮวาห์ตรัสดังนี้ว่า พรุ่งนี้ประมาณเวลานี้ยอดแป้งถังหนึ่งเขาจะขายกันหนึ่งเชเขล และข้าวบาร์เลย์สองถังเชเขล ที่ประตูเมืองสะมาเรีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 2, 'แล้วนายทหารคนสนิทของกษัตริย์ตอบคนแห่งพระเจ้าว่า “ดูเถิด ถ้าแม้พระเยโฮวาห์ทรงสร้างหน้าต่างในฟ้าสวรรค์ สิ่งนี้จะเป็นขึ้นได้หรือ” แต่ท่านบอกว่า “ดูเถิด ท่านจะเห็นกับตาของท่านเอง แต่จะไม่ได้กิน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 3, 'มีคนโรคเรื้อนสี่คนอยู่ที่ทางเข้าประตูเมือง เขาพูดกันว่า “เราจะนั่งที่นี่จนตายทําไมเล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 4, 'ถ้าเราว่า ‘ให้เราเข้าไปในเมือง’ การกันดารอาหารก็อยู่ในเมือง และเราก็จะตายที่นั่น และถ้าเรานั่งที่นี่เราก็ตายเหมือนกัน ฉะนั้นบัดนี้จงมาเถิด ให้เราเข้าไปในกองทัพของคนซีเรีย ถ้าเขาไว้ชีวิตของเรา เราก็จะรอดตาย ถ้าเขาฆ่าเรา ก็ได้แต่ตายเท่านั้นเอง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 5, 'ดังนั้นเขาจึงลุกขึ้นในเวลาโพล้เพล้เพื่อจะไปยังค่ายของคนซีเรีย แต่เมื่อเขามาถึงริมค่ายของคนซีเรียแล้ว ดูเถิด ไม่มีใครที่นั่นสักคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 6, 'เพราะองค์พระผู้เป็นเจ้าได้ทรงกระทําให้กองทัพของคนซีเรียได้ยินเสียงรถรบ เสียงม้า และเสียงกองทัพใหญ่ เขาจึงพูดกันและกันว่า “ดูเถิด กษัตริย์แห่งอิสราเอลได้จ้างบรรดากษัตริย์แห่งคนฮิตไทต์ และบรรดากษัตริย์แห่งอียิปต์มารบเราแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 7, 'เขาจึงลุกขึ้นหนีไปในเวลาโพล้เพล้ และทิ้งเต็นท์ ม้าและลาของเขา ทิ้งค่ายไว้อย่างนั้นเอง และหนีไปเอาชีวิตรอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 8, 'และเมื่อคนโรคเรื้อนเหล่านี้มาถึงที่ริมค่าย เขาก็เข้าไปในเต็นท์หนึ่งกินและดื่ม และขนเงิน ทองคําและเสื้อผ้าเอาไปซ่อนไว้ แล้วเขาก็กลับมาเข้าไปในอีกเต็นท์หนึ่งขนเอาข้าวของออกไปจากที่นั่นด้วยเอาไปซ่อนไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 9, 'แล้วเขาพูดกันและกันว่า “เราทําไม่ถูกเสียแล้ว วันนี้เป็นวันข่าวดี ถ้าเรานิ่งอยู่และคอยจนแสงอรุณขึ้นโทษจะตกอยู่กับเรา เพราะฉะนั้นบัดนี้มาเถิด ให้เราไปบอกยังสํานักพระราชวัง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 10, 'เขาจึงมาเรียกนายประตูเมือง และบอกเรื่องราวแก่เขาว่า “เรามายังค่ายของคนซีเรีย และดูเถิด เราไม่เห็นใครและไม่ได้ยินเสียงผู้ใดที่นั่น มีแต่ม้าผูกอยู่ และลาผูกอยู่ และเต็นท์ตั้งอยู่อย่างนั้นเอง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 11, 'แล้วเขาบอกแก่เหล่านายประตู และพวกเขาก็บอกกันไปถึงสํานักพระราชวัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 12, 'กษัตริย์ก็ทรงตื่นบรรทมในกลางคืน และตรัสกับข้าราชการว่า “เราจะบอกให้ว่าคนซีเรียเตรียมสู้รบเราอย่างไร เขาทั้งหลายรู้อยู่ว่าเราหิว เขาจึงออกไปซ่อนตัวอยู่นอกค่ายที่กลางทุ่งคิดว่า ‘เมื่อเขาออกมาจากในเมืองเราจะจับเขาทั้งเป็น แล้วจะเข้าไปในเมือง’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 13, 'และข้าราชการคนหนึ่งทูลว่า “ขอรับสั่งให้คนเอาม้าที่เหลืออยู่ในเมืองสักห้าตัว (ดูเถิด บางทีม้าเหล่านั้นจะยังเป็นอยู่อย่างคนอิสราเอลที่เหลืออยู่ในเมือง หรือดูเถิด จะเป็นอย่างคนอิสราเอลที่ได้พินาศแล้วก็ช่างเถิด) ขอให้เราส่งคนไปดู”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 14, 'เขาจึงเอาม้ากับรถรบสองคัน และกษัตริย์ทรงส่งให้ไปติดตามกองทัพของคนซีเรีย ตรัสว่า “จงไปดู”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 15, 'เขาทั้งหลายจึงติดตามไปจนถึงแม่น้ําจอร์แดน และดูเถิด ตลอดทางมีเสื้อผ้าและเครื่องใช้ ซึ่งคนซีเรียทิ้งเมื่อเขารีบหนีไป ผู้สื่อสารก็กลับมาทูลกษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 16, 'แล้วประชาชนก็ยกออกไปปล้นเต็นท์ทั้งหลายของคนซีเรีย ยอดแป้งจึงขายกันถังละเชเขล และข้าวบาร์เลย์สองถังเชเขล ตามพระวจนะของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 17, 'ฝ่ายกษัตริย์ทรงแต่งตั้งนายทหารคนสนิทให้เป็นนายประตู และประชาชนก็เหยียบไปบนเขาตรงประตู เขาจึงสิ้นชีวิตตามซึ่งคนแห่งพระเจ้าได้กล่าวไว้ในวันเมื่อกษัตริย์เสด็จลงมาหาท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 18, 'และเป็นไปตามที่คนแห่งพระเจ้าได้ทูลกษัตริย์ว่า “ข้าวบาร์เลย์สองถังขายหนึ่งเชเขล และยอดแป้งหนึ่งถังหนึ่งเชเขล ประมาณเวลานี้ในวันพรุ่งนี้ที่ประตูเมืองสะมาเรีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 19, 'และนายทหารคนสนิทก็ได้ตอบคนแห่งพระเจ้าว่า “ดูเถิด ถ้าแม้พระเยโฮวาห์ทรงสร้างหน้าต่างในฟ้าสวรรค์ สิ่งนี้จะเป็นขึ้นได้หรือ” และท่านได้ตอบว่า “ดูเถิด ท่านจะเห็นกับตาของท่านเองแต่จะไม่ได้กิน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 20, 'และอยู่มาก็บังเกิดเป็นดังนั้นแก่เขา เพราะประชาชนเหยียบไปบนเขาที่ประตูเมืองและเขาก็ได้สิ้นชีวิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 1, 'ฝ่ายเอลีชาได้บอกหญิงคนที่ท่านได้ให้บุตรชายของนางกลับคืนชีวิตมาว่า “จงลุกขึ้นและออกไปทั้งครัวเรือนของเจ้า ไปอาศัยอยู่ที่ใดซึ่งเจ้าจะอาศัยอยู่ได้ เพราะพระเยโฮวาห์ทรงเรียกให้เกิดการกันดารอาหาร และจะเป็นแก่แผ่นดินนี้เจ็ดปี”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 2, 'หญิงคนนั้นก็ลุกขึ้นกระทําตามถ้อยคําของคนแห่งพระเจ้า นางยกออกไปทั้งครัวเรือนของนาง ไปอาศัยอยู่ในแผ่นดินฟีลิสเตียเจ็ดปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 3, 'และอยู่มาเมื่อสิ้นเจ็ดปีแล้วหญิงคนนั้นก็กลับมาจากแผ่นดินฟีลิสเตีย และได้ออกไปทูลอุทธรณ์ต่อกษัตริย์เพื่อขอบ้านและที่ดินของนางคืน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 4, 'ฝ่ายกษัตริย์กําลังตรัสกับเกหะซีคนใช้ของคนแห่งพระเจ้าอยู่ว่า “จงบอกเราถึงบรรดามหกิจที่เอลีชาได้กระทํา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 5, 'และอยู่มาเมื่อเขากําลังทูลกษัตริย์ถึงเรื่องที่เอลีชาได้เรียกชีวิตของศพคนหนึ่งกลับคืนมา ดูเถิด ผู้หญิงคนที่ท่านได้ให้บุตรชายกลับคืนชีวิตมาได้อุทธรณ์ต่อกษัตริย์เพื่อขอบ้านและที่ดินของนางคืน และเกหะซีทูลว่า “โอ ข้าแต่กษัตริย์ เจ้านายของข้าพระองค์ นี่เป็นนางคนนั้น และคนนี้แหละเป็นบุตรชายของนาง ซึ่งเอลีชาได้ให้กลับคืนชีวิตมา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 6, 'และเมื่อกษัตริย์ตรัสถามหญิงคนนั้น นางก็ทูลเรื่องถวายพระองค์ กษัตริย์จึงทรงตั้งเจ้าหน้าที่คนหนึ่งให้แก่นางรับสั่งว่า “จงจัดการคืนทุกสิ่งที่เป็นของของนาง พร้อมทั้งพืชผลของนานั้น ตั้งแต่วันที่นางออกจากแผ่นดินมาจนถึงบัดนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 7, 'ฝ่ายเอลีชามายังดามัสกัส เบนฮาดัดกษัตริย์แห่งซีเรียทรงประชวร และเมื่อมีคนทูลว่า “คนแห่งพระเจ้ามาที่นี่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 8, 'กษัตริย์ตรัสกับฮาซาเอลว่า “จงนําของกํานัลไปพบคนแห่งพระเจ้า ให้ทูลถามพระเยโฮวาห์โดยท่านว่า ‘ข้าพเจ้าจะหายป่วยไหม’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 9, 'ฮาซาเอลจึงไปพบท่านนําของกํานัลไปด้วย คือสินค้าอย่างดีทุกอย่างของเมืองดามัสกัสจํานวนเท่าอูฐสี่สิบตัวบรรทุกได้ และเขามายืนอยู่ต่อหน้าท่าน กล่าวว่า “บุตรของท่านคือเบนฮาดัด กษัตริย์แห่งซีเรีย ได้ทรงใช้ข้าพเจ้ามาหาท่าน กล่าวว่า ‘ข้าพเจ้าจะหายป่วยหรือ’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 10, 'และเอลีชาตอบเขาว่า “จงไปทูลพระองค์ว่า ‘พระองค์จะทรงหายประชวรแน่’ แต่พระเยโฮวาห์ทรงสําแดงแก่ข้าพเจ้าว่า พระองค์จะสิ้นพระชนม์แน่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 11, 'และท่านก็เพ่งหน้าจ้องมองเขาแน่นิ่งจนเขาอาย และคนแห่งพระเจ้าก็ร้องไห้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 12, 'และฮาซาเอลถามว่า “เหตุใดเจ้านายของข้าพเจ้าจึงร้องไห้” ท่านตอบว่า “เพราะข้าพเจ้าทราบถึงเหตุร้ายซึ่งท่านจะกระทําต่อประชาชนอิสราเอล ท่านจะเอาไฟเผาป้อมปราการของเขาเสีย และท่านจะสังหารคนหนุ่มๆเสียด้วยดาบ และจับเด็กๆโยนลง และผ่าท้องหญิงที่มีครรภ์เสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 13, 'และฮาซาเอลตอบว่า “ผู้รับใช้ของท่านผู้เป็นแต่เพียงสุนัขเป็นใครเล่า ซึ่งจะกระทําสิ่งใหญ่โตนี้” เอลีชาตอบว่า “พระเยโฮวาห์ทรงสําแดงแก่ข้าพเจ้าว่า ท่านจะเป็นกษัตริย์ครอบครองประเทศซีเรีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 14, 'และเขาก็ไปจากเอลีชามายังนายของตน ผู้ซึ่งถามเขาว่า “เอลีชาว่าอย่างไรกับเจ้าบ้าง” และเขาทูลตอบว่า “เขาบอกว่าพระองค์จะหายประชวรแน่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 15, 'และอยู่มาในวันรุ่งขึ้นเขาก็เอาผ้าหนาทึบจุ่มน้ําคลุมพระพักตร์พระองค์ไว้ จนพระองค์สิ้นพระชนม์ และฮาซาเอลก็ขึ้นครองแทน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 16, 'ในปีที่ห้าแห่งโยรัมโอรสอาหับกษัตริย์ของอิสราเอล เมื่อเยโฮชาฟัทยังเป็นกษัตริย์ของยูดาห์อยู่ เยโฮรัมโอรสเยโฮชาฟัทกษัตริย์ของยูดาห์ได้ทรงเริ่มครอบครอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 17, 'เมื่อพระองค์ทรงเริ่มครอบครองนั้นมีพระชนมายุสามสิบสองพรรษา และพระองค์ทรงครอบครองในเยรูซาเล็มแปดปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 18, 'และพระองค์ทรงดําเนินตามมรรคาของบรรดากษัตริย์แห่งอิสราเอล ตามอย่างที่ราชวงศ์อาหับกระทํา เพราะว่าธิดาของอาหับเป็นมเหสีของพระองค์ และพระองค์ทรงกระทําชั่วในสายพระเนตรของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 19, 'อย่างไรก็ดีพระเยโฮวาห์จะไม่ทรงทําลายยูดาห์ เพราะทรงเห็นแก่ดาวิดผู้รับใช้ของพระองค์ เหตุที่พระองค์ได้ตรัสสัญญาว่า จะทรงประทานประทีปแก่ดาวิด และแก่ราชโอรสของพระองค์เป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 20, 'ในรัชกาลของพระองค์เอโดมได้กบฏออกห่างจากการปกครองของยูดาห์ และตั้งกษัตริย์ขึ้นเหนือตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 21, 'แล้วโยรัมก็เสด็จพร้อมกับบรรดารถรบของพระองค์ผ่านไปถึงศาอีร์ พอกลางคืนพระองค์ก็ลุกขึ้นโจมตีคนเอโดมซึ่งมาล้อมพระองค์นั้น พร้อมกับผู้บัญชาการรถรบ แล้วกองทัพได้หนีกลับเต็นท์เสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 22, 'เอโดมจึงได้กบฏออกห่างจากการปกครองของยูดาห์จนทุกวันนี้ แล้วลิบนาห์ก็ได้กบฏในคราวเดียวกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 23, 'ส่วนพระราชกิจนอกนั้นของโยรัม และบรรดาสิ่งซึ่งพระองค์ทรงกระทํา มิได้บันทึกไว้ในหนังสือพงศาวดารแห่งกษัตริย์ประเทศยูดาห์หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 24, 'โยรัมจึงทรงล่วงหลับไปอยู่กับบรรพบุรุษของพระองค์ และเขาฝังไว้กับบรรพบุรุษของพระองค์ในนครดาวิด และอาหัสยาห์โอรสของพระองค์ได้ขึ้นครองแทน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 25, 'ในปีที่สิบสองแห่งรัชกาลโยรัมโอรสของอาหับกษัตริย์แห่งอิสราเอล อาหัสยาห์โอรสเยโฮรัมกษัตริย์แห่งยูดาห์ได้ทรงเริ่มครอบครอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 26, 'เมื่ออาหัสยาห์ทรงเริ่มครอบครองนั้นมีพระชนมายุยี่สิบสองพรรษา และทรงครอบครองในเยรูซาเล็มหนึ่งปี พระราชมารดาของพระองค์ทรงพระนามอาธาลิยาห์ พระนางเป็นธิดาของอมรีกษัตริย์แห่งอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 27, 'พระองค์ทรงดําเนินตามมรรคาราชวงศ์ของอาหับด้วย และทรงกระทําชั่วในสายพระเนตรของพระเยโฮวาห์ ดังที่ราชวงศ์ของอาหับได้กระทํา เพราะทรงเป็นราชบุตรเขยในราชวงศ์ของอาหับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 28, 'พระองค์เสด็จกับโยรัมโอรสของอาหับเพื่อทําสงครามกับฮาซาเอลกษัตริย์แห่งซีเรียที่ราโมทกิเลอาด และคนซีเรียกระทําให้โยรัมบาดเจ็บ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 29, 'และกษัตริย์โยรัมได้กลับมารักษาพระองค์ที่ยิสเรเอลให้หายบาดเจ็บจากที่คนซีเรียได้กระทําแก่พระองค์ที่รามาห์ เมื่อพระองค์ทรงสู้กันกับฮาซาเอลกษัตริย์แห่งซีเรีย และอาหัสยาห์โอรสของเยโฮรัมกษัตริย์แห่งยูดาห์ได้เสด็จลงไปหาโยรัมโอรสของอาหับในยิสเรเอล เพราะว่าพระองค์ทรงประชวร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 1, 'แล้วเอลีชาผู้พยากรณ์ได้เรียกเหล่าศิษย์แห่งผู้พยากรณ์มาคนหนึ่ง และพูดกับเขาว่า “จงคาดเอวของเจ้าไว้ ถือน้ํามันขวดนี้ไปที่ราโมทกิเลอาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 2, 'และเมื่อเจ้าไปถึงแล้ว จงมองดูเยฮูบุตรเยโฮชาฟัทบุตรนิมซี จงเข้าไปหาเขา ให้ลุกขึ้นจากหมู่พวกพี่น้อง และนําเขาเข้าไปในห้องชั้นใน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 3, 'แล้วจงเอาน้ํามันในขวดเทลงบนศีรษะของเขา และกล่าวว่า ‘พระเยโฮวาห์ตรัสดังนี้ว่า เราเจิมตั้งเจ้าให้เป็นกษัตริย์เหนืออิสราเอล’ แล้วจงเปิดประตูออกหนีไป อย่ารอช้าอยู่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 4, 'คนหนุ่มนั้นคือคนหนุ่มที่เป็นผู้พยากรณ์จึงไปยังราโมทกิเลอาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 5, 'และเมื่อเขามาถึง ดูเถิด บรรดาผู้บังคับบัญชาทหารกําลังประชุมกันอยู่ และเขากล่าวว่า “โอ ท่านผู้บัญชาการ ข้าพเจ้ามีธุระด่วนมาถึงท่าน” และเยฮูพูดว่า “มาหาคนใดในพวกเรา” และเขาว่า “โอ ท่านผู้บัญชาการ มาหาท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 6, 'ท่านก็ลุกขึ้นเข้าไปในเรือน และคนหนุ่มนั้นก็เทน้ํามันบนศีรษะของท่าน กล่าวว่า “พระเยโฮวาห์พระเจ้าแห่งอิสราเอลตรัสดังนี้ว่า เราเจิมตั้งเจ้าไว้เป็นกษัตริย์เหนือประชาชนของพระเยโฮวาห์คือเหนืออิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 7, 'และเจ้าจงโค่นราชวงศ์ของอาหับนายของเจ้า เพื่อเราจะได้จัดการสนองเยเซเบลเพราะโลหิตของบรรดาผู้พยากรณ์ผู้รับใช้ของเรา และเพราะโลหิตของบรรดาผู้รับใช้ทั้งสิ้นของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 8, 'เพราะว่าราชวงศ์อาหับทั้งหมดจะต้องพินาศ และเราจะตัดคนที่ปัสสาวะรดกําแพงได้ออกเสียจากอาหับ ทั้งคนที่ยังอยู่และเหลืออยู่ในอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 9, 'และเราจะกระทําราชวงศ์ของอาหับให้เหมือนราชวงศ์ของเยโรโบอัมบุตรเนบัท และเหมือนราชวงศ์ของบาอาชาบุตรอาหิยาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 10, 'และสุนัขจะกินเยเซเบลในที่ดินส่วนพระองค์ ณ ยิสเรเอล และจะไม่มีผู้ใดฝังศพพระนาง” แล้วเขาก็เปิดประตูหนีไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 11, 'เมื่อเยฮูออกมาสู่พวกข้าราชการของเจ้านายของท่าน คนหนึ่งพูดกับท่านว่า “ทุกอย่างเรียบร้อยดีหรือ ทําไมคนบ้าคนนี้จึงมาหาท่าน” ท่านพูดกับเขาทั้งหลายว่า “ท่านทั้งหลายรู้จักชายคนนั้นและทราบว่าเขาพูดอะไรแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 12, 'และเขาทั้งหลายว่า “นั่นไม่เป็นความจริง ขอบอกเรามาเถิด” และท่านว่า “เขาพูดอย่างนี้กับข้าพเจ้าว่า ‘พระเยโฮวาห์ตรัสดังนี้ว่า เราเจิมตั้งเจ้าให้เป็นกษัตริย์เหนืออิสราเอล’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 13, 'แล้วทุกคนก็รีบเปลื้องเสื้อผ้าของตนออกวางไว้รองท่านที่ขั้นบันไดซึ่งเปล่าอยู่ และเขาทั้งหลายเป่าแตร และป่าวร้องว่า “เยฮูเป็นกษัตริย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 14, 'ดังนี้แหละ เยฮูบุตรชายเยโฮชาฟัทบุตรชายนิมซีได้ร่วมกันคิดกบฏต่อโยรัม (ฝ่ายโยรัมพร้อมกับอิสราเอลทั้งปวงยังระวังป้องกันราโมทกิเลอาดอยู่เพราะเหตุฮาซาเอลกษัตริย์แห่งซีเรีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 15, 'แต่กษัตริย์โยรัมทรงกลับไปรักษาพระองค์ที่ยิสเรเอล เพราะบาดแผลซึ่งชนซีเรียได้กระทําแก่พระองค์ เมื่อพระองค์ทรงสู้รบกับฮาซาเอลกษัตริย์แห่งซีเรีย) เยฮูจึงตรัสว่า “ถ้านี่เป็นความประสงค์ของท่านทั้งหลาย ก็ขออย่าให้คนหนึ่งคนใดเล็ดลอดออกไปจากเมืองเพื่อบอกข่าวที่ยิสเรเอล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 16, 'แล้วเยฮูก็เสด็จทรงรถรบ และเสด็จไปยังยิสเรเอล เพราะโยรัมบรรทมที่นั่น และอาหัสยาห์กษัตริย์แห่งยูดาห์ได้เสด็จลงมาเยี่ยมโยรัม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 17, 'ฝ่ายทหารยามยืนอยู่บนหอคอยที่ยิสเรเอล เขามองเห็นพวกของเยฮูมาจึงว่า “ข้าพเจ้าเห็นคนพวกหนึ่ง” โยรัมตรัสว่า “จงใช้ให้พลม้าคนหนึ่งไปพบเขาให้ถามเขาว่า ‘มาอย่างสันติหรือ’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 18, 'คนนั้นจึงขึ้นม้าไปพบท่านและพูดว่า “กษัตริย์ตรัสดังนี้ว่า ‘มาอย่างสันติหรือ’” และเยฮูตอบว่า “ท่านเกี่ยวข้องอะไรกับสันติ จงเลี้ยวกลับตามเรามา” และทหารยามก็รายงานว่า “ผู้สื่อสารไปถึงเขาแล้ว แต่เขาไม่กลับมา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 19, 'พระองค์จึงรับสั่งใช้พลม้าคนที่สองออกไป ผู้นั้นมาถึงเขาแล้วก็พูดว่า “กษัตริย์ตรัสดังนี้ว่า ‘มาอย่างสันติหรือ’” และเยฮูตอบว่า “ท่านเกี่ยวข้องอะไรกับสันติ จงเลี้ยวกลับตามเรามา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 20, 'ทหารยามก็รายงานว่า “เขาไปถึงแล้วแต่เขาไม่กลับมา และการขับรถนั้นก็เหมือนกับการขับรถของเยฮูบุตรนิมซี เพราะเขาขับรวดเร็วนัก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 21, 'โยรัมตรัสว่า “จงเตรียมพร้อม” และเขาก็จัดรถรบของพระองค์ให้พร้อมไว้ แล้วโยรัมกษัตริย์แห่งอิสราเอลและอาหัสยาห์กษัตริย์แห่งยูดาห์ก็เสด็จออกไป ต่างก็ทรงรถรบของพระองค์เอง ทรงออกไปปะทะกับเยฮู มาพบกันเข้า ณ ที่ดินแปลงของนาโบทชาวยิสเรเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 22, 'และอยู่มาเมื่อโยรัมเห็นเยฮูแล้วจึงตรัสว่า “เยฮูมาอย่างสันติหรือ” เยฮูตอบว่า “จะสันติอย่างไรได้ เมื่อการเล่นชู้และวิทยาคมของเยเซเบลมารดาของท่านยังมีอยู่มากเช่นนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 23, 'แล้วโยรัมทรงชักบังเหียนหันกลับหนีไปพลางรับสั่งกับอาหัสยาห์ว่า “โอ ข้าแต่อาหัสยาห์ เขาร่วมกันคิดกบฏ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 24, 'และเยฮูก็โก่งธนูด้วยสุดกําลัง ยิงถูกเยโฮรัมระหว่างพระอังสาทั้งสอง ลูกธนูจึงแทงทะลุพระหทัยของพระองค์ พระองค์ก็ทรงล้มลงในรถรบของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 25, 'เยฮูตรัสกับบิดคาร์นายทหารของพระองค์ว่า “จงยกศพเขาขึ้นและโยนทิ้งลงไปในที่ดินแปลงของนาโบทชาวยิสเรเอล จําไว้เถอะ เมื่อฉันและท่านขี่ม้าเคียงกันมาตามอาหับบิดาของเขาไป พระเยโฮวาห์ทรงกล่าวโทษเขาดังนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 26, 'พระเยโฮวาห์ตรัสว่า ‘เราได้เห็นโลหิตของนาโบทและโลหิตของลูกหลานของเขาเมื่อวานนี้’ พระเยโฮวาห์ตรัสว่า ‘แน่ทีเดียวเราจะสนองเจ้าบนที่ดินแปลงนี้แหละ’ ฉะนั้นบัดนี้จงยกเขาขึ้นทิ้งไว้บนที่ดินแปลงนี้แหละตามพระวจนะของพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 27, 'เมื่ออาหัสยาห์กษัตริย์แห่งยูดาห์เห็นดังนั้น พระองค์ทรงหนีไปทางบ้านในสวน และเยฮูก็ติดตามพระองค์ไปตรัสว่า “จงยิงท่านในรถรบด้วย” และเขาทั้งหลายได้ยิงพระองค์ตรงทางข้ามเขาตําบลกูรซึ่งอยู่ใกล้อิบเลอัม และพระองค์ทรงหนีไปถึงเมืองเมกิดโด และสิ้นพระชนม์ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 28, 'ข้าราชการของพระองค์ก็บรรทุกพระศพใส่รถรบไปยังเยรูซาเล็ม และฝังไว้ในอุโมงค์ของพระองค์กับบรรพบุรุษของพระองค์ในนครดาวิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 29, 'ในปีที่สิบเอ็ดแห่งรัชกาลโยรัมโอรสของอาหับ อาหัสยาห์เริ่มครอบครองเหนือยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 30, 'เมื่อเยฮูมาถึงเมืองยิสเรเอล เยเซเบลทรงได้ยินเรื่องนั้น พระนางก็ทรงเขียนตาและแต่งพระเศียรและทรงมองออกไปทางพระแกล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 31, 'และเมื่อเยฮูผ่านเข้าประตูวังมา พระนางตรัสว่า “ศิมรีผู้ฆ่านายของเขามีสันติหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 32, 'แล้วเยฮูแหงนพระพักตร์ทอดพระเนตรที่พระแกลตรัสว่า “ใครอยู่ฝ่ายเรา ใครบ้าง” มีขันทีสองสามคนชะโงกหน้าต่างออกมาดูพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 33, 'พระองค์ตรัสว่า “โยนนางลงมา” เขาจึงโยนพระนางลงมา และโลหิตของพระนางก็กระเด็นติดผนังกําแพงและติดม้า และพระองค์ทรงม้าย่ําไปบนพระนาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 34, 'แล้วพระองค์เสด็จเข้าไป เสวยและทรงดื่ม และพระองค์ตรัสว่า “จัดการกับหญิงที่ถูกสาปคนนี้ เอาไปฝังเสีย เพราะเธอเป็นธิดาของกษัตริย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 35, 'แต่เมื่อเขาจะไปฝังศพพระนาง เขาก็พบแต่กะโหลกพระเศียร พระบาทและฝ่าพระหัตถ์ของพระนาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 36, 'เมื่อเขากลับมาทูลพระองค์ พระองค์ตรัสว่า “นี่เป็นไปตามพระวจนะของพระเยโฮวาห์ ซึ่งพระองค์ตรัสทางเอลียาห์ชาวทิชบีผู้รับใช้ของพระองค์ว่า ‘สุนัขจะกินเนื้อของเยเซเบลในเขตแดนยิสเรเอล’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 37, 'และศพของเยเซเบลจะเป็นเหมือนมูลสัตว์บนพื้นทุ่งในเขตแดนยิสเรเอล เพื่อว่าจะไม่มีใครกล่าวว่า ‘นี่คือเยเซเบล’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 1, 'ฝ่ายอาหับมีโอรสเจ็ดสิบองค์ในสะมาเรีย เยฮูจึงทรงพระอักษรส่งไปยังสะมาเรียถึงบรรดาผู้ปกครองเมืองยิสเรเอลนั้น ถึงพวกผู้ใหญ่ และถึงบรรดาพี่เลี้ยงแห่งโอรสของอาหับว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 2, '“เพราะบรรดาโอรสของนายของท่านอยู่กับท่าน และท่านมีรถรบและม้า และเมืองที่มีป้อมด้วยและอาวุธ พอจดหมายนี้มาถึงท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 3, 'จงคัดเลือกโอรสนายของท่านองค์ที่ดีที่สุด และเหมาะสมที่สุด จงตั้งท่านไว้บนพระที่นั่งของพระชนกของท่าน และจงสู้รบเพื่อราชวงศ์นายของท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 4, 'แต่เขาทั้งหลายกลัวอย่างที่สุด และพูดว่า “ดูเถิด กษัตริย์สององค์ยังต้านทานพระองค์ไม่ได้แล้ว เราจะต่อสู้พระองค์ได้อย่างไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 5, 'ฉะนั้นผู้ที่ปกครองดูแลพระราชวัง และผู้ที่ปกครองดูแลบ้านเมือง พร้อมทั้งพวกผู้ใหญ่และพวกพี่เลี้ยงของราชโอรส ก็ใช้คนให้ไปทูลเยฮูว่า “ข้าพระองค์ทั้งหลายเป็นผู้รับใช้ของพระองค์ และข้าพระองค์จะกระทําทุกอย่างที่พระองค์ตรัสสั่งแก่ข้าพระองค์ ข้าพระองค์จะไม่ตั้งกษัตริย์ผู้หนึ่งผู้ใด ขอทรงกระทําตามที่ชอบพระทัยในสายพระเนตรของพระองค์เถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 6, 'แล้วพระองค์ทรงมีลายพระหัตถ์ไปถึงเขาฉบับที่สองว่า “ถ้าท่านทั้งหลายอยู่ฝ่ายเรา และถ้าท่านพร้อมที่จะเชื่อฟังเสียงของเรา จงนําศีรษะของบรรดาโอรสนายของท่านมาหาเราที่ยิสเรเอลพรุ่งนี้เวลานี้” ฝ่ายโอรสของกษัตริย์เจ็ดสิบองค์ด้วยกัน อยู่กับคนใหญ่คนโตในเมือง ผู้ซึ่งได้ชุบเลี้ยงท่านทั้งหลายมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 7, 'และอยู่มาเมื่อลายพระหัตถ์มาถึงเขาทั้งหลาย เขาก็จับโอรสของกษัตริย์ฆ่าเสียเจ็ดสิบองค์ด้วยกัน เอาศีรษะใส่ตะกร้าส่งไปยังพระองค์ที่ยิสเรเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 8, 'เมื่อผู้สื่อสารมาทูลพระองค์ว่า “เขานําศีรษะโอรสของกษัตริย์มาแล้วพระเจ้าข้า” พระองค์ตรัสว่า “จงกองไว้เป็นสองกองตรงทางเข้าประตูเมืองจนถึงรุ่งเช้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 9, 'อยู่มาพอรุ่งเช้าพระองค์เสด็จออกไปประทับยืน ตรัสกับประชาชนทั้งปวงว่า “ท่านทั้งหลายเป็นผู้ชอบธรรม ดูเถิด ส่วนเราได้กบฏต่อนายของเราและประหารพระองค์เสีย แต่ผู้ใดเล่าที่ฆ่าบรรดาคนเหล่านี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 10, 'จงทราบเถิดว่าพระวจนะของพระเยโฮวาห์ ซึ่งพระเยโฮวาห์ตรัสเกี่ยวกับราชวงศ์ของอาหับ จะไม่ตกดินแต่อย่างไรเลย เพราะพระเยโฮวาห์ทรงกระทําตามที่พระองค์ตรัสโดยเอลียาห์ผู้รับใช้ของพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 11, 'เยฮูทรงประหารราชวงศ์ของอาหับที่เหลืออยู่ในยิสเรเอลทั้งสิ้น คนใหญ่คนโตทุกคนของพระองค์ และญาติพี่น้องของพระองค์ และปุโรหิตของพระองค์ ดังนี้แหละไม่เหลือไว้สักคนเดียวเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 12, 'แล้วพระองค์ก็ทรงลุกขึ้นเสด็จออกไปยังสะมาเรีย เมื่อพระองค์ประทับที่โรงตัดขนแกะตามทางที่เสด็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 13, 'เยฮูทรงพบพระญาติของอาหัสยาห์กษัตริย์แห่งยูดาห์ และพระองค์ตรัสถามว่า “ท่านทั้งหลายคือใคร” และเขาทั้งหลายทูลตอบว่า “ข้าพเจ้าทั้งหลายคือญาติของอาหัสยาห์ และข้าพเจ้าทั้งหลายลงมาเยี่ยมบรรดาโอรสของกษัตริย์และโอรสของราชมารดา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 14, 'พระองค์รับสั่งว่า “จับเขาทั้งเป็น” เขาทั้งหลายก็จับเขาทั้งเป็นและประหารเขาเสียที่บ่อโรงตัดขนแกะสี่สิบสองคนด้วยกัน ไม่เหลือไว้สักคนเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 15, 'และเมื่อพระองค์เสด็จจากที่นั่นก็ทรงพบเยโฮนาดับบุตรชายเรคาบมาหาพระองค์ พระองค์ทรงต้อนรับเขาและตรัสกับเขาว่า “จิตใจของท่านซื่อตรงต่อจิตใจของฉัน อย่างจิตใจของฉันตรงต่อจิตใจของท่านหรือ” และเยโฮนาดับทูลว่า “ตรง พระเจ้าข้า” เยฮูตรัสว่า “ถ้าตรงก็ยื่นมือมาให้เรา” เขาจึงยื่นมือของเขา และเยฮูก็จับเขาขึ้นมาบนรถรบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 16, 'พระองค์ตรัสว่า “มากับเราเถิด และดูความร้อนรนของเราเพื่อพระเยโฮวาห์” พระองค์จึงให้เขานั่งรถรบของพระองค์ไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 17, 'และเมื่อพระองค์มาถึงสะมาเรีย พระองค์ทรงประหารคนทั้งปวงที่เป็นราชวงศ์ของอาหับที่เหลืออยู่ในสะมาเรียเสีย จนพระองค์ทรงทําลายอาหับเสียสิ้น ตามพระวจนะของพระเยโฮวาห์ซึ่งพระองค์ตรัสกับเอลียาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 18, 'แล้วเยฮูทรงประชุมบรรดาประชาชนทั้งสิ้น และตรัสกับเขาทั้งหลายว่า “อาหับปรนนิบัติพระบาอัลแต่เล็กน้อย แต่เยฮูจะปรนนิบัติพระองค์มาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 19, 'ฉะนั้นบัดนี้จงเรียกผู้พยากรณ์ของพระบาอัลมาให้หมด ทั้งบรรดาผู้รับใช้และปุโรหิตของท่าน อย่าให้ผู้ใดขาดไปเลย เพราะเราจะมีสัตวบูชาอย่างใหญ่โตที่จะถวายแก่พระบาอัล ผู้ใดขาดจะมีชีวิตอยู่ไม่ได้” แต่เยฮูทรงกระทําเป็นอุบายเพื่อจะทําลายผู้นับถือพระบาอัล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 20, 'และเยฮูตรัสสั่งว่า “จงจัดประชุมอันศักดิ์สิทธิ์สําหรับพระบาอัล” เขาก็ป่าวร้องเรียกประชุมเช่นนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 21, 'และเยฮูทรงใช้ให้ไปทั่วอิสราเอล และผู้นับถือพระบาอัลก็มาทั้งหมดจึงไม่มีเหลือสักคนหนึ่งที่ไม่ได้มา และเขาทั้งหลายก็เข้าไปในนิเวศของพระบาอัล และนิเวศของพระบาอัลก็เต็มแน่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 22, 'พระองค์ตรัสสั่งผู้ที่ดูแลตู้เสื้อว่า “จงเอาเสื้อสําหรับบรรดาผู้นับถือพระบาอัลออกมา” เขาก็เอาเสื้อออกมาให้เขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 23, 'แล้วเยฮูเสด็จเข้าไปในนิเวศของพระบาอัล พร้อมกับเยโฮนาดับบุตรชายเรคาบ พระองค์ตรัสกับผู้นับถือพระบาอัลว่า “จงค้นดู ดูให้ดีว่าไม่มีผู้รับใช้ของพระเยโฮวาห์อยู่ในหมู่พวกท่าน ให้มีแต่ผู้นับถือพระบาอัลเท่านั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 24, 'แล้วเขาทั้งหลายเข้าไปถวายเครื่องสัตวบูชาและเครื่องเผาบูชา เยฮูทรงวางคนแปดสิบคนไว้ภายนอก และตรัสว่า “ชายคนใดที่ปล่อยให้คนหนึ่งคนใดซึ่งเรามอบไว้ในมือเจ้าหนีรอดไปได้ เขาต้องเสียชีวิตของเขาแทน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 25, 'และอยู่มาเมื่อพระองค์เสร็จการถวายเครื่องเผาบูชา เยฮูรับสั่งแก่ทหารรักษาพระองค์และพวกนายทหารว่า “จงเข้าไปฆ่าเขาเสีย อย่าให้รอดสักคนเดียว” เมื่อเขาฆ่าเขาทั้งหลายเสียด้วยคมดาบแล้ว ทหารรักษาพระองค์และพวกนายทหารก็โยนศพเขาทั้งหลายออกไปข้างนอก แล้วก็ไปที่เมืองแห่งนิเวศของพระบาอัล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 26, 'เขานําเอาเสาศักดิ์สิทธิ์ซึ่งอยู่ในนิเวศของพระบาอัลออกมาเผาเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 27, 'และเขาทั้งหลายทลายเสาศักดิ์สิทธิ์แห่งพระบาอัล และทลายนิเวศของพระบาอัลและกระทําให้เป็นส้วมจนทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 28, 'เยฮูทรงกวาดล้างพระบาอัลจากอิสราเอลดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 29, 'แต่เยฮูมิได้ทรงหันจากบาปทั้งหลายของเยโรโบอัมบุตรชายเนบัท ซึ่งพระองค์ทรงกระทําให้อิสราเอลทําบาปด้วย คือวัวทองคําซึ่งอยู่ในเมืองเบธเอลและในเมืองดาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 30, 'และพระเยโฮวาห์ตรัสกับเยฮูว่า “เพราะเจ้าได้ทําดีในการที่กระทําสิ่งที่ถูกต้องในสายตาของเรา และได้กระทําต่อราชวงศ์อาหับตามทุกอย่างที่อยู่ในใจของเรา ลูกหลานของเจ้าชั่วอายุที่สี่จะได้นั่งบนบัลลังก์แห่งอิสราเอล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 31, 'แต่เยฮูมิได้ทรงระมัดระวังที่จะดําเนินตามพระราชบัญญัติของพระเยโฮวาห์พระเจ้าแห่งอิสราเอลด้วยสิ้นสุดพระทัยของพระองค์ พระองค์มิได้ทรงหันเสียจากบาปทั้งหลายของเยโรโบอัม ซึ่งพระองค์ทรงกระทําให้อิสราเอลทําบาปด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 32, 'ในสมัยนั้นพระเยโฮวาห์ทรงเริ่มตัดส่วนของอิสราเอลออก ฮาซาเอลได้รบชนะตามบรรดาพรมแดนอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 33, 'ตั้งแต่แม่น้ําจอร์แดนฟากตะวันออก ทั่วแผ่นดินกิเลอาด คนกาด คนรูเบนและคนมนัสเสห์ ตั้งแต่อาโรเออร์ ซึ่งอยู่ข้างที่ลุ่มแม่น้ําอารโนน คือกิเลอาดและบาชาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 34, 'ส่วนพระราชกิจนอกนั้นของเยฮู และบรรดาสิ่งซึ่งพระองค์ทรงกระทํา และยุทธพลังทั้งสิ้นของพระองค์ มิได้บันทึกไว้ในหนังสือพงศาวดารแห่งกษัตริย์ประเทศอิสราเอลหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 35, 'เยฮูจึงทรงล่วงหลับไปอยู่กับบรรพบุรุษของพระองค์ และเขาก็ฝังไว้ในกรุงสะมาเรีย และเยโฮอาหาสโอรสของพระองค์ได้เสวยราชย์แทนพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 36, 'เวลาที่เยฮูทรงครอบครองเหนืออิสราเอลในสะมาเรียนั้นเป็นยี่สิบแปดปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 1, 'เมื่ออาธาลิยาห์พระราชมารดาของอาหัสยาห์ทรงเห็นว่าโอรสของพระนางสิ้นพระชนม์ พระนางก็ลุกขึ้นทรงทําลายเชื้อพระวงศ์เสียสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 2, 'แต่เยโฮเชบาธิดาของกษัตริย์โยรัม พระน้องนางของอาหัสยาห์ ได้นําโยอาชโอรสของอาหัสยาห์และลอบลักเธอไปจากท่ามกลางโอรสของกษัตริย์ ผู้ซึ่งจะถูกประหารชีวิต และพระนางเก็บเธอและพี่เลี้ยงของเธอไว้ในห้องบรรทมเพื่อซ่อนเธอเสียจากอาธาลิยาห์ ดังนี้แหละ เธอจึงมิได้ถูกประหารชีวิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 3, 'และเธออยู่กับพระนางหกปีซ่อนอยู่ในพระนิเวศของพระเยโฮวาห์ และอาธาลิยาห์ก็ครอบครองแผ่นดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 4, 'แต่ในปีที่เจ็ดเยโฮยาดาได้ใช้ให้บรรดานายทัพนายกอง ผู้บังคับบัญชากองและพวกทหารรักษาพระองค์ ให้เขาทั้งหลายมาหาท่านที่ในพระนิเวศของพระเยโฮวาห์ และท่านได้ทําพันธสัญญากับเขาทั้งหลาย และให้เขาปฏิญาณในพระนิเวศของพระเยโฮวาห์ และท่านได้นําโอรสของกษัตริย์มาให้เขาเห็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 5, 'และท่านบัญชาเขาทั้งหลายว่า “นี่เป็นสิ่งที่ท่านทั้งหลายพึงกระทํา คือหนึ่งในสามของพวกท่าน ผู้เข้าเวรวันสะบาโต ให้เฝ้าพระราชวัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 6, 'ฝ่ายอีกหนึ่งในสามประจําอยู่ที่ประตูสูร และอีกหนึ่งในสามประจําอยู่ที่ประตูข้างหลังทหารรักษาพระองค์ ให้เฝ้าพระราชวังเพื่อป้องกันไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 7, 'ส่วนท่านทั้งหลายอีกสองพวก คือผู้ที่ออกเวรวันสะบาโต ให้เฝ้าพระนิเวศของพระเยโฮวาห์รอบกษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 8, 'ท่านทั้งหลายจงล้อมกษัตริย์ไว้รอบ ทุกคนถืออาวุธของตนไว้ ผู้ที่เข้ามาใกล้แถวให้ประหารชีวิตเสีย จงอยู่กับกษัตริย์เมื่อพระองค์เสด็จออกและเสด็จเข้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 9, 'นายทัพนายกองก็ได้กระทําตามที่เยโฮยาดาปุโรหิตสั่งทุกประการ ต่างก็นําคนของตนที่จะเข้าเวรวันสะบาโต พร้อมกับคนที่จะออกเวรวันสะบาโตนั้น มาหาเยโฮยาดาปุโรหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 10, 'และปุโรหิตก็มอบหอกและโล่ซึ่งอยู่ในพระวิหารของพระเยโฮวาห์ อันเป็นของกษัตริย์ดาวิดแก่นายทัพนายกอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 11, 'และทหารรักษาพระองค์ถืออาวุธทุกคนยืนประจําอยู่ตั้งแต่พระวิหารด้านขวาไปถึงพระวิหารด้านซ้าย รอบแท่นบูชาและพระวิหารอยู่รอบกษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 12, 'แล้วท่านก็นําโอรสของกษัตริย์ออกมาสวมมงกุฎให้ และมอบพระโอวาทให้ และเขาทั้งหลายตั้งท่านไว้เป็นกษัตริย์ และได้เจิมท่าน และเขาทั้งหลายก็ตบมือ พูดว่า “ขอกษัตริย์ทรงพระเจริญ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 13, 'เมื่ออาธาลิยาห์ทรงสดับเสียงทหารรักษาพระองค์และเสียงประชาชน พระนางก็เสด็จเข้าไปหาประชาชนที่พระวิหารของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 14, 'และเมื่อพระนางทอดพระเนตร ดูเถิด กษัตริย์ประทับยืนอยู่ที่ข้างเสาตามธรรมเนียมประเพณี มีนายทัพนายกองและพลแตรอยู่ข้างกษัตริย์ และประชาชนแห่งแผ่นดินทั้งสิ้นก็ร่าเริง และเป่าแตร พระนางอาธาลิยาห์ก็ฉีกฉลองพระองค์ทรงร้องว่า “กบฏ กบฏ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 15, 'แล้วเยโฮยาดาปุโรหิตก็บัญชานายทัพนายกองทั้งปวง ผู้ที่ได้ตั้งให้ควบคุมกองทัพว่า “จงคุมพระนางออกมาระหว่างแถวทหาร ผู้ใดติดตามพระนางไปก็จงประหารเสียด้วยดาบ” เพราะปุโรหิตกล่าวว่า “อย่าให้พระนางถูกประหารในพระนิเวศของพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 16, 'เขาทั้งหลายจึงจับพระนาง และพระนางก็ไปตามทางที่ม้าเข้าพระราชวัง และถูกประหารเสียที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 17, 'และเยโฮยาดาได้กระทําพันธสัญญาระหว่างพระเยโฮวาห์และกษัตริย์และประชาชนว่า ให้เขาเป็นประชาชนของพระเยโฮวาห์ และระหว่างกษัตริย์กับประชาชนด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 18, 'แล้วประชาชนทั้งสิ้นแห่งแผ่นดินก็เข้าไปในนิเวศของพระบาอัล และพังนิเวศเสีย เขาทําลายแท่นบูชาและรูปเคารพของพระบาอัลเสียเป็นชิ้นๆ และได้ประหารชีวิตมัททานปุโรหิตของพระบาอัลเสียที่หน้าแท่นบูชา และปุโรหิตก็วางยามไว้ดูแลพระนิเวศของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 19, 'และท่านได้นํานายทัพนายกอง ผู้บังคับบัญชากอง ทหารรักษาพระองค์ และประชาชนทั้งสิ้นแห่งแผ่นดิน และเขาทั้งหลายได้นํากษัตริย์ลงมาจากพระนิเวศของพระเยโฮวาห์ ไปตามทางประตูทหารรักษาพระองค์ไปถึงพระราชวัง และพระองค์เสด็จประทับบนพระที่นั่งของกษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 20, 'ประชาชนทุกคนแห่งแผ่นดินจึงร่าเริง และบ้านเมืองก็สงบเงียบ และอาธาลิยาห์ทรงถูกประหารด้วยดาบแล้วที่พระราชวัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 21, 'เมื่อเยโฮอาชได้เริ่มครอบครองนั้นมีพระชนมายุเจ็ดพรรษา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 1, 'ในปีที่เจ็ดแห่งรัชกาลเยฮู เยโฮอาชได้เริ่มครอบครอง และพระองค์ทรงปกครองในกรุงเยรูซาเล็มสี่สิบปี พระราชมารดาของพระองค์ทรงพระนามว่าศิบียาห์ชาวเบเออร์เชบา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 2, 'และเยโฮอาชทรงกระทําสิ่งที่ถูกต้องในสายพระเนตรของพระเยโฮวาห์ ตลอดรัชสมัยของพระองค์ตามที่เยโฮยาดาปุโรหิตได้สั่งสอนพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 3, 'ถึงกระนั้นเขาก็ยังมิได้รื้อปูชนียสถานสูงเอาไป ประชาชนยังคงถวายสัตวบูชา และเผาเครื่องหอมในปูชนียสถานสูงเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 4, 'เยโฮอาชตรัสกับพวกปุโรหิตว่า “เงินอันเป็นของถวายที่บริสุทธิ์ทั้งสิ้นซึ่งเขานํามาในพระนิเวศของพระเยโฮวาห์ เงินที่เรียกจากรายบุคคล คือเงินที่กําหนดให้เสียตามรายบุคคล และบรรดาเงินซึ่งประชาชนถวายด้วยความสมัครใจที่จะนํามาไว้ในพระนิเวศของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 5, 'ให้ปุโรหิตรับเงินนั้นจากหมู่คนที่รู้จักกัน ให้เขาซ่อมพระนิเวศตรงที่ที่เขาเห็นว่าต้องการซ่อมแซม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 6, 'แต่เมื่อถึงปีที่ยี่สิบสามแห่งรัชกาลกษัตริย์เยโฮอาชปรากฏว่า ปุโรหิตมิได้ทําการซ่อมแซมพระนิเวศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 7, 'เพราะฉะนั้นกษัตริย์เยโฮอาชจึงตรัสเรียกเยโฮยาดาปุโรหิตและปุโรหิตอื่นๆและตรัสกับเขาว่า “ไฉนท่านจึงมิได้ซ่อมแซมพระนิเวศ เพราะฉะนั้นบัดนี้อย่าเก็บเงินจากคนที่ท่านรู้จักอีกต่อไปเลย แต่ให้ส่งไปเพื่อการซ่อมแซมพระนิเวศ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 8, 'ปุโรหิตจึงตกลงว่าจะไม่รับเงินจากประชาชนอีก และเขาไม่ต้องทําการซ่อมแซมพระนิเวศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 9, 'แล้วเยโฮยาดาปุโรหิตนําหีบมาใบหนึ่ง เจาะรูๆหนึ่งที่ฝาหีบนั้น และตั้งไว้ที่ข้างๆแท่นบูชาด้านขวาเมื่อเข้าไปในพระนิเวศของพระเยโฮวาห์ และพวกปุโรหิตผู้ที่เฝ้าอยู่ที่ธรณีประตูก็นําเงินทั้งหมดซึ่งเขานํามาในพระนิเวศของพระเยโฮวาห์ใส่ไว้ในหีบนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 10, 'และเมื่อเขาเห็นว่ามีเงินในหีบมากแล้ว ราชเลขาของกษัตริย์และมหาปุโรหิตมานับเงิน และเอาเงินที่เขาพบในพระนิเวศของพระเยโฮวาห์นั้นใส่ถุงมัดไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 11, 'แล้วเขาจะมอบเงินที่ชั่งออกแล้วนั้นใส่มือของคนงานผู้ดูแลพระนิเวศของพระเยโฮวาห์ แล้วเขาจะจ่ายต่อให้แก่ช่างไม้และช่างก่อสร้าง ผู้ทํางานพระนิเวศของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 12, 'และให้แก่ช่างก่อ และช่างสกัดหิน ทั้งจ่ายซื้อไม้ และหินสกัด ที่ใช้ในการซ่อมแซมพระนิเวศของพระเยโฮวาห์ และเพื่อค่าใช้จ่ายทั้งหมดในงานซ่อมแซมพระนิเวศนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 13, 'แต่ว่าเงินที่นํามาถวายในพระนิเวศของพระเยโฮวาห์นั้นมิได้นําไปใช้ในการทําอ่างเงิน ตะไกรตัดไส้ตะเกียง ชาม แตร หรือภาชนะทองคําใดๆ หรือภาชนะเงิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 14, 'เพราะเงินนั้นเขาให้แก่คนงานซึ่งทํางานซ่อมพระนิเวศของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 15, 'และเขามิได้ขอบัญชีจากคนที่เขามอบเงินใส่ในมือให้เอาไปจ่ายแก่คนงาน เพราะว่าเขาปฏิบัติงานด้วยความสัตย์ซื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 16, 'เงินที่ได้จากการไถ่การละเมิด และเงินที่ได้จากการไถ่บาป มิได้นํามาไว้ในพระนิเวศของพระเยโฮวาห์ เงินนั้นเป็นของปุโรหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 17, 'แล้วคราวนั้นฮาซาเอลกษัตริย์แห่งซีเรียได้ยกขึ้นไปสู้รบกับเมืองกัทและยึดเมืองนั้นได้ แต่เมื่อฮาซาเอลมุ่งพระพักตร์จะไปตีกรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 18, 'เยโฮอาชกษัตริย์แห่งยูดาห์ทรงนําเอาส่วนศักดิ์สิทธิ์ทั้งหมดที่เยโฮชาฟัท และเยโฮรัม และอาหัสยาห์บรรพบุรุษของพระองค์ กษัตริย์แห่งยูดาห์ถวายไว้นั้น และส่วนศักดิ์สิทธิ์ของพระองค์เอง และทองคําทั้งหมดที่พบในคลังพระนิเวศของพระเยโฮวาห์ และของสํานักพระราชวัง และส่งสิ่งเหล่านี้ไปกํานัลฮาซาเอลกษัตริย์แห่งซีเรีย แล้วฮาซาเอลก็ถอยทัพจากกรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 19, 'ส่วนพระราชกิจนอกนั้นของโยอาช และบรรดาสิ่งซึ่งพระองค์ทรงกระทํา มิได้บันทึกไว้ในหนังสือพงศาวดารแห่งกษัตริย์ประเทศยูดาห์หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 20, 'ข้าราชการของพระองค์ลุกขึ้นกระทําการทรยศและประหารโยอาชเสียในวังมิลโลตามทางที่ลงไปยังสิลลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 21, 'คือโยซาคาร์บุตรชายชิเมอัท และเยโฮซาบาดบุตรชายโชเมอร์ ข้าราชการของพระองค์ได้ประหารพระองค์ พระองค์จึงสิ้นพระชนม์ และเขาฝังไว้กับบรรพบุรุษของพระองค์ในนครดาวิด และอามาซิยาห์โอรสของพระองค์ได้ขึ้นครองแทน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 1, 'ในปีที่ยี่สิบสามแห่งรัชกาลโยอาชโอรสของอาหัสยาห์กษัตริย์แห่งยูดาห์ เยโฮอาหาสโอรสของเยฮูได้เริ่มครอบครองเหนืออิสราเอลในสะมาเรีย และทรงครอบครองอยู่สิบเจ็ดปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 2, 'พระองค์ทรงกระทําสิ่งที่ชั่วช้าในสายพระเนตรของพระเยโฮวาห์ และกระทําตามบาปทั้งหลายของเยโรโบอัมบุตรชายเนบัท ซึ่งพระองค์ได้ทรงกระทําให้อิสราเอลทําบาปด้วย พระองค์หาได้พรากจากสิ่งเหล่านั้นไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 3, 'และพระพิโรธของพระเยโฮวาห์ก็พลุ่งขึ้นต่ออิสราเอล และพระองค์ทรงมอบเขาทั้งหลายไว้ในมือของฮาซาเอลกษัตริย์แห่งซีเรีย และในมือของเบนฮาดัดโอรสของฮาซาเอลเนืองๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 4, 'แล้วเยโฮอาหาสได้วิงวอนพระเยโฮวาห์ และพระเยโฮวาห์ทรงสดับท่าน เพราะพระองค์ทรงเห็นการบีบบังคับอิสราเอล คือที่กษัตริย์แห่งซีเรียบีบบังคับเขาอย่างไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 5, '(เพราะฉะนั้นพระเยโฮวาห์ทรงประทานผู้ช่วยผู้หนึ่งแก่อิสราเอล เขาจึงรอดพ้นจากมือคนซีเรีย และประชาชนอิสราเอลก็อาศัยอยู่ในเต็นท์เขาอย่างเดิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 6, 'ถึงกระนั้นเขาก็มิได้พรากจากบาปทั้งหลายของราชวงศ์เยโรโบอัม ซึ่งพระองค์ทรงกระทําให้อิสราเอลทําด้วย แต่ทรงดําเนินในบาปนั้น และเสารูปเคารพก็ยังคงอยู่ในสะมาเรียด้วย)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 7, 'เพราะมิได้เหลือกองทัพไว้ให้เยโฮอาหาสเกินกว่าทหารม้าห้าสิบคน และรถรบสิบคัน และทหารราบหนึ่งหมื่นคน เพราะกษัตริย์แห่งซีเรียได้ทําลายเขาทั้งหลายเสีย ทําให้เหมือนละอองเวลานวดข้าว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 8, 'ส่วนพระราชกิจนอกนั้นของเยโฮอาหาส และบรรดาสิ่งซึ่งพระองค์ทรงกระทํา และยุทธพลังของพระองค์ มิได้บันทึกไว้ในหนังสือพงศาวดารแห่งกษัตริย์ประเทศอิสราเอลหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 9, 'และเยโฮอาหาสทรงล่วงหลับไปอยู่กับบรรพบุรุษของพระองค์ และเขาฝังไว้ในสะมาเรีย และโยอาชโอรสของพระองค์ขึ้นครองแทนพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 10, 'ในปีที่สามสิบเจ็ดแห่งรัชกาลโยอาชกษัตริย์แห่งยูดาห์ เยโฮอาชโอรสเยโฮอาหาสได้เริ่มครอบครองเหนืออิสราเอลในสะมาเรีย และพระองค์ทรงครอบครองสิบหกปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 11, 'พระองค์ทรงกระทําสิ่งที่ชั่วร้ายในสายพระเนตรของพระเยโฮวาห์ พระองค์มิได้พรากจากบรรดาบาปของเยโรโบอัมบุตรชายเนบัท ซึ่งพระองค์ทรงกระทําให้อิสราเอลทําด้วย แต่พระองค์ทรงดําเนินในบาปนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 12, 'ส่วนพระราชกิจนอกนั้นของโยอาช และบรรดาสิ่งซึ่งพระองค์ทรงกระทํา และยุทธพลังซึ่งพระองค์ทรงสู้รบกับอามาซิยาห์กษัตริย์แห่งยูดาห์ มิได้บันทึกไว้ในหนังสือพงศาวดารแห่งกษัตริย์ประเทศอิสราเอลหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 13, 'โยอาชจึงทรงล่วงหลับไปอยู่กับบรรพบุรุษของพระองค์ และเยโรโบอัมทรงประทับบนบัลลังก์ของพระองค์ และเขาฝังพระศพโยอาชไว้ในสะมาเรียกับกษัตริย์แห่งอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 14, 'เมื่อเอลีชาล้มป่วยด้วยโรคที่ท่านจะต้องสิ้นชีวิต โยอาชกษัตริย์แห่งอิสราเอลได้เสด็จลงไปหาท่าน และกันแสงต่อหน้าท่าน ตรัสว่า “โอ บิดาของข้า บิดาของข้า ราชรถของอิสราเอล และพลม้าของประเทศ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 15, 'และเอลีชาทูลพระองค์ว่า “ขอทรงเอาคันธนูและลูกธนูมา” พระองค์จึงทรงเอาคันธนูและลูกธนูมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 16, 'แล้วท่านทูลกษัตริย์แห่งอิสราเอลว่า “ขอทรงหยิบธนู” และพระองค์ทรงหยิบมา และเอลีชาเอามือของตนวางบนพระหัตถ์ของกษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 17, 'และท่านทูลว่า “ขอทรงเปิดหน้าต่างด้านตะวันออก” และพระองค์ทรงเปิด แล้วเอลีชาทูลว่า “ขอทรงยิง” และพระองค์ก็ทรงยิง และท่านทูลว่า “ลูกธนูแห่งการช่วยให้รอดพ้นของพระเยโฮวาห์ ลูกธนูแห่งการช่วยให้รอดพ้นจากซีเรีย เพราะพระองค์จะทรงต่อสู้กับคนซีเรียที่อาเฟก จนกว่าพระองค์จะทรงกระทําให้เขาสิ้นไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 18, 'และท่านทูลว่า “ขอทรงหยิบลูกธนู” และพระองค์ทรงหยิบมัน และท่านทูลกษัตริย์แห่งอิสราเอลว่า “เอาลูกธนูตีพื้นดิน” และพระองค์ทรงตีสามครั้งแล้วทรงหยุดเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 19, 'แล้วคนแห่งพระเจ้าก็โกรธพระองค์ และทูลว่า “พระองค์ควรจะได้ตีสักห้าหรือหกครั้ง แล้วพระองค์จะได้ตีซีเรียจนกว่าพระองค์จะทรงกระทําให้เขาสิ้นไป แต่บัดนี้พระองค์จะตีซีเรียได้เพียงสามครั้งเท่านั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 20, 'และเอลีชาสิ้นชีวิต เขาก็ฝังไว้ ฝ่ายหมู่คนโมอับเคยปล้นแผ่นดินนั้นในฤดูแล้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 21, 'อยู่มาเมื่อเขากําลังส่งศพคนหนึ่งไป ดูเถิด เขาเห็นโจรหมู่หนึ่ง เขาจึงโยนศพชายคนนั้นลงไปในอุโมงค์ของเอลีชา พอศพชายคนนั้นลงไปแตะต้องกระดูกของเอลีชา เขาก็คืนชีวิตลุกขึ้นยืน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 22, 'ฝ่ายฮาซาเอลกษัตริย์แห่งซีเรียได้บีบบังคับคนอิสราเอลอยู่ตลอดรัชกาลของเยโฮอาหาส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 23, 'แต่พระเยโฮวาห์ทรงพระกรุณาต่อเขา และทรงเมตตาเขา และพระองค์ทรงหันมาทางเขาเพราะพันธสัญญาของพระองค์กับอับราฮัม อิสอัค และยาโคบ และจะไม่ทรงทําลายเขาหรือทอดทิ้งเขาเสียให้พ้นพระพักตร์จนบัดนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 24, 'เมื่อฮาซาเอลกษัตริย์แห่งซีเรียสิ้นพระชนม์ เบนฮาดัดโอรสของพระองค์ได้ขึ้นครองแทนพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 25, 'แล้วเยโฮอาชโอรสของเยโฮอาหาสได้ยึดบรรดาหัวเมืองจากพระหัตถ์เบนฮาดัดบุตรชายฮาซาเอลกลับคืนมา เป็นหัวเมืองที่พระองค์ตีไปได้จากพระหัตถ์เยโฮอาหาสพระชนกของพระองค์เมื่อทําสงครามกัน โยอาชได้รบชนะพระองค์สามครั้งและได้หัวเมืองอิสราเอลกลับคืนมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 1, 'ในปีที่สองแห่งรัชกาลโยอาชโอรสของเยโฮอาหาสกษัตริย์แห่งอิสราเอล อามาซิยาห์โอรสของโยอาชกษัตริย์แห่งยูดาห์ได้เริ่มครอบครอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 2, 'เมื่อพระองค์ทรงเริ่มครอบครองนั้น พระองค์มีพระชนมายุยี่สิบห้าพรรษา และพระองค์ทรงครองในเยรูซาเล็มยี่สิบเก้าปี พระราชมารดาของพระองค์มีพระนามว่าเยโฮอัดดานชาวเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 3, 'และพระองค์ทรงกระทําสิ่งที่ถูกต้องในสายพระเนตรของพระเยโฮวาห์ แต่ยังไม่เหมือนกับดาวิดบรรพบุรุษของพระองค์ พระองค์ทรงกระทําตามทุกสิ่งที่โยอาชราชบิดาของพระองค์ได้ทรงกระทํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 4, 'แต่ว่าปูชนียสถานสูงนั้นยังมิได้ทรงรื้อเสีย ประชาชนยังคงถวายสัตวบูชาและเผาเครื่องหอมบนปูชนียสถานสูงเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 5, 'และอยู่มาเมื่อราชอาณาจักรอยู่ในพระหัตถ์ของพระองค์อย่างมั่นคงแล้ว พระองค์ก็ทรงประหารชีวิตข้าราชการของพระองค์ผู้ที่ฆ่ากษัตริย์คือพระราชบิดาของพระองค์เสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 6, 'แต่พระองค์มิได้ทรงประหารชีวิตลูกหลานของเหล่าฆาตกรนั้น ตามซึ่งได้บันทึกไว้ในหนังสือพระราชบัญญัติของโมเสส ที่พระเยโฮวาห์ทรงบัญชาว่า “อย่าให้บิดาต้องรับโทษถึงตายแทนบุตรของตน หรือให้บุตรต้องรับโทษถึงตายแทนบิดาของตน ให้ทุกคนรับโทษถึงตายเนื่องด้วยบาปของคนนั้นเอง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 7, 'พระองค์ทรงประหารชีวิตคนเอโดมหนึ่งหมื่นคนในหุบเขาเกลือ และยึดเมืองเส-ลาด้วยการสงคราม และเรียกเมืองนั้นว่า โยกเธเอล ซึ่งเป็นชื่อมาถึงทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 8, 'และอามาซิยาห์ทรงใช้ผู้สื่อสารไปหาเยโฮอาชโอรสของเยโฮอาหาสโอรสของเยฮูกษัตริย์แห่งอิสราเอลทูลว่า “มาเถิด ขอให้เราเผชิญหน้ากัน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 9, 'และเยโฮอาชกษัตริย์แห่งอิสราเอลทรงส่งข่าวไปยังอามาซิยาห์กษัตริย์แห่งยูดาห์ว่า “ต้นผักหนามบนภูเขาเลบานอนส่งข่าวไปหาต้นสนสีดาร์บนภูเขาเลบานอนว่า ‘จงยกบุตรสาวของเจ้าให้เป็นภรรยาบุตรชายของเรา’ และสัตว์ป่าทุ่งตัวหนึ่งแห่งเลบานอนผ่านมา และย่ําต้นผักหนามลงเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 10, 'จริงอยู่ ท่านได้โจมตีเอโดม และพระทัยของท่านก็ทําให้ท่านผยองขึ้น จงพอใจในสง่าราศีของท่านเถิด และอยู่กับบ้าน เพราะไฉนท่านจึงเร้าใจตนเองให้ต่อสู้และรับอันตราย อันจะให้ท่านล้มลง ทั้งท่านและยูดาห์ด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 11, 'แต่อามาซิยาห์หาทรงฟังไม่ เยโฮอาชกษัตริย์แห่งอิสราเอลจึงขึ้นไป และพระองค์กับอามาซิยาห์กษัตริย์แห่งยูดาห์ก็เผชิญหน้ากันที่เบธเชเมชซึ่งเป็นของยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 12, 'และยูดาห์ก็พ่ายแพ้อิสราเอล และทุกคนก็หนีกลับไปเต็นท์ของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 13, 'และเยโฮอาชกษัตริย์แห่งอิสราเอลก็จับอามาซิยาห์กษัตริย์แห่งยูดาห์โอรสของเยโฮอาชโอรสของอาหัสยาห์ได้ที่เมืองเบธเชเมช และได้เสด็จมายังเยรูซาเล็ม และทลายกําแพงเยรูซาเล็มลงเสียสี่ร้อยศอก ตั้งแต่ประตูเอฟราอิมจนถึงประตูมุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 14, 'และพระองค์ทรงริบทองคําและเงินทั้งหมด และเครื่องใช้ทั้งหมดที่พบในพระนิเวศของพระเยโฮวาห์ และในคลังของสํานักพระราชวัง พร้อมกับคนประกัน และพระองค์กลับไปยังสะมาเรีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 15, 'ส่วนพระราชกิจนอกนั้นของเยโฮอาช ซึ่งพระองค์ทรงกระทํา ทั้งยุทธพลังของพระองค์ และที่พระองค์ทรงสู้รบกับอามาซิยาห์กษัตริย์แห่งยูดาห์อย่างไรนั้น มิได้บันทึกไว้ในหนังสือพงศาวดารแห่งกษัตริย์ประเทศอิสราเอลหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 16, 'และเยโฮอาชทรงล่วงหลับไปอยู่กับบรรพบุรุษของพระองค์ และเขาฝังไว้ในสะมาเรียกับบรรดากษัตริย์แห่งอิสราเอล และเยโรโบอัมโอรสของพระองค์ได้ครอบครองแทนพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 17, 'อามาซิยาห์โอรสของโยอาชกษัตริย์แห่งยูดาห์ทรงพระชนม์อยู่สิบห้าปี หลังจากสวรรคตของเยโฮอาชโอรสของเยโฮอาหาสกษัตริย์แห่งอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 18, 'ส่วนพระราชกิจนอกนั้นของอามาซิยาห์ มิได้บันทึกไว้ในหนังสือพงศาวดารแห่งกษัตริย์ประเทศยูดาห์หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 19, 'และเขาได้ร่วมกันกบฏต่อพระองค์ในเยรูซาเล็ม และพระองค์ทรงหนีไปยังลาคีช แต่เขาใช้คนไปตามพระองค์ที่ลาคีช และประหารชีวิตพระองค์เสียที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 20, 'และเขานําพระศพบรรทุกม้ากลับมา และฝังไว้ในเยรูซาเล็มอยู่กับบรรพบุรุษของพระองค์ในนครดาวิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 21, 'และประชาชนทั้งสิ้นแห่งยูดาห์ก็ตั้งอาซาริยาห์ ผู้ซึ่งมีพระชนมายุสิบหกพรรษา ให้เป็นกษัตริย์แทนอามาซิยาห์พระราชบิดาของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 22, 'พระองค์ทรงสร้างเมืองเอลัทและให้กลับขึ้นแก่ยูดาห์ หลังจากที่กษัตริย์ทรงล่วงหลับไปอยู่กับบรรพบุรุษของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 23, 'ในปีที่สิบห้าแห่งรัชกาลอามาซิยาห์โอรสของโยอาชกษัตริย์แห่งยูดาห์ เยโรโบอัมโอรสของโยอาชกษัตริย์แห่งอิสราเอลได้เริ่มครอบครองในสะมาเรีย และทรงครอบครองอยู่สี่สิบเอ็ดปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 24, 'และพระองค์ทรงกระทําสิ่งที่ชั่วร้ายในสายพระเนตรของพระเยโฮวาห์ พระองค์มิได้ทรงพรากจากบาปทั้งสิ้นของเยโรโบอัมบุตรชายเนบัท ซึ่งพระองค์ทรงกระทําให้อิสราเอลทําบาป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 25, 'พระองค์ทรงตีเอาดินแดนอิสราเอลคืนมาตั้งแต่ทางเข้าเมืองฮามัทไกลไปจนถึงทะเลแห่งที่ราบ ตามพระวจนะของพระเยโฮวาห์พระเจ้าแห่งอิสราเอล ซึ่งพระองค์ตรัสโดยผู้รับใช้ของพระองค์คือโยนาห์ ผู้เป็นบุตรชายอามิททัย ผู้พยากรณ์ผู้มาจากกัธเฮเฟอร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 26, 'เพราะพระเยโฮวาห์ทอดพระเนตรเห็นว่า ความทุกข์ใจของอิสราเอลนั้นขมขื่นนัก เพราะไม่มีใครยังอยู่หรือเหลืออยู่ และไม่มีผู้ใดช่วยอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 27, 'พระเยโฮวาห์มิได้ตรัสว่าจะทรงลบนามอิสราเอลเสียจากใต้ฟ้าสวรรค์ แต่พระองค์ทรงช่วยเขาโดยพระหัตถ์ของเยโรโบอัมโอรสของโยอาช');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 28, 'ส่วนพระราชกิจนอกนั้นของเยโรโบอัม และบรรดาสิ่งซึ่งพระองค์ทรงกระทํา และยุทธพลังของพระองค์ พระองค์สู้รบอย่างไร และเรื่องที่พระองค์ทรงตีเอาดามัสกัสและฮามัทคืนแก่อิสราเอล ซึ่งได้เคยเป็นของยูดาห์ มิได้บันทึกไว้ในหนังสือพงศาวดารแห่งกษัตริย์ประเทศอิสราเอลหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 29, 'และเยโรโบอัมทรงล่วงหลับไปอยู่กับบรรพบุรุษของพระองค์ คือบรรดากษัตริย์แห่งอิสราเอล และเศคาริยาห์โอรสของพระองค์ขึ้นครองแทนพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 1, 'ในปีที่ยี่สิบเจ็ดแห่งรัชกาลเยโรโบอัมกษัตริย์แห่งอิสราเอล อาซาริยาห์โอรสของอามาซิยาห์กษัตริย์แห่งยูดาห์ได้เริ่มครอบครอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 2, 'เมื่อพระองค์ทรงเริ่มครอบครองนั้น พระองค์ทรงมีพระชนมายุสิบหกพรรษา และพระองค์ทรงครอบครองอยู่ในกรุงเยรูซาเล็มห้าสิบสองปี พระราชมารดามีพระนามว่าเยโคลียาห์ชาวเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 3, 'พระองค์ได้ทรงกระทําสิ่งที่ถูกต้องในสายพระเนตรของพระเยโฮวาห์ ตามทุกสิ่งที่อามาซิยาห์ราชบิดาของพระองค์ทรงกระทํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 4, 'ถึงกระนั้นปูชนียสถานสูงก็ยังมิได้ถูกกําจัดเสีย ประชาชนยังถวายสัตวบูชาและเผาเครื่องหอมบนปูชนียสถานสูงเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 5, 'และพระเยโฮวาห์ทรงลงทัณฑ์กษัตริย์ กษัตริย์จึงทรงเป็นโรคเรื้อนจนถึงวันสิ้นพระชนม์ และทรงประทับในวังต่างหาก และโยธามโอรสของกษัตริย์ควบคุมสํานักพระราชวัง และทรงวินิจฉัยประชาชนแห่งแผ่นดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 6, 'ส่วนพระราชกิจนอกนั้นของอาซาริยาห์ และบรรดาสิ่งซึ่งพระองค์ทรงกระทํา มิได้บันทึกไว้ในหนังสือพงศาวดารแห่งกษัตริย์ประเทศยูดาห์หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 7, 'และอาซาริยาห์ทรงล่วงหลับไปอยู่กับบรรพบุรุษของพระองค์ และเขาฝังไว้กับบรรพบุรุษของพระองค์ในนครดาวิด และโยธามโอรสของพระองค์ขึ้นครองแทนพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 8, 'ในปีที่สามสิบแปดแห่งรัชกาลอาซาริยาห์กษัตริย์แห่งยูดาห์ เศคาริยาห์โอรสของเยโรโบอัมขึ้นครองเหนืออิสราเอลในสะมาเรียหกเดือน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 9, 'และพระองค์ทรงกระทําสิ่งที่ชั่วร้ายในสายพระเนตรของพระเยโฮวาห์ ดังที่บรรพบุรุษของพระองค์ทรงกระทํา พระองค์มิได้ทรงพรากจากบาปทั้งหลายของเยโรโบอัมบุตรชายเนบัท ซึ่งพระองค์ทรงกระทําให้อิสราเอลทําบาป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 10, 'ชัลลูมบุตรชายยาเบชร่วมกันกบฏต่อพระองค์ และล้มพระองค์เสียต่อหน้าประชาชน และประหารพระองค์เสีย และขึ้นครองแทนพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 11, 'ส่วนพระราชกิจนอกนั้นของเศคาริยาห์ ดูเถิด ได้บันทึกไว้ในหนังสือพงศาวดารแห่งกษัตริย์ประเทศอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 12, 'เหตุการณ์นี้เป็นไปตามพระดํารัสที่พระเยโฮวาห์ตรัสแก่เยฮูว่า “บุตรชายของเจ้าจะนั่งบนบัลลังก์แห่งอิสราเอลถึงชั่วอายุที่สี่” และเป็นไปอย่างนั้นแหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 13, 'ชัลลูมบุตรชายยาเบชได้เริ่มครอบครองในปีที่สามสิบเก้าแห่งรัชกาลอุสซียาห์กษัตริย์ของยูดาห์ และท่านครองในสะมาเรียเวลาหนึ่งเดือนเต็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 14, 'แล้วเมนาเฮมบุตรชายกาดีได้ขึ้นมาจากเมืองทีรซาห์และมายังสะมาเรีย และท่านก็ล้มชัลลูมบุตรชายยาเบชเสียที่ในสะมาเรีย และประหารชีวิตท่านเสีย และได้ขึ้นครอบครองแทนท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 15, 'ส่วนพระราชกิจนอกนั้นของชัลลูม และการร่วมกันคิดกบฏที่ท่านได้กระทํา ดูเถิด ได้บันทึกไว้ในหนังสือพงศาวดารแห่งกษัตริย์ประเทศอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 16, 'ในคราวนั้นเมนาเฮมเข้าปล้นทิฟสาห์และบรรดาผู้ที่อยู่ในเมืองนั้น และดินแดนของเมืองนั้นตั้งแต่ทีรซาห์ไป เพราะเขามิได้เปิดให้แก่ท่าน ท่านจึงโจมตีเมืองนั้น และท่านได้ผ่าท้องหญิงมีครรภ์ในเมืองนั้นเสียทุกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 17, 'ในปีที่สามสิบเก้าแห่งรัชกาลอาซาริยาห์กษัตริย์แห่งยูดาห์ เมนาเฮมบุตรชายกาดีได้เริ่มครอบครองเหนืออิสราเอล และพระองค์ทรงครอบครองในสะมาเรียสิบปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 18, 'และพระองค์ทรงกระทําสิ่งที่ชั่วร้ายในสายพระเนตรของพระเยโฮวาห์ พระองค์มิได้พรากจากบาปทั้งหลายของเยโรโบอัมบุตรชายเนบัทตลอดรัชสมัยของพระองค์ ซึ่งพระองค์ทรงกระทําให้อิสราเอลทําบาป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 19, 'ปูลกษัตริย์แห่งอัสซีเรียได้ยกขึ้นมาต่อสู้แผ่นดินนั้น และเมนาเฮมได้ถวายเงินหนึ่งพันตะลันต์แก่ปูล เพื่อจะให้ปูลช่วยให้พระองค์ยึดพระราชอาณาจักรไว้ในพระหัตถ์ของพระองค์ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 20, 'เมนาเฮมได้เร่งรัดเอาเงินนั้นมาจากอิสราเอล คือจากคนมั่งมีทุกคน เงินคนละห้าสิบเชเขล เพื่อถวายแด่กษัตริย์แห่งอัสซีเรีย กษัตริย์แห่งอัสซีเรียจึงยกทัพกลับ และมิได้ทรงยับยั้งอยู่ในแผ่นดินนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 21, 'ส่วนพระราชกิจนอกนั้นของเมนาเฮม และบรรดาสิ่งซึ่งพระองค์ทรงกระทํา มิได้บันทึกไว้ในหนังสือพงศาวดารแห่งกษัตริย์ประเทศอิสราเอลหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 22, 'และเมนาเฮมก็ล่วงหลับไปอยู่กับบรรพบุรุษของพระองค์ และเปคาหิยาห์โอรสก็ขึ้นครองแทนพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 23, 'ในปีที่ห้าสิบแห่งรัชกาลอาซาริยาห์กษัตริย์แห่งยูดาห์ เปคาหิยาห์โอรสของเมนาเฮมได้เริ่มครอบครองเหนืออิสราเอลในสะมาเรีย และพระองค์ทรงครอบครองสองปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 24, 'และพระองค์ทรงกระทําสิ่งที่ชั่วร้ายในสายพระเนตรของพระเยโฮวาห์ พระองค์มิได้ทรงพรากจากบาปทั้งหลายของเยโรโบอัมบุตรชายเนบัท ซึ่งพระองค์ทรงกระทําให้อิสราเอลทําบาป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 25, 'แต่เปคาห์บุตรชายเรมาลิยาห์ แม่ทัพของพระองค์ ได้ร่วมกันคิดกบฏต่อพระองค์ และได้ประหารพระองค์เสียในสะมาเรีย ในพระราชวังแห่งราชสํานัก กับอารโกบและอารีเอห์ และมีคนกิเลอาดห้าสิบคนร่วมกับท่าน ท่านได้สังหารพระองค์ และได้ขึ้นครอบครองแทนพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 26, 'ส่วนพระราชกิจนอกนั้นของเปคาหิยาห์ และบรรดาสิ่งซึ่งพระองค์ทรงกระทํา ดูเถิด มีบันทึกไว้ในหนังสือพงศาวดารแห่งกษัตริย์ประเทศอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 27, 'ในปีที่ห้าสิบสองแห่งรัชกาลอาซาริยาห์กษัตริย์แห่งยูดาห์ เปคาห์บุตรชายเรมาลิยาห์ได้เริ่มครอบครองเหนืออิสราเอลในสะมาเรีย และทรงครอบครองยี่สิบปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 28, 'และพระองค์ทรงกระทําสิ่งที่ชั่วร้ายในสายพระเนตรของพระเยโฮวาห์ พระองค์มิได้ทรงพรากจากบาปทั้งหลายของเยโรโบอัมบุตรชายเนบัท ซึ่งพระองค์ทรงกระทําให้อิสราเอลทําบาป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 29, 'ในรัชกาลของเปคาห์กษัตริย์แห่งอิสราเอล ทิกลัทปิเลเสอร์กษัตริย์แห่งอัสซีเรียได้ยกมาและยึดเมืองอิโยน อาเบลเบธมาอาคาห์ ยาโนอาห์ เคเดช ฮาโซร์ กิเลอาด กาลิลี แผ่นดินนัฟทาลีทั้งหมด และกวาดต้อนประชาชนเป็นเชลยไปยังอัสซีเรีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 30, 'แล้วโฮเชยาบุตรชายเอลาห์ได้ร่วมกันคิดกบฏต่อเปคาห์บุตรชายเรมาลิยาห์ และล้มพระองค์ลง และประหารพระองค์เสีย และขึ้นครองแทนพระองค์ในปีที่ยี่สิบแห่งรัชกาลโยธามโอรสของอุสซียาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 31, 'ส่วนพระราชกิจนอกนั้นของเปคาห์ และบรรดาสิ่งซึ่งพระองค์ทรงกระทํา ดูเถิด มีบันทึกไว้ในหนังสือพงศาวดารแห่งกษัตริย์ประเทศอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 32, 'ในปีที่สองแห่งรัชกาลเปคาห์บุตรชายเรมาลิยาห์กษัตริย์แห่งอิสราเอล โยธามโอรสของอุสซียาห์กษัตริย์แห่งยูดาห์ได้เริ่มครอบครอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 33, 'เมื่อพระองค์ทรงเริ่มครอบครองนั้นมีพระชนมายุยี่สิบห้าพรรษา และพระองค์ทรงครอบครองในเยรูซาเล็มสิบหกปี พระราชมารดาของพระองค์มีพระนามว่าเยรูชาบุตรสาวของศาโดก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 34, 'และพระองค์ทรงกระทําสิ่งที่ถูกต้องในสายพระเนตรของพระเยโฮวาห์ พระองค์ทรงกระทําตามทุกสิ่งที่อุสซียาห์พระราชบิดาของพระองค์ทรงกระทํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 35, 'ถึงกระนั้นปูชนียสถานสูงก็ยังมิได้ถูกกําจัดเสีย ประชาชนยังถวายสัตวบูชาและเผาเครื่องหอมบนปูชนียสถานสูงนั้น พระองค์ทรงสร้างประตูบนของพระนิเวศแห่งพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 36, 'ส่วนพระราชกิจนอกนั้นของโยธาม และบรรดาสิ่งซึ่งพระองค์ได้ทรงกระทํา มิได้บันทึกไว้ในหนังสือพงศาวดารแห่งกษัตริย์ประเทศยูดาห์หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 37, 'ในกาลครั้งนั้นพระเยโฮวาห์ได้ทรงใช้เรซีนกษัตริย์แห่งซีเรีย และเปคาห์บุตรชายเรมาลิยาห์ให้มาสู้กับยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 38, 'โยธามได้ทรงล่วงหลับไปอยู่กับบรรพบุรุษของพระองค์ และได้ฝังไว้กับบรรพบุรุษของพระองค์ในนครดาวิดบรรพบุรุษของพระองค์ และอาหัสโอรสของพระองค์ขึ้นครอบครองแทน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 1, 'ในปีที่สิบเจ็ดแห่งรัชกาลเปคาห์บุตรชายเรมาลิยาห์ อาหัสโอรสของโยธามกษัตริย์แห่งยูดาห์ได้เริ่มครอบครอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 2, 'อาหัสมีพระชนมายุยี่สิบพรรษาเมื่อพระองค์ทรงเริ่มครองราชย์ และพระองค์ทรงครองราชย์ในกรุงเยรูซาเล็มสิบหกปี และพระองค์มิได้ทรงกระทําสิ่งที่ถูกต้องในสายพระเนตรของพระเยโฮวาห์พระเจ้าของพระองค์ ดังดาวิดบรรพบุรุษของพระองค์ได้ทรงกระทํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 3, 'แต่พระองค์ทรงดําเนินตามทางของกษัตริย์ทั้งหลายแห่งอิสราเอล และถวายโอรสของพระองค์ให้ลุยไฟ ตามการกระทําอันน่าสะอิดสะเอียนของประชาชาติ ซึ่งพระเยโฮวาห์ทรงขับไล่ออกไปจากเบื้องหน้าประชาชนอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 4, 'และพระองค์ทรงถวายสัตวบูชาและเผาเครื่องหอมบนปูชนียสถานสูง และในเนินสูง และใต้ต้นไม้สีเขียวทุกต้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 5, 'แล้วเรซีนกษัตริย์แห่งซีเรียและเปคาห์บุตรชายเรมาลิยาห์กษัตริย์แห่งอิสราเอลทรงยกขึ้นมาทําสงครามกับกรุงเยรูซาเล็ม และกษัตริย์ทั้งสองได้ล้อมอาหัสไว้ แต่ทรงเอาชัยชนะยังไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 6, 'คราวนั้นเรซีนกษัตริย์แห่งซีเรียได้เข้ายึดเมืองเอลัทคืนให้ซีเรีย และทรงขับไล่พวกยิวเสียจากเอลัท และคนซีเรียมาที่เอลัท และอยู่ที่นั่นจนทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 7, 'อาหัสจึงทรงส่งผู้สื่อสารไปยังทิกลัทปิเลเสอร์กษัตริย์แห่งอัสซีเรียว่า “ข้าพเจ้าเป็นคนใช้ของท่าน และเป็นบุตรของท่าน ขอเชิญขึ้นมาช่วยข้าพเจ้าให้พ้นจากมือของกษัตริย์แห่งซีเรีย และจากมือของกษัตริย์แห่งอิสราเอล ผู้ซึ่งลุกขึ้นต่อสู้ข้าพเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 8, 'อาหัสทรงนําเอาเงินและทองคําซึ่งมีอยู่ในพระนิเวศแห่งพระเยโฮวาห์ และในคลังสํานักพระราชวัง และส่งเป็นของกํานัลถวายแด่กษัตริย์แห่งอัสซีเรีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 9, 'กษัตริย์แห่งอัสซีเรียก็ทรงฟังพระองค์ กษัตริย์แห่งอัสซีเรียก็ทรงยกทัพขึ้นไปยังดามัสกัสและยึดได้ จับประชาชนเมืองนั้นไปเป็นเชลยยังเมืองคีร์ และทรงประหารเรซีนเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 10, 'เมื่อกษัตริย์อาหัสเสด็จไปดามัสกัสเพื่อพบกับทิกลัทปิเลเสอร์กษัตริย์แห่งอัสซีเรียก็ทรงเห็นแท่นบูชาที่ดามัสกัส และกษัตริย์อาหัสทรงส่งหุ่นแท่นบูชาไปยังอุรียาห์ปุโรหิตพร้อมทั้งแบบแปลนตามลักษณะการสร้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 11, 'และอุรียาห์ปุโรหิตก็ได้สร้างแท่นบูชานั้นตามแบบทุกประการซึ่งกษัตริย์อาหัสได้ส่งมาจากดามัสกัส อุรียาห์ปุโรหิตจึงได้สร้างแท่นบูชานั้นก่อนที่กษัตริย์อาหัสเสด็จจากดามัสกัสมาถึง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 12, 'และเมื่อกษัตริย์เสด็จจากดามัสกัสถึงแล้ว กษัตริย์ก็ทรงเห็นแท่นบูชา แล้วกษัตริย์ทรงเข้ามาใกล้แท่นบูชาเสด็จขึ้นถวายบนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 13, 'และทรงเผาเครื่องเผาบูชาของพระองค์ และธัญญบูชาของพระองค์ และทรงเทเครื่องดื่มบูชาของพระองค์ และทรงพรมเลือดเครื่องสันติบูชาของพระองค์ลงบนแท่นนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 14, 'และพระองค์ทรงย้ายแท่นบูชาทองเหลือง ซึ่งอยู่ต่อพระพักตร์พระเยโฮวาห์ออกเสียจากข้างหน้าพระนิเวศ จากสถานที่ระหว่างแท่นบูชาและพระนิเวศของพระเยโฮวาห์ และตั้งไว้ทางด้านเหนือแห่งแท่นบูชานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 15, 'และกษัตริย์อาหัสทรงบัญชากับอุรียาห์ปุโรหิตว่า “บนแท่นใหญ่นี้ท่านจงเผาเครื่องเผาบูชาตอนเช้าและธัญญบูชาตอนเย็น และเครื่องเผาบูชาของกษัตริย์ และเครื่องธัญญบูชาของพระองค์ พร้อมกับเครื่องเผาบูชาของบรรดาประชาชนแห่งแผ่นดิน และธัญญบูชาของเขาทั้งหลาย และเครื่องดื่มบูชาของเขาทั้งหลาย และจงพรมเลือดทั้งหมดของเครื่องเผาบูชาบนนั้น และเลือดทั้งหมดของเครื่องสัตวบูชา แต่แท่นบูชาทองเหลืองให้เป็นที่ที่ข้าจะทูลถามพระเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 16, 'อุรียาห์ปุโรหิตได้กระทําการเหล่านี้ทั้งสิ้นตามพระบัญชาของกษัตริย์อาหัส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 17, 'และกษัตริย์อาหัสทรงตัดแผงแท่นนั้นออก และทรงยกขันออกไปจากแท่นเสีย และพระองค์ทรงเอาขันสาครลงมาเสียจากวัวทองเหลืองที่รองอยู่นั้น ทรงวางไว้บนพื้นก้อนหิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 18, 'และศาลาวันสะบาโตซึ่งเขาได้สร้างไว้ในพระนิเวศ และทางเข้าพระนิเวศของพระเยโฮวาห์ชั้นนอกสําหรับกษัตริย์นั้น พระองค์ทรงเปลี่ยนเสีย เพราะเห็นแก่กษัตริย์แห่งอัสซีเรีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 19, 'ส่วนพระราชกิจนอกนั้นของอาหัส ซึ่งพระองค์ทรงกระทํา มิได้บันทึกไว้ในหนังสือพงศาวดารแห่งกษัตริย์ประเทศยูดาห์หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 20, 'และอาหัสทรงล่วงหลับไปอยู่กับบรรพบุรุษของพระองค์ และเขาฝังไว้กับบรรพบุรุษของพระองค์ในนครดาวิด และเฮเซคียาห์โอรสของพระองค์ขึ้นครอบครองแทนพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 1, 'ในปีที่สิบสองแห่งรัชกาลอาหัสกษัตริย์แห่งยูดาห์ โฮเชยาบุตรชายเอลาห์ได้เริ่มครอบครองในกรุงสะมาเรียเหนืออิสราเอล และพระองค์ทรงครอบครองเก้าปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 2, 'และพระองค์ทรงกระทําสิ่งที่ชั่วร้ายในสายพระเนตรของพระเยโฮวาห์ แต่ก็ไม่เหมือนกับกษัตริย์ทั้งหลายแห่งอิสราเอลที่อยู่มาก่อนพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 3, 'แชลมาเนเสอร์กษัตริย์แห่งอัสซีเรียได้ยกทัพมารบกับพระองค์ และโฮเชยาทรงยอมเป็นผู้รับใช้และถวายเครื่องบรรณาการ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 4, 'แต่กษัตริย์อัสซีเรียได้ทรงพบความทรยศในโฮเชยา เพราะพระองค์ทรงใช้ผู้สื่อสารไปยังโสกษัตริย์แห่งอียิปต์ และไม่ถวายเครื่องบรรณาการแด่กษัตริย์อัสซีเรียตามซึ่งพระองค์ทรงเคยกระทําทุกปี เพราะฉะนั้นกษัตริย์แห่งอัสซีเรียจึงขังพระองค์ไว้ และจําพระองค์ไว้ในคุก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 5, 'แล้วกษัตริย์แห่งอัสซีเรียก็ทรงบุกเข้าทั่วแผ่นดินและมายังสะมาเรีย และพระองค์ทรงล้อมเมืองไว้สามปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 6, 'ในปีที่เก้าแห่งรัชกาลโฮเชยา กษัตริย์แห่งอัสซีเรียยึดเมืองสะมาเรียได้ และพระองค์ทรงนําชนอิสราเอลไปยังอัสซีเรีย ให้เขาอยู่ที่ฮาลาห์ และข้างแม่น้ําฮาโบร์ แม่น้ําเมืองโกซาน และในหัวเมืองแห่งชาวมีเดีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 7, 'ที่เป็นอย่างนั้น ก็เพราะประชาชนอิสราเอลได้กระทําบาปต่อพระเยโฮวาห์พระเจ้าของตน ผู้ทรงนําเขาขึ้นออกมาจากแผ่นดินอียิปต์ จากพระหัตถ์ของฟาโรห์กษัตริย์แห่งอียิปต์ และได้เกรงกลัวพระอื่นๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 8, 'และได้ดําเนินตามกฎเกณฑ์แห่งประชาชาติทั้งหลาย ซึ่งพระเยโฮวาห์ได้ทรงขับไล่ไปเสียให้พ้นหน้าประชาชนอิสราเอล และตามกฎเกณฑ์ซึ่งกษัตริย์แห่งอิสราเอลทรงทําขึ้นมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 9, 'และประชาชนอิสราเอลได้กระทําสิ่งที่ไม่ชอบต่อพระเยโฮวาห์พระเจ้าของตนอย่างลับๆ เขาได้สร้างปูชนียสถานสูงทั่วบ้านทั่วเมืองสําหรับตน ตั้งแต่ที่ที่มีหอคอยเหตุ กระทั่งถึงเมืองที่มีป้อม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 10, 'เขาได้ตั้งเสาศักดิ์สิทธิ์และเสารูปเคารพบนเนินเขาสูงทุกแห่ง และใต้ต้นไม้เขียวทุกต้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 11, 'ณ ที่นั่นเขาได้เผาเครื่องหอมบนปูชนียสถานสูงทั้งหมดนั้น ตามอย่างประชาชาติซึ่งพระเยโฮวาห์ทรงกวาดไปเสียต่อหน้าเขาทั้งหลาย และเขาทั้งหลายได้กระทําสิ่งชั่วร้ายกระทําให้พระเยโฮวาห์ทรงพระพิโรธ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 12, 'และเขาทั้งหลายปรนนิบัติรูปเคารพ ซึ่งพระเยโฮวาห์ได้ตรัสแก่เขาแล้วว่า “เจ้าอย่ากระทําอย่างนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 13, 'พระเยโฮวาห์ยังทรงตักเตือนอิสราเอลและยูดาห์โดยผู้พยากรณ์ทุกคนและโดยผู้ทํานายทุกคนว่า “จงหันกลับจากทางชั่วร้ายทั้งหลายของเจ้า และรักษาบัญญัติของเราและกฎเกณฑ์ของเรา ตามราชบัญญัติทุกข้อซึ่งเราได้บัญชาแก่บรรพบุรุษของเจ้า และซึ่งเราได้ส่งมายังเจ้าโดยผู้พยากรณ์ผู้รับใช้ของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 14, 'เขาไม่ฟังแต่ทําให้คอของตนแข็ง ดังคอของบรรพบุรุษของเขาได้เป็นมาแล้ว ผู้ซึ่งมิได้เชื่อถือพระเยโฮวาห์พระเจ้าของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 15, 'เขาทอดทิ้งกฎเกณฑ์ของพระองค์ และพันธสัญญาของพระองค์ซึ่งได้ทรงกระทําไว้กับบรรพบุรุษของเขา และพระโอวาทซึ่งพระองค์ได้ทรงประทานแก่เขา เขาทั้งหลายติดตามสิ่งที่ไร้สาระและกลายเป็นผู้ที่ไร้สาระไป และเขาติดตามประชาชาติที่อยู่รอบๆเขา ซึ่งพระเยโฮวาห์ได้ทรงบัญชาเขามิให้เขากระทําตาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 16, 'และเขาทั้งหลายได้ละทิ้งพระบัญญัติทั้งสิ้นของพระเยโฮวาห์พระเจ้าของตน และได้หล่อรูปเคารพสําหรับตนเป็นลูกวัวสองตัว และเขาได้สร้างเสารูปเคารพ และนมัสการบรรดาบริวารของฟ้าสวรรค์ และปรนนิบัติพระบาอัล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 17, 'และเขาทั้งหลายได้ถวายบุตรชายหญิงของเขาให้ลุยไฟ ใช้การทํานายและใช้เวทมนตร์ และยอมขายตัวเองเพื่อกระทําความชั่วร้ายในสายพระเนตรของพระเยโฮวาห์ ซึ่งเป็นการยั่วยุให้พระองค์ทรงกริ้วโกรธ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 18, 'เพราะฉะนั้นพระเยโฮวาห์ทรงพระพิโรธต่ออิสราเอลยิ่งนัก และทรงให้เขาออกไปเสียจากสายพระเนตรของพระองค์ ไม่มีผู้ใดเหลืออยู่นอกจากตระกูลยูดาห์เท่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 19, 'ยูดาห์มิได้รักษาพระบัญญัติของพระเยโฮวาห์พระเจ้าของเขาด้วย แต่ดําเนินตามกฎเกณฑ์ซึ่งอิสราเอลทําขึ้นมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 20, 'และพระเยโฮวาห์ทรงปฏิเสธไม่รับเชื้อสายทั้งสิ้นของอิสราเอล และได้ให้เขาทั้งหลายทุกข์ใจ และทรงมอบเขาไว้ในมือของผู้ปล้น จนกว่าพระองค์ได้ทรงเหวี่ยงเขาเสียจากสายพระเนตรของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 21, 'เพราะพระองค์ทรงฉีกอิสราเอลจากราชวงศ์ของดาวิด และเขาได้ตั้งเยโรโบอัมบุตรชายเนบัทให้เป็นกษัตริย์ และเยโรโบอัมทรงชักนําอิสราเอลไปจากการที่ติดตามพระเยโฮวาห์ และกระทําให้เขาทําบาปอย่างใหญ่หลวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 22, 'ประชาชนอิสราเอลได้ดําเนินในความบาปทั้งสิ้นซึ่งเยโรโบอัมได้ทรงกระทํา เขาทั้งหลายไม่พรากจากบาปเหล่านั้นเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 23, 'จนพระเยโฮวาห์ทรงให้อิสราเอลออกไปเสียจากสายพระเนตรของพระองค์ ตามที่พระองค์ตรัสโดยบรรดาผู้พยากรณ์ผู้รับใช้ของพระองค์ อิสราเอลจึงถูกกวาดไปเป็นเชลยจากแผ่นดินของตนยังประเทศอัสซีเรียจนทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 24, 'และกษัตริย์แห่งอัสซีเรียได้นําประชาชนมาจากบาบิโลน คูธาห์ อิฟวาห์ ฮามัท เสฟารวาอิม และบรรจุเขาไว้ในหัวเมืองสะมาเรียแทนประชาชนอิสราเอล เขาทั้งหลายก็เข้าถือกรรมสิทธิ์สะมาเรีย และอาศัยอยู่ในหัวเมืองของประเทศนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 25, 'และตั้งแต่ต้นที่เขามาอาศัยอยู่ที่นั่น เขามิได้ยําเกรงพระเยโฮวาห์ ฉะนั้นพระเยโฮวาห์จึงทรงใช้สิงโตมาท่ามกลางเขา ซึ่งได้ฆ่าเขาเสียบ้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 26, 'เพราะฉะนั้นมีผู้ไปทูลกษัตริย์แห่งอัสซีเรียว่า “ประชาชาติซึ่งพระองค์ได้ทรงพาเอาไปให้อยู่ในหัวเมืองสะมาเรียนั้นไม่รู้ลักษณะของพระเจ้าของแผ่นดินนั้น ฉะนั้นพระองค์จึงส่งสิงโตมาท่ามกลางเขา และดูเถิด สิงโตนั้นได้ฆ่าเขาเสีย เพราะเขาไม่รู้พระลักษณะแห่งพระเจ้าของแผ่นดินนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 27, 'แล้วกษัตริย์แห่งอัสซีเรียจึงบัญชาว่า “จงส่งปุโรหิตสักคนหนึ่งไปที่นั่นจากบรรดาที่เจ้ากวาดเอามา จงให้เขาไปอยู่ที่นั่น และให้สั่งสอนพระลักษณะแห่งพระเจ้าของแผ่นดินนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 28, 'ฉะนั้นปุโรหิตผู้หนึ่งในบรรดาซึ่งเขากวาดมาจากสะมาเรียจึงมาอาศัยอยู่ที่เบธเอลและสั่งสอนเขาทั้งหลายว่า เขาจะต้องยําเกรงพระเยโฮวาห์อย่างไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 29, 'แต่ว่าทุกๆประชาชาติยังสร้างรูปพระของตนเอง และตั้งไว้ในนิเวศแห่งปูชนียสถานสูงซึ่งชาวสะมาเรียได้สร้างไว้ ทุกๆประชาชาติในหัวเมืองที่เขาอาศัยอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 30, 'ชาวบาบิโลนสร้างพระสุคคทเบโนท ชาวคูทสร้างพระเนอร์กัล ชาวฮามัทสร้างพระอาชิมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 31, 'และชาวอิฟวาห์สร้างพระนิบหัสและพระทารทัก และชาวเสฟารวาอิมเผาลูกของตนในไฟถวายพระอัดรัมเมเลคและพระอานัมเมเลค ซึ่งเป็นพระของเมืองเสฟารวาอิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 32, 'เขาทั้งหลายเกรงกลัวพระเยโฮวาห์ด้วย และได้กําหนดประชาชนจากท่ามกลางเขาให้เป็นปุโรหิตของปูชนียสถานสูงนั้น ซึ่งถวายสัตวบูชาสําหรับพวกเขาในนิเวศแห่งปูชนียสถานสูงเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 33, 'เขาจึงเกรงกลัวพระเยโฮวาห์ แต่ปรนนิบัติพระของเขาเองด้วย ตามอย่างประชาชาติซึ่งเขาได้ถูกนําให้ออกมาจากที่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 34, 'ทุกวันนี้เขาก็กระทําตามอย่างเดิม เขาทั้งหลายไม่ยําเกรงพระเยโฮวาห์ และเขาทั้งหลายไม่กระทําตามกฎเกณฑ์ หรือกฎ หรือพระราชบัญญัติ หรือพระบัญญัติ ซึ่งพระเยโฮวาห์ทรงบัญชาแก่ลูกหลานของยาโคบ ผู้ซึ่งพระองค์ทรงประทานนามว่าอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 35, 'ซึ่งพระเยโฮวาห์ทรงกระทําพันธสัญญากับเขาทั้งหลายและบัญชาแก่เขาว่า “เจ้าอย่ายําเกรงพระอื่นๆ หรือกราบนมัสการพระนั้น หรือปรนนิบัติ หรือถวายสัตวบูชาแก่พระนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 36, 'แต่เจ้าจงยําเกรงพระเยโฮวาห์ ผู้ซึ่งนําเจ้าขึ้นออกมาจากแผ่นดินอียิปต์ด้วยกําลังอันยิ่งใหญ่และด้วยพระหัตถ์ที่เหยียดออก เจ้าจงโน้มตัวลงต่อพระองค์ และเจ้าจงถวายสัตวบูชาต่อพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 37, 'และกฎเกณฑ์ และกฎ และพระราชบัญญัติ และพระบัญญัติซึ่งพระองค์ทรงจารึกให้แก่เจ้า เจ้าทั้งหลายจงระวังที่จะกระทําตามเสมอ เจ้าอย่ายําเกรงพระอื่นเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 38, 'เจ้าทั้งหลายอย่าลืมพันธสัญญาซึ่งเราได้กระทําไว้กับเจ้า และอย่ายําเกรงพระอื่นเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 39, 'แต่เจ้าทั้งหลายจงยําเกรงพระเยโฮวาห์พระเจ้าของเจ้า และพระองค์จะทรงช่วยเจ้าให้พ้นมือศัตรูทั้งสิ้นของเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 40, 'ถึงอย่างนั้นเขาทั้งหลายก็มิได้ฟัง แต่เขายังกระทําตามอย่างเดิมของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 41, 'ประชาชาติเหล่านี้จึงเกรงกลัวพระเยโฮวาห์ และปรนนิบัติรูปเคารพสลักของเขาด้วย ลูกของเขาก็เช่นเดียวกัน หลานของเขาก็เช่นเดียวกัน บรรพบุรุษของเขาทําอย่างไร เขาก็กระทําอย่างนั้นจนทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 1, 'อยู่มาในปีที่สามแห่งรัชกาลโฮเชยาบุตรชายเอลาห์กษัตริย์แห่งอิสราเอล เฮเซคียาห์โอรสของอาหัสกษัตริย์แห่งยูดาห์ได้เริ่มครอบครอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 2, 'เมื่อพระองค์ทรงเริ่มครอบครองนั้นพระองค์มีพระชนมายุยี่สิบห้าพรรษา และพระองค์ทรงครอบครองในกรุงเยรูซาเล็มยี่สิบเก้าปี พระราชมารดาของพระองค์มีพระนามว่าอาบีบุตรสาวของเศคาริยาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 3, 'และพระองค์ทรงกระทําสิ่งที่ถูกต้องในสายพระเนตรของพระเยโฮวาห์ ตามทุกสิ่งที่ดาวิดบรรพบุรุษของพระองค์ได้ทรงกระทํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 4, 'พระองค์ทรงรื้อปูชนียสถานสูงทิ้งไป และทรงพังเสาศักดิ์สิทธิ์เสีย และตัดเสารูปเคารพลงเสีย และพระองค์ทรงทุบงูทองเหลืองซึ่งโมเสสสร้างขึ้นนั้นเป็นชิ้นๆ เพราะว่าประชาชนอิสราเอลได้เผาเครื่องหอมให้แก่งูนั้นจนถึงวันเหล่านั้น เขาเรียกงูนั้นว่าเนหุชทาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 5, 'พระองค์ทรงวางพระทัยในพระเยโฮวาห์พระเจ้าแห่งอิสราเอล เพราะฉะนั้นในบรรดากษัตริย์แห่งยูดาห์ต่อจากพระองค์มาหรือในบรรดาผู้อยู่ก่อนพระองค์ ไม่มีผู้ใดเหมือนพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 6, 'เพราะว่าพระองค์ทรงยึดพระเยโฮวาห์แน่น พระองค์มิได้ทรงพรากจากการติดตามพระองค์เลย แต่ได้รักษาพระบัญญัติซึ่งพระเยโฮวาห์ทรงบัญชาแก่โมเสส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 7, 'และพระเยโฮวาห์ทรงสถิตกับพระองค์ พระองค์ทรงออกไปยังที่ใด พระองค์ก็ทรงกระทําความสําเร็จที่นั่น พระองค์ได้ทรงกบฏต่อกษัตริย์แห่งอัสซีเรีย และไม่ยอมปรนนิบัติท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 8, 'พระองค์ทรงโจมตีคนฟีลิสเตียไกลไปจนถึงเมืองกาซาและดินแดนเมืองนั้น ตั้งแต่ที่ที่มีหอคอยเหตุกระทั่งถึงเมืองที่มีป้อม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 9, 'และอยู่มาในปีที่สี่แห่งรัชกาลกษัตริย์เฮเซคียาห์ ซึ่งเป็นปีที่เจ็ดแห่งรัชกาลโฮเชยาบุตรชายเอลาห์กษัตริย์แห่งอิสราเอล แชลมาเนเสอร์กษัตริย์แห่งอัสซีเรียได้ทรงยกขึ้นมารบสะมาเรียและล้อมเมืองไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 10, 'และเมื่อสิ้นสามปีเขาก็ยึดเมืองนั้นได้ ในปีที่หกแห่งรัชกาลเฮเซคียาห์ ซึ่งเป็นปีที่เก้าแห่งรัชกาลโฮเชยากษัตริย์แห่งอิสราเอล สะมาเรียก็ถูกยึดไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 11, 'กษัตริย์แห่งอัสซีเรียได้กวาดเอาคนอิสราเอลไปยังอัสซีเรีย ไปไว้ที่ฮาลาห์ และข้างแม่น้ําฮาโบร์แม่น้ําเมืองโกซาน และในหัวเมืองของคนมีเดีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 12, 'เพราะว่าเขาทั้งหลายมิได้เชื่อฟังพระสุรเสียงของพระเยโฮวาห์พระเจ้าของตน แต่ได้ละเมิดพันธสัญญาของพระองค์ คือทุกอย่างซึ่งโมเสสผู้รับใช้ของพระเยโฮวาห์ได้บัญชาไว้ และเขาทั้งหลายไม่ฟัง ไม่กระทําตาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 13, 'ในปีที่สิบสี่แห่งรัชกาลกษัตริย์เฮเซคียาห์ เซนนาเคอริบกษัตริย์แห่งอัสซีเรียได้ทรงยกขึ้นมาต่อสู้บรรดานครที่มีป้อมของยูดาห์ และยึดได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 14, 'และเฮเซคียาห์กษัตริย์แห่งยูดาห์ทรงใช้ให้ไปทูลกษัตริย์แห่งอัสซีเรียที่เมืองลาคีชว่า “ข้าพเจ้าได้กระทําผิด ขอถอนทัพไปเสียจากข้าพเจ้า ท่านจะปรับสักเท่าใด ข้าพเจ้าจะยอมทั้งสิ้น” และกษัตริย์แห่งอัสซีเรียได้เรียกร้องเอาเงินสามร้อยตะลันต์ และทองคําสามสิบตะลันต์ จากเฮเซคียาห์กษัตริย์แห่งยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 15, 'และเฮเซคียาห์ได้มอบเงินทั้งหมดซึ่งมีอยู่ในพระนิเวศของพระเยโฮวาห์ และในคลังสํานักพระราชวัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 16, 'ในครั้งนั้นเฮเซคียาห์ทรงลอกทองคําจากประตูทั้งหลายของพระวิหารแห่งพระเยโฮวาห์ และจากเสาประตูซึ่งเฮเซคียาห์กษัตริย์แห่งยูดาห์ทรงบุทองคําไว้ และทรงมอบให้แด่กษัตริย์แห่งอัสซีเรีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 17, 'และกษัตริย์แห่งอัสซีเรียได้รับสั่งให้ทารทาน รับสารีสและรับชาเคห์ไปพร้อมกับกองทัพใหญ่จากเมืองลาคีชถึงกรุงเยรูซาเล็มเข้าเฝ้ากษัตริย์เฮเซคียาห์ เขาก็ขึ้นไปยังกรุงเยรูซาเล็ม เมื่อเขาขึ้นมาเขาก็มายืนอยู่ทางรางระบายน้ําสระบน ซึ่งอยู่ที่ถนนลานซักฟอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 18, 'และเมื่อเขาเรียกหากษัตริย์แล้ว เอลียาคิมบุตรชายฮิลคียาห์ ผู้บัญชาการราชสํานัก พร้อมกับเชบนาห์ราชเลขา และโยอาห์บุตรชายของอาสาฟเจ้ากรมสารบรรณ ก็ออกไปหาพวกเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 19, 'และรับชาเคห์พูดกับเขาว่า “จงทูลเฮเซคียาห์ว่า ‘พระมหากษัตริย์ คือกษัตริย์แห่งอัสซีเรีย ตรัสดังนี้ว่า ท่านวางใจในอะไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 20, 'ท่านคิดว่า (แต่เป็นเพียงแต่ถ้อยคําไร้สาระ) “เรามียุทธศาสตร์และแสนยานุภาพ” หรือ เดี๋ยวนี้ท่านวางใจในใคร ท่านจึงได้กบฏต่อเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 21, 'ดูเถิด เดี๋ยวนี้ท่านวางใจในไม้เท้าอ้อช้ํา คืออียิปต์ ซึ่งจะตํามือของคนใดๆที่ใช้ไม้เท้านั้นยัน ฟาโรห์กษัตริย์แห่งอียิปต์เป็นเช่นนั้นต่อทุกคนที่วางใจในเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 22, 'แต่ถ้าท่านทั้งหลายจะบอกเราว่า “เราวางใจในพระเยโฮวาห์พระเจ้าของเรา” ก็ปูชนียสถานสูงและแท่นบูชาของพระองค์นั้นมิใช่หรือที่เฮเซคียาห์รื้อทิ้งเสียแล้ว พลางกล่าวแก่ยูดาห์และเยรูซาเล็มว่า “ท่านทั้งหลายจงนมัสการที่หน้าแท่นบูชานี้ในเยรูซาเล็มเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 23, 'ฉะนั้นบัดนี้ มาเถิด มาทําสัญญากันกับกษัตริย์แห่งอัสซีเรียนายของข้า เราจะให้ม้าสองพันตัวแก่เจ้า ถ้าฝ่ายเจ้าหาคนที่ขี่ม้าเหล่านั้นได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 24, 'แล้วอย่างนั้นเจ้าจะขับไล่นายกองแต่เพียงคนเดียวในหมู่ข้าราชการผู้น้อยที่สุดของนายของเราอย่างไรได้ แต่เจ้ายังวางใจพึ่งอียิปต์เพื่อรถรบและเพื่อพลม้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 25, 'ยิ่งกว่านั้นอีกที่เรามาต่อสู้สถานที่นี้เพื่อทําลายเสีย ก็ขึ้นมาโดยปราศจากพระเยโฮวาห์หรือ พระเยโฮวาห์ตรัสแก่ข้าว่า “จงขึ้นไปต่อสู้กับแผ่นดินนี้และทําลายเสีย”’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 26, 'แล้วเอลียาคิมบุตรชายฮิลคียาห์และเชบนาห์และโยอาห์ เรียนรับชาเคห์ว่า “ขอทีเถอะ ขอพูดกับผู้รับใช้ของท่านเป็นภาษาอารัมเถิด เพราะเราเข้าใจภาษานั้น ขออย่าพูดกับเราเป็นภาษาฮีบรูให้ประชาชนผู้อยู่บนกําแพงนั้นได้ยินเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 27, 'แต่รับชาเคห์พูดกับเขาทั้งหลายว่า “นายของข้าใช้ให้เรามาพูดถ้อยคําเหล่านี้แก่นายของเจ้าและแก่เจ้า และไม่ให้พูดกับคนที่นั่งอยู่บนกําแพง ผู้ที่จะต้องกินขี้และกินเยี่ยวของเขาพร้อมกับเจ้าอย่างนั้นหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 28, 'แล้วรับชาเคห์ได้ยืนร้องตะโกนเสียงดังเป็นภาษาฮีบรูว่า “จงฟังพระวจนะของพระมหากษัตริย์ คือกษัตริย์แห่งอัสซีเรีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 29, 'กษัตริย์ตรัสดังนี้ว่า ‘อย่าให้เฮเซคียาห์ลวงเจ้า เพราะเขาไม่สามารถที่จะช่วยเจ้าให้พ้นจากพระหัตถ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 30, 'อย่าให้เฮเซคียาห์กระทําให้เจ้าวางใจในพระเยโฮวาห์โดยกล่าวว่า “พระเยโฮวาห์จะทรงช่วยเราให้พ้นแน่ และจะไม่ทรงมอบเมืองนี้ไว้ในมือของกษัตริย์แห่งอัสซีเรีย”’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 31, 'อย่าฟังเฮเซคียาห์ เพราะกษัตริย์แห่งอัสซีเรียตรัสดังนี้ว่า ‘จงทําสัญญาไมตรีกับเราด้วยของกํานัล และออกมาหาเรา แล้วทุกคนจะได้กินจากเถาองุ่นของตน และทุกคนจะกินจากต้นมะเดื่อของตน และทุกคนจะดื่มน้ําจากที่ขังน้ําของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 32, 'จนเราจะมานําเจ้าไปยังแผ่นดินที่เหมือนแผ่นดินของเจ้าเอง เป็นแผ่นดินที่มีข้าวและน้ําองุ่น เป็นแผ่นดินที่มีขนมปังและสวนองุ่น เป็นแผ่นดินที่มีน้ํามันมะกอกเทศและน้ําผึ้ง เพื่อเจ้าทั้งหลายจะมีชีวิตอยู่และไม่ตาย และอย่าฟังเฮเซคียาห์เมื่อเขานําเจ้าผิดไปโดยกล่าวว่า “พระเยโฮวาห์จะทรงช่วยเราทั้งหลายให้พ้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 33, 'มีพระแห่งประชาชาติองค์ใดเคยช่วยแผ่นดินของตนให้พ้นจากพระหัตถ์ของกษัตริย์แห่งอัสซีเรียได้หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 34, 'พระของเมืองฮามัทและเมืองอารปัดอยู่ที่ไหน พระของเมืองเสฟารวาอิม เฮนาและอิฟวาห์อยู่ที่ไหน เขาได้ช่วยสะมาเรียให้พ้นจากมือของเราหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 35, 'พระองค์ใดในบรรดาพระทั้งหลายของประเทศเหล่านี้ได้ช่วยประเทศของตนให้พ้นจากมือของเรา แล้วพระเยโฮวาห์จะทรงช่วยเยรูซาเล็มให้พ้นจากมือของเราหรือ’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 36, 'แต่ประชาชนนิ่งไม่ตอบเขาสักคําเดียว เพราะพระบัญชาของกษัตริย์มีว่า “อย่าตอบเขาเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 37, 'แล้วเอลียาคิมบุตรชายฮิลคียาห์ ผู้บัญชาการราชสํานัก และเชบนาห์ราชเลขา และโยอาห์บุตรชายอาสาฟเจ้ากรมสารบรรณ ได้เข้าเฝ้าเฮเซคียาห์ด้วยเสื้อผ้าฉีกขาด และกราบทูลถ้อยคําของรับชาเคห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 1, 'อยู่มาเมื่อกษัตริย์เฮเซคียาห์ทรงได้ยิน พระองค์ก็ทรงฉีกฉลองพระองค์เสีย และทรงเอาผ้ากระสอบคลุมพระองค์ และเสด็จเข้าไปในพระนิเวศของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 2, 'และพระองค์ทรงใช้เอลียาคิม ผู้บัญชาการราชสํานัก และเชบนาห์ราชเลขา และพวกปุโรหิตใหญ่ คลุมตัวด้วยผ้ากระสอบ ไปหาอิสยาห์ผู้พยากรณ์บุตรชายของอามอส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 3, 'เขาทั้งหลายเรียนท่านว่า “เฮเซคียาห์ตรัสดังนี้ว่า ‘วันนี้เป็นวันทุกข์ใจ วันถูกติเตียนและหมิ่นประมาท เด็กก็ถึงกําหนดคลอด แต่ไม่มีกําลังเบ่งให้คลอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 4, 'ชะรอยพระเยโฮวาห์พระเจ้าของท่านคงจะสดับบรรดาถ้อยคําของรับชาเคห์ ผู้ซึ่งกษัตริย์แห่งอัสซีเรียนายของเขาได้สั่งมาให้เย้ยพระเจ้าผู้ทรงพระชนม์ และจะทรงขนาบถ้อยคําซึ่งพระเยโฮวาห์พระเจ้าของท่านได้ทรงสดับ เพราะฉะนั้นขอท่านถวายคําอธิษฐานเพื่อส่วนชนที่เหลืออยู่นี้’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 5, 'ดังนั้นข้าราชการของกษัตริย์เฮเซคียาห์มาถึงอิสยาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 6, 'อิสยาห์ก็บอกเขาทั้งหลายว่า “จงทูลนายของท่านเถิดว่า พระเยโฮวาห์ตรัสดังนี้ว่า ‘อย่ากลัวเพราะถ้อยคําที่เจ้าได้ยินนั้น ซึ่งข้าราชการของกษัตริย์แห่งอัสซีเรียได้กล่าวหยาบช้าต่อเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 7, 'ดูเถิด เราจะบรรจุจิตใจอย่างหนึ่งในเขา เพื่อเขาจะได้ยินข่าวลือ และกลับไปยังแผ่นดินของเขา และเราจะให้เขาล้มลงด้วยดาบในแผ่นดินของเขาเอง’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 8, 'รับชาเคห์ได้กลับไป และได้พบกษัตริย์แห่งอัสซีเรียสู้รบเมืองลิบนาห์ เพราะเขาได้ยินว่าพระองค์ออกจากลาคีชแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 9, 'และเมื่อกษัตริย์ทรงได้ยินเรื่องทีรหะคาห์กษัตริย์แห่งเอธิโอเปียว่า “ดูเถิด เขาได้ยกออกมาสู้รบกับพระองค์แล้ว” พระองค์จึงส่งผู้สื่อสารไปเฝ้าเฮเซคียาห์ทูลว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 10, '“เจ้าจงพูดกับเฮเซคียาห์กษัตริย์แห่งยูดาห์ดังนี้ว่า ‘อย่าให้พระเจ้าของท่านซึ่งท่านวางใจนั้นลวงท่านว่า “เยรูซาเล็มจะมิได้ถูกมอบไว้ในมือของกษัตริย์แห่งอัสซีเรีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 11, 'ดูเถิด ท่านได้ยินแล้วว่า บรรดากษัตริย์แห่งอัสซีเรียได้กระทําอะไรกับแผ่นดินทั้งสิ้นบ้าง ทําลายเสียหมดอย่างสิ้นเชิง ส่วนท่านเองจะรับการช่วยให้พ้นหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 12, 'บรรดาพระของบรรดาประชาชาติได้ช่วยเขาให้รอดพ้นหรือ คือประชาชาติซึ่งบรรพบุรุษของเราได้ทําลาย คือโกซาน ฮาราน เรเซฟ และประชาชนของเอเดนซึ่งอยู่ในเทลอัสสาร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 13, 'กษัตริย์ของฮามัท กษัตริย์ของอารปัด กษัตริย์ของเมืองเสฟารวาอิม เฮนาและอิฟวาห์อยู่ที่ไหน’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 14, 'เฮเซคียาห์ทรงรับจดหมายจากมือของผู้สื่อสาร และทรงอ่าน และเฮเซคียาห์ได้ขึ้นไปยังพระนิเวศของพระเยโฮวาห์ และทรงคลี่จดหมายนั้นออกต่อเบื้องพระพักตร์พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 15, 'และเฮเซคียาห์ทรงอธิษฐานต่อเบื้องพระพักตร์พระเยโฮวาห์ว่า “โอ ข้าแต่พระเยโฮวาห์พระเจ้าแห่งอิสราเอล ผู้ทรงประทับระหว่างพวกเครูบ พระองค์ทรงเป็นพระเจ้าแห่งบรรดาราชอาณาจักรของแผ่นดินโลก พระองค์แต่องค์เดียว พระองค์ได้ทรงสร้างฟ้าสวรรค์และแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 16, 'ข้าแต่พระเยโฮวาห์ ขอทรงเงี่ยพระกรรณสดับ ข้าแต่พระเยโฮวาห์ ขอทรงเบิกพระเนตรทอดพระเนตร และขอทรงสดับถ้อยคําของเซนนาเคอริบ ซึ่งเขาได้ใช้มาเย้ยพระเจ้าผู้ทรงพระชนม์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 17, 'ข้าแต่พระเยโฮวาห์ เป็นความจริงที่กษัตริย์แห่งอัสซีเรียได้กระทําแก่ประชาชาติทั้งหลายและแผ่นดินของประชาชาตินั้นร้างเปล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 18, 'และได้เหวี่ยงพระของประชาชาตินั้นเข้าไฟ เพราะเขามิใช่พระ เป็นแต่ผลงานของมือมนุษย์ เป็นไม้และหิน เพราะฉะนั้นเขาจึงถูกทําลายเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 19, 'ฉะนั้นบัดนี้ โอ ข้าแต่พระเยโฮวาห์พระเจ้าของข้าพระองค์ทั้งหลาย ขอทรงช่วยข้าพระองค์ให้พ้นมือของเขา เพื่อราชอาณาจักรทั้งสิ้นแห่งแผ่นดินโลกจะทราบว่า พระองค์ทรงเป็นพระเยโฮวาห์พระเจ้าแต่พระองค์เดียว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 20, 'แล้วอิสยาห์บุตรชายอามอสได้ใช้ให้ไปเฝ้าเฮเซคียาห์ทูลว่า “พระเยโฮวาห์พระเจ้าแห่งอิสราเอลตรัสดังนี้ว่า เราได้ยินคําอธิษฐานของเจ้าเรื่องเซนนาเคอริบกษัตริย์แห่งอัสซีเรียแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 21, 'ต่อไปนี้เป็นพระวจนะที่พระเยโฮวาห์ตรัสเกี่ยวกับท่านนั้นว่า ‘ธิดาพรหมจารีแห่งศิโยนดูหมิ่นเจ้า และหัวเราะเยาะเย้ยเจ้า ธิดาแห่งเยรูซาเล็มสั่นศีรษะใส่เจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 22, 'เจ้าเย้ยและกล่าวหยาบช้าต่อผู้ใด เจ้าขึ้นเสียงของเจ้าต่อผู้ใด แล้วเบิ่งตาของเจ้าอย่างเย่อหยิ่งต่อผู้ใด ต่อองค์บริสุทธิ์แห่งอิสราเอลน่ะซิ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 23, 'เจ้าได้เย้ยองค์พระผู้เป็นเจ้าด้วยผู้สื่อสารของเจ้า และเจ้าได้ว่า “ด้วยรถรบเป็นอันมากของข้า ข้าได้ขึ้นไปที่สูงของภูเขา ถึงที่ไกลสุดของเลบานอน ข้าจะโค่นต้นสนสีดาร์ที่สูงที่สุดของมันลง ทั้งต้นสนสามใบที่ดีที่สุดของมัน ข้าจะเข้าไปในที่พํานักในชายแดนของมัน และที่ป่าไม้แห่งคารเมล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 24, 'ข้าขุดบ่อและดื่มน้ําต่างด้าว ข้าเอาฝ่าเท้าของข้ากวาดธารน้ําทั้งสิ้นของสถานที่ที่ถูกล้อมโจมตีให้แห้งไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 25, 'เจ้าไม่ได้ยินหรือว่า เราได้จัดไว้นานแล้ว เราได้กะแผนงานไว้แต่ดึกดําบรรพ์ ณ บัดนี้เราให้เป็นไปแล้ว คือเจ้าจะทําเมืองที่มีป้อมให้พังลงให้เป็นกองสิ่งปรักหักพัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 26, 'ส่วนชาวเมืองนั้นมีอํานาจน้อย เขาสะดุ้งกลัวและอับอาย เขาเหมือนหญ้าที่ทุ่งนา และเหมือนหญ้าอ่อน เหมือนหญ้าที่บนยอดหลังคาเรือน เหมือนข้าวเกรียมไปก่อนที่มันจะงอกงามอย่างนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 27, 'แต่เราได้รู้จักการที่เจ้านั่งลงกับการออกไปและเข้ามาของเจ้า และการเกรี้ยวกราดของเจ้าต่อเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 28, 'เพราะเจ้าได้เกรี้ยวกราดต่อเรา และความจองหองของเจ้าได้มาเข้าหูของเรา ฉะนั้นเราจะเอาขอของเราเกี่ยวจมูกเจ้า และบังเหียนของเราใส่ริมฝีปากเจ้า และเราจะหันเจ้ากลับไปตามทางซึ่งเจ้ามานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 29, 'และนี่จะเป็นหมายสําคัญแก่เจ้า คือปีนี้เจ้าจะกินสิ่งที่งอกขึ้นเอง และในปีที่สองสิ่งที่ผลิจากเดิม แล้วในปีที่สาม จงหว่านและเกี่ยว และปลูกสวนองุ่นและกินผลของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 30, 'ส่วนที่รอดและเหลือแห่งวงศ์วานของยูดาห์จะหยั่งรากลงไป และเกิดผลขึ้นบน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 31, 'เพราะว่าส่วนคนที่เหลือจะออกไปจากเยรูซาเล็ม และส่วนที่รอดมาจะออกมาจากภูเขาศิโยน ความกระตือรือร้นของพระเยโฮวาห์จอมโยธาจะกระทําการนี้’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 32, 'เพราะฉะนั้นพระเยโฮวาห์จึงตรัสเกี่ยวกับกษัตริย์แห่งอัสซีเรียดังนี้ว่า ‘ท่านจะไม่เข้าในนครนี้หรือยิงลูกธนูไปที่นั่น หรือถือโล่เข้ามาข้างหน้านคร หรือสร้างเชิงเทินสู้มัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 33, 'ท่านมาทางใด ท่านจะต้องกลับไปทางนั้น ท่านจะไม่เข้ามาในนครนี้ พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 34, 'เพราะเราจะป้องกันนครนี้ไว้เพื่อให้รอด เพื่อเห็นแก่เราเอง และเห็นแก่ดาวิดผู้รับใช้ของเรา’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 35, 'และอยู่มาในคืนนั้นทูตสวรรค์ของพระเยโฮวาห์ได้ออกไป และได้ประหารคนในค่ายแห่งคนอัสซีเรียเสียหนึ่งแสนแปดหมื่นห้าพันคน และเมื่อคนลุกขึ้นในเวลาเช้ามืด ดูเถิด พวกเหล่านั้นเป็นศพทั้งนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 36, 'แล้วเซนนาเคอริบกษัตริย์แห่งอัสซีเรียก็ได้ยกไป และกลับบ้าน และอยู่ในนีนะเวห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 37, 'และอยู่มาเมื่อท่านนมัสการในนิเวศของพระนิสโรกพระของท่าน อัดรัมเมเลคและชาเรเซอร์โอรสของท่านประหารท่านเสียด้วยดาบ และหนีไปยังแผ่นดินอาร์มีเนีย และเอสารฮัดโดนโอรสของท่านขึ้นครอบครองแทนท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 1, 'ในวันเหล่านั้นเฮเซคียาห์ทรงประชวรใกล้จะสิ้นพระชนม์ และผู้พยากรณ์อิสยาห์บุตรชายของอามอสเข้ามาเฝ้าพระองค์ และทูลพระองค์ว่า “พระเยโฮวาห์ตรัสดังนี้ว่า ‘จงจัดการการบ้านการเมืองของเจ้าให้เรียบร้อย เจ้าจะต้องตาย เจ้าจะไม่ฟื้น’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 2, 'แล้วเฮเซคียาห์ทรงหันพระพักตร์เข้าข้างฝา และอธิษฐานต่อพระเยโฮวาห์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 3, '“โอ ข้าแต่พระเยโฮวาห์ ข้าพระองค์ขอวิงวอนต่อพระองค์ ขอทรงระลึกว่า ข้าพระองค์ดําเนินอยู่ต่อเบื้องพระพักตร์พระองค์ด้วยความจริงและด้วยใจที่เพียบพร้อม และได้กระทําสิ่งที่ประเสริฐในสายพระเนตรของพระองค์มาอย่างไร” และเฮเซคียาห์ทรงกันแสงอย่างปวดร้าว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 4, 'และอยู่มาก่อนที่อิสยาห์จะออกไปถึงลาน พระวจนะของพระเยโฮวาห์มาถึงท่านว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 5, '“จงกลับไปบอกเฮเซคียาห์เจ้านายแห่งประชาชนของเราว่า พระเยโฮวาห์พระเจ้าของดาวิดบรรพบุรุษของเจ้า ตรัสดังนี้ว่า ‘เราได้ยินคําอธิษฐานของเจ้าแล้ว เราได้เห็นน้ําตาของเจ้าแล้ว ดูเถิด เราจะรักษาเจ้า ในวันที่สามเจ้าจะขึ้นไปยังพระนิเวศของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 6, 'และเราจะเพิ่มชีวิตของเจ้าอีกสิบห้าปี เราจะช่วยเจ้าและเมืองนี้พ้นจากมือของกษัตริย์แห่งอัสซีเรีย และจะป้องกันเมืองนี้ไว้ เพื่อเห็นแก่เราเอง และเพื่อเห็นแก่ดาวิดผู้รับใช้ของเรา’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 7, 'และอิสยาห์บอกว่า “เอาขนมมะเดื่อมาอันหนึ่ง” เขาก็เอามาวางไว้บนพระยอดนั้น พระองค์จึงทรงหายเป็นปกติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 8, 'และเฮเซคียาห์ตรัสกับอิสยาห์ว่า “อะไรจะเป็นหมายสําคัญว่าพระเยโฮวาห์จะทรงรักษาข้าพเจ้า และว่าข้าพเจ้าจะได้ขึ้นไปยังพระนิเวศของพระเยโฮวาห์ในวันที่สาม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 9, 'และอิสยาห์ทูลว่า “ต่อไปนี้เป็นหมายสําคัญสําหรับพระองค์จากพระเยโฮวาห์ ที่พระเยโฮวาห์จะทรงกระทําตามที่พระองค์ทรงตรัสไว้ คือว่า จะให้เงาคืบหน้าไปสิบขั้น หรือย้อนกลับมาสิบขั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 10, 'เฮเซคียาห์ตรัสตอบว่า “เป็นการง่ายที่เงาจะยาวออกไปอีกสิบขั้น แต่ให้เงาย้อนกลับมาสิบขั้นต่างหาก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 11, 'และอิสยาห์ผู้พยากรณ์ก็ร้องทูลต่อพระเยโฮวาห์ และพระองค์ทรงนําเงาย้อนกลับมาสิบขั้น ซึ่งเงานั้นได้เลยไปในนาฬิกาแดดของอาหัส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 12, 'คราวนั้น เบโรดัคบาลาดันโอรสของบาลาดันกษัตริย์แห่งบาบิโลนทรงส่งราชสารและเครื่องบรรณาการมายังเฮเซคียาห์ เพราะพระองค์ทรงได้ยินว่า เฮเซคียาห์ทรงประชวร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 13, 'และเฮเซคียาห์ได้ทรงต้อนรับเขา และพระองค์ทรงพาเขาชมคลังทรัพย์ทั้งหมดของพระองค์ ให้ชมเงิน ทองคํา และเครื่องเทศ และน้ํามันประเสริฐ และคลังพระแสงของพระองค์ทุกอย่างซึ่งมีในท้องพระคลัง ไม่มีสิ่งใดที่ในพระราชวังหรือในราชอาณาจักรของพระองค์ทั้งสิ้นซึ่งเฮเซคียาห์มิได้สําแดงแก่เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 14, 'แล้วอิสยาห์ผู้พยากรณ์ก็เข้าเฝ้ากษัตริย์เฮเซคียาห์ และทูลพระองค์ว่า “คนเหล่านี้ทูลอะไรบ้าง และเขามาเฝ้าพระองค์แต่ไหน” และเฮเซคียาห์ตรัสว่า “เขาได้มาจากเมืองไกล จากบาบิโลน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 15, 'ท่านทูลว่า “เขาเห็นอะไรในพระราชวังของพระองค์บ้าง” และเฮเซคียาห์ตรัสตอบว่า “เขาเห็นทุกอย่างในวังของเรา ไม่มีสิ่งใดในพระคลังของเราซึ่งเรามิได้สําแดงแก่เขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 16, 'แล้วอิสยาห์ทูลเฮเซคียาห์ว่า “ขอทรงฟังพระวจนะของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 17, 'ดูเถิด วันเวลากําลังย่างเข้ามาเมื่อสรรพสิ่งทั้งสิ้นในวังของเจ้า และสิ่งซึ่งบรรพบุรุษของเจ้าได้สะสมจนถึงทุกวันนี้ จะต้องถูกเอาไปยังบาบิโลน ไม่มีสิ่งใดเหลือเลย พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 18, 'และลูกบางคนซึ่งถือกําเนิดจากเจ้า ผู้ซึ่งเกิดมาแก่เจ้า จะถูกนําเอาไป และเขาจะเป็นขันทีในวังของกษัตริย์แห่งบาบิโลน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 19, 'แล้วเฮเซคียาห์ตรัสกับอิสยาห์ว่า “พระวจนะของพระเยโฮวาห์ซึ่งท่านกล่าวนั้นก็ดีอยู่” เพราะพระองค์ดําริว่า “ก็ดีแล้วมิใช่หรือ ในเมื่อมีความอยู่เย็นเป็นสุขและความจริงในวันเวลาของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 20, 'ส่วนพระราชกิจนอกนั้นของเฮเซคียาห์ และยุทธพลังทั้งสิ้นของพระองค์ และที่พระองค์ทรงสร้างสระและรางระบายน้ํานําน้ําเข้ามาในกรุงอย่างไร มิได้บันทึกไว้ในหนังสือพงศาวดารแห่งกษัตริย์ประเทศยูดาห์หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 21, 'และเฮเซคียาห์ทรงล่วงหลับไปอยู่กับบรรพบุรุษของพระองค์ และมนัสเสห์โอรสของพระองค์ขึ้นครอบครองแทนพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 1, 'มนัสเสห์มีพระชนมายุสิบสองพรรษาเมื่อพระองค์เริ่มครอบครอง และพระองค์ทรงครอบครองในกรุงเยรูซาเล็มห้าสิบห้าปี พระราชมารดาของพระองค์มีพระนามว่าเฮฟซีบาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 2, 'และพระองค์ทรงกระทําสิ่งที่ชั่วร้ายในสายพระเนตรของพระเยโฮวาห์ ตามการกระทําอันน่าสะอิดสะเอียนของประชาชาติ ซึ่งพระเยโฮวาห์ทรงขับไล่ออกไปให้พ้นหน้าประชาชนอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 3, 'เพราะพระองค์ทรงสร้างปูชนียสถานสูง ซึ่งเฮเซคียาห์พระราชบิดาของพระองค์ทรงทําลายเสียนั้นขึ้นใหม่ และพระองค์ทรงสร้างแท่นบูชาสําหรับพระบาอัล และทรงสร้างเสารูปเคารพ ดังที่อาหับกษัตริย์แห่งอิสราเอลทรงกระทํา และทรงนมัสการบริวารทั้งสิ้นของฟ้าสวรรค์ และปรนนิบัติพระเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 4, 'และพระองค์ทรงสร้างแท่นบูชาในพระนิเวศของพระเยโฮวาห์ ซึ่งพระเยโฮวาห์ได้ตรัสว่า “เราจะบรรจุนามของเราไว้ในเยรูซาเล็ม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 5, 'และพระองค์ได้สร้างแท่นบูชาสําหรับบรรดาบริวารแห่งฟ้าสวรรค์ในลานทั้งสองของพระนิเวศแห่งพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 6, 'และพระองค์ได้ทรงถวายโอรสของพระองค์ให้ลุยไฟ ถือฤกษ์ยาม การใช้เวทมนตร์ ทรงเจ้าเข้าผี และพ่อมดหมอผี พระองค์ทรงกระทําความชั่วร้ายเป็นอันมากในสายพระเนตรของพระเยโฮวาห์ ซึ่งเป็นการยั่วยุให้พระองค์ทรงกริ้วโกรธ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 7, 'ส่วนรูปเคารพสลักจากเสารูปเคารพที่พระองค์ทรงสร้างนั้น พระองค์ทรงตั้งไว้ในพระนิเวศ คือพระนิเวศที่พระเยโฮวาห์ตรัสกับดาวิดและซาโลมอนโอรสของพระองค์ว่า “ในนิเวศนี้และในเยรูซาเล็ม ซึ่งเราได้เลือกออกจากตระกูลทั้งสิ้นของอิสราเอล เราจะบรรจุนามของเราไว้เป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 8, 'เราจะไม่เป็นเหตุให้เท้าของอิสราเอลพเนจรออกไปจากแผ่นดินซึ่งเราได้ให้กับบรรพบุรุษของเขาอีก ถ้าเขาเพียงแต่ระมัดระวังที่จะกระทําตามทุกอย่างซึ่งเราได้บัญชาเขา และตามราชบัญญัติทั้งสิ้นซึ่งโมเสสผู้รับใช้ของเราบัญชาเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 9, 'แต่เขามิได้ฟัง และมนัสเสห์ได้ชักจูงเขาให้กระทําชั่วมากยิ่งไปกว่าบรรดาประชาชาติ ซึ่งพระเยโฮวาห์ทรงทําลายเสียต่อหน้าประชาชนอิสราเอลได้เคยกระทําแล้วเสียอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 10, 'และพระเยโฮวาห์ตรัสโดยเหล่าผู้พยากรณ์ผู้รับใช้ของพระองค์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 11, '“เพราะมนัสเสห์กษัตริย์แห่งยูดาห์ได้กระทําการอันน่าสะอิดสะเอียนเหล่านี้ และได้ประพฤติชั่วร้ายยิ่งกว่าสิ่งทั้งปวงที่คนอาโมไรต์ได้กระทํา ผู้ซึ่งอยู่มาก่อนพระองค์ และได้ทรงกระทําให้ยูดาห์ทําบาปด้วยรูปเคารพทั้งหลายของพระองค์อีกด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 12, 'เพราะฉะนั้นพระเยโฮวาห์พระเจ้าแห่งอิสราเอลตรัสดังนี้ว่า ‘ดูเถิด เรากําลังนําเหตุร้ายมาถึงเยรูซาเล็มและยูดาห์ อย่างที่ผู้ใดซึ่งได้ยินแล้วหูทั้งสองของเขาจะซ่าไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 13, 'และเราจะเอาเชือกอย่างที่วัดกรุงสะมาเรียขึงเหนือกรุงเยรูซาเล็ม และใช้ลูกดิ่งอย่างที่วัดราชวงศ์อาหับ และเราจะล้างเยรูซาเล็มอย่างเขาล้างชาม ล้างและพลิกคว่ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 14, 'และเราจะทอดทิ้งมรดกส่วนที่เหลือของเรา และมอบเขาไว้ในมือศัตรูของเขา และเขาทั้งหลายจะเป็นเหยื่อ และเป็นของริบของศัตรูทั้งสิ้นของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 15, 'เพราะเขาได้กระทําสิ่งที่ชั่วร้ายในสายตาของเรา และได้ยั่วยุให้เราโกรธ ตั้งแต่วันที่บรรพบุรุษของเขาออกจากอียิปต์ กระทั่งถึงทุกวันนี้’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 16, 'ยิ่งกว่านั้นมนัสเสห์ได้ทรงกระทําให้โลหิตที่ไร้ความผิดตกเป็นอันมาก จนเต็มเยรูซาเล็มจากปลายข้างหนึ่งถึงปลายอีกข้างหนึ่ง นอกเหนือจากบาปที่พระองค์ทรงกระทําให้ยูดาห์ทําด้วย โดยประพฤติสิ่งที่ชั่วร้ายในสายพระเนตรของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 17, 'ส่วนพระราชกิจนอกนั้นของมนัสเสห์ และบรรดาสิ่งซึ่งพระองค์ทรงกระทํา และบาปซึ่งพระองค์ทรงกระทํา มิได้บันทึกไว้ในหนังสือพงศาวดารแห่งกษัตริย์ประเทศยูดาห์หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 18, 'และมนัสเสห์ทรงล่วงหลับไปอยู่กับบรรพบุรุษของพระองค์ และเขาฝังไว้ในพระอุทยานริมพระราชวังของพระองค์ในสวนของอุสซาห์ และอาโมนโอรสของพระองค์ได้ขึ้นครอบครองแทนพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 19, 'อาโมนมีพระชนมายุยี่สิบสองพรรษาเมื่อพระองค์เริ่มครอบครอง และพระองค์ทรงครอบครองในกรุงเยรูซาเล็มสองปี พระราชมารดาของพระองค์มีพระนามว่าเมชุลเลเมทบุตรสาวของฮารูสชาวโยทบาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 20, 'และพระองค์ทรงกระทําสิ่งที่ชั่วร้ายในสายพระเนตรของพระเยโฮวาห์ อย่างมนัสเสห์บิดาของพระองค์ได้ทรงกระทํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 21, 'พระองค์ทรงดําเนินในทางทั้งสิ้นซึ่งบิดาของพระองค์ทรงดําเนิน และปรนนิบัติรูปเคารพซึ่งบิดาของพระองค์ทรงปรนนิบัติ และนมัสการรูปเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 22, 'พระองค์ทรงทอดทิ้งพระเยโฮวาห์พระเจ้าแห่งบรรพบุรุษของพระองค์ และมิได้ทรงดําเนินในมรรคาของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 23, 'และข้าราชการของอาโมนได้ร่วมกันคิดกบฏต่อพระองค์ และประหารกษัตริย์ในพระราชวังของพระองค์เสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 24, 'แต่ประชาชนแห่งแผ่นดินได้ประหารทุกคนที่ร่วมกันคิดกบฏต่อกษัตริย์อาโมน และประชาชนแห่งแผ่นดินได้ตั้งโยสิยาห์โอรสของพระองค์ให้เป็นกษัตริย์แทนพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 25, 'ส่วนพระราชกิจนอกนั้นของอาโมนซึ่งพระองค์ทรงกระทํา มิได้บันทึกไว้ในหนังสือพงศาวดารแห่งกษัตริย์ประเทศยูดาห์หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 26, 'และเขาฝังไว้ในอุโมงค์ของพระองค์ในสวนของอุสซาห์ และโยสิยาห์โอรสของพระองค์ได้ครอบครองแทนพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 1, 'โยสิยาห์มีพระชนมายุแปดพรรษาเมื่อเริ่มครอบครอง และพระองค์ทรงครอบครองในกรุงเยรูซาเล็มสามสิบเอ็ดปี พระราชมารดาของพระองค์มีพระนามว่า เยดีดาห์บุตรสาวของอาดายาห์ชาวโบสคาท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 2, 'และพระองค์ได้ทรงกระทําสิ่งที่ถูกต้องในสายพระเนตรของพระเยโฮวาห์ และทรงดําเนินในมรรคาทั้งสิ้นของดาวิดบรรพบุรุษของพระองค์ และมิได้ทรงหันไปทางขวามือหรือซ้ายมือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 3, 'และอยู่มาในปีที่สิบแปดแห่งรัชกาลกษัตริย์โยสิยาห์ กษัตริย์ทรงใช้ชาฟานบุตรชายอาซาลิยาห์ บุตรชายเมชุลลามราชเลขา ไปยังพระนิเวศของพระเยโฮวาห์ รับสั่งว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 4, '“จงขึ้นไปหาฮิลคียาห์มหาปุโรหิต เพื่อให้ท่านรวมเงินซึ่งเขานําเข้ามาในพระนิเวศของพระเยโฮวาห์ ซึ่งผู้รักษาธรณีประตูได้เก็บจากประชาชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 5, 'และให้มอบไว้ในมือของคนงานผู้ดูแลพระนิเวศของพระเยโฮวาห์ และให้เขาจ่ายแก่คนงานผู้ที่อยู่ ณ พระนิเวศของพระเยโฮวาห์ ที่ทําการซ่อมแซมพระนิเวศอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 6, 'คือให้แก่ช่างไม้ และแก่ช่างก่อสร้าง และแก่ช่างปูน ทั้งสําหรับซื้อไม้และหินสกัดเพื่อซ่อมแซมพระนิเวศ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 7, 'แต่ไม่ได้ขอบัญชีจากเขาเรื่องเงินที่จ่ายใส่มือของเขา เพราะเขากระทําด้วยความสัตย์ซื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 8, 'และฮิลคียาห์มหาปุโรหิตพูดกับชาฟานราชเลขาว่า “ข้าพเจ้าได้พบหนังสือพระราชบัญญัติในพระนิเวศของพระเยโฮวาห์” และฮิลคียาห์ได้มอบหนังสือนั้นให้ชาฟานและท่านก็อ่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 9, 'และชาฟานราชเลขาได้เข้าเฝ้ากษัตริย์และทูลรายงานต่อกษัตริย์อีกว่า “ผู้รับใช้ของพระองค์ได้เทเงินที่พบในพระนิเวศออก และได้มอบไว้ในมือของคนงานผู้ดูแลพระนิเวศของพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 10, 'แล้วชาฟานราชเลขาได้ทูลกษัตริย์ว่า “ฮิลคียาห์ปุโรหิตได้มอบหนังสือแก่ข้าพระองค์ม้วนหนึ่ง” และชาฟานก็อ่านถวายกษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 11, 'และอยู่มาเมื่อกษัตริย์ได้ฟังถ้อยคําของหนังสือแห่งพระราชบัญญัติ พระองค์ทรงฉีกฉลองพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 12, 'และกษัตริย์ทรงบัญชาฮิลคียาห์ปุโรหิต และอาหิคัมบุตรชายชาฟาน และอัคโบร์บุตรชายมีคายาห์ และชาฟานราชเลขา และอาสายาห์ผู้รับใช้ของกษัตริย์ รับสั่งว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 13, '“จงไปทูลถามพระเยโฮวาห์ให้เรา ให้ประชาชนและให้ยูดาห์ทั้งหมดเกี่ยวกับถ้อยคําในหนังสือนี้ที่ได้พบ เพราะว่า พระพิโรธของพระเยโฮวาห์ซึ่งพลุ่งขึ้นต่อเราทั้งหลายนั้นใหญ่หลวงนัก เพราะว่าบรรพบุรุษของเรามิได้เชื่อฟังถ้อยคําของหนังสือนี้ กระทําทุกสิ่งซึ่งเขียนไว้เกี่ยวกับเราทั้งหลาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 14, 'ฮิลคียาห์ปุโรหิต และอาหิคัม และอัคโบร์ และชาฟาน และอาสายาห์ ได้ไปหาฮุลดาห์หญิงผู้พยากรณ์ภรรยาของชัลลูม บุตรชายของทิกวาห์บุตรชายฮารฮัสผู้ดูแลตู้เสื้อ (เวลานั้นนางอยู่ในเยรูซาเล็มแขวงสอง) และเขาทั้งหลายได้สนทนากับนาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 15, 'และนางตอบพวกเขาว่า “พระเยโฮวาห์พระเจ้าแห่งอิสราเอลตรัสดังนี้ว่า ‘จงบอกชายคนที่ใช้พวกเจ้ามาหาเรานั้นว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 16, '“พระเยโฮวาห์ตรัสดังนี้ว่า ดูเถิด เราจะนําเหตุร้ายมาเหนือสถานที่นี้ และเหนือชาวเมืองนี้ ตามบรรดาถ้อยคําในหนังสือซึ่งกษัตริย์แห่งยูดาห์ได้อ่านนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 17, 'เพราะเขาทั้งหลายได้ทอดทิ้งเรา และได้เผาเครื่องหอมถวายพระอื่น เพื่อเขาจะได้กระทําให้เราโกรธด้วยผลงานทั้งสิ้นแห่งมือของเขา เพราะฉะนั้นความพิโรธของเราจึงจะพลุ่งขึ้นต่อสถานที่นี้ และจะดับเสียไม่ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 18, 'แต่ฝ่ายกษัตริย์แห่งยูดาห์ผู้ได้ส่งเจ้ามาถามพระเยโฮวาห์นั้น เจ้าจงไปบอกเขาว่า “พระเยโฮวาห์พระเจ้าแห่งอิสราเอลตรัสดังนี้ว่า เกี่ยวกับเรื่องถ้อยคําที่เจ้าได้ยิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 19, 'เพราะจิตใจของเจ้าอ่อนโยน และเจ้าได้ถ่อมตัวลงต่อพระพักตร์พระเยโฮวาห์ เมื่อเจ้าได้ยินเรากล่าวต่อต้านสถานที่นี้และต่อต้านชาวเมืองนี้ว่าเขาจะต้องกลายเป็นที่รกร้างและที่ถูกสาป และเจ้าได้ฉีกเสื้อและร้องไห้ต่อหน้าเรา เราก็ได้ยินเจ้าแล้วด้วย พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 20, 'เพราะฉะนั้น ดูเถิด เราจะรวบเจ้าไปไว้กับบรรพบุรุษของเจ้า และเจ้าจะถูกรวบไปยังอุโมงค์ของเจ้าอย่างสันติ และตาของเจ้าจะไม่เห็นเหตุร้ายทั้งสิ้นซึ่งเราจะนํามาเหนือที่นี้”’” และเขาทั้งหลายก็ได้นําถ้อยคําเหล่านั้นมาทูลกษัตริย์อีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 1, 'แล้วกษัตริย์ทรงใช้ และบรรดาผู้ใหญ่ของยูดาห์และเยรูซาเล็มได้มาชุมนุมกับพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 2, 'และกษัตริย์เสด็จขึ้นไปยังพระนิเวศของพระเยโฮวาห์ และคนยูดาห์ทั้งสิ้น และบรรดาชาวกรุงเยรูซาเล็มพร้อมกับพระองค์ และปุโรหิต และผู้พยากรณ์ และประชาชนทั้งปวงทั้งเล็กและใหญ่ และพระองค์ทรงอ่านถ้อยคําทั้งหมดในหนังสือพันธสัญญา ซึ่งได้พบในพระนิเวศของพระเยโฮวาห์ให้เขาฟัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 3, 'และกษัตริย์ทรงประทับยืนข้างเสา และทรงกระทําพันธสัญญาต่อพระพักตร์พระเยโฮวาห์ว่า จะดําเนินตามพระเยโฮวาห์ และรักษาพระบัญญัติ พระโอวาทและกฎเกณฑ์ของพระองค์ด้วยสุดพระจิตสุดพระทัยของพระองค์ จะปฏิบัติตามถ้อยคําของพันธสัญญานี้ ซึ่งเขียนไว้ในหนังสือนี้ และประชาชนทั้งปวงก็เข้าส่วนในพันธสัญญานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 4, 'และกษัตริย์ทรงบัญชาฮิลคียาห์มหาปุโรหิต และพวกปุโรหิตรอง และผู้รักษาธรณีประตู ให้นําเครื่องใช้ทั้งสิ้นที่ทําขึ้นสําหรับพระบาอัล สําหรับเสารูปเคารพ และสําหรับบรรดาบริวารของฟ้าสวรรค์ออกมาจากพระวิหารของพระเยโฮวาห์ พระองค์ทรงเผาเสียที่ภายนอกกรุงเยรูซาเล็มในทุ่งนาแห่งขิดโรน และขนมูลเถ้าของมันไปยังเบธเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 5, 'และพระองค์ทรงกําจัดปุโรหิตของปฏิมากร ผู้ซึ่งบรรดากษัตริย์แห่งยูดาห์ได้สถาปนา ให้เผาเครื่องหอมในปูชนียสถานสูงที่หัวเมืองแห่งยูดาห์ และรอบๆกรุงเยรูซาเล็ม ทั้งคนเหล่านั้นที่เผาเครื่องหอมถวายพระบาอัล ถวายดวงอาทิตย์ ดวงจันทร์ และหมู่ดาวประจําราศี และบริวารทั้งสิ้นของฟ้าสวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 6, 'และพระองค์ทรงนําเสารูปเคารพออกมาจากพระนิเวศของพระเยโฮวาห์ ภายนอกเยรูซาเล็มถึงลําธารขิดโรน และเผาเสียที่ลําธารขิดโรน และทรงทุบให้เป็นผงคลี และเหวี่ยงผงคลีนั้นลงบนหลุมศพของคนสามัญ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 7, 'และพระองค์ทรงทําลายเรือนกะเทย ซึ่งอยู่ข้างพระนิเวศของพระเยโฮวาห์เสีย เป็นที่ที่ผู้หญิงทอม่านสําหรับเสารูปเคารพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 8, 'และพระองค์ทรงให้ปุโรหิตทั้งหมดออกจากหัวเมืองยูดาห์ และทรงกระทําให้ปูชนียสถานสูงเสียความศักดิ์สิทธิ์ คือที่ที่ปุโรหิตได้เผาเครื่องหอม ตั้งแต่เมืองเกบาถึงเบเออร์เชบา และพระองค์ทรงทําลายปูชนียสถานสูงของประตูเมือง ซึ่งอยู่ตรงทางเข้าประตูโยชูวาผู้ว่าราชการเมือง ซึ่งอยู่ทางซ้ายมือที่ประตูเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 9, 'ถึงอย่างไรก็ดีปุโรหิตแห่งปูชนียสถานสูงมิได้ขึ้นไปยังแท่นบูชาแห่งพระเยโฮวาห์ในกรุงเยรูซาเล็ม แต่เขาทั้งหลายกินขนมปังไร้เชื้อท่ามกลางพวกพี่น้องของเขาเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 10, 'และทรงกระทําให้โทเฟทเสียความศักดิ์สิทธิ์ คือที่ที่หุบเขาบุตรแห่งฮินโนม เพื่อจะไม่มีผู้ใดถวายบุตรชายหญิงของตนให้ลุยไฟต่อพระโมเลค');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 11, 'และพระองค์ทรงกําจัดม้าซึ่งบรรดากษัตริย์แห่งยูดาห์ได้ถวายแก่ดวงอาทิตย์ ที่ตรงทางเข้าพระนิเวศของพระเยโฮวาห์ ข้างห้องนาธันเมเลคข้าราชสํานัก ซึ่งอยู่ในบริเวณ และพระองค์ทรงเผารถรบของดวงอาทิตย์เสียด้วยไฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 12, 'และแท่นบนหลังคาห้องชั้นบนของอาหัส ซึ่งบรรดากษัตริย์ของยูดาห์ได้สร้างไว้ และแท่นบูชาซึ่งมนัสเสห์ได้สร้างไว้ในลานทั้งสองของพระนิเวศแห่งพระเยโฮวาห์ กษัตริย์ทรงดึงลงมาให้หักเสียที่นั่น และทรงเหวี่ยงผงคลีของมันลงไปในลําธารขิดโรน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 13, 'และกษัตริย์ทรงกระทําให้ปูชนียสถานสูงซึ่งอยู่หน้ากรุงเยรูซาเล็มเสียความศักดิ์สิทธิ์ ซึ่งอยู่ทางขวามือของภูเขาพินาศ ซึ่งซาโลมอนกษัตริย์แห่งอิสราเอลได้สร้างสําหรับพระอัชโทเรทสิ่งน่าสะอิดสะเอียนของคนไซดอน และสําหรับพระเคโมชสิ่งน่าสะอิดสะเอียนของคนโมอับ และสําหรับพระมิลโคมสิ่งน่าสะอิดสะเอียนของชนอัมโมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 14, 'และพระองค์ทรงทุบเสาศักดิ์สิทธิ์เป็นชิ้นๆ และตัดเหล่าเสารูปเคารพลงเสีย และเอากระดูกมนุษย์ถมที่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 15, 'ยิ่งกว่านั้นอีกแท่นบูชาที่เบธเอล ปูชนียสถานสูงซึ่งเยโรโบอัมบุตรชายเนบัทได้ตั้งไว้ ผู้ซึ่งกระทําให้อิสราเอลทําบาปด้วย พระองค์ทรงรื้อแท่นบูชากับปูชนียสถานสูงนั้นลงและทรงเผาปูชนียสถานสูงนั้น บดให้เป็นผงคลีและพระองค์ทรงเผาเสารูปเคารพเสียด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 16, 'และเมื่อโยสิยาห์ทรงหันพระพักตร์ พระองค์ทอดพระเนตรอุโมงค์ฝังศพอยู่บนภูเขา และพระองค์ทรงใช้ให้ไปเอากระดูกออกมาเสียจากอุโมงค์ และเผาเสียบนแท่นบูชา และทรงกระทําให้เสียความศักดิ์สิทธิ์ ตามพระวจนะของพระเยโฮวาห์ซึ่งคนแห่งพระเจ้าได้ป่าวร้องไว้ ผู้ซึ่งป่าวร้องถึงสิ่งเหล่านี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 17, 'แล้วพระองค์ตรัสว่า “อนุสาวรีย์ที่เรามองเห็นข้างโน้นคืออะไร” คนเมืองนั้นก็ทูลพระองค์ว่า “เป็นอุโมงค์ฝังศพของคนแห่งพระเจ้าผู้มาจากยูดาห์ และได้ป่าวร้องถึงสิ่งเหล่านี้ ซึ่งพระองค์ได้ทรงกระทําต่อแท่นบูชาที่เบธเอล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 18, 'และพระองค์ตรัสว่า “ให้เขาอยู่ที่นั่นแหละ อย่าให้ผู้ใดย้ายกระดูกของเขา” เขาทั้งหลายจึงทิ้งกระดูกของเขาไว้อย่างนั้นพร้อมกับกระดูกของผู้พยากรณ์ผู้ออกมาจากสะมาเรีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 19, 'โยสิยาห์ทรงกําจัดนิเวศทั้งสิ้นของปูชนียสถานสูงที่อยู่ในหัวเมืองสะมาเรีย ซึ่งบรรดากษัตริย์แห่งอิสราเอลได้ทรงสร้างไว้กระทําให้พระเยโฮวาห์ทรงกริ้ว พระองค์ทรงกระทําต่อที่เหล่านั้นตามทุกอย่างที่พระองค์ทรงกระทําที่เบธเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 20, 'และพระองค์ทรงประหารปุโรหิตทั้งปวงแห่งปูชนียสถานสูงซึ่งอยู่ที่นั่นเสียบนแท่นบูชา และเผากระดูกคนเสียบนนั้น แล้วพระองค์ก็เสด็จกลับกรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 21, 'และกษัตริย์ทรงบัญชาประชาชนทั้งปวงว่า “จงถือเทศกาลปัสกาถวายแด่พระเยโฮวาห์พระเจ้าของเจ้า ดังที่เขียนไว้ในหนังสือพันธสัญญานี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 22, 'เพราะว่าเทศกาลปัสกาอย่างนี้มิได้ถือกันมาตั้งแต่สมัยผู้วินิจฉัยผู้ที่ครอบครองอิสราเอล หรือระหว่างสมัยบรรดากษัตริย์แห่งอิสราเอลหรือกษัตริย์แห่งยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 23, 'แต่ในปีที่สิบแปดแห่งรัชกาลกษัตริย์โยสิยาห์ได้ถือเทศกาลปัสกานี้ถวายแด่พระเยโฮวาห์ในกรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 24, 'ยิ่งกว่านั้นอีกโยสิยาห์ได้กําจัดคนทรง และแม่มด และรูปปั้น และรูปเคารพ และบรรดาสิ่งน่าสะอิดสะเอียนซึ่งเห็นกันอยู่ในแผ่นดินยูดาห์และในกรุงเยรูซาเล็ม เพื่อพระองค์จะทรงสถาปนาถ้อยคําแห่งพระราชบัญญัติซึ่งเขียนอยู่ในหนังสือที่ฮิลคียาห์ปุโรหิตได้พบในพระนิเวศของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 25, 'ก่อนพระองค์หามีกษัตริย์องค์ใดเหมือนพระองค์ไม่ ผู้ซึ่งหันหาพระเยโฮวาห์ด้วยสุดพระจิตสุดพระทัย และด้วยสิ้นสุดพระกําลัง ตามพระราชบัญญัติทั้งสิ้นของโมเสส หรือผู้ที่เกิดมาทีหลังพระองค์ ก็ไม่มีใครเหมือนพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 26, 'ถึงกระนั้นพระเยโฮวาห์มิได้ทรงหันจากพระพิโรธอันแรงกล้าและยิ่งใหญ่ของพระองค์ พระพิโรธของพระองค์ได้พลุ่งขึ้นต่อยูดาห์ ด้วยการกระทําทั้งสิ้นของมนัสเสห์อันเป็นเหตุให้พระองค์ทรงพระพิโรธ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 27, 'และพระเยโฮวาห์ตรัสว่า “เราจะให้ยูดาห์ออกเสียจากสายตาของเราด้วย ดังที่เราได้กระทําให้อิสราเอลออกเสีย และเราจะเหวี่ยงเมืองนี้ซึ่งเราได้เลือกออกไปเสีย คือเยรูซาเล็ม กับนิเวศซึ่งเราได้บอกว่า ‘นามของเราจะอยู่ที่นั่น’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 28, 'ส่วนพระราชกิจนอกนั้นของโยสิยาห์ และบรรดาสิ่งซึ่งพระองค์ทรงกระทํา มิได้บันทึกไว้ในหนังสือพงศาวดารแห่งกษัตริย์ประเทศยูดาห์หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 29, 'ในสมัยของพระองค์ ฟาโรห์เนโคกษัตริย์ของอียิปต์เสด็จขึ้นไปยังกษัตริย์แห่งอัสซีเรียถึงแม่น้ํายูเฟรติส กษัตริย์โยสิยาห์เสด็จไปปะทะพระองค์ และเมื่อฟาโรห์เนโคทรงเห็นพระองค์ก็ประหารพระองค์เสียที่เมืองเมกิดโด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 30, 'ข้าราชการของพระองค์ก็นําพระศพใส่รถรบไปจากเมืองเมกิดโด และนํามายังกรุงเยรูซาเล็ม และฝังไว้ในอุโมงค์ของพระองค์ และประชาชนแห่งแผ่นดินนั้นก็รับเยโฮอาหาสโอรสโยสิยาห์เจิมท่านไว้ และตั้งท่านให้เป็นกษัตริย์แทนราชบิดาของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 31, 'เยโฮอาหาสมีพระชนมายุยี่สิบสามพรรษาเมื่อพระองค์ทรงเริ่มครอบครอง และพระองค์ทรงครอบครองในกรุงเยรูซาเล็มสามเดือน พระราชมารดาของพระองค์มีพระนามว่า ฮามุทาลบุตรสาวของเยเรมีย์ชาวลิบนาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 32, 'และพระองค์ทรงกระทําสิ่งที่ชั่วร้ายในสายพระเนตรของพระเยโฮวาห์ ตามทุกสิ่งซึ่งบรรพบุรุษของพระองค์ได้กระทํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 33, 'และฟาโรห์เนโคก็จับพระองค์ขังไว้ที่ริบลาห์ในแผ่นดินฮามัท เพื่อมิให้พระองค์ครอบครองในเยรูซาเล็ม และกําหนดบรรณาการจากแผ่นดินนั้นเป็นเงินหนึ่งร้อยตะลันต์ และทองคําหนึ่งตะลันต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 34, 'และฟาโรห์เนโคทรงตั้งเอลียาคิมโอรสโยสิยาห์เป็นกษัตริย์แทนโยสิยาห์บิดาของท่าน และเปลี่ยนชื่อของท่านเป็นเยโฮยาคิม แต่ได้พาเยโฮอาหาสไปเสีย และท่านมาถึงอียิปต์และสิ้นชีวิตเสียที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 35, 'และเยโฮยาคิมก็มอบเงินและทองคําแก่ฟาโรห์ แต่พระองค์ทรงเก็บภาษีจากชาวแผ่นดินเพื่อมอบเงินตามบัญชาของฟาโรห์ พระองค์ทรงเร่งรัดเอาเงินและทองคําของประชาชนแห่งแผ่นดินนั้น จากทุกคนตามการประเมิน เพื่อมอบแก่ฟาโรห์เนโค');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 36, 'เยโฮยาคิมมีพระชนมายุยี่สิบห้าพรรษาเมื่อพระองค์ทรงเริ่มครอบครอง และพระองค์ทรงครอบครองในกรุงเยรูซาเล็มสิบเอ็ดปี พระราชมารดาของพระองค์มีพระนามว่า เศบูดาห์บุตรสาวเปดายาห์ชาวรูมาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 37, 'และพระองค์ทรงกระทําสิ่งที่ชั่วร้ายในสายพระเนตรของพระเยโฮวาห์ ตามทุกสิ่งซึ่งบรรพบุรุษของพระองค์ได้ทรงกระทํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 1, 'ในรัชกาลของพระองค์ เนบูคัดเนสซาร์กษัตริย์แห่งบาบิโลนยกขึ้นมา และเยโฮยาคิมเป็นคนใช้ของพระองค์สามปี แล้วท่านก็กลับกบฏต่อพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 2, 'และพระเยโฮวาห์ทรงใช้พวกคนเคลเดีย และพวกคนซีเรีย และพวกคนโมอับ และพวกคนอัมโมนมาต่อสู้กับท่าน และทรงใช้เขาทั้งหลายไปต่อสู้ยูดาห์เพื่อจะทําลายเสีย ตามพระวจนะของพระเยโฮวาห์ซึ่งพระองค์ตรัสโดยบรรดาผู้พยากรณ์ผู้รับใช้ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 3, 'แท้จริงเหตุการณ์นี้เกิดขึ้นกับยูดาห์ตามพระบัญชาของพระเยโฮวาห์เพื่อจะให้เขาออกไปเสียจากสายพระเนตรของพระองค์ เพราะบรรดาบาปของมนัสเสห์ ตามทุกอย่างซึ่งพระองค์ได้ทรงกระทํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 4, 'และเพราะโลหิตที่ไร้ความผิดซึ่งท่านได้ทําให้หลั่งนั้นด้วย เพราะท่านได้กระทําให้โลหิตไร้ความผิดตกเต็มเยรูซาเล็ม และพระเยโฮวาห์ไม่ทรงอภัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 5, 'ส่วนพระราชกิจนอกนั้นของเยโฮยาคิม และบรรดาสิ่งซึ่งพระองค์ทรงกระทํา มิได้บันทึกไว้ในหนังสือพงศาวดารแห่งกษัตริย์ประเทศยูดาห์หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 6, 'เยโฮยาคิมจึงทรงล่วงหลับไปอยู่กับบรรพบุรุษของพระองค์ และเยโฮยาคีนโอรสของพระองค์ขึ้นครอบครองแทนพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 7, 'และกษัตริย์แห่งอียิปต์มิได้ทรงยกออกมาจากแผ่นดินของพระองค์อีก เพราะกษัตริย์แห่งบาบิโลนได้ยึดแดนทั้งสิ้นซึ่งเป็นของกษัตริย์อียิปต์ตั้งแต่แม่น้ําอียิปต์ถึงแม่น้ํายูเฟรติส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 8, 'เยโฮยาคีนมีพระชนมายุสิบแปดพรรษาเมื่อพระองค์ทรงเริ่มครอบครอง และพระองค์ทรงครอบครองในกรุงเยรูซาเล็มสามเดือน พระราชมารดาของพระองค์มีพระนามว่า เนหุชทาบุตรสาวของเอลนาธันชาวเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 9, 'และพระองค์ทรงกระทําสิ่งที่ชั่วร้ายในสายพระเนตรของพระเยโฮวาห์ ตามทุกสิ่งซึ่งราชบิดาของพระองค์ทรงกระทํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 10, 'คราวนั้นข้าราชการของเนบูคัดเนสซาร์กษัตริย์แห่งบาบิโลนยกขึ้นมายังกรุงเยรูซาเล็มล้อมกรุงไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 11, 'และเนบูคัดเนสซาร์กษัตริย์แห่งบาบิโลนเสด็จมาที่เมืองนั้น ขณะเมื่อข้าราชการของพระองค์ยังล้อมเมืองอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 12, 'และเยโฮยาคีนกษัตริย์แห่งยูดาห์ทรงมอบพระองค์แด่กษัตริย์แห่งบาบิโลน พระองค์เอง และพระราชมารดาของพระองค์ และข้าราชการของพระองค์ และเจ้านายของพระองค์ และข้าราชสํานักของพระองค์ กษัตริย์แห่งบาบิโลนจับพระองค์เป็นนักโทษในปีที่แปดแห่งรัชกาลของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 13, 'ได้ขนเอาบรรดาทรัพย์สินในพระนิเวศของพระเยโฮวาห์ และทรัพย์สินในสํานักพระราชวัง และตัดบรรดาเครื่องใช้ทองคําเป็นชิ้นๆ ซึ่งซาโลมอนกษัตริย์แห่งอิสราเอลทรงสร้างไว้ในพระวิหารของพระเยโฮวาห์ ดังที่พระเยโฮวาห์ตรัสไว้ก่อนแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 14, 'พระองค์ทรงกวาดชาวเยรูซาเล็มไปหมด ทั้งเจ้านายทั้งปวง และทแกล้วทหารทั้งหมด เป็นเชลยหนึ่งหมื่นคน มีช่างฝีมือและช่างเหล็กทั้งหมด ไม่มีผู้ใดเหลือนอกจากประชาชนที่จนที่สุดแห่งแผ่นดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 15, 'และพระองค์นําเยโฮยาคีนไปยังบาบิโลน ทั้งพระราชมารดา และบรรดาพระมเหสี ข้าราชสํานักของพระองค์ และบุคคลชั้นหัวหน้าของแผ่นดิน พระองค์จับเป็นเชลยจากกรุงเยรูซาเล็มถึงบาบิโลน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 16, 'และกษัตริย์แห่งบาบิโลนทรงนําเชลยมายังบาบิโลน คือทแกล้วทหารทั้งหมดเจ็ดพันคน และช่างฝีมือและช่างเหล็กหนึ่งพัน ทุกคนแข็งแรง และเหมาะสําหรับการรบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 17, 'และกษัตริย์แห่งบาบิโลนตั้งมัทธานิยาห์ปิตุลาของเยโฮยาคีนเป็นกษัตริย์แทนพระองค์ และเปลี่ยนพระนามว่าเศเดคียาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 18, 'เศเดคียาห์มีพระชนมายุยี่สิบเอ็ดพรรษาเมื่อพระองค์ทรงเริ่มครอบครอง และพระองค์ทรงครอบครองในกรุงเยรูซาเล็มสิบเอ็ดปี พระราชมารดาของพระองค์มีพระนามว่า ฮามุทาลบุตรสาวของเยเรมีย์ชาวลิบนาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 19, 'และพระองค์ทรงกระทําสิ่งที่ชั่วร้ายในสายพระเนตรของพระเยโฮวาห์ ตามทุกสิ่งซึ่งเยโฮยาคิมทรงกระทํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 20, 'เพราะว่าโดยพระพิโรธของพระเยโฮวาห์นั้นเหตุการณ์มาถึงขีด ที่พระองค์ทรงเหวี่ยงเยรูซาเล็มและยูดาห์ไปให้พ้นพระพักตร์พระองค์ และเศเดคียาห์ได้กบฏต่อกษัตริย์แห่งบาบิโลน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 1, 'และอยู่มาเมื่อวันที่สิบเดือนที่สิบปีที่เก้าแห่งรัชกาลของพระองค์ เนบูคัดเนสซาร์กษัตริย์แห่งบาบิโลนได้ยกมาพร้อมกับกองทัพทั้งสิ้นของพระองค์เข้าสู้รบกรุงเยรูซาเล็ม และล้อมกรุงนั้นไว้ และเขาทั้งหลายได้สร้างเครื่องล้อมไว้รอบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 2, 'กรุงนั้นจึงถูกล้อมอยู่ถึงปีที่สิบเอ็ดแห่งรัชกาลกษัตริย์เศเดคียาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 3, 'เมื่อวันที่เก้าของเดือนที่สี่ การกันดารอาหารในกรุงนั้นก็ร้ายกาจนัก ไม่มีอาหารให้แก่ประชาชนแห่งแผ่นดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 4, 'แล้วกรุงนั้นก็แตก ทหารทั้งสิ้นหนีออกไปในกลางคืนตามทางประตูเมืองระหว่างกําแพงทั้งสองซึ่งอยู่ริมราชอุทยาน (ทั้งๆที่คนเคลเดียอยู่รอบเมือง) และกษัตริย์ก็เสด็จตามทางไปที่ราบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 5, 'แต่กองทัพของคนเคลเดียได้ไล่ตามกษัตริย์ และมาทันพระองค์ในที่ราบเมืองเยรีโค และกองทัพทั้งสิ้นของพระองค์ก็กระจัดกระจายไปจากพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 6, 'แล้วเขาจึงจับกษัตริย์นําขึ้นมายังกษัตริย์แห่งบาบิโลนที่ริบลาห์ และพวกเขาได้พิพากษาพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 7, 'เขาได้ประหารชีวิตบรรดาโอรสของเศเดคียาห์ต่อพระพักตร์ของพระองค์ แล้วทําพระเนตรเศเดคียาห์ให้บอดไป ได้ผูกมัดพระองค์ไว้ด้วยโซ่ตรวนทองเหลือง และพาพระองค์ไปยังบาบิโลน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 8, 'เมื่อวันที่เจ็ดเดือนที่ห้าซึ่งเป็นปีที่สิบเก้าของรัชกาลกษัตริย์เนบูคัดเนสซาร์กษัตริย์แห่งบาบิโลน เนบูซาระดานผู้บัญชาการทหารรักษาพระองค์ ข้าราชการคนหนึ่งของกษัตริย์แห่งบาบิโลน ได้มายังเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 9, 'ท่านได้เผาพระนิเวศของพระเยโฮวาห์เสีย และเผาพระราชวัง และเผาบ้านเรือนทั้งหมดของเยรูซาเล็ม ท่านเผาบ้านใหญ่ทุกหลังลงหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 10, 'และทหารคนเคลเดียทั้งหมดผู้อยู่กับผู้บัญชาการทหารรักษาพระองค์ได้ทลายกําแพงรอบเยรูซาเล็มลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 11, 'และประชาชนที่เหลืออยู่ซึ่งอยู่ในเมือง และคนหลบหนีซึ่งหลบหนีไปยังกษัตริย์แห่งบาบิโลน พร้อมกับมวลชนที่เหลืออยู่นั้น เนบูซาระดานผู้บัญชาการทหารรักษาพระองค์ได้กวาดไปเป็นเชลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 12, 'แต่ผู้บัญชาการทหารรักษาพระองค์ได้ละคนจนแห่งแผ่นดินไว้ให้เป็นคนทําสวนองุ่นและเป็นคนทําไร่ไถนา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 13, 'และเสาทองเหลืองซึ่งอยู่ในพระนิเวศของพระเยโฮวาห์ และเชิงกับขันสาครทองเหลืองซึ่งอยู่ในพระนิเวศของพระเยโฮวาห์นั้น คนเคลเดียได้ทุบเป็นชิ้นๆ และขนเอาทองเหลืองไปยังบาบิโลน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 14, 'เขาขนหม้อ พลั่ว และตะไกรตัดไส้ตะเกียง และช้อน และบรรดาเครื่องใช้ทองเหลืองซึ่งใช้ในงานปรนนิบัติเอาไปเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 15, 'ทั้งถาดรองไฟด้วย กับชาม สิ่งใดที่ทําด้วยทองคํา ผู้บัญชาการทหารรักษาพระองค์ก็ขนเอาไปเป็นทองคํา และสิ่งใดที่ทําด้วยเงินก็ขนเอาไปเป็นเงิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 16, 'ส่วนเสาสองต้น ขันสาครหนึ่งลูก และเชิงซึ่งซาโลมอนทรงสร้างสําหรับพระนิเวศของพระเยโฮวาห์นั้น ทองเหลืองของภาชนะทั้งหมดนี้ก็เหลือที่จะชั่งได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 17, 'เสาต้นหนึ่งสูงสิบแปดศอก และบัวคว่ําทองเหลืองมีบนเสา บัวคว่ํานั้นสูงสามศอก มีตาข่ายกับลูกทับทิมล้วนทองเหลืองอยู่บนบัวคว่ําโดยรอบ และเสาต้นที่สองก็เหมือนกันพร้อมตาข่าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 18, 'และผู้บัญชาการทหารรักษาพระองค์ก็จับเสไรอาห์ปุโรหิตผู้ใหญ่และเศฟันยาห์ปุโรหิตที่สอง กับผู้รักษาธรณีประตูสามคนไปด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 19, 'และจากเมืองนั้นท่านได้จับข้าราชสํานักซึ่งเป็นผู้บัญชาการกองทัพ กับที่ปรึกษาของกษัตริย์อีกห้าคนที่พบในเมืองนั้น และเลขาธิการคือผู้บัญชาการกองทัพผู้เกณฑ์ประชาชนแห่งแผ่นดิน และอีกหกสิบคนจากประชาชนแห่งแผ่นดินซึ่งพบในเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 20, 'และเนบูซาระดานผู้บัญชาการทหารรักษาพระองค์ได้จับคนเหล่านี้ไป พามาถึงกษัตริย์แห่งบาบิโลนที่ริบลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 21, 'และกษัตริย์แห่งบาบิโลนได้ทรงฟันเขา และประหารชีวิตเขาทั้งหลายเสียที่ริบลาห์ในแผ่นดินฮามัท ยูดาห์จึงถูกกวาดออกไปจากแผ่นดินของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 22, 'พระองค์ทรงตั้งเกดาลิยาห์บุตรชายอาหิคัมบุตรชายชาฟานให้เป็นเจ้าเมืองเหนือประชาชนผู้เหลืออยู่ในแผ่นดินยูดาห์ ผู้ซึ่งเนบูคัดเนสซาร์กษัตริย์บาบิโลนได้ทรงเหลือไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 23, 'เมื่อบรรดาผู้บังคับบัญชาพลรบ ทั้งตัวเขาทั้งหลายและคนของเขาได้ยินว่า กษัตริย์แห่งบาบิโลนได้แต่งตั้งเกดาลิยาห์ให้เป็นเจ้าเมือง เขาก็มาหาเกดาลิยาห์ที่มิสปาห์ คืออิชมาเอลบุตรชายเนธานิยาห์ และโยฮานันบุตรชายคาเรอาห์ และเสไรอาห์บุตรชายทันหุเมทชาวเนโทฟาห์ และยาอาซันยาห์บุตรชายคนมาอาคาห์ ทั้งเขาทั้งหลายและคนของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 24, 'และเกดาลิยาห์ก็กระทําสัตย์ปฏิญาณแก่เขาและคนของเขาว่า “อย่ากลัวที่จะเป็นผู้รับใช้ของคนเคลเดียเลย จงอาศัยในแผ่นดินและปรนนิบัติกษัตริย์แห่งบาบิโลน แล้วท่านก็จะอยู่เย็นเป็นสุข”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 25, 'แต่อยู่มาในเดือนที่เจ็ดอิชมาเอลบุตรชายเนธานิยาห์บุตรชายเอลีชามาผู้เป็นเชื้อพระวงศ์ ได้เข้ามาพร้อมกับชายสิบคน ได้โจมตีและฆ่าเกดาลิยาห์และพวกยิวกับคนเคลเดียผู้อยู่กับท่านที่มิสปาห์เสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 26, 'แล้วประชาชนทั้งปวง ทั้งเล็กและใหญ่ และผู้บังคับบัญชาพลรบได้ลุกขึ้น และไปยังอียิปต์ เพราะเขากลัวคนเคลเดีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 27, 'และอยู่มาในปีที่สามสิบเจ็ดแห่งการเนรเทศเยโฮยาคีนกษัตริย์แห่งยูดาห์ ในเดือนที่สิบสองเมื่อวันที่ยี่สิบเจ็ดของเดือนนั้น เอวิลเมโรดักกษัตริย์แห่งบาบิโลน ในปีที่พระองค์ทรงเริ่มครอบครอง ทรงพระกรุณาโปรดให้เยโฮยาคีนกษัตริย์แห่งยูดาห์พ้นจากเรือนจํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 28, 'พระองค์ตรัสด้วยคําอ่อนหวานแก่ท่าน และให้นั่งสูงกว่าบรรดาที่นั่งของกษัตริย์ที่อยู่ในบาบิโลนกับพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 29, 'เยโฮยาคีนจึงได้ถอดเครื่องแต่งกายของนักโทษออก และได้รับประทานที่โต๊ะเสวยของกษัตริย์เป็นปกติทุกวันตลอดชีวิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 30, 'ส่วนงบประมาณที่ให้นั้นก็ได้รับพระราชทานจากกษัตริย์ตามความต้องการรายวันอยู่เสมอตลอดเมื่อท่านมีชีวิตอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 1, 'อาดัม เสท เอโนช');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 2, 'เคนัน มาหะลาเลล ยาเรด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 3, 'เอโนค เมธูเสลาห์ ลาเมค');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 4, 'โนอาห์ เชม ฮาม ยาเฟท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 5, 'บุตรชายทั้งหลายของยาเฟท ชื่อ โกเมอร์ มาโกก มีเดีย ยาวาน ทูบัล เมเชค และทิราส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 6, 'บุตรชายทั้งหลายของโกเมอร์ ชื่อ อัชเคนัส รีฟาท และโทการมาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 7, 'บุตรชายทั้งหลายของยาวาน ชื่อ เอลีชาห์ ทารชิช คิทธิม และโดดานิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 8, 'บุตรชายทั้งหลายของฮาม ชื่อ คูช มิสรายิม พูต และคานาอัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 9, 'บุตรชายทั้งหลายของคูช ชื่อ เส-บา ฮาวิลาห์ สับทา ราอามาห์ และสับเทคา บุตรชายทั้งหลายของราอามาห์ ชื่อ เชบาและเดดาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 10, 'คูชให้กําเนิดบุตรชื่อนิมโรด เขาเริ่มเป็นคนมีอํานาจมากบนแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 11, 'มิสรายิมให้กําเนิดบุตรชื่อลูดิม อานามิม เลหะบิม นัฟทูฮิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 12, 'ปัทรุสิม คัสลูฮิม (ผู้ซึ่งออกมาจากเขาคือคนฟีลิสเตีย) และคัฟโทริม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 13, 'คานาอันให้กําเนิดบุตรหัวปีชื่อไซดอนและเฮท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 14, 'และคนเยบุส คนอาโมไรต์ คนเกอร์กาชี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 15, 'คนฮีไวต์ คนอารกี คนสินี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 16, 'คนอารวัด คนเศเมอร์ และคนฮามัท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 17, 'บุตรชายทั้งหลายของเชม ชื่อ เอลาม อัสชูร อารฟัคชาด ลูด อารัม อูส ฮุล เกเธอร์ และเมเชค');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 18, 'อารฟัคชาดให้กําเนิดบุตรชื่อเชลาห์ และเชลาห์ให้กําเนิดบุตรชื่อเอเบอร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 19, 'เอเบอร์ให้กําเนิดบุตรชายสองคน คนหนึ่งชื่อเปเลก เพราะในสมัยของเขาแผ่นดินถูกแบ่งแยก และน้องชายของเขาชื่อโยกทาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 20, 'โยกทานให้กําเนิดบุตรชื่ออัลโมดัด เชเลฟ ฮาซาร-มาเวท และเยราห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 21, 'ฮาโดรัม อุซาล และดิคลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 22, 'เอบาล อาบีมาเอล เชบา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 23, 'โอฟีร์ ฮาวิลาห์ และโยบับ คนเหล่านี้เป็นบุตรชายทั้งหลายของโยกทาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 24, 'เชม อารฟัคชาด เชลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 25, 'เอเบอร์ เปเลก เรอู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 26, 'เสรุก นาโฮร์ เทราห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 27, 'อับราม คืออับราฮัม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 28, 'บุตรชายของอับราฮัม ชื่อ อิสอัค และอิชมาเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 29, 'ต่อไปนี้เป็นพงศ์พันธุ์ของเขา บุตรหัวปีของอิชมาเอล คือ เนบาโยท และเคดาร์ อัดบีเอล มิบสัม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 30, 'มิชมา ดูมาห์ มัสสา ฮาดัด เทมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 31, 'เยทูร์ นาฟิช และเคเดมาห์ คนเหล่านี้เป็นบุตรชายของอิชมาเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 32, 'บุตรชายทั้งหลายของนางเคทูราห์ภรรยาน้อยของอับราฮัม คือ นางให้กําเนิดบุตรชื่อศิมราน โยกชาน เมดาน มีเดียน อิชบาก และชูอาห์ และบุตรชายของโยกชาน ชื่อ เชบาและเดดาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 33, 'บุตรชายของมีเดียน ชื่อ เอฟาห์ เอเฟอร์ ฮาโนค อาบีดา และเอลดาอาห์ ทั้งหมดนี้เป็นลูกหลานของนางเคทูราห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 34, 'อับราฮัมให้กําเนิดบุตรชื่ออิสอัค บุตรชายของอิสอัค ชื่อ เอซาว และอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 35, 'บุตรชายของเอซาว ชื่อ เอลีฟัส เรอูเอล เยอูช ยาลาม และโคราห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 36, 'บุตรชายของเอลีฟัส ชื่อ เทมาน โอมาร์ เศฟี กาทาม เคนัส ทิมนาและอามาเลข');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 37, 'บุตรชายของเรอูเอล ชื่อ นาหาท เศ-ราห์ ชัมมาห์ และมิสซาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 38, 'บุตรชายของเสอีร์ ชื่อ โลทาน โชบาล ศิเบโอน อานาห์ ดีโชน เอเซอร์ และดีชาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 39, 'บุตรชายของโลทาน ชื่อ โฮรี และโฮมาม และน้องสาวของโลทานชื่อทิมนา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 40, 'บุตรชายของโชบาล ชื่อ เอลียัน มานาฮาท เอบาล เชฟี และโอนัม บุตรชายของศิเบโอน ชื่อ อัยยาห์ และอานาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 41, 'บุตรชายของอานาห์ ชื่อ ดีโชน บุตรชายของดีโชน ชื่อ อัมราม เอชบาน อิธราน และเคราน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 42, 'บุตรชายของเอเซอร์ ชื่อ บิลฮาน ศาวาน และยาอาคัน บุตรชายของดีชาน ชื่อ อูส และอารัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 43, 'ต่อไปนี้เป็นกษัตริย์ผู้ทรงครอบครองอยู่ในแผ่นดินเอโดม ก่อนที่มีกษัตริย์ครอบครองอยู่เหนือคนอิสราเอล คือ เบลาบุตรชายเบโอร์ เมืองหลวงของท่านชื่อดินฮาบาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 44, 'เมื่อเบลาสิ้นพระชนม์แล้ว โยบับบุตรชายเศ-ราห์ชาวเมืองโบสราห์ขึ้นครอบครองแทน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 45, 'เมื่อโยบับสิ้นพระชนม์แล้ว หุชามชาวแผ่นดินของคนเทมานขึ้นครอบครองแทน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 46, 'เมื่อหุชามสิ้นพระชนม์แล้ว ฮาดัดบุตรชายของเบดัดผู้รบชนะคนมีเดียนในทุ่งแห่งโมอับขึ้นครอบครองแทน เมืองหลวงของท่านชื่ออาวีท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 47, 'เมื่อฮาดัดสิ้นพระชนม์แล้ว สัมลาห์ชาวเมืองมัสเรคาห์ขึ้นครอบครองแทน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 48, 'เมื่อสัมลาห์สิ้นพระชนม์แล้ว ชาอูลชาวเมืองเรโหโบทอยู่ที่แม่น้ําขึ้นครอบครองแทน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 49, 'เมื่อชาอูลสิ้นพระชนม์แล้ว บาอัลฮานันบุตรชายอัคโบร์ขึ้นครอบครองแทน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 50, 'เมื่อบาอัลฮานันสิ้นพระชนม์แล้ว ฮาดัดขึ้นครอบครองแทน เมืองหลวงของท่านชื่อปาอี และมเหสีของท่านมีพระนามว่า เมเหทาเบล ธิดาของมัทเรด ธิดาของเมซาหับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 51, 'และฮาดัดก็สิ้นพระชนม์ เจ้านายของเอโดมคือ เจ้านายทิมนา เจ้านายอาลียาห์ เจ้านายเยเธท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 52, 'เจ้านายโอโฮลีบามาห์ เจ้านายเอลาห์ เจ้านายปิโนน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 53, 'เจ้านายเคนัส เจ้านายเทมาน เจ้านายมิบซาร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 54, 'เจ้านายมักดีเอล และเจ้านายอิราม คนเหล่านี้เป็นเจ้านายของเอโดม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 1, 'ต่อไปนี้เป็นบุตรชายของอิสราเอล คือ รูเบน สิเมโอน เลวี ยูดาห์ อิสสาคาร์ เศบูลุน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 2, 'ดาน โยเซฟ เบนยามิน นัฟทาลี กาด และอาเชอร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 3, 'บุตรชายของยูดาห์ชื่อ เอร์ โอนัน และเช-ลาห์ ทั้งสามคนนี้บุตรสาวของชูวาคนคานาอันให้กําเนิดแก่ท่าน ฝ่ายเอร์บุตรหัวปีของยูดาห์นั้นเป็นคนชั่วในสายพระเนตรของพระเยโฮวาห์ และพระองค์ทรงสังหารเขาเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 4, 'ทามาร์บุตรสะใภ้ของท่านก็ให้กําเนิดบุตรชื่อเปเรศและเศ-ราห์ให้ท่านด้วย ยูดาห์มีบุตรชายห้าคนด้วยกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 5, 'บุตรชายของเปเรศชื่อเฮสโรน และฮามูล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 6, 'บุตรชายของเศ-ราห์คือ ศิมรี เอธาน เฮมาน คาลโคล์ และดารา ห้าคนด้วยกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 7, 'บุตรชายของคารมีชื่อ อาคาน ผู้นําความเดือดร้อนให้แก่อิสราเอล ผู้ละเมิดในเรื่องของที่ถูกสาปแช่งนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 8, 'และบุตรชายของเอธานชื่อ อาซาริยาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 9, 'บุตรชายของเฮสโรนซึ่งกําเนิดแก่ท่านนั้นคือ เยราเมเอล ราม และเคลุบัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 10, 'รามให้กําเนิดบุตรชื่ออัมมีนาดับ และอัมมีนาดับให้กําเนิดบุตรชื่อนาโชน เจ้านายในบุตรของยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 11, 'นาโชนให้กําเนิดบุตรชื่อสัลมา สัลมาให้กําเนิดบุตรชื่อโบอาส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 12, 'โบอาสให้กําเนิดบุตรชื่อโอเบด โอเบดให้กําเนิดบุตรชื่อเจสซี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 13, 'เจสซีให้กําเนิดเอลีอับบุตรหัวปีของท่าน อาบีนาดับที่สอง ชิเมอาที่สาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 14, 'เนธันเอลที่สี่ รัดดัยที่ห้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 15, 'โอเซมที่หก ดาวิดที่เจ็ด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 16, 'และพี่สาวของเขาคือเศรุยาห์ และอาบีกายิล บุตรชายของนางเศรุยาห์ชื่ออาบีชัย โยอาบและอาสาเฮล สามด้วยกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 17, 'อาบีกายิลให้กําเนิดบุตรชื่ออามาสา และบิดาของอามาสาชื่อเยเธอร์คนอิชมาเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 18, 'คาเลบบุตรชายเฮสโรนให้กําเนิดบุตรกับอาซูบาห์ภรรยาของตน และกับเยรีโอท ต่อไปนี้เป็นบุตรชายของนาง คือ เยเชอร์ โชบับ และอารโดน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 19, 'เมื่ออาซูบาห์สิ้นชีพแล้ว คาเลบก็แต่งงานกับเอฟราธาห์ ผู้ให้กําเนิดบุตรชื่อเฮอร์ให้แก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 20, 'เฮอร์ให้กําเนิดบุตรชื่ออุรี และอุรีให้กําเนิดบุตรชื่อเบซาเลล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 21, 'ภายหลังเฮสโรนได้เข้าหาบุตรสาวของมาคีร์บิดาของกิเลอาด และได้แต่งงานด้วยเมื่อท่านมีอายุหกสิบปี และนางได้กําเนิดบุตรให้ท่านชื่อ เสกุบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 22, 'และเสกุบให้กําเนิดบุตรชื่อยาอีร์ ผู้มีหัวเมืองยี่สิบสามหัวเมืองในแผ่นดินกิเลอาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 23, 'แต่จากหัวเมืองเหล่านั้น เขาได้ยึดเกชูร์กับอารัม พร้อมกับหัวเมืองต่างๆของยาอีร์ และหัวเมืองเคนาท กับบรรดาชนบทของหัวเมืองหกสิบชนบทด้วยกัน ทั้งสิ้นเหล่านี้เป็นของลูกหลานมาคีร์บิดาของกิเลอาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 24, 'ภายหลังเฮสโรนสิ้นชีพในคาเลบเอฟราธาห์ แล้วอาบียาห์ภรรยาของเฮสโรนก็คลอดบุตรให้แก่เขาชื่ออัชฮูร์ผู้เป็นบิดาของเทโคอา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 25, 'บุตรชายทั้งหลายของเยราเมเอลบุตรหัวปีของเฮสโรน คือ ราม บุตรหัวปีของท่าน บุนาห์ โอเรน โอเซม และอาหิยาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 26, 'เยราเมเอลมีภรรยาอีกคนหนึ่งชื่ออาทาราห์ นางเป็นมารดาของโอนัม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 27, 'บุตรชายของรามบุตรหัวปีของเยราเมเอลชื่อ มาอัส ยามีน และเอเคอร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 28, 'บุตรชายของโอนัมชื่อ ชัมมัยและยาดา บุตรชายของชัมมัยชื่อ นาดับและอาบีชูร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 29, 'ภรรยาของอาบีชูร์ชื่ออาบีฮาอิล และนางคลอดอัคบานและโมลิดให้ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 30, 'บุตรชายของนาดับชื่อ เสเลด และอัปปาอิม แต่เสเลดได้สิ้นชีพไม่มีบุตร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 31, 'บุตรชายของอัปปาอิมชื่อ อิชอี บุตรชายของอิชอีชื่อ เชชัน บุตรของเชชันชื่อ อัคลัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 32, 'บุตรชายของยาดาน้องชายของชัมมัยชื่อ เยเธอร์ และโยนาธาน และเยเธอร์สิ้นชีพไม่มีบุตร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 33, 'บุตรชายของโยนาธานชื่อ เปเลท และศาซา เหล่านี้เป็นลูกหลานของเยราเมเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 34, 'ฝ่ายเชชันไม่มีบุตรชายมีแต่บุตรสาว แต่เชชันมีทาสชาวอียิปต์อยู่คนหนึ่งชื่อ ยารฮา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 35, 'เชชันจึงยกบุตรสาวของตนให้เป็นภรรยาของยารฮาทาสของตน และนางก็คลอดบุตรให้เขาชื่อ อัททัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 36, 'อัททัยให้กําเนิดบุตรชื่อนาธัน และนาธันให้กําเนิดบุตรชื่อศาบาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 37, 'ศาบาดให้กําเนิดบุตรชื่อเอฟลาล และเอฟลาลให้กําเนิดบุตรชื่อโอเบด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 38, 'โอเบดให้กําเนิดบุตรชื่อเยฮู เยฮูให้กําเนิดบุตรชื่ออาซาริยาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 39, 'อาซาริยาห์ให้กําเนิดบุตรชื่อเฮเลส และเฮเลสให้กําเนิดบุตรชื่อเอเลอาสาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 40, 'เอเลอาสาห์ให้กําเนิดบุตรชื่อสิสะมัย และสิสะมัยให้กําเนิดบุตรชื่อชัลลูม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 41, 'ชัลลูมให้กําเนิดบุตรชื่อเยคามิยาห์ และเยคามิยาห์ให้กําเนิดบุตรชื่อเอลีชามา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 42, 'บุตรชายของคาเลบน้องชายของเยราเมเอลชื่อ เมชาบุตรหัวปีของท่าน ผู้เป็นบิดาของศิฟ และบุตรชายของมาเรชาห์ ผู้เป็นบิดาของเฮโบรน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 43, 'บุตรชายของเฮโบรนชื่อ โคราห์ ทัปปูวาห์ เรเคม และเชมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 44, 'เชมาให้กําเนิดบุตรชื่อราฮัม ผู้เป็นบิดาของโยรเคอัม และเรเคมให้กําเนิดบุตรชื่อชัมมัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 45, 'บุตรชายของชัมมัยคือ มาโอน และมาโอนเป็นบิดาของเบธซูร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 46, 'เอฟาห์ภรรยาน้อยของคาเลบคลอดบุตรชื่อฮาราน โมซาและกาเซส และฮารานให้กําเนิดบุตรชื่อกาเซส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 47, 'บุตรชายของยาดัยชื่อ เรเกม โยธาม เกชาน เปเลธ เอฟาห์ และชาอัฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 48, 'มาอาคาห์ภรรยาน้อยของคาเลบคลอดบุตรชื่อเชเบอร์และทีรหะนาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 49, 'นางคลอดบุตรชื่อชาอัฟ ผู้เป็นบิดาของมัดมันนาห์ เชวาผู้เป็นบิดาของมัคเบนาห์ และบิดาของกิเบอาด้วย บุตรสาวของคาเลบชื่ออัคสาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 50, 'เหล่านี้เป็นลูกหลานของคาเลบบุตรชายของเฮอร์ บุตรหัวปีของเอฟราธาห์ ชื่อ โชบาล บิดาของคีริยาทเยอาริม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 51, 'สัลมาบิดาของเบธเลเฮม และฮาเรฟบิดาของเบธกาเดอร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 52, 'โชบาลบิดาของคีริยาทเยอาริมมีบุตรชายอีกชื่อ ฮาโรเอห์ และครึ่งหนึ่งของคนเมนูโหท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 53, 'และครอบครัวของคีริยาทเยอาริม คือครอบครัวอิทไรต์ ครอบครัวปุไท ครอบครัวชุมัท ครอบครัวมิชรา จากคนเหล่านี้บังเกิดชาวโศราห์ และชาวเอชทาโอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 54, 'บุตรชายของสัลมาคือ เบธเลเฮม ชาวเนโทฟาห์ อาทาโรท วงศ์วานของโยอาบ และครึ่งหนึ่งของคนเมนูโหท ผู้เป็นชาวโศราห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 55, 'ทั้งครอบครัวของอาลักษณ์ซึ่งอยู่ ณ เมืองยาเบสคือ ครอบครัวทิราไธต์ ครอบครัวชิเมอา และครอบครัวสุคา เหล่านี้เป็นคนเคไนต์ผู้มาจากฮามัท ผู้เป็นบิดาวงศ์วานของเรคาบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 1, 'ต่อไปนี้เป็นโอรสของดาวิดประสูติให้แก่พระองค์ในกรุงเฮโบรน อัมโนนโอรสหัวปี พระนางอาหิโนอัมชาวยิสเรเอลประสูติ องค์ที่สองคือดาเนียล พระนางอาบีกายิลชาวคารเมลประสูติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 2, 'องค์ที่สามคืออับซาโลม โอรสของมาอาคาห์ราชธิดาของทัลมัย กษัตริย์ของเมืองเกชูร์ องค์ที่สี่คืออาโดนียาห์ โอรสของฮักกีท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 3, 'องค์ที่ห้าคือเชฟาทิยาห์ พระนางอาบีทัลประสูติ องค์ที่หกคืออิทเรอัม เอกลาห์มเหสีของพระองค์ประสูติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 4, 'ทั้งหกองค์ประสูติให้แก่พระองค์ในกรุงเฮโบรน ที่นั่นพระองค์ทรงครอบครองเจ็ดปีกับหกเดือน และพระองค์ทรงครอบครองในกรุงเยรูซาเล็มสามสิบสามปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 5, 'ต่อไปนี้เป็นโอรสที่ประสูติให้แก่พระองค์ในกรุงเยรูซาเล็ม คือ ชิเมอา โชบับ นาธันและซาโลมอน สี่องค์นี้พระนางบัทชูวา บุตรสาวของอัมมีเอลประสูติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 6, 'แล้วก็มีอิบฮาร์ เอลีชามา เอลีเฟเลท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 7, 'โนกาห์ เนเฟก ยาเฟีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 8, 'เอลีชามา เอลียาดา และเอลีเฟเลท เก้าองค์ด้วยกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 9, 'ทั้งสิ้นนี้เป็นโอรสของดาวิด นอกเหนือจากบุตรชายของนางสนม และทามาร์เป็นขนิษฐาของโอรส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 10, 'โอรสของซาโลมอนคือเรโหโบอัม โอรสของเรโหโบอัมคืออาบียาห์ โอรสของอาบียาห์คืออาสา โอรสของอาสาคือเยโฮชาฟัท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 11, 'โอรสของเยโฮชาฟัทคือโยรัม โอรสของโยรัมคืออาหัสยาห์ โอรสของอาหัสยาห์คือโยอาช');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 12, 'โอรสของโยอาชคืออามาซิยาห์ โอรสของอามาซิยาห์คืออาซาริยาห์ โอรสของอาซาริยาห์คือโยธาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 13, 'โอรสของโยธามคืออาหัส โอรสของอาหัสคือเฮเซคียาห์ โอรสของเฮเซคียาห์คือมนัสเสห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 14, 'โอรสของมนัสเสห์คืออาโมน โอรสของอาโมนคือโยสิยาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 15, 'โอรสของโยสิยาห์คือโยฮานันโอรสหัวปี องค์ที่สองคือเยโฮยาคิม องค์ที่สามคือเศเดคียาห์ องค์ที่สี่คือชัลลูม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 16, 'โอรสของเยโฮยาคิมคือเยโคนิยาห์ โอรสของเยโคนิยาห์คือเศเดคียาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 17, 'และโอรสของเยโคนิยาห์ชื่ออัสสีร์ เชอัลทิเอลโอรสของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 18, 'มัลคีราม เปดายาห์ เชนาสซาร์ เยคามิยาห์ โฮชามา เนดาบียาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 19, 'และบุตรชายของเปดายาห์คือ เศรุบบาเบลและชิเมอี และบุตรชายของเศรุบบาเบลคือ เมชุลลาม ฮานันยาห์ และน้องสาวของเขาชื่อเชโลมิท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 20, 'ฮาชูบาห์ โอเฮล เบเรคิยาห์ ฮาสาดิยาห์ และยูชับเฮเสด ห้าคนด้วยกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 21, 'บุตรชายของฮานันยาห์คือ เป-ลาทียาห์และเยชายาห์ ลูกหลานของเรไฟยาห์ ลูกหลานของอารนัน ลูกหลานของโอบาดีห์ ลูกหลานของเชคานิยาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 22, 'บุตรชายของเชคานิยาห์คือ เชไมอาห์ และบุตรชายของเชไมอาห์คือ ฮัทธัช อิกาล บารียาห์ เนอารียาห์และชาฟัท หกคนด้วยกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 23, 'บุตรชายของเนอารียาห์คือ เอลีโอนัย เฮเซคียาห์ และอัสรีคัม สามคนด้วยกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 24, 'บุตรชายของเอลีโอนัยคือ โฮดาอียาห์ เอลียาชีบ เปไลยาห์ อักขูบ โยฮานัน เดไลยาห์ และอานานี เจ็ดคนด้วยกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 1, 'บุตรชายของยูดาห์คือ เปเรศ เฮสโรน คารมี เฮอร์ และโชบาล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 2, 'เรอายาห์บุตรชายโชบาลให้กําเนิดบุตรชื่อยาหาท และยาหาทให้กําเนิดบุตรชื่ออาหุมัยและลาฮาด เหล่านี้เป็นครอบครัวของชาวโศราห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 3, 'ต่อไปนี้มาจากบิดาของเอตาม คือยิสเรเอล อิชมา และอิดบาช และน้องสาวของเขาชื่อฮัสเซเลลโพนี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 4, 'และเปนูเอลผู้เป็นบิดาของเกโดร์ และเอเซอร์ผู้เป็นบิดาของหุชาห์ เหล่านี้เป็นบุตรชายของเฮอร์ บุตรหัวปีของเอฟราธาห์ผู้เป็นบิดาของเบธเลเฮม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 5, 'อัชฮูร์บิดาของเทโคอา มีภรรยาสองคนคือ เฮลาห์และนาอาราห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 6, 'นาอาราห์คลอดอาหุสซาม เฮเฟอร์ เทเมนี และฮาอาหัชทารีให้แก่เขา เหล่านี้เป็นบุตรชายของนาอาราห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 7, 'บุตรชายของเฮลาห์ คือ เศเรท ยาโศอาร์ และเอทนาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 8, 'ฮักโขสให้กําเนิดบุตรชื่ออานูบ โศเบบาห์และบรรดาครอบครัวของอาหารเฮลบุตรชายฮารูม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 9, 'ฝ่ายยาเบสเป็นผู้มีเกียรติกว่าพี่น้องทั้งหลายของเขา มารดาของเขาเรียกชื่อเขาว่า ยาเบส กล่าวว่า “เพราะเราคลอดเขาด้วยความเจ็บปวด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 10, 'ยาเบสทูลพระเจ้าของอิสราเอลว่า “โอ ขอพระองค์ทรงอวยพระพรแก่ข้าพระองค์ และขยายเขตแดนของข้าพระองค์ และขอพระหัตถ์ของพระองค์อยู่กับข้าพระองค์ และขอพระองค์ทรงรักษาข้าพระองค์ให้พ้นจากเหตุร้าย เพื่อมิให้ข้าพระองค์เจ็บใจปวดกาย” และพระเจ้าทรงประสาทตามที่เขาทูลขอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 11, 'เคลูบพี่ชายของชูอาห์ให้กําเนิดบุตรชื่อเมหิร์ ผู้เป็นบิดาของเอชโทน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 12, 'เอชโทนให้กําเนิดบุตรชื่อเบธราฟา ปาเสอาห์ และเทหินนาห์ ผู้เป็นบิดาของอิรนาหาช เหล่านี้เป็นคนของเรคาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 13, 'บุตรชายของเคนัส คือโอทนีเอล และเสไรอาห์ และบุตรชายของโอทนีเอล คือฮาธาท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 14, 'เมโอโนธัยให้กําเนิดบุตรชื่อโอฟราห์ และเสไรอาห์ให้กําเนิดบุตรชื่อโยอาบ ผู้เป็นบิดาของชาวหุบเขาเกหะราชิม เพราะพวกเขาเป็นช่างฝีมือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 15, 'บุตรชายของคาเลบผู้เป็นบุตรชายเยฟุนเนห์คือ อิรู เอลาห์ และนาอัม และบุตรชายของเอลาห์คือเคนัส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 16, 'บุตรชายของเยฮาลเลเลลคือ ศิฟ ศิฟาห์ ทีรียา และอาสาเรล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 17, 'บุตรชายของเอสรา คือเยเธอร์ เมเรด เอเฟอร์ และยาโลน และนางก็คลอดบุตรชื่อมิเรียม ชัมมัย และอิชบาห์ ผู้เป็นบิดาของเอชเทโมอา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 18, 'และภรรยาของท่านชื่อเยฮูไดยาห์คลอดยาเรดบิดาของเกโดร์ เฮเบอร์บิดาของโสโค และเยคูธีเอลบิดาของศาโนอาห์ เหล่านี้เป็นบุตรชายของบิทิยาห์ธิดาของฟาโรห์ผู้ที่เมเรดได้แต่งงานด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 19, 'บุตรชายภรรยาของท่านชื่อโฮดียาห์น้องสาวของนาฮัมเป็นบิดาของเคอีลาห์ ผู้เป็นคนเกเรม และเอชเทโมอาผู้เป็นคนมาอาคาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 20, 'บุตรชายของชิโมนคือ อัมโนน รินนาห์ เบนฮานัน และทิโลน บุตรชายของอิชอีคือ โศเหท และเบนโซเฮท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 21, 'บุตรชายของเช-ลาห์ผู้เป็นบุตรชายยูดาห์ คือ เอร์ บิดาของเลคาห์ ลาอาดาห์บิดาของมาเรชาห์ และบรรดาครอบครัวแห่งวงศ์วานของผู้ทําผ้าป่านเนื้อละเอียดแห่งวงศ์วานอัชเบอา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 22, 'และโยคิม และคนเมืองโคเซบา และโยอาช และสาราฟผู้ปกครองในเมืองโมอับ และยาชูบิเลเฮม เป็นเรื่องแต่โบราณกาล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 23, 'คนเหล่านี้เป็นช่างหม้อ เขาอยู่กับต้นไม้เล็กๆและรั้วต้นไม้ ที่นั่นเขาอาศัยอยู่กับกษัตริย์รับราชการ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 24, 'บุตรชายของสิเมโอนชื่อ เนมูเอล ยามีน ยารีบ เศ-ราห์ และชาอูล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 25, 'บุตรชายของชาอูลคือชัลลูม บุตรชายของชัลลูมคือมิบสัม บุตรชายของมิบสัมคือมิชมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 26, 'บุตรชายของมิชมาคือฮัมมูเอล บุตรชายของฮัมมูเอลคือศักเกอร์ บุตรชายของศักเกอร์คือชิเมอี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 27, 'ชิเมอีมีบุตรชายสิบหกคน และบุตรสาวหกคน แต่พี่น้องของชิเมอีหามีบุตรมากไม่ ครอบครัวของเขาก็ไม่ทวีมากขึ้นอย่างกับคนยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 28, 'เขาทั้งหลายอาศัยอยู่ในเมืองเบเออร์เชบา โมลาดาห์ ฮาซารชูอาล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 29, 'และที่บิลฮาห์ เอเซม โทลัด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 30, 'เบธูเอล โฮรมาห์ ศิกลาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 31, 'เบธมารคาโบท ฮาซารสูสิม เบธบิรี และที่ชาอาราอิม เหล่านี้เป็นหัวเมืองของเขาจนถึงดาวิดขึ้นครอบครอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 32, 'และชนบทของเขาทั้งหลายคือเอตาม อายิน ริมโมน โทเคน และอาชัน ห้าหัวเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 33, 'รวมอยู่กับบรรดาชนบทของเขาซึ่งอยู่รอบหัวเมืองเหล่านี้ไกลไปจนถึงเมืองบาอัล เหล่านี้เป็นภูมิลําเนาของเขา และสํามะโนครัวเชื้อสายของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 34, 'เมโชบับ ยัมเลค โยชาห์บุตรชายอามาซิยาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 35, 'โยเอล เยฮูบุตรชายโยชิบียาห์ ผู้เป็นบุตรชายเสไรอาห์ ผู้เป็นบุตรชายอาสิเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 36, 'เอลีโอนัย ยาอาโคบาห์ เยโชฮายาห์ อาสายาห์ อาดีเอล เยสิมีเอล เบไนยาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 37, 'ซีซาบุตรชายชิฟี ผู้เป็นบุตรชายอาโลน ผู้เป็นบุตรชายเยดายาห์ ผู้เป็นบุตรชายชิมรี ผู้เป็นบุตรชายเชไมอาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 38, 'ท่านที่กล่าวชื่อมานี้เป็นเจ้านายในครอบครัวของท่าน และเรือนบรรพบุรุษของเขาทั้งหลายก็เพิ่มขึ้นมากมาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 39, 'เขาทั้งหลายได้เดินทางไปถึงทางเข้าเมืองที่เกโดร์ ถึงข้างทิศตะวันออกของหุบเขา เพื่อหาทุ่งหญ้าให้ฝูงแพะแกะของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 40, 'เขาทั้งหลายก็พบทุ่งหญ้าอุดมดี และแผ่นดินนั้นก็กว้างขวางเงียบและสงบสันติ เพราะชาวเมืองที่อยู่ก่อนนั้นเป็นคนฮาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 41, 'แล้วคนเหล่านี้ซึ่งมีชื่อในสํามะโนครัวได้เข้ามาในสมัยของเฮเซคียาห์กษัตริย์แห่งยูดาห์ และโจมตีเต็นท์ของเขา และที่อยู่อาศัยทั้งหลายที่พบอยู่ที่นั่น และกวาดล้างเขาเสียจนถึงทุกวันนี้ แล้วก็ตั้งภูมิลําเนาอยู่ในที่ของเขา เพราะที่นั่นมีทุ่งหญ้าให้ฝูงแพะแกะของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 42, 'ส่วนหนึ่งของเขาเหล่านั้นคือส่วนคนสิเมโอนห้าร้อยคนพากันไปที่ภูเขาเสอีร์ มีประมุขชื่อเป-ลาทียาห์ เนอารียาห์ เรไฟยาห์และอุสซีเอลบุตรชายทั้งหลายของอิชอี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 43, 'และเขาได้โจมตีคนอามาเลขส่วนที่เหลืออยู่ซึ่งหนีรอดไป แล้วเขาทั้งหลายก็อาศัยอยู่ที่นั่นจนทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 1, 'บุตรชายของรูเบนบุตรหัวปีของอิสราเอล (เขาเป็นบุตรหัวปีก็จริง แต่เพราะเขาได้กระทําให้ที่นอนของบิดาของเขามีมลทิน สิทธิบุตรหัวปีของเขาจึงตกอยู่กับบุตรชายของโยเซฟผู้เป็นบุตรชายอิสราเอล แต่โยเซฟมิได้ขึ้นทะเบียนไว้ในสํามะโนครัวเชื้อสายตามสิทธิบุตรหัวปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 2, 'แม้ว่ายูดาห์มีกําลังมากในพวกพี่น้องของตน และเจ้านายองค์หนึ่งก็มาจากเขา แต่สิทธิบุตรหัวปีก็ยังเป็นของโยเซฟ)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 3, 'บุตรชายของรูเบนบุตรหัวปีของอิสราเอล คือ ฮาโนค ปัลลู เฮสโรนและคารมี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 4, 'บุตรชายของโยเอลคือเชไมอาห์ บุตรชายของเชไมอาห์คือโกก บุตรชายของโกกคือชิเมอี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 5, 'บุตรชายของชิเมอีคือมีคาห์ บุตรชายของมีคาห์คือเรอายาห์ บุตรชายของเรอายาห์คือบาอัล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 6, 'บุตรชายของบาอัลคือเบเอราห์ ผู้ซึ่งทิกลัทปิเลเสอร์กษัตริย์เมืองอัสซีเรียได้กวาดไปเป็นเชลย ท่านเป็นเจ้านายของคนรูเบน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 7, 'และญาติของท่านตามครอบครัวเมื่อขึ้นทะเบียนสํามะโนครัวเชื้อสายไว้นั้นคือ เจ้าเยอีเอล และเศคาริยาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 8, 'และเบลาบุตรชายอาซาส บุตรชายเชมา บุตรชายโยเอล ผู้อาศัยอยู่ในอาโรเออร์ ไกลไปถึงเมืองเนโบและบาอัลเมโอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 9, 'ท่านอาศัยอยู่ทางทิศตะวันออกไกลออกไปถึงทางเข้าถิ่นทุรกันดาร ซึ่งอยู่ฟากข้างนี้ของแม่น้ํายูเฟรติสด้วย เพราะสัตว์เลี้ยงของเขาทวีมากขึ้นในแผ่นดินกิเลอาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 10, 'ในรัชกาลของซาอูลเขาทั้งหลายทําสงครามกับคนฮาการ์ผู้ต้องล้มตายด้วยมือของเขา เขาทั้งหลายอาศัยอยู่ในเต็นท์ของเขาตลอดแถบตะวันออกของกิเลอาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 11, 'ลูกหลานของกาดอาศัยอยู่ตรงหน้าเขาในแผ่นดินบาชานไปจนถึงเมืองสาเลคาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 12, 'โยเอลเป็นเจ้า ชาฟามเป็นที่สอง ยานัย และชาฟัทในบาชาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 13, 'และวงศ์ญาติของเขาตามเรือนบรรพบุรุษของเขา คือมีคาเอล เมชุลลาม เชบา โยรัย ยาคาน ศิอา และเอเบอร์ เจ็ดคนด้วยกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 14, 'คนเหล่านี้เป็นบุตรอาบีฮาอิล ผู้เป็นบุตรชายหุรี ผู้เป็นบุตรชายยาโรอาห์ ผู้เป็นบุตรชายกิเลอาด ผู้เป็นบุตรชายมีคาเอล ผู้เป็นบุตรชายเยชิชัย ผู้เป็นบุตรชายยาโด ผู้เป็นบุตรชายบูส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 15, 'อาหิเป็นบุตรชายอับดีเอล ผู้เป็นบุตรชายกูนี เป็นเจ้านายในเรือนบรรพบุรุษของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 16, 'และเขาทั้งหลายอาศัยอยู่ในกิเลอาด ในบาชาน และตามหัวเมือง และในเขตทุ่งหญ้าทั้งสิ้นของชาโรนจนสุดเขต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 17, 'คนเหล่านี้ทั้งสิ้นขึ้นทะเบียนสํามะโนครัวเชื้อสายไว้ในรัชกาลของโยธามกษัตริย์แห่งยูดาห์ และในรัชกาลของเยโรโบอัมกษัตริย์แห่งอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 18, 'คนรูเบน คนกาด และคนตระกูลมนัสเสห์ครึ่งหนึ่งมีคนเก่งกล้า ผู้ถือดั้งและดาบ และโก่งธนู ชํานาญศึกสี่หมื่นสี่พันเจ็ดร้อยหกสิบคน พร้อมที่จะเข้ารบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 19, 'เขาทําศึกกับคนฮาการ์ เยทูร์ นาฟิช และโนดับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 20, 'และเมื่อเขาได้รับความช่วยเหลือ คนฮาการ์และพวกที่อยู่ด้วยทุกคนก็ถูกมอบไว้ในมือของเขา เพราะเขาร้องทูลต่อพระเจ้าในการสงคราม และพระองค์ทรงประสาทตามคําทูลของเขา เพราะเขาทั้งหลายวางใจในพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 21, 'เขาได้กวาดเอาฝูงสัตว์ของข้าศึกไป คืออูฐห้าหมื่นตัว แกะสองแสนห้าหมื่นตัว ลาสองพัน และคนหนึ่งแสน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 22, 'เพราะเขาล้มตายเสียมาก ด้วยการศึกครั้งนั้นเป็นมาจากพระเจ้า และเขาทั้งหลายอาศัยอยู่ในที่ของเขาจนถูกกวาดไปเป็นเชลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 23, 'คนตระกูลมนัสเสห์ครึ่งหนึ่งอาศัยอยู่ในแผ่นดินนั้น เขามีคนมากขึ้นด้วยกันตั้งแต่เมืองบาชานถึงเมืองบาอัลเฮอร์โมน เสนีร์ และภูเขาเฮอร์โมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 24, 'ต่อไปนี้เป็นหัวหน้าเรือนบรรพบุรุษของเขาคือ เอเฟอร์ อิชอี เอลีเอล อัซรีเอล เยเรมีย์ โฮดาวิยาห์ และยาดีเอล เป็นทแกล้วทหาร คนมีชื่อเสียง เป็นหัวหน้าเรือนบรรพบุรุษของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 25, 'แต่เขาทั้งหลายละเมิดต่อพระเจ้าแห่งบรรพบุรุษของเขา และเล่นชู้กับบรรดาพระของชนชาติทั้งหลายแห่งแผ่นดินนั้น ผู้ซึ่งพระเจ้าทรงทําลายเสียต่อหน้าเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 26, 'พระเจ้าแห่งอิสราเอลจึงทรงเร้าจิตใจของปูลกษัตริย์แห่งอัสซีเรีย และจิตใจของทิกลัทปิเลเสอร์กษัตริย์แห่งอัสซีเรีย และพระองค์ทรงกวาดเขาไปเสียคือ คนรูเบน คนกาด และคนตระกูลมนัสเสห์ครึ่งหนึ่ง และพาเขาทั้งหลายไปยังฮาลาห์ ฮาโบร์ ฮารา และแม่น้ําเมืองโกซาน จนถึงทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 1, 'บุตรชายของเลวีคือ เกอร์โชน โคฮาท และเมรารี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 2, 'บุตรชายของโคฮาทชื่อ อัมราม อิสฮาร์ เฮโบรน และอุสซีเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 3, 'บุตรของอัมรามคือ อาโรน โมเสส และนางมิเรียม บุตรชายอาโรนคือ นาดับ อาบีฮู เอเลอาซาร์ และอิธามาร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 4, 'เอเลอาซาร์ให้กําเนิดบุตรชื่อฟีเนหัส ฟีเนหัสให้กําเนิดบุตรชื่ออาบีชูวา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 5, 'อาบีชูวาให้กําเนิดบุตรชื่อบุคคี บุคคีให้กําเนิดบุตรชื่ออุสซี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 6, 'อุสซีให้กําเนิดบุตรชื่อเศ-ราหิยาห์ เศ-ราหิยาห์ให้กําเนิดบุตรชื่อเมราโยท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 7, 'เมราโยทให้กําเนิดบุตรชื่ออามาริยาห์ อามาริยาห์ให้กําเนิดบุตรชื่ออาหิทูบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 8, 'อาหิทูบให้กําเนิดบุตรชื่อศาโดก ศาโดกให้กําเนิดบุตรชื่ออาหิมาอัส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 9, 'อาหิมาอัสให้กําเนิดบุตรชื่ออาซาริยาห์ อาซาริยาห์ให้กําเนิดบุตรชื่อโยฮานัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 10, 'และโยฮานันให้กําเนิดบุตรชื่ออาซาริยาห์ (ท่านนี้แหละที่ทําหน้าที่ปุโรหิตอยู่ในพระวิหารซึ่งซาโลมอนทรงสร้างในเยรูซาเล็ม)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 11, 'อาซาริยาห์ให้กําเนิดบุตรชื่ออามาริยาห์ อามาริยาห์ให้กําเนิดบุตรชื่ออาหิทูบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 12, 'อาหิทูบให้กําเนิดบุตรชื่อศาโดก ศาโดกให้กําเนิดบุตรชื่อชัลลูม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 13, 'ชัลลูมให้กําเนิดบุตรชื่อฮิลคียาห์ ฮิลคียาห์ให้กําเนิดบุตรชื่ออาซาริยาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 14, 'อาซาริยาห์ให้กําเนิดบุตรชื่อเสไรอาห์ เสไรอาห์ให้กําเนิดบุตรชื่อเยโฮซาดัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 15, 'และเยโฮซาดักถูกกวาดไปเป็นเชลย เมื่อพระเยโฮวาห์ได้ทรงให้ยูดาห์ และเยรูซาเล็มเข้าสู่การถูกกวาดไปเป็นเชลยด้วยหัตถ์ของเนบูคัดเนสซาร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 16, 'บุตรชายของเลวีคือ เกอร์โชม โคฮาท และเมรารี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 17, 'ต่อไปนี้เป็นชื่อบุตรชายของเกอร์โชมคือ ลิบนี และชิเมอี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 18, 'บุตรชายของโคฮาทคือ อัมราม อิสฮาร์ เฮโบรน และอุสซีเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 19, 'บุตรชายของเมรารีคือ มาห์ลี และมูชี เหล่านี้เป็นครอบครัวของคนเลวีตามพงศ์พันธุ์บิดาของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 20, 'บุตรชายของเกอร์โชมคือลิบนี บุตรชายของลิบนีคือยาหาท บุตรชายของยาหาทคือศิมมาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 21, 'บุตรชายของศิมมาห์คือโยอาห์ บุตรชายของโยอาห์คืออิดโด บุตรชายของอิดโดคือเศ-ราห์ บุตรชายของเศ-ราห์คือเยอาเธรัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 22, 'บุตรชายของโคฮาทคือ อัมมีนาดับ บุตรชายของอัมมีนาดับคือโคราห์ บุตรชายของโคราห์คืออัสสีร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 23, 'บุตรชายของอัสสีร์คือเอลคานาห์ บุตรชายของเอลคานาห์คือเอบียาสาฟ บุตรชายของเอบียาสาฟคืออัสสีร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 24, 'บุตรชายของอัสสีร์คือทาหัท บุตรชายของทาหัทคืออุรีเอล บุตรชายของอุรีเอลคืออุสซียาห์ บุตรชายของอุสซียาห์คือชาอูล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 25, 'บุตรชายของเอลคานาห์คือ อามาสัย และอาหิโมท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 26, 'สําหรับเอลคานาห์นั้น บุตรชายของเอลคานาห์คือโศฟัย บุตรชายของโศฟัยคือนาหาท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 27, 'บุตรชายของนาหาทคือเอลีอับ บุตรชายของเอลีอับคือเยโรฮัม บุตรชายของเยโรฮัมคือเอลคานาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 28, 'บุตรชายของซามูเอลคือ วัสนีบุตรหัวปีของเขา และอาบียาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 29, 'บุตรชายของเมรารีคือมาห์ลี บุตรชายของมาห์ลีคือลิบนี บุตรชายของลิบนีคือชิเมอี บุตรชายของชิเมอีคืออุสซาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 30, 'บุตรชายของอุสซาห์คือชิเมอา บุตรชายของชิเมอาคือฮักกียาห์ บุตรชายของฮักกียาห์คืออาสายาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 31, 'เหล่านี้เป็นบุคคลที่ดาวิดทรงแต่งตั้งให้ดูแลการร้องเพลงในพระนิเวศของพระเยโฮวาห์ หลังจากที่หีบพันธสัญญามาตั้งอยู่ที่นั่นแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 32, 'เขาทั้งหลายทําการปรนนิบัติด้วยเพลง ข้างหน้าที่พักอาศัยในพลับพลาแห่งชุมนุม จนซาโลมอนได้ทรงสร้างพระนิเวศของพระเยโฮวาห์ในเยรูซาเล็ม และเขาได้ปฏิบัติหน้าที่ของเขาตามตําแหน่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 33, 'ต่อไปนี้เป็นบุคคลที่ปฏิบัติงานอยู่พร้อมกับบุตรของเขา พวกบุตรชายของคนโคฮาทคือ เฮมานนักร้อง ผู้เป็นบุตรชายโยเอล ผู้เป็นบุตรชายเชมูเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 34, 'ผู้เป็นบุตรชายเอลคานาห์ ผู้เป็นบุตรชายเยโรฮัม ผู้เป็นบุตรชายเอลีเอล ผู้เป็นบุตรชายโทอาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 35, 'ผู้เป็นบุตรชายศูฟ ผู้เป็นบุตรชายเอลคานาห์ ผู้เป็นบุตรชายมาฮาท ผู้เป็นบุตรชายอามาสัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 36, 'ผู้เป็นบุตรชายเอลคานาห์ ผู้เป็นบุตรชายโยเอล ผู้เป็นบุตรชายอาซาริยาห์ ผู้เป็นบุตรชายเศฟันยาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 37, 'ผู้เป็นบุตรชายทาหัท ผู้เป็นบุตรชายอัสสีร์ ผู้เป็นบุตรชายเอบียาสาฟ ผู้เป็นบุตรชายโคราห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 38, 'ผู้เป็นบุตรชายอิสฮาร์ ผู้เป็นบุตรชายโคฮาท ผู้เป็นบุตรชายเลวี ผู้เป็นบุตรชายอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 39, 'กับอาสาฟพี่น้องของเขา ผู้ซึ่งยืนอยู่ข้างขวามือของเขา คืออาสาฟบุตรชายเบเรคิยาห์ ผู้เป็นบุตรชายชิเมอา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 40, 'ผู้เป็นบุตรชายมีคาเอล ผู้เป็นบุตรชายบาอาเสยาห์ ผู้เป็นบุตรชายมัลคิยาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 41, 'ผู้เป็นบุตรชายเอทนี ผู้เป็นบุตรชายเศ-ราห์ ผู้เป็นบุตรชายอาดายาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 42, 'ผู้เป็นบุตรชายเอธาน ผู้เป็นบุตรชายศิมมาห์ ผู้เป็นบุตรชายชิเมอี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 43, 'ผู้เป็นบุตรชายยาหาท ผู้เป็นบุตรชายเกอร์โชม ผู้เป็นบุตรชายเลวี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 44, 'ที่ข้างซ้ายมือมีบุตรชายของเมรารี พี่น้องของเขาคือ เอธานผู้เป็นบุตรชายคีชี ผู้เป็นบุตรชายอับดี ผู้เป็นบุตรชายมัลลูค');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 45, 'ผู้เป็นบุตรชายฮาชาบิยาห์ ผู้เป็นบุตรชายอามาซิยาห์ ผู้เป็นบุตรชายฮิลคียาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 46, 'ผู้เป็นบุตรชายอัมซี ผู้เป็นบุตรชายบานี ผู้เป็นบุตรชายเชเมอร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 47, 'ผู้เป็นบุตรชายมาห์ลี ผู้เป็นบุตรชายมูชี ผู้เป็นบุตรชายเมรารี ผู้เป็นบุตรชายเลวี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 48, 'และคนเลวีพี่น้องของเขาได้รับแต่งตั้งให้ปฏิบัติงานทุกอย่างของพลับพลาของพระนิเวศของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 49, 'แต่อาโรนกับบุตรชายของท่านถวายเครื่องบูชาบนแท่นเครื่องเผาบูชาและบนแท่นเครื่องหอม และปฏิบัติงานทั้งสิ้นในที่บริสุทธิ์ที่สุด และกระทําการลบมลทินบาปของอิสราเอล ตามทุกอย่างที่โมเสสผู้รับใช้ของพระเจ้าได้บัญชาไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 50, 'ต่อไปนี้เป็นบุตรชายของอาโรนคือเอเลอาซาร์ บุตรชายของเอเลอาซาร์คือฟีเนหัส บุตรชายของฟีเนหัสคืออาบีชูวา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 51, 'บุตรชายอาบีชูวาคือบุคคี บุตรชายของบุคคีคืออุสซี บุตรชายของอุสซีคือเศ-ราหิยาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 52, 'บุตรชายของเศ-ราหิยาห์คือเมราโยท บุตรชายของเมราโยทคืออามาริยาห์ บุตรชายของอามาริยาห์คืออาหิทูบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 53, 'บุตรชายของอาหิทูบคือศาโดก บุตรชายของศาโดกคืออาหิมาอัส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 54, 'ต่อไปนี้เป็นที่อาศัยของเขาตามค่ายในเขตแดนของเขา คือลูกหลานของอาโรน ครอบครัวคนโคฮาท เพราะฉลากตกเป็นของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 55, 'เขาได้รับเมืองเฮโบรนในแผ่นดินยูดาห์ และทุ่งหญ้าซึ่งอยู่ล้อมรอบนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 56, 'แต่ทุ่งนาและตามชนบทของเมืองนั้น เขายกให้แก่คาเลบบุตรชายเยฟุนเนห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 57, 'เขาให้เมืองต่างๆแห่งยูดาห์แก่ลูกหลานของอาโรน คือเมืองเฮโบรนซึ่งเป็นเมืองลี้ภัย เมืองลิบนาห์กับทุ่งหญ้า เมืองยาททีร์ เมืองเอชเทโมอากับทุ่งหญ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 58, 'ฮีเลนพร้อมกับทุ่งหญ้า เดบีร์พร้อมกับทุ่งหญ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 59, 'อาชันพร้อมกับทุ่งหญ้า และเบธเชเมชพร้อมกับทุ่งหญ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 60, 'และจากดินแดนตระกูลเบนยามินก็มอบเมืองเกบาพร้อมกับทุ่งหญ้า อาเลเมทพร้อมกับทุ่งหญ้า และอานาโธทพร้อมกับทุ่งหญ้า หัวเมืองทั้งสิ้นของเขาทุกครอบครัวเป็นสิบสามหัวเมืองด้วยกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 61, 'ส่วนคนโคฮาทที่เหลืออยู่นั้นได้รับส่วนมอบโดยฉลากที่ได้จากครอบครัวของตระกูล จากตระกูลมนัสเสห์ครึ่งหนึ่งมีสิบหัวเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 62, 'และมอบสิบสามหัวเมืองจากตระกูลอิสสาคาร์ ตระกูลอาเชอร์ ตระกูลนัฟทาลี และจากตระกูลมนัสเสห์ในบาชานให้แก่คนเกอร์โชมตามครอบครัวของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 63, 'และมอบโดยฉลากสิบสองหัวเมืองจากตระกูลรูเบน ตระกูลกาด และตระกูลเศบูลุนให้แก่คนเมรารีตามครอบครัวของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 64, 'ดังนี้แหละประชาชนอิสราเอลได้มอบหัวเมืองพร้อมกับทุ่งหญ้าให้แก่คนเลวี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 65, 'และคนอิสราเอลได้จับฉลากให้หัวเมืองจากตระกูลยูดาห์ ตระกูลสิเมโอน และตระกูลเบนยามิน ตามที่กล่าวชื่อไว้นั้นด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 66, 'และครอบครัวคนโคฮาทที่เหลืออยู่มีหัวเมืองอันเป็นดินแดนของเขาจากตระกูลเอฟราอิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 67, 'คนอิสราเอลได้ให้หัวเมืองลี้ภัย คือเมืองเชเคมพร้อมกับทุ่งหญ้าในถิ่นภูเขาเอฟราอิม เมืองเกเซอร์พร้อมกับทุ่งหญ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 68, 'เมืองโยกเมอัมพร้อมกับทุ่งหญ้า เมืองเบธโฮโรนพร้อมกับทุ่งหญ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 69, 'เมืองอัยยาโลนพร้อมกับทุ่งหญ้า เมืองกัทริมโมนพร้อมกับทุ่งหญ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 70, 'และมอบเมืองจากตระกูลมนัสเสห์ครึ่งหนึ่ง คือเมืองอาเนอร์พร้อมกับทุ่งหญ้า เมืองบิเลอัมพร้อมกับทุ่งหญ้าให้แก่ครอบครัวคนโคฮาทที่เหลืออยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 71, 'ดินแดนของมนัสเสห์ครึ่งตระกูลที่มอบให้แก่คนเกอร์โชมคือ โกลานในเมืองบาชานพร้อมกับทุ่งหญ้า และอัชทาโรทพร้อมกับทุ่งหญ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 72, 'และจากตระกูลอิสสาคาร์ คือเมืองเคเดชพร้อมกับทุ่งหญ้า เมืองดาเบรัทพร้อมกับทุ่งหญ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 73, 'และเมืองราโมทพร้อมกับทุ่งหญ้า และเมืองอาเนมพร้อมกับทุ่งหญ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 74, 'จากตระกูลอาเชอร์ คือ เมืองมาชาลพร้อมกับทุ่งหญ้า เมืองอับโดนพร้อมกับทุ่งหญ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 75, 'เมืองหุกอกพร้อมกับทุ่งหญ้า และเมืองเรโหบพร้อมกับทุ่งหญ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 76, 'และจากตระกูลนัฟทาลี คือ เมืองเคเดชในกาลิลีพร้อมกับทุ่งหญ้า เมืองฮัมโมนพร้อมกับทุ่งหญ้า เมืองคีริยาธาอิมพร้อมกับทุ่งหญ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 77, 'ส่วนคนเมรารีที่เหลืออยู่นั้นได้รับจากตระกูลเศบูลุนคือ เมืองริมโมนพร้อมกับทุ่งหญ้า เมืองทาโบร์พร้อมกับทุ่งหญ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 78, 'และฟากแม่น้ําจอร์แดนข้างโน้นที่เยรีโค คือฟากตะวันออกของแม่น้ําจอร์แดนนั้น จากตระกูลรูเบน คือเมืองเบเซอร์ในถิ่นทุรกันดารพร้อมกับทุ่งหญ้า เมืองยาฮาสพร้อมกับทุ่งหญ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 79, 'เมืองเคเดโมทพร้อมกับทุ่งหญ้า และเมืองเมฟาอาทพร้อมกับทุ่งหญ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 80, 'และจากตระกูลกาด คือ เมืองราโมทในกิเลอาดพร้อมกับทุ่งหญ้า เมืองมาหะนาอิมพร้อมกับทุ่งหญ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 81, 'เมืองเฮชโบนพร้อมกับทุ่งหญ้า เมืองยาเซอร์พร้อมกับทุ่งหญ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 1, 'บุตรชายของอิสสาคาร์ คือ โทลา ปูวาห์ ยาชูบ และชิมโรน สี่คนด้วยกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 2, 'บุตรชายของโทลาคือ อุสซี เรไฟยาห์ เยรีเอล ยามัย ยิบสัม และเชมูเอล หัวหน้าในเรือนบรรพบุรุษของเขา คือของโทลา เป็นทแกล้วทหารของพงศ์พันธุ์ของเขา และจํานวนของคนเหล่านี้ในรัชสมัยของดาวิดเป็นสองหมื่นสองพันหกร้อยคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 3, 'บุตรชายของอุสซีคือ อิสราหิยาห์ และบุตรชายของอิสราหิยาห์คือ มีคาเอล โอบาดีห์ โยเอล และอิสชีอาห์ ห้าคนด้วยกัน ทุกคนเป็นคนชั้นหัวหน้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 4, 'และพร้อมกับคนเหล่านี้ตามพงศ์พันธุ์ของเขาตามเรือนบรรพบุรุษของเขา มีหน่วยทหารศึกสามหมื่นหกพันคน เพราะเขามีภรรยาและบุตรชายมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 5, 'ญาติพี่น้องของเขาซึ่งเป็นคนในบรรดาครอบครัวของอิสสาคาร์ มีหมดด้วยกันเป็นทแกล้วทหารแปดหมื่นเจ็ดพันคน ขึ้นทะเบียนไว้ในสํามะโนครัวเชื้อสาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 6, 'บุตรชายของเบนยามินคือ เบลา เบเคอร์ และเยดียาเอล สามคนด้วยกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 7, 'บุตรชายของเบลาคือ เอสโบน อุสซี อุสซีเอล เยรีโมท และอิรี ห้าคนด้วยกัน เป็นหัวหน้าของเรือนบรรพบุรุษ เป็นทแกล้วทหาร และจํานวนที่ขึ้นทะเบียนไว้ในสํามะโนครัวเชื้อสายของเขาเป็นสองหมื่นสองพันสามสิบสี่คน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 8, 'บุตรชายของเบเคอร์คือ เศมิราห์ โยอาช เอลีเยเซอร์ เอลีโอนัย อมรี เยรีโมท อาบียาห์ อานาโธท และอาเลเมท ทั้งหมดนี้เป็นบุตรชายของเบเคอร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 9, 'และจํานวนที่ขึ้นทะเบียนไว้ในสํามะโนครัวเชื้อสาย ตามพงศ์พันธุ์ เป็นหัวหน้าเรือนบรรพบุรุษของเขา เป็นทแกล้วทหาร เป็นสองหมื่นสองร้อยคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 10, 'บุตรชายของเยดียาเอลคือ บิลฮาน และบุตรชายของบิลฮานคือ เยอูช เบนยามิน เอฮูด เคนาอะนาห์ เศธาน ทารชิช และอาหิชาฮาร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 11, 'ทั้งหมดนี้เป็นบุตรชายของเยดียาเอล ตามหัวหน้าเรือนบรรพบุรุษของเขา เป็นทแกล้วทหาร เป็นหนึ่งหมื่นเจ็ดพันสองร้อยคน พร้อมที่จะทําศึกสงคราม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 12, 'และชุปปิม และหุปปิม เป็นบุตรอิระ และหุชิมบุตรชายอาเฮอร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 13, 'บุตรชายของนัฟทาลีคือ ยาซีเอล กูนี เยเซอร์ และชัลลูม ลูกหลานของนางบิลฮาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 14, 'บุตรชายของมนัสเสห์คือ อัสรีเอล ซึ่งนางกําเนิดให้ท่าน (แต่ภรรยาน้อยของท่านคือชาวอารัมกําเนิดมาคีร์บิดาของกิเลอาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 15, 'มาคีร์ก็รับพี่สาวของหุปปิมและชุปปิมมาเป็นภรรยา พี่สาวของเขาชื่อมาอาคาห์) และคนที่สองชื่อเศโลเฟหัด และเศโลเฟหัดมีบุตรสาว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 16, 'และมาอาคาห์ภรรยาของมาคีร์คลอดบุตรชายคนหนึ่ง นางเรียกชื่อเขาว่า เปเรช และน้องชายของเขาชื่อเชเรช และบุตรชายของเขาชื่อ อุลาม และราเคม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 17, 'บุตรชายของอุลามคือเบดาน เหล่านี้เป็นบุตรชายกิเลอาด ผู้เป็นบุตรชายมาคีร์ ผู้เป็นบุตรชายมนัสเสห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 18, 'และฮัมโมเลเคทน้องสาวของเขาคลอดบุตรชื่ออิชโฮด อาบีเยเซอร์ และมาฮาลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 19, 'บุตรชายของเชมิดาคือ อาหิยัน เชเคม ลิคฮี และอานียัม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 20, 'บุตรชายของเอฟราอิมคือชูเธลาห์ และบุตรชายของชูเธลาห์คือเบเรด บุตรชายของเบเรดคือทาหัท บุตรชายของทาหัทคือเอลอาดาห์ บุตรชายของเอลอาดาห์คือทาหัท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 21, 'บุตรชายของทาหัทคือศาบาด บุตรชายของศาบาดคือชูเธลาห์ กับเอเซอร์และเอเลอัด ซึ่งคนของกัทผู้ที่เกิดในเมืองนั้นได้ฆ่าเสีย เพราะเขาทั้งหลายลงมาปล้นสัตว์เลี้ยงของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 22, 'และเอฟราอิมบิดาของเขาไว้ทุกข์โศกเศร้าเป็นหลายวัน และพี่น้องของเขาก็มาเล้าโลมเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 23, 'และเอฟราอิมก็เข้าไปหาภรรยา และนางก็ตั้งครรภ์คลอดบุตรชายคนหนึ่ง และท่านเรียกชื่อเขาว่า เบรียาห์ เพราะเหตุชั่วร้ายตกอยู่กับเรือนของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 24, '(บุตรสาวของท่านชื่อเชเอราห์ ผู้ซึ่งสร้างเมืองเบธโฮโรนล่างและบน และเมืองอุสเซนเชเอราห์)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 25, 'เอฟราอิมมีบุตรชายชื่อเรฟาห์ บุตรชายของเรฟาห์คือเรเชฟ บุตรชายของเรเชฟคือเทลาห์ บุตรชายของเทลาห์คือทาหาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 26, 'บุตรชายของทาหานคือลาดาน บุตรชายของลาดานคืออัมมีฮูด บุตรชายของอัมมีฮูดคือเอลีชามา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 27, 'บุตรชายของเอลีชามาคือนูน บุตรชายของนูนคือโยชูวา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 28, 'ที่ดินกรรมสิทธิ์และภูมิลําเนาของเขาคือ เบธเอลพร้อมกับบรรดาหัวเมือง และนาอารันด้านตะวันออก และเกเซอร์ด้านตะวันตกพร้อมกับบรรดาหัวเมือง เชเคมพร้อมกับบรรดาหัวเมือง และกาซาพร้อมกับบรรดาหัวเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 29, 'และตามพรมแดนของคนมนัสเสห์ มีเมืองเบธชานพร้อมกับบรรดาหัวเมือง ทาอานาคพร้อมกับบรรดาหัวเมือง เมกิดโดพร้อมกับบรรดาหัวเมือง โดร์พร้อมกับบรรดาหัวเมือง ลูกหลานโยเซฟบุตรชายอิสราเอลได้อาศัยอยู่ในที่เหล่านี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 30, 'บุตรชายของอาเชอร์คือ อิมนาห์ อิชวาห์ อิชวี เบรียาห์ และเสราห์น้องสาวของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 31, 'บุตรชายของเบรียาห์คือ เฮเบอร์และมัลคีเอล ผู้เป็นบิดาของบิรซาวิธ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 32, 'เฮเบอร์ให้กําเนิดบุตรชื่อยาเฟล็ท โชเมอร์ โฮธามและชูวาน้องสาวของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 33, 'บุตรชายของยาเฟล็ทคือ ปาสัค บิมฮาล และอัชวาท เหล่านี้เป็นบุตรยาเฟล็ท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 34, 'บุตรชายของเชเมอร์คือ อาหิ โรกาห์ เยฮุบบาห์ และอารัม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 35, 'บุตรชายของเฮเลมน้องชายของเขาคือ โศฟาห์ อิมนา เชเลช และอามัล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 36, 'บุตรชายของโศฟาห์คือ สุอาห์ ฮารเนเฟอร์ ชูอัล เบรี อิมราห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 37, 'เบเซอร์ โฮด ชัมมา ชิลชาห์ อิธราน และเบโอรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 38, 'บุตรชายของเยเธอร์คือ เยฟุนเนห์ ปิสปา และอารา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 39, 'บุตรชายของอุลลาคือ อาราห์ ฮันนีเอล และรีเซีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 40, 'ทั้งสิ้นเหล่านี้เป็นคนของอาเชอร์ หัวหน้าในเรือนบรรพบุรุษของเขา เป็นทแกล้วทหารที่คัดเลือกไว้ เป็นเจ้านายใหญ่ จํานวนที่ขึ้นทะเบียนไว้ในสํามะโนครัวเชื้อสายเพื่อทําศึกสงครามเป็นสองหมื่นหกพันคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 1, 'เบนยามินให้กําเนิดเบลาบุตรหัวปีของเขา อัชเบลคนที่สอง อาหะราห์คนที่สาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 2, 'โนฮาห์คนที่สี่ ราฟาคนที่ห้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 3, 'และบุตรชายของเบลาคือ อัดดาห์ เก-รา อาบีฮูด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 4, 'อาบีชูวา นาอามาน อาโหอาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 5, 'เก-รา เชฟูฟาน และหุราม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 6, 'ต่อไปนี้เป็นบุตรชายของเอฮูด เขาทั้งหลายเป็นหัวหน้าบรรพบุรุษของชาวเมืองเกบา และเขาถูกกวาดไปเป็นเชลยยังเมืองมานาฮาท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 7, 'คือนาอามาน อาหิยาห์ และเก-รา เขาทั้งหลายถูกกวาดไปเป็นเชลย และท่านให้กําเนิดบุตรชื่ออุสซาห์ และอาหิฮูด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 8, 'และชาหะราอิมให้กําเนิดบุตรในดินแดนโมอับ ภายหลังจากที่เขาได้ไล่หุชิมและบาอาราภรรยาของเขาไปแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 9, 'เขาให้กําเนิดบุตรกับโฮเดชภรรยาของเขาคือ โยบับ ศิเบีย เมชา มัลคาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 10, 'เยอูส สาเคีย และมิรมาห์ เหล่านี้เป็นบุตรชายของเขา เป็นหัวหน้าบรรพบุรุษของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 11, 'เขาให้กําเนิดบุตรกับหุชิมด้วยคือ อาบีทูบ และเอลปาอัล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 12, 'บุตรชายของเอลปาอัลคือ เอเบอร์ มิชอัม และเชเมด ผู้สร้างเมืองโอโน และเมืองโลดพร้อมกับหัวเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 13, 'และเบรียาห์ และเชมา เขาทั้งหลายเป็นหัวหน้าบรรพบุรุษของชาวเมืองอัยยาโลน ผู้ซึ่งขับไล่ชาวเมืองกัทไปเสียนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 14, 'และอาหิโย ชาชัก และเยรีโมท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 15, 'เศบาดิยาห์ อาราด เอเดอร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 16, 'มีคาเอล อิชปาห์ และโยฮาเป็นบุตรชายของเบรียาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 17, 'เศบาดิยาห์ เมชุลลาม ฮิสคี เฮเบอร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 18, 'อิชเมรัย ยิสลิยาห์และโยบับเป็นบุตรชายของเอลปาอัล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 19, 'ยาคิม ศิครี ศับดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 20, 'เอลีเยนัย ศิลเลธัย เอลีเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 21, 'อาดายาห์ เบไรอาห์ และชิมราทเป็นบุตรชายของชิเมอี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 22, 'อิชปาน เอเบอร์ เอลีเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 23, 'อับโดน ศิครี ฮานัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 24, 'ฮานันยาห์ เอลาม อันโธธียาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 25, 'อิฟไดยาห์ และเปนูเอลเป็นบุตรชายของชาชัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 26, 'ชัมเชรัย เชหะรียาห์ อาธาลิยาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 27, 'ยาอาเรชียาห์ เอลียาห์ และศิครี เป็นบุตรชายของเยโรฮัม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 28, 'คนเหล่านี้เป็นหัวหน้าบรรพบุรุษของเขา ตามพงศ์พันธุ์ของเขา เป็นชั้นหัวหน้า คนเหล่านี้อยู่ในเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 29, 'และในกิเบโอนก็มีบิดาของกิเบโอนอาศัยอยู่ และภรรยาของท่านชื่อมาอาคาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 30, 'บุตรชายหัวปีของท่านชื่ออับโดน แล้วก็มี ศูร์ คีช บาอัล นาดับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 31, 'เกโดร์ อาหิโย เศเคอร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 32, 'และมิกโลทให้กําเนิดบุตรชื่อชิเมอาห์ คนเหล่านี้อาศัยอยู่ตรงข้ามกับญาติของเขาในเยรูซาเล็มด้วย เขาอยู่กับญาติของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 33, 'เนอร์ให้กําเนิดบุตรชื่อคีช คีชให้กําเนิดบุตรชื่อซาอูล ซาอูลให้กําเนิดบุตรชื่อโยนาธาน มัลคีชูวา อาบีนาดับ และเอชบาอัล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 34, 'และบุตรชายของโยนาธานคือ เมริบบาอัล และเมริบบาอัลให้กําเนิดบุตรชื่อมีคาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 35, 'บุตรชายของมีคาห์คือ ปีโธน เมเลค ทาเรีย และอาหัส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 36, 'และอาหัสให้กําเนิดบุตรชื่อเยโฮอัดดาห์ และเยโฮอัดดาห์ให้กําเนิดบุตรชื่ออาเลเมท อัสมาเวทและศิมรี ศิมรีให้กําเนิดบุตรชื่อโมซา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 37, 'โมซาให้กําเนิดบุตรชื่อบิเนอา บุตรชายของบิเนอาคือราฟา บุตรชายของราฟาคือเอเลอาสาห์ บุตรชายของเอเลอาสาห์คืออาเซล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 38, 'อาเซลมีบุตรชายหกคน และต่อไปนี้เป็นชื่อของเขา อัสรีคัม โบเครู อิชมาเอล เชอาริยาห์ โอบาดีห์ และฮานัน ทั้งหมดนี้เป็นบุตรชายของอาเซล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 39, 'บุตรชายของเอเชกน้องชายของเขาคือ อุลามบุตรหัวปีของเขา เยฮูชคนที่สอง และเอลีเฟเลทคนที่สาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 40, 'บุตรชายของอุลามเป็นคนที่เป็นทแกล้วทหาร นักธนู มีลูกหลานมากหนึ่งร้อยห้าสิบคน คนเหล่านี้ทั้งสิ้นเป็นลูกหลานของเบนยามิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 1, 'ดังนั้นอิสราเอลทั้งปวงได้ขึ้นทะเบียนไว้ในสํามะโนครัวเชื้อสาย และดูเถิด ทะเบียนนี้ก็บันทึกไว้ในหนังสือของกษัตริย์แห่งอิสราเอลและยูดาห์ ผู้ถูกกวาดไปเป็นเชลยในบาบิโลนเพราะการละเมิดของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 2, 'ฝ่ายพวกแรกที่เข้ามาอาศัยในที่กรรมสิทธิ์ของเขาอีกในบรรดาหัวเมืองของเขานั้น คืออิสราเอล พวกปุโรหิต พวกเลวี และพวกคนใช้ประจําพระวิหาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 3, 'และในเยรูซาเล็มมีประชาชนบางคนในพวกยูดาห์ พวกเบนยามิน พวกเอฟราอิม และพวกมนัสเสห์ ได้อาศัยอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 4, 'คืออุธัยเป็นบุตรชายอัมมีฮูด ผู้เป็นบุตรชายอมรี ผู้เป็นบุตรชายอิมรี ผู้เป็นบุตรชายบานี ในพวกบุตรเปเรศ ผู้เป็นบุตรชายยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 5, 'และจากคนชีโลห์คือ อาสายาห์บุตรหัวปี และบุตรชายของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 6, 'จากบุตรชายของเศ-ราห์คือ เยอูเอล กับญาติของเขาเป็นหกร้อยเก้าสิบคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 7, 'จากลูกหลานของเบนยามินคือ สัลลู ผู้เป็นบุตรชายเมชุลลาม ผู้เป็นบุตรชายโฮดาวิยาห์ ผู้เป็นบุตรชายหัสเสนูอาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 8, 'อิบเนยาห์บุตรชายเยโรฮัม เอลาห์บุตรชายอุสซี ผู้เป็นบุตรชายมิครี และเมชุลลามบุตรชายเชฟาทิยาห์ ผู้เป็นบุตรชายเรอูเอล ผู้เป็นบุตรชายอิบนียาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 9, 'และญาติของเขาตามพงศ์พันธุ์ของเขา เป็นเก้าร้อยห้าสิบหกคน ทั้งสิ้นนี้เป็นประมุขของบรรพบุรุษตามเรือนบรรพบุรุษของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 10, 'จากพวกปุโรหิตมี เยดายาห์ เยโฮยาริบ ยาคีน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 11, 'และอาซาริยาห์ ผู้เป็นบุตรชายฮิลคียาห์ ผู้เป็นบุตรชายเมชุลลาม ผู้เป็นบุตรชายศาโดก ผู้เป็นบุตรชายเมราโยท ผู้เป็นบุตรชายอาหิทูบ เจ้าหน้าที่ปกครองของพระนิเวศแห่งพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 12, 'และอาดายาห์ ผู้เป็นบุตรชายเยโรฮัม ผู้เป็นบุตรชายปาชเฮอร์ ผู้เป็นบุตรชายมัลคิยาห์ และมาอาสัย ผู้เป็นบุตรชายอาดีเอล ผู้เป็นบุตรชายยาเซราห์ ผู้เป็นบุตรชายเมชุลลาม ผู้เป็นบุตรชายเมชิลเลมิท ผู้เป็นบุตรชายอิมเมอร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 13, 'และญาติของเขา หัวหน้าเรือนบรรพบุรุษของเขา รวมเป็นหนึ่งพันเจ็ดร้อยหกสิบคน เป็นคนสามารถมากที่จะทํางานปรนนิบัติในพระนิเวศของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 14, 'จากคนเลวีมี เชไมอาห์ ผู้เป็นบุตรชายหัสชูบ ผู้เป็นบุตรชายอัสรีคัม ผู้เป็นบุตรชายฮาชาบิยาห์ ลูกหลานของเมรารี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 15, 'กับบัคบัคคาร์ เฮเรช กาลาล และมัทธานิยาห์ ผู้เป็นบุตรชายมีคาห์ ผู้เป็นบุตรชายศิครี ผู้เป็นบุตรชายอาสาฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 16, 'และโอบาดีห์ ผู้เป็นบุตรชายเชไมอาห์ ผู้เป็นบุตรชายกาลาล ผู้เป็นบุตรชายเยดูธูน และเบเรคิยาห์ ผู้เป็นบุตรชายอาสา ผู้เป็นบุตรชายเอลคานาห์ ผู้อาศัยอยู่ในชนบทของชาวเนโทฟาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 17, 'ผู้เฝ้าประตูคือ ชัลลูม อักขูบ ทัลโมน อาหิมาน และญาติของเขา ชัลลูมเป็นหัวหน้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 18, 'ประจําอยู่จนบัดนี้ที่พระทวารของกษัตริย์ทางด้านตะวันออก คนเหล่านี้เป็นผู้เฝ้าประตูค่ายของคนเลวี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 19, 'ชัลลูมเป็นบุตรชายโคเร ผู้เป็นบุตรชายเอบียาสาฟ ผู้เป็นบุตรชายโคราห์ และญาติของเขาคือเรือนบรรพบุรุษของเขา คือคนโคราห์ เป็นผู้ดูแลการงานปรนนิบัติ เป็นผู้เฝ้าธรณีประตูของพลับพลา ดังบรรพบุรุษของเขา เป็นผู้ดูแลค่ายของพระเยโฮวาห์ เป็นผู้ดูแลทางเข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 20, 'และฟีเนหัสบุตรชายเอเลอาซาร์ เป็นผู้ครอบครองเหนือเขาในกาลก่อน พระเยโฮวาห์ทรงสถิตกับเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 21, 'เศคาริยาห์ บุตรชายเมเชเลมิยาห์ เป็นผู้เฝ้าทางเข้าประตูพลับพลาแห่งชุมนุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 22, 'ผู้ถูกเลือกเป็นผู้เฝ้าประตูที่ธรณีนั้นมีสองร้อยสิบสองคน เขาขึ้นทะเบียนสํามะโนครัวเชื้อสายไว้ในชนบทของเขา ดาวิดและซามูเอลผู้ทํานายได้สถาปนาเขาไว้ในตําแหน่งหน้าที่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 23, 'ดังนั้นเขาและลูกหลานของเขาจึงเป็นผู้ดูแลประตูรั้วพระนิเวศของพระเยโฮวาห์ เป็นผู้เฝ้าประตูรั้วพระนิเวศแห่งพลับพลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 24, 'ผู้ดูแลประตูรั้วอยู่ทั้งสี่ด้าน คือด้านตะวันออก ตะวันตก เหนือ และใต้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 25, 'และญาติของเขาซึ่งอยู่ในชนบทของเขาต้องเข้ามาทุกๆเจ็ดวัน ตามเวลากําหนดเพื่อจะอยู่กับคนเหล่านี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 26, 'เพราะนายประตูรั้วทั้งสี่คน ผู้เป็นพวกเลวีนั้น มีตําแหน่งหน้าที่เป็นผู้ดูแลห้องและคลังของพระนิเวศแห่งพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 27, 'และเขาพักอาศัยอยู่รอบพระนิเวศของพระเจ้า เพราะหน้าที่เฝ้าตกอยู่กับเขา และเขามีหน้าที่เปิดทุกเช้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 28, 'บางคนเป็นคนดูแลเครื่องใช้ในการปรนนิบัติ เพราะว่าจะเบิกออกไปหรือส่งเข้ามาต้องนับทุกครั้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 29, 'และบางคนถูกแต่งตั้งให้ดูแลภาชนะ และดูแลเครื่องใช้ของสถานบริสุทธิ์ทั้งสิ้น ดูแลยอดแป้ง น้ําองุ่น น้ํามัน กํายาน และเครื่องเทศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 30, 'และบางคนซึ่งเป็นลูกหลานของปุโรหิตก็เตรียมเครื่องเทศประสม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 31, 'และมัททีธิยาห์คนเลวีคนหนึ่ง ผู้เป็นบุตรหัวปีของชัลลูม คนโคราห์ มีตําแหน่งหน้าที่เป็นผู้ดูแลสิ่งที่ปิ้งในถาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 32, 'และญาติของเขาบางคน ซึ่งเป็นคนโคฮาท เป็นผู้ดูแลขนมปังหน้าพระพักตร์ มีหน้าที่จัดเตรียมทุกวันสะบาโต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 33, 'ต่อไปนี้เป็นนักร้อง คือประมุขของบรรพบุรุษคนเลวี ผู้อาศัยอยู่ในห้องในพระวิหารไม่ต้องทําการปรนนิบัติอย่างอื่น เพราะเขาอยู่เวรทั้งกลางวันและกลางคืน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 34, 'คนเหล่านี้เป็นบรรดาหัวหน้าของคนเลวี ตามพงศ์พันธุ์ของเขาเป็นชั้นหัวหน้า คนเหล่านี้อาศัยอยู่ที่เยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 35, 'ในกิเบโอนนั้นเยฮีเอลบิดาของกิเบโอนอาศัยอยู่ และภรรยาของท่านชื่อมาอาคาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 36, 'และบุตรชายหัวปีของท่านชื่อ อับโดน แล้วก็มี ศูร์ คีช บาอัล เนอร์ นาดับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 37, 'เกโดร์ อาหิโย เศคาริยาห์ และมิกโลท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 38, 'และมิกโลทให้กําเนิดบุตรชื่อชิเมอัม และคนเหล่านี้อาศัยอยู่ตรงข้ามกับญาติของเขาในเยรูซาเล็มด้วย อยู่กับญาติของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 39, 'เนอร์ให้กําเนิดบุตรชื่อคีช คีชให้กําเนิดบุตรชื่อซาอูล ซาอูลให้กําเนิดบุตรชื่อโยนาธาน มัลคีชูวา อาบีนาดับ และเอชบาอัล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 40, 'บุตรชายของโยนาธานชื่อเมริบบาอัล และเมริบบาอัลให้กําเนิดบุตรชื่อมีคาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 41, 'บุตรชายของมีคาห์คือ ปีโธน เมเลค ทาเรีย และอาหัส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 42, 'และอาหัสให้กําเนิดบุตรชื่อยาราห์ และยาราห์ให้กําเนิดบุตรชื่ออาเลเมท อัสมาเวท และศิมรี และศิมรีให้กําเนิดบุตรชื่อโมซา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 43, 'โมซาให้กําเนิดบุตรชื่อบิเนอา และบุตรชายของบิเนอาคือเรไฟยาห์ บุตรชายของเรไฟยาห์คือเอเลอาสาห์ บุตรชายของเอเลอาสาห์คืออาเซล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 44, 'อาเซลมีบุตรชายหกคน และต่อไปนี้เป็นชื่อของเขาทั้งหลายคือ อัสรีคัม โบเครู อิชมาเอล เชอาริยาห์ โอบาดีห์ และฮานัน เหล่านี้เป็นบุตรชายของอาเซล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 1, 'คนฟีลิสเตียได้สู้กับคนอิสราเอล และคนอิสราเอลก็หนีไปให้พ้นหน้าคนฟีลิสเตียล้มตายอยู่ที่บนภูเขากิลโบอา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 2, 'และคนฟีลิสเตียก็ไล่ทันซาอูลกับพวกราชโอรส และคนฟีลิสเตียก็ฆ่าโยนาธาน อาบีนาดับ และมัลคีชูวา ราชโอรสของซาอูลเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 3, 'การรบหนักก็ประชิดซาอูลเข้าไป และนักธนูมาพบพระองค์เข้า พระองค์ก็ทรงบาดเจ็บสาหัสด้วยฝีมือของนักธนู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 4, 'แล้วซาอูลรับสั่งคนถืออาวุธของพระองค์ว่า “จงชักดาบออก แทงเราเสียให้ทะลุเถิด เกรงว่าคนที่มิได้เข้าสุหนัตเหล่านี้จะเข้ามาทําลบหลู่แก่เรา” แต่ผู้ถืออาวุธไม่ยอมกระทําตาม เพราะเขากลัวมาก ซาอูลจึงทรงชักดาบของพระองค์ออก ทรงล้มทับดาบนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 5, 'และเมื่อผู้ถืออาวุธเห็นว่าซาอูลสิ้นพระชนม์แล้ว เขาก็ล้มทับดาบของเขาตายด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 6, 'ดังนั้นซาอูลก็สิ้นพระชนม์พร้อมกับราชโอรสทั้งสามของพระองค์ และราชวงศ์ทั้งสิ้นของพระองค์ก็ตายด้วยกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 7, 'เมื่อบรรดาคนอิสราเอลผู้อยู่ในหุบเขาเห็นว่ากองทัพหนีไป และซาอูลกับโอรสของพระองค์ก็สิ้นพระชนม์แล้ว เขาก็ทิ้งบ้านเมืองของเขาและหลบหนีไป คนฟีลิสเตียก็เข้ามาอาศัยอยู่ในนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 8, 'อยู่มาวันรุ่งขึ้น เมื่อคนฟีลิสเตียมาปลดเสื้อผ้าจากคนที่ถูกฆ่า เขาพบพระศพซาอูลและราชโอรสทั้งสามอยู่บนภูเขากิลโบอา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 9, 'เขาก็ถอดเครื่องทรงของพระองค์ เอาพระเศียรและอาวุธของพระองค์ไป และส่งผู้สื่อสารไปทั่วดินแดนฟีลิสเตีย ให้นําข่าวดีไปยังรูปเคารพและประชาชนของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 10, 'เขาเอาเครื่องอาวุธของพระองค์ไปไว้ในวิหารพระของเขา และเอาพระเศียรของพระองค์มัดไว้ในวิหารของพระดาโกน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 11, 'แต่เมื่อชาวยาเบชกิเลอาดทั้งสิ้นได้ยินเรื่องทั้งหมดที่คนฟีลิสเตียได้กระทําแก่ซาอูล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 12, 'ทหารเก่งกล้าทั้งสิ้นก็ลุกขึ้นไปเชิญพระศพของซาอูลและศพโอรสของพระองค์ นํามาที่ยาเบช และเขาก็ฝังพระอัฐินั้นใต้ต้นโอ๊กในยาเบช และได้อดอาหารเจ็ดวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 13, 'ซาอูลจึงสิ้นพระชนม์ด้วยความละเมิดของพระองค์ซึ่งพระองค์กระทําต่อพระเยโฮวาห์ ในเรื่องที่พระองค์มิได้รักษาพระบัญชาของพระเยโฮวาห์ และได้ทรงแสวงหาการนําโดยทรงปรึกษาคนทรงด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 14, 'และมิได้ทรงแสวงหาการนําจากพระเยโฮวาห์ พระเยโฮวาห์จึงทรงสังหารพระองค์เสีย และทรงยกราชอาณาจักรให้แก่ดาวิดบุตรชายเจสซี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 1, 'แล้วคนอิสราเอลทั้งสิ้นก็ชุมนุมอยู่ด้วยกันเฝ้าดาวิดที่เมืองเฮโบรนทูลว่า “ดูเถิด ข้าพระองค์ทั้งหลายเป็นกระดูกและเนื้อของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 2, 'ในกาลก่อน แม้เมื่อซาอูลทรงเป็นกษัตริย์ พระองค์ทรงเป็นผู้นําอิสราเอลออกไปและเข้ามา และพระเยโฮวาห์พระเจ้าของพระองค์ตรัสแก่พระองค์ว่า ‘เจ้าจะเลี้ยงดูอิสราเอลประชาชนของเรา และเจ้าจะเป็นเจ้าเหนืออิสราเอลประชาชนของเรา’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 3, 'ดังนั้นพวกผู้ใหญ่ทั้งสิ้นของคนอิสราเอลก็มาเฝ้ากษัตริย์ที่เมืองเฮโบรน และดาวิดทรงกระทําพันธสัญญากับเขาทั้งหลายที่เมืองเฮโบรนต่อพระพักตร์พระเยโฮวาห์ และเขาทั้งหลายก็เจิมตั้งดาวิดให้เป็นกษัตริย์เหนืออิสราเอล ตามพระวจนะของพระเยโฮวาห์โดยซามูเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 4, 'ดาวิดและคนอิสราเอลทั้งสิ้นไปยังเยรูซาเล็ม คือเยบุส ที่นั่นคนเยบุสอยู่ ซึ่งเป็นชาวแผ่นดินนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 5, 'ชาวเมืองเยบุสทูลดาวิดว่า “พระองค์จะเสด็จเข้ามาที่นี่ไม่ได้” อย่างไรก็ดี ดาวิดทรงยึดที่กําบังเข้มแข็งแห่งศิโยนไว้ คือนครของดาวิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 6, 'ดาวิดรับสั่งว่า “ผู้ใดที่โจมตีคนเยบุสได้ก่อนจะได้เป็นหัวหน้าและผู้บังคับบัญชา” และโยอาบบุตรชายของนางเศรุยาห์ได้ยกขึ้นไปก่อน ท่านจึงได้เป็นหัวหน้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 7, 'และดาวิดทรงประทับอยู่ในที่กําบังเข้มแข็ง เพราะฉะนั้นเขาจึงเรียกว่า นครของดาวิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 8, 'และพระองค์ทรงสร้างเมืองรอบ ตั้งแต่มิลโลโดยรอบ และโยอาบก็ซ่อมส่วนที่เหลือของเมืองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 9, 'และดาวิดทรงจําเริญยิ่งๆขึ้น เพราะว่าพระเยโฮวาห์จอมโยธาทรงสถิตกับพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 10, 'ต่อไปนี้เป็นคนที่เด่นในพวกวีรบุรุษของดาวิด ผู้สนับสนุนพระองค์อย่างแข็งแรงในราชอาณาจักรของพระองค์ ด้วยกันกับอิสราเอลทั้งสิ้น เชิญพระองค์ให้เป็นกษัตริย์ ตามพระวจนะของพระเยโฮวาห์เกี่ยวด้วยเรื่องอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 11, 'ต่อไปนี้เป็นจํานวนวีรบุรุษของดาวิด คือ ยาโชเบอัม คนฮักโมนี เป็นหัวหน้าพวกผู้บังคับบัญชา เขายกหอกของเขาสู้คนสามร้อย และฆ่าเสียในคราวเดียวกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 12, 'และในวีรบุรุษทั้งสาม คนที่ถัดเขาไปคือเอเลอาซาร์ บุตรชายโดโด คนอาโหอาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 13, 'เขาอยู่กับดาวิดที่ปัสดัมมิม เมื่อคนฟีลิสเตียชุมนุมกันทําสงครามที่นั่น มีที่ดินแปลงหนึ่งมีข้าวบาร์เลย์เต็มไปหมด และคนทั้งหลายก็หนีไปให้พ้นหน้าคนฟีลิสเตีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 14, 'แต่พวกเขายืนหยัดอยู่ท่ามกลางที่ดินแปลงนั้น และป้องกันมันไว้ ได้ฆ่าคนฟีลิสเตียเสีย และพระเยโฮวาห์ทรงช่วยเขาทั้งหลายให้พ้นด้วยชัยชนะอันยิ่งใหญ่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 15, 'สามคนในพวกทหารเอกทั้งสามสิบคนนั้นได้ลงไปถึงศิลาหาดาวิดที่ถ้ําอดุลลัม เมื่อกองทัพของคนฟีลิสเตียตั้งค่ายอยู่ที่หุบเขาเรฟาอิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 16, 'คราวนั้นดาวิดอยู่ในที่กําบังเข้มแข็ง และทหารประจําป้อมของคนฟีลิสเตียอยู่ที่เบธเลเฮม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 17, 'ดาวิดตรัสด้วยความอาลัยว่า “โอ ใครหนอจะส่งน้ําจากบ่อที่เบธเลเฮมซึ่งอยู่ข้างประตูเมืองมาให้เราดื่มได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 18, 'แล้วคนทั้งสามก็แหกค่ายของคนฟีลิสเตียเข้าไป และตักน้ํามาจากบ่อเบธเลเฮมที่ข้างประตูเมือง นําเอามาถวายดาวิด แต่ดาวิดหาทรงดื่มน้ํานั้นไม่ พระองค์ทรงเทออกถวายแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 19, 'ตรัสว่า “ขอพระเจ้าของข้าทรงห้ามข้าไม่ให้กระทําอย่างนี้ ควรหรือที่ข้าจะดื่มโลหิตของคนเหล่านี้ผู้ที่เสี่ยงชีวิตของเขา เพราะด้วยการเสี่ยงชีวิตของเขาเอง เขาได้เอาน้ํานี้มา” เพราะฉะนั้นพระองค์จึงหาทรงดื่มไม่ ทแกล้วทหารสามคนนั้นได้กระทําสิ่งนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 20, 'ฝ่ายอาบีชัยน้องชายของโยอาบเป็นหัวหน้าของทั้งสามคนนั้น ท่านได้ยกหอกของท่านสู้คนสามร้อย และฆ่าเสีย และได้รับชื่อเสียงดังวีรบุรุษสามคนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 21, 'ในสามคนนั้นท่านมีชื่อเสียงมากกว่าอีกสองคนนั้น และได้เป็นผู้บังคับบัญชาของเขา แต่ท่านไม่มียศเท่ากับสามคนแรกนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 22, 'และเบไนยาห์บุตรชายเยโฮยาดา เป็นบุตรชายของคนเก่งกล้าแห่งเมืองขับเซเอล เป็นคนประกอบมหกิจ เขาได้ฆ่าคนดุจสิงโตของโมอับเสียสองคน เขาลงไปฆ่าสิงโตที่ในบ่อในวันที่หิมะตกด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 23, 'เขาได้ฆ่าคนอียิปต์คนหนึ่ง เป็นชายรูปร่างใหญ่โต สูงห้าศอก คนอียิปต์นั้นถือหอกเหมือนไม้กระพั่นทอผ้า แต่เบไนยาห์ถือไม้เท้าลงไปหาเขา และแย่งเอาหอกมาจากมือของคนอียิปต์ และฆ่าเขาเสียด้วยหอกของเขาเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 24, 'สิ่งเหล่านี้เบไนยาห์บุตรชายเยโฮยาดาได้กระทํา และได้ชื่อเสียงในหมู่พวกทแกล้วทหารสามคนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 25, 'ดูเถิด เขามีชื่อเสียงโด่งดังกว่าสามสิบคนนั้น แต่เขาไม่มียศเท่ากับสามคนแรกนั้น และดาวิดได้ทรงแต่งเขาให้เป็นผู้บังคับบัญชาทหารรักษาพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 26, 'นอกนั้นมีพวกทแกล้วทหารของกองทัพคือ อาสาเฮลน้องชายของโยอาบ เอลฮานันบุตรชายของโดโดชาวเบธเลเฮม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 27, 'ชัมโมทชาวเมืองฮาโรร์ เฮเลสคนเปโลน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 28, 'อิราบุตรชายอิกเขชชาวเมืองเทโคอา อาบีเยเซอร์ชาวเมืองอานาโธท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 29, 'สิบเบคัย คนหุชาห์ อิลัย คนอาโหอาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 30, 'มาหะรัย ชาวเนโทฟาห์ เฮเลด บุตรชายบาอานาห์ชาวเนโทฟาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 31, 'อิธัย บุตรชายรีบัยแห่งเมืองกิเบอาห์ของคนเบนยามิน เบไนยาห์ ชาวปิราโธน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 32, 'หุรัย ชาวลําธารกาอัช อาบีเอล คนอารบาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 33, 'อัสมาเวท คนบาฮูริม เอลียาบา ชาวชาอัลโบน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 34, 'ลูกหลานฮาเชมคนกีโซน โยนาธาน บุตรชายชากีชาวฮาราร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 35, 'อาหิยัม บุตรชายสาคาร์ชาวฮาราร์ เอลีฟัล บุตรชายเออร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 36, 'เฮเฟอร์ คนเมเค-ราไธด์ อาหิยาห์ คนเปโลน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 37, 'เฮสโร ชาวคารเมล นาอารัย บุตรชายเอสบัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 38, 'โยเอล น้องชายนาธัน มิบฮาร์ บุตรชายฮากรี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 39, 'เศเลก คนอัมโมน นาหะรัย ชาวเบเอโรท ผู้ถืออาวุธของโยอาบบุตรชายนางเศรุยาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 40, 'อิรา คนอิทไรต์ กาเรบ คนอิทไรต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 41, 'อุรีอาห์ คนฮิตไทต์ ศาบาด บุตรชายอัคลัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 42, 'อาดีนา บุตรชายชิซาคนรูเบน หัวหน้าคนหนึ่งของคนรูเบน และสามสิบคนด้วยกันกับเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 43, 'ฮานัน บุตรชายมาอาคาห์ และโยชาฟัท คนมิทเน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 44, 'อุสชียา ชาวอัชทาโรท ซามาและเยฮีเอล บุตรชายโฮธามคนอาโรเออร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 45, 'เยดียาเอล บุตรชายชิมรี และโยฮา น้องชายของเขา ชาวทิไซต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 46, 'เอลีเอล คนมาหะไวต์ เยรีบัยและโยชาวิยาห์ บุตรชายเอลนาอัม และอิทมาห์ คนโมอับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 47, 'เอลีเอล โอเบด และยาอาสีเอล คนเมโซบัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 1, 'ต่อไปนี้เป็นคนที่มาหาดาวิดที่ศิกลาก ขณะเมื่อท่านไปไหนไม่ได้สะดวกเพราะเหตุซาอูลบุตรชายคีช เขาทั้งหลายเป็นคนในพวกทแกล้วทหาร ผู้ช่วยท่านในการรบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 2, 'เขาเป็นนักธนู เขาเหวี่ยงหินด้วยสลิงและยิงธนูได้ด้วยมือขวาหรือมือซ้าย เขาเป็นคนเบนยามิน ญาติของซาอูล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 3, 'อาหิเยเซอร์เป็นหัวหน้า ถัดไปคือโยอาช บุตรชายของเชมาอาห์ชาวเมืองกิเบอัท และเยซีเอลกับเปเลธ บุตรชายของอัสมาเวท เบราคาห์และเยฮูชาวอานาโธท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 4, 'อิชมัยยาห์แห่งกิเบโอน ทแกล้วทหารในพวกสามสิบคนนั้น และเป็นหัวหน้าเหนือสามสิบคนนั้น เยเรมีย์ ยาฮาซีเอล โยฮานัน โยซาบาดชาวเมืองเกเดราห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 5, 'เอลูซัย เยรีโมท เบอัลยาห์ เชมาริยาห์ เชฟาทิยาห์คนฮารูฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 6, 'เอลคานาห์ อิสชีอาห์ อาซาเรล โยเอเซอร์ ยาโชเบอัม คนโคราห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 7, 'และโยเอลาห์ กับ เศบาดิยาห์ บุตรชายของเยโรฮัมชาวเกโดร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 8, 'มีทแกล้วทหารและผู้ชํานาญศึกจากคนกาดหนีเข้าไปหาดาวิด ณ ที่กําบังเข้มแข็งในถิ่นทุรกันดาร เขาชํานาญโล่และดั้ง ผู้ซึ่งหน้าของเขาเหมือนหน้าสิงโต และผู้ซึ่งรวดเร็วเหมือนละมั่งบนภูเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 9, 'เอเซอร์เป็นหัวหน้า โอบาดีห์ที่สอง เอลีอับที่สาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 10, 'มิชมันนาห์ที่สี่ เยเรมีย์ที่ห้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 11, 'อัททัยที่หก เอลีเอลที่เจ็ด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 12, 'โยฮานันที่แปด เอลซาบาดที่เก้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 13, 'เยเรมีย์ที่สิบ มัคบันนัยที่สิบเอ็ด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 14, 'คนเหล่านี้เป็นบุตรชายของกาด เป็นนายทหารในกองทัพ ผู้น้อยก็เป็นนายร้อย ผู้ใหญ่ก็เป็นนายพัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 15, 'เหล่านี้เป็นคนที่ข้ามแม่น้ําจอร์แดนในเดือนแรก เมื่อน้ําท่วมฝั่งทั้งสิ้น และให้คนที่อยู่ ณ ลุ่มแม่น้ําแตกหนีไปทางทิศตะวันออกและทิศตะวันตก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 16, 'มีคนเบนยามินและยูดาห์มาเฝ้าดาวิด ณ ที่กําบังเข้มแข็ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 17, 'ดาวิดทรงออกไปต้อนรับเขา และตรัสกับเขาว่า “ถ้าท่านทั้งหลายมาฉันมิตรเพื่อช่วยข้าพเจ้า จิตใจของข้าพเจ้าจะพันผูกติดกับท่าน แต่ถ้ามาเพื่อขายข้าพเจ้าให้แก่ปฏิปักษ์ของข้าพเจ้า แม้ว่าในมือของข้าพเจ้าไม่มีความผิดใดๆ ก็ขอพระเจ้าแห่งบรรพบุรุษของเราทั้งหลายทอดพระเนตร และทรงกล่าวโทษท่านทั้งหลายเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 18, 'แล้วพระวิญญาณได้มาเหนืออามาสัย หัวหน้าพวกผู้บังคับบัญชานั้น และเขาทูลว่า “ข้าแต่ดาวิด ข้าพระองค์ทั้งหลายเป็นของพระองค์ และอยู่กับพระองค์ ข้าแต่บุตรเจสซี สันติภาพ สันติภาพจงมีแก่พระองค์ และสันติภาพจงมีแก่ผู้ช่วยของพระองค์ เพราะว่าพระเจ้าของพระองค์ทรงอุปถัมภ์พระองค์” แล้วดาวิดทรงรับเขาทั้งหลายไว้ และทรงตั้งให้เป็นนายทหารในกองทัพของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 19, 'คนมนัสเสห์ด้วยได้หลบหนีไปเข้าฝ่ายดาวิดบ้าง เมื่อพระองค์ยกมากับคนฟีลิสเตียเพื่อทําสงครามกับซาอูล แต่พวกฝ่ายดาวิดมิได้ช่วยคนฟีลิสเตีย เพราะผู้ครอบครองของคนฟีลิสเตียได้หารือกันและส่งพระองค์กลับไปเสีย บอกว่า “เขาจะหลบหนีไปคืนดีกับซาอูลนายของเขาโดยเอาหัวของเราไปด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 20, 'ขณะเมื่อพระองค์ไปยังศิกลาก คนมนัสเสห์เหล่านี้หลบหนีไปสมทบพระองค์ คือ อัดนาห์ โยซาบาด เยดียาเอล มีคาเอล โยซาบาด เอลีฮู และศิลเลธัย หัวหน้าบรรดากองพันในคนมนัสเสห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 21, 'เขาทั้งหลายช่วยเหลือดาวิดต่อสู้พวกปล้น เพราะเขาทั้งหลายเป็นทแกล้วทหารทั้งสิ้น และเป็นผู้บังคับบัญชาในกองทัพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 22, 'ในสมัยนั้นทุกๆวันมีคนมาเข้าฝ่ายดาวิด เพื่อจะช่วยเหลือพระองค์ จนเป็นกองทัพใหญ่อย่างกองทัพของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 23, 'ต่อไปนี้เป็นจํานวนทหารติดอาวุธพร้อมสําหรับสงคราม ผู้มาหาดาวิดในเมืองเฮโบรนเพื่อจะมอบราชอาณาจักรของซาอูลให้กับพระองค์ ตามพระวจนะของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 24, 'คนยูดาห์ที่ถือโล่และหอกมีหกพันแปดร้อย เป็นทหารติดอาวุธพร้อมสําหรับสงคราม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 25, 'จากคนสิเมโอน มีทแกล้วทหารชํานาญศึกเจ็ดพันหนึ่งร้อย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 26, 'จากคนเลวีสี่พันหกร้อย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 27, 'เยโฮยาดาเป็นหัวหน้าคนของอาโรน มีคนมากับท่านสามพันเจ็ดร้อย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 28, 'ศาโดกทแกล้วทหารหนุ่ม และคนจากเรือนบรรพบุรุษของเขาเองเป็นผู้บังคับบัญชายี่สิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 29, 'จากคนเบนยามินญาติของซาอูลสามพันคน ซึ่งแต่ก่อนนี้จํานวนมากจงรักภักดีต่อราชวงศ์ซาอูล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 30, 'จากคนเอฟราอิม ทแกล้วทหารแกล้วกล้าสองหมื่นแปดร้อยคน เป็นคนมีชื่อเสียงในเรือนบรรพบุรุษของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 31, 'จากคนมนัสเสห์ครึ่งตระกูล หนึ่งหมื่นแปดพันคน ผู้ซึ่งเขาบ่งชื่อไว้ให้มาเชิญดาวิดไปเป็นกษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 32, 'จากคนอิสสาคาร์ มีผู้รู้กาลเทศะ ทราบว่าอิสราเอลควรทําประการใด มีหัวหน้าสองร้อยคน และญาติของเขาทั้งสิ้นอยู่ใต้บังคับบัญชาของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 33, 'จากคนเศบูลุน มีห้าหมื่นคนที่ฝึกแล้วเตรียมพร้อมเข้าสู้รบ พร้อมสรรพด้วยอาวุธทุกอย่างเพื่อทําสงครามเพื่อช่วยเหลือ มิใช่ด้วยสองจิตสองใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 34, 'จากคนนัฟทาลี ผู้บังคับบัญชาหนึ่งพัน ซึ่งมีคนติดโล่และหอกมาด้วยสามหมื่นเจ็ดพันคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 35, 'จากคนดาน มีคนเตรียมพร้อมทําสงครามสองหมื่นแปดพันหกร้อยคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 36, 'จากคนอาเชอร์ สี่หมื่นคนฝึกพร้อมที่จะทําสงคราม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 37, 'และจากฟากแม่น้ําจอร์แดนข้างโน้น จากคนรูเบน และคนกาด และคนมนัสเสห์ครึ่งตระกูล มีหนึ่งแสนสองหมื่นคน ติดอาวุธทุกอย่างเพื่อทําสงคราม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 38, 'ทหารทั้งสิ้นเหล่านี้ พร้อมที่จะทําศึก ได้มายังเฮโบรน ด้วยเจตนาเต็มเปี่ยมที่จะเชิญดาวิดเป็นกษัตริย์เหนืออิสราเอลทั้งสิ้น ในทํานองเดียวกันบรรดาคนอิสราเอลที่เหลืออยู่ ก็เป็นใจเดียวกันที่จะเชิญดาวิดเป็นกษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 39, 'เขาทั้งหลายอยู่ที่นั่นกับดาวิดสามวันกินและดื่ม เพราะว่าพี่น้องของเขาได้เตรียมไว้ให้เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 40, 'ยิ่งกว่านั้นผู้ที่อยู่ใกล้เขาทั้งหลายด้วยคือไกลออกไปถึงอิสสาคาร์ และเศบูลุน และนัฟทาลีได้จัดอาหารบรรทุกลา อูฐ ล่อ และวัว กับเสบียงอาหารมากมายเป็นแป้ง ขนมมะเดื่อ ช่อองุ่นแห้ง น้ําองุ่น น้ํามัน วัวและแกะ เพราะว่ามีความชื่นบานในอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 1, 'ดาวิดได้ทรงหารือกับนายพันและนายร้อย กับหัวหน้าทุกๆคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 2, 'และดาวิดตรัสกับชุมนุมชนอิสราเอลทั้งปวงว่า “ถ้าท่านทั้งหลายเห็นด้วย และถ้าเป็นน้ําพระทัยของพระเยโฮวาห์พระเจ้าของเรา ก็ให้เราทั้งหลายส่งคนไปหาพี่น้องของเรา ผู้ที่เหลืออยู่ในแผ่นดินอิสราเอลทั้งสิ้น ให้ไปยังปุโรหิตและคนเลวีด้วย ผู้ซึ่งอยู่ในหัวเมืองและทุ่งหญ้าของเขา เพื่อให้เขาทั้งหลายมาหาพวกเราพร้อมกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 3, 'และให้เราทั้งหลายนําหีบแห่งพระเจ้าของเรามายังเราอีก เพราะเราทั้งหลายมิได้ไต่ถามถึงในสมัยของซาอูล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 4, 'ชุมนุมชนทั้งสิ้นนั้นก็พากันกล่าวว่าพวกเขาจะกระทําตาม เพราะสิ่งนั้นเป็นสิ่งที่ถูกต้องในสายตาของประชาชนทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 5, 'เพราะฉะนั้นดาวิดจึงประชุมอิสราเอลทั้งสิ้น ตั้งแต่ชิโหร์แห่งอียิปต์ ถึงทางเข้าเมืองฮามัท เพื่อจะเชิญหีบแห่งพระเจ้าจากคีริยาทเยอาริม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 6, 'ดาวิดกับอิสราเอลทั้งปวงขึ้นไปยังบาอาลาห์ คือคีริยาทเยอาริมซึ่งเป็นของยูดาห์ เพื่อจากที่นั่นจะได้เชิญหีบของพระเจ้าคือพระเยโฮวาห์ ผู้ประทับระหว่างพวกเครูบ อันเป็นหีบที่เรียกกันตามพระนาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 7, 'และเขาทั้งหลายก็บรรทุกหีบของพระเจ้าไปในเกวียนเล่มใหม่จากเรือนของอาบีนาดับ และอุสซาห์กับอาหิโยเป็นคนขับเกวียน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 8, 'และดาวิดกับอิสราเอลทั้งปวงก็ร่าเริงกันอยู่ต่อพระพักตร์พระเจ้าด้วยเต็มกําลังของเขาทั้งหลาย ด้วยเพลง พิณเขาคู่ พิณใหญ่ รํามะนา ฉาบ และแตร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 9, 'และเมื่อเขาทั้งหลายมาถึงลานนวดข้าวของคิโดน อุสซาห์ก็เหยียดมือออกกุมหีบไว้เพราะวัวสะดุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 10, 'และพระพิโรธของพระเยโฮวาห์ได้พลุ่งขึ้นต่ออุสซาห์ และพระองค์ทรงประหารเขา เพราะเขาเหยียดมือออกยังหีบนั้น และเขาก็สิ้นชีวิตต่อพระพักตร์พระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 11, 'และดาวิดก็ไม่ทรงพอพระทัย เพราะพระเยโฮวาห์ทรงทลายออกมาเหนืออุสซาห์ จึงเรียกที่ตรงนั้นว่า เปเรศอุสซาห์ จนถึงทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 12, 'และดาวิดทรงเกรงกลัวพระเจ้าในวันนั้น และพระองค์ตรัสว่า “เราจะนําหีบของพระเจ้าไปบ้านไปเมืองอย่างไรได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 13, 'ดาวิดจึงมิได้ทรงย้ายหีบไปไว้ในนครของดาวิด แต่ทรงนําหีบแวะไปไว้ที่บ้านโอเบดเอโดมคนกัท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 14, 'และหีบของพระเจ้าได้ค้างอยู่กับครัวเรือนของโอเบดเอโดมที่เรือนของเขาสามเดือน และพระเยโฮวาห์ทรงอํานวยพระพรแก่ครัวเรือนของโอเบดเอโดมกับทั้งสิ้นซึ่งเขามีอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 1, 'ฮีรามกษัตริย์เมืองไทระได้ทรงส่งผู้สื่อสารมาเฝ้าดาวิด และทรงส่งไม้สนสีดาร์ ทั้งช่างก่อและช่างไม้เพื่อจะสร้างวังถวายพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 2, 'และดาวิดทรงทราบว่าพระเยโฮวาห์ทรงสถาปนาพระองค์เป็นกษัตริย์เหนืออิสราเอล เพราะพระราชอาณาจักรของพระองค์ก็เป็นที่ยกย่องอย่างยิ่ง เพื่อเห็นแก่อิสราเอลประชาชนของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 3, 'และดาวิดทรงรับมเหสีเพิ่มขึ้นในกรุงเยรูซาเล็ม และดาวิดทรงให้กําเนิดโอรสและธิดาอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 4, 'ต่อไปนี้เป็นชื่อราชบุตรซึ่งพระองค์ทรงมีในเยรูซาเล็มคือ ชัมมูอา โชบับ นาธัน ซาโลมอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 5, 'อิบฮาร์ เอลีชูอา เอลเปเลท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 6, 'โนกาห์ เนเฟก ยาเฟีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 7, 'เอลีชามา เบเอลยาดา เอลีเฟเลท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 8, 'เมื่อคนฟีลิสเตียได้ยินว่าดาวิดทรงรับการเจิมเป็นกษัตริย์เหนืออิสราเอลทั้งปวงแล้ว คนฟีลิสเตียทั้งปวงก็ขึ้นไปแสวงหาดาวิด ดาวิดทรงได้ยินเรื่องนั้นก็เสด็จออกไปสู้รบกับเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 9, 'ฝ่ายคนฟีลิสเตียได้มาปล้นในหุบเขาเรฟาอิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 10, 'และดาวิดก็ทรงทูลถามพระเจ้าว่า “ควรที่ข้าพระองค์จะขึ้นไปต่อสู้ฟีลิสเตียหรือ พระองค์จะทรงมอบเขาไว้ในมือของข้าพระองค์หรือ” และพระเยโฮวาห์ตรัสตอบพระองค์ว่า “ขึ้นไปเถอะ และเราจะมอบเขาไว้ในมือเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 11, 'และพระองค์เสด็จไปยังบาอัลเปราซิม และดาวิดทรงชนะเขาทั้งหลายที่นั่น และดาวิดตรัสว่า “พระเจ้าทรงทะลวงข้าศึกของข้าพเจ้าเหมือนดังกระแสน้ําที่พุ่งใส่” เพราะฉะนั้นเขาจึงเรียกที่นั้นว่า บาอัลเปราซิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 12, 'เขาทั้งหลายก็ทิ้งรูปเคารพของเขาเสียที่นั่น และดาวิดก็ทรงมีพระบัญชา และรูปเคารพเหล่านั้นก็ถูกเผาด้วยไฟเสียหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 13, 'และคนฟีลิสเตียยังมาปล้นในหุบเขานั้นอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 14, 'และเมื่อดาวิดทูลถามพระเจ้าอีกครั้งหนึ่ง พระเจ้าตรัสตอบพระองค์ว่า “เจ้าอย่าขึ้นไปตามเขา จงอ้อมไปและโจมตีเขาที่ตรงข้ามกับหมู่ต้นหม่อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 15, 'และเมื่อเจ้าได้ยินเสียงกระบวนทัพอยู่ที่ยอดหมู่ต้นหม่อนแล้ว จงออกไปทําศึก เพราะว่าพระเจ้าได้เสด็จออกไปข้างหน้าเพื่อโจมตีกองทัพของคนฟีลิสเตีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 16, 'และดาวิดทรงกระทําตามที่พระเจ้าบัญชาแก่พระองค์ และเขาทั้งหลายโจมตีกองทัพคนฟีลิสเตียตั้งแต่เมืองกิเบโอนถึงเมืองเกเซอร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 17, 'กิตติศัพท์ของดาวิดก็ลือไปสู่บรรดาประเทศทั้งหลาย และพระเยโฮวาห์ทรงให้ประชาชาติทั้งปวงครั่นคร้ามดาวิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 1, 'ดาวิดทรงสร้างพระราชวังของพระองค์หลายหลังในนครดาวิด และพระองค์ทรงเตรียมที่ไว้สําหรับหีบของพระเจ้าและทรงตั้งเต็นท์ไว้ให้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 2, 'แล้วดาวิดตรัสว่า “นอกจากคนเลวีแล้วไม่ควรที่คนอื่นจะหามหีบของพระเจ้า เพราะว่าพระเยโฮวาห์ทรงเลือกเขาให้หามหีบของพระเจ้า และปรนนิบัติพระองค์เป็นนิตย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 3, 'และดาวิดทรงประชุมอิสราเอลทั้งสิ้นที่เยรูซาเล็ม เพื่อจะนําหีบของพระเยโฮวาห์มาสู่ที่ของหีบนั้น ซึ่งพระองค์ได้ทรงเตรียมไว้ให้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 4, 'และดาวิดทรงรวบรวมลูกหลานของอาโรนและคนเลวี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 5, 'คือจากลูกหลานของโคฮาท ได้อุรีเอลเป็นหัวหน้า พร้อมกับพี่น้องของเขาหนึ่งร้อยยี่สิบคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 6, 'จากลูกหลานของเมรารี ได้อาสายาห์เป็นหัวหน้า พร้อมกับพี่น้องของเขาสองร้อยยี่สิบคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 7, 'จากลูกหลานของเกอร์โชม ได้โยเอลเป็นหัวหน้า กับพี่น้องของเขาหนึ่งร้อยสามสิบคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 8, 'จากลูกหลานของเอลีซาฟาน ได้เชไมอาห์เป็นหัวหน้า กับพี่น้องของเขาสองร้อยคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 9, 'จากลูกหลานของเฮโบรน ได้เอลีเอลเป็นหัวหน้า กับพี่น้องของเขาแปดสิบคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 10, 'จากลูกหลานของอุสซีเอล ได้อัมมีนาดับเป็นหัวหน้า กับพี่น้องของเขาหนึ่งร้อยสิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 11, 'แล้วดาวิดทรงเรียกศาโดกและอาบียาธาร์ปุโรหิต และคนเลวีคือ อุรีเอล อาสายาห์ โยเอล เชไมอาห์ เอลีเอล และอัมมีนาดับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 12, 'และตรัสกับเขาทั้งหลายว่า “เจ้าทั้งหลายเป็นประมุขของบรรพบุรุษของคนเลวี จงชําระตัวของเจ้าเสีย ทั้งเจ้าและพี่น้องของเจ้า เพื่อเจ้าจะนําหีบของพระเยโฮวาห์พระเจ้าแห่งอิสราเอลขึ้นมายังสถานที่ซึ่งเราได้จัดเตรียมไว้ให้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 13, 'เพราะเจ้ามิได้ไปหามเสียแต่ครั้งแรก พระเยโฮวาห์พระเจ้าของเราจึงทรงทลายออกมาเหนือเรา เพราะเรามิได้แสวงหาตามระเบียบอันสมควร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 14, 'แล้วปุโรหิตและคนเลวีจึงได้ชําระตัวของเขาเพื่อจะเชิญหีบของพระเยโฮวาห์พระเจ้าของอิสราเอลขึ้นมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 15, 'และคนเลวีได้หามหีบของพระเจ้าบนบ่าด้วยคานหาม ดังที่โมเสสได้บัญชาเขาไว้ตามพระวจนะของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 16, 'ดาวิดได้ทรงบัญชาแก่บรรดาหัวหน้าของคนเลวีให้แต่งตั้งพี่น้องของเขาให้เป็นนักร้องเล่นเครื่องดนตรี มีพิณใหญ่ พิณเขาคู่ และฉาบ เพื่อทําเสียงดังด้วยความชื่นบาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 17, 'คนเลวีจึงแต่งตั้งเฮมานบุตรชายโยเอล และพี่น้องของเขาคือ อาสาฟบุตรชายเบเรคิยาห์ และจากลูกหลานเมรารีพี่น้องของเขาคือ เอธานบุตรชายคูชายาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 18, 'และพร้อมกับเขาได้แต่งตั้งพี่น้องของเขาในอันดับสองคือ เศคาริยาห์ เบน ยาอาซีเอล เชมิราโมท เยฮีเอล อุนนี เอลีอับ เบไนยาห์ มาอาเสอาห์ มัททีธิยาห์ เอลีฟัล และมิกเนยาห์ และโอเบดเอโดม กับเยอีเอล เป็นคนเฝ้าประตู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 19, 'นักร้องคือ เฮมาน อาสาฟ เอธาน เป็นคนตีฉาบทองเหลือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 20, 'เศคาริยาห์ อาซีเอล เชมิราโมท เยฮีเอล อุนนี เอลีอับ มาอาเสอาห์ และเบไนยาห์ เล่นพิณใหญ่ตามสําเนียงอาลาโมท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 21, 'แต่มัททีธิยาห์ เอลีฟัล มิกเนยาห์ โอเบดเอโดม เยอีเอล และอาซาซิยาห์ เป็นผู้นําด้วยพิณเขาคู่ตามสําเนียงเชมินิท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 22, 'เคนานิยาห์หัวหน้าของคนเลวีในเรื่องเพลงเป็นผู้อํานวยการเพลง เพราะเขาเข้าใจดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 23, 'เบเรคิยาห์และเอลคานาห์ เป็นนายประตูเฝ้าหีบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 24, 'เชบานิยาห์ เยโฮชาฟัท เนธันเอล อามาสัย เศคาริยาห์ เบไนยาห์ และเอลีเยเซอร์ปุโรหิตได้เป่าแตรหน้าหีบของพระเจ้า โอเบดเอโดม และเยฮียาห์เป็นนายประตูเฝ้าหีบด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 25, 'ดาวิด และบรรดาผู้ใหญ่ของอิสราเอล และผู้บัญชากองพัน จึงได้ไปนําหีบพันธสัญญาของพระเยโฮวาห์ขึ้นจากเรือนของโอเบดเอโดมด้วยความเปรมปรีดิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 26, 'อยู่มาเพราะพระเจ้าทรงช่วยคนเลวีผู้หามหีบพันธสัญญาของพระเยโฮวาห์ เขาทั้งหลายก็ได้ถวายเครื่องบูชาเป็นวัวผู้เจ็ดตัวและแกะผู้เจ็ดตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 27, 'ดาวิดทรงฉลองพระองค์ผ้าป่านเนื้อละเอียด ทั้งคนเลวีทั้งปวงผู้หามหีบ และนักร้อง และเคนานิยาห์ผู้อํานวยการเพลงของนักร้อง และดาวิดทรงเอโฟดผ้าป่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 28, 'ดังนี้แหละคนอิสราเอลทั้งปวงได้นําหีบพันธสัญญาของพระเยโฮวาห์ขึ้นมาด้วยเสียงโห่ร้อง เสียงแตรทองเหลืองขนาดเล็ก เสียงแตร และฉาบ และทําเพลงเสียงดังด้วยพิณใหญ่และพิณเขาคู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 29, 'และต่อมาเมื่อหีบพันธสัญญาของพระเยโฮวาห์มาถึงนครดาวิดแล้ว มีคาลราชธิดาของซาอูลแลดูตามช่องพระแกลเห็นกษัตริย์ดาวิดทรงเต้นรําและทรงร่าเริงอยู่ พระนางก็มีใจดูหมิ่นพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 1, 'และเขาทั้งหลายได้นําหีบของพระเจ้าเข้ามา วางไว้ภายในเต็นท์ซึ่งดาวิดได้ทรงตั้งไว้ให้ และเขาทั้งหลายได้ถวายเครื่องเผาบูชาและเครื่องสันติบูชาต่อพระพักตร์พระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 2, 'และเมื่อดาวิดทรงถวายเครื่องเผาบูชาและเครื่องสันติบูชาเสร็จแล้ว พระองค์ทรงอวยพระพรแก่ประชาชนในพระนามพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 3, 'และทรงแจกขนมปังคนละก้อน เนื้อคนละส่วน และขนมองุ่นแห้งคนละอัน แก่บรรดาประชาชนอิสราเอลทั้งชายและหญิง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 4, 'และพระองค์ทรงตั้งคนเลวีบางคนให้เป็นผู้ปรนนิบัติหน้าหีบของพระเยโฮวาห์ ให้ระลึกถึง ถวายโมทนาและสรรเสริญพระเยโฮวาห์พระเจ้าของอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 5, 'อาสาฟเป็นหัวหน้า และรองท่านคือเศคาริยาห์ เยอีเอล เชมิราโมท เยฮีเอล มัททีธิยาห์ เอลีอับ เบไนยาห์ โอเบดเอโดม และเยอีเอล ผู้ซึ่งจะเล่นพิณใหญ่และพิณเขาคู่ อาสาฟเป็นคนตีฉาบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 6, 'และเบไนยาห์กับยาฮาซีเอลปุโรหิตจะเป่าแตรเรื่อยไปหน้าหีบพันธสัญญาของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 7, 'แล้วในวันนั้นดาวิดทรงกําหนดเป็นครั้งแรกให้มีการร้องเพลงโมทนาถวายแด่พระเยโฮวาห์โดยอาสาฟและพี่น้องของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 8, '“จงโมทนาขอบพระคุณพระเยโฮวาห์ จงร้องทูลออกพระนามพระองค์ จงให้บรรดาพระราชกิจของพระองค์แจ้งแก่ชนชาติทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 9, 'จงร้องเพลงถวายพระองค์ ร้องเพลงสดุดีถวายพระองค์ จงเล่าถึงการมหัศจรรย์ทั้งสิ้นของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 10, 'จงอวดพระนามบริสุทธิ์ของพระองค์ ให้จิตใจของบรรดาผู้แสวงหาพระเยโฮวาห์เปรมปรีดิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 11, 'จงแสวงหาพระเยโฮวาห์ และพระกําลังของพระองค์ แสวงหาพระพักตร์ของพระองค์เรื่อยไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 12, 'จงระลึกถึงการอัศจรรย์ซึ่งพระองค์ทรงกระทํา การมหัศจรรย์และคําพิพากษาแห่งพระโอษฐ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 13, 'โอ เชื้อสายของอิสราเอล ผู้รับใช้ของพระองค์ ลูกหลานของยาโคบ ผู้เลือกสรรของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 14, 'พระองค์คือพระเยโฮวาห์พระเจ้าของเรา คําพิพากษาของพระองค์อยู่ทั่วไปในแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 15, 'จงจดจําพันธสัญญาของพระองค์อยู่เป็นนิตย์ คือพระวจนะที่พระองค์ทรงบัญชาไว้ตลอดชั่วหนึ่งพันชั่วอายุ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 16, 'คือพันธสัญญาซึ่งพระองค์ทรงกระทําไว้กับอับราฮัม คําปฏิญาณซึ่งทรงกระทําไว้กับอิสอัค');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 17, 'ซึ่งพระองค์ทรงยืนยันอีกกับยาโคบให้เป็นพระราชบัญญัติ และแก่อิสราเอลให้เป็นพันธสัญญานิรันดร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 18, 'ว่า ‘เราจะให้แผ่นดินคานาอันแก่เจ้า เป็นส่วนมรดกของเจ้าทั้งหลาย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 19, 'เมื่อเจ้าทั้งหลายยังมีคนจํานวนน้อย จํานวนน้อยจริง ยังเป็นแต่คนอาศัยอยู่ในนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 20, 'พเนจรไปจากประชาชาตินี้ถึงประชาชาตินั้น จากราชอาณาจักรนี้ถึงอีกชนชาติหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 21, 'พระองค์มิได้ทรงยอมให้ผู้ใดบีบบังคับเขา พระองค์ทรงขนาบกษัตริย์หลายองค์ด้วยเห็นแก่เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 22, 'ว่า ‘อย่าแตะต้องบรรดาผู้ที่เราเจิมไว้ อย่าทําอันตรายแก่ผู้พยากรณ์ทั้งหลายของเรา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 23, 'แผ่นดินโลกทั้งสิ้น จงร้องเพลงถวายพระเยโฮวาห์ จงประกาศความรอดของพระองค์ทุกๆวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 24, 'จงเล่าถึงสง่าราศีของพระองค์ท่ามกลางบรรดาประชาชาติ ถึงการมหัศจรรย์ของพระองค์ท่ามกลางบรรดาชนชาติทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 25, 'เพราะพระเยโฮวาห์นั้นทรงยิ่งใหญ่และสมควรจะสรรเสริญอย่างยิ่ง พระองค์ทรงเป็นที่เกรงกลัวเหนือพระทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 26, 'เพราะพระทั้งปวงของชนชาติทั้งหลายเป็นรูปเคารพ แต่พระเยโฮวาห์ทรงสร้างฟ้าสวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 27, 'เกียรติและความโอ่อ่าตระการมีอยู่ต่อพระพักตร์พระองค์ กําลังและความชื่นบานอยู่ในสถานที่ประทับของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 28, 'ตระกูลของชนชาติทั้งหลายเอ๋ย จงถวายแด่พระเยโฮวาห์ จงถวายสง่าราศีและกําลังแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 29, 'จงถวายสง่าราศีซึ่งควรแก่พระนามของพระองค์แด่พระเยโฮวาห์ จงนําเครื่องบูชาและมาเข้าเฝ้าพระองค์ จงนมัสการพระเยโฮวาห์ด้วยเครื่องประดับแห่งความบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 30, 'ชาวโลกทั้งสิ้นเอ๋ย จงตัวสั่นต่อเบื้องพระพักตร์พระองค์ เออ พิภพถูกสถาปนาแล้ว จะไม่หวั่นไหวเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 31, 'จงให้ฟ้าสวรรค์ยินดีและแผ่นดินโลกเปรมปรีดิ์ ให้เขาพูดในหมู่บรรดาประชาชาติว่า ‘พระเยโฮวาห์ทรงครอบครอง’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 32, 'ให้ทะเลคํารน กับสิ่งทั้งปวงที่อยู่ในนั้น ให้ทุ่งนาเริงโลด กับสิ่งทุกอย่างที่อยู่ในนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 33, 'แล้วต้นไม้ทั้งสิ้นของป่าไม้จะร้องเพลง เฉพาะพระพักตร์พระเยโฮวาห์ ด้วยพระองค์เสด็จมาพิพากษาโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 34, 'โอ จงโมทนาขอบพระคุณพระเยโฮวาห์เพราะพระองค์ประเสริฐ เพราะความเมตตาของพระองค์ดํารงเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 35, 'และท่านจงกล่าวว่า ‘โอ ข้าแต่พระเจ้าแห่งความรอดของข้าพระองค์ทั้งหลาย ขอจงช่วยข้าพระองค์ทั้งหลายให้รอด และขอทรงรวบรวมข้าพระองค์ทั้งหลาย และทรงช่วยข้าพระองค์ทั้งปวงให้พ้นจากประชาชาติทั้งหลาย เพื่อข้าพระองค์ทั้งหลายจะโมทนาขอบพระคุณพระนามอันบริสุทธิ์ของพระองค์ และเริงโลดในการสรรเสริญพระองค์’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 36, 'จงถวายสาธุการแด่พระเยโฮวาห์พระเจ้าของอิสราเอลแต่นิรันดร์กาลจนถึงนิรันดร์กาล” แล้วประชาชนทั้งปวงได้กล่าวว่า “เอเมน” และได้สรรเสริญพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 37, 'ดาวิดจึงทรงให้อาสาฟและพี่น้องของท่านอยู่ที่นั่นต่อหน้าหีบพันธสัญญาของพระเยโฮวาห์ ให้ปรนนิบัติอยู่หน้าหีบนั้นเรื่อยไปตามงานประจําวันที่ต้องทํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 38, 'ทั้งโอเบดเอโดมและพี่น้องหกสิบแปดคนของท่านด้วย ฝ่ายโอเบดเอโดมบุตรชายเยดูธูนกับโฮสาห์ให้เป็นคนเฝ้าประตู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 39, 'และพระองค์ทรงให้ศาโดกปุโรหิต กับพี่น้องของท่านผู้เป็นปุโรหิต อยู่หน้าพลับพลาแห่งพระเยโฮวาห์ซึ่งอยู่ในปูชนียสถานสูงเมืองกิเบโอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 40, 'เพื่อถวายเครื่องเผาบูชาแด่พระเยโฮวาห์บนแท่นเครื่องเผาบูชาในเวลาเช้าเวลาเย็นเสมอ ตามซึ่งได้บันทึกไว้ทั้งสิ้นในพระราชบัญญัติของพระเยโฮวาห์ ซึ่งพระองค์ทรงบัญชาอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 41, 'เฮมานและเยดูธูนอยู่กับเขาทั้งหลายและบรรดาคนอื่นที่ถูกเลือก และบ่งชื่อไว้ให้ถวายโมทนาแด่พระเยโฮวาห์ เพราะความเมตตาของพระองค์ดํารงอยู่เป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 42, 'และพร้อมกับเขาเฮมานและเยดูธูนมีแตรและฉาบเพื่อบรรเลง และเครื่องดนตรีประกอบเพลงถวายพระเจ้า ลูกหลานของเยดูธูนได้รับแต่งตั้งให้ประจําประตู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 43, 'และประชาชนทั้งปวงต่างก็จากไปยังบ้านของตน และดาวิดเสด็จกลับเพื่ออวยพรแด่ราชวงศ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 1, 'อยู่มาเมื่อดาวิดประทับในพระราชวังของพระองค์ ดาวิดตรัสกับนาธันผู้พยากรณ์ว่า “ดูเถิด เราอยู่ในบ้านทําด้วยไม้สนสีดาร์ แต่หีบพันธสัญญาแห่งพระเยโฮวาห์อยู่ภายใต้ม่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 2, 'และนาธันทูลดาวิดว่า “ขอพระองค์ทรงกระทําทั้งสิ้นตามพระประสงค์ของพระองค์ เพราะพระเจ้าทรงสถิตกับพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 3, 'แต่อยู่มาในคืนวันนั้นเอง พระวจนะของพระเจ้ามาถึงนาธันว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 4, '“จงไปบอกดาวิดผู้รับใช้ของเราว่า ‘พระเยโฮวาห์ตรัสดังนี้ว่า เจ้าอย่าสร้างนิเวศให้เราอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 5, 'เพราะเราไม่เคยอยู่ในนิเวศนับแต่วันที่เราพาอิสราเอลขึ้นมาจนกระทั่งวันนี้ แต่เราได้ไปจากเต็นท์นี้ถึงเต็นท์โน้น และจากพลับพลาแห่งนี้ถึงแห่งโน้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 6, 'ในที่ต่างๆที่เราเคลื่อนไปมากับอิสราเอลทั้งหมด เราได้เคยพูดสักคํากับผู้วินิจฉัยของอิสราเอลคนใด ผู้ที่เราได้บัญชาให้เขาเลี้ยงดูประชาชนของเราหรือว่า “ทําไมเจ้ามิได้สร้างนิเวศด้วยไม้สนสีดาร์ให้แก่เรา”’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 7, 'เพราะฉะนั้นบัดนี้เจ้าจงกล่าวแก่ดาวิดผู้รับใช้ของเราว่า ‘พระเยโฮวาห์จอมโยธาตรัสว่า เราได้เอาเจ้ามาจากทุ่งหญ้า จากการตามฝูงแพะแกะ เพื่อให้เจ้าเป็นเจ้าเหนืออิสราเอลประชาชนของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 8, 'และเราได้อยู่กับเจ้าไม่ว่าเจ้าไปที่ไหน และได้ขจัดบรรดาศัตรูของเจ้าให้พ้นหน้าเจ้า และเราได้กระทําให้เจ้ามีชื่อเสียงใหญ่โตอย่างกับชื่อเสียงของผู้ยิ่งใหญ่ในโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 9, 'และเราจะกําหนดที่หนึ่งในอิสราเอลประชาชนของเรา และเราจะปลูกฝังเขาไว้ เพื่อเขาทั้งหลายจะได้อยู่ในที่ของเขาเอง และไม่ต้องถูกกวนใจอีก และคนชั่วจะไม่มาตีปล้นเขาดังแต่ก่อนมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 10, 'ตั้งแต่สมัยเมื่อเราตั้งผู้วินิจฉัยเหนืออิสราเอลประชาชนของเรา และเราจะปราบปรามศัตรูทั้งสิ้นของเจ้า ยิ่งกว่านั้นอีก เรากล่าวแก่เจ้าว่า พระเยโฮวาห์จะทรงให้เจ้ามีราชวงศ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 11, 'และอยู่มาเมื่อวันทั้งหลายของเจ้าครบแล้ว เจ้าจะไปอยู่กับบรรพบุรุษของเจ้า เราจะให้เชื้อสายของเจ้าที่มาภายหลังเจ้าเกิดขึ้น ผู้ซึ่งจะเป็นบุตรชายคนหนึ่งของตัวเจ้าเอง และเราจะสถาปนาอาณาจักรของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 12, 'เขาจะเป็นผู้สร้างนิเวศให้เรา และเราจะสถาปนาบัลลังก์ของเขาไว้เป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 13, 'เราจะเป็นบิดาของเขา และเขาจะเป็นบุตรของเรา เราจะไม่นําความเมตตาของเราไปจากเขาเสีย อย่างที่เราเอาไปจากคนที่อยู่ก่อนเจ้านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 14, 'แต่เราจะให้เขาดํารงอยู่ในนิเวศของเรา และในอาณาจักรของเราเป็นนิตย์ เราจะสถาปนาบัลลังก์ของเขาไว้เป็นนิตย์’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 15, 'นาธันก็กราบทูลดาวิดตามถ้อยคําเหล่านี้ทั้งสิ้นและตามนิมิตนี้ทั้งหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 16, 'แล้วกษัตริย์ดาวิดก็เสด็จเข้าไปประทับนั่งต่อพระพักตร์พระเยโฮวาห์ และกราบทูลว่า “โอ ข้าแต่พระเยโฮวาห์พระเจ้า ข้าพระองค์เป็นผู้ใดเล่า และราชวงศ์ของข้าพระองค์เป็นอะไรเล่าที่พระองค์ทรงนําข้าพระองค์มาไกลจนถึงเพียงนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 17, 'โอ ข้าแต่พระเจ้า สิ่งนี้เป็นของเล็กน้อยในสายพระเนตรของพระองค์ เพราะพระองค์ยังตรัสถึงราชวงศ์ของผู้รับใช้ของพระองค์ในอนาคตอันไกลที่จะมาถึงนั้น และทรงมองข้าพระองค์ตามชนชั้นของมนุษย์ที่มีฐานะอันสูงส่ง โอ ข้าแต่พระเยโฮวาห์พระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 18, 'และดาวิดจะกล่าวทูลอะไรแก่พระองค์ได้อีกในเรื่องเกียรติอันทรงประทานแก่ผู้รับใช้ของพระองค์ เพราะพระองค์ทรงรู้จักผู้รับใช้ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 19, 'โอ ข้าแต่พระเยโฮวาห์ เพื่อทรงเห็นแก่ผู้รับใช้ของพระองค์ และตามน้ําพระทัยของพระองค์เอง พระองค์ทรงกระทําการใหญ่ยิ่งนี้ทั้งสิ้นเพื่อจะกระทําให้สิ่งใหญ่นี้เป็นที่รู้กันทั่วไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 20, 'โอ ข้าแต่พระเยโฮวาห์ หามีผู้ใดเหมือนพระองค์ไม่ ไม่มีพระเจ้าอื่นใดนอกเหนือพระองค์ ตามที่ข้าพระองค์ทั้งหลายได้ยินกับหูของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 21, 'ประชาชาติอื่นใดบนแผ่นดินโลกเหมือนอิสราเอลประชาชนของพระองค์ ผู้ซึ่งพระเจ้าเสด็จไปไถ่ให้เป็นประชาชนของพระองค์ เพื่อทรงกระทําให้พระองค์มีพระนามใหญ่ยิ่งโดยสิ่งที่ใหญ่โตน่าสะพรึงกลัว ในการที่ทรงขับไล่ประชาชาติทั้งหลายให้พ้นหน้าประชาชนของพระองค์ ผู้ซึ่งพระองค์ทรงไถ่มาจากอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 22, 'และพระองค์ทรงกระทําให้อิสราเอลประชาชนของพระองค์เป็นประชาชนของพระองค์เป็นนิตย์ และข้าแต่พระเยโฮวาห์ พระองค์ทรงเป็นพระเจ้าของเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 23, 'ข้าแต่พระเยโฮวาห์ ฉะนั้นบัดนี้ขอให้พระวจนะซึ่งพระองค์ตรัสเกี่ยวกับผู้รับใช้ของพระองค์ และเกี่ยวกับราชวงศ์จงดํารงอยู่เป็นนิตย์ และขอพระองค์ทรงกระทําตามที่พระองค์ตรัสแล้วนั้นเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 24, 'และขอพระนามของพระองค์สถาปนาไว้และเกรียงไกรอยู่เป็นนิตย์ ว่า ‘พระเยโฮวาห์จอมโยธาทรงเป็นพระเจ้าแห่งอิสราเอล คือพระเจ้าแก่อิสราเอล’ และวงศ์ของดาวิดผู้รับใช้ของพระองค์จะถูกสถาปนาไว้ต่อพระพักตร์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 25, 'โอ ข้าแต่พระเจ้าของข้าพระองค์ เพราะพระองค์ได้ทรงสําแดงแก่ผู้รับใช้ของพระองค์ว่า พระองค์จะทรงสร้างวงศ์ให้ เพราะฉะนั้นผู้รับใช้ของพระองค์จึงได้ประสบความกล้าหาญที่จะอธิษฐานต่อพระพักตร์พระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 26, 'ข้าแต่พระเยโฮวาห์ บัดนี้ พระองค์ทรงเป็นพระเจ้า และพระองค์ได้ทรงสัญญาสิ่งที่ดีนี้ให้แก่ผู้รับใช้ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 27, 'เพราะฉะนั้นบัดนี้ขอให้เป็นที่พอพระทัยพระองค์ที่จะทรงอวยพระพรแก่วงศ์ของผู้รับใช้ของพระองค์ เพื่อวงศ์นั้นจะดํารงอยู่ต่อพระพักตร์พระองค์เป็นนิตย์ โอ ข้าแต่พระเยโฮวาห์ เพราะว่าสิ่งใดที่พระองค์ทรงอํานวยพระพร สิ่งนั้นก็ได้รับพระพรเป็นนิตย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 1, 'และอยู่ต่อมาดาวิดทรงโจมตีคนฟีลิสเตียและทรงปราบปรามเขาเสีย ทรงยึดเมืองกัทและชนบทของเมืองนั้นจากมือคนฟีลิสเตีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 2, 'และพระองค์ทรงโจมตีโมอับ และคนโมอับก็เป็นผู้รับใช้ของดาวิดและนําบรรณาการมาถวาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 3, 'ดาวิดทรงโจมตีฮาดัดเอเซอร์กษัตริย์ของเมืองโศบาห์ด้วยตรงไปยังเมืองฮามัท ขณะเมื่อพระองค์เสด็จไปตั้งอํานาจการปกครองของพระองค์ที่แม่น้ํายูเฟรติส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 4, 'และดาวิดทรงยึดรถรบจากท่านมาหนึ่งพันคัน พลม้าเจ็ดพัน และทหารราบสองหมื่น และดาวิดทรงตัดเอ็นโคนขาม้ารถรบเสียสิ้น แต่ทรงเหลือไว้ให้พอแก่รถรบหนึ่งร้อยคัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 5, 'และเมื่อคนซีเรียแห่งเมืองดามัสกัสมาช่วยฮาดัดเอเซอร์กษัตริย์แห่งเมืองโศบาห์ ดาวิดทรงประหารคนซีเรียเสียสองหมื่นสองพันคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 6, 'แล้วดาวิดทรงตั้งทหารประจําป้อมในซีเรียแห่งเมืองดามัสกัส และคนซีเรียเป็นผู้รับใช้ของดาวิด และนําบรรณาการมาถวาย ดาวิดเสด็จไป ณ ที่ใด พระเยโฮวาห์ทรงประทานชัยชนะแก่พระองค์ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 7, 'ดาวิดทรงยึดโล่ทองคําที่ผู้รับใช้ของฮาดัดเอเซอร์ถือ และทรงนํามาที่เยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 8, 'ดาวิดทรงยึดทองเหลืองเป็นอันมากจากเมืองทิบหาทและจากเมืองคูน หัวเมืองของฮาดัดเอเซอร์ ซึ่งซาโลมอนทรงใช้สร้างขันสาครทองเหลืองและเสา และเครื่องใช้ทองเหลือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 9, 'เมื่อโทอูกษัตริย์แห่งเมืองฮามัทได้ยินว่าดาวิดทรงโจมตีกองทัพทั้งสิ้นของฮาดัดเอเซอร์กษัตริย์แห่งเมืองโศบาห์แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 10, 'พระองค์ทรงใช้ฮาโดรัมโอรสของพระองค์ไปเฝ้ากษัตริย์ดาวิดเพื่อรับเสด็จ และถวายพระพรที่พระองค์ทรงรบกับฮาดัดเอเซอร์และทรงชนะ (เพราะว่าฮาดัดเอเซอร์ได้สู้รบกับโทอูบ่อยๆ) และพระองค์ได้ส่งของทุกอย่างที่ทําด้วยทองคํา ด้วยเงิน และด้วยทองเหลืองมาถวาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 11, 'และกษัตริย์ดาวิดทูลถวายสิ่งเหล่านี้แด่พระเยโฮวาห์ พร้อมกับเงินและทองคําซึ่งพระองค์ทรงนํามาจากประชาชาติทั้งปวง จากเอโดม โมอับ คนอัมโมน คนฟีลิสเตีย และอามาเลข');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 12, 'และอาบีชัยบุตรชายนางเศรุยาห์ได้ประหารคนเอโดมหนึ่งหมื่นแปดพันคนเสียในหุบเขาเกลือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 13, 'และท่านตั้งทหารประจําป้อมในเอโดม และคนเอโดมทั้งสิ้นได้เป็นคนรับใช้ของดาวิด และพระเยโฮวาห์ทรงประทานชัยชนะแก่ดาวิดไม่ว่าพระองค์เสด็จไป ณ ที่ใดๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 14, 'ดาวิดจึงทรงครอบครองเหนืออิสราเอลทั้งสิ้น และพระองค์ทรงให้ความยุติธรรมและความเที่ยงธรรมแก่ประชาชนของพระองค์ทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 15, 'และโยอาบบุตรชายนางเศรุยาห์เป็นผู้บัญชาการกองทัพ และเยโฮชาฟัทบุตรชายอาหิลูดเป็นเจ้ากรมสารบรรณ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 16, 'และศาโดกบุตรชายอาหิทูบและอาบีเมเลคบุตรชายอาบียาธาร์เป็นปุโรหิต และชาวะชาเป็นราชเลขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 17, 'และเบไนยาห์บุตรชายเยโฮยาดาอยู่เหนือคนเคเรธีและคนเปเลท และบรรดาโอรสของดาวิดก็เป็นเจ้าหน้าที่ชั้นหัวหน้าในราชการของกษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 1, 'และอยู่ต่อมาภายหลังนี้นาหาชกษัตริย์ของคนอัมโมนสิ้นพระชนม์ และโอรสของพระองค์ได้ขึ้นครอบครองแทน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 2, 'และดาวิดตรัสว่า “เราจะแสดงความเมตตาต่อฮานูนโอรสของนาหาช เพราะว่าบิดาของท่านได้แสดงความเมตตาต่อเรา” ดาวิดจึงทรงส่งผู้สื่อสารไปเล้าโลมท่านเกี่ยวกับบิดาของท่าน และข้าราชการของดาวิดก็มายังฮานูนในแผ่นดินของคนอัมโมน เพื่อจะเล้าโลมท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 3, 'แต่บรรดาเจ้านายของคนอัมโมนทูลฮานูนว่า “พระองค์ดําริว่าดาวิดส่งผู้เล้าโลมมาหาพระองค์เพราะนับถือพระราชบิดาของพระองค์เช่นนั้นหรือ ข้าราชการของท่านมาหาพระองค์เพื่อค้นหาและคว่ําและสอดแนมแผ่นดินมิใช่หรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 4, 'ฮานูนจึงจับข้าราชการของดาวิดและโกนเขาเสีย และตัดเครื่องแต่งกายของเขาออกเสียที่ตรงกลางตรงสะโพก แล้วปล่อยตัวไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 5, 'เมื่อมีบางคนไปทูลดาวิดถึงเรื่องคนเหล่านั้น พระองค์ก็ทรงใช้ให้ไปรับเขา เพราะคนเหล่านั้นอายมาก และกษัตริย์ตรัสว่า “จงพักอยู่ที่เมืองเยรีโคจนกว่าเคราของท่านทั้งหลายจะขึ้น แล้วจึงค่อยกลับมา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 6, 'เมื่อคนอัมโมนเห็นว่าเขาทั้งหลายเป็นที่เกลียดชังแก่ดาวิด ฮานูนและคนอัมโมนจึงส่งเงินหนึ่งพันตะลันต์ไปจ้างรถรบและพลม้าจากเมโสโปเตเมีย จากซีเรียมาอาคาห์ และจากโศบาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 7, 'เขาได้จ้างรถรบสามหมื่นสองพันคันและกษัตริย์แห่งเมืองมาอาคาห์กับกองทัพของท่าน ผู้ซึ่งมาตั้งค่ายอยู่ที่หน้าเมืองเมเดบา และคนอัมโมนก็รวบรวมกันมาจากหัวเมืองของเขาทั้งหลาย และมาทําสงคราม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 8, 'เมื่อดาวิดทรงได้ยินเรื่องนั้นจึงใช้โยอาบ และกองทัพทแกล้วทหารทั้งสิ้นไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 9, 'คนอัมโมนออกมาจัดทัพตรงหน้าประตูเมือง และบรรดากษัตริย์ที่ยกมาอยู่ที่ชนบทกลางแจ้งต่างหาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 10, 'เมื่อโยอาบเห็นว่าการศึกนั้นขนาบอยู่ข้างหน้าและข้างหลัง ท่านจึงคัดเอาจากบรรดาคนอิสราเอลที่สรรไว้แล้วและจัดทัพเข้าไปต่อสู้คนซีเรีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 11, 'ส่วนคนของท่านที่เหลืออยู่ ท่านก็มอบไว้ในการบังคับบัญชาของอาบีชัยน้องชายของท่าน คนเหล่านั้นก็จัดเข้าสู้กับคนอัมโมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 12, 'และท่านพูดว่า “ถ้ากําลังคนซีเรียแข็งเหลือกําลังของเราแล้วเจ้าจงช่วยเรา แต่ถ้ากําลังคนอัมโมนแข็งเกินกําลังของเจ้า เราจะช่วยเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 13, 'จงมีความกล้าหาญเถิด และให้เราประพฤติตัวอย่างกล้าหาญเพื่อชนชาติของเรา และเพื่อหัวเมืองของพระเจ้าของเรา และขอพระเยโฮวาห์ทรงกระทําสิ่งที่ชอบพระทัยในสายพระเนตรของพระองค์เถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 14, 'ดังนั้นโยอาบและประชาชนผู้อยู่กับท่านได้เข้ามาใกล้ข้างหน้าคนซีเรียเพื่อสู้รบกัน และเขาทั้งหลายก็แตกหนีไปต่อหน้าท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 15, 'และเมื่อคนอัมโมนเห็นว่าคนซีเรียหนีไปแล้ว เขาก็หนีไปให้พ้นหน้าอาบีชัยน้องชายของโยอาบด้วย และเข้าไปในเมือง แล้วโยอาบก็กลับมายังเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 16, 'แต่เมื่อคนซีเรียเห็นว่าเขาพ่ายแพ้แก่อิสราเอล เขาจึงส่งผู้สื่อสารไปนําคนซีเรียซึ่งอยู่ฟากแม่น้ําข้างโน้นออกมา มีโชฟัคผู้บังคับบัญชากองทัพของฮาดัดเอเซอร์เป็นหัวหน้าของเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 17, 'และเมื่อมีคนกราบทูลดาวิด พระองค์ก็ทรงรวมอิสราเอลทั้งสิ้นเข้าด้วยกัน และข้ามแม่น้ําจอร์แดนมาหาเขา และจัดทัพต่อสู้กับเขา และเมื่อดาวิดทรงจัดทัพเข้าต่อสู้กับคนซีเรีย เขาทั้งหลายต่อสู้กับพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 18, 'และคนซีเรียก็หนีไปต่อหน้าอิสราเอล และดาวิดทรงประหารคนซีเรียคือคนของรถรบเจ็ดพันคนและทหารราบสี่หมื่นคน และฆ่าโชฟัคผู้บัญชาการกองทัพของเขาทั้งหลายด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 19, 'และเมื่อผู้รับใช้ของฮาดัดเอเซอร์เห็นว่าเขาพ่ายแพ้ต่ออิสราเอล เขาก็ยอมทําสันติภาพกับดาวิด และเป็นผู้รับใช้ของพระองค์ คนซีเรียจึงไม่ช่วยคนอัมโมนอีกต่อไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 1, 'และอยู่มาพอสิ้นปีแล้วเมื่อบรรดากษัตริย์ยกกองทัพออกไปรบ โยอาบก็นํากําลังกองทัพไปกวาดล้างแผ่นดินของคนอัมโมน และมาล้อมเมืองรับบาห์ไว้ แต่ดาวิดประทับที่เยรูซาเล็ม และโยอาบก็โจมตีเมืองรับบาห์ และคว่ําเมืองนั้นเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 2, 'และดาวิดทรงถอดมงกุฎจากพระเศียรของกษัตริย์ของเขาทั้งหลาย พระองค์ทรงทราบว่ามงกุฎนั้นมีทองคําหนักหนึ่งตะลันต์ และมีเพชรพลอยต่างๆ ซึ่งต่อมาอยู่บนพระเศียรของดาวิด และพระองค์ทรงริบของจากเมืองนั้นได้ข้าวของเป็นอันมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 3, 'พระองค์ทรงนําประชาชนที่อยู่ในเมืองนั้นออกมา ตั้งเขาให้ทํางานหนักอยู่กับเลื่อยและเหล็กขุดและขวาน และดาวิดทรงกระทําเช่นนั้นแก่หัวเมืองทั้งสิ้นของคนอัมโมน แล้วดาวิดกับประชาชนทั้งปวงก็กลับสู่เยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 4, 'และอยู่มาภายหลังเกิดสงครามขึ้นกับคนฟีลิสเตียที่เมืองเกเซอร์ แล้วสิบเบคัยคนหุชาห์ได้สังหารสิปปัยผู้เป็นลูกหลานของคนยักษ์เสีย และคนฟีลิสเตียก็ถูกปราบปราม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 5, 'และมีสงครามกับคนฟีลิสเตียอีก และเอลฮานันบุตรชายยาอีร์ได้ฆ่าลามีน้องชายของโกลิอัทชาวกัทเสีย ผู้มีหอกที่มีด้ามโตเท่าไม้กระพั่นทอผ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 6, 'และมีสงครามที่เมืองกัทอีก มีชายคนหนึ่งรูปร่างใหญ่โต ผู้ที่มือข้างหนึ่งมีนิ้วหกนิ้ว และนิ้วเท้าข้างละหกนิ้ว จํานวนยี่สิบสี่นิ้ว และเขาเป็นบุตรชายของคนยักษ์ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 7, 'และเมื่อเขาท้าทายอิสราเอล โยนาธานบุตรชายชิเมอาพระเชษฐาของดาวิดก็ประหารเขาเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 8, 'คนเหล่านี้บังเกิดแก่คนยักษ์ในเมืองกัท และเขาล้มตายด้วยพระหัตถ์ของดาวิด และด้วยมือผู้รับใช้ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 1, 'ซาตานได้ยืนขึ้นต่อสู้อิสราเอล และดลพระทัยให้ดาวิดนับจํานวนอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 2, 'ดาวิดจึงตรัสกับโยอาบและผู้บังคับบัญชากองทัพว่า “จงไปนับอิสราเอลตั้งแต่เมืองเบเออร์เชบาถึงเมืองดาน แล้วนํารายงานมาให้เราเพื่อจะได้ทราบจํานวนรวมของเขาทั้งหลาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 3, 'แต่โยอาบทูลว่า “ขอพระเยโฮวาห์ทรงเพิ่มประชาชนของพระองค์อีกร้อยเท่าของที่มีอยู่แล้ว ข้าแต่กษัตริย์เจ้านายของข้าพระองค์ แต่ประชาชนนี้ทั้งสิ้นเป็นผู้รับใช้ของเจ้านายของข้าพระองค์มิใช่หรือ ไฉนเจ้านายของข้าพระองค์จึงรับสั่งเช่นนี้ ไฉนพระองค์จึงทรงนําการละเมิดมาสู่อิสราเอล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 4, 'แต่โยอาบขัดรับสั่งของกษัตริย์มิได้ โยอาบจึงจากไป และไปตลอดคนอิสราเอลทั้งสิ้น และกลับมายังเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 5, 'และโยอาบถวายจํานวนประชาชนที่นับได้แก่ดาวิด ในอิสราเอลทั้งสิ้นมีหนึ่งล้านหนึ่งแสนคนที่ชักดาบ และในยูดาห์มีสี่แสนเจ็ดหมื่นคนที่ชักดาบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 6, 'แต่ท่านมิได้นับเลวีและเบนยามินท่ามกลางจํานวนนั้นด้วย เพราะว่าพระดํารัสของกษัตริย์เป็นที่น่ารังเกียจแก่โยอาบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 7, 'แต่พระเจ้าไม่ทรงพอพระทัยในเรื่องนี้ พระองค์จึงทรงลงโทษอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 8, 'และดาวิดทูลพระเจ้าว่า “ข้าพระองค์ได้ทําบาปใหญ่ยิ่งในการที่ข้าพระองค์ได้กระทําสิ่งนี้ ข้าแต่พระองค์ บัดนี้ขอทรงให้อภัยความชั่วช้าของผู้รับใช้ของพระองค์ เพราะข้าพระองค์ได้กระทําการอย่างโง่เขลามาก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 9, 'และพระเยโฮวาห์ตรัสกับกาดผู้ทํานายของดาวิดว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 10, '“จงไปบอกดาวิดว่า ‘พระเยโฮวาห์ตรัสดังนี้ว่า เราเสนอเจ้าสามประการ จงเลือกเอาประการหนึ่ง เพื่อเราจะได้กระทําให้แก่เจ้า’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 11, 'กาดจึงเข้าเฝ้าดาวิดและกราบทูลพระองค์ว่า “พระเยโฮวาห์ตรัสดังนี้ว่า จงเลือกเอาตามที่เจ้าพอใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 12, 'คือ กันดารอาหารสามปี หรือการล้างผลาญโดยศัตรูของเจ้าสามเดือนขณะที่ดาบของศัตรูจะขับเจ้าทัน หรือดาบของพระเยโฮวาห์สามวันคือโรคระบาดบนแผ่นดิน และทูตสวรรค์ของพระเยโฮวาห์ทําลายทั่วไปในดินแดนทั้งสิ้นของอิสราเอล ฉะนั้นบัดนี้ขอทรงพิจารณาดูว่าจะให้ข้าพระองค์กราบทูลพระองค์ผู้ทรงใช้ข้าพระองค์มาว่าประการใด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 13, 'แล้วดาวิดตรัสกับกาดว่า “เรามีความกระวนกระวายมาก ขอให้เราตกเข้าไปอยู่ในพระหัตถ์ของพระเยโฮวาห์ เพราะพระกรุณาคุณของพระองค์ใหญ่ยิ่งนัก แต่ขออย่าให้เราตกเข้าไปในมือของมนุษย์เลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 14, 'ดังนั้นพระเยโฮวาห์ทรงให้โรคระบาดเกิดขึ้นในอิสราเอล และคนอิสราเอลได้ล้มตายเจ็ดหมื่นคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 15, 'และพระเจ้าทรงใช้ทูตสวรรค์ไปยังเยรูซาเล็มเพื่อจะทําลายเสีย แต่เมื่อท่านจะลงมือทําลาย พระเยโฮวาห์ทรงทอดพระเนตร และพระองค์ทรงกลับพระทัยในเหตุร้ายนั้น และพระองค์ตรัสกับทูตสวรรค์ผู้ทําลายนั้นว่า “พอแล้ว ยับยั้งมือของเจ้าได้” ส่วนทูตสวรรค์ของพระเยโฮวาห์ก็กําลังยืนอยู่ที่ลานนวดข้าวของโอรนันคนเยบุส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 16, 'และดาวิดแหงนพระพักตร์ทรงเห็นทูตสวรรค์ของพระเยโฮวาห์ยืนระหว่างแผ่นดินโลกและฟ้าสวรรค์ และในมือถือดาบที่ชักออกเหนือเยรูซาเล็ม แล้วดาวิดและพวกผู้ใหญ่ของอิสราเอล ผู้ได้สวมผ้ากระสอบแล้ว ก็ซบหน้าลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 17, 'และดาวิดทูลพระเจ้าว่า “ข้าพระองค์มิใช่หรือที่บัญชาให้นับประชาชน ข้าพระองค์เป็นผู้ได้กระทําบาป และได้กระทําความชั่วร้ายยิ่งนัก แต่บรรดาแกะเหล่านี้เขาได้กระทําอะไร โอ ข้าแต่พระเยโฮวาห์พระเจ้าของข้าพระองค์ ขอพระหัตถ์ของพระองค์อยู่เหนือข้าพระองค์ และราชวงศ์ของข้าพระองค์ แต่ขออย่าให้โรคร้ายนั้นอยู่เหนือประชาชนของพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 18, 'แล้วทูตสวรรค์ของพระเยโฮวาห์ได้บัญชาให้กาดทูลดาวิดว่า ให้ดาวิดขึ้นไปสร้างแท่นบูชาถวายแด่พระเยโฮวาห์ที่ลานนวดข้าวของโอรนันคนเยบุส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 19, 'ดาวิดจึงเสด็จขึ้นไปตามคําของกาด ซึ่งท่านได้กราบทูลในพระนามของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 20, 'ฝ่ายโอรนันกําลังนวดข้าวสาลีอยู่ โอรนันหันมาเห็นทูตสวรรค์ และบุตรชายสี่คนของท่านที่อยู่กับท่านก็ซ่อนตัวเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 21, 'เมื่อดาวิดเสด็จมายังโอรนัน โอรนันมองเห็นดาวิด และออกไปจากลานนวดข้าวถวายบังคมดาวิดด้วยซบหน้าลงถึงดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 22, 'และดาวิดตรัสกับโอรนันว่า “จงให้ที่ลานนวดข้าวแก่เราเถิด เพื่อเราจะสร้างแท่นบูชาถวายแด่พระเยโฮวาห์บนนั้น จงให้แก่เราตามราคาเต็ม เพื่อว่าโรคระบาดนั้นจะได้ระงับเสียจากประชาชน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 23, 'แล้วโอรนันกราบทูลดาวิดว่า “ขอทรงรับไปเถิดพ่ะย่ะค่ะ และขอกษัตริย์เจ้านายของข้าพระองค์กระทําสิ่งที่พระองค์ทรงเห็นชอบเถิด นี่พ่ะย่ะค่ะ ข้าพระองค์ขอถวายวัวสําหรับเครื่องเผาบูชา และถวายเลื่อนนวดข้าวให้เป็นฟืน แล้วข้าวสาลีเป็นธัญญบูชา ข้าพระองค์ขอถวายหมด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 24, 'แต่กษัตริย์ดาวิดตรัสกับโอรนันว่า “หามิได้ แต่เราจะซื้อเอาตามราคาเต็ม เราจะไม่เอาของของเจ้าถวายพระเยโฮวาห์ หรือถวายสิ่งที่เรามิได้เสียค่าเป็นเครื่องเผาบูชา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 25, 'ดาวิดจึงทรงชําระให้โอรนันเป็นทองคําน้ําหนักหกร้อยเชเขลเพื่อที่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 26, 'ดาวิดก็ทรงสร้างแท่นบูชาถวายแด่พระเยโฮวาห์ที่นั่น และทรงถวายเครื่องเผาบูชา และเครื่องสันติบูชา และกราบทูลออกพระนามพระเยโฮวาห์ และพระเยโฮวาห์ทรงตอบพระองค์ด้วยไฟจากสวรรค์บนแท่นเครื่องเผาบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 27, 'แล้วพระเยโฮวาห์ก็ทรงบัญชาทูตสวรรค์ และท่านก็เอาดาบใส่ฝักเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 28, 'ครั้งนั้น เมื่อดาวิดทรงเห็นว่าพระเยโฮวาห์ทรงตอบพระองค์ที่ลานนวดข้าวของโอรนันคนเยบุส พระองค์ก็ทรงถวายสัตวบูชาที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 29, 'เพราะพลับพลาของพระเยโฮวาห์ซึ่งโมเสสได้สร้างขึ้นในถิ่นทุรกันดาร และแท่นเครื่องเผาบูชา ในเวลานั้นอยู่ในปูชนียสถานสูงที่กิเบโอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 30, 'แต่ดาวิดจะไปทูลถามพระเจ้าที่นั่นไม่ได้ เพราะพระองค์ทรงกลัวดาบของทูตสวรรค์ของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 1, 'แล้วดาวิดตรัสว่า “นี่แหละพระนิเวศของพระเยโฮวาห์พระเจ้า นี่แหละแท่นเครื่องเผาบูชาสําหรับอิสราเอล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 2, 'ดาวิดทรงบัญชาให้รวบรวมคนต่างด้าวที่อยู่ในแผ่นดินอิสราเอล และพระองค์ทรงจัดคนสกัดหินให้เตรียมหินสกัดเพื่อสร้างพระนิเวศของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 3, 'ดาวิดยังทรงจัดสะสมเหล็กเป็นจํานวนมาก เพื่อเป็นตะปูของบานประตูรั้วและเป็นเหล็กหนีบ ทั้งทองเหลืองเป็นจํานวนมากเหลือที่จะชั่งได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 4, 'และไม้สนสีดาร์นับไม่ถ้วน เพราะว่าชาวไซดอน และชาวไทระ ได้นําไม้สนสีดาร์จํานวนมากมายมาถวายดาวิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 5, 'เพราะดาวิดตรัสว่า “ซาโลมอนบุตรชายของเรายังเด็กอยู่และไม่เคยงาน และพระนิเวศซึ่งจะสร้างถวายพระเยโฮวาห์นั้นต้องหรูหราอย่างยิ่ง มีชื่อเสียงและสง่าราศีในบรรดาประเทศทั้งหลาย เพราะฉะนั้นบัดนี้เราจึงจะจัดเตรียมไว้” ดาวิดจึงทรงจัดวัตถุเป็นจํานวนมากก่อนพระองค์สิ้นพระชนม์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 6, 'แล้วพระองค์ทรงเรียกซาโลมอนราชโอรสของพระองค์ และกําชับท่านให้สร้างพระนิเวศถวายพระเยโฮวาห์พระเจ้าแห่งอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 7, 'ดาวิดรับสั่งซาโลมอนว่า “ลูกเอ๋ย เรามีใจประสงค์ที่จะสร้างพระนิเวศถวายพระนามแห่งพระเยโฮวาห์พระเจ้าของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 8, 'แต่พระวจนะของพระเยโฮวาห์มายังเราว่า ‘เจ้าได้ทําให้โลหิตตกมาก และได้ทําสงครามใหญ่โต เจ้าอย่าสร้างพระนิเวศเพื่อนามของเราเลย เพราะเจ้าได้ทําให้โลหิตตกเป็นอันมากต่อสายตาของเราบนแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 9, 'ดูเถิด บุตรชายคนหนึ่งจะบังเกิดมาแก่เจ้า เขาจะเป็นคนแห่งความสงบ เราจะให้ความสงบแก่เขาให้พ้นจากศัตรูทั้งสิ้นของเขารอบข้าง เพราะเขาจะมีชื่อว่าซาโลมอน และเราจะให้สันติภาพและความสงบแก่อิสราเอลในสมัยของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 10, 'เขาจะสร้างพระนิเวศเพื่อนามของเรา เขาจะเป็นบุตรของเรา และเราจะเป็นบิดาของเขา และเราจะสถาปนาราชบัลลังก์ของเขาเหนืออิสราเอลเป็นนิตย์’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 11, 'นี่แหละ ลูกของข้าเอ๋ย ขอพระเยโฮวาห์ทรงสถิตอยู่กับเจ้า และขอให้เจ้ามีความสําเร็จ และสร้างพระนิเวศของพระเยโฮวาห์พระเจ้าของเจ้าสําเร็จดังที่พระองค์ตรัสถึงเรื่องเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 12, 'ขอเพียงพระเยโฮวาห์ประสาทให้เจ้ามีความเฉลียวฉลาดและความเข้าใจ และทรงตั้งเจ้าให้ปกครองอิสราเอลและทรงโปรดให้เจ้ารักษาพระราชบัญญัติของพระเยโฮวาห์พระเจ้าของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 13, 'แล้วเจ้าจะทําสําเร็จ ถ้าเจ้าจะระมัดระวังที่จะปฏิบัติตามกฎเกณฑ์และคําตัดสินซึ่งพระเยโฮวาห์ทรงบัญชากับโมเสสเกี่ยวกับอิสราเอล จงเข้มแข็งและกล้าหาญเถิด อย่ากลัวและอย่าท้อถอยเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 14, 'และดูเถิด เราได้จัดเตรียมไว้เพื่อพระนิเวศของพระเยโฮวาห์ด้วยความเหนื่อยยากอย่างยิ่ง เป็นทองคําหนักหนึ่งแสนตะลันต์ เงินหนักหนึ่งล้านตะลันต์ ทองเหลืองและเหล็กเหลือที่จะชั่ง เพราะมีมากมายเหลือเกิน เราได้จัดเตรียมไม้และหินด้วย เจ้าจะเพิ่มเติมเข้าอีกก็ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 15, 'ยิ่งกว่านั้นเจ้ามีคนทํางานมากมาย คือช่างสกัดหิน ช่างก่อ ช่างไม้ และช่างฝีมือทุกชนิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 16, 'ส่วนทองคํา เงิน ทองเหลือง และเหล็กนั้นก็มีมากมายเหลือที่จะนับได้ ลุกขึ้นทําไปเถิด ขอพระเยโฮวาห์ทรงสถิตอยู่กับเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 17, 'ดาวิดทรงบัญชาประมุขทั้งปวงของอิสราเอลให้ช่วยซาโลมอนโอรสของพระองค์ด้วยว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 18, '“พระเยโฮวาห์พระเจ้าของเจ้าทรงสถิตอยู่กับเจ้ามิใช่หรือ และพระองค์มิได้ประทานการหยุดพักสงบแก่เจ้าทุกด้านหรือ เพราะพระองค์ทรงมอบชาวแผ่นดินนี้ไว้ในมือของเรา และแผ่นดินนั้นก็ราบคาบต่อพระพักตร์พระเยโฮวาห์และต่อหน้าประชาชนของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 19, 'บัดนี้จงตั้งจิตตั้งใจของเจ้าที่จะแสวงหาพระเยโฮวาห์พระเจ้าของเจ้า จงลุกขึ้นสร้างสถานบริสุทธิ์ของพระเยโฮวาห์พระเจ้า เพื่อว่าหีบพันธสัญญาของพระเยโฮวาห์ก็ดี และเครื่องใช้อันบริสุทธิ์ของพระเจ้าก็ดี จะได้นําเอามาไว้ในพระนิเวศที่จะสร้างขึ้นเพื่อพระนามของพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 1, 'เมื่อดาวิดทรงชราและหง่อมแล้ว พระองค์ทรงตั้งซาโลมอนโอรสของพระองค์ให้เป็นกษัตริย์เหนืออิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 2, 'ดาวิดทรงให้ประชุมเจ้านายทั้งสิ้นของอิสราเอล และบรรดาปุโรหิตและคนเลวี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 3, 'คนเลวีนั้นอายุตั้งแต่สามสิบปีขึ้นไปก็ได้นับไว้ทีละคน ตามจํานวนชื่อรายบุคคล รวมได้สามหมื่นแปดพันคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 4, 'ดาวิดตรัสว่า “จากพวกนี้ สองหมื่นสี่พันคนจะต้องดูแลการงานในพระนิเวศของพระเยโฮวาห์ และหกพันคนเป็นเจ้าหน้าที่และผู้วินิจฉัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 5, 'สี่พันคนเป็นนายประตู และอีกสี่พันคนจะถวายสรรเสริญแด่พระเยโฮวาห์ด้วยเครื่องดนตรีซึ่งเราได้สร้างไว้ให้ใช้สรรเสริญ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 6, 'และดาวิดทรงจัดแบ่งเป็นกองๆตามบุตรชายของเลวี คือ เกอร์โชน โคฮาท และเมรารี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 7, 'จากคนเกอร์โชนคือลาดานและชิเมอี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 8, 'บุตรชายของลาดานคือ เยฮีเอลผู้เป็นหัวหน้า และเศธาม และโยเอล สามคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 9, 'บุตรชายของชิเมอีคือ เชโลมิท ฮาซีเอล และฮาราน สามคน คนเหล่านี้เป็นประมุขของบรรพบุรุษลาดาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 10, 'และบุตรชายของชิเมอีคือ ยาหาท ศินา เยอูช และเบรียาห์ ทั้งสี่คนนี้เป็นบุตรชายของชิเมอี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 11, 'และยาหาทเป็นหัวหน้า และศิซาห์เป็นที่สอง แต่เยอูชและเบรียาห์ไม่มีบุตรชายมาก เพราะฉะนั้นในการนับจึงรวมเข้าเป็นเรือนบรรพบุรุษเดียวกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 12, 'บุตรชายของโคฮาทคือ อัมราม อิสฮาร์ เฮโบรน และอุสซีเอล สี่คน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 13, 'บุตรชายของอัมรามคือ อาโรนและโมเสส เขาตั้งอาโรนไว้ต่างหากให้เป็นผู้ทําพิธีชําระสิ่งของที่บริสุทธิ์ที่สุด ทั้งเขาและบุตรชายของเขาสืบไปเป็นนิตย์ เพื่อเผาเครื่องหอมถวายต่อพระพักตร์พระเยโฮวาห์และปรนนิบัติพระองค์ และอวยพระพรในพระนามของพระองค์เป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 14, 'ฝ่ายโมเสสคนของพระเจ้านั้น บุตรชายของท่านมีชื่อเสียงท่ามกลางคนตระกูลเลวี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 15, 'บุตรชายของโมเสสคือ เกอร์โชม กับ เอลีเยเซอร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 16, 'บุตรชายของเกอร์โชมคือ เชบูเอลผู้เป็นหัวหน้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 17, 'บุตรชายของเอลีเยเซอร์คือ เรหับยาห์ผู้เป็นหัวหน้า เอลีเยเซอร์ไม่มีบุตรชายอีก แต่บุตรชายของเรหับยาห์มีมากนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 18, 'บุตรชายของอิสฮาร์คือ เชโลมิทผู้เป็นหัวหน้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 19, 'บุตรชายของเฮโบรนคือ เยรียาห์ผู้เป็นหัวหน้า อามาริยาห์ที่สอง ยาฮาซีเอลที่สาม และเยคาเมอัมที่สี่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 20, 'บุตรชายของอุสซีเอลคือ มีคาห์ผู้เป็นหัวหน้า และอิสชีอาห์ที่สอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 21, 'บุตรชายของเมรารีคือ มาห์ลีและมูชี บุตรชายของมาห์ลีคือ เอเลอาซาร์และคีช');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 22, 'เอเลอาซาร์สิ้นชีวิตไม่มีบุตรชาย มีแต่บุตรสาว บุตรชายของคีชผู้เป็นญาติของเขาแต่งงานกับเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 23, 'บุตรชายของมูชีคือ มาห์ลี เอเดอร์ และเยรีโมท สามคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 24, 'คนเหล่านี้เป็นคนเลวีตามเรือนบรรพบุรุษของเขา เป็นประมุขของบรรพบุรุษของเขา ตามที่เขาได้ขึ้นทะเบียนไว้ตามจํานวนชื่อรายบุคคล อายุตั้งแต่ยี่สิบปีขึ้นไป ผู้ซึ่งจะทํางานปรนนิบัติในพระนิเวศของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 25, 'เพราะดาวิดตรัสว่า “พระเยโฮวาห์พระเจ้าของอิสราเอลได้ประสาทการหยุดพักสงบแก่ประชาชนของพระองค์ เพื่อเขาทั้งหลายจะอาศัยอยู่ในเยรูซาเล็มเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 26, 'และคนเลวีจึงไม่ต้องหาบหามพลับพลาหรือเครื่องใช้ใดๆเพื่องานปรนนิบัติอีกเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 27, 'เพราะตามพระดํารัสสุดท้ายของดาวิด คนเลวีตั้งแต่อายุยี่สิบปีขึ้นไปถูกนับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 28, 'แต่หน้าที่ของเขาจะต้องคอยช่วยบุตรชายของอาโรนในงานปรนนิบัติพระนิเวศแห่งพระเยโฮวาห์ มีงานดูแลลานและห้องและงานชําระของทุกอย่างที่บริสุทธิ์ และงานใดๆซึ่งเป็นงานปรนนิบัติของพระนิเวศแห่งพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 29, 'และช่วยเกี่ยวกับเรื่องขนมปังหน้าพระพักตร์ด้วย เรื่องยอดแป้งสําหรับธัญญบูชา ขนมไร้เชื้อแผ่นของปิ้งบูชา ของบูชาคลุกน้ํามัน และเครื่องตวง เครื่องวัดทุกขนาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 30, 'และทุกๆเช้าเขาจะต้องยืนโมทนาและสรรเสริญพระเยโฮวาห์ และเวลาเย็นก็เช่นเดียวกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 31, 'ทั้งในเวลาเมื่อถวายบรรดาเครื่องเผาบูชาแด่พระเยโฮวาห์ในวันสะบาโต ในวันขึ้นหนึ่งค่ํา ในวันเทศกาลกําหนด ตามจํานวนที่กําหนดให้ถวายบูชาต่อพระพักตร์พระเยโฮวาห์ทุกวันเรื่อยไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 32, 'ดังนี้แหละเขาจะดูแลพลับพลาแห่งชุมนุมและดูแลที่บริสุทธิ์ และจะรับใช้บุตรชายของอาโรนพี่น้องของเขา เพื่องานปรนนิบัติแห่งพระนิเวศของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 1, 'กองเวรของลูกหลานอาโรนมีดังนี้ บุตรชายของอาโรนคือ นาดับ อาบีฮู เอเลอาซาร์ และอิธามาร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 2, 'แต่นาดับและอาบีฮูสิ้นชีวิตก่อนบิดาของตนและไม่มีบุตร เอเลอาซาร์และอิธามาร์จึงทําหน้าที่ตําแหน่งปุโรหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 3, 'ด้วยความช่วยเหลือของศาโดกบุตรชายเอเลอาซาร์ และอาหิเมเลคบุตรชายอิธามาร์ ดาวิดได้ทรงจัดเป็นเวรตามหน้าที่ในการปรนนิบัติของเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 4, 'มีหัวหน้าในหมู่บุตรชายของเอเลอาซาร์มากกว่าในหมู่บุตรชายของอิธามาร์ เขาจึงจัดแบ่งดังนี้ พวกบุตรชายของเอเลอาซาร์มีสิบหกคนเป็นหัวหน้าตามเรือนบรรพบุรุษของเขา และในหมู่พวกบุตรชายของอิธามาร์ตามเรือนบรรพบุรุษของเขามีแปดคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 5, 'เขาทั้งหลายจัดแบ่งด้วยฉลาก เหมือนกันหมด เพราะมีเจ้าหน้าที่ของสถานบริสุทธิ์ และเจ้าหน้าที่แห่งพระนิเวศของพระเจ้า เป็นบุตรชายของเอเลอาซาร์กับบุตรชายของอิธามาร์ทั้งสองฝ่าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 6, 'และเชไมอาห์บุตรชายเนธันเอลอาลักษณ์ ผู้เป็นพวกเลวี ได้บันทึกไว้ต่อพระพักตร์กษัตริย์ ต่อหน้าเจ้านาย และศาโดกปุโรหิต และอาหิเมเลคบุตรชายอาบียาธาร์ และต่อหน้าประมุขของบรรพบุรุษของปุโรหิตและของคนเลวี เขาจับฉลากครอบครัวหนึ่งจากเอเลอาซาร์ และจับฉลากครอบครัวหนึ่งจากอิธามาร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 7, 'ฉลากแรกตกกับเยโฮยาริบ ที่สองตกแก่เยดายาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 8, 'ที่สามแก่ฮาริม ที่สี่แก่เสโอริม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 9, 'ที่ห้าแก่มัลคิยาห์ ที่หกแก่มิยามิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 10, 'ที่เจ็ดแก่ฮักโขส ที่แปดแก่อาบียาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 11, 'ที่เก้าแก่เยชูอา ที่สิบแก่เชคานิยาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 12, 'ที่สิบเอ็ดแก่เอลียาชีบ ที่สิบสองแก่ยาคิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 13, 'ที่สิบสามแก่หุปปาห์ ที่สิบสี่แก่เยเชเบอับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 14, 'ที่สิบห้าแก่บิลกาห์ ที่สิบหกแก่อิมเมอร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 15, 'ที่สิบเจ็ดแก่เฮซีร์ ที่สิบแปดแก่อัฟเซส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 16, 'ที่สิบเก้าแก่เปธาหิยาห์ ที่ยี่สิบแก่เยเฮเซเคล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 17, 'ที่ยี่สิบเอ็ดแก่ยาคีน ที่ยี่สิบสองแก่กามูล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 18, 'ที่ยี่สิบสามแก่เดไลยาห์ ที่ยี่สิบสี่แก่มาอาซิยาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 19, 'คนเหล่านี้มีหน้าที่กําหนดของเขาในการปรนนิบัติที่จะเข้าไปในพระนิเวศของพระเยโฮวาห์ ตามระเบียบที่อาโรนบิดาของเขาได้ตั้งไว้สําหรับเขาทั้งหลาย ดังที่พระเยโฮวาห์พระเจ้าแห่งอิสราเอลได้ทรงบัญชาเขาไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 20, 'ฝ่ายลูกหลานของเลวีที่เหลืออยู่คือ จากบุตรชายของอัมรามมี ชูบาเอล จากบุตรชายของชูบาเอลมี เยเดยาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 21, 'ฝ่ายเรหับยาห์ คือจากบุตรชายของเรหับยาห์มี อิสชีอาห์ ผู้เป็นหัวหน้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 22, 'จากคนอิสฮาร์มี เชโลโมท จากบุตรชายของเชโลโมทมี ยาหาท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 23, 'และบุตรชายของเฮโบรนคือ เยรียาห์ผู้เป็นหัวหน้า อามาริยาห์ที่สอง ยาฮาซีเอลที่สาม เยคาเมอัมที่สี่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 24, 'บุตรชายของอุสซีเอลคือ มีคาห์ บุตรชายของมีคาห์คือ ชามีร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 25, 'น้องชายของมีคาห์คือ อิสชีอาห์ บุตรชายของอิสชีอาห์คือ เศคาริยาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 26, 'บุตรชายของเมรารีคือ มาห์ลีและมูชี บุตรชายของยาอาซียาห์คือ เบโน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 27, 'ฝ่ายลูกหลานของเมรารีคือ ของยาอาซียาห์มี เบโน โชฮัม ศักเกอร์ และอิบรี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 28, 'ของมาห์ลีคือ เอเลอาซาร์ผู้ไม่มีบุตรชาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 29, 'ของคีช บุตรชายของคีชคือ เยราเมเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 30, 'บุตรชายของมูชีคือ มาห์ลี เอเดอร์ และเยรีโมท คนเหล่านี้เป็นลูกหลานของคนเลวี ตามเรือนบรรพบุรุษของเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 31, 'คนเหล่านี้คือ แต่ละหัวหน้าเรือนบรรพบุรุษ และน้องชายของเขาก็เหมือนกันได้จับฉลากด้วยอย่างเดียวกับพี่น้องของเขาคือ บุตรชายของอาโรน ต่อพระพักตร์ของกษัตริย์ดาวิด ศาโดก อาหิเมเลค และต่อประมุขของบรรพบุรุษของปุโรหิตและของคนเลวี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 1, 'ดาวิดและบรรดาหัวหน้าของผู้ปรนนิบัติได้จัดแยกบางคนไว้สําหรับการปรนนิบัติ คือจากลูกหลานของอาสาฟ และของเฮมาน และของเยดูธูน ผู้ซึ่งจะพยากรณ์ด้วยพิณเขาคู่ ด้วยพิณใหญ่และด้วยฉาบ รายชื่อของผู้ทํางานตามหน้าที่ของเขา คือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 2, 'จากลูกหลานของอาสาฟคือ ศักเกอร์ โยเซฟ เนธานิยาห์ และอาชาเรลาห์ ลูกหลานของอาสาฟ ภายใต้การนําของอาสาฟ ผู้พยากรณ์ภายใต้พระราชดํารัสสั่งของกษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 3, 'จากเยดูธูน คือลูกหลานของเยดูธูนมี เกดาลิยาห์ เศรี เยชายาห์ ฮาชาบิยาห์ และมัททีธิยาห์ หกคนภายใต้การนําของเยดูธูนบิดาของเขา ผู้พยากรณ์ด้วยพิณเขาคู่ในการโมทนาและสรรเสริญต่อพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 4, 'จากเฮมาน คือลูกหลานของเฮมานมี บุคคียาห์ มัทธานิยาห์ อุสซีเอล เชบูเอล และเยรีโมท ฮานันยาห์ ฮานานี เอลียาธาห์ กิดดาลที และโรมัมทีเอเซอร์ โยชเบคาชาห์ มัลโลธี โฮธีร์ และมาหะซิโอท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 5, 'คนเหล่านี้เป็นบุตรชายของเฮมานผู้ทํานายของกษัตริย์ตามพระวจนะของพระเจ้าเพื่อจะเป่าแตร และพระเจ้าทรงประทานบุตรชายสิบสี่คน และบุตรสาวสามคนแก่เฮมาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 6, 'เขาทั้งหลายทุกคนอยู่ภายใต้การนําของบิดาของเขาเพื่อประกอบเพลงในพระนิเวศของพระเยโฮวาห์ ด้วยฉาบ พิณใหญ่ และพิณเขาคู่ เพื่อการปรนนิบัติในพระนิเวศของพระเจ้า อาสาฟ เยดูธูน และเฮมาน อยู่ภายใต้พระราชดํารัสสั่งของกษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 7, 'จํานวนคนของเขารวมทั้งพี่น้องของเขา ผู้รับการฝึกในการร้องเพลงถวายพระเยโฮวาห์ทุกคนผู้มีความชํานาญ มีสองร้อยแปดสิบแปดคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 8, 'เขาทั้งหลายจับฉลากหน้าที่ของเขา ทั้งผู้น้อย ผู้ใหญ่ ครูและศิษย์ก็เหมือนกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 9, 'ฉลากแรกตกเป็นพวกของอาสาฟได้แก่โยเซฟ ที่สองได้แก่เกดาลิยาห์ พร้อมกับพี่น้องและบุตรชายของเขา สิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 10, 'ที่สามตกแก่ศักเกอร์ พร้อมกับบุตรชายของเขาและพี่น้องของเขา สิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 11, 'ที่สี่ได้แก่อิสรี พร้อมกับบุตรชายของเขาและพี่น้องของเขา สิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 12, 'ที่ห้าได้แก่เนธานิยาห์ พร้อมกับบุตรชายของเขาและพี่น้องของเขา สิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 13, 'ที่หกได้แก่บุคคียาห์ พร้อมกับบุตรชายของเขาและพี่น้องของเขา สิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 14, 'ที่เจ็ดได้แก่เยชาเรลาห์ พร้อมกับบุตรชายของเขาและพี่น้องของเขา สิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 15, 'ที่แปดได้แก่เยชายาห์ พร้อมกับบุตรชายของเขาและพี่น้องของเขา สิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 16, 'ที่เก้าได้แก่มัทธานิยาห์ พร้อมกับบุตรชายของเขาและพี่น้องของเขา สิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 17, 'ที่สิบได้แก่ชิเมอี พร้อมกับบุตรชายของเขาและพี่น้องของเขา สิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 18, 'ที่สิบเอ็ดได้แก่อาซาเรล พร้อมกับบุตรชายของเขาและพี่น้องของเขา สิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 19, 'ที่สิบสองได้แก่ฮาชาบิยาห์ พร้อมกับบุตรชายของเขาและพี่น้องของเขา สิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 20, 'ที่สิบสามได้แก่ชูบาเอล พร้อมกับบุตรชายของเขาและพี่น้องของเขา สิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 21, 'ที่สิบสี่ได้แก่มัททีธิยาห์ พร้อมกับบุตรชายของเขาและพี่น้องของเขา สิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 22, 'ที่สิบห้าได้แก่เยรีโมท พร้อมกับบุตรชายของเขาและพี่น้องของเขา สิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 23, 'ที่สิบหกได้แก่ฮานันยาห์ พร้อมกับบุตรชายของเขาและพี่น้องของเขา สิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 24, 'ที่สิบเจ็ดได้แก่โยชเบคาชาห์ พร้อมกับบุตรชายของเขาและพี่น้องของเขา สิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 25, 'ที่สิบแปดได้แก่ฮานานี พร้อมกับบุตรชายของเขาและพี่น้องของเขา สิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 26, 'ที่สิบเก้าได้แก่มัลโลธี พร้อมกับบุตรชายของเขาและพี่น้องของเขา สิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 27, 'ที่ยี่สิบได้แก่เอลียาธาห์ พร้อมกับบุตรชายของเขาและพี่น้องของเขา สิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 28, 'ที่ยี่สิบเอ็ดได้แก่โฮธีร์ พร้อมกับบุตรชายของเขาและพี่น้องของเขา สิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 29, 'ที่ยี่สิบสองได้แก่กิดดาลที พร้อมกับบุตรชายของเขาและพี่น้องของเขา สิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 30, 'ที่ยี่สิบสามได้แก่มาหะซิโอท พร้อมกับบุตรชายของเขาและพี่น้องของเขา สิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 31, 'ที่ยี่สิบสี่ได้แก่โรมัมทีเอเซอร์ พร้อมกับบุตรชายของเขาและพี่น้องของเขา สิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 1, 'ฝ่ายกองเวรเฝ้าประตู จากคนโคราห์มี เมเชเลมิยาห์บุตรชายโคเร เป็นลูกหลานของอาสาฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 2, 'และเมเชเลมิยาห์มีบุตรชายคือ เศคาริยาห์ บุตรหัวปี เยดียาเอล ที่สอง เศบาดิยาห์ ที่สาม ยาทนีเอล ที่สี่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 3, 'เอลาม ที่ห้า เยโฮฮานัน ที่หก เอลีโอนัย ที่เจ็ด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 4, 'และโอเบดเอโดมมีบุตรชายคือ เชไมอาห์ บุตรหัวปี เยโฮซาบาด ที่สอง โยอาห์ ที่สาม สาคาร์ ที่สี่ เนธันเอล ที่ห้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 5, 'อัมมีเอล ที่หก อิสสาคาร์ ที่เจ็ด เปอุลเลธัย ที่แปด เพราะว่าพระเจ้าทรงอํานวยพระพรแก่เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 6, 'และแก่เชไมอาห์บุตรชายของเขาด้วย มีบุตรชายหลายคนเกิดแก่เขา เป็นผู้ปกครองในครัวเรือนบิดาของเขา เพราะเขาทั้งหลายเป็นคนมีอํานาจใหญ่โตและกล้าหาญ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 7, 'บุตรชายของเชไมอาห์คือ โอทนี เรฟาเอล โอเบด และเอลซาบาด ผู้ซึ่งพี่น้องของเขาเป็นคนมีกําลังคือ เอลีฮู และเสมาคิยาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 8, 'คนเหล่านี้ทั้งหมดเป็นบุตรชายของโอเบดเอโดมกับบุตรชายและพี่น้องของเขา เป็นคนสามารถมีกําลังเหมาะแก่การปรนนิบัติ เป็นของโอเบดเอโดมหกสิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 9, 'และเมเชเลมิยาห์มีบุตรชายและพี่น้องเป็นคนมีกําลังสิบแปดคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 10, 'และโฮสาห์ผู้เป็นลูกหลานของเมรารีมีบุตรชายคือ ชิมรี ผู้เป็นหัวหน้า (เพราะถึงเขาจะไม่เป็นบุตรหัวปี บิดาของเขาก็ให้เขาเป็นหัวหน้า)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 11, 'ฮิลคียาห์ ที่สอง เทบาลิยาห์ ที่สาม เศคาริยาห์ ที่สี่ บุตรชายและพี่น้องของโฮสาห์ทั้งสิ้น มีสิบสามคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 12, 'กองเวรเฝ้าประตูเหล่านี้ตามคนผู้เป็นหัวหน้าของเขา มีหน้าที่เช่นเดียวกับพี่น้องของเขา ในการปรนนิบัติในพระนิเวศของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 13, 'และเขาจับฉลากกันตามเรือนบรรพบุรุษของเขา ทั้งผู้ใหญ่และผู้น้อยเหมือนกัน สําหรับใครอยู่ประตูไหน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 14, 'ฉลากสําหรับด้านตะวันออกตกแก่เชเลมิยาห์ เขาจับฉลากให้บุตรชายของเขาคือเศคาริยาห์ด้วย เขาเป็นที่ปรึกษาที่เฉลียวฉลาด และฉลากของเขาออกมาสําหรับด้านเหนือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 15, 'ของโอเบดเอโดมออกมาสําหรับด้านใต้ คลังพัสดุนั้นเขาจัดให้บุตรชายของเขาดูแล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 16, 'ส่วนของชุปปิมและโฮสาห์ ออกมาสําหรับด้านตะวันตก ที่ประตูชัลเลเคท ตามถนนที่ขึ้นไป กําหนดยามตามยาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 17, 'ด้านตะวันออกมีคนเลวีหกคน ด้านเหนือมีสี่คนทุกวัน ด้านใต้วันละสี่คนทุกวัน และสองคู่ที่คลังพัสดุ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 18, 'สําหรับระเบียงทางตะวันตกนั้น มีสี่คนที่ถนนและสองคนที่ระเบียง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 19, 'คนเหล่านี้เป็นเวรเฝ้าประตูจากลูกหลานของโคราห์ และลูกหลานของเมรารี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 20, 'จากคนเลวีนั้น อาหิยาห์ดูแลคลังพระนิเวศของพระเจ้า และคลังสิ่งของถวาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 21, 'ลูกหลานของลาดานคือ ลูกหลานของคนเกอร์โชน ที่เป็นบุตรชายของลาดาน บรรดาหัวหน้าของลาดาน คนเกอร์โชนคือ เยฮีเอลี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 22, 'บุตรชายของเยฮีเอลีคือ เศธามและโยเอลน้องชายของเขา เป็นผู้ดูแลคลังพระนิเวศของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 23, 'จากคนอัมราม คนอิสฮาร์ คนเฮโบรน และคนอุสซีเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 24, 'และเชบูเอล บุตรชายของเกอร์โชม ผู้เป็นบุตรชายของโมเสส เป็นนายคลังใหญ่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 25, 'พี่น้องของเขาคือ จากเอลีเยเซอร์มี เรหับยาห์เป็นบุตรชาย บุตรชายของเรหับยาห์คือ เยชายาห์ บุตรชายของเยชายาห์คือ โยรัม บุตรชายของโยรัมคือ ศิครี บุตรชายของศิครีคือ เชโลมิท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 26, 'เชโลมิทคนนี้และพี่น้องของเขาเป็นผู้ดูแลคลังของถวายทั้งสิ้น ซึ่งกษัตริย์ดาวิด และบรรดาหัวหน้า และนายพันนายร้อย และผู้บัญชาการกองทัพได้มอบถวายไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 27, 'จากของที่ริบได้ซึ่งเขาได้ในสงคราม เขาทั้งหลายมอบถวายเพื่อแก่การซ่อมแซมพระนิเวศของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 28, 'และทุกสิ่งซึ่งซามูเอลผู้ทํานาย และซาอูลบุตรชายคีช และอับเนอร์บุตรชายเนอร์ และโยอาบบุตรชายนางเศรุยาห์ได้ถวายไว้ และผู้ใดก็ตามได้ถวายสิ่งใด ของถวายทั้งสิ้นก็อยู่ในความดูแลของเชโลมิทและพี่น้องของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 29, 'จากคนอิสฮาร์ เคนานิยาห์และบุตรชายของเขาได้รับแต่งตั้งให้มีหน้าที่ภายนอกสําหรับอิสราเอล ให้เป็นเจ้าหน้าที่และเป็นผู้วินิจฉัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 30, 'จากคนเฮโบรน ฮาชาบิยาห์และพี่น้องของเขาเป็นคนมีความกล้าหาญ หนึ่งพันเจ็ดร้อยคน ได้เป็นผู้ดูแลอิสราเอลทางฟากตะวันตกของแม่น้ําจอร์แดนข้างโน้น ในเรื่องกิจการทั้งสิ้นของพระเยโฮวาห์ และราชการของกษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 31, 'จากคนเฮโบรนมี เยรียาห์เป็นหัวหน้าของคนเฮโบรน ตามพงศ์พันธุ์ ตามบรรพบุรุษ ในปีที่สี่สิบของรัชกาลดาวิด เขาได้สํารวจและพบคนที่มีอํานาจใหญ่โตและกล้าหาญที่ยาเซอร์ในเมืองกิเลอาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 32, 'กษัตริย์ดาวิดได้ทรงแต่งตั้งให้ท่านและพี่น้องของท่าน คือคนกล้าหาญสองพันเจ็ดร้อยคนผู้เป็นหัวหน้า ให้เป็นผู้ดูแลคนรูเบน คนกาด และคนตระกูลมนัสเสห์ครึ่งหนึ่ง ในกิจธุระทุกอย่างเกี่ยวกับพระเจ้า และกิจธุระเกี่ยวกับกษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 1, 'ต่อไปนี้เป็นรายชื่อประชาชนอิสราเอลตามจํานวน คือ บรรดาหัวหน้า บรรดานายพันนายร้อย และบรรดาเจ้าหน้าที่ผู้รับใช้กษัตริย์ในราชการทุกอย่างที่เกี่ยวกับกองเวรที่เข้ามาและออกไป เดือนแล้วเดือนเล่าตลอดปี กองเวรหนึ่งๆมีจํานวนสองหมื่นสี่พันคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 2, 'คือ ยาโชเบอัมบุตรชายศับดีเอล เป็นผู้ดูแลกองเวรที่หนึ่งในเดือนต้น ในกองเวรของเขามีสองหมื่นสี่พันคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 3, 'เขาเป็นลูกหลานของเปเรศ และเป็นหัวหน้าผู้บัญชาการกองทัพทั้งสิ้นในเดือนต้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 4, 'โดดัยคนอาโหอาห์ เป็นผู้ดูแลกองเวรของเดือนที่สอง มิกโลทเป็นผู้บังคับบัญชากองเวรของเขา ในกองเวรของเขามีสองหมื่นสี่พันคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 5, 'ผู้บังคับบัญชาการกองทัพคนที่สามสําหรับเดือนที่สามคือ เบไนยาห์บุตรชายเยโฮยาดา เป็นปุโรหิตใหญ่ ในกองเวรของเขามีสองหมื่นสี่พันคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 6, 'เบไนยาห์นี้คือ ผู้ที่เป็นทแกล้วทหารในสามสิบคน และเป็นผู้บัญชาการของสามสิบคนนั้น อัมมีซาบาดบุตรชายของเขาเป็นผู้ดูแลกองเวรของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 7, 'อาสาเฮลน้องชายของโยอาบเป็นผู้บัญชาการคนที่สี่สําหรับเดือนที่สี่ และเศบาดิยาห์บุตรชายของเขาดูแลต่อจากเขา ในกองเวรของเขามีสองหมื่นสี่พันคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 8, 'ผู้บัญชาการคนที่ห้าสําหรับเดือนที่ห้าคือ ชัมหุทคนอิสราห์ ในกองเวรของเขามีสองหมื่นสี่พันคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 9, 'ผู้บัญชาการคนที่หกสําหรับเดือนที่หกคือ อิราบุตรชายอิกเขชชาวเทโคอา ในกองเวรของเขามีสองหมื่นสี่พันคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 10, 'ผู้บัญชาการคนที่เจ็ดสําหรับเดือนที่เจ็ดคือ เฮเลสคนเปโลน เป็นคนเอฟราอิม ในกองเวรของเขามีสองหมื่นสี่พันคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 11, 'ผู้บัญชาการคนที่แปดสําหรับเดือนที่แปดคือ สิบเบคัยคนหุชาห์แห่งคนเศ-ราห์ ในกองเวรของเขามีสองหมื่นสี่พันคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 12, 'ผู้บัญชาการคนที่เก้าสําหรับเดือนที่เก้าคือ อาบีเยเซอร์ชาวอานาโธทคนเบนยามิน ในกองเวรของเขามีสองหมื่นสี่พันคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 13, 'ผู้บัญชาการคนที่สิบสําหรับเดือนที่สิบคือ มาหะรัยชาวเนโทฟาห์จากคนเศ-ราห์ ในกองเวรของเขามีสองหมื่นสี่พันคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 14, 'ผู้บัญชาการคนที่สิบเอ็ดสําหรับเดือนที่สิบเอ็ดคือ เบไนยาห์ชาวปิราโธนจากคนเอฟราอิม ในกองเวรของเขามีสองหมื่นสี่พันคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 15, 'ผู้บัญชาการคนที่สิบสองสําหรับเดือนที่สิบสองคือ เฮลดัยชาวเนโทฟาห์จากคนโอทนีเอล ในกองเวรของเขามีสองหมื่นสี่พันคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 16, 'เหนือตระกูลต่างๆของอิสราเอลคือ สําหรับคนรูเบนมี เอลีเยเซอร์บุตรชายศิครีเป็นประมุข สําหรับคนสิเมโอนมี เชฟาทิยาห์บุตรชายมาอาคาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 17, 'สําหรับคนเลวีมี ฮาชาบิยาห์บุตรชายเคมูเอล สําหรับคนอาโรนมี ศาโดก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 18, 'สําหรับคนยูดาห์มี เอลีฮู พี่ชายคนหนึ่งของดาวิด สําหรับคนอิสสาคาร์มี อมรีบุตรชายมีคาเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 19, 'สําหรับคนเศบูลุนมี อิชมัยอาห์บุตรชายโอบาดีห์ สําหรับคนนัฟทาลีมี เยรีโมทบุตรชายอัซรีเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 20, 'สําหรับคนเอฟราอิมมี โฮเชยาบุตรชายอาซาซิยาห์ สําหรับคนมนัสเสห์ครึ่งตระกูลมี โยเอลบุตรชายเปดายาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 21, 'สําหรับคนมนัสเสห์ครึ่งตระกูลในกิเลอาดมี อิดโดบุตรชายเศคาริยาห์ สําหรับคนเบนยามินมี ยาอาสีเอลบุตรชายอับเนอร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 22, 'สําหรับคนดานมี อาซาเรลบุตรชายเยโรฮัม คนเหล่านี้เป็นประมุขของตระกูลต่างๆแห่งอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 23, 'ดาวิดมิได้ทรงนับจํานวนคนที่อายุต่ํากว่ายี่สิบปี เพราะพระเยโฮวาห์ได้ตรัสไว้ว่าจะกระทําให้อิสราเอลมากเหมือนดาวแห่งท้องฟ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 24, 'โยอาบบุตรชายนางเศรุยาห์ได้ตั้งต้นนับ แต่ไม่สําเร็จ เพราะพระพิโรธก็มาเหนืออิสราเอลในเรื่องนี้ และจํานวนนั้นก็มิได้ลงไว้ในหนังสือพงศาวดารของกษัตริย์ดาวิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 25, 'อัสมาเวทบุตรชายอาดีเอลเป็นเจ้ากรมพระคลังนครหลวง และเยโฮนาธันบุตรชายของอุสซียาห์ เป็นเจ้ากรมคลังนอกนคร ในหัวเมือง ในชนบทและในป้อม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 26, 'เอสรีบุตรชายเคลูบ เป็นผู้ดูแลบรรดาผู้ที่ทําไร่นาหลวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 27, 'ชิเมอีชาวรามาห์ดูแลสวนองุ่น และศับดีชาวเชฟามดูแลผลิตผลของสวนองุ่นสําหรับห้องเก็บน้ําองุ่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 28, 'บาอัลฮานันชาวเกเดอร์เป็นผู้ดูแลต้นมะกอกเทศและต้นมะเดื่อที่ในหุบเขา โยอาชดูแลคลังน้ํามัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 29, 'ชิตรัยชาวชาโรนดูแลฝูงวัวซึ่งหากินอยู่ในชาโรน ชาฟัทบุตรชายอัดลัยดูแลฝูงวัวในหุบเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 30, 'และโอบิลคนอิชมาเอลดูแลอูฐ เยเดยาห์ชาวเมโรโนทดูแลลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 31, 'ยาซีสชาวฮาการ์ดูแลฝูงแพะแกะ บรรดาคนเหล่านี้เป็นพนักงานดูแลทรัพย์สมบัติของกษัตริย์ดาวิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 32, 'โยนาธานลุงของดาวิดเป็นที่ปรึกษา เป็นคนที่มีความเข้าใจและเป็นอาลักษณ์ และเยฮีเอลบุตรชายฮักโมนีเป็นผู้เลี้ยงดูราชโอรส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 33, 'อาหิโธเฟลเป็นที่ปรึกษาของกษัตริย์ และหุชัยคนอารคีเป็นพระสหายของกษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 34, 'เยโฮยาดาบุตรชายเบไนยาห์และอาบียาธาร์เป็นผู้ทํางานต่อจากอาหิโธเฟล โยอาบเป็นผู้บัญชาการกองทัพของกษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 1, 'ณ เยรูซาเล็ม ดาวิดได้ทรงเรียกประชุมบรรดาเจ้านายทั้งสิ้นของอิสราเอล คือเจ้านายของตระกูล และผู้บัญชาการกองทัพที่รับราชการตามเวร นายพันนายร้อย และพนักงานผู้ดูแลบรรดาทรัพย์สมบัติและสิ่งของทั้งสิ้นของกษัตริย์และโอรสของพระองค์ พร้อมกับพนักงานราชสํานัก ทแกล้วทหารและวีรบุรุษทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 2, 'แล้วกษัตริย์ดาวิดทรงลุกขึ้นประทับยืน และตรัสว่า “พี่น้องของข้าพเจ้า และประชาชนของข้าพเจ้า ขอจงฟังข้าพเจ้า ข้าพเจ้ามีใจประสงค์ที่จะสร้างพระนิเวศอันเป็นที่พักของหีบพันธสัญญาของพระเยโฮวาห์ และเพื่อเป็นที่รองพระบาทของพระเจ้าของเรา และข้าพเจ้าได้จัดเตรียมการก่อสร้างไว้เสร็จแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 3, 'แต่พระเจ้าตรัสกับข้าพเจ้าว่า ‘เจ้าอย่าสร้างนิเวศเพื่อนามของเราเลย เพราะเจ้าเป็นนักรบและได้ทําโลหิตให้ตก’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 4, 'ถึงกระนั้นก็ดีพระเยโฮวาห์พระเจ้าแห่งอิสราเอลทรงเลือกข้าพเจ้าจากเรือนบรรพบุรุษของข้าพเจ้าทั้งหมด ให้เป็นกษัตริย์เหนืออิสราเอลเป็นนิตย์ เพราะพระองค์ทรงเลือกยูดาห์ให้เป็นประมุข และในวงศ์วานของยูดาห์ เรือนบรรพบุรุษของข้าพเจ้า และในบรรดาบุตรชายของบิดาข้าพเจ้า พระองค์ทรงพอพระทัยในข้าพเจ้า และทรงให้ข้าพเจ้าเป็นกษัตริย์เหนืออิสราเอลทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 5, 'และบุตรชายทั้งสิ้นของข้าพเจ้า (เพราะพระเยโฮวาห์ทรงประทานบุตรชายเป็นอันมากแก่ข้าพเจ้า) พระองค์ทรงเลือกซาโลมอนบุตรชายของข้าพเจ้าให้นั่งบัลลังก์แห่งราชอาณาจักรของพระเยโฮวาห์เหนืออิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 6, 'พระองค์ตรัสกับข้าพเจ้าว่า ‘ซาโลมอนบุตรชายของเจ้าจะสร้างนิเวศของเราและลานนิเวศของเรา เพราะเราได้เลือกเขาให้เป็นลูกของเรา และเราจะเป็นพ่อของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 7, 'เราจะสถาปนาราชอาณาจักรของเขาให้อยู่เป็นนิตย์ ถ้าเขาจะเพียรแน่วแน่อยู่ในการรักษาปฏิบัติตามบัญญัติของเราและคําตัดสินของเราอย่างที่เขาทําอยู่ในวันนี้’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 8, 'เพราะฉะนั้นบัดนี้ท่ามกลางสายตาของคนอิสราเอลทั้งปวงอันเป็นชุมนุมชนของพระเยโฮวาห์ และต่อพระกรรณของพระเจ้าของเรา จงรักษาและแสวงหาพระบัญญัติทั้งสิ้นของพระเยโฮวาห์พระเจ้าของเจ้าทั้งหลาย เพื่อเจ้าจะได้กรรมสิทธิ์แผ่นดินอันดีนี้ และมอบไว้ให้เป็นมรดกของลูกหลานผู้มาภายหลังเจ้าสืบไปเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 9, 'ซาโลมอนบุตรของเราเอ๋ย เจ้าจงรู้จักพระเจ้าของบิดาเจ้า และจงปรนนิบัติพระองค์ด้วยใจจริงและด้วยความเต็มใจของเจ้า เพราะพระเยโฮวาห์ทรงพิจารณาจิตใจทั้งปวง และทรงเข้าใจในแผนงานแห่งความคิดทั้งปวง ถ้าเจ้าแสวงหาพระองค์ เจ้าจะพบพระองค์ แต่ถ้าเจ้าทอดทิ้งพระองค์ พระองค์จะทรงเหวี่ยงเจ้าออกไปเสียเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 10, 'บัดนี้จงฟังให้ดี เพราะว่าพระเยโฮวาห์ทรงเลือกเจ้าให้สร้างพระนิเวศเพื่อเป็นสถานบริสุทธิ์ จงเข้มแข็งและทําให้สําเร็จเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 11, 'แล้วดาวิดทรงมอบให้กับซาโลมอนโอรสของพระองค์ ซึ่งแผนผังมุขของพระวิหารและแผนผังเรือนต่างๆของพระวิหารนั้น คลังและห้องชั้นบน และห้องชั้นใน และห้องสําหรับพระที่นั่งกรุณา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 12, 'และแผนผังทั้งสิ้นซึ่งพระองค์มีอยู่ในพระทัย ในเรื่องลานของพระนิเวศของพระเยโฮวาห์ และบรรดาห้องระเบียงรอบ และคลังสําหรับพระนิเวศของพระเจ้า และคลังสําหรับบรรดาของถวาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 13, 'และผังสําหรับเวรปุโรหิตและคนเลวี และงานปรนนิบัติทั้งสิ้นในพระนิเวศของพระเยโฮวาห์ และสําหรับบรรดาเครื่องใช้ในงานปรนนิบัติในพระนิเวศของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 14, 'พระองค์ทรงมอบน้ําหนักทองคําของเครื่องใช้ทองคําทุกอย่างสําหรับการปรนนิบัติแต่ละอย่าง น้ําหนักเงินของเครื่องใช้เงินทุกอย่างสําหรับงานปรนนิบัติแต่ละอย่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 15, 'น้ําหนักของเชิงประทีปทองคําและตะเกียงทองคํา น้ําหนักของเชิงประทีปแต่ละคันกับตะเกียงแต่ละดวง น้ําหนักเงินของเชิงประทีป ทั้งเชิงประทีปกับตะเกียงนั้น ตามที่จะใช้คันประทีปแต่ละคัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 16, 'น้ําหนักทองคําสําหรับโต๊ะขนมปังหน้าพระพักตร์แต่ละโต๊ะ เงินสําหรับโต๊ะเงิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 17, 'และขอเกี่ยวเนื้อ ชาม กับคนโทเป็นทองคําบริสุทธิ์ ชามทองคําและน้ําหนักทองคําของแต่ละใบ ชามเงินและน้ําหนักเงินของแต่ละใบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 18, 'แท่นเครื่องหอมทําด้วยทองคําเนื้อละเอียดและน้ําหนักของแท่นนั้น ทั้งแผนผังสําหรับรถรบทองคําของเครูบ ซึ่งกางปีกออกปกหีบพันธสัญญาของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 19, 'ดาวิดตรัสว่า “สิ่งทั้งปวงเหล่านี้พระเยโฮวาห์ทรงกระทําให้ข้าพเจ้าเข้าใจโดยอาศัยลายพระหัตถ์ของพระองค์เหนือข้าพเจ้า คืองานทุกอย่างซึ่งจะต้องกระทําตามแผนผังนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 20, 'แล้วดาวิดตรัสกับซาโลมอนโอรสของพระองค์ว่า “จงเข้มแข็งและกล้าหาญ และทําให้สําเร็จเถิด อย่ากลัวเลย อย่าขยาด เพราะว่าพระเยโฮวาห์พระเจ้า คือพระเจ้าของข้าจะทรงสถิตกับเจ้า พระองค์จะไม่ทรงปล่อยให้เจ้าล้มเหลวหรือทอดทิ้งเจ้า จนกว่างานทั้งสิ้นสําหรับงานปรนนิบัติแห่งพระนิเวศของพระเยโฮวาห์จะสําเร็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 21, 'ดูเถิด มีเวรปุโรหิตและคนเลวี จะอยู่กับเจ้าสําหรับงานปรนนิบัติทุกอย่างแห่งพระนิเวศของพระเจ้า ในการนี้ทั้งสิ้นจะมีคนอยู่กับเจ้า คือทุกคนที่เต็มใจ และเป็นผู้มีฝีมือในงานปรนนิบัติทุกอย่าง ทั้งประมุขและประชาชนทั้งปวงจะอยู่ในบังคับบัญชาของเจ้าทั้งสิ้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 1, 'และกษัตริย์ดาวิดตรัสกับชุมนุมชนทั้งสิ้นว่า “ซาโลมอนบุตรชายของเรา ซึ่งเป็นผู้เดียวที่พระเจ้าทรงเลือกไว้นั้น ยังเป็นคนหนุ่มและไม่มีความชํานาญ การงานก็ใหญ่โต เพราะว่ามหานิเวศนั้นมิใช่สําหรับคน แต่สําหรับพระเยโฮวาห์พระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 2, 'เพราะฉะนั้นเราจึงจัดเตรียมไว้สําหรับพระนิเวศของพระเจ้าของเรา เต็มความสามารถของเรา คือทองคําสําหรับสิ่งที่ทําด้วยทองคํา และเงินสําหรับสิ่งที่ทําด้วยเงิน และทองเหลืองสําหรับสิ่งที่ทําด้วยทองเหลือง และเหล็กสําหรับสิ่งที่ทําด้วยเหล็ก และไม้สําหรับสิ่งที่ทําด้วยไม้ มีพลอยสีน้ําข้าว และพลอยสําหรับฝัง พลวง หินลาย เพชรพลอยทุกชนิดและหินอ่อนมากมาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 3, 'ยิ่งกว่านั้นอีกนอกจากสิ่งทั้งปวงที่เราจัดหาไว้สําหรับนิเวศบริสุทธิ์แล้ว เรายังมีทองคําและเงินเป็นสมบัติของเราเอง และเพราะความรักของเราที่มีต่อพระนิเวศของพระเจ้าของเรา เรามอบให้แก่พระนิเวศแห่งพระเจ้าของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 4, 'ดังนี้ ทองคําสามพันตะลันต์ เป็นทองคําเมืองโอฟีร์ และเงินถลุงแล้วเจ็ดพันตะลันต์เพื่อจะบุผนังพระนิเวศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 5, 'ทองคําสําหรับสิ่งที่ทําด้วยทองคํา และเงินสําหรับสิ่งที่ทําด้วยเงิน และเพื่องานทั้งสิ้นที่ช่างจะต้องทําด้วยมือ ใครบ้างเต็มใจที่จะถวายของพร้อมกับถวายตัวแด่พระเยโฮวาห์ในวันนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 6, 'แล้วเจ้านายของบรรพบุรุษ บรรดาประมุขของตระกูลแห่งอิสราเอล ทั้งนายพันนายร้อย และพนักงานดูแลราชการก็ถวายด้วยความเต็มใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 7, 'เขาทั้งหลายถวายเพื่องานปรนนิบัติแห่งพระนิเวศของพระเจ้า เป็นทองคําห้าพันตะลันต์ และหนึ่งหมื่นดาริค เงินหนึ่งหมื่นตะลันต์ ทองเหลืองหนึ่งหมื่นแปดพันตะลันต์ และเหล็กหนึ่งแสนตะลันต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 8, 'ผู้ใดที่มีเพชรพลอยก็ถวายไว้ที่คลังพระนิเวศของพระเยโฮวาห์ ในความดูแลของเยฮีเอลคนเกอร์โชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 9, 'แล้วประชาชนก็เปรมปรีดิ์ เพราะเขาถวายสิ่งเหล่านี้ตามความสมัครใจของเขา เพราะเขาถวายด้วยความจริงใจและความเต็มใจแด่พระเยโฮวาห์ กษัตริย์ดาวิดก็ทรงเปรมปรีดิ์เป็นที่ยิ่งด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 10, 'เพราะฉะนั้นดาวิดจึงสรรเสริญพระเยโฮวาห์ต่อหน้าชุมนุมชนทั้งปวง และดาวิดทูลว่า “ข้าแต่พระเยโฮวาห์พระเจ้าแห่งอิสราเอลบรรพบุรุษของข้าพระองค์ทั้งหลาย สาธุการแด่พระองค์เป็นนิตย์และเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 11, 'โอ ข้าแต่พระเยโฮวาห์ ความยิ่งใหญ่ ฤทธานุภาพ สง่าราศี ชัยชนะ และความโอ่อ่าตระการเป็นของพระองค์ และบรรดาสิ่งที่มีอยู่ในฟ้าสวรรค์และในแผ่นดินโลกเป็นของพระองค์ โอ ข้าแต่พระเยโฮวาห์ ราชอาณาจักรเป็นของพระองค์ และพระองค์ทรงเป็นที่ยกย่องเป็นจอมของสิ่งสารพัด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 12, 'ทั้งความมั่งคั่งและเกียรติมาจากพระองค์ และพระองค์ทรงครอบครองอยู่เหนือทุกสิ่ง ฤทธานุภาพและมหิทธิฤทธิ์อยู่ในพระหัตถ์ของพระองค์ และอยู่ที่พระหัตถ์ของพระองค์ที่จะทรงกระทําให้ใหญ่ยิ่งและประทานกําลังแก่คนทั้งมวล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 13, 'ฉะนั้นบัดนี้ข้าพระองค์ทั้งหลายโมทนาพระคุณพระองค์ผู้เป็นพระเจ้าของข้าพระองค์ และสรรเสริญพระนามอันรุ่งโรจน์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 14, 'แต่ข้าพระองค์เป็นผู้ใด และชนชาติของข้าพระองค์เป็นผู้ใด ที่ข้าพระองค์ทั้งหลายจะสามารถถวายแด่พระองค์ด้วยความเต็มใจเช่นนี้ เพราะว่าสิ่งของทุกอย่างมาจากพระองค์ ข้าพระองค์ทั้งหลายได้ถวายของที่เป็นของพระองค์แด่พระองค์เท่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 15, 'เพราะว่าข้าพระองค์ทั้งหลายเป็นคนต่างด้าวต่างแดนต่อพระพักตร์พระองค์ และเป็นคนอาศัยอยู่ชั่วคราว ดังที่บรรพบุรุษของข้าพระองค์ได้เป็นอย่างนั้นมาแล้ว วันปีของข้าพระองค์บนแผ่นดินโลกเป็นเหมือนเงา และไม่มีอะไรจีรัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 16, 'โอ ข้าแต่พระเยโฮวาห์พระเจ้าของข้าพระองค์ทั้งหลาย ของมากมายเหล่านี้ทั้งสิ้นซึ่งข้าพระองค์จัดหาเพื่อสร้างพระนิเวศถวายแด่พระองค์เพื่อพระนามบริสุทธิ์ของพระองค์ มาจากพระหัตถ์ของพระองค์ และเป็นของพระองค์ทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 17, 'ข้าแต่พระเจ้าของข้าพระองค์ ข้าพระองค์ทราบแน่ว่า พระองค์ทรงทดลองจิตใจ และทรงพอพระทัยในความเที่ยงธรรม ส่วนข้าพระองค์ ข้าพระองค์ได้ถวายทุกสิ่งเหล่านี้ทั้งสิ้นด้วยความเต็มใจในความเที่ยงธรรมแห่งจิตใจของข้าพระองค์ และบัดนี้ข้าพระองค์ชื่นใจที่ได้เห็นประชาชนของพระองค์ ผู้ซึ่งอยู่ ณ ที่นี้ได้เต็มใจถวายแด่พระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 18, 'โอ ข้าแต่พระเยโฮวาห์พระเจ้าของอับราฮัม อิสอัคและอิสราเอลบรรพบุรุษของข้าพระองค์ทั้งหลาย ขอพระองค์ทรงรักษาความประสงค์แห่งความคิดในใจของประชาชนของพระองค์ให้เป็นเช่นนี้เสมอไป และขอทรงตั้งจิตใจของเขาทั้งหลายให้มั่นในพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 19, 'ขอพระองค์ทรงโปรดซาโลมอนบุตรชายของข้าพระองค์ให้มีจิตใจจริงที่จะรักษาบรรดาพระบัญญัติของพระองค์ พระโอวาทของพระองค์ และกฎเกณฑ์ของพระองค์ และให้กระทําทุกอย่างเหล่านี้ และสร้างนิเวศตามซึ่งข้าพระองค์ได้ตระเตรียมไว้แล้วนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 20, 'แล้วดาวิดตรัสกับชุมนุมชนทั้งปวงว่า “จงถวายสาธุการแด่พระเยโฮวาห์พระเจ้าของท่านทั้งหลาย” และชุมนุมชนทั้งปวงก็สรรเสริญพระเยโฮวาห์พระเจ้าแห่งบรรพบุรุษของเขาทั้งหลาย และก้มศีรษะของเขาทั้งหลายลงและนมัสการพระเยโฮวาห์ และถวายบังคมแด่กษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 21, 'และเขาทั้งหลายได้ถวายสัตวบูชาแด่พระเยโฮวาห์ และถวายเครื่องเผาบูชาแด่พระเยโฮวาห์ในวันรุ่งขึ้นต่อจากวันนั้น เป็นวัวผู้หนึ่งพันตัว แกะผู้หนึ่งพันตัว ลูกแกะหนึ่งพันตัว พร้อมกับเครื่องดื่มบูชาที่คู่กัน และถวายสัตวบูชาอย่างมากมายเพื่ออิสราเอลทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 22, 'และเขาทั้งหลายได้กินได้ดื่มต่อพระพักตร์พระเยโฮวาห์ในวันนั้นด้วยความยินดียิ่ง และเขาทั้งหลายได้ตั้งซาโลมอนโอรสของดาวิดเป็นกษัตริย์เป็นคํารบสอง และเขาทั้งหลายได้เจิมท่านไว้ให้เป็นเจ้านายเพื่อพระเยโฮวาห์ และศาโดกให้เป็นปุโรหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 23, 'แล้วซาโลมอนทรงประทับบนพระที่นั่งของพระเยโฮวาห์เป็นกษัตริย์แทนดาวิดราชบิดาของพระองค์ และพระองค์ทรงเจริญขึ้น และอิสราเอลทั้งปวงก็เชื่อฟังพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 24, 'บรรดาประมุขทั้งปวง และทแกล้วทหารทั้งหลาย ทั้งบรรดาโอรสของกษัตริย์ดาวิดได้ปฏิญาณตัวต่อกษัตริย์ซาโลมอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 25, 'และพระเยโฮวาห์ทรงให้ซาโลมอนมีเกียรติยศอย่างเหลือล้นท่ามกลางสายตาของอิสราเอลทั้งปวง และทรงประทานความสง่าผ่าเผยของกษัตริย์แก่พระองค์ อย่างที่ไม่มีกษัตริย์องค์ใดในอิสราเอลที่มาก่อนพระองค์ได้รับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 26, 'ฝ่ายดาวิดบุตรชายเจสซีได้ครอบครองเหนืออิสราเอลทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 27, 'เวลาที่พระองค์ทรงครอบครองเหนืออิสราเอลนั้นเป็นสี่สิบปี พระองค์ทรงครอบครองในเฮโบรนเจ็ดปี และทรงครอบครองในเยรูซาเล็มสามสิบสามปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 28, 'แล้วพระองค์สิ้นพระชนม์เมื่อทรงพระชรามาก หง่อมแล้ว ทั้งทรงมั่งคั่งและมีพระเกียรติ และซาโลมอนโอรสของพระองค์ครอบครองแทนพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 29, 'ส่วนพระราชกิจของกษัตริย์ดาวิด ตั้งแต่ต้นจนที่สุด ดูเถิด ได้บันทึกไว้ในหนังสือของซามูเอลผู้ทํานาย และในหนังสือของนาธันผู้พยากรณ์ และในหนังสือของกาดผู้ทํานาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 30, 'มีเรื่องราวการครอบครองของพระองค์ทั้งสิ้น และยุทธพลังของพระองค์ และเรื่องราวที่บังเกิดกับพระองค์และกับอิสราเอล และบรรดาราชอาณาจักรทั้งสิ้นของประเทศต่างๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 1, 'ซาโลมอนโอรสของดาวิดได้สถาปนาราชอาณาจักรของพระองค์ และพระเยโฮวาห์พระเจ้าของพระองค์ทรงสถิตกับพระองค์ และทรงกระทําให้พระองค์ใหญ่โตอย่างยิ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 2, 'ซาโลมอนตรัสกับอิสราเอลทั้งปวง กับนายพันและนายร้อย ทั้งกับผู้วินิจฉัยและกับเจ้านายทั้งปวงในอิสราเอลทั้งสิ้น ผู้เป็นประมุขของบรรพบุรุษของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 3, 'และซาโลมอนกับชุมนุมชนทั้งปวงที่อยู่กับพระองค์ได้ขึ้นไปที่ปูชนียสถานสูงซึ่งอยู่ที่กิเบโอน เพราะพลับพลาแห่งชุมนุมของพระเจ้า ซึ่งโมเสสผู้รับใช้ของพระเยโฮวาห์ได้สร้างขึ้นในถิ่นทุรกันดาร อยู่ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 4, 'แต่ดาวิดได้ทรงนําหีบของพระเจ้าขึ้นมาจากคีริยาทเยอาริมถึงสถานที่ซึ่งดาวิดทรงเตรียมไว้ให้ เพราะพระองค์ได้ทรงตั้งเต็นท์ไว้ให้ในกรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 5, 'ยิ่งกว่านั้น แท่นบูชาทองเหลือง ซึ่งเบซาเลลบุตรชายอุรีผู้เป็นบุตรชายเฮอร์ได้สร้างไว้นั้นก็อยู่ที่หน้าพลับพลาของพระเยโฮวาห์ และซาโลมอนกับชุมนุมชนก็ได้ใช้แท่นนั้นเป็นประจํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 6, 'และซาโลมอนเสด็จขึ้นไปที่นั่นยังแท่นบูชาทองเหลืองต่อพระพักตร์พระเยโฮวาห์ซึ่งอยู่ที่พลับพลาแห่งชุมนุม และทรงถวายเครื่องเผาบูชาหนึ่งพันตัวบนแท่นนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 7, 'ในคืนนั้นพระเจ้าทรงปรากฏแก่ซาโลมอน และตรัสกับพระองค์ว่า “เจ้าอยากให้เราให้อะไรเจ้า ก็จงขอเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 8, 'และซาโลมอนทูลพระเจ้าว่า “พระองค์ได้ทรงสําแดงความเมตตายิ่งใหญ่แก่ดาวิดเสด็จพ่อของข้าพระองค์ และทรงกระทําให้ข้าพระองค์ปกครองแทน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 9, 'โอ ข้าแต่พระเยโฮวาห์พระเจ้า ขอให้พระสัญญาของพระองค์ที่มีต่อดาวิดเสด็จพ่อของข้าพระองค์เป็นจริง ณ บัดนี้ เพราะพระองค์ได้ทรงตั้งให้ข้าพระองค์เป็นกษัตริย์เหนือชนชาติที่มากอย่างผงคลีแห่งแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 10, 'ขอทรงประทานสติปัญญาและความรู้แก่ข้าพระองค์ที่จะเข้านอกออกในต่อหน้าชนชาตินี้ เพราะผู้ใดเล่าที่จะวินิจฉัยประชาชนของพระองค์ได้ ซึ่งใหญ่โตนัก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 11, 'พระเจ้าตรัสตอบซาโลมอนว่า “เพราะว่าสิ่งนี้อยู่ในจิตใจของเจ้า และเจ้ามิได้ขอทรัพย์สมบัติ ความมั่งคั่งและเกียรติ หรือชีวิตของศัตรูเจ้า และทั้งมิได้ขอชีวิตยืนยาว แต่ได้ขอสติปัญญาและความรู้เพื่อตัวเจ้าเอง เพื่อเจ้าจะวินิจฉัยประชาชนของเรา ผู้ซึ่งเราได้ตั้งเจ้าให้เป็นกษัตริย์เหนือเขานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 12, 'เราประสาทสติปัญญาและความรู้ให้แก่เจ้า เราจะให้ทรัพย์สมบัติ ความมั่งคั่งและเกียรติแก่เจ้าด้วย อย่างที่ไม่มีกษัตริย์องค์ใดผู้อยู่ก่อนเจ้าได้มี และไม่มีผู้ใดภายหลังเจ้าจะมีเหมือน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 13, 'ซาโลมอนจึงเสด็จจากปูชนียสถานสูงที่กิเบโอน จากต่อหน้าพลับพลาแห่งชุมนุมไปยังกรุงเยรูซาเล็ม และพระองค์ทรงครอบครองอยู่เหนืออิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 14, 'ซาโลมอนทรงสะสมรถรบ และพลม้า พระองค์ทรงมีรถรบหนึ่งพันสี่ร้อยคัน และพลม้าหนึ่งหมื่นสองพันคน ซึ่งพระองค์ทรงให้ประจําอยู่ที่หัวเมืองรถรบ และอยู่กับกษัตริย์ในกรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 15, 'และกษัตริย์ทรงกระทําให้เงินและทองคําเป็นของสามัญในกรุงเยรูซาเล็มเหมือนก้อนหิน และทรงกระทําให้มีไม้สนสีดาร์มากมายเหมือนไม้มะเดื่อแห่งหุบเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 16, 'ม้าอันเป็นสินค้าเข้าของซาโลมอนมาจากอียิปต์ พร้อมด้วยเส้นด้ายสําหรับผ้าป่าน และบรรดาพ่อค้าของกษัตริย์รับเส้นด้ายสําหรับผ้าป่านนั้นมาตามราคา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 17, 'เขาทั้งหลายนํารถรบเข้ามาจากอียิปต์คันหนึ่งเป็นเงินหกร้อยเชเขลเงิน และม้าตัวหนึ่งหนึ่งร้อยห้าสิบ ดังนั้นโดยทางพวกพ่อค้า เขาก็ส่งออกไปยังบรรดากษัตริย์ของคนฮิตไทต์และบรรดากษัตริย์ของคนซีเรีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 1, 'ฝ่ายซาโลมอนทรงตั้งพระทัยที่จะสร้างพระนิเวศเพื่อพระนามของพระเยโฮวาห์ และสร้างราชวังเพื่อราชอาณาจักรของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 2, 'และซาโลมอนทรงกําหนดให้เจ็ดหมื่นคนเป็นคนขนของ และให้แปดหมื่นคนสกัดหินที่ถิ่นเทือกเขา และให้คนสามพันหกร้อยคนดูแลเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 3, 'และซาโลมอนทรงส่งราชสารไปยังหุรามกษัตริย์เมืองไทระว่า “ท่านได้กระทํากิจกับดาวิดราชบิดาของข้าพเจ้า คือ ได้ส่งไม้สนสีดาร์ให้พระองค์ท่าน เพื่อสร้างวังให้พระองค์ท่านอาศัยอย่างไร ขอท่านได้กระทําแก่ข้าพเจ้าอย่างนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 4, 'ดูเถิด ข้าพเจ้ากําลังจะสร้างพระนิเวศเพื่อพระนามพระเยโฮวาห์พระเจ้าของข้าพเจ้า และมอบถวายแด่พระองค์ เพื่อเผาเครื่องหอมต่อพระพักตร์พระองค์ และเพื่อขนมปังหน้าพระพักตร์เนืองนิตย์ และเพื่อเครื่องเผาบูชาทั้งเช้าและเย็น ในวันสะบาโต และในวันขึ้นหนึ่งค่ํา และวันเทศกาลตามกําหนดของพระเยโฮวาห์พระเจ้าของเรา ซึ่งเป็นกฎตั้งไว้เป็นนิตย์สําหรับอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 5, 'พระนิเวศซึ่งข้าพเจ้าจะสร้างนั้นใหญ่โต เพราะว่าพระเจ้าของเราใหญ่ยิ่งกว่าพระทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 6, 'แต่ผู้ใดเล่าที่จะสามารถสร้างพระนิเวศสําหรับพระองค์ได้ ในเมื่อฟ้าสวรรค์ถึงแม้ว่าฟ้าสวรรค์ที่สูงที่สุดรับรองพระองค์ไว้ไม่ได้ ข้าพเจ้าเป็นผู้ใดเล่าที่จะสร้างพระนิเวศสําหรับพระองค์ นอกจากให้เป็นที่เผาเครื่องบูชาต่อพระพักตร์พระองค์เท่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 7, 'เพราะฉะนั้น บัดนี้ขอส่งชายคนหนึ่งผู้ชํานาญการช่างทองคํา เงิน ทองเหลืองและเหล็กและชํานาญในเรื่องผ้าสีม่วง สีแดงเข้มและสีฟ้า ทั้งเป็นผู้ชํานาญในการแกะสลัก เพื่อจะอยู่กับช่างฝีมือผู้อยู่กับข้าพเจ้าในยูดาห์และในเยรูซาเล็ม ผู้ซึ่งดาวิดราชบิดาของข้าพเจ้าได้จัดหาไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 8, 'ขอท่านส่งไม้สนสีดาร์ ไม้สนสามใบและไม้ประดู่จากเลบานอนให้ข้าพเจ้าด้วย เพราะข้าพเจ้าทราบว่า ข้าราชการของท่านรู้จักการตัดไม้ในเลบานอน และดูเถิด ข้าราชการของข้าพเจ้าจะอยู่กับข้าราชการของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 9, 'เพื่อจัดเตรียมไม้ให้แก่ข้าพเจ้าให้มากมาย เพราะว่าพระนิเวศที่ข้าพเจ้าจะสร้างนี้จะใหญ่โตและแปลกประหลาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 10, 'และดูเถิด ส่วนข้าราชการของท่าน คือผู้ที่โค่นตัดไม้นั้น ข้าพเจ้าจะให้ข้าวสาลีนวดแล้วสองหมื่นโคระ ข้าวบาร์เลย์สองหมื่นโคระ น้ําองุ่นสองหมื่นบัท และน้ํามันสองหมื่นบัทแก่เขาทั้งหลาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 11, 'แล้วหุรามกษัตริย์แห่งเมืองไทระทรงตอบเป็นลายพระหัตถ์ ซึ่งพระองค์ทรงมีไปถึงซาโลมอนว่า “เพราะว่าพระเยโฮวาห์ทรงรักประชาชนของพระองค์ พระองค์จึงทรงกระทําให้ท่านเป็นกษัตริย์เหนือเขาทั้งหลาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 12, 'หุรามตรัสอีกว่า “สาธุการแด่พระเยโฮวาห์พระเจ้าแห่งอิสราเอล ผู้ทรงสร้างฟ้าสวรรค์และแผ่นดินโลก ผู้ได้ประทานโอรสที่ฉลาดคนหนึ่งแก่ดาวิดกอปรด้วยความเฉลียวฉลาดและความเข้าใจ ผู้ซึ่งจะสร้างพระนิเวศถวายพระเยโฮวาห์ และสร้างพระราชวังเพื่อราชอาณาจักรของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 13, 'บัดนี้ข้าพเจ้าได้ส่งช่างฝีมือคนหนึ่ง กอปรด้วยความเข้าใจ คือหุรามที่ปรึกษาอาวุโส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 14, 'บุตรชายของหญิงคนดาน บิดาของเขาเป็นชาวเมืองไทระ เขาชํานาญงานช่างทองคํา เงิน ทองเหลือง เหล็ก หินและไม้ และทํางานช่างผ้าสีม่วง สีฟ้า ผ้าป่านเนื้อละเอียดและผ้าสีแดงเข้ม และทําการแกะสลักทุกชนิด และสร้างตามแบบลวดลายใดๆที่จะกําหนดให้แก่เขา พร้อมกับช่างฝีมือของท่าน คือช่างฝีมือของดาวิดราชบิดาของท่านผู้เป็นเจ้านายของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 15, 'เพราะฉะนั้นบัดนี้เรื่องข้าวสาลี ข้าวบาร์เลย์ น้ํามัน และน้ําองุ่น ซึ่งเจ้านายของข้าพเจ้าได้กล่าวถึงนั้น ขอท่านได้ส่งไปให้พวกเราผู้รับใช้ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 16, 'และพวกเราจะตัดไม้เท่าที่ท่านต้องการจากเลบานอน และนํามาให้ท่านโดยแพทางทะเลถึงเมืองยัฟฟา เพื่อว่าท่านจะได้นําขึ้นไปยังกรุงเยรูซาเล็ม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 17, 'แล้วซาโลมอนทรงทําบัญชีสํามะโนครัวชนต่างด้าวทั้งสิ้นผู้อยู่ในแผ่นดินอิสราเอล ภายหลังบัญชีสํามะโนครัวซึ่งดาวิดราชบิดาของพระองค์ได้ทรงกระทําไว้ และปรากฏว่ามีคนหนึ่งแสนห้าหมื่นสามพันหกร้อยคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 18, 'พระองค์ทรงกําหนดให้เจ็ดหมื่นคนเป็นคนขนของ และให้แปดหมื่นคนสกัดหินที่ถิ่นเทือกเขา และคนสามพันหกร้อยคนเป็นผู้ดูแลให้ประชาชนทํางาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 1, 'แล้วซาโลมอนทรงเริ่มสร้างพระนิเวศของพระเยโฮวาห์ที่กรุงเยรูซาเล็มบนภูเขาโมริยาห์ ที่ซึ่งพระเยโฮวาห์ทรงปรากฏแก่ดาวิดราชบิดาของพระองค์ ตรงที่ซึ่งดาวิดทรงกําหนดไว้ที่ลานนวดข้าวของโอรนันคนเยบุส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 2, 'พระองค์ทรงเริ่มสร้างในวันที่สองเดือนที่สองของปีที่สี่แห่งรัชกาลของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 3, 'ต่อไปนี้เป็นรากฐานซึ่งซาโลมอนทรงวางเพื่อสร้างพระนิเวศของพระเจ้า ส่วนยาวตามศอกโบราณ หกสิบศอก และกว้างยี่สิบศอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 4, 'มุขด้านหน้าของพระนิเวศนั้นยาวยี่สิบศอก เท่ากับด้านกว้างของพระนิเวศ และส่วนสูงหนึ่งร้อยยี่สิบ พระองค์ทรงบุด้านในด้วยทองคําบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 5, 'ห้องโถงพระองค์ทรงบุด้วยไม้สนสามใบ และบุด้วยทองคําเนื้อดี และทําต้นอินทผลัมและลูกโซ่ประดับไว้บนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 6, 'พระองค์ทรงแต่งพระนิเวศด้วยฝังเพชรพลอยต่างๆเพื่อความสวยงาม ทองคํานั้นเป็นทองคําเมืองพารวายิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 7, 'พระองค์จึงทรงบุพระนิเวศนั้นด้วยทองคําคือที่คาน ธรณีประตู ผนัง ประตู กับสลักรูปเครูบไว้บนผนัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 8, 'และพระองค์ทรงสร้างที่บริสุทธิ์ที่สุด คือความยาวของที่นั้นตามความกว้างของพระนิเวศ เป็นยี่สิบศอก และกว้างยี่สิบศอก พระองค์ทรงบุด้วยทองคําเนื้อดีหนักหกร้อยตะลันต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 9, 'น้ําหนักของตะปูห้าสิบเชเขลทองคํา และพระองค์ทรงบุห้องชั้นบนด้วยทองคํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 10, 'ในที่บริสุทธิ์ที่สุดนั้น พระองค์ทรงสร้างเครูบไว้สองรูปด้วยไม้บุทองคํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 11, 'ปีกของเครูบทั้งสองนั้นกางออกยี่สิบศอก ปีกข้างหนึ่งของเครูบรูปหนึ่งยาวห้าศอกจดผนังพระนิเวศ และอีกปีกหนึ่งยาวห้าศอกจดปีกของเครูบอีกรูปหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 12, 'และของเครูบอีกรูปหนึ่งปีกข้างหนึ่งห้าศอกจดผนังพระนิเวศ และอีกปีกหนึ่งห้าศอกด้วยติดต่อกับปีกของเครูบอีกรูปหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 13, 'ปีกของเครูบเหล่านี้กางออกยี่สิบศอก เครูบทั้งสองนั้นยืนหันหน้าไปทางห้องโถง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 14, 'และพระองค์ทรงสร้างม่าน ด้วยผ้าสีฟ้า สีม่วง และสีแดงเข้ม และผ้าป่านเนื้อละเอียด และปักรูปเครูบไว้บนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 15, 'ข้างหน้าพระนิเวศพระองค์ทรงสร้างเสาสองต้น สูงสามสิบห้าศอก มีบัวคว่ําสูงห้าศอกอยู่บนยอดเสาแต่ละต้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 16, 'พระองค์ทรงทําลูกโซ่เหมือนในห้องหลังติดไว้ที่ยอดเสา และพระองค์ทรงทําทับทิมหนึ่งร้อยลูกแขวนไว้ที่โซ่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 17, 'พระองค์ทรงตั้งเสาไว้หน้าพระวิหาร ข้างขวาต้นหนึ่ง อีกต้นหนึ่งข้างซ้าย ต้นข้างขวานั้นพระองค์ทรงขนานนามว่า ยาคีน และต้นข้างซ้ายว่า โบอาส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 1, 'พระองค์ทรงสร้างแท่นบูชาด้วยทองเหลือง ยาวยี่สิบศอก กว้างยี่สิบศอก และสูงสิบศอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 2, 'แล้วพระองค์ทรงสร้างขันสาครหล่อ เป็นขันกลม วัดจากขอบหนึ่งไปถึงอีกขอบหนึ่งได้สิบศอก สูงห้าศอก และวัดโดยรอบได้สามสิบศอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 3, 'ภายใต้ขันนี้มีรูปวัวอยู่รอบขันสาคร ในระยะหนึ่งศอกมีรูปวัวสิบลูก อยู่รอบขันสาคร วัวเหล่านี้เป็นสองแถว หล่อพร้อมกับเมื่อหล่อขันสาคร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 4, 'ขันสาครนั้นวางอยู่บนวัวสิบสองตัวหันหน้าไปทิศเหนือสามตัว หันหน้าไปทิศตะวันตกสามตัว หันหน้าไปทิศใต้สามตัว และหันหน้าไปทิศตะวันออกสามตัว ขันสาครนั้นวางอยู่บนวัวนี้ ส่วนเบื้องหลังของมันทั้งสิ้นอยู่ข้างใน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 5, 'ขันสาครหนาหนึ่งคืบ ที่ขอบของมันทําเหมือนขอบถ้วย เหมือนอย่างดอกลิลลี่ บรรจุได้สามพันบัท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 6, 'พระองค์ทรงทําขันสิบลูก วางอยู่ด้านขวาห้าลูก ด้านซ้ายห้าลูก เพื่อใช้ล้างของในนั้น เขาจะล้างของซึ่งใช้เป็นเครื่องเผาบูชาในนี้ ขันสาครนั้นสําหรับให้ปุโรหิตล้างในนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 7, 'แล้วพระองค์ทรงสร้างคันประทีปทองคําสิบคันตามที่กําหนดเกี่ยวกับคันประทีปนั้น และพระองค์ทรงตั้งไว้ในพระวิหาร อยู่ด้านขวาห้าคัน และด้านซ้ายห้าคัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 8, 'พระองค์ทรงสร้างโต๊ะสิบตัวด้วย และตั้งไว้ในพระวิหาร อยู่ด้านขวาห้าตัว ด้านซ้ายห้าตัว และพระองค์ทรงทําชามทองคําหนึ่งร้อยใบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 9, 'พระองค์ทรงสร้างลานแห่งปุโรหิต และลานใหญ่ และประตูลาน และทรงบุประตูนั้นด้วยทองเหลือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 10, 'และพระองค์ทรงวางขันสาครไว้ที่ด้านขวาพระนิเวศทางทิศตะวันออกเฉียงใต้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 11, 'หุรามได้สร้างหม้อ พลั่ว และชาม ดังนั้นหุรามจึงทํางานซึ่งท่านกระทําให้กษัตริย์ซาโลมอนเรื่องพระนิเวศของพระเจ้าสําเร็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 12, 'คือ เสาสองต้น คิ้ว และบัวคว่ําซึ่งอยู่บนยอดเสาทั้งสอง และตาข่ายสองผืนซึ่งคลุมคิ้วทั้งสองของบัวคว่ําซึ่งอยู่บนยอดเสา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 13, 'และลูกทับทิมสี่ร้อยลูกสําหรับตาข่ายทั้งสองผืน ตาข่ายผืนหนึ่งมีลูกทับทิมสองแถว เพื่อคลุมคิ้วทั้งสองของบัวคว่ําซึ่งอยู่บนยอดเสา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 14, 'เขาทําแท่นด้วย และทําขันไว้บนแท่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 15, 'และขันสาครลูกหนึ่ง และวัวสิบสองตัวรองอยู่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 16, 'หม้อ พลั่ว และขอเกี่ยวเนื้อ และเครื่องประกอบทั้งสิ้นนี้ หุรามที่ปรึกษาอาวุโสได้ทําขึ้นด้วยทองเหลืองสุกถวายกษัตริย์ซาโลมอนสําหรับพระนิเวศของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 17, 'กษัตริย์ทรงหล่อสิ่งเหล่านี้ในที่ราบแม่น้ําจอร์แดน ในที่ดินเหนียวระหว่างสุคคทกับเศเรดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 18, 'ซาโลมอนทรงทําเครื่องใช้ทั้งสิ้นนี้เป็นจํานวนมาก จึงมิได้หาน้ําหนักของทองเหลือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 19, 'และซาโลมอนจึงทรงกระทําเครื่องใช้ทั้งสิ้นซึ่งอยู่ในพระนิเวศของพระเจ้า คือแท่นบูชาทองคํา โต๊ะขนมปังหน้าพระพักตร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 20, 'คันประทีปและตะเกียงทําด้วยทองคําบริสุทธิ์ เพื่อใช้ตามประทีปหน้าห้องหลังตามลักษณะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 21, 'ดอกไม้ ตะเกียง และตะไกรตัดไส้ตะเกียง ทําด้วยทองคํา คือทองคําบริสุทธิ์ที่สุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 22, 'ตะไกรตัดไส้ตะเกียง ชาม ช้อน และกระถางไฟ ทําด้วยทองคําบริสุทธิ์ ส่วนทางเข้าของพระนิเวศคือ ประตูชั้นในของที่บริสุทธิ์ที่สุด และประตูพระวิหารคือประตูห้องโถงทําด้วยทองคํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 1, 'บรรดากิจการซึ่งซาโลมอนทรงกระทําสําหรับพระนิเวศของพระเยโฮวาห์ก็สําเร็จดังนี้ และซาโลมอนทรงนําบรรดาสิ่งซึ่งดาวิดราชบิดาทรงถวายไว้เข้ามา คือเครื่องเงิน เครื่องทองคํา และเครื่องใช้ต่างๆ และเก็บไว้ในคลังพระนิเวศของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 2, 'แล้วซาโลมอนทรงประชุมพวกผู้ใหญ่ของอิสราเอล และบรรดาหัวหน้าของตระกูล และบรรดาประมุขของบรรพบุรุษชนอิสราเอล ในกรุงเยรูซาเล็ม เพื่อจะนําหีบพันธสัญญาของพระเยโฮวาห์ขึ้นมาจากนครดาวิด คือเมืองศิโยน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 3, 'และผู้ชายทั้งสิ้นของอิสราเอลก็ประชุมต่อพระพักตร์กษัตริย์ ณ การเลี้ยงในเดือนที่เจ็ด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 4, 'พวกผู้ใหญ่ทั้งสิ้นของอิสราเอลมา และคนเลวีก็ยกหีบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 5, 'และเขาทั้งหลายก็นําหีบ พลับพลาแห่งชุมนุม และเครื่องใช้บริสุทธิ์ทั้งสิ้นซึ่งอยู่ในพลับพลาขึ้นมา ของเหล่านี้บรรดาปุโรหิตและคนเลวีหามขึ้นมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 6, 'และกษัตริย์ซาโลมอนกับชุมนุมชนอิสราเอลทั้งสิ้นที่ได้ประชุมกันอยู่กับพระองค์ต่อหน้าหีบ ได้ถวายแกะและวัวมากมาย ซึ่งเขาจะนับหรือเอาจํานวนก็ไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 7, 'แล้วปุโรหิตก็นําหีบพันธสัญญาของพระเยโฮวาห์มายังที่ของหีบ ในที่อยู่ในห้องหลังของพระนิเวศคือในที่บริสุทธิ์ที่สุด ภายใต้ปีกเครูบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 8, 'เพราะว่าเครูบนั้นกางปีกออกเหนือที่ของหีบ เครูบจึงเป็นเครื่องคลุมเหนือหีบและไม้คานหามของหีบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 9, 'พวกเขาดึงคานหามของหีบนั้นออกบ้าง จึงเห็นปลายคานหามได้จากหีบนั้น ซึ่งอยู่ข้างหน้าห้องหลัง แต่เขาจะเห็นจากข้างนอกไม่ได้ และคานหามก็ยังอยู่ที่นั่นจนทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 10, 'ไม่มีสิ่งใดในหีบนอกจากศิลาสองแผ่นซึ่งโมเสสเก็บไว้ ณ ภูเขาโฮเรบ เมื่อพระเยโฮวาห์ทรงกระทําพันธสัญญากับคนอิสราเอล เมื่อเขาทั้งหลายออกมาจากอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 11, 'และอยู่มาเมื่อปุโรหิตออกมาจากที่บริสุทธิ์ (เพราะปุโรหิตทั้งปวงผู้อยู่ที่นั่นได้ชําระตนให้บริสุทธิ์แล้ว และไม่คํานึงถึงเวร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 12, 'และบรรดาพวกเลวีที่เป็นนักร้องทั้งหมด ทั้งอาสาฟ เฮมาน และเยดูธูน ทั้งบุตรชายและญาติของเขาทั้งหลาย แต่งกายด้วยผ้าป่านสีขาว มีฉาบ พิณใหญ่ และพิณเขาคู่ ยืนอยู่ทางตะวันออกของแท่นบูชา พร้อมกับปุโรหิตเป่าแตรหนึ่งร้อยยี่สิบคน)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 13, 'อยู่มาพวกคนเป่าแตรและพวกนักร้องจะทําให้คนได้ยินเขาทั้งหลายร้องเพลงสรรเสริญ และเพลงโมทนาพระคุณพระเยโฮวาห์เป็นเสียงเดียวกัน และเมื่อเขาร้องขึ้นพร้อมกับแตรและฉาบกับเครื่องดนตรีอย่างอื่น ในการถวายสรรเสริญแด่พระเยโฮวาห์ว่า “เพราะพระองค์ประเสริฐ เพราะความเมตตาของพระองค์ดํารงเป็นนิตย์” พระนิเวศคือพระนิเวศของพระเยโฮวาห์ก็มีเมฆเต็มไปหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 14, 'จนปุโรหิตจะยืนปรนนิบัติไม่ได้ด้วยเหตุเมฆนั้น เพราะสง่าราศีของพระเยโฮวาห์เต็มพระนิเวศของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 1, 'แล้วซาโลมอนตรัสว่า “พระเยโฮวาห์ได้ตรัสว่า พระองค์จะประทับในความมืดทึบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 2, 'ข้าพระองค์ได้สร้างพระนิเวศอันเป็นที่ประทับสําหรับพระองค์ เป็นสถานที่เพื่อพระองค์จะทรงสถิตอยู่เป็นนิตย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 3, 'แล้วกษัตริย์ก็ทรงหันพระพักตร์มา และทรงให้พรแก่ชุมนุมชนอิสราเอลทั้งปวง ขณะที่ชุมนุมชนอิสราเอลทั้งปวงยืนอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 4, 'พระองค์ตรัสว่า “สาธุการแด่พระเยโฮวาห์พระเจ้าแห่งอิสราเอล ผู้ทรงกระทําให้สําเร็จด้วยพระหัตถ์ของพระองค์ ตามที่พระองค์ตรัสไว้ด้วยพระโอษฐ์ต่อดาวิดพระราชบิดาของข้าพเจ้าว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 5, '‘ตั้งแต่วันที่เราได้นําประชาชนของเราออกจากแผ่นดินอียิปต์ เรามิได้เลือกเมืองหนึ่งเมืองใดในตระกูลอิสราเอลทั้งสิ้น เพื่อจะสร้างพระนิเวศ เพื่อนามของเราจะอยู่ที่นั่น และเรามิได้เลือกชายคนใดให้เป็นเจ้านายเหนืออิสราเอลประชาชนของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 6, 'แต่เราได้เลือกเยรูซาเล็มแล้วเพื่อนามของเราจะอยู่ที่นั่น และเราได้เลือกดาวิดแล้วให้อยู่เหนืออิสราเอลประชาชนของเรา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 7, 'ดาวิดราชบิดาของข้าพเจ้าทรงตั้งพระทัยที่จะสร้างพระนิเวศสําหรับพระนามแห่งพระเยโฮวาห์พระเจ้าของอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 8, 'แต่พระเยโฮวาห์ตรัสกับดาวิดราชบิดาของข้าพเจ้าว่า ‘ที่เจ้าตั้งใจสร้างพระนิเวศสําหรับนามของเรานั้น เจ้าก็ทําดีอยู่แล้ว ในเรื่องความตั้งใจของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 9, 'อย่างไรก็ตาม เจ้าจะไม่สร้างพระนิเวศ แต่บุตรชายของเจ้าผู้ซึ่งจะออกมาจากบั้นเอวของเจ้าจะสร้างพระนิเวศเพื่อนามของเรา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 10, 'บัดนี้พระเยโฮวาห์ทรงให้พระดํารัสของพระองค์ซึ่งพระองค์ทรงกระทํานั้นสําเร็จ เพราะข้าพเจ้าได้ขึ้นมาแทนดาวิดราชบิดาของข้าพเจ้า และนั่งอยู่บนบัลลังก์ของอิสราเอล ดังที่พระเยโฮวาห์ได้ทรงสัญญาไว้ และข้าพเจ้าได้สร้างพระนิเวศสําหรับพระนามของพระเยโฮวาห์พระเจ้าแห่งอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 11, 'และข้าพเจ้าได้วางหีบไว้ที่นั่น ซึ่งพันธสัญญาของพระเยโฮวาห์อยู่ในนั้น ซึ่งพระองค์ได้ทรงกระทํากับชนอิสราเอล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 12, 'แล้วพระองค์ประทับยืนหน้าแท่นบูชาของพระเยโฮวาห์ ต่อหน้าชุมนุมชนอิสราเอลทั้งปวง และกางพระหัตถ์ของพระองค์ออก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 13, 'เพราะซาโลมอนได้ทรงสร้างแท่นทองเหลือง ยาวห้าศอก กว้างห้าศอก สูงสามศอก และทรงตั้งไว้กลางลาน และพระองค์ทรงประทับอยู่บนนั้น แล้วพระองค์ทรงคุกเข่าลงต่อหน้าชุมนุมอิสราเอลทั้งปวง และกางพระหัตถ์ของพระองค์สู่ฟ้าสวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 14, 'และพระองค์ทูลว่า “โอ ข้าแต่พระเยโฮวาห์พระเจ้าแห่งอิสราเอล ไม่มีพระเจ้าองค์ใดเหมือนพระองค์ ในฟ้าสวรรค์หรือที่แผ่นดินโลก ผู้ทรงรักษาพันธสัญญา และทรงสําแดงความเมตตาแก่ผู้รับใช้ของพระองค์ ผู้ดําเนินอยู่ต่อพระพักตร์พระองค์ด้วยสิ้นสุดใจของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 15, 'พระองค์ได้ทรงกระทํากับดาวิดบิดาของข้าพระองค์ผู้รับใช้ของพระองค์ตามบรรดาสิ่งซึ่งพระองค์ทรงสัญญาไว้แก่ท่าน พระองค์ตรัสด้วยพระโอษฐ์ของพระองค์ และพระองค์ได้ทรงกระทําให้สําเร็จในวันนี้ด้วยพระหัตถ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 16, 'โอ ข้าแต่พระเยโฮวาห์พระเจ้าแห่งอิสราเอล เพราะฉะนั้นบัดนี้ขอทรงรักษาสิ่งที่พระองค์ทรงสัญญาไว้กับดาวิดผู้รับใช้ของพระองค์ราชบิดาของข้าพระองค์ว่า ‘เจ้าจะไม่ขาดชายผู้หนึ่งในสายตาของเราที่จะนั่งบนบัลลังก์แห่งอิสราเอล เพื่อว่าลูกหลานทั้งหลายของเจ้าจะระมัดระวังในวิถีทางของเขา ที่จะดําเนินตามราชบัญญัติของเรา อย่างที่เจ้าได้ดําเนินต่อหน้าเรานั้น’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 17, 'เพราะฉะนั้น โอ ข้าแต่พระเยโฮวาห์พระเจ้าแห่งอิสราเอล ขอพระวจนะของพระองค์จงดํารงอยู่ ซึ่งพระองค์ได้ตรัสกับดาวิดผู้รับใช้ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 18, 'แต่พระเจ้าจะทรงประทับกับมนุษย์ที่แผ่นดินโลกหรือ ดูเถิด ฟ้าสวรรค์และฟ้าสวรรค์อันสูงที่สุดยังรับพระองค์อยู่ไม่ได้ พระนิเวศซึ่งข้าพระองค์ได้สร้างขึ้นจะรับพระองค์ไม่ได้ยิ่งกว่านั้นสักเท่าใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 19, 'แต่ขอพระองค์ทรงสนพระทัยในคําอธิษฐานของผู้รับใช้ของพระองค์ และในคําวิงวอนนี้ โอ ข้าแต่พระเยโฮวาห์พระเจ้าของข้าพระองค์ ขอทรงสดับเสียงร้องและคําอธิษฐานซึ่งผู้รับใช้ของพระองค์อธิษฐานต่อพระพักตร์พระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 20, 'เพื่อว่าพระเนตรของพระองค์จะทรงลืมอยู่เหนือพระนิเวศนี้ทั้งกลางวันและกลางคืน คือสถานที่ซึ่งพระองค์ได้ตรัสว่า จะตั้งพระนามของพระองค์ไว้ที่นั่น เพื่อว่าพระองค์จะทรงสดับคําอธิษฐานซึ่งผู้รับใช้ของพระองค์จะได้อธิษฐานตรงต่อสถานที่นี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 21, 'และขอพระองค์ทรงสดับคําวิงวอนของผู้รับใช้ของพระองค์ และของอิสราเอลประชาชนของพระองค์ เมื่อเขาอธิษฐานตรงต่อสถานที่นี้ ขอพระองค์ทรงสดับอยู่ในฟ้าสวรรค์อันเป็นที่ประทับของพระองค์ และเมื่อพระองค์ทรงสดับแล้ว ก็ขอพระองค์ทรงประทานอภัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 22, 'เมื่อชายคนใดกระทําบาปต่อเพื่อนบ้านของเขาและถูกบังคับให้ทําสัตย์สาบาน และเขามาให้คําสาบานต่อหน้าแท่นบูชาของพระองค์ในพระนิเวศนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 23, 'ขอพระองค์ทรงสดับจากฟ้าสวรรค์และขอทรงกระทํา ขอทรงพิพากษาผู้รับใช้ทั้งหลายของพระองค์ ลงโทษผู้กระทําความผิด และทรงนําความประพฤติของเขาให้กลับตกบนศีรษะของตัวเขาเอง และขอทรงประกาศความบริสุทธิ์ของผู้ชอบธรรม สนองแก่เขาตามความชอบธรรมของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 24, 'ถ้าอิสราเอลประชาชนของพระองค์พ่ายแพ้ต่อหน้าศัตรูเพราะเขาได้กระทําบาปต่อพระองค์ และเขาหันกลับมาหาพระองค์อีก ยอมรับพระนามของพระองค์ และอธิษฐานและกระทําการวิงวอนต่อพระพักตร์พระองค์ในพระนิเวศนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 25, 'ก็ขอพระองค์ทรงสดับในฟ้าสวรรค์ และประทานอภัยแก่บาปของอิสราเอลประชาชนของพระองค์ และขอทรงนําเขากลับมายังแผ่นดินซึ่งพระองค์ได้พระราชทานแก่เขาทั้งหลายและบรรพบุรุษของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 26, 'เมื่อฟ้าสวรรค์ปิดอยู่และไม่มีฝน เพราะเขาทั้งหลายได้กระทําบาปต่อพระองค์ ถ้าเขาทั้งหลายได้อธิษฐานต่อสถานที่นี้ และยอมรับพระนามของพระองค์ และหันกลับเสียจากบาปของเขาทั้งหลาย เมื่อพระองค์ทรงให้ใจเขาทั้งหลายรับความทุกข์ใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 27, 'ก็ขอพระองค์ทรงสดับในฟ้าสวรรค์ และขอประทานอภัยแก่บาปของผู้รับใช้ของพระองค์ และของอิสราเอลประชาชนของพระองค์ เมื่อพระองค์ทรงสอนทางดีแก่เขาซึ่งเขาควรจะดําเนิน และขอทรงประทานฝนบนแผ่นดินของพระองค์ ซึ่งพระองค์พระราชทานแก่ประชาชนของพระองค์เป็นมรดกนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 28, 'ถ้ามีการกันดารอาหารในแผ่นดิน ถ้ามีโรคระบาด ข้าวม้าน รากินข้าว หรือตั๊กแตนวัยบิน หรือตั๊กแตนวัยคลาน หรือศัตรูของเขาทั้งหลายล้อมเมืองในแผ่นดินของเขาไว้รอบด้าน จะเป็นภัยพิบัติอย่างใด หรือความเจ็บอย่างใดมีขึ้นก็ดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 29, 'ไม่ว่าคําอธิษฐานอย่างใด หรือคําวิงวอนประการใด ซึ่งประชาชนคนใด หรืออิสราเอลประชาชนของพระองค์ทั้งสิ้นทูล ต่างก็ประจักษ์ในภัยพิบัติและความทุกข์ใจของเขา และได้กางมือของเขาสู่พระนิเวศนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 30, 'ขอพระองค์ทรงสดับในฟ้าสวรรค์อันเป็นที่ประทับของพระองค์ และพระราชทานอภัย และทรงประทานแก่ทุกคนซึ่งพระองค์ทรงทราบจิตใจตามการประพฤติทั้งสิ้นของเขา (เพราะพระองค์เท่านั้นที่ทรงทราบจิตใจแห่งบุตรทั้งหลายของมนุษย์)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 31, 'เพื่อว่าเขาทั้งหลายจะได้ยําเกรงพระองค์ และดําเนินในมรรคาของพระองค์ ตลอดวันเวลาที่เขามีชีวิตอาศัยในแผ่นดิน ซึ่งพระองค์พระราชทานแก่บรรพบุรุษของข้าพระองค์ทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 32, 'ยิ่งกว่านั้นอีก เกี่ยวกับชนต่างด้าว ผู้ซึ่งไม่ใช่อิสราเอลประชาชนของพระองค์ เมื่อเขามาจากประเทศเมืองไกล เพราะเห็นแก่พระนามใหญ่ยิ่งของพระองค์ พระหัตถ์อันมหิทธิฤทธิ์ของพระองค์ และพระกรที่เหยียดออกของพระองค์ เมื่อเขามาอธิษฐานตรงต่อพระนิเวศนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 33, 'ก็ขอพระองค์ทรงสดับในฟ้าสวรรค์อันเป็นที่ประทับของพระองค์ และขอทรงกระทําตามทุกสิ่งซึ่งชนต่างด้าวได้ทูลขอต่อพระองค์ เพื่อว่าชนชาติทั้งหลายแห่งแผ่นดินโลกจะรู้จักพระนามของพระองค์ และยําเกรงพระองค์ ดังอิสราเอลประชาชนของพระองค์ยําเกรงพระองค์อยู่นั้น และเพื่อเขาทั้งหลายจะทราบว่า พระนิเวศนี้ซึ่งข้าพระองค์ได้สร้างไว้เขาเรียกกันด้วยพระนามของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 34, 'ถ้าประชาชนของพระองค์ออกไปกระทําสงครามต่อสู้ศัตรูของเขาทั้งหลาย จะเป็นโดยทางใดๆที่พระองค์ทรงใช้เขาออกไปก็ตาม และเขาทั้งหลายได้อธิษฐานต่อพระองค์ตรงต่อเมืองนี้ซึ่งพระองค์ทรงเลือกสรรไว้ และตรงต่อพระนิเวศซึ่งข้าพระองค์ได้สร้างเพื่อพระนามของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 35, 'แล้วขอพระองค์ทรงสดับคําอธิษฐานของเขาและคําวิงวอนของเขาในฟ้าสวรรค์ และขอทรงให้สิทธิอันชอบธรรมของเขาคงอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 36, 'ถ้าเขาทั้งหลายกระทําบาปต่อพระองค์ (เพราะไม่มีมนุษย์สักคนหนึ่งซึ่งมิได้กระทําบาป) และพระองค์ทรงกริ้วต่อเขา และพระองค์ทรงมอบเขาไว้ต่อหน้าศัตรู เขาจึงถูกจับไปเป็นเชลยยังแผ่นดินหนึ่งไม่ว่าไกลหรือใกล้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 37, 'แต่ถ้าเขาสํานึกผิดในใจในแผ่นดินซึ่งเขาได้ถูกจับไปเป็นเชลย และได้กลับใจและได้อธิษฐานต่อพระองค์ในแผ่นดินที่เขาไปเป็นเชลย ทูลว่า ‘ข้าพระองค์ทั้งหลายได้กระทําบาป และได้ประพฤติชั่วร้ายและได้กระทําความชั่ว’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 38, 'ถ้าเขาทั้งหลายกลับมาหาพระองค์ด้วยสุดจิตสุดใจของเขาในแผ่นดินที่เขาไปเป็นเชลย ที่ซึ่งศัตรูกวาดเขาไปเป็นเชลย และอธิษฐานต่อพระองค์ตรงต่อแผ่นดินของเขา ซึ่งพระองค์พระราชทานแก่บรรพบุรุษของเขาทั้งหลาย และต่อเมืองซึ่งพระองค์ได้ทรงเลือกสรรไว้ และต่อพระนิเวศซึ่งข้าพระองค์ได้สร้างไว้เพื่อพระนามของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 39, 'แล้วขอพระองค์ทรงสดับคําอธิษฐานและคําวิงวอนของเขาในฟ้าสวรรค์อันเป็นที่ประทับของพระองค์ และขอทรงให้สิทธิอันชอบธรรมของเขาคงอยู่ และขอทรงประทานอภัยแก่ประชาชนของพระองค์ผู้ได้กระทําบาปต่อพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 40, 'ข้าแต่พระเจ้าของข้าพระองค์ บัดนี้ขอพระเนตรของพระองค์ทรงลืมอยู่ และขอพระกรรณของพระองค์สดับคําอธิษฐานแห่งสถานที่นี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 41, 'โอ ข้าแต่พระเยโฮวาห์พระเจ้า ฉะนั้นบัดนี้ขอทรงลุกขึ้น เสด็จไปยังที่พํานักของพระองค์ ทั้งพระองค์และหีบแห่งฤทธานุภาพของพระองค์ โอ ข้าแต่พระเยโฮวาห์พระเจ้า ขอให้ปุโรหิตของพระองค์สวมความรอด และให้วิสุทธิชนของพระองค์เปรมปรีดิ์ในความประเสริฐของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 42, 'โอ ข้าแต่พระเยโฮวาห์พระเจ้า ขออย่าทรงหันหน้าของผู้ที่พระองค์ทรงเจิมไว้นั้นไปเสีย ขอพระองค์ทรงระลึกถึงความเมตตาของพระองค์อันมีอยู่ต่อดาวิดผู้รับใช้ของพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 1, 'เมื่อซาโลมอนทรงจบคําอธิษฐานของพระองค์แล้ว ไฟได้ลงมาจากฟ้าสวรรค์ไหม้เครื่องเผาบูชาและเครื่องสัตวบูชาเสีย และสง่าราศีของพระเยโฮวาห์ก็เต็มพระนิเวศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 2, 'ปุโรหิตเข้าไปในพระนิเวศของพระเยโฮวาห์ไม่ได้ เพราะว่าสง่าราศีของพระเยโฮวาห์เต็มพระนิเวศของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 3, 'เมื่อบรรดาชนอิสราเอลได้เห็นไฟลงมาและสง่าราศีของพระเยโฮวาห์อยู่บนพระนิเวศ เขาทั้งหลายก็กราบซบหน้าลงถึงพื้นหิน และได้นมัสการสรรเสริญพระเยโฮวาห์ว่า “เพราะพระองค์ประเสริฐ เพราะความเมตตาของพระองค์ดํารงอยู่เป็นนิตย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 4, 'แล้วกษัตริย์และบรรดาประชาชนทั้งหลายได้ถวายเครื่องสัตวบูชาต่อพระพักตร์พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 5, 'กษัตริย์ซาโลมอนทรงถวายเครื่องสัตวบูชาเป็นวัวสองหมื่นสองพันตัวและแกะหนึ่งแสนสองหมื่นตัว ดังนี้แหละกษัตริย์และประชาชนทั้งปวงได้อุทิศถวายพระนิเวศแห่งพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 6, 'บรรดาปุโรหิตก็ยืนประจําตําแหน่งของตน ทั้งคนเลวีด้วยพร้อมกับเครื่องดนตรีถวายแด่พระเยโฮวาห์ ซึ่งกษัตริย์ดาวิดได้ทรงกระทําเพื่อสรรเสริญพระเยโฮวาห์ เมื่อดาวิดได้ถวายสาธุการด้วยการปรนนิบัติของเขาทั้งหลาย เพราะความเมตตาของพระองค์ดํารงอยู่เป็นนิตย์ และปุโรหิตก็เป่าแตรข้างหน้าเขา และอิสราเอลทั้งปวงยืนอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 7, 'และซาโลมอนทรงทําพิธีชําระส่วนกลางของลานซึ่งอยู่ข้างหน้าพระนิเวศของพระเยโฮวาห์ให้เป็นส่วนบริสุทธิ์ เพราะพระองค์ทรงถวายเครื่องเผาบูชาและไขมันของเครื่องสันติบูชาที่นั่น เพราะว่าแท่นทองเหลืองซึ่งซาโลมอนทรงสร้างไว้นั้น ไม่พอจุเครื่องเผาบูชา เครื่องธัญญบูชาและไขมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 8, 'ในครั้งนั้นซาโลมอนทรงถือเทศกาลอยู่เจ็ดวัน และอิสราเอลทั้งปวงอยู่กับพระองค์ด้วย เป็นชุมนุมชนใหญ่ยิ่งนัก ตั้งแต่ทางเข้าเมืองฮามัทจนถึงแม่น้ําอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 9, 'และในวันที่แปดเขาทั้งหลายมีการประชุมอันศักดิ์สิทธิ์ เพราะเขาทั้งหลายได้มีงานมอบถวายแท่นบูชามาเจ็ดวัน และถือเทศกาลเลี้ยงมาเจ็ดวันแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 10, 'เมื่อวันที่ยี่สิบสามของเดือนที่เจ็ด พระองค์ทรงให้ประชาชนกลับไปเต็นท์ของตน มีใจชื่นบานและยินดีด้วยความดีซึ่งพระเยโฮวาห์ได้ทรงสําแดงแก่ดาวิด และแก่ซาโลมอน และแก่อิสราเอลประชาชนของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 11, 'ดังนี้แหละซาโลมอนทรงสร้างพระนิเวศของพระเยโฮวาห์และพระราชวังเสร็จ คือทุกอย่างซึ่งพระองค์ทรงดําริจะกระทําในเรื่องพระนิเวศของพระเยโฮวาห์และในเรื่องพระราชสํานักของพระองค์ พระองค์ทรงกระทําให้สําเร็จสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 12, 'แล้วพระเยโฮวาห์ทรงปรากฏแก่ซาโลมอนเวลากลางคืนและตรัสกับท่านว่า “เราได้ยินคําอธิษฐานของเจ้า และได้เลือกสถานที่นี้สําหรับเราให้เป็นนิเวศแห่งเครื่องสัตวบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 13, 'ถ้าเราปิดฟ้าสวรรค์มิให้ฝนตก หรือเราบัญชาให้ตั๊กแตนมากินแผ่นดิน หรือส่งโรคระบาดมาท่ามกลางประชาชนของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 14, 'ถ้าประชาชนของเราผู้ซึ่งเขาเรียกกันโดยนามของเรานั้นจะถ่อมตัวลง และอธิษฐาน และแสวงหาหน้าของเรา และหันเสียจากทางชั่วของเขา เราก็จะฟังจากสวรรค์ และจะให้อภัยแก่บาปของเขา และจะรักษาแผ่นดินของเขาให้หาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 15, 'บัดนี้ตาของเราจะลืมอยู่และหูของเราจะฟังคําอธิษฐานซึ่งเขาทั้งหลายอธิษฐาน ณ สถานที่นี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 16, 'เพราะบัดนี้เราได้เลือกสรรและกระทําให้นิเวศนี้เป็นที่บริสุทธิ์เพื่อนามของเราจะอยู่ที่นั่นเป็นนิตย์ ตาของเราและใจของเราจะอยู่ที่นั่นตลอดเวลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 17, 'ส่วนเจ้า ถ้าเจ้าดําเนินต่อหน้าเราอย่างดาวิดบิดาของเจ้าดําเนินนั้น กระทําตามทุกสิ่งซึ่งเราได้บัญชาแก่เจ้า และรักษากฎเกณฑ์ของเราและคําตัดสินของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 18, 'แล้วเราจะสถาปนาราชบัลลังก์แห่งอาณาจักรของเจ้า ดังที่เราได้กระทําพันธสัญญาไว้กับดาวิดบิดาของเจ้าว่า ‘เจ้าจะไม่ขาดชายผู้หนึ่งที่จะครอบครองเหนืออิสราเอล’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 19, 'แต่ถ้าเจ้าหันไปและทอดทิ้งกฎเกณฑ์ของเราและบัญญัติของเราซึ่งเราตั้งไว้ต่อหน้าเจ้า และจะไปปรนนิบัติพระอื่นและนมัสการพระเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 20, 'แล้วเราจะถอนรากเขาทั้งหลายออกจากแผ่นดินของเรา ซึ่งเราได้ให้แก่เขา และนิเวศซึ่งเราชําระให้บริสุทธิ์เพื่อนามของเรา เราจะเหวี่ยงออกไปจากสายตาของเรา และเราจะทําให้เขาเป็นคําภาษิตและคําครหาท่ามกลางชนชาติทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 21, 'และนิเวศนี้ซึ่งสูงส่ง ทุกคนที่ผ่านไปจะประหลาดใจ และกล่าวว่า ‘ไฉนพระเยโฮวาห์จึงทรงกระทําเช่นนี้แก่แผ่นดินนี้และแก่พระนิเวศนี้’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 22, 'แล้วเขาทั้งหลายจะตอบว่า ‘เพราะเขาทั้งหลายทอดทิ้งพระเยโฮวาห์พระเจ้าแห่งบรรพบุรุษของเขา ผู้ทรงนําเขาออกจากแผ่นดินอียิปต์ และได้ยึดพระอื่น และได้นมัสการพระเหล่านั้นทั้งปรนนิบัติด้วย ฉะนั้นพระองค์จึงได้ทรงนําเหตุร้ายทั้งหมดนี้มาถึงเขาทั้งหลาย’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 1, 'และอยู่มาเมื่อสิ้นยี่สิบปี ที่ซาโลมอนได้ทรงสร้างพระนิเวศของพระเยโฮวาห์ และพระราชวังส่วนพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 2, 'ซาโลมอนได้ทรงเสริมสร้างหัวเมืองซึ่งหุรามได้ถวายแด่พระองค์ แล้วให้คนอิสราเอลอาศัยอยู่ในนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 3, 'และซาโลมอนได้เสด็จไปยังฮามัทโศบาห์ และยึดเมืองนั้นได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 4, 'พระองค์ได้ทรงสร้างเมืองทัดโมร์ไว้ในถิ่นทุรกันดาร และหัวเมืองคลังหลวงทั้งสิ้นซึ่งพระองค์ทรงสร้างไว้ในฮามัท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 5, 'พระองค์ได้ทรงสร้างเมืองเบธโฮโรนบนและเบธโฮโรนล่างด้วยเป็นเมืองที่มั่นคง มีกําแพง ประตูเมือง และดาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 6, 'และทรงสร้างเมืองบาอาลัทและหัวเมืองคลังหลวงทั้งปวงที่ซาโลมอนทรงมีอยู่ และเมืองทั้งปวงสําหรับรถรบของพระองค์ และเมืองทั้งปวงสําหรับพลม้าของพระองค์ และสิ่งใดๆซึ่งพระองค์ประสงค์จะสร้างในเยรูซาเล็ม ในเลบานอน และในแผ่นดินทั้งหมดซึ่งอยู่ในการครอบครองของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 7, 'ประชาชนทั้งปวงที่เหลืออยู่ในเหล่าคนฮิตไทต์ คนอาโมไรต์ คนเปริสซี คนฮีไวต์ และคนเยบุส ผู้ซึ่งไม่ใช่อิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 8, 'จากลูกหลานของชนเหล่านี้ ผู้เหลือต่อมาในแผ่นดิน ผู้ซึ่งประชาชนอิสราเอลมิได้ทําลาย ซาโลมอนได้ทรงกระทําให้ประชาชนเหล่านี้เป็นทาสแรงงานและเขาทั้งหลายก็เป็นอยู่จนทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 9, 'แต่ส่วนคนอิสราเอลนั้นซาโลมอนหาได้ทรงกระทําให้เป็นทาสแรงงานไม่ เขาทั้งหลายเป็นทหารและเป็นนายทหารของพระองค์ เป็นผู้บังคับบัญชารถรบของพระองค์ และพลม้าของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 10, 'และคนต่อไปนี้เป็นเจ้าหน้าที่ชั้นผู้ใหญ่ของกษัตริย์ซาโลมอน มีสองร้อยห้าสิบคน เป็นผู้ปกครองประชาชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 11, 'ซาโลมอนทรงนําธิดาของฟาโรห์ขึ้นมาจากนครดาวิดยังพระราชวังซึ่งพระองค์ทรงสร้างไว้ให้พระนาง เพราะพระองค์ตรัสว่า “มเหสีของเราไม่ควรอยู่ในวังของดาวิดกษัตริย์แห่งอิสราเอล เพราะสถานที่ทั้งหลายซึ่งหีบของพระเยโฮวาห์มาถึงเป็นที่บริสุทธิ์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 12, 'แล้วซาโลมอนทรงถวายเครื่องเผาบูชาแด่พระเยโฮวาห์บนแท่นบูชาของพระเยโฮวาห์ ซึ่งพระองค์ทรงสร้างไว้ที่หน้ามุข');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 13, 'ตามหน้าที่ประจําวันที่ต้องทําเป็นการถวายบูชาตามบัญญัติของโมเสส ในวันสะบาโต ในวันขึ้นหนึ่งค่ํา และในวันเทศกาลตามกําหนด ประจําปีสามเทศกาล คือเทศกาลกินขนมปังไร้เชื้อ เทศกาลสัปดาห์ และเทศกาลอยู่เพิง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 14, 'ตามพระราชบัญชาของดาวิดราชบิดาของพระองค์ พระองค์ทรงกําหนดแบ่งเวรปุโรหิตสําหรับการปรนนิบัติ และแบ่งคนเลวีให้ประจําหน้าที่การสรรเสริญและการปรนนิบัติต่อหน้าปุโรหิต ตามหน้าที่ประจําวันที่ต้องทํา และคนเฝ้าประตูเป็นเวรเฝ้าทุกประตู เพราะว่าดาวิดบุรุษของพระเจ้าทรงบัญชาไว้เช่นนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 15, 'และเขาทั้งหลายมิได้หันไปเสียจากสิ่งซึ่งกษัตริย์ได้ทรงบัญชาปุโรหิตและคนเลวีซึ่งเกี่ยวกับเรื่องใดๆ และเกี่ยวกับเรื่องคลัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 16, 'บรรดาพระราชกิจของซาโลมอนก็ลุล่วงไปตั้งแต่วันที่วางรากพระนิเวศของพระเยโฮวาห์จนถึงวันสําเร็จงาน ดังนั้นพระนิเวศของพระเยโฮวาห์ก็สําเร็จครบถ้วน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 17, 'แล้วซาโลมอนเสด็จไปยังเอซีโอนเกเบอร์และเมืองเอโลทที่ชายทะเลในแผ่นดินเอโดม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 18, 'และหุรามก็ให้ข้าราชการของพระองค์ส่งเรือ และข้าราชการที่คุ้นเคยกับทะเลไปให้ซาโลมอน และเขาทั้งหลายไปถึงเมืองโอฟีร์พร้อมกับข้าราชการของซาโลมอน และนําเอาทองคําจากที่นั่นหนักสี่ร้อยห้าสิบตะลันต์มายังกษัตริย์ซาโลมอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 1, 'เมื่อพระราชินีแห่งเชบาทรงได้ยินกิตติศัพท์แห่งซาโลมอน พระนางก็เสด็จมายังเยรูซาเล็ม เพื่อทดลองพระองค์ด้วยปัญหายุ่งยากต่างๆ พร้อมด้วยข้าราชบริพารมากมาย กับอูฐบรรทุกเครื่องเทศและทองคําเป็นอันมาก และเพชรพลอยต่างๆ และเมื่อพระนางเสด็จมาถึงซาโลมอนแล้ว พระนางทูลเรื่องในใจของพระนางทุกประการ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 2, 'และซาโลมอนตรัสตอบปัญหาของพระนางทั้งสิ้น ไม่มีสิ่งใดที่ซ่อนเร้นอยู่พ้นซาโลมอนซึ่งพระองค์จะทรงอธิบายแก่พระนางไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 3, 'และเมื่อพระราชินีแห่งเชบาทรงเห็นพระสติปัญญาของซาโลมอนและพระราชวังที่พระองค์ทรงสร้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 4, 'ทั้งอาหารที่โต๊ะเสวย กับการเข้าเฝ้าของบรรดาข้าราชการ และการปรนนิบัติรับใช้ของมหาดเล็กตลอดทั้งภูษาอาภรณ์ของเขา และพนักงานเชิญถ้วยของพระองค์ตลอดทั้งภูษาอาภรณ์ของเขา และการที่พระองค์เสด็จขึ้นไปในพระนิเวศของพระเยโฮวาห์ พระทัยของพระนางก็สลดลงทีเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 5, 'พระนางทูลกษัตริย์ว่า “ข่าวคราวซึ่งหม่อมฉันได้ยินในประเทศของหม่อมฉัน ถึงพระราชกิจและพระสติปัญญาของพระองค์เป็นความจริง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 6, 'แต่หม่อมฉันมิได้เชื่อถ้อยคํานั้น จนหม่อมฉันมาเฝ้า และตาของหม่อมฉันได้เห็นเอง และดูเถิด ที่เขาบอกแก่หม่อมฉันก็ไม่ถึงครึ่งหนึ่งแห่งพระสติปัญญาใหญ่ยิ่งของพระองค์ พระองค์เลิศล้ํายิ่งไปกว่าข่าวคราวที่หม่อมฉันได้ยิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 7, 'บรรดาคนของพระองค์ก็เป็นสุข บรรดาข้าราชการเหล่านี้ของพระองค์ ผู้อยู่งานประจําต่อพระพักตร์พระองค์และฟังพระสติปัญญาของพระองค์ก็เป็นสุข');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 8, 'สาธุการแด่พระเยโฮวาห์พระเจ้าของพระองค์ ผู้ทรงพอพระทัยในพระองค์และทรงแต่งตั้งพระองค์ไว้บนบัลลังก์ เป็นกษัตริย์เพื่อพระเยโฮวาห์พระเจ้าของพระองค์ เพราะพระเจ้าของพระองค์ทรงรักอิสราเอลและจะสถาปนาเขาไว้เป็นนิตย์ พระองค์จึงได้ทรงแต่งตั้งให้พระองค์เป็นกษัตริย์เหนือเขาทั้งหลาย เพื่อพระองค์จะทรงอํานวยความยุติธรรมและความเที่ยงธรรม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 9, 'แล้วพระนางก็ถวายทองคําหนึ่งร้อยยี่สิบตะลันต์แด่กษัตริย์ ทั้งเครื่องเทศเป็นจํานวนมาก และเพชรพลอยต่างๆ ไม่มีเครื่องเทศใดๆเหมือนอย่างที่พระราชินีแห่งเมืองเชบาถวายแด่กษัตริย์ซาโลมอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 10, 'ยิ่งกว่านั้นอีก ข้าราชการของหุรามและข้าราชการของซาโลมอนผู้นําทองคํามาจากโอฟีร์ ได้นําไม้ประดู่และเพชรพลอยต่างๆมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 11, 'แล้วกษัตริย์ทรงใช้ไม้ประดู่ทําขั้นบันไดพระนิเวศของพระเยโฮวาห์และพระราชวัง ทั้งทําพิณเขาคู่ และพิณใหญ่ให้แก่นักร้อง ซึ่งไม่เคยเห็นมีอย่างนั้นแต่ก่อนในแผ่นดินยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 12, 'กษัตริย์ซาโลมอนพระราชทานทุกอย่างแก่พระราชินีแห่งเชบาตามที่พระนางทรงมีพระประสงค์ ไม่ว่าพระนางจะทูลขอสิ่งใด นอกเหนือไปจากสิ่งที่พระนางนํามาถวายกษัตริย์ ดังนั้นพระนางก็เสด็จกลับไปยังแผ่นดินของพระนาง พร้อมกับข้าราชการของพระนาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 13, 'น้ําหนักทองคําที่นํามาส่งซาโลมอนในปีหนึ่งนั้น เป็นทองคําหกร้อยหกสิบหกตะลันต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 14, 'นอกเหนือจากทองคําซึ่งนักการค้าและพ่อค้าได้นํามา และกษัตริย์ทั้งปวงของประเทศอาระเบีย และบรรดาเจ้าเมืองแห่งแผ่นดินได้นําทองคําและเงินมายังซาโลมอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 15, 'กษัตริย์ซาโลมอนทรงสร้างโล่ใหญ่สองร้อยอันด้วยทองคําทุบ โล่อันหนึ่งใช้ทองคําทุบหกร้อยเชเขล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 16, 'และพระองค์ทรงสร้างโล่สามร้อยอันด้วยทองคําทุบ โล่อันหนึ่งใช้ทองคําสามร้อยเชเขล และกษัตริย์ก็ทรงเก็บโล่ไว้ในพระตําหนักพนาเลบานอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 17, 'กษัตริย์ทรงกระทําพระที่นั่งงาช้างขนาดใหญ่ด้วย และทรงบุด้วยทองคําบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 18, 'พระที่นั่งนั้นมีบันไดหกขั้น กับที่รองพระบาททําด้วยทองคํา ซึ่งติดอยู่กับพระที่นั่ง ทั้งสองข้างของพระที่นั่งมีที่วางพระหัตถ์ และสิงโตสองตัวยืนอยู่ข้างๆที่วางพระหัตถ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 19, 'มีสิงโตอีกสิบสองตัวยืนอยู่ที่นั่น บนบันไดหกขั้นทั้งสองข้าง เขาไม่เคยทําในราชอาณาจักรใดๆเหมือนอย่างนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 20, 'ภาชนะทั้งสิ้นสําหรับเครื่องดื่มของกษัตริย์ซาโลมอนทําด้วยทองคํา และภาชนะทั้งสิ้นของพระตําหนักพนาเลบานอนทําด้วยทองคําบริสุทธิ์ ไม่มีที่ทําด้วยเงินเลย เงินนั้นถือว่าเป็นของไม่มีค่าอะไรในสมัยของซาโลมอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 21, 'เพราะเรือของกษัตริย์แล่นไปยังทารชิชพร้อมกับข้าราชการของหุราม กําปั่นทารชิชนําทองคํา เงิน งาช้าง ลิง และนกยูง มาสามปีต่อครั้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 22, 'ดังนั้นแหละ กษัตริย์ซาโลมอนจึงได้เปรียบกว่ากษัตริย์อื่นๆแห่งแผ่นดินโลกในเรื่องสมบัติและสติปัญญา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 23, 'และกษัตริย์ทั้งสิ้นแห่งแผ่นดินโลกก็แสวงหาที่จะเข้าเฝ้าซาโลมอน เพื่อจะฟังพระสติปัญญาซึ่งพระเจ้าพระราชทานไว้ในใจของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 24, 'ทุกคนก็นําเครื่องบรรณาการของเขามา เป็นเครื่องทําด้วยเงิน เครื่องทําด้วยทองคํา และเครื่องแต่งกาย เครื่องอาวุธ เครื่องเทศ ม้า และล่อ ตามจํานวนกําหนดทุกๆปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 25, 'และซาโลมอนทรงมีโรงช่องม้าสี่พันช่องสําหรับม้าและรถรบ และมีพลม้าหนึ่งหมื่นสองพันคน ซึ่งพระองค์ทรงให้ประจําอยู่ในหัวเมืองรถรบและอยู่กับกษัตริย์ที่กรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 26, 'และพระองค์ทรงครอบครองเหนือกษัตริย์ทั้งปวงตั้งแต่แม่น้ําถึงแผ่นดินของคนฟีลิสเตีย และถึงพรมแดนของอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 27, 'และกษัตริย์ทรงกระทําให้เงินนั้นเป็นของสามัญในกรุงเยรูซาเล็มเหมือนก้อนหิน และกระทําให้มีไม้สนสีดาร์มากมายเหมือนไม้มะเดื่อแห่งหุบเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 28, 'และเขานําม้าเข้ามาถวายซาโลมอนจากอียิปต์ และจากแผ่นดินทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 29, 'ส่วนพระราชกิจนอกนั้นของซาโลมอน ตั้งแต่ต้นจนปลาย มิได้บันทึกไว้ในหนังสือของนาธันผู้พยากรณ์ และในคําพยากรณ์ของอาหิยาห์ชาวชีโลห์ และในนิมิตของอิดโดผู้ทํานายเกี่ยวกับเยโรโบอัมบุตรชายเนบัทหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 30, 'ซาโลมอนทรงครอบครองในกรุงเยรูซาเล็มเหนืออิสราเอลทั้งปวงสี่สิบปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 31, 'และซาโลมอนล่วงหลับไปอยู่กับบรรพบุรุษของพระองค์ และเขาฝังพระศพไว้ในนครดาวิดราชบิดาของพระองค์ และเรโหโบอัมโอรสของพระองค์ครอบครองแทนพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 1, 'เรโหโบอัมได้ไปยังเมืองเชเคม เพราะอิสราเอลทั้งปวงได้มายังเชเคมเพื่อจะตั้งท่านให้เป็นกษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 2, 'และอยู่มาเมื่อเยโรโบอัมบุตรชายเนบัทได้ยินเรื่องนั้น เพราะท่านยังอยู่ในอียิปต์ที่ซึ่งท่านหนีไปจากพระพักตร์กษัตริย์ซาโลมอน แล้วเยโรโบอัมกลับจากอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 3, 'เขาทั้งหลายก็ใช้คนไปเรียนท่าน และเยโรโบอัมกับอิสราเอลทั้งหมดได้มาและทูลเรโหโบอัมว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 4, '“พระราชบิดาของพระองค์ได้กระทําให้แอกของข้าพระองค์ทุกข์หนัก เพราะฉะนั้นบัดนี้ขอทรงผ่อนการปรนนิบัติอย่างทุกข์หนักของพระราชบิดาของพระองค์ และแอกอันหนักของพระองค์เหนือข้าพระองค์ทั้งหลายให้เบาลงเสีย และข้าพระองค์ทั้งหลายจะปรนนิบัติพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 5, 'พระองค์ตรัสกับเขาว่า “สิ้นสามวันจงกลับมาหาเราอีก” ประชาชนจึงกลับไปเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 6, 'แล้วกษัตริย์เรโหโบอัมก็ทรงปรึกษากับบรรดาผู้เฒ่า ผู้อยู่งานประจําซาโลมอนราชบิดาของพระองค์ขณะเมื่อพระองค์ยังทรงพระชนม์อยู่ว่า “ท่านทั้งหลายจะแนะนําเราให้ตอบประชาชนนี้อย่างไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 7, 'เขาทั้งหลายทูลพระองค์ว่า “ถ้าพระองค์ทรงเมตตาแก่ประชาชนนี้และให้เขาพอใจ และตรัสตอบคําดีแก่เขา เขาทั้งหลายจะเป็นผู้รับใช้ของพระองค์เป็นนิตย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 8, 'แต่พระองค์ทรงทอดทิ้งคําปรึกษาซึ่งผู้เฒ่าถวายนั้นเสีย และไปปรึกษากับคนหนุ่มซึ่งเติบโตขึ้นมาพร้อมกับพระองค์และอยู่งานประจําพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 9, 'และพระองค์ตรัสกับเขาทั้งหลายว่า “ท่านจะแนะนําเราอย่างไร เพื่อพวกเราจะตอบประชาชนนี้ผู้ที่ทูลเราว่า ‘ขอทรงผ่อนแอกซึ่งพระราชบิดาของพระองค์วางอยู่เหนือข้าพระองค์ทั้งหลายให้เบาลง’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 10, 'และคนหนุ่มเหล่านั้นผู้ได้เติบโตมาพร้อมกับพระองค์ทูลพระองค์ว่า “พระองค์จงตรัสดังนี้แก่ประชาชนนี้ ผู้ทูลพระองค์ว่า ‘พระราชบิดาของพระองค์ได้ทรงกระทําให้แอกของข้าพระองค์ทั้งหลายทุกข์หนัก แต่ขอพระองค์ทรงผ่อนแก่ข้าพระองค์ให้เบาลง’ นั้น พระองค์จงตรัสแก่เขาทั้งหลายอย่างนี้ว่า ‘นิ้วก้อยของเราก็หนากว่าเอวแห่งราชบิดาของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 11, 'ที่พระราชบิดาของเราวางแอกหนักบนท่านทั้งหลายก็ดีแล้ว เราจะเพิ่มแอกให้แก่ท่านทั้งหลายอีก พระราชบิดาของเราตีสอนท่านทั้งหลายด้วยไม้เรียว แต่เราจะตีสอนท่านทั้งหลายด้วยแส้แมงป่อง’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 12, 'เยโรโบอัมกับประชาชนทั้งปวงจึงเข้ามาเฝ้าเรโหโบอัมในวันที่สาม ดังที่กษัตริย์รับสั่งว่า “จงมาหาเราอีกในวันที่สาม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 13, 'และกษัตริย์ตรัสตอบเขาทั้งหลายอย่างดุดัน กษัตริย์เรโหโบอัมทรงทอดทิ้งคําปรึกษาของผู้เฒ่าเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 14, 'และตรัสกับเขาทั้งหลายตามคําแนะนําของพวกคนหนุ่มว่า “พระราชบิดาของเราทําแอกของท่านทั้งหลายให้หนัก แต่เราจะเพิ่มให้แก่แอกนั้น พระราชบิดาของเราตีสอนท่านทั้งหลายด้วยไม้เรียว แต่เราจะตีสอนท่านทั้งหลายด้วยแส้แมงป่อง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 15, 'กษัตริย์จึงมิได้ทรงฟังเสียงประชาชน เพราะเหตุการณ์นี้เป็นมาแต่พระเจ้า เพื่อพระเยโฮวาห์จะทรงให้พระวจนะของพระองค์ได้สําเร็จ ซึ่งพระองค์ตรัสโดยอาหิยาห์ชาวชีโลห์แก่เยโรโบอัมบุตรชายเนบัท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 16, 'และเมื่ออิสราเอลทั้งปวงเห็นว่ากษัตริย์มิได้ทรงฟังเขาทั้งหลาย ประชาชนก็ทูลตอบกษัตริย์ว่า “ข้าพระองค์ทั้งหลายมีส่วนอะไรในดาวิด ข้าพระองค์ทั้งหลายไม่มีส่วนมรดกในบุตรเจสซี โอ อิสราเอลเอ๋ย กลับไปเต็นท์ของตนแต่ละคนเถิด ข้าแต่ดาวิด จงดูแลราชวงศ์ของพระองค์เองเถิด” อิสราเอลทั้งปวงจึงไปยังเต็นท์ของเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 17, 'แต่เรโหโบอัมทรงปกครองเหนือประชาชนอิสราเอลผู้อาศัยอยู่ในหัวเมืองยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 18, 'แล้วกษัตริย์เรโหโบอัมทรงใช้ฮาโดรัมนายงานเหนือแรงงานเกณฑ์ไป และประชาชนอิสราเอลก็เอาหินขว้างท่านถึงตาย แล้วกษัตริย์เรโหโบอัมก็ทรงรีบขึ้นรถรบของพระองค์ ทรงหนีไปกรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 19, 'อิสราเอลจึงกบฏต่อราชวงศ์ของดาวิดถึงทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 1, 'เมื่อเรโหโบอัมมายังกรุงเยรูซาเล็มแล้ว พระองค์ได้ทรงรวบรวมวงศ์วานยูดาห์และเบนยามิน เป็นนักรบที่คัดเลือกแล้วหนึ่งแสนแปดหมื่นคน เพื่อจะสู้รบกับอิสราเอล หมายจะเอาราชอาณาจักรคืนมาให้แก่เรโหโบอัม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 2, 'แต่พระวจนะของพระเยโฮวาห์มายังเชไมอาห์คนของพระเจ้าว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 3, '“จงไปทูลเรโหโบอัมโอรสของซาโลมอนกษัตริย์แห่งยูดาห์ และบอกแก่อิสราเอลทั้งปวงในยูดาห์และเบนยามินว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 4, '‘พระเยโฮวาห์ตรัสดังนี้ว่า เจ้าอย่าขึ้นไปสู้รบกับพี่น้องของเจ้า จงกลับไปบ้านของตนทุกคนเถิด เพราะสิ่งนี้เป็นมาจากเรา’” เขาทั้งหลายก็เชื่อฟังพระวจนะของพระเยโฮวาห์ และกลับไป ไม่ได้สู้รบกับเยโรโบอัม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 5, 'และเรโหโบอัมประทับในกรุงเยรูซาเล็ม และพระองค์ทรงสร้างหัวเมืองเพื่อป้องกันในยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 6, 'พระองค์ทรงสร้างเมืองเบธเลเฮม เอตาม เทโคอา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 7, 'เบธซูร์ โสโค อดุลลัม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 8, 'กัท มาเรชาห์ และศิฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 9, 'อาโดราอิม ลาคีช และอาเซคาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 10, 'โศราห์ อัยยาโลน และเฮโบรน หัวเมืองซึ่งมีป้อมที่อยู่ในยูดาห์และในเบนยามิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 11, 'พระองค์ทรงเสริมป้อมปราการให้แข็งแกร่ง และส่งผู้บังคับบัญชาไปประจําการในป้อมเหล่านั้น และทรงสะสมเสบียงอาหาร น้ํามัน และน้ําองุ่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 12, 'และพระองค์ทรงเก็บโล่และหอกไว้ในหัวเมืองทั้งปวง และกระทําให้หัวเมืองเหล่านั้นแข็งแรงมาก พระองค์จึงทรงยึดยูดาห์และเบนยามินไว้ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 13, 'และปุโรหิตกับคนเลวีซึ่งอยู่ในอิสราเอลทั้งสิ้นได้เข้ามาหาพระองค์จากเขตแดนซึ่งเขาอาศัยอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 14, 'เพราะคนเลวีละทิ้งทุ่งหญ้าและที่บ้านซึ่งเขายึดถือเป็นกรรมสิทธิ์และมายังยูดาห์และเยรูซาเล็ม เพราะเยโรโบอัมและโอรสของพระองค์ได้ขับไล่เขาทั้งหลายออกจากตําแหน่งปุโรหิตของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 15, 'และพระองค์ทรงแต่งตั้งปุโรหิตของพระองค์ขึ้นสําหรับปูชนียสถานสูงทั้งหลาย และสําหรับเมษปีศาจ และสําหรับรูปลูกวัวซึ่งพระองค์ทรงสร้างขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 16, 'และบรรดาผู้ที่ปักใจแสวงหาพระเยโฮวาห์พระเจ้าของอิสราเอลก็ติดตามเขาทั้งหลายมาจากตระกูลทั้งปวงของอิสราเอลยังเยรูซาเล็ม เพื่อถวายสัตวบูชาต่อพระเยโฮวาห์พระเจ้าแห่งบรรพบุรุษของเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 17, 'เขาทั้งหลายได้เสริมกําลังให้ราชอาณาจักรของยูดาห์ และได้กระทําให้เรโหโบอัมโอรสของซาโลมอนเข้มแข็งอยู่ได้สามปี เพราะเขาทั้งหลายดําเนินอยู่สามปีในวิถีของดาวิดและซาโลมอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 18, 'เรโหโบอัมทรงรับมาหะลัทธิดาของเยรีโมทโอรสของดาวิดเป็นมเหสี และอาบีฮาอิลบุตรสาวของเอลีอับบุตรชายเจสซี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 19, 'และพระนางก็ประสูติโอรสให้พระองค์คือ เยอูช เชมาริยาห์ และศาฮัม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 20, 'ภายหลังพระองค์ก็ทรงรับมาอาคาห์ธิดาของอับซาโลม ผู้ซึ่งประสูติ อาบียาห์ อัททัย ซีซา และเชโลมิทให้พระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 21, 'เรโหโบอัมทรงรักมาอาคาห์ธิดาของอับซาโลมมากกว่ามเหสีและนางสนมของพระองค์ทั้งสิ้น (พระองค์มีมเหสีสิบแปดองค์และนางสนมหกสิบคนและให้กําเนิดโอรสยี่สิบแปดองค์และธิดาหกสิบองค์)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 22, 'และเรโหโบอัมทรงแต่งตั้งให้อาบียาห์โอรสของมาอาคาห์เป็นโอรสองค์ใหญ่ ให้เป็นประมุขท่ามกลางพี่น้องของตน เพราะพระองค์ทรงตั้งพระทัยจะให้ท่านเป็นกษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 23, 'และพระองค์ทรงจัดการอย่างฉลาด และแจกจ่ายบรรดาโอรสของพระองค์ไปทั่วแผ่นดินทั้งสิ้นของยูดาห์และของเบนยามิน ในหัวเมืองที่มีป้อมทั้งสิ้น และพระองค์ประทานเสบียงอาหารให้อย่างอุดม และพระองค์ทรงประสงค์มเหสีมากมาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 1, 'ต่อมาเมื่อเรโหโบอัมตั้งราชอาณาจักรให้มั่นคงและทําให้ตนเองแข็งแรงขึ้นแล้ว พระองค์ทรงทอดทิ้งพระราชบัญญัติของพระเยโฮวาห์เสีย และอิสราเอลทั้งปวงก็ทิ้งพร้อมกับพระองค์ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 2, 'อยู่มาในปีที่ห้าแห่งกษัตริย์เรโหโบอัม เพราะเขาทั้งหลายได้ละเมิดต่อพระเยโฮวาห์ ชิชักกษัตริย์แห่งอียิปต์เสด็จขึ้นมาสู้รบเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 3, 'มีรถรบหนึ่งพันสองร้อยคันและพลม้าหกหมื่นคน และพลผู้มากับพระองค์จากอียิปต์นับไม่ถ้วนคือ ชาวลิบนี คนสุคีอิม และคนเอธิโอเปีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 4, 'และพระองค์ทรงยึดหัวเมืองที่มีป้อมของยูดาห์และมายังเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 5, 'แล้วเชไมอาห์ผู้พยากรณ์ได้มาเฝ้าเรโหโบอัมและบรรดาเจ้านายแห่งยูดาห์ ผู้มาประชุมกันอยู่ที่เยรูซาเล็มด้วยเรื่องชิชัก และกล่าวแก่เขาทั้งหลายว่า “พระเยโฮวาห์ตรัสดังนี้ว่า เจ้าได้ละทิ้งเรา เราจึงได้ละทิ้งเจ้าให้อยู่ในมือของชิชัก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 6, 'แล้วเจ้านายแห่งอิสราเอลและกษัตริย์ได้ถ่อมตนลงและกล่าวว่า “พระเยโฮวาห์ทรงชอบธรรมแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 7, 'เมื่อพระเยโฮวาห์ทรงเห็นว่าเขาทั้งหลายถ่อมตัวลง พระวจนะของพระเยโฮวาห์ได้มาถึงเชไมอาห์ว่า “เขาทั้งหลายได้ถ่อมตัวลงแล้ว เราจึงจะไม่ทําลายเขา แต่เราจะประสาทการช่วยให้พ้นแก่เขาบ้าง และพระพิโรธของเราจะไม่เทลงมาเหนือเยรูซาเล็มโดยมือของชิชัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 8, 'อย่างไรก็ดีเขาทั้งหลายต้องเป็นผู้รับใช้ของชิชัก เพื่อเขาทั้งหลายจะได้ทราบความแตกต่างระหว่างการรับใช้เราและรับใช้ราชอาณาจักรทั้งหลายของแผ่นดินโลก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 9, 'ชิชักกษัตริย์แห่งอียิปต์จึงขึ้นมาต่อสู้เยรูซาเล็ม พระองค์ทรงเก็บเอาทรัพย์สินแห่งพระนิเวศของพระเยโฮวาห์ และทรัพย์สมบัติในพระราชวัง พระองค์ทรงเก็บเอาไปทุกอย่าง พระองค์ทรงเก็บเอาโล่ทองคําซึ่งซาโลมอนทรงสร้างไว้นั้นไปด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 10, 'และกษัตริย์เรโหโบอัมทรงทําโล่ทองเหลืองขึ้นแทน และได้มอบไว้ในมือของทหารรักษาพระองค์ ผู้เฝ้าทวารพระราชวัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 11, 'และกษัตริย์เสด็จเข้าไปในพระนิเวศของพระเยโฮวาห์เมื่อไร ทหารรักษาพระองค์ก็มาถือโล่นั้น แล้วนํากลับไปเก็บไว้ในห้องทหารรักษาพระองค์ตามเดิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 12, 'และเมื่อพระองค์ทรงถ่อมพระองค์ลง พระพิโรธของพระเยโฮวาห์ก็หันไปเสียจากพระองค์ มิได้ทําลายพระองค์อย่างสิ้นเชิง ยิ่งกว่านั้นอีกสภาพการณ์ก็ยังดีอยู่ในยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 13, 'กษัตริย์เรโหโบอัมจึงสถาปนาพระองค์ขึ้นในกรุงเยรูซาเล็มและทรงครอบครอง เมื่อเรโหโบอัมทรงเริ่มครอบครองนั้นมีพระชนมายุสี่สิบเอ็ดพรรษา และพระองค์ทรงครอบครองสิบเจ็ดปีในกรุงเยรูซาเล็ม อันเป็นเมืองซึ่งพระเยโฮวาห์ทรงเลือกสรรไว้จากตระกูลต่างๆทั้งสิ้นของอิสราเอล เพื่อจะตั้งพระนามของพระองค์ไว้ที่นั่น พระราชมารดาของพระองค์ทรงพระนามว่านาอามาห์คนอัมโมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 14, 'และพระองค์ได้ทรงกระทําการชั่วร้าย เพราะพระองค์ไม่ตั้งพระทัยของพระองค์ที่จะแสวงหาพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 15, 'ส่วนพระราชกิจของเรโหโบอัม ตั้งแต่ต้นจนสุดท้าย มิได้บันทึกไว้ในหนังสือของเชไมอาห์ผู้พยากรณ์ และของอิดโดผู้ทํานายตามแบบพงศาวดารหรือ มีสงครามเรื่อยไปอยู่ระหว่างเรโหโบอัมและเยโรโบอัม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 16, 'และเรโหโบอัมก็ล่วงหลับไปอยู่กับบรรพบุรุษของพระองค์ และเขาก็ฝังพระศพไว้ในนครดาวิด และอาบียาห์ราชโอรสของพระองค์ได้ขึ้นครอบครองแทนพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 1, 'ในปีที่สิบแปดแห่งรัชกาลของกษัตริย์เยโรโบอัม อาบียาห์ได้เริ่มครอบครองเหนือประเทศยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 2, 'พระองค์ทรงครอบครองในเยรูซาเล็มสามปี พระราชมารดาของพระองค์มีพระนามว่ามีคายาห์ธิดาของอุรีเอลแห่งกิเบอาห์ มีสงครามระหว่างอาบียาห์และเยโรโบอัม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 3, 'อาบียาห์เสด็จออกทําสงคราม มีกองทัพทหารชํานาญศึกเป็นคนคัดเลือกแล้วสี่แสนคน และเยโรโบอัมได้ตั้งแนวรบสู้กับพระองค์ด้วยคนคัดเลือกแล้วเป็นทแกล้วทหารแปดแสนคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 4, 'และอาบียาห์ทรงลุกยืนอยู่บนภูเขาเศมาราอิมซึ่งอยู่ในถิ่นเทือกเขาเอฟราอิม และตรัสว่า “ข้าแต่เยโรโบอัมและอิสราเอลทั้งปวง ขอฟังข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 5, 'ไม่ควรหรือที่ท่านทั้งหลายจะรู้ว่า พระเยโฮวาห์พระเจ้าแห่งอิสราเอลพระราชทานตําแหน่งกษัตริย์เหนืออิสราเอลเป็นนิตย์แก่ดาวิด และลูกหลานของพระองค์โดยพันธสัญญาเกลือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 6, 'ถึงกระนั้นเยโรโบอัมบุตรชายเนบัท ข้าราชการของซาโลมอนโอรสของดาวิด ได้ลุกขึ้นกบฏต่อเจ้านายของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 7, 'และมีคนถ่อยลูกของเบลีอัลบางคนมั่วสุมกันกับเขาและขันสู้กับเรโหโบอัมโอรสของซาโลมอน เมื่อเรโหโบอัมยังเด็กอยู่และใจอ่อนแอต้านทานไม่ไหว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 8, 'และบัดนี้ท่านคิดว่าจะต่อต้านราชอาณาจักรของพระเยโฮวาห์ซึ่งอยู่ในมือของลูกหลานของดาวิด เพราะท่านทั้งหลายเป็นคนหมู่ใหญ่และมีลูกวัวทองคําซึ่งเยโรโบอัมสร้างไว้ให้ท่านเป็นพระ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 9, 'ท่านทั้งหลายมิได้ขับไล่ปุโรหิตของพระเยโฮวาห์ ลูกหลานของอาโรน และคนเลวีออกไป และตั้งปุโรหิตสําหรับตนเองอย่างชนชาติทั้งหลายหรือ ผู้ใดที่นําวัวหนุ่มและแกะผู้เจ็ดตัวมาชําระตัวให้บริสุทธิ์ไว้ จะได้เป็นปุโรหิตของสิ่งที่ไม่ใช่พระ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 10, 'แต่สําหรับเราทั้งหลาย พระเยโฮวาห์ทรงเป็นพระเจ้าของเราทั้งหลาย และเราทั้งหลายมิได้ทอดทิ้งพระองค์ เรามีปุโรหิตผู้ปรนนิบัติพระเยโฮวาห์ เป็นลูกหลานของอาโรน ทั้งมีคนเลวีทํางานหน้าที่ของเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 11, 'เขาถวายเครื่องเผาบูชาแด่พระเยโฮวาห์ทุกเช้าทุกเย็น ทั้งเครื่องหอม ตั้งขนมปังหน้าพระพักตร์บนโต๊ะบริสุทธิ์ และดูแลคันประทีปทองคําพร้อมทั้งตะเกียง เพื่อให้ประทีปลุกอยู่ทุกเย็น เพราะเราได้รักษาพระบัญชากําชับของพระเยโฮวาห์พระเจ้าของเรา แต่ท่านได้ทอดทิ้งพระองค์เสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 12, 'และดูเถิด พระเจ้าทรงอยู่กับเรา ทรงเป็นผู้บังคับบัญชาของเรา และปุโรหิตของพระองค์พร้อมกับแตรศึกพร้อมที่จะเป่าเรียกทําสงครามต่อสู้กับท่าน โอ ข้าแต่ประชาชนอิสราเอล ขออย่าต่อสู้กับพระเยโฮวาห์พระเจ้าแห่งบรรพบุรุษของท่าน เพราะท่านจะชนะไม่ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 13, 'เยโรโบอัมได้ส้องสุมผู้คนไว้เพื่อจะอ้อมมาหาเขาจากเบื้องหลัง ดังนั้นกองทหารของท่านจึงอยู่ข้างหน้ายูดาห์ และกองซุ่มก็อยู่ข้างหลังเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 14, 'และเมื่อยูดาห์มองดูข้างหลัง ดูเถิด การศึกก็อยู่ข้างหน้าและข้างหลังเขา และเขาทั้งหลายก็ร้องทูลต่อพระเยโฮวาห์ และบรรดาปุโรหิตก็เป่าแตร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 15, 'แล้วคนของยูดาห์ก็ตะเบ็งเสียงร้องทํานองศึกและเมื่อคนยูดาห์ตะโกน อยู่มาพระเจ้าทรงให้เยโรโบอัมและอิสราเอลทั้งปวงพ่ายแพ้ไปต่ออาบียาห์และยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 16, 'คนอิสราเอลได้หนีต่อหน้ายูดาห์ และพระเจ้าทรงมอบเขาไว้ในมือของเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 17, 'อาบียาห์และประชาชนของพระองค์ก็ฆ่าเขาเสียมากมาย คนอิสราเอลที่คัดเลือกแล้วจึงล้มตายห้าแสนคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 18, 'นี่แหละคนอิสราเอลก็ถูกปราบปรามในครั้งนั้น และคนยูดาห์ก็ชนะ เพราะเขาพึ่งพระเยโฮวาห์พระเจ้าแห่งบรรพบุรุษของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 19, 'และอาบียาห์ได้ติดตามเยโรโบอัม และยึดเอาหัวเมืองจากพระองค์ คือเมืองเบธเอลกับชนบทของเมืองนั้น และเยชานาห์กับชนบทของเมืองนั้น และเอโฟรนกับชนบทของเมืองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 20, 'เยโรโบอัมมิได้ฟื้นอํานาจของพระองค์ในรัชสมัยของอาบียาห์ และพระเยโฮวาห์ทรงประหารพระองค์ พระองค์ก็สิ้นพระชนม์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 21, 'แต่อาบียาห์ก็มีอํานาจยิ่งขึ้น และมีมเหสีสิบสี่องค์ ให้กําเนิดโอรสยี่สิบสององค์ และธิดาสิบหกองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 22, 'ราชกิจนอกนั้นของอาบียาห์ วิธีการและพระดํารัสของพระองค์ได้บันทึกไว้ในหนังสือของผู้พยากรณ์อิดโด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 1, 'อาบียาห์จึงล่วงหลับไปอยู่กับบรรพบุรุษของพระองค์ เขาก็ฝังพระศพไว้ในนครดาวิด และอาสาโอรสของพระองค์ได้ขึ้นครองแทนพระองค์ ในรัชกาลของอาสาแผ่นดินได้สงบอยู่สิบปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 2, 'และอาสาทรงกระทําสิ่งที่ดีและชอบในสายพระเนตรพระเยโฮวาห์พระเจ้าของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 3, 'พระองค์ทรงกําจัดแท่นบูชาพระต่างด้าวและปูชนียสถานสูงทั้งหลาย และพังเสาศักดิ์สิทธิ์ลง และได้โค่นเสารูปเคารพเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 4, 'และทรงบัญชาให้ยูดาห์แสวงหาพระเยโฮวาห์พระเจ้าแห่งบรรพบุรุษของตน และให้รักษาพระราชบัญญัติและพระบัญญัติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 5, 'พระองค์ทรงกําจัดปูชนียสถานสูงและแท่นเครื่องหอมออกเสียจากหัวเมืองทั้งสิ้นของยูดาห์ด้วย และราชอาณาจักรก็ได้สงบอยู่ภายใต้พระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 6, 'พระองค์ทรงสร้างหัวเมืองที่มีป้อมในยูดาห์ เพราะแผ่นดินก็สงบ พระองค์มิได้ทําสงครามในปีเหล่านั้น เพราะพระเยโฮวาห์ทรงประทานการหยุดพักสงบแก่พระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 7, 'และพระองค์ตรัสกับยูดาห์ว่า “ให้เราทั้งหลายสร้างหัวเมืองเหล่านี้ ล้อมด้วยกําแพง หอคอย ประตูเมือง และดาน แผ่นดินยังเป็นของเรา เพราะเราได้แสวงหาพระเยโฮวาห์พระเจ้าของเรา เราได้แสวงหาพระองค์ และพระองค์ได้ทรงประทานการหยุดพักสงบทุกด้าน” เขาทั้งหลายจึงสร้างและจําเริญขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 8, 'และอาสาทรงมีกองทัพพร้อมสรรพด้วยโล่ใหญ่และหอกจากยูดาห์สามแสนคน และจากเบนยามินซึ่งถือโล่และโก่งธนูสองแสนแปดหมื่นคน ทั้งสิ้นเป็นทแกล้วทหาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 9, 'เศ-ราห์ชาวเอธิโอเปียได้ออกมาต่อสู้กับเขาทั้งหลายด้วยกองทัพหนึ่งล้านคน และรถรบสามร้อยคันมาถึงเมืองมาเรชาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 10, 'และอาสาทรงยกออกไปปะทะกับเขา และเขาทั้งหลายก็ตั้งแนวรบในหุบเขาเศฟาธาห์ที่มาเรชาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 11, 'และอาสาร้องทูลต่อพระเยโฮวาห์พระเจ้าของพระองค์ว่า “ข้าแต่พระเยโฮวาห์ ไม่มีผู้ใดช่วยได้อย่างพระองค์ ในการสู้รบกันระหว่างผู้ที่มีกําลังกับผู้ที่ไม่มีกําลัง โอ ข้าแต่พระเยโฮวาห์พระเจ้าของข้าพระองค์ทั้งหลาย ขอทรงช่วยพวกข้าพระองค์ เพราะข้าพระองค์ทั้งหลายพึ่งพระองค์ ข้าพระองค์ทั้งหลายมาต่อสู้กับชนหมู่ใหญ่นี้ในพระนามของพระองค์ โอ ข้าแต่พระเยโฮวาห์ พระองค์ทรงเป็นพระเจ้าของข้าพระองค์ทั้งหลาย ขออย่าให้มนุษย์ชนะพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 12, 'พระเยโฮวาห์จึงทรงให้ชาวเอธิโอเปียพ่ายแพ้ต่ออาสาและต่อยูดาห์ และชาวเอธิโอเปียก็หนีไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 13, 'อาสาและพลที่อยู่กับพระองค์ก็ไล่ตามเขาไปถึงเมืองเก-ราร์ และชาวเอธิโอเปียล้มตายมากจนไม่เหลือสักชีวิตเดียว เพราะเขาได้แตกพ่ายต่อพระพักตร์พระเยโฮวาห์และกองทัพของพระองค์ คนยูดาห์ได้เก็บของที่ริบได้มากมายนักหนา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 14, 'และเขาก็โจมตีบรรดาหัวเมืองรอบเมืองเก-ราร์ เพราะว่าความกลัวพระเยโฮวาห์นั้นมาครอบเขาทั้งหลาย เขาได้ปล้นหัวเมืองทั้งสิ้น เพราะมีของที่ริบได้ในนั้นมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 15, 'และเขาได้โจมตีเต็นท์ของผู้ที่มีวัว และเอาแกะไปมากมายและอูฐด้วย แล้วเขาก็กลับไปยังเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 1, 'พระวิญญาณของพระเจ้าเสด็จมาสถิตกับอาซาริยาห์บุตรชายโอเดด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 2, 'และท่านออกไปเฝ้าอาสาทูลพระองค์ว่า “ข้าแต่อาสา และยูดาห์กับเบนยามินทั้งปวง ขอจงฟังข้าพเจ้า พระเยโฮวาห์ทรงสถิตกับท่านทั้งหลาย ต่อเมื่อท่านทั้งหลายอยู่กับพระองค์ ถ้าท่านทั้งหลายแสวงหาพระองค์ ท่านก็จะพบพระองค์ แต่ถ้าท่านทั้งหลายทอดทิ้งพระองค์ พระองค์จะทรงทอดทิ้งท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 3, 'อิสราเอลอยู่ปราศจากพระเจ้าเที่ยงแท้เป็นเวลานาน และไม่มีปุโรหิตผู้สั่งสอน และไม่มีพระราชบัญญัติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 4, 'แต่เมื่อถึงคราวเขาทุกข์ยากลําบาก เขาหันมาหาพระเยโฮวาห์พระเจ้าแห่งอิสราเอลและแสวงหาพระองค์ เขาทั้งหลายก็พบพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 5, 'ในสมัยนั้นไม่มีสันติภาพแก่ผู้ที่ออกไปหรือผู้ที่เข้ามา เพราะมีการวุ่นวายอยู่มากมายรบกวนชาวเมืองทั้งหลายนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 6, 'เขาแตกแยกกันเป็นพวกๆ ประชาชาติต่อประชาชาติและเมืองต่อเมือง เพราะพระเจ้าทรงรบกวนเขาด้วยความทุกข์ยากทุกอย่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 7, 'แต่ท่านทั้งหลายจงกล้าหาญ อย่าให้มือของท่านอ่อนลง เพราะว่ากิจการของท่านจะได้รับบําเหน็จ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 8, 'เมื่ออาสาทรงสดับถ้อยคําเหล่านี้ คือคําพยากรณ์ของโอเดดผู้พยากรณ์ พระองค์ก็ทรงมีพระทัยกล้าขึ้น ทรงกําจัดสิ่งที่น่าสะอิดสะเอียนจากแผ่นดินยูดาห์และเบนยามินสิ้น และจากหัวเมืองซึ่งพระองค์ยึดมาได้จากถิ่นเทือกเขาเอฟราอิม และพระองค์ทรงซ่อมแซมแท่นบูชาของพระเยโฮวาห์ ซึ่งอยู่หน้ามุขพระนิเวศของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 9, 'และพระองค์ทรงรวบรวมยูดาห์และเบนยามินทั้งปวง และคนเหล่านั้นจากเอฟราอิม มนัสเสห์ และจากสิเมโอน ผู้อาศัยอยู่กับเขาทั้งหลาย เพราะคนเป็นจํานวนมากได้หลบหนีมาหาพระองค์จากอิสราเอล เมื่อเขาเห็นว่าพระเยโฮวาห์พระเจ้าของพระองค์สถิตกับพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 10, 'เขาทั้งหลายชุมนุมกันที่เยรูซาเล็มในเดือนที่สามของปีที่สิบห้าในรัชกาลของอาสา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 11, 'เขาทั้งหลายถวายสัตวบูชาแด่พระเยโฮวาห์ในวันนั้นจากข้าวของที่เขาได้ริบมา มีวัวผู้เจ็ดร้อยตัวและแกะเจ็ดพันตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 12, 'และเขาก็เข้าทําพันธสัญญาที่จะแสวงหาพระเยโฮวาห์พระเจ้าแห่งบรรพบุรุษของเขาด้วยสุดจิตสุดใจของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 13, 'และว่าผู้ใดที่ไม่แสวงหาพระเยโฮวาห์พระเจ้าแห่งอิสราเอลควรจะมีโทษถึงตาย ไม่ว่าเล็กหรือใหญ่ ชายหรือหญิง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 14, 'เขาทั้งหลายได้กระทําสัตย์สาบานต่อพระเยโฮวาห์ด้วยเสียงอันดัง และด้วยเสียงโห่ร้อง และด้วยเสียงแตรและแตรทองเหลืองขนาดเล็ก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 15, 'และยูดาห์ทั้งปวงก็เปรมปรีดิ์เพราะคําสัตย์สาบานนั้น เพราะเขาทั้งหลายได้สาบานด้วยสุดใจของเขา และได้แสวงหาพระองค์ด้วยสิ้นความปรารถนาของเขา และเขาทั้งหลายก็พบพระองค์ และพระเยโฮวาห์ทรงประทานให้เขาหยุดพักสงบรอบด้าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 16, 'แม้ว่ามาอาคาห์พระราชมารดาของกษัตริย์อาสา พระองค์ก็ทรงถอดเสียจากเป็นพระราชชนนี เพราะพระนางได้กระทํารูปเคารพอันน่าเกลียดน่าชังในเสารูปเคารพ อาสาทรงโค่นรูปเคารพของพระนางลง และบดและเผาเสียที่ลําธารขิดโรน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 17, 'แต่ยังมิได้กําจัดปูชนียสถานสูงออกเสียจากอิสราเอล อย่างไรก็ดีพระทัยของอาสาก็บริสุทธิ์ตลอดรัชสมัยของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 18, 'และพระองค์ทรงนําของถวายของราชบิดาของพระองค์และข้าวของที่พระองค์เองทรงถวาย มีเงิน และทองคํา และเครื่องใช้เข้าไปในพระนิเวศของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 19, 'และไม่มีสงครามอีกจนปีที่สามสิบห้าในรัชกาลของอาสา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 1, 'ในปีที่สามสิบหกแห่งรัชกาลอาสา บาอาชากษัตริย์แห่งอิสราเอลขึ้นมาต่อสู้กับยูดาห์และได้สร้างเมืองรามาห์ เพื่อว่าพระองค์จะมิทรงให้คนหนึ่งคนใดออกไปหรือเข้ามาหาอาสากษัตริย์ของยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 2, 'แล้วอาสาทรงเอาเงินและทองคําจากคลังของพระนิเวศของพระเยโฮวาห์และราชสํานัก และส่งไปให้เบนฮาดัดกษัตริย์แห่งซีเรียผู้ประทับในเมืองดามัสกัสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 3, '“ขอให้มีสัญญาไมตรีระหว่างข้าพเจ้าและท่านดังที่มีอยู่กับพระชนกของข้าพเจ้าและพระชนกของท่าน ดูเถิด ข้าพเจ้าได้ส่งเงินและทองคํามายังท่าน ขอเสด็จไปทําลายสัญญาไมตรีของท่านซึ่งมีกับบาอาชากษัตริย์แห่งอิสราเอล เพื่อเขาจะถอยทัพไปจากข้าพเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 4, 'และเบนฮาดัดทรงเชื่อฟังกษัตริย์อาสา และส่งผู้บังคับบัญชากองทัพของพระองค์ไปต่อสู้กับหัวเมืองของอิสราเอล และเขาทั้งหลายโจมตีเมืองอิโยน ดาน เอเบลมาอิม และหัวเมืองคลังหลวงทั้งสิ้นของนัฟทาลี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 5, 'และต่อมาเมื่อบาอาชาทรงได้ยินเรื่องนั้น พระองค์ทรงหยุดสร้างเมืองรามาห์ และให้พระราชกิจของพระองค์หยุดยั้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 6, 'แล้วกษัตริย์อาสาทรงนํายูดาห์ทั้งสิ้น และเขาทั้งหลายขนหินของเมืองรามาห์และเครื่องไม้ของเมืองนั้น ซึ่งบาอาชาใช้สร้างอยู่นั้น และเอามาสร้างเมืองเกบาและเมืองมิสปาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 7, 'ครั้งนั้นฮานานีผู้ทํานายได้มาเฝ้าอาสากษัตริย์ของยูดาห์ และทูลพระองค์ว่า “เพราะท่านพึ่งกษัตริย์ของซีเรีย และมิได้พึ่งพระเยโฮวาห์พระเจ้าของท่าน เพราะฉะนั้นกองทัพของกษัตริย์ซีเรียจึงได้หลุดพ้นมือท่านไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 8, 'คนเอธิโอเปียและชาวลิบนีไม่เป็นกองทัพมหึมา มีรถรบและพลม้ามากเหลือหลายหรือ แต่เพราะท่านพึ่งพระเยโฮวาห์ พระองค์ทรงมอบเขาทั้งหลายไว้ในมือของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 9, 'เพราะว่าพระเนตรของพระเยโฮวาห์ไปมาอยู่เหนือแผ่นดินโลกทั้งสิ้น เพื่อสําแดงฤทธานุภาพของพระองค์โดยเห็นแก่ผู้เหล่านั้นที่จริงใจต่อพระองค์ ในเรื่องนี้ท่านได้กระทําการอย่างโง่เขลา เพราะตั้งแต่นี้ไปท่านจะมีการศึกสงคราม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 10, 'และอาสาก็ทรงกริ้วต่อผู้ทํานายนั้น และจับเขาจําไว้ในคุก เพราะพระองค์ทรงเกรี้ยวกราดแก่เขาในเรื่องนี้ และอาสาทรงข่มเหงประชาชนบางคนในเวลาเดียวกันนั้นด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 11, 'และดูเถิด พระราชกิจของอาสา ตั้งแต่ต้นจนสุดท้าย ได้บันทึกไว้ในหนังสือของกษัตริย์แห่งยูดาห์และอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 12, 'ในปีที่สามสิบเก้าแห่งรัชกาลของพระองค์ อาสาทรงเป็นโรคที่พระบาทของพระองค์ และโรคของพระองค์ก็ร้ายแรง แม้เป็นโรคอยู่พระองค์ก็มิได้ทรงแสวงหาพระเยโฮวาห์ แต่ได้แสวงหาความช่วยเหลือจากแพทย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 13, 'และอาสาทรงล่วงหลับไปอยู่กับบรรพบุรุษของพระองค์ สิ้นพระชนม์ในปีที่สี่สิบเอ็ดแห่งรัชกาลของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 14, 'เขาทั้งหลายฝังพระศพไว้ในอุโมงค์ของพระองค์ ซึ่งพระองค์ได้สกัดออกเพื่อพระองค์ในนครดาวิด เขาวางพระศพของพระองค์ไว้บนแท่นซึ่งมีเครื่องหอมต่างๆเต็มไปหมด ซึ่งช่างปรุงเครื่องหอมได้ปรุงไว้ และเขาทั้งหลายก็ก่อเพลิงใหญ่โตถวายพระเกียรติพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 1, 'เยโฮชาฟัทโอรสของพระองค์ครอบครองแทนพระองค์ และทรงเสริมกําลังพลต่อสู้อิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 2, 'พระองค์ทรงวางกําลังพลไว้ในหัวเมืองที่มีป้อมทั้งปวงของยูดาห์ และทรงตั้งทหารประจําป้อมในแผ่นดินยูดาห์ และในหัวเมืองเอฟราอิม ซึ่งอาสาราชบิดาของพระองค์ได้ยึดไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 3, 'พระเยโฮวาห์ทรงสถิตกับเยโฮชาฟัท เพราะพระองค์ทรงดําเนินในทางเบื้องต้นๆของดาวิดราชบิดาของพระองค์ พระองค์มิได้ทรงแสวงหาพระบาอัล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 4, 'แต่ได้แสวงหาพระเยโฮวาห์พระเจ้าของพระราชบิดาของพระองค์ และดําเนินในพระบัญญัติของพระองค์ มิได้ทรงดําเนินตามการกระทําของอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 5, 'เพราะฉะนั้นพระเยโฮวาห์ทรงสถาปนาราชอาณาจักรไว้ในพระหัตถ์ของพระองค์ และสิ้นทั้งยูดาห์ก็นําเครื่องบรรณาการมาถวายเยโฮชาฟัท พระองค์จึงมีทรัพย์มั่งคั่งอย่างยิ่งและมีเกียรติมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 6, 'พระทัยของพระองค์เข้มแข็งขึ้นในพระมรรคาของพระเยโฮวาห์ พระองค์จึงทรงกําจัดปูชนียสถานสูงและบรรดาเสารูปเคารพเสียจากยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 7, 'ในปีที่สามแห่งรัชกาลของพระองค์ พระองค์ทรงใช้เจ้านายของพระองค์คือ เบนฮาอิล โอบาดีห์ เศคาริยาห์ เนธันเอล และมีคายาห์ไปสั่งสอนในหัวเมืองของยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 8, 'และคนเลวีไปกับเขาด้วยคือ เชไมอาห์ เนธานิยาห์ เศบาดิยาห์ อาสาเฮล เชมิราโมท เยโฮนาธัน อาโดนียาห์ โทบียาห์ และโทบาโดนิยาห์ คนเลวี และพร้อมกับคนเหล่านี้มี เอลีชามา และเยโฮรัม ผู้เป็นปุโรหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 9, 'และเขาทั้งหลายได้สั่งสอนในยูดาห์ มีหนังสือพระราชบัญญัติของพระเยโฮวาห์ไปกับเขาด้วย เขาเที่ยวไปทั่วหัวเมืองทั้งสิ้นแห่งยูดาห์ และได้สั่งสอนประชาชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 10, 'ความหวาดกลัวอันมาจากพระเยโฮวาห์ตกอยู่เหนือบรรดาราชอาณาจักรแห่งแผ่นดินต่างๆที่อยู่รอบยูดาห์ และเขาทั้งหลายมิได้ทําสงครามกับเยโฮชาฟัท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 11, 'คนฟีลิสเตียบางพวกได้นําของกํานัลมาถวายเยโฮชาฟัท และนําเงินมาเป็นบรรณาการ และพวกอาระเบียได้นําฝูงแพะแกะ คือแกะผู้เจ็ดพันเจ็ดร้อยตัว และแพะผู้เจ็ดพันเจ็ดร้อยตัวมาถวายพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 12, 'และเยโฮชาฟัททรงเจริญใหญ่ยิ่งขึ้นเป็นลําดับ พระองค์ทรงสร้างป้อมและหัวเมืองคลังหลวงไว้ในยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 13, 'และพระองค์ทรงมีพระราชกิจมากมายในหัวเมืองของยูดาห์ พระองค์ทรงมีทหารเป็นทแกล้วทหารในกรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 14, 'ต่อไปนี้เป็นจํานวนตามเรือนบรรพบุรุษของเขาคือ ของยูดาห์ ผู้บังคับบัญชากองพันมี อัดนาห์ผู้บังคับบัญชา พร้อมกับทแกล้วทหารสามแสนคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 15, 'ถัดเขาไปคือ เยโฮฮานัน ผู้บังคับบัญชาพร้อมกับสองแสนแปดหมื่นคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 16, 'และถัดเขาไปคือ อามัสยาห์ บุตรชายศิครี เป็นคนอาสาสมัครเพื่อการปรนนิบัติพระเยโฮวาห์พร้อมกับทแกล้วทหารสองแสนคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 17, 'ของเบนยามินคือ เอลียาดา ทแกล้วทหารพร้อมกับคนสองแสนพร้อมสรรพด้วยธนูและโล่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 18, 'และถัดเขาไปคือ เยโฮซาบาด พร้อมกับคนติดอาวุธหนึ่งแสนแปดหมื่นคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 19, 'เหล่านี้เป็นข้าราชการของกษัตริย์ นอกเหนือจากผู้ที่กษัตริย์ทรงวางไว้ในหัวเมืองที่มีป้อมทั่วตลอดแผ่นดินยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 1, 'ฝ่ายเยโฮชาฟัททรงมีทรัพย์มั่งคั่งและเกียรติใหญ่ยิ่ง และพระองค์ทรงกระทําให้เป็นทองแผ่นเดียวกันกับอาหับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 2, 'ครั้นล่วงมาหลายปีพระองค์เสด็จลงไปเฝ้าอาหับในสะมาเรีย และอาหับทรงฆ่าแกะและวัวมากมายสําหรับพระองค์ และสําหรับพลที่มากับพระองค์ และทรงชักชวนพระองค์ให้ขึ้นไปต่อสู้กับราโมทกิเลอาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 3, 'อาหับกษัตริย์แห่งอิสราเอลตรัสกับเยโฮชาฟัทกษัตริย์แห่งยูดาห์ว่า “ท่านจะไปกับข้าพเจ้ายังราโมทกิเลอาดหรือ” พระองค์ทูลตอบพระองค์ว่า “ข้าพเจ้าก็เป็นอย่างที่ท่านเป็น ประชาชนของข้าพเจ้าก็เป็นดังประชาชนของท่าน เราจะอยู่กับท่านในการสงคราม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 4, 'และเยโฮชาฟัทตรัสกับกษัตริย์แห่งอิสราเอลว่า “ขอสอบถามดูพระดํารัสของพระเยโฮวาห์วันนี้เสียก่อน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 5, 'แล้วกษัตริย์แห่งอิสราเอลก็เรียกประชุมพวกผู้พยากรณ์ประมาณสี่ร้อยคนตรัสกับเขาว่า “ควรที่เราจะไปตีราโมทกิเลอาดหรือ หรือเราไม่ควรไป” และเขาทั้งหลายทูลตอบว่า “ขอเชิญเสด็จขึ้นไปเถิด เพราะพระเจ้าจะทรงมอบไว้ในพระหัตถ์ของกษัตริย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 6, 'แต่เยโฮชาฟัททูลว่า “ที่นี่ไม่มีผู้พยากรณ์ของพระเยโฮวาห์อีกสักคนหนึ่งหรือซึ่งเราจะสอบถามได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 7, 'และกษัตริย์แห่งอิสราเอลทูลเยโฮชาฟัทว่า “ยังมีชายอีกคนหนึ่ง ซึ่งเราจะให้ทูลถามพระเยโฮวาห์ได้ แต่ข้าพเจ้าชังเขา เพราะเขาพยากรณ์แต่ความร้ายเสมอ ไม่เคยพยากรณ์ความดีเกี่ยวกับข้าพเจ้าเลย คนนั้นคือมีคายาห์บุตรอิมลาห์” และเยโฮชาฟัททูลว่า “ขอกษัตริย์อย่าตรัสดังนั้นเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 8, 'แล้วกษัตริย์แห่งอิสราเอลจึงเรียกมหาดเล็กคนหนึ่งเข้ามาและตรัสสั่งว่า “ไปพามีคายาห์บุตรอิมลาห์มาเร็วๆ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 9, 'ฝ่ายกษัตริย์แห่งอิสราเอลและเยโฮชาฟัทกษัตริย์แห่งยูดาห์ ต่างประทับบนพระที่นั่ง ทรงฉลองพระองค์ ณ ที่ว่างตรงทางเข้าประตูเมืองสะมาเรีย และผู้พยากรณ์ทั้งปวงก็พยากรณ์ถวายอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 10, 'และเศเดคียาห์บุตรชายเคนาอะนาห์ จึงเอาเหล็กทําเป็นเขา และพูดว่า “พระเยโฮวาห์ตรัสดังนี้ว่า ‘ด้วยสิ่งเหล่านี้ เจ้าจะผลักคนซีเรียไปจนเขาทั้งหลายถูกทําลาย’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 11, 'และบรรดาผู้พยากรณ์ก็พยากรณ์อย่างนั้น ทูลว่า “ขอเสด็จขึ้นไปราโมทกิเลอาดเถิด และจะมีชัยชนะ เพราะพระเยโฮวาห์จะทรงมอบเมืองนั้นไว้ในพระหัตถ์ของกษัตริย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 12, 'และผู้สื่อสารผู้ไปตามมีคายาห์ได้บอกท่านว่า “ดูเถิด ถ้อยคําของบรรดาผู้พยากรณ์ก็พูดสิ่งที่ดีแก่กษัตริย์ดุจปากเดียวกัน ขอให้ถ้อยคําของท่านเหมือนอย่างถ้อยคําของคนหนึ่งในพวกนั้น และพูดแต่สิ่งที่ดี”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 13, 'แต่มีคายาห์ตอบว่า “พระเยโฮวาห์ทรงพระชนม์อยู่แน่ฉันใด พระเจ้าของข้าพเจ้าตรัสว่าอย่างไร ข้าพเจ้าจะพูดอย่างนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 14, 'และเมื่อท่านมาเฝ้ากษัตริย์ กษัตริย์ตรัสถามท่านว่า “มีคายาห์ ควรที่เราจะไปตีราโมทกิเลอาดหรือ หรือเราไม่ควรไป” และท่านทูลตอบพระองค์ว่า “ขอเชิญเสด็จขึ้นไปและจะมีชัยชนะ เขาทั้งหลายจะถูกมอบไว้ในพระหัตถ์ของพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 15, 'แต่กษัตริย์ตรัสกับท่านว่า “เราได้ให้เจ้าปฏิญาณกี่ครั้งแล้วว่า เจ้าจะพูดกับเราแต่ความจริงในพระนามของพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 16, 'และท่านทูลว่า “ข้าพระองค์ได้เห็นคนอิสราเอลทั้งปวงกระจัดกระจายอยู่บนภูเขา อย่างแกะที่ไม่มีผู้เลี้ยง และพระเยโฮวาห์ตรัสว่า ‘คนเหล่านี้ไม่มีนาย ให้เขาต่างกลับยังเรือนของตนโดยสันติภาพเถิด’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 17, 'กษัตริย์แห่งอิสราเอลจึงทูลเยโฮชาฟัทว่า “ข้าพเจ้ามิได้บอกท่านแล้วหรือว่า เขาจะไม่พยากรณ์สิ่งดีเกี่ยวกับข้าพเจ้าเลย แต่สิ่งชั่วร้ายต่างหาก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 18, 'และมีคายาห์ทูลว่า “ฉะนั้นขอสดับพระวจนะของพระเยโฮวาห์ ข้าพระองค์ได้เห็นพระเยโฮวาห์ประทับบนพระที่นั่งของพระองค์ และบรรดาบริวารแห่งฟ้าสวรรค์ยืนข้างๆพระองค์ข้างขวาพระหัตถ์และข้างซ้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 19, 'และพระเยโฮวาห์ตรัสว่า ‘ผู้ใดจะเกลี้ยกล่อมอาหับกษัตริย์แห่งอิสราเอล เพื่อเขาจะขึ้นไปและล้มลงที่ราโมทกิเลอาด’ บ้างก็ทูลอย่างนี้ บ้างก็ทูลอย่างนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 20, 'แล้วมีวิญญาณดวงหนึ่งมาข้างหน้าเฝ้าต่อพระพักตร์พระเยโฮวาห์ทูลว่า ‘ข้าพระองค์จะเกลี้ยกล่อมเขาเอง’ และพระเยโฮวาห์ตรัสกับเขาว่า ‘จะทําอย่างไร’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 21, 'และเขาทูลว่า ‘ข้าพระองค์จะออกไปและจะเป็นวิญญาณมุสาอยู่ในปากของผู้พยากรณ์ของเขาทุกคน’ และพระเยโฮวาห์ตรัสว่า ‘เจ้าไปเกลี้ยกล่อมเขาได้ และเจ้าจะทําได้สําเร็จ จงไปทําเช่นนั้นเถิด’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 22, 'เพราะฉะนั้นบัดนี้ ดูเถิด พระเยโฮวาห์ทรงใส่วิญญาณมุสาในปากของเหล่าผู้พยากรณ์ของพระองค์ พระเยโฮวาห์ทรงลั่นพระวาจาเป็นความร้ายเกี่ยวกับพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 23, 'แล้วเศเดคียาห์บุตรชายเคนาอะนาห์ได้เข้ามาใกล้และตบแก้มมีคายาห์พูดว่า “พระวิญญาณของพระเยโฮวาห์ไปจากข้าพูดกับเจ้าได้อย่างไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 24, 'และมีคายาห์ตอบว่า “ดูเถิด เจ้าจะเห็นในวันนั้น เมื่อเจ้าเข้าไปในห้องชั้นในเพื่อจะซ่อนตัวเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 25, 'และกษัตริย์แห่งอิสราเอลตรัสว่า “จงจับมีคายาห์ พาเขากลับไปมอบให้อาโมนผู้ว่าราชการเมือง และแก่โยอาชราชโอรส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 26, 'และว่า ‘กษัตริย์ตรัสดังนี้ว่า เอาคนนี้จําคุกเสีย ให้อาหารแห่งความทุกข์กับน้ําแห่งความทุกข์ จนกว่าเราจะกลับมาโดยสันติภาพ’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 27, 'และมีคายาห์ทูลว่า “ถ้าพระองค์เสด็จกลับมาโดยสันติภาพ พระเยโฮวาห์ก็มิได้ตรัสโดยข้าพระองค์” และท่านกล่าวว่า “บรรดาชนชาติทั้งหลายเอ๋ย ขอจงฟังเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 28, 'กษัตริย์แห่งอิสราเอลกับเยโฮชาฟัทกษัตริย์แห่งยูดาห์จึงเสด็จขึ้นไปยังราโมทกิเลอาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 29, 'และกษัตริย์แห่งอิสราเอลตรัสกับเยโฮชาฟัทว่า “ข้าพเจ้าจะปลอมตัวเข้าทําศึก แต่ท่านจงสวมเครื่องทรงของท่าน” และกษัตริย์แห่งอิสราเอลก็ทรงปลอมพระองค์ แล้วทั้งสองพระองค์เข้าทําสงคราม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 30, 'ฝ่ายกษัตริย์ประเทศซีเรียทรงบัญชาบรรดาผู้บัญชาการรถรบของพระองค์ว่า “อย่ารบกับทหารน้อยหรือใหญ่ แต่มุ่งเฉพาะกษัตริย์แห่งอิสราเอล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 31, 'และอยู่มาเมื่อผู้บัญชาการรถรบแลเห็นเยโฮชาฟัท เขาทั้งหลายก็ว่า “เป็นกษัตริย์อิสราเอลแล้ว” เขาจึงหันเข้าไปจะสู้รบกับพระองค์ และเยโฮชาฟัททรงร้องขึ้น และพระเยโฮวาห์ทรงช่วยพระองค์ พระเจ้าทรงให้เขาทั้งหลายออกไปเสียจากพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 32, 'และอยู่มาเมื่อผู้บัญชาการรถรบเห็นว่าไม่ใช่กษัตริย์อิสราเอล ก็หันรถกลับจากไล่ตามพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 33, 'แต่มีชายคนหนึ่งโก่งธนูยิงเดาไป ถูกกษัตริย์แห่งอิสราเอลเข้าระหว่างเกล็ดเกราะและแผ่นบังพระอุระ พระองค์จึงรับสั่งคนขับรถรบว่า “หันกลับเถอะ พาเราออกจากการรบ เพราะเราบาดเจ็บแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 34, 'วันนั้นการรบก็ดุเดือดขึ้น และกษัตริย์อิสราเอลก็พยุงพระองค์เองขึ้นไปในรถรบของพระองค์หันพระพักตร์เข้าสู้ชนซีเรียจนถึงเวลาเย็น แล้วประมาณเวลาดวงอาทิตย์ตกพระองค์ก็สิ้นพระชนม์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 1, 'เยโฮชาฟัทกษัตริย์แห่งยูดาห์เสด็จกลับไปโดยสวัสดิภาพถึงพระราชวังของพระองค์ในกรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 2, 'แต่เยฮูบุตรชายฮานานีผู้ทํานายได้ออกไปเฝ้าพระองค์ ทูลกษัตริย์เยโฮชาฟัทว่า “ควรที่พระองค์จะช่วยคนอธรรมและรักผู้ที่เกลียดชังพระเยโฮวาห์หรือ เพราะเรื่องนี้พระพิโรธของพระเยโฮวาห์ได้ออกมาถึงพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 3, 'อย่างไรก็ดีพระองค์ทรงพบความดีในพระองค์บ้าง เพราะพระองค์ได้ทําลายบรรดาเสารูปเคารพเสียจากแผ่นดิน และได้มุ่งพระทัยแสวงหาพระเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 4, 'เยโฮชาฟัทประทับที่เยรูซาเล็ม และพระองค์ทรงออกไปท่ามกลางประชาชนอีก ตั้งแต่เบเออร์เชบาถึงถิ่นเทือกเขาเอฟราอิม และนําเขาทั้งหลายกลับมายังพระเยโฮวาห์พระเจ้าแห่งบรรพบุรุษของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 5, 'พระองค์ทรงตั้งผู้วินิจฉัยในแผ่นดินนั้น ในหัวเมืองที่มีป้อมทั้งสิ้นของยูดาห์ ทีละหัวเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 6, 'และตรัสกับผู้วินิจฉัยเหล่านั้นว่า “จงพิจารณาสิ่งที่ท่านทั้งหลายจะกระทํา เพราะท่านมิได้พิพากษาเพื่อมนุษย์แต่เพื่อพระเยโฮวาห์ พระองค์ทรงสถิตกับท่านในการพิพากษา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 7, 'ฉะนั้นจงให้ความยําเกรงพระเยโฮวาห์อยู่เหนือท่าน จงระมัดระวังสิ่งที่ท่านกระทํา เพราะพระเยโฮวาห์พระเจ้าของเราไม่มีความชั่วช้า ไม่เห็นแก่หน้าคนใด และไม่มีการรับสินบน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 8, 'ยิ่งกว่านั้นอีก ในเยรูซาเล็ม เยโฮชาฟัททรงตั้งคนเลวี และปุโรหิตบ้าง กับประมุขของบรรพบุรุษแห่งอิสราเอลบ้าง เพื่อจะให้การพิพากษาแห่งพระเยโฮวาห์ และวินิจฉัยคดีที่โต้แย้งกัน เขาทั้งหลายมีตําแหน่งในเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 9, 'และพระองค์ทรงกําชับเขาทั้งหลายว่า “ท่านทั้งหลายจงกระทําการนี้ด้วยความยําเกรงพระเยโฮวาห์ ด้วยความสัตย์ซื่อ และด้วยสิ้นสุดใจของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 10, 'เมื่อมีคดีมาถึงท่านจากพี่น้องของท่านผู้อาศัยอยู่ในหัวเมืองของเขาทั้งหลาย เกี่ยวกับเรื่องฆ่าฟันกัน พระราชบัญญัติหรือพระบัญญัติ กฎเกณฑ์หรือคําตัดสิน ท่านทั้งหลายก็ควรจะตักเตือนเขา เพื่อเขาจะไม่ละเมิดต่อพระเยโฮวาห์ พระพิโรธจึงจะไม่มาเหนือท่านและพี่น้องของท่าน ท่านจงกระทําเช่นนี้ และท่านจะไม่ละเมิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 11, 'และดูเถิด อามาริยาห์ปุโรหิตใหญ่ก็อยู่เหนือท่านในสรรพกิจของพระเยโฮวาห์ และเศบาดิยาห์บุตรชายอิชมาเอลเจ้านายของวงศ์วานยูดาห์ก็อยู่เหนือท่านในสรรพกิจของกษัตริย์ และเลวีจะเป็นเจ้าหน้าที่ปรนนิบัติท่าน จงประกอบกิจอย่างแกล้วกล้า และขอพระเยโฮวาห์ทรงสถิตอยู่กับผู้มีคุณธรรม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 1, 'และอยู่มาภายหลัง คนโมอับและคนอัมโมน และพร้อมกับเขามีคนอื่นนอกจากคนอัมโมนนั้นได้ขึ้นมาทําสงครามกับเยโฮชาฟัท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 2, 'มีคนมาทูลเยโฮชาฟัทว่า “มีคนหมู่ใหญ่มาสู้รบกับพระองค์จากซีเรียข้างนี้ จากฟากทะเลข้างโน้น และดูเถิด เขาทั้งหลายอยู่ในฮาซาโซนทามาร์ คือเอนเกดี”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 3, 'และเยโฮชาฟัทก็กลัว และมุ่งแสวงหาพระเยโฮวาห์ และได้ทรงประกาศให้อดอาหารทั่วยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 4, 'และยูดาห์ได้ชุมนุมกันแสวงหาความช่วยเหลือจากพระเยโฮวาห์ เขาทั้งหลายพากันมาจากหัวเมืองทั้งสิ้นแห่งยูดาห์เพื่อแสวงหาพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 5, 'และเยโฮชาฟัทประทับยืนอยู่ในที่ประชุมของยูดาห์และเยรูซาเล็ม ในพระนิเวศของพระเยโฮวาห์ ข้างหน้าลานใหม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 6, 'และตรัสทูลว่า “โอ ข้าแต่พระเยโฮวาห์พระเจ้าแห่งบรรพบุรุษของข้าพเจ้าทั้งหลาย พระองค์มิได้เป็นพระเจ้าในฟ้าสวรรค์หรือ พระองค์มิได้ปกครองเหนือบรรดาราชอาณาจักรของประชาชาติหรือ ในพระหัตถ์ของพระองค์มีฤทธิ์และอํานาจ จึงไม่มีผู้ใดต่อต้านพระองค์ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 7, 'พระองค์เป็นพระเจ้าของข้าพระองค์ทั้งหลายมิใช่หรือ ผู้ทรงขับไล่ชาวแผ่นดินนี้ออกไปเสียให้พ้นหน้าอิสราเอลประชาชนของพระองค์ และทรงมอบไว้แก่เชื้อสายของอับราฮัมมิตรสหายของพระองค์เป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 8, 'และเขาทั้งหลายได้อาศัยอยู่ในนั้น และได้สร้างสถานบริสุทธิ์แห่งหนึ่งในนั้นถวายพระองค์ เพื่อพระนามของพระองค์ ทูลว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 9, '‘ถ้าเหตุชั่วร้ายขึ้นมาเหนือข้าพระองค์ทั้งหลาย จะเป็นดาบ การพิพากษา หรือโรคระบาด หรือการกันดารอาหาร ข้าพระองค์ทั้งหลายจะยืนอยู่ต่อหน้าพระนิเวศนี้ และต่อพระพักตร์พระองค์ (เพราะพระนามของพระองค์อยู่ในพระนิเวศนี้) และร้องทูลต่อพระองค์ในความทุกข์ใจของข้าพระองค์ทั้งหลาย และพระองค์จะทรงฟังและช่วยให้รอด’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 10, 'ดูเถิด บัดนี้คนอัมโมนและโมอับ และภูเขาเสอีร์ ผู้ซึ่งพระองค์ไม่ทรงยอมให้คนอิสราเอลบุกรุก เมื่อเขามาจากแผ่นดินอียิปต์ และผู้ซึ่งเขาได้หลีกไปมิได้ทําลายเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 11, 'ดูเถิด เขาทั้งหลายได้ให้บําเหน็จแก่เราอย่างไร ด้วยมาขับเราออกเสียจากแผ่นดินกรรมสิทธิ์ของพระองค์ ซึ่งพระองค์ประทานให้แก่ข้าพระองค์ทั้งหลายเป็นมรดก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 12, 'โอ ข้าแต่พระเจ้าของข้าพระองค์ทั้งหลาย พระองค์จะไม่ทรงกระทําการพิพากษาเหนือเขาหรือ เพราะว่าข้าพระองค์ทั้งหลายไม่มีฤทธิ์ที่จะต่อสู้คนหมู่มหึมานี้ซึ่งกําลังมาต่อสู้กับข้าพระองค์ทั้งหลาย ข้าพระองค์ทั้งหลายไม่ทราบว่าจะกระทําประการใด แต่ดวงตาของข้าพระองค์ทั้งหลายเพ่งที่พระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 13, 'ในระหว่างนั้นคนทั้งปวงของยูดาห์ก็ยืนอยู่ต่อพระพักตร์พระเยโฮวาห์พร้อมกับภรรยาและลูกหลานของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 14, 'และพระวิญญาณของพระเยโฮวาห์เสด็จมาสถิตกับยาฮาซีเอลบุตรชายเศคาริยาห์ ผู้เป็นบุตรชายเบไนยาห์ ผู้เป็นบุตรชายเยอีเอล ผู้เป็นบุตรชายมัทธานิยาห์ เป็นคนเลวี ลูกหลานของอาสาฟ เมื่อท่านอยู่ท่ามกลางที่ประชุมนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 15, 'และเขาได้พูดว่า “ยูดาห์ทั้งปวง และชาวเยรูซาเล็มทั้งหลาย กับกษัตริย์เยโฮชาฟัทขอจงฟัง พระเยโฮวาห์ตรัสดังนี้แก่ท่านทั้งหลายว่า ‘อย่ากลัวเลย และอย่าท้อถอยด้วยคนหมู่มหึมานี้เลย เพราะว่าการสงครามนั้นไม่ใช่ของท่าน แต่เป็นของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 16, 'พรุ่งนี้ท่านทั้งหลายจงลงไปต่อสู้กับเขา ดูเถิด เขาจะขึ้นมาทางขึ้นที่ตําบลศิส ท่านจะพบเขาที่ปลายลําธาร ข้างหน้าถิ่นทุรกันดารเยรูเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 17, 'ไม่จําเป็นที่ท่านจะต้องสู้รบในสงครามครั้งนี้ โอ ยูดาห์และเยรูซาเล็ม จงเข้าประจําที่ ยืนนิ่งอยู่และดูชัยชนะของพระเยโฮวาห์เพื่อท่าน’ อย่ากลัวเลย อย่าท้อถอย พรุ่งนี้จงออกไปสู้กับเขา เพราะพระเยโฮวาห์จะทรงสถิตอยู่กับท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 18, 'แล้วเยโฮชาฟัทโน้มพระเศียรก้มพระพักตร์ของพระองค์ลงถึงดิน และยูดาห์ทั้งปวงกับชาวเยรูซาเล็มได้กราบลงต่อพระพักตร์พระเยโฮวาห์ นมัสการพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 19, 'และคนเลวี จากลูกหลานคนโคฮาท และลูกหลานคนโคราห์ ได้ยืนขึ้นถวายสรรเสริญแด่พระเยโฮวาห์พระเจ้าแห่งอิสราเอลด้วยเสียงอันดังในที่สูง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 20, 'และเขาทั้งหลายได้ลุกขึ้นแต่เช้า และออกไปในถิ่นทุรกันดารแห่งเทโคอา และเมื่อเขาออกไป เยโฮชาฟัทประทับยืนและตรัสว่า “โอ ยูดาห์และชาวเยรูซาเล็มเอ๋ย จงฟังข้าพเจ้า จงเชื่อพระเยโฮวาห์พระเจ้าของท่าน และท่านจะตั้งมั่นคงอยู่ จงเชื่อบรรดาผู้พยากรณ์ของพระองค์ และท่านจะสําเร็จผล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 21, 'และเมื่อพระองค์ได้ปรึกษากับประชาชนแล้ว พระองค์ได้ทรงแต่งตั้งบรรดาผู้ที่จะร้องเพลงถวายพระเยโฮวาห์ ให้สรรเสริญพระองค์ด้วยเครื่องประดับแห่งความบริสุทธิ์ ขณะเมื่อเขาเดินออกไปหน้าศัตรู และว่า “จงถวายโมทนาแด่พระเยโฮวาห์ เพราะความเมตตาของพระองค์ดํารงอยู่เป็นนิตย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 22, 'และเมื่อเขาทั้งหลายตั้งต้นร้องเพลงสรรเสริญ พระเยโฮวาห์ทรงจัดกองซุ่มคอยต่อสู้กับคนอัมโมน โมอับ และชาวภูเขาเสอีร์ ผู้ได้เข้ามาต่อสู้กับยูดาห์ ดังนั้นเขาทั้งหลายจึงแตกพ่ายไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 23, 'เพราะว่าคนของอัมโมนและของโมอับได้ลุกขึ้นต่อสู้กับชาวภูเขาเสอีร์ ทําลายเขาเสียอย่างสิ้นเชิง และเมื่อเขาทั้งหลายทําลายชาวเสอีร์หมดแล้ว เขาทั้งสิ้นช่วยกันทําลายซึ่งกันและกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 24, 'เมื่อยูดาห์ขึ้นไปอยู่ที่หอคอยที่ในถิ่นทุรกันดาร เขามองตรงไปที่คนหมู่ใหญ่นั้น และดูเถิด มีแต่ศพนอนอยู่บนแผ่นดิน ไม่มีสักคนเดียวที่รอดไปได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 25, 'เมื่อเยโฮชาฟัทและประชาชนของพระองค์มาเก็บของที่ริบจากเขาทั้งหลาย พร้อมกับศพทั้งหลายนั้นเขาพบสิ่งของเป็นจํานวนมาก ทั้งทรัพย์สมบัติและเพชรพลอยต่างๆ ซึ่งเขาเก็บมามากสําหรับตัวจนขนไปไม่ไหว เขาเก็บของที่ริบได้เหล่านั้นสามวัน เพราะมากเหลือเกิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 26, 'ในวันที่สี่เขาทั้งหลายได้ชุมนุมกันที่หุบเขาเบราคาห์ ด้วยที่นั่นเขาสรรเสริญพระเยโฮวาห์ เพราะฉะนั้นเขาจึงเรียกที่นั้นว่า หุบเขาเบราคาห์ จนถึงทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 27, 'แล้วเขาทั้งหลายกลับไปคนยูดาห์และเยรูซาเล็มทุกคน และเยโฮชาฟัททรงนําหน้ากลับไปยังเยรูซาเล็มด้วยความชื่นบาน เพราะพระเยโฮวาห์ได้ทรงกระทําให้เขาเปรมปรีดิ์เย้ยศัตรูของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 28, 'เขาทั้งหลายมายังเยรูซาเล็มด้วยพิณใหญ่ พิณเขาคู่ และแตร ยังพระนิเวศของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 29, 'และความกลัวพระเจ้ามาอยู่เหนือบรรดาราชอาณาจักรของประเทศทั้งปวง เมื่อเขาได้ยินว่าพระเยโฮวาห์ทรงต่อสู้ศัตรูของอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 30, 'แดนดินของเยโฮชาฟัทจึงสงบเงียบ เพราะว่าพระเจ้าของพระองค์ทรงประทานให้พระองค์มีการหยุดพักสงบอยู่รอบด้าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 31, 'ดังนี้แหละ เยโฮชาฟัททรงครอบครองอยู่เหนือยูดาห์ เมื่อพระองค์ทรงเริ่มครอบครองนั้นมีพระชนมายุสามสิบห้าพรรษา และพระองค์ทรงครอบครองในเยรูซาเล็มยี่สิบห้าปี พระราชมารดาของพระองค์ทรงพระนามว่า อาซูบาห์ บุตรสาวชิลหิ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 32, 'พระองค์ทรงดําเนินตามมรรคาของอาสาราชบิดาของพระองค์ และมิได้ทรงพรากไปจากทางนั้น พระองค์ทรงกระทําสิ่งที่ถูกต้องในสายพระเนตรของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 33, 'อย่างไรก็ดี ปูชนียสถานสูงยังไม่ได้ถูกกําจัดออกไป ประชาชนยังมิได้ปักใจในพระเจ้าแห่งบรรพบุรุษของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 34, 'ส่วนพระราชกิจนอกนั้นของเยโฮชาฟัท ตั้งแต่ต้นจนถึงที่สุด ดูเถิด ได้มีบันทึกไว้ในหนังสือของเยฮูบุตรชายฮานานี ซึ่งรวมเข้าในหนังสือของกษัตริย์แห่งอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 35, 'ต่อมาภายหลัง เยโฮชาฟัทกษัตริย์ของยูดาห์ได้ทรงร่วมงานกับอาหัสยาห์กษัตริย์ของอิสราเอลผู้ทรงกระทําการอย่างชั่วร้ายมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 36, 'พระองค์ทรงร่วมงานในเรื่องการสร้างเรือไปยังเมืองทารชิช และเขาทั้งหลายสร้างเรือในเอซีโอนเกเบอร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 37, 'แล้วเอลีเยเซอร์บุตรชายโดดาวาหุแห่งเมืองมาเรชาห์ได้พยากรณ์ถึงเยโฮชาฟัทว่า “เพราะพระองค์ทรงร่วมงานกับอาหัสยาห์ พระเยโฮวาห์จะทรงทําลายสิ่งที่ท่านกระทํา” เรือก็แตกไม่สามารถไปเมืองทารชิชได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 1, 'เยโฮชาฟัทก็ล่วงหลับไปอยู่กับบรรพบุรุษของพระองค์ และเขาฝังพระศพไว้กับบรรพบุรุษของพระองค์ในนครดาวิด และเยโฮรัมโอรสของพระองค์ครอบครองแทนพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 2, 'พระองค์ทรงมีพระอนุชา ผู้เป็นโอรสของเยโฮชาฟัทคือ อาซาริยาห์ เยฮีเอล เศคาริยาห์ อาซาริยาห์ มีคาเอล เชฟาทิยาห์ เหล่านี้ทั้งสิ้นเป็นโอรสของเยโฮชาฟัทกษัตริย์ของอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 3, 'พระราชบิดาของเขาทั้งหลายประทานเงิน ทองคํา และของอันมีค่ามากมาย พร้อมกับหัวเมืองที่มีป้อมในยูดาห์ แต่พระองค์ประทานราชอาณาจักรแก่เยโฮรัม เพราะว่าท่านเป็นโอรสหัวปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 4, 'เมื่อเยโฮรัมได้ขึ้นครอบครองราชอาณาจักรของราชบิดาของพระองค์และได้สถาปนาไว้แล้ว พระองค์ทรงประหารพระอนุชาของพระองค์เสียหมดด้วยดาบ ทั้งเจ้านายบางคนของอิสราเอลด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 5, 'เมื่อเยโฮรัมทรงเริ่มครอบครองนั้นพระองค์มีพระชนมายุสามสิบสองพรรษา และพระองค์ทรงครอบครองในเยรูซาเล็มแปดปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 6, 'และพระองค์ทรงดําเนินตามมรรคาของกษัตริย์ทั้งหลายแห่งอิสราเอล ตามอย่างที่ราชวงศ์อาหับกระทํา เพราะว่าธิดาของอาหับเป็นมเหสีของพระองค์ และพระองค์ทรงกระทําสิ่งที่ชั่วร้ายในสายพระเนตรพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 7, 'อย่างไรก็ดีพระเยโฮวาห์จะไม่ทรงทําลายราชวงศ์ของดาวิด เพราะเหตุพันธสัญญาซึ่งพระองค์ทรงกระทําไว้กับดาวิด และเหตุที่พระองค์ทรงสัญญาว่าจะประทานประทีปแก่ดาวิดและแก่ลูกหลานของพระองค์เป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 8, 'ในรัชกาลของพระองค์เอโดมได้กบฏออกห่างจากการปกครองของยูดาห์ และตั้งกษัตริย์ขึ้นเหนือตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 9, 'แล้วเยโฮรัมก็เสด็จออกไปพร้อมกับบรรดาเจ้านายและรถรบทั้งสิ้นของพระองค์ และพระองค์ทรงลุกขึ้นในกลางคืนโจมตีคนเอโดม ซึ่งมาล้อมพระองค์และผู้บังคับบัญชารถรบไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 10, 'เอโดมจึงได้กบฏออกห่างจากการปกครองของยูดาห์จนทุกวันนี้ ครั้งนั้นลิบนาห์ก็ได้กบฏออกห่างจากการปกครองของพระองค์ด้วย เพราะว่าพระองค์ได้ทรงทอดทิ้งพระเยโฮวาห์พระเจ้าแห่งบรรพบุรุษของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 11, 'ยิ่งกว่านั้นอีก พระองค์ทรงสร้างปูชนียสถานสูงในถิ่นเทือกเขาของยูดาห์ และทรงนําชาวเยรูซาเล็มไปทําการผิดประเวณี และทรงกระทําให้ยูดาห์ทําเช่นกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 12, 'และจดหมายฉบับหนึ่งมาถึงพระองค์จากเอลียาห์ผู้พยากรณ์ว่า “พระเยโฮวาห์พระเจ้าของดาวิดบรรพบุรุษของพระองค์ ตรัสดังนี้ว่า ‘เพราะเจ้ามิได้ดําเนินในบรรดามรรคาของเยโฮชาฟัทบิดาของเจ้า หรือในบรรดามรรคาของอาสากษัตริย์ของยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 13, 'แต่ได้ดําเนินในมรรคาของบรรดากษัตริย์แห่งอิสราเอล และได้นํายูดาห์กับชาวเยรูซาเล็มในการแพศยา อย่างกับการแพศยาแห่งราชวงศ์อาหับ และเจ้าได้ฆ่าพวกน้องชายของเจ้าเสียด้วย ผู้เป็นเชื้อวงศ์บิดาของเจ้า และพวกเขาดีกว่าเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 14, 'ดูเถิด พระเยโฮวาห์จะทรงนําภัยพิบัติอันยิ่งใหญ่มาเหนือชนชาติของเจ้า ลูกหลานของเจ้า เมียของเจ้า และข้าวของทั้งสิ้นของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 15, 'และตัวเจ้าเองจะมีความเจ็บป่วยสาหัสด้วยโรคลําไส้ของเจ้า จนกว่าลําไส้ของเจ้าจะออกมาเพราะเหตุโรคนั้นวันแล้ววันเล่า’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 16, 'ยิ่งกว่านั้น พระเยโฮวาห์ทรงเร้าให้ความโกรธของคนฟีลิสเตีย และของคนอาระเบีย ผู้อยู่ใกล้กับคนเอธิโอเปีย มีต่อเยโฮรัม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 17, 'และเขาทั้งหลายยกมาต่อสู้กับยูดาห์ และบุกรุกเข้าไปในนั้น และขนข้าวของทั้งสิ้นซึ่งมีในราชสํานัก ทั้งบรรดาโอรสและมเหสีของพระองค์ จึงไม่มีโอรสเหลือไว้ให้แก่พระองค์นอกจากเยโฮอาหาสโอรสองค์สุดท้องของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 18, 'ภายหลังเรื่องเหล่านี้ พระเยโฮวาห์ทรงกระทําให้ลําไส้ของเยโฮรัมเป็นโรคซึ่งรักษาไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 19, 'ต่อมาเป็นเวลาสิ้นสองปีลําไส้ของพระองค์ก็ออกมาเพราะโรคนั้น และพระองค์ก็สิ้นพระชนม์ด้วยความทุรนทุรายอย่างยิ่ง ประชาชนของพระองค์มิได้ก่อเพลิงถวายเกียรติแด่พระองค์ อย่างกับก่อเพลิงให้กับบรรพบุรุษของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 20, 'เมื่อพระองค์ทรงเริ่มครอบครองนั้น พระองค์มีพระชนมายุสามสิบสองพรรษา และทรงครอบครองในเยรูซาเล็มแปดปี และพระองค์ได้ทรงจากไปโดยไม่มีใครอาลัย เขาก็ฝังพระศพไว้ในนครดาวิด แต่ไม่ใช่ในอุโมงค์ของบรรดากษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 1, 'และชาวเยรูซาเล็มได้ให้อาหัสยาห์โอรสองค์สุดท้องของพระองค์เป็นกษัตริย์แทนพระองค์ เพราะคนหมู่นั้นมาถึงค่ายกับคนอาระเบียได้ฆ่าโอรสผู้พี่เสียทั้งหมด ดังนั้นอาหัสยาห์โอรสของเยโฮรัมกษัตริย์ของยูดาห์จึงครอบครอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 2, 'เมื่ออาหัสยาห์เริ่มครอบครองนั้น พระองค์มีพระชนมายุสี่สิบสองพรรษา และพระองค์ทรงครอบครองในเยรูซาเล็มหนึ่งปี พระราชมารดาของพระองค์ทรงพระนามว่า อาธาลิยาห์ธิดาของอมรี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 3, 'พระองค์ทรงดําเนินในทางทั้งหลายของราชวงศ์ของอาหับด้วย เพราะว่าพระราชมารดาของพระองค์เป็นที่ปรึกษาในการกระทําความชั่วร้ายของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 4, 'ดังนั้นพระองค์จึงทรงกระทําชั่วในสายพระเนตรของพระเยโฮวาห์อย่างราชวงศ์ของอาหับได้กระทํา เพราะว่าหลังจากราชบิดาของพระองค์สิ้นพระชนม์แล้ว เขาทั้งหลายเป็นที่ปรึกษาของพระองค์ นําไปสู่ความพินาศของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 5, 'พระองค์ทรงดําเนินตามคําปรึกษาของเขาทั้งหลายด้วย และเสด็จไปกับเยโฮรัมโอรสของอาหับกษัตริย์แห่งอิสราเอล เพื่อทําสงครามกับฮาซาเอลกษัตริย์ของซีเรียที่เมืองราโมทกิเลอาด และคนซีเรียได้กระทําให้โยรัมบาดเจ็บ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 6, 'และพระองค์ทรงกลับมาที่ยิสเรเอลเพื่อรักษาบาดแผลซึ่งพระองค์ได้รับที่เมืองรามาห์ เมื่อพระองค์ทรงต่อสู้กับฮาซาเอลกษัตริย์ของซีเรีย และอาหัสยาห์โอรสของเยโฮรัมกษัตริย์ของยูดาห์เสด็จลงไปเฝ้าเยโฮรัม โอรสของอาหับในเมืองยิสเรเอล เพราะว่าพระองค์ประชวร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 7, 'แต่พระเจ้าทรงกําหนดไว้เสียแล้วว่า ความล่มจมของอาหัสยาห์จะมาโดยที่พระองค์เสด็จลงไปเยี่ยมโยรัม เพราะเมื่อพระองค์เสด็จไปที่นั่น พระองค์เสด็จออกไปกับเยโฮรัมเพื่อจะปะทะกับเยฮูบุตรชายนิมซี ผู้ซึ่งพระเยโฮวาห์ได้ทรงเจิมตั้งให้ตัดราชวงศ์ของอาหับออกเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 8, 'และอยู่มาเมื่อเยฮูกําลังสําเร็จโทษราชวงศ์ของอาหับ ท่านได้พบเจ้านายของยูดาห์ และบรรดาโอรสพระเชษฐาของอาหัสยาห์ ผู้มาปรนนิบัติอาหัสยาห์ และท่านก็ได้ประหารเขาทั้งหลายเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 9, 'ท่านได้ค้นหาอาหัสยาห์ และพระองค์ก็ถูกจับ (เมื่อซ่อนพระองค์อยู่ในสะมาเรีย) และเขาพาพระองค์มาหาเยฮู และประหารชีวิตพระองค์เสีย เขาทั้งหลายก็ฝังพระศพไว้ เพราะเขาทั้งหลายกล่าวว่า “พระองค์ทรงเป็นโอรสของเยโฮชาฟัท ผู้แสวงหาพระเยโฮวาห์ด้วยสิ้นสุดพระทัยของพระองค์” และราชวงศ์ของอาหัสยาห์ไม่มีผู้ใดสามารถปกครองราชอาณาจักรได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 10, 'เมื่ออาธาลิยาห์พระราชมารดาของอาหัสยาห์เห็นว่าโอรสของพระนางสิ้นพระชนม์แล้ว พระนางก็ลุกขึ้นทําลายเชื้อพระวงศ์แห่งราชวงศ์ของยูดาห์เสียสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 11, 'แต่พระนางเยโฮชาเบอาทธิดาของกษัตริย์ได้นําโยอาชโอรสของอาหัสยาห์ลักพาไปเสียจากท่ามกลางบรรดาโอรสของกษัตริย์ ผู้ซึ่งจะต้องถูกประหาร และพระนางก็เก็บเธอและพี่เลี้ยงของเธอไว้ในห้องบรรทม ดังนั้นแหละเยโฮชาเบอาทธิดาของกษัตริย์เยโฮรัม และภรรยาของเยโฮยาดาปุโรหิต (เพราะว่าพระนางเป็นพระขนิษฐาของอาหัสยาห์) ได้ซ่อนเธอให้พ้นพระนางอาธาลิยาห์ เพื่อมิให้พระนางประหารเธอได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 12, 'และเธอได้อยู่กับเขาในพระนิเวศของพระเจ้าซ่อนตัวอยู่หกปี ฝ่ายพระนางอาธาลิยาห์ก็ได้ครอบครองแผ่นดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 1, 'แต่ในปีที่เจ็ดเยโฮยาดาได้กล้าแข็งขึ้น และให้พวกนายร้อยกระทําพันธสัญญากับท่าน มีอาซาริยาห์บุตรชายเยโรฮัม อิชมาเอลบุตรชายเยโฮฮานัน อาซาริยาห์บุตรชายโอเบด มาอาเสอาห์บุตรชายอาดายาห์ และเอลีชาฟัทบุตรชายศิครี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 2, 'และเขาทั้งหลายเที่ยวไปทั่วยูดาห์และรวบรวมคนเลวีมาจากทุกหัวเมืองของยูดาห์ ทั้งบรรดาหัวประมุขของบรรพบุรุษของอิสราเอล และเขาทั้งหลายมายังเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 3, 'และบรรดาชุมนุมชนทั้งสิ้นก็ทําพันธสัญญากับกษัตริย์ในพระนิเวศของพระเจ้า และเยโฮยาดากล่าวแก่เขาทั้งหลายว่า “ดูเถิด โอรสของกษัตริย์จะครอบครองตามที่พระเยโฮวาห์ตรัสเกี่ยวกับบรรดาโอรสของดาวิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 4, 'ท่านทั้งหลายจงกระทําอย่างนี้ คือท่านผู้เป็นปุโรหิตและคนเลวี ผู้ออกเวรในวันสะบาโตหนึ่งในสาม ให้เป็นคนเฝ้าประตู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 5, 'และหนึ่งในสามให้อยู่ที่พระราชสํานัก และหนึ่งในสามให้อยู่ที่ประตูเชิงราก และให้ประชาชนทั้งปวงอยู่ในลานพระนิเวศของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 6, 'แต่อย่าให้สักคนหนึ่งเข้าไปในพระนิเวศของพระเยโฮวาห์ นอกจากปุโรหิตและคนเลวีที่ปรนนิบัติอยู่ เขาทั้งหลายเข้าไปได้ เพราะเขาทั้งหลายบริสุทธิ์ แต่ประชาชนทั้งปวงจะต้องรักษาการบังคับบัญชาของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 7, 'ให้คนเลวีล้อมกษัตริย์ไว้ แต่ละคนให้ถืออาวุธ และผู้ใดเข้าไปในพระนิเวศนั้นจะต้องถูกประหาร จงอยู่กับกษัตริย์เมื่อพระองค์เสด็จเข้ามา และเมื่อพระองค์เสด็จออกไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 8, 'คนเลวีและคนยูดาห์ทั้งปวงได้กระทําทุกสิ่งที่เยโฮยาดาปุโรหิตได้บัญชาไว้ เขาทั้งหลายต่างก็นําคนของเขามา คือทั้งคนที่ออกเวรในวันสะบาโต และบรรดาคนเหล่านั้นที่จะเข้าเวรในวันสะบาโต เพราะเยโฮยาดาปุโรหิตมิได้ปล่อยกองเวร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 9, 'และเยโฮยาดาปุโรหิตได้มอบหอกกับดั้งและโล่ซึ่งเป็นของกษัตริย์ดาวิดนั้น ซึ่งอยู่ในพระนิเวศของพระเจ้าให้ผู้บังคับบัญชากองร้อย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 10, 'และท่านได้ตั้งประชาชนทั้งสิ้นให้ล้อมกษัตริย์ไว้ ทุกคนถืออาวุธตั้งแต่ด้านขวาของพระวิหารถึงด้านซ้ายของพระวิหาร รอบแท่นบูชาและพระวิหาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 11, 'แล้วเขานําโอรสของกษัตริย์ออกมา และสวมมงกุฎให้ท่าน มอบพระโอวาทให้แก่ท่าน และเขาทั้งหลายตั้งท่านไว้เป็นกษัตริย์ เยโฮยาดากับบุตรชายของท่านก็เจิมพระองค์ และเขาทั้งหลายร้องว่า “ขอกษัตริย์ทรงพระเจริญ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 12, 'เมื่ออาธาลิยาห์ได้ยินเสียงประชาชนวิ่งและสรรเสริญกษัตริย์ พระนางก็เสด็จเข้าไปหาประชาชนในพระนิเวศของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 13, 'และเมื่อพระนางทอดพระเนตร ดูเถิด มีกษัตริย์ประทับยืนอยู่ที่เสาของพระองค์ตรงที่ทางเข้า บรรดาผู้บังคับกองและพลแตรก็อยู่ข้างกษัตริย์ และประชาชนทั้งปวงแห่งแผ่นดินก็เปรมปรีดิ์และเป่าแตร บรรดานักร้องพร้อมกับเครื่องดนตรีของเขาก็นําการสรรเสริญ พระนางอาธาลิยาห์ก็ฉีกฉลองพระองค์ของพระนาง ทรงร้องว่า “กบฏ กบฏ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 14, 'แล้วเยโฮยาดาปุโรหิตจึงนําบรรดานายร้อยผู้บัญชาการกองทัพออกมา สั่งเขาว่า “จงคุมพระนางออกมาระหว่างแถวทหาร ผู้ใดที่ตามพระนางไปก็ให้ประหารชีวิตเสียด้วยดาบ” เพราะปุโรหิตกล่าวว่า “อย่าประหารพระนางในพระนิเวศของพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 15, 'เขาจึงจับพระนาง แล้วพระนางก็เสด็จไปที่ทางเข้าประตูม้า ณ พระราชวังและเขาทั้งหลายก็ประหารพระนางเสียที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 16, 'เยโฮยาดาได้กระทําพันธสัญญาระหว่างท่านเองกับประชาชนทั้งปวงและกษัตริย์ว่า เขาทั้งหลายจะเป็นประชาชนของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 17, 'แล้วประชาชนทั้งปวงก็ไปที่นิเวศของพระบาอัล และพังลงเสีย และเขาทุบแท่นบูชาและรูปเคารพของพระบาอัลนั้นให้เป็นชิ้นๆ และเขาประหารมัททานปุโรหิตของพระบาอัลเสียที่หน้าแท่นบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 18, 'เยโฮยาดาวางยามไว้ดูแลพระนิเวศของพระเยโฮวาห์ภายใต้การควบคุมของปุโรหิตแห่งคนเลวี ผู้ซึ่งดาวิดทรงจัดตั้งให้ดูแลพระนิเวศของพระเยโฮวาห์ ให้ถวายเครื่องเผาบูชาแด่พระเยโฮวาห์ ตามที่บันทึกไว้ในพระราชบัญญัติของโมเสส ด้วยความเปรมปรีดิ์และการร้องเพลง ตามพระราชดํารัสสั่งของดาวิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 19, 'ท่านได้ตั้งผู้เฝ้าประตูไว้ที่ประตูรั้วพระนิเวศของพระเยโฮวาห์ เพื่อมิให้ผู้มีมลทินด้วยประการหนึ่งประการใดเข้าไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 20, 'ท่านได้นําผู้บังคับกองร้อย ขุนนาง ผู้ปกครองประชาชน และบรรดาประชาชนแห่งแผ่นดิน และท่านได้เชิญกษัตริย์ลงมาจากพระนิเวศของพระเยโฮวาห์ไปทางประตูบนไปสู่พระราชสํานัก และเขาก็เชิญกษัตริย์ประทับบนพระราชบัลลังก์แห่งราชอาณาจักร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 21, 'บรรดาประชาชนแห่งแผ่นดินก็เปรมปรีดิ์ และกรุงก็สงบเงียบหลังจากที่เขาได้ประหารพระนางอาธาลิยาห์เสียด้วยดาบแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 1, 'เมื่อโยอาชได้เริ่มครอบครองมีพระชนมายุเจ็ดพรรษา และพระองค์ทรงครอบครองในกรุงเยรูซาเล็มสี่สิบปี พระราชมารดาของพระองค์ทรงพระนามว่า ศิบียาห์แห่งเมืองเบเออร์เชบา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 2, 'และโยอาชทรงกระทําสิ่งที่ชอบในสายพระเนตรของพระเยโฮวาห์ตลอดชั่วอายุของเยโฮยาดาปุโรหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 3, 'เยโฮยาดาหามเหสีให้พระองค์สององค์ และพระองค์ก็ให้กําเนิดโอรสและธิดาหลายองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 4, 'ต่อมาภายหลังโยอาชทรงตั้งพระทัยที่จะซ่อมแซมพระนิเวศของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 5, 'พระองค์ทรงประชุมปุโรหิตและคนเลวี และตรัสกับเขาทั้งหลายว่า “จงออกไปตามหัวเมืองยูดาห์ และเก็บเงินจากอิสราเอลทั้งปวง เพื่อซ่อมแซมพระนิเวศของพระเจ้าของเจ้าเป็นปีๆไป และจงรีบทํางานนั้น” แต่คนเลวีไม่เร่งรีบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 6, 'แล้วกษัตริย์จึงตรัสเรียกเยโฮยาดาผู้เป็นหัวหน้า และตรัสกับท่านว่า “ไฉนท่านไม่เรียกร้องให้คนเลวีนําเงินส่วยเข้ามาจากยูดาห์และเยรูซาเล็ม ซึ่งโมเสสผู้รับใช้ของพระเยโฮวาห์กําหนดไว้ ให้ชุมนุมชนอิสราเอลนํามาเพื่อพลับพลาพระโอวาท”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 7, 'เพราะบรรดาโอรสของพระนางอาธาลิยาห์หญิงชั่วร้ายคนนั้นได้ปล้นพระนิเวศของพระเจ้า และได้เอาสิ่งของที่มอบถวายทั้งสิ้นของพระนิเวศของพระเยโฮวาห์มอบให้แก่พระบาอัล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 8, 'กษัตริย์จึงทรงบัญชาและเขาได้ทําหีบลูกหนึ่งวางไว้นอกประตูพระนิเวศของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 9, 'และมีคําประกาศไปทั่วยูดาห์และเยรูซาเล็มให้นําส่วยซึ่งโมเสสผู้รับใช้ของพระเจ้ากําหนดแก่อิสราเอลในถิ่นทุรกันดาร เข้ามาถวายพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 10, 'บรรดาเจ้านายทั้งสิ้นและประชาชนทั้งปวงก็เปรมปรีดิ์ และนําส่วยของเขาทั้งหลายมาหย่อนลงในหีบจนครบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 11, 'และต่อมาเมื่อคนเลวีนําหีบเข้ามายังเจ้าพนักงานของกษัตริย์เมื่อไร และเมื่อเขาทั้งหลายเห็นว่ามีเงินมาก ราชเลขาและเจ้าหน้าที่ของมหาปุโรหิตจะเข้ามาเทหีบออกและนําหีบกลับไปยังที่เดิม เขาทั้งหลายทําอย่างนี้วันแล้ววันเล่า และเก็บเงินได้เป็นอันมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 12, 'กษัตริย์และเยโฮยาดาก็ให้แก่บรรดาผู้ดูแลกิจการของพระนิเวศของพระเยโฮวาห์ และเขาทั้งหลายจ้างช่างก่อและช่างไม้ให้ซ่อมแซมพระนิเวศของพระเยโฮวาห์ ทั้งคนงานช่างเหล็กและช่างทองเหลือง ให้ซ่อมแซมพระนิเวศของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 13, 'บรรดาคนที่รับจ้างทํางานจึงได้ทํางาน และงานซ่อมแซมก็ดําเนินก้าวหน้าในมือของเขา และเขาได้ซ่อมแซมพระนิเวศของพระเจ้าตามขนาดเดิมและเสริมให้แข็งแรงขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 14, 'และเมื่อเขาได้กระทําสําเร็จแล้วเขาก็นําเงินที่เหลืออยู่มาหน้าพระพักตร์กษัตริย์และเยโฮยาดา และเขาเอาเงินนั้นทําเครื่องใช้สําหรับพระนิเวศแห่งพระเยโฮวาห์ คือเครื่องใช้สําหรับการปรนนิบัติ ทั้งสําหรับการถวายเครื่องบูชาและช้อน และภาชนะทองคําและเงิน และเขาทั้งหลายได้ถวายเครื่องเผาบูชาในพระนิเวศของพระเยโฮวาห์เสมอตลอดชั่วอายุของเยโฮยาดา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 15, 'แต่เยโฮยาดาก็ชราลงและหง่อมแล้วก็สิ้นชีวิต เมื่อสิ้นชีวิตนั้นท่านมีอายุหนึ่งร้อยสามสิบปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 16, 'เขาก็ฝังศพท่านไว้ในนครของดาวิดท่ามกลางบรรดากษัตริย์ เพราะท่านได้กระทําการดีในอิสราเอล และต่อพระเจ้าและพระนิเวศของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 17, 'หลังจากที่เยโฮยาดาสิ้นชีวิตแล้วบรรดาเจ้านายแห่งยูดาห์ได้เข้ามาถวายบังคมต่อกษัตริย์ แล้วกษัตริย์ทรงฟังคําทูลของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 18, 'และเขาได้ทอดทิ้งพระนิเวศของพระเยโฮวาห์พระเจ้าแห่งบรรพบุรุษของเขา และปรนนิบัติบรรดาเสารูปเคารพและรูปเคารพ และพระพิโรธได้ลงมาเหนือยูดาห์และเยรูซาเล็มเพราะการละเมิดของเขานี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 19, 'แต่พระองค์ยังทรงใช้ผู้พยากรณ์มาท่ามกลางเขานําเขาให้กลับมายังพระเยโฮวาห์ คนเหล่านี้เป็นพยานปรักปรําเขา แต่เขาไม่ยอมเงี่ยหูฟัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 20, 'แล้วพระวิญญาณของพระเจ้าได้สวมทับเศคาริยาห์บุตรชายเยโฮยาดาปุโรหิต และท่านได้ยืนเหนือประชาชน และกล่าวแก่เขาทั้งหลายว่า “พระเจ้าตรัสดังนี้ว่า ‘ทําไมท่านทั้งหลายจึงละเมิดพระบัญญัติของพระเยโฮวาห์อันเป็นเหตุให้ท่านเจริญขึ้นไม่ได้’ เพราะท่านทั้งหลายได้ทอดทิ้งพระเยโฮวาห์พระองค์จึงทอดทิ้งท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 21, 'แต่เขาทั้งหลายคิดร้ายต่อท่าน และโดยบัญชาของกษัตริย์เขาทั้งหลายจึงขว้างท่านด้วยหินในลานพระนิเวศของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 22, 'ดังนี้แหละกษัตริย์โยอาชจึงมิได้ทรงระลึกถึงความกรุณาซึ่งเยโฮยาดาบิดาของเศคาริยาห์ได้สําแดงต่อพระองค์ แต่ได้ทรงประหารบุตรชายของท่านเสีย และเมื่อเขากําลังจะตาย เขาพูดว่า “ขอพระเยโฮวาห์ทรงทอดพระเนตรและแก้แค้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 23, 'ต่อมาพอปลายปีกองทัพของคนซีเรียก็มาต่อสู้กับโยอาช เขามายังยูดาห์และเยรูซาเล็ม และได้ทําลายบรรดาเจ้านายของประชาชนจากหมู่ประชาชน และส่งของที่ริบได้ทั้งสิ้นไปยังกษัตริย์แห่งดามัสกัส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 24, 'แม้ว่ากองทัพคนซีเรียมาแต่น้อยคน พระเยโฮวาห์ทรงมอบกองทัพใหญ่ไว้ในมือของเขา เพราะเขาทั้งหลายได้ทอดทิ้งพระเยโฮวาห์พระเจ้าแห่งบรรพบุรุษของเขา ดังนี้แหละคนซีเรียได้ทําโทษโยอาช');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 25, 'เมื่อเขาทั้งหลายจากพระองค์ไป (เขาละพระองค์ไว้บาดเจ็บอย่างสาหัส) ข้าราชการของพระองค์ก็คิดร้ายต่อพระองค์ เพราะโลหิตของบุตรชายเยโฮยาดาปุโรหิต และได้ประหารพระองค์เสียที่บนแท่นบรรทม พระองค์ก็สิ้นพระชนม์ และเขาทั้งหลายฝังพระศพไว้ในนครดาวิด แต่เขาทั้งหลายมิได้ฝังพระศพไว้ในอุโมงค์ของบรรดากษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 26, 'คนเหล่านั้นที่คิดร้ายต่อพระองค์ คือศาบาดบุตรชายนางชิเมอัทคนอัมโมน และเยโฮซาบาดบุตรชายนางชิมริทคนโมอับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 27, 'เรื่องราวแห่งโอรสของพระองค์ และภาระหนักมากมายที่ตกอยู่แก่พระองค์ และการซ่อมแซมพระนิเวศของพระเจ้า ดูเถิด มีบันทึกไว้ในหนังสือเรื่องราวของกษัตริย์ และอามาซิยาห์โอรสของพระองค์ครอบครองแทนพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 1, 'เมื่ออามาซิยาห์เริ่มครอบครองนั้นมีพระชนมายุยี่สิบห้าพรรษา และพระองค์ทรงครอบครองในเยรูซาเล็มยี่สิบเก้าปี พระราชมารดาของพระองค์ทรงพระนามว่า เยโฮอัดดาน ชาวเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 2, 'และพระองค์ทรงกระทําสิ่งที่ถูกต้องในสายพระเนตรของพระเยโฮวาห์ แต่มิใช่ด้วยพระทัยที่เพียบพร้อม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 3, 'และอยู่มาพอราชอาณาจักรอยู่ในพระหัตถ์ของพระองค์อย่างมั่นคงแล้ว พระองค์ทรงประหารชีวิตข้าราชการของพระองค์ ผู้ที่ฆ่าพระราชบิดาของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 4, 'แต่พระองค์มิได้ทรงประหารชีวิตลูกหลานของเขา แต่ได้ทรงกระทําตามที่มีบันทึกไว้ในหนังสือพระราชบัญญัติของโมเสส ที่พระเยโฮวาห์ทรงบัญชาไว้นั้นว่า “อย่าให้บิดาต้องรับโทษถึงตายแทนบุตรของตน หรือให้บุตรต้องรับโทษถึงตายแทนบิดาของตน ให้ทุกคนรับโทษถึงตายเนื่องด้วยบาปของคนนั้นเอง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 5, 'แล้วอามาซิยาห์ได้ประชุมพวกยูดาห์ และให้เขาอยู่ภายใต้ผู้บังคับกองพันและผู้บังคับกองร้อยตามเรือนบรรพบุรุษของเขา คือยูดาห์และเบนยามินทั้งสิ้น พระองค์ได้ทรงนับคนที่มีอายุยี่สิบปีขึ้นไปและทรงเห็นว่ามีชายฉกรรจ์สามแสนคน สามารถเข้าทําสงคราม สามารถถือหอกและโล่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 6, 'นอกจากนั้นพระองค์ทรงจ้างทแกล้วทหารจากอิสราเอลหนึ่งแสนคนเป็นเงินหนึ่งร้อยตะลันต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 7, 'แต่คนของพระเจ้าคนหนึ่งมาเฝ้าพระองค์ทูลว่า “โอ ข้าแต่กษัตริย์ ขออย่าให้กองทัพอิสราเอลไปกับพระองค์ เพราะพระเยโฮวาห์มิได้ทรงสถิตอยู่กับอิสราเอล คือกับคนเอฟราอิมเหล่านี้ทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 8, 'แต่ถ้าพระองค์คาดหมายว่าโดยวิธีนี้ พระองค์จะเข้มแข็งพอที่จะเข้าสงคราม พระเจ้าจะทรงเหวี่ยงพระองค์ลงต่อหน้าศัตรู เพราะว่าพระเจ้าทรงฤทธิ์ที่จะช่วยไว้หรือทิ้งไปได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 9, 'และอามาซิยาห์ตรัสกับคนของพระเจ้าว่า “แต่เราจะกระทําประการใดเรื่องเงินหนึ่งร้อยตะลันต์ซึ่งเราได้ให้แก่กองทัพอิสราเอลไปแล้วนั้น” แล้วคนของพระเจ้าทูลตอบว่า “พระเยโฮวาห์ทรงสามารถที่จะประทานแก่พระองค์ยิ่งกว่านี้อีกมาก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 10, 'และอามาซิยาห์ก็ทรงปลดปล่อยกองทัพซึ่งมายังพระองค์จากเอฟราอิมให้กลับไปบ้านอีก เขาทั้งหลายจึงโกรธยูดาห์ยิ่งนัก และได้กลับบ้านด้วยความโกรธอย่างรุนแรง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 11, 'แต่อามาซิยาห์ทรงกล้าแข็งขึ้น และทรงนําพลของพระองค์ออกไปยังหุบเขาเกลือและโจมตีคนเสอีร์หนึ่งหมื่นคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 12, 'คนยูดาห์จับเป็นได้หนึ่งหมื่นคน และพาเขาไปที่ยอดหิน และทิ้งเขาทั้งหลายลงมาจากยอดหินนั้น เขาก็ตกมาแหลกเป็นชิ้นๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 13, 'แต่คนของกองทัพซึ่งอามาซิยาห์ทรงปลดให้กลับไป และไม่ให้เขาไปรบด้วยนั้น เขาตลบเข้าโจมตีหัวเมืองของยูดาห์ ตั้งแต่สะมาเรียถึงเบธโฮโรน และฆ่าประชาชนเสียสามพันคน และริบข้าวของไปเป็นอันมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 14, 'และอยู่มาเมื่ออามาซิยาห์เสด็จกลับจากการฆ่าฟันคนเอโดม พระองค์ทรงนํารูปเคารพของคนชาวเสอีร์มาตั้งไว้เป็นพระของพระองค์ และกราบนมัสการพระเหล่านั้น ทรงเผาเครื่องหอมถวาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 15, 'เพราะฉะนั้นพระเยโฮวาห์ทรงกริ้วต่ออามาซิยาห์ และทรงใช้ผู้พยากรณ์คนหนึ่งไปหา ทูลพระองค์ว่า “ทําไมเจ้าจึงแสวงหาพระของชนชาติหนึ่ง ซึ่งไม่สามารถช่วยชนชาติของตนเองให้พ้นจากมือของเจ้าได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 16, 'อยู่มาขณะที่เขากําลังทูลอยู่ กษัตริย์ตรัสกับเขาว่า “เราได้แต่งตั้งเจ้าให้เป็นที่ปรึกษาของกษัตริย์หรือ หยุด ทําไมเจ้าจะต้องตายเล่า” ผู้พยากรณ์นั้นจึงหยุด แต่ทูลว่า “ข้าพระองค์ทราบว่าพระเจ้าทรงตั้งพระทัยจะทําลายพระองค์ เพราะพระองค์ทรงกระทําเช่นนี้ และมิได้ทรงฟังคําปรึกษาของข้าพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 17, 'แล้วอามาซิยาห์กษัตริย์แห่งยูดาห์ได้ทรงรับคําปรึกษา และทรงใช้ให้ไปเฝ้าโยอาชโอรสของเยโฮอาหาส โอรสของเยฮู กษัตริย์ของอิสราเอลทูลว่า “มาเถิด ให้เราทั้งสองมาเผชิญหน้ากัน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 18, 'และโยอาชกษัตริย์แห่งอิสราเอลทรงใช้ไปยังอามาซิยาห์กษัตริย์แห่งยูดาห์ว่า “ต้นผักหนามบนเลบานอนส่งข่าวให้หาต้นสนสีดาร์บนเลบานอนว่า ‘จงยกบุตรสาวของเจ้าให้เป็นภรรยาบุตรชายของเรา’ และสัตว์ป่าทุ่งตัวหนึ่งแห่งเลบานอนผ่านมาและย่ําต้นผักหนามลงเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 19, 'ท่านว่า ‘ดูซิ ข้าพเจ้าได้โจมตีเอโดม’ และจิตใจของท่านก็ผยองขึ้นในความโอ้อวด แต่จงอยู่กับบ้านเถิด เพราะไฉนท่านจึงเร้าใจตนเองให้ต่อสู้และรับอันตราย อันจะให้ท่านล้มลง ทั้งท่านและยูดาห์กับท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 20, 'แต่อามาซิยาห์หาทรงฟังไม่เพราะเป็นมาจากพระเจ้า เพื่อว่าพระองค์จะทรงมอบเขาทั้งหลายไว้ในมือของศัตรูของเขา เพราะเขาทั้งหลายได้เสาะหาพระแห่งเอโดม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 21, 'โยอาชกษัตริย์แห่งอิสราเอลจึงเสด็จขึ้นไป พระองค์และอามาซิยาห์กษัตริย์แห่งยูดาห์ได้เผชิญหน้ากันที่เบธเชเมช ซึ่งเป็นของยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 22, 'และยูดาห์ก็พ่ายแพ้อิสราเอล และทุกคนก็หนีกลับไปเต็นท์ของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 23, 'โยอาชกษัตริย์แห่งอิสราเอลทรงจับอามาซิยาห์กษัตริย์แห่งยูดาห์โอรสของโยอาช โอรสของเยโฮอาหาสที่เบธเชเมช และนําพระองค์มายังเยรูซาเล็ม และทรงพังกําแพงเยรูซาเล็มลงสี่ร้อยศอก ตั้งแต่ประตูเอฟราอิมถึงประตูมุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 24, 'และพระองค์ทรงริบทองคําและเงินทั้งหมด และเครื่องใช้ทั้งสิ้นซึ่งพบในพระนิเวศของพระเจ้า ในความอารักขาของโอเบดเอโดม ทั้งคลังทรัพย์ของสํานักพระราชวัง พร้อมกับคนประกันด้วย และพระองค์เสด็จกลับไปยังสะมาเรีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 25, 'อามาซิยาห์ โอรสของโยอาชกษัตริย์แห่งยูดาห์ทรงพระชนม์อยู่สิบห้าปี หลังจากสวรรคตของโยอาช โอรสของเยโฮอาหาส กษัตริย์แห่งอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 26, 'ส่วนพระราชกิจนอกนั้นของอามาซิยาห์ ตั้งแต่ต้นจนปลาย ดูเถิด มิได้บันทึกไว้ในหนังสือของกษัตริย์แห่งยูดาห์และอิสราเอลหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 27, 'นับแต่เวลาเมื่ออามาซิยาห์ทรงหันไปจากการติดตามพระเยโฮวาห์ เขาทั้งหลายก็คิดกบฏต่อพระองค์ในเยรูซาเล็ม และพระองค์ทรงหนีไปที่ลาคีช แต่เขาใช้ไปตามพระองค์ที่ลาคีช และประหารพระองค์เสียที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 28, 'และเขาทั้งหลายนําพระศพใส่หลังม้ากลับมา และฝังไว้กับบรรพบุรุษของพระองค์ในเมืองแห่งยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 1, 'ประชาชนทั้งสิ้นแห่งยูดาห์จึงตั้งอุสซียาห์ ผู้ซึ่งมีพระชนมายุสิบหกพรรษา ให้เป็นกษัตริย์แทนอามาซิยาห์ราชบิดาของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 2, 'พระองค์ทรงสร้างเมืองเอโลทและให้กลับขึ้นแก่ยูดาห์ หลังจากที่กษัตริย์ทรงล่วงหลับไปอยู่กับบรรพบุรุษของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 3, 'เมื่ออุสซียาห์ทรงเริ่มครอบครองนั้นมีพระชนมายุสิบหกพรรษา และพระองค์ทรงครอบครองในกรุงเยรูซาเล็มห้าสิบสองปี พระราชมารดาของพระองค์ทรงพระนามว่า เยโคลียาห์ ชาวเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 4, 'และพระองค์ทรงกระทําสิ่งที่ถูกต้องในสายพระเนตรของพระเยโฮวาห์ ตามที่อามาซิยาห์ราชบิดาของพระองค์ได้ทรงกระทําทุกประการ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 5, 'และพระองค์ทรงแสวงหาพระเจ้าในสมัยของเศคาริยาห์ ผู้เข้าใจในนิมิตต่างๆจากพระเจ้า และตราบใดที่พระองค์แสวงหาพระเยโฮวาห์ พระเจ้าทรงกระทําให้พระองค์เจริญ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 6, 'พระองค์เสด็จออกไปทําสงครามต่อสู้กับคนฟีลิสเตีย และพังกําแพงเมืองกัท และกําแพงเมืองยับเนห์ และกําแพงเมืองอัชโดด และพระองค์ทรงสร้างหัวเมืองในเขตแดนอัชโดด และที่อื่นๆอีกท่ามกลางคนฟีลิสเตีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 7, 'พระเจ้าทรงช่วยพระองค์ในการต่อสู้คนฟีลิสเตีย และต่อสู้คนอาระเบียซึ่งอาศัยอยู่ในกูร์บาอัล และต่อสู้กับคนเมอูนิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 8, 'ชนอัมโมนได้ถวายบรรณาการแก่อุสซียาห์ และพระนามของพระองค์ก็แผ่แพร่ออกไปถึงเขตแดนอียิปต์ เพราะพระองค์ทรงเข้มแข็งขึ้นยิ่งนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 9, 'ยิ่งกว่านั้นอีกอุสซียาห์ทรงสร้างป้อมในเยรูซาเล็มที่ประตูมุม ที่ประตูหุบเขาและที่หัวเลี้ยว และป้องกันไว้แข็งแรง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 10, 'และพระองค์ทรงสร้างป้อมในถิ่นทุรกันดาร ทรงขุดบ่อน้ําหลายแห่ง เพราะพระองค์ทรงมีฝูงสัตว์ใหญ่โต ทั้งในหุบเขาและในที่ราบ และทรงมีชาวนาและคนแต่งต้นองุ่นในเนินเขา และในคารเมล เพราะพระองค์ทรงรักเกษตรกรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 11, 'ยิ่งกว่านั้นอีกอุสซียาห์ทรงมีกองทหาร ซึ่งออกไปทําศึกเป็นกองๆตามจํานวนที่เยอีเอลราชเลขาได้รวบรวมไว้ด้วยกันกับมาอาเสอาห์เจ้าหน้าที่ภายใต้การควบคุมของฮานันยาห์ ผู้บังคับกองพลคนหนึ่งของกษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 12, 'จํานวนประมุขของบรรพบุรุษทั้งหมดแห่งพวกทแกล้วทหารคือ สองพันหกร้อยคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 13, 'ใต้บังคับบัญชาของคนเหล่านี้ มีกองทัพพลสามแสนเจ็ดพันห้าร้อยคน ผู้ทําสงครามได้ด้วยกําลังมาก เพื่อช่วยกษัตริย์ให้ต่อสู้กับศัตรู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 14, 'และอุสซียาห์ทรงเตรียมโล่ หอก หมวกเหล็ก เสื้อเกราะ ธนู และก้อนหินสําหรับสลิงไว้สําหรับกองทัพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 15, 'ในเยรูซาเล็มพระองค์ทรงกระทําเครื่องกลไกโดยคนช่างประดิษฐ์ทําขึ้น ไว้บนป้อมและตามมุม เพื่อยิงลูกธนูและโยนก้อนหินใหญ่ๆ และพระนามของพระองค์ก็ลือไปไกล เพราะพระองค์ทรงรับความช่วยเหลืออย่างมหัศจรรย์จนพระองค์เข้มแข็ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 16, 'แต่เมื่อพระองค์ทรงแข็งแรงแล้ว พระองค์ก็มีพระทัยผยองขึ้นจึงทรงกระทําความเสียหาย เพราะพระองค์ละเมิดต่อพระเยโฮวาห์พระเจ้าของพระองค์ และเข้าไปในพระวิหารของพระเยโฮวาห์เพื่อเผาเครื่องหอมบนแท่นเครื่องหอม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 17, 'แต่อาซาริยาห์ปุโรหิตได้เข้าไปติดตามพระองค์พร้อมกับปุโรหิตของพระเยโฮวาห์แปดสิบคนผู้ซึ่งเก่งกล้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 18, 'และเขาทั้งหลายได้ขัดขวางกษัตริย์อุสซียาห์และทูลพระองค์ว่า “ข้าแต่อุสซียาห์ มิใช่หน้าที่ของพระองค์ที่จะเผาเครื่องหอมถวายแด่พระเยโฮวาห์ แต่เป็นหน้าที่ของปุโรหิตลูกหลานของอาโรน ผู้ซึ่งชําระไว้ให้บริสุทธิ์เพื่อเผาเครื่องหอม ขอเชิญพระองค์เสด็จออกไปจากสถานบริสุทธิ์นี้ เพราะพระองค์ได้ทรงล่วงเกิน และพระองค์จะไม่ได้รับเกียรติอันใดจากพระเยโฮวาห์พระเจ้าเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 19, 'แล้วอุสซียาห์ทรงกริ้ว พระองค์มีกระถางไฟอยู่ในพระหัตถ์จะทรงเผาเครื่องหอม และเมื่อพระองค์ทรงกริ้วต่อพวกปุโรหิต โรคเรื้อนก็เกิดขึ้นมาที่พระนลาฏต่อหน้าปุโรหิตในพระนิเวศของพระเยโฮวาห์ข้างแท่นเผาเครื่องหอม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 20, 'และอาซาริยาห์ปุโรหิตใหญ่ และบรรดาปุโรหิตทั้งปวงมองดูพระองค์ และดูเถิด พระองค์ทรงเป็นโรคเรื้อนที่พระนลาฏ และเขาทั้งหลายก็ผลักพระองค์ออกไปจากที่นั่น และพระองค์เองก็ทรงรีบเสด็จออกไป เพราะว่าพระเยโฮวาห์ทรงลงโทษพระองค์แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 21, 'และกษัตริย์อุสซียาห์ก็ทรงเป็นโรคเรื้อนจนวันสิ้นพระชนม์ และเพราะเป็นโรคเรื้อนก็ทรงประทับในวังต่างหาก เพราะพระองค์ทรงถูกตัดขาดจากพระนิเวศของพระเยโฮวาห์ และโยธามโอรสของพระองค์เป็นผู้ดูแลราชสํานักปกครองประชาชนแห่งแผ่นดินนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 22, 'ส่วนพระราชกิจนอกนั้นของอุสซียาห์ ตั้งแต่ต้นจนปลาย อิสยาห์ผู้พยากรณ์ บุตรชายอามอส ได้บันทึกไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 23, 'และอุสซียาห์ก็ทรงล่วงหลับไปอยู่กับบรรพบุรุษของพระองค์ และเขาก็ฝังพระศพไว้กับบรรพบุรุษของพระองค์ในนาที่ฝังศพอันเป็นของกษัตริย์ เพราะเขาทั้งหลายว่า “พระองค์ทรงเป็นโรคเรื้อน” และโยธามโอรสของพระองค์ก็ครอบครองแทนพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 1, 'เมื่อโยธามทรงเริ่มครอบครองนั้นมีพระชนมายุยี่สิบห้าพรรษา และพระองค์ทรงครอบครองในเยรูซาเล็มสิบหกปี พระราชมารดาของพระองค์มีพระนามว่า เยรูชาห์ บุตรสาวของศาโดก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 2, 'และพระองค์ทรงกระทําสิ่งที่ถูกต้องในสายพระเนตรของพระเยโฮวาห์ ตามซึ่งอุสซียาห์ราชบิดาของพระองค์ได้ทรงกระทําทุกประการ เว้นแต่พระองค์มิได้เข้าไปในพระวิหารของพระเยโฮวาห์ แต่ประชาชนยังประพฤติอย่างเลวทราม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 3, 'พระองค์ทรงสร้างประตูบนของพระนิเวศแห่งพระเยโฮวาห์ และทรงกระทําการก่อสร้างมากที่กําแพงตําบลโอเฟล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 4, 'ยิ่งกว่านั้นอีกพระองค์ทรงสร้างหัวเมืองในถิ่นเทือกเขาแห่งยูดาห์ และสร้างป้อมกับหอคอยตามป่าไม้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 5, 'และพระองค์ทรงสู้รบกับกษัตริย์คนอัมโมนและทรงชนะ และในปีนั้นคนอัมโมนได้ถวายเงินแด่พระองค์หนึ่งร้อยตะลันต์ และข้าวสาลีหนึ่งหมื่นโคระกับข้าวบาร์เลย์หนึ่งหมื่น คนอัมโมนได้ถวายเท่ากันในปีที่สองและในปีที่สาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 6, 'โยธามจึงทรงมีกําลังมากขึ้น เพราะพระองค์ทรงตระเตรียมทางทั้งหลายของพระองค์ต่อพระพักตร์พระเยโฮวาห์พระเจ้าของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 7, 'ส่วนพระราชกิจนอกนั้นของโยธาม และการสงครามทั้งสิ้นของพระองค์ และพระราชวัตรของพระองค์ ดูเถิด มีบันทึกไว้ในหนังสือของกษัตริย์แห่งอิสราเอลและยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 8, 'เมื่อพระองค์ทรงเริ่มครอบครองมีพระชนมายุยี่สิบห้าพรรษา และพระองค์ทรงครอบครองในเยรูซาเล็มสิบหกปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 9, 'และโยธามล่วงหลับไปอยู่กับบรรพบุรุษของพระองค์ และเขาฝังพระศพไว้ในนครดาวิด และอาหัสโอรสของพระองค์ครอบครองแทนพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 1, 'เมื่ออาหัสทรงเริ่มครองราชย์มีพระชนมายุยี่สิบพรรษา และพระองค์ทรงครองราชย์ในเยรูซาเล็มสิบหกปี แต่พระองค์มิได้ทรงกระทําสิ่งที่ถูกต้องในสายพระเนตรของพระเยโฮวาห์ อย่างกับดาวิดบรรพบุรุษของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 2, 'แต่ทรงดําเนินตามทางของกษัตริย์แห่งอิสราเอล พระองค์ถึงกับทรงสร้างรูปเคารพหล่อสําหรับพระบาอัล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 3, 'ยิ่งกว่านั้นพระองค์ทรงเผาเครื่องหอมในหุบเขาบุตรชายของฮินโนม และทรงเผาโอรสทั้งหลายของพระองค์ในไฟ ตามการกระทําอันน่าสะอิดสะเอียนของประชาชาติ ซึ่งพระเยโฮวาห์ทรงขับไล่ออกไปให้พ้นหน้าประชาชนอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 4, 'พระองค์ทรงถวายสัตวบูชาและทรงเผาเครื่องหอมที่ปูชนียสถานสูง และบนเนินเขาและใต้ต้นไม้เขียวสดทุกต้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 5, 'เพราะฉะนั้นพระเยโฮวาห์พระเจ้าของพระองค์จึงทรงมอบพระองค์ไว้ในพระหัตถ์ของกษัตริย์แห่งซีเรียผู้ทรงชนะพระองค์ และจับประชาชนของพระองค์เป็นเชลยจํานวนมากนํามายังดามัสกัส และพระองค์ทรงถูกมอบไว้ในพระหัตถ์ของกษัตริย์แห่งอิสราเอล ผู้ชนะพระองค์ด้วยการฆ่าฟันอย่างใหญ่หลวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 6, 'เพราะว่าเปคาห์บุตรชายเรมาลิยาห์ได้ฆ่าเสียหนึ่งแสนสองหมื่นคนในยูดาห์ในวันเดียว ทั้งสิ้นเป็นทหารกล้าแข็ง เพราะเขาทั้งหลายได้ทอดทิ้งพระเยโฮวาห์พระเจ้าแห่งบรรพบุรุษของเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 7, 'และศิครีทแกล้วทหารของเอฟราอิมได้สังหารมาอาเสอาห์โอรสของกษัตริย์ และอัสรีคัมอธิบดีกรมวังและเอลคานาห์อุปราช');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 8, 'คนอิสราเอลได้จับญาติพี่น้องของตนเป็นเชลยสองแสนคน มีผู้หญิง บุตรชาย และบุตรสาว และได้ริบของเป็นอันมากมาจากเขานํามายังสะมาเรีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 9, 'แต่ผู้พยากรณ์คนหนึ่งของพระเยโฮวาห์อยู่ที่นั่นชื่อว่าโอเดด ท่านออกไปพบกองทัพซึ่งมายังสะมาเรีย และพูดกับเขาทั้งหลายว่า “ดูเถิด เพราะพระเยโฮวาห์พระเจ้าแห่งบรรพบุรุษของท่านทั้งหลายทรงกริ้วต่อยูดาห์ พระองค์ทรงมอบเขาทั้งหลายไว้ในมือของท่าน แต่ท่านทั้งหลายได้สังหารเขาเสียด้วยความเกรี้ยวกราดซึ่งขึ้นไปถึงฟ้าสวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 10, 'และบัดนี้ท่านทั้งหลายเจตนาจะข่มขี่ประชาชนแห่งยูดาห์และเยรูซาเล็มให้เป็นทาสชายและทาสหญิงของท่าน ตัวท่านเองไม่มีบาปต่อพระเยโฮวาห์พระเจ้าของท่านหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 11, 'บัดนี้ขอฟังข้าพเจ้า และขอส่งเชลยซึ่งท่านได้นํามาจากญาติพี่น้องของท่านกลับไป เพราะว่าพระพิโรธอันแรงกล้าของพระเยโฮวาห์อยู่เหนือท่านทั้งหลาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 12, 'บางคนในหัวหน้าคนเอฟราอิมคือ อาซาริยาห์บุตรชายโยฮานัน เบเรคิยาห์บุตรชายเมซิลเลโมท เยฮิสคียาห์บุตรชายชัลลูมและอามาสาบุตรชายหัดลัย ได้ยืนขึ้นขัดขวางบรรดาผู้ที่กลับมาจากสงคราม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 13, 'พูดกับเขาทั้งหลายว่า “เจ้าอย่านําเชลยเข้ามาที่นี่ เพราะเจ้ามุ่งหมายที่จะนําโทษบาปมาเหนือเราต่อพระเยโฮวาห์ เพิ่มเข้ากับบาปและการละเมิดในปัจจุบันของเรา เพราะว่าการละเมิดของเราก็ใหญ่โตอยู่ พระพิโรธอันแรงกล้าต่ออิสราเอลมีอยู่แล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 14, 'เพราะฉะนั้น ผู้ถืออาวุธจึงทิ้งเชลยและของที่ริบมาต่อหน้าเจ้านายและชุมนุมชนทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 15, 'และผู้ชายซึ่งถูกระบุชื่อนั้นได้ลุกขึ้นเอาเสื้อผ้าอันเป็นของที่ริบมาให้แก่คนที่เปลือยกายอยู่ในพวกเชลยและเขาก็นุ่งห่มให้เขาไว้ และให้รองเท้า และจัดหาอาหารและเครื่องดื่มให้ และชโลมเขา และนําคนที่อ่อนเปลี้ยในพวกเขาขึ้นลา นําเขากลับมายังญาติพี่น้องของเขาที่เมืองเยรีโค คือเมืองต้นอินทผลัม และเขาทั้งหลายก็กลับไปยังสะมาเรีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 16, 'ครั้งนั้นกษัตริย์อาหัสทรงใช้ให้ไปหากษัตริย์แห่งอัสซีเรียเพื่อขอความช่วยเหลือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 17, 'เพราะคนเอโดมได้บุกรุกเข้ามาอีก และโจมตียูดาห์ และจับไปเป็นเชลยบ้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 18, 'และคนฟีลิสเตียได้เข้าปล้นหัวเมืองในหุบเขาและที่ภาคใต้ของยูดาห์ และได้ยึดเมืองเบธเชเมช อัยยาโลน เกเดโรท และโสโคกับชนบท ทิมนาห์กับชนบท และทั้งกิมโซกับชนบท และเขาก็ตั้งอยู่ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 19, 'เพราะพระเยโฮวาห์ทรงกระทําให้ยูดาห์ต้อยต่ําลงด้วยเหตุอาหัสกษัตริย์แห่งอิสราเอล เพราะอาหัสทรงกระทําให้ยูดาห์เปลือยเปล่าไปแล้วและได้ละเมิดต่อพระเยโฮวาห์อย่างร้ายแรง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 20, 'ฉะนั้นทิกลัทปิเลเสอร์กษัตริย์แห่งอัสซีเรียจึงยกขึ้นมาต่อสู้กับพระองค์ และกระทําให้พระองค์ทุกข์พระทัยแทนที่จะสนับสนุนพระองค์ให้เข้มแข็ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 21, 'เพราะอาหัสทรงเอาของส่วนหนึ่งจากพระนิเวศของพระเยโฮวาห์ และจากราชสํานัก และจากเจ้านายถวายเป็นบรรณาการแด่กษัตริย์ของอัสซีเรีย แต่หาเป็นประโยชน์แก่พระองค์ไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 22, 'ในคราวทุกข์ยากนั้น พระองค์ยิ่งละเมิดต่อพระเยโฮวาห์ คือกษัตริย์อาหัสองค์เดียวกันนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 23, 'เพราะพระองค์ทรงถวายสัตวบูชาแก่พระของเมืองดามัสกัสซึ่งได้ให้พระองค์พ่ายแพ้และตรัสว่า “เพราะว่าพระแห่งกษัตริย์ของซีเรียได้ช่วยเขาทั้งหลาย เราจึงจะถวายสัตวบูชาแก่พระเหล่านั้นเพื่อจะช่วยเรา” แต่พระเหล่านั้นเป็นเครื่องทําลายพระองค์ และทั้งอิสราเอลทั้งปวงด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 24, 'และอาหัสทรงรวบรวมเครื่องใช้ของพระนิเวศแห่งพระเจ้า และตัดเครื่องใช้แห่งพระนิเวศของพระเจ้าเป็นชิ้นๆ และพระองค์ทรงปิดประตูพระนิเวศของพระเยโฮวาห์ และพระองค์ทรงสร้างแท่นบูชาสําหรับพระองค์ทุกมุมเมืองเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 25, 'พระองค์ทรงสร้างปูชนียสถานสูงในหัวเมืองของยูดาห์ทุกหัวเมืองเพื่อเผาเครื่องหอมถวายพระอื่น กระทําให้พระเยโฮวาห์พระเจ้าแห่งบรรพบุรุษของพระองค์ทรงพระพิโรธ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 26, 'ส่วนพระราชกิจนอกนั้นของพระองค์ และพระราชวัตรของพระองค์ทั้งสิ้น ตั้งแต่ต้นจนปลาย ดูเถิด เขาบันทึกไว้ในหนังสือของกษัตริย์แห่งยูดาห์และอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 27, 'และอาหัสก็ล่วงหลับไปอยู่กับบรรพบุรุษของพระองค์ เขาก็ฝังพระศพไว้ในกรุง คือในเยรูซาเล็ม แต่เขามิได้นําพระศพไปไว้ในอุโมงค์ของกษัตริย์แห่งอิสราเอล และเฮเซคียาห์โอรสของพระองค์ได้ครอบครองแทนพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 1, 'เมื่อเฮเซคียาห์มีพระชนมายุยี่สิบห้าพรรษา พระองค์ทรงเริ่มครอบครอง และพระองค์ทรงครอบครองในกรุงเยรูซาเล็มยี่สิบเก้าปี พระราชมารดาของพระองค์ทรงพระนามว่า อาบียาห์ บุตรสาวของเศคาริยาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 2, 'และพระองค์ทรงกระทําสิ่งที่ถูกต้องในสายพระเนตรของพระเยโฮวาห์ ตามซึ่งดาวิดบรรพบุรุษของพระองค์ได้ทรงกระทําทุกประการ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 3, 'ในปีแรกแห่งรัชกาลของพระองค์ในเดือนแรก พระองค์ทรงเปิดประตูพระนิเวศของพระเยโฮวาห์ และได้ทรงทําการซ่อมแซมประตูนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 4, 'พระองค์ทรงนําปุโรหิตและคนเลวีเข้ามาและทรงให้เขาชุมนุมที่ถนนด้านตะวันออก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 5, 'และตรัสกับเขาว่า “คนเลวีเอ๋ย ขอฟังเรา จงชําระตัวให้บริสุทธิ์ และชําระพระนิเวศของพระเยโฮวาห์พระเจ้าแห่งบรรพบุรุษของท่านให้บริสุทธิ์ และขนสิ่งสกปรกออกเสียจากสถานบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 6, 'เพราะบรรพบุรุษของเราทั้งหลายได้กระทําการละเมิด และได้กระทําสิ่งที่ชั่วในสายพระเนตรพระเยโฮวาห์พระเจ้าของเรา เขาทั้งหลายได้ทอดทิ้งพระองค์ และหันหน้าของเขาเสียจากที่ประทับของพระเยโฮวาห์ และได้หันหลังให้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 7, 'เขาปิดประตูมุขพระนิเวศด้วย และได้ดับประทีปเสีย และมิได้เผาเครื่องหอมหรือถวายเครื่องเผาบูชาในสถานบริสุทธิ์แด่พระเจ้าแห่งอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 8, 'เพราะฉะนั้นพระพิโรธของพระเยโฮวาห์จึงมาบนยูดาห์และเยรูซาเล็ม และพระองค์ทรงกระทําให้เขาเป็นสิ่งที่น่าหวาดเสียว เป็นที่สยดสยอง และเป็นที่เย้ยหยันตามที่ท่านได้เห็นกับตาของท่านแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 9, 'เพราะดูเถิด บิดาทั้งหลายของเราได้ล้มลงด้วยดาบ และบุตรชายบุตรสาวกับภรรยาของเราได้เป็นเชลยเพราะเหตุนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 10, 'บัดนี้เรามีใจประสงค์ที่จะกระทําพันธสัญญากับพระเยโฮวาห์พระเจ้าแห่งอิสราเอล เพื่อว่าพระพิโรธอันแรงกล้าของพระองค์จะหันไปเสียจากเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 11, 'บุตรชายทั้งหลายของข้าพเจ้าเอ๋ย อย่าเพิกเฉยเพราะพระเยโฮวาห์ได้ทรงเลือกท่านให้ยืนอยู่เฉพาะพระพักตร์ของพระองค์ เพื่อปรนนิบัติพระองค์ และเป็นผู้ปรนนิบัติของพระองค์ และเผาเครื่องหอม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 12, 'แล้วคนเลวีก็ลุกขึ้น คือมาฮาทบุตรชายอามาสัย และโยเอลบุตรชายอาซาริยาห์ ผู้เป็นลูกหลานของโคฮาท และลูกหลานของเมรารี มีคีชบุตรชายอับดี และอาซาริยาห์บุตรชายเยฮาลเลเลล และของคนเกอร์โชน มีโยอาห์บุตรชายศิมมาห์ และเอเดนบุตรชายโยอาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 13, 'และลูกหลานของเอลีซาฟาน มีชิมรีและเยอีเอล และลูกหลานของอาสาฟ มีเศคาริยาห์และมัทธานิยาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 14, 'และลูกหลานของเฮมาน มีเยฮีเอลและชิเมอี และลูกหลานของเยดูธูน มีเชไมอาห์และอุสซีเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 15, 'เขาทั้งหลายรวบรวมพี่น้องของเขา และชําระตนให้บริสุทธิ์ และเข้าไปตามที่กษัตริย์ได้ทรงบัญชา โดยพระวจนะของพระเยโฮวาห์ ให้ชําระพระนิเวศของพระเยโฮวาห์ให้บริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 16, 'ปุโรหิตได้เข้าไปในส่วนข้างในของพระนิเวศของพระเยโฮวาห์เพื่อชําระให้บริสุทธิ์ และเขานําสิ่งสกปรกที่เขาพบในพระวิหารของพระเยโฮวาห์ออกมาที่ลานพระนิเวศของพระเยโฮวาห์ และคนเลวีก็ขนเอาของนั้นออกไปยังลําธารขิดโรน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 17, 'เขาเริ่มชําระในวันแรกของเดือนแรก และในวันที่แปดของเดือนนั้นเขามายังมุขของพระเยโฮวาห์ เขาชําระพระนิเวศของพระเยโฮวาห์อยู่แปดวัน และในวันที่สิบหกของเดือนแรกก็เสร็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 18, 'แล้วเขาเข้าไปหากษัตริย์เฮเซคียาห์และทูลว่า “ข้าพระองค์ทั้งหลายได้กระทําความสะอาดพระนิเวศของพระเยโฮวาห์สิ้นเสร็จแล้ว ทั้งแท่นเครื่องเผาบูชา และเครื่องใช้ของแท่นนั้นทั้งสิ้น และโต๊ะขนมปังหน้าพระพักตร์ และเครื่องใช้ของโต๊ะนั้นทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 19, 'เครื่องใช้ทั้งสิ้นซึ่งกษัตริย์อาหัสคัดทิ้งในรัชสมัยของพระองค์ เมื่อพระองค์ได้กระทําการละเมิด ข้าพระองค์ทั้งหลายได้เตรียมพร้อมและได้ชําระแล้ว และดูเถิด ของเหล่านั้นก็อยู่หน้าแท่นบูชาของพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 20, 'แล้วกษัตริย์เฮเซคียาห์ทรงลุกขึ้นแต่เช้า และรวบรวมเจ้านายของกรุง และเสด็จขึ้นไปยังพระนิเวศของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 21, 'และเขาได้นําวัวผู้เจ็ดตัว แกะผู้เจ็ดตัว ลูกแกะเจ็ดตัว และแพะผู้เจ็ดตัวเป็นเครื่องบูชาไถ่บาปสําหรับราชอาณาจักร สถานบริสุทธิ์และยูดาห์ และพระองค์ทรงบัญชาให้ลูกหลานของอาโรน คือปุโรหิตให้ถวายของเหล่านั้นบนแท่นบูชาของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 22, 'เขาทั้งหลายจึงฆ่าวัวผู้และปุโรหิตก็รับเลือดและพรมที่แท่นบูชา และเขาทั้งหลายฆ่าแกะผู้ และเอาเลือดของมันพรมแท่นบูชา และฆ่าลูกแกะ เอาเลือดของมันพรมแท่นบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 23, 'แล้วแพะผู้สําหรับเป็นเครื่องบูชาไถ่บาปนั้นเขานํามาที่กษัตริย์และที่ประชุมชน และเขาทั้งหลายก็เอามือของเขาวางบนแพะนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 24, 'และปุโรหิตก็ฆ่าแพะเสีย และเอาเลือดของมันทําการคืนดีกันบนแท่นนั้นเพื่อทําการลบมลทินบาปให้อิสราเอลทั้งปวง เพราะกษัตริย์ทรงบัญชาว่า ให้ทําเครื่องเผาบูชาและเครื่องบูชาไถ่บาปสําหรับอิสราเอลทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 25, 'แล้วพระองค์ทรงให้คนเลวีประจําอยู่ในพระนิเวศของพระเยโฮวาห์ มีฉาบ พิณใหญ่ และพิณเขาคู่ ตามบัญญัติของดาวิด และของกาดผู้ทํานายของกษัตริย์ และของนาธันผู้พยากรณ์ เพราะว่าพระบัญญัตินั้นมาจากพระเยโฮวาห์ทางผู้พยากรณ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 26, 'คนเลวีก็ยืนอยู่ ถือเครื่องดนตรีของดาวิด และปุโรหิตถือแตร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 27, 'แล้วเฮเซคียาห์ทรงบัญชาว่า ให้ถวายเครื่องเผาบูชานั้นบนแท่น และเมื่อเริ่มถวายเครื่องเผาบูชา ก็เริ่มถวายเพลงแด่พระเยโฮวาห์ และแตรกับเครื่องดนตรีของดาวิดกษัตริย์ของอิสราเอลก็เริ่มด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 28, 'ชุมนุมชนทั้งสิ้นก็นมัสการ และนักร้องก็ร้องเพลง และคนดนตรีก็เป่าแตร ทําอย่างนี้อยู่จนถวายเครื่องเผาบูชาเสร็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 29, 'เมื่อการถวายบูชาเสร็จแล้ว กษัตริย์และคนทั้งปวงที่อยู่กับพระองค์ก็กราบลงนมัสการ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 30, 'และกษัตริย์เฮเซคียาห์และเจ้านายก็บัญชาให้คนเลวีร้องเพลงสรรเสริญพระเยโฮวาห์ด้วยถ้อยคําของดาวิดและของอาสาฟผู้ทํานาย และเขาทั้งหลายร้องเพลงสรรเสริญด้วยความยินดี และเขาก็ก้มศีรษะลงนมัสการ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 31, 'แล้วเฮเซคียาห์ตรัสว่า “บัดนี้ท่านทั้งหลายได้ชําระตัวของท่านให้บริสุทธิ์ต่อพระเยโฮวาห์ จงเข้ามาใกล้ นําเครื่องสัตวบูชา และเครื่องบูชาโมทนามายังพระนิเวศของพระเยโฮวาห์” และชุมนุมชนก็นําเครื่องสัตวบูชาและเครื่องบูชาโมทนา และทุกคนที่มีใจสมัครก็ได้นําเครื่องเผาบูชามา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 32, 'จํานวนเครื่องเผาบูชาซึ่งชุมนุมชนนํามา คือวัวผู้เจ็ดสิบตัว แกะผู้หนึ่งร้อยและลูกแกะสองร้อย ทั้งสิ้นนี้เป็นเครื่องเผาบูชาแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 33, 'และเครื่องบูชาที่มอบถวายไว้ มีวัวผู้หกร้อยตัว และแกะสามพันตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 34, 'แต่มีปุโรหิตน้อยเกินไป จนถลกหนังเครื่องเผาบูชาทั้งหมดไม่ได้ คนเลวีพี่น้องของเขาก็ได้ช่วยจนเสร็จงาน และจนกว่าปุโรหิตคนอื่นจะเสร็จการชําระตนให้บริสุทธิ์ เพราะในการชําระตนนั้นคนเลวีจริงจังยิ่งกว่าพวกปุโรหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 35, 'นอกจากเครื่องเผาบูชามีจํานวนมากมายแล้วยังมีไขมันของเครื่องสันติบูชา และมีเครื่องดื่มบูชาคู่กับเครื่องเผาบูชาด้วย ดังนี้แหละงานปรนนิบัติในพระนิเวศของพระเยโฮวาห์ก็ฟื้นคืนมาอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 36, 'เฮเซคียาห์กับประชาชนทั้งปวงก็เปรมปรีดิ์ด้วยการที่พระเจ้าได้ทรงกระทําให้แก่ประชาชนครั้งนี้ เพราะเรื่องนี้เกิดขึ้นปัจจุบันทันด่วน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 1, 'เฮเซคียาห์ทรงรับสั่งไปถึงอิสราเอลและยูดาห์ทั้งปวง และทรงพระอักษรถึงเอฟราอิมกับมนัสเสห์ด้วยว่า เขาทั้งหลายควรจะมายังพระนิเวศของพระเยโฮวาห์ที่เยรูซาเล็ม เพื่อจะถือเทศกาลปัสกาถวายแด่พระเยโฮวาห์พระเจ้าของอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 2, 'เพราะว่ากษัตริย์และเจ้านายของพระองค์ทั้งชุมนุมชนทั้งปวงในเยรูซาเล็มได้ปรึกษากันที่จะถือเทศกาลปัสกาในเดือนที่สอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 3, 'ด้วยเขาทั้งหลายจะถือปัสกาตามกําหนดไม่ได้ เพราะว่าพวกปุโรหิตยังมิได้ชําระตนให้บริสุทธิ์เพียงพอแก่จํานวน และประชาชนยังมิได้ชุมนุมกันในเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 4, 'และแผนงานนั้นก็เป็นที่ชอบแก่กษัตริย์และชุมนุมชนทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 5, 'เขาจึงลงมติให้ทําประกาศออกไปทั่วอิสราเอล ตั้งแต่เบเออร์เชบาถึงเมืองดานว่า ประชาชนควรมาถือปัสกาถวายแด่พระเยโฮวาห์พระเจ้าแห่งอิสราเอลที่เยรูซาเล็ม เพราะเขามิได้ถือเป็นเวลานานตามที่ได้กําหนดไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 6, 'คนเดินหนังสือจึงออกไปทั่วอิสราเอลและยูดาห์ ถือหนังสือจากกษัตริย์และบรรดาเจ้านายของพระองค์ เพราะกษัตริย์ได้ทรงบัญชาว่า “ชนอิสราเอลเอ๋ย จงกลับมาหาพระเยโฮวาห์ พระเจ้าของอับราฮัม อิสอัค และอิสราเอล เพื่อพระองค์จะหันกลับมายังคนส่วนที่เหลืออยู่ของท่าน ผู้ซึ่งหนีรอดจากพระหัตถ์ของกษัตริย์แห่งอัสซีเรีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 7, 'ท่านอย่าเป็นเหมือนบิดาและเหมือนพี่น้องของท่านผู้ได้กระทําการละเมิดต่อพระเยโฮวาห์พระเจ้าแห่งบรรพบุรุษของเขา พระองค์จึงทรงมอบเขาให้ถึงความเศร้าสลดตามที่ท่านเองก็เห็นอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 8, 'และคราวนี้อย่าคอแข็งอย่างบิดาของท่านทั้งหลายเลย แต่จงยอมมอบตัวท่านแด่พระเยโฮวาห์ และมายังสถานบริสุทธิ์ของพระองค์ซึ่งพระองค์ทรงชําระไว้ให้บริสุทธิ์เป็นนิตย์ และปรนนิบัติพระเยโฮวาห์พระเจ้าของท่าน เพื่อพระพิโรธอันแรงกล้าของพระองค์จะหันไปเสียจากท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 9, 'เพราะถ้าท่านทั้งหลายหันกลับมายังพระเยโฮวาห์ พี่น้องของท่านและลูกหลานของท่านจะประสบความเอ็นดูจากผู้ที่จับเขาไปเป็นเชลย และจะได้กลับมายังแผ่นดินนี้อีก เพราะพระเยโฮวาห์พระเจ้าของท่านทรงพระเมตตาและกรุณา ถ้าท่านกลับมาหาพระองค์ พระองค์จะไม่ทรงหันพระพักตร์ไปจากท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 10, 'คนเดินหนังสือจึงไปตามหัวเมืองต่างๆทั่วแผ่นดินเอฟราอิมและมนัสเสห์ไกลไปจนถึงเศบูลุน แต่คนทั้งหลายก็หัวเราะเยาะเขา และเย้ยหยันเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 11, 'มีแต่คนอาเชอร์ มนัสเสห์และเศบูลุนบางคนที่ถ่อมตัวและมายังเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 12, 'พระหัตถ์ของพระเจ้าอยู่เหนือยูดาห์ด้วย ทรงให้เขาเป็นใจเดียวกันที่จะกระทําตามซึ่งกษัตริย์และเจ้านายได้บัญชาเขาไว้ตามพระวจนะของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 13, 'ประชาชนเป็นอันมากมาประชุมกันในเยรูซาเล็มเพื่อถือเทศกาลกินขนมปังไร้เชื้อในเดือนที่สอง เป็นการชุมนุมใหญ่ยิ่งนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 14, 'พวกเขาลุกขึ้นและได้กําจัดแท่นบูชาที่อยู่ในเยรูซาเล็มและแท่นสําหรับเผาเครื่องหอมทั้งปวงนั้น เขาขนไปทิ้งเสียในลําธารขิดโรน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 15, 'และเขาทั้งหลายได้ฆ่าแกะปัสกาในวันที่สิบสี่ของเดือนที่สอง ปุโรหิตและคนเลวีก็ต้องรู้สึกละอาย เพราะฉะนั้นเขาจึงชําระตัวให้บริสุทธิ์ และนําเครื่องเผาบูชามาในพระนิเวศของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 16, 'เขาทั้งหลายเข้าประจําตําแหน่งที่เขาเคย ตามพระราชบัญญัติของโมเสสคนของพระเจ้า ปุโรหิตก็เอาเลือดซึ่งเขารับมาจากมือของคนเลวีประพรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 17, 'เพราะว่ามีหลายคนในชุมนุมชนนั้นยังมิได้ชําระตนให้บริสุทธิ์ เพราะฉะนั้นคนเลวีจึงต้องฆ่าแกะปัสกาแทนทุกคนที่มลทิน เพื่อกระทําให้บริสุทธิ์ต่อพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 18, 'เพราะว่ามวลชนนั้น คนเป็นอันมากที่มาจากเอฟราอิม มนัสเสห์ อิสสาคาร์ และเศบูลุนยังไม่ได้ชําระตน ถึงกระนั้นเขาก็ยังรับประทานปัสกาผิดต่อข้อที่กําหนดไว้ แต่เฮเซคียาห์ทรงอธิษฐานเผื่อเขาว่า “ขอพระเยโฮวาห์ผู้ประเสริฐทรงให้อภัยแก่ทุกๆคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 19, 'ผู้ปักใจเสาะหาพระเจ้า คือพระเยโฮวาห์พระเจ้าแห่งบรรพบุรุษของเขา ถึงแม้ว่าจะไม่ชําระตัวตามกฎของความบริสุทธิ์แห่งสถานบริสุทธิ์นี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 20, 'พระเยโฮวาห์ทรงฟังเฮเซคียาห์และทรงรักษาประชาชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 21, 'และประชาชนอิสราเอลที่อยู่ ณ เยรูซาเล็มได้ถือเทศกาลกินขนมปังไร้เชื้อเจ็ดวันด้วยความยินดียิ่ง และคนเลวีกับปุโรหิตได้สรรเสริญพระเยโฮวาห์ทุกวันๆ ร้องเพลงทําเสียงดังด้วยเครื่องดนตรีของเขาถวายแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 22, 'และเฮเซคียาห์ทรงกล่าวหนุนใจพวกคนเลวีทั้งปวงผู้สอนถึงความรู้อันประเสริฐแห่งพระเยโฮวาห์ พวกเขาจึงรับประทานอาหารในเทศกาลนั้นเจ็ดวัน ได้ถวายสัตว์เป็นเครื่องสันติบูชา และสารภาพความผิดบาปต่อพระเยโฮวาห์พระเจ้าแห่งบรรพบุรุษของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 23, 'แล้วชุมนุมชนทั้งสิ้นก็ตกลงกันที่จะถือเทศกาลไปอีกเจ็ดวัน เขาจึงถือเทศกาลไปอีกเจ็ดวันด้วยความยินดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 24, 'เพราะเฮเซคียาห์กษัตริย์แห่งยูดาห์ได้ทรงประทานวัวผู้หนึ่งพันตัวและแกะเจ็ดพันตัวแก่ชุมนุมชน และพวกเจ้านายได้ให้วัวผู้หนึ่งพันตัวและแกะหนึ่งหมื่นตัวแก่ชุมนุมชน และปุโรหิตเป็นจํานวนมากก็ได้ชําระตนให้บริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 25, 'ชุมนุมชนทั้งสิ้นของยูดาห์ กับบรรดาปุโรหิตและคนเลวี และชุมนุมชนทั้งสิ้นซึ่งออกมาจากอิสราเอล และคนต่างด้าวซึ่งออกมาจากแผ่นดินอิสราเอลและซึ่งอยู่ในยูดาห์เปรมปรีดิ์กัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 26, 'จึงมีความชื่นบานใหญ่ยิ่งในเยรูซาเล็ม เพราะตั้งแต่สมัยของซาโลมอนโอรสของดาวิดกษัตริย์แห่งอิสราเอลไม่เคยมีอย่างนี้เลยในเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 27, 'แล้วบรรดาปุโรหิตและคนเลวีได้ลุกขึ้นอวยพรประชาชน เสียงของเขาก็ถึงพระกรรณ และคําอธิษฐานของเขาก็ขึ้นมายังที่ประทับบริสุทธิ์ของพระองค์คือสวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 1, 'เมื่อสําเร็จงานนี้ทั้งสิ้นแล้วอิสราเอลทั้งปวงผู้อยู่ที่นั่นได้ออกไปยังหัวเมืองยูดาห์และทําลายเสาศักดิ์สิทธิ์เป็นชิ้นๆ และโค่นบรรดาเสารูปเคารพลง และพังปูชนียสถานสูงลง และพังแท่นทั่วยูดาห์และเบนยามินทั้งสิ้นและในเอฟราอิมกับมนัสเสห์ จนเขาทําลายเสียหมดสิ้น แล้วประชาชนอิสราเอลทั้งปวงก็กลับไปยังหัวเมืองของตน ทุกคนกลับไปยังที่ดินของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 2, 'เฮเซคียาห์ได้ทรงจัดการแบ่งบรรดาปุโรหิตและคนเลวีเป็นกองๆ แต่ละกองตามหน้าที่ปรนนิบัติของตน คือบรรดาปุโรหิตและคนเลวี ให้เป็นพนักงานฝ่ายเครื่องเผาบูชาและเครื่องสันติบูชาให้ปรนนิบัติ และให้ถวายโมทนาและสรรเสริญภายในประตูค่ายของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 3, 'ส่วนที่กษัตริย์ทรงบริจาคจากทรัพย์สินส่วนพระองค์นั้น เป็นเครื่องเผาบูชาคือเครื่องเผาบูชาสําหรับเช้าและสําหรับเย็น และเครื่องเผาบูชาสําหรับวันสะบาโต วันขึ้นหนึ่งค่ําและเทศกาลตามกําหนด ดังที่บันทึกไว้ในพระราชบัญญัติของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 4, 'และพระองค์ทรงบัญชาประชาชนผู้อยู่ในเยรูซาเล็มให้บริจาคส่วนที่เป็นของปุโรหิตและของคนเลวี เพื่อเขาเหล่านั้นจะได้เข้มแข็งขึ้นในพระราชบัญญัติของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 5, 'พอพระบัญชากระจายออกไป ประชาชนอิสราเอลก็ได้บริจาคเข้ามาอย่างมากมาย มีผลรุ่นแรกของข้าว น้ําองุ่น น้ํามัน น้ําผึ้ง และผลิตผลทุกอย่างของไร่นา และเขานําสิบชักหนึ่งแห่งของทุกชนิดเข้ามาอย่างมากมาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 6, 'และประชาชนอิสราเอลและยูดาห์ผู้อาศัยอยู่ในหัวเมืองของยูดาห์ได้นําสิบชักหนึ่งของวัวและแกะ และสิบชักหนึ่งของสิ่งบริสุทธิ์ที่มอบถวายแด่พระเยโฮวาห์พระเจ้าของเขา และเก็บไว้เป็นกองๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 7, 'ในเดือนที่สามเขาเริ่มกองสุมขึ้นและสําเร็จในเดือนที่เจ็ด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 8, 'เมื่อเฮเซคียาห์และเจ้านายมาเห็นกองเหล่านั้น ท่านทั้งหลายก็ถวายสาธุการแด่พระเยโฮวาห์ และอวยพรแก่อิสราเอลประชาชนของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 9, 'เฮเซคียาห์ก็ทรงไต่ถามปุโรหิตและคนเลวีถึงเรื่องกองเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 10, 'อาซาริยาห์ปุโรหิตใหญ่ ผู้เป็นวงศ์วานของศาโดกทูลตอบพระองค์ว่า “ตั้งแต่ประชาชนได้เริ่มนําส่วนบริจาคเข้ามาในพระนิเวศของพระเยโฮวาห์ พวกข้าพระองค์ได้รับประทานและมีพอกับมีเหลือมาก เพราะพระเยโฮวาห์ได้ทรงอํานวยพระพรประชาชนของพระองค์ จึงมีเหลืออยู่ใหญ่โตอย่างนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 11, 'แล้วเฮเซคียาห์จึงทรงบัญชาให้เขาจัดห้องในพระนิเวศของพระเยโฮวาห์และเขาทั้งหลายก็จัดไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 12, 'และเขาทั้งหลายนําสิ่งบริจาคเข้ามาอย่างสัตย์ซื่อทั้งสิบชักหนึ่งและของมอบถวาย หัวหน้าเจ้าหน้าที่ผู้ดูแลคือโคนานิยาห์คนเลวีกับชิเมอีน้องชายเป็นคนรอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 13, 'เยฮีเอล อาซาซิยาห์ นาหาท อาสาเฮล เยรีโมท โยซาบาด เอลีเอล อิสมาคิยาห์ มาฮาท และเบไนยาห์ เป็นผู้ควบคุมช่วยเหลือโคนานิยาห์ และชิเมอีน้องชายของเขา โดยการแต่งตั้งของกษัตริย์เฮเซคียาห์ และอาซาริยาห์เจ้าหน้าที่ชั้นผู้ใหญ่ของพระนิเวศของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 14, 'โคเร บุตรชายอิมนาห์คนเลวี ผู้เฝ้าประตูตะวันออก เป็นผู้ดูแลของบูชาที่ถวายตามใจสมัครแด่พระเจ้า แจกส่วนบริจาคที่สงวนไว้สําหรับพระเยโฮวาห์และสิ่งบริสุทธิ์ที่สุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 15, 'เอเดน มินยามิน เยชูอา เชไมอาห์ อามาริยาห์ เชคานิยาห์ได้ช่วยเขาในตําแหน่งหน้าที่ในหัวเมืองของปุโรหิต ให้แจกแก่พี่น้องของเขาทั้งหลาย ทั้งผู้ใหญ่และผู้น้อยเหมือนกันตามกองเวร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 16, 'เว้นแต่คนเหล่านั้นที่ขึ้นทะเบียนไว้ตามผู้ชาย ตั้งแต่สามขวบขึ้นไป ทุกคนที่เข้าไปในพระนิเวศของพระเยโฮวาห์ เป็นเวรตามหน้าที่ประจําวันที่ต้องทํา เพื่อทําการปรนนิบัติตามหน้าที่โดยกองของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 17, 'การขึ้นทะเบียนปุโรหิตก็กระทําตามวงศ์วานแห่งบรรพบุรุษของเขา ส่วนคนเลวีตั้งแต่อายุยี่สิบปีขึ้นไปก็ขึ้นตามหน้าที่ของเขา ตามกองเวรของเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 18, 'และขึ้นทะเบียนทั้งลูกเล็กๆของเขา ภรรยาของเขา บุตรชายบุตรสาวของเขามวลชนทั้งสิ้น เพราะในตําแหน่งหน้าที่นั้นเขาทั้งหลายได้ชําระตัวให้บริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 19, 'สําหรับลูกหลานของอาโรนคือพวกปุโรหิต ผู้อยู่ในทุ่งนารวมรอบหัวเมืองของเขานั้น มีผู้ชายในหัวเมืองต่างๆ ผู้ถูกระบุชื่อให้แจกจ่ายส่วนแบ่งแก่ผู้ชายทุกคนในพวกปุโรหิต และทุกคนในพวกคนเลวีผู้ซึ่งได้ขึ้นทะเบียนไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 20, 'เฮเซคียาห์ทรงกระทําดังนี้ทั่วทั้งยูดาห์ และพระองค์ทรงกระทําสิ่งที่ดีและชอบ และที่เป็นความจริงต่อพระพักตร์พระเยโฮวาห์พระเจ้าของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 21, 'และงานทุกอย่างซึ่งพระองค์ทรงเริ่มกระทําในการปรนนิบัติแห่งพระนิเวศของพระเจ้า และตามพระราชบัญญัติและพระบัญญัติ เพื่อแสวงหาพระเจ้าของพระองค์ พระองค์ทรงกระทําด้วยเต็มพระทัย และทรงจําเริญขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 1, 'ภายหลังเหตุการณ์เหล่านี้และการสถาปนาขึ้นนั้น เซนนาเคอริบกษัตริย์อัสซีเรียยกมาบุกรุกยูดาห์ และตั้งค่ายล้อมหัวเมืองที่มีป้อมไว้ ทรงดําริที่จะยึดไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 2, 'และเมื่อเฮเซคียาห์ทรงเห็นว่าเซนนาเคอริบยกมาด้วยเจตนาจะต่อสู้กับเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 3, 'พระองค์ทรงวางแผนการกับเจ้านายของพระองค์ และทแกล้วทหารของพระองค์ ที่จะอุดน้ําตามน้ําพุที่อยู่นอกเมืองเสีย และเขาทั้งหลายก็ทรงช่วยพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 4, 'มีประชาชนเป็นอันมากรวบรวมกันเข้ามา และเขาทั้งหลายอุดน้ําพุและปิดลําธารซึ่งไหลผ่านแผ่นดินเสีย พูดว่า “ทําไมจะให้บรรดากษัตริย์อัสซีเรียยกมาพบน้ําเป็นอันมากเล่า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 5, 'พระองค์ทรงประกอบกิจอย่างบึกบึน สร้างกําแพงที่ปรักหักพังนั้นทั่วไปใหม่ และสร้างหอคอยขึ้น และทรงสร้างกําแพงข้างนอกอีกชั้นหนึ่ง และพระองค์ทรงเสริมกําแพงป้อมมิลโลที่นครดาวิด ทรงสร้างหอกและโล่เป็นจํานวนมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 6, 'และพระองค์ทรงตั้งผู้บังคับการต่อต้านไว้เหนือประชาชน และทรงรวบรวมเข้าไว้ด้วยกัน ณ ถนนที่ประตูนคร และตรัสอย่างหนุนใจเขาทั้งหลายว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 7, '“จงเข้มแข็งและกล้าหาญเถิด อย่ากลัวหรือท้อถอยต่อกษัตริย์อัสซีเรีย และต่อกองทัพทั้งสิ้นที่อยู่กับเขานั้น เพราะมีผู้หนึ่งฝ่ายเราที่ใหญ่กว่าฝ่ายเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 8, 'ฝ่ายเขามีแต่กําลังเนื้อหนัง แต่ฝ่ายเรามีพระเยโฮวาห์พระเจ้าของเราทรงสถิตกับเราที่ทรงช่วยเราและสู้รบฝ่ายเรา” ประชาชนก็วางใจในพระดํารัสของเฮเซคียาห์กษัตริย์แห่งยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 9, 'ภายหลังเซนนาเคอริบกษัตริย์แห่งอัสซีเรีย (ผู้ซึ่งกําลังล้อมเมืองลาคีชอยู่ด้วยกําลังรบทั้งสิ้นของพระองค์) ได้รับสั่งให้ข้าราชการของพระองค์ไปยังกรุงเยรูซาเล็มถึงเฮเซคียาห์กษัตริย์ของยูดาห์ และถึงประชาชนทั้งปวงของยูดาห์ที่อยู่ในเยรูซาเล็มว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 10, '“เซนนาเคอริบกษัตริย์แห่งอัสซีเรียตรัสดังนี้ว่า ‘เจ้าทั้งหลายพึ่งอะไร เจ้าจึงยืนมั่นให้ล้อมอยู่ในกรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 11, 'เฮเซคียาห์มิได้พาเจ้าให้หลงเพื่อจะมอบให้เจ้าตายด้วยการอดอาหารและความกระหายหรือ ในเมื่อเขาบอกเจ้าว่า “พระเยโฮวาห์พระเจ้าของเราจะทรงช่วยเราให้พ้นจากมือของกษัตริย์แห่งอัสซีเรีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 12, 'เฮเซคียาห์คนนี้แหละมิใช่หรือที่ได้กําจัดปูชนียสถานสูง และแท่นบูชาของพระองค์ และบัญชาแก่ยูดาห์กับเยรูซาเล็มว่า “เจ้าจงนมัสการอยู่หน้าแท่นบูชาแท่นเดียว และเจ้าจงเผาเครื่องหอมบนแท่นนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 13, 'เจ้าไม่รู้หรือว่าเราและบรรพบุรุษของเราได้กระทําอะไรแก่ชนชาติทั้งหลายแห่งประเทศต่างๆ พระของบรรดาประชาชาติแห่งประเทศเหล่านั้นสามารถที่จะช่วยประเทศของเขาให้พ้นจากมือของเราหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 14, 'ในพวกพระทั้งปวงแห่งประชาชาติเหล่านั้นที่บรรพบุรุษของเราได้ทําลายเสียอย่างสิ้นเชิง ยังมีพระองค์ใดเล่าที่สามารถช่วยประชาชนของตนให้พ้นจากมือของเรา แล้วพระเจ้าของเจ้าน่ะหรือจะสามารถช่วยเจ้าให้พ้นจากมือของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 15, 'เพราะฉะนั้นบัดนี้อย่าให้เฮเซคียาห์ล่อลวงเจ้า หรือพาเจ้าให้หลงในทํานองนี้ อย่าเชื่อเขา เพราะไม่มีพระแห่งประชาชาติหรือราชอาณาจักรใดที่สามารถช่วยประชาชนของตนให้พ้นจากมือของเรา หรือจากมือบรรพบุรุษของเรา พระเจ้าของเจ้าจะช่วยเจ้าให้พ้นจากมือของเราได้น้อยยิ่งกว่านั้นสักเท่าใดเล่า’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 16, 'และข้าราชการของพระองค์ก็กล่าวทับถมพระเยโฮวาห์พระเจ้าและเฮเซคียาห์ผู้รับใช้ของพระองค์มากยิ่งกว่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 17, 'และพระองค์ทรงพระอักษรหมิ่นประมาทพระเยโฮวาห์พระเจ้าของอิสราเอล และตรัสทับถมพระองค์ว่า “พระของบรรดาประชาชาติแห่งประเทศทั้งหลายมิได้ช่วยประชาชนของตนให้พ้นจากมือของเราฉันใด พระเจ้าของเฮเซคียาห์ก็จะไม่ช่วยประชาชนของตนให้พ้นจากมือของเราฉันนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 18, 'และเขาทั้งหลายก็ตะโกนความนี้ด้วยเสียงอันดังเป็นภาษาฮีบรูให้ชาวเยรูซาเล็มผู้อยู่บนกําแพงฟัง เพื่อให้เขาตกใจและหวาดหวั่นไหว จะได้ยึดเอาเมืองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 19, 'เขาได้พูดถึงพระเจ้าแห่งเยรูซาเล็มอย่างกับที่เขาพูดถึงพระแห่งชนชาติทั้งหลายของแผ่นดินโลก ซึ่งเป็นผลงานของมือมนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 20, 'แล้วกษัตริย์เฮเซคียาห์และผู้พยากรณ์อิสยาห์บุตรชายอามอสได้อธิษฐานเพราะเรื่องนี้และร้องทูลต่อสวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 21, 'และพระเยโฮวาห์ทรงใช้ทูตสวรรค์องค์หนึ่ง ซึ่งได้ตัดทแกล้วทหารทั้งปวงและผู้บังคับกองและนายทหารในค่ายของกษัตริย์แห่งอัสซีเรียออกเสีย เพราะฉะนั้นพระองค์จึงเสด็จกลับไปยังแผ่นดินของพระองค์ด้วยความอับอายขายพระพักตร์ และเมื่อพระองค์เสด็จเข้าในนิเวศแห่งพระของพระองค์ คนเหล่านั้นที่ออกมาจากบั้นเอวของพระองค์เองได้ฆ่าพระองค์ด้วยดาบเสียที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 22, 'ดังนั้นพระเยโฮวาห์จึงทรงช่วยเฮเซคียาห์และชาวเยรูซาเล็มให้พ้นจากพระหัตถ์ของเซนนาเคอริบกษัตริย์แห่งอัสซีเรีย และจากมือของศัตรูทั้งสิ้นของพระองค์ และพระองค์ทรงนําเขาทั้งหลายอยู่ทุกด้าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 23, 'และคนเป็นอันมากนําของถวายพระเยโฮวาห์มายังกรุงเยรูซาเล็ม และของกํานัลต่างๆมาถวายเฮเซคียาห์กษัตริย์แห่งยูดาห์ พระองค์จึงทรงเป็นที่ยกย่องในสายตาของประชาชาติทั้งปวงตั้งแต่เวลานั้นเป็นต้นมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 24, 'ครั้งนั้นเฮเซคียาห์ทรงประชวรใกล้จะสิ้นพระชนม์ และพระองค์ทูลอธิษฐานต่อพระเยโฮวาห์ และพระเยโฮวาห์ทรงตอบ และประทานหมายสําคัญอย่างหนึ่งให้แก่เฮเซคียาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 25, 'แต่เฮเซคียาห์มิได้สนองพระคุณนั้น เพราะพระทัยของพระองค์ผยองขึ้น เพราะฉะนั้นพระพิโรธจึงมาเหนือพระองค์ ยูดาห์และเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 26, 'แต่เฮเซคียาห์ทรงอ่อนน้อมถ่อมพระทัยที่กําเริบนั้นลง ทั้งพระองค์และชาวเยรูซาเล็ม พระพิโรธของพระเยโฮวาห์จึงมิได้มาเหนือเขาทั้งหลายในรัชกาลเฮเซคียาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 27, 'เฮเซคียาห์ทรงมีราชทรัพย์และเกียรติใหญ่ยิ่ง และพระองค์ทรงสร้างคลังไว้สําหรับพระองค์ เพื่อเก็บเงิน ทองคํา และเพชรพลอยต่างๆ เครื่องเทศ โล่ และสําหรับทรัพย์สินที่มีค่าทุกชนิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 28, 'ทั้งฉางสําหรับข้าว น้ําองุ่น และน้ํามัน ที่ผลิตมา และโรงเก็บสัตว์เลี้ยงทุกชนิดและคอกแกะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 29, 'พระองค์ทรงจัดหัวเมืองเพื่อพระองค์ด้วย ทั้งฝูงแพะแกะและฝูงวัวเป็นอันมาก เพราะพระเจ้าทรงประทานทรัพย์สินให้พระองค์มากยิ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 30, 'เฮเซคียาห์องค์นี้เองทรงปิดทางน้ําออกตอนบนของน้ําพุกีโฮนเสีย แล้วนําไปให้ไหลลงไปทางทิศตะวันตกของนครดาวิด และเฮเซคียาห์ทรงจําเริญในพระราชกิจทั้งสิ้นของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 31, 'อย่างไรก็ตามในเรื่องทูตที่เจ้านายเมืองบาบิโลนใช้ให้มาถามถึงการมหัศจรรย์ซึ่งได้เกิดขึ้นในแผ่นดิน พระเจ้าก็ทรงปล่อยพระองค์ตามอําเภอใจ เพื่อจะทดลองพระองค์ และเพื่อจะทราบพระดําริทั้งสิ้นในพระทัยของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 32, 'ฝ่ายพระราชกิจนอกนั้นของเฮเซคียาห์ และความดีของพระองค์ ดูเถิด มีบันทึกไว้ในนิมิตของอิสยาห์ผู้พยากรณ์บุตรชายอามอส และในหนังสือของกษัตริย์แห่งยูดาห์และอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 33, 'และเฮเซคียาห์ล่วงหลับไปอยู่กับบรรพบุรุษของพระองค์ และเขาฝังพระศพไว้ในอุโมงค์สําคัญที่สุดของโอรสของดาวิด และบรรดาคนยูดาห์และชาวเยรูซาเล็มทั้งปวงได้ถวายเกียรติเมื่อพระองค์สิ้นพระชนม์ และมนัสเสห์โอรสของพระองค์ได้ครอบครองแทนพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 1, 'เมื่อมนัสเสห์เริ่มครอบครองมีพระชนมายุสิบสองพรรษา และพระองค์ทรงครอบครองในเยรูซาเล็มห้าสิบห้าปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 2, 'พระองค์ทรงกระทําสิ่งที่ชั่วร้ายในสายพระเนตรของพระเยโฮวาห์ ตามการกระทําที่น่าสะอิดสะเอียนของประชาชาติ ซึ่งพระเยโฮวาห์ทรงขับไล่ไปเสียให้พ้นหน้าประชาชนอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 3, 'เพราะพระองค์ทรงสร้างปูชนียสถานสูงขึ้นใหม่ ซึ่งเฮเซคียาห์พระราชบิดาของพระองค์ได้ทรงพังลงนั้น และทรงสร้างแท่นบูชาแก่พระบาอัล และทรงทําบรรดาเสารูปเคารพ และนมัสการบริวารทั้งสิ้นของฟ้าสวรรค์ และปรนนิบัติพระเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 4, 'และพระองค์ทรงสร้างแท่นบูชาในพระนิเวศของพระเยโฮวาห์ ซึ่งพระเยโฮวาห์ตรัสว่า “นามของเราจะอยู่ในเยรูซาเล็มเป็นนิตย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 5, 'และพระองค์ได้ทรงสร้างแท่นบูชาสําหรับบรรดาบริวารแห่งฟ้าสวรรค์ในลานทั้งสองแห่งพระนิเวศของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 6, 'และพระองค์ได้ทรงถวายโอรสของพระองค์ให้ลุยไฟในหุบเขาบุตรชายของฮินโนม ถือฤกษ์ยาม ใช้เวทมนตร์ ใช้ไสยศาสตร์ ติดต่อกับคนทรงและพ่อมดหมอผี พระองค์ทรงกระทําสิ่งที่ชั่วร้ายเป็นอันมากในสายพระเนตรของพระเยโฮวาห์ ซึ่งเป็นการยั่วยุให้พระองค์ทรงกริ้วโกรธ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 7, 'และรูปเคารพสลัก ซึ่งคือรูปเคารพที่พระองค์ทรงสร้างนั้น พระองค์ทรงตั้งไว้ในพระนิเวศของพระเจ้า ซึ่งพระเจ้าตรัสกับดาวิดและซาโลมอนโอรสของดาวิดว่า “ในนิเวศนี้และในเยรูซาเล็ม ซึ่งเราได้เลือกออกจากตระกูลทั้งสิ้นของอิสราเอล เราจะบรรจุนามของเราไว้เป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 8, 'และเราจะไม่ให้เท้าของอิสราเอลพเนจรออกไปจากแผ่นดินซึ่งเราได้กําหนดให้บรรพบุรุษของเจ้าอีกเลย ถ้าเขาเพียงแต่จะระมัดระวังกระทําทุกอย่างซึ่งเราได้บัญชาเขาไว้ คือราชบัญญัติ กฎเกณฑ์ และกฎทั้งสิ้นซึ่งได้ให้ไว้โดยทางโมเสส”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 9, 'มนัสเสห์ทรงชักจูงยูดาห์และชาวเยรูซาเล็มให้หลง เขาจึงได้กระทําความชั่วร้ายยิ่งกว่าบรรดาประชาชาติ ซึ่งพระเยโฮวาห์ได้ทรงทําลายให้พ้นหน้าประชาชนอิสราเอลนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 10, 'พระเยโฮวาห์ตรัสกับมนัสเสห์และประชาชนของพระองค์ แต่เขาทั้งหลายไม่ฟัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 11, 'เพราะฉะนั้นพระเยโฮวาห์ทรงให้ผู้บังคับกองทหารของกษัตริย์แห่งอัสซีเรียมาต่อสู้เขาทั้งหลาย ได้จับมนัสเสห์ท่ามกลางพงหนามและจองจําด้วยตรวนและนําพระองค์มายังบาบิโลน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 12, 'และเมื่อพระองค์ทรงทุกข์ยาก พระองค์ทรงวิงวอนขอพระกรุณาต่อพระเยโฮวาห์พระเจ้าของพระองค์ และถ่อมพระทัยลงอย่างมากต่อพระพักตร์พระเจ้าของบรรพบุรุษของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 13, 'พระองค์ทรงอธิษฐานต่อพระเจ้า และพระเจ้าทรงรับคําวิงวอนของพระองค์ และทรงฟังคําอ้อนวอนของพระองค์ และนําพระองค์กลับมายังกรุงเยรูซาเล็มในราชอาณาจักรของพระองค์อีก แล้วมนัสเสห์ทรงทราบว่าพระเยโฮวาห์ทรงเป็นพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 14, 'ภายหลังพระองค์ทรงสร้างกําแพงชั้นนอกให้นครดาวิดทางตะวันตกของกีโฮนในหุบเขาไปจนถึงทางเข้าประตูปลา แล้ววนรอบตําบลโอเฟล และก่อขึ้นให้สูงมาก และพระองค์ทรงตั้งผู้บังคับบัญชากองทัพให้อยู่ในหัวเมืองมีป้อมในยูดาห์ทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 15, 'และพระองค์ทรงเอาพระต่างด้าวและรูปเคารพไปเสียจากพระนิเวศของพระเยโฮวาห์ และแท่นบูชาทั้งสิ้นซึ่งพระองค์ได้ทรงสร้างไว้บนภูเขาแห่งพระนิเวศของพระเยโฮวาห์ และในเยรูซาเล็ม และพระองค์ทรงทิ้งออกไปนอกเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 16, 'และพระองค์ทรงซ่อมแท่นบูชาของพระเยโฮวาห์ และทรงถวายเครื่องสัตวบูชาเป็นเครื่องสันติบูชาและเครื่องโมทนาพระคุณบนแท่นนั้น และพระองค์ทรงบัญชาให้ยูดาห์ปรนนิบัติพระเยโฮวาห์พระเจ้าแห่งอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 17, 'ถึงกระนั้นก็ดีประชาชนก็ยังถวายสัตวบูชาที่ปูชนียสถานสูง แต่ถวายต่อพระเยโฮวาห์พระเจ้าของเขาเท่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 18, 'ส่วนพระราชกิจนอกนั้นของมนัสเสห์ และคําอธิษฐานของพระองค์ต่อพระเจ้า และถ้อยคําของผู้ทํานาย ผู้ทูลพระองค์ในพระนามของพระเยโฮวาห์พระเจ้าแห่งอิสราเอล ดูเถิด มีบันทึกไว้ในหนังสือของกษัตริย์แห่งอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 19, 'และคําอธิษฐานของพระองค์ และเรื่องที่พระเจ้าทรงรับคําวิงวอนของพระองค์ บาปทั้งสิ้นของพระองค์ และการละเมิดของพระองค์ทั้งสิ้น และสถานที่ซึ่งพระองค์ทรงสร้างปูชนียสถานสูง และตั้งบรรดาเสารูปเคารพและรูปเคารพสลัก ก่อนที่พระองค์ทรงถ่อมพระองค์ลงนั้น ดูเถิด เขาบันทึกไว้ในหนังสือประวัติที่ผู้ทํานายแต่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 20, 'มนัสเสห์จึงทรงล่วงหลับไปอยู่กับบรรพบุรุษของพระองค์ และเขาฝังพระศพไว้ในพระราชวังของพระองค์ และอาโมนโอรสของพระองค์ได้ครอบครองแทนพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 21, 'เมื่ออาโมนเริ่มครอบครองมีพระชนมายุยี่สิบสองพรรษา และพระองค์ทรงครอบครองในเยรูซาเล็มสองปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 22, 'พระองค์ทรงกระทําความชั่วร้ายในสายพระเนตรของพระเยโฮวาห์ อย่างมนัสเสห์ราชบิดาของพระองค์ทรงกระทํานั้น อาโมนถวายสัตวบูชาแก่รูปเคารพสลักทั้งสิ้น ซึ่งมนัสเสห์ราชบิดาของพระองค์ได้ทรงสร้างขึ้น และทรงปรนนิบัติรูปเคารพนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 23, 'และพระองค์มิได้ถ่อมพระองค์ลงต่อพระพักตร์พระเยโฮวาห์ อย่างมนัสเสห์ราชบิดาของพระองค์ได้ถ่อมพระองค์ลงนั้น แต่อาโมนองค์นี้ได้ละเมิดยิ่งขึ้นๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 24, 'แล้วข้าราชการของพระองค์ก็ร่วมกันคิดกบฏต่อพระองค์ และได้ฆ่าพระองค์เสียในพระราชวังของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 25, 'แต่ประชาชนแห่งแผ่นดินได้ประหารบรรดาคนเหล่านั้นที่คิดกบฏต่อกษัตริย์อาโมน และประชาชนแห่งแผ่นดินได้แต่งตั้งให้โยสิยาห์โอรสของพระองค์ครอบครองแทนพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 1, 'เมื่อโยสิยาห์เริ่มครอบครองมีพระชนมายุแปดพรรษา และพระองค์ทรงครอบครองในเยรูซาเล็มสามสิบเอ็ดปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 2, 'พระองค์ทรงกระทําสิ่งที่ถูกต้องในสายพระเนตรของพระเยโฮวาห์ และดําเนินในมรรคาของดาวิดบรรพบุรุษของพระองค์ และพระองค์มิได้ทรงเอนเอียงไปทางขวามือหรือทางซ้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 3, 'เพราะในปีที่แปดแห่งรัชกาลของพระองค์ เมื่อพระองค์ยังทรงพระเยาว์อยู่ พระองค์ทรงเริ่มแสวงหาพระเจ้าของดาวิดบรรพบุรุษของพระองค์ และในปีที่สิบสองพระองค์ทรงเริ่มกวาดล้างยูดาห์และเยรูซาเล็มด้วยการกําจัดปูชนียสถานสูง ทั้งบรรดาเสารูปเคารพและรูปเคารพแกะสลักและรูปเคารพหล่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 4, 'และเขาพังแท่นบูชาพระบาอัลลงต่อพระพักตร์ของพระองค์ และพระองค์ทรงโค่นบรรดารูปเคารพซึ่งตั้งอยู่บนนั้นลง และพระองค์ทรงทุบบรรดาเสารูปเคารพและรูปเคารพแกะสลักกับรูปเคารพหล่อเป็นชิ้นๆ และทรงกระทําให้เป็นผงโรยบนหลุมศพของบรรดาคนที่ถวายสัตวบูชาแก่พระเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 5, 'และพระองค์ทรงเผากระดูกของปุโรหิตบนแท่นพระเหล่านั้น และทรงกวาดยูดาห์และเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 6, 'และพระองค์ทรงกระทําเช่นกันในหัวเมืองของมนัสเสห์ เอฟราอิมและสิเมโอน และไปถึงนัฟทาลี ในที่ปรักหักพังซึ่งอยู่โดยรอบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 7, 'เมื่อพระองค์ทรงทําลายแท่นบูชาและบรรดาเสารูปเคารพ และทรงทุบรูปเคารพสลักให้เป็นผง และทรงโค่นบรรดารูปเคารพทั้งสิ้นลงทั่วแผ่นดินอิสราเอลแล้ว พระองค์เสด็จกลับเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 8, 'ในปีที่สิบแปดแห่งรัชกาลของพระองค์ เมื่อพระองค์ทรงกวาดล้างแผ่นดินและพระนิเวศแล้ว พระองค์ทรงใช้ชาฟานบุตรชายอาซาลิยาห์ และมาอาเสอาห์ผู้ว่าราชการนคร และโยอาห์บุตรชายโยอาฮาสเจ้ากรมสารบรรณ ให้ซ่อมแซมพระนิเวศของพระเยโฮวาห์พระเจ้าของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 9, 'เมื่อเขาทั้งหลายมาหาฮิลคียาห์มหาปุโรหิตแล้ว เขาได้มอบเงินซึ่งคนทั้งหลายนํามายังพระนิเวศของพระเจ้า ซึ่งคนเลวีผู้เฝ้าธรณีประตูได้เก็บจากมนัสเสห์และเอฟราอิม และจากบรรดาคนที่เหลือของอิสราเอล และจากยูดาห์กับเบนยามินทั้งสิ้น แล้วพวกเขากลับไปยังเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 10, 'เขาทั้งหลายมอบให้แก่คนทํางานผู้ดูแลพระนิเวศของพระเยโฮวาห์ และมอบให้แก่คนทํางานผู้ทํางานอยู่ในพระนิเวศของพระเยโฮวาห์ เพื่อการซ่อมแซมพระนิเวศให้มั่นคง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 11, 'เขาทั้งหลายมอบให้แก่ช่างไม้และช่างก่อสร้างเพื่อจะซื้อหินสลักและไม้กระดาน เพื่อประกับและเป็นคานสําหรับอาคาร ซึ่งกษัตริย์แห่งยูดาห์ได้ปล่อยให้ทรุดโทรมพังทลายไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 12, 'และคนทั้งหลายก็ทํางานอย่างสัตย์ซื่อ ผู้คุมงานมียาหาทและโอบาดีห์คนเลวีลูกหลานของเมรารี และเศคาริยาห์กับเมชุลลามลูกหลานของคนโคฮาทเป็นผู้ดูแล คนเลวีทุกคนที่ชํานาญเครื่องดนตรี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 13, 'เป็นผู้ดูแลคนหาบหาม และบรรดาคนที่ทํางานปรนนิบัติทุกอย่าง คนเลวีบางคนเป็นอาลักษณ์ เป็นเจ้าหน้าที่และเป็นนายประตู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 14, 'ขณะที่เขาทั้งหลายนําเงินที่ได้ถวายในพระนิเวศของพระเยโฮวาห์ออกมา ฮิลคียาห์ปุโรหิตได้พบหนังสือพระราชบัญญัติของพระเยโฮวาห์ซึ่งทรงประทานทางโมเสส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 15, 'และฮิลคียาห์พูดกับชาฟานราชเลขาว่า “ข้าพเจ้าได้พบหนังสือพระราชบัญญัติในพระนิเวศของพระเยโฮวาห์” และฮิลคียาห์ก็มอบหนังสือนั้นให้ชาฟาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 16, 'และชาฟานได้นําหนังสือไปถวายกษัตริย์ และต่อไปก็ทูลรายงานกษัตริย์ว่า “สิ่งทั้งปวงที่พระองค์ทรงมอบหมายแก่ผู้รับใช้ของพระองค์ให้กระทํานั้น เขากําลังกระทําอยู่แล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 17, 'เขารวบรวมเงินซึ่งพบในพระนิเวศของพระเยโฮวาห์ และได้มอบไว้ในมือของผู้ดูแลและคนงาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 18, 'แล้วชาฟานราชเลขาทูลกษัตริย์ว่า “ฮิลคียาห์ปุโรหิตได้มอบหนังสือแก่ข้าพระองค์ม้วนหนึ่ง” แล้วชาฟานก็อ่านถวายต่อพระพักตร์กษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 19, 'และอยู่มาเมื่อกษัตริย์ทรงสดับถ้อยคําของพระราชบัญญัตินั้น พระองค์ทรงฉีกฉลองพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 20, 'และกษัตริย์ทรงบัญชาแก่ฮิลคียาห์ อาหิคัมบุตรชายชาฟาน อับโดนบุตรชายมีคาห์ ชาฟานราชเลขา และอาสายาห์ผู้รับใช้ของกษัตริย์ ตรัสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 21, '“จงไปทูลถามพระเยโฮวาห์ให้แก่เรา และให้แก่บรรดาผู้ที่เหลืออยู่ในอิสราเอลและในยูดาห์ เกี่ยวกับถ้อยคําในหนังสือซึ่งได้พบนั้น เพราะว่าพระพิโรธของพระเยโฮวาห์ซึ่งเทลงเหนือเรานั้นใหญ่ยิ่งนัก เพราะว่าบรรพบุรุษของเราไม่ได้รักษาพระวจนะของพระเยโฮวาห์ ตามซึ่งเขียนไว้ในหนังสือนี้ทุกประการ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 22, 'ฮิลคียาห์และคนเหล่านั้นซึ่งกษัตริย์ทรงใช้ไปจึงไปยังฮุลดาห์หญิงผู้พยากรณ์ภรรยาของชัลลูม บุตรชายทิกวาห์ บุตรชายหัสราห์ผู้ดูแลฉลองพระองค์ (นางอยู่ในเยรูซาเล็มที่แขวงสอง) และพูดกับนางถึงเรื่องนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 23, 'และนางพูดกับเขาว่า “พระเยโฮวาห์พระเจ้าแห่งอิสราเอลตรัสดังนี้ว่า จงบอกชายผู้ซึ่งใช้พวกเจ้าให้มาหาเราว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 24, '‘พระเยโฮวาห์ตรัสดังนี้ว่า ดูเถิด เราจะนําเหตุชั่วร้ายมาเหนือสถานที่นี้ และเหนือชาวเมืองนี้ คือคําสาปทั้งสิ้นที่บันทึกไว้ในหนังสือซึ่งได้อ่านถวายต่อพระพักตร์กษัตริย์แห่งยูดาห์นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 25, 'เพราะว่าเขาทั้งหลายได้ทอดทิ้งเรา และได้เผาเครื่องหอมถวายพระอื่น เพื่อเขาจะกระทําให้เราโกรธด้วยการงานทั้งสิ้นแห่งมือของเขา เพราะฉะนั้นความพิโรธของเราจะเทลงเหนือสถานที่นี้และจะดับไม่ได้’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 26, 'แต่กษัตริย์ของยูดาห์ผู้ใช้เจ้าให้มาทูลพระเยโฮวาห์นั้น เจ้าจงทูลท่านดังนี้ว่า ‘พระเยโฮวาห์พระเจ้าแห่งอิสราเอลตรัสดังนี้ว่า เรื่องถ้อยคําซึ่งเจ้าได้ยินนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 27, 'เพราะจิตใจของเจ้าอ่อนโยน และเจ้าได้ถ่อมตัวลงต่อพระพักตร์พระเจ้า เมื่อเจ้าได้ยินถ้อยคําที่ปรักปรําสถานที่นี้ และชาวเมืองนี้ เจ้าได้ถ่อมตัวลงต่อหน้าเรา และเจ้าได้ฉีกเสื้อผ้าของเจ้าและร้องไห้ต่อหน้าเรา พระเยโฮวาห์ตรัสว่า เราได้ฟังเจ้าด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 28, 'ดูเถิด เราจะรวบเจ้าไปอยู่กับบรรพบุรุษของเจ้า และเขาจะรวบเจ้าไปสู่ที่ฝังศพอย่างสันติ และตาของเจ้าจะไม่เห็นบรรดาเหตุชั่วร้ายซึ่งเราจะนํามาเหนือสถานที่นี้และชาวเมืองนี้’” และเขาทั้งหลายนําพระวจนะกลับมายังกษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 29, 'แล้วกษัตริย์รับสั่งให้รวบรวมบรรดาผู้ใหญ่ของยูดาห์และเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 30, 'และกษัตริย์เสด็จขึ้นไปยังพระนิเวศของพระเยโฮวาห์ พร้อมกับคนทั้งปวงของยูดาห์และชาวเยรูซาเล็มกับปุโรหิตและคนเลวี คนทั้งปวงทั้งใหญ่และเล็ก และพระองค์ทรงอ่านถ้อยคําทั้งสิ้นในหนังสือพันธสัญญา ซึ่งได้พบในพระนิเวศของพระเยโฮวาห์ให้เขาฟัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 31, 'และกษัตริย์ประทับยืนอยู่ในพระที่ของพระองค์ และกระทําพันธสัญญาต่อพระพักตร์พระเยโฮวาห์ ที่จะทรงดําเนินตามพระเยโฮวาห์ และรักษาพระบัญญัติ พระโอวาทและกฎเกณฑ์ของพระองค์ด้วยสุดพระจิตสุดพระทัย ที่จะทรงประกอบกิจตามถ้อยคําของพันธสัญญาซึ่งบันทึกไว้ในหนังสือม้วนนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 32, 'แล้วพระองค์ทรงรับสั่งบรรดาผู้ที่อยู่ในเยรูซาเล็มและในเบนยามินให้เข้าส่วนในพันธสัญญานั้น และชาวเยรูซาเล็มก็กระทําตามพันธสัญญาของพระเจ้า พระเจ้าของบรรพบุรุษของเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 33, 'และโยสิยาห์ได้เอาสิ่งที่น่าสะอิดสะเอียนทั้งปวงออกไปเสียจากดินแดนทั้งสิ้นซึ่งเป็นของประชาชนอิสราเอล และทรงกระทําให้บรรดาผู้ที่อยู่ในอิสราเอลปรนนิบัติพระเยโฮวาห์พระเจ้าของเขาทั้งหลาย เขาทั้งหลายก็มิได้พรากไปจากการติดตามพระเยโฮวาห์พระเจ้าของบรรพบุรุษของเขาทั้งหลายตลอดรัชสมัยของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 1, 'ยิ่งกว่านั้นโยสิยาห์ทรงถือเทศกาลปัสกาถวายแด่พระเยโฮวาห์ในกรุงเยรูซาเล็ม เขาฆ่าแกะปัสกาในวันที่สิบสี่ของเดือนต้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 2, 'พระองค์ทรงแต่งตั้งปุโรหิตให้ประจําหน้าที่ และทรงสนับสนุนเขาในการปรนนิบัติของพระนิเวศแห่งพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 3, 'และพระองค์ตรัสกับคนเลวี ผู้บริสุทธิ์เฉพาะพระเยโฮวาห์ ผู้สอนอิสราเอลทั้งปวงว่า “จงวางหีบบริสุทธิ์ไว้ในพระนิเวศ ซึ่งซาโลมอนโอรสของดาวิดกษัตริย์ของอิสราเอลทรงสร้างไว้ เจ้าทั้งหลายไม่ต้องใส่บ่าหามไปอีก บัดนี้จงปรนนิบัติพระเยโฮวาห์พระเจ้าของเจ้า และอิสราเอลประชาชนของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 4, 'จงเตรียมตัวของเจ้าตามเรือนบรรพบุรุษของเจ้าเป็นกองๆ ตามบันทึกพระราชดํารัสชี้แจงของดาวิดกษัตริย์แห่งอิสราเอล และตามบันทึกพระราชดํารัสชี้แจงของซาโลมอนโอรสของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 5, 'และยืนประจําอยู่ในสถานบริสุทธิ์ ตามพวกต่างๆตามครอบครัวของบรรพบุรุษที่เป็นพี่น้องของท่าน ผู้เป็นประชาชน และตามส่วนแบ่งของแต่ละครอบครัวของคนเลวี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 6, 'และฆ่าแกะปัสกาและชําระตนให้บริสุทธิ์ และเตรียมไว้ให้พี่น้องของเจ้า เพื่อให้เขากระทําตามพระวจนะของพระเยโฮวาห์ทางโมเสสนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 7, 'แล้วโยสิยาห์ได้ทรงบริจาคแก่ประชาชนเป็นเครื่องปัสกาบูชาสําหรับคนทั้งปวงที่อยู่ที่นั่น เป็นลูกแกะและลูกแพะจากฝูงแพะแกะจํานวนสามหมื่นตัว และวัวผู้สามพันตัว สัตว์เหล่านี้ได้มาจากทรัพย์สินของกษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 8, 'และเจ้านายของพระองค์บริจาคด้วยความเต็มใจแก่ประชาชน แก่ปุโรหิต และแก่คนเลวี ฮิลคียาห์ เศคาริยาห์และเยฮีเอล เจ้าหน้าที่ชั้นหัวหน้าของพระนิเวศแห่งพระเจ้า ได้มอบลูกแกะและลูกแพะสองพันหกร้อยตัวกับวัวผู้สามร้อยตัวแก่ปุโรหิตเป็นเครื่องปัสกาบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 9, 'กับโคนานิยาห์ และเชไมอาห์ กับเนธันเอล พวกน้องชายของเขา และฮาชาบิยาห์ และเยอีเอล กับโยซาบาด หัวหน้าของคนเลวี ได้ให้ลูกแกะและลูกแพะห้าพันตัวกับวัวผู้ห้าร้อยตัวแก่คนเลวีเป็นเครื่องปัสกาบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 10, 'เมื่อเตรียมการเรียบร้อยแล้วบรรดาปุโรหิตก็ยืนประจําที่ของตน และคนเลวีก็อยู่ตามกองของตน ตามพระบัญชาของกษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 11, 'แล้วเขาก็ฆ่าแกะปัสกา แล้วปุโรหิตก็เอาเลือดซึ่งรับมาจากมือเขาประพรม ส่วนคนเลวีถลกหนังสัตว์นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 12, 'แล้วเขาก็แยกส่วนที่เป็นเครื่องเผาบูชาไว้ต่างหากเพื่อแจกจ่ายได้ตามพวกต่างๆ ผู้เป็นประชาชนที่แบ่งเป็นแต่ละครอบครัว ให้ถวายแด่พระเยโฮวาห์ ดังที่บันทึกไว้ในหนังสือของโมเสส และเขากระทํากับวัวผู้ทํานองเดียวกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 13, 'และเขาก็ปิ้งแกะปัสกาด้วยไฟตามกฎ และเขาทั้งหลายต้มเครื่องบูชาบริสุทธิ์อื่นๆในหม้อ ในหม้อขนาดใหญ่ และในกระทะ และนําไปให้ประชาชนทั้งปวงโดยเร็ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 14, 'ภายหลังเขาทั้งหลายจึงเตรียมสําหรับตนเองและสําหรับปุโรหิต เพราะว่าปุโรหิตลูกหลานของอาโรนติดธุระในการถวายเครื่องเผาบูชาและส่วนไขมันจนกลางคืน คนเลวีจึงเตรียมเพื่อตนเองและเพื่อปุโรหิตลูกหลานของอาโรน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 15, 'บรรดานักร้องซึ่งเป็นลูกหลานของอาสาฟอยู่ประจําที่ของตน ตามบัญชาของดาวิด อาสาฟ และเฮมาน กับเยดูธูนผู้ทํานายของกษัตริย์ และคนเฝ้าประตูก็อยู่ประจําทุกประตู เขาไม่จําเป็นละงานหน้าที่ของเขา เพราะคนเลวีพี่น้องของเขาได้เตรียมไว้ให้เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 16, 'เขาจึงเตรียมการปรนนิบัติทั้งสิ้นแด่พระเยโฮวาห์ในวันเดียวนั้นเอง เพื่อจะถือเทศกาลปัสกา และถวายเครื่องเผาบูชาบนแท่นบูชาของพระเยโฮวาห์ ตามพระบัญชาของกษัตริย์โยสิยาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 17, 'และประชาชนอิสราเอลผู้อยู่ที่นั่นได้ถือเทศกาลปัสกาเวลานั้น และเทศกาลกินขนมปังไร้เชื้อเจ็ดวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 18, 'ตั้งแต่สมัยของซามูเอลผู้พยากรณ์ ไม่มีเทศกาลปัสกาเหมือนอย่างนี้ได้ถือกันมาในอิสราเอล ไม่มีกษัตริย์แห่งอิสราเอลสักองค์หนึ่งที่ถือเทศกาลปัสกาอย่างที่โยสิยาห์ได้ทรงถือนี้ และบรรดาปุโรหิตกับคนเลวี และยูดาห์กับอิสราเอลทั้งปวงซึ่งอยู่พร้อมกัน ทั้งชาวเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 19, 'เขาถือเทศกาลปัสกานี้ในปีที่สิบแปดแห่งรัชกาลโยสิยาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 20, 'หลังจากสิ่งทั้งปวงเหล่านี้เมื่อโยสิยาห์ได้เตรียมพระวิหารไว้ เนโคกษัตริย์แห่งอียิปต์ได้เสด็จขึ้นไปสู้รบที่คารเคมิชที่แม่น้ํายูเฟรติส และโยสิยาห์เสด็จออกไปสู้รบกับพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 21, 'แต่พระองค์รับสั่งให้ทูตไปทูลโยสิยาห์ว่า “กษัตริย์แห่งยูดาห์เอ๋ย เรามีเรื่องอะไรเกี่ยวข้องกับท่าน วันนี้เรามิได้มาต่อสู้ท่านแต่ต่อสู้กับวงศ์วานซึ่งเราทําสงครามด้วย เพราะพระเจ้าทรงบัญชาเราให้เร่งรีบ ขอยับยั้งการขัดขวางพระเจ้าผู้ทรงสถิตกับเรา เกรงว่าพระองค์จะทรงทําลายท่านเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 22, 'ถึงกระนั้นก็ดีโยสิยาห์มิได้หันพระพักตร์ไปจากพระองค์ แต่ทรงปลอมพระองค์ เพื่อจะสู้รบกับพระองค์ มิได้ฟังพระดํารัสของเนโคที่ออกจากพระโอษฐ์ของพระเจ้า แต่เข้ารบ ณ ที่หุบเขาเมกิดโด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 23, 'และนักธนูได้ยิงกษัตริย์โยสิยาห์ และกษัตริย์ตรัสกับข้าราชการของพระองค์ว่า “จงพาเราไปเสียเถอะ เพราะเราถูกบาดเจ็บสาหัสแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 24, 'ข้าราชการของพระองค์จึงนําพระองค์ออกจากรถรบ และให้พระองค์ประทับในรถรบคันที่สองของพระองค์ และนําพระองค์มาเยรูซาเล็มและพระองค์ก็สิ้นพระชนม์ และเขาฝังไว้ในอุโมงค์แห่งบรรพบุรุษของพระองค์ ยูดาห์และเยรูซาเล็มทั้งปวงได้ไว้ทุกข์ให้โยสิยาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 25, 'เยเรมีย์กล่าวคําคร่ําครวญถวายโยสิยาห์ด้วย และบรรดานักร้องชายและนักร้องหญิงทั้งปวงกล่าวถึงโยสิยาห์ในคําคร่ําครวญของเขาจนทุกวันนี้ เขาทั้งหลายกระทําเรื่องนี้ให้เป็นกฎในอิสราเอล ดูเถิด มีบันทึกไว้ในหนังสือคร่ําครวญ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 26, 'ส่วนพระราชกิจนอกนั้นของโยสิยาห์ และความดีของพระองค์ ตามที่บันทึกไว้ในพระราชบัญญัติของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 27, 'และพระราชกิจของพระองค์ ตั้งแต่ต้นจนปลาย ดูเถิด มีบันทึกไว้ในหนังสือของกษัตริย์แห่งอิสราเอลและยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 1, 'ประชาชนแห่งแผ่นดินได้ตั้งเยโฮอาหาสโอรสของโยสิยาห์ และให้พระองค์เป็นกษัตริย์แทนราชบิดาของพระองค์ในเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 2, 'เมื่อเยโฮอาหาสเริ่มครอบครองมีพระชนมายุยี่สิบสามพรรษา และพระองค์ทรงครอบครองในเยรูซาเล็มสามเดือน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 3, 'แล้วกษัตริย์แห่งอียิปต์ทรงถอดพระองค์ในเยรูซาเล็ม และกําหนดให้แผ่นดินนั้นถวายบรรณาการเป็นเงินหนึ่งร้อยตะลันต์ และทองคําหนึ่งตะลันต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 4, 'และกษัตริย์แห่งอียิปต์ตั้งให้เอลียาคิมพระอนุชาของพระองค์เป็นกษัตริย์เหนือยูดาห์และเยรูซาเล็ม และทรงเปลี่ยนพระนามของพระองค์ใหม่ว่า เยโฮยาคิม แต่เนโคทรงจับเยโฮอาหาสพระเชษฐานําไปยังอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 5, 'เมื่อเยโฮยาคิมเริ่มครองราชย์นั้นทรงมีพระชนมายุยี่สิบห้าพรรษา และพระองค์ทรงครองราชย์ในเยรูซาเล็มสิบเอ็ดปี พระองค์ทรงกระทําความชั่วร้ายในสายพระเนตรของพระเยโฮวาห์พระเจ้าของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 6, 'เนบูคัดเนสซาร์กษัตริย์แห่งบาบิโลนเสด็จขึ้นมาต่อสู้กับพระองค์ และจองจําพระองค์ด้วยตรวนเพื่อพาพระองค์ไปยังบาบิโลน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 7, 'เนบูคัดเนสซาร์ทรงนําเครื่องใช้ส่วนหนึ่งของพระนิเวศของพระเยโฮวาห์ไปยังบาบิโลน และทรงเก็บไว้ในวิหารของพระองค์ในบาบิโลน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 8, 'ส่วนพระราชกิจนอกนั้นของเยโฮยาคิม และการอันน่าสะอิดสะเอียนซึ่งพระองค์ทรงกระทํา และเหตุการณ์อื่นๆซึ่งเกี่ยวกับพระองค์ ดูเถิด สิ่งเหล่านี้ก็ถูกบันทึกไว้ในหนังสือของกษัตริย์แห่งอิสราเอลและยูดาห์ และเยโฮยาคีนโอรสของพระองค์ได้ครองราชย์แทนพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 9, 'เมื่อเยโฮยาคีนเริ่มครองราชย์นั้นทรงมีพระชนมายุสิบแปดพรรษา และพระองค์ทรงครองราชย์ในเยรูซาเล็มสามเดือนกับสิบวัน พระองค์ทรงกระทําความชั่วร้ายในสายพระเนตรของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 10, 'พอถึงสิ้นปีแล้วกษัตริย์เนบูคัดเนสซาร์ทรงใช้ให้นําพระองค์มายังบาบิโลน พร้อมกับเครื่องใช้ประเสริฐแห่งพระนิเวศของพระเยโฮวาห์ และตั้งให้เศเดคียาห์ปิตุลาของพระองค์เป็นกษัตริย์เหนือยูดาห์และเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 11, 'เมื่อเศเดคียาห์เริ่มครอบครองมีพระชนมายุยี่สิบเอ็ดพรรษา และพระองค์ทรงครอบครองในเยรูซาเล็มสิบเอ็ดปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 12, 'พระองค์ทรงกระทําความชั่วร้ายในสายพระเนตรของพระเยโฮวาห์พระเจ้าของพระองค์ พระองค์มิได้ถ่อมพระองค์ลงต่อหน้าเยเรมีย์ผู้พยากรณ์ ผู้กล่าวจากพระโอษฐ์ของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 13, 'พระองค์ทรงกบฏเช่นกันต่อกษัตริย์เนบูคัดเนสซาร์ ผู้ซึ่งทรงให้พระองค์สาบานในพระนามของพระเจ้า พระองค์ทรงแข็งพระศอของพระองค์ ทําพระทัยให้กระด้าง ไม่หันไปหาพระเยโฮวาห์พระเจ้าแห่งอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 14, 'ยิ่งกว่านั้นบรรดาปุโรหิตใหญ่และประชาชนก็ทําการละเมิดอย่างยิ่งโดยการติดตามบรรดาสิ่งที่น่าสะอิดสะเอียนของประชาชาติ และเขาทั้งหลายกระทําให้พระนิเวศของพระเยโฮวาห์ซึ่งพระองค์ทรงชําระให้บริสุทธิ์ในเยรูซาเล็มนั้นเป็นมลทินไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 15, 'พระเยโฮวาห์พระเจ้าแห่งบรรพบุรุษของเขาทรงใช้ให้ทูตของพระองค์มาอย่างไม่หยุดยั้ง เพราะพระองค์ทรงมีพระทัยกรุณาต่อประชาชนของพระองค์และต่อที่ประทับของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 16, 'แต่เขาทั้งหลายเยาะเย้ยทูตของพระเจ้า และดูหมิ่นพระวจนะของพระองค์ และด่าผู้พยากรณ์ของพระองค์ จนพระพิโรธของพระเยโฮวาห์พลุ่งขึ้นต่อประชาชนของพระองค์จนแก้ไม่ไหว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 17, 'พระองค์จึงทรงนํากษัตริย์แห่งคนเคลเดียมาต่อสู้เขาทั้งหลาย ผู้ซึ่งฆ่าชายหนุ่มของเขาด้วยดาบในพระนิเวศอันเป็นสถานบริสุทธิ์ของเขา และไม่มีความกรุณาแก่ชายหนุ่มหรือหญิงพรหมจารี คนแก่หรือคนที่ค้อมลงเพราะชรา พระองค์ทรงมอบทั้งหมดไว้ในมือของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 18, 'และเครื่องใช้ทั้งสิ้นของพระนิเวศของพระเจ้า ทั้งใหญ่และเล็ก และทรัพย์สมบัติแห่งพระนิเวศของพระเยโฮวาห์ และทรัพย์สมบัติแห่งกษัตริย์และแห่งเจ้านายของพระองค์ สิ่งทั้งหมดนี้พระองค์ทรงนํามายังบาบิโลน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 19, 'และเขาเผาพระนิเวศของพระเจ้า และพังกําแพงเยรูซาเล็มลง และเอาไฟเผาวังของเมืองนั้นเสียสิ้น และทําลายเครื่องใช้ประเสริฐทั้งปวงในนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 20, 'และบรรดาผู้ที่รอดจากดาบนั้นพระองค์ทรงให้กวาดไปเป็นเชลยยังบาบิโลน และเขาทั้งหลายเป็นผู้รับใช้ของพระองค์และแก่ราชวงศ์ของพระองค์ จนถึงการสถาปนาราชอาณาจักรเปอร์เซีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 21, 'เพื่อให้สําเร็จตามพระวจนะของพระเยโฮวาห์ผ่านปากของเยเรมีย์ จนกว่าแผ่นดินจะได้ชื่นชมกับปีสะบาโตของมัน เพราะตราบเท่าที่มันยังว่างเปล่าอยู่ มันก็รักษาสะบาโต เพื่อจะให้ครบตามกําหนดเจ็ดสิบปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 22, 'ในปีแรกแห่งรัชกาลไซรัสกษัตริย์ของเปอร์เซีย เพื่อพระวจนะของพระเยโฮวาห์ทางปากของเยเรมีย์จะสําเร็จ พระเยโฮวาห์ทรงรบเร้าจิตใจของไซรัสกษัตริย์ของเปอร์เซีย กษัตริย์จึงทรงมีประกาศตลอดราชอาณาจักรของพระองค์ และบันทึกเป็นลายลักษณ์อักษรลงด้วยว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 23, '“ไซรัสกษัตริย์แห่งเปอร์เซียตรัสดังนี้ว่า ‘พระเยโฮวาห์พระเจ้าของฟ้าสวรรค์ได้พระราชทานบรรดาราชอาณาจักรแห่งแผ่นดินโลกแก่เรา และพระองค์ทรงกําชับให้เราสร้างพระนิเวศให้พระองค์ที่เยรูซาเล็ม ซึ่งอยู่ในยูดาห์ มีผู้ใดในท่ามกลางท่านทั้งหลายที่เป็นประชาชนของพระองค์ ขอพระเยโฮวาห์พระเจ้าของเขาสถิตกับเขา ขอให้เขาขึ้นไปเถิด’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 1, 'ในปีแรกแห่งรัชกาลไซรัสกษัตริย์ของเปอร์เซีย เพื่อพระวจนะของพระเยโฮวาห์ทางปากของเยเรมีย์จะสําเร็จ พระเยโฮวาห์ทรงรบเร้าจิตใจของไซรัสกษัตริย์ของเปอร์เซีย กษัตริย์จึงทรงมีประกาศตลอดราชอาณาจักรของพระองค์ และบันทึกเป็นลายลักษณ์อักษรลงด้วยว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 2, '“ไซรัสกษัตริย์แห่งเปอร์เซียตรัสดังนี้ว่า ‘พระเยโฮวาห์พระเจ้าของฟ้าสวรรค์ได้พระราชทานบรรดาราชอาณาจักรแห่งแผ่นดินโลกแก่เรา และพระองค์ทรงกําชับให้เราสร้างพระนิเวศให้พระองค์ที่เยรูซาเล็ม ซึ่งอยู่ในยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 3, 'มีผู้ใดในท่ามกลางท่านทั้งหลายที่เป็นประชาชนของพระองค์ ขอพระเจ้าของเขาสถิตกับเขา และขอให้เขาขึ้นไปยังเยรูซาเล็มซึ่งอยู่ในยูดาห์และสร้างพระนิเวศของพระเยโฮวาห์พระเจ้าแห่งอิสราเอล (คือพระองค์ทรงเป็นพระเจ้า) ซึ่งอยู่ในเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 4, 'และคนใดก็ตามที่เหลืออยู่ ไม่ว่าเขาจะอาศัยอยู่ ณ ที่ใด ขอให้คนซึ่งอยู่ในที่ของเขาช่วยเขาด้วยเงินและด้วยทองคํา ด้วยข้าวของและสัตว์ นอกเหนือจากเครื่องบูชาตามใจสมัครสําหรับพระนิเวศของพระเจ้าซึ่งอยู่ในเยรูซาเล็ม’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 5, 'แล้วประมุขของบรรพบุรุษแห่งยูดาห์และเบนยามินได้ลุกขึ้น ทั้งบรรดาปุโรหิตและคนเลวี คือทุกคนที่พระเจ้าทรงเร้าจิตใจของเขาให้ไปสร้างพระนิเวศของพระเยโฮวาห์ซึ่งอยู่ในเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 6, 'และทุกคนที่อยู่ใกล้เขาก็ได้ช่วยมือเขาด้วยเครื่องเงิน ด้วยทองคํา ด้วยข้าวของและด้วยสัตว์ และด้วยของมีค่า นอกเหนือจากทุกสิ่งที่ถวายบูชาตามใจสมัคร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 7, 'กษัตริย์ไซรัสก็ทรงนําเครื่องใช้ของพระนิเวศแห่งพระเยโฮวาห์ออกมา ซึ่งเป็นเครื่องใช้ที่เนบูคัดเนสซาร์ได้ทรงกวาดมาจากเยรูซาเล็ม และทรงเก็บไว้ในนิเวศแห่งพระของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 8, 'ไซรัสกษัตริย์แห่งเปอร์เซียทรงนําสิ่งเหล่านี้ออกมาในความดูแลของมิทเรดาท สมุหพระคลัง ผู้นับออกให้แก่เชชบัสซาร์เจ้านายของยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 9, 'และนี่เป็นจํานวนของสิ่งเหล่านั้น อ่างทองคําสามสิบ อ่างเงินหนึ่งพัน มีดยี่สิบเก้าเล่ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 10, 'ชามทองคําสามสิบ ชามเงินอีกชนิดหนึ่งมีสี่ร้อยสิบ และภาชนะอย่างอื่นหนึ่งพัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 11, 'ภาชนะที่ทําด้วยทองคําและทําด้วยเงินทั้งสิ้นรวมห้าพันสี่ร้อย ทั้งหมดนี้เชชบัสซาร์ได้นําขึ้นมา เมื่อได้นําพวกเชลยขึ้นมาจากบาบิโลนถึงกรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 1, 'ต่อไปนี้เป็นประชาชนแห่งมณฑลที่ขึ้นมาจากการเป็นเชลยในพวกที่ถูกกวาดไป ซึ่งเนบูคัดเนสซาร์กษัตริย์แห่งบาบิโลนได้กวาดเอาไปเป็นเชลยยังบาบิโลน และกลับไปยังเยรูซาเล็มและยูดาห์ ต่างก็ไปยังเมืองของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 2, 'เขาทั้งหลายมากับเศรุบบาเบลคือ เยชูอา เนหะมีย์ เสไรอาห์ เรเอไลยาห์ โมรเดคัย บิลชาน มิสปาร์ บิกวัย เรฮูม และบาอานาห์ จํานวนผู้ชายของประชาชนอิสราเอลคือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 3, 'คนปาโรช สองพันหนึ่งร้อยเจ็ดสิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 4, 'คนเชฟาทิยาห์ สามร้อยเจ็ดสิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 5, 'คนอาราห์ เจ็ดร้อยเจ็ดสิบห้าคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 6, 'คนปาหัทโมอับ คือลูกหลานของเยชูอาและโยอาบ สองพันแปดร้อยสิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 7, 'คนเอลาม หนึ่งพันสองร้อยห้าสิบสี่คน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 8, 'คนศัทธู เก้าร้อยสี่สิบห้าคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 9, 'คนศักคัย เจ็ดร้อยหกสิบคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 10, 'คนบานี หกร้อยสี่สิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 11, 'คนเบบัย หกร้อยยี่สิบสามคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 12, 'คนอัสกาด หนึ่งพันสองร้อยยี่สิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 13, 'คนอาโดนีคัม หกร้อยหกสิบหกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 14, 'คนบิกวัย สองพันห้าสิบหกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 15, 'คนอาดีน สี่ร้อยห้าสิบสี่คน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 16, 'คนอาเทอร์คือของเฮเซคียาห์ เก้าสิบแปดคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 17, 'คนเบไซ สามร้อยยี่สิบสามคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 18, 'คนโยราห์ หนึ่งร้อยสิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 19, 'คนฮาชูม สองร้อยยี่สิบสามคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 20, 'คนกิบบาร์ เก้าสิบห้าคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 21, 'คนชาวเบธเลเฮม หนึ่งร้อยยี่สิบสามคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 22, 'ชาวเนโทฟาห์ ห้าสิบหกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 23, 'ชาวอานาโธท หนึ่งร้อยยี่สิบแปดคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 24, 'คนอัสมาเวท สี่สิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 25, 'คนชาวคีริยาทอาริม ชาวเคฟีราห์ และชาวเบเอโรท เจ็ดร้อยสี่สิบสามคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 26, 'คนชาวรามาห์ และชาวเกบา หกร้อยยี่สิบเอ็ดคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 27, 'ชาวมิคมาส หนึ่งร้อยยี่สิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 28, 'ชาวเบธเอลและชาวอัย สองร้อยยี่สิบสามคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 29, 'คนชาวเนโบ ห้าสิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 30, 'คนชาวมักบีช หนึ่งร้อยห้าสิบหกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 31, 'คนเอลามอีกคนหนึ่ง หนึ่งพันสองร้อยห้าสิบสี่คน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 32, 'คนชาวฮาริม สามร้อยยี่สิบคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 33, 'คนชาวโลด ชาวฮาดิด และชาวโอโน เจ็ดร้อยยี่สิบห้าคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 34, 'คนชาวเยรีโค สามร้อยสี่สิบห้าคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 35, 'คนเสนาอาห์ สามพันหกร้อยสามสิบคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 36, 'บรรดาปุโรหิตคือ คนเยดายาห์ วงศ์วานเยชูอา เก้าร้อยเจ็ดสิบสามคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 37, 'คนอิมเมอร์ หนึ่งพันห้าสิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 38, 'คนปาชเฮอร์ หนึ่งพันสองร้อยสี่สิบเจ็ดคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 39, 'คนฮาริม หนึ่งพันสิบเจ็ดคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 40, 'คนเลวีคือ คนเยชูอาและขัดมีเอล ฝ่ายคนโฮดาวิยาห์ เจ็ดสิบสี่คน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 41, 'พวกนักร้องคือ คนอาสาฟ หนึ่งร้อยยี่สิบแปดคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 42, 'ลูกหลานคนเฝ้าประตูคือ คนชัลลูม คนอาเทอร์ คนทัลโมน คนอักขูบ คนฮาทิธา และคนโชบัย รวมกันหนึ่งร้อยสามสิบเก้าคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 43, 'คนใช้ประจําพระวิหาร คือคนศีหะ คนฮาสูฟา คนทับบาโอท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 44, 'คนเคโรส คนสีอาฮา คนพาโดน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 45, 'คนเลบานาห์ คนฮากาบาห์ คนอักขูบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 46, 'คนฮากาบ คนชัลมัย คนฮานัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 47, 'คนกิดเดล คนกาฮาร์ คนเรอายาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 48, 'คนเรซีน คนเนโคดา คนกัสซาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 49, 'คนอุสซาห์ คนปาเสอาห์ คนเบสัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 50, 'คนอัสนาห์ คนเมอูนิม คนเนฟิสิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 51, 'คนบัคบูค คนฮาคูฟา คนฮารฮูร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 52, 'คนบัสลูท คนเมหิดา คนฮารชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 53, 'คนบารโขส คนสิเสรา คนเทมาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 54, 'คนเนซิยาห์ และคนฮาทิฟา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 55, 'ลูกหลานข้าราชการของซาโลมอนคือ คนโสทัย คนโสเฟเรท คนเปรุดา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 56, 'คนยาอาลาห์ คนดารโคน คนกิดเดล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 57, 'คนเชฟาทิยาห์ คนฮัทธิล คนโปเคเรทแห่งซาบาอิม และคนอามี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 58, 'คนใช้ประจําพระวิหารและลูกหลานของข้าราชการของซาโลมอนทั้งสิ้น เป็นสามร้อยเก้าสิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 59, 'ต่อไปนี้เป็นบรรดาผู้ที่ขึ้นมาจากเทลเมลาห์ เทลฮารชา เครูบ อัดดาน และอิมเมอร์ แต่เขาพิสูจน์เรือนบรรพบุรุษของเขาหรือเชื้อสายของเขาไม่ได้ ว่าเขาเป็นคนอิสราเอลหรือไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 60, 'คือคนเดไลยาห์ คนโทบีอาห์ และคนเนโคดา รวมหกร้อยห้าสิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 61, 'และจากลูกหลานของปุโรหิตด้วยคือ คนฮาบายาห์ คนฮักโขส และคนบารซิลลัย ผู้ได้ภรรยาจากบุตรสาวของบารซิลลัย คนกิเลอาด จึงได้ชื่อตามนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 62, 'คนเหล่านี้เมื่อค้นหาชื่อในทะเบียนที่เขาขึ้นไว้ในสํามะโนครัวเชื้อสายก็ไม่พบ จึงถือว่าเป็นมลทิน และถูกตัดออกจากตําแหน่งปุโรหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 63, 'ผู้ว่าราชการเมืองสั่งเขามิให้รับประทานอาหารบริสุทธิ์ที่สุด จนกว่าจะมีปุโรหิตที่จะปรึกษากับอูริมและทูมมิมเสียก่อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 64, 'ชุมนุมชนทั้งหมดรวมกันมี สี่หมื่นสองพันสามร้อยหกสิบคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 65, 'นอกเหนือจากคนใช้ชายหญิงซึ่งมีอยู่เจ็ดพันสามร้อยสามสิบเจ็ดคน และเขามีนักร้องชายหญิงสองร้อยคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 66, 'ม้าของเขามีเจ็ดร้อยสามสิบหกตัว ล่อของเขาสองร้อยสี่สิบห้าตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 67, 'อูฐของเขาสี่ร้อยสามสิบห้าตัว และลาของเขาหกพันเจ็ดร้อยยี่สิบตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 68, 'ประมุขของบรรพบุรุษบางคน เมื่อเขามาถึงที่พระนิเวศของพระเยโฮวาห์ซึ่งอยู่ในเยรูซาเล็ม ได้ถวายตามใจสมัครเพื่อพระนิเวศของพระเจ้า เพื่อจะสร้างพระนิเวศขึ้นในที่เดิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 69, 'เขาถวายตามกําลังของเขาแก่กองทรัพย์เพื่อพระราชกิจ เป็นทองคําหกหมื่นหนึ่งพันดาริค เงินห้าพันมาเน และเครื่องแต่งกายปุโรหิตหนึ่งร้อยตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 70, 'บรรดาปุโรหิต คนเลวี ประชาชนส่วนหนึ่ง นักร้อง คนเฝ้าประตู และคนใช้ประจําพระวิหารอยู่ตามเมืองของตน และอิสราเอลทั้งปวงอยู่ตามเมืองของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 1, 'เมื่อมาถึงเดือนที่เจ็ดที่คนอิสราเอลอยู่ตามหัวเมือง ประชาชนได้มาพร้อมหน้ากันที่เยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 2, 'แล้วเยชูอาบุตรชายโยซาดักได้ลุกขึ้นพร้อมกับพวกปุโรหิตผู้เป็นญาติของเขาด้วยกัน กับเศรุบบาเบลบุตรชายเชอัลทิเอล พร้อมกับญาติของเขา และได้สร้างแท่นบูชาของพระเจ้าแห่งอิสราเอล เพื่อถวายเครื่องเผาบูชาบนนั้น ตามที่บันทึกไว้ในพระราชบัญญัติของโมเสสคนของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 3, 'เขาได้ตั้งแท่นบูชาไว้บนฐาน เพราะความกลัวอยู่เหนือเขาเหตุด้วยชนชาติทั้งหลายแห่งแผ่นดินเหล่านั้น และเขาถวายเครื่องเผาบูชาบนแท่นนั้นต่อพระเยโฮวาห์ เป็นเครื่องเผาบูชาเวลาเช้าและเวลาเย็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 4, 'และเขาถือเทศกาลอยู่เพิงตามที่บันทึกไว้ และถวายเครื่องเผาบูชาประจําวันตามจํานวนที่กําหนดไว้ ตามธรรมเนียม อันเป็นหน้าที่พึงทําทุกวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 5, 'ต่อมาก็ถวายเครื่องเผาบูชาเนืองนิตย์ ถวายเครื่องบูชาในวันขึ้นหนึ่งค่ํา และตามบรรดาเทศกาลกําหนดของพระเยโฮวาห์ที่ตั้งไว้ และถวายเครื่องบูชาของทุกคนที่ถวายตามใจสมัครแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 6, 'เขาเริ่มต้นถวายเครื่องเผาบูชาแด่พระเยโฮวาห์ตั้งแต่วันที่หนึ่งของเดือนที่เจ็ด แต่เขายังมิได้วางรากฐานพระวิหารของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 7, 'เขาทั้งหลายจึงให้เงินแก่ช่างสกัดหิน และช่างไม้ และมอบอาหาร เครื่องดื่มและน้ํามันแก่คนไซดอนและคนไทระ เพื่อให้นําไม้สนสีดาร์มาจากเลบานอนไปถึงทะเลถึงเมืองยัฟฟา ตามที่เขาได้รับอนุญาตมาจากไซรัสกษัตริย์แห่งเปอร์เซีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 8, 'ในปีที่สองซึ่งเขามาถึงพระนิเวศแห่งพระเจ้าที่เยรูซาเล็ม ในเดือนที่สอง เศรุบบาเบลบุตรชายเชอัลทิเอล และเยชูอาบุตรชายโยซาดัก ได้ทําการตั้งต้นพร้อมพี่น้องของเขาที่เหลืออยู่ คือบรรดาปุโรหิตและคนเลวีและคนทั้งปวงซึ่งมาจากการเป็นเชลยยังเยรูซาเล็ม เขาได้เลือกตั้งคนเลวี ตั้งแต่อายุยี่สิบปีขึ้นไป เพื่อให้ดูแลการงานของพระนิเวศแห่งพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 9, 'และเยชูอากับบุตรชายและพี่น้องของท่าน กับขัดมีเอลและบุตรชายของเขา คนของยูดาห์ รวมกันควบคุมคนงานในพระนิเวศแห่งพระเจ้า รวมกับบุตรชายเฮนาดัดพร้อมกับบุตรชายและญาติของเขาผู้เป็นคนเลวี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 10, 'และเมื่อช่างก่อได้วางรากฐานของพระวิหารแห่งพระเยโฮวาห์ บรรดาปุโรหิตก็แต่งเครื่องยศออกมาพร้อมกับแตรและคนเลวี คนของอาสาฟพร้อมกับฉาบ ถวายสรรเสริญพระเยโฮวาห์ตามพระราชกําหนดของดาวิดกษัตริย์แห่งอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 11, 'และเขาร้องเพลงตอบกัน สรรเสริญและโมทนาแด่พระเยโฮวาห์ว่า “เพราะพระองค์ประเสริฐ เพราะความเมตตาของพระองค์ดํารงเป็นนิตย์ต่ออิสราเอล” และประชาชนทั้งปวงก็โห่ร้องด้วยเสียงดังเมื่อเขาสรรเสริญพระเยโฮวาห์ เพราะว่ารากฐานของพระนิเวศแห่งพระเยโฮวาห์วางเสร็จแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 12, 'แต่ปุโรหิตและคนเลวีและประมุขของบรรพบุรุษเป็นอันมาก คือคนแก่ผู้ได้เห็นพระวิหารหลังก่อน เมื่อเขาเห็นรากฐานของพระวิหารหลังนี้ได้วางแล้ว ได้ร้องไห้ด้วยเสียงดัง คนเป็นอันมากได้โห่ร้องด้วยความชื่นบาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 13, 'ประชาชนจึงสังเกตไม่ได้ว่าไหนเป็นเสียงโห่ร้องด้วยความชื่นบาน และไหนเป็นเสียงประชาชนร้องไห้ เพราะประชาชนโห่ร้องเสียงดังมาก และเสียงนั้นก็ได้ยินไปไกล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 1, 'เมื่อปฏิปักษ์ของยูดาห์และเบนยามินได้ยินว่า ลูกหลานของพวกที่ถูกกวาดไปเป็นเชลย กําลังสร้างพระวิหารถวายแด่พระเยโฮวาห์พระเจ้าแห่งอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 2, 'เขาทั้งหลายได้เข้ามาหาเศรุบบาเบลและประมุขของบรรพบุรุษและพูดกับเขาว่า “ให้เราสร้างด้วยกันกับท่าน เพราะว่าพวกเราแสวงหาพระเจ้าของท่านอย่างท่านทั้งหลาย และเราได้ถวายสัตวบูชาแด่พระองค์ตั้งแต่วันที่เอสารฮัดโดนกษัตริย์แห่งอัสซีเรียได้นําเรามาที่นี่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 3, 'แต่เศรุบบาเบล เยชูอา และคนอื่นๆที่เป็นพวกประมุขของบรรพบุรุษที่เหลืออยู่ในอิสราเอล พูดกับเขาทั้งหลายว่า “ท่านทั้งหลายไม่มีส่วนกับเราในการสร้างพระนิเวศถวายแด่พระเจ้าของเรา แต่พวกเราจะสร้างแต่ลําพังถวายแด่พระเยโฮวาห์พระเจ้าแห่งอิสราเอล ตามที่กษัตริย์ไซรัสกษัตริย์แห่งเปอร์เซียทรงบัญชาไว้แก่เรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 4, 'แล้วประชาชนแห่งแผ่นดินนั้นได้กระทําให้ประชาชนยูดาห์ท้อถอย และรบกวนพวกเขาในการสร้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 5, 'และได้จ้างที่ปรึกษาไว้ขัดขวางเขาเพื่อมิให้เขาสมหวังตามจุดประสงค์ของเขา ตลอดรัชสมัยของไซรัสกษัตริย์แห่งเปอร์เซีย แม้ถึงรัชกาลของดาริอัสกษัตริย์แห่งเปอร์เซีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 6, 'และในรัชกาลอาหสุเอรัส ต้นรัชกาลของพระองค์ เขาทั้งหลายได้เขียนฟ้องชาวยูดาห์และเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 7, 'และในรัชสมัยของอารทาเซอร์ซีสนั้น บิชลาม มิทเรดาท และทาเบเอล และพวกภาคีทั้งปวงของเขาได้เขียนไปทูลอารทาเซอร์ซีสกษัตริย์แห่งเปอร์เซีย ฎีกานั้นได้เขียนขึ้นเป็นอักขระอารัมแล้วก็แปลเป็นภาษาอารัม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 8, 'เรฮูมผู้บังคับบัญชา และชิมชัยอาลักษณ์ได้เขียนหนังสือปรักปรําเยรูซาเล็มถวายกษัตริย์อารทาเซอร์ซีสดังต่อไปนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 9, 'แล้วเรฮูมผู้บังคับบัญชา ชิมชัยอาลักษณ์ กับภาคีทั้งปวงของท่าน และชาวดินา คนอาฟอาร์เซคา คนทาร์เปลี คนอาฟอาร์ซี คนเอเรก ชาวบาบิโลน ชาวสุสา คนเดฮาวาห์ และคนเอลาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 10, 'และคนประชาชาติอื่นๆ ผู้ซึ่งโอสนัปปาร์ เจ้านายผู้ใหญ่ได้ส่งมาให้ตั้งอยู่ในหัวเมืองสะมาเรีย และในส่วนที่เหลือของมณฑลทางฟากแม่น้ําข้างนี้ เป็นต้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 11, 'และนี่เป็นสําเนาจดหมายที่เขาส่งไปถึงพระองค์ คือถึงกษัตริย์อารทาเซอร์ซีสว่า “ขอกราบทูล ข้าราชการของพระองค์ คือคนของมณฑลฟากแม่น้ําข้างนี้ เป็นต้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 12, 'บัดนี้ขอกษัตริย์ทรงทราบว่า พวกยิวซึ่งมาจากพระองค์มาหาข้าพระองค์นั้นได้ไปยังเยรูซาเล็ม เขากําลังก่อสร้างเมืองที่มักกบฏและชั่วร้ายขึ้นใหม่ เขากําลังจะทํากําแพงเมืองเสร็จและซ่อมแซมรากฐาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 13, 'บัดนี้ขอกษัตริย์ทรงทราบว่า ถ้าเมืองนี้ได้สร้างขึ้นใหม่และกําแพงเมืองเสร็จแล้ว เขาจะไม่ส่งบรรณาการ ค่าธรรมเนียม หรือค่าภาษี และเงินรายได้ของหลวงก็จะขาดตกบกพร่องไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 14, 'เพราะเมื่อข้าพระองค์ทั้งหลายได้รับพระบรมราชูปถัมภ์จากราชวังของกษัตริย์ จึงไม่สมควรที่ข้าพระองค์ทั้งหลายจะเห็นการเสื่อมเกียรติของกษัตริย์ เพราะฉะนั้นข้าพระองค์ทั้งหลายจึงส่งมากราบทูลแก่กษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 15, 'เพื่อว่าจะได้ค้นดูในหนังสือบันทึกของบรรพบุรุษของพระองค์ พระองค์จะพบในหนังสือบันทึกแล้วทราบว่าเมืองนี้เป็นเมืองมักกบฏ เป็นภยันตรายแก่บรรดากษัตริย์และมณฑลทั้งหลาย และได้มีการปลุกปั่นขึ้นจากสมัยเก่าก่อน เพราะเหตุนี้เองเมืองนี้จึงถูกทิ้งร้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 16, 'ข้าพระองค์ทั้งหลายขอกราบทูลให้กษัตริย์ทรงทราบว่า ถ้าเมืองนี้ได้สร้างใหม่เสร็จและกําแพงเมืองก็สําเร็จแล้ว พระองค์จะไม่มีกรรมสิทธิ์ในมณฑลฟากแม่น้ําข้างนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 17, 'กษัตริย์ทรงส่งพระราชสารตอบไปถึงเรฮูมผู้บังคับบัญชา และชิมชัยอาลักษณ์ และภาคีทั้งปวงของเขาผู้อาศัยในสะมาเรีย และในส่วนที่เหลือของมณฑลทางฟากแม่น้ําข้างโน้นว่า “ขอให้อยู่เย็นเป็นสุขเถิด เป็นต้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 18, 'บัดนี้หนังสือที่ท่านส่งไปยังเราได้ให้แปลต่อหน้าเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 19, 'และเราได้ออกคําสั่ง และได้สอบสวนแล้ว เห็นว่าเมืองนี้แต่ก่อนโน้นได้ลุกขึ้นต่อสู้กษัตริย์ และการกบฏ และการปลุกปั่นได้เกิดขึ้นในเมืองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 20, 'เคยมีกษัตริย์ผู้ทรงอํานาจได้ครองเยรูซาเล็ม เป็นผู้ทรงปกครองมณฑลทั้งสิ้นฟากแม่น้ําข้างโน้น ซึ่งเขาถวายบรรณาการ ค่าธรรมเนียมและภาษีให้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 21, 'เพราะฉะนั้นท่านทั้งหลายจงออกคําสั่งว่า ให้คนเหล่านี้หยุดและไม่ต้องสร้างเมืองนี้ใหม่ จนกว่าเราจะออกกฤษฎีกา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 22, 'และขอระวังอย่าหย่อนในเรื่องนี้ ทําไมจะให้ความเสื่อมเสียเกิดขึ้นเป็นภยันตรายต่อกษัตริย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 23, 'แล้วเมื่อได้อ่านสําเนาราชสารของกษัตริย์อารทาเซอร์ซีสต่อหน้าเรฮูม และชิมชัยอาลักษณ์ และภาคีทั้งหลายของท่าน ท่านทั้งหลายก็รีบไปหาพวกยิวที่เยรูซาเล็ม และใช้กําลังและอํานาจกระทําให้เขาหยุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 24, 'งานพระนิเวศแห่งพระเจ้าซึ่งอยู่ในเยรูซาเล็มจึงหยุด งานนั้นได้หยุดจนถึงปีที่สองแห่งรัชกาลดาริอัสกษัตริย์แห่งเปอร์เซีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 1, 'ฝ่ายผู้พยากรณ์คือ ฮักกัยผู้พยากรณ์ และเศคาริยาห์บุตรชายอิดโด ได้พยากรณ์แก่พวกยิวผู้อยู่ในยูดาห์และเยรูซาเล็มในพระนามของพระเจ้าแห่งอิสราเอล คือแก่พวกเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 2, 'แล้วเศรุบบาเบลบุตรชายเชอัลทิเอล และเยชูอาบุตรชายโยซาดัก ได้ลุกขึ้นตั้งต้นสร้างพระนิเวศแห่งพระเจ้าซึ่งอยู่ในเยรูซาเล็มขึ้นใหม่ และผู้พยากรณ์ของพระเจ้าได้อยู่กับท่านช่วยเหลือท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 3, 'ในเวลาเดียวกันนั้นทัทเธนัย ผู้ว่าราชการมณฑลฟากแม่น้ําข้างนี้ และเชธาร์โบเซนัย และคณะของเขาได้มาหาท่าน และพูดกับท่านดังนี้ว่า “ผู้ใดที่ให้กฤษฎีกาแก่ท่าน ให้สร้างพระนิเวศและกําแพงนี้จนสําเร็จ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 4, 'เขาถามท่านอย่างนี้ด้วยว่า “ผู้ที่กําลังสร้างตึกนี้นั้นมีชื่อใครบ้าง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 5, 'แต่พระเนตรของพระเจ้าของเขาทั้งหลายอยู่เหนือพวกผู้ใหญ่ของพวกยิว และเขาก็ยับยั้งเขาทั้งหลายไม่ได้จนกว่าเรื่องนี้จะทราบถึงดาริอัส และมีคําตอบเป็นหนังสือเกี่ยวกับเรื่องนี้มา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 6, 'สําเนาจดหมายซึ่งทัทเธนัยผู้ว่าราชการมณฑลฟากแม่น้ําข้างนี้ และเชธาร์โบเซนัย และคณะของท่านคือคนอาฟอาร์เซคาซึ่งอยู่ในมณฑลฟากแม่น้ําข้างนี้ ส่งไปทูลกษัตริย์ดาริอัส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 7, 'ท่านทั้งหลายได้ส่งหนังสือซึ่งมีข้อความต่อไปนี้ “กราบทูลกษัตริย์ดาริอัส ขอทรงพระเจริญ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 8, 'ขอกษัตริย์ทรงทราบว่าข้าพระองค์ทั้งหลายไปยังมณฑลยูดาห์ ถึงพระนิเวศของพระเจ้าใหญ่ยิ่ง ซึ่งกําลังสร้างขึ้นด้วยหินใหญ่ และวางไม้ไว้บนผนัง งานนี้ได้ดําเนินไปอย่างขยันขันแข็งและเจริญขึ้นในมือของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 9, 'แล้วข้าพระองค์ทั้งหลายได้ถามพวกผู้ใหญ่เหล่านั้นว่า ‘ผู้ใดที่ให้กฤษฎีกาแก่ท่านให้สร้างพระนิเวศและทํากําแพงนี้จนสําเร็จ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 10, 'ข้าพระองค์ทั้งหลายได้ถามชื่อของเขาด้วย เพื่อกราบทูลให้พระองค์ทรงทราบ เพื่อข้าพระองค์จะได้เขียนชื่อบุคคลเหล่านั้นที่เป็นหัวหน้าของเขาลงไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 11, 'และนี่เป็นคําตอบของเขาแก่ข้าพระองค์ ‘เราเป็นผู้รับใช้ของพระเจ้าแห่งฟ้าสวรรค์และแผ่นดินโลก และเรากําลังสร้างพระนิเวศซึ่งได้สร้างมาหลายปีแล้วขึ้นใหม่ ซึ่งกษัตริย์ผู้ยิ่งใหญ่ของอิสราเอลได้ทรงสร้างให้สําเร็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 12, 'แต่เพราะว่าบรรพบุรุษของเราได้กระทําให้พระเจ้าแห่งฟ้าสวรรค์ทรงกริ้ว พระองค์ทรงมอบท่านเหล่านั้นไว้ในพระหัตถ์ของเนบูคัดเนสซาร์กษัตริย์แห่งบาบิโลน คนเคลเดียผู้ทรงทําลายพระนิเวศนี้ และทรงกวาดเอาประชาชนไปยังบาบิโลน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 13, 'ถึงอย่างไรก็ดีในปีต้นแห่งรัชกาลไซรัสกษัตริย์แห่งบาบิโลน กษัตริย์ไซรัสได้ทรงออกกฤษฎีกาให้สร้างพระนิเวศหลังนี้ของพระเจ้าขึ้นใหม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 14, 'และเครื่องใช้ทองคําและเงินของพระนิเวศของพระเจ้า ซึ่งเนบูคัดเนสซาร์ได้ทรงกวาดไปจากพระวิหารซึ่งอยู่ในเยรูซาเล็มนั้น และทรงนําไปยังวิหารของบาบิโลน สิ่งเหล่านี้กษัตริย์ไซรัสทรงนําออกมาจากวิหารของบาบิโลน และทรงมอบไว้กับคนหนึ่งชื่อเชชบัสซาร์ ผู้ซึ่งพระองค์ทรงตั้งให้เป็นผู้ว่าราชการเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 15, 'และพระองค์ตรัสกับท่านดังนี้ว่า “จงรับเครื่องใช้เหล่านี้ไปเก็บไว้ในพระวิหารซึ่งอยู่ในเยรูซาเล็ม และจงสร้างพระนิเวศของพระเจ้าขึ้นใหม่ในที่เดิมนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 16, 'แล้วเชชบัสซาร์คนนี้ได้มาวางรากฐานพระนิเวศของพระเจ้าซึ่งอยู่ในเยรูซาเล็ม และตั้งแต่เวลานั้นจนบัดนี้ก็กําลังสร้างอยู่และยังไม่สําเร็จ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 17, 'เพราะฉะนั้นบัดนี้ถ้ากษัตริย์ทรงเห็นดีก็ขอทรงให้ค้นดูในคลังราชทรัพย์ที่อยู่ในบาบิโลน เพื่อดูว่ากษัตริย์ไซรัสทรงออกกฤษฎีกาให้สร้างพระนิเวศหลังนี้ของพระเจ้าขึ้นใหม่ในเยรูซาเล็มหรือไม่ และขอกษัตริย์รับสั่งแก่ข้าพระองค์ทั้งหลายตามพอพระทัยของพระองค์ในเรื่องนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 1, 'แล้วกษัตริย์ดาริอัสทรงออกกฤษฎีกาและทรงให้ค้นดูในหอเก็บหนังสือซึ่งเป็นที่ราชทรัพย์สะสมไว้ในบาบิโลน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 2, 'และได้มีการพบหนังสือม้วนหนึ่งที่อาคเมตาห์ในพระราชวังซึ่งอยู่ในมณฑลมีเดีย และมีข้อความเขียนอยู่ในหนังสือม้วนนั้นดังต่อไปนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 3, '“ในปีต้นแห่งรัชกาลกษัตริย์ไซรัส กษัตริย์ไซรัสทรงออกกฤษฎีกาว่า เรื่องพระนิเวศของพระเจ้าที่เยรูซาเล็มว่า ‘ให้สร้างพระนิเวศนั้นขึ้นใหม่ คือที่ซึ่งเขานําเครื่องสัตวบูชามาถวาย ให้ลงรากมั่นคง ให้พระนิเวศสูงหกสิบศอกและกว้างหกสิบศอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 4, 'ให้ก่อด้วยหินใหญ่สามชั้นและไม้ใหม่ชั้นหนึ่ง และให้เสียเงินค่าก่อสร้างจากพระคลังหลวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 5, 'และเครื่องใช้ทองคําและเงินของพระนิเวศแห่งพระเจ้า ซึ่งเนบูคัดเนสซาร์ทรงนําออกมาจากพระวิหารที่อยู่ในเยรูซาเล็มนํามาไว้ที่บาบิโลนนั้น ให้คืนเสียและให้นํากลับไปยังพระวิหารซึ่งอยู่ในเยรูซาเล็ม ไว้ตามที่ของสิ่งนั้นๆ ท่านจงเก็บไว้ในพระนิเวศแห่งพระเจ้า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 6, 'เพราะฉะนั้นบัดนี้ทัทเธนัยผู้ว่าราชการมณฑลฟากแม่น้ําข้างโน้น เชธาร์โบเซนัย และภาคีของท่าน คือคนอาฟอาร์เซคาซึ่งอยู่ในมณฑลฟากแม่น้ําข้างโน้น จงไปเสียให้ห่างเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 7, 'จงให้งานสร้างพระนิเวศของพระเจ้าดําเนินไปเถิด ให้ผู้ว่าราชการของพวกยิว และบรรดาพวกผู้ใหญ่ของพวกยิวสร้างพระนิเวศของพระเจ้านี้ในที่เดิมขึ้นใหม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 8, 'ยิ่งกว่านั้นอีก เราออกกฤษฎีกาเกี่ยวกับสิ่งที่ท่านพึงกระทําเพื่อพวกผู้ใหญ่ของพวกยิวในการสร้างพระนิเวศของพระเจ้า ให้ชําระเงินค่าก่อสร้างแก่คนเหล่านี้เต็ม เพื่อพวกเขาไม่ถูกหยุดยั้ง เอาเงินจากราชทรัพย์ คือบรรณาการของมณฑลฟากแม่น้ําข้างโน้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 9, 'และสิ่งใดๆที่เขาต้องการ เช่น วัวหนุ่ม แกะผู้ หรือแกะสําหรับเครื่องเผาบูชาถวายแด่พระเจ้าแห่งฟ้าสวรรค์ ทั้งข้าวสาลี เกลือ น้ําองุ่น หรือน้ํามัน ตามที่ปุโรหิตเยรูซาเล็มกําหนดไว้ ให้มอบแก่เขาเป็นวันๆไปอย่าได้ขาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 10, 'เพื่อเขาจะได้ถวายเครื่องสัตวบูชา อันเป็นกลิ่นที่พอพระทัยแด่พระเจ้าแห่งฟ้าสวรรค์ และให้อธิษฐานเพื่อชีวิตของกษัตริย์และโอรสของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 11, 'และเราออกกฤษฎีกาว่า ถ้าผู้ใดเปลี่ยนแปลงประกาศิตนี้ ก็ให้ดึงไม้ใหญ่อันหนึ่งออกเสียจากเรือนของเขา และให้เขาถูกตรึงไว้บนไม้นั้น และให้เรือนของเขาเป็นกองขยะเพราะเรื่องนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 12, 'และขอพระเจ้าผู้ทรงกระทําให้พระนามของพระองค์สถิตที่นั่นทรงคว่ํากษัตริย์ทั้งหมดหรือประชาชาติใดๆ ที่ยื่นมือออกเปลี่ยนแปลงข้อนี้ คือเพื่อทําลายพระนิเวศของพระเจ้าซึ่งอยู่ในเยรูซาเล็ม ข้าพเจ้าดาริอัสออกกฤษฎีกานี้ ขอให้กระทํากันด้วยความขยันขันแข็ง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 13, 'แล้วทัทเธนัยผู้ว่าราชการมณฑลฟากแม่น้ําข้างนี้ เชธาร์โบเซนัย และภาคีของท่านทั้งสองก็ได้กระทําทุกอย่างด้วยความขยันขันแข็งตามพระดํารัสซึ่งกษัตริย์ดาริอัสได้ทรงบัญชามา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 14, 'และพวกผู้ใหญ่ของพวกยิวก็ได้ทําการก่อสร้างให้ก้าวหน้าไป ตามการพยากรณ์ของฮักกัยผู้พยากรณ์ และเศคาริยาห์บุตรชายอิดโด เขาสร้างเสร็จตามพระบัญชาแห่งพระเจ้าของอิสราเอล และตามกฤษฎีกาของไซรัสและดาริอัสและอารทาเซอร์ซีสกษัตริย์แห่งเปอร์เซีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 15, 'และพระนิเวศนี้ได้สําเร็จในวันที่สามของเดือนอาดาร์ ในปีที่หกแห่งรัชกาลกษัตริย์ดาริอัส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 16, 'และชนชาติอิสราเอล บรรดาปุโรหิตและคนเลวี และลูกหลานของพวกที่ถูกกวาดไปเป็นเชลยที่เหลืออยู่ ได้ฉลองการมอบถวายพระนิเวศแห่งพระเจ้านี้ด้วยความชื่นบาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 17, 'ณ การถวายพระนิเวศแห่งพระเจ้านี้ เขาทั้งหลายได้ถวายวัวผู้หนึ่งร้อยตัว แกะผู้สองร้อยตัว ลูกแกะสี่ร้อยตัว และส่วนเครื่องบูชาไถ่บาปสําหรับอิสราเอลทั้งปวงนั้นมีแพะผู้สิบสองตัว ตามจํานวนตระกูลของอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 18, 'และเขาตั้งปุโรหิตไว้ในกองของเขาทั้งหลาย และคนเลวีในเวรของเขา สําหรับการปรนนิบัติพระเจ้าที่เยรูซาเล็ม ตามที่บันทึกไว้ในหนังสือของโมเสส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 19, 'ในวันที่สิบสี่ของเดือนที่หนึ่งลูกหลานของพวกที่ถูกกวาดไปเป็นเชลยได้ถือเทศกาลปัสกา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 20, 'เพราะบรรดาปุโรหิตและคนเลวีได้ชําระตนทุกคน เขาบริสุทธิ์หมดด้วยกัน เขาจึงฆ่าแกะปัสกาสําหรับลูกหลานของพวกที่ถูกกวาดไปเป็นเชลยทั้งหมด สําหรับพวกพี่น้องที่เป็นปุโรหิต และสําหรับตัวเขาทั้งหลายเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 21, 'ประชาชนอิสราเอลผู้ได้กลับมาจากการถูกกวาดไปเป็นเชลย และทุกคนที่สมทบกับเขาและแยกตัวออกจากการมลทินของบรรดาประชาชาติแห่งแผ่นดินนั้น เพื่อจะแสวงหาพระเยโฮวาห์พระเจ้าแห่งอิสราเอลก็ได้รับประทาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 22, 'และเขาได้ถือเทศกาลกินขนมปังไร้เชื้อเจ็ดวันด้วยความชื่นบาน เพราะว่าพระเยโฮวาห์ได้ทรงกระทําให้เขาชื่นบาน และทรงหันพระทัยของกษัตริย์อัสซีเรียมาหาเขา เพื่อเสริมกําลังมือของเขาในการสร้างพระนิเวศของพระเจ้า พระเจ้าแห่งอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 1, 'ภายหลังเหตุการณ์เหล่านี้ในรัชกาลของอารทาเซอร์ซีส กษัตริย์แห่งเปอร์เซีย เอสราบุตรชายเสไรอาห์ ผู้เป็นบุตรชายอาซาริยาห์ ผู้เป็นบุตรชายฮิลคียาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 2, 'ผู้เป็นบุตรชายชัลลูม ผู้เป็นบุตรชายศาโดก ผู้เป็นบุตรชายอาหิทูบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 3, 'ผู้เป็นบุตรชายอามาริยาห์ ผู้เป็นบุตรชายอาซาริยาห์ ผู้เป็นบุตรชายเมราโยท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 4, 'ผู้เป็นบุตรชายเศ-ราหิยาห์ ผู้เป็นบุตรชายอุสซี ผู้เป็นบุตรชายบุคคี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 5, 'ผู้เป็นบุตรชายอาบีชูวา ผู้เป็นบุตรชายฟีเนหัส ผู้เป็นบุตรชายเอเลอาซาร์ ผู้เป็นบุตรชายอาโรนปุโรหิตใหญ่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 6, 'เอสราคนนี้ได้ขึ้นไปจากบาบิโลน ท่านเป็นธรรมาจารย์ชํานาญในเรื่องพระราชบัญญัติของโมเสส ซึ่งพระเยโฮวาห์พระเจ้าแห่งอิสราเอลประทานให้ และกษัตริย์ประทานทุกอย่างที่ท่านทูลขอ เพราะว่าพระหัตถ์ของพระเยโฮวาห์พระเจ้าของท่านอยู่กับท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 7, 'มีบางคนในคนอิสราเอลและในบรรดาปุโรหิต บรรดาคนเลวี บรรดานักร้อง และคนเฝ้าประตู และคนใช้ประจําพระวิหาร ได้ขึ้นไปด้วย ถึงเยรูซาเล็มในปีที่เจ็ดแห่งรัชกาลกษัตริย์อารทาเซอร์ซีส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 8, 'และท่านมาถึงเยรูซาเล็มในเดือนที่ห้า ซึ่งเป็นปีที่เจ็ดของกษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 9, 'เพราะในวันที่หนึ่งของเดือนที่หนึ่งท่านได้เริ่มขึ้นไปจากบาบิโลน และในวันที่หนึ่งของเดือนที่ห้าท่านมายังเยรูซาเล็ม เพราะว่าพระหัตถ์ประเสริฐของพระเจ้าของท่านอยู่กับท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 10, 'เพราะเอสราได้ตั้งใจของท่านที่จะแสวงหาพระราชบัญญัติของพระเยโฮวาห์ และกระทําตาม และสอนกฎเกณฑ์และคําตัดสินต่างๆในอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 11, 'ต่อไปนี้เป็นสําเนาจดหมายซึ่งกษัตริย์อารทาเซอร์ซีสพระราชทานแก่เอสราปุโรหิตผู้เป็นธรรมาจารย์ ผู้เป็นธรรมาจารย์แห่งเรื่องราวของพระบัญญัติของพระเยโฮวาห์และกฎเกณฑ์ของพระองค์เพื่ออิสราเอลว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 12, '“อารทาเซอร์ซีส พระมหากษัตริย์เหนือกษัตริย์ทั้งหลาย ถึงเอสราปุโรหิต ธรรมาจารย์ของพระราชบัญญัติแห่งพระเจ้าของฟ้าสวรรค์ ขอให้อยู่เย็นเป็นสุขอย่างสมบูรณ์เถิด เป็นต้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 13, 'บัดนี้เราออกกฤษฎีกาว่า ประชาชนอิสราเอลผู้หนึ่งผู้ใด หรือปุโรหิตของเขาทั้งหลาย หรือคนเลวีในราชอาณาจักรของเรา ผู้ซึ่งสมัครใจที่จะไปยังเยรูซาเล็ม ก็ให้ไปกับเจ้าได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 14, 'เพราะกษัตริย์และที่ปรึกษาทั้งเจ็ดได้ใช้เจ้าไป ให้ถามถึงยูดาห์และเยรูซาเล็ม ตามพระราชบัญญัติของพระเจ้าของเจ้าซึ่งอยู่ในมือเจ้านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 15, 'และให้นําเงินและทองคําซึ่งกษัตริย์และที่ปรึกษาของพระองค์สมัครใจถวายแด่พระเจ้าแห่งอิสราเอล ผู้ประทับในเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 16, 'พร้อมทั้งเงินและทองคําทั้งสิ้นซึ่งเจ้าจะหาได้ทั่วไปในมณฑลบาบิโลน พร้อมกับของถวายด้วยใจสมัครของประชาชนและปุโรหิต เต็มใจถวายแด่พระนิเวศของพระเจ้าของเขา ซึ่งอยู่ในเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 17, 'แล้วด้วยเงินนี้เจ้าจงขยันขันแข็งซื้อวัวผู้ แกะผู้และลูกแกะ กับธัญญบูชาคู่กัน และเครื่องดื่มบูชาคู่กัน และเจ้าจงถวายสิ่งเหล่านี้บนแท่นบูชาของพระนิเวศแห่งพระเจ้าของเจ้าซึ่งอยู่ในเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 18, 'ส่วนเงินและทองคําที่เหลืออยู่นั้นเจ้าและพี่น้องของเจ้าเห็นดีที่จะทําประการใด ก็จงกระทําเถิด ตามน้ําพระทัยของพระเจ้าของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 19, 'และเครื่องใช้ซึ่งได้มอบให้เจ้าสําหรับการปรนนิบัติในพระนิเวศของพระเจ้าของเจ้า เจ้าจงมอบถวายไว้ต่อพระพักตร์พระเจ้าแห่งเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 20, 'และสิ่งใดๆซึ่งยังต้องการสําหรับพระนิเวศของพระเจ้าของเจ้าซึ่งเจ้าจะต้องจัดหานั้น เจ้าจงจัดหาด้วยเงินพระคลังของกษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 21, 'และเรา คือกษัตริย์อารทาเซอร์ซีส ได้ออกกฤษฎีกาไปยังบรรดานายคลังในมณฑลฟากแม่น้ําข้างโน้นว่า สิ่งใดๆที่เอสราปุโรหิตธรรมาจารย์ของพระราชบัญญัติแห่งพระเจ้าของฟ้าสวรรค์ต้องการจากท่าน จงกระทําให้เขาด้วยความขยันขันแข็ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 22, 'ถึงจํานวนเงินหนึ่งร้อยตะลันต์ และข้าวสาลีถึงหนึ่งร้อยโคระ น้ําองุ่นหนึ่งร้อยบัท น้ํามันหนึ่งร้อยบัท และเกลือไม่จํากัดจํานวนว่าเท่าไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 23, 'สิ่งใดที่พระเจ้าแห่งฟ้าสวรรค์ทรงบัญชา ก็จงกระทําให้อย่างเต็มขนาดสําหรับพระนิเวศของพระเจ้าแห่งฟ้าสวรรค์ เกลือกว่าพระพิโรธของพระองค์จะมีต่อดินแดนของกษัตริย์และโอรสของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 24, 'เราขอแจ้งแก่ท่านทั้งหลายด้วยว่า ไม่เป็นการถูกต้องตามกฎหมายที่จะเอาบรรณาการ ค่าธรรมเนียม หรือภาษีจากคนหนึ่งคนใดในบรรดาปุโรหิต คนเลวี นักร้อง คนเฝ้าประตู คนใช้ประจําพระวิหาร หรือผู้รับใช้อื่นๆของพระนิเวศของพระเจ้านี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 25, 'ส่วนเจ้า เอสรา ตามพระสติปัญญาแห่งพระเจ้าของเจ้าอันอยู่ในมือของเจ้า จงแต่งตั้งพนักงานผู้ปกครองและผู้พิพากษา ให้พิพากษาประชาชนทั้งปวงในมณฑลฟากแม่น้ําข้างโน้น คือทุกคนที่รู้บรรดาพระราชบัญญัติของพระเจ้าของเจ้า และคนเหล่านั้นที่ไม่รู้ เจ้าทั้งหลายจะต้องสอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 26, 'ผู้ใดที่ไม่เชื่อฟังพระราชบัญญัติของพระเจ้าของเจ้า และกฎหมายของกษัตริย์ ก็ให้พิพากษาลงโทษเขาอย่างเคร่งครัด จะเป็นโทษถึงตาย หรือถึงเนรเทศ หรือถึงริบทรัพย์ของเขา หรือถึงจําขังก็ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 27, 'สาธุการแด่พระเยโฮวาห์พระเจ้าแห่งบรรพบุรุษของเรา ผู้ทรงดลพระทัยของกษัตริย์ ให้เสริมความงามแก่พระนิเวศของพระเยโฮวาห์ซึ่งอยู่ในเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 28, 'และทรงบันดาลให้ข้าพเจ้ามีความเมตตาต่อพระพักตร์กษัตริย์ และที่ปรึกษาของพระองค์ และต่อหน้าเจ้านายผู้ทรงอํานาจของกษัตริย์ และข้าพเจ้าก็มีใจกล้าขึ้น เพราะพระหัตถ์ของพระเยโฮวาห์พระเจ้าของข้าพเจ้าอยู่กับข้าพเจ้า และข้าพเจ้าได้รวบรวมบุคคลชั้นผู้นําจากอิสราเอลขึ้นไปกับข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 1, 'ต่อไปนี้เป็นประมุขของบรรพบุรุษของเขาทั้งหลาย และนี่เป็นสํามะโนครัวเชื้อสายของบรรดาผู้ที่ขึ้นไปกับข้าพเจ้าจากบาบิโลน ในรัชกาลกษัตริย์อารทาเซอร์ซีส คือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 2, 'จากคนฟีเนหัสมี เกอร์โชม จากคนอิธามาร์มี ดาเนียล จากคนดาวิดมี ฮัทธัช');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 3, 'จากคนเชคานิยาห์ จากคนปาโรชมี เศคาริยาห์ พร้อมกับท่านมีผู้ชายผู้ขึ้นทะเบียนไว้หนึ่งร้อยห้าสิบคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 4, 'จากคนปาหัทโมอับมี เอลีโอนัย บุตรชายเศ-ราหิยาห์ พร้อมกับท่านมีผู้ชายสองร้อยคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 5, 'จากคนเชคานิยาห์มี บุตรชายของยาฮาซีเอล พร้อมกับท่านมีผู้ชายสามร้อยคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 6, 'จากคนอาดีนมี เอเบด บุตรชายโยนาธาน พร้อมกับท่านมีผู้ชายห้าสิบคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 7, 'จากคนเอลามมี เยชายาห์ บุตรชายอาธาลิยาห์ พร้อมกับท่านมีผู้ชายเจ็ดสิบคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 8, 'จากคนเชฟาทิยาห์มี เศบาดิยาห์ บุตรชายมีคาเอล พร้อมกับท่านมีผู้ชายแปดสิบคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 9, 'จากคนโยอาบมี โอบาดีห์ บุตรชายเยฮีเอล พร้อมกับท่านมีผู้ชายสองร้อยสิบแปดคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 10, 'จากคนเชโลมิทมี บุตรชายของโยสิฟียาห์ พร้อมกับท่านมีผู้ชายหนึ่งร้อยหกสิบคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 11, 'จากคนเบบัยมี เศคาริยาห์ บุตรชายเบบัย พร้อมกับท่านมีผู้ชายยี่สิบแปดคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 12, 'จากคนอัสกาดมี โยฮานัน บุตรชายฮักคาทาน พร้อมกับท่านมีผู้ชายหนึ่งร้อยสิบคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 13, 'จากคนอาโดนีคัมมีผู้ที่มาทีหลัง นี่เป็นชื่อของเขาคือ เอลีเฟเลท เยอีเอลและเชไมอาห์ พร้อมกับพวกเขามีผู้ชายหกสิบคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 14, 'จากคนบิกวัยมี อุธัยและศับบูด พร้อมกับเขาทั้งสองมีผู้ชายเจ็ดสิบคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 15, 'ข้าพเจ้าได้รวบรวมเขาทั้งหลายเข้ามายังแม่น้ําที่ไหลไปสู่อาหะวา เราตั้งค่ายอยู่ที่นั่นสามวัน เมื่อข้าพเจ้าสํารวจดูประชาชนและปุโรหิต ข้าพเจ้าไม่เห็นลูกหลานของเลวีที่นั่นเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 16, 'แล้วข้าพเจ้าจึงให้ไปเรียกเอลีเยเซอร์ อารีเอล เชไมอาห์ เอลนาธัน ยารีบ เอลนาธัน นาธัน เศคาริยาห์ และเมชุลลาม บุคคลชั้นหัวหน้า และให้หาโยยาริบ และเอลนาธัน ผู้เป็นคนมีความเข้าใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 17, 'และส่งเขาด้วยคําสั่งไปยังท่านอิดโด บุคคลชั้นหัวหน้ายังสถานที่ที่ชื่อคาสิเฟีย คือให้บอกท่านอิดโดและพี่น้องของท่านผู้เป็นคนใช้ประจําพระวิหารที่สถานที่ที่ชื่อคาสิเฟียว่า ขอส่งผู้ปรนนิบัติสําหรับพระนิเวศของพระเจ้าของเรามายังเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 18, 'และโดยพระหัตถ์อันทรงพระคุณของพระเจ้าของเราอยู่กับเรา เขาได้นําคนที่มีความสุขุมมาให้เรา เป็นลูกหลานของมาห์ลีบุตรชายเลวี ผู้เป็นบุตรชายอิสราเอล ชื่อเชเรบิยาห์ กับบุตรชายและญาติพี่น้อง รวมสิบแปดคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 19, 'ทั้งฮาชาบิยาห์และเยชายาห์ ลูกหลานของเมรารีกับญาติพี่น้องและบุตรชายของเขารวมยี่สิบคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 20, 'และคนใช้ประจําพระวิหาร ซึ่งดาวิดและข้าราชการของพระองค์ได้จัดตั้งขึ้นไว้เพื่อปรนนิบัติคนเลวี มีคนใช้ประจําพระวิหารสองร้อยยี่สิบคน บุคคลเหล่านี้ทั้งสิ้นมีชื่อระบุไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 21, 'แล้วข้าพเจ้าก็ประกาศให้ถืออดอาหารที่นั่น คือที่แม่น้ําอาหะวา เพื่อเราทั้งหลายจะได้ถ่อมตัวลงต่อพระพักตร์พระเจ้าของเรา เพื่อจะทูลขอหนทางอันถูกต้องจากพระองค์ สําหรับเรา ลูกหลานของเรา และข้าวของทั้งสิ้นของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 22, 'เพราะข้าพเจ้าละอายที่จะทูลขอกองทหารและพลม้าจากกษัตริย์เพื่อช่วยเราสู้ศัตรูตามทางของเรา ในเมื่อเราได้กราบทูลกษัตริย์แล้วว่า “พระหัตถ์ของพระเจ้าของเราอยู่กับบรรดาผู้ที่แสวงหาพระองค์ให้ยังผลดี แต่ฤทธานุภาพและพระพิโรธของพระองค์ต่อสู้คนเหล่านั้นที่ละทิ้งพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 23, 'เราจึงอดอาหารและวิงวอนพระเจ้าของเราเพื่อเรื่องนี้ และพระองค์ทรงฟังเสียงร้องทูลของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 24, 'และข้าพเจ้าได้แยกปุโรหิตใหญ่ออกสิบสองคนคือ เชเรบิยาห์ ฮาชาบิยาห์ และพี่น้องสิบคนของเขาที่อยู่กับเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 25, 'และข้าพเจ้าได้ชั่งเงิน และทองคํา และเครื่องใช้ กับเครื่องบูชาสําหรับพระนิเวศของพระเจ้าของเรา มอบให้เขาทั้งหลายซึ่งกษัตริย์และที่ปรึกษาและเจ้านายของพระองค์ และคนอิสราเอลทั้งปวงที่นั่นได้ถวายไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 26, 'ข้าพเจ้าได้ชั่งใส่มือของเขาเป็นเงินหกร้อยห้าสิบตะลันต์ และเครื่องใช้ที่ทําด้วยเงินมีค่าหนึ่งร้อยตะลันต์ และทองคําร้อยตะลันต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 27, 'ชามทองคํายี่สิบใบมีค่าหนึ่งพันดาริค และเครื่องใช้ทองแดงเนื้อละเอียดสุกใสสองใบมีค่าเท่ากับทองคํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 28, 'และข้าพเจ้าบอกเขาว่า “ท่านทั้งหลายบริสุทธิ์ต่อพระเยโฮวาห์ และเครื่องใช้ก็บริสุทธิ์ และเงินกับทองคําเป็นของถวายด้วยใจสมัครแด่พระเยโฮวาห์พระเจ้าแห่งบรรพบุรุษของท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 29, 'จงเฝ้าดูแลไว้จนกว่าท่านชั่งสิ่งเหล่านั้นต่อหน้าพวกปุโรหิตใหญ่และคนเลวี และประมุขของบรรพบุรุษอิสราเอลในเยรูซาเล็ม ภายในห้องพระนิเวศของพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 30, 'บรรดาปุโรหิตและคนเลวีจึงรับเงินและทองคําที่ได้ชั่ง และเครื่องใช้ เพื่อนําไปยังเยรูซาเล็ม ยังพระนิเวศของพระเจ้าของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 31, 'และเราก็ออกจากแม่น้ําอาหะวาในวันที่สิบสองของเดือนต้น เพื่อไปยังเยรูซาเล็ม และพระหัตถ์ของพระเจ้าของเราอยู่กับเรา และพระองค์ทรงช่วยเราให้พ้นจากมือของศัตรูและจากพวกซุ่มคอยอยู่ตามทาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 32, 'เรามาถึงเยรูซาเล็มและพักอยู่ที่นั่นสามวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 33, 'ในวันที่สี่ภายในพระนิเวศของพระเจ้าของเรา ก็ชั่งเงิน ทองคําและเครื่องใช้ใส่มือของเมเรโมทปุโรหิต บุตรชายอุรีอาห์ และคนที่อยู่กับเขาคือเอเลอาซาร์บุตรชายฟีเนหัส และคนที่อยู่กับเขาทั้งหลายคือ โยซาบาด บุตรชายเยชูอา และโนอัดยาห์บุตรชายบินนุย คนเลวี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 34, 'เขาชั่งและนับทั้งหมดและบันทึกน้ําหนักของทุกสิ่งไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 35, 'บรรดาลูกหลานของพวกที่ถูกกวาดไปเป็นเชลย ซึ่งมาจากการเป็นเชลย ได้ถวายเครื่องเผาบูชาแด่พระเจ้าแห่งอิสราเอล มีวัวผู้สิบสองตัวสําหรับพวกอิสราเอลทั้งปวง แกะผู้เก้าสิบหกตัว ลูกแกะเจ็ดสิบเจ็ดตัว และแพะผู้สิบสองตัวเป็นเครื่องบูชาไถ่บาป ทั้งสิ้นนี้เป็นเครื่องเผาบูชาถวายพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 36, 'เขาทั้งหลายได้มอบพระราชโองการให้แก่สมุหเทศาภิบาลของกษัตริย์ และแก่ผู้ว่าราชการมณฑลฟากแม่น้ําข้างนี้ และท่านเหล่านี้ได้ช่วยเหลือประชาชนและพระนิเวศของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 1, 'เมื่อเหตุการณ์เหล่านี้ได้เสร็จสิ้นลงแล้ว พวกเจ้านายก็เข้ามาหาข้าพเจ้า กล่าวว่า “ประชาชนแห่งอิสราเอล และพวกปุโรหิตกับคนเลวีมิได้แยกตนเองออกจากชนชาติทั้งหลายแห่งแผ่นดินเหล่านั้น โดยได้ประพฤติตามการกระทําอันน่าสะอิดสะเอียนของเขา คือออกจากคนคานาอัน คนฮิตไทต์ คนเปริสซี คนเยบุส คนอัมโมน คนโมอับ คนอียิปต์ และคนอาโมไรต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 2, 'เพราะเขารับบุตรสาวของชนเหล่านี้เป็นภรรยาของเขาเอง และของบุตรชายของเขา ดังนั้นเชื้อสายบริสุทธิ์ได้ปะปนกับชนชาติทั้งหลายของแผ่นดินเหล่านั้น นี่แหละในการละเมิดข้อนี้ มือของเจ้าหน้าที่ชั้นหัวหน้าและผู้ครองเมืองได้เด่นที่สุด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 3, 'เมื่อข้าพเจ้าได้ยินอย่างนี้ ข้าพเจ้าก็ฉีกเสื้อของข้าพเจ้าทั้งเสื้อคลุมของข้าพเจ้า และทึ้งผมออกจากศีรษะของข้าพเจ้าและทึ้งหนวดเครา และนั่งลงตะลึงอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 4, 'แล้วบรรดาคนที่สั่นสะท้านไปด้วยพระวจนะของพระเจ้าแห่งอิสราเอล เหตุด้วยการละเมิดของพวกที่ถูกกวาดไปเป็นเชลยนั้น ได้มาประชุมต่อหน้าข้าพเจ้าเมื่อข้าพเจ้านั่งตะลึงอยู่จนถึงเวลาถวายเครื่องสักการบูชาตอนเย็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 5, 'ณ เวลาสักการบูชาตอนเย็นนั้นข้าพเจ้าได้ลุกขึ้นจากการถ่อมตัว มีเครื่องแต่งกายและเสื้อคลุมของข้าพเจ้าฉีกขาด และข้าพเจ้าก็คุกเข่าลงและชูมือขึ้นต่อพระเยโฮวาห์พระเจ้าของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 6, 'และข้าพเจ้าทูลว่า “โอ ข้าแต่พระเจ้าของข้าพระองค์ ข้าพระองค์ละอายขวยเขินที่จะเงยหน้าหาพระองค์ พระเจ้าของข้าพระองค์ เพราะว่าความชั่วช้าของข้าพระองค์ทั้งหลายขึ้นสูงกว่าศีรษะของข้าพระองค์ และการละเมิดของข้าพระองค์ทั้งหลายกองขึ้นไปถึงฟ้าสวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 7, 'ข้าพระองค์ทั้งหลายมีการละเมิดยิ่งใหญ่ตั้งแต่สมัยบรรพบุรุษของข้าพระองค์ทั้งหลายจนถึงทุกวันนี้ และเพราะความชั่วช้าของข้าพระองค์ทั้งหลาย ข้าพระองค์ทั้งหลาย ทั้งบรรดากษัตริย์ของข้าพระองค์ และบรรดาปุโรหิตของข้าพระองค์ได้ถูกมอบไว้ในมือของบรรดากษัตริย์แห่งแผ่นดินเหล่านั้น ให้แก่ดาบ แก่การเป็นเชลย แก่การปล้น และแก่การขายหน้าอย่างที่สุด อย่างทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 8, 'แต่บัดนี้พระเยโฮวาห์พระเจ้าของข้าพระองค์ทั้งหลายทรงสําแดงพระกรุณา พอพระทัยชั่วครู่หนึ่งสั้นๆ และได้ทรงประทานให้ข้าพระองค์ทั้งหลายมีคนที่เหลืออยู่และมีที่ยึดมั่นในที่บริสุทธิ์ของพระองค์ เพื่อว่าพระเจ้าของข้าพระองค์จะได้ทรงให้ตาของข้าพระองค์ทั้งหลายแจ่มขึ้น และทรงประสาทความฟื้นคืนมาเล็กน้อยจากการเป็นทาสของข้าพระองค์ทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 9, 'เพราะว่าข้าพระองค์ทั้งหลายเป็นทาส แต่พระเจ้าของข้าพระองค์มิได้ทรงละทิ้งข้าพระองค์ไว้ในความเป็นทาส แต่ทรงบันดาลให้ข้าพระองค์ทั้งหลายได้รับความเมตตาในสายพระเนตรกษัตริย์ทั้งหลายแห่งเปอร์เซีย ทรงให้ข้าพระองค์ทั้งหลายมีการฟื้นฟูขึ้น เพื่อจะตั้งพระนิเวศของพระเจ้าของข้าพระองค์ทั้งหลายขึ้นไว้ เพื่อจะซ่อมแซมสิ่งที่ปรักหักพังในพระนิเวศ เพื่อจะประทานกําแพงแก่ข้าพระองค์ทั้งหลายในยูดาห์และในเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 10, 'และบัดนี้ โอ ข้าแต่พระเจ้าของข้าพระองค์ทั้งหลาย ต่อจากนี้ข้าพระองค์จะทูลอะไรอีก เพราะข้าพระองค์ทั้งหลายได้ละทิ้งพระบัญญัติของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 11, 'ซึ่งพระองค์ได้ทรงบัญชาไว้โดยผู้พยากรณ์ผู้รับใช้ของพระองค์ว่า ‘แผ่นดินซึ่งเจ้ากําลังเข้าไปเพื่อยึดเป็นกรรมสิทธิ์นั้น เป็นแผ่นดินมลทินด้วยความโสโครกของชนชาติทั้งหลายในแผ่นดินเหล่านั้น ด้วยการกระทําอันน่าสะอิดสะเอียนของเขา ซึ่งเต็มไปหมดตั้งแต่ปลายข้างนี้ถึงปลายข้างโน้น ด้วยความมลทินของเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 12, 'เพราะฉะนั้นบัดนี้ อย่ามอบพวกบุตรสาวของเจ้าแก่พวกบุตรชายของเขา หรืออย่ารับพวกบุตรสาวของเขาให้พวกบุตรชายของเจ้า หรืออย่าเสริมสันติภาพและความเจริญมั่งคั่งของเขาทั้งหลายเป็นนิตย์ เพื่อเจ้าทั้งหลายจะแข็งแรง และกินของดีๆแห่งแผ่นดินนั้น และมอบแผ่นดินนั้นไว้เป็นมรดกแก่ลูกหลานของเจ้าทั้งหลายเป็นนิตย์’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 13, 'และเมื่อข้าพระองค์ทั้งหลายรับโทษเพราะการชั่วร้ายของข้าพระองค์ และเพราะการละเมิดใหญ่ยิ่งของข้าพระองค์ และเมื่อพระองค์คือพระเจ้าของข้าพระองค์ทั้งหลายได้ทรงลงโทษข้าพระองค์ เหตุความชั่วช้าของข้าพระองค์ น้อยกว่าที่พึงควรได้รับ และทรงประทานการช่วยให้พ้นแก่ข้าพระองค์ทั้งหลายอย่างนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 14, 'สมควรที่ข้าพระองค์ทั้งหลายจะฝ่าฝืนพระบัญญัติของพระองค์อีก และเข้าเกี่ยวดองด้วยการแต่งงานกับชนชาติทั้งหลายที่กระทําสิ่งที่น่าสะอิดสะเอียนเหล่านี้หรือ พระองค์จะไม่ทรงกริ้วต่อข้าพระองค์ทั้งหลายจนพระองค์ผลาญข้าพระองค์ทั้งหลายเสีย จนไม่มีคนที่เหลืออยู่และไม่มีใครรอดได้เลยหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 15, 'โอ ข้าแต่พระเยโฮวาห์พระเจ้าแห่งอิสราเอล พระองค์ชอบธรรม เพราะข้าพระองค์ทั้งหลายเป็นคนที่เหลืออยู่ซึ่งรอดพ้นมาอย่างทุกวันนี้ ดูเถิด ข้าพระองค์ทั้งหลายอยู่ต่อพระพักตร์พระองค์ มีการละเมิดของข้าพระองค์อยู่ เพราะไม่มีสักคนเดียวที่จะยืนต่อพระพักตร์พระองค์ได้เหตุเรื่องนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 1, 'ขณะที่เอสราอธิษฐานและทําการสารภาพร้องไห้ทิ้งตัวลงต่อหน้าพระนิเวศของพระเจ้า มีชุมนุมชนหมู่ใหญ่โตมากทั้งชายหญิงและเด็กจากอิสราเอลประชุมต่อหน้าท่าน เพราะประชาชนได้ร้องไห้อย่างขมขื่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 2, 'และเชคานิยาห์บุตรชายเยฮีเอล คนเอลามกล่าวแก่เอสราว่า “พวกเราทั้งหลายได้ละเมิดต่อพระเจ้าของเราเสียแล้ว และได้แต่งงานกับหญิงต่างชาติจากชนชาติทั้งหลายของแผ่นดินนี้ แต่ถึงจะมีเรื่องอย่างนี้ ก็ยังมีความหวังในอิสราเอลอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 3, 'เพราะฉะนั้นบัดนี้ ให้เรากระทําพันธสัญญากับพระเจ้าของเราที่จะทิ้งภรรยาและลูกเหล่านี้ซึ่งเกิดมาจากเขาทั้งหลายเสียทั้งสิ้น ตามคําปรึกษาของเจ้านายของข้าพเจ้า และของบรรดาผู้ที่สั่นสะท้านด้วยพระบัญญัติของพระเจ้าของเราทั้งหลาย และขอให้กระทําตามพระราชบัญญัติเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 4, 'จงลุกขึ้นเถิด เพราะเป็นหน้าที่ของท่าน และเราทั้งหลายจะสนับสนุนท่าน ขอจงเข้มแข็งและกระทําเสียเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 5, 'แล้วเอสราได้ลุกขึ้นให้บรรดาปุโรหิตใหญ่และเลวีและอิสราเอลทั้งปวงกระทําสัตย์ปฏิญาณว่า เขาจะกระทําตามที่ได้พูดแล้ว เขาทั้งหลายจึงกระทําสัตย์ปฏิญาณ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 6, 'แล้วเอสราก็ถอยไปจากต่อหน้าพระนิเวศของพระเจ้า เข้าไปในห้องของโยฮานันบุตรชายเอลียาชีบ เมื่อมาถึงที่นั่นแล้วก็ไม่รับประทานขนมปังหรือดื่มน้ํา เพราะท่านโศกเศร้าด้วยเรื่องการละเมิดของพวกที่ถูกกวาดไปเป็นเชลยนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 7, 'และเขาทําการป่าวร้องทั่วยูดาห์และเยรูซาเล็ม แก่ลูกหลานทั้งสิ้นของพวกที่ถูกกวาดไปเป็นเชลยว่า ให้มาชุมนุมกันที่เยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 8, 'และถ้าผู้ใดไม่มาภายในสามวัน ตามคําสั่งของเจ้าหน้าที่และพวกผู้ใหญ่ทั้งหลาย จะต้องริบทรัพย์สมบัติของเขาเสียทั้งสิ้น และผู้นั้นต้องขาดจากชุมนุมชนของพวกที่ถูกกวาดไปเป็นเชลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 9, 'และชายทั้งปวงของยูดาห์และเบนยามินได้ชุมนุมกันที่เยรูซาเล็มภายในสามวัน ในเดือนที่เก้า ณ วันที่ยี่สิบของเดือนนั้น และประชาชนทั้งปวงนั่งอยู่ที่ถนนหน้าพระนิเวศของพระเจ้า ตัวสั่นสะท้านด้วยเรื่องนี้ และด้วยเรื่องฝนตกหนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 10, 'และเอสราปุโรหิตได้ลุกขึ้นพูดกับเขาทั้งหลายว่า “ท่านทั้งหลายได้ละเมิดและได้แต่งงานกับหญิงต่างชาติ จึงได้ทวีการละเมิดของอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 11, 'เหตุฉะนั้นบัดนี้ จงสารภาพต่อพระเยโฮวาห์พระเจ้าแห่งบรรพบุรุษของท่าน และกระทําตามน้ําพระทัยของพระองค์ จงแยกตัวท่านออกเสียจากชนชาติทั้งหลายแห่งแผ่นดินและจากภรรยาต่างชาติ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 12, 'แล้วชุมนุมชนทั้งสิ้นได้ตอบด้วยเสียงอันดังว่า “เป็นดังนั้นแหละ เราต้องกระทําตามที่ท่านพูดแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 13, 'แต่มีประชาชนมากและเป็นเวลาที่ฝนตกหนัก เราอยู่กลางแจ้งไม่ไหวและจะจัดให้เสร็จในวันสองวันก็ไม่ได้ เพราะเราได้ละเมิดในเรื่องนี้มากนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 14, 'ขอให้เจ้าหน้าที่ของเราทําการแทนชุมนุมชนทั้งสิ้น และให้บรรดาคนในหัวเมืองของเราที่ได้รับภรรยาต่างชาติมาตามเวลากําหนด พร้อมกับพวกผู้ใหญ่และผู้วินิจฉัยของทุกเมืองจนกว่าพระพิโรธอันแรงกล้าของพระเจ้าของเรา ที่ทรงมีในเรื่องนี้หันเหไปจากเราทั้งหลาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 15, 'โยนาธานบุตรชายอาสาเฮล และยาไซอาห์บุตรชายทิกวาห์ เท่านั้นที่คัดค้านเรื่องนี้ และเมชุลลามกับชับเบธัย คนเลวีสนับสนุนเขาทั้งสอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 16, 'แล้วลูกหลานของพวกที่ถูกกวาดไปเป็นเชลยก็ได้กระทําตาม เอสราปุโรหิต และประมุขของบรรพบุรุษบางคน ตามเรือนบรรพบุรุษของเขา แต่ละคนที่ระบุชื่อไว้ได้ถูกเลือก ในวันที่หนึ่งของเดือนที่สิบเขานั่งประชุมกันพิจารณาเรื่องนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 17, 'พอถึงวันที่หนึ่งของเดือนที่หนึ่ง เขาก็จบเรื่องที่ชายทั้งปวงได้แต่งงานกับหญิงต่างชาติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 18, 'ลูกหลานของปุโรหิตผู้ได้แต่งงานกับหญิงต่างชาติ จากคนเยชูอาบุตรชายโยซาดักและพี่น้องของท่านมี มาอาเสอาห์ เอลีเยเซอร์ ยารีบและเกดาลิยาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 19, 'เขาทั้งหลายปฏิญาณตนว่าเขาจะทิ้งภรรยาของเขาเสีย และเพราะเขามีความผิด เขาจึงถวายแกะผู้ตัวหนึ่งจากฝูงแพะแกะเป็นเครื่องบูชา เพราะเหตุการละเมิดของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 20, 'จากคนอิมเมอร์ มี ฮานานีและเศบาดิยาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 21, 'จากคนฮาริม มี มาอาเสอาห์ เอลียาห์ เชไมอาห์ เยฮีเอล และอุสซียาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 22, 'จากคนปาชเฮอร์ มี เอลีโอนัย มาอาเสอาห์ อิชมาเอล เนธันเอล โยซาบาด และเอลาสาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 23, 'จากพวกคนเลวี มี โยซาบาด ชิเมอี เคลายาห์ (คือเคลิทา) เปธาหิยาห์ ยูดาห์และเอลีเยเซอร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 24, 'จากพวกนักร้อง มี เอลียาชีบ จากคนเฝ้าประตู มี ชัลลูม เทเลม และอุรี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 25, 'และจากพวกอิสราเอล คือจากคนปาโรช มี รามียาห์ อิสซียาห์ มัลคิยาห์ มิยามิน เอเลอาซาร์ มัลคิยาห์ และเบไนยาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 26, 'จากคนเอลาม คือ มัทธานิยาห์ เศคาริยาห์ เยฮีเอล อับดี เยรีโมท เอลียาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 27, 'จากคนศัทธู มี เอลีโอนัย เอลียาชีบ มัทธานิยาห์ เยรีโมท ศาบาด และอาซีซา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 28, 'จากคนเบบัย มี เยโฮฮานัน ฮานันยาห์ ศับบัย อัทลัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 29, 'จากคนบานี มี เมชุลลาม มัลลูค อาดายาห์ ยาชูบ เชอัล และราโมท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 30, 'จากคนปาหัทโมอับ มี อัดนา เคลาล เบไนยาห์ มาอาเสอาห์ มัทธานิยาห์ เบซาเลล บินนุย และมนัสเสห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 31, 'จากคนฮาริม มี เอลีเยเซอร์ อิสชีอาห์ มัลคิยาห์ เชไมอาห์ ชิเมโอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 32, 'เบนยามิน มัลลูค เชมาริยาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 33, 'จากคนฮาชูม มี มัทเธนัย มัทธัตตาห์ ศาบาด เอลีเฟเลท เยเรมัย มนัสเสห์และชิเมอี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 34, 'จากคนบานี มี มาอาดัย อัมราม อูเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 35, 'เบไนยาห์ เบดัยยาห์ เชลลูห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 36, 'วานิยาห์ เมเรโมท เอลียาชีบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 37, 'มัทธานิยาห์ มัทเธนัย ยาอาสุ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 38, 'บานี บินนุย ชิเมอี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 39, 'เชเลมิยาห์ นาธัน อาดายาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 40, 'มัคนาเดบัย ชาชัย ชารัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 41, 'อาซาเรล เชเลมิยาห์ เชมาริยาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 42, 'ชัลลูม อามาริยาห์ และโยเซฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 43, 'จากคนเนโบ มี เยอีเอล มัททีธิยาห์ ศาบาด เศบินา ยาดดัย โยเอล และเบไนยาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 44, 'บุคคลเหล่านี้ทั้งสิ้นได้แต่งงานกับหญิงต่างชาติ บางคนมีบุตรเกิดจากภรรยาเหล่านั้นด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 1, 'ถ้อยคําของเนหะมีย์ บุตรชายฮาคาลิยาห์ ต่อมาในเดือนคิสลิว ในปีที่ยี่สิบขณะที่ข้าพเจ้าอยู่ในสุสาปราสาท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 2, 'ฮานานีพี่น้องของข้าพเจ้าคนหนึ่งมาจากยูดาห์กับชายบางคน ข้าพเจ้าได้ไต่ถามถึงพวกยิวที่หนีได้ ผู้ซึ่งเหลือจากพวกที่ถูกกวาดไปเป็นเชลย และถามเรื่องเกี่ยวกับเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 3, 'เขาทั้งหลายพูดกับข้าพเจ้าว่า “ผู้ที่เหลือจากพวกที่ถูกกวาดไปเป็นเชลยซึ่งอยู่ในมณฑลมีความลําบากและความอับอายมาก กําแพงเมืองเยรูซาเล็มก็พังลง และประตูเมืองก็ถูกไฟทําลายเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 4, 'อยู่มาเมื่อข้าพเจ้าได้ยินถ้อยคําเหล่านี้ ข้าพเจ้าก็นั่งลงร้องไห้และโศกเศร้าอยู่หลายวัน ข้าพเจ้าอดอาหารและอธิษฐานต่อพระพักตร์พระเจ้าแห่งฟ้าสวรรค์เรื่อยมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 5, 'ข้าพเจ้าทูลว่า “โอ ข้าแต่พระเยโฮวาห์พระเจ้าแห่งฟ้าสวรรค์ พระเจ้าผู้ใหญ่ยิ่งและน่าเกรงกลัว ผู้ทรงรักษาพันธสัญญา และดํารงความเมตตากับบรรดาผู้ที่รักพระองค์ และรักษาพระบัญญัติของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 6, 'ขอพระองค์ทรงเงี่ยพระกรรณสดับ และขอทรงลืมพระเนตรของพระองค์ดูอยู่ เพื่อจะทรงฟังคําอธิษฐานของผู้รับใช้ของพระองค์ ซึ่งข้าพระองค์ทูลอธิษฐานต่อพระพักตร์พระองค์ ณ บัดนี้ทั้งกลางวันและกลางคืน เพื่อประชาชนอิสราเอลผู้รับใช้ของพระองค์ สารภาพบาปของประชาชนอิสราเอล ซึ่งข้าพระองค์ทั้งหลายได้กระทําบาปต่อพระองค์ ด้วยว่าข้าพระองค์กับเรือนบรรพบุรุษของข้าพระองค์ทําบาปแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 7, 'ข้าพระองค์ทั้งหลายประพฤติเลวทรามมากต่อพระองค์ และมิได้รักษาพระบัญญัติ กฎเกณฑ์ และคําตัดสินซึ่งพระองค์ได้ทรงบัญชาไว้กับโมเสสผู้รับใช้ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 8, 'ขอพระองค์ทรงระลึกถึงพระวจนะซึ่งพระองค์ได้บัญชาไว้กับโมเสสผู้รับใช้ของพระองค์ว่า ‘ถ้าเจ้าทั้งหลายกระทําการละเมิด เราจะกระจายเจ้าทั้งหลายไปในหมู่ชนชาติทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 9, 'แต่ถ้าเจ้ากลับมาหาเรา และรักษาบัญญัติของเราและประพฤติตาม ถึงแม้ว่าพวกเจ้ากระจัดกระจายไปอยู่ใต้ฟ้าที่ไกลที่สุด เราจะรวบรวมเจ้ามาจากที่นั่น และนําเจ้ามายังสถานที่ซึ่งเราได้เลือกไว้ เพื่อกระทําให้นามของเราดํารงอยู่ที่นั่น’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 10, 'เขาเหล่านี้เป็นผู้รับใช้และเป็นประชาชนของพระองค์ ผู้ซึ่งพระองค์ได้ทรงไถ่ไว้ด้วยฤทธานุภาพยิ่งใหญ่ของพระองค์ และด้วยพระหัตถ์อันทรงฤทธิ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 11, 'โอ ข้าแต่องค์พระผู้เป็นเจ้า ข้าพระองค์ทูลวิงวอนต่อพระองค์ ขอทรงเงี่ยพระกรรณตั้งพระทัยสดับฟังคําอธิษฐานของผู้รับใช้ของพระองค์ และคําอธิษฐานของบรรดาผู้รับใช้ของพระองค์ ผู้ปรารถนาจะยําเกรงพระนามของพระองค์ ข้าพระองค์ทูลวิงวอนต่อพระองค์ ขอทรงให้ผู้รับใช้ของพระองค์จําเริญขึ้นในวันนี้ และขอทรงโปรดให้เขาได้รับความเมตตาในสายตาของชายคนนี้” ขณะนั้น ข้าพเจ้าเป็นพนักงานเชิญถ้วยเสวยของกษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 1, 'และอยู่มาในเดือนนิสาน ในปีที่ยี่สิบแห่งรัชกาลกษัตริย์อารทาเซอร์ซีส เมื่อน้ําองุ่นจัดตั้งไว้ตรงพระพักตร์พระองค์ ข้าพเจ้าก็หยิบน้ําองุ่นถวายกษัตริย์ แต่ก่อนนี้ข้าพเจ้ามิได้โศกเศร้าต่อพระพักตร์พระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 2, 'ด้วยเหตุนี้กษัตริย์จึงตรัสกับข้าพเจ้าว่า “ทําไมสีหน้าของเจ้าจึงเศร้าหมอง เจ้าก็ไม่เจ็บไม่ป่วยมิใช่หรือ เห็นจะไม่มีอะไรนอกจากเศร้าใจ” และข้าพเจ้าก็เกรงกลัวยิ่งนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 3, 'ข้าพเจ้าทูลกษัตริย์ว่า “ขอกษัตริย์ทรงพระเจริญเป็นนิตย์เถิด ไฉนสีหน้าของข้าพระองค์จะไม่เศร้าหมองเล่าในเมื่อเมืองสถานที่ฝังศพของบรรพบุรุษของข้าพระองค์ร้างเปล่าอยู่ และประตูเมืองก็ถูกไฟทําลายเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 4, 'แล้วกษัตริย์ตรัสกับข้าพเจ้าว่า “เจ้าปรารถนาจะขออะไร” ข้าพเจ้าจึงอธิษฐานต่อพระเจ้าของฟ้าสวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 5, 'และข้าพเจ้าทูลกษัตริย์ว่า “ถ้าเป็นที่พอพระทัยกษัตริย์ และถ้าผู้รับใช้ของพระองค์เป็นที่โปรดปรานในสายพระเนตรของพระองค์ ขอทรงใช้ข้าพระองค์ให้ไปยังยูดาห์ ยังเมืองซึ่งเป็นที่ฝังศพของบรรพบุรุษของข้าพระองค์ เพื่อข้าพระองค์จะสร้างขึ้นใหม่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 6, 'และกษัตริย์ตรัสกับข้าพเจ้า (มีพระราชินีประทับข้างพระองค์) ว่า “เจ้าจะไปนานสักเท่าใด เมื่อไรเจ้าจะกลับมา” จึงเป็นที่พอพระทัยกษัตริย์ที่จะให้ข้าพเจ้าไป และข้าพเจ้าก็กําหนดเวลาให้พระองค์ทรงทราบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 7, 'และข้าพเจ้ากราบทูลกษัตริย์ว่า “ถ้าเป็นที่พอพระทัยกษัตริย์ ขอทรงโปรดมีพระราชสารให้ข้าพระองค์นําไปถึงผู้ว่าราชการมณฑลฟากแม่น้ําข้างโน้น เพื่อเขาจะได้อนุญาตให้ข้าพระองค์ผ่านไปจนข้าพระองค์จะไปถึงยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 8, 'และพระราชสารถึงอาสาฟเจ้าพนักงานผู้ดูแลป่าไม้หลวง เพื่อเขาจะได้ให้ไม้แก่ข้าพระองค์ เพื่อทําคานประตูพระราชวังของพระนิเวศ และทํากําแพงเมือง และเพื่อทําบ้านที่ข้าพระองค์จะได้เข้าอาศัย” กษัตริย์ก็ทรงพระราชทานให้ตามพระหัตถ์อันประเสริฐของพระเจ้าของข้าพเจ้าที่อยู่เหนือข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 9, 'แล้วข้าพเจ้ามายังผู้ว่าราชการมณฑลฟากแม่น้ําข้างโน้น และมอบพระราชสารของกษัตริย์ให้แก่เขา อนึ่งกษัตริย์ทรงจัดให้นายทหารและพลม้าไปกับข้าพเจ้าด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 10, 'แต่เมื่อสันบาลลัทชาวโฮโรนาอิม และโทบีอาห์คนอัมโมนข้าราชการได้ยินเรื่องนี้ เป็นเรื่องที่ไม่พอใจเขาอย่างยิ่งที่มีคนมาหาความสุขให้คนอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 11, 'ข้าพเจ้าจึงมายังเยรูซาเล็มและพักอยู่ที่นั่นสามวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 12, 'แล้วข้าพเจ้าลุกขึ้นในกลางคืน คือข้าพเจ้ากับบางคนที่อยู่กับข้าพเจ้า ข้าพเจ้าไม่ได้บอกผู้หนึ่งผู้ใดถึงเรื่องที่พระเจ้าของข้าพเจ้าดลใจข้าพเจ้าให้กระทําเพื่อเยรูซาเล็ม ข้าพเจ้าไม่มีสัตว์อื่นกับข้าพเจ้านอกจากสัตว์ที่ข้าพเจ้าขี่อยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 13, 'ในกลางคืนข้าพเจ้าออกไปทางประตูหุบเขา ถึงบ่อมังกร และถึงประตูกองขยะ และข้าพเจ้าได้ตรวจดูกําแพงเยรูซาเล็มที่พัง และประตูเมืองที่ถูกไฟทําลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 14, 'แล้วข้าพเจ้าก็ไปต่อยังประตูน้ําพุ ถึงสระหลวง แต่ไม่มีที่ที่จะให้สัตว์ซึ่งข้าพเจ้าขี่อยู่ผ่านไปได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 15, 'แล้วข้าพเจ้าขึ้นไปกลางคืนทางลําธารและตรวจดูกําแพง แล้วกลับมาเข้าทางประตูหุบเขากลับที่เดิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 16, 'ส่วนพวกเจ้าหน้าที่ก็ไม่ทราบว่าข้าพเจ้าไปไหน หรือข้าพเจ้าทําอะไร และข้าพเจ้าก็ยังไม่ได้บอกพวกยิว บรรดาปุโรหิต พวกขุนนาง พวกเจ้าหน้าที่ และคนอื่นๆที่จะรับผิดชอบการงาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 17, 'แล้วข้าพเจ้าพูดกับเขาทั้งหลายว่า “ท่านทั้งหลายเห็นแล้วว่าเราตกอยู่ในความลําบากอย่างไร ที่เยรูซาเล็มปรักหักพังลง และไฟไหม้ประตูเมืองเสียนั้น มาเถิด ให้เราสร้างกําแพงเยรูซาเล็มขึ้น เพื่อเราจะไม่ต้องอับอายขายหน้าอีก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 18, 'แล้วข้าพเจ้าบอกพวกเขาถึงการที่พระหัตถ์แห่งพระเจ้าของข้าพเจ้าอยู่กับข้าพเจ้า เพื่อยังผลดี ทั้งพระดํารัสซึ่งกษัตริย์ตรัสกับข้าพเจ้า และเขาทั้งหลายพูดว่า “ให้เราลุกขึ้นสร้างเถิด” เขาก็ปลงใจลงมือทําการดีนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 19, 'แต่เมื่อสันบาลลัทคนโฮโรนาอิม และโทบีอาห์ข้าราชการ คนอัมโมน กับเกเชมชาวอาระเบียได้ยินเรื่องนั้น เขาทั้งหลายเยาะเย้ยและดูถูกเรา พูดว่า “เจ้าทั้งหลายทําอะไรกันนี่ เจ้ากําลังกบฏต่อกษัตริย์หรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 20, 'แล้วข้าพเจ้าตอบเขาทั้งหลายว่า “พระเจ้าแห่งฟ้าสวรรค์จะทรงให้เรากระทําสําเร็จ และเราทั้งหลายผู้รับใช้ของพระองค์จะลุกขึ้นสร้าง แต่ท่านทั้งหลายไม่มีส่วนหรือสิทธิหรือที่ระลึกในเยรูซาเล็ม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 1, 'แล้วเอลียาชีบมหาปุโรหิตได้ลุกขึ้นพร้อมกับพี่น้องของท่าน บรรดาปุโรหิต และเขาทั้งหลายได้สร้างประตูแกะ เขาได้ทําพิธีชําระให้บริสุทธิ์และได้ตั้งบานประตู เขาทั้งหลายได้ทําพิธีชําระให้บริสุทธิ์จนถึงหอคอยเมอาห์ไกลไปจนถึงหอคอยฮานันเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 2, 'และถัดท่านไป คนชาวเยรีโคก็ได้สร้าง และถัดเขาไป ศักเกอร์บุตรชายอิมรีก็ได้สร้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 3, 'และลูกหลานของหัสเสนาอาห์ได้สร้างประตูปลา เขาได้วางวงกบและได้ตั้งบานประตู ติดลูกสลักและดาลประตู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 4, 'ถัดเขาไปเมเรโมทบุตรชายอุรียาห์ ผู้เป็นบุตรชายฮักโขสได้ซ่อมแซม และถัดเขาไปเมชุลลามบุตรชายเบเรคิยาห์ ผู้เป็นบุตรชายเมเชซาเบลได้ซ่อมแซม และถัดเขาไปศาโดกบุตรชายบาอานาได้ซ่อมแซม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 5, 'และถัดเขาไปชาวเทโคอาได้ซ่อมแซม แต่พวกขุนนางของเขาไม่ยอมเอาคอมารับงานขององค์พระผู้เป็นเจ้าของเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 6, 'และเยโฮยาดาบุตรชายปาเสอาห์ และเมชุลลามบุตรชายเบโสไดอาห์ได้ซ่อมแซมประตูเก่า เขาวางวงกบและตั้งบานประตู ติดลูกสลักและดาลประตู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 7, 'และถัดเขาไป คือ เมลาติยาห์ชาวกิเบโอน และยาโดนชาวเมโรโนท คนเมืองกิเบโอนและเมืองมิสปาห์ได้ซ่อมแซม ซึ่งอยู่ใต้ปกครองของเจ้าเมืองฟากแม่น้ําข้างนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 8, 'ถัดเขาไปคืออุสซีเอลบุตรชายฮารฮายาห์ช่างทองได้ซ่อมแซม ถัดเขาไปคือฮานันยาห์ผู้เป็นบุตรชายของช่างน้ําหอมคนหนึ่งได้ซ่อมแซม เขาบูรณะเยรูซาเล็มไกลไปจนถึงตอนกําแพงกว้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 9, 'ถัดเขาไป คือเรไฟยาห์บุตรชายเฮอร์ ผู้ปกครองแขวงครึ่งหนึ่งของเยรูซาเล็มได้ซ่อมแซม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 10, 'ถัดเขาไปคือ เยดายาห์บุตรชายฮารุมัฟได้ซ่อมแซมตรงข้ามกับบ้านของเขา และถัดเขาไปคือ ฮัทธัชบุตรชายฮาชับนิยาห์ได้ซ่อมแซม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 11, 'มัลคิยาห์บุตรชายฮาริม และหัสชูบบุตรชายปาหัทโมอับได้ซ่อมแซมอีกส่วนหนึ่ง และหอคอยเตาอบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 12, 'ถัดเขาไปคือ ชัลลูมบุตรชายฮัลโลเหช ผู้ปกครองแขวงครึ่งหนึ่งของเยรูซาเล็มได้ซ่อมแซม ทั้งตัวเขาและบุตรสาวของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 13, 'ฮานูนและชาวเมืองศาโนอาห์ได้ซ่อมแซมประตูหุบเขา เขาสร้างประตูขึ้นใหม่และตั้งบานประตู ติดลูกสลักและดาลประตู และซ่อมแซมกําแพงระยะพันศอกไกลไปจนถึงประตูกองขยะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 14, 'มัลคิยาห์บุตรชายเรคาบ ผู้ปกครองส่วนหนึ่งของแขวงเบธฮัคเคเรม ได้ซ่อมประตูกองขยะ เขาสร้างและตั้งบานประตู ติดลูกสลักและดาลประตู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 15, 'ชัลลูนบุตรชายคลโฮเซห์ ผู้ปกครองส่วนหนึ่งของแขวงมิสปาห์ ได้ซ่อมแซมประตูน้ําพุ ได้สร้างประตู สร้างมุงและตั้งบานประตู ติดลูกสลักและดาลประตู ท่านได้สร้างกําแพงสระชิโลอาห์ตรงไปทางราชอุทยานไกลไปจนถึงบันไดซึ่งลงไปจากนครดาวิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 16, 'ถัดเขาไปเนหะมีย์บุตรชายอัสบูก ผู้ปกครองแขวงเบธซูร์ครึ่งหนึ่งได้ซ่อมแซม ไปจนถึงที่ตรงข้ามกับอุโมงค์ฝังศพของดาวิด ถึงสระขุดและถึงโรงทแกล้วทหาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 17, 'ถัดเขาไปคนเลวีได้ซ่อมแซม คือ เรฮูมบุตรชายบานี ถัดเขาไปคือ ฮาชาบิยาห์ ผู้ปกครองแขวงเคอีลาห์ครึ่งหนึ่ง ได้ซ่อมแซมส่วนของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 18, 'ถัดเขาไปพี่น้องของเขาได้ซ่อมแซมคือ บัฟวัยบุตรชายเฮนาดัด ผู้ปกครองแขวงเคอีลาห์ครึ่งหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 19, 'ถัดเขาไปคือ เอเซอร์บุตรชายเยชูอา ผู้ปกครองเมืองมิสปาห์ได้ซ่อมแซมอีกส่วนหนึ่งตรงข้ามกับทางขึ้นไปยังคลังอาวุธตรงที่มุมหักของกําแพง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 20, 'ถัดเขาไปคือ บารุคบุตรชายศับบัย ได้ซ่อมแซมอย่างร้อนใจอีกส่วนหนึ่ง ตั้งแต่มุมหักของกําแพงจนถึงประตูเรือนของเอลียาชีบมหาปุโรหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 21, 'ถัดเขาไปคือ เมเรโมทบุตรชายอุรียาห์ ผู้เป็นบุตรชายฮักโขส ได้ซ่อมแซมอีกส่วนหนึ่ง ตั้งแต่ประตูเรือนของเอลียาชีบถึงปลายเรือนของเอลียาชีบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 22, 'ถัดเขาไปคือบรรดาปุโรหิตชาวที่ราบได้ซ่อมแซม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 23, 'ถัดเขาไปคือ เบนยามินและหัสชูบ ได้ซ่อมแซมตรงข้ามกับบ้านของเขาทั้งหลาย ถัดเขาไปคือ อาซาริยาห์บุตรชายมาอาเสอาห์ ผู้เป็นบุตรชายอานานิยาห์ได้ซ่อมแซมข้างเรือนของเขาเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 24, 'ถัดเขาไปคือ บินนุยบุตรชายเฮนาดัดได้ซ่อมแซมอีกส่วนหนึ่ง ตั้งแต่บ้านของอาซาริยาห์ถึงมุมหักของกําแพง คือถึงมุมเลี้ยว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 25, 'ปาลาลบุตรชายอุซัยได้ซ่อมแซมที่ตรงข้ามกับมุมหักของกําแพง และหอคอยที่ยื่นจากพระราชวังหลังบนที่ลานทหารรักษาพระองค์ ถัดเขาไปคือ เปดายาห์บุตรชายปาโรช');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 26, 'และคนใช้ประจําพระวิหารอยู่ที่โอเฟล ได้ซ่อมแซมไปจนถึงที่ตรงข้ามกับประตูน้ําทางด้านตะวันออกและที่หอคอยยื่นออกไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 27, 'ถัดเขาไปชาวเทโคอาได้ซ่อมแซมอีกส่วนหนึ่งตรงข้ามกับหอคอยใหญ่ที่ยื่นออกไปไกลไปจนถึงประตูเมืองโอเฟล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 28, 'บรรดาปุโรหิตได้ซ่อมแซมเหนือประตูม้าขึ้นไป ต่างก็ซ่อมที่ตรงข้ามกับเรือนของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 29, 'ถัดเขาไป ศาโดกบุตรชายอิมเมอร์ ได้ซ่อมแซมที่ตรงข้ามกับเรือนของเขา ถัดเขาไป เชไมอาห์บุตรชายเชคานิยาห์ คนเฝ้าประตูตะวันออกได้ซ่อมแซม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 30, 'ถัดเขาไป ฮานันยาห์บุตรชายเชเลมิยาห์ และฮานูนบุตรชายคนที่หกของศาลาฟ ได้ซ่อมแซมอีกส่วนหนึ่ง ถัดเขาไปคือ เมชุลลามบุตรชายเบเรคิยาห์ ได้ซ่อมแซมตรงข้ามกับห้องของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 31, 'ถัดเขาไป มัลคิยาห์บุตรชายของช่างทองคนหนึ่งได้ซ่อมแซมไกลไปจนถึงเรือนของคนใช้ประจําพระวิหาร และของพ่อค้า ตรงข้ามกับประตูมิฟคาด จนถึงห้องชั้นบนที่มุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 32, 'และระหว่างห้องชั้นบนที่มุมกับประตูแกะนั้น บรรดาช่างทองและพ่อค้าได้ซ่อมแซม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 1, 'ต่อมาเมื่อสันบาลลัทได้ยินว่าเรากําลังก่อสร้างกําแพง เขาโกรธและเดือดดาลมาก และเขาเยาะเย้ยพวกยิว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 2, 'และเขาพูดต่อหน้าพี่น้องของเขาและต่อหน้ากองทัพของสะมาเรียว่า “พวกยิวที่อ่อนแอเหล่านี้ทําอะไรกัน เขาจะซ่อมกันหรือ เขาจะทําสัตวบูชาหรือ เขาจะทําให้เสร็จในวันเดียวหรือ เขาจะเอาหินที่ถูกเผาจากกองขยะมาใช้อีกหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 3, 'โทบีอาห์คนอัมโมนอยู่ข้างๆท่าน และเขาพูดว่า “เออ สิ่งที่เขากําลังสร้างอยู่นั้น ถ้าสุนัขจิ้งจอกตัวหนึ่งวิ่งขึ้นไป มันจะพังกําแพงหินของเขาลงมา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 4, '“โอ ข้าแต่พระเจ้าของข้าพระองค์ทั้งหลาย ขอทรงสดับ เพราะข้าพระองค์ทั้งหลายเป็นที่ดูถูกดูหมิ่น ขอทรงหันการเยาะเย้ยของเขาให้ตกบนศีรษะของเขาเอง และขอทรงมอบเขาไว้ให้ถูกปล้นบนแผ่นดินที่เขาจะไปเป็นเชลยนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 5, 'ขออย่าทรงปกปิดความชั่วช้าของเขาไว้ และขออย่าลบล้างบาปของเขาทั้งหลายต่อเบื้องพระพักตร์พระองค์ เพราะเขาทั้งหลายได้ยั่วเย้าให้ทรงกริ้วต่อหน้าบรรดาผู้ก่อสร้าง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 6, 'เราจึงสร้างกําแพงขึ้น และกําแพงทั้งสิ้นก็ต่อกันสูงครึ่งหนึ่งแล้ว เพราะประชาชนมีน้ําใจที่จะทํางาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 7, 'แต่ต่อมาเมื่อสันบาลลัทและโทบีอาห์ กับชาวอาระเบีย และคนอัมโมน และชาวอัชโดดได้ยินว่า การซ่อมแซมกําแพงเยรูซาเล็มนั้นกําลังคืบหน้าต่อไป และกําลังปิดช่องโหว่ต่างๆ เขาทั้งหลายก็โกรธมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 8, 'และเขาก็ปองร้ายกันจะมาสู้รบกับเยรูซาเล็ม และก่อการโกลาหลขึ้นในนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 9, 'แต่เราทั้งหลายได้อ้อนวอนต่อพระเจ้าของเรา และวางยามป้องกันเขาทั้งหลายทั้งกลางวันและกลางคืน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 10, 'แต่ยูดาห์กล่าวว่า “เรี่ยวแรงของคนที่ขนของก็กําลังทรุดลง และมีสิ่งปรักหักพังมาก เราไม่สามารถสร้างกําแพงได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 11, 'และศัตรูของเรากล่าวว่า “เขาจะไม่รู้ไม่เห็นจนกว่าเราจะเข้ามาท่ามกลางเขาและฆ่าเขา กับยับยั้งงานของเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 12, 'ต่อมาเมื่อพวกยิวที่อยู่ใกล้เขาทั้งหลายมาก็ได้บอกเราตั้งสิบครั้งว่า “เขาจะลุกขึ้นมาต่อสู้เราจากที่อยู่ของเขาทุกแห่ง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 13, 'ข้าพเจ้าจึงตั้งประชาชนไว้ในส่วนที่ต่ําที่สุดข้างหลังกําแพง และในที่สูง ตามครอบครัวของเขา โดยมีดาบ หอก และคันธนู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 14, 'ข้าพเจ้ามองดู แล้วลุกขึ้นพูดกับขุนนางและเจ้าหน้าที่ทั้งหลาย กับคนนอกนั้นว่า “อย่ากลัวเขาเลย จงระลึกถึงองค์พระผู้เป็นเจ้าผู้ใหญ่ยิ่งและน่าเกรงกลัว และต่อสู้เพื่อพี่น้องของท่าน บุตรชายบุตรสาวของท่าน ภรรยาและเรือนของท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 15, 'อยู่มาเมื่อศัตรูของเราได้ยินว่าเราได้ยินเรื่องแล้ว และพระเจ้าได้ทรงทําลายแผนงานของเขา เราต่างก็กลับมายังกําแพงที่งานของตนทุกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 16, 'ตั้งแต่วันนั้นมา ผู้รับใช้ของข้าพเจ้าครึ่งหนึ่งทําการก่อสร้าง อีกครึ่งหนึ่งถือหอก โล่ คันธนู และเสื้อเกราะ บรรดาประมุขทั้งหลายหนุนหลังบรรดาวงศ์วานยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 17, 'ผู้ที่ก่อสร้างกําแพง และบรรดาผู้ที่ขนของกับผู้ที่ยกของขึ้น ทุกคนมือหนึ่งทํางาน อีกมือหนึ่งถืออาวุธไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 18, 'ผู้ก่อสร้างทุกคนมีดาบคาดอยู่ที่สีข้างขณะที่เขาสร้าง ชายที่เป่าแตรก็อยู่ข้างข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 19, 'ข้าพเจ้าพูดกับขุนนางและเจ้าหน้าที่ทั้งปวงกับคนนอกนั้นว่า “การงานก็ใหญ่โตและกระจายกันไปมาก เพราะเราแยกกันอยู่บนกําแพงห่างจากกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 20, 'เมื่อท่านทั้งหลายได้ยินเสียงแตรอยู่ตรงไหน จงวิ่งกรูกันไปที่พวกเรา พระเจ้าของเราทั้งหลายจะทรงต่อสู้เพื่อพวกเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 21, 'เราจึงทํางานกัน พวกเราครึ่งหนึ่งถือหอกตั้งแต่เช้ามืดจนดาวขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 22, 'ครั้งนั้น ข้าพเจ้าพูดกับประชาชนอีกว่า “ขอให้ผู้ชายทุกคนกับคนใช้ของเขาด้วยค้างคืนเสียภายในเยรูซาเล็ม เพื่อเขาจะเป็นยามให้เราในกลางคืนและทํางานกลางวัน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 23, 'ข้าพเจ้า พี่น้องของข้าพเจ้า หรือคนใช้ของข้าพเจ้า หรือคนยามผู้ติดตามข้าพเจ้าก็ดี ไม่มีใครถอดเครื่องแต่งกายออก เว้นแต่เหล่าคนที่ถอดออกเพื่อซัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 1, 'มีเสียงร้องของประชาชนและของภรรยาของเขาอย่างเกรียวกราวกล่าวโทษพี่น้องพวกยิว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 2, 'เพราะมีคนที่กล่าวว่า “เรามากคนด้วยกัน ทั้งบุตรชายและบุตรสาวของเรา ขอให้เราได้ข้าว เพื่อเราจะได้รับประทานและมีชีวิตอยู่ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 3, 'และมีคนกล่าวว่า “เราต้องจํานําไร่นาของเรา สวนองุ่นของเรา และบ้านเรือนของเรา เพื่อจะได้ข้าว เพราะเหตุการกันดารอาหาร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 4, 'และคนอื่นๆกล่าวว่า “เราได้ขอยืมเงินมาเป็นค่าภาษีถวายกษัตริย์ โดยจํานํานาและสวนองุ่นของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 5, 'เนื้อของเราเป็นเหมือนเนื้อพี่น้องของเรา ลูกของเราก็เหมือนลูกของเขา แต่ดูเถิด เราก็ยังให้บุตรชายและบุตรสาวของเราเป็นทาส บุตรสาวของเราบางคนเป็นทาสแล้ว และเราไม่มีกําลังที่จะไถ่เขาเลย เพราะคนอื่นยึดนาและสวนองุ่นของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 6, 'เมื่อข้าพเจ้าได้ยินเสียงร้องของเขา และถ้อยคําของเขา ข้าพเจ้าก็โกรธมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 7, 'ข้าพเจ้าตรึกตรองแล้วก็นําความนี้ไปกล่าวหาพวกขุนนางและเจ้าหน้าที่ ข้าพเจ้าพูดกับเขาว่า “ท่านทั้งหลายต่างคนต่างได้ให้ยืมเงินโดยคิดดอกเบี้ยจากพี่น้องของตน” และข้าพเจ้าก็เรียกชุมนุมใหญ่มาสู้กับเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 8, 'และข้าพเจ้ากล่าวแก่เขาว่า “เราได้ไถ่พวกยิวพี่น้องของเราผู้ถูกขายไปยังคนต่างประเทศคืนมา ตามแต่เราจะสามารถทําได้ แต่ท่านกลับขายพี่น้องของท่าน เพื่อเขาจะได้ถูกขายให้แก่พวกเรา” คนทั้งหลายก็นิ่งอยู่ พูดไม่ออก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 9, 'ข้าพเจ้าจึงว่า “สิ่งที่ท่านทั้งหลายทําอยู่นั้นไม่ดี ไม่ควรที่ท่านจะดําเนินในความยําเกรงพระเจ้าของเราทั้งหลาย เพื่อป้องกันการเยาะเย้ยของประชาชาติเหล่านั้น ซึ่งเป็นศัตรูของเราดอกหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 10, 'ยิ่งกว่านั้นอีก ข้าพเจ้ากับพี่น้องของข้าพเจ้าและคนใช้ของข้าพเจ้าให้เขายืมเงินและยืมข้าว ให้เราเลิกการให้ยืมโดยคิดดอกเบี้ยนั้นเสียเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 11, 'ในวันนี้ ขอจงคืนมา ไร่นา สวนองุ่น สวนมะกอกเทศ และเรือนของเขา และส่วนร้อยของเงิน ข้าว น้ําองุ่น และน้ํามัน ซึ่งท่านได้รีดเอาจากเขานั้นเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 12, 'แล้วเขาทั้งหลายพูดว่า “เราจะคืนสิ่งเหล่านี้และจะไม่เรียกร้องสิ่งใดๆจากเขาทั้งหลาย เราจะกระทําตามที่ท่านพูด” และข้าพเจ้าก็เรียกบรรดาปุโรหิตมา และให้ปุโรหิตเอาคําสาบานจากเขาทั้งหลายว่า เขาจะกระทําตามที่เขาสัญญาแล้วนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 13, 'ข้าพเจ้าก็สลัดตักของข้าพเจ้าด้วย และพูดว่า “ดังนั้นแหละถ้าคนใดมิได้กระทําตามสัญญานี้ ขอพระเจ้าทรงสลัดเขาเสียจากเรือนของเขา และจากการงานของเขา ให้เขาถูกสลัดออกแล้วไปตัวเปล่า” และชุมนุมชนทั้งปวงกล่าวว่า “เอเมน” และได้สรรเสริญพระเยโฮวาห์ แล้วประชาชนก็ได้กระทําตามที่เขาได้สัญญาไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 14, '“ยิ่งกว่านั้นอีก ตั้งแต่เวลาที่ข้าพเจ้าได้รับแต่งตั้งให้เป็นผู้ว่าราชการในแผ่นดินยูดาห์ ตั้งแต่ปีที่ยี่สิบจนปีที่สามสิบสองแห่งรัชกาลกษัตริย์อารทาเซอร์ซีส สิบสองปีด้วยกัน ข้าพเจ้าหรือพี่น้องของข้าพเจ้ามิได้รับประทานอาหารของตําแหน่งผู้ว่าราชการ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 15, 'ผู้ว่าราชการคนที่อยู่ก่อนข้าพเจ้าได้เบียดเบียนประชาชน ได้เอาเงินเป็นค่าอาหารและน้ําองุ่นไปจากเขา นอกจากเงินวันละสี่สิบเชเขล แม้ข้าราชการของท่านก็ได้ใช้อํานาจเหนือประชาชน แต่ข้าพเจ้ามิได้กระทําเช่นนั้น เพราะความยําเกรงพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 16, 'ข้าพเจ้ายังยึดงานสร้างกําแพงนี้อยู่ และมิได้ซื้อที่ดินเลย และคนใช้ของข้าพเจ้าทั้งสิ้นก็ได้ชุมนุมกันทํางานกันที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 17, 'ยิ่งกว่านั้น ข้าพเจ้ามีคนหนึ่งร้อยห้าสิบร่วมสํารับกับข้าพเจ้า คือพวกยิวและเจ้าหน้าที่ นอกเหนือจากบรรดาผู้ที่มาอยู่กับเราทั้งหลายจากประชาชาติผู้ซึ่งอยู่รอบเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 18, 'สิ่งที่เตรียมไว้ในวันหนึ่งๆ มีวัวตัวหนึ่ง และแกะที่คัดเลือกแล้วหกตัว เป็ดไก่เขาก็จัดไว้ให้ข้าพเจ้าด้วย ในทุกๆสิบวันน้ําองุ่นมากมายหลายถุงหนัง แม้จะมากอย่างนี้ ข้าพเจ้ามิได้เรียกร้องเอาส่วนอาหารของตําแหน่งผู้ว่าราชการ เพราะว่าการปรนนิบัตินั้นเป็นภาระหนักแก่ชนชาตินี้อยู่แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 19, 'ข้าแต่พระเจ้าของข้าพระองค์ ขอทรงระลึกถึงสิ่งที่ข้าพระองค์ได้กระทําเพื่อชนชาตินี้ให้เกิดผลดีเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 1, 'อยู่มาเมื่อมีรายงานให้สันบาลลัท โทบีอาห์และเกเชมชาวอาระเบียกับศัตรูอื่นๆของเราทั้งหลายได้ยินว่า ข้าพเจ้าได้ก่อกําแพง และไม่มีช่องโหว่เหลืออยู่ (แม้ว่าจนวันนั้นข้าพเจ้ายังไม่ได้ตั้งบานประตูที่ประตูเมือง)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 2, 'สันบาลลัทกับเกเชมใช้ให้มาหาข้าพเจ้าว่า “ขอเชิญมาพบกันในชนบทแห่งหนึ่งในที่ราบโอโน” แต่เขาทั้งหลายเจตนาจะทําอันตรายข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 3, 'ข้าพเจ้าก็ใช้ผู้สื่อสารไปหาพวกเขาว่า “ข้าพเจ้ากําลังทํางานใหญ่ ลงมาไม่ได้ ทําไมจะให้งานหยุดเสียในขณะที่ข้าพเจ้าทิ้งงานลงมาหาท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 4, 'แล้วเขาใช้ให้มาหาข้าพเจ้าอย่างนี้สี่ครั้ง ข้าพเจ้าก็ตอบเขาไปทํานองเดียวกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 5, 'สันบาลลัทได้ส่งคนใช้ของท่านมาหาข้าพเจ้าในทํานองเดียวกันเป็นครั้งที่ห้า ถือจดหมายเปิดมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 6, 'ในนั้นมีเขียนไว้ว่า “เขากล่าวกันในท่ามกลางประชาชาติทั้งหลาย และเกเชมก็กล่าวด้วยว่า ท่านและพวกยิวเจตนาจะกบฏ เหตุนั้นแหละท่านจึงสร้างกําแพง และท่านปรารถนาจะเป็นกษัตริย์ของพวกเขา ตามถ้อยคํานี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 7, 'และท่านได้แต่งตั้งผู้พยากรณ์ไว้ให้ป่าวร้องเกี่ยวกับตัวท่านในเยรูซาเล็มว่า ‘มีกษัตริย์ในยูดาห์’ บัดนี้จะได้รายงานให้กษัตริย์ทรงทราบตามถ้อยคําเหล่านี้ เหตุฉะนั้นบัดนี้ขอเชิญท่านมาหารือด้วยกัน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 8, 'แล้วข้าพเจ้าก็ใช้ให้ไปหาเขากล่าวว่า “สิ่งที่ท่านกล่าวมานั้นเราไม่ได้กระทํากันเลย ท่านเสกสรรขึ้นตามใจของท่านเอง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 9, 'เพราะเขาทั้งหลายต้องการที่จะให้เราตกใจคิดว่า “มือของเขาจะผละจากงานไปเสีย และงานจะได้ไม่สําเร็จ” โอ ข้าแต่พระเจ้า ฉะนั้นบัดนี้ขอพระองค์ทรงเสริมกําลังมือของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 10, 'และข้าพเจ้าเข้าไปในเรือนของเชไมอาห์ บุตรชายเดไลยาห์ ผู้เป็นบุตรชายเมเหทาเบล ผู้ที่เก็บตัวอยู่ เขาพูดว่า “ให้เราไปพบกันในพระนิเวศของพระเจ้าในพระวิหาร ให้เราปิดประตูพระวิหารเสีย เพราะเขาทั้งหลายจะมาฆ่าท่าน เวลากลางคืนเขาจะมาฆ่าท่านเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 11, 'แต่ข้าพเจ้าว่า “คนอย่างข้าพเจ้าจะหนีหรือ และคนอย่างข้าพเจ้าจะเข้าไปอยู่ในพระวิหารเพื่อช่วยชีวิตให้รอดได้หรือ ข้าพเจ้าจะไม่เข้าไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 12, 'และดูเถิด ข้าพเจ้าเข้าใจและเห็นว่า พระเจ้ามิได้ทรงใช้เขา แต่เขาได้พยากรณ์ใส่ร้ายข้าพเจ้า เพราะโทบีอาห์และสันบาลลัทได้จ้างเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 13, 'เขาทั้งสองได้จ้างเขามาด้วยหวังจะให้ข้าพเจ้ากลัวแล้วกระทําเช่นนั้น จะได้บาปและเขาจะมีเรื่องป้ายร้ายข้าพเจ้า เพื่อจะเยาะเย้ยข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 14, '“ข้าแต่พระเจ้าของข้าพระองค์ ขอพระองค์ทรงระลึกถึงโทบีอาห์และสันบาลลัทตามสิ่งเหล่านี้ที่เขาได้กระทํา ทั้งโนอัดยาห์หญิงผู้พยากรณ์และผู้พยากรณ์อื่นๆซึ่งต้องการให้ข้าพระองค์กลัว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 15, 'กําแพงจึงสําเร็จในวันที่ยี่สิบห้าเดือนเอลูล ในห้าสิบสองวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 16, 'และอยู่มาเมื่อศัตรูทั้งสิ้นของเราทั้งหลายได้ยิน และเมื่อประชาชาติทั้งปวงรอบเราก็เห็นแล้ว เขาก็น้อยเนื้อต่ําใจ เพราะเขาทั้งหลายหยั่งรู้ว่างานนี้ที่ได้สําเร็จไปก็ด้วยพระเจ้าของเราทรงช่วยเหลือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 17, 'ยิ่งกว่านั้นอีก ในครั้งนั้นขุนนางทั้งหลายของยูดาห์ก็ได้ส่งจดหมายหลายฉบับไปถึงโทบีอาห์ และจดหมายของโทบีอาห์ก็มาถึงเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 18, 'เพราะมีหลายคนในยูดาห์ได้ผูกพันกับเขาไว้ด้วยคําปฏิญาณ เพราะเขาเป็นบุตรเขยของเชคานิยาห์ ผู้เป็นบุตรชายอาราห์ และโยฮานันบุตรชายของเขาก็ได้รับบุตรสาวของเมชุลลาม ผู้เป็นบุตรชายเบเรคิยาห์เป็นภรรยาของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 19, 'เขาทั้งหลายพูดถึงความดีของโทบีอาห์ต่อหน้าข้าพเจ้าด้วย และรายงานคําของข้าพเจ้าไปให้เขา และโทบีอาห์ก็ได้ส่งจดหมายมาให้ข้าพเจ้า เพื่อให้กลัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 1, 'ต่อมาเมื่อสร้างกําแพงเสร็จ ข้าพเจ้าก็ตั้งบานประตู และผู้เฝ้าประตู นักร้องเพลง และแต่งตั้งคนเลวีไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 2, 'ข้าพเจ้ามอบให้ฮานานีพี่น้องของข้าพเจ้า และฮานันยาห์ผู้ดูแลสํานักพระราชวังเป็นผู้รับผิดชอบกรุงเยรูซาเล็ม เพราะเขาเป็นคนสัตย์ซื่อและยําเกรงพระเจ้ามากกว่าคนอื่นๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 3, 'ข้าพเจ้าพูดกับพวกเขาว่า “อย่าให้ประตูเมืองเยรูซาเล็มเปิดจนกว่าแดดจะร้อน และเมื่อเขายืนเฝ้ายามอยู่ ก็ให้ปิดและเอาดาลกั้นไว้ จงแต่งตั้งยามจากชาวเยรูซาเล็ม ต่างก็ประจําที่ของเขา และต่างก็อยู่ยามตรงข้ามเรือนของเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 4, 'เมืองนั้นกว้างและใหญ่ แต่คนภายในน้อย และบ้านช่องก็ยังไม่ได้สร้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 5, 'แล้วพระเจ้าทรงดลใจข้าพเจ้าให้เรียกชุมนุมพวกขุนนาง และเจ้าหน้าที่และประชาชนเพื่อจะขึ้นทะเบียนสํามะโนครัวเชื้อสาย ข้าพเจ้าพบหนังสือสํามะโนครัวเชื้อสายของคนที่ขึ้นมาครั้งก่อน ข้าพเจ้าเห็นเขียนไว้ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 6, 'ต่อไปนี้ เป็นประชาชนแห่งมณฑลที่ขึ้นมาจากการเป็นเชลยในพวกที่ถูกกวาดไป ซึ่งเนบูคัดเนสซาร์กษัตริย์แห่งบาบิโลนได้กวาดไป เขาทั้งหลายกลับมายังเยรูซาเล็มและยูดาห์ ต่างกลับยังหัวเมืองของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 7, 'เขาทั้งหลายที่กลับมากับเศรุบบาเบล เยชูอา เนหะมีย์ อาซาริยาห์ ราอามิยาห์ นาหะมานี โมรเดคัย บิลชาน มิสเปเรท บิกวัย เนฮูม บาอานาห์ จํานวนผู้ชายของประชาชนอิสราเอลคือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 8, 'คนปาโรช สองพันหนึ่งร้อยเจ็ดสิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 9, 'คนเชฟาทิยาห์ สามร้อยเจ็ดสิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 10, 'คนอาราห์ หกร้อยห้าสิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 11, 'คนปาหัทโมอับ คือลูกหลานของเยชูอาและโยอาบ สองพันแปดร้อยสิบแปดคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 12, 'คนเอลาม หนึ่งพันสองร้อยห้าสิบสี่คน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 13, 'คนศัทธู แปดร้อยสี่สิบห้าคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 14, 'คนศักคัย เจ็ดร้อยหกสิบคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 15, 'คนบินนุย หกร้อยสี่สิบแปดคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 16, 'คนเบบัย หกร้อยยี่สิบแปดคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 17, 'คนอัสกาด สองพันสามร้อยยี่สิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 18, 'คนอาโดนีคัม หกร้อยหกสิบเจ็ดคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 19, 'คนบิกวัย สองพันหกสิบเจ็ดคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 20, 'คนอาดีน หกร้อยห้าสิบห้าคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 21, 'คนอาเทอร์ของเฮเซคียาห์ เก้าสิบแปดคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 22, 'คนฮาชูม สามร้อยยี่สิบแปดคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 23, 'คนเบไซ สามร้อยยี่สิบสี่คน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 24, 'คนฮาริฟ หนึ่งร้อยสิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 25, 'คนกิเบโอน เก้าสิบห้าคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 26, 'คนชาวเบธเลเฮมและเนโทฟาห์ หนึ่งร้อยแปดสิบแปดคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 27, 'คนชาวอานาโธท หนึ่งร้อยยี่สิบแปดคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 28, 'คนชาวเบธอัสมาเวท สี่สิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 29, 'คนชาวคีริยาทเยอาริม เคฟีราห์ และเบเอโรท เจ็ดร้อยสี่สิบสามคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 30, 'คนชาวรามาห์ และเกบา หกร้อยยี่สิบเอ็ดคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 31, 'คนชาวมิคมาส หนึ่งร้อยยี่สิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 32, 'คนชาวเบธเอลและอัย หนึ่งร้อยยี่สิบสามคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 33, 'คนชาวเนโบอีกแห่งหนึ่ง ห้าสิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 34, 'คนเอลามอีกคนหนึ่ง หนึ่งพันสองร้อยห้าสิบสี่คน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 35, 'คนฮาริม สามร้อยยี่สิบคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 36, 'คนชาวเยรีโค สามร้อยสี่สิบห้าคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 37, 'คนชาวโลด ชาวฮาดิด และชาวโอโน เจ็ดร้อยยี่สิบเอ็ดคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 38, 'คนชาวเสนาอาห์ สามพันเก้าร้อยสามสิบคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 39, 'บรรดาปุโรหิต คนเยดายาห์ คือวงศ์วานของเยชูอา เก้าร้อยเจ็ดสิบสามคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 40, 'คนอิมเมอร์ หนึ่งพันห้าสิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 41, 'คนปาชเฮอร์ หนึ่งพันสองร้อยสี่สิบเจ็ดคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 42, 'คนฮาริม หนึ่งพันสิบเจ็ดคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 43, 'คนเลวี คือคนเยชูอาคือ ของขัดมีเอล และของคนโฮเดวาห์ เจ็ดสิบสี่คน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 44, 'บรรดานักร้องคือ คนอาสาฟ หนึ่งร้อยสี่สิบแปดคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 45, 'คนเฝ้าประตูคือ คนชัลลูม คนอาเทอร์ คนทัลโมน คนอักขูบ คนฮาทิธา คนโชบัย หนึ่งร้อยสามสิบแปดคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 46, 'คนใช้ประจําพระวิหารคือ คนศีหะ คนฮาสูฟา คนทับบาโอท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 47, 'คนเคโรส คนสีอา คนพาโดน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 48, 'คนเลบานา คนฮากาบา คนชัลมัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 49, 'คนฮานัน คนกิดเดล คนกาฮาร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 50, 'คนเรอายาห์ คนเรซีน คนเนโคดา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 51, 'คนกัสซาม คนอุสซาห์ คนปาเสอาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 52, 'คนเบสัย คนเมอูนิม คนเนฟิชิสิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 53, 'คนบัคบูค คนฮาคูฟา คนฮารฮูร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 54, 'คนบัสลีท คนเมหิดา คนฮารชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 55, 'คนบารโขส คนสิเสรา คนเทมาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 56, 'คนเนซิยาห์ คนฮาทิฟา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 57, 'ลูกหลานผู้รับใช้ของซาโลมอน คนโสทัย คนโสเฟเรท คนเปรีดา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 58, 'คนยาอาลา คนดารโคน คนกิดเดล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 59, 'คนเชฟาทิยาห์ คนฮัทธิล คนโปเคเรทแห่งซาบาอิม คนอาโมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 60, 'คนใช้ประจําพระวิหารทั้งสิ้น และลูกหลานแห่งข้าราชการของซาโลมอน มีสามร้อยเก้าสิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 61, 'ต่อไปนี้ เป็นบรรดาคนที่ขึ้นมาจากเทลเมลาห์ เทลฮารชา เครูบ อัดโดน และอิมเมอร์ แต่เขาพิสูจน์เรือนบรรพบุรุษของเขาหรือเชื้อสายของเขาไม่ได้ ว่าเขาเป็นคนอิสราเอลหรือไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 62, 'คือคนเดไลยาห์ คนโทบีอาห์ คนเนโคดา หกร้อยสี่สิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 63, 'จากบรรดาปุโรหิตด้วยคือ คนฮาบายาห์ คนฮักโขส คนบารซิลลัย ผู้มีภรรยาคนหนึ่งเป็นบุตรสาวของบารซิลลัยคนกิเลอาด จึงได้ชื่อตามนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 64, 'คนเหล่านี้หาการลงทะเบียนของเขาในทะเบียนสํามะโนครัวเชื้อสาย แต่หาไม่พบ จึงถือว่าเป็นมลทิน และถูกตัดออกจากตําแหน่งปุโรหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 65, 'ผู้ว่าราชการเมืองสั่งเขามิให้รับอาหารบริสุทธิ์ที่สุด จนกว่าจะมีปุโรหิตที่จะปรึกษากับอูริมและทูมมิมเสียก่อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 66, 'ชุมนุมชนทั้งหมดด้วยกันมีสี่หมื่นสองพันสามร้อยหกสิบคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 67, 'นอกเหนือจากคนใช้ชายหญิงของเขา ซึ่งมีอยู่เจ็ดพันสามร้อยสามสิบเจ็ดคน และเขามีนักร้องสองร้อยสี่สิบห้าคนทั้งชายและหญิง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 68, 'ม้าของเขามีเจ็ดร้อยสามสิบหกตัว ล่อของเขามีสองร้อยสี่สิบห้าตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 69, 'อูฐของเขามีสี่ร้อยสามสิบห้าตัว และลาของเขามีหกพันเจ็ดร้อยยี่สิบตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 70, 'ประมุขของบรรพบุรุษบางคนได้ถวายให้แก่งาน ผู้ว่าราชการถวายเข้าพระคลังเป็นทองคําหนึ่งพันดาริค ชามห้าสิบใบ เสื้อปุโรหิตห้าร้อยสามสิบตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 71, 'และประมุขของบรรพบุรุษบางคนถวายให้แก่พระคลังของงาน เป็นทองคําสองหมื่นดาริค เงินสองพันสองร้อยมาเน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 72, 'และสิ่งที่ประชาชนส่วนที่เหลือถวายนั้น มีทองคําสองหมื่นดาริค เงินสองพันมาเน และเสื้อปุโรหิตหกสิบเจ็ดตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 73, 'ดังนั้นบรรดาปุโรหิต คนเลวี คนเฝ้าประตู นักร้อง ประชาชนบางคน คนใช้ประจําพระวิหาร และคนอิสราเอลทั้งปวงอาศัยอยู่ในหัวเมืองของตน เมื่อถึงเดือนที่เจ็ด คนอิสราเอลอยู่ในหัวเมืองของเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 1, 'ประชาชนทั้งปวงได้ชุมนุมพร้อมหน้ากันที่ถนนซึ่งอยู่หน้าประตูน้ํา และเขาบอกเอสราธรรมาจารย์ให้นําหนังสือพระราชบัญญัติของโมเสส ซึ่งพระเยโฮวาห์ทรงบัญชาแก่อิสราเอลนั้นมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 2, 'เอสราปุโรหิตได้นําพระราชบัญญัติมาหน้าชุมนุมชน ทั้งชายและหญิง และบรรดาผู้ที่ฟังเข้าใจได้ ณ วันต้นของเดือนที่เจ็ด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 3, 'และท่านหันหน้าไปทางถนนซึ่งอยู่หน้าประตูน้ํา อ่านตั้งแต่เช้าตรู่จนเที่ยงวัน ต่อหน้าผู้ชายผู้หญิงกับบรรดาผู้ที่ฟังเข้าใจได้ และประชาชนก็ตะแคงหูฟังหนังสือพระราชบัญญัติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 4, 'เอสราธรรมาจารย์ยืนอยู่บนแท่นไม้ ซึ่งเขาทําไว้เพื่อการนี้ ข้างๆท่านมีมัททีธิยาห์ เชมา อานายาห์ อุรียาห์ ฮิลคียาห์และมาอาเสอาห์ยืนอยู่ข้างขวามือของท่าน กับมีเปดายาห์ มิชาเอล มัลคิยาห์ ฮาชูม ฮัชบัดดานาห์ เศคาริยาห์และเมชุลลามอยู่ข้างซ้ายมือของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 5, 'และเอสราได้เปิดหนังสือต่อสายตาของประชาชนทั้งปวง (เพราะท่านอยู่สูงกว่าประชาชนทั้งปวงนั้น) เมื่อท่านเปิดหนังสือประชาชนทั้งหมดก็ยืนขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 6, 'เอสราสรรเสริญพระเยโฮวาห์ พระเจ้าใหญ่ยิ่ง และประชาชนทั้งปวงตอบว่า “เอเมน เอเมน” พร้อมกับยกมือขึ้น และเขาทั้งหลายโน้มตัวลงนมัสการพระเยโฮวาห์ ซบหน้าลงถึงดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 7, 'อนึ่งเยชูอา บานี เชเรบิยาห์ ยามีน อักขูบ ชับเบธัย โฮดียาห์ มาอาเสอาห์ เคลิทา อาซาริยาห์ โยซาบาด ฮานัน เปไลยาห์และพวกคนเลวี ได้ช่วยประชาชนให้เข้าใจพระราชบัญญัติ ฝ่ายประชาชนก็ยังอยู่ในที่ของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 8, 'และเขาทั้งหลายอ่านจากหนังสือ จากพระราชบัญญัติของพระเจ้าเป็นตอนๆ และเขาก็แปลความ ประชาชนจึงเข้าใจข้อความที่อ่านนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 9, 'และเนหะมีย์ที่เป็นผู้ว่าราชการ และเอสราปุโรหิตและธรรมาจารย์ และคนเลวีผู้สอนประชาชน ได้พูดกับประชาชนทั้งปวงว่า “วันนี้เป็นวันบริสุทธิ์แด่พระเยโฮวาห์พระเจ้าของท่านทั้งหลาย อย่าคร่ําครวญหรือร้องไห้” เพราะประชาชนได้ร้องไห้เมื่อเขาได้ยินถ้อยคําของพระราชบัญญัติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 10, 'แล้วท่านพูดกับเขาทั้งหลายว่า “ไปเถิด ไปรับประทานไขมัน และดื่มน้ําหวาน และส่งส่วนอาหารไปให้คนที่ไม่มีอะไรเตรียมไว้ เพราะว่าวันนี้เป็นวันบริสุทธิ์แด่องค์พระผู้เป็นเจ้าของเรา อย่าโศกเศร้าเลย เพราะความชื่นบานของตนในพระเยโฮวาห์เป็นกําลังของท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 11, 'บรรดาคนเลวีจึงให้ประชาชนทั้งปวงเงียบ กล่าวว่า “จงนิ่งเสีย เพราะวันนี้เป็นวันบริสุทธิ์ อย่าทุกข์โศกเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 12, 'และประชาชนทั้งปวงจึงไปกินและดื่มและส่งส่วนอาหาร เปรมปรีดิ์กันเป็นที่ยิ่ง เพราะเขาทั้งหลายเข้าใจถ้อยคําซึ่งประกาศให้เขาฟังนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 13, 'ณ วันที่สอง ประมุขของบรรพบุรุษแห่งประชาชนทั้งปวง พร้อมกับบรรดาปุโรหิตและคนเลวีมาหาเอสราธรรมาจารย์พร้อมกัน เพื่อจะศึกษาถ้อยคําของพระราชบัญญัติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 14, 'และเขาเห็นเขียนไว้ในพระราชบัญญัติว่า พระเยโฮวาห์ได้ทรงบัญชาโดยทางโมเสสว่า ประชาชนอิสราเอลควรจะอยู่เพิงระหว่างเทศกาลเลี้ยงในเดือนที่เจ็ด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 15, 'และเขาควรจะประกาศและป่าวร้องในหัวเมืองทั้งปวง และในเยรูซาเล็มว่า “จงออกไปที่ภูเขา และนํากิ่งมะกอกเทศ กิ่งไม้สน กิ่งต้นน้ํามันเขียว ใบอินทผลัม และกิ่งไม้ใบดกอื่นๆ เพื่อทําเพิง ดังที่ได้เขียนไว้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 16, 'ประชาชนจึงออกไป เอากิ่งไม้เหล่านั้นมาและทําเพิงสําหรับตัวต่างอยู่บนหลังคาบ้านของตน และตามลานบ้านของตน และในลานพระนิเวศของพระเจ้า และในถนนที่ประตูน้ํา และในถนนที่ประตูเอฟราอิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 17, 'และชุมนุมชนทั้งปวง ผู้ได้กลับมาจากการเป็นเชลยได้ทําเพิงและพักอยู่ในเพิง เขามีความเปรมปรีดิ์ยิ่งนัก เพราะตั้งแต่สมัยของเยชูอาบุตรชายนูนถึงวันนั้นประชาชนอิสราเอลไม่ได้กระทําเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 18, 'และทุกวันท่านอ่านจากหนังสือพระราชบัญญัติของพระเจ้า ตั้งแต่วันแรกจนวันสุดท้าย เขาถือเทศกาลเลี้ยงอยู่เจ็ดวัน และในวันที่แปดมีการประชุมอันศักดิ์สิทธิ์ตามระเบียบปฏิบัติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 1, 'ในวันที่ยี่สิบสี่เดือนนี้ ประชาชนอิสราเอลได้ชุมนุมกันถืออดอาหาร และนุ่งห่มผ้ากระสอบ และเอาดินใส่ศีรษะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 2, 'และเชื้อสายของอิสราเอลได้แยกตนออกจากชนต่างชาติทั้งปวง และยืนสารภาพบาปของตน และสารภาพความชั่วช้าแห่งบรรพบุรุษของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 3, 'และเขาลุกขึ้นในที่ของเขา และอ่านหนังสือพระราชบัญญัติของพระเยโฮวาห์พระเจ้าของเขาอยู่สามชั่วโมง อีกสามชั่วโมงเขาสารภาพและนมัสการพระเยโฮวาห์พระเจ้าของเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 4, 'เยชูอา บานี ขัดมีเอล เชบานิยาห์ บุนนี เชเรบิยาห์ บานีและเคนานี คนเลวี ได้ยืนขึ้นที่บันได และเขาได้ร้องด้วยเสียงดังต่อพระเยโฮวาห์พระเจ้าของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 5, 'แล้วคนเลวี เยชูอา ขัดมีเอล บานี ฮาชับนิยาห์ เชเรบิยาห์ โฮดียาห์ เชบานิยาห์ และเปธาหิยาห์ กล่าวว่า “จงยืนขึ้นและสรรเสริญพระเยโฮวาห์พระเจ้าของท่านทั้งหลายตั้งแต่นิรันดร์กาลจนนิรันดร์กาล สาธุการแด่พระนามอันรุ่งโรจน์ของพระองค์ ซึ่งยิ่งใหญ่เหนือการโมทนาและการสรรเสริญทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 6, 'พระองค์คือพระเยโฮวาห์พระองค์องค์เดียว พระองค์ได้ทรงสร้างฟ้าสวรรค์ ฟ้าสวรรค์อันสูงสุดพร้อมกับบริวารทั้งสิ้นของฟ้าสวรรค์นั้น แผ่นดินโลกและบรรดาสิ่งที่อยู่ในนั้น ทะเลและบรรดาสิ่งที่อยู่ในนั้น และพระองค์ทรงรักษาสิ่งทั้งปวงเหล่านั้นไว้ และบริวารของฟ้าสวรรค์ได้นมัสการพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 7, 'พระองค์คือพระเยโฮวาห์พระเจ้าผู้ทรงเลือกอับราม และทรงนําท่านออกมาจากเมืองเออร์แห่งประเทศเคลเดีย และทรงประทานนามท่านว่าอับราฮัม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 8, 'และพระองค์ทรงเห็นว่าน้ําใจของท่านสัตย์ซื่อต่อพระพักตร์พระองค์ และพระองค์ได้ทรงกระทําพันธสัญญากับท่าน ที่จะประทานแผ่นดินของคนคานาอัน คนฮิตไทต์ คนอาโมไรต์ คนเปริสซี คนเยบุส และคนเกอร์กาชีให้แก่เชื้อสายของท่าน และพระองค์ทรงกระทําให้คําตรัสของพระองค์สําเร็จ เพราะพระองค์ชอบธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 9, 'และพระองค์ทอดพระเนตรความทุกข์ใจของบรรพบุรุษของข้าพระองค์ในอียิปต์ และฟังเสียงร้องทุกข์ของเขาทั้งหลายที่ทะเลแดง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 10, 'และพระองค์ทรงกระทําหมายสําคัญและการมหัศจรรย์สู้ฟาโรห์และข้าราชการทั้งสิ้น และต่อประชาชนทั้งสิ้นแห่งแผ่นดินของฟาโรห์ เพราะพระองค์ทรงทราบว่าเขาทั้งหลายได้ประพฤติอย่างหยิ่งยโสต่อบรรพบุรุษของข้าพระองค์ และพระนามของพระองค์ก็ลือไป ดังทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 11, 'และพระองค์ได้ทรงแยกทะเลต่อหน้าเขาทั้งหลาย เขาจึงเดินไปกลางทะเลบนดินแห้ง และพระองค์ได้ทรงเหวี่ยงผู้ข่มเหงเขาทั้งหลายลงในที่ลึกอย่างกับทรงเหวี่ยงหินลงไปในมหาสมุทร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 12, 'ยิ่งกว่านั้นอีก พระองค์ทรงนําเขาในกลางวันด้วยเสาเมฆและในกลางคืนด้วยเสาเพลิง เพื่อให้แสงแก่เขาในทางที่เขาควรจะไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 13, 'พระองค์เสด็จลงมาบนภูเขาซีนายและตรัสกับเขาจากฟ้าสวรรค์ และประทานคําตัดสินอันชอบ และพระราชบัญญัติที่แท้ กฎเกณฑ์และพระบัญญัติที่ดีแก่เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 14, 'และพระองค์ทรงให้เขาทราบถึงวันสะบาโตบริสุทธิ์ของพระองค์ และทรงบัญชาข้อบังคับ กฎเกณฑ์และพระราชบัญญัติทางโมเสสผู้รับใช้ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 15, 'พระองค์ประทานอาหารแก่เขาจากฟ้าสวรรค์แก้ความหิว และทรงนําน้ําออกมาจากศิลาให้เขาแก้กระหาย และพระองค์ทรงสัญญาไว้ว่าจะให้เขาเข้าไปยึดแผ่นดินซึ่งพระองค์ทรงปฏิญาณว่าจะประทานให้เขานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 16, 'แต่เขาทั้งหลาย คือบรรพบุรุษของข้าพระองค์ทั้งหลายได้ประพฤติอย่างหยิ่งยโส และแข็งคอของเขาเสีย มิได้เชื่อฟังพระบัญญัติของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 17, 'เขาทั้งหลายปฏิเสธไม่เชื่อฟัง และไม่เอาใจใส่ในการมหัศจรรย์ซึ่งพระองค์ทรงประกอบขึ้นท่ามกลางเขา แต่เขาแข็งคอของเขา และในการกบฏนั้นได้แต่งตั้งหัวหน้าเพื่อจะกลับไปสู่ความเป็นทาสเขา แต่พระองค์ทรงเป็นพระเจ้าพร้อมที่จะทรงให้อภัย มีพระทัยเมตตาและกรุณา ทรงพระพิโรธช้า และทรงอุดมด้วยความเมตตา และมิได้ทรงละทิ้งเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 18, 'แม้ว่าเขาทั้งหลายได้สร้างรูปวัวหล่อไว้สําหรับตัวและกล่าวว่า ‘นี่คือพระเจ้าของเจ้า ผู้ทรงนําเจ้าขึ้นมาจากอียิปต์’ และได้กระทําการหมิ่นประมาทอย่างใหญ่หลวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 19, 'ด้วยพระกรุณาซับซ้อนของพระองค์ พระองค์ก็มิได้ทรงละทิ้งเขาในถิ่นทุรกันดาร เสาเมฆซึ่งนําเขาในกลางวันมิได้พรากจากเขาไป หรือเสาเพลิงในกลางคืนซึ่งให้แสงแก่เขาตามทางซึ่งเขาควรจะไปก็มิได้ขาดไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 20, 'พระองค์ประทานพระวิญญาณอันประเสริฐให้สั่งสอนเขา และมิได้ทรงยับยั้งมานาของพระองค์เสียจากปากของเขาทั้งหลาย และประทานน้ําแก้กระหายของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 21, 'เออ พระองค์ทรงชุบเลี้ยงเขาทั้งหลายในถิ่นทุรกันดารสี่สิบปี และเขามิได้ขาดสิ่งใดเลย เสื้อผ้าของเขาไม่ขาดวิ่น และเท้าของเขามิได้บวม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 22, 'และยิ่งกว่านั้นอีก พระองค์ทรงมอบราชอาณาจักรและชนชาติทั้งหลายแก่เขา และทรงปันให้เขาตามเขตแดน เขาจึงได้ยึดแผ่นดินแห่งสิโหน และแผ่นดินของกษัตริย์แห่งเมืองเฮชโบน และแผ่นดินของโอกกษัตริย์แห่งเมืองบาชาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 23, 'พระองค์ทรงทวีลูกหลานของเขาอย่างดวงดาวแห่งฟ้าสวรรค์ และพระองค์ทรงนําเขาเข้าไปในแผ่นดิน ซึ่งพระองค์ตรัสสัญญาไว้กับบรรพบุรุษของเขาให้เข้าไปยึดนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 24, 'ลูกหลานเหล่านั้นจึงเข้าไปและยึดแผ่นดินนั้น พระองค์ทรงปราบปรามชาวแผ่นดินนั้น คือคนคานาอันให้พ้นหน้าเขา และทรงมอบเขาทั้งหลายไว้ในมือของเขา พร้อมกับกษัตริย์และชนชาติทั้งหลายแห่งแผ่นดินนั้น ให้ได้กระทําแก่คนเหล่านั้นตามชอบใจเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 25, 'และเขาจึงเข้ายึดหัวเมืองที่มีป้อม และแผ่นดินอุดม และถือกรรมสิทธิ์เรือนซึ่งเต็มด้วยของดีทั้งปวง ทั้งที่ขังน้ําซึ่งสกัดไว้ สวนองุ่น สวนมะกอกเทศ และต้นผลไม้มากมาย เขาจึงได้กินอิ่มจนอ้วน และปีติยินดีในพระคุณยิ่งของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 26, 'ถึงกระนั้นก็ดี เขาไม่เชื่อฟังและได้กบฏต่อพระองค์ เหวี่ยงพระราชบัญญัติของพระองค์ไว้เบื้องหลัง และได้ฆ่าผู้พยากรณ์ของพระองค์ ผู้ซึ่งได้ตักเตือนเขาเพื่อให้เขากลับมาหาพระองค์ และเขากระทําการหมิ่นประมาทอย่างใหญ่หลวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 27, 'เพราะฉะนั้นพระองค์ทรงมอบเขาไว้ในมือศัตรูของเขา ผู้ซึ่งกระทําให้เขาทนทุกข์และในเวลาแห่งการทนทุกข์ของเขานั้น เขาร้องทูลต่อพระองค์ และพระองค์ทรงฟังเขาจากฟ้าสวรรค์ พระองค์ได้ประทานบรรดาผู้ช่วยแก่เขา ผู้ได้ช่วยเขาให้พ้นจากมือศัตรูของเขาตามพระกรุณาซับซ้อนของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 28, 'แต่เมื่อเขาพักสงบแล้ว เขาก็กระทําความชั่วต่อพระพักตร์พระองค์อีก พระองค์จึงทรงสละเขาไว้ในมือศัตรูของเขา ศัตรูจึงได้ปกครองเขา ถึงกระนั้นเมื่อเขาหันมาร้องทูลต่อพระองค์ พระองค์ทรงฟังเขาจากฟ้าสวรรค์ และพระองค์ทรงช่วยเขาให้พ้นหลายครั้งหลายหน ตามพระกรุณาของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 29, 'และพระองค์ทรงตักเตือนเขา เพื่อว่าจะทรงหันเขาให้กลับมาสู่พระราชบัญญัติของพระองค์ แต่เขาก็ยังประพฤติอย่างเย่อหยิ่งอวดดี ไม่ยอมเชื่อฟังพระบัญญัติของพระองค์ แต่ได้กระทําผิดต่อคําตัดสินของพระองค์ (อันเป็นข้อปฏิบัติซึ่งมนุษย์จะดํารงชีพอยู่ได้) และได้หันบ่าดื้อและคอแข็งเข้าสู้และมิได้เชื่อฟัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 30, 'พระองค์ทรงอดทนกับเขาอยู่หลายปี และทรงเตือนเขาด้วยพระวิญญาณของพระองค์ทางผู้พยากรณ์ของพระองค์ เขาก็ยังไม่เงี่ยหูฟัง เพราะฉะนั้นพระองค์จึงทรงมอบเขาไว้ในมือของชนชาติทั้งหลายแห่งแผ่นดินนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 31, 'ถึงกระนั้นด้วยพระกรุณาซับซ้อนของพระองค์ พระองค์มิได้ทรงกระทําให้เขาพินาศหรือละทิ้งเขาเสีย เพราะพระองค์ทรงเป็นพระเจ้าผู้ทรงพระเมตตาและพระกรุณา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 32, 'ข้าแต่พระเจ้าของข้าพระองค์ทั้งหลาย ซึ่งเป็นพระเจ้าใหญ่ยิ่ง ทรงฤทธิ์และน่าเกรงกลัว ผู้ทรงรักษาพันธสัญญาและความเมตตา ฉะนั้นบัดนี้ขอพระองค์อย่าทรงเห็นว่าความทุกข์ยากลําบากทั้งสิ้นนั้นเป็นแต่สิ่งเล็กน้อยซึ่งบังเกิดขึ้นกับข้าพระองค์ทั้งหลาย กับบรรดากษัตริย์ของข้าพระองค์ กับบรรดาเจ้านาย บรรดาปุโรหิต บรรดาผู้พยากรณ์ บรรพบุรุษ และชนชาติของพระองค์ทั้งสิ้น ตั้งแต่สมัยกษัตริย์อัสซีเรีย จนถึงวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 33, 'แต่ในบรรดาสิ่งที่เกิดขึ้นแก่ข้าพระองค์ทั้งหลาย พระองค์ยุติธรรม เพราะพระองค์ทรงประกอบกิจอย่างเที่ยงตรง แต่ข้าพระองค์ทั้งหลายประพฤติอย่างชั่วร้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 34, 'บรรดากษัตริย์ เจ้านาย ปุโรหิต และบรรพบุรุษของข้าพระองค์ทั้งหลาย มิได้รักษาพระราชบัญญัติของพระองค์ หรือเชื่อฟังพระบัญญัติของพระองค์ และพระโอวาทของพระองค์ซึ่งพระองค์ทรงเตือนเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 35, 'เพราะเขาทั้งหลายมิได้ปรนนิบัติพระองค์ในราชอาณาจักรของเขา ในพระคุณยิ่งของพระองค์ซึ่งพระองค์ทรงประทานแก่เขา และในแผ่นดินที่ใหญ่อุดมซึ่งพระองค์ทรงยกให้แก่เขา และเขามิได้หันกลับจากการชั่วร้ายของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 36, 'ดูเถิด วันนี้ข้าพระองค์ทั้งหลายเป็นทาสในแผ่นดินที่พระองค์ประทานแก่บรรพบุรุษของข้าพระองค์ทั้งหลาย เพื่อให้ได้รับประทานพืชผลกับของอันดีของมัน ดูเถิด ข้าพระองค์ทั้งหลายเป็นทาสในแผ่นดินนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 37, 'และผลิตผลอันมากมายของแผ่นดินนั้นก็ตกแก่กษัตริย์ผู้ที่พระองค์ทรงตั้งไว้เหนือข้าพระองค์ทั้งหลาย ด้วยเหตุบาปของข้าพระองค์ทั้งหลาย เขาทั้งหลายมีอํานาจเหนือร่างกาย และเหนือฝูงสัตว์ของข้าพระองค์ทั้งหลาย ตามความพอใจของเขาทั้งหลาย และข้าพระองค์ทั้งหลายทุกข์นัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 38, 'เหตุบรรดาสิ่งเหล่านี้เราทั้งหลายจึงกระทําพันธสัญญามั่นคงและบันทึกไว้ เจ้านาย คนเลวีและปุโรหิตของเราทั้งหลายจึงประทับตราของเขาไว้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 1, 'บรรดาผู้ที่ประทับตราของเขาไว้คือ เนหะมีย์ผู้ว่าราชการ ผู้เป็นบุตรชายฮาคาลิยาห์ เศเดคียาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 2, 'เสไรอาห์ อาซาริยาห์ เยเรมีย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 3, 'ปาชเฮอร์ อามาริยาห์ มัลคิยาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 4, 'ฮัทธัช เชบานิยาห์ มัลลูค');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 5, 'ฮาริม เมเรโมท โอบาดีห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 6, 'ดาเนียล กินเนโธน บารุค');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 7, 'เมชุลลาม อาบียาห์ มิยามิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 8, 'มาอาซิยาห์ บิลกัย เชไมอาห์ คนเหล่านี้เป็นปุโรหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 9, 'และคนเลวีคือ เยชูอาผู้เป็นบุตรชายอาซันยาห์ บินนุยลูกหลานเฮนาดัด ขัดมีเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 10, 'และพี่น้องของเขา เชบานิยาห์ โฮดียาห์ เคลิทา เปไลยาห์ ฮานัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 11, 'มีคา เรโหบ ฮาชาบิยาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 12, 'ศักเกอร์ เชเรบิยาห์ เชบานิยาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 13, 'โฮดียาห์ บานี เบนินู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 14, 'บรรดาหัวหน้าของประชาชนคือ ปาโรช ปาหัทโมอับ เอลาม ศัทธู บานี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 15, 'บุนนี อัสกาด เบบัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 16, 'อาโดนียาห์ บิกวัย อาดีน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 17, 'อาเทอร์ เฮเซคียาห์ อัสซูร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 18, 'โฮดียาห์ ฮาชูม เบไซ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 19, 'ฮาริฟ อานาโธท เนบัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 20, 'มักปีอาช เมชุลลาม เฮซีร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 21, 'เมเชซาเบล ศาโดก ยาดดูวา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 22, 'เป-ลาทียาห์ ฮานัน อานายาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 23, 'โฮเชยา ฮานันยาห์ หัสชูบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 24, 'ฮัลโลเหช ปิลหา โชเบก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 25, 'เรฮูม ฮาชับนาห์ มาอาเสอาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 26, 'อาหิยาห์ ฮานัน อานัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 27, 'มัลลูค ฮาริม บาอานาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 28, 'ส่วนประชาชนนอกนั้น บรรดาปุโรหิต คนเลวี คนเฝ้าประตู นักร้อง คนใช้ประจําพระวิหาร และคนทั้งปวงผู้ได้แยกตัวออกจากชนชาติทั้งหลายของแผ่นดินเหล่านั้นมาถือพระราชบัญญัติของพระเจ้า ทั้งภรรยาของเขา บุตรชายบุตรสาวของเขา และคนทั้งปวงผู้มีความรู้และความเข้าใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 29, 'ได้สมทบกับพี่น้องของเขา กับขุนนางของเขา ได้เข้าในการสาปแช่งและในการสาบานที่จะดําเนินตามพระราชบัญญัติของพระเจ้า ซึ่งทรงมอบไว้ทางโมเสสผู้รับใช้ของพระเจ้า และที่จะปฏิบัติและกระทําตามพระบัญญัติทั้งสิ้นของพระเยโฮวาห์องค์พระผู้เป็นเจ้าของเรา และตามคําตัดสินและกฎเกณฑ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 30, 'และที่เราทั้งหลายจะไม่ยกบุตรสาวของเราให้แก่ชนชาติทั้งหลายของแผ่นดินนั้น และไม่รับบุตรสาวของเขาทั้งหลายให้แก่บุตรชายของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 31, 'และถ้าชนชาติทั้งหลายของแผ่นดินนั้นนําเครื่องใช้หรือข้าวอย่างใดๆมาขายในวันสะบาโต เราจะไม่ซื้อจากเขาในวันสะบาโตหรือในวันบริสุทธิ์ และเราจะไม่เก็บผลของปีที่เจ็ด และไม่เก็บหนี้สินทุกอย่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 32, 'และเราทั้งหลายกําหนดไว้ว่าจะให้คิดกับตัวเราเป็นรายปีให้เสียคนละจํานวนหนึ่งส่วนสามเชเขล เพื่อการปรนนิบัติในพระนิเวศของพระเจ้าของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 33, 'คือให้เป็นราคาขนมปังหน้าพระพักตร์ ธัญญบูชาเนืองนิตย์ เครื่องเผาบูชาเนืองนิตย์ สําหรับสะบาโตต่างๆ วันขึ้นหนึ่งค่ํา เทศกาลกําหนดต่างๆ สิ่งของบริสุทธิ์ และเครื่องบูชาไถ่บาปเพื่อทําการลบมลทินบาปของพวกอิสราเอล สําหรับงานทุกอย่างในพระนิเวศของพระเจ้าของเราทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 34, 'เราได้จับฉลากด้วย คือบรรดาปุโรหิต คนเลวี และประชาชนทั้งหลายเพื่อเอาฟืนถวาย นําเข้ามาในพระนิเวศของพระเจ้าของเรา ตามเรือนบรรพบุรุษของเรา ตามเวลากําหนดเป็นปีๆไป เพื่อเผาบนแท่นบูชาแห่งพระเยโฮวาห์พระเจ้าของเรา ตามที่บันทึกไว้ในพระราชบัญญัติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 35, 'และเพื่อนําผลแรกแห่งที่ดินของเรา และผลแรกของผลต้นไม้ทั้งสิ้นทุกปี มายังพระนิเวศของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 36, 'และจะนําบุตรชายหัวปี และสัตว์หัวปีของเรา ตามที่บันทึกไว้ในพระราชบัญญัติ และลูกหัวปีแห่งฝูงวัว และฝูงแพะแกะของเรามายังพระนิเวศของพระเจ้าของเรา ยังปุโรหิตผู้ปรนนิบัติอยู่ในพระนิเวศแห่งพระเจ้าของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 37, 'และที่จะนํายอดแป้งเปียกของเรา สิ่งบริจาคของเรา ผลไม้ของต้นไม้ทุกต้น น้ําองุ่นและน้ํามัน มายังบรรดาปุโรหิต มายังห้องพระนิเวศของพระเจ้าของเรา และที่จะนําสิบชักหนึ่งจากแผ่นดินของเรามาให้คนเลวี เพราะคนเลวีเป็นผู้เก็บสิบชักหนึ่งแห่งงานของเราจากหัวเมืองชนบททั้งสิ้นของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 38, 'และปุโรหิต ลูกหลานของอาโรน จะอยู่กับคนเลวีเมื่อคนเลวีได้รับสิบชักหนึ่ง และคนเลวีจะนําสิบชักหนึ่งของสิบชักหนึ่งมายังพระนิเวศของพระเจ้าของเรา มายังห้อง ยังคลังพัสดุ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 39, 'เพราะประชาชนอิสราเอลและคนเลวีจะนําส่วนบริจาคคือ ข้าว น้ําองุ่นใหม่และน้ํามัน มายังห้องซึ่งเป็นที่เก็บเครื่องใช้ของสถานบริสุทธิ์ และที่อยู่ของปุโรหิตผู้ปรนนิบัติ และคนเฝ้าประตู และนักร้อง เราจะไม่เพิกเฉยต่อพระนิเวศของพระเจ้าของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 1, 'พวกประมุขของประชาชนอาศัยอยู่ในเยรูซาเล็ม และประชาชนนอกนั้นจับฉลากกัน เพื่อจะนําเอาคนส่วนหนึ่งในสิบส่วนให้เข้าไปอยู่ในเยรูซาเล็มนครบริสุทธิ์ ฝ่ายอีกเก้าส่วนสิบนั้นให้อยู่ในหัวเมืองต่างๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 2, 'และประชาชนได้โมทนาแก่บรรดาผู้ที่สมัครใจไปอยู่ในเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 3, 'ต่อไปนี้เป็นหัวหน้ามณฑลที่มาอาศัยอยู่ในเยรูซาเล็ม แต่ในหัวเมืองของประเทศยูดาห์ต่างคนต่างอาศัยอยู่ในที่ดินของตนในหัวเมืองของตน คืออิสราเอล บรรดาปุโรหิต คนเลวี คนใช้ประจําพระวิหาร และลูกหลานข้าราชการของซาโลมอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 4, 'บางคนในลูกหลานของยูดาห์และลูกหลานของเบนยามินอาศัยอยู่ในเยรูซาเล็ม ลูกหลานของยูดาห์มี อาธายาห์บุตรชายอุสซียาห์ ผู้เป็นบุตรชายเศคาริยาห์ ผู้เป็นบุตรชายอามาริยาห์ ผู้เป็นบุตรชายเชฟาทิยาห์ ผู้เป็นบุตรชายมาหะลาเลล แห่งคนเปเรศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 5, 'และมาอาเสอาห์บุตรชายบารุค ผู้เป็นบุตรชายคลโฮเซห์ ผู้เป็นบุตรชายฮาซายาห์ ผู้เป็นบุตรชายอาดายาห์ ผู้เป็นบุตรชายโยยาริบ ผู้เป็นบุตรชายเศคาริยาห์ ผู้เป็นบุตรชายชาวชีโลห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 6, 'ลูกหลานของเปเรศทั้งสิ้นที่อาศัยอยู่ในเยรูซาเล็ม มีคนเก่งกล้า สี่ร้อยหกสิบแปดคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 7, 'และต่อไปนี้เป็นคนเบนยามิน คือสัลลูบุตรชายเมชุลลาม ผู้เป็นบุตรชายโยเอด ผู้เป็นบุตรชายเปดายาห์ ผู้เป็นบุตรชายโคลายาห์ ผู้เป็นบุตรชายมาอาเสอาห์ ผู้เป็นบุตรชายอิธีเอล ผู้เป็นบุตรชายเยชายาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 8, 'และถัดเขาไปคือ กับบัย สัลลัย มีเก้าร้อยยี่สิบแปดคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 9, 'โยเอลบุตรชายศิครีเป็นผู้ดูแลเขาทั้งหลาย และเหนือเมืองนั้นยูดาห์บุตรชายเสนูอาห์เป็นที่สอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 10, 'จากบรรดาปุโรหิตคือ เยดายาห์บุตรชายโยยาริบ ยาคีน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 11, 'เสไรอาห์บุตรชายฮิลคียาห์ ผู้เป็นบุตรชายเมชุลลาม ผู้เป็นบุตรชายศาโดก ผู้เป็นบุตรชายเมราโยท ผู้เป็นบุตรชายอาหิทูบ ผู้ปกครองพระนิเวศของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 12, 'และพี่น้องของเขาที่ทํางานอยู่ในพระนิเวศ มีแปดร้อยยี่สิบสองคน และอาดายาห์บุตรชายเยโรฮัม ผู้เป็นบุตรชายเปลาลิยาห์ ผู้เป็นบุตรชายอัมซี ผู้เป็นบุตรชายเศคาริยาห์ ผู้เป็นบุตรชายปาชเฮอร์ ผู้เป็นบุตรชายมัลคิยาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 13, 'และพี่น้องของเขา ประมุขของบรรพบุรุษ มีสองร้อยสี่สิบสองคน และอามาชสัยบุตรชายอาซาเรล ผู้เป็นบุตรชายอัคซัย ผู้เป็นบุตรชายเมซิลเลโมท ผู้เป็นบุตรชายอิมเมอร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 14, 'และพี่น้องของเขาเป็นทแกล้วทหาร มีหนึ่งร้อยยี่สิบแปดคน ผู้ดูแลของเขาคือ ศับดีเอลบุตรชายของคนใหญ่คนโตคนหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 15, 'จากคนเลวีคือ เชไมอาห์บุตรชายหัสชูบ ผู้เป็นบุตรชายอัสรีคัม ผู้เป็นบุตรชายฮาชาบิยาห์ ผู้เป็นบุตรชายบุนนี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 16, 'และชับเบธัยกับโยซาบาด จากพวกหัวหน้าของคนเลวี ผู้ควบคุมการงานภายนอกพระนิเวศของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 17, 'และมัทธานิยาห์บุตรชายมีคา ผู้เป็นบุตรชายศับดี ผู้เป็นบุตรชายอาสาฟ ผู้เป็นหัวหน้าในการเริ่มต้นการโมทนาพระคุณในการอธิษฐาน และบัคบูคิยาห์เป็นที่สองในหมู่พี่น้องของเขา และอับดาบุตรชายชัมมูอา ผู้เป็นบุตรชายกาลาล ผู้เป็นบุตรชายเยดูธูน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 18, 'คนเลวีทั้งหมดในนครบริสุทธิ์มี สองร้อยแปดสิบสี่คน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 19, 'คนเฝ้าประตูมี อักขูบ ทัลโมนและพี่น้องของเขา ผู้เฝ้าบรรดาประตูมีหนึ่งร้อยเจ็ดสิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 20, 'คนอิสราเอลนอกนั้น ที่เป็นพวกปุโรหิตและคนเลวี อยู่ในหัวเมืองทั้งสิ้นของยูดาห์ ทุกคนอยู่ในที่ดินมรดกของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 21, 'แต่คนใช้ประจําพระวิหารอยู่ที่โอเฟล และศีหะกับกิชปาควบคุมคนใช้ประจําพระวิหาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 22, 'ผู้ดูแลคนเลวีในเยรูซาเล็มคือ อุสซีบุตรชายบานี ผู้เป็นบุตรชายฮาชาบิยาห์ ผู้เป็นบุตรชายมัทธานิยาห์ ผู้เป็นบุตรชายมีคา สําหรับลูกหลานของอาสาฟ พวกนักร้องดูแลการงานพระนิเวศของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 23, 'เพราะมีพระบัญชาจากกษัตริย์ถึงเรื่องเขา และมีของส่วนแบ่งที่ได้ตกลงกันไว้สําหรับนักร้อง ตามที่ต้องการทุกๆวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 24, 'และเปธาหิยาห์บุตรชายเมเชซาเบล คนเศ-ราห์ บุตรชายยูดาห์เป็นสนองโอษฐ์ของกษัตริย์ในเรื่องกิจการต่างๆอันเกี่ยวกับประชาชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 25, 'ส่วนที่ชนบทและไร่นาของชนบทเหล่านั้น ประชาชนพวกยูดาห์บางคนอาศัยอยู่ในคีริยาทอารบา และชนบทของเมืองนั้น และในดีโบนกับชนบทของเมืองนั้น และในเยขับเซเอลกับชนบทของเมืองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 26, 'และในเยชูอากับในโมลาดาห์ และเบธเปเลท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 27, 'ในฮาซารชูอาล ในเบเออร์เชบากับชนบทของเมืองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 28, 'ในศิกลาก ในเมโคนาห์กับชนบทของเมืองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 29, 'ในเอนริมโมน ในโศราห์ ในยารมูท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 30, 'ศาโนอาห์ อดุลลัมและชนบทของเมืองนั้น ลาคีชและไร่นาของเมืองนั้น อาเซคาห์กับชนบทของเมืองนั้น เขาจึงตั้งค่ายจากเบเออร์เชบาถึงหุบเขาฮินโนม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 31, 'ประชาชนเบนยามินอยู่ต่อจากเกบาไปด้วย ที่มิคมาช ที่อัยยา เบธเอลและชนบทของเมืองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 32, 'ที่อานาโธท โนบ อานานิยาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 33, 'ฮาโซร์ รามาห์ กิททาอิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 34, 'ฮาดิด เสโบอิม เนบัลลัท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 35, 'โลด และโอโน หุบเขาของพวกช่างฝีมือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 36, 'และบางส่วนของคนเลวีอยู่ในยูดาห์และในเบนยามิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 1, 'ต่อไปนี้เป็นปุโรหิตและคนเลวีที่ขึ้นมากับเศรุบบาเบลบุตรชายเชอัลทิเอล และกับเยชูอาคือ เสไรอาห์ เยเรมีย์ เอสรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 2, 'อามาริยาห์ มัลลูค ฮัทธัช');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 3, 'เชคานิยาห์ เรฮูม เมเรโมท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 4, 'อิดโด กินเนโธน อาบียาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 5, 'มิยามิน มาอาดียาห์ บิลกาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 6, 'เชไมอาห์ โยยาริบ เยดายาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 7, 'สัลลู อาโมค ฮิลคียาห์ เยดายาห์ คนเหล่านี้เป็นปุโรหิตใหญ่และพี่น้องของเขาในสมัยของเยชูอา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 8, 'คนเลวีคือ เยชูอา บินนุย ขัดมีเอล เชเรบิยาห์ ยูดาห์ และมัทธานิยาห์ ผู้ซึ่งดูแลการเพลงโมทนาพร้อมกับพี่น้องของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 9, 'และบัคบูคิยาห์ กับอุนนีพี่น้องของเขา ยืนอยู่ตรงกันข้ามในการปรนนิบัติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 10, 'และเยชูอาให้กําเนิดบุตรชื่อโยยาคิม โยยาคิมให้กําเนิดบุตรชื่อเอลียาชีบ เอลียาชีบให้กําเนิดบุตรชื่อโยยาดา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 11, 'โยยาดาให้กําเนิดบุตรชื่อโยนาธาน และโยนาธานให้กําเนิดบุตรชื่อยาดดูวา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 12, 'และในรัชกาลโยยาคิม มีปุโรหิตผู้เป็นประมุขของบรรพบุรุษคือ ของคนเสไรอาห์มี เมรายาห์ ของคนเยเรมีย์มี ฮานันยาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 13, 'ของคนเอสรามี เมชุลลาม ของคนอามาริยาห์มี เยโฮฮานัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 14, 'ของคนมัลลูคมี โยนาธาน ของคนเชบานิยาห์มี โยเซฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 15, 'ของคนฮาริมมี อัดนา ของคนเมราโยทมี เฮลคาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 16, 'ของคนอิดโดมี เศคาริยาห์ ของคนกินเนโธนมี เมชุลลาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 17, 'ของคนอาบียาห์มี ศิครี ของคนมินยามิน ของคนโมอัดยาห์มี ปิลทัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 18, 'ของคนบิลกาห์มี ชัมมูอา ของคนเชไมอาห์มี เยโฮนาธัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 19, 'และของคนโยยาริบมี มัทเธนัย ของคนเยดายาห์มี อุสซี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 20, 'ของคนสัลลัยมี คาลลัย ของคนอาโมคมี เอเบอร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 21, 'ของคนฮิลคียาห์มี ฮาชาบิยาห์ ของคนเยดายาห์มี เนธันเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 22, 'ส่วนคนเลวีในสมัยของเอลียาชีบ โยยาดา โยฮานัน และยาดดูวา ชื่อประมุขของบรรพบุรุษมีบันทึกไว้ทั้งบรรดาปุโรหิตจนถึงรัชสมัยของดาริอัสคนเปอร์เซีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 23, 'ลูกหลานของเลวี ประมุขของบรรพบุรุษ มีบันทึกไว้ในหนังสือพงศาวดาร จนสมัยของโยฮานันบุตรชายเอลียาชีบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 24, 'และหัวหน้าของคนเลวีคือ ฮาชาบิยาห์ เชเรบิยาห์ และเยชูอาบุตรชายขัดมีเอล กับญาติพี่น้องของเขาอยู่ตรงกันข้าม ที่จะสรรเสริญและโมทนาพระคุณ ตามบัญญัติของดาวิดคนของพระเจ้า เป็นยามๆไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 25, 'มัทธานิยาห์ บัคบูคิยาห์ โอบาดีห์ เมชุลลาม ทัลโมน และอักขูบ เป็นคนเฝ้าประตู ยืนเฝ้าอยู่ที่โรงพัสดุของประตู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 26, 'คนเหล่านี้อยู่ในสมัยของโยยาคิมบุตรชายเยชูอา ผู้เป็นบุตรชายโยซาดัก และในสมัยของเนหะมีย์ผู้ว่าราชการ กับในสมัยของเอสราปุโรหิต และธรรมาจารย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 27, 'คราวเมื่อทําพิธีมอบถวายกําแพงเยรูซาเล็ม เขาได้แสวงหาคนเลวีตามที่ของเขาทั่วทุกแห่ง เพื่อจะนําเขามาที่เยรูซาเล็ม เพื่อฉลองมอบถวายด้วยความยินดี ด้วยการโมทนาและด้วยการร้องเพลง ด้วยฉาบ พิณใหญ่ และพิณเขาคู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 28, 'ลูกหลานพวกนักร้องได้รวมกันมาจากมณฑลรอบเยรูซาเล็ม และจากชนบทของชาวเนโทฟาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 29, 'ทั้งมาจากวงศ์วานกิลกาล และจากเขตเกบาและอัสมาเวท เพราะบรรดานักร้องได้สร้างชนบทของตนรอบเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 30, 'บรรดาปุโรหิตและคนเลวีได้ชําระตนให้บริสุทธิ์ และเขาทั้งหลายได้ชําระประชาชน และประตูเมือง กับกําแพงให้บริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 31, 'แล้วข้าพเจ้าได้นําเจ้านายแห่งยูดาห์ขึ้นบนกําแพง และแต่งตั้งให้คณะใหญ่สองคณะ เป็นผู้กล่าวโมทนาและเดินเป็นกระบวนแห่ คณะหนึ่งไปทางขวาขึ้นไปบนกําแพงจนถึงประตูกองขยะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 32, 'และถัดเขาไปมี โฮชายาห์ และเจ้านายแห่งยูดาห์ครึ่งหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 33, 'กับอาซาริยาห์ เอสรา เมชุลลาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 34, 'ยูดาห์ เบนยามิน เชไมอาห์ และเยเรมีย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 35, 'และบุตรชายของพวกปุโรหิตบางคนที่มีแตรคือ เศคาริยาห์บุตรชายโยนาธาน ผู้เป็นบุตรชายเชไมอาห์ ผู้เป็นบุตรชายมัทธานิยาห์ ผู้เป็นบุตรชายมีคายาห์ ผู้เป็นบุตรชายศักเกอร์ ผู้เป็นบุตรชายอาสาฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 36, 'กับญาติพี่น้องของเขาคือ เชไมอาห์ อาซาเรล มิลาลัย กิลาลัย มาอัย เนธันเอลและยูดาห์ ฮานานี พร้อมกับเครื่องดนตรีของดาวิดคนของพระเจ้า และเอสราธรรมาจารย์ได้เดินนําหน้าเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 37, 'ที่ประตูน้ําพุ ซึ่งอยู่ตรงข้ามกับพวกเขา เขาทั้งหลายเดินขึ้นบันไดของนครดาวิด ที่ทางขึ้นกําแพงเหนือพระราชวังของดาวิดถึงประตูน้ําทางทิศตะวันออก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 38, 'อีกคณะหนึ่งที่กล่าวคําโมทนาเดินไปทางตรงกันข้าม และข้าพเจ้าตามเขาไป พร้อมกับประชาชนครึ่งหนึ่ง บนกําแพงเหนือหอคอยเตาไฟ ถึงกําแพงกว้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 39, 'และเหนือประตูเอฟราอิม และทางประตูเก่า และทางประตูปลา และหอคอยฮานันเอล และหอคอยเมอาห์ ถึงประตูแกะ และเขามาหยุดอยู่ที่ประตูยาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 40, 'คณะทั้งสองผู้กล่าวคําโมทนาได้มายืนอยู่ที่พระนิเวศของพระเจ้า ทั้งข้าพเจ้าและเจ้าหน้าที่ครึ่งหนึ่งอยู่กับข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 41, 'กับปุโรหิตที่ถือแตรคือ เอลียาคิม มาอาเสอาห์ มินยามิน มีคายาห์ เอลีโอนัย เศคาริยาห์ กับฮานันยาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 42, 'และมาอาเสอาห์ เชไมอาห์ เอเลอาซาร์ อุสซี เยโฮฮานัน มัลคิยาห์ เอลาม และเอเซอร์ และบรรดานักร้องได้ร้องเพลงด้วยเสียงดัง มีอิสราหิยาห์เป็นหัวหน้าของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 43, 'และเขาทั้งหลายได้ถวายเครื่องสัตวบูชาใหญ่โตในวันนั้น และเปรมปรีดิ์ เพราะพระเจ้าทรงกระทําให้เขาเปรมปรีดิ์ด้วยความชื่นบานใหญ่ยิ่ง พวกภรรยาและเด็กๆก็เปรมปรีดิ์ด้วย และความชื่นบานของเยรูซาเล็มก็ได้ยินไปไกล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 44, 'ในวันนั้น เขาแต่งตั้งบางคนให้ดูแลห้องสําหรับพัสดุ ของบริจาค ผลไม้รุ่นแรก ส่วนสิบชักหนึ่ง ให้รวบรวมส่วนแบ่งซึ่งกําหนดไว้ในพระราชบัญญัติสําหรับปุโรหิตและคนเลวีเข้ามาไว้ในนั้น ตามไร่นาในหัวเมืองเหล่านั้น เพราะยูดาห์เปรมปรีดิ์ด้วยเรื่องบรรดาปุโรหิต และคนเลวีผู้ปรนนิบัติอยู่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 45, 'และทั้งพวกนักร้องและพวกเฝ้าประตูได้ทําการปรนนิบัติพระเจ้าของเขาและทําการชําระให้บริสุทธิ์ ตามพระบัญชาของดาวิดและของซาโลมอนราชโอรสของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 46, 'เพราะในสมัยดาวิดและอาสาฟในดึกดําบรรพ์นั้นมีหัวหน้าพวกนักร้อง และมีบทเพลงสรรเสริญ และบทเพลงโมทนาพระคุณพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 47, 'และอิสราเอลทั้งปวงในสมัยของเศรุบบาเบลและในสมัยของเนหะมีย์ ได้ให้ส่วนแบ่งตามความต้องการทุกวันแก่นักร้องและคนเฝ้าประตู และเขาได้กันส่วนบริสุทธิ์ของคนเลวีไว้ต่างหาก และคนเลวีได้กันส่วนของลูกหลานอาโรนไว้ต่างหาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 1, 'ในวันนั้น เขาอ่านหนังสือของโมเสสให้ประชาชนฟัง และเขาพบที่มีเขียนไว้ว่า ไม่ควรให้คนอัมโมนหรือคนโมอับเข้าไปในที่ชุมนุมของพระเจ้าเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 2, 'เพราะเขามิได้เอาอาหารและน้ํามาต้อนรับคนอิสราเอล แต่ได้จ้างบาลาอัมให้มาต่อต้านและแช่งเขา แต่พระเจ้าของเราทรงเปลี่ยนคําแช่งเป็นพร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 3, 'และอยู่มาเมื่อประชาชนได้ยินพระราชบัญญัติ เขาก็แยกอิสราเอลออกเสียจากคนต่างด้าวทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 4, 'ก่อนหน้านี้ เอลียาชีบปุโรหิตผู้ได้รับการแต่งตั้งให้ดูแลห้องในพระนิเวศของพระเจ้าของเรา และผู้เกี่ยวพันกับโทบีอาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 5, 'ได้จัดห้องใหญ่ห้องหนึ่งให้โทบีอาห์ เป็นห้องที่แต่ก่อนใช้เก็บธัญญบูชา กํายาน เครื่องใช้ต่างๆ และสิบชักหนึ่งที่เป็นข้าว น้ําองุ่นใหม่ และน้ํามัน ซึ่งเขาให้ไว้ตามบัญญัติให้แก่คนเลวี นักร้อง คนเฝ้าประตูและของบริจาคสําหรับปุโรหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 6, 'เมื่อเกิดเรื่องนี้ข้าพเจ้ามิได้อยู่ในเยรูซาเล็ม เพราะในปีที่สามสิบสองแห่งรัชกาลอารทาเซอร์ซีสกษัตริย์แห่งบาบิโลนนั้น ข้าพเจ้าได้ไปเฝ้ากษัตริย์ และอีกไม่กี่วันข้าพเจ้าก็ทูลลากษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 7, 'และมายังเยรูซาเล็ม แล้วข้าพเจ้าจึงทราบความชั่วร้ายซึ่งเอลียาชีบได้กระทําเพื่อโทบีอาห์ คือจัดห้องภายในบริเวณพระนิเวศของพระเจ้าให้เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 8, 'ข้าพเจ้าโกรธนัก และข้าพเจ้าก็โยนเครื่องแต่งเรือนทั้งสิ้นของโทบีอาห์ออกเสียจากห้อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 9, 'แล้วข้าพเจ้าสั่งให้เขาชําระห้อง และข้าพเจ้าก็นําเครื่องใช้ประจําพระนิเวศของพระเจ้า ทั้งธัญญบูชากับกํายานกลับมาไว้ที่นั่นอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 10, 'และข้าพเจ้ายังทราบอีกว่า ส่วนของคนเลวีนั้น เขาก็ไม่ได้มอบให้ เพราะฉะนั้นคนเลวีและนักร้องผู้ปฏิบัติการงาน ต่างก็หนีกลับไปยังไร่นาของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 11, 'ข้าพเจ้าจึงต่อว่าเจ้าหน้าที่และพูดว่า “ทําไมจึงทอดทิ้งพระนิเวศของพระเจ้าเสีย” ข้าพเจ้าจึงรวบรวมเขากลับมา และตั้งเขาไว้ตามตําแหน่งของเขาอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 12, 'และยูดาห์ทั้งปวงได้นําสิบชักหนึ่งที่เป็นข้าว น้ําองุ่นใหม่ และน้ํามันเข้ามายังเรือนพัสดุ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 13, 'ข้าพเจ้าได้แต่งตั้งคนให้ดูแลเรือนพัสดุคือ เชเลมิยาห์ปุโรหิต ศาโดกธรรมาจารย์ และเปดายาห์แห่งคนเลวี และผู้ช่วยของเขาคือ ฮานันบุตรชายศักเกอร์ ผู้เป็นบุตรชายมัทธานิยาห์ เพราะนับได้ว่าเขาสัตย์ซื่อ และหน้าที่ของเขาคือแจกจ่ายแก่พวกพี่น้อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 14, '“โอ ข้าแต่พระเจ้าของข้าพระองค์ เกี่ยวกับเรื่องนี้ขอทรงระลึกถึงข้าพระองค์ และขออย่าทรงลบล้างการที่ดีทั้งหลายของข้าพระองค์ที่ข้าพระองค์ได้กระทํา เพื่อพระนิเวศของพระเจ้าของข้าพระองค์ และเพื่อการปรนนิบัติในที่นั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 15, 'ครั้งนั้นในยูดาห์ ข้าพเจ้าเห็นคนย่ําน้ําองุ่นในวันสะบาโต และนําฟ่อนข้าวเข้ามาบรรทุกหลังลา ทั้งน้ําองุ่น ผลองุ่น มะเดื่อ และภาระทุกอย่าง ซึ่งเขานํามายังเยรูซาเล็มในวันสะบาโต ข้าพเจ้าได้ตักเตือนเขาในวันที่เขาทั้งหลายขายอาหาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 16, 'และมีคนชาวไทระอาศัยอยู่ในเมืองได้นําปลาและสินค้าทุกอย่างเข้ามาขายในวันสะบาโตแก่ประชาชนยูดาห์ และในเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 17, 'แล้วข้าพเจ้าได้ต่อว่าพวกขุนนางแห่งยูดาห์ และพูดกับเขาว่า “ทําไมท่านทั้งหลายกระทําความชั่วร้ายเช่นนี้ กระทําให้วันสะบาโตเป็นมลทิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 18, 'บรรพบุรุษของท่านมิได้กระทําเช่นนี้หรือ และพระเจ้าของเรามิได้ทรงนําเหตุร้ายทั้งสิ้นให้ตกอยู่บนเราและบนเมืองนี้หรือ ท่านยังจะนําพระพิโรธยิ่งกว่านั้นมาเหนืออิสราเอลด้วยการกระทําให้วันสะบาโตเป็นมลทิน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 19, 'และอยู่มาพอเริ่มมืดที่ประตูเมืองเยรูซาเล็มก่อนวันสะบาโต ข้าพเจ้าได้บัญชาให้ปิดประตูเมือง และสั่งว่า ไม่ให้เปิดจนกว่าจะพ้นวันสะบาโตแล้ว และข้าพเจ้าก็ตั้งข้าราชการบางคนของข้าพเจ้าให้ดูแลประตูเมือง ว่าไม่ให้นําภาระสิ่งใดเข้ามาในวันสะบาโต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 20, 'แล้วพวกพ่อค้าและพวกขายสินค้าทุกชนิดค้างอยู่นอกเยรูซาเล็มหนหนึ่ง หรือสองหน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 21, 'ข้าพเจ้าได้ตักเตือนเขา และพูดกับเขาว่า “ทําไมท่านมานอนอยู่ข้างกําแพงเมือง ถ้าท่านทําอีกข้าพเจ้าจะจับท่าน” ตั้งแต่คราวนั้นมาเขาก็ไม่มาอีกในวันสะบาโต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 22, 'และข้าพเจ้าบัญชาคนเลวีให้ชําระตัวเขาและมาเฝ้าประตูเมือง เพื่อรักษาวันสะบาโตให้บริสุทธิ์ “โอ ข้าแต่พระเจ้าของข้าพระองค์ ขอพระองค์ทรงระลึกถึงข้าพระองค์ในเรื่องนี้ด้วย และขอทรงไว้ชีวิตข้าพระองค์ตามความยิ่งใหญ่แห่งความเมตตาของพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 23, 'ในสมัยนั้นข้าพเจ้าได้เห็นพวกยิวผู้ได้แต่งงานกับหญิงชาวอัชโดด อัมโมนและโมอับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 24, 'และเด็กของเขาครึ่งหนึ่งพูดภาษาอัชโดด เขาพูดภาษาฮีบรูไม่ได้ แต่พูดภาษาชนชาติของเขาแต่ละพวก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 25, 'ข้าพเจ้าได้โต้แย้งกับเขา และแช่งเขา และเฆี่ยนตีเขาบางคนและดึงผมของเขาออก และข้าพเจ้ากระทําให้เขาปฏิญาณในพระนามของพระเจ้า ด้วยข้าพเจ้ากล่าวว่า “เจ้าทั้งหลายอย่ายกบุตรสาวของเจ้าให้แก่บุตรชายของเขา หรือรับบุตรสาวของเขาให้แก่บุตรชายของเจ้า หรือตัวเจ้าเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 26, 'ซาโลมอนกษัตริย์แห่งอิสราเอล มิได้ทําบาปด้วยเรื่องหญิงอย่างนี้หรือ ท่ามกลางหลายประชาชาติไม่มีกษัตริย์ใดเหมือนพระองค์ และพระเจ้าของพระองค์ก็ทรงรักพระองค์ และพระเจ้าทรงกระทําให้พระองค์เป็นกษัตริย์เหนืออิสราเอลทั้งปวง ถึงกระนั้นก็ดี แม้เป็นพระองค์หญิงต่างชาติก็เป็นเหตุให้พระองค์ทรงทําบาป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 27, 'ควรหรือที่เราจะฟังเจ้าและกระทําความชั่วร้ายใหญ่ยิ่งนี้ทั้งสิ้น และประพฤติละเมิดต่อพระเจ้าของเราด้วยการแต่งงานกับหญิงต่างชาติ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 28, 'บุตรชายคนหนึ่งของโยยาดา ผู้เป็นบุตรชายเอลียาชีบมหาปุโรหิต เป็นบุตรเขยของสันบาลลัท ชาวโฮโรนาอิม เพราะฉะนั้นข้าพเจ้าจึงขับไล่เขาไปเสียจากข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 29, '“โอ ข้าแต่พระเจ้าของข้าพระองค์ ขอทรงระลึกถึงเขาทั้งหลาย เพราะว่าเขาทั้งหลายได้กระทําให้การเป็นปุโรหิต และพันธสัญญาของพวกปุโรหิตและคนเลวีเป็นมลทิน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 30, 'ดังนี้แหละ ข้าพเจ้าได้ชําระเขาจากคนต่างด้าวทุกคน และข้าพเจ้าได้ตั้งหน้าที่ของบรรดาปุโรหิตและคนเลวีต่างก็ประจํางานของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 31, 'ข้าพเจ้าได้จัดให้หาฟืนถวายตามเวลากําหนดและสําหรับผลรุ่นแรกด้วย “โอ ข้าแต่พระเจ้าของข้าพระองค์ ขอทรงระลึกถึงข้าพระองค์ให้เกิดผลดีเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 1, 'อยู่มาในรัชสมัยของอาหสุเอรัส (อาหสุเอรัสผู้ทรงครอบครองตั้งแต่ประเทศอินเดียถึงประเทศเอธิโอเปีย เหนือหนึ่งร้อยยี่สิบเจ็ดมณฑลนั้น)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 2, 'ในสมัยที่กษัตริย์อาหสุเอรัสประทับบนบัลลังก์แห่งราชอาณาจักรของพระองค์ในสุสาปราสาท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 3, 'ในปีที่สามแห่งรัชกาลของพระองค์ พระองค์พระราชทานการเลี้ยงแก่เจ้านาย และบรรดาข้าราชการของพระองค์ นายทัพนายกองทัพแห่งเปอร์เซียและมีเดีย และขุนนางกับผู้ว่าราชการมณฑลเฝ้าอยู่ต่อพระพักตร์พระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 4, 'ขณะที่พระองค์ทรงแสดงราชสมบัติแห่งราชอาณาจักรอันรุ่งเรืองของพระองค์ ทั้งความโอ่อ่าตระการอันรุ่งโรจน์ของพระองค์อยู่เป็นเวลาหลายวัน ถึงหนึ่งร้อยแปดสิบวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 5, 'เมื่อวันเหล่านี้ผ่านพ้นไปแล้ว กษัตริย์ทรงจัดการเลี้ยงแก่บรรดาประชาชนผู้อยู่ในสุสาปราสาท ทั้งผู้ใหญ่ผู้น้อย นานเจ็ดวันในลานอุทยานแห่งสํานักพระราชวังของกษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 6, 'มีผ้าม่านฝ้ายสีขาวและสีม่วงคล้ํา มีสายป่านและเชือกขนแกะสีม่วงคล้องห่วงเงินและเสาหินอ่อน ทั้งเตียงทองคําและเงินบนพื้นลาดปูนฝังหินแดง หินอ่อน มุกดา และหินอ่อนสีดํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 7, 'เครื่องดื่มก็ใส่ถ้วยทองคําส่งให้ (เป็นถ้วยหลากชนิด) และเหล้าองุ่นของราชสํานักมากมายตามพระทัยกว้างขวางของกษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 8, 'การดื่มก็กระทํากันตามกฎหมายที่ไม่มีการบังคับ เพราะกษัตริย์ทรงมีพระกระแสรับสั่งไปยังพนักงานทั้งปวงว่า ให้ทุกคนทําได้ตามใจปรารถนา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 9, 'พระราชินีวัชทีก็พระราชทานการเลี้ยงแก่สตรีในราชสํานักซึ่งเป็นของกษัตริย์อาหสุเอรัสด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 10, 'ณ วันที่เจ็ดเมื่อพระทัยของกษัตริย์รื่นเริงด้วยเหล้าองุ่น พระองค์ทรงบัญชาเมหุมาน บิสธา ฮารโบนา บิกธาและอาบักธา เศธาร์ และคารคาส ขันทีทั้งเจ็ดผู้ปรนนิบัติต่อพระพักตร์กษัตริย์อาหสุเอรัส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 11, 'ให้ไปเชิญพระราชินีวัชทีสวมมงกุฎมาเฝ้ากษัตริย์ เพื่อจะให้ประชาชนและเจ้านายของพระองค์ได้ชมสง่าราศีโฉมของพระนาง เพราะพระนางงามนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 12, 'แต่พระราชินีวัชทีทรงปฏิเสธไม่มาตามพระบัญชาของกษัตริย์ที่รับสั่งไปกับขันที เมื่อเป็นเช่นนี้กษัตริย์ทรงเดือดดาล และพระพิโรธของพระองค์ระอุอยู่ในพระอุระ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 13, 'ฝ่ายกษัตริย์จึงตรัสกับคนที่มีปัญญาผู้ทราบกาลเทศะ (เพราะนี่เป็นวิธีดําเนินการของกษัตริย์ต่อบรรดาผู้ที่เจนจัดในกฎหมายและการพิพากษา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 14, 'ผู้ที่รองพระองค์คือ คารเชนา เชธาร์ อัดมาธา ทารชิช เมเรส มารเสนา และเมมูคาน เจ้านายทั้งเจ็ดของเปอร์เซียและมีเดีย ผู้เคยเข้าเฝ้ากษัตริย์ และนั่งก่อนในราชอาณาจักร)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 15, 'ว่า “ตามกฎหมายจะต้องกระทําอะไรต่อพระราชินีวัชที เพราะว่าพระนางมิได้ปฏิบัติตามพระบัญชาของกษัตริย์อาหสุเอรัสซึ่งรับสั่งไปกับขันที”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 16, 'เมมูคานจึงทูลต่อพระพักตร์กษัตริย์และเจ้านายทั้งปวงว่า “พระราชินีวัชทีได้ทรงกระทําผิดมิใช่ต่อกษัตริย์เท่านั้น แต่ต่อเจ้านายทั้งปวงและประชาชนทั้งปวงผู้อยู่ในมณฑลทั้งสิ้นของกษัตริย์อาหสุเอรัส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 17, 'เพราะสิ่งที่พระราชินีทรงกระทํานี้จะเป็นที่ทราบแก่สตรีทั้งปวง ทําให้เขามองดูสามีของเขาด้วยความประมาท เพราะเขาจะพูดว่า ‘กษัตริย์อาหสุเอรัสมีพระบัญชาให้นําพระราชินีวัชทีมาต่อพระพักตร์พระองค์ แต่พระนางไม่เสด็จมา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 18, 'ในวันนี้ทีเดียวเจ้านายผู้หญิงแห่งเปอร์เซียและมีเดียซึ่งได้ยินถึงสิ่งที่พระราชินีทรงกระทํานี้ ก็จะเล่าให้เจ้านายทั้งปวงของกษัตริย์รู้ทั่วกัน ทําให้มีความประมาทและความโกรธขึ้นเป็นอันมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 19, 'ถ้าเป็นที่พอพระทัยกษัตริย์ ขอให้มีพระราชโองการจากพระองค์ และให้บันทึกไว้ในกฎหมายของคนเปอร์เซียและคนมีเดีย อย่างที่คืนคําไม่ได้ว่า ‘วัชทีจะเข้าเฝ้ากษัตริย์อาหสุเอรัสอีกไม่ได้’ และขอกษัตริย์ประทานตําแหน่งราชินีให้แก่ผู้อื่นที่ดีกว่าพระนาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 20, 'ดังนั้นเมื่อกษัตริย์ทรงประกาศกฤษฎีกา ตลอดพระราชอาณาจักรของพระองค์ (อันกว้างใหญ่อย่างยิ่งนั้น) สตรีทั้งปวงจะต้องให้เกียรติสามีของตน ไม่ว่าสูงหรือต่ํา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 21, 'คําทูลแนะนํานี้เป็นที่พอพระทัยกษัตริย์และเจ้านาย กษัตริย์จึงทรงกระทําตามที่เมมูคานทูลเสนอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 22, 'พระองค์ทรงมีพระอักษรไปทั่วราชมณฑลของกษัตริย์ ถึงทุกมณฑลตามอักขระของมณฑลนั้น และถึงทุกชาติตามภาษาของเขา ให้ชายทุกคนเป็นเจ้าเป็นนายในเรือนของตน และให้ประกาศกฤษฎีกานี้ตามภาษาของแต่ละชนชาติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 1, 'ภายหลังเหตุการณ์เหล่านี้ เมื่อพระพิโรธของกษัตริย์อาหสุเอรัสสงบลง พระองค์ทรงระลึกถึงวัชทีและสิ่งที่พระนางทรงกระทํา และกฤษฎีกาที่พระองค์ทรงออกเรื่องพระนาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 2, 'ข้าราชการของกษัตริย์ผู้ปรนนิบัติพระองค์อยู่จึงทูลว่า “ขอทรงให้หาหญิงพรหมจารีสาวสวยมาถวายกษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 3, 'และขอกษัตริย์ทรงแต่งตั้งเจ้าหน้าที่ทุกมณฑลแห่งราชอาณาจักรของพระองค์ เพื่อให้คนเหล่านี้รวบรวมหญิงสาวพรหมจารีงดงามทั้งหลายมายังฮาเร็มในสุสาปราสาท ให้อยู่ในอารักขาของเฮกัยข้าราชบริพารในพระราชสํานักของกษัตริย์ ผู้ดูแลสตรี และขอประทานเครื่องชําระล้างสําหรับหญิงเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 4, 'และขอให้หญิงสาวคนที่กษัตริย์พอพระทัยได้เป็นพระราชินีแทนวัชที” ข้อนี้พอพระทัยกษัตริย์ พระองค์จึงทรงกระทําตามนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 5, 'ยังมียิวคนหนึ่งในสุสาปราสาทชื่อโมรเดคัย บุตรชายยาอีร์ ผู้เป็นบุตรชายชิเมอี ผู้เป็นบุตรชายคีช คนเบนยามิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 6, 'ผู้ถูกกวาดต้อนจากเยรูซาเล็มในหมู่เชลยที่ถูกกวาดต้อนไปพร้อมกับเยโคนิยาห์กษัตริย์ของยูดาห์ ผู้ซึ่งเนบูคัดเนสซาร์กษัตริย์ของบาบิโลนได้กวาดต้อนไปนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 7, 'ท่านได้เลี้ยงดูฮาดาชาห์คือเอสเธอร์บุตรสาวลุงของท่าน เพราะเธอไม่มีพ่อแม่ สาวคนนี้รูปงามและน่าดู เมื่อบิดามารดาของเธอสิ้นชีวิตแล้ว โมรเดคัยก็รับเธอมาเลี้ยงเป็นบุตรสาว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 8, 'ต่อมาเมื่อพระบัญชาของกษัตริย์และกฤษฎีกาของพระองค์ประกาศออกไป และเมื่อเขารวบรวมหญิงสาวเป็นอันมากเข้ามาในสุสาปราสาทให้อยู่ภายใต้อารักขาของเฮกัย เอสเธอร์ก็ถูกนําเข้ามาไว้ในราชสํานักภายใต้อารักขาของเฮกัยผู้ดูแลสตรี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 9, 'หญิงนั้นเป็นที่พอใจเขาและเธอก็เป็นที่โปรดปรานแก่เขา เขาจึงรีบจัดหาเครื่องชําระล้าง และส่วนของเธอให้เธอ พร้อมกับสาวใช้ที่คัดเลือกแล้วเจ็ดคนจากราชสํานัก แล้วก็เลื่อนเธอและสาวใช้ของเธอขึ้นไปยังสถานที่ที่ดีที่สุดในฮาเร็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 10, 'เอสเธอร์มิได้บอกให้ทราบถึงชาติและญาติของเธอ เพราะโมรเดคัยกําชับเธอไม่ให้ใครรู้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 11, 'ทุกๆวันโมรเดคัยเดินมาหน้าลานของฮาเร็ม เพื่อฟังข่าวเอสเธอร์เป็นอย่างไร และมีอะไรเกิดขึ้นแก่เธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 12, 'เมื่อถึงเวรที่สาวๆทุกคนจะเข้าไปเฝ้ากษัตริย์อาหสุเอรัส หลังจากได้เตรียมตัวตามระเบียบของหญิงสิบสองเดือนแล้ว (และนี่เป็นเวลาปกติสําหรับการชําระล้าง คือชโลมกายหญิงด้วยน้ํามันกํายานหกเดือน และหกเดือนด้วยเครื่องเทศและสิ่งอื่นๆสําหรับการชําระล้างผู้หญิง)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 13, 'เมื่อสาวๆทุกคนจะเข้าไปเฝ้ากษัตริย์อย่างนี้ เธอต้องการจะเอาอะไรจากฮาเร็มไปยังราชสํานัก ก็เอาไปได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 14, 'เธอเข้าไปเฝ้าเวลาเย็น และในเวลาเช้าเธอกลับออกมาในฮาเร็มที่สองในอารักขาของชาอัชกาสขันทีของกษัตริย์ผู้ดูแลนางห้าม เธอไม่ได้เข้าไปเฝ้ากษัตริย์อีก นอกจากกษัตริย์จะพอพระทัยในเธอ และทรงเรียกชื่อเธอให้เข้าเฝ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 15, 'บัดนี้เมื่อถึงเวรของเอสเธอร์ บุตรสาวของอาบีฮาอิล ลุงของโมรเดคัยผู้ซึ่งรับเธอไว้เป็นบุตรสาว จะเข้าเฝ้ากษัตริย์ เธอมิได้ขอสิ่งใด นอกจากสิ่งที่เฮกัยข้าราชสํานักของกษัตริย์ผู้ดูแลพวกสตรีแนะนํา ฝ่ายเอสเธอร์ได้รับความโปรดปรานในสายตาของทุกคนที่ได้พบเห็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 16, 'เมื่อเขาพาเอสเธอร์เข้าไปเฝ้ากษัตริย์อาหสุเอรัสในพระราชสํานัก ในเดือนสิบซึ่งเป็นเดือนเทเบทในปีที่เจ็ดแห่งรัชกาลของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 17, 'กษัตริย์ทรงรักเอสเธอร์ยิ่งกว่าบรรดาหญิงทั้งปวงนั้น และเธอได้รับพระกรุณาและความโปรดปรานในสายพระเนตรของพระองค์มากกว่าหญิงพรหมจารีทั้งสิ้น พระองค์จึงทรงสวมพระมงกุฎบนศีรษะของเธอ และทรงตั้งเธอให้เป็นพระราชินีแทนวัชที');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 18, 'แล้วกษัตริย์พระราชทานการเลี้ยงใหญ่แก่เจ้านายและข้าราชการทั้งปวงของพระองค์ เป็นการเลี้ยงของพระนางเอสเธอร์ พระองค์ทรงอนุมัติให้งดส่วยแก่มณฑลทั้งปวง และพระราชทานของกํานัล ด้วยพระทัยกว้างขวางของกษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 19, 'เมื่อเขารวบรวมหญิงพรหมจารีมาครั้งที่สอง โมรเดคัยนั่งอยู่ที่ประตูของกษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 20, 'ฝ่ายพระนางเอสเธอร์นั้นมิได้ทรงให้ใครทราบถึงพระญาติหรือชนชาติของพระนางดังที่โมรเดคัยกําชับพระนางไว้ เพราะพระนางเอสเธอร์ทรงทําตามคําสั่งของโมรเดคัย เช่นเดียวกับเมื่อเขาเลี้ยงดูพระนางมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 21, 'ในครั้งนั้นเมื่อโมรเดคัยนั่งอยู่ที่ประตูของกษัตริย์ บิกธานและเทเรช ขันทีสองคนของกษัตริย์ ผู้เฝ้าธรณีประตู มีความโกรธและหาช่องที่จะประทุษร้ายกษัตริย์อาหสุเอรัส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 22, 'เรื่องนี้รู้ถึงโมรเดคัยและท่านก็ทูลพระราชินีเอสเธอร์ พระนางเอสเธอร์กราบทูลกษัตริย์ในนามของโมรเดคัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 23, 'เมื่อมีการสอบสวนเรื่องนี้ว่าเป็นความจริงแล้ว กษัตริย์ก็ทรงให้แขวนสองคนนั้นเสียที่ต้นไม้ และบันทึกเรื่องไว้ในหนังสือพงศาวดารต่อพระพักตร์กษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 1, 'ภายหลังเหตุการณ์เหล่านี้กษัตริย์อาหสุเอรัสทรงเลื่อนยศฮามานบุตรชายฮัมเมดาธา คนอากัก กษัตริย์ทรงเลื่อนท่านและทรงตั้งเก้าอี้ของท่านไว้เหนือกว่าของเจ้านายทั้งปวงที่อยู่กับพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 2, 'บรรดาข้าราชการของกษัตริย์ซึ่งอยู่ที่ประตูของกษัตริย์ก็กราบลงแสดงความเคารพต่อฮามาน เพราะกษัตริย์ทรงบัญชาให้แสดงความเคารพต่อท่านเช่นนั้น แต่โมรเดคัยมิได้กราบหรือแสดงความเคารพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 3, 'ข้าราชการของกษัตริย์ซึ่งอยู่ที่ประตูของกษัตริย์จึงพูดกับโมรเดคัยว่า “ทําไมท่านละเมิดพระบัญชาของกษัตริย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 4, 'อยู่มาเมื่อเขาทั้งหลายพูดกับท่านวันแล้ววันเล่า และท่านไม่ฟังเขา เขาก็ไปเรียนฮามานเพื่อจะดูว่าถ้อยคําของโมรเดคัยจะชนะหรือไม่ เพราะท่านบอกเขาว่าท่านเป็นยิว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 5, 'เมื่อฮามานเห็นว่าโมรเดคัยไม่กราบลงหรือแสดงความเคารพต่อท่าน ฮามานก็เดือดดาล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 6, 'แต่ท่านเห็นว่าเป็นการเสียเกียรติที่จะจับกุมโมรเดคัยคนเดียว เพราะมีคนเรียนท่านให้ทราบถึงชนชาติของโมรเดคัย ฮามานจึงหาช่องที่จะทําลายยิวทั้งหมด คือชนชาติของโมรเดคัยทั่วราชอาณาจักรของอาหสุเอรัส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 7, 'ในเดือนแรกซึ่งเป็นเดือนนิสานปีที่สิบสองแห่งรัชกาลกษัตริย์อาหสุเอรัส เขาพากันทอดเปอร์ คือฉลาก ต่อหน้าฮามานเพื่อหาวัน และเพื่อหาเดือน ได้เดือนที่สิบสอง คือเป็นเดือนอาดาร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 8, 'แล้วฮามานทูลกษัตริย์อาหสุเอรัสว่า “มีชนชาติหนึ่งกระจายอยู่ทั่ว และแยกกันอยู่ท่ามกลางชนชาติทั้งหลายในมณฑลทั้งหลายแห่งราชอาณาจักรของพระองค์ กฎหมายของเขาผิดกับกฎหมายของชนชาติอื่นทั้งสิ้น และพวกนี้ไม่รักษากฎหมายของกษัตริย์ การที่กษัตริย์ทรงปล่อยเขาไว้นี้ไม่บังเกิดประโยชน์แก่พระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 9, 'ถ้าเป็นที่พอพระทัยกษัตริย์ ขอทรงออกกฤษฎีกาให้ทําลายล้างเขาเสียเถิด และข้าพระองค์จะถวายเงินหนึ่งหมื่นตะลันต์ใส่มือบรรดาผู้ที่ดูแลพระราชกิจของกษัตริย์ เพื่อเขาจะได้ใส่ในพระคลังของกษัตริย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 10, 'กษัตริย์จึงถอดพระธํามรงค์ตราออกจากพระหัตถ์ของพระองค์มอบแก่ฮามานบุตรชายฮัมเมดาธา คนอากัก ศัตรูของพวกยิว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 11, 'และกษัตริย์ตรัสกับฮามานว่า “เรามอบเงินนั้นให้แก่ท่าน และมอบประชาชนแก่ท่านด้วย เพื่อจะทําแก่เขาตามที่ท่านเห็นดี”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 12, 'แล้วทรงเรียกราชอาลักษณ์เข้ามาในวันที่สิบสามเดือนต้น ให้เขียนกฤษฎีกาตามที่ฮามานบัญชาไว้ทุกประการ ส่งไปยังสมุหเทศาภิบาลของกษัตริย์และของเจ้าเมืองมณฑลทั้งปวงและถึงเจ้านายแห่งชนชาติทั้งปวง ถึงทุกมณฑลเป็นอักขระของมณฑลนั้น และถึงชนทุกชาติเป็นภาษาของเขา เขียนในพระนามของกษัตริย์อาหสุเอรัส และประทับตราด้วยพระธํามรงค์ของกษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 13, 'ให้คนเดินข่าวจดหมายเหล่านี้ไปถึงมณฑลของกษัตริย์ทั้งสิ้นสั่งให้ทําลาย สังหารและทําให้ยิวทั้งปวงพินาศไป ทั้งหนุ่มและแก่ เด็กและผู้หญิงในวันเดียวกัน คือวันที่สิบสามเดือนที่สิบสองซึ่งเป็นเดือนอาดาร์ และให้ริบเอาข้าวของของเขาไปหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 14, 'ให้ออกสําเนาเอกสารนั้นเป็นกฤษฎีกาในทุกมณฑล นําไปป่าวร้องให้ชนชาติทั้งปวงพร้อมเพื่อวันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 15, 'บรรดาคนเดินข่าวก็รีบไปตามพระบัญชาของกษัตริย์ และออกกฤษฎีกานั้นในสุสาปราสาท กษัตริย์ก็ประทับดื่มกับฮามาน ส่วนชาวนครสุสาพากันงุนงง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 1, 'เมื่อโมรเดคัยทราบทุกอย่างที่ได้กระทําไปแล้ว โมรเดคัยก็ฉีกเสื้อของตนสวมผ้ากระสอบและใส่ขี้เถ้า และออกไปกลางนคร คร่ําครวญด้วยเสียงดังอย่างขมขื่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 2, 'ท่านขึ้นไปอยู่ตรงหน้าประตูของกษัตริย์ เพราะไม่มีผู้ใดที่สวมผ้ากระสอบเข้าประตูของกษัตริย์ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 3, 'และในทุกมณฑลที่พระบัญชาของกษัตริย์และกฤษฎีกาของพระองค์ไปถึง ก็มีการไว้ทุกข์อย่างใหญ่หลวงท่ามกลางพวกยิว ด้วยการอดอาหาร ร้องไห้และคร่ําครวญ และคนเป็นอันมากนอนในผ้ากระสอบและมีขี้เถ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 4, 'เมื่อสาวใช้และขันทีของพระนางเอสเธอร์มาทูลพระนาง พระราชินีก็เป็นทุกข์ในพระทัยยิ่งนัก พระนางทรงส่งเสื้อผ้าไปให้แก่โมรเดคัย เพื่อท่านจะได้ถอดผ้ากระสอบของท่านออกเสีย แต่ท่านไม่ยอมรับผ้านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 5, 'แล้วพระนางเอสเธอร์ตรัสเรียกฮาธาคขันทีคนหนึ่งของกษัตริย์ ผู้ซึ่งพระองค์ทรงแต่งตั้งให้ปรนนิบัติ พระนางตรัสสั่งให้ไปหาโมรเดคัย เพื่อจะทรงทราบว่า เรื่องอะไร และทําอย่างนั้นทําไม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 6, 'ฮาธาคออกไปหาโมรเดคัยที่ถนนในนคร ข้างหน้าประตูของกษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 7, 'โมรเดคัยก็เล่าเรื่องทั้งสิ้นที่เกิดแก่ท่าน และจํานวนเงินถูกต้องที่ฮามานสัญญาถวายแก่พระคลังของกษัตริย์เพื่อการทําลายพวกยิว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 8, 'โมรเดคัยยังได้ให้สําเนากฤษฎีกาเขียนที่ออกในสุสาสั่งให้ทําลายเขาทั้งหลายเพื่อนําไปแสดงแก่พระนางเอสเธอร์ อธิบายเรื่องให้พระนาง และกําชับให้พระนางเข้าเฝ้ากษัตริย์ เพื่อทูลอ้อนวอนพระองค์ และวิงวอนพระองค์เพื่อเห็นแก่ชนชาติของพระนาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 9, 'ฮาธาคก็กลับไปทูลพระนางเอสเธอร์ถึงสิ่งที่โมรเดคัยได้บอกไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 10, 'แล้วพระนางเอสเธอร์ก็บอกฮาธาคให้ส่งข่าวไปให้โมรเดคัยว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 11, '“ข้าราชการของกษัตริย์ทั้งสิ้นและประชาชนในบรรดามณฑลของกษัตริย์ทราบอยู่ว่า ถ้าชายหรือหญิงคนใดเข้าเฝ้ากษัตริย์ภายในพระลานชั้นในโดยมิได้ทรงเรียก ก็มีกฎหมายอยู่ข้อเดียวเหมือนกันหมด ให้ลงโทษถึงตาย เว้นเสียแต่ผู้ซึ่งกษัตริย์ยื่นธารพระกรทองคําออกรับคนนั้นจึงจะมีชีวิตอยู่ได้ ส่วนฉันกษัตริย์ก็มิได้ตรัสเรียกให้เข้าเฝ้ามาสามสิบวันแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 12, 'เขาทั้งหลายก็มาบอกโมรเดคัยถึงสิ่งที่พระนางเอสเธอร์ตรัสนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 13, 'โมรเดคัยจึงบอกเขาให้กลับไปทูลตอบพระนางเอสเธอร์ว่า “อย่าคิดว่าเธออยู่ในราชสํานักจะรอดพ้นได้ดีกว่าพวกยิวทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 14, 'เพราะถ้าเธอเงียบอยู่ในเวลานี้ ความช่วยเหลือและการช่วยให้พ้นจะมาถึงพวกยิวจากที่อื่น แต่เธอและวงศ์วานบิดาของเธอจะพินาศ ที่จริงเธอมารับตําแหน่งราชินีก็เพื่อยามวิกฤตเช่นนี้ก็เป็นได้นะ ใครจะรู้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 15, 'แล้วเอสเธอร์ตรัสบอกเขาให้ไปบอกโมรเดคัยว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 16, '“ไปเถิด ให้รวบรวมพวกยิวทั้งสิ้นที่หาพบในสุสา และถืออดอาหารเพื่อฉัน อย่ารับประทาน อย่าดื่มสามวันกลางคืนหรือกลางวัน ฉันและสาวใช้ของฉันจะอดอาหารอย่างท่านด้วย แล้วฉันจะเข้าเฝ้ากษัตริย์แม้ว่าเป็นการฝ่าฝืนกฎหมาย ถ้าฉันพินาศ ฉันก็พินาศ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 17, 'โมรเดคัยก็ไปกระทําทุกอย่างตามที่พระนางเอสเธอร์รับสั่งแก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 1, 'อยู่มาในวันที่สามพระนางเอสเธอร์ทรงฉลองพระองค์ และประทับยืนที่ในลานชั้นในของพระราชสํานัก ตรงข้ามกับท้องพระโรงใหญ่ของกษัตริย์ กษัตริย์ประทับบนราชบัลลังก์ภายในพระราชวัง ตรงข้ามทางเข้าพระราชวัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 2, 'เมื่อกษัตริย์ทอดพระเนตรเห็นพระราชินีเอสเธอร์ประทับยืนอยู่ในพระลาน พระนางก็เป็นที่โปรดปรานในสายพระเนตรของพระองค์ พระองค์จึงทรงยื่นธารพระกรทองคําซึ่งอยู่ในพระหัตถ์ของพระองค์แก่พระนางเอสเธอร์ พระนางเอสเธอร์ก็เสด็จเข้ามาแตะยอดธารพระกร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 3, 'กษัตริย์ตรัสกับพระนางว่า “พระราชินีเอสเธอร์ เรื่องอะไรกัน พระนางต้องการสิ่งใด ก็จะประทานให้แก่พระนางถึงครึ่งราชอาณาจักรของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 4, 'และพระนางเอสเธอร์ทูลว่า “ถ้าเป็นที่พอพระทัยกษัตริย์ ขอกษัตริย์เสด็จมาพร้อมกับฮามานในวันนี้ถึงการเลี้ยงที่หม่อมฉันเตรียมไว้เพื่อพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 5, 'กษัตริย์จึงตรัสว่า “ให้ฮามานรีบมา เพื่อท่านจะได้กระทําตามที่พระนางเอสเธอร์ปรารถนา” กษัตริย์จึงเสด็จไปในการเลี้ยงกับฮามานซึ่งพระนางเอสเธอร์ได้ทรงเตรียมไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 6, 'ขณะอยู่ที่การเลี้ยงเหล้าองุ่นกษัตริย์ตรัสกับเอสเธอร์ว่า “คําร้องขอของพระนางว่ากระไร เราจะให้ แล้วคําทูลขอของพระนางว่ากระไร แม้จะถึงครึ่งราชอาณาจักรของเรา ก็จะสําเร็จ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 7, 'พระนางเอสเธอร์ทูลว่า “คําร้องขอของหม่อมฉันและคําทูลขอของหม่อมฉัน คือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 8, 'ถ้าหม่อมฉันเป็นที่โปรดปรานในสายพระเนตรของกษัตริย์ และเป็นที่พอพระทัยกษัตริย์ที่จะประทานตามคําร้องขอของหม่อมฉัน และให้คําทูลขอของหม่อมฉันสําเร็จนี้ ขอกษัตริย์เสด็จมาพร้อมกับฮามานในการเลี้ยงซึ่งหม่อมฉันจะเตรียมไว้สําหรับเขาทั้งหลาย และพรุ่งนี้หม่อมฉันจะกระทําตามที่กษัตริย์ตรัสนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 9, 'วันนั้นฮามานก็ออกไปด้วยใจชื่นบานและยินดี แต่เมื่อฮามานเห็นโมรเดคัยที่ประตูของกษัตริย์ ไม่ยืนขึ้นหรือตัวสั่นอยู่ต่อหน้าท่าน ท่านก็เดือดดาลต่อโมรเดคัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 10, 'ถึงอย่างนั้นก็ดี ฮามานก็อดกลั้นไว้ กลับไปบ้าน ใช้ให้คนไปตามบรรดาเพื่อนของตนและเศเรชภรรยาของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 11, 'ฮามานพรรณนาถึงความโอ่โถงแห่งความมั่งมีของท่าน จํานวนบุตรของท่าน และเกียรติยศทั้งสิ้นซึ่งกษัตริย์พระราชทานแก่ท่าน และถึงเรื่องว่ากษัตริย์ได้เลื่อนท่านขึ้นเหนือเจ้านาย และข้าราชการของกษัตริย์อย่างไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 12, 'แล้วฮามานเสริมว่า “แม้พระราชินีเอสเธอร์ก็มิได้ทรงให้ผู้ใดไปกับกษัตริย์ในการเลี้ยงซึ่งพระนางทรงจัดขึ้นนอกจากตัวข้า และพรุ่งนี้พระนางทรงเชิญข้ากับกษัตริย์อีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 13, 'แต่สิ่งเหล่านี้หาเป็นประโยชน์แก่ข้าไม่ ตราบใดที่ข้าเห็นโมรเดคัยคนยิวนั่งอยู่ที่ประตูของกษัตริย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 14, 'เศเรชภรรยาของท่าน และสหายทั้งสิ้นของท่านจึงพูดกับท่านว่า “ขอทําตะแลงแกงสูงห้าสิบศอก รุ่งเช้าก็ทูลกษัตริย์ให้แขวนโมรเดคัยเสียที่นั่น แล้วก็ไปกินเลี้ยงอย่างร่าเริงกับกษัตริย์” คําแนะนํานี้เป็นที่พอใจฮามาน ท่านจึงสั่งให้ทําตะแลงแกง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 1, 'คืนวันนั้นกษัตริย์บรรทมไม่หลับ และพระองค์ทรงบัญชาให้นําหนังสือบันทึกเหตุที่น่าจดจําคือพระราชพงศาวดารมา เขาก็อ่านถวายกษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 2, 'พระองค์ทรงเห็นเขียนไว้ว่า โมรเดคัยได้ทูลเรื่องบิกธานาและเทเรชอย่างไร คือเรื่องขันทีสองคนของกษัตริย์ผู้เฝ้าธรณีประตู หาช่องจะปลงพระชนม์กษัตริย์อาหสุเอรัส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 3, 'กษัตริย์ตรัสว่า “ได้ให้เกียรติและยศอะไรแก่โมรเดคัยเพราะเรื่องนี้บ้าง” ข้าราชการของกษัตริย์ผู้ปรนนิบัติพระองค์ทูลว่า “ยังไม่ได้ให้สิ่งใดพ่ะย่ะค่ะ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 4, 'กษัตริย์ตรัสว่า “ใครอยู่ในลานบ้าน” ฝ่ายฮามานพึ่งเข้ามาถึงพระลานชั้นนอกแห่งราชสํานัก เพื่อจะทูลกษัตริย์เรื่องเอาโมรเดคัยแขวนเสียที่ตะแลงแกงซึ่งท่านได้เตรียมไว้สําหรับท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 5, 'ข้าราชการของกษัตริย์จึงทูลพระองค์ว่า “ดูเถิด ฮามานกําลังยืนอยู่ในพระลานพ่ะย่ะค่ะ” และกษัตริย์ตรัสว่า “ให้ท่านเข้ามานี่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 6, 'ฮามานจึงเข้ามา กษัตริย์ตรัสกับท่านว่า “หากกษัตริย์มีพระประสงค์จะประทานเกียรติยศแก่บุคคลผู้ใดแล้ว กษัตริย์ควรจะทําแก่เขาประการใด” และฮามานรําพึงในใจว่า “ผู้ใดเล่าที่กษัตริย์พอพระทัยจะประทานเกียรติยศมากกว่าข้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 7, 'แล้วฮามานจึงทูลกษัตริย์ว่า “เพื่อให้เกียรติแก่คนที่กษัตริย์พอพระทัยจะประทานเกียรติยศนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 8, 'ขอนําฉลองพระองค์ซึ่งกษัตริย์ทรง และม้าซึ่งกษัตริย์ทรง และมงกุฎซึ่งพระองค์ทรงสวมบนพระเศียร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 9, 'ขอทรงมอบฉลองพระองค์และม้าในมือของเจ้านายผู้ใหญ่ยิ่งที่สุดคนหนึ่งของกษัตริย์ ขอให้แต่งคนที่กษัตริย์พอพระทัยจะประทานเกียรติยศ และขอให้ชายนั้นขึ้นนั่งหลังม้าไปตามถนนของกรุง และป่าวร้องไปข้างหน้าเขาว่า ‘ผู้ที่กษัตริย์พอพระทัยจะประทานเกียรติยศก็เป็นเช่นนี้แหละ’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 10, 'กษัตริย์จึงตรัสกับฮามานว่า “รีบเข้าเถอะ เอาเสื้อและม้าอย่างที่ท่านว่า แล้วให้เกียรติแก่โมรเดคัยคนยิวซึ่งนั่งที่ประตูของกษัตริย์ อย่าเว้นสิ่งใดที่ท่านกล่าวมานั้นเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 11, 'ฮามานจึงนําฉลองพระองค์กับม้าและตกแต่งโมรเดคัย และให้ท่านขึ้นม้าไปตามถนนในกรุง ป่าวร้องหน้าท่านว่า “ผู้ที่กษัตริย์พอพระทัยจะประทานเกียรติยศก็เป็นเช่นนี้แหละ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 12, 'แล้วโมรเดคัยก็กลับมายังประตูของกษัตริย์ แต่ฮามานรีบกลับไปบ้านของท่าน คลุมศีรษะและคร่ําครวญ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 13, 'และฮามานเล่าทุกสิ่งที่อุบัติแก่ท่านให้เศเรชภรรยาของท่านและสหายทั้งหลายของท่านฟัง คนฉลาดของท่านและเศเรชภรรยาของท่านจึงว่า “ถ้าท่านเริ่มล้มลงต่อหน้าโมรเดคัยซึ่งเป็นเชื้อสายของยิว ท่านจะไม่ชนะเขา แต่จะล้มลงต่อหน้าเขาแน่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 14, 'ขณะเมื่อเขาทั้งหลายกําลังพูดกับท่านอยู่ ขันทีของกษัตริย์ก็มาถึงรีบนําฮามานไปยังการเลี้ยงซึ่งพระนางเอสเธอร์ทรงจัดนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 1, 'กษัตริย์จึงเสด็จกับฮามานไปในการเลี้ยงกับพระราชินีเอสเธอร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 2, 'ในวันที่สองเมื่ออยู่ที่การเลี้ยงเหล้าองุ่นกษัตริย์ตรัสกับเอสเธอร์อีกว่า “พระราชินีเอสเธอร์ คําร้องขอของพระนางคืออะไร และคําทูลขอของพระนางคืออะไร เราจะประทานให้ แม้ถึงครึ่งราชอาณาจักรของเรา ก็จะสําเร็จ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 3, 'พระราชินีเอสเธอร์ทูลตอบว่า “โอ ข้าแต่กษัตริย์ ถ้าหม่อมฉันเป็นที่โปรดปรานในสายพระเนตรของพระองค์ และถ้าเป็นที่พอพระทัยกษัตริย์ ขอพระราชทานชีวิตของหม่อมฉันให้แก่หม่อมฉันตามคําร้องขอของหม่อมฉัน และชีวิตของชนชาติของหม่อมฉันตามคําทูลขอของหม่อมฉัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 4, 'เพราะพวกเราถูกขายทั้งหม่อมฉันและชนชาติของหม่อมฉันให้ถูกทําลาย ให้ถูกสังหารและให้ถูกล้างผลาญ แต่ถ้าพวกเราถูกขายเพียงให้เป็นทาสชายและหญิง หม่อมฉันก็จะอดกลั้นสงบไว้ เพราะความทุกข์ยากของเราจะเปรียบกับผลเสียหายของกษัตริย์นั้นก็ไม่ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 5, 'กษัตริย์อาหสุเอรัสจึงตรัสกับพระราชินีเอสเธอร์ว่า “ผู้นั้นคือใคร อยู่ที่ไหน จึงบังอาจคิดการกระทําเช่นนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 6, 'และพระนางเอสเธอร์ทูลว่า “คู่อริและศัตรูคือฮามานคนโหดร้ายผู้นี้เพคะ” ฮามานก็กลัวอยู่ต่อพระพักตร์กษัตริย์และพระราชินี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 7, 'กษัตริย์ทรงลุกขึ้นจากการเลี้ยงเหล้าองุ่นด้วยทรงพระพิโรธ และเสด็จเข้าไปในราชอุทยาน แต่ฮามานยังอยู่เพื่อทูลขอชีวิตจากพระราชินีเอสเธอร์ เพราะท่านเห็นว่ากษัตริย์ทรงมุ่งร้ายต่อท่านแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 8, 'เมื่อกษัตริย์เสด็จกลับจากราชอุทยานมายังที่ซึ่งมีการเลี้ยงเหล้าองุ่น ฝ่ายฮามานยังกราบอยู่ที่พระแท่นซึ่งพระนางเอสเธอร์ประทับอยู่นั้น กษัตริย์ตรัสว่า “เขายังจะข่มขืนพระราชินีต่อหน้าต่อตาเราในบ้านของเราหรือ” พอพระวาทะหลุดจากพระโอษฐ์กษัตริย์เขาก็มาคลุมหน้าฮามาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 9, 'ฮารโบนาขันทีคนหนึ่งทูลต่อพระพักตร์กษัตริย์ว่า “ดูเถิด ตะแลงแกงซึ่งฮามานเตรียมไว้สําหรับโมรเดคัย ซึ่งรายงานช่วยพระชนม์กษัตริย์ ก็ยังตั้งอยู่ที่บ้านของฮามาน สูงห้าสิบศอกพ่ะย่ะค่ะ” กษัตริย์ตรัสว่า “แขวนมันบนนั้นแหละ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 10, 'เขาก็แขวนฮามานบนตะแลงแกงซึ่งท่านได้เตรียมไว้สําหรับโมรเดคัย แล้วพระพิโรธของกษัตริย์ก็สงบลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 1, 'ในวันนั้นกษัตริย์อาหสุเอรัสพระราชทานวงศ์วานของฮามานศัตรูของพวกยิวแก่พระราชินีเอสเธอร์ โมรเดคัยก็เข้าเฝ้ากษัตริย์ เพราะพระนางเอสเธอร์ได้ทูลว่าท่านเป็นอะไรกับพระนาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 2, 'กษัตริย์จึงถอดพระธํามรงค์ตรา ซึ่งพระองค์ทรงเอามาจากฮามาน พระราชทานให้โมรเดคัย พระนางเอสเธอร์ก็ทรงตั้งโมรเดคัยเป็นใหญ่เหนือวงศ์วานของฮามาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 3, 'แล้วพระนางเอสเธอร์กราบทูลกษัตริย์อีก พระนางกราบลงที่พระบาทของพระองค์และวิงวอนพระองค์ด้วยน้ําพระเนตร ขอให้แผนการร้ายของฮามาน คนอากัก และการปองร้ายซึ่งท่านได้คิดขึ้นต่อพวกยิวนั้นพ้นไปเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 4, 'กษัตริย์จึงทรงยื่นธารพระกรทองคําแก่พระนางเอสเธอร์ พระนางเอสเธอร์ก็ทรงลุกขึ้นประทับยืนเฝ้ากษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 5, 'พระนางทูลว่า “ถ้าเป็นที่พอพระทัยกษัตริย์ และถ้าหม่อมฉันเป็นที่โปรดปรานในสายพระเนตรของพระองค์ ถ้าสิ่งนั้นเป็นสิ่งที่ถูกต้องต่อพระพักตร์กษัตริย์ และหม่อมฉันเป็นที่พอพระทัยในสายพระเนตรของพระองค์ ขอทรงให้มีพระอักษรรับสั่งให้กลับความในจดหมายซึ่งฮามาน คนอากัก บุตรชายฮัมเมดาธาได้คิดขึ้น และเขียนเพื่อทําลายพวกยิวที่อยู่ในมณฑลทั้งสิ้นของกษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 6, 'เพราะหม่อมฉันจะอดทนดูภัยพิบัติมาถึงชาติของหม่อมฉันอย่างไรได้ หม่อมฉันจะทนดูการทําลายญาติพี่น้องของหม่อมฉันอย่างไรได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 7, 'กษัตริย์อาหสุเอรัสจึงตรัสกับพระราชินีเอสเธอร์และแก่โมรเดคัยคนยิวว่า “ดูเถิด เรามอบวงศ์วานของฮามานแก่พระนางเอสเธอร์แล้ว และเขาก็แขวนมันบนตะแลงแกง เพราะมันจะทําอันตรายแก่พวกยิว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 8, 'ท่านจะเขียนตามที่ท่านพอใจเกี่ยวกับเรื่องยิวในนามของกษัตริย์ และประทับตราด้วยพระธํามรงค์ เพราะว่ากฤษฎีกาที่เขียนในนามของกษัตริย์และประทับตราด้วยพระธํามรงค์จะเปลี่ยนกลับไม่ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 9, 'แล้วพระองค์ทรงเรียกราชอาลักษณ์เข้ามาในเวลานั้นในเดือนที่สามซึ่งเป็นเดือนสิวัน ณ วันที่ยี่สิบสาม และให้เขียนกฤษฎีกาตามที่โมรเดคัยบัญชาทุกอย่างเกี่ยวกับพวกยิว ถึงบรรดาสมุหเทศาภิบาล และผู้ว่าราชการ และเจ้าหน้าที่ของมณฑล ตั้งแต่อินเดียถึงเอธิโอเปีย ร้อยยี่สิบเจ็ดมณฑล ไปถึงทุกมณฑลเป็นอักขระของมณฑลนั้น และถึงชนทุกชาติเป็นภาษาของเขา และถึงพวกยิวเป็นอักขระและในภาษาของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 10, 'และท่านเขียนในพระนามของกษัตริย์อาหสุเอรัสและประทับตราพระธํามรงค์ของกษัตริย์ และส่งจดหมายนั้นไปทางผู้เดินข่าวขึ้นม้าเร็ว และผู้ขี่ล่อ อูฐและม้าอาชาไนยหนุ่ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 11, 'ตามจดหมายเหล่านี้กษัตริย์ทรงอนุญาตให้พวกยิวผู้อยู่ในทุกเมืองชุมนุมกันและป้องกันชีวิตของตน ให้ทําลาย ให้สังหารและให้ล้างผลาญกําลังพลใดๆของประชาชนหรือมณฑลใดๆซึ่งจะมาทําร้าย ทั้งเด็กและผู้หญิง และปล้นเอาข้าวของของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 12, 'ในวันเดียวตลอดทั่วทุกมณฑลของกษัตริย์อาหสุเอรัส คือวันที่สิบสาม เดือนที่สิบสอง ซึ่งเป็นเดือนอาดาร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 13, 'สําเนาของหนังสือที่เขียนนั้นจะต้องเป็นกฤษฎีกาในทุกมณฑล และออกโดยการป่าวร้องแก่ชนชาติทั้งปวง พวกยิวจะต้องพร้อมกันในวันนั้นแก้แค้นศัตรูของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 14, 'คนเดินข่าวซึ่งขี่ล่อกับอูฐจึงรีบเร่งขับไปตามพระบัญชาของกษัตริย์ และกฤษฎีกานั้นออกในสุสาปราสาท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 15, 'เมื่อโมรเดคัยออกไปพ้นพระพักตร์กษัตริย์ สวมฉลองพระองค์สีฟ้าและสีขาว พร้อมกับมงกุฎทองคําใหญ่และเสื้อคลุมผ้าป่านเนื้อละเอียดสีม่วง ฝ่ายชาวนครสุสาก็โห่ร้องเปรมปรีดิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 16, 'พวกยิวมีความผ่องใส ความยินดี ชื่นบานและเกียรติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 17, 'ทุกมณฑลทุกเมือง ไม่ว่าที่ใดที่พระบัญชาของกษัตริย์และกฤษฎีกาของพระองค์มาถึง ก็มีความยินดีและความชื่นบานท่ามกลางพวกยิว มีการเลี้ยงและวันรื่นเริง คนเป็นอันมากมาจากชนชาติของประเทศก็ประกาศตัวเป็นพวกยิว เพราะความกลัวพวกยิวมาครอบงําเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 1, 'ในเดือนที่สิบสองซึ่งเป็นเดือนอาดาร์ วันที่สิบสามเดือนนั้น เมื่อจะปฏิบัติตามพระบัญชาของกษัตริย์และกฤษฎีกา ในวันนั้นเองที่ศัตรูของพวกยิวหวังจะเป็นใหญ่เหนือพวกยิว (แต่ซึ่งถูกเปลี่ยนไป เป็นวันที่พวกยิวได้ความเป็นใหญ่เหนือพวกที่เกลียดชังเขา)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 2, 'พวกยิวก็ชุมนุมกันในบรรดาหัวเมืองตลอดทั่วทุกมณฑลของกษัตริย์อาหสุเอรัส เพื่อจะจับพวกที่หาช่องทําร้ายเขา ไม่มีผู้ใดต่อต้านพวกเขาได้ เพราะความกลัวเขาครอบงําเหนือชนชาติทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 3, 'บรรดาเจ้านายทั้งปวงของมณฑล และสมุหเทศาภิบาล และผู้ว่าราชการเมือง และเจ้าหน้าที่ราชการก็ช่วยพวกยิวด้วย เพราะความกลัวโมรเดคัยครอบงําเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 4, 'เหตุว่าโมรเดคัยเป็นใหญ่อยู่ในราชสํานักของกษัตริย์ และชื่อเสียงของท่านเลื่องลือไปทั่วทุกมณฑล เพราะชายที่ชื่อโมรเดคัยนั้นมีอํานาจมากยิ่งขึ้นทุกที');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 5, 'พวกยิวจึงโจมตีศัตรูทั้งหมดของตนด้วยฟันดาบ สังหารและทําลายเขา และทําแก่ผู้ที่เกลียดชังเขาตามใจชอบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 6, 'ในสุสาปราสาทพวกยิวได้สังหารและทําลายล้างเสียห้าร้อยคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 7, 'ได้สังหารปารชันดาธา และดาลโฟน และอัสปาธา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 8, 'และโปราธา และอาดัลยา และอารีดาธา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 9, 'และปารมัชทา และอารีสัย และอารีดัย และไวซาธา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 10, 'คือเขาสังหารบุตรชายทั้งสิบของฮามาน บุตรชายฮัมเมดาธา ศัตรูของพวกยิว แต่เขามิได้ปล้นข้าวของ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 11, 'ในวันนั้นจํานวนคนที่ถูกฆ่าในสุสาปราสาทก็ถูกนํามารายงานต่อเบื้องพระพักตร์กษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 12, 'กษัตริย์จึงตรัสกับพระราชินีเอสเธอร์ว่า “พวกยิวได้สังหารและทําลายล้างเสียห้าร้อยคนในสุสาปราสาท รวมทั้งบุตรชายทั้งสิบคนของฮามานด้วย แล้วเขาได้ทําอะไรกันบ้างในมณฑลที่เหลืออยู่ของกษัตริย์นั้น บัดนี้คําร้องของพระนางคืออะไร เราจะประทานให้ คําทูลขอของพระนางมีอะไรอีกต่อไปอีกบ้าง เราก็จะกระทําตามนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 13, 'พระนางเอสเธอร์ทูลว่า “ถ้าเป็นที่พอพระทัยกษัตริย์ ขอให้พวกยิวที่อยู่ในสุสาได้กระทําตามกฤษฎีกาของวันนี้ในวันพรุ่งนี้อีก และขอให้แขวนบุตรชายทั้งสิบของฮามานบนตะแลงแกง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 14, 'กษัตริย์ได้ทรงบัญชาให้กระทําเช่นนั้น มีกฤษฎีกาออกในสุสา และบุตรชายทั้งสิบคนของฮามานก็ถูกแขวน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 15, 'พวกยิวที่อยู่ในสุสาชุมนุมกันในวันที่สิบสี่เดือนอาดาร์ด้วย และได้สังหารสามร้อยคนในสุสา แต่เขามิได้ริบข้าวของ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 16, 'ฝ่ายพวกยิวอื่นๆซึ่งอยู่ในมณฑลของกษัตริย์ก็ชุมนุมกันป้องกันชีวิต และพ้นศัตรูของเขา เขาสังหารผู้ที่เกลียดชังเขาเสียเจ็ดหมื่นห้าพันคน แต่เขามิได้ริบข้าวของ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 17, 'เหตุนี้เกิดขึ้นในวันที่สิบสามเดือนอาดาร์ และในวันที่สิบสี่เขาหยุดพัก และกระทําวันนั้นให้เป็นวันกินเลี้ยงและยินดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 18, 'แต่พวกยิวที่อยู่ในสุสาชุมนุมกันในวันที่สิบสามและวันที่สิบสี่ และหยุดพักในวันที่สิบห้า ทําให้วันนั้นเป็นวันกินเลี้ยงและยินดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 19, 'เพราะฉะนั้นพวกยิวในชนบท ที่อยู่ตามหัวเมืองที่ไม่มีกําแพง ถือวันที่สิบสี่ของเดือนอาดาร์เป็นวันแห่งความยินดีและกินเลี้ยง และถือเป็นวันรื่นเริง และเป็นวันที่เขาส่งของขวัญไปให้กันและกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 20, 'และโมรเดคัยบันทึกเรื่องนี้และส่งจดหมายไปยังพวกยิวทั้งปวงผู้อยู่ในมณฑลทั้งปวงของกษัตริย์อาหสุเอรัส ทั้งใกล้และไกล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 21, 'ชักชวนเขาให้ถือวันที่สิบสี่เดือนอาดาร์ และวันที่สิบห้าเดือนเดียวกันทุกๆปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 22, 'เป็นวันที่พวกยิวพ้นจากศัตรูของเขา และเป็นเดือนที่เปลี่ยนความโศกเศร้าเป็นความยินดี และการคร่ําครวญเป็นวันรื่นเริงให้แก่เขา และให้เขาถือเป็นวันกินเลี้ยงและวันยินดี เป็นวันที่ส่งของขวัญแก่กันและกัน และให้ของขวัญแก่คนจน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 23, 'พวกยิวจึงตกลงกระทําตามที่เขาตั้งต้นแล้ว และตามที่โมรเดคัยเขียนไปถึงเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 24, 'เพราะฮามานบุตรชายฮัมเมดาธา คนอากัก ศัตรูของพวกยิวทั้งปวง ได้ปองร้ายต่อพวกยิวเพื่อทําลายเขา ได้ทอดเปอร์ คือฉลาก เพื่อล้างผลาญและทําลายเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 25, 'แต่เมื่อพระนางเอสเธอร์เข้าเฝ้ากษัตริย์ พระองค์ทรงบัญชาเป็นลายลักษณ์อักษรให้แผนการมุ่งร้ายของท่าน ซึ่งท่านได้คิดต่อพวกยิวนั้น กลับตกลงบนศีรษะของท่านเอง และให้ตัวท่านกับบุตรชายของท่านถูกแขวนบนตะแลงแกง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 26, 'เพราะฉะนั้นเขาจึงเรียกวันเหล่านี้ว่า เปอร์ริม ตามคําเปอร์ ดังนั้น เพราะทุกอย่างที่เขียนไว้ในจดหมายนี้ และเพราะสิ่งที่พวกยิวต้องเผชิญในเรื่องนี้ และสิ่งที่อุบัติแก่เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 27, 'พวกยิวก็กําหนดและรับว่าตัวเขาเอง เชื้อสายของเขา และบรรดาผู้ที่เข้าจารีตยิวจะถือสองวันนี้ดังที่เขียนไว้ และตามเวลาที่กําหนดไว้ทุกปีมิได้ขาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 28, 'และว่าจะจดจําวันเหล่านี้ และถือตลอดทุกชั่วอายุ ทุกครอบครัว มณฑลและเมือง วันเทศกาลเปอร์ริมนี้จะไม่เลิกถือในท่ามกลางพวกยิว หรือการระลึกถึงวันเหล่านี้จะไม่สิ้นลงในเชื้อสายของเขาเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 29, 'แล้วพระราชินีเอสเธอร์ ธิดาของอาบีฮาอิล กับโมรเดคัยคนยิว ก็เขียนเป็นลายลักษณ์อักษรรับรองจดหมายฉบับที่สองนี้เรื่องเทศกาลเปอร์ริม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 30, 'ให้ส่งจดหมายไปถึงยิวทั้งปวงในหนึ่งร้อยยี่สิบเจ็ดมณฑลในราชอาณาจักรของอาหสุเอรัส เป็นคําที่แท้จริงให้อยู่เย็นเป็นสุข');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 31, 'และให้ถือวันเทศกาลเปอร์ริมเหล่านี้ตามกําหนดฤดูกาล ดังที่โมรเดคัยคนยิวและพระราชินีเอสเธอร์ทรงตรัสสั่งพวกยิว และตามที่เขาตั้งไว้สําหรับตนเองและสําหรับเชื้อสายของเขา เกี่ยวกับการอดอาหารและการร้องทุกข์ของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 32, 'พระบัญชาของพระนางเอสเธอร์ตั้งระเบียบการเทศกาลเปอร์ริมไว้และมีบันทึกไว้ในหนังสือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 1, 'กษัตริย์อาหสุเอรัสมีรับสั่งให้เก็บบรรณาการทั่วราชอาณาจักรและตามเกาะต่างๆแห่งทะเล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 2, 'พระราชกิจอันกอปรด้วยพระราชอํานาจและอานุภาพ กับเรื่องราวละเอียดของยศศักดิ์อันสูงของโมรเดคัย ซึ่งกษัตริย์ทรงเลื่อนท่านขึ้น มิได้บันทึกไว้ในหนังสือพงศาวดารของกษัตริย์แห่งมีเดียและเปอร์เซียหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 3, 'เพราะโมรเดคัยคนยิวมีตําแหน่งรองกษัตริย์อาหสุเอรัส และท่านเป็นใหญ่ท่ามกลางพวกยิว และเป็นที่ชอบพอของมวลญาติพี่น้องของท่าน เพราะท่านแสวงหาความมั่งคั่งให้ชนชาติของท่าน และพูดให้เกิดสันติสุขแก่เชื้อสายทั้งปวงของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 1, 'มีชายคนหนึ่งในแผ่นดินอูส ชื่อโยบ ชายคนนั้นเป็นคนดีรอบคอบและเที่ยงธรรม เป็นผู้เกรงกลัวพระเจ้าและหันเสียจากความชั่วร้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 2, 'ท่านให้กําเนิดบุตรชายเจ็ดคนและบุตรสาวสามคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 3, 'ส่วนสัตว์เลี้ยงของท่าน มีแกะเจ็ดพันตัว อูฐสามพันตัว วัวห้าร้อยคู่ และลาตัวเมียห้าร้อยตัว และท่านมีคนใช้มากมาย ดังนั้นชายผู้นี้จึงใหญ่โตที่สุดในบรรดาชาวตะวันออก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 4, 'บุตรชายของท่านเคยจัดการเลี้ยงในบ้านของแต่ละคนตามวันกําหนดของตน เขาจะใช้ให้ไปเชิญน้องสาวทั้งสามคนของเขามารับประทานและดื่มกับเขาด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 5, 'และเมื่อการเลี้ยงเวียนครบรอบแล้ว โยบจะใช้ให้ไปทําพิธีชําระตัวเขาทั้งหลายให้บริสุทธิ์ และท่านจะตื่นแต่เช้ามืด ถวายเครื่องเผาบูชาตามจํานวนของเขาทั้งหมด เพราะโยบกล่าวว่า “ชะรอยบุตรชายของข้าพเจ้าได้กระทําบาป และแช่งพระเจ้าอยู่ในใจของเขา” โยบกระทําดังนี้เรื่อยมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 6, 'อยู่มาวันหนึ่ง เมื่อบุตรชายทั้งหลายของพระเจ้ามารายงานตัวต่อพระพักตร์พระเยโฮวาห์ ซาตานได้มาในหมู่เขาด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 7, 'พระเยโฮวาห์ตรัสถามซาตานว่า “เจ้ามาจากไหน” ซาตานทูลตอบพระเยโฮวาห์ว่า “จากไปๆมาๆอยู่บนแผ่นดินโลก และจากเดินขึ้นเดินลงบนนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 8, 'และพระเยโฮวาห์ตรัสกับซาตานว่า “เจ้าได้ไตร่ตรองดูโยบผู้รับใช้ของเราหรือไม่ ว่าในแผ่นดินโลกไม่มีใครเหมือนเขา เป็นคนดีรอบคอบและเที่ยงธรรม เกรงกลัวพระเจ้าและหันเสียจากความชั่วร้าย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 9, 'แล้วซาตานทูลตอบพระเยโฮวาห์ว่า “โยบยําเกรงพระเจ้าเปล่าๆหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 10, 'พระองค์มิได้ทรงกั้นรั้วต้นไม้รอบตัวเขา และครัวเรือนของเขา และทุกสิ่งที่เขามีอยู่เสียทุกด้านหรือ พระองค์ได้ทรงอํานวยพระพรงานน้ํามือของเขา และฝูงสัตว์ของเขาได้ทวีขึ้นในแผ่นดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 11, 'แต่ขอยื่นพระหัตถ์เถิด และแตะต้องสิ่งของทั้งสิ้นที่เขามีอยู่ และเขาจะแช่งพระองค์ต่อพระพักตร์พระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 12, 'และพระเยโฮวาห์ตรัสกับซาตานว่า “ดูเถิด บรรดาสิ่งที่เขามีอยู่ก็อยู่ในอํานาจของเจ้า เพียงแต่อย่ายื่นมือแตะต้องตัวเขาเท่านั้น” ซาตานจึงออกไปจากพระพักตร์ของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 13, 'อยู่มาวันหนึ่งเมื่อบุตรชายหญิงของท่านกําลังรับประทานและดื่มน้ําองุ่นอยู่ในเรือนของพี่ชายหัวปีของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 14, 'มีผู้สื่อสารมาหาโยบเรียนว่า “วัวกําลังไถนาอยู่ และลากําลังกินหญ้าในที่ข้างๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 15, 'และคนเชบามาโจมตีเอามันไป และฆ่าคนใช้เสียด้วยคมดาบ และข้าพเจ้าผู้เดียวได้หนีรอดมาเรียนท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 16, 'ขณะที่เขากําลังพูดอยู่ ก็มีอีกคนหนึ่งมาเรียนว่า “เพลิงของพระเจ้าตกลงมาจากฟ้าสวรรค์ไหม้แกะและคนใช้และเผาผลาญเสียหมด และข้าพเจ้าแต่ผู้เดียวได้หนีรอดมาเรียนท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 17, 'ขณะที่เขากําลังพูดอยู่ มีอีกคนหนึ่งมาเรียนว่า “ชาวเคลเดียจัดเป็นสามกองทําการปล้นเอาอูฐไป และฆ่าคนใช้เสียด้วยคมดาบ และข้าพเจ้าผู้เดียวได้หนีรอดมาเรียนท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 18, 'ขณะที่เขากําลังพูดอยู่ มีอีกคนหนึ่งมาเรียนว่า “บุตรชายหญิงของท่านกําลังรับประทานและดื่มน้ําองุ่นอยู่ในเรือนของพี่ชายหัวปีของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 19, 'และดูเถิด มีพายุใหญ่ข้ามถิ่นทุรกันดารมากระทบเรือนทั้งสี่มุม และเรือนนั้นพังทับคนหนุ่ม และเขาก็ตาย และข้าพเจ้าผู้เดียวได้หนีรอดมาเรียนท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 20, 'แล้วโยบก็ลุกขึ้น ฉีกเสื้อคลุมของตน โกนศีรษะ กราบลงถึงดินนมัสการ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 21, 'ท่านว่า “ข้าพเจ้ามาจากครรภ์มารดาของข้าพเจ้าตัวเปล่า และข้าพเจ้าจะกลับไปตัวเปล่า พระเยโฮวาห์ทรงประทาน และพระเยโฮวาห์ทรงเอาไปเสีย สาธุการแด่พระนามพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 22, 'ในเหตุการณ์นี้ทั้งสิ้นโยบมิได้ทําบาปหรือกล่าวโทษพระเจ้าอย่างโง่เขลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 1, 'และอยู่มาวันหนึ่ง เมื่อบุตรชายทั้งหลายของพระเจ้ามารายงานตัวต่อพระพักตร์พระเยโฮวาห์ ซาตานก็มาในหมู่พวกเขาเพื่อรายงานตัวต่อพระพักตร์พระเยโฮวาห์ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 2, 'และพระเยโฮวาห์ตรัสถามซาตานว่า “เจ้ามาจากไหน” ซาตานทูลตอบพระเยโฮวาห์ว่า “จากไปๆมาๆอยู่บนแผ่นดินโลก และจากเดินขึ้นเดินลงบนนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 3, 'และพระเยโฮวาห์ตรัสกับซาตานว่า “เจ้าได้ไตร่ตรองดูโยบผู้รับใช้ของเราหรือไม่ว่า บนแผ่นดินโลกไม่มีใครเหมือนเขา เป็นคนดีรอบคอบและเที่ยงธรรม เกรงกลัวพระเจ้าและหันเสียจากความชั่วร้าย เขายังยึดมั่นในความซื่อสัตย์ของเขาอยู่ ถึงแม้เจ้าชวนเราให้ต่อสู้กับเขา เพื่อทําลายเขาโดยไม่มีเหตุ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 4, 'แล้วซาตานทูลตอบพระเยโฮวาห์ว่า “หนังแทนหนัง คนย่อมให้ทุกอย่างที่เขามีอยู่แทนชีวิตของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 5, 'แต่บัดนี้ ขอพระองค์เหยียดพระหัตถ์ของพระองค์ และแตะต้องกระดูกและเนื้อของเขา และเขาจะแช่งพระองค์ต่อพระพักตร์ของพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 6, 'และพระเยโฮวาห์ตรัสกับซาตานว่า “ดูเถิด เขาอยู่ในมือของเจ้า จงไว้ชีวิตของเขาเท่านั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 7, 'ซาตานจึงออกไปจากเบื้องพระพักตร์ของพระเยโฮวาห์ และได้ให้โยบเป็นฝีร้าย ตั้งแต่ฝ่าเท้าของท่านจนถึงกระหม่อมที่ศีรษะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 8, 'และท่านก็เอาชิ้นหม้อแตกขูดตัวของท่าน และนั่งอยู่ในกองขี้เถ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 9, 'แล้วภรรยาท่านเรียนว่า “ท่านยังจะยึดมั่นในความซื่อสัตย์ของท่านอีกหรือ จงแช่งพระเจ้าและตายเสียเถอะ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 10, 'แต่ท่านตอบนางว่า “เธอพูดอย่างหญิงโฉดจะพึงพูด อะไรกัน เราจะรับสิ่งดีจากพระหัตถ์ของพระเจ้า และจะไม่รับของชั่วบ้างหรือ” ในเหตุการณ์นี้ทั้งสิ้นโยบมิได้กระทําบาปด้วยริมฝีปากของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 11, 'เมื่อสหายทั้งสามของโยบได้ยินถึงภัยพิบัตินี้ทั้งสิ้นที่ได้เกิดขึ้นกับท่าน ต่างก็มาจากที่ของตน คือ เอลีฟัสชาวเทมาน บิลดัดคนชูอาห์ และโศฟาร์ชาวนาอามาห์ เขาได้นัดมาพร้อมกันเพื่อร่วมทุกข์กับท่านและเล้าโลมใจท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 12, 'เมื่อเขาเงยหน้าขึ้นแต่ไกลเขาก็จําท่านไม่ได้ ก็เปล่งเสียงร้องไห้ ต่างก็ฉีกเสื้อคลุมของตน และซัดผงคลีดินเหนือศีรษะของตนขึ้นไปยังฟ้าสวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 13, 'และนั่งกับท่านบนดินเจ็ดวันเจ็ดคืน ไม่มีสักคนหนึ่งพูดกับท่านสักคํา ด้วยเขาเห็นว่าความทุกข์ระทมของท่านนั้นใหญ่ยิ่งนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 1, 'ต่อมาโยบอ้าปากของท่านแช่งวันกําเนิดของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 2, 'และโยบว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 3, '“ขอให้วันซึ่งข้าเกิดนั้นพินาศทั้งคืนที่พูดว่า ‘ตั้งครรภ์เด็กชายคนหนึ่งแล้ว’ นั้นด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 4, 'ขอให้วันนั้นเป็นความมืด ขอพระเจ้าจากเบื้องบนอย่าแสวงหาวันนั้น หรืออย่าให้แสงสว่างส่องในวันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 5, 'ขอความมืดทึบและเงามัจจุราชยึดเอาวันนั้นไว้ ขอให้เมฆคลุมมันไว้ ขอให้ความดําทะมึนแห่งวันนั้นทําให้มันหวาดกลัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 6, 'คืนนั้นน่ะ ขอให้ความมืดทึบฉวยมันไว้ อย่าให้มันเข้าส่วนท่ามกลางบรรดาวันของปี อย่าให้นับมันเข้าเป็นส่วนของเดือนต่อไปเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 7, 'ดูเถิด ขอให้คืนนั้นเป็นหมัน ขออย่าให้เสียงร้องอันชื่นบานได้ยินในคืนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 8, 'ขอให้บรรดาผู้ที่สาปวันได้สาปคืนนั้นด้วย คือผู้ที่พร้อมจะเปล่งเสียงร้องคร่ําครวญ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 9, 'ขอให้ดาวเวลารุ่งสางของมันมืด ขอให้มันหวังความสว่าง แต่ไม่พบ อย่าให้เห็นแสงอรุณรุ่งเช้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 10, 'เพราะว่ามันมิได้ปิดประตูแห่งครรภ์มารดาของข้า หรือซ่อนความเศร้าโศกจากตาของข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 11, 'ทําไมข้าไม่ตายเสียแต่กําเนิด ทําไมข้าไม่ขาดใจเสียเมื่อข้าออกมาจากครรภ์แล้วก็สิ้นไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 12, 'ทําไมหัวเข่าจึงรับข้าไว้ หรือทําไมหัวนมมีให้ข้าดูด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 13, 'ถ้าหาไม่แล้ว ข้าจะนอนเงียบสงบอยู่ ข้าจะหลับ แล้วข้าจะได้หยุดพักอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 14, 'กับพวกกษัตริย์และพวกที่ปรึกษาของแผ่นดินโลก ผู้ได้สร้างที่โดดเดี่ยวอ้างว้างไว้สําหรับตัวเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 15, 'หรือกับเจ้านายผู้มีทองคํา ผู้บรรจุเงินไว้เต็มบ้าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 16, 'หรือทําไมข้าไม่เป็นอย่างลูกที่แท้งซึ่งซ่อนไว้ อย่างทารกซึ่งไม่เคยเห็นแสงสว่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 17, 'ที่นั่นคนชั่วร้ายหยุดดิ้นรน และที่นั่นผู้ที่เหนื่อยอ่อนได้หยุดพัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 18, 'ที่นั่นผู้ถูกจองจําก็สบายด้วยกัน เขาทั้งหลายไม่ได้ยินเสียงของผู้กดขี่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 19, 'ผู้ใหญ่และผู้น้อยก็อยู่ที่นั่น และทาสก็เป็นอิสระพ้นจากนายของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 20, 'ไฉนหนอผู้ที่ทนทุกข์เวทนาอย่างนี้ ยังได้รับแสงสว่าง และผู้ที่มีใจขมขื่นได้รับชีวิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 21, 'ผู้คอยความตาย แต่มันไม่มา และขุดหามันมากกว่าหาทรัพย์ที่ซ่อนอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 22, 'ผู้ซึ่งเปรมปรีดิ์อย่างยิ่งและยินดี เมื่อเขาพบหลุมฝังศพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 23, 'ไฉนจึงประทานความสว่างแก่ผู้ที่ทางของเขาซ่อนอยู่ ผู้ซึ่งพระเจ้าทรงล้อมรั้วต้นไม้กั้นไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 24, 'เพราะการถอนหายใจของข้ามีมาก่อนอาหารของข้า และการครวญครางของข้าก็เทออกมาเหมือนน้ําทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 25, 'เพราะสิ่งที่ข้ากลัวมากก็มาเหนือข้า และสิ่งที่ข้าครั่นคร้ามก็ตกแก่ข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 26, 'ข้าไม่สบายใจเลย ทั้งข้าก็ไม่สงบ ข้าไม่ได้หยุดพัก แต่ความทรมานก็มาหา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 1, 'แล้วเอลีฟัสชาวเทมานตอบว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 2, '“ถ้าจะลองพูดสักคํา ท่านจะทนไหวไหม ถึงกระนั้นใครจะอดพูดได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 3, 'ดูเถิด ท่านได้แนะนําคนมามากมายแล้ว และท่านได้เสริมมือที่อ่อนเปลี้ยให้มีกําลัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 4, 'ถ้อยคําของท่านหนุนใจคนที่กําลังสะดุด และท่านได้ทําเข่าที่อ่อนเปลี้ยให้มั่นคง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 5, 'แต่บัดนี้มาถึงท่านแล้ว และท่านก็ท้อใจ มันแตะต้องท่านเข้า และท่านก็ลําบากใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 6, 'ความยําเกรงของท่าน ความมั่นใจของท่าน ความหวังของท่าน และการประพฤติดีรอบคอบของท่านอยู่ที่ไหนเล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 7, 'ข้าขอร้องให้ท่านจําไว้หน่อยเถิดว่า ผู้ที่ไร้ความผิดเคยพินาศหรือ หรือคนเที่ยงธรรมถูกตัดออกที่ไหน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 8, 'ตามที่ข้าได้เห็น บรรดาผู้ที่ไถความชั่วช้า และหว่านความชั่วร้าย ก็ได้เกี่ยวอย่างนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 9, 'เขาพินาศด้วยลมหายใจของพระเจ้า และเขาต้องสิ้นไปด้วยลมแห่งพระนาสิกของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 10, 'เสียงคํารามของสิงโต และเสียงของสิงโตดุร้าย และฟันของสิงโตหนุ่มก็หักเสียแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 11, 'สิงโตแก่พินาศเพราะขาดเหยื่อ และลูกของสิงโตที่แข็งแรงก็กระจัดกระจายไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 12, 'มีคําหนึ่งมาถึงข้าอย่างเงียบๆ หูของข้าได้ยินเสียงกระซิบคํานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 13, 'ท่ามกลางความคิดจากนิมิตกลางคืนเมื่อคนหลับสนิท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 14, 'ความครั่นคร้ามมาเหนือข้าและตัวสั่น ซึ่งกระทําให้กระดูกทั้งสิ้นของข้าสั่นสะเทือน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 15, 'มีวิญญาณองค์หนึ่งผ่านหน้าของข้า ขนที่เนื้อของข้าลุกชัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 16, 'องค์นั้นนิ่งอยู่ แต่ข้าพิเคราะห์รูปร่างขององค์นั้นไม่ได้ มีสัณฐานอย่างหนึ่งข้างหน้าตาของข้า เงียบอยู่ แล้วข้าได้ยินเสียงหนึ่งว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 17, '‘มนุษย์ที่อ่อนแอจะชอบธรรมยิ่งกว่าพระเจ้าได้หรือ มนุษย์จะบริสุทธิ์ยิ่งกว่าผู้ทรงสร้างเขาได้หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 18, 'ดูเถิด แม้ผู้รับใช้ของพระองค์พระองค์ก็ไม่ทรงวางพระทัย และทูตสวรรค์ของพระองค์พระองค์ทรงกล่าวโทษที่เขาโง่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 19, 'ผู้ที่อาศัยในเรือนดินจะยิ่งกว่านั้นสักเท่าใด รากฐานของเขาอยู่ในผงคลีดิน ผู้ถูกขยี้เหมือนอย่างตัวมอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 20, 'เขาถูกทําลายระหว่างเวลาเช้าและเย็น เขาพินาศไปเป็นนิตย์โดยไม่มีผู้ใดสนใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 21, 'สง่าราศีซึ่งอยู่ภายในเขาจะหายไปมิใช่หรือ เขาจะตายด้วยปราศจากปัญญา’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 1, '“ร้องเรียกเดี๋ยวนี้ซิ มีผู้ใดจะตอบท่าน ท่านจะหันไปหาวิสุทธิชนผู้ใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 2, 'แน่ละ ความโกรธฆ่าคนโฉดและความริษยาฆ่าคนเขลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 3, 'ข้าเคยเห็นคนโฉดหยั่งราก แต่ทันใดนั้นข้าก็แช่งที่อาศัยของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 4, 'บุตรของเขาห่างไกลจากความปลอดภัย เขาถูกบีบคั้นที่ประตูเมือง และไม่มีผู้ใดช่วยเขาให้พ้นได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 5, 'ผลการเกี่ยวของเขาคนหิวก็กินเสีย แม้ส่วนที่เอาหนามปกไว้ เขาก็เอาออกไป และผู้ปล้นก็กลืนความมั่งคั่งของเขาเข้าไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 6, 'เพราะความทุกข์ใจมิได้มาจากผงคลี หรือความยากลําบากงอกออกมาจากดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 7, 'แต่มนุษย์เกิดมาเพื่อแก่ความยากลําบาก อย่างประกายไฟย่อมปลิวขึ้นบน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 8, 'ข้าจะแสวงหาพระเจ้า และข้าจะมอบเรื่องราวของข้ากับพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 9, 'ผู้ทรงกระทําการใหญ่เหลือที่จะหยั่งรู้ได้ และการมหัศจรรย์อย่างนับไม่ถ้วน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 10, 'พระองค์ประทานฝนบนแผ่นดินโลก และทรงส่งน้ํามาบนไร่นา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 11, 'พระองค์ทรงตั้งคนต่ําไว้บนที่สูง และบรรดาคนที่ไว้ทุกข์ก็ทรงยกขึ้นให้ปลอดภัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 12, 'พระองค์ทรงขัดขวางอุบายของเจ้าเล่ห์ เพื่อมือของเขาจะได้ทําไม่สําเร็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 13, 'พระองค์ทรงจับคนที่มีปัญญาด้วยอุบายของเขาเอง และคําปรึกษาของคนหลักแหลมก็สิ้นลงโดยด่วน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 14, 'เขาประสบความมืดในเวลากลางวัน และคลําไปในเที่ยงวันเหมือนอย่างกลางคืน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 15, 'แต่พระองค์ทรงช่วยคนขัดสนจากดาบ จากปากของเขา และจากมือของคนมีกําลัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 16, 'คนจนจึงมีความหวัง และความชั่วช้าก็ปิดปากของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 17, 'ดูเถิด มนุษย์คนใดที่พระเจ้าทรงติเตียนก็เป็นสุข เพราะฉะนั้นอย่าดูหมิ่นการตีสอนขององค์ผู้ทรงมหิทธิฤทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 18, 'เพราะพระองค์ทรงให้บาดเจ็บ แต่พระองค์ทรงพันแผลให้ พระองค์โบยตี แต่พระหัตถ์ของพระองค์ทรงรักษา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 19, 'พระองค์จะทรงช่วยท่านให้พ้นจากความยากลําบากหกประการ เออ เจ็ดประการ จะไม่มีเหตุร้ายมาแตะต้องท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 20, 'ในคราวกันดารอาหาร พระองค์จะทรงไถ่ท่านออกจากความตาย และในการสงคราม จากอานุภาพของดาบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 21, 'จะทรงซ่อนท่านไว้จากการใส่ร้ายของลิ้น และจะไม่กลัวการทําลายเมื่อมันมาถึง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 22, 'ท่านจะเยาะการทําลายและการกันดารอาหาร และจะไม่กลัวสัตว์ป่าดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 23, 'ท่านจะพันธมิตรกับหินแห่งทุ่งนา และสัตว์ป่าทุ่งจะอยู่อย่างสันติกับท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 24, 'ท่านจะทราบว่าเต็นท์ของท่านปลอดภัย และท่านจะไปพักในที่อาศัยของท่าน และจะไม่ทําความผิดบาป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 25, 'ท่านจะทราบด้วยว่าเชื้อสายของท่านจะมากมาย และลูกหลานของท่านจะเป็นอย่างหญ้าแห่งแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 26, 'ท่านจะมาที่หลุมศพของท่านเมื่อแก่หง่อม อย่างฟ่อนข้าวที่นํามาสู่ลานตามฤดู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 27, 'ดูเถิด นี่แหละ เป็นข้อที่เราตรองออกมาเป็นความจริง จงฟังและทราบ เพื่อประโยชน์ของตนเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 1, 'แล้วโยบตอบว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 2, '“โอ ข้าอยากให้ชั่งดูความเศร้าโศกของข้า และเอาความลําบากยากเย็นของข้าใส่ไว้ในตราชู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 3, 'บัดนี้ก็จะหนักกว่าทรายในทะเล เพราะเหตุนี้คําพูดของข้าก็จะถูกกลืนไปหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 4, 'เพราะธนูขององค์ผู้ทรงมหิทธิฤทธิ์ก็อยู่ในตัวข้า จิตใจของข้าดื่มพิษของมัน ความน่าหวาดเสียวจากพระเจ้าขยายแนวเข้าใส่ข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 5, 'ลาป่าร้องเมื่อมันมีหญ้าหรือ วัวผู้ร้องบนกองหญ้าของมันหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 6, 'จะรับประทานสิ่งที่จืดโดยไม่ใส่เกลือได้หรือ หรือไข่ขาวมีรสอะไรบ้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 7, 'สิ่งที่จิตใจของข้าไม่ยอมแตะต้องนั้น กลับเป็นอาหารระทมทุกข์ของข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 8, 'โอ ข้าอยากจะได้สมดังที่ทูลขอ และขอพระเจ้าทรงประทานตามความปรารถนาของข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 9, 'ว่าพระเจ้าพอพระทัยที่จะขยี้ข้าว่า พระองค์จะใช้พระหัตถ์ของพระองค์อย่างเต็มที่ และตัดข้าออกเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 10, 'นี่จะเป็นการปลอบโยนใจของข้า ข้าจะเสริมกําลังในความทุกข์ ขออย่าให้พระองค์แสดงพระเมตตา เพราะข้ามิได้ปกปิดพระวจนะขององค์ผู้บริสุทธิ์นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 11, 'ข้ามีกําลังอะไร ที่ข้าจะมีความหวัง และอะไรเป็นอวสานของข้า ที่ข้าจะต่อชีวิตของข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 12, 'กําลังของข้าเป็นกําลังของหินหรือ เนื้อของข้าเป็นเนื้อทองเหลืองหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 13, 'ข้าไม่มีความช่วยเหลือในตัวข้าหรือ ข้าจนปัญญาเสียแล้วหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 14, 'บุคคลผู้ใดสิ้นความหวังก็ควรได้รับความกรุณาจากเพื่อน แต่เขาทอดทิ้งความยําเกรงองค์ผู้ทรงมหิทธิฤทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 15, 'พี่น้องของข้าทรยศอย่างลําธาร อย่างลําธารที่น้ําไหลล้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 16, 'ซึ่งดําไปเหตุด้วยน้ําแข็ง และที่หิมะซ่อนตัวอยู่ในนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 17, 'เมื่อมันร้อนขึ้นมันก็หายไป เมื่อร้อนมันก็สูญไปจากที่ของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 18, 'หมู่คนเดินทางหันออกจากทางของเขา เขาขึ้นไปยังที่ร้างเปล่า และพินาศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 19, 'หมู่คนเดินทางของตําบลเทมามองดู คนเดินทางของเมืองเชบารอคอยหมู่คนเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 20, 'เพราะเขาทั้งหลายหวังใจ เขาจึงต้องผิดหวัง เขามาถึงที่นั่นและต้องละอายใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 21, 'เพราะบัดนี้ ท่านทั้งหลายก็ไร้ความหมาย ท่านเห็นความลําบากยากเย็นของข้า และท่านก็กลัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 22, 'ข้าพูดว่า ‘ขอของกํานัลข้าหน่อย’ หรือ ‘ขอสินบนจากทรัพย์สินของท่านให้ข้า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 23, 'หรือว่า ‘ขอช่วยข้าให้พ้นจากมือของปฏิปักษ์’ หรือว่า ‘ขอไถ่ข้าจากมือของผู้มีอํานาจ’ หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 24, 'สอนข้าซี และข้าจะเงียบ ขอทําให้ข้าเข้าใจว่าข้าผิดตรงไหน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 25, 'คําซื่อตรงมีอํานาจมากจริงๆ แต่คําติเตียนของท่านติเตียนอะไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 26, 'ท่านคิดว่าท่านติเตียนถ้อยคําได้หรือ เมื่อคําปราศรัยของคนสิ้นหวังเป็นแต่ลม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 27, 'เออ ท่านทั้งหลายเอาเปรียบลูกกําพร้าพ่อ และขุดบ่อดักจับเพื่อนของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 28, 'ฉะนั้นบัดนี้ ขอมองดูข้าด้วยความพอใจเถิด เพราะถ้าข้ามุสา ก็จะปรากฏแจ้งแก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 29, 'ขอทีเถอะ ขอหันคิดใหม่ อย่าทําความชั่วช้าเลย เออ กลับคิดใหม่เถอะ ข้ายังชอบธรรมอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 30, 'มีความชั่วช้าสิ่งใดบนลิ้นข้าหรือ ข้าไม่รู้ถึงรสภัยพิบัติหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 1, '“มนุษย์ไม่มีเวลากําหนดบนแผ่นดินโลกหรือ และชีวิตของเขาไม่เหมือนชีวิตของลูกจ้างดอกหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 2, 'เหมือนอย่างทาสที่ปรารถนาเงา และเหมือนอย่างลูกจ้างผู้มองหาค่าจ้างแห่งงานของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 3, 'เช่นเดียวกัน ข้าต้องได้รับส่วนเปล่าประโยชน์เป็นเดือนๆ และเขาแบ่งคืนแห่งความน่าอิดโรยแก่ข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 4, 'เมื่อข้านอนลง ข้าว่า ‘เมื่อไรหนอข้าจะลุกขึ้น และกลางคืนจะผ่านพ้นไป’ และข้าก็พลิกไปพลิกมาจนรุ่งเช้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 5, 'เนื้อของข้าห่มหนอนและก้อนฝุ่น หนังของข้าแข็งขึ้น แล้วก็น่ารังเกียจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 6, 'วันคืนของข้าเร็วกว่ากระสวยของช่างทอ และสิ้นสุดลงด้วยไร้ความหวัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 7, 'โอ ขอทรงจําไว้ว่า ชีวิตของข้าพระองค์เป็นแต่ลมหายใจ ตาของข้าพระองค์จะไม่เห็นสิ่งดีอีกเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 8, 'ตาของผู้ที่เห็นข้าพระองค์จะไม่ได้ดูข้าพระองค์อีกต่อไป ฝ่ายพระเนตรของพระองค์มองหาข้าพระองค์ ข้าพระองค์ก็ไปเสียแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 9, 'เมฆจางและหายไปฉันใด บุคคลที่ลงไปยังแดนคนตายก็มิได้ขึ้นมาฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 10, 'เขาจะไม่กลับไปเรือนของเขาอีก หรือที่อยู่ของเขาก็จะไม่รู้จักเขาอีกเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 11, 'เพราะฉะนั้น ข้าพระองค์จึงไม่ยับยั้งปากของข้าพระองค์ ข้าพระองค์จะพูดด้วยความแสนระทมแห่งจิตใจของข้าพระองค์ ข้าพระองค์จะบ่นด้วยความขมขื่นแห่งจิตใจของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 12, 'ข้าพระองค์เป็นทะเล หรือเป็นปลาวาฬหรือ พระองค์จึงทรงวางยามเฝ้าข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 13, 'เมื่อข้าพระองค์พูดว่า ‘เตียงของข้าจะเล้าโลมข้า ที่นอนของข้าจะบรรเทาการร้องทุกข์ของข้า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 14, 'แล้วพระองค์ก็ทําให้ข้าพระองค์กลัวด้วยความฝัน และทําให้ข้าพระองค์หวาดเสียวด้วยนิมิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 15, 'จิตใจข้าพระองค์จึงเลือกที่จะถูกรัดคอตาย และเลือกความตายแทนชีวิตของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 16, 'ข้าพระองค์เบื่อชีวิต ข้าพระองค์จะไม่อยู่ตลอดไป ปล่อยข้าพระองค์แต่ลําพังเถิด เพราะวันคืนของข้าพระองค์เป็นแต่เพียงเปล่าประโยชน์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 17, 'มนุษย์เป็นอะไร พระองค์จึงทรงถือว่าเขาสําคัญนัก และที่พระองค์ใส่พระทัยเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 18, 'ทรงเยี่ยมเขาทุกเช้า ทรงลองดูเขาทุกขณะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 19, 'อีกนานเท่าใดพระองค์จึงจะไม่ทรงออกไปจากข้าพระองค์ หรือปล่อยข้าพระองค์แต่ลําพัง จนข้าพระองค์จะกลืนน้ําลายของตนได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 20, 'โอ ข้าแต่พระองค์ผู้ปกปักรักษามนุษย์ ข้าพระองค์ทําบาปแล้ว ข้าพระองค์จะทําอะไรแก่พระองค์เล่า ทําไมพระองค์จึงทรงทําให้ข้าพระองค์เป็นเป้าหมายของพระองค์ ดังนั้นจึงเป็นภาระหนักแก่ข้าพระองค์เอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 21, 'ทําไมพระองค์ไม่ทรงประทานอภัยแก่การละเมิดของข้าพระองค์ และนําเอาความชั่วช้าของข้าพระองค์ไปเสีย เพราะบัดนี้ข้าพระองค์จะนอนลงในผงคลีดิน พระองค์จะทรงเสาะหาข้าพระองค์ในเวลาเช้า แต่ข้าพระองค์จะไม่อยู่แล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 1, 'แล้วบิลดัดคนชูอาห์ตอบว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 2, '“ท่านจะพูดอย่างนี้อยู่นานเท่าใด และคําปากของท่านจะเป็นพายุนานสักเท่าใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 3, 'พระเจ้าทรงผันแปรความยุติธรรมหรือ หรือองค์ผู้ทรงมหิทธิฤทธิ์ผันแปรความเที่ยงธรรมหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 4, 'ถ้าบุตรของท่านได้กระทําบาปต่อพระองค์ และพระองค์ทรงทอดทิ้งเขาทั้งหลายเพราะเหตุการละเมิดของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 5, 'ถ้าท่านจะหมั่นแสวงหาพระเจ้า และวิงวอนต่อองค์ผู้ทรงมหิทธิฤทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 6, 'ถ้าท่านบริสุทธิ์และเที่ยงธรรมแน่ละ บัดนี้พระองค์ก็จะทรงตื่นขึ้นเพื่อท่าน และทรงให้ที่อาศัยแห่งความชอบธรรมของท่านเจริญเป็นแน่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 7, 'ถึงแม้การเริ่มต้นของท่านจะเล็กน้อย แต่ต่อไปปลายๆจะใหญ่โตมากยิ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 8, 'ข้าขอร้อง ให้ท่านถามคนโบราณดู และคิดดูว่า บรรพบุรุษค้นพบสิ่งใดบ้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 9, '(เพราะส่วนเราเหมือนอย่างเกิดวานนี้ จะรู้อะไรก็หาไม่ เพราะวันคืนของเราบนแผ่นดินโลกเปรียบเหมือนเงา)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 10, 'เขาจะไม่สอนท่านและบอกท่าน และกล่าวคําจากใจของเขาหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 11, 'ต้นกกจะงอกขึ้นในที่ที่ไม่มีตมได้หรือ ต้นอ้อจะงอกงามในที่ที่ไม่มีน้ําได้หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 12, 'ขณะที่มีดอกยังไม่ได้ตัดลง มันก็เหี่ยวแห้งไปก่อนต้นไม้อื่นๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 13, 'ทางของบรรดาผู้ที่ลืมพระเจ้าก็เป็นอย่างนั้นแหละ ความหวังของคนหน้าซื่อใจคดจะพินาศไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 14, 'ความหวังใจของเขาหักสะบั้น และความไว้วางใจของเขาจะเหมือนใยแมงมุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 15, 'เขาพิงเรือนของเขา แต่มันทานไม่ไหว เขายึดมันไว้ แต่มันก็หาทนอยู่ไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 16, 'เขาเขียวสดอยู่ต่อหน้าดวงอาทิตย์ และแขนงของเขาก็แผ่ออกเหนือสวนของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 17, 'รากของเขาเลื้อยไปเกาะกองหิน และหยั่งลงไปในซอกก้อนหิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 18, 'ถ้าพระองค์ทําลายเขาไปจากที่ของเขาแล้วที่นั้นจะปฏิเสธเขาว่า ‘ข้าไม่เคยเห็นเจ้า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 19, 'ดูเถิด นี่เป็นความชื่นบานแห่งทางของเขา และผู้อื่นจะงอกออกมาจากดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 20, 'ดูเถิด พระเจ้าจะไม่ทรงทอดทิ้งคนดีรอบคอบ หรือค้ําจุนผู้กระทําความชั่วร้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 21, 'พระองค์ยังจะทรงให้ปากของท่านหัวเราะร่วน และทําให้ริมฝีปากของท่านโห่ร้องเสมอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 22, 'คนเหล่านั้นที่เกลียดชังท่านจะห่มความอับอาย และที่อาศัยของคนชั่วจะไม่มีต่อไปอีกเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 1, 'แล้วโยบตอบว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 2, '“จริงทีเดียว ข้าทราบว่าเป็นอย่างนั้น แต่คนเราจะชอบธรรมจําเพาะพระพักตร์พระเจ้าได้อย่างไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 3, 'ถ้าคนหนึ่งคนใดปรารถนาจะโต้แย้งกับพระองค์ ในพันครั้งผู้นั้นก็ตอบพระองค์ไม่ได้สักครั้งเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 4, 'พระองค์ฉลาดอยู่ในพระทัย และพระกําลังก็แข็งแรง ผู้ใดเคยได้แข็งข้อต่อพระองค์และเจริญขึ้นได้เล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 5, 'พระองค์ผู้ทรงเคลื่อนภูเขา และภูเขาทั้งหลายก็ไม่รู้ เมื่อพระองค์ทรงคว่ํามันเสียด้วยพระพิโรธของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 6, 'ผู้ทรงสั่นแผ่นดินโลกให้ออกจากที่ของมัน และเสาของมันก็สั่นสะเทือน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 7, 'ผู้ทรงบัญชาดวงอาทิตย์ และมันไม่ขึ้น ผู้ทรงผนึกเก็บบรรดาดวงดาวไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 8, 'ผู้ทรงขึงฟ้าสวรรค์ออกแต่พระองค์เดียว และทรงย่ําคลื่นของทะเล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 9, 'ผู้ทรงสร้างหมู่ดาวจระเข้ และหมู่ดาวไถ หมู่ดาวลูกไก่ และหมู่ดาวทิศใต้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 10, 'ผู้ทรงกระทํามหกิจเหลือที่จะเข้าใจได้ และการมหัศจรรย์อย่างนับไม่ถ้วน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 11, 'ดูเถิด พระองค์ทรงผ่านข้าไป และข้าหาเห็นพระองค์ไม่ พระองค์ทรงเลยไป และข้าหาสังเกตเห็นไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 12, 'ดูเถิด พระองค์ทรงฉวยไป ใครจะห้ามพระองค์ได้ ใครจะทูลพระองค์ว่า ‘พระองค์ทรงกระทําอะไรนั่น’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 13, 'ถ้าพระเจ้าจะไม่ทรงหันพระพิโรธของพระองค์กลับต่อพระองค์ เหล่าสมุนของความอหังการต้องกราบอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 14, 'แล้วข้าจะตอบพระองค์ได้อย่างไร จะเลือกถ้อยคําอะไรมาโต้ตอบพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 15, 'แม้ว่าข้าชอบธรรม ข้าก็ตอบพระองค์ไม่ได้ ข้าจะต้องขอพระกรุณาต่อผู้พิพากษาของข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 16, 'ถ้าข้าร้องทูลต่อพระองค์ และพระองค์ทรงตอบข้า ข้าจะไม่เชื่อว่าพระองค์ทรงฟังเสียงของข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 17, 'เพราะพระองค์ทรงขยี้ข้าด้วยพายุ และทวีบาดแผลของข้าโดยไม่มีเหตุ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 18, 'พระองค์จะไม่ทรงให้ข้าหายใจได้ แต่เติมความขมขื่นให้ข้าเต็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 19, 'ถ้าข้ากล่าวถึงกําลัง ดูเถิด พระองค์ทรงมีฤทธิ์ ถ้าเป็นเรื่องการพิพากษา ใครจะนัดเวลาให้ข้าสู้คดีได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 20, 'ถ้าข้าอ้างว่าตัวชอบธรรม ปากของข้าจะกล่าวโทษข้า ถ้าข้าอ้างว่าตัวดีรอบคอบ พระองค์จะพิสูจน์ว่าข้าบกพร่อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 21, 'ถึงแม้ข้าดีรอบคอบ ข้าก็ไม่เข้าใจตัวข้าเอง ข้าจะเกลียดชีวิตของข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 22, 'ก็เหมือนกันหมด เพราะฉะนั้นข้าจึงว่า ‘พระองค์ทรงทําลายทั้งคนดีรอบคอบและคนชั่ว’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 23, 'เมื่อภัยพิบัตินําความตายมาโดยฉับพลัน พระองค์ทรงเยาะเย้ยความลําบากยากเย็นของผู้ไร้ผิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 24, 'แผ่นดินโลกนี้ทรงมอบไว้ในมือของคนชั่ว พระองค์ทรงปิดหน้าบรรดาผู้วินิจฉัยโลก ถ้าไม่ใช่พระองค์ แล้วใครเล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 25, '‘วันทั้งหลายของข้าพระองค์เร็วกว่านักวิ่ง มันพ้นไป มันไม่เห็นสิ่งดีอะไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 26, 'มันผ่านไปอย่างกับเรือเร็ว ดังนกอินทรีโฉบลงบนเหยื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 27, 'ถ้าข้าพระองค์ว่า “ข้าจะลืมคําร้องทุกข์ของข้า ข้าจะทิ้งหน้าเศร้าของข้าเสีย และเบิกบาน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 28, 'ข้าพระองค์เกิดกลัวบรรดาความทุกข์ของข้าพระองค์ เพราะข้าพระองค์ทราบว่าพระองค์จะไม่ถือว่าข้าพระองค์ไร้ผิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 29, 'ถ้าข้าพระองค์ชั่วช้า ข้าพระองค์ตรากตรําเปล่าๆทําไม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 30, 'ถ้าข้าพระองค์ชําระตัวของข้าพระองค์ด้วยน้ําจากหิมะ และล้างมือของข้าพระองค์ด้วยน้ําด่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 31, 'พระองค์ยังจะทรงจุ่มข้าพระองค์ลงไปในบ่อ แม้เสื้อผ้าของข้าพระองค์จะรังเกียจข้าพระองค์’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 32, 'พระองค์มิใช่มนุษย์อย่างข้า ที่ข้าจะตอบพระองค์ ซึ่งเราจะมาสู้คดีด้วยกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 33, 'ไม่มีคนกลางระหว่างเรา ผู้ซึ่งจะวางมือบนเราทั้งสองได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 34, 'ขอให้พระองค์ทรงนําไม้เรียวไปจากข้าเสียที และขออย่าให้ความครั่นคร้ามจากพระองค์กระทําให้ข้ากลัวมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 35, 'แล้วข้าจะพูดและไม่กลัวพระองค์ แต่ใจจริงของข้าไม่เป็นอย่างนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 1, '“จิตใจข้าเบื่อชีวิตของข้า ข้าจะร้องทุกข์อย่างไม่ยับยั้ง ข้าจะพูดด้วยจิตใจขมขื่นของข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 2, 'ข้าจะทูลพระเจ้าว่า ‘ขออย่าทรงกล่าวโทษข้าพระองค์ ขอให้ข้าพระองค์ทราบว่าไฉนพระองค์ทรงโต้แย้งกับข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 3, 'พระองค์ทรงเห็นชอบแล้วหรือที่จะบีบบังคับ ที่จะหมิ่นพระหัตถกิจของพระองค์ และทรงโปรดแผนการของคนชั่ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 4, 'พระองค์ทรงมีพระเนตรอย่างตาคนหรือ พระองค์ทรงเห็นอย่างมนุษย์เห็นหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 5, 'วันของพระองค์เหมือนวันของมนุษย์หรือ ปีของพระองค์เหมือนวันคืนของคนเราหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 6, 'ที่พระองค์ทรงคอยจับความชั่วช้าข้าพระองค์ และค้นหาบาปของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 7, 'แม้พระองค์ทรงทราบว่าข้าพระองค์มิได้เป็นคนชั่ว และไม่มีใครช่วยให้พ้นออกจากพระหัตถ์ของพระองค์ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 8, 'พระหัตถ์ของพระองค์ปั้นและทรงสร้างข้าพระองค์ ถึงกระนั้นพระองค์ทรงหันมาทําลายข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 9, 'ขอทรงระลึกว่าพระองค์ทรงสร้างข้าพระองค์ดุจดังดินเหนียว พระองค์จะทรงนําข้าพระองค์ให้กลับเป็นผงคลีดินอีกหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 10, 'พระองค์มิได้ทรงเทข้าพระองค์ออกอย่างน้ํานม และทําข้าพระองค์ให้แข็งเหมือนเนยแข็งหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 11, 'พระองค์ทรงห่มข้าพระองค์ไว้ด้วยหนังและเนื้อ และทรงสานข้าพระองค์ด้วยกระดูกและเส้นเอ็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 12, 'พระองค์ทรงประสาทชีวิตและความเมตตาแก่ข้าพระองค์ และความดูแลรักษาของพระองค์ได้สงวนจิตวิญญาณข้าพระองค์ไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 13, 'แต่สิ่งต่อไปนี้พระองค์ทรงซ่อนไว้ในพระทัยของพระองค์ ข้าพระองค์ทราบว่านี่เป็นพระประสงค์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 14, 'ถ้าข้าพระองค์ทําบาป พระองค์ทรงหมายข้าพระองค์ไว้ และไม่ทรงปล่อยตัวข้าพระองค์ให้พ้นโทษความชั่วช้าของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 15, 'ถ้าข้าพระองค์ชั่วร้าย วิบัติแก่ข้าพระองค์ ถ้าข้าพระองค์ชอบธรรม ข้าพระองค์ยังผงกศีรษะของข้าพระองค์ขึ้นไม่ได้ ข้าพระองค์เต็มด้วยความอดสู ฉะนั้นขอมองดูความทุกข์ใจของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 16, 'ภัยพิบัติต่างๆเพิ่มมากขึ้น พระองค์จะทรงล่าข้าพระองค์อย่างสิงโตดุร้าย และทรงทําการมหัศจรรย์สู้ข้าพระองค์อีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 17, 'พระองค์ทรงฟื้นพยานของพระองค์ปรักปรําข้าพระองค์ใหม่ และทรงเพิ่มความร้อนพระทัยของพระองค์ในข้าพระองค์ พระองค์ทรงนําพลโยธาหลายกองมาสู้ข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 18, 'ไฉนพระองค์ทรงนําข้าพระองค์ออกมาจากครรภ์ โอ ข้าพระองค์อยากตายก่อนตาใดๆได้เห็นข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 19, 'เหมือนอย่างกับว่าข้าพระองค์มิได้เกิดมา ข้าพระองค์คงถูกนําจากครรภ์ไปถึงหลุมฝังศพแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 20, 'วันคืนชีวิตของข้าพระองค์ไม่น้อยหรือ ขอหยุดเถิด ขอให้ข้าพระองค์อยู่ลําพัง เพื่อข้าพระองค์จะชื่นใจสักหน่อย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 21, 'ก่อนที่ข้าพระองค์จะไปยังที่ที่ข้าพระองค์ไม่กลับ ถึงแผ่นดินแห่งความมืดและเงามัจจุราช');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 22, 'แผ่นดินแห่งความมืดทึบดังตัวความมืดทีเดียว เป็นแผ่นดินแห่งเงามัจจุราช ไม่มีระเบียบ ที่ความสว่างเป็นเหมือนความมืด’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 1, 'แล้วโศฟาร์ชาวนาอามาห์ตอบว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 2, '“ควรที่จะฟังมวลถ้อยคําโดยไม่มีใครตอบหรือ และคนที่พูดมากควรจะนับว่าชอบธรรมหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 3, 'ควรที่คําพูดมุสาของท่านทําให้คนนิ่ง และเมื่อท่านเยาะเย้ย ไม่ควรมีผู้ใดทําให้ท่านอายหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 4, 'เพราะท่านว่า ‘หลักคําสอนของข้าบริสุทธิ์ และข้าก็สะอาดในสายพระเนตรพระเจ้า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 5, 'แต่ โอ ใคร่จะให้พระเจ้าตรัสและทรงเปิดริมพระโอษฐ์ของพระองค์ตรัสกับท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 6, 'ใคร่จะให้พระองค์ทรงสําแดงเคล็ดลับของสติปัญญาให้ท่าน เพราะความเข้าใจของพระองค์อเนกอนันต์ จงทราบเถิดว่าพระเจ้าทรงเรียกร้องจากท่านน้อยกว่าความชั่วช้าของท่านพึงได้รับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 7, 'ท่านจะหยั่งรู้สภาพของพระเจ้าได้หรือ ท่านหยั่งรู้องค์ผู้ทรงมหิทธิฤทธิ์ได้หมดหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 8, 'นั่นสูงเท่าฟ้าสวรรค์ ท่านจะทําอะไรได้ ลึกกว่านรก ท่านจะทราบอะไรได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 9, 'วัดดูก็ยาวกว่าโลก และกว้างกว่าทะเล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 10, 'ถ้าพระองค์ทรงตัดออก และทรงคุมขัง และทรงเรียกมาชุมนุมกัน ใครจะขัดขวางพระองค์ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 11, 'เพราะพระองค์ทรงทราบคนไร้ค่า เมื่อพระองค์ทรงเห็นความชั่วร้าย พระองค์จะไม่ทรงพิจารณาหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 12, 'แต่คนไร้ค่าอยากฉลาด ถึงแม้ว่ามนุษย์เกิดมาเหมือนลูกลาป่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 13, 'ถ้าท่านเตรียมใจของท่านไว้ และท่านเหยียดมือของท่านออกไปหาพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 14, 'ถ้าความชั่วช้าอยู่ในมือของท่าน ทิ้งเสียให้ไกล และอย่าให้ความชั่วร้ายอาศัยอยู่ในเต็นท์ของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 15, 'แล้วแน่ละ ท่านจะเงยหน้าขึ้นโดยปราศจากตําหนิ ท่านจะมั่นคง และไม่ต้องกลัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 16, 'เพราะท่านจะลืมความทุกข์ยากของท่าน ท่านจะจดจําได้เหมือนน้ําที่ได้ไหลผ่านพ้นไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 17, 'แล้วชีวิตของท่านจะสุกใสยิ่งกว่าเวลาเที่ยงวัน ท่านจะส่องแสงเหมือนเวลาเช้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 18, 'และท่านจะรู้สึกมั่นคง เพราะมีความหวัง เออ ท่านจะตรวจตราดู และนอนพักอย่างปลอดภัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 19, 'ท่านจะนอนลง และไม่มีใครทําให้ท่านกลัว เออ คนเป็นอันมากจะมาวอนขอความช่วยเหลือจากท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 20, 'แต่ตาของคนชั่วร้ายจะมืดมัว เขาจะหลีกเลี่ยงหลบหนีไม่ได้ และความหวังของเขาจะเหมือนความตายนั่นเอง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 1, 'แล้วโยบตอบว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 2, '“ไม่ต้องสงสัยเลยที่ท่านทั้งหลายเป็นเสียงของประชาชน และสติปัญญาจะตายไปพร้อมกับท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 3, 'แต่ข้าก็มีความเข้าใจอย่างกับท่าน ข้าไม่ด้อยกว่าท่าน เออ เรื่องอย่างนี้ใครจะไม่ทราบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 4, 'ข้าเป็นเหมือนผู้ที่ให้เพื่อนบ้านหัวเราะเยาะ ผู้ร้องทูลพระเจ้าและพระองค์ทรงตอบ คนดีรอบคอบอันชอบธรรมเป็นที่ให้เขาหัวเราะเยาะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 5, 'ในความคิดของผู้ที่อยู่อย่างสบาย ผู้มีเท้าพร้อมที่จะพลาดเหมือนตะเกียงที่ถูกสบประมาท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 6, 'เต็นท์ของโจรก็มั่งคั่ง และบุคคลที่ยั่วเย้าพระเจ้าก็มั่นคง พระเจ้าทรงนําของมากมายมาสู่มือของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 7, 'แต่ขอถามสัตว์เดียรัจฉาน และมันจะสอนท่าน ถามนกในอากาศดู และมันจะบอกท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 8, 'หรือพูดกับแผ่นดินโลก และมันจะสอนท่าน และปลาทะเลจะประกาศแก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 9, 'ในบรรดาสิ่งเหล่านี้มีสิ่งใดที่ไม่ทราบว่าพระหัตถ์ของพระเยโฮวาห์ทรงกระทําให้เป็นไปอย่างนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 10, 'จิตใจของสิ่งที่มีชีวิตทุกอย่างอยู่ในพระหัตถ์ของพระองค์ ทั้งลมหายใจของมนุษย์ทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 11, 'หูทดลองถ้อยคํามิใช่หรือ และเพดานปากชิมรสอาหารมิใช่หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 12, 'สติปัญญาอยู่กับคนมีอายุมาก และอายุยืนยาวทําให้เกิดความเข้าใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 13, 'สติปัญญาและฤทธานุภาพอยู่กับพระเจ้า พระองค์ทรงมีคําแนะนําและความเข้าใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 14, 'ดูเถิด พระองค์ทรงพังทลายลงและไม่มีผู้ใดสร้างใหม่ได้ พระองค์ทรงกักขังมนุษย์คนหนึ่งไว้และไม่มีผู้ใดเปิดได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 15, 'ดูเถิด พระองค์ทรงยึดน้ําไว้และมันก็แห้งไป ดังนั้นพระองค์ทรงส่งมันออกไปและมันก็ท่วมแผ่นดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 16, 'พระกําลังและพระสติปัญญาอยู่กับพระองค์ ผู้ถูกลวงทั้งผู้ลวงเป็นของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 17, 'พระองค์ทรงนําที่ปรึกษาตัวล่อนจ้อนไป และพระองค์ทรงกระทําผู้พิพากษาให้เป็นคนโง่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 18, 'พระองค์ทรงแก้พันธนาการของกษัตริย์ และทรงผูกมัดเอวของกษัตริย์เหล่านั้นด้วยผ้าคาดเอว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 19, 'พระองค์ทรงนําเจ้าชายตัวล่อนจ้อนไป และทรงคว่ําผู้มีกําลังเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 20, 'พระองค์ทรงเอาคําพูดไปเสียจากผู้ที่เขาวางใจ และทรงนําการพินิจพิจารณาไปเสียจากพวกผู้มีอายุ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 21, 'พระองค์ทรงเทความเหยียดหยามบนเจ้านาย และทรงกระทําให้ผู้ที่แข็งแรงอ่อนกําลัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 22, 'พระองค์ทรงเปิดสิ่งที่ลึกออกมาจากความมืด และทรงนําเงามัจจุราชมาสู่ความสว่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 23, 'พระองค์ทรงกระทําประชาชาติให้ใหญ่โต และทรงทําลายเสีย พระองค์ทรงขยายบรรดาประชาชาติ และทรงนําเขาทั้งหลายให้แคบลงอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 24, 'พระองค์ทรงนําความเข้าใจไปเสียจากหัวหน้าชาวโลก และทรงกระทําให้เขาพเนจรไปในถิ่นทุรกันดารซึ่งไม่มีหนทาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 25, 'เขาทั้งหลายคลําอยู่ในความมืดปราศจากความสว่าง และพระองค์ทรงทําให้เขาโซเซอย่างคนเมา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 1, '“ดูเถิด ตาของข้าได้เห็นสิ่งทั้งหมดนี้แล้ว หูของข้าได้ยินและเข้าใจเรื่องนี้แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 2, 'อะไรที่ท่านทั้งหลายรู้ ข้าก็รู้ด้วย ข้าไม่ด้อยกว่าท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 3, 'แต่ข้าใคร่จะทูลต่อองค์ผู้ทรงมหิทธิฤทธิ์ และปรารถนาจะสู้คดีของข้ากับพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 4, 'ส่วนท่าน ท่านฉาบเสียด้วยการมุสา ท่านทั้งปวงเป็นแพทย์ที่ใช้ไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 5, 'โอ ท่านน่าจะนิ่งเสีย และความนิ่งนั้นจะเป็นสติปัญญาของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 6, 'บัดนี้ขอฟังการหาเหตุผลของข้า และขอฟังคําวิงวอนแห่งริมฝีปากของข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 7, 'ท่านทั้งหลายจะพูดชั่วร้ายเพื่อพระเจ้าหรือ และพูดลวงเพื่อพระองค์หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 8, 'ท่านทั้งหลายจะแสดงความลําเอียงเข้าข้างพระองค์หรือ ท่านจะว่าความฝ่ายพระเจ้าหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 9, 'เมื่อพระองค์ทรงค้นท่านพบ จะดีแก่ท่านไหม หรือท่านจะเยาะเย้ยพระองค์ได้อย่างผู้หนึ่งผู้ใดเยาะเย้ยมนุษย์หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 10, 'พระองค์จะทรงตําหนิท่านทั้งหลายแน่ ถ้าท่านแสดงความลําเอียงอย่างลับๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 11, 'ความโอ่อ่าตระการของพระองค์จะไม่กระทําให้ท่านคร้ามกลัว และความครั่นคร้ามต่อพระองค์จะไม่ตกเหนือท่านหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 12, 'ความระลึกถึงทั้งหลายของท่านเป็นเหมือนอย่างขี้เถ้า ร่างกายของท่านเป็นแต่กายดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 13, 'ขอนิ่งเถอะ และข้าจะพูด และอะไรจะเกิดแก่ข้า ก็ขอให้เกิดเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 14, 'ทําไมน่ะหรือ ข้าจะงับเนื้อของข้าไว้ และเสี่ยงชีวิตของข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 15, 'ถึงแม้พระองค์ทรงประหารข้าเสีย ข้าก็จะยังวางใจในพระองค์ แต่ข้าจะยังยืนยันทางทั้งหลายของข้าจําเพาะพระพักตร์พระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 16, 'พระองค์จะทรงเป็นความรอดของข้าด้วย เพราะคนหน้าซื่อใจคดจะไม่ได้เข้ามาต่อเบื้องพระพักตร์พระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 17, 'ขอฟังถ้อยคําของข้าอย่างระมัดระวัง และให้คํากล่าวของข้าอยู่ในหูของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 18, 'ดูเถิด ข้าเตรียมคดีของข้าแล้ว ข้าทราบว่า จะปรากฏว่าข้าบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 19, 'ใครนะจะสู้คดีกับข้า เพราะบัดนี้ ถ้าข้านิ่งเสีย ข้าก็จะตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 20, '‘ขอทรงประสาทสองสิ่งแก่ข้าพระองค์ และข้าพระองค์จะไม่ซ่อนตัวจากพระพักตร์พระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 21, 'ขอทรงหดพระหัตถ์ให้ไกลจากข้าพระองค์ และขออย่าให้ความครั่นคร้ามพระองค์ทําให้ข้าพระองค์คร้ามกลัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 22, 'ขอพระองค์ทรงเรียกเถิด แล้วข้าพระองค์จะทูลตอบ หรือขอให้ข้าพระองค์ทูล และขอพระองค์ทรงตอบแก่ข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 23, 'บรรดาความชั่วช้าและความบาปผิดของข้าพระองค์มีเท่าใด ขอทรงโปรดให้ข้าพระองค์ทราบถึงการละเมิดและบาปของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 24, 'ทําไมพระองค์ทรงเมินพระพักตร์เสีย และทรงนับว่าข้าพระองค์เป็นศัตรูของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 25, 'พระองค์จะทรงให้ใบไม้ที่ถูกลมพัดหักเสียหรือ และจะทรงไล่ติดตามฟางแห้งหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 26, 'เพราะพระองค์ทรงจารึกสิ่งขมขื่นต่อสู้ข้าพระองค์ และทรงกระทําให้ข้าพระองค์รับโทษความชั่วช้าที่ข้าพระองค์กระทําเมื่อยังรุ่นๆอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 27, 'พระองค์ทรงเอาเท้าของข้าพระองค์ใส่ขื่อไว้ และทรงเฝ้าดูทางทั้งสิ้นของข้าพระองค์ พระองค์ทรงจารึกเครื่องหมายไว้บนฝ่าเท้าของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 28, 'มนุษย์ก็ทรุดโทรมไปเหมือนของเน่า เหมือนเครื่องแต่งกายที่ตัวมอดกิน’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 1, '“‘มนุษย์ที่เกิดมาโดยผู้หญิงก็อยู่แต่น้อยวัน และเต็มไปด้วยความยุ่งยากใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 2, 'เขาออกมาเหมือนดอกไม้ แล้วก็ถูกตัดให้ล้มลง เขาลี้ไปอย่างเงา และไม่อยู่ต่อไปอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 3, 'และพระองค์ทรงลืมพระเนตรมองคนอย่างนี้หรือ และทรงนําข้าพระองค์มาในการพิพากษาของพระองค์หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 4, 'ใครจะเอาสิ่งสะอาดออกมาจากสิ่งไม่สะอาดได้ ไม่มีใครสักคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 5, 'วันเวลาของเขาถูกกําหนดไว้เสียแล้ว และจํานวนเดือนของเขาก็อยู่กับพระองค์ พระองค์ทรงกําหนดขอบเขตของเขาไม่ให้เขาผ่านไปได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 6, 'ฉะนั้น ขอทรงหันพระพักตร์ไปจากเขา และทรงเลิกเถิดพระเจ้าข้า เพื่อให้เขาชื่นบานด้วยวันของเขาอย่างลูกจ้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 7, 'เพราะสําหรับต้นไม้ก็มีความหวัง ถ้ามันถูกตัดลง มันก็จะแตกหน่ออีก และหน่ออ่อนของมันจะไม่หยุดยั้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 8, 'ถึงรากของมันจะแก่อยู่ในดิน และตอของมันจะตายอยู่ในผงคลีดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 9, 'แต่พอได้กลิ่นไอของน้ํา มันจะงอกและแตกกิ่งออกเหมือนต้นไม้อ่อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 10, 'แต่มนุษย์ตาย และล้มพังพาบ เออ มนุษย์สิ้นลมหายใจและเขาอยู่ที่ไหนเล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 11, 'น้ําขาดจากทะเลไป และแม่น้ําก็เหือดและแห้งไปฉันใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 12, 'ฉันนั้นแหละ มนุษย์ก็นอนลงและไม่ลุกขึ้นอีก จนท้องฟ้าไม่มีอีก เขาก็ไม่ตื่นขึ้น และปลุกเขาก็ไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 13, 'โอ หากพระองค์ทรงซ่อนข้าพระองค์ไว้ในแดนคนตายก็จะดี ใคร่จะให้พระองค์ทรงปกปิดข้าพระองค์ไว้จนพระพิโรธพระองค์พ้นไป ใคร่จะให้พระองค์ทรงกําหนดเวลาให้ข้าพระองค์ และทรงระลึกถึงข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 14, 'ถ้ามนุษย์ตายแล้ว เขาจะมีชีวิตอีกหรือ ข้าพระองค์จะคอยอยู่ตลอดวันประจําการของข้าพระองค์ จนกว่าการปลดปล่อยของข้าพระองค์จะมาถึง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 15, 'พระองค์จะทรงเรียก และข้าพระองค์จะทูลตอบพระองค์ พระองค์จะทรงอาลัยอาวรณ์พระหัตถกิจของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 16, 'แต่พระองค์ทรงนับก้าวของข้าพระองค์ พระองค์มิได้ทรงจ้องจับผิดข้าพระองค์หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 17, 'การละเมิดของข้าพระองค์นั้นทรงใส่ไว้ในถุงที่ผนึกตรา และพระองค์ทรงมัดความชั่วช้าของข้าพระองค์ไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 18, 'แต่ภูเขาก็ทลายลงและผุพังไป และก้อนหินก็ถูกย้ายไปจากที่ของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 19, 'น้ําเซาะหินไปเสีย พระองค์ทรงพัดพาสิ่งต่างๆที่งอกขึ้นจากผงคลีดินแห่งแผ่นดินโลกไป พระองค์ทรงทําลายความหวังของมนุษย์เช่นกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 20, 'พระองค์ทรงชนะเขาเสมอ และเขาก็ล่วงลับไป พระองค์ทรงเปลี่ยนสีหน้าของเขาและทรงส่งเขาไปเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 21, 'บรรดาบุตรชายของเขาได้รับเกียรติและเขาก็ไม่ทราบ เขาทั้งหลายตกต่ําลง แต่เขาหาหยั่งรู้ไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 22, 'เขารู้สึกเพียงความเจ็บในร่างกายของตน และจิตใจเขาคร่ําครวญ’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 1, 'แล้วเอลีฟัสชาวเทมานตอบว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 2, '“ควรที่คนมีปัญญาจะตอบด้วยความรู้ลมๆแล้งๆหรือ และบรรจุลมตะวันออกให้เต็มท้อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 3, 'ควรที่เขาจะโต้แย้งกันในการพูดอันไร้ประโยชน์ หรือด้วยถ้อยคําซึ่งไม่ได้ผลหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 4, 'แต่ท่านกําลังขจัดความยําเกรงเสีย และขัดขวางการอธิษฐานต่อพระพักตร์พระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 5, 'เพราะปากของท่านกล่าวความชั่วช้าของท่าน และท่านเลือกเอาลิ้นของคนฉลาดแกมโกง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 6, 'ปากของท่านกล่าวโทษท่านเอง ไม่ใช่ข้าพเจ้า และริมฝีปากของท่านปรักปรําท่านเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 7, 'ท่านเป็นมนุษย์คนแรกที่เกิดมาหรือ หรือท่านคลอดมาก่อนเนินเขาหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 8, 'ท่านได้ฟังความลึกลับของพระเจ้าหรือ และท่านจํากัดสติปัญญาไว้เฉพาะตัวท่านหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 9, 'ท่านทราบอะไรที่พวกเราไม่ทราบบ้าง ท่านเข้าใจอะไรที่ไม่กระจ่างแก่เราเล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 10, 'ในพวกเรามีคนผมหงอกและคนสูงอายุ แก่ยิ่งกว่าบิดาของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 11, 'ท่านเห็นคําเล้าโลมของพระเจ้าเป็นของเล็กน้อยไปหรือ มีเรื่องลึกลับอะไรบ้างอยู่กับท่านหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 12, 'เหตุไฉนท่านจึงปล่อยตัวไปตามใจ ท่านกระพริบตาเพราะเหตุอะไรเล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 13, 'คือที่ท่านหันจิตใจของท่านต่อสู้พระเจ้า และให้ถ้อยคําอย่างนี้ออกจากปากของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 14, 'มนุษย์เป็นอะไรเล่า เขาจึงจะสะอาดได้ หรือเขาผู้เกิดมาโดยผู้หญิงเป็นอะไร เขาจึงชอบธรรมได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 15, 'ดูเถิด พระเจ้ามิได้ทรงวางใจในวิสุทธิชนของพระองค์ ใช่แล้ว ในสายพระเนตรพระองค์ ฟ้าสวรรค์ก็ไม่สะอาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 16, 'แล้วมนุษย์ผู้ดื่มความชั่วช้าเหมือนดื่มน้ํา ก็น่าสะอิดสะเอียนและโสโครกยิ่งกว่านั้นสักเท่าใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 17, 'ฟังข้าซิ ข้าจะแสดงแก่ท่าน สิ่งใดที่ข้าได้เห็น ข้าจะกล่าว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 18, 'สิ่งที่คนมีปัญญาได้บอกกันมาตั้งแต่บรรพบุรุษของเขา และมิได้ปิดบังไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 19, 'ผู้ที่ได้รับพระราชทานแผ่นดินแต่พวกเดียว และไม่มีคนต่างด้าวผ่านไปท่ามกลางเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 20, 'คนชั่วทนทุกข์ทรมานตลอดอายุของเขา ตลอดปีทั้งปวงได้ซ่อนไว้จากผู้บีบบังคับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 21, 'เสียงที่น่าคร้ามกลัวอยู่ในหูของเขา ผู้ทําลายจะมาเหนือเขาในยามมั่งคั่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 22, 'เขาไม่เชื่อว่าเขาจะกลับออกมาจากความมืด เขาจะต้องตายด้วยดาบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 23, 'เขาพเนจรไปเพื่อหาอาหาร กล่าวว่า ‘อยู่ที่ไหนนะ’ เขาทราบอยู่ว่าวันแห่งความมืดอยู่แค่เอื้อมมือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 24, 'ความทุกข์ใจและความแสนระทมจะทําให้เขาคร้ามกลัว มันจะชนะเขา เหมือนอย่างกษัตริย์เตรียมพร้อมแล้วสําหรับการศึก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 25, 'เพราะเขาได้เหยียดมือของเขาออกสู้พระเจ้า และเพิ่มกําลังเพื่อต่อสู้องค์ผู้ทรงมหิทธิฤทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 26, 'เขาวิ่งเข้าใส่พระองค์อย่างดื้อดึงพร้อมกับดั้งปุ่มหนา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 27, 'เพราะว่าเขาได้คลุมหน้าของเขาด้วยความอ้วนของเขาแล้ว และรวบรวมไขมันมาไว้ที่บั้นเอวของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 28, 'และได้อาศัยอยู่ในหัวเมืองที่รกร้าง ในเรือนซึ่งไม่มีผู้อาศัย ซึ่งพร้อมที่จะกลายเป็นกองซากปรักหักพัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 29, 'เขาจะไม่มั่งมี และทรัพย์สมบัติของเขาจะไม่ทนทาน และข้าวของของเขาจะไม่เพิ่มพูนในแผ่นดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 30, 'เขาจะหนีจากความมืดไม่พ้น เปลวเพลิงจะทําให้หน่อของเขาแห้งไป และโดยลมพระโอษฐ์เขาจะต้องจากไปเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 31, 'อย่าให้เขาวางใจในความอนิจจังลวงตัวเขาเอง เพราะความอนิจจังจะเป็นสิ่งตอบแทนเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 32, 'จะชําระให้เขาเต็มก่อนเวลาของเขา และกิ่งก้านของเขาจะไม่เขียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 33, 'เขาจะเป็นประดุจเถาองุ่นที่เขย่าลูกองุ่นดิบของมัน และเป็นดังต้นมะกอกเทศที่สลัดทิ้งดอกบานของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 34, 'เพราะว่าที่ชุมนุมของพวกหน้าซื่อใจคดนั้นจะรกร้างไป และไฟจะเผาผลาญเต็นท์แห่งสินบนเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 35, 'เขาทั้งหลายตั้งครรภ์ความชั่ว และคลอดความร้ายออกมา และท้องของเขาทั้งหลายตระเตรียมการล่อลวง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 1, 'แล้วโยบตอบว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 2, '“ข้าเคยได้ยินเรื่องอย่างนี้มามากแล้ว ท่านทุกคนเป็นผู้เล้าโลมที่กวนใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 3, 'คําลมๆแล้งๆจะจบสิ้นเมื่อไรหนอ ท่านเป็นอะไรไป ท่านจึงตอบอย่างนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 4, 'ข้าก็พูดอย่างท่านทั้งหลายได้เหมือนกัน ถ้าชีวิตท่านมาแทนที่ชีวิตของข้า ข้าก็สามารถสรรหาถ้อยคํามากมายก่ายกองมาต่อสู้ท่านทั้งหลายได้ และสั่นศีรษะของข้าใส่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 5, 'ข้าจะหนุนกําลังของท่านทั้งหลายด้วยปากของข้าก็ได้ และการเคลื่อนไหวแห่งริมฝีปากของข้าจะระงับความเจ็บปวดของท่านก็ได้ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 6, 'ถ้าข้าพูด ความเจ็บปวดของข้าก็ไม่ระงับ และถ้าข้านิ่งไว้ จะบรรเทาไปสักเท่าใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 7, 'แต่นี่แหละ เดี๋ยวนี้พระเจ้าทรงให้ข้าอ่อนเปลี้ย พระองค์ทรงกระทําให้พรรคพวกทั้งสิ้นของข้าเลิกร้างไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 8, 'และพระองค์ได้ให้ข้าเต็มไปด้วยรอยย่นซึ่งสภาพนี้เป็นพยานปรักปรําข้า และความผ่ายผอมของข้าลุกขึ้นปรักปรําข้า มันเป็นพยานใส่หน้าข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 9, 'พระองค์ทรงฉีกข้าด้วยพระพิโรธของพระองค์และทรงเกลียดชังข้า พระองค์ทรงขบเขี้ยวเคี้ยวฟันใส่ข้า ปรปักษ์ของข้าถลึงตาสู้ข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 10, 'มีคนอ้าปากใส่ข้า เขาตบแก้มประจานข้า เขาสุมหัวกันปรักปรําข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 11, 'พระเจ้าทรงมอบข้าให้แก่คนอธรรม และทรงเหวี่ยงข้าไว้ในมือของคนชั่วร้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 12, 'ข้าอยู่สบาย และพระองค์ทรงหักข้าสะบั้น เออ พระองค์ทรงฉวยคอข้า และฟาดข้าลงเป็นชิ้นๆ พระองค์ทรงตั้งข้าให้เป็นเป้าของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 13, 'นักธนูของพระองค์ล้อมข้า พระองค์ทรงทะลวงเปิดไตของข้าและไม่เพลามือเลย พระองค์ทรงเทน้ําดีของข้าลงบนดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 14, 'พระองค์ทรงพังเข้าไปเป็นช่องๆ พระองค์ทรงวิ่งเข้าใส่ข้าอย่างมนุษย์ยักษ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 15, 'ข้าเย็บผ้ากระสอบติดหนังของข้า และทําให้เขาสัตว์ของข้าสกปรกด้วยผงคลีดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 16, 'หน้าของข้าแดงด้วยการร่ําไห้ เงามัจจุราชอยู่ที่หนังตาของข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 17, 'แม้ว่าในมือของข้าไม่มีความอยุติธรรมเลย และคําอธิษฐานของข้าก็บริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 18, 'โอ แผ่นดินโลกเอ๋ย อย่าปิดบังโลหิตของข้านะ อย่าให้เสียงร้องของข้ามีที่หยุดพัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 19, 'ดูเถิด เดี๋ยวนี้เองพยานของข้าก็อยู่บนสวรรค์ และพระองค์ผู้รับรองข้าก็อยู่ในที่สูง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 20, 'เพื่อนของข้าดูหมิ่นข้า แต่ตาของข้าเทน้ําตาออกถวายพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 21, 'โอ ขอให้ผู้หนึ่งผู้ใดอ้อนวอนเพื่อมนุษย์ต่อพระเจ้า อย่างที่มนุษย์อ้อนวอนเพื่อเพื่อนบ้านของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 22, 'เพราะว่าต่อไปอีกไม่กี่ปี ข้าจะไปตามทางที่ข้าจะไม่กลับ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 1, '“ลมหายใจของข้าได้แตกดับ วันเวลาของข้าก็จบลง หลุมฝังศพพร้อมสําหรับข้าแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 2, 'แน่ละ คนมักเยาะเย้ยก็อยู่รอบข้านี่เอง และตาของข้าก็จ้องอยู่ที่การยั่วเย้าของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 3, '‘โปรดทรงวางประกันไว้สําหรับข้าพระองค์กับพระองค์ ใครอยู่ที่นั่นที่จะให้ประกันสําหรับข้าพระองค์ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 4, 'เพราะพระองค์ทรงปิดใจของเขาทั้งหลายไว้จากความเข้าใจ ฉะนั้นพระองค์จะไม่ทรงยกย่องเขา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 5, 'ผู้ที่กล่าวคําประจบประแจงแก่เพื่อนของเขา นัยน์ตาของลูกหลานของเขาจะมัวมืดไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 6, 'พระองค์ทรงกระทําให้ข้าเป็นที่ครหาของชนชาติทั้งหลาย แต่ก่อนนั้นข้าเป็นเหมือนรํามะนา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 7, 'นัยน์ตาของข้าได้มืดมัวไปด้วยความโศกสลด และอวัยวะทั้งสิ้นของข้าก็เหมือนกับเงา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 8, 'คนเที่ยงธรรมก็จะตกตะลึงด้วยเรื่องนี้ และคนไร้ผิดก็จะเร้าตัวขึ้นปรักปรําคนหน้าซื่อใจคด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 9, 'คนชอบธรรมยังจะยึดมั่นอยู่กับทางของเขา และผู้ที่มีมือสะอาดก็จะแข็งแรงยิ่งๆขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 10, 'แต่พวกท่าน ท่านทุกคนมาอีกซี ข้าจะไม่พบคนที่มีปัญญาสักคนในพวกท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 11, 'วันของข้าก็ผ่านพ้นไป แผนงานของข้าก็แตกหัก คือความคิดในใจของข้านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 12, 'เขาเหล่านั้นทํากลางคืนให้เป็นกลางวัน ความสว่างนั้นก็สั้นเพราะเหตุความมืด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 13, 'ถ้าข้ารอคอย แดนคนตายจะเป็นบ้านของข้า ข้าได้กางที่นอนออกในความมืด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 14, 'ข้าได้พูดกับความเปื่อยเน่าว่า ‘เจ้าเป็นพ่อของข้า’ และพูดกับหนอนว่า ‘เจ้าเป็นแม่ของข้าและเป็นพี่สาวของข้า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 15, 'แล้วบัดนี้ความหวังของข้าอยู่ที่ไหนเล่า ส่วนความหวังของข้านั้นใครจะเห็นได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 16, 'ความหวังนั้นจะลงไปที่ดาลประตูแดนคนตาย เราจะลงไปด้วยกันในผงคลีดิน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 1, 'แล้วบิลดัดคนชูอาห์ตอบว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 2, '“ท่านจะค้นหาถ้อยคํานานเท่าใด จงใคร่ครวญแล้วภายหลังพวกเราจะพูด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 3, 'ทําไมเราจึงถูกนับให้เป็นสัตว์ และถือว่าเลวทรามในสายตาของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 4, 'ท่านผู้ฉีกตัวของท่านด้วยความโกรธของท่าน จะให้แผ่นดินโลกถูกทอดทิ้งเพราะเห็นแก่ท่านหรือ หรือจะให้ก้อนหินโยกย้ายจากที่ของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 5, 'เออ ความสว่างแห่งคนชั่วจะถูกดับเสีย และเปลวไฟของเขาจะไม่ส่องแสงอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 6, 'ความสว่างในเต็นท์ของเขาจะมืด และตะเกียงของเขาจะดับพร้อมกับเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 7, 'ก้าวอันแข็งแรงของเขาก็จะสั้นเข้า และความคิดอ่านของเขาเองก็จะคว่ําเขาลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 8, 'เพราะเขาถูกเหวี่ยงเข้าไปในข่ายด้วยเท้าของเขาเอง และเขาเดินอยู่บนหลุมพราง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 9, 'กับอันหนึ่งจะฉวยส้นเท้าของเขาไว้ ผู้ปล้นจะมีชัยต่อเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 10, 'มีบ่วงซ่อนอยู่ในดินไว้ดักเขา มีกับอยู่ในทางไว้ดักเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 11, 'สิ่งน่าหวาดเสียวจะทําให้เขาตกใจอยู่รอบด้าน และไล่ติดส้นเท้าของเขาอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 12, 'กําลังของเขาก็จะกร่อนไปเพราะความหิว และภัยพิบัติก็จะคอยพร้อมอยู่ที่ข้างเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 13, 'มันจะกินความแข็งแกร่งแห่งผิวหนังของเขาเสีย แม้แต่บุตรหัวปีแห่งความตายจะกินความแข็งแกร่งของเขาเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 14, 'ความไว้วางใจของเขาจะถูกถอนออกจากเต็นท์ของเขา จะถูกนํามายังกษัตริย์แห่งความน่าหวาดเสียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 15, 'สิ่งที่ไม่ใช่ของเขาจะอาศัยอยู่ในเต็นท์ของเขา จะมีกํามะถันเกลื่อนกลาดอยู่เหนือที่อยู่ของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 16, 'รากของเขาจะแห้งไปข้างใต้นั้น และกิ่งของเขาที่อยู่ข้างบนจะถูกตัดทิ้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 17, 'การระลึกถึงเขาจะพินาศไปจากโลก และเขาจะไม่มีชื่ออยู่ในถนน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 18, 'เขาจะถูกผลักไสจากความสว่างเข้าสู่ความมืด และจะถูกไล่ออกไปจากแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 19, 'เขาจะไม่มีลูกหรือหลานท่ามกลางประชาชนของเขา และจะไม่มีใครเหลืออยู่ในที่ซึ่งเขาเคยอาศัยอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 20, 'ผู้ที่มาภายหลังเขาก็จะตกตะลึงด้วยวันของเขา เหมือนกับผู้ที่มาก่อนก็หวาดกลัวด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 21, 'แน่ละ ที่อยู่ของคนชั่วเป็นอย่างนี้แหละ และที่อยู่ของคนซึ่งไม่รู้จักพระเจ้าก็เป็นอย่างนี้แหละ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 1, 'แล้วโยบตอบว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 2, '“ท่านทั้งหลายจะทรมานจิตใจช้านานสักเท่าใด ทั้งทุบข้าเป็นชิ้นๆด้วยถ้อยคํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 3, 'ท่านทั้งหลายพูดสบประมาทข้าสิบหนแล้ว และที่ทําตัวเป็นคนแปลกหน้าต่อข้านั้นท่านก็ไม่อายเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 4, 'ถ้าแม้ว่าข้าหลงทําผิดจริง ความผิดของข้าก็อยู่กับข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 5, 'ถ้าท่านทั้งหลายจะผยองเพราะข้าจริง และใช้ความต่ําต้อยของข้าปรักปรําข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 6, 'จงทราบเถิดว่าพระเจ้าทรงคว่ําข้าลงแล้ว และได้ทรงเอาตาข่ายของพระองค์ล้อมข้าไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 7, 'ดูเถิด ข้าร้องออกมาเพราะเหตุความทารุณ แต่ไม่มีใครฟัง ข้าร้องให้ช่วย แต่ไม่มีความยุติธรรมที่ไหน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 8, 'พระองค์ทรงก่อกําแพงกั้นทางข้าไว้ ข้าจึงข้ามไปไม่ได้ และพระองค์ทรงให้ทางของข้ามืดไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 9, 'พระองค์ทรงปลดสง่าราศีของข้าไปจากข้าเสีย และทรงถอดมงกุฎจากศีรษะของข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 10, 'พระองค์ทรงพังข้าลงเสียทุกด้านและข้าก็สิ้นไป พระองค์ทรงทึ้งความหวังของข้าขึ้นเหมือนถอนต้นไม้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 11, 'พระพิโรธของพระองค์พลุ่งขึ้นใส่ข้า และทรงนับข้าว่าเป็นปรปักษ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 12, 'กองทหารของพระองค์เข้ามาพร้อมกัน เขาทั้งหลายก่อเชิงเทินต่อสู้ข้า และตั้งค่ายล้อมเต็นท์ของข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 13, 'พระองค์ทรงให้พี่น้องของข้าห่างไกลจากข้า ผู้ที่คุ้นเคยของข้าก็หันไปจากข้าเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 14, 'ญาติของข้าละข้าเสีย และเพื่อนสนิทของข้าได้ลืมข้าเสียแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 15, 'คนทั้งหลายที่อาศัยอยู่ในบ้านของข้าและสาวใช้ของข้า นับข้าเป็นคนต่างด้าว ข้ากลายเป็นคนต่างด้าวในสายตาของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 16, 'ข้าเรียกคนใช้ของข้า แต่เขาไม่ตอบข้า ข้าต้องวิงวอนเขาด้วยปากของข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 17, 'ลมหายใจข้าเป็นที่ขยะแขยงแก่ภรรยาของข้า ถึงแม้ข้าได้อ้อนวอนเพื่อลูกๆที่บังเกิดแก่ข้าเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 18, 'แม้เด็กๆดูหมิ่นข้า เมื่อข้าลุกขึ้นเขาก็ว่าข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 19, 'สหายสนิททั้งสิ้นของข้ารังเกียจข้า และคนเหล่านั้นที่ข้ารัก เขาหันหลังให้ข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 20, 'กระดูกของข้าเกาะติดหนังและติดเนื้อของข้า และข้ารอดได้อย่างหวุดหวิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 21, 'โอ ท่าน สหายของข้า สงสารข้าเถิด สงสารข้าเถิด เพราะพระหัตถ์ของพระเจ้าได้แตะต้องข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 22, 'ทําไมท่านทั้งหลายจึงข่มเหงข้าอย่างกับเป็นพระเจ้า ทําไมท่านไม่พอใจกับเนื้อของข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 23, 'โอ ข้าอยากให้ถ้อยคําของข้าได้ถูกบันทึกไว้ โอ ข้าอยากให้จารึกไว้ในหนังสือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 24, 'ข้าอยากให้สลักไว้ในศิลาเป็นนิตย์ ด้วยปากกาเหล็กและตะกั่ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 25, 'แต่ส่วนข้า ข้าทราบว่า พระผู้ไถ่ของข้าทรงพระชนม์อยู่ และในที่สุดพระองค์จะทรงประทับยืนบนแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 26, 'และหลังจากตัวหนอนแห่งผิวหนังทําลายร่างกายนี้แล้ว ในเนื้อหนังของข้า ข้าจะเห็นพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 27, 'ผู้ซึ่งข้าจะได้เห็นเอง และนัยน์ตาของข้าจะได้เห็น ไม่ใช่คนอื่น แม้ว่าจิตใจในตัวข้าก็ถูกเผาผลาญ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 28, 'แต่ท่านทั้งหลายควรว่า ‘ทําไมพวกเราข่มเหงท่าน เมื่อรากของเรื่องนั้นพบอยู่ในตัวเรา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 29, 'จงกลัวดาบ เพราะพระพิโรธนําโทษของดาบมา เพื่อท่านจะทราบว่ามีการพิพากษา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 1, 'แล้วโศฟาร์ชาวนาอามาห์ตอบว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 2, '“เพราะฉะนั้นเพราะเหตุความคิดของข้าๆจึงต้องตอบด้วยความเร่งร้อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 3, 'ข้าได้ฟังคําติเตียนที่สบประมาทแล้ว เพราะเหตุจิตใจข้ารู้เรื่องข้าจึงต้องตอบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 4, 'ตั้งแต่ดึกดําบรรพ์มา ตั้งแต่มนุษย์ถูกวางไว้บนแผ่นดินโลก ท่านไม่ทราบหรือว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 5, 'เสียงไชโยของคนชั่วนั้นสั้น และความชื่นบานของคนหน้าซื่อใจคดนั้นเป็นแต่ครู่เดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 6, 'แม้ความสูงของเขาเด่นขึ้นไปถึงฟ้าสวรรค์ และศีรษะของเขาไปถึงหมู่เมฆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 7, 'เขาจะพินาศเป็นนิตย์อย่างอุจจาระของเขาเอง บรรดาคนที่เคยเห็นเขาจะพูดว่า ‘เขาอยู่ที่ไหน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 8, 'เขาจะบินไปเสียเหมือนความฝัน และจะไม่มีใครพบอีก เขาจะถูกไล่ไปเสียอย่างนิมิตในกลางคืน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 9, 'นัยน์ตาซึ่งได้เห็นเขาจะไม่เห็นเขาอีก หรือที่ของเขาจะไม่เห็นเขาอีกเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 10, 'ลูกหลานของเขาจะเสาะหาเป็นที่โปรดปรานของคนยากจน และมือของเขาจะคืนทรัพย์สมบัติของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 11, 'กระดูกของเขาเต็มไปด้วยความบาปของคนหนุ่มซึ่งจะนอนลงกับเขาในผงคลีดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 12, 'แม้ว่าความชั่วจะหวานอยู่ในปากของเขา แม้เขาซ่อนไว้ใต้ลิ้นของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 13, 'แม้เขาไม่อยากจะปล่อยและไม่ละทิ้ง แต่อมไว้ในปากของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 14, 'อาหารของเขายังเปลี่ยนในท้องของเขา เหมือนพิษของงูเห่าในตัวเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 15, 'เขากลืนทรัพย์สมบัติลงไป แต่จะอาเจียนมันออกมาอีก พระเจ้าจะเหวี่ยงมันออกมาจากท้องของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 16, 'เขาจะดูดพิษของงูเห่า ลิ้นของงูร้ายจะฆ่าเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 17, 'เขาจะไม่ได้เห็นแม่น้ําลําธาร หรือน้ําเอ่อล้น คือลําธารที่มีน้ําผึ้งและเนยข้นไหลอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 18, 'เขาจะคืนผลงานของเขา และจะไม่กลืนกินเสีย เขาได้กําไรเท่าไหร่ เขาจะต้องคืนให้เท่านั้น และเขาจะไม่ได้ความชื่นบานในสิ่งนั้นเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 19, 'เพราะเขาได้ขยี้และทอดทิ้งคนยากจน เขาได้ชิงบ้านซึ่งเขาไม่ได้สร้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 20, 'แน่นอนเขาจะไม่รู้สึกสงบใจ เขาจะเก็บสิ่งที่เขาปรารถนาไม่ได้เลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 21, 'อาหารของเขาจะไม่มีอะไรเหลือ เหตุฉะนั้นไม่มีใครเสาะหาทรัพย์สมบัติของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 22, 'ในขณะที่เขาอิ่มหนําสําราญ เขาจะตกในสภาพขัดสน มือของคนชั่วทั้งปวงจะมายังเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 23, 'เมื่อกําลังจะเติมท้องของเขาให้เต็ม พระเจ้าจะทรงส่งความพิโรธอันดุเดือดมาถึงเขา และหลั่งลงมาบนเขาเมื่อเขารับประทานอาหารอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 24, 'เขาจะลี้จากอาวุธเหล็ก คันธนูเหล็กกล้าจะแทงเขาทะลุ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 25, 'เขาดึงมันออก และมันออกมาจากร่างกายของเขา เออ กระบี่อันวาววับออกมาจากน้ําดีของเขา ความน่าหวาดเสียวมายังเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 26, 'ความมืดทั้งปวงจะซ่อนไว้ในที่ลึกลับของเขา ไฟที่ไม่ต้องเป่าจะกลืนเขาเสีย สิ่งใดที่เหลืออยู่ในเต็นท์ของเขาจะถูกเผาผลาญ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 27, 'ฟ้าสวรรค์จะสําแดงความชั่วช้าของเขา และแผ่นดินโลกจะลุกขึ้นปรักปรําเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 28, 'ผลกําไรแห่งครัวเรือนของเขาจะถูกนําไปเสีย ทรัพย์สมบัติของเขาจะถูกกวาดไปในวันแห่งพระพิโรธของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 29, 'นี่เป็นส่วนของคนชั่วจากพระเจ้า และเป็นมรดกที่พระเจ้าทรงกําหนดให้เขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 1, 'แล้วโยบตอบว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 2, '“ขอฟังถ้อยคําของข้าอย่างระมัดระวัง และให้คํานี้ปลอบใจท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 3, 'ขออดทนหน่อยและข้าจะพูด และเมื่อข้าพูดแล้ว ก็เยาะต่อไปเถอะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 4, 'ส่วนข้านี้ จะต่อว่ามนุษย์หรือ ถ้าเป็นเช่นนั้นทําไมใจข้าจึงไม่ควรเป็นทุกข์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 5, 'มองดูข้าซี และจงตกตะลึงเถิด และท่านจงเอามือปิดปากของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 6, 'เมื่อข้าระลึกถึงเรื่องนี้ข้าก็ตระหนกตกใจ และความสั่นสะท้านก็จับเนื้อของข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 7, 'ทําไมคนชั่วจึงมีชีวิตอยู่ เออ จนถึงแก่ และเจริญมีกําลังมากขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 8, 'เชื้อสายของเขาก็ตั้งมั่นคงอยู่ในสายตาของเขา และลูกหลานของเขาก็อยู่ต่อหน้าต่อตาเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 9, 'เรือนของเขาทั้งหลายก็ปลอดภัยปราศจากความกลัว และไม้เรียวของพระเจ้าก็ไม่อยู่บนเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 10, 'วัวผู้ของเขาเกิดพันธุ์ ไม่มีขาด วัวเมียของเขาตกลูก และไม่มีแท้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 11, 'เขาส่งเด็กๆออกไปอยู่อย่างฝูงแพะแกะ และลูกหลานเล็กของเขาก็เต้นรํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 12, 'เขาหยิบเอารํามะนาและพิณเขาคู่ และเปรมปรีดิ์ตามเสียงขลุ่ย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 13, 'ตลอดวันเวลาของเขา เขาก็เจริญ และเขาลงไปที่แดนคนตายในพริบตาเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 14, 'เขาจึงทูลพระเจ้าว่า ‘ขอจากเราไปเสีย เพราะเราไม่ปรารถนาความรู้ในทางของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 15, 'องค์ผู้ทรงมหิทธิฤทธิ์คืออะไร ที่เราจะต้องปรนนิบัติเขา ถ้าเราอธิษฐานต่อเขา เราจะได้ประโยชน์อะไร’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 16, 'ดูเถิด ความจําเริญของเขาทั้งหลายไม่อยู่ในกํามือของเขา คําปรึกษาของคนชั่วอยู่ห่างไกลจากข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 17, 'ตะเกียงของคนชั่วดับบ่อยเท่าใด ความยากลําบากมาเหนือเขาบ่อยเท่าใด พระเจ้าทรงแจกจ่ายความเศร้าโศกด้วยพระพิโรธของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 18, 'เขาเป็นเหมือนฟางข้าวหน้าลม และเป็นเหมือนแกลบที่พายุพัดไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 19, 'พระเจ้าทรงสะสมความชั่วช้าของเขาไว้ให้ลูกหลานของเขาหรือ พระองค์ทรงตอบแทนแก่เขาเอง และเขาก็จะทราบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 20, 'นัยน์ตาของเขาจะเห็นความพินาศของเขา และเขาจะดื่มพระพิโรธขององค์ผู้ทรงมหิทธิฤทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 21, 'เพราะเขามีความพึงพอใจอะไรในเรื่องวงศ์วานที่ตามเขามา เมื่อจํานวนเดือนของเขาถูกตัดขาดกลางคันเสียแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 22, 'มีผู้ใดจะสอนความรู้ให้แด่พระเจ้าได้หรือ เมื่อพระองค์ทรงพิพากษาผู้สูงศักดิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 23, 'คนหนึ่งตายเมื่อยังแข็งแรงเต็มที่สบายและปลอดภัยทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 24, 'ถังกายของเขาเต็มด้วยน้ํานม และกระดูกของเขาก็ชุ่มด้วยไขกระดูก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 25, 'อีกคนหนึ่งตายด้วยใจขมขื่น ไม่เคยได้ชิมของดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 26, 'เขาทั้งสองนอนลงในผงคลีดินเหมือนกัน และตัวหนอนก็คลุมเขาทั้งสองไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 27, 'ดูเถิด ข้ารู้ความคิดของท่านและอุบายของท่านที่จะทําผิดต่อข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 28, 'เพราะท่านว่า ‘วังของเจ้านายอยู่ที่ไหน เต็นท์ซึ่งคนชั่วอาศัยนั้นอยู่ที่ไหน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 29, 'ท่านมิได้ถามนักท่องเที่ยว และท่านไม่ได้รับสักขีพยานของเขาหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 30, 'ว่าคนชั่วได้สงวนไว้จนถึงวันแห่งภัยพิบัติ และเขาจะถูกนําไปยังวันแห่งพระพิโรธ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 31, 'ใครแจ้งวิธีการของเขาต่อหน้าเขา และผู้ใดสนองเขาในสิ่งที่เขาได้กระทํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 32, 'แม้กระนั้นเขาจะถูกหามไปยังหลุมศพ และจะยังอยู่ในอุโมงค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 33, 'สําหรับเขาก้อนดินที่หุบเขาก็เบาสบาย คนทั้งปวงก็ตามเขาไป และคนที่ไปข้างหน้าก็นับไม่ถ้วน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 34, 'แล้วทําไมท่านจะมาเล้าโลมใจข้าด้วยสิ่งว่างเปล่า คําตอบของท่านไม่มีอะไรเหลือแล้วนอกจากการมุสา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 1, 'แล้วเอลีฟัสชาวเทมานตอบว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 2, '“คนจะเป็นประโยชน์อะไรแก่พระเจ้าได้หรือ แน่ละ ผู้ใดฉลาดก็เป็นประโยชน์แก่ตนเองต่างหาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 3, 'ถ้าท่านเป็นคนชอบธรรม จะเป็นที่พอพระทัยแก่องค์ผู้ทรงมหิทธิฤทธิ์หรือ หรือถ้าทางทั้งหลายของท่านดีรอบคอบจะเป็นประโยชน์อะไรแก่พระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 4, 'พระองค์จะทรงติเตียนท่านเพราะยําเกรงหรือ พระองค์จะทรงสู้ความกับท่านหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 5, 'ความชั่วของท่านใหญ่โตมิใช่หรือ ความชั่วช้าของท่านไม่มีที่สิ้นสุดมิใช่หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 6, 'เพราะท่านยึดของประกันไปจากพี่น้องเปล่าๆ และริบเสื้อผ้าของคนที่เปลือยกาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 7, 'ท่านมิได้ให้น้ําแก่คนอิดโรยดื่ม และท่านหน่วงเหนี่ยวขนมปังไว้มิให้คนที่หิว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 8, 'คนที่มีอํานาจใหญ่โตย่อมได้ที่ดินเป็นกรรมสิทธิ์ และคนที่มีหน้ามีตาก็ได้เข้าอาศัยอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 9, 'ท่านไล่หญิงม่ายออกไปมือเปล่า และแขนของลูกกําพร้าพ่อก็หัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 10, 'เพราะฉะนั้นกับดักอยู่รอบท่าน และความสยดสยองอันฉับพลันก็ท่วมทับท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 11, 'หรือความมืดจนท่านไม่เห็นอะไร และน้ําที่ท่วมก็คลุมท่านไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 12, 'พระเจ้ามิได้ทรงสถิตอยู่ ณ ที่สูงในฟ้าสวรรค์หรือ ดูดาวที่สูงที่สุดเถิด มันสูงจริงๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 13, 'เพราะฉะนั้นท่านว่า ‘พระเจ้าทรงรู้อะไร พระองค์จะทรงทะลุเมฆมืดทึบไปพิพากษาได้หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 14, 'เมฆทึบคลุมพระองค์ไว้ พระองค์ทรงมองอะไรไม่เห็น และพระองค์ทรงดําเนินโดยรอบบนพื้นฟ้า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 15, 'ท่านมุ่งไปทางเก่าหรือ ซึ่งคนชั่วเคยดําเนินนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 16, 'ผู้ถูกฉวยเอาไปก่อนเวลากําหนดของเขา รากฐานของเขาถูกไหลล้นไปด้วยน้ําท่วม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 17, 'ผู้ทูลพระเจ้าว่า ‘ขอทรงไปจากข้าทั้งหลาย’ และ ‘องค์ผู้ทรงมหิทธิฤทธิ์จะทรงช่วยเขาทั้งหลายได้’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 18, 'แต่พระองค์ทรงให้เรือนของเขาเต็มด้วยของดี แต่คําปรึกษาของคนชั่วห่างไกลจากข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 19, 'คนชอบธรรมเห็นและยินดี คนไร้ผิดหัวเราะเยาะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 20, 'ในขณะที่ทรัพย์สมบัติของเราไม่ถูกตัดขาด แต่ของที่เหลือนั้นไฟก็เผาเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 21, 'จงปรองดองกับพระเจ้าและอยู่อย่างสันติ ดังนั้นสิ่งที่ดีจะมาถึงท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 22, 'ขอจงรับพระราชบัญญัติจากพระโอษฐ์ของพระองค์ และเก็บพระวจนะของพระองค์ไว้ในใจของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 23, 'ถ้าท่านกลับมายังองค์ผู้ทรงมหิทธิฤทธิ์ ท่านจะเจริญและจะทิ้งความชั่วช้าให้ไกลจากเต็นท์ของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 24, 'ท่านจะรวบรวมทองคําไว้เหมือนผงคลีดิน และทองคําเมืองโอฟีร์ไว้เหมือนหินในลําธาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 25, 'และองค์ผู้ทรงมหิทธิฤทธิ์จะเป็นผู้ป้องกันท่าน และท่านจะมีเงินอย่างมากมาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 26, 'แล้วท่านจะปีติยินดีในองค์ผู้ทรงมหิทธิฤทธิ์ และเงยหน้าของท่านหาพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 27, 'ท่านจะอธิษฐานต่อพระองค์ และพระองค์จะทรงฟังท่าน และท่านจะทําตามคําปฏิญาณของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 28, 'ท่านจะตัดสินใจในเรื่องใด และเรื่องนั้นจะสําเร็จสมประสงค์ และจะมีแสงสว่างส่องทางให้ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 29, 'เมื่อมนุษย์ถูกทิ้งลงไป ท่านจะว่า ‘มีการทรงช่วยยกชูขึ้น และพระองค์ทรงช่วยคนถ่อมใจให้รอด’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 30, 'พระองค์ทรงช่วยเกาะแห่งผู้ไร้ความผิดให้พ้น มันได้รับการช่วยให้พ้นโดยความสะอาดแห่งมือของท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 1, 'แล้วโยบตอบว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 2, '“คําร้องทุกข์ของข้าก็ขมขื่นในวันนี้ด้วย การที่ข้าถูกทุบตีก็หนักกว่าการร้องครางของข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 3, 'โอ ข้าอยากทราบว่าจะพบพระองค์ได้ที่ไหน เพื่อข้าจะมาถึงพระที่นั่งของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 4, 'ข้าจะยื่นคดีของข้าต่อพระพักตร์พระองค์ และบรรจุข้อโต้แย้งให้เต็มปากข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 5, 'ข้าจะทราบคําตอบของพระองค์ และเข้าใจสิ่งที่พระองค์จะตรัสกับข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 6, 'พระองค์จะทรงโต้แย้งกับข้าด้วยฤทธานุภาพอันยิ่งใหญ่ของพระองค์หรือ เปล่าน่ะ พระองค์จะทรงให้กําลังแก่ข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 7, 'ณ ที่นั่นคนเที่ยงธรรมจะสู้ความกับพระองค์ได้ และข้าจะรับการช่วยให้พ้นจากผู้พิพากษาของข้าเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 8, 'ดูเถิด ข้าเดินไปข้างหน้า แต่พระองค์มิได้ทรงสถิตที่นั่น และเดินไปข้างหลัง แต่ข้าก็ไม่สังเกตเห็นพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 9, 'ข้างซ้ายมือที่พระองค์ทรงกระทํากิจ ข้าก็ไม่เห็นพระองค์ ข้างขวามือพระองค์ทรงซ่อนอยู่ ข้าหาพระองค์ไม่พบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 10, 'ด้วยว่าพระองค์ทรงทราบทางที่ข้าไป เมื่อพระองค์ทรงทดสอบข้าแล้ว ข้าก็จะเป็นอย่างทองคํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 11, 'เท้าของข้าติดรอยพระบาทของพระองค์แน่น ข้าตามมรรคาของพระองค์ และมิได้หันไปข้างๆเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 12, 'ข้ามิได้พรากไปจากพระบัญญัติแห่งริมพระโอษฐ์ของพระองค์ ข้าตีราคาพระวจนะแห่งพระโอษฐ์ของพระองค์สูงกว่าอาหารที่จําเป็นสําหรับข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 13, 'แต่พระองค์ทรงผันแปรมิได้ และผู้ใดจะหันพระองค์ได้ พระองค์มีพระประสงค์สิ่งใด พระองค์ก็ทรงกระทําสิ่งนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 14, 'เพราะว่าพระองค์จะทรงกระทําสิ่งที่พระองค์ทรงกําหนดให้ข้านั้นครบถ้วน และสิ่งอย่างนั้นเป็นอันมากอยู่ในพระดําริของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 15, 'เพราะฉะนั้นข้าจึงสะทกสะท้านต่อพระพักตร์พระองค์ เมื่อข้าตรึกตรอง ข้าก็ครั่นคร้ามต่อพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 16, 'พระเจ้าทรงกระทําให้ใจของข้าอ่อนเปลี้ย องค์ผู้ทรงมหิทธิฤทธิ์ได้กระทําให้ข้าสะทกสะท้าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 17, 'เพราะข้ามิได้ถูกตัดขาดก่อนความมืดมาถึง และพระองค์มิได้ทรงปิดบังความมืดทึบไว้จากหน้าข้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 1, '“เมื่อวาระกําหนดไม่ปิดบังไว้จากองค์ผู้ทรงมหิทธิฤทธิ์ ทําไมบรรดาผู้ที่รู้จักพระองค์ไม่เห็นวันกําหนดของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 2, 'มีคนที่ย้ายหลักเขต เขายึดฝูงแพะแกะพาไปเลี้ยง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 3, 'เขาไล่ต้อนลาของคนกําพร้าพ่อไป เขาเอาวัวของหญิงม่ายไปเป็นประกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 4, 'เขาผลักคนขัดสนออกนอกถนน คนยากจนแห่งแผ่นดินโลกต่างก็ซ่อนตัวหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 5, 'ดูเถิด ดังลาป่าอยู่ในถิ่นทุรกันดาร คนยากจนนั้นออกไปทํางานพยายามหาอาหาร ถิ่นแห้งแล้งให้อาหารแก่เขาและบุตรทั้งหลายของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 6, 'เขาทั้งหลายเก็บหญ้าแห้งที่ในทุ่ง และเขาเล็มสวนองุ่นของคนชั่ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 7, 'เขาทําให้คนที่เปลือยกายนอนตลอดคืนโดยไม่มีเสื้อผ้า และไม่มีผ้าห่มกันหนาว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 8, 'เขาเปียกฝนแห่งภูเขา และเกาะหินอยู่เพราะขาดที่กําบัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 9, 'มีผู้ฉวยเด็กกําพร้าพ่อไปจากอก และเอาของประกันจากคนยากจน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 10, 'เขาทั้งหลายทําให้เขาเดินเปลือยกายไปโดยไม่มีเสื้อผ้า เขาก็แบกฟ่อนข้าวไปจากคนที่หิว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 11, 'เขาทําน้ํามันอยู่ท่ามกลางกําแพงของพวกเขา เขาย่ําอยู่ที่บ่อย่ําองุ่น แต่เขาต้องทนความกระหาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 12, 'คนคร่ําครวญออกมาจากที่ในเมือง และจิตใจของคนบาดเจ็บร้องขอ แต่พระเจ้ามิได้สนพระทัยในความโง่เขลาของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 13, 'เขาอยู่ในพวกที่กบฏต่อความสว่าง ที่ไม่คุ้นเคยกับทางของความสว่างนั้น และมิได้อยู่ในทางของความสว่างนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 14, 'ฆาตกรลุกขึ้นมาแต่เช้าตรู่ เขาฆ่าคนยากจนและคนขัดสน และในกลางคืนเขาเป็นเหมือนขโมย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 15, 'ตาของผู้ล่วงประเวณีคอยเวลาพลบค่ํา กล่าวว่า ‘ไม่มีตาใดจะเห็นข้า’ และเขาก็ปลอมหน้าของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 16, 'ในยามมืดเขาขุดเข้าไปในเรือนซึ่งเขาหมายไว้สําหรับตนเองในเวลากลางวัน เขาไม่รู้จักความสว่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 17, 'เพราะเงามัจจุราชเป็นเหมือนเวลาเช้าแก่เขาทุกคน ถ้าใครรู้จักเขา เขาก็เป็นความสยดสยองของเงามัจจุราช');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 18, 'เขารวดเร็วดุจดังน้ํามากหลาย ส่วนแบ่งของเขาถูกสาปในแผ่นดิน เขาไม่หันหน้าไปสู่สวนองุ่นของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 19, 'ความแห้งแล้งและความร้อนฉวยเอาน้ําหิมะไปฉันใด แดนคนตายก็ฉวยเอาผู้กระทําบาปไปฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 20, 'ครรภ์จะลืมเขา ตัวหนอนจะกินเขาอย่างอร่อย ไม่มีใครจําเขาได้ต่อไป ความชั่วจะหักลงเหมือนต้นไม้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 21, 'เขารีดเอาจากหญิงหมันที่ไม่มีลูก และไม่ทําดีอะไรให้แก่หญิงม่าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 22, 'เขาได้ทําลายคนที่มีกําลังด้วยอํานาจของตน เขาลุกขึ้น แล้วไม่มีใครมั่นใจเรื่องชีวิตของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 23, 'พระเจ้าทรงประทานความปลอดภัยให้เขา และเขาก็พึ่งอยู่ และพระเนตรของพระองค์อยู่บนหนทางของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 24, 'เขาทั้งหลายถูกยกย่องขึ้นครู่หนึ่งแต่ก็ต้องสิ้นไปและถูกนําลงมา เขาถูกเอาออกไปจากทางเหมือนคนอื่นๆ และถูกตัดออกเหมือนยอดรวงข้าว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 25, 'แล้วบัดนี้ถ้าไม่เป็นเช่นนั้น ใครจะพิสูจน์ได้ว่าข้ามุสา และสําแดงว่าสิ่งที่ข้ากล่าวนั้นไร้สาระ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 1, 'แล้วบิลดัดคนชูอาห์ตอบว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 2, '“พระเจ้าทรงอํานาจในการครอบครองและทรงให้ยําเกรงพระองค์ ทรงกระทําสันติภาพในสวรรค์เบื้องสูงของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 3, 'กองทัพของพระองค์มีจํานวนหรือ ความสว่างของพระองค์มิได้ส่องมาเหนือผู้ใดบ้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 4, 'แล้วมนุษย์จะชอบธรรมต่อพระพักตร์พระเจ้าได้อย่างไร คนที่เกิดจากผู้หญิงจะสะอาดได้อย่างไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 5, 'ดูเถิด ถึงแม้ดวงจันทร์ก็ไม่มีความสุกใส และดวงดาวก็ไม่บริสุทธิ์ในสายพระเนตรของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 6, 'มนุษย์จะยิ่งสะอาดน้อยกว่านั้นเท่าใด ผู้เป็นเพียงตัวดักแด้ และบุตรของมนุษย์เล่า ผู้เป็นเพียงตัวหนอน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 1, 'แล้วโยบตอบว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 2, '“ท่านได้ช่วยผู้ไม่มีกําลังมากจริงหนอ ท่านได้ช่วยแขนที่ไม่มีแรงแล้วหนอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 3, 'ท่านให้คําปรึกษาแก่คนที่ไม่มีสติปัญญา และได้ให้ความรู้มากที่สัมฤทธิ์ผล จริงหนอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 4, 'ท่านเปล่งวาจาออกมาแก่ใครเล่า และวิญญาณของใครได้ออกมาจากท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 5, 'ชาวแดนคนตายเบื้องล่างสะทกสะท้านใต้น้ําและชาวเมืองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 6, 'นรกเปลือยอยู่ต่อพระพักตร์พระเจ้า และแดนพินาศไม่มีอะไรปกคลุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 7, 'พระองค์ทรงคลี่ทางเหนือออกคลุมที่เวิ้งว้าง และแขวนโลกไว้เหนือที่ว่างเปล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 8, 'พระองค์ทรงผูกมัดน้ําไว้ในเมฆทึบของพระองค์ และเมฆนั้นก็ไม่ฉีกขาดไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 9, 'พระองค์ทรงคลุมหน้าของพระที่นั่ง และคลี่เมฆของพระองค์ออกคลุมมันไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 10, 'พระองค์ทรงขีดปริมณฑลไว้บนพื้นน้ํา ณ เขตระหว่างความสว่างและความมืด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 11, 'เสาฟ้าก็หวั่นไหวและประหลาดใจเมื่อพระองค์ทรงขนาบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 12, 'พระองค์ทรงแยกทะเลด้วยอานุภาพของพระองค์ พระองค์ทรงตีคนจองหองด้วยความเข้าพระทัยของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 13, 'พระองค์ทรงตกแต่งฟ้าสวรรค์ด้วยพระวิญญาณของพระองค์ พระหัตถ์ของพระองค์ทรงสร้างพญานาคที่ขด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 14, 'ดูเถิด เหล่านี้เป็นเพียงพระราชกิจผิวเผินของพระองค์ เราได้ยินถึงพระองค์ก็เป็นเพียงเสียงกระซิบ ใครจะเข้าใจถึงฤทธิ์กัมปนาทอันเกรียงไกรของพระองค์ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 1, 'และโยบได้กล่าวกลอนภาษิตของตนอีกว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 2, '“พระเจ้าทรงพระชนม์อยู่แน่ฉันใด คือพระองค์ผู้ทรงนําความยุติธรรมอันควรตกแก่ข้าไปเสีย และองค์ผู้ทรงมหิทธิฤทธิ์ทรงพระชนม์อยู่แน่ฉันใด คือผู้ทรงทําใจข้าให้ขมขื่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 3, 'เพราะลมหายใจยังอยู่ในตัวข้าตราบใด และลมปราณจากพระเจ้ายังอยู่ในรูจมูกของข้าตราบใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 4, 'ริมฝีปากของข้าจะไม่พูดความเท็จและลิ้นของข้าจะไม่เปล่งคําหลอกลวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 5, 'ขอพระเจ้าอย่ายอมให้ข้าเห็นว่าท่านเป็นฝ่ายที่ถูกเลย ข้าจะไม่ทิ้งความสัตย์จริงของข้าจนข้าตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 6, 'ข้ายึดความชอบธรรมของข้าไว้มั่นไม่ยอมปล่อยไป จิตใจของข้าไม่ตําหนิข้า ไม่ว่าวันใดในชีวิตของข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 7, 'ขอให้ศัตรูของข้าเป็นเหมือนคนชั่ว และขอให้ผู้ที่ลุกขึ้นต่อสู้ข้าเป็นเหมือนคนอธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 8, 'เพราะอะไรจะเป็นความหวังของคนหน้าซื่อใจคด แม้ว่าเขาได้กําไรแล้ว เมื่อพระเจ้าทรงเอาชีวิตของเขาไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 9, 'พระเจ้าจะทรงฟังเสียงร้องของเขาหรือ เมื่อความยากลําบากมาสู่เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 10, 'เขาจะปีติยินดีในองค์ผู้ทรงมหิทธิฤทธิ์หรือ เขาจะกราบทูลพระเจ้าทุกเวลาหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 11, 'ข้าจะสอนท่านทั้งหลายโดยพระหัตถ์ของพระเจ้า ข้าจะไม่ปิดบังพระดําริขององค์ผู้ทรงมหิทธิฤทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 12, 'ดูเถิด ท่านทุกคนได้เห็นเองแล้ว ทําไมท่านจึงเหลวไหลสิ้นเชิงทีเดียวเล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 13, 'ต่อพระเจ้า นี่เป็นส่วนของคนชั่ว และมรดกซึ่งผู้บีบบังคับจะได้รับจากองค์ผู้ทรงมหิทธิฤทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 14, 'ถ้าลูกหลานของเขาเพิ่มขึ้น ก็เพื่อถูกดาบ และลูกหลานของเขาก็หาไม่พอกิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 15, 'คนของเขาที่เหลืออยู่ ความตายก็จะฝังเขาเสีย และภรรยาม่ายทั้งหลายของเขาจะไม่คร่ําครวญ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 16, 'ถึงเขาจะกอบโกยเอาเงินไว้มากอย่างผงคลีดิน และกองเสื้อผ้าไว้ดังดินเหนียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 17, 'เขาจะกองไว้ก็ได้ แต่คนชอบธรรมจะสวม และคนไร้ผิดจะแบ่งเงินกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 18, 'เขาสร้างบ้านเหมือนอย่างตัวมอด เหมือนอย่างเพิงที่คนยามสร้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 19, 'คนมั่งคั่งจะนอนลง แต่เขาจะไม่ถูกรวบรวมไว้ เขาลืมตาของเขาขึ้น และเขาไม่อยู่แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 20, 'ความสยดสยองท่วมเขาเหมือนน้ํามากหลาย ในกลางคืนพายุหอบเขาไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 21, 'ลมตะวันออกหอบเขาขึ้น และเขาก็จากไป เหมือนพายุมันก็กวาดเขาออกไปจากที่ของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 22, 'พระเจ้าจะทรงเหวี่ยงเขาอย่างไม่ปรานี เขาจะหนีจากพระหัตถ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 23, 'คนจะตบมือเยาะเย้ยเขา และเย้ยหยันเขาออกไปจากที่ของเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 1, '“แน่ละ ต้องมีเหมืองสําหรับแร่เงิน และมีที่สําหรับทองคําที่เขาถลุง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 2, 'เขาเอาเหล็กมาจากพื้นดิน และถลุงทองเหลืองจากแร่ดิบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 3, 'มนุษย์กําจัดความมืด และค้นหาไปยังเขตไกลที่สุด ค้นแร่ดิบในที่มืดครึ้มและเงามัจจุราช');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 4, 'เขาขุดปล่องไกลจากที่ฝูงคนอาศัยอยู่ คนสัญจรไปมาลืมเขาแล้ว เขาแขวนอยู่แกว่งไปแกว่งมาไกลจากฝูงคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 5, 'ฝ่ายแผ่นดินนั้นมีอาหารออกมา แต่ภายใต้ก็คว่ําอย่างถูกไฟไหม้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 6, 'ก้อนหินของที่นั่นเป็นที่อยู่ของพลอยไพทูรย์ และมันมีผงทองคํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 7, 'ทางนั้นไม่มีเหยี่ยวรู้ และไม่มีตาเหยี่ยวดํามองเห็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 8, 'ลูกสิงโตไม่เคยเดินที่นั่น สิงโตดุร้ายไม่ผ่านมาที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 9, 'คนยื่นมือที่หินแข็ง และทําลายภูเขาลงถึงราก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 10, 'เขาขุดลํารางไว้ในหิน และตาของเขาเห็นของประเสริฐทุกอย่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 11, 'เขากันตาน้ําไว้ เพื่อมิให้มีน้ําย้อย และสิ่งที่ปิดบังไว้ เขานํามาให้แจ้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 12, 'แต่จะพบพระปัญญาที่ไหน และที่ของความเข้าใจอยู่ที่ไหน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 13, 'มนุษย์ไม่รู้จักค่าของพระปัญญา และในแผ่นดินของคนเป็นก็หาไม่พบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 14, 'บาดาลพูดว่า ‘ที่ข้าไม่มี’ และทะเลกล่าวว่า ‘ไม่อยู่กับข้า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 15, 'จะเอาทองคําซื้อก็ไม่ได้ และจะชั่งเงินให้ตามราคาก็ไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 16, 'จะตีราคาเป็นทองคําโอฟีร์ก็ไม่ได้ หรือเป็นพลอยสีน้ําข้าวประเสริฐหรือพลอยไพทูรย์ก็ไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 17, 'จะเทียบเท่าทองคําและแก้วผลึกก็ไม่ได้ หรือจะแลกกับเครื่องทองคําเนื้อดีก็ไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 18, 'อย่าเอ่ยถึงหินปะการังและไข่มุกเลย ค่าของพระปัญญาสูงกว่ามุกดา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 19, 'บุษราคัมแห่งเมืองเอธิโอเปีย ก็เปรียบกับพระปัญญาไม่ได้ หรือจะตีราคาเป็นทองคําบริสุทธิ์ก็ไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 20, 'ดังนั้นพระปัญญามาจากไหนเล่า และที่ของความเข้าใจอยู่ที่ไหน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 21, 'เป็นสิ่งที่ซ่อนพ้นจากตาของสิ่งที่มีชีวิตทั้งปวง และปิดบังไว้จากนกในอากาศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 22, 'แดนพินาศและมัจจุราชกล่าวว่า ‘เราได้ยินเสียงลือเรื่องพระปัญญากับหูของเรา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 23, 'พระเจ้าทรงทราบทางไปหาพระปัญญานั้น และพระองค์ทรงทราบที่อยู่ของพระปัญญาด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 24, 'เพราะพระองค์ทอดพระเนตรไปถึงที่สุดปลายแผ่นดินโลก และทรงเห็นทุกสิ่งที่ใต้ฟ้าสวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 25, 'ในเมื่อพระองค์ทรงกําหนดน้ําหนักให้แก่ลม และทรงกะน้ําด้วยเครื่องตวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 26, 'เมื่อพระองค์ทรงสร้างกฎให้ฝน และสร้างทางไว้ให้แสงแลบของฟ้าผ่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 27, 'แล้วพระองค์ทอดพระเนตรพระปัญญาและทรงประกาศ ทรงสถาปนาไว้และทรงวิจัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 28, 'และพระองค์ตรัสกับมนุษย์ว่า ‘ดูเถิด ความยําเกรงองค์พระผู้เป็นเจ้า นั่นแหละคือพระปัญญา และที่จะหันจากความชั่ว คือความเข้าใจ’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 1, 'แล้วโยบก็กล่าวกลอนภาษิตของท่านอีกว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 2, '“โอ ข้าอยากจะอยู่อย่างแต่ละเดือนที่ผ่านไป อย่างในสมัยเมื่อพระเจ้าทรงพิทักษ์ข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 3, 'เมื่อประทีปของพระองค์ส่องเหนือศีรษะข้า และข้าเดินฝ่าความมืดไปด้วยความสว่างของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 4, 'อย่างข้าเมื่อครั้งยังหนุ่มแน่นอยู่ เมื่อความลึกลับแห่งพระเจ้าทรงอยู่เหนือเต็นท์ของข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 5, 'เมื่อองค์ผู้ทรงมหิทธิฤทธิ์ยังอยู่กับข้า และลูกหลานห้อมล้อมข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 6, 'เมื่อข้าล้างย่างเท้าของข้าด้วยเนยข้น และก้อนหินเทธารน้ํามันออกให้ข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 7, 'เมื่อข้าออกมายังประตูเมือง เมื่อข้าเตรียมที่นั่งของข้าที่ถนน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 8, 'คนหนุ่มๆเห็นข้าแล้วก็หลีกไป คนสูงอายุลุกขึ้นยืน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 9, 'เจ้านายหยุดพูด เอามือปิดปากของตนไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 10, 'เสียงของขุนนางก็สงบลง และลิ้นของเขาก็เกาะติดเพดานปาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 11, 'เมื่อหูได้ยินแล้ว ต่างก็ว่าข้าเป็นสุข และเมื่อตาดู ก็ยกย่องข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 12, 'เพราะว่าข้าช่วยคนยากจนที่ร้องให้ช่วย และเด็กกําพร้าพ่อที่ไม่มีใครอุปถัมภ์เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 13, 'พรของคนที่จวนพินาศก็มาถึงข้า และข้าเป็นเหตุให้จิตใจของหญิงม่ายร้องเพลงด้วยความชื่นบาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 14, 'ข้าสวมความชอบธรรม และมันก็ห่อหุ้มข้าไว้ ความยุติธรรมของข้าเหมือนเสื้อคลุมและผ้าโพกศีรษะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 15, 'ข้าเป็นนัยน์ตาให้คนตาบอด และเป็นเท้าให้คนง่อย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 16, 'ข้าเป็นบิดาให้คนขัดสน และข้าสอบสวนเรื่องของผู้ที่ข้าไม่รู้จัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 17, 'ข้าหักขากรรไกรของคนชั่ว และได้ดึงเอาเหยื่อจากฟันของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 18, 'แล้วข้าคิดว่า ‘ข้าจะตายในรังของข้า และข้าจะทวีวันเวลาของข้าอย่างทราย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 19, 'รากของข้าจะแผ่ไปถึงน้ํา มีน้ําค้างบนกิ่งของข้าตลอดคืน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 20, 'สง่าราศีของข้าสดชื่นอยู่กับข้า และคันธนูของข้าใหม่เสมออยู่ในมือข้า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 21, 'คนทั้งหลายเงี่ยหูฟังข้าและคอยอยู่ และเงียบอยู่ฟังคําปรึกษาของข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 22, 'หลังจากที่ข้าพูดแล้ว เขาก็ไม่พูดอีกเลย และคําของข้าก็กลั่นลงมาเหนือเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 23, 'เขาคอยข้าเหมือนคอยฝน เขาอ้าปากของเขาเหมือนอย่างรอรับน้ําฝนชุกปลายฤดู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 24, 'ถ้าข้าหัวเราะเยาะเขา เขาก็ไม่ยอมเชื่อ และสีหน้าอันผ่องใสของข้า เขาก็มิได้ทําให้หม่นหมองลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 25, 'ข้าเลือกทางให้เขา และนั่งเป็นหัวหน้า และอยู่อย่างกษัตริย์ท่ามกลางกองทหาร อย่างผู้ที่ปลอบโยนคนที่คร่ําครวญ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 1, '“แต่เดี๋ยวนี้เขาเยาะข้า คือคนที่อ่อนกว่าข้าน่ะ คนที่ข้าจะเหยียดหยามพ่อของเขา ถึงกับไม่ยอมให้อยู่กับสุนัขที่เฝ้าฝูงแพะแกะของข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 2, 'ข้าจะได้อะไรจากกําลังมือของเขาทั้งหลาย คือของคนที่เรี่ยวแรงเขาหมดไปแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 3, 'เพราะเหตุความขาดแคลนและหิวโหยพวกเขาจึงอยู่อย่างโดดเดี่ยว เมื่อก่อนเขาหนีไปยังถิ่นทุรกันดารซึ่งรกร้างและถูกทิ้งไว้เสียเปล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 4, 'เขาเก็บผักชะครามซึ่งอยู่กับพุ่มไม้ และเอารากต้นไม้จําพวกสนจูนิเปอร์มาเป็นอาหาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 5, 'เขาถูกขับไล่ออกไปจากท่ามกลางคน (มีคนตะโกนตามเขาไปอย่างตามโจร)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 6, 'ฉะนั้น เขาต้องพักอยู่ที่ลําละหาน ในโพรงดินและซอกหิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 7, 'เขาร้องอยู่ท่ามกลางพุ่มไม้ เขาเบียดกันอยู่ภายใต้ต้นตําแย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 8, 'เขาเป็นลูกของคนถ่อย เออ เป็นลูกของคนเสียชื่อ เขาถูกกวาดออกไปเสียจากแผ่นดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 9, 'และบัดนี้ข้ากลายเป็นเพลงเยาะเย้ยของเขา เออ ข้าเป็นที่ครหาของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 10, 'เขาทั้งหลายสะอิดสะเอียนข้า และเหินห่างจากข้า เขาไม่รั้งรอที่จะถ่มน้ําลายลงหน้าของข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 11, 'เพราะพระเจ้าทรงหย่อนสายธนูของข้า และให้ข้าตกต่ํา เขาทั้งหลายก็เหวี่ยงความยั้งคิดเสียต่อหน้าข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 12, 'คนหนุ่มลุกขึ้นข้างขวามือของข้า เขาผลักดันเท้าของข้าออกไป เขาเหวี่ยงทางแห่งความพินาศไว้ต่อสู้ข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 13, 'เขาพังทางเดินของข้า เขาเสริมภัยพิบัติให้ข้า ไม่มีผู้ใดช่วยเขาไว้เลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 14, 'เขามาหาข้าอย่างกับน้ําที่ทะลักเข้ามาอย่างเต็มที่ เขากลิ้งตัวเข้ามาหาข้าท่ามกลางซากปรักหักพัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 15, 'ความสยดสยองต่างๆหันมาใส่ข้า จิตใจของข้าถูกเขาติดตามอย่างลมตาม และความเจริญรุ่งเรืองของข้าสูญไปเสียอย่างเมฆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 16, 'บัดนี้จิตใจของข้าก็ละลายไป วันแห่งความทุกข์ใจยึดตัวข้าไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 17, 'กลางคืนกระดูกข้าทะลุไป และความเจ็บปวดที่แทะข้านั้นไม่หยุดพักเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 18, 'เครื่องแต่งกายของข้าเสียรูปไปด้วยความรุนแรงแห่งโรคนี้ มันมัดข้าอย่างผ้าคอเสื้อรัดข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 19, 'พระเจ้าทรงเหวี่ยงข้าลงในปลัก และข้าก็กลายเป็นเหมือนผงคลีและขี้เถ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 20, 'ข้าพระองค์ร้องทูลพระองค์ และพระองค์หาทรงสดับข้าพระองค์ไม่ ข้าพระองค์ยืนขึ้น และพระองค์หาทรงมองไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 21, 'พระองค์กลับทรงดุร้ายต่อข้าพระองค์ พระองค์ทรงต่อต้านข้าพระองค์ด้วยพระหัตถ์ทรงฤทธิ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 22, 'พระองค์ทรงชูข้าพระองค์ขึ้นเหนือลม และทรงให้ข้าพระองค์ขี่ลม และทรงให้ตัวข้าพระองค์ละลายไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 23, 'ข้าพระองค์ทราบแล้วว่าพระองค์จะทรงให้ข้าพระองค์ตายเสีย และให้ไปสู่ที่กําหนดของคนเป็นทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 24, 'ถึงกระนั้นเขาจะไม่ยื่นมือของเขาออกช่วยคนในแดนคนตาย ถึงแม้ว่าพวกเขาร้องขอความช่วยเหลือในท่ามกลางภัยพิบัติของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 25, 'ข้ามิได้ร้องไห้เพื่อผู้ที่วันเวลาของเขายากเย็นหรือ จิตใจของข้ามิได้โศกสลดเพื่อคนขัดสนหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 26, 'แต่เมื่อข้ามองหาของดี ของร้ายก็มาถึง และเมื่อข้าคอยความสว่าง ความมืดก็มาถึง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 27, 'จิตใจของข้าร้อนรุ่มไม่เคยสงบเลย วันแห่งความทุกข์ใจมาพบข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 28, 'ข้าได้ไว้ทุกข์ มิใช่ด้วยแดด ข้ายืนขึ้นในที่ชุมนุมชน และร้องขอความช่วยเหลือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 29, 'ข้าเป็นพี่น้องกับมังกร และเป็นเพื่อนกับนกเค้าแมว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 30, 'ผิวหนังของข้าดํา กระดูกของข้าร้อนอย่างไฟไหม้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 31, 'เพราะฉะนั้นเสียงพิณเขาคู่ของข้ากลายเป็นเสียงโหยไห้ และเสียงขลุ่ยของข้ากลายเป็นเสียงของผู้ที่ร้องไห้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 1, '“ข้าได้ทําพันธสัญญากับนัยน์ตาของข้า แล้วข้าจะมองหญิงพรหมจารีได้อย่างไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 2, 'อะไรจะเป็นส่วนของข้าจากพระเจ้าเบื้องบน และเป็นมรดกของข้าจากองค์ผู้ทรงมหิทธิฤทธิ์ ณ ที่สูง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 3, 'มิใช่ภยันตรายสําหรับคนชั่ว และภัยพิบัติสําหรับคนที่กระทําความชั่วช้าดอกหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 4, 'พระองค์มิทรงเห็นทางที่ข้าไป และนับฝีก้าวของข้าดอกหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 5, 'ถ้าข้าได้ดําเนินไปกับความไร้สาระ และเท้าของข้าเร่งไปสู่ความหลอกลวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 6, 'ก็ขอให้เอาข้าชั่งด้วยตราชูเที่ยงตรง และขอพระเจ้าทรงทราบความซื่อสัตย์ของข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 7, 'ถ้าย่างเท้าของข้าหันออกไปจากทาง และจิตใจของข้าดําเนินตามนัยน์ตาของข้า และถ้าความด่างพร้อยใดๆเกาะติดมือข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 8, 'ก็ขอให้ข้าหว่าน และให้คนอื่นกิน และขอให้สิ่งที่งอกขึ้นเพื่อข้าถูกถอนรากเอาไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 9, 'ถ้าใจของข้าถูกล่อชวนไปหาผู้หญิง และข้าได้ซุ่มอยู่ที่ประตูเพื่อนบ้านของข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 10, 'แล้วก็ขอให้ภรรยาของข้าโม่แป้งให้คนอื่น และให้คนอื่นโน้มทับนาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 11, 'เพราะนั่นเป็นความผิดที่ร้ายกาจ และเป็นความชั่วช้าที่ผู้พิพากษาต้องปรับโทษ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 12, 'เพราะนั่นจะเป็นไฟผลาญให้ไปถึงแดนพินาศ และจะถอนรากผลเพิ่มพูนทั้งปวงของข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 13, 'ถ้าข้าดูถูกเรื่องของทาสหรือทาสหญิงของข้า เมื่อเขานํามาร้องทุกข์ต่อข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 14, 'เมื่อพระเจ้าทรงลุกขึ้น แล้วข้าจะทําอะไรได้ เมื่อพระองค์ทรงสอบถาม ข้าจะทูลตอบพระองค์อย่างไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 15, 'พระองค์ผู้ทรงสร้างข้าในครรภ์ มิได้ทรงสร้างเขาหรือ มิใช่พระองค์องค์เดียวเท่านั้นหรือ ที่ทรงสร้างเราทั้งสองในครรภ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 16, 'ถ้าข้าได้หน่วงเหนี่ยวสิ่งใดๆที่คนยากจนอยากได้ หรือได้กระทําให้นัยน์ตาของหญิงม่ายมองเสียเปล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 17, 'หรือข้ารับประทานอาหารของข้าแต่ลําพัง และคนกําพร้าพ่อไม่ได้ร่วมรับประทานอาหารนั้นด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 18, '(เพราะตั้งแต่เด็กมา เขาเติบโตขึ้นกับข้า อย่างอยู่กับพ่อ และข้าได้เป็นผู้แนะนําเธอตั้งแต่ครรภ์มารดาของข้า)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 19, 'ถ้าข้าเห็นคนหนึ่งคนใดพินาศเพราะขาดเสื้อผ้า หรือเห็นคนขัดสนไม่มีผ้าคลุมกาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 20, 'ถ้าบั้นเอวของเขามิได้อวยพรแก่ข้า และถ้าเขามิได้อบอุ่นด้วยขนแกะของข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 21, 'ถ้าข้ายกมือขึ้นแตะต้องคนกําพร้าพ่อเพราะข้าเห็นความสนับสนุนที่ประตูเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 22, 'แล้วก็ให้กระดูกไหปลาร้าหลุดจากบ่าของข้า และให้แขนของข้าหักหลุดจากข้อต่อเสียเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 23, 'เพราะข้าสยดสยองด้วยภัยพิบัติที่มาจากพระเจ้า และด้วยเหตุความโอ่อ่าตระการของพระองค์ ข้าทําอะไรไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 24, 'ถ้าข้ากระทําให้ทองคําเป็นที่ไว้ใจหรือพูดกับทองคําเนื้อดีว่า ‘ท่านเป็นที่วางใจของข้า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 25, 'ถ้าข้าเปรมปรีดิ์เพราะสมบัติของข้ามากมาย หรือเพราะมือของข้าได้มามาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 26, 'หรือข้าเพ่งดวงอาทิตย์เมื่อส่องแสง หรือดวงจันทร์เมื่อเคลื่อนไปอย่างสง่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 27, 'และจิตใจของข้าถูกล่อชวนอยู่อย่างลับๆ และปากของข้าจุบมือของข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 28, 'นี่เป็นความชั่วช้าด้วยที่ผู้พิพากษาจะต้องปรับโทษ เพราะข้าคงต้องปฏิเสธพระเจ้าเบื้องบน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 29, 'ถ้าข้าเปรมปรีดิ์เมื่อผู้ที่เกลียดชังข้านั้นพินาศ หรือเริงโลดเมื่อเหตุร้ายมาทันเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 30, 'ข้าไม่ยอมให้ปากของข้าบาปไปโดยขอชีวิตของเขาด้วยคําสาปแช่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 31, 'ถ้าคนแห่งเต็นท์ของข้ามิได้กล่าวว่า ‘โอ ยังมีใครที่ไหนที่กินเนื้อของนายไม่อิ่ม’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 32, 'คนต่างถิ่นมิได้พักอยู่ในถนน ข้าเปิดประตูให้แก่คนเดินทาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 33, 'ถ้าข้าปิดบังการละเมิดของข้าอย่างอาดัม ด้วยซ่อนความชั่วช้าของข้าไว้ในอกของข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 34, 'เพราะข้ากลัวมวลชนและกลัวที่ครอบครัวต่างๆจะเหยียดหยามข้า ข้าจึงนิ่งเสีย ไม่ออกไปพ้นประตูบ้าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 35, 'โอ ข้าอยากให้สักคนหนึ่งฟังข้า ดูเถิด ความปรารถนาของข้าคือ ขอองค์ผู้ทรงมหิทธิฤทธิ์ตอบข้า ข้าอยากได้คําสํานวนฟ้องข้าซึ่งคู่ความเขียนขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 36, 'ข้าจะใส่บ่าแบกไปแน่ทีเดียว ข้าจะมัดมันไว้ต่างมงกุฎ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 37, 'ข้าจะแจ้งจํานวนฝีก้าวของข้าแก่พระองค์ ข้าจะเข้าไปเฝ้าพระองค์อย่างเป็นเจ้านาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 38, 'ถ้าที่ดินของข้าร้องกล่าวโทษข้า และร่องไถในนั้นร้องไห้ด้วยกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 39, 'ถ้าข้ากินผลิตผลของมันด้วยมิได้เสียเงิน และกระทําให้เจ้าของที่ดินเดิมนั้นเสียชีวิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 40, 'ก็ขอให้มีต้นผักหนามงอกแทนข้าวสาลี และหญ้าสาบแร้งแทนข้าวบาร์เลย์” จบถ้อยคําของโยบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 1, 'ดังนั้น บุรุษทั้งสามก็หยุดตอบโยบ เพราะโยบชอบธรรมในสายตาของตนเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 2, 'แล้วเอลีฮู บุตรชายบาราเคล คนบุชี ครอบครัวราม ก็โกรธ เขาโกรธโยบ เพราะท่านอ้างตัวว่าชอบธรรมหาใช่พระเจ้าไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 3, 'เขาโกรธสหายสามคนของโยบด้วย เพราะเขาทั้งหลายตอบไม่ได้ ทั้งๆที่เขาหาว่าโยบผิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 4, 'ฝ่ายเอลีฮูคอยจนโยบพูดจบ เพราะพวกเขาแก่กว่าตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 5, 'และเมื่อเอลีฮูเห็นว่าไม่มีคําตอบในปากของบุรุษทั้งสามนี้แล้ว เขาจึงโกรธ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 6, 'และเอลีฮู บุตรชายบาราเคล คนบุชี กล่าวว่า “ข้าพเจ้ายังเยาว์วัย และท่านสูงอายุแล้ว เพราะฉะนั้นข้าพเจ้าเกรงกลัวที่จะกล่าวความคิดเห็นของข้าพเจ้าแก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 7, 'ข้าพเจ้าว่า ‘ขอให้วัยพูดเถิด และให้ปีหลายปีสอนสติปัญญา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 8, 'แต่มีจิตวิญญาณในมนุษย์ การดลใจจากองค์ผู้ทรงมหิทธิฤทธิ์กระทําให้เขาเข้าใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 9, 'ไม่ใช่ผู้ยิ่งใหญ่เท่านั้นที่เป็นคนฉลาด หรือคนสูงอายุเข้าใจความยุติธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 10, 'เพราะฉะนั้น ข้าพเจ้าจึงว่า ‘ขอฟังข้าพเจ้า ขอให้ข้าพเจ้ากล่าวความคิดเห็นของข้าพเจ้าด้วย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 11, 'ดูเถิด ข้าพเจ้าได้คอยฟังคําของท่านทั้งหลาย ข้าพเจ้าเงี่ยหูฟังเหตุผลของท่านขณะที่ท่านค้นหาว่าจะพูดว่ากระไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 12, 'เออ ข้าพเจ้าสนใจฟังท่าน และ ดูเถิด ไม่มีผู้ใดให้เหตุผลอันควรแก่โยบ ในพวกท่านไม่มีผู้ใดที่ตอบคําของโยบได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 13, 'อย่าเพ่อพูดนะว่า ‘เราได้พบพระปัญญาแล้ว พระเจ้าทรงผลักเขาลงแล้ว มิใช่มนุษย์’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 14, 'เขามิได้เพ่งเล็งถ้อยคําของเขาใส่ข้าพเจ้า และข้าพเจ้าจะไม่ตอบถ้อยคําของเขาด้วยคําพูดของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 15, 'เขาทั้งหลายก็ตกตะลึง เขาไม่ตอบอีก เขาไม่มีถ้อยคําจะพูดสักคําเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 16, 'และข้าพเจ้าจะคอยหรือ (เพราะเขาทั้งหลายไม่พูด เพราะเขายืนอยู่ที่นั่น ไม่ตอบอีก)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 17, 'ข้าพเจ้ากล่าวว่า ‘ข้าพเจ้าจะให้คําตอบของข้าพเจ้า ข้าพเจ้าจะสําแดงความคิดเห็นของข้าพเจ้าด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 18, 'เพราะข้าพเจ้ามีถ้อยคําเต็มตัว จิตใจภายในข้าพเจ้าบังคับข้าพเจ้าอยู่’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 19, 'ดูเถิด จิตใจของข้าพเจ้าเหมือนเหล้าองุ่นซึ่งไม่มีที่ระบายออก เหมือนถุงหนังเหล้าองุ่นใหม่จะระเบิดอยู่รอมร่อแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 20, 'ข้าพเจ้าต้องพูดจึงจะได้ความบรรเทา ข้าพเจ้าต้องเปิดริมฝีปากขึ้นตอบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 21, 'ข้าพเจ้าจะไม่แสดงอคติต่อบุคคลใดๆ หรือใช้การประจบสอพลอต่อผู้ใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 22, 'เพราะข้าพเจ้าประจบสอพลอไม่ได้ ถ้าทําอย่างนั้น ผู้ทรงสร้างของข้าพเจ้าจะกําจัดข้าพเจ้าเสียในไม่ช้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 1, '“ท่านโยบเจ้าข้า อย่างไรก็ตามขอฟังคําของข้าพเจ้า และฟังถ้อยคําทั้งสิ้นของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 2, 'ดูเถิด บัดนี้ข้าพเจ้าได้อ้าปาก ลิ้นภายในปากของข้าพเจ้าก็พูด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 3, 'ถ้อยคําของข้าพเจ้าสําแดงความเที่ยงธรรมแห่งจิตใจ และริมฝีปากของข้าพเจ้าจะกล่าวความรู้อย่างจริงใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 4, 'พระวิญญาณของพระเจ้าได้ทรงสร้างข้าพเจ้า และลมปราณขององค์ผู้ทรงมหิทธิฤทธิ์ได้ให้ชีวิตแก่ข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 5, 'ถ้าท่านตอบข้าพเจ้าได้ ก็ตอบซี จงลําดับถ้อยคําของท่านต่อหน้าข้าพเจ้า เชิญเถอะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 6, 'ดูเถิด ข้าพเจ้าอยู่อย่างท่านตรงพระพักตร์พระเจ้า พระองค์ทรงปั้นข้าพเจ้าขึ้นมาจากดินด้วยเหมือนกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 7, 'ดูเถิด อย่าให้ความกลัวข้าพเจ้ากระทําให้ท่านตกใจ ข้าพเจ้าจะไม่ชักชวนท่านหนักเกินไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 8, 'แน่ละ ท่านพูดให้ข้าพเจ้าฟัง และข้าพเจ้าได้ยินเสียงถ้อยคําของท่านว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 9, '‘ข้าพเจ้าสะอาด ปราศจากการละเมิด ข้าพเจ้าบริสุทธิ์ ไม่มีความชั่วช้าในข้าพเจ้าเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 10, 'ดูเถิด พระองค์ทรงหาเรื่องกับข้าพเจ้า พระองค์ทรงนับว่าข้าพเจ้าเป็นศัตรูกับพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 11, 'พระองค์ทรงเอาเท้าของข้าพเจ้าใส่ขื่อไว้ และทรงเฝ้าดูทางของข้าพเจ้าทั้งสิ้น’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 12, 'ดูเถิด ในเรื่องนี้ท่านไม่ยุติธรรมเลย ข้าพเจ้าจะตอบท่าน พระเจ้าใหญ่ยิ่งกว่ามนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 13, 'ทําไมท่านจึงโต้แย้งกับพระองค์ เพราะพระองค์ไม่ทรงรายงานเรื่องพระราชกิจใดๆของพระองค์เลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 14, 'เพราะพระเจ้าตรัสครั้งหนึ่ง เออ สองครั้ง แต่มนุษย์ไม่หยั่งรู้ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 15, 'ในความฝัน ในนิมิตกลางคืนเมื่อคนหลับสนิท เมื่อเขาเคลิบเคลิ้มอยู่บนที่นอนของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 16, 'แล้วพระองค์ทรงเบิกหูของมนุษย์ และทรงประทับตราคําสั่งสอนของเขาไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 17, 'เพื่อว่าพระองค์จะได้หันให้มนุษย์กลับจากเป้าหมายของเขา และตัดความเย่อหยิ่งออกเสียจากมนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 18, 'พระองค์ทรงยึดเหนี่ยววิญญาณของเขาไว้จากปากแดนคนตาย และยึดชีวิตของเขาไว้จากการที่จะพินาศด้วยดาบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 19, 'มนุษย์ยังถูกตีสอนด้วยความเจ็บปวดบนที่นอนของเขาด้วย และด้วยความเจ็บปวดอย่างสาหัสในกระดูกต่างๆของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 20, 'ชีวิตของเขาจึงได้เบื่ออาหาร และจิตใจจึงได้เบื่ออาหารโอชะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 21, 'เนื้อของเขาทรุดโทรมไปมากจนมองไม่เห็น กระดูกของเขาซึ่งแลไม่เห็นนั้นก็โผล่ออกมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 22, 'เออ วิญญาณของเขาเข้าไปใกล้ปากแดนคนตาย และชีวิตของเขาใกล้ผู้ที่นําความตายมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 23, 'ถ้ามีผู้ส่งข่าวผู้หนึ่งมาเพื่อเขาเป็นล่าม หนึ่งในพันเพื่อแถลงแก่มนุษย์ว่าอะไรถูกเพื่อเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 24, 'และผู้ส่งข่าวนั้นกรุณาเขา ทูลว่า ‘ขอทรงปล่อยเขาให้พ้นจากที่จะไปยังปากแดนคนตาย ข้าพระองค์พบค่าไถ่แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 25, 'เนื้อของเขาจะอ่อนกว่าเนื้อเด็ก ขอให้เขากลับไปสู่กําลังเหมือนเมื่อยังหนุ่ม’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 26, 'เขาจึงจะอธิษฐานต่อพระเจ้า และพระองค์จะทรงพอพระทัยเขา เขาจะเห็นพระพักตร์พระองค์ด้วยความชื่นบาน แล้วพระองค์จะทรงให้มนุษย์กลับสู่สภาพความชอบธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 27, 'พระองค์ทรงทอดพระเนตรมนุษย์ และถ้าผู้ใดกล่าวว่า ‘ข้าบาปแล้ว และเห็นผิดเป็นชอบ และมิได้เป็นประโยชน์อะไรแก่ข้า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 28, 'พระองค์จะทรงไถ่จิตวิญญาณของเขาให้พ้นจากการลงไปสู่ปากแดนคนตาย และชีวิตของเขาจะเห็นความสว่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 29, 'ดูเถิด พระเจ้าทรงกระทําสิ่งเหล่านี้ทั้งสิ้นกับมนุษย์บ่อยๆหลายครั้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 30, 'เพื่อจะนําจิตวิญญาณของเขามาจากปากแดนคนตาย เพื่อให้เขาแจ่มแจ้งขึ้นด้วยความสว่างแห่งผู้ทรงมีชีวิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 31, 'โอ ท่านโยบเจ้าข้า ขอตั้งใจฟังข้าพเจ้า ขอเงียบ และข้าพเจ้าจะพูด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 32, 'ถ้าท่านมีอะไรพูดก็ตอบข้าพเจ้ามาเถอะ เพราะข้าพเจ้าปรารถนาแก้คดีให้ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 33, 'ถ้าหาไม่ก็ขอฟังข้าพเจ้า ขอเงียบและข้าพเจ้าจะสอนปัญญาให้แก่ท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 1, 'เอลีฮูพูดต่อไปว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 2, '“โอ ท่านผู้มีปัญญา ขอฟังถ้อยคําของข้าพเจ้า ท่านผู้มีความรู้ ขอเงี่ยหูฟังข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 3, 'เพราะหูก็ลองชิมถ้อยคําอย่างกับเพดานปากชิมอาหาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 4, 'ขอให้เราเลือกสิ่งที่ถูก ขอให้เราเรียนรู้ในพวกเราเองว่าอะไรดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 5, 'เพราะโยบกล่าวว่า ‘ข้าพเจ้าเป็นคนชอบธรรม และพระเจ้าทรงเอาความยุติธรรมที่ควรตกแก่ข้าพเจ้าไปเสีย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 6, 'ข้าพเจ้าถูกนับเป็นคนมุสา ถึงแม้ข้าพเจ้าชอบธรรม แผลของข้าพเจ้ารักษาไม่หายแม้ว่าข้าพเจ้าไม่มีการละเมิดเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 7, 'ใครหนอที่จะเหมือนโยบ ผู้ดื่มความเหยียดหยามเหมือนดื่มน้ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 8, 'ผู้เข้าสังคมกับคนกระทําความชั่วช้า และเดินไปกับคนชั่ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 9, 'เพราะท่านได้กล่าวว่า ‘ไม่เป็นประโยชน์อะไรแก่มนุษย์เราที่เขาจะปีติยินดีในพระเจ้า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 10, 'เพราะฉะนั้น ท่านผู้มีความเข้าใจ ขอฟังข้าพเจ้า เมินเสียเถิดที่พระเจ้าจะทรงกระทําความชั่ว และที่องค์ผู้ทรงมหิทธิฤทธิ์จะทรงกระทําความชั่วช้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 11, 'เพราะพระเจ้าทรงสนองตามการกระทําของมนุษย์ และพระองค์ทรงให้เกิดแก่เขาตามการกระทําของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 12, 'แน่นอนทีเดียว พระเจ้าจะไม่ทรงกระทําชั่ว และองค์ผู้ทรงมหิทธิฤทธิ์จะไม่ทรงผันแปรความยุติธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 13, 'ใครแต่งตั้งให้พระองค์ปกครองโลก หรือใครเล่ามอบหมายทั้งโลกไว้กับพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 14, 'ถ้าพระองค์ทรงเอาพระทัยใส่กับมนุษย์ และทรงรวบรวมวิญญาณและลมปราณของเขากลับมาสู่พระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 15, 'เนื้อหนังทั้งสิ้นก็จะพินาศไปด้วยกัน และมนุษย์ก็จะกลับไปเป็นผงคลีดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 16, 'ถ้าท่านมีความเข้าใจ ขอฟังข้อนี้ ขอฟังเสียงถ้อยคําของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 17, 'ผู้ที่เกลียดชังความยุติธรรมควรจะปกครองหรือ ท่านจะประณามผู้ที่ชอบธรรมที่สุดหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 18, 'เหมาะสมหรือไม่ที่จะพูดแก่กษัตริย์ว่า ‘ท่านผู้ชั่วร้าย’ และแก่เจ้านายว่า ‘ท่านทั้งหลายผู้อธรรม’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 19, 'ยิ่งไม่เหมาะสมที่จะแสดงอคติแก่เจ้านาย หรือไม่ทรงเห็นแก่คนมั่งคั่งมากกว่าคนยากจน เพราะคนทั้งหมดนี้เป็นพระหัตถกิจของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 20, 'สักครู่เดียวเขาทั้งหลายก็ตาย เวลาเที่ยงคืนประชาชนตัวสั่นและตายไป และผู้มีอานุภาพก็ถูกเอาไปเสียมิใช่ด้วยมือมนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 21, 'เพราะพระเนตรของพระองค์มองดูทางทั้งหลายของมนุษย์ พระองค์ทรงเห็นย่างเท้าของเขาหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 22, 'ไม่มีที่มืดครึ้มหรือเงามัจจุราชซึ่งคนกระทําความชั่วช้าจะซ่อนตัวได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 23, 'เพราะพระองค์จะไม่ทรงกําหนดให้มนุษย์ทําเกินสิ่งที่สมควร ให้เข้าเฝ้าพระเจ้ารับการพิพากษา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 24, 'พระองค์ทรงทุบผู้มีอานุภาพเป็นชิ้นๆโดยไม่ต้องนับและทรงตั้งคนอื่นไว้แทน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 25, 'เพราะฉะนั้นพระองค์ทรงทราบกิจการของเขา และทรงคว่ําเขาเสียในกลางคืน เขาก็แหลกไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 26, 'พระองค์ทรงตีเขาเหมือนอย่างคนชั่วต่อหน้าต่อตาคนอื่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 27, 'เพราะว่าเขาทั้งหลายหันกลับเสียจากการติดตามพระองค์ และไม่นับถือมรรคาของพระองค์แต่อย่างใดเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 28, 'เหตุนี้เขาจึงกระทําให้เสียงร้องของคนยากจนมาถึงพระองค์ และพระองค์ทรงฟังเสียงร้องของผู้รับความทุกข์ใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 29, 'เมื่อพระองค์ทรงประทานความสงบให้ ใครจะสร้างความยุ่งยากได้ เมื่อพระองค์ทรงซ่อนพระพักตร์ของพระองค์ ใครจะเห็นพระองค์ได้ ไม่ว่าจะทําแก่ประชาชาติหรือแก่บุคคลก็เหมือนกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 30, 'เพื่อว่าคนหน้าซื่อใจคดจะไม่ได้ครอบครอง และเขาจะไม่วางกับดักประชาชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 31, 'เพราะเป็นสิ่งเหมาะสมที่จะร้องทูลพระเจ้าว่า ‘ข้าพระองค์ได้รับการตีสอนแล้ว ข้าพระองค์จะไม่ทําผิดต่อไปอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 32, 'ขอทรงโปรดสอนข้าพระองค์ถึงสิ่งที่ข้าพระองค์มองไม่เห็น ถ้าข้าพระองค์กระทําความชั่วช้า ข้าพระองค์จะไม่กระทําอีก’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 33, 'การตอบสนองของพระองค์จะต้องเป็นอย่างที่ท่านต้องการหรือ ท่านจึงไม่รับ ท่านเองต้องเลือก และไม่ใช่ข้าพเจ้า เหตุฉะนั้นท่านมีความคิดเห็นอย่างไร ก็พูดไปเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 34, 'จงให้คนที่เข้าใจพูดกับข้าพเจ้า และให้คนฉลาดฟังข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 35, 'โยบพูดอย่างไม่มีความรู้ ถ้อยคําของเขาปราศจากสติปัญญา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 36, 'ข้าพเจ้าปรารถนาให้โยบถูกทดลองต่อไปถึงที่สุด เพราะว่าเขาตอบเหมือนอย่างคนชั่ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 37, 'เพราะเขาเพิ่มการกบฏเข้ากับบาปของเขา เขาตบมือเย้ยอยู่ท่ามกลางเรา และทวีถ้อยคําของเขากล่าวร้ายพระเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 1, 'เอลีฮูพูดต่อไปว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 2, '“ท่านคิดว่า นี่ยุติธรรมหรือ ท่านพูดหรือว่า ‘ความชอบธรรมของข้าพเจ้ายิ่งกว่าของพระเจ้า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 3, 'ที่ท่านถามว่า ‘ข้าพเจ้าจะได้ประโยชน์อะไร’ และ ‘ข้าพเจ้าจะได้ประโยชน์อะไรถ้าข้าพเจ้าได้รับการชําระจากบาปของข้าพเจ้า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 4, 'ข้าพเจ้าจะตอบท่านกับมิตรสหายของท่านด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 5, 'จงมองดูท้องฟ้าเถิด ดูเมฆซึ่งอยู่สูงกว่าท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 6, 'ถ้าท่านทําบาป ท่านจะได้อะไรที่กระทบกระเทือนพระองค์ ถ้าการละเมิดของท่านทวีขึ้น ท่านทําอะไรแก่พระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 7, 'ถ้าท่านเป็นคนชอบธรรม ท่านถวายอะไรแด่พระองค์ หรือพระองค์ทรงรับอะไรจากมือของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 8, 'ความชั่วของท่านก็เป็นอันตรายแก่คนอย่างท่าน และความชอบธรรมของท่านก็เป็นประโยชน์แก่บุตรมนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 9, 'เหตุด้วยการถูกบีบบังคับเป็นอันมาก ก็ทําให้ผู้ที่ถูกบีบบังคับนั้นร้องทุกข์ เขาร้องขอความช่วยเหลือเนื่องด้วยแขนของผู้มีอํานาจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 10, 'แต่ไม่มีสักคนพูดว่า ‘พระเจ้าผู้ทรงสร้างข้าพเจ้า ผู้ทรงประทานเพลงในเวลากลางคืน ทรงอยู่ที่ไหน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 11, 'ผู้ทรงสอนเรามากกว่าสอนสัตว์แห่งแผ่นดินโลก และทรงกระทําให้เราฉลาดกว่านกในฟ้าอากาศ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 12, 'เขาร้องทุกข์ ณ ที่นั่น แต่ไม่มีผู้ใดตอบเขา เหตุความเย่อหยิ่งของคนชั่ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 13, 'แน่ละ พระเจ้ามิได้ฟังสิ่งไร้สาระ และองค์ผู้ทรงมหิทธิฤทธิ์ก็มิได้ทรงนับถือเสียงนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 14, 'ถึงแม้ท่านว่า ท่านจะไม่เห็นพระองค์ แต่คดีนั้นก็อยู่ต่อพระพักตร์พระองค์ ฉะนั้นท่านจงวางใจในพระองค์อยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 15, 'บัดนี้ เพราะไม่เป็นเช่นนั้น พระพิโรธของพระองค์ได้ลงโทษ แต่พระองค์มิได้สนพระทัยการละเมิดเสียมากมาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 16, 'เพราะฉะนั้นโยบจึงอ้าปากพูดคําลมๆแล้งๆ และทวีคําพูดโดยปราศจากความรู้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 1, 'และเอลีฮูพูดต่อไปด้วยว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 2, '“ขอทนอยู่กับข้าพเจ้าสักหน่อย และข้าพเจ้าจะสําแดงแก่ท่าน เพราะข้าพเจ้ามีบางสิ่งที่จะพูดแทนพระเจ้าอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 3, 'ข้าพเจ้าจะเอาความรู้มาจากที่ไกล และถวายความชอบธรรมแก่ผู้ทรงสร้างข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 4, 'เพราะที่จริงถ้อยคําของข้าพเจ้ามิใช่เท็จ พระองค์ผู้ทรงความรู้รอบคอบสถิตกับท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 5, 'ดูเถิด พระเจ้าทรงอานุภาพ และมิได้ทรงเหยียดหยามผู้ใดเลย พระองค์ทรงอานุภาพในเรื่องกําลังและสติปัญญา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 6, 'พระองค์มิได้สงวนชีวิตคนชั่ว แต่ทรงประทานความยุติธรรมแก่คนยากจน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 7, 'พระองค์มิได้ทรงหันพระเนตรของพระองค์จากคนชอบธรรม แต่กับบรรดากษัตริย์บนพระที่นั่ง พระองค์ทรงตั้งเขาไว้เป็นนิตย์ และเขาก็อยู่ในที่สูง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 8, 'และถ้าเขาถูกจําด้วยพันธนาการ และติดอยู่ในบ่วงแห่งความทุกข์ใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 9, 'พระองค์ก็ทรงสําแดงกิจกรรมของเขาทั้งหลายแก่เขา และการละเมิดของเขาว่าเขาได้กระทํามากเกินไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 10, 'พระองค์ทรงเบิกหูของเขาให้ฟังคําเตือนสอน และทรงบัญชาให้เขากลับจากความชั่วช้าของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 11, 'ถ้าเขาทั้งหลายเชื่อฟัง และปรนนิบัติพระองค์ เขาจะอยู่ครบอายุของเขาด้วยความเจริญรุ่งเรือง และอยู่ครบปีของเขาด้วยความสุขใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 12, 'แต่ถ้าเขาทั้งหลายไม่เชื่อฟัง เขาทั้งหลายจะพินาศด้วยดาบ และตายโดยปราศจากความรู้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 13, 'คนหน้าซื่อใจคดก็สะสมพระพิโรธ เมื่อพระองค์ทรงมัดเขา เขาไม่ร้องให้ช่วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 14, 'เขาตายเมื่อยังหนุ่มอยู่ และชีวิตของเขาอยู่ท่ามกลางผู้เป็นมลทิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 15, 'พระองค์ทรงช่วยคนยากจนให้พ้นด้วยความทุกข์ใจของเขา และทรงให้ความลําเค็ญเบิกหูของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 16, 'เออ พระองค์ทรงชวนท่านให้ออกมาจากความคับใจ มายังที่กว้างที่ไม่มีการบีบ และสิ่งที่วางไว้ในสํารับของท่านก็มีแต่สิ่งอ้วนพี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 17, 'แต่ท่านก็สมกับการพิพากษาคนชั่ว การพิพากษาและความเที่ยงธรรมมาทันจับท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 18, 'เหตุด้วยพระพิโรธ จงระวังเถิด เกรงว่าพระองค์จะเอาท่านไปเสียด้วยการลงโทษ แล้วแม้การไถ่อันยิ่งใหญ่ก็ไม่สามารถช่วยท่านให้พ้นได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 19, 'พระองค์จะสนพระทัยในทรัพย์สมบัติของท่าน หรือทองคํา หรือเรี่ยวแรงทั้งสิ้นหรือ เปล่าเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 20, 'อย่าอาลัยถึงกลางคืน เมื่อชนชาติทั้งหลายถูกตัดขาดในที่ของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 21, 'ระวังให้ดี อย่าหันไปหาความชั่วช้า เพราะท่านเลือกสิ่งนี้มากกว่าเลือกความทุกข์ใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 22, 'ดูเถิด พระเจ้าทรงสําแดงความยิ่งใหญ่ด้วยฤทธานุภาพของพระองค์ ผู้ใดเป็นผู้สั่งสอนเหมือนอย่างพระองค์เล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 23, 'ผู้ใดเป็นผู้บงการมรรคาของพระองค์ หรือผู้ใดจะพูดได้ว่า ‘พระองค์ทรงกระทําความชั่วช้าแล้ว’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 24, 'จงระลึกถึงที่จะยกย่องพระราชกิจของพระองค์ ซึ่งมนุษย์ได้เห็นนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 25, 'มนุษย์ทั้งปวงเพ่งดูสิ่งนั้นอยู่แล้ว มนุษย์เห็นสิ่งนั้นได้แต่ไกล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 26, 'ดูเถิด พระเจ้านั้นใหญ่ยิ่ง และเราก็หาหยั่งรู้ถึงพระองค์ไม่ อายุของพระองค์เป็นสิ่งที่ค้นหากันไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 27, 'เพราะพระองค์ทรงดึงหยดน้ําขึ้นไป ซึ่งตกลงเป็นฝนจากไอน้ําของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 28, 'ซึ่งเมฆก็เทลงมา และหยดลงที่มนุษย์อย่างอุดม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 29, 'เออ มีคนใดเข้าใจการแผ่ของเมฆหรือ และการคะนองแห่งพลับพลาของพระองค์หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 30, 'ดูเถิด พระองค์ทรงกระจายฟ้าแลบออกไปรอบพระองค์และคลุมก้นของทะเล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 31, 'เพราะพระองค์ทรงพิพากษาชนชาติทั้งหลายด้วยสิ่งนี้ พระองค์ประทานอาหารอย่างอุดมสมบูรณ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 32, 'พระองค์ทรงคลุมฟ้าแลบด้วยเมฆ และทรงบัญชาให้เมฆบังฟ้าแลบนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 33, 'เสียงครืนๆของมันประกาศเกี่ยวกับพระองค์ และฝูงสัตว์ก็ประกาศเกี่ยวกับพายุซึ่งจะมาถึง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 1, '“เรื่องนี้กระทําให้หัวใจของข้าพเจ้าสั่นรัว สะทกสะท้านขวัญหนีดีฝ่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 2, 'จงตั้งใจฟังเสียงกัมปนาทของพระองค์ และเสียงกระหึ่มที่ออกมาจากพระโอษฐ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 3, 'พระองค์ทรงปล่อยให้ไปทั่วใต้ฟ้าทั้งสิ้น และฟ้าแลบของพระองค์ไปถึงสุดปลายแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 4, 'พระสุรเสียงของพระองค์ครางกระหึ่มตามไป พระองค์ทรงแผดพระสุรเสียงอันโอฬารึกของพระองค์ พระองค์มิได้ทรงหน่วงเหนี่ยวฟ้าแลบ เมื่อได้ยินพระสุรเสียงของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 5, 'พระเจ้าทรงสําแดงกัมปนาทอย่างประหลาดด้วยพระสุรเสียงของพระองค์ พระองค์ทรงกระทําการใหญ่โตซึ่งเราเข้าใจไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 6, 'เพราะพระองค์ตรัสกับหิมะว่า ‘ตกลงบนแผ่นดินซี’ และในทํานองเดียวกันก็ตรัสกับฝน และกับห่าฝนอันหนักแห่งกําลังของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 7, 'พระองค์ทรงมัดมือของมนุษย์ทุกคน เพื่อทุกคนจะรู้จักพระราชกิจของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 8, 'แล้วสัตว์ป่าจึงเข้าไปสู่รังของมัน และพักอยู่ในถ้ําของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 9, 'ลมหมุนออกมาจากห้องทิศใต้ และความหนาวมาจากลมเหนือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 10, 'พระเจ้าประทานน้ําค้างแข็งด้วยลมหายใจของพระองค์ และน้ํากว้างใหญ่ก็แข็งตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 11, 'เช่นเดียวกันพระองค์ทรงบรรทุกความชุ่มชื้นไว้ที่เมฆทึบ พระองค์ทรงกระจายเมฆแห่งฟ้าแลบออกไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 12, 'มันหันไปๆตามการนําของพระองค์ เพื่อให้มันทําตามที่พระองค์ทรงบัญชามันไว้เหนือผิวพิภพโลกนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 13, 'ไม่ว่าจะเป็นเพื่อการตีสอน หรือเพื่อแผ่นดินของพระองค์หรือเพื่อความเมตตา พระองค์ทรงกระทําให้สิ่งเหล่านี้เกิดขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 14, 'โอ ท่านโยบเจ้าข้า ขอฟังข้อนี้ จงนิ่งพิจารณาการกระทําอันมหัศจรรย์ของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 15, 'ท่านทราบหรือว่าพระเจ้าทรงกําชับมันอย่างไร และกระทําให้ฟ้าแลบแห่งเมฆของพระองค์มีแสง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 16, 'ท่านทราบถึงการทรงตัวของเมฆหรือ เป็นพระราชกิจอันประหลาดของพระองค์ผู้สมบูรณ์ในความรู้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 17, 'ตัวท่าน ผู้ที่เสื้อผ้าของตนร้อนเมื่อแผ่นดินโลกอบอ้าวและชื้นเพราะลมทิศใต้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 18, 'ท่านแผ่ฟ้าออกไปพร้อมกับพระองค์ได้หรือ ให้แข็งอย่างคันฉ่องหลอม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 19, 'จงสอนเรามาว่าเราควรจะทูลพระองค์อย่างไร เพราะความมืดเราจึงร่างสํานวนของเราไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 20, 'จะทูลพระองค์ได้ไหมว่า ข้าพเจ้าอยากจะทูล ถ้าผู้ใดทูล เขาจะต้องถูกกลืนไปหมดเป็นแน่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 21, 'บัดนี้มนุษย์เพ่งดูฟ้าแลบอันสุกใสแห่งเมฆไม่ได้ เมื่อลมผ่านไปกวาดให้กระจ่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 22, 'แสงทองส่องมาจากทิศเหนือ พระเจ้าทรงฉลองพระองค์ด้วยความโอ่อ่าตระการอย่างน่าคร้ามกลัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 23, 'องค์ผู้ทรงมหิทธิฤทธิ์นั้น เราจะค้นพบพระองค์ไม่ได้ พระองค์ใหญ่ยิ่งในเรื่องฤทธานุภาพ ความยุติธรรมและความเที่ยงธรรมอันมากยิ่ง พระองค์จะไม่ทรงฝ่าฝืน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 24, 'เพราะฉะนั้นมนุษย์จึงยําเกรงพระองค์ พระองค์ไม่ทรงนับถือผู้ใดที่มีใจประกอบด้วยสติปัญญา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 1, 'แล้วพระเยโฮวาห์ทรงตอบโยบออกมาจากลมหมุนว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 2, '“นี่ใครหนอที่ให้คําปรึกษามืดมนไปด้วยถ้อยคําอันปราศจากความรู้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 3, 'จงคาดเอวไว้อย่างกับลูกผู้ชายหน่อยซิ เราจะถามเจ้า ขอเจ้าตอบเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 4, 'เมื่อเราวางรากฐานของแผ่นดินโลกนั้น เจ้าอยู่ที่ไหน ถ้าเจ้ามีความเข้าใจก็บอกเรามา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 5, 'ผู้ใดได้กําหนดขนาดให้โลก แน่นอนละ เจ้าต้องรู้ซี หรือใครขึงเชือกวัดบนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 6, 'รากฐานของโลกจมไปอยู่บนอะไร หรือผู้ใดวางศิลามุมเอกของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 7, 'ในเมื่อดาวรุ่งแซ่ซ้องสรรเสริญ และบรรดาบุตรชายทั้งหลายของพระเจ้าโห่ร้องด้วยความชื่นบาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 8, 'หรือผู้ใดเอาประตูปิดทะเลไว้ เมื่อมันระเบิดออกมา ดังออกมาจากครรภ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 9, 'เมื่อเราสร้างเมฆให้เป็นเสื้อ และความมืดทึบเป็นผ้าอ้อมของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 10, 'แล้วกําหนดเขตให้มัน และวางดาลและประตู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 11, 'และกล่าวว่า ‘เจ้าไปได้ไกลแค่นี้แหละ อย่าเลยไปอีก และคลื่นคะนองของเจ้าหยุดเพียงแค่นี้แหละ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 12, 'เจ้าได้บังคับบัญชาอรุณตั้งแต่เจ้าเกิดมา และเป็นเหตุให้อรุโณทัยรู้จักที่ของมันหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 13, 'เพื่อมันจะจับปลายแผ่นดินโลก และสลัดคนชั่วออกไปเสียจากโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 14, 'โลกก็เปลี่ยนไปเหมือนดินเหนียวถูกตราประทับ และทุกสิ่งเด่นออกมาเหมือนเสื้อผ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 15, 'แสงสว่างถูกยึดไว้เสียจากคนชั่วร้าย และแขนของเขาที่เงื้อขึ้นก็ถูกหักเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 16, 'เจ้าเข้าไปในตาน้ําแห่งทะเลแล้วหรือ หรือเดินเข้าไปในซอกมหาสมุทรแล้วหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 17, 'เขาเผยประตูความตายแก่เจ้าแล้วหรือ หรือเจ้าได้เห็นประตูเงามัจจุราชแล้วหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 18, 'เจ้าหยั่งรู้ความกว้างใหญ่ของแผ่นดินโลกหรือ ถ้าเจ้ารู้ทั้งหมดนี้ก็จงบอกมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 19, 'ทางที่จะนําไปสู่สํานักของความสว่างอยู่ที่ไหน และส่วนที่มืด สถานที่นั้นอยู่ที่ไหน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 20, 'เพื่อเจ้าจะได้พามันไปยังแดนของมัน และเพื่อเจ้าจะได้เห็นทางไปบ้านของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 21, 'เจ้าคงรู้เพราะเจ้าเกิดมาแล้วอายุของเจ้าก็มากเหลือหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 22, 'เจ้าเข้าไปในคลังหิมะแล้วหรือ หรือเจ้าเห็นคลังลูกเห็บแล้วหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 23, 'ซึ่งเราสงวนไว้เพื่อเวลายากลําบาก เพื่อวันศึกและสงคราม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 24, 'ทางที่จะไปสู่ที่ซึ่งความสว่างแจกจ่ายออกไปนั้นอยู่ที่ไหน หรือที่ซึ่งลมตะวันออกกระจายไปบนแผ่นดินโลกอยู่ที่ไหน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 25, 'ใครเซาะช่องให้กระแสฝนและทําทางให้ฟ้าผ่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 26, 'ให้นําฝนมาบนแผ่นดินที่ไม่มีคนอยู่ และบนถิ่นทุรกันดารซึ่งไม่มีมนุษย์ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 27, 'เพื่อให้พื้นดินที่รกร้างและว่างเปล่าได้อิ่มเอม และกระทําให้หน่อของต้นอ่อนงอกขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 28, 'ฝนมีพ่อหรือ หรือผู้ใดได้กระทําให้เกิดหยาดน้ําค้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 29, 'น้ําแข็งมาจากครรภ์ของผู้ใด ผู้ใดให้กําเนิดแก่ปุยน้ําค้างแข็งแห่งฟ้าสวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 30, 'น้ําถูกซ่อนไว้เหมือนมีหินปิดบัง และผิวมหาสมุทรแข็งตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 31, 'เจ้ามัดหมู่ดาวลูกไก่ให้เป็นกลุ่มได้หรือ หรือแก้เครื่องผูกหมู่ดาวไถได้หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 32, 'เจ้านําดาวนักษัตรออกมาตามฤดูของมันได้หรือ หรือเจ้านําทางของหมู่ดาวจระเข้และลูกของมันได้ไหม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 33, 'เจ้ารู้กฎของฟ้าสวรรค์หรือเปล่า เจ้าตั้งฟ้าสวรรค์ให้ครอบครองแผ่นดินได้หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 34, 'เจ้าตะเบ็งเสียงไปถึงเมฆได้ไหมล่ะ เพื่อน้ํามากมายจะลงมาคลุมเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 35, 'เจ้าใช้ฟ้าแลบออกไปเพื่อให้มันไปและพูดกับเจ้าว่า ‘เราอยู่ที่นี่’ ได้ไหม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 36, 'ใครให้สติปัญญาภายใน หรือให้ความเข้าใจแก่จิตใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 37, 'ใครจะนับเมฆด้วยสติปัญญาได้ หรือใครจะเอียงถุงน้ําของท้องฟ้าได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 38, 'เมื่อผงคลีแข็งอย่างโลหะหลอม เมื่อก้อนดินเกาะกันแน่นหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 39, 'เจ้าล่าเหยื่อให้สิงโตได้หรือ หรือให้สิงโตหนุ่มที่หิวอิ่มได้ไหมล่ะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 40, 'เมื่อมันหมอบอยู่ในถ้ําของมัน หรือนอนคอยอยู่ในที่กําบัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 41, 'ใครจัดหาเหยื่อให้นกกา เมื่อลูกของมันร้องต่อพระเจ้า และระเหระหนไปเพราะขาดอาหาร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 1, '“เจ้ารู้ไหมว่าเลียงผาตกลูกเมื่อไร เจ้าเคยเฝ้าดูกวางตัวเมียตกลูกหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 2, 'เจ้านับเดือนที่มันท้องครบได้หรือ และเจ้ารู้เวลาเมื่อมันตกลูกไหม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 3, 'คือเมื่อมันฟุบลงตกลูกของมันแล้วก็ตกลูกอ่อนของมันออกมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 4, 'ลูกอ่อนของมันแข็งแรงขึ้น มันเติบโตใหญ่ด้วยมีต้นข้าวกิน มันออกไปแล้วไม่กลับมาหาอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 5, 'ใครปล่อยให้ลาป่าวิ่งกระเจิงไป ใครแก้เชือกผูกลาเปลี่ยว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 6, 'ซึ่งเราได้ให้ถิ่นทุรกันดารเป็นบ้านของมัน และให้ดินแห้งแล้งเป็นที่อาศัยของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 7, 'มันเย้ยเสียงอึกทึกของเมือง มันไม่ได้ยินเสียงของผู้ขับขี่ตะโกนบอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 8, 'มันตระเวนภูเขาอันเป็นลานหญ้าของมัน และมันแสวงหาหญ้าเขียวทุกอย่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 9, 'ม้ายูนิคอนยอมรับใช้เจ้าหรือ มันจะนอนค้างคืนอยู่ที่รางหญ้าของเจ้าหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 10, 'เจ้าเอาเชือกผูกม้ายูนิคอนให้ลากไถได้หรือ หรือมันจะยอมคราดที่ลุ่มตามเจ้าไปหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 11, 'เจ้าจะพึ่งมัน เพราะแรงมันมากได้หรือ หรือจะมอบงานของเจ้าไว้กับมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 12, 'เจ้าไว้ใจว่ามันจะกลับมาและนําข้าวของเจ้ามาที่ลานนวดข้าวหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 13, 'เจ้าให้ปีกอันสวยงามแก่นกยูงหรือ และให้ปีกและขนแก่นกกระจอกเทศหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 14, 'ซึ่งละไข่ของมันไว้กับดินให้มันอบอุ่นอยู่ในดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 15, 'ลืมไปว่าตีนหนึ่งอาจจะเหยียบมันแหลก และสัตว์ป่าทุ่งจะย่ํามัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 16, 'มันรุนแรงต่อลูกอ่อนของมันอย่างกับว่าไม่ใช่ลูกของมัน ถึงมันจะเหนื่อยเปล่า มันก็ไม่กลัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 17, 'เพราะพระเจ้าทรงกระทําให้มันลืมสติปัญญา และมิได้ทรงให้มันมีความเข้าใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 18, 'เมื่อมันเร่งตัวเองให้หนี มันหัวเราะเยาะม้าและคนขี่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 19, 'เจ้าให้พลังแก่ม้าหรือ เจ้าห่มคอของมันด้วยฟ้าร้องหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 20, 'เจ้าทําให้มันกลัวอย่างตั๊กแตนหรือ เสียงหายใจอันดังของมันน่าสะพรึงกลัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 21, 'มันตะกุยไปในหุบเขา และเต้นโลดด้วยกําลังของมัน มันออกไปปะทะคนถืออาวุธ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 22, 'มันหัวเราะเยาะความกลัว และไม่ตกใจ มันไม่หันหนีจากดาบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 23, 'แล่งธนูกวัดแกว่งกระทบมัน ทั้งหอกใหญ่ที่วาววับและโล่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 24, 'มันโกยดินด้วยความดุร้ายและเดือดดาล พอได้ยินเสียงแตร มันยืนนิ่งอยู่ต่อไปไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 25, 'เมื่อเป่าแตรขึ้น มันร้อง ‘ฮีแฮ่’ มันได้กลิ่นสงครามแต่ไกล ทั้งเสียงตะโกนของผู้บังคับบัญชาและเสียงโห่ร้อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 26, 'เหยี่ยวนกเขาโผไปมาด้วยสติปัญญาของเจ้าหรือ และกางปีกของมันตรงไปทางทิศใต้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 27, 'นกอินทรีทะยานขึ้นตามบัญชาของเจ้าหรือ ทั้งทํารังของมันบนที่สูง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 28, 'มันอยู่ที่หน้าผาและทํารังของมันบนชะโงกผาและบนที่เข้มแข็ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 29, 'มันส่ายหาเหยื่อจากที่นั่น ตาของมันเห็นเหยื่อได้แต่ไกล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 30, 'ลูกอ่อนของมันดูดเลือด และมีอะไรถูกฆ่าตายที่ไหน มันอยู่ที่นั่นแหละ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 1, 'และพระเยโฮวาห์ตรัสกับโยบว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 2, '“คนมักติจะโต้แย้งกับองค์ผู้ทรงมหิทธิฤทธิ์หรือ เขาผู้โต้แย้งกับพระเจ้า ขอให้เขาตอบหน่อยเถอะ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 3, 'แล้วโยบทูลตอบพระเยโฮวาห์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 4, '“ดูเถิด ข้าพระองค์นี้ก็ไร้ค่า จะทูลพระองค์ว่ากระไรได้ ข้าพระองค์เอามือปิดปาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 5, 'ข้าพระองค์ได้กราบทูลครั้งหนึ่งแล้ว และจะไม่กราบทูลอีก สองครั้งแล้ว แต่ข้าพระองค์จะไม่ทูลต่อไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 6, 'แล้วพระเยโฮวาห์ทรงตอบโยบออกมาจากลมหมุนว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 7, '“จงคาดเอวไว้อย่างลูกผู้ชายหน่อยซี เราจะถามเจ้า ขอเจ้าตอบเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 8, 'เจ้ายังจะให้เราอยู่ฝ่ายผิดหรือ เจ้าจะหาว่าเราผิด เพื่อเจ้าจะเป็นฝ่ายชอบหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 9, 'เจ้ามีแขนเหมือนพระเจ้าหรือ และเจ้าทําเสียงกัมปนาทเหมือนเสียงของพระองค์ได้หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 10, 'จงเอาความโอ่อ่าตระการและความสง่าผ่าเผยประดับตัว จงเอาสง่าราศีและความสง่างามห่มตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 11, 'เทความกริ้วที่ล้นของเจ้านั้นออกมา จงดูทุกคนที่เย่อหยิ่ง และทําให้เขาตกต่ําลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 12, 'จงดูทุกคนที่เย่อหยิ่งและดึงเขาลงมา และเหยียบคนชั่วไว้ตรงที่ที่เขายืนอยู่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 13, 'ซ่อนเขาไว้ในผงคลีด้วยกัน มัดหน้าของเขาไว้ด้วยกันในที่ลึกลับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 14, 'แล้วเราเองจะยอมรับว่า มือขวาของเจ้าสามารถช่วยเจ้าได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 15, 'ดูเบเฮโมทเถิด ซึ่งเราได้สร้างอย่างที่เราได้สร้างเจ้า มันกินหญ้าเหมือนวัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 16, 'ดูเถิด กําลังของมันอยู่ในเอว และฤทธิ์ของมันอยู่ในกล้ามเนื้อท้อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 17, 'มันขยับหางของมันให้แข็งเหมือนไม้สนสีดาร์ เอ็นโคนขาของมันก็สานเข้าด้วยกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 18, 'กระดูกของมันเหมือนท่อนทองเหลือง และกระดูกของมันเหมือนท่อนเหล็ก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 19, 'มันเป็นพระราชกิจชิ้นที่สําคัญของพระเจ้า ผู้ทรงสร้างมันนําดาบมาให้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 20, 'ภูเขาผลิตอาหารให้มันแน่ เป็นที่ที่สัตว์ป่าทุ่งทุกชนิดเล่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 21, 'มันนอนอยู่ใต้ต้นไม้ที่มีร่มเงา ในเพิงอ้อและในบึง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 22, 'ต้นไม้ที่มีร่มเงาเป็นเงาคลุมมัน ต้นหลิวแห่งธารน้ําล้อมมันไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 23, 'ดูเถิด มันดื่มแม่น้ําจนหมดและไม่รีบหนีไป มันวางใจว่าจะดูดแม่น้ําจอร์แดนเข้าใส่ปากมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 24, 'มันจ้องตาดูแม่น้ํา จมูกมันทะลุผ่านบ่วงทั้งหลายได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 1, '“เจ้าจะลากเลวีอาธานออกมาด้วยเบ็ดได้หรือ หรือจะเอาเชือกกดลิ้นของมันลงได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 2, 'เจ้าเอาเชือกสนตะพายมันได้หรือ หรือเอาหนามเจาะคางมันได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 3, 'มันจะวิงวอนต่อเจ้าเป็นอันมากหรือ มันจะพูดด้วยคําอ่อนหวานกับเจ้าหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 4, 'มันจะทําพันธสัญญากับเจ้า เพื่อเจ้าจะรับมันเป็นบ่าวตลอดไปหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 5, 'เจ้าจะเล่นกับมันเหมือนนก หรือเจ้าจะผูกมันไว้ให้สาวๆของเจ้าเล่นหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 6, 'เพื่อนฝูงจะมาจับและกินมันได้หรือ เขาทั้งหลายจะแบ่งกันท่ามกลางพวกพ่อค้าหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 7, 'เจ้าเอาฉมวกปักหนังของมัน หรือเอาหลาวแทงหัวของมันได้หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 8, 'ลงมือจับมันดู เมื่อคิดถึงการต่อสู้กับมันแล้ว เจ้าจะไม่คิดทําอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 9, 'ดูเถิด ความหวังของคนที่อาจสู้มันนั้นก็เป็นของเปล่า เมื่อเห็นมันเข้าเท่านั้น จะไม่ล้มลงหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 10, 'ไม่มีใครดุพอที่จะไปยั่วเย้ามัน แล้วใครเล่าจะยืนมั่นต่อเราได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 11, 'ใครเล่าที่จะขัดขวางเรา ซึ่งเราจะต้องตอบสนองเขา สิ่งใดๆที่อยู่ใต้ฟ้าสวรรค์ทั้งสิ้นก็เป็นของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 12, 'เราจะไม่งดพูดถึงอวัยวะต่างๆของมัน หรือกําลังอันแข็งกล้าของมัน หรือโครงร่างอันดีของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 13, 'ใครจะถลกเสื้อชั้นนอกของมันออกได้ ใครจะแทงเข้าไปในเสื้อเกราะสองชั้นของมันได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 14, 'ใครจะเปิดประตูหน้าของมันได้ ฟันของมันนั้นน่าสยดสยองโดยรอบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 15, 'เกล็ดของมันอยู่อย่างทะนง แนบตัวมันสนิทเหมือนอย่างตราผนึก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 16, 'มันอยู่ชิดกันมาก ไม่มีลมผ่านเข้าไปได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 17, 'เกล็ดเหล่านั้นต่อซึ่งกันและกัน มันเกาะติดหมด และแยกจากกันไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 18, 'การจามของมันปล่อยแสงสว่างออกมา ตาของมันเหมือนอย่างแสงอรุณรุ่งเช้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 19, 'คบเพลิงออกมาจากปากของมัน ประกายไฟกระโดดออกมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 20, 'ควันออกมาทางรูจมูกของมันอย่างกับมาจากหม้อหรือหม้อขนาดใหญ่ที่เดือดพล่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 21, 'ลมหายใจของมันจุดถ่านลุก เปลวเพลิงออกมาจากปากของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 22, 'กําลังอยู่ในลําคอของมัน และความสยดสยองเต้นอยู่ข้างหน้ามัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 23, 'หลืบเนื้อของมันเกาะติดกัน หล่อติดกันแน่น ทําอะไรมันไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 24, 'หัวใจของมันแข็งอย่างกับหิน เออ แข็งเหมือนอย่างแท่นหินโม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 25, 'เมื่อมันลอยขึ้นมา ผู้มีอานุภาพก็กลัวมัน พอมันแว้ง เขาทั้งหลายก็มีใจฝ่อเสียแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 26, 'ถึงคนใดเอาดาบลองแทงมัน ก็ต่อต้านมันไม่ได้ ไม่ว่าหอก หรือแหลน หรือหอกซัด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 27, 'มันนับเหล็กว่าเป็นฟาง และทองเหลืองว่าเป็นไม้ผุ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 28, 'ลูกธนูทําให้มันหนีไปไม่ได้ หินลูกสลิงก็กลายเป็นตอข้าว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 29, 'ไม้กระบองก็นับเป็นตอข้าวด้วย มันหัวเราะเยาะการซัดหอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 30, 'เบื้องล่างของมันคมอย่างกับเศษหม้อแตก มันเหยียดตัวออกบนเลนเหมือนแหลมคม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 31, 'มันทําให้น้ําลึกเดือดเหมือนหม้อ มันทําให้ทะเลเหมือนหม้อน้ํามันทา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 32, 'มันละทางแวบวาบไว้ข้างหลัง ทําให้ใครๆคิดว่ามหาสมุทรผมหงอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 33, 'บนแผ่นดินโลก ไม่มีอะไรเหมือนมัน เป็นสิ่งที่ถูกสร้างไม่ให้รู้จักความกลัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 34, 'มันเห็นทุกสิ่งที่อยู่สูง มันเป็นกษัตริย์เหนือบรรดาสัตว์ที่สง่า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 1, 'แล้วโยบทูลพระเยโฮวาห์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 2, '“ข้าพระองค์ทราบแล้วว่า พระองค์ทรงกระทําทุกสิ่งได้ และพระประสงค์ของพระองค์จะไม่หดหู่ไปได้เลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 3, '‘นี่ใครหนอที่ซ่อนคําปรึกษาด้วยไร้ความรู้’ เพราะฉะนั้น ข้าพระองค์จึงกล่าวถึงสิ่งที่ข้าพระองค์ไม่เข้าใจ สิ่งที่ประหลาดเกินแก่ข้าพระองค์ ซึ่งข้าพระองค์ไม่ทราบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 4, '‘ฟังซี เราจะพูด เราจะถามเจ้า ขอเจ้าตอบเรา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 5, 'ข้าพระองค์เคยได้ยินถึงพระองค์ด้วยหู แต่บัดนี้ตาของข้าพระองค์เห็นพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 6, 'ฉะนั้นข้าพระองค์จึงเกลียดตนเอง และกลับใจอยู่ในผงคลีและขี้เถ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 7, 'เมื่อพระเยโฮวาห์ตรัสพระวจนะเหล่านี้แก่โยบแล้ว พระเยโฮวาห์ตรัสกับเอลีฟัสชาวเทมานว่า “ความพิโรธของเราพลุ่งขึ้นต่อเจ้า และต่อสหายทั้งสองของเจ้า เพราะเจ้ามิได้พูดถึงเราอย่างที่ถูก ดังโยบผู้รับใช้ของเราได้พูด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 8, 'เพราะฉะนั้นจงเอาวัวผู้เจ็ดตัว และแกะผู้เจ็ดตัว ไปหาโยบผู้รับใช้ของเรา และถวายเครื่องเผาบูชาสําหรับเจ้าทั้งหลาย และโยบผู้รับใช้ของเราจะอธิษฐานเพื่อเจ้า เพราะเราจะยอมรับเขา เกรงว่าเรากระทํากับเจ้าตามความโง่ของเจ้า เพราะเจ้าทั้งหลายมิได้พูดถึงเราอย่างที่ถูก ดังโยบผู้รับใช้ของเราได้พูด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 9, 'ฝ่ายเอลีฟัสชาวเทมาน และบิลดัดคนชูอาห์ และโศฟาร์ชาวนาอามาห์ ได้ไปกระทําตามที่พระเยโฮวาห์ตรัสสั่ง และพระเยโฮวาห์ทรงยอมรับโยบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 10, 'และพระเยโฮวาห์ทรงให้โยบกลับสู่สภาพดี เมื่อท่านอธิษฐานเผื่อสหายของท่าน และพระเยโฮวาห์ประทานให้โยบมีมากเป็นสองเท่าของที่มีอยู่ก่อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 11, 'และบรรดาพี่น้องชายหญิงของท่าน และบรรดาผู้ที่รู้จักท่านมาก่อนได้มาหาท่าน และรับประทานอาหารกับท่านในบ้านของท่าน และเขาทั้งหลายสําแดงความเห็นอกเห็นใจและเล้าโลมท่าน ด้วยเรื่องเหตุร้ายทั้งสิ้นซึ่งพระเยโฮวาห์ทรงนํามาเหนือท่าน และต่างก็ให้เงินแผ่นหนึ่งกับตุ้มหูทองคําอันหนึ่งแก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 12, 'และพระเยโฮวาห์ทรงอํานวยพระพรชีวิตบั้นปลายของโยบมากยิ่งกว่าข้างต้นของท่าน และท่านมีแกะหนึ่งหมื่นสี่พัน อูฐหกพัน วัวผู้พันคู่ และลาตัวเมียหนึ่งพัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 13, 'ท่านมีบุตรชายเจ็ดคน และบุตรสาวสามคนด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 14, 'และท่านเรียกชื่อคนแรกว่า เยมีมาห์ และชื่อคนที่สอง เคสิยาห์ และชื่อคนที่สาม เคเรนหัปปุค');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 15, 'และในแผ่นดินนั้นทั้งสิ้นไม่มีหญิงใดงดงามเท่าบรรดาบุตรสาวของโยบ และบิดาของเขาได้ให้มรดกแก่เธอพร้อมกับพวกพี่ชายและน้องชายของเธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 16, 'ต่อจากนี้ไป โยบมีชีวิตอยู่อีกหนึ่งร้อยสี่สิบปี และได้เห็นบุตรชายของท่าน หลานเหลนของท่านสี่ชั่วอายุ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 17, 'และโยบก็สิ้นชีวิตเป็นคนแก่หง่อมทีเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 1, 'บุคคลผู้ไม่ดําเนินตามคําแนะนําของคนอธรรม หรือยืนอยู่ในทางของคนบาป หรือนั่งอยู่ในที่นั่งของคนที่ชอบเยาะเย้ย ผู้นั้นก็เป็นสุข');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 2, 'แต่ความปีติยินดีของผู้นั้นอยู่ในพระราชบัญญัติของพระเยโฮวาห์ เขาไตร่ตรองถึงพระราชบัญญัติของพระองค์ทั้งกลางวันและกลางคืน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 3, 'เขาจะเป็นเช่นต้นไม้ที่ปลูกไว้ริมธารน้ํา ซึ่งเกิดผลตามฤดูกาล และใบก็จะไม่เหี่ยวแห้ง การทุกอย่างซึ่งเขากระทําก็จะจําเริญขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 4, 'คนอธรรมไม่เป็นเช่นนั้น แต่เป็นเหมือนแกลบซึ่งลมพัดกระจายไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 5, 'เหตุฉะนั้นคนอธรรมจะไม่ยั่งยืนอยู่ได้เมื่อถึงการพิพากษา หรือคนบาปไม่ยืนยงในที่ชุมนุมของคนชอบธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 6, 'เพราะพระเยโฮวาห์ทรงทราบทางของคนชอบธรรม แต่ทางของคนอธรรมจะพินาศไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 1, 'เหตุใดชนต่างชาติจึงกระทําโกลาหลขึ้น และชนชาติทั้งหลายคิดอ่านในการที่ไร้ประโยชน์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 2, 'บรรดากษัตริย์แห่งแผ่นดินโลกตั้งตนเองขึ้น และนักปกครองปรึกษากันต่อสู้พระเยโฮวาห์และผู้รับการเจิมของพระองค์ กล่าวว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 3, '“ให้เราระเบิดสายแอกของเขาให้ขาดสะบั้น และขจัดบังเหียนของเขาให้พ้นจากเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 4, 'พระองค์ผู้ประทับในสวรรค์จะทรงพระสรวล องค์พระผู้เป็นเจ้าจะทรงเย้ยหยันเขาเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 5, 'แล้วพระองค์จะตรัสกับเขาทั้งหลายด้วยพระพิโรธ และกระทําให้เขาสยดสยองด้วยความกริ้วของพระองค์ ตรัสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 6, '“เราได้ตั้งกษัตริย์ของเราไว้แล้วบนศิโยน ภูเขาอันบริสุทธิ์ของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 7, 'ข้าพเจ้าจะประกาศพระดํารัสของพระองค์ พระเยโฮวาห์รับสั่งกับข้าพเจ้าว่า “เจ้าเป็นบุตรของเรา วันนี้เราได้ให้กําเนิดแก่เจ้าแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 8, 'จงขอจากเราเถิด และเราจะมอบบรรดาประชาชาติให้เป็นมรดกของเจ้า ตลอดทั้งแผ่นดินโลกให้เป็นกรรมสิทธิ์ของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 9, 'เจ้าจะตีเขาให้แตกด้วยคทาเหล็ก และฟาดให้แหลกเป็นชิ้นๆดุจภาชนะของช่างหม้อ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 10, 'เพราะฉะนั้นบัดนี้ โอ ข้าแต่กษัตริย์ทั้งหลาย จงฉลาดเถิด ข้าแต่นักปกครองแห่งแผ่นดินโลก จงรับคําเตือนเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 11, 'จงปรนนิบัติพระเยโฮวาห์ด้วยความยําเกรง และจงเกษมเปรมปรีดิ์ด้วยตัวสั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 12, 'จงจุบพระบุตรเถิดเกลือกว่าพระองค์จะทรงพระพิโรธ และเจ้าต้องพินาศจากทางนั้น เมื่อพระพิโรธของพระองค์นั้นเริ่มจุดให้ลุกแต่น้อย ความสุขเป็นของคนทั้งหลายผู้วางใจในพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 1, 'เพลงสดุดีของดาวิด เมื่อเสด็จหนีจากอับซาโลมโอรสของพระองค์ข้าแต่พระเยโฮวาห์ ศัตรูของข้าพระองค์ทวีมากขึ้นเหลือเกิน คู่อริมากมายเหล่านี้กําลังลุกขึ้นต่อสู้ข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 2, 'มีคนเป็นอันมากกําลังกล่าวถึงจิตวิญญาณข้าพระองค์ว่า “ในพระเจ้าไม่มีทางรอดสําหรับเขา” เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 3, 'โอ ข้าแต่พระเยโฮวาห์ พระองค์ทรงเป็นโล่ล้อมรอบตัวข้าพระองค์ พระองค์ทรงเป็นสง่าราศีของข้าพระองค์ และทรงเป็นผู้ชูศีรษะของข้าพระองค์ไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 4, 'ข้าพเจ้าร้องทูลพระเยโฮวาห์ด้วยเสียงของข้าพเจ้า และพระองค์ทรงฟังข้าพเจ้าจากภูเขาอันบริสุทธิ์ของพระองค์ เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 5, 'ข้าพเจ้านอนลงและหลับไป ข้าพเจ้ากลับตื่นขึ้น เพราะพระเยโฮวาห์ทรงอุปถัมภ์ข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 6, 'ข้าพเจ้าไม่กลัวคนเป็นหมื่นๆ ซึ่งตั้งตนต่อสู้ข้าพเจ้าอยู่รอบด้าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 7, 'โอ ข้าแต่พระเยโฮวาห์ โปรดทรงลุกขึ้น โอ ข้าแต่พระเจ้าของข้าพระองค์ โปรดทรงช่วยข้าพระองค์ให้พ้น เพราะพระองค์ทรงตบแก้มศัตรูทั้งหลายของข้าพระองค์ และทรงทุบฟันของคนอธรรมทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 8, 'การช่วยให้รอดเป็นของพระเยโฮวาห์ ขอพระพรของพระองค์หลั่งลงเหนือประชาชนของพระองค์เถิด เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 1, 'ถึงหัวหน้านักร้องใช้เครื่องสาย เพลงสดุดีของดาวิดโอ ข้าแต่พระเจ้าแห่งความชอบธรรมของข้าพระองค์ ขอทรงโปรดสดับเมื่อข้าพระองค์ร้องทูล เมื่อข้าพระองค์จนตรอก พระองค์ทรงประทานช่องทางให้ ขอทรงเมตตาแก่ข้าพระองค์และทรงฟังคําอธิษฐานของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 2, 'โอ บุตรทั้งหลายของมนุษย์เอ๋ย ท่านจะทําให้เกียรติของข้าพเจ้ากลายเป็นความอับอายอีกนานเท่าใด ท่านจะรักสิ่งไร้สาระ และแสวงหาการมุสาอีกนานเท่าใด เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 3, 'จงทราบเถิดว่า พระเยโฮวาห์ทรงแยกคนที่ตามทางของพระเจ้าไว้สําหรับพระองค์ พระเยโฮวาห์จะทรงสดับเมื่อข้าพเจ้าทูลพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 4, 'จงยืนตะลึงพรึงเพริด และอย่าทําบาป จงคํานึงในใจเวลาอยู่บนที่นอนและสงบอยู่ เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 5, 'จงถวายเครื่องสัตวบูชาแห่งความชอบธรรมและวางใจในพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 6, 'มีคนเป็นอันมากกล่าวว่า “ผู้ใดจะแสดงสิ่งดีๆให้เราได้เห็นบ้าง ข้าแต่พระเยโฮวาห์ ขอทรงเปล่งแสงสว่างจากสีพระพักตร์ของพระองค์มาเหนือข้าพระองค์ทั้งหลาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 7, 'พระองค์ได้ประทานความชื่นบานให้แก่จิตใจของข้าพระองค์มากกว่าเมื่อพวกเขาได้ข้าวและน้ําองุ่นมากมาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 8, 'ข้าพระองค์จะเอนกายลงนอนหลับในความสันติ ข้าแต่พระเยโฮวาห์ เพราะพระองค์เท่านั้นที่ทรงกระทําให้ข้าพระองค์อาศัยอยู่อย่างปลอดภัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 1, 'ถึงหัวหน้านักร้องใช้เครื่องเป่า เพลงสดุดีของดาวิดโอ ข้าแต่พระเยโฮวาห์ ขอทรงเงี่ยพระกรรณสดับถ้อยคําของข้าพระองค์ ขอทรงพิจารณาการไตร่ตรองของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 2, 'ข้าแต่พระบรมกษัตริย์และพระเจ้าของข้าพระองค์ ขอทรงฟังเสียงร้องทูลของข้าพระองค์ เพราะข้าพระองค์จะอธิษฐานทูลต่อพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 3, 'โอ ข้าแต่พระเยโฮวาห์ ในเวลาเช้าพระองค์จะทรงสดับเสียงของข้าพระองค์ ในเวลาเช้าข้าพระองค์จะเตรียมคําอธิษฐานทูลต่อพระองค์และเฝ้าคอยดูอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 4, 'ด้วยว่าพระองค์มิได้ทรงเป็นพระเจ้าผู้ปีติยินดีในความชั่ว ความชั่วร้ายจะไม่อาศัยอยู่กับพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 5, 'คนโง่เขลาจะไม่ยืนอยู่เฉพาะพระเนตรของพระองค์ พระองค์ทรงเกลียดชังผู้กระทําความชั่วช้าทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 6, 'พระองค์จะทรงทําลายผู้ที่พูดมุสา พระเยโฮวาห์จะทรงสะอิดสะเอียนต่อผู้กระหายเลือดและคนหลอกลวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 7, 'แต่โดยความเมตตาอันบริบูรณ์ของพระองค์ข้าพระองค์จะเข้าไปในพระนิเวศของพระองค์ ข้าพระองค์จะนมัสการตรงต่อพระวิหารอันบริสุทธิ์ของพระองค์ ด้วยความยําเกรงพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 8, 'โอ ข้าแต่พระเยโฮวาห์ เนื่องด้วยพวกศัตรูของข้าพระองค์ ขอทรงนําข้าพระองค์ไปโดยความชอบธรรมของพระองค์ ขอทรงโปรดทําทางซึ่งข้าพระองค์เดินนั้นให้ราบรื่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 9, 'เพราะในปากของเขาเหล่านั้นไม่มีความสัตย์ซื่อ จิตใจของเขาก็คือความชั่วร้าย ลําคอของเขาคือหลุมฝังศพที่เปิดอยู่ เขาประจบสอพลอด้วยลิ้นของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 10, 'โอ ข้าแต่พระเจ้า โปรดทําลายพวกเขา และให้เขาทั้งหลายล้มลงด้วยความคิดเห็นของตนเอง เหตุการละเมิดเป็นอันมากนั้นขอทรงขับไล่เขาออกไปเนื่องจากเขาทั้งหลายได้กบฏต่อพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 11, 'แต่ให้คนทั้งปวงที่วางใจในพระองค์นั้นเปรมปรีดิ์ ให้เขาโห่ร้องด้วยความชื่นบานอยู่เสมอ เพราะพระองค์ทรงป้องกันเขาไว้ ให้คนที่รักพระนามของพระองค์ปรีดาปราโมทย์อยู่ในพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 12, 'ข้าแต่พระเยโฮวาห์ เพราะพระองค์จะทรงอํานวยพระพรแก่คนชอบธรรม พระองค์จะทรงคุ้มครองเขาไว้ด้วยความโปรดปรานประดุจเป็นโล่ป้องกันเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 1, 'ถึงหัวหน้านักร้องใช้เครื่องสายตามทํานองเชมินิท เพลงสดุดีของดาวิดโอ ข้าแต่พระเยโฮวาห์ ขออย่าทรงขนาบข้าพระองค์เมื่อทรงโกรธ และขออย่าทรงลงทัณฑ์ข้าพระองค์ด้วยพระพิโรธของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 2, 'โอ ข้าแต่พระเยโฮวาห์ ขอทรงพระกรุณาแก่ข้าพระองค์เพราะข้าพระองค์อ่อนระโหยโรยแรง โอ ข้าแต่พระเยโฮวาห์ ขอทรงรักษาข้าพระองค์เพราะกระดูกของข้าพระองค์ทุกข์ยากลําบากนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 3, 'ทั้งจิตใจของข้าพระองค์ก็ทุกข์ยากลําบากอย่างยิ่ง โอ ข้าแต่พระเยโฮวาห์ อีกนานสักเท่าใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 4, 'โอ ข้าแต่พระเยโฮวาห์ ขอทรงหันมาช่วยชีวิตของข้าพระองค์ให้พ้นด้วยเถิด โอ ขอทรงช่วยข้าพระองค์ให้รอดเพราะเห็นแก่ความเมตตาของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 5, 'เพราะในความตาย ไม่มีการระลึกถึงพระองค์ ในแดนผู้ตายใครเล่าจะโมทนาพระคุณของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 6, 'ข้าพระองค์อ่อนเปลี้ยด้วยการคร่ําครวญ และหลั่งน้ําตาท่วมที่นอนตลอดทั้งคืน ที่เอนกายก็ชุ่มโชกไปด้วยน้ําตาของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 7, 'ตาของข้าพระองค์ทรุดโทรมไปเพราะความทุกข์ใจ มันอ่อนเพลียลงเพราะคู่อริทั้งปวงของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 8, 'บรรดาเจ้าผู้กระทําความชั่วช้าจงพรากไปจากข้า เพราะพระเยโฮวาห์ทรงสดับเสียงร้องไห้ของข้าแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 9, 'พระเยโฮวาห์ทรงสดับคําวิงวอนของข้า พระเยโฮวาห์จะทรงรับคําอธิษฐานของข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 10, 'ขอให้ศัตรูทั้งสิ้นของข้าได้อายและลําบากยากนัก ขอให้เขาทั้งหลายหันกลับและได้รับความอับอายในพริบตาเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 1, 'ชิกกาโยนของดาวิดซึ่งท่านร้องถวายพระเยโฮวาห์เกี่ยวกับคําพูดของคูชคนเบนยามินโอ ข้าแต่พระเยโฮวาห์พระเจ้าของข้าพระองค์ ข้าพระองค์วางใจอยู่ในพระองค์ ขอทรงช่วยข้าพระองค์ให้พ้นภัยจากผู้ข่มเหงทั้งมวล ขอทรงช่วยข้าพระองค์ให้พ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 2, 'เกรงว่าเขาจะฉีกจิตวิญญาณข้าพระองค์เสียอย่างสิงโต และฉีกจิตวิญญาณนั้นออกเป็นชิ้นๆ โดยไม่มีผู้ใดช่วยได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 3, 'โอ ข้าแต่พระเยโฮวาห์พระเจ้าของข้าพระองค์ ถ้าข้าพระองค์กระทําเช่นนี้ คือถ้ามีความชั่วช้าในมือของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 4, 'ถ้าข้าพระองค์ตอบแทนความชั่วแก่ผู้ที่อยู่อย่างสันติกับข้าพระองค์ (แต่ผู้ที่เป็นศัตรูด้วยปราศจากเหตุ ข้าพระองค์เคยช่วยผู้นั้นให้รอดพ้นไป)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 5, 'ก็ขอให้ศัตรูข่มเหงจิตวิญญาณข้าพระองค์ทัน และให้เขาเหยียบย่ําชีวิตข้าพระองค์ลงถึงดิน และวางเกียรติยศของข้าพระองค์ไว้ในผงคลี เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 6, 'โอ ข้าแต่พระเยโฮวาห์ ขอพระองค์ทรงลุกขึ้นด้วยพระพิโรธของพระองค์ ขอทรงขึ้นสู้ความเกรี้ยวกราดของศัตรูของข้าพระองค์ ขอทรงตื่นขึ้นเพื่อทําการพิพากษาที่พระองค์ทรงกําหนดแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 7, 'ดังนั้นชุมนุมชนชาติทั้งหลายจะมาอยู่รอบพระองค์ เพราะเห็นแก่ชุมนุมนั้นขอทรงกลับไปประทับบนที่สูง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 8, 'พระเยโฮวาห์จะทรงพิพากษาชนชาติทั้งหลาย โอ ข้าแต่พระเยโฮวาห์ ขอทรงพิพากษาข้าพระองค์ตามความชอบธรรมของข้าพระองค์ และตามความสัตย์สุจริตซึ่งมีอยู่ในข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 9, 'โอ ขอให้ความชั่วร้ายของคนชั่วจงมาถึงที่สิ้นสุด แต่ขอทรงสถาปนาคนชอบธรรมขึ้น เพราะพระเจ้าผู้ทรงชอบธรรมทรงทดลองความคิดและจิตใจทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 10, 'การป้องกันข้าพเจ้าอยู่กับพระเจ้า ผู้ทรงช่วยคนใจเที่ยงตรงให้รอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 11, 'พระเจ้าทรงพิพากษาคนชอบธรรม และพระเจ้าทรงพระพิโรธต่อคนชั่วทุกวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 12, 'ถ้ามนุษย์คนใดไม่กลับใจ พระองค์จะทรงลับคมดาบของพระองค์ พระองค์ทรงโก่งธนูเตรียมพร้อมไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 13, 'พระองค์ทรงเตรียมอาวุธแห่งความตาย พระองค์ทรงกระทําให้ลูกธนูของพระองค์ต่อสู้ผู้ข่มเหงทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 14, 'ดูเถิด คนชั่วก่อความชั่วช้าขึ้นแล้ว กําลังท้องความชั่วช้า และคลอดการมุสาออกมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 15, 'เขาขุดหลุมพรางไว้ และตกลงไปในหลุมที่เขาทําไว้นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 16, 'ความชั่วช้าของเขาจะกลับมาสุมศีรษะเขา และความทารุณของเขาจะลงมาบนกบาลของเขาเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 17, 'ข้าพเจ้าจะสรรเสริญพระเยโฮวาห์เนื่องด้วยความชอบธรรมของพระองค์ และข้าพเจ้าจะร้องเพลงสรรเสริญพระนามของพระเยโฮวาห์ผู้สูงสุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 1, 'ถึงหัวหน้านักร้องตามทํานองกิททีธ เพลงสดุดีของดาวิดโอ ข้าแต่พระเยโฮวาห์คือองค์พระผู้เป็นเจ้าของบรรดาข้าพระองค์ พระนามของพระองค์สูงส่งยิ่งนักทั่วทั้งแผ่นดินโลก พระองค์ผู้ทรงตั้งสง่าราศีของพระองค์ไว้เหนือฟ้าสวรรค์ทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 2, 'จากปากของเด็กอ่อนและเด็กที่ยังดูดนม พระองค์ทรงตั้งกําลังเพราะบรรดาคู่อริของพระองค์ เพื่อระงับยับยั้งศัตรูและผู้กระทําการแก้แค้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 3, 'เมื่อข้าพระองค์พิจารณาดูฟ้าสวรรค์อันเป็นผลงานแห่งนิ้วพระหัตถ์ของพระองค์ ดวงจันทร์และดวงดาวซึ่งพระองค์ได้ทรงสถาปนาไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 4, 'มนุษย์เป็นผู้ใดเล่าซึ่งพระองค์ทรงระลึกถึงเขา และบุตรมนุษย์เป็นผู้ใดซึ่งพระองค์ทรงเยี่ยมเยียนเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 5, 'เพราะพระองค์ทรงทําให้เขาต่ํากว่าพวกทูตสวรรค์แต่หน่อยเดียว และทรงประทานสง่าราศีกับเกียรติเป็นมงกุฎให้แก่เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 6, 'พระองค์ทรงมอบอํานาจให้ครอบครองบรรดาพระหัตถกิจของพระองค์ พระองค์ทรงให้สิ่งทั้งปวงอยู่ใต้ฝ่าเท้าของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 7, 'คือฝูงแกะและฝูงวัวทั้งสิ้นทั้งสัตว์ป่าด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 8, 'ตลอดทั้งนกในอากาศ ปลาในทะเล และอะไรต่างๆที่ไปมาอยู่ตามทะเล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 9, 'โอ ข้าแต่พระเยโฮวาห์คือองค์พระผู้เป็นเจ้าของบรรดาข้าพระองค์ พระนามของพระองค์สูงส่งยิ่งนักทั่วทั้งแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 1, 'ถึงหัวหน้านักร้องตามทํานองมุธลับเบน เพลงสดุดีของดาวิดโอ ข้าแต่พระเยโฮวาห์ ข้าพระองค์จะสรรเสริญพระองค์ด้วยสิ้นสุดใจของข้าพระองค์ ข้าพระองค์จะบอกถึงการมหัศจรรย์ทั้งสิ้นของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 2, 'ข้าพระองค์จะยินดีและปลาบปลื้มใจในพระองค์ โอ ข้าแต่องค์ผู้สูงสุด ข้าพระองค์จะร้องเพลงสรรเสริญพระนามของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 3, 'เมื่อพวกศัตรูของข้าพระองค์หันกลับ เขาทั้งหลายก็สะดุดและพินาศไปต่อเบื้องพระพักตร์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 4, 'เพราะพระองค์ทรงให้ความยุติธรรมและความเที่ยงตรงแก่ข้าพระองค์ พระองค์ประทับบนพระที่นั่งและประทานการพิพากษาอันชอบธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 5, 'พระองค์ได้ทรงขนาบบรรดาประชาชาติ และทรงทําลายคนชั่ว แล้วทรงลบชื่อของเขาออกเสียเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 6, 'โอ ศัตรูเอ๋ย ความพินาศของเจ้าได้สําเร็จเป็นนิตย์ พระองค์ทรงทําลายบรรดาหัวเมืองของเขา และที่ระลึกของเขาก็วอดวายพร้อมกับเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 7, 'แต่พระเยโฮวาห์จะทรงยืนยงอยู่เป็นนิตย์ พระองค์ทรงตระเตรียมบัลลังก์ของพระองค์เพื่อการพิพากษา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 8, 'พระองค์จะทรงพิพากษาโลกด้วยความชอบธรรม พระองค์จะทรงพิพากษาบรรดาประชาชาติด้วยความเที่ยงธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 9, 'พระเยโฮวาห์จะทรงเป็นที่ลี้ภัยของคนที่ถูกกดขี่ ทรงเป็นที่ลี้ภัยในเวลายากลําบาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 10, 'บรรดาผู้ที่รู้จักพระนามของพระองค์ก็จะวางใจในพระองค์ ข้าแต่พระเยโฮวาห์ เพราะว่าพระองค์มิได้ทรงทอดทิ้งบรรดาผู้ที่เสาะแสวงหาพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 11, 'จงร้องเพลงสรรเสริญพระเยโฮวาห์ ผู้ซึ่งประทับในศิโยน จงบอกเล่าถึงพระราชกิจของพระองค์ในท่ามกลางชนชาติทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 12, 'เมื่อพระองค์ทรงไต่สวนเรื่องโลหิต พระองค์ทรงจําเขาทั้งหลายไว้ พระองค์มิได้ทรงลืมคําร้องทุกข์ของผู้ถ่อมตัวลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 13, 'โอ ข้าแต่พระเยโฮวาห์ ขอทรงพระกรุณาแก่ข้าพระองค์ ขอทรงทอดพระเนตรว่าข้าพระองค์ต้องทนทุกข์ทรมานเพราะคนที่เกลียดชังข้าพระองค์เพียงใด ข้าแต่พระองค์ ผู้ทรงยกข้าพระองค์ขึ้นจากประตูของความตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 14, 'เพื่อข้าพระองค์จะกล่าวบรรดาคําสรรเสริญพระองค์ที่ในประตูทั้งหลายแห่งธิดาศิโยน ข้าพระองค์จะเปรมปรีดิ์ในการช่วยให้รอดของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 15, 'บรรดาประชาชาติได้จมลงในหลุมซึ่งเขาทําไว้ และเท้าของเขาติดตาข่ายซึ่งเขาเองซ่อนดักไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 16, 'พระเยโฮวาห์ทรงเผยพระองค์ให้ปรากฏแจ้งด้วยการพิพากษาซึ่งพระองค์ได้ทรงกระทํา คนชั่วถูกดักด้วยกิจการที่ทําด้วยมือของเขาเอง ฮิกเกอัน เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 17, 'คนชั่วจะต้องถอยไปสู่นรก คือประชาชาติทั้งมวลที่ลืมพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 18, 'เพราะพระองค์จะไม่ทรงลืมคนขัดสนเสมอไป และความหวังของคนยากจนจะไม่พินาศไปเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 19, 'โอ ข้าแต่พระเยโฮวาห์ ขอทรงลุกขึ้น อย่าให้มนุษย์มีชัยได้ แต่ให้บรรดาประชาชาติถูกพิพากษาในสายพระเนตรของพระองค์ทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 20, 'โอ ข้าแต่พระเยโฮวาห์ ขอทรงให้เขายําเกรง และให้บรรดาประชาชาติทราบว่า เขาทั้งหลายเป็นเพียงมนุษย์เท่านั้น เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 1, 'โอ ข้าแต่พระเยโฮวาห์ ไฉนพระองค์ประทับยืนอยู่ห่างไกล ไฉนพระองค์ทรงซ่อนพระองค์เสียในยามยากลําบาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 2, 'คนชั่วข่มเหงคนยากจนอย่างทะนงองอาจ ขอให้เขาติดกับบ่วงแร้วแห่งอุบายที่เขาคิดขึ้นนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 3, 'เพราะคนชั่วอวดถึงสิ่งที่ใจเขาอยากได้นั้น และอวยพรคนที่โลภ ผู้ซึ่งพระเยโฮวาห์ทรงเกลียดชัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 4, 'เพราะคนชั่วนั้นด้วยสีหน้าที่เย่อหยิ่งยโสจะไม่แสวงหาพระเจ้า พระเจ้ามิได้อยู่ในความคิดทั้งสิ้นของเขาเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 5, 'วิธีการของคนชั่วร้ายกาจอยู่ทุกเวลา การพิพากษาของพระองค์อยู่สูงพ้นสายตาของเขา เขาพ่นความร้ายใส่บรรดาคู่อริของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 6, 'โดยคิดในใจของเขาว่า “ข้าจะไม่หวั่นไหว เพราะข้าจะไม่พบความยากลําบากเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 7, 'การแช่งด่า การล่อลวง และการฉ้อฉลอยู่เต็มปากของเขา ความชั่วร้ายและความเลวทรามอยู่ใต้ลิ้นของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 8, 'เขานั่งซุ่มคอยดักทําร้ายอยู่ตามชนบท และกระทําฆาตกรรมคนไร้ผิดเสียในที่เร้นลับ ตาของเขาสอดหาคนยากจน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 9, 'เขาซุ่มอยู่ในที่ลับเหมือนสิงโตอยู่ในที่กําบัง เขาซุ่มอยู่เพื่อจับคนยากจน แล้วเขาฉุดลากคนยากจนมาด้วยตาข่ายของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 10, 'เขาหมอบลงและย่อตัวลง เพื่อคนยากจนจะล้มลงด้วยพวกที่แข็งแรงของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 11, 'เขาคิดในใจว่า “พระเจ้าลืมแล้ว พระองค์ทรงซ่อนพระพักตร์และจะไม่ทรงเห็นเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 12, 'โอ ข้าแต่พระเยโฮวาห์ ขอทรงลุกขึ้น โอ ข้าแต่พระเจ้า ขอทรงชูพระหัตถ์ของพระองค์ขึ้น ขออย่าทรงลืมคนที่ถ่อมตัวลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 13, 'ไฉนคนชั่วจึงประณามพระเจ้า และกล่าวในใจของตนเองว่า “พระองค์จะไม่ทรงเอาเรื่องเอาราว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 14, 'พระองค์ทรงเห็น เออ พระองค์ทรงพิเคราะห์ความยากลําบากและความโกรธเคืองแล้ว เพื่อพระองค์จะได้ทรงดําเนินคดีด้วยพระหัตถ์ของพระองค์ คนยากจนมอบตัวไว้กับพระองค์ พระองค์ทรงเป็นผู้ช่วยคนกําพร้าพ่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 15, 'ขอพระองค์ทรงหักแขนของคนชั่วและคนกระทําชั่ว ขอทรงค้นความชั่วของเขาออกมาจนหมดสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 16, 'พระเยโฮวาห์ทรงเป็นพระมหากษัตริย์อยู่เป็นนิตย์นิรันดร์ บรรดาประชาชาติจะพินาศไปจากแผ่นดินของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 17, 'ข้าแต่พระเยโฮวาห์ พระองค์ทรงสดับฟังความปรารถนาของคนที่ถ่อมตัวลง จะทรงเสริมกําลังใจเขา และพระองค์จะทรงเงี่ยพระกรรณสดับฟังถ้อยคําของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 18, 'เพื่อประทานความยุติธรรมแก่คนกําพร้าพ่อและคนถูกบีบบังคับ เพื่อมนุษย์บนแผ่นดินโลกจะไม่บีบบังคับเขาอีกต่อไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 1, 'ถึงหัวหน้านักร้อง เพลงสดุดีของดาวิดข้าพเจ้าวางใจในพระเยโฮวาห์ ท่านจะพูดกับจิตใจข้าพเจ้าอย่างไรว่า “จงหนีไปที่ภูเขาเหมือนนก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 2, 'เพราะดูเถิด คนชั่วโก่งธนูและเอาลูกธนูพาดสายไว้แล้ว เพื่อจะยิงเข้าไปอย่างลับๆให้ถูกคนใจเที่ยงธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 3, 'ถ้ารากฐานถูกทําลายเสียแล้ว คนชอบธรรมจะทําอะไรได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 4, 'พระเยโฮวาห์ทรงสถิตในพระวิหารอันบริสุทธิ์ของพระองค์ พระที่นั่งของพระเยโฮวาห์อยู่บนฟ้าสวรรค์ พระเนตรของพระองค์มองและหนังตาของพระองค์ทดสอบบุตรทั้งหลายของมนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 5, 'พระเยโฮวาห์ทรงทดสอบคนชอบธรรม แต่วิญญาณของพระองค์ทรงเกลียดชังคนชั่วและผู้ที่รักความทารุณโหดร้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 6, 'พระองค์จะทรงเทบ่วงแร้วต่างๆ เพลิงและไฟกํามะถัน และลมที่แผดเผาใส่คนชั่ว นี้แหละจะเป็นส่วนถ้วยของเขาเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 7, 'เพราะพระเยโฮวาห์ผู้ชอบธรรมทรงรักความชอบธรรม พระพักตร์ของพระองค์ทอดพระเนตรคนเที่ยงตรง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 1, 'ถึงหัวหน้านักร้องตามทํานองเชมินิท เพลงสดุดีของดาวิดข้าแต่พระเยโฮวาห์ ขอทรงโปรดช่วยเพราะคนที่ตามทางของพระเจ้าไม่มีอีกแล้ว และคนสุจริตได้อันตรธานไปจากบุตรทั้งหลายของมนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 2, 'ทุกคนกล่าวคําไร้สาระต่อเพื่อนบ้านของตน เขาทั้งหลายพูดด้วยริมฝีปากที่ป้อยอและสองใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 3, 'พระเยโฮวาห์จะทรงตัดริมฝีปากที่ป้อยอออกเสียสิ้น และลิ้นที่พูดวาจาเย่อหยิ่งนั้นด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 4, 'คือบรรดาผู้ที่กล่าวว่า “เราจะชนะด้วยลิ้นของเรา ริมฝีปากของเราเป็นฝ่ายเรา ใครจะเป็นนายเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 5, 'พระเยโฮวาห์ตรัสว่า “เราจะลุกขึ้นเดี๋ยวนี้ เพราะคนยากจนถูกบีบบังคับ และคนขัดสนคร่ําครวญ เราจะจัดเขาไว้ในที่ปลอดภัยจากคนที่พ่นความร้ายใส่เขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 6, 'พระดํารัสของพระเยโฮวาห์เป็นพระดํารัสที่บริสุทธิ์ เป็นเหมือนเงินหลอมให้บริสุทธิ์ในเตาไฟบนแผ่นดินแล้วถึงเจ็ดครั้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 7, 'โอ ข้าแต่พระเยโฮวาห์ พระองค์จะทรงป้องกันพระดํารัสเหล่านั้น พระองค์จะทรงปกปักรักษาพระดํารัสไว้เสมอจากพงศ์พันธุ์นี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 8, 'คนชั่วก็เพ่นพ่านไปมาอยู่รอบด้าน ขณะเมื่อมีการยกย่องคนชั่วช้าที่สุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 1, 'ถึงหัวหน้านักร้อง เพลงสดุดีของดาวิดโอ ข้าแต่พระเยโฮวาห์ อีกนานเท่าใดพระองค์จะทรงลืมข้าพระองค์เสีย เป็นนิตย์หรือ พระองค์จะปิดบังพระพักตร์ของพระองค์จากข้าพระองค์นานเท่าใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 2, 'ข้าพระองค์จะต้องตรึกตรองในใจของข้าพระองค์ และมีความทุกข์โศกอยู่ในใจทุกวันนานเท่าใด ศัตรูของข้าพระองค์จะเหนือข้าพระองค์นานเท่าใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 3, 'โอ ข้าแต่พระเยโฮวาห์พระเจ้าของข้าพระองค์ ขอทรงพิจารณา และฟังข้าพระองค์ด้วยเถิด ทั้งขอทรงเพิ่มความสว่างแก่ตาข้าพระองค์ เกลือกว่าข้าพระองค์จะหลับอยู่ในความตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 4, 'เกรงว่าศัตรูของข้าพระองค์จะว่า “เราชนะเขาแล้ว” เกรงว่าคู่อริของข้าพระองค์จะเปรมปรีดิ์เพราะข้าพระองค์กําลังหวั่นไหว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 5, 'แต่ข้าพระองค์วางใจในความเมตตาของพระองค์ จิตใจของข้าพระองค์จะเปรมปรีดิ์ในความรอดของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 6, 'ข้าพเจ้าจะร้องเพลงสรรเสริญพระเยโฮวาห์ เพราะว่าพระองค์ทรงกระทําแก่ข้าพเจ้าอย่างบริบูรณ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 1, 'ถึงหัวหน้านักร้อง เพลงสดุดีของดาวิดคนโง่รําพึงในใจของตนว่า “ไม่มีพระเจ้า” เขาทั้งหลายก็เลวทรามลง เขากระทํากิจการที่น่าสะอิดสะเอียน ไม่มีสักคนเดียวที่ทําดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 2, 'พระเยโฮวาห์ทรงมองลงมาจากฟ้าสวรรค์ ดูบุตรทั้งหลายของมนุษย์ว่าจะมีคนใดบ้างที่เข้าใจที่เสาะแสวงหาพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 3, 'เขาทั้งหลายก็หลงเจิ่นไปหมด เขาทั้งหลายก็เลวทรามลงเหมือนกันสิ้น ไม่มีสักคนเดียวที่ทําดี ไม่มีเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 4, 'บรรดาผู้ที่กระทําความชั่วช้าไม่มีความรู้หรือ คือผู้ที่กินประชาชนของเราอย่างกินขนมปัง และไม่ร้องทูลพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 5, 'เขาทั้งหลายอยู่ที่นั่นอย่างน่าสยดสยองยิ่งนัก เพราะพระเจ้าทรงสถิตตลอดชั่วอายุของผู้ชอบธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 6, 'เจ้าได้คว่ําแผนงานของคนยากจนเสีย แต่พระเยโฮวาห์ทรงเป็นที่ลี้ภัยของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 7, 'โอ ขอการช่วยให้รอดเพื่ออิสราเอลมาจากศิโยนเสียทีเถิด เมื่อพระเยโฮวาห์ทรงให้พวกเชลยแห่งประชาชนของพระองค์กลับสู่สภาพเดิม ยาโคบจะปลาบปลื้ม อิสราเอลจะยินดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 1, 'เพลงสดุดีของดาวิดข้าแต่พระเยโฮวาห์ ผู้ใดจะอาศัยอยู่ในพลับพลาของพระองค์ ผู้ใดจะอยู่บนภูเขาอันบริสุทธิ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 2, 'คือผู้ที่ดําเนินในความเที่ยงธรรม และประพฤติตามความชอบธรรม และพูดความจริงจากใจของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 3, 'ผู้ซึ่งไม่ใช้ลิ้นของตนในการนินทาว่าร้าย ไม่กระทําชั่วต่อเพื่อนบ้าน และไม่ตําหนิเพื่อนบ้านของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 4, 'ในสายตาของเขา คนถ่อยเป็นคนที่ถูกดูหมิ่นเหยียดหยาม เขาให้เกียรติแก่ผู้ที่ยําเกรงพระเยโฮวาห์ เมื่อให้คําสัตย์ปฏิญาณแล้วต้องพบกับความปวดร้าวเขาก็ไม่กลับคํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 5, 'เขาเป็นผู้ที่ให้คนอื่นกู้เงินโดยมิได้คิดดอกเบี้ย และไม่ยอมรับสินบนต่อสู้ผู้ไร้ความผิด ผู้ซึ่งกระทําสิ่งเหล่านี้จะไม่หวั่นไหวเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 1, 'มิคทามบทหนึ่งของดาวิดโอ ข้าแต่พระเจ้า ขอทรงพิทักษ์ข้าพระองค์ไว้ เพราะข้าพระองค์วางใจในพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 2, 'โอ จิตวิญญาณของข้าพเจ้าเอ๋ย เจ้าได้ทูลพระเยโฮวาห์แล้วว่า “พระองค์ทรงเป็นองค์พระผู้เป็นเจ้าของข้าพระองค์ นอกเหนือพระองค์แล้ว ข้าพระองค์ไม่มีดีเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 3, 'วิสุทธิชนในแผ่นดินและผู้ประเสริฐ เป็นพวกที่ข้าพเจ้ามีความปีติยินดีทั้งสิ้นด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 4, 'แต่บรรดาผู้ที่รีบติดตามพระอื่น ความทุกข์โศกของเขาก็ทวีขึ้น ข้าพเจ้าจะไม่ถวายเครื่องดื่มบูชาแห่งเลือดของพวกเขา หรือริมฝีปากของข้าพเจ้าจะไม่ออกชื่อพระนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 5, 'พระเยโฮวาห์ทรงเป็นส่วนมรดกและถ้วยของข้าพเจ้า พระองค์ทรงรักษาส่วนของข้าพระองค์ไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 6, 'เขตแดนของข้าพเจ้าเป็นที่ที่ร่มรื่น เออ ข้าพเจ้ามีมรดกที่ดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 7, 'ข้าพเจ้าจะสรรเสริญพระเยโฮวาห์ ผู้ประทานคําปรึกษาแก่ข้าพเจ้า เออ ในกลางคืนจิตใจของข้าพเจ้าเตือนสอนข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 8, 'ข้าพเจ้าตั้งพระเยโฮวาห์ไว้ตรงหน้าข้าพเจ้าเสมอ เพราะพระองค์ประทับที่มือขวาของข้าพเจ้า ข้าพเจ้าจะไม่หวั่นไหว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 9, 'เพราะฉะนั้นจิตใจของข้าพเจ้าจึงยินดีและจิตวิญญาณของข้าพเจ้าก็ปรีดา เนื้อหนังของข้าพเจ้าจะพักพิงอยู่ในความหวังใจด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 10, 'เพราะพระองค์จะไม่ทรงทิ้งจิตวิญญาณของข้าพระองค์ไว้ในนรก ทั้งจะไม่ทรงให้องค์บริสุทธิ์ของพระองค์เปื่อยเน่าไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 11, 'พระองค์จะทรงสําแดงวิถีแห่งชีวิตแก่ข้าพระองค์ ต่อพระพักตร์พระองค์มีความชื่นบานอย่างเปี่ยมล้น ในพระหัตถ์ขวาของพระองค์มีความเพลิดเพลินอยู่เป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 1, 'คําอธิษฐานของดาวิดโอ ข้าแต่พระเยโฮวาห์ ขอทรงสดับความฝ่ายยุติธรรม ทรงฟังคําร้องทูลของข้าพระองค์ ขอทรงเงี่ยพระกรรณสดับคําอธิษฐานของข้าพระองค์ ซึ่งมาจากริมฝีปากที่ไม่มีการหลอกลวงของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 2, 'ขอให้การชนะความของข้าพระองค์มาจากพระพักตร์พระองค์ ขอพระเนตรของพระองค์ทรงเห็นสิ่งเที่ยงธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 3, 'เมื่อพระองค์ทรงลองจิตใจของข้าพระองค์ และเสด็จเยี่ยมเยียนข้าพระองค์ในเวลากลางคืน เมื่อทรงทดสอบข้าพระองค์แล้ว พระองค์จะไม่ทรงพบความชั่วในข้าพระองค์เลย ข้าพระองค์ตั้งใจแล้วว่าปากของข้าพระองค์จะมิได้ละเมิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 4, 'เกี่ยวด้วยกิจการของมนุษย์ โดยพระวจนะจากพระโอษฐ์ของพระองค์ ข้าพระองค์มิได้ข้องเกี่ยวกับทางแห่งคนทารุณโหดร้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 5, 'ขอให้ย่างเท้าของข้าพระองค์แนบสนิทกับวิถีของพระองค์ เพื่อเท้าของข้าพระองค์มิได้พลาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 6, 'โอ ข้าแต่พระเจ้า ข้าพระองค์ร้องทูลถึงพระองค์ เพราะพระองค์จะทรงสดับข้าพระองค์ ขอทรงเอียงพระกรรณสดับถ้อยคําของข้าพระองค์ด้วยเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 7, 'โอ ข้าแต่พระผู้ช่วยของบรรดาผู้แสวงหาที่ลี้ภัยจากปฏิปักษ์ของเขา ณ พระหัตถ์ขวาของพระองค์ ขอทรงสําแดงความเมตตาอย่างมหัศจรรย์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 8, 'ขอทรงรักษาข้าพระองค์ดังแก้วตา ขอทรงซ่อนข้าพระองค์ไว้ภายใต้ร่มปีกของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 9, 'ให้พ้นจากคนชั่วผู้ล้างผลาญและจากศัตรูผู้คอยเข่นฆ่าซึ่งล้อมข้าพระองค์ไว้โดยรอบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 10, 'เขาปิดใจของเขาไว้เพราะเหตุความมั่งคั่งของตน ปากของเขาพูดคําหยิ่งยโส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 11, 'เขาสะกดรอยข้าพระองค์ เดี๋ยวนี้ได้ล้อมข้าพระองค์ไว้ เขาจับตาดูข้าพระองค์เพื่อจะเหวี่ยงข้าพระองค์ลงดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 12, 'เขาเป็นดุจสิงโตที่กระหายเหยื่อของมัน เหมือนดังสิงโตหนุ่มซึ่งซุ่มดักทําร้ายอยู่ในที่ลับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 13, 'โอ ข้าแต่พระเยโฮวาห์ ขอทรงลุกขึ้นปะทะเขาไว้ และคว่ําเขาลงเสีย ขอทรงช่วยชีวิตของข้าพระองค์ให้พ้นจากคนชั่วด้วยดาบของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 14, 'โอ ข้าแต่พระเยโฮวาห์ ขอทรงช่วยข้าพระองค์ให้พ้นจากมนุษย์ผู้ซึ่งเป็นพระหัตถ์ของพระองค์ จากมนุษย์แห่งโลกนี้ จากมนุษย์ผู้ซึ่งมีส่วนของชีวิตนี้ ผู้ซึ่งพระองค์ทรงให้ท้องของเขาเต็มไปด้วยทรัพย์สมบัติที่พระองค์ทรงซ่อนไว้ พวกเขามีลูกหลานอุดมสมบูรณ์ และส่วนที่เหลือเขามอบไว้ให้แก่ลูกอ่อนของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 15, 'ส่วนข้าพระองค์ ข้าพระองค์จะเห็นพระพักตร์ของพระองค์ในความชอบธรรม เมื่อข้าพระองค์ตื่นขึ้น ข้าพระองค์จะอิ่มเอิบใจด้วยพระลักษณะของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 1, 'ถึงหัวหน้านักร้อง เพลงสดุดีของดาวิด ผู้รับใช้ของพระเยโฮวาห์ ซึ่งถวายถ้อยคําของเพลงบทนี้แด่พระเยโฮวาห์ในวันที่พระเยโฮวาห์ทรงช่วยท่านให้พ้นจากเงื้อมมือศัตรูทั้งหลายของท่าน และจากเงื้อมพระหัตถ์ของซาอูล ท่านกล่าวว่าโอ ข้าแต่พระเยโฮวาห์ กําลังของข้าพระองค์ ข้าพระองค์จะรักพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 2, 'พระเยโฮวาห์เป็นศิลา ป้อมปราการ และผู้ช่วยให้พ้นของข้าพระองค์ เป็นพระเจ้าของข้าพระองค์ เป็นกําลังของข้าพระองค์ ซึ่งข้าพระองค์จะวางใจในพระองค์ เป็นดั้ง เป็นเขาแห่งความรอดของข้าพระองค์ เป็นที่กําบังเข้มแข็งของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 3, 'ข้าพระองค์จะร้องทูลต่อพระเยโฮวาห์ผู้ทรงสมควรแก่การสรรเสริญ และข้าพระองค์จะได้รับการช่วยให้พ้นจากศัตรูของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 4, 'ความโศกเศร้าแห่งความตายล้อมข้าพระองค์ไว้ กระแสแห่งคนอธรรมที่ท่วมทับข้าพระองค์ทําให้ข้าพระองค์กลัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 5, 'ความโศกเศร้าแห่งนรกล้อมข้าพระองค์ไว้ บ่วงมัจจุราชปะทะข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 6, 'ในยามทุกข์ระทมใจ ข้าพเจ้าร้องทูลต่อพระเยโฮวาห์ ข้าพเจ้าร้องทูลขอความช่วยเหลือจากพระเจ้าของข้าพเจ้า พระองค์ทรงสดับเสียงของข้าพเจ้าจากพระวิหารของพระองค์ และเสียงร้องของข้าพเจ้าได้ยินต่อพระพักตร์พระองค์ ไปถึงพระกรรณของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 7, 'แล้วแผ่นดินโลกก็สั่นสะเทือนและโคลงเคลง รากฐานของภูเขาก็หวั่นไหวด้วย และสั่นสะเทือน เพราะพระองค์ทรงกริ้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 8, 'ควันออกไปตามช่องพระนาสิกของพระองค์ และเพลิงผลาญออกมาจากพระโอษฐ์ของพระองค์ ถ่านก็ติดเปลวไฟนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 9, 'พระองค์ทรงโน้มฟ้าสวรรค์ลงด้วยและเสด็จลงมา ความมืดทึบอยู่ใต้พระบาทของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 10, 'พระองค์ทรงเครูบตนหนึ่ง แล้วทรงเหาะไป พระองค์ทรงเหาะไปโดยปีกของลมอย่างรวดเร็ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 11, 'พระองค์ทรงกระทําให้ความมืดปกคลุมพระองค์ไว้ ให้เมฆมืดและอุ้มน้ําเป็นพลับพลาของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 12, 'มีลูกเห็บและถ่านเพลิงแตกออกมาทะลุเมฆจากความสว่างสุกใสข้างหน้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 13, 'พระเยโฮวาห์ทรงคะนองกึกก้องในฟ้าสวรรค์ และองค์ผู้สูงสุดก็เปล่งพระสุรเสียง คือลูกเห็บและถ่านเพลิง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 14, 'พระองค์ทรงยิงลูกธนูของพระองค์ออกไป ทําให้เขาต่างกระจัดกระจายไป พระองค์ทรงปล่อยฟ้าแลบแปลบปลาบ ทําให้เขาโกลาหล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 15, 'โอ ข้าแต่พระเยโฮวาห์ แล้วก็เห็นก้นทะเลตลอดจนรากฐานของพิภพก็ปรากฏแจ้ง เมื่อพระองค์ทรงขนาบทะเลด้วยลมที่พวยพุ่งจากช่องพระนาสิกของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 16, 'พระองค์ทรงเอื้อมมาจากที่สูงทรงจับข้าพเจ้า พระองค์ทรงดึงข้าพเจ้าออกมาจากน้ําอันมากหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 17, 'พระองค์ทรงช่วยข้าพเจ้าให้พ้นจากศัตรูเข้มแข็งของข้าพเจ้า และจากบรรดาผู้ที่เกลียดชังข้าพเจ้า เพราะเขามีอานุภาพเกินกว่าข้าพเจ้ามากนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 18, 'เขาขัดขวางข้าพเจ้าในวันที่ข้าพเจ้าประสบหายนะ แต่พระเยโฮวาห์ทรงเป็นที่พักพิงของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 19, 'พระองค์ทรงนําข้าพเจ้าออกมายังที่กว้างใหญ่ และทรงช่วยข้าพเจ้าให้พ้น เพราะพระองค์ทรงชื่นชมยินดีในข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 20, 'พระเยโฮวาห์ประทานรางวัลแก่ข้าพเจ้าตามความชอบธรรมของข้าพเจ้า พระองค์ทรงตอบแทนข้าพเจ้าตามความสะอาดแห่งมือของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 21, 'เพราะข้าพเจ้ารักษาบรรดามรรคาของพระเยโฮวาห์ และไม่ได้พรากจากพระเจ้าของข้าพเจ้าอย่างชั่วร้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 22, 'เพราะคําตัดสินทั้งสิ้นของพระองค์อยู่ต่อหน้าข้าพเจ้า และข้าพเจ้ามิได้ผลักกฎเกณฑ์ของพระองค์ไปเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 23, 'ต่อพระพักตร์พระองค์ข้าพเจ้าไร้ตําหนิ และข้าพเจ้ารักษาตัวไว้ไม่ทําความชั่วช้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 24, 'เพราะฉะนั้นพระเยโฮวาห์จึงทรงตอบแทนข้าพเจ้าตามความชอบธรรมของข้าพเจ้า ตามความสะอาดแห่งมือของข้าพเจ้าในสายพระเนตรของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 25, 'พระองค์จะทรงสําแดงความเมตตาต่อผู้ที่มีความเมตตา พระองค์จะทรงสําแดงพระองค์อย่างไร้ตําหนิต่อผู้ที่ไร้ตําหนิ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 26, 'พระองค์จะทรงสําแดงพระองค์บริสุทธิ์ต่อผู้ที่บริสุทธิ์ พระองค์จะทรงสําแดงพระองค์เป็นปฏิปักษ์ต่อผู้ที่คดโกง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 27, 'เพราะพระองค์จะทรงช่วยประชาชนที่ยากแค้นให้พ้น แต่ตาที่หยิ่งยโสนั้นพระองค์จะทรงกระทําให้ต่ําลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 28, 'พระองค์จะทรงจุดตะเกียงของข้าพระองค์ พระเยโฮวาห์พระเจ้าของข้าพระองค์จะทรงกระทําความมืดของข้าพระองค์ให้สว่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 29, 'พระเจ้าข้า ข้าพระองค์ตะลุยกองทัพได้โดยพระองค์ และโดยพระเจ้าของข้าพเจ้านี้ข้าพเจ้าสามารถกระโดดข้ามกําแพงได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 30, 'สําหรับพระเจ้าพระองค์นี้ พระมรรคาของพระองค์ดีเลิศทุกประการ พระวจนะของพระเยโฮวาห์พิสูจน์แล้วเป็นความจริง พระองค์ทรงเป็นดั้งของบรรดาผู้ที่วางใจในพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 31, 'เพราะผู้ใดจะเป็นพระเจ้า นอกจากพระเยโฮวาห์ และผู้ใดเล่าเป็นศิลา เว้นแต่พระเจ้าของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 32, 'คือพระเจ้าผู้ทรงเอากําลังคาดเอวของข้าพเจ้าไว้ และทรงกระทําให้ทางของข้าพเจ้ารอบคอบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 33, 'พระองค์ทรงกระทําให้เท้าของข้าพเจ้าเหมือนอย่างตีนกวางตัวเมีย และทรงวางข้าพเจ้าไว้บนที่สูง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 34, 'พระองค์ทรงฝึกมือของข้าพเจ้าให้ทําสงคราม ดังนั้นแขนของข้าพเจ้าสามารถทําให้คันธนูเหล็กกล้าหักได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 35, 'พระองค์ประทานโล่แห่งความรอดของพระองค์ให้ข้าพระองค์ และพระหัตถ์ขวาของพระองค์ทรงค้ําจุนข้าพระองค์ และซึ่งพระองค์ทรงน้อมพระทัยลง ก็กระทําให้ข้าพระองค์เป็นใหญ่ขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 36, 'พระองค์ประทานที่กว้างขวางสําหรับย่างเท้าของข้าพระองค์ เท้าของข้าพระองค์จึงไม่พลาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 37, 'ข้าพระองค์ไล่ตามศัตรูของข้าพระองค์ทัน และไม่หันกลับจนกว่าเขาจะถูกผลาญเสียสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 38, 'ข้าพระองค์ได้แทงเขาทะลุ เขาจึงไม่สามารถลุกขึ้นได้อีก เขาล้มลงที่ใต้เท้าของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 39, 'เพราะพระองค์ทรงเอากําลังคาดเอวข้าพระองค์ไว้เพื่อทําสงคราม พระองค์ทรงกระทําให้พวกที่ลุกขึ้นต่อสู้กับข้าพระองค์สยบลงอย่างราบคาบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 40, 'พระองค์ทรงโปรดประทานคอของศัตรูของข้าพระองค์แก่ข้าพระองค์ เพื่อข้าพระองค์จะทําลายบรรดาผู้ที่เกลียดชังข้าพระองค์เสียสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 41, 'เขาร้องให้ช่วย แต่ไม่มีใครช่วยให้รอดได้ เขาร้องทูลพระเยโฮวาห์ แต่พระองค์มิได้ทรงตอบเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 42, 'ข้าพระองค์จึงทุบเขาแหลกละเอียดอย่างผงคลีต่อหน้าลม ข้าพระองค์จึงโยนเขาออกไปเหมือนโคลนตามถนน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 43, 'พระองค์ทรงช่วยข้าพระองค์ให้พ้นจากการยื้อแย่งกับประชาชน และทรงตั้งให้ข้าพระองค์เป็นหัวหน้าของบรรดาประชาชาติ ชนชาติที่ข้าพระองค์ไม่เคยรู้จักก็จะได้ปรนนิบัติข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 44, 'พอเขาได้ยินถึงข้าพระองค์ เขาก็จะเชื่อฟัง ชนต่างด้าวจะได้มาหมอบราบต่อข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 45, 'ชนต่างด้าวนั้นจะเสียกําลังใจ และตัวสั่นออกมาจากที่กําบังอันเข้มแข็งของเขาเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 46, 'พระเยโฮวาห์ทรงพระชนม์อยู่ และศิลาของข้าพระองค์เป็นที่ควรสรรเสริญ พระเจ้าแห่งความรอดของข้าพระองค์เป็นที่ยกย่อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 47, 'คือพระเจ้าผู้ประทานการแก้แค้นแก่ข้าพระองค์ และทรงปราบปรามบรรดาชนชาติทั้งหลายให้อยู่ภายใต้อํานาจของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 48, 'ผู้ทรงช่วยข้าพระองค์ให้พ้นจากศัตรู พระเจ้าข้า พระองค์ทรงยกข้าพระองค์ขึ้นเหนือพวกที่ลุกขึ้นต่อสู้กับข้าพระองค์ พระองค์ทรงช่วยข้าพระองค์ให้พ้นจากคนทารุณโหดร้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 49, 'โอ ข้าแต่พระเยโฮวาห์ เพราะเหตุนี้ข้าพระองค์จึงจะขอเทิดทูนพระองค์ไว้ท่ามกลางประชาชาติทั้งหลาย และร้องเพลงสรรเสริญพระนามของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 50, 'พระองค์ประทานชัยชนะอันยิ่งใหญ่แก่กษัตริย์ของพระองค์ และทรงสําแดงความเมตตาแก่ผู้ที่พระองค์ทรงเจิมไว้นั้น คือดาวิด และแก่เชื้อพระวงศ์ของท่านเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 1, 'ถึงหัวหน้านักร้อง เพลงสดุดีของดาวิดฟ้าสวรรค์ประกาศสง่าราศีของพระเจ้า และภาคพื้นฟ้าสําแดงพระหัตถกิจของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 2, 'วันส่งถ้อยคําให้แก่วัน และคืนแจ้งความรู้ให้แก่คืน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 3, 'ไม่มีสําเนียงหรือภาษาใดๆ ที่ไม่ได้ยินเสียงฟ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 4, 'เสียงฟ้าก็ออกไปทั่วแผ่นดินโลก และถ้อยคําก็แพร่ไปถึงสุดปลายพิภพ พระองค์ทรงตั้งพลับพลาไว้ให้ดวงอาทิตย์ ณ ที่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 5, 'ซึ่งออกมาอย่างเจ้าบ่าวออกมาจากห้องโถงของเขา และวิ่งไปตามวิถีด้วยความชื่นบานอย่างชายฉกรรจ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 6, 'ดวงอาทิตย์ขึ้นมาจากสุดปลายฟ้าสวรรค์ข้างหนึ่ง และโคจรไปถึงที่สุดปลายอีกข้างหนึ่ง ไม่มีสิ่งใดสามารถซ่อนให้พ้นจากความร้อนของมันได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 7, 'พระราชบัญญัติของพระเยโฮวาห์รอบคอบและฟื้นฟูจิตวิญญาณ พระโอวาทของพระเยโฮวาห์นั้นแน่นอนกระทําให้คนรู้น้อยมีปัญญา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 8, 'กฎเกณฑ์ของพระเยโฮวาห์นั้นถูกต้องกระทําให้จิตใจเปรมปรีดิ์ พระบัญญัติของพระเยโฮวาห์นั้นบริสุทธิ์กระทําให้ดวงตากระจ่างแจ้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 9, 'ความยําเกรงพระเยโฮวาห์นั้นสะอาดหมดจดถาวรเป็นนิตย์ คําตัดสินของพระเยโฮวาห์ก็เที่ยงตรงและชอบธรรมทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 10, 'น่าปรารถนามากกว่าทองคํา เออ ยิ่งกว่าทองคําเนื้อดีมากนัก หวานยิ่งกว่าน้ําผึ้งและรวงผึ้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 11, 'อนึ่ง สิ่งเหล่านี้เป็นที่ตักเตือนผู้รับใช้ของพระองค์ การที่จะรักษาข้อความเหล่านั้นก็ได้บําเหน็จอันใหญ่ยิ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 12, 'แต่ผู้ใดเล่าจะเข้าใจเรื่องความผิดพลาดของตนได้ ขอพระองค์ทรงชําระข้าพระองค์ให้พ้นจากความผิดที่ซ่อนเร้นอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 13, 'ขอทรงยับยั้งผู้รับใช้ของพระองค์ให้พ้นจากบาปโดยประมาทนั้นด้วยเถิด ขออย่าให้มันมีอํานาจเหนือข้าพระองค์เลย แล้วข้าพระองค์จะไร้ตําหนิและพ้นจากความผิดจากการละเมิดที่ยิ่งใหญ่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 14, 'โอ ข้าแต่พระเยโฮวาห์ กําลังของข้าพระองค์และพระผู้ไถ่ของข้าพระองค์ ขอให้ถ้อยคําจากปากของข้าพระองค์ และการไตร่ตรองในจิตใจของข้าพระองค์เป็นที่พอพระทัยในสายพระเนตรของพระองค์เถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 1, 'ถึงหัวหน้านักร้อง เพลงสดุดีของดาวิดขอพระเยโฮวาห์ทรงฟังท่านในวันยากลําบาก พระนามของพระเจ้าแห่งยาโคบพิทักษ์รักษาท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 2, 'ขอพระองค์ทรงให้ความช่วยเหลือมาจากสถานบริสุทธิ์ และทรงเพิ่มกําลังให้แก่ท่านมาจากเมืองศิโยน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 3, 'ขอทรงระลึกถึงเครื่องถวายทั้งสิ้นของท่าน และโปรดปรานเครื่องเผาบูชาของท่าน เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 4, 'ขอทรงประสิทธิ์ประสาทตามใจปรารถนาของท่านด้วย และให้โครงการที่ท่านคิดนั้นสําเร็จทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 5, 'เพื่อพวกเราจะได้โห่ร้องเนื่องด้วยความรอดของท่าน และยกธงขึ้นในพระนามพระเจ้าของเรา ขอพระเยโฮวาห์ทรงโปรดให้คําทูลขอทั้งสิ้นของท่านสําเร็จเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 6, 'บัดนี้ ข้าพเจ้าทราบว่าพระเยโฮวาห์จะทรงช่วยผู้ที่พระองค์ทรงเจิมไว้ พระองค์จะทรงฟังเขาจากฟ้าสวรรค์อันบริสุทธิ์ของพระองค์ และโดยชัยชนะอันทรงอานุภาพด้วยพระหัตถ์ขวาของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 7, 'บ้างก็วางใจในรถรบ บ้างก็วางใจในม้า แต่เราจะระลึกถึงพระนามพระเยโฮวาห์พระเจ้าของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 8, 'เขาทั้งหลายจะล้มพับลงไป แต่เราจะลุกขึ้นยืนตรงอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 9, 'ข้าแต่พระเยโฮวาห์ ขอทรงช่วยข้าพระองค์ทั้งหลายให้รอดเถิด ขอให้กษัตริย์ทรงฟังเมื่อข้าพระองค์ทั้งหลายร้องทูลต่อท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 1, 'ถึงหัวหน้านักร้อง เพลงสดุดีของดาวิดโอ ข้าแต่พระเยโฮวาห์ กษัตริย์จะเปรมปรีดิ์ในพระกําลังของพระองค์ ท่านจะปีติยินดีอย่างยิ่งในความรอดของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 2, 'พระองค์ทรงประสิทธิ์ประสาทตามใจปรารถนาของท่าน และมิได้ทรงยับยั้งสิ่งที่ริมฝีปากท่านทูลขอ เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 3, 'เพราะพระองค์ทรงอํานวยพรดีแก่ท่าน พระองค์ทรงสวมมงกุฎทองคําบริสุทธิ์บนศีรษะของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 4, 'ท่านทูลขอชีวิต และพระองค์ก็ประทานชีวิตยืนนานเป็นนิตย์นิรันดร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 5, 'สง่าราศีของท่านใหญ่ยิ่งเนื่องด้วยความรอดของพระองค์ พระองค์ทรงประดับกษัตริย์ด้วยยศศักดิ์และความสง่าโอ่อ่าตระการ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 6, 'พระองค์ทรงโปรดให้ท่านรับพระพรอย่างที่สุดเป็นนิตย์ และทรงกระทําให้ท่านยินดีปรีดาอย่างเหลือล้นด้วยสีพระพักตร์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 7, 'เพราะกษัตริย์วางใจในพระเยโฮวาห์ และด้วยความเมตตาของพระองค์ผู้สูงสุด ท่านจะไม่หวั่นไหวเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 8, 'พระหัตถ์ของพระองค์จะค้นพบเหล่าศัตรูทั้งหลาย พระหัตถ์ขวาจะพบบรรดาผู้ที่เกลียดชังพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 9, 'เมื่อพระองค์ทรงพระพิโรธ พระองค์จะทรงกระทําให้เขาร้อนจัดดังเตาไฟ พระเยโฮวาห์จะทรงกลืนเขาด้วยพระพิโรธของพระองค์ และไฟจะเผาผลาญเขาเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 10, 'พระองค์จะทรงทําลายลูกหลานของเขาเสียจากแผ่นดินโลก และพรากเชื้อสายของเขาจากบุตรทั้งหลายของมนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 11, 'แม้เขาทั้งหลายได้ปองร้ายต่อพระองค์ แม้เขาประดิษฐ์เรื่องชั่วร้าย เขาก็จะกระทําไม่สําเร็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 12, 'ฉะนั้นพระองค์จะทรงกระทําให้เขาหนีพ่ายไปเมื่อพระองค์จะทรงเล็งธนูไปตรงหน้าเขาทีเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 13, 'ข้าแต่พระเยโฮวาห์ ขอทรงเป็นที่ยกย่องเชิดชูในพระกําลังของพระองค์ ข้าพระองค์ทั้งหลายจะร้องเพลงสรรเสริญฤทธานุภาพของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 1, 'ถึงหัวหน้านักร้องตามทํานองอาเยเลท ชาหาร์ เพลงสดุดีของดาวิดพระเจ้าของข้าพระองค์ พระเจ้าของข้าพระองค์ ไฉนพระองค์ทรงทอดทิ้งข้าพระองค์เสีย เหตุใดพระองค์ทรงเมินเฉยที่จะช่วยข้าพระองค์ และต่อถ้อยคําคร่ําครวญของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 2, 'โอ ข้าแต่พระเจ้าของข้าพระองค์ ข้าพระองค์ร้องทูลในเวลากลางวัน แต่พระองค์มิได้ทรงฟัง ถึงกลางคืนข้าพระองค์ยังร่ําทูลต่อไปไม่หยุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 3, 'ถึงอย่างไรพระองค์ทรงเป็นองค์บริสุทธิ์ โอ พระองค์ประทับเหนือคําสรรเสริญของคนอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 4, 'บรรพบุรุษของข้าพระองค์ทั้งหลายวางใจในพระองค์ เขาทั้งหลายวางใจ และพระองค์ทรงช่วยเขาให้พ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 5, 'เขาร้องทูล พระองค์ก็ทรงช่วยเขาให้รอด เขาวางใจในพระองค์ เขาจึงมิได้รับความอับอาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 6, 'ข้าพระองค์เป็นดุจตัวหนอน มิใช่คน คนก็ด่า ประชาชนก็ดูหมิ่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 7, 'บรรดาผู้ที่เห็นข้าพระองค์ก็หัวเราะเยาะเย้ยข้าพระองค์ เขาบุ้ยริมฝีปากและสั่นศีรษะกล่าวว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 8, '“เขาวางใจในพระเยโฮวาห์ว่าพระองค์จะทรงช่วยเขาให้พ้น จงให้พระองค์ทรงช่วยเขาให้พ้น เพราะพระองค์ทรงพอพระทัยในเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 9, 'ถึงกระนั้นพระองค์ก็ทรงเป็นผู้นําข้าพระองค์ออกมาจากครรภ์มารดา และทรงให้ข้าพระองค์มีความหวังใจเมื่ออยู่ที่อกแม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 10, 'ตั้งแต่คลอด ข้าพระองค์ก็ต้องพึ่งพระองค์ พระองค์ทรงเป็นพระเจ้าของข้าพระองค์ตั้งแต่ข้าพระองค์ยังอยู่ในครรภ์มารดา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 11, 'ขออย่าทรงห่างไกลข้าพระองค์ เพราะความยากลําบากอยู่ใกล้และไม่มีผู้ใดช่วยได้เลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 12, 'เหล่าวัวผู้ล้อมข้าพระองค์ วัวผู้แข็งแรงแห่งบาชานล้อมข้าพระองค์ไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 13, 'มันอ้าปากกว้างเข้าใส่ข้าพระองค์ดั่งสิงโตขณะกัดฉีกและคํารามร้อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 14, 'ข้าพระองค์ถูกเทออกเหมือนอย่างน้ํา กระดูกทั้งสิ้นของข้าพระองค์หลุดลุ่ยไป จิตใจก็เหมือนขี้ผึ้ง ละลายภายในอกของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 15, 'กําลังของข้าพระองค์เหือดแห้งไปเหมือนเศษหม้อดิน และลิ้นของข้าพระองค์ก็เกาะติดที่ขากรรไกร พระองค์ทรงวางข้าพระองค์ไว้ในผงคลีมัจจุราช');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 16, 'พระเจ้าข้า บรรดาสุนัขล้อมรอบข้าพระองค์ไว้ คนทําชั่วหมู่หนึ่งล้อมข้าพระองค์ เขาแทงมือแทงเท้าข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 17, 'ข้าพระองค์นับกระดูกทั้งหลายของข้าพระองค์ได้เป็นชิ้นๆ เขาจ้องมองและยิ้มเยาะข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 18, 'เสื้อผ้าของข้าพระองค์เขาแบ่งปันกัน ส่วนเสื้อของข้าพระองค์นั้นเขาก็จับฉลากกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 19, 'โอ ข้าแต่พระเยโฮวาห์ ขอพระองค์อย่าทรงห่างไกลเลย โอ ข้าแต่พระองค์ กําลังของข้าพระองค์ ขอทรงเร่งรีบมาช่วยข้าพระองค์ด้วยเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 20, 'ขอทรงช่วยจิตวิญญาณข้าพระองค์ให้พ้นจากดาบ ช่วยชีวิตข้าพระองค์จากฤทธิ์ของสุนัข');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 21, 'ขอทรงช่วยข้าพระองค์ให้รอดพ้นจากปากสิงโต เพราะพระองค์ทรงฟังข้าพระองค์จากบรรดาเขาของม้ายูนิคอนเหล่านั้นด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 22, 'ข้าพระองค์จะประกาศพระนามของพระองค์แก่พี่น้องของข้าพระองค์ ข้าพระองค์จะสรรเสริญพระองค์ท่ามกลางชุมนุมชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 23, 'ท่านผู้เกรงกลัวพระเยโฮวาห์ จงสรรเสริญพระองค์ ท่านเชื้อสายทั้งหลายของยาโคบเอ๋ย จงถวายสง่าราศีแด่พระองค์ ท่านเชื้อสายทั้งสิ้นของอิสราเอลเอ๋ย จงเกรงกลัวพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 24, 'เพราะพระองค์มิได้ทรงดูถูกหรือสะอิดสะเอียนต่อความทุกข์ยากของผู้ที่ทุกข์ใจ และพระองค์มิได้ทรงซ่อนพระพักตร์จากเขา เมื่อเขาร้องทูล พระองค์ทรงสดับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 25, 'ข้าพระองค์จะสรรเสริญพระองค์ในที่ชุมนุมชนใหญ่ ข้าพระองค์จะทําตามคําปฏิญาณต่อหน้าผู้ที่เกรงกลัวพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 26, 'คนเสงี่ยมเจียมตัวจะได้กินอิ่ม บรรดาผู้ที่แสวงหาพระองค์จะสรรเสริญพระเยโฮวาห์ ขอจิตใจของท่านทั้งหลายมีชีวิตอยู่เป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 27, 'ที่สุดปลายทั้งสิ้นของแผ่นดินโลกจะจดจําและหันกลับมายังพระเยโฮวาห์ และครอบครัวทั้งสิ้นของบรรดาประชาชาติจะนมัสการต่อพระพักตร์พระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 28, 'เพราะอํานาจการปกครองเป็นของพระเยโฮวาห์ และพระองค์ทรงครอบครองเหนือบรรดาประชาชาติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 29, 'เออ คนร่ํารวยทั้งสิ้นของแผ่นดินโลกจะต้องกินเลี้ยงและกราบลงต่อพระองค์ บรรดาผู้ที่ลงไปสู่ผงคลีทั้งสิ้นจะกราบไหว้ต่อพระพักตร์พระองค์ คือบรรดาผู้ที่รักษาตัวให้คงชีวิตอยู่ไม่ได้แล้วนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 30, 'จะมีเชื้อสายๆหนึ่งปรนนิบัติพระองค์ จะทรงนับว่าพวกนั้นเป็นยุคที่ถวายแด่องค์พระผู้เป็นเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 31, 'พวกเขาจะมาประกาศความชอบธรรมของพระองค์แก่ชนชาติหนึ่งที่จะเกิดมา ว่าพระองค์ได้ทรงกระทําการนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 1, 'เพลงสดุดีของดาวิดพระเยโฮวาห์ทรงเป็นผู้เลี้ยงดูข้าพเจ้า ข้าพเจ้าจะไม่ขัดสน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 2, 'พระองค์ทรงกระทําให้ข้าพเจ้านอนลงที่ทุ่งหญ้าเขียวสด พระองค์ทรงนําข้าพเจ้าไปริมน้ําแดนสงบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 3, 'พระองค์ทรงฟื้นจิตวิญญาณของข้าพเจ้า พระองค์ทรงนําข้าพเจ้าไปในทางชอบธรรม เพราะเห็นแก่พระนามของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 4, 'แม้ข้าพระองค์จะเดินไปตามหุบเขาเงามัจจุราช ข้าพระองค์ไม่กลัวอันตรายใดๆ เพราะพระองค์ทรงสถิตกับข้าพระองค์ คทาและธารพระกรของพระองค์เล้าโลมข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 5, 'พระองค์ทรงเตรียมสํารับให้ข้าพระองค์ต่อหน้าต่อตาศัตรูของข้าพระองค์ พระองค์ทรงเจิมศีรษะข้าพระองค์ด้วยน้ํามัน ขันน้ําของข้าพระองค์ก็ล้นอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 6, 'แน่ทีเดียวที่ความดีและความเมตตาจะติดตามข้าพเจ้าไปตลอดวันคืนชีวิตของข้าพเจ้า และข้าพเจ้าจะอยู่ในพระนิเวศของพระเยโฮวาห์สืบไปเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 1, 'เพลงสดุดีของดาวิดแผ่นดินโลกกับสรรพสิ่งในโลกนั้นเป็นของพระเยโฮวาห์ ทั้งพิภพกับบรรดาผู้ที่อยู่ในพิภพนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 2, 'เพราะพระองค์เองทรงประดิษฐานแผ่นดินไว้บนทะเลและทรงสถาปนามันไว้เหนือน้ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 3, 'ผู้ใดจะขึ้นไปบนภูเขาของพระเยโฮวาห์ และผู้ใดจะยืนอยู่ในที่บริสุทธิ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 4, 'คือผู้ที่มีมือสะอาดและใจบริสุทธิ์ ผู้ที่มิได้ปลงใจในสิ่งไร้สาระและมิได้ปฏิญาณอย่างหลอกลวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 5, 'เขาจะรับพระพรจากพระเยโฮวาห์ และความชอบธรรมจากพระเจ้าแห่งความรอดของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 6, 'อย่างนี้แหละเป็นยุคที่เสาะหาพระองค์ ที่เสาะหาพระพักตร์ของพระองค์ โอ ยาโคบเอ๋ย เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 7, 'โอ ประตูเมืองเอ๋ย จงยกหัวของเจ้าขึ้นเถิด บานประตูนิรันดร์เอ๋ย จงยกขึ้นเถิด เพื่อกษัตริย์ผู้ทรงสง่าราศีจะได้เสด็จเข้ามา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 8, 'กษัตริย์ผู้ทรงสง่าราศีนั้นคือผู้ใด คือพระเยโฮวาห์ ผู้เข้มแข็งและทรงอานุภาพ พระเยโฮวาห์ผู้ทรงอานุภาพในสงคราม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 9, 'โอ ประตูเมืองเอ๋ย จงยกหัวของเจ้าขึ้นเถิด บานประตูนิรันดร์เอ๋ย จงยกขึ้นเถิด เพื่อกษัตริย์ผู้ทรงสง่าราศีจะได้เสด็จเข้ามา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 10, 'กษัตริย์ผู้ทรงสง่าราศีนั้นคือผู้ใด คือพระเยโฮวาห์จอมโยธา พระองค์ทรงเป็นกษัตริย์ผู้ทรงสง่าราศี เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 1, 'เพลงสดุดีของดาวิดโอ ข้าแต่พระเยโฮวาห์ จิตวิญญาณข้าพระองค์ตั้งใจแน่วแน่ในพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 2, 'โอ ข้าแต่พระเจ้าของข้าพระองค์ ข้าพระองค์วางใจในพระองค์ ขออย่าให้ข้าพระองค์ได้อาย ขออย่าให้ศัตรูของข้าพระองค์ได้ไชโยเหนือข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 3, 'เออ อย่าให้ผู้ใดๆที่เฝ้าพระองค์อยู่นั้นได้อาย แต่ผู้ที่ละเมิดโดยไม่มีเหตุนั้นขอให้ได้รับความอาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 4, 'โอ ข้าแต่พระเยโฮวาห์ ขอทรงกระทําให้ข้าพระองค์รู้จักพระมรรคาของพระองค์ ขอทรงสอนวิถีของพระองค์แก่ข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 5, 'ขอทรงนําข้าพระองค์ไปในความจริงของพระองค์ และขอทรงสอนข้าพระองค์ เพราะพระองค์ทรงเป็นพระเจ้าแห่งความรอดของข้าพระองค์ ข้าพระองค์รอคอยพระองค์อยู่วันยังค่ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 6, 'โอ ข้าแต่พระเยโฮวาห์ ขอทรงระลึกถึงพระกรุณาของพระองค์และถึงความเมตตาของพระองค์ ด้วยสิ่งเหล่านั้นมีมาแต่กาลก่อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 7, 'ขออย่าทรงนึกถึงบาปในวัยหนุ่มของข้าพระองค์ หรือการละเมิดของข้าพระองค์ โอ ข้าแต่พระเยโฮวาห์ ด้วยเห็นแก่ความดีของพระองค์ ขอทรงนึกถึงข้าพระองค์ด้วยเห็นแก่ความเมตตาของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 8, 'พระเยโฮวาห์ทรงเป็นผู้ประเสริฐและเที่ยงธรรม เพราะฉะนั้นพระองค์จะทรงสั่งสอนพระมรรคานั้นแก่คนบาป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 9, 'พระองค์จะทรงนําคนใจถ่อมไปในสิ่งที่ถูก และทรงสอนมรรคาของพระองค์แก่คนใจถ่อม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 10, 'พระมรรคาทั้งสิ้นของพระเยโฮวาห์เป็นความเมตตาและความจริง แก่บรรดาผู้ที่รักษาพันธสัญญาและบรรดาพระโอวาทของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 11, 'โอ ข้าแต่พระเยโฮวาห์ เพื่อเห็นแก่พระนามของพระองค์ ขอทรงให้อภัยความชั่วช้าของข้าพระองค์ เพราะความชั่วนั้นใหญ่โตนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 12, 'ผู้ใดเล่าที่เป็นคนยําเกรงพระเยโฮวาห์ พระองค์จะทรงสั่งสอนผู้นั้นในทางที่เขาควรเลือกได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 13, 'จิตวิญญาณเขาเองจะอาศัยอยู่อย่างสงบ และเชื้อสายของเขาจะได้แผ่นดินเป็นกรรมสิทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 14, 'ความลึกลับของพระเยโฮวาห์มีอยู่แก่คนที่ยําเกรงพระองค์ และพระองค์จะทรงแจ้งพันธสัญญาของพระองค์แก่เขาเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 15, 'ตาของข้าพเจ้าจ้องตรงพระเยโฮวาห์เสมอ เพราะพระองค์จะทรงถอนเท้าของข้าพเจ้าออกจากข่าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 16, 'ขอพระองค์ทรงหันมาทางข้าพระองค์ และมีพระเมตตาต่อข้าพระองค์ เพราะข้าพระองค์ว้าเหว่และเป็นทุกข์อยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 17, 'ความยากลําบากในใจของข้าพระองค์ก็ขยายกว้างออกไป โอ ขอทรงนําข้าพระองค์ออกจากความทุกข์ใจของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 18, 'ขอทรงพิจารณาความทุกข์ยากและความยากลําบากของข้าพระองค์ และทรงยกบาปทั้งสิ้นของข้าพระองค์เสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 19, 'ขอทรงพิจารณาว่าคู่อริของข้าพระองค์มีมากเท่าใด และเขาเกลียดชังข้าพระองค์ด้วยความเกลียดอย่างทารุณสักเพียงใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 20, 'โอ ขอทรงระแวดระวังชีวิตของข้าพระองค์ และช่วยข้าพระองค์ให้พ้น ขออย่าให้ข้าพระองค์ได้รับความอาย เพราะข้าพระองค์วางใจในพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 21, 'ขอให้ความสุจริตและความเที่ยงธรรมสงวนข้าพระองค์ไว้ เพราะข้าพระองค์รอคอยพระองค์อยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 22, 'โอ ข้าแต่พระเจ้า ขอทรงไถ่อิสราเอลออกจากความยากลําบากทั้งสิ้นของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 1, 'เพลงสดุดีของดาวิดโอ ข้าแต่พระเยโฮวาห์ ขอทรงตัดสินเข้าข้างข้าพระองค์ เพราะข้าพระองค์ดําเนินอยู่ในความสุจริตของข้าพระองค์ ข้าพระองค์ได้วางใจในพระเยโฮวาห์ ฉะนั้นข้าพระองค์จะไม่พลาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 2, 'โอ ข้าแต่พระเยโฮวาห์ ขอพิสูจน์ข้าพระองค์ และลองข้าพระองค์เถิด ทดสอบใจและจิตของข้าพระองค์เถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 3, 'เพราะความเมตตาของพระองค์อยู่ต่อตาข้าพระองค์ และข้าพระองค์ดําเนินในความจริงของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 4, 'ข้าพระองค์มิได้นั่งอยู่กับคนไร้สาระ หรือจะมิได้สมาคมกับคนมารยา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 5, 'ข้าพระองค์เกลียดชุมนุมคนที่ทําชั่ว และข้าพระองค์จะไม่นั่งกับคนชั่ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 6, 'โอ ข้าแต่พระเยโฮวาห์ เพื่อความบริสุทธิ์ข้าพระองค์จะชําระมือและจะเดินอยู่รอบแท่นของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 7, 'พลางประกาศด้วยเสียงแห่งการโมทนาพระคุณและบอกเล่าถึงพระราชกิจมหัศจรรย์ทั้งสิ้นของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 8, 'ข้าแต่พระเยโฮวาห์ ข้าพระองค์รักพระนิเวศอันเป็นที่ประทับของพระองค์ และสถานที่ประทับแห่งเกียรติยศของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 9, 'ขออย่าทรงกวาดจิตวิญญาณข้าพระองค์ไปกับคนบาป หรือกวาดชีวิตของข้าพระองค์ไปกับคนกระหายเลือด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 10, 'คือคนซึ่งในมือของเขามีแผนการชั่ว และมือขวาของเขาเต็มด้วยสินบน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 11, 'แต่สําหรับข้าพระองค์ ข้าพระองค์เดินในความสุจริต ขอทรงไถ่ข้าพระองค์และทรงกรุณาต่อข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 12, 'เท้าของข้าพระองค์เหยียบอยู่บนพื้นราบ ข้าพระองค์จะสรรเสริญพระเยโฮวาห์ในที่ชุมนุมชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 1, 'เพลงสดุดีของดาวิดพระเยโฮวาห์ทรงเป็นความสว่างและความรอดของข้าพเจ้า ข้าพเจ้าจะกลัวผู้ใดเล่า พระเยโฮวาห์ทรงเป็นที่กําบังเข้มแข็งแห่งชีวิตข้าพเจ้า ข้าพเจ้าจะต้องเกรงใคร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 2, 'เมื่อคนชั่วได้เข้ามาหาข้าพเจ้าเพื่อจะกินเนื้อข้าพเจ้า คือปฏิปักษ์และคู่อริของข้าพเจ้า เขาได้สะดุดและล้มลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 3, 'แม้กองทัพตั้งค่ายสู้ข้าพเจ้า จิตใจของข้าพเจ้าจะไม่กลัว แม้ข้าพเจ้าจะได้รับภัยสงคราม ข้าพเจ้ายังไว้ใจได้อยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 4, 'ข้าพเจ้าทูลขอสิ่งหนึ่งจากพระเยโฮวาห์ซึ่งข้าพเจ้าจะเสาะแสวงหาเสมอ คือที่ข้าพเจ้าจะได้อยู่ในพระนิเวศของพระเยโฮวาห์ตลอดวันเวลาชั่วชีวิตของข้าพเจ้า เพื่อจะดูความงามของพระเยโฮวาห์ และเพื่อจะพินิจพิจารณาอยู่ในพระวิหารของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 5, 'เพราะพระองค์จะทรงซ่อนข้าพเจ้าในที่กําบังของพระองค์ในยามยากลําบาก พระองค์จะปิดข้าพเจ้าไว้ในที่ซ่อนเร้นแห่งพลับพลาของพระองค์ พระองค์จะทรงตั้งข้าพเจ้าไว้สูงบนศิลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 6, 'และบัดนี้ศีรษะของข้าพเจ้าจะเชิดขึ้นเหนือศัตรูของข้าพเจ้าที่อยู่รอบข้าง ฉะนั้นข้าพเจ้าจะถวายเครื่องสัตวบูชาแห่งการโห่ร้องในพลับพลาของพระองค์ ข้าพเจ้าจะร้องเพลงและร้องเพลงสรรเสริญแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 7, 'โอ ข้าแต่พระเยโฮวาห์ ขอทรงสดับเมื่อข้าพระองค์ร้องทูลด้วยเสียงของข้าพระองค์ ขอทรงกรุณาและตรัสตอบข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 8, 'พระองค์ตรัสแล้วว่า “จงแสวงหาหน้าของเรา” จิตใจของข้าพระองค์ทูลพระองค์ว่า “ข้าแต่พระเยโฮวาห์ ข้าพระองค์จะแสวงหาพระพักตร์ของพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 9, 'ขออย่าทรงซ่อนพระพักตร์ของพระองค์จากข้าพระองค์ อย่าผลักไสผู้รับใช้ของพระองค์ออกไปเสียด้วยความกริ้ว พระองค์ทรงเป็นผู้อุปถัมภ์ของข้าพระองค์ โอ ข้าแต่พระเจ้าแห่งความรอดของข้าพระองค์ ขออย่าทรงทิ้งข้าพระองค์ หรือสละข้าพระองค์เสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 10, 'แม้บิดาและมารดาของข้าพระองค์ทอดทิ้งข้าพระองค์ แต่พระเยโฮวาห์จะทรงยกข้าพระองค์ขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 11, 'โอ ข้าแต่พระเยโฮวาห์ ขอสอนมรรคาของพระองค์แก่ข้าพระองค์ และทรงนําข้าพระองค์ไปบนวิถีราบ เหตุด้วยศัตรูของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 12, 'ขออย่าทรงมอบข้าพระองค์ไว้กับปฏิปักษ์ให้เขาทําตามใจชอบ เพราะพยานเท็จได้ลุกขึ้นสู้ข้าพระองค์ และเขาหายใจออกมาเป็นความทารุณ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 13, 'ข้าพเจ้าคงหมดสติไปนอกจากข้าพเจ้าเชื่อว่า ข้าพเจ้าจะเห็นความดีของพระเยโฮวาห์ที่ในแผ่นดินของคนเป็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 14, 'จงรอคอยพระเยโฮวาห์ จงเข้มแข็ง และพระองค์จะทําให้จิตใจของท่านกล้าหาญ เออ จงรอคอยพระเยโฮวาห์เถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 1, 'เพลงสดุดีของดาวิดโอ ข้าแต่พระเยโฮวาห์ ข้าพระองค์ร้องทูลต่อพระองค์ ศิลาของข้าพระองค์ ขออย่าให้พระกรรณหนวกต่อข้าพระองค์ เกรงว่าถ้าพระองค์ทรงเงียบอยู่ต่อข้าพระองค์ ข้าพระองค์จะเป็นเหมือนคนเหล่านั้นที่ลงไปยังปากแดนผู้ตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 2, 'ขอทรงสดับเสียงวิงวอนของข้าพระองค์ ขณะเมื่อข้าพระองค์ร้องทูลขอความอุปถัมภ์จากพระองค์ ขณะเมื่อข้าพระองค์ยกมือของข้าพระองค์ขึ้นตรงต่อที่บริสุทธิ์ที่สุดของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 3, 'ขออย่าทรงกวาดข้าพระองค์ไปพร้อมกับคนชั่ว กับบรรดาคนที่กระทําความชั่วช้า ผู้พูดอย่างสันติกับเพื่อนบ้านของตน แต่การปองร้ายอยู่ในใจของเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 4, 'ขอทรงสนองเขาตามการงานของเขา และตามความชั่วแห่งกิจการของเขา ขอทรงสนองเขาตามงานน้ํามือของเขา และทรงตอบแทนเขาตามสมควร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 5, 'เพราะเขาไม่นับถือพระราชกิจของพระเยโฮวาห์ หรือพระหัตถกิจของพระองค์ พระองค์จะทรงพังเขาลงและไม่สร้างเขาขึ้นอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 6, 'สาธุการแด่พระเยโฮวาห์ เพราะพระองค์ทรงสดับเสียงวิงวอนของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 7, 'พระเยโฮวาห์ทรงเป็นกําลังและเป็นโล่ของข้าพเจ้า จิตใจของข้าพเจ้าวางใจในพระองค์ ข้าพเจ้าจึงได้รับความอุปถัมภ์ ฉะนั้นจิตใจของข้าพเจ้าจึงปีติยินดียิ่ง ข้าพเจ้าจะถวายโมทนาแด่พระองค์ด้วยบทเพลงของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 8, 'พระเยโฮวาห์ทรงเป็นกําลังของเขาทั้งหลาย พระองค์ทรงเป็นป้อมแห่งความรอดของผู้รับเจิมของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 9, 'ขอทรงช่วยประชาชนของพระองค์ให้รอด และอํานวยพระพรแก่มรดกของพระองค์ ขอทรงเป็นผู้เลี้ยงดูเขา และหอบหิ้วเขาไปเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 1, 'เพลงสดุดีของดาวิดโอ ข้าแต่ท่านผู้มีฤทธิ์ทั้งหลาย จงถวายแด่พระเยโฮวาห์เถิด จงถวายสง่าราศีและพระกําลังแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 2, 'จงถวายสง่าราศีซึ่งควรแก่พระนามของพระองค์แด่พระเยโฮวาห์ จงนมัสการพระเยโฮวาห์ด้วยเครื่องประดับแห่งความบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 3, 'พระสุรเสียงของพระเยโฮวาห์อยู่เหนือน้ํา พระเจ้าแห่งสง่าราศีทรงคะนองเสียง คือพระเยโฮวาห์ทรงอยู่เหนือน้ําทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 4, 'พระสุรเสียงของพระเยโฮวาห์ทรงฤทธานุภาพ พระสุรเสียงของพระเยโฮวาห์เต็มด้วยความสูงส่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 5, 'พระสุรเสียงของพระเยโฮวาห์หักต้นสนสีดาร์ พระเยโฮวาห์ทรงหักต้นสนสีดาร์แห่งเลบานอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 6, 'พระองค์ทรงกระทําให้พวกเขากระโดดเหมือนลูกวัว เลบานอนและสีรีออนเหมือนม้ายูนิคอนหนุ่ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 7, 'พระสุรเสียงของพระเยโฮวาห์แยกเปลวเพลิงออกจากกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 8, 'พระสุรเสียงของพระเยโฮวาห์สั่นถิ่นทุรกันดาร พระเยโฮวาห์ทรงสั่นถิ่นทุรกันดารแห่งเมืองคาเดช');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 9, 'พระสุรเสียงของพระเยโฮวาห์กระทําให้กวางตัวเมียตกลูก และทําให้ป่าดงโหรงเหรง และในพระวิหารของพระองค์ทุกคนกล่าวถึงสง่าราศีของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 10, 'พระเยโฮวาห์ประทับเหนือน้ําท่วม พระเยโฮวาห์ประทับเป็นกษัตริย์เป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 11, 'พระเยโฮวาห์จะทรงประทานกําลังแก่ประชาชนของพระองค์ พระเยโฮวาห์จะทรงอํานวยพระพรแก่ประชาชนของพระองค์ให้มีสันติภาพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 1, 'เพลงสดุดีและบทเพลงของดาวิด ณ พิธีถวายพระราชวังของดาวิดโอ ข้าแต่พระเยโฮวาห์ ข้าพระองค์จะยอพระเกียรติพระองค์ เพราะพระองค์ทรงดึงข้าพระองค์ขึ้นมา และมิได้ทรงให้คู่อริของข้าพระองค์เปรมปรีดิ์เพราะข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 2, 'โอ ข้าแต่พระเยโฮวาห์พระเจ้าของข้าพระองค์ ข้าพระองค์ร้องทูลขอความอุปถัมภ์จากพระองค์ และพระองค์ได้ทรงรักษาข้าพระองค์ให้หาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 3, 'โอ ข้าแต่พระเยโฮวาห์ พระองค์ทรงนําจิตวิญญาณของข้าพระองค์ขึ้นมาจากแดนผู้ตาย ทรงให้ข้าพระองค์มีชีวิต เพื่อข้าพระองค์ไม่ต้องลงไปสู่ปากแดนผู้ตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 4, 'โอ ท่านวิสุทธิชนของพระองค์เอ๋ย จงร้องสรรเสริญพระเยโฮวาห์ และถวายโมทนาเมื่อระลึกถึงความบริสุทธิ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 5, 'เพราะพระพิโรธของพระองค์นั้นเป็นแต่ชั่วขณะหนึ่ง และความโปรดปรานของพระองค์นั้นตลอดชีวิต การร้องไห้อาจจะอ้อยอิ่งอยู่สักคืนหนึ่ง แต่ความชื่นบานจะมาเวลาเช้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 6, 'ข้าพระองค์พูดในความเจริญรุ่งเรืองของข้าพระองค์ว่า “ข้าพเจ้าจะไม่หวั่นไหวเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 7, 'ข้าแต่พระเยโฮวาห์ โดยความโปรดปรานของพระองค์ พระองค์ทรงสถาปนาข้าพระองค์ไว้อย่างภูเขาเข้มแข็ง พอพระองค์ทรงซ่อนพระพักตร์ของพระองค์ ข้าพระองค์ก็ลําบากใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 8, 'โอ ข้าแต่พระเยโฮวาห์ ข้าพระองค์ร้องทูลต่อพระองค์ และข้าพระองค์ได้วิงวอนพระเยโฮวาห์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 9, '“จะได้กําไรอะไรจากโลหิตของข้าพระองค์เมื่อข้าพระองค์ลงไปยังปากแดนผู้ตาย ผงคลีจะสรรเสริญพระองค์หรือ มันจะบอกเล่าเรื่องความจริงของพระองค์หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 10, 'โอ ข้าแต่พระเยโฮวาห์ ขอทรงสดับและทรงพระกรุณาต่อข้าพระองค์ ข้าแต่พระเยโฮวาห์ ขอทรงเป็นผู้อุปถัมภ์ของข้าพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 11, 'สําหรับข้าพระองค์ พระองค์ทรงเปลี่ยนการไว้ทุกข์เป็นการเต้นรํา พระองค์ทรงถอดเสื้อผ้ากระสอบของข้าพระองค์ออก และทรงคาดเอวข้าพระองค์ด้วยความยินดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 12, 'เพื่อจิตวิญญาณของข้าพระองค์จะร้องเพลงสรรเสริญพระองค์และไม่นิ่งเงียบ โอ ข้าแต่พระเยโฮวาห์พระเจ้าของข้าพระองค์ ข้าพระองค์จะถวายโมทนาแด่พระองค์เป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 1, 'ถึงหัวหน้านักร้อง เพลงสดุดีของดาวิดโอ ข้าแต่พระเยโฮวาห์ ข้าพระองค์วางใจในพระองค์ ขออย่าให้ข้าพระองค์ได้อายเลย ขอทรงช่วยข้าพระองค์ให้พ้นในความชอบธรรมของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 2, 'ขอทรงเงี่ยพระกรรณให้แก่ข้าพระองค์ ขอทรงช่วยข้าพระองค์ให้รอดอย่างรวดเร็วเถิด ขอพระองค์ทรงเป็นศิลาเข้มแข็งของข้าพระองค์ เป็นป้อมปราการเข้มแข็งที่จะช่วยข้าพระองค์ให้รอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 3, 'พระเจ้าข้า พระองค์ทรงเป็นศิลาและเป็นป้อมปราการของข้าพระองค์ ขอทรงพาและนําข้าพระองค์ด้วยเห็นแก่พระนามของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 4, 'ขอทรงปลดข้าพระองค์ออกจากข่ายที่พวกเขาวางอย่างลับๆเพื่อดักข้าพระองค์ เพราะพระองค์ทรงเป็นกําลังของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 5, 'ข้าพระองค์มอบจิตวิญญาณของข้าพระองค์ไว้ในพระหัตถ์ของพระองค์ โอ ข้าแต่พระเยโฮวาห์พระเจ้าแห่งความจริง พระองค์ทรงไถ่ข้าพระองค์แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 6, 'ข้าพระองค์เกลียดบรรดาผู้ที่นับถือพระเทียมเท็จ แต่ข้าพระองค์วางใจในพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 7, 'ข้าพระองค์จะเปรมปรีดิ์และยินดีในความเมตตาของพระองค์ เพราะพระองค์ทรงทอดพระเนตรความทุกข์ใจของข้าพระองค์ พระองค์ทรงทราบเรื่องความทุกข์ยากแห่งจิตวิญญาณของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 8, 'และมิได้ทรงมอบข้าพระองค์ไว้ในมือของศัตรู พระองค์ทรงวางเท้าของข้าพระองค์ไว้ในที่กว้างขวาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 9, 'โอ ข้าแต่พระเยโฮวาห์ ขอทรงพระกรุณาแก่ข้าพระองค์ เพราะข้าพระองค์กําลังทุกข์ใจ นัยน์ตาของข้าพระองค์ก็ร่วงโรยไปเพราะความระทม ทั้งจิตวิญญาณและร่างกายของข้าพระองค์ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 10, 'เพราะชีวิตของข้าพระองค์ก็ร่อยหรอไปด้วยความทุกข์โศก และปีเดือนของข้าพระองค์ก็หมดไปด้วยการถอนหายใจ กําลังของข้าพระองค์อ่อนลงเพราะความชั่วช้าของข้าพระองค์ และกระดูกของข้าพระองค์ก็ร่วงโรยไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 11, 'ข้าพระองค์เป็นที่นินทาท่ามกลางบรรดาปฏิปักษ์ของข้าพระองค์ โดยเฉพาะท่ามกลางเพื่อนบ้านของข้าพระองค์ เป็นเรื่องน่าครั่นคร้ามของผู้ที่คุ้นเคย ผู้ที่เห็นข้าพระองค์ในถนนก็หนีข้าพระองค์ไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 12, 'เขาลืมข้าพระองค์เสียประหนึ่งว่าเป็นคนตายแล้ว ข้าพระองค์เหมือนอย่างภาชนะที่แตก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 13, 'พระเจ้าข้า ข้าพระองค์ได้ยินเสียงซุบซิบของคนเป็นอันมาก มีความสยดสยองอยู่ทุกด้าน ขณะเมื่อเขาร่วมกันคิดแผนการต่อสู้ข้าพระองค์ ขณะที่เขาปองร้ายชีวิตของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 14, 'โอ ข้าแต่พระเยโฮวาห์ แต่ข้าพระองค์วางใจในพระองค์ ข้าพระองค์ทูลว่า “พระองค์ทรงเป็นพระเจ้าของข้าพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 15, 'วันเวลาของข้าพระองค์อยู่ในพระหัตถ์ของพระองค์ ขอพระองค์ทรงช่วยข้าพระองค์ให้พ้นมือศัตรูและผู้ข่มเหงของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 16, 'ขอพระพักตร์พระองค์ทอแสงบนผู้รับใช้ของพระองค์ ขอทรงช่วยข้าพระองค์ให้รอดด้วยความเมตตาของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 17, 'โอ ข้าแต่พระเยโฮวาห์ ขออย่าให้ข้าพระองค์ได้อาย เพราะข้าพระองค์ร้องทูลพระองค์ ขอให้คนชั่วได้อาย ขอให้เขาเงียบเสียงไปยังแดนผู้ตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 18, 'ขอให้ริมฝีปากที่มุสาเป็นใบ้ ซึ่งพูดทะลึ่งอวดดีต่อคนชอบธรรม ด้วยความจองหองและการดูหมิ่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 19, 'โอ ความดีของพระองค์อุดมสักเท่าใดที่พระองค์ทรงสะสมไว้เพื่อบรรดาผู้ที่เกรงกลัวพระองค์ และทรงกระทําไว้เพื่อผู้ที่วางใจในพระองค์ ต่อหน้าบุตรทั้งหลายของมนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 20, 'พระองค์ทรงซ่อนเขาไว้ในความลึกลับแห่งพระพักตร์พระองค์ให้พ้นจากการปองร้ายของมนุษย์ พระองค์ทรงยึดเขาไว้อย่างลึกลับในที่กําบังของพระองค์ให้พ้นจากลิ้นที่ทะเลาะวิวาท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 21, 'สาธุการแด่พระเยโฮวาห์ เพราะพระองค์ทรงสําแดงความเมตตาอย่างมหัศจรรย์ของพระองค์แก่ข้าพระองค์ในเมืองเข้มแข็ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 22, 'ด้วยข้าพระองค์กล่าวอย่างรีบร้อนว่า “ข้าพระองค์ถูกตัดขาดไปพ้นสายพระเนตรของพระองค์แล้ว” แต่พระองค์ยังทรงได้ยินเสียงแห่งคําวิงวอนของข้าพระองค์ เมื่อข้าพระองค์ร้องทูลขอต่อพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 23, 'โอ ท่านบรรดาวิสุทธิชนทั้งสิ้นของพระองค์เอ๋ย จงรักพระเยโฮวาห์ เพราะพระเยโฮวาห์ทรงพิทักษ์รักษาคนสัตย์ซื่อไว้ แต่ทรงสนองผู้กระทําอหังการอย่างเต็มขนาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 24, 'จงเข้มแข็ง และพระองค์จะให้ใจของท่านกล้าหาญ ท่านทั้งปวงผู้หวังใจในพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 1, 'เพลงสดุดีของดาวิด มัสคิลบทหนึ่งบุคคลผู้ซึ่งได้รับอภัยการละเมิดแล้วก็เป็นสุข คือผู้ที่บาปของเขาได้รับการกลบเกลื่อนแล้วนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 2, 'บุคคลซึ่งพระเยโฮวาห์มิได้ทรงถือโทษความชั่วช้าก็เป็นสุข คือผู้ที่ไม่มีการหลอกลวงในใจของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 3, 'เมื่อข้าพระองค์นิ่งเงียบ ร่างกายของข้าพระองค์ก็ร่วงโรยไปโดยการคร่ําครวญวันยังค่ําของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 4, 'พระหัตถ์ของพระองค์หนักอยู่บนข้าพระองค์ทั้งวันทั้งคืน กําลังของข้าพระองค์ก็เหี่ยวแห้งไปอย่างความร้อนในหน้าแล้ง เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 5, 'ข้าพระองค์สารภาพบาปของข้าพระองค์ต่อพระองค์ และข้าพระองค์มิได้ซ่อนความชั่วช้าของข้าพระองค์ไว้ ข้าพระองค์ทูลว่า “ข้าพระองค์จะสารภาพการละเมิดของข้าพระองค์ต่อพระเยโฮวาห์” แล้วพระองค์ทรงยกโทษความชั่วช้าแห่งความบาปของข้าพระองค์ เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 6, 'เพราะฉะนั้นทุกคนที่ตามทางของพระเจ้าจะอธิษฐานต่อพระองค์ในเวลาที่จะพบพระองค์ได้ ในเวลาน้ําท่วมมาก น้ําจะไม่มาถึงคนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 7, 'พระองค์ทรงเป็นที่ซ่อนของข้าพระองค์ พระองค์ทรงสงวนข้าพระองค์ไว้จากความยากลําบาก พระองค์ทรงล้อมข้าพระองค์ไว้ด้วยเพลงฉลองการช่วยให้พ้น เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 8, 'เราจะแนะนําและสอนเจ้าถึงทางที่เจ้าควรจะเดินไป เราจะให้คําปรึกษาแก่เจ้าด้วยจับตาเจ้าอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 9, 'อย่าเป็นเหมือนม้าหรือล่อที่ปราศจากความเข้าใจ ซึ่งต้องติดเหล็กขวางปากและบังเหียน มิฉะนั้นมันก็จะเข้ามาหาเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 10, 'อันความทุกข์ของคนชั่วนั้นมีมาก แต่ความเมตตาจะล้อมบุคคลที่วางใจในพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 11, 'ท่านผู้ชอบธรรมเอ๋ย จงยินดีในพระเยโฮวาห์ และเปรมปรีดิ์ บรรดาท่านผู้มีใจเที่ยงตรงจงโห่ร้องด้วยความชื่นบานเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 1, 'โอ ท่านผู้ชอบธรรม จงเปรมปรีดิ์ในพระเยโฮวาห์ การสรรเสริญนั้นควรแก่คนเที่ยงธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 2, 'จงสรรเสริญพระเยโฮวาห์ด้วยพิณเขาคู่ จงถวายสดุดีแด่พระองค์ด้วยพิณใหญ่และพิณสิบสาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 3, 'จงร้องเพลงบทใหม่ถวายพระองค์ จงดีดสายอย่างแคล่วคล่องพร้อมกับโห่ร้อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 4, 'เพราะพระวจนะของพระเยโฮวาห์เที่ยงธรรม และบรรดาพระราชกิจของพระองค์ก็สําเร็จด้วยความจริง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 5, 'พระองค์ทรงรักความชอบธรรมและความยุติธรรม แผ่นดินโลกเต็มด้วยความดีของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 6, 'โดยพระวจนะของพระเยโฮวาห์ฟ้าสวรรค์ก็ถูกสร้างขึ้นมา กับบริวารทั้งปวงด้วยลมพระโอษฐ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 7, 'พระองค์ทรงรวบรวมน้ําทะเลไว้ด้วยกันเป็นกองใหญ่ และทรงเก็บที่ลึกไว้ในคลัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 8, 'ให้แผ่นดินโลกทั้งสิ้นยําเกรงพระเยโฮวาห์ ให้บรรดาชาวพิภพทั้งปวงยืนตะลึงพรึงเพริดต่อพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 9, 'เพราะพระองค์ตรัส มันก็เกิดขึ้นมา พระองค์ทรงบัญชา มันก็ออกมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 10, 'พระเยโฮวาห์ทรงให้การปรึกษาของชาติต่างๆเปล่าประโยชน์ พระองค์ทรงให้แผนงานของชนชาติทั้งหลายไร้ผล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 11, 'คําปรึกษาของพระเยโฮวาห์ตั้งมั่นคงเป็นนิตย์ พระดําริในพระทัยของพระองค์อยู่ทุกชั่วอายุ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 12, 'ประชาชาติที่พระเจ้าของเขาคือพระเยโฮวาห์ก็เป็นสุข คือชนชาติซึ่งพระองค์ทรงเลือกสรรไว้เป็นมรดกของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 13, 'พระเยโฮวาห์ทอดพระเนตรจากฟ้าสวรรค์ พระองค์ทอดพระเนตรบุตรทั้งหลายของมนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 14, 'จากที่ซึ่งพระองค์ประทับพระองค์ทอดพระเนตรเหนือชาวแผ่นดินโลกทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 15, 'คือพระองค์ผู้ทรงประดิษฐ์จิตใจของเขาทั้งหลายทุกคน และทรงพิจารณากิจการของเขาทั้งหลายทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 16, 'กองทัพใหญ่หาช่วยให้กษัตริย์องค์หนึ่งองค์ใดรอดพ้นไปไม่ กําลังอันมากมายก็ไม่ช่วยนักรบให้พ้นได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 17, 'ม้าศึกจะเป็นที่หวังความปลอดภัยก็หาไม่ กําลังมหาศาลของมันก็ช่วยให้รอดไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 18, 'ดูเถิด พระเนตรของพระเยโฮวาห์อยู่เหนือผู้ที่ยําเกรงพระองค์ เหนือผู้ที่หวังในความเมตตาของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 19, 'เพื่อพระองค์จะทรงช่วยจิตวิญญาณของเขาให้พ้นจากมัจจุราช และให้เขาดํารงชีวิตอยู่ได้ในเวลากันดารอาหาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 20, 'จิตวิญญาณของเราทั้งหลายรอคอยพระเยโฮวาห์ พระองค์ทรงเป็นความอุปถัมภ์และเป็นโล่ของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 21, 'เออ จิตใจของเราทั้งหลายยินดีในพระองค์ เพราะเราวางใจในพระนามบริสุทธิ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 22, 'โอ ข้าแต่พระเยโฮวาห์ ขอความเมตตาของพระองค์จงอยู่เหนือข้าพระองค์ทั้งหลายตามที่ข้าพระองค์หวังใจในพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 1, 'เพลงสดุดีของดาวิดเมื่อท่านทําเป็นบ้าต่อหน้าอาบีเมเลค พระองค์จึงขับไล่ท่านออกไปเสียและท่านก็ไปข้าพเจ้าจะสรรเสริญพระเยโฮวาห์ตลอดไป คําสรรเสริญพระองค์อยู่ที่ปากข้าพเจ้าเรื่อยไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 2, 'จิตใจของข้าพเจ้าจะโอ้อวดในพระเยโฮวาห์ คนที่เสงี่ยมเจียมตัวจะฟังและยินดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 3, 'โอ เชิญยอพระเกียรติพระเยโฮวาห์พร้อมกับข้าพเจ้า ให้เราสรรเสริญพระนามของพระองค์ด้วยกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 4, 'ข้าพเจ้าได้แสวงหาพระเยโฮวาห์ และพระองค์ทรงฟังข้าพเจ้า และทรงช่วยข้าพเจ้าให้พ้นจากความกลัวทั้งสิ้นของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 5, 'เขาทั้งหลายเพ่งดูพระองค์ และเบิกบาน หน้าตาของเขาจึงไม่ต้องอาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 6, 'คนจนคนนี้ร้องทูล และพระเยโฮวาห์ทรงสดับ และทรงช่วยเขาให้พ้นจากความยากลําบากทั้งสิ้นของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 7, 'ทูตสวรรค์ของพระเยโฮวาห์ได้ตั้งค่ายล้อมบรรดาผู้ที่เกรงกลัวพระองค์ และช่วยเขาทั้งหลายให้รอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 8, 'โอ ขอเชิญชิมดูแล้วจะเห็นว่าพระเยโฮวาห์ประเสริฐ คนที่วางใจในพระองค์ก็เป็นสุข');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 9, 'โอ ท่านวิสุทธิชนทั้งหลายของพระองค์ จงยําเกรงพระเยโฮวาห์ เพราะผู้ที่ยําเกรงพระองค์ไม่ขาดแคลน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 10, 'เหล่าสิงโตหนุ่มยังขาดแคลนและหิวโหย แต่บรรดาผู้ที่แสวงหาพระเยโฮวาห์จะไม่ขาดของดีใดๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 11, 'บุตรทั้งหลายเอ๋ย มาเถิด มาฟังเรา เราจะสอนเจ้าถึงความเกรงกลัวพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 12, 'มนุษย์คนใดผู้ปรารถนาชีวิตและรักวันคืนทั้งหลาย เพื่อเขาจะได้เห็นของดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 13, 'จงระวังลิ้นของเจ้าจากความชั่ว และอย่าให้ริมฝีปากพูดเป็นอุบายล่อลวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 14, 'จงหนีความชั่ว และกระทําความดี แสวงหาความสงบสุขและดําเนินตามนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 15, 'พระเนตรของพระเยโฮวาห์เห็นคนชอบธรรม และพระกรรณของพระองค์สดับคําอ้อนวอนของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 16, 'พระพักตร์ของพระเยโฮวาห์ตั้งต่อสู้กับคนทั้งหลายที่ทําความชั่ว เพื่อจะตัดการระลึกถึงเขาเสียจากแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 17, 'เมื่อคนชอบธรรมร้องทูลขอ พระเยโฮวาห์ทรงสดับและทรงช่วยเขาให้พ้นจากความยากลําบากทั้งสิ้นของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 18, 'พระเยโฮวาห์ทรงอยู่ใกล้ผู้ที่จิตใจฟกช้ําและทรงช่วยผู้ที่จิตใจสํานึกผิดให้รอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 19, 'คนชอบธรรมนั้นถูกข่มใจหลายอย่าง แต่พระเยโฮวาห์ทรงช่วยเขาออกมาให้พ้นหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 20, 'พระองค์ทรงรักษากระดูกเขาไว้ทั้งหมด ไม่หักสักซี่เดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 21, 'ความชั่วจะสังหารคนชั่ว และคนทั้งหลายที่เกลียดชังคนชอบธรรมจะสาบสูญไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 22, 'พระเยโฮวาห์ทรงไถ่ชีวิตผู้รับใช้ของพระองค์ และไม่มีผู้ใดที่วางใจในพระองค์แล้วจะต้องสาบสูญไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 1, 'เพลงสดุดีของดาวิดโอ ข้าแต่พระเยโฮวาห์ ขอทรงผจญผู้ที่ผจญข้าพระองค์ ขอทรงสู้รบผู้ที่รบกับข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 2, 'ขอทรงถือโล่และดั้ง และทรงลุกขึ้นช่วยข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 3, 'ขอทรงเตรียมหอกและขวานศึกสู้ผู้ข่มเหงข้าพระองค์ ขอตรัสกับจิตใจของข้าพระองค์ว่า “เราเป็นผู้ช่วยให้รอดของเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 4, 'ผู้ที่แสวงหาชีวิตของข้าพระองค์นั้น ขอให้เขาได้อายและอัปยศ ผู้ที่ประดิษฐ์ความชั่วต่อสู้ข้าพระองค์นั้น ขอทรงให้เขากลับไปและอดสู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 5, 'ขอให้เขาเป็นเหมือนแกลบต่อหน้าลม และขอให้ทูตสวรรค์ของพระเยโฮวาห์ขับไล่ตามเขาไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 6, 'ขอให้ทางของเขามืดและลื่น และขอให้ทูตสวรรค์ของพระเยโฮวาห์ข่มเหงพวกเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 7, 'เพราะเขาเอาข่ายซ่อนดักข้าพระองค์ไว้อย่างไม่มีเหตุ เขาขุดหลุมพรางเอาชีวิตข้าพระองค์อย่างไม่มีเรื่อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 8, 'ขอให้ความพินาศมาถึงเขาอย่างไม่รู้ตัว และขอให้ข่ายที่เขาซ่อนไว้นั้นติดเขาเองและให้เขาติดข่ายพินาศเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 9, 'แล้วจิตวิญญาณของข้าพระองค์จะเปรมปรีดิ์ในพระเยโฮวาห์ เริงโลดอยู่ในการช่วยให้รอดของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 10, 'กระดูกทั้งสิ้นของข้าพระองค์จะกล่าวว่า “ข้าแต่พระเยโฮวาห์ มีผู้ใดเหมือนพระองค์ พระองค์ผู้ทรงช่วยคนยากจนให้พ้นจากผู้ที่เข้มแข็งเกินกําลังของเขา คนยากจนและคนขัดสนจากผู้ที่ปล้นเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 11, 'มีพยานเท็จลุกขึ้น เขาฟ้องสิ่งที่ข้าพระองค์ไม่ทราบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 12, 'เขาสนองข้าพระองค์โดยทําชั่วตอบความดี จิตใจของข้าพระองค์ก็ตรอมตรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 13, 'ส่วนข้าพระองค์ เมื่อเขาป่วยข้าพระองค์สวมผ้ากระสอบ ข้าพระองค์ข่มใจตนเองด้วยการอดอาหาร ข้าพระองค์ซบหน้าลงที่อกอธิษฐาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 14, 'ข้าพระองค์ประพฤติอย่างที่เขาเป็นเพื่อนหรือพี่น้องของข้าพระองค์ ข้าพระองค์คอตกและร้องไห้คร่ําครวญเหมือนคนไว้ทุกข์ให้มารดา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 15, 'แต่พอข้าพระองค์สะดุด เขาก็ชุมนุมกันอย่างชอบใจ นักเลงหัวไม้รวบรวมกันมาสู้กับข้าพระองค์ ข้าพระองค์ยังไม่รู้ แต่พวกเขาได้ด่าว่าข้าพระองค์อย่างไม่หยุดยั้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 16, 'เขาเยาะเย้ยอย่างคนหน้าซื่อใจคดในการเลี้ยงต่างๆ ขบเขี้ยวเคี้ยวฟันใส่ข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 17, 'ข้าแต่องค์พระผู้เป็นเจ้า พระองค์จะทอดพระเนตรเมินเฉยอีกนานเท่าใด ขอทรงช่วยจิตวิญญาณข้าพระองค์ให้พ้นจากการร้ายกาจของเขา ช่วยชีวิตข้าพระองค์จากหมู่สิงโต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 18, 'แล้วข้าพระองค์จะโมทนาพระคุณพระองค์ในที่ชุมนุมใหญ่ ข้าพระองค์จะสรรเสริญพระองค์ท่ามกลางคนเป็นอันมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 19, 'ขออย่าให้คู่อริอย่างไร้เหตุผลนั้นมีความเปรมปรีดิ์เหนือข้าพระองค์ และอย่าให้บรรดาผู้ที่เกลียดชังข้าพระองค์อย่างไม่มีเหตุได้หลิ่วตาให้กัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 20, 'เพราะเขาไม่พูดอย่างสันติ แต่เขาคิดถ้อยคําหลอกลวงต่อบรรดาผู้ที่สงบเงียบในแผ่นดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 21, 'เขาอ้าปากกว้างใส่ข้าพระองค์ เขากล่าวว่า “อ้าฮา อ้าฮา เราเห็นกับตาแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 22, 'โอ ข้าแต่พระเยโฮวาห์ พระองค์ทอดพระเนตรแล้ว ขออย่าทรงนิ่งเสีย โอ ข้าแต่องค์พระผู้เป็นเจ้า ขออย่าทรงสถิตไกลจากข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 23, 'ข้าแต่พระเจ้าของข้าพระองค์ องค์พระผู้เป็นเจ้าของข้าพระองค์ ขอทรงร้อนพระทัย ตื่นขึ้นเพื่อเห็นแก่สิทธิของข้าพระองค์ เพื่อเห็นแก่เรื่องของข้าพระองค์เถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 24, 'โอ ข้าแต่พระเยโฮวาห์พระเจ้าของข้าพระองค์ ขอทรงให้ความยุติธรรมแก่ข้าพระองค์ตามความชอบธรรมของพระองค์ และขออย่าให้เขาเปรมปรีดิ์เหนือข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 25, 'อย่าให้เขาทั้งหลายรําพึงในใจว่า “เอ้อเฮอ เราได้ตามใจปรารถนาของเรา” อย่าให้เขากล่าวได้ว่า “เราได้กลืนเขาเสียแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 26, 'ขอให้เขาได้อายและได้ความยุ่งยากด้วยกัน คือเขาผู้เปรมปรีดิ์เพราะความลําเค็ญของข้าพระองค์ ให้เขาได้ห่มความอายและความอัปยศ คือผู้ที่เขาอวดตัวสู้ข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 27, 'ขอให้บรรดาผู้ที่เห็นชอบในเหตุอันชอบธรรมของข้าพระองค์โห่ร้องด้วยความชื่นบานและยินดี และกล่าวอยู่เสมอว่า “ขอให้พระเยโฮวาห์นั้นใหญ่ยิ่ง พระองค์ผู้ทรงปีติยินดีในความเจริญของผู้รับใช้ของพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 28, 'แล้วลิ้นของข้าพระองค์จะบอกเล่าถึงความชอบธรรมของพระองค์ และจะสรรเสริญพระองค์วันยังค่ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 1, 'ถึงหัวหน้านักร้อง เพลงสดุดีของดาวิด ผู้รับใช้ของพระเยโฮวาห์การละเมิดของคนชั่วล้วงลึกเข้าไปในใจของข้าพเจ้าว่า “ในแววตาของเขาไม่มีความเกรงกลัวพระเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 2, 'เพราะเขาป้อยอตนเองในสายตาของตนจนได้พบว่าความชั่วช้าของเขาเป็นสิ่งที่น่ารังเกียจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 3, 'ถ้อยคําจากปากของเขาก็ชั่วช้าและหลอกลวง เขาหยุดที่จะประพฤติอย่างฉลาดและกระทําความดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 4, 'เขาปองความชั่วร้ายเมื่อเขาอยู่บนที่นอนของเขา เขาวางตัวในทางที่ไม่ดี เขามิได้เกลียดชังความชั่ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 5, 'โอ ข้าแต่พระเยโฮวาห์ ความเมตตาของพระองค์อยู่ในฟ้าสวรรค์ ความสัตย์ซื่อของพระองค์ไปถึงเมฆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 6, 'ความชอบธรรมของพระองค์เหมือนภูเขาใหญ่ทั้งหลาย คําตัดสินของพระองค์เหมือนที่ลึกยิ่ง โอ ข้าแต่พระเยโฮวาห์ พระองค์ทรงช่วยมนุษย์และสัตว์ให้รอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 7, 'โอ ข้าแต่พระเจ้า ความเมตตาของพระองค์ประเสริฐสักเท่าใด บุตรทั้งหลายของมนุษย์เข้าลี้ภัยอยู่ใต้ร่มปีกของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 8, 'เขาอิ่มด้วยความอุดมสมบูรณ์แห่งพระนิเวศของพระองค์ และพระองค์จะประทานให้เขาดื่มจากแม่น้ําแห่งความสุขเกษมของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 9, 'เพราะธารน้ําพุแห่งชีวิตอยู่กับพระองค์ เราจะเห็นความสว่างโดยสว่างของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 10, 'โอ ขอประทานความเมตตาของพระองค์ต่อไปแก่ผู้ที่รู้จักพระองค์ และความชอบธรรมของพระองค์แก่คนใจเที่ยงธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 11, 'ขออย่าให้เท้าของคนจองหองมาเหนือข้าพระองค์ หรือให้มือของคนชั่วขับไล่ข้าพระองค์ไปเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 12, 'แล้วคนกระทําความชั่วช้าก็ล้มอยู่ที่นั่น เขาถูกผลักลง ลุกขึ้นอีกไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 1, 'เพลงสดุดีของดาวิดอย่าให้เจ้าเดือดร้อนเพราะเหตุคนที่กระทําชั่ว อย่าอิจฉาคนที่กระทําความชั่วช้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 2, 'เพราะไม่ช้าเขาจะเหี่ยวไปเหมือนหญ้า และแห้งไปเหมือนพืชสด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 3, 'จงวางใจในพระเยโฮวาห์ และกระทําความดี ท่านจึงจะอาศัยอยู่ในแผ่นดินและจะได้รับการเลี้ยงดูอย่างแท้จริง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 4, 'จงปีติยินดีในพระเยโฮวาห์และพระองค์จะประทานตามใจปรารถนาของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 5, 'จงมอบทางของท่านไว้กับพระเยโฮวาห์ วางใจในพระองค์ และพระองค์จะทรงกระทําให้สําเร็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 6, 'พระองค์จะทรงให้ความชอบธรรมของท่านกระจ่างอย่างความสว่าง และให้ความยุติธรรมของท่านแจ้งอย่างเที่ยงวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 7, 'จงสงบอยู่ต่อพระเยโฮวาห์ และเพียรรอคอยพระองค์อยู่ อย่าให้ใจของท่านเดือดร้อนเพราะเหตุผู้ที่เจริญตามทางของเขา หรือเพราะเหตุผู้ที่กระทําตามอุบายชั่ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 8, 'จงระงับความโกรธ และทิ้งความพิโรธ อย่าให้ใจเดือดร้อนของท่านนําท่านไปกระทําชั่ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 9, 'เพราะคนที่กระทําชั่วจะถูกตัดออกไป แต่คนเหล่านั้นที่รอคอยพระเยโฮวาห์จะได้แผ่นดินโลกเป็นมรดก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 10, 'ยังอีกหน่อยหนึ่งคนชั่วจะไม่มีอีก แม้จะมองดูที่ที่ของเขาให้ดี เขาก็ไม่ได้อยู่ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 11, 'แต่คนใจอ่อนสุภาพจะได้แผ่นดินตกไปเป็นมรดก และตัวเขาจะปีติยินดีในสันติภาพอุดมสมบูรณ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 12, 'คนชั่วปองร้ายคนชอบธรรม และขบเขี้ยวเคี้ยวฟันใส่เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 13, 'แต่องค์พระผู้เป็นเจ้าจะทรงพระสรวลต่อคนชั่ว เพราะพระองค์ทอดพระเนตรเห็นวันเวลาของเขากําลังมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 14, 'คนชั่วชักดาบและโก่งคันธนู เพื่อเอาคนจนและคนขัดสนลง เพื่อสังหารคนที่เดินอย่างเที่ยงธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 15, 'ดาบของเขาจะเข้าไปในใจของเขาเอง และคันธนูของเขาจะหัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 16, 'เล็กๆน้อยๆที่คนชอบธรรมมีก็ดีกว่าความอุดมสมบูรณ์ของคนชั่วเป็นอันมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 17, 'เพราะแขนของคนชั่วจะหัก แต่พระเยโฮวาห์ทรงเชิดชูคนชอบธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 18, 'พระเยโฮวาห์ทรงทราบวันเวลาของคนไร้ตําหนิ และมรดกของเขาจะดํารงอยู่เป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 19, 'เขาจะไม่ได้อายในยามชั่วร้าย ในวันกันดารเขาจะอิ่มใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 20, 'แต่คนชั่วจะพินาศ ศัตรูของพระเยโฮวาห์จะเหมือนสง่าของลูกแกะ เขาจะอันตรธานไป อันตรธานไปเหมือนควัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 21, 'คนชั่วขอยืมและไม่จ่ายคืน แต่คนชอบธรรมนั้นแสดงความเมตตาและแจกจ่าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 22, 'เพราะคนเช่นนั้นที่พระองค์ทรงอํานวยพระพรจะได้แผ่นดินโลกเป็นมรดก แต่คนทั้งหลายที่ถูกพระองค์สาปจะต้องถูกตัดออกไปเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 23, 'พระเยโฮวาห์ทรงนําย่างเท้าของคนดี และพระองค์ทรงพอพระทัยในทางของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 24, 'แม้เขาล้ม เขาจะไม่ถูกเหวี่ยงลงเหยียดยาว เพราะว่าพระหัตถ์พระเยโฮวาห์พยุงเขาไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 25, 'ข้าพเจ้าเคยหนุ่ม และเดี๋ยวนี้แก่แล้ว แต่ข้าพเจ้ายังไม่เคยเห็นคนชอบธรรมถูกทอดทิ้ง หรือเชื้อสายของเขาขอทาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 26, 'เขาแสดงความเมตตาและให้ยืมเสมอ และเชื้อสายของเขาก็ได้รับพระพร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 27, 'จงพรากเสียจากการชั่ว และกระทําความดี และท่านจะดํารงอยู่เป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 28, 'เพราะพระเยโฮวาห์ทรงรักการพิพากษา พระองค์จะไม่ทอดทิ้งวิสุทธิชนของพระองค์ จะทรงสงวนคนเหล่านั้นไว้เป็นนิตย์ แต่เชื้อสายของคนชั่วจะถูกตัดออกไปเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 29, 'คนชอบธรรมจะได้แผ่นดินตกไปเป็นมรดก และอาศัยอยู่บนนั้นเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 30, 'ปากของคนชอบธรรมเปล่งสติปัญญา และลิ้นของเขาพูดความยุติธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 31, 'พระราชบัญญัติของพระเจ้าอยู่ในจิตใจของเขา และย่างเท้าของเขาจะไม่พลาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 32, 'คนชั่วเฝ้าดูคนชอบธรรมและแสวงหาที่จะสังหารเขาเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 33, 'พระเยโฮวาห์จะไม่ทรงทิ้งเขาไว้ในมือของเขา หรือให้เขาถูกปรับโทษเมื่อเขาขึ้นศาล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 34, 'จงรอคอยพระเยโฮวาห์ และรักษาทางของพระองค์ไว้ และพระองค์จะยกย่องท่านให้ได้แผ่นดินโลกเป็นมรดก ท่านจะได้เห็นเมื่อคนชั่วถูกตัดออกไปเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 35, 'ข้าพเจ้าเห็นคนชั่วมีอํานาจมากยิ่ง และสูงเด่นอย่างต้นไม้เขียวสดที่อยู่ในท้องถิ่นของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 36, 'เขาได้ผ่านไป และดูเถิด ไม่มีเขาเสียแล้ว ถึงข้าพเจ้าจะแสวงหาเขา ก็ไม่พบเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 37, 'จงหมายคนไร้ตําหนิไว้ และมองดูคนเที่ยงธรรม เพราะอนาคตของคนนั้นคือสันติภาพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 38, 'แต่ผู้ละเมิดจะถูกทําลายเสียด้วยกัน จุดหมายปลายทางของคนชั่วจะถูกตัดออกไปเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 39, 'ความรอดของคนชอบธรรมมาจากพระเยโฮวาห์ พระองค์ทรงเป็นกําลังของเขาในเวลายากลําบาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 40, 'พระเยโฮวาห์จะทรงช่วยเขาและทรงช่วยเขาให้พ้น พระองค์จะทรงช่วยเขาให้พ้นจากคนชั่วและทรงช่วยเขาให้รอด เพราะเขาทั้งหลายวางใจในพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 1, 'เพลงสดุดีของดาวิด เพื่อการถวายบูชารําลึกโอ ข้าแต่พระเยโฮวาห์ ขออย่าทรงขนาบข้าพระองค์ด้วยความกริ้วของพระองค์ หรือตีสอนข้าพระองค์ด้วยพระพิโรธของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 2, 'เพราะลูกธนูของพระองค์จมเข้าไปในข้าพระองค์ และพระหัตถ์ของพระองค์ลงมาเหนือข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 3, 'เพราะพระพิโรธของพระองค์จึงไม่มีความปกติในเนื้อหนังของข้าพระองค์ เพราะบาปของข้าพระองค์จึงไม่มีอนามัยในกระดูกของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 4, 'เพราะความชั่วช้าของข้าพระองค์ท่วมศีรษะ มันหนักเหมือนภาระซึ่งหนักเหลือกําลังข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 5, 'เพราะความโง่เขลาของข้าพระองค์บาดแผลของข้าพระองค์จึงเหม็นและเปื่อยเน่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 6, 'ข้าพระองค์หนักใจ ข้าพระองค์ก็งอลงมาก ข้าพระองค์เดินเป็นทุกข์ไปวันยังค่ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 7, 'เพราะบั้นเอวของข้าพระองค์เต็มไปด้วยโรคที่น่ารังเกียจ และไม่มีความปกติในเนื้อหนังของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 8, 'ข้าพระองค์ร่วงโรยและฟกช้ําทีเดียว ข้าพระองค์ครวญครางเพราะใจข้าพระองค์ไม่สงบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 9, 'ข้าแต่องค์พระผู้เป็นเจ้า ความปรารถนาทั้งสิ้นของข้าพระองค์ก็แจ้งอยู่ต่อพระพักตร์พระองค์ การถอนหายใจของข้าพระองค์ก็ไม่พ้นที่พระองค์ทรงทราบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 10, 'หัวใจของข้าพระองค์เต้น และกําลังของข้าพระองค์หมดไป และความสว่างของนัยน์ตาของข้าพระองค์ก็สูญไปจากข้าพระองค์เสียแล้วด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 11, 'มิตรและเพื่อนของข้าพระองค์ยืนเด่นอยู่ห่างจากภัยพิบัติของข้าพระองค์ และญาติของข้าพระองค์ยืนห่างออกไปไกลโพ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 12, 'และบรรดาผู้ที่แสวงหาชีวิตของข้าพระองค์ได้วางบ่วงไว้ บรรดาผู้ที่คิดทําร้ายข้าพระองค์พูดเป็นอุบาย และรําพึงถึงการทรยศอยู่วันยังค่ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 13, 'แต่ข้าพระองค์เหมือนคนหูหนวก ข้าพระองค์ไม่ได้ยิน ข้าพระองค์เหมือนคนใบ้ผู้ไม่อ้าปากของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 14, 'พ่ะย่ะค่ะ ข้าพระองค์เหมือนคนที่ไม่ได้ยิน ซึ่งในปากของเขาไม่มีการตัดพ้อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 15, 'โอ ข้าแต่พระเยโฮวาห์ แต่ข้าพระองค์หวังใจในพระองค์ โอ ข้าแต่องค์พระผู้เป็นเจ้าพระเจ้าของข้าพระองค์คือพระองค์ผู้ที่จะทรงฟังข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 16, 'เพราะข้าพระองค์ทูลว่า “โปรดฟังข้าพระองค์เถิด มิฉะนั้นพวกเขาจะเปรมปรีดิ์เพราะข้าพระองค์ คือผู้ที่โอ้อวดต่อข้าพระองค์เมื่อเท้าข้าพระองค์พลาดไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 17, 'เพราะข้าพระองค์จะล้มแล้ว และความเศร้าโศกอยู่ต่อหน้าข้าพระองค์เสมอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 18, 'ข้าพระองค์จะสารภาพความชั่วช้าของข้าพระองค์ ข้าพระองค์จะเป็นทุกข์เพราะบาปของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 19, 'บรรดาผู้ที่เป็นคู่อริของข้าพระองค์ก็ว่องไวและแข็งแรง และคนที่เกลียดข้าพระองค์โดยไร้เหตุทวีมากขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 20, 'บรรดาผู้ที่กระทําชั่วแก่ข้าพระองค์ตอบแทนความดี เป็นปฏิปักษ์ของข้าพระองค์ เพราะข้าพระองค์ติดตามความดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 21, 'โอ ข้าแต่พระเยโฮวาห์ ขออย่าทรงทอดทิ้งข้าพระองค์ โอ ข้าแต่พระเจ้าของข้าพระองค์ ขออย่าสถิตไกลจากข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 22, 'โอ ข้าแต่องค์พระผู้เป็นเจ้า ความรอดของข้าพระองค์ ขอทรงรีบมาช่วยข้าพระองค์เถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 1, 'ถึงหัวหน้านักร้อง ถึงเยดูธูน เพลงสดุดีของดาวิดข้าพเจ้าว่า “ข้าพเจ้าจะระแวดระวังทางของข้าพเจ้า เพื่อข้าพเจ้าจะไม่ทําบาปด้วยลิ้นของข้าพเจ้า ข้าพเจ้าจะใส่บังเหียนปากของข้าพเจ้า ตราบเท่าที่คนชั่วอยู่ต่อหน้าข้าพเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 2, 'ข้าพเจ้าก็เป็นใบ้เงียบไป ข้าพเจ้านิ่งเงียบแม้แต่จากสิ่งที่ดี ความทุกข์ใจของข้าพเจ้ารุนแรงขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 3, 'จิตใจข้าพเจ้าร้อนอยู่ภายในข้าพเจ้า ขณะที่ข้าพเจ้ากําลังรําพึงอยู่นั้นไฟก็ลุก ข้าพเจ้าจึงพูดด้วยลิ้นของข้าพเจ้าว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 4, '“ข้าแต่พระเยโฮวาห์ ขอให้ข้าพระองค์ทราบถึงบั้นปลายของข้าพระองค์ และวันเวลาของข้าพระองค์จะนานสักเท่าใด เพื่อข้าพระองค์จะทราบว่าข้าพระองค์อ่อนแอแค่ไหน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 5, 'ดูเถิด พระองค์ทรงกระทําให้วันเวลาของข้าพระองค์ยาวสองสามฝ่ามือเท่านั้น ชั่วชีวิตของข้าพระองค์ไม่เท่าไรเลยเฉพาะพระพักตร์พระองค์ มนุษย์ทุกคนดํารงอยู่อย่างไร้สาระแน่ทีเดียว เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 6, 'มนุษย์ทุกคนดําเนินไปอย่างเงาแน่ทีเดียว เขาทั้งหลายยุ่งอยู่เปล่าๆแน่ทีเดียว มนุษย์โกยกองไว้ และไม่ทราบว่าใครจะเก็บไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 7, 'ข้าแต่องค์พระผู้เป็นเจ้า บัดนี้ข้าพระองค์จะรอคอยอะไร ความหวังของข้าพระองค์อยู่ในพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 8, 'ขอทรงช่วยข้าพระองค์ให้พ้นจากการละเมิดทั้งสิ้นของข้าพระองค์ อย่าให้ข้าพระองค์เป็นที่นินทาของคนโง่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 9, 'ข้าพระองค์เป็นใบ้ ข้าพระองค์ไม่อ้าปาก เป็นพระองค์เองที่ทรงกระทําเช่นนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 10, 'ขอทรงถอนโทษทัณฑ์จากข้าพระองค์เสียเถิด ข้าพระองค์ร่วงโรยไปด้วยการทุบตีจากพระหัตถ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 11, 'เมื่อพระองค์ทรงตีสอนมนุษย์ด้วยการขนาบเพราะเรื่องความชั่วช้า พระองค์ทรงเผาผลาญความสวยงามของเขาเสียอย่างตัวมอด มนุษย์ทุกคนก็ไร้สาระแน่ทีเดียว” เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 12, '“โอ ข้าแต่พระเยโฮวาห์ ขอทรงสดับคําอธิษฐานของข้าพระองค์ ขอทรงเงี่ยพระกรรณแก่การร้องทูลของข้าพระองค์ ขออย่าทรงเฉยเมยต่อน้ําตาของข้าพระองค์ เพราะข้าพระองค์เป็นแต่แขกที่ผ่านไปของพระองค์ เป็นคนที่อาศัยอยู่อย่างบรรพบุรุษทั้งหลายของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 13, 'โอ ขอทรงเมินพระพักตร์จากข้าพระองค์ เพื่อข้าพระองค์จะเบิกบานขึ้น ก่อนที่ข้าพระองค์จะจากไปและไม่มีอยู่อีก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 1, 'ถึงหัวหน้านักร้อง เพลงสดุดีของดาวิดข้าพเจ้าได้เพียรรอคอยพระเยโฮวาห์ พระองค์ทรงเอนพระองค์ลงสดับคําร้องทูลของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 2, 'พระองค์ทรงฉุดข้าพเจ้าขึ้นมาจากหลุมอันน่ากลัว ออกมาจากเลนตม แล้ววางเท้าของข้าพเจ้าลงบนศิลา กระทําให้ย่างเท้าของข้าพเจ้ามั่นคง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 3, 'พระองค์ทรงบรรจุเพลงใหม่ในปากข้าพเจ้า เป็นบทเพลงสรรเสริญพระเจ้าของเรา คนเป็นอันมากจะเห็นและเกรงกลัวและวางใจในพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 4, 'คนใดที่วางใจในพระเยโฮวาห์ก็เป็นสุข ผู้มิได้หันไปหาคนจองหองหรือไปหาบรรดาผู้ที่หลงเจิ่นไปตามความเท็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 5, 'โอ ข้าแต่พระเยโฮวาห์พระเจ้าของข้าพระองค์ พระองค์ได้ทรงทวีพระราชกิจอันมหัศจรรย์ของพระองค์ และพระดําริของพระองค์แก่ข้าพระองค์ ไม่มีผู้ใดรายงานพระราชกิจทั้งสิ้นเหล่านั้นได้ ถ้าข้าพระองค์จะประกาศและบอกกล่าวแล้ว ก็มีมากมายเหลือที่จะนับได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 6, 'เครื่องสัตวบูชาและเครื่องบูชาพระองค์ไม่ทรงประสงค์ พระองค์ทรงเบิกหูของข้าพระองค์ เครื่องเผาบูชาและเครื่องบูชาไถ่บาป พระองค์มิได้ทรงเรียกร้อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 7, 'แล้วข้าพระองค์ทูลว่า “ดูเถิด ข้าพระองค์มาแล้ว พระเจ้าข้า ในหนังสือม้วนก็มีเขียนเรื่องข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 8, 'โอ ข้าแต่พระเจ้าของข้าพระองค์ ข้าพระองค์ปีติยินดีที่กระทําตามน้ําพระทัยพระองค์ พระราชบัญญัติของพระองค์อยู่ในจิตใจของข้าพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 9, 'ข้าพระองค์ได้ประกาศเรื่องความชอบธรรมในชุมนุมชนใหญ่ โอ ข้าแต่พระเยโฮวาห์ ดูเถิด ตามที่พระองค์ทรงทราบแล้ว ข้าพระองค์มิได้ยับยั้งริมฝีปากของข้าพระองค์ไว้เลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 10, 'ข้าพระองค์มิได้ปกปิดความชอบธรรมของพระองค์ไว้แต่ในจิตใจของข้าพระองค์ ข้าพระองค์ได้พูดถึงความสัตย์ซื่อและความรอดของพระองค์ ข้าพระองค์มิได้ปิดบังความเมตตาและความจริงของพระองค์ไว้จากชุมนุมชนใหญ่โตนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 11, 'โอ ข้าแต่พระเยโฮวาห์ ขอพระองค์อย่าทรงยึดเหนี่ยวพระกรุณาคุณของพระองค์จากข้าพระองค์ ขอให้ความเมตตาและความจริงของพระองค์สงวนข้าพระองค์ไว้เป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 12, 'เพราะความชั่วได้ล้อมข้าพระองค์ไว้อย่างนับไม่ถ้วน ความชั่วช้าของข้าพระองค์ตามทันข้าพระองค์ จนข้าพระองค์มองอะไรไม่เห็น มันมากกว่าเส้นผมบนศีรษะข้าพระองค์ จิตใจของข้าพระองค์ก็ฝ่อไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 13, 'โอ ข้าแต่พระเยโฮวาห์ ขอทรงพอพระทัยที่จะช่วยข้าพระองค์ให้พ้น โอ ข้าแต่พระเยโฮวาห์ ขอทรงเร่งมาสงเคราะห์ข้าพระองค์เถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 14, 'ขอให้ผู้ที่หาโอกาสทําลายชีวิตของข้าพระองค์ได้อายและเกิดความยุ่งเหยิงด้วยกัน ขอให้ผู้ปรารถนาสิ่งชั่วร้ายต่อข้าพระองค์นั้นต้องหันกลับไปและได้ความอัปยศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 15, 'ขอให้คนเหล่านั้นสาบสูญไปเพื่อเป็นรางวัลสําหรับความน่าละอายที่เขาได้พูดกับข้าพระองค์ว่า “อ้าฮา อ้าฮา” นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 16, 'ขอให้บรรดาผู้แสวงหาพระองค์เปรมปรีดิ์และยินดีในพระองค์ ขอให้บรรดาผู้ที่รักความรอดของพระองค์ กล่าวเสมอว่า “พระเยโฮวาห์ใหญ่ยิ่งนัก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 17, 'ฝ่ายข้าพระองค์ยากจนและขัดสน แต่องค์พระผู้เป็นเจ้าทรงเอาพระทัยใส่ข้าพระองค์ โอ ข้าแต่พระเจ้าของข้าพระองค์ ขออย่าทรงรอช้า พระองค์ทรงเป็นผู้อุปถัมภ์และเป็นผู้ช่วยให้พ้นของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 1, 'ถึงหัวหน้านักร้อง เพลงสดุดีของดาวิดผู้ใดเอาใจใส่คนจนก็เป็นสุข พระเยโฮวาห์จะทรงช่วยเขาให้พ้นในวันยากลําบาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 2, 'พระเยโฮวาห์จะทรงป้องกันเขาและรักษาเขาให้มีชีวิต ในแผ่นดินเขาจะได้รับพระพร พระองค์จะไม่ทรงมอบเขาไว้กับศัตรูของเขาให้ทําตามใจชอบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 3, 'เมื่อเขาอยู่บนที่นอนด้วยความอิดโรยพระเยโฮวาห์จะทรงทําให้เขาแข็งแรงขึ้น เมื่อเขาอยู่บนที่นอนแห่งความเจ็บไข้พระองค์จะทรงรักษาเขาให้หายหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 4, 'ข้าพระองค์ทูลว่า “ข้าแต่พระเยโฮวาห์ ขอทรงพระกรุณาแก่ข้าพระองค์ ขอทรงรักษาจิตวิญญาณข้าพระองค์ เพราะข้าพระองค์ได้ทําบาปต่อพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 5, 'ศัตรูของข้าพระองค์กล่าวใส่ร้ายข้าพระองค์ว่า “เมื่อไรเขาจะตายนะ และชื่อของเขาจะได้พินาศ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 6, 'ถ้าคนหนึ่งคนใดมาเห็นข้าพระองค์ เขาจะพูดเรื่องไร้สาระ ขณะที่ใจของเขาเก็บเรื่องความชั่วช้า เมื่อเขาออกไปเขาก็ป่าวร้องไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 7, 'ทุกคนที่เกลียดข้าพระองค์ เขาซุบซิบกันถึงเรื่องข้าพระองค์ เขาปองร้ายต่อข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 8, 'เขาทั้งหลายกล่าวว่า “โรคร้ายเข้าไปอยู่ในตัวเขาแล้ว เขาจะไม่ลุกไปจากที่ที่เขานอนนั้นอีก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 9, 'แม้ว่าเพื่อนในอกของข้าพระองค์ ผู้ซึ่งข้าพระองค์ไว้วางใจ ผู้ที่รับประทานอาหารของข้าพระองค์ได้ยกส้นเท้าต่อข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 10, 'โอ ข้าแต่พระเยโฮวาห์ ขอแต่พระองค์ทรงพระกรุณาต่อข้าพระองค์ ขอทรงยกข้าพระองค์ขึ้น เพื่อข้าพระองค์จะสนองเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 11, 'โดยข้อนี้ ข้าพระองค์ทราบว่า พระองค์ทรงพอพระทัยในข้าพระองค์ คือศัตรูของข้าพระองค์ไม่ได้ชนะข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 12, 'แต่พระองค์ทรงค้ําชูข้าพระองค์ไว้เพราะความสัตย์สุจริตของข้าพระองค์ และทรงตั้งข้าพระองค์ไว้ต่อเบื้องพระพักตร์พระองค์เป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 13, 'สาธุการแด่พระเยโฮวาห์พระเจ้าแห่งอิสราเอลเป็นนิตย์ในอดีต และสืบไปเป็นนิตย์ เอเมนและเอเมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 1, 'ถึงหัวหน้านักร้อง มัสคิลบทหนึ่งของคณะโคราห์กวางกระเสือกกระสนหาลําธารที่มีน้ําไหลฉันใด โอ ข้าแต่พระเจ้า จิตวิญญาณของข้าพระองค์ก็กระเสือกกระสนหาพระองค์ฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 2, 'จิตวิญญาณของข้าพเจ้ากระหายหาพระเจ้า หาพระเจ้าผู้ทรงพระชนม์ เมื่อไรข้าพเจ้าจะได้มาปรากฏต่อพระพักตร์พระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 3, 'ข้าพเจ้ากินน้ําตาต่างอาหารทั้งวันคืน ขณะที่คนพูดกับข้าพเจ้าวันแล้ววันเล่าว่า “พระเจ้าของเจ้าอยู่ที่ไหน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 4, 'เมื่อข้าพเจ้าระลึกถึงสิ่งเหล่านี้ ข้าพเจ้าก็ระบายความในใจออกมาได้ เพราะข้าพเจ้าไปกับประชาชน คือไปกับพวกเขาถึงพระนิเวศของพระเจ้า ด้วยเสียงโห่ร้องยินดีและเสียงเพลงโมทนา คือมวลชนกําลังมีเทศกาลฉลอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 5, 'โอ จิตใจของข้าพเจ้าเอ๋ย ไฉนเจ้าจึงฝ่ออยู่ ไฉนเจ้าจึงกระสับกระส่ายอยู่ในข้าพเจ้า เจ้าจงหวังใจในพระเจ้า เพราะข้าพเจ้าจะยังคงสรรเสริญพระองค์สําหรับความช่วยเหลือที่มาจากพระพักตร์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 6, 'โอ ข้าแต่พระเจ้าของข้าพระองค์ จิตใจของข้าพระองค์ฝ่ออยู่ภายในข้าพระองค์ เพราะฉะนั้นข้าพระองค์จึงจะระลึกถึงพระองค์ ตั้งแต่แผ่นดินแห่งแม่น้ําจอร์แดนและแห่งภูเขาเฮอร์โมนตั้งแต่เนินมิซาร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 7, 'เมื่อเสียงน้ําแก่งตกที่ลึกก็กู่เรียกที่ลึก บรรดาคลื่นและระลอกของพระองค์ท่วมข้าพระองค์แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 8, 'กลางวันพระเยโฮวาห์จะทรงบัญชาความเมตตาของพระองค์ และกลางคืนเพลงของพระองค์จะอยู่กับข้าพเจ้า พร้อมกับคําอธิษฐานต่อพระเจ้าแห่งชีวิตของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 9, 'ข้าพเจ้าทูลพระเจ้าศิลาของข้าพเจ้าว่า “ไฉนพระองค์ทรงลืมข้าพระองค์เสีย ไฉนข้าพระองค์จึงต้องไปอย่างเป็นทุกข์ เพราะการบีบบังคับของศัตรู”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 10, 'ปรปักษ์ของข้าพเจ้าเยาะเย้ยข้าพเจ้า ประดุจดาบภายในบรรดากระดูกของข้าพเจ้า ในเมื่อเขากล่าวแก่ข้าพเจ้าทุกวันว่า “พระเจ้าของเจ้าอยู่ที่ไหน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 11, 'โอ จิตใจของข้าพเจ้าเอ๋ย ไฉนเจ้าจึงฝ่ออยู่ ไฉนเจ้าจึงกระสับกระส่ายอยู่ในข้าพเจ้า เจ้าจงหวังใจในพระเจ้า เพราะข้าพเจ้าจะยังคงสรรเสริญพระองค์ ผู้ทรงเป็นสวัสดิภาพแห่งสีหน้าของข้าพเจ้า และพระเจ้าของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 1, 'โอ ข้าแต่พระเจ้า ขอทรงแก้แทนข้าพระองค์ และต่อสู้คดีของข้าพระองค์ต่อประชาชาติที่ไร้ธรรม โอ ขอทรงช่วยข้าพระองค์ให้พ้นจากคนล่อลวงและคนอธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 2, 'เพราะพระองค์ทรงเป็นพระเจ้าแห่งกําลังของข้าพระองค์ ไฉนพระองค์ทรงทอดทิ้งข้าพระองค์เสีย ไฉนข้าพระองค์จึงต้องไปอย่างเป็นทุกข์เพราะการบีบบังคับของศัตรู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 3, 'โอ ขอทรงโปรดใช้ความสว่างและความจริงของพระองค์ออกไปให้นําข้าพระองค์ ให้ทั้งสองนําข้าพระองค์มาถึงภูเขาบริสุทธิ์ของพระองค์ และถึงพลับพลาของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 4, 'แล้วข้าพระองค์จะไปยังแท่นบูชาของพระเจ้า ถึงพระเจ้าซึ่งเป็นความชื่นบานยอดยิ่งของข้าพระองค์ โอ ข้าแต่พระเจ้า พระเจ้าของข้าพระองค์ ข้าพระองค์จะถวายเพลงสดุดีแด่พระองค์ด้วยพิณเขาคู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 5, 'โอ จิตใจของข้าพเจ้าเอ๋ย ไฉนเจ้าจึงฝ่ออยู่ ไฉนเจ้าจึงกระสับกระส่ายอยู่ในข้าพเจ้า จงหวังใจในพระเจ้า เพราะข้าพเจ้าจะยังคงสรรเสริญพระองค์ ผู้ทรงเป็นสวัสดิภาพแห่งสีหน้าของข้าพเจ้า และพระเจ้าของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 1, 'ถึงหัวหน้านักร้อง มัสคิลบทหนึ่งของคณะโคราห์โอ ข้าแต่พระเจ้า ข้าพระองค์ทั้งหลายได้ยินกับหูของตน บรรพบุรุษของข้าพระองค์ทั้งหลายเล่าให้ฟัง ถึงกิจการซึ่งพระองค์ทรงกระทําในสมัยของเขา ในสมัยโบราณกาลนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 2, 'พระองค์ทรงขับไล่บรรดาประชาชาติออกไปด้วยพระหัตถ์ของพระองค์เอง แต่พระองค์ทรงปลูกบรรพบุรุษทั้งหลายไว้ พระองค์ทรงให้ชาติทั้งหลายทุกข์ใจ และได้ทรงขับไล่ชาติทั้งหลายนั้นออกไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 3, 'เพราะเขาทั้งหลายไม่ได้แผ่นดินนั้นมาครอบครองด้วยดาบของเขาเอง มิใช่แขนของเขาที่ช่วยให้เขารอด แต่โดยพระหัตถ์ขวา และพระกรของพระองค์ และโดยความสว่างจากสีพระพักตร์พระองค์ เพราะพระองค์ทรงโปรดปรานเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 4, 'โอ ข้าแต่พระเจ้า พระองค์ทรงเป็นกษัตริย์ของข้าพระองค์ ขอพระองค์ทรงบัญชาการช่วยให้พ้นไว้สําหรับยาโคบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 5, 'ข้าพระองค์ทั้งหลายดันศัตรูออกไปโดยพระองค์ ข้าพระองค์ทั้งหลายเหยียบคนที่ลุกขึ้นต่อสู้ข้าพระองค์ลงด้วยพระนามของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 6, 'เพราะข้าพระองค์ไม่วางใจในคันธนูของข้าพระองค์ และดาบของข้าพระองค์ช่วยข้าพระองค์ให้รอดไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 7, 'แต่พระองค์ได้ทรงช่วยข้าพระองค์ทั้งหลายให้รอดจากศัตรู และทรงให้ผู้เกลียดข้าพระองค์ได้ความอาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 8, 'ข้าพระองค์ทั้งหลายอวดถึงพระเจ้าได้ตลอดทั้งวัน และข้าพระองค์ทั้งหลายสรรเสริญพระนามของพระองค์เป็นนิตย์ เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 9, 'แต่พระองค์ยังทรงทอดทิ้งข้าพระองค์ทั้งหลายเสีย และให้ข้าพระองค์ได้ความอัปยศ และมิได้เสด็จออกไปกับกองทัพของข้าพระองค์ทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 10, 'พระองค์ทรงกระทําให้ข้าพระองค์ทั้งหลายถอยกลับจากคู่อริ และคนที่เกลียดข้าพระองค์ทั้งหลายก็ได้ของริบไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 11, 'พระองค์ทรงกระทําให้ข้าพระองค์ทั้งหลายเป็นดังแกะที่จะเอาไปกิน และทรงกระจายข้าพระองค์ทั้งหลายให้ไปอยู่ท่ามกลางบรรดาประชาชาติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 12, 'พระองค์ทรงขายประชาชนของพระองค์อย่างให้เปล่า ตามราคาไม่ทรงได้อะไรเพิ่มเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 13, 'พระองค์ทรงกระทําให้ข้าพระองค์เป็นที่นินทาของเพื่อนบ้าน เป็นที่เยาะเย้ยและดูหมิ่นแก่ผู้ที่อยู่รอบข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 14, 'พระองค์ทรงกระทําให้ข้าพระองค์ทั้งหลายเป็นคําครหาท่ามกลางประชาชาติ เป็นที่สั่นศีรษะท่ามกลางชาติทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 15, 'ความอัปยศอดสูอยู่ตรงหน้าข้าพระองค์วันยังค่ํา และความอับอายคลุมหน้าข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 16, 'เนื่องด้วยเสียงของคนเยาะเย้ย และคนหมิ่นประมาท เนื่องด้วยศัตรูและผู้แก้แค้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 17, 'สิ่งทั้งปวงนี้เกิดแก่ข้าพระองค์ทั้งหลาย แม้ว่าข้าพระองค์ไม่ลืมพระองค์ หรือทุจริตต่อพันธสัญญาของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 18, 'จิตใจของข้าพระองค์ทั้งหลายก็มิได้หันกลับ ย่างเท้าของข้าพระองค์ทั้งหลายก็มิได้พรากจากพระมรรคาของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 19, 'ถึงแม้พระองค์ทรงให้ข้าพระองค์ทั้งหลายแหลกลาญในที่ของมังกร และคลุมข้าพระองค์ทั้งหลายไว้ด้วยเงามัจจุราช');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 20, 'ถ้าเราได้ลืมพระนามพระเจ้าของเรา หรือพนมมือของเราให้แก่พระอื่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 21, 'พระเจ้าจะไม่ทรงค้นหาเรื่องนี้หรือ เพราะพระองค์ทรงทราบความลึกลับของจิตใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 22, 'เพราะเห็นแก่พระองค์ ข้าพระองค์ทั้งหลายจึงถูกประหารวันยังค่ํา และนับว่าเป็นเหมือนแกะสําหรับจะเอาไปฆ่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 23, 'โอ ข้าแต่องค์พระผู้เป็นเจ้า ขอทรงตื่นเถิด ไฉนพระองค์บรรทมอยู่ ขอทรงตื่นขึ้นเถิด ขออย่าทรงทอดทิ้งข้าพระองค์เสียตลอดกาล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 24, 'ไฉนพระองค์ทรงซ่อนพระพักตร์ของพระองค์เสีย ไฉนพระองค์ทรงลืมการที่ข้าพระองค์ทั้งหลายทุกข์ยากและถูกบีบบังคับเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 25, 'เพราะจิตวิญญาณข้าพระองค์ทั้งหลายโน้มถึงผงคลี ร่างกายของข้าพระองค์ทั้งหลายเกาะติดดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 26, 'ลุกขึ้นเถิด พระเจ้าข้า ขอเสด็จมาช่วยข้าพระองค์ทั้งหลาย ขอทรงไถ่ข้าพระองค์ไว้เพื่อเห็นแก่ความเมตตาของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 1, 'ถึงหัวหน้านักร้อง ตามทํานองโชชานิม มัสคิลบทหนึ่งของคณะโคราห์ เพลงแห่งความรักจิตใจข้าพเจ้าล้นไหลด้วยแนวคิดดี ข้าพเจ้าเล่าบทประพันธ์ของข้าพเจ้าถวายกษัตริย์ ลิ้นของข้าพเจ้าเหมือนปากกาของอาลักษณ์ที่ชํานาญ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 2, 'พระองค์ท่านงามเลิศยิ่งกว่าบุตรทั้งหลายของมนุษย์ พระคุณหลั่งลงบนริมฝีปากของพระองค์ท่าน เพราะฉะนั้นพระเจ้าทรงอํานวยพระพรพระองค์ท่านตลอดกาล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 3, 'โอ ข้าแต่องค์ผู้ทรงมหิทธิฤทธิ์ ขอทรงขัดดาบไว้ที่เอวของพระองค์ท่าน โดยสง่าราศีและความสูงส่งของพระองค์ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 4, 'ขอทรงม้าอย่างสง่างามเสด็จไปอย่างมีชัย เพื่อเห็นแก่ความจริง ความอ่อนสุภาพและความชอบธรรม ให้พระหัตถ์ขวาของพระองค์ท่านสอนกิจอันน่าครั่นคร้ามแก่พระองค์ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 5, 'ลูกธนูของพระองค์ท่านก็คมอยู่ในจิตใจของศัตรูของกษัตริย์ ชนชาติทั้งหลายจึงล้มอยู่ใต้พระองค์ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 6, 'โอ พระเจ้าข้า พระที่นั่งของพระองค์ดํารงเป็นนิตย์และเป็นนิตย์ ธารพระกรแห่งอาณาจักรของพระองค์ก็เป็นธารพระกรเที่ยงธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 7, 'พระองค์ทรงรักความชอบธรรมและทรงเกลียดชังความชั่วช้า ฉะนั้นพระเจ้าคือพระเจ้าของพระองค์ท่านได้ทรงเจิมพระองค์ท่านไว้ ด้วยน้ํามันแห่งความยินดียิ่งกว่าพระสหายทั้งปวงของพระองค์ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 8, 'บรรดาฉลองพระองค์ของพระองค์ท่านก็หอมฟุ้งไปด้วยกลิ่นมดยอบ กฤษณา และการบูรจากพระราชวังงาช้าง ฉลองพระองค์เหล่านี้กระทําให้พระองค์ท่านยินดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 9, 'ในหมู่สตรีผู้มีเกียรติของพระองค์ท่านมีราชธิดาของบรรดากษัตริย์ พระราชินีประดับทองคําเมืองโอฟีร์ประทับอยู่ข้างขวาพระหัตถ์พระองค์ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 10, 'โอ ธิดาเอ๋ย จงพิเคราะห์ ฟังและเอียงหูของเธอลง จงลืมชนชาติของเธอ และลืมบ้านบิดาของเธอเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 11, 'และกษัตริย์จะทรงปรารถนาความงามของเธอ เนื่องจากพระองค์ท่านเป็นเจ้านายของเธอ จงโค้งลงให้พระองค์ท่านเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 12, 'ธิดาของเมืองไทระจะเอาของกํานัลมากํานัลเธอ คือเศรษฐีมั่งคั่งที่สุดของประชาชนจะขอความกรุณาจากเธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 13, 'เจ้าหญิงประดับพระกายในห้องของพระนางเธอด้วยเสื้อผ้ายกทองคํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 14, 'เขาจะนําพระนางผู้ทรงเสื้อหลายสีเข้าเฝ้ากษัตริย์ และจะนําหญิงพรหมจารีผู้ติดตามคือเพื่อนเจ้าสาวมาถวายพระองค์ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 15, 'เขาทั้งหลายจะถูกนําไปด้วยความชื่นบานและยินดี เขาจะเข้าไปในพระราชวัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 16, 'บรรดาโอรสของพระองค์ท่านจะแทนบรรพบุรุษของพระองค์ท่าน พระองค์ท่านจะแต่งตั้งให้เป็นเจ้านายทั่วแผ่นดินโลกทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 17, 'เราจะกระทําให้พระนามของพระองค์ท่านเป็นที่เชิดชูตลอดบรรดาชั่วอายุ ฉะนั้นชนชาติทั้งหลายจะสดุดีพระองค์ท่านเป็นนิจกาล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 1, 'ถึงหัวหน้านักร้อง ของคณะโคราห์ บทเพลงตามทํานองอาลาโมทพระเจ้าทรงเป็นที่ลี้ภัยและเป็นกําลังของข้าพระองค์ทั้งหลาย เป็นความช่วยเหลือที่พร้อมอยู่ในยามยากลําบาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 2, 'ฉะนั้นเราจะไม่กลัว แม้ว่าแผ่นดินโลกจะถูกยกออกไป แม้ว่าภูเขาทั้งหลายจะโคลงเคลงลงสู่สะดือทะเล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 3, 'แม้ว่าน้ําทะเลคึกคะนองและฟองฟู แม้ว่าภูเขาสั่นสะเทือนเพราะทะเลอลวนนั้น เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 4, 'มีแม่น้ําสายหนึ่ง ที่คลองระบายจะกระทําให้พระมหานครของพระเจ้ายินดี คือพลับพลาบริสุทธิ์ขององค์ผู้สูงสุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 5, 'พระเจ้าทรงสถิตกลางพระมหานคร เธอจะไม่โคลงเคลงย้ายไป พอรุ่งอรุณพระเจ้าก็ทรงช่วยเธอไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 6, 'บรรดาประชาชาติก็อลหม่าน และราชอาณาจักรทั้งหลายก็คลอนแคลน พระองค์ทรงเปล่งพระสุรเสียง แผ่นดินโลกก็ละลายไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 7, 'พระเยโฮวาห์จอมโยธาทรงสถิตกับเราทั้งหลาย พระเจ้าของยาโคบทรงเป็นที่ลี้ภัยของพวกเรา เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 8, 'มาเถิด มาดูพระราชกิจของพระเยโฮวาห์ ว่าพระองค์ทรงกระทําให้เกิดการรกร้างอะไรบ้างในแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 9, 'พระองค์ทรงให้สงครามสงบถึงที่สุดปลายแผ่นดินโลก พระองค์ทรงหักคันธนูและฟันหอกเสีย พระองค์ทรงเผารถรบเสียด้วยไฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 10, '“จงนิ่งเสีย และรู้เถอะว่า เราคือพระเจ้า เราจะเป็นที่ยกย่องท่ามกลางประชาชาติ เราจะเป็นที่ยกย่องในแผ่นดินโลก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 11, 'พระเยโฮวาห์จอมโยธาทรงสถิตกับเราทั้งหลาย พระเจ้าของยาโคบทรงเป็นที่ลี้ภัยของพวกเรา เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 1, 'ถึงหัวหน้านักร้อง เพลงสดุดีของคณะโคราห์โอ ดูก่อนชนชาติทั้งหลาย จงตบมือ จงโห่ร้องถวายพระเจ้าด้วยเสียงไชโย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 2, 'เพราะพระเยโฮวาห์องค์ผู้สูงสุดเป็นที่น่าคร้ามกลัว ทรงเป็นพระมหากษัตริย์ผู้ยิ่งใหญ่เหนือแผ่นดินโลกทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 3, 'พระองค์จะทรงปราบปรามชนชาติทั้งหลายให้อยู่ภายใต้เรา และชาวประเทศทั้งหลายให้อยู่ภายใต้เท้าของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 4, 'พระองค์จะทรงเลือกมรดกของเราให้เรา เป็นสิ่งภูมิใจของยาโคบที่พระองค์ทรงรัก เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 5, 'พระเยโฮวาห์เสด็จขึ้นด้วยเสียงโห่ร้อง พระเยโฮวาห์เสด็จขึ้นด้วยเสียงแตร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 6, 'จงร้องเพลงสรรเสริญถวายพระเจ้า จงร้องเพลงสรรเสริญเถิด จงร้องเพลงสรรเสริญถวายพระมหากษัตริย์ของเรา จงร้องเพลงสรรเสริญเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 7, 'เพราะพระเจ้าทรงเป็นกษัตริย์เหนือแผ่นดินโลกทั้งสิ้น จงร้องเพลงสรรเสริญด้วยความเข้าใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 8, 'พระเจ้าทรงครอบครองเหนือนานาประชาชาติ พระเจ้าทรงประทับบนพระที่นั่งแห่งความบริสุทธิ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 9, 'บรรดาเจ้านายของชนชาติทั้งหลายประชุมกัน เป็นประชาชนของพระเจ้าแห่งอับราฮัม เพราะบรรดาโล่ของแผ่นดินโลกเป็นของพระเจ้า พระองค์ทรงเป็นที่ยกย่องอย่างสูง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 1, 'บทเพลงและเพลงสดุดีของคณะโคราห์พระเยโฮวาห์นั้นยิ่งใหญ่และสมควรจะสรรเสริญอย่างยิ่ง ในนครแห่งพระเจ้าของเรา บนภูเขาแห่งความบริสุทธิ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 2, 'มองขึ้นไปก็ดูงาม เป็นความชื่นบานของแผ่นดินโลกทั้งสิ้น คือภูเขาศิโยน ด้านทิศเหนือ ซึ่งเป็นนครของพระมหากษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 3, 'ภายในปราสาททั้งหลายของนครนั้นก็เป็นที่ทราบกันแล้วว่า พระเจ้าทรงเป็นที่ลี้ภัยอันมั่นคง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 4, 'เพราะดูเถิด กษัตริย์ชุมนุมกันแล้วเสด็จไปด้วยกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 5, 'พอท่านทั้งหลายเห็นนครนั้นท่านก็พากันประหลาดใจ ท่านเป็นทุกข์ แล้วก็ตื่นหนีไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 6, 'ความตระหนกตกประหม่าจับใจท่านที่นั่น มีความทุกข์ระทมอย่างหญิงกําลังคลอดบุตร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 7, 'พระองค์ทรงฟาดทําลายกําปั่นแห่งทารชิชด้วยลมตะวันออก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 8, 'เราได้ยินอย่างไร เราก็ได้เห็นอย่างนั้น ในนครแห่งพระเยโฮวาห์จอมโยธา ในนครแห่งพระเจ้าของเรา ซึ่งพระเจ้าจะทรงสถาปนาไว้เป็นนิตย์ เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 9, 'โอ ข้าแต่พระเจ้า ข้าพระองค์ทั้งหลายคํานึงถึงความเมตตาของพระองค์ ในท่ามกลางพระวิหารของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 10, 'โอ ข้าแต่พระเจ้า พระนามของพระองค์ไปถึงที่สุดปลายแผ่นดินโลกอย่างไร คําสรรเสริญพระองค์ก็ไปถึงอย่างนั้น พระหัตถ์ขวาของพระองค์เต็มไปด้วยความชอบธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 11, 'ขอภูเขาศิโยนจงเปรมปรีดิ์ ขอธิดาแห่งยูดาห์จงยินดี เพราะเหตุคําตัดสินของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 12, 'จงเดินรอบศิโยน ไปให้รอบเถิด จงนับหอคอยของศิโยน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 13, 'จงสังเกตเชิงเทินของเธอให้ดี จงพิจารณาปราสาททั้งหลายของเธอ เพื่อท่านจะได้บอกคนชั่วอายุต่อไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 14, 'ว่านี่คือพระเจ้า ทรงเป็นพระเจ้าของเราเป็นนิจกาล พระองค์จะทรงเป็นผู้นําของเราจนถึงเวลาสิ้นชีวิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 1, 'ถึงหัวหน้านักร้อง เพลงสดุดีของคณะโคราห์ดูก่อนชาติทั้งหลาย จงฟังข้อความนี้ ชาวพิภพทั้งปวงเอ๋ย จงเงี่ยหูฟัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 2, 'ทั้งผู้ใหญ่ผู้น้อย ทั้งเศรษฐีและคนจนด้วยกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 3, 'ปากของข้าพเจ้าจะกล่าวถึงปัญญา การไตร่ตรองของจิตใจข้าพเจ้าจะอยู่ในเรื่องความเข้าใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 4, 'ข้าพเจ้าจะเอียงหูฟังคําอุปมา ข้าพเจ้าจะแก้ปริศนาของข้าพเจ้าให้เข้ากับเสียงพิณเขาคู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 5, 'ทําไมข้าพเจ้าจึงกลัวในคราวทุกข์ยากลําบาก เมื่อความชั่วช้าแห่งผู้ข่มเหงล้อมตัวข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 6, 'คนผู้วางใจในทรัพย์ศฤงคารของตัว และอวดอ้างความมั่งคั่งอันอุดมของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 7, 'แน่ทีเดียวไม่มีคนใดไถ่พี่น้องของตนได้ หรือถวายค่าชีวิตของเขาแด่พระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 8, '(เพราะค่าไถ่ชีวิตของเขานั้นแพงและไม่เคยพอเลย)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 9, 'ที่เขาจะมีชีวิตเรื่อยไปเป็นนิตย์และไม่ต้องเห็นความเปื่อยเน่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 10, 'เออ เขาเห็นว่า ถึงปราชญ์ก็ยังตาย คนโง่และคนโฉดก็ต้องพินาศเหมือนกัน และละทรัพย์ศฤงคารของตนไว้ให้คนอื่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 11, 'จิตใจเขาคิดว่าวงศ์วานของเขาจะดํารงอยู่เป็นนิตย์ และที่อาศัยของเขาจะอยู่ถึงทุกชั่วอายุ ถึงเขาเคยเรียกที่ดินของตัวตามชื่อของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 12, 'มนุษย์จะคงชีพในยศศักดิ์ของตนไม่ได้ เขาก็เหมือนสัตว์เดียรัจฉานที่พินาศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 13, 'วิถีทางของพวกเขาคือความโง่เขลา ถึงกระนั้นคนชั่วอายุต่อไปก็พอใจกับคํากล่าวของเขา เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 14, 'ดังแกะ เขาถูกกําหนดไว้ให้แก่แดนผู้ตาย มัจจุราชจะเป็นเมษบาลของเขา คนเที่ยงธรรมจะมีอํานาจเหนือเขาทั้งหลายในเวลาเช้า และความงามของเขาจะเปื่อยสิ้นไปในแดนผู้ตายซึ่งคือที่อาศัยของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 15, 'แต่พระเจ้าจะทรงไถ่จิตวิญญาณของข้าพเจ้าจากฤทธานุภาพของแดนผู้ตาย เพราะพระองค์จะทรงรับข้าพเจ้าไว้ เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 16, 'ท่านอย่ากลัวเมื่อผู้หนึ่งมั่งมีขึ้น เมื่อสง่าราศีของบ้านของเขาเพิ่มขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 17, 'เพราะเมื่อเขาตาย เขาจะไม่เอาอะไรไปเลย สง่าราศีของเขาจะไม่ลงไปตามเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 18, 'แม้ว่าเมื่อเขาเป็นอยู่ เขานับว่าตัวเขาสุขสบาย และคนอื่นจะยกย่องท่านเมื่อท่านเจริญ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 19, 'เขาจะไปอยู่กับพวกบรรพบุรุษของเขา ผู้ซึ่งจะไม่เห็นความสว่างเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 20, 'มนุษย์ซึ่งมียศศักดิ์ แต่ขาดความเข้าใจ เขาก็เหมือนสัตว์เดียรัจฉานที่พินาศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 1, 'เพลงสดุดีของอาสาฟพระเจ้าผู้ทรงมหิทธิฤทธิ์คือพระเยโฮวาห์ตรัสและทรงเรียกแผ่นดินโลก ตั้งแต่ที่ดวงอาทิตย์ขึ้นจนถึงที่ดวงอาทิตย์ตก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 2, 'พระเจ้าทรงทอแสงออกมาจากศิโยนนครแห่งความงามหมดจด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 3, 'พระเจ้าของเราจะเสด็จมา พระองค์จะมิได้ทรงเงียบอยู่ เพลิงจะเผาผลาญมาข้างหน้าพระองค์ รอบพระองค์คือวาตะอันทรงมหิทธิฤทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 4, 'พระองค์จะทรงเรียกถึงฟ้าสวรรค์เบื้องบน และถึงแผ่นดินโลก เพื่อพระองค์จะทรงพิพากษาประชาชนของพระองค์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 5, '“จงรวบรวมบรรดาวิสุทธิชนของเรามาให้เรา ผู้กระทําพันธสัญญากับเราด้วยเครื่องสัตวบูชา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 6, 'ฟ้าสวรรค์จะประกาศความชอบธรรมของพระองค์ เพราะพระเจ้านั่นแหละทรงเป็นผู้พิพากษา เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 7, '“โอ ประชาชนของเราเอ๋ย จงฟัง และเราจะพูด โอ อิสราเอลเอ๋ย เราจะเป็นพยานปรักปรําเจ้า เราเป็นพระเจ้า พระเจ้าของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 8, 'เราจะมิได้ตักเตือนเจ้าเรื่องเครื่องสัตวบูชาของเจ้า เครื่องเผาบูชาของเจ้ามีอยู่ต่อหน้าเราเสมอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 9, 'เราจะไม่รับวัวผู้จากเรือนของเจ้า หรือแพะผู้จากคอกของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 10, 'เพราะสัตว์ทุกตัวในป่าเป็นของเรา ทั้งสัตว์เลี้ยงบนภูเขาตั้งพันยอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 11, 'เรารู้จักบรรดานกแห่งภูเขาทั้งหลาย และบรรดาสัตว์ในนาเป็นของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 12, 'ถ้าเราหิว เราจะไม่บอกเจ้า เพราะพิภพและสารพัดที่อยู่ในนั้นเป็นของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 13, 'เราจะกินเนื้อวัวผู้หรือ หรือดื่มเลือดแพะหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 14, 'จงนําเครื่องการโมทนาพระคุณมาเป็นเครื่องสักการบูชาแด่พระเจ้า และทําตามคําปฏิญาณของเจ้าต่อองค์ผู้สูงสุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 15, 'และจงร้องทูลเราในวันทุกข์ยากลําบาก เราจะช่วยเจ้าให้พ้น และเจ้าจะถวายสง่าราศีแก่เรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 16, 'แต่พระเจ้าตรัสกับคนชั่วว่า “เจ้ามีสิทธิ์อะไรที่จะท่องกฎเกณฑ์ของเรา หรือรับปากตามพันธสัญญาของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 17, 'เพราะเจ้าเกลียดคําสั่งสอน และเจ้าเหวี่ยงคําของเราไว้ข้างหลังเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 18, 'เมื่อเจ้าเห็นโจร เจ้าก็คบเขา และเจ้าเข้าสังคมกับคนล่วงประเวณี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 19, 'เจ้าปล่อยปากของเจ้าให้พูดชั่ว และลิ้นของเจ้าประกอบการหลอกลวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 20, 'เจ้านั่งพูดใส่ร้ายพี่น้องของเจ้า เจ้านินทาลูกชายมารดาของเจ้าเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 21, 'เจ้าได้กระทําสิ่งเหล่านี้แล้ว เราก็นิ่งเงียบ เจ้าคิดว่าเราเป็นเหมือนเจ้า แต่เราจะขนาบเจ้า และเราจะรายงานสิ่งเหล่านั้นต่อหน้าต่อตาเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 22, 'เจ้าทั้งหลายผู้ลืมพระเจ้า จงพิจารณาเรื่องนี้ หาไม่เราจะฉีกเจ้าเป็นชิ้นๆ และจะไม่มีสักคนที่ช่วยเจ้าให้พ้นได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 23, 'บุคคลที่นําการสรรเสริญมาเป็นเครื่องสักการบูชาก็ให้เกียรติแก่เรา เราจะสําแดงความรอดของพระเจ้าแก่ผู้จัดทางของเขาอย่างถูกต้อง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 1, 'ถึงหัวหน้านักร้อง เพลงสดุดีของดาวิด เมื่อนาธันผู้พยากรณ์มาเฝ้าท่าน หลังจากที่ท่านเข้าหานางบัทเชบาแล้วโอ ข้าแต่พระเจ้า ขอทรงแสดงพระกรุณาต่อข้าพระองค์ตามความเมตตาของพระองค์ ขอทรงลบการละเมิดของข้าพระองค์ออกไปตามแต่พระกรุณาอันอุดมของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 2, 'ขอทรงล้างข้าพระองค์จากความชั่วช้าให้หมดสิ้น และทรงชําระข้าพระองค์จากบาปของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 3, 'เพราะข้าพระองค์ทราบถึงการละเมิดของข้าพระองค์แล้ว และบาปของข้าพระองค์อยู่ต่อหน้าข้าพระองค์เสมอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 4, 'ข้าพระองค์ได้ทําบาปต่อพระองค์ ต่อพระองค์เท่านั้น และได้กระทําสิ่งที่ชั่วร้ายในสายพระเนตรพระองค์ ทั้งนี้เพื่อพระองค์จะทรงชอบธรรมในคําตรัสของพระองค์ และกระจ่างแจ้งในการพิพากษาของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 5, 'ดูเถิด ข้าพระองค์ถือกําเนิดมาในความชั่วช้า และมารดาตั้งครรภ์ข้าพระองค์ในบาป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 6, 'ดูเถิด พระองค์มีพระประสงค์ความจริงภายใน และจะทรงสอนสติปัญญาแก่ข้าพระองค์ภายในจิตใจลึกลับของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 7, 'ขอทรงชําระข้าพระองค์ด้วยต้นหุสบ ข้าพระองค์จึงจะสะอาด ขอทรงล้างข้าพระองค์และข้าพระองค์จะขาวกว่าหิมะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 8, 'ขอทรงโปรดให้ข้าพระองค์ได้ยินความชื่นบานและความยินดี เพื่อกระดูกซึ่งพระองค์ทรงหักนั้นจะเปรมปรีดิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 9, 'ขอทรงเบือนพระพักตร์พระองค์จากบาปทั้งหลายของข้าพระองค์เสีย และทรงลบบรรดาความชั่วช้าของข้าพระองค์ให้สิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 10, 'โอ ข้าแต่พระเจ้า ขอทรงสร้างใจสะอาดภายในข้าพระองค์ และฟื้นน้ําใจที่หนักแน่นขึ้นใหม่ภายในข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 11, 'ขออย่าทรงเหวี่ยงข้าพระองค์ไปเสียจากเบื้องพระพักตร์พระองค์ และขออย่าทรงนําพระวิญญาณบริสุทธิ์ของพระองค์ไปจากข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 12, 'ขอทรงคืนความชื่นบานในความรอดแก่ข้าพระองค์ และชูข้าพระองค์ไว้ด้วยเต็มพระทัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 13, 'แล้วข้าพระองค์จะสอนผู้ละเมิดทั้งหลายถึงบรรดาพระมรรคาของพระองค์ และคนบาปทั้งหลายจะกลับสู่พระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 14, 'โอ ข้าแต่พระเจ้า คือพระเจ้าแห่งความรอดของข้าพระองค์ ขอทรงช่วยข้าพระองค์ให้พ้นจากความผิดเพราะทําโลหิตเขาตก และลิ้นของข้าพระองค์จะร้องเพลงเรื่องความชอบธรรมของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 15, 'โอ ข้าแต่องค์พระผู้เป็นเจ้า ขอทรงเบิกริมฝีปากของข้าพระองค์ และปากของข้าพระองค์จะสําแดงการสรรเสริญพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 16, 'เพราะพระองค์มิได้ทรงประสงค์เครื่องสัตวบูชา มิฉะนั้นข้าพระองค์จะถวายให้ พระองค์มิได้พอพระทัยเครื่องเผาบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 17, 'เครื่องบูชาที่พระเจ้าทรงรับได้คือจิตใจที่ชอกช้ํา จิตใจที่สํานึกผิดและชอกช้ํานั้น โอ ข้าแต่พระเจ้า พระองค์จะมิได้ทรงดูถูก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 18, 'ขอทรงกระทําดีแก่ศิโยนตามพระกรุณาของพระองค์ ขอทรงสร้างกําแพงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 19, 'แล้วพระองค์จะทรงปีติยินดีในเครื่องสัตวบูชาแห่งความชอบธรรม ในเครื่องเผาบูชาและในเครื่องเผาบูชาทั้งตัว แล้วเขาจะถวายวัวผู้บนแท่นบูชาของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 1, 'ถึงหัวหน้านักร้อง มัสคิลบทหนึ่ง เพลงสดุดีของดาวิด เมื่อโดเอกคนเอโดมมาทูลซาอูลว่า “ดาวิดได้มาที่เรือนอาหิเมเลค”โอ เจ้าผู้มีอํานาจ ไฉนเจ้าจึงโอ้อวดในการชั่ว ความเมตตาของพระเจ้าดํารงอยู่วันยังค่ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 2, 'ลิ้นของเจ้าออกอุบายประสงค์ร้าย และหลอกลวงอย่างมีดโกนคม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 3, 'เจ้ารักชั่วมากกว่าดี และการมุสามากกว่าพูดความชอบธรรม เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 4, 'เจ้ารักทุกคําที่ทําลาย โอ ลิ้นแห่งการหลอกลวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 5, 'แต่พระเจ้าจะทรงทําลายเจ้าลงเสียเป็นนิตย์ พระองค์จะทรงฉวยและดึงเจ้าจากที่อยู่อาศัยของเจ้า พระองค์จะทรงถอนรากเจ้าเสียจากแผ่นดินของคนเป็น เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 6, 'คนชอบธรรมจะเห็นและเกรงกลัว และจะหัวเราะเยาะเขา กล่าวว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 7, '“จงดูบุรุษผู้ไม่ให้พระเจ้าเป็นกําลังของตน แต่ไว้ใจในความมั่งคั่งอันอุดมของเขา เขาเสริมกําลังตัวเขาในความชั่วร้ายของเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 8, 'ฝ่ายข้าพเจ้าเป็นเหมือนต้นมะกอกเทศเขียวสดในพระนิเวศของพระเจ้า ข้าพเจ้าวางใจในความเมตตาของพระเจ้าเป็นนิจกาล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 9, 'ข้าพระองค์จะสรรเสริญพระองค์เป็นนิตย์ เพราะพระองค์ได้ทรงกระทําเช่นนั้น ข้าพระองค์จะรอคอยพระนามของพระองค์ เพราะเป็นพระนามประเสริฐต่อหน้าวิสุทธิชนของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 1, 'ถึงหัวหน้านักร้อง ตามทํานองมาหะลัท มัสคิลบทหนึ่ง เพลงสดุดีของดาวิดคนโง่รําพึงในใจของตนว่า “ไม่มีพระเจ้า” เขาทั้งหลายก็เลวทรามลง และกระทําความชั่วช้าที่น่าสะอิดสะเอียน ไม่มีสักคนเดียวที่ทําดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 2, 'พระเจ้าทรงมองลงมาจากฟ้าสวรรค์ ดูบุตรทั้งหลายของมนุษย์ว่าจะมีคนใดบ้างที่เข้าใจที่เสาะแสวงหาพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 3, 'เขาทั้งหลายก็ถดถอยไปหมด เขาทั้งหลายก็เลวทรามลงเหมือนกันสิ้น ไม่มีสักคนเดียวที่ทําดี ไม่มีเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 4, 'บรรดาผู้ที่กระทําความชั่วช้าไม่มีความรู้หรือ คือผู้ที่กินประชาชนของเราอย่างกินขนมปัง และไม่ร้องทูลพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 5, 'เขาทั้งหลายอยู่ที่นั่นอย่างน่าสยดสยองยิ่งนัก ในที่ซึ่งไม่น่ามีความสยดสยอง เพราะพระเจ้าทรงกระจายกระดูกของคนที่ตั้งค่ายสู้เจ้า พระองค์ทรงให้เขาทั้งหลายได้อาย เพราะพระเจ้าทรงชังเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 6, 'โอ ขอการช่วยให้รอดเพื่ออิสราเอลมาจากศิโยนเสียทีเถิด เมื่อพระเจ้าทรงให้พวกเชลยแห่งประชาชนของพระองค์กลับสู่สภาพเดิม ยาโคบจะปลาบปลื้ม อิสราเอลจะยินดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 1, 'ถึงหัวหน้านักร้องใช้เครื่องสาย มัสคิลบทหนึ่ง เพลงสดุดีของดาวิด เมื่อพวกชาวศิฟไปทูลซาอูลว่า “ดาวิดซ่อนตัวอยู่ท่ามกลางเราไม่ใช่หรือ”โอ ข้าแต่พระเจ้า ขอทรงช่วยข้าพระองค์ให้รอดด้วยพระนามของพระองค์ และแก้แทนข้าพระองค์ด้วยอานุภาพของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 2, 'โอ ข้าแต่พระเจ้า ขอทรงสดับคําอธิษฐานของข้าพระองค์ ขอทรงเงี่ยพระกรรณสดับถ้อยคําจากปากของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 3, 'เพราะคนแปลกหน้าได้ลุกขึ้นสู้ข้าพระองค์ ผู้บีบบังคับเสาะหาชีวิตของข้าพระองค์ เขามิได้ตั้งพระเจ้าไว้ตรงหน้าเขา เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 4, 'ดูเถิด พระเจ้าทรงเป็นผู้ช่วยของข้าพเจ้า องค์พระผู้เป็นเจ้าทรงเป็นผู้ผดุงชีวิตของข้าพเจ้าไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 5, 'พระองค์จะทรงตอบสนองการร้ายต่อพวกศัตรูของข้าพเจ้าและทรงขจัดเขาเสียด้วยความจริงของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 6, 'ข้าพระองค์จะถวายสัตวบูชาตามใจสมัครแด่พระองค์ โอ ข้าแต่พระเยโฮวาห์ ข้าพระองค์จะสรรเสริญพระนามของพระองค์ เพราะพระนามนั้นประเสริฐ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 7, 'เพราะพระองค์ทรงช่วยข้าพเจ้าให้พ้นจากความทุกข์ยากลําบากทุกอย่าง และนัยน์ตาของข้าพเจ้ามองเห็นพระประสงค์ของพระองค์ต่อพวกศัตรูของข้าพเจ้านั้นสําเร็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 1, 'ถึงหัวหน้านักร้องใช้เครื่องสาย มัสคิลบทหนึ่ง เพลงสดุดีของดาวิดโอ ข้าแต่พระเจ้า ขอทรงเงี่ยพระกรรณสดับคําอธิษฐานของข้าพระองค์ ขออย่าซ่อนพระองค์เสียจากคําวิงวอนของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 2, 'ขอทรงสดับ และขอทรงฟังข้าพระองค์ ข้าพระองค์เศร้าสลดในเรื่องร้องทุกข์ของข้าพระองค์ ข้าพระองค์จึงส่งเสียงครวญคราง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 3, 'เพราะเสียงของศัตรู เพราะการบีบบังคับของคนชั่ว เหตุว่าเขาฟ้องว่าข้าพระองค์ได้ทําความชั่วช้า และเขาบ่มความเกลียดชังข้าพระองค์โดยความโกรธ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 4, 'จิตใจของข้าพระองค์ระทมอยู่ในข้าพระองค์ ความสยดสยองของมัจจุราชตกเหนือข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 5, 'ความกลัวและความสะทกสะท้านมาเหนือข้าพระองค์ ความหวาดเสียวท่วมข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 6, 'และข้าพระองค์ว่า “โอ ข้าอยากมีปีกอย่างนกเขา จะได้บินหนีไปและอยู่สงบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 7, 'ดูเถิด ข้าจะได้พเนจรไปไกล ข้าจะได้พักอยู่ในถิ่นทุรกันดาร เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 8, 'ข้าจะได้รีบหนีไปจากลมดุเดือดและพายุ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 9, 'โอ ข้าแต่องค์พระผู้เป็นเจ้า ขอทรงทําลายเสีย และให้ภาษาของเขายุ่งเหยิงไป เพราะข้าพระองค์เห็นความทารุณและการโกลาหลที่ในนคร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 10, 'เขาเดินบนกําแพงรอบนครอยู่ทั้งกลางวันและกลางคืน และความบาปผิดกับความเศร้าโศกอยู่ภายในนคร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 11, 'ความเลวทรามมีอยู่ท่ามกลางเธอ การหลอกลวงและการฉ้อโกงไม่พรากไปจากถนนทั้งปวงของเธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 12, 'มิใช่ศัตรูผู้เยาะเย้ยข้าพเจ้า ข้าพเจ้าจะได้ทนได้ มิใช่ผู้ที่เกลียดชังข้าพเจ้าผู้พองตัวใส่ข้าพเจ้า ข้าพเจ้าจะได้หลบเขาได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 13, 'แต่เป็นท่าน เสมอบ่าเสมอไหล่กับข้าพเจ้า เป็นเกลอของข้าพเจ้า เป็นมิตรรู้จักมักคุ้นกับข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 14, 'เราเคยสนทนาปราศรัยกันอย่างชื่นใจ เราดําเนินในพระนิเวศของพระเจ้าฉันมิตรสนิท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 15, 'ขอมัจจุราชมาหาเขาเหล่านั้น ให้เขาลงไปยังนรกทั้งเป็น เพราะความเลวทรามอยู่ในที่อยู่อาศัยของเขาและอยู่ท่ามกลางพวกเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 16, 'สําหรับข้าพเจ้า ข้าพเจ้าจะร้องทูลต่อพระเจ้า และพระเยโฮวาห์จะทรงช่วยข้าพเจ้าให้รอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 17, 'ทั้งเวลาเช้า เวลาเย็น และเวลาเที่ยง ข้าพเจ้าจะอธิษฐานและร้องทุกข์ และพระองค์จะทรงสดับเสียงของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 18, 'พระองค์ได้ทรงช่วยจิตวิญญาณของข้าพเจ้าให้ปลอดภัยจากสงครามที่ข้าพเจ้าต่อสู้อยู่ เพราะคนเป็นอันมากอยู่ฝ่ายข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 19, 'พระเจ้าจะทรงสดับและลดเขาลง คือพระองค์ผู้ทรงดํารงอยู่ตั้งแต่โบราณกาล เซลาห์ เพราะเขาไม่เปลี่ยน เขาจึงไม่ยําเกรงพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 20, 'เขายื่นมือออกต่อสู้ผู้อยู่อย่างสันติกับเขา เขาฝ่าฝืนพันธสัญญาของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 21, 'คําพูดจากปากของเขาเรียบลื่นยิ่งกว่าเนยข้น แต่สงครามอยู่ภายในใจของเขา ถ้อยคําของเขาอ่อนนุ่มยิ่งกว่าน้ํามัน แต่ทว่าเป็นดาบที่ชักออกมาแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 22, 'จงมอบภาระของท่านไว้กับพระเยโฮวาห์ และพระองค์จะทรงค้ําจุนท่าน พระองค์จะไม่ทรงยอมให้คนชอบธรรมคลอนแคลนเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 23, 'โอ ข้าแต่พระเจ้า แต่พระองค์จะทรงเหวี่ยงเขาลงสู่ปากแดนพินาศ คนที่ทําให้โลหิตตกและคนหลอกลวงจะมีชีวิตอยู่ไม่ถึงครึ่งจํานวนเวลาของเขา แต่ข้าพระองค์จะวางใจในพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 1, 'ถึงหัวหน้านักร้อง ตามทํานองโยนาเธเลมเรโคคิม มิคทามบทหนึ่งของดาวิด เมื่อชาวฟีลิสเตียจับท่านในเมืองกัทโอ ข้าแต่พระเจ้า ขอทรงเมตตาข้าพระองค์ เพราะมนุษย์จะกลืนข้าพระองค์เสีย เขาต่อสู้และบีบบังคับข้าพระองค์วันยังค่ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 2, 'โอ ข้าแต่พระองค์ผู้สูงสุด พวกศัตรูของข้าพระองค์จะกลืนข้าพระองค์เสียวันยังค่ํา เพราะหลายคนต่อสู้ข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 3, 'เมื่อข้าพระองค์กลัว ข้าพระองค์วางใจในพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 4, 'ในพระเจ้า ข้าพระองค์จะสรรเสริญพระวจนะของพระองค์ ในพระเจ้า ข้าพระองค์วางใจอยู่ ข้าพระองค์จะไม่กลัวว่าเนื้อหนังอาจกระทําอะไรแก่ข้าพระองค์ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 5, 'เขาประทุษร้ายต่อคํากล่าวของข้าพระองค์วันยังค่ํา ความคิดทั้งสิ้นของเขาล้วนมุ่งร้ายต่อข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 6, 'เขาร่วมหัวกัน เขาซุ่มอยู่ เขาเฝ้ารอยเท้าของข้าพระองค์อย่างกับคนที่ซุ่มคอยเอาชีวิตข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 7, 'เขาจะหนีให้พ้นเพราะเหตุความชั่วช้าของเขาหรือ โอ ข้าแต่พระเจ้า ขอทรงเหวี่ยงชนชาติทั้งหลายลงมาด้วยพระพิโรธ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 8, 'พระองค์ทรงนับการระหกระเหินของข้าพระองค์ ทรงเก็บน้ําตาของข้าพระองค์ใส่ขวดของพระองค์ไว้ น้ําตานั้นไม่อยู่ในบัญชีของพระองค์หรือ พระเจ้าข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 9, 'แล้วศัตรูของข้าพระองค์จะหันกลับในวันที่ข้าพระองค์ร้องทูล ข้าพระองค์ทราบเช่นนี้ว่า พระเจ้าทรงสถิตฝ่ายข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 10, 'ในพระเจ้า ข้าพระองค์จะสรรเสริญพระวจนะของพระองค์ ในพระเยโฮวาห์ ข้าพระองค์จะสรรเสริญพระวจนะของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 11, 'ในพระเจ้า ข้าพระองค์วางใจอยู่ ข้าพระองค์จะไม่กลัวว่ามนุษย์อาจกระทําอะไรแก่ข้าพระองค์ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 12, 'โอ ข้าแต่พระเจ้า ที่ข้าพระองค์ปฏิญาณไว้นั้น ข้าพระองค์จะทําตาม ข้าพระองค์จะถวายคําสรรเสริญแด่พระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 13, 'เพราะพระองค์ทรงช่วยจิตวิญญาณของข้าพระองค์ให้พ้นจากมัจจุราช พระองค์จะทรงช่วยเท้าของข้าพระองค์ให้พ้นจากการล้มมิใช่หรือ เพื่อข้าพระองค์จะดําเนินอยู่ต่อเบื้องพระพักตร์พระเจ้าในความสว่างแห่งชีวิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 1, 'ถึงหัวหน้านักร้องตามทํานองอาลทัสชิท มิคทามบทหนึ่งของดาวิด เมื่อท่านหนีซาอูลที่ในถ้ําโอ ข้าแต่พระเจ้า ขอทรงพระกรุณาต่อข้าพระองค์ ขอทรงพระกรุณาต่อข้าพระองค์ เพราะจิตวิญญาณของข้าพระองค์วางใจในพระองค์ ข้าพระองค์ลี้ภัยอยู่ใต้ร่มปีกของพระองค์จนกว่าภัยอันตรายเหล่านี้จะผ่านพ้นไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 2, 'ข้าพเจ้าจะร้องทูลต่อพระเจ้าองค์ผู้สูงสุด ต่อพระเจ้าผู้ทรงกระทําการทั้งสิ้นให้สําเร็จเพื่อข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 3, 'พระองค์จะทรงใช้มาจากฟ้าสวรรค์ และช่วยข้าพเจ้าให้รอดจากการเยาะเย้ยของผู้ที่อยากกลืนข้าพเจ้าเสีย เซลาห์ พระเจ้าจะทรงใช้ความเมตตาและความจริงลงมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 4, 'จิตใจข้าพเจ้าอยู่ท่ามกลางเหล่าสิงโต ข้าพเจ้านอนท่ามกลางผู้ที่ไฟติดตัวคือบุตรทั้งหลายของมนุษย์ ฟันของเขาทั้งหลายคือหอกและลูกธนู ลิ้นของเขาคือดาบคม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 5, 'โอ ข้าแต่พระเจ้า ขอทรงเป็นที่ยกย่องเหนือฟ้าสวรรค์ ขอสง่าราศีของพระองค์อยู่เหนือทั่วแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 6, 'เขาทั้งหลายวางตาข่ายดักเท้าข้าพเจ้า จิตใจของข้าพเจ้าได้ค้อมลง เขาขุดบ่อไว้ต่อหน้าข้าพเจ้า แต่เขาก็ตกลงไปเสียเอง เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 7, 'โอ ข้าแต่พระเจ้า จิตใจของข้าพระองค์มั่นคง จิตใจของข้าพระองค์มั่นคง ข้าพระองค์จะร้องเพลงและร้องเพลงสรรเสริญ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 8, 'จิตใจของข้าพเจ้าเอ๋ย จงตื่นเถิด พิณใหญ่และพิณเขาคู่เอ๋ย จงตื่นเถิด ข้าพเจ้าจะปลุกอรุณ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 9, 'โอ ข้าแต่องค์พระผู้เป็นเจ้า ข้าพระองค์จะสรรเสริญพระองค์ท่ามกลางประชาชาติ ข้าพระองค์จะร้องเพลงสรรเสริญพระองค์ท่ามกลางชนชาติทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 10, 'เพราะความเมตตาของพระองค์ใหญ่ยิ่งถึงฟ้าสวรรค์ ความจริงของพระองค์สูงถึงเมฆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 11, 'โอ ข้าแต่พระเจ้า ขอทรงเป็นที่เชิดชูเหนือฟ้าสวรรค์ ขอสง่าราศีของพระองค์อยู่เหนือทั่วแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 1, 'ถึงหัวหน้านักร้องตามทํานองอาลทัสชิท มิคทามบทหนึ่งของดาวิดโอ ชุมนุมชนเอ๋ย ท่านพูดอย่างชอบธรรมหรือ โอ บุตรทั้งหลายของมนุษย์เอ๋ย ท่านพิพากษาอย่างเที่ยงธรรมหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 2, 'เปล่าเลย ในใจของท่าน ท่านประดิษฐ์ความผิด ท่านชั่งความทารุณแห่งมือของท่านในแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 3, 'คนชั่วหลงเจิ่นไปตั้งแต่จากครรภ์ เขาหลงทางไปตั้งแต่เกิด คือพูดมุสา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 4, 'เขามีพิษเหมือนพิษงู เหมือนงูพิษหูหนวกที่อุดหูของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 5, 'มันจึงไม่ฟังเสียงของหมองู ผู้ซึ่งมีมนต์ขลัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 6, 'โอ ข้าแต่พระเจ้า ขอทรงหักฟันในปากของมันเสีย โอ ข้าแต่พระเยโฮวาห์ ขอทรงฉีกเขี้ยวของสิงโตหนุ่มออกเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 7, 'ให้พวกเขาละลายไปเหมือนน้ําที่ไหลไม่ขาดสาย เมื่อเขาเล็งธนูเพื่อยิงลูกศร ให้ลูกศรนั้นถูกตัดเป็นชิ้นๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 8, 'ขอให้เขาเหมือนทากที่ละลายเป็นเมือกไป เหมือนทารกแท้งที่ไม่เคยเห็นดวงอาทิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 9, 'ก่อนหม้อของเจ้าจะรู้สึกร้อนจากหนามทั้งเป็น พระองค์จะทรงกวาดหนามเหล่านั้นไปเสียเหมือนลมหมุน และด้วยพระพิโรธของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 10, 'คนชอบธรรมจะเปรมปรีดิ์ เมื่อเขาเห็นการแก้แค้น เขาจะเอาโลหิตของคนชั่วล้างเท้าของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 11, 'จะมีคนกล่าวว่า “แน่แล้ว มีบําเหน็จให้แก่คนชอบธรรม แน่แล้ว มีพระเจ้าผู้ทรงพิพากษาโลก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 1, 'ถึงหัวหน้านักร้องตามทํานองอาลทัสชิท มิคทามบทหนึ่งของดาวิด เมื่อซาอูลทรงใช้คนให้ไปเฝ้าบ้านของท่านเพื่อจะฆ่าท่านเสียโอ ข้าแต่พระเจ้าของข้าพระองค์ ขอทรงช่วยข้าพระองค์ให้พ้นจากศัตรูของข้าพระองค์ ขอทรงช่วยป้องกันข้าพระองค์ให้พ้นจากบรรดาผู้ที่ลุกขึ้นต่อสู้ข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 2, 'ขอทรงช่วยข้าพระองค์ให้พ้นจากผู้ที่ทําความชั่วร้าย และขอทรงช่วยข้าพระองค์ให้รอดจากคนกระหายเลือด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 3, 'เพราะดูเถิด เขาซุ่มคอยเอาชีวิตข้าพระองค์ ผู้มีอํานาจร่วมหัวกันต่อสู้ข้าพระองค์ โอ ข้าแต่พระเยโฮวาห์ มิใช่การละเมิดหรือบาปของข้าพระองค์เอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 4, 'เขาวิ่งไปเตรียมพร้อม มิใช่ความผิดของข้าพระองค์ ขอทรงกระปรี้กระเปร่า ขอทรงมาช่วยข้าพระองค์และทอดพระเนตร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 5, 'โอ ข้าแต่พระเยโฮวาห์พระเจ้าจอมโยธา พระองค์ทรงเป็นพระเจ้าของอิสราเอล ขอทรงตื่นขึ้นลงโทษบรรดาประชาชาติ ขออย่าทรงเมตตาผู้ละเมิดที่คิดร้ายแม้สักคนเดียว เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 6, 'เขากลับมาทุกเย็น หอนอย่างสุนัข และตระเวนไปทั่วนคร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 7, 'ดูเถิด ปากของเขายังพ่นอยู่ และมีดาบที่ริมฝีปากของเขา เพราะเขาคิดว่า “ใครจะฟังเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 8, 'โอ ข้าแต่พระเยโฮวาห์ แต่พระองค์ทรงหัวเราะเยาะเขา พระองค์ทรงเยาะเย้ยประชาชาติทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 9, 'เพราะเหตุพระกําลังของพระองค์ ข้าพระองค์จะคอยเฝ้าพระองค์ เพราะพระเจ้าทรงเป็นป้อมปราการของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 10, 'พระเจ้าแห่งความเมตตาของข้าพเจ้าจะทรงป้องกันข้าพเจ้า พระเจ้าจะทรงให้ข้าพเจ้าเห็นความปรารถนาของข้าพเจ้าต่อพวกศัตรูของข้าพเจ้านั้นสําเร็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 11, 'โอ ข้าแต่องค์พระผู้เป็นเจ้า โล่ของข้าพระองค์ทั้งหลาย ขออย่าทรงสังหารเขาเสีย เกรงว่าชนชาติของข้าพระองค์จะลืม ขอให้เขาระหกระเหินไปด้วยฤทธานุภาพของพระองค์และทําให้เขาล้มลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 12, 'เพราะบาปแห่งปากของเขา และเพราะถ้อยคําริมฝีปากของเขา ขอให้เขาติดกับโดยความเย่อหยิ่งของเขา เพราะการสาปแช่งและการมุสาซึ่งเขาเปล่งออกมานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 13, 'ขอทรงเผาผลาญเขาเสียโดยพระพิโรธ ขอทรงเผาผลาญเขาจนเขาไม่เหลือเลย แล้วเขาจะทราบว่าพระเจ้าทรงปกครองเหนือยาโคบ ถึงที่สุดปลายแผ่นดินโลก เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 14, 'ให้เขากลับมาทุกเย็น หอนอย่างสุนัข และตระเวนไปทั่วนคร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 15, 'ให้เขาเที่ยวไปหาอาหาร ถ้าไม่ได้กินอิ่มก็ขู่คําราม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 16, 'แต่ข้าพระองค์จะร้องเพลงถึงอานุภาพของพระองค์ ข้าพระองค์จะร้องเพลงถึงความเมตตาของพระองค์ในเวลาเช้า เพราะพระองค์ทรงเป็นป้อมปราการของข้าพระองค์ เป็นที่ลี้ภัยในยามทุกข์ของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 17, 'โอ ข้าแต่พระกําลังของข้าพระองค์ ข้าพระองค์จะร้องเพลงสรรเสริญพระองค์ เพราะพระเจ้าทรงเป็นป้อมปราการของข้าพระองค์ และทรงเป็นพระเจ้าแห่งความเมตตาของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 1, 'ถึงหัวหน้านักร้อง ตามทํานองชูชานเอดูท มิคทามบทหนึ่งของดาวิดเพื่อสั่งสอน เมื่อท่านขับเคี่ยวกับอารัม-นาหะราอิม และกับอารัมโซบาห์ และเมื่อขากลับโยอาบได้ฆ่าชาวเอโดมเสียหนึ่งหมื่นสองพันคนในหุบเขาเกลือโอ ข้าแต่พระเจ้า พระองค์ได้ทรงทอดทิ้งข้าพระองค์ทั้งหลายแล้ว ทั้งได้ทรงทําให้ข้าพระองค์ทั้งหลายกระจัดกระจายไป พระองค์ทรงไม่พอพระทัย โอ ขอให้พระองค์ทรงหันมาหาข้าพระองค์ทั้งหลายอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 2, 'พระองค์ทรงกระทําให้แผ่นดินหวั่นไหว ทรงให้มันแตกแยกออก ขอทรงซ่อมช่องของมันเพราะมันโยกเยก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 3, 'พระองค์ทรงกระทําให้ประชาชนของพระองค์ประสบความลําบาก พระองค์ทรงบังคับข้าพระองค์ให้ดื่มน้ําองุ่นแห่งความประหลาดใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 4, 'พระองค์ทรงตั้งธงไว้ให้บรรดาผู้ที่เกรงกลัวพระองค์ เพื่อชักขึ้นเพราะเหตุความจริง เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 5, 'ขอทรงช่วยให้รอดโดยพระหัตถ์ขวาของพระองค์ และทรงฟังข้าพระองค์ เพื่อว่าผู้ที่พระองค์ทรงรักจะได้รับการช่วยให้พ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 6, 'พระเจ้าได้ตรัสด้วยความบริสุทธิ์ของพระองค์ ว่า “เราจะปีติยินดี เราจะแบ่งเมืองเชเคม และแบ่งหุบเขาเมืองสุคคทออก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 7, 'กิเลอาดเป็นของเรา มนัสเสห์เป็นของเรา เอฟราอิมเป็นที่กันศีรษะของเรา ยูดาห์เป็นผู้ตั้งพระราชบัญญัติของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 8, 'โมอับเป็นอ่างล้างชําระของเรา เราเหวี่ยงรองเท้าของเราลงบนเอโดม เราโห่ร้องด้วยความมีชัยเหนือฟีลิสเตีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 9, 'ผู้ใดจะนําข้าพเจ้าเข้าไปในนครที่มีป้อม ผู้ใดจะนําข้าพเจ้าไปยังเอโดม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 10, 'โอ ข้าแต่พระเจ้า พระองค์มิได้ทรงทอดทิ้งข้าพระองค์ทั้งหลายแล้วหรือ โอ ข้าแต่พระเจ้า พระองค์ไม่ทรงออกไปกับกองทัพของข้าพระองค์ทั้งหลายแล้วละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 11, 'ขอประทานความช่วยเหลือเพื่อต่อต้านความยุ่งยากต่างๆ เพราะความช่วยเหลือของมนุษย์ก็ไร้ผล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 12, 'โดยพระเจ้าเอง ข้าพเจ้าทั้งหลายจะปฏิบัติอย่างเข้มแข็ง พระองค์เองจะทรงเป็นผู้เหยียบคู่อริของข้าพเจ้าทั้งหลายลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 1, 'ถึงหัวหน้านักร้องใช้เครื่องสาย เพลงสดุดีของดาวิดโอ ข้าแต่พระเจ้า ขอทรงฟังเสียงร้องของข้าพระองค์ ขอทรงสดับคําอธิษฐานของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 2, 'ข้าพระองค์ร้องทูลพระองค์มาแต่ที่สุดปลายแผ่นดินโลก เมื่อจิตใจของข้าพระองค์อ่อนระอาไป ขอทรงนําข้าพระองค์มาถึงศิลาที่สูงกว่าข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 3, 'เพราะพระองค์ทรงเป็นที่ลี้ภัยของข้าพระองค์ เป็นหอคอยเข้มแข็งที่ประจันหน้าศัตรู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 4, 'ข้าพระองค์จะอยู่ในพลับพลาของพระองค์เป็นนิตย์ ข้าพระองค์จะวางใจในที่กําบังปีกของพระองค์ เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 5, 'โอ ข้าแต่พระเจ้า เพราะพระองค์ทรงสดับคําปฏิญาณของข้าพระองค์ และพระองค์ประทานมรดกของบรรดาผู้ที่เกรงกลัวพระนามของพระองค์แก่ข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 6, 'พระองค์จะทรงยืดพระชนม์ของกษัตริย์ ให้ปีเดือนของท่านยืนนานไปหลายชั่วอายุ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 7, 'ท่านจะคอยเฝ้าต่อพระพักตร์พระเจ้าเป็นนิตย์ โอ ขอทรงแต่งตั้งความเมตตาและความจริงไว้คุ้มครองท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 8, 'แล้วข้าพระองค์จะร้องเพลงสรรเสริญพระนามของพระองค์เสมอ ตามที่ข้าพระองค์ทําตามคําปฏิญาณอยู่แต่ละวันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 1, 'ถึงหัวหน้านักร้อง ตามทํานองเยดูธูน เพลงสดุดีของดาวิดแน่นอนจิตใจของข้าพเจ้าคอยท่าพระเจ้า ความรอดของข้าพเจ้ามาจากพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 2, 'พระองค์เท่านั้นทรงเป็นศิลา และเป็นความรอดของข้าพเจ้า เป็นป้อมปราการของข้าพเจ้า ข้าพเจ้าจะไม่หวั่นไหวใหญ่โต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 3, 'พวกเจ้าจะคิดความร้ายต่อคนอื่นนานสักเท่าใด เจ้าทุกคนจะถูกสังหาร ผู้เหมือนกําแพงที่เอนและรั้วที่โยกเยก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 4, 'เขาคิดแต่เพียงจะผลักท่านลงมาจากยศของท่าน เขาพอใจในความเท็จ เขาอวยพรด้วยปากของเขา แต่เขาแช่งอยู่ในใจ เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 5, 'จิตใจของข้าพเจ้า จงคอยท่าพระเจ้าแต่องค์เดียว เพราะความหวังของข้าพเจ้ามาจากพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 6, 'พระองค์เท่านั้นทรงเป็นศิลา และเป็นความรอดของข้าพเจ้า เป็นป้อมปราการของข้าพเจ้า ข้าพเจ้าจะไม่หวั่นไหว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 7, 'ความช่วยให้รอดและสง่าราศีของข้าพเจ้าอยู่ที่พระเจ้า ศิลาอันทรงมหิทธิฤทธิ์และที่ลี้ภัยของข้าพเจ้าคือพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 8, 'ประชาชนเอ๋ย จงวางใจในพระองค์ตลอดเวลา จงระบายความในใจของท่านต่อพระองค์ พระเจ้าทรงเป็นที่ลี้ภัยของเรา เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 9, 'คนฐานะต่ําก็เป็นสิ่งไร้สาระ คนฐานะสูงก็เป็นความเท็จ เมื่อชั่งดูเขาก็ลอยขึ้น เขารวมด้วยกันยังเบากว่าสิ่งไร้สาระ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 10, 'อย่าวางใจในการบีบบังคับ อย่าหวังเปล่าด้วยการปล้นสะดม ถ้าความมั่งคั่งเพิ่มขึ้น อย่าวางใจในสิ่งนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 11, 'พระเจ้าตรัสครั้งหนึ่ง ข้าพเจ้าได้ยินอย่างนี้สองครั้งแล้ว ว่าฤทธานุภาพเป็นของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 12, 'โอ ข้าแต่องค์พระผู้เป็นเจ้า ความเมตตาเป็นของพระองค์ เพราะพระองค์ทรงสนองมนุษย์ทุกคนตามการงานของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 1, 'เพลงสดุดีของดาวิด เมื่อท่านอยู่ในถิ่นทุรกันดารยูดาห์โอ ข้าแต่พระเจ้า พระองค์ทรงเป็นพระเจ้าของข้าพระองค์ ข้าพระองค์แสวงหาพระองค์แต่เช้า จิตวิญญาณของข้าพระองค์กระหายหาพระองค์ เนื้อหนังของข้าพระองค์กระเสือกกระสนหาพระองค์ในดินแดนที่แห้งและกระหายน้ํา ที่ที่ไม่มีน้ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 2, 'เช่นนั้นแหละ ข้าพระองค์จึงเคยเห็นพระองค์ในสถานบริสุทธิ์ เห็นฤทธานุภาพและสง่าราศีของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 3, 'เพราะว่าความเมตตาของพระองค์ดีกว่าชีวิต ริมฝีปากของข้าพระองค์จะสรรเสริญพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 4, 'เช่นนั้นแหละ ข้าพระองค์จะสรรเสริญพระองค์ตราบเท่าชีวิตของข้าพระองค์ ข้าพระองค์จะชูมือต่อพระนามของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 5, 'จิตใจของข้าพระองค์จะอิ่มหนําดังกินไขกระดูกและไขมัน และปากของข้าพระองค์จะสรรเสริญพระองค์ด้วยริมฝีปากที่ชื่นบาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 6, 'เมื่อข้าพระองค์คิดถึงพระองค์ขณะอยู่บนที่นอน และไตร่ตรองถึงพระองค์ทุกๆยาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 7, 'เพราะพระองค์ทรงเป็นความอุปถัมภ์ของข้าพระองค์ ข้าพระองค์จึงเปรมปรีดิ์อยู่ในร่มปีกของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 8, 'จิตวิญญาณของข้าพระองค์เกาะติดอยู่ที่พระองค์ พระหัตถ์ขวาของพระองค์ชูข้าพระองค์ไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 9, 'แต่บรรดาผู้แสวงหาชีวิตของข้าพระองค์เพื่อทําลาย จะลงไปในที่ลึกแห่งแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 10, 'เขาจะล้มลงด้วยดาบ เขาจะเป็นเหยื่อของสุนัขจิ้งจอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 11, 'แต่กษัตริย์จะทรงเปรมปรีดิ์ในพระเจ้า ทุกคนที่ปฏิญาณในพระนามของพระองค์จะอวดอ้างพระนามนั้น แต่ปากของคนมุสาจะถูกปิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 1, 'ถึงหัวหน้านักร้อง เพลงสดุดีของดาวิดโอ ข้าแต่พระเจ้า ขอทรงสดับเสียงของข้าพระองค์เมื่อข้าพระองค์อธิษฐาน ขอทรงสงวนชีวิตของข้าพระองค์ไว้จากความคิดกลัวศัตรู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 2, 'ขอทรงซ่อนข้าพระองค์ไว้จากการหารืออย่างลับๆของคนชั่ว จากการปองร้ายของคนกระทําความชั่วช้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 3, 'ผู้ลับลิ้นของเขาอย่างลับดาบ ผู้เอาคําขมขื่นเล็งอย่างลูกธนู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 4, 'ยิงออกมาจากที่ซุ่มยังคนปราศจากตําหนิ ยิงเขาทันทีและอย่างไม่กลัวเกรง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 5, 'เขายึดจุดประสงค์ชั่วของเขาไว้มั่น เขาพูดถึงการวางกับดักอย่างลับๆ คิดว่า “ใครจะเห็นเขาทั้งหลายได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 6, 'เขาทั้งหลายค้นหาความชั่วช้า เขาทั้งหลายค้นหาอย่างขมีขมันจนสําเร็จ เพราะความคิดภายในและจิตใจของมนุษย์นั้นลึกล้ํานัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 7, 'แต่พระเจ้าจะทรงยิงธนูใส่เขา เขาจะบาดเจ็บทันที');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 8, 'เพราะว่าเขาทําให้ลิ้นของเขาเป็นสิ่งสะดุดแก่เขาเอง ทุกคนที่เห็นเขาจะหนีไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 9, 'แล้วทุกคนจะกลัวเกรง เขาจะบอกถึงกิจการของพระเจ้า และตรึกตรองถึงสิ่งนั้นที่พระองค์ได้ทรงกระทําแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 10, 'คนชอบธรรมจะเปรมปรีดิ์ในพระเยโฮวาห์ และจะวางใจในพระองค์ บรรดาคนที่เที่ยงธรรมในจิตใจจะอวดอ้างพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 1, 'ถึงหัวหน้านักร้อง เพลงสดุดีและบทเพลงของดาวิดโอ ข้าแต่พระเจ้า ในศิโยนการสรรเสริญคอยท่าพระองค์ เขาจะทําตามคําปฏิญาณแด่พระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 2, 'โอ ข้าแต่พระองค์ผู้ทรงสดับคําอธิษฐาน เนื้อหนังทั้งสิ้นจะมายังพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 3, 'ความชั่วช้าทั้งหลายชนะข้าพระองค์ เนื่องด้วยการละเมิดของข้าพระองค์ทั้งหลาย พระองค์ก็จะทรงชําระล้างให้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 4, 'สุขจริงหนอ ผู้ที่พระองค์ทรงเลือกและนํามาใกล้ให้พํานักอยู่ในบริเวณพระนิเวศของพระองค์ ข้าพระองค์ทั้งหลายจะอิ่มเอิบด้วยความดีแห่งพระนิเวศของพระองค์ คือพระวิหารบริสุทธิ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 5, 'โอ ข้าแต่พระเจ้าแห่งความรอดของข้าพระองค์ทั้งหลาย พระองค์จะทรงตอบข้าพระองค์ทั้งหลายด้วยความชอบธรรมโดยกิจการที่น่าครั่นคร้าม พระองค์ผู้ทรงเป็นความไว้วางใจของที่สิ้นสุดปลายทั้งปวงของแผ่นดินโลก และของคนที่อยู่ทางทะเลที่ไกลโพ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 6, 'พระองค์ผู้ทรงสถาปนาภูเขาด้วยพระกําลังของพระองค์ ทรงคาดพระองค์ไว้ด้วยอานุภาพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 7, 'ผู้ทรงระงับเสียงอึงคะนึงของทะเล เสียงอึงคะนึงของคลื่นทะเล เสียงโกลาหลของชาวประเทศทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 8, 'ผู้ที่อยู่ในเขตแผ่นดินโลกไกลโพ้นจึงเกรงกลัวต่อหมายสําคัญของพระองค์ พระองค์ทรงกระทําให้เช้าขึ้นและเย็นลงกู่ก้องด้วยความชื่นบาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 9, 'พระองค์ทรงเยี่ยมเยียนแผ่นดินโลก และทรงรดน้ํา พระองค์ทรงกระทําให้อุดมยิ่งด้วยแม่น้ําของพระเจ้าซึ่งมีน้ําเต็ม พระองค์ทรงจัดหาข้าวให้ เมื่อทรงจัดเตรียมโลกไว้เช่นนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 10, 'พระองค์ทรงรดน้ําตามรอยไถของมันอย่างอุดม และให้ขี้ไถราบลง ให้อ่อนละมุนด้วยฝน และทรงอวยพรผลิตผลของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 11, 'พระองค์ทรงให้ปีเป็นยอดด้วยความดีของพระองค์ พระมรรคาทั้งหลายของพระองค์มีความไพบูลย์ย้อยหยด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 12, 'ทุ่งหญ้าในถิ่นทุรกันดารก็หยดย้อย เนินเขาคาดเอวด้วยความชื่นบาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 13, 'ป่าพงห่มตัวด้วยฝูงแพะแกะ หุบเขาพราวไปด้วยข้าว เขาโห่ร้องด้วยความชื่นบานและร้องเพลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 1, 'ถึงหัวหน้านักร้อง บทเพลงหรือเพลงสดุดีแผ่นดินโลกทั้งสิ้นเอ๋ย จงเปล่งเสียงอย่างชื่นบานถวายพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 2, 'จงร้องเพลงถวายพระเกียรติแด่พระนามของพระองค์ จงถวายสรรเสริญอย่างรุ่งเรืองต่อพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 3, 'จงทูลพระเจ้าว่า “พระราชกิจของพระองค์น่าครั่นคร้ามยิ่งนัก ฤทธานุภาพของพระองค์ใหญ่หลวงนัก จนศัตรูจะหมอบราบต่อเบื้องพระพักตร์พระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 4, 'แผ่นดินโลกทั้งสิ้นจะนมัสการพระองค์ และจะร้องเพลงสรรเสริญพระองค์ เขาทั้งหลายจะร้องเพลงสรรเสริญพระนามของพระองค์” เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 5, 'จงมาดูสิ่งที่พระเจ้าได้ทรงกระทํา พระราชกิจของพระองค์น่าครั่นคร้ามต่อบุตรทั้งหลายของมนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 6, 'พระองค์ทรงเปลี่ยนทะเลให้เป็นดินแห้ง คนเดินข้ามแม่น้ําไป ที่นั่นเราได้เปรมปรีดิ์ในพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 7, 'ผู้ทรงปกครองด้วยอานุภาพของพระองค์เป็นนิตย์ ผู้ซึ่งพระเนตรเฝ้าบรรดาประชาชาติอยู่ อย่าให้คนมักกบฏยกย่องตนเอง เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 8, 'โอ ชนชาติทั้งหลายเอ๋ย จงสรรเสริญพระเจ้าของเรา จงให้ได้ยินเสียงสรรเสริญพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 9, 'ผู้ทรงให้จิตวิญญาณเราอยู่ท่ามกลางคนเป็น และมิได้ทรงยอมให้เท้าเราพลาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 10, 'โอ ข้าแต่พระเจ้า เพราะพระองค์ทรงลองใจข้าพระองค์ทั้งหลาย พระองค์ทรงทดลองข้าพระองค์อย่างทดลองเงิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 11, 'พระองค์ทรงนําข้าพระองค์ทั้งหลายเข้ามาในข่าย พระองค์ทรงวางความทุกข์ยากไว้ที่เอวของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 12, 'พระองค์ทรงให้คนขับรถรบทับศีรษะของข้าพระองค์ทั้งหลาย ข้าพระองค์ทั้งหลายต้องลุยไฟลุยน้ํา แต่พระองค์ยังทรงนําข้าพระองค์มาสู่ที่อิ่มเอิบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 13, 'ข้าพระองค์จะเข้าไปในพระนิเวศของพระองค์พร้อมด้วยเครื่องเผาบูชา ข้าพระองค์จะทําตามคําปฏิญาณต่อพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 14, 'ตามที่ริมฝีปากข้าพระองค์ได้พูดไว้ และที่ปากข้าพระองค์ได้กล่าวในยามที่ข้าพระองค์ทุกข์ยากลําบาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 15, 'ข้าพระองค์จะถวายสัตว์อ้วนพีเป็นเครื่องเผาบูชาแด่พระองค์ พร้อมกับควันเครื่องสัตวบูชาด้วยแกะผู้ ข้าพระองค์จะถวายบูชาด้วยวัวผู้และแพะ เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 16, 'บรรดาผู้ที่เกรงกลัวพระเจ้า ขอเชิญมาฟัง และข้าพเจ้าจะบอกถึงว่าพระองค์ได้ทรงกระทําอะไรแก่จิตวิญญาณข้าพเจ้าบ้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 17, 'ปากข้าพเจ้าได้ร้องทูลพระองค์ และลิ้นข้าพเจ้าได้ยกย่องพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 18, 'ถ้าข้าพเจ้าได้บ่มความชั่วช้าไว้ในใจข้าพเจ้า องค์พระผู้เป็นเจ้าจะไม่ทรงสดับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 19, 'แต่พระเจ้าได้ทรงสดับแน่ทีเดียว พระองค์ได้ทรงฟังเสียงคําอธิษฐานของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 20, 'สาธุการแด่พระเจ้า เพราะว่าพระองค์ไม่ทรงปฏิเสธคําอธิษฐานของข้าพเจ้า หรือยับยั้งความเมตตาของพระองค์เสียจากข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 1, 'ถึงหัวหน้านักร้องใช้เครื่องสาย เพลงสดุดีหรือบทเพลงขอพระเจ้าทรงพระเมตตาต่อข้าพระองค์ทั้งหลาย และอํานวยพรแก่ข้าพระองค์ ขอพระองค์ทรงให้พระพักตร์ฉายสว่างแก่ข้าพระองค์ เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 2, 'เพื่อพระมรรคาของพระองค์จะเป็นที่รู้จักในแผ่นดินโลก ความรอดของพระองค์จะเป็นที่ทราบท่ามกลางบรรดาประชาชาติทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 3, 'โอ ข้าแต่พระเจ้า ขอชนชาติทั้งหลายสรรเสริญพระองค์ ให้ชนชาติทั้งหลายสรรเสริญพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 4, 'โอ ขอให้ชาวประเทศทั้งหลายยินดีและร้องเพลงด้วยความชื่นบาน เพราะพระองค์จะทรงพิพากษาชนชาติทั้งหลายด้วยความชอบธรรม และทรงครอบครองชาวประเทศทั้งหลายในโลก เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 5, 'โอ ข้าแต่พระเจ้า ขอชนชาติทั้งหลายสรรเสริญพระองค์ ให้ชนชาติทั้งหลายสรรเสริญพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 6, 'แล้วแผ่นดินโลกจึงจะได้เกิดผล พระเจ้าคือพระเจ้าของเราจะทรงอํานวยพระพรแก่เรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 7, 'พระเจ้าจะทรงอวยพระพรแก่เรา แล้วที่สุดปลายแผ่นดินโลกจะเกรงกลัวพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 1, 'ถึงหัวหน้านักร้อง เพลงสดุดีหรือบทเพลงของดาวิดขอพระเจ้าทรงลุกขึ้น ให้ศัตรูของพระองค์กระจายไป ให้บรรดาผู้ที่เกลียดชังพระองค์หนีไปต่อเบื้องพระพักตร์พระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 2, 'ควันถูกขับไปฉันใด ก็ขอทรงไล่เขาไปฉันนั้น ขี้ผึ้งละลายต่อหน้าไฟฉันใด ก็ขอให้คนชั่วพินาศต่อเบื้องพระพักตร์พระเจ้าฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 3, 'แต่ขอให้คนชอบธรรมชื่นบาน ให้เขาเต้นโลดต่อเบื้องพระพักตร์พระเจ้า ให้เขาเริงโลดด้วยความชื่นบาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 4, 'จงร้องเพลงถวายพระเจ้า จงร้องเพลงสรรเสริญพระนามของพระองค์ จงยกย่องพระองค์ผู้ทรงเมฆเป็นพาหนะโดยพระนามของพระองค์คือพระเยโฮวาห์ จงเริงโลดต่อเบื้องพระพักตร์พระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 5, 'พระเจ้าในที่ประทับบริสุทธิ์ของพระองค์ ทรงเป็นพระบิดาของคนกําพร้าพ่อ และทรงเป็นผู้พิพากษาของหญิงม่าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 6, 'พระเจ้าทรงให้คนเปลี่ยวเปล่าอยู่ในครอบครัว พระองค์ทรงปลดปล่อยคนเหล่านั้นที่ถูกล่ามด้วยโซ่ตรวน แต่คนมักกบฏจะอาศัยในแผ่นดินที่แห้งแล้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 7, 'โอ ข้าแต่พระเจ้า เมื่อพระองค์เสด็จนําหน้าประชาชนของพระองค์ เมื่อพระองค์เสด็จไปตามถิ่นทุรกันดาร เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 8, 'แผ่นดินโลกก็หวั่นไหว ท้องฟ้าก็เทฝนลงมาต่อเบื้องพระพักตร์พระเจ้า ภูเขาซีนายโน้มสั่นสะเทือนต่อเบื้องพระพักตร์พระเจ้าคือพระเจ้าของอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 9, 'โอ ข้าแต่พระเจ้า พระองค์ทรงส่งฝนอันอุดมลงมา เมื่อมรดกของพระองค์อ่อนระโหย พระองค์ทรงฟื้นขึ้นใหม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 10, 'ชุมนุมชนของพระองค์ก็มาอาศัยในนั้น โอ ข้าแต่พระเจ้า โดยความดีของพระองค์ พระองค์ทรงจัดเตรียมไว้ให้แก่คนขัดสน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 11, 'องค์พระผู้เป็นเจ้าประทานพระวจนะ พวกที่นําข่าวนั้นก็เป็นพวกใหญ่โต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 12, 'บรรดากษัตริย์ของกองทัพทั้งหลายก็หนีไป ผู้หญิงที่อยู่บ้านก็เอาข้าวของที่ริบมาได้แบ่งกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 13, 'ถึงแม้ท่านนอนอยู่ท่ามกลางคอกแกะ ท่านก็จะเหมือนปีกนกเขาที่บุด้วยเงิน และขนของมันที่บุด้วยทองคํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 14, 'เมื่อผู้ทรงมหิทธิฤทธิ์กระจายกษัตริย์ ณ ที่นั่น มันก็ขาวเหมือนหิมะที่ตกลงบนภูเขาศัลโมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 15, 'ภูเขาของพระเจ้าเหมือนอย่างภูเขาเมืองบาชาน ภูเขาที่มียอดสูงก็เหมือนอย่างภูเขาเมืองบาชาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 16, 'ภูเขาที่มียอดสูงทั้งหลายเอ๋ย ทําไมเจ้าจึงกระโดด นี่เป็นภูเขาซึ่งพระเจ้าทรงประสงค์ให้เป็นที่พํานักของพระองค์ เออ ที่ที่พระเยโฮวาห์จะประทับเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 17, 'รถรบของพระเจ้าอเนกอนันต์ คือมีทูตสวรรค์นับเป็นพันๆ องค์พระผู้เป็นเจ้าทรงสถิตอยู่ท่ามกลางพวกเขา เหมือนในซีนาย คือในสถานบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 18, 'พระองค์เสด็จขึ้นสู่เบื้องสูง พระองค์ทรงนําพวกเชลยไปเป็นเชลยอีก และรับของประทานเพื่อมนุษย์ และรับเพื่อผู้ที่กบฏด้วย เพื่อพระเยโฮวาห์พระเจ้าจะทรงประทับท่ามกลางพวกเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 19, 'สาธุการแด่องค์พระผู้เป็นเจ้า ผู้ทรงค้ําชูเราทั้งหลายอยู่ทุกวัน พระเจ้าผู้ทรงเป็นความรอดของเรา เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 20, 'พระเจ้าของเราเป็นพระเจ้าแห่งความรอด ซึ่งได้พ้นความตายนั้นก็อยู่ที่พระเจ้าคือองค์พระผู้เป็นเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 21, 'แต่พระเจ้าจะทรงตีศีรษะของศัตรูของพระองค์ให้แตก คือกระหม่อมมีผมของผู้ที่ขืนดําเนินในทางละเมิดของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 22, 'องค์พระผู้เป็นเจ้าตรัสว่า “เราจะนําเขาทั้งหลายกลับมาจากบาชาน เราจะนําประชาชนของเรากลับมาจากที่ลึกของทะเล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 23, 'เพื่อเจ้าจะเอาเท้าอาบเลือดของคู่อริของเจ้า เพื่อลิ้นสุนัขของเจ้าจะมีส่วนด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 24, 'โอ ข้าแต่พระเจ้า การเสด็จของพระองค์ปรากฏแล้ว การเสด็จของพระเจ้าของข้าพระองค์ พระมหากษัตริย์ของข้าพระองค์ เข้าในสถานบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 25, 'นักร้องนําหน้า นักดนตรีคัดท้าย ระหว่างนั้นมีสตรีเล่นรํามะนา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 26, 'ท่านทั้งหลายผู้เป็นน้ําพุของอิสราเอล จงสรรเสริญพระเจ้าคือองค์พระผู้เป็นเจ้าในที่ชุมนุมใหญ่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 27, 'นั่นมีเบนยามินผู้น้อยที่สุดนําหน้า บรรดาเจ้านายยูดาห์อยู่เป็นหมู่ใหญ่ เจ้านายแห่งเศบูลุน เจ้านายแห่งนัฟทาลี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 28, 'โอ ข้าแต่พระเจ้า ขอทรงเรียกอานุภาพของพระองค์มา พระเจ้าทรงบัญชาพระกําลังของพระองค์ พระองค์ผู้ได้ทรงกระทําเพื่อข้าพระองค์ทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 29, 'บรรดากษัตริย์จะนําของกํานัลมาถวายพระองค์ เนื่องด้วยพระวิหารของพระองค์ที่เยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 30, 'ขอทรงขนาบหมู่คนที่แทงด้วยหอก ฝูงวัวกับลูกวัวแห่งชนชาติทั้งหลาย จนเขาทุกคนยินยอมด้วยถวายเงินแผ่น ขอให้ชนชาติทั้งหลายผู้ปีติยินดีในสงครามได้กระจัดพลัดพรากไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 31, 'พวกเจ้านายจะออกมาจากอียิปต์ เอธิโอเปียจะรีบยื่นมือของเขาออกทูลพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 32, 'โอ บรรดาอาณาจักรแห่งแผ่นดินโลกเอ๋ย จงร้องเพลงถวายพระเจ้า จงร้องเพลงสรรเสริญองค์พระผู้เป็นเจ้า เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 33, 'ต่อพระองค์ผู้ทรงฟ้าสวรรค์ ฟ้าสวรรค์ดึกดําบรรพ์ ดูเถิด พระองค์ทรงเปล่งพระสุรเสียงของพระองค์ คือพระสุรเสียงอันทรงมหิทธิฤทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 34, 'จงถวายฤทธานุภาพแด่พระเจ้า ซึ่งความสูงส่งของพระองค์อยู่เหนืออิสราเอล และฤทธานุภาพของพระองค์อยู่ในท้องฟ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 35, 'โอ ข้าแต่พระเจ้า พระองค์ทรงน่าครั่นคร้ามนักในสถานบริสุทธิ์ของพระองค์ คือพระเจ้าของอิสราเอล พระองค์นั้นประทานฤทธิ์และกําลังแก่ประชาชนของพระองค์ สาธุการแด่พระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 1, 'ถึงหัวหน้านักร้อง ตามทํานองโชชานิม เพลงสดุดีของดาวิดโอ ข้าแต่พระเจ้า ขอทรงช่วยข้าพระองค์ให้รอด เพราะน้ําขึ้นมาถึงจิตวิญญาณข้าพระองค์แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 2, 'ข้าพระองค์จมอยู่ในเลนลึกไม่มีที่ยืน ข้าพระองค์มาอยู่ในน้ําลึกและน้ําท่วมข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 3, 'ข้าพระองค์อ่อนระอาใจด้วยเหตุร้องไห้ คอของข้าพระองค์แห้งผาก ตาของข้าพระองค์มัวลง ด้วยการคอยท่าพระเจ้าของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 4, 'บรรดาคนที่เกลียดชังข้าพระองค์โดยไร้เหตุ มีมากยิ่งกว่าเส้นผมบนศีรษะข้าพระองค์ คนที่จะทําลายข้าพระองค์ก็มีอิทธิพล คือผู้ที่เป็นพวกศัตรูของข้าพระองค์อย่างไม่มีเหตุ แล้วข้าพระองค์ได้ส่งคืนสิ่งที่ข้าพระองค์มิได้ขโมยไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 5, 'โอ ข้าแต่พระเจ้า พระองค์ทรงทราบถึงความโง่ของข้าพระองค์ ความผิดบาปที่ข้าพระองค์กระทําแล้วมิได้ซ่อนไว้จากพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 6, 'โอ ข้าแต่องค์พระผู้เป็นเจ้าพระเจ้าจอมโยธา ขออย่าให้บรรดาผู้ที่คอยท่าพระองค์ได้รับความอายเพราะข้าพระองค์ โอ ข้าแต่พระเจ้าของอิสราเอล ขออย่าให้บรรดาผู้ที่เสาะหาพระองค์ได้ความอัปยศเพราะข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 7, 'ที่ข้าพระองค์ทนการเยาะเย้ย ที่ความอับอายได้คลุมหน้าข้าพระองค์ไว้ก็เพราะเห็นแก่พระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 8, 'ข้าพระองค์กลายเป็นแขกแปลกหน้าของพี่น้อง และเป็นคนต่างด้าวของบุตรแห่งมารดาข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 9, 'ความร้อนใจในเรื่องพระนิเวศของพระองค์ได้ท่วมท้นข้าพระองค์ และคําพูดเยาะเย้ยของบรรดาผู้ที่เยาะเย้ยพระองค์ ตกอยู่แก่ข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 10, 'เมื่อข้าพระองค์ร้องไห้และถ่อมใจลงด้วยการอดอาหาร มันกลายเป็นการเยาะเย้ยข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 11, 'ข้าพระองค์ใช้ผ้ากระสอบเป็นเครื่องนุ่งห่ม ข้าพระองค์กลายเป็นขี้ปากของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 12, 'คนที่นั่งที่ประตูเมืองก็พูดตําหนิข้าพระองค์ คนขี้เมาแต่งเพลงร้องว่าข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 13, 'โอ ข้าแต่พระเยโฮวาห์ แต่ส่วนข้าพระองค์ ข้าพระองค์อธิษฐานต่อพระองค์ในเวลาอันเหมาะสม โอ ข้าแต่พระเจ้า โดยความเมตตาอันอุดมของพระองค์ ขอทรงโปรดฟังข้าพระองค์ด้วยความจริงแห่งความรอดของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 14, 'ขอทรงช่วยข้าพระองค์ให้พ้นจากจมลงในเลน ขอทรงช่วยข้าพระองค์ให้พ้นจากคนที่เกลียดชังข้าพระองค์และจากน้ําลึก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 15, 'ขออย่าให้น้ําท่วมข้าพระองค์ หรือน้ําที่ลึกกลืนข้าพระองค์เสีย หรือปากแดนผู้ตายงับข้าพระองค์ไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 16, 'โอ ข้าแต่พระเยโฮวาห์ ขอทรงฟังข้าพระองค์ เพราะความเมตตาของพระองค์นั้นเลิศ ขอทรงหันมาหาข้าพระองค์ตามพระกรุณาอันอุดมของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 17, 'ขออย่าทรงซ่อนพระพักตร์ของพระองค์เสียจากผู้รับใช้ของพระองค์ เพราะข้าพระองค์ทุกข์ใจ ขอทรงรีบฟังข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 18, 'ขอมาใกล้จิตวิญญาณข้าพระองค์ ทรงไถ่จิตวิญญาณนั้นไว้ เพราะศัตรูของข้าพระองค์ ขอทรงปลดเปลื้องข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 19, 'พระองค์ทรงทราบการที่เขาเยาะเย้ยข้าพระองค์แล้ว ทั้งความอายและความอัปยศของข้าพระองค์ บรรดาคู่อริของข้าพระองค์อยู่ต่อพระพักตร์พระองค์หมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 20, 'การเยาะเย้ยกระทําให้จิตใจข้าพระองค์ชอกช้ํา ข้าพระองค์จึงหมดกําลังใจ ข้าพระองค์มองหาผู้สงสาร แต่ก็ไม่มี หาผู้เล้าโลม แต่ข้าพระองค์หาไม่พบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 21, 'เขาให้ดีหมีแก่ข้าพระองค์เป็นอาหาร ให้น้ําส้มสายชูแก่ข้าพระองค์ดื่มแก้กระหาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 22, 'ขอให้สํารับที่อยู่ตรงหน้าเขาเองกลายเป็นบ่วงแร้ว และสิ่งที่ควรเป็นสําหรับความสุขสบายของเขาให้กลายเป็นเครื่องดัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 23, 'ขอให้ตาของเขามืดไปเพื่อเขาจะได้มองไม่เห็น และทําบั้นเอวเขาให้สั่นสะเทือนเรื่อยไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 24, 'ขอทรงเทความกริ้วลงเหนือเขา และให้ความกริ้วอันร้อนยิ่งตามทันเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 25, 'ขอให้ที่อาศัยของเขารกร้างและอย่าให้ผู้ใดอาศัยอยู่ในเต็นท์ของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 26, 'เพราะเขาได้ข่มเหงผู้ที่พระองค์ทรงเฆี่ยนตี เขาเล่าถึงความเจ็บปวดของผู้ที่พระองค์ให้บาดเจ็บแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 27, 'ขอทรงเพิ่มโทษความชั่วช้า แล้วทรงเพิ่มอีก อย่าให้เขาได้รับความชอบธรรมจากพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 28, 'ขอให้เขาถูกลบออกเสียจากทะเบียนผู้มีชีวิต อย่าให้เขาขึ้นทะเบียนไว้ในหมู่คนชอบธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 29, 'แต่ข้าพระองค์ทุกข์ยากและมีความเศร้าโศก โอ ข้าแต่พระเจ้า ขอความรอดของพระองค์ตั้งข้าพระองค์ไว้ให้สูง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 30, 'ข้าพเจ้าจะสรรเสริญพระนามพระเจ้าด้วยบทเพลง ข้าพเจ้าจะยกย่องพระองค์โดยโมทนาพระคุณ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 31, 'การนั้นจะเป็นที่พอพระทัยพระเยโฮวาห์มากกว่าวัวผู้หรือวัวผู้ทั้งเขาและกีบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 32, 'บรรดาผู้ถ่อมใจจะเห็นและยินดี ท่านผู้เสาะหาพระเจ้า ขอให้ใจของท่านฟื้นชื่นขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 33, 'เพราะพระเยโฮวาห์ทรงสดับคนขัดสน และมิได้ทรงดูหมิ่นคนของพระองค์ที่ถูกจองจํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 34, 'ขอฟ้าสวรรค์และแผ่นดินโลกสรรเสริญพระองค์ ทั้งทะเลและสรรพสิ่งที่เคลื่อนไหวอยู่ในนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 35, 'เพราะพระเจ้าจะทรงช่วยศิโยนให้รอด และจะสร้างหัวเมืองยูดาห์ขึ้น เขาทั้งหลายจะอาศัยอยู่ที่นั่น และได้เป็นกรรมสิทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 36, 'เชื้อสายของผู้รับใช้ของพระองค์จะได้เป็นมรดก และบรรดาผู้ที่รักพระนามของพระองค์จะอยู่ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 1, 'ถึงหัวหน้านักร้อง เพลงสดุดีของดาวิด สําหรับการบูชาอันเป็นที่ระลึกโอ ข้าแต่พระเจ้า ขอทรงเร่งมาช่วยข้าพระองค์ให้พ้น โอ ข้าแต่พระเยโฮวาห์ ขอทรงเร่งมาช่วยข้าพระองค์เถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 2, 'ขอให้ผู้ที่มุ่งเอาชีวิตของข้าพระองค์ได้อายและเกิดความอลวน ขอให้ผู้ปรารถนาที่จะให้ข้าพระองค์เจ็บนั้นต้องหันกลับไปและได้ความอัปยศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 3, 'ผู้ที่พูดว่า “อ้าฮา อ้าฮา” นั้นขอให้ต้องหันกลับไปเพราะเป็นผลแห่งความอายของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 4, 'ขอให้บรรดาผู้ที่แสวงหาพระองค์เปรมปรีดิ์และยินดีในพระองค์ ขอให้บรรดาผู้ที่รักความรอดของพระองค์ กล่าวเสมอว่า “พระเจ้าใหญ่ยิ่งนัก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 5, 'แต่ข้าพระองค์ยากจนและขัดสน โอ ข้าแต่พระเจ้า ขอทรงรีบมาหาข้าพระองค์ โอ ข้าแต่พระเยโฮวาห์ ขออย่าทรงรอช้า พระองค์ทรงเป็นผู้อุปถัมภ์และผู้ช่วยให้พ้นของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 1, 'โอ ข้าแต่พระเยโฮวาห์ ข้าพระองค์วางใจในพระองค์ อย่าให้ข้าพระองค์รับความละอายเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 2, 'ขอทรงช่วยข้าพระองค์ให้พ้นและหลีกเลี่ยงหลบหนีโดยความชอบธรรมของพระองค์ ขอทรงเอียงพระกรรณฟังข้าพระองค์ ขอทรงช่วยข้าพระองค์ให้รอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 3, 'ขอพระองค์ทรงเป็นที่ลี้ภัยเข้มแข็งของข้าพระองค์ที่ข้าพระองค์อาศัยเสมอ พระองค์ทรงบัญชาที่จะช่วยข้าพระองค์ให้รอด เพราะพระองค์ทรงเป็นศิลาและเป็นป้อมปราการของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 4, 'โอ ข้าแต่พระเจ้าของข้าพระองค์ ขอทรงช่วยข้าพระองค์ให้พ้นจากมือคนชั่ว จากเงื้อมมือของคนอธรรมและคนดุร้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 5, 'โอ ข้าแต่องค์พระผู้เป็นเจ้าพระเจ้า เพราะพระองค์ทรงเป็นความหวังของข้าพระองค์ พระองค์ทรงเป็นที่วางใจของข้าพระองค์ตั้งแต่เด็กๆมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 6, 'ข้าพระองค์พึ่งพระองค์ตั้งแต่กําเนิด พระองค์ทรงเป็นผู้นําข้าพระองค์มาจากครรภ์มารดาข้าพระองค์ ข้าพระองค์จะสรรเสริญพระองค์เสมอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 7, 'ข้าพระองค์เป็นที่อัศจรรย์ใจของคนเป็นอันมาก แต่พระองค์ทรงเป็นที่ลี้ภัยเข้มแข็งของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 8, 'ขอให้ปากของข้าพระองค์เต็มไปด้วยการสรรเสริญพระองค์ และถวายเกียรติแด่พระองค์วันยังค่ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 9, 'เมื่อวัยชรา ขออย่าทรงเหวี่ยงข้าพระองค์ทิ้งเสีย ขออย่าทรงทอดทิ้งข้าพระองค์เมื่อข้าพระองค์หมดแรง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 10, 'เพราะบรรดาศัตรูของข้าพระองค์กล่าวร้ายข้าพระองค์ บรรดาผู้ที่จ้องเอาชีวิตของข้าพระองค์ปรึกษากัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 11, 'และกล่าวว่า “พระเจ้าทรงทอดทิ้งเขาแล้ว จงข่มเหงและฉวยเขาไว้ เพราะไม่มีผู้ใดช่วยเขาให้พ้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 12, 'โอ ข้าแต่พระเจ้า ขออย่าทรงอยู่ไกลข้าพระองค์ โอ ข้าแต่พระเจ้าของข้าพระองค์ ขอทรงรีบมาช่วยข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 13, 'ขอให้ศัตรูชีวิตของข้าพระองค์รับความอายและถูกล้างผลาญเสีย ผู้เสาะหาที่จะทําอันตรายข้าพระองค์นั้น ขอให้การเยาะเย้ยและความอัปยศท่วมเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 14, 'แต่ข้าพระองค์จะหวังอยู่ตลอดไป และจะสรรเสริญพระองค์มากยิ่งขึ้นๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 15, 'ปากของข้าพระองค์จะเล่าถึงความชอบธรรมและความรอดของพระองค์วันยังค่ํา เพราะจํานวนเหล่านั้นมากมายเกินความรู้ของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 16, 'ข้าพระองค์จะไปด้วยพระกําลังขององค์พระผู้เป็นเจ้าพระเจ้า ข้าพระองค์จะกล่าวถึงความชอบธรรมของพระองค์ ของพระองค์เท่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 17, 'โอ ข้าแต่พระเจ้า พระองค์ทรงสอนข้าพระองค์ตั้งแต่เด็กๆมา และข้าพระองค์ยังป่าวร้องราชกิจมหัศจรรย์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 18, 'แม้จะถึงวัยชราและผมหงอกก็ตาม โอ ข้าแต่พระเจ้า ขออย่าทรงทอดทิ้งข้าพระองค์เสีย จนกว่าข้าพระองค์จะประกาศถึงอานุภาพของพระองค์แก่ชั่วอายุถัดไป และฤทธิ์เดชของพระองค์แก่บรรดาผู้ที่จะเกิดมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 19, 'โอ ข้าแต่พระเจ้า ความชอบธรรมของพระองค์ไปถึงที่สูงนั้น โอ ข้าแต่พระเจ้า พระองค์ผู้ได้ทรงกระทําการใหญ่ ผู้ใดจะเหมือนพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 20, 'พระองค์ผู้ทรงกระทําให้ข้าพระองค์ประสบความทุกข์ยากลําบากเป็นอันมากจะทรงรื้อข้าพระองค์ขึ้นมาอีก พระองค์จะทรงนําข้าพระองค์ขึ้นมาอีกจากที่ลึกของโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 21, 'พระองค์จะทรงเพิ่มเกียรติแก่ข้าพระองค์ และเล้าโลมข้าพระองค์รอบด้าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 22, 'โอ ข้าแต่พระเจ้าของข้าพระองค์ ฝ่ายข้าพระองค์จะสรรเสริญพระองค์ด้วยพิณใหญ่ถึงเรื่องความจริงของพระองค์ โอ ข้าแต่องค์บริสุทธิ์แห่งอิสราเอล ข้าพระองค์จะร้องเพลงสรรเสริญพระองค์ด้วยพิณเขาคู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 23, 'ริมฝีปากของข้าพระองค์จะโห่ร้องด้วยความชื่นบาน เมื่อข้าพระองค์ร้องเพลงสรรเสริญพระองค์ ทั้งจิตวิญญาณของข้าพระองค์ด้วย ซึ่งพระองค์ได้ทรงไถ่ไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 24, 'และลิ้นของข้าพระองค์จะพูดถึงความชอบธรรมของพระองค์ตลอดวันยังค่ํา เพราะผู้ซึ่งแสวงหาที่จะทําอันตรายข้าพระองค์ได้รับความอับอายและอัปยศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 1, 'เพลงสดุดีเพื่อซาโลมอนโอ ข้าแต่พระเจ้า ขอประทานความยุติธรรมของพระองค์แก่กษัตริย์ และความชอบธรรมของพระองค์แก่ราชโอรส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 2, 'ท่านจะได้พิพากษาประชาชนของพระองค์ด้วยความชอบธรรม และคนยากจนของพระองค์ด้วยความยุติธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 3, 'บรรดาภูเขาจะบังเกิดสันติสุขสําหรับประชาชน และเนินเขา โดยความชอบธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 4, 'ท่านจะสู้คดีของคนยากจนแห่งประชาชน ให้การช่วยให้พ้นแก่ลูกหลานของคนขัดสน และจะทุบผู้บีบบังคับเป็นชิ้นๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 5, 'พวกเขาจะเกรงกลัวพระองค์ตราบที่ดวงอาทิตย์และดวงจันทร์คงอยู่ ตลอดทุกชั่วอายุ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 6, 'ท่านจะเป็นเหมือนฝนที่ตกบนหญ้าที่ตัดแล้ว เหมือนห่าฝนที่รดแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 7, 'ในสมัยของท่านคนชอบธรรมจะเจริญขึ้น และสันติภาพจะอุดมจนไม่มีดวงจันทร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 8, 'ท่านจะครอบครองจากทะเลถึงทะเล และจากแม่น้ํานั้นถึงที่สุดปลายแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 9, 'บรรดาผู้ที่อยู่ในถิ่นทุรกันดารจะกราบลงต่อท่าน และบรรดาศัตรูของท่านจะเลียผงคลีดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 10, 'บรรดากษัตริย์แห่งเมืองทารชิชและของเกาะทั้งปวงจะถวายเครื่องราชบรรณาการ บรรดากษัตริย์แห่งเชบาและเส-บาจะนําของกํานัลมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 11, 'กษัตริย์ทั้งปวงจะกราบลงไหว้ท่าน บรรดาประชาชาติจะปรนนิบัติท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 12, 'เพราะท่านจะช่วยคนขัดสนให้พ้นเมื่อเขาร้องทูล คนยากจน และคนที่ไร้ผู้อุปถัมภ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 13, 'ท่านจะสงสารคนอ่อนเปลี้ย และคนขัดสน และช่วยชีวิตบรรดาคนขัดสน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 14, 'ท่านจะไถ่ชีวิตของเขาจากการหลอกลวงและความรุนแรง และโลหิตของเขาจะประเสริฐในสายตาของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 15, 'ท่านผู้นั้นจะมีชีวิตยืนนาน คนจะถวายทองคําเมืองเชบาแก่ท่าน เขาจะอธิษฐานเผื่อท่านเรื่อยไป และจะอวยพรท่านวันยังค่ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 16, 'จะมีข้าวอุดมในแผ่นดินบนยอดภูเขาทั้งหลาย ผลของแผ่นดินจะแกว่งไกวเหมือนเลบานอน และคนจากนครจะบานออกเหมือนหญ้าในทุ่งนา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 17, 'นามของท่านจะดํารงอยู่เป็นนิตย์ ชื่อเสียงของท่านจะยั่งยืนอย่างดวงอาทิตย์ คนจะอวยพรกันเองโดยใช้ชื่อท่าน ประชาชาติทั้งปวงจะเรียกท่านว่าผู้ได้รับพระพร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 18, 'สาธุการแด่พระเยโฮวาห์พระเจ้า พระเจ้าแห่งอิสราเอล ผู้ทรงกระทําสิ่งมหัศจรรย์แต่พระองค์เดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 19, 'สาธุการแด่พระนามรุ่งโรจน์ของพระองค์เป็นนิตย์ ขอสง่าราศีของพระองค์เต็มโลก เอเมนและเอเมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 20, 'คําอธิษฐานของดาวิด บุตรชายของเจสซี จบเท่านี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 1, 'เพลงสดุดีของอาสาฟแท้จริงพระเจ้าทรงดีต่ออิสราเอล ต่อบุคคลผู้มีใจบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 2, 'แต่ข้าพเจ้าเล่า เท้าของข้าพเจ้าเกือบสะดุด ย่างเท้าของข้าพเจ้าหมิ่นพลาดเต็มทีแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 3, 'เพราะข้าพเจ้าริษยาคนโง่เขลาเมื่อข้าพเจ้าเห็นความเจริญรุ่งเรืองของคนชั่ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 4, 'เพราะเขาทั้งหลายไม่มีความเจ็บปวดเมื่อเขาตายไป แต่กําลังของเขายังสมบูรณ์อยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 5, 'เขาทั้งหลายไม่ลําบากอย่างคนอื่นๆ เขาทั้งหลายไม่รับภัยอย่างคนอื่นๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 6, 'เพราะฉะนั้นความเย่อหยิ่งจึงเป็นสร้อยคอของเขา ความทารุณคลุมเขาไว้อย่างเครื่องแต่งกาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 7, 'ตาของเขาพองด้วยความอ้วนพี เขามีสิ่งของเหลือเฟือตามใจปรารถนา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 8, 'เขาเย้ยและพูดด้วยความมุ่งร้าย เขาใฝ่สูงขู่ว่าจะบีบบังคับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 9, 'เขาอ้าปากสู้ฟ้าสวรรค์ และลิ้นของเขาก็คะนองไปในโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 10, 'ประชาชนของพระองค์จึงหันกลับมา และน้ําแห่งความบริบูรณ์ถูกบีบให้เขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 11, 'และเขาทั้งหลายพูดว่า “พระเจ้าทรงทราบได้อย่างไร พระองค์ผู้สูงสุดมีความรู้หรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 12, 'ดูเถิด คนอธรรมเป็นเช่นนี้แหละ เขาเจริญในแผ่นดินโลกและร่ํารวยขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 13, 'แท้จริง ข้าพเจ้าชําระใจให้สะอาด และชําระมือด้วยความบริสุทธิ์ก็เปล่าประโยชน์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 14, 'เพราะข้าพเจ้ารับภัยอยู่วันยังค่ําและถูกขนาบอยู่ทุกเช้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 15, 'ถ้าข้าพระองค์ได้พูดว่า “ข้าพเจ้าจะพูดอย่างนี้” ดูเถิด ข้าพระองค์จะทําผิดต่อชั่วอายุแห่งบุตรทั้งหลายของพระองค์แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 16, 'แต่เมื่อข้าพระองค์ตริตรองว่า จะเข้าใจเรื่องนี้ได้อย่างไร ข้าพระองค์รู้สึกว่า เป็นงานที่เหน็ดเหนื่อย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 17, 'จนข้าพระองค์เข้าไปในสถานบริสุทธิ์ของพระเจ้า แล้วข้าพระองค์จึงพิเคราะห์เห็นปลายทางของเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 18, 'จริงละ พระองค์ทรงวางเขาไว้ในที่ลื่น พระองค์ทรงกระทําให้เขาล้มถึงความพินาศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 19, 'เขาถูกนําไปสู่การรกร้างในครู่เดียวเสียจริงๆ เขาถูกครอบงําด้วยความสยดสยองอย่างสิ้นเชิง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 20, 'โอ ข้าแต่องค์พระผู้เป็นเจ้า เหมือนความฝันทั้งที่ตื่นอยู่ เมื่อพระองค์ทรงตื่นอยู่ พระองค์จะดูหมิ่นภาพของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 21, 'เมื่อจิตใจของข้าพระองค์ขมขื่น เมื่อข้าพระองค์เสียวแปลบถึงหัวใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 22, 'ข้าพระองค์โฉดและไม่เดียงสา ข้าพระองค์ประพฤติเหมือนสัตว์ต่อพระพักตร์พระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 23, 'ถึงกระนั้นก็ดี ข้าพระองค์อยู่กับพระองค์เสมอ พระองค์ทรงจับมือขวาของข้าพระองค์ไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 24, 'พระองค์จะทรงนําข้าพระองค์ด้วยความปรึกษาของพระองค์ และภายหลังพระองค์จะทรงนําข้าพระองค์ให้ได้รับเกียรติยศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 25, 'นอกจากพระองค์ ข้าพระองค์มิมีผู้ใดในฟ้าสวรรค์ นอกจากพระองค์แล้ว ข้าพระองค์ไม่ปรารถนาผู้ใดในโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 26, 'เนื้อหนังและจิตใจของข้าพระองค์จะวายไป แต่พระเจ้าทรงเป็นกําลังใจของข้าพระองค์ และเป็นส่วนของข้าพระองค์เป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 27, 'เพราะดูเถิด บุคคลผู้ห่างเหินจากพระองค์จะพินาศ พระองค์ทรงให้บุคคลที่ไม่จริงใจต่อพระองค์ดับไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 28, 'แต่ส่วนข้าพระองค์ ที่จะเข้าใกล้พระเจ้านั้นเป็นสิ่งที่ดี ข้าพระองค์ได้วางใจในองค์พระผู้เป็นเจ้าพระเจ้า เพื่อข้าพระองค์จะได้เล่าถึงพระราชกิจทั้งสิ้นของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 1, 'มัสคิลบทหนึ่งของอาสาฟโอ ข้าแต่พระเจ้า ไฉนพระองค์ทรงเหวี่ยงข้าพระองค์ทั้งหลายทิ้งเสียเป็นนิตย์ ไฉนความกริ้วของพระองค์กรุ่นขึ้นต่อแกะแห่งทุ่งหญ้าของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 2, 'ขอทรงระลึกถึงชุมนุมชนของพระองค์ ซึ่งพระองค์ทรงไถ่มาแต่ดึกดําบรรพ์ ซึ่งพระองค์ทรงไถ่ไว้ให้เป็นตระกูลที่เป็นมรดกของพระองค์ ขอทรงระลึกถึงภูเขาศิโยน ซึ่งพระองค์ทรงเคยประทับนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 3, 'ขอทรงนําย่างพระบาทของพระองค์มายังซากปรักหักพังอยู่เนืองนิตย์ คือมายังสิ่งทั้งปวงที่ถูกศัตรูกระทําอย่างชั่วร้ายในสถานบริสุทธิ์นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 4, 'พวกคู่อริของพระองค์คํารามอยู่กลางสถานประชุมของพระองค์ เขาตั้งธงของเขาเองไว้เป็นหมายสําคัญ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 5, 'คนหนึ่งคนใดเคยมีชื่อเสียงเหมือนคนยกขวานขึ้นเหนือหมู่ต้นไม้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 6, 'แต่บัดนี้บรรดาไม้ที่แกะสลักทั้งสิ้นเขาก็พังลงมาเสียด้วยขวานและค้อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 7, 'เขาเอาไฟเผาสถานบริสุทธิ์ของพระองค์ เขาทําลายความศักดิ์สิทธิ์แห่งสถานที่พระนามของพระองค์ประทับนั้นลงถึงดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 8, 'เขารําพึงในใจว่า “เราจงทําลายเขาทั้งหลายให้สิ้นเชิง” เขาเผาบรรดาธรรมศาลาของพระเจ้าที่ในแผ่นดินจนหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 9, 'พวกเราไม่เห็นหมายสําคัญทั้งหลายของเรา ไม่มีผู้พยากรณ์อีกแล้ว ในพวกเราไม่มีใครทราบว่านานเท่าใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 10, 'โอ ข้าแต่พระเจ้า คู่อริจะเย้ยอยู่นานเท่าใด ศัตรูจะหมิ่นประมาทพระนามของพระองค์เป็นนิตย์หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 11, 'ไฉนพระองค์จึงหดพระหัตถ์ของพระองค์เสีย คือพระหัตถ์ขวาของพระองค์ ขอทรงเหยียดพระหัตถ์จากพระทรวงของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 12, 'ถึงกระนั้น พระเจ้า กษัตริย์ของข้าพระองค์ ทรงอยู่แต่ดึกดําบรรพ์ ทรงประกอบกิจความรอดท่ามกลางแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 13, 'พระองค์ทรงแยกทะเลด้วยฤทธานุภาพของพระองค์ พระองค์ทรงหักหัวมังกรในน้ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 14, 'พระองค์ทรงทุบหัวทั้งหลายของเลวีอาธานเป็นชิ้นๆ พระองค์ประทานมันให้เป็นอาหารของคนที่อาศัยอยู่ในถิ่นทุรกันดาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 15, 'พระองค์ทรงแยกหินเปิดน้ําพุและลําธาร พระองค์ทรงให้แม่น้ําที่ไหลอยู่เสมอแห้งไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 16, 'วันเป็นของพระองค์ คืนเป็นของพระองค์ด้วย พระองค์ทรงสถาปนาความสว่างและดวงอาทิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 17, 'พระองค์ทรงกําหนดเขตทั้งสิ้นของแผ่นดินโลก พระองค์ทรงสร้างฤดูร้อนและฤดูหนาว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 18, 'โอ ข้าแต่พระเยโฮวาห์ ขอทรงระลึกถึงข้อนี้ว่า ศัตรูเยาะเย้ยอย่างไร และชนชาติโง่เขลาได้หมิ่นประมาทพระนามของพระองค์อย่างไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 19, 'โอ ขออย่าทรงมอบวิญญาณนกเขาของพระองค์แก่ฝูงชนโหดร้าย ขออย่าทรงลืมชุมนุมชนยากจนของพระองค์เป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 20, 'ขอสนพระทัยในพันธสัญญา เพราะสถานที่มืดของแผ่นดินเต็มไปด้วยที่อยู่ของความทารุณ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 21, 'โอ ขออย่าให้ผู้ที่ถูกบีบบังคับได้อาย ขอให้คนจนและคนขัดสนสรรเสริญพระนามของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 22, 'โอ ข้าแต่พระเจ้า ขอทรงลุกขึ้น สู้คดีของพระองค์ ขอทรงระลึกว่าคนโง่เย้ยพระองค์อยู่วันยังค่ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 23, 'ขออย่าทรงลืมเสียงของคู่อริของพระองค์ เสียงอึงคะนึงของคนที่ลุกขึ้นสู้พระองค์ก็เพิ่มขึ้นอยู่เรื่อยๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 1, 'ถึงหัวหน้านักร้อง ตามทํานองอาลทัสชิท เพลงสดุดีหรือบทเพลงของอาสาฟโอ ข้าแต่พระเจ้า ข้าพระองค์ทั้งหลายขอโมทนาพระองค์ ข้าพระองค์ทั้งหลายขอโมทนาพระองค์ เพราะบรรดาพระราชกิจมหัศจรรย์ของพระองค์ประกาศว่าพระนามของพระองค์อยู่ใกล้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 2, 'เมื่อสถานประชุมมาอยู่ต่อหน้าเรา เราจะพิพากษาด้วยความเที่ยงธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 3, 'เมื่อแผ่นดินโลกละลาย พร้อมทั้งบรรดาชาวแผ่นดินโลกนั้น ผู้ที่รักษาเสาของมันให้มั่นอยู่คือเราเอง เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 4, 'เราพูดกับคนโง่เขลาว่า “อย่าประพฤติโง่เขลา” และแก่คนชั่วว่า “อย่ายกเขาขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 5, 'อย่ายกเขาของเจ้าขึ้นให้สูง หรือพูดจาอย่างคอแข็ง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 6, 'เพราะการยกขึ้นนั้นมิได้มาจากทิศตะวันออกหรือทิศตะวันตก และมิใช่มาจากทิศใต้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 7, 'แต่พระเจ้าทรงเป็นผู้พิพากษา พระองค์ทรงให้คนหนึ่งลง และทรงยกอีกคนหนึ่งขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 8, 'เพราะในพระหัตถ์ของพระเยโฮวาห์มีถ้วยใบหนึ่ง มีน้ําองุ่นเป็นฟอง ประสมไว้ดี พระองค์ทรงเทของดื่มจากถ้วยนั้นและคนชั่วของแผ่นดินโลกทั้งสิ้นจะดื่มหมดทั้งตะกอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 9, 'แต่ข้าพเจ้าจะประกาศเป็นนิตย์ ข้าพเจ้าจะร้องเพลงสรรเสริญพระเจ้าของยาโคบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 10, '“บรรดาเขาของคนชั่วจะถูกเราตัดออกหมด แต่เขาของผู้ชอบธรรมจะถูกเชิดชูขึ้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 1, 'ถึงหัวหน้านักร้องใช้เครื่องสาย เพลงสดุดีหรือบทเพลงของอาสาฟในยูดาห์เขารู้จักพระเจ้า ในอิสราเอลพระนามของพระองค์ใหญ่ยิ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 2, 'ที่ประทับของพระองค์ตั้งอยู่ในซาเล็ม ที่พํานักของพระองค์อยู่ในศิโยน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 3, 'ที่นั่นพระองค์ทรงหักลูกธนูทั้งโล่ ดาบ และการยุทธ์ เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 4, 'พระองค์ทรงรุ่งโรจน์สูงส่งยิ่งกว่าภูเขาที่มีเหยื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 5, 'ด้วยว่าคนใจเข้มแข็งถูกริบข้าวของ เขาหลับไป ชายฉกรรจ์ทั้งสิ้นไม่สามารถใช้มือของเขาได้อีกแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 6, 'โอ ข้าแต่พระเจ้าของยาโคบ พอพระองค์ทรงขนาบทั้งรถม้าและม้าก็ล่วงลับไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 7, 'แต่พระองค์เจ้า พระองค์ทรงเป็นที่น่าคร้ามกลัว เมื่อพระองค์ทรงกริ้วขึ้นแล้วใครจะยืนอยู่ในสายพระเนตรของพระองค์ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 8, 'พระองค์ทรงลั่นคําพิพากษามาจากฟ้าสวรรค์ แผ่นดินโลกก็กลัวและนิ่งเงียบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 9, 'เมื่อพระเจ้าทรงลุกขึ้นพิพากษา เพื่อช่วยผู้ถ่อมตัวทั้งสิ้นของแผ่นดินโลกให้รอด เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 10, 'แน่ละ ความโกรธของมนุษย์จะสรรเสริญพระองค์ และความโกรธที่เหลืออยู่นั้นพระองค์จะทรงยับยั้งไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 11, 'จงปฏิญาณต่อพระเยโฮวาห์พระเจ้าของท่านทั้งหลาย และจงปฏิบัติตาม ให้คนที่อยู่รอบพระองค์นําของกํานัลมายังพระองค์ผู้ซึ่งเขาควรเกรงกลัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 12, 'พระองค์จะทรงตัดดวงจิตของผู้ครอบครองทั้งหลาย พระองค์ทรงเป็นที่น่าคร้ามกลัวแก่บรรดากษัตริย์แห่งแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 1, 'ถึงหัวหน้านักร้อง ตามทํานองเยดูธูน เพลงสดุดีของอาสาฟข้าพเจ้าร้องทูลต่อพระเจ้าด้วยเสียงของข้าพเจ้า ทูลต่อพระเจ้าด้วยเสียงของข้าพเจ้า และพระองค์ได้ทรงเงี่ยพระกรรณสดับข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 2, 'ในวันยากลําบากของข้าพเจ้า ข้าพเจ้าแสวงหาองค์พระผู้เป็นเจ้า ในกลางคืนบาดแผลข้าพเจ้าไหลออกไม่หยุด จิตใจของข้าพเจ้าไม่รับคําเล้าโลม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 3, 'ข้าพเจ้าระลึกถึงพระเจ้า ข้าพเจ้าก็ครวญคราง ข้าพเจ้าคร่ําครวญ จิตใจของข้าพเจ้าก็อ่อนระอาไป เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 4, 'พระองค์ทรงจับหนังตาของข้าพระองค์ไว้ไม่ให้ปิด ข้าพระองค์ทุกข์มากจนพูดไม่ออก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 5, 'ข้าพระองค์พิจารณาถึงสมัยก่อน ข้าพระองค์จําปีที่นมนานมาแล้วได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 6, 'ข้าพระองค์ระลึกถึงบทเพลงของข้าพระองค์ในกลางคืน ข้าพระองค์ตรึกตรองกับจิตใจของตนเอง และจิตวิญญาณของข้าพระองค์ก็เสาะหา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 7, '“องค์พระผู้เป็นเจ้าจะทรงทอดทิ้งเป็นนิตย์ และจะไม่เคยพอพระทัยอีกหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 8, 'ความเมตตาของพระองค์จะระงับอยู่เป็นนิตย์หรือ พระสัญญาของพระองค์สิ้นสุดตลอดทุกชั่วอายุหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 9, 'พระเจ้าทรงลืมที่จะทรงพระกรุณาหรือ เพราะพระพิโรธพระองค์จึงทรงปิดความเวทนาเสียหรือ” เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 10, 'และข้าพเจ้าว่า “นั่นแหละเป็นความทุกข์ของข้าพเจ้า แต่ข้าพเจ้าจะระลึกถึงปีทั้งหลายแห่งพระหัตถ์ขวาของพระองค์ผู้สูงสุด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 11, 'ข้าพเจ้าจะระลึกถึงพระราชกิจทั้งปวงของพระเยโฮวาห์ พระเจ้าข้า ข้าพระองค์จะจดจําบรรดาการมหัศจรรย์ของพระองค์ในสมัยก่อนๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 12, 'ข้าพระองค์จะไตร่ตรองถึงพระราชกิจทั้งสิ้นของพระองค์ และกล่าวถึงพระราชกิจของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 13, 'โอ ข้าแต่พระเจ้า วิธีการของพระองค์อยู่ในสถานบริสุทธิ์ พระองค์ใดจะยิ่งใหญ่อย่างพระเจ้าของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 14, 'พระองค์คือพระเจ้าผู้ทรงกระทําการมหัศจรรย์ ผู้ทรงสําแดงฤทธานุภาพของพระองค์ท่ามกลางชนชาติทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 15, 'พระองค์ได้ทรงไถ่ประชาชนของพระองค์ด้วยพระกรของพระองค์ คือลูกหลานของยาโคบและโยเซฟ เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 16, 'โอ ข้าแต่พระเจ้า เมื่อน้ําเห็นพระองค์ น้ําเห็นพระองค์ มันก็เกรงกลัวแน่ทีเดียว ที่ลึกก็สั่นสะท้าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 17, 'เมฆเทน้ําลงมา ท้องฟ้าก็คะนองเสียง ลูกธนูของพระองค์ก็ปลิวไปปลิวมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 18, 'ฟ้าผ่าของพระองค์มีเสียงอยู่ในฟ้าสวรรค์ ฟ้าแลบทําให้พิภพสว่าง แผ่นดินโลกก็สั่นสะเทือนและหวั่นไหว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 19, 'พระมรรคาของพระองค์อยู่ในทะเล พระวิถีของพระองค์อยู่ในน้ํามหึมาทั้งหลาย ถึงกระนั้นรอยพระบาทของพระองค์ก็ไม่มีใครรู้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 20, 'พระองค์ทรงนําประชาชนของพระองค์โดยมือของโมเสสและอาโรนเหมือนฝูงแพะแกะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 1, 'มัสคิลบทหนึ่งของอาสาฟโอ ประชาชนของข้าพเจ้าเอ๋ย จงเงี่ยหูฟังกฎของข้าพเจ้า เอียงหูของท่านทั้งหลายฟังถ้อยคําจากปากข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 2, 'ข้าพเจ้าจะอ้าปากกล่าวคําอุปมา ข้าพเจ้าจะกล่าวคําลึกลับของโบราณกาล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 3, 'ถึงสิ่งที่เราทั้งหลายได้ยินได้ทราบ ที่บรรพบุรุษของเราได้บอกเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 4, 'เราจะไม่ซ่อนไว้จากลูกหลานของเขา แต่จะบอกแก่ชั่วอายุที่กําลังเกิดมา ถึงการสรรเสริญพระเยโฮวาห์ และฤทธานุภาพของพระองค์ และการมหัศจรรย์ซึ่งพระองค์ได้ทรงกระทํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 5, 'เพราะพระองค์ทรงสถาปนาพระโอวาทไว้ในยาโคบ และทรงแต่งตั้งพระราชบัญญัติไว้ในอิสราเอล ซึ่งพระองค์ทรงบัญชาแก่บรรพบุรุษของเรา ว่าให้แจ้งเรื่องราวเหล่านั้นแก่ลูกหลานของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 6, 'เพื่อชั่วอายุรุ่นต่อไปจะทราบเรื่องคือลูกหลานที่จะเกิดมา และที่จะลุกขึ้นบอกลูกหลานของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 7, 'เพื่อเขาจะตั้งความหวังของเขาไว้ในพระเจ้า และไม่ลืมพระราชกิจของพระเจ้า แต่รักษาพระบัญญัติของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 8, 'และเพื่อเขาจะมิได้เหมือนบรรพบุรุษของเขา คือชั่วอายุที่ดื้อดึงและมักกบฏ ชั่วอายุที่จิตใจไม่มั่นคง ผู้ซึ่งจิตวิญญาณของเขาไม่มั่นคงต่อพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 9, 'บรรดาคนเอฟราอิม มีอาวุธพร้อมและถือคันธนู ได้หันกลับในวันสงคราม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 10, 'เขาทั้งหลายมิได้รักษาพันธสัญญาของพระเจ้า และปฏิเสธที่จะเดินตามพระราชบัญญัติของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 11, 'เขาลืมสิ่งที่พระองค์ได้ทรงกระทําและการมหัศจรรย์ซึ่งพระองค์ทรงสําแดงแก่เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 12, 'พระองค์ทรงกระทําการมหัศจรรย์ท่ามกลางสายตาของบรรพบุรุษของเขา ในแผ่นดินอียิปต์ ในไร่นาโศอัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 13, 'พระองค์ทรงแยกทะเล และให้เขาเดินผ่านไป และกระทําให้น้ําตั้งอยู่เหมือนกองสูง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 14, 'ในกลางวันพระองค์ทรงนําเขาด้วยเมฆ และด้วยแสงไฟคืนยังรุ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 15, 'พระองค์ทรงผ่าหินในถิ่นทุรกันดาร ประทานน้ําเป็นอันมากให้เขาดื่มเหมือนมาจากที่ลึก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 16, 'พระองค์ทรงกระทําให้ลําธารออกมาจากหิน ทรงกระทําให้น้ําไหลลงมาเหมือนแม่น้ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 17, 'แต่เขายังกระทําบาปยิ่งขึ้นต่อพระองค์ โดยได้ยั่วองค์ผู้สูงสุดในที่แห้งแล้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 18, 'เขาทดลองพระเจ้าอยู่ในใจของเขาโดยเรียกร้องอาหารที่เขาอยาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 19, 'เขาพูดปรักปรําพระเจ้าว่า “พระเจ้าจะทรงเตรียมสํารับในถิ่นทุรกันดารได้หรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 20, 'ดูเถิด พระองค์ทรงตีหินให้น้ําพุออกมา และลําธารก็ไหลล้น พระองค์จะประทานขนมปังด้วยได้หรือ หรือทรงจัดเนื้อให้ประชาชนของพระองค์ได้หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 21, 'เพราะฉะนั้น เมื่อพระเยโฮวาห์ทรงสดับแล้ว พระองค์ทรงพระพิโรธ มีไฟลุกโพลงขึ้นสู้ยาโคบ พระพิโรธของพระองค์พลุ่งขึ้นสู้อิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 22, 'เพราะเขาไม่เชื่อพระเจ้า และไม่ไว้วางใจในความรอดของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 23, 'พระองค์ยังทรงบัญชาเมฆเบื้องบน และทรงเปิดประตูฟ้าสวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 24, 'พระองค์ทรงหลั่งมานาให้เขารับประทาน และทรงประทานอาหารทิพย์ให้เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 25, 'มนุษย์ได้กินอาหารของทูตสวรรค์ พระองค์ทรงประทานอาหารให้เขาอย่างอุดม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 26, 'พระองค์ทรงกระทําให้ลมตะวันออกพัดในฟ้าสวรรค์ และทรงนําลมใต้ออกมาด้วยฤทธิ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 27, 'พระองค์ทรงหลั่งเนื้อให้เขาอย่างผงคลี คือนก ดังเม็ดทรายในทะเล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 28, 'พระองค์ทรงให้มันตกลงมากลางค่ายของเขา และรอบที่อาศัยของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 29, 'เขาได้รับประทานอิ่มดี เพราะพระองค์ประทานสิ่งที่เขาอยาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 30, 'แต่ก่อนที่เขาจะหายอยาก ขณะที่อาหารยังอยู่ในปากของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 31, 'พระพิโรธของพระเจ้าพลุ่งขึ้นต่อเขา และพระองค์ทรงสังหารคนฉกรรจ์ที่สุดของเขาเสีย และทรงคว่ําคนที่คัดเลือกแล้วในอิสราเอลเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 32, 'ถึงมีเรื่องทั้งสิ้นนี้ เขาก็ยังกระทําบาป เขามิได้เชื่อถือการมหัศจรรย์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 33, 'พระองค์จึงทรงกระทําให้วันของเขาหายไปด้วยการกระทําที่ไร้สาระ และทรงให้ปีของเขาหายไปด้วยความยากลําบาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 34, 'เมื่อพระองค์ทรงสังหารเขา เขาแสวงหาพระองค์ เขาได้กลับมาแสวงพระเจ้าด้วยใจร้อนรน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 35, 'เขาระลึกว่าพระเจ้าทรงเป็นศิลาของเขา และพระเจ้าองค์สูงสุดเป็นพระผู้ไถ่ของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 36, 'แต่เขายอพระองค์ด้วยปากของเขา และมุสาต่อพระองค์ด้วยลิ้นของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 37, 'เพราะจิตใจของเขาไม่แน่วแน่ต่อพระองค์ เขาไม่จริงจังต่อพันธสัญญาของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 38, 'แต่พระองค์ทรงเต็มไปด้วยความเมตตากรุณา พระองค์ทรงอภัยความชั่วช้าของเขา และมิได้ทรงทําลายเขา พระองค์ทรงยับยั้งพระพิโรธของพระองค์บ่อยๆ และมิได้ทรงกวนพระพิโรธของพระองค์ทั้งสิ้นให้ขึ้นมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 39, 'พระองค์ทรงระลึกว่าเขาเป็นเพียงแต่เนื้อหนัง เป็นลมที่ผ่านไปแล้วมิได้กลับมาอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 40, 'เขายั่วพระองค์ในถิ่นทุรกันดารบ่อยสักเท่าใด และทําให้พระองค์โทมนัสในทะเลทราย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 41, 'แต่เขายังได้กลับทดลองพระเจ้าอีกและได้ทําให้องค์บริสุทธิ์ของอิสราเอลเศร้าพระทัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 42, 'เขามิได้ระลึกถึงพระหัตถ์ของพระองค์ หรือวันที่พระองค์ทรงช่วยเขาให้พ้นจากคู่อริของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 43, 'เมื่อพระองค์ทรงกระทําหมายสําคัญของพระองค์ในอียิปต์ และการมหัศจรรย์ของพระองค์ในไร่นาโศอัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 44, 'พระองค์ทรงเปลี่ยนแม่น้ําและลําธารของเขาให้เป็นเลือด เพื่อเขาดื่มอะไรไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 45, 'พระองค์ทรงส่งฝูงเหลือบหลายชนิดมาท่ามกลางเขา ซึ่งผลาญเขา และกบ ซึ่งทําลายเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 46, 'พระองค์ประทานพืชผลของเขาแก่ตั๊กแตนวัยคลาน และผลแห่งแรงงานของเขาแก่ตั๊กแตนวัยบิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 47, 'พระองค์ทรงทําลายเถาองุ่นของเขาด้วยลูกเห็บ และต้นมะเดื่อของเขาด้วยน้ําค้างแข็ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 48, 'พระองค์ทรงมอบฝูงวัวของเขาไว้กับลูกเห็บ และฝูงแพะแกะของเขากับฟ้าผ่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 49, 'พระองค์ทรงปล่อยความกริ้วดุร้ายของพระองค์มาเหนือเขา ทั้งพระพิโรธ ความกริ้วและความทุกข์ลําบาก โดยส่งเหล่าทูตสวรรค์ชั่วร้ายท่ามกลางเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 50, 'พระองค์ทรงเปิดวิถีให้แก่ความกริ้วของพระองค์ พระองค์มิได้ทรงเว้นจิตวิญญาณเขาไว้จากความตาย แต่ประทานชีวิตของเขาแก่โรคระบาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 51, 'พระองค์ทรงประหารลูกหัวปีทั้งสิ้นในอียิปต์ คือผลแรกแห่งกําลังของเขาในเต็นท์ของฮาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 52, 'แล้วพระองค์ทรงนําประชาชนของพระองค์ออกมาเหมือนนําแกะ และนําเขาไปในถิ่นทุรกันดารเหมือนฝูงแพะแกะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 53, 'พระองค์นําเขาไปอย่างปลอดภัย เขาจึงไม่กลัว แต่ทะเลท่วมศัตรูของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 54, 'และพระองค์ทรงพาเขามายังเขตแดนแห่งสถานบริสุทธิ์ของพระองค์ ยังภูเขานี้ ซึ่งพระหัตถ์ขวาของพระองค์ได้ทรงไถ่ไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 55, 'พระองค์ทรงขับประชาชาติต่างๆออกไปข้างหน้าเขา พระองค์ทรงวัดแบ่งแดนประชาชาตินั้นให้เป็นมรดก และทรงตั้งบรรดาตระกูลอิสราเอลไว้ในเต็นท์ของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 56, 'แต่เขาทั้งหลายยังทดลองและยั่วพระเจ้าองค์สูงสุด มิได้รักษาบรรดาพระโอวาทของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 57, 'กลับหันไปเสียและประพฤติทรยศอย่างบรรพบุรุษของเขา เขาบิดไปเหมือนคันธนูที่ไว้ใจไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 58, 'เพราะเขายั่วเย้าพระองค์ให้ทรงกริ้วด้วยเรื่องปูชนียสถานสูงของเขาทั้งหลาย ได้ยั่วยุให้พระองค์หวงแหนเขาด้วยเรื่องรูปเคารพแกะสลักของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 59, 'เมื่อพระเจ้าทรงสดับ พระองค์ทรงพระพิโรธยิ่ง และพระองค์ทรงรังเกียจอิสราเอลยิ่งนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 60, 'พระองค์ทรงละพลับพลาในชีโลห์ คือเต็นท์ที่พระองค์ทรงตั้งไว้ท่ามกลางมนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 61, 'และทรงมอบฤทธานุภาพของพระองค์แก่การเป็นเชลย และสง่าราศีของพระองค์แก่มือของคู่อริ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 62, 'พระองค์ทรงมอบประชาชนของพระองค์แก่ดาบ และทรงพระพิโรธต่อมรดกของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 63, 'ไฟผลาญหนุ่มๆของเขาเสีย และสาวๆของเขาก็ไม่ได้แต่งงาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 64, 'บรรดาปุโรหิตของเขาล้มลงด้วยดาบ และแม่ม่ายของเขาไม่มีการร้องทุกข์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 65, 'แล้วองค์พระผู้เป็นเจ้าทรงตื่นอย่างตื่นบรรทม อย่างชายฉกรรจ์โห่ร้องเพราะฤทธิ์เหล้าองุ่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 66, 'และพระองค์ทรงตีปฏิปักษ์ของพระองค์ทางด้านหลัง และให้เขาได้อายเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 67, 'พระองค์ทรงปฏิเสธพลับพลาของโยเซฟ พระองค์มิได้ทรงเลือกตระกูลเอฟราอิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 68, 'แต่พระองค์ทรงเลือกตระกูลยูดาห์ ภูเขาศิโยนซึ่งพระองค์ทรงรัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 69, 'พระองค์ทรงสร้างสถานบริสุทธิ์ของพระองค์อย่างกับพระราชวังสูง อย่างแผ่นดินโลกซึ่งพระองค์ตั้งไว้เป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 70, 'พระองค์ทรงเลือกดาวิดผู้รับใช้ของพระองค์ ทรงพาท่านมาจากคอกแกะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 71, 'พระองค์ทรงพาท่านมาจากการดูแลแม่แกะที่มีลูกอ่อนให้เป็นผู้เลี้ยงดูยาโคบประชาชนของพระองค์ และอิสราเอลมรดกของพระองค์อย่างเลี้ยงแกะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 72, 'ท่านจึงเลี้ยงดูเขาทั้งหลายด้วยใจเที่ยงธรรม และนําเขาทั้งหลายไปด้วยมือช่ําชอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 1, 'เพลงสดุดีของอาสาฟโอ ข้าแต่พระเจ้า พวกต่างชาติได้เข้าในมรดกของพระองค์ เขาได้ทําให้พระวิหารบริสุทธิ์ของพระองค์มีมลทิน เขาได้ทําให้เยรูซาเล็มเป็นที่ปรักหักพัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 2, 'เขาให้ศพผู้รับใช้ของพระองค์เป็นอาหารแก่บรรดานกในอากาศ ให้เนื้อของวิสุทธิชนของพระองค์แก่สัตว์ป่าแห่งแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 3, 'เขาได้เทโลหิตของคนเหล่านั้นออกมาอย่างน้ํารอบเยรูซาเล็ม จนไม่มีคนฝังศพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 4, 'เรากลายเป็นที่เย้ยหยันแก่เพื่อนบ้านของเรา เป็นที่สบประมาทและเยาะเย้ยแก่คนที่อยู่รอบเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 5, 'ข้าแต่พระเยโฮวาห์ พระองค์ทรงกริ้วอีกนานเท่าใด เป็นนิตย์หรือ พระเจ้าข้า ความหวงแหนของพระองค์จะไหม้ดังไฟไปอีกนานเท่าใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 6, 'ขอทรงเทความกริ้วของพระองค์ลงเหนือบรรดาประชาชาติที่ไม่รู้จักพระองค์ และเหนือราชอาณาจักรทั้งหลายที่ไม่ร้องทูลออกพระนามของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 7, 'เพราะเขาทั้งหลายได้ผลาญยาโคบ และกระทําให้ที่อาศัยของเขาร้างเปล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 8, 'โอ ขออย่าทรงระลึกถึงความชั่วช้าของบรรพบุรุษของข้าพระองค์ทั้งหลาย ขอความสังเวชของพระองค์เร่งมาพบข้าพระองค์ทั้งหลาย เพราะข้าพระองค์ทั้งหลายตกต่ํามาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 9, 'โอ ข้าแต่พระเจ้าแห่งความรอดของข้าพระองค์ทั้งหลาย ขอทรงช่วยข้าพระองค์ เพราะเห็นแก่สง่าราศีแห่งพระนามของพระองค์ ขอทรงช่วยข้าพระองค์ให้พ้นและอภัยบาปของข้าพระองค์ เพราะเห็นแก่พระนามของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 10, 'ควรหรือที่บรรดาประชาชาติจะกล่าวว่า “พระเจ้าของเขาอยู่ที่ไหน” ขอให้พระองค์ทรงปรากฏในท่ามกลางประชาชาติต่อสายตาของข้าพระองค์ทั้งหลาย โดยการแก้แค้นโลหิตของผู้รับใช้พระองค์ที่ไหลออกมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 11, 'ขอให้เสียงคร่ําครวญของบรรดาเชลยมาอยู่ต่อพระพักตร์พระองค์ ด้วยฤทธานุภาพอันยิ่งใหญ่ของพระองค์ ขอทรงสงวนคนเหล่านั้นที่ต้องถึงตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 12, 'โอ ข้าแต่องค์พระผู้เป็นเจ้า ขอทรงตอบแทนการที่เพื่อนบ้านของข้าพระองค์ได้เย้ยหยันต่อพระองค์ สักเจ็ดเท่า ณ ทรวงอกของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 13, 'แล้วข้าพระองค์ทั้งหลายประชากรของพระองค์ ฝูงแพะแกะแห่งทุ่งหญ้าของพระองค์ จะโมทนาพระคุณพระองค์เป็นนิตย์ ข้าพระองค์ทั้งหลายจะกล่าวสรรเสริญพระองค์ตลอดทุกชั่วอายุ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 1, 'ถึงหัวหน้านักร้อง ตามทํานองโชชานิมเอดูท เพลงสดุดีของอาสาฟโอ ข้าแต่พระผู้ทรงเลี้ยงดูอิสราเอลอย่างเลี้ยงแกะ คือพระองค์ผู้ทรงนําโยเซฟอย่างนําฝูงแพะแกะ ขอทรงเงี่ยพระกรรณสดับ พระผู้ประทับระหว่างพวกเครูบ ขอทรงทอแสงออกมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 2, 'ต่อหน้าเอฟราอิม และเบนยามิน และมนัสเสห์ ขอทรงปลุกพระราชอํานาจของพระองค์ขึ้นมาช่วยข้าพระองค์ทั้งหลายให้รอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 3, 'โอ ข้าแต่พระเจ้า ขอทรงช่วยข้าพระองค์ทั้งหลายให้กลับสู่สภาพดี ขอพระพักตร์ของพระองค์ทอแสง เพื่อข้าพระองค์ทั้งหลายจะรอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 4, 'โอ ข้าแต่พระเยโฮวาห์พระเจ้าจอมโยธา พระองค์จะทรงกริ้วต่อคําอธิษฐานของประชาชนของพระองค์นานสักเท่าใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 5, 'พระองค์ได้ทรงเลี้ยงเขาด้วยน้ําตาต่างอาหาร และทรงให้เขาดื่มน้ําตาอย่างเต็มขนาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 6, 'พระองค์ทรงกระทําให้ข้าพระองค์เป็นที่แตกร้าวกันในหมู่เพื่อนบ้านของข้าพระองค์ และศัตรูของข้าพระองค์หัวเราะกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 7, 'โอ ข้าแต่พระเจ้าจอมโยธา ขอทรงช่วยข้าพระองค์ทั้งหลายให้กลับสู่สภาพดี ขอพระพักตร์ของพระองค์ทอแสง เพื่อข้าพระองค์ทั้งหลายจะรอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 8, 'พระองค์ทรงนําเถาองุ่นออกจากอียิปต์ พระองค์ทรงขับไล่บรรดาประชาชาติออกไปและทรงปลูกเถาองุ่นไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 9, 'พระองค์ทรงปราบดินให้ มันก็หยั่งรากลึกและแผ่เต็มแผ่นดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 10, 'ร่มเงาของมันคลุมภูเขาและกิ่งก้านของมันเหมือนต้นสนสีดาร์อันดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 11, 'มันส่งกิ่งไปถึงทะเลและส่งแขนงไปถึงแม่น้ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 12, 'ทําไมพระองค์จึงทรงพังรั้วต้นไม้ลงเสีย บรรดาคนทั้งสิ้นที่ผ่านไปตามทางจึงเด็ดผลของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 13, 'หมูป่าจากดงมาย่ํายีมันและบรรดาสัตว์ป่าในไร่นากินมันเป็นอาหาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 14, 'โอ ข้าแต่พระเจ้าจอมโยธา ขอทรงหันกลับเถิด พระเจ้าข้า ขอทรงมองจากฟ้าสวรรค์และทรงเห็น ขอทรงสนพระทัยในเถาองุ่นนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 15, 'คือสวนองุ่นซึ่งพระหัตถ์ขวาของพระองค์ทรงปลูกไว้ และกิ่งที่พระองค์ทรงให้เจริญแข็งแรงเพื่อพระองค์เอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 16, 'มันถูกเผาเสียด้วยไฟ มันถูกตัดลง พวกเขาพินาศด้วยการตําหนิจากสีพระพักตร์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 17, 'ขอพระหัตถ์ของพระองค์จงอยู่เหนือผู้ที่อยู่เบื้องขวาพระหัตถ์ของพระองค์ คือบุตรของมนุษย์ที่พระองค์ทรงกระทําให้แข็งแรงเพื่อพระองค์เอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 18, 'แล้วข้าพระองค์ทั้งหลายจะไม่หันกลับมาจากพระองค์ ขอทรงสงวนชีวิตข้าพระองค์ทั้งหลายไว้ แล้วข้าพระองค์ทั้งหลายจะทูลออกพระนามพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 19, 'โอ ข้าแต่พระเยโฮวาห์พระเจ้าจอมโยธา ขอทรงช่วยข้าพระองค์ทั้งหลายให้กลับสู่สภาพดี ขอพระพักตร์ของพระองค์ทอแสง เพื่อข้าพระองค์ทั้งหลายจะรอดได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 1, 'ถึงหัวหน้านักร้อง ตามทํานองกิททีธ เพลงสดุดีของอาสาฟจงร้องเพลงถวายพระเจ้า พระกําลังของพวกเรา จงเปล่งเสียงอย่างชื่นบานถวายแด่พระเจ้าของยาโคบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 2, 'จงเปล่งเสียงสดุดี จงตีรํามะนาทั้งพิณเขาคู่อันไพเราะ และพิณใหญ่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 3, 'จงเป่าแตรในวันขึ้นหนึ่งค่ํา ในเวลาที่กําหนดไว้ ณ วันการเลี้ยงของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 4, 'เพราะเป็นกฎเกณฑ์สําหรับอิสราเอล เป็นพระราชบัญญัติของพระเจ้าแห่งยาโคบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 5, 'พระองค์ทรงตั้งให้เป็นพระโอวาทในโยเซฟ เมื่อพระองค์ทรงออกไปสู่แผ่นดินอียิปต์ ในที่ซึ่งข้าพเจ้าได้ยินภาษาซึ่งข้าพเจ้าไม่เคยรู้จัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 6, 'ว่า “เราผ่อนบ่าของเขาจากภาระของเขา มือเขาเป็นอิสระพ้นกระจาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 7, 'เมื่อทุกข์ใจเจ้าเรียก เราก็ช่วยเจ้าให้พ้น เราตอบเจ้าในที่ลับลี้ของฟ้าร้อง เราได้ทดลองเจ้าที่น้ํา ณ เมรีบาห์ เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 8, 'โอ ประชาชนของเราเอ๋ย จงฟัง แล้วเราจะทักท้วงเจ้า โอ อิสราเอลเอ๋ย ถ้าเจ้าจะฟังเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 9, 'จะไม่มีพระแปลกๆท่ามกลางเจ้าเลย เจ้าจะไม่กราบไหว้พระต่างด้าว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 10, 'เราคือพระเยโฮวาห์พระเจ้าของเจ้า ผู้ได้พาเจ้าออกมาจากแผ่นดินอียิปต์ อ้าปากของเจ้าให้กว้างเถิด เราจะป้อนเจ้าให้อิ่ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 11, 'แต่ประชาชนของเราไม่ฟังเสียงของเรา อิสราเอลไม่ยอมรับเราเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 12, 'เราจึงมอบเขาไว้แก่จิตใจดื้อด้านของเขาเอง ให้ดําเนินตามคําปรึกษาของเขาเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 13, 'โอ ประชาชนของเรา น่าจะฟังเรา และอิสราเอล น่าจะเดินในทางทั้งหลายของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 14, 'แล้วไม่ช้า เราก็จะให้ศัตรูของเขานอบน้อมลง และจะหันมือของเราสู้คู่อริของเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 15, 'บรรดาผู้ที่เกลียดชังพระเยโฮวาห์จะหมอบราบต่อพระองค์ “แต่เวลาของเขาทั้งหลายจะยั่งยืนอยู่เป็นนิตย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 16, 'พระองค์จะทรงเลี้ยงเขาด้วยข้าวสาลีอย่างดีที่สุด “เราจะให้เจ้าพอใจด้วยน้ําผึ้งที่มาจากหิน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 1, 'เพลงสดุดีของอาสาฟพระเจ้าทรงเข้าประทับในชุมนุมชนของผู้มีอํานาจ พระองค์ทรงทําการพิพากษาท่ามกลางพระทั้งหลายว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 2, '“ท่านจะตัดสินอย่างไม่ยุติธรรมและแสดงความลําเอียงเข้าข้างคนชั่วนานเท่าใด เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 3, 'จงให้ความยุติธรรมแก่คนยากจนและกําพร้าพ่อ จงดํารงสิทธิของผู้ที่ทุกข์ยากและคนขัดสน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 4, 'จงช่วยคนยากจนและคนขัดสนให้พ้น ช่วยเขาให้พ้นจากมือของคนชั่ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 5, 'เขาทั้งหลายไม่รู้และไม่เข้าใจ เขาเดินไปมาในความมืด รากทั้งสิ้นของแผ่นดินโลกก็หวั่นไหว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 6, 'เราได้กล่าวว่า “ท่านทั้งหลายเป็นพระ เป็นบุตรขององค์ผู้สูงสุด ท่านทุกคนนั่นแหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 7, 'ถึงกระนั้น ท่านก็จะตายอย่างมนุษย์และล้มลงเหมือนเจ้านายคนใดคนหนึ่ง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 8, 'โอ ข้าแต่พระเจ้า ขอทรงลุกขึ้นพิพากษาแผ่นดินโลก เพราะบรรดาประชาชาติทั้งสิ้นจะเป็นมรดกของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 1, 'บทเพลงหรือเพลงสดุดีของอาสาฟโอ ข้าแต่พระเจ้า ขออย่าทรงนิ่งอยู่ โอ ข้าแต่พระเจ้า ขออย่าทรงเงียบและเฉยอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 2, 'เพราะดูเถิด ศัตรูของพระองค์สับสนอลหม่าน บรรดาผู้ที่ชังพระองค์ได้ยกศีรษะของเขาขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 3, 'เขาวางแผนการแยบคายสู้ประชาชนของพระองค์ เขาปรึกษากันสู้ผู้ที่พระองค์ทรงซ่อนไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 4, 'เขาพูดว่า “มาเถิด ให้เราตัดเขาออกจากการเป็นประชาชาติ เพื่อจะไม่ระลึกถึงชื่ออิสราเอลอีกต่อไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 5, 'เพราะเขาปองร้ายเป็นใจเดียวกัน เขาทําพันธสัญญาสู้พระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 6, 'คือ เต็นท์ของเอโดม และคนอิชมาเอล โมอับ และคนฮาการ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 7, 'เกบาล อัมโมน และอามาเลข ฟีลิสเตียกับชาวเมืองไทระ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 8, 'อัสซีเรียก็สมทบเขาด้วย เขาได้ช่วยลูกหลานของโลท เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 9, 'ขอทรงทํากับเขาอย่างพระองค์ทรงกระทํากับมีเดียน อย่างที่ทํากับสิเสราและยาบินที่ลําธารคีโชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 10, 'ผู้ถูกทําลายที่ตําบลเอนโดร์ ผู้กลายเป็นปุ๋ยของที่ดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 11, 'ขอทรงทําขุนนางของเขาเหมือนโอเรบและเศเอบ ทําเจ้านายทั้งสิ้นของเขาเหมือนเศบาห์และศัลมุนนา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 12, 'ผู้ที่กล่าวว่า “ให้เราเอาที่อาศัยทั้งหลายของพระเจ้ามาเป็นกรรมสิทธิ์ของเราเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 13, 'โอ ข้าแต่พระเจ้าของข้าพระองค์ ขอทรงทําเขาให้เหมือนกงจักร เหมือนแกลบต่อหน้าลม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 14, 'อย่างไฟเผาผลาญป่าไม้ อย่างเปลวเพลิงที่ให้ภูเขาลุกโพลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 15, 'ขอทรงก่อกวนเขาด้วยพายุแรงกล้าของพระองค์ และทรงทําให้เขาคร้ามกลัวด้วยพายุจัดของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 16, 'ทรงให้หน้าของเขาเต็มไปด้วยความอาย โอ ข้าแต่พระเยโฮวาห์ เพื่อเขาจะได้แสวงหาพระนามของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 17, 'ขอให้เขาอับอาย และกลัวอยู่เป็นนิตย์ ให้เขาอดสูและพินาศไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 18, 'เพื่อคนทั้งปวงจะทราบว่าพระองค์ ผู้ทรงพระนามว่าพระเยโฮวาห์แต่ผู้เดียว ทรงเป็นผู้สูงสุดเหนือแผ่นดินโลกทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 1, 'ถึงหัวหน้านักร้อง ตามทํานองกิททีธ เพลงสดุดีของคณะโคราห์โอ ข้าแต่พระเยโฮวาห์จอมโยธา ที่ประทับของพระองค์เป็นที่รักจริงๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 2, 'วิญญาณของข้าพระองค์ปรารถนา เออ อาลัยหาบริเวณพระนิเวศของพระเยโฮวาห์ ใจกายของข้าพระองค์โห่ร้องถวายพระเจ้าผู้ทรงพระชนม์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 3, 'แม้นกกระจอกก็หาบ้านได้ แล้วและนกนางแอ่นหารังสําหรับตัวมันได้ ที่ที่มันจะตกฟองออกลูก คือที่แท่นบูชาของพระองค์ โอ ข้าแต่พระเยโฮวาห์จอมโยธา กษัตริย์และพระเจ้าของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 4, 'ความสุขเป็นของบุคคลที่อาศัยในพระนิเวศของพระองค์ เขาจะร้องเพลงสรรเสริญพระองค์เสมอ เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 5, 'ความสุขเป็นของบุคคลที่กําลังของเขาอยู่ในพระองค์ คือคนที่ในใจของเขาเป็นทางทั้งหลายของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 6, 'ขณะที่เขาผ่านไปตามหว่างเขาบาคา เขากระทําให้เป็นบ่อน้ํา ฝนต้นฤดูกระทําให้สระน้ําเต็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 7, 'เขาไปด้วยมีกําลังมาเพิ่มขึ้นๆ เขาทั้งหลายจะเข้าเฝ้าพระเจ้าในศิโยน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 8, 'โอ ข้าแต่พระเยโฮวาห์พระเจ้าจอมโยธา ขอทรงสดับคําอธิษฐานของข้าพระองค์ โอ ข้าแต่พระเจ้าของยาโคบ ขอทรงเงี่ยพระกรรณ เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 9, 'ขอทอดพระเนตร โอ ข้าแต่พระเจ้าโล่ของข้าพระองค์ทั้งหลาย ขอทอดพระเนตรหน้าผู้รับเจิมของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 10, 'เพราะวันเดียวในบริเวณพระนิเวศของพระองค์ดีกว่าพันวันในที่อื่น ข้าพระองค์จะเป็นคนเฝ้าประตูพระนิเวศของพระเจ้าของข้าพระองค์ดีกว่าอยู่ในเต็นท์ของความชั่วร้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 11, 'เพราะพระเยโฮวาห์พระเจ้าทรงเป็นดวงอาทิตย์และเป็นโล่ พระเยโฮวาห์จะทรงประทานความกรุณาและเกียรติ พระองค์จะมิได้ทรงหวงของดีอันใดไว้เลยจากบุคคลผู้ดําเนินในความเที่ยงธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 12, 'โอ ข้าแต่พระเยโฮวาห์จอมโยธา บุคคลที่วางใจในพระองค์ก็เป็นสุข');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 1, 'ถึงหัวหน้านักร้อง เพลงสดุดีของคณะโคราห์ข้าแต่พระเยโฮวาห์ พระองค์ได้ทรงโปรดปรานแผ่นดินของพระองค์ พระองค์ทรงให้พวกเชลยของยาโคบกลับสู่สภาพดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 2, 'พระองค์ได้ทรงยกความชั่วช้าของประชาชนของพระองค์เสีย พระองค์ทรงกลบเกลื่อนบาปทั้งสิ้นของเขา เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 3, 'พระองค์ได้ทรงนําพระพิโรธทั้งสิ้นของพระองค์กลับ พระองค์ทรงเคยหันจากความกริ้วอันร้อนแรงของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 4, 'โอ ข้าแต่พระเจ้าแห่งความรอดของข้าพระองค์ทั้งหลาย ขอทรงช่วยข้าพระองค์ให้กลับคืนอีก ขอทรงระงับความกริ้วจากข้าพระองค์ทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 5, 'พระองค์จะทรงกริ้วต่อข้าพระองค์ทั้งหลายเป็นนิตย์หรือ พระองค์จะทรงให้ความกริ้วของพระองค์ดํารงตลอดทุกชั่วอายุหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 6, 'พระองค์จะไม่ทรงให้ข้าพระองค์ทั้งหลายฟื้นอีกหรือ เพื่อประชาชนของพระองค์จะได้เปรมปรีดิ์ในพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 7, 'โอ ข้าแต่พระเยโฮวาห์ ขอทรงสําแดงความเมตตาของพระองค์แก่ข้าพระองค์ทั้งหลาย และขอประทานความรอดของพระองค์แก่ข้าพระองค์ทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 8, 'ข้าพระองค์จะได้ฟังความที่พระเจ้าพระเยโฮวาห์จะตรัส เพราะพระองค์จะตรัสความสันติแก่ประชาชนของพระองค์ และแก่วิสุทธิชนของพระองค์ แต่อย่าให้เขาทั้งหลายหันกลับไปสู่ความโง่อีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 9, 'แน่ทีเดียวที่ความรอดของพระองค์อยู่ใกล้คนที่เกรงกลัวพระองค์ เพื่อสง่าราศีจะอยู่ในแผ่นดินของข้าพระองค์ทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 10, 'ความเมตตาและความจริงได้พบกัน ความชอบธรรมและสันติภาพได้จุบกันและกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 11, 'ความจริงจะงอกขึ้นมาจากแผ่นดิน และความชอบธรรมจะมองลงมาจากฟ้าสวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 12, 'เออ พระเยโฮวาห์จะประทานสิ่งที่ดีๆ และแผ่นดินของข้าพระองค์ทั้งหลายจะเกิดผล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 13, 'ความชอบธรรมจะนําหน้าพระองค์ และจะตั้งข้าพระองค์ทั้งหลายไว้ในมรรคาแห่งรอยพระบาทของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 1, 'คําอธิษฐานของดาวิดโอ ข้าแต่พระเยโฮวาห์ ขอทรงเงี่ยพระกรรณสดับข้าพระองค์ เพราะข้าพระองค์ยากจนและขัดสน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 2, 'ขอทรงสงวนชีวิตข้าพระองค์ไว้เพราะข้าพระองค์บริสุทธิ์ โอ ข้าแต่พระเจ้าของข้าพระองค์ ขอทรงช่วยผู้รับใช้ของพระองค์ผู้วางใจในพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 3, 'โอ ข้าแต่องค์พระผู้เป็นเจ้า ขอทรงพระกรุณาต่อข้าพระองค์ เพราะข้าพระองค์ร้องทูลต่อพระองค์วันยังค่ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 4, 'ขอทรงให้จิตใจผู้รับใช้ของพระองค์ยินดี โอ ข้าแต่องค์พระผู้เป็นเจ้า จิตใจข้าพระองค์ตั้งใจแน่วแน่ในพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 5, 'ข้าแต่องค์พระผู้เป็นเจ้า เพราะพระองค์ประเสริฐและทรงพร้อมที่จะประทานอภัย อุดมด้วยความเมตตาต่อบรรดาผู้ร้องทูลพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 6, 'โอ ข้าแต่พระเยโฮวาห์ ขอทรงเงี่ยพระกรรณสดับคําทูลอธิษฐานของข้าพระองค์ ขอทรงสดับเสียงร้องทูลวิงวอนของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 7, 'ในวันลําบากของข้าพระองค์ ข้าพระองค์จะร้องทูลพระองค์ เพราะพระองค์จะทรงตอบข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 8, 'โอ ข้าแต่องค์พระผู้เป็นเจ้า ในบรรดาพระไม่มีผู้ใดเหมือนพระองค์ และไม่มีกิจการใดๆเหมือนพระราชกิจของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 9, 'โอ ข้าแต่องค์พระผู้เป็นเจ้า บรรดาประชาชาติที่พระองค์ทรงสร้างจะมานมัสการต่อพระพักตร์พระองค์ และจะเทิดทูนพระนามของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 10, 'เพราะพระองค์ใหญ่ยิ่งและทรงกระทําการมหัศจรรย์ พระองค์แต่องค์เดียวทรงเป็นพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 11, 'โอ ข้าแต่พระเยโฮวาห์ ขอทรงสอนพระมรรคาของพระองค์แก่ข้าพระองค์ ข้าพระองค์จะดําเนินในความจริงของพระองค์ ขอทรงสํารวมใจของข้าพระองค์ให้ยําเกรงพระนามของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 12, 'โอ ข้าแต่องค์พระผู้เป็นเจ้าพระเจ้าของข้าพระองค์ ข้าพระองค์จะสรรเสริญพระองค์ด้วยสิ้นสุดใจ และข้าพระองค์จะเทิดทูนพระนามของพระองค์เป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 13, 'เพราะความเมตตาของพระองค์ที่ทรงมีต่อข้าพระองค์นั้นใหญ่ยิ่งนัก และพระองค์ทรงช่วยจิตวิญญาณของข้าพระองค์ให้พ้นจากที่ลึกที่สุดของนรก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 14, 'โอ ข้าแต่พระเจ้า คนหยิ่งยโสได้ลุกขึ้นต่อสู้ข้าพระองค์ หมู่คนทารุณเสาะหาชีวิตข้าพระองค์ เขามิได้ประดิษฐานพระองค์ไว้ตรงหน้าเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 15, 'โอ ข้าแต่องค์พระผู้เป็นเจ้า แต่พระองค์ทรงเป็นพระเจ้ากอปรด้วยพระกรุณาและพระเมตตา ทรงกริ้วช้า และอุดมด้วยความเมตตา และความจริง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 16, 'โอ ขอทรงหันมาเมตตาข้าพระองค์ ขอประทานกําลังแก่ผู้รับใช้ของพระองค์ และขอทรงช่วยชีวิตบุตรชายของหญิงคนใช้ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 17, 'ขอประทานหมายสําคัญแห่งความโปรดปรานของพระองค์แก่ข้าพระองค์ เพื่อคนที่เกลียดชังข้าพระองค์จะเห็น และจะได้อาย ข้าแต่พระเยโฮวาห์ เพราะพระองค์ได้ทรงช่วยข้าพระองค์และทรงเล้าโลมข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 1, 'เพลงสดุดีหรือบทเพลงของคณะโคราห์รากฐานของพระองค์อยู่บนภูเขาอันบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 2, 'พระเยโฮวาห์ทรงรักประตูศิโยนมากยิ่งกว่าบรรดาที่อาศัยของยาโคบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 3, 'โอ นครแห่งพระเจ้าเอ๋ย เขากล่าวสรรเสริญเธอ เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 4, 'ในบรรดาผู้ที่รู้จักเรา เราระบุชื่อราหับและบาบิโลน ดูเถิด ฟีลิสเตีย ไทระ และเอธิโอเปีย เขากล่าวกันว่า “ผู้นี้เกิดที่นั่น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 5, 'และเขาจะพูดเรื่องศิโยนว่า “ผู้นี้และผู้นั้นเกิดในเมืองนั้น” เพราะองค์ผู้สูงสุดนั่นแหละจะสถาปนาเมืองนั้นไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 6, 'ขณะที่พระเยโฮวาห์ทรงจดชนชาติทั้งหลาย พระองค์จะทรงบันทึกว่า “ผู้นี้เกิดที่นั่น” เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 7, 'นักร้องและนักเล่นเครื่องดนตรีจะอยู่ที่นั่น น้ําพุทั้งสิ้นของเราอยู่ในเธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 1, 'บทเพลงหรือเพลงสดุดีของคณะโคราห์ ถึงหัวหน้านักร้อง ตามทํานองมาหะลัท เลอันโนท มัสคิลบทหนึ่งของเฮมาน คนเอสราห์โอ ข้าแต่พระเยโฮวาห์พระเจ้าแห่งความรอดของข้าพระองค์ ข้าพระองค์ร้องทูลต่อพระพักตร์พระองค์ทั้งกลางวันและกลางคืน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 2, 'ขอคําอธิษฐานของข้าพระองค์มาจําเพาะเบื้องพระพักตร์ของพระองค์ ขอทรงเงี่ยพระกรรณสดับคําร้องทูลของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 3, 'เพราะจิตใจของข้าพระองค์ลําบากเต็มที และชีวิตของข้าพระองค์เข้าใกล้แดนผู้ตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 4, 'เขานับข้าพระองค์ในบรรดาผู้ที่ลงไปยังปากแดน ข้าพระองค์เป็นเหมือนชายที่ไม่มีกําลัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 5, 'เหมือนคนที่เขาทิ้งไว้ท่ามกลางคนตาย เหมือนคนถูกฆ่าที่นอนอยู่ในหลุมศพ ผู้ที่พระองค์มิได้ทรงระลึกถึงอีก และเขาทั้งหลายถูกพรากเสียจากพระหัตถ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 6, 'พระองค์ทรงใส่ข้าพระองค์ไว้ในส่วนลึกของปากแดนผู้ตาย ในแดนที่มืดและลึก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 7, 'พระพิโรธของพระองค์หนักอยู่บนข้าพระองค์ และพระองค์ทรงทับถมข้าพระองค์ด้วยคลื่นทั้งสิ้นของพระองค์ เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 8, 'พระองค์ทรงกันผู้ที่คุ้นเคยกับข้าพระองค์ให้ออกห่างจากข้าพระองค์ พระองค์ทรงกระทําให้ข้าพระองค์เป็นที่น่ารังเกียจต่อเขาทั้งหลาย ข้าพระองค์ถูกขัง ข้าพระองค์จึงออกไปไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 9, 'นัยน์ตาของข้าพระองค์มัวไปเพราะความทุกข์ ข้าแต่พระเยโฮวาห์ ข้าพระองค์ร้องทูลพระองค์ทุกวัน ข้าพระองค์ชูมือขึ้นต่อพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 10, 'พระองค์จะทรงกระทําการมหัศจรรย์เพื่อคนตายหรือ ชาวแดนผู้ตายจะลุกขึ้นสรรเสริญพระองค์ได้หรือ เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 11, 'เขาจะประกาศความเมตตาของพระองค์ในหลุมศพหรือ หรือจะประกาศความสัตย์สุจริตในแดนพินาศหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 12, 'ในความมืดเขาจะรู้จักการมหัศจรรย์ของพระองค์หรือ ในแผ่นดินแห่งความหลงลืมเขาจะรู้จักความชอบธรรมของพระองค์หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 13, 'โอ ข้าแต่พระเยโฮวาห์ แต่ข้าพระองค์ร้องทูลต่อพระองค์ ในเวลาเช้าคําอธิษฐานของข้าพระองค์จะขึ้นไปหาพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 14, 'ข้าแต่พระเยโฮวาห์ ไฉนพระองค์ทรงเหวี่ยงจิตวิญญาณข้าพระองค์ออกไปเสีย ไฉนพระองค์ทรงซ่อนพระพักตร์เสียจากข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 15, 'ตั้งแต่เป็นอนุชนมา ข้าพระองค์ทุกข์ยากและพร้อมที่จะตาย ขณะข้าพระองค์ทนต่อความสยดสยองของพระองค์ ข้าพระองค์มีจิตใจไขว้เขวไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 16, 'ความพิโรธอันแรงกล้าของพระองค์กวาดไปเหนือข้าพระองค์ สิ่งที่น่ากลัวจากพระองค์ตัดข้าพระองค์ออกเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 17, 'มันล้อมข้าพระองค์ไว้รอบวันยังค่ําอย่างน้ําท่วม มันท่วมข้าพระองค์มิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 18, 'พระองค์ทรงให้คนรักและสหายห่างเหินจากข้าพระองค์ ผู้ที่คุ้นเคยกับข้าพระองค์อยู่ในความมืด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 1, 'มัสคิลบทหนึ่งของเอธาน คนเอสราห์ข้าพระองค์จะร้องเพลงถึงความเมตตาของพระเยโฮวาห์เป็นนิตย์ ด้วยปากของข้าพระองค์ ข้าพระองค์จะประกาศความสัตย์สุจริตของพระองค์ตลอดทุกชั่วอายุ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 2, 'ด้วยข้าพระองค์ได้กล่าวแล้วว่า “ความเมตตาจะตั้งอยู่เป็นนิตย์ พระองค์จะสถาปนาความสัตย์สุจริตของพระองค์ในฟ้าสวรรค์ทีเดียว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 3, '“เราได้กระทําพันธสัญญากับผู้ที่ถูกเลือกของเรา เราได้ปฏิญาณกับดาวิดผู้รับใช้ของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 4, 'ว่า ‘เราจะสถาปนาเชื้อสายของเจ้าไว้เป็นนิตย์และจะสร้างบัลลังก์ของเจ้าไว้ทุกชั่วอายุ’” เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 5, 'โอ ข้าแต่พระเยโฮวาห์ ฟ้าสวรรค์จะสรรเสริญการมหัศจรรย์ของพระองค์ และสรรเสริญความสัตย์สุจริตของพระองค์ในที่ประชุมของบรรดาวิสุทธิชนด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 6, 'เพราะผู้ใดเล่าที่ในฟ้าสวรรค์จะเปรียบกับพระเยโฮวาห์ได้ ในบรรดาลูกหลานของผู้มีอํานาจผู้ใดจะเหมือนพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 7, 'คือองค์พระเจ้าผู้เป็นที่เกรงกลัวอย่างยิ่งในสภาของบรรดาวิสุทธิชน และบรรดาผู้ที่อยู่รอบพระองค์เกรงขามพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 8, 'โอ ข้าแต่พระเยโฮวาห์พระเจ้าจอมโยธา ข้าแต่พระเยโฮวาห์ ผู้ใดจะทรงฤทธานุภาพเท่าเทียมพระองค์ ด้วยความสัตย์สุจริตของพระองค์รอบพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 9, 'พระองค์ทรงปกครองการเดือดดาลของทะเล เมื่อคลื่นสูงขึ้นพระองค์ทรงให้สงบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 10, 'พระองค์ทรงทุบราหับเป็นชิ้นๆเหมือนผู้ถูกฆ่า พระองค์ทรงกระจายศัตรูของพระองค์ด้วยพระกรทรงฤทธิ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 11, 'ฟ้าสวรรค์เป็นของพระองค์ แผ่นดินโลกเป็นของพระองค์ด้วย พระองค์ได้ทรงตั้งพิภพและบรรดาสิ่งที่อยู่ในนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 12, 'ทิศเหนือและทิศใต้ พระองค์ก็ได้ทรงสร้าง ภูเขาทาโบร์กับภูเขาเฮอร์โมนจะสรรเสริญพระนามของพระองค์อย่างชื่นบาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 13, 'พระองค์มีพระกรอันทรงฤทธิ์ พระหัตถ์ของพระองค์ก็แข็งแรง พระหัตถ์ขวาของพระองค์ก็สูง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 14, 'ความเที่ยงธรรมและความยุติธรรมเป็นรากฐานแห่งบัลลังก์ของพระองค์ ความเมตตาและความจริงเดินนําหน้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 15, 'ชนชาติที่รู้จักโห่ร้องอย่างชื่นบานก็เป็นสุข โอ ข้าแต่พระเยโฮวาห์ พวกเขาจะเดินในความสว่างจากสีพระพักตร์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 16, 'พวกเขาจะปลาบปลื้มยินดีในพระนามพระองค์วันยังค่ํา และได้รับการเชิดชูโดยความชอบธรรมของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 17, 'เพราะพระองค์ทรงเป็นสง่าราศีแห่งกําลังของเขาทั้งหลาย แต่โดยความโปรดปรานของพระองค์ เขาของข้าพระองค์ทั้งหลายจะถูกเชิดชูขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 18, 'เพราะผู้ป้องกันเราทั้งหลายเป็นพระเยโฮวาห์ กษัตริย์ของเราเป็นองค์บริสุทธิ์แห่งอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 19, 'ในกาลก่อน พระองค์ตรัสด้วยนิมิตแก่ผู้บริสุทธิ์ของพระองค์และตรัสว่า “เราได้ช่วยเหลือชายฉกรรจ์คนหนึ่ง เราได้เชิดชูคนที่ถูกเลือกคนหนึ่งเหนือประชาชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 20, 'เราได้พบดาวิดผู้รับใช้ของเรา ด้วยน้ํามันบริสุทธิ์ของเรา เราได้เจิมเขาไว้แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 21, 'เพื่อว่ามือของเราจะอยู่กับเขาเป็นนิตย์ และแขนของเราจะเสริมกําลังของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 22, 'ศัตรูจะเรียกอะไรจากเขาไม่ได้ บุตรแห่งความชั่วร้ายจะกดขี่เขาไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 23, 'เราจะขยี้คู่อริของเขาต่อหน้าเขา และตีผู้ที่เกลียดเขาให้ล้มลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 24, 'ความสัตย์สุจริตและความเมตตาของเราจะอยู่กับเขา และเขาของเขาจะเป็นที่เชิดชูโดยนามของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 25, 'เราจะเอามือของเขาวางไว้บนทะเล และมือขวาของเขาบนแม่น้ําทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 26, 'เขาจะร้องต่อเราว่า ‘พระองค์ทรงเป็นพระบิดาของข้าพระองค์ พระเจ้าของข้าพระองค์ และเป็นศิลาแห่งความรอดของข้าพระองค์’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 27, 'และเราจะให้เขาเป็นบุตรหัวปีของเราด้วย สูงกว่าบรรดากษัตริย์แห่งแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 28, 'เราจะเก็บความเมตตาของเราไว้ให้เขาเป็นนิตย์ และพันธสัญญาของเราจะตั้งมั่นคงอยู่เพื่อเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 29, 'เราจะสถาปนาเชื้อสายของเขาไว้เป็นนิตย์ ทั้งบัลลังก์ของเขาให้ดํารงตราบเท่ากาลของฟ้าสวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 30, 'ถ้าลูกหลานของเขาทิ้งราชบัญญัติของเรา และไม่ดําเนินตามคําตัดสินของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 31, 'ถ้าเขาทั้งหลายฝ่าฝืนกฎเกณฑ์ของเรา และมิได้รักษาบัญญัติของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 32, 'แล้วเราจะลงโทษการละเมิดของเขาด้วยไม้เรียว และความชั่วช้าของเขาด้วยการเฆี่ยน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 33, 'แต่จะไม่ถอนความเมตตาของเราไปจากเขา หรือไม่ยอมให้ความสัตย์สุจริตของเราล้มเหลว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 34, 'เราจะไม่ฝ่าฝืนพันธสัญญาของเรา หรือพลิกแพลงถ้อยคําที่ออกไปจากริมฝีปากของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 35, 'เราปฏิญาณด้วยความบริสุทธิ์ของเราเด็ดขาดว่า เราจะไม่มุสาต่อดาวิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 36, 'เชื้อสายของเขาจะดํารงอยู่เป็นนิตย์ บัลลังก์ของเขาจะยืนนานอย่างดวงอาทิตย์ต่อหน้าเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 37, 'จะสถาปนาไว้อย่างดวงจันทร์เป็นนิตย์ และเหมือนสักขีพยานอันสัตย์ซื่อในท้องฟ้า” เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 38, 'แต่พระองค์ทรงได้เหวี่ยงออกไปและเกลียดชัง พระองค์ทรงพระพิโรธต่อผู้ที่เจิมไว้ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 39, 'พระองค์ได้ทรงบอกเลิกพันธสัญญากับผู้รับใช้ของพระองค์ พระองค์ทรงกระทํามงกุฎของท่านมลทินโดยเหวี่ยงลงสู่พื้นดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 40, 'พระองค์ได้พังรั้วต้นไม้ของท่านทั้งสิ้น พระองค์ทรงให้ที่กําบังเข้มแข็งของท่านปรักหักพังลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 41, 'คนทั้งปวงที่ผ่านไปก็ปล้นท่าน ท่านก็เป็นที่นินทาของเพื่อนบ้าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 42, 'พระองค์ทรงยกย่องมือขวาของคู่อริของท่าน พระองค์ทรงกระทําให้ศัตรูทั้งสิ้นของท่านเปรมปรีดิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 43, 'จริงทีเดียว พระองค์ทรงหันคมดาบของท่าน และพระองค์มิได้ทรงกระทําให้ท่านตั้งมั่นอยู่ในสงคราม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 44, 'พระองค์ได้ทรงกระทําให้สง่าของท่านเสื่อมสูญไป และทรงเหวี่ยงบัลลังก์ของท่านลงสู่พื้นดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 45, 'พระองค์ทรงตัดวันวัยหนุ่มของท่านให้สั้น และทรงคลุมท่านไว้ด้วยความอาย เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 46, 'ข้าแต่พระเยโฮวาห์ พระองค์จะซ่อนองค์อยู่นานเท่าใด เป็นนิตย์หรือ พระพิโรธของพระองค์จะไหม้อยู่นานเท่าใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 47, 'ขอทรงระลึกว่า ช่วงชีวิตของข้าพระองค์สั้นแค่ไหน ไฉนพระองค์ทรงเนรมิตสร้างบรรดามนุษย์มาอย่างเปล่าประโยชน์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 48, 'มนุษย์คนใดมีชีวิตอยู่ได้โดยไม่ต้องเห็นความตาย เขาจะช่วยจิตวิญญาณของตนให้พ้นจากมือของแดนผู้ตายได้หรือ เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 49, 'ข้าแต่องค์พระผู้เป็นเจ้า ความเมตตาในกาลก่อนของพระองค์อยู่ที่ไหน ซึ่งพระองค์ทรงปฏิญาณต่อดาวิดโดยความจริงของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 50, 'ข้าแต่องค์พระผู้เป็นเจ้า ขอทรงระลึกว่าผู้รับใช้ของพระองค์ถูกด่าอย่างไร และข้าพระองค์รับความสบประมาทของบรรดาชนชาติที่มีอํานาจใหญ่โตไว้ในอกของข้าพระองค์อย่างไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 51, 'โอ ข้าแต่พระเยโฮวาห์ นั่นแหละศัตรูของพระองค์ได้เย้ยหยัน นั่นแหละเขาเย้ยรอยเท้าของผู้ที่เจิมไว้ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 52, 'สาธุการแด่พระเยโฮวาห์เป็นนิตย์ เอเมนและเอเมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 1, 'คําอธิษฐานของโมเสส คนของพระเจ้าข้าแต่องค์พระผู้เป็นเจ้า พระองค์ทรงเป็นที่อาศัยของข้าพระองค์ทั้งหลายตลอดทุกชั่วอายุ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 2, 'ก่อนที่ภูเขาทั้งหลายเกิดขึ้นมา ก่อนที่พระองค์ทรงให้กําเนิดแผ่นดินโลกและพิภพ พระองค์ทรงเป็นพระเจ้าตั้งแต่นิรันดร์กาลถึงนิรันดร์กาล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 3, 'พระองค์ทรงให้มนุษย์กลับไปสู่ความพินาศ และตรัสว่า “บุตรทั้งหลายของมนุษย์เอ๋ย จงกลับเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 4, 'เพราะพันปีในสายพระเนตรของพระองค์เป็นเหมือนวานนี้ซึ่งผ่านไปแล้ว หรือเหมือนยามเดียวในเวลากลางคืน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 5, 'พระองค์ทรงกวาดมนุษย์ไปเสียอย่างน้ําท่วม เขาเป็นเหมือนการนอนหลับ เหมือนหญ้าที่งอกขึ้นใหม่ในเวลาเช้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 6, 'ในเวลาเช้ามันก็บานออกและใหญ่ขึ้น ครั้นเวลาเย็นก็ถูกตัดลงและเหี่ยวไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 7, 'เพราะข้าพระองค์ทั้งหลายถูกความกริ้วของพระองค์ผลาญเสีย ข้าพระองค์ก็เดือดร้อนเพราะพระพิโรธของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 8, 'พระองค์ทรงตั้งความชั่วช้าของข้าพระองค์ไว้ต่อพระพักตร์พระองค์ ทรงตั้งบาปลับๆของข้าพระองค์ไว้ในความสว่างแห่งพระพักตร์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 9, 'วันทั้งปวงของข้าพระองค์ทั้งหลายสิ้นไปใต้พระพิโรธของพระองค์ กําหนดปีของข้าพระองค์สิ้นสุดลงอย่างเสียงถอนหายใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 10, 'กําหนดปีของข้าพระองค์ทั้งหลายคือเจ็ดสิบหรือถ้าเป็นเหตุจากมีกําลังก็ถึงแปดสิบ แต่ช่วงชีวิตนั้นมีแต่งานและความโศกเศร้า ไม่ช้าก็สูญไปและข้าพระองค์ทั้งหลายก็จากไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 11, 'ผู้ใดจะทราบถึงฤทธิ์ความกริ้วของพระองค์ และพระพิโรธของพระองค์ตามความเกรงกลัวพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 12, 'ขอพระองค์ทรงสอนให้นับวันของข้าพระองค์ เพื่อข้าพระองค์ทั้งหลายจะตั้งจิตตั้งใจได้สติปัญญา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 13, 'โอ ข้าแต่พระเยโฮวาห์ ขอทรงหันมาเถิดพระเจ้าข้า หรือยังอีกนานเท่าใด ขอทรงมีความสงสารบรรดาผู้รับใช้ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 14, 'โอ ขอทรงให้ข้าพระองค์ทั้งหลายอิ่มในเวลาเช้าด้วยความเมตตาของพระองค์ เพื่อข้าพระองค์ทั้งหลายจะได้เปรมปรีดิ์และยินดีตลอดวันเวลาของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 15, 'ขอทรงให้ข้าพระองค์ทั้งหลายยินดีให้มากวันเท่ากับที่พระองค์ได้ทรงให้ข้าพระองค์ทุกข์ยากนั้น และให้มากปีเท่ากับที่ข้าพระองค์ได้ประสบการร้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 16, 'ขอให้พระราชกิจของพระองค์ปรากฏแก่ผู้รับใช้ของพระองค์ และให้สง่าราศีของพระองค์ปรากฏแก่ลูกหลานของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 17, 'ขอความงามของพระเยโฮวาห์พระเจ้าของข้าพระองค์อยู่เหนือข้าพระองค์ทั้งหลาย ขอทรงสถาปนาหัตถกิจของข้าพระองค์เหนือข้าพระองค์ พระเจ้าข้า ขอพระองค์ทรงสถาปนาหัตถกิจของข้าพระองค์ทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 1, 'ผู้ที่อาศัยอยู่ ณ ที่กําบังขององค์ผู้สูงสุดจะอยู่ในร่มเงาของผู้ทรงมหิทธิฤทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 2, 'ข้าพเจ้าจะกล่าวถึงพระเยโฮวาห์ว่า “พระองค์ทรงเป็นที่ลี้ภัยของข้าพระองค์และป้อมปราการของข้าพระองค์ พระเจ้าของข้าพระองค์ ผู้ที่ข้าพระองค์จะไว้วางใจ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 3, 'เพราะพระองค์จะทรงช่วยตัวท่านให้พ้นจากกับของพรานนกและจากโรคภัยอย่างร้ายแรงนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 4, 'พระองค์จะทรงปกท่านไว้ด้วยปีกของพระองค์ และท่านจะวางใจอยู่ใต้ปีกของพระองค์ ความจริงของพระองค์เป็นโล่และเป็นดั้งของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 5, 'ท่านจะไม่กลัวความสยดสยองในกลางคืน หรือกลัวลูกธนูที่ปลิวไปในกลางวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 6, 'หรือโรคภัยที่ไล่มาในความมืด หรือความพินาศที่เกิดความหายนะในเที่ยงวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 7, 'พันคนจะล้มอยู่ที่ข้างๆท่าน หมื่นคนที่มือขวาของท่าน แต่ภัยนั้นจะไม่มาใกล้ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 8, 'ท่านจะมองดูด้วยตาเท่านั้น และเห็นการตอบแทนแก่คนชั่ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 9, 'เพราะท่านได้กระทําให้พระเยโฮวาห์ผู้เป็นที่ลี้ภัยของข้าพเจ้าคือองค์ผู้สูงสุด เป็นที่อยู่ของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 10, 'ไม่มีการร้ายใดๆจะตกมาบนท่าน ไม่มีภัยมาใกล้ที่อาศัยของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 11, 'เพราะพระองค์จะรับสั่งเหล่าทูตสวรรค์ของพระองค์ในเรื่องท่าน ให้ระแวดระวังท่านในทางทั้งปวงของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 12, 'เขาทั้งหลายจะเอามือประคองชูท่านไว้ เกรงว่าเท้าของท่านจะกระแทกหิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 13, 'ท่านจะเหยียบสิงโตและงูพิษ ท่านจะย่ําสิงโตหนุ่มและมังกร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 14, 'เพราะเขาผูกพันกับเราด้วยความรัก เราจึงจะช่วยเขาให้พ้น เราจะตั้งเขาไว้ในที่สูง เพราะเขารู้จักนามของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 15, 'เขาจะร้องทูลเรา และเราจะตอบเขา เราจะอยู่กับเขาในยามลําบาก เราจะช่วยเขาให้พ้นและให้เกียรติเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 16, 'เราจะให้เขาอิ่มใจด้วยชีวิตยืนยาว และสําแดงความรอดของเราแก่เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 1, 'เพลงสดุดีหรือบทเพลงสําหรับวันสะบาโตเป็นการดีที่จะโมทนาพระคุณพระเยโฮวาห์ โอ ข้าแต่องค์ผู้สูงสุด ที่จะร้องเพลงสรรเสริญพระนามของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 2, 'ที่จะประกาศความเมตตาของพระองค์ในเวลาเช้า และความสัตย์สุจริตของพระองค์ในกลางคืน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 3, 'เป็นเสียงก้องไปด้วยพิณสิบสายและพิณใหญ่ และด้วยเสียงพิณเขาคู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 4, 'ข้าแต่พระเยโฮวาห์ เพราะพระองค์ทรงกระทําให้ข้าพระองค์ยินดีด้วยพระราชกิจของพระองค์ ข้าพระองค์จะฉลองชัยชนะเนื่องในพระหัตถกิจของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 5, 'โอ ข้าแต่พระเยโฮวาห์ พระราชกิจของพระองค์ใหญ่หลวงนัก พระดําริของพระองค์สุดลึกล้ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 6, 'คนเขลาจะทราบไม่ได้ คนโฉดเข้าใจเรื่องนี้ไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 7, 'ว่า ถึงแม้คนชั่วจะงอกขึ้นอย่างหญ้า และคนกระทําความชั่วช้าทั้งปวงเจริญขึ้น เขาทั้งหลายจะถูกทําลายเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 8, 'ข้าแต่พระเยโฮวาห์ แต่พระองค์ทรงอยู่บนที่สูงเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 9, 'โอ ข้าแต่พระเยโฮวาห์ เพราะดูเถิด ศัตรูของพระองค์ เพราะดูเถิด ศัตรูของพระองค์จะพินาศ คนกระทําความชั่วช้าทั้งปวงจะต้องกระจัดกระจายไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 10, 'แต่พระองค์ทรงเชิดชูเขาของข้าพระองค์อย่างกับเขาม้ายูนิคอน ข้าพระองค์จะถูกเจิมด้วยน้ํามันใหม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 11, 'นัยน์ตาของข้าพระองค์จะเห็นความปรารถนาของข้าพระองค์ต่อพวกศัตรูของข้าพระองค์นั้นสําเร็จ หูของข้าพระองค์จะได้ยินถึงความปรารถนาของข้าพระองค์ต่อคนชั่วที่ลุกขึ้นสู้ข้าพระองค์นั้นสําเร็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 12, 'คนชอบธรรมจะงอกขึ้นอย่างต้นอินทผลัม เขาจะเจริญขึ้นอย่างต้นสนสีดาร์ในเลบานอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 13, 'คนที่ถูกปลูกไว้ในพระนิเวศของพระเยโฮวาห์จะเจริญขึ้นในบริเวณของพระเจ้าของเราทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 14, 'เขาแก่แล้วก็ยังเกิดผล เขาจะมีน้ําเลี้ยงเต็มและเขียวสดอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 15, 'เพื่อแสดงว่าพระเยโฮวาห์นั้นเที่ยงธรรม พระองค์ทรงเป็นศิลาของข้าพระองค์ ในพระองค์ไม่มีความอธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 1, 'พระเยโฮวาห์ทรงครอบครอง พระองค์ทรงสวมความยิ่งใหญ่ พระเยโฮวาห์ทรงสวมกําลัง พระองค์ทรงเอาพระกําลังคาดพระองค์ โลกได้สถาปนาไว้แล้ว มันจะไม่หวั่นไหว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 2, 'พระที่นั่งของพระองค์ได้สถาปนาไว้แล้วตั้งแต่กาลดึกดําบรรพ์ พระองค์ดํารงอยู่ตั้งแต่นิรันดร์กาล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 3, 'โอ ข้าแต่พระเยโฮวาห์ กระแสน้ําได้คะนอง กระแสน้ําคะนองเสียง กระแสน้ําคะนองเสียงกึกก้อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 4, 'พระเยโฮวาห์บนที่สูงนั้นทรงมหิทธิฤทธิ์ยิ่งกว่าเสียงของน้ํามากหลาย ทรงมหิทธิฤทธิ์ยิ่งกว่าคลื่นทะเล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 5, 'บรรดาพระโอวาทของพระองค์แน่นอนทีเดียว โอ ข้าแต่พระเยโฮวาห์ ความบริสุทธิ์เหมาะกับพระนิเวศของพระองค์เป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 1, 'โอ ข้าแต่พระเยโฮวาห์พระเจ้า เจ้าแห่งการแก้แค้น โอ ข้าแต่พระเจ้า เจ้าแห่งการแก้แค้น ขอทรงสําแดงพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 2, 'ข้าแต่ผู้พิพากษาโลก ขอทรงลุกขึ้น ให้คนโอหังได้รับผลสนองอันสมกับเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 3, 'ข้าแต่พระเยโฮวาห์ คนชั่วจะนานเท่าใด คือคนชั่วจะเริงโลดอยู่นานเท่าใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 4, 'เขาจะพล่ามและพูดอย่างจองหองนานเท่าใด คนกระทําความชั่วช้าทั้งปวงจะโอ้อวดนานเท่าใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 5, 'โอ ข้าแต่พระเยโฮวาห์ เขาทุบประชาชนของพระองค์เป็นชิ้นๆ และทํามรดกของพระองค์ให้ทุกข์ยาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 6, 'เขาสังหารหญิงม่ายและคนต่างด้าว และกระทําฆาตกรรมลูกกําพร้าพ่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 7, 'และเขากล่าวว่า “พระเยโฮวาห์จะไม่แลเห็น พระเจ้าของยาโคบจะไม่หยั่งรู้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 8, 'คนเขลาที่สุดของประชาชนเอ๋ย จงเข้าใจเถิด คนโง่ทั้งหลาย เมื่อไรเจ้าจึงจะฉลาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 9, 'พระองค์ผู้ทรงปลูกหู พระองค์จะไม่ทรงได้ยินหรือ พระองค์ผู้ทรงปั้นตา พระองค์จะไม่ทรงเห็นหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 10, 'พระองค์ผู้ทรงตีสอนบรรดาประชาชาติ พระองค์จะไม่ทรงขนาบหรือ พระองค์ผู้ทรงสอนความรู้ให้มนุษย์ พระองค์จะไม่ทรงทราบหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 11, 'พระเยโฮวาห์ทรงทราบความคิดของมนุษย์ว่าเป็นเพียงแต่ไร้สาระ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 12, 'โอ ข้าแต่พระเยโฮวาห์ คนที่พระองค์ทรงตีสอนนั้นก็เป็นสุข คือคนที่พระองค์ทรงสอนด้วยพระราชบัญญัติของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 13, 'เพื่อจะให้เขาพักจากวันลําบากจนกว่าจะขุดบ่อไว้ให้คนชั่ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 14, 'เพราะพระเยโฮวาห์จะไม่ทอดทิ้งประชาชนของพระองค์ พระองค์จะไม่ทรงสละมรดกของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 15, 'เพราะความยุติธรรมจะกลับไปหาความชอบธรรม และบรรดาคนเที่ยงธรรมในใจจะติดตามไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 16, 'ผู้ใดจะลุกขึ้นต่อต้านคนกระทําความชั่วแทนข้าพเจ้า ผู้ใดจะยืนต่อสู้คนกระทําความชั่วช้าแทนข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 17, 'ถ้าพระเยโฮวาห์มิใช่ความอุปถัมภ์ของข้าพเจ้า วิญญาณของข้าพเจ้าคงอยู่ในความเงียบสงัด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 18, 'เมื่อข้าพเจ้าได้คิดว่า “เท้าของข้าพลาด” โอ ข้าแต่พระเยโฮวาห์ ความเมตตาของพระองค์ยึดข้าพระองค์ไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 19, 'เมื่อความกังวลในใจของข้าพระองค์มีมาก การเล้าโลมของพระองค์ก็หนุนจิตใจของข้าพระองค์ให้ชื่นบาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 20, 'บัลลังก์แห่งความชั่วช้าจะร่วมมิตรกับพระองค์ได้หรือ คือผู้ที่ใช้กฎหมายประกอบการชั่วร้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 21, 'เขาทั้งหลายผูกมิตรกันต่อสู้ชีวิตของคนชอบธรรม และปรับโทษโลหิตที่ไร้ความผิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 22, 'แต่พระเยโฮวาห์ทรงเป็นที่กําบังเข้มแข็งของข้าพเจ้าแล้ว และพระเจ้าของข้าพเจ้าเป็นศิลาที่ลี้ภัยของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 23, 'พระองค์จะทรงนําความชั่วช้าของเขาเองมาเหนือเขา และจะทรงตัดเขาเหล่านั้นออกเสียเพราะความชั่วร้ายของเขาเอง ใช่แล้ว พระเยโฮวาห์พระเจ้าของเราจะทรงตัดเขาออกเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 1, 'โอ มาเถิด ให้เราทั้งหลายร้องเพลงถวายพระเยโฮวาห์ ให้เราเปล่งเสียงอย่างชื่นบานถวายศิลาแห่งความรอดของพวกเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 2, 'ให้เราทั้งหลายเข้ามาอยู่เฉพาะเบื้องพระพักตร์พระองค์ด้วยโมทนา ให้เราเปล่งเสียงอย่างชื่นบานถวายพระองค์ด้วยบทเพลงสดุดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 3, 'เพราะพระเยโฮวาห์ทรงเป็นพระเจ้าใหญ่ยิ่ง และทรงเป็นกษัตริย์ใหญ่ยิ่งเหนือพระทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 4, 'ที่ลึกของแผ่นดินโลกอยู่ในพระหัตถ์ของพระองค์ ที่สูงของภูเขาเป็นของพระองค์ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 5, 'ทะเลเป็นของพระองค์ เพราะพระองค์ทรงสร้างมัน และพระหัตถ์ของพระองค์ทรงปั้นแผ่นดินแห้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 6, 'โอ มาเถิด ให้เรานมัสการและกราบลง ให้เราคุกเข่าลงต่อพระพักตร์พระเยโฮวาห์ผู้ทรงสร้างพวกเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 7, 'เพราะพระองค์ทรงเป็นพระเจ้าของเรา และเราเป็นประชากรแห่งทุ่งหญ้าของพระองค์ และเป็นแกะแห่งพระหัตถ์ของพระองค์ วันนี้ ถ้าท่านทั้งหลายจะฟังพระสุรเสียงของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 8, 'อย่าให้จิตใจของท่านแข็งกระด้างไปอย่างในครั้งกบฏนั้น เหมือนอย่างในวันที่ถูกทดลองในถิ่นทุรกันดาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 9, 'เมื่อบรรพบุรุษของท่านทดลองเราโดยเอาเราเข้าพิสูจน์ และได้เห็นกิจการของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 10, 'เราจึงเคืองคนชั่วอายุนั้นอยู่สี่สิบปีและว่า “เขาเป็นชนชาติที่มีใจมักหลงผิด เขาไม่รู้จักทางทั้งหลายของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 11, 'เพราะฉะนั้นเราจึงปฏิญาณด้วยความพิโรธของเราว่า “เขาจะไม่ได้เข้าสู่ที่สงบสุขของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 1, 'โอ จงร้องเพลงบทใหม่ถวายพระเยโฮวาห์ แผ่นดินโลกทั้งสิ้น จงร้องเพลงถวายพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 2, 'จงร้องเพลงถวายพระเยโฮวาห์ สรรเสริญพระนามของพระองค์ จงประกาศความรอดของพระองค์ทุกๆวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 3, 'จงเล่าถึงสง่าราศีของพระองค์ท่ามกลางบรรดาประชาชาติ ถึงการมหัศจรรย์ของพระองค์ท่ามกลางบรรดาชนชาติทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 4, 'เพราะพระเยโฮวาห์นั้นทรงยิ่งใหญ่และสมควรจะสรรเสริญอย่างยิ่ง พระองค์ทรงเป็นที่เกรงกลัวเหนือพระทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 5, 'เพราะพระทั้งปวงของชนชาติทั้งหลายเป็นรูปเคารพ แต่พระเยโฮวาห์ทรงสร้างฟ้าสวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 6, 'เกียรติและความสูงส่งมีอยู่ต่อเบื้องพระพักตร์พระองค์ กําลังและความงามอยู่ในสถานบริสุทธิ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 7, 'โอ ตระกูลของชนชาติทั้งหลายเอ๋ย จงถวายแด่พระเยโฮวาห์ จงถวายสง่าราศีและกําลังแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 8, 'จงถวายสง่าราศีซึ่งควรแก่พระนามของพระองค์แด่พระเยโฮวาห์ จงนําเครื่องบูชาและมายังบริเวณพระนิเวศของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 9, 'โอ จงนมัสการพระเยโฮวาห์ด้วยเครื่องประดับแห่งความบริสุทธิ์ ชาวโลกทั้งสิ้นเอ๋ย จงตัวสั่นต่อเบื้องพระพักตร์พระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 10, 'จงพูดท่ามกลางบรรดาประชาชาติว่าพระเยโฮวาห์ทรงครอบครอง เออ พิภพจะถูกสถาปนาเพื่อมันจะไม่หวั่นไหวเลย พระองค์จะทรงพิพากษาชนชาติทั้งหลายด้วยความชอบธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 11, 'จงให้ฟ้าสวรรค์เปรมปรีดิ์ และแผ่นดินโลกยินดี ให้ทะเลคํารน กับสิ่งทั้งปวงที่อยู่ในนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 12, 'ให้ทุ่งนาเริงโลด กับสิ่งทุกอย่างที่อยู่ในนั้น แล้วต้นไม้ทั้งสิ้นของป่าไม้จะปลาบปลื้มยินดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 13, 'เฉพาะพระพักตร์พระเยโฮวาห์ เพราะพระองค์เสด็จมา ด้วยพระองค์เสด็จมาพิพากษาโลก พระองค์จะทรงพิพากษาโลกด้วยความชอบธรรม และชนชาติทั้งหลายด้วยความจริงของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 1, 'พระเยโฮวาห์ทรงครอบครอง จงให้แผ่นดินโลกเปรมปรีดิ์ ให้เกาะเล็กๆมากมายนั้นยินดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 2, 'เมฆและความมืดทึบอยู่รอบพระองค์ ความชอบธรรมและความยุติธรรมเป็นรากฐานแห่งบัลลังก์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 3, 'ไฟลุกอยู่ข้างหน้าพระองค์และไหม้ปฏิปักษ์ของพระองค์ที่อยู่รอบข้างเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 4, 'ฟ้าแลบของพระองค์กระทําให้พิภพสว่าง แผ่นดินโลกเห็นแล้วสั่นสะท้าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 5, 'ภูเขาละลายอย่างขี้ผึ้งต่อเบื้องพระพักตร์พระเยโฮวาห์ ต่อเบื้องพระพักตร์องค์พระผู้เป็นเจ้าแห่งแผ่นดินโลกทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 6, 'ฟ้าสวรรค์ป่าวร้องความชอบธรรมของพระองค์ และชนชาติทั้งหลายเห็นสง่าราศีของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 7, 'ให้ผู้ปรนนิบัติรูปเคารพสลักทั้งสิ้นได้อาย คือผู้ที่อวดในรูปเคารพของเขา ให้พระทั้งสิ้นกราบลงต่อพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 8, 'ศิโยนได้ยินและยินดีและธิดาทั้งปวงของยูดาห์เปรมปรีดิ์ โอ ข้าแต่พระเยโฮวาห์ เพราะคําพิพากษาของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 9, 'ข้าแต่พระเยโฮวาห์ เพราะพระองค์สูงสุดเหนือแผ่นดินโลกทั้งสิ้น พระองค์ทรงสูงเด่นกว่าพระทั้งปวงอย่างยิ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 10, 'ท่านผู้ที่รักพระเยโฮวาห์ ก็จงเกลียดชังความชั่ว พระองค์ทรงอารักขาชีวิตวิสุทธิชนของพระองค์ พระองค์ทรงช่วยเขาให้พ้นจากมือของคนชั่ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 11, 'ความสว่างแจ้งขึ้นแก่คนชอบธรรม และความชื่นบานมีขึ้นแก่คนใจเที่ยงธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 12, 'ท่านผู้ชอบธรรมเอ๋ย จงเปรมปรีดิ์ในพระเยโฮวาห์ และถวายโมทนาเมื่อระลึกถึงความบริสุทธิ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 1, 'เพลงสดุดีโอ จงร้องเพลงบทใหม่ถวายพระเยโฮวาห์เพราะพระองค์ได้ทรงกระทําการมหัศจรรย์ พระหัตถ์ขวาและพระกรบริสุทธิ์ของพระองค์ได้นําความมีชัยมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 2, 'พระเยโฮวาห์ทรงกระทําให้ความรอดของพระองค์เป็นที่รู้จัก พระองค์ทรงสําแดงความชอบธรรมของพระองค์อย่างเปิดเผยท่ามกลางสายตาของบรรดาประชาชาติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 3, 'พระองค์ทรงระลึกถึงความเมตตาและความจริงของพระองค์ต่อวงศ์วานอิสราเอล ที่สุดปลายแผ่นดินโลกทั้งสิ้นได้เห็นความรอดของพระเจ้าของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 4, 'ชาวโลกทั้งสิ้นเอ๋ย จงเปล่งเสียงอย่างชื่นบานถวายแด่พระเยโฮวาห์ จงเปล่งเสียงด้วยความยินดีและร้องเพลงสรรเสริญ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 5, 'จงร้องเพลงสรรเสริญถวายพระเยโฮวาห์ด้วยพิณเขาคู่ ด้วยพิณเขาคู่ คลอด้วยเสียงเพลงสดุดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 6, 'ด้วยเสียงแตรและเสียงแตรทองเหลืองขนาดเล็กจงเปล่งเสียงอย่างชื่นบานต่อพระพักตร์พระเยโฮวาห์ คือพระมหากษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 7, 'ให้ทะเลคํารนกับสิ่งทั้งปวงที่อยู่ในทะเลนั้น พิภพและบรรดาผู้อาศัยอยู่ในนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 8, 'ให้กระแสน้ําตบมือของมัน ให้บรรดาเนินเขาปีติยินดีด้วยกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 9, 'เฉพาะเบื้องพระพักตร์พระเยโฮวาห์ เพราะพระองค์เสด็จมาพิพากษาโลก พระองค์จะทรงพิพากษาโลกด้วยความชอบธรรม และชนชาติทั้งหลายด้วยความเที่ยงตรง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 1, 'พระเยโฮวาห์ทรงครอบครอง ให้ชนชาติทั้งหลายตัวสั่น พระองค์ผู้ประทับระหว่างพวกเครูบ ให้แผ่นดินโลกหวั่นไหว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 2, 'พระเยโฮวาห์ใหญ่ยิ่งอยู่ในศิโยน พระองค์สูงเด่นอยู่เหนือประชาชาติทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 3, 'ให้เขาสรรเสริญพระนามอันยิ่งใหญ่และน่าคร้ามกลัวของพระองค์ เพราะพระนามนั้นบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 4, 'ฤทธานุภาพของกษัตริย์ทรงรักความยุติธรรม พระองค์ทรงสถาปนาความเที่ยงตรง พระองค์ทรงประกอบความยุติธรรมและความชอบธรรมขึ้นในยาโคบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 5, 'จงยอพระเกียรติพระเยโฮวาห์พระเจ้าของเรา และนมัสการที่แท่นรองพระบาทของพระองค์ เพราะพระองค์บริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 6, 'โมเสสและอาโรนอยู่ในพวกปุโรหิตของพระองค์ ซามูเอลอยู่ในพวกที่ทูลออกพระนามของพระองค์ด้วย พวกท่านร้องทูลพระเยโฮวาห์ และพระองค์ทรงตอบท่านเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 7, 'พระองค์ตรัสกับท่านที่ในเสาเมฆ ท่านทั้งปวงได้รักษาบรรดาพระโอวาทของพระองค์และกฎที่พระองค์ประทานแก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 8, 'โอ ข้าแต่พระเยโฮวาห์พระเจ้าของข้าพระองค์ทั้งหลาย พระองค์ทรงตอบท่านเหล่านั้น พระองค์ทรงเป็นพระเจ้าผู้ยกโทษท่านเหล่านั้น แต่ทรงเป็นผู้สนองการกระทําผิดของท่านเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 9, 'จงยอพระเกียรติพระเยโฮวาห์พระเจ้าของเรา และนมัสการที่ภูเขาอันบริสุทธิ์ของพระองค์ เพราะพระเยโฮวาห์พระเจ้าของเราบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 1, 'เพลงสดุดีเพื่อสรรเสริญพระเจ้าชาวโลกทั้งสิ้นเอ๋ย จงเปล่งเสียงอย่างชื่นบานถวายแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 2, 'จงปรนนิบัติพระเยโฮวาห์ด้วยความยินดี จงเข้ามาเฝ้าพระองค์ด้วยการร้องเพลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 3, 'จงรู้เถิดว่า พระเยโฮวาห์ทรงเป็นพระเจ้า คือพระองค์เองที่ทรงสร้างเราทั้งหลาย เราไม่ได้สร้างตัวเองขึ้น เราเป็นประชากรของพระองค์ เป็นแกะแห่งทุ่งหญ้าของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 4, 'จงเข้าประตูของพระองค์ด้วยการโมทนา และเข้าบริเวณพระนิเวศของพระองค์ด้วยการสรรเสริญ จงถวายโมทนาขอบพระคุณพระองค์ จงถวายสาธุการแด่พระนามของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 5, 'เพราะพระเยโฮวาห์ประเสริฐ ความเมตตาของพระองค์ดํารงเป็นนิตย์ และความจริงของพระองค์ดํารงอยู่ทุกชั่วอายุ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 1, 'เพลงสดุดีของดาวิดข้าพระองค์จะร้องเพลงเรื่องความเมตตาและความยุติธรรม โอ ข้าแต่พระเยโฮวาห์ ข้าพระองค์จะร้องเพลงถวายพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 2, 'ข้าพระองค์จะประพฤติอย่างเฉลียวฉลาดตามมรรคาที่ดีรอบคอบ โอ เมื่อไรพระองค์จะเสด็จมาหาข้าพระองค์ ข้าพระองค์จะดําเนินด้วยใจซื่อสัตย์ภายในเรือนของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 3, 'ข้าพระองค์จะไม่ตั้งสิ่งใดๆที่ชั่วช้าไว้ต่อหน้าต่อตาของข้าพระองค์ ข้าพระองค์เกลียดกิจการของผู้ที่ไม่ซื่อตรง กิจการนั้นจะไม่ติดอยู่กับข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 4, 'ข้าพระองค์จะอยู่ห่างไกลจากคนใจดื้อรั้น ข้าพระองค์จะไม่สนิทสนมกับคนชั่วร้ายเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 5, 'บุคคลใดก็ตามใส่ร้ายเพื่อนบ้านของเขาอย่างลับๆ ข้าพระองค์จะขจัดเขาออกเสีย คนที่มีสายตาที่หยิ่งยโสและใจที่จองหอง ข้าพระองค์จะไม่ยอมทนด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 6, 'นัยน์ตาข้าพระองค์จะมองหาคนที่ซื่อตรงในแผ่นดิน เพื่อเขาจะอาศัยอยู่กับข้าพระองค์ ผู้ใดดําเนินในทางที่ดีรอบคอบ ผู้นั้นจะปรนนิบัติข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 7, 'ผู้ที่ประพฤติหลอกลวงจะไม่ได้อาศัยอยู่ในเรือนของข้าพระองค์ คนใดที่พูดเท็จจะไม่ยั่งยืนอยู่ต่อสายตาของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 8, 'ข้าพระองค์จะทําลายคนชั่วทั้งสิ้นในแผ่นดินเสียแต่เนิ่นๆ เพื่อว่าข้าพระองค์จะได้ตัดบรรดาผู้กระทําชั่วออกเสียให้หมดจากนครของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 1, 'คําอธิษฐานของผู้ถูกข่มใจ เมื่อเขาอ่อนระอาใจ และระบายความนั้นต่อพระพักตร์พระเยโฮยาห์โอ ข้าแต่พระเยโฮวาห์ ขอทรงสดับคําอธิษฐานของข้าพระองค์ ขอเสียงร้องของข้าพระองค์มาถึงพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 2, 'ขออย่าทรงซ่อนพระพักตร์ของพระองค์จากข้าพระองค์ในวันทุกข์ใจของข้าพระองค์ ขอทรงเงี่ยพระกรรณสดับข้าพระองค์ ขอทรงตอบข้าพระองค์โดยเร็วในวันที่ข้าพระองค์ร้องทูลต่อพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 3, 'เพราะวันของข้าพระองค์สิ้นไปอย่างควัน และกระดูกของข้าพระองค์ไหม้อย่างเตาไฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 4, 'จิตใจของข้าพระองค์ถูกนาบและเหี่ยวไปเหมือนหญ้า ข้าพระองค์จึงลืมรับประทานอาหารของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 5, 'เหตุด้วยเสียงร้องครางของข้าพระองค์ กระดูกของข้าพระองค์เกาะติดเนื้อของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 6, 'ข้าพระองค์เป็นเหมือนนกกระทุงที่ในถิ่นทุรกันดาร ดุจนกเค้าแมวแห่งทะเลทราย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 7, 'ข้าพระองค์เฝ้าอยู่ ข้าพระองค์เหมือนนกกระจอกโดดเดี่ยวบนหลังคาเรือน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 8, 'ศัตรูของข้าพระองค์เย้ยหยันข้าพระองค์วันยังค่ํา ผู้ที่คลั่งใส่ข้าพระองค์ปฏิญาณตัวต่อต้านข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 9, 'เพราะข้าพระองค์กินขี้เถ้าต่างอาหาร และเจือน้ําตาเข้ากับเครื่องดื่ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 10, 'เหตุด้วยความพิโรธและความกริ้วของพระองค์ เพราะพระองค์ทรงชูข้าพระองค์ขึ้นและโยนข้าพระองค์ทิ้งไปเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 11, 'วันเวลาของข้าพระองค์เหมือนเงาเวลาเย็น ข้าพระองค์เหี่ยวไปเหมือนหญ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 12, 'โอ ข้าแต่พระเยโฮวาห์ แต่พระองค์จะทรงประทับอยู่เป็นนิตย์ การระลึกถึงพระองค์ดํารงอยู่ทุกชั่วอายุ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 13, 'พระองค์จะทรงลุกขึ้นเมตตาศิโยน เพราะถึงเวลาที่จะทรงพระกรุณาเธอ เออ เวลากําหนดมาถึงแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 14, 'เพราะผู้รับใช้ของพระองค์รักซากก้อนหินของเธอนัก และสงสารผงคลีของเธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 15, 'บรรดาประชาชาติจะกลัวพระนามของพระเยโฮวาห์ และบรรดากษัตริย์ของแผ่นดินโลกกลัวสง่าราศีของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 16, 'เพราะเมื่อพระเยโฮวาห์จะทรงสร้างศิโยนนั้น พระองค์จะทรงปรากฏด้วยสง่าราศีของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 17, 'พระองค์จะสนพระทัยในคําอธิษฐานของคนสิ้นเนื้อประดาตัว และจะไม่ทรงดูหมิ่นคําอธิษฐานของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 18, 'จงบันทึกเรื่องนี้ไว้ให้ชั่วอายุที่จะมีมา เพื่อประชาชนที่ยังจะทรงสร้างมานั้นจะได้สรรเสริญพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 19, 'เพราะพระองค์ทอดพระเนตรลงมาจากที่สูงอันบริสุทธิ์ของพระองค์ จากฟ้าสวรรค์พระเยโฮวาห์ทอดพระเนตรแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 20, 'เพื่อทรงสดับเสียงร้องครางของเชลย เพื่อทรงปล่อยคนที่ต้องถึงตายให้เป็นอิสระ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 21, 'เพื่อจะประกาศพระนามของพระเยโฮวาห์ในศิโยน และกล่าวสรรเสริญพระองค์ในเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 22, 'ขณะเมื่อชนชาติทั้งหลายรวบรวมกัน ทั้งบรรดาราชอาณาจักร เพื่อปรนนิบัติพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 23, 'พระองค์ทรงหักกําลังของข้าพเจ้ากลางทาง พระองค์ทรงกระทําให้วันเวลาของข้าพเจ้าสั้นเข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 24, 'ข้าพเจ้าว่า “โอ ข้าแต่พระเจ้าของข้าพระองค์ ขออย่าทรงนําข้าพระองค์ไปเสียในครึ่งกลางวันเวลาของข้าพระองค์ พระองค์ผู้ปีเดือนดํารงอยู่ตลอดทุกชั่วอายุ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 25, 'เมื่อเดิมพระองค์ทรงวางรากฐานของแผ่นดินโลก และฟ้าสวรรค์เป็นพระหัตถกิจของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 26, 'สิ่งเหล่านี้จะพินาศไป แต่พระองค์จะทรงดํารงอยู่ บรรดาสิ่งเหล่านี้จะเก่าไปเหมือนเครื่องนุ่งห่ม พระองค์จะทรงเปลี่ยนสิ่งเหล่านี้ไว้ดุจเสื้อคลุม และสิ่งเหล่านั้นก็จะเปลี่ยนแปลงไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 27, 'แต่พระองค์ยังทรงเป็นเหมือนเดิม และปีเดือนของพระองค์จะไม่สิ้นสุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 28, 'ลูกหลานของบรรดาผู้รับใช้ของพระองค์จะอยู่มั่นคง และเชื้อสายของเขาจะได้รับการสถาปนาต่อเบื้องพระพักตร์พระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 1, 'เพลงสดุดีของดาวิดโอ จิตใจของข้าเอ๋ย จงถวายสาธุการแด่พระเยโฮวาห์ และทั้งสิ้นที่อยู่ภายในข้า จงถวายสาธุการแด่พระนามบริสุทธิ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 2, 'โอ จิตใจของข้าเอ๋ย จงถวายสาธุการแด่พระเยโฮวาห์ และอย่าลืมพระราชกิจอันมีพระคุณทั้งสิ้นของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 3, 'ผู้ทรงอภัยความชั่วช้าทั้งสิ้นของท่าน ผู้ทรงรักษาโรคทั้งสิ้นของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 4, 'ผู้ทรงไถ่ชีวิตของท่านมาจากปากแดนผู้ตาย ผู้ทรงสวมความเมตตาและพระกรุณาเป็นมงกุฎให้ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 5, 'ผู้ทรงให้ปากท่านอิ่มด้วยของดี วัยหนุ่มของท่านจึงกลับคืนมาใหม่อย่างวัยนกอินทรี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 6, 'พระเยโฮวาห์ทรงประกอบความชอบธรรมและการยุติธรรมให้แก่บรรดาผู้ที่ถูกบีบบังคับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 7, 'พระองค์ทรงสําแดงวิธีการของพระองค์แก่โมเสส พระราชกิจของพระองค์แก่ประชาชนอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 8, 'พระเยโฮวาห์ทรงพระกรุณาและมีพระคุณ ทรงกริ้วช้าและอุดมด้วยความเมตตา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 9, 'พระองค์จะไม่ทรงปรักปรําเสมอหรือทรงกริ้วอยู่เป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 10, 'พระองค์มิได้ทรงกระทําต่อเราตามเรื่องบาปของเรา หรือทรงสนองตามความชั่วช้าของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 11, 'เพราะว่าฟ้าสวรรค์สูงเหนือแผ่นดินเท่าใด ความเมตตาของพระองค์ที่มีต่อบรรดาคนที่เกรงกลัวพระองค์ก็ใหญ่ยิ่งเท่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 12, 'ตะวันออกไกลจากตะวันตกเท่าใด พระองค์ทรงปลดการละเมิดของเราจากเราไปไกลเท่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 13, 'บิดาสงสารบุตรของตนฉันใด พระเยโฮวาห์ทรงสงสารบรรดาคนที่ยําเกรงพระองค์ฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 14, 'เพราะพระองค์ทรงทราบโครงร่างของเรา พระองค์ทรงระลึกว่าเราเป็นแต่ผงคลี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 15, 'ส่วนมนุษย์นั้น วันเวลาของเขาเหมือนหญ้า เขาเจริญขึ้นเหมือนดอกไม้ในทุ่งนา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 16, 'เพราะลมพัดผ่านมันไป มันก็สูญเสีย และสถานที่ของมันไม่รู้จักมันอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 17, 'แต่ความเมตตาของพระเยโฮวาห์นั้นดํารงอยู่ตั้งแต่นิรันดร์กาลถึงนิรันดร์กาลต่อผู้ที่ยําเกรงพระองค์ และความชอบธรรมของพระองค์ต่อหลานเหลน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 18, 'ต่อบรรดาผู้ที่รักษาพันธสัญญาของพระองค์ และระลึกอยู่ที่จะกระทําตามพระบัญญัติของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 19, 'พระเยโฮวาห์ทรงสถาปนาบัลลังก์ของพระองค์ไว้ในฟ้าสวรรค์ และราชอาณาจักรของพระองค์ครองทุกสิ่งอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 20, 'ข้าแต่ท่านทั้งหลาย ผู้เป็นทูตสวรรค์ของพระองค์ จงถวายสาธุการแด่พระเยโฮวาห์ ท่านผู้ทรงมหิทธิฤทธิ์ ผู้กระทําตามพระบัญชาของพระองค์ และเชื่อฟังเสียงพระวจนะของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 21, 'พลโยธาทั้งสิ้นของพระองค์ จงถวายสาธุการแด่พระเยโฮวาห์ คือบรรดาผู้รับใช้ที่กระทําตามพระทัยพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 22, 'พระราชกิจทั้งสิ้นของพระองค์ในทุกสถานที่ที่พระองค์ทรงครอบครองอยู่ จงถวายสาธุการแด่พระเยโฮวาห์ โอ จิตใจของข้าเอ๋ย จงถวายสาธุการแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 1, 'โอ จิตใจของข้าเอ๋ย จงถวายสาธุการแด่พระเยโฮวาห์ โอ ข้าแต่พระเยโฮวาห์พระเจ้าของข้าพระองค์ พระองค์ใหญ่ยิ่งนัก พระองค์ทรงเกียรติและความสูงส่งเป็นฉลองพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 2, 'ผู้ทรงคลุมพระองค์ด้วยแสงสว่างดุจดังฉลองพระองค์ ผู้ทรงขึงฟ้าสวรรค์ออกดังขึงม่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 3, 'ผู้ทรงวางคานของที่ประทับอันสูงของพระองค์ไว้ในน้ํา ผู้ทรงใช้เมฆเป็นราชรถ ผู้ทรงดําเนินไปบนปีกของลม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 4, 'ผู้ทรงบันดาลพวกทูตสวรรค์ของพระองค์ให้เป็นดุจวิญญาณ และทรงบันดาลผู้รับใช้ของพระองค์ให้เป็นดุจเปลวเพลิง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 5, 'ผู้ทรงวางรากฐานของแผ่นดินโลก เพื่อมิให้มันหวั่นไหวเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 6, 'พระองค์ทรงคลุมมันไว้ด้วยน้ําลึกอย่างกับเครื่องนุ่งห่ม น้ําอยู่เหนือภูเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 7, 'เมื่อพระองค์ทรงขนาบ น้ํานั้นก็หนีไป พอได้ยินเสียงฟ้าร้องของพระองค์ มันก็วิ่งไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 8, 'น้ํานั้นขึ้นไปยังภูเขา แล้วไหลลงไปยังหุบเขา ไปยังที่ซึ่งพระองค์ทรงกําหนดไว้ให้น้ํานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 9, 'พระองค์ทรงวางขอบเขตมิให้มันข้าม เพื่อมิให้มันคลุมแผ่นดินโลกอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 10, 'พระองค์ทรงกระทําให้น้ําพุพลุ่งขึ้นมาในหุบเขา น้ํานั้นก็ไหลไประหว่างเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 11, 'ให้บรรดาสัตว์ป่าได้ดื่มและให้ลาป่าดับความกระหายของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 12, 'ที่ริมน้ํานั้น นกในอากาศจึงได้มีที่อาศัย มันร้องอยู่ท่ามกลางกิ่งไม้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 13, 'พระองค์ทรงรดภูเขาจากที่ประทับอันสูงของพระองค์ แผ่นดินโลกก็อิ่มด้วยผลพระราชกิจของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 14, 'พระองค์ทรงให้หญ้างอกมาเพื่อสัตว์เลี้ยง และผักให้มนุษย์ได้ดูแล เพื่อเขาจะทําให้เกิดอาหารจากแผ่นดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 15, 'และน้ําองุ่นซึ่งให้ใจมนุษย์ยินดี น้ํามันเพื่อทําให้หน้าของเขาทอแสง และขนมปังซึ่งเสริมกําลังใจมนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 16, 'บรรดาต้นไม้ของพระเยโฮวาห์ได้อิ่มหนํา คือต้นสนสีดาร์แห่งเลบานอนซึ่งพระองค์ได้ทรงปลูกไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 17, 'นกสร้างรังของมันอยู่ในนั้น ส่วนนกกระสาดํานั้น ต้นสนสามใบเป็นบ้านของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 18, 'ภูเขาสูงนั้นเป็นที่ลี้ภัยของเลียงผา หินเป็นของตัวกระจงผา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 19, 'พระองค์ทรงจัดตั้งดวงจันทร์ให้กําหนดฤดู ดวงอาทิตย์รู้จักเวลาตกของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 20, 'พระองค์ทรงให้เกิดความมืดและเป็นกลางคืน เป็นที่ซึ่งบรรดาสัตว์ของป่าไม้คลานออกมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 21, 'สิงโตหนุ่มคํารามหาเหยื่อของมัน และแสวงหาอาหารของมันจากพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 22, 'เมื่อดวงอาทิตย์ขึ้นมันก็รวบรวมกันและไปนอนอยู่ในที่ของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 23, 'มนุษย์ก็ออกไปทํางานของเขา ไปทําภารกิจของเขาจนเวลาเย็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 24, 'โอ ข้าแต่พระเยโฮวาห์ พระราชกิจของพระองค์มากมายจริงๆ พระองค์ทรงสร้างการงานนั้นทั้งสิ้นด้วยพระปัญญา แผ่นดินโลกเต็มไปด้วยทรัพย์สมบัติของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 25, 'ทะเลอยู่ข้างโน้น ทั้งใหญ่และกว้าง ซึ่งในนั้นมีสิ่งเคลื่อนไหวนับไม่ถ้วน คือสัตว์ที่มีชีวิตทั้งเล็กและใหญ่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 26, 'กําปั่นแล่นไปโน่นแน่ะ และเลวีอาธานที่พระองค์สร้างไว้ให้เล่นนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 27, 'บรรดาสิ่งเหล่านี้แหงนหาพระองค์ เพื่อให้พระองค์ประทานอาหารแก่มันตามเวลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 28, 'เมื่อพระองค์ประทานให้ มันก็เก็บไป เมื่อพระองค์ทรงยื่นพระหัตถ์ออก มันก็อิ่มหนําด้วยของดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 29, 'เมื่อพระองค์ทรงซ่อนพระพักตร์เสีย มันทั้งหลายก็ลําบากใจ เมื่อพระองค์ทรงเอาลมหายใจมันไปเสีย มันก็ตาย และกลับเป็นผงคลี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 30, 'เมื่อพระองค์ทรงส่งวิญญาณของพระองค์ออกไป มันก็ถูกสร้างขึ้นมา และพระองค์ก็ทรงเปลี่ยนโฉมหน้าของพื้นดินเสียใหม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 31, 'สง่าราศีของพระเยโฮวาห์จะดํารงอยู่เป็นนิตย์ พระเยโฮวาห์จะทรงเปรมปรีดิ์ในบรรดาพระราชกิจของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 32, 'ผู้ทรงทอดพระเนตรโลก มันก็สั่นสะท้าน ผู้ทรงแตะต้องภูเขา มันก็มีควันขึ้นมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 33, 'ข้ามีชีวิตอยู่ตราบใด ข้าจะร้องเพลงถวายพระเยโฮวาห์ ขณะข้ายังเป็นอยู่ ข้าจะร้องเพลงสรรเสริญพระเจ้าของข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 34, 'การไตร่ตรองถึงพระองค์จะเป็นสิ่งที่พอพระทัย ข้าจะเปรมปรีดิ์ในพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 35, 'ขอคนบาปถูกผลาญเสียจากแผ่นดินโลก และขออย่าให้มีคนชั่วอีกเลย โอ จิตใจของข้าเอ๋ย จงถวายสาธุการแด่พระเยโฮวาห์ จงสรรเสริญพระเยโฮวาห์เถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 1, 'โอ จงโมทนาขอบพระคุณพระเยโฮวาห์ จงร้องทูลออกพระนามพระองค์ จงให้บรรดาพระราชกิจของพระองค์แจ้งแก่ชนชาติทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 2, 'จงร้องเพลงถวายพระองค์ ร้องเพลงสดุดีถวายพระองค์ จงเล่าถึงการมหัศจรรย์ทั้งสิ้นของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 3, 'จงอวดพระนามบริสุทธิ์ของพระองค์ ให้จิตใจของบรรดาผู้แสวงหาพระเยโฮวาห์เปรมปรีดิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 4, 'จงแสวงหาพระเยโฮวาห์ และพระกําลังของพระองค์ แสวงหาพระพักตร์ของพระองค์เรื่อยไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 5, 'จงระลึกถึงการอัศจรรย์ซึ่งพระองค์ทรงกระทํา การมหัศจรรย์และคําพิพากษาแห่งพระโอษฐ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 6, 'โอ เชื้อสายของอับราฮัม ผู้รับใช้ของพระองค์ เชื้อสายของยาโคบ ผู้เลือกสรรของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 7, 'พระองค์คือพระเยโฮวาห์พระเจ้าของเรา คําพิพากษาของพระองค์อยู่ทั่วไปในแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 8, 'พระองค์ทรงจดจําพันธสัญญาของพระองค์อยู่เป็นนิตย์ คือพระวจนะที่พระองค์ทรงบัญชาไว้ตลอดหนึ่งพันชั่วอายุ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 9, 'คือพันธสัญญาซึ่งพระองค์ทรงกระทําไว้กับอับราฮัม คําปฏิญาณซึ่งทรงกระทําไว้กับอิสอัค');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 10, 'ซึ่งพระองค์ทรงยืนยันอีกกับยาโคบให้เป็นพระราชบัญญัติ และแก่อิสราเอลให้เป็นพันธสัญญานิรันดร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 11, 'ว่า “เราจะให้แผ่นดินคานาอันแก่เจ้า เป็นส่วนมรดกของเจ้าทั้งหลาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 12, 'เมื่อเขายังมีคนจํานวนน้อย จํานวนน้อยจริง ยังเป็นแต่คนอาศัยอยู่ในนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 13, 'พเนจรไปจากประชาชาตินี้ถึงประชาชาตินั้น จากราชอาณาจักรนี้ถึงอีกชนชาติหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 14, 'พระองค์มิได้ทรงยอมให้ผู้ใดบีบบังคับเขา พระองค์ทรงขนาบกษัตริย์หลายองค์ด้วยเห็นแก่เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 15, 'ว่า “อย่าแตะต้องบรรดาผู้ที่เราเจิมไว้ อย่าทําอันตรายแก่ผู้พยากรณ์ทั้งหลายของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 16, 'เมื่อพระองค์ทรงเรียกการกันดารอาหารให้เกิดขึ้นที่แผ่นดิน และทรงทําลายอาหารที่บํารุงชีวิตเสียสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 17, 'พระองค์ทรงใช้ชายคนหนึ่งไปข้างหน้าเขา คือโยเซฟ ซึ่งถูกขายไปเป็นทาส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 18, 'เท้าของเขาเจ็บช้ําด้วยตรวน ตัวเขาเข้าอยู่ในปลอกเหล็ก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 19, 'จนกว่าสิ่งที่เขาบอกได้บังเกิดขึ้น พระวจนะของพระเยโฮวาห์ทดสอบเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 20, 'กษัตริย์ก็ทรงใช้ให้ไปปล่อยตัวเขา ผู้ปกครองของชนชาติทั้งหลายได้ปล่อยเขาเป็นอิสระ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 21, 'กษัตริย์ทรงตั้งเขาให้เป็นเจ้านายเหนือวังของพระองค์ เป็นผู้ปกครองกรรมสิทธิ์ทั้งปวงของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 22, 'ให้ผูกมัดเจ้านายของพระองค์ตามชอบใจ และสอนสติปัญญาแก่ผู้อาวุโสของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 23, 'แล้วอิสราเอลได้มาที่อียิปต์ ยาโคบได้อาศัยอยู่ในแผ่นดินของฮาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 24, 'และพระเจ้าทรงกระทําให้ประชาชนของพระองค์มีลูกดก และทรงกระทําให้เขาแข็งแรงกว่าคู่อริของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 25, 'พระองค์ทรงหันใจเขาเหล่านั้นให้เกลียดประชาชนของพระองค์ ให้ใช้กลอุบายแก่ผู้รับใช้ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 26, 'พระองค์ทรงใช้โมเสสผู้รับใช้ของพระองค์ และอาโรนผู้ที่พระองค์ทรงเลือกไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 27, 'เขาทั้งสองกระทําหมายสําคัญท่ามกลางเขาทั้งหลาย ทําการมหัศจรรย์ในแผ่นดินของฮาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 28, 'พระองค์ทรงใช้ความมืดมา กระทําให้แผ่นดินมืด เขาทั้งหลายมิได้กบฏต่อพระวจนะของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 29, 'พระองค์ทรงกระทําให้น้ํากลายเป็นเลือด และให้ปลาของเขาตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 30, 'กบแห่กันมาเป็นฝูงใหญ่ที่แผ่นดินของเขา แม้ห้องในของกษัตริย์ของเขาก็มี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 31, 'พระองค์ตรัส และฝูงเหลือบหลายชนิดก็มาและเหามีไปทั่วในแผ่นดินของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 32, 'พระองค์ประทานลูกเห็บแก่เขาแทนฝน และไฟไหม้ทั่วแผ่นดินของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 33, 'พระองค์ทรงนาบเถาองุ่น และต้นมะเดื่อของเขา และทรงฟาดต้นไม้ในประเทศของเขาให้หัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 34, 'พระองค์ตรัส และตั๊กแตนวัยบินก็มา และตั๊กแตนวัยคลานมานับไม่ถ้วน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 35, 'มากินพืชในแผ่นดินของเขาหมด และกินผลแห่งดินของเขาสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 36, 'พระองค์ทรงสังหารบรรดาลูกหัวปีในแผ่นดินของเขา คือผลแรกแห่งกําลังทั้งสิ้นของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 37, 'แล้วพระองค์ทรงนําอิสราเอลออกไปพร้อมกับเงินและทองคํา และไม่มีสักคนหนึ่งในตระกูลของพระองค์ที่อ่อนแอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 38, 'เมื่อเขาพรากจากไป อียิปต์ก็ยินดี เพราะความครั่นคร้ามต่ออิสราเอลได้ตกอยู่บนเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 39, 'พระองค์ทรงกางเมฆเป็นเครื่องกําบัง และไฟให้ความสว่างเวลากลางคืน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 40, 'ประชาชนร้องขอ และพระองค์ทรงนํานกคุ่มมา และให้เขาอิ่มใจด้วยอาหารจากฟ้าสวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 41, 'พระองค์ทรงเปิดหิน และน้ําก็ไหลออกมา มันไหลพุ่งไปเป็นแม่น้ําในที่แห้งแล้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 42, 'เพราะพระองค์ทรงระลึกถึงพระสัญญาบริสุทธิ์ของพระองค์ และอับราฮัมผู้รับใช้ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 43, 'พระองค์จึงทรงนําประชาชนของพระองค์ออกมาด้วยความชื่นบาน ทรงนําผู้ที่เลือกสรรไว้นั้นด้วยความเบิกบานใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 44, 'และพระองค์ประทานแผ่นดินของบรรดาประชาชาติให้แก่เขา และเขาได้ผลงานของชาติทั้งหลายเป็นกรรมสิทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 45, 'เพื่อเขาจะปฏิบัติกฎเกณฑ์ของพระองค์ และรักษาพระราชบัญญัติของพระองค์ จงสรรเสริญพระเยโฮวาห์เถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 1, 'จงสรรเสริญพระเยโฮวาห์เถิด โอ จงโมทนาขอบพระคุณพระเยโฮวาห์ เพราะพระองค์ประเสริฐ เพราะความเมตตาของพระองค์ดํารงเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 2, 'ผู้ใดจะพรรณนาถึงพระราชกิจอันทรงมหิทธิฤทธิ์ของพระเยโฮวาห์ ผู้ใดจะแสดงถึงพระเกียรติของพระองค์อย่างครบถ้วนได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 3, 'บรรดาผู้ที่รักษาความยุติธรรมก็เป็นสุข และผู้ที่กระทําความชอบธรรมตลอดเวลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 4, 'โอ ข้าแต่พระเยโฮวาห์ ขอทรงระลึกถึงข้าพระองค์ด้วยความโปรดปรานซึ่งพระองค์ทรงมีต่อประชาชนของพระองค์ โอ ขอทรงประทานความรอดของพระองค์ให้แก่ข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 5, 'เพื่อข้าพระองค์จะเห็นความเจริญรุ่งเรืองของบรรดาผู้เลือกสรรของพระองค์ เพื่อข้าพระองค์จะเปรมปรีดิ์ในความยินดีแห่งประชาชาติของพระองค์ เพื่อข้าพระองค์จะอวดได้ร่วมกับมรดกของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 6, 'ทั้งข้าพระองค์ทั้งหลายและบรรพบุรุษของข้าพระองค์ได้กระทําบาปแล้ว ข้าพระองค์ทั้งหลายได้กระทําความชั่วช้า ข้าพระองค์ทั้งหลายได้กระทําอย่างชั่วร้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 7, 'บรรพบุรุษของข้าพระองค์ทั้งหลายเมื่อท่านอยู่ในอียิปต์ท่านมิได้เข้าใจการมหัศจรรย์ของพระองค์ ท่านมิได้ระลึกถึงความเมตตาอันอุดมของพระองค์ แต่ได้กบฏต่อพระองค์ที่ทะเล ที่ทะเลแดง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 8, 'ถึงกระนั้นพระองค์ยังทรงช่วยท่านให้รอดเพราะเห็นแก่พระนามของพระองค์ เพื่อพระองค์จะให้ทราบถึงฤทธานุภาพอันใหญ่ยิ่งของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 9, 'พระองค์ทรงขนาบทะเลแดง มันก็แห้งไป และพระองค์ทรงนําท่านข้ามที่ลึกอย่างกับเดินข้ามถิ่นทุรกันดาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 10, 'พระองค์จึงทรงช่วยท่านให้พ้นมือของผู้ที่เกลียดชังท่าน และไถ่ท่านจากเงื้อมมือของศัตรู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 11, 'และน้ําท่วมปฏิปักษ์ของท่าน เขาไม่เหลือสักคนเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 12, 'แล้วท่านเชื่อพระวจนะของพระองค์ ท่านร้องเพลงสรรเสริญพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 13, 'แต่ไม่ช้าท่านก็ลืมพระราชกิจของพระองค์เสีย ท่านไม่คอยพระดํารัสปรึกษาของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 14, 'แต่ในถิ่นทุรกันดารนั้นท่านมีความอยากอย่างรุนแรง และได้ทดลองพระเจ้าในทะเลทราย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 15, 'พระองค์ทรงประทานสิ่งที่ท่านขอ แต่ทรงใช้โรคผอมแห้งมาท่ามกลางจิตใจท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 16, 'เมื่อคนในค่ายริษยาโมเสสและอาโรนวิสุทธิชนของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 17, 'พื้นแผ่นดินอ้าปากกลืนดาธานและทับคณะอาบีรัมเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 18, 'ไฟระเบิดในคณะของท่านและเปลวเพลิงผลาญคนชั่วเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 19, 'ท่านได้สร้างลูกวัวในโฮเรบและนมัสการรูปเคารพหล่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 20, 'ท่านจึงเอาสง่าราศีของพระเจ้าแลกกับรูปของวัวที่กินหญ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 21, 'ท่านลืมพระเจ้า พระผู้ช่วยให้รอดของท่าน ผู้ได้ทรงกระทําพระราชกิจใหญ่โตในอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 22, 'ทําการมหัศจรรย์ในแผ่นดินของฮามและสิ่งน่าคร้ามกลัวที่ทะเลแดง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 23, 'เพราะฉะนั้นพระองค์ตรัสว่าจะทําลายท่านเสีย ดีว่าโมเสสผู้เลือกสรรของพระองค์ได้มายืนเฝ้าทัดทานพระองค์ เพื่อหันพระพิโรธของพระองค์เสียจากการทําลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 24, 'แล้วท่านก็ดูถูกแผ่นดินอันร่มรื่นนั้น ท่านไม่เชื่อพระวจนะของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 25, 'ท่านบ่นอยู่ในเต็นท์ของท่าน และไม่ฟังพระสุรเสียงของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 26, 'เพราะฉะนั้นพระองค์ทรงยกพระหัตถ์ของพระองค์ปฏิญาณต่อท่าน ว่าจะทําให้ท่านล้มตายในถิ่นทุรกันดาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 27, 'และจะกระจายเชื้อสายของท่านไปท่ามกลางประชาชาติ หว่านเขาไปทั่วประเทศทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 28, 'แล้วท่านก็ไปติดพันอยู่กับพระบาอัลเปโอร์ และรับประทานเครื่องสัตวบูชาที่บูชาพระตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 29, 'ท่านยั่วเย้าพระองค์ให้ทรงกริ้วด้วยการกระทําของท่าน และโรคระบาดเกิดขึ้นท่ามกลางท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 30, 'แล้วฟีเนหัสได้ยืนขึ้นจัดการลงโทษและโรคระบาดนั้นก็หยุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 31, 'ที่เขาทํานั้นพระองค์ทรงนับว่าเป็นความชอบธรรมแก่เขาตลอดทุกชั่วอายุสืบต่อไปเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 32, 'ท่านทําให้พระองค์กริ้วที่น้ําแห่งการโต้เถียง เพราะเรื่องของท่านนี้ โมเสสก็พลอยเสียหายด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 33, 'เพราะท่านทําให้จิตใจโมเสสขมขื่น ดังนั้นริมฝีปากของเขาจึงพูดถ้อยคําหุนหัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 34, 'ท่านมิได้ทําลายชนชาติทั้งหลายตามที่พระเยโฮวาห์ทรงบัญชาท่านไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 35, 'แต่ท่านได้ปะปนกับประชาชาติเหล่านั้น และหัดทําอย่างที่เขาทํากัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 36, 'ท่านปรนนิบัติรูปเคารพของเขาซึ่งกลายเป็นบ่วงสําหรับท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 37, 'ท่านฆ่าบุตรชายและบุตรสาวของท่านถวายเป็นเครื่องสักการบูชาแก่ปีศาจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 38, 'ท่านเทโลหิตผู้ไร้ผิดออกมาคือโลหิตบุตรชายบุตรสาวของท่าน ผู้ซึ่งท่านได้ฆ่าเป็นเครื่องสักการบูชาแก่รูปเคารพแห่งคานาอัน แผ่นดินก็มลทินไปด้วยโลหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 39, 'ท่านจึงเป็นคนไม่สะอาดด้วยการกระทําของท่าน และประพฤติเยี่ยงโสเภณีในการกระทําของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 40, 'แล้วความกริ้วของพระเยโฮวาห์ก็พลุ่งขึ้นต่อประชาชนของพระองค์ และพระองค์ทรงรังเกียจมรดกของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 41, 'พระองค์ทรงมอบท่านไว้ในมือประชาชาติต่างๆ บรรดาผู้ที่เกลียดท่านจึงปกครองเหนือท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 42, 'ศัตรูของท่านได้บีบบังคับท่านและท่านตกไปอยู่ใต้อํานาจของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 43, 'พระองค์ทรงช่วยท่านให้พ้นหลายครั้ง แต่ท่านมักกบฏในจุดประสงค์ของท่าน และถูกเหยียดลงด้วยความชั่วช้าของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 44, 'ถึงอย่างไร เมื่อพระองค์สดับเสียงร้องทูลของท่าน พระองค์ทรงสนพระทัยในความทุกข์ใจของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 45, 'เพื่อเห็นแก่ท่าน พระองค์ทรงระลึกถึงพันธสัญญาของพระองค์ และกลับทรงกรุณาตามความเมตตาอันอุดมของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 46, 'พระองค์ทรงให้ท่านได้รับความสงสารจากบรรดาผู้ที่ได้ยึดท่านไปเป็นเชลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 47, 'โอ ข้าแต่พระเยโฮวาห์พระเจ้าของข้าพระองค์ทั้งหลาย ขอทรงช่วยข้าพระองค์ทั้งหลายให้รอด และขอทรงรวบรวมข้าพระองค์ทั้งหลายจากท่ามกลางประชาชาติต่างๆ เพื่อข้าพระองค์ทั้งหลายจะโมทนาขอบพระคุณพระนามบริสุทธิ์ของพระองค์ และเริงโลดในการสรรเสริญพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 48, 'จงถวายสาธุการแด่พระเยโฮวาห์พระเจ้าของอิสราเอลแต่นิรันดร์กาลจนถึงนิรันดร์กาล และขอประชาชนทั้งปวงกล่าวว่า “เอเมน” จงสรรเสริญพระเยโฮวาห์เถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 1, 'โอ จงโมทนาขอบพระคุณพระเยโฮวาห์ เพราะพระองค์ประเสริฐ เพราะความเมตตาของพระองค์ดํารงเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 2, 'ให้ผู้ที่พระเยโฮวาห์ทรงไถ่ไว้แล้วกล่าวดังนั้นเถิด คือผู้ที่พระองค์ทรงไถ่ไว้จากมือของปรปักษ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 3, 'และรวบรวมเข้ามาจากแผ่นดินทั้งหลาย จากตะวันออก และจากตะวันตก จากเหนือและจากใต้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 4, 'เขาก็พเนจรอยู่ในป่าในที่แห้งแล้ง หาไม่พบทางที่จะเข้านครซึ่งพอจะอาศัยได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 5, 'หิวโหยและกระหาย จิตใจของเขาก็อ่อนระอาไปในตัวเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 6, 'แล้วในความยากลําบากของเขาเมื่อเขาร้องทูลพระเยโฮวาห์ พระองค์ทรงช่วยเขาให้พ้นจากความทุกข์ใจของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 7, 'พระองค์ทรงนําเขาไปในทางตรงจนเขามาถึงนครซึ่งพอจะอาศัยได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 8, 'โอ ให้เขาขอบพระคุณพระเยโฮวาห์เพราะความดีของพระองค์ เพราะการมหัศจรรย์ของพระองค์ที่มีต่อบุตรทั้งหลายของมนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 9, 'เพราะผู้ที่กระหาย พระองค์ทรงให้เขาอิ่ม และผู้ที่หิว พระองค์ทรงให้เขาหนําใจด้วยของดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 10, 'ผู้ที่นั่งอยู่ในความมืดและเงามัจจุราช ถูกขังอยู่ด้วยความทุกข์ยากและติดตรวน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 11, 'เพราะเขากบฏต่อพระวจนะของพระเจ้า และหยามคําปรึกษาขององค์ผู้สูงสุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 12, 'พระองค์จึงทรงกระทําจิตใจของเขาทั้งหลายให้ถ่อมลงด้วยงานหนัก เขาล้มลงและไม่มีใครช่วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 13, 'แล้วในความยากลําบากของเขาเมื่อเขาร้องทูลพระเยโฮวาห์ พระองค์ทรงให้เขารอดจากความทุกข์ใจของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 14, 'พระองค์ทรงนําเขาออกมาจากความมืดและเงามัจจุราช และทรงระเบิดพันธนะของเขาให้ขาดสะบั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 15, 'โอ ให้เขาขอบพระคุณพระเยโฮวาห์เพราะความดีของพระองค์ เพราะการมหัศจรรย์ของพระองค์ที่มีต่อบุตรทั้งหลายของมนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 16, 'เพราะพระองค์ทรงพังประตูทองเหลืองและทรงตัดซี่ลูกกรงเหล็กเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 17, 'เขาเป็นคนโง่เพราะการละเมิดของเขา และเพราะความชั่วช้าของเขา เขาต้องทนความทุกข์ยาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 18, 'จิตใจเขารังเกียจอาหารทุกชนิดและเข้าไปใกล้ประตูความตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 19, 'แล้วในความยากลําบากของเขาเมื่อเขาร้องทูลพระเยโฮวาห์ พระองค์ทรงให้เขารอดจากความทุกข์ใจของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 20, 'พระองค์ทรงใช้พระวจนะของพระองค์ไปรักษาเขา และทรงช่วยเขาให้พ้นจากสิ่งต่างๆที่จะทําลายเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 21, 'โอ ให้เขาขอบพระคุณพระเยโฮวาห์เพราะความดีของพระองค์ เพราะการมหัศจรรย์ของพระองค์ที่มีอยู่ต่อบุตรทั้งหลายของมนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 22, 'และให้เขาถวายเครื่องสักการบูชาโมทนาพระคุณ และเล่าพระราชกิจของพระองค์ด้วยความชื่นบาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 23, 'ผู้ที่ลงเรือไปในทะเล ทําอาชีพอยู่บนน้ํากว้างใหญ่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 24, 'เขาได้เห็นพระราชกิจของพระเยโฮวาห์ และการมหัศจรรย์ของพระองค์ในที่น้ําลึก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 25, 'เพราะพระองค์ทรงบัญชา และทรงให้เกิดลมพายุซึ่งให้คลื่นทะเลกําเริบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 26, 'คนเหล่านั้นถูกซัดขึ้นไปสู่ท้องฟ้าและลงไปสู่ที่ลึก ใจของเขาละลายไปเพราะเหตุความยากลําบาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 27, 'เขาถลาและโซเซไปอย่างคนเมาและสิ้นปัญญาลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 28, 'แล้วในความยากลําบากของเขาเมื่อเขาร้องทูลพระเยโฮวาห์ พระองค์ทรงช่วยนําเขาออกจากความทุกข์ใจของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 29, 'พระองค์ทรงกระทําให้พายุสงบลงและคลื่นทะเลก็นิ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 30, 'แล้วเขาก็ยินดีเพราะเขามีความเงียบ และพระองค์ทรงนําเขามายังท่าที่เขาปรารถนา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 31, 'โอ ให้เขาขอบพระคุณพระเยโฮวาห์เพราะความดีของพระองค์ เพราะการมหัศจรรย์ของพระองค์ที่มีต่อบุตรทั้งหลายของมนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 32, 'ให้เขายอพระเกียรติพระองค์ในชุมนุมประชาชน และสรรเสริญพระองค์ในที่ประชุมของผู้อาวุโส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 33, 'พระองค์ทรงเปลี่ยนแม่น้ําให้เป็นถิ่นทุรกันดาร น้ําพุให้เป็นดินแห้งผาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 34, 'แผ่นดินที่มีผลดกให้เป็นที่แห้งแล้ง เพราะเหตุความโหดร้ายของชาวเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 35, 'พระองค์ทรงเปลี่ยนถิ่นทุรกันดารให้เป็นสระน้ํา แผ่นดินแห้งผากให้เป็นน้ําพุ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 36, 'และพระองค์ทรงให้คนหิวโหยอาศัยที่นั่น เพื่อเขาจะสถาปนานครซึ่งพอจะอาศัยได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 37, 'เขาหว่านนา และปลูกสวนองุ่นและได้ผลดกมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 38, 'โดยพระพรของพระองค์เขาทั้งหลายทวีผลมากยิ่ง และพระองค์มิได้ทรงให้วัวของเขาลดจํานวนลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 39, 'เมื่อเขาถูกทําให้น้อยลงและถูกเหยียดให้ต่ําโดยการบีบบังคับกับความยากลําบากและความโศกเศร้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 40, 'พระองค์ทรงเทความดูหมิ่นลงบนเจ้านาย ทรงกระทําให้เขาพเนจรไปในถิ่นทุรกันดารที่ไม่มีหนทาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 41, 'แต่พระองค์ทรงยกคนขัดสนขึ้นจากความทุกข์ยาก และกระทําให้ครอบครัวของเขามากอย่างฝูงแพะแกะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 42, 'คนชอบธรรมจะเห็นและยินดี และความชั่วช้าทั้งปวงก็จะปิดปากของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 43, 'ผู้ใดฉลาดและจะรักษาสิ่งเหล่านี้ ก็จะเข้าใจถึงความเมตตาของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 1, 'บทเพลงหรือเพลงสดุดีของดาวิดโอ ข้าแต่พระเจ้า จิตใจของข้าพระองค์มั่นคง ข้าพระองค์จะร้องเพลงและร้องเพลงสรรเสริญด้วยจิตใจของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 2, 'พิณใหญ่และพิณเขาคู่เอ๋ย จงตื่นเถิด ข้าพเจ้าจะปลุกอรุณ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 3, 'โอ ข้าแต่พระเยโฮวาห์ ข้าพระองค์จะสรรเสริญพระองค์ท่ามกลางประชาชาติ ข้าพระองค์จะร้องเพลงสรรเสริญพระองค์ท่ามกลางชนชาติทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 4, 'เพราะความเมตตาของพระองค์ใหญ่ยิ่งเหนือฟ้าสวรรค์ ความจริงของพระองค์สูงถึงเมฆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 5, 'โอ ข้าแต่พระเจ้า ขอทรงเป็นที่เชิดชูเหนือฟ้าสวรรค์ ขอสง่าราศีของพระองค์อยู่เหนือทั่วแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 6, 'ขอทรงช่วยให้รอดโดยพระหัตถ์ขวาของพระองค์และทรงตอบข้าพระองค์ เพื่อว่าผู้ที่พระองค์ทรงรักจะได้รับการช่วยให้พ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 7, 'พระเจ้าได้ตรัสด้วยความบริสุทธิ์ของพระองค์ว่า “เราจะปีติยินดี เราจะแบ่งเมืองเชเคม และแบ่งหุบเขาเมืองสุคคทออก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 8, 'กิเลอาดเป็นของเรา มนัสเสห์เป็นของเรา เอฟราอิมเป็นที่กันศีรษะของเรา ยูดาห์เป็นผู้ตั้งพระราชบัญญัติของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 9, 'โมอับเป็นอ่างล้างชําระของเรา เราเหวี่ยงรองเท้าของเราลงบนเอโดม เราโห่ร้องด้วยความมีชัยเหนือฟีลิสเตีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 10, 'ผู้ใดจะนําข้าพเจ้าเข้าไปในนครที่มีป้อม ผู้ใดจะนําข้าพเจ้าไปยังเอโดม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 11, 'โอ ข้าแต่พระเจ้า พระองค์มิได้ทรงทอดทิ้งข้าพระองค์ทั้งหลายแล้วหรือ โอ ข้าแต่พระเจ้า พระองค์ไม่ทรงออกไปกับกองทัพของข้าพระองค์ทั้งหลายแล้วล่ะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 12, 'ขอประทานความช่วยเหลือเพื่อต่อต้านความยุ่งยากต่างๆ เพราะความช่วยเหลือของมนุษย์ก็ไร้ผล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 13, 'โดยพระเจ้าเอง ข้าพเจ้าทั้งหลายจะปฏิบัติอย่างเข้มแข็ง พระองค์เองจะทรงเป็นผู้เหยียบคู่อริของข้าพเจ้าทั้งหลายลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 1, 'ถึงหัวหน้านักร้อง เพลงสดุดีของดาวิดโอ ข้าแต่พระเจ้า ผู้ซึ่งข้าพระองค์สรรเสริญ ขออย่าทรงนิ่งเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 2, 'เพราะปากของคนชั่วและปากของคนหลอกลวงอ้าใส่ข้าพระองค์อยู่แล้ว พวกเขาได้พูดปรักปรําข้าพระองค์ด้วยลิ้นมุสา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 3, 'เขาทั้งหลายล้อมข้าพระองค์ไว้ด้วยถ้อยคําเกลียดชัง และโจมตีข้าพระองค์อย่างไร้เหตุ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 4, 'เขาเป็นพวกปฏิปักษ์ต่อข้าพระองค์แทนความรักของข้าพระองค์ ส่วนข้าพระองค์ได้อธิษฐานเท่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 5, 'เขาตอบแทนข้าพระองค์ด้วยความชั่วแทนความดี และความเกลียดชังแทนความรักของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 6, 'ขอทรงตั้งคนชั่วให้อยู่เหนือเขาและให้ซาตานยืนอยู่ที่มือขวาของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 7, 'เมื่อพิจารณาคดี ก็ให้เขาปรากฏว่าเป็นผู้กระทําผิด และให้คําอธิษฐานของเขากลายเป็นความบาป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 8, 'ขอให้วันเวลาของเขาน้อย ขอให้อีกผู้หนึ่งมายึดตําแหน่งของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 9, 'ขอให้ลูกของเขากําพร้าพ่อ และภรรยาของเขาเป็นม่าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 10, 'ขอให้ลูกของเขาต้องเร่ร่อนขอทานเรื่อยไป ขอให้เขาหาอาหารจากที่รกร้างว่างเปล่าของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 11, 'ขอให้เจ้าหนี้มายึดของทั้งสิ้นที่เขามีอยู่ ขอคนต่างถิ่นมาปล้นผลงานของเขาไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 12, 'ขออย่าให้ผู้ใดเอ็นดูเขา อย่าให้ผู้ใดสงสารลูกกําพร้าพ่อของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 13, 'ขอให้ทายาทของเขาถูกตัดออก และในคนชั่วอายุต่อมาก็ขอให้ชื่อของเขาถูกลบออกเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 14, 'ขอให้ความชั่วช้าของบรรพบุรุษของเขายังเป็นที่จําได้อยู่ต่อพระพักตร์พระเยโฮวาห์ อย่าให้บาปของมารดาเขาถูกลบออกไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 15, 'ขอให้บาปเหล่านั้นอยู่ต่อเบื้องพระพักตร์พระเยโฮวาห์เสมอไป เพื่อพระองค์จะทรงตัดการระลึกถึงเขาเหล่านั้นเสียจากแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 16, 'เพราะเขาไม่จดจําที่จะแสดงความเอ็นดู แต่ข่มเหงคนจนและคนขัดสน เพื่อจะฆ่าคนที่เศร้าใจเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 17, 'เขารักที่จะแช่ง ขอให้คําแช่งตกบนเขา เขาไม่ชอบการให้พร ขอพรจงห่างไกลจากเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 18, 'เขาเอาการแช่งห่มต่างเสื้อผ้าของเขา ขอให้ซึมเข้าไปในกายของเขาอย่างน้ํา ขอให้ซึมเข้าไปในกระดูกของเขาอย่างน้ํามัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 19, 'ให้เหมือนเครื่องแต่งกายที่คลุมเขาอยู่ เหมือนเข็มขัดที่คาดเขาไว้เสมอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 20, 'ทั้งนี้ขอให้เป็นบําเหน็จจากพระเยโฮวาห์แก่พวกปฏิปักษ์ของข้าพระองค์ แก่ผู้ที่กล่าวร้ายต่อชีวิตของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 21, 'โอ ข้าแต่พระเจ้าคือองค์พระผู้เป็นเจ้า ขอทรงกระทําเพื่อข้าพระองค์โดยเห็นแก่พระนามของพระองค์ เพราะว่าความเมตตาของพระองค์นั้นประเสริฐ ขอทรงช่วยข้าพระองค์ให้พ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 22, 'เพราะข้าพระองค์ยากจนและขัดสน และจิตใจของข้าพระองค์ก็บาดเจ็บอยู่ภายใน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 23, 'ข้าพระองค์สิ้นสุดไปแล้วอย่างเงาตอนเย็น ข้าพระองค์ถูกสลัดออกเหมือนตั๊กแตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 24, 'เข่าของข้าพระองค์ก็อ่อนเปลี้ยเพราะการอดอาหาร ร่างกายของข้าพระองค์ก็ซูบผอมไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 25, 'ข้าพระองค์กลายเป็นที่ตําหนิติเตียนของเขา เมื่อเขามองดูข้าพระองค์ เขาก็สั่นศีรษะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 26, 'โอ ข้าแต่พระเยโฮวาห์พระเจ้าของข้าพระองค์ ขอทรงช่วยข้าพระองค์ โอ ขอทรงช่วยข้าพระองค์ให้รอดตามความเมตตาของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 27, 'เพื่อเขาจะทราบว่านี่เป็นฝีพระหัตถ์ของพระองค์ ข้าแต่พระเยโฮวาห์ พระองค์ได้ทรงกระทําการนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 28, 'ให้เขาแช่งไป แต่ขอพระองค์ทรงอํานวยพระพร เมื่อเขาลุกขึ้น ขอให้เขาได้อาย แต่ขอให้ผู้รับใช้ของพระองค์ยินดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 29, 'ขอให้พวกปฏิปักษ์ของข้าพระองค์ห่มความอัปยศ ขอให้ความอับอายสวมกายเขาอย่างเสื้อคลุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 30, 'ด้วยปากของข้าพเจ้า ข้าพเจ้าจะสรรเสริญพระเยโฮวาห์เป็นอย่างมาก ข้าพเจ้าจะสรรเสริญพระองค์ท่ามกลางคนมากหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 31, 'เพราะพระองค์จะทรงประทับขวามือของคนขัดสน เพื่อทรงช่วยเขาให้พ้นจากคนที่ปรับโทษจิตใจเขานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 1, 'เพลงสดุดีของดาวิดพระเยโฮวาห์ตรัสกับองค์พระผู้เป็นเจ้าของข้าพเจ้าว่า “จงนั่งที่ขวามือของเรา จนกว่าเราจะกระทําให้ศัตรูของเจ้าเป็นแท่นรองเท้าของเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 2, 'พระเยโฮวาห์จะทรงใช้คทาทรงฤทธิ์ของพระองค์ท่านไปจากศิโยน จงครอบครองท่ามกลางศัตรูของพระองค์ท่านเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 3, 'ชนชาติของพระองค์ท่านจะสมัครถวายตัวของเขาด้วยความเต็มใจ ในวันแห่งฤทธิ์อํานาจของพระองค์ท่าน ด้วยเครื่องประดับแห่งความบริสุทธิ์จากครรภ์ของอรุโณทัย น้ําค้างแห่งวัยหนุ่มเป็นของพระองค์ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 4, 'พระเยโฮวาห์ทรงปฏิญาณแล้วและจะไม่เปลี่ยนพระทัยของพระองค์ว่า “เจ้าเป็นปุโรหิตเป็นนิตย์ตามอย่างของเมลคีเซเดค”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 5, 'องค์พระผู้เป็นเจ้าซึ่งประทับข้างขวาพระหัตถ์ของพระองค์ พระองค์จะทรงทลายบรรดากษัตริย์ในวันที่ทรงพระพิโรธ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 6, 'พระองค์จะทรงกระทําการพิพากษาท่ามกลางประชาชาติให้ซากศพเต็มไปหมด พระองค์จะทรงทลายผู้เป็นประมุขทั่วแผ่นดินโลกอันกว้างขวาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 7, 'พระองค์ท่านจะทรงดื่มจากลําธารข้างทาง ฉะนั้นพระองค์ท่านจะทรงยกพระเศียรขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 1, 'จงสรรเสริญพระเยโฮวาห์เถิด ข้าพเจ้าจะสรรเสริญพระเยโฮวาห์ด้วยสิ้นสุดใจของข้าพเจ้า ในคณะผู้เที่ยงธรรม ในชุมนุมชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 2, 'บรรดาพระราชกิจของพระเยโฮวาห์ใหญ่ยิ่ง เป็นที่ค้นคว้าของทุกคนที่พอใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 3, 'พระราชกิจของพระองค์สูงส่งและมีเกียรติ และความชอบธรรมของพระองค์ดํารงอยู่เป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 4, 'พระองค์ได้ทรงให้พระราชกิจมหัศจรรย์ของพระองค์เป็นที่จดจํา พระเยโฮวาห์ทรงมีพระคุณและเต็มไปด้วยพระกรุณา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 5, 'พระองค์ประทานอาหารให้ผู้ที่เกรงกลัวพระองค์ พระองค์จะทรงจดจําพันธสัญญาของพระองค์เสมอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 6, 'พระองค์ได้ทรงสําแดงฤทธานุภาพแห่งพระราชกิจของพระองค์แก่ประชาชนของพระองค์ เพื่อจะทรงประทานมรดกของบรรดาประชาชาติแก่เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 7, 'พระหัตถกิจของพระองค์นั้นสุจริตและยุติธรรม และพระบัญญัติทั้งหลายของพระองค์ก็ไว้ใจได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 8, 'สถาปนาอยู่เป็นนิจกาล และประกอบความจริงกับความเที่ยงธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 9, 'พระองค์ทรงใช้การไถ่ให้มายังประชาชนของพระองค์ พระองค์ทรงบัญชาพันธสัญญาของพระองค์เป็นนิตย์ พระนามของพระองค์บริสุทธิ์และน่าคร้ามกลัวจริงๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 10, 'ความยําเกรงพระเยโฮวาห์เป็นที่เริ่มต้นของสติปัญญา บรรดาผู้ที่ปฏิบัติตามพระบัญญัติของพระองค์ก็ได้ความเข้าใจดี การสรรเสริญพระเจ้าดํารงอยู่เป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 1, 'จงสรรเสริญพระเยโฮวาห์เถิด คนที่เกรงกลัวพระเยโฮวาห์ก็เป็นสุข คือผู้ปีติยินดีเป็นอันมากในพระบัญญัติของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 2, 'เชื้อสายของเขาจะทรงอานุภาพในแผ่นดิน ชั่วอายุที่เที่ยงธรรมจะรับพระพร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 3, 'ทรัพย์ศฤงคารและความมั่งคั่งมีอยู่ในเรือนของเขา และความชอบธรรมของเขาดํารงอยู่เป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 4, 'ความสว่างจะโผล่ขึ้นมาในความมืดให้คนเที่ยงธรรม เขามีความเมตตา เต็มไปด้วยความสงสารและชอบธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 5, 'คนที่ดีจะแสดงความเมตตาคุณและให้ยืม เขาจะดําเนินการของเขาด้วยความยุติธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 6, 'แน่นอนเขาจะไม่ถดถอยเป็นนิตย์ คนจะระลึกถึงคนชอบธรรมอยู่เป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 7, 'เขาจะไม่กลัวข่าวร้าย จิตใจของเขายึดแน่น วางใจในพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 8, 'จิตใจของเขาแน่วแน่ เขาจะไม่กลัวจนกว่าจะเห็นความประสงค์ต่อศัตรูของเขาสําเร็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 9, 'เขาแจกจ่าย เขาได้ให้แก่คนยากจน ความชอบธรรมของเขาดํารงเป็นนิตย์ เขาของเขาจะถูกเชิดชูขึ้นด้วยเกียรติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 10, 'คนชั่วจะเห็นแล้วเป็นทุกข์ใจ เขาขบเขี้ยวเคี้ยวฟันแล้วละลายไป ความปรารถนาของคนชั่วนั้นจะสูญเปล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 1, 'จงสรรเสริญพระเยโฮวาห์เถิด โอ บรรดาผู้รับใช้ของพระเยโฮวาห์เอ๋ย จงสรรเสริญเถิด จงสรรเสริญพระนามพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 2, 'สาธุการแด่พระนามของพระเยโฮวาห์ตั้งแต่บัดนี้เป็นต้นไปเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 3, 'ตั้งแต่ที่ดวงอาทิตย์ขึ้นจนถึงที่ดวงอาทิตย์ตกพระนามของพระเยโฮวาห์เป็นที่สรรเสริญ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 4, 'พระเยโฮวาห์ประทับอยู่สูงเหนือประชาชาติทั้งปวง และสง่าราศีของพระองค์สูงเหนือฟ้าสวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 5, 'ไม่มีพระใดเป็นเหมือนพระเยโฮวาห์พระเจ้าของเรา ผู้ประทับบนที่สูง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 6, 'ผู้ถ่อมพระทัยลงทอดพระเนตรสิ่งทั้งปวงในฟ้าสวรรค์และแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 7, 'พระองค์ทรงยกคนยากจนขึ้นมาจากผงคลี และทรงยกคนขัดสนขึ้นมาจากกองขยะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 8, 'เพื่อให้เขานั่งกับบรรดาเจ้านาย คือบรรดาเจ้านายแห่งชนชาติของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 9, 'พระองค์โปรดให้หญิงหมันมีบ้านอยู่ เป็นแม่ที่ชื่นบานมีบุตร จงสรรเสริญพระเยโฮวาห์เถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 1, 'เมื่ออิสราเอลออกไปจากอียิปต์ คือวงศ์วานของยาโคบไปจากชนชาติต่างภาษา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 2, 'ยูดาห์กลายเป็นสถานบริสุทธิ์ของพระองค์ อิสราเอลเป็นอาณาจักรของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 3, 'ทะเลมองแล้วหนี จอร์แดนหันกลับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 4, 'ภูเขากระโดดเหมือนแกะผู้ เนินเขากระโดดเหมือนลูกแกะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 5, 'เป็นอะไรนะ โอ ทะเลเอ๋ย เจ้าจึงหนี แม่น้ําจอร์แดนเอ๋ย เจ้าจึงหันกลับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 6, 'ภูเขาเอ๋ย เจ้าจึงกระโดดเหมือนแกะผู้ เนินเขาเอ๋ย เจ้าจึงกระโดดเหมือนลูกแกะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 7, 'แผ่นดินเอ๋ย สั่นเทิ้มเถิด ต่อเบื้องพระพักตร์องค์พระผู้เป็นเจ้า ต่อเบื้องพระพักตร์พระเจ้าของยาโคบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 8, 'ผู้ให้หินเป็นสระน้ํา หินเหล็กไฟเป็นน้ําพุ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 1, 'โอ ข้าแต่พระเยโฮวาห์ มิใช่แก่เหล่าข้าพระองค์ มิใช่แก่เหล่าข้าพระองค์ พระเจ้าข้า แต่ขอถวายสง่าราศีแด่พระนามของพระองค์ เพราะเห็นแก่ความเมตตาของพระองค์ และความจริงของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 2, 'ทําไมบรรดาประชาชาติจะกล่าวว่า “บัดนี้พระเจ้าของเขาทั้งหลายอยู่ไหนเล่า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 3, 'แต่พระเจ้าของเราทั้งหลายอยู่ในฟ้าสวรรค์ สิ่งใดที่พระองค์พอพระทัยพระองค์ก็ทรงกระทํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 4, 'รูปเคารพของคนเหล่านั้นเป็นเงินและทองคํา เป็นหัตถกรรมของมนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 5, 'รูปเหล่านั้นมีปาก แต่พูดไม่ได้ มีตา แต่ดูไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 6, 'มีหู แต่ฟังไม่ได้ยิน มีจมูก แต่ดมไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 7, 'มีมือ แต่คลําไม่ได้ มีเท้า แต่เดินไม่ได้ รูปเหล่านั้นทําเสียงในคอไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 8, 'ผู้ที่ทํารูปเหล่านั้นจะเป็นเหมือนรูปเหล่านั้น เออ บรรดาผู้ที่วางใจในรูปเหล่านั้นก็เช่นกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 9, 'โอ อิสราเอลเอ๋ย จงวางใจในพระเยโฮวาห์เถิด พระองค์ทรงเป็นความอุปถัมภ์และเป็นโล่ของเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 10, 'โอ วงศ์วานอาโรนเอ๋ย จงวางใจในพระเยโฮวาห์เถิด พระองค์ทรงเป็นความอุปถัมภ์และเป็นโล่ของเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 11, 'ท่านผู้เกรงกลัวพระเยโฮวาห์เอ๋ย จงวางใจในพระเยโฮวาห์เถิด พระองค์ทรงเป็นความอุปถัมภ์และเป็นโล่ของเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 12, 'พระเยโฮวาห์ทรงเป็นห่วงเราทั้งหลาย พระองค์จะทรงอํานวยพระพรเราทั้งหลาย พระองค์จะทรงอํานวยพระพรแก่วงศ์วานอิสราเอล พระองค์จะทรงอํานวยพระพรแก่วงศ์วานอาโรน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 13, 'พระองค์จะทรงอํานวยพระพรแก่บรรดาผู้ที่ยําเกรงพระเยโฮวาห์ทั้งผู้ใหญ่และผู้น้อย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 14, 'พระเยโฮวาห์จะทรงให้ท่านเพิ่มพูนขึ้นทั้งท่านและลูกหลานของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 15, 'ท่านได้รับพระพรจากพระเยโฮวาห์ผู้ทรงสร้างฟ้าสวรรค์และแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 16, 'ฟ้าสวรรค์เป็นฟ้าสวรรค์ของพระเยโฮวาห์ แต่พระองค์ทรงประทานแผ่นดินโลกให้แก่บุตรทั้งหลายของมนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 17, 'คนตายไม่สรรเสริญพระเยโฮวาห์ หรือผู้ที่ลงไปสู่ที่สงัดก็เช่นนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 18, 'แต่เราทั้งหลายจะสรรเสริญพระเยโฮวาห์ ตั้งแต่บัดนี้เป็นต้นไปเป็นนิตย์ จงสรรเสริญพระเยโฮวาห์เถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 1, 'ข้าพเจ้ารักพระเยโฮวาห์เพราะพระองค์ทรงสดับเสียงและคําวิงวอนของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 2, 'เพราะพระองค์ทรงเงี่ยพระกรรณสดับข้าพเจ้า เพราะฉะนั้นข้าพเจ้าจะทูลพระองค์ตราบเท่าที่ข้าพเจ้ามีชีวิตอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 3, 'ความเศร้าโศกแห่งความตายมาล้อมข้าพเจ้าอยู่ ความเจ็บปวดแห่งนรกจับข้าพเจ้าไว้ ข้าพเจ้าประสบความทุกข์ใจและความระทม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 4, 'แล้วข้าพเจ้าร้องทูลออกพระนามพระเยโฮวาห์ว่า “โอ ข้าแต่พระเยโฮวาห์ ขอทรงช่วยชีวิตข้าพระองค์ให้รอด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 5, 'พระเยโฮวาห์ทรงพระกรุณาและชอบธรรม พระเจ้าของเราทั้งหลายกอปรด้วยพระเมตตา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 6, 'พระเยโฮวาห์ทรงสงวนคนรู้น้อยไว้ เมื่อข้าพเจ้าตกต่ํา พระองค์ทรงช่วยข้าพเจ้าให้รอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 7, 'โอ จิตใจของข้าพเจ้าเอ๋ย กลับไปสู่ที่พักของเจ้าเถิด เพราะพระเยโฮวาห์ทรงกระทําแก่เจ้าอย่างบริบูรณ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 8, 'เพราะพระองค์ทรงช่วยจิตใจข้าพระองค์ให้พ้นจากมัจจุราช ช่วยนัยน์ตาข้าพระองค์จากน้ําตา ช่วยเท้าข้าพระองค์จากการล้ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 9, 'ข้าพเจ้าจะดําเนินอยู่เฉพาะเบื้องพระพักตร์พระเยโฮวาห์ในแผ่นดินของคนเป็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 10, 'ข้าพเจ้าเชื่อแล้ว เหตุฉะนั้นข้าพเจ้าจึงพูด ข้าพเจ้าได้รับความทุกข์ยากใหญ่ยิ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 11, 'ข้าพเจ้ากล่าวด้วยความเร่งร้อนว่า “คนเรานี้เป็นคนโกหกทั้งนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 12, 'ข้าพเจ้าจะเอาอะไรตอบแทนพระเยโฮวาห์ได้ เนื่องจากบรรดาพระราชกิจอันมีพระคุณต่อข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 13, 'ข้าพเจ้าจะยกถ้วยแห่งความรอดและร้องทูลออกพระนามพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 14, 'บัดนี้ข้าพเจ้าจะทําตามคําปฏิญาณของข้าพเจ้าแด่พระเยโฮวาห์ต่อหน้าประชาชนทั้งปวงของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 15, 'มรณกรรมแห่งวิสุทธิชนของพระองค์สําคัญในสายพระเนตรของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 16, 'โอ ข้าแต่พระเยโฮวาห์ แท้จริงข้าพระองค์เป็นผู้รับใช้ของพระองค์ พระเจ้าข้า ข้าพระองค์เป็นผู้รับใช้ของพระองค์ เป็นบุตรชายของหญิงคนใช้ของพระองค์ พระองค์ทรงแก้พันธนะของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 17, 'ข้าพระองค์จะถวายเครื่องสักการบูชาโมทนาพระคุณแด่พระองค์ และจะร้องทูลออกพระนามของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 18, 'บัดนี้ข้าพเจ้าจะทําตามคําปฏิญาณของข้าพเจ้าแด่พระเยโฮวาห์ต่อหน้าประชาชนทั้งปวงของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 19, 'ในบริเวณพระนิเวศของพระเยโฮวาห์ โอ เยรูซาเล็มเอ๋ย ในท่ามกลางเธอ จงสรรเสริญพระเยโฮวาห์เถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 1, 'โอ ประชาชาติทั้งปวงเอ๋ย จงสรรเสริญพระเยโฮวาห์เถิด ชนชาติทั้งหลายเอ๋ย จงยกย่องพระองค์เถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 2, 'เพราะความเมตตาของพระองค์ที่มีต่อเรานั้นใหญ่หลวง และความจริงของพระเยโฮวาห์ดํารงเป็นนิตย์ จงสรรเสริญพระเยโฮวาห์เถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 1, 'โอ จงโมทนาขอบพระคุณพระเยโฮวาห์ เพราะพระองค์ประเสริฐ เพราะความเมตตาของพระองค์ดํารงเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 2, 'บัดนี้จงให้อิสราเอลกล่าวว่า “ความเมตตาของพระองค์ดํารงเป็นนิตย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 3, 'บัดนี้จงให้วงศ์วานอาโรนกล่าวว่า “ความเมตตาของพระองค์ดํารงเป็นนิตย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 4, 'บัดนี้จงให้บรรดาผู้ที่ยําเกรงพระเยโฮวาห์กล่าวว่า “ความเมตตาของพระองค์ดํารงเป็นนิตย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 5, 'ข้าพเจ้าได้ร้องทูลพระเยโฮวาห์ในยามเป็นทุกข์ พระเยโฮวาห์ทรงตอบข้าพเจ้าและทรงตั้งข้าพเจ้าให้อยู่ในที่กว้างขวาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 6, 'มีพระเยโฮวาห์อยู่ฝ่ายข้าพเจ้า ข้าพเจ้าจะไม่กลัว มนุษย์จะทําอะไรแก่ข้าพเจ้าได้เล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 7, 'พระเยโฮวาห์ทรงอยู่ฝ่ายข้าพเจ้า พร้อมกับผู้อื่นที่ช่วยข้าพเจ้า ข้าพเจ้าจึงจะเห็นความปรารถนาของข้าพเจ้าต่อคนที่เกลียดข้าพเจ้านั้นสําเร็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 8, 'การวางใจในพระเยโฮวาห์ก็ดีกว่าที่จะเชื่อใจในมนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 9, 'การวางใจในพระเยโฮวาห์ก็ดีกว่าที่จะเชื่อใจในเจ้านาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 10, 'ประชาชาติทั้งหลายได้ล้อมข้าพเจ้า แต่ข้าพเจ้าจะทําลายเขาในพระนามพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 11, 'เขาทั้งหลายได้ล้อมข้าพเจ้า ล้อมรอบข้าพเจ้า แต่ข้าพเจ้าจะทําลายเขาในพระนามพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 12, 'เขาได้ล้อมข้าพเจ้าเหมือนผึ้ง เขาทั้งหลายดับเสียแล้วเหมือนเปลวไฟหนาม เพราะข้าพเจ้าจะทําลายเขาในพระนามพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 13, 'เจ้าได้ผลักข้าพเจ้าอย่างแรงเพื่อให้ข้าพเจ้าล้มลง แต่พระเยโฮวาห์ทรงช่วยข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 14, 'พระเยโฮวาห์ทรงเป็นกําลังและบทเพลงของข้าพเจ้า พระองค์ทรงมาเป็นความรอดของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 15, 'เสียงแห่งความยินดีและความรอดอยู่ในพลับพลาของผู้ชอบธรรมว่า “พระหัตถ์ขวาของพระเยโฮวาห์ห้าวหาญนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 16, 'พระหัตถ์ขวาของพระเยโฮวาห์เป็นที่เชิดชู พระหัตถ์ขวาของพระเยโฮวาห์ห้าวหาญนัก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 17, 'ข้าพเจ้าจะไม่ตาย แต่ข้าพเจ้าจะเป็นอยู่ และประกาศพระราชกิจของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 18, 'พระเยโฮวาห์ทรงตีสอนข้าพเจ้าอย่างหนัก แต่พระองค์ไม่ทรงมอบข้าพเจ้าไว้กับมัจจุราช');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 19, 'ขอเปิดประตูความชอบธรรมให้ข้าพเจ้า ข้าพเจ้าจะเข้าประตูนั้นไปและจะสรรเสริญพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 20, 'นี่คือประตูของพระเยโฮวาห์ คนชอบธรรมจะเข้าไปทางนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 21, 'ข้าพระองค์จะสรรเสริญพระองค์ เพราะพระองค์ทรงฟังข้าพระองค์ และมาเป็นความรอดของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 22, 'ศิลาซึ่งช่างก่อได้ปฏิเสธเสีย ได้กลับกลายเป็นศิลามุมเอกแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 23, 'การนี้เป็นมาจากพระเยโฮวาห์ เป็นการมหัศจรรย์ประจักษ์แก่ตาเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 24, 'นี่เป็นวันซึ่งพระเยโฮวาห์ได้ทรงสร้าง เราจะเปรมปรีดิ์และยินดีในวันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 25, 'โอ ข้าแต่พระเยโฮวาห์ ขอทรงช่วยข้าพระองค์ให้รอดเถิด โอ ข้าแต่พระเยโฮวาห์ บัดนี้ขอประทานความจําเริญแก่ข้าพระองค์ทั้งหลายเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 26, 'ขอให้ท่านผู้เข้ามาในพระนามของพระเยโฮวาห์จงได้รับพระพร ข้าพเจ้าทั้งหลายอวยพรท่านทั้งหลายจากพระนิเวศของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 27, 'พระเจ้าทรงเป็นพระเยโฮวาห์ ผู้ทรงประทานความสว่างแก่เรา จงผูกมัดเครื่องบูชาด้วยเชือกไปถึงเชิงงอนของแท่นบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 28, 'พระองค์ทรงเป็นพระเจ้าของข้าพระองค์ และข้าพระองค์จะสรรเสริญพระองค์ พระองค์ทรงเป็นพระเจ้าของข้าพระองค์ ข้าพระองค์จะเชิดชูพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 29, 'โอ จงโมทนาขอบพระคุณพระเยโฮวาห์ เพราะพระองค์ประเสริฐ เพราะความเมตตาของพระองค์ดํารงเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 1, 'อาเลฟ (ก)บรรดาผู้ที่ดีรอบคอบในทางของเขาก็เป็นสุข คือผู้ที่ดําเนินตามพระราชบัญญัติของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 2, 'ผู้ที่รักษาบรรดาพระโอวาทของพระองค์ก็เป็นสุข คือผู้ที่แสวงหาพระองค์ด้วยสุดใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 3, 'ทั้งผู้ที่ไม่กระทําความชั่วช้า แต่เดินตามบรรดาพระมรรคาของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 4, 'พระองค์ได้ทรงบัญชาให้เราทั้งหลายรักษาข้อบังคับของพระองค์อย่างเคร่งครัด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 5, 'โอ ขอให้ทางทั้งหลายของข้าพระองค์มั่นคงในการรักษากฎเกณฑ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 6, 'แล้วข้าพระองค์จะไม่ได้รับความอาย เมื่อข้าพระองค์เอาใจใส่พระบัญญัติทั้งสิ้นของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 7, 'ข้าพระองค์จะสรรเสริญพระองค์ด้วยใจเที่ยงตรง เมื่อข้าพระองค์เรียนรู้คําตัดสินอันชอบธรรมของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 8, 'ข้าพระองค์จะรักษากฎเกณฑ์ของพระองค์ โอ ขออย่าทรงทอดทิ้งข้าพระองค์เสียอย่างสิ้นเชิงเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 9, 'เบธ (ข)หนุ่มๆจะรักษาทางของตนให้บริสุทธิ์ได้อย่างไร โดยระแวดระวังตามพระวจนะของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 10, 'ข้าพระองค์แสวงหาพระองค์ด้วยสุดใจของข้าพระองค์ โอ ขออย่าให้ข้าพระองค์หลงไปจากพระบัญญัติของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 11, 'ข้าพระองค์ได้สะสมพระดํารัสของพระองค์ไว้ในใจของข้าพระองค์ เพื่อข้าพระองค์จะไม่ทําบาปต่อพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 12, 'โอ ข้าแต่พระเยโฮวาห์ สาธุการแด่พระองค์ ขอทรงสอนกฎเกณฑ์ของพระองค์แก่ข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 13, 'ข้าพระองค์ประกาศด้วยริมฝีปากของข้าพระองค์ถึงบรรดาคําตัดสินแห่งพระโอษฐ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 14, 'ข้าพระองค์ปีติยินดีในทางแห่งบรรดาพระโอวาทของพระองค์ มากเท่ากับในความมั่งคั่งทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 15, 'ข้าพระองค์จะไตร่ตรองถึงข้อบังคับของพระองค์ และเอาใจใส่ทางทั้งหลายของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 16, 'ข้าพระองค์จะปีติยินดีในกฎเกณฑ์ของพระองค์ ข้าพระองค์จะไม่ลืมพระวจนะของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 17, 'กิเมล (ค)ขอทรงกระทําแก่ผู้รับใช้ของพระองค์อย่างบริบูรณ์ เพื่อข้าพระองค์จะมีชีวิตและจะรักษาพระวจนะของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 18, 'ขอเบิกตาข้าพระองค์ เพื่อข้าพระองค์จะเห็นสิ่งมหัศจรรย์จากพระราชบัญญัติของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 19, 'ข้าพระองค์เป็นคนพเนจรบนแผ่นดินโลก ขออย่าทรงซ่อนพระบัญญัติของพระองค์จากข้าพระองค์เสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 20, 'จิตใจของข้าพระองค์เร่าร้อนเพราะปรารถนาคําตัดสินของพระองค์ตลอดเวลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 21, 'พระองค์ทรงขนาบคนยโสที่ถูกสาปแช่ง ผู้หลงไปจากพระบัญญัติของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 22, 'ขอทรงนําการตําหนิและการประมาทไปจากข้าพระองค์ เพราะข้าพระองค์ได้รักษาบรรดาพระโอวาทของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 23, 'แม้เจ้านายนั่งปรึกษากันต่อสู้ข้าพระองค์ แต่ผู้รับใช้ของพระองค์ได้ไตร่ตรองถึงกฎเกณฑ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 24, 'บรรดาพระโอวาทของพระองค์เป็นความปีติยินดีของข้าพระองค์ เป็นที่ปรึกษาของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 25, 'ดาเลธ (ง)จิตใจของข้าพระองค์ติดผงคลี ขอทรงสงวนชีวิตของข้าพระองค์ตามพระวจนะของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 26, 'ข้าพระองค์ได้ทูลถึงทางของข้าพระองค์ และพระองค์ทรงฟังข้าพระองค์ ขอทรงสอนกฎเกณฑ์ของพระองค์แก่ข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 27, 'ขอทรงกระทําให้ข้าพระองค์เข้าใจทางแห่งข้อบังคับของพระองค์ และข้าพระองค์จะกล่าวถึงพระราชกิจอันมหัศจรรย์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 28, 'จิตใจของข้าพระองค์ละลายไปด้วยความโศก ขอทรงเสริมกําลังข้าพระองค์ตามพระวจนะของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 29, 'ขอทรงให้ทางเทียมเท็จไกลจากข้าพระองค์ และขอโปรดประทานพระราชบัญญัติของพระองค์แก่ข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 30, 'ข้าพระองค์ได้เลือกทางแห่งความจริง ข้าพระองค์ตั้งคําตัดสินของพระองค์ไว้ตรงหน้าข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 31, 'ข้าพระองค์ผูกพันอยู่กับบรรดาพระโอวาทของพระองค์ โอ ข้าแต่พระเยโฮวาห์ ขออย่าให้ข้าพระองค์ขายหน้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 32, 'ข้าพระองค์จะวิ่งในทางพระบัญญัติของพระองค์ เมื่อพระองค์ทรงให้จิตใจของข้าพระองค์กว้างขวาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 33, 'ฮี (จ)โอ ข้าแต่พระเยโฮวาห์ ขอทรงสอนทางแห่งกฎเกณฑ์ของพระองค์แก่ข้าพระองค์ และข้าพระองค์จะรักษาทางนั้นไว้จนสุดปลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 34, 'ขอประทานความเข้าใจแก่ข้าพระองค์ และข้าพระองค์จะรักษาพระราชบัญญัติของพระองค์ไว้ ข้าพระองค์จะปฏิบัติพระราชบัญญัตินั้นด้วยสุดใจของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 35, 'ขอโปรดให้ข้าพระองค์ไปในมรรคาแห่งพระบัญญัติของพระองค์ เพราะข้าพระองค์ยินดีในมรรคานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 36, 'ขอทรงโน้มใจข้าพระองค์ในบรรดาพระโอวาทของพระองค์และมิใช่ในทางโลภกําไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 37, 'ขอทรงหันนัยน์ตาของข้าพระองค์ไปจากการมองดูสิ่งอนิจจัง และขอทรงสงวนชีวิตของข้าพระองค์ในพระมรรคาของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 38, 'ขอทรงยืนยันพระวจนะของพระองค์กับผู้รับใช้ของพระองค์ ผู้เกรงกลัวพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 39, 'ขอทรงหันการเยาะเย้ยซึ่งข้าพระองค์ครั่นคร้ามนั้นไปเสีย เพราะคําตัดสินของพระองค์นั้นดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 40, 'ดูเถิด ข้าพระองค์ปรารถนาข้อบังคับของพระองค์ โดยความชอบธรรมของพระองค์ขอทรงสงวนชีวิตของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 41, 'เวา (ฉ)โอ ข้าแต่พระเยโฮวาห์ ขอความเมตตาของพระองค์มาถึงข้าพระองค์ คือความรอดของพระองค์ตามพระวจนะของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 42, 'แล้วข้าพระองค์จะมีคําตอบแก่ผู้ที่เยาะเย้ยข้าพระองค์ เพราะข้าพระองค์วางใจในพระวจนะของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 43, 'ขออย่าทรงนําพระวจนะแห่งความจริงออกไปจากปากข้าพระองค์อย่างสิ้นเชิง เพราะความหวังของข้าพระองค์อยู่ในคําตัดสินของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 44, 'ข้าพระองค์จะรักษาพระราชบัญญัติของพระองค์สืบๆไปเป็นนิจกาล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 45, 'และข้าพระองค์จะเดินอย่างเสรีเพราะข้าพระองค์ได้แสวงหาข้อบังคับของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 46, 'ข้าพระองค์จะพูดถึงพระโอวาทของพระองค์ต่อเบื้องพระพักตร์บรรดากษัตริย์และจะไม่ขายหน้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 47, 'ข้าพระองค์จะปีติยินดีในพระบัญญัติของพระองค์ ซึ่งข้าพระองค์รัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 48, 'ข้าพระองค์จะยกมือต่อพระบัญญัติของพระองค์ซึ่งข้าพระองค์รัก และข้าพระองค์จะไตร่ตรองถึงกฎเกณฑ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 49, 'เซน (ช)ขอทรงระลึกถึงพระวจนะของพระองค์ที่มีต่อผู้รับใช้ของพระองค์ ซึ่งพระองค์ทรงกระทําให้ข้าพระองค์หวังอยู่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 50, 'นี่คือการเล้าโลมในความทุกข์ยากของข้าพระองค์ คือพระวจนะของพระองค์ให้ชีวิตแก่ข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 51, 'คนโอหังเย้ยหยันข้าพระองค์ยิ่งนัก แต่ข้าพระองค์ไม่หันไปเสียจากพระราชบัญญัติของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 52, 'ข้าพระองค์ระลึกถึงคําตัดสินของพระองค์แต่โบราณกาล โอ ข้าแต่พระเยโฮวาห์ ข้าพระองค์ได้รับความเล้าโลมใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 53, 'ความกริ้วอันเร่าร้อนฉวยข้าพระองค์ไว้ เพราะเหตุคนชั่ว ผู้ละทิ้งพระราชบัญญัติของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 54, 'กฎเกณฑ์ของพระองค์ได้เป็นบทเพลงของข้าพระองค์ในเรือนที่ข้าพระองค์อาศัยอยู่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 55, 'โอ ข้าแต่พระเยโฮวาห์ ในกลางคืนข้าพระองค์ระลึกถึงพระนามของพระองค์ และรักษาพระราชบัญญัติของพระองค์ไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 56, 'สิ่งนี้ได้ตกมายังข้าพระองค์เพราะข้าพระองค์รักษาข้อบังคับของพระองค์ไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 57, 'เชธ (ซ)โอ ข้าแต่พระเยโฮวาห์ พระองค์ทรงเป็นส่วนของข้าพระองค์ ข้าพระองค์กล่าวว่าข้าพระองค์จะรักษาพระวจนะของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 58, 'ข้าพระองค์วอนขอความโปรดปรานของพระองค์ด้วยสิ้นสุดใจของข้าพระองค์ ขอทรงกรุณาแก่ข้าพระองค์ตามพระดํารัสของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 59, 'ข้าพระองค์คิดถึงทางทั้งหลายของข้าพระองค์ แล้วข้าพระองค์หันเท้าของข้าพระองค์ไปทางบรรดาพระโอวาทของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 60, 'ข้าพระองค์เร่งรีบไม่ล่าช้าที่จะรักษาพระบัญญัติของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 61, 'แม้หมู่คนชั่วดักข้าพระองค์ แต่ข้าพระองค์ไม่ลืมพระราชบัญญัติของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 62, 'พอเที่ยงคืน ข้าพระองค์จะลุกขึ้นโมทนาพระคุณพระองค์เนื่องด้วยคําตัดสินอันชอบธรรมของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 63, 'ข้าพระองค์เป็นเพื่อนกับทุกคนผู้ยําเกรงพระองค์กับผู้ที่รักษาข้อบังคับของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 64, 'โอ ข้าแต่พระเยโฮวาห์ แผ่นดินโลกเต็มด้วยความเมตตาของพระองค์ ขอทรงสอนกฎเกณฑ์ของพระองค์แก่ข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 65, 'เทธ (ฌ)พระองค์ได้ทรงกระทําดีต่อผู้รับใช้ของพระองค์ โอ ข้าแต่พระเยโฮวาห์ ตามพระวจนะของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 66, 'ขอทรงสอนคําตัดสินและความรู้แก่ข้าพระองค์ เพราะข้าพระองค์เชื่อถือพระบัญญัติของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 67, 'ก่อนที่ข้าพระองค์ทุกข์ยาก ข้าพระองค์หลงเจิ่น แต่บัดนี้ข้าพระองค์รักษาพระวจนะของพระองค์ไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 68, 'พระองค์ประเสริฐ และทรงกระทําการดี ขอทรงสอนกฎเกณฑ์ของพระองค์แก่ข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 69, 'คนโอหังป้ายความเท็จใส่ข้าพระองค์ แต่ข้าพระองค์จะรักษาข้อบังคับของพระองค์ด้วยสุดใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 70, 'จิตใจของเขาทั้งหลายต่ําช้าเหมือนไขมัน แต่ข้าพระองค์ปีติยินดีในพระราชบัญญัติของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 71, 'ดีแล้วที่ข้าพระองค์ทุกข์ยากเพื่อข้าพระองค์จะเรียนรู้ถึงกฎเกณฑ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 72, 'สําหรับข้าพระองค์ พระราชบัญญัติแห่งพระโอษฐ์ของพระองค์ก็ดีกว่าทองคําและเงินพันๆแท่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 73, 'โจด (ญ)พระหัตถ์ของพระองค์ได้สร้างและสถาปนาข้าพระองค์ ขอประทานความเข้าใจแก่ข้าพระองค์เพื่อข้าพระองค์จะเรียนรู้พระบัญญัติของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 74, 'บรรดาผู้เกรงกลัวพระองค์จะเห็นข้าพระองค์และเปรมปรีดิ์ เพราะว่าข้าพระองค์ได้หวังในพระวจนะของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 75, 'โอ ข้าแต่พระเยโฮวาห์ ข้าพระองค์ทราบว่าคําตัดสินของพระองค์นั้นถูกต้องแล้ว และทราบว่าด้วยความซื่อตรงพระองค์ทรงให้ข้าพระองค์ทุกข์ยาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 76, 'ขอความเมตตาของพระองค์เป็นที่เล้าโลมข้าพระองค์ ตามพระดํารัสของพระองค์ที่มีแก่ผู้รับใช้ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 77, 'ขอพระกรุณาของพระองค์มายังข้าพระองค์ เพื่อข้าพระองค์จะเป็นอยู่ เพราะพระราชบัญญัติของพระองค์เป็นความปีติยินดีของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 78, 'ขอทรงให้คนโอหังได้รับความอาย เพราะว่าเขาได้คว่ําข้าพระองค์ด้วยความเท็จโดยไม่มีเหตุ แต่ข้าพระองค์จะไตร่ตรองถึงข้อบังคับของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 79, 'ขอให้บรรดาผู้ที่ยําเกรงพระองค์หันกลับมายังข้าพระองค์ พร้อมกับผู้ที่ทราบถึงบรรดาพระโอวาทของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 80, 'ขอให้จิตใจข้าพระองค์ไร้ตําหนิในเรื่องกฎเกณฑ์ของพระองค์ เพื่อข้าพระองค์จะไม่ต้องขายหน้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 81, 'คาฟ (ด)จิตใจของข้าพระองค์อ่อนระโหยคอยความรอดของพระองค์ แต่ข้าพระองค์หวังในพระวจนะของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 82, 'นัยน์ตาของข้าพระองค์มัวมืดไปด้วยคอยพระดํารัสของพระองค์ ข้าพระองค์ทูลถามว่า “เมื่อไรพระองค์จะทรงเล้าโลมข้าพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 83, 'เพราะว่าข้าพระองค์เป็นเหมือนถุงหนังถูกรมควัน แต่ข้าพระองค์ยังไม่ลืมกฎเกณฑ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 84, 'ผู้รับใช้ของพระองค์จะอยู่นานเท่าไร พระองค์จะทรงกระทําการพิพากษาบรรดาผู้ข่มเหงข้าพระองค์เมื่อไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 85, 'คนโอหังได้ขุดหลุมพรางดักข้าพระองค์ ซึ่งไม่สอดคล้องกับพระราชบัญญัติของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 86, 'พระบัญญัติของพระองค์ทั้งสิ้นสัตย์ซื่อ เขาข่มเหงข้าพระองค์ด้วยความเท็จ ขอทรงช่วยข้าพระองค์ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 87, 'เขาเกือบจะทําให้ข้าพระองค์ดับชีพไปจากแผ่นดินโลกแล้ว แต่ข้าพระองค์ไม่ทอดทิ้งข้อบังคับของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 88, 'ขอทรงสงวนชีวิตข้าพระองค์ไว้ด้วยความเมตตาของพระองค์ เพื่อข้าพระองค์จะรักษาพระโอวาทแห่งพระโอษฐ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 89, 'ลาเมด (ต)โอ ข้าแต่พระเยโฮวาห์ พระวจนะของพระองค์ปักแน่นอยู่ในสวรรค์เป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 90, 'ความซื่อตรงของพระองค์ดํารงอยู่ทุกชั่วอายุ พระองค์ทรงสถาปนาแผ่นดินโลกและมันก็ตั้งอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 91, 'โดยกฎของพระองค์สิ่งเหล่านี้ตั้งมั่นอยู่ทุกวันนี้ เพราะของทุกสิ่งเป็นผู้รับใช้ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 92, 'ถ้าพระราชบัญญัติของพระองค์ไม่เป็นที่ปีติยินดีของข้าพระองค์ ข้าพระองค์คงจะพินาศแล้วในความทุกข์ยากของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 93, 'ข้าพระองค์จะไม่ลืมข้อบังคับของพระองค์เลย เพราะพระองค์ทรงสงวนชีวิตของข้าพระองค์โดยข้อบังคับนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 94, 'ข้าพระองค์เป็นของพระองค์ ขอทรงช่วยข้าพระองค์ให้รอด เพราะข้าพระองค์ได้แสวงหาข้อบังคับของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 95, 'คนชั่วซุ่มคอยทําลายข้าพระองค์ แต่ข้าพระองค์จะพิจารณาพระโอวาทของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 96, 'ข้าพระองค์เคยเห็นขอบเขตของความสมบูรณ์ทั้งสิ้นแล้ว แต่พระบัญญัติของพระองค์กว้างขวางเหลือเกิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 97, 'เมม (ถ)โอ ข้าพระองค์รักพระราชบัญญัติของพระองค์จริงๆ เป็นการไตร่ตรองของข้าพระองค์วันยังค่ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 98, 'โดยพระบัญญัติของพระองค์ พระองค์ทรงกระทําให้ข้าพระองค์ฉลาดกว่าศัตรูของข้าพระองค์ เพราะพระบัญญัตินั้นอยู่กับข้าพระองค์เสมอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 99, 'ข้าพระองค์มีความเข้าใจมากกว่าบรรดาครูของข้าพระองค์ เพราะบรรดาพระโอวาทของพระองค์เป็นการไตร่ตรองของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 100, 'ข้าพระองค์เข้าใจมากกว่าคนสูงอายุ เพราะข้าพระองค์รักษาข้อบังคับของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 101, 'ข้าพระองค์รั้งเท้าข้าพระองค์ไว้จากวิถีชั่วทุกอย่าง เพื่อรักษาพระวจนะของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 102, 'ข้าพระองค์มิได้เลี่ยงจากคําตัดสินของพระองค์ เพราะพระองค์ได้ทรงสอนข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 103, 'พระดํารัสของพระองค์นั้น ข้าพระองค์ชิมแล้วหวานจริงๆ หวานกว่าน้ําผึ้งเมื่อถึงปากข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 104, 'ข้าพระองค์ได้ความเข้าใจโดยข้อบังคับของพระองค์ เพราะฉะนั้นข้าพระองค์เกลียดชังวิถีเท็จทุกอย่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 105, 'นูน (ท)พระวจนะของพระองค์เป็นโคมสําหรับเท้าของข้าพระองค์ และเป็นความสว่างแก่มรรคาของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 106, 'ข้าพระองค์ได้ตั้งสัตย์ปฏิญาณและจะกระทําให้สําเร็จ ว่าจะรักษาคําตัดสินอันชอบธรรมของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 107, 'ข้าพระองค์ทุกข์ยากอย่างหนัก โอ ข้าแต่พระเยโฮวาห์ ขอทรงสงวนชีวิตของข้าพระองค์ตามพระวจนะของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 108, 'โอ ข้าแต่พระเยโฮวาห์ ขอทรงรับคําสักการบูชาด้วยปากของข้าพระองค์ และขอสอนคําตัดสินของพระองค์แก่ข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 109, 'ชีวิตของข้าพระองค์อยู่ในมือของข้าพระองค์เสมอ แต่ข้าพระองค์ไม่ลืมพระราชบัญญัติของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 110, 'คนชั่ววางกับดักข้าพระองค์ แต่ข้าพระองค์ไม่หลงเจิ่นจากข้อบังคับของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 111, 'บรรดาพระโอวาทของพระองค์ ข้าพระองค์รับไว้เป็นมรดกเป็นนิตย์ พระเจ้าข้า เป็นความชื่นบานแก่ใจข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 112, 'ข้าพระองค์โน้มจิตใจข้าพระองค์ปฏิบัติตามกฎเกณฑ์ของพระองค์เป็นนิตย์จนอวสาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 113, 'ซาเมค (ธ)ข้าพระองค์เกลียดชังความคิดสองจิตสองใจ แต่ข้าพระองค์รักพระราชบัญญัติของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 114, 'พระองค์ทรงเป็นที่ซ่อนและเป็นโล่ของข้าพระองค์ ข้าพระองค์หวังในพระวจนะของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 115, 'แน่ะ เจ้าคนทําชั่ว ไปเสียจากข้า เพื่อข้าจะรักษาพระบัญญัติของพระเจ้าของข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 116, 'ขอทรงประคองข้าพระองค์ไว้ตามพระดํารัสของพระองค์ เพื่อข้าพระองค์จะเป็นอยู่ และอย่าให้ข้าพระองค์ขายหน้าในความหวังของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 117, 'ขอทรงชูข้าพระองค์ขึ้น เพื่อข้าพระองค์จะปลอดภัย และมีความนับถือกฎเกณฑ์ของพระองค์สืบๆไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 118, 'พระองค์ทรงตะเพิดบรรดาคนที่หลงเจิ่นจากกฎเกณฑ์ของพระองค์ พระเจ้าข้า อุบายหลอกลวงของเขาคือความเท็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 119, 'พระองค์ทรงทิ้งบรรดาคนชั่วของแผ่นดินโลกเหมือนทิ้งขี้แร่ เพราะฉะนั้นข้าพระองค์รักบรรดาพระโอวาทของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 120, 'เนื้อหนังข้าพระองค์สั่นเทิ้มเพราะเกรงกลัวพระองค์ และข้าพระองค์กลัวคําตัดสินของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 121, 'เอน (น)ข้าพระองค์ได้กระทําสิ่งที่ยุติธรรมและเที่ยงธรรม ขออย่าทรงละข้าพระองค์แก่ผู้บีบบังคับข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 122, 'ขอทรงเป็นประกันเพื่อช่วยผู้รับใช้ของพระองค์ ขออย่าทรงให้คนโอหังบีบบังคับข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 123, 'นัยน์ตาของข้าพระองค์มัวมืดไปด้วยคอยความรอดของพระองค์ และคอยพระดํารัสชอบธรรมของพระองค์สําเร็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 124, 'ขอทรงกระทําแก่ผู้รับใช้ของพระองค์ตามความเมตตาของพระองค์ และขอทรงสอนกฎเกณฑ์ของพระองค์แก่ข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 125, 'ข้าพระองค์เป็นผู้รับใช้ของพระองค์ ขอทรงประทานความเข้าใจแก่ข้าพระองค์ เพื่อข้าพระองค์จะรู้ถึงบรรดาพระโอวาทของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 126, 'เป็นเวลาที่พระเยโฮวาห์ควรทรงจัดการ เพราะเขาหักพระราชบัญญัติของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 127, 'เพราะฉะนั้นข้าพระองค์รักพระบัญญัติของพระองค์ยิ่งกว่าทองคํา ยิ่งกว่าทองคําเนื้อดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 128, 'เพราะฉะนั้นข้าพระองค์ถือว่าบรรดาข้อบังคับของพระองค์ถูกต้องในทุกเรื่อง ข้าพระองค์เกลียดมรรคาทุจริตทุกทาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 129, 'บี (บ)บรรดาพระโอวาทของพระองค์ประหลาดนัก เพราะฉะนั้นจิตใจของข้าพระองค์จึงรักษาไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 130, 'การคลี่คลายพระวจนะของพระองค์ให้ความสว่าง ทั้งให้ความเข้าใจแก่คนรู้น้อย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 131, 'ข้าพระองค์หอบจนอ้าปาก เพราะข้าพระองค์กระหายพระบัญญัติของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 132, 'ขอทรงหันมาหาข้าพระองค์และมีพระกรุณาต่อข้าพระองค์ ดังที่พระองค์ทรงเคยกระทําต่อผู้ที่รักพระนามของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 133, 'ขอทรงให้ย่างเท้าของข้าพระองค์มั่นคงอยู่ในพระดํารัสของพระองค์ ขออย่าทรงให้ความชั่วช้าใดๆมีอํานาจเหนือข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 134, 'ขอทรงช่วยข้าพระองค์ให้พ้นการบีบบังคับของมนุษย์ เพื่อข้าพระองค์จะรักษาข้อบังคับของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 135, 'ขอทรงกระทําให้พระพักตร์ของพระองค์ทอแสงมาที่ผู้รับใช้ของพระองค์ และขอทรงสอนกฎเกณฑ์ของพระองค์แก่ข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 136, 'ข้าพระองค์น้ําตาไหลพรั่งพรูเพราะคนไม่รักษาพระราชบัญญัติของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 137, 'ซาดดี (ป)โอ ข้าแต่พระเยโฮวาห์ พระองค์ชอบธรรมและคําตัดสินของพระองค์ก็ถูกต้อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 138, 'บรรดาพระโอวาทที่พระองค์ทรงกําหนดไว้ก็ชอบธรรมและสัตย์สุจริตทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 139, 'ความเร่าร้อนของข้าพระองค์เผาข้าพระองค์อยู่ เพราะคู่อริของข้าพระองค์ลืมพระวจนะของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 140, 'พระดํารัสของพระองค์นั้นบริสุทธิ์ เพราะฉะนั้นผู้รับใช้ของพระองค์รักพระดํารัสนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 141, 'ข้าพระองค์ต่ําต้อยและเป็นที่ดูถูก แต่ข้าพระองค์ไม่ลืมข้อบังคับของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 142, 'ความชอบธรรมของพระองค์ชอบธรรมอยู่เป็นนิตย์ และพระราชบัญญัติของพระองค์เป็นความจริง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 143, 'ความทุกข์ยากลําบากและความแสนระทมได้มาสู่ข้าพระองค์ แต่พระบัญญัติของพระองค์เป็นความปีติยินดีของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 144, 'บรรดาพระโอวาทของพระองค์ชอบธรรมเป็นนิตย์ ขอประทานความเข้าใจแก่ข้าพระองค์เพื่อข้าพระองค์จะดํารงชีวิตอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 145, 'คอฟ (ผ)ข้าพระองค์ร้องทูลด้วยสิ้นสุดใจของข้าพระองค์ โอ ข้าแต่พระเยโฮวาห์ ขอทรงฟังข้าพระองค์ ข้าพระองค์จะรักษากฎเกณฑ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 146, 'ข้าพระองค์ร้องทูลพระองค์ ขอทรงช่วยข้าพระองค์ให้รอด เพื่อข้าพระองค์จะรักษาบรรดาพระโอวาทของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 147, 'ข้าพระองค์ตื่นขึ้นก่อนอรุณ ทูลขอความช่วยเหลือ ข้าพระองค์หวังอยู่ในพระวจนะของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 148, 'นัยน์ตาของข้าพระองค์ตื่นอยู่ก่อนถึงยามทุกยามในกลางคืน เพื่อข้าพระองค์สามารถไตร่ตรองถึงพระดํารัสของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 149, 'ขอทรงฟังเสียงข้าพระองค์ด้วยความเมตตาของพระองค์ โอ ข้าแต่พระเยโฮวาห์ ขอทรงสงวนชีวิตของข้าพระองค์ไว้ตามคําตัดสินของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 150, 'ผู้ติดตามการมุ่งร้ายเข้ามาใกล้ข้าพระองค์แล้ว เขาอยู่ห่างไกลจากพระราชบัญญัติของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 151, 'โอ ข้าแต่พระเยโฮวาห์ แต่พระองค์ทรงสถิตอยู่ใกล้ และพระบัญญัติทั้งสิ้นของพระองค์ก็จริง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 152, 'ข้าพระองค์ทราบนานแล้วจากบรรดาพระโอวาทของพระองค์ ว่าพระองค์ทรงตั้งไว้เป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 153, 'เรช (ฝ)ขอทอดพระเนตรความทุกข์ยากของข้าพระองค์ และขอทรงช่วยข้าพระองค์ให้พ้น เพราะข้าพระองค์มิได้ลืมพระราชบัญญัติของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 154, 'ขอทรงแก้คดีของข้าพระองค์และขอทรงช่วยข้าพระองค์ให้พ้น ขอทรงสงวนชีวิตของข้าพระองค์ตามพระดํารัสของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 155, 'ความรอดนั้นอยู่ห่างไกลจากคนชั่ว เพราะเขาไม่แสวงหากฎเกณฑ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 156, 'โอ ข้าแต่พระเยโฮวาห์ พระกรุณาของพระองค์ใหญ่หลวงนัก ขอทรงสงวนชีวิตของข้าพระองค์ไว้ตามคําตัดสินของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 157, 'ผู้ข่มเหงและปรปักษ์ของข้าพระองค์มีมากมาย แต่ข้าพระองค์ไม่หันเหไปจากบรรดาพระโอวาทของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 158, 'ข้าพระองค์มองดูคนละเมิดด้วยความชิงชัง เพราะเขาไม่รักษาพระดํารัสของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 159, 'โอ ข้าแต่พระเยโฮวาห์ ขอทรงพิเคราะห์ว่าข้าพระองค์รักข้อบังคับของพระองค์มากเท่าใด ขอทรงสงวนชีวิตของข้าพระองค์ไว้ตามความเมตตาของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 160, 'ตั้งแต่แรกพระวจนะของพระองค์คือความจริง และคําตัดสินอันชอบธรรมของพระองค์ทุกข้อดํารงอยู่เป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 161, 'ชิน (พ)เจ้านายได้ข่มเหงข้าพระองค์โดยปราศจากเหตุ แต่จิตใจของข้าพระองค์ตะลึงพรึงเพริดเพราะพระวจนะของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 162, 'ข้าพระองค์เปรมปรีดิ์เพราะพระดํารัสของพระองค์ อย่างผู้ซึ่งพบของที่ถูกริบมาเป็นอันมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 163, 'ข้าพระองค์เกลียดและสะอิดสะเอียนต่อความเท็จ แต่ข้าพระองค์รักพระราชบัญญัติของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 164, 'ข้าพระองค์สรรเสริญพระองค์วันละเจ็ดครั้ง เหตุเรื่องข้อตัดสินอันชอบธรรมของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 165, 'บุคคลเหล่านั้นที่รักพระราชบัญญัติของพระองค์มีสันติภาพใหญ่ยิ่ง ไม่มีสิ่งใดกระทําให้เขาสะดุดได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 166, 'ข้าแต่พระเยโฮวาห์ ข้าพระองค์หวังในความรอดของพระองค์ และข้าพระองค์ทําตามพระบัญญัติของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 167, 'จิตใจของข้าพระองค์รักษาบรรดาพระโอวาทของพระองค์ ข้าพระองค์รักพระโอวาทนั้นมากยิ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 168, 'ข้าพระองค์รักษาข้อบังคับและบรรดาพระโอวาทของพระองค์ เพราะทางทั้งสิ้นของข้าพระองค์อยู่ต่อเบื้องพระพักตร์พระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 169, 'เทา (ฟ)โอ ข้าแต่พระเยโฮวาห์ ขอเสียงร้องทูลของข้าพระองค์ขึ้นมาต่อเบื้องพระพักตร์พระองค์ ขอประทานความเข้าใจแก่ข้าพระองค์ตามพระวจนะของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 170, 'ขอคําวิงวอนของข้าพระองค์ขึ้นมาต่อเบื้องพระพักตร์พระองค์ ขอทรงช่วยข้าพระองค์ให้พ้นตามพระดํารัสของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 171, 'ริมฝีปากของข้าพระองค์จะเทคําสรรเสริญออกมา ที่พระองค์ทรงสอนกฎเกณฑ์ของพระองค์แก่ข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 172, 'ลิ้นของข้าพระองค์จะกล่าวเรื่องพระดํารัสของพระองค์ เพราะพระบัญญัติทั้งสิ้นของพระองค์ชอบธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 173, 'ขอพระหัตถ์ของพระองค์ทรงช่วยข้าพระองค์ เพราะข้าพระองค์ได้เลือกข้อบังคับของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 174, 'โอ ข้าแต่พระเยโฮวาห์ ข้าพระองค์กระหายความรอดของพระองค์ และพระราชบัญญัติของพระองค์เป็นความปีติยินดีของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 175, 'ขอทรงโปรดให้จิตใจข้าพระองค์มีชีวิตอยู่ และจิตใจนั้นจะสรรเสริญพระองค์ และให้คําตัดสินของพระองค์ช่วยข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 176, 'ข้าพระองค์หลงเจิ่นดังแกะที่หายไป ขอทรงเสาะหาผู้รับใช้ของพระองค์ เพราะข้าพระองค์ไม่ลืมพระบัญญัติของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 1, 'บทเพลงใช้แห่ขึ้นเมื่อข้าพเจ้าทุกข์ใจ ข้าพเจ้าได้ร้องทูลต่อพระเยโฮวาห์ และพระองค์ทรงฟังข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 2, 'คือทูลว่า “โอ ข้าแต่พระเยโฮวาห์ ขอทรงช่วยจิตใจข้าพระองค์ให้พ้นจากริมฝีปากมุสา จากลิ้นที่หลอกลวง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 3, 'แน่ะ ลิ้นหลอกลวงเอ๋ย จะประทานสิ่งใดแก่เจ้าและจะเพิ่มเติมอะไรให้เจ้าอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 4, 'ลูกธนูคมของนักรบกับถ่านไม้จําพวกสนจูนิเปอร์ที่ลุกโพลง น่ะซี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 5, 'วิบัติแก่ข้าพเจ้า ที่ข้าพเจ้าอาศัยกับชนเมเชค ที่พักอยู่ท่ามกลางเต็นท์ของคนเคดาร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 6, 'จิตใจข้าพเจ้าพักอยู่ท่ามกลางผู้เกลียดสันตินานจนเกินไปแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 7, 'ข้าพเจ้าชอบสันติ แต่เมื่อข้าพเจ้าพูด เขาหนุนสงคราม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 1, 'บทเพลงใช้แห่ขึ้นข้าพเจ้าจะเงยหน้าดูภูเขา ความอุปถัมภ์ของข้าพเจ้ามาจากไหน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 2, 'ความอุปถัมภ์ของข้าพเจ้ามาจากพระเยโฮวาห์ ผู้ทรงสร้างฟ้าสวรรค์และแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 3, 'พระองค์จะไม่ให้เท้าของท่านพลาดไป พระองค์ผู้ทรงอารักขาท่านจะไม่เคลิ้มไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 4, 'ดูเถิด พระองค์ผู้ทรงอารักขาอิสราเอลจะไม่ทรงหลับสนิทหรือนิทรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 5, 'พระเยโฮวาห์ทรงเป็นผู้อารักขาท่าน พระเยโฮวาห์ทรงเป็นที่กําบังที่ข้างขวามือของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 6, 'ดวงอาทิตย์จะไม่โจมตีท่านในเวลากลางวัน หรือดวงจันทร์ในเวลากลางคืน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 7, 'พระเยโฮวาห์จะทรงอารักขาท่านให้พ้นภยันตรายทั้งสิ้น พระองค์จะทรงอารักขาชีวิตของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 8, 'พระเยโฮวาห์จะทรงอารักขาการเข้าออกของท่านตั้งแต่กาลบัดนี้สืบไปเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 1, 'บทเพลงใช้แห่ขึ้นของดาวิดข้าพเจ้ายินดี เมื่อเขากล่าวแก่ข้าพเจ้าว่า “ให้เราเข้าไปยังพระนิเวศพระเยโฮวาห์เถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 2, 'โอ เยรูซาเล็มเอ๋ย เท้าของพวกข้าพเจ้าจะยืนอยู่ภายในประตูกําแพงของเธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 3, 'เขาสร้างเยรูซาเล็มไว้เป็นนครซึ่งประสานแน่นไว้ด้วยกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 4, 'เป็นที่ที่บรรดาตระกูลต่างๆขึ้นไป คือบรรดาตระกูลของพระเยโฮวาห์ ไปยังหีบพระโอวาทของอิสราเอล ให้ถวายโมทนาแด่พระนามของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 5, 'พระที่นั่งสําหรับการพิพากษาได้ตั้งอยู่ที่นั่น คือพระที่นั่งของพระราชวงศ์ดาวิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 6, 'จงอธิษฐานขอสันติภาพให้แก่เยรูซาเล็มว่า “ขอบรรดาผู้ที่รักเธอจงจําเริญ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 7, 'ขอสันติภาพจงมีอยู่ภายในกําแพงของเธอ และให้ความเจริญอยู่ภายในวังของเธอ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 8, 'เพื่อเห็นแก่พี่น้องและมิตรสหาย บัดนี้ข้าพเจ้าจะพูดว่า “สันติภาพจงมีอยู่ภายในเธอ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 9, 'เพื่อเห็นแก่พระนิเวศของพระเยโฮวาห์พระเจ้าของเรา ข้าพเจ้าจะหาความดีให้เธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 1, 'บทเพลงใช้แห่ขึ้นโอ ข้าแต่พระองค์ผู้ประทับในฟ้าสวรรค์ ข้าพระองค์เงยหน้าดูพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 2, 'ดูเถิด ตาของผู้รับใช้มองดูมือนายของตนฉันใด และตาของสาวใช้มองดูมือนายหญิงของตนฉันใด ตาของข้าพเจ้าทั้งหลายมองดูพระเยโฮวาห์พระเจ้าของข้าพเจ้าทั้งหลายจนกว่าพระองค์จะมีพระกรุณาต่อข้าพเจ้าทั้งหลายฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 3, 'โอ ข้าแต่พระเยโฮวาห์ ขอทรงพระกรุณาต่อพวกข้าพระองค์ ขอทรงพระกรุณาต่อพวกข้าพระองค์เถิด พระเจ้าข้า เพราะพวกข้าพระองค์เอือมระอาความหมิ่นประมาท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 4, 'จิตใจของข้าพระองค์ทั้งหลายเอือมระอาการเยาะเย้ยของคนที่อยู่สบาย คือการหมิ่นประมาทของคนเย่อหยิ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 1, 'บทเพลงใช้แห่ขึ้นของดาวิด“ถ้าพระเยโฮวาห์มิได้ทรงสถิตฝ่ายพวกเรา” เออ ขอให้อิสราเอลกล่าวว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 2, '“ถ้าพระเยโฮวาห์มิได้ทรงสถิตฝ่ายพวกเรา เมื่อคนลุกขึ้นต่อสู้เรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 3, 'แล้วเขาจะกลืนเราเสียทั้งเป็น เมื่อความโกรธของเขาพลุ่งขึ้นต่อเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 4, 'แล้วน้ําทั้งหลายจะท่วมพวกเรา กระแสน้ําจะไหลอยู่เหนือจิตใจเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 5, 'แล้วน้ําที่กําเริบจะไหลท่วมจิตใจเราไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 6, 'สาธุการแด่พระเยโฮวาห์ผู้มิได้ทรงให้เราเป็นเหยื่อฟันเขาเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 7, 'จิตใจเรารอดไปอย่างนกจากกับของพรานนก กับก็หัก และเราได้หนีรอดไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 8, 'ความอุปถัมภ์ของเราอยู่ในพระนามของพระเยโฮวาห์ ผู้ทรงสร้างฟ้าสวรรค์และแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 1, 'บทเพลงใช้แห่ขึ้นบรรดาผู้ที่วางใจในพระเยโฮวาห์ก็เหมือนภูเขาศิโยน ซึ่งไม่หวั่นไหว แต่ดํารงอยู่เป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 2, 'ภูเขาอยู่รอบเยรูซาเล็มฉันใด พระเยโฮวาห์ทรงอยู่รอบประชาชนของพระองค์ ตั้งแต่เวลานี้สืบต่อไปเป็นนิตย์ฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 3, 'เพราะคทาของคนชั่วจะไม่พักอยู่เหนือแผ่นดินที่ตกเป็นส่วนของคนชอบธรรม เกรงว่าคนชอบธรรมจะยื่นมือออกกระทําความชั่วช้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 4, 'โอ ข้าแต่พระเยโฮวาห์ ขอทรงประกอบการดีต่อผู้ทําดี และต่อผู้เที่ยงธรรมในจิตใจของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 5, 'แต่บรรดาผู้ที่หันเข้าหาทางคดของเขา พระเยโฮวาห์จะทรงพาเขาไปพร้อมกับคนทําความชั่วช้า แต่สันติภาพจะมีอยู่ในอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 1, 'บทเพลงใช้แห่ขึ้นเมื่อพระเยโฮวาห์ทรงให้ศิโยนกลับมาจากการเป็นเชลย เราก็เป็นเหมือนคนที่ฝันไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 2, 'ปากของเราได้หัวเราะเต็มที่ และลิ้นของเราได้เปล่งเสียงโห่ร้องอย่างชื่นบาน แล้วเขาได้พูดกันท่ามกลางประชาชาติว่า “พระเยโฮวาห์ทรงกระทําการมโหฬารให้เขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 3, 'พระเยโฮวาห์ทรงกระทําการมโหฬารให้เรา เรามีความยินดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 4, 'โอ ข้าแต่พระเยโฮวาห์ ขอทรงให้ข้าพระองค์ทั้งหลายกลับมาจากการเป็นเชลย อย่างทางน้ําไหลที่ทางใต้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 5, 'บรรดาผู้ที่หว่านด้วยน้ําตาจะได้เกี่ยวด้วยเสียงโห่ร้องอย่างชื่นบาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 6, 'ผู้ที่ร้องไห้ออกไปหอบหิ้วเมล็ดพืชอันมีค่าจะกลับบ้านด้วยเสียงโห่ร้องอย่างชื่นบาน นําฟ่อนข้าวของตนมาด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 1, 'บทเพลงใช้แห่ขึ้นของซาโลมอนถ้าพระเยโฮวาห์มิได้ทรงสร้างบ้าน บรรดาผู้ที่สร้างก็เหนื่อยเปล่า ถ้าพระเยโฮวาห์มิได้ทรงเฝ้าอยู่เหนือนคร คนยามตื่นอยู่ก็เหนื่อยเปล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 2, 'เป็นการเหนื่อยเปล่าที่ท่านลุกขึ้นแต่เช้ามืด นอนดึก และกินอาหารแห่งความเศร้าโศก เพราะพระองค์ประทานแก่ผู้ที่รักของพระองค์ให้หลับสบาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 3, 'ดูเถิด บุตรทั้งหลายเป็นมรดกจากพระเยโฮวาห์ ผู้บังเกิดจากครรภ์เป็นรางวัลของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 4, 'บุตรทั้งหลายที่เกิดเมื่อเขายังหนุ่มก็เหมือนลูกธนูในมือนักรบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 5, 'ชายใดๆที่มีลูกธนูเต็มแล่งก็เป็นสุข เขาจะไม่ต้องละอาย แต่เขาจะพูดกับศัตรูของเขาที่ประตูเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 1, 'บทเพลงใช้แห่ขึ้นทุกคนที่เกรงกลัวพระเยโฮวาห์ก็เป็นสุข คือผู้ที่ดําเนินในมรรคาของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 2, 'เพราะท่านจะกินผลน้ํามือของท่าน ท่านจะเป็นสุข และท่านจะอยู่เย็นเป็นสุข');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 3, 'ภรรยาของท่านจะเป็นอย่างเถาองุ่นลูกดกอยู่ข้างบ้านของท่าน ลูกๆของท่านจะเป็นเหมือนหน่อมะกอกเทศรอบโต๊ะของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 4, 'ดูเถิด คนที่ยําเกรงพระเยโฮวาห์จะได้รับพระพรดั่งนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 5, 'พระเยโฮวาห์จะทรงอํานวยพระพรท่านจากศิโยน และท่านจะเห็นความเจริญของเยรูซาเล็มตลอดวันเวลาชีวิตของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 6, 'เออ ท่านจะเห็นลูกหลานของท่าน และสันติภาพมีอยู่ในอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 1, 'บทเพลงใช้แห่ขึ้น“เขาได้ให้ข้าพเจ้าทุกข์ยากหลายครั้งตั้งแต่หนุ่มๆมา” ให้อิสราเอลกล่าวเถิดว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 2, '“เขาได้ให้ข้าพเจ้าทุกข์ยากหลายครั้งตั้งแต่หนุ่มๆมา แต่เขายังเอาชนะข้าพเจ้าไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 3, 'คนที่ไถก็ได้ไถบนหลังข้าพเจ้า เขาทํารอยไถของเขาให้ยาว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 4, 'พระเยโฮวาห์ทรงชอบธรรม พระองค์ทรงตัดเครื่องจองจําของคนชั่วออก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 5, 'ขอให้บรรดาผู้ที่เกลียดชังศิโยนได้ขายหน้าและต้องถอยกลับไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 6, 'ให้เขาเป็นเหมือนหญ้าที่งอกบนหลังคาเรือน ซึ่งเหี่ยวแห้งไปก่อนมันโตขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 7, 'ซึ่งคนเกี่ยวไม่เก็บใส่มือหรือคนที่มัดเป็นฟ่อนไม่เก็บไว้ที่อกของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 8, 'ทั้งคนที่ผ่านไปไม่พูดว่า “ขอพระพรของพระเยโฮวาห์อยู่บนท่านทั้งหลาย เราอวยพรท่านทั้งหลายในพระนามพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 1, 'บทเพลงใช้แห่ขึ้นโอ ข้าแต่พระเยโฮวาห์ ข้าพระองค์ร้องทูลพระองค์จากที่ลึก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 2, 'ข้าแต่องค์พระผู้เป็นเจ้า ขอทรงสดับเสียงของข้าพระองค์ ขอทรงเงี่ยพระกรรณสดับเสียงคําวิงวอนของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 3, 'โอ ข้าแต่พระเยโฮวาห์ ถ้าพระองค์จะทรงหมายความชั่วช้าไว้ องค์พระผู้เป็นเจ้าเจ้าข้า ผู้ใดจะยืนอยู่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 4, 'แต่พระองค์มีการอภัยเพื่อเขาจะยําเกรงพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 5, 'ข้าพเจ้าคอยพระเยโฮวาห์ จิตใจของข้าพเจ้าคอยอยู่ และข้าพเจ้าหวังในพระวจนะของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 6, 'จิตใจของข้าพเจ้าคอยองค์พระผู้เป็นเจ้ายิ่งกว่าคนยามคอยเวลารุ่งเช้า ข้าพเจ้ากล่าวว่า ยิ่งกว่าคนยามคอยเวลารุ่งเช้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 7, 'จงให้อิสราเอลหวังใจในพระเยโฮวาห์ เพราะในพระเยโฮวาห์มีความเมตตา และในพระองค์มีการไถ่อย่างสมบูรณ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 8, 'และพระองค์จะทรงไถ่อิสราเอลจากความชั่วช้าทั้งสิ้นของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 1, 'บทเพลงใช้แห่ขึ้นของดาวิดข้าแต่พระเยโฮวาห์ จิตใจของข้าพระองค์มิได้เห่อเหิม และนัยน์ตาของข้าพระองค์มิได้ยโส ข้าพระองค์มิได้ไปยุ่งกับเรื่องใหญ่โต หรือเรื่องมหัศจรรย์เกินตัวของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 2, 'แต่ข้าพระองค์ได้สงบและระงับจิตใจของข้าพระองค์ อย่างเด็กที่หย่านมมารดาของตนแล้ว จิตใจของข้าพระองค์เหมือนอย่างเด็กที่หย่านมแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 3, 'จงให้อิสราเอลหวังใจในพระเยโฮวาห์ตั้งแต่กาลบัดนี้สืบไปเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 1, 'บทเพลงใช้แห่ขึ้นข้าแต่พระเยโฮวาห์ ขอทรงระลึกถึงดาวิดและความลําบากยากเข็ญทั้งสิ้นของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 2, 'ว่า ท่านได้ปฏิญาณต่อพระเยโฮวาห์อย่างไร และได้ปฏิญาณตัวไว้ต่อองค์ผู้ทรงมหิทธิฤทธิ์ของยาโคบว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 3, '“แน่นอนข้าพระองค์จะไม่เข้าตัวบ้านหรือขึ้นไปนอนบนที่นอนของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 4, 'ข้าพระองค์จะไม่ให้นัยน์ตาของข้าพระองค์หลับ หรือให้หนังตาเคลิ้มไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 5, 'จนกว่าข้าพระองค์จะหาสถานที่สําหรับพระเยโฮวาห์ได้ คือที่ประทับของพระเจ้าผู้ทรงมหิทธิฤทธิ์ของยาโคบ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 6, 'ดูเถิด เราได้ยินเรื่องนี้ในเอฟราธาห์ เราได้พบสิ่งนี้ในทุ่งแห่งป่าไม้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 7, '“เราจะไปยังที่ประทับของพระองค์ เราจะนมัสการที่รองพระบาทของพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 8, 'โอ ข้าแต่พระเยโฮวาห์ ขอทรงลุกขึ้นเสด็จไปยังที่พํานักของพระองค์ ทั้งพระองค์และหีบแห่งอานุภาพของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 9, 'ขอปุโรหิตของพระองค์สวมความชอบธรรม และให้วิสุทธิชนของพระองค์โห่ร้องด้วยความชื่นบาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 10, 'เพราะเห็นแก่ดาวิดผู้รับใช้ของพระองค์ ขออย่าทรงเมินพระพักตร์หนีจากผู้ที่พระองค์ทรงเจิมไว้นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 11, 'พระเยโฮวาห์ทรงปฏิญาณเป็นความจริงกับดาวิด ซึ่งพระองค์จะไม่ทรงหันกลับคือว่า “เราจะตั้งผลจากตัวของเจ้าไว้บนบัลลังก์ของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 12, 'ถ้าบรรดาบุตรของเจ้ารักษาพันธสัญญาของเรา และบรรดาพระโอวาทของเราซึ่งเราจะสอนเขา เหล่าบุตรของเขาทั้งหลายด้วยเช่นกันจะนั่งบนบัลลังก์ของเจ้าเป็นนิตย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 13, 'เพราะพระเยโฮวาห์ทรงเลือกศิโยน พระองค์มีพระประสงค์จะให้เป็นที่ประทับของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 14, 'ตรัสว่า “นี่เป็นที่พํานักของเราเป็นนิตย์ เราจะอยู่ที่นี่ เพราะปรารถนาเช่นนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 15, 'เราจะอํานวยพรอย่างมากมายแก่เสบียงของเมืองนี้ เราจะให้คนจนของเมืองนี้อิ่มด้วยขนมปัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 16, 'เราจะเอาความรอดห่มปุโรหิตของเมืองนั้น และวิสุทธิชนของเมืองนั้นจะโห่ร้องด้วยความชื่นบาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 17, 'ณ ที่นั้นเราจะกระทําให้มีเขาหนึ่งงอกขึ้นมาสําหรับดาวิด เราได้เตรียมประทีปดวงหนึ่งสําหรับผู้รับเจิมของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 18, 'เราจะเอาความอายห่มศัตรูของท่าน แต่มงกุฎของท่านจะรุ่งเรืองอยู่บนท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 1, 'บทเพลงใช้แห่ขึ้นของดาวิดดูเถิด ซึ่งพี่น้องอาศัยอยู่ด้วยกันเป็นน้ําหนึ่งใจเดียวกัน ก็เป็นการดีและน่าชื่นใจมากสักเท่าใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 2, 'เหมือนน้ํามันประเสริฐอยู่บนศีรษะไหลอาบลงมาบนหนวดเครา บนหนวดเคราของอาโรน ไหลอาบลงมาบนคอเสื้อของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 3, 'เหมือนน้ําค้างของภูเขาเฮอร์โมน เหมือนน้ําค้างซึ่งตกลงบนเทือกเขาศิโยน เพราะว่าพระเยโฮวาห์ทรงบังคับบัญชาพระพรที่นั่น คือชีวิตจําเริญเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 1, 'บทเพลงใช้แห่ขึ้นมาเถิด มาถวายสาธุการแด่พระเยโฮวาห์ บรรดาท่านผู้รับใช้ทั้งสิ้นของพระเยโฮวาห์ ผู้ยืนอยู่ในพระนิเวศของพระเยโฮวาห์ในกลางคืน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 2, 'จงยกมือของท่านขึ้นในสถานบริสุทธิ์ และถวายสาธุการแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 3, 'ขอพระเยโฮวาห์ทรงอํานวยพระพรท่านจากศิโยน คือพระองค์ผู้ทรงสร้างฟ้าสวรรค์และแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 1, 'จงสรรเสริญพระเยโฮวาห์เถิด จงสรรเสริญพระนามของพระเยโฮวาห์ โอ บรรดาผู้รับใช้ของพระเยโฮวาห์เอ๋ย จงสรรเสริญพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 2, 'ท่านที่ยืนอยู่ในพระนิเวศของพระเยโฮวาห์ ที่ในบริเวณพระนิเวศของพระเจ้าของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 3, 'จงสรรเสริญพระเยโฮวาห์ เพราะพระเยโฮวาห์ประเสริฐ จงร้องเพลงสรรเสริญพระนามของพระองค์ เพราะการกระทํานั้นเพลิดเพลิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 4, 'เพราะพระเยโฮวาห์ทรงเลือกยาโคบไว้สําหรับพระองค์เอง เลือกอิสราเอลไว้เป็นกรรมสิทธิ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 5, 'เพราะข้าพเจ้าทราบว่าพระเยโฮวาห์ใหญ่ยิ่ง และองค์พระผู้เป็นเจ้าของเราใหญ่ยิ่งกว่าพระอื่นทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 6, 'พระเยโฮวาห์พอพระทัยสิ่งใด พระองค์ก็ทรงกระทําในฟ้าสวรรค์และบนแผ่นดินโลก ในทะเลและที่น้ําลึกทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 7, 'พระองค์ทรงกระทําให้เมฆลอยขึ้นมาจากที่สุดปลายแผ่นดินโลก พระองค์ทรงกระทําฟ้าแลบให้แก่ฝนและทรงนําลมออกมาจากคลังของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 8, 'พระองค์คือผู้ทรงสังหารลูกหัวปีของอียิปต์ ทั้งของคนและของสัตว์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 9, 'โอ อียิปต์เอ๋ย ผู้ทรงให้หมายสําคัญและการมหัศจรรย์ท่ามกลางเจ้า ให้ต่อสู้กับฟาโรห์และบรรดาข้าราชการของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 10, 'พระองค์คือผู้ทรงตีประชาชาติใหญ่โต และทรงสังหารกษัตริย์ผู้ทรงฤทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 11, 'คือสิโหนกษัตริย์ของคนอาโมไรต์ และโอกกษัตริย์ของเมืองบาชาน และบรรดาราชอาณาจักรแห่งคานาอัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 12, 'และประทานแผ่นดินของเขาทั้งหลายให้เป็นมรดก เป็นมรดกแก่อิสราเอลประชาชนของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 13, 'โอ ข้าแต่พระเยโฮวาห์ พระนามของพระองค์ดํารงเป็นนิตย์ โอ ข้าแต่พระเยโฮวาห์ ความระลึกถึงพระองค์ดํารงอยู่ทุกชั่วอายุ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 14, 'เพราะพระเยโฮวาห์จะทรงแก้แทนประชาชนของพระองค์ และทรงกลับพระทัยในเรื่องบรรดาผู้รับใช้ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 15, 'รูปเคารพของบรรดาประชาชาติเป็นเงินและทองคํา เป็นหัตถกรรมของมนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 16, 'รูปเหล่านั้นมีปาก แต่พูดไม่ได้ มีตา แต่ดูไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 17, 'มีหู แต่ฟังไม่ได้ยิน ทั้งไม่มีลมหายใจในปากของรูปนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 18, 'ผู้ที่ทํารูปนั้นเหมือนรูปเหล่านั้น เออ บรรดาผู้ที่วางใจในรูปนั้นก็เช่นกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 19, 'โอ วงศ์วานอิสราเอลเอ๋ย จงถวายสาธุการแด่พระเยโฮวาห์ โอ วงศ์วานอาโรนเอ๋ย จงถวายสาธุการแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 20, 'โอ วงศ์วานเลวีเอ๋ย จงถวายสาธุการแด่พระเยโฮวาห์ ท่านที่ยําเกรงพระเยโฮวาห์ จงถวายสาธุการแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 21, 'สาธุการแด่พระเยโฮวาห์จากศิโยน พระองค์ผู้ทรงพํานักอยู่ในเยรูซาเล็ม จงสรรเสริญพระเยโฮวาห์เถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 1, 'โอ จงโมทนาขอบพระคุณพระเยโฮวาห์ เพราะพระองค์ทรงประเสริฐ เพราะความเมตตาของพระองค์ดํารงเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 2, 'โอ จงโมทนาขอบพระคุณพระเจ้าผู้เหนือพระทั้งหลาย เพราะความเมตตาของพระองค์ดํารงเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 3, 'โอ จงโมทนาขอบพระคุณถวายแด่พระองค์ ผู้เป็นเจ้าเหนือเจ้าทั้งหลาย เพราะความเมตตาของพระองค์ดํารงเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 4, 'ถวายแด่พระองค์ ผู้ทรงกระทําการมหัศจรรย์ยิ่งใหญ่แต่องค์เดียว เพราะความเมตตาของพระองค์ดํารงเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 5, 'ถวายแด่พระองค์ ผู้ทรงสร้างฟ้าสวรรค์ด้วยพระสติปัญญา เพราะความเมตตาของพระองค์ดํารงเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 6, 'ถวายแด่พระองค์ ผู้ทรงกางแผ่นดินโลกออกเหนือน้ําทั้งหลาย เพราะความเมตตาของพระองค์ดํารงเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 7, 'ถวายแด่พระองค์ ผู้ทรงสร้างดวงสว่างใหญ่ๆ เพราะความเมตตาของพระองค์ดํารงเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 8, 'สร้างดวงอาทิตย์ให้ครองกลางวัน เพราะความเมตตาของพระองค์ดํารงเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 9, 'ดวงจันทร์และดาวทั้งหลายให้ครองกลางคืน เพราะความเมตตาของพระองค์ดํารงเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 10, 'ถวายแด่พระองค์ ผู้ทรงตีอียิปต์ทางบรรดาลูกหัวปี เพราะความเมตตาของพระองค์ดํารงเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 11, 'และทรงนําอิสราเอลออกมาจากท่ามกลางเขา เพราะความเมตตาของพระองค์ดํารงเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 12, 'ด้วยพระหัตถ์เข้มแข็งและพระกรที่เหยียดออก เพราะความเมตตาของพระองค์ดํารงเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 13, 'ถวายแด่พระองค์ ผู้ทรงแยกทะเลแดงออกจากกัน เพราะความเมตตาของพระองค์ดํารงเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 14, 'และทรงให้อิสราเอลผ่านไปท่ามกลางทะเลนั้น เพราะความเมตตาของพระองค์ดํารงเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 15, 'แต่ทรงคว่ําฟาโรห์และกองทัพของท่านเสียในทะเลแดง เพราะความเมตตาของพระองค์ดํารงเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 16, 'ถวายแด่พระองค์ ผู้ทรงนําประชาชนของพระองค์ไปในถิ่นทุรกันดาร เพราะความเมตตาของพระองค์ดํารงเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 17, 'ถวายแด่พระองค์ ผู้ทรงตีพระมหากษัตริย์ทั้งหลาย เพราะความเมตตาของพระองค์ดํารงเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 18, 'และทรงสังหารเหล่ากษัตริย์ผู้มีชื่อเสียง เพราะความเมตตาของพระองค์ดํารงเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 19, 'มีสิโหนกษัตริย์ของคนอาโมไรต์ เพราะความเมตตาของพระองค์ดํารงเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 20, 'และโอกกษัตริย์แห่งเมืองบาชาน เพราะความเมตตาของพระองค์ดํารงเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 21, 'และประทานแผ่นดินของเขาให้เป็นมรดก เพราะความเมตตาของพระองค์ดํารงเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 22, 'ให้เป็นมรดกแก่อิสราเอลผู้รับใช้ของพระองค์ เพราะความเมตตาของพระองค์ดํารงเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 23, 'คือพระองค์นี่เอง ผู้ทรงระลึกถึงเราในฐานะต่ําต้อยของเรา เพราะความเมตตาของพระองค์ดํารงเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 24, 'และทรงไถ่เราให้พ้นจากศัตรูของเรา เพราะความเมตตาของพระองค์ดํารงเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 25, 'พระองค์ผู้ประทานอาหารแก่เนื้อหนังทั้งปวง เพราะความเมตตาของพระองค์ดํารงเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 26, 'โอ จงโมทนาขอบพระคุณพระเจ้าแห่งฟ้าสวรรค์ เพราะความเมตตาของพระองค์ดํารงเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 1, 'ณ ริมฝั่งแม่น้ําแห่งบาบิโลนเรานั่งลง เมื่อได้ระลึกถึงศิโยนเราก็ร่ําไห้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 2, 'ในท่ามกลางที่นั่นเราแขวนพิณเขาคู่ของเราไว้ที่ต้นหลิว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 3, 'เพราะที่นั่นผู้ที่นําเราไปเป็นเชลยต้องการให้เราร้องเพลง และผู้ที่ปล้นเราต้องการให้สนุกสนาน เขาว่า “จงร้องเพลงศิโยนสักบทหนึ่งให้เราฟัง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 4, 'เราจะร้องเพลงของพระเยโฮวาห์ได้อย่างไร ที่ในแผ่นดินต่างด้าว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 5, 'โอ เยรูซาเล็มเอ๋ย ถ้าข้าพเจ้าลืมเธอก็ขอให้มือขวาของข้าพเจ้าลืมฝีมือเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 6, 'ขอให้ลิ้นของข้าพเจ้าเกาะติดเพดานปากของข้าพเจ้า ถ้าว่าข้าพเจ้าไม่ระลึกถึงเธอ ถ้าว่าข้าพเจ้ามิได้ตั้งเยรูซาเล็มไว้เหนือความชื่นบานอันสูงที่สุดของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 7, 'โอ ข้าแต่พระเยโฮวาห์ ในวันแห่งเยรูซาเล็มขอทรงระลึกถึงคนเอโดม ผู้ที่พูดว่า “จงทลายเสีย จงทลายเสีย ลงไปจนถึงรากฐานของมัน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 8, 'โอ ธิดาแห่งบาบิโลนเอ๋ย ซึ่งจะต้องล้างผลาญเสีย ความสุขจงมีแก่ผู้ที่สนองเจ้าให้สมกับที่เจ้าได้กระทํากับเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 9, 'ความสุขจงมีแก่ผู้ที่เอาลูกเล็กเด็กแดงของเจ้าเหวี่ยงกระแทกลงกับก้อนหิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 1, 'เพลงสดุดีของดาวิดข้าพระองค์จะสรรเสริญพระองค์ด้วยสิ้นสุดใจของข้าพระองค์ ข้าพระองค์จะร้องเพลงสรรเสริญถวายพระองค์ต่อหน้าบรรดาพระทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 2, 'ข้าพระองค์กราบลงตรงมายังพระวิหารอันบริสุทธิ์ของพระองค์ และสรรเสริญพระนามของพระองค์ เพราะความเมตตาและความจริงของพระองค์ เพราะพระองค์ทรงเชิดชูพระวจนะของพระองค์เหนือพระนามทั้งหลายของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 3, 'ในวันที่ข้าพระองค์ร้องทูล พระองค์ได้ทรงตอบข้าพระองค์ พระองค์ทรงเพิ่มกําลังจิตใจของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 4, 'โอ ข้าแต่พระเยโฮวาห์ บรรดากษัตริย์แห่งแผ่นดินโลกจะสรรเสริญพระองค์ เมื่อท่านเหล่านั้นได้ยินพระวจนะแห่งพระโอษฐ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 5, 'และท่านเหล่านั้นจะร้องเพลงถึงพระมรรคาของพระเยโฮวาห์ เพราะสง่าราศีของพระเยโฮวาห์นั้นใหญ่หลวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 6, 'ถึงแม้พระเยโฮวาห์นั้นสูงยิ่ง พระองค์ก็ทรงเห็นแก่คนถ่อมตัวลง แต่พระองค์ทรงทราบคนโอหังได้แต่ไกล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 7, 'แม้ข้าพระองค์เดินอยู่กลางความลําบากยากเย็น พระองค์จะทรงสงวนชีวิตข้าพระองค์ไว้ พระองค์จะทรงเหยียดพระหัตถ์ของพระองค์ออกต่อต้านความโกรธของศัตรูของข้าพระองค์ และพระหัตถ์ขวาของพระองค์จะทรงช่วยข้าพระองค์ให้รอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 8, 'พระเยโฮวาห์จะทรงให้สําเร็จพระประสงค์ของพระองค์แก่ข้าพระองค์ โอ ข้าแต่พระเยโฮวาห์ ความเมตตาของพระองค์ดํารงเป็นนิตย์ ขออย่าทรงละทิ้งพระหัตถกิจของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 1, 'ถึงหัวหน้านักร้อง เพลงสดุดีของดาวิดโอ ข้าแต่พระเยโฮวาห์ พระองค์ได้ทรงตรวจสอบข้าพระองค์และทรงรู้จักข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 2, 'เมื่อข้าพระองค์นั่งลงและลุกขึ้น พระองค์ทรงทราบ พระองค์ทรงประจักษ์ในความคิดของข้าพระองค์ได้แต่ไกล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 3, 'พระองค์ทรงค้นวิถีของข้าพระองค์และการนอนของข้าพระองค์ และทรงคุ้นเคยกับทางทั้งสิ้นของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 4, 'โอ ข้าแต่พระเยโฮวาห์ แม้ก่อนที่ลิ้นของข้าพระองค์จะพูด ดูเถิด พระองค์ก็ทรงทราบความเสียหมดแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 5, 'พระองค์ทรงล้อมข้าพระองค์อยู่ทั้งข้างหลังและข้างหน้า และทรงวางพระหัตถ์บนข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 6, 'ความรู้อย่างนี้มหัศจรรย์เกินข้าพระองค์ สูงนัก ข้าพระองค์เอื้อมไม่ถึง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 7, 'ข้าพระองค์จะไปไหนให้พ้นพระวิญญาณของพระองค์ได้ หรือข้าพระองค์จะหนีไปไหนให้พ้นพระพักตร์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 8, 'ถ้าข้าพระองค์ขึ้นไปยังสวรรค์ พระองค์ทรงสถิตที่นั่น ถ้าข้าพระองค์จะทําที่นอนไว้ในนรก ดูเถิด พระองค์ทรงสถิตที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 9, 'ถ้าข้าพระองค์จะติดปีกแสงอรุณ และอาศัยอยู่ที่ส่วนของทะเลไกลโพ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 10, 'แม้ถึงที่นั่น พระหัตถ์ของพระองค์จะนําข้าพระองค์ และพระหัตถ์ขวาของพระองค์จะยึดข้าพระองค์ไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 11, 'ถ้าข้าพระองค์จะว่า “แน่นอนความมืดจะปกคลุมข้าไว้และแม้กลางคืนก็จะเป็นความสว่างอยู่รอบข้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 12, 'สําหรับพระองค์ แม้ความมืดก็มิได้ซ่อนอะไรไว้จากพระองค์ กลางคืนก็แจ้งอย่างกลางวัน ความมืดเป็นอย่างความสว่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 13, 'เพราะพระองค์ทรงปั้นส่วนภายในของข้าพระองค์ พระองค์ทรงทอข้าพระองค์เข้าด้วยกันในครรภ์มารดาของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 14, 'ข้าพระองค์จะสรรเสริญพระองค์ เพราะข้าพระองค์ถูกสร้างมาอย่างแปลกประหลาดและน่ากลัว พระราชกิจของพระองค์มหัศจรรย์ จิตใจข้าพระองค์ทราบเรื่องนี้อย่างดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 15, 'เมื่อข้าพระองค์ถูกสร้างอยู่ในที่ลับลี้ ประดิษฐ์ขึ้นมา ณ ภายในที่ลึกแห่งโลก โครงร่างของข้าพระองค์ไม่ปิดบังไว้จากพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 16, 'พระเนตรของพระองค์ทรงเห็นส่วนประกอบของข้าพระองค์ในเมื่อยังไม่สมบูรณ์ ในวันทั้งหลายที่กําลังประกอบขึ้น เมื่อครั้งไม่เกิดขึ้น อวัยวะทั้งหลายของข้าพระองค์ก็ทรงจารึกไว้ในพระตํารับของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 17, 'โอ ข้าแต่พระเจ้า พระดําริของพระองค์ประเสริฐแก่ข้าพระองค์จริงๆ รวมกันเข้าก็ไพศาลนักหนา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 18, 'ถ้าข้าพระองค์จะนับก็มากกว่าเม็ดทราย เมื่อข้าพระองค์ตื่นขึ้น ข้าพระองค์ก็ยังอยู่กับพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 19, 'โอ ข้าแต่พระเจ้า แน่นอนพระองค์จะทรงสังหารคนชั่วเสีย ดังนั้น คนกระหายเลือดเอ๋ย จงพรากไปจากข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 20, 'เพราะพวกเขากล่าวต่อต้านพระองค์ด้วยมุ่งร้าย และพวกศัตรูของพระองค์ใช้พระนามของพระองค์อย่างไร้ประโยชน์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 21, 'โอ ข้าแต่พระเยโฮวาห์ ข้าพระองค์มิได้เกลียดผู้ที่เกลียดพระองค์หรือ และข้าพระองค์มิได้สะอิดสะเอียนคนเหล่านั้นผู้ลุกขึ้นต่อสู้พระองค์ดอกหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 22, 'ข้าพระองค์เกลียดเขาด้วยความเกลียดอย่างที่สุด และนับเขาเป็นศัตรูของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 23, 'โอ ข้าแต่พระเจ้า ขอทรงค้นดูข้าพระองค์ และทรงทราบจิตใจของข้าพระองค์ ขอทรงลองข้าพระองค์ และทรงทราบความคิดของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 24, 'และทอดพระเนตรว่ามีทางชั่วใดๆในข้าพระองค์หรือไม่ และขอทรงนําข้าพระองค์ไปในมรรคานิรันดร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 1, 'ถึงหัวหน้านักร้อง เพลงสดุดีของดาวิดโอ ข้าแต่พระเยโฮวาห์ ขอทรงช่วยข้าพระองค์ให้พ้นจากคนชั่วร้าย ขอทรงสงวนข้าพระองค์ไว้จากคนทารุณ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 2, 'ผู้คิดปองร้ายอยู่ในจิตใจของเขา และก่อกวนต่อเนื่องกันให้มีสงครามขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 3, 'เขาทําลิ้นของเขาให้คมเหมือนลิ้นงู และภายใต้ริมฝีปากของเขามีพิษของงูพิษ เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 4, 'โอ ข้าแต่พระเยโฮวาห์ ขอทรงรักษาข้าพระองค์ไว้ให้พ้นจากมือของคนชั่ว ขอทรงสงวนข้าพระองค์ไว้จากคนทารุณ ผู้คิดแผนการพลิกเท้าของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 5, 'คนโอหังได้ซ่อนกับดักข้าพระองค์และวางบ่วงไว้ ที่ข้างทางเขากางตาข่าย เขาตั้งบ่วงแร้วดักข้าพระองค์ เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 6, 'ข้าพเจ้าทูลพระเยโฮวาห์ว่า “พระองค์ทรงเป็นพระเจ้าของข้าพระองค์ โอ ข้าแต่พระเยโฮวาห์ ขอทรงฟังเสียงทูลวิงวอนของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 7, 'โอ ข้าแต่พระเจ้าคือองค์พระผู้เป็นเจ้า ผู้ทรงเป็นกําลังแห่งความรอดของข้าพระองค์ พระองค์ทรงคลุมศีรษะข้าพระองค์ไว้ในยามศึก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 8, 'โอ ข้าแต่พระเยโฮวาห์ ขออย่าทรงอนุมัติตามความปรารถนาของคนชั่ว อย่าให้การคิดปองร้ายของเขาคืบหน้าไป เกลือกว่าเขาจะยกตัวขึ้น เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 9, 'ฝ่ายศีรษะของคนที่ล้อมข้าพระองค์ไว้นั้น ขอให้ความสาระแนแห่งริมฝีปากของเขาท่วมเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 10, 'ขอให้ถ่านที่ลุกอยู่ตกใส่เขา ขอให้เขาถูกทิ้งในไฟลงไปในบ่อ ไม่ให้ลุกขึ้นมาอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 11, 'ขออย่าให้เขาตั้งคนส่อเสียดไว้ในแผ่นดิน ขอให้ความร้ายล่าคนทารุณจนคว่ําเขาได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 12, 'ข้าพเจ้าทราบว่าพระเยโฮวาห์จะทรงกระทําความเที่ยงธรรมให้แก่ผู้ที่ทุกข์ยาก และทรงจัดความยุติธรรมให้แก่คนขัดสน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 13, 'แน่นอนทีเดียว ที่คนชอบธรรมจะถวายโมทนาขอบพระคุณพระนามของพระองค์ คนเที่ยงธรรมจะอาศัยอยู่ต่อเบื้องพระพักตร์พระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 1, 'เพลงสดุดีของดาวิดข้าแต่พระเยโฮวาห์ ข้าพระองค์ร้องทูลต่อพระองค์ ขอทรงรีบตอบข้าพระองค์ ขอทรงเงี่ยพระกรรณสดับเสียงข้าพระองค์ เมื่อข้าพระองค์ร้องทูลพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 2, 'ขอให้คําอธิษฐานของข้าพระองค์เป็นดังเครื่องหอมต่อพระพักตร์พระองค์ และที่ข้าพระองค์ยกมือขึ้นเป็นดังเครื่องสัตวบูชาเวลาเย็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 3, 'โอ ข้าแต่พระเยโฮวาห์ ขอทรงตั้งยามเฝ้าปากของข้าพระองค์ ขอรักษาประตูริมฝีปากของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 4, 'ขออย่าให้จิตใจข้าพระองค์เอนเอียงไปหาความชั่วใดๆ หรือให้ข้าพระองค์สาละวนอยู่กับการชั่วร้ายร่วมกับคนที่ทําความชั่วช้า และขออย่าให้ข้าพระองค์กินของโอชะของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 5, 'ขอให้คนชอบธรรมตีข้าพระองค์ จะเป็นความเมตตาแก่ข้าพระองค์ ขอให้เขาติเตียนข้าพระองค์ จะเป็นน้ํามันดีเลิศซึ่งจะไม่ให้ศีรษะข้าพระองค์แตก เพราะข้าพระองค์ยังอธิษฐานต่อสู้ความชั่วของเขาทั้งหลายอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 6, 'เมื่อผู้พิพากษาทั้งหลายของเขาถูกโยนลงที่หน้าผา เขาจะได้ยินถ้อยคําของข้าพระองค์ เพราะเป็นถ้อยคําไพเราะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 7, 'กระดูกของเราทั้งหลายกระจายที่ปากแดนผู้ตายฉันใด เหมือนเมื่อคนหนึ่งตัดและผ่าไม้อยู่บนแผ่นดินฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 8, 'โอ ข้าแต่พระเจ้าคือองค์พระผู้เป็นเจ้า ตาของข้าพระองค์เพ่งตรงพระองค์ ข้าพระองค์วางใจในพระองค์ ขออย่าให้จิตใจข้าพระองค์ไร้คุณธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 9, 'ขอพระองค์ทรงรักษาข้าพระองค์ให้พ้นจากกับซึ่งเขาวางดักข้าพระองค์ไว้ และจากบ่วงแร้วของผู้กระทําความชั่วช้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 10, 'ขอให้คนชั่วตกไปด้วยกันในข่ายของตนเอง แต่ขอให้ข้าพระองค์ผ่านพ้นไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 1, 'มัสคิลบทหนึ่งของดาวิด คําอธิษฐานเมื่อท่านอยู่ในถ้ําข้าพเจ้าร้องทูลพระเยโฮวาห์ด้วยเสียงของข้าพเจ้า ด้วยเสียงของข้าพเจ้า ข้าพเจ้าวิงวอนต่อพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 2, 'ข้าพเจ้าหลั่งคําคร่ําครวญของข้าพเจ้าออกมาต่อเบื้องพระพักตร์พระองค์ ข้าพเจ้าทูลเรื่องความลําบากยากเย็นของข้าพเจ้าต่อพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 3, 'เมื่อจิตใจของข้าพระองค์อ่อนระอาภายใน พระองค์ทรงทราบทางของข้าพระองค์ ในวิถีที่ข้าพระองค์เดินไปเขาซ่อนกับไว้ดักข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 4, 'ข้าพระองค์มองทางขวามือและมองดู แต่ไม่มีใครยอมรู้จักข้าพระองค์ ข้าพระองค์ไม่มีที่หลบภัย ไม่มีใครเอาใจใส่จิตใจข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 5, 'โอ ข้าแต่พระเยโฮวาห์ ข้าพระองค์ร้องทูลต่อพระองค์ ข้าพระองค์ว่า “พระองค์ทรงเป็นที่ลี้ภัยของข้าพระองค์ เป็นส่วนของข้าพระองค์ในแผ่นดินของคนเป็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 6, 'ขอทรงฟังคําร้องทูลของข้าพระองค์ เพราะข้าพระองค์ตกต่ํามากนัก ขอทรงช่วยข้าพระองค์ให้พ้นจากผู้ข่มเหงข้าพระองค์ เพราะเขาแข็งแรงเกินกําลังข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 7, 'ขอทรงพาจิตใจข้าพระองค์ออกจากคุก เพื่อข้าพระองค์จะสรรเสริญพระนามของพระองค์ คนชอบธรรมจะล้อมข้าพระองค์ไว้เพราะพระองค์จะทรงกระทําแก่ข้าพระองค์อย่างบริบูรณ์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 1, 'เพลงสดุดีของดาวิดโอ ข้าแต่พระเยโฮวาห์ ขอทรงสดับคําอธิษฐานของข้าพระองค์ ขอทรงเงี่ยพระกรรณสดับคําวิงวอนของข้าพระองค์ ขอทรงตอบข้าพระองค์ตามความสัตย์สุจริตของพระองค์ ตามความชอบธรรมของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 2, 'ขออย่าทรงตัดสินผู้รับใช้ของพระองค์ เพราะไม่มีคนเป็นคนใดที่ชอบธรรมในสายพระเนตรของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 3, 'เพราะศัตรูข่มเหงจิตใจข้าพระองค์ มันขยี้ชีวิตข้าพระองค์ลงถึงดิน มันได้กระทําให้ข้าพระองค์อาศัยในที่มืด เหมือนคนที่ตายนานแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 4, 'เพราะฉะนั้นจิตวิญญาณของข้าพระองค์จึงอ่อนระอาอยู่ในข้าพระองค์ จิตใจภายในข้าพระองค์ก็อ้างว้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 5, 'ข้าพระองค์ระลึกถึงสมัยเก่าก่อนได้ ข้าพระองค์คิดคํานึงถึงทุกสิ่งที่พระองค์ทรงกระทํา ข้าพระองค์รําพึงถึงพระหัตถกิจของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 6, 'ข้าพระองค์เหยียดมือออกไปสู่พระองค์ จิตใจของข้าพระองค์กระหายหาพระองค์อย่างแผ่นดินที่แห้งผาก เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 7, 'โอ ข้าแต่พระเยโฮวาห์ ขอทรงรีบฟังข้าพระองค์ จิตวิญญาณข้าพระองค์ฝ่อไปแล้ว ขออย่าทรงซ่อนพระพักตร์ของพระองค์ไว้จากข้าพระองค์ เกรงว่าข้าพระองค์จะเหมือนคนเหล่านั้นที่ลงไปยังปากแดนผู้ตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 8, 'ขอทรงโปรดให้ข้าพระองค์ได้ยินถึงความเมตตาของพระองค์ในเวลาเช้า เพราะข้าพระองค์วางใจในพระองค์ ขอทรงสอนข้าพระองค์ถึงทางที่ควรดําเนินไป เพราะข้าพระองค์ตั้งใจแน่วแน่ในพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 9, 'โอ ข้าแต่พระเยโฮวาห์ ขอทรงช่วยข้าพระองค์ให้พ้นจากศัตรูของข้าพระองค์ ข้าพระองค์ได้ซ่อนตัวอยู่กับพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 10, 'ขอทรงสอนให้ข้าพระองค์ทําตามพระทัยของพระองค์ เพราะพระองค์ทรงเป็นพระเจ้าของข้าพระองค์ พระวิญญาณของพระองค์ประเสริฐ ขอทรงนําข้าพระองค์เข้าไปยังแผ่นดินแห่งความเที่ยงธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 11, 'โอ ข้าแต่พระเยโฮวาห์ ขอทรงสงวนชีวิตข้าพระองค์ไว้ เพราะเห็นแก่พระนามของพระองค์ ขอทรงนําจิตใจข้าพระองค์ออกมาจากความยากลําบากเพราะเห็นแก่ความชอบธรรมของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 12, 'และขอทรงตัดศัตรูของข้าพระองค์ออกไปตามความเมตตาของพระองค์ และขอทรงทําลายบรรดาผู้ที่ทรมานจิตใจข้าพระองค์ เพราะข้าพระองค์เป็นผู้รับใช้ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 1, 'เพลงสดุดีของดาวิดสาธุการแด่พระเยโฮวาห์ กําลังของข้าพระองค์ ผู้ทรงฝึกมือของข้าพระองค์ให้ทําสงคราม และนิ้วมือของข้าพระองค์ให้ทําศึก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 2, 'ทรงเป็นความดีและป้อมปราการของข้าพระองค์ เป็นที่กําบังเข้มแข็ง และเป็นผู้ช่วยให้พ้นของข้าพระองค์ เป็นโล่ของข้าพระองค์ และเป็นผู้ซึ่งข้าพระองค์วางใจอยู่ ผู้ทรงปราบชนชาติทั้งหลายไว้ใต้ข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 3, 'ข้าแต่พระเยโฮวาห์ มนุษย์เป็นอะไรเล่าซึ่งพระองค์ทรงเอาพระทัยใส่เขา หรือบุตรของมนุษย์เป็นอะไรซึ่งพระองค์ทรงคิดถึงเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 4, 'มนุษย์เหมือนสิ่งไร้สาระ วันเวลาของเขาเหมือนเงาที่ผ่านไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 5, 'โอ ข้าแต่พระเยโฮวาห์ ขอทรงโน้มฟ้าสวรรค์ของพระองค์ และขอเสด็จลงมาแตะต้องภูเขาเพื่อให้มันมีควันขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 6, 'ขอทรงพุ่งฟ้าผ่าออกมาและกระจายเขาไป ขอทรงยิงลูกธนูของพระองค์และทรงทําลายพวกเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 7, 'ขอทรงเหยียดพระหัตถ์ของพระองค์จากที่สูง ขอทรงช่วยเหลือข้าพระองค์ และช่วยข้าพระองค์ให้พ้นจากน้ํามากหลาย ให้พ้นจากมือของชนต่างด้าว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 8, 'ผู้ซึ่งปากของเขาพูดเรื่องไร้สาระและซึ่งมือขวาของเขาเป็นมือขวาแห่งความมุสา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 9, 'โอ ข้าแต่พระเจ้า ข้าพระองค์จะร้องเพลงบทใหม่ถวายแด่พระองค์ ข้าพระองค์จะร้องเพลงสรรเสริญพระองค์ด้วยพิณใหญ่และพิณสิบสาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 10, 'พระองค์ทรงเป็นผู้ประทานความรอดแก่บรรดากษัตริย์ ผู้ทรงช่วยดาวิดผู้รับใช้ของพระองค์ให้พ้นจากดาบที่นํามาซึ่งความเจ็บปวด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 11, 'ขอทรงช่วยเหลือข้าพระองค์ และขอทรงช่วยข้าพระองค์ให้พ้นจากมือคนต่างด้าว ผู้ซึ่งปากของเขาพูดเรื่องไร้สาระและซึ่งมือขวาของเขาเป็นมือขวาแห่งความมุสา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 12, 'เพื่อบรรดาบุตรชายของข้าพระองค์ทั้งหลายเมื่อเขายังหนุ่มๆอยู่จะเป็นเหมือนต้นไม้โตเต็มขนาด เพื่อบรรดาบุตรสาวของข้าพระองค์ทั้งหลายจะเป็นเหมือนเสาหัวมุม สลักออกมาตามแบบพระราชวัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 13, 'เพื่อยุ้งฉางของข้าพระองค์ทั้งหลายจะเต็ม มีของบรรจุอยู่ทุกอย่าง เพื่อแกะของข้าพระองค์ทั้งหลายมีลูกตั้งพันตั้งหมื่นตามถนนของข้าพระองค์ทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 14, 'เพื่อวัวตัวผู้ของข้าพระองค์ทั้งหลายมีกําลังใช้แรงงาน เพื่อไม่มีใครพังเข้ามา ไม่มีออกไป เพื่อไม่มีเสียงร้องทุกข์ในถนนหนทางของข้าพระองค์ทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 15, 'ชนชาติผู้มีพระพรอย่างนี้หลั่งลงมาถึงก็เป็นสุข ชนชาติซึ่งพระเจ้าของเขาคือพระเยโฮวาห์ก็เป็นสุข');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 1, 'บทเพลงสรรเสริญของดาวิดข้าแต่พระเจ้าของข้าพระองค์ โอ ข้าแต่พระมหากษัตริย์ ข้าพระองค์จะเยินยอพระองค์ จะถวายสาธุการแด่พระนามของพระองค์เป็นนิจกาล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 2, 'ข้าพระองค์จะถวายสาธุการแด่พระองค์ทุกๆวัน ข้าพระองค์จะสรรเสริญพระนามของพระองค์เป็นนิจกาล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 3, 'พระเยโฮวาห์นั้นยิ่งใหญ่ และสมควรจะสรรเสริญอย่างยิ่ง ความใหญ่ยิ่งของพระองค์นั้นเหลือจะหยั่งรู้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 4, 'คนชั่วอายุหนึ่งจะสรรเสริญพระราชกิจของพระองค์ให้คนอีกชั่วอายุหนึ่งฟัง และจะประกาศกิจการอันทรงอานุภาพของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 5, 'ข้าพระองค์จะกล่าวถึงเกียรติยศอันรุ่งโรจน์ของความสูงส่งของพระองค์ และถึงพระราชกิจมหัศจรรย์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 6, 'มนุษย์จะกล่าวถึงอานุภาพแห่งกิจการอันน่าเกรงขามของพระองค์ และข้าพระองค์จะเล่าถึงความยิ่งใหญ่ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 7, 'เขาทั้งหลายจะโฆษณาข่าวเลื่องลือให้ระลึกถึงคุณความดีอันอุดมของพระองค์ออกมา และจะร้องเพลงถึงความชอบธรรมของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 8, 'พระเยโฮวาห์ทรงพระเมตตาและทรงเต็มไปด้วยพระกรุณา ทรงกริ้วช้าและมีความเมตตาอย่างอุดม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 9, 'พระเยโฮวาห์ทรงดีต่อทุกคน และความเมตตาของพระองค์มีอยู่เหนือพระราชกิจทั้งสิ้นของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 10, 'โอ ข้าแต่พระเยโฮวาห์ พระราชกิจทั้งสิ้นของพระองค์จะสรรเสริญพระองค์ และวิสุทธิชนทั้งสิ้นของพระองค์จะถวายสาธุการแด่พระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 11, 'เขาทั้งหลายจะพูดถึงสง่าราศีแห่งราชอาณาจักรของพระองค์ และเล่าถึงฤทธานุภาพของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 12, 'เพื่อให้กิจการอันทรงอานุภาพของพระองค์ และสง่าราศีอันรุ่งโรจน์แห่งราชอาณาจักรของพระองค์แจ้งแก่บุตรทั้งหลายของมนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 13, 'ราชอาณาจักรของพระองค์เป็นราชอาณาจักรนิรันดร์ และอํานาจการปกครองของพระองค์ดํารงอยู่ตลอดทุกชั่วอายุ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 14, 'พระเยโฮวาห์ทรงชูทุกคนที่กําลังจะล้มลง และทรงยกทุกคนที่โน้มตัวลงให้ลุกขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 15, 'นัยน์ตาทั้งปวงมองดูพระองค์ และพระองค์ประทานอาหารให้ตามเวลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 16, 'พระองค์ทรงยื่นพระหัตถ์ของพระองค์ พระองค์ทรงให้สิ่งสารพัดที่มีชีวิตอิ่มตามความปรารถนา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 17, 'พระเยโฮวาห์ทรงชอบธรรมตามทางทั้งสิ้นของพระองค์ และทรงบริสุทธิ์ในการกระทําทั้งสิ้นของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 18, 'พระเยโฮวาห์ทรงสถิตใกล้ทุกคนที่ร้องทูลพระองค์ ทุกคนที่ร้องทูลพระองค์ตามความจริง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 19, 'พระองค์จะทรงโปรดตามความปรารถนาของบรรดาผู้ที่ยําเกรงพระองค์ พระองค์จะทรงสดับเสียงร้องทูลของเขาด้วย และจะทรงช่วยเขาให้รอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 20, 'พระเยโฮวาห์ทรงสงวนทุกคนที่รักพระองค์ไว้ แต่บรรดาคนชั่ว พระองค์จะทรงทําลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 21, 'ปากของข้าพเจ้าจะกล่าวสรรเสริญพระเยโฮวาห์ และให้บรรดาเนื้อหนังทั้งสิ้นถวายสาธุการแด่พระนามบริสุทธิ์ของพระองค์เป็นนิจกาล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 1, 'จงสรรเสริญพระเยโฮวาห์เถิด โอ จิตใจของข้าพเจ้าเอ๋ย จงสรรเสริญพระเยโฮวาห์เถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 2, 'ข้าพเจ้าจะสรรเสริญพระเยโฮวาห์ตราบเท่าที่ข้าพเจ้ามีชีวิตอยู่ ข้าพเจ้าจะร้องเพลงสรรเสริญพระเจ้าของข้าพเจ้าขณะที่ข้าพเจ้ายังเป็นอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 3, 'อย่าวางใจในเจ้านายหรือในบุตรของมนุษย์ ซึ่งไม่มีความช่วยเหลืออยู่ในตัวเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 4, 'เมื่อลมหายใจของเขาพรากไป เขาก็กลับคืนเป็นดิน ในวันเดียวกันนั้นความคิดของเขาก็พินาศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 5, 'คนที่ผู้อุปถัมภ์ของเขาคือพระเยโฮวาห์ของยาโคบก็เป็นสุข คือผู้ที่ความหวังของเขาอยู่ในพระเยโฮวาห์พระเจ้าของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 6, 'ผู้ได้ทรงสร้างฟ้าสวรรค์และแผ่นดินโลก ทะเลและบรรดาสิ่งของที่อยู่ในนั้น ผู้รักษาความจริงไว้เป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 7, 'ผู้ทรงประกอบความยุติธรรมให้แก่คนที่ถูกบีบบังคับ ผู้ประทานอาหารแก่คนที่หิว พระเยโฮวาห์ทรงปล่อยผู้ถูกคุมขังให้เป็นอิสระ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 8, 'พระเยโฮวาห์ทรงเบิกตาของคนตาบอด พระเยโฮวาห์ทรงยกคนที่ตกต่ําให้ลุกขึ้น พระเยโฮวาห์ทรงรักคนชอบธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 9, 'พระเยโฮวาห์ทรงเฝ้าดูคนต่างด้าว พระองค์ทรงชูลูกกําพร้าพ่อและหญิงม่าย แต่พระองค์ทรงพลิกทางของคนชั่ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 10, 'พระเยโฮวาห์จะทรงครอบครองเป็นนิตย์ โอ ศิโยนเอ๋ย พระเจ้าของเธอจะทรงครอบครองทุกชั่วอายุ จงสรรเสริญพระเยโฮวาห์เถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 1, 'จงสรรเสริญพระเยโฮวาห์เถิด เป็นการดีที่จะร้องเพลงสรรเสริญพระเจ้าของเรา เพราะการกระทํานั้นเป็นที่น่ายินดีและการสรรเสริญก็เหมาะสม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 2, 'พระเยโฮวาห์ทรงก่อสร้างเยรูซาเล็มขึ้น พระองค์ทรงรวบรวมคนอิสราเอลที่ต้องกระจัดกระจายไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 3, 'พระองค์ทรงรักษาคนที่ชอกช้ําระกําใจ และทรงพันผูกบาดแผลของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 4, 'พระองค์ทรงนับจํานวนดาว พระองค์ทรงตั้งชื่อมันทุกดวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 5, 'องค์พระผู้เป็นเจ้าของเราใหญ่ยิ่งและทรงฤทธานุภาพอุดม ความเข้าใจของพระองค์นั้นวัดไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 6, 'พระเยโฮวาห์ทรงชูคนใจถ่อมขึ้น พระองค์ทรงเหวี่ยงคนชั่วลงถึงดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 7, 'จงร้องเพลงโมทนาพระคุณถวายพระเยโฮวาห์ จงร้องเพลงสรรเสริญพระเจ้าของเราด้วยพิณเขาคู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 8, 'ผู้ทรงคลุมฟ้าสวรรค์ด้วยเมฆ ผู้ทรงเตรียมฝนให้แก่แผ่นดินโลก ผู้ทรงกระทําให้หญ้างอกบนภูเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 9, 'พระองค์ทรงประทานอาหารแก่สัตว์และแก่นกกาหนุ่มที่ร้อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 10, 'ความปีติยินดีของพระองค์มิได้อยู่ที่กําลังของม้า ความปรีดีของพระองค์มิได้อยู่ที่ขาของมนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 11, 'แต่พระเยโฮวาห์ทรงปรีดีในคนที่ยําเกรงพระองค์ ในคนที่ความหวังของเขาอยู่ในความเมตตาของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 12, 'โอ เยรูซาเล็มเอ๋ย จงสรรเสริญพระเยโฮวาห์เถิด โอ ศิโยนเอ๋ย จงถวายสรรเสริญแด่พระเจ้าของเธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 13, 'เพราะพระองค์ทรงเสริมกําลังดาลประตูของเธอ พระองค์ทรงอํานวยพระพรบุตรทั้งหลายที่อยู่ภายในเธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 14, 'พระองค์ทรงกระทําสันติภาพในเขตแดนของเธอ ทรงให้เธออิ่มด้วยข้าวสาลีที่ดีที่สุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 15, 'พระองค์ทรงใช้พระบัญญัติของพระองค์ออกไปยังแผ่นดินโลก พระวจนะของพระองค์ไปเร็ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 16, 'พระองค์ประทานหิมะอย่างปุยขนแกะ พระองค์ทรงหว่านน้ําค้างแข็งขาวอย่างขี้เถ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 17, 'พระองค์ทรงโยนน้ําแข็งของพระองค์เป็นก้อนๆ ใครจะทนทานความหนาวของพระองค์ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 18, 'พระองค์ทรงใช้พระวจนะของพระองค์ออกไป และละลายมันเสีย พระองค์ทรงให้ลมพัด และน้ําก็ไหล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 19, 'พระองค์ทรงสําแดงพระวจนะของพระองค์แก่ยาโคบ กฎเกณฑ์และคําตัดสินของพระองค์แก่อิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 20, 'พระองค์มิได้ทรงประกอบการเช่นนี้แก่ประชาชาติอื่นใด และสําหรับคําตัดสินของพระองค์นั้น พวกเขาไม่รู้จักเลย จงสรรเสริญพระเยโฮวาห์เถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 1, 'จงสรรเสริญพระเยโฮวาห์เถิด จงสรรเสริญพระเยโฮวาห์จากฟ้าสวรรค์ จงสรรเสริญพระองค์ในที่สูง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 2, 'ทูตสวรรค์ทั้งหลายของพระองค์ จงสรรเสริญพระองค์ บรรดาพลโยธาของพระองค์ จงสรรเสริญพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 3, 'ดวงอาทิตย์และดวงจันทร์ จงสรรเสริญพระองค์ บรรดาดาวที่ส่องแสง จงสรรเสริญพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 4, 'ฟ้าสวรรค์ที่สูงสุด จงสรรเสริญพระองค์ ทั้งน้ําทั้งหลายเหนือฟ้าสวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 5, 'ให้สิ่งเหล่านั้นสรรเสริญพระนามพระเยโฮวาห์ เพราะพระองค์ทรงบัญชา สิ่งเหล่านั้นก็ถูกเนรมิตขึ้นมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 6, 'และพระองค์ทรงสถาปนามันไว้เป็นนิจกาล พระองค์ทรงกําหนดเขตซึ่งมันข้ามไปไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 7, 'จงสรรเสริญพระเยโฮวาห์จากแผ่นดินโลก พวกเจ้ามังกรทั้งหลายและที่น้ําลึกทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 8, 'ไฟกับลูกเห็บ หิมะกับหมอก ลมพายุ กระทําตามพระวจนะของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 9, 'บรรดาภูเขาและเนินเขาทั้งปวง ต้นไม้มีผลและไม้สนสีดาร์ทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 10, 'สัตว์ป่าและสัตว์ใช้งานทั้งปวง สัตว์เลื้อยคลานและนกที่บินได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 11, 'บรรดากษัตริย์ของแผ่นดินโลกและชนชาติทั้งหลาย เจ้านายและผู้พิพากษาทั้งปวงของแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 12, 'และคนหนุ่มกับทั้งสาว คนแก่และเด็ก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 13, 'ให้ทั้งหลายเหล่านี้สรรเสริญพระนามพระเยโฮวาห์ เพราะพระนามของพระองค์เท่านั้นที่ประเสริฐ สง่าราศีของพระองค์อยู่เหนือแผ่นดินโลกและฟ้าสวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 14, 'พระองค์ทรงยกย่องเขาแห่งประชาชนของพระองค์ ผู้ทรงเป็นที่สรรเสริญของบรรดาวิสุทธิชนของพระองค์ คือชนชาติอิสราเอล ประชาชนที่อยู่ใกล้พระองค์ จงสรรเสริญพระเยโฮวาห์เถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 1, 'จงสรรเสริญพระเยโฮวาห์เถิด จงร้องเพลงบทใหม่ถวายพระเยโฮวาห์ ร้องบทสรรเสริญถวายพระองค์ในชุมนุมวิสุทธิชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 2, 'ให้อิสราเอลยินดีในผู้สร้างของเขา ให้บุตรทั้งหลายของศิโยนเปรมปรีดิ์ในกษัตริย์ของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 3, 'ให้เขาสรรเสริญพระนามของพระองค์ด้วยเต้นรํา ให้เขาถวายเพลงสรรเสริญแด่พระองค์ด้วยรํามะนาและพิณเขาคู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 4, 'เพราะพระเยโฮวาห์ทรงปรีดีในประชาชนของพระองค์ พระองค์จะทรงประดับคนใจถ่อมด้วยความรอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 5, 'ให้วิสุทธิชนเริงโลดในสง่าราศี ให้เขาร้องเพลงบนที่นอนของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 6, 'ให้การสรรเสริญอย่างสูงแด่พระเจ้าอยู่ในปากของเขา และให้ดาบสองคมอยู่ในมือของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 7, 'เพื่อทําการแก้แค้นบรรดาประชาชาติ และทําการลงโทษชนชาติทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 8, 'เพื่อเอาตรวนล่ามบรรดากษัตริย์ของเขา และเอาเครื่องเหล็กจองจําล่ามบรรดาขุนนางของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 9, 'เพื่อจะกระทําแก่เขาตามคําพิพากษาที่บันทึกไว้แล้ว นี่เป็นเกียรติแก่บรรดาวิสุทธิชนของพระองค์ จงสรรเสริญพระเยโฮวาห์เถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 1, 'จงสรรเสริญพระเยโฮวาห์เถิด จงสรรเสริญพระเจ้าในสถานบริสุทธิ์ของพระองค์ จงสรรเสริญพระองค์ในพื้นฟ้าอันทรงอานุภาพของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 2, 'จงสรรเสริญพระองค์เพราะกิจการอันทรงอานุภาพของพระองค์ จงสรรเสริญพระองค์ตามความยิ่งใหญ่อย่างมากของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 3, 'จงสรรเสริญพระองค์ด้วยเสียงแตร จงสรรเสริญพระองค์ด้วยพิณใหญ่และพิณเขาคู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 4, 'จงสรรเสริญพระองค์ด้วยรํามะนาและการเต้นรํา จงสรรเสริญพระองค์ด้วยเครื่องสายและขลุ่ย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 5, 'จงสรรเสริญพระองค์ด้วยเสียงฉิ่ง จงสรรเสริญพระองค์ด้วยเสียงฉาบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 6, 'จงให้ทุกสิ่งที่หายใจสรรเสริญพระเยโฮวาห์ จงสรรเสริญพระเยโฮวาห์เถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 1, 'สุภาษิตของซาโลมอน โอรสของดาวิด กษัตริย์แห่งอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 2, 'เพื่อให้บรรลุปัญญาและคําสั่งสอน เพื่อให้เข้าใจถ้อยคําแห่งความเข้าใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 3, 'เพื่อให้รับคําสั่งสอนในเรื่องสติปัญญา ในเรื่องความเที่ยงธรรม ความยุติธรรมและความเที่ยงตรง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 4, 'เพื่อให้ความหยั่งรู้แก่คนเขลา ให้ความรู้และความเฉลียวฉลาดแก่คนหนุ่ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 5, 'ทั้งปราชญ์จะได้ยินและเพิ่มพูนการเรียนรู้ และคนที่มีความเข้าใจจะได้คําปรึกษาที่ฉลาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 6, 'เพื่อให้เข้าใจสุภาษิตและปริศนา ทั้งถ้อยคําของปราชญ์และปริศนาที่ลึกลับของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 7, 'ความยําเกรงพระเยโฮวาห์เป็นบ่อเกิดของความรู้ คนโง่ย่อมดูหมิ่นปัญญาและคําสั่งสอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 8, 'บุตรชายของเราเอ๋ย จงฟังคําสั่งสอนของพ่อเจ้า และอย่าละทิ้งกฎเกณฑ์ของแม่เจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 9, 'เพราะทั้งสองนั้นจะเป็นมาลัยงามสวมศีรษะของเจ้า เป็นจี้ห้อยคอของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 10, 'บุตรชายของเราเอ๋ย ถ้าคนบาปล่อชวนเจ้า อย่าได้ยอมตาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 11, 'ถ้าเขาว่า “มากับพวกเราเถิด ให้เราหมอบคอยเอาเลือดคน ให้เราซุ่มดักคนไร้ผิดเล่นเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 12, 'ให้เรากลืนเขาทั้งเป็นอย่างแดนผู้ตาย และกลืนเขาทั้งตัวอย่างคนเหล่านั้นที่ลงไปสู่ปากแดน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 13, 'เราจะพบของประเสริฐทุกอย่าง เราจะบรรจุเรือนของเราให้เต็มด้วยของที่ริบได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 14, 'จงเข้าส่วนกับพวกเรา เราทุกคนจะมีเงินถุงเดียวกัน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 15, 'บุตรชายของเราเอ๋ย อย่าเดินในทางนั้นกับเขา จงยับยั้งเท้าของเจ้าจากวิถีของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 16, 'เพราะว่าเท้าของเขาวิ่งไปหาความชั่วร้าย และเขารีบเร่งไปทําให้โลหิตตก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 17, 'เพราะที่จะขึงข่ายไว้ให้นกเห็น ก็ไร้ผล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 18, 'แต่คนเหล่านี้หมอบคอยโลหิตของตนเอง เขาซุ่มดักชีวิตของเขาเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 19, 'ทางของบรรดาผู้ที่หากําไรด้วยความทารุณโหดร้ายก็อย่างนี้แหละ คือมันย่อมคร่าเอาชีวิตของเจ้าของนั้นเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 20, 'ปัญญาร้องเสียงดังอยู่ที่ถนน เธอเปล่งเสียงของเธอตามถนน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 21, 'เธอร้องออกมาที่ชุมนุมชนใหญ่สุด ที่ทางเข้าประตูเมือง เธอกล่าวถ้อยคําของเธออยู่ในเมืองว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 22, '“คนเขลาเอ๋ย เจ้าจะรักความเขลาไปนานสักเท่าใด คนมักเยาะเย้ยจะปีติยินดีในการเยาะเย้ยนานเท่าใด และคนโง่จะเกลียดความรู้นานเท่าใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 23, 'จงหันกลับเพราะคําตักเตือนของเรา ดูเถิด เราจะเทวิญญาณของเราให้เจ้า เราจะให้ถ้อยคําของเราแจ้งแก่เจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 24, 'เพราะเราได้เรียกแล้วและเจ้าปฏิเสธ เราเหยียดมือออกและไม่มีใครสนใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 25, 'เจ้ามิได้รับรู้ในบรรดาคําแนะนําของเรา และไม่ยอมรับคําตักเตือนของเราเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 26, 'ฝ่ายเราจะหัวเราะเย้ยความหายนะของเจ้า เราจะเยาะเมื่อความกลัวลานมากระทบเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 27, 'เมื่อความหวาดกลัวของเจ้ามาถึงอย่างการรกร้างว่างเปล่า และความพินาศของเจ้ามาถึงอย่างลมหมุน เมื่อความซึมเศร้าและความปวดร้าวมาถึงเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 28, 'แล้วเขาจะทูลเรา แต่เราจะไม่ตอบ เขาจะแสวงหาเราอย่างขยันขันแข็ง แต่จะไม่พบเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 29, 'เพราะว่าเขาเกลียดความรู้ และไม่เลือกเอาความยําเกรงพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 30, 'เขาไม่รับคําแนะนําของเราเลย แต่กลับดูหมิ่นคําตักเตือนของเราทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 31, 'เพราะฉะนั้นเขาจะกินผลแห่งทางของเขา และอิ่มด้วยกลวิธีของเขาเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 32, 'เพราะการหันกลับของคนโง่จะฆ่าเขา และความเจริญของคนโง่จะทําลายเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 33, 'แต่บุคคลผู้ฟังเราจะอยู่อย่างปลอดภัย เขาจะอยู่อย่างสุขสงบปราศจากความคิดพรั่นพรึงในความชั่วร้าย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 1, 'บุตรชายของเราเอ๋ย ถ้าเจ้ารับคําของเรา และสะสมคําบัญชาของเราไว้กับเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 2, 'กระทําหูของเจ้าให้ผึ่งเพื่อรับปัญญา และเอียงใจของเจ้าเข้าหาความเข้าใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 3, 'เออ ถ้าเจ้าร้องหาความรอบรู้ และเปล่งเสียงของเจ้าหาความเข้าใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 4, 'ถ้าเจ้าแสวงหาปัญญาดุจหาเงิน และเสาะหาปัญญาอย่างหาขุมทรัพย์ที่ซ่อนไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 5, 'นั่นแหละ เจ้าจะเข้าใจความยําเกรงพระเยโฮวาห์ และพบความรู้ของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 6, 'เพราะพระเยโฮวาห์ทรงประทานปัญญา ความรู้และความเข้าใจมาจากพระโอษฐ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 7, 'พระองค์ทรงสะสมสติปัญญาไว้ให้คนชอบธรรม พระองค์ทรงเป็นดั้งให้แก่ผู้ที่ดําเนินในความเที่ยงธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 8, 'พระองค์ทรงรักษาระวังวิถีของความยุติธรรม และทรงสงวนทางของวิสุทธิชนของพระองค์ไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 9, 'แล้วเจ้าจะเข้าใจความชอบธรรมและความยุติธรรม และความเที่ยงตรง คือวิถีที่ดีทุกสาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 10, 'เมื่อปัญญาจะเข้ามาในใจของเจ้า และความรู้จะเป็นที่ร่มรื่นแก่จิตใจของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 11, 'ความเฉลียวฉลาดจะคอยเฝ้าเจ้า และความเข้าใจจะระแวดระวังเจ้าไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 12, 'เพื่อช่วยเจ้าให้พ้นจากทางแห่งคนชั่วร้าย จากคนที่พูดตลบตะแลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 13, 'ผู้ทอดทิ้งวิถีแห่งความเที่ยงธรรม เพื่อเดินในทางแห่งความมืด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 14, 'ผู้เปรมปรีดิ์ในการกระทําความชั่วร้าย และปีติยินดีในการตลบตะแลงของคนชั่ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 15, 'ผู้ซึ่งวิถีชีวิตของเขาล้วนแต่คดเคี้ยวทั้งสิ้น และทางประพฤติของเขาตลบตะแลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 16, 'เพื่อช่วยเจ้าให้พ้นจากหญิงชั่ว จากหญิงสัญจรที่พูดจาพะเน้าพะนอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 17, 'ผู้ทอดทิ้งคู่เคียงที่นางได้มาเมื่อยังสาวๆนั้นเสีย และลืมพันธสัญญาแห่งพระเจ้าของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 18, 'เพราะเรือนของนางจมลงไปสู่ความมรณา และวิถีของนางไปสู่ชาวเมืองผี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 19, 'ผู้ที่ไปหานางไม่มีกลับมาสักคนเดียว หรือหามีผู้ใดหันเข้าทางแห่งชีวิตอีกได้ไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 20, 'ดังนั้น เจ้าควรจะดําเนินในทางของคนดี และรักษาวิถีของคนชอบธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 21, 'เพราะว่าคนที่เที่ยงธรรมจะได้อยู่ในแผ่นดิน และคนดีรอบคอบจะคงอยู่ในนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 22, 'แต่คนชั่วร้ายจะถูกตัดขาดเสียจากแผ่นดินโลก และคนละเมิดจะถูกถอนรากออกไปจากแผ่นดินโลกเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 1, 'บุตรชายของเราเอ๋ย อย่าลืมกฎเกณฑ์ของเรา แต่ให้ใจของเจ้ารักษาบัญญัติของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 2, 'เพราะสิ่งเหล่านี้จะเพิ่มวันเดือนปี ชีวิตยืนยาว และความสุขสมบูรณ์แก่เจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 3, 'อย่าให้ความเมตตาและความจริงทอดทิ้งเจ้า จงผูกมันไว้ที่คอของเจ้า จงเขียนมันไว้ที่แผ่นจารึกแห่งหัวใจของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 4, 'ดังนั้น เจ้าจะพบความโปรดปรานและความเข้าใจอันดีในสายพระเนตรพระเจ้าและในสายตามนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 5, 'จงวางใจในพระเยโฮวาห์ด้วยสุดใจของเจ้า และอย่าพึ่งพาความเข้าใจของตนเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 6, 'จงยอมรับรู้พระองค์ในทุกทางของเจ้า และพระองค์จะทรงกระทําให้วิถีของเจ้าราบรื่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 7, 'อย่าทําตัวฉลาดตามสายตาของตนเอง จงยําเกรงพระเยโฮวาห์ และออกไปเสียจากความชั่วร้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 8, 'การกระทําเช่นนี้จะเป็นสุขภาพแก่สะดือของเจ้า และเป็นไขในกระดูกของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 9, 'จงถวายเกียรติแด่พระเยโฮวาห์ด้วยทรัพย์สินของตน และด้วยผลแรกแห่งผลิตผลทั้งสิ้นของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 10, 'แล้วยุ้งของเจ้าจะเต็มด้วยความอุดม และบ่อย่ําองุ่นของเจ้าจะล้นด้วยน้ําองุ่นใหม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 11, 'บุตรชายของเราเอ๋ย อย่าดูหมิ่นการตีสอนของพระเยโฮวาห์ หรือเบื่อหน่ายต่อการตักเตือนของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 12, 'เพราะพระเยโฮวาห์ทรงตักเตือนผู้ที่พระองค์ทรงรัก ดังบิดาตักเตือนบุตรชายผู้ที่เขาปีติชื่นชม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 13, 'มนุษย์ผู้ประสบปัญญาและผู้ได้ความเข้าใจ เป็นสุขจริงหนอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 14, 'เพราะผลที่ได้จากปัญญาย่อมดีกว่าผลที่ได้จากเงินและกําไรนั้นดีกว่าทองคําเนื้อดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 15, 'เธอประเสริฐกว่าทับทิม และบรรดาสิ่งที่เจ้าปรารถนาจะเปรียบกับเธอไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 16, 'ชีวิตยืนยาวอยู่ที่มือขวาของเธอ และที่มือซ้ายของเธอมีความมั่งคั่งและเกียรติยศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 17, 'ทางของเธอเป็นทางของความร่มรื่น และวิถีทั้งสิ้นของเธอคือสันติภาพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 18, 'เธอเป็นต้นไม้แห่งชีวิตแก่ผู้ที่ยึดเธอไว้ บรรดาผู้ที่ยึดเธอไว้แน่นก็เป็นสุข');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 19, 'พระเยโฮวาห์ทรงวางรากแผ่นดินโลกโดยปัญญา พระองค์ทรงสถาปนาฟ้าสวรรค์โดยความเข้าใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 20, 'โดยความรู้ของพระองค์น้ําบาดาลก็ปะทุออกมา และเมฆก็หยาดน้ําค้างลงมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 21, 'บุตรชายของเราเอ๋ย จงรักษาสติปัญญาและความเฉลียวฉลาดไว้ อย่าให้ทั้งสองนี้หนีไปจากสายตาของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 22, 'ดังนั้นทั้งสองจะเป็นชีวิตแก่จิตใจของเจ้า จะเป็นความงดงามประดับคอของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 23, 'แล้วเจ้าจะดําเนินในทางของเจ้าอย่างปลอดภัย และเท้าของเจ้าจะไม่สะดุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 24, 'เมื่อเจ้านอน เจ้าจะไม่กลัว เออ เจ้าจะนอนและการนอนหลับของเจ้าจะเป็นอย่างผาสุกสดชื่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 25, 'อย่าเกรงความหวาดกลัวอย่างปัจจุบันทันด่วน และอย่าเกรงเมื่อการรกร้างว่างเปล่าของคนชั่วมาถึง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 26, 'เพราะพระเยโฮวาห์จะทรงเป็นความไว้วางใจของเจ้า และจะทรงรักษาเท้าของเจ้าให้พ้นจากการถูกจับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 27, 'อย่ายึดความดีไว้จากผู้ที่สมควรจะได้รับ ในเมื่อสิ่งนี้อยู่ในอํานาจมือของเจ้าที่จะกระทําได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 28, 'อย่าพูดกับเพื่อนบ้านของเจ้าว่า “ไปเถอะ แล้วกลับมาอีก พรุ่งนี้ฉันจะให้” ในเมื่อเจ้ามีให้อยู่แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 29, 'อย่ากะแผนงานชั่วร้ายต่อเพื่อนบ้านของเจ้า ผู้อาศัยอย่างไว้วางใจอยู่ข้างๆเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 30, 'อย่าโต้แย้งกับผู้ใดอย่างไร้เหตุผลในเมื่อเขามิได้ทําอันตรายอย่างใดแก่เจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 31, 'อย่าอิจฉาคนที่ทารุณ อย่าเลือกทางใดๆของเขาเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 32, 'เพราะคนตลบตะแลงเป็นที่น่าสะอิดสะเอียนต่อพระเยโฮวาห์ แต่ข้อลึกลับของพระองค์นั้นอยู่กับคนชอบธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 33, 'คําสาปแช่งของพระเยโฮวาห์อยู่บนเรือนของคนชั่วร้าย แต่พระองค์ทรงอํานวยพระพรแก่ที่อาศัยของคนชอบธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 34, 'แน่นอนพระองค์ทรงเยาะเย้ยคนที่มักเยาะเย้ย แต่พระองค์ทรงประทานพระคุณแก่คนที่ใจถ่อม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 35, 'คนฉลาดจะได้เกียรติเป็นมรดก แต่คนโง่จะได้ความอัปยศเป็นตําแหน่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 1, 'บุตรทั้งหลายเอ๋ย จงฟังคําสั่งสอนของพ่อเจ้า ให้ตั้งใจฟังเพื่อเจ้าจะได้รับความเข้าใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 2, 'เพราะเราให้หลักคําสอนที่ดีแก่เจ้า อย่าละทิ้งกฎเกณฑ์ของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 3, 'เพราะเราเป็นลูกชายของพ่อเรา ดูอ่อนโยนและเป็นที่รักยิ่งในสายตาของแม่เรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 4, 'บิดาสอนเรา และพูดกับเราว่า “ให้ใจของเจ้ายึดคําสอนของเราไว้ให้มั่น จงรักษาบัญญัติของเรา และมีชีวิตอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 5, 'อย่าลืมและอย่าหันกลับจากถ้อยคําแห่งปากของเรา จงเอาปัญญา และเอาความเข้าใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 6, 'อย่าทอดทิ้งเธอ และเธอจะรักษาเจ้าไว้ จงรักเธอ และเธอจะระแวดระวังเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 7, 'ปัญญาเป็นสิ่งสําคัญที่สุด ฉะนั้นจงเอาปัญญา แม้เจ้าจะได้อะไรก็ตาม จงเอาความเข้าใจไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 8, 'จงตีราคาเธอให้สูง และเธอจะยกย่องเจ้า ถ้าเจ้ากอดเธอไว้ เธอจะให้เกียรติเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 9, 'เธอจะเอามาลัยงามสวมศีรษะเจ้า เธอจะให้มงกุฎแห่งสง่าราศีแก่เจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 10, 'โอ บุตรชายของเราเอ๋ย จงฟังและรับถ้อยคําของเรา เพื่อปีเดือนแห่งชีวิตของเจ้าจะมากหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 11, 'เราได้สอนเจ้าในเรื่องทางปัญญาแล้ว เราได้นําเจ้าในวิถีของความเที่ยงธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 12, 'เมื่อเจ้าเดิน ย่างเท้าของเจ้าจะไม่ถูกขัดขวาง และเมื่อเจ้าวิ่ง เจ้าจะไม่สะดุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 13, 'จงยึดคําสั่งสอนไว้ และอย่าปล่อยไป จงระแวดระวังเธอไว้ เพราะเธอเป็นชีวิตของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 14, 'อย่าเข้าไปในวิถีของคนชั่ว และอย่าเดินในทางของคนชั่วร้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 15, 'จงหลีกเสีย อย่าเดินบนนั้น เลี้ยวออกไปเสีย และจงผ่านไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 16, 'เพราะถ้าคนชั่วร้ายไม่ได้ทําความผิด เขานอนไม่หลับ ถ้าเขาไม่ได้ทําให้คนใดสะดุด เขาจะหลับไม่ลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 17, 'เพราะเขารับประทานอาหารของความชั่วร้าย และดื่มเหล้าองุ่นแห่งความทารุณ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 18, 'แต่วิถีของคนชอบธรรมเหมือนแสงอรุณ ซึ่งฉายสุกใสยิ่งขึ้นๆจนเต็มวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 19, 'ทางของคนชั่วร้ายก็เหมือนความมืดทึบ เขาไม่ทราบว่าเขาสะดุดอะไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 20, 'บุตรชายของเราเอ๋ย จงตั้งใจต่อถ้อยคําของเรา จงเอียงหูของเจ้าเข้าหาคําพูดของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 21, 'อย่าให้มันหนีไปจากสายตาของเจ้า จงรักษามันไว้ภายในใจของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 22, 'เพราะมันเป็นชีวิตแก่ผู้ที่ค้นพบ และมันเป็นสุขภาพแก่เนื้อหนังของผู้นั้นทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 23, 'จงรักษาใจของเจ้าด้วยความระวังระไวรอบด้าน เพราะแหล่งแห่งชีวิตเริ่มต้นออกมาจากใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 24, 'จงหันไปจากปากที่พูดคดเคี้ยว และให้ริมฝีปากลดเลี้ยวอยู่ห่างจากเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 25, 'ให้ตาของเจ้ามองตรงไปข้างหน้า และให้หนังตาของเจ้ามองตรงไปข้างหน้าเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 26, 'จงพิจารณาวิถีแห่งเท้าของเจ้า แล้วทางทั้งสิ้นของเจ้าจะมั่นคง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 27, 'อย่าเหไปข้างขวาหรือหันมาข้างซ้าย จงกลับเท้าของเจ้าเสียจากความชั่วร้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 1, 'บุตรชายของเราเอ๋ย จงตั้งใจต่อปัญญาของเรา จงเอียงหูของเจ้าฟังความเข้าใจของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 2, 'เพื่อเจ้าจะรักษาความเฉลียวฉลาดไว้ และริมฝีปากของเจ้าจะระแวดระวังความรู้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 3, 'เพราะริมฝีปากของหญิงชั่วนั้นก็หยาดน้ําผึ้งออกมา และปากของนางก็ลื่นยิ่งกว่าน้ํามัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 4, 'แต่ในที่สุด นางขมขื่นอย่างบอระเพ็ด และคมอย่างดาบสองคม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 5, 'เท้าของนางก้าวลงไปสู่ความตาย ย่างเท้าของนางติดตามวิถีสู่นรก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 6, 'เกรงว่าเจ้าจะสนใจในวิถีแห่งชีวิต ทางของนางวนเวียนไป เพื่อเจ้าจะหารู้ทางนั้นไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 7, 'ฉะนั้น โอ บุตรทั้งหลายเอ๋ย บัดนี้จงฟังเรา และอย่าพรากจากถ้อยคําแห่งปากของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 8, 'จงหลีกทางของเจ้าให้ไกลจากนาง อย่าไปใกล้ประตูเรือนของนาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 9, 'เกรงว่าเจ้าจะให้เกียรติของเจ้าแก่คนอื่น และให้ปีเดือนของเจ้าแก่คนโหดร้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 10, 'เกรงว่าแขกแปลกหน้าจะกินความอุดมสมบูรณ์ของเจ้าจนอิ่ม และแรงงานของเจ้าตกไปในเรือนของคนต่างด้าว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 11, 'และถึงบั้นปลายชีวิตของเจ้า เจ้าครวญคราง เมื่อเนื้อและกายของเจ้าถูกล้างผลาญ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 12, 'และเจ้าว่า “ข้าเคยเกลียดคําสั่งสอนเสียจริงๆ และจิตใจของข้าดูหมิ่นการตักเตือน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 13, 'ข้าไม่เคยเชื่อฟังเสียงครูของข้า หรือเอียงหูให้แก่ผู้สั่งสอนของข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 14, 'ข้าจวนจะล้มละลายสู่ความพินาศอยู่รอมร่อ ในหมู่ชุมนุมชนและคนที่ประชุมกันอยู่นั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 15, 'จงดื่มน้ําจากถังเก็บน้ําของเจ้า ดื่มน้ําไหลจากบ่อของเจ้าเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 16, 'จงให้น้ําพุของเจ้าไหลกระจายออกไปนอกบ้าน และให้ธารน้ํานั้นไหลไปตามถนน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 17, 'จงให้มันเป็นของเจ้าแต่ผู้เดียว และมิใช่สําหรับคนแปลกหน้าด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 18, 'จงให้น้ําพุของเจ้าได้รับพร และเปรมปรีดิ์อยู่กับภรรยาคนที่เจ้าได้เมื่อหนุ่มนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 19, 'จงให้นางเหมือนนางกวางที่น่ารัก เลียงผาที่งามสง่า จงให้ถันของภรรยาเจ้าเป็นที่หนําใจเจ้าอยู่ทุกเวลา จงดื่มด่ําอยู่กับความรักของนางเสมอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 20, 'บุตรชายของเราเอ๋ย เจ้าจะเคลิบเคลิ้มอยู่กับหญิงชั่วทําไมเล่า และโอบกอดอกของนางสัญจรอยู่ทําไม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 21, 'เพราะว่าทางของคนก็อยู่เบื้องหน้าพระเนตรของพระเยโฮวาห์ และพระองค์ทรงใคร่ครวญวิถีทั้งสิ้นของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 22, 'ความชั่วช้าของคนชั่วร้ายจะดักเขาเอง และเขาก็จะติดอยู่กับตาข่ายบาปของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 23, 'เขาจะตายปราศจากคําสั่งสอน และเพราะความโง่อย่างยิ่งของเขา เขาจึงจะหลงเจิ่นไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 1, 'บุตรชายของเราเอ๋ย ถ้าเจ้าเป็นผู้ประกันเพื่อนของเจ้า ได้ทําสัญญาให้แก่คนแปลกหน้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 2, 'เจ้าจึงติดบ่วงเพราะคําจากปากของเจ้า และเจ้าติดกับเพราะคําพูดจากปากของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 3, 'บุตรชายของเราเอ๋ย จงทําอย่างนี้และช่วยตัวเจ้าให้รอดเถิด เพราะเมื่อเจ้าตกอยู่ในกํามือเพื่อนของเจ้าแล้ว ไป รีบไปวิงวอนเพื่อนของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 4, 'อย่าให้ตาของเจ้าหลับลง อย่าให้หนังตาของเจ้าปรือไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 5, 'จงปลีกตัวของเจ้าจากภัย อย่างละมั่งที่ปลีกตัวจากมือของพราน อย่างนกจากมือของคนจับนก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 6, 'คนเกียจคร้านเอ๋ย ไปหามดไป๊ พิเคราะห์ดูทางของมัน และจงฉลาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 7, 'โดยปราศจากผู้นําทาง ผู้ดูแลหรือผู้ปกครอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 8, 'มันเตรียมอาหารของมันในฤดูแล้ง และส่ําสมของกินของมันในฤดูเกี่ยว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 9, 'โอ คนเกียจคร้านเอ๋ย เจ้าจะนอนนานเท่าใด เมื่อไรเจ้าจะลุกขึ้นจากหลับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 10, 'หลับนิด เคลิ้มหน่อย กอดมือพักนิดหน่อย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 11, 'ความจนจะมาเหนือเจ้าอย่างคนจร และความขัดสนอย่างคนถืออาวุธ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 12, 'คนเหลวไหล คือคนชั่วร้าย ที่เที่ยวไปด้วยปากคดเคี้ยว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 13, 'ตาของเขาก็ขยิบ เท้าของเขาก็ขยับ นิ้วของเขาก็ชี้ไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 14, 'ประดิษฐ์ความชั่วร้ายอยู่เรื่อยไปด้วยใจตลบตะแลง หว่านความแตกร้าว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 15, 'เพราะฉะนั้นความหายนะจะมาถึงเขาอย่างปัจจุบันทันด่วน ฉับพลันนั้นเองเขาจะแตกอย่างซ่อมไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 16, 'หกสิ่งเหล่านี้พระเยโฮวาห์ทรงเกลียด เออ มีเจ็ดสิ่งเป็นที่น่าสะอิดสะเอียนสําหรับพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 17, 'สายตาที่หยิ่งยโส ลิ้นมุสา และมือที่ทําโลหิตไร้ผิดให้ตก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 18, 'จิตใจที่คิดแผนงานชั่วร้าย เท้าซึ่งรีบวิ่งไปสู่ความร้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 19, 'พยานเท็จซึ่งพูดมุสา และคนผู้หว่านความแตกร้าวท่ามกลางพวกพี่น้อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 20, 'บุตรชายของเราเอ๋ย จงรักษาบัญญัติของพ่อเจ้า และอย่าละทิ้งกฎเกณฑ์ของแม่เจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 21, 'มัดมันติดไว้บนใจของเจ้าเสมอ ผูกมันไว้ที่คอของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 22, 'เมื่อเจ้าเดิน มันจะนําเจ้า เมื่อเจ้านอนลง มันจะเฝ้าเจ้า และเมื่อเจ้าตื่นขึ้น มันจะพูดกับเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 23, 'เพราะพระบัญญัติเป็นประทีป และพระราชบัญญัติเป็นความสว่าง และคําตักเตือนแห่งการสั่งสอนเป็นทางแห่งชีวิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 24, 'เพื่อสงวนเจ้าไว้จากหญิงชั่วร้าย จากลิ้นพะเน้าพะนอของหญิงสัญจร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 25, 'อย่าปรารถนาความงามของนางอยู่ในใจของเจ้า อย่าให้นางจับเจ้าด้วยหนังตาของนาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 26, 'เพราะโดยวิธีการของหญิงแพศยา ชายคนนั้นอาจเหลือแค่ขนมปังก้อนเดียวได้ และหญิงเล่นชู้ล่าชีวิตประเสริฐของชายทีเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 27, 'ผู้ชายจะหอบไฟไว้ที่อกของเขาโดยไม่ให้เสื้อผ้าของเขาไหม้ได้หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 28, 'หรือผู้ใดจะเดินบนถ่านที่ลุกโพลง โดยไม่ให้เท้าของเขาถูกไฟลวกได้หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 29, 'บุคคลผู้เข้าหาภรรยาของเพื่อนบ้านก็เป็นอย่างนั้นแหละ ไม่มีผู้ใดที่แตะต้องนางแล้วจะไร้ความผิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 30, 'ถ้าขโมยเข้าลักเพื่อบรรเทาความอยากเมื่อเขาหิว คนไม่ดูหมิ่นขโมยนั้นมิใช่หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 31, 'แต่ถ้าจับขโมยได้ เขาต้องชําระคืนเจ็ดเท่า เขาจะต้องให้สิ่งของทั้งสิ้นในบ้านของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 32, 'แต่ผู้ใดที่ล่วงประเวณีกับผู้หญิงคนหนึ่งก็ขาดความเข้าใจ ผู้ใดที่กระทําอย่างนั้นก็ทําลายจิตใจตนเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 33, 'เขาได้รับบาดแผลและความอัปยศ และจะล้างความขายหน้าของตนหาได้ไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 34, 'เพราะความอิจฉาริษยากระทําให้คนเกรี้ยวกราด ในวันที่เขาแก้แค้น เขาจะไม่เพลามือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 35, 'เขาจะไม่รับค่าทําขวัญใดๆ ถึงเจ้าจะทวีของกํานัล เขาก็ไม่ยอมสงบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 1, 'บุตรชายของเราเอ๋ย จงรักษาถ้อยคําของเรา จงสะสมบัญญัติของเราไว้กับเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 2, 'จงรักษาบัญญัติของเรา และดํารงชีวิตอยู่ จงรักษากฎเกณฑ์ของเราอย่างกับแก้วตาของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 3, 'มัดมันไว้ที่นิ้วมือของเจ้า เขียนมันไว้บนแผ่นจารึกแห่งใจของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 4, 'จงพูดกับปัญญาว่า “เธอเป็นพี่สาวของฉัน” และจงเรียกความเข้าใจว่า “ญาติผู้หญิง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 5, 'เพื่อปัญญานี้จะพิทักษ์เจ้าไว้ให้พ้นจากหญิงชั่ว จากหญิงสัญจรที่พูดจาพะเน้าพะนอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 6, 'เพราะที่หน้าต่างบ้านของเรา เราได้มองออกไปตามบานเกล็ด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 7, 'เราเห็นว่าท่ามกลางคนเขลาและท่ามกลางคนหนุ่มๆที่เราพิเคราะห์ดูนั้น ก็มีหนุ่มคนหนึ่งไร้ความเข้าใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 8, 'ผ่านไปตามถนนใกล้ทางแยกไปบ้านของนาง เดินตามถนนซึ่งไปบ้านนาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 9, 'ในเวลาโพล้เพล้ ในเวลาเย็น เวลาค่ําคืนและความมืด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 10, 'และดูเถิด หญิงคนหนึ่งมาพบเขาแต่งตัวอย่างหญิงแพศยาหัวใจเจ้าเล่ห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 11, '(นางจัดจ้านและดื้อดึง เท้าของนางไม่อยู่กับบ้าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 12, 'ประเดี๋ยวอยู่ข้างนอก ประเดี๋ยวอยู่ตามถนน และนางหมอบคอยอยู่ทุกมุม)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 13, 'นางฉวยเขาได้และจุบเขา นางพูดกับเขาอย่างไม่มียางอายว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 14, '“ฉันจําต้องถวายเครื่องสักการบูชา และวันนี้ฉันได้ทําตามคําปฏิญาณแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 15, 'ฉันจึงออกมาหาเธอ เสาะหาหน้าเธอ และฉันพบเธอแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 16, 'ฉันได้ประดับเตียงของฉันด้วยผ้าคลุม เป็นผ้าลินินอียิปต์สีต่างๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 17, 'ฉันได้อบที่นอนของฉันด้วยมดยอบ กฤษณา และอบเชย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 18, 'มาเถอะ ให้เรามาอิ่มด้วยความรักจนรุ่งเช้า ให้เราทําตัวของเราให้ปีติยินดีด้วยความรัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 19, 'เพราะผัวของฉันไม่อยู่บ้าน เขาไปทางไกล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 20, 'เขาเอาเงินไปถุงหนึ่ง พอถึงวันกําหนดไว้เขาจึงจะกลับมา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 21, 'นางหว่านล้อมด้วยวาจาโอ้โลม นางบังคับเขาด้วยริมฝีปากที่พูดพะเน้าพะนอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 22, 'เขาก็ติดตามนางไปทันทีอย่างวัวตัวผู้ไปสู่การฆ่า หรืออย่างคนเขลาที่ไปรับโทษที่ขื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 23, 'จนลูกธนูปักเข้าไปถึงตับ อย่างนกรนเข้าไปหาบ่วง เขาหาทราบไม่ว่านี่มีค่าถึงชีวิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 24, 'ฉะนั้น โอ บุตรทั้งหลายเอ๋ย บัดนี้จงฟังเราและจงตั้งใจต่อถ้อยคําจากปากของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 25, 'อย่าให้ใจของเจ้าหันไปตามทางของนาง อย่าหลงทางไปในวิถีของนางนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 26, 'เพราะนางได้ฟัดเหยื่อลงเสียเป็นอันมาก เออ นางได้ฆ่าชายที่แข็งแรงจํานวนมากเสียแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 27, 'เรือนของนางเป็นทางไปสู่นรก ลงไปถึงห้วงแห่งความตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 1, 'ปัญญามิได้ร้องเรียกหรือ ความเข้าใจมิได้เปล่งเสียงของเธอหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 2, 'ณ ที่สูงที่ข้างทาง ที่กลางถนนเธอก็ยืนอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 3, 'ข้างประตู หน้าเมือง ที่ทางเข้ามุข เธอก็ร้องเสียงดังว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 4, '“โอ บรรดาผู้ชายเอ๋ย เราเรียกเจ้า และเสียงเรียกของเราไปถึงบุตรชายของมนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 5, 'โอ คนเขลา จงเข้าใจสติปัญญา คนโง่ทั้งหลาย จงมีใจที่เข้าใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 6, 'ฟังซี เพราะเราจะพูดถึงสิ่งยอดเยี่ยม เพราะสิ่งที่ชอบจะมาจากริมฝีปากของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 7, 'เพราะปากของเราจะกล่าวความจริง ความชั่วร้ายเป็นสิ่งที่น่าสะอิดสะเอียนต่อริมฝีปากของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 8, 'บรรดาคําปากของเรานั้นชอบธรรม ในนั้นไม่มีคําบิดหรือคําคด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 9, 'คําเหล่านั้นสําหรับผู้ที่เข้าใจก็ตรงหมด สําหรับผู้พบความรู้ก็ถูกต้อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 10, 'จงรับคําสั่งสอนของเราแทนเงิน และความรู้แทนทองคําอย่างดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 11, 'เพราะปัญญาดีกว่าทับทิม และสิ่งที่เจ้าปรารถนาทั้งหมดจะเปรียบเทียบกับปัญญาไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 12, 'เราคือปัญญา อยู่ในความหยั่งรู้ และเราพบความรู้แห่งความเฉลียวฉลาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 13, 'ความยําเกรงพระเยโฮวาห์เป็นความเกลียดชังความชั่วร้าย เราเกลียดความเย่อหยิ่งและความจองหอง และทางของความชั่วร้ายกับปากตลบตะแลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 14, 'เรามีคําหารือและสติปัญญา เรามีความเข้าใจ เรามีกําลัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 15, 'โดยเรานี่แหละกษัตริย์จึงปกครอง และผู้ครอบครองจึงตรากฎหมายที่ยุติธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 16, 'โดยเรานี่แหละเจ้านายและขุนนางได้ครอบครอง คือบรรดาผู้พิพากษาของแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 17, 'เรารักบรรดาผู้ที่รักเรา และบรรดาผู้ที่แสวงหาเราอย่างขยันขันแข็งก็พบเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 18, 'ความมั่งคั่งและเกียรติอยู่กับเรา เออ ทั้งทรัพย์ศฤงคารที่ทนทานและความชอบธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 19, 'ผลของเราดีกว่าทองคํา แม้ทองคําเนื้อดี และผลได้ของเราดีกว่าเงินเนื้อบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 20, 'เรานําในทางแห่งความชอบธรรม ในวิถีทั้งหลายของความยุติธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 21, 'ประสาททรัพย์ศฤงคารแก่บรรดาผู้ที่รักเรา บรรจุคลังทรัพย์ทั้งหลายของเขาให้เต็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 22, 'พระเยโฮวาห์ทรงเป็นเจ้าของเราในเมื่อพระองค์ทรงเริ่มงานของพระองค์ ก่อนบรรดาพระราชกิจโบราณของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 23, 'เราได้รับการสถาปนาไว้ตั้งแต่ดึกดําบรรพ์มาแล้ว ตั้งแต่แรก ก่อนปฐมกาลของแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 24, 'เราถือกําเนิดมาเมื่อก่อนมีมหาสมุทร เมื่อไม่มีน้ําพุที่มีน้ํามากมาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 25, 'ก่อนการเนรมิตสร้างภูเขา ก่อนเนินเขา เราก็ถือกําเนิดมาแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 26, 'ก่อนที่พระองค์ทรงสร้างแผ่นดินโลก ทั้งไร่นา หรือก่อนผงคลีแรกของพิภพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 27, 'เมื่อพระองค์ทรงสถาปนาฟ้าสวรรค์ เราอยู่ที่นั่นแล้ว เมื่อพระองค์ทรงลากเส้นรอบวงบนพื้นมหาสมุทร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 28, 'เมื่อพระองค์ทรงสถาปนาฟ้าเบื้องบน เมื่อพระองค์ทรงกระทําน้ําพุของน้ําบาดาลให้มั่นไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 29, 'เมื่อพระองค์ทรงกําหนดเขตจํากัดให้แก่ทะเล เพื่อว่าน้ําจะไม่ละเมิดพระบัญชาของพระองค์ เมื่อพระองค์ทรงปักผังรากฐานของพิภพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 30, 'เราอยู่ข้างพระองค์แล้ว เหมือนผู้ที่พระองค์ทรงเลี้ยงดู เราเป็นความปีติยินดีประจําวันของพระองค์ เปรมปรีดิ์อยู่ต่อพระพักตร์พระองค์เสมอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 31, 'เปรมปรีดิ์ในพิภพที่มีคนอาศัยของพระองค์ และปีติยินดีในบุตรทั้งหลายของมนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 32, 'ฉะนั้น โอ บุตรทั้งหลายเอ๋ย บัดนี้จงฟังเรา บรรดาผู้ที่รักษาทางของเราก็อยู่สุขสงบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 33, 'จงฟังคําสั่งสอน และจงฉลาด และอย่าเพิกเฉยเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 34, 'ผู้ใดที่ฟังเราก็เป็นสุข คือเฝ้าอยู่ที่ประตูรั้วของเราทุกวัน และคอยอยู่ข้างประตูบ้านของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 35, 'เพราะผู้ใดที่พบเราก็พบชีวิต และได้รับความพอพระทัยจากพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 36, 'แต่ผู้ที่พลาดขาดเราก็กระทําจิตใจตัวเองให้เจ็บ บรรดาผู้ที่เกลียดชังเราก็รักความมรณา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 1, 'ปัญญาได้สร้างเรือนของเธอแล้ว เธอได้ตั้งเสาเจ็ดต้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 2, 'เธอได้ฆ่าสัตว์ของเธอ ได้ประสมน้ําองุ่นของเธอ ได้จัดโต๊ะของเธอแล้วด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 3, 'และได้ส่งสาวใช้ของเธอออกไป ส่งเสียงเรียกจากที่สูงที่สุดในเมืองว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 4, '“ผู้ใดที่เป็นคนเขลา ให้เขาหันเข้ามาที่นี่” เธอพูดกับผู้ที่ไร้ความเข้าใจว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 5, '“มาเถอะ มารับประทานขนมปังของเรา และดื่มน้ําองุ่นที่เราได้ประสม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 6, 'จงทิ้งความเขลาเสีย และดํารงชีวิตอยู่ ดําเนินในทางของความเข้าใจนั้นเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 7, 'ผู้ที่ว่ากล่าวคนมักเยาะเย้ยจะได้รับความอับอาย และผู้ที่ตักเตือนคนชั่วร้ายจะได้รับรอยเปื้อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 8, 'อย่าตักเตือนคนมักเยาะเย้ย เพราะเขาจะเกลียดเจ้า จงตักเตือนปราชญ์ และเขาจะรักเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 9, 'จงให้คําสั่งสอนแก่ปราชญ์และเขาจะฉลาดยิ่งขึ้น จงสอนคนชอบธรรมและเขาจะเพิ่มการเรียนรู้มากขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 10, 'ความยําเกรงพระเยโฮวาห์เป็นที่เริ่มต้นของปัญญา และซึ่งรู้จักองค์บริสุทธิ์เป็นความเข้าใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 11, 'เนื่องจากเรา วันคืนของเจ้าจะเพิ่มทวีคูณ และปีเดือนแห่งชีวิตของเจ้าจะเพิ่มพูน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 12, 'ถ้าเจ้าฉลาด เจ้าก็ฉลาดเพื่อตนเอง แต่ถ้าเจ้าเยาะเย้ย เจ้าก็จะทนแต่ลําพัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 13, 'หญิงโง่นั้นเสียงเอ็ดอึง นางเซ่อและไม่รู้อะไรเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 14, 'เพราะนางนั่งที่ประตูเรือนของนาง และ ณ ที่นั่งสูงในเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 15, 'พลางร้องเรียกบรรดาผู้ที่ผ่านไป ผู้เดินตรงไปตามทางของเขาว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 16, '“ผู้ใดที่เป็นคนเขลา ให้เขาหันเข้ามาที่นี่” นางพูดกับเขาผู้ไร้ความเข้าใจว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 17, '“น้ําที่ขโมยมาหวานดี และขนมที่รับประทานในที่ลับก็อร่อย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 18, 'แต่เขาไม่ทราบว่าคนตายอยู่ที่นั่น และแขกของนางก็อยู่ในห้วงลึกของนรก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 1, 'สุภาษิตของซาโลมอน บุตรชายที่ฉลาดกระทําให้บิดายินดี แต่บุตรชายที่โง่เขลาเป็นความโศกเศร้าของมารดาเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 2, 'คลังทรัพย์ชั่วร้ายไม่เป็นกําไร แต่ความชอบธรรมช่วยให้พ้นจากความตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 3, 'พระเยโฮวาห์จะไม่ทรงปล่อยให้จิตใจคนชอบธรรมหิว แต่พระองค์ทรงทอดทิ้งทรัพย์สมบัติของคนชั่วร้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 4, 'มือที่หย่อนเป็นเหตุให้เกิดความยากจน แต่มือที่ขยันขันแข็งกระทําให้มั่งคั่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 5, 'ผู้ที่ส่ําสมไว้ในฤดูแล้งก็เป็นบุตรชายที่ฉลาด แต่ผู้หลับในฤดูเกี่ยวก็เป็นบุตรชายที่นําความอับอายมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 6, 'พระพรอยู่บนศีรษะของคนชอบธรรม แต่ความทารุณท่วมปากคนชั่วร้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 7, 'การระลึกถึงคนชอบธรรมเป็นพระพร แต่ชื่อเสียงของคนชั่วร้ายจะเน่าเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 8, 'ผู้ที่มีใจประกอบด้วยปัญญาจะยอมรับบัญญัติ แต่คนที่พูดโง่ๆจะล้มลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 9, 'ผู้ใดที่ดําเนินในความเที่ยงธรรมก็ดําเนินอย่างมั่นคงดี แต่ผู้ที่ทําทางของตนให้ชั่วก็จะปรากฏแจ้งแก่คนอื่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 10, 'ผู้ที่ขยิบตาก็ก่อความเศร้าโศก แต่คนที่พูดโง่ๆจะล้มลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 11, 'ปากของคนชอบธรรมเป็นบ่อน้ําแห่งชีวิต แต่ความทารุณปกคลุมปากคนชั่วร้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 12, 'ความเกลียดชังเร้าให้เกิดความวิวาท แต่ความรักปกปิดบรรดาความผิดบาปเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 13, 'ที่ริมฝีปากของผู้ที่มีความเข้าใจจะพบปัญญา แต่ไม้เรียวก็เหมาะสําหรับหลังของผู้ที่ขาดความเข้าใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 14, 'ปราชญ์ก็ส่ําสมความรู้ไว้ แต่ปากของคนโง่นําความพินาศมาใกล้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 15, 'ทรัพย์ศฤงคารของคนมั่งคั่งคือเมืองเข้มแข็งของเขา แต่ความยากจนของคนจนคือความพินาศของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 16, 'ผลงานของคนชอบธรรมนําไปถึงชีวิต แต่ผลของคนชั่วร้ายนําไปถึงบาป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 17, 'เขาผู้รักษาคําสั่งสอนก็อยู่ในวิถีแห่งชีวิต แต่เขาผู้ปฏิเสธคําเตือนสติก็หลงเจิ่นไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 18, 'เขาผู้ปิดบังความเกลียดชังด้วยริมฝีปากมุสา และเขาผู้ออกปากใส่ร้ายเป็นคนโง่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 19, 'การพูดมากก็จะไม่ขาดความผิดบาป แต่เขาผู้ยับยั้งริมฝีปากของตนเป็นผู้ที่ฉลาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 20, 'ลิ้นของคนชอบธรรมก็เหมือนเงินเนื้อบริสุทธิ์ ความคิดของคนชั่วร้ายมีค่าแต่น้อย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 21, 'ริมฝีปากของคนชอบธรรมเลี้ยงคนเป็นอันมาก แต่คนโง่ตายเพราะขาดสติปัญญา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 22, 'พระพรของพระเยโฮวาห์กระทําให้มั่งคั่ง และพระองค์มิได้แถมความโศกเศร้าไว้ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 23, 'คนโง่กระทําความผิดเหมือนการเล่นสนุก แต่คนที่มีความเข้าใจกอปรด้วยปัญญา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 24, 'สิ่งใดที่คนชั่วร้ายคิดกลัว มันจะมาถึงเขา แต่สิ่งใดที่คนชอบธรรมปรารถนาจะทรงประสาทให้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 25, 'ลมหมุนผ่านไปฉันใด คนชั่วก็ไม่มีอีกฉันนั้น แต่คนชอบธรรมเป็นรากฐานที่อยู่เป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 26, 'อย่างน้ําส้มกับฟัน และควันกับตาเป็นฉันใด คนเกียจคร้านกับผู้ที่ใช้เขาก็เป็นฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 27, 'ความยําเกรงพระเยโฮวาห์นั้นยืดชีวิตให้ยาวไป แต่ปีเดือนของคนชั่วร้ายนั้นจะสั้นเข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 28, 'ความหวังของคนชอบธรรมจะจบลงในความยินดี แต่ความมุ่งหวังของความชั่วร้ายก็จะสูญเปล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 29, 'มรรคาของพระเยโฮวาห์ทรงเป็นกําลังแก่ผู้เที่ยงธรรม แต่ผู้กระทําความชั่วช้าจะถูกทําลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 30, 'ผู้ชอบธรรมจะไม่ถูกกําจัดเลย แต่คนชั่วร้ายจะไม่ได้อยู่ในแผ่นดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 31, 'ปากของคนชอบธรรมนําปัญญาออกมา แต่ลิ้นของคนตลบตะแลงจะถูกตัดออก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 32, 'ริมฝีปากของคนชอบธรรมรู้ว่าอะไรเหมาะสม แต่ปากของคนชั่วร้ายรู้ว่าสิ่งใดตลบตะแลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 1, 'ตราชูเทียมเท็จนั้นเป็นที่น่าสะอิดสะเอียนต่อพระเยโฮวาห์ แต่ลูกตุ้มเที่ยงตรงเป็นความปีติยินดีของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 2, 'เมื่อความเย่อหยิ่งมาถึง ความอับอายก็มาด้วย แต่ปัญญาอยู่กับคนใจถ่อม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 3, 'ความซื่อสัตย์ของคนที่เที่ยงธรรมย่อมนําเขา แต่ความคดโกงของคนละเมิดย่อมทําลายเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 4, 'ความมั่งคั่งไม่อํานวยกําไรในวันทรงพระพิโรธ แต่ความชอบธรรมช่วยให้พ้นความมรณา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 5, 'ความชอบธรรมของคนที่ไร้ตําหนิย่อมรักษาทางของเขาให้ตรง แต่คนชั่วร้ายจะล้มลงด้วยความชั่วร้ายของเขาเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 6, 'ความชอบธรรมของคนเที่ยงธรรมย่อมช่วยเขาให้พ้น แต่คนละเมิดจะถูกราคะของเขาจับเป็นเชลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 7, 'เมื่อคนชั่วร้ายตาย ความหวังของเขาจะพินาศ และความมุ่งหวังของคนอธรรมก็สูญเปล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 8, 'คนชอบธรรมรับการช่วยเหลือให้พ้นความลําบาก และคนชั่วร้ายเข้าไปแทนที่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 9, 'คนหน้าซื่อใจคดทําลายเพื่อนบ้านของเขาด้วยปาก แต่คนชอบธรรมจะได้รับการช่วยให้พ้นด้วยอาศัยความรู้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 10, 'เมื่อคนชอบธรรมอยู่เย็นเป็นสุข บ้านเมืองก็เปรมปรีดิ์ และเมื่อคนชั่วร้ายพินาศ ก็มีเสียงโห่ร้อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 11, 'โดยพรของคนเที่ยงธรรม บ้านเมืองก็เป็นที่ยกย่อง แต่ว่ามันคว่ําลงโดยปากของคนชั่วร้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 12, 'บุคคลที่ขาดสติปัญญาย่อมเหยียดเพื่อนบ้านของตน แต่คนที่มีความเข้าใจก็ยังนิ่งอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 13, 'บุคคลที่เที่ยวซุบซิบก็เผยความลับ แต่บุคคลที่มีใจสัตย์ซื่อย่อมปิดบังสิ่งหนึ่งสิ่งใดไว้ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 14, 'ที่ไหนที่ไม่มีคําแนะนํา ประชาชนก็ล้มลง แต่ในที่ซึ่งมีที่ปรึกษามากย่อมมีความปลอดภัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 15, 'บุคคลผู้รับประกันคนอื่นจะต้องทนทุกข์ แต่คนที่เกลียดการรับประกันย่อมปลอดภัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 16, 'สตรีงามสง่าย่อมได้รับเกียรติ และชายที่มีอํานาจใหญ่โตย่อมมั่งคั่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 17, 'ชายผู้มีความเอ็นดูย่อมให้ประโยชน์แก่จิตใจตน แต่ชายที่ดุร้ายย่อมทําให้ตัวเองเจ็บปวด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 18, 'บุคคลชั่วร้ายได้ทํางานที่หลอกลวง แต่บุคคลที่หว่านความชอบธรรมจะได้บําเหน็จที่แน่นอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 19, 'ความชอบธรรมนําไปสู่ชีวิตฉันใด บุคคลผู้ติดตามความชั่วร้ายจะนําไปสู่ความตายของตนเองฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 20, 'คนที่มีใจตลบตะแลงเป็นที่น่าสะอิดสะเอียนต่อพระเยโฮวาห์ แต่คนที่เที่ยงตรงในทางของเขาย่อมเป็นความปีติยินดีของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 21, 'ถึงแม้ใครลงมือช่วยก็ตาม ซึ่งคนชั่วร้ายจะไม่มีโทษนั้นหามิได้ แต่บรรดาเชื้อสายของคนชอบธรรมจะได้รับการช่วยให้พ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 22, 'สตรีงามที่ปราศจากความเฉลียวฉลาด ก็เหมือนห่วงทองคําที่จมูกหมู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 23, 'ความปรารถนาของคนชอบธรรมอยู่ในความดีเท่านั้น ความมุ่งหวังของคนชั่วร้ายอยู่ในความพิโรธ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 24, 'บางคนที่ยิ่งแจกจ่ายก็ยิ่งทวีขึ้น บางคนที่ยิ่งหวงสิ่งที่ควรแจกจ่ายไว้ก็ยิ่งขัดสน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 25, 'บุคคลที่ใจกว้างขวางย่อมได้รับความมั่งคั่ง บุคคลที่รดน้ํา เขาเองจะรับการรดน้ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 26, 'ประชาชนจะแช่งบุคคลที่กักข้าว แต่พระพรจะอยู่บนศีรษะของผู้ที่ขายข้าว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 27, 'บุคคลผู้แสวงหาความดี ก็แสวงหาความพอใจ แต่ความชั่วร้ายมาถึงผู้ที่เสาะหามัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 28, 'บุคคลผู้วางใจในความมั่งคั่งของตนจะล้มละลาย แต่คนชอบธรรมจะรุ่งเรืองอย่างใบไม้เขียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 29, 'บุคคลผู้ทําให้ครัวเรือนของเขาลําบากจะรับลมเป็นมรดก และคนโง่จะเป็นคนใช้ของคนที่มีใจฉลาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 30, 'ผลของคนชอบธรรมเป็นต้นไม้แห่งชีวิต และผู้ชนะวิญญาณก็มีสติปัญญา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 31, 'ดูเถิด แม้คนชอบธรรมอาจจะถูกทําโทษในแผ่นดินโลก คนชั่วร้ายและคนบาปจะยิ่งกว่านั้นสักเท่าใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 1, 'ผู้ใดที่รักคําสั่งสอนก็รักความรู้ แต่บุคคลที่เกลียดการตักเตือนก็เป็นคนโฉด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 2, 'คนดีเป็นที่โปรดปรานของพระเยโฮวาห์ แต่คนที่คิดการชั่วร้ายพระองค์จะทรงตําหนิ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 3, 'คนจะตั้งอยู่ด้วยความชั่วร้ายไม่ได้ แต่รากของคนชอบธรรมจะไม่รู้จักเคลื่อนย้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 4, 'ภรรยาดีเป็นมงกุฎของสามีตน แต่นางผู้ที่นําความอับอายมาก็เหมือนความเปื่อยเน่าในกระดูกสามี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 5, 'ความคิดของคนชอบธรรมนั้นยุติธรรม แต่คําหารือของคนชั่วร้ายนั้นหลอกลวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 6, 'ถ้อยคําของคนชั่วร้ายหมอบคอยเอาโลหิต แต่ปากของคนเที่ยงธรรมจะช่วยคนให้รอดพ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 7, 'คนชั่วร้ายคว่ําแล้วและไม่มีอีก แต่เรือนของคนชอบธรรมยังดํารงอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 8, 'คนจะได้คําชมเชยตามสติปัญญาของเขา แต่คนที่ความคิดตลบตะแลงจะเป็นที่ดูหมิ่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 9, 'ผู้ที่ถูกสบประมาทและมีคนรับใช้ ก็ดีกว่าคนที่ยกย่องตนเองแต่ขาดอาหาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 10, 'คนชอบธรรมย่อมเห็นแก่ชีวิตสัตว์ของเขา แต่ความกรุณาของคนชั่วร้ายคือความดุร้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 11, 'บุคคลที่ไถนาของตนจะมีอาหารอุดม แต่บุคคลที่ติดตามคนไร้สาระก็ขาดความเข้าใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 12, 'คนชั่วร้ายปรารถนาตาข่ายของคนเลว แต่รากของคนชอบธรรมย่อมออกผล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 13, 'คนชั่วร้ายย่อมติดบ่วงโดยการละเมิดแห่งริมฝีปากของตน แต่คนชอบธรรมจะหนีพ้นจากความลําบาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 14, 'จากผลแห่งปากของตนคนก็อิ่มใจในความดี และผลงานแห่งมือของเขาก็จะกลับมาหาเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 15, 'ทางของคนโง่นั้นถูกต้องในสายตาของเขาเอง แต่คนที่ยอมฟังคําแนะนําก็ฉลาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 16, 'จะรู้ความโกรธของคนโง่ได้ทันที แต่คนที่หยั่งรู้ย่อมปิดบังความอับอาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 17, 'บุคคลผู้พูดความจริงกล่าวความชอบธรรม แต่พยานเท็จกล่าวคําหลอกลวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 18, 'มีบางคนที่คําพูดพล่อยๆของเขาเหมือนดาบแทง แต่ลิ้นของปราชญ์นําการรักษามาให้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 19, 'ริมฝีปากที่พูดจริงจะทนอยู่ได้เป็นนิตย์ แต่ลิ้นที่พูดมุสาอยู่ได้เพียงประเดี๋ยวเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 20, 'ความหลอกลวงอยู่ในใจของบรรดาผู้คิดแผนการชั่วร้าย แต่บรรดาผู้กะแผนงานแห่งสันติภาพมีความชื่นบาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 21, 'ไม่มีความชั่วตกอยู่กับคนชอบธรรม แต่คนชั่วร้ายจะเต็มด้วยความร้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 22, 'ริมฝีปากที่พูดมุสาเป็นที่น่าสะอิดสะเอียนต่อพระเยโฮวาห์ แต่คนทั้งหลายที่ประพฤติอย่างจริงใจเป็นความปีติยินดีของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 23, 'คนที่หยั่งรู้ย่อมเก็บความรู้ไว้ แต่ใจคนโง่ป่าวร้องความโง่เขลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 24, 'มือของคนที่ขยันขันแข็งจะครอบครอง ฝ่ายคนเกียจคร้านจะถูกบังคับให้ทํางานโยธา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 25, 'ความกระวนกระวายในใจของมนุษย์ถ่วงเขาลง แต่ถ้อยคําที่ดีกระทําให้เขาชื่นชม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 26, 'คนชอบธรรมประเสริฐกว่าเพื่อนบ้านของตน แต่ทางของคนชั่วร้ายชักจูงพวกเขาให้หลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 27, 'คนเกียจคร้านจะไม่ปิ้งเหยื่อที่เขาล่ามา แต่ทรัพย์ศฤงคารของคนขยันขันแข็งมีค่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 28, 'ในวิถีของความชอบธรรมมีชีวิต และในทางนั้นไม่มีความมรณา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 1, 'บุตรชายที่ฉลาดฟังคําสั่งสอนของบิดาตน แต่คนมักเยาะเย้ยไม่ฟังคําขนาบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 2, 'คนจะกินของดีจากผลปากของตน แต่จิตใจของคนละเมิดจะกินความทารุณ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 3, 'บุคคลที่ระแวดระวังปากของเขาจะสงวนชีวิตของเขา แต่บุคคลที่เปิดริมฝีปากกว้างก็จะมาถึงความพินาศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 4, 'วิญญาณของคนเกียจคร้านยังอยากอยู่ แต่ไม่ได้อะไรเลย ฝ่ายวิญญาณของคนขยันจะอ้วนพี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 5, 'คนชอบธรรมเกลียดความเท็จ แต่คนชั่วร้ายประพฤติน่ารังเกียจและน่าอดสู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 6, 'ความชอบธรรมระแวดระวังผู้ที่ทางของเขาเที่ยงธรรม แต่ความชั่วร้ายคว่ําคนบาป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 7, 'คนที่ว่าตนมั่งคั่ง แต่ไม่มีอะไรเลยก็มี คนที่ว่าตนเป็นคนจน แต่มีทรัพย์ศฤงคารเป็นอันมากก็มีอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 8, 'ค่าไถ่ชีวิตของคนคือทรัพย์ศฤงคารของเขา แต่คนยากจนไม่ฟังคําติเตียน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 9, 'สว่างของคนชอบธรรมก็เปรมปรีดิ์ แต่ประทีปของคนชั่วร้ายจะถูกดับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 10, 'เพราะความทะนงตัวเท่านั้นการวิวาทจึงเกิดขึ้น แต่ปัญญาอยู่กับบรรดาผู้ที่รับคําแนะนํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 11, 'ทรัพย์ศฤงคารที่ได้มาโดยโชคลาภจะยอบแยบลง แต่บุคคลที่ส่ําสมโดยการงานจะได้เพิ่มพูนขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 12, 'ความหวังที่ถูกหน่วงไว้ทําให้ใจเจ็บช้ํา แต่ความปรารถนาที่สําเร็จแล้วเป็นต้นไม้แห่งชีวิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 13, 'บุคคลผู้ดูหมิ่นพระวจนะจะถูกทําลาย แต่บุคคลผู้เกรงกลัวพระบัญญัติจะได้รับบําเหน็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 14, 'กฎเกณฑ์ของปราชญ์เป็นน้ําพุแห่งชีวิต เพื่อจะออกไปให้พ้นจากบ่วงของความมรณา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 15, 'ความเข้าใจที่ดีก็ได้รับความโปรดปราน แต่หนทางของคนละเมิดก็ยากนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 16, 'บรรดาคนที่หยั่งรู้กระทําทุกอย่างด้วยความรู้ แต่คนโง่ก็อวดความโง่ของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 17, 'ผู้สื่อสารที่ชั่วร้ายหลงไปในความร้าย แต่ทูตที่สัตย์ซื่อนําการรักษามาให้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 18, 'ความยากจนและความอดสูมาถึงบุคคลที่เพิกเฉยต่อคําสั่งสอน แต่บุคคลที่สนใจคําตักเตือนก็ได้รับเกียรติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 19, 'ความปรารถนาที่สัมฤทธิ์ผลเป็นสิ่งหอมหวานสําหรับจิตวิญญาณ แต่เป็นความสะอิดสะเอียนแก่คนโง่ที่จะละเสียจากความชั่วร้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 20, 'บุคคลที่เดินกับปราชญ์จะกลายเป็นคนฉลาด แต่เพื่อนฝูงของคนโง่จะถูกทําลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 21, 'ความชั่วร้ายตามติดคนบาป แต่คนชอบธรรมจะได้รับความดีเป็นบําเหน็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 22, 'คนดีก็ละมรดกไว้ให้แก่หลานๆ แต่ทรัพย์ศฤงคารของคนบาปนั้นส่ําสมไว้ให้คนชอบธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 23, 'ดินที่คนยากจนไถไว้ก็เกิดผลอุดม แต่สิ่งของถูกทําลายได้เพราะขาดความยุติธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 24, 'บุคคลที่สงวนไม้เรียวก็เกลียดบุตรชายของตน แต่ผู้ที่รักเขาพยายามตีสอนเขาทันเวลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 25, 'คนชอบธรรมรับประทานได้จนพอใจ แต่ท้องของคนชั่วร้ายจะหิว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 1, 'ผู้หญิงทั้งหลายที่มีสติปัญญาสร้างเรือนของเธอขึ้น แต่ผู้หญิงที่โง่รื้อมันลงด้วยมือตนเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 2, 'บุคคลผู้ดําเนินในความเที่ยงธรรมเกรงกลัวพระเยโฮวาห์ แต่บุคคลที่คดเคี้ยวในทางของเขาก็ดูหมิ่นพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 3, 'ในปากของคนโง่มีไม้เรียวแห่งความโอหัง แต่ริมฝีปากของปราชญ์จะสงวนเขาไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 4, 'ที่ไหนที่ไม่มีวัวผู้ ที่นั่นรางหญ้าสะอาด แต่พืชผลอุดมได้มาด้วยแรงวัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 5, 'พยานที่สัตย์ซื่อจะไม่มุสา แต่พยานเท็จจะกล่าวคํามุสา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 6, 'คนมักเยาะเย้ยแสวงหาปัญญาเสียเปล่า แต่ความรู้นั้นก็ง่ายแก่คนที่มีความเข้าใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 7, 'จงไปให้พ้นหน้าคนโง่ เมื่อเจ้าไม่พบริมฝีปากแห่งความรู้ในตัวเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 8, 'ปัญญาของคนหยั่งรู้คือการเข้าใจทางของเขา แต่ความโง่ของคนโง่เป็นที่หลอกลวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 9, 'คนโง่เขลาเยาะเย้ยเรื่องความผิดบาป แต่ในท่ามกลางคนชอบธรรมก็มีความโปรดปราน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 10, 'จิตใจรู้ความขมขื่นของใจเอง และไม่มีใครอื่นมาเข้าส่วนความชื่นบานของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 11, 'เรือนของคนชั่วร้ายจะถูกคว่ํา แต่เต็นท์ของคนเที่ยงธรรมจะรุ่งเรือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 12, 'มีทางหนึ่งซึ่งคนเราดูเหมือนถูก แต่มันสิ้นสุดลงที่ทางของความมรณา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 13, 'แม้ใจของคนที่หัวเราะก็เศร้า และที่สุดของความชื่นบานนั้นคือความโศกสลด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 14, 'คนที่มีใจหันกลับจะได้ผลจากทางของเขาจนเต็ม และคนดีก็จะได้ผลดีแห่งการกระทําของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 15, 'คนเขลาเชื่อถือวาจาทุกอย่าง แต่คนหยั่งรู้มองดูว่าเขากําลังไปทางไหน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 16, 'คนมีปัญญาก็เกรงกลัวและหันเสียจากความชั่วร้าย แต่คนโง่เดือดดาลด้วยความมั่นใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 17, 'คนโมโหฉับพลันประพฤติโง่เขลา และคนวางแผนชั่วร้ายเป็นที่เกลียดชัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 18, 'คนเขลาได้ความโง่เป็นมรดก แต่คนหยั่งรู้ก็มีความรู้เป็นมงกุฎ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 19, 'คนชั่วร้ายกราบคนดี และคนชั่วร้ายกราบอยู่ที่ประตูเมืองของคนชอบธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 20, 'คนยากจนนั้นแม้เพื่อนบ้านของตนก็รังเกียจ แต่คนมั่งคั่งมีสหายมากมาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 21, 'บุคคลที่ดูหมิ่นเพื่อนบ้านของตนก็ทําบาป แต่บุคคลที่เอ็นดูคนยากจนก็เป็นสุข');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 22, 'คนที่คิดการชั่วนั้นไม่ผิดหรือ บรรดาผู้ที่คิดการดีก็จะพบความเมตตาและความจริง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 23, 'มีกําไรอยู่ในงานทุกอย่าง การเพียงแต่พูดแห่งริมฝีปากนั้นโน้มไปทางความขาดแคลน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 24, 'มงกุฎของปราชญ์คือความมั่งคั่งของตน แต่ความโง่ของคนโง่คือความเขลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 25, 'พยานซื่อตรงจะช่วยชีวิตให้รอด แต่พยานหลอกลวงจะกล่าวคํามุสา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 26, 'ความยําเกรงพระเยโฮวาห์ทําให้คนอยู่อย่างมั่นใจมาก ลูกหลานของเขาจะมีที่ลี้ภัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 27, 'ความยําเกรงพระเยโฮวาห์เป็นน้ําพุแห่งชีวิต เพื่อผู้หนึ่งผู้ใดจะหลีกจากบ่วงของความมรณาได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 28, 'ในมวลประชาชนก็มีศักดิ์ศรีของกษัตริย์ แต่ไร้ประชาชนเจ้านายก็ถูกทําลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 29, 'บุคคลที่โกรธช้าก็มีความเข้าใจมาก แต่บุคคลที่โมโหเร็วก็ยกย่องความโง่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 30, 'ใจที่สงบให้ชีวิตแก่เนื้อหนัง แต่ความอิจฉาริษยากระทําให้กระดูกผุ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 31, 'บุคคลผู้บีบบังคับคนยากจน ดูถูกพระผู้สร้างของเขา แต่บุคคลที่ถวายเกียรติแด่พระองค์ก็เอ็นดูต่อคนขัดสน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 32, 'คนชั่วร้ายก็ถูกไล่ออกตามการกระทําชั่วร้ายของเขา แต่คนชอบธรรมมีความหวังในความมรณาของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 33, 'ปัญญาอาศัยอยู่ในใจของคนที่มีความเข้าใจ แต่สิ่งซึ่งอยู่ท่ามกลางบรรดาคนโง่ก็ปรากฏตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 34, 'ความชอบธรรมเชิดชูประชาชาติหนึ่งๆ แต่บาปเป็นเหตุให้ชนชาติหนึ่งๆถูกตําหนิ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 35, 'ข้าราชการที่เฉลียวฉลาดก็ได้รับความโปรดปรานจากกษัตริย์ แต่พระพิโรธของพระองค์ก็ตกลงบนผู้ที่ประพฤติน่าละอาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 1, 'คําตอบอ่อนหวานทําให้ความโกรธเกรี้ยวหันไปเสีย แต่คํากักขฬะเร้าโทสะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 2, 'ลิ้นของปราชญ์ใช้ความรู้อย่างถูกต้อง แต่ปากของคนโง่เทความโง่ออกมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 3, 'พระเนตรของพระเยโฮวาห์อยู่ในทุกแห่งหน ทรงเฝ้าดูคนชั่วและคนดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 4, 'ลิ้นที่สุภาพเป็นต้นไม้แห่งชีวิต แต่ลิ้นตลบตะแลงทําน้ําใจให้แตกสลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 5, 'คนโง่ดูหมิ่นคําสั่งสอนของบิดาตน แต่ผู้ที่สนใจคําตักเตือนเป็นผู้หยั่งรู้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 6, 'ในเรือนของคนชอบธรรมมีคลังทรัพย์มาก แต่ความลําบากตกอยู่กับรายได้ของคนชั่วร้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 7, 'ริมฝีปากของปราชญ์กระจายความรู้ แต่ความคิดของคนโง่หาเป็นเช่นนั้นไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 8, 'เครื่องสักการบูชาของคนชั่วร้ายเป็นที่น่าสะอิดสะเอียนต่อพระเยโฮวาห์ แต่คําอธิษฐานของคนเที่ยงธรรมเป็นความปีติยินดีของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 9, 'ทางของคนชั่วร้ายเป็นที่น่าสะอิดสะเอียนต่อพระเยโฮวาห์ แต่พระองค์ทรงรักผู้ที่ติดตามความชอบธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 10, 'ผู้ที่ทอดทิ้งทางดีนับว่าการทําโทษเป็นสิ่งที่หนักใจ บุคคลผู้เกลียดคําเตือนสติจะตายเปล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 11, 'นรกและแดนพินาศก็ประจักษ์แจ้งอยู่เฉพาะพระพักตร์พระเยโฮวาห์ ใจแห่งบุตรทั้งหลายของมนุษย์จะแจ้งเฉพาะพระองค์ยิ่งกว่านั้นสักเท่าใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 12, 'คนมักเยาะเย้ยไม่รักคนที่ตักเตือนเขา ทั้งเขาจะไม่ไปหาปราชญ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 13, 'ใจที่ร่าเริงกระทําให้สีหน้าแจ่มใส แต่โดยความเศร้าในใจดวงจิตก็แหลกสลายไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 14, 'ใจของบุคคลผู้มีความเข้าใจก็แสวงหาความรู้ แต่ปากของคนโง่กินความโง่เป็นอาหาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 15, 'ทุกๆวันของคนที่ทุกข์ใจก็ร้าย แต่คนที่มีใจร่าเริงมีการเลี้ยงต่อเนื่องกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 16, 'มีทรัพย์น้อยแต่มีความยําเกรงพระเยโฮวาห์ ดีกว่ามีคลังทรัพย์ใหญ่ แต่มีความลําบากอยู่ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 17, 'กินผักเป็นอาหารในที่ที่มีความรักก็ดีกว่ากินเนื้อวัวอ้วนพร้อมกับความเกลียดชังอยู่ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 18, 'คนใจร้อนเร้าการวิวาท แต่บุคคลผู้โกรธช้าก็ระงับการชิงดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 19, 'ทางของคนเกียจคร้านเหมือนรั้วต้นไม้หนาม แต่วิถีของคนชอบธรรมเป็นทางหลวงราบเสมอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 20, 'บุตรชายที่ฉลาดกระทําให้บิดายินดี แต่คนโง่ดูหมิ่นมารดาของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 21, 'ความโง่เป็นความชื่นบานแก่บุคคลผู้ไม่มีสติปัญญา แต่คนที่มีความเข้าใจจะดําเนินในความเที่ยงธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 22, 'ปราศจากการปรึกษาหารือ แผนงานก็ล้มเหลว แต่มีผู้แนะนํามากๆ แผนงานนั้นก็สําเร็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 23, 'คําตอบจากปากที่เหมาะสมก็เป็นความชื่นบานแก่คน คําเดียวที่ถูกกาลเทศะก็ดีจริงๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 24, 'ทางแห่งชีวิตนําคนฉลาดขึ้นไปสู่เบื้องบน เพื่อเขาจะได้หลีกหนีจากนรกเบื้องล่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 25, 'พระเยโฮวาห์จะทรงรื้อเรือนของคนเย่อหยิ่ง แต่ให้ขอบเขตของหญิงม่ายคงอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 26, 'ความคิดทั้งหลายของคนชั่วร้ายเป็นสิ่งที่น่าสะอิดสะเอียนต่อพระเยโฮวาห์ แต่ถ้อยคําของคนบริสุทธิ์เป็นถ้อยคําที่พอพระทัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 27, 'บุคคลผู้ตะกละหากําไรก็กระทําความลําบากแก่ครัวเรือนของตน แต่บุคคลผู้เกลียดสินบนจะมีชีวิตอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 28, 'ใจของคนชอบธรรมรําพึงว่าจะตอบอย่างไร แต่ปากของคนชั่วร้ายเทสิ่งชั่วร้ายออก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 29, 'พระเยโฮวาห์ทรงอยู่ห่างไกลจากคนชั่วร้าย แต่พระองค์ทรงสดับคําอธิษฐานของคนชอบธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 30, 'สว่างของตาทําให้ใจเปรมปรีดิ์ และข่าวดีกระทําให้กระดูกสดชื่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 31, 'หูที่ฟังคําตักเตือนที่ให้ชีวิตจะอยู่ท่ามกลางปราชญ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 32, 'บุคคลผู้เพิกเฉยต่อคําสั่งสอนก็ดูหมิ่นจิตใจตนเอง แต่บุคคลผู้ฟังคําตักเตือนก็ได้ความเข้าใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 33, 'ความยําเกรงพระเยโฮวาห์เป็นการสอนให้เกิดปัญญา และความถ่อมใจเดินอยู่ข้างหน้าเกียรติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 1, 'ทั้งแผนงานของจิตใจมนุษย์ และคําตอบของลิ้น มาจากพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 2, 'ทางทั้งสิ้นของมนุษย์ก็สะอาดในสายตาของเขาเอง แต่พระเยโฮวาห์ทรงชั่งจิตใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 3, 'จงมอบงานของเจ้าไว้กับพระเยโฮวาห์ และแผนงานของเจ้าจะได้รับการสถาปนาไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 4, 'พระเยโฮวาห์ทรงสร้างทุกสิ่งไว้เพื่อพระองค์เอง แม้คนชั่วร้ายก็เพื่อวันชั่วร้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 5, 'ทุกคนที่มีความเย่อหยิ่งในใจก็เป็นที่น่าสะอิดสะเอียนต่อพระเยโฮวาห์ ถึงแม้มือประสานมือช่วยกัน เขาจะพ้นโทษก็หามิได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 6, 'ความเมตตาและความจริงได้ลบความชั่วช้า และคนหลีกความชั่วร้ายได้โดยความยําเกรงพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 7, 'เมื่อทางของมนุษย์เป็นที่โปรดปรานแด่พระเยโฮวาห์ แม้ศัตรูของเขานั้นพระองค์ก็ทรงกระทําให้คืนดีกับเขาได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 8, 'มีแต่น้อยแต่มีความชอบธรรมก็ดีกว่ามีรายได้มากด้วยอยุติธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 9, 'ใจของมนุษย์กะแผนงานทางของเขา แต่พระเยโฮวาห์ทรงนําย่างเท้าของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 10, 'คําตัดสินอันมาจากพระเจ้าอยู่ที่ริมฝีพระโอษฐ์ของกษัตริย์ พระโอษฐ์ของพระองค์ไม่ละเมิดในการพิพากษา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 11, 'ตราชูและตาชั่งเที่ยงตรงเป็นของพระเยโฮวาห์ ลูกตุ้มทั้งสิ้นในถุงเป็นพระราชกิจของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 12, 'การกระทําความชั่วร้ายเป็นสิ่งน่าเกลียดน่าชังต่อกษัตริย์ เพราะว่าบัลลังก์นั้นถูกสถาปนาไว้ด้วยความชอบธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 13, 'ริมฝีปากที่ชอบธรรมเป็นที่ปีติยินดีแก่กษัตริย์ และพระองค์ทรงรักบุคคลผู้พูดสิ่งที่ถูก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 14, 'พระพิโรธของกษัตริย์เป็นผู้สื่อสารของความมรณา แต่ปราชญ์จะระงับเสียได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 15, 'ในความผ่องใสจากสีพระพักตร์ของกษัตริย์ก็มีชีวิต และความโปรดปรานของพระองค์ก็เหมือนเมฆฝนปลายฤดู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 16, 'ได้ปัญญาก็ดีกว่าได้ทองคําสักเท่าใด ที่จะได้ความเข้าใจก็ดีกว่าเลือกเอาเงิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 17, 'ทางหลวงของคนเที่ยงธรรมหันออกจากความชั่วร้าย บุคคลผู้ระแวดระวังทางของตนก็สงวนชีวิตของเขาไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 18, 'ความเย่อหยิ่งเดินหน้าการถูกทําลาย และจิตใจที่ยโสนําหน้าการล้มลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 19, 'ที่จะเป็นคนมีใจถ่อมอยู่กับคนยากจนก็ดีกว่าแบ่งของที่ริบมาได้กับคนเย่อหยิ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 20, 'บุคคลผู้จัดการธุรกิจอย่างเฉลียวฉลาดจะพบของดี และคนที่วางใจในพระเยโฮวาห์จะเป็นสุข');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 21, 'คนใจฉลาดเรียกว่าเป็นคนมีความพินิจ และความหวานแห่งริมฝีปากเพิ่มความเรียนรู้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 22, 'ความเข้าใจเป็นน้ําพุแห่งชีวิตแก่ผู้ที่มีความเข้าใจ แต่คําสั่งสอนของคนโง่เป็นความโง่เขลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 23, 'ใจของปราชญ์กระทําให้ปากของเขาสุขุม และเพิ่มการเรียนรู้แก่ริมฝีปากของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 24, 'ถ้อยคําแช่มชื่นเหมือนรวงผึ้ง เป็นความหวานแก่จิตวิญญาณ และเป็นอนามัยแก่กระดูก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 25, 'มีทางหนึ่งซึ่งคนเราดูเหมือนถูก แต่มันสิ้นสุดลงที่ทางของความมรณา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 26, 'คนที่ทํางานก็ทํางานเพื่อตนเอง เพราะปากของเขากระตุ้นเขาไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 27, 'คนอธรรมขุดค้นความชั่ว และในริมฝีปากของเขาเหมือนอย่างไฟลวก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 28, 'คนตลบตะแลงแพร่การวิวาท และผู้กระซิบก็แยกเพื่อนสนิทออกจากกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 29, 'คนทารุณล่อชวนเพื่อนบ้านของเขา และนําเขาไปในทางที่ไม่ดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 30, 'เขาขยิบตากะแผนงานที่ตลบตะแลง เขาเม้มริมฝีปากของเขานําความชั่วร้ายให้เกิดขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 31, 'ศีรษะที่มีผมหงอกเป็นมงกุฎแห่งสง่าราศี ถ้าพบในทางแห่งความชอบธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 32, 'บุคคลผู้โกรธช้าก็ดีกว่าคนมีกําลังมาก และบุคคลผู้ปกครองจิตใจของตนเองก็ดีกว่าผู้ที่ตีเมืองได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 33, 'ฉลากนั้นเขาทอดลงที่ตัก แต่การตัดสินมาจากพระเยโฮวาห์ทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 1, 'เสบียงกรังหน่อยหนึ่งพร้อมกับความสงบ ดีกว่าเรือนที่มีเครื่องสักการบูชาเต็มพร้อมกับการวิวาท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 2, 'ทาสที่เฉลียวฉลาดจะปกครองบุตรชายผู้ประพฤติความละอาย และจะได้ส่วนแบ่งมรดกเท่ากับพวกพี่น้อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 3, 'เบ้ามีไว้สําหรับเงิน และเตาถลุงมีไว้สําหรับทองคํา และพระเยโฮวาห์ทรงทดลองใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 4, 'ผู้กระทําความชั่วฟังริมฝีปากเท็จ และคนมุสาเงี่ยหูแก่ลิ้นเหลวไหล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 5, 'บุคคลที่เย้ยหยันคนยากจนก็ดูถูกพระผู้สร้างของเขา บุคคลที่ยินดีเมื่อมีความลําบากยากเย็นจะไม่มีโทษหามิได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 6, 'หลานๆเป็นมงกุฎของคนแก่ และสง่าราศีของบุตรคือบิดาของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 7, 'วาจาสละสลวยไม่เหมาะแก่คนโง่ฉันใด ริมฝีปากที่มุสายิ่งไม่เหมาะแก่เจ้านายฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 8, 'ของกํานัลก็เป็นเหมือนเพชรพลอยในสายตาของเจ้าของ ไม่ว่ามันจะหันไปทางไหนก็เจริญรุ่งเรืองทางนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 9, 'บุคคลผู้ปิดบังการละเมิดก็เสาะหาความรัก แต่คนกล่าวเรื่องนั้นซ้ําซากก็ทําให้เพื่อนสนิทแยกจากกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 10, 'คําขนาบเข้าไปในคนฉลาดลึกกว่าเฆี่ยนคนโง่สักร้อยที');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 11, 'คนชั่วร้ายก็แสวงแต่การกบฏ ฉะนั้นจะมีผู้สื่อสารดุร้ายไปสู้เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 12, 'ให้คนไปพบแม่หมีที่ลูกถูกขโมยไป ยังดีกว่าไปพบคนโง่ในความโง่ของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 13, 'ถ้าคนหนึ่งคนใดทําชั่วตอบแทนความดี ความชั่วจะไม่พรากจากเรือนของคนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 14, 'เมื่อเริ่มต้นวิวาทก็เหมือนปล่อยน้ําให้ไหล ฉะนั้นจงเลิกเสียก่อนเกิดการวิวาท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 15, 'ผู้ที่ช่วยให้คนชั่วร้ายเป็นฝ่ายถูกและผู้ที่ปรับโทษคนชอบธรรม ทั้งสองก็เป็นที่น่าสะอิดสะเอียนต่อพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 16, 'ทําไมคนโง่จึงมีเงินในมือเพื่อซื้อปัญญา ในเมื่อเขาไม่มีความคิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 17, 'มิตรสหายก็มีความรักอยู่ทุกเวลา และพี่น้องก็เกิดมาเพื่อช่วยกันยามทุกข์ยาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 18, 'คนที่ไม่มีความเข้าใจก็ให้คําปฏิญาณ และเป็นผู้รับประกันต่อหน้าเพื่อนของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 19, 'บุคคลผู้รักการละเมิดก็รักการวิวาท บุคคลผู้ทําประตูเรือนของเขาให้สูงก็แสวงการทําลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 20, 'ผู้หนึ่งผู้ใดมีใจตลบตะแลงก็ไม่พบสิ่งที่ดีอันใด และผู้ที่ลิ้นวิปลาสก็ตกอยู่ในความยากลําบาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 21, 'ผู้ที่ให้กําเนิดแก่คนโฉดก็มีความโศก และบิดาของคนโง่ไม่มีความชื่นบาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 22, 'ใจร่าเริงเป็นยาอย่างดี แต่จิตใจที่หมดมานะทําให้กระดูกแห้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 23, 'คนชั่วร้ายรับสินบนจากอกเสื้อเพื่อผันแปรทางแห่งความยุติธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 24, 'คนที่มีความเข้าใจมุ่งหน้าของเขาตรงไปสู่ปัญญา แต่ตาของคนโง่อยู่ที่สุดปลายแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 25, 'บุตรชายโง่เป็นที่โศกสลดแก่บิดา และเป็นความขมขื่นแก่สตรีผู้ให้กําเนิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 26, 'ที่จะปรับคนชอบธรรมก็ไม่ดี ที่จะโบยเจ้านายเพราะเหตุความเที่ยงตรงก็ผิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 27, 'บุคคลที่ยับยั้งถ้อยคําของเขาเป็นคนมีความรู้ และบุคคลผู้มีจิตใจเยือกเย็นเป็นคนมีความเข้าใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 28, 'ถึงคนโง่หากนิ่งเสียก็นับว่าเป็นคนฉลาด คนที่หุบริมฝีปากของเขาก็นับว่าเป็นคนมีความเข้าใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 1, 'คนที่ปลีกตัวไปจากผู้อื่น จงใจกระทําตามใจตนเอง และค้านคติแห่งสติปัญญาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 2, 'คนโง่ไม่เพลิดเพลินในความเข้าใจ แต่เพลิดเพลินในการแสดงความคิดเห็นของตนเท่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 3, 'เมื่อคนชั่วร้ายมาถึง ความหมิ่นประมาทก็มาด้วย และความอดสูมากับความไร้เกียรติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 4, 'คําปากของคนเราเป็นน้ําลึก น้ําพุแห่งปัญญาเหมือนลําธารน้ําเชี่ยว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 5, 'ที่จะลําเอียงเข้าข้างคนชั่วร้ายเพื่อจะบังคับคนชอบธรรมเรื่องความยุติธรรมก็ไม่ดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 6, 'ริมฝีปากของคนโง่นําการวิวาทมา และปากของเขาก็เชื้อเชิญการโบย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 7, 'ปากของคนโง่เป็นสิ่งทําลายตัวเขาเอง และริมฝีปากของเขาก็เป็นบ่วงดักจิตใจตนเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 8, 'ถ้อยคําของผู้กระซิบนินทาก็เหมือนบาดแผล มันลงไปยังส่วนข้างในของร่างกาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 9, 'แล้วบุคคลที่หย่อนยานในการงานก็เป็นพี่น้องกับคนเจ้าทําลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 10, 'พระนามของพระเยโฮวาห์เป็นป้อมเข้มแข็ง คนชอบธรรมวิ่งเข้าไปในนั้นและปลอดภัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 11, 'ทรัพย์ศฤงคารของเศรษฐีเป็นเมืองเข้มแข็งของเขา และเป็นเหมือนกําแพงสูงตามความคิดเห็นของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 12, 'ใจของคนก็จองหองก่อนถึงการถูกทําลาย แต่ความถ่อมใจเดินอยู่หน้าเกียรติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 13, 'ถ้าคนหนึ่งคนใดตอบก่อนที่เขาได้ยิน ก็เป็นความโง่และความอับอายของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 14, 'จิตใจของคนจะทนต่อความเจ็บป่วยได้ แต่จิตใจที่ชอกช้ําใครจะทนได้เล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 15, 'ใจของคนหยั่งรู้ย่อมหาความรู้ และหูของปราชญ์แสวงความรู้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 16, 'ของกํานัลของผู้หนึ่งผู้ใดย่อมเปิดทางให้ผู้นั้น และนําเขามาถึงคนใหญ่คนโต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 17, 'บุคคลผู้แถลงคดีของตนก่อนก็ดูเหมือนเป็นฝ่ายถูก จนกว่าฝ่ายตรงข้ามจะมาสอบสวนเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 18, 'การจับฉลากกระทําให้การทะเลาะสิ้นสุด และตัดสินคู่โต้แย้งที่มีกําลัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 19, 'การคืนดีกันกับพี่น้องที่สะดุดกันแล้วก็ยากกว่าการชนะเมืองที่เข้มแข็ง และการทะเลาะวิวาทของเขาเหมือนดาลที่ป้อมปราการ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 20, 'ท้องจะอิ่มก็จากผลแห่งปากของเขา เขาจะหนําใจเพราะผลอันเกิดจากริมฝีปากของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 21, 'ความตายและความเป็นอยู่ที่อํานาจของลิ้น และบรรดาผู้ที่รักมันก็จะกินผลของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 22, 'บุคคลที่พบภรรยาก็พบของดี และได้ความโปรดปรานจากพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 23, 'คนยากจนใช้คําวิงวอน แต่คนมั่งคั่งตอบเสียงห้วนๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 24, 'คนที่มีเพื่อนต้องแสร้งทําเป็นเพื่อน แต่มีมิตรคนหนึ่งที่ใกล้ชิดยิ่งกว่าพี่น้อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 1, 'คนยากจนผู้ดําเนินในความซื่อสัตย์ของเขา ดีกว่าคนที่มีริมฝีปากตลบตะแลงและเป็นคนโง่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 2, 'เช่นเดียวกัน การที่จิตใจคนไม่มีความรู้ก็ไม่ดี และบุคคลที่เร่งเท้าหนักก็มักพลาดผิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 3, 'ความโง่ของคนก็นําความพินาศมาสู่ทางของเขา และใจของเขาเกรี้ยวกราดต่อพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 4, 'ทรัพย์ศฤงคารเพิ่มเพื่อนเป็นอันมาก แต่คนยากจนก็ถูกเพื่อนของเขาร้างไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 5, 'พยานเท็จจะไม่ได้รับโทษหามิได้ และบุคคลผู้เปล่งคํามุสาจะหนีไม่พ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 6, 'คนเป็นอันมากเอาอกเอาใจของเจ้านาย และทุกคนก็เป็นมิตรกับคนที่ให้ของกํานัล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 7, 'บรรดาพี่น้องของคนยากจนก็ยังเกลียดเขา มิตรของเขาจะยิ่งไกลจากเขาสักเท่าใด เขาพยายามพูด แต่ไม่มีใครยอมฟัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 8, 'บุคคลที่ได้ปัญญาก็รักจิตใจตนเอง บุคคลผู้รักษาความเข้าใจไว้จะพบสิ่งที่ดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 9, 'พยานเท็จจะไม่รับโทษหามิได้ และบุคคลที่เปล่งคํามุสาจะพินาศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 10, 'ที่คนโง่จะอยู่อย่างสําราญก็ไม่เหมาะอยู่แล้ว ที่ทาสจะปกครองเจ้านายก็ยิ่งไม่เหมาะมากกว่านั้นอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 11, 'สามัญสํานึกที่ดีกระทําให้คนโกรธช้า และที่มองข้ามการละเมิดไปเสียก็เป็นสง่าราศีแก่เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 12, 'พระพิโรธของกษัตริย์เหมือนเสียงคํารามของสิงโต แต่ความโปรดปรานของพระองค์เหมือนน้ําค้างบนผักหญ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 13, 'บุตรชายโง่เขลาเป็นความพินาศของบิดาของเขา และการทะเลาะวิวาทของภรรยาก็เหมือนน้ําฝนย้อยหยดไม่หยุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 14, 'เรือนและทรัพย์ศฤงคารเป็นมรดกมาจากบิดา แต่ภรรยาที่หยั่งรู้ก็มาจากพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 15, 'ความเกียจคร้านทําให้หลับสนิท และคนขี้เกียจจะต้องหิวโหย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 16, 'บุคคลที่รักษาพระบัญญัติก็รักษาชีวิตของตน บุคคลที่ดูหมิ่นมรรคาทั้งหลายของพระองค์ก็จะถึงตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 17, 'บุคคลที่เอ็นดูคนยากจนก็ให้พระเยโฮวาห์ทรงยืม และพระองค์จะทรงตอบแทนแก่การกระทําของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 18, 'จงตีสอนบุตรชายของตนเมื่อยังมีความหวัง อย่าหมดกําลังใจเพราะเหตุการร้องไห้ของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 19, 'คนที่โมโหฉุนเฉียวจะต้องได้รับโทษ เพราะถ้าเจ้าช่วยเขาให้พ้นแล้ว ก็ต้องช่วยเขาให้พ้นอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 20, 'จงฟังคําแนะนําและรับคําสั่งสอนเพื่อเจ้าจะได้ปัญญาสําหรับอนาคต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 21, 'ในใจของมนุษย์มีแผนงานเป็นอันมาก แต่คําปรึกษาของพระเยโฮวาห์นั่นแหละ จะดํารงอยู่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 22, 'สิ่งที่น่าปรารถนาในตัวมนุษย์คือความเมตตา และคนยากจนยังดีกว่าคนมุสา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 23, 'ความยําเกรงพระเยโฮวาห์นําไปสู่ชีวิต และบุคคลผู้ได้รับแล้วก็หยุดด้วยความพอใจ เขาจะไม่มีความชั่วร้ายใดๆมาเยี่ยมกรายเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 24, 'คนเกียจคร้านฝังมือของตัวไว้ในอกเสื้อ และจะไม่ยอมเอามาสู่ปากของตนอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 25, 'จงตีคนที่มักเยาะเย้ย และคนเขลาจะเรียนความหยั่งรู้เอง จงตักเตือนคนที่มีความเข้าใจและเขาจะเข้าใจความรู้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 26, 'บุคคลผู้ทําทารุณแก่บิดาของเขาและขับไล่มารดาของเขาไปเสีย เป็นบุตรชายผู้ก่อให้เกิดความอับอายและการถูกตําหนิ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 27, 'บุตรชายของเราเอ๋ย จงเลิกฟังคําสั่งสอนที่ทําให้เจ้าหลงไปจากคําแห่งความรู้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 28, 'พยานที่อธรรมก็เยาะเย้ยความยุติธรรม และปากของคนชั่วร้ายก็กลืนกินแต่ความชั่วช้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 29, 'การปรับโทษมีพร้อมอยู่สําหรับคนมักเยาะเย้ย และการโบยก็สําหรับหลังของคนโง่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 1, 'เหล้าองุ่นให้เกิดการเยาะเย้ย และสุราก็ให้เกิดเป็นพาลเกเร ผู้ใดถูกมันหลอกลวงก็ไม่เป็นคนฉลาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 2, 'ความเกรงกลัวกษัตริย์ก็เหมือนเสียงสิงโตคําราม ผู้ใดยั่วเย้าพระองค์ให้กริ้วก็ทําผิดต่อชีวิตของตนเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 3, 'ที่จะรักษาตนให้พ้นการวิวาทก็เป็นเกียรติ แต่คนโง่ทุกคนจะเข้ายุ่งกับธุระของคนอื่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 4, 'คนเกียจคร้านไม่ไถนาในหน้าหนาว เขาจึงจะแสวงหาเมื่อถึงฤดูเกี่ยว แต่ไม่พบอะไรเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 5, 'คําปรึกษาในใจของคนเหมือนน้ําลึก แต่คนที่มีความเข้าใจจะสามารถโพงมันออกมาได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 6, 'คนเป็นอันมากป่าวร้องความดีของเขาเอง แต่ใครจะหาคนสัตย์ซื่อพบเล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 7, 'คนชอบธรรมดําเนินในความซื่อสัตย์ของตน บุตรทั้งหลายของเขาที่เกิดตามเขามาย่อมได้รับพร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 8, 'กษัตริย์ผู้ประทับบนบัลลังก์พิพากษาย่อมฝัดความชั่วทั้งหลายออกด้วยพระเนตรของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 9, 'ผู้ใดจะกล่าวได้ว่า “ข้าพเจ้าได้กระทําใจของข้าพเจ้าให้สะอาด ข้าพเจ้าบริสุทธิ์พ้นบาปของข้าพเจ้าแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 10, 'ลูกตุ้มหลายชนิดและเครื่องตวงหลายขนาด ทั้งสองสิ่งเป็นที่น่าสะอิดสะเอียนต่อพระเยโฮวาห์พอๆกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 11, 'แม้เด็กๆก็แสดงตัวโดยการประพฤติของเขาว่า สิ่งที่เขากระทําจะบริสุทธิ์ และถูกต้องหรือไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 12, 'หูที่ฟังได้และตาที่มองเห็น พระเยโฮวาห์ทรงสร้างมันทั้งสอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 13, 'อย่ารักการหลับใหล เกรงว่าเจ้าจะมาถึงความยากจน จงลืมตาของเจ้า และเจ้าจะได้กินอาหารอิ่ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 14, 'ผู้ซื้อพูดว่า “เลว เลว” แต่เมื่อเขาไปแล้ว เขาจึงอวด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 15, 'มีทองคําและมีทับทิมเป็นอันมาก แต่ริมฝีปากที่มีความรู้ก็เป็นเพชรนิลจินดาประเสริฐ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 16, 'จงยึดเสื้อผ้าของเขาไว้ เมื่อเขาเป็นประกันให้คนอื่น และยึดตัวเขาไว้ เมื่อเขารับประกันหญิงต่างด้าว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 17, 'อาหารที่ได้มาด้วยการหลอกลวงมีรสหวานแก่ผู้ได้มา แต่ภายหลังปากของเขาจะเต็มไปด้วยกรวด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 18, 'แผนงานทั้งสิ้นดํารงอยู่ได้ด้วยการปรึกษาหารือ จงทําสงครามด้วยมีการนําที่ฉลาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 19, 'บุคคลที่เที่ยวซุบซิบไปก็เผยความลับให้กระจาย ฉะนั้นอย่าเข้าสังคมกับคนที่ยกยอด้วยริมฝีปากของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 20, 'ถ้าคนหนึ่งคนใดแช่งบิดาหรือมารดาของตน ประทีปของเขาจะดับมืดมิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 21, 'เริ่มแรกอาจได้รับมรดกแบบชิงสุกก่อนห่าม แต่ที่สุดปลายจะไม่เป็นพร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 22, 'อย่าพูดว่า “ข้าจะแก้แค้นความชั่ว” แต่จงรอคอยพระเยโฮวาห์ พระองค์จะทรงช่วยเจ้าให้รอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 23, 'ลูกตุ้มหลายชนิดเป็นที่น่าสะอิดสะเอียนต่อพระเยโฮวาห์ และตราชูเทียมเท็จก็ไม่ดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 24, 'ย่างเท้าของมนุษย์นั้นพระเยโฮวาห์ทรงเป็นผู้สั่ง แล้วคนจะเข้าใจทางของเขาเองได้อย่างไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 25, 'ที่คนจะกินของบริสุทธิ์ และมาสอบถามเมื่อปฏิญาณไปแล้ว ทั้งสองเป็นบ่วงดักตนเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 26, 'กษัตริย์ที่ฉลาดย่อมฝัดคนชั่วร้าย แล้วทรงขับกงจักรทับเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 27, 'จิตวิญญาณของมนุษย์เป็นประทีปของพระเยโฮวาห์ ส่องดูส่วนลึกที่สุดของเขาทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 28, 'ความเมตตาและความจริงสงวนกษัตริย์ไว้ และความเมตตาก็เชิดชูพระที่นั่งของพระองค์ไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 29, 'สง่าราศีของคนหนุ่มคือกําลังของเขา แต่ความงามของคนแก่คือผมหงอกของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 30, 'ความฟกช้ําดําเขียวของบาดแผลก็ชําระความชั่วเสีย การโบยตีกระทําให้ส่วนลึกที่สุดสะอาดสะอ้าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 1, 'พระทัยกษัตริย์เป็นเหมือนธารน้ําในพระหัตถ์ของพระเยโฮวาห์ พระเยโฮวาห์จะหันไปไหนๆตามแต่พระองค์ทรงโปรด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 2, 'ทางของคนทุกทางก็ถูกต้องในสายตาของตนเอง แต่พระเยโฮวาห์ทรงพินิจดูจิตใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 3, 'ที่จะกระทําความเที่ยงธรรมและความยุติธรรมก็เป็นที่โปรดปรานแด่พระเยโฮวาห์มากกว่าเครื่องสักการบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 4, 'สายตาที่หยิ่งยโส ใจเย่อหยิ่งและการไถนาของคนชั่วร้ายเป็นบาป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 5, 'แผนงานของคนขยันขันแข็งนําสู่ความอุดมแน่นอน แต่ทุกคนที่เร่งร้อนก็มาสู่ความขัดสนเท่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 6, 'การได้คลังทรัพย์มาด้วยลิ้นมุสาก็เป็นความอนิจจังที่เคลื่อนไปๆมาๆของคนที่เสาะหาความตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 7, 'ความทารุณของคนชั่วร้ายจะกวาดเขาไป เพราะเขาปฏิเสธไม่ยอมทําสิ่งที่ยุติธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 8, 'ทางของมนุษย์ตลบตะแลงและมีความผิด แต่ความประพฤติของผู้บริสุทธิ์นั้นถูกต้อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 9, 'อยู่ที่มุมบนหลังคาเรือนดีกว่าอยู่ในเรือนกว้างขวางร่วมกับหญิงขี้ทะเลาะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 10, 'วิญญาณของคนชั่วร้ายปรารถนาความชั่ว เพื่อนบ้านของเขาไม่เป็นที่ชอบใจในสายตาของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 11, 'เมื่อคนมักเยาะเย้ยถูกลงโทษ คนเขลาก็ฉลาดขึ้น เมื่อปราชญ์ได้รับการสั่งสอน เขาก็ได้ความรู้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 12, 'คนชอบธรรมสังเกตดูเรือนของคนชั่วร้าย แต่พระเจ้าทรงคว่ําคนชั่วร้ายลงเพราะเหตุความชั่วร้ายของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 13, 'บุคคลผู้อุดหูไม่ฟังเสียงร้องของคนยากจน ตัวเขาเองจะร้อง แต่ไม่มีใครได้ยิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 14, 'ให้ของกํานัลในที่ลับย่อมแปรความโกรธ ให้สินบนในอกก็แปรการพิโรธร้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 15, 'เมื่อกระทําการตัดสินก็เป็นการชื่นบานแก่คนชอบธรรม แต่คนกระทําความชั่วช้าจะได้รับความพินาศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 16, 'ผู้ใดที่หันเหไปจากทางแห่งความเข้าใจ จะพักอยู่ในที่ประชุมของคนตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 17, 'บุคคลที่รักความเพลิดเพลินจะเป็นคนยากจน บุคคลที่รักเหล้าองุ่นและน้ํามันจะไม่มั่งคั่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 18, 'คนชั่วร้ายเป็นค่าไถ่สําหรับคนชอบธรรม และคนละเมิดสําหรับคนเที่ยงธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 19, 'อยู่ในแผ่นดินทุรกันดารดีกว่าอยู่กับผู้หญิงที่ขี้ทะเลาะและจู้จี้ขี้บ่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 20, 'คลังทรัพย์ประเสริฐและน้ํามันมีอยู่ในที่อาศัยของคนฉลาด แต่คนโง่กินมันหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 21, 'บุคคลผู้ตามติดความชอบธรรมและความเอ็นดู จะพบชีวิตและความชอบธรรมกับเกียรติยศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 22, 'ปราชญ์ปีนเข้าไปในเมืองของคนที่มีกําลัง และพังทลายที่กําบังเข้มแข็งที่เขาไว้วางใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 23, 'บุคคลที่รักษาปากและลิ้นของตนก็รักษาจิตใจเขาเองให้พ้นความลําบาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 24, '“คนเย่อหยิ่งและคนมักเยาะเย้ย” เป็นชื่อของคนที่ประพฤติตัวด้วยความโกรธเย่อหยิ่งยโส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 25, 'ความปรารถนาของคนเกียจคร้านฆ่าตัวเขาเอง เพราะมือของเขาปฏิเสธไม่ทํางาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 26, 'เขาโลภอย่างตะกละอยู่วันยังค่ํา แต่คนชอบธรรมให้และไม่หน่วงเหนี่ยวไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 27, 'เครื่องสักการบูชาของคนชั่วร้ายเป็นสิ่งที่น่าสะอิดสะเอียน เมื่อเขานํามาด้วยใจที่ชั่วร้ายจะยิ่งกว่านั้นสักเท่าใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 28, 'พยานเท็จจะต้องพินาศ แต่คนที่พูดอย่างซื่อสัตย์นั้นฟังได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 29, 'คนชั่วร้ายทําให้หน้าของตนด้านไป แต่คนเที่ยงธรรมพิเคราะห์ดูทางของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 30, 'ปัญญาก็ดี ความเข้าใจก็ดี คําปรึกษาก็ดี จะเอาชนะพระเยโฮวาห์ไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 31, 'ม้าก็เตรียมไว้พร้อมแล้วสําหรับวันสงคราม แต่ความปลอดภัยเป็นของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 1, 'ชื่อเสียงดีเป็นสิ่งควรเลือกยิ่งกว่าความมั่งคั่งมากมาย และซึ่งเป็นที่โปรดปรานก็ยิ่งกว่ามีเงินหรือทอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 2, 'คนมั่งคั่งและยากจนประชุมพร้อมกัน พระเยโฮวาห์ทรงสร้างเขาทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 3, 'คนหยั่งรู้เห็นอันตรายและซ่อนตัวของเขาเสีย แต่คนเขลาเดินเรื่อยไปและรับโทษ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 4, 'บําเหน็จของความถ่อมใจและความยําเกรงพระเยโฮวาห์ คือความมั่งคั่ง เกียรติและชีวิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 5, 'หนามและบ่วงอยู่ในทางของคนตลบตะแลง บุคคลที่ระแวดระวังจิตใจตนเองจะอยู่ไกลเสียจากสิ่งเหล่านี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 6, 'จงฝึกเด็กในทางที่เขาควรจะเดินไป และเมื่อเขาเติบโตแล้ว เขาจะไม่พรากจากทางนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 7, 'คนมั่งคั่งปกครองเหนือคนยากจน และคนขอยืมก็เป็นทาสของคนให้ยืม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 8, 'บุคคลผู้หว่านความชั่วช้าจะเกี่ยวความหายนะ และไม้เรียวแห่งความโกรธของเขาจะล้มเหลว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 9, 'บุคคลที่มีตาแสดงใจกว้างขวางก็จะรับพร เพราะเขาแบ่งส่วนอาหารของเขาแก่คนยากจน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 10, 'จงขับคนมักเยาะเย้ยออกไปเสีย แล้วการวิวาทจะหมดไป เออ การวิวาทและการดูแคลนจะหยุดลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 11, 'บุคคลที่รักใจบริสุทธิ์ เพราะเหตุริมฝีปากของเขามีกรุณาคุณ กษัตริย์จะได้เป็นมิตรของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 12, 'พระเนตรพระเยโฮวาห์เฝ้าอยู่เหนือความรู้ แต่พระองค์ทรงคว่ําถ้อยคําของคนละเมิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 13, 'คนเกียจคร้านกล่าวว่า “มีสิงโตอยู่ข้างนอก ข้าจะถูกฆ่าตามถนน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 14, 'ปากของหญิงชั่วเป็นหลุมลึก บุคคลซึ่งพระเยโฮวาห์ทรงพระพิโรธจะตกลงในที่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 15, 'ความโง่ถูกผูกมัดอยู่ในใจของเด็ก แต่ไม้เรียวที่ตีสอนก็ขับมันให้ห่างไปจากเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 16, 'บุคคลผู้บีบบังคับคนยากจนเพื่อเพิ่มทรัพย์ศฤงคารของตน และผู้ที่เพิ่มให้แก่คนมั่งคั่ง จะมาถึงความขัดสนอย่างแน่นอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 17, 'เอียงหูของเจ้าและฟังถ้อยคําของปราชญ์ และเอาใจใส่ความรู้ของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 18, 'เพราะถ้าเจ้ารักษาถ้อยคําและความรู้นั้นไว้ในตัวเจ้า ก็จะเป็นความชื่นใจแก่เจ้า แล้วทั้งสองจะมั่นคงในริมฝีปากของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 19, 'เพื่อความไว้วางใจของเจ้าจะอยู่ในพระเยโฮวาห์ เราให้แจ้งประจักษ์แก่เจ้าในวันนี้แม้แก่ตัวเจ้าเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 20, 'เราได้เขียนให้เจ้าถึงสิ่งวิเศษนัก ถึงเรื่องการปรึกษาและความรู้แล้วมิใช่หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 21, 'เพื่อเราจะให้เจ้าทราบถึงความแน่นอนของถ้อยคําแห่งความจริง เพื่อเจ้าจะได้ตอบถ้อยคําแห่งความจริงแก่ผู้ที่ใช้เจ้าไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 22, 'อย่าปล้นคนยากจน เพราะเขาเป็นคนยากจน หรือบีบคั้นคนทุกข์ใจที่ประตูเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 23, 'เพราะว่าพระเยโฮวาห์จะทรงว่าความแทนเขา และริบชีวิตของผู้ที่ริบเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 24, 'อย่าเป็นมิตรกับคนที่มักโกรธ หรือไปกับคนขี้โมโห');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 25, 'เกรงว่าเจ้าจะเรียนรู้ทางของเขา และพัวพันจิตใจเจ้าเข้าในบ่วง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 26, 'อย่าเป็นพวกที่เป็นผู้ค้ําประกัน อย่าเป็นพวกผู้เป็นประกันหนี้สิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 27, 'ถ้าเจ้าไม่มีอะไรชําระเขา ทําไมจึงควรให้เขาเอาที่นอนไปจากใต้ตัวเจ้าเล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 28, 'อย่าย้ายหลักเขตเก่าแก่ซึ่งบรรพบุรุษของเจ้าได้ปักไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 29, 'เจ้าเห็นคนที่ขยันในงานของเขาหรือ เขาจะได้เข้าเฝ้ากษัตริย์ เขาจะไม่ยืนอยู่ต่อหน้าคนต่ําต้อย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 1, 'เมื่อเจ้านั่งลงรับประทานกับผู้ครอบครองบ้านเมือง จงสังเกตให้ดีว่าอะไรอยู่ข้างหน้าเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 2, 'ถ้าเจ้าเป็นคนตะกละ เจ้าจงจ่อมีดไว้ที่คอของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 3, 'อย่าปรารถนาของโอชะของท่าน เพราะมันเป็นอาหารที่หลอกลวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 4, 'อย่าทํางานเพื่อมั่งมี จงเลิกพึ่งสติปัญญาของตนเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 5, 'เจ้าจะเพ่งตาของเจ้าอยู่ที่ของอนิจจังหรือ เพราะแน่นอนทีเดียวทรัพย์สมบัติมีปีก มันจะบินไปในท้องฟ้าเหมือนนกอินทรี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 6, 'อย่ากินอาหารของคนที่มีแววตาอันชั่วร้าย อย่าปรารถนาของโอชะของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 7, 'เพราะเขาคิดในใจอย่างไร เขาก็เป็นอย่างนั้น เขาพูดกับเจ้าว่า “จงกินและดื่มเถิด” แต่ใจของเขามิได้อยู่กับเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 8, 'เจ้าจะต้องสํารอกอาหารซึ่งเจ้าได้กินเข้าไปนั้น และเสียถ้อยคําแช่มชื่นของเจ้าเสียเปล่าๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 9, 'อย่าพูดให้คนโง่ได้ยิน เพราะเขาจะดูหมิ่นปัญญาแห่งถ้อยคําของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 10, 'อย่าโยกย้ายเสาเขตเก่าแก่ หรือเข้าไปในไร่นาของคนกําพร้าพ่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 11, 'เพราะพระผู้ไถ่ของเขาแข็งแรง พระองค์จะว่าคดีของเขาต่อสู้เจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 12, 'จงเอาใจของเจ้ารับคําสั่งสอน และเอาหูของเจ้ารับถ้อยคําแห่งความรู้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 13, 'อย่ายับยั้งการตีสอนเสียจากเด็ก เพราะถ้าเจ้าตีเขาด้วยไม้เรียว เขาจะไม่ตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 14, 'เจ้าจะตีเขาด้วยไม้เรียว แล้วเจ้าจะช่วยชีวิตของเขาให้รอดจากนรก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 15, 'บุตรชายของเราเอ๋ย ถ้าใจของเจ้าฉลาด ใจของเราเองก็จะยินดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 16, 'เออ วิญญาณของเราจะเปรมปรีดิ์ เมื่อริมฝีปากของเจ้าพูดสิ่งที่ถูกต้อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 17, 'อย่าให้ใจของเจ้าริษยาคนบาป แต่จงยําเกรงพระเยโฮวาห์วันยังค่ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 18, 'ด้วยว่าจะมีที่สิ้นสุดอย่างแน่นอนทีเดียว และความคาดหวังของเจ้าจะมิได้ถูกตัดออก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 19, 'บุตรชายของเราเอ๋ย จงฟัง และจงฉลาดเถิด และนําใจของเจ้าไปในทางนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 20, 'อย่าอยู่ท่ามกลางคนดื่มเหล้าองุ่น หรือท่ามกลางคนตะกละที่กินเนื้อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 21, 'เพราะคนขี้เมาและคนตะกละจะมาถึงความยากจน และความง่วงเหงาจะเอาผ้าขี้ริ้วห่มคนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 22, 'จงฟังบิดาของเจ้าผู้ให้กําเนิดเจ้า และอย่าดูหมิ่นมารดาของเจ้าเมื่อนางแก่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 23, 'จงซื้อความจริงและอย่าขายไปเสีย จงซื้อปัญญา คําสั่งสอน และความเข้าใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 24, 'บิดาของคนชอบธรรมจะเปรมปรีดิ์อย่างยิ่ง บุคคลผู้ให้กําเนิดบุตรที่ฉลาดจะยินดีเพราะเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 25, 'บิดามารดาของเจ้าจะยินดี และผู้ที่คลอดเจ้าก็จะเปรมปรีดิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 26, 'บุตรชายของเราเอ๋ย ขอใจของเจ้าให้เราเถอะ และให้ตาของเจ้าสังเกตดูทางทั้งหลายของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 27, 'เพราะหญิงแพศยาเป็นหลุมลึก และหญิงสัญจรเป็นเหมือนบ่อแคบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 28, 'นางหมอบคอยอยู่เหมือนคอยเหยื่อ และเพิ่มคนละเมิดขึ้นท่ามกลางมนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 29, 'ใครที่ร้องโอย ใครที่ร้องอุย ใครที่มีการวิวาท ใครที่มีการร้องคราง ใครที่มีบาดแผลปราศจากเหตุ ใครที่มีตาแดง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 30, 'คือบรรดาผู้ที่นั่งแช่อยู่กับเหล้าองุ่น บรรดาผู้ที่ไปแสวงหาเหล้าประสม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 31, 'อย่ามองดูเหล้าองุ่นเมื่อมันมีสีแดง เมื่อเป็นประกายในถ้วย และลงไปคล่องๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 32, 'ณ ที่สุดมันกัดเหมือนงู และมันฉกเอาเหมือนงูพิษ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 33, 'ตาของเจ้าจะมองดูหญิงชั่ว และใจของเจ้าจะพูดตลบตะแลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 34, 'เออ เจ้าจะเป็นเหมือนคนที่นอนอยู่กลางทะเล อย่างคนที่นอนอยู่บนเสากางใบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 35, 'เจ้าจะว่า “เขาตีข้า แต่ข้าไม่เจ็บ เขาทุบข้า แต่ข้าไม่รู้สึก ข้าจะตื่นเมื่อไรหนอ ข้าจะแสวงหาการดื่มอีก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 1, 'อย่าคิดริษยาคนชั่ว หรือปรารถนาอยู่ร่วมกับเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 2, 'เพราะว่าใจของเขาคิดประกอบการทําลาย และริมฝีปากของเขาพูดการประทุษร้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 3, 'เรือนนั้นเขาสร้างกันด้วยปัญญา และสถาปนามันไว้ด้วยความเข้าใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 4, 'โดยความรู้บรรดาห้องก็เต็มไปด้วยความมั่งคั่งล้วนประเสริฐและเพลิดเพลินทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 5, 'คนฉลาดมีกําลังมาก และคนมีความรู้ก็เพิ่มกําลังขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 6, 'เพราะว่าโดยการนําที่ฉลาด เจ้าก็จะเข้าสงครามได้ และด้วยมีที่ปรึกษามากๆก็มีความปลอดภัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 7, 'สําหรับคนโง่นั้นปัญญาสูงเกินไป ที่ประตูเมืองเขาไม่อ้าปากพูด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 8, 'บุคคลผู้กะแผนงานทําความชั่วเขาเรียกกันว่าคนเจ้าเล่ห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 9, 'การคิดในเรื่องที่โง่เขลาเป็นบาป และคนมักเยาะเย้ยเป็นที่น่าเกลียดน่าชังแก่มนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 10, 'ถ้าเจ้าท้อใจในวันแห่งความชั่วร้าย กําลังของเจ้าก็น้อย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 11, 'ถ้าเจ้าไม่ช่วยบรรดาผู้ที่ถูกนําไปสู่ความมรณา และไม่ช่วยบรรดาผู้ที่ตุปัดตุเป๋ไปเพื่อถูกฆ่าให้รอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 12, 'ถ้าเจ้าจะว่า “ดูเถิด เราไม่รู้เรื่องนี้เลย” พระองค์ผู้ทรงชั่งใจจะไม่ทรงเพ่งเล็งเห็นหรือ พระองค์ผู้ทรงเฝ้าวิญญาณอยู่เหนือเจ้าจะไม่ทราบหรือ และพระองค์จะไม่ทรงเรียกเอาจากทุกคนตามการกระทําของเขาหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 13, 'บุตรชายของเราเอ๋ย จงรับประทานน้ําผึ้งเพราะเป็นของดี และรวงผึ้งซึ่งมีรสหวาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 14, 'การรู้จักปัญญาก็เป็นเช่นนั้นแก่วิญญาณของเจ้า เมื่อเจ้าพบปัญญาก็จะมีบําเหน็จ และความคาดหวังของเจ้าจะไม่ถูกตัดออก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 15, 'โอ คนชั่วร้ายเอ๋ย อย่าหมอบคอยเพื่อต่อสู้กับที่อาศัยของคนชอบธรรม อย่าปล้นเรือนของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 16, 'เพราะคนชอบธรรมล้มลงเจ็ดครั้งแล้วก็ลุกขึ้นอีก แต่คนชั่วร้ายจะตกอยู่ในอาการร้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 17, 'อย่าเปรมปรีดิ์เมื่อศัตรูของเจ้าล้ม และอย่าให้ใจของเจ้ายินดีเมื่อเขาสะดุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 18, 'เกรงว่าพระเยโฮวาห์จะทอดพระเนตรและไม่ทรงพอพระทัย และทรงหันความกริ้วจากเขาเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 19, 'เจ้าอย่ากระวนกระวายเพราะคนชั่ว และอย่ามีใจริษยาคนชั่วร้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 20, 'เพราะคนชั่วจะไม่มีบําเหน็จ ประทีปของคนชั่วร้ายจะถูกดับเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 21, 'บุตรชายของเราเอ๋ย จงยําเกรงพระเยโฮวาห์และกษัตริย์ อย่าเข้ายุ่งกับคนที่หันกลับจากพระองค์ทั้งสองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 22, 'เพราะภัยพิบัติจากพระองค์ทั้งสองจะอุบัติขึ้นโดยพลัน และผู้ใดจะทราบถึงความพินาศที่จะมาจากพระองค์ทั้งสอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 23, 'ข้อความเหล่านี้เป็นคํากล่าวของปราชญ์ด้วย การเห็นแก่หน้าคนใดในการตัดสินนั้นไม่ดีเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 24, 'บุคคลผู้กล่าวแก่คนชั่วร้ายว่า “เจ้าไร้ความผิด” จะถูกชนชาติทั้งหลายแช่งและประชาชาติจะรังเกียจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 25, 'แต่บรรดาผู้ขนาบเขาจะมีความปีติยินดี และพรอันดีจะมีอยู่กับเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 26, 'ทุกคนจะจุบริมฝีปากของผู้ให้คําตอบที่ถูก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 27, 'จงเตรียมงานของเจ้าที่ภายนอก ทําทุกอย่างของเจ้าให้พร้อมที่ในนา และหลังจากนั้นก็จงสร้างเรือนของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 28, 'อย่าเป็นพยานปรักปรําเพื่อนบ้านของเจ้าอย่างไม่มีเหตุ และอย่าล่อลวงด้วยริมฝีปากของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 29, 'อย่ากล่าวว่า “ข้าจะทําแก่เขาอย่างที่เขาได้กระทําแก่ข้า ข้าจะทําตอบแก่เขาอย่างที่เขาได้กระทํา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 30, 'เราผ่านไปที่ไร่นาของคนเกียจคร้าน ข้างสวนองุ่นของคนที่ไร้ความเข้าใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 31, 'และดูเถิด มีหนามงอกเต็มไปหมด และแผ่นดินก็เต็มไปด้วยตําแย และกําแพงหินของมันก็พังลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 32, 'แล้วเราได้เห็นและพิเคราะห์ดู เรามองดูและได้รับคําสั่งสอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 33, '“หลับนิด เคลิ้มหน่อย กอดมือพักนิดหน่อย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 34, 'แล้วความยากจนจะมาหาเจ้าอย่างนักท่องเที่ยว ความขัดสนอย่างคนถืออาวุธ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 1, 'ต่อไปนี้เป็นสุภาษิตของซาโลมอนด้วยเหมือนกัน ซึ่งคนของเฮเซคียาห์กษัตริย์แห่งยูดาห์ได้คัดลอกไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 2, 'สง่าราศีของพระเจ้าคือการซ่อนสิ่งต่างๆไว้ แต่ศักดิ์ศรีของกษัตริย์คือการค้นสิ่งต่างๆให้ปรากฏ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 3, 'ฟ้าสวรรค์สูงฉันใด และแผ่นดินโลกลึกฉันใด พระทัยของกษัตริย์ก็เหลือจะหยั่งรู้ฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 4, 'จงไล่ขี้ออกจากเงินเสีย แล้วจะมีวัสดุสําหรับช่างทําขัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 5, 'จงไล่คนชั่วร้ายออกไปเสียจากพระพักตร์กษัตริย์ และพระที่นั่งของพระองค์จะสถาปนาไว้ด้วยความชอบธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 6, 'อย่าเอาตัวเจ้าขึ้นมาข้างหน้าต่อพระพักตร์กษัตริย์ หรือยืนอยู่ในที่ของผู้หลักผู้ใหญ่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 7, 'เพราะที่จะให้เขาว่า “เชิญขึ้นมาที่นี่” ก็ดีกว่าถูกไล่ลงไปที่ต่ําต่อหน้าเจ้านายผู้ซึ่งตาของเจ้าได้เห็นแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 8, 'อย่าด่วนนําเข้ามายังโรงศาล เพราะเมื่อเพื่อนบ้านของเจ้าทําให้เจ้าได้อายแล้ว ในที่สุดเจ้าจะทําอย่างไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 9, 'จงตกลงเรื่องของเจ้ากับเพื่อนบ้านของเจ้า และอย่าทําให้เผยความลับของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 10, 'เกรงว่าผู้ที่ได้ยินจะนําความอายมาสู่เจ้า และชื่อเสียงของเจ้าจะมัวหมองอยู่นาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 11, 'ถ้อยคําที่พูดเหมาะๆจะเหมือนผลแอบเปิ้ลทองคําในภาชนะเงิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 12, 'คนตักเตือนที่ฉลาดกับหูที่เชื่อฟังก็เหมือนตุ้มหูทองคําหรืออาภรณ์ทองคําเนื้อดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 13, 'หิมะให้ความเย็นในฤดูเกี่ยวอย่างไร ผู้สื่อสารที่สัตย์ซื่อย่อมทําให้จิตวิญญาณของนายผู้ใช้เขาชุ่มชื่นอย่างนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 14, 'คนที่อวดว่าจะให้ของกํานัลแต่มิได้ให้ ก็เหมือนเมฆและลมที่ไม่มีฝน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 15, 'ความพากเพียรจะชักนําผู้ครอบครองได้ และลิ้นที่อ่อนหวานจะทําให้กระดูกหักได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 16, 'เจ้าได้พบน้ําผึ้งแล้วหรือ จงกินแต่พอดี เกรงว่าเจ้าจะอิ่มและอาเจียนออกมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 17, 'อย่าให้เท้าของเจ้าอยู่ในเรือนเพื่อนบ้านของเจ้านานๆ เกรงว่าเขาจะเหน็ดเหนื่อยเพราะเจ้า และเกลียดชังเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 18, 'คนใดที่เป็นพยานเท็จกล่าวโทษเพื่อนบ้านของเขา ก็เหมือนกระบองศึก หรือดาบ หรือลูกธนูที่คม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 19, 'การวางใจในคนที่ไม่ซื่อในยามลําบาก ก็เหมือนฟันที่หักเสียหรือเท้าที่หลุดจากข้อต่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 20, 'บรรดาคนที่ร้องเพลงให้คนหนักใจฟัง ก็เหมือนคนถอดเครื่องแต่งกายออกในวันที่อากาศหนาว และเหมือนเอาน้ําส้มมาราดบนดินประสิว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 21, 'ถ้าศัตรูของเจ้าหิว จงให้อาหารเขารับประทาน และถ้าเขากระหาย จงให้น้ําเขาดื่ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 22, 'เพราะเจ้าจะกองถ่านที่ลุกโพลงไว้บนศีรษะของเขา และพระเยโฮวาห์จะทรงให้บําเหน็จแก่เจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 23, 'ลมเหนือไล่ฝนไปเสียฉันใด สีหน้าที่โกรธแค้นก็ไล่ลิ้นที่ส่อเสียดไปเสียฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 24, 'อยู่ที่มุมบนหลังคาเรือนดีกว่าอยู่ในเรือนกว้างขวางร่วมกับหญิงขี้ทะเลาะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 25, 'ข่าวดีจากเมืองไกล ก็เหมือนน้ําเย็นที่ให้แก่คนกระหาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 26, 'คนชอบธรรมที่ยอมแพ้แก่คนชั่วร้าย ก็เหมือนน้ําพุมีโคลนหรือเหมือนน้ําบ่อที่สกปรก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 27, 'ที่จะกินน้ําผึ้งมากก็ไม่ดี ฉะนั้นจึงเป็นการไร้เกียรติเมื่อใครเสาะหาเกียรติสําหรับตนเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 28, 'คนที่ปราศจากการปกครองจิตใจตนเองก็เหมือนเมืองที่ปรักหักพังและไม่มีกําแพง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 1, 'เกียรติยศไม่เหมาะสมกับคนโง่เช่นเดียวกับหิมะในฤดูร้อนและฝนในฤดูเกี่ยว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 2, 'คําสาปแช่งที่ไร้เหตุผลย่อมไม่มาเกาะเช่นเดียวกับนกที่กําลังโผไปมาและนกนางแอ่นที่กําลังบิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 3, 'แส้สําหรับม้า บังเหียนสําหรับลา และไม้เรียวสําหรับหลังคนโง่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 4, 'อย่าตอบคนโง่ตามความโง่ของเขา เกรงว่าเจ้าเองจะเป็นเหมือนเขาเข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 5, 'จงตอบคนโง่ตามความโง่ของเขา เกรงว่าเขาจะทําตัวฉลาดตามการล่อลวงของเขาเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 6, 'บุคคลที่ส่งข่าวไปด้วยมือของคนโง่ก็ตัดเท้าของเขาเองออกและดื่มความเสียหาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 7, 'คําอุปมาที่อยู่ในปากของคนโง่ก็เหมือนขาของคนพิการที่ไม่เท่ากัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 8, 'บุคคลผู้ให้เกียรติแก่คนโง่ก็เหมือนผู้ที่มัดก้อนหินไว้กับสลิง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 9, 'คําอุปมาที่อยู่ในปากของคนโง่ก็เหมือนหนามเข้าอยู่ในมือคนขี้เมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 10, 'พระเจ้ายิ่งใหญ่ผู้ทรงสร้างสิ่งสารพัดได้ทรงให้บําเหน็จแก่ทั้งคนโง่และคนละเมิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 11, 'คนโง่ที่ทําความโง่ซ้ําแล้วซ้ําอีกก็เหมือนสุนัขที่กลับไปหาสิ่งที่มันสํารอกออกมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 12, 'ท่านเห็นคนที่คิดว่าตัวเองฉลาดหรือ ยังมีหวังในคนโง่ได้มากกว่าในคนเช่นนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 13, 'คนเกียจคร้านพูดว่า “มีสิงโตอยู่ตามหนทาง มีสิงโตอยู่ตามถนน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 14, 'ประตูหันไปมาด้วยบานพับของมันฉันใด คนเกียจคร้านก็ทําอย่างนั้นบนที่นอนของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 15, 'คนเกียจคร้านฝังมือของเขาไว้ในอกเสื้อ เขาเหน็ดเหนื่อยที่จะนํามือกลับมาที่ปากของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 16, 'คนเกียจคร้านเห็นว่าตัวเองฉลาดกว่าคนเจ็ดคนที่ตอบได้อย่างหลักแหลม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 17, 'บุคคลที่กําลังผ่านไปและเข้ายุ่งในการทะเลาะวิวาทซึ่งไม่ใช่เรื่องของเขาเองก็เหมือนคนจับหูสุนัข');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 18, 'คนบ้าที่โยนดุ้นไฟ ลูกธนูและความตายออกไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 19, 'ก็เหมือนกับคนที่ล่อลวงเพื่อนบ้านของเขาและกล่าวว่า “ข้าล้อเล่นเท่านั่นเอง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 20, 'ที่ไหนที่ไม่มีฟืน ไฟก็ดับ และที่ไหนที่ไม่มีคนซุบซิบ การทะเลาะวิวาทก็หยุดไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 21, 'ถ่านเป็นเชื้อเพลิง และฟืนเป็นเชื้อไฟฉันใด คนที่มักทะเลาะวิวาทก็เป็นเชื้อการวิวาทฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 22, 'ถ้อยคําของผู้กระซิบนินทาก็เหมือนบาดแผล มันลงไปยังส่วนข้างในของร่างกาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 23, 'ริมฝีปากที่ร้อนรนกับใจที่ชั่วร้ายก็เหมือนขี้เงินอยู่บนภาชนะดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 24, 'บุคคลที่เกลียดผู้อื่นก็สอพลอด้วยริมฝีปากของตน และเก็บความหลอกลวงไว้ในใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 25, 'เมื่อเขาพูดจาไพเราะน่าฟังอย่าเชื่อเขา เพราะมีสิ่งน่าเกลียดน่าชังเจ็ดอย่างอยู่ในใจของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 26, 'ถึงแม้เขาจะปิดความเกลียดชังของเขาไว้ด้วยความหลอกลวง ความชั่วร้ายของเขาจะเผยออกต่อหน้าที่ประชุมทั้งหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 27, 'บุคคลที่ขุดหลุมพราง เขาจะตกลงไปเอง ผู้ใดให้ก้อนหินกลิ้งมา มันจะกลับทับเขาเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 28, 'ลิ้นที่มุสาเกลียดชังผู้ที่มันทําลาย และปากที่ป้อยอก็ทําความพินาศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 1, 'อย่าคุยอวดถึงพรุ่งนี้ เพราะเจ้าไม่ทราบว่าวันหนึ่งๆจะนําอะไรมาให้บ้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 2, 'จงให้คนอื่นยกย่องเจ้า และไม่ใช่ปากของเจ้าเอง ให้คนต่างถิ่นยกย่อง ไม่ใช่ริมฝีปากของเจ้าเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 3, 'หินก็หนัก และทรายก็มีน้ําหนัก แต่ความกริ้วโกรธของคนโง่ก็หนักยิ่งกว่าทั้งสองอย่างนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 4, 'ความพิโรธก็ดุร้าย ความโกรธก็รุนแรง แต่ใครจะยืนต่อหน้าความริษยาได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 5, 'ว่ากันต่อหน้าดีกว่ารักกันลับๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 6, 'บาดแผลที่มิตรทําก็สุจริต แต่การจุบของศัตรูนั้นก็หลอกลวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 7, 'บุคคลที่อิ่มแล้ว รวงผึ้งก็น่าเบื่อ แต่สําหรับผู้ที่หิว ทุกสิ่งที่ขมก็กลับหวาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 8, 'คนที่เจิ่นไปจากบ้านของตนก็เหมือนนกที่เจิ่นไปจากรังของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 9, 'น้ํามันและน้ําหอมกระทําให้ใจยินดี และคําเตือนสติอันอ่อนหวานของเพื่อนก็เป็นที่ให้ชื่นใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 10, 'อย่าทอดทิ้งมิตรของเจ้าเอง และมิตรของบิดาเจ้า และอย่าเข้าไปในเรือนพี่น้องของเจ้าในวันที่เจ้าประสบหายนะ เพราะเพื่อนบ้านสักคนที่อยู่ใกล้ดีกว่าพี่น้องคนหนึ่งที่อยู่ห่างไกล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 11, 'บุตรชายของเราเอ๋ย จงฉลาดและกระทําให้ใจของเรายินดี เพื่อเราจะตอบบุคคลที่ตําหนิเราได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 12, 'คนหยั่งรู้เห็นอันตรายและซ่อนตัวของเขาเสีย แต่คนเขลาเดินเรื่อยไปและรับโทษ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 13, 'จงยึดเสื้อผ้าของเขาไว้ เมื่อเขาเป็นประกันให้คนอื่น และยึดตัวเขาไว้ เมื่อเขารับประกันหญิงต่างด้าว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 14, 'บุคคลที่ตื่นแต่เช้ามืดไปอวยพรเพื่อนบ้านด้วยเสียงดัง เขากลับจะเห็นว่าเป็นคําสาปแช่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 15, 'ฝนย้อยหยดไม่หยุดในวันที่ฝนตกฉันใด ผู้หญิงที่ขี้ทะเลาะก็เหมือนกันฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 16, 'ผู้ใดที่จะยับยั้งเธอก็เหมือนยับยั้งลมหรือกอบน้ํามันด้วยมือขวา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 17, 'เหล็กลับเหล็กให้แหลมคมได้ คนหนึ่งคนใดก็ลับหน้าตาของเพื่อนให้หลักแหลมขึ้นได้ฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 18, 'บุคคลที่ดูแลต้นมะเดื่อจะได้กินผลของมัน และบุคคลที่ระแวดระวังนายของตนจะได้รับเกียรติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 19, 'ในน้ําคนเห็นหน้าคนฉันใด จิตใจของคนก็ส่อคนฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 20, 'นรกและแดนพินาศไม่รู้จักอิ่ม ตาของคนเราก็ไม่รู้จักอิ่มเช่นกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 21, 'เบ้ามีไว้สําหรับเงิน เตาถลุงมีไว้สําหรับทองคํา คําสรรเสริญของคนจะพิสูจน์คน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 22, 'ถึงแม้เจ้าจะเอาคนโง่ใส่ครกตําด้วยสากพร้อมกับข้าวสาลี ความโง่เขลาของเขาก็ยังไม่พรากจากเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 23, 'จงรู้ความทุกข์สุขของฝูงแพะแกะของเจ้าให้ดี และจงเอาใจใส่ฝูงวัวของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 24, 'เพราะความมั่งคั่งไม่ได้ทนอยู่ได้เป็นนิตย์ และมงกุฎทนอยู่ได้ทุกชั่วอายุหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 25, 'หญ้าแห้งปรากฏแล้ว และหญ้างอกใหม่ปรากฏขึ้นมา และเขาเก็บผักหญ้าต่างๆที่ภูเขากันแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 26, 'ลูกแกะจะให้เสื้อผ้าแก่เจ้า และแพะก็จะเป็นค่านา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 27, 'และเจ้าจะมีนมแพะเป็นอาหารแก่เจ้าเพียงพอ ทั้งเป็นอาหารแก่ครัวเรือนของเจ้า และเป็นเครื่องยังชีพสาวใช้ของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 1, 'คนชั่วร้ายก็หนีเมื่อไม่มีใครไล่ตาม แต่คนชอบธรรมก็กล้าหาญอย่างสิงโต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 2, 'เมื่อแผ่นดินละเมิดก็มีผู้ครอบครองเพิ่มขึ้น แต่ด้วยคนที่มีความเข้าใจและความรู้ เสถียรภาพของแผ่นดินนั้นจะยั่งยืนนาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 3, 'คนยากจนที่บีบบังคับคนยากจนก็เหมือนฝนที่ซัดลงมา แต่ไม่ให้อาหาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 4, 'บรรดาผู้ที่ทอดทิ้งพระราชบัญญัติย่อมยกย่องคนชั่วร้าย แต่บรรดาผู้ที่รักษาพระราชบัญญัติย่อมคอยต่อสู้เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 5, 'คนชั่วร้ายไม่เข้าใจความยุติธรรม แต่บรรดาผู้ที่แสวงหาพระเยโฮวาห์เข้าใจสิ่งสารพัด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 6, 'คนยากจนที่ดําเนินในความเที่ยงธรรมของเขา ก็ดีกว่าคนมั่งคั่งที่คดโกงในทางของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 7, 'บุคคลที่รักษาพระราชบัญญัติเป็นบุตรชายที่ฉลาด แต่เพื่อนของคนตะกละนําความอับอายมาถึงบิดาเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 8, 'บุคคลที่เพิ่มทรัพย์ศฤงคารของตนด้วยดอกเบี้ยและเงินเพิ่ม พระเจ้าจะทรงเอาทรัพย์นั้นไปจากเขาเพื่อเพิ่มแก่คนที่จะเอ็นดูคนยากจน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 9, 'ถ้าผู้ใดหันใบหูไปเสียจากการฟังพระราชบัญญัติ แม้คําอธิษฐานของเขาก็เป็นสิ่งที่น่าสะอิดสะเอียน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 10, 'บุคคลผู้นําคนชอบธรรมเข้าไปในทางชั่ว ก็จะตกลงในหลุมของเขาเอง แต่คนเที่ยงธรรมจะมีสิ่งของอย่างดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 11, 'คนมั่งคั่งก็ฉลาดตามการล่อลวงของเขาเอง แต่คนยากจนที่มีความเข้าใจก็รู้จักเขาอย่างแจ่มแจ้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 12, 'เมื่อคนชอบธรรมชื่นชมยินดี ความรุ่งเรืองก็มีมากขึ้น แต่เมื่อคนชั่วร้ายทวีอํานาจ คนก็พากันซ่อนตัวเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 13, 'บุคคลที่ซ่อนความบาปของตนจะไม่จําเริญ แต่บุคคลที่สารภาพและทิ้งความชั่วเสียจะได้ความกรุณา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 14, 'คนที่เกรงกลัวอยู่เสมอก็เป็นสุข แต่บุคคลที่ทําใจตนให้กระด้างจะตกในความลําบากยากเย็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 15, 'ผู้ครอบครองที่ชั่วร้ายเหนือคนยากจนก็เหมือนสิงโตคํารามหรือหมีที่กําลังเข้าต่อสู้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 16, 'ผู้ครอบครองที่ขาดความเข้าใจก็เป็นผู้บีบบังคับที่ดุร้าย แต่บุคคลที่เกลียดความโลภย่อมยืดปีเดือนของเขาออกไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 17, 'คนใดที่ทํารุนแรงต่อโลหิตของคนอื่น คนนั้นก็เป็นคนหลบหนีอยู่จนลงไปสู่ปากแดน อย่าให้ใครช่วยเขาเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 18, 'บุคคลที่ดําเนินในความเที่ยงธรรมจะได้รับการช่วยให้รอด แต่คนที่มีเล่ห์กะเท่ห์ในทางทั้งหลายของเขาเองจะล้มลงทันที');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 19, 'บุคคลที่ไถไร่นาของตนจะได้อาหารมากมาย แต่ผู้ที่ติดตามคนไร้ค่าจะยิ่งจนลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 20, 'คนที่สัตย์ซื่อจะได้รับพรมากมาย แต่ผู้ที่รีบมั่งคั่งจะไม่มีโทษหามิได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 21, 'ซึ่งจะเห็นแก่หน้าคนใดก็ไม่ดี คนนั้นอาจจะละเมิดเพราะอาหารชิ้นหนึ่งก็เป็นได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 22, 'คนที่เร่งหาทรัพย์ศฤงคารก็มีนัยน์ตาชั่ว และไม่ทราบว่าความขัดสนจะมาถึงเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 23, 'บุคคลที่ขนาบคนหนึ่งคนใด ทีหลังเขาจะได้รับความชอบมากกว่าคนที่ป้อยอด้วยลิ้นของตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 24, 'บุคคลที่ขโมยของของบิดาหรือมารดาของตน และกล่าวว่า “อย่างนี้ไม่ละเมิด” เขาก็เป็นเพื่อนของคนทําลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 25, 'คนใจเย่อหยิ่งเร้าให้เกิดการวิวาท แต่ผู้ที่วางใจในพระเยโฮวาห์จะเจริญขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 26, 'บุคคลที่วางใจในจิตใจของตัวเป็นคนโง่ แต่บุคคลที่ดําเนินในปัญญาจะได้รับการช่วยให้พ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 27, 'บุคคลที่ให้แก่คนยากจนจะไม่รู้จักการขัดสน แต่บุคคลที่ปิดตาของเขาเสียจากการนี้จะได้รับการสาปแช่งมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 28, 'เมื่อคนชั่วร้ายมีอํานาจขึ้น คนก็ซ่อนตัวเสีย แต่เมื่อเขาทั้งหลายพินาศไป คนชอบธรรมก็เพิ่มขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 1, 'บุคคลที่ถูกตักเตือนบ่อยๆ แต่ยังทําคอแข็ง ประเดี๋ยวจะถูกทําลาย จึงรักษาไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 2, 'เมื่อคนชอบธรรมทวีอํานาจ ประชาชนก็เปรมปรีดิ์ แต่เมื่อคนชั่วร้ายครอบครอง ประชาชนก็คร่ําครวญ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 3, 'บุคคลผู้รักปัญญาย่อมทําให้บิดาของเขายินดี แต่ผู้ที่คบค้าหญิงแพศยาก็ผลาญทรัพย์สิ่งของของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 4, 'กษัตริย์ทรงให้เสถียรภาพแก่แผ่นดินด้วยความยุติธรรม แต่องค์ที่ทรงรับของกํานัลก็ทําให้แผ่นดินย่อยยับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 5, 'คนที่ป้อยอเพื่อนบ้านของตนย่อมกางข่ายไว้ดักเท้าของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 6, 'คนชั่วติดกับอยู่ในการละเมิดของตน แต่คนชอบธรรมร้องเพลงและเปรมปรีดิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 7, 'คนชอบธรรมรู้จักสิทธิของคนยากจน แต่คนชั่วร้ายไม่เข้าใจความรู้อย่างนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 8, 'คนมักเยาะเย้ยกระทําบ้านเมืองให้เข้าบ่วง แต่ปราชญ์แปรความโกรธเกรี้ยวไปเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 9, 'ถ้าปราชญ์มีเรื่องโต้เถียงกับคนโง่ ไม่ว่าเขาดุเดือดหรือหัวเราะ ก็ไม่มีวันสงบลงได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 10, 'คนที่กระหายเลือดย่อมเกลียดคนเที่ยงธรรม แต่คนชอบธรรมแสวงหาชีวิตของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 11, 'คนโง่ย่อมให้ความคิดของเขาพลุ่งออกมาเต็มที่ แต่ปราชญ์ย่อมยับยั้งความคิดไว้จนภายหลัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 12, 'ถ้าผู้ครอบครองเชื่อฟังความเท็จ ข้าราชการของท่านก็พลอยชั่วร้ายทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 13, 'คนยากจนและคนหลอกลวงมักมาประจัญหน้ากันเสมอ และพระเยโฮวาห์ประทานความสว่างแก่ตาของคนทั้งสอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 14, 'กษัตริย์ที่พิพากษาคนยากจนด้วยความสัตย์ซื่อ พระที่นั่งของพระองค์จะสถาปนาอยู่เป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 15, 'ไม้เรียวและคําตักเตือนทําให้เกิดปัญญา แต่ถ้าปล่อยเด็กไว้แต่ลําพังจะนําความอับอายมาสู่มารดาของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 16, 'เมื่อคนชั่วร้ายเพิ่มพูน การละเมิดก็ทวีขึ้น แต่คนชอบธรรมจะมองดูความล่มจมของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 17, 'จงฝึกสอนบุตรชายของเจ้า และเขาจะให้เจ้าได้หยุดพัก เออ เขาจะให้ความปีติยินดีแก่ใจของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 18, 'ที่ใดๆที่ไม่มีนิมิต ประชาชนก็พินาศ แต่คนที่รักษาพระราชบัญญัติจะเป็นสุข');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 19, 'สักแต่ใช้คําพูดเท่านั้นจะฝึกสอนคนใช้ไม่ได้ เพราะถึงแม้เขาเข้าใจ แต่เขาก็จะไม่ตอบสนอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 20, 'เจ้าเห็นคนที่ปากไวหรือ ยังมีหวังในคนโง่มากกว่าเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 21, 'บุคคลที่ทะนุถนอมคนใช้ของตนตั้งแต่เด็กๆ ที่สุดจะเห็นว่าเขากลายเป็นบุตรชายของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 22, 'คนเจ้าโมโหย่อมเร้าการวิวาท และคนที่มักโกรธก็เป็นเหตุให้มีการละเมิดมากขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 23, 'ความเย่อหยิ่งของคนนําเขาให้ต่ําลง แต่คนที่มีใจถ่อมจะได้รับเกียรติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 24, 'ผู้เข้าส่วนกับขโมยก็เกลียดชังชีวิตของตน เขาได้ยินคําสาปแช่ง แต่ไม่เปิดเผยอะไรเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 25, 'การกลัวมนุษย์ก็เป็นบ่วงดักไว้ แต่บุคคลที่วางใจในพระเยโฮวาห์ก็จะปลอดภัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 26, 'คนเป็นอันมากแสวงหาความพอใจจากผู้ครอบครอง แต่ทุกคนจะได้ความยุติธรรมจากพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 27, 'คนไม่ชอบธรรมเป็นที่สะอิดสะเอียนแก่คนชอบธรรม แต่คนเที่ยงธรรมในทางของเขากลับเป็นที่สะอิดสะเอียนแก่คนชั่วร้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 1, 'ถ้อยคําของอากูร์ บุตรชายของยาเคห์ คือคําพยากรณ์นั้น ชายคนนั้นพูดกับอิธีเอล คือกับอิธีเอลและอูคาล ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 2, 'แท้จริงข้าก็เขลากว่าคนใด ข้าไม่มีความเข้าใจอย่างมนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 3, 'ข้าไม่เคยเรียนรู้ปัญญา ทั้งไม่มีความรู้ขององค์ผู้บริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 4, 'ใครเล่าได้ขึ้นไปยังสวรรค์หรือลงมา ใครเล่าได้รวบรวมลมไว้ในกํามือของท่าน ใครเล่าได้เอาเครื่องแต่งกายห่อห้วงน้ําไว้ ใครเล่าได้สถาปนาที่สุดปลายแห่งแผ่นดินโลกไว้ นามของผู้นั้นว่ากระไร และนามบุตรชายของผู้นั้นว่ากระไร ถ้าท่านบอกได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 5, 'พระวจนะทุกคําของพระเจ้านั้นก็บริสุทธิ์ พระองค์ทรงเป็นโล่แก่บรรดาผู้ที่วางใจในพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 6, 'อย่าเพิ่มอะไรเข้ากับพระวจนะของพระองค์ เกรงว่าพระองค์จะทรงขนาบเจ้า และเขาจะเห็นว่าเจ้าเป็นคนมุสา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 7, 'ข้าพระองค์ขอสองสิ่งจากพระองค์ ขออย่าทรงปฏิเสธที่จะให้ข้าพระองค์ก่อนข้าพระองค์ตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 8, 'ขอให้ความไร้สาระและความมุสาไกลจากข้าพระองค์ ขออย่าประทานความยากจนหรือความมั่งคั่งแก่ข้าพระองค์ ขอเลี้ยงข้าพระองค์ด้วยอาหารที่พอดีแก่ข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 9, 'เกรงว่าข้าพระองค์จะอิ่ม และปฏิเสธพระองค์ แล้วพูดว่า “พระเยโฮวาห์เป็นผู้ใดเล่า” หรือเกรงว่าข้าพระองค์จะยากจนและขโมย และออกพระนามพระเจ้าของข้าพระองค์อย่างไร้ค่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 10, 'อย่ากล่าวหาคนใช้ให้นายของเขาฟัง เกรงว่าเขาจะแช่งเจ้า และเจ้าจะต้องมีความผิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 11, 'มีคนชั่วอายุหนึ่งที่แช่งบิดาของตน และไม่อวยพรแก่มารดาของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 12, 'มีคนชั่วอายุหนึ่งที่บริสุทธิ์ในสายตาของตนเอง แต่ยังมิได้รับการชําระล้างให้พ้นจากความโสโครกของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 13, 'มีคนชั่วอายุหนึ่ง โอ ตาของเขาสูงจริงหนอ และหนังตาของเขาสูงยิ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 14, 'มีคนชั่วอายุหนึ่งที่ฟันของเขาเป็นเหมือนดาบ เขี้ยวของเขาเป็นเหมือนมีด เพื่อจะกลืนกินคนยากจนเสียจากแผ่นดินโลก และคนขัดสนเสียจากท่ามกลางมนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 15, 'ปลิงมีลูกตัวเมียสองตัว มันร้องว่า “ให้ ให้” แต่สิ่งสามสิ่งนี้ไม่เคยอิ่ม เออ สี่สิ่งไม่เคยพูดว่า “พอแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 16, 'คือแดนผู้ตาย ครรภ์ของหญิงหมัน แผ่นดินโลกที่ไม่อิ่มน้ํา และไฟที่ไม่เคยพูดว่า “พอแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 17, 'นัยน์ตาที่เยาะเย้ยบิดาและดูถูกไม่ฟังมารดาจะถูกนกกาแห่งหุบเขาจิกออกและนกอินทรีหนุ่มจะกินเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 18, 'มีสามสิ่งที่ประหลาดเหลือสําหรับข้า เออ สี่สิ่งที่ข้าไม่เข้าใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 19, 'คือท่าทีของนกอินทรีในฟ้า ท่าทีของงูบนหิน ท่าทีของเรือในท้องทะเล และท่าทีของชายกับหญิงสาว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 20, 'นี่เป็นทางของหญิงผู้ล่วงประเวณีคือ นางรับประทาน และนางเช็ดปาก และนางพูดว่า “ฉันไม่ได้ทําผิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 21, 'แผ่นดินโลกสั่นสะเทือนอยู่ใต้สามสิ่ง เออ มันทนอยู่ใต้สี่สิ่งไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 22, 'คือทาสเมื่อได้เป็นกษัตริย์ คนโง่เมื่อกินอิ่ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 23, 'เมื่อหญิงที่น่าเกลียดชังได้สามี และสาวใช้ที่ได้เป็นนายแทนนายหญิงของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 24, 'มีสี่สิ่งในแผ่นดินโลกที่เล็กเหลือเกิน แต่มีปัญญามากเหลือล้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 25, 'มด เป็นประชากรที่ไม่แข็งแรง แต่มันยังเตรียมอาหารของมันไว้ในฤดูแล้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 26, 'ตัวกระจงผา เป็นประชากรที่ไม่มีกําลัง แต่มันยังสร้างบ้านของมันในซอกหิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 27, 'ตั๊กแตนไม่มีกษัตริย์ แต่มันยังเดินขบวนเป็นแถว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 28, 'แมงมุมนั้น เจ้าเอามือจับได้ แต่มันยังอยู่ในพระราชวัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 29, 'มีสามสิ่งที่สง่างามมากในท่าเดิน เออ มีสี่สิ่งที่ย่างเท้าของมันผ่าเผย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 30, 'คือสิงโต ซึ่งเป็นสัตว์ที่มีกําลังมากที่สุด และไม่ยอมหันหลังกลับเพราะสิ่งใดเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 31, 'สุนัขล่าเนื้อ แพะผู้ด้วย และกษัตริย์ผู้ซึ่งไม่มีใครก่อการกบฏ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 32, 'ถ้าเจ้าเป็นคนโง่ยกย่องตนเอง หรือคิดแผนการชั่วร้าย จงเอามือปิดปากของเจ้าเสียเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 33, 'เพราะเมื่อกวนน้ํานมก็ได้เนยข้น เมื่อบีบจมูกก็ได้โลหิต และเมื่อกวนโทโสก็ได้การวิวาท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 1, 'ถ้อยคําของกษัตริย์เลมูเอล คือคําพยากรณ์ที่พระราชมารดาได้สอนไว้แก่พระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 2, 'อะไรเล่า ลูกแม่เอ๋ย อะไรเล่า ลูกแห่งท้องแม่เอ๋ย อะไรเล่า ลูกแห่งคําปฏิญาณของแม่เอ๋ย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 3, 'อย่าให้กําลังของเจ้าแก่ผู้หญิง อย่าให้ทางของเจ้าแก่ผู้ทําลายกษัตริย์ใดๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 4, 'โอ เลมูเอลเอ๋ย ไม่สมควรที่กษัตริย์ ไม่สมควรที่กษัตริย์จะเสวยเหล้าองุ่น หรือผู้ที่ครอบครองจะดื่มสุรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 5, 'เกรงว่าเขาจะดื่มและหลงลืมตัวบทกฎหมายนั้นเสีย และคําวินิจฉัยที่มีต่อคนทุกข์ยากก็ไขว้เขวไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 6, 'จงให้สุราแก่ผู้ที่กําลังจะพินาศ และเหล้าองุ่นแก่ผู้ที่ทุกข์ใจอย่างขมขื่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 7, 'จงให้เขาดื่มและลืมความยากจนของเขา เพื่อจะจดจําความระทมทุกข์ของเขาไม่ได้อีกต่อไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 8, 'จงอ้าปากของเจ้าแทนคนใบ้ เพื่อสิทธิของทุกคนที่ถูกทิ้งร้างอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 9, 'จงอ้าปากของเจ้า พิพากษาอย่างชอบธรรม รักษาสิทธิของคนจนและคนขัดสนให้คงอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 10, 'ใครจะพบภรรยาที่ดี เพราะค่าของเธอประเสริฐยิ่งกว่าทับทิมมากนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 11, 'จิตใจของสามีเธอก็วางใจในเธอ และสามีจะไม่ขาดกําไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 12, 'เธอจะทําความดีให้เขา ไม่ทําความร้าย ตลอดชีวิตของเธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 13, 'เธอแสวงหาขนแกะและป่าน และทํางานด้วยมืออย่างเต็มใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 14, 'เธอเป็นเหมือนกําปั่นของพ่อค้า เธอนําอาหารของเธอมาจากที่ที่ไกล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 15, 'เธอลุกขึ้นตั้งแต่ยังมืดอยู่และจัดอาหารให้ครัวเรือนของเธอ และจัดส่วนแบ่งให้แก่สาวใช้ของเธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 16, 'เธอพิเคราะห์ดูไร่นาแล้วก็ซื้อไว้ ด้วยผลแห่งน้ํามือของเธอ เธอปลูกสวนองุ่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 17, 'เธอคาดเอวของเธอด้วยกําลัง และกระทําให้แขนของเธอเข้มแข็ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 18, 'เธอรู้ว่าสินค้าของเธอเป็นของที่ดี กลางคืนตะเกียงของเธอก็ไม่ดับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 19, 'เธอยื่นมือออกจับไน และมือของเธอจับเครื่องปั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 20, 'เธอหยิบยื่นให้คนยากจน เออ เธอยื่นมือออกช่วยคนขัดสน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 21, 'เธอไม่กลัวหิมะมาทําอันตรายแก่คนในครัวเรือนของเธอ เพราะบรรดาคนในครัวเรือนของเธอสวมเสื้อสีแดงสด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 22, 'เธอทําผ้าปูสําหรับเธอด้วยสิ่งทอ เสื้อผ้าของเธอทําด้วยผ้าลินินและผ้าสีม่วง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 23, 'สามีของเธอเป็นที่รู้จักที่ประตูเมือง เมื่อท่านนั่งอยู่ในหมู่พวกผู้ใหญ่ของแผ่นดินนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 24, 'เธอทําเครื่องแต่งกายด้วยผ้าลินินไว้ขาย เธอส่งผ้าคาดเอวให้แก่พ่อค้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 25, 'กําลังและเกียรติยศเป็นเครื่องนุ่งห่มของเธอ เธอจะปลื้มปีติในอนาคต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 26, 'เธออ้าปากกล่าวด้วยสติปัญญา และกฎเกณฑ์แห่งความกรุณาก็อยู่ที่ลิ้นของเธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 27, 'เธอดูแลการงานในครัวเรือนของเธอ และไม่รับประทานอาหารแห่งความเกียจคร้าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 28, 'ลูกๆของเธอตื่นขึ้นมาก็ชมเชยเธอ สามีของเธอก็ยกย่องเธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 29, 'ว่า “สตรีเป็นอันมากทําอย่างดีเลิศ แต่เธอเลิศยิ่งกว่าเขาทั้งหมด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 30, 'เสน่ห์เป็นของหลอกลวง และความงามก็เปล่าประโยชน์ แต่สตรียําเกรงพระเยโฮวาห์จะได้รับการยกย่อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 31, 'จงให้เธอรับผลแห่งน้ํามือของเธอ และให้การงานของเธอยกย่องเธอที่ประตูเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 1, 'ถ้อยคําของปัญญาจารย์ ผู้เป็นบุตรชายของดาวิด กษัตริย์ในเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 2, 'ปัญญาจารย์กล่าวว่า อนิจจัง อนิจจัง อนิจจัง อนิจจัง สารพัดอนิจจัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 3, 'ที่มนุษย์ทํางานตรากตรําภายใต้ดวงอาทิตย์ เขาได้ประโยชน์อะไรจากงานทั้งสิ้นที่เขาทํานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 4, 'ชั่วอายุหนึ่งล่วงไป และอีกชั่วอายุหนึ่งก็มา แต่แผ่นดินโลกคงเดิมอยู่เป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 5, 'ดวงอาทิตย์ขึ้น และดวงอาทิตย์ตก แล้วรีบไปถึงที่ซึ่งขึ้นมานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 6, 'ลมพัดไปทางใต้ แล้วเวียนกลับไปทางเหนือ ลมพัดเวียนไปเวียนมา แล้วลมพัดกลับตามทางเวียนของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 7, 'แม่น้ําทั้งหลายไหลไปสู่ทะเล แต่ทะเลก็ไม่เต็ม แม่น้ําไหลไปสู่ที่ใดก็ไหลไปสู่ที่นั่นอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 8, 'สารพัดเหนื่อยกันหมด คนใดๆก็พูดไม่ออก นัยน์ตาก็ดูไม่อิ่มหรือหูก็ฟังไม่เต็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 9, 'สิ่งที่เป็นขึ้นแล้วคือสิ่งที่จะเป็นขึ้นอีก สิ่งที่ทํากันแล้วคือสิ่งที่จะต้องทํากันอีก และไม่มีสิ่งใดใหม่ภายใต้ดวงอาทิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 10, 'มีสักสิ่งหนึ่งหรือที่เขาจะพูดได้ว่า “ดูซี สิ่งนี้ใหม่” สิ่งนั้นมีอยู่แล้วในสมัยก่อนเราทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 11, 'ไม่มีการจดจําถึงสมัยก่อนและจะไม่มีการจดจําสิ่งหลังๆที่จะเกิดมาในท่ามกลางบรรดาผู้ที่มาภายหลัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 12, 'ข้าพเจ้า ปัญญาจารย์ เคยเป็นกษัตริย์เหนืออิสราเอลในกรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 13, 'และข้าพเจ้าตั้งใจเสาะและแสวงหาโดยสติปัญญาถึงสิ่งสารพัดที่กระทํากันภายใต้ฟ้าสวรรค์ เป็นเรื่องยากลําบากซึ่งพระเจ้าประทานให้บุตรของมนุษย์ทํากันอยู่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 14, 'ข้าพเจ้าเคยเห็นการทั้งปวงซึ่งเขากระทํากันภายใต้ดวงอาทิตย์ และดูเถิด สารพัดก็เป็นความว่างเปล่าและความวุ่นวายใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 15, 'อะไรที่คดจะทําให้ตรงไม่ได้ และอะไรที่ขาดอยู่จะนับให้ครบไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 16, 'ข้าพเจ้ารําพึงในใจของข้าพเจ้าว่า “ดูเถิด ข้าพเจ้าได้มาถึงฐานะที่สูงส่ง และได้มีสติปัญญามากกว่าใครๆที่เคยอยู่ในกรุงเยรูซาเล็มก่อนข้าพเจ้า เออ ใจข้าพเจ้าก็เจนจัดในสติปัญญาและความรู้อย่างยิ่ง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 17, 'ข้าพเจ้าก็ตั้งใจรู้สติปัญญา รู้ความบ้าบอ และความเขลา ข้าพเจ้าสังเกตเห็นว่าเรื่องนี้ก็เป็นแต่กินลมกินแล้งด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 18, 'เพราะในสติปัญญามากมายก็มีความทุกข์ระทมมาก และบุคคลที่เพิ่มความรู้ก็เพิ่มความเศร้าโศก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 1, 'ข้าพเจ้ารําพึงในใจว่า “มาเถอะ มาลองสนุกสนานกันดู เอ้า จงสนุกสบายใจไป” แต่ ดูเถิด เรื่องนี้ก็อนิจจังเช่นกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 2, 'ข้าพเจ้าพูดเกี่ยวกับการหัวเราะว่า “บ้าๆบอๆ” และกล่าวถึงความสนุกสนานว่า “มีประโยชน์อะไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 3, 'ข้าพเจ้าครุ่นคิดในใจว่าจะทําอย่างไรกายจึงจะคึกคักด้วยเหล้าองุ่น และใจยังคงแนะนําข้าพเจ้าด้วยสติปัญญา และจะยึดความเขลาไว้อย่างไร จนข้าพเจ้าจะเห็นได้ว่า อะไรจะดีสําหรับให้บุตรทั้งหลายของมนุษย์กระทําภายใต้ท้องฟ้าตลอดชีวิตของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 4, 'ข้าพเจ้ากระทําการใหญ่โต ข้าพเจ้าได้สร้างเรือนหลายหลัง และปลูกสวนองุ่นหลายแปลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 5, 'ข้าพเจ้าทําสวนหย่อนใจและสวนผลไม้หลายแห่ง ปลูกต้นไม้มีผลทุกอย่างไว้ในสวนเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 6, 'ข้าพเจ้าสร้างสระน้ําหลายสระสําหรับตัวเอง เพื่อจะใช้น้ําในสระนั้นรดหมู่ไม้ที่กําลังงอกงาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 7, 'ข้าพเจ้าซื้อทาสชายหญิงไว้ มีทาสเกิดขึ้นในบ้าน ข้าพเจ้ายังมีฝูงวัวฝูงแพะแกะเป็นสมบัติมากกว่าของบรรดาคนที่อยู่ในกรุงเยรูซาเล็มก่อนข้าพเจ้าด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 8, 'ข้าพเจ้าสะสมเงินทองไว้ด้วย และส่ําสมทรัพย์สมบัติอันควรคู่กับกษัตริย์และควรคู่กับเมืองทั้งหลาย ข้าพเจ้ามีนักร้องชายหญิงสําหรับตัว และเครื่องดนตรีทุกอย่าง ซึ่งเป็นสิ่งชอบใจบุตรทั้งหลายของมนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 9, 'ข้าพเจ้าจึงเป็นใหญ่เป็นโตและเพิ่มพูนมากกว่าบรรดาคนที่เคยอยู่มาก่อนข้าพเจ้าในเยรูซาเล็ม และสติปัญญาของข้าพเจ้ายังคงอยู่กับข้าพเจ้าด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 10, 'สิ่งใดๆที่นัยน์ตาของข้าพเจ้าอยากเห็น ข้าพเจ้าก็ไม่ปิดบัง ข้าพเจ้ามิได้ห้ามใจจากความสนุกสนานใดๆ เพราะใจข้าพเจ้าพบความเพลิดเพลินในบรรดางานของข้าพเจ้า และนี่เป็นส่วนของข้าพเจ้าจากการงานทั้งสิ้นของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 11, 'แล้วข้าพเจ้าหันมาดูบรรดาสิ่งที่มือข้าพเจ้ากระทํา และความเหน็ดเหนื่อยที่ข้าพเจ้าทุ่มเทลงไปและ ดูเถิด ทุกอย่างก็เป็นความว่างเปล่าและความวุ่นวายใจ และไม่มีประโยชน์อะไรภายใต้ดวงอาทิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 12, 'ข้าพเจ้าจึงหันมาพิเคราะห์สติปัญญา ความบ้าบอและความเขลา เพราะคนที่มาภายหลังกษัตริย์จะทําอะไรได้บ้าง เขาก็กระทําสิ่งที่เขากระทํากันมานานแล้วนั้นได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 13, 'ข้าพเจ้าเห็นว่าสติปัญญาวิเศษกว่าความเขลา เหมือนความสว่างวิเศษกว่าความมืด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 14, 'คนมีสติปัญญามีตาอยู่ในสมอง แต่คนเขลาเดินในความมืด ถึงกระนั้นข้าพเจ้ายังเห็นว่า เหตุการณ์อย่างเดียวกันเกิดขึ้นแก่เขาทั้งมวล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 15, 'ข้าพเจ้าจึงรําพึงในใจว่า “เหตุการณ์อันใดเกิดแก่คนเขลาฉันใด ก็จะเกิดกับตัวข้าพเจ้าฉันนั้น ถ้ากระนั้นแล้วข้าพเจ้าจะมีสติปัญญามากมายทําไมเล่า” ข้าพเจ้าจึงรําพึงในใจว่า เรื่องนี้ก็อนิจจังเหมือนกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 16, 'เพราะตลอดไปไม่มีใครระลึกถึงคนมีสติปัญญามากกว่าคนเขลา ด้วยเห็นว่าในอนาคตก็ลืมกันไปหมดแล้ว แล้วคนมีสติปัญญาตายอย่างไร ก็เหมือนคนเขลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 17, 'ข้าพเจ้าจึงเกลียดชีวิต เพราะว่าการงานที่เขาทํากันภายใต้ดวงอาทิตย์ก่อความสลดใจให้แก่ข้าพเจ้า เพราะสารพัดก็เป็นความว่างเปล่าและความวุ่นวายใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 18, 'เออ ข้าพเจ้าเกลียดการงานทั้งสิ้นของข้าพเจ้า ซึ่งข้าพเจ้าตรากตรําอยู่ภายใต้ดวงอาทิตย์ เพราะข้าพเจ้าจําต้องละการนั้นไว้ให้แก่คนที่มาภายหลังข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 19, 'แล้วใครจะไปทราบว่าเขาคนนั้นจะเป็นคนมีสติปัญญาหรือคนเขลา กระนั้นเขาก็ครอบครองบรรดาการงานของข้าพเจ้า ที่ข้าพเจ้าได้ตรากตรํามาและที่ข้าพเจ้าใช้สติปัญญากระทําภายใต้ดวงอาทิตย์ นี่ก็อนิจจังด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 20, 'ข้าพเจ้าจึงกลับอัดอั้นตันใจนักถึงเรื่องการงานทั้งสิ้นของข้าพเจ้า ซึ่งข้าพเจ้าตรากตรํามาภายใต้ดวงอาทิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 21, 'ด้วยว่ามีคนที่ทํางานโดยใช้สติปัญญา ความรู้ และความชํานาญ แต่แล้วก็ละการนั้นให้เป็นส่วนของอีกคนหนึ่งที่หาได้ออกแรงทําเพื่อการนั้นไม่ นี่ก็อนิจจังด้วยและเลวร้ายยิ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 22, 'เพราะว่าเขาได้อะไรจากบรรดาการงานและความเคร่งเครียดในใจที่เขาต้องตรากตรําภายใต้ดวงอาทิตย์เล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 23, 'ด้วยว่าวันเวลาทั้งหมดของเขามีแต่ความเจ็บปวด และกิจธุระของเขาก่อความสลดใจ ถึงกลางคืนจิตใจของเขาก็ไม่หยุดพักสงบ นี่ก็อนิจจังด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 24, 'สําหรับมนุษย์นั้นไม่มีอะไรดีไปกว่ากินและดื่ม กับการให้จิตใจของเขายินดีในผลดีแห่งการงานของเขา นี่แหละข้าพเจ้าเห็นว่าเป็นมาจากพระหัตถ์ของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 25, 'ด้วยใครจะกินได้ หรือใครจะมีความชื่นบานได้ มากกว่าข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 26, 'เพราะว่าพระเจ้าประทานสติปัญญา ความรู้ และความยินดีให้แก่คนที่พระองค์ทรงพอพระทัยในสายพระเนตรของพระองค์ แต่ส่วนคนบาปนั้นพระองค์ประทานความเหนื่อยยากในการรวบรวมและสะสมให้เพิ่มพูน เพื่อว่าเขาจะได้มอบให้แก่ผู้ที่พอพระทัยต่อพระพักตร์พระเจ้า นี่ก็เป็นความว่างเปล่าและความวุ่นวายใจด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 1, 'มีฤดูกาลสําหรับทุกสิ่ง และมีวาระสําหรับเรื่องราวทุกอย่างภายใต้ฟ้าสวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 2, 'มีวาระเกิด และวาระตาย มีวาระปลูก และวาระถอนสิ่งที่ปลูกทิ้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 3, 'มีวาระฆ่า และวาระรักษาให้หาย มีวาระรื้อทลายลง และวาระก่อสร้างขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 4, 'มีวาระร้องไห้ และวาระหัวเราะ มีวาระไว้ทุกข์ และวาระเต้นรํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 5, 'มีวาระโยนหินทิ้ง และวาระเก็บรวบรวมหิน มีวาระสวมกอด และวาระงดเว้นการสวมกอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 6, 'มีวาระแสวงหา และวาระทําหาย วาระเก็บรักษาไว้ และวาระโยนทิ้งไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 7, 'มีวาระฉีกขาด และวาระเย็บ วาระนิ่งเงียบ และวาระพูด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 8, 'มีวาระรัก และวาระเกลียด วาระสงคราม และวาระสันติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 9, 'คนงานได้กําไรอะไรจากการงานของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 10, 'ข้าพเจ้าเห็นเรื่องยากลําบากซึ่งพระเจ้าประทานให้บุตรทั้งหลายของมนุษย์ทํากันอยู่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 11, 'พระองค์ทรงกระทําให้สรรพสิ่งงดงามตามฤดูกาลของมัน พระองค์ทรงบรรจุโลกไว้ในจิตใจของมนุษย์ เพื่อมนุษย์จะมองไม่เห็นว่าพระเจ้าทรงกระทําอะไรไว้ตั้งแต่เดิมจนกาลสุดปลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 12, 'ข้าพเจ้าทราบแล้วว่า สําหรับเขาไม่มีอะไรที่จะดีไปกว่าเปรมปรีดิ์และกระทําการดีตลอดชีวิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 13, 'และว่าเป็นของประทานจากพระเจ้าแก่มนุษย์ ที่จะให้มนุษย์ได้กินดื่มและเพลิดเพลินในผลดีแห่งบรรดาการงานของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 14, 'ข้าพเจ้าทราบอยู่ว่าสารพัดที่พระเจ้าทรงกระทําก็ดํารงอยู่เป็นนิตย์ จะเพิ่มเติมอะไรเข้าไปอีกก็ไม่ได้ หรือจะชักอะไรออกเสียก็ไม่ได้ พระเจ้าทรงกระทําเช่นนั้น เพื่อให้คนทั้งหลายมีความยําเกรงต่อพระพักตร์พระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 15, 'อะไรๆซึ่งเป็นอยู่ในปัจจุบันก็เป็นอยู่นานมาแล้ว อะไรๆที่จะเป็นมาก็เคยเป็นอยู่นานมาแล้ว และพระเจ้าทรงแสวงหาอะไรๆที่ล่วงไปนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 16, 'ยิ่งกว่านั้นอีก ที่ภายใต้ดวงอาทิตย์ข้าพเจ้าเห็นว่า ในที่ของความยุติธรรมมีความชั่วร้ายอยู่ด้วย และในที่ของความชอบธรรมมีความชั่วช้าอยู่ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 17, 'ข้าพเจ้ารําพึงในใจของข้าพเจ้าว่า “พระเจ้าจะทรงพิพากษาคนชอบธรรมและคนชั่วร้าย เพราะมีกาลกําหนดไว้สําหรับทุกเรื่อง และสําหรับการงานทุกอย่าง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 18, 'ข้าพเจ้ารําพึงในใจของข้าพเจ้าเกี่ยวกับสภาพของบุตรทั้งหลายของมนุษย์ว่า “พระเจ้าทรงทดสอบเขาเพื่อจะสําแดงว่าเขาเป็นเพียงสัตว์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 19, 'เพราะว่าเหตุการณ์ของบุตรทั้งหลายของมนุษย์กับเหตุการณ์ของสัตว์เดียรัจฉานนั้นเหมือนกัน คือเป็นเหตุการณ์อันเดียวกัน ฝ่ายหนึ่งตาย อีกฝ่ายหนึ่งก็ตายเหมือนกัน ทั้งสองมีลมหายใจอย่างเดียวกัน และมนุษย์ไม่มีอะไรดีกว่าสัตว์เดียรัจฉาน เพราะสารพัดก็อนิจจัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 20, 'สารพัดไปยังที่เดียวกัน สารพัดเป็นมาจากผงคลีดิน และสารพัดกลับเป็นผงคลีดินอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 21, 'ใครรู้ว่าจิตวิญญาณของมนุษย์ไปสู่เบื้องบนหรือเปล่า และวิญญาณของสัตว์เดียรัจฉานลงไปสู่พิภพโลกหรือเปล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 22, 'เพราะฉะนั้นข้าพเจ้าจึงเห็นว่า ไม่มีอะไรดีไปกว่าที่มนุษย์จะเปรมปรีดิ์ในการงานของตน ด้วยว่านั่นเป็นส่วนของเขา ใครจะนําเขาให้เห็นว่าอะไรจะเป็นมาภายหลังเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 1, 'ข้าพเจ้าพิจารณาบรรดาการข่มเหงที่เกิดขึ้นภายใต้ดวงอาทิตย์อีก และดูเถิด น้ําตาของผู้ที่ถูกข่มเหง ไม่มีคนเล้าโลมเขา ฝ่ายผู้ข่มเหงเขานั้นกุมอํานาจ แต่หามีผู้ใดเล้าโลมเขาไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 2, 'เพราะฉะนั้นข้าพเจ้ายกย่องคนตายที่ตายไปแล้วมากกว่าคนเป็นที่ยังเป็นอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 3, 'เออ คนที่ยังไม่เป็นมา ที่ไม่เห็นการชั่วที่อุบัติขึ้นภายใต้ดวงอาทิตย์ ก็ยิ่งดีกว่าคนทั้งสองจําพวกนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 4, 'แล้วข้าพเจ้าพิจารณาบรรดาการงานตรากตรําและบรรดาฝีมือในการงาน เพราะเหตุนี้คนก็ถูกเพื่อนบ้านของตนริษยา นี่ก็เป็นความว่างเปล่าและความวุ่นวายใจด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 5, 'คนโง่งอมือ และกินเนื้อของตนเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 6, 'ความสงบสุขกํามือหนึ่งยังดีกว่าการงานตรากตรําสองกํามือและกินลมกินแล้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 7, 'แล้วข้าพเจ้าเห็นอนิจจังภายใต้ดวงอาทิตย์อีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 8, 'คือ คนหนึ่งอยู่ตัวคนเดียว ไม่มีคนอื่น ไม่มีบุตรหรือพี่น้อง แต่เขาทําการงานไม่หยุดหย่อน ตาของเขาไม่เคยอิ่มความมั่งคั่ง เขาไม่เคยคิดว่า “ข้าตรากตรําทํางานและตัวข้าอดๆอยากๆเพื่อผู้ใด” นี่ก็อนิจจังด้วย และเป็นเรื่องเลวร้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 9, 'สองคนก็ดีกว่าคนเดียว เพราะว่าเขาทั้งสองย่อมได้รับผลตอบแทนอย่างดีสําหรับการงานของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 10, 'ด้วยว่าถ้าคนหนึ่งล้มลง อีกคนหนึ่งจะได้พยุงเพื่อนของตนให้ลุกขึ้น แต่วิบัติแก่คนนั้นที่อยู่คนเดียวเมื่อเขาล้มลง เพราะไม่มีผู้อื่นพยุงยกเขาให้ลุกขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 11, 'อนึ่ง ถ้าสองคนนอนอยู่ด้วยกัน เขาก็อบอุ่น แต่ถ้านอนคนเดียวจะอุ่นอย่างไรได้เล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 12, 'แม้คนหนึ่งสู้คนเดียวได้ สองคนจะสู้เขาได้แน่ เชือกสามเกลียวจะขาดง่ายก็หามิได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 13, 'เด็กยากจนและมีสติปัญญาก็ดีกว่ากษัตริย์ชราและโฉดเขลาผู้รับคําแนะนําอีกไม่ได้แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 14, 'เพราะท่านออกมาจากเรือนจําแล้วขึ้นครองราชสมบัติ ในขณะที่มีคนเกิดในราชอาณาจักรของท่านเองกลายเป็นคนจน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 15, 'ข้าพเจ้าพิจารณาบรรดาคนที่มีชีวิตเดินไปเดินมาอยู่ภายใต้ดวงอาทิตย์ ทั้งเด็กคนที่สองนั้นที่จะขึ้นไปแทนท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 16, 'ประชาชนทั้งหลายคือบรรดาผู้ซึ่งอยู่ก่อนนั้นไม่มีที่สิ้นสุด และบรรดาคนที่มาภายหลังก็จะไม่เปรมปรีดิ์ในท่านด้วย แน่นอน นี่ก็เป็นความว่างเปล่าและความวุ่นวายใจด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 1, 'เจ้าจงระวังเท้าของเจ้าเมื่อเจ้าไปยังพระนิเวศของพระเจ้า เพราะการเข้าใกล้ชิดเพื่อจะฟังก็ดีกว่าคนเขลาถวายสักการบูชา ด้วยว่าเขาไม่รู้ว่าตนกําลังทําชั่ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 2, 'อย่าให้ใจของเจ้าเร็วและอย่าให้ปากของเจ้าพูดโพล่งๆต่อเบื้องพระพักตร์พระเจ้า เพราะว่าพระเจ้าทรงสถิตในสวรรค์ และเจ้าอยู่บนแผ่นดินโลก เหตุฉะนั้นเจ้าจงพูดน้อยคํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 3, 'ความฝันจะสําเร็จโดยมีงานมาก และจะรู้จักเสียงคนเขลาได้เพราะการพูดมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 4, 'เมื่อเจ้าปฏิญาณไว้ต่อพระเจ้า อย่าชักช้าที่จะทําตามคําปฏิญาณนั้นให้สําเร็จ เพราะพระองค์หาชอบพระทัยในคนเขลาไม่ จงทําตามที่เจ้าปฏิญาณไว้เถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 5, 'ที่เจ้าจะไม่ปฏิญาณก็ยังดีกว่าที่เจ้าปฏิญาณแล้วไม่ทําตาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 6, 'อย่าให้ปากของเจ้าเป็นเหตุนําตัวเจ้าให้กระทําผิดไป และอย่าพูดต่อหน้าทูตสวรรค์ว่า นี่แหละเป็นความพลั้งเผลอ เหตุไฉนจะให้พระเจ้าทรงพระพิโรธเพราะเสียงพูดของเจ้า แล้วทรงทําลายการงานแห่งน้ํามือของเจ้าเสียเล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 7, 'เพราะว่าเมื่อฝันมากและคําพูดมาก ก็มีอนิจจังต่างๆด้วย แต่เจ้าจงยําเกรงพระเจ้าเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 8, 'ถ้าเจ้าเห็นคนจนในเมืองถูกข่มเหงก็ดี เห็นความยุติธรรมและความเที่ยงธรรมถูกเอาไปเสียก็ดี เจ้าอย่าประหลาดใจในเรื่องนั้น ด้วยว่ามีเจ้าหน้าที่คอยจับตาเจ้าหน้าที่อยู่ แล้วยังมีผู้สูงกว่าอีกชั้นหนึ่งจับตาอยู่เหนือพวกเขาทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 9, 'ยิ่งกว่านั้นอีก ผลประโยชน์แห่งแผ่นดินโลก ก็อยู่ที่เขาเหล่านั้นทั้งหมด กษัตริย์เองก็ได้รับการเลี้ยงดูจากไร่นา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 10, 'คนรักเงินย่อมไม่อิ่มเงิน และคนรักสมบัติไม่รู้จักอิ่มกําไร นี่ก็อนิจจังด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 11, 'เมื่อของดีเพิ่มพูนขึ้น คนกินก็มีคับคั่งขึ้น คนที่เป็นเจ้าของทรัพย์จะได้ประโยชน์อะไร นอกจากจะได้ชมเล่นเป็นขวัญตาเท่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 12, 'การหลับของกรรมกรก็ผาสุก ไม่ว่าเขาจะได้กินน้อยหรือได้กินมาก แต่ความอิ่มท้องของคนมั่งมีก็ไม่ช่วยเขาให้หลับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 13, 'ยังมีสิ่งเลวร้ายอันน่าสลดใจอีกอย่างหนึ่งที่ข้าพเจ้าเห็นภายใต้ดวงอาทิตย์ คือทรัพย์สมบัติที่เจ้าของได้เก็บไว้จนเกิดเป็นภัยแก่ตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 14, 'และทรัพย์สมบัตินั้นสูญเสียไปด้วยเรื่องทุกข์ยากลําบากอันชั่วร้าย และเขาให้กําเนิดบุตรชายคนหนึ่ง แต่ไม่มีอะไรในมือเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 15, 'เขาได้คลอดมาจากครรภ์มารดาฉันใด เขาจะกลับไปอย่างเปลือยเปล่าเช่นเดียวกับที่เขามาฉันนั้น และเขาจะเอาอะไรซึ่งเป็นผลจากหยาดเหงื่อแรงงานของเขาติดมือไปไม่ได้เลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 16, 'นี่เป็นสิ่งเลวร้ายอันน่าสลดใจอีก คือเขาได้เกิดมาอย่างไรเขาก็ต้องไปอย่างนั้น เขาจะได้ประโยชน์อะไรเล่าที่เขาได้ลงแรงเพื่อลมแล้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 17, 'อนึ่งเขารับประทานอยู่ในความมืดตลอดปีเดือนของเขา เขามีความทุกข์อย่างสาหัสและมีโทโสพร้อมกับความเจ็บไข้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 18, 'ดูเถิด ที่ข้าพเจ้าเห็นดีและสมควร คือให้กินและดื่ม กับปรีดาในผลดีแห่งบรรดากิจการของตนที่ตนกระทําภายใต้ดวงอาทิตย์ ตลอดปีเดือนแห่งชีวิตของตนที่พระเจ้าทรงประทานแก่ตน เพราะการนี้แหละเป็นส่วนของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 19, 'อนึ่งทุกๆคนที่พระเจ้าทรงประทานทรัพย์สมบัติและความมั่งคั่งให้ ก็ได้ทรงโปรดให้มีอํานาจรับประทานของเหล่านั้น ได้รับส่วนของตน และยินดีปรีดาในการงานของตนได้ นี่แหละเป็นของประทานจากพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 20, 'เขาจะได้ไม่ต้องนึกถึงปีเดือนแห่งชีวิตของตนมาก เพราะพระเจ้าทรงตอบเขาในสิ่งที่ให้ใจเขาปีติยินดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 1, 'มีสิ่งเลวร้ายอย่างหนึ่งที่ข้าพเจ้าเห็นภายใต้ดวงอาทิตย์ และสิ่งนั้นหนักแก่มนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 2, 'คือมนุษย์คนใดที่พระเจ้าทรงประทานทรัพย์สมบัติ ความมั่งคั่งและยศฐาบรรดาศักดิ์ให้ จนสิ่งใดๆที่เขาปรารถนาสําหรับตัว จิตใจเขาก็มีครบไม่ขาดเลย แต่พระเจ้ามิได้ทรงโปรดให้เขามีอํานาจรับประทานสิ่งนั้นได้ คนนอกบ้านนอกเมืองกลับรับประทานสิ่งนั้น นี่ก็อนิจจัง และเป็นความทุกข์ใจอย่างร้ายแรง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 3, 'แม้ว่ามนุษย์คนใดมีบุตรสักร้อยคน และมีอายุอยู่หลายปี จนปีเดือนของเขาก็มากมาย แต่จิตใจของเขาหาได้อิ่มด้วยของดีไม่ ยิ่งกว่านั้นอีก เขาไม่มีงานฝังศพของตนด้วย ข้าพเจ้าว่าบุตรที่เกิดมาแท้งเสียยังดีกว่าคนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 4, 'เพราะเด็กนั้นเกิดมาอนิจจังและตายไปในความมืด และชื่อของเขาถูกปิดไว้ในความมืด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 5, 'ยิ่งกว่านั้นอีก ยังไม่ทันเห็นตะวันหรือยังไม่ทันรู้เรื่องราวอะไร เด็กคนนี้มีความสงบสุขยิ่งกว่าผู้ใหญ่นั้นเสียอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 6, 'เออ แม้ว่าเขามีชีวิตอยู่พันปีทวีอีกเท่าตัว แต่ไม่ได้เห็นของดีอะไร ทุกคนมิได้ลงไปที่เดียวกันหมดดอกหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 7, 'บรรดาการงานของมนุษย์ก็เพื่อปากของเขา แต่ถึงกระนั้นเขาก็ไม่รู้จักอิ่ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 8, 'ด้วยว่าคนมีสติปัญญาได้เปรียบอะไรกว่าคนเขลาเล่า หรือคนยากจนที่รู้จักดําเนินชีวิตของตนอยู่ต่อหน้าคนที่มีชีวิตก็ได้เปรียบอะไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 9, 'เห็นแล้วกับนัยน์ตาก็ดีกว่าความปรารถนาที่ตระเวนไป นี่ก็เป็นความว่างเปล่าและความวุ่นวายใจด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 10, 'สิ่งใดซึ่งมีอยู่เดี๋ยวนี้ เขาได้ใช้ชื่อเรียกสิ่งนั้นนานมาแล้ว และก็ทราบกันแล้วว่ามนุษย์คืออะไร และเขาไม่อาจโต้เถียงกับพระองค์ผู้ทรงฤทธิ์เดชากว่าตนได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 11, 'ยิ่งมีสิ่งของมากก็ยิ่งอนิจจังมาก แล้วจะเป็นประโยชน์อะไรแก่มนุษย์เล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 12, 'ใครคนไหนรู้ว่าสิ่งใดเป็นสิ่งที่ดีสําหรับมนุษย์ในชีวิตนี้ คือในระยะวันเดือนปีทั้งหลายแห่งชีวิตอันเหลวๆของตนที่ได้เสียไปดุจดังเงาเล่า หรือใครผู้ใดอาจบอกกับมนุษย์ได้ว่า สิ่งนี้สิ่งนั้นจะเกิดขึ้นภายหลังตนที่ภายใต้ดวงอาทิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 1, 'ชื่อเสียงดีก็ประเสริฐกว่าน้ํามันหอมอย่างวิเศษ และวันตายก็ดีกว่าวันเกิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 2, 'ไปยังเรือนที่มีการไว้ทุกข์ก็ดีกว่าไปยังเรือนที่มีการเลี้ยงกัน เพราะนั่นเป็นวาระสุดท้ายของมนุษย์ทั้งปวง และผู้ที่ยังมีชีวิตอยู่จะเอาเหตุการณ์นั้นใส่ไว้ในใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 3, 'ความโศกเศร้าก็ดีกว่าการหัวเราะ เพราะความเศร้าหมองของใบหน้าก็ทําให้จิตใจดีขึ้นได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 4, 'จิตใจของคนที่มีสติปัญญาย่อมอยู่ในเรือนที่มีความโศกเศร้า แต่จิตใจของคนเขลาย่อมอยู่ในเรือนที่มีการสนุกสนาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 5, 'ฟังคําตําหนิของคนที่มีสติปัญญายังดีกว่าให้คนฟังเพลงของคนเขลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 6, 'มีเสียงแตกของเรียวหนามอยู่ใต้หม้อฉันใด เสียงหัวเราะของคนเขลาก็ฉันนั้น นี่ก็อนิจจังด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 7, 'แท้จริงการบีบบังคับกระทําให้ผู้มีสติปัญญาโง่ไป และสินบนก็กระทําให้ความเข้าใจเสียไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 8, 'เบื้องปลายแห่งสิ่งใดๆก็ดีกว่าเบื้องต้นแห่งสิ่งนั้นๆ มีใจอดกลั้นก็ดีกว่ามีใจอหังการ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 9, 'อย่าให้ใจของเจ้าโกรธเร็ว เพราะความโกรธมีประจําอยู่ในทรวงอกของคนเขลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 10, 'อย่าว่า “อะไรหนอเป็นเหตุให้กาลก่อนดีกว่ากาลบัดนี้” เพราะที่เจ้าไต่ถามนั้นไม่ได้ถามด้วยสติปัญญา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 11, 'สติปัญญาประกอบกับมรดกก็เป็นของดี การนั้นเป็นประโยชน์แก่คนที่ได้เห็นดวงตะวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 12, 'เงินเป็นเครื่องป้องกันฉันใด สติปัญญาก็เป็นเครื่องป้องกันฉันนั้น และผลประโยชน์ของความรู้ คือสติปัญญาย่อมรักษาชีวิตของผู้ที่มีสติปัญญานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 13, 'จงพิจารณาพระราชกิจของพระเจ้า สิ่งใดๆที่พระองค์ทรงกระทําให้คดอยู่แล้ว ใครจะเหยียดสิ่งนั้นๆให้ตรงได้เล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 14, 'ในวันแห่งความเจริญก็จงชื่นชมยินดี แต่ในวันแห่งความทุกข์ยากก็จงพินิจพิจารณา พระเจ้าทรงบันดาลให้มีทั้งสองอย่าง เพื่อมนุษย์จะไม่ค้นได้ว่าเมื่อเขาล่วงไปแล้วจะมีอะไรมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 15, 'ข้าพเจ้าเห็นสิ่งเหล่านี้ทั้งสิ้นในชีวิตอนิจจังของข้าพเจ้า คือคนชอบธรรมพินาศในความชอบธรรมของตัว และมีคนชั่วร้ายมีชีวิตยืนยาวในการกระทําชั่ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 16, 'อย่าเป็นคนชอบธรรมเกินไป และอย่าฉลาดเกินตัว เหตุใดเจ้าจะทําตัวให้พินาศเสียเล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 17, 'อย่าชั่วมากนัก หรืออย่าเป็นคนเขลา ทําไมเจ้าจะไปตายเสียก่อนถึงวาระของเจ้าเล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 18, 'ก็ดีอยู่แล้วที่เจ้าจะยึดถือสิ่งเหล่านี้ไว้ เออ เจ้าอย่าแบมือปล่อยสิ่งนั้นให้หลุดลอยเสียทีเดียว เพราะว่าผู้ที่เกรงกลัวพระเจ้าจะพ้นจากบรรดาสิ่งที่กล่าวมานี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 19, 'สติปัญญาเป็นกําลังแก่คนฉลาดดีกว่าผู้มีอํานาจใหญ่โตสิบคนที่อยู่ในเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 20, 'แน่ทีเดียวไม่มีคนชอบธรรมสักคนเดียวบนแผ่นดินโลก ที่ได้ประพฤติล้วนแต่ความดี และไม่กระทําบาปเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 21, 'อย่าสนใจฟังบรรดาถ้อยคําที่ใครๆกล่าว เกรงว่าเจ้าจะได้ยินทาสของเจ้าแช่งด่าตัวเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 22, 'ด้วยว่าเจ้าก็แจ้งอยู่กับใจของเจ้าเองหลายครั้งหลายหนแล้วว่า ตัวเจ้าเองได้แช่งด่าคนอื่นเหมือนกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 23, 'บรรดาข้อความเหล่านี้ข้าพเจ้าได้ชันสูตรดูด้วยใช้สติปัญญาแล้ว ข้าพเจ้าว่า “ข้าพเจ้าจะได้ปัญญา” แต่ปัญญานั้นกลับอยู่ห่างไกลจากข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 24, 'สิ่งที่อยู่ไกลและลึกล้ําเหลือเกิน ใครผู้ใดจะค้นออกมาได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 25, 'ใจข้าพเจ้าหวนกลับมาเรียนรู้และเสาะแสวงหาสติปัญญา และมูลเหตุของสิ่งต่างๆ เพื่อให้รู้ความชั่วร้ายแห่งความเขลา คือความเขลาและความบ้าบอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 26, 'ข้าพเจ้าได้พบอีกสิ่งหนึ่งซึ่งขมขื่นยิ่งกว่าความตาย คือผู้หญิงที่มีใจเป็นบ่วงแร้วและข่าย มือของนางเป็นโซ่ตรวน คนใดเป็นคนที่พอพระทัยพระเจ้า คนนั้นจะหนีพ้นนาง แต่คนบาปจะถูกผู้หญิงคนนั้นจับเอาไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 27, 'ปัญญาจารย์กล่าวว่า ดูเถิด ข้าพเจ้าพบดังต่อไปนี้ โดยเอาเรื่องหนึ่งมาประดิษฐ์ติดต่อเข้ากับอีกเรื่องหนึ่ง เพื่อหามูลเหตุ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 28, 'ซึ่งจิตใจของข้าพเจ้ายังกําลังหาแล้วหาอีก แต่ข้าพเจ้าหาได้พบปะไม่ ในชายพันคนจะพบชายจริงสักคนหนึ่ง แต่จะหาหญิงแท้สักคนหนึ่งในจํานวนพันคนก็หาไม่พบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 29, 'ดูเถิด ข้าพเจ้าพบแต่ความนี้ต่างหาก คือพระเจ้าทรงสร้างมนุษย์ให้เป็นคนเที่ยงธรรม แต่มนุษย์ทั้งหลายได้ค้นคว้ากลอุบายต่างๆออกมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 1, 'ใครผู้ใดจะเหมือนนักปราชญ์ หรือใครเล่าจะอธิบายอะไรๆก็ได้ สติปัญญาของมนุษย์กระทําให้ใบหน้าของเขาผ่องใส และใบหน้าของเขาที่แข็งกระด้างก็เปลี่ยนไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 2, 'ข้าพเจ้าแนะนําว่า จงถือรักษาพระบัญชาของกษัตริย์ และที่เกี่ยวข้องกับคําปฏิญาณต่อพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 3, 'อย่ารีบออกไปให้พ้นพระพักตร์กษัตริย์ อย่ายืนอยู่ฝ่ายความชั่วร้าย เพราะกษัตริย์ย่อมทรงกระทําอะไรๆตามชอบพระทัยพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 4, 'ด้วยว่าพระดํารัสของกษัตริย์อยู่ที่ไหน อํานาจก็อยู่ที่นั่น และใครผู้ใดจะกราบทูลถามพระองค์ได้ว่า “พระองค์ทรงกระทําอะไรเช่นนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 5, 'ผู้ที่รักษาพระบัญชาจะไม่ประสบความชั่วร้าย และจิตใจของคนที่มีสติปัญญาก็เข้าใจทั้งวาระและคําตัดสิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 6, 'ด้วยว่าไม่ว่าอะไรทั้งนั้นย่อมมีวาระและคําตัดสิน ฉะนั้นความลําบากของมนุษย์จึงเป็นภาระหนักแก่ตัวเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 7, 'ด้วยเขาไม่ทราบว่าอะไรจะเกิดขึ้น ด้วยใครจะบอกแก่เขาได้ว่าสิ่งนั้นจะเกิดขึ้นเวลาใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 8, 'หามีมนุษย์คนใดมีอํานาจเหนือจิตวิญญาณที่จะรั้งจิตวิญญาณได้ไม่ หรือหามีอํานาจอันใดเหนือวันตายไม่ การสงครามนั้นย่อมไม่มีการปลดปล่อย ความชั่วร้ายย่อมไม่มีการปลดปล่อยผู้ที่ถูกมอบให้ไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 9, 'บรรดาการนี้ข้าพเจ้าเห็นหมดแล้ว และข้าพเจ้าสนใจกิจการทุกอย่างที่เขากระทํากันภายใต้ดวงอาทิตย์ มีวาระซึ่งให้คนหนึ่งมีอํานาจเหนืออีกคนหนึ่งที่จะมาทําอันตรายเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 10, 'ข้าพเจ้าได้เห็นเขาฝังคนชั่วร้าย ผู้ซึ่งเคยเข้าออกที่สถานบริสุทธิ์ และมีคนลืมเขาในเมืองที่คนชั่วร้ายนั้นเองกระทําสิ่งเช่นนั้น นี่ก็อนิจจังด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 11, 'เพราะการตัดสินการกระทําชั่วนั้น เขาไม่ได้ลงโทษโดยเร็ว เหตุฉะนั้นใจบุตรทั้งหลายของมนุษย์จึงเจตนามุ่งที่จะกระทําความชั่ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 12, 'แม้ว่าคนบาปทําชั่วตั้งร้อยครั้ง และอายุเขายังยั่งยืนอยู่ได้ ถึงกระนั้นข้าพเจ้ายังรู้แน่ว่า ความดีจะมีแก่เขาทั้งหลายที่ยําเกรงพระเจ้า คือที่มีความยําเกรงต่อพระพักตร์พระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 13, 'แต่ว่าจะไม่เป็นการดีแก่คนชั่วร้าย อายุของเขาที่เป็นดังเงาก็จะไม่มียืดยาวออกไปได้ เพราะเขาไม่มีความยําเกรงต่อพระพักตร์พระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 14, 'ยังมีอนิจจังอีกอย่างหนึ่งที่กระทํากันบนแผ่นดินโลก คือมีคนชอบธรรมรับเหตุการณ์อันเป็นเหตุการณ์ที่คนชั่วควรรับ และมีคนชั่วรับเหตุการณ์อันเป็นเหตุการณ์ที่คนชอบธรรมควรรับ ข้าพเจ้ากล่าวได้ว่า นี่ก็อนิจจังด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 15, 'แล้วข้าพเจ้าจึงสนับสนุนให้หาความสนุกสนาน ด้วยว่าภายใต้ดวงอาทิตย์ มนุษย์ไม่มีอะไรดีไปกว่ากินและดื่มกับชื่นชมยินดี ด้วยว่าอาการนี้คลุกคลีไปในการงานของตนตลอดปีเดือนแห่งชีวิตของตน ที่พระเจ้าทรงโปรดประทานแก่ตนภายใต้ดวงอาทิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 16, 'เมื่อข้าพเจ้าตั้งใจจะเข้าใจสติปัญญาและทราบธุรกิจที่กระทํากันในโลก (ที่เขาอดหลับอดนอนทํากันตลอดวันตลอดคืน)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 17, 'แล้วข้าพเจ้าจึงเห็นบรรดาพระราชกิจของพระเจ้าว่า มนุษย์จะค้นหาความเข้าใจในพระราชกิจที่บังเกิดอยู่ภายใต้ดวงอาทิตย์หาได้ไม่ เพราะว่าถึงแม้มนุษย์จะออกแรงค้นหาสักปานใดก็ยังจะค้นหาให้พบไม่ได้ เออ ยิ่งกว่านั้นอีก แม้ว่านักปราชญ์คนใดนึกเอาว่าเขาจะเข้าใจแล้ว เขาก็ยังค้นหาไม่พบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 1, 'ข้าพเจ้าได้นําเรื่องราวเหล่านี้มาคิด ตรวจพิจารณาให้สิ้นว่า คนชอบธรรมและคนมีสติปัญญารวมทั้งกิจการของเขาทั้งหลาย ก็อยู่ในพระหัตถ์ของพระเจ้า จะทรงรักหรือทรงเกลียดก็ตาม มนุษย์หารู้ไม่ ทุกอย่างก็อยู่ต่อหน้าเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 2, 'สิ่งสารพัดตกแก่คนทั้งปวงเหมือนกันหมด คือเหตุการณ์อันเดียวกันตกแก่คนชอบธรรมและคนชั่ว ตกแก่คนดี ตกแก่คนสะอาดและคนที่มีมลทิน ตกแก่ผู้ที่ถวายสัตวบูชา และแก่ผู้ที่ไม่ถวายสัตวบูชา ตกแก่คนดีอย่างไรก็ตกแก่คนบาปอย่างนั้น ตกแก่คนปฏิญาณอย่างไรก็ตกแก่คนไม่กล้าปฏิญาณอย่างนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 3, 'นี่แหละเป็นสิ่งเลวร้ายที่มีอยู่ในบรรดาการที่บังเกิดขึ้นภายใต้ดวงอาทิตย์ คือว่ามีเหตุการณ์อันเดียวกันที่ตกแก่คนทั้งปวง เออ จิตใจของบุตรทั้งหลายของมนุษย์ก็เต็มไปด้วยความชั่ว และความบ้าบออยู่ในใจของเขาเมื่อมีชีวิตอยู่และต่อจากนั้นเขาก็ไปอยู่กับคนตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 4, 'ส่วนคนใดที่เข้าร่วมอยู่กับคนทั้งปวงที่มีชีวิต คนนั้นก็มีความหวังใจได้ ด้วยว่าสุนัขที่เป็นอยู่ก็ยังดีกว่าสิงโตที่ตายแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 5, 'เพราะว่าคนเป็นย่อมรู้ว่าเขาเองจะตาย แต่คนตายแล้วก็ไม่รู้อะไรเลย เขาหาได้รับรางวัลอีกไม่ ด้วยว่าใครๆก็พากันลืมเขาเสียหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 6, 'ทั้งความรัก ความชัง และความอิจฉาของเขาได้สาบสูญไปแล้ว ในบรรดาการที่บังเกิดขึ้นภายใต้ดวงอาทิตย์ เขาทั้งหลายหามีส่วนร่วมอีกต่อไปไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 7, 'ไปเถิด ไปรับประทานอาหารของเจ้าด้วยความชื่นชม และไปดื่มน้ําองุ่นของเจ้าด้วยใจร่าเริง เพราะพระเจ้าทรงเห็นชอบกับการงานของเจ้าแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 8, 'จงให้เสื้อผ้าของเจ้าขาวอยู่เสมอ และน้ํามันที่ศีรษะของเจ้าก็อย่าให้ขาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 9, 'เจ้าจงอยู่กินด้วยความชื่นชมยินดีกับภรรยาซึ่งเจ้ารักตลอดปีเดือนแห่งชีวิตอนิจจังของเจ้า ซึ่งพระองค์ได้ทรงประทานให้แก่เจ้าภายใต้ดวงอาทิตย์ ตลอดปีเดือนอนิจจังของเจ้า ด้วยว่านั่นเป็นส่วนในชีวิตและในการงานของเจ้า ซึ่งเจ้าได้ออกแรงกระทําภายใต้ดวงอาทิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 10, 'มือของเจ้าจับทําการงานอะไร จงกระทําการนั้นด้วยเต็มกําลังของเจ้า เพราะว่าในแดนคนตายที่เจ้าจะไปนั้นไม่มีการงาน หรือแนวความคิด หรือความรู้ หรือสติปัญญา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 11, 'ข้าพเจ้าได้เห็นภายใต้ดวงอาทิตย์อีกว่า คนเร็วไม่ชนะในการวิ่งแข่งเสมอไป หรือฝ่ายมีกําลังไม่ชนะสงครามเสมอไป หรือคนฉลาดไม่รับประทานเสมอไป หรือคนมีความเข้าใจไม่ร่ํารวยเสมอไป หรือผู้ที่เชี่ยวชาญไม่ได้รับความโปรดปรานเสมอไป แต่วาระและโอกาสมีมาถึงเขาทุกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 12, 'เพราะว่ามนุษย์ไม่รู้วาระของตน ปลาติดอยู่ในอวนอันร้ายฉันใด และนกถูกดักติดอยู่ในบ่วงแร้วฉันใด วาระอันร้ายก็มาถึงบุตรทั้งหลายของมนุษย์ เขาก็ถูกวาระอันร้ายนั้นดักจับติดโดยฉับพลันเหมือนกันฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 13, 'ข้าพเจ้าเห็นเรื่องสติปัญญาภายใต้ดวงอาทิตย์ เห็นว่าเป็นเรื่องใหญ่โตดังต่อไปนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 14, 'ยังมีเมืองเล็กๆเมืองหนึ่ง มีคนอยู่ในเมืองนั้นน้อยคน แล้วมีมหากษัตริย์มาตีเมืองนั้นและล้อมเมืองนั้นไว้ และสร้างเครื่องล้อมไว้รอบเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 15, 'แต่ในเมืองนั้นมีชายฉลาดแต่ยากจนอยู่คนหนึ่ง และชายคนนี้ช่วยเมืองนั้นไว้ให้พ้นด้วยปัญญาของตน แต่หามีใครจดจํารําลึกถึงชายยากจนคนนี้ไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 16, 'แต่ข้าพเจ้าว่า สติปัญญาก็ดีกว่ากําลังวังชา ถึงสติปัญญาของชายยากจนคนนั้นถูกดูแคลน และถ้อยคําของเขาไม่มีใครฟังก็ตามที');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 17, 'ถ้อยคําของคนฉลาดได้ยินในที่สงัดมากกว่าสิงหนาทของผู้ครอบครองในหมู่คนเขลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 18, 'สติปัญญาดีกว่าเครื่องอาวุธยุทโธปกรณ์ แต่คนบาปคนเดียวย่อมบั่นรอนความดีเสียเป็นอันมากได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 1, 'แมลงวันตายย่อมทําให้ขี้ผึ้งของคนปรุงยาบูดเหม็นไป ดังนั้นความโง่เขลานิดหน่อยก็ทําให้เขาเสียชื่อด้วยในเรื่องสติปัญญาและเกียรติยศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 2, 'จิตใจของคนที่มีสติปัญญาย่อมอยู่ที่ข้างขวามือของตน แต่จิตใจของคนเขลาย่อมอยู่ที่ข้างมือซ้ายของตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 3, 'แม้เมื่อคนเขลากําลังเดินไปตามทาง เขาก็ขาดสํานึก และตัวเขามักแสดงแก่ทุกคนว่าตนเป็นคนเขลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 4, 'ถ้าใจของเจ้านายเกิดโมโหขึ้นต่อท่าน อย่าออกเสียจากที่ของท่าน เพราะว่าอารมณ์เย็นย่อมระงับความผิดใหญ่หลวงไว้ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 5, 'มีสิ่งเลวร้ายที่ข้าพเจ้าเห็นภายใต้ดวงอาทิตย์ ประหนึ่งว่าเป็นความผิดซึ่งมาจากผู้มีอํานาจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 6, 'คือคนเขลาถูกแต่งตั้งไว้ในตําแหน่งสูงใหญ่ และคนมั่งคั่งรับตําแหน่งต่ําต้อย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 7, 'ข้าพเจ้าเห็นทาสขี่ม้า และเจ้านายเดินที่พื้นแผ่นดินอย่างทาส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 8, 'ผู้ใดขุดบ่อไว้ ผู้นั้นจะตกลงในบ่อนั้น ผู้ใดพังรั้วต้นไม้ทะลุเข้าไป งูจะขบกัดผู้นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 9, 'ผู้ใดสกัดหิน ผู้นั้นจะเจ็บเพราะหินนั้น ผู้ใดผ่าขอนไม้ ผู้นั้นจะประสบอันตรายเพราะขอนไม้นั้นได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 10, 'ถ้าขวานทื่อแล้ว และเขาไม่ลับให้คม เขาก็ต้องออกแรงมากกว่า แต่สติปัญญาจะช่วยให้บรรลุความสําเร็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 11, 'ถ้างูขบเสียก่อนที่ทําให้มันเชื่อง หมองูก็ไม่เป็นประโยชน์อะไรแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 12, 'ถ้อยคําจากปากของผู้มีสติปัญญาก็มีคุณ แต่ริมฝีปากของคนเขลาจะกลืนตัวเองเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 13, 'ถ้อยคําจากปากของเขาเป็นความเขลาตั้งแต่เริ่มปริปาก ตอนจบถ้อยคํานั้นก็เป็นความบ้าบออย่างร้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 14, 'คนเขลาพูดมากซ้ําซาก มนุษย์หารู้ไม่ว่าเหตุอันใดจะบังเกิดขึ้น ใครเล่าจะบอกเขาได้ว่ามีอะไรเกิดขึ้นเมื่อเขาล่วงไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 15, 'การงานของคนเขลากระทําให้เขาทุกคนเหน็ดเหนื่อย ด้วยว่าเขาไม่รู้จักทางที่จะเข้าไปในกรุง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 16, 'โอ บ้านเมืองเอ๋ย วิบัติแก่เจ้าเมื่อกษัตริย์ของเจ้าเป็นเด็ก และเจ้านายทั้งหลายของเจ้ามีการเลี้ยงกันสนุกสนานแต่เช้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 17, 'โอ บ้านเมืองเอ๋ย ความสําราญจะมีแก่เจ้า เมื่อกษัตริย์ของเจ้าเป็นบุตรชายของขุนนาง และเจ้านายของเจ้ามีการเลี้ยงตามกาลเทศะ เพื่อจะมีกําลังวังชา มิใช่จะดื่มให้มึนเมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 18, 'เพราะความขี้เกียจ หลังคาจึงหักพังลง และเพราะมือเกียจคร้านเรือนจึงรั่วเฉอะแฉะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 19, 'เขาจัดงานเลี้ยงไว้เพื่อให้คนหัวเราะ และน้ําองุ่นทําให้ชื่นบาน และเงินก็จัดให้ได้ทุกอย่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 20, 'อย่าแช่งด่ากษัตริย์ เออ แม้แต่คิดแช่งด่าในใจก็อย่าเลย และอย่าแช่งคนมั่งมีที่ในห้องนอนของเจ้า เพราะนกในอากาศจะคาบเสียงของเจ้าไป หรือตัวที่มีปีกจะเล่าเรื่องนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 1, 'จงโยนขนมปังของเจ้าลงบนน้ํา เพราะอีกหลายวันเจ้าจะพบมันได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 2, 'จงแบ่งปันส่วนหนึ่งให้แก่คนเจ็ดคน เออ ถึงแปดคนก็ให้เถอะ เพราะเจ้าไม่ทราบว่าสิ่งเลวร้ายอย่างใดจะบังเกิดขึ้นบนพื้นแผ่นดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 3, 'ถ้าบรรดาเมฆมีฝนอยู่เต็ม มันก็จะเททั้งหมดลงมาบนแผ่นดินโลก และถ้าต้นไม้ล้มลงทางใต้หรือทางเหนือ มันล้มลงตรงไหน มันก็นอนอยู่ตรงนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 4, 'ผู้ใดเฝ้าสังเกตลมก็จะไม่หว่านพืช และผู้ที่มองเมฆก็จะไม่เก็บเกี่ยว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 5, 'เจ้าไม่ทราบทางของวิญญาณว่าไปทางไหน และกระดูกมีขึ้นในมดลูกของหญิงที่มีครรภ์อย่างไรฉันใด เจ้าก็จะไม่ทราบถึงกิจการของพระเจ้าผู้ทรงกระทําสิ่งสารพัดฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 6, 'เวลาเช้าเจ้าจงหว่านพืชของเจ้า และพอเวลาเย็นก็อย่าหดมือของเจ้าเสีย เพราะเจ้าหาทราบไม่ว่าการไหนจะเจริญ การนี้หรือการนั้น หรือการทั้งสองจะเจริญดีเหมือนกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 7, 'แสงสว่างเป็นที่ชื่นใจ และการที่นัยน์ตาเห็นดวงตะวันก็เป็นที่ชื่นบาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 8, 'แต่ถ้าคนใดมีชีวิตอยู่ได้ตั้งหลายปี และเขาเปรมปรีดิ์ในตลอดปีเดือนเหล่านั้น ก็จงให้เขาระลึกถึงวันมืดมิดว่าจะมีมาก บรรดาเหตุการณ์ที่เกิดขึ้นมานั้นก็อนิจจัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 9, 'โอ เยาวชน จงเปรมปรีดิ์ในปฐมวัยของเจ้า และให้จิตใจของเจ้ากระทําตัวเจ้าให้ร่าเริงในปีเดือนแห่งปฐมวัยของเจ้า เจ้าจงดําเนินในทางแห่งใจของเจ้าและตามสายตาของเจ้า แต่จงทราบว่าเนื่องด้วยกิจการงานทั้งปวงเหล่านี้พระเจ้าจะทรงนําเจ้าเข้ามาถึงการพิพากษา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 10, 'ฉะนั้นจงตัดความเศร้าหมองเสียจากใจของเจ้า และจงสลัดความชั่วร้ายเสียจากเนื้อหนังของเจ้า เพราะความหนุ่มสาวและวัยฉกรรจ์นั้นเป็นอนิจจัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 1, 'ในปีเดือนแห่งปฐมวัยของเจ้า เจ้าจงระลึกถึงพระผู้เนรมิตสร้างของเจ้าก่อนที่ยามทุกข์ร้อนจะมาถึง และปีเดือนใกล้เข้ามา เมื่อเจ้าจะกล่าวว่า “ข้าไม่มีความเพลิดเพลินในปีเดือนนั้นเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 2, 'ก่อนที่ดวงอาทิตย์ แสงสว่าง ดวงจันทร์ และดวงดาวทั้งหลายอับแสง และก่อนที่เมฆกลับมาเมื่อหมดฝนแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 3, 'ในกาลเมื่อคนยามเฝ้าเรือนจะตัวสั่น และคนแข็งแรงจะตัวโค้งงอลง และเมื่อฟันกรามจะหยุดเสีย เพราะจํานวนลดน้อยลง และผู้ที่มองออกไปทางหน้าต่างจะมืดมัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 4, 'และประตูคู่ที่เปิดออกถนนจะปิดเสีย เมื่อเสียงเคี้ยวอ่อยลง เมื่อมีเสียงนก เขาจะลุกขึ้น และบรรดานักร้องสตรีจะย่อตัวลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 5, 'เออ เขาทั้งหลายจะกลัวที่สูง และสิ่งน่าสยดสยองก็จะอยู่ในหนทาง ต้นอัลมันด์จะมีดอก และตั๊กแตนจะเป็นภาระ ความปรารถนาก็จะประลาตไปเสีย เพราะมนุษย์กําลังไปบ้านอันถาวรของเขา ส่วนผู้ไว้ทุกข์ก็เวียนไปมาตามถนน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 6, 'ก่อนที่สายเงินจะขาด หรือชามทองคําจะบรรลัย หรือเหยือกน้ําจะแตกเสียที่น้ําพุ หรือล้อจะหักเสีย ณ ที่ขังน้ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 7, 'และผงคลีจะกลับไปเป็นดินอย่างเดิม และจิตวิญญาณจะกลับไปสู่พระเจ้าผู้ทรงประทานให้มานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 8, 'ปัญญาจารย์ว่า อนิจจัง อนิจจัง สารพัดก็อนิจจัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 9, 'ยิ่งกว่านั้น เพราะปัญญาจารย์เป็นคนฉลาดแล้ว ท่านยังสอนความรู้ให้ประชาชนอีกด้วย เออ ท่านพิเคราะห์ ท่านค้นคว้า และท่านเรียบเรียงสุภาษิตหลายข้อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 10, 'ปัญญาจารย์เสาะหาถ้อยคําที่เพราะหู และท่านเขียนถ้อยคําแห่งความจริงไว้อย่างเที่ยงตรง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 11, 'ถ้อยคําของนักปราชญ์เป็นประดุจประตัก และประดุจตะปูซึ่งอาจารย์ผู้สอนแห่งการชุมนุมได้ตรึงแน่น ซึ่งท่านเมษบาลผู้หนึ่งได้ประทานให้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 12, 'และยิ่งกว่านั้นอีก บุตรชายของข้าพเจ้าเอ๋ย จงรับคําตักเตือนเถิด ซึ่งจะทําหนังสือมากก็ไม่มีสิ้นสุด และเรียนมากก็เหนื่อยเนื้อหนัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 13, 'ให้เราฟังตอนสรุปความกันทั้งสิ้นแล้ว คือจงยําเกรงพระเจ้า และรักษาพระบัญญัติของพระองค์ เพราะนี่แหละเป็นหน้าที่ทั้งสิ้นของมนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 14, 'ด้วยว่าพระเจ้าจะทรงเอาการงานทุกประการเข้าสู่การพิพากษา พร้อมด้วยสิ่งเร้นลับทุกอย่าง ไม่ว่าดีหรือชั่ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 1, 'บทเพลงแห่งบทเพลงทั้งหลายซึ่งเป็นของซาโลมอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 2, 'ขอเขาจุบดิฉันด้วยจุบจากปากของเขา เพราะว่าความรักของเธอดีกว่าน้ําองุ่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 3, 'เพราะน้ํามันเจิมของเธอนั้นหอมฟุ้ง นามของเธอจึงหอมเหมือนน้ํามันที่เทออกแล้ว เพราะฉะนั้นพวกหญิงพรหมจารีจึงรักเธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 4, 'ขอพาดิฉันไป พวกเราจะวิ่งตามเธอไป กษัตริย์ได้นําดิฉันไปในห้องโถงของพระองค์ เราจะเต้นโลดและเปรมปรีดิ์ในตัวเธอ เราจะพรรณนาถึงความรักของเธอให้ยิ่งกว่าน้ําองุ่น บรรดาคนเที่ยงธรรมก็รักเธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 5, 'โอ บุตรสาวแห่งเยรูซาเล็มเอ๋ย ดิฉันผิวดําๆ แต่ว่าดําขํา ดังเต็นท์ของพวกเคดาร์ ดังวิสูตรของซาโลมอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 6, 'อย่ามองค่อนขอดดิฉัน เพราะดิฉันผิวคล้ํา เนื่องด้วยแสงแดดแผดเผาดิฉัน พวกบุตรแห่งมารดาของดิฉันได้ขึ้งโกรธดิฉัน เขาทั้งหลายใช้ดิฉันให้เป็นคนดูแลสวนองุ่น แต่สวนองุ่นของดิฉันเอง ดิฉันไม่ได้ดูแล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 7, 'โอ เธอผู้ที่จิตใจดิฉันรัก ขอบอกดิฉันว่า เธอเลี้ยงฝูงสัตว์อยู่ที่ไหนในเวลาเที่ยงวัน เธอให้มันนอนพักที่ไหน เพราะเหตุใดเล่าดิฉันจะต้องหันไปตามฝูงสัตว์ของพวกเพื่อนเธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 8, 'โอ แม่งามเลิศในท่ามกลางหญิงทั้งหลาย ถ้าเธอไม่รู้จงเดินไปตามรอยตีนฝูงแพะแกะ แล้วจงเลี้ยงฝูงแพะแกะของเธอไว้ที่ข้างเต็นท์ของเมษบาลเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 9, 'โอ ที่รักของฉันเอ๋ย ฉันขอเปรียบเธอประหนึ่งอาชาเทียมราชรถของฟาโรห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 10, 'แก้มทั้งสองของเธองามด้วยอาภรณ์ประดับเพชรพลอย ลําคอของเธอก็สวยมีสร้อยทองคํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 11, 'พวกฉันจะทําเครื่องประดับทองคํามีลูกปัดเงินประกอบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 12, 'ขณะเมื่อกษัตริย์กําลังประทับที่โต๊ะอยู่ น้ํามันแฝกหอมของดิฉันก็ส่งกลิ่นฟุ้งไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 13, 'ที่รักของดิฉันเป็นเหมือนห่อมดยอบสําหรับดิฉัน ห้อยอยู่ตลอดคืนระหว่างสองถันของดิฉัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 14, 'ที่รักของดิฉันนั้น สําหรับดิฉันเธอเป็นเหมือนช่อดอกเทียนขาว อยู่ในสวนองุ่นเอนเกดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 15, 'ดูเถิด ที่รักของฉัน ดูช่างสวยงาม ดูเถิด เธอสวยงาม ดวงตาทั้งสองของเธอดังนกเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 16, 'ดูเถิด ที่รักของฉัน เธอเป็นคนสวยงามจริงเจ้าค่ะ เธอเป็นคนน่าชมจริงๆ ที่นอนของเราเขียวสด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 17, 'ขื่อเรือนของเราทําด้วยไม้สนสีดาร์ และแปของเรานั้นทําด้วยไม้สนสามใบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 1, 'ดิฉันเหมือนดอกกุหลาบในทุ่งชาโรน เหมือนดอกลิลลี่ในหุบเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 2, 'ดอกลิลลี่อยู่ท่ามกลางต้นหนามนั้นอย่างไร ที่รักของฉันก็อยู่เด่นในท่ามกลางสาวอื่นๆอย่างนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 3, 'ต้นแอบเปิ้ลขึ้นอยู่กลางต้นไม้ป่าอย่างไร ที่รักของดิฉันก็อยู่ท่ามกลางชายหนุ่มอื่นๆอย่างนั้น ดิฉันได้นั่งอยู่ใต้ร่มของเขาด้วยความยินดีเป็นอันมาก และผลของเขาดิฉันได้ลิ้มรสหวาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 4, 'เขาได้พาดิฉันให้เข้าในเรือนสําหรับงานเลี้ยง และธงสําคัญของเขาซึ่งห้อยอยู่เหนือดิฉันนั้นคือความรัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 5, 'จงชูกําลังของดิฉันด้วยขนมองุ่นแห้ง ขอทําให้ดิฉันชื่นใจด้วยผลแอบเปิ้ล เพราะดิฉันป่วยเป็นโรครัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 6, 'มือซ้ายของเขาช้อนใต้ศีรษะของดิฉันไว้ และมือขวาของเขาสอดกอดดิฉันไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 7, 'โอ เหล่าบุตรสาวแห่งเยรูซาเล็มเอ๋ย ดิฉันขอให้เธอทั้งหลายปฏิญาณต่อละมั่งหรือกวางตัวเมียในทุ่งว่า เธอทั้งหลายจะไม่เร้าหรือจะไม่ปลุกที่รักของดิฉันให้ตื่นกระตือขึ้นจนกว่าเขาจะจุใจแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 8, 'แน่ะ เสียงที่รักของดิฉัน ดูเถิด เขามาแล้ว กําลังเต้นโลดอยู่บนภูเขา กําลังกระโดดอยู่บนเนินเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 9, 'ที่รักของดิฉันเป็นดุจดังละมั่งหรือดุจดังกวางหนุ่ม ดูเถิด เขากําลังยืนอยู่ที่ข้างหลังกําแพงของเรา เขาชะโงกหน้าต่างเข้ามา เขาสอดมองดูทางตาข่าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 10, 'ที่รักของดิฉันได้เอ่ยปากพูดกับดิฉันว่า “ที่รักของฉันเอ๋ย เธอจงลุกขึ้นเถอะ คนสวยงามของฉันเอ๋ย จงมาเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 11, 'ด้วยว่า ดูเถิด ฤดูหนาวล่วงไปแล้ว และฝนก็วายแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 12, 'ดอกไม้ต่างๆนานากําลังปรากฏบนพื้นแผ่นดิน เวลาสําหรับวิหคร้องเพลงมาถึงแล้ว และเสียงคูของนกเขาก็ได้ยินอยู่ในแผ่นดินของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 13, 'ต้นมะเดื่อกําลังบ่มผลดิบให้สุก และเถาองุ่นมีดอกบานอยู่มันส่งกลิ่นหอมฟุ้ง ที่รักของฉันเอ๋ย จงลุกขึ้นเถอะ คนสวยงามของฉันเอ๋ย จงมาเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 14, 'โอ แม่นกเขาของฉันเอ๋ย แม่นกเขาตัวที่อยู่ในซอกผาในช่องลับแห่งเขาชัน ขอให้ฉันได้ชมรูปโฉมของเธอหน่อยเถอะ ขอให้ฉันได้ยินสําเนียงของเธอหน่อย ด้วยว่าน้ําเสียงของเธอก็หวาน และรูปโฉมของเธอก็งามวิไล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 15, 'จงจับสุนัขจิ้งจอกมาให้เรา คือสุนัขจิ้งจอกตัวเล็กที่ทําลายสวนองุ่น เพราะว่าสวนองุ่นของเรากําลังมีดอกช่อแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 16, 'ที่รักของดิฉันเป็นกรรมสิทธิ์ของดิฉัน และตัวดิฉันก็เป็นของเขา เขากําลังเลี้ยงฝูงสัตว์ของเขาท่ามกลางหมู่ดอกลิลลี่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 17, 'ที่รักของดิฉันจ๋า จนเวลาเย็น และเงาหมดไปแล้ว ขอเธอเป็นดั่งละมั่งหรือกวางหนุ่มที่เทือกเขาเบเธอร์เถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 1, 'ยามราตรีกาลเมื่อดิฉันนอนอยู่ดิฉันมองหาเขาผู้นั้นที่ดวงใจของดิฉันรักใคร่ ดิฉันมองหาเขา แต่หาได้พบไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 2, '“บัดนี้ดิฉันจะลุกขึ้น แล้วจะเที่ยวไปในเมืองให้ตลอดไป ตามถนนและลานเมือง ดิฉันจะแสวงหาเขาผู้นั้นที่ดวงใจของดิฉันรักใคร่” ดิฉันมองหาเขา แต่หาได้พบไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 3, 'พวกพลตระเวนที่ลาดตระเวนในเมืองนั้นได้พบดิฉัน แล้วดิฉันถามเขาว่า “ท่านเห็นเขาผู้นั้นที่ดวงใจของดิฉันรักใคร่ไหม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 4, 'พอดิฉันผ่านพลตระเวนพ้นมาหน่อยเดียว ดิฉันก็พบเขาผู้นั้นที่ดวงใจของดิฉันรักใคร่ ดิฉันจับตัวเขากุมไว้แน่น และไม่ยอมปล่อยให้เขาหลุดไปเลย จนดิฉันพาเขาให้เข้ามาในเรือนของมารดาดิฉัน และให้เข้ามาในห้องของผู้ที่ให้ดิฉันได้ปฏิสนธิ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 5, 'โอ เหล่าบุตรสาวแห่งเยรูซาเล็มเอ๋ย ดิฉันขอให้เธอทั้งหลายปฏิญาณต่อละมั่งหรือกวางตัวเมียในทุ่งว่า เธอทั้งหลายจะไม่เร้าหรือจะไม่ปลุกที่รักของดิฉันให้ตื่นกระตือขึ้นจนกว่าเขาจะจุใจแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 6, 'ผู้ใดหนอที่กําลังขึ้นมาจากถิ่นทุรกันดารดูประดุจเสาควัน หอมไปด้วยกลิ่นมดยอบและกํายาน ทําด้วยบรรดาเครื่องหอมของพ่อค้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 7, 'ดูเถิด เป็นพระวอของซาโลมอน ห้อมล้อมมาด้วยทแกล้วทหารหกสิบคน เป็นทแกล้วทหารคนอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 8, 'เขาทั้งหลายถือดาบและเป็นผู้ชํานาญศึก เขาทุกคนเหน็บดาบไว้ที่ต้นขาของตน เพราะเกรงภัยในราตรีกาล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 9, 'กษัตริย์ซาโลมอนสร้างพระวอสําหรับพระองค์ ด้วยไม้มาจากเลบานอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 10, 'พระองค์ทรงทําเสาพระวอนั้นด้วยเงิน แท่นประทับทําด้วยทองคํา และยี่ภู่ลาดด้วยผ้าสีม่วง ข้างในพระวอนั้นบุไว้ด้วยความรักโดยบุตรสาวแห่งเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 11, 'โอ บุตรสาวแห่งศิโยนเอ๋ย จงออกไป ไปดูกษัตริย์ซาโลมอนเถิด ทรงมงกุฎซึ่งพระราชมารดาได้สวมให้ ในวันที่พระองค์ได้ทรงอภิเษกสมรสนั้น ในวันเมื่อพระทัยของพระองค์ทรงเบิกบานอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 1, 'ที่รักของฉันเอ๋ย ดูเถิด เธอช่างสวยงาม ดูซี เธอสวยงาม ดวงตาของเธอดังนกเขาอยู่ในผ้าคลุม ผมของเธอดุจฝูงแพะที่เคลื่อนมาตามเนินลาดภูเขากิเลอาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 2, 'ซี่ฟันของเธอดังฝูงแกะตัวเมียที่กําลังจะตัดขน เพิ่งขึ้นมาจากการชําระล้าง มีลูกแฝดติดมาทุกตัว และหามีตัวใดเป็นหมันไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 3, 'ริมฝีปากของเธอแดงดุจด้ายสีครั่ง และคําพูดของเธอก็งดงาม ขมับของเธอเหมือนผลทับทิมผ่าซีกอยู่ในผ้าคลุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 4, 'ลําคอของเธอดุจป้อมของดาวิดที่ได้ก่อสร้างไว้เพื่อเก็บเครื่องอาวุธ มีดั้งพันหนึ่งแขวนไว้ ทั้งหมดเป็นโล่ของทแกล้วทหาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 5, 'ถันทั้งสองของเธอเหมือนลูกละมั่งสองตัวซึ่งเป็นละมั่งฝาแฝดที่กําลังหากินในท่ามกลางหมู่ดอกลิลลี่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 6, 'จนเวลาเย็นและเงาหมดไปแล้ว ฉันจะไปยังภูเขามดยอบและยังเนินเขากํายาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 7, 'ที่รักของฉันเอ๋ย เธอช่างงามสะพรั่งไปทั้งนั้น ในตัวเธอจะหาตําหนิสักนิดก็ไม่มี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 8, 'จงจากเลบานอนไปกับฉันเถิด เจ้าสาวของฉันจ๋า จงจากเลบานอนไปกับฉันนะ ให้มองลงจากยอดเขาอามานา จากยอดเขาเสนีร์ และยอดเขาเฮอร์โมน จากถ้ําราชสีห์ จากเขาเสือดาว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 9, 'น้องสาวของฉันจ๋า น้องได้ปล้นเอาดวงใจของพี่ไปเสียแล้วละ เจ้าสาวของฉันเอ๋ย เจ้าได้ปล้นเอาดวงใจของฉันไปด้วยการชายตาเพียงแวบเดียวเท่านั้น ด้วยสร้อยคอสายเดียวของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 10, 'น้องสาวของฉันจ๊ะ เจ้าสาวของฉันจ๋า ความรักของเธอช่างหวานเสียนี่กระไร ความรักของเธอนั้นช่างหวานกว่าน้ําองุ่น และกลิ่นน้ํามันของเธอช่างหอมกว่าเครื่องเทศทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 11, 'โอ เจ้าสาวของฉันจ๋า ริมฝีปากของเธอเสมือนน้ําผึ้งกําลังจะหยดย้อย น้ําผึ้งและน้ํานมอยู่ใต้ลิ้นของเธอ กลิ่นเสื้อผ้าของเธอหอมดุจกลิ่นมาจากเลบานอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 12, 'เจ้าสาวของฉันเอ๋ย น้องสาวของฉันเปรียบประดุจสวนสงวน ดุจอุทยานที่หวงห้ามไว้ และดุจน้ําพุที่ถูกประทับตราไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 13, 'ผลิตผลของเธอดุจสวนต้นทับทิม อีกทั้งผลไม้อันโอชาอย่างอื่นๆ อีกทั้งเทียนขาวและแฝกหอม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 14, 'ต้นแฝกหอมและต้นฝรั่น ต้นตะไคร้และอบเชย อีกทั้งบรรดาต้นไม้สําหรับทํากํายานคือต้นมดยอบและต้นกฤษณา อีกทั้งเครื่องหอมชั้นเยี่ยมทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 15, 'ตัวเธอประดุจดังน้ําพุในอุทยาน ประดุจบ่อน้ําแห่งชีวิต และประดุจลําธารไหลจากเลบานอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 16, 'โอ ลมเหนือเอ๋ย จงตื่นขึ้นเถิด ลมใต้เอ๋ย จงพัดมาเถิด จงพัดโชยสวนของดิฉัน เพื่อของหอมในสวนนั้นจะหอมฟุ้งออกไป ขอให้ที่รักของดิฉันเข้ามาในสวนของเขา และรับประทานผลไม้อันโอชาเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 1, 'น้องสาวของฉันจ๊ะ เจ้าสาวของฉันจ๋า ฉันเข้ามาในสวนของฉันแล้วนะ ฉันมาเก็บเอามดยอบของฉันพร้อมกับไม้สีเสียดของฉันแล้ว ฉันรับประทานรวงผึ้งกับน้ําผึ้งของฉันแล้ว ฉันดื่มน้ําองุ่นกับน้ํานมของฉันแล้ว โอ สหายทั้งหลาย จงรับประทานและจงดื่มเถิด โอ ท่านผู้เป็นที่รักเอ๋ย จงดื่มให้อิ่มหนําเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 2, 'ดิฉันหลับแล้ว แต่ใจของดิฉันยังตื่นอยู่ คือมีเสียงเคาะของที่รักของดิฉันพูดว่า “น้องสาวจ๋า ที่รักของฉันจ๋า เปิดประตูให้ฉันซิจ๊ะ แม่นกเขาของฉันจ๊ะ แม่คนงามหมดจดของฉันจ๋า เพราะศีรษะของฉันก็ถูกน้ําค้างชื้น และเส้นผมของฉันก็ชุ่มด้วยละอองน้ําฟ้าแห่งราตรีกาล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 3, 'ดิฉันเปลื้องเสื้อของดิฉันออกเสียแล้ว ดิฉันจะสวมกลับเข้าไปอีกอย่างไรได้ ดิฉันล้างเท้าของดิฉันแล้ว ทําไมจะให้เท้าของดิฉันกลับเปื้อนไปอีกเล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 4, 'ที่รักของดิฉันสอดมือของเขาเข้ามาทางรูประตู และใจดิฉันก็กระสันถึงเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 5, 'ดิฉันลุกขึ้นไปเปิดประตูให้ที่รักของดิฉัน และมือของดิฉันทําให้มดยอบหยด และนิ้วของดิฉันทําให้น้ํามดยอบย้อยบนลูกสลักกลอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 6, 'ดิฉันเปิดประตูให้ที่รักของดิฉัน แต่ที่รักของดิฉันกลับไปเสียแล้ว เมื่อเขาพูด จิตใจดิฉันมัวตกตะลึง ดิฉันแสวงหาเขา แต่ดิฉันหาเขาไม่พบ ดิฉันร้องเรียกเขา แต่เขามิได้ขานตอบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 7, 'พลตระเวนที่ลาดตระเวนในเมืองได้พบดิฉัน เขาตีดิฉัน เขาทําให้ดิฉันบาดเจ็บ พลตระเวนรักษากําแพงเมืองฉกชิงเอาผ้าคลุมตัวจากดิฉันไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 8, 'โอ บุตรสาวแห่งเยรูซาเล็มเอ๋ย ดิฉันขอให้พวกเธอปฏิญาณว่า ถ้าเธอคนใดได้พบที่รักของดิฉัน เธอจะรับปากบอกเขาว่า ดิฉันป่วยเป็นโรครัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 9, 'โอ แม่สาวงามล้ําเลิศในท่ามกลางสาวอื่นๆ คู่รักของเธอนั้นวิเศษอะไรไปกว่าคู่รักของใครๆ คู่รักของเธอนั้นวิเศษอะไรไปกว่าคู่รักของใครอื่นหรือ เธอจึงได้มาให้พวกฉันปฏิญาณให้เช่นนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 10, 'ที่รักของดิฉันผิวเปล่งปลั่งอมเลือด เขาเป็นเอกในท่ามกลางหมื่นคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 11, 'ศีรษะของเขาดังทองคําเนื้อดี ผมของเขาหยิกและดําเหมือนนกกา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 12, 'ตาของเขาเปรียบเหมือนตานกเขาที่ริมห้วยอาบน้ํานม และจับอยู่ที่ริมกระแสน้ําเต็มฝั่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 13, 'แก้มของเขาเหมือนอย่างลานปลูกไม้สีเสียด ส่งกลิ่นหอมหวน ริมฝีปากของเขาเหมือนดอกลิลลี่หยดน้ํามดยอบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 14, 'มือของเขาดุจวงแหวนทองคําอันประดับด้วยพลอยเขียว ท้องของเขาดุจเสางาช้างและประดับด้วยไพทูรย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 15, 'ขาของเขาดุจเสาหินอ่อนตั้งบนฐานเสียบทองคําเนื้อดี สีหน้าของเขาดุจเลบานอนประเสริฐอย่างไม้สนสีดาร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 16, 'ปากของเขาอ่อนหวานที่สุด ทั่วทั้งสรรพางค์ของเขาล้วนแต่น่ารักน่าใคร่ โอ เหล่าบุตรสาวแห่งเยรูซาเล็มจ๋า นี่คือที่รักของดิฉัน และนี่คือเพื่อนยากของดิฉัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 1, 'โอ แม่สาวงามล้ําเลิศในท่ามกลางสาวอื่นๆ คู่รักของเธอไปไหนเสีย คู่รักของเธอกลับไปไหนเสียแล้วเล่า เพื่อพวกเราจะไปเสาะหาเขากับเธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 2, 'ที่รักของดิฉันลงไปยังสวนของเขาเพื่อจะไปที่ลานปลูกไม้สีเสียด และเพื่อจะไปเลี้ยงฝูงสัตว์ในสวนกับเพื่อจะเก็บดอกลิลลี่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 3, 'ตัวดิฉันเป็นกรรมสิทธิ์ของที่รักของดิฉัน และที่รักก็เป็นของดิฉัน เขาเลี้ยงฝูงสัตว์อยู่ท่ามกลางหมู่ดอกลิลลี่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 4, 'โอ ที่รักของฉันเอ๋ย แม่ช่างสวยงามประหนึ่งเมืองทีรซาห์และงามเย็นตาดังเยรูซาเล็ม แม่เป็นสง่าน่าคร้ามเกรงดังกองทัพมีธงประจํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 5, 'ขอเบือนเนตรไปจากฉันเถอะ เพราะว่าฉันแพ้นัยน์ตาของเธอแล้ว ผมของน้องดุจฝูงแพะที่เคลื่อนมาตามเนินลาดภูเขากิเลอาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 6, 'ซี่ฟันของเธอดังฝูงแกะตัวเมียเพิ่งขึ้นมาจากการชําระล้าง มีลูกแฝดติดมาทุกตัว และหามีตัวใดเป็นหมันไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 7, 'ขมับของเธอเหมือนผลทับทิมผ่าซีกอยู่ในผ้าคลุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 8, 'มีมเหสีหกสิบองค์ และนางห้ามแปดสิบคน พวกหญิงพรหมจารีอีกมากเหลือจะคณนา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 9, 'แม่นกเขาของฉัน แม่คนงามหมดจดของฉัน เป็นคนเดียว เธอเป็นคนเดียวของมารดา เป็นหัวรักหัวใคร่ของผู้ให้กําเนิด สาวๆทั้งหลายเห็นเธอ และเรียกเธอว่า ผาสุก ทั้งเหล่ามเหสีและเหล่านางห้ามก็สรรเสริญเยินยอเธอว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 10, '“แม่สาวคนนี้เป็นผู้ใดหนอ เมื่อมองลงก็ดังอรุโณทัย แจ่มจรัสดังดวงจันทร์ กระจ่างจ้าดังดวงสุริยัน สง่าน่าเกรงขามดังกองทัพมีธงประจํา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 11, 'ดิฉันลงไปในสวนผลนัท เพื่อจะดูหมู่ไม้เขียวตามหุบเขาว่าเถาองุ่นมีดอกตูมออกหรือเปล่า และเพื่อจะดูว่าผลทับทิมมีดอกแล้วหรือยัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 12, 'เมื่อดิฉันยังไม่ทันรู้ตัว จิตใจของดิฉันได้กระทําให้ดิฉันเหมือนรถม้าแห่งอามินาดิบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 13, 'กลับมาเถอะ กลับมาเถิด โอ แม่ชาวชูเลมจ๋า กลับมาเถิด กลับมาเถอะจ๊ะ เพื่อพวกดิฉันจะได้เธอไว้ชมเชย นี่กระไรนะ เธอทั้งหลายจงมองตัวแม่ชาวชูเลม ดังกองทัพสองพวก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 1, 'โอ แม่ธิดาของจ้าว เท้าสวมรองเท้าผูกของเธอนั้นนวยนาดนี่กระไร สะโพกของเธอกลมดิกราวกับเม็ดเพชรที่มือช่างผู้ชํานาญได้เจียระไนไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 2, 'สะดือของเธอดุจอ่างกลมที่มิได้ขาดเหล้าองุ่นประสม ท้องของเธอดังกองข้าวสาลีที่มีดอกลิลลี่ปักไว้ล้อมรอบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 3, 'ถันทั้งสองของเธอเหมือนลูกละมั่งสองตัวซึ่งเป็นละมั่งฝาแฝด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 4, 'ลําคอของเธอประหนึ่งหอคอยสร้างด้วยงาช้าง เนตรทั้งสองของเธอดุจสระในเมืองเฮชโบนที่ริมประตูเมืองบัทรับบิม จมูกของเธอเหมือนหอแห่งเลบานอนซึ่งมองลงเห็นเมืองดามัสกัส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 5, 'ศีรษะของเธอดังยอดภูเขาคารเมล ผมของเธอดุจด้ายสีม่วง กษัตริย์ก็ต้องมนต์เสน่ห์ด้วยเส้นผมนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 6, 'โอ แม่ช่างน่ารัก แม่ช่างชื่นชม เธอนี่ช่างสวยงามต้องตาจริง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 7, 'เธองามระหงดุจต้นอินทผลัม และถันทั้งสองของเธอดังพวงองุ่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 8, 'ฉันจึงคิดว่า ฉันจะปีนขึ้นต้นอินทผลัมนั้น ฉันจะจับพวงเหนี่ยวไว้ ขอให้ถันทั้งสองของเธองามดังพวงองุ่นเถอะ และขอให้ลมหายใจของเธอหอมดังผลแอบเปิ้ลเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 9, 'และขอให้เพดานปากของเธอดุจน้ําองุ่นอย่างดียิ่งสําหรับที่รักของฉัน ดื่มคล่องคอจริงๆ ทําให้ริมฝีปากของคนที่หลับอยู่พูดได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 10, 'ตัวดิฉันเป็นกรรมสิทธิ์ของที่รักของดิฉัน และความปรารถนาของเขาก็เจาะจงเอาตัวดิฉัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 11, 'ที่รักของดิฉันจ๋า มาเถอะจ๊ะ ให้เราพากันออกไปในทุ่งนา ให้เราพักอยู่ตามหมู่บ้าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 12, 'ให้เราตื่นแต่เช้าตรู่ไปยังสวนองุ่น ให้เราดูว่าเถาองุ่นมีดอกตูมออกหรือเปล่า หรือว่ามีดอกบานแล้ว ให้เราดูว่าต้นทับทิมมีดอกหรือยัง ณ ที่นั่นแหละดิฉันจะมอบความรักของดิฉันให้แก่เธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 13, 'โอ ที่รักของดิฉันจ๋า ผลมะเขือดูดาอิมส่งกลิ่นหอมฟุ้งไป แล้วที่ประตูบ้านของพวกดิฉันมีผลไม้อร่อยนานาชนิด มีทั้งผลใหม่และผลเก่าที่ดิฉันได้เก็บรวบรวมไว้สําหรับเธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 1, 'โอ ถ้าเธอได้เป็นเหมือนพี่ชายของดิฉัน ผู้ได้ดูดนมจากอกมารดาของดิฉันก็จะดี เพราะเมื่อดิฉันพบเธอนอกบ้าน ดิฉันจะได้จุบเธอได้ แล้วคนทั้งหลายจะได้ไม่ดูถูกดูหมิ่นดิฉัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 2, 'แล้วดิฉันจะได้เดินนําเธอพาเธอให้เข้ามาในเรือนมารดาของดิฉัน ผู้ซึ่งจะสอนดิฉัน ดิฉันจะได้ให้เธอดื่มน้ําองุ่นใส่เครื่องเทศ และดื่มน้ําทับทิมของดิฉัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 3, 'แล้วมือซ้ายของเขาจะช้อนใต้ศีรษะของดิฉันไว้ และมือขวาของเขาจะสอดกอดดิฉันไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 4, 'โอ บุตรสาวแห่งเยรูซาเล็มเอ๋ย ดิฉันขอให้เธอทั้งหลายปฏิญาณว่า เธอทั้งหลายจะไม่เร้าหรือจะไม่ปลุกที่รักของดิฉันให้ตื่นกระตือขึ้น จนกว่าเขาจะจุใจแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 5, 'แม่คนนี้ที่ขึ้นมาจากถิ่นทุรกันดารอิงแอบแนบมากับคู่รัก คือใครที่ไหนหนอ ดิฉันได้ปลุกเธอเมื่อเธออยู่ใต้ต้นแอบเปิ้ล ที่นั่นแหละที่มารดาของเธอได้ให้กําเนิดเธอ ที่ตรงนั้นแหละผู้ที่คลอดเธอได้ให้กําเนิดเธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 6, 'จงแนบดิฉันไว้ดุจดวงตราแขวนอยู่ที่ใจของเธอ ประดุจดวงตราบนแขนของเธอ เพราะความรักนั้นเข้มแข็งอย่างความตาย ความริษยาก็ดุเดือดเหมือนแดนคนตาย และประกายแห่งความริษยานั้นก็คือประกายเพลิง คือประกายเพลิงที่แสนรุนแรง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 7, 'น้ํามากหลายไม่อาจดับความรักให้มอดเสียได้ หรืออุทกธารทั้งหลายไม่อาจท่วมความรักให้สําลักตายเสียได้ แม้ว่าคนใดจะเอาทรัพย์สมบัติในเหย้าเรือนของตนทั้งสิ้นมาแลกกับความรักนั้น คนนั้นจะได้รับความหมิ่นประมาทจากคนทั้งหลายเป็นอย่างยิ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 8, 'เรามีน้องสาวคนหนึ่งและเธอยังไม่มีถัน เราจะทําอย่างไรกับน้องสาวของเรา เมื่อถึงวันที่เขามาสู่ขอน้องของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 9, 'ถ้าหากน้องสาวนั้นเป็นกําแพง พวกเราก็จะสร้างปราสาทเงินไว้หลังหนึ่ง และถ้าหากน้องเป็นประตู พวกเราจะโอบล้อมเธอด้วยแผ่นไม้สนสีดาร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 10, 'ดิฉันเป็นกําแพง ถันทั้งสองของดิฉันเหมือนดังหอคอย เพราะฉะนั้นในสายตาของเขาดิฉันจึงเป็นดังผู้ที่ได้รับความโปรดปราน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 11, 'ซาโลมอนทรงมีสวนองุ่นอยู่แปลงหนึ่งที่เมืองบาอัลฮาโมน พระองค์ทรงมอบสวนองุ่นนั้นให้แก่ผู้รักษาสวนเช่า ทุกคนต้องส่งเงินคนละพันแผ่นเป็นค่าผลไม้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 12, 'สวนองุ่นของดิฉัน ซึ่งเป็นของดิฉันเอง อยู่ต่อหน้าดิฉัน โอ ข้าแต่ซาโลมอน พันนั้นพระองค์เอาไปเถิด และผู้ดูแลผลไม้ในสวนนั้นก็เอาไปคนละสองร้อยเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 13, 'โอ เธอ ผู้อยู่ในสวน พวกเพื่อนๆของเธอคอยฟังเสียงของเธออยู่ ขอให้ฉันได้ยินเสียงเธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 14, 'ที่รักของดิฉันจ๋า เร็วๆเข้าเถอะจ๊ะ ขอให้เธอเป็นดังละมั่งหรือกวางหนุ่มบนภูเขาต้นสีเสียดเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 1, 'นิมิตของอิสยาห์บุตรชายของอามอส ซึ่งท่านได้เห็นเกี่ยวกับยูดาห์และเยรูซาเล็ม ในรัชกาลของอุสซียาห์ โยธาม อาหัส และเฮเซคียาห์กษัตริย์แห่งยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 2, 'โอ ฟ้าสวรรค์เอ๋ย จงฟัง โอ แผ่นดินโลกเอ๋ย จงเงี่ยหู เพราะพระเยโฮวาห์ได้ตรัสว่า “เราได้เลี้ยงดูบุตรและให้เติบโตขึ้น แต่เขาทั้งหลายได้กบฏต่อเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 3, 'วัวรู้จักเจ้าของของมัน และลาก็รู้จักรางหญ้าของนายมัน แต่อิสราเอลไม่รู้จัก ชนชาติของเราไม่พิจารณาเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 4, 'เออ ประชาชาติบาปหนา ชนชาติซึ่งหนักด้วยความชั่วช้า เชื้อสายของผู้กระทําความชั่วร้าย บรรดาบุตรที่ทําความเสียหาย เขาทั้งหลายได้ทอดทิ้งพระเยโฮวาห์ เขาได้ยั่วองค์บริสุทธิ์ของอิสราเอลให้ทรงพระพิโรธ เขาทั้งหลายหันหลังให้เสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 5, 'ยังจะให้เฆี่ยนเจ้าตรงไหนอีกที่เจ้ากบฏอยู่เรื่อยไป ศีรษะก็เจ็บหมด จิตใจก็อ่อนเปลี้ยไปสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 6, 'ตั้งแต่ฝ่าเท้าจนถึงศีรษะไม่มีความปกติในนั้นเลย มีแต่บาดแผลและฟกช้ําและเป็นแผลเลือดไหล ไม่เห็นบีบออกหรือพันไว้ หรือทําให้อ่อนลงด้วยน้ํามัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 7, 'ประเทศของเจ้าก็รกร้างและหัวเมืองของเจ้าก็ถูกไฟเผา ส่วนแผ่นดินของเจ้าคนต่างด้าวก็ทําลายเสียต่อหน้าเจ้า มันก็รกร้างไป เหมือนอย่างถูกพลิกคว่ําเสียโดยคนต่างด้าวนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 8, 'ส่วนธิดาแห่งศิโยนก็ถูกทิ้งไว้เหมือนอย่างเพิงที่ในสวนองุ่น เหมือนเพิงในไร่แตงกวา เหมือนเมืองที่ถูกล้อม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 9, 'ถ้าพระเยโฮวาห์จอมโยธามิได้เหลือคนไว้ให้เราบ้างเล็กน้อยแล้ว เราก็จะได้เป็นเหมือนเมืองโสโดม และจะเป็นเหมือนเมืองโกโมราห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 10, 'ดูก่อนท่านผู้ปกครองเมืองโสโดม จงฟังพระวจนะของพระเยโฮวาห์ ดูก่อนท่านประชาชนเมืองโกโมราห์ จงเงี่ยหูฟังพระราชบัญญัติของพระเจ้าของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 11, 'พระเยโฮวาห์ตรัสว่า “เครื่องบูชาอันมากมายของเจ้านั้นจะเป็นประโยชน์อะไรแก่เรา เราเอือมแกะตัวผู้อันเป็นเครื่องเผาบูชา และไขมันของสัตว์ที่ขุนไว้นั้นแล้ว เรามิได้ปีติยินดีในเลือดของวัวผู้หรือลูกแกะหรือแพะผู้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 12, 'เมื่อเจ้าเข้ามาเฝ้าเรา ผู้ใดขอให้เจ้าทําอย่างนี้ที่เหยียบย่ําเข้ามาในบริเวณพระนิเวศของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 13, 'อย่านําเครื่องบูชาอันเปล่าประโยชน์มาอีกเลย เครื่องหอมเป็นสิ่งน่าสะอิดสะเอียนต่อเรา วันขึ้นหนึ่งค่ํา และวันสะบาโต และการเรียกประชุม เราทนอีกไม่ได้ มันเป็นความชั่วช้า แม้แต่การประชุมอันศักดิ์สิทธิ์นั้นด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 14, 'ใจของเราเกลียดวันขึ้นหนึ่งค่ําของเจ้าและวันเทศกาลตามกําหนดของเจ้า มันกลายเป็นภาระแก่เรา เราแบกเหน็ดเหนื่อยเสียแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 15, 'เมื่อเจ้ากางมือของเจ้าออกเราจะซ่อนตาของเราเสียจากเจ้า แม้ว่าเจ้าจะอธิษฐานมากมายเราจะไม่ฟัง มือของเจ้าเปรอะไปด้วยโลหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 16, 'จงชําระตัว จงทําตัวให้สะอาด จงเอาการกระทําที่ชั่วของเจ้าออกไปให้พ้นจากสายตาของเรา จงเลิกกระทําชั่ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 17, 'จงฝึกกระทําดี จงแสวงหาความยุติธรรม จงบรรเทาผู้ถูกบีบบังคับ จงป้องกันให้ลูกกําพร้าพ่อ จงสู้ความเพื่อหญิงม่าย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 18, 'พระเยโฮวาห์ตรัสว่า “มาเถิด ให้เราสู้ความกัน ถึงบาปของเจ้าเหมือนสีแดงเข้มก็จะขาวอย่างหิมะ ถึงมันจะแดงอย่างผ้าแดงก็จะกลายเป็นอย่างขนแกะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 19, 'ถ้าเจ้าเต็มใจและเชื่อฟัง เจ้าจะได้กินผลดีแห่งแผ่นดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 20, 'แต่ถ้าเจ้าปฏิเสธและกบฏ เจ้าจะถูกทําลายเสียด้วยคมดาบ เพราะว่าพระโอษฐ์ของพระเยโฮวาห์ได้ตรัสแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 21, 'เมืองที่สัตย์ซื่อกลายเป็นแพศยาเสียแล้วหนอ คือเธอที่เคยเปี่ยมด้วยความยุติธรรม ความชอบธรรมเคยพํานักอยู่ในเธอ แต่เดี๋ยวนี้พวกฆาตกรพํานักอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 22, 'เงินของเจ้าได้กลายเป็นขี้เงินไปแล้ว น้ําองุ่นของเจ้าปนน้ําแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 23, 'เจ้านายของเจ้าเป็นพวกกบฏและเป็นเพื่อนของโจร ทุกคนรักสินบนและวิ่งตามของกํานัล เขามิได้ป้องกันให้ลูกกําพร้าพ่อ และคดีของหญิงม่ายก็ไม่มาถึงเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 24, 'ฉะนั้น องค์พระผู้เป็นเจ้าคือพระเยโฮวาห์จอมโยธา ผู้ทรงมหิทธิฤทธิ์ของอิสราเอลตรัสว่า “ดูเถิด เราจะระบายความโกรธของเราเหนือศัตรูของเรา และแก้แค้นข้าศึกของเราเสียเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 25, 'เราจะหันมือของเรามาสู้เจ้าและจะถลุงไล่ขี้แร่ของเจ้าออกเสียอย่างกับล้างด้วยน้ําด่าง และเอาของเจือปนของเจ้าออกให้หมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 26, 'และเราจะคืนผู้พิพากษาของเจ้าให้ดังเดิม และคืนที่ปรึกษาของเจ้าอย่างกับตอนแรก ภายหลังเขาจะเรียกเจ้าว่า ‘นครแห่งความชอบธรรม นครสัตย์ซื่อ’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 27, 'ศิโยนจะรับการไถ่ด้วยความยุติธรรม และบรรดาคนในนครที่กลับใจจะรับการไถ่ด้วยความชอบธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 28, 'แต่พวกละเมิดและพวกคนบาปจะถูกทําลายด้วยกัน และบรรดาคนเหล่านั้นที่ละทิ้งพระเยโฮวาห์จะถูกล้างผลาญ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 29, 'เพราะเจ้าจะละอายเรื่องต้นโอ๊กที่เจ้าปรารถนานั้น และเจ้าจะอับอายเรื่องสวนซึ่งเจ้าเลือก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 30, 'เพราะเจ้าจะเป็นเหมือนต้นโอ๊กที่ใบเหี่ยวแห้ง และเหมือนสวนที่ขาดน้ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 31, 'และผู้ที่แข็งแรงจะกลายเป็นใยป่าน และผู้ประกอบมันขึ้นจะเป็นเหมือนประกายไฟ และทั้งสองจะไหม้เสียด้วยกัน ไม่มีผู้ใดดับได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 1, 'ถ้อยคําซึ่งอิสยาห์บุตรชายของอามอสเห็นเกี่ยวกับยูดาห์และเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 2, 'ในยุคหลังจะเป็นดังนี้ คือภูเขาแห่งพระนิเวศของพระเยโฮวาห์จะถูกสถาปนาขึ้นให้สูงที่สุดในจําพวกภูเขาทั้งหลาย และจะถูกยกขึ้นให้เหนือบรรดาเนินเขา และประชาชาติทั้งสิ้นจะหลั่งไหลเข้ามาหา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 3, 'และชนชาติทั้งหลายเป็นอันมากจะมากล่าวว่า “มาเถิด ให้เราขึ้นไปยังภูเขาของพระเยโฮวาห์ ยังพระนิเวศแห่งพระเจ้าของยาโคบ เพื่อพระองค์จะทรงสอนวิถีของพระองค์แก่เรา และเพื่อเราจะเดินในมรรคาของพระองค์” เพราะว่าพระราชบัญญัติจะออกมาจากศิโยน และพระวจนะของพระเยโฮวาห์จะออกมาจากเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 4, 'พระองค์จะทรงวินิจฉัยระหว่างบรรดาประชาชาติ และจะทรงตําหนิชนชาติทั้งหลายเป็นอันมาก และเขาทั้งหลายจะตีดาบของเขาให้เป็นผาลไถนา และหอกของเขาให้เป็นขอลิด ประชาชาติจะไม่ยกดาบต่อสู้กันอีก เขาจะไม่ศึกษายุทธศาสตร์อีกต่อไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 5, 'โอ วงศ์วานของยาโคบเอ๋ย มาเถิด ให้เราทั้งหลายดําเนินในสว่างของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 6, 'เพราะฉะนั้นพระองค์ทรงละทิ้งชนชาติของพระองค์เสีย คือวงศ์วานของยาโคบ เพราะว่าเขาอุดมด้วยหมอดูจากตะวันออกอย่างคนฟีลิสเตีย และเขาตีสนิทกับคนต่างชาติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 7, 'แผ่นดินของเขาเต็มด้วยเงินและทองคํา ทรัพย์สมบัติของเขาไม่มีสิ้นสุด แผ่นดินของเขาเต็มด้วยม้า รถรบของเขาไม่มีสิ้นสุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 8, 'แผ่นดินของเขาเต็มด้วยรูปเคารพ เขากราบไหว้ผลงานแห่งมือของเขา ต่อสิ่งซึ่งนิ้วมือของเขาได้กระทํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 9, 'คนต่ําต้อยจึงกราบลงและคนใหญ่โตก็ถ่อมตัวลง ฉะนั้นอย่าอภัยเขาเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 10, 'จงหลบเข้าไปในหินและซ่อนอยู่ในผงคลี ให้พ้นจากความน่าเกรงขามของพระเยโฮวาห์ และจากสง่าราศีแห่งความโอ่อ่าตระการของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 11, 'และท่าอันผยองของมนุษย์จะตกต่ําลง และความจองหองของคนจะถูกปราบลง พระเยโฮวาห์องค์เดียวจะเป็นผู้เทิดทูนในวันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 12, 'เพราะว่าวันแห่งพระเยโฮวาห์จอมโยธาจะสู้สารพัดที่เย่อหยิ่งและสูงส่ง สู้สารพัดที่ถูกยกขึ้นและพวกเขาจะถูกปราบลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 13, 'สู้ต้นสนสีดาร์ทั้งสิ้นของเลบานอนที่สูงและที่ถูกยกขึ้น และสู้ต้นโอ๊กทั้งสิ้นของบาชาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 14, 'สู้ภูเขาสูงทั้งสิ้น และสู้เนินเขาทั้งปวงที่ถูกยกขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 15, 'สู้หอคอยสูงทุกแห่ง และสู้กําแพงที่เข้มแข็งทุกแห่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 16, 'สู้กําปั่นทั้งสิ้นของทารชิช และสู้รูปภาพงดงามทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 17, 'และความผยองของมนุษย์จะต้องถูกปราบลง และความจองหองของคนจะตกต่ําลง ในวันนั้นพระเยโฮวาห์องค์เดียวจะเป็นที่เทิดทูน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 18, 'และรูปเคารพทั้งหลายพระองค์จะทรงทําลายอย่างเต็มที่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 19, 'และคนจะเข้าไปในถ้ําหินและในโพรงดินให้พ้นจากความน่าเกรงขามของพระเยโฮวาห์ และจากสง่าราศีแห่งความโอ่อ่าตระการของพระองค์ เมื่อพระองค์ทรงลุกขึ้นกระทําให้โลกสั่นสะท้าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 20, 'ในวันนั้นคนจะเหวี่ยงรูปเคารพของตนออกไปอันทําด้วยเงิน และรูปเคารพของตนที่ทําด้วยทองคํา ซึ่งเขาทําไว้เพื่อตนเองจะนมัสการ ไปยังตัวตุ่นและตัวค้างคาว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 21, 'เพื่อเขาจะเข้าถ้ําหินและเข้าซอกผา ให้พ้นจากความน่าเกรงขามของพระเยโฮวาห์ และจากสง่าราศีแห่งความโอ่อ่าตระการของพระองค์ เมื่อพระองค์ทรงลุกขึ้นกระทําให้โลกสั่นสะท้าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 22, 'จงตัดขาดจากมนุษย์เสียเถิด ซึ่งในจมูกของเขามีลมหายใจ เพราะเขามีคุณค่าอะไรเล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 1, 'เพราะดูเถิด องค์พระผู้เป็นเจ้า คือพระเยโฮวาห์จอมโยธาทรงนําออกไปเสียจากเยรูซาเล็มและจากยูดาห์ ซึ่งเครื่องค้ําและเครื่องจุน เครื่องค้ําอันเป็นอาหารทั้งหมด และเครื่องค้ําอันเป็นน้ําทั้งหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 2, 'พวกทแกล้วและพวกทหาร ผู้วินิจฉัยและผู้พยากรณ์ ผู้เฉลียวฉลาดและพวกผู้ใหญ่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 3, 'นายห้าสิบและผู้มียศ ที่ปรึกษาและคนเล่นกลที่มีฝีมือ และนักพูดที่วาทะโวหารดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 4, 'และเราจะกระทําให้เด็กๆเป็นเจ้านายของเขา และทารกจะปกครองเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 5, 'และประชาชนจะถูกบีบบังคับ ทุกคนจะบีบบังคับเพื่อนของตน และทุกคนจะบีบบังคับเพื่อนบ้านของตน เด็กๆจะทะลึ่งต่อผู้ใหญ่ และคนถ่อยต่อคนผู้มีเกียรติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 6, 'เมื่อใครคนหนึ่งไปยึดตัวพี่น้องของเขาในเรือนของบิดาของเขา กล่าวว่า “เจ้ามีเสื้อคลุมอยู่แล้ว เจ้าจงเป็นผู้นําของเรา และซากที่อยู่นี้จะอยู่ใต้กํามือของเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 7, 'ในวันนั้นเขาจะคัดค้านว่า “ข้าพเจ้าจะไม่ยอมเป็นผู้สมาน เพราะในเรือนของข้าพเจ้าไม่มีทั้งอาหารและเสื้อคลุม ท่านจะตั้งข้าพเจ้าให้เป็นผู้นําของประชาชนไม่ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 8, 'เพราะเยรูซาเล็มก็ล่มจมและยูดาห์ก็ล้มคว่ํา เพราะว่าลิ้นของเขาและการกระทําของเขาก็ต่อสู้พระเยโฮวาห์ กบฏต่อพระเนตรอันรุ่งโรจน์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 9, 'สีหน้าของเขาเป็นพยานปรักปรําเขาทั้งหลาย เขาป่าวร้องความผิดของเขาอย่างโสโดม เขามิได้ปิดบังไว้ วิบัติแก่จิตใจเขา เพราะว่าเขาได้นําความชั่วร้ายมาเป็นบําเหน็จแก่ตัวเขาเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 10, 'จงบอกคนชอบธรรมว่า เขาทั้งหลายจะเป็นสุข เพราะเขาจะได้รับประทานผลแห่งการกระทําของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 11, 'วิบัติแก่คนชั่ว ความร้ายจะตกแก่เขา เพราะว่าสิ่งใดที่มือเขาได้กระทํา เขาจะถูกกระทําเช่นกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 12, 'ส่วนชนชาติของเรา เด็กๆเป็นผู้บีบบังคับเขา และผู้หญิงปกครองเหนือเขา โอ ชนชาติของเราเอ๋ย ผู้นําของเจ้าทําเจ้าให้ผิด และทําลายแนวทางทั้งหลายของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 13, 'พระเยโฮวาห์ทรงเข้าประทับสู้ความ พระองค์ประทับยืนพิพากษาชนชาติของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 14, 'พระเยโฮวาห์จะทรงเข้าพิพากษาพวกผู้ใหญ่และเจ้านายชนชาติของพระองค์ “เจ้าทั้งหลายนี่แหละซึ่งได้กลืนกินสวนองุ่นเสีย ของที่ริบมาจากคนจนก็อยู่ในเรือนของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 15, 'ซึ่งเจ้าได้ทุบชนชาติของเราเป็นชิ้นๆ และได้บดบี้หน้าของคนจนนั้นเจ้าหมายความว่ากระไร” องค์พระผู้เป็นเจ้าพระเจ้าจอมโยธาตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 16, 'พระเยโฮวาห์ตรัสอีกว่า “เพราะธิดาทั้งหลายของศิโยนนั้นก็ผยอง และเดินคอยืดคอยาว ตาของเขาชม้อยชม้าย เดินกระตุ้งกระติ้ง ขยับเท้าให้เสียงกรุ๋งกริ๋ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 17, 'องค์พระผู้เป็นเจ้าจะทรงให้เป็นชันนะตุที่ศีรษะของบรรดาธิดาของศิโยน และพระเยโฮวาห์จะทรงกระทําให้ที่ส่วนลับของเขาทั้งหลายโล้นไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 18, 'ในวันนั้นองค์พระผู้เป็นเจ้าจะทรงนําเอาเครื่องวิจิตรงดงามไปเสีย คือกําไลข้อเท้า เครื่องประดับศีรษะ เครื่องประดับรูปวงเดือน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 19, 'จี้ กําไลมือ ผ้าแถบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 20, 'ผ้ามาลา กําไลเท้า ผ้าคาดศีรษะ หีบเครื่องน้ําอบ ตะกรุดพิสมร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 21, 'แหวนตรา และแหวนจมูก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 22, 'เสื้องาน และเสื้อคลุม ผ้าคลุม และกระเป๋าถือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 23, 'กระจก เสื้อผ้าลินิน ผ้าโพกศีรษะ และผ้าคลุมตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 24, 'ต่อมาแทนน้ําอบจะมีแต่ความเน่า แทนผ้าคาดเอวจะมีเชือก แทนผมดัดจะมีแต่ศีรษะล้าน แทนเสื้องามล้ําค่าจะคาดเอวด้วยผ้ากระสอบ แทนความงดงามจะมีแต่รอยไหม้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 25, 'พวกผู้ชายของเจ้าจะล้มลงด้วยดาบ และทแกล้วทหารของเจ้าจะล้มในสงคราม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 26, 'ประตูทั้งหลายของเธอจะคร่ําครวญและโศกเศร้า เธอผู้อยู่อย่างโดดเดี่ยวจะนั่งบนพื้นดิน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 1, 'ในวันนั้นหญิงเจ็ดคนจะยึดชายคนหนึ่งไว้ กล่าวว่า “เราจะหากินของเรา หานุ่งหาห่มของเราเอง ขอเพียงให้เขาเรียกเราด้วยชื่อของท่าน ขอจงปลดความอดสูของเราเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 2, 'ในวันนั้นอังกูรของพระเยโฮวาห์จะงดงามและรุ่งโรจน์ และพืชผลของแผ่นดินนั้นจะเป็นความภูมิใจและเป็นเกียรติของผู้ที่หลีกเลี่ยงหลบหนีแห่งอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 3, 'และต่อมาคนที่เหลืออยู่ในศิโยนและค้างอยู่ในเยรูซาเล็ม เขาจะเรียกว่าบริสุทธิ์ คือทุกคนผู้มีชื่อในทะเบียนชีวิตในเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 4, 'ในเมื่อองค์พระผู้เป็นเจ้าจะทรงล้างความโสโครกของธิดาทั้งหลายของศิโยน และชําระรอยโลหิตของเยรูซาเล็มจากท่ามกลางเมืองนั้น ด้วยวิญญาณแห่งการพิพากษาและด้วยวิญญาณแห่งการเผาผลาญ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 5, 'และพระเยโฮวาห์จะทรงสร้างเมฆและควันเพื่อกลางวัน และแสงแห่งเปลวเพลิงเพื่อกลางคืนเหนือที่อยู่อาศัยทั้งสิ้นของภูเขาศิโยน และเหนือประชุมชนเมืองนั้น เพราะจะมีการป้องกันอยู่เหนือสง่าราศีทั่วสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 6, 'จะมีพลับพลาทําร่มกลางวันบังแดด และเป็นที่ลี้ภัยและที่กําบังพายุและฝน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 1, 'บัดนี้ข้าพเจ้าจะร้องเพลงถึงที่รักของข้าพเจ้า เป็นเพลงของที่รักของข้าพเจ้าเกี่ยวกับสวนองุ่นของท่าน ที่รักของข้าพเจ้ามีสวนองุ่นแปลงหนึ่ง อยู่บนเนินเขาอันอุดมยิ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 2, 'ท่านทํารั้วไว้รอบแล้วเก็บก้อนหินออกหมดและปลูกเถาองุ่นอย่างดีไว้ ท่านสร้างหอเฝ้าไว้ท่ามกลาง และสกัดบ่อย่ําองุ่นไว้ในสวนนั้นด้วย ท่านมุ่งหวังว่ามันจะบังเกิดลูกองุ่น แต่มันบังเกิดลูกเถาเปรี้ยว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 3, 'บัดนี้ โอ ชาวเยรูซาเล็มและคนยูดาห์เอ๋ย ขอตัดสินระหว่างเราและสวนองุ่นของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 4, 'มีอะไรอีกที่จะทําได้เพื่อสวนองุ่นของเรา ซึ่งเรายังไม่ได้ทําให้ ก็เมื่อเรามุ่งหวังว่ามันจะบังเกิดลูกองุ่น ไฉนมันจึงเกิดลูกเถาเปรี้ยว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 5, 'บัดนี้เราจะบอกเจ้าทั้งหลายให้ว่าเราจะทําอะไรกับสวนองุ่นของเรา เราจะรื้อรั้วต้นไม้ของมันเสีย แล้วมันก็จะถูกเผา เราจะพังกําแพงของมันลง มันก็จะถูกเหยียบย่ําลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 6, 'เราจะกระทํามันให้เป็นที่ร้าง จะไม่มีใครลิดแขนงหรือพรวนดิน หนามย่อยหนามใหญ่ก็จะงอกขึ้น และเราจะบัญชาเมฆไม่ให้โปรยฝนรดมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 7, 'เพราะว่าสวนองุ่นของพระเยโฮวาห์จอมโยธาคือวงศ์วานอิสราเอล และคนยูดาห์เป็นหมู่ไม้ที่พระองค์ทรงชื่นพระทัย และพระองค์ทรงมุ่งหวังความยุติธรรม แต่ดูเถิด มีแต่การนองเลือด หวังความชอบธรรม แต่ ดูเถิด เสียงร้องให้ช่วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 8, 'วิบัติแก่ผู้เหล่านั้นที่เสริมบ้านหลังหนึ่งเข้ากับอีกหลังหนึ่ง และเสริมนาเข้ากับนา จนไม่มีที่อีกแล้ว เพื่อเขาทั้งหลายต้องอยู่ลําพังในท่ามกลางแผ่นดินนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 9, 'พระเยโฮวาห์จอมโยธาทรงกล่าวที่หูของข้าพเจ้าว่า “เป็นความจริงทีเดียว บ้านหลายหลังจะต้องรกร้าง บ้านใหญ่บ้านงามจะไม่มีคนอาศัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 10, 'เพราะว่าสวนองุ่นยี่สิบห้าไร่จะได้ผลแต่เพียงบัทเดียว และเมล็ดพืชหนึ่งโฮเมอร์จะให้ผลแต่เอฟาห์เดียว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 11, 'วิบัติแก่คนเหล่านั้นที่ลุกขึ้นแต่เช้ามืด เพื่อวิ่งไปตามเมรัย ผู้เฉื่อยแฉะอยู่จนดึก จนเหล้าองุ่นทําให้เขาเมาหยําเป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 12, 'เขามีพิณเขาคู่และพิณใหญ่ รํามะนา ปี่ และเหล้าองุ่น ณ งานเลี้ยงของเขา แต่เขาทั้งหลายมิได้เอาใจใส่ในพระราชกิจของพระเยโฮวาห์ หรือพิจารณาพระหัตถกิจของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 13, 'เพราะฉะนั้นชนชาติของเราจึงตกไปเป็นเชลย เพราะขาดความรู้ ผู้มีเกียรติของเขาก็หิวแย่ และมวลชนของเขาก็แห้งผากไปเพราะความกระหาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 14, 'เพราะฉะนั้นนรกก็ขยายที่ของมันออก และอ้าปากเสียโดยไม่จํากัด และสง่าราศีของเขา และมวลชนของเขา และเสียงอึงคะนึงของเขา และผู้เริงโลดอยู่ ก็จะลงไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 15, 'คนต่ําต้อยจึงจะกราบลง และคนเข้มแข็งก็ถ่อมตัวลง และนัยน์ตาของผู้ผยองก็ถูกลดต่ําลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 16, 'แต่พระเยโฮวาห์จอมโยธาจะได้รับการเทิดทูนไว้โดยความยุติธรรม และพระเจ้าองค์บริสุทธิ์จะได้ทรงสําแดงความบริสุทธิ์โดยความชอบธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 17, 'แล้วลูกแกะจะเที่ยวหากินที่นั่นตามลักษณะท่าทางของมัน คนแปลกหน้าจะหากินในที่ปรักหักพังของสัตว์ที่อ้วน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 18, 'วิบัติแก่คนเหล่านั้นที่ลากความชั่วช้าด้วยสายของความไร้สาระ ผู้ลากบาปอย่างกับใช้เชือกโยงเกวียน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 19, 'ผู้กล่าวว่า “ให้พระองค์รีบร้อน ให้พระองค์เร่งงานของพระองค์ เพื่อเราจะได้เห็น ให้พระประสงค์ขององค์ผู้บริสุทธิ์แห่งอิสราเอลเสด็จมาใกล้ ขอให้มาเพื่อเราจะได้รู้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 20, 'วิบัติแก่คนเหล่านั้นที่เรียกความชั่วร้ายว่าความดี และความดีว่าความชั่วร้าย ผู้ถือเอาว่าความมืดเป็นความสว่าง และความสว่างเป็นความมืด ผู้ถือเอาว่าความขมเป็นความหวาน และความหวานเป็นความขม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 21, 'วิบัติแก่คนเหล่านั้นที่ฉลาดตามสายตาของตนเอง และสุขุมรอบคอบในสายตาของตนเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 22, 'วิบัติแก่คนเหล่านั้นที่เก่งกล้าในการดื่มเหล้าองุ่น และเป็นคนแกล้วกล้าในการประสมเมรัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 23, 'ผู้ปล่อยตัวคนทําผิดเพราะเขารับสินบน และเอาความชอบธรรมไปจากผู้ชอบธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 24, 'ดังนั้นเปลวเพลิงกลืนตอข้าวฉันใด และเพลิงเผาผลาญหญ้าแห้งฉันใด รากของเขาก็จะเป็นเหมือนความเปื่อยเน่า และดอกบานของเขาจะฟุ้งไปเหมือนผงคลีฉันนั้น เพราะเขาทั้งหลายทอดทิ้งพระราชบัญญัติของพระเยโฮวาห์จอมโยธา และได้ดูหมิ่นพระวจนะขององค์บริสุทธิ์แห่งอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 25, 'เหตุฉะนั้นพระพิโรธของพระเยโฮวาห์จึงพลุ่งขึ้นต่อชนชาติของพระองค์ และพระองค์ทรงเหยียดพระหัตถ์ของพระองค์ออกสู้เขาและตีเขา และภูเขาทั้งหลายก็สั่นสะเทือน และซากศพของเขาทั้งหลายถูกฉีกขาดกลางถนน ถึงกระนั้นก็ดี พระพิโรธของพระองค์ก็มิได้หันกลับ แต่พระหัตถ์ของพระองค์ก็ยังเหยียดออกอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 26, 'พระองค์จะทรงยกอาณัติสัญญาณให้แก่ประชาชาติที่ห่างไกล และจะทรงผิวพระโอษฐ์เรียกเขามาจากที่สุดปลายแผ่นดินโลก และดูเถิด เขาจะมาอย่างเร็วและรีบเร่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 27, 'ไม่มีผู้ใดในพวกเขาจะอ่อนเปลี้ย ไม่มีผู้ใดจะสะดุด ไม่มีผู้ใดจะหลับสนิทหรือนิทรา ผ้าคาดเอวสักผืนหนึ่งก็จะไม่หลุดลุ่ย สายรัดรองเท้าก็จะไม่ขาดสักสายหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 28, 'ลูกธนูของเขาก็แหลม บรรดาคันธนูของเขาก็ก่งไว้ กีบม้าทั้งหลายของเขาจะเหมือนกับหินเหล็กไฟ และล้อของเขาทั้งหลายเหมือนลมหมุน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 29, 'เสียงคํารามของเขาจะเหมือนสิงโต เหมือนสิงโตหนุ่ม เขาเหล่านั้นจะคําราม เขาจะคํารนและตะครุบเหยื่อของเขา และเขาจะขนเอาไปเสีย และไม่มีผู้ใดช่วยเหยื่อนั้นให้พ้นไปได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 30, 'ในวันนั้นเขาทั้งหลายจะคํารนเหนือเหยื่อนั้นเหมือนเสียงคะนองของทะเล และถ้ามีผู้หนึ่งผู้ใดมองที่แผ่นดิน ดูเถิด ความมืดและความทุกข์ใจ และสว่างแห่งฟ้าสวรรค์ก็มืดลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 1, 'ในปีที่กษัตริย์อุสซียาห์สิ้นพระชนม์ ข้าพเจ้าเห็นองค์พระผู้เป็นเจ้าประทับ ณ พระที่นั่งสูงและเทิดทูนขึ้น และชายฉลองพระองค์ของพระองค์เต็มพระวิหาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 2, 'เหนือพระองค์มีเสราฟิมยืนอยู่ แต่ละตนมีปีกหกปีก ใช้สองปีกบังหน้า และสองปีกคลุมเท้า และด้วยสองปีกบินไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 3, 'ต่างก็ร้องต่อกันและกันว่า “บริสุทธิ์ บริสุทธิ์ บริสุทธิ์ พระเยโฮวาห์จอมโยธา แผ่นดินโลกทั้งสิ้นเต็มด้วยสง่าราศีของพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 4, 'และรากฐานของธรณีประตูทั้งหลายก็สั่นสะเทือนด้วยเสียงของผู้ร้อง และพระนิเวศก็มีควันเต็มไปหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 5, 'และข้าพเจ้าว่า “วิบัติแก่ข้าพเจ้า เพราะข้าพเจ้าพินาศแล้ว เพราะข้าพเจ้าเป็นคนริมฝีปากไม่สะอาด และข้าพเจ้าอาศัยอยู่ในหมู่ชนชาติที่ริมฝีปากไม่สะอาด เพราะนัยน์ตาของข้าพเจ้าได้เห็นกษัตริย์ คือพระเยโฮวาห์จอมโยธา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 6, 'แล้วตนหนึ่งในเสราฟิมบินมาหาข้าพเจ้า ในมือมีถ่านเพลิง ซึ่งเขาเอาคีมคีบมาจากแท่นบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 7, 'และเขาถูกต้องปากของข้าพเจ้าพูดว่า “ดูเถิด สิ่งนี้ได้ถูกต้องริมฝีปากของเจ้าแล้ว ความชั่วช้าของเจ้าก็ถูกยกเสีย และเจ้าก็จะรับการลบมลทินบาป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 8, 'และข้าพเจ้าได้ยินพระสุรเสียงขององค์พระผู้เป็นเจ้าตรัสว่า “เราจะใช้ผู้ใดไป และผู้ใดจะไปแทนพวกเรา” แล้วข้าพเจ้าทูลว่า “ข้าพระองค์นี่พระเจ้าข้า ขอทรงใช้ข้าพระองค์ไปเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 9, 'และพระองค์ตรัสว่า “ไปเถอะ และกล่าวแก่ชนชาตินี้ว่า ‘ฟังแล้วฟังเล่า แต่อย่าเข้าใจ ดูแล้วดูเล่า แต่อย่ามองเห็น’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 10, 'จงกระทําให้จิตใจของชนชาตินี้มึนงง และให้หูทั้งหลายของเขาหนัก และปิดตาของเขาทั้งหลายเสีย เกรงว่าเขาจะเห็นด้วยตาของเขา และได้ยินด้วยหูของเขา และเข้าใจด้วยจิตใจของเขา และหันกลับมาได้รับการรักษาให้หาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 11, 'แล้วข้าพเจ้ากล่าวว่า “ข้าแต่องค์พระผู้เป็นเจ้า นานสักเท่าใด” และพระองค์ตรัสตอบว่า “จนหัวเมืองทั้งหลายถูกทิ้งร้างไม่มีชาวเมือง และบ้านเรือนไม่มีคน และแผ่นดินก็รกร้างอย่างสิ้นเชิง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 12, 'และพระเยโฮวาห์ทรงกวาดคนออกไปไกล และที่ที่ทอดทิ้งก็มีมากอยู่ท่ามกลางแผ่นดินนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 13, 'และแม้ว่ามีเหลืออยู่ในนั้นสักหนึ่งในสิบ ก็จะกลับมาและถูกเผาไฟ เหมือนต้นน้ํามันสนหรือต้นโอ๊กซึ่งเหลืออยู่แต่ตอเมื่อถูกโค่น” ตอของมันจะเป็นเชื้อสายบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 1, 'ต่อมาในรัชกาลของอาหัสโอรสของโยธาม โอรสของอุสซียาห์ กษัตริย์แห่งยูดาห์ เรซีนกษัตริย์แห่งซีเรีย และเปคาห์โอรสของเรมาลิยาห์ กษัตริย์แห่งอิสราเอลได้ขึ้นมายังเยรูซาเล็มเพื่อกระทําสงครามกับเมืองนั้น แต่รบไม่ชนะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 2, 'เมื่อเขาไปบอกที่ราชสํานักของดาวิดว่า “ซีเรียเป็นพันธมิตรกับเอฟราอิมแล้ว” พระทัยของพระองค์และจิตใจของประชาชนของพระองค์ก็สั่นเหมือนต้นไม้ในป่าสั่นอยู่หน้าลม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 3, 'และพระเยโฮวาห์ตรัสกับอิสยาห์ว่า “จงออกไปพบอาหัส ทั้งเจ้าและเชอารยาชูบบุตรชายของเจ้า ณ ที่ปลายท่อน้ําสระบนที่ถนนลานซักฟอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 4, 'และจงกล่าวแก่เขาว่า ‘จงระวังและสงบใจ อย่ากลัว อย่าให้พระทัยของพระองค์ขลาดด้วยเหตุเศษดุ้นฟืนที่จวนมอดทั้งสองนี้ เพราะความกริ้วอันร้ายแรงของเรซีน และซีเรีย และโอรสของเรมาลิยาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 5, 'เพราะว่าซีเรียพร้อมกับเอฟราอิมและโอรสของเรมาลิยาห์ได้คิดการชั่วร้ายต่อพระองค์ กล่าวว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 6, '“ให้เราทั้งหลายขึ้นไปต่อสู้กับยูดาห์และทําให้มันคร้ามกลัว และให้เราทะลวงเอาเมืองของเขาเพื่อเราเอง และตั้งบุตรของทาเบเอลให้เป็นกษัตริย์ท่ามกลางเมืองนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 7, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า มันจะไม่เป็นไป และจะไม่เกิดขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 8, 'เพราะเศียรของซีเรียคือดามัสกัส และเศียรของดามัสกัสคือเรซีน ภายในหกสิบห้าปีเอฟราอิมจะแตกเป็นชิ้นๆ กระทั่งไม่เป็นชนชาติอีกแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 9, 'และเศียรของเอฟราอิมคือสะมาเรีย และเศียรของสะมาเรียคือโอรสของเรมาลิยาห์ ถ้าเจ้าจะไม่มั่นใจ แน่ละ ก็จะตั้งมั่นเจ้าไว้ไม่ได้’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 10, 'พระเยโฮวาห์ตรัสกับอาหัสอีกว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 11, '“จงขอหมายสําคัญจากพระเยโฮวาห์พระเจ้าของเจ้า จงขอในที่ลึกหรือที่สูงเบื้องบนก็ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 12, 'แต่อาหัสตอบว่า “เราจะไม่ทูลขอ และเราจะไม่ทดลองพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 13, 'และท่านกล่าวว่า “โอ ข้าแต่ข้าราชสํานักของดาวิด ขอจงฟัง การที่จะให้มนุษย์อ่อนใจนั้นเล็กน้อยอยู่หรือ และท่านยังให้พระเจ้าของข้าพเจ้าอ่อนพระทัยด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 14, 'เพราะฉะนั้นองค์พระผู้เป็นเจ้าจะประทานหมายสําคัญเอง ดูเถิด หญิงพรหมจารีคนหนึ่งจะตั้งครรภ์ และคลอดบุตรชายคนหนึ่ง และเขาจะเรียกนามของท่านว่า อิมมานูเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 15, 'ท่านจะรับประทานเนยข้นและน้ําผึ้ง เพื่อท่านจะรู้ที่จะปฏิเสธความชั่วและเลือกความดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 16, 'เพราะก่อนที่เด็กนั้นจะรู้ที่จะปฏิเสธความชั่วและเลือกความดีนั้น แผ่นดินซึ่งท่านเกลียดชังนั้น มันจะขาดกษัตริย์ทั้งสององค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 17, 'พระเยโฮวาห์จะทรงนําวันนั้นมาเหนือพระองค์ เหนือชนชาติของพระองค์และเหนือวงศ์วานแห่งบิดาของพระองค์ คือวันอย่างที่ไม่เคยพบเห็น ตั้งแต่วันที่เอฟราอิมได้พรากจากยูดาห์ คือกษัตริย์ของอัสซีเรีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 18, 'ต่อมาในวันนั้นพระเยโฮวาห์จะทรงผิวพระโอษฐ์เรียกเหลือบซึ่งอยู่ทางต้นกําเนิดแม่น้ําแห่งอียิปต์ และเรียกผึ้งซึ่งอยู่ในแผ่นดินอัสซีเรีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 19, 'และมันจะมากันและทั้งหมดก็จะหยุดพักตามหุบเขาที่ร้าง และในซอกหิน และบนต้นหนามทั้งสิ้น และบนพุ่มไม้ทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 20, 'ในวันนั้นองค์พระผู้เป็นเจ้าจะทรงโกนทั้งศีรษะและขนที่เท้าเสียด้วยมีดโกนซึ่งเช่ามาจากฟากแม่น้ําข้างโน้น คือโดยกษัตริย์แห่งอัสซีเรียนั้นเอง และจะผลาญเคราด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 21, 'ต่อมาในวันนั้นชายคนหนึ่งจะเลี้ยงแม่วัวสาวไว้ตัวหนึ่งและแกะสองตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 22, 'และต่อมาเพราะมันให้นมมากมาย เขาจะรับประทานเนยข้น เพราะว่าทุกคนที่เหลืออยู่ในแผ่นดินจะรับประทานเนยข้นและน้ําผึ้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 23, 'ต่อมาในวันนั้นทุกแห่งที่เคยมีเถาองุ่นหนึ่งพันเถา มีค่าเงินหนึ่งพันเชเขล ก็จะกลายเป็นต้นหนามย่อยและหนามใหญ่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 24, 'คนจะมาที่นั่นพร้อมกับคันธนูและลูกธนู เพราะว่าแผ่นดินทั้งสิ้นนั้นจะกลายเป็นที่หนามย่อยและหนามใหญ่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 25, 'ส่วนเนินเขาทั้งสิ้นที่เขาเคยขุดด้วยจอบ การกลัวหนามย่อยและหนามใหญ่จะไม่มาที่นั่น แต่เนินเขาเหล่านั้นจะกลายเป็นที่ซึ่งเขาปล่อยฝูงวัวและที่ซึ่งฝูงแกะจะเหยียบย่ํา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 1, 'แล้วพระเยโฮวาห์ตรัสกับข้าพเจ้าอีกว่า “จงเอาแผ่นจารึกใหญ่มาแผ่นหนึ่ง และจงเขียนด้วยปากกาของมนุษย์เรื่อง ‘มาเฮอร์ชาลาลหัชบัส’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 2, 'และข้าพเจ้าได้พยานที่เชื่อถือได้ คือ อุรีอาห์ปุโรหิต และเศคาริยาห์บุตรชายของเยเบเรคียาห์ให้บันทึกไว้เพื่อข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 3, 'และข้าพเจ้าได้เข้าไปหาหญิงผู้พยากรณ์ และเธอก็ตั้งครรภ์และคลอดบุตรชายคนหนึ่ง และพระเยโฮวาห์ตรัสกับข้าพเจ้าว่า “จงเรียกชื่อบุตรนั้นว่า มาเฮอร์ชาลาลหัชบัส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 4, 'เพราะก่อนที่เด็กจะรู้ที่จะร้องเรียก ‘พ่อ แม่’ ได้ ทรัพย์สมบัติของดามัสกัสและของที่ริบได้จากสะมาเรีย จะถูกขนเอาไปต่อพระพักตร์กษัตริย์อัสซีเรีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 5, 'แล้วพระเยโฮวาห์ตรัสกับข้าพเจ้าอีกว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 6, '“เพราะว่าชนชาตินี้ได้ปฏิเสธน้ําแห่งชิโลอาห์ซึ่งไหลเอื่อยๆ และปีติยินดีต่อเรซีนและโอรสของเรมาลิยาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 7, 'เพราะฉะนั้นบัดนี้ ดูเถิด องค์พระผู้เป็นเจ้าทรงนําน้ําแห่งแม่น้ํามาสู้เขาทั้งหลาย ที่มีกําลังและมากหลาย คือกษัตริย์แห่งอัสซีเรียและสง่าราศีทั้งสิ้นของพระองค์ และน้ํานั้นจะไหลล้นห้วยทั้งสิ้นของมัน และท่วมฝั่งทั้งสิ้นของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 8, 'และจะกวาดต่อไปเข้าในยูดาห์ และจะไหลท่วมและผ่านไปแม้จนถึงคอ และปีกอันแผ่กว้างของมันจะเต็มแผ่นดินของท่านนะ โอ ท่านอิมมานูเอล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 9, 'โอ ชนชาติทั้งหลายเอ๋ย จงเข้าร่วมกัน และเจ้าจะถูกทําให้แหลกเป็นชิ้นๆ บรรดาประเทศไกลๆทั้งหมด เจ้าเอ๋ยจงเงี่ยหู จงคาดเอวเจ้าไว้และเจ้าจะถูกทําให้แหลกเป็นชิ้นๆ จงคาดเอวเจ้าไว้และเจ้าจะถูกทําให้แหลกเป็นชิ้นๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 10, 'จงปรึกษากันเถิด แต่ก็จะไร้ผล จงพูดกันเถิด แต่ก็จะไม่สําเร็จผล เพราะว่าพระเจ้าทรงสถิตกับเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 11, 'เพราะว่าพระเยโฮวาห์ตรัสดังต่อไปนี้กับข้าพเจ้าพร้อมด้วยพระหัตถ์อันเข้มแข็ง และทรงสั่งสอนข้าพเจ้ามิให้ดําเนินในทางของชนชาตินี้ พระองค์ตรัสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 12, '“สิ่งที่ชนชาตินี้เรียกว่า การร่วมคิดกบฏ เจ้าอย่าเรียกว่า การร่วมคิดกบฏ เสียหมด อย่ากลัวสิ่งที่เขากลัว หรืออย่าครั่นคร้าม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 13, 'แต่พระเยโฮวาห์จอมโยธานั้นแหละ เจ้าต้องว่าพระองค์บริสุทธิ์ จงให้พระองค์ทรงเป็นผู้ที่เจ้ายําเกรง จงให้พระองค์ทรงเป็นผู้ที่เจ้าครั่นคร้าม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 14, 'แล้วพระองค์จะเป็นสถานบริสุทธิ์ แต่เป็นศิลาที่ทําให้สะดุด และเป็นก้อนหินที่ทําให้ขุ่นเคืองใจของวงศ์วานทั้งคู่ของอิสราเอล เป็นกับและเป็นบ่วงดักชาวเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 15, 'และคนเป็นอันมากในพวกเขาจะสะดุดหินนั้น เขาทั้งหลายจะล้มลงและแตกหัก เขาจะติดบ่วงและถูกจับไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 16, 'จงมัดถ้อยคําพยานเก็บไว้เสีย และจงตีตราพระราชบัญญัติไว้ในหมู่พวกสาวกของข้าพเจ้าเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 17, 'ข้าพเจ้าจะรอคอยพระเยโฮวาห์ ผู้ทรงซ่อนพระพักตร์ของพระองค์จากวงศ์วานของยาโคบ และข้าพเจ้าจะคอยท่าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 18, 'ดูเถิด ข้าพเจ้าและบุตรผู้ซึ่งพระเยโฮวาห์ทรงประทานแก่ข้าพเจ้า เป็นหมายสําคัญและเป็นการมหัศจรรย์ต่างๆในอิสราเอล จากพระเยโฮวาห์จอมโยธา ผู้ทรงประทับบนภูเขาศิโยน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 19, 'และเมื่อเขาทั้งหลายจะกล่าวแก่พวกท่านว่า “จงปรึกษากับคนทรงและพ่อมดแม่มดผู้ร้องเสียงจ๊อกแจ๊กและเสียงพึมพํา” ไม่ควรที่ประชาชนจะปรึกษากับพระเจ้าของเขาหรือ ควรเขาจะไปปรึกษาคนตายเพื่อคนเป็นหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 20, 'ไปค้นพระราชบัญญัติและถ้อยคําพยาน ถ้าเขาไม่พูดตามคําเหล่านี้ก็เพราะในตัวเขาไม่มีแสงสว่างเสียเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 21, 'เขาทั้งหลายจะผ่านแผ่นดินไปด้วยความระทมใจอันยิ่งใหญ่และด้วยความหิว และต่อมาเมื่อเขาหิว เขาจะเกรี้ยวกราดและแช่งด่ากษัตริย์ของเขาและพระเจ้าของเขา และจะแหงนหน้าขึ้นข้างบน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 22, 'และจะมองดูที่แผ่นดินโลก และจะมองเห็นความทุกข์ใจและความมืด ความกลุ้มแห่งความแสนระทม และเขาจะถูกผลักไสเข้าไปในความมืดทึบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 1, 'แต่กระนั้นแผ่นดินนั้นซึ่งอยู่ในความแสนระทมจะไม่กลัดกลุ้ม ในกาลก่อนพระองค์ทรงนําแคว้นเศบูลุนและแคว้นนัฟทาลีมาสู่ความดูหมิ่น แต่ในกาลภายหลังพระองค์จะทรงกระทําให้หนทางข้างทะเล แคว้นฟากแม่น้ําจอร์แดนข้างโน้น คือ กาลิลีแห่งบรรดาประชาชาติ ให้เจ็บปวดทรมานอย่างมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 2, 'ชนชาติที่ดําเนินในความมืดได้เห็นความสว่างยิ่งใหญ่แล้ว บรรดาผู้ที่อาศัยอยู่ในแผ่นดินแห่งเงามัจจุราช ความสว่างได้ส่องมาบนเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 3, 'พระองค์ได้ทรงทวีประชาชาตินั้นขึ้น และมิได้ทรงเพิ่มความชื่นบานของเขา เขาทั้งหลายเปรมปรีดิ์ต่อพระพักตร์พระองค์ ดั่งความชื่นบานในฤดูเกี่ยวเก็บ ดุจดั่งคนเปรมปรีดิ์เมื่อเขาแบ่งของริบมานั้นแก่กัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 4, 'เพราะว่าแอกอันเป็นภาระของเขาก็ดี ไม้พลองที่ตีบ่าเขาก็ดี ไม้ตะบองของผู้บีบบังคับเขาก็ดี พระองค์จะทรงหักเสียอย่างในวันของคนมีเดียน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 5, 'เพราะการรบทั้งสิ้นของนักรบมีเสียงวุ่นวาย และเสื้อคลุมที่เกลือกอยู่ในโลหิต แต่การรบครั้งนี้จะถูกเผาเป็นเชื้อเพลิงใส่ไฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 6, 'ด้วยมีเด็กคนหนึ่งเกิดมาเพื่อเรา มีบุตรชายคนหนึ่งประทานมาให้เรา และการปกครองจะอยู่ที่บ่าของท่าน และท่านจะเรียกนามของท่านว่า “ผู้ที่มหัศจรรย์ ที่ปรึกษา พระเจ้าผู้ทรงมหิทธิฤทธิ์ พระบิดานิรันดร์ องค์สันติราช”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 7, 'เพื่อการปกครองของท่านจะเพิ่มพูนยิ่งขึ้น และสันติภาพจะไม่มีที่สิ้นสุดเหนือพระที่นั่งของดาวิด และเหนือราชอาณาจักรของพระองค์ ที่จะสถาปนาไว้ และเชิดชูไว้ด้วยความยุติธรรมและด้วยความเที่ยงธรรม ตั้งแต่บัดนี้เป็นต้นไปจนนิรันดร์กาล ความกระตือรือร้นของพระเยโฮวาห์จอมโยธาจะกระทําการนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 8, 'องค์พระผู้เป็นเจ้าทรงใช้พระวจนะไปต่อสู้ยาโคบ และจะตกอยู่เหนืออิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 9, 'และประชาชนทั้งสิ้นจะรู้เรื่อง คือเอฟราอิมและชาวสะมาเรีย ผู้กล่าวด้วยความเย่อหยิ่งและด้วยจิตใจจองหอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 10, 'ว่า “ก้อนอิฐพังลงแล้ว แต่เราจะสร้างด้วยศิลาสลัก ต้นมะเดื่อถูกโค่นลง แต่เราจะใส่ต้นสีดาร์เข้าแทนไว้ในที่นั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 11, 'พระเยโฮวาห์จึงทรงหนุนปฏิปักษ์ของเรซีนมาสู้เขา และทรงกระตุ้นศัตรูของเขาให้ร่วมกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 12, 'คือคนซีเรียทางข้างหน้าและคนฟีลิสเตียทางข้างหลัง และเขาจะอ้าปากออกกลืนอิสราเอลเสีย ถึงกระนั้นก็ดีพระพิโรธของพระองค์ก็ยังมิได้หันกลับ และพระหัตถ์ของพระองค์ยังเหยียดออกอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 13, 'เพราะประชาชนมิได้หันมาหาพระองค์ผู้ทรงตีเขา มิได้แสวงหาพระเยโฮวาห์จอมโยธา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 14, 'พระเยโฮวาห์จึงจะทรงตัดหัวตัดหางออกเสียจากอิสราเอล ทั้งกิ่งก้านและต้นกกในวันเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 15, 'ผู้ใหญ่และคนมีเกียรติคือหัว และผู้พยากรณ์ผู้สอนเท็จเป็นหาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 16, 'เพราะบรรดาผู้ที่นําชนชาตินี้ได้นําเขาให้หลง และบรรดาผู้ที่เขานําก็ถูกทําลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 17, 'ฉะนั้นองค์พระผู้เป็นเจ้าจะหาทรงเปรมปรีดิ์ในคนหนุ่มของเขาไม่ และจะมิได้ทรงมีพระกรุณาต่อคนกําพร้าพ่อหรือแม่ม่ายของเขา เพราะว่าทุกคนเป็นคนหน้าซื่อใจคดและเป็นคนทําความชั่วและปากทุกปากก็กล่าวคําโฉดเขลา ถึงกระนั้นก็ดีพระพิโรธของพระองค์ก็ยังมิได้หันกลับ และพระหัตถ์ของพระองค์ยังเหยียดออกอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 18, 'เพราะความชั่วก็ไหม้เหมือนไฟไหม้ มันจะผลาญทั้งหนามย่อยและหนามใหญ่ มันจะจุดไฟเข้าที่ป่าทึบ และป่าทึบก็จะม้วนขึ้นข้างบนเหมือนควันเป็นลูกๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 19, 'แผ่นดินนั้นก็มืดไปโดยเหตุพระพิโรธของพระเยโฮวาห์จอมโยธา ประชาชนก็จะเหมือนเชื้อเพลิง ไม่มีคนใดจะไว้ชีวิตพี่น้องของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 20, 'เขาจะฉวยได้ทางขวา แต่ยังหิวอยู่ เขาจะกินทางซ้าย แต่ก็ยังไม่อิ่ม ต่างก็จะกินเนื้อแขนของตนเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 21, 'มนัสเสห์กินเอฟราอิม เอฟราอิมกินมนัสเสห์ และทั้งคู่ก็สู้กับยูดาห์ ถึงกระนั้นก็ดีพระพิโรธของพระองค์ก็ยังมิได้หันกลับ และพระหัตถ์ของพระองค์ยังเหยียดออกอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 1, 'วิบัติแก่คนเหล่านั้นที่ออกกฎหมายอธรรม และแก่ผู้เขียนที่เขียนแต่การบีบคั้นเรื่อยไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 2, 'เพื่อหันคนขัดสนไปจากความยุติธรรม และปล้นสิทธิของคนจนแห่งชนชาติของเราเสีย เพื่อว่าหญิงม่ายจะเป็นเหยื่อของเขา และเพื่อเขาจะปล้นคนกําพร้าพ่อเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 3, 'พวกเจ้าจะกระทําอย่างไรในวันแห่งการลงอาญา และในการกวาดล้างซึ่งจะมาจากที่ไกล เจ้าจะหนีไปพึ่งใคร และเจ้าจะฝากสง่าราศีของเจ้าไว้ที่ไหน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 4, 'ปราศจากเราพวกเขาจะกราบลงอยู่กับนักโทษ เขาจะล้มลงในหมู่พวกคนที่ถูกฆ่า ถึงกระนั้นก็ดีพระพิโรธของพระองค์ก็ยังมิได้หันกลับ และพระหัตถ์ของพระองค์ยังเหยียดออกอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 5, 'โอ ชาวอัสซีเรียเอ๋ย ผู้เป็นตะบองแห่งความกริ้วของเรา และไม้พลองในมือของเขาคือความเกรี้ยวกราดของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 6, 'เราจะใช้เขาไปสู้ประชาชาติอันหน้าซื่อใจคด เราจะบัญชาเขาให้ไปสู้ชนชาติที่เรากริ้ว ไปเอาของริบและฉวยเหยื่อและให้เหยียบย่ําลงเหมือนเหยียบเลนในถนน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 7, 'แต่เขามิได้ตั้งใจอย่างนั้น และจิตใจของเขาก็มิได้คิดอย่างนั้น แต่ในใจของเขาคิดจะทําลาย และตัดประชาชาติเสียมิใช่น้อย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 8, 'เพราะเขาพูดว่า “ผู้บังคับบัญชาของข้าเป็นกษัตริย์หมดมิใช่หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 9, 'เมืองคาลโนก็เหมือนเมืองคารเคมิชมิใช่หรือ เมืองฮามัทก็เหมือนเมืองอารปัดมิใช่หรือ เมืองสะมาเรียก็เหมือนเมืองดามัสกัสมิใช่หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 10, 'เหมือนอย่างมือของเราไปถึงบรรดาราชอาณาจักรของรูปเคารพ ซึ่งรูปเคารพแกะสลักของเขานั้นใหญ่กว่าของเยรูซาเล็มและสะมาเรีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 11, 'เราก็จะไม่ทําแก่เยรูซาเล็มกับรูปเคารพของเขาดอกหรือ ดังที่เราได้ทําแก่สะมาเรียและรูปเคารพของเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 12, 'ต่อมาเมื่อองค์พระผู้เป็นเจ้าทรงสําเร็จพระราชกิจทั้งสิ้นของพระองค์ที่ภูเขาศิโยนและที่เยรูซาเล็มแล้ว เราจะลงทัณฑ์แก่ผลแห่งจิตใจจองหองของกษัตริย์แห่งอัสซีเรีย และเกียรติยศแห่งตาที่หยิ่งยโสของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 13, 'เพราะเขาว่า “ข้าได้กระทําการนี้ด้วยกําลังมือของข้า และด้วยสติปัญญาของข้า เพราะข้ามีความเข้าใจ ข้าได้รื้อเขตแดนของชนชาติทั้งหลาย และได้ปล้นทรัพย์สมบัติของเขา ข้าได้โยนบรรดาชาวเมืองลงมาอย่างคนกล้าหาญ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 14, 'มือของข้าได้ฉวยทรัพย์สมบัติของชนชาติทั้งหลายเหมือนฉวยรังนก และอย่างคนเก็บไข่ซึ่งละทิ้งไว้ ข้าก็รวบรวมแผ่นดินโลกทั้งสิ้นดังนั้นแหละ และไม่มีผู้ใดขยับปีกมาปก หรืออ้าปากหรือร้องเสียงจ๊อกแจ๊ก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 15, 'ขวานจะคุยข่มคนที่ใช้มันสกัดนั้นหรือ หรือเลื่อยจะทะนงตัวเหนือผู้ที่ใช้มันเลื่อยนั้นหรือ เหมือนกับว่าตะบองจะยกผู้ซึ่งถือมันขึ้นตี หรืออย่างไม้พลองจะยกตัวขึ้นเหมือนกับว่ามันไม่ทําด้วยไม้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 16, 'ฉะนั้น องค์พระผู้เป็นเจ้า องค์พระผู้เป็นเจ้าจอมโยธาจะทรงให้โรคผอมแห้งมาในหมู่พวกคนอ้วนพีของเขา ภายใต้เกียรติของเขาจะมีการไหม้ใหญ่โตเหมือนอย่างไฟไหม้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 17, 'ความสว่างแห่งอิสราเอลจะเป็นไฟ และองค์บริสุทธิ์ของท่านจะกลายเป็นเปลวเพลิง และจะเผาและกินหนามใหญ่และหนามย่อยของเขาเสียในวันเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 18, 'พระองค์จะทรงผลาญสง่าราศีแห่งป่าของเขาและแห่งสวนผลไม้ของเขา ทั้งจิตวิญญาณและร่างกาย และจะเป็นเหมือนเวลาผู้ถือธงอ่อนเปลี้ยลงไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 19, 'ต้นไม้แห่งป่าของเขาจะเหลือน้อยเต็มที จนเด็กๆจะเขียนลงได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 20, 'ต่อมาในวันนั้น คนอิสราเอลที่เหลืออยู่ และคนที่รอดหนีไปแห่งวงศ์วานของยาโคบ จะไม่พิงผู้ที่ตีเขาอีก แต่จะพักพิงที่พระเยโฮวาห์ องค์บริสุทธิ์แห่งอิสราเอล โดยความจริง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 21, 'ส่วนคนที่เหลืออยู่จะกลับมายังพระเจ้าผู้ทรงมหิทธิฤทธิ์ คือคนที่เหลืออยู่ของยาโคบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 22, 'อิสราเอลเอ๋ย เพราะแม้ว่าชนชาติของเจ้าจะเป็นดั่งเม็ดทรายในทะเล คนที่เหลืออยู่จะกลับมา การเผาผลาญซึ่งกําหนดไว้แล้วจะเปี่ยมล้นไปด้วยความชอบธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 23, 'เพราะว่าองค์พระผู้เป็นเจ้า พระเจ้าจอมโยธาจะทรงกระทําให้การเผาผลาญนั้นสิ้นสุดลงตามที่กําหนดไว้แล้วในท่ามกลางแผ่นดินทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 24, 'ฉะนั้น องค์พระผู้เป็นเจ้า พระเจ้าจอมโยธาตรัสดังนี้ว่า “โอ ชนชาติของเราเอ๋ย ผู้อยู่ในศิโยน อย่ากลัวคนอัสซีเรีย เขาจะตีเจ้าด้วยตะบองและจะยกไม้พลองของเขาขึ้นสู้เจ้าอย่างที่ในอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 25, 'เพราะอีกสักหน่อยเท่านั้น แล้วความกริ้วนั้นจะสิ้นสุด และความโกรธของเราจะมุ่งตรงที่การทําลายเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 26, 'และพระเยโฮวาห์จอมโยธาจะทรงเหวี่ยงแส้มาสู้เขา ดังที่พระองค์ทรงโจมตีคนมีเดียน ณ ศิลาโอเรบ และไม้พลองของพระองค์ที่เคยอยู่เหนือทะเล พระองค์จะทรงยกขึ้นอย่างที่ในอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 27, 'และต่อมาในวันนั้นภาระของเขาจะพรากไปจากบ่าของเจ้า และแอกของเขาจะถูกทําลายเสียจากคอของเจ้า และแอกนั้นจะถูกทําลายเพราะเหตุการเจิม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 28, 'เขาได้มาถึงอัยยาทแล้ว เขาได้ข้ามมิโกรน เขาเก็บสัมภาระของเขาไว้ที่มิคมาช');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 29, 'เขาเหล่านั้นผ่านช่องหว่างเขามาแล้ว เกบาเป็นที่เขาค้างคืน รามาห์สะทกสะท้าน กิเบอาห์ของซาอูลหนีไปแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 30, 'โอ ธิดาของกัลลิมเอ๋ย ส่งเสียงร้องซี ให้เขายินได้ในลาอิชเถิด โอ อานาโธทเอ๋ย น่าสงสารจริง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 31, 'มัดเมนาห์กําลังหนีอยู่ คนเกบิมหนีให้พ้นภัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 32, 'ในวันนั้นเอง เขาจะยับยั้งอยู่ที่เมืองโนบ เขาจะส่ายมือของเขาต่อต้านภูเขาแห่งธิดาของศิโยน เนินเขาของเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 33, 'ดูเถิด องค์พระผู้เป็นเจ้า พระเยโฮวาห์จอมโยธา จะทรงตัดกิ่งไม้ด้วยกําลังอันน่าคร้ามกลัว ต้นที่สูงยิ่งจะถูกโค่นลงมา และต้นที่สูงจะต้องต่ําลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 34, 'พระองค์จะทรงใช้ขวานเหล็กฟันป่าทึบ และเลบานอนจะล้มลงโดยคนมีอํานาจใหญ่โต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 1, 'จะมีหน่อแตกออกมาจากตอแห่งเจสซี จะมีกิ่งงอกออกมาจากรากทั้งหลายของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 2, 'และพระวิญญาณของพระเยโฮวาห์จะอยู่บนท่านนั้น คือวิญญาณแห่งปัญญาและความเข้าใจ วิญญาณแห่งการวินิจฉัยและอานุภาพ วิญญาณแห่งความรู้และความยําเกรงพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 3, 'ความพึงใจของท่านก็ในความยําเกรงพระเยโฮวาห์ ท่านจะไม่พิพากษาตามซึ่งตาท่านเห็น หรือตัดสินตามซึ่งหูท่านได้ยิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 4, 'แต่ท่านจะพิพากษาคนจนด้วยความชอบธรรม และตัดสินเผื่อผู้มีใจถ่อมแห่งแผ่นดินโลกด้วยความเที่ยงตรง ท่านจะตีโลกด้วยตะบองแห่งปากของท่าน และท่านจะประหารคนชั่วด้วยลมแห่งริมฝีปากของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 5, 'ความชอบธรรมจะเป็นผ้าคาดเอวของท่าน และความสัตย์สุจริตจะเป็นผ้าคาดบั้นเอวของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 6, 'สุนัขป่าจะอยู่กับลูกแกะ และเสือดาวจะนอนอยู่กับลูกแพะ ลูกวัวกับสิงโตหนุ่มกับสัตว์อ้วนพีจะอยู่ด้วยกัน และเด็กเล็กๆจะนํามันไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 7, 'แม่วัวกับหมีจะกินด้วยกัน ลูกของมันก็จะนอนอยู่ด้วยกัน และสิงโตจะกินฟางเหมือนวัวผู้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 8, 'และทารกกินนมจะเล่นอยู่ที่ปากรูงูเห่า และเด็กที่หย่านมจะเอามือวางบนรังของงูทับทาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 9, 'สัตว์เหล่านั้นจะไม่ทําให้เจ็บหรือจะทําลายทั่วภูเขาอันบริสุทธิ์ของเรา เพราะว่าแผ่นดินโลกจะเต็มไปด้วยความรู้เรื่องของพระเยโฮวาห์ ดั่งน้ําปกคลุมทะเลอยู่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 10, 'ในวันนั้น รากแห่งเจสซี ซึ่งตั้งขึ้นเป็นธงแก่ชนชาติทั้งหลายจะเป็นที่แสวงหาของบรรดาประชาชาติ และที่พํานักของท่านจะรุ่งโรจน์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 11, 'อยู่มาในวันนั้น องค์พระผู้เป็นเจ้าจะทรงยื่นพระหัตถ์ของพระองค์ออกไปเป็นครั้งที่สอง เพื่อจะได้ส่วนชนชาติของพระองค์ที่เหลืออยู่คืนมา เป็นคนเหลือจากอัสซีเรีย จากอียิปต์ จากปัทโรส จากคูช จากเอลาม จากชินาร์ จากฮามัท และจากเกาะต่างๆแห่งทะเล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 12, 'พระองค์จะทรงยกอาณัติสัญญาณนั้นขึ้นให้แก่บรรดาประชาชาติ และจะชุมนุมอิสราเอลที่พลัดพราก และรวบรวมยูดาห์ที่กระจัดกระจายจากสี่มุมแห่งแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 13, 'ความอิจฉาของเอฟราอิมจะพรากไปด้วย และบรรดาคู่อริของยูดาห์จะถูกตัดออกไป เอฟราอิมจะไม่อิจฉายูดาห์ และยูดาห์จะไม่รบกวนเอฟราอิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 14, 'แต่เขาทั้งหลายจะโฉบลงเหนือไหล่เขาของคนฟีลิสเตียทางตะวันตก และเขาจะร่วมกันปล้นประชาชนทางตะวันออก เขาจะยื่นมือออกต่อสู้เอโดมและโมอับ และคนอัมโมนจะเชื่อฟังเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 15, 'และพระเยโฮวาห์จะทรงทําลายลิ้นของทะเลแห่งอียิปต์อย่างสิ้นเชิง และจะทรงโบกพระหัตถ์เหนือแม่น้ํานั้น ด้วยลมอันแรงกล้าของพระองค์ และจะตีมันให้แตกเป็นธารน้ําเจ็ดสาย และให้คนเดินข้ามไปได้โดยที่เท้าไม่เปียกน้ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 16, 'และจะมีถนนหลวงจากอัสซีเรียสําหรับคนที่เหลืออยู่จากชนชาติของพระองค์ ดั่งที่มีอยู่สําหรับอิสราเอลในวันที่เขาขึ้นมาจากแผ่นดินอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 1, 'ในวันนั้น ท่านจะกล่าวว่า “โอ ข้าแต่พระเยโฮวาห์ ข้าพระองค์จะสรรเสริญพระองค์ เพราะแม้พระองค์ทรงพระพิโรธต่อข้าพระองค์ ความกริ้วของพระองค์ก็หันกลับไป และพระองค์ทรงเล้าโลมข้าพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 2, 'ดูเถิด พระเจ้าทรงเป็นความรอดของข้าพเจ้า ข้าพเจ้าจะวางใจและไม่กลัว เพราะพระเยโฮวาห์ คือพระเยโฮวาห์ทรงเป็นกําลังและบทเพลงของข้าพเจ้า และพระองค์ทรงเป็นความรอดของข้าพเจ้าแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 3, 'เจ้าจะโพงน้ําด้วยความชื่นบานจากบ่อแห่งความรอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 4, 'และในวันนั้นเจ้าจะกล่าวว่า “จงสรรเสริญพระเยโฮวาห์ จงร้องทูลออกพระนามของพระองค์ จงประกาศบรรดาพระราชกิจของพระองค์ท่ามกลางชนชาติทั้งหลาย จงป่าวร้องว่าพระนามของพระองค์เป็นที่เชิดชู”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 5, 'จงร้องเพลงสรรเสริญพระเยโฮวาห์ เพราะพระองค์ทรงกระทํากิจอันดีเลิศ ให้เรื่องนี้รู้กันทั่วไปในแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 6, 'ชาวศิโยนเอ๋ย จงโห่ร้องและร้องเสียงดัง เพราะองค์บริสุทธิ์แห่งอิสราเอลนั้นก็ใหญ่ยิ่งอยู่ในหมู่พวกเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 1, 'ภาระเกี่ยวกับบาบิโลน ตามซึ่งอิสยาห์บุตรชายของอามอสได้เห็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 2, 'จงชูธงสัญญาณขึ้นบนภูเขาสูง จงเปล่งเสียงร้องเรียกเขาทั้งหลาย จงโบกมือให้เขาเข้าไปในประตูเมืองของขุนนาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 3, 'ตัวเราเองได้บัญชาแก่ผู้ที่เราชําระให้บริสุทธิ์แล้ว เราได้เรียกชายฉกรรจ์ของเราให้จัดการตามความโกรธของเรา คือผู้ที่ยินดีในความสูงส่งของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 4, 'เสียงอึงอลบนภูเขาดั่งเสียงมวลชนมหึมา เสียงอึงคะนึงของราชอาณาจักรทั้งหลายของบรรดาประชาชาติที่รวมเข้าด้วยกัน พระเยโฮวาห์จอมโยธากําลังระดมพลเพื่อสงคราม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 5, 'เขาทั้งหลายมาจากแผ่นดินอันไกล จากสุดปลายฟ้าสวรรค์ พระเยโฮวาห์และอาวุธแห่งพระพิโรธของพระองค์ เพื่อจะทําลายแผ่นดินทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 6, 'จงพิลาปร่ําไห้ซิ เพราะวันแห่งพระเยโฮวาห์มาใกล้แล้ว วันนั้นจะมา เป็นการทําลายจากองค์ผู้ทรงมหิทธิฤทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 7, 'เพราะฉะนั้น ทุกๆมือก็จะอ่อนเปลี้ย และจิตใจของทุกคนก็จะละลายไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 8, 'และเขาทั้งหลายจะตกใจกลัว ความเจ็บและความปวดจะเกาะเขา เขาจะทุรนทุรายดั่งหญิงกําลังคลอดบุตร เขาจะมองตากันอย่างตกตะลึง หน้าของเขาแดงเป็นแสงไฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 9, 'ดูเถิด วันแห่งพระเยโฮวาห์จะมา โหดร้ายด้วยพระพิโรธและความโกรธอันเกรี้ยวกราด ที่จะกระทําให้แผ่นดินเป็นที่รกร้าง และพระองค์จะทรงทําลายคนบาปของแผ่นดินเสียจากแผ่นดินนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 10, 'เพราะดวงดาวแห่งฟ้าสวรรค์ และหมู่ดาวในนั้น จะไม่ทอแสงของมัน ดวงอาทิตย์ก็จะมืดเมื่อเวลาขึ้น และดวงจันทร์จะไม่ส่องแสงของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 11, 'เราจะลงโทษโลกเพราะความชั่วร้าย และคนชั่วเพราะความชั่วช้าของเขา เราจะกระทําให้ความเย่อหยิ่งของคนจองหองสิ้นสุด และปราบความยโสของคนโหดร้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 12, 'เราจะกระทําให้คนมีค่ามากกว่าทองคําเนื้อดี และมนุษย์มีค่ามากกว่าทองคําแห่งโอฟีร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 13, 'เพราะฉะนั้น เราจะกระทําให้ฟ้าสวรรค์สั่นสะเทือน และแผ่นดินโลกจะสะท้านพลัดจากที่ของมัน โดยพระพิโรธของพระเยโฮวาห์จอมโยธา ในวันแห่งความโกรธอันเกรี้ยวกราดของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 14, 'คนทุกคนจะหันเข้าสู่ชนชาติของตนเอง และคนทุกคนจะหนีไปยังแผ่นดินของตนเอง ดั่งละมั่งที่ถูกล่าหรือเหมือนแกะที่ไม่มีผู้รวมฝูง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 15, 'ทุกคนที่เขาพบเข้าก็จะถูกแทงทะลุ และทุกคนที่รวมเข้าด้วยกันกับพวกเขาก็จะล้มลงด้วยดาบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 16, 'เด็กเล็กๆของเขาจะถูกฟาดลงเป็นชิ้นๆต่อหน้าต่อตาเขา เรือนของเขาจะถูกปล้นและภรรยาของเขาจะถูกขืนใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 17, 'ดูเถิด เราจะรบเร้าให้ชาวมีเดียมาสู้เขา ผู้ซึ่งไม่เอาใจใส่ในเรื่องเงิน และไม่ไยดีในเรื่องทองคํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 18, 'คันธนูของเขาจะฟาดชายหนุ่มลงเป็นชิ้นๆ เขาจะไม่ปรานีต่อผู้บังเกิดจากครรภ์ นัยน์ตาของเขาจะไม่สงสารเด็ก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 19, 'และบาบิโลน ซึ่งโอ่อ่าในบรรดาราชอาณาจักร เมืองที่สง่าและเป็นที่ภูมิใจของชาวเคลเดีย จะเป็นดังเมืองโสโดมและเมืองโกโมราห์ เมื่อพระเจ้าทรงคว่ํามันเสียนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 20, 'จะไม่มีใครเข้าอยู่ในบาบิโลน หรืออาศัยอยู่ตลอดทุกชั่วอายุ คนอาระเบียจะไม่กางเต็นท์ของเขาที่นั่น ไม่มีผู้เลี้ยงแกะที่จะให้แกะของเขานอนลงที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 21, 'แต่สัตว์ป่าจะนอนลงที่นั่น และบ้านเรือนในนั้นจะเต็มไปด้วยนกทึดทือ นกเค้าแมวจะอาศัยที่นั่น เมษปีศาจจะเต้นรําอยู่ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 22, 'หมาจิ้งจอกจะเห่าหอนอยู่ในที่อาศัยอันรกร้าง และมังกรจะร้องอยู่ในวังแสนสุขของมัน เวลาของเมืองนั้นก็ใกล้เข้ามาแล้ว และวันเวลาของมันจะไม่ยืดให้ยาวไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 1, 'เพราะพระเยโฮวาห์จะทรงมีพระเมตตาต่อยาโคบ และจะทรงเลือกอิสราเอลอีก และจะทรงตั้งเขาทั้งหลายไว้ในแผ่นดินของเขาเอง คนต่างด้าวจะสมทบกับเขา และติดสนิทอยู่กับวงศ์วานของยาโคบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 2, 'และชนชาติทั้งหลายจะรับเขาและนําเขาทั้งหลายมายังที่ของเขา และวงศ์วานของอิสราเอลจะมีกรรมสิทธิ์ในเขา เป็นทาสชายหญิงในแผ่นดินของพระเยโฮวาห์ ผู้ที่จับเขาเป็นเชลยจะถูกเขาจับเป็นเชลย และจะปกครองผู้ที่เคยบีบบังคับเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 3, 'และต่อมาในวันที่พระเยโฮวาห์จะทรงประทานให้เจ้าได้หยุดพักจากความเศร้าโศกของเจ้า และจากความกลัว และจากงานหนักซึ่งเจ้าถูกบังคับให้กระทํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 4, 'เจ้าจะยกคําภาษิตนี้กล่าวต่อกษัตริย์แห่งบาบิโลนว่า “เออ ผู้บีบบังคับก็สงบไปแล้วหนอ เมืองทองคําก็สงบไปด้วยซิ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 5, 'พระเยโฮวาห์ทรงหักไม้พลองของคนชั่ว คทาของผู้ครอบครอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 6, 'ผู้ซึ่งตีชนชาติทั้งหลายด้วยความพิโรธ ด้วยการตีอย่างไม่หยุดยั้ง ผู้ซึ่งได้ครอบครองประชาชาติด้วยความโกรธ ได้ถูกข่มเหงโดยไม่มีผู้ใดยับยั้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 7, 'โลกทั้งสิ้นก็พักและสงบอยู่ เขาทั้งหลายร้องเพลงโพล่งออกมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 8, 'ต้นสนสามใบเปรมปรีดิ์เพราะเจ้า ต้นสนสีดาร์แห่งเลบานอนด้วย และกล่าวว่า ‘ตั้งแต่เจ้าตกต่ํา ก็ไม่มีผู้โค่นขึ้นมาต่อสู้เราแล้ว’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 9, 'นรกเบื้องล่างก็ตื่นเต้นเพื่อต้อนรับเจ้าเมื่อเจ้ามา มันปลุกให้ชาวแดนคนตายมาต้อนรับเจ้า คือบรรดาผู้ซึ่งเคยเป็นผู้นําของโลก มันทําให้บรรดาผู้ที่เคยเป็นกษัตริย์แห่งประชาชาติทั้งหลายลุกขึ้นมาจากพระที่นั่งของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 10, 'ทุกตนจะพูด และกล่าวแก่เจ้าว่า ‘เจ้าก็อ่อนเปลี้ยอย่างเราด้วยหรือ เจ้ากลายเป็นอย่างพวกเราหรือ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 11, 'ความโอ่อ่าของเจ้าถูกนําลงมาถึงแดนคนตาย และเสียงพิณใหญ่ของเจ้า ตัวหนอนจะเป็นที่นอนอยู่ใต้ตัวเจ้า และตัวหนอนจะเป็นผ้าห่มของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 12, 'โอ ลูซีเฟอร์เอ๋ย โอรสแห่งรุ่งอรุณ เจ้าร่วงลงมาจากฟ้าสวรรค์แล้วซิ เจ้าถูกตัดลงมายังพื้นดินอย่างไรหนอ เจ้าผู้กระทําให้บรรดาประชาชาติตกต่ําน่ะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 13, 'เจ้ารําพึงในใจของเจ้าว่า ‘ข้าจะขึ้นไปยังฟ้าสวรรค์ ข้าจะตั้งพระที่นั่งของข้า ณ เหนือดวงดาวทั้งหลายของพระเจ้า ข้าจะนั่งบนขุนเขาชุมนุมสถาน ณ ด้านทิศเหนือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 14, 'ข้าจะขึ้นไปเหนือความสูงของเมฆ ข้าจะกระทําตัวของข้าเหมือนองค์ผู้สูงสุด’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 15, 'แต่เจ้าจะถูกนําลงมาสู่นรก ยังที่ลึกของปากแดน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 16, 'บรรดาผู้ที่เห็นเจ้าจะเพ่งดูเจ้า และจะพิจารณาเจ้าว่า ‘ชายคนนี้หรือที่ทําให้โลกสั่นสะเทือน ผู้เขย่าราชอาณาจักรทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 17, 'ผู้ที่ได้กระทําให้โลกเป็นเหมือนถิ่นทุรกันดาร และคว่ําหัวเมืองของโลกเสีย ผู้ไม่ยอมให้เชลยกลับไปบ้านของเขา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 18, 'กษัตริย์ทั้งสิ้นของบรรดาประชาชาตินอนอยู่อย่างมีเกียรติ ต่างก็อยู่ในอุโมงค์ของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 19, 'แต่เจ้าถูกเหวี่ยงออกไปจากหลุมศพของเจ้า เหมือนกิ่งที่พึงรังเกียจ เหมือนเสื้อผ้าของผู้ที่ถูกสังหาร คือที่ถูกแทงด้วยดาบ ผู้ซึ่งลงไปยังกองหินของหลุมศพ เหมือนซากศพที่ถูกเหยียบย่ําอยู่ใต้ฝ่าเท้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 20, 'เจ้าจะไม่ได้รับการฝังศพร่วมกับเขา เพราะเจ้าได้ทําลายแผ่นดินของเจ้า เจ้าได้สังหารประชาชนของเจ้า ‘ขออย่าให้ใครเอ่ยถึงชื่อของเชื้อสายแห่งผู้กระทําความชั่วอีกเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 21, 'จงเตรียมสังหารลูกๆของเขาเถิด เพราะความชั่วช้าแห่งบิดาของเขา เกรงว่าเขาทั้งหลายจะลุกขึ้นเป็นเจ้าของแผ่นดิน และกระทําให้พื้นโลกเต็มไปด้วยหัวเมือง’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 22, 'พระเยโฮวาห์จอมโยธาตรัสว่า “เพราะเราจะลุกขึ้นสู้กับเขา และจะตัดชื่อกับคนที่เหลืออยู่และลูกหลานออกจากบาบิโลน” พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 23, '“และเราจะกระทําให้เป็นกรรมสิทธิ์ของอีกาบ้าน และเป็นสระน้ํา และจะกวาดด้วยไม้กวาดแห่งการทําลาย” พระเยโฮวาห์จอมโยธาตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 24, 'พระเยโฮวาห์จอมโยธาได้ทรงปฏิญาณว่า “เรากะแผนงานไว้อย่างไร ก็จะเป็นไปอย่างนั้น และเราได้มุ่งหมายไว้อย่างไร ก็จะเกิดขึ้นอย่างนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 25, 'คือว่าเราจะตีคนอัสซีเรียในแผ่นดินของเราให้ย่อยยับไป และบนภูเขาของเราเหยียบย่ําเขาไว้ และแอกของเขานั้นจะพรากไปจากเขาทั้งหลาย และภาระของเขานั้นจากบ่าของเขาทั้งหลาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 26, 'นี่เป็นความมุ่งหมายที่มุ่งหมายไว้เกี่ยวกับแผ่นดินโลกทั้งสิ้น และนี่เป็นพระหัตถ์ซึ่งเหยียดออกเหนือบรรดาประชาชาติทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 27, 'เพราะพระเยโฮวาห์จอมโยธาทรงมุ่งไว้แล้ว ผู้ใดเล่าจะลบล้างเสียได้ พระหัตถ์ของพระองค์ทรงเหยียดออก และผู้ใดจะหันให้กลับได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 28, 'ในปีที่กษัตริย์อาหัสสิ้นพระชนม์ ภาระนี้มีมาว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 29, '“ประเทศฟีลิสเตียเอ๋ย เจ้าทุกคนอย่าเปรมปรีดิ์ไปเลย เพราะว่าตะบองซึ่งตีเจ้านั้นหักเสียแล้ว เพราะงูทับทางจะออกมาจากรากเง่าของงู และผลของมันจะเป็นงูแมวเซา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 30, 'และลูกหัวปีของคนยากจนจะมีอาหารกิน และคนขัดสนจะนอนลงอย่างปลอดภัย แต่เราจะฆ่ารากเง่าของเจ้าด้วยการกันดารอาหาร และคนที่เหลืออยู่ของเจ้าจะถูกสังหารเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 31, 'โอ ประตูเมืองเอ๋ย พิลาปร่ําไห้ซิ โอ กรุงเอ๋ย จงร้องไห้ ประเทศฟีลิสเตียเอ๋ย เจ้าทุกคนจงละลายเสีย เพราะควันจะออกมาจากทิศเหนือ และจะไม่มีคนล้าหลังในแถวของเขาเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 32, 'จะตอบทูตของประชาชาตินั้นว่าอย่างไร ก็ว่า “พระเยโฮวาห์ได้ทรงสถาปนาศิโยน และคนยากจนในชนชาติของพระองค์จะได้วางใจในที่นั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 1, 'ภาระเกี่ยวกับโมอับ เพราะนครอาร์แห่งโมอับถูกทําลายร้างในคืนเดียวและได้ถึงหายนะ เพราะนครคีร์แห่งโมอับถูกทําลายร้างในคืนเดียวและได้ถึงหายนะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 2, 'เขาได้ขึ้นไปยังบายิทและดีโบน ไปยังปูชนียสถานสูงเพื่อจะร่ําไห้ โมอับจะคร่ําครวญถึงเนโบและถึงเมเดบา ศีรษะทุกศีรษะจะโล้น และหนวดเคราทุกคนก็ถูกโกนออกเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 3, 'เขาจะคาดผ้ากระสอบอยู่ในถนนหนทาง ทุกคนจะร่ําไห้เป็นนักหนาที่บนหลังคาเรือนและตามถนน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 4, 'เมืองเฮชโบนและเอเลอาเลห์จะส่งเสียงร้อง เสียงของเขาจะได้ยินไปถึงเมืองยาฮาส เพราะฉะนั้นทหารที่ถืออาวุธของโมอับจึงจะร้องเสียงดัง ชีวิตของเขาจะเป็นที่เศร้าโศกแก่เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 5, 'จิตใจของข้าพเจ้าจะร้องออกมาเพื่อโมอับ ผู้หลบภัยของโมอับนั้นจะหนีไปยังโศอาร์ เหมือนอย่างวัวสาวที่มีอายุสามปี เพราะตามทางขึ้นไปเมืองลูฮีท เขาจะขึ้นไปคร่ําครวญ ตามถนนสู่เมืองโฮโรนาอิม เขาจะเปล่งเสียงร้องถึงการทําลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 6, 'เพราะธารน้ําที่นิมริมก็จะถูกทิ้งร้าง ฟางก็เหี่ยวแห้ง หญ้าก็ไม่งอก พืชที่เขียวชอุ่มไม่มีเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 7, 'เพราะฉะนั้นทรัพย์สินซึ่งเขาเก็บได้ และที่เขาสะสมไว้ เขาจะขนเอาไปข้ามลําธารต้นหลิว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 8, 'เพราะเสียงร้องได้กระจายไปทั่วชายแดนโมอับ เสียงคร่ําครวญไปถึงเอกลาอิม เสียงคร่ําครวญไปถึงเบเออร์เอลิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 9, 'เพราะน้ําของเมืองดีโมนจะมีเลือดเต็มไปหมด ถึงกระนั้นเรายังจะเพิ่มภัยแก่ดีโมนอีก คือให้สิงโตสําหรับชาวโมอับที่หนีไป และสําหรับคนที่เหลืออยู่ในแผ่นดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 1, 'เจ้าจงส่งลูกแกะไปยังผู้ปกครองแผ่นดินจากเส-ลาตามทางถิ่นทุรกันดาร ไปยังภูเขาแห่งธิดาของศิโยน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 2, 'เหมือนนกที่กําลังบินหนีอย่างลูกนกที่พลัดรัง ธิดาของโมอับจะเป็นอย่างนั้นตรงท่าลุยข้ามแม่น้ําอารโนน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 3, '“จงให้คําปรึกษา จงอํานวยความยุติธรรม จงทําร่มเงาของท่านเหมือนกลางคืน ณ เวลาเที่ยงวัน จงช่วยซ่อนผู้ถูกขับไล่ อย่าหักหลังผู้ลี้ภัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 4, 'โมอับเอ๋ย จงให้ผู้ถูกขับไล่ของเราอาศัยอยู่ท่ามกลางท่าน จงเป็นที่กําบังภัยแก่เขาให้พ้นจากหน้าผู้ทําลาย เพราะผู้บีบบังคับได้สิ้นสุดแล้ว ผู้ทําลายได้หยุดยั้งแล้ว และผู้เหยียบย่ําได้ถูกเผาผลาญไปเสียจากแผ่นดินแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 5, 'พระที่นั่งก็จะได้รับการสถาปนาด้วยความเมตตา บนนั้นจะมีผู้หนึ่งนั่งอยู่ด้วยความจริงในเต็นท์ของดาวิด คือท่านผู้พิพากษาและแสวงหาความยุติธรรม และรวดเร็วในการกระทําความชอบธรรม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 6, 'เราได้ยินถึงความเย่อหยิ่งของโมอับ ว่าเขาหยิ่งเสียจริงๆ ถึงความจองหองของเขา ความเย่อหยิ่งของเขา และความโกรธของเขา แต่คําโกหกของเขาจะไม่สําเร็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 7, 'เพราะฉะนั้นโมอับจะคร่ําครวญเพื่อโมอับ ทุกคนจะคร่ําครวญ เจ้าทั้งหลายจะโอดครวญเนื่องด้วยรากฐานของเมืองคีร์หะเรเชท เพราะมันจะถูกทุบแน่นอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 8, 'เพราะทุ่งนาแห่งเมืองเฮชโบนอ่อนระทวย ทั้งเถาองุ่นของสิบมาห์ เจ้านายทั้งหลายแห่งบรรดาประชาชาติได้ตีกิ่งของมันลง ซึ่งไปถึงเมืองยาเซอร์ และพเนจรไปถึงถิ่นทุรกันดาร หน่อของมันก็แตกกว้างออกไปและผ่านข้ามทะเลไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 9, 'เพราะฉะนั้นข้าพเจ้าจึงร้องไห้กับคนร้องไห้ของเมืองยาเซอร์ เนื่องด้วยเถาองุ่นของสิบมาห์ โอ เฮชโบนและเอเลอาเลห์เอ๋ย ข้าพเจ้าจะราดเจ้าด้วยน้ําตาของข้าพเจ้า เพราะเสียงโห่ร้องเนื่องด้วยผลฤดูร้อนของเจ้า และเนื่องด้วยข้าวที่เกี่ยวเก็บของเจ้าได้สงบลงแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 10, 'เขาเอาความชื่นบานและความยินดีไปเสียจากที่สวนผลไม้ เขาไม่ร้องเพลงกันตามสวนองุ่น ไม่มีใครโห่ร้อง ตามบ่อย่ําองุ่นไม่มีคนย่ําให้น้ําองุ่นออก ข้าพเจ้าทําให้เสียงเห่ย่ําองุ่นเงียบเสียแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 11, 'ฉะนั้นจิตของข้าพเจ้าจึงจะร่ําไห้เหมือนพิณเขาคู่เพื่อโมอับ และใจของข้าพเจ้าร่ําไห้เพื่อคีร์เฮเรส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 12, 'และต่อมาเมื่อเห็นว่าโมอับเหน็ดเหนื่อยอยู่ที่ปูชนียสถานสูงนั้น และเมื่อเขาจะเข้ามาในสถานบริสุทธิ์ของเขาเพื่อจะอธิษฐาน เขาก็จะไม่ได้รับผล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 13, 'นี่เป็นพระวจนะซึ่งพระเยโฮวาห์ตรัสเกี่ยวกับโมอับในอดีต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 14, 'แต่บัดนี้ พระเยโฮวาห์ตรัสว่า “ภายในสามปี ตามปีจ้างลูกจ้าง สง่าราศีของโมอับจะถูกเหยียดหยาม แม้มวลชนมหึมาของเขาทั้งสิ้นก็ดี และคนที่เหลืออยู่นั้นก็จะน้อยและกะปลกกะเปลี้ย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 1, 'ภาระเกี่ยวกับเมืองดามัสกัส ดูเถิด ดามัสกัสจะหยุดไม่เป็นเมือง และจะกลายเป็นกองสิ่งปรักหักพัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 2, 'เมืองต่างๆของอาโรเออร์จะเริศร้างเป็นนิตย์ จะเป็นที่สําหรับฝูงแพะแกะ ซึ่งมันจะนอนลงและไม่มีผู้ใดจะให้มันกลัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 3, 'ป้อมปราการจะสูญหายไปจากเอฟราอิม และราชอาณาจักรจะสูญหายไปจากดามัสกัสและคนที่เหลืออยู่ของซีเรีย พวกเขาจะเป็นเหมือนสง่าราศีของคนอิสราเอล พระเยโฮวาห์จอมโยธาตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 4, 'และต่อมาในวันนั้นสง่าราศีของยาโคบจะตกต่ํา และความอ้วนที่เนื้อของเขาจะซูบผอมลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 5, 'และจะเป็นเหมือนเมื่อคนเกี่ยวข้าวเก็บเกี่ยวพืชข้าวที่ตั้งอยู่และแขนของเขาจะเกี่ยวรวงข้าว และจะเป็นเหมือนเมื่อคนหนึ่งเก็บรวงข้าวในที่หุบเขาเรฟาอิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 6, 'จะมีผลองุ่นเหลืออยู่บ้างในนั้น เหมือนอย่างเมื่อตีต้นมะกอกเทศให้ลูกหล่น จะมีเหลืออยู่ที่ยอดสูงที่สุดสองสามลูก หรือที่เหลือบนกิ่งไม้ ผลสี่ห้าลูก พระเยโฮวาห์พระเจ้าแห่งอิสราเอลตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 7, 'ในวันนั้น คนจะมองดูพระผู้สร้างตน และนัยน์ตาเขาจะเอาใจใส่ในองค์บริสุทธิ์ของอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 8, 'เขาจะไม่มองแท่นบูชา ผลงานแห่งมือของเขา และเขาจะไม่เอาใจใส่สิ่งที่นิ้วของเขาเองได้กระทําขึ้น ไม่ว่าจะเป็นเสารูปเคารพ หรือรูปเคารพทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 9, 'ในวันนั้นเมืองเข้มแข็งของเขาจะเป็นเหมือนกิ่งไม้ที่ถูกทอดทิ้ง และกิ่งก้านที่อยู่บนยอดสูงที่สุดซึ่งเขาได้ละทิ้งเพราะคนอิสราเอล และจะมีการรกร้างว่างเปล่าเกิดขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 10, 'เพราะเจ้าได้หลงลืมพระเจ้าแห่งความรอดของเจ้าเสีย และมิได้จดจําศิลาเข้มแข็งของเจ้า ฉะนั้นเจ้าจะปลูกต้นอภิรมย์ และจะปลูกกิ่งไม้ต่างชาติลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 11, 'เจ้าจะทําให้มันงอกในวันที่เจ้าปลูกมัน และจะทําให้มันออกดอกในเช้าของวันที่เจ้าหว่าน ถึงกระนั้นผลการเก็บเกี่ยวก็จะหนีไป ในวันแห่งความกลัดกลุ้มและความทุกข์ใจอย่างเหลือเกิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 12, 'วิบัติแก่ชนชาติทั้งหลายเป็นอันมาก ซึ่งทําเสียงกึกก้องเหมือนทะเลก้องกึก และแก่เสียงครืนๆของชนชาติทั้งหลาย ซึ่งครืนๆเหมือนเสียงครืนๆของน้ําที่มีกําลังมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 13, 'ชนชาติทั้งหลายครืนๆเหมือนเสียงครืนๆของน้ําเป็นอันมาก แต่พระเจ้าจะทรงขนาบไว้ และมันจะหนีไปไกลเสีย จะถูกไล่ไปเหมือนแกลบต้องลมบนภูเขา เหมือนพืชแห้งปลิวไปต่อหน้าลมหมุน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 14, 'ดูเถิด พอเวลาเย็น ก็ความสยดสยอง ก่อนรุ่งเช้า ก็ไม่มีเขาทั้งหลายแล้ว นี่เป็นส่วนของบรรดาผู้ที่ริบของของเรา และเป็นส่วนของผู้ที่ปล้นเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 1, 'วิบัติแก่แผ่นดินแห่งปีกที่กระหึ่ม ซึ่งอยู่เลยแม่น้ําทั้งหลายแห่งเอธิโอเปีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 2, 'ซึ่งส่งทูตไปโดยทางทะเล โดยเรือต้นกกบนน้ํา กล่าวว่า “เจ้าผู้สื่อสารที่รวดเร็วเอ๋ย จงไปยังประชาชาติที่ถูกกระจัดกระจายและถูกปอกเปลือก ยังชนชาติที่เขากลัวตั้งแต่แรก ยังประชาชาติที่เข้มแข็งและมักชนะ ซึ่งแผ่นดินของเขามีแม่น้ําแบ่ง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 3, 'ท่านทั้งปวงผู้เป็นชาวพิภพ ท่านอาศัยอยู่บนแผ่นดินโลก เมื่อเขายกอาณัติสัญญาณขึ้นบนภูเขา จงมองดู เมื่อเขาเป่าแตร จงฟัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 4, 'เพราะพระเยโฮวาห์ตรัสแก่ข้าพเจ้าดังนี้ว่า “เราจะพักผ่อนและจะพิจารณาจากที่อาศัยของเรา เหมือนความร้อนที่กระจ่างอยู่บนผักหญ้า เหมือนอย่างเมฆแห่งน้ําค้างในความร้อนของฤดูเกี่ยว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 5, 'เพราะก่อนถึงฤดูเกี่ยว ดอกตูมเบ่งบานเต็มที่แล้ว และผลองุ่นเปรี้ยวกําลังสุกอยู่ในช่อของมัน พระองค์จะทรงตัดแขนงออกด้วยขอลิดแขนงและนําออกไป และจะทรงตัดกิ่งก้านนั้นลงเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 6, 'และเขาทั้งหลายจะถูกทิ้งไว้ทั้งหมดให้แก่เหยี่ยวที่อยู่บนภูเขา และแก่สัตว์แห่งแผ่นดินโลก และนกกินเหยื่อจะกินเสียในฤดูร้อน และบรรดาสัตว์ทั้งสิ้นแห่งแผ่นดินโลกจะกินเสียในฤดูหนาว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 7, 'ในครั้งนั้น เขาจะนําของกํานัลมาถวายแด่พระเยโฮวาห์จอมโยธาจากชนชาติที่ถูกกระจัดกระจายและถูกปอกเปลือก จากชนชาติที่เขากลัวตั้งแต่แรก จากประชาชาติที่เข้มแข็งและมักชนะ ซึ่งแผ่นดินของเขามีแม่น้ําแบ่ง ยังสถานที่แห่งพระนามของพระเยโฮวาห์จอมโยธา คือภูเขาศิโยน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 1, 'ภาระเกี่ยวกับอียิปต์ ดูเถิด พระเยโฮวาห์ทรงเมฆอันรวดเร็วและจะเสด็จมายังอียิปต์ ต่อพระพักตร์พระองค์ รูปเคารพแห่งอียิปต์จะสั่นสะเทือน และใจของคนอียิปต์จะละลายไปภายในตัวเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 2, 'และเราจะกวนให้คนอียิปต์ต่อสู้กับคนอียิปต์ และเขาจะสู้รบกัน ทุกคนรบพี่น้องของตน และทุกคนรบเพื่อนบ้านของตน เมืองรบกับเมือง ราชอาณาจักรรบกับราชอาณาจักร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 3, 'และในสมัยนั้นคนอียิปต์ก็จะจนใจ และเราจะกระทําให้แผนงานของเขายุ่งเหยิง และเขาจะปรึกษารูปเคารพและพวกหมอดู และคนทรง และพ่อมดแม่มด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 4, 'และเราจะมอบคนอียิปต์ไว้ในมือของนายที่แข็งกระด้าง และกษัตริย์ดุร้ายคนหนึ่งจะปกครองเหนือเขา องค์พระผู้เป็นเจ้า พระเยโฮวาห์จอมโยธาตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 5, 'และน้ําจะแห้งไปจากทะเลและแม่น้ําจะแห้งผาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 6, 'และแม่น้ําของมันจะเน่าเหม็น และแม่น้ําแห่งการป้องกันจะน้อยลงและแห้งไป ต้นอ้อและกอปรือจะเหี่ยวแห้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 7, 'กอแขมที่แม่น้ํา ที่ริมฝั่งแม่น้ํา และทั้งสิ้นที่หว่านลงข้างแม่น้ํานั้นจะแห้งไป จะถูกไล่ไปเสียและไม่มีอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 8, 'ชาวประมงจะร้องทุกข์ คือบรรดาผู้ที่ตกเบ็ดในแม่น้ําจะไว้ทุกข์ และผู้ที่ทอดแหลงในน้ําจะอ่อนระทวย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 9, 'คนงานที่หวีป่านจะอับอาย ทั้งคนที่ทอฝ้ายขาวด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 10, 'บรรดาผู้ที่ทําเขื่อนและสระน้ําสําหรับปลา เป้าหมายของเขาจะถูกบีบคั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 11, 'พวกเจ้านายแห่งโศอันโง่เขลาทีเดียว ที่ปรึกษาที่ฉลาดของฟาโรห์ให้คําปรึกษาอย่างโง่เขลา พวกเจ้าจะพูดกับฟาโรห์ได้อย่างไรว่า “ข้าพระองค์เป็นบุตรของนักปราชญ์ เป็นเชื้อสายของกษัตริย์โบราณ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 12, 'พวกท่านอยู่ที่ไหน นักปราชญ์ของท่านอยู่ที่ไหน ให้เขาบอกท่านและให้เขาทําให้แจ้งซิว่า พระเยโฮวาห์จอมโยธามีพระประสงค์อะไรกับอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 13, 'เจ้านายแห่งโศอันกลายเป็นคนโง่ และเจ้านายแห่งโนฟถูกหลอกลวงแล้ว บรรดาผู้ที่เป็นศิลามุมเอกของตระกูลของอียิปต์ ได้นําอียิปต์ให้หลงไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 14, 'พระเยโฮวาห์ทรงปนดวงจิตแห่งความยุ่งเหยิงไว้ในอียิปต์ และเขาทั้งหลายได้กระทําให้อียิปต์แชเชือนในการกระทําทั้งสิ้นของมัน ดั่งคนเมาโซเซอยู่บนสิ่งที่เขาอาเจียน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 15, 'ไม่มีอะไรที่จะกระทําได้เพื่อช่วยอียิปต์ ซึ่งหัวก็ดี หางก็ดี หรือกิ่งก้านก็ดี ต้นกกก็ดี ไม่อาจจะทําได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 16, 'ในวันนั้นอียิปต์จะเป็นเหมือนผู้หญิง จะเกรงกลัวและหวาดกลัวต่อพระหัตถ์ซึ่งพระเยโฮวาห์จอมโยธาทรงกวัดแกว่งเหนือเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 17, 'และแผ่นดินยูดาห์จะเป็นที่หวาดกลัวแก่คนอียิปต์ เมื่อกล่าวชื่อให้คนหนึ่งคนใดเขาก็จะกลัว เพราะพระประสงค์ของพระเยโฮวาห์จอมโยธา ซึ่งทรงประสงค์ต่อเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 18, 'ในวันนั้นจะมีห้าหัวเมืองในแผ่นดินอียิปต์ซึ่งพูดภาษาของคานาอัน และปฏิญาณต่อพระเยโฮวาห์จอมโยธา เมืองหนึ่งเขาจะเรียกว่า เมืองแห่งการรื้อทําลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 19, 'ในวันนั้นจะมีแท่นบูชาแท่นหนึ่งแด่พระเยโฮวาห์ในท่ามกลางแผ่นดินอียิปต์ และมีเสาสําคัญแด่พระเยโฮวาห์ที่พรมแดน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 20, 'จะเป็นหมายสําคัญและเป็นพยานในแผ่นดินอียิปต์ถึงพระเยโฮวาห์จอมโยธา เพราะเมื่อเขาทั้งหลายร้องทูลต่อพระเยโฮวาห์เหตุด้วยผู้บีบบังคับเขา พระองค์จะทรงส่งผู้ช่วยผู้ยิ่งใหญ่มาให้เขา และผู้นั้นจะทรงช่วยเขาให้พ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 21, 'และพระเยโฮวาห์จะสําแดงพระองค์ให้เป็นที่รู้จักแก่คนอียิปต์ และคนอียิปต์จะรู้จักพระเยโฮวาห์ในวันนั้น และจะถวายเครื่องสักการบูชาและเครื่องถวาย และเขาทั้งหลายจะปฏิญาณต่อพระเยโฮวาห์และปฏิบัติตาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 22, 'และพระเยโฮวาห์จะโจมตีอียิปต์ ทรงโจมตีพลาง ทรงรักษาพลาง และเขาทั้งหลายจะหันกลับมาหาพระเยโฮวาห์ และพระองค์จะทรงฟังคําวิงวอนของเขา และทรงรักษาเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 23, 'ในวันนั้นจะมีทางหลวงจากอียิปต์ถึงอัสซีเรีย และคนอัสซีเรียจะเข้ามายังอียิปต์ และคนอียิปต์ยังอัสซีเรีย และคนอียิปต์จะปรนนิบัติพร้อมกับคนอัสซีเรีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 24, 'ในวันนั้นอิสราเอลจะเป็นที่สามกับอียิปต์และกับอัสซีเรีย เป็นพรท่ามกลางแผ่นดินนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 25, 'เป็นผู้ที่พระเยโฮวาห์จอมโยธาจะทรงอํานวยพระพรว่า “อียิปต์ชนชาติของเราจงได้รับพร และอัสซีเรียผลงานแห่งมือของเรา และอิสราเอลมรดกของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 1, 'ในปีที่ทารทาน (ผู้ซึ่งซาร์กอนกษัตริย์แห่งอัสซีเรียทรงใช้มานั้น) ได้มาถึงเมืองอัชโดดและได้ต่อสู้ยึดเมืองอัชโดดนั้นได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 2, 'ในครั้งนั้นพระเยโฮวาห์ตรัสโดยอิสยาห์บุตรชายอามอสว่า “จงไปแก้ผ้ากระสอบออกจากบั้นเอวของเจ้า และเอารองเท้าออกจากเท้าของเจ้า” และท่านก็กระทําตาม เดินเปลือยกายและเท้าเปล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 3, 'และพระเยโฮวาห์ตรัสว่า “อิสยาห์ผู้รับใช้ของเราเดินเปลือยกายและเท้าเปล่าสามปี เป็นหมายสําคัญและเป็นมหัศจรรย์แก่อียิปต์และแก่เอธิโอเปียฉันใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 4, 'กษัตริย์แห่งอัสซีเรียจะนําคนอียิปต์ไปเป็นเชลย และจะกวาดคนเอธิโอเปียไปเป็นเชลย ทั้งคนหนุ่มสาวและคนแก่ เปลือยกายและเท้าเปล่า เปิดก้น เป็นที่ละอายแก่อียิปต์ฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 5, 'แล้วเขาทั้งหลายจะกลัวและอับอายด้วยเหตุเอธิโอเปียความหวังของเขา และอียิปต์ความโอ้อวดของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 6, 'และชาวเกาะนี้จะกล่าวในวันนั้นว่า “ดูเถิด นี่แหละผู้ซึ่งเราหวังใจ และผู้ซึ่งเราหนีไปหาความช่วยให้พ้นจากกษัตริย์อัสซีเรีย และเราจะหนีให้พ้นได้อย่างไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 1, 'ภาระเกี่ยวกับถิ่นทุรกันดารของทะเล เหมือนลมหมุนในภาคใต้พัดเกลี้ยงไป มันมาจากถิ่นทุรกันดาร จากแผ่นดินอันน่าคร้ามกลัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 2, 'เขาบอกนิมิตที่เหี้ยมหาญแก่ข้าพเจ้า ว่าผู้ปล้นเข้าปล้น ผู้ทําลายเข้าทําลาย โอ เอลามเอ๋ย จงขึ้นไป โอ มีเดียเอ๋ย จงเข้าล้อมซึ่งมันให้เกิดการถอนหายใจทั้งสิ้น เราได้กระทําให้สิ้นไปแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 3, 'เพราะฉะนั้นบั้นเอวของข้าพเจ้าจึงเต็มด้วยความแสนระทม ความเจ็บปวดฉวยข้าพเจ้าไว้อย่างความเจ็บปวดที่หญิงกําลังคลอดบุตร ข้าพเจ้าจนใจเพราะสิ่งที่ได้ยิน ข้าพเจ้าท้อถอยเพราะสิ่งที่ได้เห็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 4, 'จิตใจของข้าพเจ้าฟุ้งซ่านไป ความหวาดเสียวกระทําให้ข้าพเจ้าครั่นคร้าม แสงโพล้เพล้ซึ่งข้าพเจ้าหวังกลับทําให้ข้าพเจ้าสั่นสะเทือน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 5, 'จงเตรียมสํารับไว้ จงเฝ้าอยู่บนหอคอย จงกิน จงดื่ม เจ้านายทั้งหลายเอ๋ย จงลุกขึ้นชโลมโล่ไว้ด้วยน้ํามัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 6, 'เพราะองค์พระผู้เป็นเจ้าตรัสกับข้าพเจ้าดังนี้ว่า “จงไป ตั้งยามให้เขาไปร้องประกาศสิ่งที่เขาเห็น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 7, 'เขาได้เห็นรถรบพร้อมกับพลม้าเป็นคู่ๆ รถเทียมลาเป็นคู่ๆและรถเทียมอูฐเป็นคู่ๆ เขาได้ฟังอย่างพินิจพิเคราะห์ อย่างพินิจพิเคราะห์ทีเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 8, 'แล้วผู้เห็นได้ร้องว่า “พวกเขามาดุจสิงโต ข้าแต่องค์พระผู้เป็นเจ้า ข้าพระองค์ยืนอยู่บนหอคอยตลอดไปในกลางวัน ข้าพระองค์ประจําอยู่ที่ตําแหน่งของข้าพระองค์ตลอดหลายคืน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 9, 'และ ดูเถิด รถรบพร้อมพลรบกับพลม้าเป็นคู่ๆกําลังมา” และเขาตอบว่า “บาบิโลนล่มแล้ว ล่มแล้ว บรรดารูปเคารพสลักทั้งสิ้นแห่งพระของเขา พระองค์ทรงทําลายลงถึงพื้นดิน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 10, 'โอ ท่านผู้ถูกนวดและผู้ถูกฝัดของข้าพเจ้าเอ๋ย ข้าพเจ้าได้ยินอะไรจากพระเยโฮวาห์จอมโยธา พระเจ้าแห่งอิสราเอล ข้าพเจ้าก็ร้องประกาศแก่ท่านอย่างนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 11, 'ภาระเกี่ยวกับดูมาห์ มีคนหนึ่งเรียกข้าพเจ้าจากเสอีร์ว่า “คนยามเอ๋ย ดึกเท่าไรแล้ว คนยามเอ๋ย ดึกเท่าไรแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 12, 'คนยามตอบว่า “เช้ามาถึง กลางคืนมาด้วย ถ้าจะถาม ก็ถามเถิด จงกลับมาอีก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 13, 'ภาระเกี่ยวกับอาระเบีย โอ กระบวนพ่อค้าของคนเดดานเอ๋ย เจ้าจะพักอยู่ในดงทึบในอาระเบีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 14, 'ชาวแผ่นดินเทมาได้เอาน้ํามาให้คนกระหาย เขาเอาขนมปังมาต้อนรับคนลี้ภัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 15, 'เพราะเขาได้หนีจากดาบ จากดาบที่ชักออก จากธนูที่โก่งอยู่ และจากสงครามซึ่งทําให้ทุกข์ทรมานเป็นอย่างมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 16, 'เพราะองค์พระผู้เป็นเจ้าตรัสกับข้าพเจ้าดังนี้ว่า “สง่าราศีทั้งสิ้นของเคดาร์จะถึงที่สุดภายในปีเดียวตามปีจ้างลูกจ้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 17, 'และนักธนูที่เหลืออยู่ของทแกล้วทหารแห่งชาวเคดาร์จะเหลือน้อย เพราะพระเยโฮวาห์พระเจ้าของอิสราเอลได้ตรัสแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 1, 'ภาระเกี่ยวกับที่ลุ่มแห่งนิมิต ที่เจ้าได้ขึ้นไป เจ้าทุกคน ที่บนหลังคาเรือนนั้น เป็นเรื่องอะไรกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 2, 'เจ้าผู้เป็นเมืองที่เต็มด้วยการโห่ร้อง เมืองที่อึกทึกครึกโครม นครที่เต้นโลด ผู้ที่ถูกฆ่าของเจ้ามิได้ถูกฆ่าด้วยดาบ หรือตายในสงคราม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 3, 'ผู้ครองเมืองของเจ้าทั้งหมดหนีกันไปแล้ว เขาถูกจับได้โดยนายธนู ชายฉกรรจ์ของเจ้าทุกคนถูกจับแม้ว่าเขาได้หนีไปไกลแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 4, 'เพราะฉะนั้นข้าพเจ้าจึงว่า “อย่ามองข้าพเจ้า ให้ข้าพเจ้าหลั่งน้ําตาอย่างขมขื่น อย่าอุตส่าห์เล้าโลมข้าพเจ้าเลย เหตุด้วยการทําลายธิดาแห่งชนชาติของข้าพเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 5, 'เพราะองค์พระผู้เป็นเจ้าพระเจ้าจอมโยธาทรงมีวันหนึ่ง เป็นวาระจลาจล วาระเหยียบย่ํา และวาระยุ่งเหยิงในที่ลุ่มแห่งนิมิต คือการพังกําแพงลงและโห่ร้องให้แก่ภูเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 6, 'เอลามหยิบแล่งธนู กับเหล่ารถรบพร้อมพลรบและพลม้าและคีร์ก็เผยโล่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 7, 'ต่อมาที่ลุ่มที่ดีที่สุดของท่านจะเต็มไปด้วยรถรบ และพลม้าจะเข้าประจําที่ประตูเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 8, 'พระองค์ทรงเอาสิ่งปิดบังยูดาห์ไปเสียแล้ว ในวันนั้นท่านได้มองที่อาวุธแห่งเรือนพนา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 9, 'ท่านได้เห็นช่องโหว่แห่งนครดาวิดว่ามีหลายแห่ง แล้วท่านทั้งหลายก็เก็บน้ําในบ่อล่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 10, 'และท่านก็นับเรือนของเยรูซาเล็ม และท่านก็พังเรือนมาเสริมกําแพงเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 11, 'ท่านทําที่ขับน้ําไว้ระหว่างกําแพงทั้งสองเพื่อรับน้ําของสระเก่า แต่ท่านมิได้มองดูผู้ที่ได้ทรงบันดาลเหตุ และมิได้เอาใจใส่ผู้ทรงวางแผนงานนี้ไว้นานมาแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 12, 'ในวันนั้นองค์พระผู้เป็นเจ้าพระเจ้าจอมโยธาทรงเรียกให้ร่ําไห้และคร่ําครวญ ให้มีศีรษะโล้นและให้คาดตัวด้วยผ้ากระสอบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 13, 'และ ดูเถิด มีความชื่นบานและความยินดี มีการฆ่าวัวและฆ่าแกะ มีการกินเนื้อและดื่มน้ําองุ่น “ให้เรากินและดื่มเถิด เพราะว่าพรุ่งนี้เราจะตาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 14, 'พระเยโฮวาห์จอมโยธาได้ทรงสําแดงในหูของข้าพเจ้าว่า “แน่ทีเดียวที่จะไม่ลบความชั่วช้าอันนี้ให้เจ้า จนกว่าเจ้าจะตาย” องค์พระผู้เป็นเจ้าพระเจ้าจอมโยธาตรัสดังนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 15, 'องค์พระผู้เป็นเจ้าพระเจ้าจอมโยธาตรัสดังนี้ว่า “ไปเถิด ไปหาผู้รักษาทรัพย์สมบัติคนนี้ คือไปยังเชบนาห์ ผู้ดูแลราชสํานัก และจงพูดกับเขาว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 16, 'เจ้ามีสิทธิ์อะไรที่นี่ และเจ้ามีใครอยู่ที่นี่ เจ้าจึงสกัดอุโมงค์ที่นี่เพื่อตัวเจ้าเอง ดุจคนสกัดอุโมงค์ในที่สูง และสลักที่อยู่สําหรับตนเองในศิลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 17, 'ดูเถิด พระเยโฮวาห์จะทรงเหวี่ยงเจ้าออกไปให้เป็นเชลยอย่างแรง พระองค์จะทรงฉวยเจ้าให้แน่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 18, 'และม้วนเจ้า และขว้างเจ้าไปอย่างลูกบอลยังแผ่นดินกว้าง เจ้าจะตายที่นั่น และที่นั่นจะมีรถรบอันตระการของเจ้า เจ้าผู้เป็นที่อดสูแก่เรือนนายของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 19, 'เราจะผลักเจ้าออกไปจากตําแหน่งของเจ้า และเจ้าจะถูกดึงลงมาจากหน้าที่ของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 20, 'อยู่มาในวันนั้นเราจะเรียกผู้รับใช้ของเรา คือเอลียาคิม บุตรชายฮิลคียาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 21, 'เราจะเอาเสื้อยศของเจ้ามาสวมให้เขา และจะเอาผ้าคาดของเจ้าคาดเขาไว้ และจะมอบอํานาจปกครองของเจ้าไว้ในมือของเขา และเขาจะเป็นดังบิดาแก่ชาวเยรูซาเล็มและแก่วงศ์วานยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 22, 'และเราจะวางลูกกุญแจของวังดาวิดไว้บนบ่าของเขา เขาจะเปิดและไม่มีผู้ใดปิด เขาจะปิดและไม่มีผู้ใดเปิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 23, 'และเราจะตอกเขาไว้เหมือนตอกหมุดในที่มั่นคง และเขาจะเป็นที่นั่งมีเกียรติแก่วงศ์วานบิดาของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 24, 'และเขาทั้งหลายจะแขวนไว้บนตัวเขาซึ่งสง่าราศีทั้งสิ้นของวงศ์วานบิดาของเขา ลูกหลานผู้สืบสาย ภาชนะเล็กๆทุกชิ้น ตั้งแต่ถ้วยจนถึงเหยือกทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 25, 'พระเยโฮวาห์จอมโยธาตรัสว่า ในวันนั้นหมุดที่ปักแน่นอยู่ในที่มั่นจะหลุด มันจะถูกโค่นลงและตกลงมา และภาระที่อยู่บนนั้นจะถูกขจัดออก เพราะพระเยโฮวาห์ได้ตรัสไว้แล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 1, 'ภาระเกี่ยวกับเมืองไทระ บรรดากําปั่นแห่งทารชิชเอ๋ย จงคร่ําครวญ เพราะว่าเมืองนั้นถูกทําลายร้างเสียแล้ว ไม่มีเรือนหรือท่าจอดเรือ เผยให้เขาทั้งหลายประจักษ์ ณ แผ่นดินคิทธิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 2, 'ชาวเกาะเอ๋ย จงนิ่งเสีย เจ้าซึ่งพ่อค้าแห่งเมืองไซดอนที่ผู้ผ่านข้ามทะเลไป ได้ทําให้เจ้าเต็มบริบูรณ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 3, 'และข้ามน้ํามากหลายรายได้ของเมืองนั้นคือข้าวเมืองชิโหร์ เป็นผลเกี่ยวเก็บของแม่น้ํา เมืองนั้นเป็นพ่อค้าของบรรดาประชาชาติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 4, 'โอ ไซดอนเอ๋ย จงอับอายเถิด เพราะทะเลได้พูดแล้ว ที่กําบังเข้มแข็งของทะเลพูดว่า “ข้ามิได้ปวดครรภ์ หรือข้ามิได้คลอดบุตร ข้ามิได้เลี้ยงดูคนหนุ่ม หรือบํารุงเลี้ยงหญิงพรหมจารี”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 5, 'เขาทั้งหลายรับเรื่องราวเกี่ยวกับอียิปต์อย่างไร เขาจะแสนระทมอยู่ด้วยเรื่องราวเมืองไทระอย่างนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 6, 'จงข้ามไปยังทารชิชเถิด ชาวเกาะเอ๋ย จงคร่ําครวญ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 7, 'นี่เป็นเมืองที่สนุกสนานของเจ้าทั้งหลายหรือ ซึ่งกําเนิดมาแต่กาลโบราณ ซึ่งเท้าได้พามันไปตั้งอยู่ไกล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 8, 'ผู้ใดได้มุ่งหมายไว้เช่นนี้ต่อเมืองไทระ คือเมืองที่ให้มงกุฎ ซึ่งบรรดาพ่อค้าของมันเป็นเจ้านาย ซึ่งพวกพาณิชของมันเป็นคนมีเกียรติของโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 9, 'พระเยโฮวาห์จอมโยธาทรงมุ่งหมายไว้เพื่อจะหลู่ความเย่อหยิ่งของสง่าราศีทั้งสิ้น เพื่อหลู่เกียรติของผู้มีเกียรติทั้งสิ้นในแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 10, 'โอ ธิดาแห่งทารชิชเอ๋ย จงผ่านแผ่นดินของเจ้าข้ามไปเหมือนแม่น้ํา มันไม่มีกําลังอีกเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 11, 'พระองค์ทรงเหยียดพระหัตถ์ของพระองค์เหนือทะเล พระองค์ทรงบันดาลให้บรรดาราชอาณาจักรสั่นสะเทือน พระเยโฮวาห์ทรงบัญชาเกี่ยวกับเรื่องเมืองแห่งพาณิชย์ เพื่อจะทําลายที่กําบังเข้มแข็งของมันเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 12, 'และพระองค์ตรัสว่า “โอ ธิดาพรหมจารีผู้ถูกบีบบังคับแห่งไซดอนเอ๋ย เจ้าจะไม่เริงโลดต่อไปอีก จงลุกขึ้นข้ามไปคิทธิมเถิด แม้ที่นั่นเจ้าก็จะไม่มีความสงบ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 13, 'จงดูแผ่นดินแห่งคนเคลเดียเถิด ชนชาตินี้ยังไม่มีขึ้นมา จนกว่าคนอัสซีเรียสถาปนาแผ่นดินนั้นไว้สําหรับคนที่อาศัยอยู่ตามถิ่นทุรกันดาร พวกเขาได้ก่อเชิงเทินของเขาขึ้น พวกเขาก่อวังทั้งหลายของเขาขึ้น แต่ท่านกระทําให้มันเป็นที่ปรักหักพัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 14, 'บรรดากําปั่นแห่งทารชิชเอ๋ย จงคร่ําครวญเถิด เพราะว่าที่กําบังเข้มแข็งของเจ้าถูกทิ้งร้างเสียแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 15, 'ต่อมาในวันนั้น เขาจะลืมเมืองไทระเจ็ดสิบปี อย่างกับอายุของกษัตริย์องค์เดียว พอสิ้นเจ็ดสิบปีไทระจะร้องเพลงอย่างหญิงแพศยาว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 16, '“หญิงแพศยาที่เขาลืมแล้วเอ๋ย จงหยิบพิณเขาคู่เดินไปทั่วเมือง จงบรรเลงเพลงไพเราะ ร้องเพลงหลายๆบท เพื่อเขาจะระลึกเจ้าได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 17, 'ต่อมาเมื่อสิ้นเจ็ดสิบปี พระเยโฮวาห์จะทรงเยี่ยมเยียนเมืองไทระ และเมืองนั้นจะกลับไปรับจ้างใหม่ และจะเล่นชู้กับบรรดาราชอาณาจักรทั้งสิ้นบนพื้นโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 18, 'สินค้าของมันและสินจ้างของมันจะเป็นของบริสุทธิ์ถวายแด่พระเยโฮวาห์ จะไม่สะสมไว้หรือเก็บนิ่งไว้ แต่สินค้าของมันจะอํานวยอาหารอุดมและเสื้อผ้างามแก่บรรดาผู้ที่อยู่ต่อพระพักตร์พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 1, 'ดูเถิด พระเยโฮวาห์จะทรงทิ้งโลกให้ร้าง และทรงกระทําให้ร้างเปล่า และพระองค์จะทรงคว่ําแผ่นดินโลกและกระจายผู้อาศัยของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 2, 'และจะเป็นอย่างนั้นต่อปุโรหิต อย่างเป็นกับประชาชน ต่อนายของเขา อย่างเป็นกับทาส ต่อนายผู้หญิงของเขา อย่างเป็นกับสาวใช้ ต่อผู้ขาย อย่างเป็นกับผู้ซื้อ ต่อผู้ยืม อย่างเป็นกับผู้ให้ยืม ต่อผู้ให้ยืมโดยคิดดอกเบี้ย อย่างผู้ยืมโดยคิดดอกเบี้ย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 3, 'แผ่นดินนั้นจะถูกทิ้งร้างอย่างสิ้นเชิง และถูกปล้นหมดสิ้น เพราะพระเยโฮวาห์ได้ตรัสพระวจนะนี้แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 4, 'โลกก็ไว้ทุกข์และเหี่ยวแห้งไป พิภพก็อ่อนระทวยและเหี่ยวแห้ง คนสูงศักดิ์ของโลกก็อ่อนระทวยไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 5, 'โลกนี้มีราคีเพราะผู้อาศัยในนั้น เพราะเขาทั้งหลายละเมิดต่อพระราชบัญญัติ ได้ฝ่าฝืนกฎ ได้หักพันธสัญญานิรันดร์นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 6, 'เพราะฉะนั้นคําสาปก็กลืนโลก และผู้ที่อาศัยในนั้นก็โดดเดี่ยว เพราะฉะนั้นผู้อาศัยในแผ่นดินโลกจึงถูกเผาผลาญ มีคนเหลือน้อย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 7, 'น้ําองุ่นใหม่ก็ไว้ทุกข์ เถาองุ่นก็อ่อนระทวย จิตใจที่รื่นเริงทั้งปวงก็ถอนหายใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 8, 'เสียงสนุกสนานของรํามะนาก็เงียบ เสียงของผู้เบิกบานก็หยุดเสีย เสียงสนุกสนานของพิณเขาคู่ก็เงียบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 9, 'เขาจะไม่ดื่มเหล้าองุ่นพร้อมกับการร้องเพลงอีก เมรัยก็จะเป็นของขมแก่ผู้ที่ดื่ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 10, 'เมืองที่จลาจลแตกหักเสียแล้ว บ้านทุกหลังก็ปิดหมด ไม่ให้ใครเข้าไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 11, 'มีเสียงร้องที่กลางถนนด้วยเรื่องเหล้าองุ่น ความชื่นบานทั้งสิ้นก็เยือกเย็นลงแล้ว ความยินดีของแผ่นดินก็สูญหายไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 12, 'มีการรกร้างว่างเปล่าทิ้งไว้ในเมือง ประตูเมืองก็ถูกทุบทําลายเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 13, 'เพราะจะเป็นเช่นนี้อยู่ท่ามกลางแผ่นดิน ท่ามกลางชนชาติทั้งหลาย อย่างกับเมื่อต้นมะกอกเทศถูกเขย่า อย่างเมื่อการเก็บเล็มตามเถาองุ่นสิ้นลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 14, 'เขาทั้งหลายจะเปล่งเสียงของเขาขึ้น เขาจะร้องเพลงฉลองความโอ่อ่าตระการของพระเยโฮวาห์ เขาจะโห่ร้องจากทะเล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 15, 'เพราะฉะนั้นในรุ่งอรุณจงถวายสง่าราศีแด่พระเยโฮวาห์ ในเกาะทั้งหลายแห่งทะเลจงถวายแด่พระนามแห่งพระเยโฮวาห์พระเจ้าของอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 16, 'ตั้งแต่ที่สุดปลายโลกเราได้ยินเสียงเพลงสรรเสริญ ว่าสง่าราศีจงมีแก่ผู้ชอบธรรม แต่ข้าพเจ้าว่า “ข้าพเจ้าก็ผ่ายผอม ข้าพเจ้าก็ผ่ายผอม วิบัติแก่ข้าพเจ้า เพราะคนทรยศประพฤติอย่างทรยศยิ่ง เออ คนทรยศประพฤติอย่างทรยศยิ่ง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 17, 'โอ ชาวแผ่นดินโลกเอ๋ย ความสยดสยองและหลุมพรางและกับก็มาทันเจ้าแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 18, 'ต่อมาผู้ใดหนีเมื่อได้ยินเสียงความสยดสยองนั้น จะตกในหลุมพราง และผู้ที่ปีนออกมาจากหลุมพรางก็จะติดกับ เพราะว่าหน้าต่างของฟ้าสวรรค์ก็ถูกเปิด และรากฐานของแผ่นดินโลกก็หวั่นไหว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 19, 'โลกแตกสลายสิ้นเชิงแล้ว โลกแตกเป็นเสี่ยงๆ โลกถูกเขย่าอย่างรุนแรง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 20, 'โลกก็จะซวนเซไปอย่างคนเมา มันจะแกว่งไปอย่างเพิง การละเมิดของโลกจะหนักอยู่บนมัน และมันจะล้มและจะไม่ลุกอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 21, 'ต่อมาในวันนั้นพระเยโฮวาห์จะทรงลงโทษบริวารของฟ้าสวรรค์ในฟ้าสวรรค์ และบรรดากษัตริย์ของแผ่นดินโลกในแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 22, 'เขาทั้งหลายจะถูกรวบรวมไว้ด้วยกัน ดั่งนักโทษในคุกมืด เขาทั้งหลายจะถูกกักขังไว้ในคุก และต่อมาหลายวันเขาจึงจะถูกลงโทษ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 23, 'แล้วดวงจันทร์จะอดสู และดวงอาทิตย์จะอับอาย เพราะว่าพระเยโฮวาห์จอมโยธาจะทรงราชย์บนภูเขาศิโยนและในเยรูซาเล็ม และสง่าราศีจะปรากฏต่อหน้าพวกผู้ใหญ่ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 1, 'โอ ข้าแต่พระเยโฮวาห์ พระองค์ทรงเป็นพระเจ้าของข้าพระองค์ ข้าพระองค์จะยอพระเกียรติพระองค์ ข้าพระองค์จะสรรเสริญพระนามของพระองค์ เพราะพระองค์ได้ทรงกระทําการมหัศจรรย์ แผนงานที่พระองค์ทรงดําริไว้นานมาแล้วก็สัตย์ซื่อและเป็นความจริง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 2, 'เพราะพระองค์ได้ทรงกระทําให้เมืองเป็นกองขยะ เมืองมีป้อมเป็นที่ปรักหักพัง วังของชนต่างด้าวไม่เป็นเมืองต่อไปอีก จะไม่ก่อสร้างขึ้นอีกเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 3, 'เพราะฉะนั้นประชาชาติที่แข็งแรงจะถวายสง่าราศีแด่พระองค์ หัวเมืองของบรรดาประชาชาติที่ทารุณจะเกรงกลัวพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 4, 'เพราะพระองค์ได้ทรงเป็นที่กําบังเข้มแข็งของคนยากจน ทรงเป็นที่กําบังเข้มแข็งของคนขัดสนเมื่อเขาทุกข์ใจ ทรงเป็นที่ลี้ภัยจากพายุ และเป็นร่มกันความร้อน เมื่อลมของผู้ที่ทารุณก็เหมือนพายุพัดกําแพง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 5, 'เหมือนความร้อนในที่แห้ง พระองค์จะทรงระงับเสียงของคนต่างด้าว ร่มเมฆระงับความร้อนฉันใด กิ่งของผู้ทารุณก็จะถูกตัดลงฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 6, 'บนภูเขานี้พระเยโฮวาห์จอมโยธาจะทรงจัดการเลี้ยงสําหรับบรรดาชนชาติทั้งหลาย เป็นการเลี้ยงด้วยของอ้วนพี เป็นการเลี้ยงด้วยน้ําองุ่นที่ตกตะกอนแล้ว ด้วยของอ้วนพีมีไขมันในกระดูกเต็ม ด้วยน้ําองุ่นตกตะกอนที่กรองแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 7, 'และบนภูเขานี้พระองค์จะทรงทําลายผ้าคลุมหน้าซึ่งคลุมหน้าบรรดาชนชาติทั้งหลาย และม่านซึ่งกางอยู่เหนือบรรดาประชาชาติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 8, 'พระองค์จะทรงกลืนความตายด้วยการมีชัย และองค์พระผู้เป็นเจ้าพระเจ้าจะทรงเช็ดน้ําตาจากหน้าทั้งปวง และพระองค์จะทรงเอาการลบหลู่ชนชาติของพระองค์ไปเสียจากทั่วแผ่นดินโลก เพราะพระเยโฮวาห์ได้ตรัสแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 9, 'ในวันนั้นเขาจะกล่าวกันว่า “ดูเถิด นี่คือพระเจ้าของเราทั้งหลาย เราได้รอคอยพระองค์ เพื่อว่าพระองค์จะทรงช่วยเราให้รอด นี่คือพระเยโฮวาห์ เราได้รอคอยพระองค์ ให้เรายินดีและเปรมปรีดิ์ในความรอดของพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 10, 'เพราะพระหัตถ์ของพระเยโฮวาห์จะพักอยู่บนภูเขานี้ และโมอับจะถูกเหยียบย่ําลงภายใต้พระองค์ เหมือนเหยียบฟางลงในกองขยะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 11, 'และพระองค์จะทรงกางพระหัตถ์ของพระองค์ท่ามกลางพวกเขา ดั่งคนว่ายน้ํากางมือว่ายน้ํา และพระองค์จะทรงให้ความเย่อหยิ่งของเขาต่ําลงพร้อมกับฝีมือชํานาญของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 12, 'ป้อมสูงของกําแพงเมืองของเจ้านั้นพระองค์จะทรงให้ต่ําลง ทรงเหยียดลง และเหวี่ยงลงถึงดิน แม้กระทั่งถึงผงคลี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 1, 'ในวันนั้นเขาจะร้องเพลงนี้ในแผ่นดินยูดาห์ “เรามีเมืองเข้มแข็งเมืองหนึ่ง พระเจ้าจะทรงตั้งความรอดไว้เป็นกําแพงและป้อมปราการ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 2, 'จงเปิดประตูเมืองเถิด เพื่อประชาชาติที่ชอบธรรมซึ่งรักษาความจริงไว้จะได้เข้ามา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 3, 'ใจแน่วแน่ในพระองค์นั้น พระองค์ทรงรักษาไว้ในสันติภาพอันสมบูรณ์ เพราะเขาวางใจในพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 4, 'จงวางใจในพระเยโฮวาห์เป็นนิตย์ เพราะพระเยโฮวาห์คือพระเยโฮวาห์ทรงเป็นพระกําลังนิรันดร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 5, 'เพราะพระองค์ทรงให้ชาวเมืองที่สูงส่งนั้น คือเมืองที่สูงส่งนั้นต่ําลง พระองค์ทรงให้มันต่ําลง พระองค์ทรงให้มันต่ําลง ต่ําลงถึงดิน พระองค์ทรงให้มันลงที่ผงคลี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 6, 'เท้าเหยียบมัน คือเท้าของคนยากจน คือย่างเท้าของคนขัดสน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 7, 'หนทางของคนชอบธรรมก็ราบเรียบ พระองค์ผู้เที่ยงธรรมทรงกระทําให้วิถีของคนชอบธรรมราบรื่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 8, 'โอ ข้าแต่พระเยโฮวาห์ ข้าพระองค์ทั้งหลายรอคอยพระองค์อยู่ ในวิถีแห่งคําตัดสินของพระองค์ พระนามอันเป็นที่ระลึกของพระองค์ เป็นที่จิตวิญญาณของข้าพระองค์ปรารถนา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 9, 'จิตใจของข้าพระองค์อยากได้พระองค์ในกลางคืน จิตวิญญาณภายในข้าพระองค์แสวงหาพระองค์อย่างร้อนรน เพราะเมื่อคําตัดสินของพระองค์อยู่ในแผ่นดินโลก ชาวพิภพจะได้เรียนรู้ถึงความชอบธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 10, 'ถ้าสําแดงพระคุณแก่คนชั่ว เขาก็จะไม่เรียนรู้ความชอบธรรม เขาจะประพฤติอย่างอยุติธรรมในแผ่นดินที่เที่ยงธรรม และจะมองไม่เห็นความโอ่อ่าตระการของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 11, 'ข้าแต่พระเยโฮวาห์ เมื่อพระหัตถ์ของพระองค์ชูขึ้น เขาก็จะมองไม่เห็น แต่เขาจะมองเห็น และจะได้อับอาย เพราะเขามีความอิจฉาต่อชนชาติของพระองค์ เออ ไฟแห่งส่วนปฏิปักษ์ของพระองค์จะเผาผลาญเขาเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 12, 'ข้าแต่พระเยโฮวาห์ พระองค์จะสถาปนาสันติภาพเพื่อข้าพระองค์ทั้งหลาย เพราะพระองค์ได้ทรงกระทําบรรดากิจการของพระองค์เพื่อข้าพระองค์เช่นเดียวกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 13, 'โอ ข้าแต่พระเยโฮวาห์พระเจ้าของข้าพระองค์ เจ้านายอื่นนอกเหนือพระองค์ได้ครอบครองพวกข้าพระองค์ แต่ข้าพระองค์จะกล่าวถึงพระนามของพระองค์เท่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 14, 'เขาทั้งหลายตายแล้ว เขาจะไม่มีชีวิตอีก เขาเป็นชาวแดนคนตาย เขาจะไม่เป็นขึ้นอีก เพราะฉะนั้นพระองค์ได้ทรงเยี่ยมเยียนและทรงทําลายเขา และทรงกวาดความระลึกถึงเขาทั้งสิ้นเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 15, 'โอ ข้าแต่พระเยโฮวาห์ แต่พระองค์ทรงเพิ่มประชาชนขึ้น พระองค์ทรงเพิ่มประชาชนขึ้น พระองค์ได้ทรงรับสง่าราศี พระองค์ทรงขยายเขตแดนของแผ่นดินไกลไปถึงที่สุดปลายแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 16, 'ข้าแต่พระเยโฮวาห์ ในยามทุกข์ใจเขาได้แสวงหาพระองค์ เขาทั้งหลายหลั่งคําอธิษฐานออกมาในเมื่อการตีสอนอยู่เหนือเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 17, 'ดั่งหญิงมีครรภ์ เมื่อใกล้ถึงกําหนดเวลาคลอด ก็เจ็บปวดและร้องออกมาด้วยความเจ็บปวดรวดร้าวอย่างฉับพลัน โอ ข้าแต่พระเยโฮวาห์ ข้าพระองค์ทั้งหลายก็เป็นเช่นนั้นในสายพระเนตรของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 18, 'ข้าพระองค์มีครรภ์ ข้าพระองค์บิดตัว เป็นเหมือนข้าพระองค์คลอดลม ข้าพระองค์มิได้ทําการช่วยให้พ้นในแผ่นดินโลก และชาวพิภพมิได้ล้มลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 19, 'คนตายของพระองค์จะมีชีวิต ศพของเขาทั้งหลายจะลุกขึ้นพร้อมกับศพของข้าพระองค์ ผู้อาศัยอยู่ในผงคลีเอ๋ย จงตื่นเถิดและร้องเพลง เพราะน้ําค้างของเจ้าเป็นเหมือนน้ําค้างบนผัก และแผ่นดินโลกจะให้ชาวแดนคนตายเป็นขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 20, 'มาเถิด ชนชาติของข้าพเจ้าเอ๋ย จงเข้าในห้องของเจ้าและปิดประตูเสีย จงซ่อนตัวเจ้าอยู่สักพักหนึ่ง จนกว่าพระพิโรธจะผ่านไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 21, 'เพราะ ดูเถิด พระเยโฮวาห์กําลังเสด็จออกมาจากสถานที่ของพระองค์ เพื่อลงโทษชาวแผ่นดินโลก เพราะความชั่วช้าของเขาทั้งหลาย และแผ่นดินโลกจะเปิดเผยโลหิตซึ่งหลั่งอยู่บนมัน และจะไม่ปิดบังผู้ถูกฆ่าของมันไว้อีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 1, 'ในวันนั้น พระเยโฮวาห์จะทรงลงโทษด้วยพระแสงอันร้ายกาจ ยิ่งใหญ่ และแข็งแกร่งของพระองค์ต่อเลวีอาธาน ซึ่งเป็นพญานาคที่ฉกกัด คือเลวีอาธานพญานาคที่ขด และพระองค์จะทรงประหารมังกรที่อยู่ในทะเล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 2, 'ในวันนั้น จงร้องเพลงถึงเธอว่า “สวนองุ่นแห่งน้ําองุ่นสีแดง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 3, 'เราคือพระเยโฮวาห์ เป็นผู้รักษาดูแลมัน เราจะรดน้ํามันอยู่ทุกขณะ เกรงว่าผู้หนึ่งผู้ใดจะทําอันตรายมัน เราจะรักษามันไว้ทั้งกลางคืนและกลางวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 4, 'เราไม่มีความพิโรธ ใครเล่าจะให้มีหนามย่อยหนามใหญ่ขึ้นมาสู้รบกับเรา เราจะออกรบกับมัน เราจะเผามันเสียด้วยกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 5, 'หรือให้เขาเกาะอยู่กับกําลังของเราเพื่อให้เขาทําสันติภาพกับเรา แล้วเขาจะทําสันติภาพกับเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 6, 'พระองค์จะทรงกระทําให้คนที่ออกมาจากยาโคบหยั่งราก อิสราเอลจะผลิดอกและแตกหน่อ กระทําให้พื้นพิภพทั้งสิ้นมีผลเต็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 7, 'พระองค์ทรงโบยตีเขาอย่างที่พระองค์โบยตีเขาทั้งหลายที่โบยตีเขาหรือ หรือเขาถูกฆ่าอย่างคนทั้งหลายที่ถูกเขาฆ่าแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 8, 'ด้วยการขับไล่ ด้วยการกวาดไปเป็นเชลย พระองค์ทรงต่อสู้แย้งกับเขา พระองค์ทรงกวาดเขาไปด้วยลมดุเดือดของพระองค์ในวันแห่งลมตะวันออก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 9, 'เพราะฉะนั้นจะลบความชั่วช้าของยาโคบอย่างนี้แหละ และนี่เป็นผลเต็มขนาดในการปลดบาปของเขา คือเมื่อเขาทําศิลาทั้งสิ้นของแท่นบูชาให้เป็นเหมือนหินดินสอพองที่ถูกบดเป็นชิ้นๆ จะไม่มีเสารูปเคารพ หรือรูปเคารพตั้งอยู่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 10, 'เพราะเมืองหน้าด่านก็จะรกร้าง ที่อาศัยก็ถูกละทิ้งและทอดทิ้งอย่างกับถิ่นทุรกันดาร ลูกวัวจะหากินอยู่ที่นั่น มันจะนอนลงที่นั่นและกินกิ่งไม้ในที่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 11, 'เมื่อกิ่งนั้นแห้ง มันก็จะถูกหัก พวกผู้หญิงก็มาเอามันไปก่อไฟ เพราะนี่เป็นชนชาติที่ไร้ความเข้าใจ เพราะฉะนั้นผู้ที่ทรงสร้างเขาก็จะไม่สงสารเขา ผู้ที่ทรงปั้นเขาจะไม่ทรงสําแดงพระคุณแก่เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 12, 'ต่อมาในวันนั้น พระเยโฮวาห์จะทรงนวดเอาข้าวตั้งแต่แม่น้ําไปจนถึงลําธารอียิปต์ โอ ประชาชนอิสราเอลเอ๋ย เจ้าจะถูกเก็บรวมเข้ามาทีละคนๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 13, 'และอยู่มาในวันนั้นเขาจะเป่าแตรใหญ่ และบรรดาผู้ที่กําลังพินาศอยู่ในแผ่นดินอัสซีเรีย และบรรดาผู้ถูกขับไล่ออกไปยังแผ่นดินอียิปต์จะมานมัสการพระเยโฮวาห์ บนภูเขาบริสุทธิ์ที่เยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 1, 'วิบัติแก่มงกุฎอันโอ่อ่า แก่คนขี้เมาแห่งเอฟราอิม ซึ่งความงามอันรุ่งเรืองของเขาเหมือนดอกไม้ที่กําลังร่วงโรย ซึ่งอยู่บนยอดเขาในที่ลุ่มอันอุดมของบรรดาผู้ที่เหล้าองุ่นมีชัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 2, 'ดูเถิด องค์พระผู้เป็นเจ้าทรงมีผู้หนึ่งที่มีกําลังและแข็งแรง เหมือนพายุลูกเห็บ อันเป็นพายุทําลาย เหมือนพายุน้ําที่กําลังไหลท่วม ซึ่งจะเหวี่ยงลงถึงดินด้วยพระหัตถ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 3, 'มงกุฎอันโอ่อ่า คือคนขี้เมาแห่งเอฟราอิม จะถูกเหยียบอยู่ใต้เท้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 4, 'และความงามอันรุ่งโรจน์ของเขา ซึ่งอยู่บนยอดเขาในที่ลุ่มอันอุดม จะเป็นดอกไม้ที่กําลังร่วงโรย จะเป็นเหมือนผลที่แรกสุกก่อนฤดูร้อน เมื่อคนเห็นเข้าก็กินมันเสียพอถึงมือเขาเท่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 5, 'ในวันนั้น พระเยโฮวาห์จอมโยธา จะเป็นมงกุฎแห่งสง่าราศี และเป็นมงกุฎแห่งความงาม แก่คนที่เหลืออยู่แห่งชนชาติของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 6, 'และเป็นวิญญาณแห่งความยุติธรรมแก่เขาผู้นั่งพิพากษา และเป็นกําลังของผู้เหล่านั้นผู้หันการสงครามกลับเสียที่ประตูเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 7, 'เขาเหล่านี้ซมซานไปด้วยเหล้าองุ่นเหมือนกัน และโซเซไปด้วยเมรัย ปุโรหิตและผู้พยากรณ์ก็ซมซานไปด้วยเมรัย เขาทั้งหลายถูกกลืนไปหมดด้วยเหล้าองุ่น เขาโซเซไปด้วยเมรัย เขาเห็นผิดไป เขาสะดุดในการให้คําพิพากษา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 8, 'เพราะสํารับทุกสํารับก็มีอาเจียนและความโสโครกเต็ม ไม่มีที่ใดที่สะอาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 9, 'เขาจะสอนความรู้ให้แก่ใคร เขาจะให้ผู้ใดเข้าใจหลักคําสอน ให้แก่คนเหล่านั้นที่หย่านมหรือ หรือให้แก่คนเอามาจากอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 10, 'เพราะเป็นข้อบังคับซ้อนข้อบังคับ ข้อบังคับซ้อนข้อบังคับ บรรทัดซ้อนบรรทัด บรรทัดซ้อนบรรทัด ที่นี่นิด ที่นั่นหน่อย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 11, 'เปล่า แต่พระองค์จะตรัสกับชนชาตินี้โดยต่างภาษาและโดยริมฝีปากของคนต่างด้าว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 12, 'คือแก่บรรดาผู้ที่พระองค์ตรัสว่า “นี่คือการหยุดพัก จงให้การหยุดพักแก่คนเหน็ดเหนื่อย และนี่คือการพักผ่อน” ถึงกระนั้นเขาก็จะไม่ฟัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 13, 'เพราะฉะนั้นพระวจนะของพระเยโฮวาห์จึงเป็นอย่างนี้แก่เขา เป็นข้อบังคับซ้อนข้อบังคับ ข้อบังคับซ้อนข้อบังคับ เป็นบรรทัดซ้อนบรรทัด บรรทัดซ้อนบรรทัด ที่นี่นิด ที่นั่นหน่อย เพื่อเขาจะไปและถอยหลัง และจะแตก และจะติดบ่วงและจะถูกจับไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 14, 'เพราะฉะนั้นเจ้าทั้งหลายคนมักเยาะเย้ยเอ๋ย จงฟังพระวจนะของพระเยโฮวาห์ คือเจ้าผู้ปกครองชนชาตินี้ในเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 15, 'เพราะเจ้าทั้งหลายได้กล่าวแล้วว่า “เราได้กระทําพันธสัญญาไว้กับความตาย และเราทําความตกลงไว้กับนรก เมื่อภัยพิบัติอันท่วมท้นผ่านไป จะไม่มาถึงเรา เพราะเราทําให้ความเท็จเป็นที่ลี้ภัยของเรา และเราได้กําบังอยู่ในความมุสา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 16, 'เพราะฉะนั้นองค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า “ดูเถิด เราวางศิลาไว้ในศิโยนเพื่อเป็นรากฐาน คือศิลาที่ทดสอบแล้ว เป็นศิลามุมเอกอย่างประเสริฐ เป็นรากฐานอันมั่นคง เขาผู้นั้นที่เชื่อจะไม่รีบร้อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 17, 'และเราจะกระทําความยุติธรรมให้เป็นเชือกวัด และความชอบธรรมให้เป็นลูกดิ่ง และลูกเห็บจะกวาดเอาความเท็จอันเป็นที่ลี้ภัยไปเสีย และน้ําจะท่วมท้นที่กําบัง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 18, 'แล้วพันธสัญญาของเจ้ากับความตายจะเป็นโมฆะ และข้อตกลงของเจ้ากับนรกจะไม่ดํารง เมื่อภัยพิบัติอันท่วมท้นผ่านไป เจ้าจะถูกเหยียบย่ําลงด้วยโทษนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 19, 'มันผ่านไปบ่อยเท่าใด มันก็จะเอาตัวเจ้า เพราะมันจะผ่านไปเช้าแล้วเช้าเล่า ทั้งกลางวันและกลางคืน เมื่อเข้าใจข่าว ก็จะเกิดแต่ความสยดสยองเท่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 20, 'เพราะที่นอนนั้นสั้นเกินที่คนหนึ่งคนใดจะเหยียดอยู่บนนั้น และผ้าห่มก็แคบไม่พอคลุมตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 21, 'เพราะว่าพระเยโฮวาห์จะทรงลุกขึ้นอย่างที่บนภูเขาเปริซิม พระองค์จะพระพิโรธอย่างที่ในหุบเขากิเบโอน เพื่อกระทําพระราชกิจของพระองค์ พระราชกิจของพระองค์นั้นประหลาด และเพื่อกระทํางานของพระองค์ งานของพระองค์ก็แปลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 22, 'เพราะฉะนั้นบัดนี้อย่าเป็นคนเยาะเย้ย เกลือกว่าพันธะของเจ้าจะเข้มงวดขึ้น เพราะข้าพเจ้าได้ยินกฤษฎีกากําหนดการทําลายเหนือแผ่นดินทั้งสิ้นแล้ว จากองค์พระผู้เป็นเจ้าพระเจ้าจอมโยธา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 23, 'เงี่ยหูลงซิ และฟังเสียงข้าพเจ้า สดับซี และฟังคําพูดของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 24, 'เขาผู้ไถนาเพื่อหว่าน ไถอยู่เสมอหรือ เขาเบิกดินและคราดอยู่เป็นนิตย์หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 25, 'เมื่อเขาปราบผิวลงแล้ว เขาไม่หว่านเทียนแดงและยี่หร่า เขาไม่ใส่ข้าวสาลีเป็นแถว และข้าวบาร์เลย์ในที่อันเหมาะของมัน และหว่านข้าวไรไว้เป็นคันแดนหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 26, 'เพราะพระเจ้าของเขาทรงสั่งสอนเขาถูกต้อง พระองค์ได้สอนเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 27, 'เขาไม่นวดเทียนแดงด้วยเลื่อนนวดข้าว และเขาไม่เอาล้อเกวียนกลิ้งทับยี่หร่า แต่เขาเอาไม้พลองตีเทียนแดงให้หลุดออก และเอาตะบองตียี่หร่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 28, 'คนใดบดข้าวที่ทําขนมปังหรือ เปล่าเลย เขาไม่นวดมันเป็นนิตย์ เมื่อเขาขับล้อเกวียนเทียมม้าทับมันแล้ว เขามิได้บดมันด้วยคนขี่ม้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 29, 'เรื่องนี้มาจากพระเยโฮวาห์จอมโยธาด้วย พระองค์มหัศจรรย์นักในการปรึกษา และวิเศษในเรื่องการกระทํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 1, 'วิบัติแก่อารีเอล อารีเอล นครซึ่งดาวิดทรงตั้งค่าย จงเพิ่มปีเข้ากับปี จงให้มีเทศกาลถวายเครื่องบูชาตามรอบของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 2, 'เรายังจะให้อารีเอลทุกข์ใจ จะมีการร้องคร่ําครวญและร้องทุกข์ และเมืองนั้นจะเป็นเหมือนอารีเอลแก่เรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 3, 'และเราจะตั้งค่ายอยู่รอบเจ้า และเราจะล้อมเจ้ากับบรรดาหอรบ และเราจะยกเชิงเทินขึ้นสู้เจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 4, 'และเจ้าจะถูกเหยียบลง เจ้าจะพูดมาจากที่ลึกของแผ่นดินโลก คําของเจ้าจะมาจากที่ต่ําลงในผงคลี เสียงของเจ้าจะมาจากพื้นดินเหมือนเสียงผี และคําพูดของเจ้าจะกระซิบออกมาจากผงคลี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 5, 'แต่มวลชาวต่างประเทศของเจ้าจะเหมือนผงคลีละเอียด และผู้น่ากลัวทั้งมวลจะเหมือนแกลบที่ฟุ้งหายไป เออ ชั่วประเดี๋ยวเดียวและในทันทีทันใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 6, 'พระเยโฮวาห์จอมโยธาจะทรงเยี่ยมเยียนเจ้าด้วยฟ้าร้องและด้วยแผ่นดินไหว และด้วยเสียงกัมปนาท ด้วยพายุและพายุแรงกล้า ด้วยเปลวแห่งเพลิงเผาผลาญ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 7, 'และมวลประชาชาติทั้งสิ้นที่ต่อสู้กับอารีเอล ทั้งหมดที่ต่อสู้กับเขาและกับที่กําบังเข้มแข็งของเขาและทําให้เขาทุกข์ใจ จะเป็นเหมือนความฝันคือนิมิตในกลางคืน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 8, 'อย่างเมื่อคนหิวฝันว่า ดูเถิด เขากําลังกินอยู่ และตื่นขึ้นก็ยังหิวอยู่ จิตใจเขาไม่อิ่ม หรือเหมือนเมื่อคนกระหายฝันว่า ดูเถิด เขากําลังดื่มอยู่ แล้วตื่นขึ้นมา ดูเถิด อ่อนเปลี้ย จิตใจของเขายังแห้งผาก มวลประชาชาติทั้งสิ้นที่ต่อสู้กับภูเขาศิโยนก็จะเป็นเช่นนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 9, 'จงรั้งรอและงงงวย จงร้องเรียกและร้องไห้ เขามึนเมา แต่ไม่ใช่ด้วยเหล้าองุ่น เขาโซเซ แต่ไม่ใช่ด้วยเมรัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 10, 'เพราะว่าพระเยโฮวาห์ทรงเทวิญญาณแห่งความหลับสนิทลงเหนือเจ้า และปิดตาของเจ้า และพระองค์ทรงคลุมตาของพวกผู้พยากรณ์ พวกเจ้านายและพวกผู้ทํานายของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 11, 'และแก่ท่านทั้งหลาย นิมิตนี้ทั้งสิ้นได้กลายเป็นเหมือนถ้อยคําในหนังสือที่ประทับตรา เมื่อคนให้แก่คนหนึ่งที่อ่านได้ กล่าวว่า “อ่านนี่ซี” เขาว่า “ข้าอ่านไม่ได้เพราะมีตราประทับ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 12, 'และเมื่อเขาให้หนังสือแก่คนหนึ่งที่อ่านไม่ได้ กล่าวว่า “อ่านนี่ซี” เขาว่า “ข้าไม่รู้หนังสือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 13, 'และองค์พระผู้เป็นเจ้าตรัสว่า “เพราะชนชาตินี้เข้ามาใกล้เราด้วยปากของเขา และให้เกียรติเราด้วยริมฝีปากของเขา แต่เขาให้จิตใจของเขาห่างไกลจากเรา เขายําเกรงเราเพียงแต่เหมือนเป็นข้อบังคับของมนุษย์ที่สอนกันมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 14, 'เพราะฉะนั้น ดูเถิด เราจะกระทําสิ่งมหัศจรรย์กับชนชาตินี้ อีกทั้งการประหลาดและอัศจรรย์ สติปัญญาของคนมีปัญญาของเขาจะพินาศไป และความเข้าใจของคนที่เข้าใจจะถูกปิดบังไว้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 15, 'วิบัติแก่ผู้ที่พยายามซ่อนแผนงานของเขาไว้ลึกจากพระเยโฮวาห์ ซึ่งการกระทําของเขาอยู่ในความมืด ผู้ซึ่งกล่าวว่า “ใครเห็นเรา ใครจําเราได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 16, 'แน่นอนความวิปริตของเจ้าจะถือว่าช่างปั้นเท่ากับดินเหนียว และสิ่งที่ถูกสร้างจะพูดเรื่องผู้สร้างมันว่า “เขาไม่ได้สร้างข้า” หรือสิ่งที่ถูกปั้นขึ้นจะพูดเรื่องผู้ปั้นมันว่า “เขาไม่มีความเข้าใจอะไรเลย” อย่างนี้หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 17, 'ไม่ใช่อีกนิดหน่อยเท่านั้นหรือ ที่เลบานอนจะถูกเปลี่ยนให้เป็นสวนผลไม้ และสวนผลไม้จะถือว่าเป็นป่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 18, 'ในวันนั้นคนหูหนวกจะได้ยินถ้อยคําของหนังสือ และตาของคนตาบอดจะเห็นออกมาจากความคลุ้มและความมืดของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 19, 'คนใจอ่อนสุภาพจะได้ความชื่นบานสดใสในพระเยโฮวาห์เพิ่มขึ้น และคนยากจนท่ามกลางมนุษย์จะเริงโลดในองค์บริสุทธิ์แห่งอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 20, 'เพราะว่าผู้น่ากลัวจะสูญไป และผู้เยาะเย้ยจะถูกผลาญไป และคนทั้งปวงที่เฝ้ารอคอยที่จะกระทําการอันชั่วช้าจะถูกตัดขาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 21, 'คือผู้ที่ใส่ความคนอื่นด้วยถ้อยคําของเขา และวางบ่วงไว้ดักเขาผู้กล่าวคําขนาบที่ประตูเมือง และด้วยถ้อยคําที่ไม่เป็นแก่นสาร เขากีดกันคนชอบธรรมเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 22, 'เพราะฉะนั้นพระเยโฮวาห์ผู้ทรงไถ่อับราฮัม ตรัสดังนี้เกี่ยวกับวงศ์วานของยาโคบว่า “ยาโคบจะไม่ต้องอับอายอีก หน้าของเขาจะไม่ซีดลงอีกต่อไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 23, 'เพราะเมื่อเขาเห็นลูกหลานของเขาซึ่งเป็นผลงานแห่งมือของเราในหมู่พวกเขา เขาทั้งหลายจะถือว่านามของเราบริสุทธิ์ เขาทั้งหลายจะถือว่าองค์บริสุทธิ์ของยาโคบบริสุทธิ์ และจะกลัวเกรงพระเจ้าแห่งอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 24, 'และบรรดาผู้ที่ผิดฝ่ายจิตใจจะมาถึงความเข้าใจ และบรรดาผู้ที่บ่นพึมพําจะยอมเรียนรู้หลักคําสอน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 1, 'พระเยโฮวาห์ตรัสว่า “วิบัติแก่ลูกหลานที่ดื้อดึง ผู้กระทําแผนงาน แต่ไม่ใช่ของเรา ผู้ปกคลุมด้วยเครื่องปกปิด แต่ไม่ใช่ตามพระวิญญาณของเรา เขาจะเพิ่มบาปซ้อนบาป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 2, 'ผู้ออกเดินลงไปยังอียิปต์ โดยไม่ขอคําปรึกษาจากปากของเรา เพื่อจะเข้มแข็งในการลี้ภัยกับฟาโรห์ เพื่อจะวางใจในร่มเงาของอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 3, 'เพราะฉะนั้นการลี้ภัยกับฟาโรห์จะกลับเป็นความอับอายของเจ้า และการวางใจในร่มเงาของอียิปต์จะกลับเป็นที่ขายหน้าของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 4, 'เพราะแม้ว่าข้าราชการของเขาอยู่ที่โศอัน และทูตของเขาไปถึงฮาเนส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 5, 'ทุกคนได้รับความอับอายโดยชนชาติหนึ่งซึ่งช่วยเขาไม่ได้ ซึ่งมิได้นําความช่วยเหลือหรือประโยชน์มาให้ ได้แต่ความอับอายและความขายหน้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 6, 'ภาระเรื่องสัตว์ป่าแห่งภาคใต้ เขาทั้งหลายบรรทุกทรัพย์สมบัติของเขาบนหลังลาและบรรทุกทรัพย์สินของเขาบนโหนกอูฐ ไปตลอดแผ่นดินแห่งความยากลําบากแสนระทม ที่ซึ่งสิงโตหนุ่มและสิงโตแก่ งูร้าย และงูแมวเซาออกมา ไปยังชนชาติหนึ่งซึ่งจะช่วยเขาไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 7, 'เพราะความช่วยเหลือของอียิปต์นั้นไร้ค่าและเปล่าประโยชน์ เพราะฉะนั้น เราจึงเรียกเขาว่า “ความเข้มแข็งของเขาคือให้นั่งเฉยเมย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 8, 'บัดนี้ ไปเถอะ เขียนลงไว้บนแผ่นจารึกต่อหน้าเขา และจดไว้ในหนังสือเพื่อในเวลาที่จะมาถึง จะเป็นสักขีพยานเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 9, 'เพราะว่าเขาทั้งหลายเป็นชนชาติดื้อดึง เป็นลูกขี้ปด เป็นหลานที่ไม่ยอมฟังพระราชบัญญัติของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 10, 'ซึ่งกล่าวแก่พวกผู้ทํานายว่า “อย่าเห็นเลย” และแก่ผู้พยากรณ์ว่า “อย่าพยากรณ์สิ่งที่ถูกต้องแก่เราเลย จงพูดสิ่งราบรื่นแก่เรา จงพยากรณ์มายา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 11, 'ออกจากทางเสีย หันเสียจากวิถี ให้องค์บริสุทธิ์ของอิสราเอลพ้นหน้าพ้นตาของเราเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 12, 'เพราะฉะนั้นองค์บริสุทธิ์ของอิสราเอลตรัสดังนี้ว่า “เพราะเจ้าดูหมิ่นถ้อยคํานี้ และวางใจในการบีบบังคับและการทุจริต และพึ่งอาศัยสิ่งเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 13, 'เพราะฉะนั้นความชั่วช้านี้จะเป็นแก่เจ้าเหมือนกําแพงสูงแยกออกโผล่ออกไปกําลังจะพัง ซึ่งจะพังอย่างปัจจุบันทันด่วนในพริบตาเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 14, 'พระองค์จะทรงกระทําให้แตกเหมือนภาชนะของช่างหม้อแตก ซึ่งแตกเป็นชิ้นๆอย่างไม่ปรานี ชิ้นที่แตกนั้นไม่พบชิ้นดีพอที่จะตักไฟออกจากเตา หรือใช้ตักน้ําออกจากบ่อเก็บน้ํา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 15, 'เพราะองค์พระผู้เป็นเจ้าพระเจ้า องค์บริสุทธิ์แห่งอิสราเอลตรัสดังนี้ว่า “ในการกลับและหยุดพัก เจ้าทั้งหลายจะรอด กําลังของเจ้าจะอยู่ในความสงบและความไว้วางใจ” และเจ้าก็ไม่ยอมทําตาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 16, 'แต่เจ้าทั้งหลายว่า “อย่าเลย เราจะขี่ม้าหนีไป” เพราะฉะนั้นเจ้าก็จะหนีไป และ “เราจะขี่ม้าเร็วจัด” เพราะฉะนั้นผู้ไล่ตามเจ้าทั้งหลายจะเร็วจัด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 17, 'คนพันหนึ่งจะหนีเพราะคําขู่เข็ญของคนคนเดียว เจ้าทั้งหลายจะหนีเพราะคําขู่เข็ญของคนห้าคน จนจะเหลือแต่เจ้าเหมือนเสาธงบนยอดภูเขา เหมือนอาณัติสัญญาณบนเนิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 18, 'เพราะฉะนั้นพระเยโฮวาห์ทรงคอยที่จะทรงพระกรุณาเจ้าทั้งหลาย เพราะฉะนั้นพระองค์จึงทรงเป็นที่ยกย่องเพื่อจะเมตตาเจ้า เพราะพระเยโฮวาห์เป็นพระเจ้าแห่งความยุติธรรม บรรดาผู้ที่คอยท่าพระองค์จะได้รับพระพร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 19, 'เพราะประชาชนจะอาศัยในศิโยน ณ เยรูซาเล็ม เจ้าจะไม่ร้องไห้อีกต่อไป เมื่อได้ยินเสียงเจ้าร้องทูล พระองค์จะทรงเมตตาต่อเจ้า เมื่อพระองค์ทรงได้ยิน พระองค์จะทรงตอบเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 20, 'และถึงแม้องค์พระผู้เป็นเจ้าประทานอาหารแห่งความยากลําบาก และน้ําแห่งความทุกข์ใจให้แก่เจ้า ถึงกระนั้นครูทั้งหลายของเจ้าจะไม่ซ่อนตัวในมุมอีกเลย แต่ตาของเจ้าจะเห็นครูของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 21, 'และเมื่อเจ้าหันไปทางขวาหรือหันไปทางซ้าย หูของเจ้าจะได้ยินวจนะข้างหลังเจ้าว่า “นี่เป็นหนทาง จงเดินในทางนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 22, 'แล้วเจ้าจะทําลายรูปเคารพสลักอาบเงินของเจ้า และรูปเคารพหล่อชุบทองคําของเจ้า เจ้าจะกระจายมันไปอย่างผ้าอนามัย และเจ้าจะกล่าวแก่มันว่า “ไปให้พ้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 23, 'และพระองค์จะประทานฝนให้แก่เมล็ดพืชซึ่งเจ้าหว่านลงที่ดิน และประทานข้าวซึ่งเป็นผลิตผลของดิน และข้าวจะอุดมและสมบูรณ์ ในวันนั้นวัวของเจ้าจะกินอยู่ในลานหญ้าใหญ่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 24, 'และวัวกับลาที่ใช้ทํานาจะกินข้าวใส่เกลือ ซึ่งใช้พลั่วและส้อมซัด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 25, 'และบนภูเขาสูงทุกแห่ง และบนเนินสูงทุกแห่งจะมีแม่น้ําลําธารที่มีน้ําไหลในวันที่มีการประหัตประหารอย่างยิ่งใหญ่ เมื่อหอคอยพังลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 26, 'ยิ่งกว่านั้นอีก แสงสว่างของดวงจันทร์จะเหมือนแสงสว่างของดวงอาทิตย์ และแสงสว่างของดวงอาทิตย์จะเป็นเจ็ดเท่า และเป็นอย่างแสงสว่างของเจ็ดวัน ในวันที่พระเยโฮวาห์ทรงพันรอยบาดเจ็บแห่งชนชาติของพระองค์ และรักษาบาดแผลซึ่งเขาถูกพระองค์ทรงตีนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 27, 'ดูเถิด พระนามของพระเยโฮวาห์มาจากที่ไกล ร้อนด้วยความกริ้วของพระองค์ ภาระนั้นก็หนักหนา ริมพระโอษฐ์ของพระองค์เต็มด้วยความกริ้ว และพระชิวหาของพระองค์เหมือนไฟเผาผลาญ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 28, 'พระปัสสาสะของพระองค์เหมือนลําธารท่วมท้น ที่ท่วมถึงกลางคอ เพื่อจะร่อนบรรดาประชาชาติด้วยตะแกรงแห่งความไร้สาระ และจะมีบังเหียนซึ่งพาให้หลงไปที่ขากรรไกรของชนชาติทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 29, 'เจ้าจะมีบทเพลงอย่างคืนที่มีเทศกาลศักดิ์สิทธิ์ และมีใจยินดี อย่างคนที่ออกเดินตามเสียงปี่ เพื่อไปยังภูเขาของพระเยโฮวาห์ ถึงผู้ทรงมหิทธิฤทธิ์ของอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 30, 'และพระเยโฮวาห์จะทรงกระทําให้พระสุรเสียงกัมปนาทของพระองค์เป็นที่ได้ยิน และจะทรงให้เห็นพระกรฟาดลงของพระองค์ ด้วยความกริ้วอย่างเกรี้ยวกราด และเปลวแห่งเพลิงเผาผลาญ พร้อมกับฝนกระหน่ําและพายุ และลูกเห็บ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 31, 'คนอัสซีเรียจะสยดสยองด้วยพระสุรเสียงของพระเยโฮวาห์ พระองค์ทรงโบยตีด้วยพระคทาของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 32, 'และจังหวะไม้เรียวลงโทษทุกจังหวะซึ่งพระเยโฮวาห์โบยลงเหนือเขาจะเข้ากับเสียงรํามะนาและพิณเขาคู่ พระองค์จะทรงต่อสู้เขาด้วยสงครามฟาดฟัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 33, 'เพราะโทเฟทก็จัดไว้นานแล้ว เออ เตรียมไว้สําหรับกษัตริย์ เชิงตะกอนก็ลึกและกว้าง พร้อมไฟและฟืนมากมาย คือพระปัสสาสะของพระเยโฮวาห์เหมือนธารกํามะถันมาจุดให้ลุก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 1, 'วิบัติแก่คนเหล่านั้นผู้ลงไปที่อียิปต์เพื่อขอความช่วยเหลือ และหมายพึ่งม้า ผู้ที่วางใจในรถรบเพราะมีมาก และวางใจในพลม้า เพราะเขาทั้งหลายแข็งแรงนัก แต่มิได้หมายพึ่งองค์บริสุทธิ์ของอิสราเอล หรือแสวงหาพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 2, 'แต่ถึงกระนั้น พระองค์ยังทรงเฉลียวฉลาดและจะนําภัยพิบัติมาให้ พระองค์จะมิได้ทรงเรียกพระวจนะของพระองค์คืนมา แต่จะทรงลุกขึ้นต่อสู้กับวงศ์วานผู้กระทําความผิด และต่อสู้กับผู้ช่วยเหลือของคนเหล่านั้นที่กระทําความชั่วช้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 3, 'คนอียิปต์เป็นคน และไม่ใช่พระเจ้า และม้าทั้งหลายของเขาเป็นเนื้อหนัง และไม่ใช่วิญญาณ เมื่อพระเยโฮวาห์จะทรงเหยียดพระหัตถ์ของพระองค์ออก ทั้งผู้ช่วยเหลือก็จะสะดุด และผู้ที่รับการช่วยเหลือก็จะล้ม และเขาทั้งหลายจะล้มเหลวด้วยกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 4, 'เพราะพระเยโฮวาห์ตรัสกับข้าพเจ้าดังนี้ว่า “ดังสิงโตหรือสิงโตหนุ่มคํารามอยู่เหนือเหยื่อของมัน และเมื่อเขาเรียกผู้เลี้ยงแกะหมู่หนึ่งมาสู้มัน มันจะไม่คร้ามกลัวต่อเสียงของเขาทั้งหลาย หรือย่อย่นต่อเสียงอึงคะนึงของเขา ดั่งนั้นแหละพระเยโฮวาห์จอมโยธาจะเสด็จลงมาเพื่อสู้รบเพื่อภูเขาศิโยนและเพื่อเนินเขาของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 5, 'เหมือนนกบินร่อนอยู่ ดั่งนั้นแหละพระเยโฮวาห์จอมโยธาจะทรงป้องกันเยรูซาเล็ม พระองค์จะทรงป้องกันและช่วยให้พ้น พระองค์จะทรงเว้นเสีย และสงวนชีวิตไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 6, 'จงกลับมาหาพระองค์ผู้ที่ประชาชนอิสราเอลได้กบฏอย่างร้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 7, 'เพราะในวันนั้น ทุกคนจะทิ้งรูปเคารพของตนที่ทําด้วยเงิน และรูปเคารพของตนที่ทําด้วยทองคํา ซึ่งมือของเจ้าได้ทําขึ้นอย่างบาปหนาสําหรับตัวเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 8, 'และคนอัสซีเรียจะล้มลงด้วยดาบซึ่งไม่ใช่ของชายฉกรรจ์ และดาบซึ่งไม่ใช่ของคนต่ําต้อยจะกินเขาเสีย และเขาจะหนีจากดาบและคนหนุ่มของเขาจะพ่ายแพ้อย่างสิ้นเชิง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 9, 'เขาจะข้ามที่กําบังของเขาไปเพราะความหวาดกลัว และพวกเจ้านายของเขาจะเกรงกลัวธงนั้น” พระเยโฮวาห์ผู้ที่ไฟของพระองค์อยู่ในศิโยน และผู้ที่เตาหลอมของพระองค์อยู่ในเยรูซาเล็ม ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 1, 'ดูเถิด กษัตริย์องค์หนึ่งจะครอบครองด้วยความชอบธรรม และเจ้านายจะครอบครองด้วยความยุติธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 2, 'และผู้หนึ่งจะเหมือนที่กําบังจากลม เป็นที่คุ้มให้พ้นจากพายุฝน เหมือนธารน้ําในที่แห้ง เหมือนร่มเงาศิลามหึมาในแผ่นดินที่อ่อนเปลี้ย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 3, 'แล้วตาของคนที่เห็นจะมิได้หลับ และหูของคนที่ฟังจะได้ยิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 4, 'จิตใจของคนที่หุนหันจะเข้าใจความรู้ และลิ้นของคนติดอ่างจะพูดฉะฉานอย่างทันควัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 5, 'เขาจะไม่เรียกคนเลวทรามว่าคนใจกว้างอีก หรือคนถ่อยว่าเป็นคนอารี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 6, 'เพราะคนเลวทรามจะพูดอย่างเลวทราม และใจของเขาก็ปองความชั่วช้า เพื่อประกอบความหน้าซื่อใจคด เพื่อออกปากพูดความผิดเกี่ยวกับพระเยโฮวาห์ เพื่อทําจิตใจของคนหิวให้อดอยากและจะไม่ให้คนกระหายได้ดื่ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 7, 'อุบายของคนถ่อยก็ชั่วร้าย เขาคิดขึ้นแต่กิจการชั่วเพื่อทําลายคนยากจนด้วยถ้อยคําเท็จ แม้ว่าเมื่อคําร้องของคนขัดสนนั้นถูกต้อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 8, 'แต่คนใจกว้างก็แนะนําแต่สิ่งที่ประเสริฐ เขาจะดํารงอยู่ด้วยสิ่งที่ประเสริฐ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 9, 'หญิงทั้งหลายที่อยู่อย่างสบายเอ๋ย จงลุกขึ้นเถิด และฟังเสียงของข้าพเจ้า ท่านบุตรสาวที่ไม่ระมัดระวังเอ๋ย จงเงี่ยหูฟังคําพูดของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 10, 'อีกสักปีกว่าๆ หญิงที่ไม่ระมัดระวังเอ๋ย ท่านจะสะดุ้งตัวสั่น เพราะไร่องุ่นก็จะไร้ผล ฤดูเก็บผลไม้ก็จะไม่มาถึง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 11, 'หญิงที่อยู่สบายเอ๋ย จงตัวสั่นเถิด ท่านผู้ไม่ระมัดระวังเอ๋ย จงสะดุ้งตัวสั่นเถิด จงแก้ผ้า ปล่อยตัวล่อนจ้อน และเอาผ้ากระสอบคาดเอวไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 12, 'เขาจะทุบอก ด้วยเรื่องไร่นาที่แสนสุข ด้วยเรื่องเถาองุ่นผลดก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 13, 'ด้วยเรื่องแผ่นดินของชนชาติของเราซึ่งงอกแต่หนามใหญ่และหนามย่อย ด้วยเรื่องบ้านเรือนที่ชื่นบานในนครที่สนุกสนาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 14, 'เพราะว่าพระราชวังจะถูกทอดทิ้ง เมืองที่มีคนหนาแน่นจะถูกทิ้งร้าง ป้อมปราการและหอคอยจะกลายเป็นถ้ําเป็นนิตย์ เป็นที่ชื่นบานของลาป่า เป็นลานหญ้าของฝูงแพะแกะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 15, 'จนกว่าพระวิญญาณจะเทลงมาบนเราจากเบื้องบน และถิ่นทุรกันดารกลายเป็นสวนผลไม้ และสวนผลไม้นั้นจะถือว่าเป็นป่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 16, 'แล้วความยุติธรรมจะอาศัยอยู่ในถิ่นทุรกันดาร และความชอบธรรมพักอยู่ในสวนผลไม้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 17, 'และผลของความชอบธรรมจะเป็นสันติภาพ และผลของความชอบธรรมคือความสงบและความวางใจเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 18, 'ชนชาติของเราจะอาศัยอยู่ในที่อยู่อย่างสันติ ในที่อาศัยอันปลอดภัย ในที่พักอันสงบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 19, 'เมื่อป่าพังทลาย ลูกเห็บจะตกและเมืองจะยุบลงทีเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 20, 'ท่านที่หว่านอยู่ข้างห้วงน้ําทั้งปวงก็เป็นสุข ผู้ที่ปล่อยให้ตีนวัวและตีนลาเที่ยวอยู่อย่างอิสระ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 1, 'วิบัติแก่เจ้าผู้ทําลาย ผู้ซึ่งตัวเจ้าเองมิได้ถูกทําลาย เจ้าผู้เป็นคนทรยศ ซึ่งไม่มีผู้ใดได้ทรยศต่อเจ้าเลย เมื่อเจ้าจะหยุดทําลาย เจ้าจะถูกทําลาย และเมื่อเจ้าจะหยุดยั้งการประพฤติทรยศเสีย เขาทั้งหลายจะทรยศต่อเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 2, 'โอ ข้าแต่พระเยโฮวาห์ ขอทรงพระกรุณาแก่ข้าพระองค์ทั้งหลาย ข้าพระองค์ทั้งหลายรอคอยพระองค์ ขอทรงเป็นแขนของเขาทั้งหลายทุกเช้า เป็นความรอดของข้าพระองค์ทั้งหลายในยามทุกข์ลําบากด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 3, 'เมื่อได้ยินเสียงกัมปนาท ชนชาติทั้งหลายหนีไป พระองค์ทรงลุกขึ้น บรรดาประชาชาติก็กระจัดกระจายไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 4, 'ของที่ริบได้ของเจ้าก็ถูกรวบรวมเหมือนตั๊กแตนวัยคลานเก็บรวบรวม คนก็กระโดดตะครุบอย่างตั๊กแตนวัยบินโดดตะครุบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 5, 'พระเยโฮวาห์ทรงเป็นที่เยินยอ เพราะพระองค์ประทับ ณ ที่สูง พระองค์ทรงให้ความยุติธรรมและความชอบธรรมเต็มศิโยน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 6, 'สติปัญญาและความรู้อันอุดมจะเป็นเสถียรภาพแห่งเวลาของเจ้า และเป็นกําลังแห่งความรอด ความยําเกรงพระเยโฮวาห์เป็นทรัพย์สมบัติของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 7, 'ดูเถิด ผู้แกล้วกล้าของเขาจะร้องทูลอยู่ภายนอก คณะทูตสันติภาพจะร่ําไห้อย่างขมขื่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 8, 'ทางหลวงก็ร้าง คนสัญจรไปมาก็หยุดเดิน เขาหักพันธสัญญาเสีย เขาดูหมิ่นเมืองต่างๆ เขาไม่นับถือคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 9, 'แผ่นดินไว้ทุกข์และอ่อนระทวย เลบานอนอับอายและถูกโค่นลง ชาโรนเหมือนถิ่นทุรกันดาร บาชานและคารเมลก็สลัดผลของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 10, 'พระเยโฮวาห์ตรัสว่า “บัดนี้เราจะลุกขึ้น บัดนี้เราจะเป็นที่ยกย่อง บัดนี้เราจะเป็นที่เชิดชู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 11, 'เจ้าจะอุ้มท้องแต่แกลบ เจ้าจะคลอดแต่ตอ ลมหายใจของเจ้าเป็นไฟที่จะเผาผลาญเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 12, 'และชนชาติทั้งหลายก็จะเหมือนถูกเผาเป็นปูน เหมือนหนามใหญ่ที่ถูกตัดลงที่เผาในไฟ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 13, 'เจ้าผู้อยู่ไกล ฟังซิ ว่าเราได้ทําอะไร เจ้าผู้อยู่ใกล้ จงรับรู้เรื่องกําลังของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 14, 'คนบาปในศิโยนก็กลัว ความสะทกสะท้านทําให้คนหน้าซื่อใจคดประหลาดใจ “ใครในพวกเราจะอยู่กับไฟที่เผาผลาญได้ ใครในพวกเราจะอาศัยอยู่กับการไหม้เป็นนิตย์ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 15, 'คือเขาผู้ดําเนินอย่างชอบธรรมและพูดอย่างซื่อตรง เขาผู้ดูหมิ่นผลที่ได้จากการบีบบังคับ ผู้สลัดมือของเขาจากการถือสินบนไว้ ผู้อุดหูจากการฟังเรื่องเลือดตกยางออก และปิดตาจากการมองความชั่วร้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 16, 'เขาจะอาศัยอยู่บนที่สูง ที่กําบังของเขาจะเป็นป้อมหิน จะมีผู้ให้อาหารเขา น้ําของเขาจะมีแน่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 17, 'ตาของเจ้าจะเห็นกษัตริย์ทรงสง่าราศี จะเห็นแผ่นดินที่ยืดออกไกล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 18, 'จิตใจของเจ้าจะคิดคํานึงถึงความสยดสยอง “เขาผู้ที่เป็นราชเลขาอยู่ที่ไหน เขาผู้ที่ชั่งบรรณาการอยู่ที่ไหน เขาผู้ที่นับหอคอยอยู่ที่ไหน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 19, 'ท่านจะไม่เห็นชนชาติที่ดุร้ายอีก ชนชาติที่พูดคลุมเครือซึ่งท่านฟังไม่ออก ที่พูดต่างภาษาซึ่งท่านเข้าใจไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 20, 'จงมองศิโยน เมืองแห่งเทศกาลของเรา ตาของท่านจะเห็นเยรูซาเล็ม เป็นที่อยู่ที่สงบ เป็นพลับพลาที่ไม่ต้องขนย้าย หลักหมุดพลับพลาจะไม่รู้จักถอนขึ้น เชือกผูกก็จะไม่รู้จักขาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 21, 'แต่นั่นพระเยโฮวาห์จะทรงอยู่กับเราด้วยความโอ่อ่าตระการ ในที่ที่มีแม่น้ําและลําธารกว้าง ที่จะไม่มีเรือกรรเชียงใหญ่แล่นไป ที่จะไม่มีเรืองามโอ่อ่าผ่านไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 22, 'เพราะพระเยโฮวาห์ทรงเป็นผู้พิพากษาของเรา พระเยโฮวาห์ทรงเป็นผู้ทรงตั้งพระราชบัญญัติให้เรา พระเยโฮวาห์ทรงเป็นบรมมหากษัตริย์ของเรา พระองค์จะทรงช่วยเราให้รอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 23, 'สายโยงของเจ้าห้อยหย่อน มันจะยึดเสาให้แน่นไม่ได้ หรือยึดใบให้กางไม่ได้ แล้วเขาจะแบ่งเหยื่อและของที่ริบได้เป็นอันมากนั้น แม้คนง่อยก็จะเอาเหยื่อได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 24, 'ไม่มีชาวเมืองคนใดจะกล่าวว่า “ข้าป่วยอยู่” ประชาชนผู้อาศัยอยู่ที่นั่นจะได้รับอภัยความชั่วช้าของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 1, 'บรรดาประชาชาติเอ๋ย จงเข้ามาใกล้จะได้ฟัง และชนชาติทั้งหลายเอ๋ย ฟังซิ ขอให้แผ่นดินโลกและสรรพสิ่งในนั้นฟัง ทั้งพิภพและบรรดาสิ่งที่มาจากพิภพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 2, 'เพราะพระเยโฮวาห์ทรงเกรี้ยวกราดต่อประชาชาติทั้งสิ้น และดุเดือดต่อพลโยธาทั้งสิ้นของเขา พระองค์ทรงสังหารผลาญเขาอย่างเด็ดขาด และมอบเขาไว้แก่การฆ่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 3, 'คนที่ถูกฆ่าของเขาจะถูกเหวี่ยงออกไป และกลิ่นเหม็นแห่งศพของเขาจะฟุ้งไป ภูเขาจะละลายไปด้วยโลหิตของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 4, 'บริวารทั้งสิ้นของฟ้าสวรรค์จะละลายไป และท้องฟ้าก็จะม้วนเหมือนหนังสือม้วน บริวารทั้งสิ้นของมันจะร่วงหล่นเหมือนใบไม้หล่นจากเถาองุ่น อย่างมะเดื่อหล่นจากต้นมะเดื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 5, 'เพราะว่าดาบของเราจะได้ดื่มจนอิ่มในฟ้าสวรรค์ ดูเถิด มันจะลงมาเพื่อพิพากษาเอโดมและชนชาติที่เราสาปแช่งแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 6, 'พระแสงของพระเยโฮวาห์เต็มไปด้วยโลหิต เกรอะกรังไปด้วยไขมัน กับเลือดของลูกแกะและแพะ กับไขมันของไตแกะผู้ เพราะพระเยโฮวาห์มีการฆ่าบูชาในเมืองโบสราห์ การฆ่าขนาดใหญ่ในแผ่นดินเอโดม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 7, 'ม้ายูนิคอนจะล้มลงพร้อมกับเขาด้วย และวัวหนุ่มจะล้มอยู่กับวัวที่ฉกรรจ์ แผ่นดินของเขาจะโชกไปด้วยเลือด และดินจะได้อุดมด้วยไขมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 8, 'เพราะพระเยโฮวาห์ทรงมีวันเพื่อการแก้แค้น มีปีแห่งการตอบแทนเพื่อการโต้เถียงกันของศิโยน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 9, 'และลําธารแห่งเอโดมจะกลายเป็นยางมะตอย และดินของเมืองนี้จะกลายเป็นกํามะถัน แผ่นดินนี้จะกลายเป็นยางมะตอยที่ลุกอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 10, 'ทั้งกลางคืนและกลางวันจะไม่ดับ ควันของมันจะขึ้นอยู่เสมอเป็นนิตย์ มันจะถูกทิ้งร้างอยู่ทุกชั่วอายุ ไม่มีใครจะผ่านไปเนืองนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 11, 'แต่นกกระทุงและอีกาบ้านจะยึดมันเป็นกรรมสิทธิ์ นกทึดทือและนกกาจะอาศัยอยู่ที่นั่น พระองค์จะทรงขึงสายแห่งความยุ่งเหยิงเหนือมัน และปล่อยลูกดิ่งแห่งความว่างเปล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 12, 'เขาจะเรียกพวกขุนนางมายังราชอาณาจักร แต่ไม่มีเลย และบรรดาเจ้านายของมันจะไม่มีค่าเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 13, 'หนามใหญ่จะงอกขึ้นในพระราชวังของมัน ตําแยและต้นหนามจะงอกขึ้นในป้อมปราการของมัน และจะเป็นที่อาศัยของมังกร และเป็นลานของนกเค้าแมว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 14, 'และสัตว์ป่าจะพบกับหมาจิ้งจอก เมษปีศาจจะร้องหาเพื่อนของมัน เออ ผีจะลงมาที่นั่นและหาที่ตัวพัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 15, 'นกฮูกจะทํารังและตกฟองที่นั่น และกกไข่และรวบรวมลูกอ่อนไว้ในเงาของมัน เออ เหยี่ยวปีกดําจะรวมกันที่นั่น ต่างคู่ก็อยู่กับของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 16, 'จงเสาะหาและอ่านจากหนังสือของพระเยโฮวาห์ สัตว์เหล่านี้จะไม่ขาดไปสักอย่างเดียว ไม่มีตัวใดที่จะไม่มีคู่ เพราะหนังสือนั้นได้บัญชาปากของเราแล้ว และพระวิญญาณของพระองค์ได้รวบรวมไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 17, 'พระองค์ทรงจับฉลากให้มันแล้ว พระหัตถ์ของพระองค์ได้แบ่งส่วนให้ด้วยเชือกวัด มันทั้งหลายจะได้กรรมสิทธิ์เป็นนิตย์ มันจะอาศัยอยู่ในนั้นทุกชั่วอายุ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 1, 'ถิ่นทุรกันดารและที่แห้งแล้งจะยินดีเพื่อเขาทั้งหลาย ทะเลทรายจะเปรมปรีดิ์และผลิดอกอย่างต้นดอกกุหลาบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 2, 'มันจะออกดอกอุดม และเปรมปรีดิ์ด้วยความชื่นบานและการร้องเพลง สง่าราศีของเลบานอนก็จะประทานให้มัน ทั้งความโอ่อ่าตระการของคารเมลและชาโรน ที่เหล่านี้จะเห็นสง่าราศีของพระเยโฮวาห์ และความโอ่อ่าตระการของพระเจ้าของพวกเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 3, 'จงหนุนกําลังของมือที่อ่อน และกระทําหัวเข่าที่อ่อนให้มั่นคง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 4, 'จงกล่าวกับคนที่มีใจคร้ามกลัวว่า “จงแข็งแรงเถอะ อย่ากลัว ดูเถิด พระเจ้าของท่านทั้งหลายจะเสด็จมาด้วยการแก้แค้น พระองค์จะเสด็จมาและช่วยท่านให้รอด ด้วยการตอบแทนของพระเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 5, 'แล้วนัยน์ตาของคนตาบอดจะเปิดออก แล้วหูของคนหูหนวกจะเบิก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 6, 'แล้วคนง่อยจะกระโดดได้อย่างกวาง และลิ้นของคนใบ้จะร้องเพลง เพราะน้ําจะพลุ่งขึ้นมาในถิ่นทุรกันดาร และลําธารจะพลุ่งขึ้นในทะเลทราย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 7, 'ดินที่แตกระแหงจะกลายเป็นสระน้ํา และดินที่กระหายจะกลายเป็นน้ําพุ ในที่อาศัยของมังกรที่ที่แต่ละตัวอาศัยนอนอยู่จะมีหญ้าพร้อมทั้งต้นอ้อและต้นกกงอกขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 8, 'และจะมีทางหลวงที่นั่น และจะมีทางหนึ่ง และเขาจะเรียกทางนั้นว่า ทางแห่งความบริสุทธิ์ คนไม่สะอาดจะไม่ผ่านไปทางนั้น แต่จะเป็นทางเพื่อพวกเขา แล้วพวกที่เดินทางแม้คนโง่ก็จะไม่หลงในนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 9, 'จะไม่มีสิงโตที่นั่น หรือจะไม่มีสัตว์ร้ายมาบนทางนั้น จะหามันที่นั่นไม่พบ แต่ผู้ที่ไถ่ไว้แล้วจะเดินบนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 10, 'ผู้ที่รับการไถ่แล้วของพระเยโฮวาห์จะกลับ และจะมายังศิโยนด้วยร้องเพลง มีความชื่นบานเป็นนิตย์บนศีรษะของเขาทั้งหลาย เขาจะได้รับความชื่นบานและความยินดี ความโศกเศร้าและการถอนหายใจจะปลาตไปเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 1, 'ต่อมาในปีที่สิบสี่แห่งรัชกาลกษัตริย์เฮเซคียาห์ เซนนาเคอริบกษัตริย์แห่งอัสซีเรียได้ยกขึ้นมาต่อสู้บรรดานครที่มีป้อมของยูดาห์และยึดได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 2, 'และกษัตริย์แห่งอัสซีเรียได้รับสั่งให้รับชาเคห์ ไปจากเมืองลาคีชถึงกรุงเยรูซาเล็ม เข้าเฝ้ากษัตริย์เฮเซคียาห์ พร้อมกับกองทัพใหญ่ และท่านมายืนอยู่ทางรางระบายน้ําสระบนที่ถนนลานซักฟอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 3, 'เอลียาคิมบุตรชายฮิลคียาห์ก็ออกมาหาท่าน เอลียาคิมเป็นผู้บัญชาการราชสํานัก พร้อมกับเชบนาห์ราชเลขา และโยอาห์บุตรชายอาสาฟเจ้ากรมสารบรรณ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 4, 'และรับชาเคห์พูดกับเขาว่า “จงทูลเฮเซคียาห์ว่า ‘พระมหากษัตริย์ คือกษัตริย์แห่งอัสซีเรีย ตรัสดังนี้ว่า ท่านวางใจในอะไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 5, 'ท่านคิดว่า (แต่เป็นเพียงแต่ถ้อยคําไร้สาระ) “เรามียุทธศาสตร์และแสนยานุภาพ” หรือ เดี๋ยวนี้ท่านวางใจในใคร ท่านจึงได้กบฏต่อเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 6, 'ดูเถิด ท่านวางใจในไม้เท้าอ้อที่เดาะ คืออียิปต์ ซึ่งจะตํามือของคนใดๆที่ใช้ไม้เท้านั้นยัน ฟาโรห์กษัตริย์แห่งอียิปต์เป็นเช่นนั้นต่อทุกคนที่วางใจในเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 7, 'แต่ถ้าท่านจะบอกเราว่า “เราวางใจในพระเยโฮวาห์พระเจ้าของเรา” ก็ปูชนียสถานสูงและแท่นบูชาของพระองค์นั้นมิใช่หรือที่เฮเซคียาห์รื้อทิ้งเสียแล้ว พลางกล่าวแก่ยูดาห์และเยรูซาเล็มว่า “ท่านทั้งหลายจงนมัสการที่หน้าแท่นบูชานี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 8, 'ฉะนั้นบัดนี้ มาเถิด มาทําสัญญากันกับกษัตริย์แห่งอัสซีเรียนายของข้า เราจะให้ม้าสองพันตัวแก่เจ้า ถ้าฝ่ายเจ้าหาคนที่ขี่ม้าเหล่านั้นได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 9, 'แล้วอย่างนั้นเจ้าจะขับไล่นายกองแต่เพียงคนเดียวในหมู่ข้าราชการผู้น้อยที่สุดของนายของเราอย่างไรได้ แต่เจ้ายังวางใจพึ่งอียิปต์เพื่อรถรบและเพื่อพลม้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 10, 'ยิ่งกว่านั้นอีกที่เรามาต่อสู้แผ่นดินนี้เพื่อทําลายเสีย ก็ขึ้นมาโดยปราศจากพระเยโฮวาห์หรือ พระเยโฮวาห์ตรัสแก่ข้าว่า “จงขึ้นไปต่อสู้แผ่นดินนี้และทําลายเสีย”’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 11, 'แล้วเอลียาคิม เชบนาห์ และโยอาห์ เรียนรับชาเคห์ว่า “ขอทีเถอะ ขอพูดกับผู้รับใช้ของท่านเป็นภาษาอารัมเถิด เพราะเราเข้าใจภาษานั้น ขออย่าพูดกับเราเป็นภาษาฮีบรูให้ประชาชนผู้อยู่บนกําแพงนั้นได้ยินเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 12, 'แต่รับชาเคห์ว่า “นายของข้าใช้ให้เรามาพูดถ้อยคําเหล่านี้แก่นายของเจ้าและแก่เจ้า และไม่ให้พูดกับคนที่นั่งอยู่บนกําแพง ผู้ที่จะต้องกินขี้และกินเยี่ยวของเขาพร้อมกับเจ้าอย่างนั้นหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 13, 'แล้วรับชาเคห์ได้ยืนร้องตะโกนเสียงดังเป็นภาษาฮีบรูว่า “จงฟังพระวจนะของพระมหากษัตริย์ คือกษัตริย์แห่งอัสซีเรีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 14, 'กษัตริย์ตรัสดังนี้ว่า ‘อย่าให้เฮเซคียาห์ลวงเจ้า เพราะเขาไม่สามารถที่จะช่วยเจ้าให้พ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 15, 'อย่าให้เฮเซคียาห์กระทําให้เจ้าวางใจในพระเยโฮวาห์โดยกล่าวว่า “พระเยโฮวาห์จะทรงช่วยเราให้พ้นแน่ จะไม่ทรงมอบเมืองนี้ไว้ในมือของกษัตริย์แห่งอัสซีเรีย”’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 16, 'อย่าฟังเฮเซคียาห์ เพราะกษัตริย์แห่งอัสซีเรียตรัสดังนี้ว่า ‘จงทําสัญญาไมตรีกับเราด้วยของกํานัล และออกมาหาเรา แล้วทุกคนจะได้กินจากเถาองุ่นของตน และทุกคนจะกินจากต้นมะเดื่อของตน และทุกคนจะดื่มน้ําจากที่ขังน้ําของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 17, 'จนเราจะมานําเจ้าไปยังแผ่นดินที่เหมือนแผ่นดินของเจ้าเอง เป็นแผ่นดินที่มีข้าวและน้ําองุ่น แผ่นดินที่มีขนมปังและสวนองุ่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 18, 'จงระวังเกลือกว่าเฮเซคียาห์จะนําเจ้าผิดไปโดยกล่าวว่า “พระเยโฮวาห์จะทรงช่วยเราทั้งหลายให้พ้น” มีพระแห่งบรรดาประชาชาติองค์ใดเคยช่วยแผ่นดินของตนให้พ้นจากพระหัตถ์แห่งกษัตริย์ของอัสซีเรียได้หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 19, 'พระของเมืองฮามัทและเมืองอารปัดอยู่ที่ไหน พระของเมืองเสฟารวาอิมอยู่ที่ไหน เขาได้ช่วยสะมาเรียให้พ้นจากมือของเราหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 20, 'พระองค์ใดในบรรดาพระทั้งหลายของประเทศเหล่านี้ได้ช่วยประเทศของตนให้พ้นจากมือของเรา แล้วพระเยโฮวาห์จะทรงช่วยเยรูซาเล็มให้พ้นจากมือของเราหรือ’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 21, 'แต่เขาทั้งหลายนิ่งไม่ตอบเขาสักคําเดียว เพราะพระบัญชาของกษัตริย์มีว่า “อย่าตอบเขาเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 22, 'แล้วเอลียาคิมบุตรชายฮิลคียาห์ ผู้บัญชาการราชสํานัก และเชบนาห์ราชเลขา และโยอาห์บุตรชายอาสาฟ เจ้ากรมสารบรรณ ได้เข้าเฝ้าเฮเซคียาห์ด้วยเสื้อผ้าฉีกขาด และกราบทูลถ้อยคําของรับชาเคห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 1, 'ต่อมาเมื่อกษัตริย์เฮเซคียาห์ทรงได้ยิน พระองค์ก็ทรงฉีกฉลองพระองค์เสีย และทรงเอาผ้ากระสอบคลุมพระองค์ และเสด็จเข้าในพระนิเวศของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 2, 'และพระองค์ทรงใช้เอลียาคิม ผู้บัญชาการราชสํานัก และเชบนาห์ราชเลขา และพวกปุโรหิตใหญ่คลุมตัวด้วยผ้ากระสอบ ไปหาอิสยาห์ผู้พยากรณ์ บุตรชายของอามอส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 3, 'เขาทั้งหลายเรียนท่านว่า “เฮเซคียาห์ตรัสดังนี้ว่า ‘วันนี้เป็นวันทุกข์ใจ วันถูกติเตียนและหมิ่นประมาท เด็กก็ถึงกําหนดคลอด แต่ไม่มีกําลังเบ่งให้คลอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 4, 'ชะรอยพระเยโฮวาห์พระเจ้าของท่านคงจะสดับถ้อยคําของรับชาเคห์ ผู้ซึ่งกษัตริย์แห่งอัสซีเรียนายของเขาได้สั่งมาให้เย้ยพระเจ้าผู้ทรงพระชนม์ และจะทรงขนาบถ้อยคําซึ่งพระเยโฮวาห์พระเจ้าของท่านได้ทรงสดับ เพราะฉะนั้นขอท่านถวายคําอธิษฐานเพื่อส่วนชนที่เหลืออยู่นี้’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 5, 'ดังนั้นข้าราชการของกษัตริย์เฮเซคียาห์มาถึงอิสยาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 6, 'อิสยาห์ก็บอกเขาทั้งหลายว่า “จงทูลนายของท่านเถิดว่า พระเยโฮวาห์ตรัสดังนี้ว่า ‘อย่ากลัวเพราะถ้อยคําที่เจ้าได้ยินนั้น ซึ่งข้าราชการของกษัตริย์แห่งอัสซีเรียได้กล่าวหยาบช้าต่อเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 7, 'ดูเถิด เราจะบรรจุจิตใจอย่างหนึ่งในเขา เพื่อเขาจะได้ยินข่าวลือ และกลับไปยังแผ่นดินของเขา และเราจะให้เขาล้มลงด้วยดาบในแผ่นดินของเขาเอง’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 8, 'รับชาเคห์ได้กลับไป และได้พบกษัตริย์แห่งอัสซีเรียสู้รบเมืองลิบนาห์ เพราะเขาได้ยินว่ากษัตริย์ออกจากลาคีชแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 9, 'พระองค์ทรงได้ยินเกี่ยวกับทีรหะคาห์กษัตริย์แห่งเอธิโอเปียว่า “เขาได้ออกมาสู้รบกับพระองค์แล้ว” และเมื่อพระองค์ทรงสดับแล้วจึงส่งผู้สื่อสารไปเฝ้าเฮเซคียาห์ทูลว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 10, '“เจ้าจงพูดกับเฮเซคียาห์กษัตริย์แห่งยูดาห์ดังนี้ว่า ‘อย่าให้พระเจ้าของท่านซึ่งท่านวางใจนั้นลวงท่านว่า “เยรูซาเล็มจะมิได้ถูกมอบไว้ในมือของกษัตริย์แห่งอัสซีเรีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 11, 'ดูเถิด ท่านได้ยินแล้วว่า บรรดากษัตริย์แห่งอัสซีเรียได้กระทําอะไรกับแผ่นดินทั้งสิ้นบ้าง ทําลายเสียหมดอย่างสิ้นเชิง ส่วนท่านเองจะรับการช่วยให้พ้นหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 12, 'บรรดาพระของบรรดาประชาชาติได้ช่วยเขาให้รอดพ้นหรือ คือประชาชาติซึ่งบรรพบุรุษของเราได้ทําลาย คือโกซาน ฮาราน เรเซฟ และประชาชนของเอเดนซึ่งอยู่ในเทลอัสสาร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 13, 'กษัตริย์ของฮามัท กษัตริย์ของอารปัด กษัตริย์ของเมืองเสฟารวาอิม เฮนาและอิฟวาห์อยู่ที่ไหน’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 14, 'เฮเซคียาห์ทรงรับจดหมายจากมือผู้สื่อสาร และทรงอ่าน และเฮเซคียาห์ได้ขึ้นไปยังพระนิเวศของพระเยโฮวาห์ และทรงคลี่จดหมายนั้นออกต่อเบื้องพระพักตร์พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 15, 'และเฮเซคียาห์ทรงอธิษฐานต่อพระเยโฮวาห์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 16, '“โอ ข้าแต่พระเยโฮวาห์จอมโยธา พระเจ้าแห่งอิสราเอล ผู้ทรงประทับระหว่างพวกเครูบ พระองค์ทรงเป็นพระเจ้าแห่งบรรดาราชอาณาจักรของแผ่นดินโลก พระองค์แต่องค์เดียว พระองค์ได้ทรงสร้างฟ้าสวรรค์และแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 17, 'โอ ข้าแต่พระเยโฮวาห์ ขอทรงเงี่ยพระกรรณสดับ โอ ข้าแต่พระเยโฮวาห์ ขอทรงเบิกพระเนตรทอดพระเนตร และขอทรงสดับบรรดาถ้อยคําของเซนนาเคอริบ ซึ่งเขาได้ใช้มาเย้ยพระเจ้าผู้ทรงพระชนม์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 18, 'ข้าแต่พระเยโฮวาห์ เป็นความจริงที่บรรดากษัตริย์แห่งอัสซีเรียได้กระทําให้ประเทศทั้งสิ้นและแผ่นดินของเขานั้นร้างเปล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 19, 'และได้เหวี่ยงพระของประชาชาตินั้นเข้าไฟ เพราะเขามิใช่พระ เป็นแต่ผลงานของมือมนุษย์ เป็นไม้และหิน เพราะฉะนั้นเขาจึงถูกทําลายเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 20, 'ฉะนั้นบัดนี้ โอ ข้าแต่พระเยโฮวาห์พระเจ้าของข้าพระองค์ทั้งหลาย ขอทรงช่วยข้าพระองค์ให้พ้นมือของเขา เพื่อราชอาณาจักรทั้งสิ้นแห่งแผ่นดินโลกจะทราบว่า พระองค์ทรงเป็นพระเยโฮวาห์แต่พระองค์เดียว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 21, 'แล้วอิสยาห์บุตรชายของอามอสได้ใช้ให้ไปเฝ้าเฮเซคียาห์ทูลว่า “พระเยโฮวาห์พระเจ้าแห่งอิสราเอลตรัสดังนี้ว่า เพราะเจ้าได้อธิษฐานต่อเราเกี่ยวกับเซนนาเคอริบกษัตริย์แห่งอัสซีเรีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 22, 'ต่อไปนี้เป็นพระวจนะซึ่งพระเยโฮวาห์ตรัสเกี่ยวกับท่านนั้นว่า ‘ธิดาพรหมจารีแห่งศิโยนดูหมิ่นเจ้า และหัวเราะเยาะเย้ยเจ้า ธิดาแห่งเยรูซาเล็มสั่นศีรษะใส่เจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 23, 'เจ้าเย้ยและกล่าวหยาบช้าต่อผู้ใด เจ้าขึ้นเสียงของเจ้าต่อผู้ใด และเบิ่งตาของเจ้าอย่างเย่อหยิ่งต่อผู้ใด ต่อองค์บริสุทธิ์แห่งอิสราเอลน่ะซิ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 24, 'เจ้าได้เย้ยองค์พระผู้เป็นเจ้าด้วยผู้รับใช้ของเจ้า และเจ้าได้ว่า “ด้วยรถรบเป็นอันมากของข้า ข้าได้ขึ้นที่สูงของภูเขา ถึงที่ไกลสุดของเลบานอน ข้าจะโค่นต้นสนสีดาร์ที่สูงที่สุดของมันลง ทั้งต้นสนสามใบที่ดีที่สุดของมัน ข้าจะเข้าไปยังที่ยอดลิบที่สุดในชายแดนของมัน ที่ป่าไม้แห่งคารเมล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 25, 'ข้าขุดบ่อและดื่มน้ํา ข้าได้เอาฝ่าเท้าของข้ากวาดธารน้ําทั้งสิ้นของสถานที่ที่ถูกล้อมโจมตีให้แห้งไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 26, 'เจ้าไม่ได้ยินหรือว่า เราได้จัดไว้นานแล้ว เราได้กะแผนงานไว้แต่ดึกดําบรรพ์ ซึ่ง ณ บัดนี้เราให้เป็นไปแล้ว คือเจ้าจะทําเมืองที่มีป้อมให้พังลงให้เป็นกองสิ่งปรักหักพัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 27, 'ส่วนชาวเมืองนั้นมีอํานาจน้อย เขาสะดุ้งกลัวและอับอาย เขาเหมือนหญ้าที่ทุ่งนา และเหมือนหญ้าอ่อน เหมือนหญ้าที่บนยอดหลังคาเรือน เหมือนข้าวเกรียมไปก่อนที่มันจะงอกงามอย่างนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 28, 'แต่เราได้รู้จักการที่เจ้านั่งลงกับการออกไปและเข้ามาของเจ้า และการเกรี้ยวกราดของเจ้าต่อเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 29, 'เพราะเจ้าได้เกรี้ยวกราดต่อเรา และความจองหองของเจ้าได้มาเข้าหูของเรา ฉะนั้น เราจะเอาขอของเราเกี่ยวจมูกเจ้า และบังเหียนของเราใส่ริมฝีปากเจ้า และเราจะหันเจ้ากลับไปตามทางซึ่งเจ้ามานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 30, 'และนี่จะเป็นหมายสําคัญแก่เจ้า คือปีนี้เจ้าจะกินสิ่งที่งอกขึ้นเอง และในปีที่สองสิ่งที่ผลิจากเดิม แล้วในปีที่สาม จงหว่าน และเกี่ยว และปลูกสวนองุ่นและกินผลของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 31, 'ส่วนที่รอดและเหลือแห่งวงศ์วานของยูดาห์จะหยั่งรากลงไป และเกิดผลขึ้นบน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 32, 'เพราะว่าส่วนคนที่เหลือจะออกไปจากเยรูซาเล็ม และส่วนที่รอดมาจะออกมาจากภูเขาศิโยน ความกระตือรือร้นของพระเยโฮวาห์จอมโยธาจะกระทําการนี้’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 33, 'เพราะฉะนั้นพระเยโฮวาห์จึงตรัสเกี่ยวกับกษัตริย์แห่งอัสซีเรียดังนี้ว่า ‘ท่านจะไม่เข้าในนครนี้หรือยิงลูกธนูไปที่นั่น หรือถือโล่เข้ามาข้างหน้านคร หรือสร้างเชิงเทินสู้มัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 34, 'ท่านมาทางใด ท่านจะต้องกลับไปทางนั้น ท่านจะไม่เข้ามาในนครนี้ พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 35, 'เพราะเราจะป้องกันนครนี้ไว้เพื่อให้รอด เพื่อเห็นแก่เราเอง และเห็นแก่ดาวิดผู้รับใช้ของเรา’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 36, 'ทูตสวรรค์ของพระเยโฮวาห์จึงได้ออกไป และได้ประหารคนในค่ายแห่งคนอัสซีเรียเสียหนึ่งแสนแปดหมื่นห้าพันคน และเมื่อคนลุกขึ้นในเวลาเช้ามืด ดูเถิด พวกเหล่านั้นเป็นศพทั้งนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 37, 'แล้วเซนนาเคอริบกษัตริย์แห่งอัสซีเรียก็ได้ยกไปและกลับบ้าน และอยู่ในนีนะเวห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 38, 'ต่อมาขณะเมื่อท่านนมัสการในนิเวศของพระนิสโรกพระของท่าน อัดรัมเมเลคและชาเรเซอร์ โอรสของท่าน ก็ประหารท่านเสียด้วยดาบ และหนีไปยังแผ่นดินอาร์มีเนีย และเอสารฮัดโดนโอรสของท่านขึ้นครอบครองแทนท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 1, 'ในวันเหล่านั้นเฮเซคียาห์ทรงประชวรใกล้จะสิ้นพระชนม์ และอิสยาห์ผู้พยากรณ์บุตรชายของอามอสเข้ามาเฝ้าพระองค์ และทูลพระองค์ว่า “พระเยโฮวาห์ตรัสดังนี้ว่า จงจัดการการบ้านการเมืองของเจ้าให้เรียบร้อย เจ้าจะต้องตาย เจ้าจะไม่ฟื้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 2, 'แล้วเฮเซคียาห์ทรงหันพระพักตร์เข้าข้างฝา และอธิษฐานต่อพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 3, 'ว่า “โอ ข้าแต่พระเยโฮวาห์ ข้าพระองค์ขอวิงวอนต่อพระองค์ ขอทรงระลึกว่า ข้าพระองค์ดําเนินอยู่ต่อเบื้องพระพักตร์พระองค์ด้วยความจริงและด้วยใจที่เพียบพร้อม และได้กระทําสิ่งที่ประเสริฐในสายพระเนตรของพระองค์มาอย่างไร” และเฮเซคียาห์ทรงกันแสงอย่างปวดร้าว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 4, 'แล้วพระวจนะของพระเยโฮวาห์มาถึงอิสยาห์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 5, '“จงไปบอกเฮเซคียาห์ว่า พระเยโฮวาห์พระเจ้าของดาวิดบรรพบุรุษของเจ้าตรัสดังนี้ว่า เราได้ยินคําอธิษฐานของเจ้าแล้ว เราได้เห็นน้ําตาของเจ้าแล้ว ดูเถิด เราจะเพิ่มชีวิตให้เจ้าอีกสิบห้าปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 6, 'เราจะช่วยเจ้าและเมืองนี้ให้พ้นจากมือของกษัตริย์แห่งอัสซีเรีย และจะป้องกันเมืองนี้ไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 7, 'นี่จะเป็นหมายสําคัญสําหรับพระองค์จากพระเยโฮวาห์ ที่พระเยโฮวาห์จะทรงกระทําสิ่งนี้ตามที่พระองค์ได้ทรงตรัสไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 8, 'ดูเถิด เราจะกระทําให้เงาที่ดวงอาทิตย์ทอดมาบนนาฬิกาแดดของอาหัสย้อนกลับมาสิบขั้น” ดวงอาทิตย์ก็ได้ย้อนกลับบนนาฬิกาแดดสิบขั้น ตามขั้นที่ได้ตกไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 9, 'บทประพันธ์ของเฮเซคียาห์กษัตริย์แห่งยูดาห์ หลังจากที่พระองค์ได้ทรงประชวรและทรงฟื้นจากการประชวรของพระองค์นั้น มีว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 10, '“ข้าพเจ้าว่า เมื่อชีวิตของข้าพเจ้ามาถึงกลางคน ข้าพเจ้าจะไปยังประตูแดนคนตาย ข้าพเจ้าต้องถูกตัดขาดจากปีที่เหลืออยู่ของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 11, 'ข้าพเจ้าว่า ข้าพเจ้าจะไม่เห็นพระเยโฮวาห์ คือพระเยโฮวาห์ ในแผ่นดินของคนเป็น ข้าพเจ้าจะมองไม่เห็นมนุษย์อีก ที่ในหมู่ชาวแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 12, 'อายุของข้าพเจ้าก็ถูกพรากและถูกถอนออกไปจากข้าพเจ้า อย่างกับเต็นท์ของผู้เลี้ยงแกะ ข้าพเจ้าได้ตัดชีวิตของข้าพเจ้าเหมือนอย่างคนทอผ้า พระองค์จะทรงตัดข้าพเจ้าด้วยโรคตรอมใจ พระองค์จะทรงนําข้าพเจ้ามาถึงอวสานทั้งวันและคืน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 13, 'ข้าพเจ้าได้คิดจนรุ่งเช้าว่า พระองค์จะทรงหักกระดูกทั้งสิ้นของข้าพเจ้าเหมือนอย่างสิงโต พระองค์จะทรงนําข้าพเจ้ามาถึงอวสานทั้งวันและคืน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 14, 'ข้าพเจ้าร้องอย่างนกนางแอ่นหรือนกกรอด ข้าพเจ้าพิลาปอย่างนกเขา ตาของข้าพเจ้าเหนื่อยอ่อนด้วยมองขึ้นข้างบน โอ ข้าแต่พระเยโฮวาห์ ข้าพระองค์ถูกบีบบังคับ ขอพระองค์ทรงเป็นผู้ประกันของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 15, 'แต่ข้าพเจ้าจะพูดอะไรได้ เพราะพระองค์ตรัสกับข้าพเจ้าแล้ว และพระองค์เองได้ทรงกระทําเช่นนั้น ข้าพเจ้าก็จะดําเนินไปด้วยความสงบเสงี่ยมตลอดชีวิตของข้าพเจ้า เพราะความขมขื่นแห่งจิตใจของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 16, 'โอ ข้าแต่องค์พระผู้เป็นเจ้า มนุษย์ดํารงชีพอยู่ได้ด้วยสิ่งเหล่านี้ และชีวิตแห่งวิญญาณของข้าพระองค์ก็อยู่ในบรรดาสิ่งเหล่านี้ พระองค์จะทรงให้ข้าพระองค์หายดีและทรงทําให้ข้าพระองค์มีชีวิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 17, 'ดูเถิด เพราะเห็นแก่สันติภาพ ข้าพระองค์จึงมีความขมขื่นมากยิ่ง แต่พระองค์ทรงรักชีวิตของข้าพระองค์จึงได้ทรงช่วยให้พ้นจากหลุมแห่งความพินาศ เพราะพระองค์ทรงเหวี่ยงบาปทั้งสิ้นของข้าพระองค์ไว้เบื้องพระปฤษฎางค์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 18, 'เพราะแดนคนตายสรรเสริญพระองค์ไม่ได้ ความมรณายกย่องพระองค์ไม่ได้ บรรดาคนที่ลงไปยังปากแดนคนตายนั้น จะหวังในความจริงของพระองค์ไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 19, 'คนเป็น คนเป็น เขาจะสรรเสริญพระองค์ อย่างที่ข้าพระองค์กระทําในวันนี้ บิดาจะได้สําแดงความจริงของพระองค์แก่ลูกของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 20, 'พระเยโฮวาห์ได้ทรงช่วยข้าพเจ้าให้รอด เพราะฉะนั้นข้าพเจ้าทั้งหลายจะร้องเพลงและเล่นเครื่องสายของข้าพเจ้า ตลอดวันเวลาแห่งชีวิตของข้าพเจ้าทั้งหลายที่พระนิเวศของพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 21, 'เพราะอิสยาห์ได้กล่าวว่า “ให้เขาเอาขนมมะเดื่อมาแผ่นหนึ่ง และแปะไว้ที่พระยอดเพื่อพระองค์จะฟื้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 22, 'เฮเซคียาห์ได้ตรัสด้วยว่า “อะไรจะเป็นหมายสําคัญว่า ข้าพเจ้าจะได้ขึ้นไปยังพระนิเวศของพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 1, 'คราวนั้น เมโรดัคบาลาดัน โอรสของบาลาดัน กษัตริย์แห่งบาบิโลน ทรงส่งราชสารและเครื่องบรรณาการมายังเฮเซคียาห์ เพราะพระองค์ทรงได้ยินว่าเฮเซคียาห์ทรงประชวรและทรงหายประชวรแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 2, 'และเฮเซคียาห์ทรงเปรมปรีดิ์เพราะเขาเหล่านั้น และทรงพาเขาชมคลังทรัพย์ของพระองค์ ชมเงิน ทองคํา และเครื่องเทศและน้ํามันประเสริฐ และคลังพระแสงทั้งสิ้นของพระองค์ ทุกอย่างซึ่งมีในท้องพระคลัง ไม่มีสิ่งใดที่ในพระราชวัง หรือในราชอาณาจักรทั้งสิ้นของพระองค์ซึ่งเฮเซคียาห์มิได้ทรงสําแดงแก่เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 3, 'แล้วอิสยาห์ผู้พยากรณ์ก็เข้าเฝ้ากษัตริย์เฮเซคียาห์และทูลพระองค์ว่า “คนเหล่านี้ทูลอะไรบ้าง และเขามาแต่ไหนเข้าเฝ้าพระองค์” เฮเซคียาห์ตรัสว่า “เขาได้มาหาเราจากเมืองไกล จากบาบิโลน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 4, 'ท่านทูลว่า “เขาเห็นอะไรในพระราชวังของพระองค์บ้าง” และเฮเซคียาห์ตรัสตอบว่า “เขาเห็นทุกอย่างในวังของเรา ไม่มีสิ่งใดในพระคลังของเราซึ่งเรามิได้สําแดงแก่เขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 5, 'แล้วอิสยาห์ทูลเฮเซคียาห์ว่า “ขอทรงฟังพระวจนะของพระเยโฮวาห์จอมโยธา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 6, 'ดูเถิด วันเวลากําลังย่างเข้ามา เมื่อสรรพสิ่งทั้งสิ้นในวังของเจ้า และสิ่งซึ่งบรรพบุรุษของเจ้าได้สะสมจนถึงทุกวันนี้จะต้องถูกเอาไปยังบาบิโลน จะไม่มีสิ่งใดเหลือเลย พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 7, 'และลูกบางคนซึ่งถือกําเนิดจากเจ้า ผู้ซึ่งเกิดมาแก่เจ้าจะถูกนําเอาไป และเขาจะเป็นขันทีในวังของกษัตริย์แห่งบาบิโลน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 8, 'แล้วเฮเซคียาห์ตรัสกับอิสยาห์ว่า “พระวจนะของพระเยโฮวาห์ซึ่งท่านกล่าวนั้นก็ดีอยู่” เพราะพระองค์ดําริว่า “จะมีความอยู่เย็นเป็นสุขและความจริงในวันเวลาของเรานี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 1, 'พระเจ้าของเจ้าตรัสว่า “จงเล้าโลม จงเล้าโลมชนชาติของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 2, 'จงพูดกับเยรูซาเล็มอย่างเห็นใจ และจงประกาศแก่เมืองนั้นว่า การสงครามของเธอสิ้นสุดลงแล้ว และความชั่วช้าของเธอก็อภัยเสียแล้ว เพราะเธอได้รับโทษจากพระหัตถ์ของพระเยโฮวาห์แล้ว เป็นสองเท่าของความบาปผิดของเธอ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 3, 'เสียงผู้ร้องในถิ่นทุรกันดารว่า “จงเตรียมมรรคาแห่งพระเยโฮวาห์ จงทําทางหลวงสําหรับพระเจ้าของเราให้ตรงไปในทะเลทราย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 4, 'หุบเขาทุกแห่งจะถูกยกขึ้น ภูเขาและเนินทุกแห่งจะให้ต่ําลง ทางคดจะกลายเป็นทางตรง และที่ขรุขระจะกลายเป็นที่ราบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 5, 'และจะเผยสง่าราศีของพระเยโฮวาห์ และบรรดาเนื้อหนังจะได้เห็นด้วยกัน เพราะพระโอษฐ์ของพระเยโฮวาห์ตรัสไว้แล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 6, 'เสียงหนึ่งร้องว่า “ร้องซิ” และเขาว่า “ข้าจะร้องว่ากระไร” บรรดาเนื้อหนังก็เป็นเสมือนต้นหญ้า และความงามทั้งสิ้นของมันก็เป็นเสมือนดอกไม้แห่งทุ่งนา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 7, 'ต้นหญ้าเหี่ยวแห้งไป ดอกไม้นั้นก็ร่วงโรยไป เพราะพระวิญญาณของพระเยโฮวาห์เป่ามาถูกมัน มนุษยชาติเป็นหญ้าแน่ทีเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 8, 'ต้นหญ้าเหี่ยวแห้งไป ดอกไม้นั้นก็ร่วงโรยไป แต่พระวจนะของพระเจ้าของเราจะยั่งยืนอยู่เป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 9, 'โอ ศิโยนเอ๋ย ผู้นําข่าวดี เจ้าจงขึ้นไปบนภูเขาสูง โอ เยรูซาเล็มเอ๋ย ผู้นําข่าวดี จงเปล่งเสียงของเจ้าด้วยเต็มกําลัง จงเปล่งเสียงเถิด อย่ากลัวเลย จงกล่าวแก่หัวเมืองแห่งยูดาห์ว่า “ดูเถิด นี่พระเจ้าของเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 10, 'ดูเถิด องค์พระผู้เป็นเจ้าพระเจ้าจะเสด็จมาด้วยพระหัตถ์อันเข้มแข็ง และพระกรของพระองค์จะครอบครองเพื่อพระองค์ ดูเถิด รางวัลของพระองค์ก็อยู่กับพระองค์ และพระราชกิจของพระองค์ก็อยู่ต่อพระพักตร์พระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 11, 'พระองค์จะทรงเลี้ยงฝูงแพะแกะของพระองค์อย่างผู้เลี้ยงแกะ พระองค์จะทรงรวบรวมลูกแกะไว้ในพระกรของพระองค์ พระองค์จะทรงอุ้มไว้ที่พระทรวง และทรงค่อยๆนําบรรดาที่มีลูกอ่อนไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 12, 'ผู้ใดได้เคยตวงน้ําทั้งสิ้นด้วยอุ้งมือของตน และวัดฟ้าสวรรค์ด้วยคืบเดียว บรรจุผงคลีของแผ่นดินโลกไว้ในถังเดียว และชั่งภูเขาในตาชั่งและชั่งเนินด้วยตราชู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 13, 'ผู้ใดได้นําทางพระวิญญาณของพระเยโฮวาห์ หรือเป็นที่ปรึกษาของพระองค์ได้สั่งสอนพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 14, 'พระองค์ทรงปรึกษาผู้ใด ผู้ใดสั่งสอนพระองค์ และผู้ใดสอนทางแห่งความยุติธรรมให้พระองค์ และสอนความรู้แก่พระองค์ และสําแดงให้พระองค์เห็นทางแห่งความเข้าใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 15, 'ดูเถิด บรรดาประชาชาติก็เหมือนน้ําหยดหนึ่งจากถัง และนับว่าเหมือนผงบนตาชั่ง ดูเถิด พระองค์ทรงหยิบเกาะทั้งหลายขึ้นมาเหมือนสิ่งเล็กน้อย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 16, 'เลบานอนไม่พอเป็นฟืน และสัตว์ป่านั้นก็ไม่พอเป็นเครื่องเผาบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 17, 'ต่อพระพักตร์พระองค์บรรดาประชาชาติทั้งสิ้นก็เหมือนไม่มีอะไรเลย พระองค์ทรงนับว่าเขาน้อยยิ่งกว่าความว่างเปล่าและการไร้ประโยชน์ใดๆทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 18, 'ท่านจะเปรียบพระเจ้าเหมือนผู้ใด หรือเปรียบพระองค์คล้ายกับอะไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 19, 'รูปเคารพสลักน่ะหรือ ช่างเขาหล่อมันไว้ ช่างทองเอาทองคําปิดไว้และหล่อสร้อยเงินให้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 20, 'เขาผู้ที่ยากจนจนเขาไม่มีเครื่องบูชาเลยก็เลือกต้นไม้ที่จะไม่ผุ เขาเสาะหาช่างที่มีฝีมือมาตกแต่งให้เป็นรูปเคารพสลักที่ไม่เคลื่อนไหว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 21, 'ท่านทั้งหลายไม่เคยรู้หรือ ท่านไม่เคยได้ยินหรือ ไม่มีผู้ใดบอกท่านตั้งแต่แรกแล้วหรือ ท่านไม่เข้าใจตั้งแต่รากฐานของแผ่นดินโลกหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 22, 'คือพระองค์ผู้ประทับเหนือขอบวงกลมของแผ่นดินโลก และชาวแผ่นดินโลกก็เหมือนอย่างตั๊กแตน ผู้ทรงขึงฟ้าสวรรค์เหมือนขึงม่าน และกางออกเหมือนเต็นท์ที่อาศัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 23, 'ผู้ทรงกระทําเจ้านายให้เป็นศูนย์เปล่า และทรงกระทําให้ผู้ครอบครองแผ่นดินโลกเป็นเหมือนศูนยภาพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 24, 'พอปลูกเขาเหล่านั้นเสร็จ พอหว่านเสร็จ พอที่รากหยั่งลง พระองค์ก็จะเป่ามาบนเขา เขาก็จะเหี่ยวแห้งไป และลมหมุนก็จะพัดพาเขาไปเหมือนตอข้าว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 25, 'องค์บริสุทธิ์ตรัสว่า “เจ้าจะเปรียบเรากับผู้ใดเล่าซึ่งเราจะเหมือนเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 26, 'จงแหงนหน้าขึ้นดูว่า ผู้ใดสร้างสิ่งเหล่านี้ พระองค์ผู้ทรงนําบริวารออกมาตามจํานวน เรียกชื่อมันทั้งหมดโดยอานุภาพอันยิ่งใหญ่ของพระองค์ และเพราะพระองค์ทรงฤทธิ์เข้มแข็งจึงไม่ขาดไปสักดวงเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 27, 'โอ ยาโคบเอ๋ย ทําไมเจ้าจึงว่า โอ อิสราเอลเอ๋ย ทําไมจึงพูดว่า “ทางของข้าพเจ้าปิดบังไว้จากพระเยโฮวาห์ และความยุติธรรมอันควรตกแก่ข้าพเจ้านั้นก็ผ่านพระเจ้าของข้าพเจ้าไปเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 28, 'ท่านไม่เคยรู้หรือ ท่านไม่เคยได้ยินหรือ พระเยโฮวาห์ทรงเป็นพระเจ้าเนืองนิตย์ คือพระผู้สร้างที่สุดปลายแผ่นดินโลก พระองค์มิได้ทรงอ่อนเปลี้ย หรือเหน็ดเหนื่อย ความเข้าพระทัยของพระองค์ก็เหลือที่จะหยั่งรู้ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 29, 'พระองค์ทรงประทานกําลังแก่คนอ่อนเปลี้ย และแก่ผู้ที่ไม่มีกําลัง พระองค์ทรงเพิ่มแรง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 30, 'แม้คนหนุ่มๆจะอ่อนเปลี้ยและเหน็ดเหนื่อย และชายฉกรรจ์จะล้มลงทีเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 31, 'แต่เขาทั้งหลายผู้รอคอยพระเยโฮวาห์จะเสริมเรี่ยวแรงใหม่ เขาจะบินขึ้นด้วยปีกเหมือนนกอินทรี เขาจะวิ่งและไม่เหน็ดเหนื่อย เขาจะเดินและไม่อ่อนเปลี้ย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 1, 'โอ เกาะทั้งหลายเอ๋ย จงสงบใจต่อหน้าเรา จงให้ชนชาติทั้งหลายฟื้นกําลังของเขาเสียใหม่ ให้เขาเข้ามาใกล้ แล้วให้เขาพูด ให้เราพากันเข้ามาใกล้เพื่อการพิพากษา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 2, 'ใครได้เร้าใจให้คนชอบธรรมมาจากตะวันออก ได้เรียกท่านให้ติดตาม ได้มอบบรรดาประชาชาติต่อหน้าท่าน และให้ท่านครอบครองเหนือกษัตริย์ทั้งหลาย ได้มอบพวกเขาไว้แก่ดาบของท่านเหมือนผงคลี และแก่คันธนูของท่านเหมือนตอข้าวที่ถูกพัดไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 3, 'ท่านไล่ตามพวกเขาและผ่านเขาไปอย่างปลอดภัย ตามทางที่เท้าของท่านไม่เคยเหยียบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 4, 'ผู้ใดได้ประกอบกิจและกระทําเช่นนี้ เรียกบรรดาชั่วอายุทั้งหลายออกมาตั้งแต่เดิม เราเองคือพระเยโฮวาห์ผู้เป็นปฐม และกับกาลอวสาน เราคือผู้นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 5, 'เกาะทั้งหลายเห็นแล้วก็เกรงกลัว ปลายแผ่นดินโลกก็กลัว เขาทั้งหลายได้เข้ามาใกล้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 6, 'ทุกคนช่วยเพื่อนบ้านของตน และทุกคนกล่าวแก่พี่น้องของตนว่า “จงกล้าเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 7, 'ช่างไม้ก็หนุนใจช่างทอง ผู้ที่ทําให้เรียบด้วยค้อนก็หนุนใจผู้ที่ตีทั่งว่า “พร้อมแล้วสําหรับการบัดกรี” และเขาก็เอาตะปูตรึงไว้เพื่อไม่ให้หวั่นไหว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 8, 'แต่เจ้า อิสราเอล เป็นผู้รับใช้ของเรา ยาโคบผู้ซึ่งเราได้เลือกไว้ เชื้อสายของอับราฮัมสหายของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 9, 'เจ้าผู้ซึ่งเรายึดไว้จากที่สุดปลายแผ่นดินโลก และเรียกเจ้ามาจากพวกผู้ใหญ่ของโลก กล่าวแก่เจ้าว่า “เจ้าเป็นผู้รับใช้ของเรา เราได้เลือกเจ้าและไม่เหวี่ยงเจ้าออกไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 10, 'อย่ากลัวเลย เพราะเราอยู่กับเจ้า อย่าขยาด เพราะเราเป็นพระเจ้าของเจ้า เราจะหนุนกําลังเจ้า เออ เราจะช่วยเจ้า เออ เราจะชูเจ้าด้วยมือขวาแห่งความชอบธรรมของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 11, 'ดูเถิด บรรดาผู้ที่ขัดเคืองกับเจ้าจะต้องได้ความอายและอดสู เขาจะเป็นความว่างเปล่า คนเหล่านั้นที่ฝืนสู้เจ้าจะพินาศไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 12, 'เจ้าจะแสวงหาพวกเขา แต่เจ้าจะไม่พบเขา คือผู้ที่ต่อสู้กับเจ้า ผู้ที่ทําสงครามกับเจ้าจะเป็นความว่างเปล่าและเป็นสิ่งไร้ค่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 13, 'เพราะเราคือพระเยโฮวาห์พระเจ้าของเจ้า จะยึดมือขวาของเจ้าไว้ คือเราเองพูดกับเจ้าว่า “อย่ากลัวเลย เราจะช่วยเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 14, 'พระเยโฮวาห์ตรัสว่า “อย่ากลัวเลย เจ้าหนอนยาโคบ เจ้าคนอิสราเอล เราจะช่วยเจ้า ผู้ไถ่ของเจ้าคือองค์บริสุทธิ์แห่งอิสราเอล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 15, 'ดูเถิด เราจะกระทําเจ้าให้เป็นเลื่อนนวดข้าวใหม่ คม และมีฟัน เจ้าจะนวดและบดภูเขา และเจ้าจะทําเนินเขาให้เหมือนแกลบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 16, 'เจ้าจะซัดมันและลมจะพัดมันไปเสีย และลมหมุนจะกระจายมัน และเจ้าจะเปรมปรีดิ์ในพระเยโฮวาห์ เจ้าจะอวดอ้างในองค์บริสุทธิ์แห่งอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 17, 'เมื่อคนจนและคนขัดสนแสวงหาน้ําและไม่มี และลิ้นของเขาก็แห้งผากเพราะความกระหาย เราคือพระเยโฮวาห์จะได้ยินเขาเอง เรา พระเจ้าของอิสราเอล จะไม่ละทิ้งเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 18, 'เราจะเปิดแม่น้ําบนที่สูงทั้งหลาย และน้ําพุที่ท่ามกลางหุบเขา เราจะทําถิ่นทุรกันดารให้เป็นสระน้ํา และที่ดินแห้งเป็นน้ําพุ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 19, 'ในถิ่นทุรกันดารเราจะปลูกต้นสนสีดาร์ ต้นกระถินเทศ ต้นน้ํามันเขียว และต้นมะกอกเทศ ในทะเลทรายเราจะวางต้นสนสามใบ ทั้งต้นสนเขาและต้นไม้ที่เขียวชะอุ่มตลอดปีด้วยกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 20, 'เพื่อคนจะได้เห็นและทราบ เขาจะใคร่ครวญและเข้าใจด้วยกัน ว่าพระหัตถ์ของพระเยโฮวาห์ได้ทรงกระทําการนี้ องค์บริสุทธิ์แห่งอิสราเอลได้สร้างสิ่งนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 21, 'พระเยโฮวาห์ตรัสว่า “จงนําข้อคดีของเจ้าขึ้นมา” กษัตริย์ของยาโคบตรัสว่า “จงนําข้อพิสูจน์ของเจ้ามา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 22, 'ให้เขานํามา และแจ้งแก่เราว่าจะเกิดอะไรขึ้น จงแจ้งสิ่งล่วงแล้วให้เราทราบว่ามีอะไรบ้าง เพื่อเราจะพิจารณา เพื่อเราจะทราบถึงอวสานของสิ่งเหล่านั้น หรือจงเล่าให้เราฟังถึงสิ่งที่จะบังเกิดมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 23, 'จงแจ้งแก่เราว่าต่อไปนี้อะไรจะเกิดขึ้น เพื่อเราจะรู้ว่าเจ้าเป็นพระ เออ จงทําดีหรือจงทําร้าย เพื่อเราจะได้ขยาดและดูกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 24, 'ดูเถิด เจ้าไม่มีค่าอะไรเลยและการงานของเจ้าก็สูญเปล่า ผู้ที่เลือกเจ้าก็เป็นที่น่าสะอิดสะเอียน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 25, 'เราได้เร้าผู้หนึ่งจากทิศเหนือและเขาจะมา จากที่ดวงอาทิตย์ขึ้น เขาจะเรียกนามของเรา เขาจะเหยียบผู้ครอบครองเหมือนเหยียบปูนสอ เหมือนช่างหม้อย่ําดินเหนียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 26, 'ใครแจ้งไว้ตั้งแต่เริ่มแรก เพื่อเราจะทราบ และล่วงหน้าเพื่อเราจะพูดว่า “เขาชอบธรรม” เออ ไม่มีผู้ใดได้แจ้งให้ทราบ เออ ไม่มีผู้ใดได้เล่าให้ฟัง เออ ไม่มีผู้ใดได้ยินถ้อยคําของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 27, 'คนแรกจะกล่าวแก่ศิโยนว่า “ดูเถิด ดูเขาทั้งหลาย” และเราจะส่งผู้นําข่าวดีให้แก่เยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 28, 'แต่เมื่อเรามองก็ไม่มีใคร ไม่มีที่ปรึกษาในหมู่พวกคนเหล่านี้ คือผู้ที่เมื่อเราถามก็ได้ให้คําตอบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 29, 'ดูเถิด พระเหล่านั้นไร้ประโยชน์ทั้งสิ้น บรรดากิจการของมันก็เป็นความว่างเปล่า รูปเคารพหล่อของมันก็เป็นแต่ลมและความยุ่งเหยิง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 1, 'จงดูผู้รับใช้ของเรา ผู้ซึ่งเราเชิดชู ผู้เลือกสรรของเรา ผู้ซึ่งใจเราปีติยินดี เราได้เอาวิญญาณของเราสวมท่านไว้แล้ว ท่านจะส่งความยุติธรรมออกไปให้แก่บรรดาประชาชาติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 2, 'ท่านจะไม่ร้องหรือเปล่งเสียงของท่าน หรือกระทําให้ได้ยินเสียงของท่านตามถนน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 3, 'ไม้อ้อช้ําแล้วท่านจะไม่หัก และไส้ตะเกียงที่ลุกริบหรี่อยู่ท่านจะไม่ดับ ท่านจะส่งความยุติธรรมออกไปด้วยความจริง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 4, 'ท่านจะไม่ล้มเหลวหรือท้อแท้จนกว่าท่านจะสถาปนาความยุติธรรมไว้ในโลก และเกาะทั้งหลายจะรอคอยพระราชบัญญัติของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 5, 'พระเจ้า คือ พระเยโฮวาห์ผู้ทรงสร้างฟ้าสวรรค์และทรงขึงมัน ผู้ทรงแผ่แผ่นดินโลกและสิ่งที่บังเกิดจากโลกออกไป ผู้ทรงประทานลมหายใจแก่ประชาชนที่บนโลก และจิตวิญญาณแก่ผู้ดําเนินอยู่บนโลก ตรัสดังนี้ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 6, '“เราคือพระเยโฮวาห์ เราได้เรียกเจ้ามาด้วยความชอบธรรม เราจะยึดมือเจ้าและจะรักษาเจ้าไว้ เราจะให้เจ้าเป็นตัวพันธสัญญาของมนุษยชาติ เป็นความสว่างแก่บรรดาประชาชาติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 7, 'เพื่อเบิกตาคนที่ตาบอด เพื่อนําผู้ถูกจองจําออกมาจากคุก นําผู้ที่นั่งในความมืดออกมาจากเรือนจํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 8, 'เราคือเยโฮวาห์ นั่นเป็นนามของเรา สง่าราศีของเรา เรามิได้ให้แก่ผู้อื่น หรือให้คําที่สรรเสริญเราแก่รูปแกะสลัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 9, 'ดูเถิด สิ่งล่วงแล้วนั้นก็สําเร็จแล้ว และเราก็แจ้งสิ่งใหม่ๆ ก่อนที่สิ่งเหล่านั้นจะเกิดขึ้นเราก็ได้เล่าให้ฟังแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 10, 'จงร้องเพลงบทใหม่ถวายพระเยโฮวาห์ จงสรรเสริญพระองค์จากปลายแผ่นดินโลก ทั้งผู้ที่ลงไปยังทะเล และบรรดาสิ่งที่อยู่ในนั้น ทั้งเกาะทั้งหลายและชาวถิ่นนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 11, 'จงให้ถิ่นทุรกันดารและหัวเมืองในนั้นเปล่งเสียง ทั้งชนบทที่เคดาร์อาศัยอยู่ จงให้ชาวศิลาร้องเพลง ให้เขาโห่ร้องมาจากยอดภูเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 12, 'จงให้เขาถวายสง่าราศีแด่พระเยโฮวาห์ และถวายสรรเสริญพระองค์ในเกาะทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 13, 'พระเยโฮวาห์จะเสด็จออกไปอย่างคนแกล้วกล้า พระองค์จะทรงเร้าความหึงหวงของพระองค์ขึ้นอย่างนักรบ พระองค์จะทรงร้อง พระองค์จะทรงโห่ดัง พระองค์จะทรงมีชัยต่อศัตรูของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 14, 'เราได้นิ่งอยู่นานแล้ว เราเงียบอยู่และรั้งตนเองไว้ บัดนี้เราจะร้องออกมาเหมือนผู้หญิงกําลังคลอดบุตร เราจะสังหารผลาญและทําลายสิ้นทันที');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 15, 'เราจะทิ้งภูเขาและเนินให้ร้าง และให้บรรดาพืชผักบนนั้นแห้งไป เราจะให้แม่น้ํากลายเป็นเกาะ และจะให้สระแห้งไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 16, 'เราจะจูงคนตาบอดไปในทางที่เขาทั้งหลายไม่รู้จัก เราจะนําเขาไปในทางทั้งหลายที่เขาไม่รู้จัก เราจะให้ความมืดข้างหน้าเขากลับเป็นสว่าง สิ่งที่คดให้ตรง สิ่งเหล่านี้เป็นสิ่งที่เราจะกระทําแก่พวกเขา และเราจะไม่ละทิ้งพวกเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 17, 'เขาทั้งหลายจะหันกลับ และจะต้องขายหน้าอย่างที่สุด คือผู้ที่วางใจในรูปแกะสลัก ผู้ที่กล่าวแก่รูปเคารพหล่อว่า “ท่านเป็นพระของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 18, 'ท่านผู้หูหนวกเอ๋ย ฟังซิ และท่านผู้ตาบอดเอ๋ย มองซิ เพื่อท่านจะเห็นได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 19, 'ใครเป็นคนตาบอด ก็ผู้รับใช้ของเราน่ะซิ หรือใครหูหนวกอย่างกับทูตของเราที่เราใช้ไป ใครตาบอดอย่างผู้ที่สมบูรณ์แล้ว หรือตาบอดอย่างผู้รับใช้ของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 20, 'เจ้าเห็นหลายอย่าง แต่มิได้สังเกต หูของเขาเปิดแล้ว แต่เขามิได้ยิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 21, 'เพราะเห็นแก่ความชอบธรรมของพระองค์ พระเยโฮวาห์ทรงพอพระทัย ที่จะเชิดชูพระราชบัญญัติและกระทําให้พระราชบัญญัตินั้นมีเกียรติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 22, 'แต่นี่เป็นชนชาติที่ถูกขโมยและถูกปล้น เขาทุกคนติดอยู่ในรูและซ่อนอยู่ในคุก เขาตกเป็นเหยื่อซึ่งไม่มีผู้ใดช่วยให้พ้น เป็นของริบซึ่งไม่มีผู้ใดพูดว่า “คืนซิ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 23, 'ผู้ใดในพวกเจ้าจะเงี่ยหูฟังในเรื่องนี้ ที่จะมุ่งหน้าตั้งใจฟังในอนาคต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 24, 'ใครได้มอบยาโคบให้เป็นของริบ และอิสราเอลให้แก่ผู้ปล้น ไม่ใช่พระเยโฮวาห์หรือ ผู้ซึ่งเราได้ทําบาปต่อพระองค์ ซึ่งเขาไม่ยอมดําเนินในทางของพระองค์ และซึ่งเขามิได้เชื่อฟังพระราชบัญญัติของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 25, 'ฉะนั้นพระองค์จึงทรงหลั่งความโกรธจัดลงมาบนเขา และหลั่งอานุภาพของสงคราม ทําให้เขาติดเพลิงอยู่โดยรอบ แต่เขาไม่รู้ มันไหม้เขา แต่เขามิได้เอาใจใส่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 1, 'บัดนี้ พระเยโฮวาห์ผู้ได้สร้างท่าน โอ ยาโคบ พระองค์ผู้ได้ทรงปั้นท่าน โอ อิสราเอล ตรัสดังนี้ว่า “อย่ากลัวเลย เพราะเราได้ไถ่เจ้าแล้ว เราได้เรียกเจ้าตามชื่อ เจ้าเป็นของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 2, 'เมื่อเจ้าลุยข้ามน้ํา เราจะอยู่กับเจ้า เมื่อข้ามแม่น้ํา น้ําจะไม่ท่วมเจ้า เมื่อเจ้าลุยไฟ เจ้าจะไม่ไหม้และเปลวเพลิงจะไม่เผาผลาญเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 3, 'เพราะเราเป็นพระเยโฮวาห์พระเจ้าของเจ้า องค์บริสุทธิ์แห่งอิสราเอล ผู้ช่วยให้รอดของเจ้า เราให้อียิปต์เป็นค่าไถ่ของเจ้า ให้เอธิโอเปียและเส-บาเพื่อแลกกับเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 4, 'เพราะว่าเจ้าประเสริฐในสายตาของเรา เจ้าได้รับเกียรติและเรารักเจ้า เราจึงให้คนเพื่อแลกกับเจ้า และให้ชนชาติทั้งหลายเพื่อแลกกับชีวิตของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 5, 'อย่ากลัวเลย เพราะเราอยู่กับเจ้า เราจะนําเชื้อสายของเจ้ามาจากตะวันออก และเราจะรวบรวมเจ้ามาจากตะวันตก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 6, 'เราจะพูดกับทิศเหนือว่า ‘ปล่อยเถิด’ และกับทิศใต้ว่า ‘อย่ายึดไว้’ จงนําบรรดาบุตรชายของเรามาแต่ไกล และเหล่าธิดาของเราจากปลายแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 7, 'คือทุกคนที่เขาเรียกตามนามของเรา เพราะเราได้สร้างเขาเพื่อสง่าราศีของเรา เราได้ปั้นเขา เออ เราได้สร้างเขาไว้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 8, 'จงนําประชาชาติทั้งหลายผู้ตาบอดแต่ยังมีตา ผู้ที่หูหนวกแต่เขายังมีหู ออกมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 9, 'ให้บรรดาประชาชาติประชุมพร้อมกัน และให้ชนชาติทั้งหลายชุมนุมกัน ในท่ามกลางเขามีผู้ที่แจ้งอย่างนี้ได้ และเล่าสิ่งล่วงแล้วให้เราฟังได้ ให้เขาทั้งหลายนําพยานของเขามาพิสูจน์ตัวเขา และให้เขาได้ยินและกล่าวว่า “จริงแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 10, 'พระเยโฮวาห์ตรัสว่า “เจ้าทั้งหลายเป็นพยานของเรา และเป็นผู้รับใช้ของเราซึ่งเราได้เลือกไว้แล้ว เพื่อเจ้าจะรู้จักและเชื่อถือเรา และเข้าใจว่าเราเป็นผู้นั้นแหละ ก่อนหน้าเรา ไม่มีพระเจ้าใดถูกปั้นขึ้น และภายหลังเราก็จะไม่มี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 11, 'เรา เราคือพระเยโฮวาห์ และนอกจากเราไม่มีพระผู้ช่วยให้รอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 12, 'เมื่อไม่มีพระอื่นในหมู่พวกเจ้า เราแจ้งให้ทราบและช่วยให้รอดและพิสูจน์ให้เห็น ฉะนั้นเจ้าทั้งหลายเป็นพยานของเราว่าเราเป็นพระเจ้า” พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 13, '“เออ ตั้งแต่เดิมเราก็เป็นพระองค์นั้นอยู่ ไม่มีผู้ใดช่วยให้พ้นจากมือของเราได้ เราจะประกอบกิจใดๆ ใครจะขัดขวางกิจการนั้นได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 14, 'พระเยโฮวาห์ผู้ไถ่ของเจ้า องค์บริสุทธิ์ของอิสราเอลตรัสดังนี้ว่า “เพื่อเห็นแก่เจ้า เราจะส่งไปยังบาบิโลน และเราจะนําบรรดาขุนนางของเขาลงมา คือพวกเคลเดียในกําปั่นที่เขาทั้งหลายเคยโห่ร้อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 15, 'เราคือพระเยโฮวาห์ องค์บริสุทธิ์ของเจ้า เป็นผู้สร้างของอิสราเอล เป็นกษัตริย์ของเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 16, 'พระเยโฮวาห์ ผู้ทรงสร้างทางในทะเล สร้างวิถีในน้ําที่มีอานุภาพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 17, 'ผู้ทรงนํารถรบและม้า กองทัพ และอานุภาพออกมา เขาทั้งหลายนอนลงด้วยกันและลุกขึ้นไม่ได้ เขาทั้งหลายสูญไปและดับเสียเหมือนไส้ตะเกียง ตรัสดังนี้ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 18, '“อย่าจดจําสิ่งล่วงแล้วนั้น อย่าพิเคราะห์สิ่งเก่าก่อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 19, 'ดูเถิด เราจะกระทําสิ่งใหม่ บัดนี้จะงอกขึ้นมาแล้ว เจ้าจะไม่เห็นหรือ เราจะทําทางในถิ่นทุรกันดารและแม่น้ําในที่แห้งแล้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 20, 'สัตว์ป่าในทุ่งจะให้เกียรติเรา คือมังกรและนกเค้าแมว เพราะเราให้น้ําในถิ่นทุรกันดาร ให้แม่น้ําในที่แห้งแล้ง เพื่อให้น้ําดื่มแก่ชนชาติผู้เลือกสรรของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 21, 'คือชนชาติที่เราปั้นเพื่อเราเอง เพื่อเขาจะถวายสรรเสริญเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 22, 'โอ ยาโคบเอ๋ย ถึงกระนั้นก็ไม่ใช่เราที่เจ้าเรียกหา โอ อิสราเอลเอ๋ย เจ้าเหน็ดเหนื่อยเราแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 23, 'เจ้ามิได้นําแพะแกะของเจ้ามาเป็นเครื่องเผาบูชาแก่เรา หรือให้เกียรติเราด้วยเครื่องสักการบูชาของเจ้า เรามิได้ให้เป็นภาระแก่เจ้าด้วยเรื่องเครื่องบูชา หรือให้เจ้าเหน็ดเหนื่อยด้วยเรื่องกํายาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 24, 'เจ้ามิได้เอาเงินซื้ออ้อยให้เรา หรือให้เราพอใจด้วยไขมันของเครื่องสักการบูชาของเจ้า แต่เจ้าได้ให้เราเป็นภาระด้วยเรื่องบาปของเจ้า เจ้าให้เราเหน็ดเหนื่อยด้วยเรื่องความชั่วช้าของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 25, 'เรา เราคือพระองค์นั้นผู้ลบล้างความละเมิดของเจ้าด้วยเห็นแก่เราเอง และเราจะไม่จดจําบรรดาบาปของเจ้าไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 26, 'จงฟื้นความให้เราฟัง ให้เรามาโต้ด้วยกัน เจ้าจงให้การมา เพื่อจะพิสูจน์ว่าเจ้าถูก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 27, 'บิดาเดิมของเจ้าทําบาป และผู้สอนทั้งหลายของเจ้าได้ละเมิดต่อเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 28, 'ฉะนั้น เราจึงถอดเจ้านายแห่งสถานบริสุทธิ์เสีย เรามอบยาโคบให้ถูกสาปแช่ง และอิสราเอลให้แก่การกล่าวหยาบช้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 1, '“โอ ยาโคบผู้รับใช้ของเรา อิสราเอลผู้ซึ่งเราเลือกสรรไว้ จงฟังซิ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 2, 'พระเยโฮวาห์ผู้ทรงสร้างเจ้า ผู้ทรงปั้นเจ้าตั้งแต่ในครรภ์และจะช่วยเจ้า ตรัสดังนี้ว่า “โอ ยาโคบผู้รับใช้ของเรา เยชูรูน ผู้ซึ่งเราเลือกสรรไว้ อย่ากลัวเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 3, 'เพราะเราจะเทน้ําลงบนผู้ที่กระหาย และลําธารลงบนดินแห้ง เราจะเทวิญญาณของเราเหนือเชื้อสายของเจ้า และพรของเราเหนือลูกหลานของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 4, 'เขาทั้งหลายจะงอกขึ้นมาท่ามกลางหญ้า เหมือนต้นหลิวข้างลําธารน้ําไหล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 5, 'ผู้นี้จะว่า ‘ข้าเป็นของพระเยโฮวาห์’ และอีกผู้หนึ่งจะเรียกชื่อตนเองด้วยนามของยาโคบ และอีกผู้หนึ่งจะเขียนไว้บนมือของตนว่า ‘ของพระเยโฮวาห์’ และขนานนามสกุลของตนด้วยนามของอิสราเอล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 6, 'พระเยโฮวาห์ พระบรมมหากษัตริย์แห่งอิสราเอล และผู้ไถ่ของเขา พระเยโฮวาห์จอมโยธา ตรัสดังนี้ว่า “เราเป็นผู้ต้นและเราเป็นผู้ปลาย นอกจากเราแล้วไม่มีพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 7, 'ใครเหมือนเราจะป่าวร้องได้ ให้เขาแจ้งให้ทราบ และให้เขาลําดับเรื่องต่อหน้าเราตั้งแต่เราได้สถาปนาประชาชนโบราณ และให้เขาบอกแก่เขาทั้งหลายถึงสิ่งต่างๆที่จะเป็นมาและอะไรจะเกิดขึ้นนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 8, 'อย่ากลัวเลย และอย่าขามเลย เรามิได้เล่าให้เจ้าฟังตั้งแต่ดึกดําบรรพ์และแจ้งให้ทราบแล้วหรือ และเจ้าเป็นพยานทั้งหลายของเรา มีพระเจ้านอกเหนือเราหรือ เออ ไม่มีพระเจ้า เราไม่รู้จักเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 9, 'บรรดาผู้ที่ทํารูปเคารพสลักต่างก็ไร้ประโยชน์ใดๆทั้งสิ้น และสิ่งที่เขาปีติยินดีนั้นก็ไม่เป็นประโยชน์ เขาเป็นพยานของเขาเอง พยานเหล่านั้นทั้งไม่เห็นและไม่รู้ เพื่อเขาจะต้องอับอาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 10, 'ใครเล่าปั้นพระหรือหล่อรูปเคารพสลักซึ่งไม่เป็นประโยชน์อะไรเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 11, 'ดูเถิด เพื่อนทั้งสิ้นของเขาจะต้องอับอาย และช่างฝีมือนั้นก็เป็นแต่มนุษย์ ให้เขาชุมนุมกันทั้งหมด ให้เขายืนขึ้น เขาจะสยดสยอง เขาจะรับความอับอายด้วยกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 12, 'ช่างเหล็กใช้คีมทํางานอยู่เหนือก้อนถ่าน และใช้ค้อนทุบมันด้วยแขนที่แข็งแรงของเขา เออ เขาหิวและกําลังของเขาอ่อนลง เขาไม่ได้ดื่มน้ําเลย และอ่อนเปลี้ย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 13, 'ช่างไม้ขึงเชือกวัด เขาเอาดินสอขีดไว้ เขาแต่งมันด้วยกบ และขีดไว้ด้วยวงเวียน เขาแต่งรูปนั้นให้เป็นรูปคน ตามความงามของคน ให้อยู่ในเรือน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 14, 'เขาตัดต้นสนสีดาร์ลง เขาเลือกต้นสนจีนและต้นโอ๊ก และปล่อยให้มันงอกขึ้นอย่างแข็งแรงท่ามกลางต้นไม้ในป่า เขาปลูกต้นแอชและฝนก็เลี้ยงมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 15, 'แล้วมนุษย์จะเอาไปเผาเสีย เขาเอามันมาส่วนหนึ่งและให้อบอุ่นตัวเขา เออ เขาก่อไฟและปิ้งขนมปัง และเขาเอามาทําพระองค์หนึ่งและนมัสการมันด้วย เออ เขาทําเป็นรูปแกะสลักและกราบรูปนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 16, 'เขาเผาในกองไฟครึ่งหนึ่ง บนครึ่งนี้เขาได้กินเนื้อ เขาย่างเนื้อและกินอิ่ม และเขาอบอุ่นตัวของเขาด้วย แล้วว่า “อ้าฮา ข้าอุ่นจัง ข้าเห็นไฟแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 17, 'และที่เหลือนั้นเขาทําเป็นพระองค์หนึ่ง เป็นรูปเคารพสลักของเขา และกราบลงนมัสการรูปนั้น และอธิษฐานต่อรูปนั้นและว่า “ขอทรงช่วยข้าพระองค์ให้พ้น เพราะพระองค์เป็นพระของข้าพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 18, 'เขาทั้งหลายไม่รู้ หรือเขาทั้งหลายไม่เข้าใจ เพราะตาของเขาถูกปิด เขาจึงเห็นอะไรไม่ได้ และจิตใจของเขาเล่าก็ถูกปิด เขาจึงเข้าใจไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 19, 'ไม่มีใครพินิจพิเคราะห์ในใจของตนเลย และไม่มีความรู้หรือความเข้าใจ ที่จะกล่าวว่า “ข้าได้เผามันเสียส่วนหนึ่งในกองไฟ และข้าก็เอาถ่านมันมาปิ้งขนมปัง ข้าย่างเนื้อกินแล้ว และควรหรือที่ข้าจะทําส่วนที่เหลือให้เป็นสิ่งน่าเกลียดน่าชัง ควรหรือที่ข้าจะกราบลงต่อท่อนไม้ท่อนหนึ่ง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 20, 'เขากินขี้เถ้า ใจที่หลอกลวงนําเขาให้เจิ่น เขาช่วยจิตใจตัวเขาเองให้พ้นหรือพูดว่า “ไม่มีความมุสาอยู่ในมือข้างขวาของข้าหรือ” ก็ไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 21, 'โอ ยาโคบและอิสราเอลเอ๋ย จงจําสิ่งเหล่านี้ เพราะเจ้าเป็นผู้รับใช้ของเรา เราได้ปั้นเจ้า เจ้าเป็นผู้รับใช้ของเรา โอ อิสราเอลเอ๋ย เราจะไม่ลืมเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 22, 'เราได้ลบล้างการละเมิดของเจ้าเสียเหมือนเมฆทึบ และลบล้างบาปของเจ้าเหมือนเมฆ จงกลับมาหาเรา เพราะเราได้ไถ่เจ้าแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 23, 'โอ ฟ้าสวรรค์เอ๋ย จงร้องเพลงเพราะพระเยโฮวาห์ทรงกระทําการนี้ ห้วงลึกของแผ่นดินโลกเอ๋ย จงโห่ร้อง ภูเขาเอ๋ย จงร้องเป็นเพลงออกมา โอ ป่าไม้เอ๋ย และต้นไม้ทุกต้นในนั้นด้วย เพราะว่าพระเยโฮวาห์ทรงไถ่ยาโคบ และจะทรงรับเกียรติในอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 24, 'พระเยโฮวาห์ผู้ไถ่ของเจ้า ผู้ปั้นเจ้าตั้งแต่ในครรภ์ ตรัสดังนี้ว่า “เราคือพระเยโฮวาห์ ผู้ทรงสร้างสิ่งสารพัด ผู้ทรงขึงฟ้าสวรรค์แต่ลําพัง ผู้ทรงกางแผ่นดินโลกด้วยตัวเราเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 25, 'ผู้กระทําให้ลางของคนมุสาไม่ขลัง และกระทําพวกโหรให้บ้าๆบอๆ ผู้หันคนฉลาดให้กลับหลัง และกระทําให้ความรู้ของเขาเขลาไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 26, 'ผู้รับรองถ้อยคําของผู้รับใช้ของพระองค์ และให้สัมฤทธิ์ผลตามแผนงานแห่งทูตของพระองค์ ผู้กล่าวถึงเยรูซาเล็มว่า ‘จะมีคนอาศัยอยู่’ และถึงหัวเมืองยูดาห์ว่า ‘จะมีคนมาสร้างขึ้น และเราจะยกสิ่งปรักหักพังของมันขึ้น’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 27, 'ผู้กล่าวแก่ที่ลึกว่า ‘จงแห้งเสีย เราจะให้แม่น้ําของเจ้าแห้ง’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 28, 'ผู้กล่าวถึงไซรัสว่า ‘เขาเป็นเมษบาลของเรา และเขาจะให้ความมุ่งหมายทั้งสิ้นของเราสําเร็จ’ กล่าวถึงเยรูซาเล็มว่า ‘จะมีคนมาสร้างเจ้าขึ้น’ และถึงพระวิหารว่า ‘จะวางรากฐานของเจ้า’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 1, 'พระเยโฮวาห์ตรัสกับผู้ที่พระองค์ทรงเจิมไว้คือไซรัส ผู้ซึ่งเราได้จับมือขวาไว้ เพื่อปราบหลายประชาชาติให้อยู่ข้างหน้าท่าน และให้ปลดรัดประคดจากบั้นเอวของบรรดากษัตริย์ ให้เปิดประตูทั้งสองที่อยู่ข้างหน้าท่านและมิให้ประตูเมืองปิด ดังนี้ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 2, '“เราจะไปข้างหน้าเจ้า และปราบที่คดให้เป็นที่ตรง เราจะพังประตูทองเหลืองให้เป็นชิ้นๆ และตัดลูกกรงเหล็กให้ขาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 3, 'เราจะให้ทรัพย์สมบัติแห่งความมืดแก่เจ้า และขุมทรัพย์ในที่ลี้ลับ เพื่อเจ้าจะได้รู้ว่า คือเรา พระเยโฮวาห์ พระเจ้าแห่งอิสราเอล ซึ่งเรียกเจ้าตามชื่อของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 4, 'เพื่อเห็นแก่ยาโคบผู้รับใช้ของเรา และอิสราเอลผู้เลือกสรรของเรา เราจึงเรียกเจ้าตามชื่อของเจ้า เราให้นามสกุลเจ้า ทั้งๆที่เจ้าไม่รู้จักเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 5, 'เราเป็นพระเยโฮวาห์ และไม่มีอื่นใดอีก นอกจากเราไม่มีพระเจ้า เราคาดเอวเจ้า แม้เจ้าไม่รู้จักเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 6, 'เพื่อคนจะได้รู้ตั้งแต่ที่ตะวันขึ้น และจากที่ตะวันตก ว่าไม่มีใครนอกจากเรา เราเป็นพระเยโฮวาห์ และไม่มีอื่นใดอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 7, 'เราปั้นความสว่างและสร้างความมืด เราทําสันติภาพและสร้างวิบัติ เราคือพระเยโฮวาห์ ผู้กระทําสิ่งเหล่านี้ทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 8, 'ฟ้าสวรรค์เอ๋ย จงโปรยฝนมาจากเบื้องบน และให้ท้องฟ้าหลั่งความชอบธรรมลงมา ให้แผ่นดินโลกเปิดออก เพื่อความรอดจะได้งอกขึ้นมา และยังความชอบธรรมให้พลุ่งขึ้นมาด้วย เรา คือพระเยโฮวาห์ได้สร้างมัน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 9, 'วิบัติแก่ผู้ที่ขืนสู้กับผู้สร้างของเขา จงให้หม้อดินสู้กับบรรดาช่างปั้นหม้อแห่งแผ่นดินโลก ดินเหนียวจะพูดกับผู้ที่ปั้นมันหรือว่า “ท่านกําลังทําอะไร” หรือผลงานของท่านจะว่า “ท่านไม่มีมือหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 10, 'วิบัติแก่ผู้ที่พูดกับบิดาว่า “ท่านให้เกิดอะไร” หรือกับผู้หญิงว่า “เธอคลอดอะไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 11, 'พระเยโฮวาห์ องค์บริสุทธิ์แห่งอิสราเอล ผู้สร้างของเขาตรัสดังนี้ว่า “เจ้าถามเราถึงสิ่งที่จะเกิดมีมาถึงลูกหลานของเรา และถึงการงานแห่งมือของเรา เจ้าสั่งเราเชียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 12, 'เราสร้างแผ่นดินโลก และเนรมิตมนุษย์บนนั้น เราเอง มือของเราขึงฟ้าสวรรค์ และเราบัญชาบริวารทั้งสิ้นของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 13, 'ด้วยความชอบธรรมเราได้เร้าท่าน และเราจะกระทําทางทั้งสิ้นของท่านให้ตรง ท่านจะสร้างนครของเรา และให้พวกเชลยของเราเป็นอิสระ ไม่ใช่เพื่อสินจ้างหรือเพื่อสินบน” พระเยโฮวาห์จอมโยธาตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 14, 'พระเยโฮวาห์ตรัสดังนี้ว่า “ผลแรงงานของอียิปต์และสินค้ากําไรของเอธิโอเปีย และคนเส-บา คนร่างสูงจะมาหาเจ้าและจะเป็นของเจ้า เขาจะติดตามเจ้า เขาจะติดตรวนมาหาและกราบไหว้เจ้า เขาจะวิงวอนเจ้าว่า ‘พระเจ้าอยู่กับท่านแน่ และไม่มีอื่นใดอีก ไม่มีพระเจ้าอื่น’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 15, 'แท้จริงพระองค์ทรงเป็นพระเจ้าผู้ทรงซ่อนพระองค์ โอ ข้าแต่พระเจ้าแห่งอิสราเอล พระผู้ช่วยให้รอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 16, 'เขาทุกคนต้องอับอายและขายหน้า ผู้สร้างรูปเคารพก็อดสูไปด้วยกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 17, 'แต่อิสราเอลนั้นพระเยโฮวาห์ทรงช่วยให้รอดด้วยความรอดเนืองนิตย์ เจ้าจะไม่ต้องอับอายหรือขายหน้าตลอดไปเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 18, 'เพราะพระเยโฮวาห์ ผู้ทรงสร้างฟ้าสวรรค์ พระเจ้าเองทรงปั้นแผ่นดินโลกและทํามันไว้ พระองค์ทรงสถาปนามันไว้ พระองค์มิได้ทรงสร้างมันไว้ให้ยุ่งเหยิง พระองค์ทรงปั้นมันไว้ให้มีคนอาศัย ตรัสดังนี้ว่า “เราคือพระเยโฮวาห์ และไม่มีอื่นใดอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 19, 'เรามิได้พูดในที่ลี้ลับ ในที่มืดแห่งแผ่นดินโลก เรามิได้กล่าวแก่เชื้อสายของยาโคบว่า ‘จงแสวงหาเราในที่ยุ่งเหยิง’ เราคือพระเยโฮวาห์พูดความชอบธรรม เราแจ้งสิ่งที่ถูกต้องให้ทราบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 20, 'จงชุมนุม และมา มาให้ใกล้กันเข้า คือเจ้าทั้งหลายผู้รอดพ้นแห่งบรรดาประชาชาติ เขาทั้งหลายไม่มีความรู้ คือผู้ที่ยกรูปเคารพสลักไม้ของเขาไป และอธิษฐานต่อพระซึ่งช่วยเขาให้รอดไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 21, 'จงแจ้งเรื่องและนําเข้ามาใกล้ เออ ให้เขาทั้งหลายปรึกษาหารือกัน ใครเล่าสิ่งนี้ให้ฟังนมนานแล้ว ใครแจ้งให้ทราบมาตั้งแต่เก่าก่อน ไม่ใช่เราหรือ คือพระเยโฮวาห์ นอกจากเราไม่มีพระเจ้าอื่นเลย พระเจ้าผู้ชอบธรรมและพระผู้ช่วยให้รอด ไม่มีอื่นใดนอกเหนือเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 22, 'มวลมนุษย์ทั่วแผ่นดินโลกเอ๋ย จงหันมาหาเราและรับการช่วยให้รอด เพราะเราเป็นพระเจ้า และไม่มีอื่นใดอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 23, 'เราได้ปฏิญาณโดยตัวเราเอง ถ้อยคําได้ออกไปจากปากของเราด้วยความชอบธรรมซึ่งจะไม่กลับว่า ‘หัวเข่าทุกหัวเข่าจะต้องคุกกราบลงต่อเรา และลิ้นทุกลิ้นจะต้องปฏิญาณต่อเรา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 24, 'แน่นอนผู้หนึ่งจะพูดว่า ‘ในพระเยโฮวาห์ข้ามีความชอบธรรมและอานุภาพ’ มนุษย์ทั้งหลายจะมาหาพระองค์ บรรดาผู้ที่แค้นเคืองต่อพระองค์จะอับอายขายหน้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 25, 'เชื้อสายทั้งสิ้นของอิสราเอลจะชอบธรรมและสดุดีภูมิใจในพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 1, '“พระเบลก็เลื่อนลง พระเนโบก็ทรุดลง ปฏิมากรของพระนี้อยู่บนสัตว์และวัว สิ่งเหล่านี้ที่เจ้าหามอยู่ก็มาบรรทุกเป็นภาระบนหลังสัตว์ที่เหน็ดเหนื่อย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 2, 'มันทรุดลงและมันเลื่อนลงด้วยกัน มันช่วยป้องกันภาระนั้นไม่ได้ มันเองก็ตกไปเป็นเชลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 3, 'โอ วงศ์วานของยาโคบเอ๋ย จงฟังเรา คือบรรดาคนที่เหลืออยู่ในวงศ์วานของอิสราเอล ผู้ซึ่งเราอุ้มมาตั้งแต่กําเนิด ชูมาตั้งแต่ในครรภ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 4, 'จนกระทั่งเจ้าแก่ เราก็คือพระองค์นั้น เราจะอุ้มเจ้าจนเจ้าถึงผมหงอก เราได้สร้าง เราจะชูไว้ เราจะอุ้มและเราจะช่วยให้พ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 5, 'เจ้าจะเทียบเราและทําเราให้เท่ากับผู้ใด และเปรียบเรา ว่าเราเหมือนกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 6, 'บรรดาผู้ที่โกยทองคําออกจากไถ้และชั่งเงินในตาชั่ง จ้างช่างทองคนหนึ่ง และเขาก็ทําให้เป็นพระ แล้วเขาทั้งหลายก็กราบลง เออ นมัสการเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 7, 'เขาทั้งหลายเอารูปนั้นใส่บ่า เขาหามไป เขาตั้งไว้ประจําที่ รูปนั้นก็อยู่ที่นั่น รูปนั้นไปจากที่ไม่ได้ แม้ผู้ใดจะมาร้องขอ รูปนั้นก็ไม่ตอบ หรือช่วยเขาให้รอดจากความยากลําบากของเขาได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 8, 'จําข้อนี้ไว้และจงเป็นลูกผู้ชายแท้ โอ เจ้าผู้ละเมิดทั้งหลาย จงนึกไว้ในใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 9, 'จงจําสิ่งล่วงแล้วในสมัยก่อนไว้ เพราะเราเป็นพระเจ้า และไม่มีอื่นใดอีก เราเป็นพระเจ้า และไม่มีอื่นใดเหมือนเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 10, 'ผู้แจ้งตอนจบให้ทราบตั้งแต่เริ่มต้น และแจ้งถึงสิ่งที่ยังไม่ได้ทําเลยให้ทราบตั้งแต่กาลโบราณ กล่าวว่า ‘แผนงานของเราจะยั่งยืน และเราจะกระทําให้ความประสงค์ของเราสําเร็จทั้งสิ้น’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 11, 'เรียกเหยี่ยวมาจากตะวันออก คือเรียกชายที่ทําตามแผนงานของเราจากเมืองไกล เออ เราพูดแล้ว และเราจะให้เป็นไป เรามุ่งแล้ว และเราจะกระทําด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 12, 'เจ้าผู้จิตใจดื้อดึง เจ้าผู้ห่างไกลจากความชอบธรรม จงฟังเราซิ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 13, 'เราจะนําความชอบธรรมของเรามาใกล้ มันจะไม่ไกลเลย และความรอดของเราจะไม่รอช้า เราจะใส่ความรอดที่ศิโยนเพื่ออิสราเอล สง่าราศีของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 1, 'โอ ธิดาพรหมจารีแห่งบาบิโลนเอ๋ย จงลงมานั่งในผงคลี โอ ธิดาแห่งชาวเคลเดียเอ๋ย จงนั่งลงบนพื้นดิน ไม่มีบัลลังก์ เพราะเขาจะไม่เรียกเจ้าอีกว่า แม่เนื้ออ่อนแม่เนื้อละเอียด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 2, 'จับโม่เข้า โม่แป้งซี เอาผ้าคลุมหน้าของเจ้าออกเสีย ถอดเสื้อคลุมของเจ้าเสีย ไม่ต้องคลุมขาของเจ้า ลุยน้ําไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 3, 'เจ้าจะต้องถูกเปลือยและเขาจะเห็นความอายของเจ้า เราจะทําการแก้แค้น และเราจะไม่พบเจ้าอย่างมนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 4, 'พระผู้ไถ่ของเรา พระนามของพระองค์คือ พระเยโฮวาห์จอมโยธา ทรงเป็นองค์บริสุทธิ์ของอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 5, 'โอ ธิดาแห่งชาวเคลเดียเอ๋ย นั่งเงียบๆ และจงเข้าไปในความมืด เพราะเขาจะไม่เรียกเจ้าอีกว่า นางพญาแห่งราชอาณาจักรทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 6, 'เรากริ้วต่อชนชาติของเรา เราทําให้มรดกของเราเป็นมลทิน เรามอบเขาไว้ในมือของเจ้า เจ้ามิได้แสดงความกรุณาต่อเขา เจ้าวางแอกอย่างหนักไว้บนบ่าของคนชรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 7, 'เจ้าว่า “ข้าจะเป็นนางพญาเป็นนิตย์” เจ้าจึงมิได้เอาเรื่องเหล่านี้เป็นที่สอนใจ หรือจดจําบั้นปลายของเรื่องเหล่านี้ไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 8, 'ฉะนั้น เจ้าผู้รักความเพลิดเพลิน จงฟังเรื่องนี้ คือผู้นั่งอย่างไร้กังวล ผู้คิดในใจของตนว่า “ข้านี่แหละ และไม่มีผู้ใดอื่นอีก ข้าจะไม่นั่งอยู่เป็นหญิงม่าย หรือรู้จักการสูญเสียลูก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 9, 'ทั้งสองเรื่องนี้จะมาถึงเจ้าในขณะเดียวกันในวันเดียว คือความที่ต้องพรากจากลูกและความที่เป็นหญิงม่าย จะมาถึงเจ้าอย่างเต็มขนาดทั้งที่มีวิทยาคมเป็นอันมาก และอานุภาพใหญ่ยิ่งในเวทมนตร์ของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 10, 'ด้วยว่าเจ้ารู้สึกมั่นอยู่ในความชั่วของเจ้า เจ้าว่า “ไม่มีผู้ใดเห็นข้า” สติปัญญาของเจ้าและความรู้ของเจ้าทําให้เจ้าเจิ่นไป และเจ้าจึงว่าในใจของเจ้าว่า “ข้านี่แหละ และไม่มีผู้ใดอื่นอีก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 11, 'ฉะนั้นความชั่วร้ายจะมาเหนือเจ้า ซึ่งเจ้าจะไม่รู้ว่ามันขึ้นมาจากไหน ความเลวร้ายจะตกใส่เจ้า ซึ่งเจ้าจะไม่สามารถถอดถอนได้ และความพินาศจะมาถึงเจ้าทันทีทันใด ซึ่งเจ้าไม่รู้เรื่องเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 12, 'จงตั้งมั่นอยู่ในเวทมนตร์ของเจ้า และวิทยาคมเป็นอันมากของเจ้า ซึ่งเจ้าทํามาหนักนักหนาตั้งแต่สาวๆ ชะรอยมันจะเป็นประโยชน์แก่เจ้าได้ ชะรอยเจ้าจะมีชัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 13, 'เจ้าเหน็ดเหนื่อยกับที่ปรึกษาเป็นอันมากของเจ้า ให้เขาลุกขึ้นออกมาและช่วยเจ้าให้รอด คือบรรดาผู้ที่แบ่งฟ้าสวรรค์และเพ่งดูดวงดาว ผู้ซึ่งทํานายให้เจ้าในแต่ละเดือนว่า จะเกิดอะไรขึ้นแก่เจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 14, 'ดูเถิด เขาจะเป็นเหมือนตอข้าว ไฟจะเผาผลาญเขา เขาจะช่วยตัวเขาเองให้พ้นจากกําลังของเปลวเพลิงไม่ได้ นี่ไม่ใช่ถ่านที่จะให้ใครอุ่น ไม่ใช่ไฟที่จะให้ใครผิง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 15, 'บรรดาที่เจ้าทํางานด้วยกันนั้นจะเป็นเช่นนี้แก่เจ้า ผู้ซึ่งค้ามากับเจ้าตั้งแต่สาวๆ เขาต่างจะพเนจรไปมาในทางของเขาเอง ไม่มีผู้ใดจะช่วยเจ้าให้รอดได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 1, 'ฟังข้อนี้ซิ โอ วงศ์วานของยาโคบเอ๋ย ผู้ซึ่งเขาเรียกด้วยนามของอิสราเอล และผู้ซึ่งออกมาจากน้ําทั้งหลายของยูดาห์ ผู้ซึ่งปฏิญาณในพระนามของพระเยโฮวาห์ และกล่าวถึงพระเจ้าของอิสราเอล แต่มิใช่ด้วยสัจจะและความชอบธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 2, 'เพราะเขาขนานนามของเขาเองตามนครบริสุทธิ์ และพึ่งอาศัยพระเจ้าของอิสราเอล พระนามของพระองค์ว่าพระเยโฮวาห์จอมโยธา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 3, '“สิ่งล่วงแล้วเราได้แจ้งให้ทราบแต่เก่าก่อน เออ มันไปจากปากของเรา และเราได้เล่าให้ฟังทั่วแล้ว ในทันใดนั้นเราก็ได้กระทําและก็เป็นไปตามนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 4, 'เพราะเรารู้อยู่ว่าเจ้าดื้อด้านและคอของเจ้าก็คือเอ็นเหล็ก และหน้าผากของเจ้าเป็นทองเหลือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 5, 'เราก็แจ้งเรื่องเหล่านั้นแก่เจ้าให้ทราบตั้งแต่เก่าก่อน ก่อนที่มันจะเกิดขึ้นเราก็ได้ว่าให้เจ้าฟังแล้ว เกรงเจ้าจะว่า ‘รูปเคารพของข้ากระทําเอง รูปเคารพสลักและรูปเคารพหล่อของข้าบัญชามันมา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 6, 'เจ้าได้ยินแล้ว จงคอยดูสิ่งทั้งปวงนี้ และเจ้าจะไม่แจ้งให้ทราบหรือ ตั้งแต่เวลานี้ไปเราเล่าสิ่งใหม่ให้เจ้าฟัง เป็นสิ่งที่ปิดซ่อนไว้ซึ่งเจ้าไม่รู้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 7, 'เป็นสิ่งที่สร้างขึ้นใหม่ ไม่ใช่ตั้งแต่เก่าก่อน ก่อนวันนี้เจ้าไม่เคยได้ยินถึง เกรงเจ้าจะพูดว่า ‘ดูเถิด เรารู้แล้ว’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 8, 'เออ เจ้าไม่เคยได้ยิน เออ เจ้าไม่เคยรู้ เออ ตั้งแต่เวลานั้นหูของเจ้ายังไม่เปิด เพราะเรารู้ว่าเจ้าจะประพฤติอย่างทรยศหนัก และรู้ว่า ตั้งแต่กําเนิดเขาเรียกเจ้าว่า ผู้ละเมิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 9, 'เพราะเห็นแก่นามของเรา เราจะหน่วงเหนี่ยวความกริ้วของเราไว้ เพราะเห็นแก่ความสรรเสริญของเรา เราจะระงับไว้เพื่อเจ้า เพื่อเราจะมิได้ตัดเจ้าออกไปเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 10, 'ดูเถิด เราได้ถลุงเจ้าแล้ว แต่ไม่ใช่ด้วยเงิน เราได้เลือกสรรเจ้าในเตาของความทุกข์ใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 11, 'เราจะกระทําเช่นนั้นเพราะเห็นแก่เราเอง เพราะเห็นแก่เราเอง เพราะว่านามของเราจะถูกเหยียดหยามอย่างไรได้ สง่าราศีของเรา เราจะไม่ให้ใครอื่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 12, 'ฟังเราซิ โอ ยาโคบเอ๋ย และอิสราเอล ผู้ซึ่งเราเรียก เราคือพระองค์ทีเดียว เราเป็นต้นและเราเป็นปลายด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 13, 'เออ มือของเราได้วางรากฐานแผ่นดินโลก และมือขวาของเราได้กางฟ้าสวรรค์ออก เมื่อเราเรียกมัน มันก็ออกมาอยู่ด้วยกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 14, 'เจ้าทั้งปวง จงชุมนุมกันและคอยฟัง ผู้ใดในท่ามกลางพวกนั้นได้ประกาศสิ่งเหล่านี้ พระเยโฮวาห์ทรงรักท่าน ท่านจะกระทําตามพระทัยของพระองค์ต่อบาบิโลน และพระกรของพระองค์จะต่อสู้กับชาวเคลเดีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 15, 'เรา นี่เราเองได้พูด เออ เราได้เรียกท่าน เราได้นําท่านมา และท่านจะจําเริญในทางของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 16, 'จงเข้ามาใกล้เรา ฟังเรื่องนี้ ตั้งแต่เริ่มต้นเรามิได้พูดในที่ลี้ลับ ตั้งแต่มันเกิดมา เราก็ได้อยู่ที่นั่นแล้ว” และบัดนี้ องค์พระผู้เป็นเจ้าพระเจ้าและพระวิญญาณของพระองค์ได้ทรงใช้ข้าพเจ้ามา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 17, 'พระเยโฮวาห์ ผู้ไถ่ของเจ้า องค์บริสุทธิ์ของอิสราเอล ตรัสดังนี้ว่า “เราคือพระเยโฮวาห์พระเจ้าของเจ้า ผู้สั่งสอนเจ้าเพื่อประโยชน์ของเจ้า ผู้นําเจ้าในทางที่เจ้าควรจะไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 18, 'โอ ถ้าเจ้าได้เชื่อฟังบัญญัติของเราแล้ว ความสุขสมบูรณ์ของเจ้าจะเป็นเหมือนแม่น้ํา และความชอบธรรมของเจ้าจะเป็นเหมือนคลื่นทะเล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 19, 'เชื้อสายของเจ้าจะเป็นเหมือนทรายเช่นกัน และลูกหลานจากบั้นเอวของเจ้าเหมือนเม็ดทราย ชื่อของเขาจะไม่ถูกตัดออกเลย หรือถูกทําลายเสียจากหน้าเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 20, 'จงไปเสียจากบาบิโลน จงหนีออกจากคนเคลเดีย จงประกาศข้อนี้ด้วยเสียงร้องเพลง จงเล่าให้ฟัง จงส่งออกไปถึงสุดปลายแผ่นดินโลกว่า “พระเยโฮวาห์ทรงไถ่ยาโคบผู้รับใช้ของพระองค์แล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 21, 'เมื่อพระองค์ทรงนําเขาทั้งหลายไปทางทะเลทราย เขาก็มิได้กระหาย พระองค์ทรงกระทําให้น้ําไหลจากศิลาเพื่อเขา พระองค์ทรงผ่าหินและน้ําก็ทะลักออกมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 22, 'พระเยโฮวาห์ตรัสว่า “ไม่มีสันติสุขแก่คนชั่วร้าย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 1, 'โอ เกาะทั้งหลายเอ๋ย จงฟังข้าพเจ้า เจ้าชนชาติทั้งหลายแต่ไกลโพ้น จงฟัง พระเยโฮวาห์ทรงเรียกข้าพเจ้าตั้งแต่ในครรภ์ พระองค์ทรงกล่าวถึงชื่อข้าพเจ้าตั้งแต่อยู่ในท้องมารดาข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 2, 'พระองค์ทรงทําปากของข้าพเจ้าเหมือนดาบคม พระองค์ทรงซ่อนข้าพเจ้าไว้ในร่มพระหัตถ์ของพระองค์ พระองค์ทรงทําข้าพเจ้าให้เป็นลูกศรขัดมัน พระองค์ทรงซ่อนข้าพเจ้าไว้เสียในแล่งของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 3, 'และพระองค์ตรัสกับข้าพเจ้าว่า “เจ้าเป็นผู้รับใช้ของเรา โอ อิสราเอล ซึ่งเราจะได้รับเกียรติในเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 4, 'แต่ข้าพเจ้าว่า “ข้าพเจ้าได้ทํางานเปล่าดาย ข้าพเจ้าเปลืองแรงของข้าพเจ้าเปล่าๆ อนิจจัง แต่แน่ละ ความยุติธรรมอันควรตกแก่ข้าพเจ้าอยู่กับพระเยโฮวาห์ และงานของข้าพเจ้าอยู่กับพระเจ้าของข้าพเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 5, 'และบัดนี้พระเยโฮวาห์ ผู้ทรงปั้นข้าพเจ้าตั้งแต่ในครรภ์ให้เป็นผู้รับใช้ของพระองค์ เพื่อจะนํายาโคบกลับมาหาพระองค์อีก ตรัสว่า “ถึงแม้อิสราเอลจะไม่ถูกรวบรวมเข้ามา ข้าพเจ้าก็ยังได้รับเกียรติในสายพระเนตรของพระเยโฮวาห์ และพระเจ้าของข้าพเจ้าจะทรงเป็นกําลังของข้าพเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 6, 'พระองค์ตรัสว่า “ซึ่งเจ้าจะเป็นผู้รับใช้ของเรา เพื่อจะยกบรรดาตระกูลของยาโคบขึ้น เพื่อจะให้อิสราเอลที่เหลืออยู่กลับสู่สภาพดีนั้น ดูเป็นการเล็กน้อยเกินไป เราจะมอบให้เจ้าเป็นความสว่างแก่บรรดาประชาชาติ เพื่อความรอดของเราจะถึงที่สุดปลายแผ่นดินโลกทางเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 7, 'พระเยโฮวาห์ ผู้ไถ่ของอิสราเอลและองค์บริสุทธิ์ ตรัสแก่ผู้ที่คนดูหมิ่นและแก่ผู้ที่ประชาชาติรังเกียจ ผู้เป็นผู้รับใช้ของผู้ครอบครองทั้งหลาย ดังนี้ว่า “กษัตริย์ทั้งหลายจะทอดพระเนตรและทรงลุกยืน บรรดาเจ้านายจะกราบลง เพราะเหตุพระเยโฮวาห์ผู้สัตย์ซื่อ องค์บริสุทธิ์ของอิสราเอล จะทรงเลือกสรรเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 8, 'พระเยโฮวาห์ตรัสดังนี้ว่า “ในเวลาอันชอบ เราได้ฟังเจ้า ในวันแห่งความรอด เราได้ช่วยเจ้า เราจะรักษาเจ้าไว้ และมอบให้เจ้าเป็นพันธสัญญาของมนุษยชาติ เพื่อสถาปนาแผ่นดิน เพื่อเป็นเหตุให้ได้รับมรดกที่ร้างเปล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 9, 'เพื่อเจ้าจะกล่าวแก่ผู้ถูกจองจําว่า ‘ออกไปเถิด’ ต่อบรรดาผู้ที่อยู่ในความมืดว่า ‘จงปรากฏตัว’ เขาทั้งหลายจะเลี้ยงชีวิตตามทาง และตามที่สูงทั้งหลายจะเป็นที่หากินของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 10, 'เขาทั้งหลายจะไม่หิวหรือกระหาย ความร้อนหรือดวงอาทิตย์จะไม่ทําลายเขา เพราะพระองค์ซึ่งเมตตาเขาจะทรงนําเขาไป และจะนําเขาไปตามน้ําพุ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 11, 'เราจะทําภูเขาของเราทั้งหมดเป็นทางเดิน และทางหลวงของเราจะสูง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 12, 'ดูเถิด พวกเหล่านี้จะมาจากเมืองไกล และดูเถิด บ้างมาจากเหนือและจากตะวันตก และบ้างมาจากแผ่นดินสเวเน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 13, 'โอ ฟ้าสวรรค์เอ๋ย จงร้องเพลง โอ แผ่นดินโลกเอ๋ย จงเริงโลดเถิด โอ ภูเขาเอ๋ย จงเปรมปรีดิ์ร้องเพลง เพราะพระเยโฮวาห์ได้ทรงเล้าโลมชนชาติของพระองค์แล้ว และจะทรงเมตตาแก่คนของพระองค์ ผู้ที่ถูกข่มใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 14, 'แต่ศิโยนกล่าวว่า “พระเยโฮวาห์ได้ทรงละทิ้งข้าพเจ้าแล้ว องค์พระผู้เป็นเจ้าของข้าพเจ้าทรงลืมข้าพเจ้าเสียแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 15, '“ผู้หญิงจะลืมบุตรที่ยังกินนมของนาง และจะไม่เมตตาบุตรชายจากครรภ์ของนางได้หรือ แม้ว่าคนเหล่านี้ยังลืมได้ กระนั้นเราก็จะไม่ลืมเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 16, 'ดูเถิด เราได้สลักเจ้าไว้บนฝ่ามือของเรา กําแพงเมืองของเจ้าอยู่ต่อหน้าเราเสมอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 17, 'ลูกหลานของเจ้าก็จะเร่งรีบ ผู้ทําลายเจ้าและบรรดาผู้ที่ทําให้เจ้าถูกทิ้งร้างก็จะออกไปจากเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 18, 'จงเงยหน้าเงยตาขึ้นดูรอบๆ เขาทั้งหลายชุมนุมกัน เขาทั้งหลายมาหาเจ้า” พระเยโฮวาห์ตรัสว่า “เรามีชีวิตอยู่ตราบใด เจ้าจะสวมเขาทั้งหลายไว้หมดอย่างเครื่องอาภรณ์ เจ้าจะผูกเขาไว้อย่างเจ้าสาวประดับอาภรณ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 19, 'เพราะว่าที่ที่ถูกทิ้งไว้เสียเปล่าและที่รกร้างของเจ้า และแผ่นดินที่ถูกทําลายของเจ้าจะแคบเกินไปด้วยเหตุมีชาวเมืองอยู่กันมาก และคนทั้งหลายที่กลืนเจ้าจะอยู่ห่างไกล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 20, 'เด็กที่เกิดแก่เจ้าหลังจากลูกเสียไปแล้ว จะพูดที่หูของเจ้าอีกว่า ‘ที่นี้แคบเกินสําหรับฉันแล้ว จงหาที่ให้ฉันอยู่’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 21, 'แล้วเจ้าจะกล่าวในใจของเจ้าว่า ‘ใครหนอได้ให้กําเนิดคนเหล่านี้แก่ข้าพเจ้า เพราะข้าพเจ้าสูญเสียลูกๆไปแล้ว และข้าพเจ้าก็โดดเดี่ยว ถูกกวาดไปเป็นเชลยและย้ายไปโน่นมานี่ แต่ใครหนอชุบเลี้ยงคนเหล่านี้ ดูเถิด ข้าพเจ้าถูกทิ้งอยู่ตามลําพัง แล้วคนเหล่านี้มาจากไหนกัน’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 22, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า “ดูเถิด เราจะยกมือของเรากวักบรรดาประชาชาติ และยกสัญญาณของเราต่อชนชาติทั้งหลาย และเขาทั้งหลายจะอุ้มบรรดาบุตรชายของเจ้ามา และบรรดาบุตรสาวของเจ้านั้น เขาจะใส่บ่าแบกมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 23, 'บรรดากษัตริย์จะเป็นพ่อเลี้ยงของเจ้า และพระราชินีทั้งหลายจะเป็นแม่เลี้ยงของเจ้า เขาเหล่านั้นจะก้มหน้าลงถึงดินกราบเจ้า เขาจะเลียผงคลีที่เท้าของเจ้า แล้วเจ้าจะรู้ว่าเราคือพระเยโฮวาห์ ผู้ที่รอคอยเราจะไม่ประสบความอาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 24, 'จะเอาเหยื่อไปจากผู้มีกําลัง หรือจะช่วยเชลยของผู้ชอบธรรมให้พ้นได้หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 25, 'แน่นอนละ พระเยโฮวาห์ตรัสดังนี้ว่า “แม้เชลยของผู้มีกําลังก็จะต้องเอาไป และเหยื่อของผู้น่ากลัวก็ต้องช่วยให้พ้น เพราะเราจะต่อสู้กับผู้ที่ต่อสู้เจ้า และจะช่วยบุตรของเจ้าให้รอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 26, 'เราจะให้ผู้บีบบังคับเจ้ากินเนื้อของตนเอง และเขาจะเมาโลหิตของเขาเองเหมือนเมาเหล้าองุ่น แล้วเนื้อหนังทั้งปวงจะทราบว่า เราคือพระเยโฮวาห์ เป็นพระผู้ช่วยให้รอดของเจ้า และพระผู้ไถ่ของเจ้า องค์อานุภาพของยาโคบ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 1, 'พระเยโฮวาห์ตรัสดังนี้ว่า “หนังสือหย่าของแม่เจ้า ผู้ซึ่งเราได้ไล่ไปเสียนั้น อยู่ที่ไหนเล่า หรือเจ้าหนี้ของเราคนไหนเล่าที่เราได้ขายตัวเจ้าไป ดูเถิด เพราะความชั่วช้าของเจ้า เจ้าจึงถูกขาย และเพราะความละเมิดของเจ้า แม่ของเจ้าจึงถูกไล่ไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 2, 'ทําไมนะ เมื่อเรามาจึงไม่มีใครเลย เมื่อเราร้องเรียกจึงไม่มีใครตอบ มือของเราสั้น ไถ่ไม่ได้หรือ และเราไม่มีกําลังที่จะช่วยให้พ้นหรือ ดูเถิด เราให้น้ําทะเลแห้งด้วยการขนาบของเรา เรากระทําให้แม่น้ําเป็นถิ่นทุรกันดาร ปลาของแม่น้ํานั้นก็เหม็นเพราะขาดน้ํา และตายเพราะกระหาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 3, 'เราห่มฟ้าสวรรค์ไว้ด้วยความดํามืด และเอาผ้ากระสอบมาคลุม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 4, 'องค์พระผู้เป็นเจ้าพระเจ้าได้ประทานให้ข้าพเจ้ามีลิ้นของบรรดาผู้ที่พระองค์ทรงสอน เพื่อข้าพเจ้าจะได้รู้ที่จะค้ําชูผู้ที่เหน็ดเหนื่อยไว้ด้วยถ้อยคํา ทุกๆเช้าพระองค์ทรงปลุก ทรงปลุกหูของข้าพเจ้าเพื่อให้ฟังอย่างผู้ที่พระองค์ทรงสอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 5, 'องค์พระผู้เป็นเจ้าพระเจ้าได้ทรงเบิกหูข้าพเจ้า และข้าพเจ้าก็ไม่ดื้อดัน ข้าพเจ้าไม่หันกลับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 6, 'ข้าพเจ้าหันหลังให้แก่ผู้ที่โบยตีข้าพเจ้า และหันแก้มให้แก่คนที่ดึงเคราข้าพเจ้าออก ข้าพเจ้าไม่หนีหน้าจากความอายแก่การถ่มน้ําลายรด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 7, 'เพราะว่าองค์พระผู้เป็นเจ้าพระเจ้าจะทรงช่วยข้าพเจ้า เพราะฉะนั้นข้าพเจ้าจึงจะไม่ขายหน้า เพราะฉะนั้นข้าพเจ้าจึงตั้งหน้าของข้าพเจ้าอย่างหินเหล็กไฟ และข้าพเจ้าทราบว่าข้าพเจ้าจะไม่ได้อาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 8, 'พระองค์ผู้ทรงแก้แทนข้าพเจ้าก็อยู่ใกล้ ใครจะสู้คดีกับข้าพเจ้า ก็ให้เรายืนอยู่ด้วยกัน ใครเป็นปฏิปักษ์ของข้าพเจ้า ก็ให้เขามาใกล้ข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 9, 'ดูเถิด องค์พระผู้เป็นเจ้าพระเจ้าจะทรงช่วยข้าพเจ้า ใครจะกล่าวโทษข้าพเจ้าว่ามีความผิด ดูเถิด บรรดาเขาทุกคนจะร่อยหรอไปเหมือนอย่างเสื้อผ้า ตัวมอดจะกินเขาเหล่านั้นเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 10, 'ใครบ้างในพวกเจ้าเกรงกลัวพระเยโฮวาห์ และเชื่อฟังเสียงของผู้รับใช้ของพระองค์ ผู้ดําเนินในความมืด และไม่มีความสว่าง จงให้เขาวางใจในพระนามพระเยโฮวาห์ และพึ่งอาศัยพระเจ้าของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 11, 'ดูเถิด เจ้าทั้งสิ้นผู้ก่อไฟ ผู้เอาดุ้นไฟคาดตัวเจ้าไว้ จงเดินด้วยแสงไฟของเจ้า และด้วยแสงดุ้นไฟซึ่งเจ้าได้ก่อ เจ้าจะได้รับอย่างนี้จากมือของเรา คือเจ้าจะต้องนอนลงด้วยความเศร้าโศก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 1, '“จงฟังเราซี เจ้าทั้งหลายผู้ติดตามความชอบธรรม เจ้าผู้แสวงหาพระเยโฮวาห์ จงมองดูหินซึ่งได้ทรงสกัดตัวเจ้ามา และจงมองดูบ่อหินซึ่งทรงขุดเอาตัวเจ้าทั้งหลายมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 2, 'จงมองอับราฮัมบรรพบุรุษของเจ้าทั้งหลาย และดูซาราห์ผู้คลอดเจ้า เพราะเมื่อมีเขาอยู่แต่คนเดียว เราได้ร้องเรียกเขา และเราอวยพรเขา และกระทําให้เป็นคนมากมาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 3, 'เพราะว่าพระเยโฮวาห์จะทรงเล้าโลมศิโยน พระองค์จะทรงเล้าโลมที่ทิ้งร้างทั้งสิ้นของเธอ และจะทําถิ่นทุรกันดารของเธอเหมือนสวนเอเดน และทะเลทรายของเธอเหมือนอุทยานของพระเยโฮวาห์ จะพบความชื่นบานและความยินดีในเธอ ทั้งการโมทนาและเสียงเพลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 4, 'ชนชาติของเราเอ๋ย จงฟังเสียงของเรา โอ ชาติของเราเอ๋ย จงเงี่ยหูฟังเรา เพราะราชบัญญัติจะออกไปจากเรา และความยุติธรรมจะออกไปเป็นความสว่างของชนชาติทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 5, 'ความชอบธรรมของเราใกล้เข้ามาแล้ว และความรอดของเราได้ออกไปแล้ว แขนของเราจะพิพากษาชนชาติทั้งหลาย เกาะทั้งหลายจะรอคอยเรา และเขาจะหวังคอยแขนของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 6, 'จงแหงนตาดูฟ้าสวรรค์ และมองดูโลกเบื้องล่าง เพราะว่าฟ้าสวรรค์จะสูญสิ้นไปเหมือนควัน และแผ่นดินโลกจะร่อยหรอไปเหมือนอย่างเสื้อผ้า และเขาทั้งหลายผู้อาศัยอยู่ในนั้นจะตายไปเหมือนกัน แต่ความรอดของเราจะอยู่เป็นนิตย์ และความชอบธรรมของเราจะไม่สิ้นสุดเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 7, 'จงฟังเรา เจ้าทั้งหลายผู้รู้ถึงความชอบธรรม ชนชาติซึ่งราชบัญญัติของเราอยู่ในใจ อย่ากลัวการตําหนิของมนุษย์ และอย่าวิตกต่อการกล่าวหยาบช้าของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 8, 'เพราะว่าตัวมอดจะกินเขาเหมือนกินเสื้อผ้า และตัวหนอนจะกินเขาเหมือนกินขนแกะ แต่ความชอบธรรมของเราจะอยู่เป็นนิตย์ และความรอดของเราจะอยู่ตลอดทุกชั่วอายุ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 9, 'โอ ข้าแต่พระกรของพระเยโฮวาห์ จงตื่นเถิด ตื่นเถิด จงสวมกําลัง จงตื่นอย่างสมัยโบราณในชั่วอายุนานมาแล้ว ท่านไม่ใช่หรือที่ฟันราหับ และทําให้พญานาคได้รับบาดเจ็บ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 10, 'ท่านไม่ใช่หรือที่ทําให้ทะเลแห้งไป คือน้ําของมหาสมุทรใหญ่ด้วย ซึ่งทําที่ลึกของทะเลให้เป็นหนทาง เพื่อให้ผู้ที่ได้ไถ่ไว้แล้วเดินผ่านไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 11, 'ฉะนั้นผู้ที่ไถ่ไว้แล้วของพระเยโฮวาห์จะกลับ และร้องเพลงมาศิโยน ความชื่นบานเป็นนิตย์จะอยู่บนศีรษะของเขา เขาจะได้รับความชื่นบานและความยินดี ความโศกเศร้าและการไว้ทุกข์จะหนีไปเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 12, 'เรา คือเราเอง ผู้เล้าโลมเจ้า เจ้าเป็นผู้ใดเล่าที่กลัวมนุษย์ผู้ซึ่งต้องตาย คือกลัวบุตรของมนุษย์ซึ่งถูกทําให้เหมือนหญ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 13, 'และที่ได้ลืมพระเยโฮวาห์ผู้สร้างของตนเสีย ผู้ทรงขึงฟ้าสวรรค์และวางรากฐานของแผ่นดินโลก และที่กลัวอยู่เรื่อยไปตลอดวัน เพราะความเกรี้ยวกราดของผู้บีบบังคับ เมื่อเขาตั้งตัวเขาที่จะทําลาย และความเกรี้ยวกราดของผู้บีบบังคับอยู่ที่ไหนเล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 14, 'ผู้ใดที่เป็นเชลยเร่งรีบเพื่อจะได้รับการปลดปล่อย เพื่อเขาจะไม่ตายในหลุม ทั้งอาหารของเขาจะไม่ขาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 15, 'เพราะเราคือพระเยโฮวาห์พระเจ้าของเจ้า ผู้แบ่งแยกทะเลและคลื่นก็คะนอง พระนามของพระองค์คือพระเยโฮวาห์จอมโยธา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 16, 'และเราได้ใส่ถ้อยคําของเราในปากของเจ้า และซ่อนเจ้าไว้ในร่มมือของเรา ซึ่งตั้งฟ้าสวรรค์ และวางรากฐานของแผ่นดินโลก และกล่าวแก่ศิโยนว่า ‘เจ้าเป็นชนชาติของเรา’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 17, 'โอ เยรูซาเล็มเอ๋ย จงปลุกตัวเอง จงปลุกตัวเอง จงยืนขึ้นเถิด เจ้าผู้ได้ดื่มจากพระหัตถ์ของพระเยโฮวาห์ ซึ่งถ้วยแห่งพระพิโรธของพระองค์ ผู้ได้ดื่มถึงตะกอน ซึ่งถ้วยแห่งความโซเซ และดูดมันออก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 18, 'ในบรรดาบุตรชายที่นางคลอดมาก็ไม่มีผู้ใดนํานาง ในบรรดาบุตรชายที่นางชุบเลี้ยงมาก็ไม่มีใครจูงมือนาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 19, 'สองสิ่งนี้ได้มาถึงเจ้า ผู้ใดเล่าจะเศร้าโศกเสียใจเพื่อเจ้า ได้แก่การล้างผลาญและการทําลาย การกันดารอาหารและดาบ เราจะให้ใครไปปลอบประโลมเจ้าดีหนอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 20, 'บุตรชายของเจ้าสลบไปแล้ว เขานอนอยู่ที่ทุกหัวถนนเหมือนวัวป่าตัวผู้ติดข่าย เขาทั้งหลายโชกโชนด้วยพระพิโรธของพระเยโฮวาห์ และการขนาบของพระเจ้าของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 21, 'ฉะนั้นเจ้าผู้ถูกข่มใจ ผู้ซึ่งมึนเมาแต่มิใช่ด้วยเหล้าองุ่น จงฟังข้อนี้เถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 22, 'องค์พระผู้เป็นเจ้าของเจ้า พระเยโฮวาห์พระเจ้าของเจ้า ผู้ทรงสู้คดีแห่งชนชาติของพระองค์ ตรัสดังนี้ว่า “ดูเถิด เราได้เอาถ้วยแห่งความโซเซมาจากมือของเจ้า แล้วตะกอนในถ้วยแห่งความพิโรธของเรา เจ้าจะไม่ต้องดื่มอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 23, 'แต่เราจะใส่มันไว้ในมือของผู้ทรมานเจ้า ผู้ได้พูดกับจิตใจเจ้าว่า ‘ก้มลง เราจะได้ข้ามไป’ และเจ้าได้กระทําให้หลังของเจ้าเหมือนพื้นดิน และเหมือนถนนเพื่อให้เขาข้ามไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 1, 'โอ ศิโยนเอ๋ย ตื่นเถิด ตื่นเถิด จงสวมกําลังของเจ้า โอ เยรูซาเล็ม กรุงบริสุทธิ์เอ๋ย จงสวมเสื้อผ้างามของเจ้า เพราะผู้ที่ไม่เข้าสุหนัตและผู้ไม่สะอาดจะไม่เข้ามาในเจ้าอีกเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 2, 'โอ เยรูซาเล็มเอ๋ย จงสลัดตัวจากผงคลี จงลุกขึ้น และนั่งลง โอ ธิดาแห่งศิโยนที่เป็นเชลยเอ๋ย จงแก้พันธนะออกจากคอของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 3, 'เพราะพระเยโฮวาห์ตรัสดังนี้ว่า “เจ้าถูกขายเปล่าๆ และเจ้าจะถูกไถ่โดยไม่ใช้เงิน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 4, 'เพราะองค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า “แต่ก่อนนั้นชนชาติของเราลงไปสู่อียิปต์เพื่ออาศัยอยู่ที่นั่น และชาวอัสซีเรียบีบบังคับเขาโดยปราศจากสาเหตุ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 5, 'พระเยโฮวาห์ตรัสว่า “ฉะนั้นบัดนี้เรามีอะไรอยู่ที่นี่ ด้วยว่าชนชาติของเราถูกนําเอาไปเสียเปล่าๆ” พระเยโฮวาห์ตรัสว่า “ผู้ครอบครองของเขาทําให้เขาร้อง และเขากล่าวหยาบหยามต่อนามของเราทุกวันตลอดไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 6, 'เหตุฉะนั้นชนชาติของเราจะรู้จักนามของเรา เพราะฉะนั้นในวันนั้นเขาจะรู้ว่า คือเรานี่แหละผู้พูด ดูเถิด คือเราเอง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 7, 'เท้าของผู้ประกาศข่าวประเสริฐมา ก็งามสักเท่าใดที่บนภูเขา ผู้โฆษณาสันติภาพ ผู้ประกาศข่าวประเสริฐแห่งสิ่งอันประเสริฐ ผู้โฆษณาความรอด ผู้กล่าวแก่ศิโยนว่า “พระเจ้าของเจ้าทรงครอบครอง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 8, 'พวกยามของเจ้าจะเปล่งเสียง เขาจะร้องเพลงกัน เพราะเขาจะได้เห็นกับตาอย่างชัด เมื่อพระเยโฮวาห์จะทรงนําศิโยนกลับมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 9, 'เจ้าคือที่ทิ้งร้างแห่งเยรูซาเล็มเอ๋ย จงเปล่งเสียงร้องเพลงด้วยกัน เพราะพระเยโฮวาห์ได้ทรงเล้าโลมชนชาติของพระองค์ พระองค์ได้ทรงไถ่เยรูซาเล็มแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 10, 'พระเยโฮวาห์ทรงเปลือยพระกรอันบริสุทธิ์ของพระองค์ท่ามกลางสายตาของบรรดาประชาชาติ และที่สุดปลายแผ่นดินโลกทั้งสิ้นจะเห็นความรอดของพระเจ้าของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 11, 'เจ้าทั้งหลายผู้ถือเครื่องภาชนะของพระเยโฮวาห์ ไปซี จงไป ออกไปจากที่โน่น อย่าแตะต้องสิ่งซึ่งไม่สะอาด จงออกไปจากท่ามกลางเธอ จงชําระตัวของเจ้าให้บริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 12, 'เพราะเจ้าจะไม่ต้องรีบออกไป และเจ้าจะไม่ต้องหลบหนีไป เพราะพระเยโฮวาห์จะเสด็จนําหน้าเจ้า และพระเจ้าแห่งอิสราเอลจะทรงระวังหลังเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 13, 'ดูเถิด ผู้รับใช้ของเราจะทําอย่างมีสติปัญญา ท่านจะสูงเด่นและเป็นที่เทิดทูน และท่านจะสูงนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 14, 'ด้วยคนเป็นอันมากตะลึงเพราะท่านฉันใด หน้าตาของท่านเสียโฉมมากกว่ามนุษย์คนใด และรูปร่างของท่านก็เสียโฉมมากกว่าบุตรทั้งหลายของมนุษย์คนใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 15, 'ท่านก็จะกระทําให้บรรดาประชาชาติเป็นอันมากตกตะลึงฉันนั้น บรรดากษัตริย์ก็จะปิดพระโอษฐ์เพราะท่านนั้น เพราะเขาทั้งหลายจะเห็นสิ่งที่ไม่มีใครบอกเขา และเขาจะพิจารณาถึงสิ่งซึ่งเขาไม่เคยได้ยิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 1, 'ใครเล่าได้เชื่อสิ่งที่เขาได้ยินจากเราทั้งหลาย พระกรของพระเยโฮวาห์ได้ทรงสําแดงแก่ผู้ใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 2, 'เพราะท่านจะเจริญขึ้นต่อพระพักตร์พระองค์อย่างต้นไม้อ่อน และเหมือนรากแตกหน่อมาจากพื้นดินแห้ง ท่านไม่มีรูปร่างหรือความสวยงาม และเมื่อเราทั้งหลายจะมองท่าน ไม่มีความงามที่เราจะพึงปรารถนาท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 3, 'ท่านได้ถูกมนุษย์ดูหมิ่นและทอดทิ้ง เป็นคนที่รับความเศร้าโศกและคุ้นเคยกับความระทมทุกข์ และดังผู้หนึ่งซึ่งคนทนมองดูไม่ได้ ท่านถูกดูหมิ่น และเราทั้งหลายไม่ได้นับถือท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 4, 'แน่ทีเดียวท่านได้แบกความระทมทุกข์ของเราทั้งหลาย และหอบความเศร้าโศกของเราไป กระนั้นเราทั้งหลายก็ยังถือว่าท่านถูกตี คือพระเจ้าทรงโบยตีและข่มใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 5, 'แต่ท่านถูกบาดเจ็บเพราะความละเมิดของเราทั้งหลาย ท่านฟกช้ําเพราะความชั่วช้าของเรา การตีสอนอันทําให้เราทั้งหลายปลอดภัยนั้นตกแก่ท่าน ที่ต้องฟกช้ํานั้นก็ให้เราหายดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 6, 'เราทุกคนได้เจิ่นไปเหมือนแกะ เราทุกคนต่างได้หันไปตามทางของตนเอง และพระเยโฮวาห์ทรงวางลงบนท่านซึ่งความชั่วช้าของเราทุกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 7, 'ท่านถูกบีบบังคับและท่านถูกข่มใจ ถึงกระนั้นท่านก็ไม่ปริปาก เหมือนลูกแกะที่ถูกนําไปฆ่า และเหมือนแกะที่เป็นใบ้อยู่หน้าผู้ตัดขนของมันฉันใด ท่านก็ไม่ปริปากของท่านเลยฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 8, 'ท่านถูกนําไปจากคุกและท่านไม่ได้รับความยุติธรรมเสียเลย และผู้ใดเล่าจะประกาศเกี่ยวกับพงศ์พันธุ์ของท่าน เพราะท่านต้องถูกตัดออกไปจากแผ่นดินของคนเป็น ต้องถูกตีเพราะการละเมิดของชนชาติของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 9, 'และเขาจัดหลุมศพของท่านไว้กับคนชั่ว ในความตายของท่านเขาจัดไว้กับเศรษฐี แม้ว่าท่านมิได้กระทําการทารุณประการใดเลย และไม่มีการหลอกลวงในปากของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 10, 'แต่ก็ยังเป็นน้ําพระทัยของพระเยโฮวาห์ที่จะให้ท่านฟกช้ําด้วยความระทมทุกข์ เมื่อพระองค์ทรงกระทําให้วิญญาณของท่านเป็นเครื่องบูชาไถ่บาป ท่านจะเห็นเชื้อสายของท่าน ท่านจะยืดวันทั้งหลายของท่าน น้ําพระทัยของพระเยโฮวาห์จะเจริญขึ้นในมือของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 11, 'ท่านจะเห็นความทุกข์ลําบากแห่งจิตวิญญาณของท่าน และจะพอใจ โดยความรู้ของท่าน ผู้รับใช้อันชอบธรรมของเราจะกระทําให้คนเป็นอันมากนับได้ว่าเป็นคนชอบธรรม เพราะท่านจะแบกบรรดาความชั่วช้าของเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 12, 'ฉะนี้เราจะแบ่งส่วนหนึ่งให้ท่านกับผู้ยิ่งใหญ่ และท่านจะแบ่งรางวัลกับคนแข็งแรง เพราะท่านเทจิตวิญญาณของท่านถึงความมรณา และถูกนับเข้ากับบรรดาผู้ละเมิด ท่านก็แบกบาปของคนเป็นอันมาก และทําการอ้อนวอนเพื่อผู้ละเมิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 1, '“จงร้องเพลงเถิด โอ หญิงหมันเอ๋ย ผู้ไม่คลอดบุตร จงเปล่งเสียงร้องเพลงและร้องเสียงดัง เจ้าผู้ไม่ได้เจ็บครรภ์ ด้วยว่าบุตรของผู้อยู่อย่างโดดเดี่ยวก็ยังจะมีมากกว่าบุตรของภรรยาที่ได้แต่งงาน” พระเยโฮวาห์ตรัสดังนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 2, '“จงขยายสถานที่แห่งเต็นท์ของเจ้า และให้เขาขึงม่านของที่อาศัยของเจ้าออก อย่าหน่วงไว้ ต่อเชือกของเจ้าให้ยาว และเสริมกําลังหลักหมุดของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 3, 'เพราะเจ้าจะกระจายออกไปทางขวาและทางซ้าย และเชื้อสายของเจ้าจะได้พวกต่างชาติเป็นมรดก และจะกระทําให้หัวเมืองที่รกร้างมีคนอาศัยอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 4, 'อย่ากลัวเลย เพราะเจ้าจะไม่ต้องอับอาย อย่าอดสูเลย เพราะเจ้าจะไม่ต้องละอาย เพราะเจ้าจะลืมความอายในวัยสาวของเจ้า และเจ้าจะไม่จําที่เขาติความเป็นม่ายของเจ้าอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 5, 'เพราะผู้สร้างเจ้าเป็นสามีของเจ้า พระนามของพระองค์คือพระเยโฮวาห์จอมโยธา และองค์บริสุทธิ์ของอิสราเอลเป็นผู้ไถ่ของเจ้า เขาจะเรียกพระองค์ว่าพระเจ้าของสากลโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 6, 'เพราะพระเยโฮวาห์ได้ทรงเรียกเจ้า ดังภรรยาผู้ถูกละทิ้งและโทมนัสในใจ เหมือนภรรยาสาวเมื่อนางถูกทิ้ง” พระเจ้าของเจ้าตรัสดังนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 7, '“เราได้ละทิ้งเจ้าอยู่หน่อยเดียว แต่เราจะรวบรวมเจ้าด้วยความเมตตายิ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 8, 'เราได้ซ่อนหน้าของเราจากเจ้า ด้วยความพิโรธอันท่วมท้นอยู่ครู่หนึ่ง แต่ด้วยความกรุณานิรันดร์ เราจะมีความเมตตาต่อเจ้า” พระเยโฮวาห์พระผู้ไถ่เจ้าตรัสดังนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 9, '“สําหรับเราเรื่องนี้เหมือนน้ําของโนอาห์ เพราะเราได้ปฏิญาณว่าน้ําของโนอาห์จะไม่ท่วมแผ่นดินโลกอีกเลยฉันใด เราจึงได้ปฏิญาณว่า เราจะไม่โกรธเจ้า และจะไม่ขนาบเจ้าฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 10, 'เพราะภูเขาจะพรากจากไป และเนินจะคลอนแคลน แต่ความกรุณาของเราจะไม่พรากไปจากเจ้า และพันธสัญญาแห่งสันติภาพของเราจะไม่คลอนแคลนไป” พระเยโฮวาห์ผู้มีความเมตตาต่อเจ้าตรัสดังนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 11, '“โอ เจ้าผู้ถูกข่มใจ ถูกพายุพัดพา และขาดการเล้าโลม ดูเถิด เราจะวางศิลาของเจ้าไว้ในพลวง และวางรากฐานของเจ้าไว้ด้วยไพทูรย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 12, 'เราจะทําหน้าต่างของเจ้าด้วยโมรา และประตูเมืองของเจ้าด้วยพลอยสีแดงเข้ม และชายแดนทั้งสิ้นของเจ้าด้วยเพชรนิลจินดา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 13, 'บุตรทั้งสิ้นของเจ้านั้นจะเรียนรู้จากพระเยโฮวาห์ และบุตรของเจ้าจะมีความปลอดภัยอย่างยิ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 14, 'เจ้าจะได้รับสถาปนาไว้ในความชอบธรรม เจ้าจะห่างไกลจากการบีบบังคับเพราะเจ้าจะไม่ต้องกลัว และห่างจากความสยดสยองเพราะมันจะไม่มาใกล้เจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 15, 'ดูเถิด พวกเขาจะปลุกปั่นให้เกิดการแก่งแย่งเป็นแน่ แต่ก็มิใช่เพราะมาจากเรา ผู้ใดปลุกปั่นให้เกิดการแก่งแย่งกับเจ้า ผู้นั้นจะล้มลงเพราะเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 16, 'ดูเถิด เราได้สร้างช่างเหล็กผู้เป่าไฟถ่าน และทําให้เกิดอาวุธเหมาะกับงานของมัน เราได้สร้างผู้ผลาญเพื่อทําลายด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 17, 'ไม่มีอาวุธใดที่สร้างเพื่อต่อสู้เจ้าจะจําเริญได้ และเจ้าจะปรับโทษลิ้นทุกลิ้นที่ลุกขึ้นต่อสู้เจ้าในการพิพากษา นี่เป็นมรดกของบรรดาผู้รับใช้ของพระเยโฮวาห์ และความชอบธรรมของเขามาจากเรา” พระเยโฮวาห์ตรัสดังนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 1, '“โอ เชิญทุกคนที่กระหายจงมาถึงน้ํา และผู้ที่ไม่มีเงินมาซื้อกินเถิด มาซื้อน้ําองุ่นและน้ํานมเถิด โดยไม่ต้องเสียเงินเสียค่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 2, 'ทําไมเจ้าจึงใช้เงินของเจ้าเพื่อของซึ่งไม่ใช่อาหาร และใช้ผลแรงงานซื้อสิ่งซึ่งมิให้อิ่มใจ จงเอาใจใส่ฟังเรา และรับประทานของดี และให้จิตใจปีติยินดีในไขมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 3, 'เอียงหูของเจ้า และมาหาเรา จงฟัง เพื่อจิตวิญญาณของเจ้าจะมีชีวิต และเราจะทําพันธสัญญานิรันดร์กับเจ้า คือความเมตตาอันแน่นอนของเราต่อดาวิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 4, 'ดูเถิด เรากระทําให้ท่านเป็นพยานต่อชนชาติทั้งหลาย เป็นหัวหน้าและเป็นผู้บัญชาการเพื่อชนชาติทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 5, 'ดูเถิด เจ้าจะร้องเรียกประชาชาติซึ่งเจ้าไม่รู้จัก และประชาชาติซึ่งไม่รู้จักเจ้าจะวิ่งมาหาเจ้าเหตุด้วยพระเยโฮวาห์พระเจ้าของเจ้า และเพราะองค์บริสุทธิ์แห่งอิสราเอล เพราะพระองค์ทรงให้เจ้าได้รับเกียรติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 6, 'จงแสวงหาพระเยโฮวาห์ เมื่อจะพบพระองค์ได้ จงทูลพระองค์ ขณะพระองค์ทรงอยู่ใกล้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 7, 'ให้คนชั่วละทิ้งทางของเขา และคนไม่ชอบธรรมสละความคิดของเขา ให้เขากลับยังพระเยโฮวาห์ เพื่อพระองค์จะทรงเมตตาเขา และยังพระเจ้าของเรา เพราะพระองค์จะทรงอภัยอย่างล้นเหลือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 8, 'เพราะความคิดของเราไม่เป็นความคิดของเจ้า ทั้งทางของเจ้าไม่เป็นวิถีของเรา” พระเยโฮวาห์ตรัสดังนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 9, '“เพราะฟ้าสวรรค์สูงกว่าแผ่นดินโลกฉันใด วิถีของเราสูงกว่าทางของเจ้า และความคิดของเราก็สูงกว่าความคิดของเจ้าฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 10, 'เพราะฝนและหิมะลงมาจากฟ้าสวรรค์ และไม่กลับที่นั่น เว้นแต่รดแผ่นดินโลก กระทําให้มันบังเกิดผลและแตกหน่อ อํานวยเมล็ดแก่ผู้หว่านและอาหารแก่ผู้กินฉันใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 11, 'คําของเราซึ่งออกไปจากปากของเราจะไม่กลับมาสู่เราเปล่า แต่จะสัมฤทธิ์ผลซึ่งเรามุ่งหมายไว้ และให้สิ่งซึ่งเราใช้ไปทํานั้นจําเริญขึ้นฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 12, 'เพราะเจ้าจะออกไปด้วยความชื่นบาน และถูกนําไปด้วยสันติภาพ ภูเขาและเนินเขาจะเปล่งเสียงร้องเพลงข้างหน้าเจ้า และต้นไม้ทั้งสิ้นในท้องทุ่งจะตบมือของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 13, 'แทนต้นหนามใหญ่ ต้นสนสามใบจะงอกขึ้น แทนต้นหนามย่อย ต้นน้ํามันเขียวจะงอกขึ้นและแด่พระเยโฮวาห์ มันจะเป็นชื่อ เพื่อเป็นหมายสําคัญนิรันดร์ ซึ่งจะไม่ถูกตัดออกเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 1, 'พระเยโฮวาห์ตรัสดังนี้ว่า “จงรักษาความยุติธรรมไว้ และกระทําความเที่ยงธรรม เพราะความรอดของเราใกล้จะมา และความชอบธรรมของเราจะเผยออก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 2, 'ความสุขย่อมมีแก่ผู้กระทําเช่นนี้ และแก่บุตรของมนุษย์ผู้ยึดไว้มั่น ผู้รักษาวันสะบาโตไม่เหยียดหยามวันนั้น และระวังมือของเขาจากการกระทําชั่วร้ายใดๆ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 3, 'อย่าให้บุตรชายของคนต่างชาติผู้เข้าจารีตถือพระเยโฮวาห์กล่าวว่า “พระเยโฮวาห์ได้ทรงแยกข้าแน่จากชนชาติของพระองค์” และอย่าให้ขันทีพูดว่า “ดูเถิด ข้าเป็นต้นไม้แห้ง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 4, 'เพราะพระเยโฮวาห์ตรัสดังนี้ว่า “เรื่องขันทีทั้งหลายผู้รักษาวันสะบาโตของเรา ผู้เลือกบรรดาสิ่งที่พอใจเรา และยึดพันธสัญญาของเราไว้มั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 5, 'ภายในนิเวศของเราและภายในกําแพงของเรา เราจะให้สถานที่และชื่อแก่เขาเหล่านั้น ที่ดีกว่าบุตรชายและบุตรสาว เราจะให้ชื่อนิรันดร์แก่เขาทั้งหลายซึ่งจะไม่ตัดออกเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 6, 'และบรรดาบุตรชายของคนต่างชาติผู้เข้าจารีตถือพระเยโฮวาห์ ปรนนิบัติพระองค์และรักพระนามของพระเยโฮวาห์ และเป็นผู้รับใช้ของพระองค์ ทุกคนผู้รักษาวันสะบาโต และมิได้เหยียดหยาม และยึดพันธสัญญาของเรามั่นไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 7, 'คนเหล่านี้เราจะนํามายังภูเขาบริสุทธิ์ของเรา และกระทําให้เขาชื่นบานอยู่ในนิเวศอธิษฐานของเรา เครื่องเผาบูชาของเขาและเครื่องสักการบูชาของเขา จะเป็นที่โปรดปรานบนแท่นบูชาของเรา เพราะนิเวศของเราเขาจะเรียกว่าเป็นนิเวศอธิษฐาน สําหรับบรรดาชนชาติทั้งหลาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 8, 'องค์พระผู้เป็นเจ้าพระเจ้าผู้ทรงรวบรวมอิสราเอลที่กระจัดกระจาย ตรัสว่า “เราจะรวบรวมคนอื่นมาไว้กับเขา นอกจากคนเหล่านั้นที่ได้รวบรวมไว้แล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 9, 'เจ้า บรรดาสัตว์ป่าทุ่ง มากินซิ ทั้งเจ้าบรรดาสัตว์ในป่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 10, 'ยามของเขาตาบอด เขาทั้งปวงไร้ความรู้ เขาทั้งปวงเป็นสุนัขใบ้ เขาเห่าไม่ได้ ได้แต่หลับ ได้แต่นอน รักแต่ง่วง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 11, 'เออ เขาเป็นสุนัขตะกละซึ่งไม่รู้จักอิ่ม เขาเป็นผู้เลี้ยงแกะที่เข้าใจไม่ได้ เขาทุกคนกลับไปตามทางเขาเอง ต่างก็หากําไรใส่ตนเอง ไม่เว้นสักคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 12, 'เขาทั้งหลายว่า “มาเถิด ให้เราเอาเหล้าองุ่น ให้เราเติมเมรัยให้เต็มตัวเรา และพรุ่งนี้ก็จะเหมือนวันนี้ใหญ่โตเกินขนาด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 1, 'คนชอบธรรมพินาศ และไม่มีใครเอาใจใส่ คนที่มีใจเมตตาถูกเอาไปเสีย ไม่มีใครพิจารณาว่าคนชอบธรรมถูกเอาไปเสียจากความชั่วร้ายที่จะมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 2, 'เขาจะเข้าไปในสันติภาพ ผู้ดําเนินในความเที่ยงธรรมของเขา ก็จะพักอยู่บนที่นอนของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 3, 'แต่เจ้าทั้งหลาย บรรดาบุตรชายของแม่มด เชื้อสายของคนล่วงประเวณีและหญิงแพศยา จงเข้ามาใกล้ที่นี่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 4, 'เจ้าทั้งหลายพูดเย้ยหยันใคร เจ้าอ้าปากเย้ยแลบลิ้นหลอกผู้ใด เจ้าเป็นลูกแห่งการละเมิด เป็นเชื้อสายแห่งความมุสามิใช่หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 5, 'คือเจ้าผู้ร้อนเร่าด้วยรูปเคารพภายใต้ต้นไม้เขียวทุกต้น ผู้ฆ่าลูกของเจ้าในหุบเขาใต้ซอกหิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 6, 'ส่วนของเจ้าอยู่ท่ามกลางหินเกลี้ยงเกลาแห่งลําธาร มัน มันเป็นส่วนของเจ้า เจ้าได้เทเครื่องดื่มบูชาและถวายธัญญบูชาให้แก่มัน เราจะรับการเล้าโลมในเรื่องสิ่งเหล่านี้หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 7, 'บนภูเขาสูงเด่น เจ้าได้ตั้งที่นอนของเจ้าไว้ และที่นั่นเจ้าไปถวายเครื่องสักการบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 8, 'เจ้าได้ตั้งอนุสาวรีย์ของเจ้าไว้หลังประตูและเสาประตู เจ้าจึงเปิดผ้าคลุมที่นอนของเจ้า เจ้าขึ้นไปบนนั้น เจ้าทําให้มันกว้าง และเจ้าตกลงกับมันเพื่อเจ้าเอง เจ้ารักที่นอนของมัน และเจ้าได้มองดูการเปลือย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 9, 'เจ้าเดินทางไปหากษัตริย์พร้อมกับน้ํามัน และทวีน้ําหอมของเจ้า เจ้าได้ส่งทูตของเจ้าไปไกล แม้ให้ลงไปจนถึงนรก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 10, 'เจ้าเหน็ดเหนื่อยเพราะระยะทางไกลของเจ้า แต่เจ้ามิได้พูดว่า “หมดหวัง” เจ้าประสบชีวิตแห่งมือของเจ้า และเจ้าจึงมิได้โศกเศร้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 11, 'เจ้าครั่นคร้ามและกลัวใคร เจ้าจึงได้มุสาอยู่นั่นเองและไม่นึกถึงเรา และไม่เอาใจใส่เราสักนิด เรามิได้ระงับปากอยู่เป็นเวลานานแล้วดอกหรือ อย่างนั้นซีเจ้าจึงไม่ยําเกรงเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 12, 'เราจะบอกถึงความชอบธรรมและการกระทําของเจ้า แต่มันก็จะไม่เป็นประโยชน์แก่เจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 13, 'เมื่อเจ้าร้องออกมาก็ให้สิ่งที่เจ้าสะสมไว้ช่วยเจ้าให้พ้นซี แต่ลมจะพัดมันไปเสียหมด เพียงลมหายใจจะหอบมันออกไป แต่ผู้ที่วางใจในเราจะได้แผ่นดินนั้นเป็นกรรมสิทธิ์ และจะได้ภูเขาบริสุทธิ์ของเราเป็นมรดก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 14, 'และจะมีเสียงว่า “พูนดิน พูนดินขึ้น และจงเตรียมทาง รื้อถอนอุปสรรคเสียจากทางของชนชาติของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 15, 'องค์ผู้สูงเด่น คือผู้อยู่ในนิรันดร์กาล ผู้ทรงพระนามว่าบริสุทธิ์ ตรัสดังนี้ว่า “เราอยู่ในที่ที่สูงและบริสุทธิ์ และอยู่กับผู้ที่มีจิตใจสํานึกผิดและถ่อมลง เพื่อจะรื้อฟื้นจิตใจของผู้ใจถ่อม และรื้อฟื้นใจของผู้สํานึกผิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 16, 'เพราะเราจะไม่ต่อสู้แย้งอยู่เป็นนิตย์ หรือโกรธอยู่เสมอ เพราะจิตวิญญาณจะอ่อนลงต่อหน้าเรา คือบรรดาจิตวิญญาณที่เราได้สร้างแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 17, 'เราโกรธเพราะความชั่วช้าแห่งความโลภของเขา เราตีเขา เราซ่อนตัวและโกรธ แต่เขายังหันกลับเดินตามชอบใจของเขาอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 18, 'เราได้เห็นวิธีการของเขาแล้ว แต่เราจะรักษาเขาให้หาย เราจะนําเขา และสนองเขากับผู้ไว้ทุกข์ให้เขาด้วยการเล้าโลม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 19, 'พระเยโฮวาห์ตรัสว่า “เราสร้างผลของริมฝีปาก สันติภาพ สันติภาพแก่คนไกลและคนใกล้ และเราจะรักษาเขาให้หาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 20, 'แต่คนชั่วนั้นเหมือนทะเลที่กําเริบ เพราะมันนิ่งอยู่ไม่ได้ และน้ําของมันก็กวนตมและเลนขึ้นมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 21, 'พระเจ้าของข้าพเจ้าตรัสว่า “ไม่มีสันติสุขแก่คนชั่วร้าย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 1, '“จงร้องดังๆ อย่าออมไว้ จงเปล่งเสียงของเจ้าเหมือนเป่าแตร จงแจ้งแก่ชนชาติของเราให้ทราบถึงเรื่องการละเมิดของเขา แก่วงศ์วานของยาโคบเรื่องบาปของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 2, 'แต่เขายังแสวงหาเราทุกวันและปีติยินดีที่จะรู้จักทางของเรา เหมือนกับว่าเขาเป็นประชาชาติที่ได้ทําความชอบธรรม และมิได้ละทิ้งกฎแห่งพระเจ้าของเขา เขาก็ขอข้อกฎอันเที่ยงธรรมจากเรา เขาทั้งหลายก็ปีติยินดีที่จะเข้ามาใกล้พระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 3, 'พวกเขากล่าวว่า ‘ทําไมข้าพระองค์ทั้งหลายได้อดอาหาร และพระองค์มิได้ทอดพระเนตร ทําไมข้าพระองค์ทั้งหลายได้ถ่อมตัวลง และพระองค์มิได้ทรงสนพระทัย’ ดูเถิด ในวันที่เจ้าอดอาหาร เจ้าทําตามใจของเจ้า และบีบบังคับคนงานของเจ้าทั้งหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 4, 'ดูเถิด เจ้าอดอาหารเพียงเพื่อวิวาทและต่อสู้ และเพื่อต่อยด้วยหมัดชั่วร้าย การอดอาหารอย่างของเจ้าในวันนี้จะไม่กระทําให้เสียงของเจ้าได้ยินไปถึงที่สูง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 5, 'อย่างนี้หรือเป็นการอดอาหารที่เราเลือก คือวันที่คนข่มตัว การก้มศีรษะของเขาลงเหมือนอ้อเล็ก และปูผ้ากระสอบและขี้เถ้ารองใต้เขา อย่างนี้หรือเจ้าจะเรียกการอย่างนี้ว่าการอดอาหาร และเป็นวันที่พระเยโฮวาห์โปรดปรานอย่างนั้นหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 6, 'การอดอาหารอย่างนี้ไม่ใช่หรือที่เราต้องการ คือการแก้พันธนะของความชั่ว การปลดเปลื้องภาระหนัก และการปล่อยให้ผู้ถูกบีบบังคับเป็นอิสระ และการหักแอกเสียทุกอัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 7, 'ไม่ใช่การที่จะปันอาหารของเจ้าให้กับผู้หิว และนําคนยากจนไร้บ้านเข้ามาในบ้านของเจ้า เมื่อเจ้าเห็นคนเปลือยกายก็คลุมกายเขาไว้ และไม่ซ่อนตัวของเจ้าจากญาติของเจ้าเอง ดอกหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 8, 'แล้วความสว่างของเจ้าจะพุ่งออกมาอย่างอรุณ และแผลของเจ้าจะเรียกเนื้อขึ้นมาอย่างรวดเร็ว ความชอบธรรมของเจ้าจะเดินนําหน้าเจ้า และสง่าราศีของพระเยโฮวาห์จะระวังหลังเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 9, 'แล้วเจ้าจะทูล และพระเยโฮวาห์จะทรงตอบ เจ้าจะร้องทูล และพระองค์จะตรัสว่า ‘เราอยู่นี่’ ถ้าเจ้าจะเอาออกไปจากท่ามกลางเจ้าเสีย ซึ่งแอก ซึ่งการชี้หน้า และซึ่งการพูดอย่างไร้สาระ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 10, 'ถ้าเจ้าทุ่มเทชีวิตของเจ้าแก่คนหิว และให้ผู้ถูกข่มใจได้อิ่มใจ แล้วความสว่างของเจ้าจะโผล่ขึ้นในความมืด และความมืดคลุ้มของเจ้าจะเป็นเหมือนเที่ยงวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 11, 'และพระเยโฮวาห์จะนําเจ้าอยู่เป็นนิตย์ และให้จิตใจเจ้าอิ่มในฤดูแล้ง และกระทําให้กระดูกของเจ้าอ้วนพี และเจ้าจะเป็นเหมือนสวนที่มีน้ํารด เหมือนน้ําพุ ที่น้ําของมันไม่ขาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 12, 'และพวกเจ้าจะได้สร้างสิ่งปรักหักพังโบราณขึ้นใหม่ เจ้าจะได้ซ่อมเสริมรากฐานของคนหลายชั่วอายุมาแล้วขึ้น เจ้าจะได้ชื่อว่า ‘เป็นผู้ซ่อมกําแพงที่พัง ผู้ซ่อมแซมถนนให้คืนคงเพื่อจะได้อาศัยอยู่’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 13, 'ถ้าเจ้าหยุดเหยียบย่ําวันสะบาโต คือจากการทําตามใจของเจ้าในวันบริสุทธิ์ของเรา และเรียกสะบาโตว่า วันปีติยินดี และเรียกวันบริสุทธิ์ของพระเยโฮวาห์ว่า วันมีเกียรติ ถ้าเจ้าให้เกียรติมัน ไม่ไปตามทางของเจ้าเอง หรือทําตามใจของเจ้า หรือพูดถ้อยคําของเจ้าเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 14, 'แล้วเจ้าจะได้ความปีติยินดีในพระเยโฮวาห์ และเราจะให้เจ้าขึ้นขี่อยู่บนที่สูงของแผ่นดินโลก และเราจะเลี้ยงเจ้าด้วยมรดกของยาโคบบิดาของเจ้า เพราะโอษฐ์ของพระเยโฮวาห์ได้ตรัสแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 1, 'ดูเถิด พระหัตถ์ของพระเยโฮวาห์มิได้สั้นลง ที่จะช่วยให้รอดไม่ได้ หรือพระกรรณตึง ซึ่งจะไม่ทรงได้ยิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 2, 'แต่ว่าความชั่วช้าของเจ้าทั้งหลายได้กระทําให้เกิดการแยกระหว่างเจ้ากับพระเจ้าของเจ้า และบาปของเจ้าทั้งหลายได้บังพระพักตร์ของพระองค์เสียจากเจ้า พระองค์จึงมิได้ยิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 3, 'เพราะมือของเจ้ามลทินด้วยโลหิต และนิ้วมือของเจ้าด้วยความชั่วช้า ริมฝีปากของเจ้าได้พูดคําเท็จ ลิ้นของเจ้าพึมพําความอธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 4, 'ไม่มีผู้ใดฟ้องอย่างยุติธรรม ไม่มีผู้ใดขึ้นศาลอย่างสัตย์จริง เขาทั้งหลายวางใจอยู่กับสิ่งที่ไม่เป็นสาระ เขาพูดเท็จ เขาตั้งครรภ์ความชั่วและคลอดความชั่วช้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 5, 'เขาฟักไข่งูทับทาง เขาทอใยแมงมุม เขาผู้กินไข่นั้นก็ตาย แม้ไข่ลูกใดถูกทุบ งูร้ายก็เป็นตัวขึ้นมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 6, 'ใยของมันจะใช้เป็นเสื้อผ้าไม่ได้ คนจะเอาสิ่งที่มันทํามาคลุมตัวไม่ได้ กิจการของมันเป็นการชั่วช้า และการกระทําอันทารุณก็อยู่ในมือของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 7, 'เท้าของเขาวิ่งไปหาความชั่ว และเขาเร่งไปหลั่งโลหิตไร้ความผิดให้ถึงตาย ความคิดของเขาเป็นความคิดชั่วช้า การล้างผลาญและการทําลายอยู่ในหนทางของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 8, 'เขาไม่รู้จักทางแห่งสันติสุข ไม่มีความยุติธรรมในวิถีของเขา เขาได้ทําให้ถนนของเขาคดโค้ง ผู้ใดที่เดินในนั้นจะไม่รู้จักสันติสุข');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 9, 'เพราะฉะนั้นความยุติธรรมจึงอยู่ห่างจากเราทั้งหลาย และความเที่ยงธรรมตามเราไม่ทัน เราทั้งหลายคอยท่าความสว่างและ ดูเถิด ความมืด คอยท่าความสุกใส แต่เราดําเนินในความมืดคลุ้ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 10, 'เราทั้งหลายคลําหากําแพงเหมือนคนตาบอด เราคลําหาราวกับว่าเราไม่มีลูกตา เราสะดุดในเวลาเที่ยงเหมือนในเวลากลางคืน เราอยู่ในที่โดดเดี่ยวเหมือนคนตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 11, 'เราทุกคนครางเหมือนหมี และพิลาปเหมือนนกเขา และมองหาความยุติธรรม แต่ไม่มีเลย หาความรอด แต่ก็อยู่ไกลจากเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 12, 'เพราะการละเมิดของข้าพระองค์ทั้งหลายทวีขึ้นต่อพระพักตร์พระองค์ และบาปของข้าพระองค์ก็ปรักปรําข้าพระองค์ เพราะการละเมิดของข้าพระองค์อยู่กับข้าพระองค์ ส่วนความชั่วช้าของข้าพระองค์ ข้าพระองค์ก็รู้จัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 13, 'คือการละเมิด การปฏิเสธพระเยโฮวาห์ การหันไปจากการติดตามพระเจ้าของเรา การพูดที่เป็นการบีบบังคับและการกบฏ การก่อและการกล่าวคําเท็จจากใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 14, 'ความยุติธรรมก็หันกลับ และความเที่ยงธรรมก็ยืนอยู่แต่ไกล เพราะความจริงล้มลงที่ถนนเสียแล้ว และความเที่ยงตรงเข้าไปไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 15, 'เออ สัจจะขาดอยู่ และผู้ใดที่พรากจากความชั่วก็ทําตัวให้เป็นเหยื่อ พระเยโฮวาห์ทรงเห็น แล้วไม่เป็นที่พอพระทัยพระองค์ที่ไม่มีความยุติธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 16, 'พระองค์ทรงเห็นว่าไม่มีคนใดเลย ทรงประหลาดพระทัยว่าไม่มีใครอ้อนวอนเผื่อ เพราะฉะนั้นพระกรของพระองค์เองก็นําความรอดมาสู่พระองค์ และความชอบธรรมของพระองค์ชูพระองค์ไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 17, 'พระองค์ทรงสวมความชอบธรรมเป็นทับทรวง และพระมาลาแห่งความรอดอยู่เหนือพระเศียรของพระองค์ พระองค์ทรงสวมฉลองพระองค์แห่งการแก้แค้นเป็นของคลุมพระกาย และเอาความกระตือรือร้นห่มพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 18, 'พระองค์จะทรงชําระให้ตามการกระทําของเขา คือพระพิโรธแก่ปรปักษ์ของพระองค์ และสิ่งสนองแก่ศัตรูของพระองค์ พระองค์จะทรงมอบการสนองแก่เกาะทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 19, 'เขาจึงจะยําเกรงพระนามพระเยโฮวาห์จากตะวันตก และสง่าราศีของพระองค์จากที่ตะวันขึ้น เมื่อศัตรูมาอย่างแม่น้ําเชี่ยว พระวิญญาณของพระเยโฮวาห์จะยกธงขึ้นสู้มัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 20, 'พระเยโฮวาห์ตรัสว่า “และพระผู้ไถ่จะเสด็จมายังศิโยน มายังบรรดาผู้อยู่ในยาโคบผู้หันจากการละเมิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 21, 'พระเยโฮวาห์ตรัสว่า “และฝ่ายเรา นี่เป็นพันธสัญญาของเรากับเขาทั้งหลาย คือวิญญาณของเราซึ่งอยู่เหนือเจ้า และคําของเราซึ่งเราใส่ไว้ในปากของเจ้าจะไม่พรากไปจากปากของเจ้า หรือจากปากเชื้อสายของเจ้า หรือจากปากของเชื้อสายแห่งเชื้อสายของเจ้า ตั้งแต่เวลานี้ไปจนกาลนิรันดร์” พระเยโฮวาห์ตรัสดังนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 1, '“จงลุกขึ้น ฉายแสง เพราะว่าความสว่างของเจ้ามาแล้ว และสง่าราศีของพระเยโฮวาห์ขึ้นมาเหนือเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 2, 'เพราะว่า ดูเถิด ความมืดจะคลุมแผ่นดินโลก และความมืดทึบจะคลุมชนชาติทั้งหลาย แต่พระเยโฮวาห์จะทรงขึ้นมาเหนือเจ้า และเขาจะเห็นสง่าราศีของพระองค์เหนือเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 3, 'และบรรดาประชาชาติจะมายังความสว่างของเจ้า และกษัตริย์ทั้งหลายยังความสุกใสแห่งการขึ้นของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 4, 'จงเงยตาของเจ้ามองให้รอบและดู เขาทั้งปวงมาอยู่ด้วยกัน เขาทั้งหลายมาหาเจ้า บุตรชายทั้งหลายของเจ้าจะมาจากที่ไกล และบุตรสาวทั้งหลายของเจ้าจะรับการเลี้ยงจากเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 5, 'แล้วเจ้าจะเห็นและโชติช่วงด้วยกัน ใจของเจ้าจะเกรงกลัวและใจกว้างขึ้น เพราะความอุดมสมบูรณ์ของทะเลจะหันมาหาเจ้า ความมั่งคั่งของบรรดาประชาชาติจะมายังเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 6, 'มวลอูฐจะมาห้อมล้อมเจ้า อูฐหนุ่มจากมีเดียนและเอฟาห์ บรรดาเหล่านั้นจากเชบาจะมา เขาจะนําทองคําและกํายาน และจะบอกข่าวดีถึงกิจการอันน่าสรรเสริญของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 7, 'ฝูงแพะแกะทั้งสิ้นแห่งเคดาร์จะรวมมาหาเจ้า แกะผู้ของเนบาโยทจะปรนนิบัติเจ้า มันจะขึ้นไปบนแท่นบูชาของเราอย่างเป็นที่โปรดปราน และเราจะให้นิเวศแห่งสง่าราศีของเราได้รับสง่าราศี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 8, 'เหล่านี้เป็นใครนะที่บินมาเหมือนเมฆ และเหมือนนกเขาไปยังหน้าต่างของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 9, 'แน่นอนเกาะทั้งหลายจะรอคอยเรา กําปั่นแห่งทารชิชก่อน เพื่อนําบุตรชายของเจ้ามาแต่ไกล นําเงินและทองคําของเขามาด้วย เพื่อพระนามแห่งพระเยโฮวาห์พระเจ้าของเจ้า และเพื่อองค์บริสุทธิ์แห่งอิสราเอล เพราะพระองค์ได้ทรงกระทําให้เจ้าได้รับสง่าราศี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 10, 'เหล่าบุตรชายของคนต่างด้าวจะสร้างกําแพงของเจ้าขึ้น และกษัตริย์ของเขาจะปรนนิบัติเจ้า เพราะด้วยความพิโรธของเรา เราเฆี่ยนเจ้า แต่ด้วยความโปรดปรานของเรา เราได้กรุณาเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 11, 'ประตูเมืองของเจ้าจึงจะเปิดอยู่เสมอ ทั้งกลางวันและกลางคืนมันจะไม่ปิด เพื่อคนจะนําความมั่งคั่งของบรรดาประชาชาติมาให้เจ้า พร้อมด้วยกษัตริย์ทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 12, 'เพราะว่าประชาชาติและราชอาณาจักรที่จะไม่ปรนนิบัติเจ้าจะพินาศ เออ บรรดาประชาชาติเหล่านั้นจะถูกทิ้งร้างอย่างสิ้นเชิง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 13, 'สง่าราศีแห่งเลบานอนจะมายังเจ้า คือต้นสนสามใบ ต้นสนเขาและต้นไม้ที่เขียวชะอุ่มตลอดปีด้วยกัน เพื่อจะกระทําให้ที่แห่งสถานบริสุทธิ์ของเรางดงาม และเราจะกระทําให้ที่แห่งเท้าของเรารุ่งโรจน์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 14, 'บุตรชายของคนเหล่านั้นที่ได้บีบบังคับเจ้าจะมาโค้งลงต่อเจ้า และบรรดาผู้ที่ดูหมิ่นเจ้าจะกราบลงที่ฝ่าเท้าของเจ้า เขาทั้งหลายจะเรียกเจ้าว่า ‘เป็นพระนครของพระเยโฮวาห์ ศิโยนแห่งองค์บริสุทธิ์ของอิสราเอล’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 15, 'ในเมื่อเจ้าได้ถูกละทิ้งและเป็นที่เกลียดชัง และไม่มีใครผ่านเจ้ามาเลย เราจะกระทําให้เจ้าโอ่อ่าตระการเป็นนิตย์ เป็นความชื่นบานทุกชั่วอายุ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 16, 'เจ้าจะได้ดูดน้ํานมของบรรดาประชาชาติ เจ้าจะได้ดูดนมของบรรดากษัตริย์ และเจ้าจะรู้ว่า เราพระเยโฮวาห์ เป็นพระผู้ช่วยให้รอดของเจ้า และพระผู้ไถ่ของเจ้า องค์อานุภาพของยาโคบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 17, 'แทนทองเหลือง เราจะนํามาซึ่งทองคํา และแทนเหล็ก เราจะนํามาซึ่งเงิน แทนไม้ ทองเหลือง แทนหิน เหล็ก เราจะกระทําให้สันติภาพเป็นผู้ครอบครองของเจ้า และความชอบธรรมเป็นนายงานของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 18, 'ในแผ่นดินของเจ้าเขาจะไม่ได้ยินถึงความทารุณอีก ในเขตแดนของเจ้า ถึงการล้างผลาญหรือการทําลาย แต่เจ้าจะเรียกกําแพงของเจ้าว่า ‘ความรอด’ และประตูเมืองของเจ้าว่า ‘ความสรรเสริญ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 19, 'ดวงอาทิตย์จะไม่เป็นความสว่างของเจ้าในกลางวันอีก หรือดวงจันทร์จะไม่ให้แสงแก่เจ้าในกลางคืนเพื่อเป็นความสุกใส แต่พระเยโฮวาห์จะทรงเป็นความสว่างเป็นนิตย์ของเจ้า และพระเจ้าของเจ้าจะเป็นสง่าราศีของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 20, 'ดวงอาทิตย์ของเจ้าจะไม่ตกอีก หรือดวงจันทร์ของเจ้าจะไม่มีข้างแรม เพราะพระเยโฮวาห์จะทรงเป็นความสว่างนิรันดร์ของเจ้า และวันที่เจ้าไว้ทุกข์จะหมดสิ้นไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 21, 'ชนชาติของเจ้าจะชอบธรรมทั้งสิ้น เขาจะได้แผ่นดินนั้นเป็นกรรมสิทธิ์เป็นนิตย์ หน่อที่เราปลูก และผลงานแห่งมือของเรานั้น เพื่อเราจะรับสง่าราศี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 22, 'ผู้เล็กน้อยที่สุดจะเป็นพันๆ และผู้นิดที่สุดจะเป็นประชาชาติอันมีอานุภาพ เราคือพระเยโฮวาห์ ถึงเวลาเราก็จะเร่ง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 1, '“พระวิญญาณแห่งองค์พระผู้เป็นเจ้าพระเจ้าสถิตอยู่บนข้าพเจ้า เพราะว่าพระเยโฮวาห์ได้ทรงเจิมตั้งข้าพเจ้าไว้ให้ประกาศข่าวประเสริฐมายังผู้ที่ถ่อมใจ พระองค์ได้ทรงใช้ข้าพเจ้าให้รักษาคนที่ชอกช้ําระกําใจ ให้ร้องประกาศอิสรภาพแก่บรรดาเชลย และบอกการเปิดเรือนจําออกให้แก่ผู้ที่ถูกจองจํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 2, 'เพื่อประกาศปีแห่งความโปรดปรานของพระเยโฮวาห์ และวันแห่งการแก้แค้นของพระเจ้าของเรา เพื่อเล้าโลมบรรดาผู้ที่ไว้ทุกข์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 3, 'เพื่อจัดให้บรรดาผู้ที่ไว้ทุกข์ในศิโยน เพื่อประทานความสวยงามแทนขี้เถ้าให้เขา น้ํามันแห่งความยินดีแทนการไว้ทุกข์ ผ้าห่มแห่งการสรรเสริญแทนจิตใจที่ท้อถอย เพื่อคนจะเรียกเขาว่าต้นไม้แห่งความชอบธรรม ที่ซึ่งพระเยโฮวาห์ทรงปลูกไว้ เพื่อพระองค์จะทรงได้รับสง่าราศี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 4, 'เขาทั้งหลายจะสร้างที่ที่ถูกทิ้งไว้เสียเปล่าแต่โบราณขึ้นใหม่ เขาจะก่อซากปรักหักพังแต่ก่อนขึ้นมาอีก เขาจะซ่อมหัวเมืองที่ถูกทิ้งไว้เสียเปล่านั้น คือที่ที่รกร้างมาหลายชั่วอายุคนแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 5, 'คนต่างถิ่นจะยืนเลี้ยงฝูงแพะแกะของเจ้าทั้งหลาย บุตรชายทั้งหลายของคนต่างด้าวจะเป็นคนไถนาและคนแต่งเถาองุ่นของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 6, 'แต่เจ้าทั้งหลายจะได้ชื่อว่า ปุโรหิตของพระเยโฮวาห์ คนจะเรียกเจ้าทั้งหลายว่า เป็นผู้ปรนนิบัติของพระเจ้าของเรา เจ้าทั้งหลายจะได้รับประทานความมั่งคั่งของบรรดาประชาชาติ และเจ้าจะอวดในสง่าราศีของเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 7, 'แทนความอายของเจ้าทั้งหลาย เจ้าจะได้ส่วนสองส่วน แทนความอดสู เขาทั้งหลายจะเปรมปรีดิ์ในส่วนของเขา เพราะฉะนั้นในแผ่นดินของเขาทั้งหลาย เขาจะได้สองส่วนเป็นกรรมสิทธิ์ ความชื่นบานเป็นนิตย์จะเป็นของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 8, 'เพราะเราคือพระเยโฮวาห์รักความยุติธรรม เราเกลียดการขโมยเพื่อได้เครื่องเผาบูชา เราจะนํากิจการของเขาด้วยความจริง และเราจะกระทําพันธสัญญานิรันดร์กับเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 9, 'เชื้อสายของเขาทั้งหลายจะเป็นที่รู้จักกันท่ามกลางบรรดาประชาชาติ และลูกหลานของเขาในท่ามกลางชนชาติทั้งหลาย ทุกคนที่ได้เห็นเขาจะจําเขาได้ ว่าเขาเป็นเชื้อสายซึ่งพระเยโฮวาห์ทรงอํานวยพระพร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 10, 'ข้าพเจ้าจะเปรมปรีดิ์อย่างยิ่งในพระเยโฮวาห์ จิตใจของข้าพเจ้าจะเริงโลดในพระเจ้าของข้าพเจ้า เพราะพระองค์ได้ทรงสวมข้าพเจ้าด้วยเสื้อผ้าแห่งความรอด พระองค์ทรงคลุมข้าพเจ้าด้วยเสื้อแห่งความชอบธรรม อย่างเจ้าบ่าวประดับตัวด้วยเครื่องประดับ และอย่างเจ้าสาวตกแต่งตัวด้วยเพชรนิลจินดา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 11, 'เพราะแผ่นดินโลกได้เกิดหน่อของมัน และสวนทําให้สิ่งที่หว่านในนั้นงอกขึ้นมาฉันใด องค์พระผู้เป็นเจ้าพระเจ้าจะทรงทําให้ความชอบธรรมและความสรรเสริญงอกขึ้นมาต่อหน้าบรรดาประชาชาติฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 1, 'เพื่อเห็นแก่ศิโยน ข้าพเจ้าจะไม่ระงับเสียง และเพื่อเห็นแก่เยรูซาเล็ม ข้าพเจ้าจะไม่นิ่งเฉยอยู่ จนกว่าความชอบธรรมของกรุงนี้จะออกไปอย่างความสุกใส และความรอดของกรุงนี้อย่างคบเพลิงที่ลุกอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 2, 'บรรดาประชาชาติจะเห็นความชอบธรรมของเจ้า และกษัตริย์ทั้งหลายจะเห็นสง่าราศีของเจ้า และเขาจะเรียกเจ้าด้วยชื่อใหม่ ซึ่งพระโอษฐ์ของพระเยโฮวาห์จะประทาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 3, 'เจ้าจะเป็นมงกุฎแห่งสง่าราศีในพระหัตถ์ของพระเยโฮวาห์ และเป็นราชมงกุฎในพระหัตถ์แห่งพระเจ้าของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 4, 'เขาจะไม่ขนานนามเจ้าอีกว่า “ถูกทอดทิ้ง” และเขาจะไม่เรียกแผ่นดินของเจ้าอีกว่า “ซึ่งร้างเปล่า” แต่เขาจะเรียกเจ้าว่า “เฮฟซีบาห์” และเรียกแผ่นดินของเจ้าว่า “บิวลาห์” เพราะพระเยโฮวาห์ทรงปีติยินดีในเจ้า และแผ่นดินของเจ้าจะแต่งงาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 5, 'เพราะชายหนุ่มแต่งงานกับหญิงพรหมจารีฉันใด บุตรชายทั้งหลายของเจ้าจะแต่งกับเจ้าฉันนั้น และเจ้าบ่าวเปรมปรีดิ์เพราะเจ้าสาวฉันใด พระเจ้าของเจ้าจะเปรมปรีดิ์เพราะเจ้าฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 6, 'โอ เยรูซาเล็มเอ๋ย บนกําแพงของเจ้า เราได้วางยามไว้ ตลอดกลางวันและตลอดกลางคืนเขาทั้งหลายจะไม่ระงับเสียงเลย เจ้าทั้งหลายผู้ที่กล่าวถึงพระเยโฮวาห์ ไม่ต้องระงับเสียง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 7, 'และอย่าให้พระองค์หยุดพักจนกว่าพระองค์จะสถาปนาและกระทํากรุงเยรูซาเล็มให้เป็นที่สรรเสริญในแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 8, 'พระเยโฮวาห์ทรงปฏิญาณด้วยพระหัตถ์ขวาของพระองค์ และด้วยพระกรอานุภาพของพระองค์ว่า “แน่นอนเราจะไม่ให้ข้าวของเจ้าเป็นอาหารของศัตรูของเจ้าอีก และบรรดาบุตรชายของคนต่างด้าวจะไม่ดื่มน้ําองุ่นของเจ้า ซึ่งเจ้าตรากตรําได้มานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 9, 'แต่ผู้ใดที่เกี่ยวเก็บไว้จะได้กินและสรรเสริญพระเยโฮวาห์ และบรรดาผู้ที่เก็บรวบรวมจะได้ดื่มในลานสถานอันบริสุทธิ์ของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 10, 'จงไป จงไปทางประตูเมือง จัดเตรียมทางไว้ให้ชนชาตินี้ จงพูน จงพูนทางหลวงขึ้น จงเก็บกวาดหินเสียให้หมด จงยกสัญญาณไว้เหนือชนชาติทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 11, 'ดูเถิด พระเยโฮวาห์ได้ทรงร้องประกาศให้ได้ยินถึงปลายแผ่นดินโลกว่า “จงกล่าวแก่ธิดาของศิโยนว่า ‘ดูเถิด ความรอดของเจ้ามา ดูเถิด รางวัลของพระองค์ก็อยู่กับพระองค์ และพระราชกิจของพระองค์ก็อยู่ต่อพระพักตร์ของพระองค์’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 12, 'และคนจะเรียกเขาทั้งหลายว่า “ประชาชนบริสุทธิ์ ผู้รับไถ่ไว้แล้วของพระเยโฮวาห์” และเขาจะเรียกเจ้าว่า “หามาได้ เมืองที่มิได้ถูกทอดทิ้ง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 1, 'นี่ใครหนอที่มาจากเมืองเอโดม สวมเสื้อผ้าย้อมสีจากเมืองโบสราห์ พระองค์ผู้ซึ่งโอ่อ่าในเครื่องทรงของพระองค์ เสด็จมาด้วยกําลังยิ่งใหญ่ของพระองค์ “นี่เราเองร้องประกาศในความชอบธรรมและมีอานุภาพที่จะช่วยให้รอด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 2, 'ทําไมเครื่องทรงของพระองค์จึงสีแดง และเสื้อผ้าของพระองค์เหมือนกับของคนที่ย่ําในบ่อย่ําองุ่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 3, '“เราได้ย่ําบ่อองุ่นแต่ลําพัง และไม่มีใครจากชนชาติทั้งหลายอยู่กับเราเลย เราจะย่ํามันด้วยความโกรธของเรา เราเหยียบมันด้วยความพิโรธของเรา โลหิตของเขาจะพรมอยู่บนเสื้อผ้าของเรา และเราจะทําให้เสื้อผ้าของเราเปื้อนหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 4, 'เพราะวันแก้แค้นอยู่ในใจของเรา และปีแห่งการไถ่ของเราได้มาถึง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 5, 'เรามอง แต่ไม่มีผู้ใดช่วยเหลือ เราประหลาดใจว่าไม่มีผู้ชูไว้ เพราะฉะนั้นแขนของเราเองจึงนําความรอดมาให้เรา และความพิโรธของเรา ชูเราไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 6, 'เราจะย่ําชนชาติทั้งหลายลงด้วยความโกรธของเรา เราทําให้เขาเมาด้วยความพิโรธของเรา และเราจะทําให้กําลังของเขาถดถอยลงบนแผ่นดินโลก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 7, 'ข้าพเจ้าจะกล่าวถึงความเมตตาแห่งพระเยโฮวาห์ และการสรรเสริญของพระเยโฮวาห์ ตามบรรดาซึ่งพระเยโฮวาห์ประทานแก่พวกเรา และความดียิ่งใหญ่ต่อวงศ์วานของอิสราเอล ซึ่งพระองค์ทรงอนุมัติให้ตามพระกรุณาของพระองค์ ตามความเมตตาอันอุดมสมบูรณ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 8, 'เพราะพระองค์ตรัสว่า “แน่ทีเดียวเขาเป็นชนชาติของเรา บุตรผู้จะไม่พูดมุสา” และพระองค์ได้เป็นพระผู้ช่วยให้รอดของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 9, 'พระองค์ทรงทุกข์พระทัยในความทุกข์ใจทั้งสิ้นของเขา และทูตสวรรค์ที่อยู่ต่อพระพักตร์พระองค์ช่วยเขาทั้งหลายให้รอด พระองค์ทรงไถ่เขาด้วยความรักของพระองค์ และด้วยความสงสารของพระองค์ สมัยเก่าก่อนพระองค์ทรงยกเขาขึ้นและอุ้มเขาไปตลอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 10, 'แต่เขาทั้งหลายได้กบฏ และทําให้พระวิญญาณบริสุทธิ์ของพระองค์เสียพระทัย ฉะนั้นพระองค์จึงทรงหันเป็นศัตรูของเขาทั้งหลาย และพระองค์ทรงต่อสู้กับเขาทั้งหลายเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 11, 'แล้วพระองค์ทรงระลึกถึงสมัยเก่าก่อน ถึงโมเสส ถึงชนชาติของพระองค์ว่า “พระองค์ผู้ทรงนําเขาทั้งหลายขึ้นมาจากทะเลพร้อมกับผู้เลี้ยงแพะแกะของพระองค์อยู่ที่ไหน พระองค์ทรงอยู่ที่ไหน ผู้ซึ่งบรรจุพระวิญญาณบริสุทธิ์ของพระองค์ท่ามกลางเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 12, 'ผู้นําเขาทั้งหลายทางมือขวาของโมเสสด้วยพระกรอันรุ่งโรจน์ของพระองค์ ผู้แยกน้ําออกต่อหน้าเขาทั้งหลาย เพื่อสร้างพระนามนิรันดร์ให้พระองค์เอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 13, 'ผู้ได้นําเขาทั้งหลายข้ามทะเลนั้นเหมือนม้าในถิ่นทุรกันดาร เพื่อเขาทั้งหลายจะมิได้สะดุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 14, 'อย่างสัตว์เลี้ยงไปยังหุบเขาฉันใด พระวิญญาณของพระเยโฮวาห์ประทานให้เขาหยุดพักฉันนั้น” ฉะนั้นพระองค์จึงทรงนําชนชาติของพระองค์ เพื่อจะสร้างพระนามอันรุ่งโรจน์แด่พระองค์เอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 15, 'ขอทอดพระเนตรลงมาจากฟ้าสวรรค์ และทรงเพ่งดูจากสถานบริสุทธิ์และรุ่งโรจน์ของพระองค์ ความกระตือรือร้นและอานุภาพของพระองค์อยู่ที่ไหน พระทัยกรุณาและพระเมตตาของพระองค์ต่อข้าพระองค์อยู่ที่ไหน ได้ถูกยึดไว้แล้วหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 16, 'แน่นอนพระองค์ทรงเป็นพระบิดาของข้าพระองค์ทั้งหลาย แม้อับราฮัมมิได้รู้จักข้าพระองค์ และอิสราเอลหาจําข้าพระองค์ได้ไม่ โอ ข้าแต่พระเยโฮวาห์ พระองค์ทรงเป็นพระบิดาและพระผู้ไถ่ของข้าพระองค์ทั้งหลาย พระนามของพระองค์ดํารงอยู่ตั้งแต่นิรันดร์กาล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 17, 'โอ ข้าแต่พระเยโฮวาห์ ไฉนพระองค์ทรงกระทําให้ข้าพระองค์ทั้งหลายผิดไปจากพระมรรคาของพระองค์ และกระทําใจของข้าพระองค์ให้แข็งกระด้างจนข้าพระองค์ไม่ยําเกรงพระองค์ ขอพระองค์ทรงกลับมาเพื่อเห็นแก่บรรดาผู้รับใช้ของพระองค์คือ ตระกูลทั้งหลายอันเป็นมรดกของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 18, 'ชนชาติแห่งความบริสุทธิ์ของพระองค์ได้อาศัยอยู่ที่นั่นแค่ประเดี๋ยวหนึ่ง ปฏิปักษ์ของข้าพระองค์ทั้งหลายได้เหยียบย่ําสถานบริสุทธิ์ของพระองค์ลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 19, 'ข้าพระองค์ทั้งหลายเป็นของพระองค์ พระองค์ไม่เคยปกครองพวกเขาเลย เขาไม่ได้เรียกพวกเขาโดยพระนามของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 1, 'โอ ถ้าหากว่าพระองค์จะทรงแหวกฟ้าสวรรค์เสด็จลงมาได้หนอ เพื่อภูเขาจะไหลลงมาต่อพระพักตร์พระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 2, 'ดังเมื่อไฟที่ทําให้ละลายไหม้อยู่ และไฟกระทําให้น้ําเดือด เพื่อให้พระนามของพระองค์เป็นที่รู้จักแก่ปฏิปักษ์ของพระองค์ เพื่อบรรดาประชาชาติจะสะเทือนต่อพระพักตร์พระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 3, 'เมื่อพระองค์ทรงกระทําสิ่งน่ากลัวที่พวกข้าพระองค์คาดไม่ถึง พระองค์เสด็จลงมา ภูเขาก็เคลื่อนที่ลงมาต่อพระพักตร์พระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 4, 'โอ ข้าแต่พระเจ้า ตั้งแต่เริ่มแรกของโลก ไม่มีผู้ใดได้ยิน หรือทราบด้วยหู หรือตาได้เห็น สิ่งทั้งหลายซึ่งพระองค์ทรงเตรียมไว้เพื่อบรรดาผู้ที่รอคอยพระองค์ นอกเหนือพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 5, 'พระองค์ทรงพบเขาที่ชื่นบานและกระทําความชอบธรรม บรรดาผู้ที่จําพระองค์ได้ในวิธีการของพระองค์ ดูเถิด พระองค์ทรงกริ้ว เพราะข้าพระองค์ทั้งหลายทําบาปแล้ว ข้าพระองค์ทั้งหลายยังอยู่ในบาปเป็นเวลานาน และข้าพระองค์ทั้งหลายจะรอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 6, 'ข้าพระองค์ทุกคนได้กลายเป็นเหมือนสิ่งที่ไม่สะอาด และการกระทําอันชอบธรรมของข้าพระองค์ทั้งสิ้นเหมือนเสื้อผ้าที่สกปรก ข้าพระองค์ทุกคนเหี่ยวลงอย่างใบไม้ และความชั่วช้าของข้าพระองค์ทั้งหลายได้พัดพาข้าพระองค์ไปเหมือนลม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 7, 'ไม่มีผู้ใดร้องทูลต่อพระนามของพระองค์ ที่เร้าตนเองให้ยึดพระองค์ไว้ เพราะพระองค์ทรงซ่อนพระพักตร์ของพระองค์จากข้าพระองค์ทั้งหลาย และได้ผลาญข้าพระองค์ทั้งหลายเพราะเหตุความชั่วช้าของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 8, 'โอ ข้าแต่พระเยโฮวาห์ แต่บัดนี้พระองค์ยังทรงเป็นพระบิดาของข้าพระองค์ ข้าพระองค์ทั้งหลายเป็นดินเหนียว และพระองค์ทรงเป็นช่างปั้น ข้าพระองค์ทุกคนเป็นผลพระหัตถกิจของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 9, 'โอ ข้าแต่พระเยโฮวาห์ ขออย่าทรงกริ้วนัก และขออย่าทรงจดจําความชั่วช้าไว้เป็นนิตย์ ดูเถิด ขอทรงพิเคราะห์ ข้าพระองค์ทั้งสิ้นเป็นชนชาติของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 10, 'หัวเมืองบริสุทธิ์ของพระองค์กลายเป็นถิ่นทุรกันดาร ศิโยนได้กลายเป็นถิ่นทุรกันดาร เยรูซาเล็มเป็นที่รกร้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 11, 'นิเวศอันบริสุทธิ์และงามของข้าพระองค์ทั้งหลาย ที่ซึ่งบรรพบุรุษของข้าพระองค์สรรเสริญพระองค์ถูกไฟเผาเสียแล้ว และสิ่งอันน่าปรารถนาของข้าพระองค์ทั้งสิ้นได้ถูกทิ้งร้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 12, 'โอ ข้าแต่พระเยโฮวาห์ เป็นอย่างนี้แล้ว พระองค์ยังจะทรงยับยั้งพระองค์ไว้หรือ พระองค์จะทรงเงียบอยู่และข่มใจพวกข้าพระองค์อย่างถึงขนาดหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 1, '“คนเหล่านั้นที่มิได้ขอพบเรา แสวงหาเรา คนเหล่านั้นที่มิได้แสวงหาเราได้พบเรา เราว่า ‘เราอยู่ที่นี่ เราอยู่ที่นี่’ ต่อประชาชาติที่เขาไม่ได้เรียกโดยนามของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 2, 'เรายื่นมือของเราออกตลอดวันต่อชนชาติที่มักกบฏ ผู้ดําเนินในทางที่ไม่ดี ติดตามอุบายของตนเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 3, 'ชนชาติที่ยั่วเย้าเราให้กริ้วต่อหน้าอยู่เสมอ ทําการสักการบูชาตามสวน และเผาเครื่องหอมอยู่บนกองอิฐ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 4, 'ผู้ยังคงอยู่ท่ามกลางอุโมงค์ฝังศพ และค้างคืนในโบราณสถาน ผู้กินเนื้อหมู และในภาชนะของเขามีแกงซึ่งทําด้วยเนื้อที่น่าสะอิดสะเอียน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 5, 'ผู้กล่าวว่า ‘ออกไปห่างๆ อย่าเข้ามาใกล้ เพราะข้าบริสุทธิ์กว่าเจ้า’ เหล่านี้เป็นควันอยู่ในจมูกของเรา เป็นไฟซึ่งไหม้อยู่วันยังค่ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 6, 'ดูเถิด มีเขียนไว้ต่อหน้าเราว่า ‘เราจะไม่นิ่งเฉย แต่เราจะตอบสนอง เออ เราจะตอบสนองไว้ในอกของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 7, 'ทั้งความชั่วช้าของเจ้าและความชั่วช้าของบรรพบุรุษของเจ้าทั้งหลายรวมกันด้วย’” พระเยโฮวาห์ตรัสดังนี้ว่า “เขาได้เผาเครื่องหอมบนภูเขา และกล่าวหยาบช้าต่อเราบนเนิน เราจึงจะตวงกิจการเก่าเข้าไปในอกของเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 8, 'พระเยโฮวาห์ตรัสดังนี้ว่า “น้ําองุ่นใหม่หาได้จากพวงองุ่นและเขากล่าวว่า ‘อย่าทําลายมันเสีย เพราะมีพระพรอยู่ในนั้น’ ฉันใด เราก็จะกระทําด้วยเห็นแก่ผู้รับใช้ของเรา และไม่ทําลายเขาหมดทีเดียวฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 9, 'เราจะนําเชื้อสายออกมาจากยาโคบ และผู้รับมรดกภูเขาทั้งหลายของเราจากยูดาห์ ผู้เลือกสรรของเราจะได้รับมันเป็นมรดก และบรรดาผู้รับใช้ของเราจะอาศัยอยู่ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 10, 'ชาโรนจะเป็นลานหญ้าสําหรับฝูงแพะแกะ และหุบเขาอาโคร์จะเป็นที่ให้ฝูงวัวนอน เพื่อชนชาติของเราที่ได้แสวงหาเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 11, 'แต่เจ้าทั้งหลายจะทอดทิ้งพระเยโฮวาห์ ผู้ลืมภูเขาบริสุทธิ์ของเรา ผู้จัดสํารับไว้ให้แก่พระโชค และจัดหาเครื่องดื่มบูชาให้แก่พระเคราะห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 12, 'เพราะฉะนั้นเราจะนับรวมเจ้าทั้งหลายไว้กับดาบ และเจ้าทุกคนจะต้องหมอบลงต่อการสังหาร เพราะเมื่อเราเรียก เจ้าไม่ตอบ เมื่อเราพูด เจ้าไม่ฟัง แต่ได้กระทําชั่วในสายตาของเรา และเลือกสิ่งที่เราไม่ปีติยินดีด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 13, 'เพราะฉะนั้นองค์พระผู้เป็นเจ้าพระเจ้าจึงตรัสดังนี้ว่า “ดูเถิด ผู้รับใช้ทั้งหลายของเราจะได้รับประทาน แต่เจ้าทั้งหลายจะหิว ดูเถิด ผู้รับใช้ของเราจะได้ดื่ม แต่เจ้าจะกระหาย ดูเถิด ผู้รับใช้ของเราจะเปรมปรีดิ์ แต่เจ้าจะได้อาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 14, 'ดูเถิด ผู้รับใช้ของเราจะร้องเพลงเพราะใจยินดี แต่เจ้าทั้งหลายจะร้องออกมาเพราะเสียใจ และจะครวญครางเพราะจิตระทม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 15, 'เจ้าทั้งหลายจะทิ้งชื่อของเจ้าไว้แก่ผู้เลือกสรรของเราเพื่อใช้แช่ง และองค์พระผู้เป็นเจ้าพระเจ้าจะทรงสังหารเจ้า แต่จะทรงเรียกชื่อผู้รับใช้ของพระองค์ด้วยชื่ออื่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 16, 'ดังนั้น ผู้ใดที่ขอพรให้ตนเองในแผ่นดินโลก จะขอพรให้ตนเองในพระนามพระเจ้าแห่งความจริง และผู้ใดที่ปฏิญาณในแผ่นดินโลก จะปฏิญาณในนามพระเจ้าแห่งความจริง เพราะความลําบากเก่าแก่นั้นก็ลืมเสียแล้ว และซ่อนเสียจากตาของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 17, 'เพราะ ดูเถิด เราจะสร้างฟ้าสวรรค์ใหม่และแผ่นดินโลกใหม่ เพราะสิ่งเก่าก่อนนั้นจะไม่จํากันหรือนึกได้อีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 18, 'แต่จงชื่นบานและเปรมปรีดิ์เป็นนิตย์ในสิ่งซึ่งเราสร้างขึ้น เพราะ ดูเถิด เราสร้างเยรูซาเล็มให้เป็นที่เปรมปรีดิ์ และชนชาติของเมืองนั้นให้เป็นความชื่นบาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 19, 'เราจะเปรมปรีดิ์ด้วยเยรูซาเล็มและชื่นบานด้วยชนชาติของเรา จะไม่ได้ยินเสียงร้องไห้ในเมืองนั้นอีก และเสียงครวญคราง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 20, 'ในนั้นจะไม่มีทารกที่มีชีวิตเพียงสองสามวัน หรือคนแก่ที่มีอายุไม่ครบกําหนด เพราะเด็กจะมีอายุหนึ่งร้อยปีจึงตาย และคนบาปที่มีอายุเพียงหนึ่งร้อยปีจะเป็นที่แช่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 21, 'เขาจะสร้างบ้านและเข้าอาศัยอยู่ในนั้น เขาจะปลูกสวนองุ่นและกินผลของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 22, 'เขาจะไม่สร้างและคนอื่นเข้าอาศัยอยู่ เขาจะไม่ปลูกและคนอื่นกิน เพราะอายุชนชาติของเราจะเป็นเหมือนอายุของต้นไม้ และผู้เลือกสรรของเราจะใช้ผลงานน้ํามือของเขานาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 23, 'เขาทั้งหลายจะไม่ทํางานโดยเปล่าประโยชน์ หรือคลอดบุตรเพื่อความสยดสยอง เพราะเขาเป็นเชื้อสายของผู้ที่ได้รับพรของพระเยโฮวาห์ กับลูกๆของเขาด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 24, 'และต่อมา ก่อนที่เขาร้องเรียก เราจะตอบ ขณะที่เขายังพูดอยู่ เราจะฟัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 25, 'สุนัขป่าและลูกแกะจะหากินอยู่ด้วยกัน สิงโตจะกินฟางเหมือนวัว และผงคลีจะเป็นอาหารของงู มันทั้งหลายจะไม่ทําอันตรายหรือทําลายทั่วภูเขาบริสุทธิ์ของเรา” พระเยโฮวาห์ตรัสดังนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 1, 'พระเยโฮวาห์ตรัสดังนี้ว่า “สวรรค์เป็นบัลลังก์ของเรา และแผ่นดินโลกเป็นแท่นวางเท้าของเรา นิเวศซึ่งเจ้าจะสร้างให้เรานั้นจะอยู่ที่ไหนเล่า และที่พํานักของเราอยู่ที่ไหน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 2, 'สิ่งเหล่านี้มือของเราได้กระทําทั้งสิ้น บรรดาสิ่งเหล่านั้นจึงเป็นขึ้นมา” พระเยโฮวาห์ตรัสดังนี้ “แต่คนนี้ต่างหากที่เราจะมอง คือเขาผู้ที่ถ่อมลงและสํานึกผิดในใจ และตัวสั่นเพราะคําของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 3, 'เขาผู้ฆ่าวัวเป็นเหมือนกับเขาฆ่าคน เขาผู้ถวายลูกแกะเป็นเครื่องบูชาเป็นเหมือนกับเขาตัดคอสุนัข เขาผู้ถวายเครื่องบูชาเป็นเหมือนกับเขาถวายเลือดหมู เขาผู้เผาเครื่องหอมเป็นเหมือนกับเขาสาธุการรูปเคารพ คนเหล่านี้ต่างก็เลือกทางของเขาเอง และจิตใจของเขาปีติยินดีอยู่ในสิ่งน่าสะอิดสะเอียนของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 4, 'เราก็จะเลือกการหลอกหลอนมาให้เขาด้วย และนําสิ่งที่เขากลัวมาถึงเขา เพราะเมื่อเราได้เรียก ไม่มีผู้ใดตอบ เมื่อเราพูด เขาไม่ฟัง แต่เขาได้กระทําชั่วต่อหน้าต่อตาของเรา และเลือกสิ่งที่เราไม่ปีติยินดีด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 5, 'เจ้าผู้ตัวสั่นเพราะพระวจนะของพระองค์ จงฟังพระวจนะของพระเยโฮวาห์ “พี่น้องของเจ้าผู้ซึ่งเกลียดชังเจ้า และเหวี่ยงเจ้าออกไปเพราะเห็นแก่นามของเรา ได้พูดว่า ‘ขอพระเยโฮวาห์ทรงรับเกียรติ’ แต่พระองค์จะได้ปรากฏและเป็นความชื่นบานของเจ้า และเขาเหล่านั้นแหละจะต้องได้รับความอาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 6, 'เสียงอึงคะนึงจากในเมือง เสียงจากพระวิหาร พระสุรเสียงของพระเยโฮวาห์กําลังให้การตอบแทนต่อศัตรูของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 7, 'ก่อนที่นางจะปวดครรภ์ นางก็คลอดบุตร ก่อนที่ความเจ็บปวดจะมาถึงนาง นางก็ให้กําเนิดบุตรชายคนหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 8, 'ใครเคยได้ยินสิ่งอย่างนี้บ้าง ใครเคยได้เห็นสิ่งอย่างนี้บ้าง แผ่นดินจะให้งอกขึ้นในวันเดียวหรือ ประชาชาติจะคลอดมาในครู่เดียวหรือ เพราะพอศิโยนปวดครรภ์ เธอก็คลอดบุตรทั้งหลายของเธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 9, 'เราจะนํามาถึงกําหนดคลอด แล้วจะไม่ให้คลอดหรือ” พระเยโฮวาห์ตรัสดังนี้ “เราผู้เป็นเหตุให้คลอด จะปิดครรภ์หรือ” พระเจ้าของท่านตรัสดังนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 10, 'จงเปรมปรีดิ์กับเยรูซาเล็มและยินดีกับเธอ นะบรรดาเจ้าที่รักเธอ จงเปรมปรีดิ์กับเธอด้วยความชื่นบาน นะบรรดาเจ้าที่ไว้ทุกข์เพื่อเธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 11, 'เพื่อเจ้าจะได้ดูดและอิ่มใจด้วยอกอันประเล้าประโลมของเธอ เพื่อเจ้าจะได้ดื่มให้เกลี้ยง ด้วยความปีติยินดี จากสง่าราศีอันอุดมของเธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 12, 'เพราะพระเยโฮวาห์ตรัสดังนี้ว่า “ดูเถิด เราจะนําสันติภาพมาถึงเธออย่างกับแม่น้ํา และสง่าราศีของบรรดาประชาชาติ เหมือนลําน้ําที่กําลังล้น และเจ้าทั้งหลายจะได้ดูด เธอจะอุ้มเจ้าไว้ที่บั้นเอวของเธอ และเขย่าขึ้นลงที่เข่าของเธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 13, 'ดั่งผู้ที่มารดาของตนเล้าโลม เราจะเล้าโลมเจ้าเช่นนั้น และเจ้าจะรับการเล้าโลมในเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 14, 'เมื่อเจ้าเห็นอย่างนี้ ใจของเจ้าจะเปรมปรีดิ์ กระดูกของเจ้าจะกระชุ่มกระชวยอย่างผักหญ้า และเขาจะรู้กันว่าหัตถ์ของพระเยโฮวาห์อยู่กับผู้รับใช้ของพระองค์ และความพิโรธต่อสู้ศัตรูของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 15, 'เพราะ ดูเถิด พระเยโฮวาห์จะเสด็จมาด้วยไฟ และรถรบของพระองค์เหมือนลมหมุน เพื่อสนองเขาด้วยความกริ้วของพระองค์อย่างเกรี้ยวกราด และด้วยการขนาบของพระองค์พร้อมด้วยเปลวเพลิง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 16, 'เพราะพระเยโฮวาห์จะทรงกระทําการพิพากษาด้วยไฟ และด้วยพระแสงของพระองค์เหนือเนื้อหนังทั้งสิ้น และผู้ที่พระเยโฮวาห์ทรงสังหารเสียจะมีมากมาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 17, 'คนทั้งหลายที่กระทําตัวให้บริสุทธิ์และชําระตัวให้บริสุทธิ์ อยู่ข้างหลังต้นไม้ต้นหนึ่งท่ามกลางสวน ที่กําลังกินเนื้อหมูและสิ่งที่น่าสะอิดสะเอียน และหนู จะถูกเผาผลาญเสียด้วยกัน” พระเยโฮวาห์ตรัสดังนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 18, '“เพราะเราทราบการงานของเขาและความคิดของเขา และเราจะมารวบรวมบรรดาประชาชาติและภาษาทั้งสิ้น และเขาจะมาเห็นสง่าราศีของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 19, 'และเราจะตั้งหมายสําคัญไว้ท่ามกลางเขา และเราจะส่งผู้รอดพ้นจากพวกเขานั้นไปยังบรรดาประชาชาติ ยังทารชิช ปูลและลูด ผู้โก่งธนู ยังทูบัลและยาวาน ยังเกาะทั้งหลายที่ไกลออกไป ที่เขายังไม่ได้ยินชื่อเสียงของเราและเห็นสง่าราศีของเรา และเขาจะประกาศสง่าราศีของเราท่ามกลางบรรดาประชาชาติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 20, 'และเขาจะนําพี่น้องทั้งสิ้นของเจ้าทั้งหลายจากบรรดาประชาชาติทั้งสิ้นเป็นเครื่องถวายบูชาพระเยโฮวาห์ มาด้วยม้า ด้วยรถรบ ด้วยเกวียนประทุน ด้วยล่อและด้วยอูฐโหนกเดียว ยังเยรูซาเล็มภูเขาบริสุทธิ์ของเรา” พระเยโฮวาห์ตรัสดังนี้ “เช่นเดียวกับคนอิสราเอลนําธัญญบูชาใส่ภาชนะสะอาดมายังพระนิเวศของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 21, 'และเราจะเอาเขาบางคนเป็นปุโรหิตและเป็นพวกเลวี” พระเยโฮวาห์ตรัสดังนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 22, '“เพราะฟ้าสวรรค์ใหม่และแผ่นดินโลกใหม่ซึ่งเราจะสร้าง จะยังอยู่ต่อหน้าเราฉันใด” พระเยโฮวาห์ตรัสดังนี้ “เชื้อสายของเจ้าและชื่อของเจ้าจะยังอยู่ฉันนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 23, 'พระเยโฮวาห์ตรัสว่า “และต่อมาทุกวันขึ้นหนึ่งค่ํา และทุกวันสะบาโต เนื้อหนังทั้งสิ้นจะมานมัสการต่อหน้าเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 24, 'และเขาจะออกไปมองดูซากศพของคนที่ได้ละเมิดต่อเรา เพราะว่าหนอนของคนเหล่านี้จะไม่ตายไป ไฟของเขาจะไม่ดับ และเขาจะเป็นที่น่าสะอิดสะเอียนต่อเนื้อหนังทั้งสิ้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 1, 'ถ้อยคําของเยเรมีย์บุตรชายของฮิลคียาห์ ผู้หนึ่งในหมู่ปุโรหิต ผู้อยู่ตําบลอานาโธท ในแผ่นดินของเบนยามิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 2, 'พระวจนะของพระเยโฮวาห์มาถึงเยเรมีย์ในรัชกาลโยสิยาห์ โอรสของอาโมน กษัตริย์แห่งยูดาห์ในปีที่สิบสามของรัชกาลนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 3, 'และมีมาในรัชกาลของเยโฮยาคิม โอรสของโยสิยาห์กษัตริย์แห่งยูดาห์ จนถึงปลายปีที่สิบเอ็ดแห่งรัชกาลเศเดคียาห์ โอรสของโยสิยาห์กษัตริย์แห่งยูดาห์ จนถึงการกวาดเยรูซาเล็มไปเป็นเชลยในเดือนที่ห้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 4, 'แล้วพระวจนะของพระเยโฮวาห์มาถึงข้าพเจ้าว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 5, '“เราได้รู้จักเจ้าก่อนที่เราได้ก่อร่างตัวเจ้าที่ในครรภ์ และก่อนที่เจ้าคลอดจากครรภ์ เราก็ได้กําหนดตัวเจ้าไว้ เราได้แต่งตั้งเจ้าเป็นผู้พยากรณ์ให้แก่บรรดาประชาชาติ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 6, 'แล้วข้าพเจ้าก็กราบทูลว่า “อนิจจา ข้าแต่องค์พระผู้เป็นเจ้าพระเจ้า ดูเถิด ข้าพระองค์พูดไม่เป็น เพราะว่าข้าพระองค์เป็นเด็ก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 7, 'แต่พระเยโฮวาห์ตรัสกับข้าพเจ้าว่า “อย่าว่าเจ้าเป็นแต่เด็ก เพราะเจ้าจะต้องไปหาทุกคนที่เราใช้ให้เจ้าไป และเราบัญชาเจ้าอย่างไรบ้าง เจ้าจะต้องพูด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 8, 'อย่ากลัวหน้าเขาเลย เพราะเราอยู่กับเจ้า จะช่วยเจ้าให้พ้น” พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 9, 'แล้วพระเยโฮวาห์ทรงเหยียดพระหัตถ์ของพระองค์ถูกต้องปากข้าพเจ้า และพระเยโฮวาห์ตรัสกับข้าพเจ้าว่า “ดูเถิด เราเอาถ้อยคําของเราใส่ในปากของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 10, 'ดูซิ ในวันนี้เราได้ตั้งเจ้าไว้เหนือบรรดาประชาชาติและเหนือราชอาณาจักรทั้งหลาย ให้ถอนออกและให้พังลง ให้ทําลายและให้คว่ําเสีย ให้สร้างและให้ปลูก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 11, 'ยิ่งกว่านี้พระวจนะของพระเยโฮวาห์มายังข้าพเจ้าว่า “เยเรมีย์เอ๋ย เจ้าเห็นอะไร” ข้าพเจ้ากราบทูลว่า “ข้าพระองค์เห็นไม้เท้าอัลมันด์อันหนึ่ง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 12, 'แล้วพระเยโฮวาห์ตรัสกับข้าพเจ้าว่า “เจ้าเห็นถูกต้องดีแล้ว เพราะเราจะเร่งเร้าถ้อยคําของเราเพื่อให้กระทําสําเร็จ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 13, 'พระวจนะของพระเยโฮวาห์มายังข้าพเจ้าครั้งที่สองว่า “เจ้าเห็นอะไร” ข้าพเจ้ากราบทูลว่า “ข้าพระองค์เห็นหม้อกําลังเดือดอยู่หม้อหนึ่ง หันหน้าไปทางทิศเหนือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 14, 'แล้วพระเยโฮวาห์ตรัสกับข้าพเจ้าว่า “เหตุร้ายจะระเบิดจากทิศเหนือมาเหนือชาวแผ่นดินนี้ทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 15, 'เพราะ ดูเถิด เราจะร้องเรียกครอบครัวทั้งปวงแห่งบรรดาราชอาณาจักรทิศเหนือ” พระเยโฮวาห์ตรัสดังนี้แหละ “เขาทั้งหลายจะมา และต่างก็จะวางบัลลังก์ของตนไว้ที่ตรงทางเข้าประตูกรุงเยรูซาเล็ม ตั้งสู้ล้อมรอบกําแพงทั้งหลาย และตั้งสู้หัวเมืองทั้งสิ้นของยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 16, 'และเราจะกล่าวคําพิพากษาของเราต่อหัวเมืองเหล่านั้น เพราะบรรดาความชั่วร้ายของเขาในการที่ได้ทอดทิ้งเรา และได้เผาเครื่องหอมบูชาพระอื่น และนมัสการสิ่งที่มือของตนได้กระทําไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 17, 'เพราะฉะนั้นส่วนเจ้าจงคาดเอวของเจ้าไว้ จงลุกขึ้นและบอกทุกอย่างที่เราบัญชาเจ้าไว้นั้นให้เขาฟัง อย่าสะดุ้งกลัวเพราะหน้าเขาเลย เกรงว่าเราจะทําให้เจ้าหงอต่อหน้าเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 18, 'เพราะ ดูเถิด ในวันนี้เรากระทําให้เจ้าเป็นเมืองมีป้อม เป็นเสาเหล็ก และเป็นกําแพงทองเหลือง สู้กับแผ่นดินทั้งหมด สู้กับบรรดากษัตริย์แห่งยูดาห์ กับเจ้านาย กับปุโรหิตและกับประชาชนแห่งแผ่นดินนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 19, 'เขาทั้งหลายจะต่อสู้กับเจ้า แต่จะไม่ชนะเจ้า เพราะเราอยู่กับเจ้าเพื่อจะช่วยเจ้าให้พ้น” พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 1, 'ยิ่งกว่านี้พระวจนะของพระเยโฮวาห์มายังข้าพเจ้าว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 2, '“จงไปประกาศกรอกหูของกรุงเยรูซาเล็มว่า พระเยโฮวาห์ตรัสดังนี้ว่า เรายังจําเจ้าได้ คือความเมตตาในวัยสาวของเจ้า ความรักขณะที่เจ้าเข้าพิธีสมรส เมื่อเจ้าตามเรามาในถิ่นทุรกันดาร ในดินแดนที่ไม่ได้หว่านพืชอะไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 3, 'อิสราเอลนั้นเป็นส่วนบริสุทธิ์ของพระเยโฮวาห์ คือเป็นผลิตผลรุ่นแรกของพระองค์ คนทั้งปวงที่ได้กินผลนั้นก็ผิด เหตุร้ายจึงจะมาถึงเขา พระเยโฮวาห์ตรัสดังนี้แหละ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 4, 'โอ วงศ์วานของยาโคบ และบรรดาครอบครัวแห่งวงศ์วานอิสราเอลเอ๋ย จงฟังพระวจนะของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 5, 'พระเยโฮวาห์ตรัสดังนี้ว่า “บรรพบุรุษของเจ้าจับความชั่วช้าอะไรได้ในเราเล่า เขาจึงไปห่างเสียจากเรา และไปดําเนินตามสิ่งไร้ค่า และได้กลายเป็นสิ่งไร้ค่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 6, 'เขาทั้งหลายมิได้กล่าวว่า ‘พระเยโฮวาห์ประทับที่ไหน ผู้ได้พาเราขึ้นมาจากแผ่นดินอียิปต์ ผู้ได้นําเราอยู่ในป่าถิ่นทุรกันดาร ในแดนทะเลทรายมีหลุม ในแดนที่กันดารน้ําและมีเงามัจจุราช ในแผ่นดินที่ไม่มีผู้ใดผ่านไปได้ และไม่มีมนุษย์อาศัยอยู่ที่นั่น’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 7, 'และเราได้พาเจ้าทั้งหลายเข้ามาในดินแดนที่อุดมสมบูรณ์ เพื่อกินผลไม้และของดีๆในแผ่นดินนั้น แต่เมื่อเจ้าเข้ามา เจ้าได้กระทําให้แผ่นดินของเราเป็นมลทิน และกระทําให้มรดกของเราเป็นสิ่งน่าสะอิดสะเอียน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 8, 'ปุโรหิตทั้งหลายมิได้กล่าวว่า ‘พระเยโฮวาห์ประทับที่ไหน’ คนเหล่านั้นที่แถลงพระราชบัญญัติไม่รู้จักเรา บรรดาผู้เลี้ยงแกะก็ละเมิดต่อเรา พวกผู้พยากรณ์ได้พยากรณ์โดยพระบาอัล และดําเนินติดตามสิ่งที่ไม่เป็นประโยชน์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 9, 'พระเยโฮวาห์ตรัสว่า “เพราะฉะนั้นเราจะยังโต้แย้งกับเจ้า เราจะโต้แย้งกับลูกหลานของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 10, 'เหตุว่า จงข้ามไปยังฝั่งเกาะคิทธิม แล้วก็ดู และใช้คนไปถึงเมืองเคดาร์และพิจารณาอย่างถี่ถ้วน ดูทีว่าเคยมีสิ่งอย่างนี้บ้างไหม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 11, 'มีประชาชาติใดเคยได้เปลี่ยนพระของตน ถึงแม้ว่าพระเหล่านั้นไม่เป็นพระ แต่ประชาชนของเราได้เอาสง่าราศีของเขาแลกกับสิ่งที่ไม่เป็นประโยชน์อย่างใด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 12, 'พระเยโฮวาห์ตรัสว่า “โอ ฟ้าสวรรค์ทั้งหลายเอ๋ย จงตกตะลึงด้วยสิ่งนี้ จงเกรงกลัวอย่างสยดสยองและจงโดดเดี่ยวอ้างว้างเสียเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 13, 'เพราะว่าประชาชนของเราได้กระทําความชั่วถึงสองประการ เขาได้ทอดทิ้งเราเสียซึ่งเป็นแหล่งน้ําแห่งชีวิต แล้วสกัดหินขังน้ําไว้สําหรับตนเอง เป็นถังน้ําแตก ซึ่งขังน้ําไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 14, 'อิสราเอลเป็นทาสเขาหรือ หรือเป็นทาสที่เกิดมาในบ้าน เหตุใดเขาจึงตกไปเป็นเหยื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 15, 'สิงโตหนุ่มคํารามเข้าใส่เขา มันคํารามเสียงดังมาก และมันทั้งหลายได้กระทําให้แผ่นดินของเขาทิ้งร้างว่างเปล่า หัวเมืองทั้งหลายของเขาก็ถูกเผา ไม่มีคนอาศัยอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 16, 'ยิ่งกว่านั้นอีก ประชาชนเมืองโนฟและเมืองทาปานเหสได้ทุบกระหม่อมของเจ้าแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 17, 'เจ้าหาเรื่องเหล่านี้ให้มาใส่ตัวเจ้าเอง โดยการทอดทิ้งพระเยโฮวาห์พระเจ้าของเจ้า เมื่อพระองค์ทรงนําเจ้าไปตามทางมิใช่หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 18, 'บัดนี้เจ้าได้อะไรด้วยการลงไปยังอียิปต์ เพื่อดื่มน้ําในแม่น้ําชิโหร์ หรือเจ้าได้อะไรด้วยการที่ลงไปยังอัสซีเรีย เพื่อดื่มน้ําในแม่น้ํานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 19, 'ความโหดร้ายของเจ้าจะตีสอนเจ้าเอง และการที่เจ้ากลับสัตย์นั้นเองจะตําหนิเจ้า ฉะนั้นเจ้าจงรู้และเห็นเถิดว่า มันเป็นความชั่วและความขมขื่น ซึ่งเจ้าทอดทิ้งพระเยโฮวาห์พระเจ้าของเจ้า ซึ่งความยําเกรงเรามิได้อยู่ในตัวเจ้าเลย” องค์พระผู้เป็นเจ้าพระเจ้าจอมโยธาตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 20, '“เพราะว่านานมาแล้วเราได้หักแอกของเจ้า และระเบิดพันธนะของเจ้าเสีย และเจ้าได้กล่าวว่า ‘ข้าจะไม่ละเมิด’ เออ เจ้าได้โน้มตัวลงเล่นชู้บนเนินเขาสูงทุกแห่งและใต้ต้นไม้เขียวสดทุกต้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 21, 'แต่เราได้ปลูกเจ้าไว้เป็นเถาองุ่นอย่างดี เป็นพันธุ์แท้ทั้งนั้น แล้วทําไมเจ้าเสื่อมทรามลงจนกลายเป็นเถาแปลกไปได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 22, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสว่า “ถึงแม้ว่าเจ้าชําระตัวด้วยน้ําด่าง และใช้สบู่มาก แต่รอยเปื้อนความชั่วช้าของเจ้าก็ยังปรากฏอยู่ต่อหน้าเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 23, 'เจ้าจะพูดได้อย่างไรว่า ‘ข้าไม่เป็นมลทิน ข้ามิได้ติดตามพระบาอัลไป’ จงมองดูท่าทางของเจ้าที่ในหุบเขาซิ จงสํานึกซิว่าเจ้าได้กระทําอะไร เจ้าเหมือนอูฐสาวคะนองที่เดินข้ามไปข้ามมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 24, 'เหมือนลาป่าที่คุ้นเคยกับถิ่นทุรกันดาร ได้สูดลมด้วยความอยากอันรุนแรงของมัน ใครจะระงับความใคร่ของมันได้ บรรดาที่แสวงหามันจะไม่ต้องเหน็ดเหนื่อย เมื่อถึงเดือนที่กําหนดของมันจะพบมันเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 25, 'ระวังอย่าให้เท้าของเจ้าขาดรองเท้า และระวังลําคอของเจ้าให้พ้นจากความกระหาย แต่เจ้ากล่าวว่า ‘หมดหวังเสียแล้ว เพราะข้าได้รักพระอื่น และข้าจะติดตามไป’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 26, 'เมื่อโจรถูกจับมีความละอายฉันใด วงศ์วานของอิสราเอลก็จะละอายฉันนั้น ทั้งตัวเขา กษัตริย์ เจ้านาย ปุโรหิตและผู้พยากรณ์ทั้งหลายของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 27, 'ผู้กล่าวแก่เสาไม้ว่า ‘ท่านเป็นบิดาของข้าพเจ้า’ และกล่าวแก่หินว่า ‘ท่านคลอดข้าพเจ้ามา’ เพราะเขาทั้งหลายได้หันหลังให้แก่เรา มิใช่หันหน้ามาให้ แต่เมื่อถึงเวลาลําบากเขาจะกล่าวว่า ‘ขอทรงลุกขึ้นช่วยข้าพระองค์ทั้งหลายให้รอด’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 28, 'แต่บรรดาพระของเจ้าอยู่ที่ไหนเล่า ซึ่งเป็นพระที่เจ้าสร้างไว้สําหรับตัวเอง ถ้ามันช่วยเจ้าให้รอดได้ ก็ให้มันลุกขึ้นช่วย เมื่อถึงเวลาลําบากของเจ้า โอ ยูดาห์เอ๋ย เจ้ามีหัวเมืองมากเท่าใด เจ้าก็มีพระมากเท่านั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 29, 'พระเยโฮวาห์ตรัสว่า “เจ้าทั้งหลายจะมาร้องทุกข์ต่อเราทําไม เจ้าได้ละเมิดต่อเราหมดทุกคนแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 30, 'เราได้โบยตีลูกหลานของเจ้าเสียเปล่า เขาทั้งหลายก็ไม่ดีขึ้น ดาบของเจ้าเองได้กลืนผู้พยากรณ์ของเจ้า เหมือนอย่างสิงโตที่ทําลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 31, 'โอ คนยุคนี้เอ๋ย เจ้าทั้งหลายจงพิจารณาดูพระวจนะของพระเยโฮวาห์ เราเป็นเหมือนถิ่นทุรกันดารแก่อิสราเอลหรือ หรือเหมือนแผ่นดินที่มืดทึบหรือ ทําไมประชาชนของเราจึงกล่าวว่า ‘ข้าพระองค์ทั้งหลายเป็นเจ้านาย ข้าพระองค์จะไม่มาหาพระองค์อีก’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 32, 'สาวพรหมจารีจะลืมอาภรณ์ของเธอได้หรือ เจ้าสาวจะลืมเครื่องพันกายของตนได้หรือ แต่ประชาชนของเราได้ลืมเรา เป็นเวลากี่วันก็นับไม่ไหวแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 33, 'ทําไมเจ้านําวิถีของเจ้าไปหาความรักอย่างแนบเนียน ฉะนั้นเจ้าจึงสอนทางของเจ้าให้คนชั่วด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 34, 'ที่ชายเสื้อของเจ้าจะเห็นโลหิตของคนจนที่ไร้ความผิดด้วย เรามิได้พบโดยการสืบหาอย่างลึกลับ แต่โดยเรื่องต่างๆเหล่านี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 35, 'เจ้าก็ยังกล่าวว่า ‘เพราะข้าพเจ้าไม่มีความผิดเลย พระพิโรธของพระองค์จะหันกลับจากข้าพเจ้าเป็นแน่’ ดูเถิด เราจะนําเจ้าไปสู่การพิพากษา เพราะเจ้าได้กล่าวว่า ‘ข้าพเจ้ามิได้กระทําบาป’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 36, 'ทําไมเจ้าท่องเที่ยวไปๆมาๆอย่างไร้เป้าหมายเช่นนั้น โดยเปลี่ยนเส้นทางของเจ้าอยู่เสมอนะ อียิปต์จะกระทําให้เจ้าได้อาย เหมือนอัสซีเรียได้กระทําให้เจ้าได้อายมาแล้วนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 37, 'เจ้าจะออกมาจากที่นั่นด้วย โดยเอามือกุมศีรษะของเจ้าไว้ เพราะพระเยโฮวาห์ทรงทอดทิ้งบรรดาความไว้วางใจของเจ้าเสีย เจ้าจะเจริญขึ้นมาเพราะเขาก็ไม่ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 1, '“เขาทั้งหลายว่า ‘ถ้าชายคนใดหย่าภรรยาของตนและเธอก็ไปจากเขาเสีย และไปเป็นภรรยาของชายอีกคนหนึ่ง เขาจะกลับไปหาเธอหรือ แผ่นดินนั้นจะไม่โสโครกมากมายหรือ’ แต่เจ้าได้เล่นชู้กับคนรักมากมายแล้ว ถึงกระนั้นเจ้าจงกลับมาหาเรา” พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 2, '“จงแหงนหน้าขึ้นสู่บรรดาที่สูงนั้น และดูซี ที่ไหนบ้างที่ไม่มีคนมานอนด้วย เจ้าได้นั่งคอยคนรักของเจ้าอยู่ที่ริมทาง อย่างคนอาระเบียในถิ่นทุรกันดาร เจ้าได้กระทําให้แผ่นดินโสโครกด้วยการแพศยาและความชั่วช้าของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 3, 'เพราะฉะนั้นฝนจึงได้ระงับเสีย และฝนชุกปลายฤดูจึงขาดไป แต่เจ้ามีหน้าผากของหญิงแพศยา เจ้าปฏิเสธไม่ยอมอาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 4, 'ตั้งแต่เวลานี้เจ้าจะร้องเรียกเรามิใช่หรือว่า ‘พระบิดาของข้าพระองค์ พระองค์ทรงเป็นผู้ชี้นําตั้งแต่ข้าพระองค์ยังสาวๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 5, 'พระองค์จะทรงพระพิโรธอยู่เป็นนิตย์หรือ พระองค์จะทรงกริ้วอยู่จนถึงที่สุดปลายหรือ’ ดูเถิด เจ้าลั่นวาจาแล้ว แต่เจ้าก็ยังกระทําความชั่วช้าทุกอย่างซึ่งเจ้ากระทําได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 6, 'พระเยโฮวาห์ตรัสกับข้าพเจ้าในรัชกาลของกษัตริย์โยสิยาห์ว่า “เธอทําอะไรเจ้าเห็นหรือ คืออิสราเอลผู้กลับสัตย์ เธอขึ้นไปบนภูเขาสูงทุกลูก และใต้ต้นไม้เขียวสดทุกต้น แล้วก็ไปเล่นชู้อยู่ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 7, 'เมื่อเธอทําอย่างนี้จนหมดแล้วเรากล่าวว่า ‘เจ้าจงกลับมาหาเรา’ แต่เธอก็ไม่กลับมา และยูดาห์น้องสาวที่ทรยศนั้นก็เห็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 8, 'และเราเห็นว่า เพราะเหตุทั้งปวงที่อิสราเอลผู้กลับสัตย์ได้ล่วงประเวณีนั้น เราได้ไล่เธอไปพร้อมกับให้หนังสือหย่า แต่ยูดาห์น้องสาวที่ทรยศนั้นก็ไม่กลัว เธอก็กลับไปเล่นชู้ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 9, 'ต่อมาเพราะการแพศยาเป็นการเบาแก่เธอมาก เธอก็กระทําให้แผ่นดินโสโครกไป โดยไปล่วงประเวณีกับหินและเสาไม้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 10, 'แม้ว่าเธอกระทําไปสิ้นอย่างนี้แล้ว ยูดาห์น้องสาวที่ทรยศของเธอก็มิได้หันกลับมาหาเราด้วยสิ้นสุดใจ แต่แสร้งทําเป็นกลับมา” พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 11, 'แล้วพระเยโฮวาห์ตรัสกับข้าพเจ้าว่า “อิสราเอลผู้กลับสัตย์ยังสําแดงตัวว่ามีผิดน้อยกว่ายูดาห์ที่ทรยศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 12, 'จงไปประกาศถ้อยคําเหล่านี้ไปทางเหนือกล่าวว่า ‘พระเยโฮวาห์ตรัสว่า อิสราเอลผู้กลับสัตย์เอ๋ย กลับมาเถิด เราจะไม่ให้ความกริ้วของเราสวมทับเจ้า เพราะเราประกอบด้วยพระกรุณาคุณ พระเยโฮวาห์ตรัสดังนี้แหละ เราจะไม่กริ้วเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 13, 'เพียงแต่ยอมรับความชั่วช้าของเจ้าว่า เจ้าได้ละเมิดต่อพระเยโฮวาห์พระเจ้าของเจ้า และเที่ยวเอาใจพระอื่นที่ใต้ต้นไม้เขียวสดทุกต้น และเจ้ามิได้เชื่อฟังเสียงของเรา’” พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 14, 'พระเยโฮวาห์ตรัสว่า “โอ ลูกหลานที่กลับสัตย์เอ๋ย กลับมาเถิด เพราะเราแต่งงานกับเจ้าแล้ว เราจะรับเจ้าจากเมืองละคนและจากครอบครัวละสองคน และเราจะนําเจ้ามาถึงศิโยน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 15, 'และเราจะให้ผู้เลี้ยงแกะคนที่พอใจเราแก่เจ้า ผู้ซึ่งจะเลี้ยงเจ้าด้วยความรู้และความเข้าใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 16, 'และต่อมาเมื่อเจ้าทวีและเพิ่มขึ้นในแผ่นดินนั้น ในครั้งนั้น” พระเยโฮวาห์ตรัสว่า “เขาทั้งหลายจะไม่กล่าวอีกว่า ‘หีบพันธสัญญาแห่งพระเยโฮวาห์’ เรื่องนี้จะไม่มีขึ้นในใจ ไม่มีใครระลึกถึง ไม่มีใครนึกถึง จะไม่ทํากันขึ้นอีกเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 17, 'ในครั้งนั้นเขาจะเรียกกรุงเยรูซาเล็มว่า เป็นพระที่นั่งของพระเยโฮวาห์ และบรรดาประชาชาติจะรวบรวมกันเข้ามาหายังพระนามของพระเยโฮวาห์ในกรุงเยรูซาเล็ม และเขาจะไม่ติดตามใจอันชั่วของเขาอย่างดื้อกระด้างอีกต่อไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 18, 'ในสมัยนั้นวงศ์วานของยูดาห์จะเดินมากับวงศ์วานของอิสราเอล เขาทั้งสองจะรวมกันมาจากแผ่นดินฝ่ายเหนือ มายังแผ่นดินซึ่งเรามอบให้แก่บรรพบุรุษของเจ้าให้เป็นมรดก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 19, 'แต่เรากล่าวว่า ‘เราจะตั้งเจ้าไว้ท่ามกลางบุตรทั้งหลายของเราอย่างไรดีหนอ และให้แผ่นดินที่น่าปรารถนาแก่เจ้า เป็นมรดกที่สวยงามที่สุดในบรรดาประชาชาติ’ และเรากล่าวว่า ‘เจ้าจะเรียกเราว่า พระบิดาของข้าพระองค์ และจะไม่หันกลับจากการติดตามเรา’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 20, 'พระเยโฮวาห์ตรัสว่า “โอ วงศ์วานอิสราเอลเอ๋ย แน่นอนทีเดียวที่ภรรยาทรยศละทิ้งสามีของนางฉันใด เจ้าก็ได้ทรยศต่อเราฉันนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 21, 'เขาได้ยินเสียงมาจากที่สูง เป็นเสียงร้องไห้และเสียงวิงวอนของบุตรทั้งหลายของอิสราเอล เพราะเขาได้เปลี่ยนวิถีของเขาเสียแล้ว เขาได้ลืมพระเยโฮวาห์พระเจ้าของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 22, '“บรรดาบุตรที่กลับสัตย์เอ๋ย จงกลับมาเถิด เราจะรักษาความกลับสัตย์ของเจ้าให้หาย” “ดูเถิด ข้าพระองค์ทั้งหลายมาหาพระองค์แล้ว เพราะพระองค์ทรงเป็นพระเยโฮวาห์พระเจ้าของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 23, 'แท้จริงความหวังว่าจะได้ความรอดจากเนินเขาและจากภูเขาหลายลูกก็เป็นความไร้สาระ แท้จริงความรอดของอิสราเอลนั้นอยู่ในพระเยโฮวาห์พระเจ้าของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 24, 'แต่ว่าสิ่งที่น่าอายนั้นได้กัดกินสิ่งทั้งปวงที่บรรพบุรุษของเราได้ลงแรงทําไว้ ตั้งแต่เรายังเป็นเด็กอนุชนอยู่ คือฝูงแกะ ฝูงวัว บุตรชาย และบุตรสาวทั้งหลายของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 25, 'ให้เรานอนจมลงในความอายของเรา และให้ความอัปยศคลุมเราไว้ เพราะเราได้กระทําบาปต่อพระเยโฮวาห์พระเจ้าของเรา ทั้งตัวเราและบรรพบุรุษของเรา ตั้งแต่เราเป็นอนุชนอยู่จนทุกวันนี้ และเราหาได้เชื่อฟังพระสุรเสียงแห่งพระเยโฮวาห์พระเจ้าของเราไม่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 1, 'พระเยโฮวาห์ตรัสว่า “โอ อิสราเอลเอ๋ย ถ้าเจ้าจะกลับมา เจ้าจงกลับมาหาเรา ถ้าเจ้ายอมเอาสิ่งที่น่าสะอิดสะเอียนไปให้พ้นสายตาของเราเสีย เจ้าก็จะไม่โลเล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 2, 'และถ้าเจ้าปฏิญาณอย่างสัจจริง อย่างยุติธรรม และอย่างชอบธรรมว่า ‘ตราบใดที่พระเยโฮวาห์ทรงพระชนม์อยู่แน่’ แล้วบรรดาประชาชาติจะให้พรกันในพระนามพระองค์ และเขาทั้งหลายจะอวดพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 3, 'เพราะว่า พระเยโฮวาห์ตรัสกับคนยูดาห์และแก่ชาวเยรูซาเล็มว่า “จงทุบดินที่ไถไว้แล้วนั้น และอย่าหว่านลงกลางหนาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 4, 'ดูก่อน คนยูดาห์และชาวกรุงเยรูซาเล็มเอ๋ย จงเอาตัวเข้าสุหนัตถวายแด่พระเยโฮวาห์ จงตัดหนังปลายหัวใจของเจ้าเสีย เกรงว่าความกริ้วของเราจะพลุ่งออกไปอย่างไฟและเผาไหม้ ไม่มีใครจะดับได้ เหตุด้วยความชั่วแห่งการกระทําทั้งหลายของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 5, 'จงประกาศในยูดาห์และโฆษณาในกรุงเยรูซาเล็ม ว่า ‘จงเป่าแตรไปทั่วแผ่นดิน จงรวมกัน จงร้องประกาศดังๆว่า มารวมกันเถิด ให้เราเข้าไปในบรรดาเมืองที่มีป้อม’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 6, 'จงยกธงขึ้นสู่ศิโยน จงรีบหนีไปให้ปลอดภัย อย่ารออยู่ เพราะเราจะนําความร้ายมาจากทิศเหนือ และนําการทําลายใหญ่ยิ่งมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 7, 'สิงโตตัวนั้นได้ออกไปจากพุ่มไม้หนาทึบของมันแล้ว และผู้ทําลายเหล่าประชาชาติกําลังเดินทางมาแล้ว เขาได้ออกไปจากสถานที่ของเขาเพื่อกระทําให้แผ่นดินของเจ้ารกร้างไป หัวเมืองของเจ้าจะถูกทิ้งไว้เสียเปล่าๆปราศจากคนอาศัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 8, 'ด้วยเหตุนี้ เจ้าจงสวมผ้ากระสอบ จงคร่ําครวญและร้องไห้ เพราะพระพิโรธอันร้อนแรงของพระเยโฮวาห์มิได้หันกลับไปจากเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 9, 'พระเยโฮวาห์ตรัสว่า “ต่อมาในวันนั้นทั้งกษัตริย์และพวกเจ้านายจะหมดกําลังใจ บรรดาปุโรหิตจะตกตะลึงและผู้พยากรณ์ก็จะอัศจรรย์ใจ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 10, 'แล้วข้าพเจ้าจึงทูลว่า “ข้าแต่องค์พระผู้เป็นเจ้าพระเจ้า พระองค์ทรงล่อลวงชนชาตินี้ และกรุงเยรูซาเล็มแน่นอนทีเดียวว่า ‘เจ้าทั้งหลายจะอยู่เย็นเป็นสุข’ แต่ที่จริงดาบได้มาถึงชีวิตของเขาทั้งหลาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 11, '“ในครั้งนั้น เขาจะกล่าวแก่ชนชาตินี้ และแก่กรุงเยรูซาเล็มว่า ‘ลมร้อนจากที่สูงในถิ่นทุรกันดารพัดมาสู่บุตรสาวแห่งประชาชนของเรา ไม่ใช่จะมาฝัดหรือมาชําระ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 12, 'กระแสลมที่แรงจะพัดมาจากที่เหล่านั้นมาสู่เรา บัดนี้เราจะกล่าวคําตัดสินต่อพวกเขา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 13, 'ดูเถิด เขาจะขึ้นมาเหมือนเมฆ รถรบของเขาจะเหมือนลมหมุน ม้าทั้งหลายของเขาเร็วยิ่งกว่านกอินทรี วิบัติแก่เราทั้งหลาย เพราะว่าเราจะต้องพินาศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 14, 'โอ กรุงเยรูซาเล็มเอ๋ย จงล้างจิตใจของเจ้าให้พ้นจากความชั่วร้าย เพื่อเจ้าจะรอดได้ ความคิดชั่วร้ายของเจ้านั้นจะสิงอยู่ในใจของเจ้านานสักเท่าใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 15, 'เพราะว่ามีเสียงประกาศมาจากเมืองดาน และโฆษณาความชั่วร้ายจากภูเขาเอฟราอิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 16, 'จงกล่าวแก่บรรดาประชาชาติ ดูเถิด จงโฆษณาแก่กรุงเยรูซาเล็มว่า บรรดาผู้ล้อมมาจากแผ่นดินไกล เขาทั้งหลายโห่ร้องเข้าใส่หัวเมืองยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 17, 'เขาทั้งหลายล้อมยูดาห์ไว้รอบเหมือนผู้ดูแลเฝ้านา เพราะว่ายูดาห์ได้กบฏต่อเรา” พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 18, '“วิถีและการกระทําทั้งหลายของเจ้าได้นําเรื่องนี้มาเหนือเจ้า นี่แหละเป็นผลแห่งความชั่วร้ายของเจ้า เพราะมันขมขื่น เพราะมันมาถึงจิตใจของเจ้าทีเดียว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 19, 'แสนระทม แสนระทม ข้าก็บิดตัวด้วยความเจ็บปวด โอ ผนังดวงใจของข้าเอ๋ย จิตใจของข้าก็ว้าวุ่น ข้าจะนิ่งอยู่ไม่ได้ เพราะจิตใจข้าได้ยินเสียงแตร เสียงปลุกของสงคราม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 20, 'การประกาศเรื่องความหายนะไล่ติดตามความหายนะ แผ่นดินทั้งสิ้นก็ถูกทิ้งร้าง บรรดาเต็นท์ของข้าก็ถูกทําลายในฉับพลัน ม่านทั้งหลายของข้าก็สิ้นไปในบัดเดี๋ยวเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 21, 'ข้าจะต้องมองดูธงและฟังเสียงแตรนานสักเท่าใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 22, '“เพราะประชาชนของเราโง่เขลา เขาทั้งหลายไม่รู้จักเรา เขาทั้งหลายเป็นลูกหลานที่โง่ทึบ เขาทั้งหลายไม่มีความเข้าใจ เขาทั้งหลายทําความชั่วเก่ง แต่เขาไม่เข้าใจที่จะทําดี”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 23, 'ข้าพเจ้ามองดูพื้นที่โลก และดูเถิด เป็นที่ร้างและว่างเปล่า และมองดูฟ้าสวรรค์ ในนั้นก็ไม่มีความสว่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 24, 'ข้าพเจ้ามองดูภูเขา ดูเถิด มันกําลังสั่นอยู่ บรรดาเนินเขาก็แกว่งไปแกว่งมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 25, 'ข้าพเจ้ามองดู และดูเถิด ไม่มีมนุษย์เลย นกทั้งปวงแห่งท้องอากาศได้หนีไปแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 26, 'ข้าพเจ้ามองดู และดูเถิด เรือกสวนไร่นาก็เป็นถิ่นทุรกันดาร และหัวเมืองทั้งสิ้นก็ปรักหักพังไปต่อพระพักตร์พระเยโฮวาห์ ต่อพระพิโรธอันร้อนแรงของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 27, 'เพราะพระเยโฮวาห์ตรัสดังนี้ว่า “แผ่นดินทั้งหมดจะเป็นที่รกร้าง ถึงกระนั้นเราก็ยังมิได้กระทําให้ถึงอวสานเสียทีเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 28, 'เพราะเรื่องนี้โลกจะไว้ทุกข์ และฟ้าสวรรค์เบื้องบนจะดํามืด เพราะเราได้ลั่นวาจาแล้ว เราได้หมายใจไว้แล้ว เราจะไม่เปลี่ยนใจหรือหันกลับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 29, 'เมื่อได้ยินเสียงพลม้าและนักธนู ชาวเมืองทั้งหมดก็จะหนีไป เขาเข้าไปอยู่ในสุมทุมพุ่มไม้ และปีนป่ายไปท่ามกลางศิลา หัวเมืองทุกแห่งก็ถูกทอดทิ้ง และไม่มีมนุษย์อาศัยอยู่ในเมืองเหล่านั้นเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 30, 'เจ้าผู้ที่ถูกทิ้งร้างเอ๋ย ที่เจ้าแต่งตัวสีแดงนั้นเจ้าทําอะไรกัน และที่เจ้าประดับตัวด้วยอาภรณ์ทองคํา ที่เจ้าขยายดวงตาให้กว้างด้วยแต้มสี เออ เจ้าแต่งตัวให้งามเสียเปล่า คนรักของเจ้าจะดูหมิ่นเจ้า เขาทั้งหลายจะแสวงหาชีวิตของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 31, 'เพราะเราได้ยินเสียงเหมือนเสียงหญิงคลอดบุตรร้องแสนเจ็บปวดอย่างกับจะคลอดบุตรหัวปี เสียงร้องแห่งบุตรสาวศิโยนนั้น แทบจะขาดใจ เหยียดมือของเธอออกร้องว่า ‘วิบัติแก่ข้าในบัดนี้ จิตใจข้าอ่อนเปลี้ยอยู่เพราะเหตุพวกฆาตกร’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 1, '“จงวิ่งไปวิ่งมาอยู่ในถนนกรุงเยรูซาเล็ม บัดนี้จงมองและรับรู้ จงค้นตามลานเมืองดูทีว่า จะหามนุษย์สักคนหนึ่งได้หรือไม่ คือคนที่กระทําการยุติธรรมและแสวงหาความจริง เพื่อเราจะได้อภัยโทษให้แก่เมืองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 2, 'แม้เขาทั้งหลายกล่าวว่า ‘ตราบใดที่พระเยโฮวาห์ทรงพระชนม์อยู่’ เขาก็ยังปฏิญาณเท็จอย่างแน่นอน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 3, 'โอ ข้าแต่พระเยโฮวาห์ พระเนตรของพระองค์ทรงหาความจริงมิใช่หรือ พระองค์ทรงเฆี่ยนตีเขาทั้งหลาย แต่เขาก็ไม่รู้สึกสํานึก พระองค์ทรงล้างผลาญเขา แต่เขาทั้งหลายปฏิเสธไม่ยอมดีขึ้น เขาได้กระทําให้หน้าของเขากระด้างยิ่งกว่าหิน เขาปฏิเสธไม่ยอมกลับใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 4, 'แล้วข้าพเจ้าจึงทูลว่า “แน่นอนคนเหล่านี้เป็นแต่คนต้อยต่ํา เขาเหล่านี้โง่เขลา เพราะเขาไม่รู้จักพระมรรคาของพระเยโฮวาห์ ไม่รู้จักคําตัดสินของพระเจ้าของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 5, 'ข้าพระองค์จะไปหาพวกผู้มีตําแหน่งสูง และจะพูดกับเขาทั้งหลาย เพราะเขารู้จักพระมรรคาของพระเยโฮวาห์ และรู้จักคําตัดสินของพระเจ้าของเขา” แต่เขาทั้งหลายทุกคนก็ได้หักแอกเสีย เขาทั้งหลายได้ระเบิดพันธนะเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 6, 'เพราะฉะนั้น สิงโตจากป่าจะมาสังหารเขา สุนัขป่ายามสนธยาจะทําลายเขา เสือดาวจะเฝ้าหัวเมืองทั้งหลายของเขา ทุกคนที่ไปจากเมืองเหล่านั้นจะถูกฉีกเป็นชิ้นๆ เพราะว่าความละเมิดของเขามากมาย การกลับสัตย์ของเขาก็ใหญ่ยิ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 7, '“เราจะให้อภัยเจ้าได้อย่างไร ลูกหลานของเจ้าได้ละทิ้งเราแล้ว และได้อ้างผู้ที่ไม่ใช่พระในการทําสัตย์ปฏิญาณ เมื่อเราเลี้ยงเขาให้อิ่ม เขาก็ทําการล่วงประเวณี แล้วก็ยกขบวนกันไปที่เรือนของหญิงแพศยา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 8, 'เขาทั้งหลายเหมือนม้าที่กินอิ่มในตอนเช้า ทุกคนก็ร้องหาภรรยาของเพื่อนบ้าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 9, 'พระเยโฮวาห์ตรัสว่า “เพราะสิ่งอย่างนี้เราจะไม่ทําโทษเขาหรือ และจิตใจเราไม่ควรที่จะแก้แค้นประชาชาติที่เป็นอย่างนี้หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 10, 'ขึ้นไปตามกําแพงของมันและทําลายเสีย แต่อย่าให้ถึงอวสานทีเดียว เอาเชิงเทินของมันออก เพราะนั่นไม่ใช่เป็นของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 11, 'เพราะวงศ์วานของอิสราเอลและวงศ์วานของยูดาห์ได้ทรยศต่อเราอย่างสิ้นเชิงแล้ว” พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 12, 'เขาทั้งหลายพูดมุสาในเรื่องพระเยโฮวาห์ และได้กล่าวว่า “พระองค์มิได้ทรงกระทําประการใด ไม่มีการร้ายอันใดจะเกิดขึ้นแก่เรา เราก็จะไม่เห็นดาบหรือการกันดารอาหาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 13, 'ผู้พยากรณ์ก็จะเป็นแต่ลมๆ พระวจนะไม่มีในคนเหล่านั้น ขอให้เป็นอย่างนั้นแก่เขาเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 14, 'เพราะฉะนั้น พระเยโฮวาห์พระเจ้าจอมโยธาจึงตรัสดังนี้ว่า “เพราะเจ้าทั้งหลายกล่าวถ้อยคําเหล่านี้ ดูเถิด เราจะทําถ้อยคําของเราที่อยู่ในปากของเจ้าให้เป็นไฟ และชนชาตินี้เป็นฟืน และไฟนั้นจะเผาผลาญเขาเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 15, 'ดูเถิด โอ วงศ์วานของอิสราเอลเอ๋ย เราจะนําประชาชาติจากแดนไกลมาสู้เจ้าทั้งหลาย” พระเยโฮวาห์ตรัสดังนี้แหละ “เป็นประชาชาติที่มีอํานาจใหญ่โต เป็นประชาชาติดึกดําบรรพ์ เป็นประชาชาติที่เจ้าไม่รู้ภาษาของเขา เขาจะพูดอะไรเจ้าก็ไม่เข้าใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 16, 'แล่งธนูของเขาเหมือนอุโมงค์เปิด เขาเป็นทแกล้วทหารทุกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 17, 'เขาจะกินซึ่งเจ้าเกี่ยวได้ และกินอาหารของเจ้าเสีย ซึ่งบุตรชายและบุตรสาวของเจ้าควรจะได้กิน เขาจะกินฝูงแกะฝูงวัวของเจ้าเสีย เขาจะกินเถาองุ่นและต้นมะเดื่อของเจ้าเสีย เขาจะทําลายตัวเมืองที่มีป้อมของเจ้า ซึ่งเจ้าวางใจนั้นเสียด้วยดาบ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 18, 'พระเยโฮวาห์ตรัสว่า “ถึงแม้ว่าในวันเหล่านั้น เราก็ยังไม่กระทําแก่เจ้าให้ถึงอวสาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 19, 'และต่อมาเมื่อเจ้าทั้งหลายจะกล่าวว่า ‘ทําไมพระเยโฮวาห์พระเจ้าของเราทั้งหลายจึงกระทําบรรดาสิ่งเหล่านี้แก่เรา’ เจ้าจะกล่าวแก่เขาว่า ‘เจ้าได้ละทิ้งเราไปปรนนิบัติพระต่างด้าวในแผ่นดินของเจ้าฉันใด เจ้าจะต้องไปปรนนิบัติคนต่างชาติในแผ่นดินซึ่งไม่ใช่ของเจ้าฉันนั้น’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 20, 'จงประกาศข้อความต่อไปนี้ในวงศ์วานของยาโคบ และจงโฆษณาเรื่องนี้ในยูดาห์ ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 21, 'โอ ชนชาติที่โง่เขลาและไร้ความเข้าใจเอ๋ย ผู้มีตา แต่มองไม่เห็น ผู้มีหู แต่ฟังไม่ได้ยิน จงฟังข้อความนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 22, 'พระเยโฮวาห์ตรัสดังนี้ว่า “เจ้าไม่ยําเกรงเราหรือ เจ้าไม่ตัวสั่นอยู่ต่อหน้าเราหรือ คือเราผู้วางกองทรายไว้เป็นเขตล้อมทะเล เป็นเครื่องกีดขวางเป็นนิตย์มิให้ผ่านไปได้ แม้ว่าคลื่นจะซัด ก็เอาชนะไม่ได้ แม้คลื่นจะคะนอง ก็ข้ามไปไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 23, 'แต่ชนชาตินี้มีใจดื้อดึงและกบฏ เขาได้หันเหและจากไปเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 24, 'ข้อความนี้เขาไม่มุ่งอยู่ในใจของเขาทั้งหลายว่า ‘บัดนี้ให้เรายําเกรงพระเยโฮวาห์พระเจ้าของเรา ผู้ทรงประทานฝนตามฤดูของมันคือฝนต้นฤดูและฝนชุกปลายฤดู และทรงรักษาสัปดาห์ที่กําหนดการเกี่ยวข้าวไว้ให้แก่เรา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 25, 'ความชั่วช้าของเจ้าได้กระทําให้สิ่งเหล่านี้หันไปเสีย และบาปของเจ้าทั้งหลายก็กันสิ่งที่ดีไว้เสียจากเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 26, 'เพราะท่ามกลางประชาชนของเราจะพบคนชั่ว เขาซุ่มคอยเหมือนคนดักนกซุ่มอยู่ เขาวางกับไว้ เขาดักคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 27, 'เรือนของเขาเต็มด้วยความหลอกลวงเหมือนกระจาดที่มีนกเต็ม เพราะฉะนั้นเขาจึงใหญ่โตและมั่งมี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 28, 'เขาจึงอ้วนพีจนตัวเกลี้ยงเกลา ในเรื่องการกระทําความชั่วเขาล้ําหน้า เขามิได้ตัดสินคดี คือคดีของลูกกําพร้าพ่อ ด้วยความยุติธรรม ถึงกระนั้นเขาก็เจริญ เขามิได้ป้องกันสิทธิของคนขัดสน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 29, 'พระเยโฮวาห์ตรัสว่า “เพราะสิ่งอย่างนี้เราจะไม่ทําโทษเขาหรือ และไม่ควรที่จิตใจเราจะแก้แค้นประชาชาติที่เป็นอย่างนี้หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 30, 'สิ่งที่น่าตกตะลึงและน่าหวาดเสียวได้เกิดขึ้นในแผ่นดินนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 31, 'คือผู้พยากรณ์ได้พยากรณ์เท็จ และบรรดาปุโรหิตก็ปกครองตามการชี้นิ้วของเขา และประชาชนของเราชอบที่มีการอย่างนี้ แต่เจ้าทั้งหลายจะกระทําอะไรเมื่อกาลสุดปลายมาถึง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 1, 'โอ ประชาชนเบนยามินเอ๋ย จงรวมกันหนีไปจากกลางกรุงเยรูซาเล็ม จงเป่าแตรในเมืองเทโคอา และยกสัญญาณไฟขึ้นไว้บนเบธฮัคเคเรม เพราะเหตุร้ายโผล่ออกมาจากทิศเหนือ คือการทําลายอย่างใหญ่หลวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 2, 'เราเปรียบบุตรสาวของศิโยนเสมือนสาวสวยและบอบบาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 3, 'ผู้เลี้ยงแกะพร้อมกับฝูงแกะจะมาสู้เธอ เขาจะตั้งเต็นท์ไว้รอบเธอ ต่างก็จะหากินอยู่ในที่ของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 4, '“จงเตรียมทําสงครามกับเธอ ลุกขึ้น ให้เราโจมตีเวลาเที่ยงวัน” “วิบัติแก่พวกเรา เพราะว่ากลางวันคล้อยเสียแล้ว เงาของเวลาเย็นก็ยาวออกไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 5, '“ลุกขึ้น ให้เราเข้าตีเวลากลางคืน และทําลายบรรดาวังของเธอเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 6, 'เพราะพระเยโฮวาห์จอมโยธาตรัสดังนี้ว่า “จงโค่นต้นไม้ของเธอลง จงก่อเชิงเทินไว้สู้กรุงเยรูซาเล็ม นี่แหละนครที่ต้องถูกทําโทษ ภายในเธอไม่มีอะไรนอกจากการบีบบังคับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 7, 'น้ําพุปล่อยน้ําของมันออกมาฉันใด เธอก็ปล่อยความชั่วของเธอออกมาฉันนั้น ได้ยินถึงความทารุณและการทําลายมีภายในเธอ ความเศร้าโศกและความบาดเจ็บก็ปรากฏต่อเราเสมอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 8, 'โอ กรุงเยรูซาเล็มเอ๋ย จงรับคําสั่งสอนเถิด เกรงว่าจิตใจเราจะพรากจากเจ้าไปเสีย เกรงว่าเราจะกระทําให้เจ้าเป็นที่รกร้าง เป็นแผ่นดินที่ปราศจากคนอาศัย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 9, 'พระเยโฮวาห์จอมโยธาตรัสดังนี้ว่า “เขาทั้งหลายจะกวาดชนอิสราเอลที่เหลืออยู่นั้นเสียให้เกลี้ยงอย่างเล็มเถาองุ่น เหมือนคนเก็บผลองุ่นเอามือเก็บผลใส่ในตะกร้าอีกคํารบหนึ่ง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 10, 'ข้าพเจ้าควรจะพูดและให้คําตักเตือนแก่ผู้ใดดีนะ เพื่อเขาจะได้ยิน ดูเถิด หูของเขามิได้เข้าสุหนัต เขาฟังไม่ได้ ดูเถิด พระวจนะของพระเยโฮวาห์เป็นสิ่งที่เขาดูหมิ่น เขาไม่พอใจฟัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 11, 'เพราะฉะนั้น ข้าพเจ้าจึงมีพระพิโรธของพระเยโฮวาห์เต็มไปหมด ข้าพเจ้าจะเก็บไว้อีกไม่ไหวแล้ว “เราจะเทออกรดเด็กๆที่ตามถนน และรดพวกหนุ่มๆที่ชุมนุมกันอยู่ด้วย ทั้งสามีและภรรยาก็จะต้องเอาไป ทั้งคนแก่และคนชราด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 12, 'บ้านเรือนของเขาจะต้องยกให้เป็นของคนอื่น ทั้งไร่นาและภรรยาของเขาด้วย เพราะเราจะเหยียดมือของเราออกต่อสู้ชาวแผ่นดิน” พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 13, '“เพราะว่า ตั้งแต่คนที่ต่ําต้อยที่สุดจนถึงคนใหญ่โตที่สุด ทุกคนโลภอยากได้กําไร และทุกคนก็กระทําการด้วยความเท็จ ตั้งแต่ผู้พยากรณ์ตลอดถึงปุโรหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 14, 'เขาทั้งหลายได้รักษาแผลบุตรสาวแห่งประชาชนของเราแต่เล็กน้อยกล่าวว่า ‘สันติภาพ สันติภาพ’ เมื่อไม่มีสันติภาพเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 15, 'เขาละอายหรือเมื่อเขากระทําการอันน่าสะอิดสะเอียน เปล่าเลย เขาไม่ละอายเสียเลย เขาหน้าแดงด้วยความละอายไม่เป็นเลย เพราะฉะนั้นเขาจะล้มลงท่ามกลางพวกที่ล้มแล้ว เมื่อถึงเวลาที่เราลงอาญาเขาทั้งหลาย เขาจะล้มคว่ําลง” พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 16, 'พระเยโฮวาห์ตรัสดังนี้ว่า “จงยืนที่ถนนและมองให้ดี และถามหาทางโบราณนั้นว่า ทางดีอยู่ที่ไหน แล้วจงเดินในทางนั้น และท่านจะพบที่พักสงบสําหรับจิตใจของท่าน แต่เขาทั้งหลายกล่าวว่า ‘เราจะไม่เดินในนั้น’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 17, 'เราวางยามไว้เหนือเจ้า สั่งว่า ‘จงฟังเสียงแตร’ แต่เขาทั้งหลายกล่าวว่า ‘เราทั้งหลายจะไม่ยอมฟัง’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 18, 'เพราะฉะนั้น บรรดาประชาชาติเอ๋ย จงฟัง โอ ที่ประชุมเอ๋ย จงทราบเถิดว่า อะไรจะบังเกิดขึ้นแก่เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 19, 'โอ พิภพเอ๋ย จงฟังเถิด ดูเถิด เราจะนําความร้ายมาเหนือชนชาตินี้ คือผลแห่งความคิดทั้งหลายของเขา เพราะเขามิได้เชื่อฟังถ้อยคําของเรา ส่วนราชบัญญัติของเรานั้น เขาปฏิเสธเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 20, 'มีกํายานมาถึงเราจากเมืองเชบา มีตะไคร้ส่งมาจากเมืองไกล เพื่ออะไรเล่า เครื่องเผาบูชาของเจ้าก็ยังไม่เป็นที่รับได้ หรือเครื่องสักการบูชาของเจ้าก็ไม่เป็นที่พอใจเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 21, 'เพราะฉะนั้น พระเยโฮวาห์จึงตรัสดังนี้ว่า “ดูเถิด ต่อหน้าชนชาตินี้ เราจะวางเครื่องสะดุดไว้ให้เขาสะดุด ทั้งบิดาและบุตรชายด้วยกัน ทั้งเพื่อนบ้านและมิตรสหายจะพินาศ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 22, 'พระเยโฮวาห์ตรัสดังนี้ว่า “ดูเถิด ชนชาติหนึ่งกําลังมาจากแดนเหนือ ประชาชาติใหญ่ชาติหนึ่งจะถูกเร้าให้มาจากส่วนที่ไกลที่สุดของพิภพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 23, 'เขาทั้งหลายจะจับคันธนูและหอก เขาทั้งหลายดุร้ายและไม่มีความสงสาร เสียงของเขาก็เหมือนเสียงทะเลกําเริบ เขาทั้งหลายขี่ม้า และจัดเตรียมกระบวนเหมือนชายที่จะเข้าสงคราม โอ บุตรสาวศิโยนเอ๋ย เขาทั้งหลายมาต่อสู้เจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 24, 'พวกเราได้ยินกิตติศัพท์พวกนั้น มือของเราก็อ่อนลง ความแสนระทมและความเจ็บปวดได้จับเราไว้เหมือนสตรีกําลังคลอดบุตร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 25, 'อย่าเดินออกไปในทุ่งนา หรือเดินบนถนน เพราะดาบของศัตรูและความสยดสยองอยู่ทุกด้าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 26, 'โอ บุตรสาวแห่งประชาชนของเราเอ๋ย จงเอาผ้ากระสอบคาดเอวไว้ และกลิ้งเกลือกอยู่ในกองเถ้า จงไว้ทุกข์เหมือนเพื่อบุตรชายคนเดียว เป็นการคร่ําครวญอย่างแสนขมขื่นที่สุด เพราะว่าผู้ทําลายมาสู้เราในทันทีทันใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 27, '“เราได้กระทําให้เจ้าเป็นหอคอยและป้อมปราการท่ามกลางประชาชนของเรา เพื่อเจ้าจะทราบและลองดูพฤติการณ์ทั้งหลายของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 28, 'เขาทั้งหลายมักกบฏอย่างดื้อด้านทั้งสิ้น เที่ยวนินทาเขาไป เขาทั้งหลายเป็นทองเหลือง และเป็นเหล็ก เขาทุกคนประพฤติเลวทรามทั้งนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 29, 'เครื่องสูบลมของเขาสูบอย่างดุเดือด ตะกั่วก็ถูกไฟเผาผลาญเสีย ถลุงกันเรื่อยไปก็เปล่าประโยชน์ เพราะว่าคนชั่วก็ยังไม่ได้ถูกถอนออกไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 30, 'จะเรียกเขาทั้งหลายได้ว่า เป็นขี้เงิน เพราะพระเยโฮวาห์ทรงปฏิเสธเขาเสียแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 1, 'พระวจนะซึ่งมาจากพระเยโฮวาห์ถึงเยเรมีย์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 2, '“เจ้าจงยืนอยู่ในประตูกําแพงพระนิเวศของพระเยโฮวาห์ และประกาศถ้อยคําเหล่านี้ที่นั่นว่า บรรดาคนยูดาห์ทั้งปวง ผู้เข้ามาในประตูกําแพงนี้เพื่อจะนมัสการพระเยโฮวาห์ จงฟังพระวจนะพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 3, 'พระเยโฮวาห์จอมโยธาพระเจ้าของอิสราเอล ตรัสดังนี้ว่า จงปรับปรุงพฤติการณ์และการกระทําของเจ้าเสีย และเราจะให้เจ้าอาศัยอยู่ในสถานที่นี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 4, 'อย่าไว้วางใจในคําเท็จเหล่านี้ที่ว่า ‘นี่เป็นพระวิหารของพระเยโฮวาห์ พระวิหารของพระเยโฮวาห์ พระวิหารของพระเยโฮวาห์’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 5, 'เพราะว่า ถ้าเจ้าปรับปรุงพฤติการณ์และการกระทําของเจ้าจริงๆ ถ้าเจ้าให้ความยุติธรรมระหว่างคนหนึ่งกับเพื่อนบ้านของเขาจริงๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 6, 'ถ้าเจ้าไม่บีบบังคับคนต่างด้าว ลูกกําพร้าพ่อหรือหญิงม่าย และไม่หลั่งโลหิตที่ไร้ความผิดให้ถึงตายในที่นี้ และเจ้าทั้งหลายไม่ติดตามพระอื่นไปให้เจ็บตัวเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 7, 'แล้วเราจะให้เจ้าอาศัยอยู่ในสถานที่นี้ ในแผ่นดินซึ่งเราได้ยกให้แก่บรรพบุรุษของเจ้าเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 8, 'ดูเถิด เจ้าวางใจในคําเท็จอย่างไม่ได้ประโยชน์อะไรเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 9, 'เจ้าจะลักทรัพย์ กระทําฆาตกรรม ล่วงประเวณี ปฏิญาณเท็จ เผาเครื่องบูชาถวายพระบาอัลและติดตามพระอื่นซึ่งเจ้าทั้งหลายมิได้รู้จักหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 10, 'แล้วจึงมายืนต่อหน้าเราในนิเวศนี้ ซึ่งเรียกตามนามของเรา และกล่าวว่า ‘เราทั้งหลายได้รับการช่วยให้รอดพ้นมาแล้ว เพื่อจะไปกระทําสิ่งที่น่าสะอิดสะเอียนเหล่านี้ทั้งสิ้น’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 11, 'นิเวศนี้ซึ่งเรียกตามนามของเรา ในสายตาของเจ้าได้กลายเป็นที่ซ่องสุมของพวกโจรไปแล้วหรือ พระเยโฮวาห์ตรัสว่า ดูเถิด แม้แต่เราก็ได้เห็นเองแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 12, 'แต่จงไปยังสถานที่ของเราซึ่งเคยอยู่ในเมืองชีโลห์ ซึ่งทีแรกเราได้กระทําให้นามของเราอยู่ที่นั่น จงดูว่าเพราะความชั่วร้ายของอิสราเอลประชาชนของเรา เราได้กระทําอะไรต่อสถานที่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 13, 'พระเยโฮวาห์ตรัสว่า และบัดนี้ เพราะเจ้าทั้งหลายได้กระทําสิ่งเหล่านี้ทั้งสิ้น และเมื่อเราพูดกับเจ้าอย่างไม่หยุดยั้ง แต่เจ้าทั้งหลายหาได้ฟังไม่ และเมื่อเราได้เรียกพวกเจ้า แต่เจ้ามิได้ตอบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 14, 'เหตุฉะนี้เราจะกระทําต่อนิเวศนี้ซึ่งเราเรียกตามนามของเรา และซึ่งพวกเจ้าได้วางใจนั้น และกระทําแก่สถานที่ซึ่งเราได้ยกให้แก่เจ้าและแก่บรรพบุรุษของเจ้าเหมือนเราได้กระทําแก่ชีโลห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 15, 'และเราจะเหวี่ยงเจ้าทิ้งจากสายตาของเรา เหมือนอย่างที่เราได้ทิ้งบรรดาพวกพี่น้องของเจ้า คือบรรดาเชื้อสายของเอฟราอิมทั้งหมดนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 16, 'เพราะฉะนั้นเจ้าอย่าอธิษฐานเพื่อชนชาตินี้ อย่าร้องขึ้นหรืออธิษฐานเพื่อเขา และอย่าวิงวอนขอต่อเรา เพราะเราจะไม่ฟังเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 17, 'เจ้ามิได้เห็นดอกหรือว่า เขากระทําอะไรกันในหัวเมืองทั้งหลายแห่งยูดาห์ และตามถนนหนทางในเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 18, 'พวกเด็กๆก็เก็บฟืน พวกพ่อก็ก่อไฟ พวกผู้หญิงก็นวดแป้ง เพื่อทําขนมถวายแก่เจ้าแม่แห่งฟ้าสวรรค์ และเขาเทเครื่องดื่มบูชาถวายแก่พระอื่นๆ เพื่อยั่วยุให้เราโกรธ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 19, 'พระเยโฮวาห์ตรัสว่า “คือเราที่เขายั่วยุหรือ มิใช่ยั่วยุตัวเขาเองให้ไปสู่ความขายหน้าของเขาทั้งหลายดอกหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 20, 'ฉะนั้น องค์พระผู้เป็นเจ้าพระเจ้าจึงตรัสดังนี้ว่า “ดูเถิด ความกริ้วและความโกรธของเราจะเทลงมาบนสถานที่นี้ บนมนุษย์และสัตว์ บนต้นไม้ในท้องทุ่งและบนพืชผลของแผ่นดิน จะเผาผลาญเสียและจะดับไม่ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 21, 'พระเยโฮวาห์จอมโยธา พระเจ้าแห่งอิสราเอล ตรัสดังนี้ว่า “จงเพิ่มเครื่องเผาบูชาเข้ากับเครื่องสักการบูชาของเจ้า และจงรับประทานเนื้อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 22, 'เพราะในวันที่เราได้พาเขาทั้งหลายออกมาจากแผ่นดินอียิปต์ เรามิได้พูดกับบรรพบุรุษของเจ้าหรือสั่งเขาเรื่องเครื่องเผาบูชาและเครื่องสักการบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 23, 'แต่เราบัญชาเขาทั้งหลายอย่างนี้ว่า ‘จงเชื่อฟังเสียงของเรา และเราจะเป็นพระเจ้าของเจ้า และเจ้าจะเป็นประชาชนของเรา และดําเนินในหนทางที่เราได้บัญชาเจ้าไว้ เพื่อเจ้าจะได้อยู่เย็นเป็นสุข’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 24, 'แต่เขาทั้งหลายมิได้เชื่อฟังหรือเงี่ยหูฟัง แต่เขาทั้งหลายดําเนินตามแผนการของเขาเอง และในความดื้อกระด้างตามจิตใจชั่วของเขาทั้งหลาย และเดินถอยหลัง มิได้เดินขึ้นหน้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 25, 'ตั้งแต่วันที่บรรพบุรุษของเจ้าทั้งหลายออกจากแผ่นดินอียิปต์จนทุกวันนี้ เราได้ส่งบรรดาผู้พยากรณ์ผู้รับใช้ของเราไปยังเขาอย่างไม่หยุดยั้ง วันแล้ววันเล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 26, 'ถึงกระนั้นเขาก็ยังไม่ฟังเรา หรือเงี่ยหูฟัง แต่ได้กระทําให้คอของตนแข็ง เขาได้กระทําชั่วร้ายยิ่งกว่าบรรพบุรุษทั้งหลายของเขาเสียอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 27, 'เจ้าจึงกล่าวบรรดาถ้อยคําเหล่านี้แก่เขา แต่เขาจะไม่ฟังเจ้า เจ้าจงร้องเรียกเขา แต่เขาจะไม่ยอมตอบเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 28, 'แต่เจ้าจงพูดแก่เขาว่า ‘นี่เป็นประชาชาติที่ไม่เชื่อฟังพระสุรเสียงของพระเยโฮวาห์พระเจ้าของเขา และไม่ยอมรับการแก้ไข ความจริงพินาศเสียแล้ว ถูกตัดขาดเสียจากปากของเขาแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 29, 'โอ เยรูซาเล็มเอ๋ย จงตัดผมของเจ้าออกเหวี่ยงทิ้งไป จงคร่ําครวญบนที่สูง เพราะว่าพระเยโฮวาห์ทรงปฏิเสธและละทิ้งคนในยุคแห่งพระพิโรธของพระองค์แล้ว’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 30, 'พระเยโฮวาห์ตรัสว่า เพราะคนยูดาห์ได้กระทําความชั่วในสายตาของเรา เขาได้ตั้งสิ่งที่น่าสะอิดสะเอียนไว้ในนิเวศซึ่งเรียกตามนามของเรา กระทําให้นิเวศนั้นมัวหมองไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 31, 'และได้สร้างปูชนียสถานสูงของโทเฟท ซึ่งอยู่ในหุบเขาแห่งบุตรชายของฮินโนม เพื่อจะเผาบุตรชายและบุตรสาวของเขาทั้งหลายเสียด้วยไฟ ซึ่งเรามิได้บัญชา และไม่เคยมีขึ้นในใจของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 32, 'พระเยโฮวาห์ตรัสว่า เพราะฉะนั้น ดูเถิด วันเวลาจะมาถึงเมื่อเขาจะไม่เรียกที่นั้นอีกว่าโทเฟท หรือภูเขาแห่งบุตรชายของฮินโนม แต่จะเรียกว่า หุบเขาแห่งการฆ่าฟันกัน เพราะเขาจะฝังกันไว้ในโทเฟทจนไม่มีที่ว่างแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 33, 'และศพของชนชาตินี้จะเป็นอาหารของนกในอากาศ และแก่สัตว์แห่งแผ่นดินโลก และไม่มีใครจะขับไล่ให้มันไปเสียได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 34, 'เราจะกระทําให้เสียงรื่นเริงและเสียงยินดี เสียงของเจ้าบ่าวและเสียงของเจ้าสาว ขาดหายไปจากหัวเมืองของยูดาห์ และจากถนนหนทางแห่งกรุงเยรูซาเล็ม เพราะว่าแผ่นดินนั้นจะต้องรกร้างไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 1, '“พระเยโฮวาห์ตรัสว่า ในกาลครั้งนั้น กระดูกของบรรดากษัตริย์ยูดาห์ กระดูกเจ้านาย กระดูกปุโรหิต กระดูกผู้พยากรณ์ และกระดูกของชาวเมืองเยรูซาเล็มจะมีคนเอาออกมาจากอุโมงค์ของเขาทั้งหลายนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 2, 'และเขาจะกระจายกระดูกเหล่านั้นออกต่อหน้าดวงอาทิตย์ ดวงจันทร์ และบริวารแห่งฟ้าสวรรค์ทั้งสิ้น ซึ่งเขาทั้งหลายรักและปรนนิบัติ ซึ่งเขาได้ติดตาม ซึ่งเขาได้แสวงหาและนมัสการ จะไม่มีใครรวบรวมหรือฝังกระดูกเหล่านี้ แต่จะเป็นเหมือนมูลสัตว์ที่พื้นดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 3, 'บรรดาคนที่เหลืออยู่จากครอบครัวอันชั่วร้ายนี้ ซึ่งตกค้างอยู่ในสถานที่ทั้งสิ้นซึ่งเราได้ขับไล่เขาไป จะเลือกความตายยิ่งกว่าที่จะมีชีวิตอยู่ พระเยโฮวาห์จอมโยธาตรัสดังนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 4, 'เจ้าจงพูดกับเขาทั้งหลายว่า พระเยโฮวาห์ตรัสดังนี้ว่า เมื่อมนุษย์ล้มลง เขาจะไม่ลุกขึ้นอีกหรือ ถ้าผู้หนึ่งผู้ใดหันไป เขาจะไม่หันกลับมาหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 5, 'ทําไมชาวเยรูซาเล็มนี้จึงได้หันไป เป็นการกลับสัตย์อยู่เป็นนิตย์ เขายึดการหลอกลวงไว้มั่น เขาทั้งหลายปฏิเสธไม่ยอมกลับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 6, 'เราได้ตั้งใจและคอยฟัง แต่เขาทั้งหลายก็พูดไม่ถูกต้อง ไม่มีคนใดกลับใจจากความชั่วของตน กล่าวว่า ‘ฉันได้ทําอะไรไปแล้วบ้าง’ ทุกคนหันไปตามทางของเขาเอง เหมือนม้าวิ่งหัวทิ่มเข้าไปในสงคราม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 7, 'แม้ว่านกกระสาดําบนฟ้ายังรู้จักเวลากําหนดของมัน และนกเขา นกนางแอ่น และนกกรอด ได้รักษาเวลามาของมัน แต่ประชาชนของเราไม่รู้จักคําตัดสินของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 8, 'เจ้าจะพูดได้อย่างไรว่า ‘เรามีปัญญา และพระราชบัญญัติของพระเยโฮวาห์ก็อยู่กับเรา’ แต่ดูเถิด แน่นอนเขาทําอย่างไร้ประโยชน์ คือปากกาของพวกอาลักษณ์ได้ทําอย่างไร้ประโยชน์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 9, 'คนมีปัญญาจะได้รับความอาย เขาจะคร้ามกลัวและถูกจับตัวไป ดูเถิด เขาได้ปฏิเสธพระวจนะของพระเยโฮวาห์ และปัญญาอย่างใดมีในตัวเขาเล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 10, 'เพราะฉะนั้น เราจะให้ภรรยาของเขาตกไปเป็นของคนอื่น ให้ไร่นาของเขาตกแก่ผู้ที่จะได้รับเป็นมรดก เพราะว่าตั้งแต่คนที่ต่ําต้อยที่สุดถึงคนที่ใหญ่โตที่สุด ทุกคนโลภอยากได้กําไร ตั้งแต่ผู้พยากรณ์ถึงปุโรหิต ทุกคนก็ทําการฉ้อเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 11, 'เขาได้รักษาแผลบุตรสาวแห่งประชาชนของเราแต่เล็กน้อย กล่าวว่า ‘สันติภาพ สันติภาพ’ เมื่อไม่มีสันติภาพเสียเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 12, 'เมื่อเขากระทําการอันน่าสะอิดสะเอียน เขาละอายหรือ เปล่าเลย เขาไม่ละอายเสียเลย เขาหน้าแดงด้วยความละอายไม่เป็นเลย เพราะฉะนั้นเขาจะล้มลงท่ามกลางพวกที่ล้มแล้ว ในเวลาแห่งการลงอาญาเขาทั้งหลาย เขาจะล้มคว่ําลง พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 13, 'พระเยโฮวาห์ตรัสว่า เราจะผลาญเขาเป็นแน่ เถาองุ่นจะไม่มีผล หรือต้นมะเดื่อไม่มีผล ใบก็จะเหี่ยวแห้งไป และสิ่งใดที่เราให้เขาก็อันตรธานไปจากเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 14, 'ทําไมเราจึงนั่งนิ่งๆ จงพากันมา ให้เราเข้าไปในหัวเมืองที่มีป้อม และนิ่งเสียที่นั่นเถิด เพราะพระเยโฮวาห์พระเจ้าของเราจะทรงให้เรานิ่ง และทรงประทานน้ําดีหมีให้เราดื่ม เพราะเราได้กระทําบาปต่อพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 15, 'เรามองหาสันติภาพ แต่ไม่มีความดีอะไรมาเลย เรามองหาเวลารักษาให้หาย แต่ประสบความสยดสยอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 16, '“เสียงคะนองแห่งม้าของเขาก็ได้ยินมาจากเมืองดาน แผ่นดินทั้งสิ้นก็หวั่นไหวด้วยเสียงร้องของกองอาชาของเขา มันทั้งหลายมากินแผ่นดินและสิ่งทั้งปวงที่อยู่บนนั้นจนหมด ทั้งเมืองและผู้ที่อาศัยอยู่ในเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 17, 'เพราะ ดูเถิด เราจะส่งงูเข้ามาท่ามกลางเจ้า คืองูทับทางซึ่งจะผูกด้วยมนต์ไม่ได้ และมันจะกัดเจ้าทั้งหลาย” พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 18, 'เมื่อข้าพเจ้าจะปลอบโยนตัวเองเนื่องด้วยความเศร้าโศก จิตใจของข้าพเจ้าก็อ่อนเปลี้ยอยู่ภายใน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 19, 'ฟังซิ เสียงร้องของบุตรสาวแห่งประชาชนของข้าพเจ้า เพราะเหตุคนที่อาศัยอยู่ในแผ่นดินห่างไกล “พระเยโฮวาห์มิได้สถิตในศิโยนหรือ กษัตริย์ของเมืองนั้นไม่อยู่ในนั้นหรือ” “ทําไมเขายั่วยุเราให้โกรธด้วยรูปเคารพสลักของเขา และด้วยพระต่างด้าวของเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 20, '“ฤดูเกี่ยวก็ผ่านไป ฤดูแล้งก็สิ้นลงแล้ว และเราทั้งหลายก็ไม่รอด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 21, 'เพราะแผลบุตรสาวแห่งประชาชนของข้าพเจ้า หัวใจข้าพเจ้าจึงเป็นแผล ข้าพเจ้าเศร้าหมอง และความสยดสยองก็ยึดข้าพเจ้าไว้มั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 22, 'ไม่มีพิมเสนในกิเลอาดหรือ ไม่มีแพทย์ที่นั่นหรือ ทําไมสุขภาพของบุตรสาวแห่งประชาชนของข้าพเจ้าจึงไม่กลับสู่สภาพเดิมได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 1, 'โอ ถ้าศีรษะของข้าพเจ้าเป็นน้ํา และดวงตาของข้าพเจ้าเป็นบ่อน้ําพุก็จะดี เพื่อข้าพเจ้าจะได้ร้องไห้ทั้งกลางวันและกลางคืน เพราะบุตรสาวแห่งประชาชนของข้าพเจ้าที่ถูกฆ่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 2, 'โอ ถ้าข้าพเจ้ามีที่พักสําหรับคนเดินทางอยู่ที่ในถิ่นทุรกันดารก็จะดี เพื่อข้าพเจ้าจะได้พรากจากชนชาติของข้าพเจ้า และไปให้พ้นเขาเสีย เพราะเขาทั้งหลายเป็นคนล่วงประเวณีทั้งหมด และเป็นหมู่คนที่มักทรยศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 3, '“เขาทั้งหลายงอลิ้นของเขาเหมือนคันธนูเพื่อกล่าวความเท็จ แต่เขาทั้งหลายไม่กล้าสู้เพื่อความจริงในแผ่นดิน เพราะเขาทั้งหลายจากความชั่วอย่างนี้ไปสู่ความชั่วอย่างนั้น และเขาทั้งหลายไม่รู้จักเรา” พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 4, '“ขอให้ทุกคนระวังเพื่อนบ้านของตน และอย่าวางใจในพี่น้องคนใดเลย เพราะว่าพี่น้องทุกคนจะเป็นคนหลอกล่อ และเพื่อนบ้านทุกคนจะเที่ยวไปเป็นคนครหานินทา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 5, 'ทุกคนจะล่อลวงเพื่อนบ้านของตน ไม่มีใครจะพูดความจริงสักคนเดียว เขาได้สอนลิ้นของเขาให้พูดมุสา เขาได้กระทําความชั่วช้าจนน่าเบื่อหน่าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 6, 'เจ้าอาศัยอยู่ท่ามกลางการล่อลวง โดยการล่อลวงเขาปฏิเสธที่จะรู้จักเรา” พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 7, 'เพราะฉะนั้น พระเยโฮวาห์จอมโยธาตรัสดังนี้ว่า “ดูเถิด เราจะถลุงเขาและทดลองเขา เหตุบุตรสาวแห่งประชาชนของเรา เราจะทําอย่างอื่นได้อย่างไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 8, 'ลิ้นของเขาเป็นเหมือนลูกศรที่ยิงออกไป มันพูดมารยา เขาพูดอย่างสันติกับเพื่อนบ้านของเขาด้วยปาก แต่ในใจของเขา เขาวางแผนการคอยดักเขาอยู่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 9, 'พระเยโฮวาห์ตรัสว่า “ไม่ควรที่เราจะลงโทษเขาเพราะสิ่งเหล่านี้หรือ ไม่ควรที่จิตใจเราจะแก้แค้นประชาชาติที่เป็นอย่างนี้หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 10, 'เราจะร้องไห้และครวญครางเหตุภูเขานั้น และคร่ําครวญเหตุลานหญ้าในถิ่นทุรกันดารเพราะว่ามันถูกเผาเสีย ไม่มีผู้ใดผ่านไปมา ไม่ได้ยินเสียงสัตว์เลี้ยงร้อง ทั้งนกในอากาศและสัตว์ได้หนีไปเสียแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 11, 'เราจะกระทําให้เยรูซาเล็มเป็นกองซากปรักหักพัง เป็นถ้ําของมังกร และเราจะกระทําให้หัวเมืองของยูดาห์เป็นที่รกร้าง ไม่มีชาวเมืองสักคนเดียว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 12, 'ใครเป็นคนมีปัญญาที่จะเข้าใจความนี้ได้ และมีผู้ใดที่พระโอษฐ์ของพระเยโฮวาห์ได้ตรัสแก่เขา เขาจึงประกาศความนั้นได้ เหตุไฉนแผ่นดินจึงพังทําลายและถูกเผาเสียเหมือนถิ่นทุรกันดาร จึงไม่มีใครผ่านไปมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 13, 'และพระเยโฮวาห์ตรัสว่า “เพราะเขาทั้งหลายทอดทิ้งราชบัญญัติของเรา ซึ่งเราได้ตั้งไว้ต่อหน้าเขา และไม่ได้เชื่อฟังเสียงของเรา หรือดําเนินตามนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 14, 'แต่ได้ดําเนินตามใจของตนเองอย่างดื้อดึง และติดตามพระบาอัล อย่างที่บรรพบุรุษได้สั่งสอนเขาไว้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 15, 'เพราะฉะนั้น พระเยโฮวาห์จอมโยธา พระเจ้าแห่งอิสราเอล จึงตรัสว่า “ดูเถิด เราจะเลี้ยงชนชาตินี้ด้วยบอระเพ็ด และให้น้ําดีหมีเขาดื่ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 16, 'เราจะกระจายเขาไปท่ามกลางประชาชาติ ที่ตัวเขาเองและบรรพบุรุษของเขาไม่รู้จัก และเราจะส่งดาบให้ไล่ตามเขาทั้งหลาย จนเราจะผลาญเขาสิ้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 17, 'พระเยโฮวาห์จอมโยธาตรัสดังนี้ว่า “จงพิจารณาดู และเรียกนางร้องไห้ให้มา จงให้คนไปตามหญิงที่ชํานาญมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 18, 'ให้เขารีบส่งเสียงคร่ําครวญเพื่อเราทั้งหลาย เพื่อน้ําตาจะอาบตาของเรา และหนังตาของเราจะมีน้ําตาพุออกมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 19, 'เพราะได้ยินเสียงคร่ําครวญจากศิโยนว่า ‘เราทั้งหลายย่อยยับเพียงใดแล้ว เราอับอายหนักหนา เพราะเราได้ทอดทิ้งแผ่นดิน เพราะที่อาศัยของเราได้เหวี่ยงพวกเราออกไป’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 20, 'โอ หญิงเอ๋ย จงฟังพระวจนะของพระเยโฮวาห์ และให้หูของเจ้ารับพระวจนะจากพระโอษฐ์ของพระองค์ จงสอนบทคร่ําครวญแก่บุตรสาวของเจ้า จงสอนบทเพลงโศกเศร้าแก่เพื่อนบ้านของเธอทุกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 21, 'เพราะความตายได้ขึ้นมาเข้าหน้าต่างของเรา มันเข้ามาในวังทั้งหลายของเรา ตัดพวกเด็กๆออกเสียจากข้างนอก และตัดคนหนุ่มๆออกเสียจากถนนทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 22, 'จงพูดว่า “พระเยโฮวาห์ตรัสดังนี้ว่า ‘ศพมนุษย์จะล้มลงเหมือนมูลสัตว์ตกตามพื้นทุ่ง เหมือนฟ่อนข้าวล้มตามผู้เกี่ยว และไม่มีผู้ใดจะเก็บ’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 23, 'พระเยโฮวาห์ตรัสดังนี้ว่า “อย่าให้ผู้มีปัญญาอวดในสติปัญญาของตน อย่าให้ชายฉกรรจ์อวดในความเข้มแข็งของตน อย่าให้คนมั่งมีอวดในความมั่งคั่งของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 24, 'แต่ให้ผู้อวดอวดในสิ่งนี้คือในการที่เขาเข้าใจและรู้จักเราว่าเราคือพระเยโฮวาห์ ทรงสําแดงความเมตตา ความยุติธรรม และความชอบธรรมในโลก เพราะว่าเราพอใจในสิ่งเหล่านี้” พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 25, 'พระเยโฮวาห์ตรัสว่า “ดูเถิด วันเวลากําลังมาถึงแล้ว เมื่อเราจะลงโทษบรรดาผู้ที่เข้าสุหนัตพร้อมด้วยผู้ที่ไม่ได้เข้าสุหนัต คือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 26, 'อียิปต์ ยูดาห์ เอโดม และคนอัมโมน โมอับและบรรดาคนที่อยู่ในมุมที่ไกลที่สุด ทุกคนที่อาศัยอยู่ในถิ่นทุรกันดาร เพราะบรรดาประชาชาติเหล่านี้มิได้เข้าสุหนัต และบรรดาวงศ์วานอิสราเอลก็มิได้เข้าสุหนัตทางจิตใจ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 1, 'โอ วงศ์วานอิสราเอลเอ๋ย จงฟังพระวจนะซึ่งพระเยโฮวาห์ตรัสกับเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 2, 'พระเยโฮวาห์ตรัสดังนี้ว่า “อย่าเรียนรู้วิถีทางแห่งบรรดาประชาชาติ หรืออย่าคร้ามกลัวเพราะหมายสําคัญของท้องฟ้า ตามที่บรรดาประชาชาติคร้ามกลัวนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 3, 'เพราะธรรมเนียมของชนชาติทั้งหลายก็ไร้สาระ เขาตัดต้นไม้มาจากป่าต้นหนึ่ง เป็นสิ่งที่มือช่างได้กระทําด้วยขวาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 4, 'เขาทั้งหลายก็เอาเงินและทองมาประดับ เขาตอกไว้แน่นด้วยค้อนและตะปู มันก็เคลื่อนไหวไปมาไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 5, 'มันตั้งขึ้นเหมือนต้นอินทผลัม มันพูดไม่ได้ คนต้องขนมันไป เพราะมันเดินไม่ได้ อย่ากลัวมันเลย เพราะมันทําร้ายไม่ได้ มันก็ทําดีไม่ได้ด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 6, 'โอ ข้าแต่พระเยโฮวาห์ หามีผู้ใดเหมือนพระองค์ไม่ พระองค์ทรงเป็นใหญ่ และพระนามของพระองค์มีฤทธิ์มาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 7, 'โอ ข้าแต่กษัตริย์แห่งบรรดาประชาชาติ ผู้ใดจะไม่ยําเกรงพระองค์ เพราะพระองค์สมควรแก่การอย่างนี้ เพราะในบรรดาปราชญ์ของบรรดาประชาชาติ และในบรรดาราชอาณาจักรทั้งสิ้นของเขา ไม่มีผู้ใดเหมือนพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 8, 'เขาทั้งหลายทั้งโฉดและโง่เขลา ไม้อันนั้นเป็นแต่คําสอนไร้สาระ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 9, 'เครื่องเงินทุบนั้นเขาเอามาจากทารชิช และเอาทองคํามาจากเมืองอุฟาส เป็นผลงานของช่างฝีมือ และเป็นผลน้ํามือของช่างทอง เสื้อผ้าของรูปเคารพนั้นสีครามและสีม่วง เป็นผลงานของคนชํานาญทั้งนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 10, 'แต่พระเยโฮวาห์เป็นพระเจ้าเที่ยงแท้ พระองค์ทรงเป็นพระเจ้าผู้ทรงพระชนม์และเป็นพระมหากษัตริย์เนืองนิตย์ พอทรงพระพิโรธแผ่นดินก็หวั่นไหว และบรรดาประชาชาติจะทนต่อความกริ้วของพระองค์ไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 11, 'เจ้าจงพูดกับเขาทั้งปวงดังนี้ว่า “บรรดาพระผู้ที่มิได้ทรงสร้างฟ้าสวรรค์และแผ่นดินโลก จะพินาศไปจากแผ่นดินโลกและจากภายใต้ฟ้าสวรรค์เหล่านี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 12, 'พระองค์ทรงสร้างโลกด้วยฤทธิ์เดชของพระองค์ พระองค์ทรงสถาปนาพิภพไว้ด้วยพระสติปัญญาของพระองค์ และทรงขึงฟ้าสวรรค์ออกด้วยความเข้าใจของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 13, 'เมื่อพระองค์ทรงเปล่งพระสุรเสียงก็มีเสียงน้ําคะนองในท้องฟ้า และทรงกระทําให้หมอกลอยขึ้นจากปลายพิภพ ทรงกระทําฟ้าแลบเพื่อฝน และทรงนําลมมาจากพระคลังของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 14, 'มนุษย์ทุกคนโฉดในทางความรู้ของตน ช่างทองทุกคนจะได้อายเพราะรูปเคารพสลักของตน เพราะรูปเคารพหล่อของเขาเป็นของเท็จ และไม่มีลมหายใจในรูปเคารพนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 15, 'มันเป็นของไร้ค่า และเป็นผลงานแห่งความผิดพลาด มันจะต้องพินาศเมื่อถึงเวลาการลงโทษ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 16, 'พระองค์ผู้ทรงเป็นส่วนของยาโคบไม่เหมือนสิ่งเหล่านี้ เพราะพระองค์ทรงเป็นผู้ที่ก่อร่างทุกสิ่งขึ้น และอิสราเอลเป็นตระกูลที่เป็นมรดกของพระองค์ พระเยโฮวาห์จอมโยธาเป็นพระนามของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 17, 'โอ เจ้าทั้งหลายที่อาศัยอยู่ภายใต้การถูกล้อมเอ๋ย จงเก็บข้าวของจากพื้นดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 18, 'เพราะพระเยโฮวาห์ตรัสดังนี้ว่า “ดูเถิด เราจะเหวี่ยงชาวแผ่นดินออกไปเสีย ณ เวลานี้ และเราจะนําความทุกข์ใจมาถึงเขาเพื่อให้เขารู้สึก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 19, 'วิบัติแก่ข้าพเจ้า เพราะความเจ็บปวดของข้าพเจ้า บาดแผลของข้าพเจ้าก็สาหัส แต่ข้าพเจ้าว่า “แท้จริงนี่เป็นความทุกข์ใจ และข้าพเจ้าจะต้องทนเอา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 20, 'พลับพลาของข้าพเจ้าก็ถูกทําลาย และเชือกของข้าพเจ้าก็ขาดสิ้น ลูกๆของข้าพเจ้าจากข้าพเจ้าไปหมด และไม่มีเขาอีกแล้ว ไม่มีผู้หนึ่งผู้ใดที่จะกางเต็นท์ของข้าพเจ้าให้ข้าพเจ้าอีก และแขวนม่านให้ข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 21, 'เพราะว่าผู้เลี้ยงแกะก็โฉด และไม่ได้เสาะหาพระเยโฮวาห์ เพราะฉะนั้นเขาจะมิได้จําเริญขึ้น และฝูงแกะทั้งหลายของเขาก็จะกระจัดกระจายไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 22, 'ดูเถิด เสียงลือมาถึงแล้ว เสียงโกลาหลยิ่งใหญ่จากแดนเหนือมากระทําให้หัวเมืองยูดาห์เป็นที่รกร้าง และให้เป็นถ้ําของมังกร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 23, 'โอ ข้าแต่พระเยโฮวาห์ ข้าพระองค์ทราบแล้วว่า ทางของมนุษย์ไม่อยู่ที่ตัวเขา คือไม่อยู่ที่มนุษย์ผู้ซึ่งดําเนินไปที่จะนําฝีก้าวของตนเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 24, 'โอ ข้าแต่พระเยโฮวาห์ ขอทรงโปรดตีสอนข้าพระองค์ด้วยความยุติธรรม มิใช่ด้วยความกริ้วของพระองค์ เกรงว่าพระองค์จะทรงนําข้าพระองค์มาถึงความสูญเปล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 25, 'ขอพระองค์ทรงเทพระพิโรธของพระองค์เหนือเหล่าประชาชาติที่ไม่รู้จักพระองค์ และเหนือครอบครัวทั้งหลายที่ไม่ออกพระนามของพระองค์ เพราะเขาทั้งหลายได้กินเผาผลาญยาโคบ เขาได้เขมือบท่านเสีย และเผาผลาญท่านเสีย และกระทําที่อาศัยของท่านให้รกร้างไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 1, 'พระวจนะซึ่งมาจากพระเยโฮวาห์ถึงเยเรมีย์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 2, '“เจ้าจงฟังถ้อยคําในพันธสัญญานี้เถิด และจงกล่าวแก่คนยูดาห์และชาวกรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 3, 'เจ้าจงกล่าวแก่เขาว่า พระเยโฮวาห์พระเจ้าแห่งอิสราเอลตรัสดังนี้ว่า คนหนึ่งคนใดที่ไม่เชื่อฟังถ้อยคําในพันธสัญญานี้ ให้ผู้นั้นเป็นที่แช่งเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 4, 'ซึ่งเป็นพันธสัญญาที่เราบัญชาแก่บรรพบุรุษของเจ้าทั้งหลาย ในวันที่เราได้นําเขาออกมาจากแผ่นดินอียิปต์ จากเตาไฟเหล็ก กล่าวว่า จงเชื่อฟังเสียงของเรา และจงกระทําทุกอย่างที่เราบัญชาเจ้าไว้ เจ้าจึงจะเป็นประชาชนของเรา และเราจะเป็นพระเจ้าของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 5, 'เพื่อเราจะกระทําให้สําเร็จตามคําปฏิญาณซึ่งเราได้ปฏิญาณไว้กับบรรพบุรุษของเจ้าว่า จะประทานแผ่นดินซึ่งมีน้ํานมและน้ําผึ้งไหลบริบูรณ์แก่เขาอย่างที่เป็นอยู่ทุกวันนี้” แล้วข้าพเจ้าจึงทูลตอบว่า “โอ ข้าแต่พระเยโฮวาห์ ขอให้เป็นดังนั้นเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 6, 'และพระเยโฮวาห์ตรัสแก่ข้าพเจ้าว่า “จงป่าวร้องถ้อยคําเหล่านี้ทั้งสิ้นในหัวเมืองของยูดาห์และในถนนหนทางเยรูซาเล็มว่า จงฟังถ้อยคําแห่งพันธสัญญานี้และประพฤติตาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 7, 'เพราะเราได้กล่าวตักเตือนอย่างแข็งแรงต่อบรรพบุรุษของเจ้า ในวันที่เรานําเขาขึ้นมาจากแผ่นดินอียิปต์ แม้จนถึงทุกวันนี้ยังกล่าวตักเตือนอย่างไม่หยุดยั้งว่า จงเชื่อฟังเสียงของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 8, 'ถึงกระนั้นเขาทั้งหลายก็ไม่เชื่อฟังหรือเงี่ยหูฟัง แต่ทุกคนดําเนินตามความดื้อกระด้างแห่งจิตใจอันชั่วร้ายของเขา เหตุฉะนี้เราจึงจะนําบรรดาถ้อยคําแห่งพันธสัญญานี้ที่เราได้บัญชาให้เขากระทํา แต่เขามิได้กระทําตามนั้น ให้มาตกเหนือเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 9, 'พระเยโฮวาห์ตรัสกับข้าพเจ้าอีกว่า “มีการคิดกบฏท่ามกลางคนยูดาห์และท่ามกลางชาวกรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 10, 'เขาได้หันกลับไปหาความชั่วช้าแห่งบรรพบุรุษของเขา ผู้ปฏิเสธไม่ยอมฟังถ้อยคําของเรา เขาติดตามพระอื่นๆ และปรนนิบัติพระนั้น วงศ์วานอิสราเอลและวงศ์วานยูดาห์ได้ผิดพันธสัญญาของเรา ซึ่งเรากระทําต่อบรรพบุรุษของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 11, 'เพราะฉะนั้น พระเยโฮวาห์ตรัสดังนี้ว่า ดูเถิด เราจะนําเหตุร้ายมาเหนือเขา ซึ่งเขาหนีไม่พ้น ถึงเขาจะร้องทุกข์ต่อเรา เราจะไม่ฟังเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 12, 'แล้วหัวเมืองยูดาห์และชาวกรุงเยรูซาเล็มจะไปร้องทุกข์ต่อพระ ซึ่งเขาทั้งหลายได้เผาเครื่องหอมถวายนั้น แต่พระเหล่านั้นจะช่วยเขาให้รอดในเวลาลําบากไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 13, 'โอ ยูดาห์เอ๋ย พระทั้งหลายของเจ้าก็มากเท่ากับหัวเมืองทั้งหลายของเจ้า และตามจํานวนหนทางในกรุงเยรูซาเล็มเจ้าได้ตั้งแท่นบูชาถวายสิ่งที่น่าอับอาย คือแท่นสําหรับเผาเครื่องหอมถวายแก่พระบาอัล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 14, 'เพราะฉะนั้น เจ้าอย่าอธิษฐานเพื่อชนชาตินี้ อย่าร้องขึ้นหรืออธิษฐานเพื่อเขาทั้งหลาย เพราะเราจะไม่ฟังเมื่อเขาร้องต่อเราในเวลาลําบาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 15, 'ผู้ที่รักของเรานั้นมีสิทธิอะไรในนิเวศของเราเล่า ในเมื่อนางนั้นได้กระทําการชั่วช้ามาก และเนื้ออันบริสุทธิ์ได้พ้นไปจากเจ้าแล้ว เมื่อเจ้ากระทําชั่ว เจ้าจึงเริงโลด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 16, 'พระเยโฮวาห์ทรงเคยเรียกเจ้าว่า ‘ต้นมะกอกเทศสดงดงามด้วยผลเป็นอย่างดี’ แต่พระองค์ทรงก่อไฟเผามันเสียด้วยเสียงพายุใหญ่ และกิ่งทั้งหลายของมันก็ถูกหักเสียแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 17, 'ด้วยว่าพระเยโฮวาห์จอมโยธา ผู้ได้ปลูกเจ้า ได้ทรงประกาศความร้ายให้ตกแก่เจ้า เพราะความชั่วช้าของวงศ์วานอิสราเอลและวงศ์วานยูดาห์ ซึ่งเขาได้กระทําต่อสู้ตนเอง เพื่อยั่วยุให้เราโกรธ ด้วยการเผาเครื่องหอมถวายแก่พระบาอัล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 18, 'พระเยโฮวาห์ทรงสําแดงแก่ข้าพเจ้า และข้าพเจ้าก็รู้แล้ว พระองค์ทรงสําแดงการกระทําของเขาแก่ข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 19, 'แต่ข้าพระองค์เป็นเหมือนลูกแกะหรือวัวซึ่งถูกพามาถึงที่ฆ่า ข้าพระองค์ไม่ทราบเลยว่า พวกเขาได้ออกอุบายต่อสู้ข้าพระองค์โดยกล่าวว่า “ให้เราทําลายต้นไม้กับผลของมันเสียด้วย ให้เราตัดเขาออกเสียจากแผ่นดินของคนเป็น เพื่อชื่อของเขาจะไม่เป็นที่ระลึกถึงอีกเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 20, 'แต่ว่า โอ ข้าแต่พระเยโฮวาห์จอมโยธา ผู้ทรงพิพากษาอย่างชอบธรรม ผู้ทรงทดลองดูทั้งใจและจิต ขอให้ข้าพระองค์แลเห็นการแก้แค้นของพระองค์ตกแก่เขา เพราะข้าพระองค์ได้มอบเรื่องของข้าพระองค์ไว้กับพระองค์แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 21, 'เพราะฉะนั้น พระเยโฮวาห์ตรัสดังนี้เกี่ยวกับคนตําบลอานาโธท ผู้แสวงหาชีวิตของเจ้าและกล่าวว่า “อย่าพยากรณ์ในพระนามของพระเยโฮวาห์ มิฉะนั้นเจ้าจะต้องตายด้วยมือของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 22, 'เพราะฉะนั้น พระเยโฮวาห์จอมโยธาตรัสว่า “ดูเถิด เราจะลงโทษเขาทั้งปวง พวกคนหนุ่มจะตายด้วยดาบ บรรดาบุตรชายและบุตรสาวของเขาจะตายด้วยการกันดารอาหาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 23, 'จะไม่มีเหลือสักคนเดียว เพราะเราจะนําความร้ายมาสู่คนตําบลอานาโธท คือปีแห่งการลงโทษเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 1, 'โอ ข้าแต่พระเยโฮวาห์ เมื่อข้าพระองค์สู้คดีกับพระองค์ พระองค์ก็ทรงเป็นฝ่ายถูก แม้กระนั้นข้าพระองค์ยังขอทูลเสนอมูลคดีของข้าพระองค์ต่อพระองค์ ไฉนทางของคนชั่วจึงจําเริญขึ้น ไฉนทุกคนที่ทรยศก็อยู่เย็นเป็นสุข');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 2, 'พระองค์ทรงปลูกเขาทั้งหลาย และเขาทั้งหลายก็หยั่งรากลง เขาทั้งหลายงอกงามขึ้นและบังเกิดผล พระองค์ทรงอยู่ใกล้ที่ปากของเขา แต่ไกลจากใจของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 3, 'โอ ข้าแต่พระเยโฮวาห์ แต่พระองค์ทรงรู้จักข้าพระองค์ พระองค์ทรงเห็นข้าพระองค์และทรงทดลองใจของข้าพระองค์ที่มีต่อพระองค์ ขอทรงฉุดเขาออกมาเหมือนแกะสําหรับการฆ่า และตั้งเขาทั้งหลายไว้ต่างหากเพื่อวันฆ่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 4, 'แผ่นดินนี้จะไว้ทุกข์นานเท่าใด และผักหญ้าตามท้องนาทุกแห่งจะเหี่ยวแห้งไปนานเท่าใด เพราะความชั่วของผู้ที่อาศัยอยู่ในนั้น สัตว์และนกก็ถูกผลาญไปเสียสิ้น เพราะเขาว่า “พระองค์จะไม่ทอดพระเนตรบั้นปลายสุดของเราทั้งหลาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 5, '“ถ้าเจ้าวิ่งแข่งกับทหารราบ และเขาทําให้เจ้าเหน็ดเหนื่อย เจ้าจะแข่งกับม้าได้อย่างไร และถ้าเจ้ายังเหน็ดเหนื่อยในแผ่นดินแห่งสันติภาพซึ่งเจ้าวางใจนั้น เจ้าจะทําอย่างไรในคลื่นของลุ่มแม่น้ําจอร์แดน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 6, 'เพราะว่าแม้พี่น้องของเจ้าและวงศ์วานของบิดาเจ้า แม้ว่าเขาก็ได้กระทําการทรยศต่อเจ้า เขายังเรียกให้ฝูงชนไล่ตามเจ้าไป ถึงแม้ว่าเขาพูดถ้อยคําอย่างดีแก่เจ้า อย่าเชื่อเขาเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 7, 'เราได้ละทิ้งนิเวศของเรา เราได้เหวี่ยงมรดกของเราทิ้ง เราได้มอบผู้ที่รักของจิตใจเราไว้ในมือศัตรูของเธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 8, 'มรดกของเราได้กลายเป็นเหมือนสิงโตในป่าต่อเรา เขาตะเบ็งเสียงของเขาเข้าใส่เรา เพราะฉะนั้นเราจึงเกลียดเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 9, 'มรดกของเราทําแก่เราเหมือนนกลายด่าง นกซึ่งอยู่รอบๆต่อสู้นกนั้น ไปเถอะ ไปชุมนุมสัตว์ป่าทุ่งทั้งสิ้น นํามันให้มากินเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 10, 'ผู้เลี้ยงแกะเป็นอันมากได้ทําลายสวนองุ่นของเราเสีย เขาทั้งหลายได้เหยียบย่ําส่วนของเราไว้ใต้ฝ่าเท้า เขาทั้งหลายได้กระทําให้ส่วนอันพึงใจของเรากลายเป็นถิ่นทุรกันดารที่รกร้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 11, 'เขาทั้งหลายได้กระทําส่วนของเราให้รกร้าง เมื่อรกร้างส่วนนั้นก็คร่ําครวญต่อเรา แผ่นดินทั้งสิ้นก็ถูกทิ้งให้รกร้าง เพราะไม่มีผู้ใดเอาใจใส่ในเรื่องนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 12, 'ผู้ทําลายล้างได้มาบนบรรดาที่สูงทั้งปวงในถิ่นทุรกันดาร เพราะว่าแสงดาบของพระเยโฮวาห์จะทําลายจากปลายแผ่นดินนี้ไปถึงปลายอีกข้างหนึ่ง ไม่มีเนื้อหนังใดๆที่จะมีสันติภาพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 13, 'เขาทั้งหลายได้หว่านข้าวสาลี แต่จะเกี่ยวหนาม เขาได้กระทําให้ตัวเจ็บปวด แต่จะไม่ได้กําไรอะไร เขาทั้งหลายจะละอายด้วยผลการเกี่ยวของเขา ด้วยเหตุความโกรธเกรี้ยวกราดของพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 14, 'พระเยโฮวาห์ตรัสดังนี้ ด้วยเรื่องบรรดาเพื่อนบ้านที่ชั่วร้ายของเรา ผู้ที่ได้แตะต้องมรดกซึ่งเราได้ให้อิสราเอลประชาชนของเราสืบมรดกนั้นว่า “ดูเถิด เราจะถอนเขาทั้งหลายขึ้นจากแผ่นดินของเขา และเราจะถอนวงศ์วานยูดาห์จากท่ามกลางเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 15, 'และต่อมาหลังจากที่เราได้ถอนเขาทั้งหลายขึ้นแล้ว เราจะกลับมีความเมตตาต่อเขาอีก และเราจะนําเขาทั้งหลายมาอีก ให้ต่างคนก็มายังมรดกของตน และยังแผ่นดินของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 16, 'และต่อมา ถ้าเขาทั้งหลายจะอุตส่าห์ศึกษาทางแห่งประชาชนของเรา คือปฏิญาณในนามของเราว่า ‘ตราบใดที่พระเยโฮวาห์ทรงพระชนม์อยู่แน่’ อย่างที่เขาได้สอนประชาชนของเราให้ปฏิญาณโดยพระบาอัล แล้วเขาจะได้รับการสร้างขึ้นไว้ท่ามกลางประชาชนของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 17, 'แต่ถ้าเขาทั้งหลายจะไม่เชื่อฟัง แล้วเราจะถอนประชาชาตินั้นขึ้นและทําลายเขาจนสิ้น” พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 1, 'พระเยโฮวาห์ตรัสแก่ข้าพเจ้าด้วยว่า “จงไปซื้อผ้าป่านคาดเอวมาผืนหนึ่ง คาดเอวของเจ้าไว้และอย่าจุ่มน้ํา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 2, 'ข้าพเจ้าจึงซื้อผ้าคาดเอวผืนหนึ่งตามพระวจนะของพระเยโฮวาห์ และคาดเอวของข้าพเจ้าไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 3, 'และพระวจนะของพระเยโฮวาห์มาถึงข้าพเจ้าครั้งที่สองว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 4, '“จงเอาผ้าคาดเอวซึ่งเจ้าได้ซื้อมา ซึ่งอยู่ที่เอวของเจ้า และจงลุกขึ้นไปยังแม่น้ํายูเฟรติส แล้วซ่อนผ้านั้นไว้ในซอกหินแห่งหนึ่ง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 5, 'ข้าพเจ้าก็ไปและซ่อนผ้านั้นไว้ข้างแม่น้ํายูเฟรติส ดังที่พระเยโฮวาห์ทรงบัญชาข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 6, 'ต่อมาอีกหลายวันพระเยโฮวาห์ตรัสกับข้าพเจ้าว่า “จงลุกขึ้นไปยังแม่น้ํายูเฟรติส และเอาผ้าคาดเอวซึ่งเราได้สั่งเจ้าให้ซ่อนไว้ที่นั่นนั้นมาเสียจากที่นั่น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 7, 'แล้วข้าพเจ้าก็ไปที่แม่น้ํายูเฟรติส และขุดเอาผ้าคาดเอวมาจากที่ซึ่งข้าพเจ้าได้ซ่อนไว้ ดูเถิด ผ้าคาดเอวนั้นเสียหมด จะใช้การสิ่งใดก็ไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 8, 'แล้วพระวจนะของพระเยโฮวาห์ก็มายังข้าพเจ้าว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 9, '“พระเยโฮวาห์ตรัสดังนี้ว่า เราก็จะทําลายความทะนงใจของยูดาห์ และความทะนงใจใหญ่ยิ่งของเยรูซาเล็มเสียอย่างนั้นแหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 10, 'คือชนชาติที่ชั่วร้ายนี้ ผู้ปฏิเสธไม่ฟังถ้อยคําของเรา ผู้ที่ดําเนินตามความดื้อกระด้างแห่งจิตใจของตนเอง และได้ติดตามพระอื่น เพื่อจะปรนนิบัติและนมัสการพระเหล่านั้น จะเป็นเหมือนผ้าคาดเอวนี้ซึ่งจะใช้การสิ่งใดก็ไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 11, 'เพราะผ้าคาดเอวติดอยู่ที่เอวของมนุษย์ฉันใด เราก็ได้กระทําให้วงศ์วานทั้งสิ้นของอิสราเอลและวงศ์วานทั้งสิ้นของยูดาห์ติดอยู่กับเราฉันนั้น พระเยโฮวาห์ตรัสดังนี้ เพื่อเขาทั้งหลายจะเป็นประชาชน เป็นชื่อเสียง เป็นที่สรรเสริญ และสง่าราศีแก่เรา แต่เขาทั้งหลายก็ไม่ฟัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 12, 'ฉะนั้นเจ้าจงกล่าวถ้อยคํานี้แก่เขาทั้งหลาย พระเยโฮวาห์พระเจ้าแห่งอิสราเอลตรัสดังนี้ว่า ‘น้ําองุ่นจะเต็มไหทุกใบ’ และเขาทั้งหลายจะพูดกับเจ้าว่า ‘เราไม่รู้หรือว่าน้ําองุ่นจะต้องเต็มไหทุกใบ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 13, 'แล้วเจ้าจงพูดกับเขาทั้งหลายว่า พระเยโฮวาห์ตรัสดังนี้ว่า ดูเถิด เราจะให้ชาวแผ่นดินนี้ทั้งสิ้นเต็มไปด้วยความมึนเมา คือกษัตริย์ทั้งหลายของผู้ประทับบนบัลลังก์ของดาวิด พวกปุโรหิต พวกผู้พยากรณ์ และชาวกรุงเยรูซาเล็มทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 14, 'และพระเยโฮวาห์ตรัสว่า เราจะเหวี่ยงเขาทั้งหลายให้ชนกันและกัน พวกพ่อก็ชนพวกลูก เราจะไม่สงสาร หรือไม่ไว้ชีวิต หรือไม่เมตตา แต่เราจะทําลายเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 15, 'จงฟังและเงี่ยหูฟัง อย่ายโสไปเลย เพราะพระเยโฮวาห์ทรงลั่นพระวาจาแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 16, 'จงถวายสง่าราศีแด่พระเยโฮวาห์ พระเจ้าของเจ้าทั้งหลาย ก่อนที่พระองค์จะทรงนําความมืดมา ก่อนที่เท้าของเจ้าจะสะดุดบนภูเขาที่มีแสงโพล้เพล้ และขณะเมื่อเจ้าทั้งหลายมองหาความสว่าง พระองค์ทรงกลับให้เป็นเงามัจจุราช และทรงกระทําให้เป็นความมืดทึบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 17, 'แต่ถ้าเจ้าทั้งหลายจะไม่ฟัง จิตใจของข้าพเจ้าก็จะร้องไห้ลับๆ เพราะความทะนงใจของเจ้า ตาของข้าพเจ้าจะร้องไห้มากมาย และมีน้ําตาอาบหน้า เพราะฝูงแกะของพระเยโฮวาห์ถูกต้อนเอาไปเป็นเชลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 18, 'จงกล่าวแก่กษัตริย์และพระราชินีว่า “ขอทรงประทับ ณ ที่ต่ํา เพราะว่าอํานาจของพระองค์ คือมงกุฎแห่งสง่าราศีของพระองค์จะหล่นลงมา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 19, 'หัวเมืองแห่งภาคใต้ก็ถูกปิดซึ่งไม่มีใครจะเปิดได้ ยูดาห์ทั้งสิ้นก็จะถูกกวาดไปเป็นเชลย จะถูกกวาดไปเป็นเชลยหมดทีเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 20, '“จงเงยหน้าของเจ้าขึ้นดูเขาเหล่านั้นที่มาจากทิศเหนือ ฝูงแกะที่ได้มอบไว้ให้แก่เจ้านั้นอยู่ที่ไหน คือฝูงแกะที่งดงามของเจ้านั่นน่ะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 21, 'เจ้าจะว่าอย่างไรเมื่อเขาจะลงโทษเจ้า เพราะเจ้าเองได้สอนเขาให้เป็นนายและเป็นประมุขของเจ้า ความเจ็บปวดจะไม่เข้ามาครอบงําเจ้า อย่างความเจ็บปวดของผู้หญิงที่กําลังคลอดบุตรหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 22, 'และถ้าเจ้าว่าในใจของเจ้าว่า ‘ทําไมสิ่งเหล่านี้จึงเกิดกับข้า’ ก็เพราะความชั่วช้าที่มากมายใหญ่โตของเจ้า เสื้อของเจ้าจึงต้องถูกถลกขึ้น และส้นเท้าของเจ้าจึงไม่ปิดบัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 23, 'คนเอธิโอเปียเปลี่ยนวรรณของตนเองได้หรือ หรือเสือดาวเปลี่ยนลายของมัน ถ้าได้แล้วเจ้าทั้งหลายผู้ที่เคยต่อการกระทําความชั่วจะมากระทําความดีก็ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 24, 'ฉะนั้นเราจะกระจายเขาทั้งหลายไปเหมือนแกลบที่ถูกลมจากถิ่นทุรกันดาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 25, 'นี่เป็นส่วนของเจ้า เป็นส่วนที่เราได้ตวงออกให้แก่เจ้า” พระเยโฮวาห์ตรัสดังนี้แหละ “เพราะเจ้าได้ลืมเราเสีย และไว้วางใจในการมุสา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 26, 'ฉะนั้น เราเองจะถลกเสื้อคลุมของเจ้ามาปกหน้าเจ้า คือให้เห็นความอับอายขายหน้าของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 27, 'เราได้เห็นการล่วงประเวณีของเจ้า การครวญหา การเล่นชู้ที่มากด้วยราคะของเจ้า และการที่น่าสะอิดสะเอียนของเจ้า บนเนินเขาทั้งหลายที่ในทุ่งนา โอ เยรูซาเล็มเอ๋ย วิบัติแก่เจ้า อีกนานสักเท่าใดเจ้าจึงจะยอมกระทําให้เจ้าสะอาดได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 1, 'พระวจนะของพระเยโฮวาห์ซึ่งมาถึงเยเรมีย์ เกี่ยวด้วยความแห้งแล้งว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 2, '“ยูดาห์ไว้ทุกข์ และประตูเมืองทั้งปวงของเธอก็อ่อนกําลังลง ประชาชนของเธอก็แต่งดําหน้าก้มอยู่บนแผ่นดิน และเสียงร้องของเยรูซาเล็มก็ขึ้นไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 3, 'ขุนนางของเธอส่งผู้น้อยของเขาให้ไปตักน้ํา เขาทั้งหลายไปยังที่ขังน้ําเห็นว่าไม่มีน้ํา เขาทั้งหลายก็กลับไปด้วยภาชนะเปล่า เขาทั้งหลายได้อายและขายหน้า เขาจึงคลุมศีรษะของเขาทั้งหลายเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 4, 'เพราะเรื่องแผ่นดินที่แห้งแล้งเนื่องจากไม่มีฝนตกบนแผ่นดิน ชาวนาทั้งหลายก็อับอาย เขาทั้งหลายจึงคลุมศีรษะของเขาเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 5, 'แม้กวางตัวเมียที่อยู่ในท้องทุ่งก็ละทิ้งลูกที่ตกใหม่ของมันเสีย เพราะว่าไม่มีหญ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 6, 'ลาป่ายืนอยู่บนที่สูง มันสูดลมหายใจเหมือนมังกร ตาของมันก็มืดมัว เพราะไม่มีหญ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 7, '“แม้ว่าความชั่วช้าของข้าพระองค์ทั้งหลายก็เป็นพยานปรักปรําข้าพระองค์ โอ ข้าแต่พระเยโฮวาห์ ขอพระองค์โปรดเถิดเพื่อเห็นแก่พระนามของพระองค์ ด้วยว่าบรรดาการกลับสัตย์ของข้าพระองค์ทั้งหลายก็มากยิ่ง ข้าพระองค์ทั้งหลายกระทําบาปต่อพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 8, 'โอ ข้าแต่พระองค์ผู้เป็นความหวังแห่งอิสราเอล เป็นพระผู้ช่วยให้รอดของเขาในยามลําบาก ไฉนพระองค์จะทรงเป็นเหมือนคนต่างด้าวในแผ่นดิน หรือเหมือนคนเดินทางแวะอาศัยค้างเพียงคืนเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 9, 'ไฉนพระองค์จะทรงเป็นเหมือนชายที่งงงัน หรือเหมือนคนที่มีกําลังมากแต่ช่วยใครให้รอดไม่ได้ โอ ข้าแต่พระเยโฮวาห์ แม้กระนั้นก็ดีพระองค์ทรงสถิตท่ามกลางข้าพระองค์ทั้งหลาย คนเขาเรียกพวกข้าพระองค์โดยพระนามของพระองค์ ขออย่าทรงละข้าพระองค์ทั้งหลายไว้เสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 10, 'พระเยโฮวาห์ตรัสแก่ชนชาตินี้ว่า “เขาทั้งหลายรักที่จะพเนจรไปอย่างนี้ เขาทั้งหลายไม่ยับยั้งเท้าของเขาไว้ ฉะนั้นพระเยโฮวาห์จึงไม่ทรงรับเขา บัดนี้พระองค์จะทรงระลึกถึงความชั่วช้าของเขา และลงโทษการผิดบาปของเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 11, 'พระเยโฮวาห์ตรัสแก่ข้าพเจ้าว่า “อย่าอธิษฐานเพื่อความอยู่เย็นเป็นสุขของชนชาตินี้เลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 12, 'แม้ว่าเขาอดอาหาร เราก็จะไม่ฟังเสียงร้องของเขา แม้เขาถวายเครื่องเผาบูชาและเครื่องธัญญบูชา เราก็จะไม่รับมัน แต่เราจะผลาญเขาเสียด้วยดาบ ด้วยการกันดารอาหาร และด้วยโรคระบาด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 13, 'แล้วข้าพเจ้าพูดว่า “ข้าแต่องค์พระผู้เป็นเจ้าพระเจ้า ดูเถิด พวกผู้พยากรณ์กล่าวแก่เขาว่า ‘ท่านทั้งหลายจะไม่เห็นดาบหรือจะมีการกันดารอาหาร แต่เราจะให้สันติภาพที่แน่นอนแก่เจ้าในสถานที่นี้’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 14, 'และพระเยโฮวาห์ตรัสแก่ข้าพเจ้าว่า “พวกผู้พยากรณ์เหล่านั้นพยากรณ์เท็จในนามของเรา เรามิได้ใช้เขาทั้งหลาย และเรามิได้บัญชาเขาหรือพูดกับเขา เขาพยากรณ์นิมิตและการทํานายเท็จแก่เจ้าทั้งหลาย เป็นการทํานายที่ไร้ค่า เป็นการล่อลวงของจิตใจเขาเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 15, 'ฉะนั้น พระเยโฮวาห์จึงตรัสดังนี้เกี่ยวด้วยพวกผู้พยากรณ์ ผู้พยากรณ์ในนามของเรา แม้ว่าเราไม่ได้ใช้เขาทั้งหลาย และผู้กล่าวว่า ‘ดาบและการกันดารอาหารจะไม่มาถึงแผ่นดินนี้’ พวกผู้พยากรณ์เหล่านั้นจะถูกผลาญเสียด้วยดาบและการกันดารอาหาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 16, 'และประชาชนผู้ซึ่งเขาพยากรณ์ให้ฟังนั้น จะถูกทิ้งไว้ในถนนหนทางกรุงเยรูซาเล็ม เพราะเหตุการกันดารอาหารและดาบ ซึ่งไม่มีผู้ใดจะฝังเขา คือทั้งตัวเขาทั้งหลาย ภรรยาของเขา บุตรชายและบุตรสาวของเขา เพราะเราจะเทความชั่วของเขาสนองเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 17, 'เจ้าจงกล่าวถ้อยคํานี้แก่เขาว่า ‘ขอให้ตาของเรามีน้ําตาไหลทั้งกลางคืนและกลางวัน อย่าให้หยุดยั้ง เพราะบุตรสาวพรหมจารีแห่งประชาชนของเรา ถูกขยี้ด้วยความหายนะยิ่งใหญ่ ถูกตีอย่างหนักมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 18, 'ถ้าเราออกไปในท้องนา ดูเถิด นั่นคนที่ถูกฆ่าเสียด้วยดาบ ถ้าเราเข้าไปในกรุง ดูเถิด นั่นโรคอันเนื่องจากการกันดาร เพราะว่าทั้งพวกผู้พยากรณ์และปุโรหิตไปค้าขายกันในแผ่นดินที่เขาไม่รู้จัก’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 19, 'พระองค์ทรงปฏิเสธไม่รับยูดาห์เสียทีเดียวแล้วหรือ พระทัยของพระองค์เกลียดศิโยนเสียแล้วหรือ ไฉนพระองค์ทรงเฆี่ยนตีข้าพระองค์ทั้งหลาย จนไม่มีการรักษาข้าพระองค์ให้หาย ข้าพระองค์ทั้งหลายมองหาสันติภาพ แต่ไม่มีความดีมาเลย เรามองหาเวลาเยียวยา แต่ประสบความสยดสยอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 20, 'โอ ข้าแต่พระเยโฮวาห์ ข้าพระองค์ทั้งหลายขอสารภาพความชั่วของพวกข้าพระองค์ และความชั่วช้าของบรรพบุรุษของข้าพระองค์ เพราะข้าพระองค์ทั้งหลายได้กระทําบาปต่อพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 21, 'เพราะเห็นแก่พระนามของพระองค์ ขออย่าทรงเกลียดพวกข้าพระองค์ ขออย่าให้หลู่เกียรติแห่งพระที่นั่งอันรุ่งเรืองของพระองค์ ขอทรงระลึกและอย่าทรงหักพันธสัญญาของพระองค์ซึ่งมีไว้กับข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 22, 'ในบรรดาพระเทียมเท็จแห่งประชาชาติทั้งหลายมีพระองค์ใดเล่าที่ทําให้เกิดฝนได้หรือ ท้องฟ้าประทานห่าฝนได้หรือ โอ ข้าแต่พระเยโฮวาห์ พระเจ้าของพวกข้าพระองค์ พระองค์มิใช่พระเจ้าองค์นั้นดอกหรือ พวกข้าพระองค์จึงคอยหวังในพระองค์ เพราะพระองค์ทรงกระทําสิ่งเหล่านี้ทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 1, 'ฝ่ายพระเยโฮวาห์ตรัสแก่ข้าพเจ้าว่า “แม้ว่าโมเสส และซามูเอล จะมายืนอยู่ต่อหน้าเรา จิตใจของเราจะไม่หันไปหาชนชาตินี้ ไล่เขาทั้งหลายออกไปให้พ้นสายตาของเรา แล้วให้เขาไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 2, 'และต่อมาถ้าเขาถามเจ้าว่า ‘เราจะไปที่ไหน’ เจ้าจงพูดกับเขาว่า พระเยโฮวาห์ตรัสดังนี้ว่า ‘คนเหล่านั้นที่กําหนดให้แก่ความตายจะไปหาความตาย คนเหล่านั้นที่กําหนดให้แก่ดาบจะไปหาดาบ คนเหล่านั้นที่กําหนดให้แก่การกันดารอาหารจะไปหาการกันดารอาหาร คนที่กําหนดให้แก่การเป็นเชลยจะไปหาการเป็นเชลย’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 3, 'พระเยโฮวาห์ตรัสว่า “เราจะกําหนดสี่อย่างไว้เหนือเขาคือ ดาบสังหาร สุนัขกัดฉีก นกในอากาศ และสัตว์บนแผ่นดินโลกที่จะกัดกินและทําลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 4, 'และเราจะกระทําให้เขาถูกถอดไปยังราชอาณาจักรทั้งสิ้นแห่งแผ่นดินโลก เหตุด้วยการกระทําซึ่งมนัสเสห์บุตรเฮเซคียาห์กษัตริย์แห่งยูดาห์ได้กระทําในเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 5, 'โอ เยรูซาเล็มเอ๋ย ใครจะสงสารเจ้า หรือใครจะเสียใจกับเจ้า หรือใครจะแวะมาถามทุกข์สุขของเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 6, 'พระเยโฮวาห์ตรัสว่า “เจ้าได้ปฏิเสธเรา เจ้าถอยหลังเรื่อยไป เราจึงจะเหยียดมือออกไปต่อสู้เจ้าและทําลายเจ้า เราเอือมต่อการผ่อนผันแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 7, 'เราจะซัดเขาด้วยส้อมซัดข้าวในบรรดาประตูเมืองแห่งแผ่นดินนั้น เราจะทําให้ลูกของเขาทั้งหลายตาย เราจะทําลายประชาชนของเรา เพราะเขาทั้งหลายมิได้หันกลับจากพฤติการณ์ของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 8, 'เรากระทําให้แม่ม่ายของเขามีมาก ยิ่งกว่าเม็ดทรายในทะเล ณ เวลาเที่ยงวัน เราได้นําผู้ทําลายมาสู่บรรดาแม่ของคนหนุ่มทั้งหลาย เราได้กระทําให้ความสยดสยองตกเหนือกรุงนั้นโดยฉับพลัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 9, 'เธอที่คลอดบุตรเจ็ดคนก็อ่อนกําลัง เธอตายไปแล้ว ดวงอาทิตย์ของเธอตกเมื่อยังวันอยู่ เธอได้รับความละอายและขายหน้า เราจะมอบผู้ที่เหลืออยู่ให้แก่ดาบต่อหน้าศัตรูของเขา” พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 10, 'แม่จ๋า วิบัติแก่ฉัน ที่แม่คลอดฉันมาเป็นคนที่ให้เกิดการแก่งแย่งและการชิงดีแก่แผ่นดินทั้งสิ้น ฉันก็มิได้ให้ยืมโดยคิดดอกเบี้ย หรือฉันก็มิได้ยืมเขาโดยคิดดอกเบี้ย แต่เขาทุกคนแช่งฉัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 11, 'พระเยโฮวาห์ตรัสว่า “พวกที่เหลืออยู่จะอยู่เย็นเป็นสุข เราจะกระทําให้พวกศัตรูกระทําดีต่อเจ้าในเวลาลําบากและในเวลาทุกข์ใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 12, 'เหล็กจะหักเหล็กจากทิศเหนือและเหล็กกล้าได้หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 13, 'บรรดาสิ่งของและทรัพย์สมบัติของเจ้า เราจะมอบให้เป็นของริบไม่คิดค่า เพราะบาปทั้งสิ้นของเจ้าตลอดทั่วดินแดนของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 14, 'เราจะกระทําให้เจ้าไปกับพวกศัตรูของเจ้ายังแผ่นดินซึ่งเจ้าไม่รู้จัก เพราะความโกรธของเรา เราก่อไฟขึ้น ซึ่งจะเผาเจ้าทั้งหลายเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 15, 'โอ ข้าแต่พระเยโฮวาห์ พระองค์ทรงทราบ ขอทรงระลึกถึงข้าพระองค์ และเยี่ยมเยียนข้าพระองค์ ขอทรงแก้แค้นผู้ข่มเหงข้าพระองค์เพื่อข้าพระองค์ เพราะการอดกลั้นพระทัยของพระองค์นั้น ขออย่าทรงนําข้าพระองค์ไปเสีย ขอทรงตระหนักว่าข้าพระองค์ทนการติเตียนด้วยเห็นแก่พระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 16, 'เมื่อพบพระวจนะของพระองค์แล้ว ข้าพระองค์ก็กินเสีย พระวจนะของพระองค์เป็นความชื่นบานแก่ข้าพระองค์ และเป็นความปีติยินดีแห่งจิตใจของข้าพระองค์ โอ ข้าแต่พระเยโฮวาห์ พระเจ้าจอมโยธา เพราะว่าเขาเรียกข้าพระองค์ตามพระนามของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 17, 'ข้าพระองค์มิได้นั่งอยู่ในหมู่คนที่เยาะเย้ยกัน ทั้งข้าพระองค์ก็มิได้เปรมปรีดิ์ ข้าพระองค์นั่งอยู่คนเดียว เพราะเหตุพระหัตถ์ของพระองค์ เพราะพระองค์ทรงให้ข้าพระองค์เต็มด้วยความกริ้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 18, 'ไฉนความเจ็บของข้าพระองค์มิได้หยุดยั้ง บาดแผลของข้าพระองค์ก็รักษาไม่หาย มันไม่ยอมหาย พระองค์ทรงเป็นเหมือนผู้มุสาแก่ข้าพระองค์หรือ หรืออย่างน้ําที่เหือดแห้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 19, 'เพราะฉะนั้น พระเยโฮวาห์จึงตรัสว่า “ถ้าเจ้ากลับมา เราจะให้เจ้ากลับมาอีก และเจ้าจะยืนอยู่ต่อหน้าเรา ถ้าเจ้าแยกสิ่งประเสริฐไปจากสิ่งเลวทราม เจ้าจะเป็นเหมือนปากของเรา จงให้เขาทั้งหลายหันกลับมาหาเจ้า แต่เจ้าอย่าหันไปหาเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 20, 'เราจะกระทําเจ้าให้เป็นกําแพงป้อมทองเหลืองแก่ชนชาตินี้ เขาทั้งหลายก็จะต่อสู้กับเจ้า แต่เขาจะไม่ชนะเจ้า เพราะเราอยู่กับเจ้า จะช่วยเจ้าให้รอดและช่วยเจ้าให้พ้น” พระเยโฮวาห์ตรัสดังนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 21, '“เราจะช่วยเจ้าให้พ้นจากมือของคนชั่ว และไถ่เจ้าจากกํามือของคนอํามหิต”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 1, 'พระวจนะของพระเยโฮวาห์มายังข้าพเจ้าว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 2, '“เจ้าอย่ามีภรรยา เจ้าอย่ามีบุตรชายหรือบุตรสาวในที่นี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 3, 'เพราะพระเยโฮวาห์ตรัสดังนี้เรื่องบุตรชายและบุตรสาวที่เกิดในที่นี้ และทรงกล่าวถึงพวกมารดาที่คลอดบุตรเหล่านั้น และพวกบิดาที่ให้กําเนิดคนเหล่านั้นในแผ่นดินนี้ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 4, 'เขาทั้งหลายจะตายด้วยโรคร้าย จะไม่มีการโอดครวญอาลัยเขาทั้งหลาย หรือจะไม่มีใครจัดการฝังเขา เขาจะเป็นเหมือนมูลสัตว์ที่อยู่บนพื้นแผ่นดิน เขาทั้งหลายจะพินาศด้วยดาบและการกันดารอาหาร และศพทั้งหลายของเขาจะเป็นอาหารของนกในอากาศและของสัตว์แห่งแผ่นดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 5, 'เพราะพระเยโฮวาห์ตรัสดังนี้ว่า อย่าเข้าไปในเรือนที่ครวญคร่ํา หรือไปโอดครวญ หรือไปเสียใจด้วย พระเยโฮวาห์ตรัสว่า เพราะเราได้เอาสันติภาพของเราไปจากชนชาตินี้แล้ว ทั้งความเมตตาและกรุณาคุณของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 6, 'ทั้งผู้ใหญ่ผู้น้อยจะตายในแผ่นดินนี้ จะไม่มีใครจัดการฝังเขา จะไม่มีใครมาโอดครวญอาลัยเขา หรือมากรีดตัวหรือมาโกนศีรษะเพื่อเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 7, 'จะไม่มีผู้ใดฉีกตัวเองเพื่อเขาเมื่อไว้ทุกข์ เพื่อจะปลอบโยนเขาเหตุคนที่ตายนั้น เพราะบิดามารดาของเขาจะไม่มีใครมอบถ้วยแห่งความเล้าโลมใจให้เขาดื่ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 8, 'เจ้าอย่าเข้าไปนั่งกินและดื่มกับเขาในเรือนที่มีการเลี้ยง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 9, 'เพราะพระเยโฮวาห์จอมโยธา พระเจ้าแห่งอิสราเอล ตรัสดังนี้ว่า ดูเถิด เราจะกระทําให้เสียงบันเทิงและเสียงรื่นเริง เสียงเจ้าบ่าวและเสียงเจ้าสาว ขาดจากสถานที่นี้ต่อสายตาของเจ้าทั้งหลายและในวันของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 10, 'ต่อมาเมื่อเจ้าบอกบรรดาถ้อยคําเหล่านี้แก่ชนชาตินี้ และเขาทั้งหลายพูดกับเจ้าว่า ‘ทําไมพระเยโฮวาห์จึงทรงประกาศความร้ายใหญ่ยิ่งทั้งสิ้นนี้ให้ตกแก่เรา ความชั่วช้าของเราคืออะไรเล่า เราได้กระทําบาปอะไรต่อพระเยโฮวาห์พระเจ้าของเราเล่า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 11, 'แล้วเจ้าพึงกล่าวแก่เขาทั้งหลายว่า ‘พระเยโฮวาห์ตรัสว่า เพราะบรรพบุรุษของเจ้าได้ละทิ้งเรา และได้ติดตามพระอื่น และได้ปรนนิบัติและนมัสการพระนั้น และได้ละทิ้งเรา และมิได้รักษาราชบัญญัติของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 12, 'และเพราะเจ้าทั้งหลายได้กระทําชั่วร้ายยิ่งเสียกว่าบรรพบุรุษของเจ้า เพราะดูเถิด เจ้าทุกๆคนได้ดําเนินตามความดื้อกระด้างแห่งจิตใจอันชั่วร้ายของตนเอง ปฏิเสธไม่ยอมฟังเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 13, 'เพราะฉะนั้น เราจะเหวี่ยงเจ้าออกเสียจากแผ่นดินนี้เข้าไปในแผ่นดินซึ่งเจ้าหรือบรรพบุรุษของเจ้าไม่รู้จัก และที่นั่นเจ้าจะปรนนิบัติพระอื่นทั้งกลางวันและกลางคืน เพราะเราจะไม่สําแดงพระคุณแก่เจ้าเลย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 14, 'พระเยโฮวาห์ตรัสว่า เพราะฉะนั้น ดูเถิด วันเดือนจะมาถึง เมื่อไม่มีใครกล่าวต่อไปอีกว่า ‘พระเยโฮวาห์ผู้ทรงนําประชาชนอิสราเอลขึ้นมาจากแผ่นดินอียิปต์ทรงพระชนม์อยู่แน่ฉันใด’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 15, 'แต่จะพูดว่า ‘พระเยโฮวาห์ผู้ทรงนําประชาชนอิสราเอลขึ้นมาจากแดนเหนือ และขึ้นมาจากบรรดาประเทศซึ่งพระองค์ได้ทรงขับไล่เขาให้ไปอยู่นั้น ทรงพระชนม์อยู่ฉันใด’ เพราะเราจะนําเขาทั้งหลายกลับมาสู่แผ่นดินของเขาเอง ซึ่งเราได้ยกให้บรรพบุรุษของเขาแล้วนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 16, 'พระเยโฮวาห์ตรัสว่า ดูเถิด เราจะส่งชาวประมงมาเป็นอันมาก และเขาจะจับเขาทั้งหลาย ภายหลังเราจะให้เขาพาพรานมาเป็นอันมาก พรานจะล่าเขาทั้งหลายตามภูเขาทุกแห่งและตามเนินเขาทุกลูกและตามซอกหิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 17, 'เพราะว่า ตาเรามองดูพฤติการณ์ทั้งสิ้นของเขา จะปิดบังไว้จากหน้าเราไม่ได้ และความชั่วช้าของเขาทั้งหลายจะซ่อนพ้นตาเราไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 18, 'และก่อนอื่นเราจะตอบสนองความชั่วช้าและบาปของเขาเป็นสองเท่า เพราะเขาได้กระทําให้แผ่นดินเราเป็นมลทินไป และกระทําให้มรดกของเราเต็มไปด้วยซากของสิ่งที่น่าสะอิดสะเอียนและสิ่งที่น่าเกลียดน่าชังของเขาทั้งหลาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 19, 'โอ ข้าแต่พระเยโฮวาห์ กําลังและที่กําบังเข้มแข็งของข้าพระองค์ เป็นที่ลี้ภัยของข้าพระองค์ในวันยากลําบาก บรรดาประชาชาติจะมาเฝ้าพระองค์จากที่สุดปลายโลก และทูลว่า “บรรพบุรุษของเราไม่ได้รับมรดกอันใด นอกจากสิ่งมุสา สิ่งไร้ค่า และสิ่งซึ่งไม่มีประโยชน์อะไรในตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 20, 'มนุษย์จะสร้างพระไว้สําหรับตนเองได้หรือ สิ่งอย่างนั้นไม่ใช่พระ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 21, '“เพราะฉะนั้น ดูเถิด เราจะกระทําให้เขารู้จักกาลครั้งนี้ เราจะกระทําให้เขารู้จักมือของเราและฤทธานุภาพของเรา และเขาทั้งหลายจะรู้ว่านามของเราคือพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 1, '“บาปของยูดาห์นั้นบันทึกไว้ด้วยปากกาเหล็ก ด้วยปลายเพชรจารึกไว้บนแผ่นแห่งจิตใจของเขา และบนเชิงงอนที่แท่นบูชาของเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 2, 'ฝ่ายลูกหลานของเขาก็ระลึกถึงแท่นบูชาและเหล่าเสารูปเคารพของเขาข้างต้นไม้สดทุกต้นบนเนินเขาสูง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 3, 'โอ ภูเขาที่อยู่กลางทุ่งเอ๋ย เราจะให้บรรดาสิ่งของและทรัพย์สมบัติทั้งสิ้นของเจ้าเป็นของริบ และเราจะนับว่าปูชนียสถานสูงทั้งหลายของเจ้าเป็นความบาปของเจ้า ตลอดทั่วบริเวณชายแดนของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 4, 'เจ้าจะต้องปล่อยมือของเจ้าจากมรดกซึ่งเราได้ยกให้แก่เจ้า และเราจะกระทําให้เจ้าปรนนิบัติศัตรูของเจ้าในแผ่นดินซึ่งเจ้าไม่รู้จัก เพราะเจ้าก่อไฟขึ้นในความโกรธของเราซึ่งจะไหม้อยู่เป็นนิตย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 5, 'พระเยโฮวาห์ตรัสดังนี้ว่า “คนที่วางใจในมนุษย์และให้เนื้อหนังเป็นแขนของเขา และใจของเขาหันออกจากพระเยโฮวาห์ คนนั้นก็เป็นที่สาปแช่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 6, 'เขาจะเป็นเหมือนพุ่มไม้ที่อยู่ในทะเลทราย และจะไม่เห็นความดีอันใดมาถึงเลย เขาจะอาศัยอยู่ในแผ่นดินที่แตกระแหงที่ในถิ่นทุรกันดาร ในแผ่นดินเค็มที่ไม่มีคนอาศัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 7, 'คนที่วางใจในพระเยโฮวาห์ย่อมได้รับพระพร คือผู้ที่ความวางใจของเขาอยู่ในพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 8, 'เขาจะเป็นเหมือนต้นไม้ที่ปลูกไว้ริมน้ํา ซึ่งหยั่งรากของมันออกไปข้างลําน้ํา เมื่อแดดส่องมาถึงก็จะไม่สังเกต เพราะใบของมันเขียวอยู่เสมอ และจะไม่กระวนกระวายในปีที่แห้งแล้ง เพราะมันไม่หยุดที่จะออกผล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 9, 'จิตใจก็เป็นตัวล่อลวงเหนือกว่าสิ่งใดทั้งหมด มันเสื่อมทรามอย่างร้ายทีเดียว ผู้ใดจะรู้จักใจนั้นเล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 10, '“เราคือพระเยโฮวาห์ตรวจค้นดูจิต และทดลองดูใจ เพื่อให้แก่ทุกคนตามพฤติการณ์ของเขา ตามผลแห่งการกระทําของเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 11, 'เหมือนนกกระทากกไข่ แต่ไม่ให้ออกเป็นตัวฉันใด คนที่ได้ความมั่งมีมาอย่างไม่เป็นธรรมก็ฉันนั้น พอถึงกลางวัย มันก็พรากจากคนนั้นเสีย และในตอนปลายของเขา เขาจะเป็นคนโฉดเขลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 12, 'ที่ตั้งแห่งสถานบริสุทธิ์ของเราทั้งหลาย เป็นพระที่นั่งรุ่งเรืองซึ่งตั้งอยู่สูงตั้งแต่เดิมนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 13, 'โอ ข้าแต่พระเยโฮวาห์ ความหวังแห่งอิสราเอล บรรดาคนเหล่านั้นที่ละทิ้งพระองค์จะต้องรับความอับอาย บรรดาคนทั้งปวงที่หันไปจากเราจะต้องจารึกไว้ในแผ่นดินโลก เพราะเขาได้ละทิ้งพระเยโฮวาห์ ผู้เป็นแหล่งน้ําแห่งชีวิตเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 14, 'โอ ข้าแต่พระเยโฮวาห์ ขอทรงรักษาข้าพระองค์ ข้าพระองค์จะได้หาย ขอทรงช่วยข้าพระองค์ให้รอด ข้าพระองค์จึงจะรอด เพราะพระองค์เป็นที่สรรเสริญของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 15, 'ดูเถิด เขาทั้งหลายได้พูดกับข้าพระองค์ว่า “พระวจนะของพระเยโฮวาห์อยู่ที่ไหน ให้มาเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 16, 'ข้าพระองค์มิได้หาโอกาสเลิกเป็นผู้เลี้ยงแกะที่ตามพระองค์ไป ข้าพระองค์ก็ไม่ประสงค์วันแห่งความหายนะ พระองค์ทรงทราบแล้ว สิ่งซึ่งออกมาจากริมฝีปากของข้าพระองค์ก็ถูกต้องต่อพระพักตร์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 17, 'ขออย่าทรงเป็นเหตุให้ข้าพระองค์ครั่นคร้าม พระองค์ทรงเป็นความหวังของข้าพระองค์ในวันร้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 18, 'ผู้ใดข่มเหงข้าพระองค์ ขอให้เขาได้รับความละอาย แต่ขออย่าให้ข้าพระองค์ได้รับความละอาย ขอให้เขาครั่นคร้าม แต่อย่าให้ข้าพระองค์ครั่นคร้าม ขอทรงนําวันร้ายมาตกเหนือเขา ขอทรงทําลายเขาด้วยการทําลายซับซ้อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 19, 'พระเยโฮวาห์ตรัสแก่ข้าพเจ้าดังนี้ว่า “จงไปยืนในประตูสําหรับบุตรแห่งพลเมือง ซึ่งบรรดากษัตริย์แห่งยูดาห์เสด็จเข้า และซึ่งพระองค์เสด็จออก และในประตูทั้งหลายของเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 20, 'และกล่าวแก่เขาทั้งหลายว่า ‘ท่านทั้งหลายผู้เป็นกษัตริย์ของยูดาห์ และบรรดาคนยูดาห์และชาวเยรูซาเล็มทั้งสิ้น ผู้ซึ่งเข้าทางประตูเหล่านี้ จงฟังพระวจนะของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 21, 'พระเยโฮวาห์ตรัสดังนี้ว่า จงระวังเพื่อเห็นแก่ชีวิตของเจ้าทั้งหลาย อย่าได้หาบหามอะไรในวันสะบาโต หรือนําของนั้นเข้าทางบรรดาประตูเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 22, 'และอย่าหาบหามของของเจ้าออกจากบ้านในวันสะบาโต หรือกระทํางานใดๆ แต่จงรักษาวันสะบาโตไว้ให้บริสุทธิ์ ดังที่เราได้บัญชาบรรพบุรุษของเจ้าไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 23, 'ถึงกระนั้นเขาก็ไม่เชื่อฟังหรือเงี่ยหูฟัง แต่กระทําคอของเขาทั้งหลายให้แข็ง เพื่อจะไม่ได้ยินและไม่รับคําสั่งสอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 24, 'พระเยโฮวาห์ตรัสว่า ต่อมาถ้าเจ้าเชื่อฟังเรา และไม่นําภาระใดๆเข้ามาทางประตูเมืองนี้ในวันสะบาโต แต่รักษาวันสะบาโตให้บริสุทธิ์ และไม่กระทํางานในวันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 25, 'แล้วจะมีกษัตริย์และเจ้านาย ผู้ประทับบนบัลลังก์แห่งดาวิดเสด็จเข้าทางประตูทั้งหลายของเมืองนี้ เสด็จมาในรถรบ และบนม้า ทั้งบรรดากษัตริย์และเจ้านายของพระองค์ ทั้งคนยูดาห์และชาวเยรูซาเล็ม และเมืองนี้จะดํารงอยู่เป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 26, 'และประชาชนจะมาจากหัวเมืองแห่งยูดาห์ และจากที่ซึ่งอยู่รอบเยรูซาเล็ม จากแผ่นดินเบนยามิน จากที่ราบ จากเทือกเขา และจากภาคใต้ นําเอาเครื่องเผาบูชา และเครื่องสักการบูชา เครื่องธัญญบูชาและกํายาน และนําเครื่องบูชาแห่งการสรรเสริญมายังนิเวศของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 27, 'แต่ถ้าเจ้าทั้งหลายไม่ฟังเราที่จะรักษาวันสะบาโตให้บริสุทธิ์ และที่จะไม่แบกภาระเข้าทางประตูทั้งหลายของเยรูซาเล็มในวันสะบาโต แล้วเราจะก่อไฟไว้ในประตูเมืองเหล่านั้น และไฟนั้นจะเผาผลาญราชวังทั้งหลายของเยรูซาเล็ม และจะดับก็ไม่ได้’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 1, 'พระวจนะซึ่งมาจากพระเยโฮวาห์ยังเยเรมีย์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 2, '“จงลุกขึ้นไปที่บ้านของช่างหม้อ เราจะให้เจ้าได้ยินถ้อยคําของเราที่นั่น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 3, 'ข้าพเจ้าจึงลงไปที่บ้านของช่างหม้อ และดูเถิด เขากําลังทํางานอยู่ที่แป้นเวียน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 4, 'และภาชนะซึ่งทําด้วยดินก็เสียอยู่ในมือของช่างหม้อ เขาจึงปั้นใหม่ให้เป็นภาชนะอีกลูกหนึ่งตามที่ช่างหม้อเห็นว่าควรทํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 5, 'แล้วพระวจนะของพระเยโฮวาห์มายังข้าพเจ้าว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 6, '“โอ วงศ์วานอิสราเอลเอ๋ย เราจะกระทําแก่เจ้าอย่างที่ช่างหม้อนี้กระทําไม่ได้หรือ พระเยโฮวาห์ตรัสดังนี้แหละ ดูเถิด โอ วงศ์วานอิสราเอลเอ๋ย เจ้าอยู่ในมือของเราอย่างดินเหนียวอยู่ในมือของช่างหม้อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 7, 'ถ้าเวลาใดก็ตามเราประกาศเกี่ยวกับประชาชาติหนึ่งหรือราชอาณาจักรหนึ่งว่า เราจะถอนและพังและทําลายมันเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 8, 'และถ้าประชาชาตินั้น ซึ่งเราได้ลั่นวาจาไว้เกี่ยวข้องด้วย หันเสียจากความชั่วร้ายของตน เราก็จะกลับใจจากความชั่วซึ่งเราได้ตั้งใจจะกระทําแก่ชาตินั้นเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 9, 'และถ้าเวลาใดก็ตาม เราได้ประกาศเกี่ยวกับประชาชาติหนึ่งหรือราชอาณาจักรหนึ่งว่า เราจะสร้างขึ้นและปลูกฝังไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 10, 'และถ้าชาตินั้นได้กระทําชั่วในสายตาของเรา ไม่เชื่อฟังเสียงของเรา เราก็จะกลับใจจากความดีซึ่งเราได้กล่าวไปแล้วว่าเราจะให้ประโยชน์แก่ชาตินั้นเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 11, 'เพราะฉะนั้น คราวนี้จงกล่าวกับคนยูดาห์และชาวเมืองเยรูซาเล็มว่า ‘พระเยโฮวาห์ตรัสดังนี้ว่า ดูเถิด เรากําลังก่อสิ่งร้ายไว้สู้เจ้า และคิดแผนงานอย่างหนึ่งไว้สู้เจ้า ทุกๆคนจงกลับเสียจากทางชั่วของตน และจงซ่อมทางและการกระทําของเจ้าทั้งหลายเสีย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 12, 'แต่เขาทั้งหลายกล่าวว่า ‘เหลวไหล เราจะดําเนินตามแผนงานของเราเอง และต่างจะกระทําตามความดื้อดึงแห่งจิตใจชั่วของตนทุกคน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 13, 'เพราะฉะนั้น พระเยโฮวาห์จึงตรัสดังนี้ว่า จงไปเที่ยวถามดูท่ามกลางประชาชาติว่า ผู้ใดเคยได้ยินเหมือนอย่างนี้บ้าง อิสราเอลพรหมจารีนั้นได้กระทําสิ่งอันน่าหวาดเสียวนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 14, 'คนจะละทิ้งหิมะแห่งภูเขาเลบานอนซึ่งมาจากหน้าผาแห่งทุ่งหรือ ลําธารที่ไหลเย็นจากที่อื่นจะถูกทอดทิ้งหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 15, 'เพราะเหตุว่าประชาชนของเราได้ลืมเราเสีย เขาทั้งหลายจึงเผาเครื่องหอมบูชาสิ่งไร้สาระ ทําให้เขาได้สะดุดในหนทางของเขาในถนนโบราณ และเดินตามทางซอยไม่ไปตามถนนหลวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 16, 'ได้กระทําให้แผ่นดินของเขาทั้งหลายเป็นที่รกร้าง เป็นสิ่งที่เขาเย้ยหยันอยู่เนืองนิตย์ ทุกคนที่ผ่านไปทางนั้นก็ตกตะลึงและสั่นศีรษะของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 17, 'เราจะให้เขากระจัดกระจายออกไปดุจถูกพัดด้วยลมตะวันออกต่อหน้าศัตรู เราจะหันหลังให้เขา ไม่ใช่หันหน้าให้ ในวันแห่งความหายนะของเขานั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 18, 'แล้วเขากล่าวว่า “มาเถิด ให้เราปองร้ายเยเรมีย์ เพราะว่าพระราชบัญญัติจะไม่พินาศไปจากบรรดาปุโรหิต หรือคําปรึกษาย่อมไม่ขาดจากนักปราชญ์ หรือถ้อยคําไม่ขาดจากผู้พยากรณ์ มาเถิด ให้เราโจมตีเขาด้วยลิ้น และอย่าให้เราฟังคําของเขาเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 19, 'โอ ข้าแต่พระเยโฮวาห์ ขอทรงฟังข้าพระองค์ ขอทรงฟังเสียงปรปักษ์ของข้าพระองค์สิ พระเจ้าข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 20, 'ความชั่วเป็นของสําหรับตอบแทนความดีหรือ ถึงกระนั้น เขายังขุดหลุมไว้ปองชีวิตของข้าพระองค์ ขอทรงระลึกว่าข้าพระองค์ยืนเฝ้าพระองค์ทูลขอความดีเพื่อเขา เพื่อจะหันพระพิโรธของพระองค์ไปเสียจากเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 21, 'เพราะฉะนั้น ขอทรงมอบลูกหลานของเขาให้แก่การกันดารอาหาร ให้โลหิตของเขาทั้งหลายไหลออกด้วยอํานาจของดาบ ให้ภรรยาของเขาทั้งหลายขาดบุตร และเป็นหญิงม่าย ขอให้ผู้ชายของเขาประสบความตาย ให้อนุชนของเขาถูกดาบตายในสงคราม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 22, 'ขอให้ได้ยินเสียงร้องมาจากเรือนของเขาทั้งหลาย เมื่อพระองค์ทรงพากองทหารมาปล้นเขาอย่างฉับพลัน เพราะเขาทั้งหลายได้ขุดหลุมไว้ดักข้าพระองค์ และวางบ่วงดักเท้าของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 23, 'แม้กระนั้น ข้าแต่พระเยโฮวาห์ พระองค์ทรงทราบการปองร้ายทั้งสิ้นของเขาที่จะฆ่าข้าพระองค์เสีย ขออย่าทรงลบความชั่วช้าของเขา หรือลบบาปของเขาเสียจากสายพระเนตรของพระองค์ ขอให้เขาถูกคว่ําลงต่อพระพักตร์พระองค์ ขอทรงจัดการเขาทั้งหลายในเวลาแห่งความกริ้วของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 1, 'พระเยโฮวาห์ตรัสดังนี้ว่า “จงไปซื้อเหยือกดินของช่างหม้อมาลูกหนึ่ง แล้วพาผู้ใหญ่บางคนของประชาชนและปุโรหิตอาวุโสบางคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 2, 'ไปที่หุบเขาบุตรชายของฮินโนม ตรงทางเข้าประตูตะวันออก และป่าวร้องถ้อยคําที่เราบอกเจ้าไว้นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 3, 'เจ้าจงว่า ‘โอ ข้าแต่บรรดากษัตริย์แห่งยูดาห์ และชาวกรุงเยรูซาเล็ม ขอทรงฟังพระวจนะของพระเยโฮวาห์ พระเยโฮวาห์จอมโยธา พระเจ้าแห่งอิสราเอลตรัสดังนี้ว่า ดูเถิด เราจะนําเหตุร้ายมาถึงสถานที่นี้ อย่างที่หูของผู้ใดที่ได้ยินจะซ่าไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 4, 'เพราะว่าประชาชนได้ละทิ้งเรา และได้ห่างเหินไปจากสถานที่นี้ และได้เผาเครื่องหอมในที่นี้เพื่อบูชาแก่พระอื่น ผู้ซึ่งตัวเขาเอง หรือบรรพบุรุษของเขา หรือบรรดากษัตริย์ของยูดาห์ไม่รู้จัก และเพราะเขาได้กระทําให้โลหิตของผู้ไม่มีผิดเต็มในที่นี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 5, 'และได้สร้างปูชนียสถานสูงสําหรับพระบาอัล เพื่อจะเผาบุตรชายของเขาเสียในไฟ เป็นเครื่องเผาบูชาแก่พระบาอัล ซึ่งเรามิได้บัญชาหรือให้ประกาศิต หรือได้นึกในใจของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 6, 'ฉะนั้น พระเยโฮวาห์ตรัสว่า ดูเถิด วันเวลาจะมาถึง เมื่อสถานที่นี้จะไม่มีใครเรียกชื่อว่า โทเฟท หรือหุบเขาบุตรชายของฮินโนมอีก แต่เรียกว่า หุบเขาของการฆ่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 7, 'และในสถานที่นี้เราจะกระทําให้แผนงานของยูดาห์และเยรูซาเล็มสูญสิ้นไป และจะกระทําให้เขาทั้งสองล้มลงด้วยดาบต่อหน้าศัตรูของเขาทั้งหลาย และด้วยมือของบรรดาผู้ที่แสวงหาชีวิตของเขา เราจะให้ศพของเขาทั้งหลายเป็นอาหารของนกในอากาศและสัตว์ที่แผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 8, 'และเราจะกระทําให้เมืองนี้เป็นที่รกร้าง เป็นสิ่งที่เขาเย้ยหยัน ทุกคนที่ผ่านไปจะตกตะลึง และเย้ยหยันเพราะภัยพิบัติทั้งสิ้นในเมืองนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 9, 'และเราจะกระทําให้เขาทั้งหลายกินเนื้อของบุตรชายและเนื้อของบุตรสาวของเขา และทุกคนจะกินเนื้อของเพื่อนของเขาในการที่ถูกล้อมและทุกข์ใจ คือที่ซึ่งศัตรูของเขาและผู้ที่แสวงหาชีวิตของเขา ได้ข่มใจเขาทั้งหลาย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 10, 'แล้วเจ้าจงทําเหยือกให้แตกท่ามกลางสายตาของคนที่ไปกับเจ้านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 11, 'และจงกล่าวแก่เขาทั้งหลายว่า ‘พระเยโฮวาห์จอมโยธาตรัสดังนี้ว่า เราจะให้ชนชาตินี้และเมืองนี้แตก เช่นเดียวกับที่คนทําให้ภาชนะของช่างหม้อแตก จนซ่อมแซมไม่ได้อีก เขาจะฝังคนไว้ในโทเฟท จนไม่มีที่อื่นให้ฝังอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 12, 'พระเยโฮวาห์ตรัสว่า เราจะกระทําดังนี้แก่สถานที่นี้ และแก่ชาวเมืองนี้ กระทําเมืองนี้ให้เหมือนโทเฟท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 13, 'บรรดาเรือนแห่งเยรูซาเล็ม และราชวังทั้งหลายแห่งบรรดากษัตริย์ยูดาห์ จะเป็นมลทินเหมือนสถานโทเฟท เพราะเขาเผาเครื่องหอมให้แก่บรรดาบริวารแห่งฟ้าสวรรค์ และเทเครื่องดื่มถวายแก่พระอื่น บนหลังคาของบรรดาบ้านทั้งปวง’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 14, 'แล้วเยเรมีย์ก็มาจากโทเฟท ที่ซึ่งพระเยโฮวาห์ทรงรับสั่งให้ท่านพยากรณ์นั้น และท่านก็ยืนอยู่ในลานพระนิเวศของพระเยโฮวาห์ และกล่าวแก่ประชาชนทั้งปวงว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 15, '“พระเยโฮวาห์จอมโยธา พระเจ้าแห่งอิสราเอล ตรัสว่า ดูเถิด เราจะนําสิ่งร้ายทั้งสิ้นซึ่งเราได้บอกกล่าวไว้ให้ตกอยู่บนเมืองนี้ และบรรดาหัวเมืองทั้งสิ้น เพราะเขาทั้งหลายได้แข็งคอของเขา ปฏิเสธไม่ฟังถ้อยคําของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 1, 'ฝ่ายปาชเฮอร์ปุโรหิต บุตรชายของอิมเมอร์ ผู้เป็นนายใหญ่ในพระนิเวศของพระเยโฮวาห์ ได้ยินว่าเยเรมีย์พยากรณ์ถึงสิ่งเหล่านี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 2, 'ปาชเฮอร์ก็ตีเยเรมีย์ผู้พยากรณ์และจับท่านใส่คา ซึ่งตั้งอยู่ทางประตูเบนยามินด้านบนแห่งพระนิเวศของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 3, 'ต่อมาพอรุ่งขึ้นเมื่อปาชเฮอร์ปลดเยเรมีย์ออกจากคา เยเรมีย์พูดกับท่านว่า “พระเยโฮวาห์มิได้ทรงเรียกชื่อของท่านว่า ปาชเฮอร์ แต่ทรงเรียกว่า มากอร์มิสสะบิบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 4, 'เพราะพระเยโฮวาห์ตรัสดังนี้ว่า ดูเถิด เราจะกระทําเจ้าให้เป็นที่น่าหวาดเสียวต่อตัวเจ้าเอง และต่อมิตรสหายทั้งสิ้นของเจ้า เขาทั้งหลายจะล้มลงด้วยดาบของศัตรูของเขา ขณะที่ตาเจ้ามองดูอยู่ และเราจะมอบยูดาห์ทั้งสิ้นไว้ในมือของกษัตริย์บาบิโลน เขาจะกวาดเอาไปเป็นเชลยยังบาบิโลน และจะฆ่าเสียด้วยดาบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 5, 'ยิ่งกว่านั้นอีกเราจะยกความมั่งคั่งของเมืองนี้ ผลแรงงานทั้งสิ้นและของมีค่าทั้งสิ้นของเมืองนี้ และทรัพย์สมบัติทั้งสิ้นของบรรดากษัตริย์ของยูดาห์ไว้ในมือของศัตรูของเขาทั้งหลาย ผู้ซึ่งจะปล้นและฉุดคร่าและขนเอาเขาเหล่านั้นไปบาบิโลน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 6, 'ส่วนตัวท่านนะ ปาชเฮอร์และบรรดาผู้ที่อาศัยอยู่ในเรือนของท่าน จะต้องไปเป็นเชลย ท่านจะต้องไปยังบาบิโลน และท่านจะตายและถูกฝังไว้ที่นั่น ทั้งท่านและมิตรสหายทั้งสิ้นของท่าน ผู้ซึ่งท่านได้พยากรณ์เท็จแก่เขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 7, 'โอ ข้าแต่พระเยโฮวาห์ พระองค์ทรงหลอกลวงข้าพระองค์ และข้าพระองค์ก็ถูกหลอกลวง พระองค์ทรงมีกําลังยิ่งกว่าข้าพระองค์ และพระองค์ก็ชนะ ข้าพระองค์เป็นที่ให้เขาหัวเราะวันยังค่ํา ทุกคนเยาะเย้ยข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 8, 'เพราะตั้งแต่ข้าพระองค์พูด ข้าพระองค์ก็ร้องให้ช่วย ข้าพระองค์ตะโกนว่า “ความทารุณและการปล้น” เพราะว่าพระวจนะของพระเยโฮวาห์ได้เป็นเหตุให้ข้าพระองค์เป็นที่ตําหนิและเยาะเย้ยตลอดวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 9, 'แล้วข้าพระองค์กล่าวว่า “ข้าพเจ้าจะไม่อ้างถึงพระองค์หรือกล่าวในพระนามของพระองค์อีก” แต่พระวจนะของพระองค์อยู่ในใจของข้าพระองค์เหมือนไฟไหม้ อัดอยู่ในกระดูกของข้าพระองค์ และข้าพระองค์ก็อ่อนเปลี้ยที่ต้องอัดไว้ และข้าพระองค์ก็อัดไว้ไม่ไหว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 10, 'เพราะข้าพระองค์ได้ยินเสียงซุบซิบเป็นอันมาก ความหวาดเสียวอยู่รอบทุกด้าน เขากล่าวว่า “ใส่ความเขา ให้เราใส่ความเขา” มิตรสหายที่คุ้นเคยทั้งสิ้นของข้าพระองค์เฝ้าดูความล่มจมของข้าพระองค์ กล่าวว่า “ชะรอยเขาจะถูกหลอกลวงแล้วเราจะชนะเขาได้ และจะทําการแก้แค้นเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 11, 'แต่พระเยโฮวาห์ทรงอยู่ข้างข้าพเจ้าดังนักรบที่น่ากลัว เพราะฉะนั้น ผู้ข่มเหงข้าพเจ้าจะสะดุด เขาจะไม่ชนะข้าพเจ้า เขาจะขายหน้ามาก เพราะเขาจะไม่เจริญขึ้น ความอัปยศอดสูเป็นนิตย์ของเขานั้นจะไม่มีวันลืม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 12, 'โอ ข้าแต่พระเยโฮวาห์จอมโยธา ผู้ทรงทดลองคนชอบธรรม ผู้ทอดพระเนตรทั้งใจและจิต ขอให้ข้าพระองค์ได้เห็นการแก้แค้นของพระองค์เหนือเขาทั้งหลาย เพราะข้าพระองค์ได้ทูลเสนอคดีของข้าพระองค์แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 13, 'จงร้องเพลงถวายพระเยโฮวาห์ จงสรรเสริญพระเยโฮวาห์ เพราะว่าพระองค์ทรงช่วยชีวิตของผู้ขัดสนให้พ้นจากมือของผู้กระทําความชั่วร้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 14, 'ขอให้วันที่ข้าพเจ้าเกิดมานั้นถูกสาปแช่ง อย่าให้วันที่มารดาของข้าพเจ้าคลอดข้าพเจ้าได้รับพร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 15, 'ขอให้ชายคนนั้นถูกสาปแช่ง คือคนที่เขานําข่าวไปบอกบิดาข้าพเจ้าว่า “บุตรชายคนหนึ่งเกิดมาแก่ท่านแล้ว” อันกระทําให้บิดามีความยินดีมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 16, 'ขอให้ชายคนนั้นเหมือนกับบรรดาเมืองซึ่งพระเยโฮวาห์ทรงคว่ําเสียและมิได้ทรงกลับพระทัย ขอให้เขาได้ยินเสียงร้องให้ช่วยในเวลาเช้า และให้ได้ยินเสียงโวยวายในเวลาเที่ยง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 17, 'เพราะเขามิได้ฆ่าข้าพเจ้าเสียตั้งแต่ในครรภ์ ให้มารดาของข้าพเจ้าเป็นหลุมฝังศพของข้าพเจ้า และครรภ์นั้นจะได้โตอยู่เป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 18, 'ทําไมข้าพเจ้าจึงออกมาจากครรภ์มาเห็นความลําบากและความทุกข์ และวันคืนของข้าพเจ้าก็สิ้นเปลืองไปด้วยความอับอาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 1, 'พระวจนะซึ่งมาจากพระเยโฮวาห์ถึงเยเรมีย์ เมื่อกษัตริย์เศเดคียาห์ทรงใช้ให้ปาชเฮอร์บุตรชายมัลคิยาห์ และเศฟันยาห์ปุโรหิตบุตรชายมาอาเสอาห์ไปหาเยเรมีย์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 2, '“ขอจงทูลถามพระเยโฮวาห์เพื่อเรา เพราะเนบูคัดเนสซาร์กษัตริย์บาบิโลนกําลังทําสงครามกับเรา ชะรอยพระเยโฮวาห์จะทรงกระทํากับเราตามบรรดาราชกิจอันมหัศจรรย์ของพระองค์ และจะทรงกระทําให้เนบูคัดเนสซาร์ถอยทัพไปจากเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 3, 'แล้วเยเรมีย์บอกเขาทั้งสองว่า “ท่านจงทูลแก่เศเดคียาห์ดังนี้ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 4, '‘พระเยโฮวาห์พระเจ้าแห่งอิสราเอลตรัสดังนี้ว่า ดูเถิด เราจะหันกลับซึ่งยุทโธปกรณ์อันอยู่ในมือของเจ้า และซึ่งเจ้าใช้สู้รบกับกษัตริย์แห่งบาบิโลนและกับชนเคลเดียซึ่งกําลังล้อมเจ้าอยู่นอกกําแพง และเราจะรวบรวมมันมาไว้ในใจกลางเมืองนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 5, 'เราเองจะต่อสู้กับเจ้าด้วยมือที่เหยียดออกและด้วยแขนที่แข็งแรง ด้วยความกริ้ว ด้วยความเกรี้ยวกราดและพิโรธมากยิ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 6, 'และเราจะโจมตีชาวกรุงนี้ ทั้งคนและสัตว์ แล้วก็จะตายลงด้วยโรคระบาดขนาดหนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 7, 'พระเยโฮวาห์ตรัสว่า ภายหลังเราจะมอบเศเดคียาห์กษัตริย์ของยูดาห์ และบรรดาข้าราชการของเขา และประชาชนเมืองนี้ซึ่งรอดตายจากโรคระบาด ดาบและการกันดารอาหารไว้ในมือของเนบูคัดเนสซาร์กษัตริย์แห่งบาบิโลน และมอบไว้ในมือของศัตรูของเขาทั้งหลาย ในมือของคนเหล่านั้นที่แสวงหาชีวิตของเขา ท่านจะฟันเขาเสียด้วยคมดาบ ท่านจะไม่สงสารเขาทั้งหลาย หรือไว้ชีวิตเขา หรือมีความเมตตาต่อเขา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 8, 'และเจ้าจงพูดกับชนชาตินี้ว่า ‘พระเยโฮวาห์ตรัสดังนี้ว่า ดูเถิด เราได้ตั้งวิถีแห่งชีวิตและทางแห่งความตายไว้ต่อหน้าเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 9, 'คนที่อยู่ในเมืองนี้จะตายเสียด้วยดาบ ด้วยการกันดารอาหารและด้วยโรคระบาด แต่ผู้ที่ออกไปยอมมอบตัวกับชนเคลเดียผู้ตั้งล้อมอยู่นั้น ก็จะมีชีวิตอยู่ได้ และจะมีชีวิตของตนเป็นบําเหน็จแห่งการสงคราม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 10, 'พระเยโฮวาห์ตรัสว่า เพราะเราได้มุ่งหน้าต่อสู้เมืองนี้ด้วยความร้ายไม่ใช่ด้วยความดี คือเมืองนี้จะถูกมอบไว้ในมือของกษัตริย์แห่งบาบิโลน และท่านจะเผามันเสียด้วยไฟ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 11, 'จงกล่าวต่อวงศ์วานของกษัตริย์ยูดาห์ว่า ‘จงฟังพระวจนะของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 12, 'โอ วงศ์วานดาวิดเอ๋ย พระเยโฮวาห์ตรัสดังนี้ว่า จงให้ความยุติธรรมในเวลาเช้า จงช่วยผู้ที่ถูกปล้นให้พ้นจากมือผู้ที่บีบบังคับ เกรงว่าความพิโรธของเราจะออกไปเหมือนไฟ และเผาไหม้อย่างที่ไม่มีใครดับได้ เพราะการกระทําอันชั่วร้ายของเจ้าทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 13, 'โอ ชาวที่ลุ่มเอ๋ย ดูเถิด เราต่อสู้เจ้า ศิลาแห่งที่ราบเอ๋ย พระเยโฮวาห์ตรัสดังนี้แหละ พวกเจ้าผู้กล่าวว่า “ใครจะลงมาต่อสู้กับเรา หรือใครจะเข้ามาในที่อาศัยของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 14, 'พระเยโฮวาห์ตรัสว่า เราจะลงโทษเจ้าทั้งหลายตามผลแห่งการกระทําของเจ้า เราจะก่อไฟไว้ในป่าของเมืองนั้น และไฟนั้นจะเผาผลาญสิ่งต่างๆที่อยู่รอบเมืองนั้นสิ้น’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 1, 'พระเยโฮวาห์ตรัสดังนี้ว่า จงลงไปยังราชสํานักของกษัตริย์ยูดาห์ และกล่าวถ้อยคําเหล่านี้ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 2, 'ว่า “โอ ข้าแต่กษัตริย์แห่งยูดาห์ ผู้ประทับบนพระที่นั่งของดาวิด จงฟังพระวจนะของพระเยโฮวาห์ ทั้งตัวท่าน ข้าราชการของท่าน และประชาชนของท่านผู้เข้ามาในประตูเมืองนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 3, 'พระเยโฮวาห์ตรัสดังนี้ว่า จงกระทําความยุติธรรมและความชอบธรรม จงช่วยผู้ที่ถูกปล้นให้พ้นมือของผู้ที่บีบบังคับ และอย่าได้กระทําความผิดหรือความทารุณแก่ชนต่างด้าว ลูกกําพร้าพ่อ และหญิงม่าย หรือหลั่งโลหิตที่ไร้ความผิดให้ถึงตายในสถานที่นี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 4, 'เพราะถ้าท่านกระทําสิ่งนี้จริงๆแล้วจะมีกษัตริย์ผู้ประทับบนพระที่นั่งของดาวิดเข้ามาทางประตูของพระราชวังนี้ เสด็จมาโดยรถรบและม้า ทั้งตัวกษัตริย์ บรรดาข้าราชการและประชาชนของท่านนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 5, 'แต่ถ้าท่านไม่ฟังถ้อยคําเหล่านี้ พระเยโฮวาห์ตรัสว่า เราปฏิญาณต่อตัวของเราเองว่า ราชสํานักนี้จะเป็นที่รกร้าง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 6, 'เพราะพระเยโฮวาห์ตรัสดังนี้แก่ราชสํานักแห่งกษัตริย์ของยูดาห์ ว่า “เจ้าเป็นเหมือนกิเลอาดแก่เรา เป็นดังยอดภูเขาเลบานอน ถึงกระนั้น เราจะกระทําเจ้าให้เป็นถิ่นทุรกันดารแน่ เป็นเมืองที่ไม่มีคนอาศัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 7, 'เราจะเตรียมผู้ทําลายไว้ต่อสู้เจ้า ต่างก็มีอาวุธของตน และเขาทั้งหลายจะตัดต้นสนสีดาร์อย่างดีของเจ้าลง และโยนเข้าในไฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 8, 'และประชาชาติเป็นอันมากจะผ่านเมืองนี้ไป และทุกคนจะพูดกับเพื่อนบ้านของตนว่า ‘ทําไมพระเยโฮวาห์จึงทรงกระทําเช่นนี้แก่เมืองใหญ่นี้’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 9, 'และเขาทั้งหลายจะตอบว่า ‘เพราะเขาทั้งหลายได้ละทิ้งพันธสัญญาของพระเยโฮวาห์พระเจ้าของเขา และนมัสการกับปรนนิบัติพระอื่น’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 10, 'อย่าร้องไห้อาลัยแก่ผู้ที่ตายไป อย่าครวญคร่ําด้วยเขาเลย แต่จงร้องไห้ร่ําไรอาลัยผู้ที่ไปแล้ว เพราะเขาจะไม่ได้กลับมาเห็นบ้านเกิดเมืองนอนของเขาอีกเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 11, 'เพราะพระเยโฮวาห์ตรัสดังนี้แหละเกี่ยวกับชัลลูม บุตรชายโยสิยาห์ กษัตริย์แห่งยูดาห์ ผู้ซึ่งครองราชย์แทนโยสิยาห์ราชบิดา และผู้ที่ไปจากสถานที่นี้ “ท่านจะไม่ได้กลับมาที่นี่อีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 12, 'ท่านจะสิ้นชีวิตในที่ซึ่งเขาจับท่านไปเป็นเชลย และท่านจะไม่เห็นแผ่นดินนี้อีกเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 13, '“วิบัติแก่เขาผู้สร้างวังของตนด้วยความอธรรม และสร้างห้องชั้นบนไว้ด้วยความอยุติธรรม ผู้ที่ทําให้เพื่อนบ้านของเขาปรนนิบัติเขาโดยไม่ได้อะไรเลย และมิได้จ่ายค่าจ้างให้แก่เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 14, 'ผู้กล่าวว่า ‘เราจะสร้างวังใหญ่อยู่เอง กับมีห้องชั้นบนกว้างขวาง และเจาะหน้าต่างให้ห้องนั้น และบุฝาผนังด้วยไม้สนสีดาร์และทาด้วยสีแดงเข้ม’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 15, 'เจ้าคิดว่าเจ้าจะครองราชสมบัติ เพราะเจ้าอวดไม้สนสีดาร์กันหรือ ราชบิดาของเจ้ามิได้กินและดื่ม และกระทําความยุติธรรมและความเที่ยงธรรมดอกหรือ ฝ่ายราชบิดาก็อยู่เย็นเป็นสุข');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 16, 'เขาพิพากษาคดีของคนจนและคนขัดสน เขาก็อยู่เย็นเป็นสุข ทําอย่างนี้เป็นการรู้จักเรามิใช่หรือ” พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 17, '“แต่เจ้ามีตาและใจไว้เพื่อความโลภ เพื่อหลั่งโลหิตที่ไร้ความผิดให้ถึงตาย และเพื่อปฏิบัติการบีบบังคับและความทารุณ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 18, 'เพราะฉะนั้น พระเยโฮวาห์จึงตรัสดังนี้เกี่ยวกับเยโฮยาคิม ราชบุตรของโยสิยาห์กษัตริย์แห่งยูดาห์ ว่า “เขาทั้งหลายจะไม่โอดครวญอาลัยเขาว่า ‘อนิจจา พี่ชายเอ๋ย’ หรือ ‘อนิจจา พี่สาวเอ๋ย’ เขาทั้งหลายจะไม่โอดครวญอาลัยเขาว่า ‘อนิจจา พระองค์ท่าน’ หรือ ‘อนิจจา ความสง่างามของพระองค์ท่าน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 19, 'ท่านจะถูกฝังไว้อย่างฝังลา คือถูกลากไปโยนทิ้งไว้ข้างนอกประตูเมืองเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 20, 'จงขึ้นไปที่เลบานอน และร้องไห้ และจงเปล่งเสียงของเจ้าในเมืองบาชาน จงร้องจากทางผ่านข้างนอก เพราะว่าคนรักทั้งสิ้นของเจ้าถูกทําลายเสียแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 21, 'เราได้พูดกับเจ้าเมื่อเจ้าอยู่เย็นเป็นสุข แต่เจ้ากล่าวว่า ‘เราจะไม่ฟัง’ นี่เป็นวิธีการของเจ้าตั้งแต่ยังหนุ่มๆ คือเจ้าไม่เชื่อฟังเสียงของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 22, 'ลมจะทําลายผู้เลี้ยงแกะทั้งสิ้นของเจ้า และบรรดาคนรักของเจ้าจะไปเป็นเชลย แล้วเจ้าจะอับอายขายหน้าเป็นแน่เนื่องด้วยความชั่วทั้งสิ้นของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 23, 'โอ ชาวเมืองเลบานอนเอ๋ย ที่สร้างรังอยู่ท่ามกลางไม้สนสีดาร์ เจ้าจะได้รับความกรุณาสักเท่าใดเมื่อความเจ็บปวดมาเหนือเจ้า อย่างความเจ็บปวดของหญิงที่คลอดบุตร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 24, 'พระเยโฮวาห์ตรัสว่า “เรามีชีวิตอยู่ตราบใด แม้ว่าโคนิยาห์ ราชบุตรของเยโฮยาคิม กษัตริย์แห่งยูดาห์ เป็นแหวนตราอยู่ที่มือขวาของเรา ถึงกระนั้นเราจะถอดออกเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 25, 'และมอบเจ้าไว้ในมือของคนเหล่านั้นที่แสวงหาชีวิตของเจ้า ในมือของคนเหล่านั้นซึ่งพวกเจ้ากลัวหน้าตาของเขา คือว่าในมือของเนบูคัดเนสซาร์กษัตริย์แห่งบาบิโลน และในมือของคนเคลเดีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 26, 'เราจะเหวี่ยงเจ้าและมารดาผู้คลอดเจ้าไปยังอีกประเทศหนึ่ง ที่ซึ่งเจ้ามิได้เกิดที่นั่น และเจ้าจะตายที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 27, 'แต่แผ่นดินซึ่งเขาอาลัยอยากจะกลับนั้น เขาจะไม่ได้กลับไปสู่ที่นั่นได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 28, 'โคนิยาห์ชายผู้นี้เป็นรูปเคารพที่ถูกดูหมิ่นและแตกหรือ เป็นภาชนะที่ไม่มีใครชอบหรือ ทําไมตัวเขาและเชื้อสายของเขาจึงถูกเหวี่ยง และถูกโยนเข้าในแผ่นดินซึ่งเขาทั้งหลายไม่รู้จัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 29, 'โอ แผ่นดิน แผ่นดิน แผ่นดินเอ๋ย จงฟังพระวจนะของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 30, 'พระเยโฮวาห์ตรัสดังนี้ว่า “จงเขียนลงว่าชายคนนี้ไม่มีบุตร เป็นชายซึ่งไม่เจริญขึ้นในชั่วชีวิตของเขา เพราะไม่มีคนแห่งเชื้อสายของเขาสักคนหนึ่งที่จะเจริญขึ้น ในการประทับบนพระที่นั่งของดาวิด และปกครองในยูดาห์อีก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 1, 'พระเยโฮวาห์ตรัสว่า “วิบัติจงมีแก่ผู้เลี้ยงแกะผู้ทําลายและกระจายแกะแห่งลานหญ้าของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 2, 'เพราะฉะนั้น พระเยโฮวาห์พระเจ้าแห่งอิสราเอลตรัสกับผู้เลี้ยงแกะผู้ดูแลประชาชนของเราดังนี้ว่า “เจ้าทั้งหลายได้กระจายฝูงแกะของเรา และได้ขับไล่มันไปเสีย และเจ้ามิได้เอาใจใส่มัน” พระเยโฮวาห์ตรัสว่า “ดูเถิด เราจะลงโทษเจ้าเพราะการกระทําที่ชั่วของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 3, 'แล้วเราจะรวบรวมฝูงแกะของเราที่เหลืออยู่ออกจากประเทศทั้งปวงซึ่งเราได้ขับไล่ให้เขาไปอยู่นั้น และจะนําเขากลับมายังคอกของเขา เขาจะมีลูกดกและทวีมากขึ้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 4, 'พระเยโฮวาห์ตรัสว่า “เราจะตั้งผู้เลี้ยงแกะไว้เหนือเขา ผู้จะเลี้ยงดูเขา และเขาทั้งหลายจะไม่กลัวอีกเลย หรือครั่นคร้าม หรือจะไม่ขาดไปเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 5, 'พระเยโฮวาห์ตรัสว่า “ดูเถิด วันเวลาจะมาถึง เมื่อเราจะเพาะอังกูรชอบธรรมให้ดาวิด และกษัตริย์องค์หนึ่งจะทรงครอบครองและเจริญขึ้น และจะทรงประทานความยุติธรรมและความเที่ยงธรรมในแผ่นดินนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 6, 'ในสมัยของท่าน ยูดาห์จะรอดได้ และอิสราเอลจะอาศัยอยู่อย่างปลอดภัย และนี่จะเป็นนามซึ่งเราจะเรียกท่าน คือ พระเยโฮวาห์เป็นความชอบธรรมของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 7, 'พระเยโฮวาห์ตรัสว่า “เพราะฉะนั้น ดูเถิด วันเวลาจะมาถึง เมื่อคนของเขาจะไม่กล่าวอีกต่อไปว่า ‘พระเยโฮวาห์ทรงพระชนม์อยู่ตราบใด ผู้ซึ่งได้นําประชาชนอิสราเอลออกมาจากแผ่นดินอียิปต์’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 8, 'แต่จะว่า ‘พระเยโฮวาห์ทรงพระชนม์อยู่ตราบใด ผู้ซึ่งได้นําและพาเชื้อสายแห่งวงศ์วานอิสราเอลออกมาจากแดนเหนือ’ และออกมาจากประเทศทั้งปวงที่เราขับไล่ให้ไปอยู่นั้น แล้วเขาทั้งหลายจะได้อาศัยอยู่ในแผ่นดินของเขาเอง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 9, 'เกี่ยวกับเรื่องบรรดาผู้พยากรณ์มีว่า ใจของข้าเป็นทุกข์อยู่ภายในข้า และกระดูกทั้งสิ้นของข้าก็สั่น ข้าเป็นเหมือนคนเมา ข้าเป็นเหมือนคนหงําด้วยเหล้าองุ่น เนื่องด้วยพระเยโฮวาห์ และเนื่องด้วยพระวจนะแห่งความบริสุทธิ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 10, 'เพราะว่า แผ่นดินนั้นเต็มไปด้วยคนล่วงประเวณี ด้วยเหตุคําสาปแช่งแผ่นดินนั้นก็ไว้ทุกข์ และลานหญ้าในถิ่นทุรกันดารก็แห้งไป วิถีของเขาทั้งหลายก็ชั่วช้า และอํานาจของเขาทั้งหลายก็ไม่เป็นธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 11, 'พระเยโฮวาห์ตรัสว่า “ทั้งผู้พยากรณ์และปุโรหิตก็อธรรม ถึงแม้ว่าในนิเวศของเรา เราก็ได้เห็นความชั่วของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 12, 'เพราะฉะนั้น หนทางของเขาทั้งหลายจะเป็นเหมือนทางลื่นในความมืดแก่เขา เขาจะถูกขับไล่เข้าไปและล้มลงในนั้น เพราะเราจะนําเหตุร้ายมาเหนือเขาในปีแห่งการลงโทษเขา” พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 13, '“เราได้เห็นความโง่เขลาในบรรดาผู้พยากรณ์แห่งสะมาเรีย เขาได้พยากรณ์ในนามของพระบาอัล และได้ทําให้อิสราเอลประชาชนของเราหลงไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 14, 'แต่ในผู้พยากรณ์แห่งเยรูซาเล็ม เราได้เห็นสิ่งอันน่าหวาดเสียว เขาล่วงประเวณีและดําเนินอยู่ในความมุสา เขาทั้งหลายหนุนกําลังมือของผู้กระทําความชั่ว จึงไม่มีผู้หนึ่งผู้ใดหันจากความชั่วของเขา เขาทุกคนกลายเป็นเหมือนเมืองโสโดมแก่เรา และชาวเมืองนั้นก็เหมือนเมืองโกโมราห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 15, 'เพราะฉะนั้น พระเยโฮวาห์จอมโยธาจึงตรัสเกี่ยวกับเรื่องผู้พยากรณ์เหล่านั้นว่า “ดูเถิด เราจะเลี้ยงเขาด้วยบอระเพ็ด และให้น้ําดีหมีเขาดื่ม เพราะว่าความอธรรมได้ออกไปทั่วแผ่นดินนี้จากผู้พยากรณ์แห่งเยรูซาเล็ม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 16, 'พระเยโฮวาห์จอมโยธาตรัสดังนี้ว่า “อย่าฟังถ้อยคําของผู้พยากรณ์ที่พยากรณ์ให้ท่านฟัง เขากระทําให้ท่านไร้สาระ เขากล่าวถึงนิมิตแห่งใจของเขาเอง มิใช่จากพระโอษฐ์ของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 17, 'เขายังพูดกับคนที่ดูหมิ่นเราว่า ‘พระเยโฮวาห์ได้ตรัสว่า ท่านจะสุขสบาย’ และแก่ทุกคนที่ดําเนินตามความดื้อกระด้างแห่งจิตใจของตนเอง เขาทั้งหลายกล่าวว่า ‘จะไม่มีเหตุร้ายมาเหนือเจ้า’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 18, 'เพราะว่าผู้ใดเล่าที่ได้ยืนอยู่ในคําตักเตือนของพระเยโฮวาห์ ที่จะพิเคราะห์เห็นและฟังพระวจนะของพระองค์ หรือผู้ใดที่เชื่อฟังพระวจนะของพระองค์และคอยฟัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 19, 'ดูเถิด นั่นลมหมุนของพระเยโฮวาห์ได้ออกไปแล้วด้วยพระพิโรธ เป็นลมหมุนอย่างรุนแรง มันจะตกหนักบนศีรษะของคนชั่ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 20, 'ความกริ้วของพระเยโฮวาห์จะไม่หันกลับ จนกว่าพระองค์จะทรงกระทําให้สําเร็จ และจนกว่าพระองค์ทรงกระทําตามพระเจตนาแห่งพระหฤทัยของพระองค์ ในวันหลังๆเจ้าทั้งหลายจะเข้าใจเรื่องนี้แจ่มแจ้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 21, '“เรามิได้ใช้ผู้พยากรณ์เหล่านั้น แต่เขาทั้งหลายยังวิ่งไป เราไม่ได้พูดกับเขาทั้งหลาย แต่เขาทั้งหลายยังพยากรณ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 22, 'แต่ถ้าเขาทั้งหลายได้ยืนอยู่ในคําตักเตือนของเรา แล้วเขาจะได้ป่าวร้องถ้อยคําของเราต่อประชาชนของเรา และเขาทั้งหลายจะได้ให้ประชาชนหันกลับจากทางชั่วของเขาแล้ว และหันกลับจากความชั่วร้ายในการกระทําของเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 23, 'พระเยโฮวาห์ตรัสว่า “เราเป็นพระเจ้าใกล้แค่คืบ มิใช่พระเจ้าที่อยู่ไกลด้วยดอกหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 24, 'พระเยโฮวาห์ตรัสว่า “คนใดจะซ่อนจากเราไปอยู่ในที่ลับเพื่อเราจะมิได้เห็นเขาได้หรือ” พระเยโฮวาห์ตรัสว่า “เรามิได้อยู่เต็มฟ้าสวรรค์และโลกดอกหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 25, 'เราได้ยินผู้พยากรณ์ ผู้ซึ่งพยากรณ์เรื่องเท็จในนามของเรา ได้กล่าวแล้วว่า ‘ข้าพเจ้าฝันไป ข้าพเจ้าฝันไป’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 26, 'นานสักเท่าใดที่คํามุสาจะอยู่ในใจของผู้พยากรณ์ ซึ่งพยากรณ์เรื่องเท็จ และผู้พยากรณ์ตามการหลอกลวงแห่งจิตใจของเขาเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 27, 'ผู้ซึ่งคิดว่าจะกระทําให้ประชาชนของเราลืมนามของเราโดยความฝันของเขาทั้งหลาย ซึ่งเขาเล่าสู่กันและกันฟัง อย่างกับบรรพบุรุษของเขาลืมนามของเราไปติดตามพระบาอัล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 28, 'จงให้ผู้พยากรณ์ที่ฝันเล่าความฝัน แต่ให้คนที่มีถ้อยคําของเรากล่าวถ้อยคําของเราอย่างสุจริต” พระเยโฮวาห์ตรัสว่า “ฟางข้าวมีอะไรบ้างที่เหมือนข้าวสาลี”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 29, 'พระเยโฮวาห์ตรัสว่า “ถ้อยคําของเราไม่เหมือนไฟหรือ หรือเหมือนค้อนที่ทุบหินให้แตกเป็นชิ้นๆ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 30, 'พระเยโฮวาห์ตรัสว่า “เพราะฉะนั้น ดูเถิด เราต่อสู้กับบรรดาผู้พยากรณ์ ผู้ขโมยถ้อยคําของเราจากกันและกัน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 31, 'พระเยโฮวาห์ตรัสว่า “ดูเถิด เราต่อสู้กับบรรดาผู้พยากรณ์ ผู้ใช้ลิ้นของเขากล่าวว่า ‘พระเจ้าตรัสว่า’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 32, 'พระเยโฮวาห์ตรัสว่า “ดูเถิด เราต่อสู้คนเหล่านั้นที่พยากรณ์ความฝันเท็จ และผู้ซึ่งบอกและนําประชาชนของเราให้หลงไปโดยคํามุสาและคําโอ้อวดของเขา เมื่อเรามิได้ใช้เขาหรือสั่งเขา เพราะฉะนั้นเขาจึงไม่เป็นประโยชน์แก่ชนชาตินี้อย่างใดเลย” พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 33, '“เมื่อมีประชาชนคนหนึ่งคนใด หรือผู้พยากรณ์คนใด หรือปุโรหิตคนใดถามเจ้าว่า ‘อะไรเป็นภาระของพระเยโฮวาห์’ เจ้าจงตอบเขาว่า ‘พระเยโฮวาห์ตรัสว่า อะไรเป็นภาระหรือ เราก็จะโยนเจ้าไปเสีย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 34, 'และส่วนผู้พยากรณ์ ปุโรหิตหรือประชาชนผู้หนึ่งผู้ใดซึ่งพูดว่า ‘ภาระของพระเยโฮวาห์’ เราจะลงโทษผู้นั้นและครัวเรือนของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 35, 'เจ้าทั้งหลายจงพูดดังนี้ คือทุกคนพูดกับเพื่อนบ้านของตน และทุกคนพูดกับพี่น้องของตนว่า ‘พระเยโฮวาห์ตอบว่ากระไร’ หรือ ‘พระเยโฮวาห์ทรงลั่นวาจาว่ากระไร’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 36, 'แต่เจ้าทั้งหลายอย่าเอ่ยว่า ‘ภาระของพระเยโฮวาห์’ อีกเลย เพราะว่าภาระนั้นเป็นคําของแต่ละคน ด้วยว่าเจ้าได้ผันแปรพระวจนะของพระเจ้าผู้ทรงพระชนม์อยู่ พระเยโฮวาห์จอมโยธาพระเจ้าของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 37, 'เจ้าจงกล่าวกับผู้พยากรณ์ดังนี้ว่า ‘พระเยโฮวาห์ทรงตอบท่านว่ากระไร’ หรือ ‘พระเยโฮวาห์ทรงลั่นวาจาว่ากระไร’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 38, 'แต่ถ้าเจ้าทั้งหลายพูดว่า ‘ภาระของพระเยโฮวาห์’” พระเยโฮวาห์ตรัสดังนี้ว่า “เพราะเจ้าทั้งหลายได้กล่าวคําเหล่านี้ว่า ‘ภาระของพระเยโฮวาห์’ เมื่อเราใช้ไปหาเจ้าทั้งหลาย เราว่า เจ้าอย่าพูดว่า ‘ภาระของพระเยโฮวาห์’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 39, 'เพราะฉะนั้น ดูเถิด เราจะลืมเจ้าทั้งหลายเสียเป็นแน่ และโยนเจ้าไปเสียจากหน้าเรา ทั้งเจ้าและเมืองซึ่งเราได้ให้แก่เจ้าและแก่บรรพบุรุษของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 40, 'และเราจะนําความถูกตําหนิเป็นนิตย์และความอายเนืองนิตย์มาเหนือเจ้าทั้งหลาย ซึ่งจะลืมเสียไม่ได้เลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 1, 'หลังจากเนบูคัดเนสซาร์กษัตริย์แห่งบาบิโลนได้จับเยโคนิยาห์ราชบุตรของเยโฮยาคิมกษัตริย์แห่งยูดาห์ไปเป็นเชลยเสียจากเยรูซาเล็ม พร้อมกับเจ้านายแห่งยูดาห์ ทั้งพวกช่างไม้และช่างเหล็ก และนําเขามายังกรุงบาบิโลนแล้ว พระเยโฮวาห์ก็ทรงสําแดงนิมิตแก่ข้าพเจ้าดังนี้ ดูเถิด มีกระจาดสองลูกใส่มะเดื่อ วางไว้หน้าพระวิหารของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 2, 'กระจาดลูกหนึ่งมีมะเดื่ออย่างดีนัก เหมือนมะเดื่อที่สุกต้นฤดู แต่กระจาดอีกลูกหนึ่งนั้นมีมะเดื่ออย่างเลวทีเดียว เลวจนรับประทานไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 3, 'และพระเยโฮวาห์ตรัสแก่ข้าพเจ้าว่า “เยเรมีย์เอ๋ย เจ้าเห็นอะไร” ข้าพเจ้าทูลตอบว่า “เห็นมะเดื่อที่ดีก็ดีมาก และที่เลวก็เลวมาก เลวจนรับประทานไม่ได้ พระเจ้าข้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 4, 'แล้วพระวจนะของพระเยโฮวาห์มาถึงข้าพเจ้าอีกว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 5, '“พระเยโฮวาห์ พระเจ้าแห่งอิสราเอล ตรัสดังนี้ว่า ก็เหมือนอย่างมะเดื่อที่ดีเหล่านี้แหละ เราจะถือว่าพวกเหล่านั้นที่ถูกกวาดไปจากยูดาห์ยังดีอยู่ คือผู้ที่เราได้ส่งไปจากสถานที่นี้ไปสู่แผ่นดินของชาวเคลเดีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 6, 'เราจะตั้งตาของเราดูเขาเพื่อจะกระทําความดี และเราจะพาเขาทั้งหลายกลับมายังแผ่นดินนี้อีก เราจะสร้างเขาทั้งหลายขึ้น และจะไม่รื้อลง เราจะปลูกฝังเขาและไม่ถอนเขาเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 7, 'เราจะให้จิตใจแก่เขาที่จะรู้จักเราว่า เราคือพระเยโฮวาห์ และเขาทั้งหลายจะเป็นประชาชนของเรา และเราจะเป็นพระเจ้าของเขา เพราะเขาทั้งหลายจะกลับมาหาเราด้วยความเต็มใจ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 8, 'แต่พระเยโฮวาห์ตรัสดังนี้ว่า “เหมือนอย่างมะเดื่อที่เลว ซึ่งเลวมากจนรับประทานไม่ได้นั้น เราจะกระทําต่อเศเดคียาห์กษัตริย์แห่งยูดาห์ ทั้งเจ้านายของเขา และชาวเยรูซาเล็มที่เหลืออยู่ ผู้ซึ่งยังค้างอยู่ในแผ่นดินนี้ และผู้ที่ยังอาศัยอยู่ในประเทศอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 9, 'เราจะมอบเขาไว้ให้ย้ายไปอยู่ในอาณาจักรทั้งสิ้นในโลกเพื่อให้เขาเจ็บปวด ให้เป็นที่ถูกตําหนิ เป็นคําภาษิต เป็นที่ถูกเยาะเย้ย และเป็นที่ถูกสาปแช่ง ในที่ทุกแห่งซึ่งเราขับไล่เขาให้ไปอยู่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 10, 'และเราจะส่งดาบและการกันดารอาหาร และโรคระบาดมาท่ามกลางเขา จนเขาจะถูกทําลายอย่างสิ้นเชิงจากแผ่นดินซึ่งเราได้ให้แก่เขาและแก่บรรพบุรุษของเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 1, 'พระวจนะซึ่งมาถึงเยเรมีย์เกี่ยวด้วยเรื่องชนชาติยูดาห์ทั้งสิ้น ในปีที่สี่แห่งรัชกาลเยโฮยาคิม ราชบุตรของโยสิยาห์กษัตริย์แห่งยูดาห์ ปีนั้นเป็นปีต้นรัชกาลของเนบูคัดเนสซาร์กษัตริย์ของกรุงบาบิโลน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 2, 'ซึ่งเยเรมีย์ผู้พยากรณ์ได้กล่าวแก่ประชาชนยูดาห์ และแก่ชาวเยรูซาเล็มทั้งสิ้น ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 3, '“ตั้งแต่ปีที่สิบสามของโยสิยาห์ ราชบุตรของอาโมนกษัตริย์แห่งยูดาห์ จนถึงวันนี้เป็นเวลายี่สิบสามปี พระวจนะของพระเยโฮวาห์มายังข้าพเจ้า และข้าพเจ้าก็ได้บอกแก่ท่านทั้งหลายอย่างไม่หยุดยั้ง แต่ท่านหาได้ฟังไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 4, 'ท่านไม่ฟังหรือเอียงหูของท่านฟัง แม้ว่าพระเยโฮวาห์ทรงส่งบรรดาผู้พยากรณ์ผู้รับใช้ของพระองค์มาอย่างไม่หยุดยั้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 5, 'กล่าวว่า ‘บัดนี้เจ้าทุกคนจงหันกลับจากทางชั่วของตน และจากการกระทําผิดของตน และอาศัยอยู่ในแผ่นดินซึ่งพระเยโฮวาห์ทรงประทานแก่เจ้าและบรรพบุรุษของเจ้าต่อไปเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 6, 'อย่าไปติดตามพระอื่นเพื่อจะปรนนิบัติและนมัสการพระเหล่านั้น หรือยั่วเย้าเราให้โกรธด้วยผลงานแห่งมือของเจ้า แล้วเราจะไม่ทําอันตรายแก่เจ้า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 7, 'พระเยโฮวาห์ตรัสว่า ‘แม้กระนั้นเจ้าทั้งหลายก็ไม่ฟังเรา เพื่อเจ้าจะได้ยั่วเย้าเราให้กริ้วด้วยผลงานแห่งมือของเจ้า ซึ่งเป็นผลร้ายแก่เจ้าเอง’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 8, 'เพราะฉะนั้น พระเยโฮวาห์จอมโยธาจึงตรัสดังนี้ว่า ‘เพราะเจ้าไม่ฟังถ้อยคําของเรา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 9, 'พระเยโฮวาห์ตรัสว่า ‘ดูเถิด เราจะส่งคนไปนําครอบครัวทั้งสิ้นของทิศเหนือและเนบูคัดเนสซาร์กษัตริย์บาบิโลนผู้รับใช้ของเรา และเราจะนําเขาทั้งหลายมาต่อสู้แผ่นดินนี้และต่อสู้คนที่อาศัยอยู่ในแผ่นดินนี้และต่อสู้บรรดาประชาชาติเหล่านี้ซึ่งอยู่ล้อมรอบ เราจะทําลายเขาทั้งหลายอย่างสิ้นเชิง และเราจะกระทําให้เขาเป็นที่น่าตกตะลึง และเป็นที่เย้ยหยันและเป็นที่รกร้างอยู่เนืองนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 10, 'ยิ่งกว่านั้นอีก เราจะกําจัดเสียงบันเทิงและเสียงร่าเริง เสียงเจ้าบ่าวและเสียงเจ้าสาว เสียงหินโม่และแสงตะเกียงเสียจากเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 11, 'แผ่นดินนี้ทั้งสิ้นจะเป็นที่รกร้างและที่น่าตกตะลึง และประชาชาติเหล่านี้จะปรนนิบัติกษัตริย์กรุงบาบิโลนอยู่เจ็ดสิบปี’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 12, 'พระเยโฮวาห์ตรัสว่า ‘ต่อมาเมื่อครบเจ็ดสิบปีแล้ว เราจะลงโทษกษัตริย์บาบิโลนและประชาชาตินั้น คือแผ่นดินของชาวเคลเดีย เพราะความชั่วช้าของเขาทั้งหลาย กระทําให้แผ่นดินนั้นรกร้างอยู่เนืองนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 13, 'เราจะนําถ้อยคําทั้งสิ้นให้สําเร็จที่แผ่นดินนั้น คือถ้อยคําที่เราได้กล่าวสู้เมืองนั้น คือทุกสิ่งที่เขียนไว้ในหนังสือนี้ ซึ่งเยเรมีย์ได้พยากรณ์แก่บรรดาประชาชาติทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 14, 'เพราะว่าจะมีหลายประชาชาติและบรรดามหากษัตริย์กระทําให้เขาเหล่านั้นเป็นทาส ทั้งเขาทั้งหลายด้วย และเราจะตอบแทนเขาทั้งหลายตามการกระทําและผลงานแห่งมือของเขา’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 15, 'พระเยโฮวาห์พระเจ้าแห่งอิสราเอลตรัสกับข้าพเจ้าดังนี้ว่า “จงเอาถ้วยน้ําองุ่นแห่งความพิโรธนี้ไปจากมือเรา และบังคับบรรดาประชาชาติซึ่งเราส่งเจ้าไปนั้นให้ดื่มจากถ้วยนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 16, 'เขาจะดื่มและเดินโซเซและบ้าคลั่งไปเนื่องด้วยดาบซึ่งเราจะส่งไปท่ามกลางเขาทั้งหลาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 17, 'ดังนั้น ข้าพเจ้าจึงรับถ้วยมาจากพระหัตถ์ของพระเยโฮวาห์ และบังคับประชาชาติทั้งสิ้น ซึ่งพระเยโฮวาห์ทรงใช้ให้ข้าพเจ้าไปหานั้นดื่ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 18, 'คือกรุงเยรูซาเล็มและหัวเมืองแห่งยูดาห์ ทั้งบรรดากษัตริย์และเจ้านายของเมืองนั้น เพื่อจะกระทําให้เป็นที่รกร้างและเป็นที่น่าตกตะลึง เป็นที่เย้ยหยันและเป็นที่สาปแช่งอย่างทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 19, 'ฟาโรห์กษัตริย์แห่งอียิปต์กับบรรดาข้าราชการและเจ้านายและประชาชนของท่านนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 20, 'และบรรดาชนที่ปะปนกัน บรรดากษัตริย์แห่งแผ่นดินอูส และบรรดากษัตริย์แห่งแผ่นดินฟีลิสเตีย เมืองอัชเคโลน อาซาห์ เอโครน และส่วนชาวเมืองอัชโดดที่เหลืออยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 21, 'เอโดม โมอับและคนอัมโมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 22, 'บรรดากษัตริย์แห่งเมืองไทระ บรรดากษัตริย์เมืองไซดอน และบรรดากษัตริย์แห่งเกาะต่างๆฟากทะเลข้างโน้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 23, 'เมืองเดดาน เทมา บูส และบรรดาคนที่อยู่ในมุมที่ไกลที่สุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 24, 'บรรดากษัตริย์แห่งอาระเบีย และบรรดากษัตริย์แห่งประชาชนที่ปะปนกันอยู่ในถิ่นทุรกันดาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 25, 'บรรดากษัตริย์แห่งศิมรี และบรรดากษัตริย์แห่งเอลาม และบรรดากษัตริย์ของมีเดีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 26, 'บรรดากษัตริย์แห่งเมืองทิศเหนือ ทั้งไกลและใกล้ ทีละเมืองๆ และบรรดาราชอาณาจักรแห่งโลกซึ่งอยู่บนพื้นพิภพ และกษัตริย์แห่งเชชัก จะดื่มภายหลังกษัตริย์เหล่านี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 27, '“แล้วเจ้าจงพูดกับเขาทั้งหลายว่า ‘พระเยโฮวาห์จอมโยธา พระเจ้าแห่งอิสราเอลตรัสดังนี้ว่า จงดื่มให้เมาแล้วก็อาเจียน จงล้มลงและอย่าลุกขึ้นอีกเลย เนื่องด้วยดาบซึ่งเราจะส่งมาท่ามกลางเจ้าทั้งหลาย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 28, 'และถ้าเขาปฏิเสธไม่รับถ้วยจากมือของเจ้าดื่ม เจ้าจงพูดกับเขาทั้งหลายว่า ‘พระเยโฮวาห์จอมโยธาตรัสดังนี้ว่า เจ้าจะต้องดื่ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 29, 'เพราะ ดูเถิด เราได้เริ่มทําโทษเมืองซึ่งเรียกตามนามของเราแล้ว และเจ้าจะลอยนวลไปได้โดยไม่ถูกโทษหรือ พระเยโฮวาห์จอมโยธาตรัสว่า เจ้าจะลอยนวลไปไม่ได้ เพราะเราจะเรียกดาบเล่มหนึ่งมาเหนือชาวแผ่นดินโลกทั้งสิ้น’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 30, 'เพราะฉะนั้น เจ้าจงพยากรณ์คําเหล่านี้ทั้งสิ้นสู้เขาทั้งหลาย และกล่าวแก่เขาว่า ‘พระเยโฮวาห์จะทรงเปล่งเสียงคํารามจากที่สูง และจากที่พํานักอันบริสุทธิ์ของพระองค์ พระองค์จะเปล่งพระสุรเสียง พระองค์จะเปล่งเสียงคํารามมากมายต่อคอกแกะของพระองค์ และทรงโห่ร้องอย่างกับคนที่ย่ําองุ่นโห่ร้องต่อชาวพิภพทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 31, 'เสียงกัมปนาทจะก้องไปทั่วปลายพิภพ เพราะพระเยโฮวาห์ทรงมีคดีกับบรรดาประชาชาติ พระองค์จะทรงเข้าพิพากษาเนื้อหนังทั้งสิ้น ส่วนคนชั่วนั้น พระองค์จะทรงฟันเสียด้วยดาบ’ พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 32, 'พระเยโฮวาห์จอมโยธาตรัสดังนี้ว่า ‘ดูเถิด ความร้ายจะไปจากประชาชาตินี้ถึงประชาชาตินั้น และลมหมุนใหญ่จะปั่นป่วนขึ้นมาจากส่วนพิภพโลกที่ไกลที่สุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 33, 'และบรรดาผู้ที่พระเยโฮวาห์ทรงประหารในวันนั้น จะมีจากปลายโลกข้างนี้ถึงปลายโลกข้างโน้น เขาเหล่านั้นจะไม่มีใครโอดครวญให้ หรือรวบรวมหรือฝังไว้ แต่จะเป็นมูลสัตว์อยู่บนพื้นดิน’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 34, 'ท่านผู้เลี้ยงแกะทั้งหลายเอ๋ย จงคร่ําครวญและร้องเถิด ท่านเจ้าของฝูงแกะ จงกลิ้งเกลือกในขี้เถ้า เพราะวันเวลาของการสังหารเจ้าและที่เจ้าต้องกระจัดกระจายมาถึงแล้ว และเจ้าทั้งหลายจะล้มลงเหมือนภาชนะงาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 35, 'ผู้เลี้ยงแกะจะไม่มีทางหนี หรือเจ้าของฝูงแกะไม่มีทางรอดหนีไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 36, 'จะได้ฟังเสียงร้องของผู้เลี้ยงแกะ และเสียงคร่ําครวญของเจ้าของฝูงแกะ เพราะว่าพระเยโฮวาห์ทรงทําลายลานหญ้าของเขาทั้งหลายเสียแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 37, 'และคอกแกะที่สงบสุขก็ถูกตัดให้ล้มลงเสียแล้ว เนื่องด้วยความกริ้วอันแรงกล้าของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 38, 'พระองค์ทรงออกจากที่ซุ่มตัวของพระองค์อย่างสิงโต เพราะว่าแผ่นดินของเขาทั้งหลายเป็นที่รกร้าง เพราะเหตุความดุดันของพระผู้เข้มงวด และเพราะเหตุความกริ้วอันแรงกล้าของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 1, 'ในต้นรัชกาลของเยโฮยาคิม ราชบุตรของโยสิยาห์กษัตริย์แห่งยูดาห์ พระวจนะนี้มาจากพระเยโฮวาห์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 2, '“พระเยโฮวาห์ตรัสดังนี้ว่า จงยืนอยู่ในลานพระนิเวศแห่งพระเยโฮวาห์ และจงพูดกับบรรดาหัวเมืองแห่งยูดาห์ ซึ่งมานมัสการในพระนิเวศของพระเยโฮวาห์ คือพูดบรรดาถ้อยคําที่เราสั่งเจ้าให้พูดกับเขา อย่าเก็บไว้สักคําเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 3, 'บางทีเขาจะฟัง และทุกคนจะกลับจากทางชั่วของเขา และเราจะกลับใจไม่ทําความร้ายซึ่งเราเจตนาจะกระทําต่อเขาทั้งหลาย เนื่องด้วยการกระทําที่ชั่วร้ายของเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 4, 'เจ้าจงพูดกับเขาทั้งหลายว่า ‘พระเยโฮวาห์ตรัสดังนี้ว่า ถ้าเจ้าทั้งหลายไม่ฟังเรา ที่จะดําเนินตามราชบัญญัติที่เราได้วางไว้ต่อหน้าเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 5, 'และเชื่อฟังถ้อยคําของบรรดาผู้รับใช้ของเรา คือบรรดาผู้พยากรณ์ ซึ่งเราได้ส่งไปหาเจ้าอย่างไม่หยุดยั้ง คือส่งพวกเขาไป ถึงเจ้าจะมิได้เชื่อฟัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 6, 'แล้วเราจะกระทําให้พระนิเวศนี้เหมือนอย่างชีโลห์ และเราจะกระทําให้เมืองนี้เป็นที่สาปแก่บรรดาประชาชาติทั่วโลก’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 7, 'บรรดาปุโรหิตและผู้พยากรณ์ และประชาชนทั้งสิ้นได้ยินเยเรมีย์พูดถ้อยคําเหล่านี้ในพระนิเวศของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 8, 'และต่อมาเมื่อเยเรมีย์ได้จบคําพูดทั้งสิ้นซึ่งพระเยโฮวาห์ได้บัญชาท่านให้พูดแก่บรรดาประชาชนนั้น พวกปุโรหิตและผู้พยากรณ์และประชาชนทั้งสิ้นได้จับเยเรมีย์กล่าวว่า “เจ้าจะต้องตายแน่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 9, 'ทําไมเจ้าจึงพยากรณ์ในพระนามของพระเยโฮวาห์ว่า ‘พระนิเวศนี้จะเหมือนชีโลห์และเมืองนี้จะรกร้าง ปราศจากคนอาศัย’” และประชาชนทั้งสิ้นก็รวมตัวกันต่อต้านเยเรมีย์ที่พระนิเวศของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 10, 'เมื่อบรรดาเจ้านายแห่งยูดาห์ได้ยินสิ่งเหล่านี้แล้ว ท่านก็ขึ้นมาจากพระราชวังถึงพระนิเวศของพระเยโฮวาห์ และมานั่งในทางเข้าประตูใหม่แห่งพระนิเวศของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 11, 'แล้วบรรดาปุโรหิตและผู้พยากรณ์จึงทูลเจ้านายและบอกประชาชนทั้งปวงว่า “ชายคนนี้ควรแก่การตัดสินลงโทษถึงความตาย เพราะเขาพยากรณ์กล่าวโทษเมืองนี้ ดังที่ท่านทั้งหลายได้ยินกับหูของท่านเองแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 12, 'เยเรมีย์จึงทูลเจ้านายทั้งสิ้นและบอกประชาชนทั้งปวงว่า “พระเยโฮวาห์ทรงใช้ให้ข้าพเจ้ามาพยากรณ์ต่อพระนิเวศและเมืองนี้ ตามถ้อยคําทั้งสิ้นซึ่งท่านทั้งหลายได้ยินมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 13, 'เพราะฉะนั้น บัดนี้ท่านทั้งหลายจงแก้ไขพฤติการณ์และการกระทําของท่านทั้งหลาย และเชื่อฟังพระสุรเสียงของพระเยโฮวาห์พระเจ้าของท่าน และพระเยโฮวาห์จะทรงกลับพระทัยจากความร้ายซึ่งพระองค์ได้ทรงประกาศเตือนท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 14, 'แต่ส่วนตัวข้าพเจ้า ดูเถิด ข้าพเจ้าอยู่ในมือของท่านทั้งหลาย ท่านจะกระทําแก่ข้าพเจ้าตามที่ท่านเห็นดีและเห็นชอบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 15, 'ขอแต่เพียงให้ทราบแน่ว่า ถ้าท่านประหารข้าพเจ้า ท่านจะนําเลือดที่ไร้ความผิดมาเหนือตัวท่านเองและเมืองนี้และชาวเมืองนี้เป็นแน่ เพราะความจริงพระเยโฮวาห์ทรงใช้ให้ข้าพเจ้ามาพูดถ้อยคําเหล่านี้ทั้งสิ้นให้เข้าหูของท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 16, 'แล้วเจ้านายและประชาชนทั้งสิ้นได้พูดกับบรรดาปุโรหิตและผู้พยากรณ์ว่า “ชายผู้นี้ไม่สมควรที่จะต้องคําพิพากษาถึงความตาย เพราะเขาได้พูดกับเราในพระนามของพระเยโฮวาห์พระเจ้าของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 17, 'และผู้ใหญ่บางคนแห่งแผ่นดินนั้นก็ลุกขึ้นพูดกับประชาชนทั้งสิ้นที่ประชุมกันอยู่ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 18, '“มีคาห์ชาวเมืองโมเรเชทได้พยากรณ์ในสมัยเฮเซคียาห์กษัตริย์แห่งยูดาห์ และกล่าวแก่ประชาชนทั้งสิ้นของยูดาห์ว่า ‘พระเยโฮวาห์จอมโยธาตรัสดังนี้ว่า เมืองศิโยนจะถูกไถเหมือนกับไถนา กรุงเยรูซาเล็มจะกลายเป็นกองสิ่งปรักหักพัง และภูเขาที่ตั้งของพระนิเวศนั้นจะเป็นเหมือนที่สูงในป่าไม้’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 19, 'เฮเซคียาห์กษัตริย์แห่งยูดาห์และคนยูดาห์ทั้งสิ้นได้ฆ่าเขาเสียหรือ ท่านได้ยําเกรงพระเยโฮวาห์และทูลวิงวอนขอพระเยโฮวาห์ และพระเยโฮวาห์ได้กลับพระทัยต่อความร้ายซึ่งพระองค์ทรงประกาศเตือนเขาเหล่านั้นมิใช่หรือ แต่เรากําลังจะนําเหตุร้ายใหญ่ยิ่งมาสู่จิตใจเราเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 20, 'ยังมีชายอีกคนหนึ่งผู้พยากรณ์ในพระนามของพระเยโฮวาห์ ชื่ออุรียาห์ บุตรชายเชไมอาห์ ชาวคีริยาทเยอาริม ท่านได้พยากรณ์กล่าวโทษเมืองนี้และแผ่นดินนี้ ตามบรรดาถ้อยคําของเยเรมีย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 21, 'และเมื่อกษัตริย์เยโฮยาคิม พร้อมกับบรรดาทแกล้วทหาร และบรรดาเจ้านายได้ยินถ้อยคํานี้ กษัตริย์ก็ทรงแสวงหาจะสังหารท่านเสีย และเมื่ออุรียาห์ได้ยินเรื่องนี้ ท่านก็กลัวจึงหนีรอดไปยังอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 22, 'แล้วกษัตริย์เยโฮยาคิมก็ส่งชายบางคน คือเอลนาธันบุตรชายอัคโบร์และคนอื่นอีกไปยังอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 23, 'และเขาทั้งหลายจับอุรียาห์มาจากอียิปต์ และนําท่านมาถวายกษัตริย์เยโฮยาคิม พระองค์ทรงประหารท่านเสียด้วยดาบ และโยนศพเข้าไปในที่ฝังศพของคนสามัญ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 24, 'แต่มือของอาหิคัมบุตรชายชาฟานอยู่กับเยเรมีย์ ฉะนั้นเยเรมีย์จึงมิได้ถูกมอบให้ในมือประชาชนเพื่อประหารชีวิตท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 1, 'ในต้นรัชกาลเยโฮยาคิมราชบุตรของโยสิยาห์ กษัตริย์แห่งยูดาห์ พระวจนะนี้มาจากพระเยโฮวาห์ถึงเยเรมีย์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 2, 'พระเยโฮวาห์ตรัสกับข้าพเจ้าดังนี้ว่า “จงทําสายรัดและแอกสําหรับตัวเจ้า จงสวมคอของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 3, 'และส่งมันไปยังกษัตริย์แห่งเอโดม กษัตริย์แห่งโมอับและกษัตริย์แห่งคนอัมโมน กษัตริย์แห่งไทระ และกษัตริย์แห่งไซดอน ด้วยมือของทูตที่มาเข้าเฝ้าเศเดคียาห์กษัตริย์แห่งยูดาห์ที่กรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 4, 'จงฝากคํากําชับเหล่านี้แก่บรรดานายของเขาว่า ‘พระเยโฮวาห์จอมโยธา พระเจ้าแห่งอิสราเอล ตรัสดังนี้ว่า เจ้าจงกล่าวเรื่องต่อไปนี้ให้นายของเจ้าฟังว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 5, 'นี่คือเราเอง ผู้ได้สร้างโลก ทั้งมนุษย์และสัตว์ซึ่งอยู่บนพื้นดิน ด้วยฤทธานุภาพใหญ่ยิ่งและด้วยแขนที่เหยียดออกของเรา และเราจะให้แก่ผู้ใดก็ได้สุดแต่เราเห็นชอบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 6, 'บัดนี้ เราได้ให้แผ่นดินเหล่านี้ทั้งสิ้นไว้ในมือของเนบูคัดเนสซาร์ กษัตริย์แห่งบาบิโลนผู้รับใช้ของเรา และเราได้ให้สัตว์ป่าทุ่งแก่เขาด้วยที่จะปรนนิบัติเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 7, 'บรรดาประชาชาติทั้งสิ้นจะต้องปรนนิบัติตัวเขา ลูกและหลานของเขา จนกว่าเวลากําหนดแห่งแผ่นดินของท่านเองจะมาถึง แล้วหลายประชาชาติและบรรดามหากษัตริย์จะกระทําให้ท่านเป็นทาสของเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 8, 'แต่ต่อมาถ้าประชาชาติใด หรือราชอาณาจักรใด จะไม่ปรนนิบัติเนบูคัดเนสซาร์กษัตริย์แห่งบาบิโลนคนนี้ และไม่ยอมวางคอไว้ใต้แอกของกษัตริย์บาบิโลน เราจะลงโทษประชาชาตินั้นด้วยดาบ ด้วยการกันดารอาหาร และด้วยโรคระบาด พระเยโฮวาห์ตรัสดังนี้แหละ จนกว่าเราจะล้างผลาญเสียด้วยมือของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 9, 'เพราะฉะนั้นอย่าฟังผู้พยากรณ์ หรือพวกโหรหรือคนช่างฝันของเจ้า หรือหมอดูหรือนักวิทยาคมของเจ้า ผู้ซึ่งกล่าวแก่เจ้าว่า “ท่านจะไม่ปรนนิบัติกษัตริย์แห่งกรุงบาบิโลนดอก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 10, 'เพราะซึ่งเขาพยากรณ์ให้ท่านนั้นเป็นความเท็จ อันยังผลให้ท่านต้องโยกย้ายไกลไปจากแผ่นดินของท่าน และเราจะขับไล่ท่านออกไป และท่านจะพินาศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 11, 'แต่ประชาชาติใดซึ่งเอาคอของตนวางไว้ใต้แอกของกษัตริย์แห่งบาบิโลนและปรนนิบัติท่าน เราจะละเขาไว้บนแผ่นดินของเขา เพื่อให้ทําไร่ไถนาและให้อาศัยอยู่ที่นั่น พระเยโฮวาห์ตรัสดังนี้แหละ’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 12, 'ข้าพเจ้าได้ทูลเศเดคียาห์กษัตริย์แห่งยูดาห์ตามบรรดาถ้อยคําเหล่านี้ว่า “จงเอาคอของท่านไว้ใต้แอกของกษัตริย์แห่งบาบิโลน และปรนนิบัติเขาและประชาชนของเขา และจงมีชีวิตอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 13, 'ทําไมท่านกับชนชาติของท่านจะมาตายเสียด้วยดาบ ด้วยการกันดารอาหารและด้วยโรคระบาด ดังที่พระเยโฮวาห์ทรงลั่นวาจาเกี่ยวด้วยประชาชาติใดๆซึ่งจะไม่ปรนนิบัติกษัตริย์แห่งบาบิโลน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 14, 'อย่าฟังถ้อยคําของผู้พยากรณ์ผู้กล่าวแก่เจ้าว่า ‘ท่านจะไม่ปรนนิบัติกษัตริย์แห่งบาบิโลนดอก’ เพราะซึ่งเขาทั้งหลายพยากรณ์แก่ท่านนั้นก็เป็นการมุสา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 15, 'พระเยโฮวาห์ตรัสว่า เราไม่ได้ใช้เขา แต่เขาพยากรณ์เท็จในนามของเรา ซึ่งยังผลให้เราต้องขับไล่เจ้าออกไปและเจ้าจะต้องพินาศ ทั้งตัวเจ้าและผู้พยากรณ์ทั้งหลายซึ่งพยากรณ์ให้แก่เจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 16, 'และข้าพเจ้าก็ได้พูดกับปุโรหิตและประชาชนนี้ทั้งสิ้นว่า “พระเยโฮวาห์ตรัสดังนี้ว่า อย่าเชื่อฟังถ้อยคําของผู้พยากรณ์ของเจ้า ซึ่งพยากรณ์ให้แก่เจ้าว่า ‘ดูเถิด ไม่ช้าเขาจะนําเครื่องใช้ของพระนิเวศแห่งพระเยโฮวาห์กลับมาจากกรุงบาบิโลน’ เพราะซึ่งเขาพยากรณ์แก่ท่านนั้นก็เป็นความเท็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 17, 'อย่าเชื่อฟังเขาเลย จงปรนนิบัติกษัตริย์แห่งบาบิโลนและมีชีวิตอยู่ ทําไมเมืองนี้จะร้างเปล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 18, 'แต่ถ้าเขาเหล่านั้นเป็นผู้พยากรณ์ และถ้าพระวจนะของพระเยโฮวาห์อยู่กับเขา ก็ขอให้เขาทูลวิงวอนต่อพระเยโฮวาห์จอมโยธาว่า ให้เครื่องใช้ซึ่งยังเหลืออยู่ในพระนิเวศของพระเยโฮวาห์ และในพระราชวังของกษัตริย์แห่งยูดาห์ และในกรุงเยรูซาเล็ม อย่าให้ไปยังบาบิโลน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 19, 'เพราะพระเยโฮวาห์จอมโยธาตรัสดังนี้เกี่ยวกับบรรดาเสา ขันสาคร และขาตั้ง และเครื่องใช้อื่นๆที่เหลืออยู่ในเมืองนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 20, 'ที่เนบูคัดเนสซาร์กษัตริย์แห่งบาบิโลนมิได้ริบเอาไป เมื่อท่านได้จับเอาเยโคนิยาห์ราชบุตรของเยโฮยาคิมกษัตริย์ของยูดาห์ และบรรดาขุนนางของยูดาห์และเยรูซาเล็มถูกกวาดต้อนจากกรุงเยรูซาเล็มไปเป็นเชลยยังกรุงบาบิโลน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 21, 'พระเยโฮวาห์จอมโยธา พระเจ้าแห่งอิสราเอลตรัสดังนี้เกี่ยวด้วยเรื่องเครื่องใช้ซึ่งยังเหลืออยู่ในพระนิเวศของพระเยโฮวาห์ ในพระราชวังของกษัตริย์แห่งยูดาห์และในกรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 22, 'พระเยโฮวาห์ตรัสว่า เครื่องใช้เหล่านี้จะถูกขนไปยังบาบิโลน และจะค้างอยู่ที่นั่นจนถึงวันที่เราเอาใจใส่มัน แล้วเราจึงจะนํามันกลับขึ้นมา และให้กลับสู่สถานที่นี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 1, 'ต่อมาในปีเดียวกันนั้นเมื่อต้นรัชกาลเศเดคียาห์กษัตริย์แห่งยูดาห์ ในเดือนที่ห้าปีที่สี่ ฮานันยาห์บุตรชายของอัสซูร์ ผู้พยากรณ์จากกิเบโอน ได้พูดกับข้าพเจ้าในพระนิเวศของพระเยโฮวาห์ ต่อหน้าบรรดาปุโรหิตและประชาชนทั้งหลายว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 2, '“พระเยโฮวาห์จอมโยธา พระเจ้าแห่งอิสราเอลตรัสดังนี้ว่า เราได้หักแอกของกษัตริย์แห่งบาบิโลนแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 3, 'ภายในสองปี เราจะนําเครื่องใช้ทั้งสิ้นของพระนิเวศแห่งพระเยโฮวาห์กลับมายังที่นี้ ซึ่งเป็นภาชนะที่เนบูคัดเนสซาร์กษัตริย์แห่งบาบิโลนริบไปจากที่นี้และขนไปยังบาบิโลน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 4, 'เราจะนําเยโคนิยาห์ราชบุตรของเยโฮยาคิมกษัตริย์แห่งยูดาห์และบรรดาผู้ที่ถูกกวาดจากยูดาห์ ผู้ซึ่งไปยังบาบิโลน กลับมายังที่นี้ พระเยโฮวาห์ตรัสดังนี้แหละว่า เพราะเราจะหักแอกของกษัตริย์แห่งบาบิโลน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 5, 'แล้วเยเรมีย์ผู้พยากรณ์ก็พูดกับฮานันยาห์ผู้พยากรณ์ต่อหน้าบรรดาปุโรหิต และต่อหน้าประชาชนทั้งปวงผู้ซึ่งยืนอยู่ในพระนิเวศของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 6, 'และเยเรมีย์ผู้พยากรณ์กล่าวว่า “เอเมน ขอพระเยโฮวาห์ทรงกระทําเช่นนั้นเถิด ขอพระเยโฮวาห์ทรงกระทําให้ถ้อยคําซึ่งท่านพยากรณ์นั้นเป็นจริง และนําเครื่องใช้แห่งพระนิเวศของพระเยโฮวาห์และบรรดาผู้ถูกกวาดไปทั้งสิ้นกลับมาจากบาบิโลนยังที่นี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 7, 'ถึงกระนั้นก็ขอฟังถ้อยคํานี้ซึ่งข้าพเจ้าพูดให้ท่านได้ยินและให้ประชาชนทั้งหลายนี้ได้ยิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 8, 'บรรดาผู้พยากรณ์ซึ่งอยู่ก่อนท่านและข้าพเจ้าตั้งแต่โบราณกาลได้พยากรณ์ถึงสงคราม เหตุร้ายต่างๆ และโรคระบาดอันมีแก่หลายประเทศและหลายราชอาณาจักรใหญ่ๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 9, 'ส่วนผู้พยากรณ์ที่พยากรณ์ว่าจะมีสันติภาพ เมื่อเป็นจริงตามถ้อยคําของผู้พยากรณ์นั้น จึงรู้กันว่าพระเยโฮวาห์ทรงใช้ผู้พยากรณ์นั้นจริง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 10, 'แล้วฮานันยาห์ผู้พยากรณ์ก็ปลดแอกออกจากคอของเยเรมีย์ผู้พยากรณ์และหักมันเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 11, 'และฮานันยาห์ได้กล่าวต่อหน้าประชาชนทั้งสิ้นว่า “พระเยโฮวาห์ตรัสดังนี้ว่า อย่างนั้นแหละ เราจะหักแอกของเนบูคัดเนสซาร์กษัตริย์ของบาบิโลนจากคอของบรรดาประชาชาติทั้งสิ้นภายในสองปี” แต่เยเรมีย์ผู้พยากรณ์ก็ออกไปเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 12, 'หลังจากที่ฮานันยาห์ผู้พยากรณ์หักแอกจากคอของเยเรมีย์ผู้พยากรณ์ พระวจนะของพระเยโฮวาห์มายังผู้พยากรณ์เยเรมีย์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 13, '“จงไปบอกฮานันยาห์ว่า ‘พระเยโฮวาห์ตรัสดังนี้ว่า เจ้าได้หักแอกไม้’ แต่เจ้าจะทําแอกเหล็กไว้ให้พวกเขาแทน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 14, 'เพราะพระเยโฮวาห์จอมโยธา พระเจ้าแห่งอิสราเอล ตรัสดังนี้ว่า เราได้วางแอกเหล็กไว้บนคอบรรดาประชาชาติเหล่านี้ทั้งสิ้น ให้เขาปรนนิบัติเนบูคัดเนสซาร์กษัตริย์แห่งบาบิโลนและเขาทั้งหลายจะปรนนิบัติเขา เพราะเราได้ยกให้เขาแล้วแม้กระทั่งสัตว์ป่าทุ่งด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 15, 'และเยเรมีย์ผู้พยากรณ์ได้พูดกับฮานันยาห์ผู้พยากรณ์ว่า “ฮานันยาห์ ขอท่านฟัง พระเยโฮวาห์มิได้ทรงใช้ท่าน แต่ท่านได้กระทําให้ชนชาตินี้วางใจในความเท็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 16, 'เพราะฉะนั้น พระเยโฮวาห์ตรัสว่า ดูเถิด เราจะย้ายเจ้าไปจากพื้นโลก ในปีเดียวนี้เองเจ้าจะต้องตาย เพราะเจ้าได้สอนให้กบฏต่อพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 17, 'ในปีเดียวกันนั้น ในเดือนที่เจ็ด ฮานันยาห์ผู้พยากรณ์ก็ตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 1, 'ต่อไปนี้เป็นถ้อยคําในจดหมายซึ่งเยเรมีย์ผู้พยากรณ์ฝากไปจากกรุงเยรูซาเล็มถึงพวกผู้ใหญ่ที่เหลืออยู่ของพวกที่เป็นเชลย และถึงบรรดาปุโรหิต บรรดาผู้พยากรณ์ และประชาชนทั้งสิ้น ผู้ซึ่งเนบูคัดเนสซาร์ได้ให้กวาดไปจากกรุงเยรูซาเล็มถึงบาบิโลน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 2, '(นี่เป็นเรื่องหลังจากกษัตริย์เยโคนิยาห์ และพระราชินี พวกขันที บรรดาเจ้านายของยูดาห์และเยรูซาเล็ม และบรรดาช่างไม้และช่างเหล็กได้ออกไปจากกรุงเยรูซาเล็มแล้ว)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 3, 'จดหมายนั้นได้ส่งไปด้วยมือของเอลาสาห์บุตรชายของชาฟานและเกมาริยาห์บุตรชายฮิลคียาห์ (ผู้ซึ่งเศเดคียาห์กษัตริย์แห่งยูดาห์ส่งไปที่บาบิโลนยังเนบูคัดเนสซาร์กษัตริย์แห่งบาบิโลน) จดหมายนั้นว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 4, '“พระเยโฮวาห์จอมโยธา พระเจ้าแห่งอิสราเอล ตรัสดังนี้แก่บรรดาผู้เป็นเชลย ผู้ซึ่งเราได้เนรเทศเขาไปจากกรุงเยรูซาเล็มถึงบาบิโลนนั้นว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 5, 'จงสร้างเรือนของเจ้าและอาศัยอยู่ในเรือนนั้น จงปลูกสวนและรับประทานผลไม้ที่ได้นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 6, 'จงมีภรรยาและให้กําเนิดบุตรชายบุตรสาว จงหาภรรยาให้บุตรชายของเจ้าทั้งหลาย และยกบุตรสาวของเจ้าให้แต่งงานเสีย เพื่อนางจะให้กําเนิดบุตรชายและบุตรสาว เพื่อเจ้าทั้งหลายจะทวีมากขึ้นที่นั่นและไม่น้อยลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 7, 'แต่จงส่งเสริมสันติภาพของเมือง ซึ่งเราได้กวาดเจ้าให้ไปเป็นเชลยอยู่นั้น และจงอธิษฐานต่อพระเยโฮวาห์เผื่อเมืองนั้น เพราะว่าเจ้าทั้งหลายจะพบสันติภาพของเจ้าในสันติภาพของเมืองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 8, 'เพราะพระเยโฮวาห์จอมโยธา พระเจ้าแห่งอิสราเอล ตรัสดังนี้ว่า อย่ายอมให้ผู้พยากรณ์ของเจ้าทั้งหลาย หรือพวกโหรของเจ้า ผู้อยู่ท่ามกลางเจ้าหลอกลวงเจ้า และอย่าเชื่อความฝันซึ่งเขาทั้งหลายได้ฝันเห็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 9, 'เพราะที่เขาพยากรณ์แก่เจ้าในนามของเรานั้นเป็นความเท็จ เรามิได้ใช้เขาไป พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 10, 'เพราะพระเยโฮวาห์ตรัสดังนี้ว่า เมื่อเจ็ดสิบปีแห่งบาบิโลนครบแล้ว เราจะเยี่ยมเยียนเจ้า และจะให้ถ้อยคําอันดีของเราสําเร็จเพื่อเจ้า และจะนําเจ้ากลับมาสู่สถานที่นี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 11, 'พระเยโฮวาห์ตรัสว่า เพราะเรารู้แผนงานที่เรามีไว้สําหรับเจ้า เป็นแผนงานเพื่อสันติภาพ ไม่ใช่เพื่อความทุกข์ยาก เพื่อจะให้อนาคตตามที่คาดหมายไว้แก่เจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 12, 'แล้วเจ้าจะทูลขอต่อเรา และจะไปอธิษฐานต่อเรา และเราจะฟังเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 13, 'เจ้าจะแสวงหาเราและพบเราเมื่อเจ้าแสวงหาเราด้วยสิ้นสุดใจของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 14, 'พระเยโฮวาห์ตรัสว่า เราจะให้เจ้าพบเรา และเราจะให้การเป็นเชลยของเจ้ากลับสู่สภาพดี และรวบรวมเจ้ามาจากบรรดาประชาชาติ และจากทุกที่ที่เราขับไล่เจ้าให้ไปอยู่นั้น พระเยโฮวาห์ตรัสดังนี้แหละ และเราจะนําเจ้ากลับมายังที่ซึ่งเราเนรเทศเจ้าให้จากไปนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 15, 'เพราะเจ้าทั้งหลายได้กล่าวว่า ‘พระเยโฮวาห์ได้เพาะให้มีผู้พยากรณ์สําหรับเราทั้งหลายขึ้นในบาบิโลน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 16, 'จงทราบว่าพระเยโฮวาห์ตรัสดังนี้เกี่ยวกับกษัตริย์ ผู้ประทับบนพระที่นั่งของดาวิด และเกี่ยวกับประชาชนทั้งสิ้นผู้อาศัยอยู่ในเมืองนี้ คือญาติพี่น้องของท่าน ผู้มิได้ถูกเนรเทศไปกับท่านว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 17, 'พระเยโฮวาห์จอมโยธาตรัสดังนี้ว่า ดูเถิด เราจะส่งดาบ การกันดารอาหาร และโรคระบาดมาเหนือเขาทั้งหลาย และเราจะกระทําให้เขาทั้งหลายเหมือนกับมะเดื่อที่เสียซึ่งเลวมากจนเขารับประทานไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 18, 'เราจะข่มเหงเขาด้วยดาบ การกันดารอาหาร และโรคระบาด และจะกระทําเขาให้ย้ายไปอยู่ในราชอาณาจักรทั้งสิ้นแห่งแผ่นดินโลก ให้เป็นคําสาป ให้เป็นที่น่าตกตะลึง ให้เป็นที่เย้ยหยัน เป็นที่นินทาท่ามกลางบรรดาประชาชาติซึ่งเราได้ขับไล่ให้เขาไปอยู่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 19, 'พระเยโฮวาห์ตรัสว่า เพราะว่าเขาทั้งหลายไม่เชื่อฟังถ้อยคําของเราที่ส่งมายังเขาอย่างไม่หยุดยั้ง โดยผู้พยากรณ์ผู้รับใช้ของเรา แต่เจ้าทั้งหลายไม่ยอมฟัง พระเยโฮวาห์ตรัสดังนี้แหละ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 20, 'เจ้าทั้งปวงผู้ถูกเนรเทศ ผู้ซึ่งเราส่งไปจากกรุงเยรูซาเล็มถึงบาบิโลน จงฟังพระวจนะของพระเยโฮวาห์ที่ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 21, '“พระเยโฮวาห์จอมโยธา พระเจ้าของอิสราเอล ตรัสดังนี้เกี่ยวกับอาหับบุตรชายของโคลายาห์ และเศเดคียาห์บุตรชายมาอาเสอาห์ ผู้ซึ่งได้พยากรณ์เท็จแก่เจ้าในนามของเรา ดูเถิด เราจะมอบเขาทั้งสองไว้ในมือของเนบูคัดเนสซาร์กษัตริย์แห่งบาบิโลน และท่านจะฆ่าเขาทั้งสองเสียต่อหน้าต่อตาเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 22, 'เหตุเขาทั้งสองบรรดาผู้ที่ถูกเนรเทศจากยูดาห์ไปถึงบาบิโลนจะใช้คําสาปต่อไปนี้ว่า ‘ขอพระเยโฮวาห์ทรงกระทําให้เจ้าเหมือนเศเดคียาห์และอาหับ ผู้ที่กษัตริย์บาบิโลนคลอกเสียด้วยไฟ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 23, 'เพราะเขาทั้งสองได้กระทําความเลวร้ายในอิสราเอล ได้ล่วงประเวณีกับภรรยาของเพื่อนบ้าน และได้พูดถ้อยคําเท็จในนามของเรา ซึ่งเรามิได้บัญชาเขา เราเป็นผู้ที่รู้และเราเป็นพยาน” พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 24, 'เจ้าจงบอกเชไมอาห์ชาวเนเฮลามว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 25, '“พระเยโฮวาห์จอมโยธา พระเจ้าแห่งอิสราเอล ตรัสดังนี้ว่า เจ้าได้ส่งจดหมายในนามของเจ้าไปยังประชาชนทั้งปวงผู้อยู่ในกรุงเยรูซาเล็ม และยังเศฟันยาห์บุตรชายมาอาเสอาห์ปุโรหิต และยังปุโรหิตทั้งปวงว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 26, '‘พระเยโฮวาห์ได้ทรงกระทําเจ้าให้เป็นปุโรหิตแทนเยโฮยาดาปุโรหิต ให้เป็นเจ้าหน้าที่ในพระนิเวศของพระเยโฮวาห์ ควบคุมคนบ้าทุกคนที่ตั้งตัวเองเป็นผู้พยากรณ์ ให้จับเขาใส่คุกและใส่คา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 27, 'ฉะนั้นบัดนี้ทําไมเจ้ามิได้ต่อว่าเยเรมีย์ชาวอานาโธทผู้ซึ่งตั้งตัวเองเป็นผู้พยากรณ์แก่เจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 28, 'เพราะเขาได้ส่งจดหมายมายังเราในบาบิโลนว่า ‘การที่เจ้าเป็นเชลยนั้นจะเนิ่นนาน จงสร้างเรือนของเจ้าและอาศัยอยู่ในเรือนนั้น และปลูกสวนและรับประทานผลที่ได้นั้น’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 29, 'เศฟันยาห์ปุโรหิตอ่านจดหมายนี้ให้เยเรมีย์ผู้พยากรณ์ฟัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 30, 'แล้วพระวจนะของพระเยโฮวาห์มายังเยเรมีย์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 31, '“จงเขียนไปถึงบรรดาผู้เป็นเชลยทั้งปวงว่า ‘พระเยโฮวาห์ตรัสเกี่ยวกับเชไมอาห์ชาวเนเฮลามว่า เพราะว่าเชไมอาห์ได้พยากรณ์แก่เจ้าเมื่อเรามิได้ใช้เขา และได้กระทําให้เจ้าวางใจในคําเท็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 32, 'เพราะฉะนั้น พระเยโฮวาห์ตรัสดังนี้ว่า ดูเถิด เราจะลงโทษเชไมอาห์ชาวเนเฮลามและเชื้อสายของเขา เขาจะไม่มีสักคนหนึ่งที่จะอาศัยอยู่ในท่ามกลางชนชาตินี้ ทั้งเขาจะมิได้เห็นความดีซึ่งเราจะกระทําแก่ประชาชนของเรา เพราะเขาได้สอนให้กบฏต่อพระเยโฮวาห์ พระเยโฮวาห์ตรัสดังนี้แหละ’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 1, 'พระวจนะของพระเยโฮวาห์มายังเยเรมีย์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 2, '“พระเยโฮวาห์พระเจ้าแห่งอิสราเอลตรัสดังนี้ว่า จงเขียนถ้อยคําทั้งสิ้นที่เราได้บอกแก่เจ้าไว้ในหนังสือม้วนหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 3, 'พระเยโฮวาห์ตรัสว่า เพราะดูเถิด วันเวลาจะมาถึง เมื่อเราจะให้ประชาชนของเรา คืออิสราเอลและยูดาห์ที่เป็นเชลยกลับคืนสู่สภาพเดิม พระเยโฮวาห์ตรัสดังนี้แหละ และเราจะนําเขามายังแผ่นดินซึ่งเราได้ให้แก่บรรพบุรุษของเขาทั้งหลาย และเขาทั้งหลายจะได้ถือกรรมสิทธิ์ที่ดินนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 4, 'ต่อไปนี้เป็นพระวจนะซึ่งพระเยโฮวาห์ตรัสเกี่ยวกับอิสราเอลและยูดาห์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 5, '“พระเยโฮวาห์ตรัสดังนี้ว่า เราได้ยินเสียงร้องเพราะความกลัวตัวสั่น ความสยดสยองและความไร้สันติภาพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 6, 'จงถามเถิดและดูว่า ผู้ชายจะคลอดบุตรได้หรือ ทําไมเราจึงเห็นผู้ชายทุกคนเอามือกดไว้ที่เอวเหมือนผู้หญิงจะคลอดบุตร ทําไมหน้าตาทุกคนจึงซีดไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 7, 'อนิจจาเอ๋ย เพราะวันนั้นใหญ่โตเหลือเกิน ไม่มีวันใดเหมือนวันนั้น เป็นเวลาทุกข์ใจของยาโคบ แต่เขาก็ยังจะรอดวันนั้นไปได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 8, 'พระเยโฮวาห์จอมโยธาตรัสว่า ในวันนั้นเหตุการณ์จะเกิดขึ้น คือเราจะหักแอกจากคอของเจ้าทั้งหลายเสีย และเราจะระเบิดพันธนะของเจ้าเสีย และคนต่างชาติจะไม่ทําให้เขาเป็นทาสอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 9, 'แต่เขาทั้งหลายจะปรนนิบัติพระเยโฮวาห์พระเจ้าของเขาทั้งหลาย และดาวิดกษัตริย์ของเขาทั้งหลายผู้ซึ่งเราจะตั้งขึ้นเพื่อเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 10, 'พระเยโฮวาห์ตรัสว่า โอ ยาโคบผู้รับใช้ของเราเอ๋ย อย่ากลัวเลย โอ อิสราเอลเอ๋ย อย่าครั่นคร้าม เพราะดูเถิด เราจะช่วยเจ้าจากที่ไกลให้รอด ทั้งเชื้อสายของเจ้าจากแผ่นดินที่เขาไปเป็นเชลย ยาโคบจะกลับมา และมีความสงบและความสบาย และจะไม่มีผู้ใดกระทําให้เขากลัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 11, 'พระเยโฮวาห์ตรัสว่า เพราะเราอยู่กับเจ้าเพื่อช่วยเจ้าให้รอด เราจะกระทําให้บรรดาประชาชาติทั้งสิ้นถึงอวสาน คือผู้ซึ่งเราได้กระจายเจ้าให้ไปอยู่ท่ามกลางเขานั้น แต่ส่วนเจ้าเราจะไม่กระทําให้ถึงอวสาน เราจะตีสอนเจ้าตามขนาด และด้วยประการใดก็ตามเราจะไม่ปล่อยเจ้าโดยไม่ลงโทษ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 12, 'เพราะพระเยโฮวาห์ตรัสดังนี้ว่า รอยฟกช้ําของเจ้ารักษาไม่หาย และบาดแผลของเจ้าก็ฉกรรจ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 13, 'ไม่มีผู้ใดที่จะช่วยคดีของเจ้า ไม่มีการรักษาบาดแผลของเจ้า ไม่มียารักษาเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 14, 'คนรักทั้งสิ้นของเจ้าได้ลืมเจ้าเสีย เขาทั้งหลายไม่แสวงหาเจ้าแล้ว เพราะเราตีเจ้าอย่างการโบยตีของศัตรู เป็นการลงโทษอย่างของคนโหดร้าย เพราะว่าความชั่วช้าของเจ้าก็มากมาย เพราะว่าบาปของเจ้าก็ทวีขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 15, 'ไฉนเจ้าร้องเพราะความเจ็บของเจ้า ความเศร้าโศกของเจ้ารักษาไม่หาย เพราะว่าความชั่วช้าของเจ้ามากมาย เพราะว่าบาปของเจ้าทวีขึ้น เราได้กระทําสิ่งเหล่านี้แก่เจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 16, 'เพราะฉะนั้นทุกคนที่กินเจ้า เขาจะถูกกิน ปรปักษ์ของเจ้าหมดสิ้นทุกคนจะตกไปเป็นเชลย ผู้เหล่านั้นที่ปล้นเจ้า เขาจะเป็นของถูกปล้น และทุกคนที่กินเจ้าเป็นเหยื่อ เราจะทําเขาให้เป็นเหยื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 17, 'เพราะเราจะให้เจ้ากลับมาสู่สุขภาพดี และเราจะรักษาบาดแผลของเจ้าให้หาย พระเยโฮวาห์ตรัส เพราะเขาทั้งหลายเรียกเจ้าว่า พวกนอกคอก คือศิโยนซึ่งไม่มีใครแสวงหา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 18, 'พระเยโฮวาห์ตรัสดังนี้ว่า ดูเถิด เราจะให้เต็นท์แห่งยาโคบที่เป็นเชลยกลับสู่สภาพเดิม และมีความเอ็นดูในเรื่องที่อาศัยของเขา เขาจะสร้างเมืองนั้นขึ้นใหม่บนเนินของเมือง และพระราชวังจะตั้งอยู่ในที่ที่เคยอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 19, 'จะมีเพลงโมทนาพระคุณออกมาจากที่เหล่านั้น และมีเสียงของผู้ที่รื่นเริง เราจะทวีเขาขึ้น และเขาจะไม่มีเพียงน้อยคน เราจะกระทําให้เขามีเกียรติ เขาจะไม่เป็นแต่ผู้เล็กน้อย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 20, 'ลูกหลานของเขาจะเป็นเหมือนสมัยก่อน และชุมนุมของเขาจะได้ถูกสถาปนาไว้ต่อหน้าเรา และทุกคนที่บีบบังคับเขา เราจะลงโทษ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 21, 'ขุนนางของเขาจะเป็นคนหนึ่งในพวกเขาทั้งหลาย ผู้ครอบครองของเขาจะออกมาจากท่ามกลางเขาเอง เราจะกระทําให้ท่านนั้นเข้ามาใกล้ และท่านนั้นจะเข้าใกล้เรา เพราะใครเล่าตั้งใจเข้ามาใกล้เราได้เอง พระเยโฮวาห์ตรัส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 22, 'และเจ้าทั้งหลายจะเป็นประชาชนของเรา และเราจะเป็นพระเจ้าของเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 23, 'ดูเถิด นั่นลมหมุนของพระเยโฮวาห์ได้ออกไปแล้วด้วยพระพิโรธ เป็นลมหมุนกวาด มันจะตกลงอย่างเจ็บปวดบนศีรษะของคนชั่ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 24, 'ความกริ้วอันแรงกล้าของพระเยโฮวาห์จะไม่หยุดยั้ง จนกว่าพระองค์จะทรงกระทํา และให้สําเร็จตามพระประสงค์แห่งพระทัยของพระองค์ ในวาระสุดท้าย เจ้าทั้งหลายจะพิจารณาถึงข้อความนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 1, 'พระเยโฮวาห์ตรัสว่า “ในวาระนั้น เราจะเป็นพระเจ้าของบรรดาครอบครัวแห่งอิสราเอล และเขาทั้งหลายจะเป็นประชาชนของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 2, 'พระเยโฮวาห์ตรัสดังนี้ว่า “ชนชาติที่รอดตายจากดาบได้ประสบพระกรุณาคุณที่ในถิ่นทุรกันดาร คืออิสราเอล เมื่อเราให้เขาหยุดพัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 3, 'พระเยโฮวาห์ทรงปรากฏแก่ข้าพเจ้าแต่ก่อน ตรัสว่า ‘เราได้รักเจ้าด้วยความรักนิรันดร์ เพราะฉะนั้นเราจึงชวนเจ้ามาด้วยความเมตตา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 4, 'เราจะสร้างเจ้าอีก และเจ้าจะถูกสร้างใหม่นะ โอ อิสราเอลพรหมจารีเอ๋ย เจ้าจะตกแต่งตัวเจ้าด้วยรํามะนาอีก และจะออกไปเต้นรํากับผู้ที่สนุกสนานกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 5, 'เจ้าจะปลูกสวนองุ่นที่บนภูเขาสะมาเรียอีก ผู้ปลูกก็จะปลูก และจะกินผลนั้น’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 6, 'เพราะว่าจะมีวันหนึ่งเมื่อคนเฝ้ายามที่อยู่บนแดนเทือกเขาเอฟราอิมจะร้องเรียกว่า ‘จงลุกขึ้น ให้เราไปยังศิโยนเถิด ไปเฝ้าพระเยโฮวาห์ พระเจ้าของเรา’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 7, 'เพราะพระเยโฮวาห์ตรัสดังนี้ว่า “จงร้องเพลงด้วยความยินดีเพราะยาโคบ และเปล่งเสียงโห่ร้องเพราะประมุขของบรรดาประชาชาติ จงป่าวร้อง สรรเสริญ และกล่าวว่า ‘โอ ข้าแต่พระเยโฮวาห์ ขอทรงช่วยประชาชนของพระองค์ให้รอด คือคนที่เหลืออยู่ของอิสราเอล’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 8, 'ดูเถิด เราจะนําเขามาจากแดนเหนือ และรวบรวมเขาจากส่วนที่ไกลที่สุดของพิภพ มีคนตาบอด คนง่อยอยู่ท่ามกลางเขา ผู้หญิงที่มีครรภ์และผู้หญิงที่คลอดบุตรจะมาด้วยกัน เขาจะกลับมาที่นี่เป็นหมู่ใหญ่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 9, 'เขาจะมาด้วยการร้องไห้ และด้วยการทูลวิงวอนเราก็จะนําเขา เราจะให้เขาเดินตามแม่น้ําเป็นทางตรง ซึ่งเขาจะไม่สะดุด เพราะเราเป็นบิดาแก่อิสราเอล และเอฟราอิมเป็นบุตรหัวปีของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 10, 'โอ บรรดาประชาชาติเอ๋ย จงฟังพระวจนะของพระเยโฮวาห์ และจงประกาศพระวจนะนั้นในเกาะทั้งหลายที่ห่างออกไป จงกล่าวว่า ‘ท่านที่กระจายอิสราเอลนั้นจะรวบรวมเขา และจะดูแลเขาอย่างกับผู้เลี้ยงแกะดูแลฝูงแกะของเขา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 11, 'เพราะพระเยโฮวาห์ทรงไถ่ยาโคบไว้แล้ว และได้ไถ่เขามาจากมือที่แข็งแรงเกินกว่าเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 12, 'เขาทั้งหลายจึงจะมาร้องเพลงอยู่บนที่สูงแห่งศิโยน และเขาจะไปอย่างราบรื่นเพราะความดีของพระเยโฮวาห์ เพราะเมล็ดข้าว น้ําองุ่น และน้ํามัน และเพราะลูกของแกะและวัว ชีวิตของเขาทั้งหลายจะเหมือนกับสวนที่มีน้ํารด และเขาจะไม่โศกเศร้าอีกต่อไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 13, 'แล้วพวกพรหมจารีจะเปรมปรีดิ์ในการเต้นรํา ทั้งคนหนุ่มกับคนแก่ด้วยกัน เราจะกลับความโศกเศร้าของเขาให้เป็นความชื่นบาน เราจะปลอบโยนเขา และให้ความยินดีแก่เขาแทนความเศร้าโศก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 14, 'เราจะเลี้ยงจิตใจของปุโรหิตด้วยความอุดมสมบูรณ์ และประชาชนของเราจะพอใจด้วยความดีของเรา” พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 15, 'พระเยโฮวาห์ตรัสดังนี้ว่า “ได้ยินเสียงในรามาห์ เป็นเสียงโอดครวญและร่ําไห้ ราเชลร้องไห้คร่ําครวญเพราะบุตรทั้งหลายของตน นางไม่รับคําเล้าโลมในเรื่องบุตรทั้งหลายของตน เพราะว่าบุตรทั้งหลายนั้นไม่มีแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 16, 'พระเยโฮวาห์ตรัสดังนี้ว่า “ระงับเสียงร้องไห้คร่ําครวญไว้ และระงับน้ําตาจากตาของเจ้าเสีย เพราะว่าการงานของเจ้าจะได้รับรางวัล พระเยโฮวาห์ตรัสดังนี้แหละ และเขาทั้งหลายจะกลับมาจากแผ่นดินของศัตรู”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 17, 'พระเยโฮวาห์ตรัสว่า “เรื่องอนาคตของเจ้ายังมีหวัง ว่าลูกหลานของเจ้าจะกลับมายังพรมแดนของเขาเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 18, 'เราได้ยินเอฟราอิมคร่ําครวญว่า ‘พระองค์ทรงตีสอนข้าพระองค์ และข้าพระองค์ก็ถูกตีสอน อย่างลูกวัวที่ยังไม่เชื่อง ขอทรงนําข้าพระองค์กลับ เพื่อข้าพระองค์จะได้กลับสู่สภาพเดิม เพราะพระองค์ทรงเป็นพระเยโฮวาห์พระเจ้าของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 19, 'เพราะแน่นอนหลังจากที่ข้าพระองค์หันไปเสีย ข้าพระองค์ก็กลับใจ และหลังจากที่ข้าพระองค์รับคําสั่งสอนแล้ว ข้าพระองค์ก็ทุบตีต้นขาของข้าพระองค์ ข้าพระองค์อับอาย และข้าพระองค์ก็ขายหน้า เพราะว่าข้าพระองค์ได้ทนความถูกหยามหน้าซึ่งเกิดขึ้นเมื่อยังหนุ่มอยู่’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 20, 'พระเยโฮวาห์ตรัสว่า “เอฟราอิมเป็นบุตรชายที่รักของเราหรือ เขาเป็นลูกที่รักของเราหรือ เพราะตั้งแต่เราพูดกล่าวโทษเขาตราบใด เราก็ยังระลึกถึงเขาอยู่ตราบนั้น เพราะฉะนั้นจิตใจของเราจึงอาลัยเขา เราจะมีความกรุณาต่อเขาแน่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 21, 'จงปักเสากรุยทางไว้สําหรับตน จงทําป้ายบอกทางไว้สําหรับตัว จงปักใจให้ดีถึงทางหลวง คือทางซึ่งเจ้าได้ไปนั้น โอ อิสราเอลพรหมจารีเอ๋ย จงกลับเถิด จงกลับมายังหัวเมืองเหล่านี้ของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 22, 'โอ บุตรสาวผู้กลับสัตย์เอ๋ย เจ้าจะเถลไถลอยู่อีกนานสักเท่าใด เพราะพระเยโฮวาห์ได้สร้างสิ่งใหม่บนพิภพแล้ว คือ ผู้หญิงจะล้อมผู้ชาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 23, 'พระเยโฮวาห์จอมโยธา พระเจ้าแห่งอิสราเอล ตรัสดังนี้ว่า “เมื่อเราจะให้การเป็นเชลยของเขากลับสู่สภาพเดิม เขาจะใช้ถ้อยคําต่อไปนี้ในแผ่นดินของยูดาห์ และในหัวเมืองทั้งหลายอีกครั้งหนึ่ง คือ โอ ที่อยู่แห่งความเที่ยงธรรมเอ๋ย ภูเขาบริสุทธิ์เอ๋ย ขอพระเยโฮวาห์ทรงอํานวยพระพรเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 24, 'ยูดาห์และหัวเมืองทั้งสิ้นนั้น ทั้งบรรดาชาวนา บรรดาผู้ที่ท่องเที่ยวไปมาพร้อมกับฝูงแกะของเขา จะอาศัยอยู่ด้วยกันที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 25, 'เพราะเราจะให้จิตใจที่อ่อนระอานั้นอิ่ม และจิตใจที่โศกเศร้าทุกดวงเราจะให้บริบูรณ์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 26, 'เมื่อนั้น ข้าพเจ้าตื่นขึ้นและมองดู และการหลับนอนของข้าพเจ้าก็เป็นที่ชื่นใจข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 27, 'พระเยโฮวาห์ตรัสว่า “ดูเถิด วันเวลาจะมาถึง เมื่อเราจะเพาะเชื้อสายของคนและเชื้อสายของสัตว์ในวงศ์วานอิสราเอลและวงศ์วานยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 28, 'และจะเป็นไปอย่างนี้ คือเมื่อเราเฝ้าดูเขา เพื่อจะถอนออกและพังลงคว่ําเสีย ทําลาย และนําเหตุร้ายมาฉันใด เราจะเฝ้าดูเหนือเขาเพื่อจะสร้างขึ้นและปลูกฝังฉันนั้น” พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 29, '“ในสมัยนั้น เขาจะไม่กล่าวต่อไปอีกว่า ‘บิดารับประทานองุ่นเปรี้ยวและบุตรก็เข็ดฟัน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 30, 'แต่ทุกคนจะต้องตายเพราะความชั่วช้าของตนเอง มนุษย์ทุกคนที่รับประทานองุ่นเปรี้ยว ก็จะเข็ดฟัน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 31, 'พระเยโฮวาห์ตรัสว่า “ดูเถิด วันเวลาจะมาถึง ซึ่งเราจะทําพันธสัญญาใหม่กับวงศ์วานอิสราเอลและวงศ์วานยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 32, 'ไม่เหมือนกับพันธสัญญาซึ่งเราได้กระทํากับบรรพบุรุษของเขาทั้งหลาย ในวันที่เราจูงมือเขาเพื่อนําเขาออกมาจากแผ่นดินอียิปต์ เป็นพันธสัญญาของเราซึ่งเขาผิด ถึงแม้ว่าเราได้เป็นสามีของเขา” พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 33, '“แต่นี่จะเป็นพันธสัญญาซึ่งเราจะกระทํากับวงศ์วานอิสราเอล ภายหลังสมัยนั้น” พระเยโฮวาห์ตรัสดังนี้แหละ “เราจะบรรจุราชบัญญัติของเราไว้ภายในเขาทั้งหลาย และเราจะจารึกมันไว้ที่ในดวงใจของเขาทั้งหลาย และเราจะเป็นพระเจ้าของเขา และเขาจะเป็นประชาชนของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 34, 'และทุกคนจะไม่สอนเพื่อนบ้านของตนและพี่น้องของตนแต่ละคนอีกว่า ‘จงรู้จักพระเยโฮวาห์’ เพราะเขาทั้งหลายจะรู้จักเราหมด ตั้งแต่คนเล็กน้อยที่สุดถึงคนใหญ่โตที่สุด” พระเยโฮวาห์ตรัสดังนี้แหละ “เพราะเราจะให้อภัยความชั่วช้าของเขา และจะไม่จดจําบาปของเขาทั้งหลายอีกต่อไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 35, 'พระเยโฮวาห์ผู้ทรงให้ดวงอาทิตย์เป็นสว่างกลางวัน และทรงให้ระเบียบตายตัวของดวงจันทร์ และทรงให้บรรดาดวงดาวเป็นสว่างกลางคืน ผู้ทรงกวนทะเลให้คลื่นกําเริบ พระนามของพระองค์คือพระเยโฮวาห์จอมโยธา ตรัสดังนี้ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 36, '“ถ้าระเบียบตายตัวนี้ต้องพรากไปจากต่อหน้าเรา แล้วเชื้อสายของอิสราเอลก็จะต้องหยุดยั้งจากการเป็นประชาชาติหนึ่งต่อหน้าเราเป็นนิตย์” พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 37, 'พระเยโฮวาห์ตรัสดังนี้ว่า “ถ้าฟ้าสวรรค์เบื้องบนเป็นที่วัดได้ และรากฐานของพิภพเบื้องล่างเป็นที่ให้สํารวจได้ แล้วเราก็จะเหวี่ยงเชื้อสายอิสราเอลทิ้งไปเสียหมด ด้วยเหตุบรรดาการซึ่งเขาได้กระทํานั้น” พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 38, 'พระเยโฮวาห์ตรัสว่า “ดูเถิด วันเวลาจะมาถึง ที่เมืองนี้จะต้องสร้างขึ้นใหม่เพื่อพระเยโฮวาห์ตั้งแต่หอคอยฮานันเอลไปถึงประตูมุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 39, 'และเชือกวัดจะไปไกลกว่านั้นตรงไปถึงเนินเขากาเรบ แล้วจะเลี้ยวไปถึงตําบลโกอาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 40, 'หุบเขาแห่งซากศพและขี้เถ้าทั้งสิ้นนั้น และทุ่งนาทั้งหมดไกลไปจนถึงลําธารขิดโรนจนถึงมุมประตูม้าไปทางตะวันออก จะเป็นที่บริสุทธิ์แด่พระเยโฮวาห์ จะไม่เป็นที่ถอนรากหรือคว่ําต่อไปอีกเป็นนิตย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 1, 'พระวจนะซึ่งมาจากพระเยโฮวาห์ถึงเยเรมีย์ในปีที่สิบแห่งเศเดคียาห์กษัตริย์ของยูดาห์ ซึ่งเป็นปีที่สิบแปดของเนบูคัดเนสซาร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 2, 'ครั้งนั้น กองทัพของกษัตริย์แห่งบาบิโลนกําลังล้อมกรุงเยรูซาเล็มอยู่ และเยเรมีย์ผู้พยากรณ์ถูกขังอยู่ในบริเวณทหารรักษาพระองค์ ซึ่งอยู่ในพระราชวังของกษัตริย์แห่งยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 3, 'เพราะเศเดคียาห์กษัตริย์แห่งยูดาห์ได้คุมขังท่านไว้ ตรัสว่า “ทําไมท่านจึงพยากรณ์และกล่าวว่า ‘พระเยโฮวาห์ตรัสดังนี้ว่า ดูเถิด เราจะให้เมืองนี้ไว้ในมือของกษัตริย์แห่งบาบิโลน และเขาจะยึดเมืองนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 4, 'เศเดคียาห์กษัตริย์แห่งยูดาห์จะหนีไปไม่พ้นจากมือของคนเคลเดีย แต่จะถูกมอบไว้ในมือของกษัตริย์แห่งบาบิโลนเป็นแน่ และจะได้พูดกันปากต่อปาก และจะแลเห็นตาต่อตา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 5, 'และเขาจะนําเศเดคียาห์ไปยังบาบิโลน และท่านจะอยู่ที่นั่นจนกว่าเราจะไปเยี่ยมท่าน พระเยโฮวาห์ตรัสดังนี้แหละ ถึงแม้เจ้าจะต่อสู้กับชาวเคลเดีย เจ้าก็จะไม่เจริญ’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 6, 'เยเรมีย์ทูลว่า “พระวจนะของพระเยโฮวาห์มายังข้าพระองค์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 7, 'ดูเถิด ฮานัมเอลบุตรชายชัลลูม อาของเจ้าจะมาหาเจ้าและกล่าวว่า ‘จงซื้อนาของข้าพเจ้าซึ่งอยู่ที่อานาโธท เพราะว่าสิทธิของการไถ่ด้วยการซื้อนั้นเป็นของท่าน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 8, 'แล้วฮานัมเอลลูกของอาของข้าพเจ้ามาหาข้าพเจ้าที่บริเวณของทหารรักษาพระองค์ถูกต้องตามพระวจนะของพระเยโฮวาห์ และพูดกับข้าพเจ้าว่า ‘จงซื้อนาของข้าพเจ้าซึ่งอยู่ที่อานาโธทในแผ่นดินเบนยามิน เพราะสิทธิของการถือกรรมสิทธิ์และการไถ่เป็นของท่าน จงซื้อไว้เถิด’ แล้วข้าพระองค์จึงทราบว่านี่เป็นพระวจนะของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 9, 'และข้าพระองค์ก็ซื้อนาที่อานาโธทจากฮานัมเอลลูกของอาของข้าพระองค์ และได้ชั่งเงินให้แก่เขา คือเงินสิบเจ็ดเชเขล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 10, 'ข้าพระองค์ก็ลงนามในโฉนดประทับตราไว้ เป็นพยานและเอาตาชั่งชั่งเงิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 11, 'แล้วข้าพระองค์ก็รับโฉนดของการซื้อทั้งฉบับที่ประทับตราแล้วตามกฎหมายและธรรมเนียมและฉบับที่เปิดอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 12, 'และข้าพระองค์ก็มอบโฉนดของการซื้อให้แก่บารุคบุตรชายเนริยาห์ ผู้เป็นบุตรชายของมาอาเสอาห์ ต่อสายตาของฮานัมเอลลูกของอาของข้าพระองค์ ต่อหน้าพยานผู้ที่ลงนามในโฉนดการซื้อและต่อหน้าบรรดาพวกยิว ผู้ซึ่งนั่งอยู่ในบริเวณทหารรักษาพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 13, 'ข้าพระองค์ก็กําชับบารุคต่อหน้าเขาทั้งหลายว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 14, '‘พระเยโฮวาห์จอมโยธา พระเจ้าแห่งอิสราเอลตรัสดังนี้ว่า จงเอาโฉนดเหล่านี้ไปเสีย ทั้งโฉนดของการซื้อที่ประทับตรากับฉบับที่เปิดนี้ และบรรจุไว้ในภาชนะดินเพื่อจะทนอยู่ได้หลายวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 15, 'เพราะพระเยโฮวาห์จอมโยธา พระเจ้าแห่งอิสราเอลตรัสดังนี้ว่า บ้านเรือนและไร่นาและสวนองุ่นจะมีการถือกรรมสิทธิ์กันอีกในแผ่นดินนี้’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 16, 'หลังจากที่ข้าพระองค์มอบโฉนดการซื้อให้แก่บารุคบุตรชายเนริยาห์แล้ว ข้าพระองค์ได้อธิษฐานต่อพระเยโฮวาห์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 17, '‘ข้าแต่องค์พระผู้เป็นเจ้าพระเจ้า ดูเถิด คือพระองค์เอง ผู้ได้ทรงสร้างฟ้าสวรรค์และแผ่นดินโลก ด้วยฤทธานุภาพใหญ่ยิ่งของพระองค์และด้วยพระกรซึ่งเหยียดออกของพระองค์ สําหรับพระองค์ไม่มีสิ่งใดที่ยากเกิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 18, 'ผู้ทรงสําแดงความเมตตาต่อคนเป็นพันๆ แต่ทรงตอบสนองความชั่วช้าของบิดาให้ตกถึงอกของลูกหลานสืบต่อมา ข้าแต่พระเจ้าผู้ใหญ่ยิ่งและทรงฤทธิ์ พระนามของพระองค์คือพระเยโฮวาห์จอมโยธา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 19, 'พระองค์ทรงเป็นใหญ่ในการให้คําปรึกษา ทรงฤทธานุภาพในพระราชกิจ พระเนตรของพระองค์เห็นทุกวิถีทางบุตรทั้งหลายของมนุษย์ ประทานรางวัลแก่ทุกคนตามพฤติการณ์ของเขาและตามผลแห่งการกระทําของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 20, 'ทรงเป็นผู้สําแดงหมายสําคัญและการมหัศจรรย์ในแผ่นดินอียิปต์ และจนถึงสมัยนี้ก็ทรงสําแดงในอิสราเอลและท่ามกลางมนุษยชาติ และทรงทําให้พระนามเลื่องลือไปอย่างทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 21, 'พระองค์ได้ทรงนําอิสราเอลประชาชนของพระองค์ออกจากแผ่นดินอียิปต์ ด้วยหมายสําคัญและการมหัศจรรย์ และด้วยพระหัตถ์เข้มแข็ง และพระกรที่เหยียดออก และด้วยความสยดสยองยิ่งนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 22, 'และพระองค์ประทานแผ่นดินนี้แก่เขาทั้งหลาย ซึ่งพระองค์ทรงปฏิญาณแก่บรรพบุรุษของเขาทั้งหลายว่าจะประทานแก่เขา คือแผ่นดินซึ่งมีน้ํานมและน้ําผึ้งไหลบริบูรณ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 23, 'และเขาทั้งหลายก็ได้เข้าไปและถือกรรมสิทธิ์แผ่นดินนั้น แต่เขาทั้งหลายมิได้เชื่อฟังพระสุรเสียงของพระองค์ หรือดําเนินตามพระราชบัญญัติของพระองค์ สิ่งทั้งปวงซึ่งพระองค์ทรงบัญชาเขาให้กระทํานั้น เขาทั้งหลายมิได้กระทําเสียเลย เพราะฉะนั้นพระองค์ทรงกระทําให้เหตุร้ายทั้งสิ้นนี้มาถึงเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 24, 'ดูเถิด เชิงเทินที่ล้อมอยู่ได้มาถึงกรุงเพื่อจะยึดเอาแล้ว และเพราะเหตุด้วยดาบ การกันดารอาหาร และโรคระบาด เมืองนี้ก็ได้ถูกมอบไว้ในมือของคนเคลเดียผู้กําลังต่อสู้อยู่นั้นแล้ว พระองค์ตรัสสิ่งใดก็เป็นไปอย่างนั้นแล้ว และดูเถิด พระองค์ทอดพระเนตรเห็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 25, 'โอ ข้าแต่องค์พระผู้เป็นเจ้าพระเจ้า พระองค์ยังตรัสแก่ข้าพระองค์ว่า “จงเอาเงินซื้อนาและหาพยานเสีย” แม้ว่าเมืองนั้นจะถูกมอบไว้ในมือของคนเคลเดีย’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 26, 'พระวจนะของพระเยโฮวาห์มายังเยเรมีย์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 27, '“ดูเถิด เราคือพระเยโฮวาห์พระเจ้าของบรรดาเนื้อหนังทั้งสิ้น สําหรับเรามีสิ่งใดที่ยากเกินหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 28, 'เพราะฉะนั้นพระเยโฮวาห์ตรัสดังนี้ว่า ดูเถิด เราจะมอบเมืองนี้ไว้ในมือของชาวเคลเดีย และในมือของเนบูคัดเนสซาร์กษัตริย์แห่งบาบิโลน และเขาจะยึดเอาแน่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 29, 'ชาวเคลเดียผู้ต่อสู้กับเมืองนี้ จะมาเผาเมืองนี้เสียด้วยไฟให้ไหม้หมด ทั้งบรรดาบ้านที่เขาเผาเครื่องถวายพระบาอัลที่บนหลังคา และเทเครื่องดื่มบูชาถวายแก่พระอื่นเพื่อยั่วเย้าเราให้กริ้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 30, 'เพราะประชาชนของอิสราเอลและประชาชนของยูดาห์ไม่ได้กระทําอะไรเลย นอกจากความชั่วต่อหน้าต่อตาของเราตั้งแต่หนุ่มๆมา พระเยโฮวาห์ตรัสว่า ประชาชนอิสราเอลไม่ได้กระทําอะไรเลย นอกจากยั่วเย้าเราให้กริ้วด้วยผลงานแห่งมือของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 31, 'เมืองนี้ได้เร้าความกริ้วและความพิโรธของเรา ตั้งแต่วันที่ได้สร้างมันขึ้นจนถึงวันนี้ เพราะฉะนั้นเราจะถอนออกไปเสียจากหน้าของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 32, 'เพราะว่าความชั่วทั้งสิ้นของประชาชนอิสราเอล และประชาชนยูดาห์ซึ่งเขาได้กระทําอันยั่วเย้าให้โกรธ คือทั้งตัวเขา บรรดากษัตริย์และเจ้านายของเขา บรรดาปุโรหิตและผู้พยากรณ์ของเขา คนยูดาห์และชาวกรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 33, 'เขาทั้งหลายได้หันหลังให้เรา มิใช่หันหน้า แม้ว่าเราได้สอนเขาอยู่อย่างไม่หยุดยั้ง เขาก็มิได้ฟังที่จะรับคําสั่งสอนของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 34, 'แต่เขาทั้งหลายได้ตั้งสิ่งที่น่าสะอิดสะเอียนของเขาไว้ในนิเวศ ซึ่งเรียกตามนามของเรา กระทําให้มีมลทิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 35, 'เขาทั้งหลายได้สร้างปูชนียสถานสูงสําหรับพระบาอัลซึ่งอยู่ในหุบเขาแห่งบุตรชายของฮินโนม เพื่อให้บุตรชายและบุตรสาวของเขาลุยไฟถวายแก่พระโมเลค ซึ่งเรามิได้บัญชาเขาเลยและไม่ได้มีอยู่ในจิตใจของเราว่า เขาควรจะกระทําสิ่งที่น่าสะอิดสะเอียนนี้เพื่อเป็นเหตุให้ยูดาห์กระทําผิดบาปไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 36, 'เพราะฉะนั้นบัดนี้ พระเยโฮวาห์พระเจ้าแห่งอิสราเอลตรัสเกี่ยวกับเมืองนี้แก่เจ้าทั้งหลายว่า ‘เมืองนี้จะถูกยกให้ไว้ในมือของกษัตริย์แห่งบาบิโลน ด้วยดาบ ด้วยการกันดารอาหาร และด้วยโรคระบาด’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 37, 'ดูเถิด เราจะรวบรวมเขามาจากประเทศทั้งปวง ซึ่งเราได้ขับไล่เขาให้ไปอยู่ด้วยความกริ้ว ด้วยความพิโรธ และความขึ้งโกรธของเรานั้น เราจะนําเขาทั้งหลายกลับมายังที่นี้ และจะกระทําให้เขาอาศัยอยู่อย่างปลอดภัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 38, 'เขาทั้งหลายจะเป็นประชาชนของเรา และเราจะเป็นพระเจ้าของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 39, 'เราจะให้ใจเดียวและทางเดียวแก่เขา เพื่อเขาจะยําเกรงเราอยู่เป็นนิตย์ เพื่อเป็นประโยชน์แก่เขา และแก่ลูกหลานของเขาที่ตามเขามา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 40, 'เราจะกระทําพันธสัญญานิรันดร์กับเขาทั้งหลายว่า เราจะไม่หันจากเขาทั้งหลายเพื่อกระทําความดีแก่เขา แต่เราจะบรรจุความยําเกรงเราไว้ในใจของเขาทั้งหลาย เพื่อว่าเขาจะมิได้หันไปจากเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 41, 'เออ เราจะเปรมปรีดิ์ในการที่จะกระทําความดีแก่เขา และเราจะปลูกเขาไว้ในแผ่นดินนี้ด้วยความมุ่งมั่น ด้วยสุดใจของเราและสุดจิตของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 42, 'เพราะพระเยโฮวาห์ตรัสดังนี้ว่า เราได้นําเอาความร้ายยิ่งใหญ่ทั้งสิ้นมาเหนือชนชาตินี้ฉันใด เราก็จะนําความดีทั้งสิ้นซึ่งเราได้สัญญาไว้นั้นมาเหนือเขาฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 43, 'และจะมีการซื้อนากันในแผ่นดินนี้ซึ่งเจ้ากล่าวถึงว่า เป็นที่รกร้างปราศจากมนุษย์หรือสัตว์ ถูกมอบไว้ในมือของคนเคลเดีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 44, 'ที่นานั้นจะซื้อกันด้วยเงิน ใบโฉนดก็จะต้องลงนามและประทับตรา และลงนามพยานที่ในแผ่นดินของเบนยามิน ในที่ต่างๆแถบกรุงเยรูซาเล็ม และในหัวเมืองยูดาห์ ในหัวเมืองแถบแดนเมืองเทือกเขา ในหัวเมืองแถบหุบเขา และในหัวเมืองแถบภาคใต้ เพราะเราจะให้การเป็นเชลยของเขาทั้งหลายกลับสู่สภาพเดิม” พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 1, 'พระวจนะของพระเยโฮวาห์มายังเยเรมีย์ครั้งที่สอง เมื่อท่านยังถูกกักตัวอยู่ในบริเวณของทหารรักษาพระองค์นั้นว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 2, '“พระเยโฮวาห์ผู้ทรงสร้าง พระเยโฮวาห์ผู้ทรงปั้นเพื่อสถาปนาไว้ พระเยโฮวาห์คือพระนามของพระองค์ ตรัสดังนี้ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 3, 'จงทูลเรา และเราจะตอบเจ้า และจะสําแดงสิ่งที่ใหญ่ยิ่งและที่มีอํานาจใหญ่โต ซึ่งเจ้าไม่รู้นั้นให้แก่เจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 4, 'เพราะว่าพระเยโฮวาห์พระเจ้าแห่งอิสราเอลได้ตรัสดังนี้เกี่ยวด้วยเรื่องบ้านในกรุงนี้ และเกี่ยวด้วยเรื่องพระราชวังของบรรดากษัตริย์แห่งยูดาห์ ซึ่งถูกรื้อลง เพื่อทําการต่อต้านเชิงเทินและดาบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 5, 'เขาทั้งหลายจะมารบกับชาวเคลเดียและทําให้คนเป็นศพไปเต็มบ้านเต็มเรือน เป็นคนที่เราสังหารด้วยความกริ้วและความพิโรธของเรา เพราะได้ซ่อนหน้าของเราจากกรุงนี้เนื่องด้วยความชั่วของเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 6, 'ดูเถิด เราจะนําอนามัย และการรักษามาให้ และเราจะรักษาเขาทั้งหลายให้หาย และเผยสันติภาพและความจริงอย่างอุดม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 7, 'เราจะให้พวกเชลยแห่งยูดาห์และพวกเชลยแห่งอิสราเอลกลับสู่สภาพเดิม และจะสร้างเขาทั้งหลายเสียใหม่อย่างที่เขาเป็นมาแต่เดิมนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 8, 'เราจะชําระเขาจากบรรดาความชั่วช้าของเขาซึ่งเขาได้กระทําต่อเรา และจะให้อภัยบรรดาความชั่วช้าของเขาซึ่งเขาได้กระทํา และการละเมิดของเขาต่อเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 9, 'และกรุงนี้จะให้เรามีชื่ออันให้ความชื่นบาน เป็นที่สรรเสริญและเป็นศักดิ์ศรีต่อหน้าบรรดาประชาชาติทั้งสิ้นแห่งแผ่นดินโลก ซึ่งจะได้ยินถึงความดีทั้งสิ้นซึ่งเราได้กระทําเพื่อเขาทั้งหลาย เขาจะกลัวและสะทกสะท้าน เพราะความดีและความเจริญทั้งสิ้นซึ่งเราได้จัดหาให้เมืองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 10, 'พระเยโฮวาห์ตรัสดังนี้ว่า และจะมีเสียงให้ได้ยินกันอีกครั้งในสถานที่นี้ซึ่งเจ้ากล่าวว่า จะเป็นที่รกร้างปราศจากมนุษย์และปราศจากสัตว์ ในหัวเมืองแห่งยูดาห์และตามถนนในกรุงเยรูซาเล็มซึ่งร้างเปล่า ปราศจากมนุษย์ ปราศจากคนอาศัย และปราศจากสัตว์ใดๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 11, 'ที่นั่นจะได้ยินเสียงบันเทิงและเสียงรื่นเริง และเสียงเจ้าบ่าวและเสียงเจ้าสาว และเสียงบรรดาคนเหล่านั้นที่ร้องเพลงอีก ขณะที่เขานําเครื่องบูชาแห่งการสรรเสริญมายังพระนิเวศของพระเยโฮวาห์ ว่า ‘จงสรรเสริญพระเยโฮวาห์จอมโยธา เพราะพระเยโฮวาห์ประเสริฐ เพราะความเมตตาของพระองค์ดํารงอยู่เป็นนิตย์’ เพราะเราจะให้พวกเชลยแห่งแผ่นดินนั้นกลับสู่สภาพเดิม พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 12, 'พระเยโฮวาห์จอมโยธาตรัสดังนี้ว่า ในสถานที่นี้ซึ่งเป็นที่รกร้าง ปราศจากมนุษย์และปราศจากสัตว์ และในหัวเมืองทั้งสิ้นของที่นี้ จะเป็นที่อาศัยของผู้เลี้ยงแกะทั้งหลายให้แกะของเขาได้นอนลงอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 13, 'พระเยโฮวาห์ตรัสว่า ในหัวเมืองแถบแดนเทือกเขา ในหัวเมืองแถบหุบเขา ในหัวเมืองแถบภาคใต้ ในแผ่นดินแห่งเบนยามิน ตามสถานที่รอบกรุงเยรูซาเล็ม ในหัวเมืองยูดาห์ จะมีฝูงแกะผ่านใต้มือของผู้ที่นับอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 14, 'พระเยโฮวาห์ตรัสว่า ดูเถิด วันนั้นจะมาถึง คือเมื่อเราจะให้สิ่งดีที่เราสัญญาไว้ต่อวงศ์วานอิสราเอลและวงศ์วานยูดาห์สําเร็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 15, 'ในวันเหล่านั้นและในเวลานั้น เราจะให้อังกูรชอบธรรมเกิดมาเพื่อดาวิด และท่านจะให้ความยุติธรรมและความชอบธรรมในแผ่นดินนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 16, 'ในกาลครั้งนั้น ยูดาห์จะได้รับการช่วยให้รอด และเยรูซาเล็มจะอาศัยอยู่อย่างปลอดภัย และนี่เป็นชื่อซึ่งเขาจะเรียกเมืองนั้นคือ ‘พระเยโฮวาห์ทรงเป็นความชอบธรรมของเรา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 17, 'เพราะพระเยโฮวาห์ตรัสดังนี้ว่า ดาวิดจะไม่ขัดสนบุรุษที่จะประทับบนพระที่นั่งแห่งวงศ์วานอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 18, 'และปุโรหิตคนเลวีจะไม่ขัดสนบุรุษที่อยู่ต่อหน้าเรา เพื่อถวายเครื่องเผาบูชา และเผาเครื่องธัญญบูชา และกระทําการสักการบูชาเป็นนิตย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 19, 'พระวจนะของพระเยโฮวาห์มายังเยเรมีย์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 20, '“พระเยโฮวาห์ตรัสดังนี้ว่า ถ้าเจ้าหักพันธสัญญาของเราด้วยวัน และหักพันธสัญญาของเราด้วยคืนได้ จนวันและคืนมาถึงตามเวลากําหนดไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 21, 'แล้วจึงจะหักพันธสัญญาของเราซึ่งมีต่อดาวิดผู้รับใช้ของเราได้ จนท่านไม่มีโอรสที่จะเสวยราชย์บนพระที่นั่งของท่าน และหักพันธสัญญาของเรา ซึ่งมีต่อปุโรหิตคนเลวีผู้ปรนนิบัติของเราเสียได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 22, 'บริวารของฟ้าสวรรค์จะนับไม่ได้ และเม็ดทรายที่ทะเลก็ตวงไม่ได้ฉันใด เราก็จะให้เชื้อสายของดาวิดผู้รับใช้ของเราและคนเลวีผู้ปรนนิบัติของเราทวีมากขึ้นฉันนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 23, 'พระวจนะของพระเยโฮวาห์มาถึงเยเรมีย์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 24, '“เจ้าไม่ได้พิจารณาดอกหรือว่า ประชาชนเหล่านี้พูดกันอย่างไร คือพูดกันว่า ‘พระเยโฮวาห์ทรงทอดทิ้งสองครอบครัวที่พระองค์ทรงเลือกไว้เสียแล้ว’ ดังนี้แหละ เขาทั้งหลายได้ดูหมิ่นประชาชนของเรา ฉะนี้เขาจึงไม่เป็นประชาชาติต่อหน้าเขาทั้งหลายอีกต่อไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 25, 'พระเยโฮวาห์ตรัสดังนี้ว่า ถ้าเรามิได้สถาปนาพันธสัญญาของเรากับวันและคืน และสถาปนากฎต่างๆของฟ้าสวรรค์และแผ่นดินโลกแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 26, 'เราจึงจะทอดทิ้งเชื้อสายของยาโคบและดาวิดผู้รับใช้ของเรา และจะไม่เลือกผู้หนึ่งจากเชื้อสายของเขาให้ครอบครองเหนือเชื้อสายของอับราฮัม อิสอัคและยาโคบ เพราะเราจะให้การเป็นเชลยของเขากลับสู่สภาพเดิม และจะมีความกรุณาเหนือเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 1, 'พระวจนะซึ่งมาจากพระเยโฮวาห์ถึงเยเรมีย์ เมื่อเนบูคัดเนสซาร์กษัตริย์แห่งเมืองบาบิโลน และกองทัพทั้งหมดของพระองค์ และบรรดาราชอาณาจักรในแผ่นดินโลกซึ่งอยู่ใต้การครอบครองของพระองค์ และชนชาติทั้งหลายที่ต่อสู้กับกรุงเยรูซาเล็ม และหัวเมืองทั้งปวงของกรุงนั้นว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 2, '“พระเยโฮวาห์พระเจ้าแห่งอิสราเอลตรัสดังนี้ว่า จงไปพูดกับเศเดคียาห์กษัตริย์แห่งยูดาห์และกล่าวแก่ท่านว่า ‘พระเยโฮวาห์ตรัสดังนี้ว่า ดูเถิด เราจะมอบกรุงนี้ไว้ในมือกษัตริย์บาบิโลน และเขาจะเผาเสียด้วยไฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 3, 'ท่านจะไม่รอดไปจากมือของเขา แต่จะถูกจับแน่และถูกมอบไว้ในมือของเขา ท่านจะได้เห็นกษัตริย์แห่งบาบิโลนตาต่อตา และจะได้พูดกันปากต่อปาก และท่านจะต้องไปยังบาบิโลน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 4, 'โอ ข้าแต่เศเดคียาห์กษัตริย์แห่งยูดาห์ อย่างไรก็ดีขอทรงสดับพระวจนะของพระเยโฮวาห์ พระเยโฮวาห์ตรัสเกี่ยวกับพระองค์ดังนี้ว่า ท่านจะไม่ตายด้วยดาบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 5, 'ท่านจะตายด้วยความสงบ และเขาจะเผาเครื่องหอมเพื่อศพบรรพบุรุษของท่าน คือบรรดากษัตริย์ซึ่งอยู่ก่อนท่านฉันใด คนเขาก็จะเผาเครื่องหอมเพื่อท่านฉันนั้น และเขาจะคร่ําครวญเพื่อท่านว่า ‘อนิจจาเอ๋ย พระองค์เจ้าข้า’ เพราะเราได้ลั่นวาจาไว้แล้ว” พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 6, 'แล้วเยเรมีย์ผู้พยากรณ์ได้ทูลบรรดาพระวจนะเหล่านี้ต่อเศเดคียาห์กษัตริย์แห่งยูดาห์ในกรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 7, 'ขณะเมื่อกองทัพของกษัตริย์แห่งบาบิโลนกําลังสู้รบกรุงเยรูซาเล็มและหัวเมืองแห่งยูดาห์ทั้งสิ้นที่ยังเหลืออยู่ คือ เมืองลาคีชและเมืองอาเซคาห์ เพราะยังเหลืออยู่สองเมืองนี้เท่านั้นที่เป็นหัวเมืองยูดาห์ที่มีกําแพงป้อม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 8, 'พระวจนะซึ่งมาจากพระเยโฮวาห์ยังเยเรมีย์ หลังจากที่กษัตริย์เศเดคียาห์ได้ทรงกระทําพันธสัญญากับบรรดาประชาชนในกรุงเยรูซาเล็มว่า จะประกาศราชกฤษฎีกาเรื่องอิสรภาพแก่เขาทั้งหลาย ดังนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 9, 'ให้ทุกคนปล่อยทาสฮีบรูของตนทั้งชายและหญิงเสียให้เป็นอิสระ เพื่อว่าจะไม่มีผู้ใดกระทําให้ยิวพี่น้องของตนเป็นทาส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 10, 'เมื่อบรรดาเจ้านายและบรรดาประชาชน ผู้เข้ากระทําพันธสัญญาได้ยินว่า ทุกคนจะปล่อยทาสของตนทั้งชายและหญิง เพื่อว่าเขาทั้งหลายจะไม่ถูกกระทําให้เป็นทาสอีก เขาทั้งหลายก็ได้เชื่อฟังและปล่อยทาสให้เป็นอิสระ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 11, 'แต่ภายหลังเขาได้หวนกลับ และจับทาสชายและหญิงซึ่งเขาได้ปล่อยให้เป็นอิสระนั้นมาให้อยู่ใต้บังคับของการเป็นทาสชายและหญิงอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 12, 'พระวจนะแห่งพระเยโฮวาห์จึงมายังเยเรมีย์จากพระเยโฮวาห์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 13, '“พระเยโฮวาห์พระเจ้าแห่งอิสราเอลตรัสดังนี้ว่า เราได้กระทําพันธสัญญากับบรรพบุรุษของเจ้า ในวันที่เรานําเขาออกมาจากแผ่นดินอียิปต์ ออกจากเรือนทาสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 14, 'เมื่อสิ้นเจ็ดปีแล้วเจ้าทุกคนจะต้องปล่อยพี่น้องฮีบรูผู้ที่เขาเอามาขายไว้กับเจ้า และได้รับใช้เจ้ามาหกปี เจ้าต้องปล่อยเขาให้เป็นอิสระพ้นจากการรับใช้เจ้า แต่บรรพบุรุษของเจ้าไม่ฟังเราและไม่เงี่ยหูฟังเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 15, 'บัดนี้เจ้าได้หันกลับและกระทําสิ่งที่ถูกต้องในสายตาของเรา โดยการประกาศอิสรภาพทุกคนต่อเพื่อนบ้านของตน และเจ้าได้กระทําพันธสัญญาต่อหน้าเราในนิเวศซึ่งเรียกตามนามของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 16, 'แต่แล้วเจ้าก็หวนกลับกระทําให้นามของเราเป็นมลทิน ในเมื่อเจ้าทุกคนจับทาสชายหญิงของเจ้า ซึ่งเจ้าได้ปล่อยให้เป็นอิสระไปตามความปรารถนาของเขาทั้งหลายแล้วนั้นกลับมาให้อยู่ใต้บังคับของการเป็นทาสชายและหญิงอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 17, 'เพราะฉะนั้น พระเยโฮวาห์จึงตรัสดังนี้ว่า เจ้าทั้งหลายมิได้เชื่อฟังเราด้วยการป่าวร้องเรื่องอิสรภาพต่อพี่น้องและเพื่อนบ้านของตน พระเยโฮวาห์ตรัสว่า ดูเถิด เราป่าวร้องว่า เจ้าทั้งหลายเป็นอิสระต่อดาบ ต่อโรคระบาด และต่อการกันดารอาหาร เราจะกระทําเจ้าให้ย้ายไปอยู่ในบรรดาราชอาณาจักรของแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 18, 'และคนที่ละเมิดต่อพันธสัญญาของเรา และมิได้กระทําตามข้อตกลงในพันธสัญญาซึ่งเขาได้กระทําต่อหน้าเรานั้น เป็นดังลูกวัวที่เขาตัดออกเป็นสองท่อน และเดินผ่านกลางท่อนเหล่านั้นไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 19, 'เจ้านายแห่งยูดาห์ก็ดี เจ้านายแห่งกรุงเยรูซาเล็มก็ดี ขันทีก็ดี ปุโรหิตและบรรดาประชาชนแห่งแผ่นดินนั้นก็ดี ผู้ผ่านระหว่างท่อนลูกวัวนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 20, 'เราจะมอบเขาไว้ในมือศัตรูของเขา และในมือของบรรดาผู้ที่แสวงหาชีวิตของเขา ศพของเขาจะเป็นอาหารของนกในอากาศและของสัตว์ในแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 21, 'ส่วนเศเดคียาห์กษัตริย์แห่งยูดาห์และเจ้านายทั้งหลายของเขานั้น เราจะมอบไว้ในมือศัตรูของเขา และในมือของบรรดาผู้ที่แสวงหาชีวิตของเขา ในมือของกองทัพแห่งกษัตริย์บาบิโลนซึ่งได้ถอยไปจากเจ้าแล้วนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 22, 'พระเยโฮวาห์ตรัสว่า ดูเถิด เราจะบัญชาและจะกระทําให้เขากลับมายังกรุงนี้ และเขาจะสู้รบกับกรุงนี้ และยึดเอาจนได้ และเผาเสียด้วยไฟ เราจะกระทําให้หัวเมืองยูดาห์เป็นที่รกร้างปราศจากคนอาศัย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 1, 'พระวจนะซึ่งมาจากพระเยโฮวาห์ถึงเยเรมีย์ในรัชกาลเยโฮยาคิมราชบุตรของโยสิยาห์กษัตริย์แห่งยูดาห์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 2, '“จงไปหาวงศ์วานเรคาบและพูดกับเขา และนําเขามาที่พระนิเวศของพระเยโฮวาห์ เข้ามาในห้องเฉลียงห้องหนึ่ง แล้วเชิญให้เขาดื่มเหล้าองุ่น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 3, 'ดังนั้น ข้าพเจ้าจึงนํายาอาซันยาห์ บุตรชายเยเรมีย์ ผู้เป็นบุตรชายฮาบาซินยาห์และพี่น้องของเขา และบุตรชายของเขาทั้งหมด และวงศ์วานเรคาบทั้งหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 4, 'ข้าพเจ้านําเขามายังพระนิเวศของพระเยโฮวาห์ มาในห้องเฉลียงของบุตรชายของฮานัน ผู้เป็นบุตรชายอิกดาลิยาห์ ผู้เป็นคนของพระเจ้า ซึ่งอยู่ใกล้กับห้องเฉลียงของเจ้านาย เหนือห้องเฉลียงของมาอาเสอาห์บุตรชายชัลลูม ผู้ดูแลธรณีประตู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 5, 'แล้วข้าพเจ้าก็วางเหยือกเหล้าองุ่นกับถ้วยหลายใบไว้หน้าเหล่าบุตรชายแห่งวงศ์วานเรคาบ และข้าพเจ้าพูดกับเขาทั้งหลายว่า “เชิญดื่มเหล้าองุ่น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 6, 'แต่เขาทั้งหลายตอบว่า “เราจะไม่ดื่มเหล้าองุ่น เพราะโยนาดับบุตรชายเรคาบผู้เป็นบิดาของเราบัญชาเราว่า ‘เจ้าทั้งหลายอย่าดื่มเหล้าองุ่น ทั้งตัวเจ้าและลูกหลานของเจ้าเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 7, 'เจ้าอย่าสร้างเรือน เจ้าอย่าหว่านพืช เจ้าอย่าปลูกหรือมีสวนองุ่น และเจ้าจงอยู่ในเต็นท์ตลอดชีวิตของเจ้า เพื่อเจ้าจะมีชีวิตยืนนานในแผ่นดินซึ่งเจ้าอาศัยอยู่’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 8, 'เราทั้งหลายได้เชื่อฟังเสียงของโยนาดับบุตรชายเรคาบผู้เป็นบิดาของเราในสิ่งทั้งปวงซึ่งท่านได้บัญชาเรา คือไม่ดื่มเหล้าองุ่นตลอดชีวิตของเรา ทั้งตัวเรา ภรรยา บุตรชาย บุตรสาวของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 9, 'และไม่สร้างเรือนเพื่อจะอาศัยอยู่ เราไม่มีสวนองุ่นหรือนาหรือพืช');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 10, 'แต่เราเคยอยู่ในเต็นท์ และได้เชื่อฟังและกระทําทุกสิ่งซึ่งโยนาดับบิดาของเราได้บัญชาเราไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 11, 'แต่ต่อมาเมื่อเนบูคัดเนสซาร์กษัตริย์แห่งบาบิโลนได้ยกมาต่อสู้กับแผ่นดินนี้ เราพูดว่า ‘มาเถิด ให้เราไปยังกรุงเยรูซาเล็มเพราะกลัวกองทัพคนเคลเดีย และเพราะกลัวกองทัพคนซีเรีย’ ดังนั้นเราจึงอยู่ในกรุงเยรูซาเล็ม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 12, 'แล้วพระวจนะแห่งพระเยโฮวาห์จึงมาถึงเยเรมีย์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 13, '“พระเยโฮวาห์จอมโยธาพระเจ้าแห่งอิสราเอลตรัสดังนี้ว่า จงไปบอกบรรดาผู้ชายของยูดาห์ และบอกชาวกรุงเยรูซาเล็มว่า พระเยโฮวาห์ตรัสว่า เจ้าจะไม่รับคําสั่งสอนเพื่อจะเชื่อฟังถ้อยคําของเราหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 14, 'คําบัญชาซึ่งโยนาดับบุตรชายเรคาบให้ไว้แก่บุตรชายทั้งหลายของตน ไม่ให้ดื่มเหล้าองุ่นนั้น เขาก็ได้รักษากันไว้แล้ว และเขาทั้งหลายมิได้ดื่มเลยจนถึงวันนี้ เพราะเขาทั้งหลายได้เชื่อฟังคําบัญชาแห่งบิดาของเขา แต่เราได้พูดกับพวกเจ้าอย่างไม่หยุดยั้ง แต่เจ้าทั้งหลายหาได้ฟังเราไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 15, 'เราได้ส่งบรรดาผู้รับใช้ของเราคือผู้พยากรณ์มาหาเจ้า ส่งเขามาอย่างไม่หยุดยั้ง กล่าวว่า ‘บัดนี้เจ้าทุกคนจงหันกลับจากทางชั่วของตน และแก้ไขการกระทําของเจ้าทั้งหลายเสีย อย่าไปติดตามพระอื่นเพื่อปรนนิบัติพระเหล่านั้น แล้วเจ้าจะได้อาศัยอยู่ในแผ่นดิน ซึ่งเราได้ประทานแก่เจ้าและบรรพบุรุษของเจ้า’ แต่เจ้ามิได้เงี่ยหูหรือเชื่อฟังเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 16, 'บุตรชายทั้งหลายของโยนาดับบุตรชายของเรคาบได้กระทําตามคําบัญชาซึ่งบิดาของเขาได้สั่งไว้ แต่ชนชาตินี้ไม่ได้เชื่อฟังเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 17, 'เหตุฉะนี้พระเยโฮวาห์พระเจ้าจอมโยธา พระเจ้าแห่งอิสราเอล ตรัสดังนี้ว่า ดูเถิด เราจะนําความร้ายทั้งสิ้นซึ่งเราประกาศไว้มาเหนือยูดาห์ และบรรดาชาวกรุงเยรูซาเล็ม เพราะว่าเราพูดกับเขาทั้งหลายและเขาก็ไม่ฟัง เราได้เรียกเขาและเขาไม่ขานตอบ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 18, 'แต่เยเรมีย์ได้พูดกับวงศ์วานเรคาบว่า “พระเยโฮวาห์จอมโยธา พระเจ้าแห่งอิสราเอล ตรัสดังนี้ว่า เพราะว่าเจ้าได้เชื่อฟังคําบัญชาของโยนาดับบิดาของเจ้า และถือรักษาข้อบังคับของท่านทั้งสิ้น และกระทําทุกอย่างที่ท่านบัญชาเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 19, 'เพราะฉะนั้น พระเยโฮวาห์จอมโยธา พระเจ้าแห่งอิสราเอล ตรัสดังนี้ว่า โยนาดับบุตรชายเรคาบจะไม่ขัดสนผู้ชายที่ยืนอยู่ต่อหน้าเราเลยเป็นนิตย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 1, 'ต่อมาในปีที่สี่แห่งรัชกาลเยโฮยาคิม ราชบุตรของโยสิยาห์ กษัตริย์แห่งยูดาห์ พระวจนะต่อไปนี้มาจากพระเยโฮวาห์ถึงเยเรมีย์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 2, '“เจ้าจงเอาหนังสือม้วนม้วนหนึ่ง และเขียนถ้อยคํานี้ทั้งสิ้นลงไว้ เป็นคําที่เราได้พูดกับเจ้าปรักปรําอิสราเอลและยูดาห์ และบรรดาประชาชาติทั้งสิ้น ตั้งแต่วันที่เราได้พูดกับเจ้า ตั้งแต่รัชกาลโยสิยาห์จนถึงวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 3, 'ชะรอยวงศ์วานยูดาห์จะได้ยินถึงความร้ายทั้งสิ้นซึ่งเราประสงค์จะกระทําแก่เขาทั้งปวง เพื่อว่าทุกคนจะหันกลับจากทางชั่วร้ายของเขา และเพื่อเราจะอภัยโทษความชั่วช้าของเขาและบาปของเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 4, 'แล้วเยเรมีย์จึงเรียกบารุคบุตรชายเนริยาห์ให้บารุคเขียนพระวจนะทั้งสิ้นของพระเยโฮวาห์ซึ่งพระองค์ตรัสแก่เยเรมีย์ ตามคําบอกของท่านไว้ในหนังสือม้วน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 5, 'และเยเรมีย์ก็สั่งบารุคว่า “ข้าพเจ้าถูกห้ามไม่ให้ไปยังพระนิเวศของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 6, 'ฉะนั้นเจ้าต้องไป และในวันถืออดอาหาร เจ้าจงอ่านพระวจนะของพระเยโฮวาห์จากหนังสือม้วน ซึ่งเจ้าเขียนไว้ตามคําบอกของเราให้ประชาชนทั้งสิ้นในพระนิเวศของพระเยโฮวาห์ได้ยิน เจ้าจงอ่านให้คนทั้งปวงแห่งยูดาห์ ผู้ออกมาจากหัวเมืองของเขาให้เขาได้ยินด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 7, 'ชะรอยเขาจะถวายคําทูลวิงวอนของเขาต่อพระพักตร์พระเยโฮวาห์ และทุกคนจะหันกลับจากทางชั่วของตน เพราะความกริ้วและความพิโรธซึ่งพระเยโฮวาห์ทรงประกาศเป็นโทษเหนือชนชาตินี้นั้นใหญ่หลวงนัก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 8, 'และบารุคบุตรชายเนริยาห์ได้กระทําทุกอย่างตามซึ่งเยเรมีย์ผู้พยากรณ์สั่งเขา ถึงเรื่องให้อ่านพระวจนะของพระเยโฮวาห์จากหนังสือม้วนในพระนิเวศของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 9, 'ต่อมาในปีที่ห้าแห่งรัชกาลเยโฮยาคิม ราชบุตรของโยสิยาห์ กษัตริย์แห่งยูดาห์ ณ เดือนที่เก้า เขาได้ป่าวร้องแก่ประชาชนทั้งสิ้นในกรุงเยรูซาเล็มและประชาชนทั้งสิ้นผู้มาจากหัวเมืองแห่งยูดาห์ยังกรุงเยรูซาเล็ม ให้ถืออดอาหารต่อพระพักตร์พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 10, 'แล้วบารุคจึงได้อ่านถ้อยคําของเยเรมีย์จากหนังสือม้วนให้ประชาชนทั้งสิ้นฟัง ในพระนิเวศของพระเยโฮวาห์ ในห้องเฉลียงของเกมาริยาห์ บุตรชายชาฟาน ผู้เป็นเลขานุการ ซึ่งอยู่ในลานบนตรงทางเข้าของประตูใหม่แห่งพระนิเวศของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 11, 'เมื่อมีคายาห์ บุตรชายเกมาริยาห์ ผู้เป็นบุตรชายชาฟาน ได้ยินพระวจนะทั้งสิ้นของพระเยโฮวาห์จากหนังสือม้วนแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 12, 'ท่านได้ลงมาที่พระราชวังของกษัตริย์เข้าไปในห้องราชเลขา และดูเถิด เจ้านายทั้งสิ้นก็นั่งอยู่ที่นั่น คือเอลีชามาราชเลขา เดไลยาห์บุตรชายเชไมอาห์ เอลนาธันบุตรชายอัคโบร์ เกมาริยาห์บุตรชายชาฟาน เศเดคียาห์บุตรชายฮานันยาห์ และบรรดาเจ้านายทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 13, 'และมีคายาห์ก็เล่าถ้อยคําทั้งสิ้นซึ่งท่านได้ยิน เมื่อบารุคอ่านจากหนังสือม้วนให้ประชาชนฟังนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 14, 'เหตุดังนั้นบรรดาเจ้านายจึงใช้เยฮูดีบุตรชายเนธานิยาห์ ผู้เป็นบุตรชายของเชเลมิยาห์ ผู้เป็นบุตรชายของคูชี ให้ไปพูดกับบารุคว่า “จงถือหนังสือม้วนซึ่งเจ้าอ่านให้ประชาชนฟังนั้นมา” ดังนั้นบารุคบุตรชายเนริยาห์จึงถือหนังสือม้วนนั้นมาหาเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 15, 'และเขาทั้งหลายจึงพูดกับเขาว่า “จงนั่งลงอ่านหนังสือนั้นให้เราฟัง” บารุคจึงอ่านให้เขาฟัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 16, 'ต่อมาเมื่อเขาได้ยินคําทั้งหมดนั้นก็หันมาหากันด้วยความกลัว เขาทั้งหลายจึงพูดกับบารุคว่า “เราจะต้องบอกบรรดาถ้อยคําเหล่านี้ต่อกษัตริย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 17, 'แล้วเขาทั้งหลายจึงถามบารุคว่า “จงบอกเราว่า เจ้าเขียนถ้อยคําเหล่านี้ทั้งสิ้นอย่างไร เขียนตามคําบอกของเขาหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 18, 'บารุคตอบเขาทั้งหลายว่า “ท่านได้บอกถ้อยคําเหล่านี้ทั้งสิ้นแก่ข้าพเจ้า ฝ่ายข้าพเจ้าก็เขียนมันไว้ด้วยหมึกในหนังสือม้วน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 19, 'แล้วเจ้านายทั้งหลายบอกบารุคว่า “ทั้งเจ้าและเยเรมีย์จงไปซ่อนเสีย อย่าให้ผู้ใดทราบว่าเจ้าอยู่ที่ไหน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 20, 'แล้วเขาทั้งหลายก็เข้าไปในท้องพระโรงเพื่อเฝ้ากษัตริย์ เมื่อเอาหนังสือม้วนเก็บไว้ในห้องของเอลีชามาราชเลขาแล้ว เขาก็กราบทูลถ้อยคําทั้งสิ้นนั้นแก่กษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 21, 'กษัตริย์ก็รับสั่งให้เยฮูดีไปเอาหนังสือม้วนนั้นมา เขาก็ไปเอามาจากห้องของเอลีชามาราชเลขา และเยฮูดีก็อ่านถวายกษัตริย์และแก่บรรดาเจ้านายทั้งสิ้นผู้ยืนอยู่ข้างๆกษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 22, 'เวลานั้นเป็นเดือนที่เก้า กษัตริย์ประทับอยู่ในพระราชวังเหมันต์ และมีไฟลุกอยู่ในโถไฟหน้าพระพักตร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 23, 'ต่อมาเมื่อเยฮูดีอ่านไปได้สามหรือสี่แถบ กษัตริย์ทรงเอามีดอาลักษณ์ตัดออก และทรงโยนเข้าไปในไฟที่ในโถไฟ จนหนังสือม้วนนั้นถูกไฟที่ในโถไฟเผาผลาญหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 24, 'ถึงกระนั้นกษัตริย์หรือข้าราชการของพระองค์ผู้ได้ยินบรรดาถ้อยคําเหล่านี้หาได้เกรงกลัวหรือฉีกเสื้อผ้าของตนไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 25, 'แม้ว่าเมื่อเอลนาธันและเดไลยาห์และเกมาริยาห์ ได้ทูลวิงวอนกษัตริย์มิให้พระองค์ทรงเผาหนังสือม้วน พระองค์หาทรงฟังไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 26, 'กษัตริย์ทรงบัญชาให้เยราเมเอลบุตรชายฮามเมเลค และเสไรอาห์บุตรชายอัซรีเอล และเชเลมิยาห์บุตรชายอับเดเอล ให้จับบารุคเสมียนและเยเรมีย์ผู้พยากรณ์ แต่พระเยโฮวาห์ทรงซ่อนท่านทั้งสองเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 27, 'หลังจากที่กษัตริย์ทรงเผาหนังสือม้วนอันมีถ้อยคําซึ่งบารุคเขียนตามคําบอกของเยเรมีย์แล้ว พระวจนะของพระเยโฮวาห์มายังเยเรมีย์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 28, '“จงเอาหนังสือม้วนอีกม้วนหนึ่งและจงเขียนถ้อยคําแรกซึ่งอยู่ในหนังสือม้วนก่อนลงไว้ทั้งหมด คือซึ่งเยโฮยาคิมกษัตริย์แห่งยูดาห์ทรงเผาเสียนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 29, 'และเกี่ยวกับเรื่องเยโฮยาคิมกษัตริย์ยูดาห์นั้นเจ้าจงกล่าวดังนี้ว่า ‘พระเยโฮวาห์ตรัสดังนี้ว่า ท่านได้เผาหนังสือม้วนนี้เสียและกล่าวว่า ทําไมเจ้าจึงได้เขียนไว้ในนั้นว่า “กษัตริย์บาบิโลนจะมาทําลายแผ่นดินนี้เป็นแน่ และจะตัดมนุษย์และสัตว์ออกเสียจากแผ่นดินนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 30, 'เพราะฉะนั้น พระเยโฮวาห์จึงตรัสดังนี้เกี่ยวด้วยเยโฮยาคิมกษัตริย์แห่งยูดาห์ว่า เยโฮยาคิมจะไม่มีบุตรที่จะประทับบนพระที่นั่งของดาวิด และศพของท่านจะถูกทิ้งไว้ให้ตากแดดกลางวัน และตากน้ําค้างแข็งเวลากลางคืน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 31, 'เราจะลงโทษท่านและเชื้อสายของท่านและข้าราชการของท่าน เพราะความชั่วช้าของเขาทั้งหลาย เราจะนําเหตุร้ายทั้งสิ้นที่เราได้ประกาศต่อพวกเขา แต่เขาไม่ฟังนั้น ให้ตกลงบนเขา และบนชาวกรุงเยรูซาเล็ม และบนคนยูดาห์’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 32, 'แล้วเยเรมีย์จึงเอาหนังสือม้วนอีกม้วนหนึ่ง มอบให้บารุคเสมียนบุตรชายเนริยาห์ ผู้เขียนถ้อยคําทั้งสิ้นในนั้นตามคําบอกของเยเรมีย์ คือถ้อยคําทั้งสิ้นในหนังสือม้วนซึ่งเยโฮยาคิมกษัตริย์แห่งยูดาห์ได้เผาเสียในไฟ และมีถ้อยคําเป็นอันมากที่คล้ายคลึงกันเพิ่มขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 1, 'เศเดคียาห์ราชบุตรของโยสิยาห์ ผู้ซึ่งเนบูคัดเนสซาร์กษัตริย์แห่งบาบิโลนได้ตั้งให้เป็นกษัตริย์ในแผ่นดินยูดาห์ ได้เสวยราชย์แทนโคนิยาห์ราชบุตรของเยโฮยาคิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 2, 'แต่ท่านเองก็ดี หรือข้าราชการของท่านก็ดี หรือประชาชนแห่งแผ่นดินก็ดี หาได้ฟังพระวจนะของพระเยโฮวาห์ ซึ่งพระองค์ตรัสโดยเยเรมีย์ผู้พยากรณ์ไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 3, 'กษัตริย์เศเดคียาห์ทรงใช้เยฮูคัลบุตรชายเชเลมิยาห์ และเศฟันยาห์ปุโรหิตบุตรชายมาอาเสอาห์ให้ไปยังเยเรมีย์ผู้พยากรณ์ กล่าวว่า “ขออธิษฐานต่อพระเยโฮวาห์พระเจ้าของเราเผื่อเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 4, 'ฝ่ายเยเรมีย์นั้นยังเข้านอกออกในท่ามกลางประชาชนอยู่ เพราะท่านยังมิได้ถูกจําขัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 5, 'กองทัพของฟาโรห์ได้ออกมาจากอียิปต์ และเมื่อคนเคลเดียผู้ซึ่งกําลังล้อมกรุงเยรูซาเล็มอยู่ได้ยินข่าวนั้น เขาทั้งหลายก็ถอยทัพไปจากกรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 6, 'พระวจนะของพระเยโฮวาห์มายังเยเรมีย์ผู้พยากรณ์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 7, '“พระเยโฮวาห์พระเจ้าแห่งอิสราเอลตรัสดังนี้ว่า เจ้าจงไปบอกกษัตริย์แห่งยูดาห์ ผู้ซึ่งใช้เจ้ามาถามต่อเราว่า ‘ดูเถิด กองทัพของฟาโรห์ซึ่งได้มาช่วยเจ้ากําลังจะกลับไปอียิปต์ ไปยังแผ่นดินของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 8, 'และคนเคลเดียจะกลับมาต่อสู้กับกรุงนี้อีก เขาทั้งหลายจะยึดไว้และเผาเสียด้วยไฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 9, 'พระเยโฮวาห์ตรัสดังนี้ว่า อย่าล่อลวงตัวเจ้าโดยกล่าวว่า “คนเคลเดียจะถอยออกไปจากเราทีเดียวแน่” เพราะว่าเขาจะไม่ถอยออกไปเลยทีเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 10, 'ถึงแม้ว่าเจ้ากระทําให้กองทัพทั้งสิ้นของคนเคลเดียที่กําลังต่อสู้เจ้าให้พ่ายแพ้ และมีเหลือแต่คนที่บาดเจ็บเท่านั้น เขาทั้งหลายจะลุกขึ้น ทุกคนในเต็นท์ของเขา และเผากรุงนี้เสียด้วยไฟ’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 11, 'ต่อมาเมื่อกองทัพของคนเคลเดียได้ถอยจากกรุงเยรูซาเล็ม เพราะกองทัพของฟาโรห์เข้ามาประชิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 12, 'เยเรมีย์ก็ออกไปจากกรุงเยรูซาเล็มมุ่งไปยังแผ่นดินเบนยามิน เพื่อจะรับส่วนของท่านท่ามกลางประชาชนที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 13, 'เมื่อท่านอยู่ที่ประตูเบนยามิน ทหารยามคนหนึ่งอยู่ที่นั่น ชื่ออิรียาห์บุตรชายเชเลมิยาห์ ผู้เป็นบุตรชายฮานันยาห์ได้จับเยเรมีย์ผู้พยากรณ์กล่าวว่า “ท่านกําลังหนีไปหาคนเคลเดีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 14, 'และเยเรมีย์ตอบว่า “ไม่จริงเลย ข้าพเจ้ามิได้กําลังหนีไปหาคนเคลเดีย” แต่อิรียาห์ไม่ฟังท่าน และจับเยเรมีย์นํามาหาพวกเจ้านาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 15, 'และบรรดาเจ้านายก็เดือดดาลต่อเยเรมีย์ และเขาทั้งหลายก็ตีท่านและขังท่านไว้ในเรือนของโยนาธานเลขานุการ เพราะได้ทําให้เป็นคุก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 16, 'เมื่อเยเรมีย์เข้าไปในคุกใต้ดินและในห้องเล็กแล้ว เยเรมีย์ก็ค้างอยู่ที่นั่นหลายวันแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 17, 'กษัตริย์เศเดคียาห์ใช้ให้คนไปเอาตัวท่านออกมา กษัตริย์ได้สอบถามท่านเป็นความลับที่ในพระราชวังว่า “มีพระวจนะอันใดมาจากพระเยโฮวาห์บ้างหรือ” เยเรมีย์ทูลว่า “มีพ่ะย่ะค่ะ” แล้วท่านทูลอีกว่า “พระองค์จะถูกมอบไว้ในมือของกษัตริย์แห่งบาบิโลน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 18, 'เยเรมีย์ได้ทูลกษัตริย์เศเดคียาห์อีกว่า “ข้าพระองค์ได้กระทําอะไรผิดต่อพระองค์ หรือต่อข้าราชการของพระองค์ หรือต่อชนชาตินี้ พระองค์จึงได้จําขังข้าพระองค์ไว้ในคุก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 19, 'ผู้พยากรณ์ของพระองค์ผู้ได้พยากรณ์ให้พระองค์ว่า ‘กษัตริย์แห่งบาบิโลนจะไม่มาต่อสู้พระองค์ หรือต่อสู้แผ่นดินนี้’ นั้นอยู่ที่ไหน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 20, 'เพราะฉะนั้นบัดนี้ โอ ข้าแต่กษัตริย์ผู้เป็นเจ้านายของข้าพระองค์ ขอพระองค์สดับฟัง ขอคําทูลของข้าพระองค์เป็นที่โปรดปรานต่อพระพักตร์ของพระองค์ ขออย่าส่งข้าพระองค์กลับไปที่เรือนของโยนาธานเลขานุการนั้นเลย เกรงว่าข้าพระองค์จะตายเสียที่นั่น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 21, 'กษัตริย์เศเดคียาห์จึงมีรับสั่งให้เขามอบเยเรมีย์ไว้ที่บริเวณทหารรักษาพระองค์ และเขาให้ขนมปังแก่ท่านวันละก้อนจากถนนช่างทําขนมจนขนมปังในกรุงนั้นหมด เยเรมีย์จึงค้างอยู่ในบริเวณทหารรักษาพระองค์อย่างนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 1, 'ฝ่ายเชฟาทิยาห์บุตรชายมัททาน เกดาลิยาห์บุตรชายปาชเฮอร์ และยูคาลบุตรชายเชเลมิยาห์ และปาชเฮอร์บุตรชายมัลคิยาห์ได้ยินถ้อยคําของเยเรมีย์ที่กล่าวแก่ประชาชนทุกคนว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 2, '“พระเยโฮวาห์ตรัสดังนี้ว่า ผู้ใดอยู่ในกรุงนี้จะต้องตายด้วยดาบ ด้วยการกันดารอาหาร และด้วยโรคระบาด แต่ผู้ใดที่ออกไปหาคนเคลเดียจะมีชีวิตอยู่ เขาจะมีชีวิตเป็นบําเหน็จแห่งการสงคราม และยังมีชีวิตอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 3, 'พระเยโฮวาห์ตรัสดังนี้ว่า แน่นอนกรุงนี้จะต้องมอบไว้ในมือของกองทัพของกษัตริย์แห่งบาบิโลนและท่านจะยึดไว้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 4, 'และบรรดาเจ้านายจึงทูลกษัตริย์ว่า “ขอประหารชายคนนี้เสีย เพราะเขากระทําให้มือของทหารซึ่งเหลืออยู่ในเมืองนี้อ่อนลง ทั้งมือของประชาชนทั้งหมดด้วย โดยพูดถ้อยคําเช่นนี้แก่เขาทั้งหลาย เพราะว่าชายคนนี้มิได้แสวงหาความอยู่เย็นเป็นสุขของชนชาตินี้ แต่หาความทุกข์ยากลําบาก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 5, 'กษัตริย์เศเดคียาห์ตรัสว่า “ดูเถิด ชายคนนี้อยู่ในมือของท่านทั้งหลายแล้ว เพราะกษัตริย์จะทําอะไรขัดท่านทั้งหลายได้เล่า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 6, 'เขาจึงจับเยเรมีย์หย่อนลงไปในคุกใต้ดินของมัลคิยาห์บุตรชายฮามเมเลคซึ่งอยู่ในบริเวณทหารรักษาพระองค์ เขาเอาเชือกหย่อนเยเรมีย์ลงไป ในคุกใต้ดินนั้นไม่มีน้ํา มีแต่โคลน และเยเรมีย์ก็จมลงไปในโคลน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 7, 'เมื่อเอเบดเมเลคคนเอธิโอเปียขันทีคนหนึ่งในพระราชวังได้ยินว่า เขาหย่อนเยเรมีย์ลงไปในคุกใต้ดินนั้น ฝ่ายกษัตริย์ประทับอยู่ที่ประตูเบนยามิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 8, 'เอเบดเมเลคก็ออกไปจากพระราชวังและทูลกษัตริย์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 9, '“ข้าแต่กษัตริย์ผู้เป็นเจ้านายของข้าพระองค์ คนเหล่านี้ได้กระทําความชั่วร้ายในบรรดาการที่เขาได้กระทําต่อเยเรมีย์ผู้พยากรณ์ โดยที่ได้ทิ้งท่านลงไปในคุกใต้ดิน ท่านคงหิวตายที่นั่น เพราะในกรุงนี้ไม่มีขนมปังเหลืออยู่เลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 10, 'แล้วกษัตริย์มีรับสั่งให้เอเบดเมเลคคนเอธิโอเปียว่า “จงเอาคนไปจากที่นี่กับเจ้าสามสิบคน แล้วฉุดเยเรมีย์ผู้พยากรณ์ออกมาจากคุกใต้ดินก่อนเขาตาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 11, 'เอเบดเมเลคจึงเอาคนไปด้วยและไปที่พระราชวังไปยังเรือนพัสดุเพื่อเอาผ้าเก่าๆและเสื้อผ้าขาดๆ ซึ่งเขาเอาเชือกผูกหย่อนลงไปให้เยเรมีย์ที่ในคุกใต้ดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 12, 'แล้วเอเบดเมเลคคนเอธิโอเปียพูดกับเยเรมีย์ว่า “ท่านจงคล้องผ้าและเสื้อเก่านั้นไว้ใต้เชือกใต้รักแร้” เยเรมีย์กระทําตาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 13, 'แล้วเขาก็ฉุดเยเรมีย์ขึ้นมาด้วยเชือก และยกท่านขึ้นมาจากคุกใต้ดิน และเยเรมีย์ก็ยังค้างอยู่ในบริเวณทหารรักษาพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 14, 'กษัตริย์เศเดคียาห์ทรงใช้คนไปนําเยเรมีย์ผู้พยากรณ์มาที่ทางเข้าพระนิเวศของพระเยโฮวาห์ช่องที่สาม กษัตริย์ตรัสกับเยเรมีย์ว่า “เราจะถามท่านสักข้อหนึ่ง ขออย่าปิดบังไว้จากเราเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 15, 'เยเรมีย์จึงทูลเศเดคียาห์ว่า “ถ้าข้าพระองค์จะทูลพระองค์ พระองค์จะประหารข้าพระองค์แน่มิใช่หรือ และถ้าข้าพระองค์จะถวายคําปรึกษา พระองค์จะไม่ฟังข้าพระองค์มิใช่หรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 16, 'แล้วกษัตริย์เศเดคียาห์ก็ทรงปฏิญาณแก่เยเรมีย์เป็นการลับว่า “พระเยโฮวาห์ผู้ทรงสร้างวิญญาณของเราทรงพระชนม์อยู่แน่ฉันใด เราจะไม่ประหารท่านหรือมอบท่านไว้ในมือของคนเหล่านี้ที่แสวงหาชีวิตของท่านฉันนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 17, 'แล้วเยเรมีย์ทูลเศเดคียาห์ว่า “พระเยโฮวาห์ พระเจ้าจอมโยธา พระเจ้าแห่งอิสราเอลตรัสดังนี้ว่า ถ้าพระองค์จะยอมมอบตัวแก่พวกเจ้านายแห่งกษัตริย์บาบิโลนแล้ว เขาจะไว้ชีวิตของพระองค์ และกรุงนี้จะไม่ต้องถูกไฟเผา พระองค์และวงศ์วานของพระองค์จะมีชีวิตอยู่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 18, 'แต่ถ้าพระองค์ไม่ยอมมอบตัวแก่พวกเจ้านายแห่งกษัตริย์ของบาบิโลนแล้ว กรุงนี้จะต้องถูกมอบไว้ในมือของชนเคลเดีย และเขาทั้งหลายจะเอาไฟเผาเสีย และพระองค์จะหนีไม่รอดไปจากมือของเขาทั้งหลาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 19, 'กษัตริย์เศเดคียาห์จึงตรัสกับเยเรมีย์ว่า “เรากลัวพวกยิวซึ่งเล็ดลอดไปหาคนเคลเดีย เกรงว่าเราจะถูกมอบไว้ในมือของพวกเหล่านั้น และเขาทั้งหลายจะกระทําความอัปยศแก่เรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 20, 'เยเรมีย์ทูลว่า “เขาจะไม่มอบพระองค์ไว้ ขอพระองค์เชื่อฟังพระสุรเสียงของพระเยโฮวาห์ตามสิ่งซึ่งข้าพระองค์ได้ทูลพระองค์ และพระองค์ก็จะเป็นสุข และเขาก็จะไว้พระชนม์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 21, 'แต่ถ้าพระองค์ไม่ยอมมอบตัว ต่อไปนี้เป็นพระวจนะซึ่งพระเยโฮวาห์ทรงสําแดงต่อข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 22, 'ดูเถิด บรรดาผู้หญิงที่เหลืออยู่ในวังของกษัตริย์แห่งยูดาห์จะถูกนําออกไปให้พวกเจ้านายของกษัตริย์แห่งบาบิโลน และผู้หญิงเหล่านั้นจะว่า ‘เพื่อนทั้งหลายของพระองค์ได้หลอกลวงพระองค์ และได้ชนะพระองค์แล้ว พระบาทของพระองค์จมลงในโคลนแล้ว และเขาทั้งหลายก็หันไปจากพระองค์’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 23, 'เขาจะพาบรรดาสนมและมเหสีและบุตรของพระองค์ไปให้คนเคลเดีย และพระองค์เองก็จะไม่ทรงรอดไปจากมือของเขาทั้งหลาย แต่พระองค์จะถูกกษัตริย์แห่งบาบิโลนจับได้ และพระองค์จะเป็นเหตุที่กรุงนี้ถูกเผาด้วยไฟ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 24, 'แล้วเศเดคียาห์ตรัสกับเยเรมีย์ว่า “อย่าให้ผู้ใดรู้ถ้อยคําเหล่านี้ และท่านจะไม่ตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 25, 'แต่ถ้าพวกเจ้านายได้ยินว่าเราได้พูดกับท่าน และมาหาท่านพูดว่า ‘จงบอกมาว่าเจ้าพูดอะไรกับกษัตริย์ และกษัตริย์ตรัสอะไรกับเจ้า อย่าซ่อนอะไรจากเราเลย และเราจะไม่ฆ่าเจ้า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 26, 'ท่านจงบอกเขาทั้งหลายว่า ‘ข้าพเจ้าได้ทูลขอต่อพระพักตร์กษัตริย์มิให้พระองค์ทรงส่งข้าพเจ้ากลับไปที่เรือนของโยนาธานเพื่อให้ตายเสียที่นั่น’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 27, 'และเจ้านายทั้งปวงก็มาหาเยเรมีย์และซักถามท่าน และท่านก็ตอบเขาตามบรรดาถ้อยคําเหล่านี้ที่กษัตริย์ทรงรับสั่งท่าน เขาทั้งหลายจึงหยุดถามท่าน เพราะการสนทนานั้นไม่มีใครได้ยิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 28, 'และเยเรมีย์ก็ค้างอยู่ในบริเวณทหารรักษาพระองค์จนถึงวันที่เยรูซาเล็มถูกยึด ท่านอยู่ในที่นั่นเมื่อเยรูซาเล็มถูกยึด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 1, 'ในปีที่เก้าแห่งเศเดคียาห์กษัตริย์แห่งยูดาห์ ในเดือนที่สิบ เนบูคัดเนสซาร์กษัตริย์แห่งบาบิโลนและกองทัพทั้งสิ้นของท่านได้มาสู้รบกรุงเยรูซาเล็มและได้ล้อมไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 2, 'ในปีที่สิบเอ็ดแห่งรัชกาลเศเดคียาห์ เมื่อวันที่เก้าของเดือนที่สี่ กรุงนั้นก็แตก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 3, 'แล้วบรรดาเจ้านายของกษัตริย์แห่งบาบิโลนได้เข้ามานั่งที่ประตูกลาง มีเนอร์กัลชาเรเซอร์ สัมการ์เนโบ สารเสคิม รับสารีส เนอร์กัลชาเรเซอร์ รับมัก และบรรดาเจ้านายที่เหลืออยู่ทั้งสิ้นของกษัตริย์แห่งบาบิโลน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 4, 'ต่อมาเมื่อเศเดคียาห์กษัตริย์แห่งยูดาห์และบรรดาทหารได้เห็นแล้ว เขาทั้งหลายได้หนีออกจากกรุงในเวลากลางคืนไปทางอุทยานของกษัตริย์ ออกทางประตูระหว่างกําแพงทั้งสอง และท่านได้หนีไปยังทางที่ราบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 5, 'แต่กองทัพของคนเคลเดียได้ติดตามเขาทั้งหลาย ไปทันเศเดคียาห์ที่ราบเมืองเยรีโค และเมื่อเขาทั้งหลายจับท่านได้แล้ว เขาได้นําท่านไปยังเนบูคัดเนสซาร์กษัตริย์แห่งบาบิโลนที่ตําบลริบลาห์ในแผ่นดินฮามัท และพระองค์ก็พิพากษาโทษท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 6, 'กษัตริย์แห่งบาบิโลนได้ฆ่าบรรดาบุตรชายของเศเดคียาห์ที่ตําบลริบลาห์ต่อหน้าต่อตาของท่าน และกษัตริย์แห่งบาบิโลนได้ประหารพวกขุนนางทั้งสิ้นของยูดาห์เสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 7, 'พระองค์ทรงทํานัยน์ตาของเศเดคียาห์ให้บอดไป แล้วตีตรวนท่านไว้เพื่อจะนําไปบาบิโลน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 8, 'คนเคลเดียได้เผาพระราชวังและบ้านเรือนของประชาชน และพังกําแพงกรุงเยรูซาเล็มเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 9, 'แล้วเนบูซาระดานผู้บัญชาการทหารรักษาพระองค์ได้จับประชาชนที่เหลืออยู่ในกรุงเป็นเชลยพาไปยังบาบิโลน ทั้งคนที่เล็ดลอด คือคนที่เล็ดลอดมาหาท่าน และส่วนคนที่เหลืออยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 10, 'เนบูซาระดาน ผู้บัญชาการทหารรักษาพระองค์ได้ทิ้งคนจนแห่งประชาชนที่ไม่มีสมบัติอะไรไว้ในแผ่นดินยูดาห์บ้าง และในเวลาเดียวกันได้มอบสวนองุ่นและไร่นาให้แก่เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 11, 'เนบูคัดเนสซาร์กษัตริย์แห่งบาบิโลนได้ประทานบัญชาเกี่ยวด้วยเยเรมีย์ทางเนบูซาระดาน ผู้บัญชาการทหารรักษาพระองค์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 12, '“จงรับท่านไป ดูแลท่านให้ดี และอย่าทําอันตรายแก่ท่าน แต่จงกระทําแก่ท่านตามที่ท่านจะบอกให้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 13, 'ดังนั้น เนบูซาระดานผู้บัญชาการทหารรักษาพระองค์ เนบูชัสบาน รับสารีส เนอร์กัลชาเรเซอร์ รับมัก และบรรดาเจ้านายของกษัตริย์แห่งบาบิโลนได้ใช้คนไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 14, 'คือพวกท่านได้ใช้คนไปนําเยเรมีย์มาจากบริเวณทหารรักษาพระองค์ เขาทั้งหลายมอบท่านไว้กับเกดาลิยาห์บุตรชายอาหิคัม ผู้เป็นบุตรชายชาฟาน ให้นําท่านไปบ้าน ดังนั้นท่านจึงได้อยู่ท่ามกลางประชาชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 15, 'พระวจนะของพระเยโฮวาห์มายังเยเรมีย์ ขณะที่ท่านถูกขังอยู่ในบริเวณทหารรักษาพระองค์นั้นว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 16, '“จงไปบอกเอเบดเมเลคคนเอธิโอเปียว่า พระเยโฮวาห์จอมโยธา พระเจ้าแห่งอิสราเอลตรัสดังนี้ว่า ดูเถิด เราจะให้ถ้อยคําของเราที่มีอยู่ต่อกรุงนี้สําเร็จในทางร้ายไม่ใช่ทางดี และจะสําเร็จต่อหน้าเจ้าในวันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 17, 'พระเยโฮวาห์ตรัสว่า แต่เราจะช่วยเจ้าให้พ้นในวันนั้น และเขาจะไม่มอบเจ้าไว้ในมือของคนที่เจ้ากลัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 18, 'เพราะเราจะช่วยเจ้าให้พ้นเป็นแน่ และเจ้าจะไม่ล้มลงด้วยดาบ แต่เจ้าจะมีชีวิตเป็นบําเหน็จแห่งการสงคราม เพราะเจ้าได้ไว้วางใจในเรา พระเยโฮวาห์ตรัสดังนี้แหละ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 1, 'พระวจนะซึ่งมาจากพระเยโฮวาห์ถึงเยเรมีย์ หลังจากที่เนบูซาระดานผู้บัญชาการทหารรักษาพระองค์ได้ปล่อยให้ท่านไปจากรามาห์ ครั้งเมื่อเขาจับท่านตีตรวนมาพร้อมกับบรรดาเชลยพวกกรุงเยรูซาเล็มและยูดาห์ ผู้ที่ถูกกวาดไปเป็นเชลยยังบาบิโลน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 2, 'ผู้บัญชาการทหารรักษาพระองค์ได้นําเยเรมีย์มาแล้วพูดกับท่านว่า “พระเยโฮวาห์พระเจ้าของท่านทรงประกาศความร้ายนี้ต่อสถานที่นี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 3, 'พระเยโฮวาห์ทรงกระทําให้เป็นไปและทรงกระทําตามที่พระองค์ตรัสไว้ เพราะท่านทั้งหลายได้กระทําบาปต่อพระเยโฮวาห์ และไม่เชื่อฟังพระสุรเสียงของพระองค์ สิ่งนี้จึงได้เป็นมาเหนือท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 4, 'ดูเถิด วันนี้ข้าพเจ้าปล่อยท่านจากโซ่ตรวนที่มือของท่าน ถ้าท่านเห็นชอบที่จะมายังกรุงบาบิโลนกับข้าพเจ้า ก็จงมาเถิด ข้าพเจ้าจะดูแลท่านให้ดี แต่ถ้าท่านไม่เห็นชอบที่จะมายังกรุงบาบิโลนกับข้าพเจ้า ก็อย่ามา ดูซิ แผ่นดินทั้งหมดนี้อยู่ต่อหน้าท่าน ท่านจะไปที่ไหนก็ได้ตามแต่ท่านเห็นดีเห็นชอบที่จะไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 5, 'ขณะเมื่อท่านยังไม่กลับไป เขากล่าวว่า “ท่านจงกลับไปหาเกดาลิยาห์บุตรชายอาหิคัม ผู้เป็นบุตรชายชาฟาน ผู้ซึ่งกษัตริย์แห่งบาบิโลนได้แต่งตั้งให้เป็นผู้ว่าราชการบรรดาหัวเมืองยูดาห์ และอยู่กับเขาท่ามกลางประชาชน หรือจะไปที่ใดที่ท่านเห็นชอบจะไปก็ได้” ผู้บัญชาการทหารรักษาพระองค์จึงสั่งอนุมัติเสบียงและให้ของขวัญแก่เยเรมีย์ แล้วก็ปล่อยท่านไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 6, 'เยเรมีย์ก็ไปหาเกดาลิยาห์ บุตรชายอาหิคัมที่มิสปาห์ และอาศัยอยู่กับเขาท่ามกลางประชาชนซึ่งเหลืออยู่ในแผ่นดินนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 7, 'เมื่อบรรดาหัวหน้าของกองทหารที่ในทุ่งนา คือพวกเขาและคนของเขาทั้งหลายได้ยินว่า กษัตริย์แห่งบาบิโลนได้แต่งตั้งเกดาลิยาห์บุตรชายอาหิคัมให้เป็นผู้ว่าราชการในแผ่นดินนั้น และได้มอบชายหญิงกับเด็กผู้ที่เป็นคนจนในแผ่นดิน ซึ่งมิได้ถูกกวาดไปเป็นเชลยยังบาบิโลนไว้ให้ท่านนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 8, 'เขาทั้งหลายก็ไปหาเกดาลิยาห์ที่มิสปาห์ มีอิชมาเอลบุตรชายเนธานิยาห์ โยฮานันและโยนาธานบุตรชายคาเรอาห์ เสไรอาห์บุตรชายทันหุเมท บรรดาบุตรชายของเอฟายชาวเนโทฟาห์ เยซันยาห์บุตรชายชาวมาอาคาห์ ทั้งตัวเขาและคนของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 9, 'เกดาลิยาห์บุตรชายอาหิคัม ผู้เป็นบุตรชายชาฟานก็ได้ปฏิญาณให้แก่เขาและคนของเขา กล่าวว่า “อย่ากลัวในการที่จะปรนนิบัติคนเคลเดีย จงอาศัยอยู่ในแผ่นดินและปรนนิบัติกษัตริย์แห่งบาบิโลน แล้วท่านทั้งหลายก็จะอยู่เย็นเป็นสุข');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 10, 'ส่วนตัวข้าพเจ้า ดูเถิด ข้าพเจ้าจะอาศัยอยู่ที่มิสปาห์ เพื่อจะปรนนิบัติคนเคลเดีย ผู้ซึ่งจะมาหาเรา แต่ฝ่ายท่านจงเก็บน้ําองุ่น ผลไม้ฤดูร้อน และน้ํามันและเก็บไว้ในภาชนะ และจงอยู่ในหัวเมืองซึ่งท่านยึดได้นั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 11, 'ในทํานองเดียวกัน เมื่อพวกยิวทั้งหลาย ซึ่งอยู่ที่โมอับและท่ามกลางคนอัมโมน และในเอโดมและในแผ่นดินอื่นๆทั้งสิ้น ได้ยินว่ากษัตริย์แห่งบาบิโลนได้ทิ้งคนให้เหลือไว้ส่วนหนึ่งในยูดาห์และได้แต่งตั้งให้เกดาลิยาห์บุตรชายอาหิคัม ผู้เป็นบุตรชายชาฟานให้เป็นผู้ว่าราชการเหนือเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 12, 'แล้วพวกยิวทั้งปวงก็ได้กลับมาจากทุกที่ซึ่งเขาถูกขับไล่ให้ไปอยู่นั้น และมายังแผ่นดินยูดาห์มาหาเกดาลิยาห์ที่มิสปาห์ และเขาทั้งหลายได้เก็บน้ําองุ่นและผลไม้ในฤดูร้อนได้เป็นอันมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 13, 'ฝ่ายโยฮานันบุตรชายของคาเรอาห์และบรรดาประมุขของกองทหารที่ในทุ่งนาได้มาหาเกดาลิยาห์ที่มิสปาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 14, 'และกล่าวแก่ท่านว่า “ท่านทราบหรือไม่ว่า บาอาลิสกษัตริย์ของคนอัมโมนได้ส่งให้อิชมาเอลบุตรชายเนธานิยาห์มาเอาชีวิตของท่าน” ฝ่ายเกดาลิยาห์บุตรชายอาหิคัมไม่เชื่อเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 15, 'แล้วโยฮานันบุตรชายคาเรอาห์ได้พูดกับเกดาลิยาห์เป็นการลับที่มิสปาห์ว่า “จงให้ข้าพเจ้าไปฆ่าอิชมาเอลบุตรชายเนธานิยาห์เสีย และจะไม่มีใครทราบเรื่อง ทําไมจะให้เขาเอาชีวิตของท่าน แล้วพวกยิวทั้งหลายซึ่งมารวบรวมอยู่กับท่านจะกระจัดกระจายกันไป และคนยูดาห์ที่เหลืออยู่นี้ก็จะพินาศ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 16, 'แต่เกดาลิยาห์บุตรชายอาหิคัมพูดกับโยฮานันบุตรชายคาเรอาห์ว่า “ท่านอย่าทําสิ่งนี้เลย เพราะที่ท่านพูดถึงอิชมาเอลนั้นเป็นความเท็จ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 1, 'ต่อมาในเดือนที่เจ็ดอิชมาเอลบุตรชายเนธานิยาห์ ผู้เป็นบุตรชายเอลีชามาเชื้อพระวงศ์ พร้อมกับเจ้านายสิบคนของกษัตริย์ ได้มาหาเกดาลิยาห์บุตรชายอาหิคัมที่มิสปาห์ แล้วพวกเขารับประทานอาหารอยู่ด้วยกันที่มิสปาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 2, 'แล้วอิชมาเอลบุตรชายเนธานิยาห์กับคนทั้งสิบที่อยู่กับเขาก็ได้ลุกขึ้นฆ่าเกดาลิยาห์บุตรชายอาหิคัม ผู้เป็นบุตรชายชาฟาน ผู้ที่กษัตริย์แห่งบาบิโลนได้แต่งตั้งให้เป็นผู้ว่าราชการที่แผ่นดินนั้นเสียด้วยดาบจนตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 3, 'อิชมาเอลได้ฆ่าพวกยิวทั้งหลายที่อยู่กับเกดาลิยาห์ที่มิสปาห์ และคนเคลเดียซึ่งได้พบอยู่ที่นั่นพร้อมกับพวกทหารด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 4, 'ต่อมาอีกสองวันหลังจากวันที่เกดาลิยาห์ถูกฆ่าก่อนที่ใครๆรู้เรื่อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 5, 'มีชายแปดสิบคนมาจากเมืองเชเคมและเมืองชีโลห์และเมืองสะมาเรีย มีหนวดเคราโกนเสียและเสื้อผ้าขาด และกรีดตัวเอง นําเครื่องธัญญบูชาและกํายานมาถวายที่พระนิเวศของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 6, 'และอิชมาเอลบุตรชายเนธานิยาห์มาจากมิสปาห์พบเขาเหล่านั้นเข้า อิชมาเอลเดินมาพลางร้องไห้พลาง และต่อมาเมื่อเขาพบคนเหล่านั้นจึงพูดกับเขาทั้งหลายว่า “เชิญเข้ามาหาเกดาลิยาห์บุตรชายอาหิคัมเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 7, 'เมื่อเขาทั้งหลายเข้ามาในเมือง อิชมาเอลบุตรชายเนธานิยาห์และคนที่อยู่กับท่านก็ฆ่าเขาทั้งหลายเสีย และโยนเขาลงไปในที่ขังน้ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 8, 'แต่ในพวกนั้นมีอยู่สิบคนด้วยกันที่พูดกับอิชมาเอลว่า “ขออย่าฆ่าเราเสียเลย เพราะเรามีของมีค่า คือข้าวสาลี ข้าวบาร์เลย์ น้ํามัน และน้ําผึ้งซ่อนไว้ในทุ่งนา” ดังนั้น เขาจึงงดไม่ฆ่าเขาทั้งหลายกับพี่น้องเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 9, 'ที่ขังน้ําซึ่งอิชมาเอลโยนศพทั้งปวงของผู้ที่เขาฆ่าตายลงไปเพราะเหตุเกดาลิยาห์นั้น เป็นที่ซึ่งกษัตริย์อาสาสร้างไว้เพื่อป้องกันบาอาชากษัตริย์แห่งอิสราเอล อิชมาเอลบุตรชายเนธานิยาห์ก็ใส่คนที่ถูกฆ่าไว้จนเต็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 10, 'แล้วอิชมาเอลก็จับคนทั้งหมดที่เหลืออยู่ในมิสปาห์ไปเป็นเชลย คือพวกราชธิดาและประชาชนทั้งปวงที่เหลืออยู่ที่มิสปาห์ ผู้ที่เนบูซาระดานผู้บัญชาการทหารรักษาพระองค์ได้มอบหมายให้แก่เกดาลิยาห์บุตรชายอาหิคัม อิชมาเอลบุตรชายเนธานิยาห์ได้จับเขาเป็นเชลย และออกเดินข้ามฟากไปหาคนอัมโมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 11, 'แต่เมื่อโยฮานันบุตรชายคาเรอาห์และบรรดาหัวหน้าของกองทหารซึ่งอยู่กับเขา ได้ยินเรื่องความชั่วร้ายทั้งหลายซึ่งอิชมาเอลบุตรชายเนธานิยาห์ได้กระทําแล้วนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 12, 'เขาก็จัดเอาคนทั้งหมดของเขาไปต่อสู้กับอิชมาเอลบุตรชายเนธานิยาห์ เขาทั้งหลายปะทะเขาที่สระใหญ่ซึ่งอยู่ที่เมืองกิเบโอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 13, 'และต่อมาเมื่อประชาชนทั้งปวงผู้ซึ่งอยู่กับอิชมาเอลเห็นโยฮานันบุตรชายคาเรอาห์และบรรดาหัวหน้ากองทหารที่อยู่กับเขา เขาทั้งหลายก็เปรมปรีดิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 14, 'ประชาชนทั้งปวงซึ่งอิชมาเอลจับเป็นเชลยมาจากมิสปาห์จึงหันหลังและกลับไป เขาไปหาโยฮานันบุตรชายคาเรอาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 15, 'แต่อิชมาเอลบุตรชายเนธานิยาห์ได้หนีรอดจากโยฮานันพร้อมกับชายแปดคนไปหาคนอัมโมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 16, 'แล้วโยฮานันบุตรชายคาเรอาห์และบรรดาหัวหน้าของกองทหารซึ่งอยู่กับท่าน ได้นําประชาชนที่เหลืออยู่ทั้งหมด ซึ่งเอากลับคืนมาจากอิชมาเอลบุตรชายเนธานิยาห์ซึ่งมาจากมิสปาห์หลังจากที่ได้ฆ่าเกดาลิยาห์บุตรชายอาหิคัมแล้วนั้น คือทหาร ผู้หญิง เด็ก และขันที ผู้ซึ่งโยฮานันนํากลับมายังกิเบโอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 17, 'และเขาทั้งหลายก็ไปอยู่ที่ที่อาศัยของคิมฮาม ใกล้เบธเลเฮม ตั้งใจจะไปยังอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 18, 'เนื่องด้วยคนเคลเดีย เพราะเขากลัว เพราะว่าอิชมาเอลบุตรชายเนธานิยาห์ได้ฆ่าเกดาลิยาห์บุตรชายอาหิคัม ผู้ซึ่งกษัตริย์แห่งบาบิโลนได้ตั้งให้เป็นผู้ว่าราชการเหนือแผ่นดินนั้นเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 1, 'บรรดาหัวหน้าของกองทหารและโยฮานันบุตรชายคาเรอาห์ และเยซันยาห์บุตรชายโฮชายาห์ และประชาชนทั้งปวงจากผู้น้อยที่สุดถึงผู้ใหญ่ที่สุดได้เข้ามาใกล้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 2, 'และพูดกับเยเรมีย์ผู้พยากรณ์ว่า “ขอให้คําอ้อนวอนของข้าพเจ้าทั้งหลายเป็นที่ยอมรับต่อหน้าท่าน และขอท่านอธิษฐานต่อพระเยโฮวาห์พระเจ้าของท่านเพื่อเราทั้งหลาย เพื่อคนที่เหลืออยู่นี้ทั้งสิ้น (เพราะเรามีเหลือน้อยจากคนมาก ตามที่ท่านเห็นอยู่กับตาแล้ว)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 3, 'ขอพระเยโฮวาห์พระเจ้าของท่านสําแดงหนทางแก่เราว่า เราควรจะดําเนินไปทางไหน และขอสําแดงสิ่งที่เราควรจะกระทํา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 4, 'เยเรมีย์ผู้พยากรณ์กล่าวแก่เขาทั้งหลายว่า “ข้าพเจ้าได้ยินท่านแล้ว ดูเถิด ข้าพเจ้าจะอธิษฐานต่อพระเยโฮวาห์พระเจ้าของท่านตามคําขอร้องของท่านทั้งหลาย และต่อมาพระเยโฮวาห์จะทรงตอบท่านประการใด ข้าพเจ้าจะบอกแก่ท่าน ข้าพเจ้าจะไม่ปิดบังสิ่งใดไว้จากท่านเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 5, 'แล้วเขาทั้งหลายพูดกับเยเรมีย์ว่า “ขอพระเยโฮวาห์จงเป็นพยานที่สัตย์จริงและสัตย์ซื่อในระหว่างข้าพเจ้าทั้งหลาย ถ้าข้าพเจ้าทั้งหลายมิได้กระทําตามบรรดาพระวจนะของพระเยโฮวาห์พระเจ้าของท่านผู้ทรงใช้ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 6, 'ไม่ว่าจะดีหรือร้าย ข้าพเจ้าทั้งหลายจะเชื่อฟังพระสุรเสียงของพระเยโฮวาห์พระเจ้าของเรา ผู้ซึ่งข้าพเจ้าทั้งหลายส่งท่านให้ไปหานั้น เพื่อเราจะอยู่เย็นเป็นสุข เมื่อเราเชื่อฟังพระสุรเสียงแห่งพระเยโฮวาห์พระเจ้าของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 7, 'ต่อมาครั้นสิ้นสิบวันแล้วพระวจนะของพระเยโฮวาห์มายังเยเรมีย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 8, 'แล้วท่านจึงให้ตามตัวโยฮานันบุตรชายคาเรอาห์ และบรรดาผู้หัวหน้าของกองทหารผู้อยู่กับท่าน และประชาชนทั้งปวงตั้งแต่คนเล็กที่สุดถึงคนใหญ่ที่สุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 9, 'และบอกเขาทั้งหลายว่า “พระเยโฮวาห์พระเจ้าแห่งอิสราเอล ผู้ซึ่งท่านได้ใช้ให้ข้าพเจ้านําเอาคําอ้อนวอนของท่านไปเสนอต่อพระพักตร์พระองค์นั้น ได้ตรัสดังนี้ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 10, 'ถ้าเจ้าทั้งหลายจะอยู่ต่อไปในแผ่นดินนี้ เราจะสร้างเจ้าทั้งหลายขึ้นและไม่ทําลายลง เราจะปลูกเจ้าไว้และไม่ถอนเจ้าเสีย เพราะเราได้กลับใจจากเหตุร้ายซึ่งเราได้กระทําไปแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 11, 'อย่ากลัวกษัตริย์แห่งบาบิโลนผู้ซึ่งเจ้ากลัวอยู่นั้น พระเยโฮวาห์ตรัสว่า อย่ากลัวเขาเลย เพราะเราอยู่กับเจ้าทั้งหลายเพื่อช่วยเจ้าให้รอด และช่วยเจ้าให้พ้นจากมือของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 12, 'เราจะให้ความกรุณาแก่เจ้า เพื่อเขาจะได้กรุณาเจ้า และยอมให้เจ้ากลับไปอยู่ในแผ่นดินของเจ้าเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 13, 'แต่ถ้าเจ้าทั้งหลายพูดว่า ‘เราจะไม่อยู่ในแผ่นดินนี้’ โดยไม่เชื่อฟังพระสุรเสียงของพระเยโฮวาห์พระเจ้าของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 14, 'และกล่าวว่า ‘ไม่เอา เราจะเข้าไปในแผ่นดินอียิปต์ ที่ซึ่งเราจะไม่เห็นสงคราม จะไม่ได้ยินเสียงแตร จะไม่หิวขนมปัง และเราทั้งหลายจะอาศัยอยู่ที่นั่น’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 15, 'เพราะฉะนั้น บัดนี้ คนยูดาห์ที่เหลืออยู่เอ๋ย ขอฟังพระวจนะของพระเยโฮวาห์ พระเยโฮวาห์จอมโยธา พระเจ้าของอิสราเอล ตรัสดังนี้ว่า ถ้าเจ้ามุ่งหน้าจะเข้าอียิปต์และไปอาศัยที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 16, 'แล้วต่อมาดาบซึ่งเจ้ากลัวอยู่นั้นจะตามทันเจ้าที่นั่นในแผ่นดินอียิปต์ และการกันดารอาหารซึ่งเจ้ากลัวอยู่นั้นจะติดตามเจ้าไปถึงอียิปต์และเจ้าจะตายที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 17, 'ทุกคนซึ่งมุ่งหน้าไปยังอียิปต์ เพื่อจะอยู่ที่นั่นจะตายเสียด้วยดาบ ด้วยการกันดารอาหาร ด้วยโรคระบาด เขาจะไม่มีคนที่เหลืออยู่หรือที่รอดตายจากเหตุร้ายซึ่งเราจะนํามาเหนือเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 18, 'เพราะพระเยโฮวาห์จอมโยธา พระเจ้าแห่งอิสราเอล ตรัสดังนี้ว่า เราเทความกริ้วของเราและความพิโรธของเราลงเหนือชาวเยรูซาเล็มอย่างไร เราจะเทความกริ้วของเราเหนือเจ้าทั้งหลายเมื่อเจ้าจะเข้าไปยังอียิปต์อย่างนั้น เจ้าจะเป็นคําสาป เป็นที่น่าตกตะลึง เป็นคําแช่งและเป็นที่นินทา เจ้าจะไม่เห็นที่นี่อีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 19, 'โอ คนยูดาห์ที่ยังเหลืออยู่เอ๋ย พระเยโฮวาห์ได้ตรัสเกี่ยวกับท่านแล้วว่า ‘อย่าไปยังอียิปต์’ จงรู้เป็นแน่ว่า ในวันนี้ข้าพเจ้าได้ตักเตือนท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 20, 'ว่าท่านทั้งหลายได้หลงเจิ่นไปในใจของท่านเอง เพราะท่านได้ใช้ข้าพเจ้าไปหาพระเยโฮวาห์พระเจ้าของท่านว่า ‘ขออธิษฐานเพื่อเราต่อพระเยโฮวาห์พระเจ้าของเรา และพระเยโฮวาห์พระเจ้าของเราจะตรัสประการใด ขอบอกแก่เรา และเราจะกระทําตาม’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 21, 'และในวันนี้ข้าพเจ้าได้ประกาศพระวจนะนั้นแก่ท่านทั้งหลายแล้ว แต่ท่านมิได้เชื่อฟังพระสุรเสียงแห่งพระเยโฮวาห์พระเจ้าของท่านในสิ่งใดๆซึ่งพระองค์ทรงใช้ข้าพเจ้ามาบอกท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 22, 'เพราะฉะนั้นบัดนี้จงทราบเป็นแน่ว่า ท่านทั้งหลายจะตายด้วยดาบ ด้วยการกันดารอาหาร และด้วยโรคระบาด ในสถานที่ซึ่งท่านทั้งหลายปรารถนาจะไปอาศัยอยู่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 1, 'ต่อมาเมื่อเยเรมีย์จบการพูดต่อประชาชนทั้งปวงถึงพระวจนะเหล่านี้ทั้งสิ้นของพระเยโฮวาห์พระเจ้าของเขาทั้งหลาย ซึ่งพระเยโฮวาห์พระเจ้าของเขาได้ทรงใช้ท่านให้ไปพูดพระวจนะทั้งสิ้นนี้กับเขาทั้งหลายนั้นแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 2, 'อาซาริยาห์บุตรชายโฮชายาห์และโยฮานันบุตรชายคาเรอาห์ และบรรดาผู้ชายที่โอหังได้พูดกับเยเรมีย์ว่า “ท่านพูดมุสา พระเยโฮวาห์พระเจ้าของเรามิได้ใช้ท่านให้มาพูดว่า ‘อย่าไปอียิปต์ที่จะอาศัยอยู่ที่นั่น’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 3, 'แต่บารุคบุตรชายเนริยาห์ได้ยุท่านให้ต่อสู้กับเรา เพื่อจะมอบเราไว้ในมือของคนเคลเดีย เพื่อเขาทั้งหลายจะได้ฆ่าเรา หรือกวาดเราไปเป็นเชลยในบาบิโลน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 4, 'โยฮานันบุตรชายคาเรอาห์ และบรรดาหัวหน้าของกองทหาร และประชาชนทั้งสิ้น ไม่เชื่อฟังพระสุรเสียงของพระเยโฮวาห์ที่จะอาศัยอยู่ในแผ่นดินยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 5, 'แต่โยฮานันบุตรชายคาเรอาห์และบรรดาหัวหน้าของกองทหารได้พาคนยูดาห์ทุกคนที่เหลืออยู่ไป คือผู้ซึ่งกลับมาอยู่ในแผ่นดินยูดาห์ จากบรรดาประชาชาติที่เขาถูกขับไล่ให้ไปอยู่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 6, 'คือพวกผู้ชายผู้หญิง เด็ก บรรดาธิดา และทุกคนซึ่งเนบูซาระดานผู้บัญชาการทหารรักษาพระองค์ได้เหลือไว้ให้แก่เกดาลิยาห์บุตรชายอาหิคัม ผู้เป็นบุตรชายชาฟาน ทั้งเยเรมีย์ผู้พยากรณ์ และบารุคบุตรชายเนริยาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 7, 'และเขาทั้งหลายได้มายังแผ่นดินอียิปต์ เพราะเขาทั้งหลายไม่เชื่อฟังพระสุรเสียงของพระเยโฮวาห์ และเขาก็มาถึงนครทาปานเหส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 8, 'แล้วพระวจนะของพระเยโฮวาห์มายังเยเรมีย์ในนครทาปานเหสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 9, '“จงถือก้อนหินใหญ่ๆไว้ จงซ่อนไว้ที่ในปูนสอในเตาเผาอิฐ ซึ่งอยู่ที่ทางเข้าไปสู่พระราชวังของฟาโรห์ในนครทาปานเหสท่ามกลางสายตาของคนยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 10, 'และจงกล่าวแก่เขาทั้งหลายว่า พระเยโฮวาห์จอมโยธา พระเจ้าแห่งอิสราเอล ตรัสดังนี้ว่า ดูเถิด เราจะใช้และนําเนบูคัดเนสซาร์กษัตริย์แห่งบาบิโลน ผู้รับใช้ของเรา และท่านจะตั้งพระที่นั่งของท่านเหนือหินเหล่านี้ ซึ่งเราได้ซ่อนไว้ และท่านจะกางพลับพลาหลวงของท่านเหนือหินเหล่านี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 11, 'เมื่อท่านมาถึง ท่านจะโจมตีแผ่นดินอียิปต์มอบผู้ที่กําหนดให้ถึงความตายจะไปหาความตาย ผู้ถูกกําหนดให้เป็นเชลยแก่การเป็นเชลย และผู้ที่ถูกกําหนดให้ถูกดาบให้แก่ดาบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 12, 'และเราจะก่อไฟในวิหารของพระแห่งอียิปต์ และท่านจะเผาเสียและเก็บไปเป็นเชลย และท่านจะปกคลุมตัวเองด้วยแผ่นดินอียิปต์ เหมือนผู้เลี้ยงแกะปกคลุมตัวเองด้วยเสื้อคลุม และท่านจะไปเสียจากที่นั่นด้วยสันติภาพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 13, 'ท่านจะหักเสาศักดิ์สิทธิ์แห่งเมืองเบธเชเมชซึ่งอยู่ในแผ่นดินอียิปต์เสีย และท่านจะเอาไฟเผาวิหารของพระแห่งอียิปต์เสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 1, 'พระวจนะที่มายังเยเรมีย์เกี่ยวด้วยบรรดายิวที่อาศัยอยู่ในแผ่นดินอียิปต์ที่มิกดล ที่ทาปานเหส ที่โนฟ และในแผ่นดินปัทโรส ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 2, '“พระเยโฮวาห์จอมโยธา พระเจ้าแห่งอิสราเอล ตรัสดังนี้ว่า เจ้าทั้งหลายได้เห็นบรรดาเหตุร้ายที่เรานํามาเหนือกรุงเยรูซาเล็ม และเหนือหัวเมืองยูดาห์ทั้งสิ้น ดูเถิด ทุกวันนี้เมืองเหล่านั้นก็เป็นที่รกร้าง ไม่มีผู้ใดอาศัยอยู่ในนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 3, 'เพราะความชั่วซึ่งเขาทั้งหลายได้กระทําได้ยั่วเย้าเราให้มีความโกรธ ด้วยการที่เขาทั้งหลายไปเผาเครื่องหอม และปรนนิบัติพระอื่นซึ่งเขาไม่รู้จัก ไม่ว่าเขาเอง หรือเจ้าทั้งหลาย หรือบรรพบุรุษของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 4, 'อย่างไรก็ดีเราได้ใช้บรรดาผู้รับใช้ของเราคือผู้พยากรณ์ไปหาเจ้าโดยได้ลุกขึ้นแต่เนิ่นๆ และใช้เขาไปกล่าวว่า ‘โอ อย่ากระทําสิ่งที่น่าสะอิดสะเอียนนี้ ซึ่งเราเกลียดชัง’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 5, 'แต่เขาไม่ฟังหรือเงี่ยหูฟัง เพื่อจะหันกลับจากความชั่วร้ายของเขา และไม่เผาเครื่องหอมแก่พระอื่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 6, 'เพราะฉะนั้น เราจึงได้เทความเดือดดาลและความโกรธของเราออกให้พลุ่งขึ้นในหัวเมืองยูดาห์ และในถนนหนทางของกรุงเยรูซาเล็ม และเมืองเหล่านั้นก็ถูกทิ้งไว้เสียเปล่าและรกร้างไป อย่างทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 7, 'เพราะฉะนั้นบัดนี้ พระเยโฮวาห์พระเจ้าจอมโยธา พระเจ้าแห่งอิสราเอล จึงตรัสดังนี้ว่า ทําไมเจ้าทั้งหลายจึงทําความชั่วร้ายยิ่งใหญ่นี้แก่จิตใจเจ้าเอง และตัดเอาผู้ชายผู้หญิงทั้งเด็กและเด็กที่ยังดูดนมเสียจากเจ้า เสียจากท่ามกลางยูดาห์ ไม่มีชนที่เหลืออยู่ไว้แก่เจ้าเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 8, 'ทําไมเจ้าทั้งหลายจึงยั่วเย้าเราให้โกรธด้วยการที่มือของเจ้ากระทํา ด้วยการเผาเครื่องหอมให้แก่พระอื่นในแผ่นดินอียิปต์ที่ที่เจ้ามาอยู่นั้น เพื่อเจ้าจะต้องถูกตัดออกและเป็นที่สาปแช่ง และเป็นที่นินทาท่ามกลางบรรดาประชาชาติแห่งแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 9, 'เจ้าได้ลืมความชั่วของบรรพบุรุษของเจ้า ความชั่วของบรรดากษัตริย์แห่งยูดาห์ บรรดาความชั่วของนางสนมและมเหสีของเขาทั้งหลาย ความชั่วของเจ้าเองและความชั่วของภรรยาของเจ้า ซึ่งเขาทั้งหลายได้กระทําในแผ่นดินยูดาห์ และในถนนหนทางของกรุงเยรูซาเล็มเสียแล้วหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 10, 'แม้กระทั่งวันนี้แล้วเขาทั้งหลายก็ยังมิได้ถ่อมตัวลง หรือเกรงกลัว หรือดําเนินตามราชบัญญัติหรือตามกฎเกณฑ์ของเรา ซึ่งเราให้มีไว้หน้าเจ้าทั้งหลายและหน้าบรรพบุรุษของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 11, 'เพราะฉะนั้น พระเยโฮวาห์จอมโยธา พระเจ้าแห่งอิสราเอล จึงตรัสดังนี้ว่า ดูเถิด เราจะมุ่งหน้าของเราต่อสู้เจ้าให้เกิดการร้าย และจะตัดยูดาห์ออกเสียให้สิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 12, 'เราจะเอาชนยูดาห์ที่เหลืออยู่ ผู้ซึ่งมุ่งหน้ามาที่แผ่นดินอียิปต์เพื่อจะอาศัยอยู่นั้น และเขาทั้งหลายจะถูกผลาญเสียหมด เขาจะล้มลงในแผ่นดินอียิปต์ เขาจะถูกผลาญด้วยดาบและด้วยการกันดารอาหาร ตั้งแต่คนเล็กน้อยที่สุดจนถึงคนใหญ่โตที่สุด เขาทั้งหลายจะตายด้วยดาบและด้วยการกันดารอาหาร และเขาจะกลายเป็นคําสาป เป็นที่น่าตกตะลึง เป็นคําแช่งและเป็นที่นินทา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 13, 'เราจะต้องลงโทษคนเหล่านั้น ผู้อาศัยอยู่ในแผ่นดินอียิปต์ ดังที่เราลงโทษกรุงเยรูซาเล็มด้วยดาบ ด้วยการกันดารอาหาร และด้วยโรคระบาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 14, 'จนคนยูดาห์ที่เหลืออยู่ผู้ซึ่งมาอาศัยในแผ่นดินอียิปต์นั้นจะไม่รอดพ้นหรือเหลือกลับไปยังแผ่นดินยูดาห์ ที่ซึ่งเขาปรารถนาจะกลับไปอาศัยอยู่ เพราะว่าเขาจะไม่ได้กลับไป นอกจากผู้หนีพ้นบางคน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 15, 'แล้วบรรดาผู้ชายผู้รู้ว่าภรรยาของตัวได้ถวายเครื่องหอมแก่พระอื่น และบรรดาผู้หญิงที่ยืนอยู่ใกล้เป็นที่ชุมนุมใหญ่ คือบรรดาประชาชนผู้อาศัยในปัทโรส ในแผ่นดินอียิปต์ ได้ตอบเยเรมีย์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 16, '“สําหรับถ้อยคําซึ่งท่านได้บอกแก่เราในพระนามของพระเยโฮวาห์นั้น เราจะไม่ฟังท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 17, 'แต่เราจะกระทําทุกสิ่งที่เราได้พูดไว้ คือเผาเครื่องหอมถวายเจ้าแม่แห่งฟ้าสวรรค์ และเทเครื่องดื่มถวายแก่พระนางเจ้าดังที่เราได้กระทํา ทั้งพวกเราและบรรพบุรุษของเรา บรรดากษัตริย์และเจ้านายของเรา ในหัวเมืองยูดาห์และในถนนหนทางกรุงเยรูซาเล็ม ทําอย่างนั้นแล้วเราจึงมีอาหารบริบูรณ์และอยู่เย็นเป็นสุข และไม่เห็นเหตุร้ายอย่างใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 18, 'ตั้งแต่เรางดการเผาเครื่องหอมถวายเจ้าแม่แห่งฟ้าสวรรค์ และเทเครื่องดื่มถวายแก่พระนางเจ้า เราก็ขัดสนทุกอย่าง และถูกผลาญด้วยดาบและด้วยการกันดารอาหาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 19, 'เมื่อเราเผาเครื่องหอมถวายเจ้าแม่แห่งฟ้าสวรรค์ และเทเครื่องดื่มถวายแก่พระนางเจ้า ที่เราได้ทําขนมถวายเพื่อนมัสการพระนางเจ้า และที่ได้เทเครื่องดื่มถวายแก่พระนางเจ้านั้น เรากระทํานอกเหนือความเห็นชอบของสามีของเราหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 20, 'แล้วเยเรมีย์ได้ตอบบรรดาประชาชน ทั้งพวกผู้ชายและผู้หญิง คือประชาชนทั้งปวงผู้ให้คําตอบแก่ท่านว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 21, '“สําหรับเครื่องหอมที่ท่านได้เผาถวายในหัวเมืองยูดาห์ และในถนนหนทางกรุงเยรูซาเล็ม ทั้งตัวท่าน บรรพบุรุษของท่าน บรรดากษัตริย์และเจ้านายของท่าน และประชาชนแห่งแผ่นดิน พระเยโฮวาห์มิได้ทรงจดจําไว้ดอกหรือ พระองค์ไม่ได้ทรงนึกถึงหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 22, 'จนพระเยโฮวาห์จะทรงทนต่อไปอีกไม่ไหวแล้ว เพราะเหตุจากการกระทําอันชั่วร้ายของท่าน และเพราะเหตุจากการอันน่าสะอิดสะเอียนซึ่งท่านได้กระทํานั้น เพราะฉะนั้นแผ่นดินของท่านจึงได้กลายเป็นที่ร้างเปล่าและเป็นที่น่าตกตะลึง และเป็นที่สาปแช่ง ปราศจากคนอาศัยดังทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 23, 'เพราะว่าท่านได้เผาเครื่องหอม และเพราะว่าท่านได้กระทําบาปต่อพระเยโฮวาห์ และไม่เชื่อฟังพระสุรเสียงของพระเยโฮวาห์ หรือดําเนินตามพระราชบัญญัติของพระองค์ ตามกฎเกณฑ์ของพระองค์ และตามพระโอวาทของพระองค์ ความร้ายนี้จึงได้ตกแก่ท่าน ดังทุกวันนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 24, 'เยเรมีย์ได้กล่าวแก่ประชาชนทั้งสิ้นและแก่พวกผู้หญิงทั้งสิ้นว่า “บรรดาท่านทั้งหลายแห่งยูดาห์ผู้อยู่ในแผ่นดินอียิปต์ จงฟังพระวจนะของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 25, 'พระเยโฮวาห์จอมโยธา พระเจ้าแห่งอิสราเอล ตรัสดังนี้ว่า ตัวเจ้าและภรรยาของเจ้าได้ยืนยันด้วยปากของเจ้าทั้งหลายเอง และได้กระทําด้วยมือของเจ้าทั้งหลายให้สําเร็จกล่าวว่า ‘เราจะทําตามการปฏิญาณของเราซึ่งเราได้ปฏิญาณไว้แน่นอน คือเผาเครื่องหอมถวายเจ้าแม่แห่งฟ้าสวรรค์ และเทเครื่องดื่มถวายแก่พระนางเจ้า’ แล้วก็ดํารงการปฏิญาณของเจ้าและทําตามการปฏิญาณของเจ้าแน่นอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 26, 'เพราะฉะนั้นบรรดาเจ้าทั้งหลายแห่งยูดาห์ผู้อยู่ในแผ่นดินอียิปต์ จงฟังพระวจนะของพระเยโฮวาห์ พระเยโฮวาห์ตรัสว่า ดูเถิด เราได้ปฏิญาณโดยชื่อใหญ่ยิ่งของเราว่า ปากของคนใดแห่งยูดาห์ตลอดทั่วแผ่นดินอียิปต์จะไม่ออกนามของเราโดยกล่าวว่า ‘องค์พระผู้เป็นเจ้าพระเจ้าทรงพระชนม์อยู่ตราบใด’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 27, 'ดูเถิด เราคอยดูอยู่เพื่อให้เกิดความร้าย มิใช่ความดี ชนยูดาห์ทั้งสิ้นผู้อยู่ในแผ่นดินอียิปต์จะถูกผลาญเสียด้วยดาบ และด้วยการกันดารอาหาร จนกว่าจะถึงที่สุดของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 28, 'และบรรดาผู้ที่หนีพ้นดาบจะกลับจากแผ่นดินอียิปต์ไปยังแผ่นดินยูดาห์ มีจํานวนน้อย และคนยูดาห์ที่เหลืออยู่ทั้งสิ้น ซึ่งมาอาศัยอยู่ที่แผ่นดินอียิปต์ จะทราบว่าคําของใครจะยั่งยืน เป็นคําของเราหรือคําของเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 29, 'พระเยโฮวาห์ตรัสว่า นี่จะเป็นหมายสําคัญแก่เจ้า คือเราจะลงโทษเจ้าในที่นี้ เพื่อเจ้าจะได้ทราบว่า คําของเราจะตั้งมั่นคงอยู่ต่อเจ้าให้เกิดความร้ายเป็นแน่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 30, 'พระเยโฮวาห์ตรัสดังนี้ว่า ดูเถิด เราจะมอบฟาโรห์โฮฟรากษัตริย์แห่งอียิปต์ไว้ในมือศัตรูของเขา และในมือของคนเหล่านั้นที่แสวงหาชีวิตของเขา ดังที่เราได้มอบเศเดคียาห์กษัตริย์แห่งยูดาห์ไว้ในมือของเนบูคัดเนสซาร์กษัตริย์แห่งบาบิโลน ผู้ซึ่งเป็นศัตรูของเขา และแสวงหาชีวิตของเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 1, 'ถ้อยคําซึ่งเยเรมีย์ผู้พยากรณ์บอกแก่บารุคบุตรชายเนริยาห์เมื่อเขาเขียนถ้อยคําเหล่านี้ลงในหนังสือตามคําบอกของเยเรมีย์ ในปีที่สี่แห่งรัชกาลเยโฮยาคิม ราชบุตรของโยสิยาห์ กษัตริย์แห่งยูดาห์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 2, '“โอ บารุคเอ๋ย พระเยโฮวาห์พระเจ้าแห่งอิสราเอล ตรัสแก่ท่านดังนี้ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 3, 'เจ้าว่า ‘บัดนี้ วิบัติแก่ข้า เพราะพระเยโฮวาห์ทรงเพิ่มความทุกข์เข้าที่ความเศร้าโศกของข้า ข้าก็เหน็ดเหนื่อยด้วยการคร่ําครวญของข้า ข้าไม่ประสบความสงบเลย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 4, 'เจ้าจงบอกเขาว่า พระเยโฮวาห์ตรัสดังนี้ว่า ดูเถิด สิ่งใดที่เราก่อสร้างขึ้น เราจะทําลายลง และสิ่งใดที่เราได้ปลูก เราจะถอนขึ้นคือแผ่นดินนี้ทั้งหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 5, 'และเจ้าจะหาสิ่งใหญ่โตเพื่อตัวเองหรือ อย่าหามันเลย เพราะพระเยโฮวาห์ตรัสว่า ดูเถิด เราจะนําเหตุร้ายมาเหนือเนื้อหนังทั้งสิ้น แต่เราจะให้ชีวิตของเจ้าแก่เจ้าเป็นบําเหน็จแห่งการสงครามในทุกสถานที่ที่เจ้าจะไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 1, 'พระวจนะของพระเยโฮวาห์ซึ่งมายังเยเรมีย์ผู้พยากรณ์เกี่ยวด้วยเรื่องบรรดาประชาชาติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 2, 'เรื่องอียิปต์ เกี่ยวด้วยกองทัพของฟาโรห์เนโค กษัตริย์แห่งอียิปต์ ซึ่งอยู่ที่ริมแม่น้ํายูเฟรติส ที่เมืองคารเคมิช และซึ่งเนบูคัดเนสซาร์ กษัตริย์แห่งบาบิโลนได้โจมตีแตกในปีที่สี่แห่งรัชกาลเยโฮยาคิมราชบุตรของโยสิยาห์กษัตริย์แห่งยูดาห์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 3, '“จงเตรียมดั้งและโล่ และประชิดเข้าสงคราม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 4, 'จงผูกอานม้า พลม้าเอ๋ย จงขึ้นม้าเถิด จงสวมหมวกเหล็กของเจ้าเข้าประจําที่ จงขัดหอกของเจ้า จงสวมเสื้อเกราะของเจ้าไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 5, 'ทําไมเราเห็นเขาทั้งหลายครั่นคร้ามและหันหลังกลับ นักรบของเขาทั้งหลายถูกตีล้มลงและได้เร่งหนีไป เขาทั้งหลายไม่เหลียวกลับ ความสยดสยองอยู่ทุกด้าน พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 6, 'คนเร็วก็หนีไปไม่ได้ นักรบก็หนีไปไม่รอด เขาทั้งหลายจะสะดุดและล้มลงในแดนเหนือข้างแม่น้ํายูเฟรติส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 7, 'นี่ใครนะ โผล่ขึ้นมาดั่งน้ําท่วม เหมือนแม่น้ําซึ่งน้ําของมันซัดขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 8, 'อียิปต์โผล่ขึ้นมาอย่างน้ําท่วม เหมือนแม่น้ําของมันซัดขึ้น เขาว่า ‘ข้าจะขึ้น ข้าจะคลุมโลก ข้าจะทําลายหัวเมืองและชาวเมืองนั้นเสีย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 9, 'ม้าทั้งหลายเอ๋ย รุดหน้าไปเถิด รถรบทั้งหลายเอ๋ย เดือดดาลเข้าเถิด จงให้นักรบออกไป คือคนเอธิโอเปียและคนลิเบีย ผู้ถือโล่ คนลิเดีย นักถือและโก่งธนู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 10, 'วันนี้เป็นวันแห่งองค์พระผู้เป็นเจ้าพระเจ้าจอมโยธา เป็นวันแห่งการแก้แค้นที่จะแก้แค้นศัตรูของพระองค์ ดาบจะกินจนอิ่ม และดื่มโลหิตของเขาจนเต็มคราบ เพราะองค์พระผู้เป็นเจ้าพระเจ้าจอมโยธาทําการบูชาในแดนเหนือข้างแม่น้ํายูเฟรติส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 11, 'โอ ธิดาพรหมจารีแห่งอียิปต์เอ๋ย จงขึ้นไปที่กิเลอาด และไปเอาพิมเสน เจ้าได้ใช้ยาเป็นอันมากแล้ว และก็ไร้ผล สําหรับเจ้านั้นรักษาไม่หาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 12, 'บรรดาประชาชาติได้ยินถึงความอายของเจ้า และแผ่นดินก็เต็มด้วยเสียงร้องของเจ้า เพราะว่านักรบสะดุดกัน เขาทั้งหลายได้ล้มลงด้วยกัน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 13, 'พระวจนะซึ่งพระเยโฮวาห์ตรัสกับเยเรมีย์ผู้พยากรณ์ เรื่องการมาของเนบูคัดเนสซาร์กษัตริย์แห่งบาบิโลน เพื่อจะโจมตีแผ่นดินอียิปต์ ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 14, '“จงประกาศในอียิปต์ และป่าวร้องในมิกดล จงป่าวร้องในโนฟและทาปานเหส จงกล่าวว่า ยืนให้พร้อมไว้และเตรียมตัวพร้อม เพราะว่าดาบจะกินอยู่รอบตัวเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 15, 'ทําไมชายที่กล้าหาญของเจ้าจึงหนีเสียเล่า พวกเขาไม่ยืนมั่นอยู่ เพราะว่าพระเยโฮวาห์ได้ทรงผลักเขาล้มลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 16, 'พระองค์ทรงทําให้คนเป็นอันมากล้มตาย เออ เขาล้มทับกันและกัน และเขาทั้งหลายพูดว่า ‘ลุกขึ้นเถอะ ให้เรากลับไปยังชนชาติของเรา ไปยังแผ่นดินที่เราถือกําเนิด เพราะเรื่องดาบของผู้กดขี่ข่มเหง’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 17, 'ที่นั่นพวกเขาได้ร้องว่า ฟาโรห์กษัตริย์แห่งอียิปต์เป็นเพียงแต่เสียงดัง โอกาสของท่านผ่านไปแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 18, 'เพราะบรมมหากษัตริย์ ผู้ซึ่งพระนามของพระองค์คือพระเยโฮวาห์จอมโยธา ตรัสว่า เรามีชีวิตอยู่ตราบใด เขาทาโบร์อยู่ท่ามกลางภูเขาทั้งหลาย และภูเขาคารเมลอยู่ข้างทะเลฉันใด จะมีผู้หนึ่งมาฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 19, 'โอ ธิดาผู้อาศัยในอียิปต์เอ๋ย จงเตรียมข้าวของสําหรับตัวเจ้าเพื่อการถูกกวาดไปเป็นเชลย เพราะว่าเมืองโนฟจะถูกทิ้งไว้เสียเปล่าๆ และรกร้าง ปราศจากคนอาศัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 20, 'อียิปต์เป็นเหมือนวัวสาวตัวงาม แต่การทําลายจากทิศเหนือมาจับเธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 21, 'ทหารรับจ้างที่อยู่ท่ามกลางเธอ ก็เหมือนลูกวัวที่ได้ขุนไว้ให้อ้วน เออ ด้วยเขาทั้งหลายหันกลับและหนีไปด้วยกัน เขาทั้งหลายไม่ยอมยืนหยัด เพราะวันแห่งหายนะของเขาได้มาเหนือเขาทั้งหลาย และเป็นเวลาแห่งการลงโทษเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 22, 'เธอทําเสียงเหมือนงูที่กําลังเลื้อยออกไป เพราะศัตรูของเธอจะเดินกระบวนเข้ามาด้วยกําลังทัพ และมาสู้กับเธอด้วยขวาน เหมือนอย่างคนเหล่านั้นที่โค่นต้นไม้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 23, 'พระเยโฮวาห์ตรัสว่า เขาทั้งหลายจะโค่นป่าของเธอลง แม้ว่าป่านั้นใครจะเข้าไปค้นหาไม่ได้ เพราะว่าพวกเขาทั้งหลายมีจํานวนมากกว่าตั๊กแตน นับไม่ถ้วน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 24, 'ธิดาของอียิปต์จะถูกกระทําให้ได้อาย เธอจะถูกมอบไว้ในมือของชนชาติหนึ่งจากทิศเหนือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 25, 'พระเยโฮวาห์จอมโยธา พระเจ้าแห่งอิสราเอล ตรัสว่า “ดูเถิด เราจะนําการลงโทษมาเหนือเหล่าฝูงชนของโนและฟาโรห์ และอียิปต์และบรรดาพระและกษัตริย์ทั้งปวงของเมืองนั้น ลงเหนือฟาโรห์และคนทั้งหลายที่วางใจในท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 26, 'เราจะมอบเขาทั้งหลายไว้ในมือของบรรดาผู้ที่แสวงหาชีวิตของเขา ในมือของเนบูคัดเนสซาร์ กษัตริย์แห่งบาบิโลน และในมือข้าราชการของท่าน พระเยโฮวาห์ตรัสว่า ภายหลังอียิปต์จึงจะมีคนอาศัยอยู่อย่างสมัยก่อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 27, 'โอ ยาโคบ ผู้รับใช้ของเราเอ๋ย อย่ากลัวเลย โอ อิสราเอลเอ๋ย อย่าครั่นคร้ามเลย เพราะดูเถิด เราจะช่วยเจ้าให้รอดได้จากที่ไกล และช่วยเชื้อสายของเจ้าจากแผ่นดินที่เขาเป็นเชลย ยาโคบจะกลับมาและมีความสงบและความสบาย และไม่มีผู้ใดกระทําให้เขากลัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 28, 'พระเยโฮวาห์ตรัสว่า โอ ยาโคบผู้รับใช้ของเราเอ๋ย อย่ากลัวเลย เพราะเราอยู่กับเจ้า เราจะกระทําให้บรรดาประชาชาติทั้งสิ้นมาถึงซึ่งอวสาน คือประชาชาติที่เราได้ขับเจ้าให้ไปอยู่นั้น แต่ส่วนเจ้าเราจะไม่กระทําให้ถึงอวสานทีเดียว เราจะตีสอนเจ้าตามขนาด เราจะไม่ปล่อยให้เจ้าไม่ถูกทําโทษเป็นอันขาด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 1, 'พระวจนะของพระเยโฮวาห์ซึ่งมายังเยเรมีย์ผู้พยากรณ์เกี่ยวด้วยเรื่องฟีลิสเตียก่อนที่ฟาโรห์โจมตีเมืองกาซา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 2, '“พระเยโฮวาห์ตรัสดังนี้ว่า ดูเถิด น้ําทั้งหลายกําลังขึ้นมาจากทิศเหนือ และจะกลายเป็นกระแสน้ําท่วม มันจะท่วมแผ่นดินและสารพัดซึ่งอยู่ในนั้น ทั้งเมืองและผู้ที่อาศัยอยู่ในเมือง คนจะร้องร่ําไร และชาวแผ่นดินนั้นทุกคนจะคร่ําครวญ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 3, 'เมื่อได้ยินเสียงกีบม้าตัวแข็งแรงของเขากระทืบ และเสียงรถรบของเขากรูกันมา และเสียงล้อรถดังกึกก้อง พวกพ่อก็จะมิได้หันกลับมาดูลูกทั้งหลายของตน เพราะมือของเขาอ่อนเปลี้ยเต็มทีแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 4, 'เพราะวันที่จะมาถึงซึ่งจะทําลายฟีลิสเตียทั้งสิ้น และจะตัดผู้อุปถัมภ์ทุกคนที่เหลืออยู่ออกจากเมืองไทระและเมืองไซดอน เพราะพระเยโฮวาห์จะทรงทําลายคนฟีลิสเตีย คือคนที่เหลืออยู่ในแถบคัฟโทร์นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 5, 'เมืองกาซาก็ล้านเลี่ยน และเมืองอัชเคโลนก็ถูกตัดออกพร้อมด้วยคนที่เหลืออยู่ในหุบเขาของเขา เจ้าจะเชือดเนื้อเถือหนังของเจ้าอีกนานเท่าใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 6, 'โอ ดาบแห่งพระเยโฮวาห์ เจ้าข้า อีกนานเท่าไรท่านจึงจะสงบ จงสอดตัวเข้าไว้ในฝักเสียเถิด จงหยุดพักและอยู่นิ่งๆเสียที');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 7, 'เมื่อพระเยโฮวาห์ทรงกําชับ มันจะสงบได้อย่างไรเล่า พระองค์ทรงบัญชาและแต่งตั้งให้ดาบนั้นต่อสู้อัชเคโลนและต่อสู้ชายทะเล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 1, 'เกี่ยวด้วยเรื่องโมอับ พระเยโฮวาห์จอมโยธา พระเจ้าแห่งอิสราเอล ตรัสดังนี้ว่า “วิบัติแก่เนโบ เพราะเป็นที่ถูกทิ้งร้าง คีริยาธาอิมได้อาย มันถูกยึดแล้ว มิสกาบก็ได้อายและคร้ามกลัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 2, 'จะไม่มีการสรรเสริญโมอับอีกต่อไป ในเมืองเฮชโบนคนเหล่านั้นได้วางแผนปองร้ายต่อโมอับว่า ‘มาเถอะ ให้เราตัดมันออกเสียจากการเป็นประชาชาติ’ โอ เมืองมัดเมนเอ๋ย เจ้าจะถูกตัดลงมาเหมือนกัน ดาบจะไล่ตามเจ้าไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 3, 'จะมีเสียงร้องมาแต่โฮโรนาอิมว่า ‘การร้างเปล่าและการทําลายอย่างใหญ่หลวง’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 4, 'เมืองโมอับถูกทําลายเสียแล้ว ได้ยินเสียงร้องไห้จากพวกเด็กเล็กๆของเธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 5, 'เพราะเขาทั้งหลายจะขึ้นไปร้องไห้ที่ทางขึ้นเมืองลูฮีท เพราะพวกศัตรูได้ยินเสียงร้องไห้เพราะการทําลาย ที่ทางลงจากเมืองโฮโรนาอิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 6, 'หนีเถิด เอาตัวรอดเถิด จงเป็นเหมือนพุ่มไม้ที่ในถิ่นทุรกันดาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 7, 'เพราะว่าเจ้าได้วางใจในผลงานและในทรัพย์สมบัติของเจ้า เจ้าจะต้องถูกยึดด้วย และพระเคโมชจะต้องถูกกวาดไปเป็นเชลย พร้อมกับปุโรหิตและเจ้านายของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 8, 'ผู้ทําลายจะมาเหนือเมืองทุกเมืองและไม่มีเมืองใดจะรอดพ้นไปได้ หุบเขาจะต้องพินาศและที่ราบจะต้องถูกทําลาย ดังที่พระเยโฮวาห์ทรงลั่นพระวาจาไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 9, 'จงให้ปีกแก่โมอับ เพื่อว่ามันจะหนีรอดไปได้ เพราะหัวเมืองของมันจะกลายเป็นที่รกร้าง ปราศจากสิ่งใดอาศัยอยู่ในนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 10, 'ผู้ใดกระทํางานของพระเยโฮวาห์อย่างไม่ซื่อ ผู้นั้นก็ถูกสาป ผู้ที่กันไม่ให้ดาบของตนกระทําให้โลหิตตก ผู้นั้นจะถูกสาป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 11, 'โมอับสบายตั้งแต่หนุ่มๆมา และได้ตกตะกอน มันไม่ได้ถูกถ่ายออกจากภาชนะนี้ไปภาชนะนั้น หรือต้องถูกกวาดไปเป็นเชลย ดังนั้น รสจึงยังอยู่ในนั้นและกลิ่นก็ไม่เปลี่ยนแปลง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 12, 'พระเยโฮวาห์ตรัสว่า “เพราะฉะนั้น ดูเถิด วันเวลาจะมาถึง เมื่อเราจะส่งนักท่องเที่ยวมาให้เขาเพื่อทําให้เขาท่องเที่ยวไป และเทภาชนะของเขาให้เกลี้ยง และทุบไหของเขาให้แตกเป็นชิ้นๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 13, 'แล้วโมอับก็จะได้อายเพราะพระเคโมช อย่างที่วงศ์วานอิสราเอลได้อายเพราะเบธเอล อันเป็นที่วางใจของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 14, 'เจ้าว่าอย่างไรได้ว่า ‘เราเป็นพวกวีรชนและทแกล้วทหารสําหรับสงคราม’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 15, 'เมืองโมอับถูกทําลายและขึ้นไปจากหัวเมืองของมันแล้ว และคนหนุ่มๆที่คัดเลือกแล้วของเมืองก็ลงไปสู่การถูกฆ่า พระบรมมหากษัตริย์ผู้ทรงพระนามว่า พระเยโฮวาห์จอมโยธา ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 16, 'ภัยพิบัติของโมอับอยู่ใกล้แค่คืบแล้ว และความทุกข์ใจของเขาก็เร่งก้าวเข้ามา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 17, 'บรรดาท่านที่อยู่รอบเขา จงเสียใจด้วยเขาเถิด และบรรดาท่านที่รู้จักชื่อเขาด้วย จงกล่าวว่า ‘ไม้ธารพระกรอันทรงฤทธิ์หักเสียแล้ว คือคทาอันรุ่งโรจน์นั้น’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 18, 'ธิดาผู้อาศัยเมืองดีโบนเอ๋ย จงลงมาจากสง่าราศีของเจ้าและนั่งด้วยความกระหาย เพราะผู้ทําลายโมอับจะมาสู้กับเจ้า เขาจะทําลายที่กําบังเข้มแข็งของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 19, 'โอ ชาวเมืองอาโรเออร์เอ๋ย จงยืนเฝ้าอยู่ข้างทาง จงถามชายที่หนีมาและผู้หญิงที่รอดพ้นมาว่า ‘เกิดเรื่องอะไรขึ้น’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 20, 'โมอับถูกกระทําให้ได้อาย เพราะมันแตกเสียแล้ว คร่ําครวญและร้องร่ําไรอยู่ จงบอกแถวแม่น้ําอารโนนว่า ‘โมอับถูกทําลายเสียแล้ว’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 21, 'การพิพากษาได้ตกเหนือที่ราบ เหนือโฮโลน และยาฮาส และเมฟาอาท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 22, 'และดีโบน และเนโบ และเบธดิบลาธาอิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 23, 'และคีริยาธาอิม และเบธกามุล และเบธเมโอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 24, 'และเคริโอท และโบสราห์ และหัวเมืองทั้งสิ้นของแผ่นดินโมอับ ทั้งไกลและใกล้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 25, 'พระเยโฮวาห์ตรัสว่า เขาของโมอับถูกตัดออกแล้ว และแขนของมันก็หักไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 26, 'จงทําให้เขามึนเมา เพราะว่าเขาได้พองตัวขึ้นต่อพระเยโฮวาห์ เพราะฉะนั้นโมอับจะต้องกลิ้งเกลือกอยู่ในอาเจียนของตัว และเขาจะถูกเยาะเย้ยด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 27, 'อิสราเอลไม่ถูกเจ้าเยาะเย้ยหรือ ได้พบเขาท่ามกลางโจรหรือ เมื่อเจ้าพูดถึงเขา เจ้าจึงกระโดดขึ้นด้วยความปีติยินดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 28, 'โอ ชาวเมืองโมอับเอ๋ย จงออกเสียจากหัวเมืองไปอาศัยอยู่ในหิน จงเป็นเหมือนนกเขาซึ่งทํารังอยู่ที่ข้างปากซอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 29, 'เราได้ยินถึงความเห่อเหิมของโมอับ (เขาเห่อเหิมมาก) ได้ยินถึงความยโส ความจองหองของเขา และความเห่อเหิมของเขา และถึงความยกตนข่มท่านในใจของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 30, 'พระเยโฮวาห์ตรัสว่า เรารู้ความโกรธของเขา แต่มันจะไม่สําเร็จ ความเท็จทั้งหลายของเขาจะไม่ถึงความสําเร็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 31, 'เพราะฉะนั้น เราจะคร่ําครวญเพื่อโมอับ เราจะร้องร่ําไรเพื่อโมอับทั้งมวล ใจของเราจะโอดครวญเพื่อคนของคีร์เฮเรส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 32, 'โอ เถาองุ่นแห่งสิบมาห์เอ๋ย เราจะร้องไห้เพื่อเจ้ามากกว่าเพื่อยาเซอร์ กิ่งทั้งหลายของเจ้ายื่นข้ามทะเลจนถึงทะเลของยาเซอร์ ผู้ทําลายได้โจมตีผลไม้ฤดูร้อนและการเก็บองุ่นของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 33, 'ความยินดีและความชื่นบานได้ถูกกวาดออกไปเสียจากเรือกสวนไร่นาและแผ่นดินของโมอับ เราได้กระทําให้เหล้าองุ่นหยุดไหลจากบ่อย่ําองุ่น ไม่มีคนย่ําด้วยเสียงโห่ร้อง เสียงโห่ร้องนั้นไม่ใช่เสียงโห่ร้องเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 34, 'เมืองเฮชโบนและเมืองเอเลอาเลห์ได้ร้องร่ําไห้ เขาทั้งหลายส่งเสียงร้องไกลถึงเมืองยาฮาส จากโศอาร์ถึงโฮโรนาอิม ดังวัวตัวเมียอายุสามปี เพราะสายน้ําทั้งหลายแห่งนิมริมก็จะร้างเปล่าด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 35, 'พระเยโฮวาห์ตรัสว่า เราจะนําอวสานมาสู่ผู้ที่ถวายเครื่องบูชาในปูชนียสถานสูงและเผาเครื่องหอมถวายพระของเขาในโมอับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 36, 'เพราะฉะนั้นใจของเราจะโอดครวญเพื่อโมอับเหมือนอย่างปี่ และใจของเราจะโอดครวญเหมือนปี่เพื่อคนเมืองคีร์เฮเรส เพราะทรัพย์สมบัติที่เขาได้มาก็ได้พินาศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 37, 'ทุกศีรษะจะถูกโกน และทุกเคราจะถูกตัด บนมือทั้งปวงจะมีรอยเชือดเฉือน และจะมีผ้ากระสอบที่บั้นเอว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 38, 'บนหลังคาเรือนทั้งสิ้นของโมอับและตามถนนทั้งหลายในเมืองนั้นจะมีแต่เสียงโอดครวญทั่วไป เพราะเราทุบโมอับเหมือนเราทุบภาชนะที่เราไม่พอใจ พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 39, 'เขาทั้งหลายจะคร่ําครวญว่า ‘โมอับแตกแล้วหนอ โมอับหันหลังกลับด้วยความอับอายแล้วหนอ’ ดังนั้นแหละโมอับได้กลายเป็นที่เยาะเย้ย และเป็นที่หวาดเสียวแก่บรรดาผู้ที่อยู่ล้อมรอบเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 40, 'เพราะพระเยโฮวาห์ตรัสว่า “ดูเถิด ผู้หนึ่งจะโฉบลงเหมือนนกอินทรี และกางปีกออกสู้โมอับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 41, 'เคริโอทถูกจับไปและที่กําบังเข้มแข็งถูกยึด จิตใจของบรรดานักรบแห่งโมอับในวันนั้นจะเหมือนจิตใจของผู้หญิงซึ่งกําลังเจ็บครรภ์คลอดบุตร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 42, 'โมอับจะถูกทําลายและไม่เป็นชนชาติหนึ่งอีกต่อไป เพราะว่าเขาพองตัวขึ้นต่อพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 43, 'พระเยโฮวาห์ตรัสว่า โอ ชาวเมืองโมอับเอ๋ย ความสยดสยอง หลุมพรางและกับดัก จะอยู่เหนือเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 44, 'ผู้ใดที่หนีจากความสยดสยองจะตกหลุมพราง และผู้ที่ปีนออกมาจากหลุมพรางก็จะติดกับ เพราะเราจะนําสิ่งเหล่านี้มาเหนือโมอับ ในปีแห่งการลงโทษเขา พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 45, 'ผู้ลี้ภัยได้ไปยืนอยู่อย่างหมดแรงที่ในเงาเมืองเฮชโบน เพราะว่าไฟจะออกมาจากเฮชโบน เปลวไฟจะออกมาจากท่ามกลางสิโหน มันจะทําลายดินแดนของโมอับและกระหม่อมของบรรดาคนแห่งความอลเวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 46, 'โอ โมอับเอ๋ย วิบัติแก่เจ้า ชนชาติแห่งพระเคโมชกําลังวอดวายอยู่แล้ว เพราะบรรดาบุตรชายของเจ้าถูกจับไปเป็นเชลย และบุตรสาวของเจ้าก็เข้าในความเป็นเชลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 47, 'แต่เรายังจะให้โมอับกลับสู่สภาพเดิมในกาลต่อไป พระเยโฮวาห์ตรัสดังนี้แหละ” ข้อพิพากษาโมอับมีเพียงเท่านี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 1, 'เกี่ยวด้วยเรื่องคนอัมโมน พระเยโฮวาห์ตรัสว่า “อิสราเอลไม่มีบุตรชายหรือ เขาไม่มีผู้รับมรดกหรือ แล้วทําไมกษัตริย์ของพวกเขาจึงรับกาดเป็นมรดก และประชาชนของท่านอาศัยอยู่ในหัวเมืองของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 2, 'พระเยโฮวาห์ตรัสว่า เพราะฉะนั้น ดูเถิด วันเวลาจะมาถึง เมื่อเราจะกระทําให้ได้ยินเสียงสัญญาณสงครามในนครรับบาห์ของคนอัมโมน มันจะกลายเป็นกองซากปรักหักพัง และธิดาทั้งหลายของเมืองนั้นจะถูกเผาเสียด้วยไฟ แล้วอิสราเอลจะเป็นผู้รับมรดกของคนเหล่านั้นที่เคยเป็นผู้รับมรดกของเขา พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 3, 'โอ เฮชโบนเอ๋ย จงคร่ําครวญ เพราะเมืองอัยถูกทําลาย บุตรสาวแห่งนครรับบาห์เอ๋ย จงร้องร่ําไร จงเอาผ้ากระสอบคาดเอวไว้ จงโอดครวญ วิ่งไปวิ่งมาอยู่ท่ามกลางรั้วต้นไม้ เพราะกษัตริย์ของพวกเขาจะต้องถูกกวาดไปเป็นเชลย พร้อมกับปุโรหิตและเจ้านายของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 4, 'โอ บุตรสาวผู้กลับสัตย์เอ๋ย ทําไมเจ้าโอ้อวดบรรดาหุบเขา หุบเขาของเจ้ามีน้ําไหล ผู้วางใจในสมบัติของตนว่า ‘ใครจะมาสู้ฉันนะ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 5, 'องค์พระผู้เป็นเจ้าพระเจ้าจอมโยธาตรัสว่า ดูเถิด เราจะนําความสยดสยองมาเหนือเจ้า จากทุกคนที่อยู่รอบตัวเจ้า และเจ้าจะถูกขับไล่ออกไป ชายทุกคนตรงออกไปข้างหน้าเขา และจะไม่มีใครรวบรวมคนลี้ภัยได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 6, 'แต่ภายหลังเราจะให้คนอัมโมนกลับสู่สภาพเดิม” พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 7, 'เกี่ยวกับเรื่องเมืองเอโดม พระเยโฮวาห์จอมโยธา ตรัสดังนี้ว่า “สติปัญญาไม่มีในเทมานอีกแล้วหรือ คําปรึกษาพินาศไปจากผู้เฉลียวฉลาดแล้วหรือ สติปัญญาของเขาสูญหายไปเสียแล้วหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 8, 'โอ ชาวเมืองเดดานเอ๋ย จงหนี จงหันกลับ จงอาศัยในที่ลึก เพราะว่าเราจะนําภัยพิบัติของเอซาวมาเหนือเขา เวลาเมื่อเราจะลงโทษเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 9, 'ถ้าคนเก็บองุ่นมาหาเจ้า เขาจะไม่ทิ้งองุ่นตกค้างไว้บ้างหรือ ถ้าขโมยมาเวลากลางคืน เขาจะไม่ทําลายเพียงพอแก่ตัวเขาเท่านั้นหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 10, 'แต่เราได้เปลือยเอซาวให้เปลือยเลย เราได้เปิดที่ซ่อนของเขา และเขาไม่สามารถซ่อนตัวได้ เชื้อสายของเขาถูกทําลาย และพี่น้องของเขา และเพื่อนบ้านของเขา ไม่มีเขาอีกแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 11, 'จงทิ้งเด็กกําพร้าพ่อของเจ้าไว้เถิด เราจะให้เขามีชีวิตอยู่ และให้แม่ม่ายของเจ้าวางใจในเราเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 12, 'เพราะพระเยโฮวาห์ตรัสดังนี้ว่า “ดูเถิด ถ้าคนที่ยังไม่สมควรจะดื่มจากถ้วยนั้นยังต้องดื่ม เจ้าจะพ้นโทษไปได้หรือ เจ้าจะพ้นโทษไปไม่ได้ เจ้าจะต้องดื่ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 13, 'พระเยโฮวาห์ตรัสว่า เราได้ปฏิญาณต่อตัวของเราเองว่า โบสราห์จะต้องกลายเป็นที่รกร้าง เป็นที่ตําหนิติเตียน เป็นที่ที่ถูกทิ้งไว้เสียเปล่า และเป็นคําสาปแช่ง และหัวเมืองทั้งสิ้นของเขาจะเป็นที่ที่ถูกทิ้งไว้เสียเปล่าอยู่เนืองนิตย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 14, 'ข้าพเจ้าได้ยินข่าวลือจากพระเยโฮวาห์ ทูตคนหนึ่งถูกส่งไปท่ามกลางบรรดาประชาชาติ บอกว่า “เจ้าทั้งหลายจงรวบรวมกันเข้า และมาต่อสู้เมืองนั้น และลุกขึ้นเพื่อกระทําสงครามเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 15, 'เพราะว่า ดูเถิด เราจะกระทําเจ้าให้เล็กท่ามกลางบรรดาประชาชาติ ให้เป็นที่ดูหมิ่นท่ามกลางมนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 16, 'เพราะความหวาดเสียวของเจ้าได้หลอกลวงเจ้า ทั้งความเห่อเหิมแห่งใจของเจ้า โอ เจ้าผู้ซึ่งอาศัยอยู่ในซอกหิน ผู้ยึดยอดภูเขาไว้เอ๋ย แม้เจ้าทํารังของเจ้าสูงเหมือนอย่างรังนกอินทรี เราจะฉุดเจ้าลงมาจากที่นั่น พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 17, 'เอโดมจะกลายเป็นที่รกร้าง ทุกคนที่ผ่านเอโดมจะตกตะลึง และจะเย้ยหยันในภัยพิบัติทั้งสิ้นของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 18, 'อย่างเมื่อเมืองโสโดม และเมืองโกโมราห์ และหัวเมืองใกล้เคียงของมันถูกทําลายล้าง พระเยโฮวาห์ตรัสว่า ไม่มีใครจะพํานักอยู่ที่นั่น ไม่มีบุตรของมนุษย์คนใดจะอาศัยในเมืองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 19, 'ดูเถิด เขาจะขึ้นมาอย่างสิงโตจากคลื่นของลุ่มแม่น้ําจอร์แดนโจนเข้าใส่คอกของแกะที่แข็งแรง แต่เราจะกระทําให้เขาวิ่งหนีเธอไปอย่างฉับพลัน และใครเป็นผู้ที่เลือกสรรไว้ ที่เราจะแต่งตั้งไว้เหนือเธอ ใครเป็นอย่างเราเล่า ใครจะนัดเราเล่า ผู้เลี้ยงแกะคนใดจะทนยืนอยู่ต่อหน้าเราได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 20, 'เพราะฉะนั้นจงฟังคําปรึกษาซึ่งพระเยโฮวาห์ทรงเตรียมไว้ต่อสู้เมืองเอโดม และพระประสงค์ทั้งหลายซึ่งพระองค์ได้ดําริไว้ต่อสู้ชาวเมืองเทมาน แน่ล่ะ ถึงตัวเล็กที่สุดในฝูงก็จะต้องถูกลากเอาไป แน่ละ พระองค์จะทรงกระทําให้ที่อาศัยของเขาร้างเปล่าไปพร้อมกับเขาด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 21, 'แผ่นดินโลกสั่นสะเทือนเพราะเสียงที่มันล้ม เสียงคร่ําครวญของเขาได้ยินถึงทะเลแดง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 22, 'ดูเถิด ผู้หนึ่งจะเหาะขึ้นและโฉบลงเหมือนนกอินทรี และกางปีกของมันออกสู้โบสราห์ และจิตใจของนักรบแห่งเอโดมในวันนั้นจะเป็นเหมือนจิตใจของหญิงปวดท้องคลอดบุตร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 23, 'เกี่ยวด้วยเรื่องเมืองดามัสกัส เมืองฮามัทและเมืองอารปัดได้ขายหน้า เพราะเขาทั้งหลายได้ยินข่าวร้าย เขาก็กลัวลาน ทะเลก็ทุรนทุราย มันสงบลงไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 24, 'เมืองดามัสกัสก็อ่อนเพลียแล้ว เธอหันหนีและความกลัวจนตัวสั่นจับเธอไว้ ความแสนระทมและความเศร้ายึดเธอไว้อย่างผู้หญิงกําลังคลอดบุตร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 25, 'เมืองแห่งการสรรเสริญนั้นถูกทอดทิ้งแล้วหนอ คือเมืองที่เต็มด้วยความชื่นบานนั่นน่ะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 26, 'เพราะฉะนั้นคนหนุ่มๆของเมืองนั้นจะล้มลงตามถนนทั้งหลายในเมืองนั้น และบรรดาทหารของเมืองนั้นจะถูกตัดออกในวันนั้น พระเยโฮวาห์จอมโยธาตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 27, 'และเราจะก่อไฟขึ้นในกําแพงเมืองดามัสกัส และไฟนั้นจะกินพระราชวังของเบนฮาดัดเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 28, 'เกี่ยวด้วยเรื่องคนเคดาร์และราชอาณาจักรฮาโซร์ ซึ่งเนบูคัดเนสซาร์กษัตริย์แห่งบาบิโลนจะโจมตี พระเยโฮวาห์ตรัสดังนี้ว่า จงลุกขึ้น รุดเข้าไปสู้คนเคดาร์ จงทําลายประชาชนแห่งตะวันออกเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 29, 'เต็นท์และฝูงแพะแกะของเขาจะถูกริบเสีย ทั้งม่านและภาชนะทั้งสิ้นของเขา อูฐของเขาจะถูกนําเอาไปจากเขา และคนจะร้องแก่เขาว่า ‘ความสยดสยองทุกด้าน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 30, 'พระเยโฮวาห์ตรัสว่า โอ ชาวเมืองฮาโซร์เอ๋ย หนีเถิด จงสัญจรไปไกล ไปอาศัยในที่ลึก เพราะเนบูคัดเนสซาร์กษัตริย์แห่งบาบิโลนได้ดําริแผนงานต่อสู้เจ้า และก่อตั้งความประสงค์ไว้สู้เจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 31, 'พระเยโฮวาห์ตรัสว่า จงลุกขึ้น รุดหน้าไปสู้ประชาชาติหนึ่งที่มั่งมี ซึ่งอาศัยอยู่อย่างมั่นคง ไม่มีประตูเมืองและไม่มีดาลประตู อยู่แต่ลําพัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 32, 'อูฐของเขาทั้งหลายจะกลายเป็นของที่ปล้นมาได้ และฝูงวัวอันมากมายของเขาจะเป็นของที่ริบมา พระเยโฮวาห์ตรัสว่า เราจะกระจายเขาไปทุกทิศลม คือคนที่อยู่ในมุมที่ไกลที่สุด และเราจะนําภัยพิบัติมาจากทุกด้านของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 33, 'เมืองฮาโซร์จะเป็นที่อาศัยของมังกร เป็นที่ที่ถูกทิ้งไว้ให้รกร้างอยู่เป็นนิตย์ ไม่มีใครจะพํานักที่นั่น ไม่มีบุตรของมนุษย์คนใดจะอาศัยในเมืองนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 34, 'พระวจนะของพระเยโฮวาห์ ซึ่งมายังเยเรมีย์ผู้พยากรณ์เกี่ยวด้วยเรื่องเมืองเอลามในตอนต้นรัชกาลเศเดคียาห์กษัตริย์แห่งยูดาห์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 35, '“พระเยโฮวาห์จอมโยธาตรัสดังนี้ว่า ดูเถิด เราจะหักคันธนูของเอลาม ซึ่งเป็นหัวใจแห่งกําลังของเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 36, 'และเราจะนําลมทั้งสี่ทิศจากฟ้าทั้งสี่ส่วนมาสู้เอลาม และเราจะกระจายเขาไปตามลมเหล่านั้นทั้งหมด จะไม่มีประชาชาติใดซึ่งผู้ถูกขับไล่ออกไปจากเอลามจะมาไม่ถึง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 37, 'ด้วยว่าเราจะกระทําให้เอลามสยดสยองต่อหน้าศัตรูของเขาทั้งหลาย และต่อหน้าผู้ที่แสวงหาชีวิตของเขา พระเยโฮวาห์ตรัสว่า เราจะนําเหตุร้ายมาถึงเขาทั้งหลาย คือความพิโรธอันแรงกล้า เราจะใช้ให้ดาบไล่ตามเขาทั้งหลาย จนกว่าเราจะได้เผาผลาญเขาเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 38, 'และเราจะตั้งพระที่นั่งของเราในเอลาม และจะทําลายกษัตริย์และบรรดาเจ้านายของเขาทั้งหลาย พระเยโฮวาห์ตรัสดังนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 39, 'พระเยโฮวาห์ตรัสว่า แต่ในกาลต่อไปเราจะให้เอลามกลับสู่สภาพเดิม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 1, 'พระวจนะซึ่งพระเยโฮวาห์ทรงกล่าวด้วยเรื่องบาบิโลน เกี่ยวด้วยเรื่องแผ่นดินของชาวเคลเดีย โดยเยเรมีย์ผู้พยากรณ์ ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 2, '“จงประกาศท่ามกลางบรรดาประชาชาติและป่าวร้อง จงตั้งธงขึ้นและป่าวร้อง อย่าปิดบังไว้เลย และว่า ‘บาบิโลนถูกยึดแล้ว พระเบลก็ได้อาย พระเมโรดัคก็ถูกทุบแหลกเป็นชิ้นๆ รูปเคารพทั้งหลายของเมืองนั้นถูกกระทําให้ได้อาย และรูปปั้นทั้งหลายก็ถูกทุบแหลกเป็นชิ้นๆ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 3, 'เพราะว่ามีประชาชาติหนึ่งออกจากทิศเหนือมาต่อสู้เมืองนั้น ซึ่งจะกระทําให้แผ่นดินของเธอเป็นที่รกร้าง และจะไม่มีสิ่งใดอาศัยในนั้นเลย ทั้งมนุษย์และสัตว์จะย้ายออกไปและจะออกไปเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 4, 'พระเยโฮวาห์ตรัสว่า ในวันเหล่านั้นและในเวลานั้น ประชาชนอิสราเอลและประชาชนยูดาห์จะมารวมกัน มาพลางร้องไห้พลาง และเขาทั้งหลายจะไปแสวงหาพระเยโฮวาห์พระเจ้าของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 5, 'เขาทั้งหลายจะถามหาทางไปศิโยนโดยหันหน้าตรงไปเมืองนั้น กล่าวว่า ‘มาเถิด ให้พวกเรามาติดสนิทกับพระเยโฮวาห์โดยทําพันธสัญญาเนืองนิตย์ซึ่งจะไม่ลืมเลย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 6, 'ประชาชนของเราเป็นแกะที่หลง บรรดาผู้เลี้ยงของเขาทั้งหลายได้พาเขาหลงไป หันเขาทั้งหลายไปเสียบนภูเขา เขาทั้งหลายได้เดินจากภูเขาไปหาเนินเขา เขาลืมคอกของเขาเสียแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 7, 'บรรดาผู้ที่พบเข้าก็กินเขา และศัตรูของเขาได้กล่าวว่า ‘เราไม่มีความผิด เพราะเขาทั้งหลายได้กระทําบาปต่อพระเยโฮวาห์ผู้เป็นที่อยู่อันเที่ยงธรรมของเขาทั้งหลาย คือพระเยโฮวาห์อันเป็นความหวังของบรรพบุรุษของเขาทั้งหลาย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 8, 'จงหนีจากท่ามกลางบาบิโลน จงออกไปเสียจากแผ่นดินของชาวเคลเดีย และเป็นเหมือนแพะตัวผู้นําหน้าฝูง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 9, 'เพราะ ดูเถิด เราจะเร้าและนําบรรดาประชาชาติใหญ่หมู่หนึ่งจากประเทศเหนือมาต่อสู้บาบิโลน และเขาทั้งหลายจะเรียงรายพวกเขามาต่อสู้กับเธอ ตรงนั้นแหละเธอจะถูกยึด ลูกธนูของเขาทั้งหลายก็เหมือนนักรบที่มีฝีมือ ไม่มีคนใดจะกลับมือเปล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 10, 'พระเยโฮวาห์ตรัสว่า ประเทศเคลเดียจะถูกปล้น บรรดาผู้ที่ปล้นเธอจะอิ่มหนํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 11, 'โอ บรรดาผู้ปล้นมรดกของเราเอ๋ย แม้ว่าเจ้าเปรมปรีดิ์ แม้ว่าเจ้าเริงโลด แม้เจ้าอ้วนพีอย่างวัวสาวอยู่ที่หญ้า และร้องอย่างวัวตัวผู้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 12, 'มารดาของเจ้าจะละอายอย่างอดสู และนางที่คลอดเจ้าจะต้องอับอาย ดูเถิด ที่รั้งท้ายแห่งบรรดาประชาชาติจะเป็นถิ่นทุรกันดาร ที่แห้งแล้งและทะเลทราย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 13, 'เมืองนั้นจะไม่มีคนอาศัยเพราะพระพิโรธของพระเยโฮวาห์ แต่จะเป็นที่รกร้างทั้งหมด ทุกคนที่ผ่านเมืองบาบิโลนไปจะตกตะลึง และจะเย้ยหยันในภัยพิบัติทั้งสิ้นของเมืองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 14, 'จงเรียงรายตัวของเจ้าทั้งหลายเข้ามาสู้บาบิโลนให้รอบข้าง บรรดาเจ้าที่โก่งคันธนูจงยิงเธอ อย่าเสียดายลูกธนู เพราะเธอได้กระทําบาปต่อพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 15, 'จงเปล่งเสียงโห่ร้องสู้เธอให้รอบข้าง เธอยอมแพ้แล้ว รากฐานของเธอล้มลงแล้ว กําแพงของเธอถูกพังลงมาแล้ว เพราะนี่เป็นการแก้แค้นของพระเยโฮวาห์ จงทําการแก้แค้นเธอ ทํากับเธออย่างที่เธอได้กระทํามาแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 16, 'จงตัดผู้หว่านเสียจากบาบิโลน และตัดผู้ที่ถือเคียวในฤดูเกี่ยว เหตุเพราะดาบของผู้บีบบังคับทุกคนจึงหันเข้าหาชนชาติของตน และทุกคนจะหนีไปยังแผ่นดินของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 17, 'อิสราเอลเป็นเหมือนแกะที่ถูกกระจัดกระจายไปแล้ว พวกสิงโตได้ขับล่าเขาไป ทีแรกกษัตริย์อัสซีเรียกินเขา ในที่สุดนี้เนบูคัดเนสซาร์กษัตริย์แห่งบาบิโลนได้หักกระดูกของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 18, 'เพราะฉะนั้นพระเยโฮวาห์จอมโยธา พระเจ้าแห่งอิสราเอล ตรัสดังนี้ว่า ดูเถิด เราจะลงโทษกษัตริย์แห่งบาบิโลนและแผ่นดินของท่าน ดังที่เราได้ลงโทษกษัตริย์แห่งอัสซีเรีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 19, 'เราจะให้อิสราเอลกลับสู่ลานหญ้าของเขา และเขาจะกินอยู่บนคารเมลและในบาชาน และเขาจะอิ่มใจบนเนินเขาเอฟราอิมและในกิเลอาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 20, 'พระเยโฮวาห์ตรัสว่า ในวันเหล่านั้นและในเวลานั้น จะหาความชั่วช้าในอิสราเอลและจะหาไม่ได้เลย จะหาบาปในยูดาห์ก็หาไม่ได้เลย เพราะเราจะให้อภัยแก่ชนเหล่านั้นผู้ที่เราเหลือไว้ให้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 21, 'พระเยโฮวาห์ตรัสว่า จงขึ้นไปสู้แผ่นดินเมราธาอิม และต่อสู้ชาวเมืองเปโขด จงฆ่าเขาและตามทําลายเสียให้สิ้นเชิง และจงกระทําทุกอย่างตามที่เราได้บัญชาเจ้าไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 22, 'เสียงสงครามอยู่ในแผ่นดิน และเสียงการทําลายอย่างใหญ่หลวงก็อยู่ในนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 23, 'ค้อนทุบของแผ่นดินโลกทั้งหมดได้ถูกตัดลงและถูกหักเสียแล้วหนอ บาบิโลนได้กลายเป็นที่รกร้างท่ามกลางบรรดาประชาชาติแล้วหนอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 24, 'โอ บาบิโลนเอ๋ย เราวางบ่วงดักเจ้าและเจ้าก็ติดบ่วงนั้น และเจ้าไม่รู้เรื่อง เขามาพบเจ้าและจับเจ้า เพราะเจ้าได้ขันสู้กับพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 25, 'พระเยโฮวาห์ได้ทรงเปิดคลังอาวุธของพระองค์ และทรงให้อาวุธแห่งพระพิโรธของพระองค์ออกมา เพราะนี่แหละเป็นพระราชกิจแห่งองค์พระผู้เป็นเจ้าพระเจ้าจอมโยธาในแผ่นดินแห่งชาวเคลเดีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 26, 'จงมาต่อสู้กับเธอจากทุกมุมโลก จงเปิดบรรดาฉางของเธอ จงกองเธอไว้เหมือนอย่างกองข้าวและทําลายเสียจนสิ้นเชิง อย่าให้เธอเหลืออยู่เลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 27, 'จงฆ่าวัวผู้ของเธอให้หมด ให้มันทั้งหลายลงไปยังการฆ่า วิบัติแก่มันทั้งหลาย เพราะวันเวลาของมันมาถึงแล้ว คือเวลาแห่งการลงโทษมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 28, 'เสียงของเขาทั้งหลายที่ได้หนีและรอดพ้นจากแผ่นดินบาบิโลน ไปประกาศการแก้แค้นของพระเยโฮวาห์พระเจ้าของเราในศิโยน คือการแก้แค้นแทนพระวิหารของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 29, 'จงเรียกนักธนูมาต่อสู้กับบาบิโลน คือบรรดาคนที่โก่งธนู จงตั้งค่ายไว้รอบมัน อย่าให้ผู้ใดหนีรอดพ้นไปได้ จงกระทํากับเธอตามการกระทําของเธอ จงกระทําแก่เธออย่างที่เธอได้กระทําแล้ว เพราะเธอจองหองลองดีกับพระเยโฮวาห์ พระองค์ผู้บริสุทธิ์แห่งอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 30, 'เพราะฉะนั้น คนหนุ่มๆของเธอจะล้มลงตามถนนทั้งหลาย และทหารของเธอทั้งสิ้นจะถูกตัดออกในวันนั้น พระเยโฮวาห์ตรัสดังนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 31, 'องค์พระผู้เป็นเจ้าพระเจ้าจอมโยธาตรัสว่า โอ ผู้จองหองเอ๋ย ดูเถิด เราต่อสู้กับเจ้า เพราะว่าวันเวลาของเจ้ามาถึงแล้ว คือเวลาที่เราจะลงโทษเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 32, 'ผู้จองหองจะสะดุดและล้มลง จะไม่มีผู้ใดพยุงเขาขึ้นได้ และเราจะก่อไฟในบรรดาหัวเมืองของเขา และไฟจะกินบรรดาที่อยู่รอบเขาเสียสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 33, 'พระเยโฮวาห์จอมโยธาตรัสดังนี้ว่า ประชาชนอิสราเอลและประชาชนยูดาห์ถูกบีบบังคับด้วยกัน บรรดาผู้ที่จับเขาทั้งหลายไปเป็นเชลยได้ยึดเขาไว้มั่น เขาทั้งหลายปฏิเสธไม่ยอมให้เขาไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 34, 'พระผู้ไถ่ของเขาทั้งหลายนั้นเข้มแข็ง พระนามของพระองค์คือพระเยโฮวาห์จอมโยธา พระองค์จะทรงแก้คดีของเขาโดยตลอด เพื่อพระองค์จะประทานความสงบแก่แผ่นดิน แต่ประทานความไม่สงบแก่ชาวเมืองบาบิโลน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 35, 'พระเยโฮวาห์ตรัสว่า ให้ดาบอยู่เหนือชาวเคลเดีย และเหนือชาวเมืองบาบิโลน และเหนือเจ้านายและนักปราชญ์ของเธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 36, 'ให้ดาบอยู่เหนือผู้มุสา เพื่อเขาจะกลายเป็นคนโง่ไป ให้ดาบอยู่เหนือบรรดานักรบของเธอ เพื่อเขาทั้งหลายจะครั่นคร้าม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 37, 'ให้ดาบอยู่เหนือม้าทั้งหลายของเขาและรถรบของเขา และอยู่เหนือบรรดาชนที่ปะปนกันท่ามกลางเขา เพื่อเขาทั้งหลายจะกลายเป็นผู้หญิงไป ให้ดาบอยู่เหนือทรัพย์สมบัติทั้งสิ้นของเขา เพื่อว่าทรัพย์สมบัตินั้นจะถูกปล้นเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 38, 'ให้ความแห้งแล้งอยู่เหนือน้ําทั้งหลายของเธอ เพื่อน้ําทั้งหลายนั้นจะได้แห้งไป เพราะเป็นแผ่นดินแห่งรูปเคารพสลัก และเขาทั้งหลายก็คลั่งไคล้รูปนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 39, 'เพราะฉะนั้น สัตว์ป่าทั้งหลายและบรรดาหมาจิ้งจอกจะอาศัยในบาบิโลน และนกเค้าแมวจะอาศัยอยู่ในนั้น เมืองนั้นจะไม่มีประชาชนอยู่อีกต่อไปเป็นนิตย์ คือไม่มีชาวเมืองอาศัยอยู่ตลอดชั่วอายุ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 40, 'พระเยโฮวาห์ตรัสว่า เมื่อพระเจ้าได้ทรงคว่ําเมืองโสโดมและเมืองโกโมราห์และหัวเมืองใกล้เคียง ดังนั้นจะไม่มีคนพํานักอยู่ที่นั่น และไม่มีบุตรของมนุษย์คนใดอาศัยอยู่ในเมืองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 41, 'ดูเถิด ชนชาติหนึ่งจะมาจากทิศเหนือ ประชาชาติอันเข้มแข็งชาติหนึ่ง และกษัตริย์หลายองค์จะถูกเร้าให้มาจากที่ไกลที่สุดของแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 42, 'เขาทั้งหลายจะจับคันธนูและหอก เขาทั้งหลายดุร้าย และจะไม่มีความกรุณา เสียงของเขาทั้งหลายจะเหมือนเสียงทะเลคะนอง เขาทั้งหลายจะขี่ม้า เรียงรายกันเป็นแถวเข้าสู้สงครามกับเจ้านะ โอ บุตรสาวแห่งบาบิโลนเอ๋ย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 43, 'กษัตริย์แห่งบาบิโลนได้ยินข่าวเรื่องนั้น และพระหัตถ์ของพระองค์ก็อ่อนลง ความแสนระทมจับหัวใจเขา เจ็บปวดอย่างผู้หญิงกําลังคลอดบุตร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 44, 'ดูเถิด เขาจะขึ้นมาอย่างสิงโตจากคลื่นของลุ่มแม่น้ําจอร์แดนโจนเข้าใส่คอกของแกะที่แข็งแรง แต่เราจะกระทําให้เขาวิ่งหนีเธอไปอย่างฉับพลัน และใครเป็นผู้ที่เลือกสรรไว้ ที่เราจะแต่งตั้งไว้เหนือเธอ ใครเป็นอย่างเราเล่า ใครจะนัดเราเล่า ผู้เลี้ยงแกะคนใดจะทนยืนอยู่ต่อหน้าเราได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 45, 'เพราะฉะนั้นจงฟังแผนงานซึ่งพระเยโฮวาห์ทรงกระทําไว้ต่อสู้บาบิโลน และบรรดาพระประสงค์ซึ่งพระองค์ได้ดําริขึ้นต่อสู้กับแผ่นดินของชาวเคลเดีย แน่ละตัวเล็กที่สุดที่อยู่ในฝูงก็ต้องถูกลากเอาไป แน่ละคอกของเขานั้นจะรกร้างไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 46, 'แผ่นดินโลกสั่นสะเทือนเพราะเสียงของการที่บาบิโลนถูกจับเป็นเชลย และเสียงคร่ําครวญดังไปท่ามกลางบรรดาประชาชาติ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 1, 'พระเยโฮวาห์ตรัสดังนี้ว่า “ดูเถิด เราจะปลุกกระแสลมแห่งการทําลาย ต่อสู้กับบาบิโลน และต่อสู้กับคนที่อาศัยท่ามกลางพวกที่ลุกขึ้นสู้กับเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 2, 'เราจะส่งผู้ฝัดไปยังบาบิโลนและเขาทั้งหลายจะฝัดเธอ และเขาทั้งหลายจะทําให้แผ่นดินของเธอว่างเปล่า เมื่อเขาทั้งหลายมาล้อมเธอไว้ทุกด้าน ในวันแห่งความยากลําบาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 3, 'อย่าให้นักธนูโก่งคันธนูได้ อย่าให้เขาสวมเสื้อเกราะลุกขึ้นได้ อย่าไว้ชีวิตคนหนุ่มๆของเธอเลย จงทําลายพลโยธาของเธอทั้งหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 4, 'ดังนั้นเขาทั้งหลายจะถูกฆ่าล้มลงในแผ่นดินของชาวเคลเดีย และจะถูกแทงทะลุที่ถนนเมืองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 5, 'เพราะว่าอิสราเอลและยูดาห์มิได้ถูกทอดทิ้งโดยพระเจ้าของเขาทั้งหลายพระเยโฮวาห์จอมโยธา ถึงแม้แผ่นดินของเขาเต็มด้วยความผิดบาปต่อองค์บริสุทธิ์แห่งอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 6, 'จงหนีเสียจากท่ามกลางบาบิโลน ให้ทุกคนเอาชีวิตของตนให้รอดพ้นเถิด เจ้าอย่าถูกตัดออกด้วยความชั่วช้าของเธอเลย เพราะนี่เป็นเวลาแห่งการแก้แค้นของพระเยโฮวาห์ พระองค์จะทรงตอบสนองต่อเธอสักครั้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 7, 'บาบิโลนได้เคยเป็นถ้วยทองคําในพระหัตถ์ของพระเยโฮวาห์ กระทําให้แผ่นดินโลกทั้งสิ้นมึนเมาไป บรรดาประชาชาติได้ดื่มเหล้าองุ่นของเธอ เพราะฉะนั้นประชาชาติต่างจึงบ้าคลั่งไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 8, 'บาบิโลนได้ล้มลงและแตกไปอย่างฉับพลัน จงคร่ําครวญเพื่อเธอเถิด จงเอาพิมเสนมาให้เธอบรรเทาปวด ชะรอยจะรักษาเธอให้หายได้กระมัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 9, 'เราทั้งหลายอยากจะรักษาบาบิโลนให้หาย แต่เธอไม่หาย ละทิ้งเธอเสียเถิด และให้เราไป ต่างไปยังประเทศของตน เพราะว่าการพิพากษาเธอได้ขึ้นไปถึงฟ้าสวรรค์ และได้ถูกยกขึ้นถึงฟากฟ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 10, 'พระเยโฮวาห์ทรงนําความชอบธรรมออกมาให้เรา มาเถิด ให้เราประกาศพระราชกิจของพระเยโฮวาห์พระเจ้าของเราที่ในศิโยน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 11, 'จงฝนลูกธนู จงหยิบโล่ขึ้นมา พระเยโฮวาห์ทรงเร้าใจบรรดากษัตริย์คนมีเดีย เพราะว่าพระประสงค์ของพระองค์เกี่ยวด้วยเรื่องบาบิโลน ก็คือการทําลายมันเสีย เพราะนั่นแหละเป็นการแก้แค้นของพระเยโฮวาห์ คือการแก้แค้นแทนพระวิหารของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 12, 'จงปักธงชิดบรรดากําแพงของบาบิโลน จงทําคนเฝ้าให้เข้มแข็ง จงตั้งคนยามขึ้น จงเตรียมกองซุ่มไว้ เพราะพระเยโฮวาห์ทรงวางแผนงานและทั้งทรงกระทําเสร็จตามที่พระองค์ทรงลั่นพระวาจาเกี่ยวด้วยชาวเมืองบาบิโลน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 13, 'โอ เจ้าผู้อาศัยตามน้ํามากหลาย ผู้มีสมบัติมากมายเอ๋ย อวสานของเจ้ามาถึงแล้ว เส้นความโลภของเจ้าได้ถูกตัดขาดเสียแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 14, 'พระเยโฮวาห์จอมโยธาได้ทรงปฏิญาณต่อพระองค์เองว่า แน่ละ เราจะให้เจ้ามีคนเต็มเมืองให้มากอย่างตั๊กแตน และเขาทั้งหลายจะเปล่งเสียงโห่ร้องมีชัยเหนือเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 15, 'พระองค์ทรงสร้างโลกด้วยฤทธิ์เดชของพระองค์ พระองค์ทรงสถาปนาพิภพไว้ด้วยพระสติปัญญาของพระองค์ และทรงคลี่ท้องฟ้าออกด้วยความเข้าใจของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 16, 'เมื่อพระองค์ทรงเปล่งพระสุรเสียงก็มีเสียงน้ําคะนองในท้องฟ้า และทรงกระทําให้หมอกลอยขึ้นจากปลายพิภพ ทรงกระทําฟ้าแลบเพื่อฝน และทรงนําลมมาจากพระคลังของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 17, 'มนุษย์ทุกคนโฉดในทางความรู้ของตน ช่างทองทุกคนจะได้อายเพราะรูปเคารพสลักของตน เพราะรูปเคารพหล่อของเขาเป็นของเท็จ และไม่มีลมหายใจในรูปเคารพนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 18, 'มันเป็นของไร้ค่า และเป็นผลงานแห่งความผิดพลาด มันจะต้องพินาศเมื่อถึงเวลาการลงโทษ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 19, 'พระองค์ผู้ทรงเป็นส่วนของยาโคบไม่เหมือนสิ่งเหล่านี้ เพราะพระองค์ทรงเป็นผู้ที่ก่อร่างทุกสิ่งขึ้น และอิสราเอลเป็นตระกูลที่เป็นมรดกของพระองค์ พระเยโฮวาห์จอมโยธาเป็นพระนามของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 20, 'เจ้าเป็นค้อนและยุทโธปกรณ์ของเรา เราจะทุบบรรดาประชาชาติเป็นชิ้นๆด้วยเจ้า เราจะทําลายราชอาณาจักรทั้งหลายด้วยเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 21, 'เราจะทุบม้าและคนขี่เป็นชิ้นๆด้วยเจ้า เราจะทุบบรรดารถรบและคนขับให้เป็นชิ้นๆด้วยเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 22, 'เราจะทุบผู้ชายและผู้หญิงเป็นชิ้นๆด้วยเจ้า เราจะทุบคนแก่และคนหนุ่มเป็นชิ้นๆด้วยเจ้า เราจะทุบคนหนุ่มและหญิงพรหมจารีเป็นชิ้นๆด้วยเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 23, 'เราจะทุบผู้เลี้ยงแกะและฝูงแกะเป็นชิ้นๆด้วยเจ้า เราจะทุบชาวนาและวัวคู่แอกของเขาเป็นชิ้นๆด้วยเจ้า เราจะทุบเจ้าเมืองและปลัดเมืองเป็นชิ้นๆด้วยเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 24, 'พระเยโฮวาห์ตรัสว่า เราจะสนองบาบิโลนและบรรดาชาวประเทศเคลเดียท่ามกลางสายตาของเจ้า ซึ่งบรรดาความชั่วร้ายอันเขาได้กระทําในศิโยน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 25, 'พระเยโฮวาห์ตรัสว่า โอ ภูเขาซึ่งทําลายเอ๋ย ดูเถิด เราต่อสู้เจ้า เจ้าผู้ทําลายแผ่นดินโลกทั้งสิ้น เราจะเหยียดมือของเราออกต่อสู้เจ้า และกลิ้งเจ้าลงมาจากหน้าผา และจะกระทําให้เจ้าเป็นภูเขาที่ถูกไหม้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 26, 'เขาจะไม่เอาหินจากเจ้าไปทําศิลามุมเอก และไม่เอาหินไปทํารากฐาน แต่เจ้าจะถูกทิ้งร้างเป็นนิตย์ พระเยโฮวาห์ตรัสดังนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 27, 'จงตั้งธงไว้บนแผ่นดิน จงเป่าแตรท่ามกลางประชาชาติทั้งหลาย จงเตรียมประชาชาติทั้งหลายไว้ทําสงครามกับเธอ จงเรียกราชอาณาจักรต่อไปนี้มาสู้กับเธอ อารารัต มินนี และอัชเคนัส จงตั้งจอมทัพไว้ต่อสู้เธอ จงทําให้ม้าขึ้นมาเหมือนพวกตัวบุ้งคัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 28, 'จงเตรียมบรรดาประชาชาติมาทําสงครามกับเธอ คือเตรียมบรรดากษัตริย์แห่งมีเดีย พร้อมทั้งเจ้าเมืองและปลัดเมืองทั้งหลาย และทุกแผ่นดินที่ขึ้นแก่มีเดีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 29, 'แผ่นดินนั้นจะสะเทือนสะท้านและโศกเศร้า เพราะบรรดาพระประสงค์ของพระเยโฮวาห์จะเกิดขึ้นเพื่อต่อสู้บาบิโลน เพื่อจะกระทําให้แผ่นดินบาบิโลนเป็นที่รกร้างปราศจากคนอาศัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 30, 'นักรบแห่งบาบิโลนหยุดรบแล้ว เขาทั้งหลายค้างอยู่ในที่กําบังเข้มแข็งของเขา กําลังของเขาถอยเสียแล้ว เขาทั้งหลายกลายเป็นเหมือนผู้หญิง เขาได้เผาที่อาศัยของเธอแล้ว และดาลประตูของเธอก็หัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 31, 'นักวิ่งคนหนึ่งวิ่งไปพบนักวิ่งอีกคนหนึ่ง ทูตคนหนึ่งวิ่งไปพบทูตอีกคนหนึ่ง เพื่อทูลกษัตริย์แห่งบาบิโลนว่า เมืองของพระองค์ถูกยึดไว้ทุกด้านแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 32, 'ท่าลุยข้ามก็ถูกยึดแล้ว ที่เป็นบึงเป็นหนองก็ถูกไฟไหม้และบรรดาทหารก็ระส่ําระสาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 33, 'เพราะพระเยโฮวาห์จอมโยธา พระเจ้าแห่งอิสราเอล ตรัสดังนี้ว่า บุตรสาวแห่งบาบิโลนก็เหมือนลานนวดข้าว ณ เวลาที่เธอถูกเหยียบย่ํา อีกสักประเดี๋ยว เวลาเกี่ยวก็จะมาถึงแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 34, 'ให้ชาวเมืองศิโยนพูดว่า “เนบูคัดเนสซาร์กษัตริย์แห่งบาบิโลนได้กินข้าพเจ้าเสียแล้ว ท่านได้ขย้ําข้าพเจ้า ท่านได้ทําให้ข้าพเจ้าเป็นภาชนะว่างเปล่า ท่านได้กลืนข้าพเจ้าดั่งมังกร ท่านได้อิ่มท้องด้วยของอร่อยของข้าพเจ้า แล้วท่านก็คายข้าพเจ้าทิ้งเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 35, 'ความทารุณที่ได้กระทําแก่ข้าพเจ้าและแก่เนื้อหนังของข้าพเจ้าจงตกเหนือบาบิโลน” ให้เยรูซาเล็มกล่าวว่า “ให้ความรับผิดชอบสําหรับเลือดตกของเราอยู่แก่ชาวประเทศเคลเดีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 36, 'เพราะฉะนั้น พระเยโฮวาห์ตรัสดังนี้ว่า “ดูเถิด เราจะแก้คดีของเจ้า และกระทําการแก้แค้นเพื่อเจ้า เราจะทําทะเลของเธอให้แห้ง และกระทําแหล่งน้ําของเธอให้เหือด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 37, 'และบาบิโลนจะกลายเป็นกองซากปรักหักพัง เป็นที่อยู่อาศัยของมังกร เป็นที่น่าตกตะลึง และเป็นที่เย้ยหยัน ปราศจากคนอาศัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 38, 'เขาทั้งหลายจะคํารามด้วยกันอย่างสิงโต เขาทั้งหลายจะคํารามอย่างลูกสิงโต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 39, 'ขณะที่เขาทั้งหลายผ่าวร้อน เราจะเตรียมการเลี้ยงให้ และกระทําให้เขาทั้งหลายมึนเมา เพื่อเขาทั้งหลายจะปลาบปลื้มยินดี จนเขาทั้งหลายจะนอนหลับอยู่ชั่วกาลนาน ไม่ตื่นเลย พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 40, 'เราจะนําเขาทั้งหลายลงมาดุจลูกแกะไปยังการฆ่า เหมือนแกะผู้และแพะผู้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 41, 'เชชักถูกยึดแล้วหนอ ซึ่งเป็นที่สรรเสริญของทั่วแผ่นดินโลกถูกจับแล้วเล่า บาบิโลนได้กลายเป็นที่น่าตกตะลึงท่ามกลางบรรดาประชาชาติเสียแล้วหนอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 42, 'ทะเลขึ้นมาเหนือบาบิโลน คลื่นอย่างมากมายคลุมเธอไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 43, 'หัวเมืองของเธอกลายเป็นที่รกร้าง เป็นแผ่นดินที่แห้งแล้งและเป็นถิ่นทุรกันดาร เป็นแผ่นดินที่ไม่มีผู้ใดอาศัยอยู่และไม่มีบุตรของมนุษย์คนใดข้ามไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 44, 'และเราจะลงโทษพระเบลในบาบิโลน ท่านกลืนอะไรเข้าไปแล้ว เราจะเอาออกจากปากท่านเสีย บรรดาประชาชาติจะไม่ไหลไปหาท่านอีก เออ กําแพงแห่งบาบิโลนจะล้มลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 45, 'ประชาชนของเราเอ๋ย จงออกไปเสียจากท่ามกลางเธอ ให้ทุกคนเอาชีวิตของตนรอดจากความพิโรธอันร้อนแรงของพระเยโฮวาห์เถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 46, 'อย่าให้ใจของเจ้าวิตก และอย่าให้กลัวต่อข่าวลือซึ่งได้ยินในแผ่นดินนั้น จะมีข่าวลือเรื่องหนึ่งมาในปีหนึ่ง และหลังจากนั้นอีกปีหนึ่งก็มีข่าวลือเรื่องหนึ่งมา และความทารุณก็มีอยู่ในแผ่นดินและผู้ครอบครองก็ต่อสู้กับผู้ครอบครอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 47, 'เพราะฉะนั้น ดูเถิด วันเวลาจะมาถึง เมื่อเราจะลงโทษรูปเคารพสลักแห่งบาบิโลน แผ่นดินทั้งสิ้นของเธอจะต้องได้อาย และบรรดาชาวบาบิโลนซึ่งถูกฆ่าจะล้มลงที่ท่ามกลางเธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 48, 'แล้วฟ้าสวรรค์และแผ่นดินโลกและสรรพสิ่งที่มีอยู่ในนั้น จะร้องเพลงเหนือบาบิโลน เพราะว่าผู้ทําลายจะมาจากทิศเหนือต่อสู้กับเธอ พระเยโฮวาห์ตรัสดังนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 49, 'บาบิโลนทําให้คนอิสราเอลที่ถูกฆ่าล้มลงฉันใด คนที่ถูกฆ่าแห่งแผ่นดินโลกทั้งมวลจะต้องล้มลงที่บาบิโลนฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 50, 'เจ้าทั้งหลายผู้ที่รอดพ้นไปจากดาบ หนีไปเถิด อย่ายืนนิ่งอยู่ จงระลึกถึงพระเยโฮวาห์จากที่ไกล และให้กรุงเยรูซาเล็มเข้ามาในจิตใจของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 51, 'เราได้อาย เพราะเราได้ยินคําเยาะเย้ย ความอัปยศคลุมหน้าเราไว้ เพราะคนต่างชาติได้เข้าในสถานบริสุทธิ์แห่งพระนิเวศของพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 52, 'พระเยโฮวาห์ตรัสว่า “เพราะฉะนั้น ดูเถิด วันเวลาจะมาถึง เมื่อเราจะลงโทษรูปเคารพสลักของเธอ และคนที่บาดเจ็บจะคร่ําครวญอยู่ทั่วแผ่นดินทั้งสิ้นของเธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 53, 'พระเยโฮวาห์ตรัสว่า ถึงแม้บาบิโลนจะขึ้นไปบนสวรรค์ และถึงแม้เธอจะสร้างป้อมกันที่สูงอันเข้มแข็งของเธอไว้ บรรดาผู้ทําลายก็ยังจะมาจากเราเหนือเธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 54, 'มีเสียงร้องมาจากบาบิโลน และเสียงการทําลายอย่างใหญ่หลวงจากแผ่นดินของคนเคลเดีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 55, 'เพราะพระเยโฮวาห์ได้ทรงกระทําให้บาบิโลนเป็นที่ทิ้งร้าง และกระทําเสียงที่ใหญ่โตของเธอให้เงียบ เมื่อคลื่นของเธอคะนองเหมือนสายน้ําอันยิ่งใหญ่ เสียงอึกทึกของเขาก็เปล่งออกมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 56, 'เพราะว่าผู้ทําลายได้มาเหนือเธอ มาเหนือบาบิโลน บรรดานักรบของเธอถูกยึดแล้ว คันธนูของเขาทั้งหลายถูกหักเป็นชิ้นๆ เพราะพระเยโฮวาห์ทรงเป็นพระเจ้าแห่งการตอบแทน พระองค์จะทรงสนองเป็นแน่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 57, 'เราจะกระทําให้เจ้านายของเธอและนักปราชญ์ของเธอ เจ้าเมืองของเธอ ผู้บังคับบัญชาของเธอ และนักรบของเธอมึนเมา จนเขาทั้งหลายจะนอนหลับอยู่ชั่วกาลนาน ไม่ตื่นเลย พระบรมมหากษัตริย์ผู้ทรงพระนามว่าพระเยโฮวาห์จอมโยธาตรัสดังนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 58, 'พระเยโฮวาห์จอมโยธาตรัสดังนี้ว่า กําแพงอันกว้างขวางของบาบิโลนจะถูกปราบลงให้เรียบเสมอพื้นดิน และประตูเมืองสูงของเธอจะถูกเผาด้วยไฟ บรรดาประชาชนจะทํางานอย่างไร้ผล และชนชาติทั้งหลายจะเหน็ดเหนื่อยก็เพื่อเผาไฟเสียเท่านั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 59, 'ถ้อยคําซึ่งเยเรมีย์ผู้พยากรณ์ได้บัญชาแก่เสไรอาห์บุตรชายเนริยาห์ ผู้เป็นบุตรชายมาอาเสอาห์ เมื่อเขาไปยังบาบิโลนกับเศเดคียาห์กษัตริย์แห่งยูดาห์ ในปีที่สี่แห่งรัชกาลของท่านนั้น เสไรอาห์เป็นหัวหน้าจัดที่พัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 60, 'เยเรมีย์ได้เขียนบรรดาความร้ายทั้งสิ้นซึ่งจะมาถึงบาบิโลนนั้นไว้ในหนังสือ บรรดาถ้อยคําเหล่านี้เป็นคําที่เขียนไว้เกี่ยวด้วยเรื่องบาบิโลน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 61, 'และเยเรมีย์พูดกับเสไรอาห์ว่า “เมื่อท่านมาถึงบาบิโลนแล้ว ท่านจะเห็นและท่านจงอ่านถ้อยคําเหล่านี้ทั้งหมดนะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 62, 'และท่านจงกล่าวว่า ‘โอ ข้าแต่พระเยโฮวาห์ พระองค์ได้ตรัสต่อสู้กับสถานที่นี้ว่า จะทรงตัดออกเสีย เพื่อว่าจะไม่มีอะไรเหลืออยู่ในนั้นเลย ไม่ว่ามนุษย์หรือสัตว์ แต่จะเป็นที่รกร้างเป็นนิตย์’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 63, 'ต่อมาเมื่อท่านอ่านหนังสือนี้จบแล้ว จงเอาหินก้อนหนึ่งมัดติดมันไว้ และโยนมันทิ้งไปกลางแม่น้ํายูเฟรติส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 64, 'และจงกล่าวว่า ‘บาบิโลนจะจมลงอย่างนี้แหละ จะไม่ลอยขึ้นอีกเลยเนื่องด้วยความร้ายซึ่งเราจะนํามาเหนือเธอ และพวกเขาจะเหน็ดเหนื่อย’” ถ้อยคําของเยเรมีย์มีเพียงนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 1, 'เศเดคียาห์มีพระชนมายุยี่สิบเอ็ดพรรษาเมื่อท่านขึ้นเสวยราชย์ และท่านครอบครองในกรุงเยรูซาเล็มสิบเอ็ดปี พระราชมารดาของท่านมีชื่อว่าฮามุทาล เป็นบุตรสาวของเยเรมีย์แห่งลิบนาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 2, 'และท่านได้กระทําสิ่งที่ชั่วร้ายในสายพระเนตรพระเยโฮวาห์ ตามการทุกอย่างที่เยโฮยาคิมได้กระทํานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 3, 'เป็นเพราะพระพิโรธของพระเยโฮวาห์เป็นแน่ สิ่งต่างๆได้เป็นไปถึงเพียงนี้ในกรุงเยรูซาเล็มและยูดาห์ จนพระองค์ทรงเหวี่ยงเขาทั้งหลายออกไปเสียจากพระพักตร์ของพระองค์ และเศเดคียาห์ได้กบฏต่อกษัตริย์แห่งบาบิโลน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 4, 'และต่อมาในปีที่เก้าแห่งรัชกาลของท่าน ในวันที่สิบของเดือนที่สิบ เนบูคัดเนสซาร์กษัตริย์แห่งเมืองบาบิโลน พร้อมกับกองทัพทั้งสิ้นของท่านได้มาต่อสู้กับกรุงเยรูซาเล็มและล้อมเมืองไว้ และสร้างเครื่องล้อมไว้รอบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 5, 'กรุงนั้นจึงถูกล้อมอยู่จนปีที่สิบเอ็ดแห่งกษัตริย์เศเดคียาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 6, 'เมื่อวันที่เก้าของเดือนที่สี่การกันดารอาหารในกรุงนั้นร้ายกาจมาก จนไม่มีอาหารเลยสําหรับประชาชนแห่งแผ่นดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 7, 'แล้วกรุงนั้นก็แตกและทหารทั้งหมดก็หนีออกไปจากกรุงในกลางคืน ไปตามทางประตูเมืองระหว่างกําแพงทั้งสอง ไปตามทางราชอุทยาน (ฝ่ายคนเคลเดียก็ล้อมอยู่รอบกรุง) และเขาทั้งหลายไปทางที่ราบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 8, 'แต่กองทัพของคนเคลเดียได้ไล่ติดตามกษัตริย์ไป และไปทันเศเดคียาห์ในที่ราบเมืองเยรีโค และกองทัพทั้งสิ้นของท่านก็กระจัดกระจายไปจากท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 9, 'และเขาก็จับกษัตริย์ นําขึ้นมาถวายแด่กษัตริย์แห่งบาบิโลนที่ตําบลริบลาห์ในแผ่นดินฮามัท และกษัตริย์ก็ได้พิพากษาโทษท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 10, 'กษัตริย์แห่งบาบิโลนได้ประหารบุตรชายทั้งหลายของเศเดคียาห์ต่อหน้าต่อตาท่าน และได้ประหารเจ้านายทั้งสิ้นแห่งยูดาห์เสียที่ตําบลริบลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 11, 'ท่านทําตาของเศเดคียาห์ให้บอดไป และกษัตริย์แห่งบาบิโลนตีตรวนไว้และนําท่านไปยังบาบิโลน และขังท่านไว้ในคุกจนวันที่ท่านสิ้นชีวิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 12, 'เมื่อวันที่สิบในเดือนที่ห้า ซึ่งเป็นปีที่สิบเก้าของรัชกาลเนบูคัดเนสซาร์กษัตริย์แห่งบาบิโลน เนบูซาระดานผู้บังคับบัญชาทหารรักษาพระองค์ ผู้ปรนนิบัติกษัตริย์บาบิโลน ได้เข้าไปในกรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 13, 'และเขาได้เผาพระนิเวศของพระเยโฮวาห์ และพระราชวัง และบรรดาเรือนทั้งสิ้นของกรุงเยรูซาเล็มเสีย ท่านเผาบ้านของผู้ยิ่งใหญ่ทั้งหลายเสียหมดทุกหลัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 14, 'และกองทัพทั้งสิ้นของคนเคลเดีย ผู้อยู่กับผู้บังคับบัญชาทหารรักษาพระองค์ได้ทลายกําแพงทั้งหมดที่อยู่รอบกรุงเยรูซาเล็มลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 15, 'และเนบูซาระดานผู้บังคับบัญชาทหารรักษาพระองค์ ได้นําประชาชนบางคนที่ยากจนและประชาชนที่เหลืออยู่ ผู้ซึ่งเหลืออยู่ในกรุง และผู้ที่หลบหนี ผู้หนีไปหากษัตริย์แห่งบาบิโลนพร้อมกับฝูงชนที่เหลืออยู่ไปเป็นเชลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 16, 'แต่เนบูซาระดานผู้บังคับบัญชาทหารรักษาพระองค์ได้ละคนจนในแผ่นดินไว้บ้าง ให้เป็นคนทําสวนองุ่น และเป็นคนทําไร่ไถนา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 17, 'บรรดาเสาทองเหลืองซึ่งอยู่ในพระนิเวศของพระเยโฮวาห์ และเชิงและขันสาครทองเหลือง ซึ่งอยู่ในพระนิเวศของพระเยโฮวาห์นั้น คนเคลเดียได้ทุบเสียเป็นชิ้นๆ และขนเอาทองเหลืองทั้งหมดไปยังบาบิโลน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 18, 'และเขาได้ขนเอาหม้อขนาดใหญ่ด้วย อีกทั้งพลั่ว ตะไกรตัดไส้ตะเกียง และชามและช้อน และภาชนะทองเหลืองทั้งสิ้น ซึ่งใช้ในการปรนนิบัติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 19, 'ทั้งอ่าง ถาดรองไฟ และชาม และหม้อขนาดใหญ่ และเชิงเทียน และช้อน และอ่างน้ํา อะไรที่ทําด้วยทองคํา ผู้บังคับบัญชาทหารรักษาพระองค์ก็เอาไปเป็นทองคํา อะไรที่ทําด้วยเงินก็เอาไปเป็นเงิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 20, 'ส่วนเสาสองเสา และขันสาครหนึ่งลูก กับวัวทองเหลืองสิบสองตัวซึ่งอยู่ใต้เชิงทั้งหลาย ซึ่งกษัตริย์ซาโลมอนได้สร้างไว้สําหรับพระนิเวศของพระเยโฮวาห์ ทองเหลืองของสิ่งของเหล่านี้ทั้งสิ้นก็ชั่งกันไม่ไหว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 21, 'ส่วนเสานั้น เสาต้นหนึ่งสูงสิบแปดศอก วัดรอบสิบสองศอก และความหนาของมันเป็นสี่นิ้ว กลางกลวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 22, 'บนเสานี้มีบัวคว่ํายอดทองเหลือง บัวคว่ํายอดอันหนึ่งสูงห้าศอก มีตาข่ายและลูกทับทิม ทั้งหมดทําด้วยทองเหลืองอยู่รอบบัวคว่ํายอด และเสาที่สองก็มีเหมือนกัน ทั้งลูกทับทิมด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 23, 'ข้างๆมีลูกทับทิมเก้าสิบหกลูก บนตาข่ายโดยรอบนั้นมีลูกทับทิมทั้งหมดหนึ่งร้อยลูก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 24, 'และผู้บัญชาการทหารรักษาพระองค์ได้จับเสไรอาห์ปุโรหิตใหญ่ และเศฟันยาห์ปุโรหิตที่สอง และผู้เฝ้าธรณีประตูอีกสามคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 25, 'และจากกรุงนั้นท่านจับขันทีคนหนึ่ง ผู้บังคับทหาร และที่ปรึกษาของกษัตริย์เจ็ดคน ซึ่งพบอยู่ในกรุงนั้น และเลขานุการของผู้บังคับบัญชาของกองทัพ ผู้ซึ่งเกณฑ์ประชาชนแห่งแผ่นดิน และประชาชนแห่งแผ่นดินอีกหกสิบคนซึ่งพบอยู่ท่ามกลางกรุงนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 26, 'และเนบูซาระดานผู้บังคับบัญชาทหารรักษาพระองค์ได้จับคนเหล่านี้นําไปถวายกษัตริย์แห่งบาบิโลนที่ตําบลริบลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 27, 'และกษัตริย์แห่งบาบิโลนทรงตีเขา และประหารเขาเสียที่ตําบลริบลาห์ในแผ่นดินฮามัท ดังนั้นแหละ ยูดาห์ก็ได้ถูกนําไปเป็นเชลยออกไปจากแผ่นดินของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 28, 'ต่อไปนี้เป็นจํานวนประชาชนซึ่งเนบูคัดเนสซาร์จับไปเป็นเชลย ในปีที่เจ็ด พวกยิวสามพันยี่สิบสามคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 29, 'ในปีที่สิบแปดแห่งรัชกาลเนบูคัดเนสซาร์ ท่านขนเชลยจากกรุงเยรูซาเล็มแปดร้อยสามสิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 30, 'ในปีที่ยี่สิบสามแห่งรัชกาลเนบูคัดเนสซาร์ เนบูซาระดานผู้บังคับบัญชาทหารรักษาพระองค์จับยิวเป็นเชลยเจ็ดร้อยสี่สิบห้าคน รวมคนทั้งหมดเป็นสี่พันกับหกร้อยคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 31, 'และต่อมาในปีที่สามสิบเจ็ดแห่งการเป็นเชลยของเยโฮยาคีนกษัตริย์แห่งยูดาห์นั้น เมื่อวันที่ยี่สิบห้าในเดือนที่สิบสอง เอวิลเมโรดักกษัตริย์แห่งบาบิโลน ในปีที่ท่านขึ้นเสวยราชย์ ท่านได้ยกศีรษะของเยโฮยาคีนกษัตริย์แห่งยูดาห์ขึ้น และได้นําท่านออกมาจากคุก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 32, 'พระองค์ตรัสอย่างเมตตาต่อท่าน และให้นั่งบนที่นั่งเหนือกว่าบรรดากษัตริย์ทั้งหลายที่อยู่ในบาบิโลน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 33, 'ดังนั้นเยโฮยาคีนจึงถอดเครื่องแต่งกายนักโทษออกเสีย และท่านได้รับประทานที่โต๊ะเสวยต่อพระพักตร์กษัตริย์ทุกวันตลอดชีวิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 34, 'ส่วนงบประมาณที่ให้นั้นท่านก็ได้รับพระราชทานจากกษัตริย์แห่งบาบิโลนตามความต้องการรายวันอยู่เสมอ ตลอดเมื่อท่านมีชีวิตอยู่จนวันตายของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 1, 'กรุงที่คับคั่งด้วยพลเมืองมาอ้างว้างอยู่ได้หนอ กรุงที่รุ่งเรืองอยู่ท่ามกลางประชาชาติมากลายเป็นดั่งหญิงม่ายหนอ กรุงที่เป็นดั่งเจ้าหญิงท่ามกลางเมืองทั้งหลายก็กลับเป็นเมืองขึ้นเขาไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 2, 'กรุงนั้นร่ําไห้สะอื้นในราตรีกาล และน้ําตาของเธอก็อาบแก้ม เธอจะหาใครท่ามกลางคนที่รักเธอให้มาปลอบเธอก็หาไม่พบ บรรดาพวกเพื่อนของเธอสิ้นทุกคนได้ทรยศต่อเธอ เขาทั้งปวงกลับเป็นศัตรูของเธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 3, 'ยูดาห์ได้ถูกกวาดไปเป็นเชลย ได้รับความทุกข์ใจ ต้องทํางานอย่างทาส เธอต้องพํานักอยู่ท่ามกลางประชาชาติทั้งหลาย เธอไม่พบที่หยุดพักสงบเลย บรรดาผู้ข่มเหงได้ไล่ทันเธอเมื่อเวลาเธอทุกข์ใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 4, 'ถนนหนทางที่เข้าเมืองศิโยนก็คร่ําครวญอยู่ เพราะไม่มีผู้ใดเดินไปในงานเทศกาลที่เคร่งครัดทั้งหลายนั้น บรรดาประตูเมืองของเธอก็รกร้างเสียแล้ว พวกปุโรหิตของเธอได้พากันถอนใจ สาวพรหมจารีทั้งหลายของเธอก็ต้องทนทุกข์ และตัวเธอเองก็ได้รับความขมขื่นยิ่งนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 5, 'พวกคู่อริของเธอกลายเป็นหัวหน้า พวกศัตรูของเธอได้จําเริญขึ้น ด้วยว่าพระเยโฮวาห์ได้ทรงกระทําให้เธอทนทุกข์ เพราะความทรยศอันมหันต์ของเธอ ลูกเต้าทั้งหลายของเธอตกไปเป็นเชลยต่อหน้าคู่อริ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 6, 'และความโอ่อ่าตระการได้พรากไปจากธิดาแห่งศิโยนเสียแล้ว พวกเจ้านายของเธอก็กลับเป็นดุจฝูงกวางที่หาทุ่งหญ้าเลี้ยงชีวิตไม่ได้ และได้วิ่งป้อแป้หนีไปข้างหน้าผู้ไล่ติดตาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 7, 'เยรูซาเล็มเมื่อตกอยู่ในยามทุกข์ใจและยามลําเค็ญก็ได้หวนระลึกถึงสิ่งประเสริฐที่ตนเคยมีในครั้งกระโน้น เมื่อพลเมืองของเธอตกอยู่ในมือของคู่อริ และหามีผู้ใดจะสงเคราะห์เธอไม่ พวกคู่อริเห็นเธอแล้วก็เยาะเย้ยวันสะบาโตทั้งหลายของเธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 8, 'เยรูซาเล็มได้ทําบาปอย่างใหญ่หลวง เหตุฉะนี้เธอจึงถูกไล่ออก บรรดาคนที่เคยให้เกียรติเธอก็ลบหลู่เธอ เพราะเหตุเขาทั้งหลายเห็นความเปลือยเปล่าของเธอ เออ เธอเองได้ถอนใจยิ่งและหันหน้าของเธอไปเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 9, 'มลทินของเธอก็กรังอยู่ในกระโปรงของเธอ และเธอหาได้คํานึงถึงอนาคตของเธอไม่ ดังนั้นเธอจึงได้เสื่อมทรามลงเร็วอย่างน่าใจหาย เธอก็ไม่มีผู้ใดจะเล้าโลม “โอ ข้าแต่พระเยโฮวาห์ ขอทอดพระเนตรความทุกข์ใจของข้าพระองค์ เพราะพวกศัตรูได้พองตัวขึ้นแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 10, 'พวกศัตรูได้ยื่นมือของเขายึดเอาบรรดาของประเสริฐของเธอ ด้วยเธอได้เห็นบรรดาประชาชาติบุกรุกเข้ามาในสถานบริสุทธิ์ของเธอ คือคนที่พระองค์ได้ทรงห้ามไม่ให้เข้ามาในชุมนุมชนของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 11, 'บรรดาพลเมืองของเธอได้ถอนใจใหญ่ เขาทั้งหลายเสาะหาอาหาร และพวกเขาได้เอาของประเสริฐของตัวออกแลกอาหารกิน เพื่อจะได้ประทังชีวิต “โอ ข้าแต่พระเยโฮวาห์ ขอทรงทอดพระเนตรและพิจารณา เพราะข้าพระองค์เป็นที่เหยียดหยามเสียแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 12, '“ดูก่อน ท่านทั้งหลายที่เดินผ่านไป ท่านไม่เกิดความรู้สึกอะไรบ้างหรือ ดูเถิด จงดูซิว่ามีความทุกข์อันใดบ้างไหมที่เหมือนความทุกข์ที่มาสู่ข้าพเจ้า เป็นความทุกข์ซึ่งพระเยโฮวาห์ได้ทรงกระทําแก่ข้าพเจ้าในวันที่พระองค์ทรงกริ้วข้าพเจ้าอย่างเกรี้ยวกราดนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 13, 'พระองค์ได้ทรงส่งเพลิงลงมาจากเบื้องบนให้เข้าไปเหนือกระดูกทั้งหลายของข้าพเจ้า และเพลิงนั้นก็มีชัยชนะต่อกระดูกเหล่านั้น พระองค์ได้ทรงกางตาข่ายไว้ดักเท้าของข้าพเจ้า พระองค์ได้ทรงกระทําให้ข้าพเจ้าต้องหันกลับ พระองค์ได้ทรงกระทําให้ข้าพเจ้าโดดเดี่ยวอ้างว้าง และอ่อนระอาตลอดทั้งวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 14, 'แอกแห่งการละเมิดทั้งมวลของข้าพเจ้าก็ถูกรวบเข้าโดยพระหัตถ์ของพระองค์ทรงรวบมัดไว้ แอกนั้นรัดรึงรอบคอข้าพเจ้า พระองค์ได้ทรงกระทําให้กําลังข้าพเจ้าถอยไป องค์พระผู้เป็นเจ้าได้ทรงมอบข้าพเจ้าไว้ในมือของเขาทั้งหลาย ซึ่งข้าพเจ้าไม่สามารถต่อต้านได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 15, 'องค์พระผู้เป็นเจ้าได้ทรงเหยียบบรรดาผู้มีกําลังแข็งแกร่งของข้าพเจ้าไว้ใต้พระบาทท่ามกลางข้าพเจ้า พระองค์ได้ทรงเกณฑ์ชุมนุมชนเข้ามาต่อสู้ข้าพเจ้า เพื่อจะขยี้ชายฉกรรจ์ของข้าพเจ้าให้แหลกไป องค์พระผู้เป็นเจ้าได้ทรงย่ําบุตรสาวพรหมจารีแห่งยูดาห์ ดั่งเหยียบผลองุ่นลงในบ่อย่ําองุ่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 16, 'เพราะเรื่องเหล่านี้ข้าพเจ้าจึงร้องไห้ นัยน์ตาของข้าพเจ้า เออ นัยน์ตาของข้าพเจ้ามีน้ําตาไหลลงมา เพราะผู้ปลอบโยนที่ควรจะปลอบประโลมใจข้าพเจ้าก็อยู่ไกลจากข้าพเจ้า ลูกๆของข้าพเจ้าก็โดดเดี่ยวอ้างว้าง เพราะพวกศัตรูได้ชัยชนะ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 17, 'เมืองศิโยนได้เหยียดมือทั้งสองออก แต่ก็ไม่มีใครที่เล้าโลมเธอได้ พระเยโฮวาห์ทรงมีพระบัญชาเรื่องยาโคบว่า ให้พวกคู่อริล้อมยาโคบไว้ เยรูซาเล็มเป็นดั่งผู้หญิงเมื่อมีประจําเดือนท่ามกลางเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 18, '“พระเยโฮวาห์ทรงชอบธรรมแล้ว เพราะข้าพเจ้าได้กบฏต่อพระบัญญัติของพระองค์ ดูก่อนบรรดาชนชาติทั้งหลาย ข้าพเจ้าขอท่านได้ฟังและขอมามองดูความทนทุกข์ของข้าพเจ้า สาวพรหมจารีของข้าพเจ้า และหนุ่มๆของข้าพเจ้าตกไปเป็นเชลยแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 19, 'ข้าพเจ้าได้ร้องเรียกบรรดาคนรักของข้าพเจ้า แต่เขาทั้งหลายได้หลอกลวงข้าพเจ้า พวกปุโรหิตและพวกผู้ใหญ่ของข้าพเจ้าก็ตายที่กลางเมือง ขณะเมื่อเขาออกหาอาหารเพื่อประทังชีวิตของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 20, 'โอ ข้าแต่พระเยโฮวาห์ โปรดทอดพระเนตร เพราะข้าพระองค์มีความทุกข์ จิตใจของข้าพระองค์มีความทุรนทุราย จิตใจของข้าพระองค์ยุ่งเหยิงเพราะข้าพระองค์มักกบฏอย่างร้ายกาจ นอกบ้านมีคนต้องคมดาบตาย ในบ้านก็เหมือนมฤตยู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 21, 'เขาทั้งหลายได้ยินว่า ข้าพระองค์ถอนใจอย่างไร หามีผู้ใดปลอบโยนข้าพระองค์ไม่ บรรดาศัตรูของข้าพระองค์ได้ยินถึงเหตุร้ายที่ตกแก่ข้าพระองค์ เขาทั้งหลายก็พากันดีใจที่พระองค์ได้ทรงกระทําอย่างนี้ พระองค์จะทรงนําวาระที่พระองค์ทรงประกาศไว้นั้นให้มาถึง และเขาทั้งหลายจะเป็นอย่างที่ข้าพระองค์เป็นอยู่นี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 22, 'ขอให้บรรดาการชั่วของเขาทั้งหลายมาปรากฏต่อพระพักตร์พระองค์ และขอทรงกระทําแก่เขาทั้งหลาย เหมือนที่พระองค์ได้ทรงกระทําแก่ข้าพระองค์ เพราะการละเมิดทั้งสิ้นของข้าพระองค์เถิด ด้วยความสะท้อนถอนใจของข้าพระองค์นั้นมากมายหลายครั้ง และจิตใจของข้าพระองค์ก็อ่อนเพลียเต็มทีแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 1, 'ด้วยพระพิโรธ องค์พระผู้เป็นเจ้าทรงใช้เมฆบังธิดาของศิโยนหนอ พระองค์ได้ทรงเหวี่ยงสง่าราศีของอิสราเอลให้ตกลงจากฟ้าถึงดิน พระองค์มิได้ทรงระลึกถึงแท่นรองพระบาทของพระองค์เลยในยามที่พระองค์ทรงกริ้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 2, 'องค์พระผู้เป็นเจ้าทรงกลืนที่อยู่ทั้งสิ้นของยาโคบเสียแล้ว และไม่ทรงเมตตา พระองค์ได้ทรงพังป้อมปราการทั้งหลายของธิดาแห่งยูดาห์ให้ลงด้วยพระพิโรธของพระองค์ พระองค์ได้ทรงทลายป้อมปราการเหล่านั้นลงถึงดิน และทรงกระทําให้ราชอาณาจักรและเจ้านายทั้งหลายในนั้นเป็นมลทินไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 3, 'พระองค์ได้ทรงตัดบรรดาเขาแห่งอิสราเอลให้ขาดสิ้นไปด้วยพระพิโรธอันรุนแรงของพระองค์ พระองค์ทรงดึงพระหัตถ์เบื้องขวาของพระองค์กลับมาเสียจากเขาต่อหน้าศัตรู และพระองค์ทรงเผาผลาญคนยาโคบดุจเพลิงลุกโพลงไหม้ไปรอบๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 4, 'พระองค์ทรงโก่งธนูของพระองค์อย่างศัตรู ทรงยกพระหัตถ์เบื้องขวาท่าทีปัจจามิตร และได้ทรงประหารบรรดาคนที่ตาของเราจะอวดได้นั้นเสียในพลับพลาของธิดาแห่งศิโยน พระองค์ได้ทรงระบายพระพิโรธของพระองค์ออกมาดุจเพลิง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 5, 'องค์พระผู้เป็นเจ้าทรงเป็นเหมือนศัตรู พระองค์ได้ทรงกลืนพวกอิสราเอลเสีย พระองค์ได้ทรงกลืนบรรดาวังของเขาหมด และได้ทรงทําลายที่กําบังของเขาให้ ทรงทวีความเศร้าโศกและการคร่ําครวญในธิดาแห่งยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 6, 'พระองค์ได้ทรงพังพลับพลาของพระองค์เสียเหมือนหนึ่งเป็นเพิงในสวน ทรงทําลายสถานที่ประชุมทั้งหลายของพระองค์ พระเยโฮวาห์ได้ทรงกระทําทั้งเทศกาลตามกําหนดและวันสะบาโตให้ลืมเลือนไปในศิโยน ด้วยพระพิโรธอันเดือดดาลพระองค์ทรงดูถูกองค์กษัตริย์และปุโรหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 7, 'องค์พระผู้เป็นเจ้าได้ทรงทิ้งแท่นบูชาของพระองค์เสีย พระองค์ทรงเกลียดสถานบริสุทธิ์ของพระองค์ กําแพงวังทั้งหลายนั้น พระองค์ได้ทรงมอบไว้ในเงื้อมมือศัตรู เขาทั้งหลายได้ส่งเสียงอึกทึกในพระนิเวศแห่งพระเยโฮวาห์เหมือนอย่างในวันเทศกาลตามกําหนด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 8, 'พระเยโฮวาห์ได้ทรงตั้งพระทัยไว้แล้วว่าจะทําลายกําแพงของธิดาแห่งศิโยนเสีย พระองค์ได้ทรงขึงเส้นวัดไว้แล้ว พระองค์มิได้ทรงหดพระหัตถ์เลิกการทําลาย เหตุฉะนี้พระองค์ได้ทรงกระทําให้เนินดินและกําแพงนั้นคร่ําครวญ ให้ทรุดโทรมร่วงโรยไปด้วยกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 9, 'ประตูเมืองศิโยนทั้งสิ้นทรุดลงในดินแล้ว พระองค์ได้ทรงทําลายและทรงหักดาลประตูทั้งปวงเสียสิ้น กษัตริย์และเจ้านายทั้งหลายแห่งศิโยนก็ตกอยู่ท่ามกลางประชาชาติ ไม่มีพระราชบัญญัติอีกต่อไป บรรดาผู้พยากรณ์แห่งเมืองศิโยนหาได้รับนิมิตจากพระเยโฮวาห์อีกไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 10, 'พวกผู้ใหญ่ของธิดาแห่งศิโยนก็กําลังนั่งเงียบอยู่บนพื้นแผ่นดิน เขาทั้งหลายเอาผงคลีดินซัดขึ้นบนศีรษะของตัว และนุ่งห่มผ้ากระสอบ สาวพรหมจารีทั้งหลายแห่งกรุงเยรูซาเล็มคอตกไปถึงดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 11, 'นัยน์ตาของข้าพเจ้าก็ร่วงโรยเพราะร้องไห้ จิตวิญญาณของข้าพเจ้าก็ระทม เพราะความพินาศของธิดาแห่งชนชาติของข้าพเจ้า ตับของข้าพเจ้าเทออกบนพื้นดิน และเพราะเหล่าเด็กเล็กและเด็กที่ยังดูดนมนั้นเป็นลมสลบอยู่ตามถนนในกรุง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 12, 'ลูกทั้งหลายถามแม่ของตัวว่า “แม่จ๋า ข้าวและน้ําองุ่นอยู่ที่ไหน” ขณะเมื่อเขาเป็นลมดุจคนที่ถูกบาดเจ็บตามถนนในกรุง เมื่อชีวิตของเขาต้องเทออกที่อกแม่ของเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 13, 'โอ ธิดาแห่งเยรูซาเล็มเอ๋ย ข้าพเจ้าจะเอาอะไรมาเป็นพยานฝ่ายเจ้าได้ ข้าพเจ้าจะเปรียบเจ้ากับอะไร โอ ธิดาพรหมจารีแห่งศิโยนเอ๋ย ข้าพเจ้าจะหาอะไรที่มาเทียบกับเจ้าได้เล่า เพื่อข้าพเจ้าจะเล้าโลมเจ้าได้ เพราะความอับปางของเจ้าก็ใหญ่เทียมเท่าสมุทร ผู้ใดจะรักษาเจ้าได้เล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 14, 'ผู้พยากรณ์ทั้งหลายของเจ้าได้เห็นสิ่งที่โง่เขลาและไร้สาระมาบอกเจ้า แทนที่เขาจะเผยความชั่วช้าของเจ้าออกมาให้ประจักษ์ เพื่อจะให้เจ้ากลับสู่สภาพดี เขาทั้งหลายกลับได้เห็นภาระที่เทียมเท็จอันเป็นเหตุให้เกิดการเนรเทศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 15, 'บรรดาคนที่ได้ผ่านไปมาก็ตบมือเยาะเย้ยเจ้า เขาทั้งหลายได้เย้ยหยันและได้สั่นศีรษะใส่ธิดาแห่งเยรูซาเล็มแล้วว่า “นี่หรือคือกรุงที่คนทั้งหลายได้ขนานนามว่า งามหมดจด ว่า เป็นความชื่นชมยินดีของคนทั่วทั้งโลก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 16, 'บรรดาศัตรูของเจ้าได้อ้าปากตะโกนโพนทะนาเจ้า เขาทั้งหลายเย้ยหยันและขบเขี้ยวเคี้ยวฟัน เขาพากันร้องว่า “พวกเราได้กลืนเมืองนี้แล้ว วันนี้แหละคือวันที่พวกเราได้จ้องมองหา พวกเราได้พบแล้ว พวกเราเห็นแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 17, 'พระเยโฮวาห์ได้ทรงกระทําตามพระประสงค์แล้ว ได้ทรงกระทําให้พระดํารัสของพระองค์สําเร็จ ตามที่พระองค์ได้บัญชาไว้นานแล้ว พระองค์ก็ได้ทรงทําลายอย่างไม่มีพระเมตตา พระองค์ทรงกระทําให้ศัตรูเปรมปรีดิ์เย้ยเจ้า พระองค์ได้ทรงชูเขาของพวกศัตรูของเจ้าขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 18, 'จิตใจของเขาทั้งหลายร้องทูลองค์พระผู้เป็นเจ้า โอ กําแพงของธิดาแห่งศิโยนเอ๋ย จงให้น้ําตาไหลลงดุจสายน้ําทั้งกลางวันและกลางคืน อย่าให้เจ้าได้หยุดพัก อย่าให้แก้วตาของเจ้าหยุดหย่อนเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 19, 'จงลุกขึ้นร้องไห้ในกลางคืน ในต้นยามจงระบายความในใจของเจ้าออกอย่างน้ําตรงพระพักตร์องค์พระผู้เป็นเจ้า จงชูมือทั้งสองของเจ้าขึ้นตรงไปยังพระองค์เพื่อขอชีวิตของบรรดาลูกเล็กเด็กแดงของเจ้า ที่หิวจนเป็นลมสลบไป ตามหัวถนนหนทางทุกแห่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 20, 'โอ ข้าแต่พระเยโฮวาห์ ขอทอดพระเนตรและพิจารณาเถิดว่า พระองค์ได้ทรงกระทําการเช่นนี้แก่ผู้ใด ควรที่พวกผู้หญิงจะกินลูกของตนหรือ จะกินทารกที่ยังอุ้มอยู่หรือ พวกปุโรหิตและพวกผู้พยากรณ์ควรจะถูกประหารในสถานบริสุทธิ์ขององค์พระผู้เป็นเจ้าหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 21, 'คนหนุ่มและคนแก่นอนเหยียดอยู่ตามพื้นดินในถนน สาวพรหมจารีและชายหนุ่มของข้าพระองค์ถูกคมดาบหวดล้มลงแล้ว พระองค์ได้ทรงประหารเขาในวันเมื่อพระองค์ทรงกริ้ว ได้ทรงสังหารเขาเสียโดยปราศจากพระกรุณา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 22, 'พระองค์ได้ทรงเรียกผู้ที่ข้าพระองค์กลัวรอบทุกด้านมาอย่างในวันเทศกาล พอถึงวันที่พระเยโฮวาห์ทรงพระพิโรธก็ไม่มีสักคนหนึ่งหนีเอาตัวรอดได้ หรือคงเหลือตกค้างรอดตายอยู่ ผู้ที่ข้าพระองค์ได้อุ้มชูและเลี้ยงดูมานั้น ศัตรูของข้าพระองค์ได้เผาผลาญเสียหมดแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 1, 'ข้าพเจ้าเป็นคนที่ได้เห็นความทุกข์ใจ โดยไม้เรียวแห่งพระพิโรธของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 2, 'พระองค์ทรงนําและพาข้าพเจ้ามาในความมืดและไม่ใช่ในความสว่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 3, 'แท้จริงพระองค์ทรงหันมาต่อสู้ข้าพเจ้า พระองค์ทรงพลิกพระหัตถ์ของพระองค์ต่อสู้ข้าพเจ้าอยู่ตลอดวันร่ําไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 4, 'เนื้อและหนังข้าพเจ้าพระองค์ทรงกระทําให้ซูบซีดไป พระองค์ทรงหักกระดูกข้าพเจ้าแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 5, 'พระองค์ทรงสร้างรั้วขังข้าพเจ้า ทรงเอาความขมขื่นและความทุกข์ยากลําบากล้อมข้าพเจ้าไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 6, 'พระองค์ได้ทรงบังคับข้าพเจ้าให้อยู่ในที่มืด ดุจคนที่ตายนานแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 7, 'พระองค์ทรงกระทํารั้วต้นไม้ล้อมข้าพเจ้าไว้เพื่อจะกักไม่ให้ออกไปได้ พระองค์ทรงตีตรวนหนักล่ามข้าพเจ้าไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 8, 'ยิ่งกว่านั้น เมื่อข้าพเจ้าร้องและตะโกน พระองค์มิทรงฟังคําอธิษฐานของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 9, 'พระองค์ทรงล้อมทางทั้งหลายของข้าพเจ้าด้วยก้อนหินที่สกัด พระองค์ทรงกระทําให้หนทางข้าพเจ้าคดเคี้ยวไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 10, 'ทีข้าพเจ้า พระองค์ทรงทําท่าดุจหมีคอยตระครุบ และดั่งสิงโตแอบซุ่มอยู่ในที่ลับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 11, 'พระองค์ทรงหันเหทางของข้าพเจ้าไปเสีย และฉีกข้าพเจ้าเป็นชิ้นๆ พระองค์ทรงกระทําให้ข้าพเจ้าต้องโดดเดี่ยวอ้างว้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 12, 'พระองค์ทรงโก่งธนูของพระองค์และเอาข้าพเจ้าตั้งเป็นเป้าสําหรับลูกธนู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 13, 'พระองค์ทรงเอาลูกธนูในแล่งของพระองค์ ยิงเข้าในหัวใจของข้าพเจ้าแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 14, 'ข้าพเจ้าได้กลายเป็นที่นินทาให้ชนชาติทั้งหลายหัวเราะเยาะ เป็นเนื้อเพลงให้เขาร้องเล่นวันยังค่ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 15, 'พระองค์ทรงให้ข้าพเจ้าบริโภคผักรสขมจนช่ํา พระองค์ทรงให้ข้าพเจ้าเมาไปด้วยบอระเพ็ด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 16, 'พระองค์กระทําให้ฟันข้าพเจ้าหักโดยเคี้ยวก้อนกรวด และทรงปกคลุมข้าพเจ้าด้วยขี้เถ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 17, 'พระองค์กระทําให้จิตวิญญาณของข้าพเจ้าขาดความสงบสุข จนข้าพเจ้าลืมความมั่งคั่งว่าเป็นอะไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 18, 'ข้าพเจ้าจึงว่า “กําลังและความหวังซึ่งข้าพเจ้าได้จากพระเยโฮวาห์ก็ดับหมด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 19, 'ขอทรงจําความทุกข์ใจและความทรมานของข้าพเจ้า อันเป็นบอระเพ็ดและดีหมี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 20, 'จิตวิญญาณของข้าพเจ้ายังนึกถึงเนืองๆ และต้องค้อมลงภายในตัวข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 21, 'ข้าพเจ้าหวนคิดขึ้นมาได้ ข้าพเจ้าจึงมีความหวัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 22, 'เพราะเหตุพระเมตตาของพระเยโฮวาห์เราจึงไม่สูญสิ้นไป เพราะพระเมตตาของพระองค์ไม่มีสิ้นสุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 23, 'เป็นของใหม่อยู่ทุกเวลาเช้า ความสัตย์ซื่อของพระองค์ใหญ่ยิ่งนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 24, 'จิตใจของข้าพเจ้าว่า “พระเยโฮวาห์ทรงเป็นส่วนของข้าพเจ้า เหตุฉะนี้ข้าพเจ้าจะหวังในพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 25, 'พระเยโฮวาห์ทรงดีต่อคนทั้งปวงที่คอยท่าพระองค์อยู่ และทรงดีต่อจิตวิญญาณที่แสวงหาพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 26, 'เป็นการดีที่คนเราจะหวังใจและรอคอยความรอดจากพระเยโฮวาห์ด้วยความสงบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 27, 'เป็นการดีที่คนเราจะแบกแอกในปฐมวัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 28, 'ให้เขานั่งเงียบๆอยู่แต่ลําพัง เพราะพระองค์ทรงวางแอกนั้นเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 29, 'ให้เขาเอาปากจดไว้ในผงคลีดิน ถ้าทําดังนั้นชะรอยจะมีหวัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 30, 'ให้เขาเอียงแก้มให้ผู้ที่ตบเขา ให้เขายอมรับความอับอายอย่างเต็มเปี่ยมเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 31, 'ด้วยว่าองค์พระผู้เป็นเจ้าจะไม่ทรงละทิ้งเป็นนิตย์ดอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 32, 'แม้พระองค์ทรงกระทําให้เกิดความเศร้าโศก พระองค์จะทรงพระกรุณาตามความเมตตาอันล้นเหลือของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 33, 'เพราะพระองค์ทรงกระทําให้ใครเกิดความทุกข์ใจ หรือให้บุตรทั้งหลายของมนุษย์มีความโศกด้วยชอบพระทัยก็หามิได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 34, 'การเหยียบย่ําบรรดาเชลยแห่งแผ่นดินโลกไว้ใต้เท้าก็ดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 35, 'การตัดสิทธิ์ของมนุษย์ผู้หนึ่งผู้ใดต่อพระพักตร์ผู้ใหญ่ยิ่งสูงสุดก็ดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 36, 'การตัดสินกลับสัตย์ในคดีของมนุษย์ก็ดี องค์พระผู้เป็นเจ้าไม่ทรงพอพระทัยเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 37, 'ผู้ใดจะสั่งและให้เป็นไปได้นอกจากเมื่อองค์พระผู้เป็นเจ้าทรงบัญชาให้เป็นไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 38, 'จากพระโอษฐ์ของพระผู้สูงสุดนั้นไม่ใช่มีมาทั้งร้ายและดีหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 39, 'มนุษย์เป็นๆจะไปบ่นเอากับใคร คือมนุษย์ที่ถูกทําโทษเพราะบาปของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 40, 'ให้พวกเราทดสอบและพิจารณาวิถีของพวกเรา และกลับมาหาพระเยโฮวาห์เถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 41, 'ให้พวกเรายกจิตใจและมือของพวกเราขึ้นต่อพระเจ้าในฟ้าสวรรค์ทูลว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 42, '“พวกข้าพระองค์ได้ทรยศและได้กบฏแล้ว และพระองค์ยังไม่ได้ทรงอภัยโทษ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 43, 'พระองค์ทรงห่มความกริ้วและข่มเหงพวกข้าพระองค์ ได้ทรงประหารอย่างไม่สงสาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 44, 'พระองค์ทรงคลุมพระองค์ไว้เสียด้วยเมฆ เพื่อว่าการอธิษฐานของพวกข้าพระองค์จะไม่ทะลุไปถึงพระองค์ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 45, 'พระองค์ได้ทรงกระทําให้พวกข้าพระองค์เป็นเหมือนหยากเยื่อและมูลฝอยอยู่ในท่ามกลางชนชาติทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 46, 'บรรดาศัตรูของพวกข้าพระองค์ได้อ้าปากตะโกนโพนทะนาว่าพวกข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 47, 'ความหวาดและกับดักมาถึงข้าพระองค์ทั้งหลาย ทั้งการรกร้างว่างเปล่าและความพินาศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 48, 'น้ําตาของข้าพระองค์ไหลเป็นแม่น้ําเนื่องด้วยความพินาศแห่งธิดาของชนชาติของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 49, 'น้ําตาของข้าพระองค์ไหลลงไม่หยุดและไม่มีเวลาสร่างเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 50, 'กว่าพระเยโฮวาห์จะทอดพระเนตรลงแลดูจากสวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 51, 'นัยน์ตาของข้าพระองค์ทําให้ใจข้าพระองค์ระทมเพราะเหตุบรรดาบุตรสาวแห่งกรุงข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 52, 'พวกที่ตั้งตนเป็นศัตรูต่อข้าพระองค์โดยไม่มีเหตุนั้นได้ขับไล่ข้าพระองค์ดังขับไล่นก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 53, 'เขาทั้งหลายจะตัดชีวิตของข้าพระองค์เสียในคุกใต้ดิน และเอาหินก้อนหนึ่งทุ่มใส่ข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 54, 'น้ําได้ท่วมศีรษะของข้าพระองค์ ข้าพระองค์ว่า ‘ข้าพเจ้าถูกผลาญแน่แล้ว’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 55, 'โอ ข้าแต่พระเยโฮวาห์ ข้าพระองค์ได้ร้องออกพระนามของพระองค์จากที่ลึกในคุกใต้ดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 56, 'พระองค์ทรงสดับเสียงข้าพระองค์ที่ว่า ‘ขออย่าทรงจุกพระกรรณต่อลมหายใจและการร้องทูลของข้าพระองค์’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 57, 'พระองค์ทรงเข้ามาใกล้ในวันที่ข้าพระองค์ร้องทูลพระองค์ พระองค์ตรัสว่า ‘ไม่ต้องกลัว’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 58, 'โอ ข้าแต่องค์พระผู้เป็นเจ้า พระองค์ได้ทรงเข้ากับคดีของจิตใจข้าพระองค์แล้ว พระองค์ทรงไถ่ชีวิตข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 59, 'โอ ข้าแต่พระเยโฮวาห์ พระองค์ทรงเห็นที่เขาผิดต่อข้าพระองค์แล้ว ขอทรงพิพากษาคดีของข้าพระองค์เถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 60, 'พระองค์ได้ทรงเห็นการแก้แค้นทั้งสิ้นของเขา และบรรดาแผนการทําร้ายข้าพระองค์แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 61, 'โอ ข้าแต่พระเยโฮวาห์ พระองค์ทรงได้ยินคําเยาะเย้ย และบรรดาแผนการทําร้ายข้าพระองค์แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 62, 'คือริมฝีปากและความคิดของผู้ที่ได้รุกรานข้าพระองค์ ก็ต่อสู้ข้าพระองค์อยู่วันยังค่ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 63, 'ดูเถิด ไม่ว่าเขาจะนั่งหรือลุก ตัวข้าพระองค์ก็เป็นเนื้อเพลงให้เขาร้องเล่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 64, 'โอ ข้าแต่พระเยโฮวาห์ ขอพระองค์ทรงสนองเขาทั้งหลายตามการกระทําแห่งน้ํามือของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 65, 'ขอพระองค์ทรงกระทําให้ใจของเขาทั้งปวงโศกเศร้า ขอให้คําสาปของพระองค์ตกเหนือเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 66, 'ขอพระองค์ทรงรังควานและทําลายเขาเสียด้วยพระพิโรธจากใต้ฟ้าสวรรค์ของพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 1, 'นี่อย่างไรหนอ ทองคําจึงมีสีสลัวและทองคําเนื้อดีก็เปลี่ยนไป เพชรพลอยแห่งสถานบริสุทธิ์ทิ้งอยู่เกลื่อนกลาดตามทุกหัวถนน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 2, 'บุตรชายผู้ประเสริฐของกรุงศิโยนมีค่าเปรียบได้กับทองคําเนื้อดีนั้น ถูกตีราคาเพียงเท่าหม้อดินที่ปั้นขึ้นด้วยมือของช่างหม้อเท่านั้นหนอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 3, 'แม้แต่สัตว์ประหลาดทะเลยังได้เอานมออกให้ลูกของมันดูด แต่ธิดาแห่งชนชาติของข้าพเจ้าก็ใจร้าย ดุจนกกระจอกเทศในถิ่นทุรกันดาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 4, 'ลิ้นของทารกที่ยังไม่หย่านมกระหายจนติดเพดาน พวกเด็กได้ขออาหาร แต่ไม่มีใครยื่นให้เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 5, 'คนทั้งปวงที่เคยรับประทานอาหารอย่างเลิศหรูกลับต้องโดดเดี่ยวอยู่ตามถนน คนทั้งหลายที่เติบโตมาด้วยเสื้อสีแดงสดกลับต้องกอดกองขยะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 6, 'เพราะโทษความชั่วช้าของธิดาแห่งชนชาติข้าพเจ้านั้นก็ใหญ่โตกว่าโทษบาปของเมืองโสโดมที่ต้องคว่ําทลายลงในพริบตาเดียว โดยไม่มีมือใครได้แตะต้องเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 7, 'พวกนาศีร์ของเธอบริสุทธิ์กว่าหิมะและขาวกว่าน้ํานม ผิวพรรณของเขาเปล่งปลั่งยิ่งกว่ามุกดา เขามีรูปร่างงามดั่งไพทูรย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 8, 'บัดนี้ผิวพรรณของเขาก็ดํายิ่งกว่าถ่านหิน ใครๆตามถนนก็จําเขาไม่ได้ หนังของเขาเหี่ยวหุ้มกระดูกและซูบราวกับไม้เสียบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 9, 'คนที่ตายด้วยคมดาบยังดีกว่าคนที่ต้องอดอยากตาย เพราะคนเหล่านี้ค่อยผอมค่อยตายไป ถูกแทงทะลุเพราะขาดผลจากท้องนา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 10, 'มือของหญิงที่ใจอ่อนกลับเอาลูกของตัวต้มกิน ลูกที่ถูกต้มเป็นอาหารนั้นกินกันเมื่อยามหายนะมาสู่ธิดาแห่งชนชาติของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 11, 'พระเยโฮวาห์ทรงบันดาลโทโสออกมาแล้ว พระองค์ทรงเทพระพิโรธอันเกรี้ยวกราดของพระองค์ลงแล้ว และได้ทรงจุดไฟขึ้นในกรุงศิโยน ซึ่งเผาผลาญรากของเมืองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 12, 'กษัตริย์ทั้งปวงแห่งแผ่นดินโลก และบรรดาชาวพิภพพากันไม่เชื่อว่าคู่อริหรือศัตรูจะได้เข้าไปในประตูกรุงเยรูซาเล็มได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 13, 'เพราะความผิดบาปของพวกผู้พยากรณ์ของกรุงศิโยน และเพราะความชั่วช้าของพวกปุโรหิตของกรุงนั้น ที่ได้กระทําโลหิตของคนชอบธรรมให้ไหลออกในท่ามกลางกรุง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 14, 'เขาทั้งหลายเดินเปะปะและตาบอดไปตามถนน ทําตัวให้มลทินด้วยโลหิต จนคนจะจับต้องไม่ได้ที่เสื้อผ้าของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 15, 'คนทั้งหลายร้องบอกเขาว่า “ไปซิ มลทินจริง ไปเถอะ ไป๊ อย่ามาถูกต้องนะ” เมื่อเขาเหล่านั้นหนีไป เป็นคนพเนจร พลเมืองของประชาชาติพูดกันว่า “เขาต้องไม่อยู่ที่นี่อีกต่อไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 16, 'พระพิโรธของพระเยโฮวาห์ทรงกระทําให้เขาทั้งปวงกระจัดกระจายไป พระองค์จะไม่ทรงสนพระทัยในเขาอีกเลย คนทั้งหลายจึงไม่นับถือพวกปุโรหิต ไม่ทําคุณต่อพวกผู้ใหญ่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 17, 'นัยน์ตาของพวกเรามองหาความช่วยเหลือ การช่วยเหลือนั้นไร้ประโยชน์ ส่วนการเฝ้ารอคอย พวกเราได้คอยประเทศที่ไม่อาจจะช่วยเราให้รอดได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 18, 'มีคนสะกดรอยตามเรา จนพวกเราเดินตามถนนของพวกเราไม่ได้ เบื้องปลายของพวกเราก็ใกล้เข้ามาแล้ว วันเดือนทั้งหลายของพวกเราก็จะจบอยู่ เพราะบั้นปลายของพวกเรามาถึง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 19, 'พวกที่ข่มเหงเราก็เร็วกว่านกอินทรีในท้องฟ้า เขาทั้งหลายวิ่งไล่กวดพวกเราบนภูเขา เขาทั้งหลายซุ่มคอยจับเราในถิ่นทุรกันดาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 20, 'ลมปราณทางจมูกของพวกข้าพเจ้า คือผู้ที่พระเยโฮวาห์ทรงเจิมไว้นั้น ก็ตกหลุมพรางของเขาทั้งหลายแล้ว คือพวกเรากล่าวถึงพระองค์ท่านว่า “เราจะดํารงชีวิตของเราท่ามกลางประชาชาติได้ ก็ด้วยอาศัยร่มเงาของพระองค์ท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 21, 'โอ ธิดาแห่งเมืองเอโดม ที่อาศัยอยู่ในแผ่นดินอูส จงเปรมปรีดิ์และยินดีเถิด ถ้วยนั้นจะผ่านมาถึงเจ้าด้วย เจ้าจะต้องเมามาย และจะกระทําให้ตัวเองเปลือยเปล่าไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 22, 'โอ ธิดาแห่งกรุงศิโยนเอ๋ย การลงโทษเพราะความชั่วช้าของเจ้าก็ครบแล้ว พระองค์จะไม่ทรงพาเจ้าออกไปให้เป็นเชลยอีกต่อไป โอ ธิดาแห่งเมืองเอโดมเอ๋ย พระองค์จะทรงลงโทษเพราะความชั่วช้าของเจ้า พระองค์จะทรงเผยบาปของเจ้าให้ประจักษ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 1, 'โอ ข้าแต่พระเยโฮวาห์ ขอทรงระลึกว่ามีอะไรตกถึงข้าพระองค์ ขอทรงพิจารณาและทอดพระเนตรความอดสูของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 2, 'มรดกของพวกข้าพระองค์ได้ไปตกอยู่กับพวกต่างประเทศ บ้านเรือนของพวกข้าพระองค์เป็นของคนต่างด้าว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 3, 'พวกข้าพระองค์เป็นคนกําพร้าและคนกําพร้าพ่อ และเหล่ามารดาของข้าพระองค์เป็นดั่งหญิงม่าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 4, 'น้ําก็ต้องซื้อเขาดื่ม ฟืนก็ต้องซื้อเขาใช้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 5, 'ผู้ข่มขี่ได้ขี่คอพวกข้าพระองค์ไว้ พวกข้าพระองค์ทํางานหนักและไม่มีเวลาพักเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 6, 'พวกข้าพระองค์พนมมือให้คนอียิปต์และคนอัสซีเรีย เพื่อจะได้อาหารรับประทานอิ่มหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 7, 'บรรพบุรุษของพวกข้าพระองค์ได้กระทําบาป และก็ตายหมดแล้ว พวกข้าพระองค์ต้องถูกโทษเพราะความชั่วช้าของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 8, 'ทาสกลับปกครองพวกข้าพระองค์ ไม่มีผู้ใดช่วยข้าพระองค์ให้พ้นมือของเขาได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 9, 'ข้าพระองค์ทั้งหลายได้อาหารมาโดยเอาชีวิตเข้าเสี่ยงเพราะดาบแห่งถิ่นทุรกันดาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 10, 'ผิวหนังของพวกข้าพระองค์ก็ร้อนปานเตาอบ เพราะความเดือดร้อนของทุพภิกขภัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 11, 'เขาทั้งหลายขืนใจพวกผู้หญิงในกรุงศิโยน และข่มใจสาวพรหมจารีในหัวเมืองแห่งยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 12, 'พวกเจ้านายต้องถูกผูกมือแขวน ไม่มีใครแสดงความนับถือต่อหน้าพวกผู้ใหญ่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 13, 'พวกคนหนุ่มถูกบังคับให้โม่แป้ง และพวกเด็กต้องแบกฟืนหนักล้มลุกคลุกคลาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 14, 'พวกผู้ใหญ่หายตัวไปจากประตูเมือง พวกคนหนุ่มได้หยุดดีดสีตีเป่าแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 15, 'ความปลาบปลื้มก็ประลาตไปจากใจของพวกข้าพระองค์สิ้น การเต้นรําของพวกข้าพระองค์กลายเป็นการร่ําไห้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 16, 'มงกุฎได้ร่วงหล่นจากศีรษะข้าพระองค์แล้ว วิบัติแก่พวกข้าพระองค์ เพราะพวกข้าพระองค์กระทําบาปไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 17, 'เหตุนี้เองใจพวกข้าพระองค์จึงอ่อนกําลัง เพราะการเหล่านี้เองนัยน์ตาข้าพระองค์จึงมัวไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 18, 'เหตุด้วยภูเขาศิโยนซึ่งรกร้างไป พวกสุนัขจิ้งจอกจึงมาเดินเพ่นพ่านอยู่บนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 19, 'โอ ข้าแต่พระเยโฮวาห์ แต่พระองค์ทรงสถิตอยู่เป็นนิตย์ พระที่นั่งของพระองค์ดํารงอยู่ทุกชั่วอายุ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 20, 'เป็นไฉนพระองค์ทรงลืมพวกข้าพระองค์เสียเป็นนิตย์ เป็นไฉนได้ทรงทอดทิ้งพวกข้าพระองค์เสียนานดังนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 21, 'โอ ข้าแต่พระเยโฮวาห์ ขอทรงช่วยข้าพระองค์ให้กลับสู่พระองค์เถิด แล้วพวกข้าพระองค์จะกลับสู่พระองค์ ขอทรงฟื้นเดือนปีของข้าพระองค์ให้เหมือนดังก่อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 22, 'เว้นเสียแต่พระองค์ทรงสลัดทิ้งพวกข้าพระองค์เสียแล้ว และพระองค์ทรงกริ้วพวกข้าพระองค์อย่างล้นพ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 1, 'อยู่มา ในวันที่ห้าเดือนที่สี่ปีที่สามสิบ ขณะเมื่อข้าพเจ้าอยู่ที่ริมแม่น้ําเคบาร์ในหมู่พวกเชลย ท้องฟ้าเบิกออก และข้าพเจ้าได้เห็นนิมิตจากพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 2, 'เมื่อวันที่ห้าเดือนนั้น คือในปีที่ห้าที่กษัตริย์เยโฮยาคีนต้องเป็นเชลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 3, 'พระวจนะของพระเยโฮวาห์มายังเอเสเคียลปุโรหิต บุตรชายบุซีในแผ่นดินของคนเคลเดียริมแม่น้ําเคบาร์ ณ ที่นั่นพระหัตถ์ของพระเยโฮวาห์มาอยู่เหนือท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 4, 'ดูเถิด เมื่อข้าพเจ้ามองดู ลมหมุนก็พัดมาจากทางเหนือ มีเมฆก้อนใหญ่ที่มีความสว่างอยู่รอบ และมีไฟลุกวาบออกมาอยู่เสมอ ท่ามกลางไฟนั้นดูประดุจสีเหลืองอําพัน ซึ่งออกมาจากท่ามกลางไฟนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 5, 'และจากท่ามกลางไฟนี้มีร่างดังสิ่งที่มีชีวิตอยู่สี่ตัวออกมา รูปร่างของสิ่งที่มีชีวิตอยู่นั้นเป็นเช่นนี้ คือมีสัณฐานเหมือนมนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 6, 'แต่สิ่งที่มีชีวิตอยู่ทุกตัวมีหน้าสี่หน้า และมีปีกสี่ปีกทุกตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 7, 'เท้าของสิ่งที่มีชีวิตอยู่นั้นตรง และฝ่าเท้าก็เหมือนฝ่าตีนลูกวัว และเป็นประกายอย่างสีของทองเหลืองขัด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 8, 'ที่ใต้ปีกข้างตัวทั้งสี่ข้างมีเป็นมือคน สิ่งที่มีชีวิตอยู่ทั้งสี่มีหน้าและมีปีกดังนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 9, 'คือปีกของมันต่างก็จดปีกของกันและกัน มันบินตรงไปข้างหน้า ขณะที่ไปก็ไม่หันเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 10, 'สัณฐานหน้าของสิ่งที่มีชีวิตอยู่ทั้งสี่มีหน้าเหมือนหน้าคน ทั้งสี่มีหน้าสิงโตอยู่ด้านขวา ทั้งสี่มีหน้าวัวอยู่ด้านซ้าย ทั้งสี่มีหน้านกอินทรีด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 11, 'หน้าของมันเป็นดังนี้แหละ ปีกของมันกางแผ่ขึ้นข้างบน ปีกสองปีกของแต่ละตัวจดปีกของกันและกัน ส่วนอีกสองปีกคลุมกายของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 12, 'สิ่งที่มีชีวิตอยู่ทุกตัวบินตรงไปข้างหน้า ไม่ว่าวิญญาณจะไปทางไหน มันก็ไปทางนั้น เมื่อไปก็ไม่หันเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 13, 'สัณฐานของสิ่งที่มีชีวิตอยู่นั้น มีสิ่งหนึ่งที่ดูเหมือนถ่านคุเหมือนคบเพลิงหลายอัน เคลื่อนไปมาอยู่ในหมู่สิ่งที่มีชีวิตอยู่เหล่านั้น ไฟนั้นสุกใสและมีแสงฟ้าแลบออกมาจากไฟนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 14, 'สิ่งที่มีชีวิตอยู่ก็พุ่งไปพุ่งมาดั่งฟ้าแลบแปลบปลาบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 15, 'ขณะเมื่อข้าพเจ้ามองดูสิ่งที่มีชีวิตอยู่นั้น ดูเถิด วงล้ออันหนึ่งอยู่บนพิภพข้างสิ่งที่มีชีวิตอยู่ที่มีหน้าสี่หน้านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 16, 'ลักษณะและทรวดทรงของวงล้อเหล่านั้นแวบวาบอย่างพลอยเขียว วงล้อทั้งสี่ก็มีสัณฐานเหมือนกัน ส่วนลักษณะและทรวดทรงนั้นเหมือนวงล้อซ้อนในวงล้อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 17, 'เมื่อจะไปก็ไปข้างใดในสี่ข้างของมันได้ เมื่อไปก็ไม่หันเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 18, 'ขอบวงล้อนั้นสูงและน่าสะพรึงกลัว และทั้งสี่นั้นที่ขอบมีนัยน์ตาเต็มอยู่รอบๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 19, 'เมื่อสิ่งที่มีชีวิตอยู่นั้นไป วงล้อก็ตามไปข้างๆด้วย เมื่อสิ่งที่มีชีวิตอยู่เหาะขึ้นจากพิภพ วงล้อก็เหาะขึ้นด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 20, 'วิญญาณจะไปที่ไหน สิ่งที่มีชีวิตอยู่นั้นก็ไป คือวิญญาณของมันไปที่นั่น และวงล้อนั้นก็เหาะตามไปด้วย เพราะว่าวิญญาณของสิ่งที่มีชีวิตอยู่ได้อยู่ในวงล้อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 21, 'เมื่อสิ่งที่มีชีวิตอยู่ไป วงล้อก็ไปด้วย เมื่อสิ่งที่มีชีวิตอยู่หยุด วงล้อก็หยุด เมื่อสิ่งที่มีชีวิตอยู่เหาะขึ้นจากพิภพ วงล้อก็เหาะตามไปด้วย เพราะว่าวิญญาณของสิ่งที่มีชีวิตอยู่ได้อยู่ในวงล้อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 22, 'เหนือศีรษะของสิ่งที่มีชีวิตอยู่นั้นมีลักษณะเหมือนท้องฟ้า ทอแสงอย่างแก้วผลึกที่น่ากลัว แผ่กว้างอยู่เหนือศีรษะของสิ่งที่มีชีวิตอยู่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 23, 'ใต้ท้องฟ้านี้ปีกกางออกตรง กางออกไปหากัน สิ่งที่มีชีวิตอยู่ทุกตัวมีปีกคลุมกายข้างนี้สองปีก และมีปีกคลุมกายข้างนั้นสองปีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 24, 'และเมื่อสิ่งที่มีชีวิตอยู่เหล่านี้ไป ข้าพเจ้าได้ยินเสียงของปีกเหมือนเสียงของน้ํามากหลาย ดังพระสุรเสียงขององค์ผู้ทรงมหิทธิฤทธิ์ เสียงโกลาหล เหมือนเสียงพลโยธา เมื่อสิ่งที่มีชีวิตอยู่เหล่านั้นหยุดนิ่งก็หุบปีกลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 25, 'และมีเสียงมาจากท้องฟ้าเหนือศีรษะของมัน เมื่อสิ่งที่มีชีวิตอยู่เหล่านั้นหยุดนิ่งก็หุบปีกลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 26, 'และเหนือท้องฟ้าที่อยู่เหนือศีรษะของสิ่งที่มีชีวิตอยู่นั้นมีสิ่งคล้ายบัลลังก์มีลักษณะเหมือนไพทูรย์ และบนสิ่งที่เหมือนบัลลังก์นั้นก็มีลักษณะเหมือนมนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 27, 'และข้าพเจ้าเห็นประดุจสีเหลืองอําพัน เหมือนไฟที่บังไว้อยู่รอบข้าง เหนือสิ่งที่เหมือนบั้นเอวของผู้นั้นขึ้นไป และจากสิ่งที่เหมือนบั้นเอวลงมา ข้าพเจ้าเห็นเหมือนไฟ และมีความสุกใสที่อยู่รอบท่านผู้นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 28, 'ลักษณะความสุกใสที่อยู่รอบนั้นเหมือนกับสัณฐานของรุ้งที่ปรากฏในเมฆในวันที่ฝนตก ลักษณะทรวดทรงแห่งสง่าราศีของพระเยโฮวาห์เป็นดังนี้แหละ และเมื่อข้าพเจ้าเห็นแล้ว ข้าพเจ้าก็ซบหน้าลงถึงดิน และข้าพเจ้าได้ยินเสียงท่านผู้หนึ่งตรัส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 1, 'พระองค์ตรัสกับข้าพเจ้าว่า “บุตรแห่งมนุษย์เอ๋ย ยืนขึ้น เราจะพูดกับเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 2, 'และเมื่อพระองค์ตรัสกับข้าพเจ้าพระวิญญาณได้เข้าไปในข้าพเจ้าและตั้งข้าพเจ้าให้ยืนขึ้น และข้าพเจ้าได้ยินพระองค์นั้นผู้ตรัสกับข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 3, 'และพระองค์ตรัสสั่งข้าพเจ้าว่า “บุตรแห่งมนุษย์เอ๋ย เราส่งเจ้าไปยังคนอิสราเอล ถึงประชาชาติที่มักกบฏ ผู้ซึ่งได้กบฏต่อเรา ทั้งตัวเขาและบรรพบุรุษของเขาได้ละเมิดต่อเราจนกระทั่งวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 4, 'ประชาชนก็หน้าด้านและดื้อดึงด้วย เราใช้เจ้าไปหาเขา และเจ้าจะพูดกับเขาว่า ‘องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 5, 'เขาจะฟังหรือปฏิเสธไม่ฟังก็ตาม (เพราะว่าเขาเป็นวงศ์วานที่มักกบฏ) เขาก็จะทราบว่า ได้มีผู้พยากรณ์คนหนึ่งในหมู่พวกเขาแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 6, 'เจ้า บุตรแห่งมนุษย์เอ๋ย เจ้าอย่ากลัวเขา หรืออย่าเกรงคําพูดของเขา ถึงแม้ว่าหนามย่อยหนามใหญ่อยู่กับเจ้า และเจ้าอยู่ท่ามกลางแมงป่อง อย่าเกรงคําพูดของเขาเลย อย่าท้อถอยเมื่อเห็นหน้าเขา เพราะเขาเป็นวงศ์วานที่มักกบฏ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 7, 'และเจ้าจะกล่าวถ้อยคําของเราให้เขาฟัง เขาจะฟังหรือปฏิเสธไม่ฟังก็ตามเถอะ เพราะเขาเป็นผู้ที่มักกบฏ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 8, 'บุตรแห่งมนุษย์เอ๋ย ฝ่ายเจ้าจงฟังสิ่งที่เรากล่าวแก่เจ้า อย่าเป็นคนมักกบฏอย่างวงศ์วานที่มักกบฏนั้น จงอ้าปากขึ้นและกินสิ่งที่เราให้เจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 9, 'ดูเถิด เมื่อข้าพเจ้ามองดูก็เห็นพระหัตถ์ข้างหนึ่งเหยียดออกมายังข้าพเจ้า และดูเถิด ในพระหัตถ์นั้นมีหนังสืออยู่ม้วนหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 10, 'พระองค์ทรงคลี่หนังสือม้วนนั้นออกต่อหน้าข้าพเจ้า และมีตัวหนังสือเขียนอยู่ทั้งด้านหน้าและด้านหลัง มีบทคร่ําครวญ คําไว้ทุกข์และคําวิบัติเขียนอยู่บนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 1, 'พระองค์ตรัสกับข้าพเจ้าอีกว่า “บุตรแห่งมนุษย์เอ๋ย จงรับประทานสิ่งที่เจ้าได้พบ จงรับประทานหนังสือม้วนนี้ และจงไปพูดกับวงศ์วานอิสราเอล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 2, 'ข้าพเจ้าจึงอ้าปาก และพระองค์ทรงให้ข้าพเจ้ารับประทานหนังสือม้วนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 3, 'และพระองค์ตรัสกับข้าพเจ้าว่า “บุตรแห่งมนุษย์เอ๋ย จงรับประทานหนังสือม้วนนี้ซึ่งเราได้ให้แก่เจ้า และบรรจุให้เต็มท้องของเจ้า” แล้วข้าพเจ้าก็ได้รับประทาน และเมื่อหนังสือม้วนนั้นอยู่ในปากของข้าพเจ้าก็หวานเหมือนน้ําผึ้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 4, 'และพระองค์ตรัสกับข้าพเจ้าว่า “บุตรแห่งมนุษย์เอ๋ย เจ้าจงไปยังวงศ์วานอิสราเอลและกล่าวถ้อยคําของเราแก่เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 5, 'เพราะเรามิได้ใช้เจ้าไปหาชนชาติที่พูดภาษาต่างด้าวและภาษาที่พูดยาก แต่ให้ไปหาวงศ์วานอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 6, 'มิใช่ให้ไปหาชนชาติทั้งหลายเป็นอันมากที่พูดภาษาต่างด้าวและภาษาที่พูดยาก เป็นคําที่เจ้าจะเข้าใจไม่ได้ ที่จริงถ้าเราใช้เจ้าไปหาคนเช่นนั้น เขาทั้งหลายจะฟังเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 7, 'แต่วงศ์วานอิสราเอลจะไม่ยอมฟังเจ้า เพราะเขาไม่ยอมฟังเรา เพราะว่าวงศ์วานอิสราเอลทั้งสิ้นเป็นคนหัวแข็งและจิตใจดื้อดึง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 8, 'ดูเถิด เราได้กระทําให้หน้าของเจ้าขมึงทึงต่อหน้าของเขา และให้หน้าผากของเจ้าขึงขังต่อหน้าผากของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 9, 'เราได้กระทําให้หน้าผากของเจ้าแข็งขันอย่างเพชรที่แข็งกว่าหินเหล็กไฟ อย่ากลัวเขาเลย อย่าท้อถอยเมื่อเห็นหน้าเขา เพราะเขาเป็นวงศ์วานที่มักกบฏ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 10, 'พระองค์ตรัสกับข้าพเจ้าอีกว่า “บุตรแห่งมนุษย์เอ๋ย จงรับถ้อยคําทั้งสิ้นของเราที่พูดกับเจ้าไว้ในใจของเจ้า และจงฟังไว้ด้วยหูของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 11, 'ไปเถอะ เจ้าจงไปหาพวกที่เป็นเชลย คือชนชาติของเจ้านั้น จงพูดกับเขา และกล่าวแก่เขาว่า ‘องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า’ ถึงเขาจะฟังหรือปฏิเสธไม่ฟังก็ช่างเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 12, 'พระวิญญาณจึงยกข้าพเจ้าขึ้น และข้าพเจ้าก็ได้ยินเสียงกระหึ่มอยู่ข้างหลังข้าพเจ้าว่า “จงสรรเสริญแด่สง่าราศีของพระเยโฮวาห์ซึ่งขึ้นมาจากสถานที่ของพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 13, 'และข้าพเจ้าได้ยินเสียงปีกสิ่งที่มีชีวิตอยู่ที่ถูกต้องกัน และเสียงวงล้อข้างๆสิ่งที่มีชีวิตอยู่นั้น เป็นเสียงกระหึ่ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 14, 'พระวิญญาณก็ยกข้าพเจ้าขึ้นและพาข้าพเจ้าไป ข้าพเจ้าก็ไปด้วยความขมขื่น ใจข้าพเจ้าเดือดร้อน พระหัตถ์ของพระเยโฮวาห์ก็หนักอยู่บนข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 15, 'ข้าพเจ้าจึงมาถึงพวกที่เป็นเชลยที่เทลอาบิบ ผู้ที่อาศัยอยู่ที่ริมแม่น้ําเคบาร์ และที่ที่เขานั่งอยู่ข้าพเจ้าก็นั่งอยู่ และยังคงอยู่อย่างมึนซึมท่ามกลางเขาเจ็ดวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 16, 'ต่อมาพอสิ้นเจ็ดวัน พระวจนะแห่งพระเยโฮวาห์ก็มาถึงข้าพเจ้าว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 17, '“บุตรแห่งมนุษย์เอ๋ย เราได้กระทําให้เจ้าเป็นยามเฝ้าวงศ์วานอิสราเอล เจ้าได้ยินถ้อยคําจากปากของเราเมื่อไร เจ้าจงกล่าวคําตักเตือนเขาจากเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 18, 'ถ้าเราจะบอกแก่คนชั่วว่า ‘เจ้าจะต้องตายแน่ๆ’ และเจ้าไม่ตักเตือนเขาหรือกล่าวเตือนคนชั่วให้ละทิ้งทางชั่วของตนเสีย เพื่อจะช่วยชีวิตเขาให้รอด คนชั่วนั้นจะตายเพราะความชั่วช้าของเขา แต่เราจะเรียกร้องโลหิตของเขาจากมือของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 19, 'แต่ถ้าเจ้าได้ตักเตือนคนชั่วและเขามิได้หันกลับจากความชั่วของเขา หรือจากทางชั่วของเขา เขาจะตายเพราะความชั่วช้าของเขา แต่เจ้าจะได้ช่วยชีวิตของเจ้าให้รอดพ้นมาได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 20, 'อีกประการหนึ่ง ถ้าคนชอบธรรมหันกลับจากความชอบธรรมของเขา และได้กระทําความชั่วช้า และเราวางสิ่งที่สะดุดไว้ตรงหน้าเขา เขาจะต้องตาย เพราะว่าเจ้ามิได้ตักเตือนเขา เขาจะตายเพราะบาปของเขา และจะไม่มีใครจดจําการกระทําอันชอบธรรมของเขาไว้เลย แต่เราจะเรียกร้องโลหิตของเขาจากมือของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 21, 'แต่ถ้าเจ้าได้ตักเตือนคนชอบธรรมไม่ให้กระทําบาปและเขามิได้กระทําบาป เขาจะมีชีวิตอยู่ได้แน่ เพราะเขารับคําตักเตือน และเจ้าก็ได้ช่วยชีวิตของเจ้าให้รอดพ้นมาได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 22, 'ณ ที่นั่นพระหัตถ์แห่งพระเยโฮวาห์ได้มาอยู่เหนือข้าพเจ้า และพระองค์ตรัสกับข้าพเจ้าว่า “จงลุกขึ้นออกไปยังที่ราบ และเราจะพูดกับเจ้าที่นั่น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 23, 'ดังนั้นข้าพเจ้าจึงลุกขึ้นออกไปยังที่ราบ และดูเถิด สง่าราศีของพระเยโฮวาห์ก็อยู่ที่นั่นอย่างเดียวกับสง่าราศีซึ่งข้าพเจ้าได้เห็นที่ริมแม่น้ําเคบาร์ และข้าพเจ้าก็ซบหน้าลงถึงดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 24, 'แต่พระวิญญาณได้เสด็จเข้าในข้าพเจ้ากระทําให้ข้าพเจ้ายืนขึ้น และพระองค์ตรัสกับข้าพเจ้า และทรงบอกข้าพเจ้าว่า “จงไป ขังตัวเจ้าไว้ภายในเรือนของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 25, 'เจ้า โอ บุตรแห่งมนุษย์เอ๋ย ดูเถิด เขาจะเอาเชือกพันเจ้า และผูกมัดเจ้าไว้ด้วยเชือกนั้น เจ้าจึงออกไปท่ามกลางเขาไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 26, 'และเราจะกระทําให้ลิ้นของเจ้าติดกับเพดานปากของเจ้า ดังนั้นเจ้าจะเป็นใบ้ ไม่สามารถว่ากล่าวเขาได้ เพราะว่าเขาทั้งหลายเป็นวงศ์วานที่มักกบฏ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 27, 'แต่เมื่อเราพูดกับเจ้า เราจะให้เจ้าหายใบ้ และเจ้าจะกล่าวแก่เขาทั้งหลายว่า ‘องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า’ ผู้ที่จะฟังก็ให้เขาได้ฟัง และผู้ที่จะปฏิเสธไม่ฟังก็ให้เขาปฏิเสธ เพราะเขาทั้งหลายเป็นวงศ์วานที่มักกบฏ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 1, '“เจ้า บุตรแห่งมนุษย์เอ๋ย เจ้าจงเอาก้อนอิฐมาวางไว้ข้างหน้าเจ้า และแกะรูปเมืองหนึ่งไว้บนนั้นคือนครเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 2, 'จงล้อมนครนั้นไว้และก่อกําแพงล้อมไว้รอบนครนั้นด้วย และก่อเชิงเทินไว้สู้นครนั้นและตั้งค่ายรอบนครไว้ และตั้งเครื่องทะลวงกําแพงไว้รอบนคร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 3, 'จงหากระทะเหล็กมา และวางกระทะเหล็กนั้นต่างเป็นกําแพงเหล็กระหว่างเจ้ากับนครนั้น และเจ้าจงหันหน้าสู่นครนั้น ให้นครนั้นถูกล้อม แล้วเจ้าจงกระชับการล้อมเข้าไป นี่เป็นหมายสําคัญสําหรับวงศ์วานอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 4, 'แล้วเจ้าจงนอนตะแคงข้างซ้ายและเราจะวางความชั่วช้าแห่งวงศ์วานอิสราเอลไว้เหนือเจ้า เจ้านอนทับอยู่กี่วัน เจ้าจะแบกความชั่วช้าของนครนั้นเท่านั้นวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 5, 'เพราะเราได้กําหนดวันให้แก่เจ้าแล้ว คือสามร้อยเก้าสิบวันเท่ากับจํานวนปีแห่งความชั่วช้าของเขา เจ้าจะต้องแบกความชั่วช้าของวงศ์วานอิสราเอลนานเท่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 6, 'และเมื่อเจ้ากระทําเช่นนี้ครบวันแล้ว เจ้าจะต้องนอนลงเป็นครั้งที่สอง แต่นอนตะแคงข้างขวา และเจ้าจะแบกความชั่วช้าของวงศ์วานยูดาห์ เรากําหนดให้เจ้าสี่สิบวันวันแทนปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 7, 'และเจ้าต้องตั้งหน้าตรงการล้อมเยรูซาเล็มไว้ด้วยแขนเปลือยเปล่า และเจ้าจงพยากรณ์สู้นครนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 8, 'และ ดูเถิด เราจะเอาเชือกมัดเจ้าไว้ เจ้าจะพลิกจากข้างนี้ไปข้างโน้นไม่ได้จนกว่าเจ้าจะครบการล้อมนครตามกําหนดวันของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 9, 'เจ้าจงเอาข้าวสาลี ข้าวบาร์เลย์ ถั่วยาง และถั่วแดง ข้าวฟ่าง และเทียนแดง มาใส่ในภาชนะลูกเดียวใช้ทําเป็นขนมปังให้เจ้า ระหว่างที่เจ้านอนตะแคงตามกําหนดวันสามร้อยเก้าสิบวันนั้น เจ้าจะรับประทานอาหารนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 10, 'และอาหารที่เจ้ารับประทานจะต้องชั่ง เป็นวันละยี่สิบเชเขล เจ้าจงรับประทานตามเวลากําหนด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 11, 'และน้ําเจ้าต้องตวงดื่ม คือหนึ่งในหกของฮินหนึ่ง เจ้าจงดื่มน้ําตามเวลากําหนด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 12, 'และเจ้าจะต้องรับประทานต่างขนมปังข้าวบาร์เลย์ ใช้ไฟอุจจาระมนุษย์ปิ้งท่ามกลางสายตาของเขาทั้งหลาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 13, 'และพระเยโฮวาห์ตรัสว่า “ประชาชนอิสราเอลจะต้องรับประทานขนมปังของเขาอย่างมลทินอย่างนี้แหละ ณ ท่ามกลางประชาชาติ ซึ่งเราจะขับไล่เขาไปอยู่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 14, 'แล้วข้าพเจ้าจึงกล่าวว่า “ข้าแต่องค์พระผู้เป็นเจ้าพระเจ้าข้า ดูเถิด จิตใจของข้าพระองค์ไม่เคยเป็นมลทินเลย เพราะตั้งแต่หนุ่มๆมาจนบัดนี้ ข้าพระองค์ไม่เคยรับประทานสิ่งที่ตายเอง หรือที่ถูกสัตว์ฉีกจนแหลกเป็นชิ้นๆ ไม่มีเนื้อสัตว์ที่พึงรังเกียจเข้าไปในปากของข้าพระองค์เลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 15, 'แล้วพระองค์จึงตรัสกับข้าพเจ้าว่า “ดูเถิด เราจะยอมให้เจ้าใช้มูลวัวแทนอุจจาระของมนุษย์ ซึ่งเจ้าจะใช้เตรียมขนมปังของเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 16, 'พระองค์ตรัสกับข้าพเจ้าอีกว่า “บุตรแห่งมนุษย์เอ๋ย ดูเถิด เราจะทําลายอาหารหลักในเยรูซาเล็มเสีย เขาจะต้องชั่งขนมปังรับประทาน ทั้งรับประทานด้วยความหวาดกลัว และเขาจะตวงน้ําดื่ม ทั้งดื่มด้วยอาการอกสั่นขวัญหาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 17, 'เพื่อให้ขาดขนมปังและน้ํา ให้ต่างคนต่างอกสั่นขวัญหาย และซูบผอมไปเพราะความชั่วช้าของเขาทั้งหลาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 1, '“เจ้า บุตรแห่งมนุษย์เอ๋ย เจ้าจงเอามีดคมเล่มหนึ่ง จงเอามีดโกนของช่างตัดผม จงโกนศีรษะและโกนเคราของเจ้า เอาตาชั่งสําหรับชั่งมา แบ่งผมนั้นออก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 2, 'เมื่อวันการล้อมครบถ้วนแล้ว เจ้าจงเผาหนึ่งในสามส่วนเสียในไฟที่กลางเมือง และเอาหนึ่งในสามอีกส่วนหนึ่งมา เอามีดฟันให้รอบเมือง และหนึ่งในสามอีกส่วนหนึ่งนั้น เจ้าจงให้ลมพัดกระจายไป และเราจะชักดาบออกตามไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 3, 'และเจ้าจงเอาเส้นผมนั้นมาหน่อยหนึ่งมัดติดไว้ที่เสื้อคลุมของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 4, 'และเจ้าจงเอาผมเหล่านี้มาอีกบ้าง จงโยนเข้าไปในไฟให้ไหม้เสียในไฟนั้น จากที่นั่นจะมีไฟเข้าไปในวงศ์วานอิสราเอลทั้งหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 5, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า นี่คือเยรูซาเล็ม เราตั้งเธอไว้ในท่ามกลางประชาชาติและประเทศทั้งหลายที่อยู่ล้อมรอบเธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 6, 'และเยรูซาเล็มได้เปลี่ยนคําตัดสินของเราให้เป็นสิ่งที่ชั่วร้ายยิ่งกว่าประชาชาติใดๆ และได้เปลี่ยนกฎเกณฑ์ของเรามากยิ่งกว่าประเทศที่อยู่ล้อมรอบ โดยปฏิเสธไม่รับคําตัดสินของเรา และไม่ดําเนินตามกฎเกณฑ์ของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 7, 'เพราะฉะนั้น องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า เพราะเหตุว่าเจ้าดันทุรังยิ่งกว่าประชาชาติที่อยู่รอบเจ้า และมิได้ดําเนินตามกฎเกณฑ์ หรือรักษาคําตัดสินของเรา แต่ได้ประพฤติตามคําตัดสินของประชาชาติที่อยู่รอบเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 8, 'เพราะฉะนั้น องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า ดูเถิด เรา แม้ว่าเรานี่แหละเป็นปฏิปักษ์กับเจ้า เราจะพิพากษาลงโทษท่ามกลางเจ้าท่ามกลางสายตาของประชาชาติทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 9, 'และเพราะการอันน่าสะอิดสะเอียนทั้งสิ้นของเจ้า เราจะกระทําท่ามกลางเจ้าอย่างที่เราไม่เคยกระทํามาก่อนเลย และเราจะไม่กระทําอย่างนั้นอีกต่อไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 10, 'เพราะฉะนั้นบิดาจะกินบุตรชายของตนท่ามกลางเจ้าทั้งหลาย และบรรดาบุตรชายจะกินบรรดาบิดาของเขาทั้งหลาย และเราจะพิพากษาลงโทษเจ้า ผู้ใดในพวกเจ้าที่เหลืออยู่ เราจะให้กระจัดกระจายไปตามลมทุกทิศานุทิศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 11, 'เพราะฉะนั้นองค์พระผู้เป็นเจ้าพระเจ้าจึงตรัสว่า เรามีชีวิตอยู่แน่ฉันใด แน่ทีเดียวเพราะเจ้าได้กระทําให้สถานบริสุทธิ์ของเราเป็นมลทินไปด้วยสิ่งน่าสะอิดสะเอียนทั้งสิ้นของเจ้า และด้วยสิ่งลามกทั้งสิ้นของเจ้า เพราะฉะนั้นเราจะตัดเจ้าลง นัยน์ตาของเราจะไม่ปรานี เราจะไม่สงสารด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 12, 'พวกเจ้าหนึ่งในสามส่วนจะล้มตายเพราะโรคระบาด และถูกผลาญด้วยการกันดารอาหารในหมู่พวกเจ้า อีกหนึ่งในสามส่วนจะล้มตายด้วยดาบอยู่รอบเจ้า และอีกหนึ่งในสามส่วนเราจะให้กระจัดกระจายไปตามลมทุกทิศานุทิศ และเราจะชักดาบออกไล่ตามเขาทั้งหลายไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 13, 'เช่นนี้แหละ ความกริ้วของเราจะมอดลง และเราจะระบายความโกรธของเราจนหมดและพอใจ และเขาทั้งหลายจะได้ทราบว่า เราคือพระเยโฮวาห์ได้กล่าวเช่นนี้ด้วยใจจดจ่อเมื่อความโกรธของเราต่อเขามอดลงแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 14, 'ยิ่งกว่านั้น เราจะกระทําให้เจ้าถูกทิ้งไว้ให้เสียไปเปล่าๆ และเป็นที่ถูกตําหนิติเตียนท่ามกลางประชาชาติทั้งหลายที่อยู่ล้อมรอบเจ้า และในสายตาของบรรดาผู้ที่ผ่านไปมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 15, 'เจ้าจะเป็นที่เขาประณามและเย้ยหยัน เป็นคําสั่งสอนและเป็นที่น่าหวาดเสียวแก่ประชาชาติที่อยู่ล้อมรอบเจ้า เมื่อเราจะพิพากษาลงโทษเจ้า ด้วยความกริ้วและความเกรี้ยวกราด และการต่อว่าอย่างรุนแรงของเรา เรา พระเยโฮวาห์ได้ลั่นวาจาเช่นนี้แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 16, 'เมื่อเราจะปล่อยลูกธนูมฤตยูแห่งการกันดารอาหาร คือลูกธนูแห่งการทําลายในท่ามกลางเจ้า ซึ่งเราจะปล่อยไปทําลายเจ้า และเมื่อเราเพิ่มการกันดารอาหารให้เจ้า และทําลายอาหารหลักของเจ้าเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 17, 'เราจะส่งการกันดารอาหารและสัตว์ป่าร้ายมาสู้เจ้า และมันจะริบลูกหลานของเจ้าไปเสีย โรคระบาดและโลหิตจะผ่านเจ้า และเราจะนําดาบมาเหนือเจ้า เราคือพระเยโฮวาห์ได้ลั่นวาจาเช่นนี้แล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 1, 'พระวจนะของพระเยโฮวาห์มาถึงข้าพเจ้าว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 2, '“บุตรแห่งมนุษย์เอ๋ย จงมุ่งหน้าของเจ้าตรงที่ภูเขาทั้งหลายของอิสราเอล และจงพยากรณ์กล่าวโทษภูเขานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 3, 'และกล่าวว่า ภูเขาทั้งหลายของอิสราเอลเอ๋ย จงฟังพระวจนะขององค์พระผู้เป็นเจ้าพระเจ้า องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้แก่ภูเขาทั้งหลายและแก่เนินเขา และห้วยและหุบเขาทั้งหลายว่า ดูเถิด เราจะนําดาบมาเหนือเจ้า และเราจะทําลายปูชนียสถานสูงของเจ้าเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 4, 'แท่นบูชาทั้งหลายของเจ้าจะรกร้าง และพวกรูปเคารพของเจ้าจะแตกหักเสีย และเราจะเหวี่ยงคนที่ถูกฆ่าสังเวยของเจ้านั้นลงต่อหน้ารูปเคารพของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 5, 'และเราจะวางศพคนอิสราเอลไว้หน้ารูปเคารพของเขา และเราจะกระจายกระดูกของเจ้ารอบแท่นบูชาของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 6, 'เจ้าอาศัยอยู่ที่ไหนๆ เมืองของเจ้าจะร้างและปูชนียสถานสูงของเจ้าจะรกร้าง ดังนั้นแหละแท่นบูชาของเจ้าจะร้างและรกร้าง รูปเคารพของเจ้าจะหักและสิ้นสุดลง รูปเคารพทั้งหลายของเจ้าจะถูกตัดลง และการงานของเจ้าจะถูกกวาดทิ้งเสียสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 7, 'และคนที่ถูกฆ่าจะล้มลงท่ามกลางเจ้า และเจ้าจะทราบว่าเราคือพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 8, 'แต่เราจะให้เจ้าเหลืออยู่บ้างเป็นบางคน เพื่อเจ้าจะมีบางคนท่ามกลางประชาชาติที่หนีพ้นดาบไป เมื่อเจ้าจะกระจายไปอยู่ในประเทศต่างๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 9, 'แล้วคนในพวกเจ้าที่หนีไปได้นั้น จะระลึกถึงเราท่ามกลางประชาชาติทั้งหลาย ซึ่งเขาถูกกวาดไปเป็นเชลยนั้น เพราะใจของเราแหลกสลายเนื่องด้วยใจแพศยาของเขาซึ่งได้พรากจากเราไป และเนื่องด้วยตาของเขาที่มองดูรูปเคารพด้วยใจแพศยานั้น และเขาจะเกลียดตัวเองเนื่องจากความชั่วร้ายซึ่งเขาได้กระทําในสิ่งที่น่าสะอิดสะเอียนทั้งสิ้นของเขาด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 10, 'เขาจะทราบว่าเราคือพระเยโฮวาห์ เรามิได้พูดพล่อยๆว่า เราจะกระทําการร้ายนี้แก่เขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 11, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า “จงตบมือและกระทืบเท้าของเจ้า และกล่าวว่า อนิจจาสําหรับการกระทําอันน่าสะอิดสะเอียนทั้งสิ้นแห่งวงศ์วานอิสราเอล เหตุว่าเขาทั้งหลายจะล้มลงด้วยดาบ ด้วยการกันดารอาหารและด้วยโรคระบาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 12, 'ผู้ที่อยู่ห่างไกลออกไปจะตายด้วยโรคระบาด ผู้ที่อยู่ใกล้ก็จะล้มตายด้วยดาบ และผู้ที่เหลืออยู่และถูกล้อมไว้จะตายด้วยการกันดารอาหาร เราจะให้ความเกรี้ยวกราดของเรามีเหนือเขาจนกว่าจะมอดลง เช่นนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 13, 'และเจ้าจะทราบว่าเราคือพระเยโฮวาห์ เมื่อคนที่ถูกฆ่านอนอยู่ท่ามกลางรูปเคารพของเขารอบแท่นบูชาของเขา บนเนินเขาสูงทุกแห่ง บนยอดเขาทั้งสิ้น ที่ใต้ต้นไม้เขียวทุกต้น และใต้ต้นโอ๊กใบดกทุกต้น ไม่ว่าที่ใดๆที่เขาถวายกลิ่นที่พึงใจแก่รูปเคารพทั้งสิ้นของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 14, 'และเราจะยื่นมือของเราออกต่อสู้เขา และกระทําให้แผ่นดินนั้นรกร้าง และทิ้งร้างตลอดที่อาศัยทั้งสิ้นของเขา คือรกร้างมากกว่าถิ่นทุรกันดารที่ไปทางดิบลา แล้วเขาจึงจะรู้ว่าเราคือพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 1, 'พระวจนะของพระเยโฮวาห์มาถึงข้าพเจ้าอีกว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 2, '“เจ้า บุตรแห่งมนุษย์เอ๋ย องค์พระผู้เป็นเจ้าพระเจ้าตรัสกับแผ่นดินอิสราเอลดังนี้ว่า อวสาน ความสิ้นสุดได้มาถึงทั้งสี่มุมของแผ่นดินแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 3, 'บัดนี้บั้นปลายก็มาถึงเจ้าแล้ว และเราจะปล่อยความโกรธของเรามาเหนือเจ้าทั้งหลาย และจะพิพากษาเจ้าตามวิถีทางทั้งหลายของเจ้า และเราจะตอบสนองการกระทําอันน่าสะอิดสะเอียนทั้งสิ้นของเจ้าแก่เจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 4, 'นัยน์ตาของเราจะไม่เมตตาเจ้า และเราจะไม่สงสาร แต่เราจะตอบสนองต่อวิถีทางทั้งหลายของเจ้าแก่เจ้าเอง และสิ่งที่น่าสะอิดสะเอียนของเจ้าจะอยู่ท่ามกลางเจ้า แล้วเจ้าจะทราบว่า เราคือพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 5, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า วิบัติแล้ววิบัติเล่า ดูเถิด วิบัติมาถึงแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 6, 'ความสิ้นสุดมาถึงแล้ว อวสานนั้นมาถึง มันตื่นขึ้นต่อสู้เจ้า ดูเถิด วิบัติมาถึงแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 7, 'โอ ชาวแผ่นดินเอ๋ย เวลาเช้ามาถึงแล้ว เวลามาถึงแล้ว วันแห่งความโกลาหลใกล้เข้ามาแล้ว และไม่ใช่เสียงโห่ร้องยินดีที่บนภูเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 8, 'บัดนี้ ไม่ช้าแล้วเราจะเทความเดือดดาลของเราลงบนเจ้า และกระทําให้ความโกรธของเราซึ่งมีต่อเจ้าถึงที่สําเร็จ และเราจะพิพากษาเจ้าตามวิถีทางทั้งหลายของเจ้า และเราจะตอบสนองเจ้าสําหรับการกระทําอันน่าสะอิดสะเอียนทั้งสิ้นของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 9, 'นัยน์ตาของเราจะไม่เมตตา และเราจะไม่สงสาร เราจะตอบสนองเจ้าตามวิถีทางทั้งหลายของเจ้า และตามการกระทําอันน่าสะอิดสะเอียนของเจ้าซึ่งอยู่ท่ามกลางเจ้า แล้วเจ้าจะทราบว่า เราคือพระเยโฮวาห์ผู้โบยตี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 10, 'ดูเถิด วันนั้น ดูเถิด มาถึงแล้ว เวลาเช้าออกมาแล้ว พลองก็บานแล้ว ความเย่อหยิ่งก็ผลิดอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 11, 'ความทารุณได้เจริญเป็นพลองชั่วร้าย จะไม่มีใครเหลืออยู่เลย ประชาชนของเขาก็ไม่มี สิ่งของของเขาก็ไม่มี ไม่มีใครร้องคร่ําครวญเผื่อพวกเขาเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 12, 'เวลานั้นมาถึงแล้ว วันนั้นก็ใกล้เข้า อย่าให้ผู้ซื้อดีใจ อย่าให้ผู้ขายเสียใจ เพราะพระพิโรธอยู่เหนือประชาชนทั้งสิ้นของเธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 13, 'เพราะว่าผู้ขายจะไม่ได้กลับไปยังสิ่งที่เขาได้ขายไป ขณะเมื่อเขายังมีชีวิตอยู่ เพราะว่านิมิตนั้นก็เกี่ยวข้องกับประชาชนทั้งมวล และจะไม่หันกลับ และเพราะความชั่วช้าของเขา จึงจะไม่มีผู้ใดรักษาชีวิตไว้ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 14, 'เขาได้เป่าแตรแล้ว และได้เตรียมทุกอย่างไว้พร้อม แต่ไม่มีใครเข้าสงคราม เพราะว่าพิโรธของเราอยู่เหนือประชาชนทั้งสิ้นของเธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 15, 'ดาบก็อยู่ข้างนอก โรคระบาดและการกันดารอาหารก็อยู่ข้างใน ผู้ที่อยู่ในทุ่งนาจะตายเสียด้วยดาบ และผู้ที่อยู่ในเมืองการกันดารอาหารและโรคระบาดจะกินเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 16, 'แต่ผู้หนึ่งผู้ใดที่รอดตายได้จะหนีไปอยู่บนภูเขาเหมือนนกเขาแห่งหุบเขา ทุกคนก็ร้องครวญครางเพราะความชั่วช้าของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 17, 'มือทั้งสิ้นจะอ่อนแอ และเข่าทั้งหมดจะอ่อนเหมือนน้ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 18, 'เขาทั้งหลายจะคาดเอวไว้ด้วยผ้ากระสอบ และความสั่นสะท้านจะครอบเขาไว้ ความละอายจะอยู่ที่ใบหน้าของเขาทุกคน และศีรษะของเขาจะล้านหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 19, 'เขาจะโยนเงินของเขาไปในถนน และทองคําของเขาจะถูกเอาออกไปเสีย เงินและทองของเขาไม่อาจที่จะช่วยเขาให้พ้นในวันแห่งพระพิโรธของพระเยโฮวาห์ เขาจะให้หายหิว หรือบรรจุให้เต็มท้องด้วยเงินทองก็ไม่ได้ เพราะว่าเป็นสิ่งที่สะดุดให้เขาทําความชั่วช้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 20, 'เขานําความงดงามแห่งเครื่องประดับของเขามาแสดงออกถึงความสง่าผ่าเผย และเขาสร้างรูปเคารพด้วยสิ่งที่น่าสะอิดสะเอียนและน่าเกลียดน่าชังของเขาไว้ภายในเครื่องประดับนั้น เพราะฉะนั้นเราจะกระทําให้สิ่งนี้อยู่ห่างไกลจากเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 21, 'และเราจะมอบสิ่งเหล่านั้นไว้ในมือของชนต่างด้าวให้เป็นของริบ และแก่คนชั่วในแผ่นดินโลกให้เป็นของปล้นได้ และเขาทั้งหลายจะกระทําให้เป็นมลทิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 22, 'เราจะหันหน้าของเราไปเสียจากเขาด้วย แล้วเขาจึงจะกระทําสถานที่ลับของเราให้มัวหมอง โจรจะเข้ามาในสถานที่ลับนั้นและกระทําให้เป็นมลทิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 23, 'จงทําโซ่ตรวน เพราะว่าแผ่นดินนั้นเต็มด้วยคดีที่แปดเปื้อนด้วยโลหิต และเมืองก็เต็มด้วยความทารุณ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 24, 'ฉะนั้นเราจะนําประชาชาติที่ชั่วร้ายที่สุดมาถือกรรมสิทธิ์บ้านเรือนของเขา และเราจะให้ทิฐิของคนที่แข็งแรงนั้นสิ้นสุดลง และสถานที่บริสุทธิ์ของเขาจะเป็นมลทิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 25, 'เมื่อการทําลายมาถึง เขาจะแสวงหาสันติภาพ แต่ก็ไม่มีเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 26, 'วิบัติมาถึงแล้ว วิบัติจะมาถึงอีก ข่าวลือจะเกิดตามข่าวลือ เขาจะแสวงหานิมิตจากผู้พยากรณ์ แต่พระราชบัญญัติจะพินาศไปจากปุโรหิต และคําปรึกษาจะปลาตไปจากพวกผู้ใหญ่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 27, 'กษัตริย์จะไว้ทุกข์ และเจ้านายจะคลุมกายด้วยความทอดอาลัย และมือของประชาชนแห่งแผ่นดินนั้นจะสั่นเทา เราจะกระทําแก่เขาตามทางของเขา และเราจะพิพากษาเขาตามสมควรแก่การกระทําของเขา และเขาจะทราบว่าเราคือพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 1, 'ต่อมาเมื่อวันที่ห้า เดือนที่หก ในปีที่หก ขณะที่ข้าพเจ้านั่งอยู่ในเรือนของข้าพเจ้า และพวกผู้ใหญ่ของพวกยูดาห์นั่งอยู่หน้าข้าพเจ้า พระหัตถ์ขององค์พระผู้เป็นเจ้าพระเจ้าลงมาบนข้าพเจ้า ณ ที่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 2, 'แล้วข้าพเจ้าก็มองดู และดูเถิด มีสัณฐานอย่างไฟ เบื้องล่างของส่วนที่มองเห็นเป็นเอวนั้นเป็นไฟ เหนือเอวขึ้นไปเหมือนความสุกปลั่งประดุจสีเหลืองอําพัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 3, 'ท่านยื่นส่วนที่มีสัณฐานเป็นมือนั้นออกมาจับผมของข้าพเจ้าปอยหนึ่ง และพระวิญญาณได้ยกข้าพเจ้าขึ้นระหว่างพิภพและสวรรค์ และนําข้าพเจ้ามาถึงเยรูซาเล็มในนิมิตของพระเจ้า มายังทางเข้าประตูด้านเหนือของลานชั้นใน ซึ่งเป็นที่ตั้งรูปของความหวงแหน ซึ่งกระทําให้บังเกิดความหวงแหน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 4, 'ดูเถิด สง่าราศีของพระเจ้าของอิสราเอลก็อยู่ที่นั่น เหมือนอย่างนิมิตที่ข้าพเจ้าได้เห็นในที่ราบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 5, 'แล้วพระองค์ตรัสกับข้าพเจ้าว่า “บุตรแห่งมนุษย์เอ๋ย บัดนี้จงเงยหน้าขึ้นไปดูทางทิศเหนือ” ข้าพเจ้าจึงเงยหน้าขึ้นมองไปดูทางทิศเหนือ และดูเถิด ทางทิศเหนือของประตูแท่นบูชาในทางเข้า รูปความหวงแหนนี้อยู่ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 6, 'และพระองค์ตรัสกับข้าพเจ้ายิ่งกว่านั้นอีกว่า “บุตรแห่งมนุษย์เอ๋ย เจ้าไม่เห็นหรือว่าเขาทําอะไร คือการกระทําอันน่าสะอิดสะเอียนที่ยิ่งใหญ่ซึ่งวงศ์วานอิสราเอลกระทํากันอยู่ที่นี่ ซึ่งจะทําให้เราออกไปให้ไกลจากสถานบริสุทธิ์ของเรา แต่เจ้าจงหันกลับมาอีกแล้วจะได้เห็นสิ่งที่น่าสะอิดสะเอียนที่ยิ่งใหญ่กว่านี้อีก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 7, 'และพระองค์ทรงนําข้าพเจ้ามาถึงประตูลาน และเมื่อข้าพเจ้ามองดู ดูเถิด ก็เห็นช่องหนึ่งอยู่ในกําแพง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 8, 'แล้วพระองค์ตรัสกับข้าพเจ้าว่า “บุตรแห่งมนุษย์เอ๋ย จงเจาะเข้าไปในกําแพง” และเมื่อข้าพเจ้าได้เจาะเข้าไปในกําแพงแล้ว ดูเถิด มีประตูอยู่ประตูหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 9, 'และพระองค์ตรัสกับข้าพเจ้าว่า “จงเข้าไปดูสิ่งที่น่าสะอิดสะเอียนอันชั่วร้ายซึ่งเขากระทํากันที่นี่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 10, 'ดังนั้นข้าพเจ้าจึงเข้าไปและได้เห็น ดูเถิด มีภาพสัตว์เลื้อยคลานในทุกรูปแบบ และสัตว์ที่พึงรังเกียจและรูปเคารพทั้งสิ้นของวงศ์วานอิสราเอลปรากฏอยู่บนผนังโดยรอบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 11, 'และมีพวกผู้ใหญ่แห่งวงศ์วานอิสราเอลเจ็ดสิบคนยืนอยู่ข้างหน้ารูปเหล่านั้น และมียาอาซันยาห์ บุตรชายชาฟานยืนอยู่ในหมู่พวกเขาทั้งหลาย ต่างก็มีกระถางไฟอยู่ในมือ และควันหนาทึบแห่งเครื่องบูชาก็ขึ้นไปข้างบน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 12, 'แล้วพระองค์ตรัสกับข้าพเจ้าว่า “บุตรแห่งมนุษย์เอ๋ย เจ้าได้เห็นแล้วมิใช่หรือว่าพวกผู้ใหญ่ของวงศ์วานอิสราเอลกระทําอะไรอยู่ในที่มืด ทุกคนต่างก็อยู่ในห้องรูปภาพของตนเพราะเขาทั้งหลายพูดว่า ‘พระเยโฮวาห์ไม่ทอดพระเนตรเห็นเรา พระเยโฮวาห์ทรงทอดทิ้งแผ่นดินนี้เสียแล้ว’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 13, 'พระองค์ตรัสกับข้าพเจ้าด้วยว่า “เจ้าจงหันกลับมาอีกแล้วเจ้าจะเห็นสิ่งที่น่าสะอิดสะเอียนซึ่งเขากระทํายิ่งกว่านี้อีก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 14, 'แล้วพระองค์ทรงนําข้าพเจ้ามาถึงทางเข้าประตูพระนิเวศของพระเยโฮวาห์ด้านเหนือ และดูเถิด ที่นั่นมีผู้หญิงหลายคนนั่งร้องไห้อาลัยเจ้าพ่อทัมมุส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 15, 'แล้วพระองค์ตรัสกับข้าพเจ้าว่า “โอ บุตรแห่งมนุษย์เอ๋ย เจ้าได้เห็นแล้วใช่ไหม เจ้าจงหันกลับมาอีกแล้วจะเห็นสิ่งที่น่าสะอิดสะเอียนยิ่งกว่าสิ่งเหล่านี้อีก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 16, 'แล้วพระองค์ทรงนําข้าพเจ้าเข้ามาในลานชั้นในแห่งพระนิเวศของพระเยโฮวาห์ ดูเถิด ตรงประตูพระวิหารของพระเยโฮวาห์ ระหว่างมุขและแท่นบูชา มีชายประมาณยี่สิบห้าคนหันหลังให้พระวิหารแห่งพระเยโฮวาห์ หน้าของเขาหันไปทางทิศตะวันออก กําลังนมัสการพระอาทิตย์ตรงทิศตะวันออกนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 17, 'แล้วพระองค์ตรัสกับข้าพเจ้าว่า “โอ บุตรแห่งมนุษย์เอ๋ย เจ้าได้เห็นแล้วใช่ไหม ที่วงศ์วานยูดาห์กระทําสิ่งที่น่าสะอิดสะเอียนซึ่งเขากระทําอยู่ที่นี่ เป็นสิ่งเล็กน้อยหรือ ด้วยว่าเขากระทําให้แผ่นดินเต็มไปด้วยความรุนแรง และกลับมายั่วยุให้เราโกรธแล้ว ดูเถิด เขาทั้งหลายเอากิ่งไม้มาแตะจมูกของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 18, 'เพราะฉะนั้น เราจะกระทําด้วยความพิโรธ นัยน์ตาของเราจะไม่ปรานี และเราจะไม่สงสาร แม้ว่าเขาจะร้องด้วยเสียงอันดังใส่หูของเรา เราจะไม่ฟังเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 1, 'แล้วพระองค์ทรงเปล่งพระสุรเสียงดังเข้าหูข้าพเจ้าว่า “เจ้าทั้งหลายผู้เป็นพนักงานทําโทษประจําเมือง จงเข้ามาใกล้ ให้ต่างคนถืออาวุธสําหรับทําลายมาด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 2, 'และ ดูเถิด มีชายหกคนเข้ามาจากทางประตูบน ซึ่งหันหน้าไปทางเหนือ ทุกคนถืออาวุธสําหรับฆ่ามา มีชายคนหนึ่งนุ่งห่มผ้าป่าน หนีบหีบเครื่องเขียนมากับคนเหล่านั้นด้วย และเขาทั้งหลายเข้าไปยืนอยู่ที่ข้างแท่นทองเหลือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 3, 'สง่าราศีของพระเจ้าของอิสราเอลได้เหาะขึ้นไปจากเครูบ แล้วซึ่งเป็นที่เคยสถิตไปยังธรณีประตูพระนิเวศ และพระองค์ตรัสเรียกชายผู้ที่นุ่งห่มผ้าป่าน ผู้ที่หนีบหีบเครื่องเขียน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 4, 'และพระเยโฮวาห์ตรัสกับเขาว่า “จงผ่านไปท่ามกลางนครนั้นให้ตลอด คือตลอดท่ามกลางกรุงเยรูซาเล็ม และทําเครื่องหมายไว้บนหน้าผากของประชาชนที่ถอนหายใจ และร่ําไห้เพราะสิ่งที่น่าสะอิดสะเอียนทั้งสิ้นที่กระทํากันท่ามกลางนครนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 5, 'และพระองค์ตรัสกับคนอื่นๆซึ่งข้าพเจ้าได้ยินว่า “จงผ่านไปตลอดนครตามชายคนนั้นไปและฆ่าฟันเสีย นัยน์ตาของเจ้าอย่าได้ปรานี และเจ้าอย่าสงสารเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 6, 'จงฆ่าให้ตายทั้งคนแก่ คนหนุ่มๆ สาวๆ ทั้งเด็กๆ และผู้หญิง แต่อย่าเข้าใกล้ผู้ที่มีเครื่องหมาย และจงเริ่มต้นที่สถานบริสุทธิ์ของเรา” ดังนั้นเขาจึงตั้งต้นกับพวกคนแก่ผู้ซึ่งอยู่หน้าพระนิเวศนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 7, 'แล้วพระองค์ตรัสกับพวกเขาว่า “จงกระทําให้พระนิเวศเป็นมลทิน จงทิ้งผู้ที่ถูกฆ่าให้เต็มลาน จงไปเถิด” เขาทั้งหลายจึงออกไปและฆ่าฟันที่ในนคร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 8, 'ต่อมาขณะที่เขากําลังฆ่าฟันอยู่นั้นเหลือข้าพเจ้าแต่ลําพัง ข้าพเจ้าก็ซบหน้าลงถึงดินร้องว่า “อนิจจา องค์พระผู้เป็นเจ้าพระเจ้า พระองค์จะทรงทําลายคนอิสราเอลที่เหลืออยู่นั้นทั้งสิ้นในการที่พระองค์ทรงระบายความกริ้วของพระองค์เหนือเยรูซาเล็มหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 9, 'แล้วพระองค์ตรัสกับข้าพเจ้าว่า “ความชั่วช้าของวงศ์วานอิสราเอลและยูดาห์ใหญ่ยิ่งนัก แผ่นดินก็เต็มไปด้วยโลหิต และความอยุติธรรมก็เต็มนคร เพราะเขากล่าวว่า ‘พระเยโฮวาห์ทรงทอดทิ้งแผ่นดินนี้แล้ว และพระเยโฮวาห์ไม่ทอดพระเนตรอีก’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 10, 'สําหรับเรา นัยน์ตาของเราจะไม่ปรานี และเราจะไม่สงสาร แต่เราจะตอบสนองตามการประพฤติของเขาเหนือศีรษะของเขาทั้งหลาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 11, 'และดูเถิด ชายคนที่นุ่งห่มผ้าป่านหนีบหีบเครื่องเขียนนั้น ได้นําถ้อยคํากลับมากล่าวว่า “ข้าพระองค์ได้กระทําตามที่พระองค์ทรงบัญชาข้าพระองค์ไว้นั้นแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 1, 'แล้วข้าพเจ้าก็มองดู ดูเถิด ที่ท้องฟ้าซึ่งอยู่เหนือศีรษะของเหล่าเครูบ มีอะไรปรากฏขึ้นเหนือเครูบนั้นเหมือนไพทูรย์ มีสัณฐานคล้ายพระที่นั่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 2, 'และพระองค์ตรัสกับชายที่นุ่งห่มผ้าป่านว่า “จงเข้าไปท่ามกลางวงล้อซึ่งอยู่ภายใต้เครูบ จงเอามือกอบถ่านคุจากท่ามกลางเหล่าเครูบ นําไปโปรยเหนือนครนั้น” และชายคนนั้นก็เข้าไปท่ามกลางสายตาของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 3, 'ฝ่ายเหล่าเครูบนั้นยืนที่ด้านขวาของพระนิเวศ ขณะเมื่อชายคนนั้นเข้าไป และเมฆก็คลุมอยู่เต็มลานชั้นใน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 4, 'และสง่าราศีของพระเยโฮวาห์ก็ขึ้นจากเครูบไปยังธรณีประตูพระนิเวศ และพระนิเวศนั้นก็มีเมฆคลุมอยู่เต็ม และลานนั้นก็เต็มไปด้วยความสุกใสแห่งสง่าราศีของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 5, 'และเสียงปีกของเหล่าเครูบนั้นก็ได้ยินไปถึงลานชั้นนอก เหมือนพระสุรเสียงของพระเจ้าผู้ทรงมหิทธิฤทธิ์เมื่อพระองค์ตรัส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 6, 'และต่อมาเมื่อพระองค์มีพระบัญชาสั่งชายที่นุ่งห่มผ้าป่านว่า “จงไปเอาไฟมาจากกลางวงล้อ และจากกลางเหล่าเครูบ” ชายคนนั้นก็เข้าไปยืนอยู่ข้างๆวงล้อเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 7, 'เครูบตนหนึ่งได้ยื่นมือของตนออกมาระหว่างเหล่าเครูบไปยังไฟซึ่งอยู่ระหว่างเหล่าเครูบ หยิบไฟขึ้นมาบ้าง และใส่มือของชายที่นุ่งห่มผ้าป่าน ชายนั้นก็นําไฟออกไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 8, 'ปรากฏว่าในเหล่าเครูบนั้นมีอะไรอยู่ใต้ปีกอย่างมือมนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 9, 'และข้าพเจ้ามองดู ดูเถิด มีวงล้ออยู่สี่อันข้างๆเหล่าเครูบ อยู่ข้างเครูบตนละหนึ่งวงล้อ ลักษณะของวงล้อนั้นเหมือนแสงพลอยเขียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 10, 'ลักษณะสัณฐานวงล้อทั้งสี่นั้นก็เหมือนกัน เหมือนวงล้อซ้อนในวงล้อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 11, 'เมื่อวงล้อนี้ไป ก็ไปได้ข้างหนึ่งข้างใดในข้างทั้งสี่ โดยไม่ต้องหันเลยในเวลาไป ถ้าอันหน้ามุ่งหน้าไปทางไหน วงล้ออันอื่นก็ตามไปโดยไม่ต้องหันในขณะที่ไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 12, 'และทั้งตัว ด้านหลัง มือ ปีก และวงล้อมีนัยน์ตาเต็มอยู่รอบ ทั้งสี่นั้นก็มีวงล้อของตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 13, 'วงล้อเหล่านั้น ที่ข้าพเจ้าได้ยินกับหูเขาเรียกว่า “โอ วงล้อกังหันเอ๋ย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 14, 'มีหน้าสี่หน้าทั้งนั้น หน้าแรกเป็นหน้าเครูบ หน้าที่สองเป็นหน้ามนุษย์ และหน้าที่สามเป็นหน้าสิงโต และที่สี่เป็นหน้านกอินทรี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 15, 'และเหล่าเครูบก็เหาะขึ้น เป็นสิ่งที่มีชีวิตอยู่ที่ข้าพเจ้าเคยเห็นอยู่ริมแม่น้ําเคบาร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 16, 'เมื่อเหล่าเครูบไป วงล้อก็ตามข้างไปด้วย และเมื่อเหล่าเครูบกางปีกออกเพื่อบินขึ้นจากพิภพ วงล้อเหล่านั้นก็ไม่หันไปจากข้างๆเหล่าเครูบเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 17, 'เมื่อเหล่าเครูบหยุดนิ่ง เหล่าวงล้อก็หยุดนิ่ง เมื่อเหล่าเครูบเหาะขึ้น เหล่าวงล้อก็เหาะขึ้นไปด้วย เพราะว่าวิญญาณของสิ่งที่มีชีวิตอยู่นั้นอยู่ในวงล้อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 18, 'แล้วสง่าราศีของพระเยโฮวาห์ได้ไปจากธรณีประตูพระนิเวศ สถิตเหนือเหล่าเครูบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 19, 'เมื่อเหล่าเครูบออกไปก็กางปีกออกบินขึ้นไปจากพิภพท่ามกลางสายตาของข้าพเจ้า วงล้อก็ตามข้างไปด้วย และไปยืนอยู่ที่ทางเข้าประตูด้านตะวันออกของพระนิเวศแห่งพระเยโฮวาห์ และสง่าราศีของพระเจ้าของอิสราเอลก็อยู่เหนือเครูบเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 20, 'เหล่านี้เป็นสิ่งที่มีชีวิตอยู่ซึ่งข้าพเจ้าได้เห็นภายใต้พระเจ้าแห่งอิสราเอลที่ริมแม่น้ําเคบาร์ และข้าพเจ้าทราบว่า เป็นเหล่าเครูบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 21, 'เครูบทุกตนมีสี่หน้าและสี่ปีก และภายใต้ปีกมีสัณฐานเหมือนมือมนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 22, 'ส่วนสัณฐานของหน้าเหล่านั้น เป็นหน้าทั้งรูปทั้งตัว ซึ่งข้าพเจ้าได้เห็นที่ริมแม่น้ําเคบาร์ เครูบทุกตนออกตรงไปข้างหน้าของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 1, 'พระวิญญาณได้ยกข้าพเจ้าขึ้น และนําข้าพเจ้ามายังประตูด้านตะวันออกของพระนิเวศแห่งพระเยโฮวาห์ซึ่งหันหน้าไปทิศตะวันออก ดูเถิด ที่ทางเข้าประตูมีผู้ชายอยู่ยี่สิบห้าคน และท่ามกลางนั้นข้าพเจ้าเห็นยาอาซันยาห์บุตรชายอัสซูร์ และเป-ลาทียาห์บุตรชายเบไนยาห์ เจ้านายแห่งประชาชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 2, 'และพระองค์ตรัสกับข้าพเจ้าว่า “บุตรแห่งมนุษย์เอ๋ย คนเหล่านี้คือผู้ที่ออกอุบายทําความบาปผิด และเป็นผู้ให้คําปรึกษาที่ชั่วร้ายในนครนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 3, 'ผู้กล่าวว่า ‘เวลายังไม่มาใกล้เลย ให้เราปลูกบ้านเถิด นครนี้เป็นหม้อขนาดใหญ่และเราเป็นเนื้อ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 4, 'โอ บุตรแห่งมนุษย์เอ๋ย เพราะฉะนั้นจงพยากรณ์กล่าวโทษเขา จงพยากรณ์เถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 5, 'พระวิญญาณของพระเยโฮวาห์ลงมาประทับบนข้าพเจ้า และพระองค์ตรัสกับข้าพเจ้าว่า “จงกล่าวเถิดว่า พระเยโฮวาห์ตรัสดังนี้ว่า โอ วงศ์วานอิสราเอลเอ๋ย เจ้าคิดดังนั้น และเรารู้สิ่งทั้งหลายที่เข้ามาในใจของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 6, 'เจ้าได้ทวีคนที่เจ้าได้ฆ่าในนครนี้ และทิ้งคนที่ถูกฆ่าเต็มตามถนนหนทางไปหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 7, 'เพราะฉะนั้นองค์พระผู้เป็นเจ้าพระเจ้าจึงตรัสดังนี้ว่า คนทั้งหลายที่เจ้าได้ฆ่าซึ่งเจ้าได้ทิ้งไว้ท่ามกลางนครนี้ เขาทั้งหลายเป็นเนื้อ และนครนี้เป็นหม้อขนาดใหญ่ แต่เราจะนําเจ้าออกมาจากท่ามกลางนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 8, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสว่า เจ้ากลัวดาบ และเราจะนําดาบมาเหนือเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 9, 'เราจะนําเจ้าออกมาจากท่ามกลางนั้น และมอบเจ้าไว้ในมือของคนต่างด้าว และจะทําการพิพากษาลงโทษเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 10, 'เจ้าจะถูกดาบล้มลง เราจะลงโทษเจ้าที่พรมแดนอิสราเอล และเจ้าจะได้ทราบว่าเราคือพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 11, 'นครนี้จะไม่ใช่หม้อขนาดใหญ่ของเจ้า ที่เจ้าจะเป็นเนื้อในท่ามกลางนั้น เราจะพิพากษาเจ้าที่พรมแดนอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 12, 'และเจ้าจะทราบว่าเราคือพระเยโฮวาห์ เพราะเจ้ามิได้ดําเนินตามกฎเกณฑ์ของเรา หรือปฏิบัติตามคําตัดสินของเรา แต่ได้ประพฤติตามลักษณะท่าทางของประชาชาติทั้งหลายที่อยู่รอบเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 13, 'อยู่มาเมื่อข้าพเจ้ากําลังพยากรณ์อยู่ เป-ลาทียาห์บุตรชายเบไนยาห์ก็สิ้นชีวิต แล้วข้าพเจ้าก็ซบหน้าลงถึงดินร้องเสียงดังว่า “องค์พระผู้เป็นเจ้าพระเจ้า เจ้าข้า พระองค์จะทรงกระทําให้คนอิสราเอลที่เหลืออยู่นั้นสิ้นสุดเลยทีเดียวหรือ พระเจ้าข้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 14, 'พระวจนะของพระเยโฮวาห์มายังข้าพเจ้าอีกว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 15, '“บุตรแห่งมนุษย์เอ๋ย พี่น้องของเจ้า คือพี่น้องของเจ้าเอง คือญาติที่มีสิทธิ์ไถ่คืน สิ้นทั้งวงศ์วานอิสราเอลหมดด้วยกัน คือบุคคลที่ชาวเยรูซาเล็มได้กล่าวว่า ‘เจ้าทั้งหลายจงเหินห่างไปจากพระเยโฮวาห์ แผ่นดินนี้ทรงมอบไว้แก่เราเป็นกรรมสิทธิ์’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 16, 'เพราะฉะนั้นจงกล่าวว่า ‘องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า แม้เราได้ย้ายเขาให้ห่างออกไปอยู่ท่ามกลางประชาชาติทั้งหลาย แม้เราได้กระจายเขาไปอยู่ท่ามกลางประเทศทั้งปวง เราก็จะเป็นสถานบริสุทธิ์อันเล็กสําหรับเขาในประเทศที่เขาจะได้ไปอยู่’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 17, 'เพราะฉะนั้นจงกล่าวว่า ‘องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า เราจะรวบรวมเจ้ามาจากชนชาติทั้งหลาย และชุมนุมเจ้าจากประเทศที่เจ้ากระจัดกระจายไปอยู่นั้น และเราจะมอบแผ่นดินอิสราเอลให้แก่เจ้า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 18, 'และเขาจะมาที่นั่น เขาจะเอาสิ่งที่น่ารังเกียจทั้งสิ้นของเมืองนั้น และสิ่งที่น่าสะอิดสะเอียนทั้งสิ้นของเมืองนั้นออกไปเสียจากที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 19, 'และเราจะให้จิตใจเดียวแก่เขา และเราจะบรรจุจิตวิญญาณใหม่ไว้ในเจ้า เราจะนําใจหินออกไปเสียจากเนื้อของเขา และจะให้ใจเนื้อแก่เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 20, 'เพื่อเขาจะดําเนินตามกฎเกณฑ์ของเรา และรักษากฎของเราและกระทําตาม เขาทั้งหลายจะเป็นประชาชนของเรา และเราจะเป็นพระเจ้าของเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 21, 'แต่คนเหล่านั้นที่ใจของเขาดําเนินตามจิตใจแห่งสิ่งที่น่ารังเกียจของเขาและสิ่งที่น่าสะอิดสะเอียนของเขา เราจะตอบสนองต่อวิถีทางของเขาเหนือศีรษะของเขาเอง องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้แหละ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 22, 'แล้วเหล่าเครูบก็กางปีกออก วงล้อก็อยู่ข้างๆ และสง่าราศีของพระเจ้าของอิสราเอลก็อยู่เหนือสิ่งเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 23, 'สง่าราศีของพระเยโฮวาห์ขึ้นไปจากกลางนคร ไปสถิตอยู่บนภูเขาซึ่งอยู่ทางด้านตะวันออกของนครนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 24, 'ต่อมาพระวิญญาณได้ยกข้าพเจ้าขึ้น และนําข้าพเจ้ามาด้วยนิมิตโดยพระวิญญาณของพระเจ้าถึงเมืองเคลเดีย มาสู่พวกที่ถูกกวาดไปเป็นเชลย แล้วนิมิตที่ข้าพเจ้าได้เห็นนั้นก็ขึ้นไปจากข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 25, 'ข้าพเจ้าจึงได้บอกถึงบรรดาสิ่งต่างๆซึ่งพระเยโฮวาห์ทรงสําแดงแก่ข้าพเจ้าให้พวกที่ถูกกวาดไปเป็นเชลยทราบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 1, 'พระวจนะของพระเยโฮวาห์มาถึงข้าพเจ้าว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 2, '“บุตรแห่งมนุษย์เอ๋ย เจ้าอาศัยอยู่ท่ามกลางวงศ์วานที่มักกบฏ ผู้มีตาเพื่อดู แต่ดูไม่เห็น ผู้มีหูเพื่อฟัง แต่ฟังไม่ได้ยิน เพราะเขาทั้งหลายเป็นวงศ์วานที่มักกบฏ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 3, 'เพราะฉะนั้น บุตรแห่งมนุษย์เอ๋ย เจ้าจงจัดเตรียมข้าวของสําหรับตนเพื่อการถูกกวาดไปเป็นเชลย และจงไปเป็นเชลยในเวลากลางวันท่ามกลางสายตาของเขา เจ้าจะต้องไปเป็นเชลยจากสถานที่ของเจ้าไปยังอีกที่หนึ่งในสายตาของเขา บางทีเขาอาจจะพินิจพิเคราะห์ดูได้ แม้ว่าเขาเป็นวงศ์วานที่มักกบฏ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 4, 'เจ้าจงเอาข้าวของของเจ้าออกมาในเวลากลางวันท่ามกลางสายตาของเขา เหมือนข้าวของเพื่อการถูกกวาดไปเป็นเชลย เจ้าจงออกไปในเวลาเย็นท่ามกลางสายตาของเขา ออกไปอย่างผู้ถูกกวาดไปเป็นเชลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 5, 'จงเจาะกําแพงท่ามกลางสายตาของเขา แล้วออกไปตามรูกําแพงนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 6, 'จงยกข้าวของใส่บ่าของเจ้าท่ามกลางสายตาของเขา แล้วแบกออกไปในเวลามืด เจ้าจงคลุมหน้าเสีย อย่าให้เห็นแผ่นดิน เพราะเรากระทําเจ้าให้เป็นหมายสําคัญแก่วงศ์วานอิสราเอล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 7, 'ข้าพเจ้าก็กระทําตามที่ข้าพเจ้ารับบัญชามา ข้าพเจ้านําข้าวของออกมาในเวลากลางวัน เหมือนข้าวของเพื่อการถูกกวาดไปเป็นเชลย ในเวลาเย็นข้าพเจ้าก็เจาะกําแพงด้วยมือของข้าพเจ้าเอง ข้าพเจ้าออกไปในเวลามืด แบกสัมภาระของข้าพเจ้าไปท่ามกลางสายตาของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 8, 'ในเวลาเช้า พระวจนะของพระเยโฮวาห์มาถึงข้าพเจ้าว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 9, '“บุตรแห่งมนุษย์เอ๋ย วงศ์วานอิสราเอลคือวงศ์วานที่มักกบฏนั้น ได้พูดกับเจ้ามิใช่หรือว่า ‘เจ้าทําอะไร’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 10, 'จงกล่าวแก่เขาว่า ‘องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า ภาระเกี่ยวกับเจ้านายคนนั้นในเยรูซาเล็ม และวงศ์วานอิสราเอลทั้งหมดซึ่งอยู่ในนครนั้น’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 11, 'จงกล่าวว่า ‘ข้าพเจ้าเป็นหมายสําคัญสําหรับท่าน ที่ข้าพเจ้าได้กระทําแล้วนี้ เขาทั้งหลายจะถูกกระทําอย่างเดียวกัน เขาจะถูกกวาดไปเป็นเชลย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 12, 'และเจ้านายคนนั้นผู้อยู่ท่ามกลางเขา จะยกข้าวของขึ้นใส่บ่าในเวลามืดและออกไป เขาทั้งหลายจะเจาะกําแพงและนําออกไปทางนั้น ท่านจะคลุมหน้าของท่าน เพื่อว่าท่านจะไม่แลเห็นแผ่นดินด้วยตาของท่านเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 13, 'และเราจะกางข่ายของเราคลุมท่าน และท่านจะติดกับของเรา และเราจะนําท่านเข้าไปในบาบิโลนแผ่นดินของคนเคลเดีย ถึงกระนั้นท่านจะยังแลไม่เห็นแผ่นดินนั้น และท่านจะต้องตายที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 14, 'บรรดาผู้ที่อยู่รอบท่านนั้น เราจะกระจายเขาไปตามลมทุกทิศานุทิศ รวมทั้งผู้ช่วยและบรรดากองทัพของท่านด้วย และเราจะชักดาบออกไล่ตามเขาไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 15, 'และเมื่อเราให้เขากระจัดกระจายไปอยู่ท่ามกลางประชาชาติ และกระจายเขาไปตามประเทศต่างๆ เขาจึงจะทราบว่าเราคือพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 16, 'แต่เราจะละบางคนในพวกเขาไว้จากดาบ จากการกันดารอาหาร และจากโรคระบาด เพื่อเขาจะได้เล่าถึงการกระทําอันน่าสะอิดสะเอียนทั้งสิ้นของเขาท่ามกลางประชาชาติซึ่งเขาไปอยู่นั้น และเขาจะทราบว่าเราคือพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 17, 'พระวจนะของพระเยโฮวาห์มาถึงข้าพเจ้าอีกว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 18, '“บุตรแห่งมนุษย์เอ๋ย จงรับประทานอาหารของเจ้าด้วยตัวสั่น และดื่มน้ําด้วยความสะทกสะท้านและด้วยความระมัดระวัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 19, 'และกล่าวแก่ประชาชนของแผ่นดินนั้นว่า องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้เกี่ยวกับพลเมืองแห่งกรุงเยรูซาเล็มและเกี่ยวกับแผ่นดินอิสราเอลว่า เขาจะรับประทานอาหารของเขาด้วยความระมัดระวัง และดื่มน้ําด้วยอกสั่นขวัญหาย เพราะว่าสารพัดที่มีอยู่ในแผ่นดินของเขาจะสูญหายไปหมด เนื่องด้วยความรุนแรงของคนทั้งปวงที่อยู่ในแผ่นดินนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 20, 'และเมืองที่มีคนอาศัยอยู่จะถูกทิ้งไว้เสียเปล่า และแผ่นดินนั้นก็จะรกร้าง และเจ้าจะทราบว่าเราคือพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 21, 'พระวจนะของพระเยโฮวาห์มาถึงข้าพเจ้าว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 22, '“บุตรแห่งมนุษย์เอ๋ย สุภาษิตซึ่งเจ้าทั้งหลายมีที่กล่าวถึงแผ่นดินอิสราเอลว่า ‘วันนั้นก็ไกลออกไป และนิมิตทุกเรื่องก็เหลว’ นั้น เจ้าหมายว่ากระไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 23, 'เพราะฉะนั้นจงบอกเขาว่า ‘องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า เราจะให้สุภาษิตบทนี้สิ้นสุดเสียที เขาจะไม่ใช้เป็นสุภาษิตอีกในอิสราเอล แต่จงกล่าวแก่เขาว่า วันนั้นก็ใกล้แค่คืบ และนิมิตทุกเรื่องก็จะสําเร็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 24, 'เพราะจะไม่มีนิมิตปลอมหรือคําทํานายประจบประแจงในวงศ์วานอิสราเอลอีกเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 25, 'แต่เราคือพระเยโฮวาห์จะพูดคําที่เราจะพูด และจะต้องเป็นไปตามคํานั้น จะไม่ล่าช้าต่อไปอีก แต่องค์พระผู้เป็นเจ้าพระเจ้าตรัสว่า โอ วงศ์วานที่มักกบฏเอ๋ย ในสมัยของเจ้านี่แหละ เราจะลั่นวาจาและจะกระทําตามนั้น’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 26, 'พระวจนะของพระเยโฮวาห์มายังข้าพเจ้าอีกว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 27, '“ดูเถิด บุตรแห่งมนุษย์เอ๋ย วงศ์วานของอิสราเอลกล่าวว่า ‘นิมิตที่เขาเห็นเป็นเรื่องของอีกหลายวันข้างหน้า และเขาพยากรณ์ถึงเวลาที่ห่างไกลโน้น’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 28, 'เพราะฉะนั้นจงกล่าวแก่เขาว่า องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า บรรดาถ้อยคําของเราจะไม่ล่าช้าอีกต่อไปเลย แต่วาจาที่เราลั่นออกมานั้นจะต้องเป็นไปจริง องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้แหละ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 1, 'พระวจนะของพระเยโฮวาห์มาถึงข้าพเจ้าว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 2, '“บุตรแห่งมนุษย์เอ๋ย เจ้าจงพยากรณ์กล่าวโทษผู้พยากรณ์ของอิสราเอลที่พยากรณ์ และกล่าวแก่คนเหล่านั้นที่พยากรณ์ตามอําเภอใจของตนว่า ‘จงฟังพระวจนะของพระเยโฮวาห์’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 3, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า วิบัติแก่ผู้พยากรณ์โฉดเขลา ผู้ติดตามวิญญาณของตนเอง และไม่เคยได้เห็นอะไรเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 4, 'โอ อิสราเอลเอ๋ย ผู้พยากรณ์ของเจ้าเหมือนสุนัขจิ้งจอกท่ามกลางสิ่งปรักหักพัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 5, 'เจ้าไม่ได้ขึ้นไปถึงที่ชํารุด และไม่ได้สร้างรั้วต้นไม้เพื่อวงศ์วานอิสราเอล เพื่อให้ตั้งอยู่ได้ในสงครามในวันแห่งพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 6, 'เขาทั้งหลายเห็นนิมิตเท็จและทํานายมุสา เขากล่าวว่า ‘พระเยโฮวาห์ตรัสว่า’ ในเมื่อพระเยโฮวาห์มิได้ทรงใช้เขาไป เขาทําให้คนอื่นหวังว่าเขาจะรับรองถ้อยคําของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 7, 'เจ้าได้เคยเห็นนิมิตเท็จ และเคยทํานายมุสามิใช่หรือ ในเมื่อเจ้ากล่าวว่า ‘พระเยโฮวาห์ตรัสว่า’ ทั้งที่เรามิได้พูดเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 8, 'เพราะฉะนั้นองค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า “เพราะเจ้ากล่าวเท็จและได้เห็นนิมิตมุสา องค์พระผู้เป็นเจ้าพระเจ้าตรัสว่า เพราะฉะนั้นดูเถิด เราเป็นปฏิปักษ์กับเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 9, 'มือของเราจะต่อสู้ผู้พยากรณ์ผู้เห็นนิมิตเท็จและผู้ให้คําทํานายมุสา เขาจะไม่ได้เข้าอยู่ในสภาแห่งประชาชนของเรา หรือขึ้นทะเบียนอยู่ในทะเบียนของวงศ์วานอิสราเอล และเขาจะไม่ได้เข้าในแผ่นดินอิสราเอล และเจ้าจะทราบว่าเราคือองค์พระผู้เป็นเจ้าพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 10, 'เพราะว่า เออ เพราะว่าเขาทั้งหลายได้นําประชาชนของเราให้หลง โดยกล่าวว่า ‘สันติภาพ’ เมื่อไม่มีสันติภาพเลย และเพราะว่าเมื่อมีคนสร้างกําแพง ดูเถิด คนอื่นก็ฉาบด้วยปูนขาว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 11, 'จงกล่าวแก่ผู้ที่ฉาบปูนขาวนั้นว่า กําแพงนั้นจะพัง จะมีฝนตกท่วม และเจ้า โอ ลูกเห็บใหญ่เอ๋ย จะตกลงมา และลมพายุจะฉีกมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 12, 'ดูเถิด เมื่อกําแพงพังลง เขาจะไม่พูดกับท่านหรือว่า ‘ปูนขาวที่เจ้าได้ฉาบนั้นอยู่ที่ไหนเล่า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 13, 'เพราะฉะนั้นองค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า เราจะกระทําให้ลมพายุฉีกมันด้วยความกริ้วของเรา และด้วยความโกรธของเราจะมีฝนท่วม ด้วยความกริ้วของเราจะมีลูกเห็บใหญ่ทําลายเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 14, 'และเราจะพังกําแพงซึ่งเจ้าฉาบด้วยปูนขาวนั้น และให้พังลงถึงดิน รากกําแพงนั้นจึงจะปรากฏ เมื่อกําแพงพัง เจ้าทั้งหลายจะพินาศอยู่ที่กลางกําแพง และเจ้าจะทราบว่าเราคือพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 15, 'เราจะให้ความพิโรธของเราสําเร็จบนกําแพงและบนคนเหล่านั้นที่ฉาบกําแพงด้วยปูนขาว และเราจะพูดกับเจ้าว่า ‘กําแพงไม่มีอีกแล้ว ผู้ที่ฉาบปูนขาวก็ไม่มีด้วย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 16, 'คือผู้พยากรณ์แห่งอิสราเอลซึ่งพยากรณ์เกี่ยวถึงกรุงเยรูซาเล็มและได้เห็นนิมิตแห่งสันติภาพของเมืองนั้น ในเมื่อไม่มีสันติภาพ องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 17, 'เจ้า บุตรแห่งมนุษย์เอ๋ย เจ้าจงมุ่งหน้าต่อสู้บรรดาบุตรสาวแห่งชนชาติของเจ้า ผู้พยากรณ์ตามอําเภอใจของตนเอง จงพยากรณ์กล่าวโทษเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 18, 'และกล่าวว่า องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า วิบัติแห่งหญิงที่เย็บปลอกไสยศาสตร์สําหรับใส่ช่องแขนเสื้อทั้งสิ้น และทําผ้าคลุมศีรษะให้คนทุกขนาดเพื่อล่าวิญญาณ เจ้าจะล่าวิญญาณซึ่งเป็นของประชาชนของเรา และจะรักษาวิญญาณอื่นๆให้คงชีวิตอยู่เพื่อผลกําไรของเจ้าหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 19, 'เจ้าจะกระทําให้เรามัวหมองท่ามกลางประชาชนของเรา ด้วยเห็นแก่ข้าวบาร์เลย์เพียงหลายกํามือ และขนมปังเพียงหลายชิ้น เพื่อสังหารคนที่ไม่สมควรจะตาย และไว้ชีวิตคนที่ไม่ควรจะมีชีวิตอยู่ โดยการมุสาของเจ้าต่อประชาชนของเราที่ฟังคํามุสานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 20, 'ด้วยเหตุนี้ องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า ดูเถิด เราต่อสู้ปลอกไสยศาสตร์ของเจ้า ซึ่งเจ้าใช้ล่าวิญญาณเพื่อให้เขาบินไป และเราจะฉีกปลอกไสยศาสตร์นั้นเสียจากแขนของเจ้าทั้งหลาย และเราจะปล่อยวิญญาณเหล่านั้นไป คือวิญญาณที่เจ้าล่าเพื่อให้เขาบินไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 21, 'ผ้าคลุมของเจ้าเราก็จะฉีกเสียด้วย และช่วยประชาชนของเราให้พ้นจากมือของเจ้า และเขาจะไม่เป็นเหยื่อในมือของเจ้าต่อไป และเจ้าจะทราบว่าเราคือพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 22, 'เพราะเจ้าได้กระทําให้คนชอบธรรมท้อใจด้วยการมุสา ทั้งที่เราไม่ได้กระทําให้เขาเศร้าใจเลย และเจ้าได้ทําให้มือของคนชั่วแข็งแรงขึ้น เพื่อมิให้เขาหันกลับจากทางชั่วของเขา โดยสัญญาว่าเขาจะได้ชีวิตรอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 23, 'เพราะฉะนั้นเจ้าจะไม่ได้เห็นเรื่องเหลวไหลหรือทํานายเหตุการณ์ในอนาคตอีก ด้วยว่าเราจะช่วยประชาชนของเราให้พ้นจากมือของเจ้า แล้วเจ้าจะทราบว่าเราคือพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 1, 'พวกผู้ใหญ่ของอิสราเอลบางคนมาหาข้าพเจ้า และมานั่งอยู่หน้าข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 2, 'และพระวจนะของพระเยโฮวาห์มาถึงข้าพเจ้าว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 3, '“บุตรแห่งมนุษย์เอ๋ย คนเหล่านี้ได้ยึดเอารูปเคารพของเขาไว้ในใจ และวางสิ่งที่สะดุดให้ทําความชั่วช้าไว้ข้างหน้าเขา ควรที่เราจะยอมตัวให้เขาถามเราหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 4, 'เพราะฉะนั้นจงพูดกับเขาและกล่าวแก่เขาว่า องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า คนใดในวงศ์วานอิสราเอลเอารูปเคารพของเขาไว้ในใจ และวางสิ่งที่สะดุดให้ทําความชั่วช้าไว้ข้างหน้าเขาและยังมาหาผู้พยากรณ์ เราคือพระเยโฮวาห์จะตอบเขาเองด้วยเรื่องรูปเคารพมากมายของเขานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 5, 'เพื่อเราจะได้ยึดจิตใจของวงศ์วานอิสราเอล ผู้เหินห่างไปจากเราทุกคนด้วยเรื่องรูปเคารพของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 6, 'เพราะฉะนั้นจงกล่าวแก่วงศ์วานอิสราเอลว่า องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า จงกลับใจและหันกลับจากรูปเคารพของเจ้าเสีย และจงหันหน้าของเจ้าเสียจากบรรดาสิ่งที่น่าสะอิดสะเอียนของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 7, 'เพราะว่าคนใดในวงศ์วานอิสราเอล หรือคนต่างด้าวคนใดที่อาศัยอยู่ในอิสราเอล ผู้ซึ่งแยกตัวเขาจากเรา ยึดเอารูปเคารพของเขาไว้ในใจของเขา และวางสิ่งที่สะดุดให้ทําความชั่วช้าไว้ตรงหน้าของเขา แล้วยังจะมาหาผู้พยากรณ์เพื่อขอถามเขาเกี่ยวกับเรา เราคือพระเยโฮวาห์จะตอบเขาเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 8, 'และเราจะมุ่งหน้าของเราต่อสู้คนนั้น เราจะทําให้เขาเป็นหมายสําคัญและเป็นคําภาษิต และจะตัดเขาออกเสียจากท่ามกลางประชาชนของเรา และเจ้าจะทราบว่าเราคือพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 9, 'และถ้าผู้พยากรณ์ถูกหลอกลวงกล่าวคําหนึ่งคําใด เราคือพระเยโฮวาห์ได้ลวงผู้พยากรณ์คนนั้น และเราจะเหยียดมือของเราออกต่อสู้เขา และจะทําลายเขาเสียจากท่ามกลางอิสราเอลประชาชนของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 10, 'เขาทั้งหลายจะต้องทนรับโทษเพราะความชั่วช้าของเขา โทษของผู้พยากรณ์และโทษของผู้ขอถามจะเหมือนกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 11, 'เพื่อว่าวงศ์วานอิสราเอลจะไม่หลงเจิ่นไปจากเราอีก หรือไม่กระทําตัวให้มลทินด้วยการละเมิดทั้งหลายของตนอีก แต่เขาทั้งหลายจะเป็นประชาชนของเรา และเราจะเป็นพระเจ้าของเขา องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 12, 'และพระวจนะของพระเยโฮวาห์มาถึงข้าพเจ้าอีกว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 13, '“บุตรแห่งมนุษย์เอ๋ย เมื่อแผ่นดินกระทําบาปต่อเราโดยประพฤติละเมิดอย่างน่าเศร้าใจ เราก็จะเหยียดมือของเราออกเหนือแผ่นดินนั้น และจะทําลายอาหารหลักเสีย และจะส่งการกันดารอาหารมาเหนือแผ่นดินนั้น และจะตัดมนุษย์และสัตว์ออกเสียจากแผ่นดินนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 14, 'ถึงแม้ว่ามนุษย์ทั้งสามนี้ คือ โนอาห์ ดาเนียล และโยบ อยู่ในแผ่นดินนั้น เขาก็จะเอาแต่ชีวิตของตนให้พ้นเท่านั้น ออกมาด้วยความชอบธรรมของเขา องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 15, 'ถ้าเรากระทําให้สัตว์ร้ายทั้งหลายผ่านแผ่นดินนั้น และพวกมันทําให้แผ่นดินเสียไป เพื่อให้เป็นที่รกร้าง จนไม่มีผู้ใดผ่านเข้าไปได้เพราะสัตว์ร้ายนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 16, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสว่า เรามีชีวิตอยู่แน่ฉันใด แม้ว่าบุรุษทั้งสามอยู่ในแผ่นดินนั้น เขาทั้งหลายจะช่วยบุตรชายหญิงให้รอดพ้นไม่ได้ เฉพาะตัวเขาเองจะรอดพ้นไปได้ แต่แผ่นดินนั้นจะรกร้างเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 17, 'หรือถ้าเรานําดาบมาเหนือแผ่นดินนั้น และกล่าวว่า ‘ดาบเอ๋ย จงผ่านแผ่นดินนั้นไปโดยตลอด’ เพื่อเราจะตัดมนุษย์และสัตว์ออกเสียจากแผ่นดินนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 18, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสว่า แม้บุรุษทั้งสามจะอยู่ในนั้น เรามีชีวิตอยู่แน่ฉันใด เขาทั้งหลายจะช่วยบุตรทั้งชายหญิงให้รอดพ้นไม่ได้ เฉพาะตัวเขาเองจะรอดพ้นไปได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 19, 'หรือถ้าเราส่งโรคระบาดเข้ามาในแผ่นดินนั้น และเทความเดือดดาลของเราออกเหนือเมืองนั้นด้วยโลหิต เพื่อตัดมนุษย์และสัตว์ออกเสียจากแผ่นดินนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 20, 'ถึงแม้ว่า โนอาห์ ดาเนียลและโยบอยู่ในแผ่นดินนั้น องค์พระผู้เป็นเจ้าพระเจ้าตรัสว่า เรามีชีวิตอยู่แน่ฉันใด เขาทั้งหลายจะช่วยบุตรทั้งชายหญิงให้รอดพ้นไม่ได้ เขาจะช่วยเฉพาะชีวิตของเขาให้รอดพ้นได้ด้วยความชอบธรรมของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 21, 'เพราะองค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า จะรุนแรงยิ่งกว่านั้นสักเท่าใด เมื่อเราส่งการพิพากษาอันร้ายกาจทั้งสี่ประการของเรามาเหนือกรุงเยรูซาเล็ม คือดาบ การกันดารอาหาร สัตว์ร้ายและโรคระบาด เพื่อตัดมนุษย์และสัตว์ออกเสียจากเมืองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 22, 'ดูเถิด แม้จะมีคนรอดตายเหลืออยู่ในนครนั้น นําเอาบุตรชายและบุตรสาวทั้งหลายของเขาออกมา ดูเถิด เมื่อเขาทั้งหลายออกมาหาเจ้า เจ้าจะได้เห็นทางและการกระทําของเขา เจ้าจะเบาใจในเรื่องการร้าย ซึ่งเราได้นํามาเหนือเยรูซาเล็ม คือบรรดาสิ่งที่เราได้นํามาเหนือนครนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 23, 'คนเหล่านั้นจะทําให้เจ้าเบาใจ เมื่อเจ้าได้เห็นทางและการกระทําทั้งหลายของเขาแล้ว และเจ้าจะทราบว่า เรามิได้กระทําบรรดาสิ่งที่เราได้กระทําไว้แล้วในนครนั้นด้วยปราศจากเหตุผล องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้แหละ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 1, 'พระวจนะของพระเยโฮวาห์มาถึงข้าพเจ้าว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 2, '“บุตรแห่งมนุษย์เอ๋ย ต้นเถาองุ่นวิเศษกว่าต้นไม้อื่น และวิเศษกว่าไม้กิ่งหนึ่งซึ่งอยู่ท่ามกลางต้นไม้ในป่าหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 3, 'เขาเอาไม้ต้นเถาองุ่นไปทําอะไรบ้างหรือ คนเอาไปทําขอสําหรับแขวนภาชนะอันใดหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 4, 'ดูเถิด เขาใช้เป็นฟืนใส่ไฟ เมื่อไฟไหม้ปลายทั้งสองแล้ว กลางก็เป็นถ่าน จะใช้ประโยชน์อะไรได้หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 5, 'ดูเถิด เมื่อมันยังดีอยู่ก็มิได้ใช้ประโยชน์อะไร เมื่อถูกไฟไหม้เป็นถ่านแล้วยิ่งมีประโยชน์น้อยลง จะใช้ทําอะไรได้บ้างเล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 6, 'เพราะฉะนั้นองค์พระผู้เป็นเจ้าพระเจ้าจึงตรัสดังนี้ว่า ต้นเถาองุ่นซึ่งอยู่ท่ามกลางต้นไม้ในป่า เราทิ้งให้มันเป็นฟืนใส่ไฟเสียฉันใด เราจะทิ้งชาวเยรูซาเล็มฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 7, 'เราจะมุ่งหน้าของเราต่อสู้เขา แม้ว่าเขาจะหนีออกจากไฟอันหนึ่ง ไฟอีกอันหนึ่งก็ยังจะเผาผลาญเขา และเมื่อเรามุ่งหน้าของเราต่อสู้เขา เจ้าจะทราบว่า เราคือพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 8, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสว่า เราจะกระทําให้แผ่นดินนั้นรกร้างไป เพราะเขาได้ประพฤติละเมิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 1, 'พระวจนะของพระเยโฮวาห์มายังข้าพเจ้าอีกว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 2, '“บุตรแห่งมนุษย์เอ๋ย จงให้เยรูซาเล็มทราบถึงสิ่งที่น่าสะอิดสะเอียนของตัวเธอเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 3, 'และกล่าวว่า องค์พระผู้เป็นเจ้าพระเจ้าตรัสอย่างนี้แก่เยรูซาเล็มว่า ดั้งเดิมและกําเนิดของเจ้าเป็นแผ่นดินของคนคานาอัน พ่อของเจ้าเป็นคนอาโมไรต์ และแม่ของเจ้าเป็นคนฮิตไทต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 4, 'พูดถึงกําเนิดของเจ้า ในวันที่เจ้าเกิดมานั้นเขามิได้ตัดสายสะดือ และเขาก็มิได้ใช้น้ําล้างชําระเจ้า มิได้เอาเกลือถู มิได้เอาผ้าพันเจ้าไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 5, 'ไม่มีตาสักดวงหนึ่งสงสารเจ้า ที่จะเมตตาเจ้าและกระทําสิ่งเหล่านี้ให้เจ้า เจ้าถูกทอดทิ้งในพื้นทุ่ง เพราะในวันที่เจ้าเกิดนั้นเจ้าเป็นที่รังเกียจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 6, 'และเมื่อเราผ่านเจ้าไป เห็นเจ้าดิ้นกระแด่วๆอยู่ในกองโลหิตของเจ้า เราก็พูดกับเจ้าในกองโลหิตของเจ้าว่า ‘จงมีชีวิตอยู่’ เออ เราก็พูดกับเจ้าในกองโลหิตของเจ้าว่า ‘จงมีชีวิตอยู่’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 7, 'เราได้กระทําให้เจ้าทวีคูณเหมือนอย่างพืชในท้องนา เจ้าก็เติบโตและสูงขึ้นจนเป็นสาวเต็มตัว ถันของเจ้าก็ก่อรูปขึ้นมา และขนของเจ้าก็งอก ทั้งๆที่เจ้าเคยเปลือยเปล่าและล่อนจ้อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 8, 'และเมื่อเราผ่านเจ้าไปอีกครั้งหนึ่งและมองดูเจ้า ดูเถิด เจ้ามีอายุรู้จักรักแล้ว เราก็ขยายชายเสื้อคลุมเจ้าและปกคลุมความเปลือยเปล่าของเจ้าไว้ องค์พระผู้เป็นเจ้าพระเจ้าตรัสว่า เออ เราก็ปฏิญาณและกระทําพันธสัญญากับเจ้า และเจ้าก็เป็นของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 9, 'และเราก็เอาเจ้าอาบน้ํา ล้างโลหิตเสียจากเจ้า และเจิมเจ้าด้วยน้ํามัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 10, 'เราแต่งตัวเจ้าด้วยเสื้อปัก และเอารองเท้าหนังของแบดเจอร์สวมให้เจ้า เราพันเจ้าไว้ด้วยผ้าป่านเนื้อละเอียด และคลุมเจ้าไว้ด้วยผ้าไหม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 11, 'เราแต่งตัวเจ้าด้วยเครื่องอาภรณ์ สวมกําไลมือให้เจ้า และสวมสร้อยคอให้เจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 12, 'เราเอาเพชรพลอยเม็ดหนึ่งใส่หน้าผากเจ้า และใส่ตุ้มหูที่หูของเจ้า และสวมมงกุฎงามไว้บนศีรษะของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 13, 'เราก็ประดับเจ้าด้วยทองคําและเงิน และเสื้อผ้าของเจ้าก็เป็นผ้าป่านเนื้อละเอียด ผ้าไหมและผ้าปัก เจ้ากินยอดแป้ง น้ําผึ้งและน้ํามัน เจ้างามเลิศทีเดียว และเจ้าเจริญขึ้นเป็นชั้นจ้าว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 14, 'ชื่อเสียงของเจ้าก็ลือไปท่ามกลางประชาชาติเพราะความงามของเจ้า ด้วยความงามนั้นก็สมบูรณ์ทีเดียว เนื่องจากความสง่างามที่เราได้ทุ่มเทให้เจ้า องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 15, 'แต่เจ้าวางใจในความงามของเจ้า และได้เล่นชู้เพราะชื่อเสียงของเจ้า ไม่ว่าผู้ใดจะผ่านมา เจ้าก็ให้หลงระเริงไปด้วยการเล่นชู้ของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 16, 'เจ้าเอาเสื้อผ้าของเจ้าบ้าง และประดับบรรดาปูชนียสถานสูงของเจ้าด้วยเสื้อผ้าหลากสี แล้วก็เล่นชู้อยู่บนนั้น ไม่เคยมีเหมือนอย่างนี้ ต่อไปก็ไม่มีเหมือนเช่นกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 17, 'เจ้ายังเอาเครื่องรูปพรรณอันงามของเจ้า ซึ่งเป็นทองคําของเราและเงินของเรา ซึ่งเราได้ให้แก่เจ้า แล้วเจ้าสร้างเป็นรูปผู้ชายสําหรับเจ้า และเจ้าก็เล่นชู้อยู่กับรูปเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 18, 'เจ้าเอาเครื่องแต่งตัวที่ปักไปห่มรูปเหล่านั้นไว้ และวางน้ํามันและเครื่องหอมของเราไว้ข้างหน้ามัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 19, 'อาหารที่เราให้แก่เจ้าก็เหมือนกัน คือเราเลี้ยงเจ้าด้วยยอดแป้ง น้ํามันและน้ําผึ้ง เจ้าก็เอามาวางข้างหน้ามัน ให้เป็นกลิ่นหอมที่พึงใจ และก็เป็นอย่างนั้น องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 20, 'ยิ่งกว่านั้นอีก เจ้าได้นําบุตรชายของเจ้าและบุตรสาวของเจ้า ซึ่งเจ้าได้ให้บังเกิดมาเพื่อเรา และเจ้าก็ได้ถวายบูชาแก่มันเพื่อให้มันเผาผลาญ การเล่นชู้ของเจ้าเป็นสิ่งเล็กน้อยอยู่หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 21, 'เจ้าจึงได้ฆ่าลูกของเราถวายแก่รูปเหล่านั้นโดยให้ลุยไฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 22, 'และในการอันน่าสะอิดสะเอียนของเจ้าและการเล่นชู้ของเจ้า เจ้ามิได้ระลึกถึงวันที่เจ้ายังเด็กอยู่เมื่อเจ้าเปลือยเปล่าและล่อนจ้อน และมัวหมองอยู่ในกองเลือดของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 23, 'ต่อมาภายหลังจากความชั่วร้ายทั้งสิ้นของเจ้า (องค์พระผู้เป็นเจ้าพระเจ้าตรัสว่า วิบัติ วิบัติแก่เจ้า)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 24, 'เจ้าได้สร้างห้องหลังคาโค้งสําหรับตัว ถนนทุกสายเจ้าก็สร้างสถานที่สูงสําหรับตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 25, 'หัวถนนทุกแห่งเจ้าสร้างที่สูงของเจ้า และเอาความงามของเจ้ามาทําลามก อ้าเท้าของเจ้าให้ผู้ที่ผ่านไปมาไม่ว่าใคร และทวีการเล่นชู้ของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 26, 'เจ้าได้เล่นชู้กับคนอียิปต์ ซึ่งเป็นเพื่อนบ้านที่มักมากของเจ้า ทวีการเล่นชู้ของเจ้าเพื่อกระทําให้เรากริ้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 27, 'ดูเถิด เราจึงเหยียดมือของเราออกต่อสู้เจ้า และลดอาหารส่วนแบ่งของเจ้าลง และมอบเจ้าไว้ให้แก่พวกที่เกลียดเจ้าให้เขากระทําตามใจชอบ คือบรรดาบุตรสาวคนฟีลิสเตีย ผู้ซึ่งละอายในความประพฤติอันลามกของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 28, 'เจ้ายังเล่นชู้กับคนอัสซีเรียด้วย เพราะว่าเจ้าไม่รู้จักอิ่ม เออ เจ้าเล่นชู้กับเขาทั้งหลาย ถึงกระนั้นเจ้าก็ยังไม่อิ่มใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 29, 'เจ้ายังทวีการเล่นชู้ของเจ้าในแผ่นดินคานาอันกับคนเคลเดีย ถึงแม้กับแผ่นดินนี้เจ้าก็ยังไม่อิ่มใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 30, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสว่า แหมใจของเจ้าช่างอ่อนแอเสียจริงๆในเมื่อเจ้ากระทําบรรดาสิ่งเหล่านี้ ซึ่งเป็นการกระทําของหญิงแพศยาที่หยิ่งยโส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 31, 'คือสร้างห้องหลังคาโค้งไว้ที่หัวถนนทุกแห่ง และสร้างสถานที่สูงของเจ้าไว้ตามถนนทุกสาย ถึงกระนั้นเจ้าก็ยังไม่เหมือนหญิงแพศยา เพราะเจ้าดูหมิ่นสินจ้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 32, 'เป็นภรรยาที่แพศยาจัด ดูซิ ยอมรับรองแขกแปลกหน้าแทนที่จะรับรองสามี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 33, 'ผู้ชายย่อมให้ของแก่หญิงแพศยาทุกคน แต่เจ้ากลับให้สิ่งของแก่คนรักทั้งหลายของเจ้าทุกคน ให้สินบนชักให้เขาเข้ามาจากทุกด้านเพื่อการเล่นชู้ของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 34, 'ฉะนั้น เจ้าจึงผิดกับหญิงอื่นในเรื่องการเล่นชู้ของเจ้า ไม่มีใครมาวิงวอนให้เล่นชู้และเจ้ากลับให้สินจ้าง ขณะเมื่อไม่มีผู้ใดให้สินจ้างแก่เจ้า เพราะฉะนั้นเจ้าจึงแตกต่างกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 35, 'เหตุฉะนี้ โอ แพศยาเอ๋ย จงฟังพระวจนะของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 36, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า เพราะความโสโครกของเจ้าก็เทออกเสียแล้ว และการเปลือยเปล่าของเจ้าก็เผยออก โดยการเล่นชู้ของเจ้ากับคนรักของเจ้า และกับบรรดารูปเคารพซึ่งเป็นสิ่งที่น่าสะอิดสะเอียนของเจ้า และโดยโลหิตลูกของเจ้าที่เจ้าถวายให้แก่มัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 37, 'เพราะฉะนั้น ดูเถิด เราจะรวบรวมคนรักของเจ้าทั้งสิ้น ซึ่งเป็นผู้ที่เจ้าเพลิดเพลินด้วย ทุกคนที่เจ้ารัก และทุกคนที่เจ้าเกลียด เราจะรวบรวมเขาให้มาต่อสู้เจ้าจากทุกด้านและจะเผยความเปลือยเปล่าของเจ้าต่อหน้าเขา เพื่อเขาจะได้เห็นความเปลือยเปล่าทั้งสิ้นของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 38, 'และเราจะพิพากษาเจ้าดังที่เขาพิพากษาหญิงที่ล่วงประเวณี และกระทําให้โลหิตตก และเราจะนําเอาโลหิตแห่งความกริ้วและความหวงแหนมาเหนือเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 39, 'และจะมอบเจ้าไว้ในมือชู้ของเจ้า เขาจะทําลายห้องหลังคาโค้งของเจ้าลง และจะทําลายสถานที่สูงของเจ้า เขาจะปลดเอาเสื้อผ้าของเจ้า และจะเอาเครื่องรูปพรรณอันงามของเจ้าไปเสีย ปล่อยให้เจ้าเปลือยเปล่าและล่อนจ้อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 40, 'เขาทั้งหลายจะนําฝูงคนมาต่อสู้เจ้า และเขาจะขว้างเจ้าด้วยก้อนหินและฟันเจ้าด้วยดาบของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 41, 'และเขาจะเอาไฟเผาบ้านเรือนของเจ้า และทําการพิพากษาลงโทษเจ้าท่ามกลางสายตาของผู้หญิงเป็นอันมาก เราจะกระทําให้เจ้าหยุดเล่นชู้ และเจ้าจะไม่ให้สินจ้างอีกต่อไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 42, 'เราจะระบายความกริ้วของเราใส่เจ้าให้หมด ความหวงแหนจะพรากจากเจ้าไป เราจะสงบและไม่กริ้วอีกเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 43, 'เพราะว่าเจ้ามิได้ระลึกถึงวันเมื่อเจ้ายังเด็ก แต่ได้กระทําให้เรากลัดกลุ้มด้วยสิ่งเหล่านี้ทั้งสิ้น องค์พระผู้เป็นเจ้าพระเจ้าตรัสว่า เพราะฉะนั้น ดูเถิด เราจะตอบสนองต่อวิถีทางของเจ้าเหนือศีรษะเจ้า แล้วเจ้าจะมิได้ประพฤติการชั่วช้าลามกเพิ่มเข้ากับการอันน่าสะอิดสะเอียนทั้งสิ้นของเจ้าหรอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 44, 'ดูเถิด ทุกคนที่ใช้สุภาษิตจะใช้สุภาษิตต่อไปนี้ในเรื่องเจ้า คือ ‘แม่เป็นอย่างไร ลูกสาวก็เป็นอย่างนั้น’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 45, 'เจ้าเป็นลูกสาวของแม่ของเจ้า ผู้เกลียดสามีและบุตรของตน เจ้าเป็นสาวคนกลางของพี่และน้องสาวของเจ้า ผู้เกลียดชังสามีและบุตรของตน แม่ของเจ้าเป็นคนฮิตไทต์ พ่อของเจ้าเป็นคนอาโมไรต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 46, 'และพี่สาวของเจ้าคือสะมาเรีย ผู้อยู่กับบุตรสาวเหนือเจ้าทางด้านซ้าย และน้องสาวของเจ้า ผู้อยู่ทางด้านขวาของเจ้า คือโสโดมกับลูกสาวของเธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 47, 'ถึงกระนั้น เจ้าก็ไม่ได้ดําเนินตามทางทั้งหลายของเขา หรือกระทําตามการอันน่าสะอิดสะเอียนของเขา แต่เพราะว่านั่นเป็นเรื่องเล็กน้อยเกินไปแล้ว แล้วเจ้าก็ทรามกว่าพวกเขาในบรรดาวิถีทางของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 48, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสว่า เรามีชีวิตอยู่แน่ฉันใด โสโดมน้องสาวของเจ้ากับบุตรสาวของเขาก็มิได้กระทําอย่างที่เจ้าและลูกสาวของเจ้าได้กระทํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 49, 'ดูเถิด นี่แหละเป็นความชั่วช้าของโสโดมน้องสาวของเจ้าคือตัวเธอและลูกสาวของเธอมีความจองหอง มีอาหารเหลือรับประทานและมีความสบายเกิน ไม่ชูกําลังมือคนยากจนและคนขัดสน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 50, 'เขาหยิ่งยโสและกระทําสิ่งน่าสะอิดสะเอียนต่อหน้าเรา เพราะฉะนั้นเราจึงเอาเขาออกไปเสียให้พ้นๆตามที่เราเห็นว่าดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 51, 'สะมาเรียไม่ได้ทําบาปถึงครึ่งของเจ้า แต่เจ้าได้ทวีการอันน่าสะอิดสะเอียนยิ่งกว่าเขาทั้งสอง และโดยการอันน่าสะอิดสะเอียนทั้งสิ้นที่เจ้าทํานั้น ก็กระทําให้พี่และน้องสาวของเจ้าดูเหมือนชอบธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 52, 'เจ้าผู้ซึ่งได้พิพากษาพี่และน้องสาวของเจ้า จงทนรับความอับอายของเจ้าเองด้วย เพราะบาปของเจ้าซึ่งเจ้าได้ทํานั้นน่าสะอิดสะเอียนยิ่งกว่าเขาเสียอีก เขาจึงมีความชอบธรรมมากกว่าเจ้า เออ เจ้าจงรับความขายหน้าไปด้วย และจงทนรับความอับอายของเจ้า เพราะเจ้าได้กระทําให้พี่และน้องสาวของเจ้าดูเหมือนชอบธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 53, 'เมื่อเราจะให้เขากลับสู่สภาพเดิม ทั้งสภาพเดิมของโสโดมและบุตรสาวและสภาพเดิมของสะมาเรียและบุตรสาว เราก็จะให้เจ้ากลับสู่สภาพเดิมของเจ้าท่ามกลางเขาด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 54, 'เพื่อเจ้าจะทนรับความอับอายขายหน้าของเจ้า และละอายสิ่งที่เจ้ากระทําแล้วทั้งสิ้นให้เป็นการปลอบใจแก่เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 55, 'เมื่อส่วนพี่และน้องสาวของเจ้า โสโดมกับบุตรสาวของเธอจะได้กลับสู่สภาวะเดิมของตน และสะมาเรียกับบุตรสาวของเธอจะกลับสู่สภาวะเดิมของตน ส่วนเจ้าและบุตรสาวของเจ้าจะกลับไปยังสภาวะเดิมของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 56, 'ในสมัยที่เจ้าเย่อหยิ่งอยู่นั้น ปากของเจ้าไม่ได้กล่าวถึงโสโดมน้องสาวของเจ้ามิใช่หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 57, 'คือก่อนความชั่วร้ายของเจ้าจะได้เผยออก เหมือนเวลาที่เจ้าเป็นสิ่งที่น่าตําหนิแก่บุตรสาวของซีเรียและบรรดาผู้ที่อยู่ล้อมรอบเธอ คือบุตรสาวของฟีลิสเตียผู้ที่อยู่ล้อมรอบซึ่งดูหมิ่นเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 58, 'เจ้าต้องรับโทษความชั่วช้าลามกของเจ้าและการอันน่าสะอิดสะเอียนของเจ้า พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 59, 'เพราะองค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า เราจะกระทําแก่เจ้าอย่างที่เจ้าได้กระทําแล้วนั้น ผู้ดูหมิ่นคําปฏิญาณและหักพันธสัญญา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 60, 'ถึงกระนั้นเราจะระลึกถึงพันธสัญญาของเรา ซึ่งเราทําไว้กับเจ้าในสมัยเมื่อเจ้ายังสาวอยู่ และเราจะสถาปนาพันธสัญญานิรันดร์ไว้กับเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 61, 'แล้วเจ้าจะระลึกถึงทางทั้งหลายของเจ้า และมีความละอาย เมื่อเจ้ารับทั้งพี่และน้องสาวของเจ้า และเรามอบให้แก่เจ้าเป็นบุตรสาว แต่ไม่ใช่ตามพันธสัญญาซึ่งทําไว้กับเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 62, 'เราจะสถาปนาพันธสัญญาของเราไว้กับเจ้า และเจ้าจะทราบว่าเราคือพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 63, 'เพื่อเจ้าจะจําได้และรับความขายหน้า และเพราะความอับอายของเจ้า เจ้าจะไม่อ้าปากพูดอีก เมื่อเราลบมลทินบาปทุกสิ่งที่เจ้าได้กระทํามาแล้ว องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 1, 'พระวจนะของพระเยโฮวาห์มายังข้าพเจ้าว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 2, '“บุตรแห่งมนุษย์เอ๋ย จงยกปริศนาและกล่าวเป็นคําอุปมาแก่วงศ์วานอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 3, 'ว่า องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า มีนกอินทรีมหึมาตัวหนึ่ง ปีกใหญ่และขนปีกก็ยาว มีขนมากมายหลายสี มายังเลบานอนและจิกยอดต้นสนสีดาร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 4, 'มันหักยอดกิ่งอ่อนแล้วก็คาบไปยังแผ่นดินพาณิชย์ และวางไว้ในหัวเมืองของพ่อค้าทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 5, 'แล้วมันก็เอาเมล็ดพืชแห่งแผ่นดินไปปลูกไว้ในที่ดินอุดม มันเอาเมล็ดไว้ข้างน้ํามากหลาย ตั้งไว้อย่างกับกิ่งต้นหลิว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 6, 'เมล็ดก็งอกขึ้นมาและเติบโตขึ้นเป็นเถาองุ่นเตี้ย แผ่แขนงไพศาล แขนงทั้งหลายของต้นนี้ก็ทอดมายังตัวนกอินทรี และรากก็ยังคงอยู่ใต้มัน เมล็ดจึงบังเกิดเป็นเถา แตกแขนงสาขาและออกใบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 7, 'แต่มีนกอินทรีตัวมหึมาอีกตัวหนึ่ง มีปีกใหญ่และมีขนมาก ดูเถิด องุ่นเถานั้นชอนรากมาหานกอินทรีตัวนี้ และแตกแขนงตรงมาที่มัน เพื่อให้มันรดน้ําให้จากร่องที่ปลูกอยู่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 8, 'นกได้ย้ายมันไปปลูกไว้ในที่ดินดีใกล้น้ํามากหลาย เพื่อให้แตกแขนงและบังเกิดผล และเป็นเถาองุ่นที่มีเกียรติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 9, 'เจ้าจงกล่าวว่า องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า เถานั้นจะเจริญขึ้นได้หรือ นกนั้นจะไม่ถอนรากมันขึ้นและเด็ดผลเพื่อให้เถาเหี่ยวแห้งเสียหรือ เถานั้นก็จะเหี่ยวแห้งไปตรงใบอ่อนที่งอกขึ้นแล้ว โดยไม่ต้องอาศัยอํานาจอันยิ่งใหญ่หรือประชาชนเป็นอันมากเพื่อถอนเถาออกจากรากของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 10, 'ดูเถิด เมื่อมันย้ายไปปลูก เถานั้นก็งอกงามดีหรือ เมื่อลมทิศตะวันออกพัดถูกมันเข้า มันจะไม่เหี่ยวแห้งไปหรือ มันจะเหี่ยวแห้งไปถึงร่องที่มันเกิดมานั้นไม่ใช่หรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 11, 'พระวจนะของพระเยโฮวาห์มายังข้าพเจ้าอีกว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 12, '“บัดนี้จงกล่าวแก่วงศ์วานที่มักกบฏนั้นว่า ท่านทั้งหลายไม่ทราบหรือว่า สิ่งเหล่านี้มีความหมายว่ากระไร จงบอกเขาว่า ดูเถิด กษัตริย์กรุงบาบิโลนได้มายังกรุงเยรูซาเล็ม และกวาดเอากษัตริย์และเจ้านายทั้งหลายพามายังกษัตริย์ที่กรุงบาบิโลน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 13, 'และพระองค์ได้ทรงเอาเชื้อพระวงศ์ผู้หนึ่งและทําพันธสัญญากับท่านผู้นั้นให้เขาปฏิญาณตัว คนสําคัญๆของแผ่นดิน พระองค์ได้กวาดต้อนเอาไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 14, 'เพื่อว่าราชอาณาจักรนั้นจะต่ําต้อย ยกตัวขึ้นอีกไม่ได้ และในการที่รักษาพันธสัญญาของพระองค์จะคงยั่งยืนอยู่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 15, 'แต่กษัตริย์ได้กบฏต่อพระองค์ โดยส่งราชทูตไปยังอียิปต์ ด้วยหวังว่าจะได้ม้าและกองทัพใหญ่โต กษัตริย์จะกระทําสําเร็จหรือ ผู้ที่กระทําเช่นนี้จะหนีไปรอดหรือ ถ้าท่านหักพันธสัญญายังจะรอดพ้นได้อีกหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 16, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสว่า เรามีชีวิตอยู่แน่ฉันใด ท่านจะต้องตายท่ามกลางบาบิโลน ในที่ที่กษัตริย์องค์นั้นประทับอยู่ คือกษัตริย์ผู้ได้ทรงตั้งท่านให้เป็นกษัตริย์ และท่านได้ดูหมิ่นคําปฏิญาณต่อพระองค์ และได้หักพันธสัญญาที่ทําไว้กับพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 17, 'ฟาโรห์ประกอบด้วยกองทัพอันใหญ่โตและผู้คนมากมายจะไม่ช่วยท่านผู้นั้น ในการสงคราม ในเมื่อเขาก่อเชิงเทินและก่อกําแพงล้อมเพื่อจะขจัดคนเป็นอันมากเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 18, 'เพราะเหตุท่านดูหมิ่นคําปฏิญาณโดยหักพันธสัญญา และดูเถิด เมื่อท่านปฏิญาณตัวและยังกระทําสิ่งทั้งปวงเหล่านี้ ท่านจึงจะหนีไปให้พ้นไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 19, 'เพราะฉะนั้นองค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า เรามีชีวิตอยู่ฉันใด เพราะคําปฏิญาณต่อเราที่เขาดูหมิ่นและพันธสัญญาของเราที่เขาหักเสีย เราจะตอบสนองให้ตกเหนือศีรษะของท่านผู้นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 20, 'เราจะกางข่ายของเราคลุมเขา และเขาจะติดกับของเรา และเราจะนําเขาเข้าไปในบาบิโลน และพิจารณาพิพากษาเขาที่นั่นในเรื่องการละเมิดที่เขาได้ละเมิดต่อเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 21, 'และบรรดาผู้ลี้ภัยกับกองทัพทั้งสิ้นของเขานั้นจะล้มลงด้วยดาบ และผู้ที่เหลืออยู่จะกระจายไปตามลมทุกทิศานุทิศ และเจ้าจะรู้ว่าเราคือพระเยโฮวาห์ที่ได้ลั่นวาจาไว้แล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 22, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า “เราเองจะเอาแขนงจากยอดสูงของต้นสนสีดาร์และปลูกไว้ เราจะหักกิ่งอ่อนของมันออกเสีย และเราเองจะปลูกมันไว้บนภูเขายอดสูง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 23, 'เราจะปลูกมันไว้บนภูเขาสูงของอิสราเอล เพื่อจะแตกกิ่งและบังเกิดผล และเป็นต้นสนสีดาร์ที่มีเกียรติ และนกทุกชนิดจะมาอาศัยอยู่ใต้มัน นกทุกอย่างจะมาทํารังอยู่ที่ร่มกิ่งของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 24, 'และต้นไม้ทุกต้นในทุ่งจะทราบว่าเราคือพระเยโฮวาห์กระทําต้นไม้สูงให้ต่ําลง และกระทําต้นไม้ต่ําให้สูงขึ้น ทําต้นไม้เขียวให้แห้งไป และทําต้นไม้แห้งให้งามสดชื่น เราคือพระเยโฮวาห์ได้ลั่นวาจาแล้ว เราได้กระทําเช่นนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 1, 'พระวจนะของพระเยโฮวาห์มายังข้าพเจ้าอีกว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 2, '“เจ้าทั้งหลายมีเจตนาอย่างไรในการกล่าวสุภาษิตข้อนี้อันเกี่ยวกับแผ่นดินอิสราเอลว่า ‘บิดารับประทานองุ่นเปรี้ยวและบุตรก็เข็ดฟัน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 3, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสว่า เรามีชีวิตอยู่แน่ฉันใด เจ้าทั้งหลายจะไม่มีโอกาสใช้สุภาษิตนี้อีกในอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 4, 'ดูเถิด ชีวิตทั้งสิ้นเป็นของเรา ชีวิตของบิดาเป็นของเราฉันใด ชีวิตของบุตรชายก็เป็นของเราฉันนั้น ชีวิตใดทําบาปก็จะตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 5, 'แต่ถ้าคนใดชอบธรรมและกระทําความยุติธรรมและความชอบธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 6, 'ถ้าคนนั้นมิได้รับประทานที่บนภูเขาหรือเงยหน้าขึ้นนมัสการรูปเคารพแห่งวงศ์วานอิสราเอล มิได้กระทําให้ภรรยาของเพื่อนบ้านมลทิน หรือเข้าใกล้ผู้หญิงในเวลาที่เธอมีมลทินประจําเดือน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 7, 'มิได้บีบบังคับผู้หนึ่งผู้ใด แต่คืนของประกันให้แก่ลูกหนี้ ไม่เคยใช้ความรุนแรงปล้นผู้ใด ให้อาหารของเขาแก่ผู้ที่หิว และให้เสื้อผ้าคลุมกายที่เปลือย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 8, 'มิได้ให้เขายืมเพื่อหาดอกเบี้ย หรือมิได้รับเงินเพิ่มหดมือไว้ ได้ถอนมือจากความชั่วช้า กระทําความยุติธรรมอันแท้จริงระหว่างมนุษย์กับมนุษย์ด้วยกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 9, 'ดําเนินตามกฎเกณฑ์ของเรา และรักษาคําตัดสินของเรา เพื่อประพฤติอย่างถูกต้อง คนนั้นเป็นคนชอบธรรม เขาจะมีชีวิตดํารงอยู่แน่ องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 10, 'ถ้าเขามีบุตรชายเป็นโจร ผู้กระทําให้โลหิตตก ผู้ได้กระทําสิ่งเหล่านี้สิ่งเดียวแก่พี่น้อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 11, 'ผู้มิได้กระทําตามหน้าที่เหล่านี้ แต่รับประทานบนภูเขา กระทําให้ภรรยาของเพื่อนบ้านมลทิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 12, 'กดขี่คนจนและคนขัดสน ได้ใช้ความรุนแรงแย่งชิงเอาของผู้อื่นไป ไม่ยอมคืนของประกัน แหงนตาขึ้นนมัสการรูปเคารพ และกระทําการอันน่าสะอิดสะเอียน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 13, 'ให้ยืมด้วยหาดอกเบี้ย และหาเงินเพิ่ม เขาควรจะมีชีวิตต่อไปหรือ เขาจะไม่มีชีวิตอยู่ เขาได้กระทําบรรดาสิ่งที่น่าสะอิดสะเอียนเหล่านี้ เขาจะต้องตายแน่ ให้โลหิตของผู้นั้นตกอยู่บนผู้นั้นเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 14, 'แต่ ดูเถิด ถ้าชายคนนี้มีบุตรชายผู้แลเห็นบาปทั้งสิ้นซึ่งบิดาของเขาได้กระทํา และตรึกตรอง และมิได้กระทําตาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 15, 'มิได้รับประทานบนภูเขา หรือเงยหน้าขึ้นนมัสการรูปเคารพแห่งวงศ์วานอิสราเอล มิได้กระทําให้ภรรยาของเพื่อนบ้านมลทิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 16, 'มิได้บีบบังคับผู้ใด ไม่เรียกร้องของประกัน ไม่เคยใช้ความรุนแรงปล้นผู้ใด แต่ให้อาหารแก่ผู้หิว และให้เสื้อผ้าคลุมกายที่เปลือย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 17, 'หดมือไว้มิได้เบียดเบียนคนยากจน ไม่เรียกดอกเบี้ยหรือเงินเพิ่ม กระทําตามคําตัดสินทั้งหลายของเรา และดําเนินตามกฎเกณฑ์ของเรา เขาจะไม่ตายเพราะความชั่วช้าของบิดาเขา เขาจะดํารงชีวิตอยู่แน่นอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 18, 'ส่วนบิดาของเขา เพราะเป็นคนหาเงินด้วยการบีบบังคับ ได้ใช้ความรุนแรงปล้นพี่น้องของตน กระทําความไม่ดีในท่ามกลางชนชาติของเขา ดูเถิด เขาก็จะต้องตายเพราะความชั่วช้าของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 19, 'แต่เจ้ายังกล่าวว่า ‘ทําไมบุตรชายจึงไม่สมควรรับโทษความชั่วช้าของบิดาตน’ เมื่อบุตรชายได้กระทําความยุติธรรมและความชอบธรรมแล้ว และได้รักษากฎเกณฑ์ทั้งสิ้นของเรา และประพฤติตาม เขาจะดํารงชีวิตอยู่แน่นอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 20, 'ชีวิตที่กระทําบาปจะต้องตาย บุตรชายไม่ต้องรับโทษความชั่วช้าของบิดา บิดาก็ไม่ต้องรับโทษความชั่วช้าของบุตรชาย คนชอบธรรมจะรับความชอบธรรมของตัว และคนชั่วจะรับความชั่วของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 21, 'แต่ถ้าคนชั่วคนใดหันกลับเสียจากบาปซึ่งเขาได้กระทําไปแล้ว และรักษากฎเกณฑ์ทั้งสิ้นของเรา และกระทําความยุติธรรมและความชอบธรรม เขาจะดํารงชีวิตอยู่แน่นอน เขาจะไม่ต้องตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 22, 'บรรดาการละเมิดใดๆซึ่งเขาได้กระทําแล้วนั้นจะมิได้จดจําไว้เพื่อเอาโทษเขา เขาจะมีชีวิตอยู่เพราะความชอบธรรมที่เขาได้กระทําไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 23, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสว่า เรามีความพอใจในความตายของคนชั่วหรือ แต่เราพอใจให้เขากลับจากความชั่วของเขาและมีชีวิตอยู่มิใช่หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 24, 'แต่เมื่อคนชอบธรรมหันกลับจากความชอบธรรมของตัว และกระทําความชั่วช้า และกระทําบรรดาสิ่งที่น่าสะอิดสะเอียนเช่นเดียวกับที่คนชั่วได้กระทํา ผู้นั้นสมควรจะมีชีวิตอยู่หรือ การชอบธรรมทั้งสิ้นซึ่งเขาได้กระทํามาแล้วนั้นจะมิได้จดจําไว้อีกเลย เขาจะต้องตายด้วยการละเมิดซึ่งเขาได้กระทําไว้และบาปซึ่งเขาได้กระทําลงไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 25, 'แต่เจ้ายังกล่าวว่า ‘วิธีการขององค์พระผู้เป็นเจ้าไม่ยุติธรรม’ โอ วงศ์วานอิสราเอลเอ๋ย จงฟังเถอะ วิธีการของเราไม่ยุติธรรมหรือ วิธีการของเจ้ามิใช่หรือที่ไม่ยุติธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 26, 'เมื่อคนชอบธรรมหันกลับจากความชอบธรรมของเขาและกระทําความชั่วช้า และตายเพราะการนั้น เขาจะต้องตายด้วยเหตุความชั่วช้าที่เขาได้กระทํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 27, 'และเมื่อคนชั่วหันกลับจากความชั่วที่ตนกระทําไป และกระทําความยุติธรรมและความชอบธรรม เขาก็ได้ช่วยชีวิตของเขาเองไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 28, 'เพราะเขาได้ตรึกตรองและหันกลับจากการละเมิดทั้งสิ้นซึ่งเขาได้กระทําไป เขาจะดํารงชีวิตอยู่แน่นอน เขาจะไม่ต้องตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 29, 'แต่วงศ์วานอิสราเอลกล่าวว่า ‘วิธีการขององค์พระผู้เป็นเจ้าไม่ยุติธรรม’ โอ วงศ์วานอิสราเอลเอ๋ย วิธีการของเราไม่ยุติธรรมหรือ วิธีการของเจ้ามิใช่หรือที่ไม่ยุติธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 30, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสว่า โอ วงศ์วานอิสราเอลเอ๋ย เพราะฉะนั้นเราจะพิพากษาเจ้าทุกคนตามทางประพฤติของคนนั้นๆ จงกลับใจและหันกลับเสียจากการละเมิดทั้งสิ้นของเจ้า เกรงว่าความชั่วช้าของเจ้าจะเป็นสิ่งสะดุดให้เจ้าพินาศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 31, 'จงละทิ้งการละเมิดทั้งสิ้นซึ่งเจ้าได้ละเมิดต่อเรา จงทําตัวให้มีจิตใจใหม่และวิญญาณใหม่ โอ วงศ์วานอิสราเอลเอ๋ย เจ้าจะตายเสียทําไมเล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 32, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสว่า เราไม่มีความพอใจในความตายของผู้หนึ่งผู้ใดเลย จงหันกลับและดํารงชีวิตอยู่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 1, 'ฝ่ายเจ้าจงเปล่งเสียงร้องบทคร่ําครวญเรื่องเจ้านายอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 2, 'กล่าวว่า “มารดาของเจ้าเป็นอย่างไรหนอ ก็เป็นแม่สิงโต เธอนอนอยู่ท่ามกลางสิงโตทั้งหลาย เธอเลี้ยงดูลูกของเธอท่ามกลางสิงโตหนุ่ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 3, 'เธอเลี้ยงลูกสิงโตตัวหนึ่งให้เติบโตขึ้น กลายเป็นสิงโตหนุ่ม มันฝึกหัดจับเหยื่อและมันกินคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 4, 'ประชาชาติได้ยินเรื่องของมัน เขาก็จับมันได้ในหลุมพรางของเขา เขาจูงมันมาด้วยโซ่มายังแผ่นดินอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 5, 'เมื่อแม่สิงโตเห็นว่าเธอคอยนานแล้ว และความหวังของเธอสูญไป เธอก็เอาลูกมาอีกตัวหนึ่งเลี้ยงให้เป็นสิงโตหนุ่ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 6, 'มันไปๆมาๆท่ามกลางสิงโตและกลายเป็นสิงโตหนุ่ม และมันฝึกหัดจับเหยื่อ มันกินคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 7, 'มันรู้จักบรรดาพระราชวังที่ร้างของเขา และกระทําให้เมืองทั้งหลายของเขาว่างเปล่า แผ่นดินนั้นก็รกร้างและความสมบูรณ์ของมันก็ว่างเปล่าไป เมื่อได้ยินเสียงคํารามของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 8, 'แล้วบรรดาประชาชาติก็ล้อมต่อสู้มันทุกด้านจากแว่นแคว้นทั้งปวง เขาทั้งหลายกางข่ายออกคลุมมัน มันก็ถูกจับอยู่ในหลุมพรางของเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 9, 'เขาล่ามโซ่ขังมันไว้ในกรง และนํามันมายังกษัตริย์บาบิโลน เขาก็ขังมันไว้ในที่กําบังเข้มแข็ง เพื่อไม่ให้ได้ยินเสียงของมันอีกที่บนภูเขาแห่งอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 10, 'มารดาของเจ้าเหมือนเถาองุ่นที่อยู่ในโลหิตของเจ้า เอามาปลูกไว้ริมน้ํา เธอมีผลดกและมีแขนงมากมายเหตุด้วยน้ําบริบูรณ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 11, 'เธอมีแขนงที่แข็งแรงซึ่งกลายเป็นไม้ธารพระกรของผู้ครอบครอง ความสูงของเธอชูขึ้นท่ามกลางแขนงที่หนาทึบ เธอปรากฏในที่สูงของเธอพร้อมกับแขนงมากมายของเธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 12, 'แต่ว่าเธอถูกถอนออกด้วยความเกรี้ยวกราด เธอถูกทิ้งลงยังพื้นดิน ลมตะวันออกกระทําให้ผลของเธอเหี่ยวไป แขนงที่แข็งแรงก็หักเสียและเหี่ยวไป ไฟก็ไหม้เสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 13, 'คราวนี้เธอปลูกไว้ในถิ่นทุรกันดาร ในแผ่นดินที่แห้งแล้งกันดารน้ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 14, 'ไฟได้ออกมาจากแขนงใหญ่นั้น เผาผลาญแขนงอื่นและผลเสียหมด จึงไม่มีแขนงแข็งแรงเหลืออยู่ในต้นอีกเลย ไม่มีธารพระกรสําหรับผู้ครอบครอง นี่เป็นบทเพลงคร่ําครวญ และใช้เป็นบทเพลงคร่ําครวญ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 1, 'อยู่มาวันที่สิบ เดือนที่ห้าในปีที่เจ็ด พวกผู้ใหญ่แห่งอิสราเอลบางคนได้มาทูลถามพระเยโฮวาห์ และมานั่งอยู่ข้างหน้าข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 2, 'พระวจนะของพระเยโฮวาห์มายังข้าพเจ้าว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 3, '“บุตรแห่งมนุษย์เอ๋ย จงพูดกับพวกผู้ใหญ่แห่งอิสราเอล และกล่าวแก่เขาว่า องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า ที่เจ้ามากันนี้จะมาถามเราหรือ องค์พระผู้เป็นเจ้าพระเจ้าตรัสว่า เรามีชีวิตอยู่แน่ฉันใด เราจะไม่ยอมให้เจ้ามาถามเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 4, 'บุตรแห่งมนุษย์เอ๋ย เจ้าจะพิพากษาเขาหรือ เจ้าจะพิพากษาเขาหรือ จงให้เขาทั้งหลายทราบถึงการกระทําอันน่าสะอิดสะเอียนของบรรพบุรุษของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 5, 'และจงกล่าวแก่เขาว่า องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า ในวันนั้นเมื่อเราเลือกสรรอิสราเอลไว้ เราปฏิญาณต่อเชื้อสายแห่งวงศ์วานยาโคบ โดยสําแดงตัวเราให้เขารู้จักในแผ่นดินอียิปต์ เมื่อเราปฏิญาณกับเขาว่า เราเป็นพระเยโฮวาห์พระเจ้าของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 6, 'ในวันนั้น เราปฏิญาณต่อเขาว่า เราจะนําเขาออกจากแผ่นดินอียิปต์ไปยังแผ่นดินที่เราหาให้เขาทั้งหลาย เป็นแผ่นดินที่มีน้ํานมและน้ําผึ้งไหลบริบูรณ์ เป็นแผ่นดินที่มีสง่าราศีที่สุดในแผ่นดินทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 7, 'และเรากล่าวแก่เขาว่า เจ้าทุกคนจงทิ้งสิ่งที่น่าสะอิดสะเอียนซึ่งนัยน์ตาของเจ้าทั้งหลายกําลังเพลิดเพลินอยู่นั้นเสีย อย่ากระทําตัวของเจ้าให้มลทินไปด้วยรูปเคารพของอียิปต์ เราคือพระเยโฮวาห์พระเจ้าของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 8, 'แต่เขาทั้งหลายได้กบฏต่อเราและไม่ยอมฟังเรา เขาทั้งหลายไม่ได้ทิ้งสิ่งที่น่าสะอิดสะเอียนซึ่งนัยน์ตาของเขาเพลิดเพลินอยู่นั้นทุกคน ทั้งเขาก็มิได้ละทิ้งรูปเคารพของอียิปต์ แล้วเราก็คิดว่า เราจะระบายความกริ้วของเราออกเหนือเขา และให้ความโกรธของเรามีต่อเขาในท่ามกลางแผ่นดินอียิปต์จนมอดลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 9, 'แต่เราก็กระทําโดยเห็นแก่นามของเราเอง เพื่อไม่ให้ชื่อนั้นมลทินต่อหน้าประชาชาติซึ่งเขาอาศัยอยู่ เราจึงได้สําแดงตัวของเราท่ามกลางสายตาของเขาให้เขารู้จัก ในการที่เรานําคนอิสราเอลออกมาจากแผ่นดินอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 10, 'ดังนั้น เราจึงนําเขาออกจากแผ่นดินอียิปต์ และนําเขาเข้ามาในถิ่นทุรกันดาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 11, 'เราให้กฎเกณฑ์ของเราแก่เขา และสําแดงคําตัดสินของเราให้เขารู้ ซึ่งถ้ามนุษย์ได้รักษาไว้ก็จะดํารงชีวิตอยู่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 12, 'ยิ่งกว่านั้นอีก เราได้ให้สะบาโตของเราแก่เขา เป็นหมายสําคัญระหว่างเราและเขาทั้งหลาย เพื่อเขาจะทราบว่าเราคือพระเยโฮวาห์ เป็นผู้กระทําให้เขาบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 13, 'แต่วงศ์วานอิสราเอลได้กบฏต่อเราในถิ่นทุรกันดาร เขามิได้ดําเนินตามกฎเกณฑ์ของเรา แต่ได้ดูหมิ่นคําตัดสินของเรา ซึ่งถ้ามนุษย์คนหนึ่งคนใดปฏิบัติตาม เขาก็จะดํารงชีวิตอยู่ได้ด้วยกฎเกณฑ์และคําตัดสินเหล่านั้น และเขาได้กระทําให้วันสะบาโตของเรามัวหมองอย่างยิ่ง เราจึงกล่าวว่า เราจะเทความเดือดดาลของเราออกเหนือเขาในถิ่นทุรกันดารเพื่อผลาญเขาเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 14, 'แต่เราก็กระทําโดยเห็นแก่นามของเราเอง เพื่อไม่ให้ชื่อนั้นมลทินต่อหน้าประชาชาติทั้งหลาย ซึ่งเราได้นําคนอิสราเอลออกมาท่ามกลางสายตาของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 15, 'ยิ่งกว่านั้นอีก เราได้ปฏิญาณต่อเขาในถิ่นทุรกันดารว่า เราจะไม่นําเขาเข้ามาในแผ่นดินซึ่งเราได้ให้แก่เขา เป็นแผ่นดินที่มีน้ํานมและน้ําผึ้งไหลบริบูรณ์ เป็นแผ่นดินที่มีสง่าราศีที่สุดในแผ่นดินทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 16, 'เพราะเขาดูหมิ่นคําตัดสินของเรา และไม่ดําเนินตามกฎเกณฑ์ของเรา และได้กระทําให้วันสะบาโตของเรามัวหมอง เพราะว่าจิตใจของเขาไปติดตามรูปเคารพของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 17, 'ถึงกระนั้นก็ดี นัยน์ตาของเราก็ยังปรานีเขา และเรามิได้ทําลายเขา หรือกระทําให้เขาจบสิ้นลงในถิ่นทุรกันดารนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 18, 'แต่เราพูดกับลูกหลานของเขาในถิ่นทุรกันดารนั้นว่า อย่าดําเนินตามกฎเกณฑ์ของบรรพบุรุษของเจ้า หรือรักษาคําตัดสินของเขา หรือกระทําตัวเจ้าให้มลทินไปด้วยรูปเคารพของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 19, 'เราคือพระเยโฮวาห์เป็นพระเจ้าของเจ้า จงดําเนินตามกฎเกณฑ์ของเรา และจงรักษาคําตัดสินของเรา และประพฤติตาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 20, 'และนับถือบรรดาสะบาโตของเรา เพื่อจะเป็นหมายสําคัญระหว่างเรากับเจ้า เพื่อเจ้าจะทราบว่าเราคือพระเยโฮวาห์เป็นพระเจ้าของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 21, 'แต่ลูกหลานเหล่านั้นก็กบฏต่อเรา เขาทั้งหลายมิได้ดําเนินตามกฎเกณฑ์ของเรา และไม่รักษาคําตัดสินของเราเพื่อจะประพฤติตาม ซึ่งถ้ามนุษย์คนหนึ่งคนใดปฏิบัติตามก็จะดํารงชีวิตอยู่ได้ด้วยกฎเกณฑ์และคําตัดสินเหล่านั้น เขาได้กระทําให้บรรดาวันสะบาโตของเรามัวหมอง เราจึงกล่าวว่า เราจะเทความเดือดดาลของเราออกเหนือเขา และให้ความโกรธของเราที่มีต่อเขาที่ในถิ่นทุรกันดารบรรลุลงเสียที');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 22, 'แต่เราได้หดมือของเราไว้ และกระทําโดยเห็นแก่นามของเราเอง เพื่อไม่ให้ชื่อนั้นมลทินท่ามกลางสายตาของประชาชาติทั้งหลาย ซึ่งเราได้นําชนอิสราเอลออกมาท่ามกลางสายตาของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 23, 'ยิ่งกว่านั้นอีก เราได้ปฏิญาณต่อเขาทั้งหลายในถิ่นทุรกันดารว่า เราจะให้กระจัดกระจายไปในท่ามกลางประชาชาติ และกระจายเขาไปอยู่ตามประเทศต่างๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 24, 'เพราะว่าเขามิได้กระทําตามคําตัดสินของเรา แต่ได้ดูหมิ่นกฎเกณฑ์ของเรา และกระทําให้วันสะบาโตทั้งหลายของเรามัวหมอง และนัยน์ตาของเขาก็ติดตามรูปเคารพแห่งบรรพบุรุษของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 25, 'ยิ่งกว่านั้นอีก เราได้ให้กฎเกณฑ์ที่ไม่ดีและให้คําตัดสินซึ่งตามนั้นเขาจะดํารงชีวิตไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 26, 'และเราก็ได้ให้เขามลทินไปด้วยของถวายของเขาเอง โดยให้เขาถวายบุตรหัวปีให้ลุยไฟ เพื่อเราจะกระทําให้เขารกร้างไป เพื่อให้เขาทราบว่าเราคือพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 27, 'เพราะฉะนั้น บุตรแห่งมนุษย์เอ๋ย จงพูดกับวงศ์วานอิสราเอลและกล่าวแก่เขาว่า องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า ในเรื่องนี้บรรพบุรุษของเจ้าก็ได้หมิ่นประมาทเราอีก โดยกระทําการละเมิดต่อเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 28, 'เพราะว่าเมื่อเราได้นําเขาเข้ามาในแผ่นดินที่เราปฏิญาณว่าจะให้เขานั้นแล้ว เมื่อเขาเห็นเนินเขาสูง ณ ที่ใด หรือเห็นต้นไม้ใบดกที่ไหน เขาก็ถวายเครื่องบูชาอันเป็นที่ให้เคืองใจเรา ณ ที่นั่น เขาถวายกลิ่นที่พึงใจ และเขาเทเครื่องดื่มบูชาออกที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 29, 'เราได้ถามเขาว่า ปูชนียสถานสูงซึ่งเจ้าเข้าไปนั้นคืออะไร และเขาจึงเรียกชื่อที่นั่นว่า บามาห์ สืบเนื่องมาจนทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 30, 'เพราะฉะนั้นจงกล่าวแก่วงศ์วานอิสราเอลว่า องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า เจ้ากระทําตัวให้มลทินไปตามอย่างบรรพบุรุษของเจ้า และเล่นชู้กับสิ่งที่น่าสะอิดสะเอียนของเขาหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 31, 'เมื่อเจ้าถวายของบูชาและถวายบุตรชายให้ลุยไฟ เจ้าได้กระทําตัวให้มลทินด้วยบรรดารูปเคารพของเจ้าจนทุกวันนี้ โอ วงศ์วานอิสราเอลเอ๋ย เราจะให้เจ้ามาถามเราหรือ องค์พระผู้เป็นเจ้าพระเจ้าตรัสว่า เรามีชีวิตอยู่แน่ฉันใด เราจะไม่ให้เจ้ามาถามเราฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 32, 'อะไรอยู่ในใจของเจ้าจะไม่เกิดขึ้นได้เลย คือความคิดที่ว่า ‘ให้เราเป็นเหมือนประชาชาติทั้งหลาย ให้เป็นเหมือนครอบครัวต่างๆในประเทศทั่วไป คือให้เราปรนนิบัติไม้และศิลา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 33, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสว่า เรามีชีวิตอยู่แน่ฉันใด เราจะครอบครองเหนือเจ้าแน่นอนทีเดียว ด้วยมือที่มีฤทธิ์ และด้วยแขนที่เหยียดออก และด้วยความพิโรธที่เทลงมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 34, 'เราจะนําเจ้าออกมาจากชนชาติทั้งหลาย และจะรวบรวมเจ้าออกมาจากประเทศทั้งปวงซึ่งเจ้าต้องกระจัดกระจายกันไปอยู่นั้น ด้วยมือที่มีฤทธิ์ และด้วยแขนที่เหยียดออก และด้วยความพิโรธที่เทลงมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 35, 'และเราจะนําเจ้าเข้าไปในถิ่นทุรกันดารแห่งชนชาติทั้งหลาย และที่นั่นเราจะเข้าสู่การพิพากษากับเจ้าหน้าต่อหน้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 36, 'เราเข้าสู่การพิพากษากับบรรพบุรุษของเจ้าในถิ่นทุรกันดารแห่งแผ่นดินอียิปต์อย่างไร องค์พระผู้เป็นเจ้าพระเจ้าตรัสว่า เราจะเข้าสู่การพิพากษากับเจ้าอย่างนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 37, 'เราจะให้เจ้าลอดไปใต้คทา และเราจะให้เจ้าเข้าพันธสัญญา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 38, 'เราจะชําระพวกกบฏเสียจากท่ามกลางเจ้า ทั้งผู้ละเมิดต่อเรา เราจะนําเขาออกจากแผ่นดินที่เขาไปอาศัยอยู่นั้น แต่เขาจะไม่ได้เข้าไปในแผ่นดินอิสราเอล แล้วเจ้าจะทราบว่าเราคือพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 39, 'เดี๋ยวนี้ องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า โอ วงศ์วานอิสราเอลเอ๋ย ฝ่ายเจ้าทั้งหลายทุกคนจงไปปรนนิบัติรูปเคารพของเจ้าเดี๋ยวนี้ และต่อไปถ้าเจ้าไม่ฟังเรา แต่ชื่ออันบริสุทธิ์ของเรานั้นเจ้าอย่ากระทําให้มลทินอีกด้วยของถวายและด้วยรูปเคารพของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 40, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสว่า ด้วยว่าบนภูเขาบริสุทธิ์ของเรา คือภูเขาสูงของอิสราเอล บรรดาวงศ์วานทั้งหมดของอิสราเอลจะปรนนิบัติเราในแผ่นดินนั้น เราจะโปรดเขา ณ ที่นั่น ณ ที่นั่นเราจะเรียกของถวายของเจ้า และผลรุ่นแรกแห่งเครื่องบูชาของเจ้า กับเครื่องถวายบูชาอันบริสุทธิ์ทั้งสิ้นของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 41, 'เมื่อเรานําเจ้าออกมาจากชาติทั้งหลาย และรวบรวมเจ้าออกมาจากประเทศที่เจ้ากระจัดกระจายไปอยู่นั้น เราจะโปรดเจ้าดั่งเป็นกลิ่นที่พอใจของเรา และเราจะสําแดงความบริสุทธิ์ของเราท่ามกลางเจ้าต่อหน้าต่อตาประชาชาติทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 42, 'และเจ้าจะทราบว่าเราคือพระเยโฮวาห์ ในเมื่อเรานําเจ้าเข้าในแผ่นดินอิสราเอล อันเป็นประเทศซึ่งเราปฏิญาณไว้ว่าจะให้แก่บรรพบุรุษของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 43, 'ณ ที่นั่นเจ้าจะระลึกถึงวิถีทางและการกระทําทั้งสิ้นของเจ้า ซึ่งได้กระทําให้เจ้าเป็นมลทิน และในสายตาของเจ้าเองเจ้าจะเกลียดชังตัวของเจ้า เพราะความชั่วทั้งหลายซึ่งเจ้าได้กระทํานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 44, 'โอ วงศ์วานอิสราเอลเอ๋ย เมื่อเราได้กระทํากับเจ้าด้วยเห็นแก่นามของเรา มิใช่ตามทางอันชั่วของเจ้า หรือตามการกระทําที่เสื่อมทรามของเจ้า แล้วเจ้าจึงจะทราบว่าเราคือพระเยโฮวาห์ องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้แหละ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 45, 'และพระวจนะของพระเยโฮวาห์มายังข้าพเจ้าว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 46, '“บุตรแห่งมนุษย์เอ๋ย จงมุ่งหน้าไปทางทิศใต้และเทศนากล่าวโทษพวกถิ่นใต้ จงพยากรณ์ต่อแดนป่าไม้ที่ในถิ่นใต้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 47, 'จงกล่าวแก่ป่าไม้แห่งถิ่นใต้ว่า จงฟังพระวจนะของพระเยโฮวาห์ องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า ดูเถิด เราจะก่อไฟไว้ในเจ้า มันจะเผาผลาญต้นไม้เขียวและต้นไม้แห้งทุกต้นที่อยู่ในเจ้าเสีย จะดับเปลวเพลิงอันลุกโพลงนั้นไม่ได้ และดวงหน้าทุกหน้าตั้งแต่ทิศใต้จนทิศเหนือจะถูกไฟลวก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 48, 'เนื้อหนังทั้งสิ้นจะเห็นว่าเราคือพระเยโฮวาห์ผู้ได้ก่อไฟนั้น ผู้ใดจะดับก็ไม่ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 49, 'แล้วข้าพเจ้าจึงกล่าวว่า “องค์พระผู้เป็นเจ้าพระเจ้า เจ้าข้า เขาทั้งหลายกําลังกล่าวถึงข้าพระองค์ว่า เขาไม่ใช่เป็นคนสร้างคําอุปมาดอกหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 1, 'พระวจนะของพระเยโฮวาห์มายังข้าพเจ้าว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 2, '“บุตรแห่งมนุษย์เอ๋ย จงมุ่งหน้าของเจ้าต่อสู้เยรูซาเล็ม และเทศนากล่าวโทษสถานบริสุทธิ์ทั้งหลาย จงพยากรณ์กล่าวโทษแผ่นดินอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 3, 'และกล่าวแก่แผ่นดินอิสราเอลว่า พระเยโฮวาห์ตรัสดังนี้ว่า ดูเถิด เราเป็นปฏิปักษ์กับเจ้า และเราจะชักดาบของเราออกจากฝัก และเราจะขจัดทั้งคนชอบธรรมและคนชั่วออกจากเจ้าเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 4, 'ดังนั้นจงดูเถิดว่าเราจะตัดเอาทั้งคนชอบธรรมและคนชั่วออกจากเจ้าเสีย เพราะฉะนั้นดาบของเราจะออกจากฝักไปต่อสู้เนื้อหนังทั้งสิ้นจากทิศใต้ถึงทิศเหนือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 5, 'เพื่อเนื้อหนังทั้งสิ้นจะทราบว่าเราคือพระเยโฮวาห์ได้ชักดาบของเราออกจากฝักแล้ว และจะไม่เก็บใส่ฝักอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 6, 'บุตรแห่งมนุษย์เอ๋ย เพราะฉะนั้นจงถอนหายใจ ถอนหายใจด้วยความระทมใจและความขมขื่นต่อหน้าต่อตาเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 7, 'และเมื่อเขาทั้งหลายกล่าวแก่เจ้าว่า ‘ทําไมเจ้าถอนหายใจ’ เจ้าจงกล่าวว่า ‘เพราะเรื่องข่าวนั้น เมื่อข่าวนั้นมาถึงหัวใจทุกดวงจะละลายและมือทั้งสิ้นจะอ่อนเปลี้ยไป และบรรดาจิตวิญญาณจะแน่นิ่งไป และหัวเข่าทุกเข่าจะอ่อนเปลี้ยดั่งน้ํา ดูเถิด ข่าวนั้นมาถึงและจะสําเร็จ’ องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้แหละ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 8, 'พระวจนะของพระเยโฮวาห์มายังข้าพเจ้าอีกว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 9, '“บุตรแห่งมนุษย์เอ๋ย จงพยากรณ์และกล่าวว่า พระเยโฮวาห์ตรัสดังนี้ว่า ดาบเล่มหนึ่ง ดาบเล่มหนึ่งซึ่งเขาลับให้คม และขัดมันด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 10, 'ลับให้คมเพื่อจะเข่นฆ่า ขัดมันไว้เพื่อจะให้วาววับ เราจะร่าเริงหรือ ดาบนั้นได้ประมาทไม้เรียวแห่งบุตรชายของเรา เหมือนต้นไม้ทุกอย่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 11, 'เพราะฉะนั้นจึงมอบดาบให้ขัดมัน เพื่อจะถือไว้ได้ ดาบนั้นคมแล้วและขัดมัน เพื่อจะมอบไว้ในมือของผู้ฆ่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 12, 'บุตรแห่งมนุษย์เอ๋ย จงร้องไห้และคร่ําครวญเถิด เพราะเป็นเรื่องต่อสู้กับประชาชนของเรา และต่อสู้กับบรรดาเจ้านายของอิสราเอล ความหวาดผวาเพราะเหตุดาบนั้นจะอยู่เหนือประชาชนของเรา เพราะฉะนั้นจงตีที่โคนขาของเจ้าเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 13, 'เพราะมีการทดลอง และอะไรเล่าถ้าดาบได้ดูหมิ่นไม้เรียวนั้น ก็จะไม่มีอีก องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 14, 'บุตรแห่งมนุษย์เอ๋ย เพราะฉะนั้นจงพยากรณ์เถิด จงตบมือและปล่อยให้ดาบลงมาสองครั้ง เออ สามครั้ง คือดาบสําหรับคนเหล่านั้นที่จะถูกฆ่า เป็นดาบของพวกผู้ยิ่งใหญ่ที่ถูกฆ่า ซึ่งได้เข้าไปในห้องส่วนตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 15, 'เพื่อว่าใจของเขาจะละลาย และเพื่อซากปรักหักพังของเขาจะทวีคูณขึ้นอีก เราได้จ่อดาบนั้นไปที่ประตูเมืองทั้งหลายของเขาแล้ว เออ ทําเสียเหมือนอย่างกับฟ้าแลบ เขาขัดมันเพื่อจะเข่นฆ่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 16, 'รวมกันเข้ามา ไปทางขวาเรียงแถว แล้วไปทางซ้าย ไม่ว่าหน้าของเจ้ามุ่งไปทางไหน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 17, 'เราจะตบมือของเราด้วย และเราจะระบายความโกรธของเราจนหมด เราคือพระเยโฮวาห์ได้ลั่นวาจาแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 18, 'พระวจนะของพระเยโฮวาห์มายังข้าพเจ้าอีกว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 19, '“บุตรแห่งมนุษย์เอ๋ย จงขีดทางไว้สองทางให้ดาบแห่งกษัตริย์บาบิโลนเข้ามา ทั้งสองทางให้ออกมาจากแผ่นดินเดียวกัน และจงทําป้ายบอกทาง จงทําไว้ที่หัวถนนที่เข้าไปหากรุง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 20, 'ทําทางหนึ่งให้ดาบมายังรับบาห์แห่งคนอัมโมน และมายังยูดาห์ในเยรูซาเล็มเมืองที่มีกําแพง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 21, 'เพราะว่ากษัตริย์บาบิโลนยืนอยู่ที่ทางแพร่ง อยู่ที่หัวถนนสองถนน กําหนดหาคําทํานาย ท่านเขย่าลูกธนู และปรึกษารูปเคารพ ท่านมองดูที่ตับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 22, 'ในมือข้างขวา ท่านมีฉลากเยรูซาเล็ม เพื่อตั้งเครื่องทะลวง เพื่อจะให้อ้าปากในการฆ่า เพื่อส่งเสียงตะโกน เพื่อวางเครื่องทะลวงกําแพงเข้าที่ประตูเมือง เพื่อก่อเชิงเทินและก่อกําแพงล้อม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 23, 'และจะเป็นเหมือนคําทํานายเท็จสําหรับคนเหล่านั้นในสายตาของเขา คือคนเหล่านั้นที่ให้สัตย์ปฏิญาณแล้ว แต่ท่านจะระลึกถึงความชั่วช้า เพื่อเขาทั้งหลายจะถูกจับเอาไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 24, 'เพราะฉะนั้น องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า เพราะว่าเจ้าได้กระทําความชั่วช้าของเจ้าให้เราระลึกได้ โดยการละเมิดของเจ้าที่เผยออก จนบาปของเจ้าปรากฏในการกระทําทั้งสิ้นของเจ้า เราได้ระลึกถึงเจ้า เจ้าจึงต้องถูกจับเอาไปด้วยมือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 25, 'และเจ้า ผู้ชั่วที่ลามกคือเจ้านายอิสราเอลเอ๋ย ผู้ที่วันกําหนดมาถึงแล้ว คือเวลาแห่งการลงโทษความชั่วช้าครั้งสุดท้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 26, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า จงปลดผ้าโพก และถอดมงกุฎออกเสีย สิ่งต่างๆจะไม่คงอยู่อย่างที่เคยเป็น ให้ยกย่องคนที่ต่ําขึ้น และให้กดคนที่สูงลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 27, 'เราจะกระทําให้เป็นที่พังทลาย พังทลาย พังทลาย และจะไม่มีเลยจนกว่าผู้มีสิทธิ์อันชอบธรรมจะมาถึง และเราจะประทานให้แก่ท่านผู้นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 28, 'บุตรแห่งมนุษย์เอ๋ย และเจ้าจงพยากรณ์และกล่าวว่า องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้เกี่ยวกับคนอัมโมน และเกี่ยวกับเรื่องน่าตําหนิของเขาทั้งหลายว่า ดาบเล่มหนึ่ง ดาบเล่มหนึ่งถูกชักออก เขาขัดมันเพื่อการเข่นฆ่า เขาให้มันดื่มโลหิตเพราะมันวาววับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 29, 'ขณะเมื่อเขาเห็นนิมิตเท็จมาบอกท่าน ขณะเมื่อเขาให้คําทํานายมุสาแก่ท่าน เพื่อจะวางท่านไว้บนคอของผู้ชั่วที่ถูกฆ่า เวลากําหนดของเขามาถึงแล้ว คือเวลาแห่งการลงโทษความชั่วช้าครั้งสุดท้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 30, 'เราจะให้ดาบกลับเข้าฝักอีกหรือ เราจะพิพากษาเจ้าในสถานที่ที่เจ้าถูกสร้างขึ้น ในแผ่นดินดั้งเดิมของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 31, 'เราจะเทความกริ้วของเราเหนือเจ้า และเราจะพ่นเจ้าด้วยไฟแห่งความพิโรธของเรา และเราจะมอบเจ้าไว้ในมือของคนเขลา ผู้มีฝีมือในการทําลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 32, 'เจ้าจะเป็นฟืนไว้ใส่ไฟ โลหิตของเจ้าจะอยู่กลางแผ่นดิน จะไม่มีใครจดจําเจ้าไว้อีก เพราะเราคือพระเยโฮวาห์ได้ลั่นวาจาแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 1, 'พระวจนะของพระเยโฮวาห์มายังข้าพเจ้าอีกว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 2, '“บุตรแห่งมนุษย์เอ๋ย ตัวเจ้าจะพิพากษาหรือ เจ้าจะพิพากษาเมืองที่แปดเปื้อนด้วยโลหิตนั้นหรือ เจ้าจงสําแดงให้เมืองนั้นเห็นสิ่งที่น่าสะอิดสะเอียนทั้งสิ้นของเธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 3, 'เจ้าจงกล่าวว่า องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า นี่เป็นเมืองที่ทําให้โลหิตตกอยู่ที่กลางตนเองเพื่อให้เวลากําหนดของตนมาถึง และเป็นเมืองที่ทํารูปเคารพไว้ให้ตัวมลทินไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 4, 'เจ้ามีความชั่วด้วยโลหิตที่เจ้ากระทําให้ตกนั้น และมลทินไปด้วยรูปเคารพที่เจ้ากระทําไว้ และเจ้าได้นําให้เวลาของเจ้าเข้ามาใกล้ เวลากําหนดแห่งปีของเจ้ามาถึงแล้ว เพราะฉะนั้นเราจึงกระทําเจ้าให้เป็นที่ประณามกันแก่ประชาชาติ และเป็นที่เย้ยหยันแก่ประเทศทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 5, 'ผู้ที่อยู่ใกล้และที่อยู่ไกลเจ้าจะเย้ยหยันเจ้า ผู้เป็นเมืองที่เสียชื่อและเต็มด้วยความโกลาหล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 6, 'ดูเถิด เจ้านายแห่งอิสราเอล ทุกคนซึ่งอยู่ในเจ้าก็โน้มไปในทางที่ทําให้โลหิตตกตามอํานาจของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 7, 'บิดามารดาถูกเหยียดหยามอยู่ในเจ้า คนต่างด้าวที่อาศัยอยู่ก็ถูกเบียดเบียนอยู่ท่ามกลางเจ้า ลูกกําพร้าพ่อและหญิงม่ายก็ถูกข่มเหงอยู่ในเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 8, 'เจ้าได้ดูหมิ่นสิ่งบริสุทธิ์ของเรา และลบหลู่วันสะบาโตทั้งหลายของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 9, 'ในเจ้ามีคนกล่าวร้ายเพื่อจะทําให้โลหิตตก และมีคนในเจ้าที่รับประทานบนภูเขา มีคนกระทําอุจาดลามกท่ามกลางเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 10, 'ในเจ้ามีชายบางคนได้เห็นความเปลือยของบิดาเขา ในเจ้ามีคนที่กระทําหยามเกียรติผู้หญิงที่ยังมีมลทินเพราะมีประจําเดือน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 11, 'คนหนึ่งกระทําการอันน่าสะอิดสะเอียนกับภรรยาของเพื่อนบ้าน อีกคนหนึ่งกระทําให้ลูกสะใภ้ของตนเป็นมลทินอย่างชั่วช้าลามก และอีกคนหนึ่งในพวกเจ้ากระทําหยามเกียรติน้องสาวของเขาเอง คือลูกสาวของบิดาของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 12, 'ในเจ้ามีคนรับสินบนเพื่อกระทําให้โลหิตตก เจ้าเอาดอกเบี้ยและเอาเงินเพิ่มและทํากําไรจากเพื่อนบ้านของเจ้าโดยการบีบบังคับ และเจ้าได้ลืมเราเสีย องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 13, 'ดูเถิด เพราะฉะนั้นเราได้ฟาดมือของเราลงบนผลกําไรอธรรมที่เจ้าได้ และลงบนโลหิตที่อยู่ในหมู่พวกเจ้าทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 14, 'ใจเจ้าจะทนได้หรือ และมือของเจ้าจะแข็งแรงอยู่หรือ ในวันที่เราจะเอาเรื่องกับเจ้า เราคือพระเยโฮวาห์ได้ลั่นวาจาแล้ว และเราจะกระทํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 15, 'เราจะให้เจ้ากระจัดกระจายไปในหมู่ประชาชาติ และกระจายเข้าไปตามประเทศต่างๆ และเราจะเผาเอาความโสโครกออกจากเจ้าเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 16, 'เจ้าจะได้มรดกของเจ้าเพราะตัวเจ้าเองท่ามกลางสายตาของประชาชาติ และเจ้าจะรู้ว่าเราคือพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 17, 'และพระวจนะของพระเยโฮวาห์มายังข้าพเจ้าว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 18, '“บุตรแห่งมนุษย์เอ๋ย สําหรับเราวงศ์วานอิสราเอลกลายเป็นขี้โลหะ เขาทั้งสิ้นเป็นทองเหลือง ดีบุก เหล็ก และตะกั่วในเตาหลอม เขาเป็นขี้โลหะเงินไปหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 19, 'เพราะฉะนั้น องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า เพราะว่าเจ้าเป็นขี้โลหะไปเสียทั้งสิ้นแล้ว เพราะฉะนั้น ดูเถิด เราจะรวบรวมเจ้าไว้ท่ามกลางเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 20, 'อย่างที่คนเขารวบรวมเงิน ทองเหลืองและเหล็ก และตะกั่วและดีบุกไว้ในเตาหลอม เพื่อเอาไฟเป่าให้มันละลาย ดังนั้นเราจะรวบรวมเจ้าด้วยความกริ้วและด้วยความพิโรธของเรา และเราจะใส่เจ้ารวมไว้ให้เจ้าละลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 21, 'เราจะรวบรวมเจ้า และเอาเพลิงแห่งความพิโรธของเราพ่นเจ้า และเจ้าจะละลายอยู่ท่ามกลางนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 22, 'เงินละลายอยู่ในเตาหลอมฉันใด เจ้าทั้งหลายจะละลายอยู่ท่ามกลางเพลิงฉันนั้น และเจ้าจะทราบว่า เราคือพระเยโฮวาห์ได้เทความกริ้วของเราลงเหนือเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 23, 'และพระวจนะของพระเยโฮวาห์มายังข้าพเจ้าว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 24, '“บุตรแห่งมนุษย์เอ๋ย จงพูดกับแผ่นดินนั้นว่า เจ้าเป็นแผ่นดินที่ไม่ได้รับการชําระ หรือฝนมิได้ชะในวันแห่งพระพิโรธ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 25, 'มีการวางแผนร้ายระหว่างพวกผู้พยากรณ์ท่ามกลางแผ่นดินนั้น เป็นเหมือนสิงโตคํารามฉีกเหยื่ออยู่ เขาทั้งหลายกินชีวิตมนุษย์ เขาริบทรัพย์สมบัติและสิ่งประเสริฐไป เขาได้กระทําให้มีหญิงม่ายเกิดขึ้นมากมายท่ามกลางแผ่นดินนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 26, 'ปุโรหิตของเขาได้ละเมิดราชบัญญัติของเรา และได้ลบหลู่สิ่งบริสุทธิ์ของเรา เขามิได้แยกแยะความแตกต่างระหว่างสิ่งที่บริสุทธิ์และสิ่งสามัญ เขามิได้แสดงให้เห็นความแตกต่างระหว่างของมลทินและของสะอาด เขาได้ซ่อนนัยน์ตาของเขาไว้จากวันสะบาโตของเรา ดังนั้นแหละเราจึงถูกลบหลู่ท่ามกลางเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 27, 'เจ้านายในท่ามกลางแผ่นดินเป็นเหมือนสุนัขป่าที่ฉีกเหยื่อ ทําให้โลหิตตก ทําลายชีวิตเพื่อจะเอากําไรที่อสัตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 28, 'และผู้พยากรณ์ของแผ่นดินนั้นก็ฉาบด้วยปูนขาว ให้เขาเห็นนิมิตเท็จ และให้คําทํานายมุสาแก่เขา โดยกล่าวว่า ‘องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้’ ในเมื่อพระเยโฮวาห์มิได้ตรัสเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 29, 'ประชาชนแห่งแผ่นดินกระทําการบีบคั้นและกระทําโจรกรรม เออ เขาบีบบังคับคนยากจนและคนขัดสน และบีบคั้นคนต่างด้าวอย่างอยุติธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 30, 'และเราก็แสวงหาสักคนหนึ่งในพวกเขาซึ่งจะสร้างรั้วต้นไม้และยืนอยู่ในช่องโหว่ต่อหน้าเราเพื่อแผ่นดินนั้น เพื่อเราจะมิได้ทําลายมันเสีย แต่ก็หาไม่ได้สักคนเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 31, 'ฉะนั้นเราจึงเทความกริ้วของเราลงเหนือเขา เราได้เผาผลาญเขาด้วยเพลิงพิโรธของเรา เราได้ตอบสนองตามการประพฤติของเขาเหนือศีรษะเขา องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้แหละ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 1, 'พระวจนะของพระเยโฮวาห์มายังข้าพเจ้าอีกว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 2, '“บุตรแห่งมนุษย์เอ๋ย มีผู้หญิงสองคน เป็นบุตรสาวมารดาเดียวกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 3, 'เธอเล่นชู้ในอียิปต์ เธอเล่นชู้ตั้งแต่สาวๆ ณ ที่นั้นถันของเธอถูกเคล้าคลึง และอกพรหมจารีของเธอก็ถูกจับต้อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 4, 'คนพี่ชื่อโอโฮลาห์และโอโฮลีบาห์เป็นชื่อน้องสาว ทั้งสองมาเป็นของเรา ทั้งสองเกิดบุตรชายหญิง เรื่องชื่อนั้น โอโฮลาห์คือสะมาเรีย และโอโฮลีบาห์คือเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 5, 'โอโฮลาห์เล่นชู้เมื่อเธอเป็นของเรา เธอลุ่มหลงพวกคนรักของเธอ คืออัสซีเรียเพื่อนบ้านของเธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 6, 'ซึ่งแต่งกายสีม่วง และเป็นเจ้าเมืองและผู้บังคับบัญชา ทุกคนเป็นชายหนุ่มที่พึงปรารถนา พลม้าขี่ม้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 7, 'เธอเล่นชู้กับคนเหล่านี้ ซึ่งเป็นบุคคลที่คัดเลือกแล้วของอัสซีเรียทุกคน และเธอก็กระทําตัวให้เป็นมลทินด้วยรูปเคารพของทุกคนที่เธอลุ่มหลงนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 8, 'เธอมิได้เลิกการเล่นชู้ซึ่งเธอได้นํามาจากอียิปต์ เพราะว่าเมื่อยังสาวอยู่คนหนุ่มก็เข้านอนกับเธอ และจับต้องอกพรหมจารีของเธอ และเทราคะของเขาให้แก่เธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 9, 'เพราะฉะนั้นเราจึงมอบเธอให้ตกอยู่ในมือพวกคนรักของเธอ คือในมือคนอัสซีเรียซึ่งเธอลุ่มหลงนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 10, 'ผู้เหล่านี้เผยความเปลือยเปล่าของเธอ เขาจับบุตรชายหญิงของเธอ และฆ่าเธอเสียด้วยดาบ เธอจึงเป็นคําเยาะเย้ยท่ามกลางผู้หญิงทั้งหลาย ในเมื่อได้พิพากษาลงโทษเธอแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 11, 'เมื่อโอโฮลีบาห์น้องสาวของเธอเห็นเช่นนั้น เธอก็ทรามเสียยิ่งกว่าพี่สาวในเรื่องการลุ่มหลง และในการเล่นชู้ซึ่งทรามเสียยิ่งกว่าพี่สาว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 12, 'เธอลุ่มหลงอัสซีเรียเพื่อนบ้านของเธอ เจ้าเมืองและผู้บังคับบัญชา ซึ่งแต่งเกราะเต็ม พลม้าขี่ม้า ทุกคนเป็นชายหนุ่มที่พึงปรารถนา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 13, 'และเราเห็นว่าเธอมีมลทินเสียแล้ว เธอทั้งสองก็เดินทางเดียวกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 14, 'แต่เธอยังเล่นชู้ยิ่งขึ้น เมื่อเธอเห็นรูปคนอยู่บนผนัง เป็นรูปคนเคลเดียเขียนด้วยสีแดงเข้ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 15, 'มีเข็มขัดคาดเอว มีผ้าโพกศีรษะชายห้อยอยู่ ทุกคนเป็นเหมือนนายทหาร เป็นรูปชาวบาบิโลน ซึ่งแผ่นดินเดิมของเขาคือเคลเดีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 16, 'เมื่อเธอเห็นรูปนั้นก็ลุ่มหลงเขาเสียแล้ว และส่งผู้สื่อสารไปหาเขาที่เคลเดีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 17, 'ชาวบาบิโลนก็มาหาเธอถึงเตียงรัก และเขาก็กระทําให้เธอเป็นมลทินด้วยราคะของเขา หลังจากที่เธอโสโครกกับเขาแล้ว จิตใจเธอก็เบื่อหน่าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 18, 'เมื่อเธอได้ทําการเล่นชู้เสียอย่างเปิดเผย และเธอสําแดงความเปลือยเปล่าของเธอ จิตใจเราก็เบื่อหน่ายเธอ อย่างที่จิตใจเราเบื่อหน่ายพี่สาวของเธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 19, 'ถึงกระนั้นเธอยังทวีการเล่นชู้ของเธอขึ้นอีก โดยหวนระลึกถึงเมื่อครั้งยังสาวอยู่ เมื่อเธอเล่นชู้อยู่ในแผ่นดินอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 20, 'เพราะเธอลุ่มหลงชู้ของเธอที่นั่น ลําเนื้อของเขาก็เหมือนของลา และของของเขาก็เหมือนของม้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 21, 'ดังนี้แหละ เจ้าก็อาลัยในราคะเมื่อเจ้ายังสาวอยู่ เมื่อคนอียิปต์จับต้องอกของเจ้า และเคล้าคลึงหัวนมสาวของเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 22, 'เพราะฉะนั้น โอ โอโฮลีบาห์เอ๋ย องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า “ดูเถิด เราจะเร้าคนรักที่จิตใจเจ้าเบื่อหน่ายแล้วนั้นให้มาสู้เจ้า และเราจะนําเขามาสู้เจ้าจากทุกด้าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 23, 'มีคนบาบิโลน และคนเคลเดียทั้งสิ้น เปโขดและโชอา และโคอา ทั้งคนอัสซีเรียทั้งสิ้นด้วย เป็นคนหนุ่มที่พึงปรารถนา เจ้าเมือง ผู้บังคับบัญชาทั้งสิ้น เป็นนายทหารและผู้มีชื่อเสียง ทุกคนขี่ม้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 24, 'เขาจะมาต่อสู้เจ้า มีรถรบ เกวียนและล้อเลื่อน และชนชาติทั้งหลายเป็นอันมาก เขาจะตั้งตนต่อสู้เจ้าทุกด้าน ด้วยดั้งและโล่ และหมวกเหล็ก และเราจะมอบการพิพากษาต่อหน้าเขา และเขาทั้งหลายจะพิพากษาเจ้าตามหลักการพิพากษาของเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 25, 'และเราจะมุ่งความร้อนรนของเราต่อสู้เจ้า และเขาจะกระทํากับเจ้าด้วยความเกรี้ยวกราด เขาจะตัดจมูกและตัดหูของเจ้าออกเสีย และผู้ที่รอดตายจะล้มลงด้วยดาบ เขาจะจับบุตรชายและบุตรสาวของเจ้า และคนที่รอดตายของเจ้าจะถูกเผาด้วยไฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 26, 'เขาจะถอดเอาเสื้อของเจ้าออก และนําเอาเครื่องรูปพรรณงามๆของเจ้าไปเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 27, 'เราจะให้ราคะและการเล่นชู้ซึ่งเจ้านํามาจากแผ่นดินอียิปต์สูญสิ้นลง เพื่อเจ้าจะมิได้เงยหน้าขึ้นดูคนอียิปต์ และระลึกถึงเขาอีกต่อไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 28, 'เพราะองค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า ดูเถิด เราจะมอบเจ้าไว้ในมือของผู้ที่เจ้าเกลียดชัง ในมือของผู้เหล่านั้นที่จิตใจเจ้าเบื่อหน่าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 29, 'และเขาทั้งหลายจะกระทํากับเจ้าด้วยความเกลียดชัง และจะริบเอาบรรดาผลแห่งการงานของเจ้าไปเสีย และจะทิ้งเจ้าไว้ให้เปลือยเปล่าและล่อนจ้อน จะต้องเปิดเผยความเปลือยเปล่า ราคะและการเล่นชู้ของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 30, 'เราจะกระทําสิ่งเหล่านี้แก่เจ้า เพราะเจ้าเล่นชู้ตามประชาชาติ และเพราะเจ้ากระทําตัวของเจ้าให้มัวหมองไปด้วยรูปเคารพของเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 31, 'เจ้าดําเนินตามทางแห่งพี่สาวของเจ้า เพราะฉะนั้นเราจะมอบถ้วยของเธอใส่มือเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 32, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า เจ้าจะต้องดื่มจากถ้วยของพี่สาวเจ้า ซึ่งลึกและใหญ่ เจ้าจะเป็นที่หัวเราะเยาะและถูกสบประมาทเพราะถ้วยนั้นจุมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 33, 'เจ้าจะเต็มไปด้วยความมึนเมาและความเศร้าโศกเสียใจ ด้วยถ้วยแห่งความน่าสะพรึงกลัวและการรกร้างว่างเปล่า ถ้วยแห่งสะมาเรียพี่สาวของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 34, 'เจ้าจะดื่มและดื่มจนเกลี้ยง เจ้าจะแทะเศษถ้วยและฉีกอกของเจ้าเสีย เพราะเราได้ลั่นวาจาแล้ว องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 35, 'เพราะฉะนั้น องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า เพราะเจ้าลืมเราและเหวี่ยงเราไปไว้เบื้องหลังเจ้าเสีย เพราะฉะนั้นเจ้าจงรับโทษราคะและการเล่นชู้ของเจ้าเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 36, 'พระเยโฮวาห์ตรัสกับข้าพเจ้ายิ่งกว่านั้นอีกว่า “บุตรแห่งมนุษย์เอ๋ย เจ้าจะพิพากษาโอโฮลาห์และโอโฮลีบาห์หรือ จงประกาศให้เขาทราบถึงการกระทําอันน่าสะอิดสะเอียนของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 37, 'เพราะว่าเธอได้กระทําการล่วงประเวณี และโลหิตอยู่ในมือของเธอ เธอกระทําการล่วงประเวณีกับรูปเคารพของเธอ และเธอยังถวายบุตรชายซึ่งเธอบังเกิดให้แก่เรานั้นให้ลุยไฟเพื่อเผาผลาญเขาเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 38, 'ยิ่งกว่านั้นอีก เธอได้กระทําเช่นนี้แก่เรา คือเธอได้กระทําให้สถานบริสุทธิ์ของเราเป็นมลทินในวันเดียวกัน และลบหลู่วันสะบาโตของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 39, 'คือขณะเมื่อเธอฆ่าลูกของเธอเป็นเครื่องบูชารูปเคารพ ในวันนั้นเธอก็เข้ามาในสถานบริสุทธิ์ของเรา และกระทําสถานที่นั้นให้เป็นมลทิน ดูเถิด เธอกระทําสิ่งเหล่านี้ในนิเวศของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 40, 'ยิ่งกว่านั้นอีก เธอยังได้ให้ไปหาผู้ชายมาจากเมืองไกล คือเธอใช้ผู้สื่อสารไปหา และดูเถิด เขาก็มา เธอก็ชําระตัวของเธอ เธอทาตาของเธอ และแต่งกายของเธอด้วยเครื่องประดับ เพื่อคนเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 41, 'เธอนั่งอยู่บนตั่งอันสูงศักดิ์ มีโต๊ะวางอยู่ข้างหน้า ซึ่งเป็นโต๊ะที่เจ้าได้วางเครื่องหอมและน้ํามันของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 42, 'เสียงของประชาชนที่ปล่อยตัวก็ดังอยู่กับเธอพร้อมกับคนสามัญ เขานําคนเส-บามาจากถิ่นทุรกันดารด้วย และเขาเอากําไลมือสวมที่มือของผู้หญิง และสวมมงกุฎงามๆบนศีรษะของเธอทั้งสอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 43, 'เราจึงกล่าวเรื่องเธอ ผู้ที่ร่วงโรยโดยการล่วงประเวณีว่า เขายังเล่นชู้กับเธอหรือ และเธอยังเล่นชู้กับเขาหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 44, 'เพราะชายเหล่านั้นยังเข้าหาเธอ อย่างเดียวกับผู้ชายเข้าหาหญิงที่เป็นโสเภณี ดังนั้นเขาก็เข้าหาโอโฮลาห์กับโอโฮลีบาห์ซึ่งเป็นหญิงมีราคะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 45, 'แต่คนชอบธรรมจะพิพากษาเธอด้วยคําพิพากษาอันควรตกแก่หญิงผู้ล่วงประเวณี และด้วยคําพิพากษาอันควรตกแก่หญิงผู้กระทําให้โลหิตตก เพราะเธอเป็นหญิงล่วงประเวณี และเพราะโลหิตอยู่ในมือของเธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 46, 'เพราะองค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า จงนํากองทัพมาสู้กับเธอทั้งสองนี้ และเราจะมอบเธอไว้แก่ความครั่นคร้ามและการถูกริบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 47, 'และกองทัพจะเอาหินขว้างเธอ และฆ่าเธอเสียด้วยดาบ เขาจะฆ่าบุตรชายหญิงของเธอ และเผาเรือนทั้งหลายของเธอเสียด้วยไฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 48, 'ดังนี้แหละ เราจะให้ราคะในแผ่นดินนั้นสูญสิ้นเสียที เพื่อผู้หญิงทั้งหลายจะได้รับความตักเตือนและไม่ประพฤติราคะอย่างที่เจ้าได้กระทําแล้วนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 49, 'ส่วนราคะของเจ้านั้นเจ้าจะต้องรับโทษ และเจ้าจะต้องรับโทษเรื่องการบูชารูปเคารพอย่างบาปหนาของเจ้า และเจ้าจะทราบว่าเราคือองค์พระผู้เป็นเจ้าพระเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 1, 'เมื่อวันที่สิบเดือนที่สิบปีที่เก้า พระวจนะของพระเยโฮวาห์มายังข้าพเจ้าอีกว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 2, '“บุตรแห่งมนุษย์เอ๋ย จงเขียนชื่อของวันนี้ไว้ วันนี้ทีเดียว กษัตริย์บาบิโลนล้อมเยรูซาเล็มในวันนี้เอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 3, 'และจงกล่าวคําอุปมาแก่วงศ์วานที่มักกบฏ และพูดกับเขาว่า องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า จงตั้งหม้อไว้ ตั้งไว้ซิ เทน้ําใส่หม้อด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 4, 'ใส่ชิ้นเนื้อเข้าไป เอาชิ้นเนื้อดีๆ คือเนื้อโคนขาและเนื้อสันขาหน้า เลือกกระดูกดีมาใส่ให้เต็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 5, 'จงเลือกแกะที่ดีที่สุดมาตัวหนึ่ง ใช้กระดูกเหล่านั้นเป็นฟืนไว้ใต้นั้น จงต้มให้ดี เพื่อเคี่ยวกระดูกที่อยู่ในนั้นด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 6, 'เพราะฉะนั้น องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า วิบัติแก่กรุงที่ชุ่มโลหิต วิบัติแก่หม้อที่ขึ้นสนิมข้างในและซึ่งสนิมมิได้หลุดออกมา จงเอาเนื้อออกทีละชิ้นๆ อย่าจับฉลากเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 7, 'เพราะว่าโลหิตที่เธอกระทําให้ตกนั้นยังอยู่ท่ามกลางเธอ เธอวางไว้บนหิน เธอมิได้เทลงดิน เพื่อเอาฝุ่นกลบไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 8, 'เราได้วางโลหิตที่เธอทําให้ตกนั้นไว้บนก้อนหิน เพื่อมิให้ปิดโลหิตนั้นไว้ เพื่อเร้าความพิโรธ และทําการแก้แค้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 9, 'เพราะฉะนั้น องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า วิบัติแก่กรุงที่ชุ่มโลหิต เราจะกระทําให้กองไฟนั้นใหญ่ขึ้นด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 10, 'จงสุมฟืนเข้าไปและก่อไฟขึ้น ต้มเนื้อให้ดี แล้วปรุงแต่งให้อร่อย และปล่อยกระดูกให้ไหม้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 11, 'และวางหม้อเปล่าไว้บนถ่าน เพื่อให้ทองเหลืองนั้นร้อนและไหม้ ให้ความโสโครกละลายเสียในนั้น ให้สนิมของมันไหม้ไฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 12, 'เธอกระทําตัวของเธอเหนื่อยด้วยการมุสาต่างๆ สนิมที่หนาของเธอก็ไม่หลุดออกไปจากเธอ สนิมนั้นจะต้องอยู่ในไฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 13, 'ราคะของเจ้าโสโครก เพราะว่าเราได้ชําระเจ้าแล้ว แต่เจ้าไม่ชําระตัว เจ้าจะไม่ถูกชําระจากความโสโครกของเจ้าอีกต่อไป จนกว่าเราจะระบายความเกรี้ยวกราดของเราออกเหนือเจ้าจนหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 14, 'เราคือพระเยโฮวาห์ได้ลั่นวาจาแล้ว จะเป็นไปอย่างนั้น เราจะกระทําเช่นนั้น เราจะไม่ถอยกลับ เราจะไม่สงวนไว้ และเราจะไม่เปลี่ยนใจ เขาจะพิพากษาเจ้าตามวิธีการและการกระทําของเจ้า องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้แหละ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 15, 'พระวจนะของพระเยโฮวาห์มายังข้าพเจ้าอีกว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 16, '“บุตรแห่งมนุษย์เอ๋ย ดูเถิด เราจะเอาสิ่งที่พอตาของเจ้าไปเสียจากเจ้าด้วยการประหารเสียแล้ว ถึงกระนั้นเจ้าก็อย่าคร่ําครวญหรือร้องไห้ หรือให้น้ําตาตก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 17, 'จงอดกลั้น ไม่คร่ําครวญเถิด อย่าไว้ทุกข์ให้คนที่ตาย จงโพกผ้าของเจ้า และสวมรองเท้าของเจ้า อย่าปิดริมฝีปากหรือรับประทานอาหารของมนุษย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 18, 'ดังนั้นข้าพเจ้าจึงพูดกับประชาชนตอนเช้า และภรรยาของข้าพเจ้าก็สิ้นชีวิตตอนเย็น รุ่งเช้าขึ้นข้าพเจ้าก็กระทําอย่างที่ข้าพเจ้ารับพระบัญชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 19, 'ประชาชนก็ถามข้าพเจ้าว่า “ท่านจะไม่บอกเราทั้งหลายหรือว่า สิ่งนี้มีความหมายอะไรแก่เรา ซึ่งท่านกระทําเช่นนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 20, 'แล้วข้าพเจ้าก็พูดกับเขาว่า “พระวจนะของพระเยโฮวาห์มายังข้าพเจ้าว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 21, 'จงกล่าวแก่วงศ์วานอิสราเอลว่า องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า ดูเถิด เราจะลบหลู่สถานบริสุทธิ์ของเราอันเป็นความล้ําเลิศในอํานาจของเจ้า ความปรารถนาแห่งตาของเจ้า และสิ่งที่จิตวิญญาณของเจ้าห่วงใย บุตรชายหญิงของเจ้าซึ่งเจ้าทิ้งไว้เบื้องหลังจะล้มลงด้วยดาบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 22, 'และเจ้าทั้งหลายจะกระทําอย่างที่เรากระทํา เจ้าจะไม่ปิดริมฝีปาก หรือรับประทานอาหารของมนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 23, 'ผ้าโพกจะอยู่บนศีรษะของเจ้า และรองเท้าจะอยู่ที่เท้าของเจ้า เจ้าจะไม่ไว้ทุกข์หรือร้องไห้ แต่เจ้าจะทรุดลงเพราะความชั่วช้าของเจ้า และจะโอดครวญแก่กันและกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 24, 'เอเสเคียลจะเป็นเครื่องหมายสําคัญแก่เจ้าทั้งหลาย ดังนี้เขาได้กระทําสิ่งใด เจ้าจะกระทําอย่างนั้นทุกอย่าง เมื่อเหตุการณ์เหล่านี้มาถึง เจ้าจะได้ทราบว่า เราคือองค์พระผู้เป็นเจ้าพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 25, 'และเจ้า บุตรแห่งมนุษย์เอ๋ย ในวันที่เราเอาที่กําบังเข้มแข็งของเขาทั้งหลายออกไป อันเป็นความร่าเริงและเป็นสง่าราศีของเขา สิ่งที่พอตาของเขาทั้งหลาย และสิ่งที่ใจของเขาปรารถนา ทั้งบุตรชายและบุตรสาวของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 26, 'ในวันนั้น ผู้หนีภัยจะมาหาเจ้า เพื่อจะรายงานข่าวให้เจ้าได้ยินเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 27, 'ในวันนั้น ปากของเจ้าจะหายใบ้ต่อหน้าผู้หนีภัย และเจ้าจะพูดและจะไม่เป็นใบ้อีกต่อไป ดังนั้นเจ้าจะเป็นหมายสําคัญสําหรับเขา และเขาทั้งหลายจะทราบว่าเราคือพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 1, 'พระวจนะของพระเยโฮวาห์มายังข้าพเจ้าอีกว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 2, '“บุตรแห่งมนุษย์เอ๋ย มุ่งหน้าของเจ้าไปยังคนอัมโมน และจงพยากรณ์กล่าวโทษเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 3, 'จงกล่าวแก่คนอัมโมนว่า จงฟังพระวจนะขององค์พระผู้เป็นเจ้าพระเจ้า องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า เพราะเจ้ากล่าวว่า ‘อ้าฮา’ เหนือสถานบริสุทธิ์ของเราเมื่อที่นั้นถูกลบหลู่ และเหนือแผ่นดินอิสราเอลเมื่อแผ่นดินนั้นรกร้างไป และเหนือวงศ์วานยูดาห์เมื่อต้องตกไปเป็นเชลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 4, 'เพราะฉะนั้น ดูเถิด เราจะมอบเจ้าให้แก่ประชาชนทางทิศตะวันออกให้เป็นกรรมสิทธิ์ เขาจะตั้งปราสาททั้งหลายท่ามกลางเจ้า และสร้างที่อยู่ของเขาท่ามกลางเจ้า เขาทั้งหลายจะรับประทานผลไม้ของเจ้า และจะดื่มน้ํานมของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 5, 'เราจะกระทําให้เมืองรับบาห์เป็นทุ่งหญ้าสําหรับอูฐ และทําให้ที่ของคนอัมโมนเป็นคอกสําหรับฝูงแพะแกะ แล้วเจ้าจะทราบว่าเราคือพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 6, 'เพราะองค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า เพราะเจ้าได้ตบมือและกระทืบเท้าและปีติด้วยใจคิดร้ายต่อแผ่นดินอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 7, 'เพราะฉะนั้น ดูเถิด เราได้ยื่นมือของเราออกต่อสู้เจ้า และจะมอบเจ้าไว้แก่ประชาชนทั้งหลายให้เป็นของริบ และเราจะตัดเจ้าออกเสียจากชนชาติทั้งหลาย และเราจะกระทําให้เจ้าพินาศไปจากประเทศต่างๆ เราจะทําลายเจ้า แล้วเจ้าจะทราบว่าเราคือพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 8, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า เพราะโมอับและเสอีร์กล่าวว่า ‘ดูเถิด วงศ์วานยูดาห์ก็เหมือนประชาชาติอื่นๆทั้งสิ้น’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 9, 'เพราะฉะนั้น ดูเถิด เราจะเปิดไหล่เขาโมอับจนไม่มีเมืองเหลือ คือเมืองของเขาจากด้านนั้น สง่าราศีของประเทศนั้น คือเมืองเบธเยชิโมท เมืองบาอัลเมโอนและเมืองคีริยาธาอิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 10, 'เราจะมอบเมืองเหล่านั้นให้แก่ประชาชนทางทิศตะวันออกพร้อมกับคนอัมโมนให้เป็นกรรมสิทธิ์ เพื่อว่าจะไม่มีใครนึกถึงคนอัมโมนอีกในท่ามกลางประชาชาติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 11, 'และเราจะพิพากษาลงโทษโมอับ แล้วเขาทั้งหลายจะทราบว่าเราคือพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 12, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า เพราะว่าเอโดมได้ประพฤติอย่างแก้แค้นต่อวงศ์วานของยูดาห์ และได้กระทําความชั่วนักหนาในการที่แก้แค้นเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 13, 'เพราะฉะนั้น องค์พระผู้เป็นเจ้าพระเจ้าจึงตรัสดังนี้ว่า เราจะเหยียดมือของเราออกเหนือเอโดมด้วย และจะตัดคนและสัตว์ออกเสียจากเมืองนั้น และเราจะกระทําให้เมืองนั้นรกร้างตั้งแต่เมืองเทมาน และชาวเมืองเดดานก็จะล้มลงด้วยดาบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 14, 'และเราจะวางการแก้แค้นของเราลงเหนือเมืองเอโดมด้วยมือของอิสราเอลประชาชนของเรา และเขาจะกระทําตามความกริ้วและความพิโรธของเราในเมืองเอโดม และเขาจะทราบถึงการแก้แค้นของเรา องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 15, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า เพราะว่าคนฟีลิสเตียได้กระทําอย่างแก้แค้น และทําการแก้แค้นด้วยใจคิดร้ายหมายทําลาย เพราะเกลียดชังแต่หนหลัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 16, 'เพราะฉะนั้นองค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า ดูเถิด เราจะเหยียดมือของเราออกเหนือคนฟีลิสเตีย และเราจะตัดคนเคเรธีออก และทําลายคนที่เหลืออยู่ตามฝั่งทะเลนั้นเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 17, 'เราจะกระทําการแก้แค้นใหญ่ยิ่งเหนือเขาด้วยการติเตียนอย่างรุนแรง แล้วเขาจะทราบว่าเราคือพระเยโฮวาห์ เมื่อเราได้วางการแก้แค้นของเราไว้เหนือเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 1, 'อยู่มาในวันต้นเดือนปีที่สิบเอ็ด พระวจนะของพระเยโฮวาห์มายังข้าพเจ้าว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 2, '“บุตรแห่งมนุษย์เอ๋ย เพราะว่าเมืองไทระได้พูดเกี่ยวพันกับเยรูซาเล็มว่า ‘อ้าฮา ประตูเมืองของชนชาติทั้งหลายหักเสียแล้ว มันเปิดกว้างไว้รับข้า มันร้างเปล่าแล้ว ข้าจะบริบูรณ์ขึ้น’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 3, 'เพราะฉะนั้นองค์พระผู้เป็นเจ้าพระเจ้าตรัสว่า ดูเถิด โอ เมืองไทระเอ๋ย เราเป็นปฏิปักษ์กับเจ้า และจะนําประชาชาติเป็นอันมากมาต่อสู้เจ้า ดังทะเลกระทําให้คลื่นของมันขึ้นมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 4, 'เขาทั้งหลายจะทําลายกําแพงเมืองไทระ และพังทลายหอคอยของเมืองนั้นเสีย และเราจะขูดดินเสียจากเมืองนั้น กระทําให้อยู่บนยอดของศิลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 5, 'เมืองนั้นจะเป็นที่สําหรับตากอวนอยู่กลางทะเล เพราะเราได้ลั่นวาจาแล้ว องค์พระผู้เป็นเจ้าพระเจ้าได้ตรัส และเมืองนั้นจะเป็นของปล้นแห่งบรรดาประชาชาติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 6, 'และพวกธิดาของเมืองนี้ซึ่งอยู่บนแผ่นดินใหญ่จะต้องถูกฆ่าเสียด้วยดาบ แล้วเขาทั้งหลายจะทราบว่าเราคือพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 7, 'เพราะองค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า ดูเถิด เราจะนําเนบูคัดเนสซาร์กษัตริย์บาบิโลน ผู้เป็นจอมกษัตริย์มายังเมืองไทระจากทิศเหนือ พร้อมทั้งม้าและรถรบกับพลม้าและกองทหารกับคนมากมาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 8, 'ท่านจะฆ่าธิดาของเจ้าบนแผ่นดินใหญ่เสียด้วยดาบ ท่านจะก่อกําแพงล้อมเจ้าไว้และก่อเชิงเทินทําด้วยดั้งต่อสู้กับเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 9, 'ท่านจะตั้งเครื่องทะลวงต่อสู้กับกําแพงของเจ้า และท่านจะเอาขวานของท่านฟันหอคอยของเจ้าลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 10, 'ม้าของท่านมากมายจนฝุ่นม้าตลบคลุมเจ้าไว้ กําแพงเมืองของเจ้าจะสั่นสะเทือนด้วยเสียงพลม้าและล้อเลื่อนและรถรบ เมื่อท่านจะยกเข้าประตูเมืองของเจ้า อย่างกับคนเดินเข้าเมืองเมื่อเมืองนั้นแตกแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 11, 'ท่านจะย่ําที่ถนนทั้งปวงของเจ้าด้วยกีบม้า ท่านจะฆ่าชนชาติของเจ้าเสียด้วยดาบ และเสาอันแข็งแรงของเจ้าจะล้มลงถึงดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 12, 'ทรัพย์สมบัติของเจ้าเขาทั้งหลายจะเอาเป็นของริบ และสินค้าของเจ้าเขาจะเอามาเป็นของปล้น เขาจะพังกําแพงของเจ้าลง และจะทําลายบ้านอันพึงใจของเจ้าเสีย หิน ไม้ และดินของเจ้านั้นเขาจะโยนทิ้งเสียกลางน้ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 13, 'เสียงเพลงของเจ้านั้นเราก็จะให้หยุด และเสียงพิณเขาคู่ของเจ้าจะไม่ได้ยินอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 14, 'เราจะกระทําให้อยู่บนยอดของศิลา เจ้าจะเป็นสถานที่สําหรับตากอวน จะไม่มีใครสร้างเจ้าขึ้นใหม่เลย เพราะเราคือพระเยโฮวาห์ได้ลั่นวาจาแล้ว องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 15, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้แก่เมืองไทระว่า เกาะต่างๆจะมิได้สั่นสะเทือนด้วยเสียงที่เจ้าล้ม เมื่อผู้บาดเจ็บร้องครวญคราง เมื่อการเข่นฆ่าได้เกิดอยู่ท่ามกลางเจ้าหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 16, 'แล้วเจ้านายทั้งสิ้นที่ทะเลจะก้าวลงมาจากบัลลังก์และเปลื้องเครื่องทรงออก และปลดเครื่องแต่งตัวที่ปักออกเสีย และจะเอาความสั่นกลัวมาเป็นเครื่องทรง จะประทับอยู่บนพื้นดินและสั่นเทาอยู่ทุกขณะและประหลาดใจเพราะเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 17, 'ท่านเหล่านี้จะเปล่งเสียงบทคร่ําครวญเรื่องเจ้า และกล่าวแก่เจ้าว่า ‘ผู้มีพลเมืองเป็นชาวกะลาสีเอ๋ย เจ้าถูกทําลายแล้ว เจ้าเป็นเมืองที่มีชื่อเสียง เจ้าเป็นเมืองแข็งกล้าอยู่ที่ทะเล ทั้งเจ้าและชาวเมืองของเจ้า ว่าถึงคนที่นั่นแล้วเจ้าให้เขากลัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 18, 'บัดนี้ เกาะทั้งหลายก็จะสั่นสะเทือนในวันที่เจ้าล้มลง เออ บรรดาเกาะที่อยู่ในทะเลก็จะกลัวเพราะเจ้าสิ้นไปเสีย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 19, 'เพราะองค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า เมื่อเราจะกระทําให้เจ้าเป็นเมืองรกร้างเหมือนอย่างเมืองที่ไม่มีคนอาศัย เมื่อเราจะนําทะเลลึกมาท่วมเจ้า และน้ํามากหลายจะคลุมเจ้าไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 20, 'แล้วเราจะนําเจ้าลงไปพร้อมกับคนเหล่านั้นที่ลงไปยังปากแดนคนตายไปอยู่กับคนสมัยเก่า และจะปล่อยให้เจ้าอยู่ที่โลกบาดาล ในสถานที่ที่โดดเดี่ยวอ้างว้างมาแต่โบราณ พร้อมกับผู้ที่ลงไปยังปากแดนคนตาย เพื่อว่าจะไม่มีใครอาศัยอยู่ในเจ้า และเราจะตั้งสง่าราศีในแผ่นดินของคนเป็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 21, 'เราจะกระทําให้เจ้าเป็นที่น่าครั่นคร้าม จะไม่มีเจ้าอีกแล้ว ถึงใครจะมาหาเจ้า เขาจะมาหาเจ้าไม่พบอีกต่อไปเป็นนิตย์ องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้แหละ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 1, 'พระวจนะของพระเยโฮวาห์มายังข้าพเจ้าอีกว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 2, '“เจ้าบุตรแห่งมนุษย์เอ๋ย จงเปล่งเสียงบทคร่ําครวญเรื่องเมืองไทระ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 3, 'และจงกล่าวแก่เมืองไทระ โอ ผู้อยู่ที่ทางเข้าสู่ทะเลเอ๋ย เป็นพ่อค้าแห่งชนชาติทั้งหลายที่อยู่ตามเกาะต่างๆ องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า โอ เมืองไทระเอ๋ย เจ้าได้กล่าวว่า ‘ข้านี้มีความงดงามพร้อมสรรพ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 4, 'พรมแดนของเจ้าอยู่ที่กลางทะเล ผู้ก่อสร้างได้กระทําให้ความงดงามของเจ้าพร้อมสรรพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 5, 'กระดานเรือของเจ้าทั้งสิ้นเขาทําด้วยไม้สนสามใบมาจากเสนีร์ เขาเอาไม้สนสีดาร์มาจากเลบานอนทําเป็นเสากระโดงให้เจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 6, 'เอาไม้โอ๊กแห่งเมืองบาชานมาทําเป็นกรรเชียงของเจ้า หมู่คนอาเชอร์ทําแท่นฝังด้วยงาช้างซึ่งมาจากเกาะคิทธิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 7, 'ส่วนใบของเจ้านั้น ทําด้วยผ้าป่านปักเนื้อละเอียดจากอียิปต์ ส่วนสิ่งที่คลุมไว้เหนือเจ้านั้น เป็นสีฟ้าสีม่วงมาจากเกาะต่างๆแห่งเมืองเอลีชาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 8, 'ชาวเมืองไซดอนและเมืองอารวัดเป็นฝีกรรเชียงของเจ้า โอ ไทระ นักปราชญ์ของเจ้าอยู่ในเจ้า เขาเป็นต้นหนของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 9, 'ผู้ใหญ่ของเมืองเกบาลและนักปราชญ์ของเมืองนี้ก็อยู่ในเจ้าเป็นช่างไม้ประจําเรือให้เจ้า บรรดาเรือทะเลทั้งสิ้นพร้อมกะลาสีก็อยู่ในเจ้าเพื่อแลกเปลี่ยนสินค้ากับเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 10, 'ชาวเปอร์เซีย และลูด และพูต ก็อยู่ในกองทัพของเจ้า เขาทั้งหลายเป็นทหารของเจ้า เขาแขวนโล่และหมวกเหล็กในเจ้า เขากระทําให้เจ้ามีสง่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 11, 'ชาวอารวัดพร้อมกับทหารของเจ้าอยู่บนกําแพงโดยรอบ ชาวกามัดอยู่ในหอคอยของเจ้า เขาแขวนโล่ไว้ตามกําแพงของเจ้าโดยรอบ เขากระทําให้ความงามของเจ้าพร้อมสรรพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 12, 'ทารชิชไปมาค้าขายกับเจ้าเพราะเจ้ามีทรัพยากรมากมายหลายชนิด เขาเอาเงิน เหล็ก ดีบุก และตะกั่วมาแลกเปลี่ยนกับสินค้าของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 13, 'เมืองยาวาน ทูบัลและเมเชค ค้าขายกับเจ้า เขาแลกเปลี่ยนคนและภาชนะทองเหลืองกับสินค้าของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 14, 'วงศ์วานโทการมาห์เอาม้า ม้าศึกและล่อมาแลกกับสินค้าของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 15, 'ชาวเดดานทําการค้าขายกับเจ้า เกาะต่างๆเป็นอันมากเป็นตลาดประจําของเจ้า เขานํางาช้างและไม้มะเกลือมาเป็นค่าของสินค้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 16, 'เมืองซีเรียไปมาค้าขายกับเจ้าเพราะเจ้ามีสินค้าอุดม เขาเอามรกต ผ้าสีม่วง ผ้าปัก ป่านเนื้อละเอียด หินปะการังและโมรามาแลกกับสินค้าของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 17, 'ยูดาห์และแผ่นดินอิสราเอลก็ค้าขายกับเจ้า เขาเอาข้าวสาลีเมืองมินนิทและเมืองปานาง น้ําผึ้ง น้ํามัน พิมเสน มาแลกกับสินค้าของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 18, 'ดามัสกัสไปมาค้าขายกับเจ้าเพราะเจ้ามีสินค้าอุดม เพราะทรัพยากรมากมายหลายชนิดของเจ้า มีเหล้าองุ่นเฮลโบน และขนแกะขาว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 19, 'ดานและยาวานมาแลกกับสินค้าของเจ้า เขาเอาเหล็กหล่อ การบูร ตะไคร้มาแลกกับสินค้าของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 20, 'เมืองเดดานค้าขายกับเจ้าในเรื่องเสื้อผ้าอันมีค่าสําหรับเหล่ารถรบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 21, 'เมืองอาระเบียและเจ้านายทั้งหลายของเมืองเคดาร์ เป็นพ่อค้าขาประจําในเรื่องลูกแกะ แกะผู้ แพะ เขาไปมาค้าขายกับเจ้าในเรื่องเหล่านี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 22, 'พ่อค้าทั้งหลายของเมืองเชบาและเมืองราอามาห์ก็ค้าขายกับเจ้า เขาเอาเครื่องเทศชนิดดีๆทั้งสิ้นและเพชรพลอยทุกชนิด และทองคํามาแลกสินค้ากับเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 23, 'เมืองฮาราน คานเนห์และเอเดน พ่อค้าทั้งหลายของเมืองเชบา อัสชูร และคิลมาดก็ค้าขายกับเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 24, 'เมืองเหล่านี้ทําการค้าขายกับเจ้าในตลาดของเจ้าในเรื่องเครื่องแต่งกายอย่างดีวิเศษ เสื้อสีฟ้าและเสื้อปัก และพรมทําด้วยด้ายสีต่างๆมัดไว้แน่นด้วยด้ายฟั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 25, 'กําปั่นทั้งหลายของเมืองทารชิชบรรทุกสินค้าของเจ้า ดังนั้น เจ้าจึงบริบูรณ์และรุ่งโรจน์อย่างมากในท้องทะเล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 26, 'ฝีกรรเชียงของเจ้านําเจ้าออกไปที่ในทะเลลึก ลมตะวันออกทําให้เจ้าอับปางในท้องทะเล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 27, 'ทรัพย์สินของเจ้า ของขายของเจ้า สินค้าของเจ้า ลูกเรือของเจ้า และต้นหนของเจ้า ช่างไม้ประจําของเจ้า ผู้ค้าสินค้าของเจ้า นักรบทั้งสิ้นของเจ้าผู้อยู่ในเจ้าพร้อมกับพรรคพวกทั้งสิ้นของเจ้าที่อยู่ท่ามกลางเจ้า จะจมลงในท้องทะเลในวันล่มจมของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 28, 'แผ่นดินจะสั่นสะท้านเมื่อได้ยินเสียงโวยวายของต้นหนของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 29, 'บรรดาผู้ที่ถือกรรเชียง พวกลูกเรือและบรรดาต้นหนแห่งทะเลจะลงมาจากเรือของเขา มายืนอยู่บนฝั่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 30, 'และจะพิลาปร่ําไห้เพราะเจ้า และจะร้องไห้หนักหนา เขาจะเหวี่ยงฝุ่นขึ้นศีรษะของเขา และจะกลิ้งเกลือกอยู่ที่กองขี้เถ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 31, 'เขาจะโกนผมเพราะเจ้าและเอาผ้ากระสอบคาดเอวไว้ เขาจะร้องไห้เพราะเจ้าด้วยจิตใจอันขมขื่นกับไว้ทุกข์หนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 32, 'ในการพิลาปร่ําไห้นั้น เขาจะเปล่งเสียงบทคร่ําครวญเพื่อเจ้าและได้ร้องทุกข์เพื่อเจ้าว่า ‘มีเมืองใดหรือที่ถูกทําลายเหมือนเมืองไทระ ในท่ามกลางทะเล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 33, 'เมื่อสินค้าของเจ้ามาจากทะเลก็กระทําให้ชนชาติทั้งหลายเป็นอันมากพอใจ เจ้าได้กระทําให้บรรดากษัตริย์แห่งโลกมั่งคั่ง ด้วยสมบัติและสินค้าอันอุดมของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 34, 'ในเมื่อเจ้าอับปางเสียด้วยทะเลในห้วงน้ําลึก สินค้าของเจ้าและพรรคพวกทั้งหลายของเจ้าจะได้จมลงพร้อมกับเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 35, 'พวกชาวเกาะต่างๆทั้งสิ้นจะตกตะลึงเพราะเจ้า กษัตริย์ทั้งหลายของพวกเขาจะเกรงกลัวยิ่งนัก สีพระพักตร์ของพระองค์ก็ดูวิตกกังวล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 36, 'พ่อค้าท่ามกลางชนชาติทั้งหลายจะเย้ยหยันเจ้า เจ้าจะเป็นสิ่งที่น่าหวาดผวา และจะไม่ดํารงอยู่อีกต่อไปเป็นนิตย์’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 1, 'พระวจนะของพระเยโฮวาห์มายังข้าพเจ้าอีกว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 2, '“บุตรแห่งมนุษย์เอ๋ย จงกล่าวแก่เจ้าเมืองไทระว่า องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า เพราะใจของเจ้าผยองขึ้นและเจ้าได้กล่าวว่า ‘ข้าเป็นพระเจ้า ข้านั่งอยู่ในที่นั่งแห่งพระเจ้าในท้องทะเล’ แต่เจ้าเป็นเพียงมนุษย์ มิใช่พระเจ้า แม้เจ้าจะยึดถือใจของเจ้าว่าเป็นใจของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 3, 'ดูเถิด เจ้าฉลาดกว่าดาเนียลจริง ไม่มีความลับอันใดที่ซ่อนให้พ้นเจ้าได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 4, 'เจ้าหาทรัพย์สมบัติมาสําหรับตนโดยสติปัญญาและความเข้าใจของเจ้า และได้รวบรวมทองคําและเงินมาไว้ในคลังของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 5, 'ด้วยสติปัญญายิ่งใหญ่ในการค้าของเจ้า เจ้าได้ทวีทรัพย์สมบัติของเจ้าขึ้น และจิตใจของเจ้าก็ผยองขึ้นในทรัพย์สมบัติของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 6, 'เพราะฉะนั้น องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า เพราะเจ้ายึดถือใจของเจ้าว่าเป็นใจของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 7, 'เพราะฉะนั้น ดูเถิด เราจะนําคนต่างด้าวมาสู้เจ้า เป็นชนชาติที่ทารุณในบรรดาประชาชาติ เขาทั้งหลายจะชักดาบออกต่อสู้กับความงามแห่งสติปัญญาของเจ้า และเขาจะกระทําให้ความฉลาดปราดเปรื่องของเจ้าเป็นมลทิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 8, 'เขาทั้งหลายจะดันเจ้าลงไปที่ในปากแดนคนตาย และเจ้าจะตายอย่างคนที่ถูกฆ่าในท้องทะเล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 9, 'เจ้ายังจะกล่าวอีกหรือ ว่า ‘ข้าเป็นพระเจ้า’ ต่อหน้าคนที่ฆ่าเจ้า ถึงเจ้าเป็นเพียงมนุษย์ มิใช่พระเจ้า อยู่ในมือของคนที่ฆ่าเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 10, 'เจ้าจะตายอย่างคนที่มิได้เข้าสุหนัตตาย โดยมือของคนต่างด้าว เพราะเราได้ลั่นวาจาแล้ว องค์พระผู้เป็นเจ้าพระเจ้าได้ตรัส”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 11, 'พระวจนะของพระเยโฮวาห์มายังข้าพเจ้าว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 12, '“บุตรแห่งมนุษย์เอ๋ย จงเปล่งเสียงบทคร่ําครวญเพื่อกษัตริย์เมืองไทระ และจงกล่าวแก่ท่านว่า องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า เจ้าเป็นตราแห่งความสมบูรณ์แบบ เต็มด้วยสติปัญญา และมีความงามอย่างพร้อมสรรพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 13, 'เจ้าเคยอยู่ในเอเดน พระอุทยานของพระเจ้า เพชรพลอยทุกอย่างเป็นเสื้อของเจ้า คือทับทิม บุษราคัม เพชร พลอยเขียว พลอยสีน้ําข้าว และหยก ไพทูรย์ มรกต พลอยสีแดงเข้มและทองคํา ความเชี่ยวชาญแห่งรํามะนาและปี่ของเจ้าได้จัดเตรียมไว้ในวันที่สร้างเจ้าขึ้นมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 14, 'เจ้าเป็นเครูบผู้พิทักษ์ที่ได้เจิมตั้งไว้ เราได้ตั้งเจ้าไว้ เจ้าเคยอยู่บนภูเขาบริสุทธิ์แห่งพระเจ้า และเจ้าเคยเดินอยู่ท่ามกลางศิลาเพลิง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 15, 'เจ้าก็ปราศจากตําหนิในวิธีการทั้งหลายของเจ้า ตั้งแต่วันที่เจ้าได้ถูกสร้างขึ้นมาจนพบความชั่วช้าในตัวเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 16, 'ในความอุดมสมบูรณ์แห่งการค้าของเจ้านั้น เจ้าก็เต็มด้วยการทารุณ เจ้ากระทําบาป ดังนั้น โอ เครูบผู้พิทักษ์เอ๋ย เราจะขับเจ้าออกไปจากภูเขาแห่งพระเจ้าดุจสิ่งมลทิน และเราจะกําจัดเจ้าเสียจากท่ามกลางศิลาเพลิง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 17, 'จิตใจของเจ้าผยองขึ้นเพราะความงามของเจ้า เจ้ากระทําให้สติปัญญาของเจ้าเสื่อมทรามลง เพราะเห็นแก่ความงามของเจ้า เราจะเหวี่ยงเจ้าลงที่ดิน เราจะตีแผ่เจ้าต่อหน้ากษัตริย์ทั้งหลาย เพื่อตาของท่านทั้งหลายเหล่านั้นจะเพลินอยู่ที่เจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 18, 'เจ้ากระทําให้สถานบริสุทธิ์ของเจ้าเป็นมลทิน โดยความชั่วช้าเป็นอันมากของเจ้า ในการค้าอันชั่วช้าของเจ้า เหตุฉะนั้นเราจะนําไฟออกมาจากท่ามกลางเจ้า ไฟจะเผาผลาญเจ้า เราจะกระทําให้เจ้าเป็นเถ้าถ่านไปบนแผ่นดินโลกท่ามกลางสายตาของคนทั้งปวงที่มองดูเจ้าอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 19, 'บรรดาผู้ที่รู้จักเจ้าท่ามกลางชนชาติทั้งหลาย เขาจะตกตะลึงเพราะเจ้า เจ้าจะสิ้นสูญลงอย่างน่าครั่นคร้าม และจะไม่ดํารงอยู่อีกต่อไปเป็นนิตย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 20, 'พระวจนะของพระเยโฮวาห์มายังข้าพเจ้าอีกว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 21, '“บุตรแห่งมนุษย์เอ๋ย จงมุ่งหน้าต่อสู้ไซดอน และพยากรณ์กล่าวโทษเมืองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 22, 'และกล่าวว่า องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า ดูเถิด โอ ไซดอนเอ๋ย เราเป็นปฏิปักษ์กับเจ้า เราจะสําแดงสง่าราศีของเราท่ามกลางเจ้า และเขาทั้งหลายจะทราบว่าเราคือพระเยโฮวาห์ เมื่อเราทําการพิพากษาลงโทษในเมืองนั้น และสําแดงความบริสุทธิ์ของเราในเมืองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 23, 'เพราะเราจะส่งโรคระบาดเข้ามาในเมืองนั้น และส่งโลหิตเข้ามาในถนนของเมืองนั้น คนที่ถูกบาดเจ็บจะล้มลงท่ามกลางเมืองนั้น ล้มลงด้วยดาบที่อยู่รอบเมืองนั้นทุกด้าน แล้วเขาทั้งหลายจะทราบว่าเราคือพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 24, 'และส่วนวงศ์วานอิสราเอลนั้น จะไม่มีหนามย่อยที่ทิ่มแทง หรือมีหนามใหญ่มายอกอีก ท่ามกลางคนทั้งปวงซึ่งได้เคยกระทําแก่เขาด้วยความดูหมิ่น แล้วเขาจะทราบว่าเราคือองค์พระผู้เป็นเจ้าพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 25, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า เมื่อเราจะรวบรวมวงศ์วานอิสราเอลจากชนชาติทั้งหลาย ซึ่งเขาได้กระจัดกระจายไปอยู่ท่ามกลางนั้น และเมื่อเราจะสําแดงความบริสุทธิ์ของเราท่ามกลางเขาท่ามกลางสายตาของประชาชาติทั้งหลายแล้ว เขาทั้งหลายจะได้อาศัยอยู่ในแผ่นดินของเขาเอง ซึ่งเราได้มอบให้แก่ยาโคบผู้รับใช้ของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 26, 'และเขาทั้งหลายจะอาศัยอยู่ในที่นั้นอย่างปลอดภัย เออ เขาจะสร้างบ้านเรือนและปลูกสวนองุ่น เมื่อเรากระทําการพิพากษาลงโทษคนทั้งหลายที่อยู่รอบเขา ผู้ได้กระทําต่อเขาด้วยความดูหมิ่นนั้น เขาทั้งหลายจะอาศัยอยู่ด้วยความมั่นใจ แล้วเขาทั้งหลายจะทราบว่า เราคือพระเยโฮวาห์พระเจ้าของเขาทั้งหลาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 1, 'เมื่อวันที่สิบสองเดือนสิบในปีที่สิบ พระวจนะของพระเยโฮวาห์มายังข้าพเจ้าว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 2, '“บุตรแห่งมนุษย์เอ๋ย จงมุ่งหน้าของเจ้าต่อสู้ฟาโรห์กษัตริย์แห่งอียิปต์ พยากรณ์กล่าวโทษกษัตริย์และอียิปต์ทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 3, 'พูดไปเถิดและกล่าวว่า องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า ดูเถิด เราเป็นปฏิปักษ์กับเจ้า ฟาโรห์กษัตริย์แห่งอียิปต์ ผู้เป็นพญานาคมหึมา นอนอยู่กลางแม่น้ําทั้งหลายของมัน ผู้กล่าวว่า ‘แม่น้ําของข้าก็เป็นของข้า ข้าสร้างมันขึ้นเพื่อตัวของข้าเอง’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 4, 'เราจะเอาเบ็ดเกี่ยวขากรรไกรของเจ้า และจะกระทําให้ปลาในแม่น้ําทั้งหลายของเจ้าติดกับเกล็ดของเจ้า และเราจะลากเจ้าขึ้นมาจากกลางแม่น้ําทั้งหลายของเจ้า และบรรดาปลาในแม่น้ําทั้งหลายของเจ้าจะติดอยู่กับเกล็ดของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 5, 'เราจะเหวี่ยงเจ้าเข้าไปในถิ่นทุรกันดาร ทั้งตัวเจ้าและบรรดาปลาในแม่น้ําทั้งหลายของเจ้า เจ้าจะตกลงที่พื้นทุ่ง จะไม่มีใครรวบรวมและฝังเจ้าไว้ เราได้มอบเจ้าไว้ให้เป็นอาหารของสัตว์ป่าดินและของนกในอากาศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 6, 'แล้วคนที่อยู่ในอียิปต์ทั้งสิ้นจะทราบว่า เราคือพระเยโฮวาห์ เพราะเจ้าเป็นไม้เท้าอ้อของวงศ์วานอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 7, 'เมื่อเขาเอามือจับเจ้า เจ้าก็หัก และบาดบ่าของเขาทุกคน และเมื่อเขาพิงเจ้า เจ้าก็โค่น และกระทําให้บั้นเอวของเขาทุกคนสั่นหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 8, 'ดังนั้นองค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า ดูเถิด เราจะนําดาบมาเหนือเจ้า และตัดมนุษย์และสัตว์ให้ขาดจากเจ้าเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 9, 'แผ่นดินอียิปต์จะเป็นที่รกร้างและถูกทิ้งไว้เสียเปล่า แล้วเขาทั้งหลายจะทราบว่า เราคือพระเยโฮวาห์ เพราะเขาได้กล่าวว่า ‘แม่น้ําเป็นของข้า และข้าสร้างมันขึ้นมา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 10, 'เหตุฉะนั้น ดูเถิด เราจะต่อสู้กับเจ้า และกับแม่น้ําทั้งหลายของเจ้า เราจะกระทําให้แผ่นดินอียิปต์ถูกทิ้งไว้เสียเปล่าและรกร้างอย่างสิ้นเชิง ตั้งแต่หอคอยแห่งสิเอเนไกลไปจนถึงพรมแดนเอธิโอเปีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 11, 'จะไม่มีเท้ามนุษย์ข้ามแผ่นดินนั้น และจะไม่มีตีนสัตว์ข้ามแผ่นดินนั้น จะไม่มีใครอาศัยอยู่ถึงสี่สิบปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 12, 'และเราจะกระทําให้แผ่นดินอียิปต์เป็นที่รกร้างท่ามกลางประเทศทั้งหลายที่รกร้างนั้น และหัวเมืองของมันจะรกร้างอยู่สี่สิบปีท่ามกลางหัวเมืองทั้งหลายที่ถูกทิ้งไว้เสียเปล่า เราจะให้คนอียิปต์กระจัดกระจายไปท่ามกลางประชาชาติ และจะกระจายเขาไปตามประเทศต่างๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 13, 'เพราะองค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า เมื่อสิ้นสี่สิบปีแล้ว เราจะรวบรวมคนอียิปต์จากท่ามกลางชนชาติทั้งหลายซึ่งเขากระจัดกระจายไปอยู่ด้วยนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 14, 'และเราจะให้อียิปต์กลับสู่สภาพเดิม และนําเขากลับมายังแผ่นดินปัทโรส ซึ่งเป็นแผ่นดินดั้งเดิมของเขา และเขาทั้งหลายจะเป็นราชอาณาจักรต่ําต้อยที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 15, 'จะเป็นราชอาณาจักรที่ต่ําต้อยที่สุดในบรรดาราชอาณาจักรทั้งหลาย และจะไม่เคยยกตนขึ้นเหนือประชาชาติทั้งหลายอีกเลย เพราะเราจะทําให้เขาเป็นราชอาณาจักรเล็กจนไม่สามารถจะปกครองประชาชาติอื่นได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 16, 'และจะไม่เป็นที่วางใจของวงศ์วานอิสราเอลอีก อันทําให้สํานึกถึงความชั่วช้าของเขาเมื่อหันไปพึ่งพาอียิปต์นี้ แล้วเขาจะทราบว่าเราคือ องค์พระผู้เป็นเจ้าพระเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 17, 'ต่อมาเมื่อวันที่หนึ่ง เดือนที่หนึ่ง ในปีที่ยี่สิบเจ็ด พระวจนะของพระเยโฮวาห์มายังข้าพเจ้าว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 18, '“บุตรแห่งมนุษย์เอ๋ย เนบูคัดเนสซาร์ กษัตริย์แห่งบาบิโลนได้ให้กองทัพมาสู้รบกับเมืองไทระอย่างหนัก จนศีรษะทุกศีรษะล้าน และบ่าทุกบ่าก็ถลอก ถึงกระนั้นท่านเองหรือกองทัพของท่านก็ไม่ได้อะไรไปจากไทระอันเป็นค่าแรงซึ่งท่านได้กระทําต่อเมืองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 19, 'เหตุฉะนั้น องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า ดูเถิด เราจะมอบแผ่นดินอียิปต์ไว้กับเนบูคัดเนสซาร์กษัตริย์แห่งบาบิโลน และท่านจะเอาคนเป็นอันมากของเขาไปและริบข้าวของไป และปล้นเอาไปเป็นค่าจ้างกองทัพของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 20, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสว่า เราได้มอบแผ่นดินอียิปต์ให้ไว้แก่ท่าน เพื่อเป็นค่าแรงงานซึ่งเขาทั้งหลายได้กระทําเพื่อเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 21, 'ในวันนั้นเราจะกระทําให้มีเขางอกขึ้นมาที่วงศ์วานอิสราเอล และเราจะให้เจ้าอ้าปากพูดท่ามกลางเขาทั้งหลาย แล้วเขาจะทราบว่าเราคือพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 1, 'พระวจนะของพระเยโฮวาห์มายังข้าพเจ้าอีกว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 2, '“บุตรแห่งมนุษย์เอ๋ย จงพยากรณ์และกล่าวว่า องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า จงพิลาปร่ําไรเถิดว่า ‘อนิจจาหนอวันนั้น’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 3, 'เพราะวันนั้นใกล้เข้ามาแล้ว วันแห่งพระเยโฮวาห์ใกล้เข้ามา จะเป็นวันมีเมฆ เป็นเวลาที่กําหนดของประชาชาติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 4, 'ดาบเล่มหนึ่งจะมาเหนืออียิปต์ และความแสนระทมจะอยู่ในเอธิโอเปีย เมื่อคนที่ถูกฆ่าจะล้มในอียิปต์ และพวกเขาจะเอาคนเป็นอันมากของประเทศนั้นไปเสีย และรากฐานของเมืองนั้นก็จะถูกทลายลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 5, 'เอธิโอเปีย และลิเบีย และลิเดีย และคนที่ปะปนกันทั้งปวง และชับ และประชาชนแห่งแผ่นดินนั้นที่อยู่ในสันนิบาตจะล้มลงพร้อมกับเขาด้วยดาบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 6, 'พระเยโฮวาห์ตรัสดังนี้ว่า ผู้เหล่านั้นที่สนับสนุนอียิปต์จะล่มจม และอานุภาพอันผยองของมันจะลงมา และจากหอคอยแห่งสิเอเน เขาจะล้มลงภายในประเทศนั้นด้วยดาบ องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 7, 'และมันจะรกร้างอยู่ท่ามกลางประเทศทั้งหลายที่รกร้าง และหัวเมืองของมันจะอยู่ท่ามกลางหัวเมืองทั้งหลายที่ถูกทิ้งไว้เสียเปล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 8, 'และเขาจะทราบว่าเราคือพระเยโฮวาห์ เมื่อเราวางเพลิงที่อียิปต์ และผู้ช่วยทั้งหมดของมันก็ทลายแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 9, 'และในวันนั้นทูตจะลงเรือไปจากเรา เพื่อจะกระทําให้คนเอธิโอเปียที่เลินเล่ออยู่นั้นครั่นคร้าม ความแสนระทมจะมาถึงเขาเหล่านั้น เหมือนในวันกําหนดของอียิปต์ เพราะ ดูเถิด วันนั้นมาถึงจริงๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 10, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า เราจะกระทําให้คนเป็นอันมากของอียิปต์สิ้นสุดลง ด้วยมือของเนบูคัดเนสซาร์กษัตริย์แห่งบาบิโลน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 11, 'ตัวท่านพร้อมกับชนชาติของท่านคือชนชาติที่ทารุณที่สุดในบรรดาประชาชาติ จะถูกนําเข้ามาเพื่อทําลายแผ่นดินนั้น และเขาจะชักดาบออกต่อสู้อียิปต์ กระทําให้แผ่นดินเต็มไปด้วยคนที่ถูกฆ่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 12, 'และเราจะกระทําให้แม่น้ําทั้งหลายแห้งไป เราจะขายแผ่นดินนั้นไว้ในมือของคนชั่ว เราจะกระทําให้แผ่นดินและสารพัดที่อยู่บนแผ่นดินนั้นร้างเปล่าโดยมือของคนต่างด้าว เราคือพระเยโฮวาห์ได้ลั่นวาจาแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 13, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า เราจะทําลายรูปเคารพ และจะกระทําให้ปฏิมากรที่ในเมืองโนฟสิ้นสุดลง และจะไม่มีจ้าวจากแผ่นดินอียิปต์อีก ดังนั้นเราจะใส่ความยําเกรงไว้ในแผ่นดินอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 14, 'เราจะกระทําให้ปัทโรสเป็นที่รกร้าง และจะวางเพลิงในโศอัน และจะกระทําการพิพากษาเมืองโน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 15, 'เราจะเทความเดือดดาลของเราลงบนเมืองสีนซึ่งเป็นขุมกําลังของอียิปต์ และจะตัดเหล่าฝูงชนออกเสียจากเมืองโน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 16, 'และเราจะวางเพลิงในอียิปต์ เมืองสีนจะอยู่ในมหันตทุกข์ เมืองโนจะแตกและเมืองโนฟจะมีปรปักษ์ในเวลากลางวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 17, 'ชายฉกรรจ์ของเมืองอาเวนและเมืองพีเบเสทจะล้มลงด้วยดาบ และเมืองนั้นจะตกไปเป็นเชลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 18, 'ที่เมืองทาปานเหสกลางวันจะมืดเมื่อเราทําลายแอกของอียิปต์ และอานุภาพอันผยองของเมืองนั้นจะสิ้นสุดลง จะมีเมฆมาคลุมเมืองนั้นไว้และเหล่าธิดาของเมืองนั้นจะตกไปเป็นเชลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 19, 'เราจะกระทําการพิพากษาลงโทษอียิปต์ดังนี้แหละ แล้วเขาจะทราบว่าเราคือพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 20, 'ต่อมาเมื่อวันที่เจ็ด เดือนที่หนึ่ง ในปีที่สิบเอ็ด พระวจนะของพระเยโฮวาห์มายังข้าพเจ้าว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 21, '“บุตรแห่งมนุษย์เอ๋ย เราได้กระทําให้แขนของฟาโรห์กษัตริย์แห่งอียิปต์หัก และดูเถิด ไม่มีผู้ใดพันแขนให้ ไม่มีผู้ใดเอาผ้ามาพันแขนเพื่อจะรักษาให้หาย เพื่อให้เข้มแข็งที่จะถือดาบได้อีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 22, 'เหตุฉะนั้น องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า ดูเถิด เราเป็นปฏิปักษ์กับฟาโรห์กษัตริย์แห่งอียิปต์ เราจะหักแขนของเขา ทั้งแขนที่ยังแข็งแรงและแขนที่หักแล้วนั้น เราจะกระทําให้ดาบหลุดจากมือของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 23, 'เราจะให้คนอียิปต์กระจัดกระจายไปอยู่ท่ามกลางประชาชาติ และจะกระจายเขาไปตามประเทศต่างๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 24, 'และเราจะเสริมกําลังแขนของกษัตริย์แห่งบาบิโลน และเอาดาบของเราใส่มือให้ แต่เราจะหักแขนของฟาโรห์ และเขาจะคร่ําครวญต่อหน้าท่านอย่างคนถูกบาดเจ็บเจียนจะตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 25, 'เราจะเสริมกําลังแขนของกษัตริย์แห่งบาบิโลน แต่แขนของฟาโรห์จะตก แล้วเขาทั้งหลายจะทราบว่าเราคือพระเยโฮวาห์ เมื่อเราเอาดาบของเราใส่มือของกษัตริย์แห่งบาบิโลน ท่านจะยื่นมันออกต่อสู้แผ่นดินอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 26, 'และเราจะให้คนอียิปต์กระจัดกระจายไปอยู่ท่ามกลางประชาชาติ และกระจายเข้าไปตามประเทศต่างๆ แล้วเขาจะทราบว่าเราคือพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 1, 'และอยู่มา เมื่อวันที่หนึ่งเดือนที่สาม ในปีที่สิบเอ็ด พระวจนะของพระเยโฮวาห์มายังข้าพเจ้าว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 2, '“บุตรแห่งมนุษย์เอ๋ย จงกล่าวแก่ฟาโรห์กษัตริย์แห่งอียิปต์และแก่หมู่นิกรของท่านว่า ในความเป็นใหญ่เป็นโตของท่านนั้น ท่านเหมือนผู้ใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 3, 'ดูเถิด คนอัสซีเรียเปรียบได้กับไม้สนสีดาร์ในเลบานอน มีกิ่งงามและมีใบร่มและสูงมาก ยอดอยู่ที่ท่ามกลางกิ่งไม้หนาทึบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 4, 'สายน้ําทําให้มันใหญ่ขึ้น น้ําลึกทําให้มันงอกสูง พร้อมกับมีแม่น้ําของสายน้ําลึกนั้นไหลรอบที่ที่ปลูกมันไว้ และก่อให้เกิดสายน้ําเล็กๆ จากแม่น้ําลึกแยกออกไปทั่วต้นไม้ทั้งสิ้นในทุ่งนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 5, 'ดังนั้นมันจึงสูงเหนือต้นไม้ในป่าทั้งหลาย กิ่งไม้ก็แตกใหญ่และก้านก็ยาว เพราะน้ํามากหลายเมื่อให้งอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 6, 'นกในอากาศทั้งสิ้นได้มาทํารังอยู่ในกิ่งของมัน สัตว์ป่าทุ่งทั้งสิ้นตกลูกออกมาอยู่ใต้ก้าน ประชาชาติใหญ่โตทั้งสิ้นอาศัยอยู่ใต้ร่มของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 7, 'มันก็งดงามด้วยความใหญ่ยิ่งของมัน ด้วยความยาวแห่งก้านของมัน เพราะรากของมันหยั่งลึกลงไปยังน้ําอุดม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 8, 'ต้นสนสีดาร์ที่อยู่ในอุทยานของพระเจ้าก็ซ่อนมันไว้ไม่ได้ ต้นสนสามใบก็ยังไม่เปรียบปานกิ่งใหญ่ของมัน ต้นเกาลัดก็ไม่เปรียบปานกิ่งของมัน ไม่มีไม้ต้นใดในอุทยานของพระเจ้าที่มีความงามเหมือนมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 9, 'เราได้กระทําให้มันงามด้วยกิ่งก้านมากมายของมัน ต้นไม้ทั้งสิ้นในสวนเอเดนก็อิจฉามัน คือต้นไม้ซึ่งอยู่ในอุทยานของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 10, 'เพราะฉะนั้น องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า เพราะว่ามันสูงและชูยอดของมันขึ้นอยู่ท่ามกลางกิ่งไม้หนาทึบ และจิตใจของมันก็เย่อหยิ่งเพราะความสูงของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 11, 'เราจึงมอบมันไว้ในมือของผู้หนึ่งที่ทรงอานุภาพในบรรดาประชาชาติ ท่านนั้นจะจัดการกับมันเป็นแน่ เราได้ไล่มันออกเพราะความชั่วร้ายของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 12, 'คนต่างด้าว คือชนชาติที่น่ากลัวในบรรดาประชาชาติ ได้โค่นมันลงและทิ้งไว้ กิ่งของมันตกลงบนภูเขาทั้งหลายและในหุบเขาทั้งสิ้น และก้านของมันก็หักอยู่ตามแม่น้ําลําธารทั้งสิ้นของแผ่นดินนั้น และบรรดาชนชาติทั้งหลายในแผ่นดินโลกก็ลงไปเสียจากร่มเงาของมันและทิ้งมันไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 13, 'นกในอากาศทั้งสิ้นจะอาศัยอยู่บนสิ่งปรักหักพังของมัน และสัตว์ป่าทุ่งทั้งปวงจะอยู่บนก้านของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 14, 'ที่เป็นเช่นนี้ก็เพื่อบรรดาต้นไม้ที่อยู่ริมน้ําจะไม่งอกขึ้นสูงนัก หรือชูยอดขึ้นท่ามกลางกิ่งไม้หนาทึบ และเพื่อไม่ให้บรรดาต้นไม้ที่ดูดน้ําขึ้นสูงอย่างนั้นได้ เพราะว่ามันทั้งหลายต้องมอบให้แก่ความตาย มอบให้แก่โลกบาดาล ท่ามกลางบุตรทั้งหลายของมนุษย์กับผู้ที่ได้ลงไปยังปากแดนคนตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 15, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า ในวันที่มันลงไปยังแดนคนตาย เรากระทําให้บาดาลคลุมตัวไว้ทุกข์ให้มัน และยับยั้งแม่น้ําของมันไว้ และน้ําเป็นอันมากจะหยุดยั้ง เราคลุมเลบานอนไว้ให้กลุ้มอยู่เพื่อมัน และต้นไม้ในทุ่งนาทั้งสิ้นจะสลบเพราะมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 16, 'เรากระทําให้ประชาชาติสั่นสะเทือนด้วยเสียงที่มันล้ม เมื่อเราเหวี่ยงมันลงไปที่นรกพร้อมกับบรรดาผู้ที่ลงไปยังปากแดน และต้นไม้ทั้งสิ้นในเอเดน ต้นไม้ที่คัดเลือกแล้วและต้นไม้ที่ดีที่สุดของเลบานอน ต้นไม้ทุกต้นที่ดื่มน้ําจะได้รับความเล้าโลมที่ในโลกบาดาล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 17, 'ประชาชาติเหล่านี้จะลงไปยังนรกกับเขาด้วย ไปอยู่กับบรรดาผู้ที่ถูกฆ่าด้วยดาบ เออ คือบรรดาผู้ที่เป็นเหมือนแขนของเขา ที่อยู่ใต้ร่มของเขาท่ามกลางประชาชาติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 18, 'ดังนี้ เจ้าเหมือนผู้ใดในเรื่องสง่าราศีและความเป็นใหญ่ท่ามกลางต้นไม้แห่งเอเดน เจ้าจะถูกนําลงมาพร้อมกับต้นไม้แห่งเอเดนไปยังโลกบาดาล เจ้าจะนอนอยู่ท่ามกลางผู้ที่มิได้เข้าสุหนัต พร้อมกับผู้ที่ถูกฆ่าด้วยดาบ นี่คือฟาโรห์และบรรดาหมู่นิกรทั้งสิ้นของท่าน องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 1, 'ต่อมาเมื่อวันที่หนึ่ง เดือนที่สิบสอง ในปีที่สิบสอง พระวจนะของพระเยโฮวาห์มายังข้าพเจ้าว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 2, '“บุตรแห่งมนุษย์เอ๋ย จงเปล่งเสียงบทคร่ําครวญเรื่องฟาโรห์กษัตริย์แห่งอียิปต์ และกล่าวให้ท่านฟังดังนี้ว่า ท่านเหมือนสิงโตหนุ่มท่ามกลางประชาชาติ แต่ท่านเป็นเหมือนปลาวาฬในทะเลทั้งหลาย ท่านเผ่นออกมาในแม่น้ําทั้งหลายของท่าน เอาเท้าของท่านกวนน้ําและกระทําแม่น้ําของมันให้มลทินไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 3, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า เราจะกางข่ายของเราคลุมท่านโดยกองทัพชนชาติทั้งหลายเป็นอันมาก และเขาเหล่านั้นจะลากท่านขึ้นมาด้วยอวนของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 4, 'และเราจะเหวี่ยงท่านลงบนดิน และเราจะฟัดท่านลงบนพื้นทุ่ง และจะกระทําให้นกทั้งสิ้นในอากาศมาจับอยู่บนท่าน และเราจะให้สัตว์ทั่วทั้งโลกได้อิ่มหนําด้วยตัวท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 5, 'เราจะเอาเนื้อของท่านเกลี่ยไว้บนภูเขา และถมหุบเขาด้วยศพของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 6, 'เราจะให้แผ่นดินถึงแม้ภูเขาชุ่มโชกด้วยเลือดกําลังไหลของท่าน และห้วยจะเต็มไปด้วยท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 7, 'เมื่อเราดับท่าน เราจะคลุมฟ้าสวรรค์ไว้ และกระทําให้ดวงดาวมืดไป เราจะเอาเมฆบังดวงอาทิตย์ และดวงจันทร์จะไม่ทอแสง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 8, 'แสงสุกใสทั้งสิ้นแห่งสวรรค์นั้นเราจะกระทําให้มืดอยู่เหนือท่าน และวางความมืดไว้เหนือแผ่นดินของท่าน องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 9, 'เมื่อเราทําลายท่านท่ามกลางประชาชาติในประเทศซึ่งท่านไม่รู้จักนั้น เราจะกระทําให้จิตใจของชนชาติทั้งหลายเป็นอันมากลําบาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 10, 'เออ เมื่อเราแกว่งดาบของเราต่อหน้าเขาทั้งหลาย เราจะกระทําให้ชนชาติทั้งหลายเป็นอันมากแลตะลึงที่ท่าน และกษัตริย์ของเขาทั้งหลายจะสะทกสะท้านเพราะท่าน ในวันที่ท่านล้มลงนั้น เขาทั้งหลายจะตัวสั่นทุกขณะจิตทั่วกันเพราะห่วงชีวิตของตนเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 11, 'เพราะองค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า ดาบของกษัตริย์แห่งบาบิโลนจะมาเหนือท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 12, 'เราจะทําให้หมู่นิกรของท่านล้มลงด้วยดาบของผู้มีกําลัง ทุกคนก็ล้วนเป็นที่ทารุณที่สุดในบรรดาประชาชาติ เขาจะนําความทะเยอทะยานของอียิปต์ให้มาถึงที่สิ้นสุด และหมู่นิกรทั้งสิ้นของมันจะพินาศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 13, 'เราจะทําลายสัตว์ของเมืองนั้นทั้งสิ้น จากข้างน้ํามากหลายและไม่มีเท้ามนุษย์คนใดกระทําให้น้ํานั้นขุ่นอีก กีบสัตว์ก็จะไม่กระทําให้น้ํานั้นขุ่นอีกเช่นกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 14, 'แล้วเราจะทําให้น้ําของเขาทั้งหลายลึก และกระทําให้แม่น้ําทั้งหลายของเขาไหลไปเหมือนน้ํามันไหล องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 15, 'เมื่อเรากระทําให้แผ่นดินอียิปต์รกร้าง และประเทศนั้นจะขาดสิ่งที่เคยอุดมสมบูรณ์ เมื่อเราฟาดฟันคนทั้งปวงที่อาศัยอยู่ในประเทศนั้น แล้วเขาทั้งหลายจะทราบว่าเราคือพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 16, 'นี่เป็นบทคร่ําครวญที่จะร้องคร่ําครวญ เหล่าธิดาแห่งประชาชาติจะร้องบทนั้น เขาจะร้องเรื่องอียิปต์และหมู่นิกรของอียิปต์ องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้แหละ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 17, 'ต่อมาเมื่อวันที่สิบห้า เดือนที่สิบสอง ในปีที่สิบสอง พระวจนะของพระเยโฮวาห์มายังข้าพเจ้าว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 18, '“บุตรแห่งมนุษย์เอ๋ย จงพิลาปร่ําไห้เพื่อคนเป็นอันมากของอียิปต์ และจงส่งเขาลงไป ทั้งตัวเขาและเหล่าธิดาแห่งประชาชาติที่โอ่อ่าไปยังโลกบาดาล ไปยังบรรดาคนเหล่านั้นที่ไปยังปากแดนคนตายแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 19, 'ในเรื่องความงาม ท่านงามล้ํากว่าผู้ใดๆหรือ จงลงไป ไปนอนกับผู้ที่ไม่ได้เข้าสุหนัต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 20, 'เขาทั้งหลายจะล้มลงกลางบรรดาผู้ที่ถูกฆ่าด้วยดาบ มีดาบกําหนดไว้แล้ว จงลากอียิปต์ไปเสียพร้อมกับหมู่นิกรทั้งสิ้นของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 21, 'เหล่าชายฉกรรจ์ในบรรดาผู้ที่แกล้วกล้าจะพูดเรื่องของเขากับผู้ช่วยของเขาจากกลางนรกว่า ‘เขาได้ลงมาแล้ว เขานอนอยู่ คือคนที่ไม่ได้เข้าสุหนัต ที่ถูกฆ่าด้วยดาบ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 22, 'อัสชูรก็อยู่ที่นั่นรวมทั้งคณะ มีหลุมศพอยู่รอบตัว ทุกคนถูกฆ่าและล้มลงด้วยดาบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 23, 'ที่ฝังศพของคนเหล่านี้อยู่ที่แดนมรณาส่วนที่ไกลที่สุด และคณะของเธอก็อยู่รอบหลุมฝังศพของเธอ ทุกคนถูกฆ่า ล้มลงด้วยดาบ เป็นพวกที่ให้เกิดความครั่นคร้ามในแผ่นดินของคนเป็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 24, 'เอลามก็อยู่ที่นั่น ทั้งหมู่นิกรทั้งสิ้นก็อยู่รอบหลุมศพของเธอ ทุกคนถูกฆ่า และล้มลงด้วยดาบ ผู้ลงไปสู่โลกบาดาลโดยไม่เข้าสุหนัต เป็นพวกที่ให้เกิดความครั่นคร้ามในแผ่นดินของคนเป็น และเขาต้องทนรับความอับอายขายหน้ากับผู้ที่ลงไปปากแดนคนตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 25, 'เขาได้ทําที่ให้เธอนอนในหมู่พวกผู้ที่ถูกฆ่าพร้อมกับหมู่นิกรทั้งสิ้นของเธอ มีหลุมศพอยู่รอบตัว เป็นผู้ที่ไม่ได้เข้าสุหนัตทุกคน ถูกฆ่าด้วยดาบ เพราะว่าเขาให้เกิดความครั่นคร้ามในแผ่นดินของคนเป็น และเขาต้องทนรับความอับอายขายหน้ากับผู้ที่ลงไปยังปากแดนคนตาย เขามีที่อยู่ในหมู่พวกผู้ถูกฆ่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 26, 'เมเชคกับทูบัลก็อยู่ที่นั่น ทั้งหมู่นิกรทั้งสิ้นของเธอ หลุมศพของเธอทั้งสองอยู่รอบเขา เป็นผู้ที่ไม่เข้าสุหนัตทุกคน ถูกฆ่าด้วยดาบ เพราะเขาให้เกิดความครั่นคร้ามในแผ่นดินของคนเป็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 27, 'เขาทั้งหลายจะไม่ได้นอนอยู่กับผู้แกล้วกล้าในจําพวกที่ไม่ได้เข้าสุหนัตที่ได้ล้มลง ลงไปยังนรกพร้อมกับยุทโธปกรณ์ของเขา ผู้ซึ่งมีดาบวางไว้ใต้ศีรษะของเขา และความชั่วช้าก็อยู่บนกระดูกของเขา เพราะว่าเขาให้ผู้แกล้วกล้าครั่นคร้ามอยู่ในแผ่นดินของคนเป็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 28, 'ดังนั้นท่านจะต้องถูกหักในหมู่พวกผู้ที่ไม่ได้เข้าสุหนัต และนอนอยู่กับคนเหล่านั้นที่ถูกฆ่าด้วยดาบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 29, 'เอโดมก็อยู่ที่นั่น คือบรรดากษัตริย์และบรรดาเจ้านายทั้งหลายของเธอ แม้ว่าเขาทั้งหลายมีอานุภาพ เขายังถูกนํามาวางไว้กับบรรดาคนเหล่านั้นที่ถูกฆ่าด้วยดาบ เขาจะนอนอยู่กับผู้ที่ไม่ได้เข้าสุหนัต กับบรรดาคนที่ได้ลงไปยังปากแดนคนตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 30, 'เจ้านายจากทิศเหนือก็อยู่ที่นั่นอยู่กันหมด คนไซดอนทั้งหมด ผู้ที่ลงไปด้วยความอายพร้อมกับผู้ที่ถูกฆ่า เพราะเหตุความครั่นคร้ามทั้งสิ้นซึ่งเขาได้กระทําขึ้นด้วยกําลังของเขา เขานอนอยู่ที่นั่นไม่เข้าสุหนัตพร้อมกับผู้ที่ถูกฆ่าด้วยดาบ และทนรับความอับอายขายหน้ากับบรรดาผู้ที่ลงไปยังปากแดนคนตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 31, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสว่า เมื่อฟาโรห์เห็นพวกเหล่านั้นแล้ว ท่านก็จะเบาใจในเรื่องหมู่นิกรทั้งสิ้นของท่าน ฟาโรห์และหมู่นิกรทั้งสิ้นของท่านถูกฆ่าด้วยดาบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 32, 'เพราะเราได้ให้เกิดความครั่นคร้ามในแผ่นดินของคนเป็น เพราะฉะนั้นเขาจะถูกวางไว้ท่ามกลางผู้ไม่เข้าสุหนัต พร้อมกับผู้เหล่านั้นที่ถูกฆ่าด้วยดาบ ทั้งฟาโรห์และหมู่นิกรทั้งสิ้นของท่าน องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้แหละ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 1, 'พระวจนะของพระเยโฮวาห์มายังข้าพเจ้าอีกว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 2, '“บุตรแห่งมนุษย์เอ๋ย จงพูดกับชนชาติของเจ้าและกล่าวแก่เขาว่า ถ้าเรานําดาบมาเหนือแผ่นดิน และถ้าประชาชนในแผ่นดินนั้นตั้งชายคนหนึ่งจากพวกเขาให้เป็นยาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 3, 'และถ้าเขาเห็นดาบมาเหนือแผ่นดินจึงเป่าแตรและตักเตือนประชาชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 4, 'เมื่อคนหนึ่งคนใดได้ยินเสียงแตรแต่ไม่นําพาต่อเสียงตักเตือน และดาบนั้นก็มาพาเอาคนนั้นไปเสีย ให้โลหิตของคนนั้นตกบนศีรษะของคนนั้นเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 5, 'คือเขาได้ยินเสียงแตร แต่ไม่นําพาต่อเสียงตักเตือน ให้โลหิตของคนนั้นตกอยู่บนคนนั้นเอง ถ้าเขาได้นําพาต่อเสียงตักเตือนแล้วเขาจะได้ช่วยชีวิตของตนเองให้รอดพ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 6, 'แต่ถ้าคนยามเห็นดาบมาแล้วและไม่เป่าแตร ประชาชนจึงไม่ได้รับเสียงตักเตือน และดาบก็มาพาคนหนึ่งคนใดไปเสีย คนนั้นถูกนําไปด้วยเรื่องความชั่วช้าของเขา แต่เราจะเรียกร้องโลหิตของเขาจากมือของยาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 7, 'ฉะนี้แหละ เจ้า โอ บุตรแห่งมนุษย์เอ๋ย เราได้ตั้งเจ้าให้เป็นคนยามสําหรับวงศ์วานอิสราเอล เจ้าได้ยินถ้อยคําจากปากของเราเมื่อไร เจ้าจงให้คําตักเตือนของเราแก่ประชาชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 8, 'ถ้าเรากล่าวแก่คนชั่วว่า โอ คนชั่วเอ๋ย เจ้าจะต้องตายแน่ แต่เจ้าก็มิได้กล่าวคําตักเตือนให้คนชั่วกลับจากทางของเขา คนชั่วนั้นจะต้องตายเพราะความชั่วช้าของเขา แต่เราจะเรียกร้องโลหิตของเขาจากมือของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 9, 'แต่ถ้าเจ้าได้ตักเตือนคนชั่วให้หันกลับจากทางของเขาแล้ว แต่เขาไม่หันกลับจากทางของเขา เขาจะตายเพราะความชั่วช้าของเขา แต่เจ้าได้ช่วยชีวิตของเจ้าเองให้รอดพ้นแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 10, 'เจ้า โอ บุตรแห่งมนุษย์เอ๋ย เจ้าจงกล่าวแก่วงศ์วานอิสราเอล พวกเจ้าเคยกล่าวดังนี้ว่า ‘การละเมิดและความบาปทั้งหลายของเราอยู่เหนือเรา เราก็ค่อยๆวอดวายไปเพราะสิ่งเหล่านี้ เราจะดํารงชีวิตอยู่ได้อย่างไร’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 11, 'จงกล่าวตอบเขาว่า องค์พระผู้เป็นเจ้าพระเจ้าตรัสว่า เรามีชีวิตอยู่แน่ฉันใด เราไม่พอใจในความตายของคนชั่ว แต่พอใจในการที่คนชั่วหันจากทางของเขาและมีชีวิตอยู่ จงหันกลับ จงหันกลับจากทางชั่วของเจ้า โอ วงศ์วานอิสราเอลเอ๋ย ยอมตายทําไม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 12, 'เจ้า บุตรแห่งมนุษย์เอ๋ย เจ้าจงกล่าวแก่ชนชาติของเจ้าว่า ความชอบธรรมของผู้ชอบธรรมจะไม่ช่วยเขาให้พ้นในวันที่เขาละเมิด ส่วนความชั่วของคนชั่วนั้นจะไม่กระทําให้เขาล้มลงในวันที่เขาหันกลับจากความชั่วของเขา และคนชอบธรรมจะไม่ดํารงชีวิตอยู่ได้ด้วยความชอบธรรมในวันที่เขากระทําบาป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 13, 'แม้เราจะได้กล่าวแก่คนชอบธรรมว่า เขาจะมีชีวิตอยู่แน่ ถ้าเขายังวางใจในความชอบธรรมของเขา และกระทําความชั่วช้า การกระทําทั้งหลายที่ชอบธรรมของเขาย่อมไม่อยู่ในความทรงจําอีกเลย แต่เขาจะต้องตายเพราะความชั่วช้าซึ่งเขาได้กระทําไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 14, 'อีกประการหนึ่ง แม้เราจะได้กล่าวแก่คนชั่วว่า ‘เจ้าจะต้องตายแน่’ ถ้าเขาหันกลับจากบาปของเขา มากระทําความยุติธรรมและความชอบธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 15, 'ถ้าคนชั่วได้คืนของประกัน ขโมยอะไรของเขามาก็คืนเสีย และดําเนินตามกฎเกณฑ์แห่งชีวิต ไม่กระทําความชั่วช้าเลย เขาจะดํารงชีวิตอยู่แน่ เขาไม่ต้องตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 16, 'บาปซึ่งเขาได้กระทํามาแล้ว จะไม่จดจํานํามากล่าวโทษเขา เขาได้กระทําความยุติธรรมและความชอบธรรม เขาจะดํารงชีวิตแน่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 17, 'แต่ชนชาติของเจ้ายังกล่าวว่า ‘วิธีการขององค์พระผู้เป็นเจ้าไม่ยุติธรรม’ ในเมื่อวิธีการของเขาเองไม่ยุติธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 18, 'เมื่อคนชอบธรรมหันกลับจากความชอบธรรมของเขาและกระทําความชั่วช้า เขาจะต้องตายเพราะความชั่วช้านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 19, 'แต่ถ้าคนชั่วหันกลับจากความชั่วของเขาและกระทําความยุติธรรมและความชอบธรรม เขาจะดํารงชีวิตอยู่ได้โดยเหตุนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 20, 'เจ้ายังกล่าวว่า ‘วิธีการขององค์พระผู้เป็นเจ้าไม่ยุติธรรม’ โอ วงศ์วานอิสราเอลเอ๋ย เราจะพิพากษาเจ้าตามการประพฤติของเจ้าแต่ละคน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 21, 'และอยู่มา เมื่อวันที่ห้า เดือนที่สิบ ในปีที่สิบสอง ซึ่งเราได้ถูกกวาดไปเป็นเชลย ชายคนหนึ่งหนีมาจากกรุงเยรูซาเล็มมาหาข้าพเจ้ากล่าวว่า “เมืองนั้นแตกเสียแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 22, 'ในเวลาเย็นก่อนที่ผู้ลี้ภัยมา พระหัตถ์ของพระเยโฮวาห์ได้มาอยู่เหนือข้าพเจ้า และพระองค์ทรงเปิดปากของข้าพเจ้าทันเวลาที่ชายคนนั้นมาถึงในตอนเช้า ดังนั้นปากของข้าพเจ้าจึงเปิดออก ข้าพเจ้าก็ไม่ได้เป็นใบ้ต่อไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 23, 'พระวจนะของพระเยโฮวาห์มายังข้าพเจ้าว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 24, '“บุตรแห่งมนุษย์เอ๋ย ชาวเมืองที่อาศัยอยู่ในที่ร้างเปล่าในแผ่นดินอิสราเอลกล่าวเรื่อยๆว่า ‘อับราฮัมเป็นแต่ชายคนเดียว และยังถือกรรมสิทธิ์ที่ดินนี้ แต่พวกเราหลายคนด้วยกัน คงต้องประทานแผ่นดินนั้นให้เป็นกรรมสิทธิ์แก่เรา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 25, 'เพราะฉะนั้น จงกล่าวแก่เขาทั้งหลายว่า องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า เจ้ารับประทานเนื้อพร้อมเลือด เจ้าเงยหน้าขึ้นนมัสการรูปเคารพของเจ้าและทําให้โลหิตตก แล้วเจ้ายังจะเอากรรมสิทธิ์ที่ดินนี้อีกหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 26, 'เจ้ายืนอยู่ด้วยดาบของเจ้า เจ้ากระทําการอันน่าสะอิดสะเอียน และเจ้าทุกคนได้กระทําให้ภรรยาของเพื่อนบ้านเป็นมลทิน แล้วเจ้าจะเอากรรมสิทธิ์ที่ดินนี้หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 27, 'จงกล่าวเช่นนี้แก่เขาว่า องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า เรามีชีวิตอยู่แน่ฉันใด บรรดาคนที่อยู่ในที่ร้างเปล่าจะต้องล้มลงด้วยดาบ และคนที่อยู่ที่พื้นทุ่ง เราจะมอบให้เป็นอาหารแก่สัตว์ป่า และบรรดาคนเหล่านั้นที่อยู่ในที่กําบังเข้มแข็งและอยู่ในถ้ําจะตายด้วยโรคระบาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 28, 'และเราจะกระทําให้แผ่นดินนั้นรกร้างที่สุด และความหยิ่งผยองในอานุภาพของแผ่นดินนั้นจะสูญสิ้นไป ภูเขาแห่งอิสราเอลจะรกร้างจนไม่มีคนเดินผ่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 29, 'แล้วเขาจะทราบว่าเราคือพระเยโฮวาห์ เมื่อเราได้กระทําให้แผ่นดินนั้นรกร้างที่สุด เพราะเหตุจากการอันน่าสะอิดสะเอียนทั้งสิ้นของเขาซึ่งเขาได้กระทํานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 30, 'เจ้า บุตรแห่งมนุษย์เอ๋ย ชนชาติของเจ้าที่พูดเรื่องเจ้าข้างกําแพงเมืองและตามประตูบ้าน พูดต่อกันและกันกับพี่น้องของตนว่า ‘มาเถิด มาฟังเสียงพระวจนะซึ่งออกมาจากพระเยโฮวาห์’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 31, 'และเข้ามาหาเจ้าอย่างที่ชาวตลาดมา และเขามานั่งข้างหน้าเจ้าอย่างประชาชนของเรา เขาฟังคําพูดของเจ้า แต่เขาไม่ยอมกระทําตาม เพราะว่าเขาแสดงความรักมากด้วยปากของเขา แต่จิตใจของเขามุ่งอยู่ตามความโลภของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 32, 'และ ดูเถิด เจ้าเป็นเหมือนคนร้องเพลงรักแก่เขา มีเสียงไพเราะและเล่นดนตรีเก่ง เพราะเขาฟังคําพูดของเจ้า แต่เขาไม่ยอมกระทําตาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 33, 'และเมื่อการเช่นนี้เป็นมา (ดูเถิด ก็จะมา) เขาทั้งหลายจะทราบว่ามีผู้พยากรณ์อยู่ในหมู่พวกเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 1, 'พระวจนะของพระเยโฮวาห์มายังข้าพเจ้าว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 2, '“บุตรแห่งมนุษย์เอ๋ย จงพยากรณ์กล่าวโทษบรรดาผู้เลี้ยงแกะแห่งอิสราเอล จงพยากรณ์และกล่าวแก่เขาว่า องค์พระผู้เป็นเจ้าพระเจ้าตรัสแก่พวกผู้เลี้ยงแกะดังนี้ว่า วิบัติแก่ผู้เลี้ยงแกะแห่งอิสราเอล ผู้เลี้ยงตัวเอง ผู้เลี้ยงแกะย่อมเลี้ยงแกะมิใช่หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 3, 'เจ้ารับประทานไขมัน เจ้าคลุมกายของเจ้าด้วยขนแกะ เจ้าฆ่าแกะตัวอ้วนๆ แต่เจ้าหาได้เลี้ยงแกะไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 4, 'ตัวที่อ่อนเพลียเจ้าก็ไม่เสริมกําลัง ตัวที่เจ็บเจ้าก็ไม่รักษา ตัวที่กระดูกหักเจ้าก็มิได้พันผ้า ตัวที่ถูกขับไล่ออกไปเจ้าก็มิได้ไปตามกลับมา ตัวที่หายไปเจ้าก็มิได้เสาะหา และเจ้าได้ปกครองเขาด้วยการบังคับและด้วยการข่มขี่เบียดเบียน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 5, 'ดังนั้นมันจึงกระจัดกระจายไปหมด เพราะว่าไม่มีผู้เลี้ยงแกะ และเมื่อมันกระจัดกระจายไป มันก็ตกเป็นอาหารของสัตว์ป่าทั้งปวงในทุ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 6, 'แกะของเราก็เที่ยวไปตามภูเขาทั้งหมด และตามเนินเขาสูงทุกแห่ง เออ แกะของเราก็กระจายไปทั่วพื้นพิภพ ไม่มีใครเที่ยวค้น ไม่มีใครเสาะหามัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 7, 'เพราะฉะนั้น ท่านทั้งหลายผู้เป็นผู้เลี้ยงแกะ จงฟังพระวจนะของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 8, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสว่า เรามีชีวิตอยู่แน่ฉันใด เพราะแกะของเรากลายเป็นเหยื่อ และแกะของเรากลายเป็นอาหารของสัตว์ป่าทุ่งทั้งสิ้น เพราะไม่มีผู้เลี้ยงแกะ และเพราะผู้เลี้ยงแกะของเราไม่เที่ยวค้นหาแกะของเรา แต่ผู้เลี้ยงแกะนั้นเลี้ยงตัวเอง และไม่ได้เลี้ยงแกะของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 9, 'เพราะฉะนั้น โอ ท่านทั้งหลายผู้เป็นผู้เลี้ยงแกะ จงฟังพระวจนะของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 10, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า ดูเถิด เราเป็นปฏิปักษ์กับผู้เลี้ยงแกะ และเราจะเรียกร้องเอาแกะของเราจากมือของเขา และให้เขายับยั้งการเลี้ยงแกะของเขา ผู้เลี้ยงแกะจะไม่ได้เลี้ยงตัวเองอีกต่อไป เราจะช่วยแกะของเราให้พ้นจากปากของเขา เพื่อมิให้แกะเป็นอาหารของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 11, 'เพราะองค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า ดูเถิด เราคือเราเองจะค้นหาแกะของเรา และจะเที่ยวหามัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 12, 'ดังผู้เลี้ยงแกะเที่ยวหาฝูงแกะในวันที่เขาอยู่ท่ามกลางแกะของเขาที่กระจัดกระจายไป เราจะเที่ยวหาแกะของเราดังนั้น และเราจะช่วยเขาให้พ้นจากสถานที่ทั้งหลายซึ่งเขาได้กระจัดกระจายไปอยู่ในวันมีเมฆและมีความมืดทึบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 13, 'เราจะนําเขาออกมาจากชนชาติทั้งหลาย และรวบรวมเขามาจากประเทศต่างๆ และจะนําเขามาไว้ในแผ่นดินของเขาเอง และเราจะเลี้ยงเขาบนภูเขาแห่งอิสราเอล ใกล้ห้วยทั้งหลายและในท้องถิ่นทุกแห่งที่มีคนอาศัยในประเทศนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 14, 'เราจะเลี้ยงเขาในลานหญ้าอย่างดี และคอกของเขาจะอยู่บนบรรดาภูเขาสูงแห่งอิสราเอล ณ ที่นั่น เขาจะนอนลงในคอกที่ดี และเขาจะหากินอยู่บนลานหญ้าอุดมบนภูเขาแห่งอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 15, 'ตัวเราเองจะเป็นผู้เลี้ยงแกะของเรา เราจะกระทําให้เขานอนลง องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 16, 'เราจะเที่ยวหาแกะที่หาย และเราจะนําแกะที่ถูกขับไล่ออกไปกลับมาอีก และเราจะพันผ้าให้แกะที่กระดูกหัก และเราจะเสริมกําลังแกะที่อ่อนเพลีย แต่ตัวที่อ้วนและเข้มแข็งเราจะทําลาย เราจะเลี้ยงเขาด้วยความยุติธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 17, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า โอ เจ้าทั้งหลายผู้เป็นฝูงแพะแกะของเราเอ๋ย ดูเถิด เราจะพิพากษาระหว่างแกะกับแกะ ระหว่างแกะผู้กับแพะผู้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 18, 'ที่จะหากินในลานหญ้าอย่างดีนั้นยังไม่พออีกหรือ เจ้าจึงต้องเอาเท้าเหยียบลานหญ้าที่เหลืออยู่ของเจ้า และดื่มน้ําจากแหล่งน้ําที่ลึกยังไม่พอหรือ จึงเอาเท้าของเจ้ากวนน้ําที่เหลืออยู่ให้ขุ่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 19, 'แกะของเราจะต้องกินสิ่งที่เท้าของเจ้าย่ํา และดื่มสิ่งที่เท้าของเจ้าทําให้ขุ่นหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 20, 'เพราะฉะนั้น องค์พระผู้เป็นเจ้าพระเจ้าตรัสแก่เขาดังนี้ว่า ดูเถิด เรา คือเราเอง จะพิพากษาระหว่างแกะอ้วนกับแกะผอม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 21, 'เพราะเจ้าเอาสีข้างและบ่าดันและผลักแกะตัวอ่อนเพลียด้วยเขาของเจ้า เจ้าทําให้เขากระจายไปต่างถิ่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 22, 'เราจึงจะช่วยฝูงแพะแกะของเราให้รอด เขาจะไม่เป็นเหยื่ออีกต่อไป และเราจะพิพากษาระหว่างแกะกับแกะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 23, 'และเราจะตั้งผู้เลี้ยงแกะผู้หนึ่งไว้เหนือเขา คือดาวิดผู้รับใช้ของเรา และท่านจะเลี้ยงเขาทั้งหลาย ท่านจะเลี้ยงเขาและจะเป็นผู้เลี้ยงของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 24, 'และเราคือพระเยโฮวาห์จะเป็นพระเจ้าของเขา และดาวิดผู้รับใช้ของเราจะเป็นเจ้านายท่ามกลางเขา เราคือพระเยโฮวาห์ได้ลั่นวาจาแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 25, 'เราจะกระทําพันธสัญญาสันติสุขกับเขา และจะกําจัดสัตว์ร้ายเสียจากแผ่นดิน เขาจะอาศัยอยู่ในถิ่นทุรกันดารอย่างปลอดภัย และนอนอยู่ในป่าไม้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 26, 'และเราจะกระทําให้เขากับสถานที่รอบๆเนินเขาของเราเป็นแหล่งพระพร เราจะส่งฝนลงมาให้ตามฤดูกาล เป็นห่าฝนแห่งพระพร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 27, 'ต้นไม้ที่ในทุ่งจะบังเกิดผล และพิภพจะบังเกิดผลประโยชน์ และเขาจะอยู่อย่างปลอดภัยในแผ่นดินของเขา และเขาจะทราบว่าเราคือพระเยโฮวาห์ ในเมื่อเราหักคานแอกของเขาเสีย และช่วยเขาให้พ้นจากมือของผู้ที่กักเขาให้เป็นทาส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 28, 'เขาจะไม่เป็นเหยื่อของประชาชาติอีกต่อไป หรือสัตว์ป่าดินก็จะไม่กินเขา และเขาจะอยู่อย่างปลอดภัย ไม่มีผู้ใดกระทําให้เขากลัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 29, 'และเราจะจัดหาไร่นาอันมีชื่อให้แก่เขา เพื่อเขาจะไม่ถูกผลาญด้วยความอดอยากในแผ่นดินนั้นต่อไปอีก ไม่ต้องทนรับความอับอายขายหน้าจากประชาชาติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 30, 'และเขาจะทราบว่าเราคือพระเยโฮวาห์พระเจ้าของเขาสถิตกับเขา และเขาคือวงศ์วานอิสราเอลเป็นประชาชนของเรา องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 31, 'เจ้าทั้งหลายเป็นแกะของเรา เป็นแกะในลานหญ้าของเรา เจ้าทั้งหลายเป็นมนุษย์และเราเป็นพระเจ้าของเจ้า องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้แหละ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 1, 'พระวจนะของพระเยโฮวาห์มายังข้าพเจ้าอีกว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 2, '“บุตรแห่งมนุษย์เอ๋ย จงมุ่งหน้าของเจ้าต่อสู้ภูเขาเสอีร์ และพยากรณ์ต่อมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 3, 'และกล่าวแก่มันว่า องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า ดูเถิด โอ ภูเขาเสอีร์เอ๋ย เราต่อสู้กับเจ้า และเราจะเหยียดมือของเราต่อสู้เจ้า และเราจะกระทําให้เจ้ารกร้างที่สุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 4, 'เราจะกระทําให้หัวเมืองของเจ้าถูกทิ้งไว้เสียเปล่าและเจ้าจะเป็นที่รกร้าง และเจ้าจะทราบว่าเราคือพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 5, 'เพราะเจ้าพยาบาทอยู่เป็นนิตย์ และให้โลหิตของประชาชนอิสราเอลไหลออกด้วยอํานาจของดาบในเวลาพิบัติของเขา ในเวลาที่ความชั่วช้าของเขาสิ้นสุดลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 6, 'องค์พระผู้เป็นเจ้าพระเจ้าจึงตรัสว่า เพราะฉะนั้น เรามีชีวิตอยู่แน่ฉันใด เราจะเตรียมเจ้าเพื่อรับโทษแห่งการให้โลหิตตก และโลหิตจะไล่ตามเจ้า เพราะเจ้ามิได้เกลียดชังเรื่องโลหิต เพราะฉะนั้นโลหิตจึงจะไล่ตามเจ้าไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 7, 'ดังนั้นเราจะกระทําให้ภูเขาเสอีร์รกร้างที่สุด และเราจะตัดผู้ที่ผ่านออกมาและผู้ที่กลับเข้าไปเสียจากมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 8, 'ภูเขาของเขานั้น เราจะให้มีผู้ที่ถูกฆ่าเต็มไปหมด ผู้ที่ถูกฆ่าด้วยดาบจะล้มลงตามเนินเขาของเจ้า ตามหุบเขาของเจ้า และในห้วยทั้งสิ้นของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 9, 'เราจะกระทําเจ้าให้เป็นที่รกร้างอยู่เนืองนิตย์ และหัวเมืองของเจ้าจะไม่กลับคืนมาอีก แล้วเจ้าจะทราบว่าเราคือพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 10, 'เพราะเจ้ากล่าวว่า ‘ประชาชาติทั้งสองนี้และประเทศทั้งสองนี้จะต้องเป็นของเรา เราจะเอาเขามาเป็นกรรมสิทธิ์’ ถึงแม้พระเยโฮวาห์สถิตอยู่ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 11, 'เพราะฉะนั้น องค์พระผู้เป็นเจ้าพระเจ้าตรัสว่า เรามีชีวิตอยู่แน่ฉันใด เราจะกระทําต่อเจ้าตามความกริ้วและความอิจฉาของเจ้า ซึ่งเจ้าสําแดงเพราะความเกลียดชังของเจ้าซึ่งมีต่อเขา เมื่อเราพิพากษาเจ้า เราจึงจะสําแดงตัวของเราในหมู่พวกเขาให้เขารู้จัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 12, 'และเจ้าจะทราบว่า เราคือพระเยโฮวาห์ และทราบว่าเราได้ยินคําหมิ่นประมาททั้งปวงของเจ้า ซึ่งเจ้าได้พูดต่อภูเขาทั้งหลายแห่งอิสราเอลว่า ‘มันถูกทิ้งไว้ให้รกร้าง มันถูกมอบไว้ให้เราเผาผลาญเสีย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 13, 'ด้วยปากของเจ้า เจ้าเบ่งตัวเจ้าต่อสู้เรา และว่าเราอีกมากหลาย เราได้ยินแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 14, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า เมื่อแผ่นดินโลกทั้งสิ้นชื่นชมยินดี เราจะกระทําเจ้าให้รกร้างไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 15, 'เจ้าได้ชื่นชมยินดีต่อมรดกแห่งวงศ์วานอิสราเอลเพราะมันเป็นที่รกร้างฉันใด เราจะกระทําแก่เจ้าฉันนั้น โอ ภูเขาเสอีร์เอ๋ย รวมทั้งเอโดมทั้งหมด ทั้งหมดเลย เจ้าจะต้องเป็นที่รกร้าง แล้วเขาทั้งหลายจะทราบว่าเราคือพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 1, '“เจ้า บุตรแห่งมนุษย์เอ๋ย จงพยากรณ์ต่อภูเขาทั้งหลายแห่งอิสราเอลว่า ภูเขาแห่งอิสราเอลเอ๋ย จงฟังพระวจนะของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 2, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า เพราะศัตรูกล่าวขวัญถึงเจ้าว่า ‘อ้าฮา แม้แต่ที่สูงโบราณเหล่านั้นได้ตกเป็นกรรมสิทธิ์ของเราแล้ว’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 3, 'เพราะฉะนั้นจงพยากรณ์และกล่าวว่า องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า เพราะว่าเขากระทําให้เจ้ารกร้าง และกลืนเจ้าเสียทุกด้านเพื่อเจ้าจะได้ตกเป็นกรรมสิทธิ์ของชนชาติที่เหลืออยู่นั้น และริมฝีปากของพวกช่างพูดก็เอาเรื่องของเจ้าไปนินทา เป็นที่เสื่อมเสียชื่อเสียงในหมู่ประชาชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 4, 'ภูเขาทั้งหลายแห่งอิสราเอลเอ๋ย เพราะฉะนั้นจงฟังพระวจนะขององค์พระผู้เป็นเจ้าพระเจ้า องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้แก่ภูเขาและเนินเขา แม่น้ําและหุบเขา ที่ที่ถูกทิ้งไว้เสียเปล่าและรกร้าง และหัวเมืองที่ถูกละทิ้ง ซึ่งได้กลายเป็นเหยื่อและเป็นที่เย้ยหยันแก่ประชาชาติที่เหลืออยู่รอบๆนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 5, 'เพราะฉะนั้นองค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า ด้วยความหวงแหนอย่างเดือดดาลของเรา เราพูดกล่าวโทษประชาชาติที่เหลืออยู่ และแก่เอโดมทั้งสิ้นผู้ที่มอบแผ่นดินของเราให้แก่ตนเองให้เป็นกรรมสิทธิ์ ด้วยความร่าเริงอย่างเต็มใจ และใจประมาทหมิ่นอย่างที่สุด เพื่อเขาจะได้ไล่คนแผ่นดินนั้นออกไป เพื่อจะได้ปล้นเอาไปเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 6, 'เพราะฉะนั้นจงกล่าวคําพยากรณ์เกี่ยวกับแผ่นดินอิสราเอล และจงกล่าวแก่ภูเขาและเนินเขา แก่ห้วยและหุบเขาว่า องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า ดูเถิด เราพูดด้วยความหวงแหนและความพิโรธของเรา เพราะเจ้าได้ทนรับความอับอายขายหน้าจากประชาชาติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 7, 'เพราะฉะนั้นองค์พระผู้เป็นเจ้าพระเจ้าจึงตรัสว่า เราปฏิญาณว่า ประชาชาติที่อยู่รอบเจ้านั้นจะทนรับความอับอายขายหน้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 8, 'โอ ภูเขาทั้งหลายแห่งอิสราเอลเอ๋ย แต่เจ้าจะแตกกิ่งของเจ้าออกมา และออกผลให้แก่อิสราเอลประชาชนของเรา เพราะไม่ช้าเขาจะได้กลับมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 9, 'เพราะ ดูเถิด เราอยู่ฝ่ายเจ้า เราจะหันมาหาเจ้า และเจ้าจะถูกไถและถูกหว่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 10, 'และเราจะทวีคนให้แก่เจ้า คือบรรดาวงศ์วานอิสราเอลทั่วหมด หัวเมืองจะมีคนมาอาศัยอยู่ และสถานที่ร้างเปล่าจะถูกสร้างขึ้นใหม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 11, 'เราจะทวีทั้งคนและสัตว์ให้แก่เจ้า จะเพิ่มขึ้นและมีลูกดก และเราจะกระทําให้เจ้ามีคนอาศัยอยู่อย่างในกาลก่อน และจะเป็นประโยชน์แก่เจ้ามากกว่าแต่ก่อน แล้วเจ้าจะทราบว่าเราคือพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 12, 'เออ เราจะให้คนดําเนินบนเจ้า คืออิสราเอลประชาชนของเราด้วย และเขาทั้งหลายจะได้เจ้าเป็นกรรมสิทธิ์ และเจ้าจะเป็นมรดกของเขา และเจ้าจะไม่เอาลูกของเขาไปอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 13, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า เพราะคนกล่าวแก่เจ้าว่า ‘เจ้ากินคนและเจ้าได้เอาลูกของประชาชาติของเจ้าไป’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 14, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสว่า เพราะฉะนั้นเจ้าจะไม่กินคน และจะไม่เอาลูกของเจ้าจากประชาชาติของเจ้าไปอีกเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 15, 'เราจะไม่ให้เจ้าได้ยินคําประมาทหมิ่นของประชาชาติต่างๆอีก และเจ้าไม่ต้องทนรับความอับอายขายหน้าของชนชาติทั้งหลายอีกเลย และไม่ต้องกระทําให้ประชาชาติของเจ้าสะดุดอีกเลย องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้แหละ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 16, 'พระวจนะของพระเยโฮวาห์มายังข้าพเจ้าอีกว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 17, '“บุตรแห่งมนุษย์เอ๋ย เมื่อวงศ์วานอิสราเอลได้มาอาศัยอยู่ในแผ่นดินของตน เขากระทําให้แผ่นดินเป็นมลทินด้วยวิถีและการกระทําของเขา ความประพฤติของเขาที่มีต่อหน้าเราก็เหมือนมลทินอันเกิดจากระดู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 18, 'เพราะฉะนั้นเราจึงระบายความกริ้วของเราออกเหนือเขาด้วยเรื่องโลหิตซึ่งเขาได้กระทําให้ตกบนแผ่นดิน ด้วยเรื่องรูปเคารพซึ่งเขากระทําให้แผ่นดินนั้นเป็นมลทิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 19, 'เราจึงให้เขากระจัดกระจายไปท่ามกลางประชาชาติ และเขาถูกกระจายไปตามประเทศต่างๆ เราพิพากษาเขาตามวิถีและการกระทําของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 20, 'แต่เมื่อเขามายังบรรดาประชาชาติ เขาจะมาที่ไหนก็ตาม เขาได้ลบหลู่นามบริสุทธิ์ของเรา ซึ่งคนกล่าวขวัญถึงเขาว่า ‘คนเหล่านี้เป็นประชาชนของพระเยโฮวาห์ ถึงกระนั้นเขายังต้องออกไปจากแผ่นดินของพระองค์’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 21, 'แต่เรายังสงสารนามบริสุทธิ์ของเรา ซึ่งวงศ์วานอิสราเอลได้ลบหลู่ท่ามกลางประชาชาติซึ่งเขาตกไปอยู่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 22, 'เพราะฉะนั้นจงกล่าวแก่วงศ์วานอิสราเอล องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า โอ วงศ์วานอิสราเอลเอ๋ย เรากําลังจะกระทําอยู่แล้ว ไม่ใช่เพื่อเห็นแก่เจ้า แต่เพราะเห็นแก่นามบริสุทธิ์ของเรา ซึ่งเจ้าได้ลบหลู่ท่ามกลางประชาชาติซึ่งเจ้าเข้าไปอยู่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 23, 'และเราจะชําระให้นามที่ยิ่งใหญ่ของเราบริสุทธิ์ ซึ่งเป็นนามที่ถูกลบหลู่ท่ามกลางประชาชาติ และซึ่งเจ้าได้ลบหลู่ท่ามกลางเขา และประชาชาติจะทราบว่า เราคือพระเยโฮวาห์ องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้แหละ เมื่อเราสําแดงความบริสุทธิ์ของเราท่ามกลางเจ้าต่อหน้าต่อตาเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 24, 'เพราะว่าเราจะเอาเจ้าออกมาจากท่ามกลางประชาชาติและรวบรวมเจ้ามาจากทุกประเทศ และจะนําเจ้าเข้ามาในแผ่นดินของเจ้าเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 25, 'เราจะเอาน้ําสะอาดพรมเจ้า และเจ้าจะสะอาดพ้นจากมลทินทั้งหลายของเจ้า และเราจะชําระเจ้าจากรูปเคารพทั้งหลายของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 26, 'เราจะให้ใจใหม่แก่เจ้า และเราจะบรรจุจิตวิญญาณใหม่ไว้ในเจ้า เราจะนําใจหินออกไปเสียจากเนื้อของเจ้า และจะให้ใจเนื้อแก่เจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 27, 'และเราจะใส่วิญญาณของเราภายในเจ้า และกระทําให้เจ้าดําเนินตามกฎเกณฑ์ของเรา และเจ้าจะรักษาคําตัดสินของเราและกระทําตาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 28, 'เจ้าจะอาศัยอยู่ในแผ่นดินซึ่งเราให้แก่บรรพบุรุษของเจ้า และเจ้าจะเป็นประชาชนของเรา และเราจะเป็นพระเจ้าของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 29, 'เราจะช่วยเจ้าให้พ้นมลทินทั้งหลายของเจ้า และเราจะเรียกข้าวมา และจะกระทําให้อุดมสมบูรณ์ และจะไม่ให้เจ้าเกิดการกันดารอาหารเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 30, 'เราจะกระทําให้ผลของต้นไม้และไร่นาอุดมสมบูรณ์ เพื่อเจ้าจะไม่ต้องทนรับความอับอายขายหน้าเพราะการกันดารอาหารท่ามกลางประชาชาติอีกเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 31, 'แล้วเจ้าจะระลึกถึงวิถีทางที่ชั่วของเจ้า และการกระทําที่ไม่ดีของเจ้า แล้วเจ้าจะเกลียดตัวเจ้าในสายตาของเจ้าเอง เพราะความชั่วช้าของเจ้าและเพราะการกระทําอันน่าสะอิดสะเอียนของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 32, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสว่า ที่เรากระทํานั้นมิใช่เพราะเห็นแก่เจ้า ขอให้เจ้าทราบเสีย โอ วงศ์วานอิสราเอลเอ๋ย จงอับอายและขายหน้าด้วยเรื่องทางของเจ้าเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 33, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า ในวันที่เราชําระเจ้าให้หมดจากความชั่วช้าทั้งสิ้นของเจ้านั้น เราจะกระทําให้เจ้าอาศัยอยู่ในบรรดาหัวเมือง และสถานที่ทิ้งร้างจะได้สร้างขึ้นใหม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 34, 'แผ่นดินที่รกร้างจะได้รับการไถแทนที่จะเป็นที่รกร้างดังที่ปรากฏต่อสายตาของคนทั้งหลายที่ผ่านไปมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 35, 'และเขาทั้งหลายจะกล่าวว่า ‘แผ่นดินนี้ที่เคยรกร้างกลายเป็นอย่างสวนเอเดน หัวเมืองที่ถูกทิ้งไว้เสียเปล่าและรกร้างและปรักหักพัง เดี๋ยวนี้ก็มีกําแพงล้อมรอบและมีคนอาศัย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 36, 'แล้วประชาชาติที่เหลืออยู่รอบๆ เจ้าจะทราบว่า เรา พระเยโฮวาห์ ได้สร้างที่ปรักหักพังเหล่านี้ขึ้นใหม่ และปลูกพืชในที่รกร้างนั้น เรา พระเยโฮวาห์ ได้ลั่นวาจาไว้แล้ว และเราจะกระทําเช่นนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 37, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า เราจะให้วงศ์วานอิสราเอลขอให้เรากระทําสิ่งนี้ให้ด้วย คือให้เพิ่มคนอย่างเพิ่มฝูงแพะแกะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 38, 'ฝูงแพะแกะอันบริสุทธิ์ และฝูงแพะแกะที่เยรูซาเล็มระหว่างเทศกาลตามกําหนดของเธอเป็นอย่างไร เมืองที่ถูกทิ้งร้างจะเต็มไปด้วยฝูงคนอย่างนั้น แล้วเขาจะทราบว่า เราคือพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 1, 'พระหัตถ์ของพระเยโฮวาห์มาอยู่เหนือข้าพเจ้า และพระองค์ทรงนําข้าพเจ้าออกมาด้วยพระวิญญาณของพระเยโฮวาห์ และวางข้าพเจ้าไว้ที่กลางหว่างเขา มีกระดูกเต็มไปหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 2, 'พระองค์ทรงพาข้าพเจ้าไปเที่ยวในหมู่กระดูกเหล่านั้น ดูเถิด มีกระดูกที่หว่างเขานั้นมากมายเหลือเกิน และดูเถิด เป็นกระดูกแห้งทีเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 3, 'และพระองค์ตรัสกับข้าพเจ้าว่า “บุตรแห่งมนุษย์เอ๋ย กระดูกเหล่านี้จะมีชีวิตได้ไหม” และข้าพเจ้าทูลตอบว่า “โอ องค์พระผู้เป็นเจ้าพระเจ้าเจ้าข้า พระองค์ก็ทรงทราบอยู่แล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 4, 'พระองค์ตรัสกับข้าพเจ้าอีกว่า “จงพยากรณ์ต่อกระดูกเหล่านี้ และกล่าวแก่มันว่า โอ กระดูกแห้งเอ๋ย จงฟังพระวจนะของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 5, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้แก่กระดูกเหล่านี้ว่า ดูเถิด เราจะกระทําให้ลมหายใจเข้าไปในเจ้า และเจ้าจะมีชีวิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 6, 'เราจะวางเส้นเอ็นไว้บนเจ้าและจะกระทําให้เนื้อมีมาบนเจ้า และเอาหนังคลุมเจ้าและบรรจุลมหายใจในเจ้าและเจ้าจะมีชีวิต และเจ้าจะทราบว่า เราคือพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 7, 'ข้าพเจ้าก็พยากรณ์ดังที่ข้าพเจ้าได้รับบัญชา เมื่อข้าพเจ้าพยากรณ์อยู่นั้นก็มีเสียง และดูเถิด เป็นเสียงกรุกกริก กระดูกเหล่านั้นก็เข้ามาหากันตามที่ของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 8, 'และเมื่อข้าพเจ้ามองดู ดูเถิด ก็เห็นมีเอ็นบนมัน และเนื้อก็มาที่กระดูก และหนังก็มาหุ้มกระดูกไว้ แต่ไม่มีลมหายใจในนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 9, 'แล้วพระองค์ตรัสกับข้าพเจ้าว่า “จงพยากรณ์แก่ลมหายใจ บุตรแห่งมนุษย์เอ๋ย จงพยากรณ์เถิด จงกล่าวแก่ลมหายใจว่า องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า โอ ลมหายใจเอ๋ย จงมาจากลมทั้งสี่มาหายใจเข้าไปในคนที่ถูกฆ่าเหล่านี้เพื่อให้เขามีชีวิต”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 10, 'ข้าพเจ้าก็พยากรณ์ดังที่ทรงบัญชาแก่ข้าพเจ้า และลมหายใจก็เข้ามาในกระดูกและกระดูกก็มีชีวิต แล้วก็ยืนขึ้น เป็นกองทัพใหญ่โตจริงๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 11, 'แล้วพระองค์ตรัสกับข้าพเจ้าว่า “บุตรแห่งมนุษย์เอ๋ย กระดูกเหล่านี้คือวงศ์วานอิสราเอลทั้งสิ้น ดูเถิด เขาทั้งหลายกล่าวว่า ‘กระดูกของเราแห้ง และความหวังของเราก็สิ้นไป เราได้ถูกตัดส่วนของเราออกเสีย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 12, 'เพราะฉะนั้น จงพยากรณ์และกล่าวแก่เขาว่า องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า ดูเถิด โอ ประชาชนของเราเอ๋ย เราจะเปิดหลุมฝังศพของเจ้า และยกเจ้าออกมาจากหลุมฝังศพของเจ้า และจะนําเจ้ากลับมายังแผ่นดินอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 13, 'โอ ประชาชนของเราเอ๋ย เจ้าจะทราบว่า เราคือพระเยโฮวาห์ ในเมื่อเราเปิดหลุมศพของเจ้า และยกเจ้าออกมาจากหลุมศพของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 14, 'และเราจะบรรจุวิญญาณของเราไว้ในเจ้า และเจ้าจะมีชีวิต และเราจะวางเจ้าไว้ในแผ่นดินของเจ้า แล้วเจ้าจะทราบว่าเราคือพระเยโฮวาห์ได้ลั่นวาจาแล้ว และเราได้กระทํา พระเยโฮวาห์ตรัสดังนี้แหละ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 15, 'พระวจนะของพระเยโฮวาห์มายังข้าพเจ้าอีกว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 16, '“เจ้า บุตรแห่งมนุษย์เอ๋ย จงเอาไม้มาอันหนึ่งเขียนลงว่า ‘สําหรับยูดาห์ และสําหรับชนอิสราเอลที่สังคมกับยูดาห์’ จงเอาไม้มาอีกอันหนึ่งเขียนลงว่า ‘สําหรับโยเซฟ ไม้ของเอฟราอิม และวงศ์วานอิสราเอลทั้งสิ้นที่สังคมกับโยเซฟ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 17, 'เอาไม้ทั้งสองมารวมกันเข้าเป็นอันเดียว เพื่อเป็นไม้อันเดียวในมือของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 18, 'และเมื่อชนชาติของเจ้ากล่าวแก่เจ้าว่า ‘ท่านจะไม่สําแดงให้เราทราบหรือว่า ไม้นี้หมายความว่ากระไร’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 19, 'จงกล่าวแก่เขาว่า องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า ดูเถิด เราจะเอาไม้ของโยเซฟ ซึ่งอยู่ในมือของเอฟราอิม และตระกูลอิสราเอลที่สังคมกับเขา และเราจะเอาไม้ของยูดาห์มารวมเข้าด้วย และกระทําให้เป็นไม้อันเดียวกัน เพื่อให้เป็นไม้อันเดียวในมือของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 20, 'และไม้ซึ่งเจ้าเขียนไว้นั้นจะอยู่ในมือของเจ้าต่อหน้าต่อตาเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 21, 'แล้วจงกล่าวแก่เขาว่า องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า ดูเถิด เราจะนําคนอิสราเอลมาจากท่ามกลางประชาชาติ ซึ่งเขาได้เข้าไปอยู่ด้วยนั้น และจะรวบรวมเขามาจากทุกด้านและนําเขามายังแผ่นดินของเขาเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 22, 'และเราจะกระทําให้เขาเป็นประชาชาติเดียวในแผ่นดินนั้นที่บนภูเขาทั้งหลายแห่งอิสราเอล และจะมีกษัตริย์แต่พระองค์เดียวปกครองอยู่เหนือเขาทั้งสิ้น เขาจะไม่เป็นสองประชาชาติอีกต่อไป และจะไม่แยกเป็นสองราชอาณาจักรอีกต่อไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 23, 'เขาจะไม่กระทําตัวให้เป็นมลทินด้วยรูปเคารพและสิ่งที่น่าสะอิดสะเอียนของเขา หรือด้วยการละเมิดใดๆของเขาต่อไปอีก แต่เราจะช่วยเขาให้พ้นจากบรรดาที่อาศัยซึ่งเขากระทําบาปนั้น และจะชําระเขา และเขาจะเป็นประชาชนของเรา และเราจะเป็นพระเจ้าของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 24, 'ดาวิดผู้รับใช้ของเราจะเป็นกษัตริย์เหนือเขาทั้งหลาย และเขาทุกคนจะมีผู้เลี้ยงผู้เดียว เขาทั้งหลายจะดําเนินตามคําตัดสินของเรา และรักษากฎเกณฑ์ของเรา และกระทําตาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 25, 'เขาทั้งหลายจะอาศัยอยู่ในแผ่นดินซึ่งบรรพบุรุษของเจ้าอาศัยอยู่ ซึ่งเราได้ให้แก่ยาโคบผู้รับใช้ของเรา ตัวเขาและลูกหลานของเขาจะอาศัยอยู่ที่นั่นเป็นนิตย์ และดาวิดผู้รับใช้ของเราจะเป็นเจ้าของเขาเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 26, 'เราจะกระทําพันธสัญญาสันติภาพกับเขา จะเป็นพันธสัญญานิรันดร์แก่เขา และเราจะตั้งเขาไว้และให้เขาทวีขึ้น และเราจะวางสถานบริสุทธิ์ของเราไว้ท่ามกลางเขาเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 27, 'พลับพลาของเราจะอยู่กับเขา เออ เราจะเป็นพระเจ้าของเขาและเขาจะเป็นประชาชนของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 28, 'แล้วประชาชาติทั้งหลายจะทราบว่าเราคือพระเยโฮวาห์กระทําให้อิสราเอลเป็นสุทธิพิเศษชาติ ในเมื่อสถานบริสุทธิ์ของเราอยู่ท่ามกลางเขาเป็นนิตย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 1, 'พระวจนะของพระเยโฮวาห์มายังข้าพเจ้าว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 2, '“บุตรแห่งมนุษย์เอ๋ย จงมุ่งหน้าของเจ้าต่อสู้โกกแห่งแผ่นดินมาโกก เจ้าองค์สําคัญของเมเชคและทูบัล และจงพยากรณ์กล่าวโทษเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 3, 'จงกล่าวว่า องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า ดูเถิด โอ โกกเอ๋ย เราเป็นปฏิปักษ์กับเจ้า ผู้เป็นเจ้าองค์สําคัญแห่งเมเชคและทูบัล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 4, 'เราจะให้เจ้าหันกลับ และเอาเบ็ดเกี่ยวขากรรไกรของเจ้า และเราจะนําเจ้าออกมาพร้อมทั้งกองทัพทั้งสิ้นของเจ้า ทั้งม้าและพลม้า สวมเครื่องรบครบทุกคน เป็นกองทัพใหญ่ มีดั้งและโล่ ถือดาบทุกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 5, 'เปอร์เซีย เอธิโอเปีย และลิเบียอยู่กับเขาด้วย ทุกคนมีโล่และหมวกเหล็ก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 6, 'โกเมอร์และกองทัพทั้งสิ้นของเขา วงศ์วานโทการมาห์จากส่วนเหนือสุด พร้อมกับกองทัพทั้งสิ้นของเขา มีชนชาติทั้งหลายเป็นอันมากอยู่กับเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 7, 'เจ้าและบรรดากองทัพซึ่งประชุมอยู่กับเจ้า จงเตรียมตัวพร้อมและให้พร้อมไว้เสมอ และจงเป็นยามเฝ้าเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 8, 'เมื่อล่วงไปหลายวันแล้วเจ้าจะต้องถูกเรียกตัว ในปีหลังๆเจ้าจะยกเข้าไปต่อสู้กับแผ่นดินซึ่งได้คืนมาจากดาบ เป็นแผ่นดินที่ประชาชนรวบรวมกันมาจากชนชาติหลายชาติอยู่ที่บนภูเขาอิสราเอล ซึ่งได้เคยเป็นที่ทิ้งร้างอยู่เนืองนิตย์ ประชาชนของแผ่นดินนั้นออกมาจากชนชาติอื่นๆ บัดนี้อาศัยอยู่อย่างปลอดภัยแล้วทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 9, 'เจ้าจะรุกออกไป มาเหมือนพายุ เจ้าจะเป็นเหมือนเมฆคลุมแผ่นดิน ทั้งเจ้าและกองทัพทั้งสิ้นของเจ้าและชนชาติทั้งหลายเป็นอันมากที่อยู่กับเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 10, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า ต่อมาในเวลานั้นจะบังเกิดความคิดในใจของเจ้า และเจ้าจะคิดแผนการชั่ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 11, 'และจะกล่าวว่า ‘เราจะยกกองทัพไปยังแผ่นดินที่ชนบทไม่มีกําแพงล้อม เราจะโจมตีประชาชนที่สงบซึ่งอาศัยอยู่อย่างปลอดภัย ทุกคนอาศัยอยู่โดยไม่มีกําแพง ไม่มีดาล ไม่มีประตู’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 12, 'เพื่อชิงข้าวของปล้นเอาไปและเพื่อชิงเหยื่อ คือเพื่อจะหันมือของเจ้ากลับมายังที่รกร้างซึ่งขณะนี้มีคนอาศัยอยู่ และมายังประชาชนซึ่งรวบรวมจากบรรดาประชาชาติที่ได้สัตว์ใช้งานและข้าวของ คือผู้อาศัยอยู่ท่ามกลางแผ่นดินนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 13, 'เชบาและเดดานและบรรดาพ่อค้าแห่งทารชิช และสิงโตหนุ่มทั้งหลายในเมืองนั้นจะกล่าวแก่เจ้าว่า ‘ท่านมาเพื่อจะชิงข้าวของหรือ ท่านชุมนุมกองทัพเพื่อจะปล้น เพื่อจะขนเอาเงินและทองไป ขนเอาสัตว์และข้าวของไป เพื่อจะชิงของมากมายหรือ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 14, 'เพราะฉะนั้น บุตรแห่งมนุษย์เอ๋ย จงพยากรณ์และกล่าวกับโกกว่า องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า ในวันนั้นเมื่ออิสราเอลประชาชนของเราอาศัยอยู่อย่างปลอดภัยแล้ว เจ้าจะมิได้รู้หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 15, 'เจ้าจะมาจากที่ของเจ้าซึ่งอยู่ส่วนเหนือที่สุด ทั้งเจ้าและชนชาติทั้งหลายเป็นอันมากที่อยู่กับเจ้า ทุกคนขี่ม้าเป็นกองทัพมหึมา เป็นกองทัพทรงกําลังยิ่งนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 16, 'เจ้าจะมาต่อสู้อิสราเอลประชาชนของเรา เหมือนอย่างเมฆคลุมแผ่นดินในกาลภายหน้า เราจะนําเจ้ามาต่อสู้กับแผ่นดินของเรา เพื่อประชาชาติทั้งหลายจะรู้จักเรา โอ โกกเอ๋ย ในเมื่อเราสําแดงความบริสุทธิ์ของเราท่ามกลางเจ้าต่อหน้าต่อตาเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 17, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า เจ้าเป็นผู้นั้นหรือผู้ที่ในสมัยก่อนเราได้พูดถึงโดยผู้พยากรณ์ของอิสราเอลผู้รับใช้ของเรา ผู้ซึ่งในสมัยนั้นได้พยากรณ์อยู่หลายปีว่า เราจะนําเจ้ามาต่อสู้กับเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 18, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสว่า แต่ต่อมาในเวลานั้นเมื่อโกกจะยกมาต่อสู้กับแผ่นดินอิสราเอล ความพิโรธของเราจะพลุ่งขึ้นต่อหน้าเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 19, 'เพราะเราขอประกาศด้วยความหวงแหนและด้วยความพิโรธดั่งเพลิงพลุ่งของเราว่า ในวันนั้นจะมีการสั่นสะเทือนใหญ่ยิ่งในแผ่นดินอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 20, 'ปลาที่ทะเลและนกในอากาศ และสัตว์ป่าทุ่งและบรรดาสัตว์เลื้อยคลานที่คลานอยู่บนแผ่นดิน และประชาชนทั้งสิ้นที่อยู่บนพื้นพิภพจะสั่นสะเทือนต่อหน้าเรา ภูเขาจะพังทลายลง และหน้าผาจะพัง และกําแพงทุกแห่งจะล้มลงที่ดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 21, 'เราจะร้องถึงภูเขาทั้งหลายของเราเรียกดาบมาต่อสู้กับโกก องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้แหละ และดาบของทุกคนจะต่อสู้กับพี่น้องของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 22, 'เราจะพิพากษาลงโทษเขาด้วยโรคระบาดและโลหิตตก เราจะให้ฝนตกอย่างน้ําไหลเชี่ยว ทั้งลูกเห็บและไฟ และไฟกํามะถันตกใส่เขาและกองทัพของเขาและชนชาติทั้งหลายเป็นอันมากที่อยู่กับเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 23, 'ดังนั้นเราจะสําแดงความยิ่งใหญ่ของเราและชําระตัวของเราให้บริสุทธิ์ และเราจะเป็นที่รู้จักท่ามกลางสายตาของประชาชาติเป็นอันมาก แล้วเขาจะทราบว่าเราคือพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 1, '“เพราะฉะนั้น เจ้า บุตรแห่งมนุษย์เอ๋ย จงพยากรณ์กล่าวโทษโกก และกล่าวว่า องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า ดูเถิด โอ โกกเอ๋ย เราเป็นปฏิปักษ์กับเจ้า ผู้เป็นเจ้าองค์สําคัญแห่งเมเชคและทูบัล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 2, 'เราจะให้เจ้าหันกลับ และเจ้าจะเหลือแค่หนึ่งในหกส่วน และให้เจ้าขึ้นมาจากส่วนเหนือที่สุด และให้เจ้าเข้าไปต่อสู้ภูเขาทั้งหลายแห่งอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 3, 'แล้วเราจะตีคันธนูให้หลุดจากมือซ้ายของเจ้า และเราจะให้ลูกธนูตกจากมือขวาของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 4, 'เจ้าจะล้มลงบนภูเขาแห่งอิสราเอล ทั้งเจ้าและกองทัพทั้งสิ้นของเจ้า และชนชาติทั้งหลายที่อยู่กับเจ้า เราจะมอบเจ้าให้เป็นอาหารแก่เหยี่ยวทุกชนิดและแก่สัตว์ป่าทุ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 5, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสว่า เจ้าจะล้มลงบนพื้นทุ่ง เพราะเราได้ลั่นวาจาแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 6, 'เราจะส่งเพลิงมาเหนือมาโกก และท่ามกลางผู้ที่อาศัยอยู่อย่างไร้กังวลตามเกาะต่างๆ และเขาทั้งหลายจะทราบว่าเราคือพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 7, 'และเราจะกระทําให้นามบริสุทธิ์ของเราเป็นที่รู้จักในท่ามกลางอิสราเอลประชาชนของเรา เราจะไม่ยอมให้อิสราเอลทําให้นามบริสุทธิ์ของเรามัวหมองอีกต่อไป และประชาชาติจะทราบว่า เราคือพระเยโฮวาห์ องค์บริสุทธิ์ในอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 8, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสว่า ดูเถิด มาแล้ว และจะเป็นอย่างนั้น คือวันนั้นซึ่งเราได้ลั่นวาจาไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 9, 'แล้วบรรดาคนเหล่านั้นที่อาศัยอยู่ในบรรดาหัวเมืองอิสราเอลจะออกไป และจะเอาไฟสุมเครื่องอาวุธเผาเสียคือโล่และดั้ง คันธนูและลูกธนู หอกยาวและหอกซัด และเขาจะเอาไฟสุมเป็นเวลาเจ็ดปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 10, 'เพราะฉะนั้น เขาไม่จําเป็นจะต้องเอาฟืนมาจากทุ่งนาหรือตัดฟืนมาจากป่า เพราะเขาจะก่อไฟด้วยเครื่องอาวุธ และเขาทั้งหลายจะแย่งชิงผู้ที่แย่งชิงเขา และจะปล้นผู้ที่ปล้นเขา องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 11, 'ต่อมาในวันนั้น เราจะให้โกกมีสุสานอยู่ในอิสราเอล คือหุบเขาของคนเดินผ่านไปมา ซึ่งอยู่ทางทิศตะวันออกของทะเล มันจะปิดจมูกของคนเดินผ่านไปมา เพราะว่าโกกและหมู่นิกรทั้งสิ้นของท่านจะถูกฝังไว้ที่นั่น เขาจะเรียกกันว่า หุบเขาฮาโมนโกก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 12, 'วงศ์วานอิสราเอลจะฝังเขาทั้งหลายอยู่ถึงเจ็ดเดือน เพื่อจะทําให้แผ่นดินนั้นสะอาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 13, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสว่า ประชาชนทุกคนแห่งแผ่นดินจะฝังเขาทั้งหลาย ในวันนั้นเมื่อเราสําแดงสง่าราศีของเรา ประชาชนนั้นจะได้รับเกียรติเพราะการฝังศพนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 14, 'เขาทั้งหลายจะตั้งคนให้เดินผ่านไปมาในแผ่นดินเรื่อยไป ให้ฝังศพคนเหล่านั้นที่เหลืออยู่บนพื้นแผ่นดิน เพื่อจะทําแผ่นดินให้สะอาด เขาจะออกตรวจค้นเมื่อสิ้นเจ็ดเดือนแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 15, 'เมื่อคนเหล่านั้นผ่านไปมาในแผ่นดิน ถ้าใครเห็นกระดูกคนเข้า เขาจะเอาเครื่องหมายปักไว้ข้างกระดูกนั้น จนกว่าคนฝังจะมาฝังเขาไว้ในหุบเขาฮาโมนโกก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 16, 'หัวเมืองหนึ่งชื่อ ฮาโมนาห์ ก็อยู่ที่นั่นด้วย เขาจะทําให้แผ่นดินสะอาดดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 17, 'เจ้า บุตรแห่งมนุษย์เอ๋ย องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า จงพูดกับนกทุกชนิดและพูดกับเหล่าสัตว์ป่าทุ่งว่า ‘จงชุมนุมและมาเถิด รวมกันมาจากทุกด้านมายังการเลี้ยงสักการบูชา ซึ่งเราถวายเพื่อเจ้า เป็นการเลี้ยงสักการบูชาใหญ่บนภูเขาทั้งหลายแห่งอิสราเอล และเจ้าจะรับประทานเนื้อและดื่มโลหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 18, 'เจ้าจะรับประทานเนื้อของผู้แกล้วกล้า และดื่มโลหิตของเจ้านายแห่งพิภพ ของแกะผู้ ของลูกแกะ และของแพะกับของวัวผู้ ทั้งสิ้นนี้เป็นสัตว์อ้วนพีแห่งเมืองบาชาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 19, 'และเจ้าจะรับประทานไขมันจนเจ้าอิ่มหนํา และดื่มโลหิตจนเจ้าจะเมา ณ การเลี้ยงสักการบูชาซึ่งเราได้ถวายเพื่อเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 20, 'และเจ้าจะอิ่มหนําที่สํารับของเราด้วยเนื้อม้าและผู้ขับขี่ ทั้งเนื้อของผู้แกล้วกล้า และของนักรบทุกชนิด’ องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 21, 'และเราจะตั้งสง่าราศีของเราไว้ในหมู่ประชาชาติทั้งหลาย และประชาชาติทั้งสิ้นจะเห็นการพิพากษาลงโทษของเราซึ่งเราได้กระทํา และเห็นมือของเราซึ่งเราวางไว้บนเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 22, 'ตั้งแต่วันนั้นเป็นต้นไป วงศ์วานอิสราเอลจะทราบว่า เราคือพระเยโฮวาห์พระเจ้าของเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 23, 'และประชาชาติทั้งหลายจะทราบว่า วงศ์วานอิสราเอลได้ถูกกวาดไปเป็นเชลยเพราะเหตุความชั่วช้าของเขา เพราะเขาได้ละเมิดต่อเรา ดังนั้นเราจึงซ่อนหน้าของเราเสียจากเขา และมอบเขาไว้ในมือพวกศัตรูของเขา เขาจึงล้มลงด้วยดาบสิ้นทุกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 24, 'เราได้กระทําต่อความโสโครกและการละเมิดของเขาทั้งหลาย และเราซ่อนหน้าของเราเสียจากเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 25, 'เพราะฉะนั้น องค์พระผู้เป็นเจ้าพระเจ้าตรัสว่า บัดนี้เราจะให้ยาโคบกลับสู่สภาพเดิม และจะมีความกรุณาต่อวงศ์วานอิสราเอลทั้งสิ้น และเราจะหวงแหนนามบริสุทธิ์ของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 26, 'หลังจากที่เขาทั้งหลายได้ทนรับความอับอายขายหน้าของเขา ทั้งการละเมิดทั้งสิ้นซึ่งเขาทั้งหลายได้เคยประพฤติต่อเรา ขณะที่เขาทั้งหลายอาศัยอยู่อย่างปลอดภัยในแผ่นดินของเขา และไม่มีผู้ใดกระทําให้เขาหวาดกลัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 27, 'เมื่อเราได้นําเขากลับมาจากชนชาติทั้งหลาย และรวบรวมเขามาจากแผ่นดินศัตรูของเขา และเมื่อเราสําแดงความบริสุทธิ์ของเราท่ามกลางเขาทั้งหลายท่ามกลางสายตาของประชาชาติเป็นอันมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 28, 'แล้วเขาจะทราบว่าเราคือพระเยโฮวาห์พระเจ้าของเขา เพราะเราได้ส่งให้เขาถูกกวาดไปเป็นเชลยอยู่ท่ามกลางบรรดาประชาชาติ แล้วก็รวบรวมเขาเข้ามาในแผ่นดินของเขาทั้งหลาย เราจะไม่ปล่อยให้สักคนหนึ่งในพวกเขาเหลืออยู่ท่ามกลางบรรดาประชาชาติอีกเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 29, 'และเราจะไม่ซ่อนหน้าของเราไว้จากเขาทั้งหลายอีกเลย เมื่อเราเทวิญญาณของเราเหนือวงศ์วานอิสราเอล องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้แหละ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 1, 'เมื่อปีที่ยี่สิบห้าที่เราได้ถูกกวาดไปเป็นเชลยนั้น ในต้นปีเมื่อวันที่สิบของเดือน ในปีที่สิบสี่หลังจากที่เขาชนะกรุงนั้น ในวันนั้นทีเดียวพระหัตถ์ของพระเยโฮวาห์มาอยู่เหนือข้าพเจ้าและทรงนําข้าพเจ้ามา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 2, 'ในนิมิตแห่งพระเจ้าพระองค์ทรงนําข้าพเจ้ามาถึงแผ่นดินอิสราเอล และพระองค์ทรงวางข้าพเจ้าไว้บนภูเขาสูงมาก ซึ่งตรงนั้นทางทิศใต้มีสิ่งก่อสร้างเหมือนเมืองหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 3, 'เมื่อพระองค์ทรงนําข้าพเจ้ามา ณ ที่นั่น ดูเถิด มีชายคนหนึ่ง ปรากฏการณ์ของเขาคล้ายทองเหลือง มีเชือกป่านเส้นหนึ่งและไม้วัดอันหนึ่งอยู่ในมือ และท่านยืนอยู่ที่หอประตู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 4, 'และชายผู้นั้นกล่าวแก่ข้าพเจ้าว่า “บุตรแห่งมนุษย์เอ๋ย จงมองดูด้วยตาเองเถิด และจงฟังด้วยหูของเจ้า และจงเอาใจใส่กับสิ่งทั้งสิ้นที่เราจะสําแดงให้แก่เจ้า เพราะว่าที่นําเจ้ามาที่นี่ก็เพื่อจะสําแดงให้แก่เจ้า สิ่งทั้งสิ้นที่เจ้าเห็นนั้น จงประกาศแก่วงศ์วานอิสราเอล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 5, 'และดูเถิด มีกําแพงล้อมอยู่รอบบริเวณนอกของพระนิเวศ และในมือของชายผู้นั้นมีไม้วัดยาวหกศอก แต่ละศอกยาวเท่ากับศอกคืบ ดังนั้นท่านจึงวัดความหนาของกําแพงได้หนึ่งไม้วัด และความสูงได้หนึ่งไม้วัด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 6, 'แล้วท่านเข้าไปตามหอประตูซึ่งหันหน้าไปทิศตะวันออกขึ้นไปตามบันได และวัดธรณีหอประตูได้ลึกหนึ่งไม้วัดและอีกธรณีหนึ่งได้ลึกหนึ่งไม้วัด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 7, 'และห้องยามยาวหนึ่งไม้วัด และกว้างหนึ่งไม้วัด และที่ว่างระหว่างห้องยามเหล่านั้นยาวห้าศอก และธรณีหอประตูที่อยู่ริมมุขที่หอประตูตอนปลายชั้นในได้หนึ่งไม้วัด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 8, 'แล้วท่านก็วัดมุขของหอประตูตอนปลายชั้นในได้หนึ่งไม้วัด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 9, 'และท่านก็วัดมุขของหอประตูได้แปดศอก และเสามุขนั้นสองศอก และมุขของหอประตูอยู่ที่ตอนปลายข้างใน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 10, 'แต่ละด้านของหอประตูตะวันออกมีห้องยามอยู่สามห้อง ห้องทั้งสามมีขนาดเดียวกัน และเสาที่อยู่ทั้งสองข้างก็มีขนาดเดียวกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 11, 'แล้วท่านจึงวัดความกว้างช่องเปิดของทางเข้าหอประตูได้สิบศอก และความยาวของหอประตูสิบสามศอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 12, 'หน้าห้องยามนั้นมีเครื่องกั้นด้านละหนึ่งศอก และห้องยามนั้นยาวด้านละหกศอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 13, 'แล้วท่านก็วัดหอประตูจากหลังคาของห้องยามห้องหนึ่งไปยังหลังคาของห้องยามอีกห้องหนึ่ง ได้กว้างยี่สิบห้าศอก จากทางเข้าหนึ่งไปยังอีกทางเข้าหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 14, 'และท่านทําเสาทั้งหลายได้หกสิบศอก และรอบหอประตูมีลานไปถึงเสา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 15, 'วัดจากข้างหน้าหอประตูตรงทางเข้าไปยังปลายมุขชั้นในของหอประตูได้ห้าสิบศอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 16, 'ตามหอประตูนั้นมีหน้าต่างรอบ ค่อยๆแคบเข้าไปข้างในทั้งในเสาและในห้องยามและมุขก็มีหน้าต่างอยู่รอบข้างในเหมือนกัน ที่เสามีต้นอินทผลัม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 17, 'แล้วท่านนําข้าพเจ้าออกมาที่ลานชั้นนอก และดูเถิด มีห้องหลายห้องและมีพื้นหินทําไว้รอบลาน มีห้องสามสิบห้องหันหน้าเข้าหาพื้นหิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 18, 'และพื้นหินนั้นมีอยู่ตามด้านข้างทางเข้าหอประตู เท่ากับความยาวของหอประตู นี่เป็นพื้นหินตอนล่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 19, 'แล้วท่านก็วัดความกว้างจากหน้าหอประตูข้างล่างไปยังหน้าลานข้างในด้านนอกได้หนึ่งร้อยศอก อยู่ทั้งทางตะวันออกและทางเหนือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 20, 'ส่วนหอประตูแห่งลานนอกหันหน้าไปทางเหนือ ท่านก็วัดความยาวและความกว้างของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 21, 'ห้องยามด้านละสามห้อง กับเสาและมุขมีขนาดเดียวกับหอประตูแรก ยาวห้าสิบศอก กว้างยี่สิบห้าศอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 22, 'หน้าต่าง มุข ต้นอินทผลัมของหอประตูนี้มีขนาดเดียวกับของหอประตูซึ่งหันหน้าไปทางทิศตะวันออก และมีบันไดเจ็ดขั้นนําขึ้นไปถึง และมุขนั้นอยู่ข้างใน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 23, 'ตรงข้ามกับประตูซึ่งอยู่ข้างเหนือเช่นเดียวกับประตูที่อยู่ข้างตะวันออก มีประตูเปิดไปสู่ลานชั้นใน และท่านก็วัดจากประตูหนึ่งไปยังอีกประตูหนึ่งได้หนึ่งร้อยศอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 24, 'และท่านได้นําข้าพเจ้าตรงไปยังทิศใต้ และดูเถิด มีหอประตูทางทิศใต้หนึ่งหอประตู ท่านก็วัดเสาและวัดมุข ก็มีขนาดเดียวกับที่อื่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 25, 'มีหน้าต่างที่หอประตูและที่มุขโดยรอบเหมือนหน้าต่างที่อื่น ยาวห้าสิบศอกและกว้างยี่สิบห้าศอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 26, 'มีบันไดเจ็ดขั้นนําขึ้นไปถึง และมุขนั้นอยู่ข้างใน มีต้นอินทผลัมอยู่ที่เสาด้านละต้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 27, 'และมีประตูหนึ่งอยู่ทางทิศใต้ของลานชั้นใน และท่านก็วัดจากประตูหนึ่งไปยังอีกประตูหนึ่งตรงไปทางทิศใต้ ได้หนึ่งร้อยศอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 28, 'แล้วท่านนําข้าพเจ้ามายังลานชั้นในโดยประตูทิศใต้ และท่านก็วัดประตูทิศใต้ มีขนาดอย่างเดียวกับประตูอื่นๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 29, 'ห้องยาม เสา และมุขของหอประตูนี้มีขนาดเดียวกับที่อื่น มีหน้าต่างที่หอประตูและที่มุขโดยรอบ ยาวห้าสิบศอกและกว้างยี่สิบห้าศอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 30, 'มีมุขอยู่รอบยาวยี่สิบห้าศอก กว้างห้าศอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 31, 'มุขนั้นหันหน้าสู่ลานชั้นนอก มีต้นอินทผลัมอยู่ที่เสา และบันไดนี้มีแปดขั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 32, 'แล้วท่านก็พาข้าพเจ้ามาที่ลานชั้นในด้านตะวันออก และท่านก็วัดหอประตูขนาดเดียวกับหอประตูอื่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 33, 'ห้องยาม เสา และมุขของหอประตูนี้มีขนาดเดียวกันกับที่อื่น มีหน้าต่างที่หอประตูและที่มุขโดยรอบ ยาวห้าสิบศอกและกว้างยี่สิบห้าศอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 34, 'มุขของด้านนี้หันหน้าสู่ลานชั้นนอก และมีต้นอินทผลัมอยู่ที่เสาด้านละต้น และบันไดนี้มีแปดขั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 35, 'แล้วท่านก็นําข้าพเจ้ามายังประตูเหนือ แล้วท่านก็วัดหอประตูนั้นมีขนาดเดียวกับหอประตูอื่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 36, 'ห้องยาม เสา และมุขของหอประตูนี้มีขนาดเดียวกันกับที่อื่น มีหน้าต่างโดยรอบ ยาวห้าสิบศอกและกว้างยี่สิบห้าศอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 37, 'มุขของด้านนี้หันหน้าสู่ลานชั้นนอก และมีต้นอินทผลัมอยู่ที่เสาด้านละต้น และบันไดนี้มีแปดขั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 38, 'มีห้องๆหนึ่งและมีทางเข้าอยู่ที่เสาของหอประตู เป็นที่ล้างเครื่องเผาบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 39, 'และที่มุมของหอประตูมีโต๊ะด้านละสองโต๊ะ บนนี้สําหรับฆ่าเครื่องเผาบูชา เครื่องบูชาไถ่บาป และเครื่องบูชาไถ่การละเมิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 40, 'และทางด้านนอก ทางที่เขาขึ้นไปถึงทางเข้าหอประตูเหนือมีโต๊ะสองโต๊ะ อีกด้านหนึ่งของมุมของหอประตูมีโต๊ะสองโต๊ะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 41, 'มีโต๊ะอยู่ข้างนี้สี่โต๊ะ และมีโต๊ะอยู่ข้างนั้นข้างๆหอประตูสี่โต๊ะ เป็นแปดโต๊ะด้วยกัน ซึ่งเขาใช้เป็นที่ฆ่าเครื่องสัตวบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 42, 'มีโต๊ะสี่โต๊ะทําด้วยหินสกัดสําหรับเครื่องเผาบูชา ยาวหนึ่งศอกคืบและกว้างหนึ่งศอกคืบ สูงหนึ่งศอก สําหรับวางเครื่องมือซึ่งเขาใช้ฆ่าเครื่องเผาบูชา และเครื่องสัตวบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 43, 'มีตะขอยาวคืบหนึ่งติดอยู่ข้างในโดยรอบ บนโต๊ะนี้เขาวางเนื้อของเครื่องบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 44, 'ข้างนอกหอประตูชั้นใน ในลานชั้นในมีห้องสําหรับพวกนักร้อง ซึ่งอยู่ข้างหอประตูเหนือ หันหน้าไปทิศใต้ อีกห้องหนึ่งอยู่ข้างหอประตูตะวันออก หันหน้าไปทิศเหนือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 45, 'และท่านบอกข้าพเจ้าว่า “ห้องนี้ซึ่งหันหน้าไปทางทิศใต้สําหรับปุโรหิตผู้ดูแลพระนิเวศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 46, 'และห้องซึ่งหันหน้าไปทางเหนือ สําหรับปุโรหิตผู้ดูแลแท่นบูชา ปุโรหิตเหล่านี้เป็นบุตรชายของศาโดกในบรรดาบุตรชายของเลวี ที่เข้ามาใกล้พระเยโฮวาห์เพื่อจะปรนนิบัติพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 47, 'และท่านก็วัดลาน ได้ยาวหนึ่งร้อยศอก และกว้างหนึ่งร้อยศอกเป็นสี่เหลี่ยมจตุรัส และแท่นบูชาอยู่ข้างหน้าพระนิเวศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 48, 'แล้วท่านนําข้าพเจ้ามาที่มุขของพระนิเวศและวัดเสาของมุขได้ห้าศอกทั้งสองด้าน และหอประตูก็กว้างด้านละสามศอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 49, 'มุขนั้นยาวยี่สิบศอกและกว้างสิบเอ็ดศอก และท่านนําข้าพเจ้าทางบันไดไปถึงที่นั้น และมีเสาอยู่ข้างเสาทั้งสองข้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 1, 'ภายหลังท่านนําข้าพเจ้ามาถึงพระวิหาร และได้วัดเสา กว้างด้านละหกศอก ซึ่งเท่ากับความกว้างของพลับพลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 2, 'และส่วนกว้างของทางเข้านั้นสิบศอก และกําแพงข้างทางเข้าด้านละห้าศอก และท่านก็วัดความยาวของพระวิหารได้สี่สิบศอก กว้างยี่สิบศอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 3, 'แล้วท่านก็เข้าไปข้างในและวัดเสาของทางเข้าได้สองศอก ทางเข้านั้นหกศอก และส่วนกว้างของทางเข้านั้นเจ็ดศอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 4, 'และท่านก็วัดความยาวของห้องได้ยี่สิบศอก กว้างยี่สิบศอก พ้นพระวิหารออกไป และท่านบอกข้าพเจ้าว่า “นี่เป็นที่บริสุทธิ์ที่สุด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 5, 'แล้วท่านก็วัดกําแพงพระนิเวศได้หนาหกศอก และห้องระเบียงนั้นกว้างสี่ศอก อยู่รอบพระนิเวศทุกด้าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 6, 'ห้องระเบียงนั้นเป็นห้องสามชั้นซ้อนกัน มีชั้นละสามสิบห้อง มีหยักบ่าอยู่รอบกําแพงพระนิเวศ ใช้เป็นที่หนุนห้องระเบียง เพื่อไม่ให้ห้องระเบียงอาศัยกําแพงพระนิเวศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 7, 'ห้องระเบียงนั้นยิ่งสูงขึ้นไปก็ยิ่งกว้างออก ตามส่วนขยายของหยักบ่าจากห้องหนึ่งซ้อนอยู่บนอีกห้องหนึ่งโดยรอบ ที่ข้างพระนิเวศมีบันไดนําขึ้นข้างบน ดังนี้แหละผู้ใดที่ขึ้นไปจากห้องต่ําที่สุดถึงห้องบนก็ต้องลอดผ่านห้องกลาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 8, 'ข้าพเจ้ายังเห็นอีกว่า พระนิเวศนั้นมียกพื้นอยู่โดยรอบ ฐานของห้องระเบียงวัดได้หนึ่งไม้วัดเต็ม ยาวหกศอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 9, 'ผนังด้านนอกของห้องระเบียงหนาห้าศอก และส่วนที่ว่างคือสถานที่ของห้องระเบียงที่อยู่ข้างในนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 10, 'ระหว่างห้องระเบียงแต่ละห้องมีความกว้างยี่สิบศอกโดยรอบพระนิเวศทุกด้าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 11, 'และประตูของห้องระเบียงนั้นเปิดเข้าไปในส่วนบนยกพื้นที่ว่าง ประตูหนึ่งหันไปทางเหนือ และอีกประตูหนึ่งหันไปทางใต้ ความกว้างของส่วนที่ว่างนั้นคือห้าศอกโดยรอบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 12, 'ตึกที่หันหน้ามายังสนามของพระนิเวศทางด้านตะวันตกนั้นกว้างเจ็ดสิบศอก และผนังของตึกหนาห้าศอกโดยรอบและยาวเก้าสิบศอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 13, 'แล้วท่านก็วัดพระนิเวศได้ยาวหนึ่งร้อยศอก สนามและตึกพร้อมกับผนังยาวหนึ่งร้อยศอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 14, 'ความกว้างด้านตะวันออกของด้านหน้าของพระนิเวศทั้งของสนาม ยาวหนึ่งร้อยศอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 15, 'แล้วท่านก็วัดความยาวของตึกซึ่งหันหน้าไปสู่สนามซึ่งอยู่ด้านหลัง พร้อมทั้งผนังข้างๆ ยาวหนึ่งร้อยศอก ห้องโถงของพระวิหารนั้นและลานของมุข');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 16, 'ทั้งธรณีประตู หน้าต่างและผนังรอบทั้งสามชั้นซึ่งอยู่ตรงข้ามประตู บุไม้โดยรอบตั้งแต่พื้นถึงหน้าต่าง และหน้าต่างนี้ก็คลุมไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 17, 'จนถึงที่อยู่เหนือประตู ถึงแม้เป็นห้องชั้นในและข้างนอก และบนผนังโดยรอบที่ห้องชั้นในและห้องโถง ก็กระทําโดยการวัด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 18, 'พระนิเวศนั้นมีรูปเครูบและรูปต้นอินทผลัม และรูปต้นอินทผลัมอยู่ระหว่างเครูบทุกรูป เครูบทุกตนมีสองหน้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 19, 'หน้าของผู้ชายตรงต้นอินทผลัมที่อยู่ข้างหนึ่ง และหน้าของสิงโตหนุ่มตรงต้นอินทผลัมที่อยู่อีกข้างหนึ่ง มีรูปอย่างนี้รอบพระนิเวศทั้งหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 20, 'จากพื้นถึงที่เหนือประตู มีรูปเครูบและรูปต้นอินทผลัมแกะอยู่ที่ผนังพระวิหาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 21, 'ฝ่ายเสาประตูของพระวิหารนั้นสี่เหลี่ยมข้างหน้าสถานบริสุทธิ์ รูปร่างของตัวนั้นก็เหมือนรูปร่างของอีกตัวหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 22, 'แท่นบูชาทําด้วยไม้สูงสามศอกยาวสองศอก ทั้งมุม ความยาว และที่ผนังทําด้วยไม้ ท่านบอกข้าพเจ้าว่า “นี่เป็นโต๊ะซึ่งอยู่ต่อพระพักตร์ของพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 23, 'พระวิหารและสถานบริสุทธิ์มีประตูคู่แห่งละคู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 24, 'ประตูเหล่านั้นมีสองบาน คือบานเหวี่ยงสองบาน ประตูหนึ่งมีสองบาน และอีกประตูหนึ่งมีสองบาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 25, 'และบนประตูของพระวิหาร มีเครูบและต้นอินทผลัมแกะไว้ เช่นเดียวกับที่แกะไว้บนผนัง มีพลับพลาไม้อยู่ที่หน้ามุขข้างนอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 26, 'มีหน้าต่างและมีต้นอินทผลัมอยู่ทั้งสองข้างที่บนผนังด้านข้างมุข ทั้งห้องระเบียงพระนิเวศและพลับพลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 1, 'แล้วท่านพาข้าพเจ้ามาถึงลานชั้นนอก ตรงทิศเหนือ และท่านนําข้าพเจ้ามาถึงห้องซึ่งอยู่ตรงข้ามกับสนาม และตรงข้ามกับตึกทางด้านทิศเหนือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 2, 'ความยาวของตึกที่อยู่หน้าประตูทางด้านเหนือนั้นเป็นหนึ่งร้อยศอก และกว้างห้าสิบศอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 3, 'ติดต่อกับส่วนยี่สิบศอกซึ่งเป็นส่วนของลานชั้นใน หันหน้าเข้าสู่พื้นหินซึ่งเป็นส่วนของลานข้างนอก เป็นระเบียงซ้อนระเบียงสามชั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 4, 'และข้างหน้าห้องมีทางเข้าข้างในกว้างสิบศอก ยาวหนึ่งศอก บรรดาประตูห้องเหล่านี้อยู่ทางด้านเหนือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 5, 'ห้องข้างบนแคบกว่า เพราะระเบียงเหล่านี้สูงกว่าระเบียงห้องชั้นล่าง และชั้นกลางในตึกนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 6, 'เพราะว่าเป็นห้องสามชั้น และไม่มีเสารองเหมือนเสาที่ลานข้างนอก เพราะฉะนั้นห้องชั้นบนจึงร่นเข้าไปกว่าพื้นมากกว่าห้องชั้นล่างและชั้นกลาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 7, 'และมีผนังข้างนอกขนานกับห้อง ตรงไปยังลานข้างนอก ตรงข้ามกับห้อง ยาวห้าสิบศอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 8, 'เพราะว่าห้องที่ลานข้างนอกยาวห้าสิบศอก และดูเถิด ส่วนห้องเหล่านั้นที่ตรงข้ามกับพระวิหารยาวหนึ่งร้อยศอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 9, 'ใต้ห้องเหล่านั้นมีทางเข้าอยู่ด้านตะวันออก ถ้าเข้าไปจากลานข้างนอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 10, 'ตรงที่ผนังด้านนอกเริ่มต้น ด้านตะวันออกก็เช่นเดียวกัน ตรงข้ามกับสนามและตรงข้ามกับตึกมีห้องหลายห้อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 11, 'ทางเดินอยู่หน้าห้องคล้ายกับห้องทางทิศเหนือ ยาวและกว้างขนาดเดียวกัน มีทางออก แผนผังและประตูอย่างเดียวกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 12, 'ข้างล่างห้องทิศใต้มีทางเข้าอยู่ด้านตะวันออกที่ที่เข้ามาตามทางเดิน ตรงข้ามมีผนังแบ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 13, 'แล้วท่านกล่าวแก่ข้าพเจ้าว่า “ห้องด้านเหนือและห้องด้านใต้ตรงข้ามสนามเป็นห้องบริสุทธิ์ ที่ปุโรหิตผู้เข้าใกล้พระเยโฮวาห์จะรับประทานของถวายอันบริสุทธิ์ที่สุด เขาจะวางของถวายอันบริสุทธิ์ที่สุดนั้นไว้ที่นั่น และธัญญบูชา เครื่องบูชาไถ่บาป เครื่องบูชาไถ่การละเมิดเพราะว่าที่นั่นบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 14, 'เมื่อปุโรหิตเข้าไปในที่บริสุทธิ์ เขาจะไม่ออกไปจากที่บริสุทธิ์เข้าสู่ลานข้างนอก แต่จะปลดเครื่องแต่งกายที่เขาสวมปฏิบัติหน้าที่วางไว้ที่นั่นเพราะสิ่งเหล่านี้บริสุทธิ์ เขาจะต้องสวมเครื่องแต่งกายอื่นก่อนที่เขาจะเข้าไปสู่ส่วนที่มีไว้สําหรับประชาชน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 15, 'เมื่อท่านได้วัดข้างในบริเวณพระนิเวศเสร็จแล้ว ท่านก็นําข้าพเจ้าออกมาทางประตูซึ่งหันหน้าไปทางทิศตะวันออก และวัดบริเวณพระนิเวศโดยรอบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 16, 'ท่านวัดด้านตะวันออกด้วยไม้วัดได้ห้าร้อยศอกตามไม้วัดโดยรอบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 17, 'แล้วท่านก็หันมาวัดทางด้านเหนือได้ห้าร้อยศอกตามไม้วัดโดยรอบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 18, 'แล้วท่านก็หันมาวัดด้านใต้ได้ห้าร้อยศอกตามไม้วัด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 19, 'แล้วท่านก็หันมาด้านตะวันตกแล้ววัดได้ห้าร้อยศอกตามไม้วัด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 20, 'ท่านวัดทั้งสี่ด้าน มีกําแพงล้อมรอบยาวห้าร้อยศอก กว้างห้าร้อยศอก เป็นที่แบ่งระหว่างสถานบริสุทธิ์กับสถานที่สามัญ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 1, 'ภายหลังท่านนําข้าพเจ้ามายังประตู คือประตูที่หันหน้าไปทิศตะวันออก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 2, 'และ ดูเถิด สง่าราศีของพระเจ้าแห่งอิสราเอลมาจากทิศตะวันออก และพระสุรเสียงของพระองค์ก็เหมือนเสียงน้ํามากหลาย และพิภพก็รุ่งโรจน์ด้วยสง่าราศีของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 3, 'และนิมิตที่ข้าพเจ้าเห็นนั้นก็เหมือนกับนิมิตซึ่งข้าพเจ้าเห็นเมื่อพระองค์เสด็จมาทําลายเมืองนั้น และเหมือนกับนิมิตซึ่งข้าพเจ้าได้เห็นที่ริมแม่น้ําเคบาร์ และข้าพเจ้าก็ซบหน้าของข้าพเจ้าลงถึงดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 4, 'และสง่าราศีของพระเยโฮวาห์ได้เข้าไปในพระนิเวศทางประตูที่หันไปทางทิศตะวันออก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 5, 'พระวิญญาณก็ยกข้าพเจ้าขึ้น และนําข้าพเจ้ามาที่ลานชั้นใน และดูเถิด สง่าราศีของพระเยโฮวาห์ก็เต็มพระนิเวศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 6, 'ขณะที่ชายคนนั้นยังยืนอยู่ที่ข้างข้าพเจ้า ข้าพเจ้าได้ยินพระองค์ตรัสกับข้าพเจ้าดังออกมาจากพระนิเวศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 7, 'และพระองค์ตรัสกับข้าพเจ้าว่า “บุตรแห่งมนุษย์เอ๋ย บัลลังก์ของเราและสถานที่วางเท้าของเราอยู่ที่นี่ เป็นที่ที่เราจะอยู่ท่ามกลางชนชาติอิสราเอลเป็นนิตย์ และวงศ์วานอิสราเอลจะไม่กระทําให้นามบริสุทธิ์ของเราเป็นมลทินอีก โดยตัวของเขาทั้งหลายเองหรือกษัตริย์ของเขาทั้งหลาย ด้วยการเล่นชู้ของเขาทั้งหลาย และด้วยศพของกษัตริย์ของเขาทั้งหลายในปูชนียสถานสูง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 8, 'โดยการวางธรณีประตูของเขาทั้งหลายไว้ข้างธรณีประตูทั้งหลายของเรา โดยการตั้งเสาประตูของเขาทั้งหลายไว้ข้างเสาประตูทั้งหลายของเรา มีเพียงผนังกั้นไว้ระหว่างเรากับเขาทั้งหลายเท่านั้น เขาได้กระทําให้นามบริสุทธิ์ของเราเป็นมลทินด้วยการอันน่าสะอิดสะเอียนของเขาซึ่งเขาทั้งหลายได้กระทํา ดังนั้นเราจึงเผาผลาญเขาเสียด้วยความกริ้วของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 9, 'บัดนี้ให้เขาทิ้งการเล่นชู้ทั้งหลายของเขาและศพของกษัตริย์ทั้งหลายของเขาให้ห่างไกลจากเรา และเราจะอยู่ท่ามกลางเขาทั้งหลายเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 10, 'เจ้า บุตรแห่งมนุษย์เอ๋ย เจ้าจงบรรยายแก่วงศ์วานอิสราเอลให้ทราบถึงพระนิเวศ เพื่อว่าเขาจะได้ละอายในเรื่องความชั่วช้าของเขา และให้เขาทั้งหลายวัดแบบแผน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 11, 'และถ้าเขาละอายในสิ่งทั้งหลายที่เขากระทํามาแล้ว จงสําแดงภาพแผนผังทางออกทางเข้า และลักษณะทั้งสิ้นของพระนิเวศนั้น และจงให้เขาทราบถึงกฎเกณฑ์ ลักษณะและกฎทั้งสิ้นของพระนิเวศ จงเขียนลงไว้ท่ามกลางสายตาของเขา เพื่อเขาจะได้รักษาลักษณะและกฎเกณฑ์ทั้งสิ้นของพระนิเวศ และกระทําตาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 12, 'ต่อไปนี้เป็นกฎของพระนิเวศ คือบริเวณโดยรอบที่อยู่บนยอดภูเขาจะเป็นที่บริสุทธิ์ที่สุด ดูเถิด นี่เป็นกฎของพระนิเวศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 13, 'ต่อไปนี้เป็นขนาดของแท่นบูชาวัดเป็นศอก ศอกหนึ่งคือความยาวหนึ่งศอกกับหนึ่งคืบ ตอนฐานสูงหนึ่งศอก และกว้างหนึ่งศอก ที่ขอบมีริมคืบหนึ่ง และความสูงของแท่นบูชาเป็นดังนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 14, 'จากตอนฐานที่อยู่บนดินมาถึงข้างล่างสูงสองศอก กว้างหนึ่งศอก จากขั้นเล็กไปถึงขั้นใหญ่สูงสี่ศอก กว้างหนึ่งศอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 15, 'และเตาของแท่นนั้นสี่ศอก และจากเตาแท่นมีเชิงงอนยื่นขึ้นสี่เชิง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 16, 'เตาแท่นนั้นเป็นสี่เหลี่ยมจตุรัส ยาวสิบสองศอก กว้างสิบสองศอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 17, 'ขั้นข้างเตาก็สี่เหลี่ยมจตุรัสเหมือนกัน ยาวสิบสี่ศอก กว้างสิบสี่ศอก ยกริมรอบกว้างครึ่งศอก ฐานกว้างศอกหนึ่งโดยรอบ บันไดแท่นบูชาหันหน้าไปทางทิศตะวันออก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 18, 'และท่านพูดกับข้าพเจ้าว่า “บุตรแห่งมนุษย์เอ๋ย องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า ต่อไปนี้เป็นกฎของแท่นบูชาในวันที่สร้างเสร็จแล้ว เพื่อจะถวายเครื่องเผาบูชา และเพื่อจะพรมด้วยเลือด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 19, 'ท่านจงมอบวัวหนุ่มตัวหนึ่งเป็นเครื่องบูชาไถ่บาปแก่ปุโรหิตคนเลวีเชื้อสายศาโดก ผู้ที่เข้ามาใกล้เพื่อปรนนิบัติเรา องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 20, 'เจ้าจงเอาเลือดวัวนั้นบ้างใส่ไว้ที่เชิงงอนทั้งสี่ของแท่น และมุมทั้งสี่ของขั้นข้างเตา และที่ยกริมโดยรอบ ทําดังนี้แหละท่านจะได้ชําระแท่นและทําการลบมลทินของแท่นนั้นไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 21, 'ท่านจงเอาวัวผู้ซึ่งเป็นเครื่องบูชาไถ่บาป และปุโรหิตจะเผามันเสียในที่ที่กําหนดไว้ซึ่งเป็นที่ของพระนิเวศภายนอกสถานบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 22, 'และในวันที่สองท่านจงถวายลูกแพะตัวผู้ที่ปราศจากตําหนิเป็นเครื่องบูชาไถ่บาป และพวกปุโรหิตจะชําระแท่นบูชา อย่างที่ชําระด้วยวัวผู้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 23, 'เมื่อท่านได้ชําระแท่นเสร็จแล้ว ท่านจงถวายวัวหนุ่มปราศจากตําหนิและแกะผู้ที่ปราศจากตําหนิจากฝูง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 24, 'ท่านจงนํามาถวายต่อพระพักตร์พระเยโฮวาห์ และปุโรหิตจะเอาเกลือพรมลงบนนั้น และจะถวายเป็นเครื่องเผาบูชาแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 25, 'ท่านจงเตรียมแพะตัวหนึ่งเป็นเครื่องบูชาไถ่บาปทุกวันจนครบเจ็ดวัน และพวกปุโรหิตจะเตรียมวัวหนุ่มและแกะผู้ที่ปราศจากตําหนิจากฝูงด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 26, 'เขาทั้งหลายจะต้องทําการลบมลทินแท่นบูชาอยู่เจ็ดวันจึงจะชําระเสร็จ และจะสถาปนาตนเองไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 27, 'และเมื่อเขากระทําครบตามกําหนดเหล่านี้แล้ว ตั้งแต่วันที่แปดเป็นต้นไปปุโรหิตจะต้องถวายเครื่องเผาบูชาของท่านและเครื่องสันติบูชาของท่านที่บนแท่นนั้น และเราจะโปรดปรานเจ้าทั้งหลาย องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้แหละ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 1, 'แล้วท่านก็นําข้าพเจ้ากลับมาตามทางของประตูของสถานบริสุทธิ์ห้องนอก ซึ่งหันหน้าไปทางตะวันออก และประตูนั้นปิดอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 2, 'พระเยโฮวาห์ตรัสกับข้าพเจ้าว่า “ประตูนี้จะปิดอยู่เรื่อยไป อย่าให้เปิดและไม่ให้ใครเข้าไปทางนี้ เพราะพระเยโฮวาห์พระเจ้าแห่งอิสราเอลได้เสด็จเข้าไปทางนี้ เพราะฉะนั้นจึงให้ปิดไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 3, 'เฉพาะเจ้านายเท่านั้น คือเจ้านาย ท่านจะประทับเสวยพระกระยาหารต่อพระพักตร์พระเยโฮวาห์ในประตูนี้ได้ ท่านจะต้องเข้ามาทางมุขของหอประตูและต้องออกไปตามทางเดียวกัน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 4, 'แล้วท่านก็นําข้าพเจ้ามาตามทางของประตูเหนือมาที่ข้างหน้าพระนิเวศ และข้าพเจ้ามองดู และดูเถิด สง่าราศีของพระเยโฮวาห์ก็เต็มพระนิเวศของพระเยโฮวาห์ และข้าพเจ้าก็ซบหน้าลงถึงดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 5, 'และพระเยโฮวาห์ตรัสกับข้าพเจ้าว่า “บุตรแห่งมนุษย์เอ๋ย จงตั้งใจให้ดี ทุกสิ่งที่เราจะบอกเจ้าเกี่ยวกับกฎทั้งสิ้นของพระนิเวศของพระเยโฮวาห์ และราชบัญญัติทั้งสิ้นของพระนิเวศนั้น จงดูด้วยตาของเจ้า และฟังด้วยหูของเจ้า และจดจําเรื่องทางเข้าพระนิเวศและทางออกจากสถานบริสุทธิ์ให้ดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 6, 'แล้วจงบอกแก่วงศ์วานที่มักกบฏ คือวงศ์วานอิสราเอลว่า องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า โอ วงศ์วานอิสราเอลเอ๋ย ขอให้การที่น่าสะอิดสะเอียนทั้งสิ้นของเจ้าสิ้นสุดเสียทีเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 7, 'คือการที่เจ้าพาคนต่างด้าวที่มิได้เข้าสุหนัตทางจิตใจและมิได้เข้าสุหนัตทางเนื้อหนังเข้ามาในสถานบริสุทธิ์ของเรา กระทําให้สถานนั้น คือพระนิเวศของเรามัวหมอง เมื่อเจ้าถวายอาหารของเราแก่เรา คือไขมันและเลือด สิ่งเหล่านี้ได้ทําลายพันธสัญญาของเราด้วยการอันน่าสะอิดสะเอียนทั้งสิ้นของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 8, 'และเจ้ามิได้ดูแลรักษาสิ่งบริสุทธิ์ของเรา แต่เจ้าได้ตั้งคนเฝ้าให้ดูแลรักษาอยู่ในสถานบริสุทธิ์ของเรา เพื่อประโยชน์แก่ตัวเจ้าเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 9, 'องค์พระผู้เป็นเจ้าพระเจ้าจึงตรัสดังนี้ว่า อย่าให้คนต่างด้าวที่มิได้เข้าสุหนัตทางจิตใจและมิได้เข้าสุหนัตทางเนื้อหนัง คือชนต่างด้าวทั้งสิ้นที่อยู่ท่ามกลางชนชาติอิสราเอลเข้าไปในสถานบริสุทธิ์ของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 10, 'แต่คนเลวีผู้ที่ได้ไปไกลจากเรา หลงไปจากเราไปติดตามรูปเคารพของเขาเมื่อคนอิสราเอลหลงไปนั้น จะต้องได้รับโทษความชั่วช้าของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 11, 'เขาทั้งหลายจะต้องปรนนิบัติอยู่ในสถานบริสุทธิ์ของเรา ตรวจตราดูอยู่ที่ประตูพระนิเวศ และปฏิบัติอยู่ในพระนิเวศ เขาจะฆ่าเครื่องเผาบูชาและเครื่องสัตวบูชาให้ประชาชน และเขาจะต้องคอยเฝ้าประชาชน เพื่อจะรับใช้เขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 12, 'เพราะเขาทั้งหลายได้ปรนนิบัติประชาชนอยู่หน้ารูปเคารพของเขา จึงทําให้วงศ์วานอิสราเอลตกอยู่ในความชั่วช้า องค์พระผู้เป็นเจ้าพระเจ้าตรัสว่า เพราะฉะนั้นเราจึงได้ปฏิญาณด้วยเรื่องเขาทั้งหลายว่า เขาทั้งหลายจะต้องได้รับโทษความชั่วช้าของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 13, 'อย่าให้เขาทั้งหลายเข้ามาใกล้เรา เพื่อจะรับใช้เราในตําแหน่งปุโรหิต หรือเข้ามาใกล้สิ่งบริสุทธิ์ใดๆของเราในที่บริสุทธิ์ที่สุดนั้น แต่เขาต้องทนรับความอับอายขายหน้า และการอันน่าสะอิดสะเอียนทั้งหลายซึ่งเขาได้กระทํานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 14, 'แต่ถึงกระนั้นเราจะกําหนดให้เขาเป็นผู้ดูแลพระนิเวศ ให้กระทําบริการทั้งสิ้นและกระทําสิ่งที่ต้องกระทําในพระนิเวศนั้นทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 15, 'แต่ปุโรหิตคนเลวี บรรดาบุตรชายของศาโดก ผู้ยังดูแลสถานบริสุทธิ์ของเรา เมื่อคนอิสราเอลหลงไปจากเรานั้น องค์พระผู้เป็นเจ้าพระเจ้าตรัสว่า ให้เขาเข้ามาใกล้เราเพื่อปรนนิบัติเรา และให้คอยรับใช้เรา ที่จะถวายไขมันและเลือด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 16, 'เขาจะเข้ามาในสถานบริสุทธิ์ของเราได้ และให้เขาเข้ามาใกล้โต๊ะของเราเพื่อจะปรนนิบัติเรา และให้เขารักษาคํากําชับของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 17, 'ต่อมาเมื่อเขาเข้าประตูลานชั้นในนั้น ให้เขาสวมเสื้อผ้าป่าน อย่าให้เขามีสิ่งใดที่ทําด้วยขนแกะเลยขณะเมื่อเขาทําการปรนนิบัติอยู่ที่ประตูลานชั้นใน และอยู่ข้างใน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 18, 'ให้เขาสวมมาลาป่านไว้เหนือศีรษะ และสวมกางเกงผ้าป่านเพียงเอว อย่าให้เขาคาดตัวด้วยสิ่งใดที่ให้มีเหงื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 19, 'และเมื่อเขาออกไปยังลานนอก คือไปยังลานนอกเพื่อไปหาประชาชน ให้เขาเปลื้องเสื้อผ้าชุดที่ปรนนิบัติงานนั้นออกเสีย และวางไว้เสียในห้องบริสุทธิ์ แล้วจึงสวมเสื้อผ้าอื่น เกรงว่าเขาจะนําความบริสุทธิ์ศักดิ์สิทธิ์ไปติดต่อกับประชาชนด้วยเสื้อผ้าของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 20, 'อย่าให้เขาโกนศีรษะหรือปล่อยให้มวยผมยาว ให้เขาเพียงแต่ขลิบผมบนศีรษะของเขาเท่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 21, 'เมื่อปุโรหิตเข้าไปในลานชั้นในจะดื่มเหล้าองุ่นไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 22, 'อย่าให้ปุโรหิตแต่งงานกับหญิงม่ายหรือหญิงที่ถูกหย่าแล้ว แต่ให้แต่งงานกับหญิงพรหมจารีจากเชื้อสายแห่งวงศ์วานอิสราเอล หรือหญิงม่ายซึ่งเป็นแม่ม่ายของปุโรหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 23, 'เขาทั้งหลายจะต้องสั่งสอนประชาชนของเราถึงความแตกต่างระหว่างของบริสุทธิ์และของสามัญ และกระทําให้เขาสังเกตแยกแยะระหว่างของมลทินกับของสะอาดได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 24, 'ถ้ามีคดี เขาจะต้องกระทําหน้าที่ผู้พิพากษา และเขาจะต้องพิพากษาตามคําตัดสินของเรา ในบรรดางานประชุมของเรานั้นเขาจะต้องรักษาราชบัญญัติและกฎเกณฑ์ของเรา และเขาจะต้องรักษาวันสะบาโตทั้งหลายของเราให้บริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 25, 'อย่าให้เขากระทําตัวให้เป็นมลทินด้วยเข้าไปใกล้ผู้ตาย เว้นแต่เป็นบิดาหรือมารดาหรือบุตรชายหรือบุตรสาว หรือพี่น้องผู้ชายหรือพี่น้องผู้หญิงที่ไม่มีสามี ก็จะกระทําตัวให้เป็นมลทินได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 26, 'หลังจากที่เขารับการชําระแล้ว มีกําหนดอีกเจ็ดวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 27, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสว่า ในวันที่เขาเข้าไปในสถานบริสุทธิ์ คือที่ลานชั้นในเพื่อจะปรนนิบัติอยู่ในสถานบริสุทธิ์ เขาจะต้องถวายเครื่องบูชาไถ่บาปเสียก่อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 28, 'นั่นจะเป็นมรดกของเขา เราเป็นมรดกของเขา และเจ้าจะไม่ต้องให้เขาถือกรรมสิทธิ์ใดๆในอิสราเอล เราเป็นกรรมสิทธิ์ของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 29, 'ให้เขารับประทานเครื่องธัญญบูชา เครื่องบูชาไถ่บาป และเครื่องบูชาไถ่การละเมิด และทุกสิ่งที่ถวายไว้ในอิสราเอลจะเป็นของเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 30, 'และผลไม้ดีที่สุดของผลไม้รุ่นแรกทุกชนิดและของถวายทุกชนิดจากเครื่องถวายบูชาทั้งสิ้นของเจ้าจะเป็นของบรรดาปุโรหิตทั้งหลาย เจ้าจงมอบแป้งเปียกผลแรกของเจ้าให้แก่ปุโรหิต เพื่อว่าพระพรจะมีอยู่เหนือครัวเรือนของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 31, 'ปุโรหิตจะต้องไม่รับประทานสิ่งใดๆ ไม่ว่าจะเป็นนกหรือสัตว์ที่ตายเองหรือถูกฉีกกัดตาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 1, '“เมื่อเจ้าแบ่งแผ่นดินเป็นกรรมสิทธิ์โดยการจับฉลากนั้น เจ้าจงถวายที่ดินส่วนหนึ่งไว้เพื่อพระเยโฮวาห์ให้เป็นตําบลบริสุทธิ์ ยาวสองหมื่นห้าพันศอก และกว้างหนึ่งหมื่นศอก จะเป็นที่บริสุทธิ์ตลอดบริเวณนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 2, 'ในบริเวณนี้ให้มีที่สี่เหลี่ยมจตุรัสแปลงหนึ่งยาวห้าร้อยกว้างห้าร้อยศอกสําหรับสถานบริสุทธิ์ ให้มีบริเวณว่างไว้โดยรอบอีกห้าสิบศอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 3, 'ในตําบลบริสุทธิ์นั้น เจ้าจงวัดส่วนหนึ่งออก ยาวสองหมื่นห้าพันศอก กว้างหนึ่งหมื่นศอก ในบริเวณนี้ให้เป็นที่ตั้งของสถานบริสุทธิ์ และของที่บริสุทธิ์ที่สุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 4, 'ให้เป็นส่วนแผ่นดินที่บริสุทธิ์ ให้เป็นของปุโรหิต ผู้ปรนนิบัติอยู่ในสถานบริสุทธิ์ และเข้าใกล้พระเยโฮวาห์เพื่อจะปรนนิบัติพระองค์ ให้เป็นที่สําหรับปลูกบ้านเรือนของเขาและเป็นที่บริสุทธิ์สําหรับสถานบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 5, 'อีกส่วนหนึ่งซึ่งยาวสองหมื่นห้าพันศอกและกว้างหนึ่งหมื่นศอกนั้นเป็นที่ของคนเลวี ผู้ปรนนิบัติอยู่ที่พระนิเวศ ให้เป็นกรรมสิทธิ์ของเขา ให้มีห้องยี่สิบห้อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 6, 'ใกล้ๆกับส่วนที่ตั้งไว้เป็นตําบลบริสุทธิ์นั้น เจ้าจะต้องกําหนดที่ดินผืนหนึ่งกว้างห้าพันศอก ยาวสองหมื่นห้าพันศอก ให้เป็นกรรมสิทธิ์ของเมือง ให้เป็นของวงศ์วานอิสราเอลทั้งหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 7, 'แผ่นดินทั้งสองข้างของตําบลบริสุทธิ์และส่วนของเมืองนั้น ให้ยกเป็นที่ดินของเจ้านายเคียงข้างกับตําบลบริสุทธิ์ และส่วนของเมืองด้านตะวันตกและตะวันออกมีส่วนยาวเท่ากับส่วนที่ยกให้คนตระกูลหนึ่ง ยืดออกไปตามทางตะวันตกและทางตะวันออกของเขตแดนแผ่นดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 8, 'ให้เป็นส่วนของเจ้านายในอิสราเอล และเจ้านายของเราจะไม่บีบคั้นประชาชนของเราอีก แต่เจ้านายเหล่านั้นจะยอมให้วงศ์วานอิสราเอลได้แผ่นดินที่เหลือตามส่วนตระกูลของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 9, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า โอ บรรดาเจ้านายแห่งอิสราเอลเอ๋ย พอเสียทีเถิด จงทิ้งการทารุณและการบีบคั้นเสีย และกระทําความยุติธรรมและความเที่ยงธรรม องค์พระผู้เป็นเจ้าพระเจ้าตรัสว่า จงเลิกการขับไล่ประชาชนของเราให้ออกจากที่ดินอันเป็นกรรมสิทธิ์ของเขาเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 10, 'เจ้าจงมีตาชั่งเที่ยงตรง เอฟาห์เที่ยงตรงและบัทที่เที่ยงตรง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 11, 'เอฟาห์และบัทนั้นให้เป็นขนาดเดียวกัน บัทหนึ่งจุหนึ่งในสิบของโฮเมอร์ และเอฟาห์ก็จุหนึ่งในสิบของโฮเมอร์ ให้โฮเมอร์เป็นเครื่องวัดมาตรฐาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 12, 'เชเขลหนึ่งมียี่สิบเก-ราห์ มาเนของเจ้าก็ให้มียี่สิบเชเขล ยี่สิบห้าเชเขลและสิบห้าเชเขล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 13, 'ต่อไปนี้เป็นกําหนดของถวายที่เจ้าทั้งหลายจะต้องถวาย คือข้าวสาลีโฮเมอร์หนึ่งให้ถวายหนึ่งในหกเอฟาห์ ข้าวบาร์เลย์โฮเมอร์หนึ่งให้ถวายหนึ่งในหกของเอฟาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 14, 'และส่วนกําหนดประจําของน้ํามัน คือน้ํามันหนึ่งบัท น้ํามันโคระหนึ่งถวายหนึ่งในสิบของบัท โคระก็เหมือนโฮเมอร์จุสิบบัท เพราะสิบบัทเท่ากับโฮเมอร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 15, 'แกะฝูงสองร้อยตัวก็ให้ถวายตัวหนึ่ง จากทุ่งเลี้ยงสัตว์อันอุดมของอิสราเอล องค์พระผู้เป็นเจ้าพระเจ้าตรัสว่า นี่แหละเป็นของถวายสําหรับธัญญบูชา เครื่องเผาบูชา และสันติบูชาเพื่อทําการลบมลทินให้เขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 16, 'ให้ประชาชนทั้งสิ้นแห่งแผ่นดินนี้มอบของถวายเหล่านี้แก่เจ้านายแห่งอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 17, 'ให้เป็นหน้าที่ของเจ้านายที่จะจัดเครื่องเผาบูชา ธัญญบูชา เครื่องดื่มบูชา ณ งานเทศกาลทั้งหลายในวันขึ้นหนึ่งค่ําและวันสะบาโต ในงานเทศกาลที่กําหนดไว้ของวงศ์วานอิสราเอลทั้งสิ้น ให้เขาจัดเครื่องบูชาไถ่บาป ธัญญบูชา เครื่องเผาบูชา และสันติบูชา เพื่อกระทําการลบบาปให้แก่วงศ์วานอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 18, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า ในวันที่หนึ่งของเดือนที่หนึ่ง เจ้าจงเอาวัวหนุ่มที่ปราศจากตําหนิตัวหนึ่ง และเจ้าจงชําระสถานบริสุทธิ์เสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 19, 'ให้ปุโรหิตเอาเลือดของเครื่องบูชาไถ่บาปมาบ้างและจงประพรมที่เสาประตูพระนิเวศ ที่ขั้นสี่มุมของแท่นบูชา และบนเสาประตูของลานชั้นใน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 20, 'ในวันที่เจ็ดของเดือนนั้นเจ้าจงกระทําเช่นเดียวกัน เพื่อผู้หนึ่งผู้ใดที่กระทําบาปด้วยความพลั้งเผลอหรือความรู้เท่าไม่ถึงการ เพื่อว่าเจ้าจะได้กระทําการลบมลทินพระนิเวศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 21, 'ในวันที่สิบสี่ของเดือนต้น เจ้าจงฉลองเทศกาลปัสกา จงรับประทานขนมปังไร้เชื้อตลอดเทศกาลเจ็ดวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 22, 'ในวันนั้นให้เจ้านายจัดหาวัวหนุ่มตัวหนึ่งสําหรับตนเองและประชาชนทั้งสิ้นแห่งแผ่นดิน เพื่อเป็นเครื่องบูชาไถ่บาป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 23, 'และในเจ็ดวันที่มีเทศกาลเลี้ยงให้เจ้านายจัดหาวัวหนุ่มเจ็ดตัวกับแกะผู้เจ็ดตัวที่ปราศจากตําหนิ ให้เป็นเครื่องเผาบูชาแด่พระเยโฮวาห์ทุกๆวันตลอดเจ็ดวันนั้น และจัดหาลูกแพะผู้ตัวหนึ่งทุกวันให้เป็นเครื่องบูชาไถ่บาป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 24, 'และให้เจ้านายจัดหาธัญญบูชาเอฟาห์หนึ่งคู่กับวัวผู้หนึ่ง และเอฟาห์หนึ่งคู่กับแกะผู้หนึ่ง และน้ํามันหนึ่งฮินต่อแป้งทุกเอฟาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 25, 'ในวันที่สิบห้าของเดือนที่เจ็ด และในเทศกาลเลี้ยงทั้งเจ็ดวัน ให้ท่านจัดหาของเช่นเดียวกันสําหรับเป็นเครื่องบูชาไถ่บาป เครื่องเผาบูชา ธัญญบูชา และเครื่องน้ํามัน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 1, '“องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า ประตูลานชั้นในที่หันหน้าไปทางทิศตะวันออกนั้นให้ปิดอยู่ในวันทํางานหกวัน แต่ในวันสะบาโตนั้นให้เปิด และในวันขึ้นหนึ่งค่ําก็ให้เปิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 2, 'ฝ่ายเจ้านายนั้นจะเข้ามาจากข้างนอกทางมุขของหอประตู และจะมายืนอยู่ที่เสาประตู และพวกปุโรหิตจะเตรียมเครื่องเผาบูชา และเครื่องสันติบูชาของท่าน และท่านจะนมัสการอยู่ที่ธรณีประตู แล้วท่านจะออกไป แต่อย่าปิดประตูนั้นจนกว่าจะถึงเวลาเย็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 3, 'เช่นเดียวกันประชาชนแห่งแผ่นดินจะนมัสการต่อพระพักตร์พระเยโฮวาห์ตรงที่ทางเข้าประตูนั้น ในวันสะบาโตและในวันขึ้นหนึ่งค่ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 4, 'เครื่องเผาบูชาที่เจ้านายจะถวายแด่พระเยโฮวาห์ในวันสะบาโตนั้น คือลูกแกะปราศจากตําหนิหกตัว และแกะผู้ปราศจากตําหนิตัวหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 5, 'และธัญญบูชาที่คู่กับแกะผู้นั้นคือแป้งเอฟาห์หนึ่ง และธัญญบูชาที่คู่กับลูกแกะนั้นก็สุดแท้แต่ที่ท่านสามารถจะถวายได้ พร้อมกับน้ํามันฮินหนึ่งต่อแป้งหนึ่งเอฟาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 6, 'ในวันขึ้นหนึ่งค่ําท่านจะถวายวัวหนุ่มปราศจากตําหนิตัวหนึ่ง และลูกแกะหกตัวกับแกะผู้ตัวหนึ่ง ซึ่งต้องปราศจากตําหนิ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 7, 'ส่วนธัญญบูชานั้นท่านจะจัดแป้งหนึ่งเอฟาห์คู่กับวัวผู้ตัวนั้น และหนึ่งเอฟาห์คู่กับแกะผู้ตัวหนึ่ง และคู่กับลูกแกะ ท่านจะจัดตามที่สามารถจัดได้ พร้อมกับน้ํามันหนึ่งฮินต่อแป้งหนึ่งเอฟาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 8, 'เมื่อเจ้านายเข้ามาท่านจะเข้าไปทางมุขของหอประตูและกลับออกไปตามทางเดียวกันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 9, 'เมื่อประชาชนแห่งแผ่นดินเข้ามาต่อพระพักตร์พระเยโฮวาห์ ณ เทศกาลเลี้ยงตามกําหนด ผู้ที่เข้ามาทางประตูเหนือเพื่อนมัสการจะต้องกลับออกไปทางประตูใต้ และผู้ที่เข้ามาทางประตูใต้จะต้องกลับออกไปทางประตูเหนือ อย่าให้ใครกลับทางประตูตามที่เขาเข้ามา แต่ให้ทุกคนออกตรงไปข้างหน้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 10, 'เมื่อประชาชนเข้าไป เจ้านายจะเข้าไปพร้อมกันด้วย และเมื่อประชาชนออกไป เจ้านายจะออกไปด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 11, 'ธัญญบูชาที่ใช้ ณ เทศกาลเลี้ยงและเทศกาลที่กําหนดนั้น ให้เป็นเอฟาห์หนึ่งคู่กับวัวหนุ่มตัวหนึ่ง และคู่กับแกะผู้ก็เอฟาห์หนึ่ง และคู่กับลูกแกะก็ตามแต่ท่านสามารถจะถวายได้ พร้อมกับน้ํามันฮินหนึ่งต่อแป้งเอฟาห์หนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 12, 'เมื่อเจ้านายถวายเครื่องบูชาตามใจสมัคร จะเป็นเครื่องเผาบูชา หรือสันติบูชาเป็นเครื่องบูชาตามใจสมัครถวายแด่พระเยโฮวาห์ ให้เปิดประตูที่หันหน้าไปทางทิศตะวันออกให้ท่านและท่านจะเตรียมเครื่องเผาบูชาและสันติบูชาของท่าน อย่างที่ท่านทําในวันสะบาโต แล้วท่านจะออกไป เมื่อท่านออกไปแล้วก็ให้ปิดประตูเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 13, 'เจ้าจะจัดการหาลูกแกะตัวหนึ่งอายุหนึ่งขวบปราศจากตําหนิถวายเป็นเครื่องเผาบูชาแด่พระเยโฮวาห์เป็นประจําวัน เจ้าจะจัดหาทุกๆเช้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 14, 'และเจ้าจะจัดหาเครื่องธัญญบูชาคู่กันทุกๆเช้าหนึ่งในหกของเอฟาห์ และน้ํามันหนึ่งในสามของฮิน เพื่อคลุกแป้งให้ชุ่มให้เป็นธัญญบูชาแด่พระเยโฮวาห์ นี่เป็นระเบียบเนืองนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 15, 'ดังนี้แหละจะต้องจัดหาลูกแกะและเครื่องธัญญบูชาพร้อมกับน้ํามันทุกๆเช้า เพื่อเป็นเครื่องเผาบูชาเนืองนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 16, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า ถ้าเจ้านายนําเอาส่วนหนึ่งของมรดกของท่านมามอบให้แก่บุตรชายเป็นของขวัญ ก็ให้ของนั้นตกเป็นของบุตรชายของท่านโดยมรดกนั้นเป็นทรัพย์สินของเขาตามมรดก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 17, 'แต่ถ้าท่านนําเอาส่วนหนึ่งของมรดกของท่านมามอบให้คนใช้ของท่านคนหนึ่งเป็นของขวัญ ของนั้นจะเป็นของคนใช้นั้นจนถึงปีอิสรภาพ แล้วของนั้นจะกลับมาเป็นของเจ้านาย เฉพาะบุตรชายของท่านเท่านั้นที่จะเก็บส่วนมรดกของท่านมาเป็นของขวัญได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 18, 'ยิ่งกว่านั้นอีกเจ้านายจะยึดสิ่งใดอันเป็นมรดกของประชาชนไม่ได้โดยไล่ประชาชนออกไปจากทรัพย์สินที่ดินของเขา แต่ท่านจะต้องมอบทรัพย์สินของท่านเองให้เป็นมรดกแก่บุตรชายของท่าน เพื่อว่าจะไม่มีประชาชนของเราสักคนหนึ่งที่ต้องถูกขับไล่จากกรรมสิทธิ์ของตน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 19, 'แล้วท่านก็นําข้าพเจ้ามาตามทางเข้าซึ่งอยู่ข้างประตู มายังห้องบริสุทธิ์แถวเหนือ ซึ่งเป็นของปุโรหิต ดูเถิด มีสถานที่แห่งหนึ่งอยู่ทั้งสองข้างทางทิศตะวันตก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 20, 'และท่านกล่าวแก่ข้าพเจ้าว่า “นี่เป็นสถานที่ซึ่งปุโรหิตจะต้องต้มเครื่องบูชาไถ่การละเมิดและเครื่องบูชาไถ่บาป และเป็นที่ซึ่งเขาจะปิ้งธัญญบูชา เพื่อจะไม่ต้องนําออกไปในลานชั้นนอก อันเป็นการที่จะนําความบริสุทธิ์ศักดิ์สิทธิ์ไปถึงประชาชน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 21, 'แล้วท่านจึงนําข้าพเจ้าออกมาที่ลานชั้นนอก และพาข้าพเจ้าไปที่มุมทั้งสี่ของลานนั้น และดูเถิด ที่มุมลานทุกมุมก็มีลานอยู่ลานหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 22, 'คือที่มุมทั้งสี่ของลาน มีลานเล็กๆยาวสี่สิบศอก กว้างสามสิบศอก ลานทั้งสี่ขนาดเดียวกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 23, 'ภายในรอบลานทั้งสี่นั้นมีสิ่งที่ก่อด้วยปูนเป็นแถว มีเตาอยู่ที่ก้นของสิ่งที่ก่อนั้นโดยรอบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 24, 'แล้วท่านจึงกล่าวแก่ข้าพเจ้าว่า “ที่เหล่านี้เป็นที่สําหรับการต้ม ซึ่งผู้ปรนนิบัติอยู่ที่พระนิเวศจะต้มเครื่องสัตวบูชาของประชาชน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 1, 'ภายหลังท่านก็นําข้าพเจ้ากลับมาที่ประตูพระนิเวศ และดูเถิด มีน้ําไหลออกมาจากใต้ธรณีประตูพระนิเวศตรงไปทางทิศตะวันออก เพราะพระนิเวศหันหน้าไปทางทิศตะวันออก และน้ําไหลลงมาจากข้างล่าง ทางด้านขวาของพระนิเวศ ทิศใต้ของแท่นบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 2, 'แล้วท่านจึงนําข้าพเจ้าออกมาทางประตูเหนือ และนําข้าพเจ้าอ้อมไปภายนอกถึงประตูชั้นนอก ซึ่งหันหน้าไปทางตะวันออก และดูเถิด น้ํานั้นออกมาทางด้านขวา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 3, 'ชายผู้นั้นได้เดินไปทางตะวันออกมีเชือกวัดอยู่ในมือ ท่านวัดได้หนึ่งพันศอก แล้วนําข้าพเจ้าลุยน้ําไป และน้ําลึกเพียงตาตุ่ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 4, 'แล้วท่านก็วัดได้อีกหนึ่งพัน แล้วนําข้าพเจ้าลุยน้ําไปและน้ําลึกถึงเข่า แล้วท่านก็วัดได้อีกหนึ่งพัน แล้วนําข้าพเจ้าลุยน้ําไป น้ํานั้นลึกเพียงเอว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 5, 'ภายหลังท่านก็วัดได้อีกหนึ่งพัน และกลายเป็นแม่น้ําที่ข้าพเจ้าลุยข้ามไม่ได้ เพราะน้ํานั้นขึ้นแล้วลึกพอที่จะว่ายได้ เป็นแม่น้ําที่ลุยข้ามไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 6, 'และท่านพูดกับข้าพเจ้าว่า “บุตรแห่งมนุษย์เอ๋ย เจ้าเห็นสิ่งนี้หรือ” แล้วท่านก็พาข้าพเจ้ากลับมาตามฝั่งแม่น้ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 7, 'ขณะเมื่อข้าพเจ้ากลับ ดูเถิด ข้าพเจ้าเห็นต้นไม้มากมายอยู่ที่ฝั่งแม่น้ําทั้งสองฟาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 8, 'และท่านพูดกับข้าพเจ้าว่า “น้ํานี้ไหลตรงไปทางท้องถิ่นตะวันออก และไหลลงไปถึงทะเลทราย แล้วลงไปถึงทะเล และเมื่อน้ําไหลออกมานั้นไปถึงน้ําทะเล น้ํานั้นก็กลับจืดดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 9, 'ต่อมาแม่น้ํานั้นไปถึงที่ไหน ทุกสิ่งที่มีชีวิตซึ่งแหวกว่ายไปมาก็จะมีชีวิตได้ และที่นั่นมีปลามากมายเพราะว่าน้ํานี้ไปถึงที่นั่นน้ําทะเลก็จืด เพราะฉะนั้นแม่น้ําไปถึงไหน ทุกสิ่งก็มีชีวิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 10, 'ต่อมาชาวประมงก็จะยืนอยู่ที่ข้างทะเล จากเอนเกดีถึงเอนเอกลาอิม จะเป็นที่สําหรับตากอวน ปลาในที่นั่นจะมีหลายชนิด เหมือนปลาในทะเลใหญ่ คือจะมีมากมาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 11, 'แต่ที่เป็นบึงและหนองน้ําจะไม่จืด ต้องทิ้งไว้ให้เป็นเกลือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 12, 'ตามฝั่งทั้งสองฟากแม่น้ํา จะมีต้นไม้ทุกชนิดที่ใช้เป็นอาหาร ใบของมันจะไม่เหี่ยวและผลของมันจะไม่วาย แต่จะเกิดผลใหม่ทุกเดือน เพราะว่าน้ําสําหรับต้นไม้นั้นไหลจากสถานบริสุทธิ์ ผลไม้นั้นใช้เป็นอาหารและใบก็ใช้เป็นยา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 13, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า “นี่เป็นเขตแดนซึ่งเจ้าจะใช้แบ่งแผ่นดินสําหรับเป็นมรดกท่ามกลางอิสราเอลทั้งสิบสองตระกูล โยเซฟจะได้สองส่วน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 14, 'และเจ้าจงแบ่งให้เท่าๆกัน เราปฏิญาณที่จะมอบให้แก่บรรพบุรุษของเจ้า และแผ่นดินนี้จะตกแก่เจ้าเป็นมรดกของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 15, 'ต่อไปนี้เป็นเขตแดนของแผ่นดินนี้ ด้านทิศเหนือจากทะเลใหญ่ไปตามทางเมืองเฮทโลน และต่อไปถึงเมืองเศดัด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 16, 'เมืองฮามัท เมืองเบโรธาห์ เมืองสิบราอิม ซึ่งอยู่ระหว่างพรมแดนเมืองดามัสกัสกับพรมแดนเมืองฮามัท จนถึงเมืองฮาซารฮัททิโคน ซึ่งอยู่ที่พรมแดนเมืองเฮาราน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 17, 'ดังนั้น เขตแดนจะยื่นจากทะเลถึงเมืองฮาซาเรนัน ซึ่งอยู่ที่พรมแดนด้านเหนือของเมืองดามัสกัส ทางทิศเหนือมีพรมแดนของเมืองฮามัท นี่เป็นแดนด้านเหนือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 18, 'ทางด้านตะวันออก เขตแดนจะยื่นจากเมืองเฮารานและดามัสกัส ระหว่างกิเลอาดกับแผ่นดินอิสราเอล เรื่อยไปตามแม่น้ําจอร์แดน ไปถึงทะเลด้านตะวันออก ท่านทั้งหลายจงวัด นี่เป็นเขตด้านตะวันออก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 19, 'ทางด้านใต้เขตแดนจะยื่นจากทามาร์จนถึงน้ําแห่งการโต้เถียงในคาเดช แล้วเรื่อยไปตามแม่น้ําถึงทะเลใหญ่ นี่เป็นเขตด้านใต้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 20, 'ทางด้านตะวันตก ทะเลใหญ่เป็นเขตแดนเรื่อยไปจนถึงตําบลที่อยู่ตรงข้ามทางเข้าเมืองฮามัท นี่เป็นเขตแดนด้านตะวันตก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 21, 'ดังนั้น เจ้าจงแบ่งแผ่นดินนี้ท่ามกลางเจ้าตามตระกูลอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 22, 'ต่อมาเจ้าทั้งหลายจงแบ่งแผ่นดินเป็นมรดกของตัวเจ้าทั้งหลายโดยการจับฉลาก และสําหรับคนต่างด้าวผู้อาศัยอยู่ท่ามกลางเจ้า และบังเกิดลูกหลานอยู่ท่ามกลางเจ้า เขาทั้งหลายจะมีสัญชาติอิสราเอล ให้เขาได้รับส่วนมรดกท่ามกลางตระกูลอิสราเอลพร้อมกับเจ้าทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 23, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสว่า ต่อมาคนต่างด้าวจะอยู่ในเขตของคนตระกูลใดก็ได้ เจ้าจงกําหนดที่ดินให้เป็นมรดกของเขาที่นั่น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 1, '“ต่อไปนี้เป็นชื่อของตระกูลต่างๆ ตั้งต้นที่พรมแดนด้านเหนือจากทะเลไปตามทางเฮทโลน ถึงทางเข้าเมืองฮามัทจนถึงฮาซาเรนัน ซึ่งอยู่ทางพรมแดนด้านเหนือของดามัสกัส ติดเมืองฮามัท และยื่นจากด้านตะวันออกไปถึงด้านตะวันตก เป็นส่วนของคนดาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 2, 'ประชิดกับเขตแดนของดานจากด้านตะวันออกไปถึงด้านตะวันตก เป็นส่วนของคนอาเชอร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 3, 'ประชิดกับเขตแดนของอาเชอร์จากด้านตะวันออกไปถึงด้านตะวันตก เป็นส่วนของคนนัฟทาลี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 4, 'ประชิดกับเขตแดนของนัฟทาลีจากด้านตะวันออกไปถึงด้านตะวันตก เป็นส่วนของคนมนัสเสห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 5, 'ประชิดกับเขตแดนของมนัสเสห์จากด้านตะวันออกไปถึงด้านตะวันตก เป็นส่วนของคนเอฟราอิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 6, 'ประชิดกับเขตแดนเอฟราอิมจากด้านตะวันออกไปถึงด้านตะวันตก เป็นส่วนของคนรูเบน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 7, 'ประชิดกับเขตแดนรูเบนจากด้านตะวันออกไปถึงด้านตะวันตก เป็นส่วนของคนยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 8, 'ประชิดกับเขตแดนยูดาห์จากด้านตะวันออกไปถึงด้านตะวันตก จะเป็นส่วนซึ่งเจ้าจะต้องแยกไว้ต่างหาก กว้างสองหมื่นห้าพันศอก และยาวเท่ากับส่วนของคนตระกูลหนึ่ง จากด้านตะวันออกไปถึงด้านตะวันตก เป็นที่มีสถานบริสุทธิ์อยู่กลาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 9, 'ส่วนซึ่งเจ้าทั้งหลายจะแยกไว้เพื่อพระเยโฮวาห์นั้นให้มีด้านยาวสองหมื่นห้าพันศอก และด้านกว้างหนึ่งหมื่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 10, 'นี่จะเป็นส่วนแบ่งของส่วนบริสุทธิ์ คือปุโรหิตจะได้ส่วนแบ่งวัดจากทางด้านเหนือยาวสองหมื่นห้าพันศอก ทางด้านตะวันตกกว้างหนึ่งหมื่นศอก ทางด้านตะวันออกกว้างหนึ่งหมื่นศอก ทางด้านใต้ยาวสองหมื่นห้าพันศอก มีสถานบริสุทธิ์ของพระเยโฮวาห์อยู่กลาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 11, 'ส่วนนี้ให้เป็นส่วนของปุโรหิตที่ชําระไว้ให้บริสุทธิ์ บุตรชายของศาโดก ผู้ได้รักษาคําสั่งของเรา ผู้ที่มิได้หลงไปเมื่อประชาชนอิสราเอลหลง ดังที่คนเลวีได้หลงไปนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 12, 'และให้ที่ดินนี้ตกแก่เขาทั้งหลายเป็นส่วนหนึ่งจากส่วนถวายของแผ่นดิน เป็นสถานที่บริสุทธิ์ที่สุด ประชิดกับเขตแดนของคนเลวี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 13, 'เคียงข้างกับเขตแดนของปุโรหิตนั้นให้คนเลวีมีส่วนแบ่งยาวสองหมื่นห้าพันศอก กว้างหนึ่งหมื่นศอก ส่วนยาวทั้งสิ้นจะเป็นสองหมื่นห้าพันศอกและส่วนกว้างหนึ่งหมื่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 14, 'อย่าให้เขาขายหรือแลกเปลี่ยนส่วนหนึ่งส่วนใดเลย อย่าให้เขาเปลี่ยนกรรมสิทธิ์ของที่ดินดีนี้ เพราะเป็นส่วนบริสุทธิ์แด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 15, 'ส่วนที่เหลืออยู่ซึ่งกว้างห้าพันศอกและยาวสองหมื่นห้าพันศอกนั้น ให้เป็นที่สามัญของเมืองคือใช้เป็นที่อยู่อาศัย และเป็นชานเมือง ให้ตัวนครอยู่ท่ามกลางนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 16, 'ต่อไปนี้เป็นขนาดของด้านต่างๆ ด้านเหนือสี่พันห้าร้อยศอก ด้านใต้สี่พันห้าร้อยศอก ด้านตะวันออกสี่พันห้าร้อย และด้านตะวันตกสี่พันห้าร้อย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 17, 'นครนั้นจะต้องมีทุ่งหญ้า ทิศเหนือสองร้อยห้าสิบศอก ทิศใต้สองร้อยห้าสิบ และทิศตะวันออกสองร้อยห้าสิบ และทิศตะวันตกสองร้อยห้าสิบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 18, 'ด้านยาวส่วนที่เหลืออยู่เคียงข้างกับส่วนบริสุทธิ์นั้น ทิศตะวันออกยาวหนึ่งหมื่นศอก และทิศตะวันตกยาวหนึ่งหมื่น และให้อยู่เคียงข้างกับส่วนบริสุทธิ์ พืชผลที่ได้ในส่วนนี้ให้เป็นอาหารของคนงานในนครนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 19, 'คนงานของนครนั้นซึ่งมาจากอิสราเอลทุกตระกูลให้เขาเป็นคนไถที่แปลงนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 20, 'ส่วนเต็มซึ่งเจ้าจะต้องแบ่งแยกไว้นั้นให้เป็นสี่เหลี่ยมจตุรัสด้านละสองหมื่นห้าพันศอก นั่นคือส่วนบริสุทธิ์รวมกับส่วนของตัวนคร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 21, 'ส่วนที่เหลืออยู่ทั้งสองข้างของส่วนบริสุทธิ์และส่วนของตัวนคร ให้ตกเป็นของเจ้านาย ยื่นจากส่วนบริสุทธิ์ซึ่งยาวสองหมื่นห้าพันศอกไปยังพรมแดนตะวันออก และทางด้านตะวันตกจากสองหมื่นห้าพันศอกไปยังพรมแดนตะวันตก ส่วนนี้ให้ตกเป็นของเจ้านาย จะเป็นส่วนบริสุทธิ์ และสถานบริสุทธิ์ของพระนิเวศนั้นอยู่ท่ามกลาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 22, 'นอกจากส่วนที่ตกเป็นของคนเลวีและส่วนของนครนั้น ซึ่งอยู่กลางส่วนอันตกเป็นของเจ้านาย ระหว่างเขตแดนยูดาห์และเขตแดนเบนยามิน ให้เป็นส่วนของเจ้านายทั้งหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 23, 'ตระกูลคนที่เหลืออยู่นั้น จากด้านตะวันออกไปถึงด้านตะวันตก เป็นส่วนของคนเบนยามิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 24, 'ประชิดกับเขตแดนของเบนยามินจากด้านตะวันออกไปถึงด้านตะวันตก เป็นส่วนของคนสิเมโอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 25, 'ประชิดกับเขตแดนของสิเมโอนจากด้านตะวันออกไปถึงด้านตะวันตก เป็นส่วนของคนอิสสาคาร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 26, 'ประชิดกับเขตแดนของอิสสาคาร์จากด้านตะวันออกไปถึงด้านตะวันตก เป็นส่วนของคนเศบูลุน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 27, 'ประชิดกับเขตแดนของเศบูลุนจากด้านตะวันออกไปถึงด้านตะวันตก เป็นส่วนของคนกาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 28, 'ประชิดกับเขตแดนของกาดทางทิศใต้เขตแดนนั้นจะยื่นจากเมืองทามาร์ ถึงน้ําแห่งการโต้เถียงในคาเดช แล้วเรื่อยไปตามแม่น้ําถึงทะเลใหญ่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 29, 'นี่เป็นแผ่นดินซึ่งเจ้าจะแบ่งให้เป็นมรดกแก่ตระกูลต่างๆของอิสราเอลโดยการจับฉลาก นี่เป็นส่วนต่างๆของเขาทั้งหลาย องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 30, 'ต่อไปนี้เป็นทางออกของนครทางด้านเหนือซึ่งวัดได้สี่พันห้าร้อยศอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 31, 'ประตูนครนั้นตั้งชื่อตามชื่อตระกูลคนอิสราเอล มีประตูสามประตูทางด้านเหนือ ประตูของรูเบน ประตูของยูดาห์ ประตูของเลวี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 32, 'ทางด้านตะวันออกซึ่งยาวสี่พันห้าร้อยศอก มีสามประตู ประตูของโยเซฟ ประตูของเบนยามิน ประตูของดาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 33, 'ทางด้านใต้ซึ่งวัดได้สี่พันห้าร้อยศอก มีประตูสามประตู ประตูของสิเมโอน ประตูของอิสสาคาร์ ประตูของเศบูลุน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 34, 'ทางด้านตะวันตกซึ่งยาวสี่พันห้าร้อยศอก มีประตูสามประตู ประตูของกาด ประตูของอาเชอร์ ประตูของนัฟทาลี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 35, 'วัดรอบนครนั้นได้หนึ่งหมื่นแปดพันศอก ตั้งแต่นี้ไปนครนี้จะมีชื่อว่า พระเยโฮวาห์สถิตที่นั่น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 1, 'ในปีที่สามของรัชกาลเยโฮยาคิมกษัตริย์ของยูดาห์ เนบูคัดเนสซาร์กษัตริย์ของบาบิโลนเสด็จมายังกรุงเยรูซาเล็ม และทรงล้อมเมืองไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 2, 'และองค์พระผู้เป็นเจ้าทรงมอบเยโฮยาคิมกษัตริย์ของยูดาห์ไว้ในหัตถ์ของพระองค์ท่าน พร้อมทั้งเครื่องใช้บางชิ้นแห่งพระนิเวศของพระเจ้า และพระองค์ท่านก็นําของเหล่านั้นมายังแผ่นดินชินาร์มายังนิเวศแห่งพระของพระองค์ท่าน และทรงบรรจุเครื่องใช้เหล่านั้นไว้ในคลังของพระของพระองค์ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 3, 'แล้วกษัตริย์นั้นก็ทรงบัญชาให้อัชเปนัสหัวหน้าขันทีของพระองค์ท่าน ให้นําคนอิสราเอลบางคน ทั้งเชื้อพระวงศ์และเชื้อสายของเจ้านาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 4, 'พวกหนุ่มๆที่ปราศจากตําหนิ มีรูปร่างงามและเชี่ยวชาญในสรรพปัญญา กอปรด้วยความรู้และเข้าใจในสรรพวิทยา กับสามารถที่จะรับราชการในพระราชวังและทรงให้สอนวิชาและภาษาของคนเคลเดียให้เขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 5, 'กษัตริย์ทรงให้นําอาหารสูงซึ่งกษัตริย์เสวย และเหล้าองุ่นซึ่งพระองค์ท่านดื่มให้แก่เขาเหล่านั้นตามกําหนดทุกวัน ทรงให้เขาทั้งหลายรับการเลี้ยงดูอยู่สามปี เมื่อครบกําหนดเวลานั้นแล้วทรงให้เขารับใช้ต่อพระพักตร์กษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 6, 'ในบรรดาคนยูดาห์นั้นมีดาเนียล ฮานันยาห์ มิชาเอล และอาซาริยาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 7, 'และท่านหัวหน้าขันทีจึงตั้งชื่อให้ใหม่ ดาเนียลนั้นให้เรียกว่าเบลเทชัสซาร์ ฮานันยาห์เรียกว่าชัดรัค มิชาเอลเรียกว่าเมชาค และอาซาริยาห์เรียกว่าเอเบดเนโก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 8, 'แต่ดาเนียลตั้งใจไว้ว่าจะไม่กระทําตัวให้เป็นมลทินด้วยอาหารสูงของกษัตริย์ หรือด้วยเหล้าองุ่นซึ่งพระองค์ดื่ม เพราะฉะนั้นเขาจึงขอหัวหน้าขันทีให้ยอมเขาที่ไม่กระทําตัวให้เป็นมลทิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 9, 'และพระเจ้าทรงให้หัวหน้าขันทีชอบและเวทนาดาเนียล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 10, 'และหัวหน้าขันทีจึงกล่าวแก่ดาเนียลว่า “ข้าเกรงว่ากษัตริย์เจ้านายของข้าผู้ทรงกําหนดอาหารและเครื่องดื่มของเจ้า ทอดพระเนตรเห็นว่า พวกเจ้ามีหน้าซูบซีดกว่าบรรดาคนหนุ่มๆอายุรุ่นราวคราวเดียวกัน เจ้าก็จะกระทําให้ศีรษะของข้าเข้าสู่อันตรายเพราะกษัตริย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 11, 'แล้วดาเนียลจึงกล่าวแก่มหาดเล็กผู้ที่หัวหน้าขันทีกําหนดให้ดูแลดาเนียล ฮานันยาห์ มิชาเอล และอาซาริยาห์ ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 12, '“ขอท่านจงทดลองผู้รับใช้ของท่านสักสิบวัน ขอให้เขานําผักมาให้เรากินและน้ํามาให้เราดื่ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 13, 'แล้วให้ท่านตรวจดูหน้าตาของเราทั้งหลายเบื้องหน้าท่านและตรวจดูหน้าตาของบรรดาอนุชนผู้รับประทานอาหารสูงของกษัตริย์ และเมื่อท่านเห็นอย่างไรแล้วจงกระทําแก่ผู้รับใช้ของท่านอย่างนั้นเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 14, 'เขาก็ยอมทําตามคนเหล่านั้นในเรื่องนี้และทดลองเขาอยู่สิบวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 15, 'เมื่อครบสิบวันแล้วหน้าตาของคนเหล่านั้นดีกว่า และเนื้อหนังก็อ้วนท้วนสมบูรณ์กว่าบรรดาอนุชนที่รับประทานอาหารสูงของกษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 16, 'ดังนั้นมหาดเล็กจึงนําอาหารสูงส่วนของเขาทั้งหลายและเหล้าองุ่นซึ่งเขาทั้งหลายควรจะได้ดื่มนั้นไปเสีย และให้ผักแก่เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 17, 'ฝ่ายอนุชนทั้งสี่คนนี้ พระเจ้าทรงประทานสรรพวิทยา และความชํานาญในเรื่องวิชาทั้งปวงและปัญญา และดาเนียลเข้าใจในนิมิตและความฝันทุกประการ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 18, 'พอสิ้นกําหนดเวลาที่กษัตริย์ทรงบัญชาให้นําเขาทั้งหลายเข้าเฝ้า หัวหน้าขันทีจึงนําเขาทั้งหลายเข้ามาเฝ้าเนบูคัดเนสซาร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 19, 'และกษัตริย์ก็ทรงสัมภาษณ์เขา ในบรรดาอนุชนเหล่านั้นไม่พบสักคนหนึ่งที่เหมือนดาเนียล ฮานันยาห์ มิชาเอลและอาซาริยาห์ เพราะฉะนั้นเขาจึงได้รับใช้ต่อพระพักตร์กษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 20, 'ในบรรดาเรื่องราวอันเกี่ยวกับปัญญาและความเข้าใจ ซึ่งกษัตริย์ตรัสถามเขาทั้งหลาย ทรงเห็นว่าเขาทั้งหลายดีกว่าพวกโหร และพวกหมอดู ซึ่งอยู่ในอาณาจักรทั้งสิ้นของพระองค์สิบเท่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 21, 'และดาเนียลก็ได้รับราชการเรื่อยมาจนปีแรกแห่งรัชกาลกษัตริย์ไซรัส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 1, 'ในปีที่สองแห่งรัชกาลเนบูคัดเนสซาร์ เนบูคัดเนสซาร์ทรงพระสุบิน พระทัยของพระองค์ก็ทรงเป็นทุกข์ บรรทมไม่หลับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 2, 'แล้วกษัตริย์จึงทรงบัญชาให้มีหมายเรียกพวกโหร พวกหมอดู พวกนักวิทยาคม และคนเคลเดียเข้าทูลกษัตริย์ให้รู้เรื่องพระสุบิน เขาทั้งหลายก็เข้ามาเฝ้ากษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 3, 'และกษัตริย์ตรัสกับเขาว่า “เราได้ฝัน และจิตใจของเราก็เป็นทุกข์ อยากรู้ว่าฝันว่ากระไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 4, 'แล้วคนเคลเดียจึงกราบทูลกษัตริย์เป็นภาษาอารัมว่า “โอ ข้าแต่กษัตริย์ ขอทรงพระเจริญเป็นนิตย์ ขอทรงเล่าพระสุบินให้แก่พวกผู้รับใช้ของพระองค์ แล้วเหล่าข้าพระองค์จะได้ถวายคําแก้พระสุบิน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 5, 'กษัตริย์ทรงตอบคนเคลเดียว่า “เราจําความฝันนั้นไม่ได้แล้ว ถ้าเจ้าไม่ให้เรารู้ความฝันพร้อมทั้งคําแก้ฝัน เจ้าจะถูกหั่นเป็นชิ้นๆ และบ้านเรือนของเจ้าจะต้องเป็นกองขยะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 6, 'แต่ถ้าเจ้าสําแดงความฝันและคําแก้ฝันให้เรา เจ้าจะได้รับของขวัญ รางวัล และเกียรติยศใหญ่ยิ่ง ฉะนั้นจงสําแดงความฝันและคําแก้ฝันให้เรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 7, 'เขาทั้งหลายกราบทูลคํารบสองว่า “ขอกษัตริย์เล่าพระสุบินแก่พวกผู้รับใช้ของพระองค์ และเหล่าข้าพระองค์จะถวายคําแก้พระสุบิน พระเจ้าข้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 8, 'กษัตริย์ทรงตอบว่า “เรารู้เป็นแน่แล้วว่า เจ้าพยายามจะถ่วงเวลาไว้ เพราะเจ้าเห็นว่าเราจําความฝันนั้นไม่ได้แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 9, 'แต่ถ้าเจ้าไม่ให้เรารู้ความฝัน ก็มีคําตัดสินเจ้าอยู่ข้อเดียว เพราะเจ้าทั้งหลายตกลงที่จะพูดเท็จและพูดทุจริตต่อหน้าเรา จนจะมีอะไรเปลี่ยนแปลงไป เพราะฉะนั้นเจ้าจงบอกความฝันให้แก่เรา แล้วเราจึงจะรู้ว่าเจ้าจะถวายคําแก้ความฝันให้เราได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 10, 'คนเคลเดียจึงกราบทูลต่อพระพักตร์กษัตริย์ว่า “ไม่มีบุรุษคนใดในพิภพที่จะสําแดงเรื่องกษัตริย์ได้ เพราะฉะนั้นไม่มีกษัตริย์ เจ้านายหรือผู้ปกครองคนใดไต่ถามสิ่งเหล่านี้จากโหร หรือหมอดู หรือคนเคลเดีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 11, 'สิ่งซึ่งกษัตริย์ตรัสถามนั้นยากและไม่มีผู้ใดจะสําแดงแด่กษัตริย์ได้นอกจากพระ ผู้ซึ่งมิได้อยู่กับมนุษย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 12, 'เพราะเรื่องนี้กษัตริย์จึงทรงกริ้วและเกรี้ยวกราดนักและรับสั่งให้ฆ่าพวกนักปราชญ์ทั้งหมดของบาบิโลนเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 13, 'เพราะฉะนั้นจึงมีพระราชกฤษฎีกาประกาศไปว่าให้ฆ่านักปราชญ์เสียทั้งหมด เขาจึงเที่ยวหาดาเนียลและพรรคพวกเพื่อจะฆ่าเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 14, 'แล้วดาเนียลก็ตอบอารีโอคหัวหน้าราชองครักษ์ผู้ที่ออกไปเที่ยวฆ่านักปราชญ์ของบาบิโลน ด้วยถ้อยคําแยบคายและปรีชาสามารถ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 15, 'ท่านถามอารีโอคหัวหน้าว่า “ไฉนพระราชกฤษฎีกาของกษัตริย์จึงเร่งร้อนเล่า” แล้วอารีโอคก็เล่าเรื่องให้ดาเนียลทราบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 16, 'แล้วดาเนียลก็เข้าไปเฝ้าและกราบทูลกษัตริย์ขอให้กําหนดเวลาเพื่อท่านจะถวายคําแก้พระสุบินแด่กษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 17, 'แล้วดาเนียลก็กลับไปเรือนของท่าน และแจ้งเรื่องให้ฮานันยาห์ มิชาเอล และอาซาริยาห์สหายของท่านฟัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 18, 'และบอกเขาให้ขอพระกรุณาแห่งพระเจ้าแห่งฟ้าสวรรค์เรื่องความลึกลับนี้ เพื่อดาเนียลและสหายของท่านจะไม่พินาศพร้อมกับบรรดานักปราชญ์อื่นๆของบาบิโลน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 19, 'ในนิมิตกลางคืนทรงเผยความลึกลับนั้นแก่ดาเนียล แล้วดาเนียลก็ถวายสาธุการแด่พระเจ้าแห่งฟ้าสวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 20, 'ดาเนียลกล่าวว่า “สาธุการแด่พระนามของพระเจ้าเป็นนิตย์สืบไป เพราะปัญญาและฤทธานุภาพเป็นของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 21, 'พระองค์ทรงเปลี่ยนวาระและฤดูกาล พระองค์ทรงถอดกษัตริย์และทรงตั้งกษัตริย์ขึ้นใหม่ พระองค์ทรงประทานปัญญาแก่นักปราชญ์ และทรงประทานความรู้แก่ผู้ที่มีความเข้าใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 22, 'พระองค์ทรงเผยสิ่งที่ลึกซึ้งและลี้ลับ พระองค์ทรงทราบสิ่งที่อยู่ในความมืด และความสว่างก็อยู่กับพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 23, 'โอ พระเจ้าแห่งบรรพบุรุษของข้าพระองค์ ข้าพระองค์ขอโมทนาและสรรเสริญพระองค์ ผู้ทรงประทานปัญญาและกําลังแก่ข้าพระองค์ สิ่งนั้นที่พวกข้าพระองค์ทูลขอ พระองค์ก็ทรงให้ข้าพระองค์รู้แล้ว เพราะพระองค์ได้ทรงสําแดงเรื่องของกษัตริย์ให้แจ้งแก่พวกข้าพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 24, 'แล้วดาเนียลก็เข้าไปหาอารีโอคผู้ซึ่งกษัตริย์แต่งตั้งให้ฆ่านักปราชญ์แห่งบาบิโลน ท่านได้เข้าไปและกล่าวแก่อารีโอคว่าดังนี้ “ขออย่าฆ่านักปราชญ์แห่งบาบิโลน ขอโปรดนําตัวข้าพเจ้าเข้าไปเฝ้ากษัตริย์ และข้าพเจ้าจะถวายคําแก้ฝันแด่กษัตริย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 25, 'แล้วอารีโอคก็รีบนําตัวดาเนียลเข้าเฝ้ากษัตริย์ และกราบทูลพระองค์ว่า “ข้าพระองค์ได้พบชายคนหนึ่งในหมู่พวกที่ถูกกวาดเป็นเชลยมาจากยูดาห์ ชายผู้นี้จะให้กษัตริย์ทรงรู้คําแก้พระสุบินได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 26, 'กษัตริย์จึงตรัสแก่ดาเนียลผู้ชื่อว่าเบลเทชัสซาร์ว่า “เจ้าสามารถที่จะให้เรารู้ถึงความฝันที่เราได้ฝันนั้นและคําแก้ได้หรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 27, 'ดาเนียลกราบทูลต่อพระพักตร์กษัตริย์ว่า “ไม่มีนักปราชญ์ หรือหมอดู หรือโหร หรือหมอดูฤกษ์ยามสําแดงความลึกลับซึ่งกษัตริย์ไต่ถามแด่พระองค์ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 28, 'แต่มีพระเจ้าองค์หนึ่งในฟ้าสวรรค์ผู้ทรงเผยความลึกลับทั้งหลาย และพระองค์ทรงให้กษัตริย์เนบูคัดเนสซาร์รู้ถึงสิ่งซึ่งจะบังเกิดขึ้นในวาระภายหลัง พระสุบินของพระองค์และนิมิตที่ผุดขึ้นในพระเศียรของพระองค์บนพระแท่นนั้นเป็นดังนี้ พระเจ้าข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 29, 'โอ ข้าแต่กษัตริย์ ขณะเมื่อพระองค์บรรทมอยู่บนพระแท่น พระดําริในเรื่องซึ่งจะบังเกิดมาภายหลังได้ผุดขึ้น และพระองค์นั้นผู้ทรงเผยความลึกลับก็ทรงให้พระองค์รู้ถึงสิ่งที่จะบังเกิดมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 30, 'ฝ่ายข้าพระองค์ ซึ่งทรงเผยความลึกลับนี้แก่ข้าพระองค์นั้น มิใช่เพราะข้าพระองค์มีปัญญามากกว่าผู้มีชีวิตทั้งหลาย แต่เพื่อกษัตริย์จะทรงรู้คําแก้พระสุบิน และเพื่อพระองค์จะทรงรู้พระดําริในพระทัยของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 31, 'โอ ข้าแต่กษัตริย์ พระองค์ทอดพระเนตร และดูเถิด มีปฏิมากรขนาดใหญ่ ปฏิมากรนี้ใหญ่และสุกใสยิ่งนัก ตั้งอยู่ต่อเบื้องพระพักตร์พระองค์ และรูปร่างก็น่ากลัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 32, 'เศียรของปฏิมากรนี้เป็นทองคําเนื้อดี อกและแขนเป็นเงิน ท้องและโคนขาเป็นทองเหลือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 33, 'ขาเป็นเหล็ก เท้าเป็นเหล็กปนดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 34, 'ขณะเมื่อพระองค์ทอดพระเนตร มีหินก้อนหนึ่งถูกตัดออกมามิใช่ด้วยมือ กระทบปฏิมากรที่เท้าอันเป็นเหล็กปนดิน กระทําให้แตกเป็นชิ้นๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 35, 'แล้วส่วนเหล็ก ส่วนดิน ส่วนทองเหลือง ส่วนเงินและส่วนทองคํา ก็แตกเป็นชิ้นๆพร้อมกัน กลายเป็นเหมือนแกลบจากลานนวดข้าวในฤดูร้อน ลมก็พัดพาเอาไป จึงหาร่องรอยไม่พบเสียเลย แต่ก้อนหินที่กระทบปฏิมากรนั้นกลายเป็นภูเขาใหญ่จนเต็มพิภพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 36, 'นี่เป็นพระสุบิน พระเจ้าข้า บัดนี้เหล่าข้าพระองค์ขอกราบทูลคําแก้พระสุบินต่อพระพักตร์กษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 37, 'โอ ข้าแต่กษัตริย์ กษัตริย์จอมกษัตริย์ทั้งหลาย ซึ่งพระเจ้าแห่งฟ้าสวรรค์ได้ทรงประทานราชอาณาจักร อานุภาพ ฤทธิ์เดชและสง่าราศี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 38, 'และได้ทรงมอบไว้ในหัตถ์พระองค์ท่านซึ่งบุตรทั้งหลายของมนุษย์ สัตว์ในทุ่งนาและนกในอากาศไม่ว่ามันจะอาศัยอยู่ ณ ที่ใดๆให้แก่พระองค์ กระทําให้พระองค์ปกครองมันได้ทั้งหมด เศียรทองคํานั้นคือพระองค์เอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 39, 'ต่อจากพระองค์ไปจะมีราชอาณาจักรด้อยกว่าพระองค์ และยังมีราชอาณาจักรที่สาม เป็นทองเหลือง ซึ่งจะปกครองอยู่ทั่วพิภพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 40, 'และจะมีราชอาณาจักรที่สี่แข็งแรงดั่งเหล็ก เพราะเหล็กตีสิ่งทั้งหลายให้หักเป็นชิ้นๆและปราบสิ่งทั้งปวงลงได้ ราชอาณาจักรนั้นจะหัก และทุบสิ่งทั้งปวงเหล่านี้ดังเหล็กซึ่งทุบให้แหลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 41, 'ดั่งที่พระองค์ทอดพระเนตรเท้าและนิ้วเท้า เท้าเป็นดินช่างหม้อบ้าง เหล็กบ้าง จะเป็นราชอาณาจักรประสม แต่ความแข็งแกร่งของเหล็กจะยังอยู่ในนั้นบ้าง ดังที่พระองค์ทอดพระเนตรเหล็กปนดินเหนียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 42, 'และนิ้วเท้าเป็นเหล็กปนดินฉันใด ราชอาณาจักรนั้นจึงแข็งแรงบ้างเปราะบ้างฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 43, 'ดังที่พระองค์ทอดพระเนตรเหล็กปนดินเหนียว ราชอาณาจักรจะปนกันด้วยเชื้อสายของมนุษย์ แต่จะไม่ยึดกันแน่นไว้ได้อย่างเดียวกับที่เหล็กไม่ประสมเข้ากับดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 44, 'และในสมัยของกษัตริย์เหล่านั้น พระเจ้าแห่งฟ้าสวรรค์จะทรงสถาปนาราชอาณาจักรหนึ่ง ซึ่งไม่มีวันทําลายเสียได้ หรือราชอาณาจักรนั้นจะไม่ตกไปแก่ชนชาติอื่น ราชอาณาจักรนั้นจะกระทําให้บรรดาราชอาณาจักรเหล่านี้แตกเป็นชิ้นๆถึงอวสาน และราชอาณาจักรนั้นจะตั้งมั่นอยู่เป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 45, 'ดังที่พระองค์ทอดพระเนตรก้อนหินถูกตัดออกจากภูเขามิใช่ด้วยมือ และก้อนหินนั้นได้กระทําให้เหล็ก ทองเหลือง ดิน เงิน และทองคําแตกเป็นชิ้นๆ พระเจ้ายิ่งใหญ่ได้ทรงให้กษัตริย์รู้ว่าอะไรจะบังเกิดมาภายหลังนี้ พระสุบินนั้นเที่ยงแท้และคําแก้พระสุบินก็แน่นอน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 46, 'แล้วกษัตริย์เนบูคัดเนสซาร์ก็ทรงกราบลงและเคารพดาเนียล และมีพระบัญชาให้นําเครื่องบูชาและเครื่องหอมมาถวายดาเนียล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 47, 'กษัตริย์ตรัสกับดาเนียลว่า “แน่นอนทีเดียว พระเจ้าของท่านเป็นพระเจ้าของพระทั้งหลาย และทรงเป็นองค์พระผู้เป็นเจ้าของกษัตริย์ทั้งปวง ทรงเป็นผู้เผยความลึกลับเพราะท่านสามารถที่จะเผยความลึกลับนี้ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 48, 'ฝ่ายกษัตริย์ก็พระราชทานยศชั้นสูง และของพระราชทานยิ่งใหญ่เป็นอันมากแก่ดาเนียล และแต่งตั้งให้เป็นผู้ครอบครองหมดเมืองบาบิโลน และเป็นประธานใหญ่ของนักปราชญ์ทั้งสิ้นแห่งบาบิโลน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 49, 'ดาเนียลก็กราบทูลขอต่อกษัตริย์และพระองค์ทรงตั้งให้ชัดรัค เมชาคและเอเบดเนโกเป็นผู้จัดราชการในเมืองบาบิโลน แต่ดาเนียลยังคงอยู่ในราชสํานัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 1, 'กษัตริย์เนบูคัดเนสซาร์ได้สร้างปฏิมากรรูปหนึ่งด้วยทองคํา สูงหกสิบศอก กว้างหกศอก ทรงตั้งไว้ ณ ที่ราบดูรา ในเมืองบาบิโลน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 2, 'แล้วกษัตริย์เนบูคัดเนสซาร์รับสั่งให้ประชุมบรรดาอุปราช ข้าหลวงภาค ผู้ว่าราชการเมือง ผู้พิพากษา นายคลัง มนตรี ตุลาการ และเจ้าหน้าที่ทั้งหลายของหัวเมือง ให้เข้ามาในงานฉลองปฏิมากรซึ่งกษัตริย์เนบูคัดเนสซาร์ได้ทรงตั้งขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 3, 'แล้วบรรดาอุปราช ข้าหลวงภาค ผู้ว่าราชการเมือง ผู้พิพากษา นายคลัง มนตรี ตุลาการและเจ้าหน้าที่ทั้งหลายของหัวเมืองได้เข้ามาประชุมเพื่องานฉลองปฏิมากร ซึ่งกษัตริย์เนบูคัดเนสซาร์ได้ทรงตั้งขึ้น และเขาทั้งหลายก็มายืนอยู่หน้าปฏิมากรซึ่งกษัตริย์เนบูคัดเนสซาร์ได้ทรงตั้งขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 4, 'และโฆษกก็ประกาศเสียงดังว่า “โอ บรรดาชนชาติ ประชาชาติทั้งปวงและภาษาทั้งหลาย มีพระบัญชาแก่ท่านทั้งหลายว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 5, 'เมื่อท่านได้ยินเสียงแตรทองเหลืองขนาดเล็ก ปี่ พิณเขาคู่ พิณสี่สาย พิณใหญ่ ปี่ถุง และเครื่องดนตรีทุกชนิด ให้ท่านทั้งหลายกราบลงนมัสการปฏิมากรทองคํา ซึ่งกษัตริย์เนบูคัดเนสซาร์ได้ทรงตั้งไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 6, 'ผู้ใดที่มิได้กราบลงนมัสการก็ให้โยนผู้นั้นทันทีเข้าไปในเตาที่ไฟลุกอยู่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 7, 'เพราะฉะนั้นพอประชาชนได้ยินเสียงแตรทองเหลืองขนาดเล็ก ปี่ พิณเขาคู่ พิณสี่สาย พิณใหญ่และเครื่องดนตรีทุกชนิด บรรดาชนชาติ ประชาชาติทั้งปวงและภาษาทั้งหลาย ก็กราบลงนมัสการปฏิมากรทองคําซึ่งกษัตริย์เนบูคัดเนสซาร์ได้ทรงตั้งไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 8, 'เพราะฉะนั้น ในครั้งนั้นพวกเคลเดียบางคนมาเข้าเฝ้า และฟ้องพวกยิวด้วยใจคิดร้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 9, 'เขาทั้งหลายกราบทูลกษัตริย์เนบูคัดเนสซาร์ว่า “โอ ข้าแต่กษัตริย์ ขอทรงพระเจริญเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 10, 'โอ ข้าแต่กษัตริย์ พระองค์ทรงออกกฤษฎีกาแล้วว่า ทุกคนผู้ได้ยินเสียงแตรทองเหลืองขนาดเล็ก ปี่ พิณเขาคู่ พิณสี่สาย พิณใหญ่ ปี่ถุง และเครื่องดนตรีทุกชนิด ก็ให้กราบลงนมัสการปฏิมากรทองคํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 11, 'และผู้ใดที่ไม่กราบลงนมัสการก็ให้โยนเข้าไปในเตาที่ไฟลุกอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 12, 'มียิวบางคนที่พระองค์ได้แต่งตั้งให้จัดราชการในเมืองบาบิโลน คือชัดรัค เมชาค และเอเบดเนโก โอ ข้าแต่กษัตริย์ คนเหล่านี้ไม่เชื่อฟังพระองค์ เขามิได้ปฏิบัติพระของพระองค์ หรือนมัสการปฏิมากรทองคําซึ่งพระองค์ได้ทรงตั้งไว้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 13, 'แล้วเนบูคัดเนสซาร์ก็ทรงกริ้วจัดและเดือดพล่าน มีรับสั่งให้นําตัวชัดรัค เมชาค และเอเบดเนโกเข้ามา แล้วเขาก็นําคนเหล่านี้เข้ามาเฝ้ากษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 14, 'เนบูคัดเนสซาร์ทรงกล่าวแก่เขาว่า “โอ ชัดรัค เมชาค และเอเบดเนโกเอ๋ย เป็นความจริงหรือไม่ที่เจ้ามิได้ปรนนิบัติพระของเรา หรือนมัสการปฏิมากรทองคําซึ่งเราได้ตั้งไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 15, 'บัดนี้ถ้าเจ้าพร้อมใจแล้ว พอเจ้าได้ยินเสียงแตรทองเหลืองขนาดเล็ก ปี่ พิณเขาคู่ พิณสี่สาย พิณใหญ่ ปี่ถุง และเครื่องดนตรีทุกชนิด เจ้าจงกราบลงนมัสการปฏิมากรซึ่งเราได้สร้างไว้ แต่ถ้าเจ้าไม่นมัสการ จะต้องโยนเจ้าทันทีเข้าไปในเตาที่ไฟลุกอยู่ และผู้ใดเล่าจะเป็นพระเจ้าที่จะช่วยให้เจ้าพ้นจากมือของเราได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 16, 'ชัดรัค เมชาค และเอเบดเนโกกราบทูลกษัตริย์ว่า “โอ ข้าแต่เนบูคัดเนสซาร์ ข้าพระองค์ทั้งหลายไม่จําเป็นจะต้องตอบพระองค์ในเรื่องนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 17, 'ถ้าพระเจ้าของพวกข้าพระองค์ผู้ซึ่งพวกข้าพระองค์ปรนนิบัติ สามารถช่วยพวกข้าพระองค์ให้พ้นจากเตาที่ไฟลุกอยู่ โอ ข้าแต่กษัตริย์ พระองค์ก็จะทรงช่วยพวกข้าพระองค์ให้พ้นพระหัตถ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 18, 'แต่ถ้าไม่เป็นเช่นนั้น โอ ข้าแต่กษัตริย์ ขอพระองค์ทรงทราบว่า พวกข้าพระองค์จะไม่ปรนนิบัติพระของพระองค์ หรือนมัสการปฏิมากรทองคําซึ่งพระองค์ได้ทรงตั้งขึ้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 19, 'แล้วเนบูคัดเนสซาร์ทรงเกรี้ยวกราดยิ่งนัก พระพักตร์ของพระองค์ก็เปลี่ยนไปไม่พอพระทัยชัดรัค เมชาค และเอเบดเนโก พระองค์จึงรับสั่งให้ทําเตาไฟให้ร้อนกว่าที่เคยอีกเจ็ดเท่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 20, 'และพระองค์รับสั่งให้บางคนที่มีกําลังมากที่สุดในกองทัพมามัดชัดรัค เมชาค และเอเบดเนโก และให้โยนเขาเข้าไปในเตาที่ไฟลุกอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 21, 'แล้วคนเหล่านี้ก็ถูกมัดไว้ทั้งเสื้อ กางเกง หมวก และเครื่องแต่งกายอื่นๆ และเขาก็ถูกโยนเข้าไปในเตาที่ไฟลุกอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 22, 'ฉะนั้นเพราะว่าคํารับสั่งของกษัตริย์นั้นเข้มงวดมากและเตาไฟก็ร้อนจัด เปลวไฟจึงได้ฆ่าคนที่โยนชัดรัค เมชาค และเอเบดเนโก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 23, 'และชายทั้งสามนี้ คือชัดรัค เมชาค และเอเบดเนโกก็ตกลงไปกลางเตาไฟที่ลุกอยู่ทั้งยังมัดอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 24, 'ขณะนั้นกษัตริย์เนบูคัดเนสซาร์ประหลาดพระทัยทรงลุกขึ้นโดยฉับพลัน พระองค์ตรัสกับองคมนตรีของพระองค์ว่า “เรามัดสามคนโยนเข้าไปกลางไฟมิใช่หรือ” เขาทูลตอบกษัตริย์ว่า “โอ ข้าแต่กษัตริย์ จริงพระเจ้าข้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 25, 'พระองค์ตรัสตอบว่า “ดูเถิด เราเห็นสี่คนถูกปล่อย กําลังเดินอยู่กลางไฟ และเขาทั้งหลายก็ไม่เป็นอันตราย รูปร่างของคนที่สี่นั้นคล้ายคลึงกับพระบุตรของพระเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 26, 'แล้วเนบูคัดเนสซาร์เสด็จมาใกล้ประตูเตาที่ไฟลุกอยู่นั้น ทรงกล่าวว่า “ชัดรัค เมชาค และเอเบดเนโก ผู้รับใช้ของพระเจ้าสูงสุด จงออกมาเถิด จงมาที่นี่” แล้วชัดรัค เมชาค และเอเบดเนโกก็เดินออกมาจากกลางไฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 27, 'ฝ่ายบรรดาอุปราช ข้าหลวงภาค ผู้ว่าราชการเมือง และองคมนตรีของกษัตริย์ก็ห้อมล้อมเข้ามา เห็นว่าไฟไม่มีอํานาจอะไรเหนือร่างกายของคนเหล่านี้ ผมที่ศีรษะของเขาก็ไม่ไหม้เกรียม เสื้อก็มิได้เป็นอันตราย ไม่มีกลิ่นไฟที่ตัวเขาทั้งหลายเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 28, 'เนบูคัดเนสซาร์ตรัสว่า “สาธุการแด่พระเจ้าของชัดรัค เมชาค และเอเบดเนโก ผู้ได้ส่งทูตสวรรค์ของพระองค์มาช่วยผู้รับใช้ของพระองค์ให้พ้น ผู้วางใจในพระองค์ กระทําให้พระบัญชาของกษัตริย์เหลวไป และยอมพลีร่างกายของเขาเสียดีกว่าที่จะปรนนิบัติและนมัสการพระอื่น นอกจากพระเจ้าของเขาเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 29, 'เพราะฉะนั้นเราจึงออกกฤษฎีกาว่า ชนชาติ ประชาชาติ หรือภาษาใดๆที่กล่าวมิดีมิร้ายต่อพระเจ้าของชัดรัค เมชาค และเอเบดเนโก จะถูกหั่นเป็นชิ้นๆ และบ้านเรือนของเขาจะต้องเป็นกองขยะ เพราะว่าไม่มีพระเจ้าอื่นที่จะสามารถช่วยให้พ้นในทางนี้ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 30, 'แล้วกษัตริย์ได้ทรงเลื่อนยศให้ชัดรัค เมชาค และเอเบดเนโกสูงขึ้นอีกในเมืองบาบิโลน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 1, 'เรา กษัตริย์เนบูคัดเนสซาร์ ขอประกาศแก่บรรดาชนชาติ ประชาชาติทั้งปวง และภาษาทั้งหลาย ซึ่งอาศัยอยู่บนพิภพทั้งสิ้นว่า สันติสุขจงมีแก่ท่านทั้งหลายอย่างทวีคูณ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 2, 'เราเห็นสมควรที่จะแสดงหมายสําคัญและการมหัศจรรย์ ซึ่งพระเจ้าสูงสุดได้ทรงกระทําแก่เรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 3, 'หมายสําคัญของพระองค์ใหญ่ยิ่งสักเท่าใด การมหัศจรรย์ของพระองค์กอปรด้วยฤทธานุภาพปานใด อาณาจักรของพระองค์เป็นอาณาจักรถาวรเป็นนิตย์ และราชอาณาจักรของพระองค์นั้นดํารงอยู่ทุกชั่วอายุ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 4, 'ตัวเรา คือ เนบูคัดเนสซาร์อยู่เป็นผาสุกในนิเวศของเรา และมีความเจริญอยู่ในวังของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 5, 'เราฝันเห็นเรื่องซึ่งกระทําให้เรากลัว ขณะเมื่อเรานอนอยู่บนที่นอนความคิดและนิมิตอันผุดขึ้นในศีรษะของเราเป็นเหตุให้เราตกใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 6, 'เราจึงออกกฤษฎีกาเรียกนักปราชญ์แห่งบาบิโลนทั้งสิ้นมาหาเราเพื่อให้แก้ความฝันให้แก่เรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 7, 'พวกโหร พวกหมอดู และคนเคลเดีย และหมอดูฤกษ์ยามก็เข้ามาเฝ้า เราก็เล่าความฝันแก่เขา แต่เขาทั้งหลายแก้ฝันให้เราไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 8, 'ในที่สุดดาเนียลก็เข้ามาเฝ้าเรา เขามีชื่อว่าเบลเทชัสซาร์ ตามนามพระของเรา เขามีวิญญาณของพระผู้บริสุทธิ์ เราก็เล่าความฝันให้เขาฟังว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 9, '“โอ เบลเทชัสซาร์ หัวหน้าของพวกโหร เพราะเราทราบว่าวิญญาณของพระผู้บริสุทธิ์อยู่ในท่าน และไม่มีความล้ําลึกใดๆที่จะให้ท่านแก้ยาก จงบอกนิมิตทั้งหลายในความฝันที่เราได้เห็น และตีความนิมิตเหล่านั้นให้แก่เรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 10, 'นิมิตที่ผุดขึ้นในศีรษะของเราเมื่อนอนอยู่บนที่นอน ดูเถิด เราได้เห็นต้นไม้ท่ามกลางพิภพ มันสูงมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 11, 'ต้นไม้เติบโตและแข็งแรง ยอดของมันขึ้นไปถึงฟ้าสวรรค์ และประจักษ์ไปถึงที่สุดปลายพิภพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 12, 'ใบก็งดงามและผลก็อุดม และจากต้นไม้นั้น มีอาหารให้แก่ชีวิตทั้งปวง สัตว์ป่าที่ในทุ่งนาอาศัยอยู่ใต้ร่มของมัน และนกในอากาศก็อาศัยอยู่ที่กิ่งก้านของมัน และเนื้อหนังทั้งหลายก็เลี้ยงตนอยู่ด้วยมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 13, 'ในนิมิตที่ผุดขึ้นในศีรษะของเราเมื่อเราอยู่บนที่นอน ดูเถิด เราได้เห็นผู้พิทักษ์ องค์บริสุทธิ์ลงมาจากฟ้าสวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 14, 'ท่านเปล่งเสียงและพูดดังนี้ว่า ‘จงฟันต้นไม้และตัดกิ่งทั้งหลายของมันออกเสีย สะบัดให้ใบของมันร่วงออกแล้วให้ผลของมันกระจายไป ให้สัตว์ป่าหนีไปเสียจากใต้ต้น และให้นกหนีไปเสียจากกิ่งของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 15, 'แต่จงปล่อยให้ตอรากติดอยู่ในดิน มีปลอกเหล็กและทองเหลืองสวมไว้ ให้อยู่ท่ามกลางหญ้าอ่อนในทุ่งนา ให้เปียกน้ําค้างจากฟ้าสวรรค์ ให้เขามีส่วนอยู่กับสัตว์ป่าในหญ้าที่พื้นดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 16, 'ให้จิตใจของเขาเปลี่ยนเสียจากจิตใจมนุษย์ แล้วมอบใจสัตว์ป่าให้แก่เขา และปล่อยให้เป็นอยู่อย่างนั้นจนครบเจ็ดวาระ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 17, 'คําพิพากษานั้นเป็นคําสั่งของผู้พิทักษ์ คําตัดสินนั้นเป็นวาทะขององค์บริสุทธิ์ เพื่อผู้มีชีวิตอยู่จะได้ทราบว่าท่านผู้สูงสุดทรงปกครองอยู่เหนือราชอาณาจักรของมนุษย์ และประทานราชอาณาจักรนั้นแก่ผู้ที่พระองค์จะประทาน และตั้งผู้ที่ด้อยที่สุดให้อยู่เหนือ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 18, 'ความฝันนี้ตัวเราคือกษัตริย์เนบูคัดเนสซาร์ได้เห็นและ โอ เบลเทชัสซาร์ ท่านจงกล่าวคําแก้ฝันเถิด เพราะพวกนักปราชญ์ทั้งสิ้นแห่งราชอาณาจักรของเราไม่สามารถที่จะให้คําแก้ความฝันแก่เรา แต่ท่านสามารถ เพราะวิญญาณของพระผู้บริสุทธิ์อยู่ในตัวท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 19, 'แล้วดาเนียล ผู้มีชื่อว่าเบลเทชัสซาร์ ก็งงงันอยู่ชั่วโมงหนึ่ง ความคิดของท่านก็กระทําให้ท่านตกใจ กษัตริย์ตรัสว่า “เบลเทชัสซาร์เอ๋ย อย่าให้ความฝันหรือคําแก้ความฝันกระทําให้ท่านตกใจเลย” เบลเทชัสซาร์ทูลตอบว่า “เจ้านายของข้าพระองค์ ขอให้ความฝันนั้นเป็นเรื่องของผู้ที่เกลียดชังพระองค์เถิด และขอให้คําแก้ความฝันนั้นตกแก่ปฏิปักษ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 20, 'ต้นไม้ที่พระองค์ทอดพระเนตร ซึ่งเติบโตขึ้นและแข็งแรง จนยอดขึ้นไปถึงฟ้าสวรรค์ ประจักษ์ไปทั่วพิภพทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 21, 'ใบของมันก็งดงามและผลก็อุดม และจากต้นนั้นมีอาหารให้แก่ชีวิตทั้งปวง สัตว์ป่าในทุ่งนามาพึ่งร่มอยู่ใต้ต้น และนกในอากาศก็มาอาศัยอยู่ที่กิ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 22, 'โอ ข้าแต่กษัตริย์ นี่คือพระองค์เอง ผู้ทรงเจริญและเข้มแข็ง ความยิ่งใหญ่ของพระองค์ได้เจริญ และขึ้นไปถึงฟ้าสวรรค์ และราชอาณาจักรของพระองค์ก็ไปถึงสุดปลายพิภพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 23, 'และที่กษัตริย์ทอดพระเนตรผู้พิทักษ์คือองค์บริสุทธิ์ลงมาจากฟ้าสวรรค์ และพูดว่า ‘จงฟันต้นไม้และทําลายเสีย แต่จงปล่อยให้ตอรากติดอยู่ในดิน มีปลอกเหล็กและทองเหลืองสวมไว้ ให้อยู่ท่ามกลางหญ้าอ่อน ในทุ่งนาให้เปียกน้ําค้างจากฟ้าสวรรค์ ให้เขามีส่วนอยู่กับสัตว์ป่า และปล่อยให้อยู่อย่างนั้นจนครบเจ็ดวาระ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 24, 'โอ ข้าแต่กษัตริย์ ต่อไปนี้เป็นคําแก้พระสุบิน เป็นพระราชกฤษฎีกามาจากผู้สูงสุด ซึ่งมาถึงกษัตริย์เจ้านายของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 25, 'ว่าพระองค์จะทรงถูกขับไล่ไปเสียจากท่ามกลางมนุษย์ และพระองค์จะอยู่กับสัตว์ในทุ่งนา พระองค์จะต้องเสวยหญ้าอย่างกับวัว และจะให้พระองค์เปียกน้ําค้างจากฟ้าสวรรค์ จะเป็นอยู่อย่างนั้นจนครบเจ็ดวาระ จนกว่าพระองค์จะทราบว่า ผู้สูงสุดนั้นทรงปกครองราชอาณาจักรของมนุษย์ และพระองค์จะประทานราชอาณาจักรนั้นแก่ผู้ที่พระองค์ทรงปรารถนา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 26, 'และที่ทรงมีพระบัญชาให้เหลือตอรากต้นไม้นั้นไว้ก็หมายความว่า ราชอาณาจักรจะยังเป็นของพระองค์ ตั้งแต่พระองค์ทรงทราบว่าสวรรค์ปกครอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 27, 'โอ ข้าแต่กษัตริย์ เพราะฉะนั้นขอทรงรับคํากราบทูลของข้าพระองค์ ขอพระองค์ทรงเลิกทําบาปเสียด้วยการกระทําความชอบธรรม และเลิกทําความชั่วช้าด้วยสําแดงความกรุณาต่อคนจน เผื่อว่าความผาสุกของพระองค์อาจจะยืดยาวไปอีกได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 28, 'สิ่งเหล่านี้ทั้งสิ้นได้บังเกิดขึ้นแก่กษัตริย์เนบูคัดเนสซาร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 29, 'พอสิ้นสิบสองเดือน พระองค์เสด็จดําเนินอยู่ในพระราชวังแห่งราชอาณาจักรบาบิโลน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 30, 'และกษัตริย์ตรัสว่า “นี่เป็นมหาบาบิโลนมิใช่หรือ ซึ่งเราได้สร้างไว้เพื่อวงศ์วานแห่งอาณาจักรนี้ด้วยอํานาจใหญ่ยิ่งของเรา และเพื่อเป็นศักดิ์ศรีอันสูงส่งของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 31, 'เมื่อกษัตริย์ตรัสยังไม่ทันขาดพระวาทะ ก็มีเสียงตกลงมาจากฟ้าสวรรค์ว่า “โอ กษัตริย์เนบูคัดเนสซาร์ เราลั่นวาจาไว้กับเจ้าแล้วว่า ราชอาณาจักรได้พรากไปเสียจากเจ้าแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 32, 'และเจ้าจะถูกขับไล่ไปจากท่ามกลางมนุษย์ และเจ้าจะอยู่กับสัตว์ในทุ่งนา และเจ้าจะต้องกินหญ้าอย่างกับวัว จะเป็นอยู่อย่างนั้นจนครบเจ็ดวาระ จนกว่าเจ้าจะเรียนรู้ได้ว่า ผู้สูงสุดปกครองอยู่เหนือราชอาณาจักรของมนุษย์ และประทานราชอาณาจักรนั้นแก่ผู้ที่พระองค์ทรงปรารถนา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 33, 'ในทันใดนั้นเองพระวาทะก็สําเร็จในเรื่องเนบูคัดเนสซาร์ พระองค์ถูกขับไล่ไปจากท่ามกลางมนุษย์ และเสวยหญ้าอย่างกับวัว และพระกายก็เปียกน้ําค้างจากฟ้าสวรรค์ จนพระเกศางอกยาวอย่างกับขนนกอินทรี และพระนขาก็เหมือนเล็บนก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 34, 'เมื่อสิ้นสุดวาระนั้นแล้ว ตัวเราเนบูคัดเนสซาร์ก็แหงนหน้าดูฟ้าสวรรค์และจิตปกติของเราคืนมา และเราก็สาธุการแด่ผู้สูงสุดนั้น และสรรเสริญถวายเกียรติยศแด่พระองค์ผู้ดํารงอยู่เป็นนิตย์ เพราะราชอาณาจักรของพระองค์เป็นราชอาณาจักรนิรันดร์ และอาณาจักรของพระองค์ดํารงอยู่ทุกชั่วอายุ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 35, 'สําหรับพระองค์ชาวพิภพทั้งสิ้นนับว่าไม่มีค่า ท่ามกลางกองทัพแห่งสวรรค์นั้นพระองค์ทรงกระทําตามชอบพระทัยพระองค์ และท่ามกลางชาวพิภพด้วย และไม่มีผู้ใดยับยั้งพระหัตถ์ของพระองค์ได้ หรือตรัสถามพระองค์ได้ว่า “พระองค์ทรงกระทําสิ่งใด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 36, 'ในเวลานั้นเอง จิตปกติของเราก็กลับคืนมา ความสูงส่งและสง่าราศีอันยิ่งใหญ่กลับมาสู่เราอีก เพื่อสง่าราศีแห่งราชอาณาจักรของเรา องคมนตรีและข้าราชบริพารของเรากลับมาหาเรา และเราก็รับการสถาปนาไว้ในราชอาณาจักรของเรา ความใหญ่ยิ่งกลับเพิ่มพูนแก่เราขึ้นอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 37, 'บัดนี้ตัวเราคือเนบูคัดเนสซาร์ ขอสรรเสริญ ยกย่องและถวายพระเกียรติแด่พระมหากษัตริย์แห่งสวรรค์ เพราะว่าพระราชกิจของพระองค์ก็ถูกต้อง และพระมรรคาของพระองค์ก็เที่ยงธรรม บรรดาผู้ดําเนินอยู่ในความเย่อหยิ่ง พระองค์ก็ทรงสามารถให้ต่ําลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 1, 'กษัตริย์เบลชัสซาร์ได้ทรงจัดการเลี้ยงใหญ่แก่เจ้านายหนึ่งพันคน และเสวยเหล้าองุ่นต่อหน้าคนหนึ่งพันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 2, 'เมื่อเบลชัสซาร์ทรงลิ้มรสเหล้าองุ่นแล้ว จึงมีพระบัญชาให้นําภาชนะทองคําและเงินซึ่งเนบูคัดเนสซาร์ราชบิดาได้ทรงกวาดมาจากพระวิหารในกรุงเยรูซาเล็ม ออกมาให้กษัตริย์และเจ้านายของพระองค์ ทั้งพระสนมและนางห้ามจะได้ใช้ใส่เหล้าดื่ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 3, 'เขาทั้งหลายจึงนําภาชนะทองคําซึ่งได้กวาดมาจากพระวิหาร คือพระนิเวศของพระเจ้าในกรุงเยรูซาเล็ม และกษัตริย์และเจ้านายของพระองค์ ทั้งพระสนมและนางห้ามก็ได้ดื่มจากภาชนะเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 4, 'เขาทั้งหลายดื่มเหล้าองุ่นและสรรเสริญพระที่ทําด้วยทองคํา เงิน ทองเหลือง เหล็ก ไม้และหิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 5, 'ในทันใดนั้น นิ้วมือคนได้ปรากฏขึ้น และเขียนลงที่ผนังของพระราชวังของกษัตริย์ตรงข้ามกับคันประทีป และกษัตริย์ก็ทอดพระเนตรมือที่เขียนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 6, 'แล้วสีพระพักตร์ของกษัตริย์ก็เปลี่ยนไป พระดําริของพระองค์กระทําให้พระองค์ตกพระทัย พระเพลาก็อ่อนเปลี้ย พระชานุก็กระทบกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 7, 'กษัตริย์รับสั่งเสียงดัง ให้นําหมอดูและคนเคลเดีย และหมอดูฤกษ์ยามเข้ามาเฝ้า และกษัตริย์ตรัสกับพวกนักปราชญ์กรุงบาบิโลนว่า “ผู้ใดที่อ่านข้อเขียนนี้และแปลความให้เราได้ เราจะให้ผู้นั้นสวมเสื้อสีม่วง และสวมสร้อยคอทองคํา และเราจะตั้งให้เป็นอุปราชตรีในราชอาณาจักรของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 8, 'แล้วพวกนักปราชญ์ของกษัตริย์ก็เข้ามาทั้งหมด แต่เขาทั้งหลายอ่านข้อเขียน หรือแปลความหมายให้กษัตริย์ทรงทราบหาได้ไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 9, 'แล้วกษัตริย์เบลชัสซาร์ก็ตกพระทัยมาก และสีพระพักตร์ของพระองค์ก็เปลี่ยนไป และเจ้านายทั้งหลายของพระองค์ก็งงงวย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 10, 'ด้วยเหตุพระวาทะของกษัตริย์และเจ้านายทั้งหลาย พระราชินีก็เสด็จเข้ามาในท้องพระโรงการเลี้ยง และพระราชินีทูลตรัสว่า “โอ ข้าแต่กษัตริย์ ขอทรงพระเจริญเป็นนิตย์ ขอพระองค์อย่าได้ตกพระทัย หรือให้สีพระพักตร์ของพระองค์เปลี่ยนไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 11, 'ในราชอาณาจักรของพระองค์มีชายคนหนึ่ง มีวิญญาณของพระผู้บริสุทธิ์ในตัว ในครั้งรัชกาลของพระชนก ความสว่าง ความเข้าใจ และปัญญา เหมือนปัญญาของพระ ได้มีประจําอยู่ที่ชายคนนี้ และกษัตริย์เนบูคัดเนสซาร์พระชนกของพระองค์ คือกษัตริย์พระชนกของพระองค์ ได้ทรงแต่งตั้งให้เขาเป็นประธานใหญ่ของพวกโหร หมอดู คนเคลเดีย และหมอดูฤกษ์ยาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 12, 'เพราะว่าดาเนียล ซึ่งกษัตริย์ประทานนามว่า เบลเทชัสซาร์ มีวิญญาณเลิศ มีความรู้และความเข้าใจที่จะแก้ความฝัน แก้ปริศนาและแก้ปัญหาต่างๆ บัดนี้ทรงเรียกดาเนียลให้เข้ามาเฝ้า แล้วเขาก็จะแปลความหมายถวายพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 13, 'เขาจึงนําดาเนียลเข้ามาเฝ้ากษัตริย์ กษัตริย์ตรัสถามดาเนียลว่า “ท่านคือดาเนียลคนนั้นในพวกที่ถูกกวาดเป็นเชลยมาจากประเทศยูดาห์ ที่กษัตริย์เสด็จพ่อของเรานํามาจากยูดาห์หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 14, 'เราได้ยินว่าท่านมีวิญญาณของพระในตัว และท่านมีความสว่าง ความเข้าใจและปัญญาเลิศประจําตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 15, 'บัดนี้ เราให้พวกนักปราชญ์ พวกหมอดูมาเข้าเฝ้า เพื่อให้อ่านข้อความนี้ และแปลความหมายให้เรา แต่เขาแปลความหมายของเรื่องราวนี้ไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 16, 'แต่เราได้ยินว่าท่านให้คําแปลและแก้ปัญหาได้ บัดนี้ถ้าท่านอ่านข้อความและแปลความหมายให้ได้ จะให้ท่านสวมเสื้อสีม่วง และสวมสร้อยคอทองคํา และจะตั้งท่านให้เป็นอุปราชตรีในราชอาณาจักร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 17, 'แล้วดาเนียลกราบทูลต่อพระพักตร์กษัตริย์ว่า “ขอทรงเก็บของพระราชทานไว้กับพระองค์เถิด และขอทรงพระราชทานรางวัลแก่ผู้อื่น ฝ่ายข้าพระองค์จะขออ่านข้อเขียนถวายกษัตริย์ และถวายคําแปลความหมายให้พระองค์ทรงทราบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 18, 'โอ ข้าแต่กษัตริย์ พระเจ้าสูงสุดได้ทรงประทานพระราชอาณาจักร ความยิ่งใหญ่และสง่าราศี และเกียรติยศแด่เนบูคัดเนสซาร์ราชบิดาของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 19, 'และเพราะความยิ่งใหญ่ซึ่งพระองค์ประทานแด่เนบูคัดเนสซาร์ บรรดาชนชาติ ประชาชาติทั้งปวง และภาษาทั้งหลายจึงได้สั่นสะท้านและเกรงขามต่อพระพักตร์พระราชบิดา พระองค์จะทรงประหารผู้ใดก็ทรงประหารเสีย หรือทรงให้ผู้ใดดํารงชีวิตอยู่ก็ทรงให้ดํารงชีวิต พระองค์จะทรงแต่งตั้งผู้ใดก็ทรงแต่งตั้ง พระองค์จะทรงกระทําให้ผู้ใดด้อยลงพระองค์ก็ทรงกระทํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 20, 'แต่เมื่อพระทัยของพระบิดาผยองขึ้น ฝ่ายจิตวิญญาณของพระองค์ก็แข็งกระด้างไป จึงทรงประกอบกิจด้วยความเห่อเหิม พระเจ้าทรงถอดพระองค์จากราชบัลลังก์ และทรงริบสง่าราศีของพระองค์ไปเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 21, 'พระเจ้าทรงขับไล่เนบูคัดเนสซาร์ไปจากบุตรทั้งหลายของมนุษย์ และทรงกระทําให้พระทัยของพระองค์ท่านเป็นเหมือนใจสัตว์ป่า และทรงให้อยู่กับลาป่า ทรงให้หญ้าเสวยเหมือนวัว และพระกายของพระองค์ท่านก็เปียกน้ําค้างจากฟ้าสวรรค์ จนกว่าพระองค์รู้ว่าพระเจ้าสูงสุดทรงปกครองราชอาณาจักรของมนุษย์ และทรงแต่งตั้งผู้ที่พระองค์จะทรงปรารถนาให้ปกครอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 22, 'โอ ข้าแต่เบลชัสซาร์ พระองค์เป็นราชโอรส แม้พระองค์ทรงทราบเช่นนี้ทั้งสิ้นแล้วก็มิได้ถ่อมพระทัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 23, 'แต่ทรงยกพระองค์ขึ้นสู้กับองค์พระผู้เป็นเจ้าแห่งสวรรค์ และทรงให้นําภาชนะแห่งพระนิเวศของพระองค์มาต่อพระพักตร์พระองค์ แล้วพระองค์ พวกเจ้านายของพระองค์ พระสนม และนางห้ามของพระองค์ก็ดื่มเหล้าองุ่นจากภาชนะเหล่านั้น และพระองค์ทรงสรรเสริญพระที่ทําด้วยเงิน ทองคํา ทองเหลือง เหล็ก ไม้ และหิน ซึ่งจะดูหรือฟัง หรือรู้เรื่องก็ไม่ได้ แต่พระองค์มิได้ถวายพระเกียรติแด่พระเจ้าซึ่งลมปราณของพระองค์อยู่ในพระหัตถ์ของพระองค์ และทางทั้งสิ้นของพระองค์ก็ขึ้นอยู่กับพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 24, 'จึงมีมือซึ่งรับใช้มาจากพระพักตร์ได้จารึกข้อเขียนนี้ลงไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 25, 'ต่อไปนี้เป็นข้อเขียนที่จารึกไว้ คือ เมเน เมเน เทเคล และ ฟารสิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 26, 'ต่อไปนี้เป็นคําไขเรื่องราวนั้น เมเน พระเจ้าได้ทรงคํานวณวาระแห่งราชอาณาจักรของพระองค์ไว้แล้ว และทรงนําราชอาณาจักรนั้นมาถึงสิ้นสุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 27, 'เทเคล พระองค์ได้ถูกชั่งในตราชู ทรงเห็นว่ายังขาดอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 28, 'เปเรส ราชอาณาจักรของพระองค์ถูกแบ่งออกให้แก่คนมีเดีย และคนเปอร์เซีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 29, 'แล้วเบลชัสซาร์ก็ทรงบัญชาและเขาได้ให้ดาเนียลสวมเสื้อสีม่วง และให้สวมสร้อยคอทองคํา และทรงให้ประกาศเกี่ยวกับเรื่องของท่านว่า ท่านได้เป็นอุปราชตรีในราชอาณาจักร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 30, 'ในคืนวันนั้นเอง เบลชัสซาร์กษัตริย์คนเคลเดียก็ทรงถูกประหาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 31, 'และดาริอัสคนมีเดียก็ทรงรับราชอาณาจักร มีพระชนมายุหกสิบสองพรรษา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 1, 'ดาริอัสพอพระทัยที่จะทรงแต่งตั้งอุปราชหนึ่งร้อยยี่สิบคนขึ้นเหนือราชอาณาจักร เพื่อจะให้ปกครองอยู่ทั่วราชอาณาจักร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 2, 'และทรงตั้งอภิรัฐมนตรีสามคนอยู่เหนือ มีดาเนียลเป็นอภิรัฐมนตรีคนแรก เพื่อให้อุปราชรายงานติดต่อกับพวกเขา เพื่อกษัตริย์จะมิได้ทรงขาดประโยชน์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 3, 'แล้วดาเนียลคนนี้ก็มีชื่อเสียงกว่าอภิรัฐมนตรีอื่นๆและอุปราช เพราะวิญญาณดีเลิศสถิตกับท่าน และกษัตริย์ก็ทรงหมายพระทัยจะทรงแต่งตั้งท่านให้ครอบครองเหนือราชอาณาจักรนั้นทั้งหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 4, 'อภิรัฐมนตรีและอุปราชทั้งหลายจึงหามูลเหตุฟ้องดาเนียลในเรื่องเกี่ยวกับราชอาณาจักร แต่ก็หามูลเหตุหรือความผิดไม่ได้ เพราะท่านเป็นคนสัตย์ซื่อ จะหาความพลั้งพลาดหรือความผิดในท่านมิได้เลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 5, 'คนเหล่านี้จึงกล่าวว่า “เราจะหามูลเหตุฟ้องดาเนียลไม่ได้เลย นอกจากเราจะหาเรื่องที่เกี่ยวกับพระราชบัญญัติแห่งพระเจ้าของเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 6, 'แล้วอภิรัฐมนตรีและอุปราชเหล่านี้ได้พากันเข้าเฝ้ากษัตริย์ทูลว่า “ข้าแต่กษัตริย์ดาริอัส ขอทรงพระเจริญเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 7, 'บรรดาอภิรัฐมนตรีแห่งราชอาณาจักร ทั้งข้าหลวงภาค และอุปราช มนตรีและผู้ว่าราชการเมืองทั้งหลายทั้งสิ้นได้ตกลงกันว่า กษัตริย์สมควรจะได้ทรงตรากฎหมายและออกพระราชกฤษฎีกาว่า ในสามสิบวันนี้ถ้าผู้หนึ่งผู้ใดทูลขอต่อพระเจ้าหรือมนุษย์นอกเหนือพระองค์ โอ ข้าแต่กษัตริย์ ก็ให้โยนผู้นั้นลงในถ้ําสิงโตเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 8, 'โอ ข้าแต่กษัตริย์ บัดนี้ขอพระองค์ออกพระราชกฤษฎีกา และลงพระนามในหนังสือสําคัญเพื่อจะเปลี่ยนแปลงไม่ได้ ตามกฎหมายของคนมีเดียและคนเปอร์เซีย ซึ่งจะแก้ไขหาได้ไม่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 9, 'เพราะฉะนั้นกษัตริย์ดาริอัสจึงทรงลงพระนามในหนังสือสําคัญและพระราชกฤษฎีกา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 10, 'เมื่อดาเนียลทราบว่าลงพระนามในหนังสือสําคัญนั้นแล้ว ท่านก็ไปยังเรือนของท่าน ที่มีหน้าต่างห้องชั้นบนของท่านเปิดตรงไปยังกรุงเยรูซาเล็ม และท่านก็คุกเข่าลงวันละสามครั้ง อธิษฐานและโมทนาพระคุณต่อพระพักตร์พระเจ้าของท่าน ดังที่ท่านได้เคยกระทํามาแต่ก่อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 11, 'แล้วคนเหล่านี้ก็ได้พากันมาและได้พบดาเนียลอธิษฐานและวิงวอนอยู่ต่อพระพักตร์พระเจ้าของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 12, 'แล้วเขาทั้งหลายก็เข้าไปใกล้กราบทูลต่อพระพักตร์กษัตริย์เกี่ยวด้วยพระราชกฤษฎีกาของกษัตริย์ว่า “ข้าแต่กษัตริย์ พระองค์ได้ทรงลงพระนามในพระราชกฤษฎีกาฉบับหนึ่งมิใช่หรือว่า ถ้าผู้หนึ่งผู้ใดทูลขอต่อพระเจ้าหรือมนุษย์นอกเหนือพระองค์ในสามสิบวันนี้ โอ ข้าแต่กษัตริย์ ก็ให้โยนผู้นั้นลงไปในถ้ําสิงโตเสีย” กษัตริย์ตรัสตอบว่า “เรื่องนั้นยังคงอยู่ตามกฎหมายของคนมีเดียและคนเปอร์เซียซึ่งจะแก้ไขหาได้ไม่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 13, 'แล้วเขาจึงกราบทูลต่อพระพักตร์กษัตริย์ว่า “ดาเนียลคนนั้นในพวกที่ถูกกวาดเป็นเชลยมาจากยูดาห์ หาได้เชื่อฟังพระองค์ไม่ โอ ข้าแต่กษัตริย์ และไม่เชื่อฟังพระราชกฤษฎีกาซึ่งพระองค์ทรงลงพระนามไว้ แต่ได้ทูลขอวันละสามครั้ง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 14, 'เมื่อกษัตริย์ทรงสดับถ้อยคําเหล่านี้แล้ว ก็ทรงโทมนัสยิ่งนัก และทรงตั้งพระทัยหาทางช่วยดาเนียลให้พ้น ทรงหาหนทางช่วยดาเนียลให้รอดพ้นจนถึงเวลาดวงอาทิตย์ตก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 15, 'แล้วคนเหล่านั้นก็พากันมาเข้าเฝ้ากษัตริย์และกราบทูลกษัตริย์ว่า “โอ ข้าแต่กษัตริย์ ขอพระองค์พึงทราบว่า กฎหมายของคนมีเดียและคนเปอร์เซียว่า พระราชกฤษฎีกาก็ดีหรือกฎหมายก็ดีซึ่งกษัตริย์ทรงประทับตราแล้วย่อมเปลี่ยนแปลงไม่ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 16, 'แล้วกษัตริย์จึงทรงบัญชา เขาก็นําดาเนียลมาทิ้งในถ้ําสิงโต กษัตริย์ตรัสแก่ดาเนียลว่า “พระเจ้าของท่าน ผู้ซึ่งท่านปรนนิบัติอยู่เนืองนิตย์นั้น พระองค์จะทรงช่วยท่านให้รอดพ้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 17, 'แล้วเขานําศิลาก้อนหนึ่งมาปิดปากถ้ําไว้ กษัตริย์ก็ได้ทรงประทับตราของพระองค์และตราของเจ้านายของพระองค์ เพื่อว่าจะไม่มีสิ่งใดอันเกี่ยวกับดาเนียลเปลี่ยนแปลงไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 18, 'แล้วกษัตริย์ก็เสด็จกลับพระราชวัง ทรงอดพระกระยาหารตลอดคืนนั้น ไม่ให้นําเครื่องดนตรีอันใดมาหน้าพระที่ และบรรทมไม่หลับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 19, 'พอเช้าตรู่ กษัตริย์ก็ลุกขึ้นรีบเสด็จไปยังถ้ําสิงโต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 20, 'เมื่อพระองค์เสด็จมาใกล้ถ้ํานั้น พระองค์ก็ตรัสเรียกดาเนียลด้วยเสียงโทมนัส กษัตริย์ตรัสกับดาเนียลว่า “โอ ดาเนียล ผู้รับใช้ของพระเจ้าผู้ทรงพระชนม์อยู่ พระเจ้าของท่านซึ่งท่านปรนนิบัติอยู่เนืองนิตย์นั้น ทรงสามารถที่จะช่วยท่านให้พ้นจากสิงโตได้แล้วหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 21, 'แล้วดาเนียลกราบทูลกษัตริย์ว่า “โอ ข้าแต่กษัตริย์ ขอทรงพระเจริญเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 22, 'พระเจ้าของข้าพระองค์ทรงใช้ทูตสวรรค์ของพระองค์มาปิดปากสิงโตไว้ มันมิได้ทําอันตรายแก่ข้าพระองค์ เพราะพระองค์ทรงเห็นว่าข้าพระองค์ไร้ความผิดต่อพระพักตร์พระองค์ โอ ข้าแต่กษัตริย์ ข้าพระองค์มิได้กระทําผิดประการใดต่อพระพักตร์พระองค์ด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 23, 'ฝ่ายกษัตริย์ก็โสมนัสในพระทัยเป็นล้นพ้น และทรงบัญชาให้นําดาเนียลขึ้นมาจากถ้ํา เขาจึงเอาดาเนียลขึ้นมาจากถ้ํา ไม่ปรากฏว่ามีอันตรายอย่างไรบนตัวท่านเลย เพราะท่านได้เชื่อในพระเจ้าของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 24, 'แล้วกษัตริย์ทรงบัญชาให้นําคนเหล่านั้นที่ฟ้องดาเนียลมาโยนทิ้งในถ้ําสิงโต ทั้งตัวเขา บุตรทั้งหลายของเขา และภรรยาของเขาทั้งหลายด้วย และก่อนที่เขาตกลงไปถึงพื้นถ้ํา สิงโตก็ได้ฟัดเขาอยู่เสียแล้ว และหักกระดูกของเขาทั้งหลายเป็นชิ้นๆไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 25, 'แล้วกษัตริย์ดาริอัสทรงมีพระราชสารไปถึงบรรดาชนชาติ ประชาชาติทั้งปวง และภาษาทั้งหลายที่อาศัยอยู่ในพิภพทั้งสิ้นว่า “สันติสุขจงมีแก่ท่านทั้งหลายอย่างทวีคูณ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 26, 'เราออกกฤษฎีกาว่า ให้คนทั้งหลายสั่นสะท้านและยําเกรงต่อพระพักตร์พระเจ้าของดาเนียลในราชอาณาจักรของเราทั้งหมด เพราะพระองค์ทรงเป็นพระเจ้าผู้ทรงพระชนม์อยู่ ทรงดํารงอยู่เป็นนิตย์ อาณาจักรของพระองค์จะไม่ถูกทําลาย และราชอาณาจักรของพระองค์จะดํารงจนถึงที่สุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 27, 'พระองค์ทรงช่วยให้พ้นและช่วยให้พ้นภัย พระองค์ทรงกระทําหมายสําคัญและการมหัศจรรย์ในฟ้าสวรรค์และบนพื้นพิภพ พระองค์คือพระผู้ช่วยดาเนียลให้พ้นจากฤทธิ์ของสิงโต”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 28, 'ดังนั้น ดาเนียลผู้นี้จึงได้เจริญขึ้นในรัชสมัยของดาริอัส และในรัชสมัยของไซรัสคนเปอร์เซีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 1, 'ในปีต้นแห่งรัชกาลเบลชัสซาร์กษัตริย์เมืองบาบิโลน ดาเนียลมีความฝันและนิมิตผุดขึ้นในศีรษะของท่านเมื่อท่านนอนอยู่ในที่นอนของท่าน ท่านจึงบันทึกความฝันนั้นไว้ และบรรยายเนื้อเรื่องนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 2, 'ดาเนียลกล่าวว่า “ข้าพเจ้าได้เห็นในนิมิตเวลากลางคืน และดูเถิด ลมทั้งสี่ของฟ้าสวรรค์ได้ปลุกปั่นทะเลใหญ่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 3, 'และสัตว์มหึมาสี่ตัวได้ขึ้นมาจากทะเล แต่ละตัวก็ต่างกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 4, 'ตัวแรกเหมือนสิงโต มีปีกนกอินทรี เมื่อข้าพเจ้ามองดูนั้น ขนปีกก็ถูกถอนออกไป และมันถูกยกขึ้นจากแผ่นดิน และให้ยืนสองเท้าเหมือนคน และมอบใจของมนุษย์ให้แก่มัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 5, 'และดูเถิด มีสัตว์อีกตัวหนึ่งเป็นตัวที่สองเหมือนหมี มันขยับตัวข้างหนึ่งขึ้น มีกระดูกซี่โครงสามซี่อยู่ในปากของมันระหว่างซี่ฟัน มีเสียงบอกมันว่า ‘จงลุกขึ้นกินเนื้อให้มากๆ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 6, 'ต่อจากนี้ไปข้าพเจ้าก็ได้มองดู ดูเถิด สัตว์อีกตัวหนึ่งเหมือนเสือดาว บนหลังมีปีกนกสี่ปีก สัตว์นั้นมีหัวสี่หัวและมันรับราชอํานาจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 7, 'ต่อจากนี้ไปข้าพเจ้าได้เห็นในนิมิตกลางคืน และดูเถิด สัตว์ที่สี่มันร้ายกาจและเป็นที่น่ากลัวและแข็งแรงยิ่งนัก มันมีฟันเหล็กมหึมา มันกินและหักเป็นชิ้นๆ และกระทืบสิ่งที่เหลือนั้นเสีย มันต่างกับสัตว์อื่นทั้งหลายที่อยู่ก่อนมัน มันมีเขาสิบเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 8, 'ข้าพเจ้าพิเคราะห์เรื่องเขาเหล่านั้น ดูเถิด มีอีกเขาหนึ่งเล็กๆงอกขึ้นมาท่ามกลางเขาเหล่านั้น เขารุ่นแรกสามเขาได้ถูกถอนรากออกไปต่อหน้ามัน และดูเถิด ในเขาอันนี้มีตาเหมือนตามนุษย์ มีปากพูดเรื่องใหญ่โต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 9, 'ขณะที่ข้าพเจ้าดูอยู่มีหลายบัลลังก์ถูกล้มลง และผู้หนึ่งผู้เจริญด้วยวัยวุฒิมาประทับ ฉลองพระองค์ขาวอย่างหิมะ พระเกศาที่พระเศียรของพระองค์เหมือนขนแกะบริสุทธิ์ พระบัลลังก์ของพระองค์เป็นเปลวเพลิง กงจักรของบัลลังก์นั้นเป็นไฟลุก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 10, 'ธารไฟพุ่งออกและไหลออกมาต่อเบื้องพระพักตร์พระองค์ คนนับแสนๆปรนนิบัติพระองค์ คนนับโกฏิๆเข้าเฝ้าพระองค์ ผู้พิพากษาก็ขึ้นนั่งบัลลังก์ บรรดาหนังสือก็เปิดขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 11, 'ข้าพเจ้าก็จ้องดู เพราะเสียงพูดใหญ่โตของเขาเล็กนั้น และเมื่อข้าพเจ้าจ้องดูสัตว์ตัวนั้นก็ถูกฆ่า และศพก็ถูกทําลาย มอบให้เผาเสียด้วยไฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 12, 'ส่วนเรื่องสัตว์ที่เหลืออยู่นั้น ราชอํานาจของมันก็ถูกนําไปเสีย แต่ชีวิตของมันนั้นยังอยู่ต่อไปให้ถึงฤดูหนึ่งและวาระหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 13, 'ข้าพเจ้าเห็นในนิมิตกลางคืน และดูเถิด มีท่านผู้หนึ่งเหมือนบุตรมนุษย์มาพร้อมกับบรรดาเมฆในท้องฟ้า และท่านมาหาผู้เจริญด้วยวัยวุฒินั้น เขานําท่านมาเฝ้าต่อเบื้องพระพักตร์พระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 14, 'ราชอํานาจ สง่าราศี กับราชอาณาจักร ก็ได้มอบให้แก่ท่าน เพื่อบรรดาชนชาติ ประชาชาติทั้งปวงและภาษาทั้งหลายจะปรนนิบัติท่าน ราชอาณาจักรของท่านเป็นราชอาณาจักรนิรันดร์ซึ่งจะไม่สิ้นสุดไป และอาณาจักรของท่านเป็นอาณาจักรซึ่งจะไม่ถูกทําลายเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 15, 'ส่วนข้าพเจ้า คือดาเนียล จิตใจข้าพเจ้าก็เป็นทุกข์ในตัวข้าพเจ้า เพราะนิมิตในศีรษะของข้าพเจ้าก็กระทําให้ข้าพเจ้าตกใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 16, 'ข้าพเจ้าเข้าไปใกล้ท่านผู้หนึ่งที่ยืนอยู่ที่นั่น และไต่ถามความจริงของเรื่องราวนี้ ท่านก็บอกข้าพเจ้า และให้ข้าพเจ้ารู้ความหมายของเรื่องเหล่านี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 17, 'สัตว์มหึมาทั้งสี่คือ กษัตริย์สี่องค์ซึ่งจะเกิดมาจากพิภพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 18, 'แต่บรรดาวิสุทธิชนแห่งองค์ผู้สูงสุดจะรับราชอาณาจักร และถือกรรมสิทธิ์ราชอาณาจักรนั้นสืบๆไปเป็นนิตย์ คือเป็นนิตย์นิรันดร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 19, 'แล้วข้าพเจ้าก็อยากจะทราบถึงความจริงอันเกี่ยวกับสัตว์ตัวที่สี่นั้นซึ่งผิดแปลกกับสัตว์อื่นๆทั้งสิ้น ร้ายกาจเหลือเกิน มีฟันเหล็กและเล็บตีนทองเหลือง ซึ่งกินและหักเป็นชิ้นๆและกระทืบสิ่งที่เหลือนั้นเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 20, 'และเกี่ยวกับเขาสิบเขาซึ่งอยู่บนหัวของมัน และเขาอีกเขาหนึ่งซึ่งงอกขึ้นมาต่อหน้าเขารุ่นแรกสามเขาที่หลุดไป เขาซึ่งมีตาและมีปากซึ่งพูดสิ่งใหญ่โต และซึ่งดูเหมือนจะใหญ่โตกว่าเพื่อนเขาด้วยกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 21, 'เมื่อข้าพเจ้ามองดู เขานี้ทําสงครามกับวิสุทธิชนและชนะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 22, 'จนถึงผู้เจริญด้วยวัยวุฒิเสด็จมาถึงและทรงให้มีการพิพากษาให้แก่วิสุทธิชนขององค์ผู้สูงสุดนั้น และจนสมัยเมื่อวิสุทธิชนรับราชอาณาจักรมาถึง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 23, 'ท่านผู้นั้นกล่าวดังนี้ว่า ‘เรื่องสัตว์ตัวที่สี่จะมีราชอาณาจักรที่สี่บนพิภพซึ่งจะผิดกับราชอาณาจักรทั้งสิ้น และจะกินทั้งพิภพนี้เสียและเหยียบพิภพลง และหักพิภพนั้นให้แตกออกเป็นชิ้นๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 24, 'ส่วนเรื่องเขาสิบเขานั้นจากราชอาณาจักรนี้จะมีกษัตริย์สิบองค์เกิดขึ้น และมีกษัตริย์อีกองค์หนึ่งเกิดขึ้นภายหลัง ผิดแปลกกว่ากษัตริย์ที่มีมาก่อน และจะโค่นกษัตริย์เสียสามองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 25, 'ท่านจะพูดคํากล่าวร้ายองค์ผู้สูงสุด และจะให้วิสุทธิชนขององค์ผู้สูงสุดนั้นอิดหนาระอาใจ และจะคิดเปลี่ยนแปลงบรรดาวาระและพระราชบัญญัติ และเขาทั้งหลายจะถูกมอบไว้ในมือของท่าน ตลอดหนึ่งวาระ สองวาระ กับครึ่งวาระ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 26, 'แต่ผู้พิพากษาก็จะขึ้นนั่งบัลลังก์และจะทรงนําเอาราชอาณาจักรของท่านไปเสีย เพื่อจะทรงเผาผลาญและทําลายเสียให้สิ้นสุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 27, 'และอาณาจักรกับราชอาณาจักรและความยิ่งใหญ่แห่งบรรดาอาณาจักรภายใต้สวรรค์ทั้งสิ้น จะต้องถูกมอบไว้แก่ชุมนุมแห่งวิสุทธิชนขององค์ผู้สูงสุดนั้น อาณาจักรของท่านจะเป็นอาณาจักรนิรันดร์ และราชอาณาจักรทั้งสิ้นจะปรนนิบัติและเชื่อฟังท่าน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 28, 'เรื่องราวก็สิ้นสุดลงเพียงนี้ ส่วนข้าพเจ้าคือดาเนียล ความคิดของข้าพเจ้าก็ทําให้ข้าพเจ้าตกใจมาก และสีหน้าของข้าพเจ้าก็เปลี่ยนไป แต่ข้าพเจ้าก็เก็บเรื่องราวนี้ไว้ในใจ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 1, 'ในปีที่สามแห่งรัชกาลกษัตริย์เบลชัสซาร์ มีนิมิตปรากฏแก่ข้าพเจ้าดาเนียล หลังจากนิมิตที่ปรากฏแก่ข้าพเจ้าครั้งแรกนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 2, 'และข้าพเจ้าเห็นเป็นนิมิต ต่อมาขณะที่ข้าพเจ้าอยู่ที่สุสาปราสาท ซึ่งอยู่ในแขวงเมืองเอลาม และข้าพเจ้าก็เห็นเป็นนิมิต และข้าพเจ้าอยู่ริมแม่น้ําอุลัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 3, 'ข้าพเจ้าเงยหน้าขึ้นเห็น และดูเถิด แกะผู้ตัวหนึ่งยืนอยู่ที่ฝั่งแม่น้ํา มีเขาสองเขา เขาทั้งสองสูง แต่เขาหนึ่งสูงกว่าอีกเขาหนึ่ง และเขาที่สูงนั้นงอกมาทีหลัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 4, 'ข้าพเจ้าเห็นแกะผู้นั้นขวิดไปทางตะวันตก และทางเหนือและทางใต้ ไม่มีสัตว์ตัวใดต้านทานมันได้ และไม่มีใครที่จะช่วยให้พ้นจากมือของมันได้ มันทําตามชอบใจของมันและก็พองตัวขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 5, 'เมื่อข้าพเจ้ากําลังตรึกตรองอยู่ ดูเถิด มีแพะผู้ตัวหนึ่งมาจากทิศตะวันตก เหาะข้ามพื้นพิภพทั้งสิ้นมา ไม่แตะต้องพื้นดินเลย และแพะนั้นมีเขาเด่นอยู่ในระหว่างตาของมันเขาหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 6, 'มันมาหาแกะผู้ที่มีเขาสองเขาซึ่งข้าพเจ้าเห็นยืนอยู่ที่ฝั่งแม่น้ํา มันวิ่งเข้าใส่แกะผู้ตัวนั้นด้วยเต็มกําลังความโกรธของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 7, 'ข้าพเจ้าเห็นมันเข้ามาใกล้แกะผู้ มันโกรธและเข้าชนแกะผู้ ทําให้เขาทั้งสองของมันหักไป และแกะผู้ก็ไม่มีกําลังต้านทานมันได้ มันเหวี่ยงแกะผู้ลงที่ดินและเหยียบเสีย และไม่มีใครช่วยแกะผู้ให้พ้นมือของมันได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 8, 'แล้วแพะผู้ก็พองตัวขึ้นอย่างยิ่ง แต่เมื่อมันแข็งแรง เขาใหญ่ของมันก็หัก มีเขาเด่นอีกสี่เขางอกขึ้นแทนที่ หันไปทางทิศลมทั้งสี่ของฟ้าสวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 9, 'และมีเขาเล็กๆเขาหนึ่งงอกออกมาจากเขาหนึ่งในพวกเขาเหล่านี้ ซึ่งงอกขึ้นใหญ่โตเหลือเกิน ตรงไปทางใต้ ตรงไปทางตะวันออก และตรงไปยังแผ่นดินอันรุ่งโรจน์นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 10, 'มันงอกขึ้นใหญ่โต แม้กระทั่งถึงบริวารแห่งฟ้าสวรรค์ มันยังเหวี่ยงบริวารกับดวงดาวลงมายังพิภพเสียบ้าง แล้วเหยียบย่ําเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 11, 'มันพองตัวขึ้นอีก แม้กระทั่งถึงจอมของบริวาร และเครื่องเผาบูชาประจําวันก็ถูกชิงไปเสีย และสถานบริสุทธิ์ของพระองค์ก็ถูกเหวี่ยงลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 12, 'และเพราะเหตุการละเมิด เขาได้รับมอบบริวารไว้สู้กับการเผาบูชาประจําวัน และความจริงก็ถูกเหวี่ยงลงที่ดิน และเขานั้นก็ปฏิบัติงานและเจริญขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 13, 'แล้วข้าพเจ้าได้ยินวิสุทธิชนผู้หนึ่งพูดอยู่ วิสุทธิชนอีกผู้หนึ่งก็พูดกับวิสุทธิชนผู้ที่พูดอยู่นั้นว่า “นิมิตที่เกี่ยวข้องกับเครื่องเผาบูชาประจําวันนั้นจะอยู่อีกนานเท่าใด ทั้งเรื่องการละเมิดที่ทําให้เกิดการรกร้างว่างเปล่า เพื่อจะมอบทั้งสถานบริสุทธิ์และบริวารให้ถูกเหยียบย่ําลงใต้ฝ่าเท้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 14, 'ท่านผู้นั้นตอบข้าพเจ้าว่า “อยู่นานสองพันสามร้อยวัน แล้วสถานบริสุทธิ์นั้นจะได้รับการชําระ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 15, 'และอยู่มาเมื่อข้าพเจ้าดาเนียลได้เห็นนิมิตนั้นแล้ว ข้าพเจ้าก็พยายามเข้าใจ และดูเถิด มีเหมือนมนุษย์ยืนอยู่หน้าข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 16, 'และข้าพเจ้าได้ยินเสียงของชายผู้หนึ่งระหว่างฝั่งแม่น้ําอุลัย และเสียงนั้นร้องเรียกและกล่าวว่า “กาเบรียลเอ๋ย จงทําให้ชายผู้นี้เข้าใจในนิมิตนั้นเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 17, 'ดังนั้นท่านจึงมาใกล้ที่ที่ข้าพเจ้ายืนอยู่ และเมื่อท่านมาแล้ว ข้าพเจ้าก็ตกใจซบหน้าลงถึงดิน แต่ท่านกล่าวแก่ข้าพเจ้าว่า “โอ บุตรแห่งมนุษย์เอ๋ย จงเข้าใจเถิดว่า นิมิตนั้นเป็นเรื่องของกาลอวสาน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 18, 'เมื่อท่านกําลังพูดอยู่กับข้าพเจ้า ข้าพเจ้าก็สลบหน้าติดดินอยู่ แต่ท่านแตะต้องข้าพเจ้าให้ข้าพเจ้ายืนขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 19, 'ท่านกล่าวว่า “ดูเถิด ข้าพเจ้าจะทําให้ท่านทราบถึงสิ่งซึ่งจะเกิดขึ้นในตอนปลายแห่งพระพิโรธ เพราะมันเกี่ยวข้องกับวาระกําหนดแห่งอวสาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 20, 'เรื่องแกะผู้มีสองเขาที่ท่านเห็นนั้นคือ กษัตริย์ของคนมีเดียและคนเปอร์เซีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 21, 'และแพะผู้คือกษัตริย์ของกรีก และเขาใหญ่ระหว่างนัยน์ตา คือกษัตริย์องค์แรก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 22, 'ส่วนเขาที่หัก และมีอีกสี่เขางอกขึ้นแทนนั้น คืออาณาจักรสี่อาณาจักรจะเกิดขึ้นจากประชาชาตินั้น แต่ไม่มีอํานาจเหนือเขาแรกนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 23, 'และในตอนปลายแห่งรัชสมัยของพวกเขา เมื่อผู้ละเมิดทั้งหลายได้กระทําเต็มขนาดแล้ว จะมีกษัตริย์องค์หนึ่งพระพักตร์ดุร้าย และมีความเข้าใจในเรื่องปริศนาเกิดขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 24, 'อํานาจของท่านจะใหญ่โตมาก แต่มิใช่โดยอํานาจของท่านเอง และท่านจะกระทําให้บังเกิดความพินาศอย่างน่ากลัว ท่านก็เจริญขึ้นและปฏิบัติงาน ท่านจะทําลายคนที่มีกําลังมากและประชาชนบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 25, 'ด้วยความฉลาดของท่าน ท่านจะกระทําให้การล่อลวงแพร่หลายขึ้นด้วยน้ํามือของท่าน ท่านจะพองตัวของท่านในใจของท่านเอง ท่านจะทําลายคนมากหลายโดยความสงบ แล้วจะลุกขึ้นต่อสู้กับจอมเจ้านาย แต่ท่านจะต้องถูกหักทําลาย ไม่ใช่ด้วยมือเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 26, 'นิมิตเรื่องเวลาเย็นและเวลาเช้าซึ่งบอกเล่านั้นเป็นความจริง แต่จงปิดบังนิมิตนั้นไว้เถอะ เพราะเป็นเรื่องของอีกหลายวันข้างหน้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 27, 'และข้าพเจ้าดาเนียลก็อ่อนเพลีย และนอนเจ็บอยู่หลายวัน แล้วข้าพเจ้าก็ลุกขึ้นไปปฏิบัติราชการของกษัตริย์ต่อไป แต่ข้าพเจ้าก็งงงันโดยนิมิตนั้น และไม่เข้าใจเรื่องราวเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 1, 'ในปีต้นรัชกาลดาริอัส โอรสกษัตริย์อาหสุเอรัส เชื้อสายคนมีเดีย ผู้ได้เป็นกษัตริย์เหนือดินแดนเคลเดีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 2, 'ในปีแรกแห่งรัชกาลของท่าน ข้าพเจ้าดาเนียลได้เข้าใจถึงจํานวนปีจากหนังสือ ซึ่งพระวจนะของพระเยโฮวาห์ได้มีมาถึงเยเรมีย์ผู้พยากรณ์ว่า พระองค์จะทรงกระทําให้ครบกําหนดเจ็ดสิบปีในการรกร้างของกรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 3, 'แล้วข้าพเจ้าก็หันหน้าไปหาองค์พระผู้เป็นเจ้าพระเจ้า แสวงหาด้วยการอธิษฐานและการวิงวอน ทั้งด้วยการอดอาหาร และนุ่งห่มผ้ากระสอบและนั่งบนมูลเถ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 4, 'ข้าพเจ้าได้อธิษฐานต่อพระเยโฮวาห์พระเจ้าของข้าพเจ้าและสารภาพว่า “โอ ข้าแต่องค์พระผู้เป็นเจ้า พระเจ้าผู้ใหญ่ยิ่งและที่น่าสะพรึงกลัว ผู้ทรงรักษาพันธสัญญาและความเมตตาต่อผู้ที่รักพระองค์และรักษาพระบัญญัติของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 5, 'ข้าพระองค์ทั้งหลายได้กระทําบาป และได้กระทําความชั่วช้า และได้ประกอบความชั่วและการกบฏ หันเสียจากข้อบังคับและคําตัดสินของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 6, 'ข้าพระองค์มิได้ฟังบรรดาผู้พยากรณ์ ผู้รับใช้ของพระองค์ ผู้กล่าวในพระนามของพระองค์ต่อกษัตริย์ของข้าพระองค์ทั้งหลาย ทั้งต่อเจ้านาย บรรพบุรุษและประชาชนทั้งสิ้นแห่งแผ่นดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 7, 'โอ ข้าแต่องค์พระผู้เป็นเจ้า ความชอบธรรมเป็นของพระองค์ แต่ความขายหน้าควรแก่พวกข้าพระองค์ ดังทุกวันนี้ ที่ควรแก่คนยูดาห์ ชาวกรุงเยรูซาเล็ม และอิสราเอลทั้งหมด ทั้งผู้ที่อยู่ใกล้และอยู่ไกลออกไป ในแผ่นดินทั้งหลายซึ่งพระองค์ทรงขับไล่เขาไปนั้น เพราะความละเมิดซึ่งเขาได้กระทําต่อพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 8, 'โอ ข้าแต่องค์พระผู้เป็นเจ้า ความขายหน้าควรแก่พวกข้าพระองค์ แก่กษัตริย์ของข้าพระองค์ทั้งหลาย เจ้านาย และบรรพบุรุษ เพราะข้าพระองค์ทั้งหลายได้กระทําบาปต่อพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 9, 'พระกรุณา และการอภัยโทษเป็นขององค์พระผู้เป็นเจ้าพระเจ้าของข้าพระองค์ทั้งหลาย ถึงแม้ข้าพระองค์ทั้งหลายได้กบฏต่อพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 10, 'และมิได้เชื่อฟังพระสุรเสียงของพระเยโฮวาห์พระเจ้าของข้าพระองค์ ด้วยการดําเนินตามพระราชบัญญัติของพระองค์ ซึ่งพระองค์ทรงตั้งไว้ต่อหน้าข้าพระองค์ทั้งหลาย โดยบรรดาผู้พยากรณ์ผู้รับใช้ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 11, 'เออ อิสราเอลทั้งผองได้ละเมิดต่อพระราชบัญญัติของพระองค์ และได้หันไปเสียไม่เชื่อฟังพระสุรเสียงของพระองค์ และการสาปแช่งและการปฏิญาณ ซึ่งจารึกไว้ในพระราชบัญญัติของโมเสสผู้รับใช้ของพระเจ้า จึงถูกเทลงเหนือข้าพระองค์ทั้งหลาย เพราะว่าข้าพระองค์ทั้งหลายได้กระทําบาปต่อพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 12, 'พระองค์ได้ทรงยืนยันถ้อยคําของพระองค์ ซึ่งพระองค์ได้ตรัสกล่าวโทษข้าพระองค์ทั้งหลาย และกล่าวโทษผู้ปกครองซึ่งปกครองข้าพระองค์ โดยนําให้ข้าพระองค์เกิดวิบัติอย่างใหญ่หลวง เพราะว่าภายใต้สวรรค์ทั้งสิ้นไม่มีที่ใดที่ได้กระทําเหมือนที่ได้กระทําแก่เยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 13, 'ดังที่ได้จารึกไว้ในพระราชบัญญัติของโมเสสแล้ว วิบัติทั้งสิ้นก็ได้ตกอยู่เหนือข้าพระองค์ทั้งหลายแล้ว แต่ข้าพระองค์ทั้งหลายยังมิได้อธิษฐานต่อพระพักตร์พระเยโฮวาห์พระเจ้าของข้าพระองค์ทั้งหลาย โดยหันเสียจากความชั่วช้าของข้าพระองค์ และเข้าใจความจริงของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 14, 'เพราะฉะนั้นพระเยโฮวาห์ทรงเก็บความวิบัติไว้พร้อมและได้ทรงนํามาเหนือข้าพระองค์ทั้งหลาย เพราะพระเยโฮวาห์พระเจ้าของข้าพระองค์ทั้งหลายทรงเป็นผู้ชอบธรรมในสรรพกิจ ซึ่งพระองค์ได้ทรงกระทํา เพราะข้าพระองค์ทั้งหลายมิได้เชื่อฟังพระสุรเสียงของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 15, 'แล้วบัดนี้ โอ ข้าแต่องค์พระผู้เป็นเจ้าพระเจ้าของข้าพระองค์ทั้งหลาย ผู้ทรงนําชนชาติของพระองค์ออกจากแผ่นดินอียิปต์ด้วยพระหัตถ์อันทรงฤทธิ์ และได้ทําให้พระนามลือมาจนทุกวันนี้ ข้าพระองค์ทั้งหลายได้กระทําบาป และข้าพระองค์ทั้งหลายกระทําความชั่ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 16, 'โอ ข้าแต่องค์พระผู้เป็นเจ้า ตามความชอบธรรมทั้งสิ้นของพระองค์ ขอให้ความกริ้วและพระพิโรธของพระองค์หันกลับเสียจากเยรูซาเล็มนครของพระองค์ ภูเขาบริสุทธิ์ของพระองค์ เพราะบาปของข้าพระองค์ทั้งหลาย และความชั่วช้าของบรรพบุรุษของข้าพระองค์ทั้งหลาย เยรูซาเล็มและประชาชนของพระองค์จึงกลายเป็นที่เยาะเย้ยในหมู่คนทั้งสิ้นที่อยู่รอบข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 17, 'ฉะนั้น โอ ข้าแต่พระเจ้าของข้าพระองค์ทั้งหลาย บัดนี้ ขอทรงสดับฟังคําอธิษฐานของผู้รับใช้ของพระองค์ และคําวิงวอนของเขา และขอทรงให้พระพักตร์ของพระองค์ทอแสงเหนือสถานบริสุทธิ์ของพระองค์ซึ่งรกร้างนั้นเพื่อเห็นแก่องค์พระผู้เป็นเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 18, 'โอ ข้าแต่พระเจ้าของข้าพระองค์ ขอทรงเงี่ยพระกรรณสดับฟัง ขอทรงลืมพระเนตรดูความรกร้างของข้าพระองค์ทั้งหลาย ทั้งนครซึ่งเรียกขานกันตามพระนามของพระองค์ เพราะว่าข้าพระองค์ทั้งหลายมิได้ถวายคําวิงวอนต่อพระพักตร์พระองค์ โดยอาศัยความชอบธรรมของข้าพระองค์ทั้งหลาย แต่โดยอาศัยพระเมตตาอันยิ่งใหญ่ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 19, 'โอ ข้าแต่องค์พระผู้เป็นเจ้า ขอทรงฟัง โอ ข้าแต่องค์พระผู้เป็นเจ้า ขอทรงให้อภัย โอ ข้าแต่องค์พระผู้เป็นเจ้า ขอทรงใส่พระทัยและทรงกระทํา ขออย่าเนิ่นช้าเลยพระเจ้าข้า เพื่อเห็นแก่พระนามของพระองค์ โอ ข้าแต่พระเจ้าของข้าพระองค์ เพราะว่านครของพระองค์ และประชาชนของพระองค์ก็มีชื่อตามพระนามของพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 20, 'ขณะที่ข้าพเจ้ากําลังพูด กําลังอธิษฐานและสารภาพบาปของข้าพเจ้าและบาปของอิสราเอลประชาชนของข้าพเจ้า และเสนอคําวิงวอนของข้าพเจ้าต่อพระพักตร์พระเยโฮวาห์พระเจ้าของข้าพเจ้า เพื่อภูเขาบริสุทธิ์แห่งพระเจ้าของข้าพเจ้าอยู่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 21, 'เออ ขณะเมื่อข้าพเจ้ากล่าวคําอธิษฐานอยู่ ชายชื่อกาเบรียล ซึ่งข้าพเจ้าได้เห็นในนิมิตครั้งแรกนั้น ได้บินอย่างเร็วมาใกล้ข้าพเจ้า แตะต้องข้าพเจ้าในเวลาถวายเครื่องบูชาตอนเย็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 22, 'ท่านได้ให้ความรู้และกล่าวแก่ข้าพเจ้าว่า “โอ ดาเนียล ข้าพเจ้าออกมา ณ บัดนี้ เพื่อจะให้ปัญญาและความเข้าใจแก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 23, 'ในตอนต้นแห่งคําวิงวอนของท่านก็มีพระบัญชาออกไป ข้าพเจ้าจึงมาบอกให้ท่านทราบเพราะท่านเป็นผู้ที่ทรงรักมาก เพราะฉะนั้นจงเข้าใจพระบัญชานั้นและพิจารณานิมิตนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 24, 'มีเจ็ดสิบสัปดาห์กําหนดไว้สําหรับชนชาติของท่าน และนครบริสุทธิ์ของท่าน เพื่อให้เสร็จสิ้นการละเมิด ให้บาปจบสิ้น และให้ลบความชั่วช้าเพื่อนําความชอบธรรมนิรันดร์เข้ามา เพื่อประทับตราทั้งนิมิตและคําพยากรณ์ไว้ และเพื่อจะเจิมสถานบริสุทธิ์ที่สุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 25, 'เพราะฉะนั้นจงทราบและเข้าใจว่า นับตั้งแต่การที่พระบัญชานั้นออกไปให้สร้างกรุงเยรูซาเล็มขึ้นใหม่ จนถึงสมัยพระเมสสิยาห์ ผู้เป็นประมุขก็เป็นเวลาเจ็ดสัปดาห์และเป็นเวลาหกสิบสองสัปดาห์ และถนนจะถูกสร้างขึ้นพร้อมด้วยกําแพงเมือง แต่ในยุคลําบาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 26, 'หลังจากหกสิบสองสัปดาห์แล้ว พระเมสสิยาห์ก็จะถูกตัดออก แต่มิใช่เพื่อตัวท่านเอง และประชาชนของประมุขผู้หนึ่งที่จะมานั้นจะทําลายกรุงและสถานบริสุทธิ์เสีย ที่สุดปลายของมันจะมาถึงด้วยน้ําท่วม และจนสงครามสิ้นสุดลงก็มีการรกร้างกําหนดไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 27, 'ท่านจะยืนยันพันธสัญญากับคนเป็นอันมากอยู่หนึ่งสัปดาห์ และในระหว่างกลางสัปดาห์นั้นท่านจะกระทําให้การถวายสัตวบูชา และเครื่องบูชาอื่นๆหยุดไป และเพราะเหตุมีความสะอิดสะเอียนแพร่กระจายไปทั่ว ท่านจะกระทําให้มันร้างเปล่าจนสําเร็จเสร็จสิ้น และสิ่งที่กําหนดไว้จะถูกเทลงเหนือผู้ที่ร้างเปล่านั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 1, 'ในปีที่สามแห่งรัชกาลไซรัสกษัตริย์แห่งประเทศเปอร์เซีย มีอยู่สิ่งหนึ่งทรงสําแดงแก่ดาเนียล ผู้ได้ชื่อว่าเบลเทชัสซาร์ และสิ่งนั้นก็จริง แต่เวลาที่กําหนดไว้ก็อีกนาน ท่านเข้าใจสิ่งนั้นและมีความเข้าใจในนิมิตนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 2, 'ในคราวนั้น ข้าพเจ้าดาเนียลเป็นทุกข์อยู่สามสัปดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 3, 'ข้าพเจ้าไม่ได้รับประทานอาหารอร่อย เนื้อหรือน้ําองุ่นก็มิได้เข้าปากข้าพเจ้า ข้าพเจ้าไม่ได้ชโลมน้ํามันตัวเลยตลอดสามสัปดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 4, 'เมื่อวันที่ยี่สิบสี่เดือนต้นข้าพเจ้าอยู่ที่ฝั่งแม่น้ําใหญ่ คือแม่น้ําไทกริส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 5, 'ข้าพเจ้าแหงนขึ้นมอง ดูเถิด มีชายคนหนึ่งสวมเสื้อผ้าป่าน มีทองคําเนื้อดีเมืองอุฟาสคาดเอวไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 6, 'ร่างกายของท่านดั่งพลอยเขียว และหน้าของท่านก็เหมือนฟ้าแลบ ดวงตาของท่านก็เหมือนกับคบเพลิง แขนและเท้าเป็นสีเหมือนกับทองเหลืองขัด และเสียงถ้อยคําของท่านเหมือนเสียงมวลชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 7, 'และข้าพเจ้าดาเนียลเห็นนิมิตนั้นแต่ผู้เดียว คนที่อยู่กับข้าพเจ้ามิได้เห็นนิมิตนั้น แต่เขาตัวสั่นมากจึงวิ่งไปซ่อนเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 8, 'แล้วข้าพเจ้าอยู่แต่ลําพัง และข้าพเจ้าได้เห็นนิมิตใหญ่ยิ่งนี้ ข้าพเจ้าก็สิ้นเรี่ยวสิ้นแรง หน้าตาสุกใสของข้าพเจ้าก็เปลี่ยนเป็นหน้าซีด ข้าพเจ้าหมดแรง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 9, 'แล้วข้าพเจ้าจึงได้ยินเสียงถ้อยคําของท่าน และเมื่อข้าพเจ้าได้ยินเสียงถ้อยคํานั้น ข้าพเจ้าก็ซบหน้าลงสลบอยู่ หน้าของข้าพเจ้าฟุบกับดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 10, 'และดูเถิด มีมือมาแตะต้องข้าพเจ้า พยุงให้ข้าพเจ้ายันตัวด้วยฝ่ามือและเข่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 11, 'ท่านกล่าวแก่ข้าพเจ้าว่า “โอ ดาเนียล บุรุษผู้เป็นที่รักอย่างยิ่ง จงเข้าใจถ้อยคําที่เราพูดกับท่าน และยืนตรง เพราะบัดนี้ข้าพเจ้าได้รับใช้ให้มาหาท่าน” ขณะที่ท่านกล่าวคํานี้แก่ข้าพเจ้า ข้าพเจ้าก็ยืนสั่นสะท้านอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 12, 'แล้วท่านพูดกับข้าพเจ้าว่า “ดาเนียลเอ๋ย อย่ากลัวเลย เพราะตั้งแต่วันแรกที่ท่านได้ตั้งใจจะเข้าใจและถ่อมตัวลงต่อพระพักตร์พระเจ้าของท่านนั้น พระเจ้าทรงฟังถ้อยคําของท่าน และข้าพเจ้ามาด้วยเรื่องถ้อยคําของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 13, 'เจ้าผู้พิทักษ์ราชอาณาจักรเปอร์เซียได้ขัดขวางข้าพเจ้าไว้ถึงยี่สิบเอ็ดวัน ข้าพเจ้าจึงยังอยู่ที่นั่นกับกษัตริย์ทั้งหลายของเปอร์เซีย แต่ดูเถิด มีคาเอลเจ้าผู้พิทักษ์ชั้นหัวหน้าผู้หนึ่งมาช่วยข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 14, 'บัดนี้ข้าพเจ้ามากระทําให้ท่านเข้าใจถึงสิ่งซึ่งจะตกกับชนชาติของท่านในกาลภายหน้า เพราะนิมิตนั้นยังมีไว้สําหรับวันเวลาอีกเป็นอันมาก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 15, 'เมื่อท่านได้พูดตามถ้อยคําเหล่านี้กับข้าพเจ้าแล้ว ข้าพเจ้าก็ก้มหน้าสู่พื้นดินแล้วก็เป็นใบ้ไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 16, 'และดูเถิด มีท่านผู้หนึ่งสัณฐานคล้ายบุตรทั้งหลายของมนุษย์มาแตะริมฝีปากของข้าพเจ้า แล้วข้าพเจ้าก็อ้าปากขึ้นพูด ข้าพเจ้ากล่าวกับท่านที่ยืนอยู่ข้างหน้าข้าพเจ้าว่า “โอ นายเจ้าข้า ด้วยเหตุนิมิตนั้นความเจ็บปวดจึงเกิดกับข้าพเจ้า แล้วข้าพเจ้าก็หมดแรง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 17, 'ผู้รับใช้ของเจ้านายของข้าพเจ้าจะพูดกับเจ้านายของข้าพเจ้าได้อย่างไร เพราะบัดนี้ไม่มีกําลังเหลืออยู่ในข้าพเจ้าเลย ลมหายใจพรากไปจากข้าพเจ้าแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 18, 'ท่านผู้มีรูปร่างอย่างมนุษย์นั้นได้แตะต้องข้าพเจ้าอีกครั้งหนึ่ง และให้กําลังข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 19, 'ท่านกล่าวว่า “โอ บุรุษผู้เป็นที่รักอย่างยิ่ง อย่ากลัวเลย สันติภาพจงมีแก่ท่าน จงเข้มแข็ง เออ จงเข้มแข็งเถิด” เมื่อท่านพูดกับข้าพเจ้านั้น ข้าพเจ้ามีกําลังขึ้นและกล่าวว่า “ขอเจ้านายของข้าพเจ้าจงพูดไปเถิด เพราะท่านได้ให้กําลังข้าพเจ้าแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 20, 'แล้วท่านจึงกล่าวว่า “ท่านทราบหรือไม่ว่าข้าพเจ้ามาหาท่านทําไม แต่บัดนี้ข้าพเจ้าจะกลับไปต่อสู้กับเจ้าผู้พิทักษ์แห่งเปอร์เซีย และเมื่อข้าพเจ้าเสร็จธุระกับเขาแล้ว ดูเถิด เจ้าผู้พิทักษ์แห่งกรีกจะมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 21, 'แต่ข้าพเจ้าจะบอกท่านตามสิ่งซึ่งบันทึกไว้ในหนังสือแห่งความจริง ไม่มีผู้ใดร่วมแรงกับข้าพเจ้าต่อสู้เจ้าเหล่านี้เลย นอกจากมีคาเอล เจ้าผู้พิทักษ์ของท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 1, '“ส่วนตัวข้าพเจ้านั้น ในปีต้นแห่งรัชกาลดาริอัส คนมีเดีย ข้าพเจ้าเป็นตัวตั้งตัวตีที่ให้กําลังกษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 2, 'และบัดนี้ ข้าพเจ้าจะสําแดงความจริงให้แก่ท่าน ดูเถิด จะมีกษัตริย์อีกสามองค์ขึ้นมาในเปอร์เซีย และองค์ที่สี่จะร่ํารวยยิ่งกว่าองค์อื่นทั้งหมดเป็นอันมาก เมื่อท่านเข้มแข็งด้วยทรัพย์ร่ํารวยของท่านแล้ว ท่านก็จะปลุกปั่นให้ทุกคนต่อสู้กับราชอาณาจักรกรีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 3, 'แล้วจะมีกษัตริย์ที่มีอานุภาพมากขึ้นมา ท่านจะปกครองด้วยราชอํานาจยิ่งใหญ่ และกระทําตามความพอใจของท่านเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 4, 'และเมื่อท่านขึ้นมาแล้ว ราชอาณาจักรของท่านจะแตกและแบ่งแยกออกไปตามทางลมทั้งสี่แห่งฟ้าสวรรค์ แต่จะไม่ตกอยู่กับทายาทของท่าน และจะไม่มีราชอํานาจอย่างที่ท่านปกครองอยู่ เพราะว่าราชอาณาจักรของท่านจะถูกถอนขึ้น ตกไปเป็นของผู้อื่นนอกเหนือคนเหล่านี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 5, 'แล้วกษัตริย์แห่งถิ่นใต้จะเข้มแข็ง แต่เจ้านายของท่านองค์หนึ่งจะเข้มแข็งกว่าท่านและมีอํานาจ และราชอํานาจของท่านจะเป็นราชอํานาจมหึมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 6, 'ต่อมาอีกหลายปีเขาจะกระทําพันธมิตรกัน และบุตรสาวแห่งกษัตริย์ถิ่นใต้จะมาหากษัตริย์แห่งถิ่นเหนือเพื่อกระทําสันติภาพ แต่เธอก็ไม่กระทําให้กําลังแขนของเธอคงอยู่ได้ กษัตริย์และแขนของท่านจะไม่ยั่งยืน เธอจะถูกอายัดไว้ ทั้งผู้ที่นําเธอมา ผู้ที่ให้กําเนิดเธอ และผู้ที่ให้กําลังแก่เธอในกาลนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 7, 'จะมีกิ่งจากรากของเธอขึ้นมาแทนที่ของกษัตริย์ ท่านจะยกมาต่อสู้กับกองทัพ และจะเข้าไปในป้อมของกษัตริย์แห่งถิ่นเหนือ และจะรบกับเขาและจะชนะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 8, 'ท่านจะขนเอาบรรดาพระพร้อมทั้งพวกเจ้านายของเขา และเครื่องใช้วิเศษที่ทําด้วยเงินและทองคําไปยังอียิปต์ และท่านจะคงอยู่นานกว่ากษัตริย์แห่งถิ่นเหนืออีกหลายปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 9, 'แล้วกษัตริย์แห่งถิ่นใต้จะเข้ามาในเขตกษัตริย์แห่งถิ่นเหนือ แต่จะกลับไปสู่แผ่นดินของท่านเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 10, 'แต่บุตรชายทั้งหลายของท่านจะก่อสงครามและชุมนุมกําลังรบเป็นอันมากไว้ และคนหนึ่งจะมาอย่างแน่นอนและไหลท่วมและผ่านไป และจะกลับไปทําสงครามจนถึงป้อมปราการของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 11, 'แล้วกษัตริย์แห่งถิ่นใต้จะโกรธมาก จะยกออกมาต่อสู้กับท่าน คือกษัตริย์แห่งถิ่นเหนือ ท่านจะจัดกองทัพเป็นอันมาก แต่พลมากมายนั้นก็จะถูกมอบไว้ในมือของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 12, 'และเมื่อท่านนํากองทัพนั้นไปแล้ว จิตใจของท่านก็จะผยองขึ้น และท่านจะทําลายเสียอีกเป็นหมื่นๆคน แต่ท่านจะไม่รับกําลังเพิ่มขึ้นโดยสิ่งนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 13, 'เพราะว่ากษัตริย์แห่งถิ่นเหนือจะกลับมาและจะจัดกองทัพเป็นอันมากใหญ่โตกว่าครั้งก่อน ต่อมาอีกหลายปีท่านจะยกกองทัพใหญ่มาพร้อมกับทรัพย์สมบัติมากมาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 14, 'ในกาลนั้น หลายเหล่าจะยกขึ้นต่อสู้กับกษัตริย์แห่งถิ่นใต้ และบรรดานักปล้นแห่งชนชาติของท่านเองก็จะยกตัวเองขึ้นเพื่อจะกระทําให้นิมิตสําเร็จ แต่พวกเขาก็จะล้มเหลว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 15, 'แล้วกษัตริย์แห่งถิ่นเหนือจะมาล้อมและก่อเชิงเทิน และยึดเมืองที่มีป้อมแข็งแรงได้ และกําลังกองทัพของถิ่นใต้จะสู้ไม่ไหว แม้ว่ากองทัพที่คัดเลือกแล้วก็ยังสู้ไม่ได้ เพราะไม่มีกําลังที่จะยืนหยัดอยู่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 16, 'แต่ผู้ที่ยกมาต่อสู้กับท่าน จะกระทําตามความพอใจของท่านเอง จึงไม่มีผู้ใดต่อสู้ท่านได้ และท่านจะยั่งยืนอยู่ในแผ่นดินอันรุ่งโรจน์ ซึ่งจะถูกทําลายโดยมือของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 17, 'ท่านจะมุ่งหน้ามาด้วยกําลังทั้งหมดแห่งราชอาณาจักร และท่านจะนําคนเที่ยงตรงไปด้วย แล้วท่านจะกระทําดังนี้ คือท่านจะยกธิดาของพวกผู้หญิงให้กษัตริย์แห่งถิ่นใต้เพื่อให้ทําลายเธอ แต่เธอจะไม่มั่นคงและอํานวยประโยชน์แก่ท่านแต่ประการใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 18, 'ภายหลังท่านจะมุ่งหน้าไปตามเกาะต่างๆและจะยึดได้เป็นอันมาก แต่แม่ทัพคนหนึ่งจะได้กําจัดความอหังการของท่านนั้นเสีย ความจริงเขาจะเอาความอหังการนั้นมาสนองท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 19, 'แล้วท่านจะหันหน้ามุ่งตรงไปยังป้อมปราการแห่งแผ่นดินของท่านเอง แต่ท่านก็จะสะดุดและล้มลง หาตัวไม่พบอีกต่อไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 20, 'แล้วจะมีผู้หนึ่งขึ้นมาแทนที่ของท่าน ผู้นี้จะส่งเจ้าพนักงานเก็บส่วยให้ไปตลอดทั่วราชอาณาจักรอันรุ่งโรจน์ แต่ไม่กี่วันเขาก็ประสบหายนะ มิใช่ด้วยความโกรธหรือสงคราม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 21, 'จะมีคนน่าเกลียดคนหนึ่งตั้งตัวขึ้นแทนที่โดยไม่มีผู้ใดมอบเกียรติศักดิ์แห่งราชอาณาจักรให้ เขาจะยกเข้ามาอย่างสงบ แล้วชิงเอาราชอาณาจักรนั้นด้วยความสอพลอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 22, 'กองทัพจะถูกกวาดไปด้วยอํานาจของน้ําท่วมต่อหน้าเขาและถูกทําลายเสีย และเจ้าแห่งพันธสัญญาจะถูกทําลายเสียด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 23, 'ตั้งแต่เวลาที่กระทําพันธมิตรกับเขา เขาจะประกอบกิจล่อลวงอยู่เสมอ เพราะเขาจะขึ้นมา และเขาจะเข้มแข็งขึ้นด้วยชนชาติเล็กๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 24, 'เขาจะยกมาอย่างสงบในส่วนของประเทศที่อุดมที่สุด และเขาจะกระทําสิ่งที่ปู่ทวดหรือบรรพบุรุษของเขาไม่กระทํา เขาจะเอาทรัพย์ที่ปล้นมา ของที่ริบมาได้ และทรัพย์สมบัติมาแจกกัน เขาจะออกอุบายต่อสู้กับที่กําบังเข้มแข็ง แต่ก็ชั่วเวลาหนึ่งเท่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 25, 'และเขาจะปลุกปั่นกําลังของเขา และความกล้าหาญของเขาด้วยกองทัพมหึมายกไปสู้กับกษัตริย์แห่งถิ่นใต้ และกษัตริย์แห่งถิ่นใต้จะทําสงครามด้วยกองทัพเข้มแข็งมหึมายิ่งนัก แต่เขาก็สู้ไม่ได้ เพราะจะมีการปองร้ายเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 26, 'ถึงแม้ว่าผู้ที่ร่วมรับประทานอาหารสูงของเขาก็จะทําลายเขา กองทัพของเขาก็จะถูกกวาดไป ที่ถูกฆ่าฟันล้มตายเสียก็มาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 27, 'ส่วนกษัตริย์สององค์นั้น จิตใจของเขาต่างก็คิดปองร้าย เขาจะพูดมุสาร่วมโต๊ะกัน แต่ก็ไม่ได้ผล เพราะวาระสุดท้ายก็จะมาตามเวลากําหนด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 28, 'แล้วกษัตริย์แห่งถิ่นเหนือก็จะกลับเข้าบ้านเข้าเมืองพร้อมกับทรัพย์สมบัติมากมาย แต่จิตใจก็มุ่งร้ายต่อพันธสัญญาบริสุทธิ์ และเขาจะปฏิบัติงานและกลับเข้าบ้านเข้าเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 29, 'พอถึงเวลากําหนดเขาจะกลับมาที่ถิ่นใต้ แต่ครั้งนี้เหตุการณ์จะไม่เป็นไปอย่างครั้งแรกหรือครั้งต่อไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 30, 'เพราะว่ากองทัพเรือของเมืองคิทธิมจะมาปะทะกับเขา เขาจึงจะกลัวและกลับไป และจะเกรี้ยวกราดต่อพันธสัญญาบริสุทธิ์ และลงมือปฏิบัติงาน เขาจะหันกลับมาร่วมพันธมิตรกับบรรดาผู้ที่ทิ้งพันธสัญญาบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 31, 'และกองทัพจะยืนหยัดอยู่ฝ่ายเขา พวกเขาจะกระทําให้สถานบริสุทธิ์แห่งกองกําลังเป็นมลทิน และจะให้เลิกเครื่องเผาบูชาประจําวันนั้นเสีย และเขาทั้งหลายจะตั้งสิ่งที่น่าสะอิดสะเอียนซึ่งกระทําให้เกิดการรกร้างว่างเปล่าขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 32, 'เขาจะใช้ความสอพลอล่อลวงผู้ที่ละเมิดพันธสัญญา แต่ประชาชนผู้รู้จักพระเจ้าของเขาทั้งหลายจะยืนมั่นและปฏิบัติงาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 33, 'และในหมู่ประชาชนคนเหล่านั้นที่ฉลาดจะกระทําให้คนเป็นอันมากเข้าใจ แม้ว่าเขาจะล้มลงด้วยดาบหรือด้วยเปลวไฟ ด้วยการเป็นเชลย ด้วยถูกปล้นหลายวันเวลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 34, 'เมื่อพวกเขาล้มลงนั้น เขาจะได้รับความช่วยเหลือเล็กน้อย และจะมีคนมากด้วยกันที่ร่วมเข้ากับความสอพลอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 35, 'คนที่ฉลาดบางคนจะล้มลงเพื่อถลุงและชําระเขาทั้งหลายให้ขาวสะอาด จนกว่าจะถึงเวลาสุดท้าย เพราะวาระก็จะมาตามเวลากําหนด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 36, 'และกษัตริย์จะกระทําตามความพอใจของเขา เขาจะยกตนขึ้นและพองตัวขึ้นเหนือพระทุกองค์ และจะพูดสิ่งที่น่ามหัศจรรย์กล่าวต่อสู้พระเจ้าแห่งพระทั้งหลาย เขาจะเจริญจนพระพิโรธจะครบถ้วน เพราะสิ่งใดที่ทรงกําหนดไว้จะสําเร็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 37, 'เขาจะไม่เชื่อฟังพระเจ้าแห่งบรรพบุรุษของเขา หรือเชื่อฟังผู้ที่ผู้หญิงปรารถนา เขาจะไม่เชื่อพระองค์ใดเลย เพราะเขาจะพองตัวเองเหนือทุกสิ่งทุกอย่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 38, 'แต่ในที่ของเขา เขาจะถวายเกียรติแก่พระของป้อมปราการ พระองค์หนึ่งที่บรรพบุรุษของเขาไม่รู้จัก เขาก็จะให้เกียรติด้วยทองคําและเงิน ด้วยเพชรพลอยต่างๆ ด้วยของขวัญอันมีค่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 39, 'เขาจะกระทําเช่นนั้นกับพระต่างด้าวที่เขานับถือและพอกพูนสง่าราศีให้ในป้อมปราการส่วนใหญ่ เขาจะแต่งตั้งให้พวกเขาปกครองคนเป็นอันมาก และเขาจะแบ่งแผ่นดินให้เป็นสิ่งตอบแทน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 40, 'พอถึงเวลาวาระสุดท้ายกษัตริย์แห่งถิ่นใต้จะมาสู้กับเขา และกษัตริย์แห่งถิ่นเหนือจะพุ่งเข้าใส่ท่านอย่างลมหมุน พร้อมด้วยรถรบและพลม้าและเรือรบเป็นอันมาก เขาจะเข้ามาในประเทศต่างๆ แล้วไหลท่วมและผ่านไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 41, 'เขาจะเข้ามาในแผ่นดินที่รุ่งโรจน์ และประเทศหลายแห่งจะถูกคว่ําไป แต่คนเหล่านี้จะได้รับการช่วยให้พ้นมือของเขา คือเอโดมและโมอับ และส่วนใหญ่ของคนอัมโมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 42, 'เขาจะยืดมือของเขาออกต่อประเทศต่างๆ และแผ่นดินอียิปต์ก็จะพ้นไปไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 43, 'เขาจะปกครองทรัพย์สมบัติที่เป็นทองและเงิน และสิ่งประเสริฐทั้งหลายของอียิปต์ คนลิเบียและคนเอธิโอเปียก็จะติดไปด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 44, 'แต่ข่าวจากทิศตะวันออกและทิศเหนือจะกระทําให้เขาตกใจ และเขาจะยกออกไปด้วยความเคียดแค้นอย่างยิ่ง ที่จะทําลายและล้างผลาญคนเป็นอันมากเสียให้สิ้นเชิง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 45, 'และเขาจะปลูกพลับพลาทั้งหลายแห่งตําหนักของเขาระหว่างทะเลในภูเขาบริสุทธิ์อันรุ่งโรจน์ แม้กระนั้นเขาก็ยังพบจุดจบ และไม่มีใครช่วยเขาเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 1, '“ในครั้งนั้น มีคาเอล เจ้าผู้พิทักษ์ยิ่งใหญ่ ผู้คุ้มกันชนชาติของท่านจะลุกขึ้น และจะมีเวลายากลําบากอย่างไม่เคยมีมาตั้งแต่ครั้งมีประชาชาติจนถึงสมัยนั้น แต่ในครั้งนั้นชนชาติของท่านจะรับการช่วยให้พ้น คือทุกคนที่มีชื่อบันทึกไว้ในหนังสือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 2, 'และคนเป็นอันมากในพวกที่หลับในผงคลีแห่งแผ่นดินโลกจะตื่นขึ้น บ้างก็จะเข้าสู่ชีวิตนิรันดร์ บ้างก็เข้าสู่ความอับอายและความขายหน้านิรันดร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 3, 'และบรรดาคนที่ฉลาดจะส่องแสงเหมือนแสงฟ้า และบรรดาผู้ที่ได้ให้คนเป็นอันมากมาสู่ความชอบธรรมจะส่องแสงเหมือนอย่างดาวเป็นนิตย์นิรันดร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 4, 'แต่ตัวเจ้า โอ ดาเนียลเอ๋ย จงปิดถ้อยคําเหล่านั้นไว้ และประทับตราหนังสือนั้นเสีย จนถึงวาระสุดท้าย คนเป็นอันมากจะวิ่งไปวิ่งมา และความรู้จะทวีมากขึ้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 5, 'แล้วข้าพเจ้าคือดาเนียลก็มองดู และดูเถิด มีอีกสองคนยืนอยู่ คนหนึ่งยืนอยู่ที่ฝั่งแม่น้ําข้างนี้ อีกคนหนึ่งยืนอยู่ที่ฝั่งแม่น้ําข้างโน้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 6, 'และเขาก็พูดกับชายที่สวมเสื้อผ้าป่าน ผู้ซึ่งอยู่เหนือน้ําแห่งแม่น้ํานั้นว่า “ยังอีกนานเท่าใดจึงจะถึงที่สุดปลายของสิ่งมหัศจรรย์เหล่านี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 7, 'ชายที่สวมเสื้อผ้าป่านผู้ซึ่งอยู่เหนือน้ําทั้งหลายแห่งแม่น้ํานั้น ได้ยกมือขวาและมือซ้ายของท่านสู่ฟ้าสวรรค์ และข้าพเจ้าได้ยินท่านปฏิญาณอ้างพระผู้ทรงพระชนม์อยู่เป็นนิตย์ว่า ยังอีกวาระหนึ่ง สองวาระ และครึ่งวาระ และเมื่อการหมดอํานาจของชนชาติบริสุทธิ์สิ้นสุดลงแล้ว บรรดาสิ่งเหล่านี้ก็จะสําเร็จไปด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 8, 'ข้าพเจ้าได้ยินแต่ไม่เข้าใจ แล้วข้าพเจ้าจึงพูดว่า “โอ นายเจ้าข้า สิ่งเหล่านี้จะลงเอยอย่างไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 9, 'พระองค์ตรัสว่า “ดาเนียลเอ๋ย ไปเถอะ เพราะว่าถ้อยคําเหล่านั้นก็ถูกปิดไว้แล้วและถูกประทับตราไว้จนถึงวาระสุดท้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 10, 'คนเป็นอันมากจะได้รับการชําระแล้วจะขาวสะอาด และจะถูกถลุง แต่คนชั่วจะยังกระทําการชั่ว และไม่มีคนชั่วสักคนหนึ่งจะเข้าใจ แต่บรรดาคนที่ฉลาดจะเข้าใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 11, 'และตั้งแต่เวลาที่ให้เลิกเครื่องเผาบูชาประจําวันเสียนั้น และให้ตั้งสิ่งที่น่าสะอิดสะเอียนซึ่งกระทําให้เกิดการรกร้างว่างเปล่าขึ้น จะเป็นเวลาหนึ่งพันสองร้อยเก้าสิบวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 12, 'ความสุขจะมีแก่ผู้คอยอยู่ และมาถึงได้หนึ่งพันสามร้อยสามสิบห้าวันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 13, 'แต่เจ้าจงไปจนวาระที่สุดเถิด และเจ้าจะได้หยุดพักสงบ และจะยืนขึ้นในส่วนที่กําหนดให้เจ้า เมื่อสิ้นสุดวันทั้งหลายนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 1, 'พระวจนะของพระเยโฮวาห์ซึ่งมาถึงโฮเชยา บุตรชายเบเออรี ในรัชกาลอุสซียาห์ โยธาม อาหัสและเฮเซคียาห์ กษัตริย์ทั้งหลายแห่งยูดาห์ และในรัชกาลเยโรโบอัม ราชโอรสของโยอาช กษัตริย์อิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 2, 'เมื่อพระเยโฮวาห์ตรัสทางโฮเชยาเป็นครั้งแรกนั้น พระเยโฮวาห์ตรัสกับโฮเชยาว่า “ไปซี ไปรับหญิงเจ้าชู้มาเป็นภรรยา และเกิดลูกชู้กับนาง เพราะว่าแผ่นดินนี้เล่นชู้อย่างยิ่ง โดยการละทิ้งพระเยโฮวาห์เสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 3, 'ดังนั้นท่านจึงไปรับนางโกเมอร์บุตรสาวดิบลาอิมมาเป็นภรรยา และนางก็มีครรภ์กับท่านและคลอดบุตรชายคนหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 4, 'และพระเยโฮวาห์ตรัสกับท่านว่า “จงเรียกชื่อเขาว่า ยิสเรเอล เพราะว่าอีกไม่ช้าเราจะลงโทษวงศ์วานของเยฮูเหตุด้วยเรื่องโลหิตของยิสเรเอล เราจะให้ราชอาณาจักรของวงศ์วานอิสราเอลสิ้นสุดลงเสียที');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 5, 'ต่อมาในวันนั้นเราจะหักธนูของอิสราเอลในหุบเขายิสเรเอล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 6, 'ต่อมานางก็ตั้งครรภ์ขึ้นอีก และคลอดบุตรสาวคนหนึ่ง และพระเจ้าตรัสกับท่านว่า “จงตั้งชื่อบุตรสาวนั้นว่า โลรุหะมาห์ เพราะเราจะไม่เมตตาวงศ์วานอิสราเอลอีกต่อไป แต่เราจะเอาเขาออกไปอย่างสิ้นเชิง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 7, 'แต่เราจะเมตตาวงศ์วานยูดาห์ และเราจะช่วยเขาให้รอดพ้นโดยพระเยโฮวาห์พระเจ้าของเขาทั้งหลาย เราจะไม่ช่วยเขาให้รอดพ้นด้วยคันธนู หรือด้วยดาบ หรือด้วยสงคราม หรือด้วยเหล่าม้า หรือด้วยเหล่าพลม้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 8, 'เมื่อนางให้โลรุหะมาห์หย่านมแล้ว นางก็ตั้งครรภ์คลอดบุตรชายคนหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 9, 'และพระเจ้าตรัสว่า “จงเรียกชื่อบุตรนั้นว่า โลอัมมี เพราะเจ้าทั้งหลายมิใช่ประชาชนของเรา และเราก็มิใช่พระเจ้าของเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 10, 'แต่จํานวนประชาชนอิสราเอลจะมากมายเหมือนเม็ดทรายในทะเล ซึ่งจะตวงหรือนับไม่ถ้วน และต่อมาในสถานที่ซึ่งทรงกล่าวแก่เขาว่า “เจ้าทั้งหลายไม่ใช่ประชาชนของเรา” ก็จะกล่าวแก่เขาว่า “เจ้าทั้งหลายเป็นบุตรชายของพระเจ้าผู้ทรงพระชนม์อยู่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 11, 'และวงศ์วานยูดาห์กับวงศ์วานอิสราเอลจะรวมเข้าด้วยกัน และเขาทั้งหลายจะตั้งผู้หนึ่งให้เป็นประมุข และจะพากันขึ้นไปจากแผ่นดินนั้น เพราะวันของยิสเรเอลจะสําคัญมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 1, '“จงเรียกน้องชายของเจ้าว่า ‘อัมมี’ จงเรียกน้องสาวของเจ้าว่า ‘รุหะมาห์’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 2, 'จงว่ากล่าวมารดาของเจ้า จงว่ากล่าวเถิด เพราะว่านางไม่ใช่ภรรยาของเรา และเราไม่ใช่สามีของนาง ฉะนั้นให้เธอทิ้งการเล่นชู้เสียจากสายตาของเธอ และทิ้งการล่วงประเวณีเสียจากระหว่างถันของนาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 3, 'เกรงว่าเราจะต้องเปลื้องผ้าของนางจนเปลือยเปล่า กระทําให้นางเหมือนวันที่นางเกิดมา กระทําให้นางเหมือนถิ่นทุรกันดาร และกระทําให้นางเหมือนแผ่นดินที่แห้งแล้ง และสังหารนางเสียด้วยความกระหาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 4, 'เราจะไม่มีความสงสารต่อบุตรทั้งหลายของนาง เพราะว่าเขาทั้งหลายเป็นลูกของการเล่นชู้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 5, 'เพราะว่ามารดาของเขาเล่นชู้ เธอผู้ที่ให้กําเนิดเขาทั้งหลายได้ประพฤติความอับอาย เพราะนางกล่าวว่า ‘ฉันจะตามคนรักของฉันไป ผู้ให้อาหารและน้ําแก่ฉัน เขาให้ขนแกะและป่านแก่ฉัน ทั้งน้ํามันและของดื่ม’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 6, 'เพราะเหตุนี้ ดูเถิด เราจะเอาไม้หนามกั้นทางของนางไว้ เราจะสร้างกําแพงกั้นนางไว้เพื่อมิให้นางหาทางของนางพบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 7, 'นางจะไปตามบรรดาคนรักของนาง แต่ก็จะตามไม่ทัน นางจะเที่ยวเสาะหาเขาทั้งหลาย แต่นางก็จะไม่พบเขา แล้วนางจะว่า ‘ฉันจะไปหาผัวคนแรกของฉัน เพราะแต่ก่อนนั้นฐานะฉันยังดีกว่าเดี๋ยวนี้’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 8, 'แต่นางหารู้ไม่ว่าเราเป็นผู้ให้ข้าว น้ําองุ่น และน้ํามัน และได้ให้เงินและทองมากมายแก่นาง ซึ่งเขาใช้สําหรับพระบาอัล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 9, 'เพราะฉะนั้น เราจะกลับมาและจะเรียกข้าวคืนตามกําหนดฤดูกาล และเรียกน้ําองุ่นคืนตามฤดู และเราจะเรียกขนแกะและป่านของเรา ซึ่งให้เพื่อใช้ปกปิดกายเปลือยเปล่าของนางนั้นคืนเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 10, 'คราวนี้เราจะเผยความลามกของนางท่ามกลางสายตาของคนรักของนาง และไม่มีใครช่วยให้นางพ้นมือเราได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 11, 'เราจะให้บรรดาความร่าเริงของนางสิ้นสุดลง ทั้งเทศกาลเลี้ยง วันขึ้นหนึ่งค่ํา วันสะบาโตและบรรดาเทศกาลตามกําหนดทั้งสิ้นของนาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 12, 'เราจะให้เถาองุ่นและต้นมะเดื่อของนางร้างเปล่าที่นางคุยว่า ‘นี่แหละเป็นสินจ้างของฉันซึ่งคนรักของฉันให้ฉัน’ เราจะทําให้กลายเป็นป่าและสัตว์ป่าทุ่งจะกินเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 13, 'เราจะทําโทษนางเนื่องในวันเทศกาลเลี้ยงพระบาอัล เมื่อนางเผาเครื่องหอมบูชาพระเหล่านั้น แล้วก็แต่งกายของนางด้วยตุ้มหูและเพชรพลอยต่างๆ และติดตามบรรดาคนรักของนางไป และลืมเราเสีย พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 14, 'ดูเถิด เหตุนี้เราจะเกลี้ยกล่อมนาง พานางเข้าไปในถิ่นทุรกันดารและปลอบใจนาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 15, 'เราจะให้นางมีสวนองุ่นที่นั่น กระทําให้หุบเขาอาโคร์เป็นประตูแห่งความหวัง แล้วนางจะร้องเพลงที่นั่นอย่างสมัยเมื่อนางยังสาวอยู่ ดังในสมัยเมื่อนางขึ้นมาจากแผ่นดินอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 16, 'พระเยโฮวาห์ตรัสว่า ในวันนั้นเจ้าจะเรียกเราว่า ‘อิชอี’ เจ้าจะไม่เรียกเราว่า ‘บาอัลลี’ อีกต่อไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 17, 'เพราะว่าเราจะเอาชื่อพระบาอัลออกเสียจากปากของนาง นางจะไม่ระลึกถึงชื่อนี้อีกต่อไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 18, 'ในครั้งนั้นเพื่อเขา เราจะกระทําพันธสัญญากับบรรดาสัตว์ป่าทุ่ง บรรดานกในอากาศและบรรดาสัตว์เลื้อยคลานบนแผ่นดิน เราจะทําลายคันธนู ดาบและสงครามเสียจากแผ่นดิน และเราจะกระทําให้เขานอนลงอย่างปลอดภัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 19, 'เราจะหมั้นเจ้าไว้สําหรับเราเป็นนิตย์ เออ เราจะหมั้นเจ้าไว้สําหรับเราด้วยความชอบธรรม ความยุติธรรม ความเมตตาและความกรุณา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 20, 'เราจะหมั้นเจ้าไว้สําหรับเราด้วยความสัตย์ซื่อ และเจ้าจะรู้จักพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 21, 'พระเยโฮวาห์ตรัสว่า “ต่อมาในวันนั้นเราจะฟัง คือเราจะฟังฟ้าสวรรค์และฟ้าสวรรค์จะฟังพิภพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 22, 'และพิภพจะฟังข้าว น้ําองุ่นและน้ํามัน สิ่งเหล่านี้จะฟังยิสเรเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 23, 'เราจะหว่านเขาไว้ในแผ่นดินสําหรับเรา เราจะเมตตานางผู้ที่มิได้รับความเมตตา และเราจะพูดกับคนเหล่านั้นที่มิได้เป็นประชาชนของเราว่า ‘เจ้าเป็นประชาชนของเรา’ และเขาจะกล่าวว่า ‘พระองค์ทรงเป็นพระเจ้าของข้าพระองค์’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 1, 'และพระเยโฮวาห์ตรัสกับข้าพเจ้าว่า “จงไปอีกครั้งหนึ่ง ไปสมานรักกับหญิงคนหนึ่ง ซึ่งเป็นคนรักของชู้และเป็นหญิงล่วงประเวณี เหมือนพระเยโฮวาห์ทรงรักวงศ์วานอิสราเอลอย่างนั้นแหละ แม้ว่าเขาจะหลงใหลไปตามพระอื่น และนิยมชมชอบกับขนมลูกองุ่นแห้ง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 2, 'ดังนั้นแหละ ข้าพเจ้าจึงได้ซื้อนางมาเป็นเงินสิบห้าเชเขลกับข้าวบาร์เลย์หนึ่งโฮเมอร์ครึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 3, 'ข้าพเจ้าจึงพูดกับนางว่า “เธอต้องรอฉันให้หลายวันหน่อย อย่าเล่นชู้อีก อย่าไปเป็นของชายอื่นอีก ส่วนฉันก็จะไม่เข้าหาเธอด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 4, 'เพราะว่าวงศ์วานอิสราเอลจะคงอยู่อย่างไม่มีกษัตริย์ และไม่มีเจ้านายเป็นเวลานาน ทั้งจะไม่มีการสักการบูชา หรือรูปเคารพ หรือเอโฟด หรือเทราฟิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 5, 'ภายหลังวงศ์วานอิสราเอลจะกลับมา และแสวงหาพระเยโฮวาห์พระเจ้าของเขา และแสวงดาวิดกษัตริย์ของเขาทั้งหลาย และในกาลต่อไปเขาจะมีความยําเกรงต่อพระเยโฮวาห์และต่อความดีของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 1, 'วงศ์วานอิสราเอลเอ๋ย จงฟังพระวจนะของพระเยโฮวาห์ เพราะว่าพระเยโฮวาห์ทรงมีคดีกับชาวแผ่นดินนั้น เพราะว่าในแผ่นดินนั้นไม่มีความจริง ความเมตตา หรือความรู้ในเรื่องพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 2, 'มีแต่การปฏิญาณ การมุสา การฆ่ากัน การโจรกรรมและการล่วงประเวณี เขาหาญหักพันธะทั้งสิ้น มีแต่เลือดซ้อนเลือด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 3, 'เพราะฉะนั้น แผ่นดินจึงเป็นทุกข์ บรรดาคนที่อยู่ในแผ่นดินนั้นจะอ่อนระอาใจ ทั้งสัตว์ป่าทุ่งและนกในอากาศด้วย และปลาในทะเลจะถูกนําเอาไปเสียหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 4, 'แต่อย่าให้ผู้ใดใส่ความหรืออย่าให้ผู้ใดฟ้อง เพราะประชาชนของเจ้าก็เหมือนกับคนทั้งหลายที่ต่อสู้กับปุโรหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 5, 'ฉะนั้นเวลากลางวันเจ้าจะสะดุด และผู้พยากรณ์จะสะดุดกับเจ้าในเวลากลางคืน และเราจะทําลายมารดาของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 6, 'ประชาชนของเราถูกทําลายเพราะขาดความรู้ เพราะเจ้าปฏิเสธไม่รับความรู้ เราก็ปฏิเสธเจ้าไม่ให้รับเป็นปุโรหิตของเรา เพราะเจ้าหลงลืมพระราชบัญญัติแห่งพระเจ้าของเจ้า เราก็จะลืมวงศ์วานของเจ้าเสียด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 7, 'เขาทวีมากขึ้นเท่าใด เขาก็กระทําบาปต่อเรามากขึ้นเท่านั้น ฉะนั้นเราจะให้สง่าราศีของเขากลายเป็นความอับอาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 8, 'เขาเลี้ยงชีพอยู่ด้วยบาปแห่งประชาชนของเรา เขามุ่งที่จะอิ่มด้วยความชั่วช้าของคนเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 9, 'ปุโรหิตเป็นอย่างไร ประชาชนก็จะเป็นอย่างนั้น เราจะลงทัณฑ์เขาเนื่องด้วยวิธีการของเขา เราจะลงโทษเขาตามการกระทําของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 10, 'เขาจะรับประทาน แต่ไม่รู้จักอิ่มหนํา เขาจะเล่นชู้ แต่ไม่เกิดผลดก เพราะว่าเขาได้ทอดทิ้งการเอาใจใส่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 11, 'การเล่นชู้ เหล้าองุ่นและเหล้าองุ่นใหม่ชิงเอาจิตใจไปเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 12, 'ประชาชนของเราไปขอความเห็นจากสิ่งที่ทําด้วยไม้ และไม้ติ้วก็แจ้งแก่เขาอย่างเปิดเผย เพราะจิตใจที่ชอบเล่นชู้นําให้เขาหลงไป และเขาทั้งหลายได้ละทิ้งพระเจ้าของเขาเสียเพื่อไปเล่นชู้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 13, 'เขาถวายสัตวบูชาอยู่ที่ยอดภูเขาและทําสักการบูชาเผาอยู่ที่เนินเขา ใต้ต้นโอ๊ก ต้นไค้และต้นเอ็ลม์ เพราะว่าร่มไม้เหล่านี้เย็นดี เพราะฉะนั้นธิดาทั้งหลายของเจ้าจึงจะเล่นชู้และเจ้าสาวทั้งหลายจึงจะล่วงประเวณี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 14, 'เมื่อธิดาทั้งหลายของเจ้าเล่นชู้ เราก็ไม่ลงโทษ หรือเมื่อเจ้าสาวของเจ้าล่วงประเวณี เราก็ไม่ลงทัณฑ์ เพราะผู้ชายเองก็หลงไปกับหญิงแพศยา และทําสักการบูชากับหญิงโสเภณี ดังนั้นชนชาติที่ไม่มีความเข้าใจจะมาถึงความพินาศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 15, 'อิสราเอลเอ๋ย ถึงเจ้าจะเล่นชู้ก็อย่าให้ยูดาห์มีความผิด อย่าเข้าไปในเมืองกิลกาลหรือขึ้นไปยังเบธาเวน และอย่าปฏิญาณว่า “พระเยโฮวาห์ทรงพระชนม์อยู่แน่ฉันใด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 16, 'เพราะว่าอิสราเอลนั้นกลับสัตย์เหมือนวัวสาวที่หันกลับ บัดนี้พระเยโฮวาห์จะทรงเลี้ยงเขาดุจเลี้ยงแกะในทุ่งกว้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 17, 'เอฟราอิมก็ผูกพันอยู่กับรูปเคารพแล้ว ปล่อยเขาแต่ลําพัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 18, 'เครื่องดื่มของเขากลายเป็นน้ําเปรี้ยว เขาก็ปล่อยตัวไปเล่นชู้เสมอ ผู้ครอบครองของเขาแสดงความรักด้วยความน่าละอาย ดังนั้นจงให้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 19, 'ลมพายุเอาปีกห่อเขาไว้ เขาจะอดสูเพราะสัตวบูชาทั้งหลายของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 1, 'โอ ปุโรหิตทั้งหลาย จงฟังข้อนี้ วงศ์วานอิสราเอลเอ๋ย จงสดับ โอ ราชวงศ์กษัตริย์ จงเงี่ยหูฟัง เพราะเจ้าทั้งหลายจะต้องถูกพิพากษา เพราะเจ้าเป็นกับอยู่ที่เมืองมิสปาห์ และเป็นข่ายกางอยู่ที่เมืองทาโบร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 2, 'พวกกบฏได้ฆ่าฟันอย่างลึกล้ํา แม้ว่าเราได้ตีสอนเขาเหล่านี้ทั้งหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 3, 'เรารู้จักเอฟราอิม และอิสราเอลก็มิได้ปิดบังไว้จากเรา โอ เอฟราอิมเอ๋ย เจ้าเล่นชู้ อิสราเอลก็เป็นมลทิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 4, 'การกระทําของเขาไม่ยอมให้เขากลับไปยังพระเจ้าของเขา เพราะจิตใจที่เล่นชู้อยู่ในตัวเขา เขาจึงไม่รู้จักพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 5, 'ความเย่อหยิ่งของอิสราเอลก็ปรากฏเป็นพยานที่หน้าเขาแล้ว อิสราเอลและเอฟราอิมจึงจะสะดุดเพราะความชั่วช้าของตน ยูดาห์ก็จะพลอยล้มคว่ําไปกับเขาทั้งหลายด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 6, 'เขาจะไปแสวงหาพระเยโฮวาห์ ทั้งนําเอาฝูงแพะแกะฝูงวัวไปด้วย แต่เขาจะหาพระองค์ไม่พบ พระองค์ทรงจากเขาไปแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 7, 'เขาได้ทรยศต่อพระเยโฮวาห์ เพราะเขาเกิดลูกนอกรีต บัดนี้ในเวลาหนึ่งเดือนเขาจะถูกผลาญเสียพร้อมกับไร่นาของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 8, 'จงเป่าแตรทองเหลืองขนาดเล็กที่ในกิเบอาห์ จงเป่าแตรที่ในรามาห์ จงร้องตะโกนที่เบธาเวน โอ เบนยามินเอ๋ย มีคนตามหาเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 9, 'ในวันแห่งการห้ามปรามนั้นเอฟราอิมจะรกร้าง เราได้ประกาศท่ามกลางตระกูลต่างๆของอิสราเอลให้ทราบถึงสิ่งที่จะเกิดขึ้นอย่างแน่นอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 10, 'เจ้านายของยูดาห์ได้กลายเป็นเหมือนคนที่ย้ายหลักเขต ดังนั้นเราจะเทพระพิโรธของเราเหนือเขาให้เหมือนอย่างเทน้ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 11, 'เอฟราอิมถูกบีบบังคับ และถูกขยี้ด้วยการทําโทษ เพราะเขาได้ตั้งจิตตั้งใจติดตามบัญญัตินั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 12, 'เพราะฉะนั้นเราจะเป็นเหมือนตัวมอดต่อเอฟราอิม และเป็นเหมือนสิ่งผุพังต่อวงศ์วานยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 13, 'เมื่อเอฟราอิมเห็นความเจ็บป่วยของตน และยูดาห์เห็นบาดแผลของตน เอฟราอิมก็ไปหาคนอัสซีเรีย และส่งคนไปหากษัตริย์เยเร็บ แต่ท่านก็ไม่สามารถจะรักษาเจ้าหรือรักษาบาดแผลของเจ้าได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 14, 'เพราะเราจะเป็นเหมือนสิงโตต่อเอฟราอิม และเป็นเหมือนสิงโตหนุ่มต่อวงศ์วานของยูดาห์ เราคือเรานี่แหละ จะฉีกแล้วก็ไปเสีย เราจะลากเอาไป และใครจะช่วยก็ไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 15, 'เราจะกลับมายังสถานที่ของเราอีกจนกว่าเขาจะยอมรับความผิดของเขาและแสวงหาหน้าของเรา เมื่อเขารับความทุกข์ร้อน เขาจะแสวงหาเราอย่างขยันขันแข็ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 1, '“มาเถิด ให้เรากลับไปหาพระเยโฮวาห์ เพราะว่าพระองค์ทรงฉีก และจะทรงรักษาเราให้หาย พระองค์ทรงโบยตี และจะทรงพันบาดแผลให้แก่เรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 2, 'อีกสองวันพระองค์จะทรงฟื้นฟูเราขึ้นใหม่ พอถึงวันที่สามจะทรงยกเราขึ้น เพื่อเราจะดํารงชีวิตอยู่ในสายพระเนตรของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 3, 'แล้วเราก็จะรู้ถ้าเราพยายามรู้จักพระเยโฮวาห์ การที่พระองค์เสด็จออกก็เตรียมไว้ดุจยามเช้า พระองค์จะเสด็จมาหาเราอย่างห่าฝน ดังฝนชุกปลายฤดูกับต้นฤดูที่รดพื้นแผ่นดิน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 4, 'โอ เอฟราอิมเอ๋ย เราจะทําอะไรกับเจ้าดี โอ ยูดาห์เอ๋ย เราจะทําอะไรกับเจ้าหนอ ความดีของเจ้าเหมือนเมฆในยามเช้า เหมือนอย่างน้ําค้างที่หายไปแต่เช้าตรู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 5, 'ฉะนี้ เราจึงให้ผู้พยากรณ์แกะสลักเขา เราประหารเขาเสียด้วยคําพูดจากปากของเรา การพิพากษาต่อเจ้าก็ออกไปอย่างแสงสว่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 6, 'เพราะเราประสงค์ความเมตตาไม่ประสงค์เครื่องสัตวบูชา เราประสงค์ความรู้ในพระเจ้ายิ่งกว่าเครื่องเผาบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 7, 'แต่พวกเขาดั่งมนุษย์ได้ละเมิดพันธสัญญา ที่นั่นเขาทรยศต่อเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 8, 'กิเลอาดเป็นเมืองของคนกระทําความชั่วช้า และเปรอะเปื้อนไปด้วยโลหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 9, 'อย่างกองโจรซุ่มคอยดักคนฉันใด พวกปุโรหิตก็ซุ่มคอยฉันนั้น เขายินยอมกระทําฆาตกรรมตามทาง เขาทําการลามก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 10, 'เราเห็นสิ่งน่าสยดสยองในวงศ์วานอิสราเอล การเล่นชู้ของเอฟราอิมก็อยู่ที่นั่น อิสราเอลเป็นมลทิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 11, 'โอ ยูดาห์เอ๋ย เจ้าก็เหมือนกันด้วยฤดูเกี่ยวก็กําหนดไว้ให้เจ้าแล้ว เมื่อเราจะให้ประชาชนของเรากลับสู่สภาพเดิมจากการเป็นเชลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 1, 'เมื่อเราจะรักษาอิสราเอลให้หาย ความชั่วช้าของเอฟราอิมก็เผยออก ทั้งการกระทําที่ชั่วร้ายของสะมาเรียก็แดงขึ้น เพราะว่าเขาทุจริต ขโมยก็หักเข้ามาข้างใน และกองโจรก็ปล้นอยู่ข้างนอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 2, 'แต่เขามิได้พิจารณาในใจว่า เราจดจําการกระทําที่ชั่วทั้งหมดของเขาได้ บัดนี้การกระทําของเขาห้อมล้อมเขาไว้แล้ว การเหล่านั้นอยู่ต่อหน้าเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 3, 'เขากระทําให้กษัตริย์ชื่นชมยินดีด้วยความชั่วร้ายของเขา กระทําให้เจ้านายพอใจด้วยการมุสาของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 4, 'เขาเป็นคนล่วงประเวณีทุกคน เหมือนเตาอบซึ่งช่างทําขนมทําให้ร้อน ซึ่งตั้งแต่ช่างนวดแป้งจนแป้งฟูขึ้นแล้ว ก็หยุดเร่งให้ร้อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 5, 'ในวันฉลองกษัตริย์ของเรา พวกเจ้านายทําให้พระองค์ป่วยด้วยขวดเหล้าองุ่น กษัตริย์ทรงเหยียดพระหัตถ์ออกพร้อมกับคนขี้เยาะเย้ย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 6, 'ใจของเขาก็ร้อนเหมือนเตาอบในขณะที่เขาซุ่มดักทําร้าย ตลอดคืนช่างทําขนมของเขาก็หลับอยู่ พอถึงรุ่งเช้าก็พลุ่งออกมาอย่างกับเปลวเพลิง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 7, 'ทุกคนก็ร้อนอย่างกับเตาอบ และเขมือบผู้ครอบครองทั้งหลายของเขา กษัตริย์ทั้งสิ้นของเขาก็ล้มลง แต่ไม่มีใครท่ามกลางพวกเขาที่ร้องถึงเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 8, 'เอฟราอิมเอาตัวเข้าปนกับชนชาติทั้งหลาย เอฟราอิมเป็นขนมปิ้งที่มิได้พลิกกลับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 9, 'คนต่างด้าวก็กินแรงของเขา และเขาก็ไม่รู้ตัว ผมของเขาก็หงอกประปรายแล้ว และเขาก็ไม่รู้ตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 10, 'ความเย่อหยิ่งของอิสราเอลเป็นพยานที่หน้าเขาแล้ว เขาก็ยังไม่กลับไปหาพระเยโฮวาห์พระเจ้าของเขา เขามีเรื่องทั้งหมดเช่นนี้ เขาก็มิได้แสวงหาพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 11, 'เอฟราอิมเป็นเหมือนนกเขาโง่เขลาและไร้ความคิด ร้องเรียกอียิปต์ วิ่งไปหาอัสซีเรีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 12, 'เมื่อเขาไป เราจะกางข่ายของเราออกคลุมเขา เราจะดึงเขาลงมาเหมือนดักนกในอากาศ เราจะลงโทษเขาตามที่ชุมนุมชนได้ยินแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 13, 'วิบัติแก่เขา เพราะเขาได้หลงเจิ่นไปจากเรา ความพินาศจงมีแก่เขา เพราะเขาได้ละเมิดต่อเรา แม้ว่าเราได้ไถ่เขาไว้แล้ว เขาก็ยังพูดมุสาเรื่องเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 14, 'เขามิได้ร้องทุกข์ต่อเราจากใจจริงของเขาเมื่อเขาคร่ําครวญอยู่บนที่นอนของเขา เขาชุมนุมกันเพื่อขอข้าวและขอน้ําองุ่น และเขากบฏต่อเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 15, 'แม้ว่าเราจะได้ฝึกและเพิ่มกําลังแขนให้เขา เขาก็ยังคิดทําร้ายต่อเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 16, 'เขากลับไป แต่ไม่กลับไปหาพระองค์ผู้สูงสุด เขาเป็นคันธนูที่หลอกลวง เจ้านายของเขาจะล้มลงด้วยดาบเพราะลิ้นที่โทโสของเขา เรื่องนี้จะเป็นเรื่องที่ให้เขาเย้ยหยันกันในแผ่นดินอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 1, 'จงจรดแตรไว้ที่ปากของเจ้า เพราะว่าเขาจะมาดังนกอินทรีเหนือพระนิเวศของพระเยโฮวาห์ เพราะเขาได้ละเมิดพันธสัญญาของเรา และละเมิดราชบัญญัติของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 2, 'อิสราเอลจะร้องทุกข์ต่อเราว่า “ข้าแต่พระเจ้าของข้าพระองค์ ข้าพระองค์รู้จักพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 3, 'อิสราเอลได้ทอดทิ้งสิ่งที่ดีเสียแล้ว ศัตรูจะไล่ติดตามเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 4, 'เขาทั้งหลายได้แต่งตั้งกษัตริย์ แต่ไม่ใช่โดยเรา เขาทั้งหลายตั้งเจ้านาย แต่เราไม่รู้เรื่องเลย พวกเขาได้สร้างรูปเคารพทั้งหลายด้วยเงินและทองคําของเขา เพื่อพวกเขาจะถูกตัดขาดออกเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 5, 'โอ สะมาเรียเอ๋ย รูปลูกวัวของเจ้าได้ทิ้งเจ้าเสียแล้ว ความกริ้วของเราพลุ่งขึ้นต่อเขา อีกนานสักเท่าใดหนอเขาจึงจะบริสุทธิ์กันได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 6, 'เพราะรูปหล่อนั้นได้มาจากอิสราเอล ช่างเป็นผู้ทําขึ้น รูปนั้นจึงมิได้เป็นพระเจ้า รูปลูกวัวของสะมาเรียจะต้องถูกทุบให้เป็นชิ้นๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 7, 'เพราะว่าเขาหว่านลม เขาจึงต้องเกี่ยวลมหมุน ต้นข้าวไม่มีรวง จะไม่เกิดข้าวสําหรับทําแป้ง ถึงจะเกิด คนต่างด้าวก็เอาไปกิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 8, 'อิสราเอลถูกกลืนไปหมดแล้ว เดี๋ยวนี้อยู่ท่ามกลางประชาชาติทั้งหลาย เป็นเหมือนภาชนะไร้ความพึงพอใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 9, 'เขาทั้งหลายขึ้นไปหาอัสซีเรียดังลาป่าที่ท่องเที่ยวอยู่ลําพัง เอฟราอิมได้จ้างคนรักมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 10, 'เออ แม้ว่าเขาจ้างประชาชาติอื่นมา ไม่ช้าเราจะต้อนเขาให้รวมกัน เขาจะเป็นทุกข์เล็กน้อยเรื่องภาระของกษัตริย์จอมเจ้านาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 11, 'เพราะเหตุเอฟราอิมได้ก่อสร้างแท่นบูชาเพิ่มขึ้นเพื่อบาป แท่นบูชาเหล่านั้นก็กลับกลายเป็นแท่นเพื่อบาปให้เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 12, 'ถึงเราได้เขียนราชบัญญัติไว้ให้สักหมื่นข้อ เขาก็ถือว่าเป็นเพียงของแปลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 13, 'ส่วนเครื่องสัตวบูชาที่ถวายแก่เรานั้น เขาถวายเนื้อและรับประทานเนื้อนั้น แต่พระเยโฮวาห์มิได้พอพระทัยในตัวเขา บัดนี้พระองค์จะทรงระลึกถึงความชั่วช้าของเขา และจะทรงลงโทษเขาเพราะบาปของเขา เขาจะกลับไปยังอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 14, 'เพราะว่าอิสราเอลได้ลืมพระผู้สร้างของตนเสียแล้ว จึงสร้างวิหารขึ้นหลายแห่ง และยูดาห์ก็ทวีจํานวนเมืองที่มีกําแพงขึ้นอีก แต่เราจะส่งไฟมายังเมืองเหล่านี้ของเขา และไฟจะเผาผลาญปราสาทของเมืองเหล่านี้เสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 1, 'โอ อิสราเอลเอ๋ย อย่าเปรมปรีดิ์ไป อย่าเปรมปรีดิ์อย่างชนชาติทั้งหลายเลย เพราะเจ้าทั้งหลายเล่นชู้นอกใจพระเจ้าของเจ้า เจ้าทั้งหลายรักค่าสินจ้างของหญิงแพศยาตามบรรดาลานนวดข้าว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 2, 'แต่ลานนวดข้าวและบ่อย่ําองุ่นจะไม่พอเลี้ยงเขา และน้ําองุ่นใหม่ก็จะขาดไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 3, 'เขาทั้งหลายจะไม่ได้อาศัยอยู่ในแผ่นดินของพระเยโฮวาห์ แต่เอฟราอิมจะกลับไปยังอียิปต์ เขาจะรับประทานอาหารไม่สะอาดอยู่ที่ในอัสซีเรีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 4, 'เขาจะไม่ทําพิธีเทน้ําองุ่นถวายพระเยโฮวาห์ เขาจะไม่กระทําให้พระองค์พอพระทัย เครื่องสัตวบูชาของเขาจะเป็นเหมือนขนมปังสําหรับไว้ทุกข์แก่เขา ผู้ใดรับประทานก็จะมีมลทิน เพราะว่าขนมปังสําหรับจิตวิญญาณของเขาจะไม่เข้าไปในพระนิเวศของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 5, 'เจ้าจะทําอะไรกันเมื่อถึงวันเทศกาล และในวันเทศกาลของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 6, 'เพราะ ดูเถิด เขาหนีไปหมดแล้วเพราะเหตุความพินาศ อียิปต์จะรวบรวมเขาไว้ เมืองเมมฟิสจะฝังเขา ต้นตําแยจะยึดสิ่งประเสริฐที่ทําด้วยเงินของเขาไว้เสีย ต้นหนามจะงอกขึ้นในเต็นท์ของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 7, 'วันลงโทษมาถึงแล้ว และวันที่จะทดแทนก็มาถึงแล้ว อิสราเอลจะรู้เรื่อง ผู้พยากรณ์เป็นคนเขลาไปแล้ว ผู้ที่อยู่ฝ่ายจิตวิญญาณก็บ้าไปเนื่องด้วยความชั่วช้าอันมากมายของเจ้า และความเกลียดชังอันยิ่งใหญ่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 8, 'ยามแห่งเอฟราอิมอยู่กับพระเจ้าของเรา แต่ผู้พยากรณ์เป็นเหมือนกับของพรานดักนกอยู่ตามทางของเขาทั่วไปหมด และความเกลียดชังอยู่ในพระนิเวศแห่งพระเจ้าของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 9, 'เขาเสื่อมทรามลึกลงไปในความชั่วอย่างมากมายดังสมัยเมืองกิเบอาห์ พระองค์จึงจะทรงระลึกถึงความชั่วช้าของเขา พระองค์จะทรงลงโทษเพราะบาปของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 10, 'เราพบอิสราเอลเหมือนพบผลองุ่นอยู่ในถิ่นทุรกันดาร เราพบบรรพบุรุษของเจ้าทั้งหลายเหมือนพบผลมะเดื่อรุ่นแรกที่ต้นมะเดื่อเมื่อออกในฤดูแรก แต่เขาไปหาพระบาอัลเปโอร์ และถวายตัวของเขาไว้แก่สิ่งอันน่าอดสูนั้น และกลายเป็นสิ่งที่น่าสะอิดสะเอียนอย่างสิ่งที่เขารักนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 11, 'สําหรับเอฟราอิม สง่าราศีของเขาก็จะบินไปเหมือนอย่างนก ไม่มีการคลอด ไม่มีการมีท้อง ไม่มีการตั้งครรภ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 12, 'ถึงแม้ว่าเขาจะเลี้ยงลูกไว้ได้จนโต เราก็จะพรากเขาไปเสียจนไม่เหลือสักคนเดียว เออ วิบัติแก่เขา เมื่อเราพรากจากเขาไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 13, 'เอฟราอิมนั้น ดังที่เราเห็นเมืองไทระ ก็ปลูกไว้ในสถานที่ถูกใจ แต่เอฟราอิมต้องนําลูกหลานของตนไปมอบให้ฆาตกร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 14, 'โอ พระเยโฮวาห์เจ้าข้า ขอประทานแก่เขา พระองค์จะประทานอะไรแก่เขา ขอประทานมดลูกที่แท้งบุตรและหัวนมที่เหี่ยวแห้งแก่เขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 15, 'ความชั่วของเขาทุกอย่างอยู่ในกิลกาล เราได้เกลียดชังเขา ณ ที่นั่น เราจะขับเขาออกไปจากนิเวศของเรา เพราะความชั่วร้ายแห่งการกระทําของเขา เราจะไม่รักเขาอีกเลย เจ้านายทั้งสิ้นของเขาก็ล้วนแต่คนกบฏ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 16, 'เอฟราอิมถูกทําลายเสียแล้ว รากของเขาก็เหี่ยวแห้งไป เขาทั้งหลายจะไม่มีผลอีก เออ แม้ว่าเขาจะเกิดลูกหลาน เราก็จะฆ่าผู้บังเกิดจากครรภ์ซึ่งเป็นที่รักของเขาเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 17, 'พระเจ้าของข้าพเจ้าจะเหวี่ยงเขาทิ้งไป เพราะเขาทั้งหลายมิได้เชื่อฟังพระองค์ เขาจะเป็นคนพเนจรอยู่ท่ามกลางประชาชาติทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 1, 'อิสราเอลเป็นเถาองุ่นที่เปล่าประโยชน์ ซึ่งเกิดผลสําหรับตัวเขาเอง เกิดผลมากขึ้นเท่าใด ยิ่งสร้างแท่นบูชามากขึ้นเท่านั้น เมื่อประเทศของเขาเฟื่องฟูขึ้นเขาก็ยิ่งให้เสาศักดิ์สิทธิ์ของเขาเจริญขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 2, 'จิตใจของเขาเทียมเท็จ บัดนี้เขาจึงต้องทนรับโทษของความผิด พระองค์จะทรงพังแท่นบูชาของเขาลง และทําลายเสาศักดิ์สิทธิ์ของเขาเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 3, 'คราวนี้เขาจะพูดเป็นแน่ว่า “เราไม่มีกษัตริย์ เพราะเราไม่ยําเกรงพระเยโฮวาห์ หากเรามีกษัตริย์ ท่านจะทําประโยชน์อะไรให้แก่เราบ้าง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 4, 'เขาพูดพล่อยๆ เขาทําพันธสัญญาด้วยคําปฏิญาณลมๆแล้งๆ การพิพากษาจึงงอกงามขึ้นมาเหมือนดีหมีอยู่ในร่องรอยไถที่ในทุ่งนา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 5, 'ชาวสะมาเรียจะหวาดกลัวเพราะเหตุลูกวัวที่เบธาเวน คนที่นั่นจะไว้ทุกข์เพราะรูปนั้น และปุโรหิตของปฏิมากรที่นั่นซึ่งเคยชื่นชมยินดีกับรูปนั้นก็จะพิลาปร่ําไห้ เพราะเหตุสง่าราศีที่หมดไปจากรูปนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 6, 'เออ รูปเคารพนั้นเองก็จะต้องถูกนําไปยังอัสซีเรีย เป็นบรรณาการแด่กษัตริย์เยเร็บ เอฟราอิมจะได้รับความอัปยศ และอิสราเอลจะรู้สึกอับอายขายหน้าเหตุแผนการของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 7, 'สําหรับสะมาเรีย กษัตริย์ของเขาจะมลายไปเหมือนฟองที่ลอยอยู่บนผิวน้ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 8, 'ปูชนียสถานสูงของเมืองอาเวน อันเป็นบาปของอิสราเอล จะต้องถูกทําลาย ต้นไม้ที่มีหนามและผักที่มีหนามจะงอกขึ้นบนแท่นบูชาของเขา เขาจะร้องบอกกับภูเขาว่า “จงปกคลุมเราไว้” และร้องบอกเนินเขาว่า “จงล้มทับเราเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 9, 'โอ อิสราเอลเอ๋ย เจ้าได้กระทําบาปตั้งแต่สมัยกิเบอาห์ เขายังยืนหยัดอยู่อย่างนั้น สงครามในกิเบอาห์ตามลูกหลานแห่งความชั่วช้าไม่ทัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 10, 'เราประสงค์จะลงโทษพวกเขา ชนชาติทั้งหลายจะประชุมกันสู้เขา เมื่อเขาจะผูกมัดตัวเองไว้ในรอยไถสองแถวของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 11, 'เอฟราอิมเป็นวัวสาวที่ได้รับการสอน มันชอบนวดข้าว เราจึงหวงคออันงามของมันไว้ แต่เราจะเอาเอฟราอิมเข้าเทียมแอก ยูดาห์ก็ต้องไถ ยาโคบต้องคราดสําหรับตนเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 12, 'จงหว่านความชอบธรรมไว้สําหรับตัว จงเกี่ยวผลของความเมตตา เจ้าจงไถดินที่ร้างอยู่ เพราะเป็นเวลาที่จะแสวงหาพระเยโฮวาห์ จนกระทั่งพระองค์จะเสด็จมาโปรยความชอบธรรมลงให้แก่เจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 13, 'เจ้าทั้งหลายได้ไถความชั่วมา แล้วเจ้าทั้งหลายได้เกี่ยวความชั่วช้า เจ้าได้รับประทานผลของการมุสา ด้วยเหตุว่าเจ้าวางใจในทางของเจ้าและในจํานวนพลรบของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 14, 'เหตุฉะนั้นเสียงสงครามจึงจะเกิดขึ้นท่ามกลางชนชาติของเจ้า ป้อมปราการทั้งสิ้นของเจ้าจะถูกทําลายอย่างกับกษัตริย์ชัลมันทําลายเมืองเบธาร์เบลในวันสงคราม พวกแม่ถูกฟาดลงอย่างยับเยินพร้อมกับลูกของนาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 15, 'เมืองเบธเอลจะกระทําแก่เจ้าเช่นนี้แหละเพราะความชั่วร้ายใหญ่ยิ่งของเจ้า ในรุ่งเช้าวันหนึ่งกษัตริย์อิสราเอลจะถูกตัดขาดเสียหมดสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 1, 'ครั้งเมื่ออิสราเอลยังเด็กอยู่ เราก็รักเขา เราได้เรียกบุตรชายของเราออกมาจากประเทศอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 2, 'พวกเขายิ่งเรียกเขามากเท่าใด เขายิ่งออกไปห่างจากพวกเขามากเท่านั้น เขาถวายสัตวบูชาแก่พระบาอัล และเผาเครื่องหอมถวายแก่รูปเคารพสลักอยู่เรื่อยไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 3, 'แต่เรานี่แหละสอนเอฟราอิมให้เดิน เราอุ้มเขาทั้งหลายไว้ แต่เขาหาทราบไม่ว่า เราเป็นผู้รักษาเขาให้หาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 4, 'เราจูงเขาด้วยสายแห่งมนุษยธรรมและด้วยปลอกแห่งความรัก เราเป็นผู้ถอดแอกที่ขากรรไกรของเขาออก และเราก้มลงเลี้ยงเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 5, 'เขาจะไม่กลับไปยังแผ่นดินอียิปต์ แต่อัสซีเรียจะเป็นกษัตริย์ของเขา เพราะเขาปฏิเสธไม่ยอมกลับมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 6, 'ดาบจะรุกรานบรรดาหัวเมืองของเขา ทําลายกิ่งทั้งหลายของเขาเสียและกลืนกินเขาเสีย เพราะแผนการของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 7, 'ประชาชนของเราหันไปในทางเสื่อมถอยจากเรา ถึงแม้พวกเขาเรียกเขาทั้งหลายให้มาหาพระองค์ผู้สูงสุด ไม่มีใครยอมยกย่องพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 8, 'เอฟราอิมเอ๋ย เราจะปล่อยเจ้าได้อย่างไร อิสราเอลเอ๋ย เราจะโยนเจ้าไปให้ผู้อื่นได้อย่างไร เราจะปล่อยเจ้าให้เหมือนเมืองอัดมาห์ได้อย่างไร เรากระทําเจ้าให้เหมือนเมืองเศโบยิมได้อย่างไร จิตใจของเราปั่นป่วนอยู่ภายใน ความเอ็นดูของเราก็คุกรุ่นขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 9, 'เราจะไม่ลงอาชญาตามที่เรากริ้วจัด เราจะไม่กลับไปทําลายเอฟราอิมอีก เพราะเราเป็นพระเจ้าไม่ใช่มนุษย์ เราเป็นผู้บริสุทธิ์ท่ามกลางพวกเจ้า เราจะไม่เข้าในเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 10, 'เขาทั้งหลายจะติดตามพระเยโฮวาห์ไป ผู้ซึ่งมีสิงหนาทดั่งราชสีห์ เออ พระองค์จะทรงเปล่งพระสิงหนาท และบุตรทั้งหลายของพระองค์จะตัวสั่นสะท้านมาจากทิศตะวันตก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 11, 'เขาจะตัวสั่นสะท้านมาเหมือนวิหคจากอียิปต์ และเหมือนนกเขาจากแผ่นดินอัสซีเรีย เราจะให้เขากลับไปบ้านของเขา พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 12, 'เอฟราอิมได้กั้นล้อมเราไว้ด้วยความมุสา และวงศ์วานอิสราเอลล้อมเราด้วยเล่ห์ลวง แต่ยูดาห์ยังปกครองอยู่กับพระเจ้าและสัตย์ซื่ออยู่กับพวกวิสุทธิชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 1, 'เอฟราอิมเลี้ยงตนด้วยลม และตามหาลมตะวันออกอยู่ วันยังค่ําเขาทวีความมุสาและการรกร้าง เขาทําพันธสัญญากับอัสซีเรียและขนเอาน้ํามันไปให้อียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 2, 'พระเยโฮวาห์ทรงมีคดีกับยูดาห์และจะลงโทษยาโคบตามการประพฤติของเขา และจะทรงทดแทนเขาตามการกระทําของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 3, 'ในครรภ์ของมารดาเขายึดส้นเท้าพี่ชายของเขา และโดยกําลังของเขาเอง เขาจึงมีอํานาจกับพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 4, 'เออ เขามีอํานาจเหนือทูตสวรรค์และมีชัย เขาร้องไห้และวิงวอนต่อพระองค์ เขาพบพระองค์ที่เบธเอล และพระองค์ตรัสสนทนากับเราที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 5, 'คือพระเยโฮวาห์พระเจ้าแห่งพลโยธา พระเยโฮวาห์ทรงเป็นที่ระลึกของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 6, '“เหตุฉะนั้นเจ้าจงกลับมาหาพระเจ้าของเจ้า ยึดความเมตตาและความยุติธรรมไว้ให้มั่น และรอคอยพระเจ้าของเจ้าอยู่เสมอ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 7, 'เขาเป็นพ่อค้า ในมือของเขามีตราชูขี้ฉ้อ เขารักที่จะบีบบังคับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 8, 'เอฟราอิมได้กล่าวว่า “แท้จริงข้าพเจ้าเป็นคนมั่งมี ข้าพเจ้าหาทรัพย์เพื่อตนเอง ในการกระทําทั้งหลายของข้าพเจ้า เขาจะไม่พบความชั่วช้าที่นับว่าเป็นความบาปได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 9, 'เราคือพระเยโฮวาห์พระเจ้าของเจ้าตั้งแต่ครั้งแผ่นดินอียิปต์ เราจะกระทําให้เจ้าอาศัยอยู่ในเต็นท์อีก ดังในสมัยที่มีเทศกาลเลี้ยงตามกําหนด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 10, 'เราได้พูดทางบรรดาผู้พยากรณ์แล้ว เราให้เกิดนิมิตมากขึ้น เราให้คําอุปมาโดยทางการรับใช้ของผู้พยากรณ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 11, 'มีความชั่วช้าในกิเลอาดหรือ แน่นอนเขาทั้งหลายก็เป็นอนิจจัง เขาเอาวัวผู้ถวายบูชาในกิลกาล เออ แท่นบูชาของเขาก็จะเหมือนกองหินอยู่บนรอยไถในท้องนา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 12, 'ยาโคบหนีไปยังแผ่นดินอารัม อิสราเอลได้ทํางานเพื่อจะได้ภรรยา ท่านเลี้ยงแกะเพื่อให้ได้ภรรยา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 13, 'พระเยโฮวาห์ทรงนําคนอิสราเอลขึ้นมาจากอียิปต์โดยผู้พยากรณ์คนหนึ่ง พระองค์ทรงรักษาเขาไว้โดยผู้พยากรณ์คนหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 14, 'เอฟราอิมกระทําให้พระองค์ทรงพระพิโรธอย่างขมขื่น ดังนั้นพระองค์ทรงปล่อยให้เลือดของเขาติดอยู่กับเขา และองค์พระผู้เป็นเจ้าทรงสนองเขาด้วยความอัปยศซึ่งเขาให้ตกกับพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 1, 'เมื่อเอฟราอิมพูดด้วยตัวสั่น เขาได้ยกย่องตัวเองในอิสราเอล แต่เมื่อเอฟราอิมได้กระทําผิดด้วยพระบาอัล เขาก็ตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 2, 'เดี๋ยวนี้เขายิ่งทําบาปมากขึ้น และสร้างรูปหล่อไว้สําหรับตัวเป็นรูปเคารพที่สร้างด้วยเงินตามความคิดของเขาเอง เป็นงานของช่างที่สร้างขึ้นทั้งนั้น เขากล่าวว่า “สําหรับคนที่ถวายสัตวบูชาแก่สิ่งเหล่านี้ จงให้เขาจุบรูปลูกวัว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 3, 'เพราะฉะนั้นเขาจึงเหมือนหมอกในเวลาเช้า หรือเหมือนน้ําค้างที่หายไปตั้งแต่เช้า เหมือนแกลบที่ลมหมุนพัดไปจากลานนวดข้าว หรือเหมือนควันที่ออกมาจากช่องลม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 4, 'เราคือพระเยโฮวาห์ พระเจ้าของเจ้า ตั้งแต่ครั้งแผ่นดินอียิปต์ เจ้าทั้งหลายไม่รู้จักพระอื่นนอกจากเรา เพราะไม่มีผู้ช่วยอื่นใดนอกจากเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 5, 'เรานี่แหละที่คุ้นเคยกับเจ้าที่ในถิ่นทุรกันดาร ในแผ่นดินที่กันดารน้ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 6, 'เมื่อเขาได้รับประทานเต็มคราบแล้ว เขาก็อิ่มหนํา และจิตใจของเขาก็ผยองขึ้น เพราะฉะนั้นเขาจึงลืมเราเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 7, 'ดังนั้นเราจึงเป็นเหมือนสิงโตต่อเขา และเราจะซุ่มคอยอยู่ตามทางอย่างเสือดาว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 8, 'เราจะตะครุบเขาอย่างกับแม่หมีที่ถูกพรากลูก เราจะฉีกอกของเขาและจะกินเขาเสียที่นั่นอย่างสิงโต สัตว์ป่าทุ่งจะฉีกเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 9, 'โอ อิสราเอลเอ๋ย เจ้าได้ทําลายตัวเอง แต่เราช่วยเจ้าได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 10, 'เราประสงค์เป็นกษัตริย์ของเจ้า กษัตริย์อื่นๆที่สามารถช่วยเจ้าในเมืองทั้งหลายของเจ้าอยู่ที่ไหน และผู้ปกครองของเจ้าอยู่ที่ไหน คือพวกเหล่านั้นที่เจ้าได้กล่าวเรื่องเขาว่า “ขอตั้งกษัตริย์และเจ้านายไว้ให้แก่ข้าพเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 11, 'เพราะความกริ้วของเรา เราจึงให้เจ้ามีกษัตริย์ และเพราะความโกรธของเรา เราจึงเอากษัตริย์นั้นไปเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 12, 'ความชั่วช้าของเอฟราอิมก็ห่อไว้ บาปของเขาก็เก็บสะสมไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 13, 'การเจ็บท้องเตือนให้เขาคลอดก็มาถึงเขา แต่เขาเป็นบุตรชายที่เขลา ด้วยว่าถึงเวลาแล้วเขาก็ไม่ยอมคลอดออกมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 14, 'เราจะไถ่เขาให้พ้นอํานาจแดนคนตาย เราจะไถ่เขาให้พ้นความตาย โอ มัจจุราชเอ๋ย เราจะเป็นภัยพิบัติทั้งหลายของเจ้า โอ แดนคนตายเอ๋ย เราจะเป็นความพินาศของเจ้า การกลับใจเสียใหม่จะถูกบดบังไว้พ้นสายตาของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 15, 'แม้ว่าเขาจะงอกงามขึ้นท่ามกลางพี่น้อง ลมตะวันออก คือลมของพระเยโฮวาห์จะพัดมา ขึ้นมาจากถิ่นทุรกันดาร และตาน้ําของเขาจะแห้งไป และน้ําพุของเขาก็จะแห้งผาก ลมนั้นจะริบของมีค่าทั้งหมดเอาไปจากคลังของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 16, 'สะมาเรียจะกลายเป็นที่รกร้าง เพราะเธอได้กบฏต่อพระเจ้าของเธอ เขาทั้งหลายจะล้มลงด้วยดาบ ทารกของเขาจะถูกจับโยนลงให้แหลกเป็นชิ้นๆ และหญิงมีครรภ์จะถูกผ่าท้อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 1, 'โอ อิสราเอลเอ๋ย จงกลับมาหาพระเยโฮวาห์พระเจ้าของเจ้า เจ้าสะดุดก็เพราะความชั่วช้าของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 2, 'จงนําถ้อยคํามาด้วยและกลับมาหาพระเยโฮวาห์ จงทูลพระองค์ว่า “ขอทรงโปรดยกความชั่วช้าทั้งหมด ขอทรงพระกรุณารับข้าพระองค์ทั้งหลาย ข้าพระองค์จึงจะนําลูกวัวแห่งริมฝีปากของข้าพระองค์ทั้งหลายมาถวาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 3, 'อัสชูรจะไม่ช่วยข้าพระองค์ทั้งหลาย ข้าพระองค์ทั้งหมดจะไม่ขี่ม้า ข้าพระองค์ทั้งหลายจะไม่กล่าวต่อไปว่า ‘พระของเราทั้งหลาย’ แก่สิ่งที่มือของข้าพระองค์ได้สร้างขึ้น เพราะว่าในพระองค์ลูกกําพร้าพ่อพบพระกรุณาคุณ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 4, 'เราจะช่วยรักษาเขาให้หายจากการกลับสัตย์ของเขา เราจะรักเขาทั้งหลายด้วยเต็มใจ เพราะว่าความกริ้วของเราหันไปจากเขาแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 5, 'เราจะเป็นเหมือนน้ําค้างแก่อิสราเอล เขาจะเบิกบานอย่างดอกลิลลี่ เขาจะหยั่งรากเหมือนเลบานอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 6, 'กิ่งก้านของเขาจะขยายออก เขาจะงามเหมือนต้นมะกอกเทศ และจะมีกลิ่นหอมเหมือนเลบานอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 7, 'เขาทั้งหลายที่อยู่ใต้ร่มเงาของเขาก็จะกลับมา เขาจะเจริญขึ้นเหมือนข้าว จะออกดอกเหมือนเถาองุ่น และจะมีกลิ่นเหมือนน้ําองุ่นแห่งเลบานอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 8, 'เอฟราอิมจะกล่าวว่า “เราต้องเกี่ยวข้องอะไรกับรูปเคารพต่อไป” เราเองได้ยินเขาและคอยดูเขา เราเป็นเหมือนต้นสนสามใบเขียวสด และผลของเจ้าก็ได้มาจากเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 9, 'ผู้ใดที่ฉลาด ก็ให้เข้าใจสิ่งเหล่านี้เถิด ผู้ใดที่ช่างสังเกต ก็ให้เขารู้ เพราะว่าพระมรรคาของพระเยโฮวาห์ก็เที่ยงตรง ผู้ชอบธรรมทั้งหลายก็เดินในทางนี้ แต่ผู้ทรยศก็สะดุดอยู่ในทางนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 1, 'พระวจนะของพระเยโฮวาห์ที่มาถึงโยเอล บุตรชายของเปธุเอล ว่าดังนี้ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 2, 'ท่านผู้เฒ่าทั้งหลาย ขอจงฟังเรื่องนี้ ชาวแผ่นดินทั้งสิ้น ขอจงเงี่ยหูฟัง สิ่งเหล่านี้เคยเกิดมาในสมัยของท่าน หรือเกิดมาในสมัยบรรพบุรุษของท่านบ้างหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 3, 'จงบอกให้ลูกของท่านทราบ และให้ลูกบอกหลาน และให้หลานบอกเหลนอีกชั่วอายุหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 4, 'สิ่งใดที่ตั๊กแตนวัยเดินกินเหลือ ตั๊กแตนวัยบินก็กินเสีย สิ่งใดที่ตั๊กแตนวัยบินกินเหลือตั๊กแตนวัยกระโดดก็กินเสีย สิ่งใดที่ตั๊กแตนวัยกระโดดกินเหลือตั๊กแตนวัยคลานก็กินเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 5, 'เจ้าพวกขี้เมาเอ๋ย จงตื่นขึ้นและร้องไห้เถิด นักดื่มเหล้าองุ่นทุกคนเอ๋ย จงโอดครวญเถิด เพราะว่าน้ําองุ่นใหม่ถูกตัดขาดจากปากของเจ้าทั้งหลายแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 6, 'เพราะว่าประชาชาติหนึ่งได้ขึ้นมาสู้กับแผ่นดินของข้าพเจ้า เขามีทั้งกําลังมากและมีจํานวนนับไม่ถ้วน ฟันของมันเหมือนฟันสิงโต เขี้ยวของมันเหมือนเขี้ยวสิงโตผู้ยิ่งใหญ่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 7, 'มันได้ทําลายเถาองุ่นของข้าพเจ้าเสีย และได้ปอกเปลือกต้นมะเดื่อของข้าพเจ้า มันลอกเปลือกออกและโยนทิ้งเสีย กิ่งก้านก็ดูขาวโพลน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 8, 'จงโอดครวญอย่างหญิงพรหมจารีซึ่งคาดเอวด้วยผ้ากระสอบที่ไว้ทุกข์ให้สามีของเธอที่ได้เมื่อวัยสาว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 9, 'ธัญญบูชาและเครื่องดื่มบูชาได้ถูกตัดขาดเสียจากพระนิเวศของพระเยโฮวาห์ ปุโรหิตผู้ปรนนิบัติของพระเยโฮวาห์ก็โศกเศร้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 10, 'นาก็ร้าง พื้นดินก็เศร้าโศก เพราะข้าวถูกทําลายเสีย น้ําองุ่นใหม่ก็แห้งไปหมด น้ํามันก็ขาดมือไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 11, 'โอ ชาวนาทั้งหลายเอ๋ย จงอับอายไปเถิด โอ ผู้แต่งเถาองุ่นเอ๋ย จงคร่ําครวญเนื่องด้วยข้าวสาลีและข้าวบาร์เลย์ เพราะผลของนาก็ถูกทําลายไปหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 12, 'เถาองุ่นก็เหี่ยว ต้นมะเดื่อก็แห้งไป ต้นทับทิม ต้นอินทผลัม และต้นแอบเปิ้ล ต้นไม้ในนาทั้งสิ้นก็เหี่ยวไป เพราะความยินดีก็เหี่ยวไปจากบุตรทั้งหลายของมนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 13, 'ท่านปุโรหิตทั้งหลายเอ๋ย จงคาดเอวและโอดครวญ ท่านผู้ปรนนิบัติที่แท่นบูชา จงคร่ําครวญ ท่านผู้ปรนนิบัติพระเจ้าของข้าพเจ้า จงเข้าไปสวมผ้ากระสอบนอนค้างคืนสักคืนหนึ่ง เพราะว่าธัญญบูชาและเครื่องดื่มบูชาได้ขาดไปเสียจากพระนิเวศแห่งพระเจ้าของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 14, 'จงเตรียมตัวถืออดอาหาร จงเรียกประชุมอันศักดิ์สิทธิ์ จงรวบรวมบรรดาผู้ใหญ่และชาวแผ่นดินทั้งสิ้นไปยังพระนิเวศของพระเยโฮวาห์พระเจ้าของท่าน และร้องทูลต่อพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 15, 'อนิจจาหนอวันนั้น เพราะวันแห่งพระเยโฮวาห์ใกล้เข้ามาแล้ว วันนั้นจะมาเป็นการทําลายจากองค์ผู้ทรงมหิทธิฤทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 16, 'อาหารถูกตัดออกจากเบื้องหน้าสายตาของพวกเราแล้ว เออ ความปีติและความยินดีก็ขาดไปจากพระนิเวศแห่งพระเจ้าของเราแล้ว มิใช่หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 17, 'เมล็ดพืชก็เน่าอยู่ในดิน ฉางก็รกร้าง ยุ้งก็หักพังลง เพราะว่าข้าวเหี่ยวแห้งไปเสียแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 18, 'สัตว์ทั้งหลายร้องครวญครางแล้วหนอ ฝูงวัวก็งุนงง เพราะว่าไม่มีทุ่งหญ้าให้มัน ฝูงแกะก็อ่อนระอาไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 19, 'โอ ข้าแต่พระเยโฮวาห์ ข้าพระองค์ร้องทูลพระองค์ เพราะว่าไฟได้เผาผลาญทุ่งหญ้าแห่งถิ่นทุรกันดาร และเปลวไฟได้ไหม้ต้นไม้ในทุ่งนาเสียหมดแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 20, 'ถึงแม้ว่าสัตว์ป่าก็ร้องทูลพระองค์ด้วย เพราะว่าน้ําในห้วยแห้งไป และไฟก็เผาผลาญทุ่งหญ้าแห่งถิ่นทุรกันดาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 1, 'จงเป่าแตรที่ในศิโยน จงเปล่งเสียงปลุกบนภูเขาบริสุทธิ์ของข้าพเจ้า ให้ชาวแผ่นดินทั้งสิ้นตัวสั่น เพราะวันแห่งพระเยโฮวาห์กําลังมาแล้ว ใกล้เข้ามาแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 2, 'เป็นวันแห่งความมืดและความมืดครึ้ม เป็นวันที่มีเมฆและความมืดทึบ ดุจแสงสว่างยามเช้าที่แผ่ปกคลุมไปทั่วภูเขาทั้งหลาย ประชาชนจํานวนมากและมีกําลังยิ่ง ตั้งแต่สมัยโบราณก็ไม่เคยมีเหมือนอย่างนี้ และตั้งแต่นี้ไปก็จะไม่มีอีกตลอดปีทั้งหลายชั่วอายุ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 3, 'ไฟเผาผลาญอยู่ข้างหน้ามันทั้งหลาย และเปลวไฟไหม้อยู่ข้างหลัง แผ่นดินนั้นเหมือนสวนเอเดนก่อนหน้ามันทั้งหลาย พอให้หลังมันไปแล้วก็เป็นถิ่นทุรกันดารที่รกร้าง ไม่มีอะไรจะรอดพ้นมันเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 4, 'ร่างของมันทั้งหลายเหมือนร่างของพวกม้า มันจะวิ่งเหมือนกับม้าสงคราม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 5, 'เหมือนอย่างเสียงรถรบ มันจะเผ่นอยู่บนยอดเขา เหมือนเสียงแตกของเปลวไฟที่ไหม้ตอข้าว เหมือนกองทัพอันเข้มแข็งแปรกระบวนเข้าสงคราม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 6, 'เมื่อชนชาติทั้งหลายเห็นหน้ามันก็จะกระสับกระส่าย ใบหน้าทุกคนก็จะซีดเซียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 7, 'มันทั้งหลายจะวิ่งเหมือนทหาร และปีนกําแพงเหมือนนักรบ ต่างก็จะเดินไปตามทางของตัว มันจะไม่แตกแถวออกไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 8, 'มันทั้งหลายจะไม่รวนกันเลย ต่างก็จะเดินอยู่ในทางของตน เมื่อมันตะลุยดาบ มันก็ไม่ได้รับบาดเจ็บ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 9, 'มันจะกระโดดเข้าในเมือง มันจะวิ่งอยู่บนกําแพงเมือง มันจะปีนเข้าไปในบ้านเรือน มันจะเข้าไปทางหน้าต่างเหมือนกับโจร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 10, 'แผ่นดินโลกจะหวั่นไหวต่อหน้ามัน ฟ้าสวรรค์จะสั่นสะเทือน ดวงอาทิตย์และดวงจันทร์จะมืดไป ดวงดาวจะอับแสง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 11, 'พระเยโฮวาห์จะทรงส่งพระสุรเสียงต่อหน้ากองทัพของพระองค์ เพราะค่ายของพระองค์ใหญ่โตยิ่งนัก ผู้ที่กระทําตามพระวจนะของพระองค์นั้นมีเดชานุภาพมาก เพราะว่าวันแห่งพระเยโฮวาห์เป็นวันใหญ่โตและน่ากลัวยิ่งนัก ผู้ใดเล่าจะทนอยู่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 12, 'พระเยโฮวาห์ตรัสว่า “ดังนั้น เจ้าทั้งหลายจงกลับมาหาเราเสียเดี๋ยวนี้ด้วยความเต็มใจ ด้วยการอดอาหาร ด้วยการร้องไห้และด้วยการโอดครวญ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 13, 'จงฉีกใจของเจ้า มิใช่ฉีกเสื้อผ้าของเจ้า” จงหันกลับมาหาพระเยโฮวาห์พระเจ้าของท่านทั้งหลาย เพราะว่าพระองค์ทรงกอปรด้วยพระคุณและทรงพระกรุณา ทรงกริ้วช้าและบริบูรณ์ด้วยความเมตตา และทรงกลับพระทัยไม่ลงโทษ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 14, 'ใครจะรู้ได้ พระองค์อาจจะทรงกลับและเปลี่ยนพระทัย และทรงอํานวยพระพรไว้ คือให้มีธัญญบูชาและเครื่องดื่มบูชาสําหรับถวายแด่พระเยโฮวาห์พระเจ้าของท่านแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 15, 'จงเป่าแตรที่ในศิโยน จงเตรียมตัวถืออดอาหาร จงเรียกประชุมอันศักดิ์สิทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 16, 'จงรวบรวมบรรดาประชาชน จงชําระชุมนุมชนให้บริสุทธิ์ จงประชุมบรรดาผู้ใหญ่ จงรวบรวมเด็กๆ แม้ว่าเด็กที่ยังกินนม จงให้เจ้าบ่าวออกจากเรือนหอ และเจ้าสาวออกจากห้องของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 17, 'ให้ปุโรหิต คือผู้ปรนนิบัติพระเยโฮวาห์คร่ําครวญอยู่ระหว่างเฉลียงและแท่นบูชา ให้ทูลว่า “โอ ข้าแต่พระเยโฮวาห์ ขอทรงเวทนาประชาชนของพระองค์ ขออย่าทรงกระทําให้มรดกของพระองค์เป็นที่ประณามกัน เพื่อให้ประชาชาติครอบครองเหนือพวกเขา ควรหรือที่เขาจะกล่าวท่ามกลางชนชาติทั้งหลายว่า ‘พระเจ้าของเขาอยู่ที่ไหน’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 18, 'แล้วพระเยโฮวาห์จะทรงหวงแหนแผ่นดินของพระองค์ และทรงสงสารประชาชนของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 19, 'พระเยโฮวาห์จะทรงตอบประชาชนของพระองค์ว่า “ดูเถิด เราจะส่งข้าว น้ําองุ่นและน้ํามันให้แก่เจ้า เจ้าทั้งหลายจะได้อิ่มหนําสําราญ เราจะไม่กระทําให้เจ้าเป็นที่เขาประณามกันท่ามกลางประชาชาติต่อไปอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 20, 'แต่เราจะถอนกองทัพทางทิศเหนือไปให้ห่างไกลจากเจ้า และขับไล่มันเข้าไปในแผ่นดินที่แห้งแล้งและรกร้าง กองหน้าของมันจะหันไปทางทะเลด้านตะวันออก และกองหลังของมันจะหันไปทางทะเลที่อยู่ไกลออกไป กลิ่นเหม็นคลุ้งของมันจะลอยขึ้นมา และกลิ่นเหม็นเน่าของมันจะลอยขึ้นมา เพราะมันทําการใหญ่หลายอย่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 21, 'โอ แผ่นดินเอ๋ย อย่ากลัวเลย จงยินดีและเปรมปรีดิ์เถิด เพราะพระเยโฮวาห์จะทรงทําการใหญ่โตมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 22, 'เจ้าที่เป็นสัตว์ป่าเอ๋ย อย่ากลัวเลย เพราะว่าทุ่งหญ้าในถิ่นทุรกันดารนั้นเขียวสด ต้นไม้เกิดผล ต้นมะเดื่อและเถาองุ่นออกผลอย่างบริบูรณ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 23, 'บุตรทั้งหลายของศิโยนเอ๋ย จงยินดีเถิด จงเปรมปรีดิ์ในพระเยโฮวาห์พระเจ้าของเจ้า เพราะว่าพระองค์ทรงประทานฝนต้นฤดูอย่างพอสมควร พระองค์จะทรงเทฝนลงมาให้เจ้า คือฝนต้นฤดูและฝนชุกปลายฤดูในเดือนแรก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 24, 'ลานนวดข้าวจะมีข้าวอยู่เต็ม จะมีน้ําองุ่นและน้ํามันอยู่เต็มล้นบ่อเก็บ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 25, 'เราจะให้บรรดาปีของเจ้าคืนสู่สภาพเดิม คือที่ตั๊กแตนวัยบินได้กินเสีย ที่ตั๊กแตนวัยกระโดด ตั๊กแตนวัยคลาน และตั๊กแตนวัยเดินได้กิน คือกองทัพใหญ่ของเราที่เราส่งมาท่ามกลางเจ้านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 26, 'เจ้าทั้งหลายจะรับประทานอย่างบริบูรณ์และอิ่มหนําและสรรเสริญพระนามพระเยโฮวาห์พระเจ้าของเจ้า ผู้ทรงกระทําแก่เจ้าอย่างมหัศจรรย์ ประชาชนของเราจะไม่ต้องขายหน้าอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 27, 'เจ้าจะรู้ว่าเราอยู่ท่ามกลางอิสราเอล และเรานี่แหละคือพระเยโฮวาห์เป็นพระเจ้าของเจ้าไม่มีอื่นใดอีก ประชาชนของเราจะไม่ต้องขายหน้าอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 28, 'ต่อมาภายหลังจะเป็นอย่างนี้ คือเราจะเทพระวิญญาณของเรามาเหนือเนื้อหนังทั้งปวง บุตรชายบุตรสาวของเจ้าทั้งหลายจะพยากรณ์ คนชราของเจ้าจะฝันและคนหนุ่มของเจ้าจะเห็นนิมิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 29, 'ในกาลครั้งนั้นเราจะเทพระวิญญาณของเรามาเหนือกระทั่งคนใช้ชายหญิง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 30, 'เราจะสําแดงลางมหัศจรรย์ในท้องฟ้าและบนดิน เป็นเลือดและไฟและเสาควัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 31, 'ดวงอาทิตย์จะกลายเป็นความมืด ดวงจันทร์เป็นเลือดก่อนวันใหญ่ยิ่งและน่าสยดสยองแห่งพระเยโฮวาห์จะมาถึง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 32, 'และอยู่มาจะเป็นอย่างนี้ คือผู้ใดที่จะร้องออกพระนามของพระเยโฮวาห์จะรอดพ้น เพราะจะมีคนรอดพ้นในภูเขาศิโยนและในเยรูซาเล็มตามที่พระเยโฮวาห์ตรัสไว้ และในพวกคนที่รอดนั้นจะมีบรรดาบุคคลที่พระเยโฮวาห์ทรงเรียกด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 1, '“เพราะ ดูเถิด ในวันเหล่านั้นและในเวลานั้น เมื่อเราให้ยูดาห์และเยรูซาเล็มกลับสู่สภาพเดิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 2, 'เราจะรวบรวมบรรดาประชาชาติทั้งสิ้น และนําเขาลงมาที่หุบเขาเยโฮชาฟัท และเราจะเข้าสู่การพิพากษากับเขาที่นั่นด้วยเรื่องประชาชนของเรา คืออิสราเอลมรดกของเรา เพราะว่าเขาได้กระจายชนชาติของเราไปท่ามกลางประชาชาติ และได้แบ่งแผ่นดินของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 3, 'และได้จับฉลากเอาประชาชนของเรา และให้เด็กผู้ชายเป็นข้าของหญิงโสเภณี และขายเด็กผู้หญิงไปซื้อเหล้าองุ่น และดื่ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 4, 'โอ ไทระและไซดอน และประเทศปาเลสไตน์ทุกแคว้นเอ๋ย เจ้าจะเอาอะไรกับเรา เจ้าจะแก้แค้นเราหรือ ถ้าเจ้าสนองเราอยู่ เราจะตอบสนองการกระทําของเจ้าเหนือศีรษะของเจ้าอย่างฉับพลันและอย่างรวดเร็ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 5, 'เพราะเจ้าได้เอาเงินของเราและทองคําของเราไป และเอาทรัพย์สมบัติมั่งคั่งของเราไปยังบรรดาวิหารของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 6, 'เจ้าได้ขายประชาชนยูดาห์และเยรูซาเล็มให้แก่พวกกรีก ถอนเขาไปไกลจากแดนเมืองของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 7, 'ดูเถิด เราจะกระตุ้นเขาจากสถานที่ซึ่งเจ้าขายเขาไปนั้น เราจะตอบสนองการกระทําของเจ้าบนศีรษะของเจ้าเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 8, 'เราจะขายบุตรชายและบุตรสาวของเจ้าไว้ในมือของคนยูดาห์ และเขาทั้งหลายจะขายต่อไปยังคนเชบา แก่ประชาชาติหนึ่งที่อยู่ห่างไกลออกไป เพราะว่าพระเยโฮวาห์ลั่นพระวาจาแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 9, 'จงประกาศข้อความต่อไปนี้ให้นานาประชาชาติทราบว่า จงเตรียมทําการรบ จงปลุกใจชายฉกรรจ์ทั้งหลาย ให้พลรบทั้งสิ้นเข้ามาใกล้ ให้เขาขึ้นมาเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 10, 'จงตีผาลไถนาของเจ้าให้เป็นดาบ และตีขอลิดของเจ้าให้เป็นทวน ให้คนอ่อนแอพูดว่า “ฉันเป็นนักรบ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 11, 'บรรดาประชาชาติทั้งสิ้นเอ๋ย จงรวมกันอยู่ล้อมรอบ จงรีบมาเถิด จงเรียกประชุมกันที่นั่น โอ ข้าแต่พระเยโฮวาห์ ขอทรงนํานักรบของพระองค์ลงมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 12, 'ให้บรรดาประชาชาติตื่นตัวและขึ้นมายังหุบเขาเยโฮชาฟัท เพราะที่นั่นเราจะนั่งพิพากษาบรรดาประชาชาติทั้งสิ้นที่อยู่ล้อมรอบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 13, 'จงเอาเคียวเกี่ยวเถิด เพราะถึงฤดูเกี่ยวแล้ว เข้าไปซิ ย่ําเลย เพราะบ่อย่ําองุ่นกําลังเต็ม บ่อเก็บน้ําองุ่นล้นแล้ว เพราะว่าความชั่วของเขาทั้งหลายมากมายนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 14, 'มวลชน มวลชนในหุบเขาแห่งการตัดสิน เพราะวันแห่งพระเยโฮวาห์ใกล้เข้ามาแล้วในหุบเขาแห่งการตัดสิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 15, 'ดวงอาทิตย์และดวงจันทร์จะมืดไป ดวงดาวจะอับแสง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 16, 'พระเยโฮวาห์จะทรงเปล่งพระสิงหนาทจากศิโยน ทรงเปล่งพระสุรเสียงของพระองค์จากเยรูซาเล็ม และฟ้าสวรรค์กับพิภพก็จะหวั่นไหว แต่พระเยโฮวาห์จะทรงเป็นความหวังแห่งประชาชนของพระองค์ เป็นที่กําบังเข้มแข็งของคนอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 17, '“ดังนั้นเจ้าทั้งหลายจะได้รู้ว่า เราคือพระเยโฮวาห์พระเจ้าของเจ้า ผู้ประทับในศิโยน ภูเขาบริสุทธิ์ของเรา แล้วเยรูซาเล็มจะเป็นเมืองบริสุทธิ์ จะไม่มีคนต่างด้าวผ่านเมืองนั้นไปอีกเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 18, 'และอยู่มาในวันนั้นจะมีน้ําองุ่นใหม่หยดจากภูเขา และมีน้ํานมไหลมาจากเนินเขา และห้วยทั้งสิ้นของยูดาห์จะมีน้ําไหล และน้ําพุจะมาจากพระนิเวศของพระเยโฮวาห์ และรดหุบเขาชิทธิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 19, 'อียิปต์จะกลายเป็นที่รกร้าง และเอโดมจะกลายเป็นถิ่นทุรกันดารร้าง เพราะเหตุความรุนแรงที่กระทําต่อชนชาติยูดาห์ เพราะว่าเขากระทําให้โลหิตที่ปราศจากความผิดตกในแผ่นดินของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 20, 'แต่ยูดาห์จะมีคนอาศัยอยู่เป็นนิตย์ และเยรูซาเล็มจะมีผู้อาศัยอยู่ทุกชั่วอายุ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 21, 'ด้วยว่าเราจะชําระเลือดของเขาซึ่งเรายังมิได้ชําระ เพราะพระเยโฮวาห์ทรงสถิตในศิโยน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 1, 'ถ้อยคําของอาโมส ผู้อยู่ในหมู่ผู้เลี้ยงแกะในเมืองเทโคอา ซึ่งท่านได้เห็นเกี่ยวกับอิสราเอล ในรัชกาลอุสซียาห์ กษัตริย์แห่งยูดาห์ และในรัชกาลเยโรโบอัม ราชโอรสของโยอาช กษัตริย์แห่งอิสราเอล ก่อนแผ่นดินไหวสองปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 2, 'ท่านกล่าวว่า “พระเยโฮวาห์จะทรงเปล่งพระสิงหนาทจากศิโยน และจะทรงเปล่งพระสุรเสียงของพระองค์จากเยรูซาเล็ม ลานหญ้าของผู้เลี้ยงแกะจะโศกเศร้า และยอดภูเขาคารเมลก็จะเหี่ยวไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 3, 'พระเยโฮวาห์ตรัสดังนี้ว่า “เพราะเหตุการละเมิดของดามัสกัส สามครั้งและสี่ครั้ง เราจะไม่ยอมกลับการลงทัณฑ์ เพราะว่าเขาทั้งหลายได้นวดกิเลอาดด้วยเลื่อนเหล็กสําหรับนวดข้าว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 4, 'แต่ เราจะส่งไฟเข้ามาในเรือนของฮาซาเอล ซึ่งจะเผาผลาญปราสาททั้งหลายของเบนฮาดัดเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 5, 'เราจะหักดาลประตูเมืองดามัสกัส และตัดผู้ที่อาศัยอยู่ออกเสียจากที่ราบอาเวน และผู้นั้นที่ถือคทาจากวงศ์วานของเอเดน และประชาชนซีเรียจะต้องตกไปเป็นเชลยยังเมืองคีร์” พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 6, 'พระเยโฮวาห์ตรัสดังนี้ว่า “เพราะเหตุการละเมิดของกาซา สามครั้งและสี่ครั้ง เราจะไม่ยอมกลับการลงทัณฑ์ เพราะเขากวาดประชาชนทั้งหมดไปเป็นเชลย เพื่อจะมอบให้แก่เอโดม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 7, 'แต่ เราจะส่งไฟมาบนกําแพงเมืองกาซา ซึ่งจะเผาผลาญปราสาททั้งหลายของเมืองนั้นเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 8, 'เราจะตัดผู้ที่อาศัยอยู่ออกเสียจากอัชโดด และผู้ที่ถือคทาออกจากเมืองอัชเคโลน เราจะหันมือของเราต่อสู้เอโครน ชาวฟีลิสเตียที่เหลืออยู่จะพินาศ” องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 9, 'พระเยโฮวาห์ตรัสดังนี้ว่า “เพราะเหตุการละเมิดของเมืองไทระ สามครั้งและสี่ครั้ง เราจะไม่ยอมกลับการลงทัณฑ์ เพราะเขาได้มอบประชาชนทั้งหมดให้แก่เอโดม และไม่ได้ระลึกถึงพันธสัญญาแห่งภราดรภาพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 10, 'แต่ เราจะส่งไฟมาบนกําแพงเมืองไทระ ซึ่งจะเผาผลาญปราสาททั้งหลายของเมืองนั้นเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 11, 'พระเยโฮวาห์ตรัสดังนี้ว่า “เพราะเหตุการละเมิดของเมืองเอโดม สามครั้งและสี่ครั้ง เราจะไม่ยอมกลับการลงทัณฑ์ เพราะเขาได้ไล่ตามน้องของเขาด้วยดาบ และสลัดความสงสารทิ้งเสียสิ้น ความโกรธของเขาบั่นทอนอยู่ตลอดกาล และความพิโรธของเขาก็มีอยู่เป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 12, 'แต่ เราจะส่งไฟมาบนเมืองเทมาน ซึ่งจะเผาผลาญปราสาททั้งหลายของเมืองโบสราห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 13, 'พระเยโฮวาห์ตรัสดังนี้ว่า “เพราะเหตุการละเมิดของคนอัมโมน สามครั้งและสี่ครั้ง เราจะไม่ยอมกลับการลงทัณฑ์ เพราะว่าเขาได้ผ่าท้องหญิงมีครรภ์ในเมืองกิเลอาด เพื่อจะขยายอาณาเขตของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 14, 'แต่ เราจะจุดไฟขึ้นในกําแพงเมืองรับบาห์ และไฟจะเผาผลาญปราสาททั้งหลายของเมืองนั้นเสีย พร้อมด้วยเสียงโห่ร้องในวันทําศึก พร้อมด้วยพายุอันแรงกล้าในวันที่มีลมหมุน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 15, 'กษัตริย์ของเขาทั้งหลายจะตกไปเป็นเชลย ทั้งตัวท่านและเจ้านายของท่านด้วย” พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 1, 'พระเยโฮวาห์ตรัสดังนี้ว่า “เพราะเหตุการละเมิดของเมืองโมอับ สามครั้งและสี่ครั้ง เราจะไม่ยอมกลับการลงทัณฑ์ เพราะเขาได้เผากระดูกของกษัตริย์เอโดมให้เป็นปูน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 2, 'แต่ เราจะส่งไฟมาบนโมอับ และไฟนั้นจะเผาผลาญปราสาททั้งหลายของเคริโอทเสีย และโมอับจะตายท่ามกลางเสียงสับสนอลหม่าน ท่ามกลางเสียงโห่ร้องและเสียงแตร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 3, 'เราจะตัดผู้วินิจฉัยออกเสียจากท่ามกลางเมืองนั้น และจะประหารเจ้านายทั้งหลายของเมืองนั้นเสียพร้อมกับผู้วินิจฉัย” พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 4, 'พระเยโฮวาห์ตรัสดังนี้ว่า “เพราะเหตุการละเมิดของยูดาห์ สามครั้งและสี่ครั้ง เราจะไม่ยอมกลับการลงทัณฑ์ เพราะว่าเขาปฏิเสธไม่รับพระราชบัญญัติของพระเยโฮวาห์ และมิได้รักษาพระบัญญัติของพระองค์ และการมุสาของเขาได้พาให้เขาหลงเจิ่นไป ตามเยี่ยงที่บิดาของเขาได้ดําเนินมาแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 5, 'แต่ เราจะส่งไฟมาบนยูดาห์ และไฟนั้นจะเผาผลาญปราสาททั้งหลายของเยรูซาเล็มเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 6, 'พระเยโฮวาห์ตรัสดังนี้ว่า “เพราะเหตุการละเมิดของอิสราเอล สามครั้งและสี่ครั้ง เราจะไม่ยอมกลับการลงทัณฑ์ เพราะเขาได้ขายคนชอบธรรมเอาเงิน และขายคนขัดสนเอารองเท้าคู่เดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 7, 'ซึ่งกระหายหาฝุ่นละอองแห่งแผ่นดินโลกบนศีรษะของคนจน และผลักคนที่ถ่อมใจออกเสียจากหนทางของเขา บุตรชายและบิดาของเขาเข้าหาหญิงคนเดียวกัน เพื่อลบหลู่นามบริสุทธิ์ของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 8, 'ตัวเขาเองนอนอยู่ข้างแท่นบูชาทุกแท่น อยู่บนเสื้อผ้าที่เขายึดมาเป็นประกัน และในนิเวศแห่งพระของเขา เขาทั้งหลายดื่มเหล้าองุ่นสําหรับผู้ที่ถูกปรับโทษ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 9, 'เรายังได้ล้างผลาญคนอาโมไรต์ตรงหน้าเขา ซึ่งส่วนสูงของเขาเหมือนอย่างความสูงของต้นสนสีดาร์ และเป็นผู้ที่แข็งแรงอย่างกับต้นโอ๊ก เราทําลายผลข้างบนของเขาเสีย และทําลายรากข้างล่างของเขาเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 10, 'เรานําเจ้าขึ้นมาจากแผ่นดินอียิปต์ และได้นําเจ้าถึงสี่สิบปีในถิ่นทุรกันดาร เพื่อจะได้กรรมสิทธิ์ที่ดินของคนอาโมไรต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 11, 'เราได้ตั้งบุตรชายบางคนของเจ้าให้เป็นผู้พยากรณ์ และได้ตั้งชายหนุ่มบางคนของเจ้าให้เป็นพวกนาศีร์ โอ คนอิสราเอลเอ๋ย ไม่เป็นความจริงดังนี้หรือ” พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 12, '“แต่เจ้าทั้งหลายได้กระทําให้พวกนาศีร์ดื่มเหล้าองุ่น และบัญชาพวกผู้พยากรณ์สั่งว่า ‘เจ้าอย่าพยากรณ์เลย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 13, 'ดูเถิด เจ้ากดเราลง เหมือนเกวียนที่เต็มด้วยฟ่อนข้าวกดยัดลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 14, 'ฉะนั้นการหลบหนีจะสูญไปจากผู้มีฝีเท้ารวดเร็ว คนที่แข็งแรงจะไม่สามารถเสริมกําลังของเขา คนที่มีกําลังมากจะช่วยชีวิตของตนก็ไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 15, 'ผู้ที่ถือคันธนูจะไม่ยืนยงอยู่ได้ ผู้มีฝีเท้าเร็วก็ช่วยตัวเองให้รอดพ้นไม่ได้ หรือผู้ที่ขี่ม้าก็ช่วยตัวเองให้รอดพ้นไม่ได้เหมือนกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 16, 'และผู้ที่มีใจกล้าหาญท่ามกลางผู้มีกําลังเข้มแข็งเหล่านั้นจะหนีไปอย่างเปลือยเปล่าในวันนั้น” พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 1, 'โอ คนอิสราเอลเอ๋ย จงฟังพระวจนะนี้ซึ่งพระเยโฮวาห์ตรัสกล่าวโทษท่านทั้งหลาย คือกล่าวโทษหมดทั้งครอบครัวซึ่งเราได้นําออกจากแผ่นดินอียิปต์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 2, '“ในบรรดาครอบครัวทั้งสิ้นในโลกนี้ เจ้าเท่านั้นที่เรารู้จัก ดังนั้นเราจึงจะลงโทษเจ้าเพราะความชั่วช้าทั้งสิ้นของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 3, 'สองคนจะเดินไปด้วยกันได้หรือนอกจากทั้งสองจะได้ตกลงกันไว้ก่อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 4, 'สิงโตจะแผดเสียงดังอยู่ในป่าเมื่อมันไม่มีเหยื่อหรือ ถ้าสิงโตหนุ่มจับสัตว์อะไรไม่ได้เลย มันจะร้องออกมาจากถ้ําของมันหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 5, 'ถ้าไม่มีเหยื่อล่อไว้ นกจะลงมาติดกับบนดินได้หรือ ถ้าไม่มีอะไรเข้าไปติดกับ กับจะลั่นขึ้นจากดินได้หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 6, 'เขาจะเป่าแตรในเมือง และประชาชนไม่ตกใจกลัวอะไรหรือ จะมีภัยตกอยู่ในเมืองหนึ่งเมืองใดหรือ นอกจากว่าพระเยโฮวาห์ทรงกระทําเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 7, 'แท้จริงองค์พระผู้เป็นเจ้าพระเจ้าจะมิได้ทรงกระทําอะไรเลย โดยมิได้เปิดเผยความลึกลับให้แก่ผู้รับใช้ของพระองค์ คือผู้พยากรณ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 8, 'สิงโตแผดเสียงร้องแล้ว ผู้ใดจะไม่กลัวบ้าง องค์พระผู้เป็นเจ้าพระเจ้าตรัสแล้ว จะมีผู้ใดที่จะไม่พยากรณ์หรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 9, 'จงประกาศในปราสาททั้งหลายที่อัชโดด และในปราสาททั้งหลายในแผ่นดินอียิปต์ และกล่าวว่า “จงประชุมกันบนภูเขาแห่งสะมาเรีย และพินิจดูความโกลาหลอันยิ่งใหญ่มากมายและผู้ที่ถูกกดขี่ทั้งหลายท่ามกลางเมืองนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 10, 'พระเยโฮวาห์ตรัสว่า “เพราะเขาไม่รู้จักที่จะกระทําให้ถูกต้อง คือผู้ที่ส่ําสมความรุนแรงและการโจรกรรมไว้ในปราสาททั้งหลายของเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 11, 'เพราะฉะนั้น องค์พระผู้เป็นเจ้าพระเจ้าจึงตรัสดังนี้ว่า “จะมีปฏิปักษ์ผู้หนึ่งมาล้อมแผ่นดินไว้ และเขาจะบั่นทอนขุมกําลังเสียจากเจ้า และปราสาททั้งหลายของเจ้าจะถูกปล้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 12, 'พระเยโฮวาห์ตรัสดังนี้ว่า “ผู้เลี้ยงแกะชิงเอาขาสองขาหรือหูชิ้นหนึ่งมาจากปากสิงโตได้ฉันใด คนอิสราเอลผู้อยู่ที่มุมหนึ่งของเตียงในสะมาเรีย และบนที่นอนในดามัสกัสจะได้รับการช่วยให้พ้นได้ฉันนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 13, 'องค์พระผู้เป็นเจ้าพระเจ้า พระเจ้าจอมโยธาตรัสว่า “ฟังซิ และเป็นพยานกล่าวโทษวงศ์วานของยาโคบเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 14, 'ว่าในวันที่เราทําโทษอิสราเอลเรื่องการละเมิดของเขา เราจะทําโทษแท่นบูชาทั้งหลายของเมืองเบธเอลด้วย เชิงงอนที่แท่นบูชานั้นจะถูกตัดออกและตกลงที่ดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 15, 'เราจะโจมตีเรือนพักฤดูหนาวพร้อมกับเรือนพักฤดูร้อน และเรือนที่ทําด้วยงาช้างจะพินาศ และเรือนใหญ่ๆทั้งสิ้นจะสูญสิ้นไป” พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 1, '“แม่วัวทั้งหลายแห่งเมืองบาชานเอ๋ย จงฟังคํานี้เถิด คือผู้ที่อยู่ในภูเขาสะมาเรีย ผู้ที่บีบบังคับคนยากจน และขยี้คนขัดสน ผู้ที่กล่าวแก่นายของตนว่า ‘เอามาซิคะ เราจะได้ดื่มกัน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 2, 'องค์พระผู้เป็นเจ้าพระเจ้าทรงปฏิญาณไว้ด้วยความบริสุทธิ์ของพระองค์ว่า ดูเถิด วันทั้งหลายจะมาถึงเจ้า เขาจะเอาขอเกี่ยวเจ้าไป จนถึงคนสุดท้ายของเจ้า เขาก็จะเกี่ยวไปด้วยเบ็ด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 3, 'และเจ้าจะออกไปตามช่องกําแพง แม่วัวทั้งหลายจะออกไปตามช่องตรงข้างหน้าตน และเจ้าจะทิ้งมันเข้าไปในวังนั้น” พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 4, '“จงมาที่เบธเอล มาทําการละเมิด มาที่กิลกาลซิ มาทําการละเมิดให้ทวีมากขึ้น จงนําเครื่องสัตวบูชาของเจ้ามาทุกเช้า และนําสิบชักหนึ่งของเจ้าหลังจากสามปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 5, 'จงเผาบูชาโมทนาด้วยใช้สิ่งที่มีเชื้อ และประกาศการถวายบูชาด้วยใจสมัคร จงโฆษณา โอ คนอิสราเอลเอ๋ย เจ้ารักที่จะกระทําอย่างนี้นี่นะ” องค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 6, '“ทั่วไปทุกเมือง เราให้ฟันของเจ้าสะอาด สถานที่ทุกแห่งของเจ้าก็ขาดอาหาร เจ้าก็ยังไม่กลับมาหาเรา” พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 7, '“เราได้ยับยั้งฝนไว้เสียจากเจ้าด้วย เมื่อก่อนถึงฤดูเกี่ยวสามเดือน เราให้ฝนตกในเมืองหนึ่ง อีกเมืองหนึ่งไม่ให้ฝน นาแห่งหนึ่งมีฝนตก และนาที่ไม่มีฝนก็เหี่ยวแห้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 8, 'ดังนั้นชาวเมืองสองสามเมืองก็ดั้นด้นไปหาอีกเมืองหนึ่งเพื่อจะหาน้ําดื่ม และไม่รู้จักอิ่ม เจ้าก็ยังไม่กลับมาหาเรา” พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 9, '“เราโจมตีเจ้าด้วยให้ข้าวม้านและขึ้นรา เมื่อบรรดาสวนของเจ้าและสวนองุ่นของเจ้า พร้อมต้นมะเดื่อและต้นมะกอกเทศของเจ้าผลิตผล ตั๊กแตนก็มากิน เจ้าก็ยังไม่กลับมาหาเรา” พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 10, '“เราให้โรคระบาดอย่างที่เกิดในอียิปต์มาเกิดท่ามกลางเจ้า เราประหารคนหนุ่มของเจ้าเสียด้วยดาบ ทั้งเอาม้าทั้งหลายของเจ้าไปเสีย และกระทําให้ความเน่าเหม็นที่ค่ายของเจ้าคลุ้งเข้าจมูกเจ้า เจ้าก็ยังไม่กลับมาหาเรา” พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 11, '“เราคว่ําเจ้าเสียบ้าง อย่างที่พระเจ้าคว่ําเมืองโสโดมและเมืองโกโมราห์ เจ้าเหมือนดุ้นฟืนที่เขาหยิบออกมาจากกองไฟ เจ้าก็ยังไม่กลับมาหาเรา” พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 12, '“โอ อิสราเอลเอ๋ย เพราะฉะนั้นเราจะต้องกระทํากับเจ้าดังนี้ เพราะเราจะต้องกระทําเช่นนี้แก่เจ้า โอ อิสราเอลเอ๋ย จงเตรียมตัวเพื่อจะเผชิญพระเจ้าของเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 13, 'เพราะดูเถิด พระองค์ผู้ปั้นภูเขาและสร้างลม และทรงประกาศพระดําริของพระองค์แก่มนุษย์ ผู้ทรงกระทําให้รุ่งสว่างกลายเป็นความมืด และทรงดําเนินบนที่สูงของพิภพ พระนามของพระองค์ คือพระเยโฮวาห์พระเจ้าจอมโยธา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 1, 'โอ วงศ์วานอิสราเอลเอ๋ย จงฟังถ้อยคํานี้ ซึ่งเราคร่ําครวญถึงเจ้าว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 2, '“พรหมจารีแห่งอิสราเอลล้มลงแล้ว และเธอจะไม่ลุกขึ้นอีก เธอถูกทิ้งไว้บนแผ่นดินของเธอ ไม่มีผู้ใดพยุงเธอขึ้นอีก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 3, 'เพราะว่าองค์พระผู้เป็นเจ้าพระเจ้าตรัสดังนี้ว่า “เมืองที่มีคนออกไปพันหนึ่งจะเหลือกลับมาหนึ่งร้อยคน และซึ่งมีออกไปหนึ่งร้อยคนจะเหลือสิบคนแก่วงศ์วานของอิสราเอล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 4, 'เพราะพระเยโฮวาห์ตรัสแก่วงศ์วานอิสราเอลดังนี้ว่า “จงแสวงหาเรา และเจ้าจะดํารงชีวิตอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 5, 'แต่อย่าแสวงหาเบธเอล และอย่าเข้าไปในกิลกาล หรือข้ามไปยังเบเออร์เชบา เพราะว่ากิลกาลจะต้องตกไปเป็นเชลยเป็นแน่ และเบธเอลก็จะสูญไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 6, 'จงแสวงหาพระเยโฮวาห์และเจ้าจะดํารงชีวิตอยู่ เกรงว่าพระองค์จะทรงพลุ่งออกมาอย่างไฟในวงศ์วานโยเซฟ ไฟจะเผาผลาญ และไม่มีผู้ใดดับให้เบธเอลได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 7, 'เจ้าทั้งหลายผู้เปลี่ยนความยุติธรรมให้ขมอย่างบอระเพ็ด และเหวี่ยงความชอบธรรมลงสู่พื้นดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 8, 'จงแสวงหาพระองค์ผู้ทรงสร้างหมู่ดาวลูกไก่และหมู่ดาวไถ และเป็นผู้ทรงกลับเงามัจจุราชให้เป็นรุ่งเช้า และทรงกระทํากลางวันให้มืดเป็นกลางคืน ผู้ทรงเรียกน้ําทะเลมาและโปรยน้ํานั้นลงบนพื้นพิภพ พระเยโฮวาห์คือพระนามของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 9, 'ผู้ทรงกระทําให้ผู้ที่ถูกปล้นเข้าต่อสู้ผู้แข็งแรง ผู้ที่ถูกปล้นจึงเข้าสู้ป้อมปราการ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 10, 'เขาทั้งหลายเกลียดผู้ที่กล่าวเตือนที่ประตูเมือง และเขาทั้งหลายสะอิดสะเอียนผู้ที่พูดอย่างเที่ยงธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 11, 'เพราะว่าเจ้าทั้งหลายเหยียบย่ําคนยากจน และเอาส่วยข้าวสาลีไปเสียจากเขา เจ้าจึงสร้างตึกด้วยศิลาสกัด แต่เจ้าจะไม่ได้อยู่ในตึกนั้น เจ้าทําสวนองุ่นที่ร่มรื่น แต่เจ้าจะไม่ได้ดื่มน้ําองุ่นจากสวนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 12, 'เพราะเรารู้ว่าการละเมิดของเจ้ามีเท่าใด และบาปของเจ้ามากมายสักเท่าใด เจ้าทั้งหลายผู้ข่มใจคนชอบธรรม ผู้รับสินบน และขับไล่คนขัดสนออกไปเสียจากประตูเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 13, 'เพราะฉะนั้น คนที่มีปัญญาจะนิ่งเสียในเวลาเช่นนั้น เพราะเป็นเวลาชั่วร้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 14, 'จงแสวงหาความดี อย่าแสวงหาความชั่ว เพื่อเจ้าจะดํารงชีวิตอยู่ได้ พระเยโฮวาห์พระเจ้าจอมโยธาจึงจะทรงสถิตกับเจ้าดังที่เจ้ากล่าวแล้วนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 15, 'จงเกลียดชังความชั่ว และรักความดี และตั้งความยุติธรรมไว้ที่ประตูเมือง ชะรอยพระเยโฮวาห์พระเจ้าจอมโยธาจะทรงพระกรุณาต่อวงศ์วานโยเซฟที่เหลืออยู่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 16, 'เพราะฉะนั้น พระเยโฮวาห์พระเจ้าจอมโยธา องค์พระผู้เป็นเจ้าตรัสดังนี้ว่า “ตามถนนทุกสายจะมีการร่ําไห้ และตามบรรดาถนนหลวงจะมีคนพูดว่า ‘อนิจจาเอ๋ย อนิจจาเอ๋ย’ เขาจะร้องเรียกชาวนาให้ไว้ทุกข์ และให้ผู้ชํานาญเพลงโศกเศร้าร้องโอดครวญ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 17, 'ในสวนองุ่นทั้งสิ้นจะมีการร่ําไห้ เพราะเราจะผ่านไปท่ามกลางเจ้า” พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 18, 'วิบัติแก่เจ้า ผู้ปรารถนาวันแห่งพระเยโฮวาห์ วันนั้นจะเป็นประโยชน์อะไรแก่เจ้าเล่า วันแห่งพระเยโฮวาห์เป็นความมืด ไม่ใช่เป็นความสว่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 19, 'อย่างกับคนหนีสิงโตไปปะหมี หรือเหมือนคนเข้าไปในเรือนเอามือเท้าฝาผนังและงูก็กัดเอา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 20, 'วันแห่งพระเยโฮวาห์จะเป็นความมืด ไม่ใช่ความสว่าง เป็นความมืดคลุ้ม ไม่มีความแจ่มใสเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 21, '“เราเกลียดชัง เราดูหมิ่นบรรดาวันเทศกาลของเจ้า และจะไม่ดมกลิ่นในการประชุมอันศักดิ์สิทธิ์ของเจ้าเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 22, 'แม้ว่าเจ้าถวายเครื่องเผาบูชาและธัญญบูชาแก่เรา เราจะไม่ยอมรับสิ่งเหล่านั้น และสันติบูชาด้วยสัตว์อ้วนพีของเจ้านั้น เราจะไม่มองดู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 23, 'จงนําเสียงเพลงของเจ้าไปเสียจากเรา เพราะเราจะไม่ฟังเสียงพิณใหญ่ของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 24, 'แต่จงให้ความยุติธรรมหลั่งไหลลงอย่างน้ํา และให้ความชอบธรรมเป็นอย่างลําธารที่ไหลอยู่เป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 25, 'โอ วงศ์วานอิสราเอลเอ๋ย เจ้าได้นําเครื่องบูชาและเครื่องสัตวบูชาถวายแก่เราในถิ่นทุรกันดารถึงสี่สิบปีหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 26, 'เจ้าทั้งหลายได้หามพลับพลาของพระโมเลคและพระชีอัน รูปเคารพของเจ้า คือดาวแห่งพระของเจ้า ซึ่งเจ้าได้ทําไว้สําหรับตัวเจ้าเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 27, 'เพราะฉะนั้น เราจะนําเจ้าให้ไปเป็นเชลย ณ ที่เลยเมืองดามัสกัสไป” พระเยโฮวาห์ ซึ่งทรงพระนามว่าพระเจ้าจอมโยธา ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 1, '“วิบัติแก่ผู้ที่เอกเขนกอยู่ในศิโยน และวางใจอยู่ในภูเขาสะมาเรีย คือผู้มีชื่อเสียงแห่งประชาชาติชั้นเอกในบรรดาประชาชาติทั้งหลาย ผู้ซึ่งวงศ์วานอิสราเอลมาหานั่นน่ะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 2, 'จงไปยังเมืองคาลเนห์ และดูเอาเถอะ จากที่นั่นก็ไปยังฮามัทเมืองใหญ่ แล้วลงไปยังเมืองกัทของชาวฟีลิสเตีย เมืองเหล่านั้นดีกว่าอาณาจักรเหล่านี้หรือ หรืออาณาเขตเมืองเหล่านั้นใหญ่กว่าอาณาเขตเมืองของเจ้าหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 3, 'เจ้าผู้ที่อยากผลัดวันสนองความร้ายให้เนิ่นไป แต่กลับนําเอาบัลลังก์แห่งความทารุณให้เข้ามาใกล้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 4, 'วิบัติแก่ผู้ที่นอนบนเตียงงาช้าง และผู้ซึ่งเหยียดตัวอยู่บนเก้าอี้ยาว และกินลูกแกะที่ได้มาจากฝูงแกะ และลูกวัวจากท่ามกลางคอกวัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 5, 'และร้องเพลงไร้สาระประสานเสียงพิณใหญ่ กระทําอย่างดาวิดในการประดิษฐ์เครื่องดนตรีขึ้นใหม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 6, 'ผู้ใช้ชามใส่น้ําองุ่นดื่ม และชโลมตัวด้วยน้ํามันอย่างดี แต่มิได้เป็นทุกข์โศกในเรื่องความทุกข์ยากของโยเซฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 7, 'เพราะฉะนั้นบัดนี้เขาจะต้องไปเป็นเชลยกับพวกแรกที่ตกไปเป็นเชลย และเสียงอึงคะนึงของพวกที่นอนเหยียดตัวก็หมดสิ้นไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 8, 'องค์พระผู้เป็นเจ้าพระเจ้าได้ทรงปฏิญาณต่อพระองค์เองว่า พระเยโฮวาห์พระเจ้าจอมโยธาตรัสว่า “เราสะอิดสะเอียนความล้ําเลิศของยาโคบ และเกลียดปราสาททั้งหลายของเขา เราจะมอบเมืองนั้นและบรรดาสิ่งสารพัดที่อยู่ในเมืองนั้นเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 9, 'ต่อมาถ้าในเรือนเดียวมีคนเหลืออยู่สิบคน เขาจะต้องตายหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 10, 'และเมื่อลุงของผู้ใด คือผู้ที่เผาเพื่อเขา จะยกศพขึ้นเพื่อจะนํากระดูกออกนอกเรือน และจะกล่าวกับคนที่อยู่ในห้องชั้นในที่สุดของเรือนนั้นว่า “ยังมีใครอยู่กับเจ้าหรือ” เขาจะตอบว่า “ไม่มี” และเขาจะกล่าวว่า “จุ๊ จุ๊ อย่าให้เราออกพระนามของพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 11, 'เพราะดูเถิด พระเยโฮวาห์ทรงบัญชาแล้ว พระองค์จะทรงฟาดเรือนใหญ่ให้แตกเป็นชิ้นๆ และเรือนเล็กก็จะแตกเป็นจุณ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 12, 'ม้าจะวิ่งบนศิลาหรือ มีคนหนึ่งคนใดใช้วัวไถที่นั่นหรือ แต่เจ้าทั้งหลายได้กลับความยุติธรรมให้ขมอย่างดีหมี และเปลี่ยนผลของความชอบธรรมให้ขมอย่างบอระเพ็ด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 13, 'เจ้าทั้งหลายผู้เปรมปรีดิ์อยู่ในสิ่งอันไร้สาระ ผู้ซึ่งกล่าวว่า “เราได้ยึดเขาสัตว์มาเป็นของเราด้วยกําลังของเรามิใช่หรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 14, 'พระเยโฮวาห์พระเจ้าจอมโยธาตรัสดังนี้ว่า “เพราะ ดูเถิด โอ วงศ์วานอิสราเอลเอ๋ย เราจะยกประชาชาติหนึ่งให้ขึ้นต่อสู้เจ้า และเขาจะบีบบังคับเจ้าตั้งแต่ทางเข้าเมืองฮามัทถึงแม่น้ําแห่งถิ่นทุรกันดาร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 1, 'องค์พระผู้เป็นเจ้าพระเจ้าทรงสําแดงแก่ข้าพเจ้าดังนี้ว่า ดูเถิด พระองค์ทรงสร้างตั๊กแตน เมื่อพืชรุ่นหลังเริ่มงอกขึ้นมา และดูเถิด เป็นพืชรุ่นหลังจากที่กษัตริย์ได้เกี่ยวแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 2, 'และต่อมาเมื่อตั๊กแตนกินหญ้าในแผ่นดินนั้นหมดแล้ว ข้าพเจ้าจึงว่า “โอ ข้าแต่องค์พระผู้เป็นเจ้าพระเจ้า ขอทรงให้อภัย ยาโคบจะตั้งอยู่ได้อย่างไร เพราะเขาเล็กนิดเดียว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 3, 'เกี่ยวด้วยเรื่องนี้พระเยโฮวาห์ทรงกลับพระทัย พระเยโฮวาห์ตรัสว่า “จะไม่เป็นไปอย่างนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 4, 'องค์พระผู้เป็นเจ้าพระเจ้าทรงสําแดงแก่ข้าพเจ้าอย่างนี้ว่า ดูเถิด องค์พระผู้เป็นเจ้าพระเจ้าทรงเรียกให้มีการสู้ความด้วยไฟ และไฟได้เผาผลาญมหาสมุทรใหญ่ และกินส่วนหนึ่งเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 5, 'ข้าพเจ้าจึงทูลว่า “โอ ข้าแต่องค์พระผู้เป็นเจ้าพระเจ้า ขอพระองค์ทรงยับยั้งไว้ ยาโคบจะตั้งอยู่ได้อย่างไร เพราะเขาเล็กนิดเดียว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 6, 'เกี่ยวด้วยเรื่องนี้พระเยโฮวาห์ทรงกลับพระทัย องค์พระผู้เป็นเจ้าพระเจ้าตรัสว่า “จะไม่เป็นไปอย่างนั้นด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 7, 'พระองค์ทรงสําแดงแก่ข้าพเจ้าว่า ดูเถิด องค์พระผู้เป็นเจ้าประทับยืนอยู่ที่ข้างกําแพงสร้างด้วยใช้สายดิ่ง มีสายดิ่งอยู่ในพระหัตถ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 8, 'และพระเยโฮวาห์ตรัสกับข้าพเจ้าว่า “อาโมสเอ๋ย เจ้าเห็นอะไร” และข้าพเจ้าทูลว่า “สายดิ่งเส้นหนึ่ง พระเจ้าข้า” แล้วองค์พระผู้เป็นเจ้าตรัสว่า “ดูเถิด เราจะเอาสายดิ่งจับท่ามกลางอิสราเอลประชาชนของเรา เราจะไม่ผ่านเขาไปอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 9, 'สถานที่อันสูงทั้งหลายของอิสอัคจะรกร้างไป และสถานบริสุทธิ์ทั้งหลายของอิสราเอลจะถูกทิ้งไว้เสียเปล่า และเราจะลุกขึ้นต่อสู้วงศ์วานเยโรโบอัมด้วยดาบ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 10, 'แล้วอามาซิยาห์ปุโรหิตแห่งเบธเอลส่งคนไปยังเยโรโบอัมกษัตริย์แห่งอิสราเอล ทูลว่า “อาโมสได้คิดกบฏต่อพระองค์ในท่ามกลางวงศ์วานอิสราเอล บรรดาถ้อยคําของเขาก็หนักแผ่นดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 11, 'เพราะอาโมสได้กล่าวดังนี้ว่า ‘เยโรโบอัมจะสิ้นชีวิตด้วยดาบ และอิสราเอลจะตกไปเป็นเชลยห่างจากแผ่นดินของเขา’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 12, 'และอามาซิยาห์พูดกับอาโมสว่า “โอ ท่านผู้ทํานาย ไปเถิด จงหนีไปเสียที่แผ่นดินยูดาห์ ไปรับประทานอาหารที่นั่น และพยากรณ์ที่นั่นเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 13, 'อย่ามาพยากรณ์ที่เบธเอลอีกเลย เพราะว่านี้เป็นสถานบริสุทธิ์ของกษัตริย์ และเป็นพระราชสํานักของกษัตริย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 14, 'อาโมสจึงตอบอามาซิยาห์ว่า “ข้าพเจ้าไม่ใช่ผู้พยากรณ์ หรือลูกชายของผู้พยากรณ์ ข้าพเจ้าเป็นคนเลี้ยงสัตว์ และเป็นคนเก็บผลมะเดื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 15, 'และพระเยโฮวาห์ทรงนําข้าพเจ้ามาจากการติดตามฝูงแพะแกะ และพระเยโฮวาห์ตรัสกับข้าพเจ้าว่า ‘ไปซิ จงพยากรณ์แก่อิสราเอลประชาชนของเรา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 16, 'ฉะนั้นบัดนี้ จงฟังพระวจนะของพระเยโฮวาห์ ท่านกล่าวว่า ‘อย่าพยากรณ์กล่าวโทษอิสราเอล และอย่าเทศนากล่าวโทษวงศ์วานอิสอัค’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 17, 'เพราะฉะนั้น พระเยโฮวาห์จึงตรัสดังนี้ว่า ‘ภรรยาของท่านจะเป็นหญิงโสเภณีที่ในเมือง บุตรชายหญิงของท่านจะล้มลงตายด้วยดาบ และที่ดินของท่านเขาจะขึงเส้นแบ่งออก ตัวท่านเองจะสิ้นชีวิตในแผ่นดินที่ไม่สะอาด และอิสราเอลจะต้องตกไปเป็นเชลยห่างจากแผ่นดินของตนเป็นแน่’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 1, 'องค์พระผู้เป็นเจ้าพระเจ้าทรงสําแดงแก่ข้าพเจ้าดังนี้ว่า ดูเถิด มีกระจาดผลไม้ฤดูร้อนกระจาดหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 2, 'และพระองค์ตรัสว่า “อาโมส เจ้าเห็นอะไร” และข้าพเจ้าทูลว่า “ผลไม้ฤดูร้อนกระจาดหนึ่ง พระเจ้าข้า” แล้วพระเยโฮวาห์ตรัสกับข้าพเจ้าว่า “วันสิ้นสุดมาถึงอิสราเอลประชาชนของเราแล้ว เราจะไม่ผ่านเขาไปอีกเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 3, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสว่า “ในวันนั้น เสียงเพลงในพระวิหารจะเป็นเสียงร่ําไห้ จะมีศพมากมายทุกแห่งทิ้งไว้เงียบๆ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 4, 'โอ ท่านผู้เหยียบย่ําคนขัดสน ท่านผู้ทําลายคนยากจนแห่งแผ่นดิน จงฟังถ้อยคํานี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 5, 'โดยกล่าวว่า “เมื่อไรหนอวันขึ้นหนึ่งค่ําจะหมดไป เราจะได้ขายข้าวของเรา เมื่อไรหนอวันสะบาโตจะพ้นไป เราจะได้เอาข้าวสาลีออกขาย เราจะได้กระทําเอฟาห์ให้ย่อมลง และกระทําเชเขลให้โตขึ้น และหลอกค้าด้วยตาชั่งขี้ฉ้อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 6, 'เพื่อเราจะได้ซื้อคนจนด้วยเงิน และซื้อคนขัดสนด้วยรองเท้าสานคู่หนึ่ง เออ และขายกากข้าวสาลี”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 7, 'โดยศักดิ์ศรีของยาโคบ พระเยโฮวาห์ทรงปฏิญาณว่า “แน่นอนทีเดียว เราจะไม่ลืมการกระทําของเขาสักอย่างเดียวเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 8, 'แผ่นดินจะไม่หวั่นไหวเพราะเรื่องนี้หรือ ทุกคนที่อาศัยอยู่ในแผ่นดินนั้นจะไม่ไว้ทุกข์หรือ และแผ่นดินนั้นทั้งหมดก็เอ่อขึ้นมาอย่างแม่น้ํา ถูกซัดไปซัดมาและยุบลงอีก เหมือนแม่น้ําแห่งอียิปต์มิใช่หรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 9, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสว่า “และต่อมาในวันนั้นเราจะกระทําให้ดวงอาทิตย์ตกในเวลาเที่ยงวัน กระทําให้โลกมืดไปในกลางวันแสกๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 10, 'เราจะให้การเลี้ยงของเจ้าทั้งหลายกลับเป็นการไว้ทุกข์ และให้เสียงเพลงทั้งสิ้นของเจ้าเป็นคําคร่ําครวญ เราจะนําผ้ากระสอบมาที่เอวของคนทั้งหลาย และศีรษะทั่วไปก็จะล้าน และเราจะกระทําให้เป็นเหมือนการไว้ทุกข์ให้บุตรชายคนเดียวของเขา และวาระสุดท้ายก็จะให้เหมือนวันที่ขมขื่น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 11, 'องค์พระผู้เป็นเจ้าพระเจ้าตรัสว่า “ดูเถิด วันเวลาก็มาถึง เมื่อเราจะส่งทุพภิกขภัยมาที่แผ่นดิน ไม่ใช่การอดอาหาร หรือการกระหายน้ํา แต่จะอดฟังพระวจนะของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 12, 'เขาทั้งหลายจะท่องเที่ยวจากทะเลนี้ไปทะเลโน้น และจากทิศเหนือไปทิศตะวันออก เขาทั้งหลายจะวิ่งไปวิ่งมาเพื่อแสวงหาพระวจนะของพระเยโฮวาห์ แต่เขาจะหาไม่พบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 13, 'ในวันนั้น สาวพรหมจารีสวยๆและคนหนุ่มจะสลบไสลเพราะความกระหาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 14, 'บรรดาผู้ที่ปฏิญาณโดยความบาปแห่งสะมาเรีย และกล่าวว่า ‘โอ ดานเอ๋ย พระของท่านมีชีวิตอยู่แน่ฉันใด’ และว่า ‘พระมรรคาของเบเออร์เชบามีชีวิตอยู่แน่ฉันใด’ เขาเหล่านี้จะล้มลง และจะไม่ลุกขึ้นอีกเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 1, 'ข้าพเจ้าเห็นองค์พระผู้เป็นเจ้าประทับยืนอยู่ข้างแท่นบูชา และพระองค์ตรัสว่า “จงตีที่หัวเสาเพื่อให้ธรณีประตูหวั่นไหว และจงหักมันเสียให้เป็นชิ้นๆเหนือศีรษะของประชาชนทั้งหมด คนที่ยังเหลืออยู่เราจะสังหารเสียด้วยดาบ จะไม่มีผู้ใดหนีไปได้เลย จะไม่รอดพ้นไปได้สักคนเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 2, 'แม้ว่าเขาจะขุดไปถึงนรก มือของเราจะจับเขามาจากที่นั่น ถ้าเขาจะปีนไปฟ้าสวรรค์ เราจะนําเขาลงมาจากที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 3, 'แม้ว่าเขาจะซ่อนอยู่ที่ยอดเขาคารเมล เราจะหาเขาที่นั่นแล้วจับเขามา แม้ว่าเขาจะไปซ่อนอยู่ที่ก้นทะเลให้พ้นตาเรา เราจะบัญชางูที่นั่น และมันจะกัดเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 4, 'แม้ว่าเขาจะตกไปเป็นเชลยต่อหน้าศัตรูของเขาทั้งหลาย เราจะบัญชาดาบที่นั่น และดาบจะฆ่าเขาเสีย เราจะจ้องมองดูเขาอยู่เป็นการมองร้าย ไม่ใช่มองดี”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 5, 'องค์พระผู้เป็นเจ้าพระเจ้าจอมโยธา พระองค์ผู้ทรงแตะต้องแผ่นดิน และแผ่นดินก็ละลายไป และบรรดาที่อาศัยอยู่ในนั้นก็ไว้ทุกข์ และแผ่นดินนั้นทั้งหมดก็เอ่อขึ้นมาอย่างแม่น้ํา และยุบลงอีกเหมือนแม่น้ําแห่งอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 6, 'ผู้ทรงสร้างห้องชั้นบนไว้ในสวรรค์ และตั้งฟ้าครอบไว้ที่พื้นโลก ผู้ทรงเรียกน้ําทะเลมาแล้วรดน้ํานั้นบนพื้นโลก พระนามของพระองค์คือ พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 7, 'พระเยโฮวาห์ตรัสว่า “โอ คนอิสราเอลเอ๋ย แก่เราเจ้าไม่เป็นเหมือนคนเอธิโอเปียดอกหรือ เรามิได้พาอิสราเอลขึ้นมาจากแผ่นดินอียิปต์หรือ และพาคนฟีลิสเตียมาจากคัฟโทร์ และพาคนซีเรียมาจากคีร์หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 8, 'ดูเถิด พระเนตรขององค์พระผู้เป็นเจ้าพระเจ้าจับอยู่ที่ราชอาณาจักรอันบาปหนา และเราจะทําลายมันเสียจากพื้นโลก เว้นแต่เราจะไม่ทําลายวงศ์วานยาโคบให้สิ้นเสียทีเดียว” พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 9, '“เพราะว่า ดูเถิด เราจะบัญชาและจะสั่นวงศ์วานอิสราเอลท่ามกลางประชาชาติทั้งหลายอย่างกับสั่นตะแกรง แต่ไม่มีเม็ดใดสักเม็ดเดียวที่ตกลงถึงดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 10, 'คนบาปทั้งปวงในประชาชนของเราจะตายด้วยดาบ คือผู้ที่กล่าวว่า ‘ความชั่วจะตามไม่ทันและจะไม่พบเรา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 11, 'ในวันนั้น เราจะยกพลับพลาของดาวิดซึ่งพังลงแล้วนั้นตั้งขึ้นใหม่ และซ่อมช่องชํารุดต่างๆเสีย และจะยกที่ปรักหักพังขึ้น และจะสร้างเสียใหม่อย่างในสมัยโบราณกาล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 12, 'เพื่อเขาจะได้ยึดกรรมสิทธิ์คนที่เหลืออยู่ของเอโดม และประชาชาติทั้งสิ้นซึ่งเขาเรียกด้วยนามของเรา” พระเยโฮวาห์ผู้ทรงกระทําเช่นนี้ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 13, 'พระเยโฮวาห์ตรัสว่า “ดูเถิด วันเวลาก็มาถึง เมื่อคนที่ไถจะทันคนที่เกี่ยว และคนที่ย่ําผลองุ่นจะทันคนที่หว่านเมล็ดองุ่น จะมีน้ําองุ่นหยดจากภูเขา เนินเขาทั้งสิ้นจะละลายไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 14, 'เราจะให้อิสราเอลประชาชนของเรากลับสู่สภาพเดิม เขาจะสร้างเมืองที่พังนั้นขึ้นใหม่และเข้าอาศัยอยู่ เขาจะปลูกสวนองุ่นและดื่มน้ําองุ่นของสวนนั้น เขาจะทําสวนผลไม้และรับประทานผลของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 15, 'เราจะปลูกเขาไว้ในแผ่นดินของเขา เขาจะไม่ถูกถอนออกไปจากแผ่นดินซึ่งเราได้มอบให้แก่เขาอีกเลย” พระเยโฮวาห์พระเจ้าของเจ้าตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 1, 'นิมิตของโอบาดีห์ องค์พระผู้เป็นเจ้าพระเจ้าตรัสเกี่ยวด้วยเรื่องเอโดมดังนี้ว่า เราได้ยินข่าวลือจากพระเยโฮวาห์ ทูตคนหนึ่งถูกส่งไปท่ามกลางบรรดาประชาชาติให้พูดว่า “จงลุกขึ้นเถิด ให้เราลุกไปทําสงครามกับเมืองเอโดม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 2, 'ดูเถิด เราได้กระทําเจ้าให้เล็กท่ามกลางบรรดาประชาชาติ ให้เจ้าเป็นที่ดูหมิ่นอย่างมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 3, 'ความเห่อเหิมแห่งใจของเจ้าได้ล่อลวงเจ้าเอง เจ้าผู้ซึ่งอาศัยอยู่ในซอกหิน ที่อาศัยของเจ้าอยู่สูง เจ้ารําพึงอยู่ในใจว่า “ผู้ใดจะให้เราลงมายังพื้นดิน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 4, 'แม้ว่าเจ้าเหินขึ้นไปสูงเหมือนนกอินทรี แม้ว่ารังของเจ้าอยู่ในหมู่ดวงดาวทั้งหลาย เราจะฉุดเจ้าลงมาจากที่นั่น พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 5, 'ถ้าขโมยเข้ามาหาเจ้า ถ้าพวกปล้นเข้ามาในเวลากลางคืน (เจ้าจะถูกทําลายสักเท่าใด) เขาจะไม่ขโมยเพียงพอแก่ตัวของเขาเท่านั้นหรือ ถ้าคนเก็บองุ่นมาหาเจ้า เขาจะไม่ทิ้งองุ่นตกค้างไว้บ้างหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 6, 'ข้าวของของเอซาวได้ถูกรื้อค้นสักเท่าใดหนอ ทรัพย์สมบัติซึ่งซ่อนไว้ก็ถูกค้นไปหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 7, 'พันธมิตรทั้งสิ้นของเจ้าได้ขับเจ้าไปถึงพรมแดน สหมิตรของเจ้าได้ล่อลวงเจ้า เขากลับสู้ชนะเจ้าเสียแล้ว มิตรที่กินข้าวหม้อเดียวกับเจ้าก็วางกับดักเจ้า เรื่องนี้ไม่มีใครเข้าใจอะไรเสียเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 8, 'พระเยโฮวาห์ตรัสว่า ในวันนั้นเราจะไม่ทําลายคนฉลาดให้สิ้นไปจากเอโดม และทําลายความเข้าใจเสียจากภูเขาเอซาวหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 9, 'โอ เทมานเอ๋ย ชายผู้มีกําลังทั้งหลายของเจ้าจะขยาด จนในที่สุดทุกคนที่มาจากภูเขาเอซาวจะถูกตัดขาดเสียด้วยการสังหาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 10, 'เหตุเพราะความรุนแรงที่กระทําต่อยาโคบน้องชายของเจ้า ความอับอายจะปกคลุมเจ้าไว้ เจ้าจะต้องถูกตัดขาดออกไปเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 11, 'ในวันที่เจ้ายืนเป็นปฏิปักษ์ ในวันที่คนต่างด้าวนํากําลังของเขาไปเป็นเชลย และคนต่างชาติเข้ามาทางประตูเมือง เขาจับฉลากเอากรุงเยรูซาเล็มกัน เจ้าก็เหมือนคนเหล่านั้นคนหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 12, 'เจ้าไม่ควรยืนยิ้มอยู่ด้วยความพอใจในวันที่น้องชายของเจ้ารับเคราะห์ในวันนั้น เจ้าไม่ควรเปรมปรีดิ์เย้ยประชาชนยูดาห์ในวันที่เขาทั้งหลายถูกทําลาย เจ้าไม่ควรจะโอ้อวดในวันที่เขาตกทุกข์ได้ยาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 13, 'เจ้าไม่ควรเข้าประตูเมืองแห่งประชาชนของเราในวันแห่งหายนะของเขา เออ เจ้าไม่ควรยืนยิ้มอยู่ในเรื่องภัยพิบัติของเขาในวันแห่งหายนะของเขา เจ้าไม่ควรจะเข้าริบทรัพย์สินของเขาไปในวันแห่งหายนะของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 14, 'เจ้าไม่ควรจะยืนสกัดทางแยก เพื่อจะกําจัดพวกที่หลบหนีของเขา เจ้าไม่ควรจะมอบพวกที่เหลืออยู่ให้แก่ศัตรูของเขาในวันที่เขาตกทุกข์ได้ยาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 15, 'เพราะวันแห่งพระเยโฮวาห์ใกล้ประชาชาติทั้งสิ้นเข้ามาแล้ว เจ้ากระทําแก่เขาอย่างไร ก็จะมีผู้มากระทําแก่เจ้าอย่างนั้น การตอบแทนของเจ้าจะกลับมาตกบนศีรษะของเจ้าเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 16, 'เจ้าดื่มอยู่บนภูเขาบริสุทธิ์ของเราฉันใด ประชาชาติทั้งสิ้นก็จะดื่มไม่หยุดฉันนั้น เออ เขาจะดื่มแล้วก็โอนเอนไป เขาจะเป็นเหมือนอย่างที่ไม่เคยเกิดมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 17, 'แต่จะมีคนรอดพ้นในภูเขาศิโยน และที่นั้นจะบริสุทธิ์ และวงศ์วานของยาโคบจะได้ถือกรรมสิทธิ์ที่ดินอันเป็นกรรมสิทธิ์ของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 18, 'วงศ์วานของยาโคบจะเป็นไฟ วงศ์วานของโยเซฟจะเป็นเปลวไฟ และวงศ์วานของเอซาวจะเป็นตอข้าว ไฟและเปลวไฟจะไหม้และเผาผลาญเสีย วงศ์วานของเอซาวจะไม่มีใครรอดได้เลย เพราะว่าพระเยโฮวาห์ได้ลั่นพระวาจาแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 19, 'คนเหล่านั้นที่อยู่ในภาคใต้จะได้ภูเขาเอซาวเป็นกรรมสิทธิ์ คนเหล่านั้นที่อยู่ในที่ราบจะได้แผ่นดินฟีลิสเตีย เขาจะได้แผ่นดินเอฟราอิมและแผ่นดินสะมาเรียเป็นกรรมสิทธิ์ และเบนยามินจะได้กิเลอาดเป็นกรรมสิทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 20, 'พลโยธาของอิสราเอลที่เป็นเชลยจะได้ที่ซึ่งเป็นของคนคานาอันไกลไปจนถึงศาเรฟัทเป็นกรรมสิทธิ์ ส่วนพวกเชลยชาวเยรูซาเล็มที่อยู่ในเสฟาราดจะได้หัวเมืองในภาคใต้เป็นกรรมสิทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 21, 'พวกผู้ช่วยให้พ้นจะขึ้นไปที่ภูเขาศิโยนเพื่อปกครองภูเขาเอซาว และราชอาณาจักรนั้นจะตกเป็นของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 1, 'พระวจนะของพระเยโฮวาห์มาถึงโยนาห์บุตรชายของอามิททัยว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 2, '“จงลุกขึ้นไปยังนีนะเวห์นครใหญ่ และร้องกล่าวโทษชาวเมืองนั้น เหตุความชั่วของเขาทั้งหลายได้ขึ้นมาเบื้องหน้าเราแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 3, 'แต่โยนาห์ได้ลุกขึ้นหนีไปยังเมืองทารชิชจากพระพักตร์พระเยโฮวาห์ ท่านได้ลงไปยังเมืองยัฟฟา และพบกําปั่นลําหนึ่งกําลังไปเมืองทารชิช ดังนั้นท่านจึงชําระค่าโดยสาร และขึ้นเรือเดินทางร่วมกับเขาทั้งหลายไปยังเมืองทารชิชให้พ้นจากพระพักตร์พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 4, 'แต่พระเยโฮวาห์ทรงขับกระแสลมใหญ่ขึ้นเหนือทะเล จึงเกิดพายุใหญ่ในทะเลนั้น จนน่ากลัวกําปั่นจะอับปาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 5, 'แล้วบรรดาลูกเรือก็กลัว ต่างก็ร้องขอต่อพระของตน และเขาโยนสินค้าในกําปั่นลงในทะเลเพื่อให้กําปั่นเบาขึ้น แต่โยนาห์เข้าไปข้างในเรือ นอนลงและหลับสนิท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 6, 'นายเรือจึงมาหาท่านและกล่าวแก่ท่านว่า “โอ เจ้าคนขี้เซาเอ๋ย อย่างไรกันนี่ ลุกขึ้นซิ จงร้องขอต่อพระเจ้าของเจ้า ชะรอยพระเจ้านั้นจะทรงระลึกถึงพวกเราบ้าง เราจะได้ไม่พินาศ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 7, 'เขาทั้งหลายก็ชักชวนกันว่า “มาเถอะ ให้เราจับฉลากกัน เพื่อเราจะทราบว่า ใครเป็นต้นเหตุแห่งภัยซึ่งเกิดขึ้นแก่เรานี้” ดังนั้นเขาก็จับฉลาก ฉลากนั้นก็ตกแก่โยนาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 8, 'เขาจึงพูดกับท่านว่า “จงบอกเรามาเถิดว่า ภัยซึ่งเกิดขึ้นแก่เรานี้ ใครเป็นต้นเหตุ เจ้าหากินทางไหน และเจ้ามาจากไหน ประเทศของเจ้าชื่ออะไร เจ้าเป็นคนชาติไหน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 9, 'และท่านจึงตอบเขาว่า “ข้าพเจ้าเป็นคนฮีบรู และข้าพเจ้ายําเกรงพระเยโฮวาห์พระเจ้าแห่งฟ้าสวรรค์ ผู้ทรงสร้างทะเลและแผ่นดินแห้ง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 10, 'คนทั้งปวงก็กลัวยิ่งนัก จึงถามท่านว่า “ท่านกระทําอะไรเช่นนี้หนอ” เพราะคนเหล่านั้นทราบแล้วว่า ท่านหลบหนีจากพระพักตร์พระเยโฮวาห์ เพราะท่านบอกแก่เขาเช่นนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 11, 'เขาทั้งหลายจึงกล่าวแก่ท่านว่า “เราควรจะทําอย่างไรแก่ท่าน เพื่อทะเลจะได้สงบลงเพื่อเรา” เพราะทะเลยิ่งกําเริบมากขึ้นทุกที');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 12, 'ท่านจึงตอบเขาทั้งหลายว่า “จงจับตัวข้าพเจ้าโยนลงไปในทะเลก็แล้วกัน ทะเลก็จะสงบลงเพื่อท่าน เพราะข้าพเจ้าทราบอยู่ว่า ที่พายุใหญ่เกิดขึ้นแก่ท่านเช่นนี้ ก็เนื่องจากตัวข้าพเจ้าเอง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 13, 'ถึงกระนั้นก็ดีพวกลูกเรือก็ช่วยกันตีกรรเชียงอย่างแข็งแรงเพื่อจะนําเรือกลับเข้าฝั่งแต่ไม่ได้ เพราะว่าทะเลยิ่งกําเริบมากขึ้นต้านเขาไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 14, 'เพราะฉะนั้นเขาจึงร้องทูลต่อพระเยโฮวาห์ว่า “โอ ข้าแต่พระเยโฮวาห์ ข้าพระองค์ทั้งหลายขอวิงวอนต่อพระองค์ ขออย่าให้พวกข้าพระองค์พินาศเพราะชีวิตของชายผู้นี้เลย ขออย่าให้โทษของการทําให้โลหิตที่ไร้ความผิดตกมาเหนือข้าพระองค์ โอ ข้าแต่พระเยโฮวาห์ เพราะว่าพระองค์ได้ทรงกระทําสิ่งที่พระองค์ทรงพอพระทัย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 15, 'เขาจึงจับโยนาห์ทิ้งลงไปในทะเล ความปั่นป่วนในทะเลก็สงบลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 16, 'คนเหล่านั้นก็ยําเกรงพระเยโฮวาห์ยิ่งนัก เขาทั้งหลายก็ถวายสัตวบูชาแด่พระเยโฮวาห์และปฏิญาณตัวไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 17, 'และพระเยโฮวาห์ทรงกําหนดให้ปลามหึมาตัวหนึ่งกลืนโยนาห์เข้าไป โยนาห์ก็อยู่ในท้องปลานั้นสามวันสามคืน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 1, 'แล้วโยนาห์ก็อธิษฐานต่อพระเยโฮวาห์พระเจ้าของท่านจากภายในท้องปลานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 2, 'ว่า “ในคราวที่ข้าพระองค์ตกทุกข์ได้ยาก ข้าพระองค์ร้องทุกข์ต่อพระเยโฮวาห์ และพระองค์ทรงสดับข้าพระองค์ ข้าพระองค์ร้องทูลจากท้องของนรก และพระองค์ทรงฟังเสียงข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 3, 'เพราะพระองค์ทรงเหวี่ยงข้าพระองค์ลงไปในที่ลึกในท้องทะเล และน้ําก็ท่วมล้อมรอบข้าพระองค์ไว้ บรรดาคลื่นและระลอกของพระองค์ท่วมข้าพระองค์แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 4, 'ข้าพระองค์จึงทูลว่า ‘ข้าพระองค์ถูกเหวี่ยงให้พ้นจากสายพระเนตรของพระองค์ แต่ข้าพระองค์จะเงยหน้าดูพระวิหารบริสุทธิ์ของพระองค์ได้อีก’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 5, 'น้ําก็ท่วมมิดข้าพระองค์ คือถึงจิตใจข้าพระองค์ ที่ลึกก็อยู่รอบตัวข้าพระองค์ สาหร่ายทะเลก็พันศีรษะข้าพระองค์อยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 6, 'ข้าพระองค์ลงไปยังที่รากแห่งภูเขาทั้งหลาย แผ่นดินกับดาลประตูปิดกั้นข้าพระองค์ไว้เป็นนิตย์ แต่กระนั้นก็ดี โอ ข้าแต่พระเยโฮวาห์พระเจ้าของข้าพระองค์ พระองค์ยังทรงนําชีวิตของข้าพระองค์ขึ้นมาจากความเปื่อยเน่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 7, 'เมื่อจิตใจอ่อนเพลียไปในตัวของข้าพระองค์ ข้าพระองค์ระลึกถึงพระเยโฮวาห์ และคําอธิษฐานของข้าพระองค์มาถึงพระองค์ เข้าสู่พระวิหารบริสุทธิ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 8, 'บรรดาผู้ที่แสดงความนับถือต่อพระเทียมเท็จ ย่อมสละทิ้งพระเมตตาเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 9, 'แต่ข้าพระองค์จะถวายสัตวบูชาแด่พระองค์ พร้อมด้วยเสียงโมทนาพระคุณ ข้าพระองค์ปฏิญาณไว้อย่างไร ข้าพระองค์จะทําตามคําปฏิญาณอย่างนั้น การที่ช่วยให้รอดนั้นเป็นของพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 10, 'และพระเยโฮวาห์ตรัสสั่งปลานั้น มันก็สํารอกโยนาห์ออกไว้บนแผ่นดินแห้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 1, 'แล้วพระวจนะของพระเยโฮวาห์มาถึงโยนาห์เป็นคํารบสองว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 2, '“จงลุกขึ้นไปยังนีนะเวห์นครใหญ่ และประกาศข่าวแก่เมืองนั้นตามที่เราบอกเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 3, 'ดังนั้นโยนาห์จึงลุกขึ้นไปยังนีนะเวห์ ตามพระวจนะของพระเยโฮวาห์ ฝ่ายนีนะเวห์เป็นนครใหญ่โตมากทีเดียว ถ้าจะเดินข้ามเมืองก็กินเวลาสามวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 4, 'โยนาห์ตั้งต้นเดินเข้าไปในเมืองได้ระยะทางเดินวันหนึ่ง และท่านก็ร้องประกาศว่า “อีกสี่สิบวัน นีนะเวห์จะถูกคว่ํา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 5, 'ฝ่ายประชาชนนครนีนะเวห์ได้เชื่อพระเจ้า เขาประกาศให้อดอาหาร และสวมผ้ากระสอบ ตั้งแต่ผู้ใหญ่ที่สุดถึงผู้น้อยที่สุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 6, 'กิตติศัพท์นี้ลือไปถึงกษัตริย์นครนีนะเวห์ พระองค์ทรงลุกขึ้นจากพระที่นั่ง ทรงเปลื้องฉลองพระองค์ออกเสีย ทรงสวมผ้ากระสอบแทน และประทับบนกองขี้เถ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 7, 'พระองค์ทรงออกพระราชกฤษฎีกา ประกาศไปทั่วนครนีนะเวห์ โดยอํานาจกษัตริย์และบรรดาขุนนางทั้งหลายว่า “คนหรือสัตว์ ไม่ว่าฝูงสัตว์ใหญ่หรือฝูงสัตว์เล็ก ห้ามลิ้มรสสิ่งใดๆ อย่าให้กินอาหาร อย่าให้ดื่มน้ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 8, 'ให้ทั้งคนและสัตว์นุ่งห่มผ้ากระสอบ ให้ตั้งจิตตั้งใจร้องทูลต่อพระเจ้า เออ ให้ทุกคนหันกลับเสียจากการประพฤติชั่ว และเลิกการทารุณซึ่งมือเขากระทํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 9, 'ใครจะรู้ได้พระเจ้าอาจจะทรงกลับและเปลี่ยนพระทัย คลายจากพระพิโรธอันรุนแรงเพื่อว่าเราจะมิได้พินาศ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 10, 'เมื่อพระเจ้าทอดพระเนตรการกระทําของเขาแล้วว่า เขากลับไม่ประพฤติชั่วต่อไป พระเจ้าก็ทรงกลับพระทัยไม่ลงโทษตามที่พระองค์ตรัสไว้ และพระองค์ก็มิได้ทรงลงโทษเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 1, 'เหตุการณ์นี้ไม่เป็นที่พอใจโยนาห์อย่างยิ่ง และท่านโกรธ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 2, 'ท่านจึงอธิษฐานต่อพระเยโฮวาห์ว่า “โอ ข้าแต่พระเยโฮวาห์ เมื่อข้าพระองค์ยังอยู่ในประเทศของข้าพระองค์ ข้าพระองค์พูดแล้วว่า จะเป็นไปเช่นนี้มิใช่หรือ นี่แหละเป็นเหตุให้ข้าพระองค์ได้รีบหนีไปยังเมืองทารชิช เพราะข้าพระองค์ทราบว่า พระองค์ทรงเป็นพระเจ้าผู้ทรงกอปรด้วยพระคุณ และทรงพระกรุณา ทรงกริ้วช้า และบริบูรณ์ด้วยความเมตตา และทรงกลับพระทัยไม่ลงโทษ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 3, 'โอ ข้าแต่พระเยโฮวาห์ เพราะฉะนั้นบัดนี้ ขอพระองค์ทรงเอาชีวิตของข้าพระองค์ไปเสีย เพราะว่าข้าพระองค์ตายเสียก็ดีกว่าอยู่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 4, 'และพระเยโฮวาห์ตรัสว่า “การที่เจ้าโกรธเช่นนี้ดีอยู่หรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 5, 'แล้วโยนาห์ก็ออกไปนอกนคร นั่งอยู่ทางทิศตะวันออกของเมืองนั้น และท่านทําเพิงไว้เป็นที่ท่านอาศัย ท่านนั่งอยู่ใต้ร่มเพิงคอยดูเหตุการณ์อันจะเกิดขึ้นกับนครนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 6, 'และพระเยโฮวาห์พระเจ้าทรงกําหนดให้ต้นละหุ่งต้นหนึ่งงอกขึ้นมาเหนือโยนาห์ ให้เป็นที่กําบังศีรษะของท่าน เพื่อให้บรรเทาความร้อนรุ่มกลุ้มใจในเรื่องนี้ เพราะเหตุต้นละหุ่งต้นนี้โยนาห์จึงมีความยินดียิ่งนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 7, 'แต่ในเวลาเช้าวันรุ่งขึ้น พระเจ้าทรงกําหนดให้หนอนตัวหนึ่งมากัดกินต้นละหุ่งต้นนั้นจนมันเหี่ยวไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 8, 'ต่อมาเมื่อดวงอาทิตย์ขึ้นแล้ว พระเจ้าทรงกําหนดให้ลมตะวันออกที่ร้อนผากพัดมา และแสงแดดก็แผดลงบนศีรษะของโยนาห์จนท่านอ่อนเพลียไป และท่านนึกปรารถนาในใจที่จะตายเสีย จึงทูลขอว่า “ให้ข้าพระองค์ตายเสียก็ดีกว่าอยู่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 9, 'แต่พระเจ้าตรัสกับโยนาห์ว่า “ที่เจ้าโกรธเพราะต้นละหุ่งนั้นดีอยู่แล้วหรือ” ท่านทูลว่า “ที่ข้าพระองค์โกรธถึงอยากตายนี้ดีแล้ว พระเจ้าข้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 10, 'และพระเยโฮวาห์ตรัสว่า “เจ้าสงสารต้นละหุ่งนั้น ซึ่งเจ้ามิได้ลงแรงปลูก หรือมิได้กระทําให้มันเจริญ มันงอกเจริญขึ้นในคืนเดียว แล้วก็ตายไปในคืนเดียวดุจกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 11, 'ไม่สมควรหรือที่เราจะไว้ชีวิตเมืองนีนะเวห์นครใหญ่นั้น ซึ่งมีพลเมืองมากกว่าหนึ่งแสนสองหมื่นคน ผู้ไม่ทราบว่าข้างไหนมือขวาข้างไหนมือซ้าย และมีสัตว์เลี้ยงเป็นอันมากด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 1, 'พระวจนะของพระเยโฮวาห์ที่มาถึงมีคาห์ชาวเมืองโมเรเชท ในรัชกาลโยธาม อาหัส และเฮเซคียาห์กษัตริย์แห่งประเทศยูดาห์ ซึ่งท่านได้เห็นเกี่ยวกับสะมาเรียและเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 2, 'ชนชาติทั้งหลายเอ๋ย ทุกคนจงฟัง โอ พิภพเอ๋ย และสารพัดที่อยู่ในนั้น จงฟัง และให้องค์พระผู้เป็นเจ้าพระเจ้าเป็นพยานกล่าวโทษท่าน คือองค์พระผู้เป็นเจ้าจากพระวิหารบริสุทธิ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 3, 'เพราะ ดูเถิด พระเยโฮวาห์เสด็จออกจากสถานของพระองค์ และจะเสด็จลงมา ทรงเหยียบย่ําที่สูงของพิภพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 4, 'ภูเขาจะละลายไปภายใต้พระองค์ และหุบเขาจะถูกผ่าเหมือนขี้ผึ้งหน้าไฟ เหมือนน้ําที่เทลงมาตามที่ชัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 5, 'เหตุการณ์ทั้งปวงเหล่านี้บังเกิดขึ้นเพราะการละเมิดของยาโคบ และเพราะความบาปของวงศ์วานอิสราเอล การละเมิดของยาโคบนั้นคืออะไร สะมาเรียมิใช่หรือ ปูชนียสถานสูงแห่งยูดาห์คืออะไร เยรูซาเล็มมิใช่หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 6, 'เหตุฉะนั้น เราจะกระทําสะมาเรียให้เป็นกองสิ่งปรักหักพังอยู่ในที่โล่ง เป็นที่สําหรับทําสวนองุ่น เราจะเทก้อนหินที่ใช้สร้างเมืองนั้นลงที่หุบเขา จะให้เห็นรากฐานของเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 7, 'รูปเคารพแกะสลักทั้งสิ้นของเมืองนั้นจะถูกทุบเป็นชิ้นๆ ค่าจ้างทั้งสิ้นของเมืองนั้นจะถูกเผาเสียด้วยไฟ และเราจะกระทําให้รูปเคารพทั้งสิ้นของเมืองนั้นถูกทิ้งร้าง เพราะเมืองนั้นรวบรวมรูปเคารพเหล่านี้มาด้วยค่าจ้างของหญิงแพศยา และมันจะกลับเป็นค่าจ้างของหญิงแพศยา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 8, 'เพราะเหตุนี้ข้าพเจ้าจึงร่ําไห้และคร่ําครวญ ข้าพเจ้าจะเดินเท้าเปล่าและเปลือยกายไปไหนๆ ข้าพเจ้าจะส่งเสียงร่ําไห้ดุจมังกร และเสียงครวญครางดุจนกเค้าแมว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 9, 'เพราะว่ารอยแผลของเมืองนั้นรักษาไม่หาย และได้ลามมาถึงยูดาห์ ได้มาถึงกระทั่งประตูเมืองแห่งประชาชนของเราคือถึงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 10, 'อย่าบอกเรื่องนี้ในเมืองกัท อย่าร้องไห้ไปเลย จงเกลือกกลิ้งตัวอยู่ในฝุ่นในวงศ์วานอัฟราห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 11, 'ชาวเมืองชาฟีร์เอ๋ย จงผ่านไปตามทางของเจ้าด้วยตัวเปลือยเปล่าและอับอาย ชาวเมืองศานันไม่ได้ออกมาในเมื่อเบธเอเซลร่ําไห้ มันจะเอาสถานที่ตั้งของมันไปเสียจากเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 12, 'เพราะว่าชาวมาโรทคอยความดีอยู่ด้วยความรอบคอบ แต่ภัยพิบัติได้ลงมาจากพระเยโฮวาห์ถึงประตูเมืองเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 13, 'โอ ชาวเมืองลาคีชเอ๋ย จงเทียมม้าเข้ากับรถรบ เธอเริ่มสร้างบาปให้แก่บุตรสาวของศิโยน เพราะได้พบการละเมิดของอิสราเอลในเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 14, 'เพราะฉะนั้น เจ้าจะต้องมอบของไว้อาลัยให้แก่โมเรเชท-กัท บรรดาเรือนของอัคซีบจะเป็นสิ่งอสัตย์แก่บรรดากษัตริย์อิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 15, 'โอ ชาวเมืองมาเรชาห์เอ๋ย เราจะนําผู้รับมรดกมาสู่เจ้าอีก ท่านจะมายังอดุลลัมซึ่งเป็นสง่าราศีของอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 16, 'จงกล้อนผมและโกนหนวดโกนเคราเสีย เพื่อไว้ทุกข์ให้แก่ลูกรักที่พอใจของเจ้า จงทําตัวให้ล้านมากขึ้นเหมือนนกอินทรี เพราะเขาทั้งหลายได้จากเจ้าไปเป็นเชลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 1, 'วิบัติแก่ผู้ที่เตรียมความชั่วช้า และคิดกระทําความชั่วอยู่บนที่นอนของตน พอรุ่งขึ้นเช้าก็ออกไปกระทํา เพราะว่าการนั้นอยู่ในอํานาจมือของเขาที่จะกระทําได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 2, 'เขาโลภที่ดินแล้วก็ใช้ความรุนแรงยึดเอาไป เขาโลภบ้านเรือนและก็ริบไปเสีย เขาบีบบังคับคนและบ้านเรือนของเขา และบีบคนกับมรดกของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 3, 'เพราะฉะนั้นพระเยโฮวาห์จึงตรัสดังนี้ว่า ดูเถิด เรากําลังเตรียมภัยให้ตกกับครอบครัวนี้ ซึ่งเจ้าจะหลบคอของเจ้าให้พ้นไปไม่ได้ และเจ้าจะเดินอย่างผึ่งผายไปไม่ได้ เพราะเวลานี้เป็นการวิบัติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 4, 'ในวันนั้น จะมีคนเล่าคําอุปมาต่อสู้เจ้า และจะร่ําไห้ด้วยการโอดครวญอย่างขมขื่นว่า “พวกเราพินาศอย่างสิ้นเชิงแล้ว พระองค์ทรงเปลี่ยนที่ดินกรรมสิทธิ์แห่งชนชาติของข้า พระองค์ทรงถอนไปจากข้าเสียแล้วหนอ พระองค์ทรงแบ่งไร่นาของพวกเราให้แก่บรรดาคนที่จับกุมพวกเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 5, 'ดังนั้น เจ้าจะไม่มีใครจับฉลากแบ่งที่ดินกันในชุมชนแห่งพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 6, 'เขากล่าวแก่ผู้ที่พยากรณ์ว่า “อย่าพยากรณ์เลย” เขาจะไม่พยากรณ์แก่พวกเขา เพื่อพวกเขาจะไม่อับอาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 7, 'โอ พวกที่มีชื่อว่า วงศ์วานของยาโคบเอ๋ย พระวิญญาณของพระเยโฮวาห์หมดความอดทนแล้วหรือ สิ่งเหล่านี้เป็นการกระทําของพระองค์หรือ ถ้อยคําของเราไม่กระทําให้บังเกิดผลดีแก่ผู้ที่ดําเนินในความเที่ยงธรรมหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 8, 'ในตอนหลังๆนี้ประชาชนของเราลุกขึ้นต่อสู้อย่างกับเป็นศัตรู เจ้าริบเอาเสื้อคลุมกับเสื้อผ้าจากผู้ที่ผ่านไปอย่างวางใจ ด้วยไม่นึกฝันว่าจะมีสงคราม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 9, 'เจ้าขับไล่พวกผู้หญิงในประชาชนของเราออกไปจากเรือนอันผาสุกของเขาทั้งหลาย เจ้าได้เอาสง่าราศีของเราไปเสียจากเด็กๆของเขาเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 10, 'จงลุกขึ้นและจากไป เพราะที่นี่ไม่ใช่ที่พักของเจ้า เพราะความไม่สะอาดซึ่งจะทําลายเจ้า ด้วยความพินาศอย่างทุกข์ระทม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 11, 'หากคนใดจะเที่ยวไปโดยมีนิสัยหลอกลวงและมุสาว่า “เราจะพยากรณ์ให้ท่านฟังเรื่องเหล้าองุ่นและเมรัย” เขาจะเป็นผู้พยากรณ์ของชนชาตินี้ได้ละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 12, 'โอ ยาโคบเอ๋ย เราจะรวบรวมเจ้าทั้งหลายเป็นแน่ เราจะรวบรวมคนอิสราเอลที่เหลืออยู่ และจะตั้งเขาไว้ด้วยกันเหมือนฝูงแพะแกะที่อยู่ในเมืองโบสราห์ เหมือนฝูงสัตว์ที่อยู่ในคอก เขาจะทําเสียงดังเพราะเหตุมีคนมากมาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 13, 'ผู้ที่ทะลวงออกได้จะขึ้นไปก่อนเขาทั้งหลาย เขาทั้งหลายจะทะลวงออกไปและผ่านออกประตูเมือง เขาจะออกไปทางนี้ กษัตริย์ของเขาทั้งหลายจะเสด็จไปก่อน และพระเยโฮวาห์จะทรงนําหน้าเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 1, 'และข้าพเจ้ากล่าวว่า โอ ท่านทั้งหลายผู้เป็นประมุขของยาโคบ คือบรรดาผู้ครอบครองวงศ์วานอิสราเอลเอ๋ย จงฟัง ท่านทั้งหลายต้องทราบความยุติธรรมไม่ใช่หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 2, 'ท่านทั้งหลายผู้เกลียดชังความดีและรักความชั่ว ผู้ที่ฉีกหนังออกจากประชาชนของเรา และฉีกเนื้อออกจากกระดูกของเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 3, 'ผู้ที่กินเนื้อชนชาติของเรา และถลกหนังออกจากตัวเขาทั้งหลาย และหักกระดูกของเขา และสับเขาเป็นชิ้นๆ เหมือนกับทําไว้ใส่หม้อ และเหมือนเนื้อที่อยู่ในหม้อขนาดใหญ่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 4, 'แล้วเขาจะร้องทุกข์ต่อพระเยโฮวาห์ แต่พระองค์จะไม่ทรงฟังเขา คราวนั้นพระองค์จะทรงซ่อนพระพักตร์เสียจากเขาทั้งหลาย เพราะเขาได้ประพฤติอย่างชั่วร้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 5, 'พระเยโฮวาห์ตรัสเกี่ยวด้วยเรื่องผู้พยากรณ์ผู้ที่นําชนชาติของข้าพเจ้าให้หลงไป ผู้ที่กัดด้วยฟันและร้องว่า “จงเป็นสุขเถิด” ผู้ที่ไม่ยื่นอะไรใส่ปากของเขา แต่พวกเขาประกาศสงครามต่อเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 6, 'เพราะฉะนั้น จะเป็นกลางคืนแก่เจ้าปราศจากนิมิต และความมืดทึบจะบังเกิดแก่เจ้าปราศจากการทํานาย สําหรับพวกผู้พยากรณ์นี้ดวงอาทิตย์จะตกไป และกลางวันก็จะมืดอยู่เหนือเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 7, 'ผู้ทํานายจะอับอาย พวกโหรจะขายหน้า เออ เขาทั้งหลายจะปิดริมฝีปากด้วยกันหมด เพราะว่าไม่มีคําตอบมาจากพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 8, 'แต่สําหรับข้าพเจ้า ข้าพเจ้าเต็มด้วยฤทธิ์เดช คือด้วยพระวิญญาณของพระเยโฮวาห์ และทั้งความยุติธรรมกับกําลังที่จะประกาศการละเมิดของยาโคบแก่เขาเอง และประกาศบาปของอิสราเอลแก่เขาเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 9, 'ท่านทั้งหลายผู้เป็นประมุขแห่งวงศ์วานของยาโคบ คือผู้ครอบครองวงศ์วานอิสราเอล จงฟังข้อความนี้ คือท่านผู้ชังความยุติธรรมและผู้แปรความเที่ยงตรงทั้งสิ้นให้ปรวนไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 10, 'ผู้สร้างศิโยนด้วยโลหิต และสร้างเยรูซาเล็มด้วยความชั่วช้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 11, 'ผู้เป็นประมุขของเมืองนี้ตัดสินความด้วยเห็นแก่สินบน ปุโรหิตของเธอสั่งสอนด้วยเห็นแก่สินจ้าง ผู้พยากรณ์ของเธอทํานายด้วยเห็นแก่เงิน ถึงกระนั้นเขาทั้งหลายยังอิงพระเยโฮวาห์และกล่าวว่า “พระเยโฮวาห์ทรงสถิตท่ามกลางเรามิใช่หรือ ไม่มีความชั่วอย่างไรเกิดขึ้นแก่เราได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 12, 'ด้วยเหตุนี้แหละ เพราะเจ้านี่เอง ศิโยนจะต้องถูกไถเหมือนไถนา เยรูซาเล็มจะกลายเป็นกองสิ่งปรักหักพัง และภูเขาแห่งพระนิเวศจะเป็นที่สูงซึ่งมีต้นไม้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 1, 'ในยุคหลังจะเป็นดังนี้ คือภูเขาแห่งพระนิเวศของพระเยโฮวาห์จะถูกสถาปนาขึ้นให้สูงที่สุดในจําพวกภูเขาทั้งหลาย และจะถูกยกขึ้นให้เหนือบรรดาเนินเขา ชนชาติทั้งหลายจะหลั่งไหลเข้ามาหา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 2, 'และประชาชาติเป็นอันมากจะมากล่าวว่า “มาเถิด ให้เราขึ้นไปยังภูเขาของพระเยโฮวาห์ ยังพระนิเวศแห่งพระเจ้าของยาโคบ เพื่อพระองค์จะทรงสอนวิถีของพระองค์แก่เรา และเพื่อเราจะเดินในมรรคาของพระองค์” เพราะว่าพระราชบัญญัติจะออกมาจากศิโยน และพระวจนะของพระเยโฮวาห์จะออกมาจากเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 3, 'พระองค์จะทรงวินิจฉัยระหว่างชนชาติทั้งหลายเป็นอันมาก และจะทรงตัดสินเพื่อบรรดาประชาชาติอันแข็งแรงที่อยู่ไกลออกไป และเขาทั้งหลายจะตีดาบของเขาให้เป็นผาลไถนา และหอกของเขาให้เป็นขอลิด ประชาชาติจะไม่ยกดาบต่อสู้กันอีก เขาจะไม่ศึกษายุทธศาสตร์อีกต่อไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 4, 'แต่ต่างก็จะนั่งอยู่ใต้ซุ้มองุ่นและใต้ต้นมะเดื่อของตน และจะไม่มีใครมากระทําให้เขาสะดุ้งกลัว เพราะพระโอษฐ์ของพระเยโฮวาห์จอมโยธาได้ตรัสอย่างนี้แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 5, 'ด้วยว่าบรรดาชนชาติทั้งหลายต่างก็ดําเนินในนามแห่งพระของตน แต่เราจะดําเนินในพระนามของพระเยโฮวาห์พระเจ้าของเราเป็นนิตย์สืบๆไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 6, 'พระเยโฮวาห์ตรัสว่า ในคราวนั้นเราจะรวบรวมคนขาพิการ และจะรวบรวมบรรดาผู้ที่ถูกขับไล่ไป และบรรดาผู้ที่เราได้ให้ทุกข์ใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 7, 'คนที่ขาพิการนั้นเราจะให้เป็นคนที่เหลืออยู่ คนที่ถูกทิ้งไปนั้นเราจะให้เป็นชนชาติที่เข้มแข็ง และพระเยโฮวาห์จะทรงปกครองเหนือเขาที่ภูเขาศิโยนตั้งแต่บัดนี้เป็นต้นไปจนชั่วกัลปาวสาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 8, 'โอ หอคอยที่เฝ้าฝูงสัตว์เอ๋ย เจ้าผู้เป็นป้อมปราการอันแข็งแกร่งสําหรับบุตรสาวแห่งศิโยน อํานาจครอบครองดั้งเดิมจะมาสู่เจ้า ราชอาณาจักรจะมาสู่บุตรสาวแห่งเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 9, 'เออ ทําไมเจ้าร้องไห้เสียงดัง ไม่มีกษัตริย์ปกครองเจ้าหรือ ที่ปรึกษาของเจ้าพินาศเสียแล้วหรือ เจ้าจึงเจ็บปวดรวดร้าวอย่างกับหญิงจะคลอดบุตร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 10, 'โอ บุตรสาวศิโยนเอ๋ย จงบิดตัวและโอดครวญไปเถิด อย่างกับหญิงจะคลอดบุตร เพราะบัดนี้เจ้าจะต้องออกไปจากนครไปพักอยู่ตามไร่นา เจ้าจะต้องไปยังบาบิโลน เจ้าจะได้รับการช่วยให้รอดพ้น ณ ที่นั่น พระเยโฮวาห์จะทรงไถ่เจ้า ณ ที่นั่นให้พ้นจากมือศัตรูของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 11, 'บัดนี้ ประชาชาติมากหลายได้ชุมนุมต่อสู้เจ้า กล่าวว่า “จงให้มันหมดความศักดิ์สิทธิ์ ให้ตาของเราเพ่งดูศิโยน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 12, 'แต่เขาทั้งหลายไม่ทราบถึงพระดําริของพระเยโฮวาห์ เขาทั้งหลายไม่เข้าใจในแผนการของพระองค์ ที่พระองค์จะทรงรวบรวมเขาทั้งหลายเข้ามา ดังรวมฟ่อนข้าวไว้ที่ลานนวดข้าว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 13, 'โอ บุตรสาวศิโยนเอ๋ย จงลุกขึ้นและนวดเถิด เพราะว่าเราจะทําเขาของเจ้าให้เป็นเหล็ก และกีบเท้าของเจ้าให้เป็นทองเหลือง และเจ้าจะตีชนชาติทั้งหลายเป็นอันมากให้เป็นชิ้นๆ และเราจะมอบสิ่งที่ได้มาถวายแด่พระเยโฮวาห์ มอบสมบัติของเขาทั้งหลายแด่องค์พระผู้เป็นเจ้าแห่งพิภพจบสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 1, 'โอ บุตรสาวแห่งกองทัพทหารเอ๋ย บัดนี้เจ้าจงรวมกันเป็นกองทัพ ศัตรูมาล้อมเราทั้งหลายไว้ เขาจะเอาไม้ตีแก้มของผู้ปกครองอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 2, 'เบธเลเฮม เอฟราธาห์เอ๋ย แต่เจ้าผู้เป็นหน่วยเล็กในบรรดาคนยูดาห์ที่นับเป็นพันๆ จากเจ้าจะมีผู้หนึ่งออกมาเพื่อเรา เป็นผู้ที่จะปกครองในอิสราเอล ดั้งเดิมของท่านมาจากสมัยเก่า จากสมัยโบราณกาล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 3, 'ดังนั้น พระองค์จะทรงมอบเขาไว้จนถึงเวลาที่หญิงผู้เจ็บครรภ์จะคลอดบุตร แล้วบรรดาพี่น้องที่เหลืออยู่จะกลับมายังคนอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 4, 'และพระองค์จะทรงยืนมั่น ทรงเลี้ยงดูด้วยพระกําลังแห่งพระเยโฮวาห์ ด้วยสง่าราศีแห่งพระนามพระเยโฮวาห์พระเจ้าของพระองค์ และเขาทั้งหลายอยู่ได้ เพราะบัดนี้พระองค์จะทรงเป็นใหญ่ตลอดจนถึงที่สุดท้ายปลายพิภพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 5, 'พระองค์ผู้นี้จะเป็นสันติสุข คือเมื่อชาวอัสซีเรียจะยกเข้ามาในแผ่นดินของเราและเมื่อเขาจะเหยียบย่ําในปราสาททั้งหลายของเรา เราจะยกผู้เลี้ยงแกะเจ็ดคนและเจ้านายแปดคนมาต่อต้านเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 6, 'เขาทั้งหลายจะทําลายแผ่นดินอัสซีเรียด้วยดาบ และแผ่นดินนิมโรดในทางเข้า และพระองค์จะทรงช่วยเราให้พ้นจากชาวอัสซีเรียเมื่อชาวอัสซีเรียยกเข้ามาในแผ่นดินของเรา และเหยียบย่ําภายในเขตแดนของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 7, 'แล้วคนยาโคบที่เหลืออยู่จะอยู่ท่ามกลางชนชาติทั้งหลายเป็นอันมาก เหมือนน้ําค้างจากพระเยโฮวาห์ เหมือนห่าฝนที่ตกบนหญ้า ซึ่งไม่อยู่คอยมนุษย์หรือคอยบุตรทั้งหลายของมนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 8, 'และคนยาโคบที่เหลืออยู่จะอยู่ท่ามกลางประชาชาติ ในท่ามกลางชนชาติทั้งหลายเป็นอันมาก ดังสิงโตอยู่ท่ามกลางสัตว์เดียรัจฉานในป่า ดังสิงโตหนุ่มอยู่ท่ามกลางฝูงแพะแกะ ซึ่งเมื่อมันผ่านไป มันก็เหยียบย่ําลงและฉีกเสีย ไม่มีใครช่วยให้พ้นได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 9, 'มือของเจ้าจะถูกยกขึ้นเหนือคู่อริของเจ้า และศัตรูทั้งสิ้นของเจ้าจะถูกตัดขาดไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 10, 'พระเยโฮวาห์ตรัสว่า ต่อมาในวันนั้นเราจะขจัดม้าของเจ้าให้หมดไปจากท่ามกลางเจ้า และจะทําลายรถรบของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 11, 'และเราจะขจัดเมืองให้หมดไปจากแผ่นดินของเจ้า และจะโค่นที่กําบังเข้มแข็งของเจ้าทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 12, 'เราจะขจัดวิทยาคมให้หมดไปจากมือของเจ้า เจ้าจะไม่มีหมอผีอีกต่อไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 13, 'เราจะขจัดรูปเคารพสลักของเจ้าออกเสียด้วย และทําลายเสาศักดิ์สิทธิ์จากท่ามกลางเจ้า เจ้าจะมิได้กราบลงไหว้ผลงานของมือของเจ้าอีกต่อไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 14, 'เราจะถอนเสารูปเคารพของเจ้าเสียจากท่ามกลางเจ้า และจะทําลายเมืองของเจ้าเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 15, 'เราจะแก้แค้นเพราะความโกรธและความกริ้วต่อประชาชาติ ดังที่ไม่เคยมีใครได้ยินเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 1, 'จงฟังสิ่งที่พระเยโฮวาห์ตรัส จงลุกขึ้น แถลงคดีของเจ้าต่อหน้าภูเขาทั้งหลาย จงให้เนินเขาฟังเสียงของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 2, 'โอ ภูเขาทั้งหลาย ทั้งรากฐานที่ทนทานของพิภพเอ๋ย จงฟังคดีของพระเยโฮวาห์เถิด เพราะว่าพระเยโฮวาห์ทรงมีคดีกับประชาชนของพระองค์ และพระองค์จะทรงสู้ความกับอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 3, '“โอ ประชาชนของเราเอ๋ย เราได้กระทําอะไรแก่เจ้า เราได้ให้เจ้าอ่อนเพลียในกรณีใด จงตอบมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 4, 'ด้วยว่าเราได้นําเจ้าขึ้นมาจากแผ่นดินอียิปต์ และไถ่เจ้ามาจากเรือนทาส และเราใช้ให้โมเสส อาโรน และมิเรียม นําหน้าเจ้าไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 5, 'โอ ประชาชนของเราเอ๋ย จงระลึกว่า บาลาคกษัตริย์โมอับคิดอุบายประการใด และบาลาอัมบุตรชายเบโอร์ได้ตอบเขาอย่างไรจากชิทธิมถึงกิลกาล มีอะไรเกิดขึ้น เพื่อเจ้าจะได้ทราบความชอบธรรมของพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 6, '“ข้าพเจ้าจะนําอะไรเข้ามาเฝ้าพระเยโฮวาห์ และกราบไหว้ต่อพระพักตร์พระเจ้าเบื้องสูง ควรข้าพเจ้าเข้าเฝ้าพระองค์ด้วยเครื่องเผาบูชาหรือ ด้วยลูกวัวอายุหนึ่งขวบหลายตัวหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 7, 'พระเยโฮวาห์จะทรงพอพระทัยการถวายแกะเป็นพันๆตัว และธารน้ํามันหลายหมื่นสายหรือ ควรที่ข้าพเจ้าจะถวายบุตรหัวปีชําระการละเมิดของข้าพเจ้าหรือ คือถวายผลแห่งกายของข้าพเจ้าชําระบาปแห่งวิญญาณของข้าพเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 8, 'โอ มนุษย์เอ๋ย พระองค์ทรงสําแดงแก่เจ้าแล้วว่าอะไรดี และพระเยโฮวาห์ทรงมีพระประสงค์อะไรจากเจ้า นอกจากให้กระทําความยุติธรรม และรักความเมตตา และดําเนินด้วยความถ่อมใจไปกับพระเจ้าของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 9, 'พระสุรเสียงพระเยโฮวาห์ประกาศแก่นครนั้น คนที่มีสติปัญญาจะพิจารณาดูพระนามของพระองค์ จงฟังคทา และผู้ที่ทรงตั้งมันไว้เถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 10, 'ยังมีทรัพย์สมบัติแห่งความชั่วร้ายในเรือนของคนชั่ว และเครื่องตวงที่พร่องไปซึ่งน่าสะอิดสะเอียนนั้นอยู่อีกหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 11, 'เราจะถือพวกที่มีตาชั่งที่ชั่วร้าย และมีถุงเต็มด้วยลูกตุ้มขี้โกงว่า ไม่มีความผิดได้หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 12, 'บรรดาคนมั่งมีของเจ้าก็เต็มไปด้วยความทารุณ และชาวเมืองของเจ้าก็พูดมุสา และลิ้นของเขาก็ล่อลวงอยู่ในปากของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 13, 'เพราะฉะนั้นเราจะกระทําให้เจ้าเจ็บป่วยด้วยการเฆี่ยนตีเจ้า ด้วยการกระทําให้เจ้ารกร้างไปเพราะเหตุบาปของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 14, 'เจ้าจะรับประทาน แต่จะไม่รู้จักอิ่ม และส่วนภายในของเจ้าก็จะมีแต่ความหิว เจ้าจะเก็บไว้ แต่ก็ไม่สั่งสม อะไรที่เจ้าสั่งสม เราก็จะให้แก่ดาบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 15, 'เจ้าจะหว่าน แต่เจ้าจะไม่ได้เกี่ยว เจ้าจะย่ําบีบมะกอกเทศ แต่จะไม่ได้ชโลมตัวเองด้วยน้ํามัน เจ้าจะย่ําองุ่น แต่จะไม่ได้ดื่มน้ําองุ่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 16, 'เพราะได้มีการถือรักษากฎเกณฑ์ของอมรี และบรรดากิจการแห่งวงศ์วานของอาหับ และเจ้าได้ดําเนินตามคําแนะนําของคนพวกนี้ เพื่อเราจะกระทําให้เจ้าเป็นที่รกร้าง และชาวเมืองที่อาศัยอยู่ในนั้นจะเป็นที่เย้ยหยัน ฉะนั้นเจ้าจะต้องทนรับการดุด่าว่ากล่าวจากชนชาติของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 1, 'วิบัติแก่ข้าพเจ้า เพราะข้าพเจ้าเป็นเหมือนคนที่พบว่าเขาเก็บผลในฤดูร้อนหมดแล้ว และเล็มผลจากเถาองุ่นหมดแล้ว ไม่มีพวงองุ่นรับประทาน จิตใจข้าพเจ้าปรารถนาผลสุกรุ่นแรก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 2, 'คนดีสูญหายไปจากโลก จะหาคนซื่อตรงท่ามกลางมนุษย์สักคนก็ไม่มี ต่างก็ซุ่มคอยจะเอาโลหิตกัน ต่างก็เอาตาข่ายดักพี่น้องของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 3, 'มือทั้งสองของเขาคอยจ้องแต่สิ่งที่ชั่ว เพื่อจะกระทําด้วยความขยัน เจ้านายและผู้พิพากษาขอสินบน และคนใหญ่คนโตก็เอ่ยถึงความปรารถนาชั่วแห่งจิตใจของเขา ต่างก็สานสิ่งเหล่านี้เข้าด้วยกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 4, 'คนที่ดีที่สุดของเขาก็เหมือนหนามย่อย คนที่ซื่อตรงที่สุดของเขาก็คมกว่ารั้วต้นไม้หนาม วันแห่งยามรักษาการณ์ของเจ้า และวันที่จะลงโทษเจ้า มาถึงแล้ว บัดนี้ ความยุ่งเหยิงของเขาก็อยู่ใกล้เต็มที');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 5, 'อย่าวางใจในสหาย อย่ามั่นใจในคนนําทาง จงเฝ้าประตูปากของเจ้า อย่าเผยอะไรแก่เธอที่อยู่ในอ้อมอกของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 6, 'เพราะว่าลูกชายดูหมิ่นพ่อ และลูกสาวลุกขึ้นต่อสู้แม่ของเธอ ลูกสะใภ้ต่อสู้แม่สามี ศัตรูของใครๆก็คือคนที่อยู่ร่วมเรือนของเขาเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 7, 'เพราะฉะนั้นสําหรับข้าพเจ้า ข้าพเจ้าจะมองดูพระเยโฮวาห์ ข้าพเจ้าจะเฝ้าคอยพระเจ้าแห่งความรอดของข้าพเจ้า พระเจ้าของข้าพเจ้าจะทรงฟังข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 8, 'โอ ศัตรูของข้าพเจ้าเอ๋ย อย่าเปรมปรีดิ์เย้ยข้าพเจ้าเลย เมื่อข้าพเจ้าล้มลง ข้าพเจ้าจะลุกขึ้นอีก เมื่อข้าพเจ้านั่งอยู่ในความมืด พระเยโฮวาห์จะทรงเป็นความสว่างแก่ข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 9, 'ข้าพเจ้าจะทนต่อพระพิโรธของพระเยโฮวาห์ เพราะว่าข้าพเจ้ากระทําบาปต่อพระองค์ ข้าพเจ้าจะทนจนกว่าพระองค์จะทรงแก้คดีของข้าพเจ้า และกระทําการตัดสินเพื่อข้าพเจ้า พระองค์จะทรงนําข้าพเจ้าไปยังความสว่าง และข้าพเจ้าจะเห็นความชอบธรรมของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 10, 'แล้วเธอซึ่งเป็นศัตรูของข้าพเจ้าจะเห็น และความอับอายจะทับถมเธอที่กล่าวแก่ข้าพเจ้าว่า “พระเยโฮวาห์ พระเจ้าของเจ้าอยู่ที่ไหน” ตาของข้าพเจ้าจะเพ่งดูเธอให้สาแก่ใจ คราวนี้เธอจะถูกย่ําลงเหมือนเลนที่ในถนน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 11, 'วันที่จะสร้างกําแพงเมืองของเจ้า ในวันนั้นคําบัญชาจะถูกปลดเปลื้องไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 12, 'ในวันนั้นเขาจะมาหาเจ้าคือมาจากอัสซีเรียและจากเมืองที่มีป้อมปราการ จากระหว่างป้อมปราการกับแม่น้ํา จากระหว่างทะเลนี้กับทะเลโน้น และจากระหว่างภูเขานี้กับภูเขาโน้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 13, 'ถึงกระนั้นแผ่นดินก็จะรกร้างเพราะคนที่อาศัยในแผ่นดินนั้นเป็นเหตุ เนื่องด้วยผลแห่งการกระทําของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 14, 'ขอทรงเลี้ยงดูประชาชนของพระองค์ด้วยคทาของพระองค์ คือฝูงประชาชนที่เป็นมรดกของพระองค์ ผู้อาศัยโดดเดี่ยวอยู่ในป่า ในท่ามกลางคารเมล ขอทรงให้เขาหากินอยู่ในบาชานและกิเลอาดอย่างในโบราณกาล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 15, 'ดังในสมัยเมื่อเจ้าออกจากแผ่นดินอียิปต์ เราจะสําแดงสิ่งมหัศจรรย์แก่เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 16, 'ประชาชาติทั้งหลายจะแลเห็นและอับอายด้วยอานุภาพทั้งสิ้นของเขาทั้งหลาย เขาทั้งหลายจะเอามือปิดปากไว้และหูของเขาจะหนวกไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 17, 'เขาทั้งหลายจะเลียผงคลีเหมือนอย่างงู เขาจะเคลื่อนตัวออกจากรูของเขาดุจหนอนบนแผ่นดินโลก เขาจะตระหนกตกใจพระเยโฮวาห์พระเจ้าของเรา เนื่องด้วยเจ้า เขาทั้งหลายจะกลัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 18, 'ใครเล่าจะเป็นพระเจ้าเสมอเหมือนพระองค์ ผู้ทรงยกโทษความชั่วช้า และทรงให้อภัยการละเมิดแก่คนที่เหลืออยู่อันเป็นมรดกของพระองค์ พระองค์มิได้ทรงถือพระพิโรธเนืองนิตย์ เพราะว่าพระองค์ทรงพอพระทัยในความเมตตา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 19, 'พระองค์จะทรงหันกลับมาอีก พระองค์จะทรงเมตตาเราทั้งหลาย พระองค์จะทรงเหยียบความชั่วช้าของเราไว้ พระองค์จะทรงเหวี่ยงบาปทั้งหลายของเขาลงไปในที่ลึกของทะเล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 20, 'พระองค์จะทรงสําแดงความจริงให้ประจักษ์แก่ยาโคบ และความเมตตาต่ออับราฮัม ดังที่พระองค์ทรงปฏิญาณต่อบรรพบุรุษของเราตั้งแต่สมัยโบราณกาล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 1, 'ภาระเกี่ยวข้องกับนครนีนะเวห์ หนังสือเรื่องนิมิตของนาฮูมชาวเมืองเอลโขช');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 2, 'พระเจ้าทรงเป็นพระเยโฮวาห์ผู้ทรงหวงแหนและทรงแก้แค้น พระเยโฮวาห์ทรงแก้แค้นและทรงมีพระพิโรธ พระเยโฮวาห์จะทรงแก้แค้นศัตรูของพระองค์ และทรงเก็บความโกรธไว้ให้ปัจจามิตรของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 3, 'พระเยโฮวาห์ทรงกริ้วช้า ทรงฤทธานุภาพใหญ่ยิ่ง พระองค์จะไม่ทรงงดโทษคนชั่วเลย พระมรรคาของพระเยโฮวาห์อยู่ในลมหมุนและพายุ และเมฆเป็นผงคลีแห่งพระบาทของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 4, 'พระองค์ทรงห้ามทะเล ทรงกระทําให้มันแห้ง ทรงให้แม่น้ําทั้งหลายแห้งไป บาชานและคารเมลก็เหี่ยว และดอกไม้ของเลบานอนก็เหือดไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 5, 'ต่อเบื้องพระพักตร์พระองค์ ภูเขาก็สั่นสะเทือนและเนินเขาก็ละลายไป แผ่นดินก็เริศร้างต่อเบื้องพระพักตร์พระองค์ เออ ทั้งโลกและสิ่งสารพัดที่อาศัยอยู่ในโลกด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 6, 'ใครจะต้านทานพระพิโรธของพระองค์ได้ ใครจะทนต่อความร้อนแรงแห่งความกริ้วของพระองค์ได้ พระพิโรธของพระองค์พลุ่งออกมาอย่างกับไฟ โดยพระองค์ศิลาก็ถูกเหวี่ยงลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 7, 'พระเยโฮวาห์ประเสริฐ ทรงเป็นที่กําบังเข้มแข็งในวันยากลําบาก พระองค์ทรงรู้จักผู้ที่วางใจในพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 8, 'แต่พระองค์จะทรงกระทําให้สถานที่แห่งนั้นสิ้นสุดลงด้วยน้ําท่วมที่ไหลท่วมท้น และความมืดจะไล่ตามศัตรูทั้งหลายของพระองค์ไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 9, 'เจ้าคิดอุบายอันใดต่อพระเยโฮวาห์ พระองค์จะทรงกระทําให้สิ้นไปอย่างเด็ดขาด ความทุกข์ยากจะไม่โผล่ขึ้นเป็นคํารบสอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 10, 'แม้ว่าเขาทั้งหลายเหมือนหนามไก่ไห้ที่เกี่ยวกันยุ่ง และเมาตามขนาดที่เขาดื่ม เขาจะถูกเผาผลาญสิ้นเหมือนตอข้าวที่แห้งผาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 11, 'เคยมีผู้หนึ่งมาจากพวกเจ้าที่คิดอุบายชั่วร้ายต่อพระเยโฮวาห์และแนะนําความชั่ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 12, 'พระเยโฮวาห์ตรัสดังนี้ว่า “แม้พวกนั้นจะอยู่อย่างสงบและมีจํานวนมากมายด้วย เขาก็จะถูกตัดขาดและสิ้นไปเมื่อเขาผ่านไป แม้ว่าเราให้เจ้าทุกข์ใจบ้าง แต่เราจะไม่ให้เจ้าทุกข์ใจอีกต่อไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 13, 'บัดนี้เราจะหักแอกของเขาเสียจากเจ้า และจะระเบิดเครื่องจองจําของเจ้าให้สลายไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 14, 'พระเยโฮวาห์ตรัสบัญชาด้วยเรื่องเจ้าว่า “เขาจะไม่หว่านชื่อของเจ้าให้แพร่หลายอีกต่อไป เราจะขจัดรูปเคารพที่สลักและรูปเคารพที่หล่อออกเสียจากนิเวศแห่งพระของเจ้า เราจะขุดหลุมศพให้เจ้า เพราะเจ้าชั่วนัก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 15, 'ดูเถิด เท้าของผู้นําข่าวดีมาที่บนภูเขา ผู้โฆษณาสันติภาพ โอ ยูดาห์เอ๋ย จงรักษาประเพณีการเลี้ยงตามกําหนดของเจ้าไว้ จงทําตามคําปฏิญาณของเจ้าเถิด เพราะว่าคนชั่วจะไม่ผ่านเจ้าไปอีก เขาถูกขจัดเสียสิ้นแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 1, 'ผู้ที่ฟาดให้แหลกเป็นชิ้นๆได้ขึ้นมาต่อสู้กับเจ้าแล้ว จงเข้าประจําป้อม จงเฝ้าทางไว้ จงคาดเอวไว้ จงรวมกําลังไว้ให้หมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 2, 'เพราะว่าพระเยโฮวาห์ทรงกระทําให้ความโอ่อ่าตระการของยาโคบกลับสู่สภาพเดิม อย่างกับความโอ่อ่าตระการของอิสราเอล เพราะว่าพวกปล้นได้ปล้นเอาไป และได้ทําลายกิ่งก้านของเขาให้พินาศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 3, 'โล่ของทหารหาญนั้นสีแดง และทหารของเขาก็แต่งกายสีแดงเข้ม ในวันเตรียมพร้อมรถรบก็จะแวบวาบดังคบเพลิง และไม้สนสามใบก็จะสั่นสะท้านอย่างรุนแรง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 4, 'รถรบห้อไปตามถนน มันรีบไปรีบมาที่ลานเมือง ส่องแสงราวกับคบเพลิง และพุ่งไปอย่างสายฟ้าแลบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 5, 'นายทหารถูกเรียกตัว เขาก็สะดุดเมื่อเขาเดินไป เขาจะรีบตรงไปที่กําแพงเมือง มีเพิงกันอาวุธตั้งขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 6, 'ประตูที่แม่น้ําจะเปิด แล้วที่พระราชวังก็จะมลายไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 7, 'ฮัสซาปจะถูกนําไปเป็นเชลย นางจะถูกนําขึ้นไป บรรดาสาวใช้จะนําหน้านางไปด้วยเสียงนกเขา ตีอกชกใจของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 8, 'แต่ตั้งแต่เดิมมาแล้วนีนะเวห์ก็เหมือนสระน้ํา แม้กระนั้นพวกเขาจะหนีออกมา เขาทั้งหลายจะร้องว่า “หยุด หยุด” แต่ก็ไม่มีใครหันกลับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 9, 'ปล้นเอาเงินซิ ปล้นเอาทองคํา มีทรัพย์สมบัติมากมายไม่รู้สิ้นสุด มีสิ่งของเครื่องใช้ทุกอย่างเป็นทรัพย์มั่งคั่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 10, 'เริศร้าง ความเริศร้าง และความพินาศ จิตใจก็ละลายไปและหัวเข่าก็สั่น บั้นเอวก็ปวดร้าวไปหมด ใบหน้าทุกคนซีดเซียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 11, 'ที่อาศัยของสิงโตอยู่ที่ไหน คือที่เลี้ยงอาหารของสิงโตหนุ่ม ที่ที่สิงโตคือสิงโตแก่เคยเดินเข้าไป ที่ที่ลูกของมันเคยอยู่ ไม่มีผู้ใดทําให้มันกลัวได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 12, 'สิงโตนั้นได้ฉีกอาหารให้ลูกของมันพอกิน และได้คาบคอเหยื่อมาให้เหล่าเมียของมัน มันสะสมเหยื่อเต็มถ้ําและสะสมเนื้อที่ฉีกแล้วเต็มรัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 13, 'พระเยโฮวาห์จอมโยธาตรัสว่า ดูเถิด เราต่อสู้เจ้า เราจะเผารถรบของเจ้าให้เป็นควัน และดาบจะสังหารสิงโตหนุ่มของเจ้า เราจะตัดเหยื่อของเจ้าเสียจากโลก และจะไม่มีใครได้ยินเสียงผู้สื่อสารของเจ้าอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 1, 'วิบัติแก่เมืองที่แปดเปื้อนไปด้วยโลหิต เต็มด้วยการมุสาและการโจรกรรม เหยื่อจะไม่จากไปเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 2, 'เสียงขวับของแส้ และเสียงกระหึ่มของล้อ ม้าควบ และรถรบห้อไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 3, 'พลม้าเข้าประจัญบานดาบแวววาวและหอกวาววับ คนถูกฆ่าเป็นก่ายกอง ซากศพกองพะเนิน ร่างคนตายไม่รู้จักจบสิ้น เขาจะสะดุดร่างนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 4, 'ทั้งนี้เพราะการแพศยาอย่างมากนับไม่ถ้วนของหญิงแพศยานั้นผู้มีเสน่ห์ และเป็นจอมวิทยาคม นางได้ขายประชาชาติเสียด้วยการแพศยาของนาง และขายบรรดาครอบครัวมนุษย์ด้วยวิทยาคมของนาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 5, 'พระเยโฮวาห์จอมโยธาตรัสว่า ดูเถิด เราต่อสู้เจ้า และจะยกกระโปรงของเจ้าคลุมหน้าเจ้า เราจะให้บรรดาประชาชาติมองดูความเปลือยเปล่าของเจ้า และให้ราชอาณาจักรทั้งหลายมองดูความอับอายของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 6, 'เราจะโยนของโสโครกที่น่าสะอิดสะเอียนใส่เจ้า และกระทําให้เจ้าน่าขยะแขยง และจะปล่อยให้เจ้าถูกประจาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 7, 'ต่อมาทุกคนที่แลเห็นเจ้าจะหลบหนีไปจากเจ้าและกล่าวว่า “นีนะเวห์เป็นเมืองร้างเสียแล้ว ใครเล่าจะสงสารเธอ” จะไปหาใครที่ไหนมาเล้าโลมเธอได้เล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 8, 'เจ้าวิเศษกว่าเมืองโนซึ่งมีพลเมืองมาก ซึ่งตั้งอยู่ระหว่างแม่น้ําหรือ ซึ่งมีน้ํารอบนคร มีทะเลเป็นที่กําบัง มีทะเลเป็นกําแพงเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 9, 'เอธิโอเปียเป็นกําลังของเมืองนี้ทั้งอียิปต์ และก็ไม่จํากัดเสียด้วย พูตและลิบนีเป็นผู้ช่วยเมืองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 10, 'ถึงกระนั้นเมืองนั้นก็ยังถูกกวาดไป เธอตกไปเป็นเชลย ลูกเล็กเด็กแดงของเธอก็ถูกเหวี่ยงลงแหลกเป็นชิ้นๆที่หัวถนนทุกสาย เขาจับฉลากแบ่งผู้มีเกียรติของเมืองนั้น และคนใหญ่คนโตทั้งสิ้นของเมืองนั้นก็ถูกล่ามโซ่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 11, 'เจ้าจะมึนเมาไปด้วย เจ้าจะถูกซ่อนไว้ เจ้าจะแสวงหากําลังเพราะเหตุศัตรู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 12, 'ป้อมปราการทั้งสิ้นของเจ้าจะเป็นเหมือนต้นมะเดื่อที่มีผลมะเดื่อสุกรุ่นแรก ถ้าถูกเขย่า ก็จะร่วงลงไปในปากของผู้กิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 13, 'ดูเถิด คนของเจ้าซึ่งอยู่ท่ามกลางเจ้าก็เหมือนผู้หญิง ประตูเมืองแห่งแผ่นดินของเจ้าก็เปิดกว้างให้แก่ศัตรูของเจ้า ไฟได้ไหม้ดาลประตูของเจ้าหมดแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 14, 'เจ้าจงชักน้ําขึ้นไว้สําหรับการถูกล้อมนั้น จงเสริมป้อมปราการของเจ้า จงลงไปในบ่อดินเหนียว ย่ําปูนสอให้เข้ากันดี และเสริมให้เตาเผาอิฐแข็งแกร่งขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 15, 'ไฟก็จะคลอกเจ้าที่นั่น ดาบก็จะฟันเจ้า มันจะกินเจ้าเสียอย่างตั๊กแตนวัยกระโดด จงเพิ่มพวกเจ้าให้มากอย่างตั๊กแตนวัยกระโดด จงเพิ่มให้มากเหมือนตั๊กแตนวัยบิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 16, 'เจ้าเพิ่มพวกพ่อค้าให้มากกว่าดวงดาวในท้องฟ้า ตั๊กแตนวัยกระโดดนั้นลอกคราบแล้วก็บินไปเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 17, 'เจ้านายของเจ้าก็เหมือนตั๊กแตนวัยบิน พวกสัสดีของเจ้าก็เหมือนฝูงตั๊กแตนเกาะอยู่ที่รั้วต้นไม้ในวันอากาศเย็น พอดวงอาทิตย์ขึ้น มันก็บินไปหมด ไม่มีใครทราบว่ามันไปที่ไหน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 18, 'โอ กษัตริย์แห่งอัสซีเรียเอ๋ย ผู้เลี้ยงแกะของเจ้าหลับเสียแล้ว ขุนนางของเจ้าจะอาศัยในผงคลี ชนชาติของเจ้ากระจัดกระจายอยู่บนภูเขา ไม่มีผู้ใดรวบรวมเอามาได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 19, 'แผลฟกช้ําของเจ้าไม่มีบรรเทา บาดแผลของเจ้าก็สาหัส ทุกคนผู้ได้ยินข่าวของเจ้า เขาก็ตบมือเยาะเจ้า มีใครเล่าที่ไม่ได้รับภัยอันร้ายเนืองนิตย์ของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 1, 'ภาระที่ฮาบากุกผู้พยากรณ์ได้เห็นมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 2, 'โอ ข้าแต่พระเยโฮวาห์ ข้าพระองค์จะร้องทุกข์นานสักเท่าใด และพระองค์จะมิได้ทรงฟังหรือ ข้าพระองค์จะร้องทูลต่อพระองค์เรื่องความทารุณ และพระองค์ก็จะไม่ทรงช่วยให้รอดหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 3, 'ไฉนพระองค์ทรงให้ข้าพระองค์เห็นความชั่วช้า และให้มองเห็นความยากลําบาก ทั้งการทําลายและความทารุณก็อยู่ตรงหน้าข้าพระองค์ การวิวาทและการทุ่มเถียงกันก็เกิดขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 4, 'ดังนั้น พระราชบัญญัติจึงหย่อนยานและความยุติธรรมก็มิได้ปรากฏเสียเลย เพราะว่าคนชั่วล้อมรอบคนชอบธรรมไว้ ความยุติธรรมจึงปรากฏอย่างวิปลาส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 5, 'จงมองทั่วประชาชาติต่างๆและดูให้ดี จงประหลาดและแปลกใจ ด้วยว่าเราจะกระทําการในกาลสมัยของเจ้า ถึงจะบอก เจ้าก็จะไม่เชื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 6, 'เพราะดูเถิด เรากําลังเร้าคนเคลเดีย ประชาชาติที่ขมขื่นและรีบร้อนนั้น ผู้กรีธาทัพไปทั่วแผ่นดิน เพื่อยึดเอาบ้านเรือนที่มิใช่ของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 7, 'เขาเป็นที่น่าครั่นคร้ามและสยดสยอง ความยุติธรรมและความโอ่อ่าของเขาจะออกมาจากพวกเขาเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 8, 'ม้าทั้งหลายของเขาก็เร็วกว่าเสือดาว และดุร้ายยิ่งกว่าหมาป่ายามเย็น พลม้าของเขาจะรุดหน้าเรื่อยไปอย่างผยอง เออ พลม้าของเขาจะมาจากถิ่นที่ไกล มันจะบินไปอย่างนกอินทรีคอยกินเร็วนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 9, 'เขาทั้งหลายจะพากันมาเพื่อความทารุณ หน้าเขาทั้งหลายจะสะสมเหมือนกับลมจากทิศตะวันออก เขาจะรวบรวมเชลยไว้มากมายเหมือนทราย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 10, 'เขาจะดูหมิ่นบรรดากษัตริย์ และเขาจะเหยียดหยามเจ้านายทั้งหลาย เขาจะหัวเราะเยาะป้อมปราการทุกแห่ง เพราะเขาจะพูนดินขึ้นและยึดป้อมนั้นเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 11, 'แล้วใจของเขาก็จะเปลี่ยนไป เขาจะผ่านไปและกระทําผิด เขาจะให้อํานาจของเขานี้แก่พระของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 12, 'โอ ข้าแต่พระเยโฮวาห์ พระเจ้าของข้าพระองค์ องค์ผู้บริสุทธิ์ของข้าพระองค์ พระองค์มิได้ดํารงมาแต่นิรันดร์ดอกหรือ ข้าพระองค์ทั้งหลายจะไม่ตาย โอ ข้าแต่พระเยโฮวาห์ พระองค์ทรงสถาปนาเขาไว้เพื่อแก่การพิพากษา โอ พระเจ้าผู้ทรงเดชานุภาพ พระองค์ทรงตั้งเขาไว้เพื่อแก่การตีสอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 13, 'พระเนตรของพระองค์บริสุทธิ์เกินที่จะทอดพระเนตรการชั่ว จะทรงมองดูความชั่วช้าก็ไม่ได้ ไฉนพระองค์ทอดพระเนตรคนทรยศ และทรงเงียบอยู่เมื่อคนชั่วกลืนคนที่ชอบธรรมเกินกว่าตัวเขาเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 14, 'เพราะว่าพระองค์ทรงให้มนุษย์เป็นดังปลาในทะเล เป็นดังสิ่งเลื้อยคลาน ที่ไม่มีหัวหน้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 15, 'เขาจับคนทั้งหลายมาด้วยเบ็ด เขาลากคนมาด้วยแห เขารวบคนมาด้วยอวนของเขา เขาจึงเปรมปรีดิ์และเริงโลด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 16, 'เพราะฉะนั้น เขาจึงถวายสัตวบูชาแก่แหของเขา และเผาเครื่องหอมให้แก่อวนของเขา เพราะโดยสิ่งเหล่านี้ เขาจึงดํารงชีพอยู่อย่างฟุ่มเฟือย อาหารของเขาก็สมบูรณ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 17, 'แล้วเขาจะเททิ้งแหของเขา และฆ่าประชาชาติทั้งหลายอย่างไม่ละเว้นตลอดไปเป็นนิตย์หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 1, 'ข้าพเจ้าจะยืนเฝ้าดูอยู่ ข้าพเจ้าจะยืนที่หอคอย และมองออกไปเพื่อจะฟังดูว่า พระองค์จะตรัสอะไรแก่ข้าพเจ้า และข้าพเจ้าจะทูลตอบพระองค์อย่างไรเมื่อข้าพเจ้าถูกตําหนิ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 2, 'และพระเยโฮวาห์ตรัสตอบข้าพเจ้าว่า “จงเขียนนิมิตนั้นลงไป จงเขียนไว้บนแผ่นป้ายให้กระจ่าง เพื่อให้คนที่วิ่งอ่านได้คล่อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 3, 'เพราะว่านิมิตนั้นยังรอเวลาที่กําหนดไว้ แต่ในที่สุด มันก็จะกล่าวออกมา มันไม่มุสา ถ้าดูช้าไป ก็จงคอยสักหน่อย มันจะบังเกิดขึ้นเป็นแน่ คงไม่ล่าช้านัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 4, 'ดูเถิด ผู้ที่จิตใจผยองขึ้นก็ไม่เที่ยงธรรม แต่ว่าคนชอบธรรมจะมีชีวิตดํารงอยู่โดยความเชื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 5, 'ยิ่งกว่านั้น เพราะเขาละเมิดโดยเหล้าองุ่น เขาจึงเป็นคนจองหอง เขาไม่ยอมอยู่บ้าน ความตะกละของเขากว้างเหมือนอย่างนรก อย่างมัจจุราชไม่เคยรู้จักอิ่ม เขากอบโกยประชาชาติทั้งหลายมาเพื่อตัวเขาเอง แล้วรวบรวมชนชาติทั้งหลายเข้ามาเป็นคนของตน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 6, 'ประชาชาติทั้งสิ้นเหล่านี้จะไม่ยกคําอุปมากล่าวต่อเขาหรือ และยกสุภาษิตกล่าวเยาะเขาว่า “วิบัติแก่ผู้ที่สะสมสิ่งที่มิใช่ของตนไว้ จะทําอย่างนี้ได้นานเท่าใดนะ และบรรทุกของที่ยึดเป็นประกันไว้เต็มตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 7, 'ลูกหนี้ของเจ้าจะไม่ลุกขึ้นมาในปัจจุบันทันด่วนหรือ และผู้ใดที่กระทําให้เจ้าตัวสั่นจะไม่ตื่นขึ้นหรือ แล้วเจ้าก็จะถูกเขาริบบ้างละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 8, 'เพราะว่าเจ้าได้ปล้นมาแล้วหลายประชาชาติ ชนชาติทั้งหลายที่เหลืออยู่นั้นจึงจะมาปล้นเจ้า เพราะเจ้าทําให้โลหิตมนุษย์ตก และเพราะการทารุณต่อแผ่นดิน ต่อบรรดาหัวเมืองและต่อบรรดาผู้ที่อยู่ในเมืองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 9, 'วิบัติแก่ผู้ที่อยากได้กําไรมาสู่เรือนของตนด้วยความชั่ว เพื่อจะวางรังของตัวให้สูงเด่นขึ้น เพื่อให้พ้นจากฤทธิ์อํานาจของความชั่วร้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 10, 'ที่จริงเจ้าได้ออกอุบายหาความอับอายมาสู่เรือนของเจ้าโดยกําจัดชนชาติทั้งหลายเป็นอันมากเสีย เจ้าได้ทําบาปต่อจิตใจของเจ้าแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 11, 'เพราะว่าศิลาจะตะโกนออกมาจากผนัง และขื่อก็จะตอบสนองมาจากหมู่ไม้ในเรือน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 12, 'วิบัติแก่ผู้สร้างเมืองด้วยโลหิต และวางรากนครไว้ด้วยความชั่วช้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 13, 'ดูเถิด ที่บรรดาชนชาติทํางานก็เพื่อแก่ไฟ และที่ชนชาติทั้งหลายทําจนเหน็ดเหนื่อยก็เพื่อแก่การไร้สาระ มิได้เป็นเช่นนี้เพราะพระเยโฮวาห์จอมโยธาดอกหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 14, 'เพราะว่าพิภพจะเต็มไปด้วยความรู้ในเรื่องสง่าราศีของพระเยโฮวาห์ดังน้ําที่เต็มทะเล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 15, 'วิบัติแก่ผู้นั้นที่ให้เพื่อนบ้านดื่ม ที่ยื่นขวดไปให้เขาและทําให้เขาเมาไป เพื่อจะเพ่งดูความเปลือยเปล่าของเพื่อนบ้าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 16, 'เจ้าจะอิ่มไปด้วยความอับอาย ไม่ใช่อิ่มด้วยสง่าราศี เจ้าดื่มเองซิ แล้วให้เปิดเผยว่า เจ้าเหมือนผู้ชายที่มิได้เข้าสุหนัต ถ้วยซึ่งอยู่ในพระหัตถ์ขวาของพระเยโฮวาห์จะเวียนมาถึงเจ้า แล้วความอับอายจะพ่นเหนือสง่าราศีของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 17, 'เนื่องด้วยความทารุณที่เจ้ากระทําแก่เลบานอนจะท่วมเจ้า ความพินาศของสัตว์เดียรัจฉานซึ่งกระทําให้เขากลัว เพราะเจ้าทําให้โลหิตมนุษย์ตก และด้วยเหตุความรุนแรงต่อแผ่นดิน ต่อบรรดาหัวเมืองและต่อบรรดาผู้ที่อยู่ในเมืองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 18, 'รูปแกะสลักให้ประโยชน์อะไรเล่า รูปที่ช่างได้แกะสลักไว้ รูปหล่ออันเป็นครูสอนความเท็จให้ประโยชน์อะไร ที่ช่างจะวางใจในสิ่งที่เขาสร้างขึ้น ที่ช่างจะสร้างพระใบ้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 19, 'วิบัติแก่ผู้ที่กล่าวแก่สิ่งที่ทําด้วยไม้ว่า ‘จงตื่นเถิด’ แก่หินใบ้ว่า ‘จงลุกขึ้นเถิด’ สิ่งนี้สั่งสอนอะไรได้หรือ ดูเถิด สิ่งนั้นกะไหล่ทองคําหรือเงิน แต่ไม่มีลมหายใจในสิ่งนั้นเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 20, 'แต่พระเยโฮวาห์ทรงสถิตในพระวิหารบริสุทธิ์ของพระองค์ จงให้สิ้นทั้งพิภพอยู่สงบต่อพระพักตร์พระองค์เถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 1, 'คําอธิษฐานของฮาบากุกผู้พยากรณ์ ตามทํานองชิกกาโยน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 2, 'โอ ข้าแต่พระเยโฮวาห์ ข้าพระองค์ได้ยินกิตติศัพท์ของพระองค์ แล้วข้าพระองค์ยําเกรง โอ ข้าแต่พระเยโฮวาห์ พอถึงกลางยุคขอทรงรื้อฟื้นพระราชกิจของพระองค์ขึ้นใหม่ พอถึงกลางยุคขอทรงแจ้งให้ทราบทั่วกัน เมื่อทรงกริ้ว ขอทรงระลึกถึงความกรุณา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 3, 'พระเจ้าเสด็จจากเทมาน องค์บริสุทธิ์เสด็จจากภูเขาปาราน เซลาห์ สง่าราศีของพระองค์คลุมทั่วฟ้าสวรรค์ และโลกก็เต็มด้วยคําสรรเสริญพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 4, 'ความผ่องใสของพระองค์ดังแสงสว่าง มีเขาออกมาจากพระหัตถ์ของพระองค์ พระองค์ทรงกําบังฤทธานุภาพของพระองค์เสียที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 5, 'โรคระบาดเดินนําหน้าพระองค์ ถ่านที่ไหม้อยู่มาชิดตามหลังพระบาทของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 6, 'พระองค์ประทับยืนและทรงวัดพิภพ พระองค์ทอดพระเนตรและทรงเขย่าประชาชาติ แล้วภูเขานิรันดร์กาลก็กระจัดกระจาย และเนินเขาอันอยู่เนืองนิตย์ก็ยุบต่ําลง การเสด็จของพระองค์ก็เป็นดังดั้งเดิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 7, 'ข้าพเจ้าได้เห็นเต็นท์ของคนคูชันอยู่ในสภาพทุกข์ใจ และม่านแห่งแผ่นดินมีเดียนหวั่นไหว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 8, 'ข้าแต่พระเยโฮวาห์ พระองค์ทรงพระพิโรธต่อแม่น้ําหรือ พระองค์ทรงกริ้วต่อแม่น้ําหรือ หรือว่าพระองค์ทรงโกรธทะเลเมื่อพระองค์เสด็จทรงม้า เมื่อทรงรถรบแห่งความรอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 9, 'คันธนูของพระองค์ก็ถูกเปิดออกจนเปลือยเปล่าทีเดียว ตามคําสัตย์ปฏิญาณของเหล่าตระกูลคือพระดํารัสของพระองค์ เซลาห์ พระองค์ทรงแยกพิภพด้วยแม่น้ําทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 10, 'บรรดาภูเขาเห็นพระองค์ก็บิดเบี้ยวไป กระแสน้ําที่ดุเดือดก็กวาดผ่านไป มหาสมุทรก็ส่งเสียง มันยกมือของมันขึ้นเบื้องสูง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 11, 'ดวงอาทิตย์และดวงจันทร์นิ่งเฉยอยู่ในที่ของมัน เมื่อแสงแห่งลูกธนูของพระองค์พุ่งผ่านไป เมื่อแสงแห่งหอกอันวาววับของพระองค์พุ่งไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 12, 'พระองค์เสด็จไปเหนือพิภพด้วยความโกรธา พระองค์ทรงเหยียบย่ําประชาชาติด้วยความกริ้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 13, 'พระองค์เสด็จออกไปเพื่อช่วยประชาชนของพระองค์ให้รอด เพื่อช่วยผู้ที่พระองค์ทรงเจิมไว้ให้รอด พระองค์ทรงทําให้ศีรษะแห่งเรือนของคนชั่วได้รับบาดเจ็บ โดยการเผยให้เห็นตั้งแต่รากฐานถึงช่วงคอ เซลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 14, 'พระองค์ทรงแทงหัวหน้าหมู่บ้านของเขาด้วยหอกของพระองค์ ผู้มาอย่างลมหมุนเพื่อจะกระจายข้าพเจ้าเสีย เขาจะเปรมปรีดิ์ดังว่าจะกินคนจนเสียเป็นความลับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 15, 'พระองค์ทรงเหยียบย่ําทะเลด้วยม้าของพระองค์ คือน้ํามากหลายซึ่งเดือดพลุ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 16, 'เมื่อข้าพเจ้าได้ยินแล้ว ท้องของข้าพเจ้าก็สะเทือน พอได้ยินเสียง ริมฝีปากของข้าพเจ้าก็สั่น กระดูกของข้าพเจ้าก็ผุพัง และข้าพเจ้าก็สะเทือนอยู่ในตัวข้าพเจ้า เพื่อข้าพเจ้าจะพักอยู่ในวันแห่งความลําบาก เมื่อเขามาถึงประชาชน เขาจะบุกรุกด้วยกองทหารของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 17, 'แม้ต้นมะเดื่อจะไม่มีดอกบาน หรือจะไม่มีผลในเถาองุ่น การตรากตรํากับต้นมะกอกเทศก็สูญเปล่า ทุ่งนาจะมิได้เกิดอาหาร ฝูงสัตว์จะขาดไปจากคอก และจะไม่มีฝูงวัวที่ในโรงนา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 18, 'ถึงกระนั้นข้าพเจ้าจะร่าเริงในพระเยโฮวาห์ ข้าพเจ้าจะเปรมปรีดิ์ในพระเจ้าแห่งความรอดของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 19, 'พระเยโฮวาห์พระเจ้าทรงเป็นกําลังของข้าพเจ้า พระองค์จะทรงกระทําเท้าของข้าพเจ้าเหมือนอย่างตีนกวางตัวเมีย พระองค์จะทรงกระทําให้ข้าพเจ้าเดินไปบนที่สูงทั้งหลายของข้าพเจ้า ถึงหัวหน้านักร้องใช้เครื่องสาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 1, 'พระวจนะของพระเยโฮวาห์ซึ่งมาถึงเศฟันยาห์บุตรชายคูชี ผู้เป็นบุตรชายเกดาลิยาห์ ผู้เป็นบุตรชายอามาริยาห์ ผู้เป็นราชโอรสของเฮเซคียาห์ ในรัชกาลโยสิยาห์ราชโอรสของอาโมน กษัตริย์ของยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 2, 'พระเยโฮวาห์ตรัสว่า “เราจะกวาดทุกสิ่งทุกอย่างให้เกลี้ยงจากพื้นแผ่นดิน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 3, 'พระเยโฮวาห์ตรัสว่า “เราจะกวาดมนุษย์และสัตว์เดียรัจฉานไปเสีย เราจะกวาดนกในอากาศไปเสียทั้งปลาในทะเลด้วย เราจะกวาดล้างสิ่งที่ทําให้สะดุดพร้อมกับคนชั่ว เราจะขจัดมนุษยชาติออกจากพื้นแผ่นดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 4, 'เราจะเหยียดมือของเราออกต่อสู้ยูดาห์ และต่อชาวเยรูซาเล็มทั้งมวล เราจะขจัดกากเดนของพระบาอัลเสียจากสถานที่นี้ และกําจัดชื่อบรรดาเคมาริมพร้อมกับพวกปุโรหิตเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 5, 'กําจัดคนเหล่านั้นที่กราบลงบนดาดฟ้าหลังคาตึกเพื่อไหว้บริวารแห่งฟ้าสวรรค์ คนเหล่านั้นที่กราบลงปฏิญาณต่อพระเยโฮวาห์ และปฏิญาณต่อพระมัลคาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 6, 'คนเหล่านั้นที่หันกลับจากการติดตามพระเยโฮวาห์ ผู้มิได้แสวงหาพระเยโฮวาห์หรือทูลถามพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 7, 'จงนิ่งสงบอยู่ต่อเบื้องพระพักตร์องค์พระผู้เป็นเจ้าพระเจ้า เพราะว่าวันแห่งพระเยโฮวาห์มาใกล้แล้ว พระเยโฮวาห์ทรงเตรียมเครื่องบูชา และทรงกระทําแขกของพระองค์ให้บริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 8, 'และต่อมาในวันที่พระเยโฮวาห์ทรงฆ่าบูชานั้น พระองค์ตรัสว่า “เราจะลงโทษบรรดาเจ้านายและโอรสของกษัตริย์ และบรรดาผู้ที่ตกแต่งตัวด้วยเครื่องแต่งกายต่างด้าว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 9, 'ในวันนั้น เราจะลงโทษทุกคนที่กระโดดข้ามธรณีประตู คือผู้ที่กระทําให้เรือนของนายเต็มไปด้วยความทารุณและการคดโกง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 10, 'พระเยโฮวาห์ตรัสว่า “ต่อมาในวันนั้น จะได้ยินเสียงร้องจากประตูปลา และเสียงร่ําไห้จากแขวงสอง และเสียงโครมครามจากเนินเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 11, 'ชาวตําบลมักเทชเอ๋ย จงร่ําไห้เถิด เพราะพ่อค้าทั้งปวงก็ถูกโค่นลงเสียแล้ว บรรดาผู้ที่ค้าขายกับเงินก็ถูกขจัดเสียแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 12, 'ต่อมาคราวนั้นเราจะเอาตะเกียงส่องดูเยรูซาเล็ม และเราจะลงโทษคนที่ตกตะกอน ผู้ที่กล่าวในใจของตนว่า ‘พระเยโฮวาห์จะไม่ทรงกระทําการดี และพระองค์ก็จะไม่ทรงกระทําการชั่ว’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 13, 'ฉะนั้นทรัพย์สิ่งของของเขาจะถูกปล้น และเรือนของเขาจะรกร้าง ถึงเขาจะสร้างเรือน เขาก็จะไม่ได้อยู่ในเรือนนั้น ถึงเขาจะปลูกสวนองุ่น เขาจะไม่ได้ดื่มน้ําองุ่นจากสวนนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 14, 'วันสําคัญแห่งพระเยโฮวาห์ใกล้เข้ามา ใกล้เข้ามาและเร่งมาก ทั้งเสียงของวันแห่งพระเยโฮวาห์ ผู้แกล้วกล้าจะร้องเสียงดังที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 15, 'วันนั้นเป็นวันแห่งพระพิโรธ เป็นวันแห่งความทุกข์ใจและความซึมเศร้า เป็นวันแห่งการทิ้งให้เสียเปล่าและการทิ้งให้รกร้าง เป็นวันแห่งความมืดและความอึมครึม เป็นวันแห่งเมฆหมอกและความมืดทึบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 16, 'เป็นวันที่มีเสียงแตรและวันโห่ร้องต่อเมืองทั้งหลายที่มีสันปราการและต่อป้อมสูง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 17, 'เราจะนําทุกข์ภัยมาสู่มนุษย์ เขาจะได้เดินไปเหมือนคนตาบอด เพราะเขาได้กระทําบาปต่อพระเยโฮวาห์ โลหิตของเขาจะถูกเทออกเหมือนฝุ่น และเนื้อของเขาจะถูกเทออกเหมือนมูลสัตว์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 18, 'เงินหรือทองคําของเขาก็ดีจะไม่สามารถช่วยเขาให้พ้นได้ในวันแห่งพระพิโรธของพระเยโฮวาห์ แผ่นดินทั้งสิ้นจะถูกเผาผลาญในไฟแห่งความหวงแหนของพระองค์ เพราะพระองค์จะทรงกําจัดคนทั้งปวงที่อาศัยอยู่ในแผ่นดินอย่างรวดเร็ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 1, 'โอ ประชาชาติที่ผู้อื่นไม่ปรารถนาเอ๋ย จงมาชุมนุมกัน เออ มาชุมนุมกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 2, 'ก่อนที่พระบัญชาสําเร็จ ก่อนที่วันนั้นผ่านไปดั่งแกลบที่ปลิว ก่อนที่พระพิโรธอันร้ายแรงแห่งพระเยโฮวาห์จะลงมาเหนือเจ้า ก่อนที่วันแห่งพระพิโรธของพระเยโฮวาห์จะลงมาเหนือเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 3, 'ทุกคนที่ใจถ่อมในแผ่นดินนี้ คือผู้ที่กระทําตามคําตัดสินของพระองค์ จงแสวงหาพระเยโฮวาห์ จงแสวงหาความชอบธรรม แสวงหาความถ่อมใจ ชะรอยเจ้าจะได้รับการกําบังในวันแห่งพระพิโรธของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 4, 'เพราะว่าเมืองกาซาจะถูกทอดทิ้ง และเมืองอัชเคโลนจะเป็นที่รกร้าง ชาวเมืองอัชโดดจะถูกขับไล่ในเวลาเที่ยงวัน และเมืองเอโครนจะถูกถอนรากถอนโคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 5, 'วิบัติแก่เจ้า ชาวเมืองชายทะเล เจ้าผู้เป็นประชาชาติเคเรธี พระวจนะของพระเยโฮวาห์มีมากล่าวโทษเจ้า โอ คานาอัน แผ่นดินของคนฟีลิสเตีย เราจะทําลายเจ้า จนไม่มีชาวเมืองเหลือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 6, 'ชายทะเลนั้นจะเป็นที่อยู่อาศัยและเป็นกระท่อมสําหรับผู้เลี้ยงแกะ และเป็นคอกสําหรับฝูงแพะแกะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 7, 'ชายทะเลนั้นจะเป็นกรรมสิทธิ์ของวงศ์วานยูดาห์ที่เหลืออยู่นั้น เขาจะหากินที่นั่น ครั้นถึงเวลาเย็น เขาจะนอนลงที่ในเหย้าเรือนทั้งหลายของอัชเคโลน เพราะว่าพระเยโฮวาห์พระเจ้าของเขาจะเอาพระทัยใส่เขา และให้เขากลับสู่สภาพเดิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 8, '“เราได้ยินคําด่าของโมอับ และคําครหาของคนอัมโมนแล้ว ซึ่งเขาด่าประชาชนของเรา และอวดอ้างเรื่องเขตแดนของเขาทั้งหลาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 9, 'พระเยโฮวาห์จอมโยธา พระเจ้าของอิสราเอลตรัสว่า “เหตุฉะนี้ เรามีชีวิตอยู่ฉันใด แน่ทีเดียว โมอับจะกลายเป็นเหมือนเมืองโสโดม และคนอัมโมนจะเหมือนเมืองโกโมราห์ คือเป็นที่ขยายพันธุ์ต้นตําแยและบ่อเกลือ และเป็นที่รกร้างอยู่เนืองนิตย์ ชนชาติของเราส่วนที่เหลือจะปล้นเขา และชนชาติของเราที่เหลืออยู่จะยึดเขาเป็นกรรมสิทธิ์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 10, 'นี่จะเป็นผลตอบแทนความจองหองของเขา เพราะเขาด่าและโอ้อวดต่อประชาชนของพระเยโฮวาห์จอมโยธา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 11, 'พระเยโฮวาห์จะทรงเป็นที่เกรงกลัวของเขาทั้งหลาย พระองค์จะทรงกระทําให้พระทั้งหลายของโลกผ่ายผอม และมนุษย์ทั้งปวงจะนมัสการพระองค์ ตามถิ่นฐานของตนทุกคน ร่วมทั้งเกาะแห่งประชาชาติทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 12, 'คนเอธิโอเปียเอ๋ย เจ้าด้วยเหมือนกัน จะต้องถูกประหารเสียด้วยดาบของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 13, 'แล้วพระองค์จะเหยียดพระหัตถ์ของพระองค์ต่อแผ่นดินทางทิศเหนือ และทําลายอัสซีเรีย และจะกระทําให้เมืองนีนะเวห์เป็นที่รกร้าง เป็นที่แห้งแล้งเหมือนถิ่นทุรกันดาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 14, 'ฝูงสัตว์ทั้งหลายจะนอนอยู่ท่ามกลางที่นั้น สัตว์ป่าในประชาชาติทั้งสิ้น ทั้งนกกระทุงและอีกาบ้านจะอาศัยอยู่ที่หัวเสาทั้งหลายของเมืองนั้น เสียงของพวกมันจะร้องอยู่ที่หน้าต่าง ความรกร้างจะอยู่ที่ธรณีประตู เพราะพระองค์จะทรงกระทําให้งานที่ทําด้วยไม้สนสีดาร์เปิดโล่งออก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 15, 'นี่เป็นเมืองที่สนุกสนานที่อยู่ได้อย่างไร้กังวล เป็นเมืองที่คิดในใจของตนว่า “ข้านี่แหละ และไม่มีเมืองอื่นใดนอกเหนือจากข้าอีก” มันกลายเป็นเมืองรกร้างเสียจริงๆ เป็นที่อาศัยนอนของสัตว์ป่า ทุกคนที่ผ่านเมืองนี้ไปจะเย้ยหยันและส่ายมือของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 1, 'วิบัติแก่เมืองนี้ที่โสโครกและเป็นมลทิน เป็นเมืองที่บีบบังคับเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 2, 'เธอไม่ยอมเชื่อฟังเสียงใดๆ และไม่ยอมรับการตีสอนใดๆ เธอไม่วางใจในพระเยโฮวาห์ และเธอไม่เข้ามาใกล้พระเจ้าของเธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 3, 'เจ้านายของเธอก็เหมือนสิงโตที่คําราม ผู้พิพากษาของเธอก็เหมือนหมาป่ายามเย็น ซึ่งไม่แทะกระดูกจนกระทั่งถึงรุ่งเช้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 4, 'ผู้พยากรณ์ของเธอเป็นคนเบาปัญญา เป็นคนทรยศ พวกปุโรหิตของเธอก็กระทําสถานบริสุทธิ์ให้มัวหมอง เขาฝ่าฝืนต่อพระราชบัญญัติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 5, 'พระเยโฮวาห์ผู้ทรงดํารงอยู่ในเมืองนั้นชอบธรรม พระองค์จะมิได้ทรงกระทําความชั่วช้าเลย ทุกเช้าพระองค์สําแดงคําตัดสินของพระองค์ พระองค์มิได้ทรงขาดเลย แต่คนอธรรมไม่รู้จักอาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 6, '“เราได้ขจัดประชาชาติทั้งหลายออกเสียแล้ว หอคอยของเขาก็รกร้าง เรากระทําให้ถนนของเมืองนั้นเสียไปเปล่าๆ ไม่มีใครผ่านไปมา หัวเมืองของเขาถูกทําลาย เพื่อจะไม่มีคน ไม่มีชาวเมืองอยู่เลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 7, 'เรากล่าวว่า ‘แท้จริง เมืองนั้นจะยําเกรงเรา เธอจะยอมรับคําสั่งสอน’ เพื่อที่อาศัยของเขาจะไม่ถูกตัดออก เราลงโทษเขาอย่างไรก็ตาม แต่เขาทั้งหลายยิ่งกลับร้อนใจที่จะให้การกระทําของเขาเสื่อมทราม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 8, 'พระเยโฮวาห์จึงตรัสว่า “เพราะฉะนั้นจงคอยเรา คอยวันที่เราลุกขึ้นเพื่อทําการปล้น เพราะการตกลงใจของเราก็คือจะรวมประชาชาติ ให้ราชอาณาจักรชุมนุมกัน เพื่อเทความกริ้วของเราบนเขาทั้งหลาย คือความร้อนแรงแห่งความโกรธของเรา เพราะว่าพิภพทั้งสิ้นจะถูกเผาผลาญในไฟแห่งความหวงแหนของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 9, 'ในคราวนั้น เราจะให้ประชาชนนั้นหันไปใช้ภาษาบริสุทธิ์ เพื่อว่าทุกคนจะร้องทูลออกพระนามพระเยโฮวาห์ และปรนนิบัติพระองค์เป็นใจเดียวกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 10, 'บุคคลที่ทูลขอต่อเรา คือบุตรสาวแห่งคนของเราที่ถูกกระจัดกระจายไป จะนําเอาเครื่องบูชาของเรามาจากฟากข้างโน้นของแม่น้ําแห่งเอธิโอเปีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 11, 'ในวันนั้น เจ้าจะไม่ถูกกระทําให้อับอายด้วยการกระทําทั้งสิ้นซึ่งเจ้าได้ละเมิดต่อเรา เพราะในเวลานั้นเราจะคัดผู้โอ้อวดเห่อเหิมนั้นออกเสียจากท่ามกลางเจ้า เจ้าจึงจะไม่เย่อหยิ่งจองหองเพราะเหตุภูเขาบริสุทธิ์ของเราอีกต่อไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 12, 'เพราะเราจะเหลือแต่คนที่ทุกข์ยากและขัดสนไว้ในท่ามกลางเจ้า เขาจะวางใจในพระนามแห่งพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 13, 'บรรดาคนที่เหลืออยู่ในอิสราเอล เขาจะไม่กระทําความชั่วช้า และไม่กล่าวคํามุสา และในปากของเขานั้นจะหาลิ้นที่ล่อลวงก็ไม่มี เพราะเขาทั้งหลายจะเที่ยวหากินและนอนลง และไม่มีผู้ใดกระทําให้เขากลัวเกรง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 14, 'โอ บุตรสาวแห่งศิโยนเอ๋ย จงร้องเพลงเสียงดัง โอ อิสราเอลเอ๋ย จงโห่ร้องเถิด จงเปรมปรีดิ์และเริงโลดด้วยเต็มใจของเจ้าเถิด โอ บุตรสาวแห่งเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 15, 'พระเยโฮวาห์ทรงล้มเลิกการพิพากษาลงโทษเจ้าแล้ว พระองค์ทรงขับไล่ศัตรูของเจ้าออกไปแล้ว กษัตริย์แห่งอิสราเอลคือพระเยโฮวาห์ทรงอยู่ท่ามกลางเจ้า เจ้าจะไม่พบความชั่วร้ายอีกต่อไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 16, 'ในวันนั้น เขาจะพูดกับเยรูซาเล็มว่า ‘อย่ากลัวเลย’ และพูดกับศิโยนว่า ‘อย่าให้มือของเจ้าอ่อนเพลียไป’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 17, 'พระเยโฮวาห์พระเจ้าของเจ้าซึ่งอยู่ท่ามกลางเจ้าทรงมหิทธิฤทธิ์ พระองค์จะทรงช่วยให้รอด พระองค์จะทรงเปรมปรีดิ์เพราะเจ้าด้วยความยินดี พระองค์จะทรงพํานักในความรักของพระองค์ พระองค์จะทรงเริงโลดเพราะเจ้าด้วยร้องเพลงเสียงดัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 18, 'เราจะรวบรวมคนที่เศร้าโศกให้มายังที่ประชุมอันศักดิ์สิทธิ์ คือคนในพวกเจ้าซึ่งต้องทนต่อการเยาะเย้ย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 19, 'ดูเถิด ในคราวนั้นเราจะกวาดล้างผู้ที่บีบบังคับเจ้าทุกคน เราจะช่วยคนขาพิการให้รอดพ้น และรวบรวมคนที่กระจัดกระจายไป และเราจะเปลี่ยนความอับอายของเขาให้เป็นความน่าสรรเสริญ และให้เป็นเสียงลือไปทั่วโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 20, 'ในคราวนั้นเราจะนําเจ้ากลับเข้ามา คือในคราวที่เรารวบรวมพวกเจ้าเข้าด้วยกัน เออ เราจะกระทําให้เจ้ามีชื่อเสียงและเป็นที่สรรเสริญในท่ามกลางบรรดาชนชาติทั้งหลายของโลก คือเมื่อเราให้เจ้ากลับสู่สภาพเดิมต่อหน้าต่อตาเจ้า” พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 1, 'ณ วันที่หนึ่ง เดือนที่หก ปีที่สองแห่งรัชกาลกษัตริย์ดาริอัส พระวจนะของพระเยโฮวาห์มาโดยทางฮักกัย ผู้พยากรณ์ ถึงเศรุบบาเบลบุตรชายเชอัลทิเอล ผู้ว่าราชการเมืองยูดาห์ และถึงโยชูวาบุตรชายเยโฮซาดัก มหาปุโรหิต ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 2, '“พระเยโฮวาห์จอมโยธาตรัสดังนี้ว่า ประชาชนเหล่านี้กล่าวว่า เวลานั้นยังไม่มาถึง คือเวลาที่จะสร้างพระนิเวศของพระเยโฮวาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 3, 'แล้วพระวจนะของพระเยโฮวาห์จึงมาถึงโดยทางฮักกัยผู้พยากรณ์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 4, '“โอ เจ้าทั้งหลาย ถึงเวลาแล้วหรือที่ตัวเจ้าเองอาศัยอยู่ในบ้านที่มีไม้บุ แต่ส่วนพระนิเวศนี้ทิ้งให้พังทลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 5, 'เพราะฉะนั้น บัดนี้พระเยโฮวาห์จอมโยธาจึงตรัสว่า จงพิจารณาดูว่า เจ้ามีความเป็นอยู่อย่างไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 6, 'เจ้าหว่านมาก แต่เกี่ยวน้อย เจ้ารับประทาน แต่ไม่เคยอิ่ม เจ้าดื่ม แต่ก็ไม่เคยหายอยาก เจ้านุ่งห่ม แต่ก็ไม่มีใครอุ่น ผู้ที่ได้ค่าจ้าง ก็ได้ค่าจ้างมาใส่ถุงที่มีรู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 7, 'พระเยโฮวาห์จอมโยธาตรัสดังนี้ว่า จงพิจารณาดูว่า เจ้ามีความเป็นอยู่อย่างไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 8, 'พระเยโฮวาห์ตรัสว่า จงขึ้นไปที่เนินเขาและนําไม้มาสร้างพระนิเวศ เราจะมีความพอใจในพระนิเวศนั้น และเราจะได้รับเกียรติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 9, 'เจ้าทั้งหลายหวังได้มาก แต่ดูเถิด ก็ได้น้อย และเมื่อเจ้านําผลมาบ้านของเจ้า เราก็เป่ามันไปเสีย พระเยโฮวาห์จอมโยธาตรัสว่า ทําไมเป็นอย่างนั้นเล่า ก็เพราะนิเวศของเราพังทลายอยู่ ฝ่ายเจ้าต่างก็สาละวนอยู่กับเรื่องบ้านของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 10, 'เพราะฉะนั้น ท้องฟ้าที่อยู่เหนือเจ้าจึงยั้งน้ําค้างไว้เสีย และโลกก็ยึดพืชผลของมันไว้เสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 11, 'และเราก็เรียกความแห้งแล้งมาสู่แผ่นดินและเนินเขา มาสู่ข้าว น้ําองุ่นใหม่ และน้ํามัน มาสู่สิ่งต่างๆซึ่งดินอํานวยผล สู่มนุษย์และสัตว์ และมาสู่ผลงานทั้งสิ้นซึ่งมือกระทําไว้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 12, 'แล้วเศรุบบาเบล บุตรชายเชอัลทิเอลและโยชูวา บุตรชายเยโฮซาดัก มหาปุโรหิต พร้อมกับประชาชนทั้งปวงที่เหลืออยู่ได้เชื่อฟังพระสุรเสียงของพระเยโฮวาห์ พระเจ้าของเขาทั้งหลาย และถ้อยคําของฮักกัยผู้พยากรณ์ เพราะว่าพระเยโฮวาห์พระเจ้าของเขาทั้งหลายได้ทรงใช้ท่านมา และประชาชนก็เกรงกลัวต่อพระพักตร์พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 13, 'แล้วฮักกัย ทูตของพระเยโฮวาห์ จึงกล่าวแก่ประชาชนตามกระแสรับสั่งของพระเยโฮวาห์ว่า “พระเยโฮวาห์ตรัสว่า เราอยู่กับเจ้าทั้งหลาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 14, 'และพระเยโฮวาห์ทรงเร้าใจเศรุบบาเบลบุตรชายเชอัลทิเอล ผู้ว่าราชการเมืองยูดาห์ และทรงเร้าใจของโยชูวาบุตรชายเยโฮซาดัก มหาปุโรหิต และเร้าใจประชาชนทั้งปวงที่เหลืออยู่นั้น เขาทั้งหลายก็มาทํางานในพระนิเวศของพระเยโฮวาห์จอมโยธา พระเจ้าของเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 15, 'ณ วันที่ยี่สิบสี่ของเดือนที่หก ในปีที่สองแห่งรัชกาลกษัตริย์ดาริอัส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 1, 'ณ วันที่ยี่สิบเอ็ด เดือนที่เจ็ด พระวจนะของพระเยโฮวาห์มาโดยทางฮักกัยผู้พยากรณ์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 2, '“จงกล่าวแก่เศรุบบาเบลบุตรชายเชอัลทิเอล ผู้ว่าราชการเมืองยูดาห์ และแก่โยชูวาบุตรชายเยโฮซาดัก มหาปุโรหิต และแก่ประชาชนที่เหลืออยู่เถิด ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 3, 'ใครบ้างที่เหลืออยู่ท่ามกลางพวกท่านนี้ ที่เห็นพระนิเวศนี้ครั้งเมื่อมีสง่าราศีเดิมนั้น บัดนี้ท่านเหล่านั้นเห็นเป็นอย่างไร มองดูแล้วเปรียบกันไม่ได้เลยใช่ไหม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 4, 'พระเยโฮวาห์ตรัสว่า โอ เศรุบบาเบลเอ๋ย แม้กระนั้นก็ดี จงกล้าหาญเถิด โอ โยชูวาบุตรชายเยโฮซาดัก มหาปุโรหิตเอ๋ย จงกล้าหาญเถิด ประชาชนทั้งสิ้นแห่งแผ่นดินเอ๋ย จงกล้าหาญเถิด พระเยโฮวาห์ตรัสดังนี้แหละ พระเยโฮวาห์จอมโยธาตรัสว่า จงทํางานเถิด เพราะเราอยู่กับเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 5, 'ตามถ้อยคําซึ่งเราได้ทําเป็นพันธสัญญาไว้กับเจ้า เมื่อเจ้าทั้งหลายออกจากอียิปต์ วิญญาณของเราอยู่ท่ามกลางเจ้า อย่ากลัวเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 6, 'เพราะพระเยโฮวาห์จอมโยธาตรัสดังนี้ว่า อีกสักหน่อย เราจะเขย่าท้องฟ้าและโลก ทะเลและแผ่นดินแห้ง อีกครั้งหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 7, 'เราจะเขย่าประชาชาติทั้งสิ้น เพื่อความปรารถนาของประชาชาติทั้งสิ้นจะได้เข้ามา เราจะบรรจุนิเวศนี้ให้เต็มด้วยสง่าราศี พระเยโฮวาห์จอมโยธาตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 8, 'เงินเป็นของเรา และทองคําเป็นของเรา พระเยโฮวาห์จอมโยธาตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 9, 'พระเยโฮวาห์จอมโยธาตรัสว่า สง่าราศีของพระนิเวศครั้งหลังนี้จะยิ่งกว่าครั้งเดิมนั้น พระเยโฮวาห์จอมโยธาตรัสว่า และเราจะให้เกิดความสมบูรณ์พูนสุขในสถานที่นี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 10, 'เมื่อวันที่ยี่สิบสี่ เดือนที่เก้า ในปีที่สองของรัชกาลดาริอัส พระวจนะของพระเยโฮวาห์มาโดยทางฮักกัยผู้พยากรณ์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 11, '“พระเยโฮวาห์จอมโยธาตรัสดังนี้ว่า จงถามบรรดาปุโรหิตเกี่ยวกับราชบัญญัติเถิดว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 12, '‘ถ้าผู้ใดยกชายเสื้อคลุมทําพกห่อเนื้อบริสุทธิ์ไป หากว่าชายเสื้อตัวนั้นไปถูกขนมปังหรือแกง หรือน้ําองุ่น หรือน้ํามัน หรืออาหารใดๆ สิ่งนั้นจะพลอยบริสุทธิ์ไปด้วยหรือไม่’” พวกปุโรหิตตอบว่า “ไม่บริสุทธิ์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 13, 'แล้วฮักกัยจึงถามว่า “ถ้าคนหนึ่งคนใดที่มลทินเพราะไปถูกศพมา แล้วมาถูกสิ่งเหล่านี้เข้า สิ่งเหล่านี้จะมลทินไปด้วยหรือไม่” ปุโรหิตตอบว่า “สิ่งเหล่านี้จะมลทินไปด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 14, 'ฮักกัยจึงตอบว่า “พระเยโฮวาห์ตรัสว่า ต่อหน้าเรา ชนชาตินี้เป็นอย่างนั้นและประชาชาตินี้ก็เป็นอย่างนั้น ผลงานทุกอย่างที่มือของเขากระทําเป็นอย่างนั้นด้วย และสิ่งใดๆที่เขาถวายบูชาที่นั่น ก็เป็นมลทิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 15, 'บัดนี้ จงพิจารณาเถิดว่า ตั้งแต่วันนี้เป็นต้นไปจะเกิดเหตุอะไรขึ้นบ้าง คือก่อนที่ศิลาก้อนหนึ่งจะวางซ้อนบนศิลาก้อนหนึ่งที่ในพระวิหารของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 16, 'ก่อนสิ่งเหล่านี้เกิดขึ้น เมื่อผู้ใดมายังกองข้าวคิดว่าจะตวงได้ยี่สิบถัง ก็มีแต่สิบถัง เมื่อผู้หนึ่งมาถึงบ่อเก็บน้ําองุ่นเพื่อตักเอาห้าสิบถัง ก็มีแต่ยี่สิบถัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 17, 'พระเยโฮวาห์ตรัสว่า เราได้โจมตีเจ้าและผลงานทั้งสิ้นจากมือของเจ้าด้วยให้ข้าวม้าน และขึ้นรา และด้วยลูกเห็บ แต่เจ้าทั้งหลายก็ยังไม่หันมาหาเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 18, 'จงพิจารณาตั้งแต่วันนี้เป็นต้นไป คือวันที่ยี่สิบสี่ เดือนที่เก้า คือตั้งแต่วันที่วางรากฐานแห่งพระวิหารของพระเยโฮวาห์ จงพิจารณาดู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 19, 'ยังมีข้าวตกค้างอยู่ในยุ้งบ้างหรือ เถาองุ่น ต้นมะเดื่อ และต้นทับทิมกับต้นมะกอกเทศยังไม่เกิดผลหรือ ตั้งแต่วันนี้เป็นต้นไป เราจะอํานวยพรแก่เจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 20, 'พระวจนะของพระเยโฮวาห์มาถึงฮักกัยเป็นครั้งที่สองเมื่อวันที่ยี่สิบสี่ของเดือนนั้นว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 21, '“จงพูดกับเศรุบบาเบลผู้ว่าราชการเมืองยูดาห์ว่า เราจะเขย่าท้องฟ้าและโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 22, 'และเราจะคว่ําพระที่นั่งของบรรดาราชอาณาจักร เราจะทําลายเรี่ยวแรงของบรรดาราชอาณาจักรแห่งประชาชาติ และจะคว่ํารถรบกับผู้ขับขี่ ม้าและผู้ขับขี่จะต้องล้มลง คือทุกคนจะต้องล้มลงด้วยดาบแห่งพี่น้องของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 23, 'พระเยโฮวาห์จอมโยธาตรัสว่า ในวันนั้นเราจะรับเจ้า โอ เศรุบบาเบล บุตรชายเชอัลทิเอล ผู้รับใช้ของเราเอ๋ย พระเยโฮวาห์ตรัสว่า เราจะกระทําเจ้าให้เป็นดังแหวนตรา เพราะเราได้เลือกสรรเจ้าแล้ว พระเยโฮวาห์จอมโยธาตรัสดังนี้แหละ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 1, 'ในเดือนที่แปด ปีที่สองแห่งรัชกาลดาริอัส พระวจนะของพระเยโฮวาห์มายังเศคาริยาห์ บุตรชายของเบเรคิยาห์ ผู้เป็นบุตรชายของอิดโด ผู้พยากรณ์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 2, '“พระเยโฮวาห์ทรงกริ้วต่อบรรพบุรุษของเจ้าทั้งหลายเป็นอย่างยิ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 3, 'เพราะฉะนั้น จงกล่าวแก่เขาทั้งหลายว่า พระเยโฮวาห์จอมโยธาตรัสดังนี้ว่า จงกลับมาหาเรา พระเยโฮวาห์จอมโยธาตรัสดังนี้แหละ และเราจะกลับมาหาเจ้า พระเยโฮวาห์จอมโยธาตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 4, 'อย่าเป็นเหมือนบรรพบุรุษของเจ้า ซึ่งบรรดาผู้พยากรณ์คนก่อนๆร้องบอกเขาว่า ‘พระเยโฮวาห์จอมโยธาตรัสดังนี้ว่า จงหันกลับเสียจากทางชั่วของเจ้า และจากการกระทําที่ชั่วของเจ้าเถิด’ พระเยโฮวาห์ตรัสว่า แต่เขาไม่ได้ยินและมิได้ฟังเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 5, 'บรรพบุรุษของเจ้า เขาอยู่ที่ไหน พวกผู้พยากรณ์เล่า เขามีชีวิตอยู่เป็นนิตย์หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 6, 'แต่ถ้อยคําของเราและกฎเกณฑ์ของเรา ซึ่งเราได้บัญชาแก่ผู้พยากรณ์ผู้รับใช้ของเราก็ได้ติดตามบรรพบุรุษของเจ้าทันมิใช่หรือ จนเขากลับใจแล้วกล่าวว่า ‘พระเยโฮวาห์จอมโยธาทรงดําริว่าจะทรงกระทําแก่เราประการใด ในเรื่องวิถีทางและการกระทําของเรา พระองค์ทรงกระทําแก่เราอย่างนั้น’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 7, 'เมื่อวันที่ยี่สิบสี่ เดือนที่สิบเอ็ด ซึ่งเป็นเดือนเชบัท ในปีที่สองแห่งรัชกาลดาริอัส พระวจนะของพระเยโฮวาห์มายังเศคาริยาห์ บุตรชายของเบเรคิยาห์ ผู้เป็นบุตรชายของอิดโด ผู้พยากรณ์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 8, '“ณ กลางคืนวันหนึ่ง ข้าพเจ้าได้มองดู และดูเถิด มีชายคนหนึ่งขี่ม้าสีแดง ยืนอยู่ท่ามกลางต้นน้ํามันเขียวที่ลานหุบเขา ณ เบื้องหลังท่านผู้นั้นมีม้าสีแดง สีแสด และสีขาว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 9, 'แล้วข้าพเจ้าจึงถามว่า ‘โอ นายเจ้าข้า เหล่านี้คืออะไร’ ทูตสวรรค์ที่สนทนากับข้าพเจ้าบอกข้าพเจ้าว่า ‘เราจะสําแดงให้เจ้าทราบว่า เหล่านี้คืออะไร’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 10, 'เหตุฉะนั้นชายที่ยืนอยู่ท่ามกลางต้นน้ํามันเขียวจึงบอกว่า ‘เหล่านี้คือผู้ที่พระเยโฮวาห์ทรงใช้ให้ไปเที่ยวตรวจตราโลก’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 11, 'และเขาเหล่านั้นได้ตอบทูตสวรรค์ของพระเยโฮวาห์ ผู้ยืนอยู่ท่ามกลางต้นน้ํามันเขียวว่า ‘เราได้ตรวจตราโลกแล้ว ดูเถิด ทั้งโลกก็นิ่งสงบอยู่’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 12, 'แล้วทูตสวรรค์ของพระเยโฮวาห์กล่าวว่า ‘โอ ข้าแต่พระเยโฮวาห์จอมโยธา อีกนานเท่าใดพระองค์จะไม่ทรงเมตตากรุงเยรูซาเล็ม และหัวเมืองแห่งยูดาห์ ซึ่งพระองค์ก็ทรงกริ้วมาเจ็ดสิบปีแล้ว พระเจ้าข้า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 13, 'และพระเยโฮวาห์ทรงตอบทูตสวรรค์ผู้ที่สนทนากับข้าพเจ้า เป็นพระวาทะที่ประเสริฐและเล้าโลมใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 14, 'ทูตสวรรค์ผู้ที่สนทนาอยู่กับข้าพเจ้าจึงกล่าวแก่ข้าพเจ้าว่า ‘จงร้องว่า พระเยโฮวาห์จอมโยธาตรัสดังนี้ว่า เรามีความหวงแหนกรุงเยรูซาเล็ม คือกรุงศิโยนเป็นที่ยิ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 15, 'เราโกรธประชาชาติมากที่อยู่อย่างสบายๆ เพราะเมื่อเราโกรธแต่น้อย เขาก็ก่อภัยพิบัติเกินขนาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 16, 'เพราะฉะนั้นพระเยโฮวาห์จึงตรัสว่า เรากลับมายังกรุงเยรูซาเล็มด้วยความกรุณา พระเยโฮวาห์จอมโยธาตรัสว่า จะต้องสร้างนิเวศของเราขึ้นไว้ในนั้น และขึงเชือกวัดไว้เหนือกรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 17, 'จงร้องอีกว่า พระเยโฮวาห์จอมโยธาตรัสดังนี้ว่า เมืองทั้งหลายของเราจะไพบูลย์ท่วมท้นไปด้วยความมั่งคั่งอีก และพระเยโฮวาห์จะปลอบศิโยน และเลือกสรรกรุงเยรูซาเล็มอีกครั้งหนึ่ง’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 18, 'ข้าพเจ้าจึงเงยหน้าขึ้นแลเห็น ดูเถิด มีเขาสี่เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 19, 'ข้าพเจ้าจึงถามทูตสวรรค์ที่สนทนาอยู่กับข้าพเจ้าว่า “เหล่านี้คืออะไร” ท่านจึงตอบข้าพเจ้าว่า “เหล่านี้คือเขาที่ขวิดยูดาห์ อิสราเอลและเยรูซาเล็ม ให้กระจัดกระจายไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 20, 'แล้วพระเยโฮวาห์จึงทรงสําแดงให้ข้าพเจ้าเห็นช่างไม้สี่คน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 21, 'และข้าพเจ้าจึงถามว่า “คนเหล่านี้มาทําอะไรกัน” พระองค์ทรงตอบว่า “เขาเหล่านี้มาขวิดยูดาห์ให้กระจัดกระจายไป จนไม่มีผู้ใดยกศีรษะขึ้นได้อีก และช่างเหล่านี้มากระทําให้เขาหวาดกลัว เพื่อจะเหวี่ยงลงซึ่งเขาแห่งประชาชาติ ที่ยกเขาของตนมาขวิดแผ่นดินยูดาห์กระทําให้กระจัดกระจายไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 1, 'ข้าพเจ้าเงยหน้าขึ้นอีกแลเห็น ดูเถิด ชายคนหนึ่งมีเชือกวัดอยู่ในมือแน่ะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 2, 'ข้าพเจ้าจึงถามว่า “ท่านจะไปไหน” เขาจึงบอกข้าพเจ้าว่า “จะไปวัดเยรูซาเล็มดูว่า กว้างเท่าใด ยาวเท่าใด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 3, 'และดูเถิด ทูตสวรรค์ที่ได้สนทนากับข้าพเจ้าก็ก้าวออกไป และทูตสวรรค์อีกองค์หนึ่งก็ก้าวออกไปพบกับท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 4, 'และบอกท่านว่า “วิ่งซิ บอกชายหนุ่มคนนั้นว่า ‘จะมีคนมาอาศัยอยู่ในเยรูซาเล็มอย่างกับเมืองที่ไม่มีกําแพงล้อม เพราะว่าประชาชนและสัตว์เลี้ยงในนั้นจะมีมากมาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 5, 'เพราะว่าเราจะเป็นเหมือนกําแพงเพลิงล้อมเธอไว้ พระเยโฮวาห์ตรัสว่า และเราจะเป็นสง่าราศีในเมืองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 6, 'พระเยโฮวาห์ตรัสว่า เฮ้ เฮ้ จงหนีไปให้พ้นจากแผ่นดินเหนือ พระเยโฮวาห์ตรัสว่า เพราะเราได้แผ่พวกเจ้าออกดังลมทั้งสี่ทิศของท้องฟ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 7, 'โอ ศิโยนเอ๋ย เจ้าผู้ที่อยู่กับธิดาของบาบิโลน จงหนีไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 8, 'เมื่อสง่าราศีมาแล้ว พระองค์ทรงใช้เราให้ไปยังประชาชาติที่ปล้นเจ้า เพราะว่าผู้ใดได้แตะต้องเจ้า ก็ได้แตะต้องแก้วพระเนตรของพระองค์ พระเยโฮวาห์จอมโยธาจึงตรัสดังนี้ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 9, 'เพราะ ดูเถิด เราจะสั่นมือของเราเหนือเขา และเขาจะเป็นของถูกปล้นให้แก่คนรับใช้ของเขาเอง’ แล้วเจ้าจะได้ทราบว่าพระเยโฮวาห์จอมโยธาใช้ข้าพเจ้ามา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 10, 'โอ บุตรสาวแห่งศิโยนเอ๋ย จงร้องเพลงและร่าเริงเถิด เพราะดูเถิด เรามาและจะอยู่ท่ามกลางเจ้าทั้งหลาย พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 11, 'และประชาชาติเป็นอันมากจะสมทบกันเข้าเป็นฝ่ายพระเยโฮวาห์ในวันนั้น และจะเป็นประชาชนของเรา และเราจะอยู่ท่ามกลางเจ้าทั้งหลาย และเจ้าจะทราบว่าพระเยโฮวาห์จอมโยธาได้ใช้ข้าพเจ้ามายังเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 12, 'และพระเยโฮวาห์จะทรงรับยูดาห์เป็นมรดก เป็นส่วนของพระองค์ในแผ่นดินบริสุทธิ์ และจะเลือกสรรกรุงเยรูซาเล็มอีกครั้งหนึ่ง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 13, 'โอ บรรดาเนื้อหนังเอ๋ย จงนิ่งสงบอยู่ต่อพระพักตร์พระเยโฮวาห์ เพราะว่าพระองค์ทรงตื่นและเสด็จจากที่ประทับอันบริสุทธิ์ของพระองค์แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 1, 'แล้วท่านได้แสดงให้ข้าพเจ้าเห็นโยชูวามหาปุโรหิต ซึ่งยืนอยู่หน้าทูตสวรรค์ของพระเยโฮวาห์ และซาตานยืนอยู่ข้างขวามือของท่าน จะขัดขวางท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 2, 'และพระเยโฮวาห์ตรัสกับซาตานว่า “โอ ซาตาน พระเยโฮวาห์ตรัสห้ามเจ้าเถอะ พระเยโฮวาห์ผู้ทรงเลือกสรรกรุงเยรูซาเล็มทรงห้ามเจ้าเถิด นี่ไม่ใช่ดุ้นฟืนที่ฉวยออกมาจากไฟดอกหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 3, 'ฝ่ายโยชูวานั้นสวมเครื่องแต่งกายสกปรก ยืนอยู่หน้าทูตสวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 4, 'และทูตสวรรค์จึงบอกผู้ที่ยืนอยู่ข้างหน้าท่านว่า “จงเปลื้องเครื่องแต่งกายที่สกปรกจากท่านเสีย” และทูตสวรรค์พูดกับท่านว่า “ดูเถิด เราได้เอาความชั่วช้าออกไปเสียจากเจ้าแล้ว และเราจะประดับตัวเจ้าด้วยเสื้อผ้าอันสะอาด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 5, 'และข้าพเจ้าว่า “จงให้เขาทั้งหลายเอาผ้ามาลาสะอาดมาโพกศีรษะของท่าน” เขาจึงเอาผ้ามาลาสะอาดมาโพกศีรษะของท่าน และสวมเครื่องแต่งกายให้ท่าน และทูตสวรรค์ของพระเยโฮวาห์ก็ยืนอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 6, 'และทูตสวรรค์ของพระเยโฮวาห์จึงกล่าวแก่โยชูวาว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 7, '“พระเยโฮวาห์จอมโยธาตรัสดังนี้ว่า ถ้าเจ้าดําเนินในหนทางของเรา และรักษาคํากําชับของเรา เจ้าจะได้ปกครองนิเวศของเรา และดูแลบริเวณของเรา และเราจะให้เจ้ามีสิทธิที่จะเข้าไปท่ามกลางผู้เหล่านั้นที่ยืนอยู่ที่นี่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 8, 'โอ โยชูวามหาปุโรหิต จงฟังเถิด เจ้าและสหายของเจ้าผู้ที่นั่งอยู่ข้างหน้าเจ้า เพราะคนเหล่านี้เป็นหมายสําคัญ ดูเถิด เราจะนําผู้รับใช้ของเรามา คือ พระอังกูร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 9, 'เพราะว่า พระเยโฮวาห์จอมโยธาตรัสว่า จงดูศิลาซึ่งเราตั้งไว้หน้าโยชูวา เป็นศิลาก้อนเดียวที่มีเจ็ดตา ดูเถิด เราจะสลักบนศิลานั้น และเราจะเปลื้องความชั่วช้าของแผ่นดินนี้ออกไปเสียในวันเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 10, 'พระเยโฮวาห์จอมโยธาตรัสว่า ในวันนั้นเจ้าทุกคนจะเชิญเพื่อนบ้านของเจ้าให้มาใต้เถาองุ่นและใต้ต้นมะเดื่อ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 1, 'และทูตสวรรค์ที่สนทนากับข้าพเจ้ามาอีก และปลุกข้าพเจ้าให้ตื่นเหมือนคนที่เพิ่งตื่นจากการนอนของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 2, 'และท่านถามข้าพเจ้าว่า “เจ้าเห็นอะไร” ข้าพเจ้าตอบว่า “ดูเถิด ข้าพเจ้าเห็นเชิงเทียนทําด้วยทองคําล้วนอันหนึ่ง มีชามอยู่ที่ยอด และมีตะเกียงอยู่บนนั้นเจ็ดดวง และมีท่อเจ็ดท่อนําไปยังตะเกียงซึ่งอยู่บนยอดนั้นดวงละท่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 3, 'และมีต้นมะกอกเทศสองต้นอยู่ข้างๆ อยู่ข้างขวาชามนั้นต้นหนึ่ง อยู่ข้างซ้ายต้นหนึ่ง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 4, 'และข้าพเจ้าถามทูตสวรรค์ผู้ที่สนทนากับข้าพเจ้าว่า “เจ้านายเจ้าข้า นี่คืออะไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 5, 'ทูตสวรรค์ที่สนทนากับข้าพเจ้าตอบข้าพเจ้าว่า “นี่คืออะไร เจ้าไม่ทราบหรือ” ข้าพเจ้าตอบว่า “เจ้านายเจ้าข้า ข้าพเจ้าไม่ทราบ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 6, 'แล้วท่านจึงตอบข้าพเจ้าว่า “นี่เป็นพระวจนะของพระเยโฮวาห์ที่ให้ไว้กับเศรุบบาเบลว่า มิใช่ด้วยกําลัง มิใช่ด้วยฤทธานุภาพ แต่ด้วยวิญญาณของเรา พระเยโฮวาห์จอมโยธาตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 7, 'โอ ภูเขาใหญ่ เจ้าเป็นอะไรเล่า ต่อหน้าเศรุบบาเบลเจ้าจะเป็นที่ราบ และท่านจะนําศิลาก้อนที่อยู่ยอดออกมาท่ามกลางการโห่ร้องว่า ‘งามจริงพระวิหาร งามจริง’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 8, 'ยิ่งกว่านั้นพระวจนะของพระเยโฮวาห์มายังข้าพเจ้ากล่าวว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 9, '“มือของเศรุบบาเบลได้วางรากฐานของพระนิเวศนี้ และมือของเขาจะสร้างให้สําเร็จ แล้วเจ้าจะทราบว่า พระเยโฮวาห์จอมโยธาได้ใช้ข้าพเจ้ามาหาเจ้าทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 10, 'เพราะว่าผู้ใดเล่าที่ดูหมิ่นวันแห่งการเล็กน้อย เพราะเขาจะเปรมปรีดิ์ และจะได้เห็นสายดิ่งที่อยู่ในมือของเศรุบบาเบลพร้อมกับสิ่งทั้งเจ็ดนี้ ซึ่งคือบรรดาพระเนตรของพระเยโฮวาห์ซึ่งมองอยู่ทั่วพิภพ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 11, 'แล้วข้าพเจ้าจึงถามท่านว่า “ต้นมะกอกเทศสองต้นที่อยู่ข้างขวาและข้างซ้ายของเชิงเทียนนั้นคืออะไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 12, 'และข้าพเจ้าถามท่านเป็นครั้งที่สองว่า “กิ่งทั้งสองของต้นมะกอกเทศ ซึ่งอยู่ข้างท่อทองคําทั้งสอง ซึ่งเทน้ํามันออกนั้นคืออะไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 13, 'ท่านพูดกับข้าพเจ้าว่า “เจ้าไม่ทราบหรือ เหล่านี้คืออะไร” ข้าพเจ้าตอบว่า “เจ้านายเจ้าข้า ข้าพเจ้าไม่ทราบ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 14, 'แล้วท่านจึงกล่าวว่า “ทั้งสองนี้คือผู้ที่ได้รับการเจิม เป็นผู้ยืนอยู่ข้างองค์พระผู้เป็นเจ้าแห่งพิภพทั้งสิ้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 1, 'ข้าพเจ้าหันกลับและเงยหน้าขึ้นอีกก็แลเห็น ดูเถิด หนังสือม้วนหนึ่งเหาะอยู่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 2, 'ท่านจึงถามข้าพเจ้าว่า “เจ้าเห็นอะไร” ข้าพเจ้าตอบว่า “ข้าพเจ้าแลเห็นหนังสือม้วนหนึ่งเหาะอยู่ มันยาวยี่สิบศอก และกว้างสิบศอก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 3, 'แล้วท่านจึงบอกข้าพเจ้าว่า “นี่แหละเป็นคําสาปที่แผ่ออกไปทั่วพื้นแผ่นดินทั้งสิ้น ผู้ที่ทําการโจรกรรมทุกคนจะต้องถูกขจัดออก ตั้งแต่นี้ไปตามความในหนังสือม้วนนั้น และทุกคนที่สาบานจะต้องถูกขจัดออกตั้งแต่นี้ไปตามที่กําหนดไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 4, 'พระเยโฮวาห์จอมโยธาตรัสว่า เราส่งคําสาปนั้นออกไป และคํานั้นจะเข้าไปในเรือนของโจร และในเรือนของคนที่สาบานเท็จโดยออกนามของเรา และคํานี้จะค้างคืนอยู่ในเรือน ผลาญเรือนนั้นเสียทั้งไม้และศิลา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 5, 'ทูตสวรรค์ผู้ที่สนทนากับข้าพเจ้าได้ออกมาพูดกับข้าพเจ้าว่า “จงเงยหน้าขึ้นดูว่า สิ่งที่ออกไปนั้นคืออะไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 6, 'ข้าพเจ้าจึงว่า “นั่นคืออะไร” ท่านจึงตอบว่า “นี่คือเอฟาห์ที่ออกไป” และท่านจึงว่า “นี่คือสิ่งคล้ายคลึงในแผ่นดินทั้งสิ้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 7, 'และ ดูเถิด ตะกั่วหนึ่งตะลันต์ก็ถูกยกขึ้น และมีผู้หญิงคนหนึ่งนั่งอยู่ในเอฟาห์นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 8, 'และเขากล่าวว่า “นี่คือความชั่ว” และท่านก็ผลักนางนั้นเข้าไปในเอฟาห์ แล้วก็ผลักลูกน้ําหนักที่ทําด้วยตะกั่วนั้นปิดปากมันไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 9, 'แล้วข้าพเจ้าก็เงยหน้าขึ้นแลเห็น ดูเถิด มีผู้หญิงสองคนออกมา มีลมอยู่ในปีกของนาง นางมีปีกเหมือนปีกของนกกระสาดํา และนางก็ยกเอฟาห์ขึ้นระหว่างโลกและฟ้าสวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 10, 'แล้วข้าพเจ้าจึงพูดกับทูตสวรรค์ผู้ที่สนทนากับข้าพเจ้าว่า “นางเหล่านั้นจะนําเอฟาห์ไปที่ไหน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 11, 'ท่านตอบข้าพเจ้าว่า “ไปยังแผ่นดินชินาร์ไปสร้างเรือนไว้ให้เอฟาห์ เมื่อเตรียมอย่างนี้เสร็จแล้ว นางเหล่านั้นจะวางเอฟาห์ไว้บนฐานของมัน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 1, 'และข้าพเจ้าได้หันกลับ เงยหน้าขึ้นอีกแลเห็น ดูเถิด มีรถรบสี่คันออกมาระหว่างภูเขาสองลูก ภูเขาเหล่านั้นเป็นภูเขาทองเหลือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 2, 'รถรบคันแรกเทียมม้าแดง รถรบคันที่สองม้าดํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 3, 'รถรบคันที่สามม้าขาว รถรบคันที่สี่ม้าด่างสีเทา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 4, 'แล้วข้าพเจ้าจึงถามทูตสวรรค์ผู้ที่สนทนากับข้าพเจ้าว่า “เจ้านายเจ้าข้า เหล่านี้คืออะไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 5, 'และทูตสวรรค์นั้นตอบข้าพเจ้าว่า “เหล่านี้เป็นวิญญาณสี่ดวงแห่งฟ้าสวรรค์ ซึ่งออกมาหลังจากที่ได้ยืนอยู่ต่อพระพักตร์ขององค์พระผู้เป็นเจ้าแห่งพิภพทั้งสิ้นแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 6, 'ม้าดําตรงไปยังประเทศเหนือ ตัวขาวติดตามม้าดําไป และตัวสีด่างตรงไปยังประเทศใต้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 7, 'และตัวสีเทาออกไป พวกมันก็ร้อนใจที่จะออกไปและตรวจตราพื้นพิภพ และท่านกล่าวว่า “ไปซิ ไปตรวจตราพิภพ” ดังนั้นม้าเหล่านั้นจึงตรวจตราพิภพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 8, 'แล้วท่านจึงร้องบอกข้าพเจ้าว่า “ดูเถิด ม้าเหล่านี้ที่ไปยังประเทศเหนือนั้นได้กระทําให้จิตวิญญาณของเราสงบนิ่งในประเทศเหนือนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 9, 'และพระวจนะของพระเยโฮวาห์มายังข้าพเจ้าว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 10, '“จงนําเอาเฮลดัย โทบียาห์ และเยดายาห์ไปเสียจากบรรดาเชลย ผู้ซึ่งกลับจากบาบิโลน ในวันเดียวกันนั้นไปยังเรือนของโยสิยาห์ บุตรชายเศฟันยาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 11, 'จงเอาเงินและทองคําทําเป็นมงกุฎหลายมงกุฎ และสวมบนศีรษะของโยชูวาบุตรชายเยโฮซาดัก มหาปุโรหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 12, 'และกล่าวแก่เขาว่า ‘พระเยโฮวาห์จอมโยธาตรัสดังนี้ว่า ดูเถิด ชายผู้ที่มีชื่อว่าพระอังกูร เพราะท่านจะไพบูลย์ในสถานที่ของท่าน และจะสร้างพระวิหารของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 13, 'ท่านผู้นี้แหละจะเป็นผู้สร้างพระวิหารของพระเยโฮวาห์ และจะรับเกียรติศักดิ์ และจะประทับและปกครองอยู่บนราชบัลลังก์ของท่าน และท่านจะเป็นปุโรหิตอยู่บนราชบัลลังก์ของท่าน และการหารือกันอย่างสันติจะมีอยู่ระหว่างท่านทั้งสอง’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 14, 'และมงกุฎเหล่านั้นจะอยู่ในพระวิหารของพระเยโฮวาห์ เพื่อให้เป็นที่ระลึกถึงเฮเลม โทบียาห์ เยดายาห์ และเฮ็น บุตรชายของเศฟันยาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 15, 'บรรดาผู้ที่อยู่ห่างไกลจะมาช่วยสร้างพระวิหารของพระเยโฮวาห์ และท่านทั้งหลายจะทราบว่า พระเยโฮวาห์จอมโยธาทรงใช้ข้าพเจ้ามายังท่าน ถ้าท่านทั้งหลายจะเชื่อฟังพระสุรเสียงของพระเยโฮวาห์พระเจ้าของท่านอย่างเคร่งครัด สิ่งนี้จะเป็นไปดังกล่าวนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 1, 'ต่อมาในปีที่สี่ของรัชกาลกษัตริย์ดาริอัส พระวจนะของพระเยโฮวาห์มายังเศคาริยาห์ ณ วันที่สี่เดือนที่เก้า ซึ่งเป็นเดือนคิสลิว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 2, 'เมื่อพวกเขาได้ใช้ให้ชาเรเซอร์และเรเกมเมเลค พร้อมกับพรรคพวกของเขา ไปยังพระนิเวศของพระเจ้า ทูลขอจําเพาะพระพักตร์พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 3, 'และร้องขอต่อบรรดาปุโรหิตที่พระนิเวศแห่งพระเยโฮวาห์จอมโยธา และต่อผู้พยากรณ์ว่า “ควรที่ข้าพเจ้าจะไว้ทุกข์และปลีกตัวออกในเดือนที่ห้า อย่างที่ข้าพเจ้าได้กระทํามาแล้วเป็นหลายปีนั้นหรือไม่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 4, 'แล้วพระวจนะของพระเยโฮวาห์จอมโยธามายังข้าพเจ้าว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 5, '“จงกล่าวแก่ประชาชนทั้งสิ้นแห่งแผ่นดินและแก่บรรดาปุโรหิตว่า เมื่อเจ้าทั้งหลายอดอาหารและไว้ทุกข์ในเดือนที่ห้าและในเดือนที่เจ็ด ตั้งเจ็ดสิบปีนั้น เจ้าได้อดอาหารเพื่อเราคือเราเองหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 6, 'และเมื่อเจ้ารับประทานและเมื่อเจ้าดื่ม เจ้าก็รับประทานเพื่อตัวเจ้าเอง และดื่มเพื่อตัวเจ้าเองมิใช่หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 7, 'ในเมื่อเยรูซาเล็มมีคนอยู่และมั่งคั่ง มีหัวเมืองล้อมรอบ ภาคใต้และแดนที่ราบก็มีคนอยู่ เจ้าควรจะฟังพระวจนะซึ่งพระเยโฮวาห์ทรงประกาศโดยผู้พยากรณ์รุ่นก่อนๆ มิใช่หรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 8, 'และพระวจนะของพระเยโฮวาห์มาถึงเศคาริยาห์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 9, '“พระเยโฮวาห์จอมโยธาตรัสดังนี้ว่า จงพิพากษาตามความจริง ทุกคนจงแสดงความเมตตากรุณาและความสงสารต่อพี่น้องของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 10, 'อย่าบีบบังคับหญิงม่าย ลูกกําพร้าพ่อ คนต่างด้าวหรือคนยากจน และอย่าคิดอุบายชั่วในใจต่อพี่น้องของตน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 11, 'แต่เขาปฏิเสธไม่ยอมฟังและหันบ่าดื้อเข้าใส่ และอุดหูของเขาเสียเพื่อเขาจะไม่ได้ยิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 12, 'เออ เขาได้กระทําใจของเขาเหมือนก้อนหินแข็ง เกรงว่าเขาจะได้ยินพระราชบัญญัติและพระวจนะ ซึ่งพระเยโฮวาห์จอมโยธาได้ทรงส่งไปทางผู้พยากรณ์รุ่นก่อนโดยพระวิญญาณของพระองค์ เหตุฉะนั้นพระพิโรธอันยิ่งใหญ่จึงได้มาจากพระเยโฮวาห์จอมโยธา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 13, 'ดังนั้นต่อมาพระเยโฮวาห์จอมโยธาตรัสว่า “เมื่อเราร้องเรียก เขาไม่ฟังฉันใด เมื่อเขาร้องทูล เราก็ไม่ฟังฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 14, 'และเราก็ให้เขากระจัดกระจายไปด้วยลมหมุนท่ามกลางประชาชาติทั้งสิ้นซึ่งเขาไม่รู้จัก ดังนั้นแผ่นดินจึงรกร้างอยู่เบื้องหลังเขา ไม่มีใครผ่านไปหรือกลับเข้าไป เพราะเขาได้ปล่อยให้แผ่นดินที่น่าพึงพอใจนั้นรกร้างไปเสียแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 1, 'และพระวจนะของพระเยโฮวาห์จอมโยธามายังข้าพเจ้าอีกว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 2, '“พระเยโฮวาห์จอมโยธาตรัสดังนี้ว่า เราหวงแหนศิโยนด้วยความหวงแหนอันยิ่งใหญ่ และเราหวงแหนเธอด้วยความกริ้วมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 3, 'พระเยโฮวาห์ตรัสดังนี้ว่า เรากลับไปยังศิโยน และจะอยู่ท่ามกลางเยรูซาเล็ม และเขาจะเรียกเยรูซาเล็มว่าเมืองแห่งความจริง และเรียกภูเขาของพระเยโฮวาห์จอมโยธาว่าภูเขาบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 4, 'พระเยโฮวาห์จอมโยธาตรัสดังนี้ว่า ชายชราและหญิงชราจะอาศัยอยู่ตามถนนในกรุงเยรูซาเล็มอีก ต่างก็มีไม้เท้าอยู่ในมือเพราะอายุมากทีเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 5, 'และถนนทั้งหลายในเมืองนั้นก็จะเต็มไปด้วยเด็กผู้ชายและเด็กผู้หญิงวิ่งเล่นอยู่ทั่วไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 6, 'พระเยโฮวาห์จอมโยธาตรัสดังนี้ว่า ถ้าเรื่องนี้เป็นเรื่องประหลาดในสายตาของประชาชนที่เหลืออยู่ในสมัยนี้แล้ว พระเยโฮวาห์จอมโยธาตรัสว่า ก็น่าจะประหลาดในสายตาของเราด้วยมิใช่หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 7, 'พระเยโฮวาห์จอมโยธาตรัสดังนี้ว่า ดูเถิด เราจะช่วยประชาชนของเราให้รอดพ้นจากประเทศตะวันออกและจากประเทศตะวันตก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 8, 'และเราจะพาเขาทั้งหลายให้มาอาศัยอยู่ท่ามกลางเยรูซาเล็ม และเขาทั้งหลายจะเป็นประชาชนของเรา และเราจะเป็นพระเจ้าของเขาทั้งหลาย ด้วยความจริงและความชอบธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 9, 'พระเยโฮวาห์จอมโยธาตรัสว่า จงให้มือของเจ้าทั้งหลายแข็งแรง คือเจ้าทั้งหลายผู้ได้ยินถ้อยคําเหล่านี้ในกาลนี้ซึ่งมาจากปากผู้พยากรณ์ทั้งหลาย ซึ่งอยู่ในวันที่ได้วางรากฐานพระนิเวศของพระเยโฮวาห์จอมโยธา เพื่อว่าจะได้ก่อสร้างพระวิหารนั้นขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 10, 'เพราะว่าก่อนสมัยนั้นไม่มีค่าจ้างให้แก่คนหรือให้แก่สัตว์ ทั้งผู้ที่เข้าออกก็ไม่มีสันติภาพเพราะเหตุภัยพิบัตินั้น เพราะเราปล่อยให้คนทั้งหลายต่อสู้กับเพื่อนบ้านของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 11, 'พระเยโฮวาห์จอมโยธาตรัสว่า แต่บัดนี้เราจะไม่กระทําต่อประชาชนที่เหลืออยู่นี้อย่างกับสมัยก่อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 12, 'เพราะว่าเมล็ดพืชจะเกิดเจริญงอกงาม เถาองุ่นจะมีลูกและแผ่นดินจะให้ผล และท้องฟ้าจะให้น้ําค้าง และเราจะกระทําให้ประชาชนที่เหลืออยู่นี้ถือกรรมสิทธิ์สิ่งเหล่านี้ทั้งหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 13, 'โอ วงศ์วานยูดาห์และวงศ์วานอิสราเอลเอ๋ย เจ้าเคยเป็นที่สาปแช่งท่ามกลางประชาชาติทั้งหลายให้เขาแช่งฉันใด ต่อมาเราจะช่วยเจ้าให้รอดพ้นและเจ้าจะได้เป็นแหล่งพระพรฉันนั้น อย่ากลัวเลย แต่จงให้มือของเจ้าแข็งแรงเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 14, 'เพราะพระเยโฮวาห์จอมโยธาตรัสดังนี้ว่า เมื่อบรรพบุรุษของเจ้ายั่วเย้าให้เราโกรธนั้น เราก็ตั้งใจว่าจะลงโทษเจ้า เรามิได้หย่อนความตั้งใจลง พระเยโฮวาห์จอมโยธาตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 15, 'ดังนั้นในวันเหล่านี้เราตั้งใจอีกว่า เราจะกระทําดีต่อเยรูซาเล็มและต่อวงศ์วานยูดาห์ อย่ากลัวเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 16, 'ต่อไปนี้เป็นสิ่งที่เจ้าทั้งหลายพึงกระทํา จงต่างคนต่างพูดความจริงกับเพื่อนบ้าน จงให้การพิพากษาที่ประตูเมืองของเจ้าเป็นตามความจริงและกระทําเพื่อสันติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 17, 'อย่าคิดอุบายชั่วในใจต่อเพื่อนบ้าน อย่ารักคําสาบานเท็จ สิ่งทั้งปวงเหล่านี้เราเกลียดชัง” พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 18, 'และพระวจนะของพระเยโฮวาห์จอมโยธามายังข้าพเจ้าว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 19, '“พระเยโฮวาห์จอมโยธาตรัสดังนี้ว่า การอดอาหารในเดือนที่สี่ การอดอาหารในเดือนที่ห้าและการอดอาหารในเดือนที่เจ็ด และการอดอาหารในเดือนที่สิบ จะเป็นที่ให้ความบันเทิงและความร่าเริง และเป็นการเลี้ยงที่ให้ชื่นชมแก่วงศ์วานยูดาห์ เหตุฉะนั้นเจ้าจงรักความจริงและสันติภาพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 20, 'พระเยโฮวาห์จอมโยธาตรัสดังนี้ว่า ต่อมาชนชาติทั้งหลายจะมา คือประชาชนที่ยังอาศัยอยู่ในหัวเมืองอันมากมาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 21, 'ชาวเมืองหนึ่งจะไปหาชาวเมืองอีกเมืองหนึ่ง กล่าวว่า ‘ให้เราไปกันทันที ไปทูลขอจําเพาะพระพักตร์พระเยโฮวาห์ และแสวงหาพระเยโฮวาห์จอมโยธา ข้าพเจ้าก็จะไปด้วย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 22, 'เออ ชนชาติทั้งหลายเป็นอันมาก และบรรดาประชาชาติที่เข้มแข็งจะมาแสวงหาพระเยโฮวาห์จอมโยธาในเยรูซาเล็ม และทูลขอจําเพาะพระพักตร์พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 23, 'พระเยโฮวาห์จอมโยธาตรัสดังนี้ว่า ต่อมาในสมัยนั้นสิบคนจากประชาชาติทุกๆภาษาจะยึดชายเสื้อคลุมของยิวคนหนึ่งไว้แล้วกล่าวว่า ‘ขอให้เราไปกับท่านเถิด เพราะเราได้ยินว่าพระเจ้าทรงสถิตกับท่าน’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 1, 'ภาระแห่งพระวจนะของพระเยโฮวาห์ที่มีในหัดราก และเมืองดามัสกัสจะเป็นที่พักสงบสําหรับที่นั่น เมื่อตาของมนุษย์จะแสวงหาพระเยโฮวาห์ แม้กระทั่งอิสราเอลทุกตระกูลด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 2, 'เมืองฮามัทซึ่งมีเขตแดนติดกันก็รวมอยู่ด้วย ไทระกับไซดอน แม้จะเป็นเมืองฉลาดก็ตาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 3, 'ไทระได้สร้างป้อมปราการให้แก่ตนเอง และสะสมเงินไว้เป็นกองอย่างกองฝุ่น และทองคําเนื้อดีอย่างโคลนตามถนน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 4, 'ดูเถิด องค์พระผู้เป็นเจ้าจะทรงปลดเอาข้าวของของเมืองนี้ไปเสีย และเหวี่ยงอํานาจของเมืองนี้ลงไปในทะเล และเมืองนี้จะถูกไฟเผาผลาญเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 5, 'เมืองอัชเคโลนจะเห็นและกลัว เมืองกาซาจะเห็น และมีความเศร้าโศกอย่างยิ่ง เมืองเอโครนด้วยเหมือนกัน เพราะความหวังของเมืองนี้จะเป็นที่น่าละอาย กษัตริย์จะพินาศจากเมืองกาซา เมืองอัชเคโลนจะไม่มีคนอาศัยอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 6, 'ลูกนอกกฎหมายจะมาอยู่ในเมืองอัชโดด เราจะตัดความหยิ่งผยองของคนฟีลิสเตียออกเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 7, 'เราจะเอาเลือดของเขาออกไปจากปากของเขา และเอาสิ่งที่น่าสะอิดสะเอียนออกไปจากระหว่างซี่ฟันของเขาเสีย แต่คนที่เหลืออยู่ คือเขาเองจะอยู่เพื่อพระเจ้าของเรา จะเป็นเหมือนผู้ครอบครองคนหนึ่งในยูดาห์ และเอโครนจะเหมือนคนเยบุส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 8, 'และเราจะตั้งค่ายรอบนิเวศของเราเป็นกองยาม เพื่อจะมิให้ผู้ใดเดินทัพไปมาได้ จะไม่มีผู้บีบบังคับผ่านพวกเขาไปอีก เพราะบัดนี้เราเห็นกับตาของเราเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 9, 'โอ ธิดาแห่งศิโยนเอ๋ย จงร่าเริงอย่างยิ่งเถิด โอ บุตรสาวแห่งเยรูซาเล็มเอ๋ย จงโห่ร้อง ดูเถิด กษัตริย์ของเธอเสด็จมาหาเธอ ทรงความชอบธรรมและความรอด พระองค์ทรงถ่อมพระองค์ลงและทรงลา ทรงลูกลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 10, 'เราจะขจัดรถรบเสียจากเอฟราอิม และม้าเสียจากเยรูซาเล็ม ธนูสงครามจะถูกขจัดเสียด้วย และท่านจะบัญชาสันติให้มีแก่ประชาชาติทั้งหลาย อาณาจักรของท่านจะมีจากทะเลนี้ไปถึงทะเลโน้น และจากแม่น้ํานั้นไปถึงสุดปลายพิภพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 11, 'ส่วนเจ้าเล่า เพราะโลหิตแห่งพันธสัญญาของเราซึ่งมีต่อเจ้า เราจะปลดปล่อยเชลยในพวกเจ้าให้เป็นอิสระจากบ่อแห้งนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 12, 'นักโทษที่มีความหวังเอ๋ย จงกลับไปยังที่กําบังเข้มแข็งของเจ้า คือวันนี้เองเราประกาศว่า เราจะคืนแก่เจ้าสองเท่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 13, 'เพราะเราได้ดัดยูดาห์เหมือนโค้งคันธนู เราได้กระทําเอฟราอิมให้เป็นลูกธนู โอ ศิโยนเอ๋ย เราปลุกเร้าบุตรชายทั้งหลายของเจ้าให้ต่อสู้กับบุตรชายทั้งหลายของเจ้านะ โอ กรีกเอ๋ย และแกว่งเจ้าอย่างดาบของนักรบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 14, 'แล้วพระเยโฮวาห์จะทรงปรากฏเหนือเขาทั้งหลาย และลูกธนูของพระองค์จะออกไปเหมือนฟ้าแลบ องค์พระผู้เป็นเจ้าพระเจ้าจะทรงเป่าแตร และจะเสด็จไปในลมหมุนทิศใต้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 15, 'พระเยโฮวาห์จอมโยธาจะพิทักษ์รักษาเขาทั้งหลายไว้ และเขาทั้งหลายจะล้างผลาญและเหยียบลงด้วยนักเหวี่ยงสลิงก้อนหิน และจะดื่มและทําเสียงอึกทึกเพราะเหตุเหล้าองุ่น และจะอิ่มเหมือนชาม เปียกเหมือนมุมแท่นบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 16, 'ในวันนั้น พระเยโฮวาห์พระเจ้าของเขาจะทรงช่วยเขาให้รอด เพราะเขาทั้งหลายเป็นประชาชนของพระองค์ดังฝูงแกะ เขาทั้งหลายจะเป็นเหมือนกับเพชรพลอยที่อยู่ในมงกุฎ คือถูกยกขึ้นเหมือนธงในแผ่นดินของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 17, 'ด้วยว่าความดีของพระองค์มากมายเพียงใด และความงดงามของพระองค์ยิ่งใหญ่แค่ไหน เมล็ดข้าวจะกระทําให้คนหนุ่มรื่นเริง และน้ําองุ่นใหม่จะทําให้หญิงสาวชื่นบาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 1, 'จงขอฝนจากพระเยโฮวาห์ในฤดูฝนชุกปลายฤดู ดังนั้นพระเยโฮวาห์จะทรงปั้นเมฆพายุ จะทรงประทานห่าฝนแก่มนุษย์ และผักในทุ่งนาแก่ทุกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 2, 'เพราะว่ารูปเคารพพูดไม่ได้เรื่อง และพวกโหรก็เห็นสิ่งหลอกลวง และเล่าความฝันเท็จ และให้คําเล้าโลมที่เปล่าประโยชน์ เพราะฉะนั้นประชาชนจึงหลงไปอย่างฝูงสัตว์ เขาทุกข์ใจเพราะขาดเมษบาล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 3, '“เราโกรธเมษบาลอย่างรุนแรง และเราลงโทษบรรดาแพะผู้ เพราะพระเยโฮวาห์จอมโยธาเอาพระทัยใส่ฝูงสัตว์ของพระองค์คือวงศ์วานยูดาห์ และทรงกระทําเขาให้เป็นเหมือนม้าศึกฮึกเหิมในสงคราม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 4, 'ศิลามุมเอกออกมาจากเขา หมุดขึงเต็นท์ออกมาจากเขา คันธนูรบศึกออกมาจากเขา และผู้บีบบังคับทุกคนออกมาจากเขาด้วยกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 5, 'เขาจะเป็นอย่างชายฉกรรจ์ในสงคราม เหยียบย่ําศัตรูไปในโคลนตามถนน เขาจะต่อสู้เพราะพระเยโฮวาห์ทรงสถิตกับเขา เขาจะกระทําให้ผู้ที่อยู่บนหลังม้ายุ่งเหยิง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 6, 'เราจะหนุนกําลังวงศ์วานของยูดาห์ และเราจะช่วยวงศ์วานของโยเซฟให้รอด เราจะนําเขากลับมาอีกเพื่อให้เขาได้อาศัยอยู่เพราะเราสงสารเขา และเขาจะเป็นเหมือนว่าเรามิได้ทอดทิ้งเขา เพราะเราคือพระเยโฮวาห์พระเจ้าของเขา เราจะฟังเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 7, 'แล้วคนเอฟราอิมจะเป็นเหมือนชายฉกรรจ์ และจิตใจของเขาทั้งหลายจะเปรมปรีดิ์เหมือนได้ดื่มน้ําองุ่น เออ ลูกหลานของเขาจะได้เห็นและเปรมปรีดิ์ และจิตใจของเขาจะยินดีเหลือล้นในพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 8, 'เราจะผิวปากเรียกเขาและรวบรวมเขาเข้ามา เพราะเราได้ไถ่เขาไว้แล้ว และเขาจะมีมากมายเหมือนกาลก่อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 9, 'แม้เราจะหว่านเขาไปท่ามกลางชนชาติทั้งหลาย แต่เขาจะระลึกถึงเราในประเทศที่ห่างไกลนั้น เขาจะดํารงชีวิตอยู่กับลูกหลานของเขาและกลับมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 10, 'เราจะนําเขากลับจากแผ่นดินอียิปต์ และรวบรวมเขามาจากอัสซีเรีย และเราจะนําเขามายังแผ่นดินกิเลอาดและเลบานอนจนจะไม่มีที่ให้เขาอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 11, 'พระองค์จะเสด็จผ่านข้ามทะเลแห่งความระทม และจะทรงทุบคลื่นทะเล และที่ลึกทั้งสิ้นของแม่น้ําจะแห้งไป ความเห่อเหิมของอัสซีเรียจะตกต่ํา และคทาของอียิปต์จะพรากไปเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 12, 'เราจะกระทําให้เขาทั้งหลายเข้มแข็งในพระเยโฮวาห์ และเขาจะดําเนินในพระนามของพระองค์” พระเยโฮวาห์ตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 1, 'โอ เลบานอนเอ๋ย จงเปิดบรรดาประตูของเจ้า เพื่อไฟจะได้เผาผลาญไม้สนสีดาร์ของเจ้าเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 2, 'ต้นสนสามใบเอ๋ย จงร่ําไห้เถิด เพราะไม้สนสีดาร์ล้มเสียแล้ว เพราะบรรดาไม้ที่สง่างามพินาศลงไปแล้ว โอ ต้นโอ๊กเมืองบาชานเอ๋ย จงร่ําไห้เถิด เพราะป่าทึบถูกโค่นเสียแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 3, 'ฟังซิ เสียงร่ําไห้ของเมษบาล เพราะสง่าราศีของเขาทั้งหลายก็ถูกทําลายไปแล้ว ฟังซิ เสียงสิงโตหนุ่มคําราม เพราะว่าความภูมิใจแห่งแม่น้ําจอร์แดนก็ร้างเปล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 4, 'พระเยโฮวาห์พระเจ้าของข้าพเจ้าตรัสดังนี้ว่า “จงเลี้ยงฝูงแพะแกะที่ต้องถูกฆ่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 5, 'บรรดาผู้ที่ซื้อมันไปก็ฆ่ามันเสีย และไม่ต้องมีโทษ และบรรดาคนที่ขายมันกล่าวว่า ‘สาธุการแด่พระเยโฮวาห์ เพราะข้าพเจ้ามั่งมีแล้ว’ และเมษบาลของมันทั้งหลายไม่สงสารมันเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 6, 'พระเยโฮวาห์ตรัสว่า เพราะเราจะไม่สงสารชาวแผ่นดินนี้อีกต่อไป ดูเถิด เราก็จะกระทําให้เขาต่างคนตกเข้าไปในมือของเพื่อนบ้านของเขา และต่างก็ตกไปในหัตถ์ของกษัตริย์ของเขา และท่านจะบีบแผ่นดินให้แหลก และเราจะไม่ช่วยเหลือคนหนึ่งคนใดให้พ้นมือของท่านทั้งหลายเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 7, 'ดังนั้น ข้าพเจ้าจึงจะได้เลี้ยงดูฝูงแพะแกะที่ถูกฆ่า คือตัวเจ้าเอง โอ พวกที่น่าสงสารแห่งฝูงแกะเอ๋ย ข้าพเจ้าจึงเอาไม้เท้าสองอัน อันหนึ่งให้ชื่อว่า พระคุณ อีกอันหนึ่งข้าพเจ้าให้ชื่อว่า สหภาพ และข้าพเจ้าก็เลี้ยงดูฝูงแกะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 8, 'ในเดือนเดียวข้าพเจ้าตัดเมษบาลสามคนนั้นออกเสีย แต่จิตใจข้าพเจ้าเกลียดชังแกะเหล่านั้น และจิตใจแกะก็เกลียดชังข้าพเจ้าด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 9, 'ข้าพเจ้าจึงว่า “ข้าจะไม่เลี้ยงดูเจ้า อะไรจะต้องตายก็ให้ตายไป อะไรที่จะต้องถูกตัดออกก็ให้ถูกตัดออกไปเสีย และให้บรรดาที่เหลืออยู่นั้นกินเนื้อซึ่งกันและกัน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 10, 'ข้าพเจ้าก็เอาไม้เท้าที่ชื่อ พระคุณ นั้นมาหัก เพื่อล้มเลิกพันธสัญญาซึ่งข้าพเจ้าได้ทําไว้กับชนชาติทั้งหลายเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 11, 'จึงเป็นอันล้มเลิกในวันนั้น และพวกที่น่าสงสารแห่งฝูงแกะ ผู้ซึ่งคอยดูข้าพเจ้าอยู่ก็รู้ว่า นั่นเป็นพระวจนะของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 12, 'แล้วข้าพเจ้าจึงพูดกับเขาว่า “ถ้าท่านเห็นควรก็ขอค่าจ้างแก่เรา ถ้าไม่เห็นควรก็ไม่ต้อง” แล้วเขาก็ชั่งเงินสามสิบเหรียญออกให้แก่ข้าพเจ้าเป็นค่าจ้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 13, 'แล้วพระเยโฮวาห์ตรัสกับข้าพเจ้าว่า “จงโยนเงินนั้นให้แก่ช่างปั้นหม้อ” คือเงินก้อนงามที่เขาจ่ายให้ข้าพเจ้า ดังนั้นข้าพเจ้าจึงเอาเงินสามสิบเหรียญโยนให้แก่ช่างปั้นหม้อในพระนิเวศของพระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 14, 'แล้วข้าพเจ้าก็หักไม้เท้าอันที่สองที่ชื่อ สหภาพ นั้นเสีย ล้มเลิกภราดรภาพระหว่างยูดาห์และอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 15, 'แล้วพระเยโฮวาห์จึงตรัสกับข้าพเจ้าว่า “จงหยิบเครื่องใช้ของเมษบาลโง่เขลาขึ้นมาอีกครั้งหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 16, 'เพราะดูเถิด เราจะตั้งเมษบาลผู้หนึ่งในแผ่นดินนี้ ผู้ไม่แวะไปหาตัวที่ถูกตัดออกไป หรือแสวงหาตัวที่ยังหนุ่ม หรือรักษาตัวที่หักเสียแล้ว หรือเลี้ยงดูตัวที่เป็นปกติ แต่กินเนื้อของแกะอ้วนทุกตัว ฉีกกินจนกระทั่งถึงกีบของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 17, 'วิบัติแก่เมษบาลผู้ไร้ค่าของเรา ผู้ที่ทอดทิ้งฝูงแพะแกะเสีย ขอให้ดาบฟันแขนของเขาและฟันตาขวาของเขาเถิด ขอให้แขนของเขาลีบไปเสีย และให้ตาขวาของเขาบอดทีเดียว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 1, 'ภาระแห่งพระวจนะของพระเยโฮวาห์เกี่ยวด้วยเรื่องอิสราเอล พระเยโฮวาห์ผู้ทรงขึงท้องฟ้าออก และวางรากพิภพ และปั้นจิตวิญญาณให้มีอยู่ในมนุษย์ ตรัสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 2, '“ดูเถิด เราจะทํากรุงเยรูซาเล็มให้เป็นถ้วยแห่งการสั่นสะเทือนสําหรับบรรดาชนชาติทั้งหลายที่อยู่ล้อมรอบ เมื่อพวกเขาจะล้อมทั้งยูดาห์และกรุงเยรูซาเล็มไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 3, 'ในวันนั้น เราจะกระทําให้เยรูซาเล็มเป็นศิลาหนักแก่บรรดาชนชาติทั้งหลาย ผู้ที่พยายามยกหินนั้นขึ้นจะกระทําให้ตัวเองถูกหั่นเป็นชิ้นๆ ถึงแม้ว่าประชาชาติทั้งสิ้นในพิภพจะสมทบกันสู้เยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 4, 'พระเยโฮวาห์ตรัสว่า ในวันนั้น เราจะให้ม้าทุกตัววุ่นวาย และกระทําให้คนขี่บ้าคลั่ง แต่เราจะลืมตาดูวงศ์วานยูดาห์ และเราจะกระทําให้ม้าทุกตัวของชนชาติทั้งหลายตาบอดไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 5, 'แล้วหัวหน้าคนยูดาห์จะรําพึงในใจว่า ‘ชาวเยรูซาเล็มจะเป็นกําลังของเรา เนื่องจากพระเยโฮวาห์จอมโยธาพระเจ้าของเขา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 6, 'ในวันนั้นเราจะกระทําให้หัวหน้าคนยูดาห์ทั้งหลายเหมือนหม้อร้อนแดงอยู่ท่ามกลางกองฟืน เหมือนคบเพลิงสว่างอยู่ท่ามกลางฟ่อนข้าว และเขาจะเผาผลาญบรรดาชนชาติทั้งหลายที่อยู่ล้อมรอบไปทางขวาและไปทางซ้ายเสีย ฝ่ายเยรูซาเล็มจะมีคนอาศัยอยู่ในที่เดิมนั้นเอง คือเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 7, 'และพระเยโฮวาห์จะประทานชัยชนะแก่เต็นท์ของยูดาห์ก่อน เพื่อว่าสง่าราศีแห่งราชวงศ์ดาวิด และสง่าราศีแห่งชาวเยรูซาเล็มจะไม่ได้เป็นที่ยกย่องเหนือกว่าของยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 8, 'ในวันนั้นพระเยโฮวาห์จะทรงป้องกันชาวเยรูซาเล็มไว้ เพื่อว่าคนที่อ่อนแอท่ามกลางเขาในวันนั้นจะเป็นเหมือนดาวิด และราชวงศ์ของดาวิดจะเป็นเหมือนพระเจ้า เหมือนทูตสวรรค์ของพระเยโฮวาห์นําหน้าเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 9, 'ต่อมาในวันนั้น เราจะแสวงหาที่จะทําลายประชาชาติทั้งสิ้นซึ่งเข้ามาต่อสู้เยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 10, 'และเราจะเทวิญญาณแห่งพระคุณและการวิงวอนบนราชวงศ์ดาวิดและชาวเยรูซาเล็ม เขาทั้งหลายจะมองดูเราผู้ซึ่งเขาเองได้แทง เขาจึงจะไว้ทุกข์เพื่อท่านเหมือนคนไว้ทุกข์เพื่อบุตรชายคนเดียวของตน และจะร้องไห้อย่างขมขื่นเพื่อท่าน เหมือนอย่างคนร้องไห้อย่างขมขื่นเพื่อบุตรหัวปีของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 11, 'ในวันนั้น การไว้ทุกข์ในเยรูซาเล็มจะใหญ่โตอย่างการไว้ทุกข์เพื่อฮาดัดริมโมน ณ ที่ราบเมกิดโด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 12, 'แผ่นดินจะไว้ทุกข์ ตามครอบครัวแต่ละครอบครัว ครอบครัวราชวงศ์ดาวิดต่างหากและบรรดาภรรยาของท่านต่างหาก ครอบครัวของวงศ์วานนาธันต่างหาก และบรรดาภรรยาของเขาต่างหาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 13, 'ครอบครัวของวงศ์วานเลวีต่างหาก และภรรยาของเขาต่างหาก ครอบครัวชิเมอีต่างหาก และภรรยาของเขาต่างหาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 14, 'และครอบครัวที่เหลืออยู่ทั้งสิ้น แต่ละครอบครัวต่างหาก และภรรยาของเขาต่างหาก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 1, '“ในวันนั้น จะมีน้ําพุพลุ่งขึ้นสําหรับราชวงศ์ของดาวิดและชาวเยรูซาเล็ม เพื่อจะชําระเขาให้พ้นจากบาปและความไม่สะอาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 2, 'พระเยโฮวาห์จอมโยธาตรัสว่า ต่อมาในวันนั้น เราจะขจัดชื่อของรูปเคารพเสียจากแผ่นดิน เพื่อว่าเขาจะระลึกถึงอีกไม่ได้เลย และเราจะไล่ผู้พยากรณ์และวิญญาณที่ไม่สะอาดไปเสียจากแผ่นดินด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 3, 'ต่อมาเมื่อมีผู้ใดมาพยากรณ์อีก บิดามารดาผู้ให้เขาบังเกิดมานั้นจะพูดกับเขาว่า ‘เจ้าอย่ามีชีวิตอยู่เลย เพราะเจ้าพูดมุสาในพระนามของพระเยโฮวาห์’ เมื่อเขาพยากรณ์ บิดามารดาผู้ให้เขาเกิดมาจะแทงเขาให้ทะลุ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 4, 'ต่อมาในวันนั้น ผู้พยากรณ์ทุกคนจะมีความละอายเพราะนิมิตของเขาเมื่อพยากรณ์ เขาจะไม่สวมผ้ามีขนเพื่อล่อลวงอีกต่อไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 5, 'แต่เขาจะกล่าวว่า ‘ข้าพเจ้าไม่ใช่ผู้พยากรณ์ ข้าพเจ้าเป็นชาวนา เพราะว่ามีคนสอนข้าพเจ้าให้เลี้ยงสัตว์ตั้งแต่ข้าพเจ้ายังหนุ่มๆ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 6, 'และถ้าผู้ใดจะถามเขาว่า ‘ทําไมท่านมีแผลในมือทั้งสอง’ เขาจะตอบว่า ‘ข้าพเจ้าได้แผลนั้นในเรือนของพวกเพื่อนของข้าพเจ้า’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 7, 'พระเยโฮวาห์จอมโยธาตรัสว่า “โอ ดาบเอ๋ย จงตื่นขึ้นต่อสู้เมษบาลของเรา จงต่อสู้ผู้ที่สนิทกับเรา จงตีเมษบาล และฝูงแกะนั้นจะกระจัดกระจายไป เราจะกลับมือของเราต่อสู้กับตัวเล็กตัวน้อย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 8, 'พระเยโฮวาห์ตรัสว่า ต่อมาทั่วทั้งแผ่นดินจะต้องขจัดเสียให้พินาศสองในสาม และเหลือไว้หนึ่งในสาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 9, 'เราจะเอาหนึ่งในสามนี้ใส่ในไฟและถลุงเขาเหมือนถลุงเงิน และลองดูเขาเหมือนทดลองทองคํา เขาจะร้องทูลออกนามของเราและเราจะฟังเขา เราจะกล่าวว่า ‘เขาทั้งหลายเป็นชนชาติของเรา’ และเขาจะกล่าวว่า ‘พระเยโฮวาห์คือพระเจ้าของข้าพเจ้า’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 1, 'ดูเถิด วันแห่งพระเยโฮวาห์มาใกล้แล้ว เมื่อทรัพย์สินที่เขาริบไปจากเจ้านั้น เขาจะแบ่งกันท่ามกลางเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 2, 'เพราะเราจะรวบรวมประชาชาติทั้งสิ้นให้ทําศึกกับเยรูซาเล็ม เมืองนั้นจะถูกยึด บ้านเรือนจะถูกปล้นสะดมและผู้หญิงจะถูกข่มขืน พลเมืองครึ่งหนึ่งจะตกไปเป็นเชลย ประชาชนส่วนที่เหลืออยู่จะไม่ถูกตัดออกเสียจากเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 3, 'แล้วพระเยโฮวาห์จะเสด็จออกไปต่อสู้กับประชาชาติเหล่านั้น เหมือนเมื่อพระองค์ทรงต่อสู้ในวันสงคราม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 4, 'ในวันนั้นพระบาทของพระองค์จะยืนอยู่ที่ภูเขามะกอกเทศ ซึ่งอยู่หน้าเมืองเยรูซาเล็มด้านตะวันออก และภูเขามะกอกเทศนั้นจะแยกออกตรงกลางจากทิศตะวันออกไปทิศตะวันตก โดยมีหุบเขากว้างมากคั่นอยู่ ภูเขาครึ่งหนึ่งจึงจะถอยไปทางเหนือ และอีกครึ่งหนึ่งจะถอยไปทางใต้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 5, 'และท่านทั้งหลายจะหนีไปยังหุบเขาแห่งบรรดาภูเขา เพราะว่าหุบเขาแห่งบรรดาภูเขาจะมาจดอาซาลและท่านทั้งหลายจะต้องหนีไป อย่างที่หนีจากแผ่นดินไหวสมัยอุสซียาห์กษัตริย์ประเทศยูดาห์ แล้วพระเยโฮวาห์พระเจ้าของข้าพเจ้าจะเสด็จมา และพวกวิสุทธิชนทั้งสิ้นจะมากับพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 6, 'ต่อมาในวันนั้นแสงสว่างจะไม่แจ่มใสหรือจะไม่มืดมัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 7, 'แต่จะเป็นวันหนึ่งที่พระเยโฮวาห์ทรงทราบแล้ว ไม่ใช่วันหรือคืน แต่ต่อมาเวลาเย็นจะมีแสงสว่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 8, 'ในวันนั้นน้ําแห่งชีวิตจะไหลออกจากเยรูซาเล็ม ครึ่งหนึ่งจะไหลไปสู่ทะเลด้านตะวันออก และครึ่งหนึ่งจะไหลไปสู่ทะเลด้านตะวันตก ในฤดูร้อนก็จะไหลเรื่อยไปดังในฤดูหนาว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 9, 'และพระเยโฮวาห์จะทรงเป็นกษัตริย์เหนือพิภพทั้งสิ้น ในวันนั้นพระเยโฮวาห์จะทรงเป็นเอก และพระนามของพระองค์ก็เป็นเอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 10, 'แผ่นดินทั้งสิ้นจะกลายเป็นที่ราบจากเกบาถึงริมโมนใต้เยรูซาเล็ม แต่เยรูซาเล็มจะดํารงสูงเด่นอยู่ในที่ตั้งของเมืองนั้น จากประตูเบนยามินถึงสถานที่ที่เป็นประตูเก่า ถึงประตูมุมและจากหอคอยฮานันเอล ถึงบ่อย่ําองุ่นของกษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 11, 'และจะมีผู้คนอาศัยอยู่ และจะไม่มีการทําลายทั้งสิ้นอีกแล้ว แต่เยรูซาเล็มจะอาศัยอยู่ได้อย่างปลอดภัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 12, 'ต่อไปนี้เป็นภัยพิบัติซึ่งพระเยโฮวาห์จะทรงใช้โจมตีบรรดาชนชาติทั้งหลายที่ทําสงครามกับเยรูซาเล็ม คือเนื้อของเขาจะเน่าไปเมื่อเขายังยืนอยู่ได้ ตาของเขาจะเน่าคาเบ้าตา และลิ้นของเขาจะเน่าคาปาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 13, 'ต่อมาในวันนั้นการสับสนอลหม่านอย่างใหญ่โตจากพระเยโฮวาห์จะอยู่ท่ามกลางเขาทั้งหลาย เพราะฉะนั้นคนหนึ่งจะจับกุมเพื่อนบ้านของตน และเขาจะยกมือขึ้นต่อสู้กันและกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 14, 'แม้ว่ายูดาห์ก็จะต่อสู้กันที่เยรูซาเล็ม ทรัพย์สมบัติของประชาชาติทั้งสิ้นที่อยู่ล้อมรอบจะถูกเก็บ มีทองคํา เงิน และเสื้อผ้ามากมาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 15, 'และภัยพิบัติอย่างหนึ่งที่เหมือนภัยพิบัติอย่างนี้จะบังเกิดแก่ม้า ล่อ อูฐ ลา และไม่ว่าสัตว์ชนิดใดซึ่งมีอยู่ในเต็นท์เหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 16, 'และอยู่มาบรรดาคนที่เหลืออยู่ในประชาชาติทั้งปวงซึ่งยกขึ้นมาสู้รบกับเยรูซาเล็ม จะขึ้นไปนมัสการกษัตริย์ปีแล้วปีเล่า คือพระเยโฮวาห์จอมโยธา และจะถือเทศกาลอยู่เพิง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 17, 'ถ้าครอบครัวใดในพื้นพิภพไม่ขึ้นไปยังเยรูซาเล็มเพื่อนมัสการกษัตริย์ คือพระเยโฮวาห์จอมโยธา ฝนก็จะไม่ตกเหนือเขาเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 18, 'และถ้าครอบครัวแห่งอียิปต์ ซึ่งขาดฝนแล้ว ไม่ขึ้นไปปรากฏตัวที่นั่น ก็จะบังเกิดภัยพิบัติด้วย ซึ่งพระเยโฮวาห์ทรงใช้โจมตีประชาชาติอื่นๆซึ่งไม่ขึ้นไปถือเทศกาลอยู่เพิง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 19, 'ที่กล่าวนี้จะเป็นการลงทัณฑ์อียิปต์และเป็นการลงทัณฑ์ประชาชาติทั้งสิ้น ซึ่งไม่ขึ้นไปถือเทศกาลอยู่เพิง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 20, 'และในวันนั้นลูกพรวนที่ผูกม้าจะมีคําจารึกว่า “บริสุทธิ์แด่พระเยโฮวาห์” และหม้อซึ่งอยู่ในพระนิเวศของพระเยโฮวาห์จะเป็นเหมือนชามซึ่งอยู่หน้าแท่นบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 21, 'เออ และหม้อทุกลูกในเยรูซาเล็มและยูดาห์จะเป็นของบริสุทธิ์แด่พระเยโฮวาห์จอมโยธา เพื่อว่าทุกคนที่มาถวายสัตวบูชาจะเอาหม้อไปบ้าง และจะต้มเนื้อในหม้อเหล่านั้น ในวันนั้นจะไม่มีคนคานาอันในพระนิเวศของพระเยโฮวาห์จอมโยธาอีกต่อไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 1, 'ภาระแห่งพระวจนะของพระเยโฮวาห์ที่มีต่ออิสราเอลโดยมาลาคี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 2, 'พระเยโฮวาห์ตรัสว่า “เราได้รักเจ้าทั้งหลาย” แต่ท่านทั้งหลายพูดว่า “พระองค์ได้ทรงรักข้าพระองค์สถานใด” พระเยโฮวาห์ตรัสว่า “เอซาวเป็นพี่ชายของยาโคบมิใช่หรือ เราก็ยังรักยาโคบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 3, 'แต่เราได้เกลียดเอซาว เราได้กระทําให้เทือกเขาและมรดกของเขาร้างเปล่าสําหรับมังกรแห่งถิ่นทุรกันดาร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 4, 'เมื่อเอโดมกล่าวว่า “เราถูกบั่นทอนเสียแล้ว แต่เราจะกลับมาสร้างที่ปรักหักพังขึ้นใหม่” พระเยโฮวาห์จอมโยธาตรัสดังนี้ว่า “เขาทั้งหลายจะสร้างขึ้น แต่เราจะรื้อลงเสีย และผู้คนจะเรียกเขาเหล่านี้ว่า ‘เป็นเขตแดนแห่งความชั่วร้าย’ และ ‘เป็นชนชาติที่พระเยโฮวาห์ทรงกริ้วอยู่เป็นนิตย์’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 5, 'ตาของเจ้าเองจะเห็นสิ่งนี้และเจ้าจะกล่าวว่า “พระเยโฮวาห์นี้จะใหญ่ยิ่งนักแม้กระทั่งนอกเขตแดนของอิสราเอล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 6, '“บุตรชายก็ย่อมให้เกียรติแก่บิดาของเขา คนใช้ก็ย่อมให้เกียรตินายของเขา แล้วถ้าเราเป็นพระบิดา เกียรติของเราอยู่ที่ไหน และถ้าเราเป็นนาย ความยําเกรงเรามีอยู่ที่ไหน นี่แหละพระเยโฮวาห์จอมโยธาตรัสแก่ท่านนะ โอ บรรดาปุโรหิต ผู้ดูหมิ่นนามของเรา ท่านก็ว่า ‘ข้าพระองค์ทั้งหลายดูหมิ่นพระนามของพระองค์สถานใด’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 7, 'ก็โดยนําอาหารมลทินมาถวายบนแท่นของเราอย่างไรล่ะ แล้วท่านว่า ‘ข้าพระองค์ทั้งหลายกระทําให้พระองค์เป็นมลทินสถานใด’ ก็โดยคิดว่า ‘โต๊ะของพระเยโฮวาห์นั้นเป็นที่ดูหมิ่น’ อย่างไรล่ะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 8, 'เมื่อเจ้านําสัตว์ตาบอดมาเป็นสัตวบูชา กระทําเช่นนั้นไม่ชั่วหรือ และเมื่อเจ้าถวายสัตว์ที่พิการหรือป่วย กระทําเช่นนั้นไม่ชั่วหรือ พระเยโฮวาห์จอมโยธาตรัสว่า จงนําของอย่างนั้นไปกํานัลเจ้าเมืองของเจ้าดู เขาจะพอใจเจ้าหรือ จะแสดงความชอบพอต่อเจ้าไหม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 9, 'ลองอ้อนวอนขอความชอบต่อพระเจ้า เพื่อพระองค์จะทรงพระกรุณาต่อพวกเราดูซี ด้วยของถวายดังกล่าวมานี้จากมือของเจ้า พระองค์จะทรงชอบพอเจ้าสักคนหนึ่งหรือ พระเยโฮวาห์จอมโยธาตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 10, 'อยากให้มีสักคนหนึ่งในพวกเจ้าซึ่งจะปิดประตูเสีย เพื่อว่าเจ้าจะไม่ก่อไฟบนแท่นบูชาของเราเสียเปล่า พระเยโฮวาห์จอมโยธาตรัสว่า เราไม่พอใจเจ้า และเราจะไม่รับเครื่องบูชาจากมือของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 11, 'พระเยโฮวาห์จอมโยธาตรัสว่า ตั้งแต่ที่ดวงอาทิตย์ขึ้นถึงที่ดวงอาทิตย์ตกนามของเราจะใหญ่ยิ่งท่ามกลางประชาชาติทั้งหลาย และเขาถวายเครื่องหอมและของถวายที่บริสุทธิ์แด่นามของเราทุกที่ทุกแห่ง เพราะว่านามของเรานั้นจะใหญ่ยิ่งท่ามกลางประชาชาติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 12, 'แต่เมื่อเจ้ากล่าวว่า ‘โต๊ะของพระเยโฮวาห์เป็นมลทิน’ และว่า ‘ผลของโต๊ะนั้นคืออาหารที่ถวายนั้นน่าดูถูก’ เจ้าก็ได้กระทําให้นามนั้นเป็นมลทินไปแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 13, 'พระเยโฮวาห์จอมโยธาตรัสว่า เจ้ากล่าวว่า ‘ดูเถิด อย่างนี้น่าอ่อนระอาใจจริง’ แล้วเจ้าก็ทําฮึดฮัดกับเรา เจ้านําเอาสิ่งที่ได้แย่งมา หรือสิ่งที่พิการหรือป่วย ของเหล่านี้แหละเจ้านํามาเป็นของบูชา พระเยโฮวาห์ตรัสว่า เราจะรับของนั้นจากมือของเจ้าได้หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 14, 'พระเยโฮวาห์จอมโยธาตรัสว่า คนใดที่มีสัตว์ตัวผู้อยู่ในฝูง และได้สาบานไว้ และยังเอาสัตว์พิการไปถวายแด่องค์พระผู้เป็นเจ้า คําสาปแช่งจงตกอยู่กับคนโกงนั้นเถิด เพราะเราเป็นพระมหากษัตริย์ และนามของเราเป็นที่กลัวเกรงท่ามกลางประชาชาติทั้งหลาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 1, '“โอ ปุโรหิตทั้งหลาย บัดนี้คําบัญชานี้มีอยู่เพื่อเจ้าทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 2, 'พระเยโฮวาห์จอมโยธาตรัสว่า ถ้าเจ้าไม่ฟัง และถ้าเจ้าไม่จําใส่ไว้ในใจที่จะถวายสง่าราศีแด่นามของเรา เราจะส่งคําแช่งมาเหนือเจ้า และเราจะสาปแช่งผลพระพรซึ่งมาถึงเจ้า เราได้สาปแช่งคําอวยพรของเจ้าแล้วนะ เพราะเจ้ามิได้จําใส่ใจไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 3, 'ดูเถิด เราจะกระทําให้เชื้อสายของเจ้าเสื่อมไป และจะละเลงมูลสัตว์ใส่หน้าเจ้า คือมูลสัตว์ของเทศกาลตามกําหนดของเจ้า และเราจะไล่เจ้าออกไปเสียจากหน้าเราอย่างนั้นแหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 4, 'พระเยโฮวาห์จอมโยธาตรัสว่า เจ้าจึงจะทราบว่า เราส่งคําบัญชานี้มาให้เจ้า เพื่อว่าพันธสัญญาของเราซึ่งทําไว้กับเลวีจะคงอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 5, 'พันธสัญญาของเราซึ่งมีไว้กับเขานั้นเป็นพันธสัญญาเรื่องชีวิตและสันติภาพ เราได้ให้สิ่งเหล่านี้แก่เขาเพื่อเขาจะได้ยําเกรง และเขาได้ยําเกรงเรา และเกรงขามนามของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 6, 'ในปากของเขามีราชบัญญัติแห่งความจริง จะหาความชั่วช้าที่ริมฝีปากของเขาไม่ได้เลย เขาดําเนินกับเราด้วยสันติและความเที่ยงตรง และเขาได้หันหลายคนให้พ้นจากความชั่วช้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 7, 'เพราะว่าริมฝีปากของปุโรหิตควรเป็นยามความรู้ และมนุษย์ควรแสวงหาราชบัญญัติจากปากของเขา เพราะว่าเขาเป็นทูตของพระเยโฮวาห์จอมโยธา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 8, 'แต่เจ้าเองได้หันไปเสียจากทางนั้น เจ้าเป็นเหตุให้หลายคนสะดุดเพราะเหตุราชบัญญัติ พระเยโฮวาห์จอมโยธาตรัสว่า เจ้าได้กระทําให้พันธสัญญาของเลวีเสื่อมไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 9, 'ดังนั้นเราจึงกระทําให้เจ้าเป็นที่ดูหมิ่นและเหยียดหยามต่อหน้าประชาชนทั้งปวง ให้สมกับที่เจ้ามิได้รักษาบรรดาวิถีทางของเรา แต่ได้แสดงอคติในการสอนราชบัญญัติ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 10, 'เราทุกคนมิได้มีบิดาคนเดียวหรอกหรือ พระเจ้าองค์เดียวได้ทรงสร้างเรามิใช่หรือ แล้วทําไมเราทุกคนจึงปฏิบัติต่อพี่น้องของตนด้วยการทรยศ โดยการลบหลู่พันธสัญญาของบรรพบุรุษของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 11, 'ยูดาห์ก็ประพฤติอย่างทรยศ การอันน่าสะอิดสะเอียนเขาก็ทํากันในอิสราเอลและในเยรูซาเล็ม เพราะว่ายูดาห์ได้ลบหลู่ความบริสุทธิ์ของพระเยโฮวาห์ซึ่งพระองค์ทรงรัก และได้ไปแต่งงานกับบุตรสาวของพระต่างด้าว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 12, 'พระเยโฮวาห์จะทรงขจัดชายคนใดๆที่กระทําเช่นนี้ ทั้งผู้สอนและนักศึกษา เสียจากเต็นท์ของยาโคบ ถึงแม้ว่าเขาจะนําเครื่องบูชาถวายแด่พระเยโฮวาห์จอมโยธาก็ตามเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 13, 'และเจ้าได้กระทําอย่างนี้อีกด้วย คือเจ้าเอาน้ําตารดทั่วแท่นบูชาของพระเยโฮวาห์ ด้วยเหตุเจ้าได้ร้องไห้คร่ําครวญ เพราะพระองค์ไม่สนพระทัยหรือรับเครื่องบูชาด้วยชอบพระทัยจากมือของเจ้าอีกแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 14, 'เจ้าถามว่า “เหตุใดพระองค์จึงไม่รับ” เพราะว่าพระเยโฮวาห์ทรงเป็นพยานระหว่างเจ้ากับภรรยาคนที่เจ้าได้เมื่อหนุ่มนั้น แม้ว่านางเป็นคู่เคียงของเจ้าและเป็นภรรยาของเจ้าตามพันธสัญญา เจ้าก็ทรยศต่อนาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 15, 'พระองค์ทรงทําให้เขาทั้งสองเป็นอันเดียวกันมิใช่หรือ แต่เขายังมีลมปราณแห่งชีวิตอยู่ และทําไมเป็นอันเดียวกัน เพราะพระองค์ทรงประสงค์เชื้อสายที่ตามทางของพระเจ้า ดังนั้นจงเอาใจใส่ต่อจิตวิญญาณของเจ้าให้ดี อย่าให้ผู้ใดทรยศต่อภรรยาคนที่ได้เมื่อหนุ่มนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 16, 'เพราะพระเยโฮวาห์พระเจ้าของอิสราเอลตรัสว่า “เราเกลียดชังการหย่าร้าง เพราะคนหนึ่งปกปิดความทารุณด้วยเสื้อผ้าของตน พระเยโฮวาห์จอมโยธาตรัสดังนี้แหละ เพราะฉะนั้นจงเอาใจใส่ต่อจิตวิญญาณของเจ้าให้ดี อย่าเป็นคนทรยศ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 17, 'เจ้าได้กระทําให้พระเยโฮวาห์อ่อนระอาพระทัยด้วยคําพูดของเจ้า เจ้ายังจะกล่าวว่า “เราทั้งหลายกระทําให้พระองค์อ่อนพระทัยสถานใดหรือ” ก็เมื่อเจ้ากล่าวว่า “ทุกคนที่กระทําความชั่วก็เป็นคนดีในสายพระเนตรของพระเยโฮวาห์ และพระองค์ทรงปีติยินดีในคนเหล่านั้น” หรือโดยถามว่า “พระเจ้าแห่งการพิพากษาอยู่ที่ไหน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 1, 'พระเยโฮวาห์จอมโยธาตรัสว่า “ดูเถิด เราจะส่งทูตของเราไป และผู้นั้นจะตระเตรียมหนทางไว้ข้างหน้าเรา และองค์พระผู้เป็นเจ้า ผู้ซึ่งเจ้าแสวงหานั้น จะเสด็จมายังพระวิหารของพระองค์อย่างกระทันหัน ทูตแห่งพันธสัญญา ผู้ซึ่งเจ้าพอใจนั้น ดูเถิด ท่านจะเสด็จมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 2, 'แต่ใครจะทนอยู่ได้ในวันที่ท่านมา และใครจะยืนมั่นอยู่ได้เมื่อท่านปรากฏตัว เพราะว่าท่านเป็นประดุจไฟถลุงแร่ และประดุจสบู่ของช่างซักฟอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 3, 'ท่านจะนั่งลงอย่างช่างหลอมและช่างถลุงเงิน และท่านจะชําระลูกหลานของเลวีให้บริสุทธิ์ และถลุงเขาอย่างถลุงทองคําและถลุงเงิน เพื่อเขาจะได้นําเครื่องบูชาอันชอบธรรมถวายแด่พระเยโฮวาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 4, 'แล้วเครื่องบูชาของยูดาห์และเยรูซาเล็มจะเป็นที่พอพระทัยพระเยโฮวาห์ ดังสมัยก่อน และดังในปีที่ล่วงแล้วมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 5, 'พระเยโฮวาห์จอมโยธาตรัสว่า แล้วเราจะมาใกล้เจ้าเพื่อการพิพากษา เราจะเป็นพยานที่รวดเร็วที่กล่าวโทษนักวิทยาคม พวกผิดประเวณี ผู้ที่สาบานเท็จ ผู้ที่บีบบังคับลูกจ้างในเรื่องค่าจ้าง และหญิงม่ายและลูกกําพร้าพ่อ ผู้ที่ผลักไสหันเหคนต่างด้าวจากสิทธิของเขา และผู้ที่ไม่ยําเกรงเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 6, 'เพราะว่า เราคือพระเยโฮวาห์ไม่มีผันแปร บุตรชายยาโคบเอ๋ย เจ้าทั้งหลายจึงไม่ถูกเผาผลาญหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 7, 'เจ้าได้หันเหไปเสียจากกฎของเราและมิได้รักษาไว้ตั้งแต่ครั้งสมัยบรรพบุรุษของเจ้า พระเยโฮวาห์จอมโยธาตรัสว่า เจ้าจงกลับมาหาเรา และเราจะกลับมาหาเจ้าทั้งหลาย แต่เจ้ากล่าวว่า ‘เราทั้งหลายจะกลับมาสถานใด’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 8, 'คนจะปล้นพระเจ้าหรือ แต่เจ้าทั้งหลายได้ปล้นเรา แต่เจ้ากล่าวว่า ‘เราทั้งหลายปล้นพระเจ้าอย่างไร’ ก็ปล้นในเรื่องสิบชักหนึ่งและเครื่องบูชานั่นซี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 9, 'เจ้าทั้งหลายต้องถูกสาปแช่งด้วยคําสาปแช่ง เพราะเจ้าทั้งหลายทั้งชาติปล้นเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 10, 'พระเยโฮวาห์จอมโยธาตรัสว่า จงนําสิบชักหนึ่งเต็มขนาดมาไว้ในคลัง เพื่อว่าจะมีอาหารในนิเวศของเรา จงลองดูเราในเรื่องนี้ว่า เราจะเปิดหน้าต่างในฟ้าสวรรค์ให้เจ้า และเทพรอย่างล้นไหลมาให้เจ้าหรือไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 11, 'เราจะขนาบตัวที่ทําลายให้แก่เจ้า เพื่อว่ามันจะไม่ทําลายผลแห่งพื้นดินของเจ้า และผลองุ่นในไร่นาของเจ้าจะไม่ร่วง พระเยโฮวาห์จอมโยธาตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 12, 'พระเยโฮวาห์จอมโยธาตรัสว่า แล้วประชาชาติทั้งสิ้นจะเรียกเจ้าว่า ผู้ที่ได้รับพระพร ด้วยว่าเจ้าจะเป็นแผ่นดินที่น่าพึงใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 13, 'พระเยโฮวาห์ตรัสว่า ถ้อยคําของเจ้านั้นใส่ร้ายเรา เจ้ายังกล่าวว่า ‘เราทั้งหลายได้กล่าวใส่ร้ายพระองค์สถานใด’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 14, 'เจ้าได้กล่าวว่า ‘ที่จะปรนนิบัติพระเจ้าก็เปล่าประโยชน์ ที่เราจะรักษากฎของพระองค์ หรือดําเนินอย่างคนไว้ทุกข์ต่อพระพักตร์พระเยโฮวาห์จอมโยธานั้นจะได้ผลประโยชน์อันใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 15, 'บัดนี้เราถือว่าคนอวดดีเป็นคนได้รับพร เออ คนที่ประกอบความชั่ว ใช่ว่าจะมั่งคั่งเท่านั้น แต่เมื่อเขาได้ทดลองพระเจ้าแล้วก็พ้นไปได้’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 16, 'แล้วคนเหล่านั้นที่เกรงกลัวพระเยโฮวาห์จึงพูดกันและกัน พระเยโฮวาห์ทรงฟังและทรงได้ยิน และมีหนังสือม้วนหนึ่งสําหรับบันทึกความจําหน้าพระพักตร์ ได้บันทึกชื่อผู้ที่เกรงกลัวพระเยโฮวาห์ และที่ตรึกตรองในพระนามของพระองค์ไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 17, 'พระเยโฮวาห์จอมโยธาตรัสว่า “เขาทั้งหลายจะเป็นคนของเรา เป็นเพชรพลอยของเราในวันที่เราจะประกอบกิจ และเราจะไว้ชีวิตคนเหล่านี้ ดังชายที่ไว้ชีวิตบุตรชายของเขาผู้ปรนนิบัติเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 18, 'แล้วเจ้าจะกลับมาและสังเกตเห็นความแตกต่างระหว่างคนชอบธรรมกับคนชั่ว ระหว่างคนที่ปรนนิบัติพระเจ้ากับคนที่ไม่ปรนนิบัติพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 1, 'พระเยโฮวาห์จอมโยธาตรัสว่า “ดูเถิด วันนั้นจะมาถึง คือวันที่จะเผาไหม้เหมือนเตาอบ เมื่อคนที่อวดดีทั้งสิ้น เออ และคนที่ประกอบความชั่วทั้งหมดจะเป็นเหมือนตอข้าว วันที่จะมานั้นจะไหม้เขาหมด จนไม่มีรากหรือกิ่งเหลืออยู่เลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 2, 'แต่ดวงอาทิตย์แห่งความชอบธรรมซึ่งมีปีกรักษาโรคภัยได้จะขึ้นมาสําหรับคนเหล่านั้นที่ยําเกรงนามของเรา เจ้าจะกระโดดโลดเต้นออกไปเหมือนลูกวัวออกไปจากคอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 3, 'และเจ้าจะเหยียบย่ําคนชั่ว เพราะว่าเขาจะเป็นเหมือนขี้เถ้าที่ใต้ฝ่าเท้าของเจ้าในวันนั้นเมื่อเราประกอบกิจ พระเยโฮวาห์จอมโยธาตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 4, 'จงจดจําราชบัญญัติของโมเสสผู้รับใช้ของเรา ทั้งกฎเกณฑ์และคําตัดสินซึ่งเราได้บัญชาเขาไว้ที่ภูเขาโฮเรบสําหรับอิสราเอลทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 5, 'ดูเถิด เราจะส่งเอลียาห์ผู้พยากรณ์มายังเจ้าก่อนวันแห่งพระเยโฮวาห์ คือวันที่ใหญ่ยิ่งและน่าสะพรึงกลัวมาถึง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 6, 'และท่านผู้นั้นจะกระทําให้จิตใจของพ่อหันไปหาลูก และจิตใจของลูกหันไปหาพ่อ หาไม่ เราจะมาโจมตีแผ่นดินนั้นด้วยคําสาปแช่ง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 1, 'หนังสือลําดับพงศ์พันธุ์ของพระเยซูคริสต์ ผู้ทรงเป็นบุตรของดาวิด ผู้ทรงเป็นบุตรของอับราฮัม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 2, 'อับราฮัมให้กําเนิดบุตรชื่ออิสอัค อิสอัคให้กําเนิดบุตรชื่อยาโคบ ยาโคบให้กําเนิดบุตรชื่อยูดาห์และพี่น้องของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 3, 'ยูดาห์ให้กําเนิดบุตรชื่อเปเรศกับเศ-ราห์เกิดจากนางทามาร์ เปเรศให้กําเนิดบุตรชื่อเฮสโรน เฮสโรนให้กําเนิดบุตรชื่อราม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 4, 'รามให้กําเนิดบุตรชื่ออัมมีนาดับ อัมมีนาดับให้กําเนิดบุตรชื่อนาโชน นาโชนให้กําเนิดบุตรชื่อสัลโมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 5, 'สัลโมนให้กําเนิดบุตรชื่อโบอาสเกิดจากนางราหับ โบอาสให้กําเนิดบุตรชื่อโอเบดเกิดจากนางรูธ โอเบดให้กําเนิดบุตรชื่อเจสซี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 6, 'เจสซีให้กําเนิดบุตรชื่อดาวิดผู้เป็นกษัตริย์ ดาวิดผู้เป็นกษัตริย์ให้กําเนิดบุตรชื่อซาโลมอน เกิดจากนางซึ่งแต่ก่อนเป็นภรรยาของอุรีอาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 7, 'ซาโลมอนให้กําเนิดบุตรชื่อเรโหโบอัม เรโหโบอัมให้กําเนิดบุตรชื่ออาบียาห์ อาบียาห์ให้กําเนิดบุตรชื่ออาสา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 8, 'อาสาให้กําเนิดบุตรชื่อเยโฮชาฟัท เยโฮชาฟัทให้กําเนิดบุตรชื่อโยรัม โยรัมให้กําเนิดบุตรชื่ออุสซียาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 9, 'อุสซียาห์ให้กําเนิดบุตรชื่อโยธาม โยธามให้กําเนิดบุตรชื่ออาหัส อาหัสให้กําเนิดบุตรชื่อเฮเซคียาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 10, 'เฮเซคียาห์ให้กําเนิดบุตรชื่อมนัสเสห์ มนัสเสห์ให้กําเนิดบุตรชื่ออาโมน อาโมนให้กําเนิดบุตรชื่อโยสิยาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 11, 'โยสิยาห์ให้กําเนิดบุตรชื่อเยโคนิยาห์กับพวกพี่น้องของเขา เกิดเมื่อคราวพวกเขาต้องถูกกวาดไปเป็นเชลยยังกรุงบาบิโลน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 12, 'หลังจากพวกเขาต้องถูกกวาดไปยังกรุงบาบิโลนแล้ว เยโคนิยาห์ก็ให้กําเนิดบุตรชื่อเชอัลทิเอล เชอัลทิเอลให้กําเนิดบุตรชื่อเศรุบบาเบล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 13, 'เศรุบบาเบลให้กําเนิดบุตรชื่ออาบีอูด อาบีอูดให้กําเนิดบุตรชื่อเอลียาคิม เอลียาคิมให้กําเนิดบุตรชื่ออาซอร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 14, 'อาซอร์ให้กําเนิดบุตรชื่อศาโดก ศาโดกให้กําเนิดบุตรชื่ออาคิม อาคิมให้กําเนิดบุตรชื่อเอลีอูด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 15, 'เอลีอูดให้กําเนิดบุตรชื่อเอเลอาซาร์ เอเลอาซาร์ให้กําเนิดบุตรชื่อมัทธาน มัทธานให้กําเนิดบุตรชื่อยาโคบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 16, 'ยาโคบให้กําเนิดบุตรชื่อโยเซฟ สามีของนางมารีย์ พระเยซูที่เรียกว่าพระคริสต์ก็ทรงบังเกิดมาจากนางมารีย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 17, 'ดังนั้น ตั้งแต่อับราฮัมลงมาจนถึงดาวิดจึงเป็นสิบสี่ชั่วคน และนับตั้งแต่ดาวิดลงมาจนถึงต้องถูกกวาดไปเป็นเชลยยังกรุงบาบิโลนเป็นเวลาสิบสี่ชั่วคน และนับตั้งแต่ต้องถูกกวาดไปเป็นเชลยยังกรุงบาบิโลนจนถึงพระคริสต์เป็นสิบสี่ชั่วคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 18, 'เรื่องพระกําเนิดของพระเยซูคริสต์เป็นดังนี้ คือมารีย์ผู้เป็นมารดาของพระเยซูนั้น เดิมโยเซฟได้สู่ขอหมั้นกันไว้แล้ว ก่อนที่จะได้อยู่กินด้วยกันก็ปรากฏว่า มารีย์มีครรภ์แล้วด้วยเดชพระวิญญาณบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 19, 'แต่โยเซฟสามีของเธอเป็นคนชอบธรรม ไม่พอใจที่จะแพร่งพรายความเป็นไปของเธอ หมายจะถอนหมั้นเสียลับๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 20, 'แต่เมื่อโยเซฟยังคิดในเรื่องนี้อยู่ ดูเถิด มีทูตสวรรค์ขององค์พระผู้เป็นเจ้า มาปรากฏแก่โยเซฟในความฝันว่า “โยเซฟ บุตรดาวิด อย่ากลัวที่จะรับมารีย์มาเป็นภรรยาของเจ้าเลย เพราะว่าผู้ซึ่งปฏิสนธิในครรภ์ของเธอเป็นโดยเดชพระวิญญาณบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 21, 'เธอจะประสูติบุตรชาย แล้วเจ้าจะเรียกนามของท่านว่า เยซู เพราะว่าท่านจะโปรดช่วยชนชาติของท่านให้รอดจากความผิดบาปของเขาทั้งหลาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 22, 'ทั้งนี้เกิดขึ้นเพื่อจะให้สําเร็จตามพระวจนะขององค์พระผู้เป็นเจ้าซึ่งตรัสไว้โดยศาสดาพยากรณ์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 23, '‘ดูเถิด หญิงพรหมจารีคนหนึ่งจะตั้งครรภ์ และจะคลอดบุตรชายคนหนึ่ง และเขาจะเรียกนามของท่านว่า อิมมานูเอล ซึ่งแปลว่า พระเจ้าทรงอยู่กับเรา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 24, 'ครั้นโยเซฟตื่นขึ้นก็กระทําตามคําซึ่งทูตสวรรค์ขององค์พระผู้เป็นเจ้าสั่งเขานั้น คือได้รับมารีย์มาเป็นภรรยา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 25, 'แต่มิได้ร่วมรู้กับเธอจนประสูติบุตรชายหัวปีแล้ว และโยเซฟเรียกนามของบุตรนั้นว่า เยซู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 1, 'ครั้นพระเยซูได้ทรงบังเกิดที่บ้านเบธเลเฮมแคว้นยูเดียในรัชกาลของกษัตริย์เฮโรด ดูเถิด มีพวกนักปราชญ์จากทิศตะวันออกมายังกรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 2, 'ถามว่า “กุมารที่บังเกิดมาเป็นกษัตริย์ของชนชาติยิวนั้นอยู่ที่ไหน เราได้เห็นดาวของท่านปรากฏขึ้นในทิศตะวันออก เราจึงมาหวังจะนมัสการท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 3, 'ครั้นกษัตริย์เฮโรดได้ยินดังนั้นแล้ว ท่านก็วุ่นวายพระทัย ทั้งชาวกรุงเยรูซาเล็มก็พลอยวุ่นวายใจไปกับท่านด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 4, 'แล้วท่านให้ประชุมบรรดาปุโรหิตใหญ่กับพวกธรรมาจารย์ของประชาชน ตรัสถามเขาว่า พระคริสต์นั้นจะบังเกิดแห่งใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 5, 'เขาทูลท่านว่า “ที่บ้านเบธเลเฮมแคว้นยูเดีย เพราะว่าศาสดาพยากรณ์ได้เขียนไว้ดังนี้ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 6, '‘บ้านเบธเลเฮมในแผ่นดินยูเดีย จะเป็นบ้านเล็กน้อยที่สุดท่ามกลางบรรดาผู้ครอบครองของยูเดียก็หามิได้ เพราะว่าเจ้านายคนหนึ่งจะออกมาจากท่าน ผู้ซึ่งจะปกครองอิสราเอลชนชาติของเรา’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 7, 'แล้วเฮโรดจึงเชิญพวกนักปราชญ์เข้ามาเป็นการลับ สอบถามเขาอย่างถ้วนถี่ถึงเวลาที่ดาวนั้นได้ปรากฏขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 8, 'และท่านได้ให้พวกนักปราชญ์ไปยังบ้านเบธเลเฮมสั่งว่า “จงไปค้นหากุมารนั้นอย่างถี่ถ้วนกันเถิด เมื่อพบแล้วจงกลับมาแจ้งแก่เรา เพื่อเราจะได้ไปนมัสการท่านด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 9, 'ครั้นพวกเขาได้ฟังกษัตริย์แล้ว เขาก็ได้ลาไป และดูเถิด ดาวซึ่งเขาได้เห็นในทิศตะวันออกนั้นก็ได้นําหน้าเขาไป จนมาหยุดอยู่เหนือสถานที่ที่กุมารอยู่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 10, 'เมื่อพวกนักปราชญ์ได้เห็นดาวนั้นแล้ว เขาก็มีความชื่นชมยินดียิ่งนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 11, 'ครั้นพวกเขาเข้าไปในเรือนก็พบกุมารกับนางมารีย์มารดา จึงกราบถวายนมัสการกุมารนั้น แล้วเปิดหีบหยิบทรัพย์ของเขาออกมาถวายแก่กุมารเป็นเครื่องบรรณาการ คือ ทองคํา กํายาน และมดยอบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 12, 'และพวกนักปราชญ์ได้ยินคําเตือนจากพระเจ้าในความฝัน มิให้กลับไปเฝ้าเฮโรด เขาจึงกลับไปยังบ้านเมืองของตนทางอื่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 13, 'ครั้นเขาไปแล้ว ดูเถิด ทูตสวรรค์ขององค์พระผู้เป็นเจ้าได้มาปรากฏแก่โยเซฟในความฝันแล้วบอกว่า “จงลุกขึ้นพากุมารกับมารดาหนีไปประเทศอียิปต์ และคอยอยู่ที่นั่นจนกว่าเราจะบอกเจ้า เพราะว่าเฮโรดจะแสวงหากุมารเพื่อจะประหารชีวิตเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 14, 'ในเวลากลางคืนโยเซฟจึงลุกขึ้นพากุมารกับมารดาไปยังประเทศอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 15, 'และได้อยู่ที่นั่นจนเฮโรดสิ้นพระชนม์ ทั้งนี้เกิดขึ้นเพื่อจะให้สําเร็จตามพระวจนะขององค์พระผู้เป็นเจ้าซึ่งได้ตรัสไว้โดยศาสดาพยากรณ์ว่า ‘เราได้เรียกบุตรชายของเราออกมาจากประเทศอียิปต์’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 16, 'ครั้นเฮโรดเห็นว่าพวกนักปราชญ์หลอกท่าน ก็กริ้วโกรธยิ่งนัก จึงใช้คนไปฆ่าเด็กทั้งหมดในบ้านเบธเลเฮมและที่ใกล้เคียงทั้งสิ้น ตั้งแต่อายุสองขวบลงมา ซึ่งพอดีกับเวลาที่ท่านได้ถามพวกนักปราชญ์อย่างถ้วนถี่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 17, 'ครั้งนั้นก็สําเร็จตามพระวจนะที่ตรัสโดยเยเรมีย์ศาสดาพยากรณ์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 18, '‘ได้ยินเสียงในหมู่บ้านรามาห์ เป็นเสียงโอดครวญและร้องไห้และร่ําไห้เป็นอันมาก คือนางราเชลร้องไห้เพราะบุตรทั้งหลายของตน นางไม่รับฟังคําเล้าโลม เพราะว่าบุตรทั้งหลายนั้นไม่มีแล้ว’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 19, 'ครั้นเฮโรดสิ้นพระชนม์แล้ว ดูเถิด ทูตสวรรค์องค์หนึ่งขององค์พระผู้เป็นเจ้า มาปรากฏในความฝันแก่โยเซฟที่ประเทศอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 20, 'สั่งว่า “จงลุกขึ้นพากุมารกับมารดามายังแผ่นดินอิสราเอล เพราะคนเหล่านั้นที่แสวงหาชีวิตของกุมารนั้นตายแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 21, 'โยเซฟจึงลุกขึ้นพากุมารกับมารดามายังแผ่นดินอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 22, 'แต่เมื่อได้ยินว่า อารเคลาอัสครอบครองแคว้นยูเดียแทนเฮโรดผู้เป็นบิดา จะไปที่นั่นก็กลัว และเมื่อได้ทราบการเตือนจากพระเจ้าในความฝัน จึงเลี่ยงไปยังบริเวณแคว้นกาลิลี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 23, 'ไปอาศัยในเมืองหนึ่งชื่อนาซาเร็ธ เพื่อจะสําเร็จตามพระวจนะซึ่งตรัสโดยพวกศาสดาพยากรณ์ว่า ‘เขาจะเรียกท่านว่าชาวนาซาเร็ธ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 1, 'คราวนั้นยอห์นผู้ให้รับบัพติศมา มาประกาศในถิ่นทุรกันดารแคว้นยูเดีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 2, 'กล่าวว่า “ท่านทั้งหลายจงกลับใจเสียใหม่ เพราะว่าอาณาจักรแห่งสวรรค์มาใกล้แล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 3, 'ยอห์นผู้นี้แหละซึ่งตรัสถึงโดยอิสยาห์ศาสดาพยากรณ์ว่า ‘เสียงผู้ร้องในถิ่นทุรกันดารว่า ท่านจงเตรียมมรรคาขององค์พระผู้เป็นเจ้า จงกระทําหนทางของพระองค์ให้ตรงไป’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 4, 'เสื้อผ้าของยอห์นผู้นี้ทําด้วยขนอูฐ และท่านใช้หนังสัตว์คาดเอว อาหารของท่านคือตั๊กแตนและน้ําผึ้งป่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 5, 'ขณะนั้นชาวกรุงเยรูซาเล็ม และคนทั่วแคว้นยูเดีย และคนทั่วบริเวณรอบแม่น้ําจอร์แดน ก็ออกไปหายอห์น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 6, 'สารภาพความผิดบาปของตน และได้รับบัพติศมาจากท่านในแม่น้ําจอร์แดน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 7, 'ครั้นยอห์นเห็นพวกฟาริสีและพวกสะดูสีพากันมาเป็นอันมากเพื่อจะรับบัพติศมา ท่านจึงกล่าวแก่เขาว่า “โอ เจ้าชาติงูร้าย ใครได้เตือนเจ้าให้หนีจากพระอาชญาซึ่งจะมาถึงนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 8, 'เหตุฉะนั้นจงพิสูจน์การกลับใจของเจ้าด้วยผลที่เกิดขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 9, 'อย่านึกเหมาเอาในใจว่า เรามีอับราฮัมเป็นบิดา เพราะเราบอกเจ้าทั้งหลายว่า พระเจ้าทรงฤทธิ์สามารถจะให้บุตรเกิดขึ้นแก่อับราฮัมจากก้อนหินเหล่านี้ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 10, 'บัดนี้ขวานวางไว้ที่โคนต้นไม้แล้ว ดังนั้นทุกต้นที่ไม่เกิดผลดีจะต้องตัดแล้วโยนทิ้งในกองไฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 11, 'เราให้เจ้าทั้งหลายรับบัพติศมาด้วยน้ํา แสดงว่ากลับใจใหม่ก็จริง แต่พระองค์ผู้จะมาภายหลังเรา ทรงมีอิทธิฤทธิ์ยิ่งกว่าเราอีก ซึ่งเราไม่คู่ควรแม้จะถือฉลองพระบาทของพระองค์ พระองค์จะทรงให้เจ้าทั้งหลายรับบัพติศมาด้วยพระวิญญาณบริสุทธิ์และด้วยไฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 12, 'พระหัตถ์ของพระองค์ถือพลั่วพร้อมแล้ว และจะทรงชําระลานข้าวของพระองค์ให้ทั่ว พระองค์จะทรงเก็บข้าวของพระองค์ไว้ในยุ้งฉาง แต่พระองค์จะทรงเผาแกลบด้วยไฟที่ไม่รู้ดับ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 13, 'แล้วพระเยซูเสด็จจากแคว้นกาลิลีมาหายอห์นที่แม่น้ําจอร์แดน เพื่อจะรับบัพติศมาจากท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 14, 'แต่ยอห์นทูลห้ามพระองค์ว่า “ข้าพระองค์ต้องการจะรับบัพติศมาจากพระองค์ ควรหรือที่พระองค์จะเสด็จมาหาข้าพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 15, 'และพระเยซูตรัสตอบยอห์นว่า “บัดนี้จงยอมเถิด เพราะสมควรที่เราทั้งหลายจะกระทําตามสิ่งชอบธรรมทุกประการ” แล้วท่านก็ยอมทําตามพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 16, 'และพระเยซูเมื่อพระองค์ทรงรับบัพติศมาแล้ว ในทันใดนั้นก็เสด็จขึ้นจากน้ํา และดูเถิด ท้องฟ้าก็แหวกออก และพระองค์ได้ทอดพระเนตรเห็นพระวิญญาณของพระเจ้าเสด็จลงมาดุจนกเขาและสถิตอยู่บนพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 17, 'และดูเถิด มีพระสุรเสียงตรัสจากฟ้าสวรรค์ว่า “ท่านผู้นี้เป็นบุตรที่รักของเรา เราชอบใจท่านมาก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 1, 'ครั้งนั้นพระวิญญาณทรงนําพระเยซูเข้าไปในถิ่นทุรกันดาร เพื่อพญามารจะได้มาทดลอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 2, 'และเมื่อพระองค์ทรงอดพระกระยาหารสี่สิบวันสี่สิบคืนแล้ว ภายหลังพระองค์ก็ทรงอยากพระกระยาหาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 3, 'เมื่อผู้ทดลองมาหาพระองค์ มันก็ทูลว่า “ถ้าท่านเป็นพระบุตรของพระเจ้า จงสั่งก้อนหินเหล่านี้ให้กลายเป็นพระกระยาหาร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 4, 'ฝ่ายพระองค์ตรัสตอบว่า “มีเขียนไว้แล้วว่า ‘มนุษย์จะบํารุงชีวิตด้วยอาหารสิ่งเดียวหามิได้ แต่บํารุงด้วยพระวจนะทุกคําซึ่งออกมาจากพระโอษฐ์ของพระเจ้า’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 5, 'แล้วพญามารก็นําพระองค์ขึ้นไปยังนครบริสุทธิ์ และให้พระองค์ประทับที่ยอดหลังคาพระวิหาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 6, 'แล้วทูลพระองค์ว่า “ถ้าท่านเป็นพระบุตรของพระเจ้า จงโจนลงไปเถิด เพราะมีเขียนไว้แล้วว่า ‘พระองค์จะรับสั่งให้เหล่าทูตสวรรค์ของพระองค์ในเรื่องท่าน และเหล่าทูตสวรรค์จะเอามือประคองชูท่านไว้ เกรงว่าในเวลาหนึ่งเวลาใดเท้าของท่านจะกระแทกหิน’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 7, 'พระเยซูจึงตรัสตอบมันว่า “มีเขียนไว้อีกว่า ‘อย่าทดลององค์พระผู้เป็นเจ้าผู้เป็นพระเจ้าของท่าน’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 8, 'อีกครั้งหนึ่งพญามารได้นําพระองค์ขึ้นไปบนภูเขาอันสูงยิ่งนัก และได้แสดงบรรดาราชอาณาจักรในโลก ทั้งความรุ่งเรืองของราชอาณาจักรเหล่านั้นให้พระองค์ทอดพระเนตร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 9, 'แล้วได้ทูลพระองค์ว่า “ถ้าท่านจะกราบลงนมัสการเรา เราจะให้สิ่งทั้งปวงเหล่านี้แก่ท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 10, 'พระเยซูจึงตรัสตอบมันว่า “อ้ายซาตาน จงไปเสียให้พ้น เพราะมีเขียนไว้แล้วว่า ‘จงนมัสการองค์พระผู้เป็นเจ้าผู้เป็นพระเจ้าของท่าน และปรนนิบัติพระองค์แต่ผู้เดียว’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 11, 'แล้วพญามารจึงละพระองค์ไป และดูเถิด มีเหล่าทูตสวรรค์มาปรนนิบัติพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 12, 'ครั้นพระเยซูทรงได้ยินว่ายอห์นถูกขังไว้อยู่ในเรือนจํา พระองค์ก็เสด็จไปยังแคว้นกาลิลี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 13, 'เมื่อเสด็จออกจากเมืองนาซาเร็ธแล้ว พระองค์ก็มาประทับที่เมืองคาเปอรนาอุม ซึ่งอยู่ริมทะเลที่เขตแดนเศบูลุนและนัฟทาลี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 14, 'เพื่อจะสําเร็จตามพระวจนะซึ่งตรัสไว้โดยอิสยาห์ศาสดาพยากรณ์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 15, '‘แคว้นเศบูลุนและแคว้นนัฟทาลีทางข้างทะเลฟากแม่น้ําจอร์แดนข้างโน้น คือกาลิลีแห่งบรรดาประชาชาติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 16, 'ประชาชนผู้นั่งอยู่ในความมืดได้เห็นความสว่างยิ่งใหญ่ และผู้ที่นั่งอยู่ในแดนและเงาแห่งความตาย ก็มีความสว่างขึ้นส่องถึงเขาแล้ว’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 17, 'ตั้งแต่นั้นมาพระเยซูได้ทรงตั้งต้นประกาศว่า “จงกลับใจเสียใหม่ เพราะว่าอาณาจักรแห่งสวรรค์มาใกล้แล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 18, 'ขณะที่พระเยซูทรงดําเนินอยู่ตามชายทะเลกาลิลี ก็ทอดพระเนตรเห็นพี่น้องสองคน คือซีโมนที่เรียกว่าเปโตร กับอันดรูว์น้องชายของเขา กําลังทอดอวนอยู่ที่ทะเล เพราะเขาเป็นชาวประมง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 19, 'พระองค์ตรัสกับเขาว่า “จงตามเรามาเถิด และเราจะตั้งท่านให้เป็นผู้หาคนดั่งหาปลา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 20, 'เขาทั้งสองได้ละอวนตามพระองค์ไปทันที');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 21, 'ครั้นพระองค์เสด็จต่อไป ก็ทอดพระเนตรเห็นพี่น้องอีกสองคน คือยากอบบุตรชายเศเบดีกับยอห์นน้องชายของเขา กําลังชุนอวนอยู่ในเรือกับเศเบดีบิดาของเขา พระองค์ได้ทรงเรียกเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 22, 'ในทันใดนั้นเขาทั้งสองก็ละเรือและลาบิดาของเขาตามพระองค์ไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 23, 'พระเยซูได้เสด็จไปทั่วแคว้นกาลิลี ทรงสั่งสอนในธรรมศาลาของเขา ทรงประกาศข่าวประเสริฐแห่งอาณาจักรนั้น และทรงรักษาโรคภัยไข้เจ็บทุกอย่างของชาวเมืองให้หาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 24, 'กิตติศัพท์ของพระองค์ก็เลื่องลือไปทั่วประเทศซีเรีย เขาจึงพาบรรดาคนป่วยเป็นโรคต่างๆ คนที่ทนทุกข์เวทนา คนผีเข้าสิง คนบ้า และคนเป็นอัมพาตมาหาพระองค์ พระองค์ก็ทรงรักษาเขาให้หาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 25, 'และมีคนหมู่ใหญ่มาจากแคว้นกาลิลี และแคว้นทศบุรี และกรุงเยรูซาเล็ม และแคว้นยูเดีย และแม่น้ําจอร์แดนฟากข้างโน้น ติดตามพระองค์ไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 1, 'ครั้นทอดพระเนตรเห็นคนมากดังนั้น พระองค์ก็เสด็จขึ้นไปบนภูเขา และเมื่อประทับแล้ว เหล่าสาวกของพระองค์มาเฝ้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 2, 'และพระองค์ทรงเอ่ยพระโอษฐ์ตรัสสอนเขาว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 3, '“บุคคลผู้ใดรู้สึกบกพร่องฝ่ายจิตวิญญาณ ผู้นั้นเป็นสุข เพราะอาณาจักรแห่งสวรรค์เป็นของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 4, 'บุคคลผู้ใดโศกเศร้า ผู้นั้นเป็นสุข เพราะว่าเขาจะได้รับการทรงปลอบประโลม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 5, 'บุคคลผู้ใดมีใจอ่อนโยน ผู้นั้นเป็นสุข เพราะว่าเขาจะได้รับแผ่นดินโลกเป็นมรดก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 6, 'บุคคลผู้ใดหิวกระหายความชอบธรรม ผู้นั้นเป็นสุข เพราะว่าเขาจะได้อิ่มบริบูรณ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 7, 'บุคคลผู้ใดมีใจกรุณา ผู้นั้นเป็นสุข เพราะว่าเขาจะได้รับพระกรุณา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 8, 'บุคคลผู้ใดมีใจบริสุทธิ์ ผู้นั้นเป็นสุข เพราะว่าเขาจะได้เห็นพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 9, 'บุคคลผู้ใดสร้างสันติ ผู้นั้นเป็นสุข เพราะว่าจะได้เรียกเขาว่าเป็นบุตรของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 10, 'บุคคลผู้ใดต้องถูกข่มเหงเพราะเหตุความชอบธรรม ผู้นั้นเป็นสุข เพราะว่าอาณาจักรแห่งสวรรค์เป็นของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 11, 'เมื่อเขาจะติเตียนข่มเหงและนินทาว่าร้ายท่านทั้งหลายเป็นความเท็จเพราะเรา ท่านก็เป็นสุข');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 12, 'จงชื่นชมยินดีอย่างเหลือล้น เพราะว่าบําเหน็จของท่านมีบริบูรณ์ในสวรรค์ เพราะเขาได้ข่มเหงศาสดาพยากรณ์ทั้งหลายที่อยู่ก่อนท่านเหมือนกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 13, 'ท่านทั้งหลายเป็นเกลือแห่งโลก แต่ถ้าเกลือนั้นหมดรสเค็มไปแล้ว จะทําให้กลับเค็มอีกอย่างไรได้ แต่นั้นไปก็ไม่เป็นประโยชน์อะไร มีแต่จะทิ้งเสียสําหรับคนเหยียบย่ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 14, 'ท่านทั้งหลายเป็นความสว่างของโลก นครซึ่งอยู่บนภูเขาจะปิดบังไว้ไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 15, 'ไม่มีผู้ใดจุดเทียนแล้วนําไปวางไว้ในถัง แต่ย่อมตั้งไว้บนเชิงเทียน จะได้ส่องสว่างแก่ทุกคนที่อยู่ในเรือนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 16, 'จงให้ความสว่างของท่านส่องไปต่อหน้าคนทั้งปวงอย่างนั้น เพื่อว่าเขาได้เห็นความดีที่ท่านทํา และจะได้สรรเสริญพระบิดาของท่านผู้ทรงอยู่ในสวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 17, 'อย่าคิดว่าเรามาเพื่อจะทําลายพระราชบัญญัติหรือคําของศาสดาพยากรณ์เสีย เรามิได้มาเพื่อจะทําลาย แต่มาเพื่อจะให้สําเร็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 18, 'เพราะเราบอกความจริงแก่ท่านทั้งหลายว่า ถึงฟ้าและดินจะล่วงไป แม้อักษรหนึ่งหรือจุดๆหนึ่งก็จะไม่สูญไปจากพระราชบัญญัติ จนกว่าจะสําเร็จทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 19, 'เหตุฉะนั้น ผู้ใดได้ทําให้ข้อเล็กน้อยสักข้อหนึ่งในพระบัญญัตินี้เบาลง ทั้งสอนคนอื่นให้ทําอย่างนั้นด้วย ผู้นั้นจะได้ชื่อว่า เป็นผู้น้อยที่สุดในอาณาจักรแห่งสวรรค์ แต่ผู้ใดที่ประพฤติและสอนตามพระบัญญัติ ผู้นั้นจะได้ชื่อว่า เป็นใหญ่ในอาณาจักรแห่งสวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 20, 'เพราะเราบอกท่านทั้งหลายว่า ถ้าความชอบธรรมของท่านไม่ยิ่งกว่าความชอบธรรมของพวกธรรมาจารย์และพวกฟาริสี ท่านจะไม่มีวันได้เข้าในอาณาจักรแห่งสวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 21, 'ท่านทั้งหลายได้ยินว่ามีคํากล่าวในครั้งโบราณว่า ‘อย่าฆ่าคน’ ถ้าผู้ใดฆ่าคน ผู้นั้นจะต้องถูกพิพากษาลงโทษ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 22, 'ฝ่ายเราบอกท่านทั้งหลายว่า ผู้ใดโกรธพี่น้องของตนโดยไม่มีเหตุ ผู้นั้นจะต้องถูกพิพากษาลงโทษ ถ้าผู้ใดจะพูดกับพี่น้องว่า ‘อ้ายบ้า’ ผู้นั้นต้องถูกนําไปที่ศาลสูงให้พิพากษาลงโทษ และผู้ใดจะว่า ‘อ้ายโง่’ ผู้นั้นจะมีโทษถึงไฟนรก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 23, 'เหตุฉะนั้น ถ้าท่านนําเครื่องบูชามาถึงแท่นบูชาแล้ว และระลึกขึ้นได้ว่า พี่น้องมีเหตุขัดเคืองข้อหนึ่งข้อใดกับท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 24, 'จงวางเครื่องบูชาไว้ที่หน้าแท่นบูชา กลับไปคืนดีกับพี่น้องผู้นั้นเสียก่อน แล้วจึงค่อยมาถวายเครื่องบูชาของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 25, 'จงปรองดองกับคู่ความโดยเร็วขณะที่พากันไป เกลือกว่าในเวลาหนึ่งเวลาใดคู่ความนั้นจะมอบท่านไว้กับผู้พิพากษา แล้วผู้พิพากษาจะมอบท่านไว้กับผู้คุม และท่านจะต้องถูกขังไว้ในเรือนจํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 26, 'เราบอกความจริงแก่ท่านว่า ท่านจะออกจากที่นั่นไม่ได้กว่าท่านจะได้ใช้หนี้จนครบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 27, 'ท่านทั้งหลายได้ยินว่ามีคํากล่าวในครั้งโบราณว่า ‘อย่าล่วงประเวณีผัวเมียเขา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 28, 'ฝ่ายเราบอกท่านทั้งหลายว่า ผู้ใดมองผู้หญิงเพื่อให้เกิดใจกําหนัดในหญิงนั้น ผู้นั้นได้ล่วงประเวณีในใจกับหญิงนั้นแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 29, 'ถ้าตาข้างขวาของท่านทําให้ท่านหลงผิด จงควักออกและโยนมันทิ้งเสียจากท่าน เพราะว่าจะเป็นประโยชน์แก่ท่านมากกว่าที่จะเสียอวัยวะไปอย่างหนึ่ง แต่ทั้งตัวของท่านไม่ต้องถูกทิ้งลงในนรก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 30, 'และถ้ามือข้างขวาของท่านทําให้ท่านหลงผิด จงตัดออกและโยนมันทิ้งเสียจากท่าน เพราะว่าจะเป็นประโยชน์แก่ท่านมากกว่าที่จะเสียอวัยวะไปอย่างหนึ่ง แต่ทั้งตัวของท่านไม่ต้องถูกทิ้งลงในนรก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 31, 'ยังมีคํากล่าวไว้ว่า ‘ผู้ใดจะหย่าภรรยา ก็ให้เขาทําหนังสือหย่าให้แก่ภรรยานั้น’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 32, 'ฝ่ายเราบอกท่านทั้งหลายว่า ผู้ใดจะหย่าภรรยา เพราะเหตุอื่นนอกจากการเล่นชู้ ก็เท่ากับว่าผู้นั้นทําให้หญิงนั้นล่วงประเวณี และถ้าผู้ใดจะรับหญิงซึ่งหย่าแล้วเช่นนั้นมาเป็นภรรยา ผู้นั้นก็ล่วงประเวณีด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 33, 'อีกประการหนึ่ง ท่านทั้งหลายได้ยินว่ามีคํากล่าวในครั้งโบราณว่า ‘อย่าเสียคําสัตย์สาบาน แต่จงปฏิบัติตามคําสัตย์สาบานของท่านต่อองค์พระผู้เป็นเจ้า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 34, 'ฝ่ายเราบอกท่านทั้งหลายว่า อย่าสาบานเลย จะอ้างถึงสวรรค์ก็ดี เพราะสวรรค์เป็นบัลลังก์ของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 35, 'หรือจะอ้างถึงแผ่นดินโลกก็ดี เพราะแผ่นดินโลกเป็นที่รองพระบาทของพระองค์ หรือจะอ้างถึงกรุงเยรูซาเล็มก็ดี เพราะกรุงเยรูซาเล็มเป็นราชธานีของพระมหากษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 36, 'อย่าสาบานโดยอ้างถึงศีรษะของตน เพราะท่านจะกระทําให้ผมขาวหรือดําไปสักเส้นหนึ่งก็ไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 37, 'จริงก็จงว่าจริง ไม่ก็ว่าไม่ พูดแต่เพียงนี้ก็พอ คําพูดเกินนี้ไปมาจากความชั่ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 38, 'ท่านทั้งหลายเคยได้ยินคําซึ่งกล่าวไว้ว่า ‘ตาแทนตา และฟันแทนฟัน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 39, 'ฝ่ายเราบอกท่านว่า อย่าต่อสู้คนชั่ว ถ้าผู้ใดตบแก้มขวาของท่าน ก็จงหันแก้มอีกข้างหนึ่งให้เขาด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 40, 'ถ้าผู้ใดอยากจะฟ้องศาลเพื่อจะริบเอาเสื้อของท่าน ก็จงให้เสื้อคลุมแก่เขาด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 41, 'ถ้าผู้ใดจะเกณฑ์ท่านให้เดินทางไปหนึ่งกิโลเมตร ก็ให้เลยไปกับเขาถึงสองกิโลเมตร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 42, 'ถ้าเขาจะขอสิ่งใดจากท่านก็จงให้ อย่าเมินหน้าจากผู้ที่อยากขอยืมจากท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 43, 'ท่านทั้งหลายเคยได้ยินคําซึ่งกล่าวไว้ว่า ‘จงรักเพื่อนบ้าน และเกลียดชังศัตรู’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 44, 'ฝ่ายเราบอกท่านว่า จงรักศัตรูของท่าน จงอวยพรแก่ผู้ที่สาปแช่งท่าน จงทําดีแก่ผู้ที่เกลียดชังท่าน และจงอธิษฐานเพื่อผู้ที่ปฏิบัติต่อท่านอย่างเหยียดหยามและข่มเหงท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 45, 'จงทําดังนี้เพื่อท่านทั้งหลายจะเป็นบุตรของพระบิดาของท่านผู้ทรงสถิตในสวรรค์ เพราะว่าพระองค์ทรงให้ดวงอาทิตย์ของพระองค์ขึ้นส่องสว่างแก่คนดีและคนชั่ว และให้ฝนตกแก่คนชอบธรรมและแก่คนอธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 46, 'แม้ว่าท่านรักผู้ที่รักท่าน ท่านจะได้บําเหน็จอะไร ถึงพวกเก็บภาษีก็กระทําอย่างนั้นมิใช่หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 47, 'ถ้าท่านทักทายแต่พี่น้องของตนฝ่ายเดียว ท่านได้กระทําอะไรเป็นพิเศษยิ่งกว่าคนทั้งปวงเล่า ถึงพวกเก็บภาษีก็กระทําอย่างนั้นมิใช่หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 48, 'เหตุฉะนี้ ท่านทั้งหลายจงเป็นคนดีรอบคอบ เหมือนอย่างพระบิดาของท่านผู้ทรงสถิตในสวรรค์เป็นผู้ดีรอบคอบ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 1, '“จงระวังให้ดี ท่านอย่าทําทานต่อหน้ามนุษย์เพื่อจะให้เขาเห็น มิฉะนั้นท่านจะไม่ได้รับบําเหน็จจากพระบิดาของท่านผู้ทรงสถิตในสวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 2, 'เหตุฉะนั้น เมื่อท่านทําทาน อย่าเป่าแตรข้างหน้าท่านเหมือนคนหน้าซื่อใจคดกระทําในธรรมศาลาและตามถนน เพื่อจะได้รับการสรรเสริญจากมนุษย์ เราบอกความจริงแก่ท่านว่า เขาได้รับบําเหน็จของเขาแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 3, 'ฝ่ายท่านทั้งหลายเมื่อทําทาน อย่าให้มือซ้ายรู้การซึ่งมือขวากระทํานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 4, 'เพื่อทานของท่านจะเป็นการลับ และพระบิดาของท่านผู้ทอดพระเนตรเห็นในที่ลี้ลับ พระองค์เองจะทรงโปรดประทานบําเหน็จแก่ท่านอย่างเปิดเผย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 5, 'เมื่อท่านทั้งหลายอธิษฐาน อย่าเป็นเหมือนคนหน้าซื่อใจคด เพราะเขาชอบยืนอธิษฐานในธรรมศาลาและที่มุมถนน เพื่อจะให้คนทั้งปวงได้เห็น เราบอกความจริงแก่ท่านว่า เขาได้รับบําเหน็จของเขาแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 6, 'ฝ่ายท่านเมื่ออธิษฐานจงเข้าในห้องชั้นใน และเมื่อปิดประตูแล้ว จงอธิษฐานต่อพระบิดาของท่านผู้ทรงสถิตในที่ลี้ลับ และพระบิดาของท่านผู้ทอดพระเนตรเห็นในที่ลี้ลับจะทรงโปรดประทานบําเหน็จแก่ท่านอย่างเปิดเผย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 7, 'แต่เมื่อท่านอธิษฐาน อย่าใช้คําซ้ําซากไร้ประโยชน์เหมือนคนต่างชาติ เพราะเขาคิดว่าพูดมากหลายคํา พระจึงจะทรงโปรดฟัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 8, 'เหตุฉะนั้นท่านอย่าเป็นเหมือนเขาเลย เพราะว่าสิ่งไรซึ่งท่านต้องการ พระบิดาของท่านทรงทราบก่อนที่ท่านทูลขอแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 9, 'เหตุฉะนั้น ท่านทั้งหลายจงอธิษฐานตามอย่างนี้ว่า ข้าแต่พระบิดาของข้าพระองค์ทั้งหลาย ผู้ทรงสถิตในสวรรค์ ขอให้พระนามของพระองค์เป็นที่เคารพสักการะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 10, 'ขอให้อาณาจักรของพระองค์มาตั้งอยู่ ขอให้เป็นไปตามพระทัยของพระองค์ ในสวรรค์เป็นอย่างไร ก็ให้เป็นไปอย่างนั้นในแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 11, 'ขอทรงโปรดประทานอาหารประจําวันแก่ข้าพระองค์ทั้งหลายในกาลวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 12, 'และขอทรงโปรดยกหนี้ของข้าพระองค์ เหมือนข้าพระองค์ยกหนี้ผู้ที่เป็นหนี้ข้าพระองค์นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 13, 'และขออย่านําข้าพระองค์เข้าไปในการทดลอง แต่ขอทรงช่วยข้าพระองค์ให้พ้นจากความชั่วร้าย เหตุว่าอาณาจักรและฤทธิ์เดชและสง่าราศีเป็นของพระองค์สืบๆไปเป็นนิตย์ เอเมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 14, 'เพราะว่าถ้าท่านยกการละเมิดของเพื่อนมนุษย์ พระบิดาของท่านผู้ทรงสถิตในสวรรค์จะทรงโปรดยกโทษให้ท่านด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 15, 'แต่ถ้าท่านไม่ยกการละเมิดของเพื่อนมนุษย์ พระบิดาของท่านจะไม่ทรงโปรดยกการละเมิดของท่านเหมือนกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 16, 'ยิ่งกว่านั้นเมื่อท่านถืออดอาหาร อย่าทําหน้าเศร้าหมองเหมือนคนหน้าซื่อใจคด ด้วยเขาแสร้งทําหน้าให้ผิดปกติ เพื่อจะให้คนเห็นว่าเขาถืออดอาหาร เราบอกความจริงแก่ท่านว่า เขาได้รับบําเหน็จของเขาแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 17, 'ฝ่ายท่านเมื่อถืออดอาหาร จงชโลมทาศีรษะและล้างหน้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 18, 'เพื่อท่านจะไม่ปรากฏแก่คนอื่นว่าถืออดอาหาร แต่ให้ปรากฏแก่พระบิดาของท่านผู้ทรงสถิตในที่ลี้ลับ และพระบิดาของท่านผู้ทอดพระเนตรเห็นในที่ลี้ลับ จะทรงโปรดประทานบําเหน็จแก่ท่านอย่างเปิดเผย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 19, 'อย่าสะสมทรัพย์สมบัติไว้สําหรับตัวในโลก ที่ตัวมอดและสนิมอาจทําลายเสียได้ และที่ขโมยอาจขุดช่องลักเอาไปได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 20, 'แต่จงสะสมทรัพย์สมบัติไว้สําหรับตัวในสวรรค์ ที่ตัวมอดและสนิมทําลายเสียไม่ได้ และที่ไม่มีขโมยขุดช่องลักเอาไปได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 21, 'เพราะว่าทรัพย์สมบัติของท่านอยู่ที่ไหน ใจของท่านก็จะอยู่ที่นั่นด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 22, 'ตาเป็นประทีปของร่างกาย เหตุฉะนั้นถ้าตาของท่านดี ทั้งตัวก็จะเต็มไปด้วยความสว่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 23, 'แต่ถ้าตาของท่านชั่ว ทั้งตัวของท่านก็จะเต็มไปด้วยความมืด เหตุฉะนั้นถ้าความสว่างซึ่งอยู่ในตัวท่านมืดไป ความมืดนั้นจะหนาทึบสักเพียงใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 24, 'ไม่มีผู้ใดปรนนิบัตินายสองนายได้ เพราะเขาจะชังนายข้างหนึ่งและจะรักนายอีกข้างหนึ่ง หรือเขาจะนับถือนายฝ่ายหนึ่งและจะดูหมิ่นนายอีกฝ่ายหนึ่ง ท่านจะปรนนิบัติพระเจ้าและเงินทองพร้อมกันไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 25, 'เหตุฉะนั้น เราบอกท่านทั้งหลายว่า อย่ากระวนกระวายถึงชีวิตของตนว่า จะเอาอะไรกิน หรือจะเอาอะไรดื่ม และอย่ากระวนกระวายถึงร่างกายของตนว่า จะเอาอะไรนุ่งห่ม ชีวิตสําคัญยิ่งกว่าอาหารมิใช่หรือ และร่างกายสําคัญยิ่งกว่าเครื่องนุ่งห่มมิใช่หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 26, 'จงดูนกในอากาศ มันมิได้หว่าน มิได้เกี่ยว มิได้สะสมไว้ในยุ้งฉาง แต่พระบิดาของท่านทั้งหลายผู้ทรงสถิตในสวรรค์ทรงเลี้ยงนกไว้ ท่านทั้งหลายมิประเสริฐกว่านกหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 27, 'มีใครในพวกท่าน โดยความกระวนกระวาย อาจต่อความสูงให้ยาวออกไปอีกสักศอกหนึ่งได้หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 28, 'ท่านกระวนกระวายถึงเครื่องนุ่งห่มทําไม จงพิจารณาดอกลิลลี่ที่ทุ่งนาว่า มันงอกงามเจริญขึ้นได้อย่างไร มันไม่ทํางาน มันไม่ปั่นด้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 29, 'และเราบอกท่านทั้งหลายว่า ซาโลมอนเมื่อบริบูรณ์ด้วยสง่าราศีของท่าน ก็มิได้ทรงเครื่องงามเท่าดอกไม้นี้ดอกหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 30, 'เหตุฉะนั้น ถ้าพระเจ้าทรงตกแต่งหญ้าที่ทุ่งนาอย่างนั้น ซึ่งเป็นอยู่วันนี้และรุ่งขึ้นต้องทิ้งในเตาไฟ โอ ผู้มีความเชื่อน้อย พระองค์จะไม่ทรงตกแต่งท่านมากยิ่งกว่านั้นหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 31, 'เหตุฉะนั้น อย่ากระวนกระวายว่า เราจะเอาอะไรกิน หรือจะเอาอะไรดื่ม หรือจะเอาอะไรนุ่งห่ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 32, '(เพราะว่าพวกต่างชาติแสวงหาสิ่งของทั้งปวงนี้) แต่ว่าพระบิดาของท่านผู้ทรงสถิตในสวรรค์ทรงทราบแล้วว่า ท่านต้องการสิ่งทั้งปวงเหล่านี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 33, 'แต่ท่านทั้งหลายจงแสวงหาอาณาจักรของพระเจ้า และความชอบธรรมของพระองค์ก่อน แล้วพระองค์จะทรงเพิ่มเติมสิ่งทั้งปวงเหล่านี้ให้แก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 34, 'เหตุฉะนั้น อย่ากระวนกระวายถึงพรุ่งนี้ เพราะว่าพรุ่งนี้ก็จะมีการกระวนกระวายสําหรับพรุ่งนี้เอง แต่ละวันก็มีทุกข์พออยู่แล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 1, '“อย่ากล่าวโทษเขา เพื่อท่านจะไม่ต้องถูกกล่าวโทษ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 2, 'เพราะว่าท่านทั้งหลายจะกล่าวโทษเขาอย่างไร ท่านจะต้องถูกกล่าวโทษอย่างนั้น และท่านจะตวงให้เขาด้วยทะนานอันใด ท่านจะได้รับตวงด้วยทะนานอันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 3, 'เหตุไฉนท่านมองดูผงที่อยู่ในตาพี่น้องของท่าน แต่ไม่ยอมพิจารณาไม้ทั้งท่อนที่อยู่ในตาของท่านเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 4, 'หรือเหตุไฉนท่านจะกล่าวแก่พี่น้องของท่านว่า ‘ให้เราเขี่ยผงออกจากตาของท่าน’ แต่ดูเถิด ไม้ทั้งท่อนก็อยู่ในตาของท่านเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 5, 'ท่านคนหน้าซื่อใจคด จงชักไม้ทั้งท่อนออกจากตาของท่านก่อน แล้วท่านจะเห็นได้ถนัด จึงจะเขี่ยผงออกจากตาพี่น้องของท่านได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 6, 'อย่าให้สิ่งซึ่งบริสุทธิ์แก่สุนัข และอย่าโยนไข่มุกของท่านให้แก่สุกร เกลือกว่ามันจะเหยียบย่ําเสีย และจะหันกลับมากัดตัวท่านด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 7, 'จงขอแล้วจะได้ จงหาแล้วจะพบ จงเคาะแล้วจะเปิดให้แก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 8, 'เพราะว่าทุกคนที่ขอก็ได้รับ คนที่แสวงหาก็พบ และคนที่เคาะก็จะเปิดให้เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 9, 'ในพวกท่านมีใครบ้างที่จะเอาก้อนหินให้บุตร เมื่อเขาขอขนมปัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 10, 'หรือให้งูเมื่อบุตรขอปลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 11, 'เหตุฉะนั้น ถ้าท่านทั้งหลายเองผู้เป็นคนชั่ว ยังรู้จักให้ของดีแก่บุตรของตน ยิ่งกว่านั้นสักเท่าใดพระบิดาของท่านผู้ทรงสถิตในสวรรค์จะประทานของดีแก่ผู้ที่ขอจากพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 12, 'เหตุฉะนั้น สิ่งสารพัดซึ่งท่านปรารถนาให้มนุษย์ทําแก่ท่าน จงกระทําอย่างนั้นแก่เขาเหมือนกัน เพราะว่านี่คือพระราชบัญญัติและคําของศาสดาพยากรณ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 13, 'จงเข้าไปทางประตูแคบ เพราะว่าประตูใหญ่และทางกว้างนั้นนําไปถึงความพินาศ และคนที่เข้าไปทางนั้นมีมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 14, 'เพราะว่าประตูซึ่งนําไปถึงชีวิตนั้นก็คับและทางก็แคบ ผู้ที่หาพบก็มีน้อย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 15, 'จงระวังผู้พยากรณ์เท็จที่มาหาท่านนุ่งห่มดุจแกะ แต่ภายในเขาร้ายกาจดุจสุนัขป่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 16, 'ท่านจะรู้จักเขาได้ด้วยผลของเขา มนุษย์เก็บผลองุ่นจากต้นไม้หนามหรือ หรือว่าเก็บผลมะเดื่อจากต้นผักหนาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 17, 'ดังนั้นแหละต้นไม้ดีทุกต้นย่อมให้แต่ผลดี ต้นไม้เลวก็ย่อมให้ผลเลว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 18, 'ต้นไม้ดีจะเกิดผลเลวไม่ได้ หรือต้นไม้เลวจะเกิดผลดีก็ไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 19, 'ต้นไม้ทุกต้นซึ่งไม่เกิดผลดีย่อมต้องถูกฟันลงและทิ้งเสียในไฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 20, 'เหตุฉะนั้น ท่านจะรู้จักเขาได้เพราะผลของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 21, 'มิใช่ทุกคนที่ร้องแก่เราว่า ‘พระองค์เจ้าข้า พระองค์เจ้าข้า’ จะได้เข้าในอาณาจักรแห่งสวรรค์ แต่ผู้ที่ปฏิบัติตามพระทัยพระบิดาของเราผู้ทรงสถิตในสวรรค์จึงจะเข้าได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 22, 'เมื่อถึงวันนั้นจะมีคนเป็นอันมากร้องแก่เราว่า ‘พระองค์เจ้าข้า พระองค์เจ้าข้า ข้าพระองค์ได้พยากรณ์ในพระนามของพระองค์ และได้ขับผีออกในพระนามของพระองค์ และได้กระทําการมหัศจรรย์เป็นอันมากในพระนามของพระองค์มิใช่หรือ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 23, 'เมื่อนั้นเราจะแจ้งแก่เขาว่า ‘เราไม่เคยรู้จักเจ้าเลย เจ้าผู้กระทําความชั่วช้า จงไปเสียให้พ้นจากเรา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 24, 'เหตุฉะนั้นผู้ใดที่ได้ยินคําเหล่านี้ของเราและประพฤติตาม เขาก็เปรียบเสมือนผู้ที่มีสติปัญญาสร้างเรือนของตนไว้บนศิลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 25, 'ฝนก็ตกและน้ําก็ไหลท่วม ลมก็พัดปะทะเรือนนั้น แต่เรือนมิได้พังลง เพราะว่ารากตั้งอยู่บนศิลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 26, 'แต่ผู้ที่ได้ยินคําเหล่านี้ของเราและไม่ประพฤติตาม เขาก็เปรียบเสมือนผู้ที่โง่เขลาสร้างเรือนของตนไว้บนทราย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 27, 'ฝนก็ตกและน้ําก็ไหลท่วม ลมก็พัดปะทะเรือนนั้น เรือนนั้นก็พังทลายลง และการซึ่งพังทลายนั้นก็ใหญ่ยิ่งนัก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 28, 'ต่อมาครั้นพระเยซูตรัสถ้อยคําเหล่านี้เสร็จแล้ว ประชาชนก็อัศจรรย์ใจด้วยคําสั่งสอนของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 29, 'เพราะว่าพระองค์ได้ทรงสั่งสอนเขาด้วยสิทธิอํานาจ ไม่เหมือนพวกธรรมาจารย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 1, 'เมื่อพระองค์เสด็จลงมาจากภูเขาแล้ว คนเป็นอันมากได้ติดตามพระองค์ไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 2, 'ดูเถิด มีคนโรคเรื้อนมานมัสการพระองค์แล้วทูลว่า “พระองค์เจ้าข้า เพียงแต่พระองค์จะโปรด ก็จะทรงบันดาลให้ข้าพระองค์สะอาดได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 3, 'พระเยซูทรงยื่นพระหัตถ์ถูกต้องเขา แล้วตรัสว่า “เราพอใจแล้ว จงสะอาดเถิด” ในทันใดนั้นโรคเรื้อนของเขาก็หาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 4, 'ฝ่ายพระเยซูตรัสสั่งเขาว่า “อย่าบอกเล่าให้ผู้ใดฟังเลย แต่จงไปสําแดงตัวแก่ปุโรหิต และถวายเครื่องถวายตามซึ่งโมเสสได้สั่งไว้ เพื่อเป็นหลักฐานต่อคนทั้งหลาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 5, 'เมื่อพระเยซูเสด็จเข้าไปในเมืองคาเปอรนาอุม มีนายร้อยคนหนึ่งมาอ้อนวอนพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 6, 'ทูลว่า “พระองค์เจ้าข้า ผู้รับใช้ของข้าพระองค์เป็นอัมพาตอยู่ที่บ้าน ทนทุกข์เวทนามาก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 7, 'พระเยซูจึงตรัสกับเขาว่า “เราจะไปรักษาเขาให้หาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 8, 'นายร้อยผู้นั้นทูลว่า “พระองค์เจ้าข้า ข้าพระองค์ไม่สมควรที่จะรับเสด็จพระองค์เข้าใต้ชายคาของข้าพระองค์ ขอพระองค์ตรัสเท่านั้น ผู้รับใช้ของข้าพระองค์ก็จะหายโรค');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 9, 'เพราะเหตุว่าข้าพระองค์เป็นคนอยู่ใต้วินัยทหาร แต่ก็ยังมีทหารอยู่ใต้บังคับบัญชาข้าพระองค์ ข้าพระองค์จะบอกแก่คนนี้ว่า ‘ไป’ เขาก็ไป บอกแก่คนนั้นว่า ‘มา’ เขาก็มา บอกผู้รับใช้ของข้าพระองค์ว่า ‘จงทําสิ่งนี้’ เขาก็ทํา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 10, 'ครั้นพระเยซูทรงได้ยินดังนั้นก็ประหลาดพระทัยนัก ตรัสกับบรรดาคนที่ตามพระองค์ว่า “เราบอกความจริงแก่ท่านทั้งหลายว่า เราไม่เคยพบความเชื่อที่ไหนมากเท่านี้แม้ในอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 11, 'เราบอกท่านทั้งหลายว่า คนเป็นอันมากจะมาจากทิศตะวันออกและทิศตะวันตก จะมาเอนกายลงกันกับอับราฮัมและอิสอัคและยาโคบในอาณาจักรแห่งสวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 12, 'แต่บรรดาลูกของอาณาจักรจะต้องถูกขับไล่ไสส่งออกไปในที่มืดภายนอก ที่นั่นจะมีเสียงร้องไห้ขบเขี้ยวเคี้ยวฟัน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 13, 'แล้วพระเยซูจึงตรัสกับนายร้อยว่า “ไปเถิด ท่านได้เชื่ออย่างไร ก็ให้เป็นแก่ท่านอย่างนั้น” และในเวลานั้นเอง ผู้รับใช้ของเขาก็หายเป็นปกติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 14, 'ครั้นพระเยซูเสด็จเข้าไปในเรือนของเปโตร พระองค์ก็ทอดพระเนตรเห็นแม่ยายของเปโตรนอนป่วยเป็นไข้อยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 15, 'พระองค์ทรงถูกต้องมือนาง ไข้นั้นก็หาย นางจึงลุกขึ้นปรนนิบัติเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 16, 'พอค่ําลง เขาพาคนเป็นอันมากที่มีผีเข้าสิงมาหาพระองค์ พระองค์ก็ทรงขับผีออกด้วยพระดํารัสของพระองค์ และบรรดาคนเจ็บป่วยนั้น พระองค์ก็ได้ทรงรักษาให้หาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 17, 'ทั้งนี้เพื่อจะให้สําเร็จตามพระวจนะโดยอิสยาห์ศาสดาพยากรณ์ที่ว่า ‘ท่านได้แบกความเจ็บไข้ของเราทั้งหลาย และหอบโรคของเราไป’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 18, 'ครั้นพระเยซูทอดพระเนตรเห็นประชาชนเป็นอันมากมาล้อมพระองค์ไว้ พระองค์จึงตรัสสั่งให้ข้ามฟากไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 19, 'ขณะนั้นมีธรรมาจารย์คนหนึ่งมาหาพระองค์ทูลว่า “อาจารย์เจ้าข้า ท่านไปทางไหน ข้าพเจ้าจะตามท่านไปทางนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 20, 'พระเยซูจึงตรัสกับเขาว่า “สุนัขจิ้งจอกยังมีโพรง และนกในอากาศยังมีรัง แต่บุตรมนุษย์ไม่มีที่ที่จะวางศีรษะ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 21, 'อีกคนหนึ่งในพวกสาวกของพระองค์ทูลพระองค์ว่า “พระองค์เจ้าข้า ขอทรงโปรดให้ข้าพระองค์ไปฝังศพบิดาข้าพระองค์ก่อน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 22, 'พระเยซูจึงตรัสกับเขาว่า “จงตามเรามาเถิด ปล่อยให้คนตายฝังคนตายของเขาเองเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 23, 'เมื่อพระองค์เสด็จลงเรือ พวกสาวกของพระองค์ก็ตามพระองค์ไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 24, 'ดูเถิด เกิดพายุใหญ่ในทะเลจนคลื่นซัดท่วมเรือ แต่พระองค์บรรทมหลับอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 25, 'และพวกสาวกของพระองค์ได้มาปลุกพระองค์ ทูลว่า “พระองค์เจ้าข้า ขอโปรดช่วยพวกเราเถิด เรากําลังจะพินาศอยู่แล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 26, 'พระองค์จึงตรัสกับเขาว่า “เหตุไฉนเจ้าจึงหวาดกลัว โอ เจ้าผู้มีความเชื่อน้อย” แล้วพระองค์ทรงลุกขึ้นห้ามลมและทะเล คลื่นลมก็สงบเงียบทั่วไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 27, 'คนเหล่านั้นก็อัศจรรย์ใจพูดกันว่า “ท่านผู้นี้เป็นคนอย่างไรหนอ แม้กระทั่งลมและทะเลก็เชื่อฟังท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 28, 'ครั้นพระองค์ทรงข้ามฟากไปถึงแดนเกอร์กาซีแล้ว มีคนสองคนที่มีผีสิงได้ออกจากอุโมงค์ฝังศพมาพบพระองค์ พวกเขาดุร้ายนัก จนไม่มีผู้ใดอาจผ่านไปทางนั้นได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 29, 'ดูเถิด เขาร้องตะโกนว่า “พระเยซูผู้เป็นพระบุตรของพระเจ้า เราเกี่ยวข้องอะไรกับท่านเล่า ท่านมาที่นี่เพื่อจะทรมานพวกเราก่อนเวลาหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 30, 'ไกลจากที่นั่นมีสุกรฝูงใหญ่กําลังหากินอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 31, 'ผีเหล่านั้นได้อ้อนวอนพระองค์ว่า “ถ้าท่านขับพวกเราออก ก็ขอให้พวกเราเข้าอยู่ในฝูงสุกรนั้นเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 32, 'พระองค์จึงตรัสแก่ผีเหล่านั้นว่า “ไปเถอะ” ผีเหล่านั้นก็ออกไปเข้าสิงอยู่ในฝูงสุกร ดูเถิด สุกรทั้งฝูงนั้นก็วิ่งกระโดดจากหน้าผาชันลงไปในทะเล และจมน้ําตายจนสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 33, 'ฝ่ายคนเลี้ยงสุกรก็หนีเข้าไปในนคร เล่าบรรดาเหตุการณ์ซึ่งเป็นไปนั้น กับเหตุที่เกิดขึ้นแก่คนที่มีผีเข้าสิงอยู่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 34, 'ดูเถิด คนทั้งนครพากันออกมาพบพระเยซู เมื่อพบพระองค์แล้ว เขาจึงอ้อนวอนขอให้พระองค์ไปเสียจากเขตแดนของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 1, 'และพระองค์ก็เสด็จลงเรือข้ามฟากไปยังเมืองของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 2, 'ดูเถิด เขาหามคนอัมพาตคนหนึ่งซึ่งนอนอยู่บนที่นอนมาหาพระองค์ เมื่อพระเยซูทอดพระเนตรเห็นความเชื่อของเขาทั้งหลาย จึงตรัสกับคนอัมพาตว่า “ลูกเอ๋ย จงชื่นใจเถิด บาปของเจ้าได้รับการอภัยแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 3, 'ดูเถิด พวกธรรมาจารย์บางคนคิดในใจว่า “คนนี้พูดหมิ่นประมาท”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 4, 'ฝ่ายพระเยซูทรงทราบความคิดของเขาจึงตรัสว่า “เหตุไฉนท่านทั้งหลายคิดชั่วอยู่ในใจเล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 5, 'ที่จะว่า ‘บาปของเจ้าได้รับการอภัยแล้ว’ หรือจะว่า ‘จงลุกขึ้นเดินไปเถิด’ นั้น ข้างไหนจะง่ายกว่ากัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 6, 'แต่เพื่อท่านทั้งหลายจะได้รู้ว่า บุตรมนุษย์มีสิทธิอํานาจในโลกที่จะโปรดยกความผิดบาปได้” (พระองค์จึงตรัสสั่งคนอัมพาตว่า) “จงลุกขึ้นยกที่นอนกลับไปบ้านเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 7, 'เขาจึงลุกขึ้นไปบ้านของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 8, 'เมื่อประชาชนเป็นอันมากเห็นดังนั้น เขาก็อัศจรรย์ใจ แล้วพากันสรรเสริญพระเจ้า ผู้ได้ทรงประทานสิทธิอํานาจเช่นนั้นแก่มนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 9, 'ครั้นพระเยซูเสด็จเลยที่นั่นไป ก็ทอดพระเนตรเห็นชายคนหนึ่งชื่อมัทธิวนั่งอยู่ที่ด่านเก็บภาษี จึงตรัสกับเขาว่า “จงตามเรามาเถิด” เขาก็ลุกขึ้นตามพระองค์ไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 10, 'ต่อมาเมื่อพระเยซูเอนพระกายลงเสวยอยู่ในเรือน ดูเถิด มีคนเก็บภาษีและคนบาปอื่นๆหลายคนเข้ามาเอนกายลงร่วมสํารับกับพระองค์และกับพวกสาวกของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 11, 'เมื่อพวกฟาริสีเห็นแล้ว ก็กล่าวแก่พวกสาวกของพระองค์ว่า “ทําไมอาจารย์ของท่านจึงรับประทานอาหารร่วมกับคนเก็บภาษีและคนบาปเล่า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 12, 'เมื่อพระเยซูทรงได้ยินเช่นนั้นจึงตรัสกับพวกเขาว่า “คนปกติไม่ต้องการหมอ แต่คนเจ็บป่วยต้องการหมอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 13, 'ท่านทั้งหลายจงไปเรียนรู้ความหมายของข้อความที่ว่า ‘เราประสงค์ความเมตตา ไม่ประสงค์เครื่องสัตวบูชา’ ด้วยว่าเรามิได้มาเพื่อจะเรียกคนชอบธรรม แต่มาเรียกคนบาปให้กลับใจเสียใหม่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 14, 'แล้วพวกสาวกของยอห์นมาหาพระองค์ทูลว่า “เหตุไฉนพวกข้าพระองค์และพวกฟาริสีถืออดอาหารบ่อยๆ แต่พวกสาวกของพระองค์ไม่ถืออดอาหาร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 15, 'พระเยซูจึงตรัสกับเขาว่า “สหายของเจ้าบ่าวเป็นทุกข์โศกเศร้าเมื่อเจ้าบ่าวยังอยู่กับเขาได้หรือ แต่วันนั้นจะมาถึงเมื่อเจ้าบ่าวจะต้องจากเขาไป เมื่อนั้นเขาจะถืออดอาหาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 16, 'ไม่มีผู้ใดเอาท่อนผ้าทอใหม่มาปะเสื้อเก่า เพราะว่าผ้าที่ปะเข้านั้น เมื่อหดจะทําให้เสื้อเก่าขาดกว้างออกไปอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 17, 'และไม่มีผู้ใดเอาน้ําองุ่นใหม่มาใส่ในถุงหนังเก่า ถ้าทําอย่างนั้นถุงหนังจะขาด น้ําองุ่นจะรั่ว ทั้งถุงหนังก็จะเสียไปด้วย แต่เขาย่อมเอาน้ําองุ่นใหม่ใส่ในถุงหนังใหม่ แล้วทั้งสองอย่างก็อยู่ดีด้วยกันได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 18, 'เมื่อพระองค์กําลังตรัสคําเหล่านี้แก่เขานั้น ดูเถิด มีขุนนางคนหนึ่งมานมัสการพระองค์แล้วทูลว่า “ลูกสาวของข้าพระองค์พึ่งตาย ขอพระองค์เสด็จไปวางพระหัตถ์ของพระองค์บนตัวเขา แล้วเขาจะฟื้นขึ้นอีก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 19, 'ฝ่ายพระเยซูจึงทรงลุกขึ้นเสด็จตามเขาไป และพวกสาวกของพระองค์ก็ตามไปด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 20, 'ดูเถิด มีผู้หญิงคนหนึ่งเป็นโรคตกเลือดได้สิบสองปีมาแล้วแอบมาข้างหลัง ถูกต้องชายฉลองพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 21, 'เพราะนางคิดในใจว่า “ถ้าเราได้แตะต้องฉลองพระองค์เท่านั้น เราก็จะหายโรค”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 22, 'ฝ่ายพระเยซูทรงเหลียวหลังทอดพระเนตรเห็นนางจึงตรัสว่า “ลูกสาวเอ๋ย จงชื่นใจเถิด ความเชื่อของเจ้าทําให้เจ้าหายเป็นปกติ” นับตั้งแต่เวลานั้น ผู้หญิงนั้นก็หายป่วยเป็นปกติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 23, 'ครั้นพระเยซูเสด็จเข้าไปในเรือนของขุนนางนั้น ทอดพระเนตรเห็นพวกเป่าปี่และคนเป็นอันมากชุลมุนกันอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 24, 'พระองค์จึงตรัสกับเขาว่า “จงถอยออกไปเถิด ด้วยว่าเด็กหญิงคนนี้ยังไม่ตาย เป็นแต่นอนหลับอยู่” เขาก็พากันหัวเราะเยาะพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 25, 'แต่เมื่อทรงขับฝูงคนออกไปแล้ว พระองค์ได้เสด็จเข้าไปจับมือเด็กหญิง และเด็กหญิงนั้นก็ลุกขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 26, 'แล้วกิตติศัพท์นี้ก็ลือไปทั่วแคว้นนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 27, 'ครั้นพระเยซูเสด็จไปจากที่นั่น ก็มีชายตาบอดสองคนตามพระองค์มาร้องว่า “บุตรดาวิดเจ้าข้า ขอเมตตาข้าพระองค์ทั้งหลายเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 28, 'และเมื่อพระองค์เสด็จเข้าไปในเรือน ชายตาบอดทั้งสองก็เข้ามาหาพระองค์ พระเยซูตรัสถามเขาว่า “เจ้าเชื่อหรือว่า เราสามารถจะกระทําการนี้ได้” เขาทูลพระองค์ว่า “เชื่อ พระเจ้าข้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 29, 'แล้วพระองค์ทรงถูกต้องตาของพวกเขาตรัสว่า “ให้เป็นไปตามความเชื่อของเจ้าเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 30, 'แล้วตาของพวกเขาก็กลับเห็นดี พระเยซูได้ทรงกําชับเขาอย่างแข็งขันว่า “จงระวังอย่าให้ผู้ใดรู้เลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 31, 'แต่เมื่อเขาไปจากที่นั่นแล้ว ก็เผยแพร่กิตติศัพท์ของพระองค์ทั่วแคว้นนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 32, 'ขณะเมื่อพระเยซูและเหล่าสาวกกําลังเสด็จออกไปจากที่นั่น ดูเถิด มีผู้พาคนใบ้คนหนึ่งที่มีผีสิงอยู่มาหาพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 33, 'เมื่อทรงขับผีออกแล้วคนใบ้นั้นก็พูดได้ หมู่คนก็อัศจรรย์ใจพูดกันว่า “ไม่เคยเห็นการกระทําเช่นนี้ในอิสราเอลเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 34, 'แต่พวกฟาริสีกล่าวว่า “คนนี้ขับผีออกด้วยฤทธิ์ของนายผี”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 35, 'พระเยซูได้เสด็จดําเนินไปตามนครและหมู่บ้านโดยรอบ ทรงสั่งสอนในธรรมศาลาของเขา ประกาศข่าวประเสริฐแห่งอาณาจักรนั้น ทรงรักษาโรคและความป่วยไข้ทุกอย่างของพลเมืองให้หาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 36, 'และเมื่อพระองค์ทอดพระเนตรเห็นประชาชนก็ทรงสงสารเขา ด้วยเขาอิดโรยกระจัดกระจายไปดุจฝูงแกะไม่มีผู้เลี้ยง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 37, 'แล้วพระองค์ตรัสกับพวกสาวกของพระองค์ว่า “การเก็บเกี่ยวนั้นเป็นการใหญ่นักหนา แต่คนงานยังน้อยอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 38, 'เหตุฉะนั้น พวกท่านจงอ้อนวอนพระองค์ผู้ทรงเป็นเจ้าของการเก็บเกี่ยวนั้น ให้ส่งคนงานมาในการเก็บเกี่ยวของพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 1, 'เมื่อพระองค์ทรงเรียกสาวกสิบสองคนของพระองค์มาแล้ว พระองค์ก็ประทานอํานาจให้เขาขับผีโสโครกออกได้ และให้รักษาโรคและความเจ็บไข้ทุกอย่างให้หายได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 2, 'อัครสาวกสิบสองคนนั้นมีชื่อดังนี้ คนแรกชื่อซีโมนที่เรียกว่าเปโตร กับอันดรูว์น้องชายของเขา ยากอบบุตรชายเศเบดี กับยอห์นน้องชายของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 3, 'ฟีลิปและบารโธโลมิว โธมัสและมัทธิวคนเก็บภาษี ยากอบบุตรชายอัลเฟอัส และเลบเบอัสผู้ที่มีชื่ออีกว่าธัดเดอัส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 4, 'ซีโมนชาวคานาอันและยูดาสอิสคาริโอทผู้ที่ได้ทรยศพระองค์นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 5, 'สิบสองคนนี้พระเยซูทรงใช้ให้ออกไปและสั่งเขาว่า “อย่าไปทางที่ไปสู่พวกต่างชาติ และอย่าเข้าไปในเมืองของชาวสะมาเรีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 6, 'แต่ว่าจงไปหาแกะหลงของวงศ์วานอิสราเอลดีกว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 7, 'จงไปพลางประกาศพลางว่า ‘อาณาจักรแห่งสวรรค์มาใกล้แล้ว’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 8, 'จงรักษาคนเจ็บป่วยให้หาย คนโรคเรื้อนให้หายสะอาด คนตายแล้วให้ฟื้น และจงขับผีให้ออก ท่านทั้งหลายได้รับเปล่าๆ ก็จงให้เปล่าๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 9, 'อย่าหาเหรียญทองคํา หรือเงิน หรือทองแดงไว้ในไถ้ของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 10, 'หรือย่ามใช้ตามทาง หรือเสื้อคลุมสองตัว หรือรองเท้า หรือไม้เท้า เพราะว่าผู้ทํางานสมควรจะได้อาหารกิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 11, 'เมื่อท่านมาถึงนครใดหรือเมืองใด จงสืบดูว่าใครเป็นคนเหมาะสมในที่นั้น แล้วจงไปอาศัยกับผู้นั้นจนกว่าจะจากไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 12, 'ขณะเมื่อท่านขึ้นเรือน จงให้พรแก่ครัวเรือนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 13, 'ถ้าครัวเรือนนั้นสมควรรับพร ก็ให้สันติสุขของท่านอยู่กับเรือนนั้น แต่ถ้าครัวเรือนนั้นไม่สมควรรับพร ก็ให้สันติสุขนั้นกลับคืนมาสู่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 14, 'ถ้าผู้ใดไม่ต้อนรับท่านทั้งหลายและไม่ฟังคําของท่าน เมื่อจะออกจากเรือนนั้นเมืองนั้น จงสะบัดผงคลีที่ติดเท้าของท่านออกเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 15, 'เราบอกความจริงแก่ท่านว่า ในวันพิพากษานั้น โทษของเมืองโสโดมและเมืองโกโมราห์ จะเบากว่าโทษของเมืองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 16, 'ดูเถิด เราใช้พวกท่านไปดุจแกะอยู่ท่ามกลางฝูงสุนัขป่า เหตุฉะนั้นท่านจงฉลาดเหมือนงู และไม่มีภัยเหมือนนกเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 17, 'แต่จงระวังผู้คนไว้ให้ดี เพราะพวกเขาจะมอบท่านทั้งหลายไว้กับศาล และจะเฆี่ยนท่านในธรรมศาลาของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 18, 'และท่านจะถูกนําตัวไปอยู่ต่อหน้าเจ้าเมืองและกษัตริย์เพราะเห็นแก่เรา เพื่อท่านจะได้เป็นพยานต่อเขาและต่อคนต่างชาติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 19, 'แต่เมื่อเขามอบท่านไว้นั้น อย่าเป็นกังวลว่าจะพูดอะไรหรืออย่างไร เพราะเมื่อถึงเวลา คําที่ท่านจะพูดนั้นจะทรงประทานแก่ท่านในเวลานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 20, 'เพราะว่าผู้ที่พูดมิใช่ตัวท่านเอง แต่เป็นพระวิญญาณแห่งพระบิดาของท่าน ผู้ตรัสทางท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 21, 'แม้ว่าพี่ก็จะมอบน้องให้ถึงความตาย พ่อจะมอบลูก และลูกก็จะทรยศต่อพ่อแม่ให้ถึงแก่ความตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 22, 'ท่านจะถูกคนทั้งปวงเกลียดชังเพราะเห็นแก่นามของเรา แต่ผู้ใดที่ทนได้ถึงที่สุด ผู้นั้นจะรอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 23, 'แต่เมื่อเขาข่มเหงท่านในเมืองนี้ จงหนีไปยังอีกเมืองหนึ่ง เราบอกความจริงแก่ท่านว่า ก่อนที่ท่านจะไปทั่วเมืองต่างๆในอิสราเอล บุตรมนุษย์จะเสด็จมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 24, 'ศิษย์ไม่ใหญ่กว่าครู และทาสไม่ใหญ่กว่านายของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 25, 'ซึ่งศิษย์จะได้เป็นเสมอครูของตน และทาสเสมอนายของตนก็พออยู่แล้ว ถ้าเขาได้เรียกเจ้าบ้านว่าเบเอลเซบูล เขาจะเรียกลูกบ้านของเขามากยิ่งกว่านั้นสักเท่าใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 26, 'เหตุฉะนั้นอย่ากลัวเขา เพราะว่าไม่มีสิ่งใดปิดบังไว้ที่จะไม่ต้องเปิดเผย หรือการลับที่จะไม่เผยให้ประจักษ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 27, 'ซึ่งเรากล่าวแก่พวกท่านในที่มืด ท่านจงกล่าวในที่สว่าง และซึ่งท่านได้ยินกระซิบที่หู ท่านจงประกาศจากดาดฟ้าหลังคาบ้าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 28, 'อย่ากลัวผู้ที่ฆ่าได้แต่กาย แต่ไม่มีอํานาจที่จะฆ่าจิตวิญญาณ แต่จงกลัวพระองค์ผู้ทรงฤทธิ์ที่จะให้ทั้งจิตวิญญาณทั้งกายพินาศในนรกได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 29, 'นกกระจอกสองตัวเขาขายบาทหนึ่งมิใช่หรือ แต่ถ้าพระบิดาของท่านไม่ทรงเห็นชอบ นกนั้นแม้สักตัวเดียวจะตกลงถึงดินก็ไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 30, 'ถึงผมของท่านทั้งหลายก็ทรงนับไว้แล้วทุกเส้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 31, 'เหตุฉะนั้นอย่ากลัวเลย ท่านทั้งหลายก็มีค่ากว่านกกระจอกหลายตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 32, 'เหตุดังนั้นผู้ใดจะรับเราต่อหน้ามนุษย์ เราจะรับผู้นั้นต่อพระพักตร์พระบิดาของเราผู้ทรงสถิตในสวรรค์ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 33, 'แต่ผู้ใดจะปฏิเสธเราต่อหน้ามนุษย์ เราจะปฏิเสธผู้นั้นต่อพระพักตร์พระบิดาของเราผู้ทรงสถิตในสวรรค์ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 34, 'อย่าคิดว่าเรามาเพื่อจะนําสันติภาพมาสู่โลก เรามิได้นําสันติภาพมาให้ แต่เรานําดาบมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 35, 'ด้วยว่าเรามาเพื่อจะให้ลูกชายหมางใจกับบิดาของตน และลูกสาวหมางใจกับมารดาและลูกสะใภ้หมางใจกับแม่สามี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 36, 'และผู้ที่อยู่ร่วมเรือนเดียวกัน ก็จะเป็นศัตรูต่อกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 37, 'ผู้ใดที่รักบิดามารดายิ่งกว่ารักเราก็ไม่สมกับเรา และผู้ใดรักบุตรชายหญิงยิ่งกว่ารักเรา ผู้นั้นก็ไม่สมกับเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 38, 'และผู้ใดที่ไม่รับเอากางเขนของตนตามเราไป ผู้นั้นก็ไม่สมกับเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 39, 'ผู้ที่จะเอาชีวิตของตนรอดจะกลับเสียชีวิต แต่ผู้ที่สู้เสียชีวิตของตนเพราะเห็นแก่เราก็จะได้ชีวิตรอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 40, 'ผู้ที่รับท่านทั้งหลายก็รับเรา และผู้ที่รับเราก็รับพระองค์ที่ทรงใช้เรามา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 41, 'ผู้ที่รับศาสดาพยากรณ์เพราะนามแห่งศาสดาพยากรณ์นั้น ก็จะได้บําเหน็จอย่างที่ศาสดาพยากรณ์พึงได้รับ และผู้ที่รับผู้ชอบธรรมเพราะนามแห่งผู้ชอบธรรมนั้น ก็จะได้บําเหน็จอย่างที่ผู้ชอบธรรมพึงได้รับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 42, 'และผู้ใดจะเอาน้ําเย็นสักถ้วยหนึ่งให้คนเล็กน้อยเหล่านี้คนใดคนหนึ่งดื่ม เพราะนามแห่งศิษย์ของเรา เราบอกความจริงแก่ท่านทั้งหลายว่า คนนั้นจะขาดบําเหน็จก็หามิได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 1, 'ต่อมาเมื่อพระเยซูตรัสสั่งสาวกสิบสองคนของพระองค์เสร็จแล้ว พระองค์ได้เสด็จจากที่นั่นไปเพื่อจะสั่งสอนและประกาศในเมืองต่างๆของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 2, 'ฝ่ายยอห์นเมื่อติดอยู่ในเรือนจําได้ยินถึงกิจการของพระคริสต์ จึงได้ใช้สาวกสองคนของท่านไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 3, 'ทูลถามพระองค์ว่า “ท่านเป็นผู้ที่จะมานั้นหรือ หรือเราจะต้องคอยหาผู้อื่น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 4, 'ฝ่ายพระเยซูตรัสตอบพวกเขาว่า “จงไปแจ้งแก่ยอห์นอีกครั้งถึงสิ่งที่ท่านได้ยินและได้เห็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 5, 'คือว่าคนตาบอดก็หายบอด คนง่อยเดินได้ คนโรคเรื้อนหายสะอาด คนหูหนวกได้ยินได้ คนตายแล้วเป็นขึ้นมา และข่าวประเสริฐก็ประกาศแก่คนอนาถา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 6, 'บุคคลผู้ใดไม่สะดุดเพราะเรา ผู้นั้นเป็นสุข”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 7, 'ครั้นสาวกเหล่านั้นไปแล้ว พระเยซูเริ่มตรัสกับคนหมู่นั้นถึงยอห์นว่า “ท่านทั้งหลายได้ออกไปในถิ่นทุรกันดารเพื่อดูอะไร ดูต้นอ้อไหวโดยถูกลมพัดหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 8, 'แต่ท่านทั้งหลายออกไปดูอะไร ดูคนนุ่งห่มผ้าเนื้ออ่อนนิ่มหรือ ดูเถิด คนนุ่งห่มผ้าเนื้อนิ่มก็อยู่ในพระนิเวศของกษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 9, 'แต่ท่านทั้งหลายออกไปดูอะไร ดูศาสดาพยากรณ์หรือ แน่ทีเดียว และเราบอกท่านว่า ท่านนั้นเป็นยิ่งกว่าศาสดาพยากรณ์เสียอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 10, 'คือผู้นั้นเองที่ได้เขียนถึงแล้วว่า ‘ดูเถิด เราใช้ทูตของเราไปข้างหน้าท่าน ผู้นั้นจะเตรียมทางของท่านไว้ข้างหน้าท่าน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 11, 'เราบอกความจริงแก่ท่านทั้งหลายว่า ในบรรดาคนซึ่งเกิดจากผู้หญิงมานั้น ไม่มีผู้ใดใหญ่กว่ายอห์นผู้ให้รับบัพติศมา แต่ว่าผู้ที่ต่ําต้อยที่สุดในอาณาจักรแห่งสวรรค์ก็ยังใหญ่กว่ายอห์นเสียอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 12, 'และตั้งแต่สมัยยอห์นผู้ให้รับบัพติศมาถึงทุกวันนี้ อาณาจักรแห่งสวรรค์ก็เป็นสิ่งที่คนได้แสวงหาด้วยใจร้อนรน และผู้ที่ใจร้อนรนก็เป็นผู้ที่ชิงเอาได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 13, 'เพราะคําของศาสดาพยากรณ์ทั้งหลายและพระราชบัญญัติได้พยากรณ์มาจนถึงยอห์นนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 14, 'ถ้าท่านทั้งหลายจะยอมรับในเรื่องนี้ ก็ยอห์นนี้แหละเป็นเอลียาห์ซึ่งจะมานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 15, 'ใครมีหูจงฟังเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 16, 'เราจะเปรียบคนยุคนี้เหมือนกับอะไรดี เปรียบเหมือนเด็กนั่งที่กลางตลาดร้องแก่เพื่อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 17, 'กล่าวว่า ‘พวกฉันได้เป่าปี่ให้พวกเธอ และเธอมิได้เต้นรํา พวกฉันได้พิลาปร่ําไห้แก่พวกเธอ และพวกเธอมิได้คร่ําครวญ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 18, 'ด้วยว่ายอห์นมาก็ไม่ได้กินหรือดื่ม และเขาว่า ‘มีผีเข้าสิงอยู่’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 19, 'ฝ่ายบุตรมนุษย์มาทั้งกินและดื่ม เขาก็ว่า ‘ดูเถิด นี่เป็นคนกินเติบและดื่มน้ําองุ่นมาก เป็นมิตรสหายกับคนเก็บภาษีและคนบาป’ แต่พระปัญญาก็ปรากฏว่าชอบธรรมแล้วโดยผลแห่งพระปัญญานั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 20, 'แล้วพระองค์ก็ทรงตั้งต้นติเตียนเมืองต่างๆที่พระองค์ได้ทรงกระทําการอิทธิฤทธิ์เป็นส่วนมาก เพราะเขามิได้กลับใจเสียใหม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 21, '“วิบัติแก่เจ้า เมืองโคราซิน วิบัติแก่เจ้า เมืองเบธไซดา เพราะถ้าการอิทธิฤทธิ์ซึ่งได้กระทําท่ามกลางเจ้าได้กระทําในเมืองไทระและเมืองไซดอน คนในเมืองทั้งสองจะได้นุ่งห่มผ้ากระสอบ นั่งบนขี้เถ้า กลับใจเสียใหม่นานมาแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 22, 'แต่เราบอกเจ้าว่า ในวันพิพากษา โทษเมืองไทระและเมืองไซดอนจะเบากว่าโทษของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 23, 'และฝ่ายเจ้า เมืองคาเปอรนาอุม ซึ่งถูกยกขึ้นเทียมฟ้าแล้ว เจ้าจะต้องลงไปถึงนรกต่างหาก ด้วยว่าการอิทธิฤทธิ์ซึ่งได้กระทําในท่ามกลางเจ้านั้น ถ้าได้กระทําในเมืองโสโดม เมืองนั้นจะได้ตั้งอยู่จนทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 24, 'แต่เราบอกเจ้าว่า ในวันพิพากษา โทษเมืองโสโดมจะเบากว่าโทษของเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 25, 'ขณะนั้นพระเยซูทูลตอบว่า “โอ ข้าแต่พระบิดา ผู้เป็นเจ้าแห่งฟ้าสวรรค์และแผ่นดิน ข้าพระองค์ขอขอบพระคุณพระองค์ ที่พระองค์ได้ทรงปิดบังสิ่งเหล่านี้ไว้จากผู้มีปัญญาและผู้ฉลาด และได้สําแดงให้ผู้น้อยรู้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 26, 'ข้าแต่พระบิดา ที่เป็นอย่างนั้นก็เพราะเป็นที่ชอบพระทัยในสายพระเนตรของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 27, 'พระบิดาของเราได้ทรงมอบสิ่งสารพัดให้แก่เรา และไม่มีใครรู้จักพระบุตรนอกจากพระบิดา และไม่มีใครรู้จักพระบิดานอกจากพระบุตรและผู้ใดก็ตามที่พระบุตรประสงค์จะสําแดงให้รู้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 28, 'บรรดาผู้ทํางานเหน็ดเหนื่อยและแบกภาระหนัก จงมาหาเรา และเราจะให้ท่านทั้งหลายหายเหนื่อยเป็นสุข');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 29, 'จงเอาแอกของเราแบกไว้ แล้วเรียนจากเรา เพราะว่าเรามีใจอ่อนสุภาพและถ่อมลง และท่านทั้งหลายจะพบที่สงบสุขในใจของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 30, 'ด้วยว่าแอกของเราก็แบกง่าย และภาระของเราก็เบา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 1, 'ในคราวนั้นพระเยซูเสด็จไปในนาในวันสะบาโต และพวกสาวกของพระองค์หิวจึงเริ่มเด็ดรวงข้าวมากิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 2, 'แต่เมื่อพวกฟาริสีเห็นเข้า เขาจึงทูลพระองค์ว่า “ดูเถิด สาวกของท่านทําการซึ่งพระราชบัญญัติห้ามไว้ในวันสะบาโต”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 3, 'พระองค์จึงตรัสกับเขาว่า “พวกท่านยังไม่ได้อ่านหรือ ซึ่งดาวิดได้กระทําเมื่อท่านและพรรคพวกหิว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 4, 'ท่านได้เข้าไปในพระนิเวศของพระเจ้า รับประทานขนมปังหน้าพระพักตร์ ซึ่งพระราชบัญญัติห้ามไว้ไม่ให้ท่านและพรรคพวกรับประทาน ควรแต่ปุโรหิตพวกเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 5, 'ท่านทั้งหลายไม่ได้อ่านในพระราชบัญญัติหรือ ที่ว่า ในวันสะบาโตพวกปุโรหิตในพระวิหารดูหมิ่นวันสะบาโตแต่ไม่มีความผิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 6, 'แต่เราบอกท่านทั้งหลายว่า ที่นี่มีผู้หนึ่งเป็นใหญ่กว่าพระวิหารอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 7, 'แต่ถ้าท่านทั้งหลายได้เข้าใจความหมายของข้อที่ว่า ‘เราประสงค์ความเมตตา ไม่ประสงค์เครื่องสัตวบูชา’ ท่านก็คงจะไม่กล่าวโทษคนที่ไม่มีความผิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 8, 'เพราะว่าบุตรมนุษย์เป็นเจ้าเป็นใหญ่เหนือแม้แต่วันสะบาโต”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 9, 'แล้วเมื่อพระองค์ได้เสด็จไปจากที่นั่น พระองค์ก็เข้าไปในธรรมศาลาของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 10, 'ดูเถิด มีชายคนหนึ่งมือข้างหนึ่งลีบ คนทั้งหลายถามพระองค์ว่า “การรักษาโรคในวันสะบาโตนั้นพระราชบัญญัติห้ามไว้หรือไม่” เพื่อเขาจะหาเหตุฟ้องพระองค์ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 11, 'พระองค์จึงตรัสกับเขาว่า “ถ้าผู้ใดในพวกท่านมีแกะตัวเดียวและแกะตัวนั้นตกบ่อในวันสะบาโต ผู้นั้นจะไม่ฉุดลากแกะตัวนั้นขึ้นหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 12, 'มนุษย์คนหนึ่งย่อมประเสริฐยิ่งกว่าแกะมากเท่าใด เหตุฉะนั้นจึงถูกต้องตามพระราชบัญญัติให้ทําการดีได้ในวันสะบาโต”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 13, 'แล้วพระองค์ก็ตรัสกับชายคนนั้นว่า “จงเหยียดมือออกเถิด” เขาก็เหยียดออก และมือนั้นก็หายเป็นปกติเหมือนมืออีกข้างหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 14, 'ฝ่ายพวกฟาริสีก็ออกไปปรึกษากันถึงพระองค์ว่า จะทําอย่างไรจึงจะฆ่าพระองค์ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 15, 'แต่เมื่อพระเยซูทรงทราบ พระองค์จึงได้เสด็จออกไปจากที่นั่น และคนเป็นอันมากก็ตามพระองค์ไป พระองค์ก็ทรงรักษาเขาให้หายโรคสิ้นทุกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 16, 'แล้วพระองค์ทรงกําชับห้ามเขามิให้แพร่งพรายว่าพระองค์คือผู้ใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 17, 'ทั้งนี้เพื่อคําที่ได้กล่าวไว้แล้วโดยอิสยาห์ศาสดาพยากรณ์จะสําเร็จ ซึ่งว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 18, '‘ดูเถิด ผู้รับใช้ของเราซึ่งเราได้เลือกสรรไว้ ที่รักของเรา ผู้ซึ่งจิตใจเราโปรดปราน เราจะเอาวิญญาณของเราสวมท่านไว้ ท่านจะประกาศการพิพากษาแก่พวกต่างชาติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 19, 'ท่านจะไม่ทะเลาะวิวาท และไม่ร้องเสียงดัง ไม่มีใครได้ยินเสียงของท่านตามถนน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 20, 'ไม้อ้อช้ําแล้วท่านจะไม่หัก ไส้ตะเกียงเป็นควันแล้วท่านจะไม่ดับ กว่าท่านจะทําให้การพิพากษามีชัยชนะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 21, 'และพวกต่างชาติจะวางใจในนามของท่าน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 22, 'ขณะนั้นเขาพาคนหนึ่งมีผีเข้าสิงอยู่ ทั้งตาบอดและเป็นใบ้มาหาพระองค์ พระองค์ทรงรักษาให้หาย คนตาบอดและใบ้นั้นจึงพูดจึงเห็นได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 23, 'และคนทั้งปวงก็อัศจรรย์ใจถามกันว่า “คนนี้เป็นบุตรของดาวิดมิใช่หรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 24, 'แต่พวกฟาริสีเมื่อได้ยินดังนั้นก็พูดกันว่า “ผู้นี้ขับผีออกได้ก็เพราะใช้อํานาจเบเอลเซบูลผู้เป็นนายผีนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 25, 'ฝ่ายพระเยซูทรงทราบความคิดของเขา จึงตรัสกับเขาว่า “ราชอาณาจักรใดๆซึ่งแตกแยกกันเองก็จะรกร้างไป เมืองใดๆหรือครัวเรือนใดๆซึ่งแตกแยกกันเองจะตั้งอยู่ไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 26, 'และถ้าซาตานขับซาตานออก มันก็แตกแยกกันในตัวมันเอง แล้วอาณาจักรของมันจะตั้งอยู่อย่างไรได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 27, 'และถ้าเราขับผีออกโดยเบเอลเซบูล พวกพ้องของท่านทั้งหลายขับมันออกโดยอํานาจของใครเล่า เหตุฉะนั้นพวกพ้องของท่านเองจะเป็นผู้ตัดสินกล่าวโทษพวกท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 28, 'แต่ถ้าเราขับผีออกด้วยพระวิญญาณของพระเจ้า อาณาจักรของพระเจ้าก็มาถึงท่านแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 29, 'หรือใครจะเข้าไปในเรือนของคนที่มีกําลังมากและปล้นเอาทรัพย์ของเขาอย่างไรได้ เว้นแต่จะจับคนที่มีกําลังมากนั้นมัดไว้เสียก่อน แล้วจึงจะปล้นทรัพย์ในเรือนนั้นได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 30, 'ผู้ที่ไม่อยู่ฝ่ายเราก็เป็นปฏิปักษ์ต่อเรา และผู้ที่ไม่รวบรวมไว้กับเราก็เป็นผู้กระทําให้กระจัดกระจายไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 31, 'เพราะฉะนั้น เราบอกท่านทั้งหลายว่า ความผิดบาปและคําหมิ่นประมาททุกอย่างจะโปรดยกให้มนุษย์ได้ เว้นแต่คําหมิ่นประมาทพระวิญญาณบริสุทธิ์จะทรงโปรดยกให้มนุษย์ไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 32, 'ผู้ใดจะกล่าวร้ายบุตรมนุษย์จะโปรดยกให้ผู้นั้นได้ แต่ผู้ใดจะกล่าวร้ายพระวิญญาณบริสุทธิ์ จะทรงโปรดยกให้ผู้นั้นไม่ได้ทั้งโลกนี้โลกหน้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 33, 'จงกระทําให้ต้นไม้ดีแล้วผลของต้นไม้นั้นดี หรือกระทําให้ต้นไม้เลวแล้วผลของต้นไม้นั้นเลว เพราะเราจะรู้จักต้นไม้ด้วยผลของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 34, 'โอ ชาติงูร้าย เจ้าเป็นคนชั่วแล้วจะพูดความดีได้อย่างไร ด้วยว่าปากย่อมพูดจากสิ่งที่เต็มอยู่ในใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 35, 'คนดีก็เอาของดีมาจากคลังดีแห่งใจนั้น คนชั่วก็เอาของชั่วมาจากคลังชั่ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 36, 'ฝ่ายเราบอกเจ้าทั้งหลายว่า คําที่ไม่เป็นสาระทุกคําซึ่งมนุษย์พูดนั้น มนุษย์จะต้องให้การสําหรับถ้อยคําเหล่านั้นในวันพิพากษา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 37, 'เหตุว่าที่เจ้าจะพ้นโทษได้ หรือจะต้องถูกปรับโทษนั้น ก็เพราะวาจาของเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 38, 'คราวนั้นมีบางคนในพวกธรรมาจารย์และพวกฟาริสีทูลว่า “อาจารย์เจ้าข้า พวกข้าพเจ้าอยากจะเห็นหมายสําคัญจากท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 39, 'พระองค์จึงตรัสตอบเขาว่า “คนชาติชั่วและเล่นชู้แสวงหาหมายสําคัญ และจะไม่ทรงโปรดให้หมายสําคัญแก่เขา เว้นไว้แต่หมายสําคัญของโยนาห์ศาสดาพยากรณ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 40, 'ด้วยว่า ‘โยนาห์ได้อยู่ในท้องปลาวาฬสามวันสามคืน’ ฉันใด บุตรมนุษย์จะอยู่ในท้องแผ่นดินสามวันสามคืนฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 41, 'ชนชาวนีนะเวห์จะลุกขึ้นในวันพิพากษาพร้อมกับคนยุคนี้ และจะกล่าวโทษเขา ด้วยว่าชาวนีนะเวห์ได้กลับใจเสียใหม่เพราะคําประกาศของโยนาห์ และดูเถิด ผู้เป็นใหญ่กว่าโยนาห์อยู่ที่นี่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 42, 'นางกษัตริย์ฝ่ายทิศใต้จะลุกขึ้นในวันพิพากษาพร้อมกับคนยุคนี้ และจะกล่าวโทษเขา ด้วยว่าพระนางนั้นได้มาจากที่สุดปลายแผ่นดินโลกเพื่อจะฟังสติปัญญาของซาโลมอน และดูเถิด ผู้เป็นใหญ่กว่าซาโลมอนก็อยู่ที่นี่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 43, 'เมื่อผีโสโครกออกมาจากผู้ใดแล้ว มันก็ท่องเที่ยวไปในที่กันดาร เพื่อแสวงหาที่หยุดพักแต่ไม่พบเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 44, 'แล้วมันก็กล่าวว่า ‘ข้าจะกลับไปยังเรือนของข้าที่ข้าได้ออกมานั้น’ และเมื่อมันมาถึงก็เห็นเรือนนั้นว่าง กวาดและตกแต่งไว้แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 45, 'มันจึงไปรับเอาผีอื่นอีกเจ็ดผีร้ายกว่ามันเอง แล้วก็เข้าไปอาศัยที่นั่น และในที่สุดคนนั้นก็ตกที่นั่งร้ายกว่าตอนแรก คนชาติชั่วนี้ก็จะเป็นอย่างนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 46, 'ขณะที่พระองค์ยังตรัสกับประชาชนอยู่นั้น ดูเถิด มารดาและพวกน้องชายของพระองค์พากันมายืนอยู่ภายนอกประสงค์จะสนทนากับพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 47, 'แล้วมีคนหนึ่งทูลพระองค์ว่า “ดูเถิด มารดาและพวกน้องชายของพระองค์ยืนอยู่ข้างนอกประสงค์จะสนทนากับพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 48, 'แต่พระองค์ตรัสตอบผู้ที่ทูลพระองค์นั้นว่า “ใครเป็นมารดาของเรา ใครเป็นพี่น้องของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 49, 'พระองค์ทรงเหยียดพระหัตถ์ไปทางพวกสาวกของพระองค์ และตรัสว่า “ดูเถิด นี่เป็นมารดาและพี่น้องของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 50, 'ด้วยว่าผู้ใดจะกระทําตามพระทัยพระบิดาของเราผู้ทรงสถิตในสวรรค์ ผู้นั้นแหละเป็นพี่น้องชายหญิงและมารดาของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 1, 'ในวันนั้นเองพระเยซูได้เสด็จจากเรือนไปประทับที่ชายทะเล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 2, 'มีคนพากันมาหาพระองค์มากนัก พระองค์จึงเสด็จลงไปประทับในเรือ และบรรดาคนเหล่านั้นก็ยืนอยู่บนฝั่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 3, 'แล้วพระองค์ก็ตรัสกับเขาหลายประการเป็นคําอุปมาว่า “ดูเถิด มีผู้หว่านคนหนึ่งออกไปหว่านพืช');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 4, 'และเมื่อเขาหว่าน เมล็ดพืชก็ตกตามหนทางบ้าง แล้วนกก็มากินเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 5, 'บ้างก็ตกในที่ซึ่งมีพื้นหิน มีเนื้อดินแต่น้อย จึงงอกขึ้นโดยเร็วเพราะดินไม่ลึก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 6, 'แต่เมื่อแดดจัดแดดก็แผดเผา เพราะรากไม่มีจึงเหี่ยวไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 7, 'บ้างก็ตกกลางต้นหนาม ต้นหนามก็งอกขึ้นปกคลุมเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 8, 'บ้างก็ตกที่ดินดี แล้วเกิดผล ร้อยเท่าบ้าง หกสิบเท่าบ้าง สามสิบเท่าบ้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 9, 'ใครมีหูจงฟังเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 10, 'ฝ่ายพวกสาวกจึงมาทูลพระองค์ว่า “เหตุไฉนพระองค์ตรัสกับเขาเป็นคําอุปมา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 11, 'พระองค์ตรัสตอบเขาว่า “เพราะว่าข้อความลึกลับของอาณาจักรแห่งสวรรค์ทรงโปรดให้ท่านทั้งหลายรู้ได้ แต่คนเหล่านั้นไม่โปรดให้รู้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 12, 'ด้วยว่าผู้ใดมีอยู่แล้ว จะเพิ่มเติมให้คนนั้นมีเหลือเฟือ แต่ผู้ใดที่ไม่มีนั้น แม้ว่าซึ่งเขามีอยู่จะต้องเอาไปจากเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 13, 'เหตุฉะนั้น เราจึงกล่าวแก่เขาเป็นคําอุปมา เพราะว่าถึงเขาเห็นก็เหมือนไม่เห็น ถึงได้ยินก็เหมือนไม่ได้ยินและไม่เข้าใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 14, 'คําพยากรณ์ของอิสยาห์ก็สําเร็จในคนเหล่านั้นที่ว่า ‘พวกเจ้าจะได้ยินก็จริง แต่จะไม่เข้าใจ จะดูก็จริง แต่จะไม่รับรู้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 15, 'เพราะว่าชนชาตินี้กลายเป็นคนมีใจเฉื่อยชา หูก็ตึง และตาของเขาเขาก็ปิด เกรงว่าในเวลาใดเขาจะเห็นด้วยตาของเขา และได้ยินด้วยหูของเขา และเข้าใจด้วยจิตใจของเขา และจะหันกลับมา และเราจะได้รักษาเขาให้หาย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 16, 'แต่ตาของท่านทั้งหลายก็เป็นสุขเพราะได้เห็น และหูของท่านก็เป็นสุขเพราะได้ยิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 17, 'เราบอกความจริงแก่ท่านทั้งหลายว่า ศาสดาพยากรณ์และผู้ชอบธรรมเป็นอันมากได้ปรารถนาจะเห็นซึ่งท่านทั้งหลายเห็นอยู่นี้ แต่เขามิเคยได้เห็น และอยากจะได้ยินซึ่งท่านทั้งหลายได้ยิน แต่เขาก็มิเคยได้ยิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 18, 'เหตุฉะนั้น ท่านทั้งหลายจงฟังคําอุปมาว่าด้วยผู้หว่านพืชนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 19, 'เมื่อผู้ใดได้ยินพระวจนะแห่งอาณาจักรนั้นแต่ไม่เข้าใจ มารร้ายก็มาฉวยเอาพืชซึ่งหว่านในใจเขานั้นไปเสีย นั่นแหละได้แก่ผู้ซึ่งรับเมล็ดริมหนทาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 20, 'และผู้ที่รับเมล็ดซึ่งตกในที่ดินซึ่งมีพื้นหินนั้น ได้แก่บุคคลที่ได้ยินพระวจนะ แล้วก็รับทันทีด้วยความปรีดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 21, 'แต่ไม่มีรากในตัวเองจึงทนอยู่ชั่วคราว และเมื่อเกิดการยากลําบากหรือการข่มเหงต่างๆเพราะพระวจนะนั้น ต่อมาเขาก็เลิกเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 22, 'ผู้ที่รับเมล็ดซึ่งตกกลางหนามนั้น ได้แก่บุคคลที่ได้ฟังพระวจนะ แล้วความกังวลตามธรรมดาโลก และการล่อลวงแห่งทรัพย์สมบัติก็รัดพระวจนะนั้นเสีย และเขาจึงไม่เกิดผล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 23, 'ส่วนผู้ที่รับเมล็ดซึ่งตกในดินดีนั้น ได้แก่บุคคลที่ได้ยินพระวจนะและเข้าใจ คนนั้นก็เกิดผลร้อยเท่าบ้าง หกสิบเท่าบ้าง สามสิบเท่าบ้าง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 24, 'พระองค์ตรัสคําอุปมาอีกข้อหนึ่งให้เขาทั้งหลายฟังว่า “อาณาจักรแห่งสวรรค์เปรียบเหมือนชายคนหนึ่งได้หว่านพืชดีในนาของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 25, 'แต่เมื่อคนทั้งหลายนอนหลับอยู่ ศัตรูของคนนั้นมาหว่านข้าวละมานปนกับข้าวสาลีนั้นไว้ แล้วก็หลบไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 26, 'ครั้นต้นข้าวนั้นงอกขึ้นออกรวงแล้ว ข้าวละมานก็ปรากฏขึ้นด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 27, 'พวกผู้รับใช้แห่งเจ้าบ้านจึงมาแจ้งแก่นายว่า ‘นายเจ้าข้า ท่านได้หว่านพืชดีในนาของท่านมิใช่หรือ แต่มีข้าวละมานมาจากไหน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 28, 'นายก็ตอบพวกเขาว่า ‘นี้เป็นการกระทําของศัตรู’ พวกผู้รับใช้จึงถามนายว่า ‘ท่านปรารถนาจะให้พวกเราไปถอนและเก็บข้าวละมานหรือ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 29, 'แต่นายตอบว่า ‘อย่าเลย เกลือกว่าเมื่อกําลังถอนข้าวละมานจะถอนข้าวสาลีด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 30, 'ให้ทั้งสองจําเริญไปด้วยกันจนถึงฤดูเกี่ยว และในเวลาเกี่ยวนั้นเราจะสั่งผู้เกี่ยวว่า “จงเก็บข้าวละมานก่อนมัดเป็นฟ่อนเผาไฟเสีย แต่ข้าวสาลีนั้นจงเก็บไว้ในยุ้งฉางของเรา”’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 31, 'พระองค์ยังตรัสคําอุปมาอีกข้อหนึ่งให้เขาฟังว่า “อาณาจักรแห่งสวรรค์เปรียบเหมือนเมล็ดมัสตาร์ดเมล็ดหนึ่ง ซึ่งชายคนหนึ่งเอาไปเพาะลงในไร่ของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 32, 'เมล็ดนั้นที่จริงก็เล็กกว่าเมล็ดทั้งปวง แต่เมื่องอกขึ้นแล้วก็ใหญ่ที่สุดท่ามกลางผักทั้งหลาย และจําเริญเป็นต้นไม้จนนกในอากาศมาทํารังอาศัยอยู่ตามกิ่งก้านของต้นนั้นได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 33, 'พระองค์ยังตรัสคําอุปมาให้เขาฟังอีกข้อหนึ่งว่า “อาณาจักรแห่งสวรรค์เปรียบเหมือนเชื้อ ซึ่งผู้หญิงคนหนึ่งเอามาเจือลงในแป้งสามถัง จนแป้งนั้นฟูขึ้นทั้งหมด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 34, 'ข้อความเหล่านี้ทั้งสิ้น พระเยซูตรัสกับหมู่ชนเป็นคําอุปมา และนอกจากคําอุปมา พระองค์มิได้ตรัสกับเขาเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 35, 'ทั้งนี้เพื่อจะให้สําเร็จตามพระวจนะที่ตรัสโดยศาสดาพยากรณ์ว่า ‘เราจะอ้าปากกล่าวคําอุปมา เราจะกล่าวข้อความซึ่งปิดซ่อนไว้ตั้งแต่เดิมสร้างโลก’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 36, 'แล้วพระเยซูจึงทรงให้ฝูงชนเหล่านั้นจากไปและเสด็จเข้าไปในเรือน พวกสาวกของพระองค์ก็มาเฝ้าพระองค์ทูลว่า “ขอพระองค์ทรงโปรดอธิบายให้พวกข้าพระองค์เข้าใจคําอุปมาที่ว่าด้วยข้าวละมานในนานั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 37, 'พระองค์ตรัสตอบเขาว่า “ผู้หว่านเมล็ดพืชดีนั้นได้แก่บุตรมนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 38, 'นานั้นได้แก่โลก ส่วนเมล็ดพืชดีได้แก่ลูกหลานแห่งอาณาจักร แต่ข้าวละมานได้แก่ลูกหลานของมารร้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 39, 'ศัตรูผู้หว่านข้าวละมานได้แก่พญามาร ฤดูเกี่ยวได้แก่การสิ้นสุดของโลกนี้ และผู้เกี่ยวนั้นได้แก่พวกทูตสวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 40, 'เหตุฉะนั้น เขาเก็บข้าวละมานเผาไฟเสียอย่างไร ในการสิ้นสุดของโลกนี้ก็จะเป็นอย่างนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 41, 'บุตรมนุษย์จะใช้พวกทูตสวรรค์ของท่านออกไปเก็บกวาดทุกสิ่งที่ทําให้หลงผิด และบรรดาผู้ที่ทําความชั่วช้าไปจากอาณาจักรของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 42, 'และจะทิ้งลงในเตาไฟอันลุกโพลง ที่นั่นจะมีการร้องไห้ขบเขี้ยวเคี้ยวฟัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 43, 'คราวนั้นผู้ชอบธรรมจะส่องแสงอยู่ในอาณาจักรพระบิดาของเขาดุจดวงอาทิตย์ ใครมีหูจงฟังเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 44, 'อีกประการหนึ่ง อาณาจักรแห่งสวรรค์เปรียบเหมือนขุมทรัพย์ซ่อนไว้ในทุ่งนา เมื่อมีผู้ใดพบแล้วก็กลับซ่อนเสียอีก และเพราะความปรีดีจึงไปขายสรรพสิ่งซึ่งเขามีอยู่ แล้วไปซื้อทุ่งนานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 45, 'อีกประการหนึ่ง อาณาจักรแห่งสวรรค์เปรียบเหมือนพ่อค้าที่ไปหาไข่มุกอย่างดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 46, 'ซึ่งเมื่อได้พบไข่มุกเม็ดหนึ่งมีค่ามาก ก็ไปขายสิ่งสารพัดซึ่งเขามีอยู่ ไปซื้อไข่มุกนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 47, 'อีกประการหนึ่ง อาณาจักรแห่งสวรรค์เปรียบเหมือนอวนที่ลากอยู่ในทะเล ติดปลารวมทุกชนิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 48, 'ซึ่งเมื่อเต็มแล้วเขาก็ลากขึ้นฝั่งนั่งเลือกเอาแต่ที่ดีใส่ในภาชนะ แต่ที่ไม่ดีนั้นก็ทิ้งเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 49, 'ในการสิ้นสุดของโลกก็จะเป็นอย่างนั้นแหละ พวกทูตสวรรค์จะออกมาแยกคนชั่วออกจากคนชอบธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 50, 'แล้วจะทิ้งลงในเตาไฟอันลุกโพลง ที่นั่นจะมีการร้องไห้ขบเขี้ยวเคี้ยวฟัน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 51, 'พระเยซูตรัสกับเขาว่า “ข้อความเหล่านี้ท่านทั้งหลายเข้าใจแล้วหรือ” เขาทูลตอบพระองค์ว่า “เข้าใจ พระเจ้าข้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 52, 'ฝ่ายพระองค์ตรัสกับเขาว่า “เพราะฉะนั้นพวกธรรมาจารย์ทุกคนที่ได้รับการสั่งสอนถึงอาณาจักรแห่งสวรรค์แล้ว ก็เป็นเหมือนเจ้าของบ้านที่เอาทั้งของใหม่และของเก่าออกจากคลังของตน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 53, 'ต่อมาเมื่อพระเยซูได้ตรัสคําอุปมาเหล่านี้เสร็จแล้ว พระองค์ก็เสด็จไปจากที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 54, 'เมื่อพระองค์เสด็จมาถึงบ้านเมืองของพระองค์แล้ว พระองค์ก็สั่งสอนในธรรมศาลาของเขา จนคนทั้งหลายประหลาดใจแล้วพูดกันว่า “คนนี้มีสติปัญญาและการอิทธิฤทธิ์อย่างนี้มาจากไหน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 55, 'คนนี้เป็นลูกช่างไม้มิใช่หรือ มารดาของเขาชื่อมารีย์มิใช่หรือ และน้องชายของเขาชื่อยากอบ โยเสส ซีโมน และยูดาสมิใช่หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 56, 'และน้องสาวทั้งหลายของเขาก็อยู่กับเรามิใช่หรือ เขาได้สิ่งทั้งปวงเหล่านี้มาจากไหน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 57, 'เขาทั้งหลายจึงหมางใจในพระองค์ ฝ่ายพระเยซูตรัสกับเขาว่า “ศาสดาพยากรณ์จะไม่ขาดความนับถือ เว้นแต่ในบ้านเมืองของตน และในครัวเรือนของตน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 58, 'พระองค์จึงมิได้ทรงกระทําการอิทธิฤทธิ์มากที่นั่น เพราะเขาไม่มีความเชื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 1, 'ครั้งนั้นเฮโรดเจ้าเมืองได้ยินกิตติศัพท์ของพระเยซู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 2, 'จึงกล่าวแก่พวกคนใช้ของท่านว่า “ผู้นี้แหละเป็นยอห์นผู้ให้รับบัพติศมา ท่านได้เป็นขึ้นมาจากความตายแล้ว เหตุฉะนั้นท่านจึงกระทําการอิทธิฤทธิ์ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 3, 'ด้วยว่าเฮโรดได้จับยอห์นมัดแล้วขังคุกไว้ เพราะเห็นแก่นางเฮโรเดียสภรรยาของฟีลิปน้องชายของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 4, 'เพราะยอห์นเคยทูลท่านว่า “ท่านผิดพระราชบัญญัติที่รับนางมาเป็นภรรยา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 5, 'ถึงเฮโรดอยากจะฆ่ายอห์นก็กลัวประชาชน ด้วยว่าเขาทั้งหลายนับถือยอห์นว่าเป็นศาสดาพยากรณ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 6, 'แต่เมื่อวันฉลองวันกําเนิดของเฮโรดมาถึง บุตรสาวนางเฮโรเดียสก็เต้นรําต่อหน้าเขาทั้งหลาย ทําให้เฮโรดชอบใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 7, 'เฮโรดจึงสัญญาโดยปฏิญาณว่า เธอจะขอสิ่งใดๆ ก็จะให้สิ่งนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 8, 'บุตรสาวก็ทูลตามที่มารดาได้สั่งไว้แล้วว่า “ขอศีรษะยอห์นผู้ให้รับบัพติศมาใส่ถาดมาให้หม่อมฉันที่นี่เพคะ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 9, 'ฝ่ายกษัตริย์เฮโรดก็เศร้าใจ แต่เพราะเหตุที่ได้ปฏิญาณไว้และเพราะเห็นแก่พวกที่เอนกายลงรับประทานด้วยกันกับท่าน จึงออกคําสั่งอนุญาตให้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 10, 'แล้วก็ใช้คนไปตัดศีรษะยอห์นในคุก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 11, 'เขาจึงเอาศีรษะของยอห์นใส่ถาดมาให้หญิงสาวนั้น หญิงสาวนั้นก็เอาไปให้มารดา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 12, 'ฝ่ายพวกสาวกของยอห์นก็มารับเอาศพไปฝังไว้ แล้วก็มาทูลพระเยซูให้ทรงทราบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 13, 'เมื่อพระเยซูทรงได้ยินแล้ว พระองค์จึงลงเรือเสด็จไปจากที่นั่น ไปยังที่เปลี่ยวแต่ลําพังพระองค์ เมื่อประชาชนทั้งปวงได้ยิน เขาก็ออกจากเมืองต่างๆเดินตามพระองค์ไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 14, 'ครั้นพระเยซูเสด็จขึ้นจากเรือแล้ว ก็ทอดพระเนตรเห็นประชาชนหมู่ใหญ่ พระองค์ทรงสงสารเขา จึงได้ทรงรักษาคนป่วยของเขาให้หาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 15, 'ครั้นเวลาเย็นแล้วพวกสาวกของพระองค์มาทูลพระองค์ว่า “ที่นี่กันดารอาหารนัก และบัดนี้ก็เย็นลงมากแล้ว ขอพระองค์ทรงให้ประชาชนไปเสียเถิด เพื่อเขาจะได้ไปซื้ออาหารตามหมู่บ้านสําหรับตนเอง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 16, 'ฝ่ายพระเยซูตรัสกับพวกสาวกว่า “เขาไม่จําเป็นต้องไปจากที่นี่ พวกท่านจงเลี้ยงเขาเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 17, 'พวกสาวกจึงทูลพระองค์ว่า “ที่นี่พวกข้าพระองค์มีแต่ขนมปังเพียงห้าก้อนกับปลาสองตัวเท่านั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 18, 'พระองค์จึงตรัสว่า “เอาอาหารนั้นมาให้เราที่นี่เถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 19, 'แล้วพระองค์ทรงสั่งให้คนเหล่านั้นนั่งลงที่หญ้า เมื่อทรงรับขนมปังห้าก้อนกับปลาสองตัวนั้นแล้ว ก็ทรงแหงนพระพักตร์ดูฟ้าสวรรค์ ทรงขอบพระคุณ และหักขนมปังส่งให้เหล่าสาวก เหล่าสาวกก็แจกให้คนทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 20, 'เขาได้กินอิ่มทุกคน ส่วนเศษอาหารที่ยังเหลือนั้น เขาเก็บไว้ได้ถึงสิบสองกระบุงเต็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 21, 'ฝ่ายคนที่ได้รับประทานอาหารนั้นมีผู้ชายประมาณห้าพันคน มิได้นับผู้หญิงและเด็ก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 22, 'ในทันใดนั้นพระเยซูได้ตรัสให้เหล่าสาวกของพระองค์ลงเรือข้ามฟากไปก่อน ส่วนพระองค์ทรงรอส่งประชาชนกลับบ้าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 23, 'และเมื่อให้ประชาชนเหล่านั้นไปหมดแล้ว พระองค์เสด็จขึ้นไปบนภูเขาโดยลําพังเพื่อจะอธิษฐาน เมื่อถึงเวลาค่ํา พระองค์ยังทรงอยู่ที่นั่นแต่ผู้เดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 24, 'แต่ขณะนั้นเรืออยู่กลางทะเลแล้ว และถูกคลื่นโคลงเพราะทวนลมอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 25, 'ครั้นเวลาสามยามเศษ พระเยซูจึงทรงดําเนินบนน้ําทะเลไปยังเหล่าสาวก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 26, 'เมื่อเหล่าสาวกเห็นพระองค์ทรงดําเนินมาบนทะเล เขาก็ตกใจนัก พูดกันว่า “เป็นผี” เขาจึงร้องอึงไปเพราะความกลัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 27, 'ในทันใดนั้นพระเยซูตรัสกับเขาว่า “จงชื่นใจเถิด คือเราเอง อย่ากลัวเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 28, 'ฝ่ายเปโตรจึงทูลตอบพระองค์ว่า “พระองค์เจ้าข้า ถ้าเป็นพระองค์แน่แล้ว ขอทรงโปรดให้ข้าพระองค์เดินบนน้ําไปหาพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 29, 'พระองค์ตรัสว่า “มาเถิด” เมื่อเปโตรลงจากเรือแล้ว เขาก็เดินบนน้ําไปหาพระเยซู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 30, 'แต่เมื่อเขาเห็นลมพัดแรงก็กลัว และเมื่อกําลังจะจมก็ร้องว่า “พระองค์เจ้าข้า ช่วยข้าพระองค์ด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 31, 'ในทันใดนั้นพระเยซูทรงเอื้อมพระหัตถ์จับเขาไว้ แล้วตรัสกับเขาว่า “โอ คนมีความเชื่อน้อย เจ้าสงสัยทําไม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 32, 'เมื่อพระองค์กับเปโตรขึ้นเรือแล้ว ลมก็สงบลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 33, 'เขาทั้งหลายที่อยู่ในเรือจึงมานมัสการพระองค์ทูลว่า “พระองค์ทรงเป็นพระบุตรของพระเจ้าจริงแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 34, 'ครั้นพวกเขาข้ามฟากไปแล้ว ก็มาถึงแขวงเยนเนซาเรท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 35, 'เมื่อคนในสถานที่นั้นรู้จักพระองค์แล้วก็ใช้คนไปบอกกล่าวทั่วแคว้นนั้น ต่างก็พาบรรดาคนเจ็บป่วยมาเฝ้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 36, 'เขาทูลอ้อนวอนขอพระองค์โปรดให้เขาได้แตะต้องแต่ชายฉลองพระองค์เท่านั้น และผู้ใดได้แตะต้องแล้วก็หายป่วยบริบูรณ์ดีทุกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 1, 'ครั้งนั้น พวกธรรมาจารย์และพวกฟาริสี ซึ่งมาจากกรุงเยรูซาเล็ม มาทูลถามพระเยซูว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 2, '“ทําไมพวกสาวกของท่านจึงละเมิดประเพณีสืบทอดมาจากบรรพบุรุษ ด้วยว่าเขามิได้ล้างมือเมื่อเขารับประทานอาหาร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 3, 'แต่พระองค์ได้ตรัสตอบเขาว่า “เหตุไฉนพวกท่านจึงละเมิดพระบัญญัติของพระเจ้าด้วยประเพณีของพวกท่านด้วยเล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 4, 'เพราะว่าพระเจ้าได้ทรงบัญญัติไว้ว่า ‘จงให้เกียรติแก่บิดามารดาของตน’ และ ‘ผู้ใดแช่งด่าบิดามารดาของตน ผู้นั้นต้องถูกปรับโทษถึงตาย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 5, 'แต่พวกท่านกลับสอนว่า ‘ผู้ใดจะกล่าวแก่บิดามารดาว่า “สิ่งใดของข้าพเจ้าซึ่งอาจเป็นประโยชน์แก่ท่าน สิ่งนั้นเป็นของถวายแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 6, 'ผู้นั้นจึงไม่ต้องให้เกียรติบิดามารดาของตน’ อย่างนั้นแหละท่านทั้งหลายทําให้พระบัญญัติของพระเจ้าเป็นหมันไปเพราะเห็นแก่ประเพณีของพวกท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 7, 'ท่านคนหน้าซื่อใจคด อิสยาห์ได้พยากรณ์ถึงพวกท่านถูกแล้วว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 8, '‘ประชาชนนี้เข้ามาใกล้เราด้วยปากของเขา และให้เกียรติเราด้วยริมฝีปากของเขา แต่ใจของเขาห่างไกลจากเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 9, 'เขานมัสการเราโดยหาประโยชน์มิได้ ด้วยเอาบทบัญญัติของมนุษย์มาอวดอ้างว่า เป็นพระดํารัสสอน’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 10, 'แล้วพระองค์ทรงเรียกประชาชนและตรัสกับเขาว่า “จงฟังและเข้าใจเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 11, 'มิใช่สิ่งซึ่งเข้าไปในปากจะทําให้มนุษย์เป็นมลทิน แต่สิ่งซึ่งออกมาจากปากนั้นแหละทําให้มนุษย์เป็นมลทิน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 12, 'ขณะนั้นพวกสาวกมาทูลพระองค์ว่า “พระองค์ทรงทราบแล้วหรือว่า เมื่อพวกฟาริสีได้ยินคําตรัสนั้น เขาแค้นเคืองใจนัก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 13, 'พระองค์จึงตรัสตอบว่า “ต้นไม้ใดๆทุกต้นซึ่งพระบิดาของเราผู้ทรงสถิตในสวรรค์มิได้ทรงปลูกไว้จะต้องถอนเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 14, 'ช่างเขาเถิด เขาเป็นผู้นําตาบอดนําทางคนตาบอด ถ้าคนตาบอดนําทางคนตาบอด ทั้งสองจะตกลงไปในบ่อ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 15, 'ฝ่ายเปโตรทูลพระองค์ว่า “ขอทรงโปรดอธิบายคําอุปมานี้ให้พวกข้าพระองค์ทราบเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 16, 'ฝ่ายพระเยซูตรัสตอบว่า “ท่านทั้งหลายยังไม่เข้าใจด้วยหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 17, 'ท่านยังไม่เข้าใจหรือว่า สิ่งใดๆซึ่งเข้าไปในปากก็ลงไปในท้อง แล้วก็ถ่ายออกลงส้วมไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 18, 'แต่สิ่งที่ออกจากปากก็ออกมาจากใจ สิ่งนั้นแหละทําให้มนุษย์เป็นมลทิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 19, 'ความคิดชั่วร้าย การฆาตกรรม การผิดผัวผิดเมีย การล่วงประเวณี การลักขโมย การเป็นพยานเท็จ การพูดหมิ่นประมาท ก็ออกมาจากใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 20, 'สิ่งเหล่านี้แหละที่ทําให้มนุษย์เป็นมลทิน แต่ซึ่งจะรับประทานอาหารโดยไม่ล้างมือก่อน ไม่ทําให้มนุษย์เป็นมลทิน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 21, 'แล้วพระเยซูเสด็จไปจากที่นั่นเข้าไปในเขตแดนเมืองไทระและเมืองไซดอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 22, 'ดูเถิด มีหญิงชาวคานาอันคนหนึ่งมาจากเขตแดนนั้นร้องทูลพระองค์ว่า “โอ พระองค์ผู้ทรงเป็นบุตรดาวิดเจ้าข้า ขอทรงโปรดเมตตาข้าพระองค์เถิด ลูกสาวของข้าพระองค์มีผีสิงอยู่เป็นทุกข์ลําบากยิ่งนัก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 23, 'ฝ่ายพระองค์ไม่ทรงตอบเขาสักคําเดียว และพวกสาวกของพระองค์มาอ้อนวอนพระองค์ ทูลว่า “ไล่เธอไปเสียเถิด เพราะเธอร้องตามเรามา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 24, 'พระองค์ตรัสตอบว่า “เรามิได้รับใช้มาหาผู้ใด เว้นแต่แกะหลงของวงศ์วานอิสราเอล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 25, 'ฝ่ายหญิงนั้นก็มานมัสการพระองค์ทูลว่า “พระองค์เจ้าข้า ขอทรงโปรดช่วยข้าพระองค์เถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 26, 'พระองค์จึงตรัสตอบว่า “ซึ่งจะเอาอาหารของลูกโยนให้แก่สุนัขก็ไม่ควร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 27, 'ผู้หญิงนั้นทูลว่า “จริงพระองค์เจ้าข้า แต่สุนัขนั้นย่อมกินเดนที่ตกจากโต๊ะนายของมัน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 28, 'แล้วพระเยซูตรัสตอบเขาว่า “โอ หญิงเอ๋ย ความเชื่อของเจ้าก็มาก ให้เป็นไปตามความปรารถนาของเจ้าเถิด” และลูกสาวของเขาก็หายเป็นปกติตั้งแต่ขณะนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 29, 'พระเยซูจึงเสด็จจากที่นั่นมายังทะเลกาลิลี แล้วเสด็จขึ้นไปบนภูเขาทรงประทับที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 30, 'และประชาชนเป็นอันมากมาเฝ้าพระองค์ พาคนง่อย คนตาบอด คนใบ้ คนพิการ และคนเจ็บอื่นๆหลายคนมาวางแทบพระบาทของพระเยซู แล้วพระองค์ทรงรักษาเขาให้หาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 31, 'คนเหล่านั้นจึงอัศจรรย์ใจนักเมื่อเห็นคนใบ้พูดได้ คนพิการหายเป็นปกติ คนง่อยเดินได้ คนตาบอดกลับเห็น แล้วเขาก็สรรเสริญพระเจ้าของชนชาติอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 32, 'ฝ่ายพระเยซูทรงเรียกพวกสาวกของพระองค์มาตรัสว่า “เราสงสารคนเหล่านี้ เพราะเขาค้างอยู่กับเราได้สามวันแล้ว และไม่มีอาหารจะกิน เราไม่อยากให้เขาไปเมื่อยังอดอาหารอยู่ กลัวว่าเขาจะหิวโหยสิ้นแรงลงตามทาง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 33, 'พวกสาวกทูลพระองค์ว่า “ในถิ่นทุรกันดารนี้ เราจะหาอาหารที่ไหนพอเลี้ยงคนเป็นอันมากนี้ให้อิ่มได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 34, 'พระเยซูจึงตรัสถามเขาว่า “ท่านมีขนมปังกี่ก้อน” เขาทูลว่า “มีเจ็ดก้อนกับปลาเล็กๆสองสามตัว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 35, 'พระองค์จึงสั่งประชาชนให้นั่งลงที่พื้นดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 36, 'แล้วพระองค์ทรงรับขนมปังเจ็ดก้อนและปลาเหล่านั้นมาขอบพระคุณ แล้วจึงทรงหักส่งให้เหล่าสาวกของพระองค์ เหล่าสาวกก็แจกให้ประชาชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 37, 'และคนทั้งปวงได้รับประทานอิ่มทุกคน อาหารที่เหลือนั้น เขาเก็บได้เจ็ดกระบุงเต็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 38, 'ผู้ที่ได้รับประทานอาหารนั้นมีผู้ชายสี่พันคน มิได้นับผู้หญิงและเด็ก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 39, 'พระองค์ตรัสสั่งให้ประชาชนไปแล้ว ก็เสด็จลงเรือมาถึงเขตเมืองมักดาลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 1, 'พวกฟาริสีกับพวกสะดูสีได้มาทดลองพระองค์โดยขอร้องให้พระองค์สําแดงหมายสําคัญจากฟ้าสวรรค์ให้เขาเห็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 2, 'พระองค์จึงตรัสตอบเขาว่า “พอตกเย็นท่านทั้งหลายพูดว่า ‘รุ่งขึ้นอากาศจะโปร่งดีเพราะฟ้าสีแดง’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 3, 'ในเวลาเช้าท่านพูดว่า ‘วันนี้จะเกิดพายุฝนเพราะฟ้าแดงและมัว’ โอ คนหน้าซื่อใจคด ท้องฟ้านั้นท่านทั้งหลายยังอาจสังเกตรู้และเข้าใจได้ แต่หมายสําคัญแห่งกาลนี้ท่านกลับไม่เข้าใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 4, 'คนชาติชั่วและเล่นชู้แสวงหาหมายสําคัญ และจะไม่โปรดให้หมายสําคัญแก่เขา เว้นไว้แต่หมายสําคัญของโยนาห์ศาสดาพยากรณ์เท่านั้น” แล้วพระองค์ก็เสด็จไปจากเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 5, 'ฝ่ายพวกสาวกของพระองค์ เมื่อข้ามฟากนั้นได้ลืมเอาขนมปังไปด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 6, 'พระเยซูตรัสกับเขาว่า “จงสังเกตและระวังเชื้อแห่งพวกฟาริสีและพวกสะดูสีให้ดี”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 7, 'เหล่าสาวกจึงปรึกษากันว่า “เพราะเหตุที่เรามิได้เอาขนมปังมา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 8, 'ฝ่ายพระเยซูทรงทราบจึงตรัสกับเขาว่า “โอ ผู้มีความเชื่อน้อย เหตุไฉนพวกท่านจึงปรึกษากันและกันถึงเรื่องไม่ได้เอาขนมปังมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 9, 'ท่านยังไม่เข้าใจและจําไม่ได้หรือ เรื่องขนมปังห้าก้อนกับคนห้าพันคนนั้น ท่านเก็บที่เหลือได้กี่กระบุง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 10, 'หรือขนมปังเจ็ดก้อนกับคนสี่พันคนนั้น ท่านเก็บที่เหลือได้กี่กระบุง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 11, 'เป็นไฉนพวกท่านถึงไม่เข้าใจว่า เรามิได้พูดกับท่านด้วยเรื่องขนมปัง แต่ได้ว่าให้ท่านระวังเชื้อแห่งพวกฟาริสีและพวกสะดูสีให้ดี”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 12, 'แล้วพวกสาวกก็เข้าใจว่า พระองค์มิได้ตรัสสั่งเขาให้ระวังเชื้อขนมปัง แต่ให้ระวังคําสอนของพวกฟาริสีและพวกสะดูสี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 13, 'ครั้นพระเยซูเสด็จเข้าไปในเขตเมืองซีซารียาฟีลิปปี พระองค์จึงตรัสถามพวกสาวกของพระองค์ว่า “คนทั้งหลายพูดกันว่าเราซึ่งเป็นบุตรมนุษย์คือผู้ใด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 14, 'เขาจึงทูลตอบว่า “บางคนว่าเป็นยอห์นผู้ให้รับบัพติศมา แต่บางคนว่าเป็นเอลียาห์ และคนอื่นว่าเป็นเยเรมีย์ หรือเป็นคนหนึ่งในพวกศาสดาพยากรณ์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 15, 'พระองค์ตรัสถามเขาว่า “แล้วพวกท่านเล่า ว่าเราเป็นผู้ใด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 16, 'ซีโมนเปโตรทูลตอบว่า “พระองค์ทรงเป็นพระคริสต์พระบุตรของพระเจ้าผู้ทรงพระชนม์อยู่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 17, 'พระเยซูตรัสตอบเขาว่า “ซีโมนบุตรโยนาเอ๋ย ท่านก็เป็นสุข เพราะว่าเนื้อหนังและโลหิตมิได้แจ้งความนี้แก่ท่าน แต่พระบิดาของเราผู้ทรงสถิตในสวรรค์ทรงแจ้งให้ทราบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 18, 'ฝ่ายเราบอกท่านด้วยว่า ท่านคือเปโตร และบนศิลานี้เราจะสร้างคริสตจักรของเราไว้ และประตูแห่งนรกจะมีชัยต่อคริสตจักรนั้นก็หามิได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 19, 'เราจะมอบลูกกุญแจของอาณาจักรแห่งสวรรค์ให้ไว้แก่ท่าน ท่านจะผูกมัดสิ่งใดในโลก สิ่งนั้นก็จะถูกมัดในสวรรค์ และท่านจะปล่อยสิ่งใดในโลก สิ่งนั้นจะถูกปล่อยในสวรรค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 20, 'แล้วพระองค์ทรงกําชับห้ามเหล่าสาวกของพระองค์ มิให้บอกผู้ใดว่า พระองค์ทรงเป็นพระเยซูผู้เป็นพระคริสต์นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 21, 'ตั้งแต่เวลานั้นมา พระเยซูทรงเริ่มเผยแก่เหล่าสาวกของพระองค์ว่า พระองค์จะต้องเสด็จไปกรุงเยรูซาเล็ม และจะต้องทนทุกข์ทรมานหลายประการจากพวกผู้ใหญ่และพวกปุโรหิตใหญ่และพวกธรรมาจารย์ จนต้องถูกประหารเสีย แต่ในวันที่สามจะทรงถูกชุบให้เป็นขึ้นมาใหม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 22, 'ฝ่ายเปโตรเอามือจับพระองค์ เริ่มทูลท้วงพระองค์ว่า “พระองค์เจ้าข้า ให้เหตุการณ์นั้นอยู่ห่างไกลจากพระองค์เถิด อย่าให้เป็นอย่างนั้นแก่พระองค์เลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 23, 'พระองค์จึงหันพระพักตร์ตรัสกับเปโตรว่า “อ้ายซาตาน จงถอยไปข้างหลังเรา เจ้าเป็นเครื่องกีดขวางเรา เพราะเจ้ามิได้คิดตามพระดําริของพระเจ้า แต่ตามความคิดของมนุษย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 24, 'ขณะนั้นพระเยซูจึงตรัสกับเหล่าสาวกของพระองค์ว่า “ถ้าผู้ใดใคร่ตามเรามา ให้ผู้นั้นเอาชนะตัวเอง และรับกางเขนของตนแบกและตามเรามา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 25, 'เพราะว่าผู้ใดใคร่จะเอาชีวิตของตนรอด ผู้นั้นจะเสียชีวิต แต่ผู้ใดจะเสียชีวิตของตนเพราะเห็นแก่เรา ผู้นั้นจะได้ชีวิตรอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 26, 'เพราะถ้าผู้ใดจะได้สิ่งของสิ้นทั้งโลก แต่ต้องสูญเสียจิตวิญญาณของตน ผู้นั้นจะได้ประโยชน์อะไร หรือผู้นั้นจะนําอะไรไปแลกเอาจิตวิญญาณของตนกลับคืนมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 27, 'เหตุว่าบุตรมนุษย์จะเสด็จมาด้วยสง่าราศีแห่งพระบิดา และพร้อมด้วยเหล่าทูตสวรรค์ของพระองค์ เมื่อนั้นพระองค์จะประทานบําเหน็จแก่ทุกคนตามการกระทําของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 28, 'เราบอกความจริงแก่ท่านทั้งหลายว่า ในพวกท่านที่ยืนอยู่ที่นี่ มีบางคนที่ยังจะไม่รู้รสความตาย จนกว่าจะได้เห็นบุตรมนุษย์เสด็จมาในราชอาณาจักรของท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 1, 'ครั้นล่วงไปได้หกวันแล้ว พระเยซูทรงพาเปโตร ยากอบ และยอห์นน้องชายของยากอบ ขึ้นภูเขาสูงแต่ลําพัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 2, 'แล้วพระกายของพระองค์ก็เปลี่ยนไปต่อหน้าเขา พระพักตร์ของพระองค์ก็ทอแสงเหมือนแสงอาทิตย์ ฉลองพระองค์ก็ขาวผ่องดุจแสงสว่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 3, 'ดูเถิด โมเสสและเอลียาห์ก็มาปรากฏแก่พวกสาวกเหล่านั้น กําลังเฝ้าสนทนากับพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 4, 'ฝ่ายเปโตรทูลพระเยซูว่า “พระองค์เจ้าข้า ซึ่งพวกข้าพระองค์อยู่ที่นี่ก็ดี ถ้าพระองค์ต้องพระประสงค์ พวกข้าพระองค์จะทําพลับพลาสามหลังที่นี่ สําหรับพระองค์หลังหนึ่ง สําหรับโมเสสหลังหนึ่ง สําหรับเอลียาห์หลังหนึ่ง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 5, 'เปโตรทูลยังไม่ทันขาดคํา ดูเถิด ก็บังเกิดมีเมฆสุกใสมาปกคลุมเขาไว้ แล้วดูเถิด มีพระสุรเสียงออกมาจากเมฆนั้นว่า “ท่านผู้นี้เป็นบุตรที่รักของเรา เราชอบใจท่านผู้นี้มาก จงฟังท่านเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 6, 'ฝ่ายพวกสาวกเมื่อได้ยินก็ซบหน้ากราบลงกลัวยิ่งนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 7, 'พระเยซูจึงเสด็จมาถูกต้องเขา แล้วตรัสว่า “จงลุกขึ้นเถิด อย่ากลัวเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 8, 'เมื่อเขาเงยหน้าดูก็ไม่เห็นผู้ใด เห็นแต่พระเยซูองค์เดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 9, 'ขณะที่ลงมาจากภูเขา พระเยซูตรัสกําชับเหล่าสาวกว่า “นิมิตซึ่งพวกท่านได้เห็นนั้น อย่าบอกเล่าแก่ผู้ใดจนกว่าบุตรมนุษย์จะฟื้นขึ้นมาจากความตาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 10, 'เหล่าสาวกก็ทูลถามพระองค์ว่า “เหตุไฉนพวกธรรมาจารย์จึงว่า เอลียาห์จะต้องมาก่อน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 11, 'พระเยซูตรัสตอบพวกเขาว่า “เอลียาห์ต้องมาก่อนจริง และทําให้สิ่งทั้งปวงคืนสู่สภาพเดิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 12, 'แต่เราบอกแก่ท่านทั้งหลายว่า เอลียาห์นั้นได้มาแล้ว และเขาหารู้จักท่านไม่ แต่เขาใคร่ทําแก่ท่านอย่างไร เขาก็ได้กระทําแล้ว ส่วนบุตรมนุษย์จะต้องทนทุกข์จากเขาเช่นเดียวกัน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 13, 'แล้วเหล่าสาวกจึงเข้าใจว่าพระองค์ได้ตรัสแก่เขาเล็งถึงยอห์นผู้ให้รับบัพติศมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 14, 'ครั้นพระเยซูกับเหล่าสาวกมาถึงฝูงชนแล้ว มีชายคนหนึ่งมาหาพระองค์คุกเข่าลงต่อพระองค์ และทูลว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 15, '“พระองค์เจ้าข้า ขอทรงพระเมตตาแก่บุตรชายของข้าพระองค์ ด้วยว่าเขาเป็นคนบ้า มีความทุกข์เวทนามาก เพราะเคยตกไฟตกน้ําบ่อยๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 16, 'ข้าพระองค์ได้พาเขามาหาพวกสาวกของพระองค์ แต่พวกสาวกนั้นรักษาเขาให้หายไม่ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 17, 'พระเยซูตรัสตอบว่า “โอ คนในยุคที่ขาดความเชื่อและมีทิฐิชั่ว เราจะต้องอยู่กับท่านทั้งหลายนานเท่าใด เราจะต้องอดทนเพราะท่านไปถึงไหน จงพาเด็กนั้นมาหาเราที่นี่เถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 18, 'พระเยซูจึงตรัสสําทับผีนั้น มันก็ออกจากเขา เด็กก็หายเป็นปกติตั้งแต่เวลานั้นเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 19, 'ภายหลังเหล่าสาวกมาหาพระเยซูเป็นส่วนตัวทูลถามว่า “เหตุไฉนพวกข้าพระองค์ขับผีนั้นออกไม่ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 20, 'พระเยซูตรัสตอบเขาว่า “เพราะเหตุพวกท่านไม่มีความเชื่อ ด้วยเราบอกความจริงแก่ท่านทั้งหลายว่า ถ้าท่านมีความเชื่อเท่าเมล็ดมัสตาร์ดเมล็ดหนึ่ง ท่านจะสั่งภูเขานี้ว่า ‘จงเลื่อนจากที่นี่ไปที่โน่น’ มันก็จะเลื่อน และไม่มีสิ่งใดที่เป็นไปไม่ได้สําหรับท่านเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 21, 'แต่ผีชนิดนี้จะไม่ยอมออก เว้นไว้โดยการอธิษฐานและการอดอาหาร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 22, 'ครั้นพระองค์กับเหล่าสาวกอาศัยอยู่ในแคว้นกาลิลี พระเยซูจึงตรัสกับเขาว่า “บุตรมนุษย์จะต้องถูกทรยศให้อยู่ในเงื้อมมือของคนทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 23, 'และเขาทั้งหลายจะประหารชีวิตท่านเสีย ในวันที่สามท่านจะกลับฟื้นขึ้นมาใหม่” พวกสาวกก็พากันเป็นทุกข์ยิ่งนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 24, 'เมื่อพระองค์กับเหล่าสาวกมาถึงเมืองคาเปอรนาอุมแล้ว พวกคนเก็บค่าบํารุงพระวิหารมาหาเปโตรถามว่า “อาจารย์ของท่านไม่เสียค่าบํารุงพระวิหารหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 25, 'เปโตรตอบว่า “เสีย” เมื่อเปโตรเข้าไปในเรือน พระเยซูทรงกันเขาไว้ แล้วตรัสว่า “ซีโมนเอ๋ย ท่านคิดเห็นอย่างไร กษัตริย์ของแผ่นดินโลกเคยเก็บภาษีและส่วยจากผู้ใด จากโอรสของพระองค์เองหรือจากผู้อื่น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 26, 'เปโตรทูลตอบพระองค์ว่า “เก็บจากผู้อื่น” พระเยซูจึงตรัสกับเขาว่า “ถ้าเช่นนั้นโอรสก็ไม่ต้องเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 27, 'แต่เพื่อมิให้เราทั้งหลายทําให้เขาสะดุด ท่านจงไปตกเบ็ดที่ทะเล เมื่อได้ปลาตัวแรกขึ้นมาก็ให้เปิดปากมัน แล้วจะพบเงินแผ่นหนึ่ง จงเอาเงินนั้นไปจ่ายให้แก่เขาสําหรับเรากับท่านเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 1, 'ในเวลานั้นเหล่าสาวกมาเฝ้าพระเยซูทูลว่า “ใครเป็นใหญ่ที่สุดในอาณาจักรแห่งสวรรค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 2, 'พระเยซูจึงทรงเรียกเด็กเล็กๆคนหนึ่งมาให้อยู่ท่ามกลางเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 3, 'แล้วตรัสว่า “เราบอกความจริงแก่ท่านทั้งหลายว่า ถ้าพวกท่านไม่กลับใจเป็นเหมือนเด็กเล็กๆ ท่านจะเข้าในอาณาจักรแห่งสวรรค์ไม่ได้เลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 4, 'เหตุฉะนั้น ถ้าผู้ใดจะถ่อมจิตใจลงเหมือนเด็กเล็กคนนี้ ผู้นั้นจะเป็นใหญ่ที่สุดในอาณาจักรแห่งสวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 5, 'ถ้าผู้ใดจะรับเด็กเล็กเช่นนี้คนหนึ่งในนามของเรา ผู้นั้นก็รับเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 6, 'แต่ผู้ใดจะทําผู้เล็กน้อยเหล่านี้คนหนึ่งที่เชื่อในเราให้หลงผิด ถ้าเอาหินโม่ก้อนใหญ่ผูกคอผู้นั้นถ่วงเสียที่ทะเลลึกก็ดีกว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 7, 'วิบัติแก่โลกนี้ด้วยเหตุให้หลงผิด ถึงจําเป็นต้องมีเหตุให้หลงผิด แต่วิบัติแก่ผู้ที่ก่อเหตุให้เกิดความหลงผิดนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 8, 'ด้วยเหตุนี้ถ้ามือหรือเท้าของท่านทําให้ท่านหลงผิด จงตัดออกและโยนมันทิ้งเสียจากท่าน ซึ่งท่านจะเข้าสู่ชีวิตด้วยมือและเท้าด้วนยังดีกว่ามีสองมือสองเท้า และต้องถูกทิ้งในไฟซึ่งไหม้อยู่เป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 9, 'ถ้าตาของท่านทําให้ท่านหลงผิด จงควักออกและโยนมันทิ้งเสียจากท่าน ซึ่งท่านจะเข้าสู่ชีวิตด้วยตาข้างเดียวยังดีกว่ามีสองตาและต้องถูกทิ้งไปในไฟนรก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 10, 'จงระวังให้ดี อย่าดูหมิ่นผู้เล็กน้อยเหล่านี้สักคนหนึ่ง ด้วยเรากล่าวแก่ท่านทั้งหลายว่า บนสวรรค์ทูตสวรรค์ประจําของเขาเฝ้าอยู่เสมอต่อพระพักตร์พระบิดาของเราผู้ทรงสถิตในสวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 11, 'เพราะว่าบุตรมนุษย์ได้เสด็จมาเพื่อช่วยผู้ซึ่งหลงหายไปนั้นให้รอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 12, 'ท่านทั้งหลายคิดเห็นอย่างไร ถ้าผู้หนึ่งมีแกะอยู่ร้อยตัว และตัวหนึ่งหลงหายไปจากฝูง ผู้นั้นจะไม่ละแกะเก้าสิบเก้าตัวไว้แล้วขึ้นไปบนภูเขาเที่ยวหาตัวที่หายนั้นหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 13, 'เราบอกความจริงแก่ท่านว่า ถ้าเขาพบแกะตัวนั้น เขาจะชื่นชมยินดียิ่งกว่าที่มีแกะเก้าสิบเก้าตัวที่มิได้หลงหายนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 14, 'อย่างนั้นแหละ พระบิดาของท่านผู้ทรงสถิตในสวรรค์ ไม่ทรงปรารถนาให้ผู้เล็กน้อยเหล่านี้สักคนหนึ่งพินาศไปเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 15, 'หากว่าพี่น้องของท่านผู้หนึ่งทําการละเมิดต่อท่าน จงไปแจ้งความผิดบาปนั้นแก่เขาสองต่อสองเท่านั้น ถ้าเขาฟังท่าน ท่านจะได้พี่น้องคืนมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 16, 'แต่ถ้าเขาไม่ฟังท่าน จงนําคนหนึ่งหรือสองคนไปด้วย ให้เป็นพยานสองสามปาก เพื่อทุกคําจะเป็นหลักฐานได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 17, 'ถ้าเขาไม่ฟังคนเหล่านั้น จงไปแจ้งความต่อคริสตจักร แต่ถ้าเขายังไม่ฟังคริสตจักรอีกก็ให้ถือเสียว่า เขาเป็นเหมือนคนต่างชาติและคนเก็บภาษี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 18, 'เราบอกความจริงแก่ท่านทั้งหลายว่า สิ่งใดซึ่งท่านจะผูกมัดในโลก ก็จะถูกผูกมัดในสวรรค์ และสิ่งซึ่งท่านจะปล่อยในโลกก็จะถูกปล่อยในสวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 19, 'เรากล่าวแก่ท่านทั้งหลายอีกว่า ถ้าในพวกท่านที่อยู่ในโลกสองคนจะร่วมใจกันขอสิ่งหนึ่งสิ่งใด พระบิดาของเราผู้ทรงสถิตในสวรรค์ก็จะทรงกระทําให้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 20, 'ด้วยว่ามีสองสามคนประชุมกันที่ไหนๆในนามของเรา เราจะอยู่ท่ามกลางเขาที่นั่น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 21, 'ขณะนั้นเปโตรมาทูลพระองค์ว่า “พระองค์เจ้าข้า หากพี่น้องของข้าพระองค์จะกระทําผิดต่อข้าพระองค์เรื่อยไป ข้าพระองค์ควรจะยกความผิดของเขาสักกี่ครั้ง ถึงเจ็ดครั้งหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 22, 'พระเยซูตรัสตอบเขาว่า “เรามิได้ว่าเพียงเจ็ดครั้งเท่านั้น แต่เจ็ดสิบครั้งคูณด้วยเจ็ด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 23, 'เหตุฉะนั้น อาณาจักรแห่งสวรรค์เปรียบเหมือนกษัตริย์องค์หนึ่งทรงประสงค์จะคิดบัญชีกับผู้รับใช้ของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 24, 'เมื่อตั้งต้นทําการนั้น เขาพาคนหนึ่งซึ่งเป็นหนี้หนึ่งหมื่นตะลันต์มาเฝ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 25, 'เจ้านายของเขาจึงสั่งให้ขายตัวกับทั้งภรรยาและลูก และบรรดาสิ่งของที่เขามีอยู่นั้นเอามาใช้หนี้ เพราะเขาไม่มีเงินจะใช้หนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 26, 'ผู้รับใช้ลูกหนี้ผู้นั้นจึงกราบลงนมัสการท่านว่า ‘ข้าแต่ท่าน ขอโปรดอดทนต่อข้าพเจ้าเถิด แล้วข้าพเจ้าจะใช้หนี้ทั้งสิ้น’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 27, 'เจ้านายของผู้รับใช้ผู้นั้นมีพระทัยเมตตา โปรดยกหนี้ปล่อยตัวเขาไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 28, 'แต่ผู้รับใช้ผู้นั้นออกไปพบคนหนึ่งเป็นเพื่อนผู้รับใช้ด้วยกัน ซึ่งเป็นหนี้เขาอยู่หนึ่งร้อยเดนาริอัน จึงจับคนนั้นบีบคอว่า ‘จงใช้หนี้ให้ข้า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 29, 'เพื่อนผู้รับใช้ผู้นั้นได้กราบลงแทบเท้าอ้อนวอนว่า ‘ขอโปรดอดทนต่อข้าพเจ้าเถิด แล้วข้าพเจ้าจะใช้หนี้ทั้งสิ้น’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 30, 'แต่เขาไม่ยอม จึงนําผู้รับใช้ลูกหนี้นั้นไปขังคุกไว้ จนกว่าจะใช้เงินนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 31, 'ฝ่ายพวกเพื่อนผู้รับใช้เมื่อเห็นเหตุการณ์เช่นนั้น ก็พากันสลดใจยิ่งนัก จึงนําเหตุการณ์ทั้งปวงไปกราบทูลเจ้านายของพวกตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 32, 'แล้วเจ้านายของเขาจึงทรงเรียกผู้รับใช้นั้นมาสั่งว่า ‘โอ เจ้าผู้รับใช้ชั่ว เราได้โปรดยกหนี้ให้เจ้าหมด เพราะเจ้าได้อ้อนวอนเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 33, 'เจ้าควรจะเมตตาเพื่อนผู้รับใช้ด้วยกัน เหมือนเราได้เมตตาเจ้ามิใช่หรือ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 34, 'แล้วเจ้านายของเขาก็กริ้วจึงมอบผู้นั้นไว้แก่เจ้าหน้าที่ให้ทรมาน จนกว่าจะใช้หนี้หมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 35, 'พระบิดาของเราผู้ทรงสถิตในสวรรค์จะทรงกระทําแก่ท่านทุกคนอย่างนั้น ถ้าหากว่าท่านแต่ละคนไม่ยกโทษการละเมิดให้แก่พี่น้องของท่านด้วยใจกว้างขวาง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 1, 'ต่อมาเมื่อพระเยซูตรัสถ้อยคําเหล่านี้เสร็จแล้ว พระองค์ได้เสด็จจากแคว้นกาลิลี เข้าไปในเขตแดนแคว้นยูเดียฟากแม่น้ําจอร์แดนข้างโน้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 2, 'ฝูงชนเป็นอันมากได้ตามพระองค์ไป แล้วพระองค์ทรงรักษาโรคของเขาให้หายที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 3, 'พวกฟาริสีมาทดลองพระองค์ทูลถามว่า “ผู้ชายจะหย่าภรรยาของตนเพราะเหตุใดๆก็ตาม เป็นการถูกต้องตามพระราชบัญญัติหรือไม่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 4, 'พระองค์ตรัสตอบเขาว่า “พวกท่านไม่ได้อ่านหรือว่า พระผู้ทรงสร้างมนุษย์แต่เดิม ‘ได้ทรงสร้างพวกเขาให้เป็นชายและหญิง’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 5, 'และตรัสว่า ‘เพราะเหตุนี้ผู้ชายจะจากบิดามารดาของเขา และจะไปผูกพันอยู่กับภรรยา และเขาทั้งสองจะเป็นเนื้ออันเดียวกัน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 6, 'เขาจึงไม่เป็นสองต่อไป แต่เป็นเนื้ออันเดียวกัน เหตุฉะนั้นซึ่งพระเจ้าได้ทรงผูกพันกันแล้ว อย่าให้มนุษย์ทําให้พรากจากกันเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 7, 'เขาจึงทูลถามพระองค์ว่า “ถ้าอย่างนั้นทําไมโมเสสได้สั่งให้ทําหนังสือหย่าให้ภรรยา แล้วก็หย่าได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 8, 'พระองค์ตรัสแก่เขาว่า “โมเสสได้ยอมให้ท่านทั้งหลายหย่าภรรยาของตน เพราะใจท่านทั้งหลายแข็งกระด้าง แต่เมื่อเดิมมิได้เป็นอย่างนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 9, 'ฝ่ายเราบอกท่านทั้งหลายว่า ผู้ใดหย่าภรรยาของตนเพราะเหตุต่างๆ เว้นแต่เป็นชู้กับชายอื่นแล้วไปมีภรรยาใหม่ก็ผิดประเวณี และผู้ใดรับหญิงที่หย่าแล้วนั้นมาเป็นภรรยาก็ผิดประเวณีด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 10, 'พวกสาวกของพระองค์ทูลพระองค์ว่า “ถ้ากรณีของฝ่ายชายต้องเป็นเช่นนั้นกับภรรยาของเขา การสมรสก็ไม่ดีเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 11, 'พระองค์ทรงตอบเขาว่า “มิใช่ทุกคนจะรับประพฤติตามข้อนี้ได้ เว้นแต่ผู้ที่ทรงให้ประพฤติได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 12, 'ด้วยว่าผู้ที่เป็นขันทีตั้งแต่กําเนิดจากครรภ์มารดาก็มี ผู้ที่มนุษย์กระทําให้เป็นขันทีก็มี ผู้ที่กระทําตัวเองให้เป็นขันทีเพราะเห็นแก่อาณาจักรแห่งสวรรค์ก็มี ใครถือได้ก็ให้ถือเอาเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 13, 'ขณะนั้นเขาพาเด็กเล็กๆมาหาพระองค์ เพื่อจะให้พระองค์ทรงวางพระหัตถ์และอธิษฐาน แต่เหล่าสาวกก็ห้ามปรามไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 14, 'ฝ่ายพระเยซูตรัสว่า “จงยอมให้เด็กเล็กๆเข้ามาหาเรา อย่าห้ามเขาเลย เพราะว่าอาณาจักรแห่งสวรรค์ย่อมเป็นของคนเช่นเด็กเหล่านั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 15, 'เมื่อพระองค์ทรงวางพระหัตถ์บนเด็กเหล่านั้นแล้ว ก็เสด็จไปจากที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 16, 'ดูเถิด มีคนหนึ่งมาทูลพระองค์ว่า “ท่านอาจารย์ผู้ประเสริฐ ข้าพเจ้าจะต้องทําดีประการใดจึงจะได้ชีวิตนิรันดร์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 17, 'พระองค์ตรัสตอบเขาว่า “ท่านเรียกเราว่าประเสริฐทําไมเล่า ไม่มีผู้ใดประเสริฐนอกจากพระองค์เดียวคือพระเจ้า แต่ถ้าท่านปรารถนาจะเข้าในชีวิต ก็ให้ถือรักษาพระบัญญัติไว้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 18, 'คนนั้นทูลถามพระองค์ว่า “คือพระบัญญัติข้อใดบ้าง” พระเยซูตรัสว่า “อย่ากระทําการฆาตกรรม อย่าล่วงประเวณีผัวเมียเขา อย่าลักทรัพย์ อย่าเป็นพยานเท็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 19, 'จงให้เกียรติแก่บิดามารดาของตน และจงรักเพื่อนบ้านเหมือนรักตนเอง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 20, 'คนหนุ่มนั้นทูลพระองค์ว่า “ข้อเหล่านี้ข้าพเจ้าได้ถือรักษาไว้ทุกประการตั้งแต่เป็นเด็กหนุ่มมา ข้าพเจ้ายังขาดอะไรอีกบ้าง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 21, 'พระเยซูตรัสแก่เขาว่า “ถ้าท่านปรารถนาเป็นผู้ที่ทําจนครบถ้วน จงไปขายบรรดาสิ่งของซึ่งท่านมีอยู่แจกจ่ายให้คนอนาถา แล้วท่านจะมีทรัพย์สมบัติในสวรรค์ แล้วจงตามเรามา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 22, 'เมื่อคนหนุ่มได้ยินถ้อยคํานั้นเขาก็ออกไปเป็นทุกข์ เพราะเขามีทรัพย์สิ่งของเป็นอันมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 23, 'พระเยซูตรัสกับเหล่าสาวกของพระองค์ว่า “เราบอกความจริงแก่ท่านทั้งหลายว่า คนมั่งมีจะเข้าในอาณาจักรแห่งสวรรค์ก็ยาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 24, 'เราบอกท่านทั้งหลายอีกว่า ตัวอูฐจะลอดรูเข็มก็ง่ายกว่าคนมั่งมีจะเข้าในอาณาจักรของพระเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 25, 'เมื่อพวกสาวกของพระองค์ได้ยินก็ประหลาดใจมาก จึงทูลว่า “ถ้าอย่างนั้นใครจะรอดได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 26, 'พระเยซูทอดพระเนตรดูพวกสาวกและตรัสกับเขาว่า “ฝ่ายมนุษย์ย่อมเป็นไปไม่ได้ แต่พระเจ้าทรงกระทําให้เป็นไปได้ทุกสิ่ง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 27, 'แล้วเปโตรทูลพระองค์ว่า “ดูเถิด ข้าพระองค์ทั้งหลายได้สละสิ่งสารพัด และได้ติดตามพระองค์มา พวกข้าพระองค์จึงจะได้อะไรบ้าง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 28, 'พระเยซูตรัสกับเขาว่า “เราบอกความจริงแก่ท่านทั้งหลายว่า ในโลกใหม่คราวเมื่อบุตรมนุษย์จะนั่งบนพระที่นั่งแห่งสง่าราศีของพระองค์นั้น พวกท่านที่ได้ติดตามเรามาจะได้นั่งบนบัลลังก์สิบสองที่ พิพากษาชนอิสราเอลสิบสองตระกูล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 29, 'ทุกคนที่ได้สละบ้านหรือพี่น้องชายหญิงหรือบิดามารดาหรือภรรยาหรือบุตรหรือที่ดิน เพราะเห็นแก่นามของเรา ผู้นั้นจะได้ผลร้อยเท่า และจะได้ชีวิตนิรันดร์เป็นมรดก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 30, 'แต่มีหลายคนที่เป็นคนต้นจะต้องกลับไปเป็นคนสุดท้าย และที่เป็นคนสุดท้ายจะกลับเป็นคนต้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 1, '“ด้วยว่าอาณาจักรแห่งสวรรค์เปรียบเหมือนเจ้าของบ้านคนหนึ่งออกไปจ้างคนทํางานในสวนองุ่นของตนแต่เวลาเช้าตรู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 2, 'ครั้นตกลงกับลูกจ้างวันละเดนาริอันแล้ว จึงใช้ให้ไปทํางานในสวนองุ่นของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 3, 'พอเวลาประมาณสามโมงเช้า เจ้าของบ้านก็ออกไปอีก เห็นคนอื่นยืนอยู่เปล่าๆกลางตลาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 4, 'จึงพูดกับเขาว่า ‘ท่านทั้งหลายจงไปทํางานในสวนองุ่นด้วยเถิด เราจะให้ค่าจ้างแก่พวกท่านตามสมควร’ แล้วเขาก็พากันไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 5, 'พอเวลาเที่ยงวันและเวลาบ่ายสามโมง เจ้าของบ้านก็ออกไปอีก ทําเหมือนก่อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 6, 'ประมาณบ่ายห้าโมงก็ออกไปอีกครั้งหนึ่ง พบอีกพวกหนึ่งยืนอยู่เปล่าๆจึงพูดกับเขาว่า ‘พวกท่านยืนอยู่ที่นี่เปล่าๆตลอดวันทําไม’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 7, 'พวกเขาตอบเจ้าของบ้านว่า ‘เพราะไม่มีใครจ้างพวกข้าพเจ้า’ เจ้าของบ้านบอกพวกเขาว่า ‘ท่านทั้งหลายจงไปทํางานในสวนองุ่นด้วยเถิด และท่านจะได้รับค่าจ้างตามสมควร’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 8, 'ครั้นถึงเวลาพลบค่ําเจ้าของสวนองุ่นจึงสั่งเจ้าพนักงานว่า ‘จงเรียกคนทํางานมาและให้ค่าจ้างแก่เขา ตั้งแต่คนมาทํางานสุดท้าย จนถึงคนที่มาแรก’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 9, 'คนที่มาทํางานเวลาประมาณบ่ายห้าโมงนั้น ได้ค่าจ้างคนละหนึ่งเดนาริอัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 10, 'ส่วนคนที่มาทีแรกนึกว่าเขาคงจะได้มากกว่านั้น แต่ก็ได้คนละหนึ่งเดนาริอันเหมือนกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 11, 'เมื่อเขารับเงินไปแล้วก็บ่นต่อว่าเจ้าของบ้าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 12, 'ว่า ‘พวกที่มาสุดท้ายได้ทํางานชั่วโมงเดียว และท่านได้ให้ค่าจ้างแก่เขาเท่ากันกับพวกเราที่ทํางานตรากตรํากลางแดดตลอดวัน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 13, 'ฝ่ายเจ้าของบ้านก็ตอบแก่คนหนึ่งในพวกนั้นว่า ‘สหายเอ๋ย เรามิได้โกงท่านเลย ท่านได้ตกลงกับเราแล้ววันละหนึ่งเดนาริอันมิใช่หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 14, 'รับค่าจ้างของท่านไปเถิด เราพอใจจะให้คนที่มาทํางานหลังที่สุดนั้นเท่ากันกับท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 15, 'เราปรารถนาจะทําอะไรกับสิ่งที่เป็นของเราเองนั้นไม่ถูกต้องตามพระราชบัญญัติหรือ ท่านมีแววตาอันชั่วร้ายเพราะเห็นเราใจดีหรือ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 16, 'อย่างนั้นแหละคนที่เป็นคนสุดท้ายจะกลับเป็นคนต้น และคนที่เป็นคนต้นจะกลับเป็นคนสุดท้าย ด้วยว่าผู้ที่ได้รับเชิญก็มาก แต่ผู้ที่ทรงเลือกก็น้อย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 17, 'เมื่อพระเยซูจะเสด็จขึ้นไปยังกรุงเยรูซาเล็ม ขณะอยู่ตามหนทางได้พาเหล่าสาวกสิบสองคนไปแต่ลําพัง และตรัสกับเขาว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 18, '“ดูเถิด เราทั้งหลายจะขึ้นไปยังกรุงเยรูซาเล็ม และบุตรมนุษย์จะถูกทรยศให้อยู่กับพวกปุโรหิตใหญ่และพวกธรรมาจารย์ และเขาเหล่านั้นจะปรับโทษท่านถึงตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 19, 'และจะมอบท่านไว้กับคนต่างชาติให้เยาะเย้ยเฆี่ยนตี และให้ตรึงไว้ที่กางเขน และวันที่สามท่านจึงจะกลับฟื้นขึ้นมาใหม่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 20, 'ขณะนั้นมารดาของบุตรแห่งเศเบดีพาบุตรชายทั้งสองมาเฝ้าพระองค์ นมัสการทูลขอสิ่งหนึ่งจากพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 21, 'พระองค์จึงทรงถามนางนั้นว่า “ท่านปรารถนาอะไร” นางทูลพระองค์ว่า “ขอทรงโปรดอนุญาตให้บุตรชายของข้าพระองค์สองคนนี้นั่งในราชอาณาจักรของพระองค์ เบื้องขวาพระหัตถ์คนหนึ่ง เบื้องซ้ายคนหนึ่ง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 22, 'แต่พระเยซูตรัสตอบว่า “ที่ท่านขอนั้นท่านไม่เข้าใจ ถ้วยซึ่งเราจะดื่มนั้นท่านจะดื่มได้หรือ และบัพติศมานั้นซึ่งเราจะรับ ท่านจะรับได้หรือ” เขาทูลพระองค์ว่า “พวกข้าพระองค์ทําได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 23, 'พระองค์ตรัสกับเขาว่า “ท่านจะดื่มจากถ้วยของเรา และรับบัพติศมาด้วยบัพติศมาที่เราจะรับก็จริง แต่ซึ่งจะนั่งข้างขวาและข้างซ้ายของเรานั้น ไม่ใช่พนักงานของเราที่จะมอบให้ แต่พระบิดาของเราได้ทรงเตรียมไว้สําหรับผู้ใด ก็จะให้แก่ผู้นั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 24, 'เมื่อสาวกสิบคนนั้นได้ยินแล้ว พวกเขาก็มีความขุ่นเคืองพี่น้องสองคนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 25, 'พระเยซูทรงเรียกเขาทั้งหลายมาตรัสว่า “ท่านทั้งหลายรู้อยู่ว่า ผู้ครอบครองของคนต่างชาติย่อมเป็นเจ้าเหนือเขา และผู้ใหญ่ทั้งหลายก็ใช้อํานาจบังคับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 26, 'แต่ในพวกท่านหาเป็นอย่างนั้นไม่ ถ้าผู้ใดใคร่จะได้เป็นใหญ่ในพวกท่าน ผู้นั้นจะต้องเป็นผู้ปรนนิบัติท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 27, 'ถ้าผู้ใดใคร่จะได้เป็นเอกเป็นต้นในพวกท่าน ผู้นั้นจะต้องเป็นผู้รับใช้ของพวกท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 28, 'อย่างที่บุตรมนุษย์มิได้มาเพื่อรับการปรนนิบัติ แต่มาเพื่อจะปรนนิบัติ และประทานชีวิตของท่านให้เป็นค่าไถ่สําหรับคนเป็นอันมาก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 29, 'เมื่อพระองค์กับเหล่าสาวกออกไปจากเมืองเยรีโค ฝูงชนเป็นอันมากก็ตามพระองค์ไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 30, 'และดูเถิด มีชายตาบอดสองคนนั่งอยู่ริมหนทาง เมื่อเขาได้ยินว่าพระเยซูเสด็จผ่านมา จึงร้องว่า “โอ พระองค์ผู้เป็นบุตรดาวิดเจ้าข้า ขอทรงพระเมตตาข้าพระองค์เถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 31, 'ฝ่ายประชาชนก็ห้ามเขาให้นิ่งเสีย แต่เขายิ่งร้องขึ้นอีกว่า “โอ พระองค์ผู้เป็นบุตรดาวิดเจ้าข้า ขอทรงพระเมตตาข้าพระองค์เถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 32, 'พระเยซูจึงหยุดประทับยืนอยู่ เรียกเขามา และตรัสว่า “ท่านทั้งสองใคร่จะให้เราทําอะไรเพื่อท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 33, 'พวกเขาทูลพระองค์ว่า “พระองค์เจ้าข้า ขอให้ตาของข้าพระองค์มองเห็น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 34, 'พระเยซูจึงมีพระทัยเมตตา ก็ทรงถูกต้องตาเขา ในทันใดนั้นตาของเขาก็เห็นได้และเขาทั้งสองได้ติดตามพระองค์ไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 1, 'ครั้นพระองค์กับพวกสาวกมาใกล้กรุงเยรูซาเล็ม ถึงหมู่บ้านเบธฟายี เชิงภูเขามะกอกเทศ แล้วพระเยซูทรงใช้สาวกสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 2, 'ตรัสสั่งเขาว่า “จงเข้าไปในหมู่บ้านที่อยู่ตรงหน้าท่าน ทันทีท่านจะพบแม่ลาตัวหนึ่งผูกอยู่กับลูกของมัน จงแก้จูงมาให้เรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 3, 'ถ้ามีผู้ใดว่าอะไรแก่ท่าน ท่านจงว่า ‘องค์พระผู้เป็นเจ้าต้องพระประสงค์’ แล้วเขาจะปล่อยให้มาทันที”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 4, 'เหตุการณ์ทั้งปวงนี้เกิดขึ้นเพื่อจะให้พระวจนะที่ตรัสโดยศาสดาพยากรณ์สําเร็จซึ่งว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 5, '‘จงบอกธิดาแห่งศิโยนว่า ดูเถิด กษัตริย์ของเธอเสด็จมาหาเธอ โดยพระทัยอ่อนสุภาพ ทรงแม่ลากับลูกของมัน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 6, 'สาวกทั้งสองคนนั้นก็ไปทําตามพระเยซูตรัสสั่งเขาไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 7, 'จึงจูงแม่ลากับลูกของมันมา และเอาเสื้อผ้าของตนปูบนหลัง แล้วเขาให้พระองค์ทรงลานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 8, 'ฝูงชนเป็นอันมากได้เอาเสื้อผ้าของตนปูตามถนนหนทาง คนอื่นๆก็ตัดกิ่งไม้มาปูตามถนน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 9, 'ฝ่ายฝูงชนซึ่งเดินไปข้างหน้ากับผู้ที่ตามมาข้างหลังก็พร้อมกันโห่ร้องว่า “โฮซันนาแก่ราชโอรสของดาวิด ‘ขอให้พระองค์ผู้เสด็จมาในพระนามขององค์พระผู้เป็นเจ้าทรงพระเจริญ โฮซันนา’ ในที่สูงสุด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 10, 'เมื่อพระองค์เสด็จเข้าไปในกรุงเยรูซาเล็มแล้ว ประชาชนทั่วทั้งกรุงก็พากันแตกตื่นถามว่า “ท่านผู้นี้เป็นผู้ใด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 11, 'ฝูงชนก็ตอบว่า “นี่คือเยซูศาสดาพยากรณ์ซึ่งมาจากนาซาเร็ธแคว้นกาลิลี”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 12, 'พระเยซูจึงเสด็จเข้าไปในพระวิหารของพระเจ้า ทรงขับไล่บรรดาผู้ซื้อขายในพระวิหารนั้น และคว่ําโต๊ะผู้รับแลกเงิน กับทั้งคว่ําที่นั่งผู้ขายนกเขาเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 13, 'และตรัสกับเขาว่า “มีพระวจนะเขียนไว้ว่า ‘นิเวศของเราเขาจะเรียกว่าเป็นนิเวศอธิษฐาน’ แต่เจ้าทั้งหลายมากระทําให้เป็น ‘ถ้ําของพวกโจร’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 14, 'คนตาบอดและคนง่อยพากันมาเฝ้าพระองค์ในพระวิหาร พระองค์ได้ทรงรักษาเขาให้หาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 15, 'แต่เมื่อพวกปุโรหิตใหญ่กับพวกธรรมาจารย์ได้เห็นการมหัศจรรย์ที่พระองค์ทรงกระทํา ทั้งได้ยินหมู่เด็กร้องในพระวิหารว่า “โฮซันนาแก่ราชโอรสของดาวิด” เขาทั้งหลายก็พากันแค้นเคือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 16, 'และจึงทูลพระองค์ว่า “ท่านไม่ได้ยินคําที่เขาร้องหรือ” พระเยซูตรัสตอบเขาว่า “ได้ยินแล้ว พวกท่านยังไม่เคยอ่านหรือว่า ‘จากปากของเด็กอ่อนและเด็กที่ยังดูดนม ท่านก็ได้รับคําสรรเสริญอันจริงแท้’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 17, 'พระองค์ได้ทรงละจากเขาและเสด็จออกจากกรุงไปประทับอยู่ที่หมู่บ้านเบธานี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 18, 'ครั้นเวลาเช้าขณะที่พระองค์เสด็จกลับไปยังกรุงอีก พระองค์ก็ทรงหิวพระกระยาหาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 19, 'และเมื่อพระองค์ทรงทอดพระเนตรเห็นต้นมะเดื่อต้นหนึ่งอยู่ริมทาง พระองค์ก็ทรงดําเนินเข้าไปใกล้ เห็นต้นมะเดื่อนั้นไม่มีผลมีแต่ใบเท่านั้น จึงตรัสกับต้นมะเดื่อนั้นว่า “เจ้าจงอย่ามีผลอีกต่อไป” ทันใดนั้นต้นมะเดื่อก็เหี่ยวแห้งไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 20, 'ครั้นเหล่าสาวกได้เห็นก็ประหลาดใจ แล้วว่า “เป็นอย่างไรหนอต้นมะเดื่อจึงเหี่ยวแห้งไปในทันใด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 21, 'ฝ่ายพระเยซูตรัสตอบเขาว่า “เราบอกความจริงแก่ท่านทั้งหลายว่า ถ้าท่านมีความเชื่อและมิได้สงสัย ท่านจะกระทําได้เช่นที่เราได้กระทําแก่ต้นมะเดื่อนี้ ยิ่งกว่านั้น ถึงแม้ท่านจะสั่งภูเขานี้ว่า ‘จงถอยไปลงทะเล’ ก็จะสําเร็จได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 22, 'สิ่งสารพัดซึ่งท่านอธิษฐานขอด้วยความเชื่อ ท่านจะได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 23, 'เมื่อพระองค์เสด็จเข้าไปในพระวิหารในเวลาที่ทรงสั่งสอนอยู่ พวกปุโรหิตใหญ่และพวกผู้ใหญ่ของประชาชนมาหาพระองค์ทูลถามว่า “ท่านมีสิทธิอันใดจึงได้ทําเช่นนี้ ใครให้สิทธินี้แก่ท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 24, 'พระเยซูตรัสตอบเขาว่า “เราจะถามท่านทั้งหลายสักข้อหนึ่งด้วย ซึ่งถ้าท่านบอกเราได้ เราจะบอกท่านเหมือนกันว่าเรากระทําการนี้โดยสิทธิอันใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 25, 'คือบัพติศมาของยอห์นนั้นมาจากไหน มาจากสวรรค์หรือจากมนุษย์” เขาได้ปรึกษากันว่า “ถ้าเราจะว่า ‘มาจากสวรรค์’ ท่านจะถามเราว่า ‘เหตุไฉนท่านจึงไม่เชื่อยอห์นเล่า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 26, 'แต่ถ้าเราจะว่า ‘มาจากมนุษย์’ เราก็กลัวประชาชน เพราะประชาชนทั้งปวงถือว่ายอห์นเป็นศาสดาพยากรณ์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 27, 'เขาจึงทูลตอบพระเยซูว่า “พวกข้าพเจ้าไม่ทราบ” พระองค์จึงตรัสกับเขาว่า “เราจะไม่บอกท่านทั้งหลายเหมือนกันว่า เรากระทําการนี้โดยสิทธิอันใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 28, 'แต่ท่านทั้งหลายคิดเห็นอย่างไร ชายผู้หนึ่งมีบุตรชายสองคน บิดาไปหาบุตรคนแรกว่า ‘ลูกเอ๋ย วันนี้จงไปทํางานในสวนองุ่นของพ่อเถิด’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 29, 'บุตรคนนั้นตอบว่า ‘ข้าพเจ้าไม่ไป’ แต่ภายหลังกลับใจแล้วไปทํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 30, 'บิดาจึงไปหาบุตรคนที่สองพูดเช่นเดียวกัน บุตรนั้นตอบว่า ‘ข้าพเจ้าไปขอรับ’ แต่ไม่ไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 31, 'บุตรสองคนนี้คนไหนเป็นผู้ทําตามความประสงค์ของบิดาเล่า” เขาทูลตอบพระองค์ว่า “คือบุตรคนแรก” พระเยซูตรัสตอบเขาว่า “เราบอกความจริงแก่ท่านทั้งหลายว่า พวกเก็บภาษีและหญิงโสเภณีก็เข้าไปในอาณาจักรของพระเจ้าก่อนท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 32, 'ด้วยยอห์นได้มาหาพวกท่านด้วยทางแห่งความชอบธรรม ท่านหาเชื่อยอห์นไม่ แต่พวกเก็บภาษีและพวกหญิงโสเภณีได้เชื่อยอห์น ฝ่ายท่านทั้งหลายถึงแม้ได้เห็นแล้ว ภายหลังก็มิได้กลับใจเชื่อยอห์น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 33, 'จงฟังคําอุปมาอีกเรื่องหนึ่งว่า ยังมีเจ้าของบ้านผู้หนึ่งได้ทําสวนองุ่น แล้วล้อมรั้วต้นไม้ไว้รอบ เขาได้สกัดบ่อย่ําองุ่นในสวน และสร้างหอเฝ้า ให้พวกชาวสวนเช่าแล้วก็ไปเมืองไกล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 34, 'ครั้นฤดูเก็บผลองุ่นใกล้เข้ามา เขาจึงใช้พวกผู้รับใช้ไปหาคนเช่าสวน เพื่อจะรับผลองุ่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 35, 'และคนเช่าสวนนั้นจับพวกผู้รับใช้ของเขา เฆี่ยนตีเสียคนหนึ่ง ฆ่าเสียคนหนึ่ง เอาหินขว้างเสียให้ตายคนหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 36, 'อีกครั้งหนึ่งเขาก็ใช้ผู้รับใช้คนอื่นๆไปมากกว่าครั้งก่อน แต่พวกเช่าสวนก็ได้ทําแก่เขาอย่างนั้นอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 37, 'ครั้งสุดท้ายเขาจึงใช้บุตรชายของเขาไปหา พูดว่า ‘พวกเขาคงจะเคารพบุตรชายของเรา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 38, 'แต่เมื่อบรรดาคนเช่าสวนเห็นบุตรชายเจ้าของบ้านก็พูดกันว่า ‘คนนี้แหละเป็นผู้รับมรดก มาเถิด ให้เราฆ่าเขา แล้วให้เรายึดมรดกของเขาเสีย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 39, 'เขาจึงพากันจับบุตรนั้น ผลักออกไปนอกสวนองุ่นแล้วฆ่าเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 40, 'เหตุฉะนั้น เมื่อเจ้าของสวนองุ่นมา เขาจะทําอะไรแก่คนเช่าสวนเหล่านั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 41, 'เขาทั้งหลายทูลตอบพระองค์ว่า “เขาจะทําลายล้างคนชั่วเหล่านั้นอย่างแสนสาหัส และจะให้สวนองุ่นนั้นแก่คนเช่าอื่นๆที่จะแบ่งผลโดยถูกต้องตามฤดูกาลแก่เขาต่อไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 42, 'พระเยซูตรัสกับเขาว่า “ท่านทั้งหลายยังไม่เคยอ่านในพระคัมภีร์หรือซึ่งว่า ‘ศิลาซึ่งช่างก่อได้ปฏิเสธเสีย ได้กลับกลายเป็นศิลามุมเอกแล้ว การนี้เป็นมาจากองค์พระผู้เป็นเจ้า เป็นการมหัศจรรย์ประจักษ์แก่ตาเรา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 43, 'เหตุฉะนั้นเราบอกท่านว่า อาณาจักรของพระเจ้าจะถูกเอาไปเสียจากท่าน และยกให้แก่ชนชาติหนึ่งซึ่งจะกระทําให้เกิดผลสมกับอาณาจักรนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 44, 'ผู้ใดล้มทับศิลานี้ ผู้นั้นจะต้องแตกหักไป แต่ศิลานี้จะตกทับผู้ใด ก็จะบดขยี้ผู้นั้นจนแหลกเป็นผุยผง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 45, 'ครั้นพวกปุโรหิตใหญ่กับพวกฟาริสีได้ยินคําอุปมาของพระองค์ พวกเขาก็หยั่งรู้ว่าพระองค์ตรัสเล็งถึงพวกเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 46, 'แต่เมื่อพวกเขาอยากจะจับพระองค์ เขาก็กลัวประชาชน เพราะประชาชนนับถือพระองค์ว่าเป็นศาสดาพยากรณ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 1, 'พระเยซูตรัสแก่เขาเป็นคําอุปมาอีกว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 2, '“อาณาจักรแห่งสวรรค์เปรียบเหมือนกษัตริย์องค์หนึ่ง ซึ่งได้จัดพิธีอภิเษกสมรสสําหรับราชโอรสของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 3, 'แล้วใช้พวกผู้รับใช้ไปตามผู้ที่ได้รับเชิญมาในงานอภิเษกสมรสนั้น แต่เขาไม่ใคร่จะมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 4, 'ท่านยังใช้พวกผู้รับใช้อื่นไปอีก รับสั่งว่า ‘ให้บอกผู้รับเชิญนั้นว่า ดูเถิด เราได้จัดการเลี้ยงไว้แล้ว วัวและสัตว์ขุนแล้วของเราก็ฆ่าไว้เสร็จ สิ่งสารพัดก็เตรียมไว้พร้อม จงมาในพิธีอภิเษกสมรสนี้เถิด’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 5, 'แต่เขาก็เพิกเฉยและไปเสีย คนหนึ่งไปไร่นาของตน อีกคนหนึ่งก็ไปทําการค้าขาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 6, 'ฝ่ายพวกนอกนั้นก็จับพวกผู้รับใช้ของท่าน ทําการอัปยศต่างๆแล้วฆ่าเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 7, 'แต่ครั้นกษัตริย์องค์นั้นได้ยินแล้ว ท่านก็ทรงพระพิโรธ จึงรับสั่งให้ยกกองทหารไป ปราบปรามฆาตกรเหล่านั้น และเผาเมืองเขาเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 8, 'แล้วท่านจึงรับสั่งแก่พวกผู้รับใช้ของท่านว่า ‘งานสมรสก็พร้อมอยู่ แต่ผู้ที่ได้รับเชิญนั้นไม่สมกับงาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 9, 'เหตุฉะนั้น จงออกไปตามทางหลวง พบคนมากเท่าใดก็ให้เชิญมาในพิธีอภิเษกสมรสนี้’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 10, 'ผู้รับใช้เหล่านั้นจึงออกไปเชิญคนทั้งปวงตามทางหลวงแล้วแต่จะพบ ให้มาทั้งดีและชั่วจนงานสมรสนั้นเต็มด้วยแขก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 11, 'แต่เมื่อกษัตริย์องค์นั้นเสด็จทอดพระเนตรแขก ก็เห็นผู้หนึ่งมิได้สวมเสื้อสําหรับงานสมรส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 12, 'ท่านจึงรับสั่งถามเขาว่า ‘สหายเอ๋ย เหตุไฉนท่านจึงมาที่นี่โดยไม่สวมเสื้อสําหรับงานสมรส’ ผู้นั้นก็นิ่งอยู่พูดไม่ออก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 13, 'กษัตริย์จึงรับสั่งแก่พวกผู้รับใช้ว่า ‘จงมัดมือมัดเท้าคนนี้เอาไปทิ้งเสียที่มืดภายนอก ที่นั่นจะมีการร้องไห้และขบเขี้ยวเคี้ยวฟัน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 14, 'ด้วยผู้ที่ได้รับเชิญก็มาก แต่ผู้ที่ทรงเลือกก็น้อย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 15, 'ขณะนั้นพวกฟาริสีไปปรึกษากันว่า พวกเขาจะจับผิดในถ้อยคําของพระองค์ได้อย่างไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 16, 'พวกเขาจึงใช้พวกสาวกของตนกับพวกเฮโรดให้ไปทูลพระองค์ว่า “อาจารย์เจ้าข้า ข้าพเจ้าทั้งหลายทราบอยู่ว่าท่านเป็นคนซื่อสัตย์ และสั่งสอนทางของพระเจ้าด้วยความสัตย์จริง โดยมิได้เอาใจผู้ใด เพราะท่านมิได้เห็นแก่หน้าผู้ใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 17, 'เหตุฉะนั้น ขอโปรดบอกให้พวกข้าพเจ้าทราบว่า ท่านคิดเห็นอย่างไร การที่จะส่งส่วยให้แก่ซีซาร์นั้น ถูกต้องตามพระราชบัญญัติหรือไม่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 18, 'แต่พระเยซูทรงล่วงรู้ถึงความชั่วร้ายของเขาจึงตรัสว่า “พวกหน้าซื่อใจคด เจ้าทดลองเราทําไม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 19, 'จงเอาเงินที่จะเสียส่วยนั้นมาให้เราดูก่อน” เขาจึงเอาเงินตราเหรียญหนึ่งถวายพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 20, 'พระองค์ตรัสถามเขาว่า “รูปและคําจารึกนี้เป็นของใคร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 21, 'เขาทูลพระองค์ว่า “ของซีซาร์” แล้วพระองค์ตรัสกับเขาว่า “เหตุฉะนั้นของของซีซาร์จงถวายแก่ซีซาร์ และของของพระเจ้าจงถวายแด่พระเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 22, 'ครั้นเขาได้ยินคําตรัสตอบของพระองค์นั้นแล้ว เขาก็ประหลาดใจ จึงละพระองค์ไว้และพากันกลับไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 23, 'ในวันนั้นมีพวกสะดูสีมาหาพระองค์ พวกนี้เป็นผู้ที่กล่าวว่า การฟื้นขึ้นมาจากความตายไม่มี เขาจึงทูลถามพระองค์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 24, '“อาจารย์เจ้าข้า โมเสสสั่งว่า ‘ถ้าผู้ใดตายยังไม่มีบุตร ก็ให้น้องชายรับพี่สะใภ้ สืบเชื้อสายของพี่ชายไว้’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 25, 'ในพวกเรามีพี่น้องผู้ชายเจ็ดคน พี่หัวปีมีภรรยาแล้วก็ตายเมื่อยังไม่มีบุตร ก็ละภรรยาไว้ให้แก่น้องชาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 26, 'ฝ่ายคนที่สองที่สามก็เช่นเดียวกัน จนถึงคนที่เจ็ด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 27, 'ในที่สุดหญิงนั้นก็ตายด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 28, 'เหตุฉะนั้นในวันที่จะฟื้นขึ้นมาจากความตาย หญิงนั้นจะเป็นภรรยาของผู้ใดในเจ็ดคนนั้น ด้วยนางได้เป็นภรรยาของชายทั้งเจ็ดคนแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 29, 'พระเยซูตรัสตอบเขาว่า “พวกท่านผิดแล้ว เพราะท่านไม่รู้พระคัมภีร์หรือฤทธิ์เดชของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 30, 'ด้วยว่าเมื่อมนุษย์ฟื้นขึ้นมาจากความตายนั้น จะไม่มีการสมรสหรือยกให้เป็นสามีภรรยากันอีก แต่จะเป็นเหมือนพวกทูตสวรรค์ของพระเจ้าในสวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 31, 'แต่เรื่องคนตายกลับฟื้นนั้น ท่านทั้งหลายยังไม่ได้อ่านหรือ ซึ่งพระเจ้าได้ตรัสไว้กับพวกท่านว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 32, '‘เราเป็นพระเจ้าของอับราฮัม เป็นพระเจ้าของอิสอัค และเป็นพระเจ้าของยาโคบ’ พระเจ้ามิได้เป็นพระเจ้าของคนตาย แต่ทรงเป็นพระเจ้าของคนเป็น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 33, 'ประชาชนทั้งปวงเมื่อได้ยินก็ประหลาดใจด้วยคําสั่งสอนของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 34, 'แต่พวกฟาริสีเมื่อได้ยินว่าพระองค์ทรงกระทําให้พวกสะดูสีนิ่งอั้นอยู่ จึงประชุมกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 35, 'มีนักกฎหมายผู้หนึ่งในพวกเขาทดลองพระองค์โดยถามพระองค์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 36, '“อาจารย์เจ้าข้า ในพระราชบัญญัตินั้น พระบัญญัติข้อใดสําคัญที่สุด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 37, 'พระเยซูทรงตอบเขาว่า “‘จงรักองค์พระผู้เป็นเจ้าผู้เป็นพระเจ้าของเจ้า ด้วยสุดจิตสุดใจของเจ้า และด้วยสิ้นสุดความคิดของเจ้า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 38, 'นี่แหละเป็นพระบัญญัติข้อต้นและข้อใหญ่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 39, 'ข้อที่สองก็เหมือนกัน คือ ‘จงรักเพื่อนบ้านเหมือนรักตนเอง’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 40, 'พระราชบัญญัติและคําพยากรณ์ทั้งสิ้นก็ขึ้นอยู่กับพระบัญญัติสองข้อนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 41, 'เมื่อพวกฟาริสียังประชุมกันอยู่ที่นั่น พระเยซูทรงถามพวกเขาว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 42, '“พวกท่านคิดอย่างไรด้วยเรื่องพระคริสต์ พระองค์ทรงเป็นบุตรของผู้ใด” เขาตอบพระองค์ว่า “เป็นบุตรของดาวิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 43, 'พระองค์ตรัสถามเขาว่า “ถ้าอย่างนั้นเป็นไฉนดาวิดโดยเดชพระวิญญาณจึงได้เรียกพระองค์ว่า องค์พระผู้เป็นเจ้า และรับสั่งว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 44, '‘องค์พระผู้เป็นเจ้าตรัสกับองค์พระผู้เป็นเจ้าของข้าพเจ้าว่า จงนั่งที่ขวามือของเรา จนกว่าเราจะกระทําให้ศัตรูของท่านเป็นแท่นรองเท้าของท่าน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 45, 'ถ้าดาวิดเรียกพระองค์ว่าองค์พระผู้เป็นเจ้า พระองค์จะเป็นบุตรของดาวิดอย่างไรได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 46, 'ไม่มีผู้หนึ่งผู้ใดอาจตอบพระองค์สักคําหนึ่ง ตั้งแต่วันนั้นมา ไม่มีใครกล้าซักถามพระองค์ต่อไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 1, 'ครั้งนั้นพระเยซูตรัสกับฝูงชนและพวกสาวกของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 2, 'ว่า “พวกธรรมาจารย์กับพวกฟาริสีนั่งบนที่นั่งของโมเสส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 3, 'เหตุฉะนั้นทุกสิ่งซึ่งเขาสั่งสอนพวกท่าน จงถือประพฤติตาม เว้นแต่การกระทําของเขา อย่าได้ทําตามเลย เพราะเขาเป็นแต่ผู้สั่งสอน แต่เขาเองหาทําตามไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 4, 'ด้วยเขาเอาภาระหนักและแบกยากวางบนบ่ามนุษย์ ส่วนเขาเองแม้แต่นิ้วเดียวก็ไม่จับต้องเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 5, 'การกระทําของเขาทุกอย่างเป็นการอวดให้คนเห็นเท่านั้น เขาใช้กลักพระบัญญัติอย่างใหญ่ สวมเสื้อที่มีพู่ห้อยอันยาว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 6, 'เขาชอบที่อันมีเกียรติในการเลี้ยงและที่นั่งตําแหน่งสูงในธรรมศาลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 7, 'กับชอบรับการคํานับที่กลางตลาด และชอบให้คนเรียกเขาว่า ‘รับบี รับบี’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 8, 'ท่านทั้งหลายอย่าให้ใครเรียกท่านว่า ‘รับบี’ ด้วยท่านมีพระอาจารย์แต่ผู้เดียวคือพระคริสต์ และท่านทั้งหลายเป็นพี่น้องกันทั้งหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 9, 'และอย่าเรียกผู้ใดในโลกว่าเป็นบิดา เพราะท่านมีพระบิดาแต่ผู้เดียว คือผู้ที่ทรงสถิตในสวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 10, 'อย่าให้ผู้ใดเรียกท่านว่า ‘นาย’ ด้วยว่านายของท่านมีแต่ผู้เดียวคือพระคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 11, 'ผู้ใดที่เป็นใหญ่ที่สุดในพวกท่าน ผู้นั้นจะเป็นผู้รับใช้ของท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 12, 'ผู้ใดจะยกตัวขึ้น ผู้นั้นจะต้องถูกเหยียดลง ผู้ใดถ่อมตัวลง ผู้นั้นจะได้รับการยกขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 13, 'วิบัติแก่เจ้า พวกธรรมาจารย์และพวกฟาริสี คนหน้าซื่อใจคด ด้วยว่าพวกเจ้าปิดประตูอาณาจักรแห่งสวรรค์ไว้จากมนุษย์ เพราะพวกเจ้าเองไม่ยอมเข้าไป และเมื่อคนอื่นจะเข้าไป พวกเจ้าก็ขัดขวางไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 14, 'วิบัติแก่เจ้า พวกธรรมาจารย์และพวกฟาริสี คนหน้าซื่อใจคด ด้วยพวกเจ้าริบเอาเรือนของหญิงม่าย และแสร้งอธิษฐานเสียยืดยาว เพราะฉะนั้นพวกเจ้าจะได้รับพระอาชญามากยิ่งขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 15, 'วิบัติแก่เจ้า พวกธรรมาจารย์และพวกฟาริสี คนหน้าซื่อใจคด ด้วยพวกเจ้าเที่ยวไปตามทางทะเลและทางบกทั่วไปเพื่อจะได้แม้แต่คนเดียวเข้าจารีต เมื่อได้แล้วเจ้าก็ทําให้เขากลายเป็นลูกแห่งนรกยิ่งกว่าตัวเจ้าเองถึงสองเท่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 16, 'วิบัติแก่เจ้า คนนําทางตาบอด เจ้ากล่าวว่า ‘ผู้ใดจะสาบานอ้างพระวิหาร คําสาบานนั้นไม่ผูกมัด แต่ผู้ใดจะสาบานอ้างทองคําของพระวิหาร ผู้นั้นจะต้องกระทําตามคําสาบาน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 17, 'คนโฉดเขลาตาบอด สิ่งไหนจะสําคัญกว่า ทองคําหรือพระวิหารซึ่งกระทําให้ทองคํานั้นศักดิ์สิทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 18, 'และว่า ‘ผู้ใดจะสาบานอ้างแท่นบูชา คําสาบานนั้นไม่ผูกมัด แต่ผู้ใดจะสาบานอ้างเครื่องตั้งถวายบนแท่นบูชานั้น ผู้นั้นต้องกระทําตามคําสาบาน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 19, 'คนโฉดเขลาตาบอด สิ่งใดจะสําคัญกว่า เครื่องตั้งถวายหรือแท่นบูชาที่กระทําให้เครื่องตั้งถวายนั้นศักดิ์สิทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 20, 'เหตุฉะนี้ ผู้ใดจะสาบานอ้างแท่นบูชา ก็สาบานอ้างแท่นบูชาและสิ่งสารพัดซึ่งอยู่บนแท่นบูชานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 21, 'ผู้ใดจะสาบานอ้างพระวิหาร ก็สาบานอ้างพระวิหารและอ้างพระองค์ผู้ทรงสถิตในพระวิหารนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 22, 'ผู้ใดจะสาบานอ้างสวรรค์ ก็สาบานอ้างพระที่นั่งของพระเจ้าและอ้างพระองค์ผู้ประทับบนพระที่นั่งนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 23, 'วิบัติแก่เจ้า พวกธรรมาจารย์และพวกฟาริสี คนหน้าซื่อใจคด ด้วยพวกเจ้าถวายสิบชักหนึ่งของสะระแหน่ ยี่หร่าและขมิ้น ส่วนข้อสําคัญแห่งพระราชบัญญัติ คือการพิพากษา ความเมตตาและความเชื่อนั้นได้ละเว้นเสีย สิ่งเหล่านั้นพวกเจ้าควรได้กระทําอยู่แล้ว แต่สิ่งอื่นนั้นไม่ควรละเว้นด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 24, 'คนนําทางตาบอด เจ้ากรองลูกน้ําออก แต่กลืนตัวอูฐเข้าไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 25, 'วิบัติแก่เจ้า พวกธรรมาจารย์และพวกฟาริสี คนหน้าซื่อใจคด ด้วยเจ้าขัดชําระถ้วยชามแต่ภายนอก ส่วนภายในถ้วยชามนั้นเต็มด้วยโจรกรรมและการมัวเมากิเลส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 26, 'พวกฟาริสีตาบอด จงชําระสิ่งที่อยู่ภายในถ้วยชามเสียก่อน เพื่อข้างนอกจะได้สะอาดด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 27, 'วิบัติแก่เจ้า พวกธรรมาจารย์และพวกฟาริสี คนหน้าซื่อใจคด เพราะว่าเจ้าเป็นเหมือนอุโมงค์ฝังศพซึ่งฉาบด้วยปูนขาว ข้างนอกดูงดงามจริงๆ แต่ข้างในเต็มไปด้วยกระดูกคนตายและการโสโครกสารพัด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 28, 'เจ้าทั้งหลายก็เป็นอย่างนั้นแหละ ภายนอกนั้นปรากฏแก่มนุษย์ว่าเป็นคนชอบธรรม แต่ภายในเต็มไปด้วยความหน้าซื่อใจคดและความชั่วช้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 29, 'วิบัติแก่เจ้า พวกธรรมาจารย์และพวกฟาริสี คนหน้าซื่อใจคด เพราะพวกเจ้าก่อสร้างอุโมงค์ฝังศพของพวกศาสดาพยากรณ์ และตกแต่งอุโมงค์ฝังศพของผู้ชอบธรรมให้งดงาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 30, 'แล้วกล่าวว่า ‘ถ้าเราได้อยู่ในสมัยบรรพบุรุษของเรานั้น เราจะมีส่วนกับเขาในการทําโลหิตของพวกศาสดาพยากรณ์ให้ตกก็หามิได้’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 31, 'อย่างนั้นเจ้าทั้งหลายก็เป็นพยานปรักปรําตนเองว่า เจ้าเป็นบุตรของผู้ที่ได้ฆ่าศาสดาพยากรณ์เหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 32, 'เจ้าทั้งหลายจงกระทําตามที่บรรพบุรุษได้กระทํานั้นให้ครบถ้วนเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 33, 'เจ้าพวกงู เจ้าชาติงูร้าย เจ้าจะพ้นการลงโทษในนรกอย่างไรได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 34, 'เหตุฉะนั้น ดูเถิด เราใช้พวกศาสดาพยากรณ์ พวกนักปราชญ์ และพวกธรรมาจารย์ต่างๆไปหาพวกเจ้า เจ้าก็ฆ่าเสียบ้าง ตรึงเสียที่กางเขนบ้าง เฆี่ยนตีในธรรมศาลาของเจ้าบ้าง ข่มเหงไล่ออกจากเมืองนี้ไปเมืองโน้นบ้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 35, 'ดังนั้นบรรดาโลหิตอันชอบธรรมซึ่งตกที่แผ่นดินโลก ตั้งแต่โลหิตของอาแบลผู้ชอบธรรมจนถึงโลหิตของเศคาริยาห์บุตรชายบารัคยา ที่พวกเจ้าได้ฆ่าเสียในระหว่างพระวิหารกับแท่นบูชานั้น ย่อมตกบนพวกเจ้าทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 36, 'เราบอกความจริงแก่เจ้าทั้งหลายว่า บรรดาสิ่งเหล่านี้จะตกกับคนสมัยนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 37, 'โอ เยรูซาเล็มๆ ที่ได้ฆ่าบรรดาศาสดาพยากรณ์ และเอาหินขว้างผู้ที่ได้รับใช้มาหาเจ้าถึงตาย เราใคร่จะรวบรวมลูกของเจ้าไว้เนืองๆ เหมือนแม่ไก่กกลูกอยู่ใต้ปีกของมัน แต่เจ้าไม่ยอมเลยหนอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 38, 'ดูเถิด ‘บ้านเมืองของเจ้าจะถูกละทิ้งให้รกร้างแก่เจ้า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 39, 'ด้วยเราว่าแก่เจ้าทั้งหลายว่า เจ้าจะไม่เห็นเราอีกจนกว่าเจ้าจะกล่าวว่า ‘ขอให้พระองค์ผู้เสด็จมาในพระนามขององค์พระผู้เป็นเจ้าทรงพระเจริญ’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 1, 'ฝ่ายพระเยซูทรงออกจากพระวิหาร แล้วพวกสาวกของพระองค์มาชี้ตึกทั้งหลายของพระวิหารให้พระองค์ทอดพระเนตร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 2, 'พระเยซูจึงตรัสกับเขาว่า “สิ่งสารพัดเหล่านี้พวกท่านเห็นแล้วมิใช่หรือ เราบอกความจริงแก่ท่านว่า ศิลาที่ซ้อนทับกันอยู่ที่นี่ ซึ่งจะไม่ถูกทําลายลงก็หามิได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 3, 'เมื่อพระองค์ประทับบนภูเขามะกอกเทศ พวกสาวกมาเฝ้าพระองค์ส่วนตัวกราบทูลว่า “ขอทรงโปรดให้ข้าพระองค์ทั้งหลายทราบว่า เหตุการณ์เหล่านี้จะบังเกิดขึ้นเมื่อไร สิ่งไรเป็นหมายสําคัญว่าพระองค์จะเสด็จมา และวาระสุดท้ายของโลกนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 4, 'พระเยซูตรัสตอบเขาว่า “ระวังให้ดี อย่าให้ผู้ใดล่อลวงท่านให้หลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 5, 'ด้วยว่าจะมีหลายคนมาต่างอ้างนามของเรา กล่าวว่า ‘เราเป็นพระคริสต์’ เขาจะล่อลวงคนเป็นอันมากให้หลงไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 6, 'ท่านทั้งหลายจะได้ยินถึงเรื่องสงครามและข่าวลือเรื่องสงคราม คอยระวังอย่าตื่นตระหนกเลย ด้วยว่าบรรดาสิ่งเหล่านี้จําต้องบังเกิดขึ้น แต่ที่สุดปลายยังไม่มาถึง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 7, 'เพราะประชาชาติจะลุกขึ้นต่อสู้ประชาชาติ ราชอาณาจักรต่อสู้ราชอาณาจักร ทั้งจะเกิดกันดารอาหารและโรคระบาดอย่างร้ายแรงและแผ่นดินไหวในที่ต่างๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 8, 'เหตุการณ์ทั้งปวงนี้เป็นขั้นแรกแห่งความทุกข์ลําบาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 9, 'ในเวลานั้นเขาจะมอบท่านทั้งหลายไว้ให้ทนทุกข์ลําบากและจะฆ่าท่านเสีย และประชาชาติต่างๆจะเกลียดชังพวกท่านเพราะนามของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 10, 'คราวนั้นคนเป็นอันมากจะถดถอยไปและทรยศกันและกัน ทั้งจะเกลียดชังซึ่งกันและกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 11, 'จะมีผู้พยากรณ์เท็จหลายคนเกิดขึ้นและล่อลวงคนเป็นอันมากให้หลงไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 12, 'ความรักของคนเป็นอันมากจะเยือกเย็นลง เพราะความชั่วช้าจะแผ่ขยายออกไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 13, 'แต่ผู้ที่ทนได้จนถึงที่สุด ผู้นั้นจะรอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 14, 'ข่าวประเสริฐเรื่องอาณาจักรนี้จะประกาศไปทั่วโลกให้เป็นคําพยานแก่บรรดาประชาชาติ แล้วที่สุดปลายจะมาถึง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 15, 'เหตุฉะนั้น เมื่อท่านทั้งหลายเห็นสิ่งที่น่าสะอิดสะเอียนซึ่งกระทําให้เกิดการรกร้างว่างเปล่า ที่ดาเนียลศาสดาพยากรณ์ได้กล่าวถึงนั้น ตั้งอยู่ในสถานบริสุทธิ์” (ผู้ใดก็ตามที่ได้อ่านก็ให้ผู้นั้นเข้าใจเอาเถิด)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 16, '“เวลานั้นให้ผู้ที่อยู่ในแคว้นยูเดียหนีไปยังภูเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 17, 'ผู้ที่อยู่บนดาดฟ้าหลังคาบ้าน อย่าให้ลงมาเก็บข้าวของใดๆออกจากบ้านของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 18, 'ผู้ที่อยู่ตามทุ่งนา อย่าให้กลับไปเอาเสื้อผ้าของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 19, 'แต่ในวันเหล่านั้น วิบัติจะเกิดขึ้นแก่หญิงที่มีครรภ์ หรือหญิงที่มีลูกอ่อนกินนมอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 20, 'จงอธิษฐานขอเพื่อการที่ท่านต้องหนีนั้นจะไม่ตกในฤดูหนาวหรือในวันสะบาโต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 21, 'ด้วยว่าในคราวนั้นจะเกิดความทุกข์ลําบากใหญ่ยิ่ง อย่างที่ไม่เคยมีตั้งแต่เริ่มโลกมาจนถึงเวลานี้ และจะไม่มีต่อไปอีกเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 22, 'และถ้ามิได้ทรงให้วันเหล่านั้นย่นสั้นเข้า จะไม่มีเนื้อหนังใดๆรอดได้เลย แต่เพราะทรงเห็นแก่ผู้ที่เลือกสรรไว้ จึงทรงให้วันเหล่านั้นย่นสั้นเข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 23, 'ในเวลานั้นถ้าผู้ใดจะบอกพวกท่านว่า ‘ดูเถิด พระคริสต์อยู่ที่นี่’ หรือ ‘อยู่ที่โน่น’ อย่าได้เชื่อเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 24, 'ด้วยว่าจะมีพระคริสต์เทียมเท็จและผู้พยากรณ์เทียมเท็จเกิดขึ้นหลายคน และจะทําหมายสําคัญอันใหญ่และการมหัศจรรย์ ถ้าเป็นไปได้จะล่อลวงแม้ผู้ที่ทรงเลือกสรรให้หลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 25, 'ดูเถิด เราได้บอกท่านทั้งหลายไว้ก่อนแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 26, 'เหตุฉะนั้น ถ้าใครจะบอกท่านทั้งหลายว่า ‘ดูเถิด ท่านผู้นั้นอยู่ในถิ่นทุรกันดาร’ ก็จงอย่าออกไป หรือจะว่า ‘ดูเถิด อยู่ที่ห้องลับ’ ก็จงอย่าเชื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 27, 'ด้วยว่าฟ้าแลบมาจากทิศตะวันออกส่องไปจนถึงทิศตะวันตกฉันใด การเสด็จมาของบุตรมนุษย์ก็จะเป็นฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 28, 'ด้วยว่าซากศพอยู่ที่ไหน ฝูงนกอินทรีก็จะตอมกันอยู่ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 29, 'แต่พอสิ้นความทุกข์ลําบากแห่งวันเหล่านั้นแล้ว ‘ดวงอาทิตย์จะมืดไปและดวงจันทร์จะไม่ส่องแสง ดวงดาวทั้งปวงจะตกจากฟ้า และบรรดาสิ่งที่มีอํานาจในท้องฟ้าจะสะเทือนสะท้านไป’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 30, 'เมื่อนั้นหมายสําคัญแห่งบุตรมนุษย์จะปรากฏขึ้นในท้องฟ้า ‘มนุษย์ทุกตระกูลทั่วโลกจะไว้ทุกข์’ แล้วเขาจะเห็น ‘บุตรมนุษย์เสด็จมาบนเมฆในท้องฟ้า’ พร้อมด้วยฤทธานุภาพและสง่าราศีเป็นอันมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 31, 'พระองค์จะทรงใช้เหล่าทูตสวรรค์ของพระองค์มาด้วยเสียงแตรอันดังยิ่งนัก ให้รวบรวมคนทั้งปวงที่พระองค์ทรงเลือกสรรไว้แล้วจากลมทั้งสี่ทิศนั้น ตั้งแต่ที่สุดฟ้าข้างนี้จนถึงที่สุดฟ้าข้างโน้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 32, 'บัดนี้ จงเรียนคําอุปมาเรื่องต้นมะเดื่อ เมื่อกิ่งก้านยังอ่อนและแตกใบแล้ว ท่านก็รู้ว่าฤดูร้อนใกล้จะถึงแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 33, 'เช่นนั้นแหละ เมื่อท่านทั้งหลายเห็นสิ่งทั้งปวงนี้ ก็ให้รู้ว่าเหตุการณ์นั้นมาใกล้จะถึงประตูแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 34, 'เราบอกความจริงแก่ท่านทั้งหลายว่า คนชั่วอายุนี้จะไม่ล่วงลับไปจนกว่าสิ่งทั้งปวงนี้จะสําเร็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 35, 'ฟ้าและดินจะล่วงไป แต่คําของเราจะสูญหายไปหามิได้เลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 36, 'แต่วันนั้น โมงนั้น ไม่มีใครรู้ ถึงบรรดาทูตสวรรค์ในสวรรค์ก็ไม่รู้ รู้แต่พระบิดาของเราองค์เดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 37, 'ด้วยสมัยของโนอาห์เป็นอย่างไร เมื่อบุตรมนุษย์เสด็จมาก็จะเป็นอย่างนั้นด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 38, 'เพราะว่าเมื่อก่อนวันน้ําท่วมนั้น คนทั้งหลายได้กินและดื่มกัน ทําการสมรสและยกให้เป็นสามีภรรยากัน จนถึงวันที่โนอาห์เข้าในนาวา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 39, 'และน้ําท่วมได้มากวาดเอาพวกเขาไปสิ้น โดยไม่ทันรู้ตัวฉันใด เมื่อบุตรมนุษย์เสด็จมาก็จะเป็นฉันนั้นด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 40, 'เมื่อนั้นสองคนจะอยู่ที่ทุ่งนา จะทรงรับคนหนึ่ง ทรงละคนหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 41, 'หญิงสองคนโม่แป้งอยู่ที่โรงโม่ จะทรงรับคนหนึ่ง ทรงละคนหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 42, 'เหตุฉะนั้นจงเฝ้าระวังอยู่ เพราะท่านไม่รู้ว่าองค์พระผู้เป็นเจ้าของท่านจะเสด็จมาเวลาใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 43, 'จงจําไว้อย่างนี้เถิดว่า ถ้าเจ้าของบ้านล่วงรู้ได้ว่าขโมยจะมายามใด เขาก็จะเฝ้าระวัง และไม่ยอมให้ทะลวงเรือนของเขาได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 44, 'เหตุฉะนั้น ท่านทั้งหลายจงเตรียมพร้อมไว้เช่นกัน เพราะในโมงที่ท่านไม่คิดไม่ฝันนั้นบุตรมนุษย์จะเสด็จมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 45, 'ใครเป็นผู้รับใช้สัตย์ซื่อและฉลาด ที่นายได้ตั้งไว้เหนือพวกผู้รับใช้สําหรับแจกอาหารตามเวลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 46, 'เมื่อนายมาพบเขากระทําอยู่อย่างนั้น ผู้รับใช้ผู้นั้นก็จะเป็นสุข');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 47, 'เราบอกความจริงแก่ท่านทั้งหลายว่า นายจะตั้งเขาไว้ให้ดูแลบรรดาข้าวของของท่านทุกอย่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 48, 'แต่ถ้าผู้รับใช้ชั่วนั้นจะคิดในใจว่า ‘นายของข้าคงมาช้า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 49, 'แล้วจะตั้งต้นโบยตีเพื่อนผู้รับใช้และกินดื่มอยู่กับพวกขี้เมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 50, 'นายของผู้รับใช้ผู้นั้นจะมาในวันที่เขาไม่คิด ในโมงที่เขาไม่รู้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 51, 'และจะทําโทษเขาถึงสาหัส ทั้งจะขับไล่ให้เขาไปเข้าส่วนกับพวกคนหน้าซื่อใจคด ซึ่งที่นั่นจะมีแต่การร้องไห้ขบเขี้ยวเคี้ยวฟัน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 1, '“เมื่อถึงวันนั้น อาณาจักรแห่งสวรรค์จะเปรียบเหมือนหญิงพรหมจารีสิบคนถือตะเกียงของตนออกไปรับเจ้าบ่าว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 2, 'ในพวกเธอเป็นคนที่มีปัญญาห้าคน และเป็นคนโง่ห้าคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 3, 'พวกที่โง่นั้นเอาตะเกียงของตนไป แต่หาได้เอาน้ํามันไปด้วยไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 4, 'แต่คนที่มีปัญญานั้นได้เอาน้ํามันใส่ภาชนะไปกับตะเกียงของตนด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 5, 'เมื่อเจ้าบ่าวยังช้าอยู่ พวกเธอทุกคนก็พากันง่วงเหงาและหลับไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 6, 'ครั้นเวลาเที่ยงคืนก็มีเสียงร้องมาว่า ‘ดูเถิด เจ้าบ่าวมาแล้ว จงออกมารับท่านเถิด’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 7, 'บรรดาหญิงพรหมจารีเหล่านั้นก็ลุกขึ้นตกแต่งตะเกียงของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 8, 'พวกที่โง่นั้นก็พูดกับพวกที่มีปัญญาว่า ‘ขอแบ่งน้ํามันของท่านให้เราบ้าง เพราะตะเกียงของเราดับอยู่’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 9, 'พวกที่มีปัญญาจึงตอบว่า ‘ทําอย่างนั้นไม่ได้ เกรงว่าน้ํามันจะไม่พอสําหรับเราและเจ้า จงไปหาคนขาย ซื้อสําหรับตัวเองจะดีกว่า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 10, 'เมื่อพวกเธอกําลังไปซื้อนั้นเจ้าบ่าวก็มาถึง ผู้ที่พร้อมอยู่แล้วก็ได้เข้าไปกับท่านในพิธีสมรสนั้น แล้วประตูก็ปิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 11, 'ภายหลังหญิงพรหมจารีอีกพวกหนึ่งก็มาร้องว่า ‘ท่านเจ้าข้าๆ ขอเปิดให้ข้าพเจ้าทั้งหลายด้วย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 12, 'ฝ่ายท่านตอบว่า ‘เราบอกความจริงแก่ท่านทั้งหลายว่า เราไม่รู้จักท่าน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 13, 'เหตุฉะนั้นจงเฝ้าระวังอยู่ เพราะท่านทั้งหลายไม่รู้กําหนดวันหรือโมงที่บุตรมนุษย์จะเสด็จมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 14, 'อาณาจักรแห่งสวรรค์ยังเปรียบเหมือนชายผู้หนึ่งจะออกเดินทางไปยังเมืองไกล จึงเรียกพวกผู้รับใช้ของตนมา และฝากทรัพย์สมบัติของเขาไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 15, 'คนหนึ่งท่านให้ห้าตะลันต์ คนหนึ่งสองตะลันต์ และอีกคนหนึ่งตะลันต์เดียว ตามความสามารถของแต่ละคน แล้วท่านก็ออกเดินทางทันที');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 16, 'คนที่ได้รับห้าตะลันต์นั้นก็เอาเงินนั้นไปค้าขาย ได้กําไรมาอีกห้าตะลันต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 17, 'คนที่ได้รับสองตะลันต์นั้นก็ได้กําไรอีกสองตะลันต์เหมือนกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 18, 'แต่คนที่ได้รับตะลันต์เดียวได้ขุดหลุมซ่อนเงินของนายไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 19, 'ครั้นอยู่มาช้านาน นายจึงมาคิดบัญชีกับผู้รับใช้เหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 20, 'คนที่ได้รับห้าตะลันต์ก็เอาเงินกําไรอีกห้าตะลันต์มาชี้แจงว่า ‘นายเจ้าข้า ท่านได้มอบเงินห้าตะลันต์ไว้กับข้าพเจ้า ดูเถิด ข้าพเจ้าได้กําไรมาอีกห้าตะลันต์’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 21, 'นายจึงตอบเขาว่า ‘ดีแล้ว เจ้าเป็นผู้รับใช้ดีและสัตย์ซื่อ เจ้าสัตย์ซื่อในของเล็กน้อย เราจะตั้งเจ้าให้ดูแลของมาก เจ้าจงปรีดีร่วมสุขกับนายของเจ้าเถิด’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 22, 'คนที่ได้รับสองตะลันต์มาชี้แจงด้วยว่า ‘นายเจ้าข้า ท่านได้มอบเงินสองตะลันต์ไว้กับข้าพเจ้า ดูเถิด ข้าพเจ้าได้กําไรมาอีกสองตะลันต์’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 23, 'นายจึงตอบเขาว่า ‘ดีแล้ว เจ้าเป็นผู้รับใช้ดีและสัตย์ซื่อ เจ้าสัตย์ซื่อในของเล็กน้อย เราจะตั้งเจ้าให้ดูแลของมาก เจ้าจงปรีดีร่วมสุขกับนายของเจ้าเถิด’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 24, 'ฝ่ายคนที่ได้รับตะลันต์เดียวมาชี้แจงว่า ‘นายเจ้าข้า ข้าพเจ้ารู้จักท่านว่าท่านเป็นคนใจแข็ง เกี่ยวผลที่ท่านมิได้หว่าน เก็บส่ําสมที่ท่านมิได้โปรย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 25, 'ข้าพเจ้ากลัวจึงเอาเงินตะลันต์ของท่านไปซ่อนไว้ใต้ดิน ดูเถิด นี่แหละเงินของท่าน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 26, 'นายจึงตอบเขาว่า ‘เจ้าผู้รับใช้ชั่วช้าและเกียจคร้าน เจ้าก็รู้อยู่ว่าเราเกี่ยวที่เรามิได้หว่าน เก็บส่ําสมที่เรามิได้โปรย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 27, 'เหตุฉะนั้น เจ้าควรเอาเงินของเราไปฝากไว้ที่ธนาคาร เมื่อเรามาจะได้รับเงินของเราทั้งดอกเบี้ยด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 28, 'เพราะฉะนั้น จงเอาเงินตะลันต์เดียวนั้นจากเขาไปให้คนที่มีสิบตะลันต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 29, 'ด้วยว่าทุกคนที่มีอยู่แล้ว จะเพิ่มเติมให้แก่ผู้นั้นจนมีเหลือเฟือ แต่ผู้ที่ไม่มี แม้ว่าซึ่งเขามีอยู่ก็จะต้องเอาไปจากเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 30, 'จงเอาเจ้าผู้รับใช้ที่ไร้ประโยชน์นี้ไปทิ้งเสียที่มืดภายนอก ซึ่งที่นั่นจะมีการร้องไห้ขบเขี้ยวเคี้ยวฟัน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 31, 'เมื่อบุตรมนุษย์จะเสด็จมาในสง่าราศีของพระองค์พร้อมกับเหล่าทูตสวรรค์อันบริสุทธิ์ทั้งปวง เมื่อนั้นพระองค์จะประทับบนพระที่นั่งอันรุ่งเรืองของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 32, 'บรรดาประชาชาติต่างๆจะประชุมพร้อมกันต่อพระพักตร์พระองค์ และพระองค์จะทรงแยกมนุษย์ทั้งหลายโดยแยกพวกหนึ่งออกจากอีกพวกหนึ่ง เหมือนอย่างผู้เลี้ยงแกะแยกแกะออกจากแพะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 33, 'และพระองค์จะทรงจัดฝูงแกะให้อยู่เบื้องขวาพระหัตถ์ของพระองค์ แต่ฝูงแพะนั้นจะทรงจัดให้อยู่เบื้องซ้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 34, 'ขณะนั้น พระมหากษัตริย์จะตรัสแก่บรรดาผู้ที่อยู่เบื้องขวาพระหัตถ์ของพระองค์ว่า ‘ท่านทั้งหลายที่ได้รับพระพรจากพระบิดาของเรา จงมารับเอาราชอาณาจักรซึ่งได้ตระเตรียมไว้สําหรับท่านทั้งหลายตั้งแต่แรกสร้างโลกเป็นมรดก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 35, 'เพราะว่าเมื่อเราหิว ท่านทั้งหลายก็ได้จัดหาให้เรากิน เรากระหายน้ํา ท่านก็ให้เราดื่ม เราเป็นแขกแปลกหน้า ท่านก็ได้ต้อนรับเราไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 36, 'เราเปลือยกาย ท่านก็ได้ให้เสื้อผ้าเรานุ่งห่ม เมื่อเราเจ็บป่วย ท่านก็ได้มาเยี่ยมเรา เมื่อเราต้องจําอยู่ในคุก ท่านก็ได้มาเยี่ยมเรา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 37, 'เวลานั้นบรรดาผู้ชอบธรรมจะกราบทูลพระองค์ว่า ‘พระองค์เจ้าข้า ที่ข้าพระองค์เห็นพระองค์ทรงหิว และได้จัดมาถวายแด่พระองค์แต่เมื่อไร หรือทรงกระหายน้ํา และได้ถวายให้พระองค์ดื่มแต่เมื่อไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 38, 'ที่ข้าพระองค์ได้เห็นพระองค์ทรงเป็นแขกแปลกหน้า และได้ต้อนรับพระองค์ไว้แต่เมื่อไร หรือเปลือยพระกาย และได้สวมฉลองพระองค์ให้แต่เมื่อไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 39, 'ที่ข้าพระองค์เห็นพระองค์ประชวรหรือต้องจําอยู่ในคุก และได้มาเฝ้าพระองค์นั้นแต่เมื่อไร’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 40, 'แล้วพระมหากษัตริย์จะตรัสตอบเขาว่า ‘เราบอกความจริงแก่ท่านทั้งหลายว่า ซึ่งท่านได้กระทําแก่คนใดคนหนึ่งในพวกพี่น้องของเรานี้ถึงแม้จะต่ําต้อยเพียงไร ก็เหมือนได้กระทําแก่เราด้วย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 41, 'แล้วพระองค์จะตรัสกับบรรดาผู้ที่อยู่เบื้องซ้ายพระหัตถ์ด้วยว่า ‘ท่านทั้งหลาย ผู้ต้องสาปแช่ง จงถอยไปจากเราเข้าไปอยู่ในไฟซึ่งไหม้อยู่เป็นนิตย์ ซึ่งเตรียมไว้สําหรับพญามารและสมุนของมันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 42, 'เพราะว่าเมื่อเราหิว ท่านก็มิได้ให้เรากิน เรากระหายน้ํา ท่านก็มิได้ให้เราดื่ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 43, 'เราเป็นแขกแปลกหน้า ท่านก็ไม่ได้ต้อนรับเราไว้ เราเปลือยกาย ท่านก็ไม่ได้ให้เสื้อผ้าเรานุ่งห่ม เราเจ็บป่วยและต้องจําอยู่ในคุก ท่านไม่ได้เยี่ยมเรา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 44, 'เขาทั้งหลายจะทูลพระองค์ด้วยว่า ‘พระองค์เจ้าข้า ที่ข้าพระองค์ได้เห็นพระองค์ทรงหิวหรือทรงกระหายน้ํา หรือทรงเป็นแขกแปลกหน้าหรือเปลือยพระกาย หรือประชวร หรือต้องจําอยู่ในคุก และข้าพระองค์มิได้ปรนนิบัติพระองค์นั้นแต่เมื่อไร’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 45, 'เมื่อนั้นพระองค์จะตรัสตอบเขาว่า ‘เราบอกความจริงแก่ท่านทั้งหลายว่า ซึ่งท่านมิได้กระทําแก่ผู้ต่ําต้อยที่สุดสักคนหนึ่งในพวกนี้ ก็เหมือนท่านมิได้กระทําแก่เรา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 46, 'และพวกเหล่านี้จะต้องออกไปรับโทษอยู่เป็นนิตย์ แต่ผู้ชอบธรรมจะเข้าสู่ชีวิตนิรันดร์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 1, 'ต่อมาเมื่อพระเยซูตรัสถ้อยคําเหล่านี้เสร็จแล้ว พระองค์จึงรับสั่งแก่พวกสาวกของพระองค์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 2, '“ท่านทั้งหลายรู้อยู่ว่าอีกสองวันจะถึงเทศกาลปัสกา และบุตรมนุษย์จะต้องถูกทรยศให้ถูกตรึงที่กางเขน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 3, 'ครั้งนั้นพวกปุโรหิตใหญ่ พวกธรรมาจารย์ และพวกผู้ใหญ่ของประชาชนได้ประชุมกันที่คฤหาสน์ของมหาปุโรหิต ผู้ซึ่งเรียกขานกันว่า คายาฟาส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 4, 'ปรึกษากันเพื่อจะจับพระเยซูด้วยอุบายเอาไปฆ่าเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 5, 'แต่พวกเขาพูดว่า “ในวันเทศกาลเลี้ยงอย่าพึ่งทําเลย กลัวว่าประชาชนจะเกิดการวุ่นวาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 6, 'ในคราวที่พระเยซูทรงประทับอยู่หมู่บ้านเบธานีในเรือนของซีโมนคนโรคเรื้อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 7, 'ขณะเมื่อพระองค์ทรงเอนพระกายลงเสวยอยู่ มีหญิงผู้หนึ่งถือผอบน้ํามันหอมราคาแพงมากมาเฝ้าพระองค์ แล้วเทน้ํามันนั้นบนพระเศียรของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 8, 'พวกสาวกของพระองค์เมื่อเห็นก็ไม่พอใจ จึงว่า “เหตุใดจึงทําให้ของนี้เสียเปล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 9, 'ด้วยน้ํามันนี้ถ้าขายก็ได้เงินมาก แล้วจะแจกให้คนจนก็ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 10, 'เมื่อพระเยซูทรงทราบจึงตรัสแก่เขาว่า “กวนใจหญิงนี้ทําไม เธอได้กระทําการดีแก่เรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 11, 'ด้วยว่าคนยากจนมีอยู่กับท่านเสมอ แต่เราไม่อยู่กับท่านเสมอไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 12, 'ซึ่งหญิงนี้ได้เทน้ํามันหอมบนกายเรา เธอกระทําเพื่อการศพของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 13, 'เราบอกความจริงแก่ท่านทั้งหลายว่า ที่ไหนๆทั่วโลกซึ่งข่าวประเสริฐนี้จะประกาศไป การซึ่งหญิงนี้ได้กระทําจะเลื่องลือไปเป็นที่ระลึกถึงเขาที่นั่นด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 14, 'ครั้งนั้นคนหนึ่งในพวกสาวกสิบสองคนชื่อ ยูดาสอิสคาริโอท ได้ไปหาพวกปุโรหิตใหญ่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 15, 'ถามว่า “ถ้าข้าพเจ้าจะมอบพระองค์ไว้แก่ท่าน ท่านทั้งหลายจะให้อะไรข้าพเจ้า” ฝ่ายเขาก็สัญญาจะให้เหรียญเงินแก่ยูดาสสามสิบเหรียญ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 16, 'ตั้งแต่เวลานั้นมายูดาสก็คอยหาช่องที่จะทรยศพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 17, 'ในวันต้นเทศกาลกินขนมปังไร้เชื้อ พวกสาวกมาทูลถามพระเยซูว่า “พระองค์ทรงปรารถนาจะให้ข้าพระองค์ทั้งหลายจัดเตรียมปัสกาให้พระองค์เสวยที่ไหน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 18, 'พระองค์จึงตรัสว่า “จงเข้าไปหาผู้หนึ่งในกรุงนั้น บอกเขาว่า ‘พระอาจารย์ว่า เวลาของเรามาใกล้แล้ว เราจะถือปัสกาที่บ้านของท่านพร้อมกับพวกสาวกของเรา’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 19, 'ฝ่ายสาวกเหล่านั้นก็กระทําตามที่พระเยซูทรงรับสั่ง แล้วได้จัดเตรียมปัสกาไว้พร้อม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 20, 'ครั้นถึงเวลาพลบค่ํา พระองค์เอนพระกายลงร่วมสํารับกับสาวกสิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 21, 'เมื่อรับประทานกันอยู่พระองค์จึงตรัสว่า “เราบอกความจริงแก่ท่านทั้งหลายว่า คนหนึ่งในพวกท่านจะทรยศเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 22, 'ฝ่ายพวกสาวกก็พากันเป็นทุกข์นัก ต่างคนต่างเริ่มทูลถามพระองค์ว่า “พระองค์เจ้าข้า คือข้าพระองค์หรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 23, 'พระองค์ตรัสตอบว่า “ผู้ที่เอาอาหารจิ้มในชามเดียวกันกับเรา ผู้นั้นแหละที่จะทรยศเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 24, 'บุตรมนุษย์จะเสด็จไปตามที่ได้เขียนไว้ว่าด้วยพระองค์นั้น แต่วิบัติแก่ผู้ที่ทรยศบุตรมนุษย์ ถ้าคนนั้นมิได้บังเกิดมาก็จะเป็นการดีต่อคนนั้นเอง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 25, 'ยูดาสที่ได้ทรยศพระองค์ทูลถามว่า “อาจารย์เจ้าข้า คือข้าพระองค์หรือ” พระองค์ตรัสตอบเขาว่า “ท่านพูดเองแล้วนี่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 26, 'ระหว่างอาหารมื้อนั้น พระเยซูทรงหยิบขนมปังมา และเมื่อขอบพระคุณแล้ว ทรงหักส่งให้แก่เหล่าสาวกตรัสว่า “จงรับกินเถิด นี่เป็นกายของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 27, 'แล้วพระองค์จึงทรงหยิบถ้วยมาขอบพระคุณและส่งให้เขา ตรัสว่า “จงรับไปดื่มทุกคนเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 28, 'ด้วยว่านี่เป็นโลหิตของเราอันเป็นโลหิตแห่งพันธสัญญาใหม่ ซึ่งต้องหลั่งออกเพื่อยกบาปโทษคนเป็นอันมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 29, 'เราบอกท่านทั้งหลายว่า เราจะไม่ดื่มน้ําผลแห่งเถาองุ่นต่อไปอีกจนวันนั้นมาถึง คือวันที่เราจะดื่มกันใหม่กับพวกท่านในอาณาจักรแห่งพระบิดาของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 30, 'เมื่อพวกเขาร้องเพลงสรรเสริญแล้ว เขาก็พากันออกไปยังภูเขามะกอกเทศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 31, 'ครั้งนั้นพระเยซูตรัสกับเหล่าสาวกว่า “ในคืนวันนี้ท่านทุกคนจะสะดุดเพราะเรา ด้วยมีคําเขียนไว้ว่า ‘เราจะตีผู้เลี้ยงแกะ และแกะฝูงนั้นจะกระจัดกระจายไป’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 32, 'แต่เมื่อเราฟื้นขึ้นมาแล้ว เราจะไปยังแคว้นกาลิลีก่อนหน้าท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 33, 'ฝ่ายเปโตรทูลตอบพระองค์ว่า “แม้คนทั้งปวงจะสะดุดเพราะพระองค์ ข้าพระองค์จะสะดุดก็หามิได้เลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 34, 'พระเยซูตรัสกับเขาว่า “เราบอกความจริงแก่ท่านว่า ในคืนนี้ก่อนไก่ขัน ท่านจะปฏิเสธเราสามครั้ง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 35, 'เปโตรทูลพระองค์ว่า “ถึงแม้ข้าพระองค์จะต้องตายกับพระองค์ ข้าพระองค์ก็จะไม่ปฏิเสธพระองค์เลย” เหล่าสาวกก็ทูลเช่นนั้นเหมือนกันทุกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 36, 'แล้วพระเยซูทรงพาสาวกมายังที่แห่งหนึ่งเรียกว่า เกทเสมนี แล้วตรัสกับสาวกว่า “จงนั่งอยู่ที่นี่ขณะเมื่อเราจะไปอธิษฐานที่โน่น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 37, 'พระองค์ก็พาเปโตรกับบุตรชายทั้งสองของเศเบดีไปด้วย พระองค์ทรงเริ่มโศกเศร้าและหนักพระทัยยิ่งนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 38, 'พระองค์จึงตรัสกับเขาว่า “ใจของเราเป็นทุกข์แทบจะตาย จงเฝ้าอยู่กับเราที่นี่เถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 39, 'แล้วพระองค์เสด็จดําเนินไปอีกหน่อยหนึ่ง ก็ซบพระพักตร์ลงถึงดิน อธิษฐานว่า “โอ พระบิดาของข้าพระองค์ ถ้าเป็นได้ขอให้ถ้วยนี้เลื่อนพ้นไปจากข้าพระองค์เถิด แต่อย่างไรก็ดี อย่าให้เป็นตามใจปรารถนาของข้าพระองค์ แต่ให้เป็นไปตามพระทัยของพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 40, 'พระองค์จึงเสด็จกลับมายังสาวกเหล่านั้น เห็นเขานอนหลับอยู่ และตรัสกับเปโตรว่า “เป็นอย่างไรนะ ท่านทั้งหลายจะคอยเฝ้าอยู่กับเราสักชั่วเวลาหนึ่งไม่ได้หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 41, 'จงเฝ้าระวังและอธิษฐาน เพื่อท่านจะไม่เข้าในการทดลอง จิตใจพร้อมแล้วก็จริง แต่เนื้อหนังยังอ่อนกําลัง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 42, 'พระองค์จึงเสด็จไปอธิษฐานครั้งที่สองอีกว่า “โอ ข้าแต่พระบิดาของข้าพระองค์ ถ้าถ้วยนี้เลื่อนพ้นไปจากข้าพระองค์ไม่ได้ และข้าพระองค์จําต้องดื่มแล้ว ก็ให้เป็นไปตามน้ําพระทัยของพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 43, 'ครั้นพระองค์เสด็จกลับมาก็ทรงพบสาวกนอนหลับอีก เพราะเขาลืมตาไม่ขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 44, 'พระองค์จึงทรงละพวกเขาไว้ เสด็จไปอธิษฐานครั้งที่สามด้วยถ้อยคําเช่นเดิมอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 45, 'แล้วพระองค์เสด็จมายังพวกสาวกของพระองค์ ตรัสว่า “เดี๋ยวนี้ จงนอนต่อไปให้หายเหนื่อยเถิด ดูเถิด เวลามาใกล้แล้ว และบุตรมนุษย์จะต้องถูกทรยศให้ตกอยู่ในมือของคนบาป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 46, 'ลุกขึ้นไปกันเถิด ดูเถิด ผู้ที่จะทรยศเรามาใกล้แล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 47, 'พระองค์ตรัสยังไม่ทันขาดคํา ดูเถิด ยูดาส คนหนึ่งในเหล่าสาวกสิบสองคนนั้น ได้เข้ามา และมีประชาชนเป็นอันมากถือดาบ ถือไม้ตะบอง มาจากพวกปุโรหิตใหญ่และพวกผู้ใหญ่แห่งประชาชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 48, 'ผู้ที่จะทรยศพระองค์นั้นได้ให้อาณัติสัญญาณแก่เขาว่า “เราจะจุบผู้ใด ก็เป็นผู้นั้นแหละ จงจับกุมเขาไว้ให้แน่นหนาเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 49, 'ขณะนั้น ยูดาสตรงมาหาพระเยซูทูลว่า “สวัสดี พระอาจารย์” แล้วจุบพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 50, 'พระเยซูตรัสกับเขาว่า “สหายเอ๋ย มาที่นี่ทําไม” คนเหล่านั้นก็เข้ามาจับพระเยซูและคุมไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 51, 'ดูเถิด มีคนหนึ่งที่อยู่กับพระเยซู ยื่นมือชักดาบออก ฟันหูผู้รับใช้คนหนึ่งของมหาปุโรหิตขาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 52, 'พระเยซูจึงตรัสกับเขาว่า “จงเอาดาบของท่านใส่ฝักเสีย ด้วยว่าบรรดาผู้ถือดาบจะพินาศเพราะดาบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 53, 'ท่านคิดว่าเราจะอธิษฐานขอพระบิดาของเรา และในบัดเดี๋ยวนั้นพระองค์จะทรงประทานทูตสวรรค์แก่เรากว่าสิบสองกองไม่ได้หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 54, 'แต่ถ้าเป็นเช่นนั้นพระคัมภีร์ที่ว่า จําจะต้องเป็นอย่างนี้ จะสําเร็จได้อย่างไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 55, 'ขณะนั้นพระเยซูตรัสกับหมู่ชนว่า “ท่านทั้งหลายเห็นเราเป็นโจรหรือจึงถือดาบ ถือตะบองออกมาจับเรา เราได้นั่งกับท่านทั้งหลายสั่งสอนในพระวิหารทุกวัน ท่านก็หาได้จับเราไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 56, 'แต่เหตุการณ์ทั้งสิ้นที่ได้บังเกิดขึ้นนี้ ก็เพื่อจะสําเร็จตามพระคัมภีร์ที่พวกศาสดาพยากรณ์ได้เขียนไว้” แล้วสาวกทั้งหมดก็ได้ละทิ้งพระองค์ไว้และพากันหนีไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 57, 'ผู้ที่จับพระเยซูได้พาพระองค์ไปยังคายาฟาสมหาปุโรหิต ที่ซึ่งพวกธรรมาจารย์และพวกผู้ใหญ่ได้ประชุมกันอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 58, 'แต่เปโตรได้ติดตามพระองค์ไปห่างๆจนถึงคฤหาสน์ของมหาปุโรหิต แล้วเข้าไปนั่งข้างในกับคนใช้ เพื่อจะดูว่าเรื่องจะจบลงอย่างไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 59, 'พวกปุโรหิตใหญ่ พวกผู้ใหญ่ กับบรรดาสมาชิกสภาได้หาพยานเท็จมาเบิกปรักปรําพระเยซู เพื่อจะประหารพระองค์เสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 60, 'แต่หาหลักฐานไม่ได้ เออ ถึงแม้มีพยานเท็จหลายคนมาให้การก็หาหลักฐานไม่ได้ ในที่สุดก็มีพยานเท็จสองคนมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 61, 'กล่าวว่า “คนนี้ได้ว่า ‘เราสามารถจะทําลายพระวิหารของพระเจ้า และจะสร้างขึ้นใหม่ในสามวัน’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 62, 'มหาปุโรหิตจึงลุกขึ้นถามพระองค์ว่า “ท่านจะไม่ตอบอะไรหรือ คนเหล่านี้เป็นพยานปรักปรําท่านด้วยเรื่องอะไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 63, 'แต่พระเยซูทรงนิ่งอยู่ มหาปุโรหิตจึงกล่าวแก่พระองค์ว่า “เราสั่งให้ท่านสาบานโดยอ้างพระเจ้าผู้ทรงพระชนม์อยู่ ให้บอกเราว่า ท่านเป็นพระคริสต์พระบุตรของพระเจ้าหรือไม่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 64, 'พระเยซูตรัสกับเขาว่า “ท่านว่าถูกแล้ว และยิ่งกว่านั้นอีก เราบอกท่านทั้งหลายว่า ในเวลาเบื้องหน้านั้น ท่านทั้งหลายจะได้เห็นบุตรมนุษย์นั่งข้างขวาพระหัตถ์ของผู้ทรงฤทธานุภาพ และเสด็จมาบนเมฆแห่งฟ้าสวรรค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 65, 'ขณะนั้นมหาปุโรหิตจึงฉีกเสื้อของตน แล้วว่า “เขาได้พูดหมิ่นประมาทแล้ว เราต้องการพยานอะไรอีกเล่า ดูเถิด บัดนี้ ท่านทั้งหลายก็ได้ยินเขาพูดหมิ่นประมาทแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 66, 'ท่านทั้งหลายคิดเห็นอย่างไร” คนทั้งปวงก็ตอบว่า “เขามีความผิดถึงตาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 67, 'แล้วเขาถ่มน้ําลายรดพระพักตร์พระองค์และตีพระองค์ และคนอื่นเอาฝ่ามือตบพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 68, 'แล้วว่า “เจ้าพระคริสต์ จงพยากรณ์ให้เรารู้ว่าใครตบเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 69, 'ขณะนั้นเปโตรนั่งอยู่ภายนอกบริเวณคฤหาสน์นั้น มีสาวใช้คนหนึ่งมาพูดกับเขาว่า “เจ้าได้อยู่กับเยซูชาวกาลิลีด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 70, 'แต่เปโตรได้ปฏิเสธต่อหน้าคนทั้งปวงว่า “ที่เจ้าว่านั้นข้าไม่รู้เรื่อง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 71, 'เมื่อเปโตรได้ออกไปที่ระเบียง สาวใช้อีกคนหนึ่งแลเห็นจึงบอกคนทั้งปวงที่อยู่ที่นั่นว่า “คนนี้ได้อยู่กับเยซูชาวนาซาเร็ธด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 72, 'เปโตรจึงปฏิเสธอีก ด้วยคําสาบานว่า “ข้าไม่รู้จักคนนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 73, 'อีกสักครู่หนึ่งคนทั้งหลายที่ยืนอยู่ใกล้ๆนั้นก็มาว่าแก่เปโตรว่า “เจ้าเป็นคนหนึ่งในพวกนั้นแน่แล้ว ด้วยว่าสําเนียงของเจ้าก็ส่อตัวเจ้าเอง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 74, 'แล้วเปโตรก็เริ่มสบถและสาบานว่า “ข้าไม่รู้จักคนนั้น” ในทันใดนั้นไก่ก็ขัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 75, 'เปโตรจึงระลึกถึงคําของพระเยซูที่ตรัสแก่เขาว่า “ก่อนไก่ขัน ท่านจะปฏิเสธเราสามครั้ง” แล้วเปโตรก็ออกไปข้างนอกร้องไห้อย่างขมขื่นยิ่งนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 1, 'ครั้นรุ่งเช้า บรรดาพวกปุโรหิตใหญ่และพวกผู้ใหญ่แห่งประชาชนปรึกษากันด้วยเรื่องพระเยซู เพื่อจะประหารพระองค์เสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 2, 'เขาจึงมัดพระองค์พาไปมอบไว้แก่ปอนทิอัสปีลาตเจ้าเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 3, 'เมื่อยูดาสผู้ทรยศพระองค์เห็นว่าพระองค์ต้องปรับโทษก็กลับใจ นําเงินสามสิบเหรียญนั้นมาคืนให้แก่พวกปุโรหิตใหญ่และพวกผู้ใหญ่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 4, 'กล่าวว่า “ข้าพเจ้าได้ทําบาปที่ได้ทรยศโลหิตอันบริสุทธิ์” คนเหล่านั้นจึงว่า “การนั้นเป็นธุระอะไรของเรา เจ้าต้องรับธุระเอาเอง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 5, 'ยูดาสจึงทิ้งเงินนั้นไว้ในพระวิหารและจากไป แล้วเขาก็ออกไปผูกคอตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 6, 'พวกปุโรหิตใหญ่จึงเก็บเอาเงินนั้นมาแล้วว่า “เป็นการผิดพระราชบัญญัติที่จะเก็บเงินนั้นไว้ในคลังพระวิหาร เพราะเป็นค่าโลหิต”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 7, 'เขาก็ปรึกษากันและได้เอาเงินนั้นไปซื้อทุ่งช่างหม้อไว้ สําหรับเป็นที่ฝังศพคนต่างบ้านต่างเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 8, 'เหตุฉะนั้น ทุ่งนั้นจึงเรียกว่า ทุ่งโลหิต จนถึงทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 9, 'ครั้งนั้นก็สําเร็จตามพระวจนะโดยเยเรมีย์ศาสดาพยากรณ์ ซึ่งว่า ‘และพวกเขาก็รับเงินสามสิบเหรียญ ซึ่งเป็นราคาของผู้ที่เขาตีราคาไว้นั้น’ คือที่คนอิสราเอลบางคนตีราคาไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 10, '‘แล้วไปซื้อทุ่งช่างหม้อ ตามที่องค์พระผู้เป็นเจ้าได้ทรงบัญชาข้าพเจ้า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 11, 'เมื่อพระเยซูทรงยืนอยู่ต่อหน้าเจ้าเมือง เจ้าเมืองจึงถามพระองค์ว่า “ท่านเป็นกษัตริย์ของพวกยิวหรือ” พระเยซูตรัสกับท่านว่า “ก็ท่านว่าแล้วนี่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 12, 'แต่เมื่อพวกปุโรหิตใหญ่และพวกผู้ใหญ่ได้ฟ้องกล่าวโทษพระองค์ พระองค์มิได้ทรงตอบประการใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 13, 'ปีลาตจึงกล่าวแก่พระองค์ว่า “ซึ่งเขาได้กล่าวความปรักปรําท่านเป็นหลายประการนี้ ท่านไม่ได้ยินหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 14, 'แต่พระองค์ก็มิได้ตรัสตอบท่านสักคําเดียว เจ้าเมืองจึงอัศจรรย์ใจยิ่งนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 15, 'ในเทศกาลเลี้ยงนั้น เจ้าเมืองเคยปล่อยนักโทษคนหนึ่งให้แก่หมู่ชนตามใจชอบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 16, 'คราวนั้นพวกเขามีนักโทษสําคัญคนหนึ่งชื่อบารับบัส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 17, 'เหตุฉะนั้นเมื่อคนทั้งปวงชุมนุมกันแล้ว ปีลาตได้ถามเขาว่า “เจ้าทั้งหลายปรารถนาให้ข้าพเจ้าปล่อยผู้ใดแก่เจ้า บารับบัสหรือพระเยซูที่เรียกว่า พระคริสต์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 18, 'เพราะท่านรู้อยู่แล้วว่าเขาได้มอบพระองค์ไว้ด้วยความอิจฉา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 19, 'ขณะเมื่อปีลาตนั่งบัลลังก์พิพากษาอยู่นั้น ภรรยาของท่านได้ใช้คนมาเรียนท่านว่า “ท่านอย่าพัวพันกับเรื่องของคนชอบธรรมนั้นเลย ด้วยว่าวันนี้ดิฉันทุกข์ใจหลายประการกับความฝันเกี่ยวกับท่านผู้นั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 20, 'ฝ่ายพวกปุโรหิตใหญ่และพวกผู้ใหญ่ก็ยุยงหมู่ชนขอให้ปล่อยบารับบัส และให้ประหารพระเยซูเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 21, 'เจ้าเมืองจึงถามเขาว่า “ในสองคนนี้เจ้าจะให้เราปล่อยคนไหนให้แก่เจ้า” เขาตอบว่า “บารับบัส”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 22, 'ปีลาตจึงถามพวกเขาว่า “ถ้าอย่างนั้น เราจะทําอย่างไรแก่พระเยซูที่เรียกว่า พระคริสต์” เขาพากันร้องแก่ท่านว่า “ให้ตรึงเขาเสียที่กางเขนเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 23, 'เจ้าเมืองถามว่า “ตรึงทําไม เขาได้ทําผิดประการใด” แต่เขาทั้งหลายยิ่งร้องว่า “ให้ตรึงเขาเสียที่กางเขนเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 24, 'เมื่อปีลาตเห็นว่าไม่ได้การมีแต่จะเกิดวุ่นวายขึ้น ท่านก็เอาน้ําล้างมือต่อหน้าหมู่ชน แล้วว่า “เราไม่มีผิดด้วยเรื่องโลหิตของคนชอบธรรมคนนี้ เจ้ารับธุระเอาเองเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 25, 'บรรดาหมู่ชนเรียนว่า “ให้โลหิตของเขาตกอยู่แก่เราทั้งบุตรของเราเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 26, 'ท่านจึงปล่อยบารับบัสให้เขา และเมื่อท่านได้โบยตีพระเยซูแล้ว ท่านก็มอบพระองค์ให้ถูกตรึงที่กางเขน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 27, 'พวกทหารของเจ้าเมืองจึงพาพระเยซูไปไว้ในศาลาปรีโทเรียม แล้วก็รวมทหารทั้งกองล้อมพระองค์ไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 28, 'และพวกเขาเปลื้องฉลองพระองค์ออก เอาเสื้อสีแดงเข้มมาสวมพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 29, 'เมื่อพวกเขาเอาหนามสานเป็นมงกุฎ เขาก็สวมพระเศียรของพระองค์ แล้วเอาไม้อ้อให้ถือไว้ในพระหัตถ์เบื้องขวาของพระองค์ และเขาได้คุกเข่าลงต่อพระพักตร์พระองค์ เยาะเย้ยพระองค์ว่า “กษัตริย์ของพวกยิวเจ้าข้า ขอทรงพระเจริญ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 30, 'แล้วเขาก็ถ่มน้ําลายรดพระองค์ และเอาไม้อ้อนั้นตีพระเศียรพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 31, 'เมื่อพวกเขาเยาะเย้ยพระองค์แล้ว เขาถอดเสื้อนั้นออก แล้วเอาฉลองพระองค์สวมให้ และนําพระองค์ออกไปเพื่อจะตรึงเสียที่กางเขน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 32, 'ขณะที่พวกเขาออกไปนั้น เขาได้พบชาวไซรีนคนหนึ่งชื่อซีโมน เขาจึงเกณฑ์คนนั้นให้แบกกางเขนของพระองค์ไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 33, 'เมื่อพวกเขามาถึงสถานที่แห่งหนึ่งซึ่งเรียกว่ากลโกธา แปลว่า สถานที่กะโหลกศีรษะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 34, 'เขาเอาน้ําองุ่นเปรี้ยวระคนกับของขมมาถวายพระองค์ เมื่อพระองค์ทรงชิมก็ไม่เสวย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 35, 'ครั้นตรึงพระองค์ที่กางเขนแล้ว เขาก็เอาฉลองพระองค์มาจับฉลากแบ่งปันกันเพื่อจะสําเร็จตามพระวจนะโดยศาสดาพยากรณ์ซึ่งว่า ‘เสื้อผ้าของข้าพระองค์ เขาแบ่งปันกัน ส่วนเสื้อของข้าพระองค์นั้น เขาก็จับฉลากกัน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 36, 'แล้วพวกเขาก็นั่งเฝ้าพระองค์อยู่ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 37, 'และได้เอาถ้อยคําข้อหาที่ลงโทษพระองค์ไปติดไว้เหนือพระเศียร ซึ่งอ่านว่า “ผู้นี้คือเยซูกษัตริย์ของชนชาติยิว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 38, 'คราวนั้นมีโจรสองคนถูกตรึงไว้พร้อมกับพระองค์ ข้างขวาพระหัตถ์คนหนึ่ง ข้างซ้ายอีกคนหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 39, 'ฝ่ายคนทั้งหลายที่เดินผ่านไปมานั้นก็ด่าทอพระองค์ สั่นศีรษะของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 40, 'กล่าวว่า “เจ้าผู้จะทําลายพระวิหารและสร้างขึ้นในสามวันน่ะ จงช่วยตัวเองให้รอด ถ้าเจ้าเป็นบุตรของพระเจ้า จงลงมาจากกางเขนเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 41, 'พวกปุโรหิตใหญ่กับพวกธรรมาจารย์และพวกผู้ใหญ่ก็เยาะเย้ยพระองค์เช่นกันว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 42, '“เขาช่วยคนอื่นให้รอดได้ แต่ช่วยตัวเองให้รอดไม่ได้ ถ้าเขาเป็นกษัตริย์ของชาติอิสราเอล ให้เขาลงมาจากกางเขนเดี๋ยวนี้เถิด และเราจะเชื่อเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 43, 'เขาไว้ใจในพระเจ้า ถ้าพระองค์พอพระทัยในเขาก็ให้พระองค์ทรงช่วยเขาให้รอดเดี๋ยวนี้เถิด ด้วยเขาได้กล่าวว่า ‘เราเป็นพระบุตรของพระเจ้า’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 44, 'ถึงโจรที่ถูกตรึงไว้กับพระองค์ก็ยังกล่าวคําหยาบช้าต่อพระองค์เหมือนกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 45, 'แล้วก็บังเกิดความมืดทั่วทั้งแผ่นดิน ตั้งแต่เวลาเที่ยงวัน จนถึงบ่ายสามโมง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 46, 'ครั้นประมาณบ่ายสามโมงพระเยซูทรงร้องเสียงดังว่า “เอลี เอลี ลามาสะบักธานี” แปลว่า “พระเจ้าของข้าพระองค์ พระเจ้าของข้าพระองค์ ไฉนพระองค์ทรงทอดทิ้งข้าพระองค์เสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 47, 'บางคนในพวกที่ยืนอยู่ที่นั่น เมื่อได้ยินก็พูดว่า “คนนี้เรียกเอลียาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 48, 'ในทันใดนั้น คนหนึ่งในพวกเขาวิ่งไปเอาฟองน้ําชุบน้ําองุ่นเปรี้ยวเสียบปลายไม้อ้อ ส่งให้พระองค์เสวย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 49, 'แต่คนอื่นร้องว่า “อย่าเพิ่ง ให้เราคอยดูซิว่าเอลียาห์จะมาช่วยเขาให้รอดหรือไม่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 50, 'ฝ่ายพระเยซู เมื่อพระองค์ร้องเสียงดังอีกครั้งหนึ่ง ก็ทรงปล่อยพระวิญญาณจิตออกไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 51, 'และดูเถิด ม่านในพระวิหารก็ขาดออกเป็นสองท่อนตั้งแต่บนตลอดล่าง แผ่นดินก็ไหว ศิลาก็แตกออกจากกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 52, 'อุโมงค์ฝังศพก็เปิดออก ศพของพวกวิสุทธิชนหลายคนที่ล่วงหลับไปแล้วได้เป็นขึ้นมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 53, 'ภายหลังที่พระองค์ทรงเป็นขึ้นมาแล้ว เขาทั้งหลายก็ออกจากอุโมงค์พากันเข้าไปในนครบริสุทธิ์ปรากฏแก่คนเป็นอันมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 54, 'บัดนี้ เมื่อนายร้อยและทหารที่เฝ้าพระเยซูอยู่ด้วยกันได้เห็นแผ่นดินไหวและเหตุการณ์เหล่านั้นซึ่งบังเกิดขึ้น ก็พากันครั่นคร้ามยิ่งนัก จึงพูดกันว่า “แท้จริงท่านผู้นี้เป็นพระบุตรของพระเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 55, 'ที่นั่นมีหญิงหลายคนที่ได้ติดตามพระเยซูจากแคว้นกาลิลีเพื่อปรนนิบัติพระองค์ มองดูอยู่แต่ไกล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 56, 'ในพวกนั้นมีมารีย์ชาวมักดาลา มารีย์มารดาของยากอบและโยเสส และมารดาของบุตรเศเบดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 57, 'ครั้นถึงเวลาพลบค่ํา มีเศรษฐีคนหนึ่งมาจากบ้านอาริมาเธียชื่อโยเซฟ เป็นสาวกของพระเยซูด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 58, 'เขาได้เข้าไปหาปีลาตขอพระศพพระเยซู ปีลาตจึงสั่งให้มอบพระศพนั้นให้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 59, 'เมื่อโยเซฟได้รับพระศพมาแล้ว เขาก็เอาผ้าป่านที่สะอาดพันหุ้มพระศพไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 60, 'แล้วเชิญพระศพไปประดิษฐานไว้ที่อุโมงค์ใหม่ของตน ซึ่งเขาได้สกัดไว้ในศิลา เขาก็กลิ้งหินใหญ่ปิดปากอุโมงค์ไว้แล้วก็จากไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 61, 'ฝ่ายมารีย์ชาวมักดาลากับมารีย์อีกคนหนึ่งนั้น ก็นั่งอยู่ที่นั่นตรงหน้าอุโมงค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 62, 'วันต่อมา คือวันถัดจากวันตระเตรียม พวกปุโรหิตใหญ่และพวกฟาริสีพากันไปหาปีลาต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 63, 'เรียนว่า “เจ้าคุณขอรับ ข้าพเจ้าทั้งหลายจําได้ว่า คนล่อลวงผู้นั้น เมื่อเขายังมีชีวิตอยู่ได้พูดว่า ‘ล่วงไปสามวันแล้วเราจะเป็นขึ้นมาใหม่’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 64, 'เหตุฉะนั้น ขอได้มีบัญชาสั่งเฝ้าอุโมงค์ให้แข็งแรงจนถึงวันที่สาม เกลือกว่าสาวกของเขาจะมาในตอนกลางคืน และลักเอาศพไป แล้วจะประกาศแก่ประชาชนว่า เขาเป็นขึ้นมาจากความตายแล้ว และการหลอกลวงครั้งนี้จะร้ายแรงยิ่งกว่าครั้งก่อนอีก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 65, 'ปีลาตจึงบอกเขาว่า “พวกท่านจงเอายามไปเถิด จงไปเฝ้าให้แข็งแรงเท่าที่ท่านจะทําได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 66, 'เขาจึงไปทําอุโมงค์ให้มั่นคง ประทับตราไว้ที่หิน และวางยามประจําอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 1, 'ภายหลังวันสะบาโต เวลาใกล้รุ่งเช้าวันต้นสัปดาห์ มารีย์ชาวมักดาลากับมารีย์อีกคนหนึ่งมาดูอุโมงค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 2, 'ดูเถิด ได้เกิดแผ่นดินไหวใหญ่ยิ่งนัก เพราะทูตสวรรค์ขององค์พระผู้เป็นเจ้าได้ลงมาจากสวรรค์ กลิ้งก้อนหินนั้นออกจากปากอุโมงค์ แล้วก็นั่งอยู่บนหินนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 3, 'ใบหน้าของทูตนั้นเหมือนแสงฟ้าแลบ เสื้อของทูตนั้นก็ขาวเหมือนหิมะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 4, 'พวกยามที่เฝ้าอยู่กลัวทูตองค์นั้นจนตัวสั่น และเป็นเหมือนคนตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 5, 'ทูตสวรรค์นั้นจึงกล่าวแก่หญิงนั้นว่า “อย่ากลัวเลย เพราะเรารู้อยู่ว่าท่านทั้งหลายมาหาพระเยซูซึ่งถูกตรึงที่กางเขน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 6, 'พระองค์หาได้ประทับอยู่ที่นี่ไม่ เพราะพระองค์ทรงเป็นขึ้นมาแล้วตามที่พระองค์ได้ตรัสไว้นั้น มาดูที่ซึ่งองค์พระผู้เป็นเจ้าได้บรรทมอยู่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 7, 'แล้วจงรีบไปบอกพวกสาวกของพระองค์เถิดว่า พระองค์ทรงเป็นขึ้นมาจากความตายแล้ว และดูเถิด พระองค์เสด็จไปยังแคว้นกาลิลีก่อนท่านทั้งหลาย ท่านทั้งหลายจะเห็นพระองค์ที่นั่น ดูเถิด เราได้บอกท่านแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 8, 'หญิงเหล่านั้นก็ไปจากอุโมงค์โดยเร็ว ทั้งกลัวทั้งยินดีเป็นอันมาก วิ่งนําความไปบอกพวกสาวกของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 9, 'ขณะที่หญิงเหล่านั้นไปบอกสาวกของพระองค์ ดูเถิด พระเยซูได้เสด็จพบเขาและตรัสว่า “จงจําเริญเถิด” หญิงเหล่านั้นก็มากอดพระบาทของพระองค์ และนมัสการพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 10, 'พระเยซูจึงตรัสกับเขาว่า “อย่ากลัวเลย จงไปบอกพวกพี่น้องของเราให้ไปยังแคว้นกาลิลี และพวกเขาจะได้พบเราที่นั่น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 11, 'ขณะที่พวกผู้หญิงกําลังไปอยู่นั้น ดูเถิด มีบางคนในพวกที่เฝ้ายามได้เข้าไปในเมือง เล่าเหตุการณ์ทั้งปวงที่บังเกิดขึ้นนั้นให้พวกปุโรหิตใหญ่ฟัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 12, 'เมื่อพวกปุโรหิตใหญ่ประชุมปรึกษากันกับพวกผู้ใหญ่แล้ว ก็แจกเงินเป็นอันมากให้แก่พวกทหาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 13, 'สั่งว่า “พวกเจ้าจงพูดว่า ‘พวกสาวกของเขามาลักเอาศพไปในเวลากลางคืนเมื่อเรานอนหลับอยู่’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 14, 'ถ้าความนี้ทราบถึงหูเจ้าเมือง เราจะพูดแก้ไขให้พวกเจ้าพ้นโทษ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 15, 'พวกทหารจึงยอมรับเงิน และทําตามที่ถูกสอนมา และความนี้ก็เลื่องลือไปในบรรดาพวกยิวจนทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 16, 'แล้วสาวกสิบเอ็ดคนนั้นก็ได้ไปยังแคว้นกาลิลี ถึงภูเขาที่พระเยซูได้ทรงกําหนดไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 17, 'และเมื่อเขาเห็นพระองค์จึงกราบลงนมัสการพระองค์ แต่บางคนยังสงสัยอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 18, 'พระเยซูจึงเสด็จเข้ามาใกล้ แล้วตรัสกับเขาว่า “ฤทธานุภาพทั้งสิ้นในสวรรค์ก็ดี ในแผ่นดินโลกก็ดี ทรงมอบไว้แก่เราแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 19, 'เหตุฉะนั้น ท่านทั้งหลายจงออกไปสั่งสอนชนทุกชาติ ให้รับบัพติศมาในพระนามแห่งพระบิดา พระบุตร และพระวิญญาณบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 20, 'สอนเขาให้ถือรักษาสิ่งสารพัดซึ่งเราได้สั่งพวกท่านไว้ ดูเถิด เราจะอยู่กับท่านทั้งหลายเสมอไป จนกว่าจะสิ้นโลก เอเมน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 1, 'ข่าวประเสริฐของพระเยซูคริสต์พระบุตรของพระเจ้าเริ่มต้นตรงนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 2, 'ตามที่ได้เขียนไว้ในคําของศาสดาพยากรณ์ว่า ‘ดูเถิด เราใช้ทูตของเราไปข้างหน้าท่าน ผู้นั้นจะเตรียมมรรคาของท่านไว้ข้างหน้าท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 3, 'เสียงผู้ร้องในถิ่นทุรกันดารว่า “จงเตรียมมรรคาแห่งองค์พระผู้เป็นเจ้า จงกระทําหนทางของพระองค์ให้ตรงไป”’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 4, 'ยอห์นให้เขารับบัพติศมาในถิ่นทุรกันดาร และประกาศเรื่องบัพติศมาอันสําแดงการกลับใจใหม่ เพื่อการยกโทษความผิดบาป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 5, 'คนทั่วแคว้นยูเดียกับชาวกรุงเยรูซาเล็มได้พากันออกไปหายอห์น สารภาพความผิดบาปของตน และได้รับบัพติศมาจากท่านในแม่น้ําจอร์แดน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 6, 'ยอห์นแต่งกายด้วยผ้าขนอูฐ และใช้หนังสัตว์คาดเอว รับประทานตั๊กแตนและน้ําผึ้งป่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 7, 'ท่านประกาศว่า “ภายหลังเราจะมีพระองค์ผู้หนึ่งเสด็จมาทรงเป็นใหญ่กว่าเราอีก ซึ่งเราไม่คู่ควรแม้จะน้อมตัวลงแก้สายฉลองพระบาทให้พระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 8, 'จริงๆแล้วเราให้เจ้าทั้งหลายรับบัพติศมาด้วยน้ํา แต่พระองค์นั้นจะให้เจ้าทั้งหลายรับบัพติศมาด้วยพระวิญญาณบริสุทธิ์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 9, 'ต่อมาในคราวนั้นพระเยซูเสด็จมาจากเมืองนาซาเร็ธแคว้นกาลิลี และได้ทรงรับบัพติศมาจากยอห์นในแม่น้ําจอร์แดน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 10, 'พอพระองค์เสด็จขึ้นมาจากน้ํา ในทันใดนั้นก็ทอดพระเนตรเห็นท้องฟ้าแหวกออก และพระวิญญาณดุจนกเขาเสด็จลงมาบนพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 11, 'แล้วมีพระสุรเสียงมาจากฟ้าสวรรค์ว่า “ท่านเป็นบุตรที่รักของเรา เราชอบใจในท่านมาก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 12, 'ในทันใดนั้น พระวิญญาณจึงเร่งเร้าพระองค์ให้เสด็จเข้าไปในถิ่นทุรกันดาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 13, 'และซาตานได้ทดลองพระองค์อยู่ในถิ่นทุรกันดารนั้นถึงสี่สิบวัน พระองค์ทรงอยู่ในที่ของสัตว์ป่า และมีพวกทูตสวรรค์มาปรนนิบัติพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 14, 'ครั้นยอห์นถูกขังไว้ในคุกแล้ว พระเยซูได้เสด็จมายังแคว้นกาลิลี ทรงประกาศข่าวประเสริฐแห่งอาณาจักรของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 15, 'และตรัสว่า “เวลากําหนดมาถึงแล้ว และอาณาจักรของพระเจ้าก็มาใกล้แล้ว ท่านทั้งหลายจงกลับใจเสียใหม่ และเชื่อข่าวประเสริฐเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 16, 'ขณะที่พระองค์เสด็จไปตามชายทะเลกาลิลี พระองค์ก็ทรงทอดพระเนตรเห็นซีโมนและอันดรูว์น้องชายของซีโมน กําลังทอดอวนอยู่ที่ทะเล ด้วยว่าเขาเป็นชาวประมง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 17, 'พระเยซูตรัสกับเขาว่า “ท่านจงตามเรามาเถิด และเราจะตั้งท่านให้เป็นผู้หาคนดังหาปลา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 18, 'เขาก็ละอวนตามพระองค์ไปทันที');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 19, 'ครั้นพระองค์ทรงดําเนินต่อไปอีกหน่อยหนึ่ง พระองค์ก็ทอดพระเนตรเห็นยากอบบุตรชายเศเบดีกับยอห์นน้องชายของเขา กําลังชุนอวนอยู่ในเรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 20, 'ในทันใดนั้นพระองค์ได้ทรงเรียกเขา เขาจึงละเศเบดีบิดาของเขาไว้ที่เรือกับลูกจ้าง และได้ตามพระองค์ไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 21, 'พระองค์กับพวกของพระองค์จึงเข้าไปในเมืองคาเปอรนาอุม และพอถึงวันสะบาโตพระองค์ได้เสด็จเข้าไปในธรรมศาลาเทศนาสั่งสอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 22, 'เขาทั้งหลายก็อัศจรรย์ใจด้วยคําสั่งสอนของพระองค์ เพราะว่าพระองค์ได้ทรงสั่งสอนเขาด้วยสิทธิอํานาจ หาเหมือนพวกธรรมาจารย์ไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 23, 'มีชายคนหนึ่งในธรรมศาลาของเขามีผีโสโครกเข้าสิง มันได้ร้องออกมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 24, 'ว่า “พระเยซูชาวนาซาเร็ธ ปล่อยเราไว้ เราเกี่ยวข้องอะไรกับท่านเล่า ท่านมาเพื่อจะทําลายเราหรือ เรารู้ว่าท่านเป็นผู้ใด ท่านคือองค์บริสุทธิ์ของพระเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 25, 'พระเยซูจึงตรัสห้ามมันว่า “เจ้าจงนิ่งเสีย ออกมาจากเขาซิ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 26, 'และเมื่อผีโสโครกทําให้คนนั้นชักและร้องเสียงดังแล้ว มันก็ออกมาจากเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 27, 'คนทั้งปวงก็ประหลาดใจนักจึงถามกันว่า “การนี้เป็นอย่างไรหนอ นี่เป็นคําสั่งสอนใหม่อะไร ท่านสั่งผีโสโครกด้วยสิทธิอํานาจและมันก็เชื่อฟังท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 28, 'ในขณะนั้น กิตติศัพท์ของพระองค์ได้เลื่องลือไปทั่วแว่นแคว้นบ้านเมืองที่อยู่รอบแขวงกาลิลี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 29, 'พอออกมาจากธรรมศาลา พระองค์กับพวกของพระองค์จึงเข้าไปในเรือนของซีโมนและอันดรูว์ พร้อมกับยากอบและยอห์น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 30, 'แม่ยายของซีโมนนอนป่วยเป็นไข้อยู่ ในทันใดนั้นเขาจึงมาทูลพระองค์ให้ทราบด้วยเรื่องของนาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 31, 'แล้วพระองค์ก็เสด็จไปจับมือนางพยุงขึ้นและทันใดนั้นไข้ก็หาย นางจึงปรนนิบัติเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 32, 'เวลาเย็นวันนั้นครั้นตะวันตกแล้ว คนทั้งหลายพาบรรดาคนเจ็บป่วย และคนที่มีผีสิง มาหาพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 33, 'และคนทั้งเมืองก็แตกตื่นมาออกันอยู่ที่ประตู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 34, 'พระองค์จึงทรงรักษาคนเป็นโรคต่างๆให้หายหลายคน และได้ทรงขับผีออกเสียหลายผี แต่ผีเหล่านั้นพระองค์ทรงห้ามมิให้พูด เพราะว่ามันรู้จักพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 35, 'ครั้นเวลาเช้ามืดพระองค์ได้ทรงลุกขึ้นเสด็จออกไปยังที่เปลี่ยว และทรงอธิษฐานที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 36, 'ฝ่ายซีโมนและคนทั้งหลายที่อยู่ด้วยก็ตามหาพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 37, 'เมื่อพวกเขาพบพระองค์แล้ว เขาจึงทูลพระองค์ว่า “คนทั้งปวงแสวงหาพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 38, 'พระองค์ตรัสแก่เขาว่า “ให้เราทั้งหลายไปในบ้านเมืองใกล้เคียง เพื่อเราจะได้ประกาศที่นั่นด้วย ที่เรามาก็เพื่อการนั้นเอง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 39, 'พระองค์ได้ประกาศในธรรมศาลาของเขาทั่วแคว้นกาลิลี และได้ขับผีออกเสียหลายผี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 40, 'และมีคนโรคเรื้อนคนหนึ่งมาหาพระองค์ คุกเข่าลงต่อพระองค์ และทูลวิงวอนพระองค์ว่า “เพียงแต่พระองค์จะโปรด พระองค์ก็จะทรงบันดาลให้ข้าพระองค์สะอาดได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 41, 'พระเยซูทรงสงสารเขาจึงทรงยื่นพระหัตถ์ถูกต้องคนนั้น ตรัสแก่เขาว่า “เราพอใจแล้ว เจ้าจงสะอาดเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 42, 'พอพระองค์ตรัสแล้ว ในทันใดนั้นโรคเรื้อนก็หาย และคนนั้นก็สะอาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 43, 'ก่อนให้เขาไป พระองค์จึงกําชับผู้นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 44, 'ตรัสแก่เขาว่า “เจ้าอย่าบอกเล่าอะไรให้ผู้ใดฟังเลย แต่จงไปสําแดงตัวแก่ปุโรหิต และถวายเครื่องบูชาสําหรับคนที่หายโรคเรื้อนแล้ว ตามซึ่งโมเสสได้สั่งไว้ เพื่อเป็นหลักฐานต่อคนทั้งหลาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 45, 'แต่คนนั้นเมื่อออกไปแล้วก็ตั้งต้นป่าวร้องมากมายให้เลื่องลือไป จนพระเยซูจะเสด็จเข้าไปในเมืองอย่างเปิดเผยต่อไปไม่ได้ แต่ต้องประทับภายนอกในที่เปลี่ยว และมีคนทุกแห่งทุกตําบลมาหาพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 1, 'ครั้นล่วงไปหลายวัน พระองค์ได้เสด็จไปในเมืองคาเปอรนาอุมอีก และคนทั้งหลายได้ยินว่า พระองค์ประทับที่บ้าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 2, 'และในเวลานั้นคนเป็นอันมากมาชุมนุมกันจนไม่มีที่จะรับ จะเข้าใกล้ประตูก็ไม่ได้ พระองค์จึงเทศนาพระวจนะนั้นให้เขาฟัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 3, 'แล้วมีคนนําคนอัมพาตคนหนึ่งมาหาพระองค์ มีสี่คนหาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 4, 'เมื่อเขาเข้าไปให้ถึงพระองค์ไม่ได้เพราะคนมาก เขาจึงรื้อดาดฟ้าหลังคาตรงที่พระองค์ประทับนั้น และเมื่อรื้อเป็นช่องแล้ว เขาก็หย่อนแคร่ที่คนอัมพาตนอนอยู่ลงมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 5, 'เมื่อพระเยซูทอดพระเนตรเห็นความเชื่อของเขาทั้งหลาย พระองค์จึงตรัสกับคนอัมพาตว่า “ลูกเอ๋ย บาปของเจ้าได้รับการอภัยแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 6, 'แต่มีพวกธรรมาจารย์บางคนนั่งอยู่ที่นั่น และเขาคิดในใจว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 7, '“ทําไมคนนี้พูดหมิ่นประมาทเช่นนั้น ใครจะยกความผิดบาปได้เว้นแต่พระเจ้าเท่านั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 8, 'และในทันใดนั้นเมื่อพระเยซูทรงทราบในพระทัยว่าเขาคิดในใจอย่างนั้น พระองค์จึงตรัสแก่เขาว่า “เหตุไฉนท่านทั้งหลายจึงคิดในใจอย่างนี้เล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 9, 'ที่จะว่ากับคนอัมพาตว่า ‘บาปของเจ้าได้รับการอภัยแล้ว’ หรือจะว่า ‘จงลุกขึ้นยกแคร่เดินไปเถิด’ นั้น ข้างไหนจะง่ายกว่ากัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 10, 'แต่เพื่อท่านทั้งหลายจะได้รู้ว่า บุตรมนุษย์มีสิทธิอํานาจในโลกที่จะโปรดยกความผิดบาปได้” (พระองค์จึงตรัสสั่งคนอัมพาตว่า)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 11, '“เราสั่งเจ้าว่า จงลุกขึ้นยกแคร่ไปบ้านของเจ้าเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 12, 'ทันใดนั้นคนอัมพาตได้ลุกขึ้นแล้วก็ยกแคร่เดินออกไปต่อหน้าคนทั้งปวง คนทั้งปวงก็ประหลาดใจนัก จึงสรรเสริญพระเจ้าว่า “เราไม่เคยเห็นการเช่นนี้เลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 13, 'ฝ่ายพระองค์ได้เสด็จไปตามชายทะเลอีก ประชาชนก็มาหาพระองค์ และพระองค์ได้ตรัสสั่งสอนเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 14, 'เมื่อพระองค์กําลังเสด็จไปนั้น พระองค์ก็ทอดพระเนตรเห็นเลวีบุตรชายอัลเฟอัสนั่งอยู่ที่ด่านเก็บภาษี จึงตรัสแก่เขาว่า “จงตามเรามาเถิด” เขาก็ลุกขึ้นตามพระองค์ไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 15, 'ต่อมาเมื่อพระเยซูเอนพระกายลงเสวยอยู่ในเรือนของเลวี มีพวกคนเก็บภาษีและคนบาปหลายคนเอนกายลงร่วมสํารับกับพระเยซูและพวกสาวกของพระองค์ เพราะมีคนติดตามพระองค์ไปมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 16, 'ฝ่ายพวกธรรมาจารย์และพวกฟาริสี เมื่อเห็นพระองค์ทรงเสวยพระกระยาหารกับพวกคนเก็บภาษีและคนบาป จึงถามสาวกของพระองค์ว่า “เหตุไฉนพระองค์จึงกินและดื่มร่วมกับพวกคนเก็บภาษีและคนบาปเล่า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 17, 'ครั้นพระเยซูทรงได้ยินดังนั้น พระองค์จึงตรัสแก่เขาว่า “คนปกติไม่ต้องการหมอ แต่คนเจ็บต้องการหมอ เรามิได้มาเพื่อจะเรียกคนชอบธรรม แต่มาเรียกคนบาปให้กลับใจเสียใหม่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 18, 'มีพวกศิษย์ของยอห์นและของพวกฟาริสีกําลังถืออดอาหาร พวกเขาจึงมาทูลถามพระองค์ว่า “เหตุไฉนพวกสาวกของยอห์นและของพวกฟาริสีถืออดอาหาร แต่พวกสาวกของพระองค์ไม่ถือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 19, 'พระเยซูจึงตรัสแก่เขาว่า “ท่านจะให้สหายของเจ้าบ่าวถืออดอาหารเมื่อเจ้าบ่าวยังอยู่กับเขากระนั้นหรือ เจ้าบ่าวอยู่ด้วยนานเท่าใด สหายก็ถืออดอาหารไม่ได้นานเท่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 20, 'แต่วันนั้นจะมาถึงเมื่อเจ้าบ่าวจะต้องจากสหายไป ในวันนั้นสหายจะถืออดอาหาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 21, 'ไม่มีผู้ใดเอาท่อนผ้าทอใหม่มาปะเสื้อเก่า ถ้าทําอย่างนั้น ท่อนผ้าทอใหม่ที่ปะเข้านั้นเมื่อหดจะทําให้เสื้อเก่าขาดกว้างออกไปอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 22, 'และไม่มีผู้ใดเอาน้ําองุ่นใหม่มาใส่ไว้ในถุงหนังเก่า ถ้าทําอย่างนั้นน้ําองุ่นใหม่จะทําให้ถุงเก่านั้นขาดไป น้ําองุ่นนั้นจะไหลออก ถุงหนังก็จะเสียไป แต่น้ําองุ่นใหม่นั้นต้องใส่ไว้ในถุงหนังใหม่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 23, 'ต่อมาในวันสะบาโตวันหนึ่งพระองค์กําลังเสด็จไปในนาข้าว และเมื่อพวกสาวกของพระองค์กําลังเดินไปก็เริ่มเด็ดรวงข้าวไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 24, 'ฝ่ายพวกฟาริสีจึงถามพระองค์ว่า “ดูเถิด ทําไมพวกเขาจึงทําการซึ่งพระราชบัญญัติห้ามไว้ในวันสะบาโต”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 25, 'พระองค์จึงตรัสกับเขาว่า “พวกท่านยังไม่เคยอ่านหรือซึ่งดาวิดได้กระทําเมื่อท่านขาดอาหารและอดอยาก ทั้งท่านและพรรคพวกด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 26, 'คือคราวเมื่ออาบียาธาร์เป็นมหาปุโรหิต ท่านได้เข้าไปในพระนิเวศของพระเจ้า และรับประทานขนมปังหน้าพระพักตร์ ซึ่งพระราชบัญญัติห้ามไม่ให้ใครรับประทาน เว้นแต่พวกปุโรหิตเท่านั้น และซ้ํายังส่งให้คนที่มากับท่านรับประทานด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 27, 'พระองค์จึงตรัสแก่เขาว่า “วันสะบาโตนั้นทรงตั้งไว้เพื่อมนุษย์ มิใช่ทรงสร้างมนุษย์ไว้สําหรับวันสะบาโต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 28, 'เหตุฉะนั้นบุตรมนุษย์เป็นเจ้าเป็นใหญ่เหนือวันสะบาโตด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 1, 'แล้วพระองค์ได้เสด็จเข้าไปในธรรมศาลาอีก และที่นั่นมีชายคนหนึ่งมือข้างหนึ่งลีบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 2, 'คนเหล่านั้นคอยดูพระองค์ว่า พระองค์จะรักษาโรคให้คนนั้นในวันสะบาโตหรือไม่ เพื่อเขาจะหาเหตุฟ้องพระองค์ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 3, 'พระองค์ตรัสแก่คนมือลีบว่า “มายืนข้างหน้าเถอะ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 4, 'พระองค์จึงตรัสแก่คนทั้งหลายว่า “ในวันสะบาโตให้ถูกต้องตามพระราชบัญญัติควรจะทําการดีหรือทําการชั่ว จะช่วยชีวิตดีหรือจะสังหารชีวิตดี” ฝ่ายคนทั้งปวงก็นิ่งอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 5, 'พระองค์มีพระทัยเป็นทุกข์เพราะใจเขาแข็งกระด้างนัก และได้ทอดพระเนตรดูรอบด้วยพระพิโรธ และพระองค์ตรัสกับชายคนนั้นว่า “จงเหยียดมือออกเถิด” เขาก็เหยียดออก และมือของเขาก็หายเป็นปกติเหมือนกับมืออีกข้างหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 6, 'พวกฟาริสีจึงออกไป และในทันใดนั้นได้ปรึกษากับพรรคพวกของเฮโรดถึงพระองค์ว่า พวกเขาจะทําอย่างไรจึงจะฆ่าพระองค์ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 7, 'ฝ่ายพระเยซูกับพวกสาวกของพระองค์จึงออกจากที่นั่นไปยังทะเล และฝูงชนเป็นอันมากจากแคว้นกาลิลีได้ตามพระองค์ไป ทั้งจากแคว้นยูเดีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 8, 'จากกรุงเยรูซาเล็ม และจากเมืองเอโดม และจากฟากแม่น้ําจอร์แดนข้างโน้น และจากแคว้นเมืองไทระและไซดอน ฝูงชนเป็นอันมาก เมื่อเขาได้ยินถึงสิ่งยิ่งใหญ่ที่พระองค์ทรงกระทํานั้นก็มาหาพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 9, 'พระองค์จึงตรัสสั่งพวกสาวกของพระองค์ให้เอาเรือเล็กมาคอยรับพระองค์ เพื่อมิให้ประชาชนเบียดเสียดพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 10, 'ด้วยว่าพระองค์ได้ทรงรักษาคนเป็นอันมากให้หายโรค จนบรรดาผู้ที่มีโรคต่างๆเบียดเสียดกันเข้ามาเพื่อจะได้ถูกต้องพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 11, 'และพวกผีโสโครกเมื่อได้เห็นพระองค์ก็ได้หมอบลงกราบพระองค์ แล้วร้องอึงว่า “พระองค์ทรงเป็นพระบุตรของพระเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 12, 'ฝ่ายพระองค์จึงทรงกําชับห้ามมันมิให้แพร่งพรายว่าพระองค์คือผู้ใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 13, 'แล้วพระองค์เสด็จขึ้นภูเขา และพอพระทัยจะเรียกผู้ใด พระองค์ก็ทรงเรียกผู้นั้น แล้วเขาได้มาหาพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 14, 'พระองค์จึงทรงตั้งสาวกสิบสองคนไว้ให้พวกเขาอยู่กับพระองค์ เพื่อพระองค์จะทรงใช้เขาไปประกาศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 15, 'และให้มีอํานาจรักษาโรคต่างๆและขับผีออกได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 16, 'และซีโมนนั้น พระองค์ทรงประทานชื่ออีกว่าเปโตร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 17, 'และยากอบบุตรชายเศเบดีกับยอห์นน้องชายของยากอบ ทั้งสองคนนี้พระองค์ทรงประทานชื่ออีกว่า โบอาเนอเย แปลว่า ลูกฟ้าร้อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 18, 'อันดรูว์ ฟีลิป บารโธโลมิว มัทธิว โธมัส ยากอบบุตรชายอัลเฟอัส ธัดเดอัส ซีโมนชาวคานาอัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 19, 'และยูดาสอิสคาริโอทที่ได้ทรยศพระองค์นั้น พระองค์และพวกสาวกจึงเข้าไปในเรือน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 20, 'และฝูงชนก็มาประชุมกันอีก จนพระองค์และพวกสาวกจะรับประทานอาหารไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 21, 'เมื่อญาติมิตรของพระองค์ได้ยินเหตุการณ์นั้น เขาก็ออกไปเพื่อจะจับพระองค์ไว้ ด้วยเขาว่า “พระองค์วิกลจริตแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 22, 'พวกธรรมาจารย์ซึ่งได้ลงมาจากกรุงเยรูซาเล็มได้กล่าวว่า “ผู้นี้มีเบเอลเซบูลสิง” และ “ที่เขาขับผีออกได้ก็เพราะใช้อํานาจนายผีนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 23, 'ฝ่ายพระองค์จึงเรียกคนเหล่านั้นมาตรัสแก่เขาเป็นคําอุปมาว่า “ซาตานจะขับซาตานให้ออกอย่างไรได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 24, 'ถ้าราชอาณาจักรใดๆเกิดแตกแยกกันแล้ว ราชอาณาจักรนั้นจะตั้งอยู่ไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 25, 'ถ้าครัวเรือนใดๆเกิดแตกแยกกัน ครัวเรือนนั้นจะตั้งอยู่ไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 26, 'และถ้าซาตานจะต่อสู้กับตนเอง และแตกแยกกัน มันก็ตั้งอยู่ไม่ได้ มีแต่จะสิ้นสูญไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 27, 'ไม่มีผู้ใดอาจเข้าไปในเรือนของคนที่มีกําลังมากและปล้นทรัพย์ของเขาได้ เว้นแต่จะจับคนที่มีกําลังมากนั้นมัดไว้เสียก่อน แล้วจึงจะปล้นทรัพย์ในเรือนนั้นได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 28, 'เราบอกความจริงแก่ท่านทั้งหลายว่า ความผิดบาปทุกอย่างและคําหมิ่นประมาทที่เขากล่าวนั้น จะทรงโปรดยกให้บุตรทั้งหลายของมนุษย์ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 29, 'แต่ผู้ใดจะกล่าวคําหมิ่นประมาทต่อพระวิญญาณบริสุทธิ์จะไม่ได้รับการอภัยโทษเลย แต่ผู้นั้นย่อมได้รับโทษจากการพิพากษาเป็นนิตย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 30, 'ที่ตรัสอย่างนั้นก็เพราะเขาทั้งหลายกล่าวว่า “พระองค์มีผีโสโครกเข้าสิง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 31, 'เวลานั้นมารดาและพวกน้องชายของพระองค์มายืนอยู่ข้างนอก แล้วใช้คนเข้าไปทูลเรียกพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 32, 'และประชาชนก็นั่งอยู่รอบพระองค์ เขาจึงทูลพระองค์ว่า “ดูเถิด มารดาและพวกน้องชายของพระองค์มาหาพระองค์คอยอยู่ข้างนอก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 33, 'พระองค์ตรัสตอบเขาว่า “ใครเป็นมารดาของเรา และใครเป็นพี่น้องของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 34, 'พระองค์ทอดพระเนตรคนที่นั่งล้อมรอบพระองค์นั้นแล้วตรัสว่า “ดูเถิด นี่เป็นมารดาและพี่น้องของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 35, 'ผู้ใดจะกระทําตามพระทัยพระเจ้า ผู้นั้นแหละเป็นพี่น้องชายหญิงและมารดาของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 1, 'แล้วพระองค์ทรงตั้งต้นสั่งสอนที่ฝั่งทะเลอีก ฝูงชนเป็นอันมากพากันมาหาพระองค์ เหตุฉะนั้นพระองค์จึงได้เสด็จลงไปประทับในเรือที่ทะเล และฝูงชนอยู่บนฝั่งชายทะเล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 2, 'พระองค์จึงตรัสสั่งสอนเขาหลายประการเป็นคําอุปมา และในการสอนนั้นพระองค์ตรัสแก่เขาว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 3, '“จงฟัง ดูเถิด มีผู้หว่านคนหนึ่งออกไปหว่านพืช');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 4, 'และต่อมาเมื่อเขาหว่าน เมล็ดพืชก็ตกตามหนทางบ้าง แล้วนกในอากาศก็มากินเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 5, 'บ้างก็ตกที่ซึ่งมีพื้นหิน มีเนื้อดินแต่น้อย จึงงอกขึ้นโดยเร็วเพราะดินไม่ลึก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 6, 'แต่เมื่อแดดจัด แดดก็แผดเผา และเพราะรากไม่มี จึงเหี่ยวไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 7, 'บ้างก็ตกกลางต้นหนาม ต้นหนามก็งอกขึ้นปกคลุมเสีย จึงไม่เกิดผล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 8, 'บ้างก็ตกที่ดินดี แล้วงอกงามจําเริญขึ้น เกิดผลสามสิบเท่าบ้าง หกสิบเท่าบ้าง ร้อยเท่าบ้าง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 9, 'แล้วพระองค์ตรัสแก่เขาว่า “ใครมีหู จงฟังเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 10, 'เมื่อพระองค์อยู่ตามลําพัง คนที่อยู่รอบพระองค์พร้อมกับสาวกสิบสองคน ได้ทูลถามพระองค์ถึงคําอุปมานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 11, 'พระองค์จึงตรัสแก่เขาว่า “ข้อความลึกลับแห่งอาณาจักรของพระเจ้าทรงโปรดให้ท่านทั้งหลายรู้ได้ แต่ฝ่ายคนนอกนั้นบรรดาข้อความเหล่านี้จะแจ้งให้เป็นคําอุปมาทุกอย่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 12, 'เพื่อว่าเขาจะดูแล้วดูเล่า แต่มองไม่เห็น และฟังแล้วฟังเล่า แต่ไม่เข้าใจ เกลือกว่าในเวลาหนึ่งเวลาใดเขาจะกลับใจเสียใหม่ และความผิดบาปของเขาจะได้ยกโทษเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 13, 'พระองค์ตรัสกับเขาว่า “คําอุปมานั้นพวกท่านยังไม่เข้าใจหรือ ถ้ากระนั้นท่านทั้งหลายจะเข้าใจคําอุปมาทั้งปวงอย่างไรได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 14, 'ผู้หว่านนั้นก็ได้หว่านพระวจนะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 15, 'ซึ่งตกริมหนทางนั้นได้แก่พระวจนะที่หว่านแล้ว และเมื่อบุคคลใดได้ฟัง ในทันใดนั้นซาตานก็มาชิงเอาพระวจนะซึ่งหว่านในใจเขานั้นไปเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 16, 'และซึ่งตกที่ซึ่งมีพื้นหิน มีเนื้อดินแต่น้อยนั้นก็ทํานองเดียวกัน ได้แก่บุคคลที่ได้ยินพระวจนะ และก็รับทันทีด้วยความปรีดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 17, 'แต่ไม่มีรากในตัวจึงทนอยู่ได้ชั่วคราว ภายหลังเมื่อเกิดการยากลําบากและการข่มเหงต่างๆเพราะพระวจนะนั้น ก็เลิกเสียในทันทีทันใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 18, 'และพืชซึ่งหว่านกลางหนามนั้นได้แก่บุคคลที่ได้ฟังพระวจนะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 19, 'แล้วความกังวลตามธรรมดาโลก และความลุ่มหลงในทรัพย์สมบัติ และความโลภในสิ่งอื่นๆได้เข้ามาและปกคลุมพระวจนะนั้น จึงไม่เกิดผล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 20, 'ส่วนพืชซึ่งหว่านตกในดินดีนั้น ได้แก่บุคคลที่ได้ยินพระวจนะนั้น และรับไว้ จึงเกิดผลสามสิบเท่าบ้าง หกสิบเท่าบ้าง ร้อยเท่าบ้าง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 21, 'แล้วพระองค์ตรัสแก่เขาว่า “เขาเอาเทียนมาสําหรับตั้งไว้ใต้ถัง ใต้เตียงนอนหรือ และมิใช่สําหรับตั้งไว้บนเชิงเทียนหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 22, 'เพราะว่าไม่มีสิ่งใดที่ซ่อนไว้ซึ่งจะไม่ปรากฏแจ้ง และไม่มีสิ่งใดที่ปิดบังไว้ ซึ่งจะไม่ต้องแพร่งพราย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 23, 'ถ้าใครมีหูฟังได้ จงฟังเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 24, 'พระองค์ตรัสแก่เขาว่า “จงเอาใจจดจ่อต่อสิ่งที่ท่านฟังให้ดี ท่านจะตวงให้เขาด้วยทะนานอันใด จะตวงให้ท่านด้วยทะนานอันนั้น ทั้งจะเพิ่มเติมให้อีกแก่ผู้ที่ฟังแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 25, 'ด้วยว่าผู้ใดมีอยู่แล้วจะเพิ่มเติมให้ผู้นั้นอีก แต่ผู้ใดไม่มี แม้ว่าซึ่งเขามีอยู่นั้นจะเอาไปเสียจากเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 26, 'พระองค์ตรัสว่า “อาณาจักรของพระเจ้าเปรียบเหมือนชายคนหนึ่งหว่านพืชลงในดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 27, 'แล้วกลางคืนก็นอนหลับและกลางวันก็ตื่นขึ้น ฝ่ายพืชนั้นจะงอกจําเริญขึ้นอย่างไรเขาก็ไม่รู้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 28, 'เพราะแผ่นดินเองทําให้พืชงอกจําเริญขึ้นเป็นลําต้นก่อน ภายหลังก็ออกรวง แล้วก็มีเมล็ดข้าวเต็มรวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 29, 'ครั้นสุกแล้วเขาก็ไปเกี่ยวเก็บทีเดียว เพราะว่าถึงฤดูเกี่ยวแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 30, 'และพระองค์ตรัสว่า “อาณาจักรของพระเจ้าจะเปรียบเหมือนสิ่งใด หรือจะสําแดงด้วยคําเปรียบอย่างไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 31, 'ก็เปรียบเหมือนเมล็ดมัสตาร์ดเมล็ดหนึ่ง เวลาเพาะลงในดินนั้นก็เล็กกว่าเมล็ดทั้งปวงทั่วทั้งแผ่นดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 32, 'แต่เมื่อเพาะแล้วจึงงอกขึ้นจําเริญใหญ่โตกว่าผักทั้งปวง และแตกกิ่งก้านใหญ่พอให้นกในอากาศมาอาศัยอยู่ในร่มนั้นได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 33, 'พระองค์ได้ตรัสสั่งสอนพระวจนะให้แก่เขาเป็นคําอุปมาอย่างนั้นเป็นหลายประการ ตามที่เขาจะสามารถฟังได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 34, 'และนอกจากคําอุปมา พระองค์มิได้ตรัสแก่เขาเลย แต่เมื่อพวกเขาอยู่ตามลําพัง พระองค์จึงทรงอธิบายสิ่งสารพัดนั้นแก่เหล่าสาวก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 35, 'เย็นวันนั้นพระองค์ได้ตรัสแก่เขาทั้งหลายว่า “ให้พวกเราข้ามไปฝั่งฟากข้างโน้นเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 36, 'เมื่อลาประชาชนแล้ว เขาจึงเชิญพระองค์เสด็จไปในเรือที่พระองค์ประทับอยู่นั้น และมีเรืออื่นเล็กๆหลายลําไปกับพระองค์ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 37, 'และพายุใหญ่ได้บังเกิดขึ้น และคลื่นก็ซัดเข้าไปในเรือจนเรือเต็มอยู่แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 38, 'ฝ่ายพระองค์บรรทมหนุนหมอนหลับอยู่ที่ท้ายเรือ เหล่าสาวกจึงมาปลุกพระองค์ทูลว่า “อาจารย์เจ้าข้า ข้าพเจ้าทั้งหลายกําลังจะพินาศอยู่แล้ว ท่านไม่ทรงเป็นห่วงบ้างหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 39, 'พระองค์จึงทรงตื่นขึ้นห้ามลมและตรัสแก่ทะเลว่า “จงสงบเงียบซิ” แล้วลมก็หยุดมีความสงบเงียบทั่วไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 40, 'พระองค์จึงตรัสแก่เขาว่า “ทําไมท่านกลัวอย่างนี้ ท่านยังไม่มีความเชื่อหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 41, 'ฝ่ายเขาก็เกรงกลัวนักหนาและพูดกันและกันว่า “ท่านนี้เป็นผู้ใดหนอ แม้กระทั่งลมและทะเลก็เชื่อฟังท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 1, 'ฝ่ายพระองค์กับเหล่าสาวกก็ข้ามทะเลไปยังเมืองชาวกาดารา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 2, 'พอพระองค์เสด็จขึ้นจากเรือ ทันใดนั้นมีชายคนหนึ่งออกจากอุโมงค์ฝังศพมีผีโสโครกสิงได้มาพบพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 3, 'คนนั้นอาศัยอยู่ตามอุโมงค์ฝังศพ และไม่มีผู้ใดจะผูกมัดตัวเขาได้ แม้จะล่ามด้วยโซ่ตรวนก็ไม่อยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 4, 'เพราะว่าได้ล่ามโซ่ใส่ตรวนหลายหนแล้ว เขาก็หักโซ่และฟาดตรวนเสีย ไม่มีผู้ใดมีแรงพอที่จะทําให้เขาสงบได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 5, 'เขาคลั่งร้องอึงอยู่ตามอุโมงค์ฝังศพและที่ภูเขาทั้งกลางคืนและกลางวันเสมอ และเอาหินเชือดเนื้อของตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 6, 'ครั้นเขาเห็นพระเยซูแต่ไกล เขาก็วิ่งเข้ามานมัสการพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 7, 'แล้วร้องเสียงดังว่า “ข้าแต่พระเยซูพระบุตรของพระเจ้าสูงสุด ข้าพระองค์เกี่ยวข้องอะไรกับท่านเล่า ข้าพระองค์ขอให้พระองค์ปฏิญาณในพระนามของพระเจ้าว่า จะไม่ทรมานข้าพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 8, 'ที่พูดเช่นนี้ เพราะพระองค์ได้ตรัสแก่มันว่า “อ้ายผีโสโครก จงออกมาจากคนนั้นเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 9, 'แล้วพระองค์ตรัสถามมันว่า “เจ้าชื่ออะไร” มันตอบว่า “ชื่อกอง เพราะว่าพวกข้าพระองค์หลายตนด้วยกัน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 10, 'มันจึงอ้อนวอนพระองค์เป็นอันมากมิให้ขับไล่มันออกจากแดนเมืองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 11, 'มีสุกรฝูงใหญ่กําลังหากินอยู่ที่ไหล่เขาตําบลนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 12, 'ผีเหล่านั้นก็อ้อนวอนพระองค์ว่า “ขอโปรดให้ข้าพระองค์ทั้งหลายเข้าในสุกรเหล่านี้เถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 13, 'พระเยซูก็ทรงอนุญาตทันที แล้วผีโสโครกนั้นจึงออกไปเข้าสิงอยู่ในสุกร สุกรทั้งฝูง (ประมาณสองพันตัว) ก็วิ่งกระโดดจากหน้าผาชันลงไปในทะเลสําลักน้ําตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 14, 'ฝ่ายคนเลี้ยงสุกรนั้นต่างคนต่างหนีไปเล่าเรื่องทั้งในนครและบ้านนอก แล้วคนทั้งปวงก็ออกมาดูเหตุการณ์ที่เกิดขึ้นนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 15, 'เมื่อเขามาถึงพระเยซู ก็เห็นคนที่ผีทั้งกองได้สิงนั้นนุ่งห่มผ้านั่งอยู่มีสติอารมณ์ดี เขาจึงเกรงกลัวนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 16, 'แล้วคนที่ได้เห็นก็เล่าเหตุการณ์ซึ่งบังเกิดแก่คนที่ผีสิงนั้น และซึ่งบังเกิดแก่ฝูงสุกรให้เขาฟัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 17, 'คนทั้งหลายจึงเริ่มพากันอ้อนวอนพระองค์ให้เสด็จไปเสียจากเขตแดนเมืองของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 18, 'เมื่อพระองค์กําลังเสด็จลงเรือ คนที่ผีได้สิงแต่ก่อนนั้นได้อ้อนวอนขอติดตามพระองค์ไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 19, 'พระเยซูไม่ทรงอนุญาต แต่ตรัสแก่เขาว่า “จงไปหาพวกพ้องของเจ้าที่บ้าน แล้วบอกเขาถึงเรื่องเหตุการณ์ใหญ่ซึ่งองค์พระผู้เป็นเจ้าได้ทรงกระทําแก่เจ้า และได้ทรงพระเมตตาแก่เจ้าแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 20, 'ฝ่ายคนนั้นก็ทูลลา แล้วเริ่มประกาศในแคว้นทศบุรีถึงเหตุการณ์ใหญ่ที่พระเยซูได้ทรงกระทําแก่เขา และคนทั้งปวงก็ประหลาดใจนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 21, 'ครั้นพระเยซูเสด็จลงเรือข้ามฟากกลับไปแล้ว มีคนเป็นอันมากมาหาพระองค์ และพระองค์ยังประทับที่ฝั่งทะเล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 22, 'ดูเถิด มีนายธรรมศาลาคนหนึ่งชื่อไยรัสเดินมา และเมื่อเขาเห็นพระองค์ก็กราบลงที่พระบาทของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 23, 'แล้วทูลอ้อนวอนพระองค์เป็นอันมากว่า “ลูกสาวเล็กๆของข้าพระองค์ป่วยเกือบจะตายแล้ว ขอเชิญพระองค์ไปวางพระหัตถ์บนเขา เพื่อเขาจะได้หายโรคและไม่ตาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 24, 'ฝ่ายพระเยซูได้เสด็จไปกับคนนั้น มีคนเป็นอันมากตามพระองค์ไป และเบียดเสียดพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 25, 'มีผู้หญิงคนหนึ่งเป็นโรคตกเลือดได้สิบสองปีมาแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 26, 'ได้ทนทุกข์ลําบากมากเพราะมีหมอหลายคนมารักษา และได้เสียทรัพย์จนหมดสิ้น โรคนั้นก็มิได้บรรเทาแต่ยิ่งกําเริบขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 27, 'ครั้นผู้หญิงนั้นได้ยินถึงเรื่องพระเยซู เธอก็เดินปะปนกับประชาชนที่เบียดเสียดข้างหลังพระองค์ และได้ถูกต้องฉลองพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 28, 'เพราะเธอคิดว่า “ถ้าเราได้แตะต้องแต่ฉลองพระองค์ เราก็จะหายโรค”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 29, 'ในทันใดนั้นเลือดที่ตกก็หยุดแห้งไป และผู้หญิงนั้นรู้สึกตัวว่าโรคหายแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 30, 'บัดเดี๋ยวนั้น พระเยซูทรงรู้สึกว่าฤทธิ์ซ่านออกจากพระองค์แล้ว จึงเหลียวหลังในขณะที่ฝูงชนเบียดเสียดกันนั้นตรัสว่า “ใครถูกต้องเสื้อของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 31, 'ฝ่ายเหล่าสาวกก็ทูลพระองค์ว่า “พระองค์ทอดพระเนตรเห็นแล้วว่า ประชาชนกําลังเบียดเสียดพระองค์ และพระองค์จะทรงถามอีกหรือว่า ‘ใครถูกต้องเรา’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 32, 'แล้วพระองค์ทอดพระเนตรดูรอบ ประสงค์จะเห็นผู้หญิงที่ได้กระทําสิ่งนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 33, 'ฝ่ายผู้หญิงนั้นก็กลัวจนตัวสั่น เพราะรู้เรื่องที่เป็นแก่ตัวนั้น จึงมากราบลงทูลแก่พระองค์ตามจริงทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 34, 'พระองค์จึงตรัสแก่ผู้หญิงนั้นว่า “ลูกสาวเอ๋ย ที่เจ้าหายโรคนั้นก็เพราะเจ้าเชื่อ จงไปเป็นสุขและหายโรคนี้เถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 35, 'เมื่อพระองค์ตรัสยังไม่ทันขาดคํา มีบางคนได้มาจากบ้านนายธรรมศาลาบอกว่า “ลูกสาวของท่านตายเสียแล้ว ยังจะรบกวนอาจารย์ทําไมอีกเล่า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 36, 'ทันทีที่พระเยซูทรงฟังคําซึ่งเขาว่านั้น พระองค์จึงตรัสแก่นายธรรมศาลาว่า “อย่าวิตกเลย จงเชื่อเท่านั้นเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 37, 'พระองค์ไม่ทรงอนุญาตให้ผู้ใดไปด้วยเว้นแต่เปโตร ยากอบ และยอห์นน้องชายของยากอบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 38, 'ครั้นพระองค์เสด็จไปถึงเรือนนายธรรมศาลาแล้ว ก็ทอดพระเนตรเห็นคนวุ่นวายร้องไห้คร่ําครวญเป็นอันมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 39, 'และเมื่อพระองค์เสด็จเข้าไปแล้วจึงตรัสถามเขาว่า “ท่านทั้งหลายพากันร้องไห้วุ่นวายไปทําไม เด็กหญิงนั้นไม่ตายแต่นอนหลับอยู่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 40, 'เขาก็พากันหัวเราะเยาะพระองค์ แต่เมื่อพระองค์ขับคนทั้งหลายออกไปแล้ว จึงนําบิดามารดาของเด็กหญิงนั้นและสาวกสามคนที่อยู่กับพระองค์ เข้าไปในที่ที่เด็กหญิงนอนอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 41, 'พระองค์จึงจับมือเด็กหญิงนั้นตรัสแก่เขาว่า “ทาลิธา คูมิ” แปลว่า “เด็กหญิงเอ๋ย เราว่าแก่เจ้าว่า จงลุกขึ้นเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 42, 'ในทันใดนั้นเด็กหญิงนั้นก็ลุกขึ้นเดิน เพราะว่าเด็กนั้นอายุได้สิบสองปี คนทั้งปวงก็ประหลาดใจอย่างยิ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 43, 'พระองค์ก็กําชับห้ามเขาแข็งแรงไม่ให้บอกผู้ใดให้รู้เหตุการณ์นี้ แล้วจึงสั่งเขาให้นําอาหารมาให้เด็กนั้นรับประทาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 1, 'ฝ่ายพระองค์ได้เสด็จออกจากที่นั่น ไปยังบ้านเมืองของพระองค์ และเหล่าสาวกของพระองค์ก็ตามพระองค์ไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 2, 'พอถึงวันสะบาโตพระองค์ทรงตั้งต้นสั่งสอนในธรรมศาลา และคนเป็นอันมากที่ได้ยินพระองค์ก็ประหลาดใจนักพูดกันว่า “คนนี้ได้ความคิดนี้มาจากไหน สติปัญญาที่ได้ประทานแก่คนนี้เป็นปัญญาอย่างใด จึงทําการมหัศจรรย์อย่างนี้สําเร็จด้วยมือของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 3, 'คนนี้เป็นช่างไม้บุตรชายนางมารีย์มิใช่หรือ ยากอบ โยเสส ยูดาส และซีโมนเป็นน้องชายมิใช่หรือ และน้องสาวทั้งหลายของเขาก็อยู่ที่นี่กับเรามิใช่หรือ” เขาทั้งหลายจึงหมางใจในพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 4, 'ฝ่ายพระเยซูตรัสกับเขาว่า “ศาสดาพยากรณ์จะไม่ขาดความนับถือเว้นแต่ในบ้านเมืองของตน ท่ามกลางญาติพี่น้องของตน และในวงศ์วานของตน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 5, 'พระองค์จะกระทําการมหัศจรรย์ที่นั่นไม่ได้ เว้นแต่ได้วางพระหัตถ์ถูกต้องคนเจ็บบางคนให้หายโรค');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 6, 'พระองค์ก็ประหลาดพระทัยเพราะเขาไม่มีความเชื่อ แล้วพระองค์จึงเสด็จไปสั่งสอนตามหมู่บ้านโดยรอบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 7, 'พระองค์ทรงเรียกสาวกสิบสองคนมา แล้วทรงเริ่มใช้เขาให้ออกไปเป็นคู่ๆ ทรงประทานอํานาจให้เขาขับผีโสโครกออกได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 8, 'และตรัสกําชับเขาไม่ให้เอาอะไรไปใช้ตามทางเว้นแต่ไม้เท้าสิ่งเดียว ห้ามมิให้เอาอาหารหรือย่าม หรือหาสตางค์ใส่ไถ้ไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 9, 'แต่ให้สวมรองเท้าและไม่ให้สวมเสื้อสองตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 10, 'แล้วพระองค์ตรัสสั่งเขาว่า “ถ้าไปแห่งใด เมื่อเข้าอาศัยในเรือนไหน ก็อาศัยในเรือนนั้นจนกว่าจะไปจากที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 11, 'และถ้าผู้ใดไม่ต้อนรับไม่ฟังท่านทั้งหลาย เมื่อจะไปจากที่นั่นจงสะบัดผงคลีใต้ฝ่าเท้าของท่านออกเป็นสักขีพยานต่อเขา เราบอกความจริงแก่ท่านว่า ในวันพิพากษานั้น โทษของเมืองโสโดมและเมืองโกโมราห์จะเบากว่าโทษของเมืองนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 12, 'ฝ่ายเหล่าสาวกก็ออกไปเทศนาประกาศให้คนทั้งปวงกลับใจเสียใหม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 13, 'เขาได้ขับผีให้ออกเสียหลายผี และได้เอาน้ํามันชโลมคนเจ็บป่วยหลายคนให้หายโรค');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 14, 'ฝ่ายกษัตริย์เฮโรดทรงได้ยินเรื่องของพระองค์ (เพราะว่าพระนามของพระองค์ได้เลื่องลือไป) แล้วท่านตรัสว่า “ยอห์นผู้ให้รับบัพติศมาเป็นขึ้นมาจากความตายแล้ว เหตุฉะนั้นจึงทําการมหัศจรรย์ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 15, 'แต่คนอื่นว่า “เป็นเอลียาห์” และคนอื่นๆว่า “เป็นศาสดาพยากรณ์คนหนึ่งหรือเหมือนคนหนึ่งในพวกศาสดาพยากรณ์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 16, 'ฝ่ายเฮโรดเมื่อทรงได้ยินแล้วจึงตรัสว่า “คือยอห์นนั้นเองที่เราได้ตัดศีรษะเสีย ท่านได้เป็นขึ้นมาจากความตาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 17, 'ด้วยว่าเฮโรดได้ใช้คนไปจับยอห์น และล่ามโซ่ขังคุกไว้ เพราะเห็นแก่นางเฮโรเดียสภรรยาฟีลิปน้องชายของตน ด้วยเฮโรดได้รับนางนั้นเป็นภรรยาของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 18, 'เพราะยอห์นได้เคยทูลเฮโรดว่า “ท่านผิดพระราชบัญญัติที่รับภรรยาของน้องชายมาเป็นภรรยาของตน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 19, 'นางเฮโรเดียสจึงผูกพยาบาทยอห์นและปรารถนาจะฆ่าท่านเสียแต่ฆ่าไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 20, 'เพราะเฮโรดยําเกรงยอห์นด้วยรู้ว่า ท่านเป็นคนชอบธรรมและบริสุทธิ์จึงได้ป้องกันท่านไว้ เมื่อเฮโรดได้ยินคําสั่งสอนของท่านก็ปฏิบัติตามหลายสิ่งและยินดีรับฟังท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 21, 'ครั้นอยู่มาวันหนึ่งเป็นโอกาสดีคือเป็นวันฉลองวันกําเนิดของเฮโรด เฮโรดให้จัดการเลี้ยงขุนนางกับนายทหารชั้นผู้ใหญ่ และคนสําคัญๆทั้งปวงในแคว้นกาลิลี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 22, 'เมื่อบุตรสาวของนางเฮโรเดียสเข้ามาเต้นรํา ทําให้เฮโรดและแขกทั้งปวงซึ่งเอนกายลงอยู่ด้วยกันนั้นชอบใจ กษัตริย์จึงตรัสกับหญิงสาวนั้นว่า “เธอจะขอสิ่งใดจากเรา เราก็จะให้สิ่งนั้นแก่เธอ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 23, 'และกษัตริย์จึงทรงปฏิญาณตัวไว้กับหญิงสาวนั้นว่า “เธอจะขอสิ่งใดๆจากเรา เราจะให้สิ่งนั้นแก่เธอจนถึงครึ่งราชสมบัติของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 24, 'หญิงสาวนั้นจึงออกไปถามมารดาว่า “ฉันจะขอสิ่งใดดี” มารดาจึงตอบว่า “จงขอศีรษะยอห์นผู้ให้รับบัพติศมาเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 25, 'ในทันใดนั้นหญิงสาวก็รีบเข้าไปเฝ้ากษัตริย์ทูลว่า “หม่อมฉันขอศีรษะยอห์นผู้ให้รับบัพติศมาใส่ถาดมาให้หม่อมฉันเดี๋ยวนี้เพคะ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 26, 'กษัตริย์ทรงเป็นทุกข์นัก แต่เพราะเหตุได้ทรงปฏิญาณไว้และเพราะเห็นแก่หน้าแขกทั้งปวงซึ่งเอนกายลงอยู่ด้วยกัน ก็ปฏิเสธไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 27, 'ในขณะนั้นกษัตริย์จึงรับสั่งเพชฌฆาตให้ไปตัดศีรษะยอห์นมา เพชฌฆาตก็ไปตัดศีรษะยอห์นในคุก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 28, 'เอาศีรษะของยอห์นใส่ถาดมาให้แก่หญิงสาวนั้น หญิงสาวนั้นก็เอาไปให้แก่มารดาของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 29, 'เมื่อสาวกของยอห์นรู้เหตุแล้ว ก็พากันมารับเอาศพของท่านไปฝังไว้ในอุโมงค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 30, 'ฝ่ายอัครสาวกพากันมาหาพระเยซู และได้ทูลถึงบรรดาการซึ่งเขาได้กระทําและได้สั่งสอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 31, 'แล้วพระองค์ตรัสแก่เขาว่า “ท่านทั้งหลายจงไปหาที่เปลี่ยวหยุดพักหายเหนื่อยสักหน่อยหนึ่ง” เพราะว่ามีคนไปมาเป็นอันมากจนไม่มีเวลาว่างจะรับประทานอาหารได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 32, 'พระองค์จึงเสด็จลงเรือกับสาวกไปยังที่เปลี่ยวแต่ลําพัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 33, 'คนเป็นอันมากเห็นพระองค์กับสาวกกําลังไป และมีหลายคนจําพระองค์ได้ จึงพากันวิ่งออกจากบ้านเมืองทั้งปวงไปถึงก่อน และพากันเฝ้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 34, 'ครั้นพระเยซูเสด็จขึ้นจากเรือแล้ว ก็ทอดพระเนตรเห็นประชาชนหมู่ใหญ่ และพระองค์ทรงสงสารเขา เพราะว่าเขาเป็นเหมือนฝูงแกะไม่มีผู้เลี้ยง พระองค์จึงเริ่มสั่งสอนเขาเป็นหลายข้อหลายประการ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 35, 'เมื่อเวลาล่วงไปมากแล้ว พวกสาวกของพระองค์มาทูลพระองค์ว่า “ที่นี่กันดารอาหารนัก และบัดนี้เวลาก็เย็นลงมากแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 36, 'ขอให้ประชาชนไปเสียเถิด เพื่อเขาจะได้ไปซื้ออาหารรับประทานตามบ้านไร่บ้านนาที่อยู่แถบนี้ เพราะเขาไม่มีอะไรที่จะรับประทานเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 37, 'แต่พระองค์ตรัสตอบแก่เหล่าสาวกว่า “พวกท่านจงเลี้ยงเขาเถิด” เขาทูลพระองค์ว่า “จะให้พวกข้าพระองค์ไปซื้ออาหารสักสองร้อยเหรียญเดนาริอันให้เขารับประทานหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 38, 'พระองค์ตรัสตอบเขาว่า “พวกท่านมีขนมปังอยู่กี่ก้อน ไปดูซิ” เมื่อรู้แล้วเขาจึงทูลว่า “มีขนมปังห้าก้อนกับปลาสองตัว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 39, 'พระองค์จึงตรัสสั่งพวกสาวกให้จัดคนทั้งปวงให้นั่งรวมกันที่หญ้าสดเป็นหมู่ๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 40, 'ประชาชนก็ได้นั่งรวมกันเป็นหมู่ๆ หมู่ละร้อยคนบ้าง ห้าสิบบ้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 41, 'เมื่อพระองค์ทรงรับขนมปังห้าก้อนกับปลาสองตัวนั้นแล้ว ก็แหงนพระพักตร์ดูฟ้าสวรรค์ขอบพระคุณ แล้วหักขนมปังนั้นให้เหล่าสาวกให้เขาแจกแก่คนทั้งปวง และปลาสองตัวนั้นพระองค์ทรงแบ่งให้ทั่วกันด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 42, 'เขาได้กินอิ่มทุกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 43, 'ส่วนเศษขนมปังและปลาที่เหลือนั้นเขาเก็บไว้ได้ถึงสิบสองกระบุงเต็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 44, 'และในจํานวนคนที่ได้รับประทานขนมปังนั้น มีผู้ชายประมาณห้าพันคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 45, 'และทันใดนั้นพระองค์ได้ตรัสให้เหล่าสาวกของพระองค์ลงในเรือข้ามไปยังอีกฟากหนึ่งถึงเมืองเบธไซดาก่อน ส่วนพระองค์ทรงรอส่งประชาชนกลับบ้าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 46, 'เมื่อพระองค์ทรงลาเขาทั้งหลายแล้วก็เสด็จขึ้นภูเขาเพื่ออธิษฐานที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 47, 'เมื่อค่ําลงแล้ว เรือของเหล่าสาวกอยู่กลางทะเล ส่วนพระองค์อยู่บนฝั่งแต่ผู้เดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 48, 'แล้วพระองค์ทอดพระเนตรเห็นเหล่าสาวกตีกรรเชียงลําบากเพราะทวนลมอยู่ ครั้นเวลาสามยามเศษ พระองค์จึงทรงดําเนินบนน้ําทะเลไปยังเหล่าสาวก และทรงดําเนินดังจะเลยเขาไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 49, 'เมื่อเหล่าสาวกเห็นพระองค์ทรงดําเนินบนทะเล เขาสําคัญว่าผี แล้วพากันร้องอึงไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 50, 'เพราะว่าทุกคนเห็นพระองค์แล้วก็กลัว แต่ในทันใดนั้นพระองค์ตรัสแก่เขาว่า “จงชื่นใจเถิด คือเราเอง อย่ากลัวเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 51, 'พระองค์จึงเสด็จขึ้นไปหาเขาบนเรือ แล้วลมก็เงียบลง เหล่าสาวกก็ประหลาดอัศจรรย์ใจเหลือประมาณ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 52, 'ด้วยว่าการอัศจรรย์เรื่องขนมปังนั้นเขายังไม่เข้าใจ เพราะใจเขายังแข็งกระด้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 53, 'ครั้นข้ามฟากไปแล้ว เขาจอดเรือที่แคว้นเยนเนซาเรท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 54, 'เมื่อขึ้นจากเรือแล้ว คนทั้งปวงก็จําพระองค์ได้ทันที');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 55, 'และเขารีบไปทั่วตลอดแว่นแคว้นล้อมรอบ เริ่มเอาคนเจ็บป่วยใส่แคร่หามมายังที่เขาได้ยินข่าวว่าพระองค์อยู่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 56, 'แล้วพระองค์เสด็จไปที่ไหนๆ ไม่ว่าในหมู่บ้าน ในตําบล หรือในเมือง เขาก็เอาคนเจ็บป่วยมาวางตามถนน ทูลอ้อนวอนขอพระองค์โปรดให้คนเจ็บป่วยแตะต้องแต่ชายฉลองพระองค์ และผู้ใดได้แตะต้องพระองค์แล้วก็หายป่วยทุกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 1, 'ครั้งนั้นพวกฟาริสีกับพวกธรรมาจารย์บางคน ซึ่งได้มาจากกรุงเยรูซาเล็ม พากันมาหาพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 2, 'เมื่อเขาได้เห็นเหล่าสาวกของพระองค์บางคนรับประทานอาหารด้วยมือที่เป็นมลทิน คือมือที่ไม่ได้ล้างก่อน เขาก็ถือว่าผิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 3, 'เพราะว่าพวกฟาริสีกับพวกยิวทั้งสิ้นถือตามประเพณีสืบทอดมาจากบรรพบุรุษว่า ถ้ามิได้ล้างมือตามพิธีโดยเคร่งครัด เขาก็ไม่รับประทานอาหารเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 4, 'และเมื่อเขามาจากตลาด ถ้ามิได้ล้างก่อน เขาก็ไม่รับประทานอาหาร และธรรมเนียมอื่นๆอีกหลายอย่างเขาก็ถือ คือล้างถ้วย เหยือก ภาชนะทองเหลือง และโต๊ะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 5, 'พวกฟาริสีกับพวกธรรมาจารย์จึงทูลถามพระองค์ว่า “ทําไมพวกสาวกของท่านไม่ดําเนินชีวิตตามประเพณีสืบทอดมาจากบรรพบุรุษ แต่รับประทานอาหารโดยมิได้ล้างมือเสียก่อน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 6, 'พระองค์ตรัสตอบเขาว่า “อิสยาห์ได้พยากรณ์ถึงพวกเจ้าคนหน้าซื่อใจคดก็ถูก ตามที่ได้เขียนไว้ว่า ‘ประชาชนนี้ให้เกียรติเราด้วยริมฝีปากของเขา แต่ใจของเขาห่างไกลจากเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 7, 'เขานมัสการเราโดยหาประโยชน์มิได้ ด้วยเอาบทบัญญัติของมนุษย์มาอวดอ้างว่า เป็นพระดํารัสสอน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 8, 'เจ้าทั้งหลายละพระบัญญัติของพระเจ้า และกลับไปถือตามประเพณีของมนุษย์ คือการล้างถ้วยเหยือก และสิ่งอื่นๆเช่นนี้อีกหลายสิ่ง เจ้าทั้งหลายก็ทําอยู่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 9, 'พระองค์ตรัสแก่เขาว่า “เหมาะจริงนะ ที่เจ้าทั้งหลายได้ละทิ้งพระบัญญัติของพระเจ้า เพื่อจะได้ถือตามประเพณีของพวกท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 10, 'เพราะโมเสสได้สั่งไว้ว่า ‘จงให้เกียรติแก่บิดามารดาของตน’ และ ‘ผู้ใดแช่งด่าบิดามารดา ผู้นั้นต้องถูกปรับโทษถึงตาย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 11, 'แต่พวกเจ้ากลับสอนว่า ‘ผู้ใดจะกล่าวแก่บิดามารดาว่า “สิ่งใดของข้าพเจ้าซึ่งอาจเป็นประโยชน์แก่ท่าน สิ่งนั้นเป็นโกระบัน”’ แปลว่าเป็นของถวายแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 12, 'เจ้าทั้งหลายจึงไม่อนุญาตให้ผู้นั้นทําสิ่งใดต่อไป เป็นที่ช่วยบํารุงบิดามารดาของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 13, 'เจ้าทั้งหลายจึงทําให้พระวจนะของพระเจ้าเป็นหมันไปด้วยประเพณีของพวกท่านซึ่งพวกท่านได้สอนไว้ และสิ่งอื่นๆเช่นนี้อีกหลายสิ่ง เจ้าทั้งหลายก็ทําอยู่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 14, 'แล้วเมื่อพระองค์ได้ทรงเรียกประชาชนทั้งหลายเข้ามาก็ตรัสกับเขาว่า “ท่านทั้งหลายจงฟังเราและเข้าใจเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 15, 'ไม่มีสิ่งใดภายนอกที่เข้าไปภายในมนุษย์จะกระทําให้มนุษย์เป็นมลทินได้ แต่สิ่งซึ่งออกมาจากภายในมนุษย์ สิ่งนั้นแหละกระทําให้มนุษย์เป็นมลทิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 16, 'ใครมีหูฟังได้ จงฟังเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 17, 'ครั้นพระองค์ได้เสด็จเข้าไปในเรือนพ้นประชาชนแล้ว เหล่าสาวกของพระองค์ก็ได้ทูลถามพระองค์ถึงคําอุปมานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 18, 'พระองค์จึงตรัสแก่เขาว่า “ถึงท่านทั้งหลายก็ยังไม่เข้าใจหรือ ท่านยังไม่เห็นหรือว่าสิ่งใดๆแต่ภายนอกที่เข้าไปภายในมนุษย์จะกระทําให้มนุษย์เป็นมลทินไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 19, 'เพราะว่าสิ่งนั้นมิได้เข้าในใจ แต่ลงไปในท้องแล้วก็ถ่ายออกลงส้วมไป ทําให้อาหารทุกอย่างปราศจากมลทิน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 20, 'พระองค์ตรัสว่า “สิ่งที่ออกมาจากภายในมนุษย์ สิ่งนั้นแหละทําให้มนุษย์เป็นมลทิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 21, 'เพราะว่าจากภายในมนุษย์คือจากใจมนุษย์ มีความคิดชั่วร้าย การล่วงประเวณี การผิดผัวผิดเมีย การฆาตกรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 22, 'การลักขโมย การโลภ ความชั่ว การล่อลวงเขา ราคะตัณหา แววตาอันชั่วร้าย การหมิ่นประมาท ความเย่อหยิ่ง ความโฉด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 23, 'สารพัดการชั่วนี้เกิดมาจากภายใน และทําให้มนุษย์เป็นมลทิน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 24, 'พระองค์จึงทรงลุกขึ้นจากที่นั่นไปยังเขตแดนเมืองไทระและเมืองไซดอน แล้วเข้าไปในเรือนแห่งหนึ่งประสงค์จะมิให้ผู้ใดรู้ แต่พระองค์จะซ่อนอยู่มิได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 25, 'เพราะผู้หญิงคนหนึ่งซึ่งมีลูกสาวที่มีผีโสโครกสิง เมื่อได้ยินข่าวถึงพระองค์ก็มากราบลงที่พระบาทของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 26, 'ผู้หญิงนั้นเป็นชาวกรีก ชาติซีเรียฟีนิเซีย และนางทูลอ้อนวอนขอพระองค์ให้ขับผีออกจากลูกสาวของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 27, 'ฝ่ายพระเยซูตรัสแก่นางนั้นว่า “ให้พวกลูกกินอิ่มเสียก่อน เพราะว่าซึ่งจะเอาอาหารของลูกโยนให้แก่สุนัขก็ไม่ควร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 28, 'แต่นางทูลตอบพระองค์ว่า “จริงด้วย พระองค์เจ้าข้า แต่สุนัขที่อยู่ใต้โต๊ะนั้นย่อมกินเดนอาหารของลูก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 29, 'แล้วพระองค์ตรัสแก่นางว่า “เพราะเหตุถ้อยคํานี้จงกลับไปเถิด ผีออกจากลูกสาวของเจ้าแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 30, 'ฝ่ายหญิงนั้นเมื่อไปยังเรือนของตน ได้เห็นลูกนอนอยู่บนที่นอน และทราบว่าผีออกแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 31, 'ต่อมาพระองค์จึงเสด็จจากเขตแดนเมืองไทระและเมืองไซดอน ดําเนินตามทางแคว้นทศบุรี มายังทะเลกาลิลี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 32, 'เขาพาชายหูหนวกพูดติดอ่างคนหนึ่งมาหาพระองค์ แล้วทูลอ้อนวอนขอพระองค์ให้ทรงวางพระหัตถ์บนคนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 33, 'พระองค์จึงทรงนําคนนั้นออกจากประชาชนไปอยู่ต่างหาก ทรงเอานิ้วพระหัตถ์ยอนเข้าที่หูของชายผู้นั้น และทรงบ้วนน้ําลายเอานิ้วพระหัตถ์จิ้มแตะลิ้นคนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 34, 'แล้วพระองค์ทรงแหงนพระพักตร์ดูฟ้าสวรรค์ ทรงถอนพระทัยตรัสแก่คนนั้นว่า “เอฟฟาธา” แปลว่า “จงเปิดออก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 35, 'แล้วในทันใดนั้นหูคนนั้นก็ปกติ สิ่งที่ขัดลิ้นนั้นก็หลุดและเขาพูดได้ชัด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 36, 'พระองค์ทรงห้ามปรามคนทั้งหลายมิให้แจ้งความนี้แก่ผู้ใดเลย แต่พระองค์ยิ่งทรงห้ามปรามพวกเขา เขาก็ยิ่งเล่าลือไปมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 37, 'พวกเขาก็ประหลาดใจเหลือเกิน พูดกันว่า “พระองค์ทรงกระทําล้วนแต่ดีทั้งนั้น ทรงกระทําคนหูหนวกให้ได้ยิน คนใบ้ให้พูดได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 1, 'คราวนั้นเมื่อฝูงชนพากันมามากมายและไม่มีอาหารกิน พระเยซูจึงทรงเรียกเหล่าสาวกของพระองค์มาตรัสแก่เขาว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 2, '“เราสงสารคนเหล่านี้ เพราะเขาค้างอยู่กับเราได้สามวันแล้วและไม่มีอาหารจะกิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 3, 'ถ้าเราจะให้เขากลับไปบ้านเมื่อยังอดอาหารอยู่ เขาจะหิวโหยสิ้นแรงตามทาง เพราะว่าบางคนมาไกล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 4, 'เหล่าสาวกของพระองค์จึงทูลตอบพระองค์ว่า “ในถิ่นทุรกันดารนี้จะหาอาหารให้เขากินอิ่มได้ที่ไหน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 5, 'พระองค์ตรัสถามเขาว่า “พวกท่านมีขนมปังกี่ก้อน” เขาทูลว่า “มีเจ็ดก้อน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 6, 'พระองค์จึงตรัสสั่งประชาชนให้นั่งลงที่พื้นดิน แล้วทรงรับขนมปังเจ็ดก้อนนั้น ทรงขอบพระคุณ แล้วจึงทรงหักส่งให้เหล่าสาวกให้เขาแจก เหล่าสาวกจึงแจกให้ประชาชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 7, 'และเขามีปลาเล็กๆอยู่บ้าง พระองค์จึงขอบพระคุณ แล้วสั่งให้เอาปลานั้นแจกด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 8, 'คนทั้งปวงได้รับประทานจนอิ่มและเศษอาหารที่เหลือนั้นเขาเก็บได้เจ็ดกระบุง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 9, 'คนที่รับประทานนั้นมีประมาณสี่พัน แล้วพระองค์ตรัสสั่งให้เขาไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 10, 'ในทันใดนั้น พระองค์ก็เสด็จลงเรือกับเหล่าสาวกของพระองค์ มาถึงเขตเมืองดาลมานูธา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 11, 'พวกฟาริสีออกมาและเริ่มโต้เถียงกับพระองค์ ขอพระองค์แสดงหมายสําคัญจากฟ้าสวรรค์ หมายจะทดลองพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 12, 'พระองค์ทรงถอนพระทัยแล้วตรัสว่า “คนยุคนี้แสวงหาหมายสําคัญทําไม เราบอกความจริงแก่เจ้าทั้งหลายว่า จะไม่โปรดให้หมายสําคัญแก่คนยุคนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 13, 'แล้วพระองค์เสด็จไปจากเขา และลงเรือข้ามฟากไปอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 14, 'ฝ่ายเหล่าสาวกลืมเอาขนมปังไป และในเรือเขามีขนมปังอยู่ก้อนเดียวเท่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 15, 'พระองค์ทรงกําชับเหล่าสาวกว่า “จงสังเกตและระวังเชื้อแห่งพวกฟาริสีและเชื้อแห่งเฮโรดให้ดี”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 16, 'เหล่าสาวกจึงปรึกษากันว่า “เพราะเหตุที่เราไม่มีขนมปัง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 17, 'เมื่อพระเยซูทรงทราบจึงตรัสแก่เขาว่า “เหตุไฉนพวกท่านจึงปรึกษากันและกันถึงเรื่องไม่มีขนมปัง ท่านยังไม่รู้และไม่เข้าใจหรือ ใจของท่านยังแข็งกระด้างหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 18, 'มีตาแล้วยังไม่เห็นหรือ มีหูแล้วยังไม่ได้ยินหรือ ท่านทั้งหลายจําไม่ได้หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 19, 'เมื่อเราหักขนมปังห้าก้อนให้แก่คนห้าพันคนนั้น ท่านทั้งหลายเก็บเศษที่เหลือนั้นได้กี่กระบุง” เขาทูลตอบพระองค์ว่า “ได้สิบสองกระบุง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 20, '“เมื่อแจกขนมปังเจ็ดก้อนให้แก่คนสี่พันคนนั้น ท่านทั้งหลายเก็บเศษที่เหลือได้กี่กระบุง” เขาทูลตอบว่า “ได้เจ็ดกระบุง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 21, 'พระองค์จึงตรัสแก่เขาว่า “เป็นไฉนพวกท่านยังไม่เข้าใจ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 22, 'พระองค์จึงไปยังเมืองเบธไซดา เขาพาชายตาบอดคนหนึ่งมาหาพระองค์ ทูลอ้อนวอนขอพระองค์ให้โปรดถูกต้องคนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 23, 'พระองค์ได้ทรงจูงมือคนตาบอดออกไปนอกเมือง เมื่อได้ทรงบ้วนน้ําลายลงที่ตาคนนั้น และวางพระหัตถ์บนเขาแล้ว พระองค์จึงตรัสถามเขาว่า เขาเห็นสิ่งใดบ้างหรือไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 24, 'คนนั้นเงยหน้าดูแล้วทูลว่า “ข้าพระองค์แลเห็นคนเหมือนต้นไม้เดินไปเดินมา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 25, 'พระองค์จึงวางพระหัตถ์บนตาเขาอีก แล้วให้เขาเงยหน้าดู และตาของเขาก็หายเป็นปกติ แลเห็นคนทั้งหลายได้ชัดเจน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 26, 'พระองค์จึงตรัสสั่งคนนั้นให้กลับตรงไปยังบ้านของตน แล้วกําชับว่า “อย่าเข้าไปในเมือง หรือเล่าให้ใครในเมืองนั้นฟังเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 27, 'พระเยซูได้เสด็จกับเหล่าสาวกของพระองค์ ออกไปยังเมืองต่างๆในแขวงซีซารียา ฟีลิปปี เมื่ออยู่ตามทางนั้น พระองค์ตรัสถามเหล่าสาวกว่า “คนทั้งหลายพูดกันว่าเราเป็นผู้ใด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 28, 'เขาทูลตอบว่า “เขาว่าเป็นยอห์นผู้ให้รับบัพติศมา แต่บางคนว่าเป็นเอลียาห์ และคนอื่นว่าเป็นคนหนึ่งในพวกศาสดาพยากรณ์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 29, 'พระองค์จึงตรัสถามเขาว่า “ฝ่ายพวกท่านเล่าว่าเราเป็นผู้ใด” เปโตรทูลตอบพระองค์ว่า “พระองค์ทรงเป็นพระคริสต์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 30, 'แล้วพระองค์ทรงกําชับห้ามเหล่าสาวกไม่ให้บอกผู้ใดถึงพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 31, 'พระองค์จึงทรงเริ่มกล่าวสอนสาวกว่า บุตรมนุษย์จะต้องทนทุกข์ทรมานหลายประการ พวกผู้ใหญ่ พวกปุโรหิตใหญ่ และพวกธรรมาจารย์จะปฏิเสธพระองค์ และพระองค์จะต้องถูกประหารชีวิต แต่ในวันที่สามพระองค์จะทรงเป็นขึ้นมาใหม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 32, 'คําเหล่านี้พระองค์ตรัสอย่างเปิดเผย ฝ่ายเปโตรจึงจับพระองค์ แล้วเริ่มทูลห้ามพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 33, 'พระองค์จึงทรงหันพระพักตร์ดูเหล่าสาวกของพระองค์ แล้วทรงติเปโตรว่า “อ้ายซาตาน จงถอยไปข้างหลังเรา เพราะเจ้ามิได้คิดตามพระดําริของพระเจ้า แต่ตามความคิดของมนุษย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 34, 'และเมื่อพระองค์ทรงร้องเรียกประชาชนกับเหล่าสาวกของพระองค์ให้เข้ามาแล้ว จึงตรัสแก่เขาว่า “ถ้าผู้ใดใคร่จะตามเรามา ให้ผู้นั้นเอาชนะตัวเอง และรับกางเขนของตนแบกและตามเรามา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 35, 'เพราะว่าผู้ใดใคร่จะเอาชีวิตรอด ผู้นั้นจะเสียชีวิต แต่ผู้ใดจะเสียชีวิตเพราะเห็นแก่เราและข่าวประเสริฐ ผู้นั้นจะได้ชีวิตรอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 36, 'เพราะถ้าผู้ใดจะได้สิ่งของสิ้นทั้งโลก แต่ต้องสูญเสียจิตวิญญาณของตน ผู้นั้นจะได้ประโยชน์อะไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 37, 'เพราะว่าผู้นั้นจะนําอะไรไปแลกเอาจิตวิญญาณของตนกลับคืนมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 38, 'เหตุฉะนั้น ถ้าผู้ใดมีความอายเพราะเราและถ้อยคําของเราในชั่วอายุนี้ ซึ่งประกอบด้วยการล่วงประเวณีและการผิดบาป บุตรมนุษย์ก็จะมีความอายเพราะผู้นั้น ในเวลาเมื่อพระองค์จะเสด็จมาด้วยสง่าราศีแห่งพระบิดาของพระองค์ และด้วยเหล่าทูตสวรรค์ผู้บริสุทธิ์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 1, 'พระองค์ยังตรัสแก่เขาว่า “เราบอกความจริงแก่ท่านทั้งหลายว่า ในพวกท่านที่ยืนอยู่ที่นี่ มีบางคนที่จะไม่รู้รสความตายจนกว่าจะได้เห็นอาณาจักรของพระเจ้ามาด้วยฤทธานุภาพ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 2, 'ครั้นล่วงไปได้หกวันแล้ว พระเยซูทรงพาเปโตร ยากอบ และยอห์นขึ้นภูเขาสูงแต่ลําพัง แล้วพระกายของพระองค์ก็เปลี่ยนไปต่อหน้าเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 3, 'และฉลองพระองค์ก็ส่องประกายขาวดุจหิมะ จะหาช่างฟอกผ้าทั่วแผ่นดินโลกฟอกให้ขาวอย่างนั้นก็ไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 4, 'แล้วเอลียาห์กับโมเสสก็ปรากฏแก่พวกสาวกเหล่านั้น และเฝ้าสนทนากับพระเยซู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 5, 'ฝ่ายเปโตรทูลพระเยซูว่า “พระอาจารย์เจ้าข้า ซึ่งเราอยู่ที่นี่ก็ดี ให้พวกข้าพระองค์ทําพลับพลาสามหลัง สําหรับพระองค์หลังหนึ่ง สําหรับโมเสสหลังหนึ่ง สําหรับเอลียาห์หลังหนึ่ง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 6, 'ที่เปโตรพูดอย่างนั้นก็เพราะไม่รู้จะว่าอย่างไร ด้วยเขาทั้งหลายกําลังกลัวนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 7, 'แล้วมีเมฆมาปกคลุมเขาไว้ และมีพระสุรเสียงออกมาจากเมฆนั้นว่า “ท่านผู้นี้เป็นบุตรที่รักของเรา จงฟังท่านเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 8, 'ทันใดนั้น เมื่อสาวกแลดูรอบก็ไม่เห็นผู้ใด เห็นแต่พระเยซูทรงอยู่กับเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 9, 'เมื่อกําลังลงมาจากภูเขา พระองค์ตรัสกําชับเหล่าสาวกไม่ให้นําสิ่งที่ได้เห็นนั้นไปบอกแก่ผู้ใดเลย จนกว่าบุตรมนุษย์จะเป็นขึ้นมาจากความตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 10, 'เหตุการณ์นั้นเหล่าสาวกก็เก็บงําไว้ แต่ซักถามกันว่า ที่ตรัสว่าจะเป็นขึ้นมาจากความตายนั้น จะหมายความว่าอย่างไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 11, 'เขาจึงทูลถามพระองค์ว่า “เหตุไฉนพวกธรรมาจารย์จึงว่าเอลียาห์จะต้องมาก่อน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 12, 'พระองค์ตรัสตอบเขาว่า “เอลียาห์ต้องมาก่อนจริง และทําให้สิ่งทั้งปวงคืนสู่สภาพเดิม อนึ่งมีคําเขียนไว้อย่างไรถึงบุตรมนุษย์ว่า พระองค์จะต้องทนทุกข์เวทนาหลายประการ และคนจะดูหมิ่นละทิ้งพระองค์เสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 13, 'แต่เราบอกแก่ท่านทั้งหลายว่า เอลียาห์นั้นได้มาแล้ว และซึ่งเขาใคร่จะทําแก่ท่านอย่างไร เขาก็ได้กระทําแล้ว ตามที่มีคําเขียนกล่าวไว้ถึงท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 14, 'เมื่อพระองค์ได้เสด็จมายังเหล่าสาวก ก็ทอดพระเนตรเห็นฝูงชนเป็นอันมากอยู่ล้อมรอบเขา และพวกธรรมาจารย์กําลังซักไซ้ไล่เลียงเขาอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 15, 'ในทันใดนั้น เมื่อบรรดาประชาชนเห็นพระองค์ก็ประหลาดใจนัก จึงวิ่งเข้ามาเคารพพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 16, 'พระองค์จึงตรัสถามพวกธรรมาจารย์ว่า “ท่านซักไซ้ไล่เลียงกับเขาด้วยข้อความอันใด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 17, 'มีคนหนึ่งในหมู่ประชาชนทูลตอบว่า “อาจารย์เจ้าข้า ข้าพระองค์ได้พาบุตรชายของข้าพระองค์มาหาพระองค์เพราะผีใบ้เข้าสิง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 18, 'ผีพาเขาไปที่ไหนๆก็ทําให้ล้มชักดิ้นไป มีอาการน้ําลายฟูมปากและขบเขี้ยวเคี้ยวฟันแล้วก็อ่อนระโหย ข้าพระองค์ได้ขอเหล่าสาวกของพระองค์ให้ขับผีนั้นออกเสีย แต่เขาขับให้ออกไม่ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 19, 'พระองค์จึงตรัสแก่คนนั้นว่า “โอ คนในยุคที่ขาดความเชื่อ เราจะต้องอยู่กับเจ้านานเท่าใด เราจะต้องอดทนกับเจ้านานเท่าใด จงพาเด็กนั้นมาหาเราเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 20, 'เขาก็พาเด็กนั้นมาหาพระองค์ และเมื่อเห็นพระองค์แล้ว ในทันใดนั้นผีนั้นจึงทําให้เขาชักล้มลงกลิ้งเกลือกที่ดิน มีน้ําลายฟูมปาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 21, 'พระองค์จึงตรัสถามบิดานั้นว่า “เป็นอย่างนี้มานานสักเท่าไร” บิดาทูลตอบว่า “ตั้งแต่เป็นเด็กเล็กๆมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 22, 'และผีก็ทําให้เด็กตกในไฟและในน้ําบ่อยๆหมายจะฆ่าเสียให้ตาย แต่ถ้าพระองค์สามารถทําได้ ขอโปรดกรุณาและช่วยเราเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 23, 'พระเยซูจึงตรัสแก่บิดานั้นว่า “ถ้าท่านเชื่อได้ ใครเชื่อก็ทําให้ได้ทุกสิ่ง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 24, 'ทันใดนั้น บิดาของเด็กก็ร้องทูลด้วยน้ําตาไหลว่า “ข้าพระองค์เชื่อ พระองค์เจ้าข้า ที่ข้าพระองค์ยังขาดความเชื่อนั้น ขอพระองค์ทรงโปรดช่วยให้เชื่อเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 25, 'เมื่อพระเยซูทอดพระเนตรเห็นประชาชนกําลังวิ่งเข้ามา พระองค์ตรัสสําทับผีโสโครกนั้นว่า “อ้ายผีใบ้หูหนวก เราสั่งเจ้าให้ออกมาจากเขา อย่าได้กลับเข้าสิงเขาอีกเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 26, 'ผีนั้นจึงร้องอื้ออึงทําให้เด็กนั้นชักดิ้นเป็นอันมาก แล้วก็ออกมา เด็กนั้นก็แน่นิ่งเหมือนคนตาย จนมีหลายคนกล่าวว่า “เขาตายแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 27, 'แต่พระเยซูทรงจับมือพยุงเด็กนั้น เด็กนั้นก็ยืนขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 28, 'เมื่อพระองค์เสด็จเข้าในเรือนแล้ว เหล่าสาวกของพระองค์มาทูลถามพระองค์เป็นส่วนตัวว่า “เหตุไฉนพวกข้าพระองค์ขับผีนั้นออกไม่ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 29, 'พระองค์ตรัสตอบเขาว่า “ผีอย่างนี้จะขับให้ออกไม่ได้เลย เว้นแต่โดยการอธิษฐานและการอดอาหาร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 30, 'พระองค์กับเหล่าสาวกจึงออกไปจากที่นั่น ดําเนินไปในแคว้นกาลิลี แต่พระองค์ไม่ประสงค์จะให้ผู้ใดรู้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 31, 'ด้วยว่าพระองค์ตรัสพร่ําสอนสาวกของพระองค์ว่า “บุตรมนุษย์จะต้องถูกมอบไว้ในเงื้อมมือของคนทั้งหลาย และเขาจะประหารท่านเสีย เมื่อประหารแล้ว ในวันที่สามท่านจะเป็นขึ้นมาใหม่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 32, 'แต่ถ้อยคํานี้เหล่าสาวกหาเข้าใจไม่ ครั้นจะทูลถามพระองค์ก็เกรงใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 33, 'พระองค์จึงเสด็จมายังเมืองคาเปอรนาอุม และเมื่อเข้าไปในเรือนแล้ว พระองค์ตรัสถามเหล่าสาวกว่า “เมื่อมาตามทางนั้น ท่านทั้งหลายได้โต้แย้งกันด้วยข้อความอันใด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 34, 'เหล่าสาวกก็นิ่งอยู่ เพราะเมื่อมาตามทางนั้นเขาได้เถียงกันว่า คนไหนจะเป็นใหญ่กว่ากัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 35, 'พระองค์ได้ประทับนั่ง แล้วทรงเรียกสาวกสิบสองคนนั้นมาตรัสแก่เขาว่า “ถ้าผู้ใดใคร่จะได้เป็นคนต้น ก็ให้ผู้นั้นเป็นคนท้ายสุด และเป็นผู้รับใช้ของคนทั้งปวง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 36, 'พระองค์จึงทรงเอาเด็กเล็กๆคนหนึ่งมาให้ยืนท่ามกลางเหล่าสาวก แล้วทรงอุ้มเด็กนั้นไว้ ตรัสแก่เหล่าสาวกว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 37, '“ถ้าผู้ใดจะรับเด็กเล็กๆเช่นนี้คนหนึ่งในนามของเรา ผู้นั้นก็รับเรา และผู้ใดได้รับเรา ผู้นั้นก็มิใช่รับเรา แต่รับพระองค์ผู้ทรงใช้เรามา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 38, 'ยอห์นจึงทูลพระองค์ว่า “พระอาจารย์เจ้าข้า พวกข้าพระองค์ได้เห็นคนหนึ่งขับผีออกโดยพระนามของพระองค์ ซึ่งคนนั้นมิได้ตามพวกเรามา และพวกข้าพระองค์ได้ห้ามเขา เพราะเขามิได้ตามพวกเรามา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 39, 'พระเยซูจึงตรัสว่า “อย่าห้ามเขาเลย เพราะว่าไม่มีผู้ใดจะกระทําการอัศจรรย์ในนามของเรา แล้วอีกประเดี๋ยวหนึ่งอาจกลับพูดประณามเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 40, 'เพราะผู้ใดไม่เป็นฝ่ายต่อสู้เรา ผู้นั้นก็เป็นฝ่ายเราแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 41, 'เพราะเราบอกความจริงแก่ท่านว่า ผู้ใดจะเอาน้ําถ้วยหนึ่งให้พวกท่านดื่มในนามของเรา เพราะท่านทั้งหลายเป็นฝ่ายพระคริสต์ ผู้นั้นจะขาดบําเหน็จก็หามิได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 42, 'แต่ผู้ใดจะทําผู้เล็กน้อยเหล่านี้คนหนึ่งที่เชื่อในเราให้หลงผิด ถ้าเอาหินโม่ก้อนใหญ่ผูกคอผู้นั้นถ่วงเสียในทะเลก็ดีกว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 43, 'และถ้ามือของท่านทําให้ท่านหลงผิด จงตัดมันทิ้งเสีย ซึ่งจะเข้าสู่ชีวิตด้วยมือด้วนยังดีกว่ามีสองมือและต้องตกนรกในไฟที่ไม่มีวันดับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 44, 'ในที่นั้นตัวหนอนของพวกเขาก็ไม่ตาย และไฟก็ไม่ดับเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 45, 'ถ้าเท้าของท่านทําให้ท่านหลงผิด จงตัดมันทิ้งเสีย ซึ่งจะเข้าสู่ชีวิตด้วยเท้าด้วนยังดีกว่ามีเท้าสองเท้าและต้องถูกทิ้งลงในนรกในไฟที่ไม่มีวันดับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 46, 'ในที่นั้นตัวหนอนของพวกเขาก็ไม่ตาย และไฟก็ไม่ดับเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 47, 'ถ้าตาของท่านทําให้ท่านหลงผิด จงควักออกทิ้งเสีย ซึ่งจะเข้าในอาณาจักรของพระเจ้าด้วยตาข้างเดียวยังดีกว่ามีสองตา และต้องถูกทิ้งในไฟนรก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 48, 'ในที่นั้นตัวหนอนของพวกเขาก็ไม่ตาย และไฟก็ไม่ดับเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 49, 'ด้วยว่าคนทั้งปวงจะต้องถูกชําระด้วยไฟ และเครื่องบูชาทุกอย่างจะต้องถูกชําระด้วยเกลือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 50, 'เกลือเป็นของดี แต่ถ้าเกลือหมดรสเค็มแล้ว จะทําให้กลับเค็มอีกอย่างไรได้ ท่านทั้งหลายจงมีเกลือในตัว และจงอยู่สงบสุขซึ่งกันและกัน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 1, 'ฝ่ายพระองค์ได้ทรงลุกขึ้นเสด็จจากที่นั่น เข้าในเขตแดนแคว้นยูเดีย ไปตามทางแม่น้ําจอร์แดนฟากข้างโน้น และประชาชนพากันมาหาพระองค์อีก พระองค์จึงตรัสสั่งสอนเขาอีกตามที่พระองค์ทรงเคยสอนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 2, 'พวกฟาริสีมาทดลองพระองค์ทูลถามพระองค์ว่า “ผู้ชายจะหย่าภรรยาของตนเป็นการถูกต้องตามพระราชบัญญัติหรือไม่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 3, 'พระองค์ตรัสถามเขาว่า “โมเสสได้บัญญัติไว้ว่าอย่างไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 4, 'เขาทูลตอบว่า “โมเสสอนุญาตให้ทําหนังสือหย่าภรรยาแล้วก็หย่าให้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 5, 'พระเยซูจึงตรัสตอบเขาว่า “โมเสสได้เขียนข้อบังคับนั้นเพราะเหตุใจพวกเจ้าแข็งกระด้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 6, 'แต่ตั้งแต่เดิมสร้างโลก ‘พระเจ้าได้ทรงสร้างพวกเขาให้เป็นชายและหญิง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 7, 'เพราะเหตุนี้ผู้ชายจะจากบิดามารดาของเขา และไปผูกพันอยู่กับภรรยา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 8, 'และเขาทั้งสองจะเป็นเนื้ออันเดียวกัน’ เขาจึงไม่เป็นสองต่อไป แต่เป็นเนื้ออันเดียวกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 9, 'เหตุฉะนั้น ซึ่งพระเจ้าได้ทรงผูกพันกันแล้ว อย่าให้มนุษย์ทําให้พรากจากกันเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 10, 'เมื่อเข้าไปในเรือนแล้วเหล่าสาวกของพระองค์ทูลถามพระองค์อีกถึงเรื่องนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 11, 'พระองค์จึงตรัสกับเขาว่า “ถ้าผู้ใดหย่าภรรยาของตน แล้วไปมีภรรยาใหม่ ผู้นั้นก็ได้ผิดประเวณีต่อเธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 12, 'และถ้าหญิงจะหย่าสามีของตน แล้วไปมีสามีใหม่ หญิงนั้นก็ผิดประเวณี”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 13, 'ขณะนั้นเขาพาเด็กเล็กๆมาหาพระองค์ เพื่อจะให้พระองค์ทรงถูกต้องตัวเด็กนั้น แต่เหล่าสาวกก็ห้ามปรามคนที่พาเด็กมานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 14, 'เมื่อพระเยซูทอดพระเนตรเห็นดังนั้นก็ไม่พอพระทัย จึงตรัสแก่เหล่าสาวกว่า “จงยอมให้เด็กเล็กๆเข้ามาหาเรา อย่าห้ามเขาเลย เพราะว่าอาณาจักรของพระเจ้าย่อมเป็นของคนเช่นเด็กเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 15, 'เราบอกความจริงแก่ท่านทั้งหลายว่า ผู้หนึ่งผู้ใดมิได้รับอาณาจักรของพระเจ้าเหมือนเด็กเล็กๆ ผู้นั้นจะเข้าในอาณาจักรนั้นไม่ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 16, 'แล้วพระองค์ทรงอุ้มเด็กเล็กๆเหล่านั้น วางพระหัตถ์บนเขา แล้วทรงอวยพรให้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 17, 'เมื่อพระองค์กําลังเสด็จออกไปตามทาง มีคนหนึ่งวิ่งมาหาพระองค์คุกเข่าลงทูลถามพระองค์ว่า “ท่านอาจารย์ผู้ประเสริฐ ข้าพเจ้าจะกระทําประการใดจึงจะได้ชีวิตนิรันดร์เป็นมรดก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 18, 'พระเยซูตรัสถามคนนั้นว่า “ท่านเรียกเราว่าประเสริฐทําไม ไม่มีใครประเสริฐเว้นแต่พระเจ้าองค์เดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 19, 'ท่านรู้จักพระบัญญัติแล้วซึ่งว่า ‘อย่าล่วงประเวณีผัวเมียเขา อย่าฆ่าคน อย่าลักทรัพย์ อย่าเป็นพยานเท็จ อย่าฉ้อเขา จงให้เกียรติแก่บิดามารดาของตน’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 20, 'คนนั้นจึงทูลตอบพระองค์ว่า “อาจารย์เจ้าข้า ข้อเหล่านี้ข้าพเจ้าได้ถือรักษาไว้ตั้งแต่เป็นเด็กมา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 21, 'พระเยซูทรงเพ่งดูคนนั้น ก็ทรงรักเขา แล้วตรัสแก่เขาว่า “ท่านยังขาดอยู่สิ่งหนึ่ง จงไปขายบรรดาสิ่งของซึ่งท่านมีอยู่ แจกจ่ายให้คนอนาถา แล้วท่านจะมีทรัพย์สมบัติในสวรรค์ แล้วจงแบกกางเขน และตามเรามา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 22, 'เมื่อเขาได้ยินคํานั้นก็เสียใจ แล้วออกไปเป็นทุกข์เพราะเขามีทรัพย์สิ่งของเป็นอันมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 23, 'พระเยซูจึงทอดพระเนตรรอบๆแล้วตรัสแก่เหล่าสาวกของพระองค์ว่า “คนมั่งมีจะเข้าในอาณาจักรของพระเจ้าก็ยากนักหนา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 24, 'เหล่าสาวกก็ประหลาดใจด้วยคําตรัสของพระองค์ และพระเยซูตรัสแก่เขาอีกว่า “ลูกเอ๋ย คนที่วางใจในทรัพย์สมบัติจะเข้าในอาณาจักรของพระเจ้าก็ยากนักหนา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 25, 'ตัวอูฐจะลอดรูเข็มก็ง่ายกว่าคนมั่งมีจะเข้าในอาณาจักรของพระเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 26, 'เหล่าสาวกก็ประหลาดใจยิ่งนักจึงพูดกันว่า “ถ้าอย่างนั้นใครจะรอดได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 27, 'พระเยซูทอดพระเนตรเหล่าสาวกแล้วตรัสว่า “ฝ่ายมนุษย์ย่อมเป็นไปไม่ได้ แต่ไม่เป็นแบบนั้นกับพระเจ้า เพราะว่าพระเจ้าทรงกระทําให้เป็นไปได้ทุกสิ่ง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 28, 'ฝ่ายเปโตรจึงเริ่มทูลพระองค์ว่า “ดูเถิด ข้าพระองค์ทั้งหลายได้สละสิ่งสารพัด และได้ติดตามพระองค์มา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 29, 'พระเยซูตรัสตอบว่า “เราบอกความจริงแก่ท่านว่า ถ้าผู้ใดได้สละบ้าน หรือพี่น้องชายหญิง หรือบิดามารดา หรือภรรยา หรือบุตร หรือที่ดิน เพราะเห็นแก่เราและข่าวประเสริฐนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 30, 'ในเวลานี้ผู้นั้นจะได้รับตอบแทนร้อยเท่า คือบ้าน พี่น้องชายหญิง มารดา บุตรและที่ดิน ทั้งจะถูกการข่มเหงด้วย และในโลกหน้าจะได้ชีวิตนิรันดร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 31, 'แต่มีหลายคนที่เป็นคนต้นจะต้องกลับไปเป็นคนสุดท้าย และที่เป็นคนสุดท้ายจะกลับเป็นคนต้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 32, 'เมื่อกําลังเดินทางจะขึ้นไปยังกรุงเยรูซาเล็ม พระเยซูก็เสด็จนําหน้าเขา ฝ่ายเหล่าสาวกก็พากันคิดประหลาดใจ และขณะที่เขาตามมาก็หวาดกลัว พระองค์จึงทรงเรียกสาวกสิบสองคนอีก แล้วเริ่มตรัสสําแดงให้เขาทราบถึงเหตุการณ์ซึ่งจะเกิดแก่พระองค์นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 33, 'ว่า “ดูเถิด เราทั้งหลายจะขึ้นไปยังกรุงเยรูซาเล็ม และเขาจะมอบบุตรมนุษย์ไว้กับพวกปุโรหิตใหญ่และพวกธรรมาจารย์ และเขาเหล่านั้นจะปรับโทษท่านถึงตาย และจะมอบท่านไว้กับคนต่างชาติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 34, 'คนต่างชาตินั้นจะเยาะเย้ยท่าน จะเฆี่ยนตีท่าน จะถ่มน้ําลายรดท่าน และจะฆ่าท่านเสีย และวันที่สามท่านจะเป็นขึ้นมาใหม่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 35, 'ฝ่ายยากอบกับยอห์น บุตรชายของเศเบดี เข้ามาทูลพระองค์ว่า “พระอาจารย์เจ้าข้า ข้าพระองค์ทั้งสองปรารถนาจะขอให้พระองค์ทรงกระทําตามคําขอของข้าพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 36, 'พระองค์จึงตรัสถามเขาว่า “ท่านทั้งสองปรารถนาจะให้เราทําสิ่งใดให้ท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 37, 'เขาจึงทูลตอบพระองค์ว่า “เมื่อพระองค์จะทรงสง่าราศีนั้น ขอให้ข้าพระองค์นั่งที่เบื้องขวาพระหัตถ์คนหนึ่ง เบื้องซ้ายพระหัตถ์คนหนึ่ง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 38, 'พระเยซูจึงตรัสแก่เขาว่า “ที่ท่านขอนั้นท่านไม่เข้าใจ ถ้วยซึ่งเราจะดื่มนั้นท่านจะดื่มได้หรือ และบัพติศมานั้นซึ่งเราจะรับ ท่านจะรับได้หรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 39, 'เขาทั้งสองทูลตอบพระองค์ว่า “ได้ พระเจ้าข้า” พระเยซูจึงตรัสแก่เขาว่า “ถ้วยซึ่งเราดื่มท่านจะดื่มก็จริง และรับบัพติศมาด้วยบัพติศมาที่เราจะรับก็จริง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 40, 'แต่ที่จะนั่งข้างขวาและข้างซ้ายของเรานั้น ไม่ใช่พนักงานของเราที่จะจัดให้ แต่ได้ทรงเตรียมไว้สําหรับผู้ใดก็จะให้แก่ผู้นั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 41, 'เมื่อสาวกสิบคนได้ยินแล้ว ก็เริ่มมีความขุ่นเคืองยากอบและยอห์น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 42, 'พระเยซูจึงทรงเรียกเขาทั้งหลายมาตรัสแก่เขาว่า “ท่านทั้งหลายรู้อยู่ว่า ผู้ที่นับว่าเป็นผู้ครอบครองของคนต่างชาติย่อมเป็นเจ้าเหนือเขา และผู้ใหญ่ทั้งหลายก็ใช้อํานาจบังคับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 43, 'แต่ในพวกท่านหาเป็นอย่างนั้นไม่ ถ้าผู้ใดใคร่จะได้เป็นใหญ่ในพวกท่าน ผู้นั้นจะต้องเป็นผู้ปรนนิบัติท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 44, 'และถ้าผู้ใดใคร่จะได้เป็นเอกเป็นต้น ผู้นั้นจะต้องเป็นผู้รับใช้ของคนทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 45, 'เพราะว่าบุตรมนุษย์มิได้มาเพื่อรับการปรนนิบัติ แต่มาเพื่อจะปรนนิบัติ และประทานชีวิตของท่านให้เป็นค่าไถ่สําหรับคนเป็นอันมาก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 46, 'ฝ่ายพระเยซูกับพวกสาวกมายังเมืองเยรีโค และเมื่อพระองค์เสด็จออกจากเมืองเยรีโคกับพวกสาวกของพระองค์และประชาชนเป็นอันมาก มีคนตาบอดคนหนึ่ง ชื่อบารทิเมอัส ซึ่งเป็นบุตรชายของทิเมอัส นั่งขอทานอยู่ที่ริมหนทาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 47, 'เมื่อคนนั้นได้ยินว่าพระเยซูชาวนาซาเร็ธเสด็จมา จึงเริ่มร้องเสียงดังว่า “ท่านเยซู บุตรดาวิดเจ้าข้า ขอทรงเมตตาข้าพระองค์เถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 48, 'มีหลายคนห้ามเขาให้เขานิ่งเสีย แต่เขายิ่งร้องเสียงดังขึ้นว่า “บุตรดาวิดเจ้าข้า ขอทรงเมตตาข้าพระองค์เถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 49, 'พระเยซูทรงหยุดประทับยืนอยู่ แล้วตรัสสั่งให้เรียกคนนั้นมา เขาจึงเรียกคนตาบอดนั้นว่าแก่เขาว่า “จงชื่นใจและลุกขึ้นเถิด พระองค์ทรงเรียกเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 50, 'คนนั้นก็ทิ้งผ้าห่มเสียลุกขึ้นมาหาพระเยซู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 51, 'พระเยซูจึงตรัสถามเขาว่า “เจ้าปรารถนาจะให้เราทําอะไรแก่เจ้า” คนตาบอดนั้นทูลพระองค์ว่า “พระอาจารย์เจ้าข้า ขอโปรดให้ตาข้าพระองค์เห็นได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 52, 'พระเยซูตรัสแก่เขาว่า “จงไปเถิด ความเชื่อของเจ้าได้กระทําให้เจ้าหายปกติแล้ว” ในทันใดนั้นคนตาบอดนั้นก็เห็นได้ และได้เดินทางตามพระเยซูไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 1, 'ครั้นพระองค์กับพวกสาวกมาใกล้กรุงเยรูซาเล็ม ถึงหมู่บ้านเบธฟายี และหมู่บ้านเบธานีเชิงภูเขามะกอกเทศ พระองค์ทรงใช้สาวกสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 2, 'สั่งเขาว่า “จงเข้าไปในหมู่บ้านที่อยู่ตรงหน้าท่าน ครั้นเข้าไปแล้วในทันใดนั้นจะพบลูกลาตัวหนึ่งผูกอยู่ ที่ยังไม่มีใครขึ้นขี่เลย จงแก้มันจูงมาเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 3, 'ถ้าผู้ใดถามท่านว่า ‘ท่านทําอย่างนี้ทําไม’ จงบอกว่า องค์พระผู้เป็นเจ้าต้องประสงค์ลูกลานี้ และประเดี๋ยวพระองค์จะส่งกลับคืนมาให้ที่นี่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 4, 'สาวกสองคนนั้นจึงไป แล้วพบลูกลาตัวนั้นผูกอยู่นอกประตูที่สี่แยก เขาจึงแก้มัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 5, 'บางคนซึ่งยืนอยู่ที่นั่นถามเขาว่า “แก้ลูกลานั้นทําไม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 6, 'สาวกก็ตอบตามพระดํารัสสั่งของพระเยซู แล้วเขาก็ยอมให้เอาไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 7, 'สาวกจึงจูงลูกลามาถึงพระเยซู แล้วเอาเสื้อผ้าของตนปูลงบนหลังลา แล้วพระองค์จึงทรงลานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 8, 'มีคนเป็นอันมากเอาเสื้อผ้าของตนปูลงตามถนนหนทาง และคนอื่นก็ตัดกิ่งไม้จากต้นไม้มาปูลงตามทางนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 9, 'ฝ่ายคนที่เดินไปข้างหน้า กับผู้ที่ตามมาข้างหลัง ก็โห่ร้องว่า “โฮซันนา ขอให้พระองค์ผู้เสด็จมาในพระนามขององค์พระผู้เป็นเจ้า ทรงพระเจริญ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 10, 'ความสุขสวัสดิ์มงคลจงมีแก่อาณาจักรของดาวิด บรรพบุรุษของเรา ที่มาตั้งอยู่ในพระนามขององค์พระผู้เป็นเจ้า โฮซันนาในที่สูงสุด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 11, 'พระเยซูก็เสด็จเข้ากรุงเยรูซาเล็มและเข้าไปในพระวิหาร เมื่อทอดพระเนตรสิ่งทั้งปวงแล้วเวลาก็จวนค่ํา จึงเสด็จออกไปยังหมู่บ้านเบธานีกับเหล่าสาวกสิบสองคนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 12, 'ครั้นรุ่งขึ้นเมื่อพระองค์กับสาวกออกมาจากหมู่บ้านเบธานีแล้ว พระองค์ก็ทรงหิว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 13, 'พอทอดพระเนตรเห็นต้นมะเดื่อต้นหนึ่งแต่ไกลมีใบ จึงเสด็จเข้าไปดูว่ามีผลหรือไม่ ครั้นมาถึงต้นนั้นแล้ว ไม่เห็นมีผลมีแต่ใบเท่านั้น เพราะยังไม่ถึงฤดูผลมะเดื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 14, 'พระเยซูจึงตรัสแก่ต้นนั้นว่า “ตั้งแต่นี้ไปจะไม่มีใครได้กินผลจากเจ้าเลย” เหล่าสาวกของพระองค์ก็ได้ยินคําซึ่งพระองค์ตรัสนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 15, 'เมื่อพระองค์กับสาวกมาถึงกรุงเยรูซาเล็ม พระเยซูก็เสด็จเข้าไปในพระวิหาร แล้วเริ่มขับไล่บรรดาผู้ซื้อขายในพระวิหารนั้น และคว่ําโต๊ะผู้รับแลกเงิน กับทั้งคว่ําม้านั่งผู้ขายนกเขาเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 16, 'และทรงห้ามมิให้ผู้ใดขนสิ่งใดๆเดินลัดพระวิหาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 17, 'พระองค์ตรัสสอนเขาว่า “มีพระวจนะเขียนไว้มิใช่หรือว่า ‘นิเวศของเราประชาชาติทั้งหลายจะเรียกว่า เป็นนิเวศอธิษฐาน’ แต่เจ้าทั้งหลายได้กระทําให้เป็น ‘ถ้ําของพวกโจร’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 18, 'เมื่อพวกธรรมาจารย์และพวกปุโรหิตใหญ่ได้ยินอย่างนั้น จึงหาช่องที่จะประหารพระองค์เสีย เพราะเขากลัวพระองค์ ด้วยว่าประชาชนประหลาดใจด้วยคําสั่งสอนของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 19, 'และเมื่อถึงเวลาเย็น พระองค์ได้เสด็จออกไปจากกรุง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 20, 'ครั้นเวลาเช้า เมื่อพระองค์กับเหล่าสาวกได้ผ่านที่นั้นไป ก็ได้เห็นมะเดื่อต้นนั้นเหี่ยวแห้งไปจนถึงราก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 21, 'ฝ่ายเปโตรระลึกขึ้นได้จึงทูลพระองค์ว่า “พระอาจารย์เจ้าข้า ดูเถิด ต้นมะเดื่อที่พระองค์ได้สาปไว้นั้นก็เหี่ยวแห้งไปแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 22, 'พระเยซูจึงตรัสตอบเหล่าสาวกว่า “จงเชื่อในพระเจ้าเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 23, 'เราบอกความจริงแก่ท่านว่า ผู้ใดก็ตามจะสั่งภูเขานี้ว่า ‘จงลอยไปลงทะเล’ และมิได้สงสัยในใจ แต่เชื่อว่าจะเป็นไปตามที่สั่งนั้น ก็จะเป็นไปตามคําสั่งนั้นจริง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 24, 'เหตุฉะนั้นเราบอกท่านทั้งหลายว่า ขณะเมื่อท่านจะอธิษฐานขอสิ่งใด จงเชื่อว่าได้รับ และท่านจะได้รับสิ่งนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 25, 'เมื่อท่านยืนอธิษฐานอยู่ ถ้าท่านมีเหตุกับผู้หนึ่งผู้ใด จงยกโทษให้ผู้นั้นเสีย เพื่อพระบิดาของท่าน ผู้ทรงสถิตในสวรรค์ จะโปรดยกการละเมิดของท่านด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 26, 'แต่ถ้าท่านทั้งหลายไม่ยกโทษให้ พระบิดาของท่าน ผู้ทรงสถิตในสวรรค์ จะไม่ทรงโปรดยกการละเมิดของท่านเหมือนกัน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 27, 'ฝ่ายพระองค์กับเหล่าสาวกมายังกรุงเยรูซาเล็มอีก เมื่อพระองค์เสด็จดําเนินอยู่ในพระวิหาร พวกปุโรหิตใหญ่ พวกธรรมาจารย์ และพวกผู้ใหญ่มาหาพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 28, 'ทูลพระองค์ว่า “ท่านมีสิทธิอันใดจึงได้ทําสิ่งเหล่านี้ ใครให้สิทธิแก่ท่านที่จะทําการนี้ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 29, 'พระเยซูจึงตรัสตอบเขาว่า “เราจะถามท่านทั้งหลายสักข้อหนึ่งเหมือนกัน จงตอบเรา แล้วเราจะบอกท่านว่า เรากระทําการนี้โดยสิทธิอันใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 30, 'คือบัพติศมาของยอห์นนั้น มาจากสวรรค์หรือมาจากมนุษย์ จงตอบเราเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 31, 'เขาจึงปรึกษากันว่า “ถ้าเราจะว่า ‘มาจากสวรรค์’ ท่านจะถามเราว่า ‘เหตุไฉนจึงไม่เชื่อยอห์นเล่า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 32, 'แต่ถ้าเราจะว่า ‘มาจากมนุษย์’” เขากลัวประชาชน เพราะประชาชนถือว่ายอห์นเป็นศาสดาพยากรณ์จริงๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 33, 'เขาจึงทูลตอบพระเยซูว่า “พวกข้าพเจ้าไม่ทราบ” พระเยซูจึงตรัสกับเขาว่า “เราจะไม่บอกท่านทั้งหลายเหมือนกันว่า เรากระทําการนี้โดยสิทธิอันใด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 1, 'พระองค์จึงเริ่มตรัสแก่เขาเป็นคําอุปมาว่า “ยังมีชายคนหนึ่งได้ทําสวนองุ่น แล้วล้อมรั้วต้นไม้ไว้รอบ เขาได้สกัดบ่อเก็บน้ําองุ่น และสร้างหอเฝ้า ให้พวกชาวสวนเช่าแล้วก็ไปเมืองไกล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 2, 'ครั้นถึงฤดูผลองุ่นเขาจึงใช้ผู้รับใช้คนหนึ่งไปหาคนเช่าสวนนั้น เพื่อเขาจะได้รับส่วนผลของสวนองุ่นจากคนเช่าสวน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 3, 'ฝ่ายคนเหล่านั้นก็จับผู้รับใช้นั้นเฆี่ยนตี แล้วไล่ให้กลับไปมือเปล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 4, 'อีกครั้งหนึ่งเจ้าของสวนใช้ผู้รับใช้อีกคนหนึ่งไปหาคนเช่าสวน คนเช่าสวนนั้นก็เอาหินขว้างผู้รับใช้นั้นศีรษะแตก และไล่ให้กลับไปอย่างน่าอัปยศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 5, 'อีกครั้งหนึ่งเจ้าของใช้ผู้รับใช้ไปอีกคนหนึ่ง เขาก็ฆ่าผู้รับใช้นั้นเสีย แล้วยังใช้ผู้รับใช้ไปอีกหลายคน เขาก็เฆี่ยนตีบ้าง ฆ่าเสียบ้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 6, 'เจ้าของสวนยังมีบุตรชายที่รักคนหนึ่ง จึงใช้บุตรคนนั้นไปเป็นครั้งสุดท้าย พูดว่า ‘พวกเขาคงจะเคารพบุตรชายของเรา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 7, 'แต่คนเช่าสวนพูดกันว่า ‘คนนี้แหละเป็นผู้รับมรดก มาเถิด ให้เราฆ่าเขาเสีย แล้วมรดกนั้นจะตกอยู่กับเรา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 8, 'เขาจึงพากันจับบุตรนั้นฆ่าเสีย และเอาศพทิ้งไว้นอกสวนองุ่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 9, 'เหตุฉะนั้น เจ้าของสวนองุ่นจะทําประการใด ท่านก็จะมาฆ่าคนเช่าสวนเหล่านั้นเสีย แล้วจะเอาสวนองุ่นนั้นให้ผู้อื่นเช่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 10, 'ท่านทั้งหลายอ่านพระคัมภีร์ตอนนี้แล้วมิใช่หรือซึ่งว่า ‘ศิลาซึ่งช่างก่อได้ปฏิเสธเสีย ได้กลับกลายเป็นศิลามุมเอกแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 11, 'การนี้เป็นมาจากองค์พระผู้เป็นเจ้า เป็นการมหัศจรรย์ประจักษ์แก่ตาเรา’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 12, 'ฝ่ายเขาจึงอยากจะจับพระองค์ แต่ว่าเขากลัวประชาชน ด้วยเขารู้อยู่ว่า พระองค์ได้ตรัสคําอุปมานี้กระทบพวกเขาเอง แล้วเขาก็ไปจากพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 13, 'เขาจึงใช้บางคนในพวกฟาริสีและพวกเฮโรดไปหาพระองค์ เพื่อจะคอยจับผิดในพระดํารัสของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 14, 'ครั้นมาถึงแล้วก็ทูลพระองค์ว่า “อาจารย์เจ้าข้า ข้าพเจ้าทั้งหลายทราบอยู่ว่า ท่านเป็นคนซื่อสัตย์และมิได้เอาใจผู้ใด เพราะท่านมิได้เห็นแก่หน้าผู้ใด แต่สั่งสอนทางของพระเจ้าจริงๆ การที่จะส่งส่วยให้แก่ซีซาร์นั้นถูกต้องตามพระราชบัญญัติหรือไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 15, 'เราจะส่งดีหรือไม่ส่งดี” แต่พระองค์ทรงทราบอุบายของเขาจึงตรัสแก่เขาว่า “ท่านทั้งหลายมาทดลองเราทําไม จงเอาเงินตราเหรียญหนึ่งมาให้เราดู”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 16, 'เขาก็เอามาให้ พระองค์จึงตรัสถามเขาว่า “รูปและคําจารึกนี้เป็นของใคร” เขาทูลตอบพระองค์ว่า “ของซีซาร์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 17, 'พระเยซูจึงตรัสแก่เขาว่า “ของของซีซาร์ จงถวายแก่ซีซาร์ และของของพระเจ้า จงถวายแด่พระเจ้า” ฝ่ายเขาก็ประหลาดใจในพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 18, 'มีพวกสะดูสีมาหาพระองค์ พวกนี้เป็นผู้ที่กล่าวว่าการฟื้นขึ้นมาจากความตายนั้นไม่มี เขาทูลถามพระองค์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 19, '“อาจารย์เจ้าข้า โมเสสได้เขียนสั่งข้าพเจ้าทั้งหลายไว้ว่า ‘ถ้าชายผู้ใดตายและภรรยายังอยู่ แต่ไม่มีบุตร ก็ให้น้องชายรับพี่สะใภ้นั้นไว้เป็นภรรยาของตน เพื่อสืบเชื้อสายของพี่ชายไว้’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 20, 'ยังมีพี่น้องผู้ชายเจ็ดคน พี่หัวปีมีภรรยาแล้วตาย ไม่มีเชื้อสาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 21, 'น้องที่หนึ่งจึงรับหญิงนั้นมาเป็นภรรยา แล้วก็ตาย ยังไม่มีเชื้อสาย และน้องที่สองที่สามก็ทําเช่นกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 22, 'พี่น้องทั้งเจ็ดคนนี้ก็ได้รับผู้หญิงนั้นไว้เป็นภรรยาและไม่มีเชื้อสาย ที่สุดผู้หญิงนั้นก็ตายด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 23, 'เหตุฉะนั้น ในวันที่จะฟื้นขึ้นมาจากความตาย เมื่อเขาทั้งเจ็ดเป็นขึ้นมาแล้ว หญิงนั้นจะเป็นภรรยาของใครด้วยนางได้เป็นภรรยาของชายทั้งเจ็ดแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 24, 'พระเยซูจึงตรัสตอบเขาว่า “พวกท่านคิดผิดเสียแล้ว เพราะท่านทั้งหลายไม่รู้พระคัมภีร์หรือฤทธิ์เดชของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 25, 'ด้วยว่าเมื่อมนุษย์จะฟื้นขึ้นมาจากความตายนั้น เขาจะไม่มีการสมรส หรือยกให้เป็นสามีภรรยากันอีก แต่จะเป็นเหมือนทูตสวรรค์ในฟ้าสวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 26, 'และเรื่องคนซึ่งตายแล้วที่เขาจะถูกชุบให้เป็นขึ้นอีกนั้น ท่านทั้งหลายยังไม่ได้อ่านคัมภีร์ของโมเสสตอนเรื่องพุ่มไม้หรือ ซึ่งพระเจ้าได้ตรัสไว้กับโมเสสว่า ‘เราเป็นพระเจ้าของอับราฮัม เป็นพระเจ้าของอิสอัค และเป็นพระเจ้าของยาโคบ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 27, 'พระองค์มิได้เป็นพระเจ้าของคนตาย แต่ทรงเป็นพระเจ้าของคนเป็น ท่านทั้งหลายจึงผิดมากทีเดียว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 28, 'มีธรรมาจารย์คนหนึ่ง เมื่อมาถึงได้ยินเขาไล่เลียงกันและเห็นว่าพระองค์ทรงตอบเขาได้ดี จึงทูลถามพระองค์ว่า “พระบัญญัติข้อใดเป็นเอกเป็นใหญ่กว่าบัญญัติทั้งปวง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 29, 'พระเยซูจึงตรัสตอบคนนั้นว่า “พระบัญญัติซึ่งเป็นเอกเป็นใหญ่กว่าบัญญัติทั้งปวงนั้นคือว่า ‘โอ คนอิสราเอล จงฟังเถิด องค์พระผู้เป็นเจ้าพระเจ้าของเราทั้งหลายเป็นองค์พระผู้เป็นเจ้าองค์เดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 30, 'และพวกท่านจงรักองค์พระผู้เป็นเจ้าผู้เป็นพระเจ้าของท่าน ด้วยสุดจิตสุดใจของท่าน ด้วยสิ้นสุดความคิด และด้วยสิ้นสุดกําลังของท่าน’ นี่เป็นพระบัญญัติที่เป็นเอกเป็นใหญ่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 31, 'และพระบัญญัติที่สองนั้นก็เป็นเช่นกันคือ ‘จงรักเพื่อนบ้านเหมือนรักตนเอง’ พระบัญญัติอื่นที่ใหญ่กว่าพระบัญญัติทั้งสองนี้ไม่มี”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 32, 'ฝ่ายธรรมาจารย์คนนั้นทูลพระองค์ว่า “ดีแล้วอาจารย์เจ้าข้า ท่านกล่าวถูกจริงว่าพระเจ้ามีแต่พระองค์เดียว และนอกจากพระองค์แล้วพระเจ้าอื่นไม่มีเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 33, 'และซึ่งจะรักพระองค์ด้วยสุดใจ สุดความเข้าใจ สุดจิตและสิ้นสุดกําลัง และรักเพื่อนบ้านเหมือนรักตนเอง ก็ประเสริฐกว่าเครื่องเผาบูชาและเครื่องสัตวบูชาทั้งสิ้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 34, 'เมื่อพระเยซูทรงเห็นแล้วว่าคนนั้นพูดโดยใช้ความคิด จึงตรัสแก่เขาว่า “ท่านไม่ไกลจากอาณาจักรของพระเจ้า” ตั้งแต่นั้นไปไม่มีใครกล้าถามพระองค์ต่อไปอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 35, 'เมื่อพระเยซูทรงสั่งสอนอยู่ในพระวิหารได้ตรัสถามว่า “ที่พวกธรรมาจารย์ว่าพระคริสต์เป็นบุตรของดาวิดนั้นเป็นได้อย่างไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 36, 'ด้วยว่าดาวิดเองทรงกล่าวโดยเดชพระวิญญาณบริสุทธิ์ว่า ‘องค์พระผู้เป็นเจ้าตรัสกับองค์พระผู้เป็นเจ้าของข้าพเจ้าว่า จงนั่งที่ขวามือของเรา จนกว่าเราจะกระทําให้ศัตรูของท่านเป็นแท่นรองเท้าของท่าน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 37, 'ดาวิดเองยังได้เรียกท่านว่า เป็นองค์พระผู้เป็นเจ้า ท่านจะเป็นบุตรของดาวิดอย่างไรได้” ฝ่ายประชาชนทั่วไปฟังพระองค์ด้วยความยินดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 38, 'พระเยซูตรัสสอนเขาในคําสอนของพระองค์ว่า “จงระวังพวกธรรมาจารย์ให้ดี ผู้ที่ชอบสวมเสื้อยาวเดินไปมา และชอบให้คนคํานับกลางตลาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 39, 'ชอบนั่งที่สูงในธรรมศาลาและที่อันมีเกียรติในการเลี้ยง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 40, 'เขาริบเอาเรือนของหญิงม่าย และแสร้งอธิษฐานเสียยืดยาว คนเหล่านี้จะได้รับพระอาชญามากยิ่งขึ้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 41, 'พระเยซูได้เสด็จประทับตรงหน้าตู้เก็บเงินถวาย ทรงทอดพระเนตรสังเกตประชาชนเอาเงินมาใส่ไว้ในตู้นั้น และคนมั่งมีหลายคนเอาเงินมากมาใส่ในที่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 42, 'มีหญิงม่ายคนหนึ่งเป็นคนยากจนเอาเหรียญทองแดงสองอัน มีค่าประมาณสลึงหนึ่งมาใส่ไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 43, 'พระองค์จึงทรงเรียกเหล่าสาวกของพระองค์มาตรัสแก่เขาว่า “เราบอกความจริงแก่ท่านทั้งหลายว่า หญิงม่ายยากจนคนนี้ได้ใส่ไว้ในตู้เก็บเงินถวายมากกว่าคนทั้งปวงที่ใส่ไว้นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 44, 'เพราะว่าคนทั้งปวงนั้นได้เอาเงินเหลือใช้ของเขามาใส่ไว้ แต่ผู้หญิงนี้ขัดสนที่สุด ยังได้เอาเงินที่มีอยู่สําหรับเลี้ยงชีวิตของตนมาใส่จนหมด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 1, 'เมื่อพระองค์เสด็จออกจากพระวิหาร มีสาวกของพระองค์คนหนึ่งทูลพระองค์ว่า “พระอาจารย์เจ้าข้า ดูเถิด ศิลาและตึกเหล่านี้ใหญ่จริง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 2, 'พระองค์จึงตรัสแก่สาวกนั้นว่า “ท่านเห็นตึกใหญ่เหล่านี้หรือ ศิลาที่ซ้อนทับกันอยู่ที่นี่ซึ่งจะไม่ถูกทําลายลงก็หามิได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 3, 'เมื่อพระองค์ประทับบนภูเขามะกอกเทศตรงหน้าพระวิหาร เปโตร ยากอบ ยอห์นและอันดรูว์มากราบทูลถามพระองค์ส่วนตัวว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 4, '“ขอทรงโปรดให้ข้าพระองค์ทั้งหลายทราบว่า เหตุการณ์เหล่านี้จะบังเกิดขึ้นเมื่อไร สิ่งไรจะเป็นหมายสําคัญว่าการณ์ทั้งปวงนี้จวนจะสําเร็จ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 5, 'พระเยซูจึงตั้งต้นตรัสตอบเขาว่า “ระวังให้ดี อย่าให้ผู้ใดล่อลวงท่านให้หลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 6, 'ด้วยว่าจะมีหลายคนมาต่างอ้างนามของเราว่า ‘เราเป็นพระคริสต์’ และจะล่อลวงคนเป็นอันมากให้หลงไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 7, 'เมื่อท่านทั้งหลายจะได้ยินถึงการสงครามและข่าวลือเรื่องสงคราม อย่าตื่นตระหนกเลย ด้วยว่าบรรดาสิ่งเหล่านี้จําต้องบังเกิดขึ้น แต่ที่สุดปลายยังไม่มาถึง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 8, 'เพราะประชาชาติจะลุกขึ้นต่อสู้ประชาชาติ ราชอาณาจักรต่อสู้ราชอาณาจักร ทั้งจะเกิดแผ่นดินไหวในที่ต่างๆ และจะเกิดกันดารอาหารและความทุกข์ยาก เหตุการณ์ทั้งปวงนี้เป็นขั้นแรกแห่งความทุกข์ลําบาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 9, 'แต่จงระวังตัวให้ดี เพราะคนเขาจะมอบท่านทั้งหลายไว้กับศาล และจะเฆี่ยนท่านในธรรมศาลา และท่านจะต้องยืนต่อหน้าเจ้าเมืองและกษัตริย์เพราะเห็นแก่เรา เพื่อจะได้เป็นพยานแก่เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 10, 'ข่าวประเสริฐจะต้องประกาศทั่วประชาชาติทั้งปวงก่อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 11, 'แต่ว่าเมื่อเขาจะนําท่านมามอบไว้นั้น อย่าเป็นกังวลก่อนว่าจะพูดอะไรดี และอย่าไตร่ตรองล่วงหน้าเลย แต่จงพูดตามซึ่งได้ทรงโปรดให้ท่านพูดในเวลานั้น เพราะว่าผู้ที่พูดนั้นมิใช่ตัวท่านเอง แต่เป็นพระวิญญาณบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 12, 'แม้ว่าพี่ก็จะทรยศน้องให้ถึงความตาย พ่อก็จะมอบลูก และลูกก็จะทรยศต่อพ่อแม่ให้ถึงแก่ความตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 13, 'ท่านจะถูกคนทั้งปวงเกลียดชังเพราะเห็นแก่นามของเรา แต่ผู้ที่ทนได้จนถึงที่สุด ผู้นั้นจะรอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 14, 'แต่เมื่อท่านทั้งหลายจะเห็นสิ่งที่น่าสะอิดสะเอียนซึ่งกระทําให้เกิดการรกร้างว่างเปล่า ที่ดาเนียลศาสดาพยากรณ์ได้กล่าวถึงนั้น ตั้งอยู่ในที่ซึ่งไม่สมควรจะตั้ง” (ให้ผู้อ่านเข้าใจเอาเถิด) “เวลานั้นให้ผู้ที่อยู่ในแคว้นยูเดียหนีไปยังภูเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 15, 'ผู้ที่อยู่บนดาดฟ้าหลังคาบ้าน อย่าให้ลงมาเข้าไปเก็บข้าวของใดๆออกจากบ้านของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 16, 'ผู้ที่อยู่ตามทุ่งนา อย่าให้กลับไปเอาเสื้อผ้าของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 17, 'แต่ในวันเหล่านั้น วิบัติจะเกิดขึ้นแก่หญิงที่มีครรภ์ หรือหญิงที่มีลูกอ่อนกินนมอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 18, 'ท่านทั้งหลายจงอธิษฐานขอเพื่อเหตุการณ์เหล่านี้จะไม่เกิดขึ้นในฤดูหนาว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 19, 'ด้วยว่าในคราวนั้นจะเกิดความทุกข์ลําบากอย่างที่ไม่เคยมี ตั้งแต่พระเจ้าทรงสร้างโลกมาจนถึงเวลานี้ และจะไม่มีต่อไปอีกเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 20, 'ถ้าองค์พระผู้เป็นเจ้ามิได้ทรงให้วันเหล่านั้นย่นสั้นเข้า จะไม่มีเนื้อหนังใดๆรอดได้เลย แต่เพราะทรงเห็นแก่ผู้ถูกเลือกสรรซึ่งพระองค์ได้ทรงเลือกไว้ พระองค์จึงทรงให้วันเหล่านั้นย่นสั้นเข้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 21, 'และในเวลานั้น ถ้าผู้ใดจะบอกพวกท่านว่า ‘ดูเถิด พระคริสต์อยู่ที่นี่’ หรือ ‘ดูเถิด อยู่ที่โน่น’ อย่าได้เชื่อเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 22, 'ด้วยว่าจะมีพระคริสต์เทียมเท็จและผู้ทํานายเทียมเท็จเกิดขึ้นหลายคน ทําหมายสําคัญและการมหัศจรรย์เพื่อล่อลวงผู้ที่ถูกเลือกสรรแล้วให้หลง ถ้าเป็นได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 23, 'แต่ท่านทั้งหลายจงระวังให้ดี ดูเถิด เราได้บอกสิ่งสารพัดให้แก่ท่านทั้งหลายไว้ก่อนแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 24, 'ภายหลังเมื่อคราวลําบากนั้นพ้นไปแล้ว ‘ดวงอาทิตย์จะมืดไป และดวงจันทร์จะไม่ส่องแสง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 25, 'ดวงดาวทั้งปวงจะตกจากฟ้า และบรรดาสิ่งที่มีอํานาจในท้องฟ้าจะสะเทือนสะท้านไป’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 26, 'เมื่อนั้นเขาจะเห็น ‘บุตรมนุษย์เสด็จมาบนเมฆ’ ทรงฤทธานุภาพและสง่าราศีเป็นอันมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 27, 'เมื่อนั้นพระองค์จะทรงใช้เหล่าทูตสวรรค์ของพระองค์ ให้รวบรวมคนทั้งปวงที่พระองค์ทรงเลือกสรรไว้แล้วจากลมทั้งสี่ทิศนั้น ตั้งแต่ที่สุดปลายแผ่นดินโลกจนถึงที่สุดขอบฟ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 28, 'บัดนี้ จงเรียนคําอุปมาเรื่องต้นมะเดื่อ เมื่อกิ่งก้านยังอ่อนและแตกใบแล้ว ท่านก็รู้ว่าฤดูร้อนใกล้จะถึงแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 29, 'เช่นนั้นแหละ เมื่อท่านทั้งหลายเห็นสิ่งทั้งปวงนี้เกิดขึ้น ก็ให้รู้ว่าเหตุการณ์นั้นมาใกล้จะถึงประตูแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 30, 'เราบอกความจริงแก่ท่านทั้งหลายว่า คนชั่วอายุนี้จะไม่ล่วงลับไปจนกว่าสิ่งทั้งปวงนี้บังเกิดขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 31, 'ฟ้าและดินจะล่วงไป แต่ถ้อยคําของเราจะสูญหายไปหามิได้เลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 32, 'แต่วันนั้นโมงนั้นไม่มีใครรู้ ถึงบรรดาทูตสวรรค์ในสวรรค์หรือพระบุตรก็ไม่รู้ รู้แต่พระบิดาองค์เดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 33, 'จงเฝ้าระวังและอธิษฐานอยู่ เพราะท่านไม่รู้ว่าเวลาวันนั้นจะมาถึงเมื่อไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 34, 'ด้วยว่าบุตรมนุษย์เปรียบเหมือนเจ้าของบ้านคนหนึ่งที่ออกจากบ้านไปทางไกล มอบสิทธิอํานาจให้แก่พวกผู้รับใช้ของเขา และให้รู้การงานของตนว่ามีหน้าที่อะไรและได้สั่งนายประตูให้เฝ้าบ้านอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 35, 'เหตุฉะนั้น ท่านทั้งหลายจงเฝ้าระวังอยู่ เพราะท่านไม่รู้ว่าเจ้าของบ้านจะมาเมื่อไร จะมาเวลาค่ํา หรือเที่ยงคืน หรือเวลาไก่ขัน หรือรุ่งเช้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 36, 'กลัวว่าจะมาฉับพลันและจะพบท่านนอนหลับอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 37, 'ซึ่งเราบอกพวกท่าน เราก็บอกคนทั้งปวงด้วยว่า จงเฝ้าระวังอยู่เถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 1, 'ยังอีกสองวันจะถึงเทศกาลปัสกาและเทศกาลกินขนมปังไร้เชื้อ พวกปุโรหิตใหญ่และพวกธรรมาจารย์ก็หาช่องที่จะจับพระองค์ด้วยอุบายและจะฆ่าเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 2, 'แต่พวกเขาพูดกันว่า “ในวันเลี้ยง อย่าเพ่อทําเลย กลัวว่าประชาชนจะเกิดวุ่นวาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 3, 'ในเวลาที่พระองค์ประทับอยู่ที่หมู่บ้านเบธานี ในเรือนของซีโมนคนโรคเรื้อน ขณะเมื่อทรงเอนพระกายลงเสวยอยู่ มีหญิงผู้หนึ่งถือผอบน้ํามันหอมนาระดาที่มีราคามากมาเฝ้าพระองค์ และนางทําให้ผอบนั้นแตกแล้วก็เทน้ํามันนั้นลงบนพระเศียรของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 4, 'แต่มีบางคนไม่พอใจพูดกันว่า “เหตุใดจึงทําให้น้ํามันนี้เสียเปล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 5, 'เพราะว่าน้ํามันนี้ ถ้าขายก็คงได้เงินกว่าสามร้อยเหรียญเดนาริอัน แล้วจะแจกให้คนจนก็ได้” เขาจึงบ่นว่าผู้หญิงนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 6, 'ฝ่ายพระเยซูตรัสว่า “อย่าว่าเขาเลย กวนใจเขาทําไม เขาได้กระทําการดีแก่เรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 7, 'ด้วยว่าคนยากจนมีอยู่กับท่านเสมอ และท่านจะทําการดีแก่เขาเมื่อไรก็ทําได้ แต่เราจะไม่อยู่กับท่านเสมอไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 8, 'ซึ่งผู้หญิงนี้ได้กระทําก็เป็นการสุดกําลังของเขา เขามาชโลมกายของเราก่อนเพื่อการศพของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 9, 'เราบอกความจริงแก่ท่านทั้งหลายว่า ที่ไหนๆทั่วโลกซึ่งข่าวประเสริฐนี้จะประกาศไป การซึ่งผู้หญิงนี้ได้กระทําก็จะลือไปเป็นที่ระลึกถึงเขาที่นั่น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 10, 'ฝ่ายยูดาสอิสคาริโอท เป็นคนหนึ่งในพวกสาวกสิบสองคน ได้ไปหาพวกปุโรหิตใหญ่ เพื่อจะทรยศพระองค์ให้เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 11, 'ครั้นเขาได้ยินอย่างนั้นก็ดีใจ และสัญญาว่าจะให้เงินแก่ยูดาส แล้วยูดาสจึงคอยหาช่องที่จะทรยศพระองค์ให้แก่เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 12, 'เมื่อวันต้นเทศกาลกินขนมปังไร้เชื้อ ถึงเวลาเขาเคยฆ่าลูกแกะสําหรับปัสกานั้น พวกสาวกของพระองค์มาทูลถามพระองค์ว่า “พระองค์ทรงปรารถนาจะให้ข้าพระองค์ทั้งหลายไปจัดเตรียมปัสกาให้พระองค์เสวยที่ไหน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 13, 'พระองค์จึงทรงใช้สาวกสองคนไป สั่งเขาว่า “จงเข้าไปในกรุงนั้น แล้วจะมีชายคนหนึ่งทูนหม้อน้ํามาพบท่าน จงตามคนนั้นไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 14, 'เขาจะเข้าไปในที่ใด ท่านจงบอกเจ้าของเรือนนั้นว่า พระอาจารย์ถามว่า ‘ห้องที่เราจะกินปัสกากับเหล่าสาวกของเราได้นั้นอยู่ที่ไหน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 15, 'เจ้าของเรือนจะชี้ให้ท่านเห็นห้องใหญ่ชั้นบนที่ตกแต่งไว้แล้ว ที่นั่นแหละ จงจัดเตรียมไว้สําหรับพวกเราเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 16, 'สาวกสองคนนั้นจึงออกเดินเข้าไปในกรุง และพบเหมือนพระดํารัสที่พระองค์ได้ตรัสแก่เขา แล้วได้จัดเตรียมปัสกาไว้พร้อม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 17, 'ครั้นถึงเวลาค่ําแล้ว พระองค์จึงเสด็จมากับสาวกสิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 18, 'เมื่อกําลังเอนกายลงรับประทานอาหารอยู่ พระเยซูจึงตรัสว่า “เราบอกความจริงแก่ท่านทั้งหลายว่า คนหนึ่งในพวกท่านจะทรยศเรา คือคนหนึ่งที่รับประทานอาหารอยู่กับเรานี่แหละ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 19, 'ฝ่ายพวกสาวกก็เริ่มพากันเป็นทุกข์ และทูลถามพระองค์ทีละคนว่า “คือข้าพระองค์หรือ” และอีกคนหนึ่งถามว่า “คือข้าพระองค์หรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 20, 'พระองค์จึงตรัสตอบเขาว่า “เป็นคนหนึ่งในสาวกสิบสองคนนี้ คือเป็นคนจิ้มในจานเดียวกันกับเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 21, 'เพราะบุตรมนุษย์จะเสด็จไปตามที่ได้มีคําเขียนไว้ถึงพระองค์นั้นจริง แต่วิบัติแก่ผู้ที่ทรยศบุตรมนุษย์ ถ้าคนนั้นมิได้บังเกิดมาก็จะเป็นการดีต่อคนนั้นเอง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 22, 'ระหว่างอาหารมื้อนั้น พระเยซูทรงหยิบขนมปังมา ทรงขอบพระคุณ แล้วหักส่งให้แก่เหล่าสาวกตรัสว่า “จงรับกินเถิด นี่เป็นกายของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 23, 'แล้วพระองค์จึงทรงหยิบถ้วย ขอบพระคุณและส่งให้เขา เขาก็รับไปดื่มทุกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 24, 'แล้วพระองค์ตรัสแก่เขาว่า “นี่เป็นโลหิตของเราอันเป็นโลหิตแห่งพันธสัญญาใหม่ ซึ่งต้องหลั่งออกเพื่อคนเป็นอันมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 25, 'เราบอกความจริงแก่ท่านทั้งหลายว่า เราจะไม่ดื่มน้ําผลแห่งเถาองุ่นนี้ต่อไปอีกจนวันนั้นมาถึง คือวันที่เราจะดื่มใหม่ในอาณาจักรของพระเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 26, 'เมื่อร้องเพลงสรรเสริญแล้ว พระองค์กับเหล่าสาวกก็พากันออกไปยังภูเขามะกอกเทศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 27, 'พระเยซูจึงตรัสกับเหล่าสาวกว่า “ท่านทั้งหลายจะสะดุดใจเพราะเราในคืนนี้เอง ด้วยมีคําเขียนไว้ว่า ‘เราจะตีผู้เลี้ยงแกะ และแกะฝูงนั้นจะกระจัดกระจายไป’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 28, 'แต่เมื่อทรงชุบให้เราฟื้นขึ้นมาแล้ว เราจะไปยังแคว้นกาลิลีก่อนหน้าท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 29, 'เปโตรทูลพระองค์ว่า “แม้คนทั้งปวงจะสะดุดใจ ข้าพระองค์จะไม่สะดุดใจ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 30, 'พระเยซูจึงตรัสกับเขาว่า “เราบอกความจริงแก่ท่านว่า ในวันนี้ คือคืนนี้เอง ก่อนไก่จะขันสองหน ท่านจะปฏิเสธเราสามครั้ง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 31, 'แต่เปโตรทูลแข็งแรงทีเดียวว่า “ถึงแม้ข้าพระองค์จะต้องตายกับพระองค์ ข้าพระองค์ก็จะไม่ปฏิเสธพระองค์เลย” เหล่าสาวกก็ทูลเช่นนั้นเหมือนกันทุกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 32, 'พระเยซูกับเหล่าสาวกมายังที่แห่งหนึ่งชื่อเกทเสมนี และพระองค์ตรัสแก่สาวกของพระองค์ว่า “จงนั่งอยู่ที่นี่ขณะเมื่อเราอธิษฐาน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 33, 'พระองค์ก็พาเปโตร ยากอบ และยอห์นไปด้วย แล้วพระองค์ทรงเริ่มวิตกยิ่งและหนักพระทัยนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 34, 'จึงตรัสกับเหล่าสาวกว่า “ใจเราเป็นทุกข์แทบจะตาย จงเฝ้าอยู่ที่นี่เถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 35, 'แล้วพระองค์เสด็จดําเนินไปอีกหน่อยหนึ่ง ซบพระกายลงที่ดินอธิษฐานว่า ถ้าเป็นได้ให้เวลานั้นล่วงพ้นไปจากพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 36, 'พระองค์ทูลว่า “อับบา พระบิดาเจ้าข้า พระองค์ทรงสามารถกระทําสิ่งทั้งปวงได้ ขอเอาถ้วยนี้เลื่อนพ้นไปจากข้าพระองค์เถิด แต่ว่าอย่าให้เป็นตามใจปรารถนาของข้าพระองค์ แต่ให้เป็นไปตามพระทัยของพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 37, 'พระองค์จึงเสด็จกลับมาทรงพบเหล่าสาวกนอนหลับอยู่ และตรัสกับเปโตรว่า “ซีโมนเอ๋ย ท่านนอนหลับหรือ จะคอยเฝ้าอยู่สักชั่วเวลาหนึ่งไม่ได้หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 38, 'ท่านทั้งหลายจงเฝ้าระวังและอธิษฐานเพื่อท่านจะไม่ต้องถูกการทดลอง จิตใจพร้อมแล้วก็จริง แต่เนื้อหนังยังอ่อนกําลัง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 39, 'พระองค์จึงเสด็จไปอธิษฐานอีกครั้งหนึ่ง ทรงกล่าวคําเหมือนคราวก่อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 40, 'ครั้นพระองค์เสด็จกลับมาก็ทรงพบสาวกนอนหลับอยู่อีก (เพราะตาเขาลืมไม่ขึ้น) และเขาไม่รู้ว่าจะทูลประการใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 41, 'เมื่อเสด็จกลับมาครั้งที่สามพระองค์จึงตรัสแก่เขาว่า “เดี๋ยวนี้ ท่านจงนอนต่อไปให้หายเหนื่อย พอเถอะ ดูเถิด เวลาซึ่งบุตรมนุษย์ต้องถูกทรยศให้ตกอยู่ในมือของคนบาปนั้นมาถึงแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 42, 'ลุกขึ้นไปกันเถิด ดูเถิด ผู้ที่จะทรยศเรามาใกล้แล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 43, 'พระองค์ตรัสยังไม่ทันขาดคํา ในทันใดนั้นยูดาสซึ่งเป็นคนหนึ่งในเหล่าสาวกสิบสองคนนั้น กับหมู่ชนเป็นอันมาก ถือดาบถือไม้ตะบอง ได้มาจากพวกปุโรหิตใหญ่ พวกธรรมาจารย์ และพวกผู้ใหญ่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 44, 'ผู้ที่จะทรยศพระองค์นั้นได้ให้สัญญาณแก่เขาว่า “เราจุบผู้ใด ก็เป็นผู้นั้นแหละ จงจับกุมเขาไปให้มั่นคง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 45, 'และทันทีที่ยูดาสมาถึง เขาตรงเข้ามาหาพระองค์ทูลว่า “พระอาจารย์เจ้าข้า พระอาจารย์เจ้าข้า” แล้วจุบพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 46, 'คนเหล่านั้นก็จับกุมพระองค์ไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 47, 'คนหนึ่งในพวกเหล่านั้นที่ยืนอยู่ใกล้ๆ ได้ชักดาบออกฟันผู้รับใช้คนหนึ่งของมหาปุโรหิตถูกหูของเขาขาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 48, 'พระเยซูจึงตรัสถามพวกเหล่านั้นว่า “ท่านทั้งหลายเห็นเราเป็นโจรหรือจึงถือดาบ ถือตะบองออกมาจับเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 49, 'เราได้อยู่กับท่านทั้งหลายทุกวันสั่งสอนในพระวิหาร ท่านก็หาได้จับเราไม่ แต่จะต้องสําเร็จตามพระคัมภีร์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 50, 'แล้วสาวกทั้งหมดได้ละทิ้งพระองค์ไว้และพากันหนีไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 51, 'มีชายหนุ่มคนหนึ่งห่มผ้าป่านผืนหนึ่งคลุมร่างกายที่เปลือยเปล่าของตนติดตามพระองค์ไป พวกหนุ่มๆก็จับเขาไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 52, 'แต่เขาได้สลัดผ้าป่านผืนนั้นทิ้งเสีย แล้วเปลือยกายหนีไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 53, 'เขาพาพระเยซูไปหามหาปุโรหิต และมีบรรดาพวกปุโรหิตใหญ่ พวกผู้ใหญ่ และพวกธรรมาจารย์ชุมนุมพร้อมกันอยู่ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 54, 'ฝ่ายเปโตรได้ติดตามพระองค์ไปห่างๆจนเข้าไปถึงคฤหาสน์ของมหาปุโรหิต และนั่งผิงไฟอยู่กับพวกคนใช้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 55, 'พวกปุโรหิตใหญ่ กับบรรดาสมาชิกสภาได้หาพยานมาเบิกปรักปรําพระเยซูเพื่อจะประหารพระองค์เสีย แต่หาหลักฐานไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 56, 'ด้วยว่ามีหลายคนเป็นพยานเท็จปรักปรําพระองค์ แต่คําของเขาแตกต่างกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 57, 'มีบางคนยืนขึ้นเบิกความเท็จปรักปรําพระองค์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 58, '“ข้าพเจ้าได้ยินคนนี้ว่า ‘เราจะทําลายพระวิหารนี้ที่สร้างไว้ด้วยมือมนุษย์ และในสามวันจะสร้างขึ้นอีกวิหารหนึ่งซึ่งไม่สร้างด้วยมือมนุษย์เลย’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 59, 'แต่คําพยานของคนเหล่านั้นเองก็ยังแตกต่างไม่ถูกต้องกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 60, 'มหาปุโรหิตจึงลุกขึ้นยืนท่ามกลางที่ชุมนุมถามพระเยซูว่า “ท่านไม่ตอบอะไรบ้างหรือ ซึ่งเขาเบิกความปรักปรําท่านนั้นจะว่าอย่างไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 61, 'แต่พระองค์ทรงนิ่งอยู่ มิได้ตอบประการใด ท่านมหาปุโรหิตจึงถามพระองค์อีกว่า “ท่านเป็นพระคริสต์พระบุตรของผู้ทรงบรมสุขหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 62, 'พระเยซูทรงตอบว่า “เราเป็น และท่านทั้งหลายจะได้เห็นบุตรมนุษย์นั่งข้างขวาของผู้ทรงฤทธานุภาพ และเสด็จมาในเมฆแห่งฟ้าสวรรค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 63, 'ท่านมหาปุโรหิตจึงฉีกเสื้อของตนแล้วกล่าวว่า “เราต้องการพยานอะไรอีกเล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 64, 'ท่านทั้งหลายได้ยินเขาพูดหมิ่นประมาทแล้ว ท่านทั้งหลายคิดเห็นอย่างไร” คนทั้งปวงจึงเห็นพร้อมกันว่าควรจะมีโทษถึงตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 65, 'บางคนก็เริ่มถ่มน้ําลายรดพระองค์ ปิดพระพักตร์พระองค์ ตีพระองค์ แล้วว่าแก่พระองค์ว่า “พยากรณ์ซิ” และพวกคนใช้ก็เอาฝ่ามือตบพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 66, 'และขณะที่เปโตรอยู่ใต้คฤหาสน์ข้างล่างนั้น มีหญิงคนหนึ่งในพวกสาวใช้ของท่านมหาปุโรหิตเดินมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 67, 'เมื่อเห็นเปโตรผิงไฟอยู่เขาเขม้นดู แล้วพูดว่า “เจ้าได้อยู่กับเยซูชาวนาซาเร็ธด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 68, 'แต่เปโตรปฏิเสธว่า “ที่เจ้าว่านั้นข้าไม่รู้เรื่องและไม่เข้าใจ” เปโตรจึงออกไปที่ระเบียงบ้าน แล้วไก่ก็ขัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 69, 'อีกครั้งหนึ่งสาวใช้คนหนึ่งได้เห็นเปโตร แล้วเริ่มบอกกับคนที่ยืนอยู่ที่นั่นว่า “คนนี้แหละ เป็นพวกเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 70, 'แต่เปโตรก็ปฏิเสธอีก แล้วอีกสักครู่หนึ่งคนทั้งหลายที่ยืนอยู่ที่นั่นได้ว่าแก่เปโตรว่า “เจ้าเป็นคนหนึ่งในพวกเขาแน่แล้ว ด้วยว่าเจ้าเป็นชาวกาลิลี และสําเนียงของเจ้าก็ส่อไปทางเดียวกันด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 71, 'แต่เปโตรเริ่มสบถและสาบานว่า “คนที่เจ้าว่านั้นข้าไม่รู้จัก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 72, 'แล้วไก่ก็ขันเป็นครั้งที่สอง เปโตรจึงระลึกถึงคําที่พระเยซูตรัสไว้แก่เขาว่า “ก่อนไก่ขันสองหน ท่านจะปฏิเสธเราสามครั้ง” เมื่อเปโตรหวนคิดขึ้นได้ก็ร้องไห้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 1, 'พอรุ่งเช้า พวกปุโรหิตใหญ่กับพวกผู้ใหญ่และพวกธรรมาจารย์และบรรดาสมาชิกสภาได้ปรึกษากัน แล้วจึงมัดพระเยซูพาไปมอบไว้แก่ปีลาต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 2, 'ปีลาตจึงถามพระองค์ว่า “ท่านเป็นกษัตริย์ของพวกยิวหรือ” พระองค์ตรัสตอบท่านว่า “ท่านว่าแล้วนี่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 3, 'ฝ่ายพวกปุโรหิตใหญ่ได้ฟ้องกล่าวโทษพระองค์เป็นหลายประการ แต่พระองค์ไม่ตรัสตอบประการใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 4, 'ปีลาตจึงถามพระองค์อีกว่า “ท่านไม่ตอบอะไรหรือ ดูเถิด เขากล่าวความปรักปรําท่านหลายประการทีเดียว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 5, 'แต่พระเยซูมิได้ตรัสตอบประการใดอีก ปีลาตจึงอัศจรรย์ใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 6, 'ในเทศกาลเลี้ยงนั้น ปีลาตเคยปล่อยนักโทษคนหนึ่งให้เขาตามที่เขาขอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 7, 'มีคนหนึ่งชื่อบารับบัสซึ่งต้องจําอยู่ในจําพวกคนกบฏ ผู้ที่ได้กระทําการฆาตกรรมในการกบฏนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 8, 'ประชาชนจึงได้ร้องเสียงดัง เริ่มขอปีลาตให้ทําตามที่ท่านเคยทําให้เขานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 9, 'ปีลาตได้ถามเขาว่า “ท่านทั้งหลายปรารถนาจะให้เราปล่อยกษัตริย์ของพวกยิวหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 10, 'เพราะท่านรู้อยู่แล้วว่า พวกปุโรหิตใหญ่ได้มอบพระองค์ไว้ด้วยความอิจฉา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 11, 'แต่พวกปุโรหิตใหญ่ยุยงประชาชนให้ขอปีลาตปล่อยบารับบัสแทนพระเยซู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 12, 'ฝ่ายปีลาตจึงถามเขาอีกว่า “ท่านทั้งหลายจะให้เราทําอย่างไรแก่คนนี้ ซึ่งท่านทั้งหลายเรียกว่ากษัตริย์ของพวกยิว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 13, 'เขาทั้งหลายร้องตะโกนอีกว่า “ตรึงเขาเสียที่กางเขนเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 14, 'ปีลาตจึงถามเขาทั้งหลายว่า “ตรึงทําไม เขาได้ทําผิดประการใด” แต่ประชาชนยิ่งร้องว่า “ตรึงเขาเสียที่กางเขนเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 15, 'ปีลาตปรารถนาจะเอาใจประชาชน จึงปล่อยบารับบัสให้เขา และเมื่อได้ให้โบยตีพระองค์แล้ว ก็มอบพระเยซูให้เขาเอาไปตรึงไว้ที่กางเขน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 16, 'พวกทหารจึงนําพระองค์ไปข้างในราชสํานักคือที่เรียกว่าศาลปรีโทเรียม แล้วเรียกพวกทหารทั้งกองให้มาประชุมกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 17, 'เขาเอาเสื้อสีม่วงมาสวมพระองค์ เอาหนามสานเป็นมงกุฎสวมพระเศียรพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 18, 'แล้วเริ่มคํานับพระองค์พูดว่า “กษัตริย์ของพวกยิวเจ้าข้า ขอทรงพระเจริญ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 19, 'แล้วเขาได้เอาไม้อ้อตีพระเศียรพระองค์ และได้ถ่มน้ําลายรดพระองค์ แล้วคุกเข่าลงนมัสการพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 20, 'เมื่อเยาะเย้ยพระองค์แล้ว เขาถอดเสื้อสีม่วงนั้นออก แล้วเอาฉลองพระองค์เองสวมให้ และนําพระองค์ออกไปเพื่อจะตรึงเสียที่กางเขน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 21, 'มีคนหนึ่งชื่อซีโมนชาวไซรีน เป็นบิดาของอเล็กซานเดอร์และรูฟัส เดินมาจากบ้านนอกตามทางนั้น เขาก็เกณฑ์ซีโมนให้แบกกางเขนของพระองค์ไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 22, 'เขาพาพระองค์มาถึงสถานที่แห่งหนึ่งชื่อกลโกธา แปลว่า สถานที่กะโหลกศีรษะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 23, 'แล้วเขาเอาน้ําองุ่นระคนกับมดยอบให้พระองค์เสวย แต่พระองค์ไม่รับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 24, 'ครั้นเขาตรึงพระองค์ที่กางเขนแล้ว เขาก็เอาฉลองพระองค์จับฉลากแบ่งปันกันเพื่อจะรู้ว่าใครจะได้อะไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 25, 'เมื่อเขาตรึงพระองค์ไว้นั้นเป็นเวลาเช้าสามโมง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 26, 'มีข้อหาที่ลงโทษพระองค์เขียนไว้ข้างบนว่า “กษัตริย์ของพวกยิว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 27, 'เขาเอาโจรสองคนตรึงไว้พร้อมกับพระองค์ ข้างขวาพระหัตถ์คนหนึ่ง และข้างซ้ายอีกคนหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 28, 'คําซึ่งเขียนไว้ในพระคัมภีร์แล้วนั้นจึงสําเร็จ คือที่ว่า ‘ท่านถูกนับเข้ากับบรรดาผู้ละเมิด’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 29, 'ฝ่ายคนทั้งหลายที่เดินผ่านไปมานั้น ก็ด่าว่าพระองค์ สั่นศีรษะของเขากล่าวว่า “เฮ้ย เจ้าผู้จะทําลายพระวิหารและสร้างขึ้นในสามวันน่ะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 30, 'จงช่วยตัวเองให้รอดและลงมาจากกางเขนเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 31, 'พวกปุโรหิตใหญ่กับพวกธรรมาจารย์ก็เยาะเย้ยพระองค์ในระหว่างพวกเขาเองเหมือนกันว่า “เขาช่วยคนอื่นให้รอดได้ แต่ช่วยตัวเองไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 32, 'ให้เจ้าพระคริสต์ กษัตริย์แห่งอิสราเอล ลงมาจากกางเขนเดี๋ยวนี้เถอะ เพื่อเราจะได้เห็นและเชื่อ” และสองคนนั้นที่ถูกตรึงไว้กับพระองค์ก็กล่าวคําหยาบช้าต่อพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 33, 'ครั้นเวลาเที่ยงก็บังเกิดความมืดทั่วทั้งแผ่นดินจนถึงบ่ายสามโมง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 34, 'พอบ่ายสามโมงแล้ว พระเยซูทรงร้องเสียงดังว่า “เอโลอี เอโลอี ลามาสะบักธานี” แปลว่า “พระเจ้าของข้าพระองค์ พระเจ้าของข้าพระองค์ ไฉนพระองค์ทรงทอดทิ้งข้าพระองค์เสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 35, 'บางคนในพวกที่ยืนอยู่ที่นั่นเมื่อได้ยินก็พูดว่า “ดูเถิด เขาเรียกเอลียาห์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 36, 'มีคนหนึ่งวิ่งไปเอาฟองน้ําชุบน้ําองุ่นเปรี้ยว เสียบปลายไม้อ้อ ส่งให้พระองค์เสวย แล้วว่า “อย่าเพิ่ง ให้เราคอยดูว่า เอลียาห์จะมาปลดเขาลงหรือไม่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 37, 'ฝ่ายพระเยซูทรงร้องเสียงดัง แล้วทรงปล่อยพระวิญญาณจิตออกไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 38, 'ขณะนั้นม่านในพระวิหารก็ขาดออกเป็นสองท่อน ตั้งแต่บนตลอดล่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 39, 'ส่วนนายร้อยที่ยืนอยู่ตรงพระพักตร์พระองค์ เมื่อเห็นว่าพระองค์ทรงร้องเสียงดังและทรงปล่อยพระวิญญาณจิตออกไปแล้ว จึงพูดว่า “แท้จริงท่านผู้นี้เป็นพระบุตรของพระเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 40, 'มีพวกผู้หญิงมองดูอยู่แต่ไกล ในพวกผู้หญิงนั้นมีมารีย์ชาวมักดาลา มารีย์มารดาของยากอบน้อยและของโยเสส และนางสะโลเม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 41, '(ผู้หญิงเหล่านั้นได้ติดตามและปรนนิบัติพระองค์ เมื่อพระองค์ยังอยู่ในแคว้นกาลิลี) และผู้หญิงอื่นอีกหลายคนที่ได้ขึ้นมายังกรุงเยรูซาเล็มกับพระองค์ได้อยู่ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 42, 'ครั้นถึงเวลาพลบค่ํา เหตุที่วันนั้นเป็นวันเตรียม คือวันก่อนวันสะบาโต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 43, 'โยเซฟเป็นชาวบ้านอาริมาเธีย ซึ่งอยู่ในพวกสมาชิกสภาและเป็นที่นับถือของคนทั้งปวง ทั้งกําลังคอยท่าอาณาจักรของพระเจ้าด้วย จึงกล้าเข้าไปหาปีลาตขอพระศพพระเยซู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 44, 'ปีลาตก็ประหลาดใจที่พระองค์สิ้นพระชนม์แล้ว จึงเรียกนายร้อยมาถามเขาว่า พระองค์ตายแล้วหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 45, 'เมื่อได้รู้เรื่องจากนายร้อยแล้ว ท่านจึงมอบพระศพให้แก่โยเซฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 46, 'ฝ่ายโยเซฟได้ซื้อผ้าป่านเนื้อละเอียด และเชิญพระศพลงมาเอาผ้าป่านพันหุ้มไว้ แล้วเชิญพระศพไปประดิษฐานไว้ในอุโมงค์ซึ่งได้สกัดไว้ในศิลา แล้วกลิ้งก้อนหินปิดปากอุโมงค์ไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 47, 'ฝ่ายมารีย์ชาวมักดาลา และมารีย์มารดาของโยเสส ได้เห็นที่ที่พระศพบรรจุไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 1, 'ครั้นวันสะบาโตล่วงไปแล้ว มารีย์ชาวมักดาลา มารีย์มารดาของยากอบ และนางสะโลเม ซื้อเครื่องหอมมาเพื่อจะไปชโลมพระศพของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 2, 'เวลารุ่งเช้าวันต้นสัปดาห์พอดวงอาทิตย์ขึ้นเขาก็มาถึงอุโมงค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 3, 'และเขาพูดกันว่า “ใครจะช่วยกลิ้งก้อนหินออกจากปากอุโมงค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 4, 'เมื่อเขามองดูก็เห็นก้อนหินนั้นกลิ้งออกแล้ว เพราะเป็นก้อนหินโตมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 5, 'ครั้นเขาเข้าไปในอุโมงค์แล้ว ได้เห็นหนุ่มคนหนึ่งนุ่งห่มผ้ายาวสีขาวนั่งอยู่ข้างขวา ผู้หญิงนั้นก็ตกตะลึง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 6, 'ฝ่ายคนหนุ่มนั้นบอกเขาว่า “อย่าตกตะลึงเลย พวกท่านทั้งหลายมาหาพระเยซูชาวนาซาเร็ธซึ่งต้องตรึงไว้ที่กางเขน พระองค์ทรงเป็นขึ้นมาแล้ว พระองค์หาได้ประทับที่นี่ไม่ จงดูที่ที่เขาได้วางพระศพของพระองค์เถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 7, 'แต่จงไปบอกพวกสาวกของพระองค์ทั้งเปโตรเถิดว่า พระองค์เสด็จไปยังแคว้นกาลิลีก่อนท่านทั้งหลาย ท่านทั้งหลายจะเห็นพระองค์ที่นั่น เหมือนพระองค์ตรัสไว้แก่พวกท่านแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 8, 'หญิงเหล่านั้นก็ออกจากอุโมงค์รีบหนีไป เพราะพิศวงตกใจจนตัวสั่น เขามิได้พูดกับผู้ใดเพราะเขากลัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 9, 'ครั้นรุ่งเช้าวันต้นสัปดาห์ เมื่อพระเยซูทรงเป็นขึ้นมาแล้ว พระองค์ทรงสําแดงพระองค์ให้ปรากฏแก่มารีย์ชาวมักดาลาก่อน คือมารีย์คนที่พระองค์ได้ขับผีออกเจ็ดผี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 10, 'มารีย์จึงไปบอกพวกคนที่เคยอยู่กับพระองค์แต่ก่อน เขากําลังร้องไห้เป็นทุกข์อยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 11, 'เมื่อเขาได้ยินว่าพระองค์ทรงพระชนม์อยู่ และมารีย์ได้เห็นพระองค์แล้ว เขาก็ไม่เชื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 12, 'ภายหลังพระองค์ทรงปรากฏพระกายอีกรูปหนึ่งแก่ศิษย์สองคน เมื่อเขากําลังเดินทางออกไปบ้านนอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 13, 'ศิษย์สองคนนั้นจึงไปบอกศิษย์อื่นๆ แต่เขามิได้เชื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 14, 'ภายหลังพระองค์ทรงปรากฏแก่สาวกสิบเอ็ดคนเมื่อเขาเอนกายลงรับประทานอยู่ และทรงติเตียนเขาเพราะเขาไม่เชื่อและใจดื้อดึง ด้วยเหตุที่เขามิได้เชื่อคนซึ่งได้เห็นพระองค์เมื่อพระองค์ทรงเป็นขึ้นมาแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 15, 'ฝ่ายพระองค์จึงตรัสสั่งพวกสาวกว่า “ท่านทั้งหลายจงออกไปทั่วโลกประกาศข่าวประเสริฐแก่มนุษย์ทุกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 16, 'ผู้ที่เชื่อและรับบัพติศมาก็จะรอด แต่ผู้ที่ไม่เชื่อจะต้องถูกลงพระอาชญา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 17, 'มีคนเชื่อที่ไหน หมายสําคัญเหล่านี้จะบังเกิดขึ้นที่นั้น คือเขาจะขับผีออกโดยนามของเรา เขาจะพูดภาษาใหม่หลายภาษา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 18, 'เขาจะจับงูได้ ถ้าเขาดื่มยาพิษอย่างใด จะไม่เป็นอันตรายแก่เขา และเขาจะวางมือบนคนไข้คนป่วย แล้วคนเหล่านั้นจะหายโรค”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 19, 'ครั้นองค์พระผู้เป็นเจ้าตรัสสั่งเขาแล้ว พระองค์ทรงถูกรับขึ้นไปในสวรรค์ ประทับเบื้องขวาพระหัตถ์ของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 20, 'พวกสาวกเหล่านั้นจึงออกไปเทศนาสั่งสอนทุกแห่งทุกตําบล และองค์พระผู้เป็นเจ้าทรงร่วมงานกับเขา และทรงสนับสนุนคําสอนของเขาโดยหมายสําคัญที่ประกอบนั้น เอเมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 1, 'มีหลายคนได้เรียบเรียงเรื่องราวเหล่านั้น ซึ่งเป็นที่เชื่อได้อย่างแน่นอนในท่ามกลางเราทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 2, 'ตามที่เขาผู้ได้เห็นกับตาเองตั้งแต่ต้น และเป็นผู้ประกาศพระวจนะนั้นได้แสดงให้เรารู้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 3, 'เรียนท่านเธโอฟีลัส ที่เคารพอย่างสูง ข้าพเจ้าเองก็ได้รู้ทุกสิ่งอย่างถูกต้องตั้งแต่ต้น จึงได้เห็นดีด้วยที่จะเรียบเรียงเรื่องตามลําดับฝากให้ท่านด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 4, 'เพื่อท่านจะได้รู้แน่นอนอันเกี่ยวกับเรื่องราวเหล่านั้น ซึ่งมีผู้แจ้งให้ท่านทราบแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 5, 'ในรัชกาลเฮโรด กษัตริย์ของยูเดีย มีปุโรหิตคนหนึ่งชื่อเศคาริยาห์ อยู่ในเวรอาบียาห์ ภรรยาของเศคาริยาห์ชื่อเอลีซาเบธ อยู่ในตระกูลอาโรน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 6, 'เขาทั้งสองเป็นคนชอบธรรมจําเพาะพระพักตร์พระเจ้า และดําเนินตามพระบัญญัติและกฎทั้งปวงขององค์พระผู้เป็นเจ้าไม่มีที่ติเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 7, 'แต่เขาไม่มีบุตร เพราะว่านางเอลีซาเบธเป็นหมัน และเขาทั้งสองก็ชราแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 8, 'ต่อมาขณะที่เศคาริยาห์ทําหน้าที่ปุโรหิตเข้าเฝ้าพระเจ้า เมื่อท่านอยู่เวรประจําการของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 9, 'ท่านได้ฉลากตามธรรมเนียมของปุโรหิต ต้องเข้าไปในพระวิหารขององค์พระผู้เป็นเจ้าเพื่อเผาเครื่องหอมบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 10, 'ส่วนบรรดาประชาชนก็อธิษฐานอยู่ภายนอกในเวลาเผาเครื่องหอมนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 11, 'ทูตสวรรค์องค์หนึ่งขององค์พระผู้เป็นเจ้ามาปรากฏแก่เศคาริยาห์ ยืนอยู่ที่ข้างขวาแท่นเผาเครื่องหอมบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 12, 'เมื่อเศคาริยาห์เห็นก็ตกใจกลัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 13, 'แต่ทูตสวรรค์องค์นั้นกล่าวแก่ท่านว่า “เศคาริยาห์เอ๋ย อย่ากลัวเลย ด้วยได้ทรงฟังคําอธิษฐานของท่านแล้ว นางเอลีซาเบธภรรยาของท่านจะมีบุตรเป็นผู้ชาย และท่านจะตั้งชื่อบุตรนั้นว่า ยอห์น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 14, 'ท่านจะมีความปรีดาและยินดี และคนเป็นอันมากจะเปรมปรีดิ์ที่บุตรนั้นบังเกิดมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 15, 'เพราะว่าเขาจะเป็นใหญ่ในสายพระเนตรขององค์พระผู้เป็นเจ้า เขาจะไม่ดื่มน้ําองุ่นหรือเหล้าเลย และเขาจะประกอบไปด้วยพระวิญญาณบริสุทธิ์ตั้งแต่ครรภ์มารดา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 16, 'เขาจะนําคนอิสราเอลหลายคนให้หันกลับมาหาองค์พระผู้เป็นเจ้า พระเจ้าของเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 17, 'เขาจะนําหน้าพระองค์โดยแสดงอารมณ์และฤทธิ์เดชอย่างเอลียาห์ ให้พ่อกลับคืนดีกับลูกและคนที่ไม่เชื่อฟังให้กลับได้ปัญญาของคนชอบธรรม เพื่อจัดเตรียมชนชาติหนึ่งไว้ให้สมแก่องค์พระผู้เป็นเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 18, 'เศคาริยาห์จึงทูลทูตสวรรค์ว่า “ข้าพเจ้าจะรู้แน่ได้อย่างไร เพราะข้าพเจ้าก็ชราและภรรยาก็อายุมากแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 19, 'ฝ่ายทูตสวรรค์นั้นจึงตอบท่านว่า “เราคือกาเบรียลซึ่งยืนอยู่เฉพาะพระพักตร์พระเจ้า และทรงใช้ให้มาพูดและนําข่าวดีนี้มาแจ้งกับท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 20, 'ดูเถิด เพราะท่านมิได้เชื่อถ้อยคําของเรา ถึงเรื่องที่จะสําเร็จตามกําหนด ท่านก็จะเป็นใบ้ แล้วไม่สามารถพูดได้ จนถึงวันที่การณ์เหล่านี้จะบังเกิดขึ้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 21, 'ฝ่ายคนทั้งหลายที่คอยเศคาริยาห์ ก็ประหลาดใจ เพราะท่านอยู่ในพระวิหารช้านาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 22, 'เมื่อท่านออกมาแล้วก็พูดกับเขาไม่ได้ คนทั้งหลายจึงหยั่งรู้ว่าท่านได้เห็นนิมิตในพระวิหาร เพราะท่านใช้ใบ้กับเขาและยังเป็นใบ้อยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 23, 'ต่อมาเมื่อหมดเวรของท่านแล้ว ท่านก็กลับไปบ้าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 24, 'ภายหลังนางเอลีซาเบธภรรยาของท่านก็ตั้งครรภ์ แล้วไปซ่อนตัวอยู่ห้าเดือนพูดว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 25, '“องค์พระผู้เป็นเจ้าได้ทรงกระทําเช่นนี้แก่ข้าพเจ้า ในวันที่พระองค์ได้ทอดพระเนตรดูข้าพเจ้า เพื่อนําความอดสูของข้าพเจ้าที่มีอยู่ท่ามกลางคนทั้งปวงไปเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 26, 'เมื่อถึงเดือนที่หก พระเจ้าทรงใช้ทูตสวรรค์กาเบรียลนั้น ให้มายังเมืองหนึ่งในแคว้นกาลิลี ชื่อนาซาเร็ธ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 27, 'มาถึงหญิงพรหมจารีคนหนึ่งที่ได้หมั้นกันไว้กับชายคนหนึ่งชื่อโยเซฟ เป็นคนในวงศ์วานดาวิด หญิงพรหมจารีนั้นชื่อมารีย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 28, 'ทูตสวรรค์มาถึงหญิงพรหมจารีนั้นแล้วว่า “เธอผู้ซึ่งเป็นที่ทรงโปรดปรานมาก จงจําเริญเถิด องค์พระผู้เป็นเจ้าทรงสถิตอยู่กับเธอ เธอได้รับพระพรท่ามกลางสตรีทั้งปวง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 29, 'เมื่อมารีย์เห็นทูตสวรรค์องค์นั้น เธอก็ตกใจเพราะคําของทูตนั้น และรําพึงว่าคํากล่าวนั้นจะหมายว่าอะไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 30, 'แล้วทูตสวรรค์จึงกล่าวแก่เธอว่า “มารีย์เอ๋ย อย่ากลัวเลย เพราะเธอเป็นที่พระเจ้าทรงโปรดปรานแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 31, 'ดูเถิด เธอจะตั้งครรภ์และคลอดบุตรชายคนหนึ่ง จงตั้งชื่อบุตรนั้นว่า เยซู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 32, 'บุตรนั้นจะเป็นใหญ่ และจะทรงเรียกว่าเป็นบุตรของพระเจ้าสูงสุด พระเจ้าซึ่งเป็นองค์พระผู้เป็นเจ้า จะทรงประทานพระที่นั่งของดาวิดบรรพบุรุษของท่านให้แก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 33, 'และท่านจะครอบครองวงศ์วานของยาโคบสืบไปเป็นนิตย์ และอาณาจักรของท่านจะไม่รู้จักสิ้นสุดเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 34, 'ฝ่ายมารีย์ทูลทูตสวรรค์นั้นว่า “เหตุการณ์นั้นจะเป็นไปอย่างไรได้ เพราะข้าพเจ้ายังหาได้ร่วมกับชายใดไม่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 35, 'ทูตสวรรค์จึงตอบเธอว่า “พระวิญญาณบริสุทธิ์จะเสด็จลงมาบนเธอ และฤทธิ์เดชของผู้สูงสุดจะปกเธอ เหตุฉะนั้นองค์บริสุทธิ์ที่จะบังเกิดมานั้นจะได้เรียกว่า พระบุตรของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 36, 'ดูเถิด ถึงนางเอลีซาเบธ ญาติของเธอชราแล้ว ก็ยังตั้งครรภ์มีบุตรเป็นชายด้วย บัดนี้ นางนั้นที่คนเขาถือว่าเป็นหญิงหมันก็มีครรภ์ได้หกเดือนแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 37, 'เพราะว่าไม่มีสิ่งหนึ่งสิ่งใดซึ่งพระเจ้าทรงกระทําไม่ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 38, 'ส่วนมารีย์จึงทูลว่า “ดูเถิด ข้าพเจ้าเป็นหญิงคนใช้ขององค์พระผู้เป็นเจ้า ขอให้บังเกิดแก่ข้าพเจ้าตามคําของท่านเถิด” แล้วทูตสวรรค์นั้นจึงจากเธอไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 39, 'คราวนั้นมารีย์จึงรีบออกไปถึงเมืองหนึ่งในแถบภูเขาแห่งยูเดีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 40, 'แล้วเข้าไปในเรือนของเศคาริยาห์ทักทายปราศรัยนางเอลีซาเบธ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 41, 'ต่อมาเมื่อนางเอลีซาเบธได้ยินคําปราศรัยของมารีย์ ทารกในครรภ์ของเขาก็ดิ้น และนางเอลีซาเบธก็ประกอบไปด้วยพระวิญญาณบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 42, 'จึงร้องเสียงดังว่า “ท่านได้รับพรท่ามกลางสตรีทั้งปวง และผู้บังเกิดจากครรภ์ของท่านก็ได้รับพระพรด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 43, 'เป็นไฉนข้าพเจ้าจึงได้ความโปรดปรานเช่นนี้ คือมารดาขององค์พระผู้เป็นเจ้าของข้าพเจ้าได้มาหาข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 44, 'เพราะดูเถิด พอเสียงปราศรัยของท่านเข้าหูข้าพเจ้า ทารกในครรภ์ของข้าพเจ้าก็ดิ้นด้วยความยินดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 45, 'สตรีที่ได้เชื่อก็เป็นสุข เพราะว่าจะสําเร็จตามพระดํารัสจากองค์พระผู้เป็นเจ้าที่มาถึงเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 46, 'นางมารีย์จึงว่า “จิตใจของข้าพเจ้าก็ยกย่ององค์พระผู้เป็นเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 47, 'และวิญญาณของข้าพเจ้าก็เกิดความปีติยินดีในพระเจ้า พระผู้ช่วยให้รอดของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 48, 'เพราะพระองค์ทรงห่วงใยฐานะอันยากต่ําแห่งหญิงคนใช้ของพระองค์ เพราะดูเถิด ตั้งแต่นี้ไปคนทุกชั่วอายุจะเรียกข้าพเจ้าว่าผาสุก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 49, 'เพราะว่าผู้ทรงฤทธิ์ได้ทรงกระทําการใหญ่กับข้าพเจ้า พระนามของพระองค์ก็บริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 50, 'พระกรุณาของพระองค์มีแก่บรรดาผู้ยําเกรงพระองค์ ทุกชั่วอายุสืบๆไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 51, 'พระองค์ทรงสําแดงฤทธิ์ด้วยพระกรของพระองค์ พระองค์ทรงกระทําให้คนที่มีใจเย่อหยิ่งแตกฉานซ่านเซ็นไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 52, 'พระองค์ทรงถอดเจ้านายจากพระที่นั่ง และทรงยกผู้น้อยขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 53, 'พระองค์ทรงโปรดให้คนอดอยากอิ่มด้วยสิ่งดี และพระองค์ทรงกระทําให้คนมั่งมีไปมือเปล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 54, 'พระองค์ทรงช่วยอิสราเอลผู้รับใช้ของพระองค์ คือทรงจดจําพระกรุณาของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 55, 'ที่มีต่ออับราฮัมและต่อเชื้อสายของท่านเป็นนิตย์ ตามที่พระองค์ได้ตรัสไว้กับบรรพบุรุษของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 56, 'มารีย์อาศัยอยู่กับนางเอลีซาเบธประมาณสามเดือน แล้วจึงกลับไปยังบ้านของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 57, 'ครั้นเวลาซึ่งนางเอลีซาเบธจะคลอดบุตรครบถ้วนแล้ว นางก็คลอดบุตรเป็นชาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 58, 'เพื่อนบ้านและญาติพี่น้องของนางได้ยินว่า องค์พระผู้เป็นเจ้าได้ทรงสําแดงพระมหากรุณาแก่นาง เขาทั้งหลายก็พากันเปรมปรีดิ์ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 59, 'ต่อมาครั้นถึงวันที่แปดแล้ว เขาก็พากันมาให้ทารกนั้นเข้าสุหนัต และเขาจะให้ชื่อทารกนั้นว่า เศคาริยาห์ ตามชื่อบิดา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 60, 'ฝ่ายมารดาจึงตอบว่า “ไม่ใช่ แต่ต้องให้ชื่อว่ายอห์น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 61, 'เขาพากันตอบนางว่า “ไม่มีผู้ใดในพวกญาติของท่านที่มีชื่ออย่างนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 62, 'แล้วเขาจึงใช้ใบ้กับบิดา ถามว่าท่านอยากจะให้บุตรนั้นชื่ออะไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 63, 'บิดาจึงขอกระดานชนวนมาเขียนว่า “ชื่อของบุตรคือยอห์น” คนทั้งหลายก็ประหลาดใจนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 64, 'ในทันใดนั้นปากและลิ้นของท่านก็คืนดีอีก แล้วท่านกล่าวสรรเสริญพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 65, 'บรรดาเพื่อนบ้านของท่านก็บังเกิดความกลัว และเหตุการณ์ทั้งปวงนั้นก็เลื่องลือไปทั่วแถบภูเขาแคว้นยูเดีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 66, 'บรรดาคนที่ได้ยินก็จดจําไว้ในใจและว่า “ทารกนั้นจะเป็นอย่างไรหนอ” และพระหัตถ์ขององค์พระผู้เป็นเจ้าอยู่กับเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 67, 'ฝ่ายเศคาริยาห์ผู้เป็นบิดาประกอบไปด้วยพระวิญญาณบริสุทธิ์แล้วได้พยากรณ์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 68, '“จงสรรเสริญองค์พระผู้เป็นเจ้า พระเจ้าของพวกอิสราเอล ด้วยว่าพระองค์ได้ทรงเยี่ยมเยียนและช่วยไถ่ชนชาติของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 69, 'และได้ทรงชูเขาแห่งความรอดขึ้นมาเพื่อเราในวงศ์วานของดาวิดผู้รับใช้ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 70, 'ตามที่พระองค์ได้ตรัสไว้ตั้งแต่เริ่มสร้างโลก โดยปากของพวกศาสดาพยากรณ์บริสุทธิ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 71, 'ว่าเราจะรอดพ้นจากพวกศัตรูของเราทั้งหลาย และพ้นจากมือของคนทั้งปวงที่ชังเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 72, 'จะทรงสําแดงพระกรุณาซึ่งทรงสัญญาแก่บรรพบุรุษของเรา และทรงระลึกถึงพันธสัญญาบริสุทธิ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 73, 'คือคําปฏิญาณซึ่งพระองค์ได้ทรงกระทําไว้กับอับราฮัมบรรพบุรุษของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 74, 'ว่าเมื่อเราทั้งหลายพ้นจากมือศัตรูของเราแล้ว จะทรงโปรดให้เราปรนนิบัติพระองค์โดยปราศจากความกลัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 75, 'ด้วยความบริสุทธิ์และด้วยความชอบธรรมจําเพาะพระพักตร์พระองค์ตลอดชีวิตของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 76, 'ท่านทารกเอ๋ย เขาจะเรียกท่านว่าเป็นศาสดาพยากรณ์ของผู้สูงสุด เพราะว่าท่านจะนําหน้าองค์พระผู้เป็นเจ้าเพื่อจะจัดเตรียมมรรคาของพระองค์ไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 77, 'เพื่อจะให้ชนชาติของพระองค์มีความรู้ถึงความรอด โดยการทรงยกบาปของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 78, 'โดยพระทัยเมตตากรุณาแห่งพระเจ้าของเรา แสงอรุณจากเบื้องสูงจึงมาเยี่ยมเยียนเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 79, 'เพื่อจะส่องสว่างแก่คนทั้งหลายผู้อยู่ในที่มืด และในเงาแห่งความตาย เพื่อจะนําเท้าของเราไปในทางสันติสุข”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 80, 'ฝ่ายทารกนั้นก็ได้เจริญวัยขึ้น และจิตวิญญาณก็มีกําลังทวีขึ้น และไปอาศัยในถิ่นทุรกันดารจนถึงวันที่ท่านจะได้มาปรากฏแก่ชนชาติอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 1, 'อยู่มาคราวนั้น มีรับสั่งจากซีซาร์ ออกัสตัส ให้จดทะเบียนสํามะโนครัวทั่วทั้งแผ่นดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 2, '(นี่เป็นครั้งแรกที่ได้จดทะเบียนสํามะโนครัว เมื่อคีรินิอัสเป็นเจ้าเมืองซีเรีย)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 3, 'คนทั้งปวงต่างคนต่างได้ไปขึ้นทะเบียนยังเมืองของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 4, 'ฝ่ายโยเซฟก็ขึ้นไปจากเมืองนาซาเร็ธแคว้นกาลิลีถึงเมืองของดาวิด ชื่อเบธเลเฮมแคว้นยูเดียด้วย (เพราะว่าเขาเป็นวงศ์วานและเชื้อสายของดาวิด)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 5, 'เขาได้ไปกับมารีย์ภรรยาของเขาที่เขาได้หมั้นไว้แล้ว เพื่อจะขึ้นทะเบียนและนางมีครรภ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 6, 'เมื่อเขาทั้งสองยังอยู่ที่นั่น ก็ถึงเวลาที่มารีย์จะประสูติบุตร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 7, 'นางจึงประสูติบุตรชายหัวปี เอาผ้าอ้อมพันและวางไว้ในรางหญ้า เพราะว่าไม่มีที่ว่างให้เขาในโรงแรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 8, 'ในแถบนั้น มีคนเลี้ยงแกะอยู่ในทุ่งนา เฝ้าฝูงแกะของเขาในเวลากลางคืน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 9, 'ดูเถิด มีทูตสวรรค์ขององค์พระผู้เป็นเจ้ามาปรากฏแก่เขา และรัศมีขององค์พระผู้เป็นเจ้าส่องล้อมรอบเขา และเขากลัวนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 10, 'ฝ่ายทูตสวรรค์องค์นั้นกล่าวแก่เขาว่า “อย่ากลัวเลย เพราะดูเถิด เรานําข่าวดีมายังท่านทั้งหลาย คือความปรีดียิ่งซึ่งจะมาถึงคนทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 11, 'เพราะว่าในวันนี้พระผู้ช่วยให้รอดของท่านทั้งหลาย คือพระคริสต์เจ้า มาบังเกิดที่เมืองดาวิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 12, 'นี่จะเป็นหมายสําคัญแก่ท่านทั้งหลาย คือท่านจะได้พบพระกุมารนั้นพันผ้าอ้อมนอนอยู่ในรางหญ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 13, 'ทันใดนั้น มีชาวสวรรค์หมู่หนึ่งมาอยู่กับทูตสวรรค์องค์นั้นร่วมสรรเสริญพระเจ้าว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 14, '“รัศมีภาพจงมีแด่พระเจ้าในที่สูงสุด และบนแผ่นดินโลกจงมีสันติสุข และสันถวไมตรีจงมีแก่มนุษย์ทั้งปวง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 15, 'ต่อมาเมื่อทูตสวรรค์เหล่านั้นไปจากเขาขึ้นสู่สวรรค์แล้ว พวกเลี้ยงแกะได้พูดกันว่า “บัดนี้ให้เราไปยังเมืองเบธเลเฮม ดูเหตุการณ์ที่เกิดขึ้นนั้น ซึ่งองค์พระผู้เป็นเจ้าได้ทรงแจ้งแก่เรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 16, 'เขาก็รีบไปแล้วพบนางมารีย์กับโยเซฟและพบพระกุมารนั้นนอนอยู่ในรางหญ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 17, 'ครั้นเขาได้เห็นแล้ว จึงเล่าเรื่องซึ่งเขาได้ยินถึงพระกุมารนั้นให้กระจายออกไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 18, 'คนทั้งปวงที่ได้ยินก็ประหลาดใจด้วยเนื้อความที่คนเลี้ยงแกะได้บอกแก่เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 19, 'ฝ่ายนางมารีย์ก็เก็บบรรดาสิ่งเหล่านี้ไว้ในใจ และรําพึงอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 20, 'คนเลี้ยงแกะจึงกลับไปยกย่องสรรเสริญพระเจ้า เพราะเหตุการณ์ทั้งปวงซึ่งเขาได้ยินและได้เห็น ดังได้กล่าวไว้แก่เขาแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 21, 'ครั้นครบแปดวันแล้ว เป็นวันให้พระกุมารนั้นเข้าสุหนัต เขาจึงให้นามว่า เยซู ตามซึ่งทูตสวรรค์ได้กล่าวไว้ก่อนยังมิได้ปฏิสนธิในครรภ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 22, 'เมื่อวันทําพิธีชําระตัวของนางมารีย์ตามพระราชบัญญัติของโมเสสเสร็จลงแล้ว เขาทั้งหลายจึงนําพระกุมารไปยังกรุงเยรูซาเล็มจะถวายแด่องค์พระผู้เป็นเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 23, '(ตามที่เขียนไว้แล้วในพระราชบัญญัติขององค์พระผู้เป็นเจ้าว่า “บุตรชายทุกคนที่เบิกครรภ์ครั้งแรก จะได้เรียกว่าเป็นผู้บริสุทธิ์ถวายแด่องค์พระผู้เป็นเจ้า”)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 24, 'และถวายเครื่องบูชาตามที่ได้ตรัสสั่งไว้แล้วในพระราชบัญญัติขององค์พระผู้เป็นเจ้าคือ ‘นกเขาคู่หนึ่ง หรือนกพิราบหนุ่มสองตัว’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 25, 'ดูเถิด มีชายคนหนึ่งในกรุงเยรูซาเล็มชื่อสิเมโอน เป็นคนชอบธรรมและเกรงกลัวพระเจ้า และคอยเวลาซึ่งพวกอิสราเอลจะได้รับความบรรเทาทุกข์ และพระวิญญาณบริสุทธิ์ทรงสถิตกับท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 26, 'พระวิญญาณบริสุทธิ์ได้ทรงสําแดงแก่ท่านว่า ท่านจะไม่ตายจนกว่าจะได้เห็นพระคริสต์ขององค์พระผู้เป็นเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 27, 'สิเมโอนเข้าไปในพระวิหารโดยพระวิญญาณทรงนํา และเมื่อบิดามารดาได้นําพระกุมารเยซูเข้าไป เพื่อจะกระทําแก่พระกุมารตามธรรมเนียมแห่งพระราชบัญญัติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 28, 'สิเมโอนจึงอุ้มพระกุมาร และสรรเสริญพระเจ้าว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 29, '“ข้าแต่องค์พระผู้เป็นเจ้า บัดนี้พระองค์ทรงให้ผู้รับใช้ของพระองค์ไปเป็นสุขตามพระดํารัสของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 30, 'เพราะว่าตาของข้าพระองค์ได้เห็นความรอดของพระองค์แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 31, 'ซึ่งพระองค์ได้ทรงจัดเตรียมไว้ต่อหน้าบรรดาชนชาติทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 32, 'เป็นความสว่างส่องแสงแก่คนต่างชาติและเป็นสง่าราศีของพวกอิสราเอล ชนชาติของพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 33, 'ฝ่ายโยเซฟกับมารดาของพระกุมารก็ประหลาดใจ เพราะถ้อยคําซึ่งท่านได้กล่าวถึงพระกุมารนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 34, 'แล้วสิเมโอนก็อวยพรแก่เขา แล้วกล่าวแก่นางมารีย์มารดาของพระกุมารนั้นว่า “ดูก่อนท่าน ทรงตั้งพระกุมารนี้ไว้เป็นเหตุให้หลายคนในพวกอิสราเอลล้มลงหรือยกตั้งขึ้น และจะเป็นหมายสําคัญซึ่งคนปฏิเสธ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 35, 'เพื่อความคิดในใจของคนเป็นอันมากจะได้ปรากฏแจ้ง (เออ ถึงจิตใจของท่านเองก็ยังจะถูกดาบแทงทะลุด้วย)”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 36, 'ยังมีผู้พยากรณ์หญิงคนหนึ่งชื่ออันนา บุตรสาวฟานูเอลในตระกูลอาเชอร์ นางเป็นคนชรามากแล้ว มีสามีตั้งแต่ยังเป็นสาวพรหมจารีอยู่ และอยู่ด้วยกันเจ็ดปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 37, 'แล้วก็เป็นม่ายมาจนถึงอายุแปดสิบสี่ปี นางมิได้ไปจากพระวิหารเลย อยู่รับใช้พระเจ้าด้วยการถืออดอาหารและอธิษฐาน ทั้งกลางคืนและกลางวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 38, 'ในขณะนั้นผู้หญิงคนนี้ก็เข้ามาขอบพระคุณองค์พระผู้เป็นเจ้าเช่นกัน และกล่าวถึงพระกุมารให้คนทั้งปวงที่คอยการทรงไถ่อยู่ในกรุงเยรูซาเล็มฟัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 39, 'ครั้นโยเซฟกับนางมารีย์ได้กระทําการทั้งปวงตามพระราชบัญญัติขององค์พระผู้เป็นเจ้าเสร็จแล้ว จึงกลับไปถึงนาซาเร็ธเมืองของตนในแคว้นกาลิลี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 40, 'พระกุมารนั้นก็เจริญวัย และเข้มแข็งขึ้นฝ่ายจิตวิญญาณ ประกอบด้วยสติปัญญา และพระคุณของพระเจ้าอยู่กับท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 41, 'ฝ่ายบิดามารดาเคยขึ้นไปยังกรุงเยรูซาเล็มในการเลี้ยงเทศกาลปัสกาทุกปีๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 42, 'เมื่อพระกุมารมีพระชนมายุสิบสองพรรษา เขาทั้งหลายก็ขึ้นไปยังกรุงเยรูซาเล็มตามธรรมเนียมการเลี้ยงนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 43, 'เมื่อครบกําหนดวันเลี้ยงกันแล้ว ขณะเขากําลังกลับไป พระกุมารเยซูก็ยังค้างอยู่ในกรุงเยรูซาเล็ม ฝ่ายโยเซฟกับมารดาของพระองค์ก็ไม่รู้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 44, 'แต่เพราะเขาทั้งสองคิดว่าพระกุมารนั้นอยู่ในหมู่คนที่มาด้วยกัน เขาจึงเดินทางไปได้วันหนึ่ง แล้วหาพระกุมารในหมู่ญาติพี่น้องและพวกคนที่รู้จักกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 45, 'เมื่อไม่พบ พวกเขาจึงกลับไปเที่ยวหาพระองค์ที่กรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 46, 'ต่อมาครั้นหามาได้สามวันแล้ว จึงพบพระกุมารนั่งอยู่ในพระวิหารท่ามกลางพวกอาจารย์ ฟังและไต่ถามพวกอาจารย์เหล่านั้นอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 47, 'คนทั้งปวงที่ได้ยินก็ประหลาดใจในสติปัญญาและคําตอบของพระกุมารนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 48, 'ฝ่ายเขาทั้งสองเมื่อเห็นพระกุมารแล้วก็ประหลาดใจ มารดาจึงถามพระกุมารว่า “ลูกเอ๋ย ทําไมจึงทําแก่เราอย่างนี้ ดูเถิด พ่อกับแม่แสวงหาเป็นทุกข์นัก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 49, 'พระกุมารจึงตอบเขาทั้งสองว่า “ท่านเที่ยวหาฉันทําไม ท่านไม่ทราบหรือว่า ฉันต้องกระทําพระราชกิจแห่งพระบิดาของฉัน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 50, 'เขาทั้งสองก็ไม่เข้าใจคําซึ่งพระกุมารกล่าวแก่เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 51, 'แล้วพระกุมารก็ลงไปกับเขาไปยังเมืองนาซาเร็ธ อยู่ใต้ความปกครองของเขา มารดาก็เก็บเรื่องราวทั้งหมดนั้นไว้ในใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 52, 'พระเยซูก็ได้จําเริญขึ้นในด้านสติปัญญา ในด้านร่างกาย และเป็นที่ชอบจําเพาะพระเจ้า และต่อหน้าคนทั้งปวงด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 1, 'เมื่อปีที่สิบห้าในรัชกาลทิเบริอัส ซีซาร์ ปอนทิอัสปีลาตเป็นเจ้าเมืองยูเดีย เฮโรดเป็นเจ้าเมืองกาลิลี ฟีลิปน้องชายของเฮโรดเป็นเจ้าเมืองอิทูเรียกับบริเวณแคว้นตราโคนิติส ลีซาเนียสเป็นเจ้าเมืองอาบีเลน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 2, 'อันนาสกับคายาฟาสเป็นมหาปุโรหิต คราวนั้นพระวจนะของพระเจ้ามาถึงยอห์นบุตรชายเศคาริยาห์ในถิ่นทุรกันดาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 3, 'แล้วยอห์นจึงไปทั่วบริเวณรอบแม่น้ําจอร์แดน ประกาศเรื่องบัพติศมาอันสําแดงการกลับใจใหม่ เพื่อจะทรงยกความผิดบาปเสียได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 4, 'ตามที่มีเขียนไว้แล้วในหนังสือถ้อยคําของอิสยาห์ศาสดาพยากรณ์ว่า “เสียงผู้ร้องในถิ่นทุรกันดารว่า ‘จงเตรียมมรรคาแห่งองค์พระผู้เป็นเจ้า จงกระทําหนทางของพระองค์ให้ตรงไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 5, 'หุบเขาทุกแห่งจะถมให้เต็ม ภูเขาและเนินทุกแห่งจะให้ต่ําลง ทางคดจะกลายเป็นทางตรง และทางที่ขรุขระจะกลายเป็นทางราบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 6, 'เนื้อหนังทั้งปวงจะได้เห็นความรอดของพระเจ้า’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 7, 'ยอห์นจึงกล่าวแก่ประชาชนที่ออกมารับบัพติศมาจากท่านว่า “โอ เจ้าชาติงูร้าย ใครได้เตือนเจ้าให้หนีจากพระอาชญาซึ่งจะมาถึงนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 8, 'เหตุฉะนั้น จงพิสูจน์การกลับใจของเจ้าด้วยผลที่เกิดขึ้น อย่านึกเหมาเอาในใจว่าตัวมีอับราฮัมเป็นบิดา เพราะเราบอกเจ้าทั้งหลายว่า พระเจ้าทรงฤทธิ์สามารถจะให้บุตรเกิดขึ้นกับอับราฮัมจากก้อนหินเหล่านี้ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 9, 'บัดนี้ขวานวางไว้ที่โคนต้นไม้แล้ว และทุกต้นที่ไม่เกิดผลดีจะต้องตัดเสียแล้วโยนทิ้งในกองไฟ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 10, 'ฝ่ายประชาชนจึงถามท่านว่า “เราจะต้องทําประการใด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 11, 'ท่านจึงตอบเขาว่า “ผู้ใดมีเสื้อสองตัว จงปันให้แก่คนไม่มี และใครมีอาหาร จงปันให้เหมือนกัน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 12, 'พวกเก็บภาษีก็มาขอรับบัพติศมาด้วย และถามท่านว่า “อาจารย์เจ้าข้า พวกข้าพเจ้าต้องทําประการใด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 13, 'ท่านจึงตอบเขาว่า “เจ้าทั้งหลายอย่าเก็บภาษีเกินพิกัด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 14, 'ฝ่ายพวกทหารถามท่านด้วยว่า “พวกข้าพเจ้าเล่า จะต้องทําประการใด” ท่านตอบเขาว่า “อย่ากดขี่ผู้ใด อย่าหาความใส่ผู้ใด แต่จงพอใจในค่าจ้างของตน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 15, 'เมื่อคนทั้งหลายกําลังคอยพระคริสต์อยู่ และได้ใคร่ครวญถึงยอห์นว่า ตัวท่านเป็นพระคริสต์หรือมิใช่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 16, 'ยอห์นจึงตอบเขาทั้งหลายว่า “เราให้เจ้ารับบัพติศมาด้วยน้ําก็จริง แต่จะมีพระองค์หนึ่งเสด็จมาทรงมีอิทธิฤทธิ์ยิ่งกว่าเราอีก ซึ่งเราไม่คู่ควรแม้จะแก้สายฉลองพระบาทของพระองค์ พระองค์นั้นจะทรงให้เจ้าทั้งหลายรับบัพติศมาด้วยพระวิญญาณบริสุทธิ์และด้วยไฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 17, 'พระหัตถ์ของพระองค์ถือพลั่วพร้อมแล้วเพื่อจะทรงชําระลานข้าวของพระองค์ให้ทั่ว และเพื่อจะเก็บข้าวไว้ในยุ้งฉางของพระองค์ แต่พระองค์จะทรงเผาแกลบด้วยไฟที่ไม่รู้ดับ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 18, 'ยอห์นจึงประกาศตักเตือนอีกหลายประการแก่คนทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 19, 'ฝ่ายเฮโรดเจ้าเมือง เมื่อถูกยอห์นว่าติเตียนเพราะเรื่องนางเฮโรเดียสภรรยาของน้องชายชื่อฟีลิป และเพราะการชั่วทั้งหมดที่เฮโรดได้กระทํานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 20, 'เฮโรดยังทําความชั่วนี้เพิ่มกับที่ได้ทํามาแล้ว คือได้จับยอห์นจําไว้ในคุก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 21, 'อยู่มาเมื่อคนทั้งปวงรับบัพติศมา และพระเยซูทรงรับบัพติศมาด้วย ขณะเมื่อทรงอธิษฐานอยู่ ท้องฟ้าก็แหวกออก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 22, 'และพระวิญญาณบริสุทธิ์ทรงรูปสัณฐานเหมือนนกเขาได้ลงมาบนพระองค์ และพระสุรเสียงมาจากฟ้าสวรรค์ว่า “ท่านเป็นบุตรที่รักของเรา เราชอบใจท่านมาก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 23, 'เมื่อพระเยซูทรงมีพระชนมายุประมาณสามสิบพรรษา (ตามความคาดหมายของคนทั้งหลาย) เข้าใจว่าเป็นบุตรโยเซฟ ซึ่งเป็นบุตรเฮลี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 24, 'ซึ่งเป็นบุตรมัทธัต ซึ่งเป็นบุตรเลวี ซึ่งเป็นบุตรเมลคี ซึ่งเป็นบุตรยันนาย ซึ่งเป็นบุตรโยเซฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 25, 'ซึ่งเป็นบุตรมัทธาธีอัส ซึ่งเป็นบุตรอาโมส ซึ่งเป็นบุตรนาอูม ซึ่งเป็นบุตรเอสลี ซึ่งเป็นบุตรนักกาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 26, 'ซึ่งเป็นบุตรมาอาท ซึ่งเป็นบุตรมัทธาธีอัส ซึ่งเป็นบุตรเสเมอิน ซึ่งเป็นบุตรโยเซฟ ซึ่งเป็นบุตรยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 27, 'ซึ่งเป็นบุตรโยอันนา ซึ่งเป็นบุตรเรซา ซึ่งเป็นบุตรเศรุบบาเบล ซึ่งเป็นบุตรเชอัลทิเอล ซึ่งเป็นบุตรเนรี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 28, 'ซึ่งเป็นบุตรเมลคี ซึ่งเป็นบุตรอัดดี ซึ่งเป็นบุตรโคสัม ซึ่งเป็นบุตรเอลมาดัม ซึ่งเป็นบุตรเอร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 29, 'ซึ่งเป็นบุตรโยซี ซึ่งเป็นบุตรเอลีเยเซอร์ ซึ่งเป็นบุตรโยริม ซึ่งเป็นบุตรมัทธัต ซึ่งเป็นบุตรเลวี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 30, 'ซึ่งเป็นบุตรสิเมโอน ซึ่งเป็นบุตรยูดาห์ ซึ่งเป็นบุตรโยเซฟ ซึ่งเป็นบุตรโยนาน ซึ่งเป็นบุตรเอลียาคิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 31, 'ซึ่งเป็นบุตรเมเลอา ซึ่งเป็นบุตรเมนนัน ซึ่งเป็นบุตรมัทตะธา ซึ่งเป็นบุตรนาธัน ซึ่งเป็นบุตรดาวิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 32, 'ซึ่งเป็นบุตรเจสซี ซึ่งเป็นบุตรโอเบด ซึ่งเป็นบุตรโบอาส ซึ่งเป็นบุตรสัลโมน ซึ่งเป็นบุตรนาโชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 33, 'ซึ่งเป็นบุตรอัมมีนาดับ ซึ่งเป็นบุตรราม ซึ่งเป็นบุตรเฮสโรน ซึ่งเป็นบุตรเปเรศ ซึ่งเป็นบุตรยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 34, 'ซึ่งเป็นบุตรยาโคบ ซึ่งเป็นบุตรอิสอัค ซึ่งเป็นบุตรอับราฮัม ซึ่งเป็นบุตรเทราห์ ซึ่งเป็นบุตรนาโฮร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 35, 'ซึ่งเป็นบุตรเสรุก ซึ่งเป็นบุตรเรกู ซึ่งเป็นบุตรเปเลก ซึ่งเป็นบุตรเอเบอร์ ซึ่งเป็นบุตรเชลาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 36, 'ซึ่งเป็นบุตรเคนัน ซึ่งเป็นบุตรอารฟัคชาด ซึ่งเป็นบุตรเชม ซึ่งเป็นบุตรโนอาห์ ซึ่งเป็นบุตรลาเมค');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 37, 'ซึ่งเป็นบุตรเมธูเสลาห์ ซึ่งเป็นบุตรเอโนค ซึ่งเป็นบุตรยาเรด ซึ่งเป็นบุตรมาหะลาเลล ซึ่งเป็นบุตรเคนัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 38, 'ซึ่งเป็นบุตรเอโนช ซึ่งเป็นบุตรเสท ซึ่งเป็นบุตรอาดัม ซึ่งเป็นบุตรพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 1, 'พระเยซูประกอบด้วยพระวิญญาณบริสุทธิ์ได้เสด็จกลับไปจากแม่น้ําจอร์แดน และพระวิญญาณได้ทรงนําพระองค์ไปในถิ่นทุรกันดาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 2, 'ทรงถูกพญามารทดลองถึงสี่สิบวัน ในวันเหล่านั้นพระองค์มิได้เสวยอะไรเลย และเมื่อสิ้นสี่สิบวันแล้ว พระองค์ทรงอยากพระกระยาหาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 3, 'พญามารจึงทูลพระองค์ว่า “ถ้าท่านเป็นพระบุตรของพระเจ้า จงสั่งก้อนหินนี้ให้กลายเป็นขนมปัง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 4, 'ฝ่ายพระเยซูตรัสตอบมารว่า “มีเขียนไว้แล้วว่า ‘มนุษย์จะบํารุงชีวิตด้วยอาหารสิ่งเดียวก็หามิได้ แต่บํารุงด้วยพระวจนะทุกคําของพระเจ้า’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 5, 'แล้วพญามารจึงนําพระองค์ขึ้นไปยังภูเขาที่สูง สําแดงบรรดาราชอาณาจักรทั่วพิภพในขณะเดียวให้พระองค์ทอดพระเนตร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 6, 'แล้วพญามารได้ทูลพระองค์ว่า “อํานาจทั้งสิ้นนี้และสง่าราศีของราชอาณาจักรนั้นเราจะยกให้แก่ท่าน เพราะว่ามอบเป็นสิทธิไว้แก่เราแล้ว และเราปรารถนาจะให้แก่ผู้ใดก็จะให้แก่ผู้นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 7, 'เหตุฉะนั้น ถ้าท่านจะกราบนมัสการเรา สรรพสิ่งนั้นจะเป็นของท่านทั้งหมด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 8, 'ฝ่ายพระเยซูตรัสตอบมารว่า “อ้ายซาตาน จงถอยไปข้างหลังเรา เพราะมีเขียนไว้แล้วว่า ‘จงนมัสการองค์พระผู้เป็นเจ้าผู้เป็นพระเจ้าของท่าน และปรนนิบัติพระองค์แต่ผู้เดียว’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 9, 'แล้วมารจึงนําพระองค์ไปยังกรุงเยรูซาเล็ม และให้พระองค์ประทับอยู่ที่ยอดหลังคาพระวิหาร แล้วทูลพระองค์ว่า “ถ้าท่านเป็นพระบุตรพระเจ้า จงโจนลงไปจากที่นี่เถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 10, 'เพราะมีเขียนไว้แล้วว่า ‘พระองค์จะรับสั่งเหล่าทูตสวรรค์ของพระองค์ในเรื่องท่าน ให้ป้องกันรักษาท่านไว้’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 11, 'และ ‘เหล่าทูตสวรรค์จะเอามือประคองชูท่านไว้ เกรงว่าในเวลาหนึ่งเวลาใดเท้าของท่านจะกระแทกหิน’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 12, 'พระเยซูจึงตรัสตอบมารว่า “มีคํากล่าวไว้ว่า ‘อย่าทดลององค์พระผู้เป็นเจ้าผู้เป็นพระเจ้าของท่าน’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 13, 'เมื่อพญามารทําการทดลองทุกอย่างสิ้นแล้ว จึงละพระองค์ไปชั่วคราว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 14, 'พระเยซูได้เสด็จกลับไปด้วยฤทธิ์เดชแห่งพระวิญญาณยังแคว้นกาลิลี และกิตติศัพท์ของพระองค์เลื่องลือไปตามถิ่นโดยรอบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 15, 'พระองค์ทรงสั่งสอนในธรรมศาลาต่างๆของเขา และได้รับความสรรเสริญจากคนทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 16, 'แล้วพระองค์เสด็จมาถึงเมืองนาซาเร็ธ เป็นที่ซึ่งพระองค์ทรงเจริญวัยขึ้น พระองค์เสด็จเข้าไปในธรรมศาลาในวันสะบาโตตามเคย และทรงยืนขึ้นเพื่อจะอ่านพระคัมภีร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 17, 'เขาจึงส่งพระคัมภีร์อิสยาห์ศาสดาพยากรณ์ให้แก่พระองค์ เมื่อพระองค์ทรงคลี่หนังสือนั้นออก ก็ค้นพบข้อที่เขียนไว้ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 18, '‘พระวิญญาณแห่งองค์พระผู้เป็นเจ้าสถิตอยู่บนข้าพเจ้า เพราะว่าพระองค์ได้ทรงเจิมตั้งข้าพเจ้าไว้ให้ประกาศข่าวประเสริฐแก่คนยากจน พระองค์ได้ทรงใช้ข้าพเจ้าให้รักษาคนที่ชอกช้ําระกําใจ ให้ร้องประกาศอิสรภาพแก่บรรดาเชลย ให้ประกาศแก่คนตาบอดว่าจะได้เห็นอีก ให้ปล่อยผู้ฟกช้ําเป็นอิสระ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 19, 'และให้ประกาศปีแห่งความโปรดปรานขององค์พระผู้เป็นเจ้า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 20, 'แล้วพระองค์ทรงม้วนหนังสือส่งคืนให้แก่เจ้าหน้าที่ แล้วทรงนั่งลงและตาของคนทั้งปวงในธรรมศาลาก็เพ่งดูพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 21, 'พระองค์จึงเริ่มตรัสแก่เขาว่า “คัมภีร์ตอนนี้ที่ท่านได้ยินกับหูของท่านก็สําเร็จในวันนี้แล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 22, 'คนทั้งปวงก็เป็นพยานรับรองคําของพระองค์ และประหลาดใจด้วยถ้อยคําอันประกอบด้วยคุณซึ่งออกมาจากพระโอษฐ์ของพระองค์ และว่า “คนนี้เป็นบุตรชายของโยเซฟมิใช่หรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 23, 'พระองค์จึงตรัสแก่เขาว่า “ท่านทั้งหลายจะกล่าวคําสุภาษิตข้อนี้แก่เราเป็นแน่ คือว่า ‘หมอจงรักษาตัวเองเถิด คือบรรดาการซึ่งเราได้ยินว่า ท่านได้กระทําในเมืองคาเปอรนาอุม จงกระทําในเมืองของตนที่นี่ด้วย’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 24, 'พระองค์ตรัสว่า “เราบอกความจริงแก่ท่านทั้งหลายว่า ไม่มีศาสดาพยากรณ์คนใดได้รับการต้อนรับในบ้านเมืองของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 25, 'แต่เราบอกความจริงแก่ท่านทั้งหลายว่า มีหญิงม่ายหลายคนในพวกอิสราเอลคราวเอลียาห์ เมื่อท้องฟ้าปิดเสียถึงสามปีกับหกเดือนจึงเกิดกันดารอาหารมากทั่วแผ่นดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 26, 'และเอลียาห์มิได้รับใช้ให้ไปหาหญิงม่ายคนใด เว้นแต่หญิงม่ายคนหนึ่งในบ้านศาเรฟัทแคว้นเมืองไซดอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 27, 'และมีคนโรคเรื้อนหลายคนในพวกอิสราเอลคราวเอลีชาศาสดาพยากรณ์ แต่ไม่มีผู้ใดได้รับการรักษาให้หายโรคนั้นเลย เว้นแต่นาอามานชาวซีเรีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 28, 'เมื่อคนทั้งปวงในธรรมศาลาได้ยินดังนั้นก็โกรธยิ่งนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 29, 'จึงลุกขึ้นผลักพระองค์ออกจากเมือง พาไปยังแง่ของเงื้อมเขาที่เมืองของเขา ซึ่งตั้งอยู่บนเนินนั้น หมายจะผลักพระองค์ลงไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 30, 'แต่พระองค์ทรงดําเนินผ่านท่ามกลางเขาพ้นไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 31, 'พระองค์เสด็จลงไปถึงเมืองคาเปอรนาอุมแคว้นกาลิลี และได้สั่งสอนเขาทั้งหลายทุกวันสะบาโต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 32, 'คนทั้งปวงก็อัศจรรย์ใจด้วยการสอนของพระองค์ เพราะคําของพระองค์ประกอบด้วยอํานาจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 33, 'มีชายคนหนึ่งในธรรมศาลาที่มีผีโสโครกเข้าสิง เขาร้องเสียงดัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 34, 'กล่าวว่า “ไฮ้ พระเยซูชาวนาซาเร็ธ ปล่อยเราไว้ เราเกี่ยวข้องอะไรกับท่านเล่า ท่านมาเพื่อจะทําลายเราหรือ เรารู้ว่าท่านเป็นผู้ใด ท่านคือองค์บริสุทธิ์ของพระเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 35, 'พระเยซูจึงตรัสห้ามมันว่า “จงนิ่งเสีย ออกมาจากเขาซิ” เมื่อผีนั้นได้ทําให้เขาล้มลงท่ามกลางประชาชนแล้ว ก็ออกมาจากเขา แต่มิได้ทําอันตรายเขาเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 36, 'คนทั้งปวงก็ประหลาดใจนักพูดกันว่า “คํานี้เป็นอย่างไรหนอ เพราะว่าท่านได้สั่งผีโสโครกด้วยสิทธิอํานาจและด้วยฤทธิ์เดช มันก็ออกมา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 37, 'กิตติศัพท์ของพระองค์จึงได้เลื่องลือไปทุกตําบลที่อยู่รอบนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 38, 'ฝ่ายพระองค์ทรงลุกขึ้นออกจากธรรมศาลา เสด็จเข้าไปในเรือนของซีโมน แม่ยายซีโมนป่วยเป็นไข้หนัก เขาทั้งหลายจึงอ้อนวอนพระองค์ให้ช่วยหญิงนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 39, 'พระองค์ทรงยืนอยู่ข้างคนเจ็บ ทรงห้ามไข้ ไข้ก็หาย และในทันใดนั้นแม่ยายของซีโมนก็ลุกขึ้นปรนนิบัติเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 40, 'ครั้นเวลาตะวันยอแสง ใครมีคนเจ็บเป็นโรคต่างๆก็พามาหาพระองค์ พระองค์ก็ทรงวางพระหัตถ์ถูกต้องเขาทุกคน ให้เขาหายโรค');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 41, 'ผีก็ออกมาจากคนหลายคนด้วย ร้องว่า “ท่านเป็นพระคริสต์พระบุตรของพระเจ้า” ฝ่ายพระองค์ก็ทรงห้ามมิให้มันพูด เพราะว่ามันรู้แล้วว่าพระองค์เป็นพระคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 42, 'ครั้นรุ่งเช้าพระองค์เสด็จออกไปยังที่เปลี่ยว ประชาชนเที่ยวเสาะหาพระองค์ ครั้นพบแล้วก็หน่วงเหนี่ยวพระองค์ไว้ไม่ให้ไปจากเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 43, 'แต่พระองค์ตรัสแก่เขาว่า “เราต้องไปประกาศเรื่องอาณาจักรของพระเจ้าแก่เมืองอื่นด้วย เพราะว่าที่เราได้รับใช้มาก็เพราะเหตุนี้เอง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 44, 'พระองค์ทรงประกาศในธรรมศาลาทั่วแคว้นกาลิลี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 1, 'ต่อมาครั้นเมื่อประชาชนกําลังเบียดเสียดพระองค์เพื่อฟังพระวจนะของพระเจ้า พระองค์ทรงยืนอยู่ที่ฝั่งทะเลสาบเยนเนซาเรท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 2, 'และพระองค์ทอดพระเนตรเห็นเรือสองลําจอดอยู่ริมฝั่งทะเลสาบนั้น แต่ชาวประมงขึ้นจากเรือแล้วกําลังซักอวนอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 3, 'พระองค์จึงเสด็จลงเรือลําหนึ่ง เป็นเรือของซีโมน และทรงขอให้เขาถอยไปจากฝั่งหน่อยหนึ่ง แล้วพระองค์ทรงนั่งลงสอนประชาชนจากเรือนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 4, 'เมื่อพระองค์ตรัสสอนเสร็จแล้ว จึงตรัสแก่ซีโมนว่า “จงถอยออกไปที่น้ําลึกหย่อนอวนต่างๆลงจับปลา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 5, 'ซีโมนทูลตอบพระองค์ว่า “พระอาจารย์เจ้าข้า ข้าพระองค์ทั้งหลายทอดอวนคืนยังรุ่ง ไม่ได้อะไรเลย แต่ข้าพระองค์จะหย่อนอวนลงตามพระดํารัสของพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 6, 'เมื่อเขาหย่อนลงแล้ว ก็ล้อมปลาไว้เป็นอันมาก จนอวนของเขาขาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 7, 'เขาจึงทําสําคัญแก่ผู้ร่วมงานที่อยู่ในเรืออีกลําหนึ่งให้มาช่วย เขาก็มาช่วย แล้วได้ปลาเต็มเรือทั้งสองลํา จนเรือเริ่มจมลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 8, 'ฝ่ายซีโมนเปโตรเมื่อเห็นดังนั้น ก็กราบลงที่พระชานุของพระเยซูทูลว่า “โอ พระองค์เจ้าข้า ขอเสด็จไปให้ห่างจากข้าพระองค์เถิด เพราะว่าข้าพระองค์เป็นคนบาป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 9, 'เพราะว่าเขากับคนทั้งหลายที่อยู่ด้วยกันประหลาดใจด้วยปลาเป็นอันมากที่เขาจับได้นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 10, 'ยากอบและยอห์นบุตรชายของเศเบดี ผู้ร่วมงานกับซีโมนก็ประหลาดใจเหมือนกัน พระเยซูตรัสแก่ซีโมนว่า “อย่ากลัวเลย ตั้งแต่นี้ไปท่านจะเป็นผู้จับคน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 11, 'เมื่อเขานําเรือมาถึงฝั่งแล้ว เขาก็ละทิ้งสิ่งสารพัด และตามพระองค์ไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 12, 'ต่อมาเมื่อพระองค์ทรงอยู่ในเมืองหนึ่ง ดูเถิด มีคนเป็นโรคเรื้อนเต็มทั้งตัว เมื่อเขาเห็นพระเยซูก็ซบหน้าลงถึงดินอ้อนวอนทูลพระองค์ว่า “พระองค์เจ้าข้า เพียงแต่พระองค์จะโปรดก็จะทรงบันดาลให้ข้าพระองค์สะอาดได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 13, 'พระองค์ทรงยื่นพระหัตถ์ถูกต้องเขาแล้วตรัสว่า “เราพอใจแล้ว จงสะอาดเถิด” ในทันใดนั้นโรคเรื้อนของเขาก็หาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 14, 'พระองค์จึงกําชับเขาไม่ให้บอกผู้ใด และตรัสว่า “แต่จงไปแสดงตัวแก่ปุโรหิต และถวายเครื่องบูชาสําหรับคนที่หายโรคเรื้อนแล้วตามซึ่งโมเสสได้สั่งไว้ เพื่อเป็นหลักฐานต่อคนทั้งหลายว่าเจ้าหายโรคแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 15, 'แต่กิตติศัพท์ของพระองค์ยิ่งเลื่องลือไป และประชาชนเป็นอันมากมาชุมนุมกันเพื่อจะฟังพระองค์ และรับการรักษาโรคต่างๆของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 16, 'แต่พระองค์เสด็จออกไปในที่เปลี่ยว และทรงอธิษฐาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 17, 'คราวนั้นวันหนึ่งเมื่อพระองค์ทรงสั่งสอนอยู่ มีพวกฟาริสีและพวกธรรมาจารย์ฝ่ายพระราชบัญญัตินั่งอยู่ด้วย เป็นผู้มาจากทุกเมืองในแคว้นกาลิลี แคว้นยูเดีย และจากกรุงเยรูซาเล็ม ฤทธิ์เดชขององค์พระผู้เป็นเจ้าก็สถิตอยู่เพื่อจะรักษาเขาให้หายโรค');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 18, 'และดูเถิด มีผู้หามคนอัมพาตคนหนึ่งนอนบนที่นอน และเขาหาช่องที่จะหามคนอัมพาตนั้นเข้ามาวางตรงพระพักตร์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 19, 'เมื่อหาช่องเอาเข้ามาไม่ได้เพราะคนมาก เขาจึงขึ้นไปบนดาดฟ้าหลังคาบ้านหย่อนคนอัมพาตลงมา ทั้งที่นอนตามช่องกระเบื้องตรงกลางหมู่คนต่อพระพักตร์พระเยซู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 20, 'เมื่อพระองค์ทอดพระเนตรเห็นความเชื่อของเขาทั้งหลาย พระองค์จึงตรัสกับคนอัมพาตว่า “บุรุษเอ๋ย บาปของเจ้าได้รับการอภัยแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 21, 'ฝ่ายพวกธรรมาจารย์และพวกฟาริสีเริ่มคิดในใจว่า “คนนี้ที่พูดหมิ่นประมาทเป็นผู้ใดเล่า ใครจะยกความผิดบาปได้เว้นแต่พระเจ้าเท่านั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 22, 'แต่เมื่อพระเยซูทรงทราบความคิดของเขา พระองค์จึงตรัสแก่เขาว่า “ไฉนท่านทั้งหลายจึงคิดในใจอย่างนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 23, 'ที่จะว่า ‘บาปของเจ้าได้รับการอภัยแล้ว’ หรือจะว่า ‘จงลุกขึ้นเดินไปเถิด’ นั้น ข้างไหนจะง่ายกว่ากัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 24, 'แต่เพื่อท่านทั้งหลายจะได้รู้ว่า บุตรมนุษย์มีฤทธิ์อํานาจในโลกที่จะโปรดยกความผิดบาปได้” (พระองค์จึงตรัสสั่งคนอัมพาตว่า) “เราสั่งเจ้าว่า จงลุกขึ้นยกที่นอนไปบ้านของเจ้าเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 25, 'ในทันใดนั้น เขาจึงลุกขึ้นต่อหน้าคนทั้งปวง ยกที่นอนซึ่งเขาได้นอนนั้น กลับไปบ้านของตน พลางร้องสรรเสริญพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 26, 'คนทั้งปวงก็อัศจรรย์ใจและได้สรรเสริญพระเจ้า ต่างเต็มไปด้วยความกลัวและพูดว่า “วันนี้เราได้เห็นสิ่งแปลกประหลาด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 27, 'ภายหลังเหตุการณ์เหล่านี้พระองค์ได้เสด็จออกไป และทอดพระเนตรเห็นคนเก็บภาษีคนหนึ่ง ชื่อเลวีนั่งอยู่ที่ด่านเก็บภาษี พระองค์จึงตรัสกับเขาว่า “จงตามเรามาเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 28, 'เขาก็ละทิ้งสิ่งสารพัด ลุกขึ้นตามพระองค์ไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 29, 'เลวีได้จัดให้มีการเลี้ยงใหญ่ในเรือนของตนเพื่อเป็นเกียรติยศแด่พระองค์ มีคนมากมายเป็นคนเก็บภาษีและคนอื่นๆมาเอนกายลงรับประทานด้วยกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 30, 'ฝ่ายพวกธรรมาจารย์ของเขา และพวกฟาริสีกระซิบบ่นติพวกสาวกของพระองค์ว่า “เหตุไฉนพวกท่านมากินและดื่มร่วมกับพวกเก็บภาษีและพวกคนบาป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 31, 'พระเยซูตรัสตอบเขาว่า “คนปกติไม่ต้องการหมอ แต่คนเจ็บต้องการหมอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 32, 'เรามิได้มาเพื่อจะเรียกคนที่เห็นว่าตัวชอบธรรม แต่มาเรียกคนบาปให้กลับใจเสียใหม่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 33, 'เขาทั้งหลายทูลพระองค์ว่า “ทําไมพวกศิษย์ของยอห์นถืออดอาหารเนืองๆและอธิษฐานอ้อนวอน และศิษย์ของพวกฟาริสีก็ถือเหมือนกัน แต่สาวกของท่านกินและดื่ม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 34, 'ฝ่ายพระองค์ตรัสแก่เขาว่า “ท่านจะให้สหายของเจ้าบ่าวอดอาหารเมื่อเจ้าบ่าวยังอยู่กับเขากระนั้นหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 35, 'แต่วันนั้นจะมาถึงเมื่อเจ้าบ่าวจะต้องจากสหายไป ในวันนั้นสหายจะถืออดอาหาร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 36, 'พระองค์ยังตรัสคําอุปมาข้อหนึ่งแก่เขาด้วยว่า “ไม่มีผู้ใดฉีกท่อนผ้าจากเสื้อใหม่มาปะเสื้อเก่า ถ้าทําอย่างนั้นเสื้อใหม่นั้นจะขาดเสียไป ทั้งท่อนผ้าที่เอามาจากเสื้อใหม่นั้นก็จะไม่สมกับเสื้อเก่าด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 37, 'ไม่มีผู้ใดเอาน้ําองุ่นใหม่มาใส่ในถุงหนังเก่า ถ้าทําอย่างนั้นน้ําองุ่นใหม่จะทําให้ถุงหนังเก่าขาดไป และน้ําองุ่นจะรั่ว ถุงหนังก็จะเสียไปด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 38, 'แต่น้ําองุ่นใหม่ต้องใส่ในถุงหนังใหม่ ทั้งสองจะถนอมรักษาด้วยกันได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 39, 'ไม่มีผู้ใดเมื่อดื่มน้ําองุ่นเก่าแล้ว จะอยากได้น้ําองุ่นใหม่ทันที เพราะเขาว่า ‘ของเก่านั้นก็ดีกว่า’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 1, 'ต่อมาในวันสะบาโตที่สอง หลังจากวันแรกนั้น พระองค์กําลังเสด็จไปที่ในนา และพวกสาวกของพระองค์ก็เด็ดรวงข้าวขยี้กิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 2, 'บางคนในพวกฟาริสีจึงกล่าวแก่เขาว่า “ทําไมพวกท่านจึงทําการซึ่งพระราชบัญญัติห้ามไว้ในวันสะบาโต”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 3, 'พระเยซูตรัสตอบเขาว่า “ท่านทั้งหลายยังไม่ได้อ่านเรื่องนี้อีกหรือ ที่ดาวิดได้กระทําเมื่ออดอยาก ทั้งท่านและพรรคพวกด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 4, 'คือท่านได้เข้าไปในพระนิเวศของพระเจ้า และรับประทานขนมปังหน้าพระพักตร์ทั้งให้พรรคพวกด้วย ซึ่งพระราชบัญญัติห้ามไม่ให้ใครรับประทานเว้นแต่พวกปุโรหิตเท่านั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 5, 'พระองค์จึงตรัสกับเขาว่า “บุตรมนุษย์เป็นเจ้าเป็นใหญ่เหนือวันสะบาโตด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 6, 'ต่อมาในวันสะบาโตอีกวันหนึ่ง พระองค์เสด็จเข้าไปในธรรมศาลาและสั่งสอน ที่นั่นมีชายคนหนึ่งมือขวาลีบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 7, 'ฝ่ายพวกธรรมาจารย์และพวกฟาริสีคอยดูพระองค์ว่า พระองค์จะทรงรักษาเขาในวันสะบาโตหรือไม่ เพื่อจะหาเหตุฟ้องพระองค์ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 8, 'แต่พระองค์ทรงทราบความคิดของเขา จึงตรัสแก่คนมือลีบนั้นว่า “จงลุกขึ้นมายืนอยู่ข้างหน้า” เขาก็ลุกขึ้นยืน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 9, 'แล้วพระเยซูตรัสกับเขาทั้งหลายว่า “เราจะถามท่านทั้งหลายว่า ในวันสะบาโตให้ถูกต้องตามพระราชบัญญัติควรจะทําการดีหรือทําการร้าย จะช่วยชีวิตดีหรือจะผลาญชีวิตดี”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 10, 'พระองค์จึงทอดพระเนตรดูทุกคนโดยรอบ แล้วตรัสกับชายคนนั้นว่า “จงเหยียดมือออกเถิด” เขาก็กระทําตาม และมือของเขาก็หายเป็นปกติเหมือนมืออีกข้างหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 11, 'แต่คนเหล่านั้นต่างก็มีความเดือดดาล และปรึกษากันว่าจะกระทําอย่างไรแก่พระเยซูได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 12, 'ต่อมาคราวนั้นพระองค์เสด็จไปที่ภูเขาเพื่อจะอธิษฐาน และได้อธิษฐานต่อพระเจ้าคืนยังรุ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 13, 'ครั้นรุ่งเช้าแล้วพระองค์ทรงเรียกสาวกของพระองค์ แล้วทรงเลือกสิบสองคนออกจากหมู่สาวกนั้น ที่พระองค์ทรงเรียกว่า อัครสาวก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 14, 'คือซีโมน (ที่พระองค์ทรงให้ชื่ออีกว่า เปโตร) อันดรูว์น้องชายของเปโตร ยากอบและยอห์น ฟีลิปและบารโธโลมิว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 15, 'มัทธิวและโธมัส ยากอบบุตรชายของอัลเฟอัส ซีโมนที่เรียกว่า เศโลเท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 16, 'ยูดาสน้องชายของยากอบ และยูดาสอิสคาริโอทที่เป็นผู้ทรยศพระองค์ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 17, 'แล้วพระองค์กับอัครสาวกก็ลงมายืน ณ ที่ราบแห่งหนึ่ง พร้อมกับหมู่สาวกของพระองค์ และประชาชนเป็นอันมากซึ่งมาจากทั่วแคว้นยูเดีย กรุงเยรูซาเล็ม และจากตําบลชายทะเลในเขตเมืองไทระและเมืองไซดอน เพื่อจะฟังพระองค์และให้พระองค์ทรงรักษาโรคของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 18, 'และบรรดาคนที่ต้องทนทุกข์เพราะผีโสโครก เขาก็ได้รับการรักษาให้หายด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 19, 'ประชาชนต่างก็พยายามที่จะถูกต้องพระองค์ เพราะว่ามีฤทธิ์ซ่านออกจากพระองค์รักษาเขาให้หายทุกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 20, 'พระองค์ทอดพระเนตรแลดูเหล่าสาวกของพระองค์ตรัสว่า “ท่านทั้งหลายที่เป็นคนยากจนก็เป็นสุข เพราะว่าอาณาจักรของพระเจ้าเป็นของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 21, 'ท่านทั้งหลายที่อดอยากเวลานี้ก็เป็นสุข เพราะว่าท่านจะได้อิ่มหนํา ท่านทั้งหลายที่ร้องไห้เวลานี้ก็เป็นสุข เพราะว่าท่านจะได้หัวเราะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 22, 'ท่านทั้งหลายจะเป็นสุขเมื่อคนทั้งหลายจะเกลียดชังท่าน และจะไล่ท่านออกจากพวกเขา และจะประณามท่าน และจะเหยียดชื่อของท่านว่าเป็นคนชั่วช้า เพราะท่านเห็นแก่บุตรมนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 23, 'ในวันนั้นท่านทั้งหลายจงชื่นชม และเต้นโลดด้วยความยินดี เพราะ ดูเถิด บําเหน็จของท่านมีบริบูรณ์ในสวรรค์ เพราะว่าบรรพบุรุษของเขาได้กระทําอย่างนั้นแก่พวกศาสดาพยากรณ์เหมือนกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 24, 'แต่วิบัติแก่เจ้าทั้งหลายที่มั่งมี เพราะว่าเจ้าได้รับสิ่งที่เล้าโลมใจแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 25, 'วิบัติแก่เจ้าทั้งหลายที่อิ่มหนําแล้ว เพราะว่าเจ้าจะอดอยาก วิบัติแก่เจ้าทั้งหลายที่หัวเราะเวลานี้ เพราะว่าเจ้าจะเป็นทุกข์และร้องไห้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 26, 'วิบัติแก่เจ้าทั้งหลายเมื่อคนทั้งหลายจะยอว่าเจ้าดี เพราะบรรพบุรุษของเขาได้กระทําอย่างนั้นแก่ผู้พยากรณ์เท็จเหมือนกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 27, 'แต่เราบอกท่านทั้งหลายที่กําลังฟังอยู่ว่า จงรักศัตรูของท่าน จงทําดีแก่ผู้ที่เกลียดชังท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 28, 'จงอวยพรแก่คนที่แช่งด่าท่าน จงอธิษฐานเพื่อคนที่เคี่ยวเข็ญท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 29, 'ผู้ใดตบแก้มของท่านข้างหนึ่ง จงหันอีกข้างหนึ่งให้เขาด้วย และผู้ใดริบเอาเสื้อคลุมของท่านไป ถ้าเขาจะเอาเสื้อด้วยก็อย่าหวงห้าม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 30, 'จงให้แก่ทุกคนที่ขอจากท่าน และถ้าใครได้ริบเอาของของท่านไป อย่าทวงเอาคืน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 31, 'จงปฏิบัติต่อผู้อื่นอย่างที่ท่านปรารถนาให้เขาปฏิบัติต่อท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 32, 'แม้ว่าท่านทั้งหลายรักผู้ที่รักท่าน จะนับว่าเป็นคุณอะไรแก่ท่าน ถึงแม้คนบาปก็ยังรักผู้ที่รักเขาเหมือนกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 33, 'ถ้าท่านทั้งหลายทําดีแก่ผู้ที่ทําดีแก่ท่าน จะนับว่าเป็นคุณอะไรแก่ท่าน เพราะว่าคนบาปก็กระทําเหมือนกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 34, 'ถ้าท่านทั้งหลายให้ยืมเฉพาะแต่ผู้ที่ท่านหวังจะได้คืนจากเขาอีก จะนับว่าเป็นคุณอะไรแก่ท่าน ถึงแม้คนบาปก็ยังให้คนบาปยืมโดยหวังว่าจะได้รับคืนจากเขาอีกเท่ากัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 35, 'แต่จงรักศัตรูของท่านทั้งหลาย และทําการดีต่อเขา จงให้เขายืมโดยไม่หวังที่จะได้คืนอีก บําเหน็จของท่านทั้งหลายจึงจะมีบริบูรณ์ และท่านทั้งหลายจะเป็นบุตรของผู้สูงสุด เพราะว่าพระองค์ยังทรงโปรดแก่คนอกตัญญูและคนชั่ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 36, 'เหตุฉะนั้น ท่านทั้งหลายจงมีความเมตตากรุณา เหมือนอย่างพระบิดาของท่านมีพระทัยเมตตากรุณา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 37, 'อย่าวินิจฉัยโทษเขา และท่านทั้งหลายจะไม่ได้ถูกวินิจฉัยโทษ อย่ากล่าวโทษเขา และท่านทั้งหลายจะไม่ถูกกล่าวโทษ จงยกโทษให้เขา และท่านจะได้รับการอภัยโทษ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 38, 'จงให้ และท่านจะได้รับด้วย และในตักของท่านเขาจะตวงด้วยทะนานถ้วนยัดสั่นแน่นพูนล้นใส่ให้ เพราะว่าท่านจะตวงให้ด้วยทะนานอันใด จะตวงให้ท่านด้วยทะนานอันนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 39, 'พระองค์ตรัสกับเขาทั้งหลายเป็นคําอุปมาด้วยว่า “คนตาบอดจะนําทางคนตาบอดได้หรือ ทั้งสองจะไม่ตกลงไปในบ่อหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 40, 'ศิษย์ไม่ใหญ่กว่าครู แต่ศิษย์ทุกคนที่ได้รับการฝึกสอนครบแล้วก็จะเป็นเหมือนครูของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 41, 'เหตุไฉนท่านมองดูผงที่ในตาพี่น้องของท่าน แต่ไม่ยอมพิจารณาไม้ทั้งท่อนที่อยู่ในตาของท่านเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 42, 'เหตุไฉนท่านจึงพูดกับพี่น้องของท่านว่า ‘พี่น้องเอ๋ย ให้เราเขี่ยผงออกจากตาของท่าน’ แต่ที่จริงท่านเองยังไม่เห็นไม้ทั้งท่อนที่อยู่ในตาของท่าน ท่านคนหน้าซื่อใจคด จงชักไม้ทั้งท่อนออกจากตาของท่านก่อน แล้วท่านจะเห็นได้ถนัดจึงจะเขี่ยผงออกจากตาพี่น้องของท่านได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 43, 'ด้วยว่าต้นไม้ดีย่อมไม่เกิดผลเลว หรือต้นไม้เลวย่อมไม่เกิดผลดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 44, 'เพราะว่าจะรู้จักต้นไม้ทุกต้นได้ก็เพราะผลของมัน เพราะว่าเขาย่อมไม่เก็บผลมะเดื่อจากต้นไม้มีหนาม หรือย่อมไม่เก็บผลองุ่นจากพุ่มไม้หนาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 45, 'คนดีก็ย่อมเอาของดีออกจากคลังดีแห่งใจของตน และคนชั่วก็ย่อมเอาของชั่วออกจากคลังชั่วแห่งใจของตน ด้วยใจเต็มด้วยอะไร ปากก็พูดออกมาอย่างนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 46, 'เหตุไฉนท่านทั้งหลายจึงเรียกเราว่า ‘พระองค์เจ้าข้า พระองค์เจ้าข้า’ แต่ไม่กระทําตามที่เราบอกนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 47, 'ทุกคนที่มาหาเราและฟังคําของเรา และกระทําตามคํานั้น เราจะแจ้งให้ท่านทั้งหลายรู้ว่า เขาเปรียบเหมือนผู้ใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 48, 'เขาเปรียบเหมือนคนหนึ่งที่สร้างเรือน เขาขุดลึกลงไป แล้วตั้งรากบนศิลา และเมื่อน้ํามาท่วม กระแสน้ําไหลเชี่ยวกระทบกระทั่ง แต่ทําให้เรือนนั้นหวั่นไหวไม่ได้ เพราะได้ตั้งรากบนศิลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 49, 'ส่วนคนที่ได้ยินและมิได้กระทําตาม เปรียบเหมือนคนหนึ่งที่สร้างเรือนบนดินไม่ก่อราก เมื่อกระแสน้ําไหลเชี่ยวกระทบกระทั่ง เรือนนั้นก็พังทลายลงทันที และความพินาศของเรือนนั้นก็ใหญ่ยิ่งนัก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 1, 'เมื่อพระองค์ตรัสคําเหล่านั้นให้คนทั้งหลายฟังเสร็จแล้ว พระองค์จึงเสด็จเข้าไปในเมืองคาเปอรนาอุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 2, 'มีผู้รับใช้ของนายร้อยคนหนึ่งที่นายรักมากป่วยเกือบจะตายแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 3, 'เมื่อนายร้อยได้ยินถึงพระเยซู จึงใช้ผู้ใหญ่บางคนของพวกยิวให้ไปอ้อนวอนเชิญพระองค์เสด็จมารักษาผู้รับใช้ของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 4, 'เมื่อเขาเหล่านั้นมาถึงพระเยซูแล้ว เขาก็อ้อนวอนพระองค์ด้วยใจร้อนรนว่า “นายร้อยนั้นเป็นคนสมควรที่พระองค์จะกระทําการนั้นให้ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 5, 'เพราะว่าท่านรักชนชาติของเราและท่านได้สร้างธรรมศาลาให้เรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 6, 'พระเยซูจึงเสด็จไปกับเขา เมื่อพระองค์ไปเกือบจะถึงบ้านแล้ว นายร้อยจึงใช้เพื่อนฝูงไปหาพระองค์ทูลว่า “พระองค์เจ้าข้า อย่าลําบากเลย เพราะว่าข้าพระองค์เป็นคนไม่สมควรที่จะรับเสด็จพระองค์เข้าใต้ชายคาของข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 7, 'เพราะเหตุนั้น ข้าพระองค์จึงคิดเห็นว่าไม่สมควรที่ข้าพระองค์จะไปหาพระองค์ด้วย แต่ขอพระองค์ทรงตรัสสั่ง และผู้รับใช้ของข้าพระองค์ก็จะหายโรค');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 8, 'ด้วยว่าข้าพระองค์อยู่ใต้วินัยทหาร แต่ก็ยังมีทหารอยู่ใต้บังคับบัญชาของข้าพระองค์ ข้าพระองค์จะบอกแก่คนนี้ว่า ‘ไป’ เขาก็ไป บอกแก่คนนั้นว่า ‘มา’ เขาก็มา บอกผู้รับใช้ของข้าพระองค์ว่า ‘จงทําสิ่งนี้’ เขาก็ทํา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 9, 'เมื่อพระเยซูทรงได้ยินคําเหล่านั้นแล้ว ก็ประหลาดพระทัยด้วยคนนั้น จึงทรงเหลียวหลังตรัสกับประชาชนที่ตามพระองค์มาว่า “เราบอกท่านทั้งหลายว่า แม้ในพวกอิสราเอล เราไม่เคยพบความเชื่อมากเท่านี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 10, 'ฝ่ายคนที่รับใช้มานั้นเมื่อกลับไปถึงบ้านก็ได้เห็นผู้รับใช้ที่ป่วยนั้นหายเป็นปกติแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 11, 'ต่อมาในวันรุ่งขึ้นพระองค์เสด็จไปยังเมืองหนึ่งชื่อนาอิน เหล่าสาวกของพระองค์กับคนเป็นอันมากก็ไปด้วยกันกับพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 12, 'เมื่อพระองค์มาใกล้ประตูเมืองนั้น ดูเถิด มีคนหามศพชายหนุ่มคนหนึ่งมา เป็นบุตรชายคนเดียวของแม่ และนางก็เป็นหญิงม่าย ชาวเมืองเป็นอันมากมากับหญิงนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 13, 'เมื่อองค์พระผู้เป็นเจ้าได้ทอดพระเนตรเห็นมารดานั้น พระองค์ทรงเมตตากรุณาเขาและตรัสแก่เขาว่า “อย่าร้องไห้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 14, 'แล้วพระองค์เสด็จเข้าไปใกล้ถูกต้องโลง คนหามศพนั้นก็หยุดยืนอยู่ พระองค์จึงตรัสว่า “ชายหนุ่มเอ๋ย เราสั่งเจ้าว่า ลุกขึ้นเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 15, 'คนที่ตายนั้นก็ลุกขึ้นนั่งเริ่มพูด พระองค์จึงทรงมอบชายหนุ่มให้แก่มารดาของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 16, 'ฝ่ายคนทั้งปวงมีความกลัวและเขาสรรเสริญพระเจ้าว่า “ท่านศาสดาพยากรณ์ผู้ยิ่งใหญ่ได้เกิดขึ้นท่ามกลางเรา” และ “พระเจ้าได้เสด็จมาเยี่ยมเยียนชนชาติของพระองค์แล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 17, 'และกิตติศัพท์ของพระองค์ได้เลื่องลือไปตลอดทั่วแคว้นยูเดีย และทั่วแว่นแคว้นล้อมรอบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 18, 'ฝ่ายพวกศิษย์ของยอห์นก็ได้เล่าเหตุการณ์ทั้งปวงนั้นให้ท่านฟัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 19, 'ยอห์นจึงเรียกศิษย์ของท่านสองคน ใช้เขาไปหาพระเยซูทูลถามว่า “ท่านเป็นผู้ที่จะมานั้นหรือ หรือเราจะต้องคอยผู้อื่น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 20, 'เมื่อคนทั้งสองนั้นมาถึงพระองค์แล้วเขาทูลว่า “ยอห์นผู้ให้รับบัพติศมาใช้ข้าพเจ้ามาหาท่านให้ถามว่า ‘ท่านเป็นผู้ที่จะมานั้นหรือ หรือเราจะต้องคอยผู้อื่น’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 21, 'ในเวลานั้น พระองค์ได้ทรงรักษาคนเป็นอันมากให้หายจากความเจ็บป่วยและโรคต่างๆและให้พ้นจากวิญญาณชั่ว และคนตาบอดหลายคนพระองค์ได้ทรงรักษาให้เห็นได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 22, 'แล้วพระเยซูตรัสตอบศิษย์สองคนนั้นว่า “จงไปแจ้งแก่ยอห์นตามซึ่งท่านได้เห็นและได้ยินคือว่า คนตาบอดก็หายบอด คนง่อยเดินได้ คนโรคเรื้อนหายสะอาด คนหูหนวกได้ยิน คนตายแล้วเป็นขึ้นมา และข่าวประเสริฐก็ประกาศแก่คนอนาถา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 23, 'บุคคลผู้ใดไม่เห็นว่าเราเป็นอุปสรรค ผู้นั้นเป็นสุข”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 24, 'เมื่อผู้ส่งข่าวทั้งสองของยอห์นไปแล้ว พระองค์จึงตั้งต้นตรัสกับประชาชนถึงยอห์นว่า “ท่านทั้งหลายได้ออกไปในถิ่นทุรกันดารเพื่อดูอะไร ดูต้นอ้อไหวโดยถูกลมพัดหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 25, 'แต่ท่านทั้งหลายได้ไปดูอะไร ดูคนนุ่งห่มผ้าเนื้ออ่อนนิ่มหรือ ดูเถิด คนนุ่งห่มผ้างดงามและอยู่อย่างดีวิเศษย่อมอยู่ในราชสํานัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 26, 'แต่ท่านทั้งหลายออกไปดูอะไร ดูศาสดาพยากรณ์หรือ แน่ทีเดียว เราบอกท่านว่า ยิ่งกว่าศาสดาพยากรณ์อีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 27, 'คือผู้นั้นเองที่ได้เขียนถึงแล้วว่า ‘ดูเถิด เราใช้ทูตของเราไปข้างหน้าท่าน ผู้นั้นจะเตรียมมรรคาของท่านไว้ข้างหน้าท่าน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 28, 'เราบอกท่านทั้งหลายว่า ในบรรดาคนที่บังเกิดจากผู้หญิงมานั้น ไม่มีศาสดาพยากรณ์ผู้ใดใหญ่กว่ายอห์นผู้ให้รับบัพติศมา แต่ว่าผู้ต่ําต้อยที่สุดในอาณาจักรของพระเจ้าก็ใหญ่กว่ายอห์นเสียอีก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 29, 'ฝ่ายคนทั้งปวงเมื่อได้ยิน รวมทั้งพวกเก็บภาษีด้วย ก็ได้รับว่าพระเจ้ายุติธรรมโดยที่เขาได้รับบัพติศมาของยอห์นแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 30, 'แต่พวกฟาริสีและพวกนักกฎหมายปฏิเสธพระประสงค์ของพระเจ้าสําหรับเขา โดยที่มิได้รับบัพติศมาจากยอห์น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 31, 'และองค์พระผู้เป็นเจ้าตรัสว่า “เหตุฉะนั้นเราจะเปรียบคนยุคนี้เหมือนกับอะไรดี และเขาเหมือนอะไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 32, 'เปรียบเหมือนเด็กนั่งที่กลางตลาดร้องแก่เพื่อนว่า ‘พวกฉันได้เป่าปี่ให้พวกเธอ และเธอมิได้เต้นรํา พวกฉันได้พิลาปร่ําไห้ให้แก่พวกเธอ และพวกเธอมิได้ร้องไห้’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 33, 'ด้วยว่ายอห์นผู้ให้รับบัพติศมาก็ไม่ได้รับประทานขนมปังหรือดื่มน้ําองุ่น และท่านทั้งหลายว่า ‘เขามีผีเข้าสิงอยู่’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 34, 'ฝ่ายบุตรมนุษย์มาทั้งกินและดื่ม และท่านทั้งหลายว่า ‘ดูเถิด นี่เป็นคนกินเติบและดื่มน้ําองุ่นมาก เป็นมิตรสหายกับพวกคนเก็บภาษีและพวกคนบาป’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 35, 'แต่พระปัญญาก็ปรากฏว่าชอบธรรมแล้วโดยบรรดาผลแห่งพระปัญญานั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 36, 'มีคนหนึ่งในพวกฟาริสีเชิญพระองค์ไปเสวยพระกระยาหารกับเขา พระองค์ก็เสด็จเข้าไปในเรือนของคนฟาริสีนั้น แล้วเอนพระกายลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 37, 'และดูเถิด มีผู้หญิงคนหนึ่งในเมืองนั้นซึ่งเป็นหญิงชั่ว เมื่อรู้ว่าพระเยซูทรงเอนพระกายลงเสวยอยู่ในบ้านของคนฟาริสีนั้น นางจึงถือผอบน้ํามันหอม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 38, 'มายืนอยู่ข้างหลังใกล้พระบาทของพระองค์ เริ่มร้องไห้น้ําตาไหลชําระพระบาทและเอาผมเช็ด จุบพระบาทของพระองค์ และชโลมพระบาทด้วยน้ํามันหอมนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 39, 'ฝ่ายคนฟาริสีที่ได้เชิญพระองค์เมื่อเห็นแล้วก็นึกในใจว่า “ถ้าท่านนี้เป็นศาสดาพยากรณ์ก็จะรู้ว่า หญิงผู้นี้ที่ถูกต้องกายของท่านเป็นผู้ใดและเป็นคนอย่างไร เพราะนางเป็นคนชั่ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 40, 'ฝ่ายพระเยซูตรัสตอบเขาว่า “ซีโมนเอ๋ย เรามีอะไรจะพูดกับท่านบ้าง” เขาทูลว่า “ท่านอาจารย์เจ้าข้า เชิญพูดไปเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 41, 'พระองค์จึงตรัสว่า “เจ้าหนี้คนหนึ่งมีลูกหนี้สองคน คนหนึ่งเป็นหนี้เงินห้าร้อยเหรียญเดนาริอัน อีกคนหนึ่งเป็นหนี้เงินห้าสิบเหรียญ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 42, 'เมื่อเขาไม่มีอะไรจะใช้หนี้แล้ว ท่านจึงโปรดยกหนี้ให้เขาทั้งสองคน เพราะฉะนั้นจงบอกเราว่า ในสองคนนั้น คนไหนจะรักเจ้าหนี้มากกว่า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 43, 'ซีโมนจึงทูลตอบว่า “ข้าพเจ้าเห็นว่า คนที่เจ้าหนี้ได้โปรดยกหนี้ให้มากกว่า” พระองค์จึงตรัสกับเขาว่า “ท่านคิดเห็นถูกแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 44, 'พระองค์จึงทรงเหลียวหลังดูผู้หญิงนั้น และตรัสแก่ซีโมนว่า “ท่านเห็นผู้หญิงนี้หรือ เราได้เข้ามาในบ้านของท่าน ท่านมิได้ให้น้ําล้างเท้าของเรา แต่นางได้เอาน้ําตาชําระเท้าของเรา และได้เอาผมของตนเช็ด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 45, 'ท่านมิได้จุบเรา แต่ผู้หญิงนี้ตั้งแต่เราเข้ามามิได้หยุดจุบเท้าของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 46, 'ท่านมิได้เอาน้ํามันชโลมศีรษะของเรา แต่นางได้เอาน้ํามันหอมชโลมเท้าของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 47, 'เหตุฉะนั้น เราบอกท่านว่า ความผิดบาปของนางซึ่งมีมากได้โปรดยกเสียแล้วเพราะนางรักมาก แต่ผู้ที่ได้รับการยกโทษน้อย ผู้นั้นก็รักน้อย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 48, 'พระองค์จึงตรัสแก่นางว่า “ความผิดบาปของเจ้าโปรดยกเสียแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 49, 'ฝ่ายคนทั้งหลายที่เอนกายอยู่ด้วยกันกับพระองค์ เริ่มนึกในใจว่า “คนนี้เป็นใครแม้ความผิดบาปก็ยกให้ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 50, 'พระองค์จึงตรัสแก่ผู้หญิงนั้นว่า “ความเชื่อของเจ้าได้ทําให้เจ้ารอด จงไปเป็นสุขเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 1, 'ต่อมาภายหลังพระองค์ก็เสด็จไปตามทุกบ้านทุกเมือง ทรงประกาศข่าวประเสริฐแห่งอาณาจักรของพระเจ้า สาวกสิบสองคนนั้นก็อยู่กับพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 2, 'พร้อมกับผู้หญิงบางคนที่มีวิญญาณชั่วออกจากนางและที่หายโรคต่างๆ คือมารีย์ที่เรียกว่าชาวมักดาลา ที่ได้ทรงขับผีออกจากนางเจ็ดผี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 3, 'และโยอันนาภรรยาของคูซา ต้นเรือนของเฮโรด และซูซันนา และผู้หญิงอื่นๆหลายคนที่เคยปรนนิบัติพระองค์ด้วยการถวายสิ่งของของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 4, 'เมื่อประชาชนเป็นอันมากอยู่พร้อมกัน และคนกําลังมาหาพระองค์จากทุกเมือง พระองค์จึงตรัสเป็นคําอุปมาว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 5, '“มีผู้หว่านคนหนึ่งออกไปหว่านเมล็ดพืชของตน และเมื่อเขาหว่าน เมล็ดพืชนั้นก็ตกตามหนทางบ้าง ถูกเหยียบย่ํา และนกในอากาศมากินเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 6, 'บ้างก็ตกที่หิน และเมื่องอกขึ้นแล้วก็เหี่ยวแห้งไปเพราะที่ไม่ชื้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 7, 'บ้างก็ตกที่กลางต้นหนาม ต้นหนามก็งอกขึ้นมาด้วยปกคลุมเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 8, 'บ้างก็ตกที่ดินดี จึงงอกขึ้นเกิดผลร้อยเท่า” ครั้นพระองค์ตรัสอย่างนั้นแล้ว จึงทรงร้องว่า “ใครมีหูฟังได้ จงฟังเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 9, 'เหล่าสาวกจึงทูลถามพระองค์ว่า “คําอุปมานั้นหมายความว่าอย่างไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 10, 'พระองค์จึงตรัสว่า “ข้อความลึกลับแห่งอาณาจักรของพระเจ้าทรงโปรดให้ท่านทั้งหลายรู้ได้ แต่สําหรับคนอื่นนั้นได้ให้เป็นคําอุปมา เพื่อเมื่อเขาดูก็ไม่เห็น และเมื่อเขาได้ยินก็ไม่เข้าใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 11, 'คําอุปมานั้นก็อย่างนี้ เมล็ดพืชนั้นได้แก่พระวจนะของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 12, 'ที่ตกตามหนทางได้แก่คนเหล่านั้นที่ได้ยิน แล้วพญามารมาชิงเอาพระวจนะจากใจของเขา เพื่อไม่ให้เขาเชื่อและรอดได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 13, 'ซึ่งตกที่หินนั้นได้แก่คนเหล่านั้นที่ได้ยินแล้วก็รับพระวจนะนั้นด้วยความปรีดี แต่ไม่มีราก เชื่อได้แต่ชั่วคราว เมื่อถูกทดลองเขาก็หลงเสียไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 14, 'ที่ตกกลางหนามนั้นได้แก่คนเหล่านั้นที่ได้ยินแล้วออกไป และความปรารภปรารมย์ ทรัพย์สมบัติ ความสนุกสนานแห่งชีวิตนี้ก็ปกคลุมเขา ผลของเขาจึงไม่เติบโต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 15, 'และซึ่งตกที่ดินดีนั้น ได้แก่คนเหล่านั้นที่ได้ยินพระวจนะด้วยใจซื่อสัตย์และใจที่ดีแล้วก็จดจําไว้ จึงเกิดผลด้วยความเพียร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 16, 'ไม่มีผู้ใดเมื่อจุดเทียนแล้วจะเอาภาชนะครอบไว้ หรือวางไว้ใต้เตียง แต่ตั้งไว้ที่เชิงเทียน เพื่อคนทั้งหลายที่เข้ามาจะเห็นแสงสว่างได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 17, 'ด้วยว่าไม่มีสิ่งใดที่ซ่อนไว้ซึ่งจะไม่ปรากฏแจ้ง และไม่มีสิ่งใดที่ปิดบังไว้ซึ่งจะไม่รู้จะไม่ต้องแพร่งพราย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 18, 'เหตุฉะนั้น ท่านทั้งหลายจะฟังอย่างไรก็จงเอาใจจดจ่อ เพราะว่าผู้ใดมีอยู่แล้วจะทรงเพิ่มเติมให้แก่ผู้นั้นอีก แต่ผู้ใดไม่มี แม้ซึ่งเขาคิดว่ามีอยู่นั้นจะทรงเอาไปจากเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 19, 'ครั้งนั้นมารดาและพวกน้องชายของพระองค์มาหาพระองค์ แต่เข้าไปถึงพระองค์ไม่ได้เพราะคนมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 20, 'มีคนทูลพระองค์ว่า “มารดาและน้องชายของพระองค์ยืนอยู่ข้างนอกปรารถนาจะพบพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 21, 'แต่พระองค์ตรัสตอบเขาว่า “มารดาของเรา และพี่น้องของเราคือคนเหล่านั้นที่ได้ฟังพระวจนะของพระเจ้าและกระทําตาม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 22, 'อยู่มาวันหนึ่งพระองค์เสด็จลงเรือกับเหล่าสาวกของพระองค์ แล้วพระองค์ตรัสแก่เขาว่า “ให้เราข้ามทะเลสาบไปฟากข้างโน้น” เขาก็ถอยเรือออกไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 23, 'เมื่อกําลังแล่นไปพระองค์ทรงบรรทมหลับ และบังเกิดพายุกล้ากลางทะเลสาบ น้ําเข้าเรืออยู่น่ากลัวจะมีอันตราย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 24, 'เขาจึงมาปลุกพระองค์ว่า “อาจารย์เจ้าข้า อาจารย์เจ้าข้า ข้าพเจ้าทั้งหลายกําลังจะพินาศอยู่แล้ว” พระองค์จึงทรงตื่นขึ้นห้ามลมและคลื่น แล้วคลื่นลมก็หยุดเงียบสงบทีเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 25, 'พระองค์จึงตรัสแก่เขาว่า “ความเชื่อของเจ้าอยู่ที่ไหน” เขาเหล่านั้นกลัวและประหลาดใจพูดกันว่า “ท่านผู้นี้เป็นผู้ใดจึงสั่งบังคับลมและน้ําได้ และลมกับน้ํานั้นก็เชื่อฟังท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 26, 'เขาแล่นไปถึงแขวงชาวเมืองกาดาราที่อยู่ตรงข้ามกาลิลี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 27, 'เมื่อพระองค์เสด็จขึ้นบกแล้ว มีชายคนหนึ่งจากเมืองนั้นมาพบพระองค์ คนนั้นมีผีเข้าสิงอยู่นานแล้ว และมิได้สวมเสื้อ มิได้อยู่เรือน แต่อยู่ตามอุโมงค์ฝังศพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 28, 'ครั้นเห็นพระเยซูเขาก็โห่ร้อง และกราบลงตรงพระพักตร์พระองค์ ร้องเสียงดังว่า “ข้าแต่พระเยซูบุตรของพระเจ้าสูงสุด ข้าพระองค์เกี่ยวข้องอะไรกับท่านเล่า ขอพระองค์อย่าทรมานข้าพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 29, '(ที่พูดเช่นนี้ก็เพราะพระองค์ได้สั่งผีโสโครกให้ออกมาจากตัวคนนั้น ด้วยว่าผีนั้นแผลงฤทธิ์ในตัวเขาบ่อยๆ และเขาถูกจําด้วยโซ่ตรวน แต่เขาได้หักเครื่องจํานั้นเสีย แล้วผีก็นําเขาไปในที่เปลี่ยว)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 30, 'ฝ่ายพระเยซูตรัสถามมันว่า “เจ้าชื่ออะไร” มันทูลตอบว่า “ชื่อกอง” ด้วยว่ามีผีหลายตนเข้าสิงอยู่ในตัวเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 31, 'ผีนั้นจึงอ้อนวอนขอพระองค์มิให้สั่งให้มันลงไปยังนรกขุมลึก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 32, 'ตําบลนั้นมีสุกรฝูงใหญ่กําลังหากินอยู่ที่ภูเขา ผีเหล่านั้นได้อ้อนวอนพระองค์ขออนุญาตให้มันเข้าสิงในฝูงสุกร พระองค์ก็ทรงอนุญาต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 33, 'ผีเหล่านั้นจึงออกมาจากคนนั้น แล้วเข้าอยู่ในตัวสุกร สุกรทั้งฝูงก็วิ่งพุ่งกระโดดจากหน้าผาชันลงไปในทะเลสาบสําลักน้ําตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 34, 'ฝ่ายคนเลี้ยงสุกรเมื่อเห็นเหตุการณ์ที่เกิดขึ้น ต่างก็หนีไปเล่าเรื่องนั้นทั้งในเมืองและนอกเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 35, 'คนทั้งหลายจึงออกไปดูเหตุการณ์ที่เกิดขึ้น และเมื่อเขามาถึงพระเยซู ก็เห็นคนนั้นที่มีผีออกจากตัวนุ่งห่มผ้ามีสติอารมณ์ดี นั่งใกล้พระบาทพระเยซู เขาทั้งหลายก็พากันกลัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 36, 'ฝ่ายคนทั้งหลายที่ได้เห็น ก็เล่าให้เขาทั้งหลายฟังถึงเรื่องคนที่ผีสิงได้หายปกติอย่างไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 37, 'ชาวเมืองกาดาราและคนทั้งปวงที่อยู่ตามชนบทโดยรอบ จึงอ้อนวอนพระองค์ให้ไปเสียจากเขา เพราะว่าเขากลัวยิ่งนัก พระองค์จึงเสด็จลงเรือกลับไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 38, 'คนที่ผีออกจากตัวนั้นอ้อนวอนขอติดตามพระองค์ แต่พระเยซูส่งเขาออกไป ตรัสสั่งว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 39, '“จงกลับไปบ้านเรือนของตัว และบอกถึงเรื่องการใหญ่ซึ่งพระเจ้าได้ทรงกระทําแก่เจ้า” แล้วคนนั้นก็ไปประกาศแก่คนทั้งเมืองถึงเหตุการณ์ใหญ่ยิ่งที่พระเยซูได้ทรงกระทําแก่ตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 40, 'ต่อมาเมื่อพระเยซูเสด็จกลับมาแล้ว ประชาชนก็ต้อนรับพระองค์ด้วยความยินดี เพราะเขาทั้งหลายคอยท่าพระองค์อยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 41, 'ดูเถิด มีชายคนหนึ่งชื่อไยรัส เป็นนายธรรมศาลา มากราบลงที่พระบาทพระเยซู อ้อนวอนพระองค์ให้เสด็จเข้าไปในเรือนของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 42, 'เพราะว่าเขามีบุตรสาวคนเดียว อายุประมาณสิบสองปี และบุตรสาวนั้นนอนป่วยอยู่เกือบจะตาย เมื่อพระองค์เสด็จไปนั้น ประชาชนเบียดเสียดพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 43, 'มีผู้หญิงคนหนึ่งเป็นโรคตกเลือดได้สิบสองปีมาแล้ว และได้ใช้ทรัพย์ทั้งหมดของเธอเป็นค่าหมอ ไม่มีผู้ใดรักษาให้หายได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 44, 'ผู้หญิงนั้นแอบมาข้างหลังถูกต้องชายฉลองพระองค์ และในทันใดนั้นเลือดที่ตกก็หยุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 45, 'พระเยซูจึงตรัสถามว่า “ใครได้ถูกต้องเรา” เมื่อคนทั้งหลายได้ปฏิเสธ เปโตรกับคนที่อยู่ด้วยกันกับเขาจึงทูลว่า “อาจารย์เจ้าข้า ก็เป็นเพราะประชาชนเบียดเสียดพระองค์ และพระองค์ยังทรงถามอีกหรือว่า ‘ใครได้ถูกต้องเรา’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 46, 'แต่พระเยซูตรัสว่า “มีผู้หนึ่งได้ถูกต้องเรา เพราะเรารู้สึกว่าฤทธิ์ได้ซ่านออกจากตัวเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 47, 'เมื่อผู้หญิงนั้นเห็นว่าจะซ่อนตัวไว้ไม่ได้แล้ว เธอก็เข้ามาตัวสั่นกราบลงตรงพระพักตร์พระองค์ ทูลพระองค์ต่อหน้าคนทั้งปวงว่า เธอได้ถูกต้องพระองค์เพราะเหตุอะไร และได้หายโรคในทันใดนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 48, 'พระองค์จึงตรัสแก่เขาว่า “ลูกสาวเอ๋ย จงมีกําลังใจเถิด ความเชื่อของเจ้าได้กระทําให้เจ้าหายโรคแล้ว จงไปเป็นสุขเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 49, 'เมื่อพระองค์กําลังตรัสอยู่ มีคนหนึ่งมาจากบ้านนายธรรมศาลา บอกเขาว่า “ลูกสาวของท่านตายเสียแล้ว ไม่ต้องรบกวนท่านอาจารย์ต่อไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 50, 'ฝ่ายพระเยซูเมื่อได้ยินจึงตรัสแก่เขาว่า “อย่ากลัวเลย จงเชื่อเท่านั้นและลูกจะหายดี”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 51, 'เมื่อพระองค์เสด็จเข้าไปในเรือน พระองค์ไม่ทรงยอมให้ผู้ใดเข้าไป เว้นแต่เปโตร ยากอบ ยอห์น และบิดามารดาของเด็กนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 52, 'คนทั้งหลายจึงร้องไห้ร่ําไรเพราะเด็กนั้น แต่พระองค์ตรัสว่า “อย่าร้องไห้เลย เขาไม่ตาย แต่นอนหลับอยู่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 53, 'คนทั้งปวงก็พากันหัวเราะเยาะพระองค์ เพราะรู้ว่าเด็กนั้นตายแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 54, 'ฝ่ายพระองค์ทรงไล่คนทั้งหมดออกไป แล้วทรงจับมือเด็กนั้น ตรัสว่า “ลูกเอ๋ย จงลุกขึ้นเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 55, 'แล้วจิตวิญญาณก็กลับเข้าในเด็กนั้น เขาก็ลุกขึ้นทันที พระองค์จึงตรัสสั่งให้เอาอาหารมาให้เขากิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 56, 'ฝ่ายบิดามารดาของเด็กนั้นก็ประหลาดใจ แต่พระองค์ทรงกําชับเขาไม่ให้บอกผู้ใดให้รู้เหตุการณ์ซึ่งเป็นมานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 1, 'พระองค์ทรงเรียกสาวกสิบสองคนของพระองค์มาพร้อมกัน แล้วทรงประทานให้เขามีอํานาจและสิทธิอํานาจเหนือผีทั้งปวงและรักษาโรคต่างๆให้หาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 2, 'แล้วพระองค์ทรงใช้เขาไปประกาศอาณาจักรของพระเจ้า และรักษาคนเจ็บป่วยให้หาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 3, 'พระองค์จึงตรัสสั่งเขาว่า “อย่าเอาอะไรไปใช้ตามทาง เช่น ไม้เท้า หรือย่าม หรืออาหาร หรือเงิน หรือเสื้อคลุมสองตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 4, 'และถ้าเข้าไปในเรือนไหน จงอาศัยอยู่ในเรือนนั้นจนกว่าจะไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 5, 'ผู้ใดไม่ต้อนรับพวกท่าน เมื่อท่านจะไปจากเมืองนั้น จงสะบัดผงคลีดินจากเท้าของท่านออกส่อให้เห็นความผิดของเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 6, 'เหล่าสาวกจึงออกไปตามเมืองต่างๆประกาศข่าวประเสริฐ และรักษาคนเจ็บป่วยทุกแห่งให้หาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 7, 'ฝ่ายเฮโรดเจ้าเมืองได้ยินเรื่องเหตุการณ์ทั้งปวงซึ่งพระองค์ได้ทรงกระทํานั้น จึงคิดสงสัยมาก เพราะบางคนว่ายอห์นเป็นขึ้นมาจากความตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 8, 'บางคนก็ว่าเป็นเอลียาห์มาปรากฏ คนอื่นว่าเป็นศาสดาพยากรณ์โบราณกลับเป็นขึ้นมาอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 9, 'เฮโรดจึงว่า “ยอห์นนั้นเราได้ตัดศีรษะแล้ว แต่คนนี้ที่เราได้ยินเหตุการณ์ของเขาอย่างนี้คือผู้ใดเล่า” แล้วเฮโรดจึงหาโอกาสที่จะเห็นพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 10, 'ครั้นอัครสาวกกลับมาแล้ว เขาทูลพระองค์ถึงบรรดาการซึ่งเขาได้กระทํานั้น พระองค์จึงพาเขาไปยังที่เปลี่ยวแต่ลําพังใกล้เมืองที่เรียกว่าเบธไซดา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 11, 'แต่เมื่อประชาชนรู้แล้วจึงตามพระองค์ไป พระองค์ทรงต้อนรับเขา ตรัสสั่งสอนเขาถึงอาณาจักรของพระเจ้า และทุกคนที่ต้องการให้หายโรคพระองค์ก็ทรงรักษาให้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 12, 'ครั้นกําลังจะเย็นแล้ว สาวกสิบสองคนมาทูลพระองค์ว่า “ขอให้ประชาชนไปตามเมืองต่างๆและชนบทที่อยู่แถบนี้ หาที่พักนอนและหาอาหารรับประทาน เพราะที่เราอยู่นี้เป็นที่เปลี่ยว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 13, 'แต่พระองค์ตรัสแก่เขาว่า “พวกท่านจงเลี้ยงเขาเถิด” เขาทูลว่า “เราไม่มีอะไรมาก มีแต่ขนมปังห้าก้อนกับปลาสองตัว เว้นเสียแต่เราจะไปซื้ออาหารสําหรับคนทั้งปวงนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 14, 'เพราะว่าคนเหล่านั้นนับแต่ผู้ชายได้ประมาณห้าพันคน พระองค์จึงสั่งเหล่าสาวกของพระองค์ว่า “จงให้คนทั้งปวงนั่งลงเป็นหมู่ๆ ราวหมู่ละห้าสิบคน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 15, 'เขาก็กระทําตาม คือให้คนทั้งปวงนั่งลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 16, 'เมื่อพระองค์ทรงรับขนมปังห้าก้อนกับปลาสองตัวนั้นแล้ว ก็แหงนพระพักตร์ดูฟ้าสวรรค์ขอบพระคุณ แล้วหักส่งให้แก่เหล่าสาวก ให้เขาแจกแก่ประชาชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 17, 'เขาได้กินอิ่มทุกคน แล้วเขาเก็บเศษอาหารที่ยังเหลือนั้นได้สิบสองกระบุง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 18, 'ต่อมาเมื่อพระองค์กําลังอธิษฐานอยู่แต่ลําพัง เหล่าสาวกอยู่กับพระองค์ พระองค์จึงตรัสถามเขาว่า “คนทั้งปวงพูดกันว่า เราเป็นผู้ใด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 19, 'เหล่าสาวกทูลตอบว่า “เขาว่าเป็นยอห์นผู้ให้รับบัพติศมา บางคนว่าเป็นเอลียาห์ แต่คนอื่นว่าเป็นคนหนึ่งในพวกศาสดาพยากรณ์โบราณเป็นขึ้นมาใหม่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 20, 'พระองค์จึงตรัสถามเขาว่า “แล้วพวกท่านเล่าว่าเราเป็นผู้ใด” เปโตรทูลตอบว่า “เป็นพระคริสต์ของพระเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 21, 'พระองค์จึงกําชับสั่งเขามิให้บอกความนี้แก่ผู้ใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 22, 'ตรัสว่า “บุตรมนุษย์จะต้องทนทุกข์ทรมานหลายประการ พวกผู้ใหญ่ พวกปุโรหิตใหญ่ และพวกธรรมาจารย์จะปฏิเสธท่าน ในที่สุดท่านจะต้องถูกประหารชีวิต แต่ในวันที่สามท่านจะทรงถูกชุบให้เป็นขึ้นมาใหม่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 23, 'พระองค์จึงตรัสแก่เขาทั้งหลายว่า “ถ้าผู้ใดใคร่จะตามเรามา ให้ผู้นั้นเอาชนะตัวเอง และรับกางเขนของตนแบกทุกวัน และตามเรามา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 24, 'เพราะว่าผู้ใดใคร่จะเอาชีวิตรอด ผู้นั้นจะเสียชีวิต แต่ผู้ใดจะเสียชีวิตเพราะเห็นแก่เรา ผู้นั้นจะได้ชีวิตรอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 25, 'เพราะถ้าผู้ใดจะได้สิ่งของสิ้นทั้งโลกแต่ต้องเสียตัวของตนเองหรือถูกทิ้งเสีย ผู้นั้นจะได้ประโยชน์อะไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 26, 'เพราะถ้าผู้ใดมีความอายเพราะเราและถ้อยคําของเรา บุตรมนุษย์ก็จะมีความอายเพราะผู้นั้น เมื่อท่านมาด้วยสง่าราศีของท่านเองและของพระบิดาและของเหล่าทูตสวรรค์บริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 27, 'แต่เราบอกความจริงแก่ท่านทั้งหลายว่า มีบางคนที่ยืนอยู่ที่นี่ ซึ่งยังจะไม่รู้รสความตายจนกว่าจะได้เห็นอาณาจักรของพระเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 28, 'ต่อมาภายหลังพระองค์ได้ตรัสคําเหล่านั้นประมาณแปดวัน พระองค์จึงทรงพาเปโตร ยอห์น และยากอบขึ้นไปบนภูเขาเพื่อจะอธิษฐาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 29, 'ขณะที่พระองค์กําลังอธิษฐานอยู่ วรรณพระพักตร์ของพระองค์ก็เปลี่ยนไป และฉลองพระองค์ก็ขาวเป็นมันระยับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 30, 'ดูเถิด มีชายสองคนสนทนาอยู่กับพระองค์ คือโมเสส และเอลียาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 31, 'ผู้มาปรากฏด้วยสง่าราศี และกล่าวถึงการมรณาของพระองค์ ซึ่งจะสําเร็จในกรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 32, 'ฝ่ายเปโตรกับคนที่อยู่ด้วยนั้นก็ง่วงเหงาหาวนอน แต่เมื่อเขาตาสว่างขึ้นแล้วเขาก็ได้เห็นสง่าราศีของพระองค์ และเห็นชายสองคนนั้นที่ยืนอยู่กับพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 33, 'ต่อมาเมื่อสองคนนั้นกําลังลาไปจากพระองค์ เปโตรจึงทูลพระเยซูว่า “พระอาจารย์เจ้าข้า ซึ่งเราอยู่ที่นี่ก็ดี ให้พวกข้าพระองค์ทําพลับพลาสามหลัง สําหรับพระองค์หลังหนึ่ง สําหรับโมเสสหลังหนึ่ง สําหรับเอลียาห์หลังหนึ่ง” เปโตรไม่เข้าใจว่าตัวได้พูดอะไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 34, 'เมื่อเขากําลังพูดคําเหล่านี้ มีเมฆมาคลุมเขาไว้ และเมื่อเข้าอยู่ในเมฆนั้นเขาก็กลัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 35, 'มีพระสุรเสียงออกมาจากเมฆนั้นว่า “ผู้นี้เป็นบุตรที่รักของเรา จงฟังท่านเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 36, 'เมื่อพระสุรเสียงนั้นสงบแล้ว พระเยซูทรงสถิตอยู่องค์เดียว เขาทั้งสามก็เก็บเรื่องนี้ไว้ และในกาลครั้งนั้นเขามิได้บอกเหตุการณ์ซึ่งเขาได้เห็นแก่ผู้ใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 37, 'ต่อมาวันรุ่งขึ้นเมื่อพระองค์กับเหล่าสาวกลงมาจากภูเขาแล้ว มีคนมากมายมาพบพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 38, 'ดูเถิด มีชายคนหนึ่งในหมู่ประชาชนนั้นร้องว่า “อาจารย์เจ้าข้า ขอพระองค์ทรงโปรดทอดพระเนตรบุตรชายของข้าพเจ้า เพราะว่าข้าพเจ้ามีบุตรคนเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 39, 'และ ดูเถิด ผีมักจะเข้าสิงเขา เด็กก็โห่ร้องขึ้นทันที ผีทําให้เด็กนั้นชักดิ้น น้ําลายฟูมปาก ทําให้ตัวฟกช้ํา ไม่ใคร่ออกจากเขาเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 40, 'ข้าพเจ้าได้ขอเหล่าสาวกของพระองค์ให้ขับมันออกเสีย แต่เขากระทําไม่ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 41, 'พระเยซูตรัสตอบว่า “โอ คนในยุคที่ขาดความเชื่อและมีทิฐิชั่ว เราจะต้องอยู่กับเจ้าทั้งหลายและอดทนเพราะพวกเจ้านานเท่าใด จงพาบุตรของท่านมาที่นี่เถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 42, 'เมื่อเด็กนั้นกําลังมา ผีก็ทําให้เขาล้มชักดิ้นใหญ่ แต่พระเยซูตรัสสําทับผีโสโครกนั้นและทรงรักษาเด็กให้หาย แล้วส่งคืนให้บิดาเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 43, 'คนทั้งปวงก็ประหลาดใจนักเพราะฤทธิ์เดชอันใหญ่ยิ่งของพระเจ้า แต่เมื่อเขาทั้งหลายยังประหลาดใจอยู่เพราะเหตุการณ์ทั้งปวงซึ่งพระเยซูได้ทรงกระทํานั้น พระองค์จึงตรัสแก่เหล่าสาวกของพระองค์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 44, '“จงให้คําเหล่านี้เข้าหูของท่าน เพราะว่าบุตรมนุษย์จะต้องถูกมอบไว้ในเงื้อมมือของคนทั้งหลาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 45, 'แต่คําเหล่านั้นสาวกหาได้เข้าใจไม่ ความก็ถูกซ่อนไว้จากเขา เพื่อเขาจะไม่ได้เข้าใจ และเขาไม่กล้าถามพระองค์ถึงคํานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 46, 'แล้วเหล่าสาวกก็เกิดเถียงกันว่า ในพวกเขาใครจะเป็นใหญ่ที่สุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 47, 'ฝ่ายพระเยซูทรงหยั่งรู้ความคิดในใจของเขา จึงให้เด็กคนหนึ่งยืนอยู่ใกล้พระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 48, 'แล้วตรัสกับเขาว่า “ถ้าผู้ใดจะรับเด็กเล็กๆคนนี้ในนามของเรา ผู้นั้นก็ได้รับเรา และผู้ใดได้รับเรา ผู้นั้นก็ได้รับพระองค์ผู้ทรงใช้เรามา เพราะว่าในพวกท่านทั้งหลาย ผู้ใดเป็นผู้ต่ําต้อยที่สุด ผู้นั้นแหละเป็นผู้ใหญ่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 49, 'ฝ่ายยอห์นทูลพระองค์ว่า “พระอาจารย์เจ้าข้า พวกข้าพระองค์เห็นผู้หนึ่งขับผีออกในพระนามของพระองค์ และข้าพระองค์ได้ห้ามเขาเสีย เพราะเขาไม่ตามพวกเรามา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 50, 'พระเยซูตรัสแก่เขาว่า “อย่าห้ามเขาเลย เพราะว่าผู้ใดไม่เป็นฝ่ายต่อสู้เรา ก็เป็นฝ่ายเราแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 51, 'ต่อมาครั้นจวนเวลาที่พระองค์จะทรงถูกรับขึ้นไป พระองค์ทรงมุ่งพระพักตร์แน่วไปยังกรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 52, 'และพระองค์ทรงใช้ผู้ส่งข่าวล่วงหน้าไปก่อน เขาก็เข้าไปในหมู่บ้านแห่งหนึ่งของชาวสะมาเรียเพื่อจะเตรียมไว้ให้พระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 53, 'ชาวบ้านนั้นไม่รับรองพระองค์ เพราะดูเหมือนว่าพระองค์กําลังทรงมุ่งพระพักตร์ไปยังกรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 54, 'และเมื่อสาวกของพระองค์ คือยากอบและยอห์นได้เห็นดังนั้น เขาทูลว่า “พระองค์เจ้าข้า พระองค์พอพระทัยจะให้ข้าพระองค์ขอไฟลงมาจากสวรรค์ เผาผลาญเขาเสียอย่างเอลียาห์ได้กระทํานั้นหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 55, 'แต่พระองค์ทรงเหลียวมาห้ามปรามเขา และตรัสว่า “ท่านไม่รู้ว่าท่านมีจิตใจทํานองใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 56, 'เพราะว่าบุตรมนุษย์มิได้มาเพื่อทําลายชีวิตมนุษย์ แต่มาเพื่อช่วยเขาทั้งหลายให้รอด” แล้วพระองค์กับเหล่าสาวกก็เลยไปที่หมู่บ้านอีกแห่งหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 57, 'ต่อมาเมื่อพระองค์กับเหล่าสาวกกําลังเดินทางไป มีคนหนึ่งทูลพระองค์ว่า “พระองค์เจ้าข้า พระองค์เสด็จไปทางไหน ข้าพระองค์จะตามพระองค์ไปทางนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 58, 'พระเยซูตรัสแก่เขาว่า “สุนัขจิ้งจอกยังมีโพรง และนกในอากาศก็ยังมีรัง แต่บุตรมนุษย์ไม่มีที่ที่จะวางศีรษะ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 59, 'พระองค์ตรัสแก่อีกคนหนึ่งว่า “จงตามเรามาเถิด” แต่คนนั้นทูลตอบว่า “พระองค์เจ้าข้า ขอทรงโปรดให้ข้าพระองค์ไปฝังศพบิดาข้าพระองค์ก่อน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 60, 'พระเยซูจึงตรัสกับเขาว่า “ปล่อยให้คนตายฝังคนตายของเขาเองเถิด แต่ส่วนท่านจงไปประกาศอาณาจักรของพระเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 61, 'อีกคนหนึ่งทูลว่า “พระองค์เจ้าข้า ข้าพระองค์จะตามพระองค์ไป แต่ขออนุญาตให้ข้าพระองค์ไปลาคนที่อยู่ในบ้านของข้าพระองค์ก่อน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 62, 'พระเยซูตรัสกับเขาว่า “ผู้ใดเอามือจับคันไถแล้วหันหน้ากลับเสีย ผู้นั้นก็ไม่สมควรกับอาณาจักรของพระเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 1, 'ภายหลังเหตุการณ์เหล่านี้ องค์พระผู้เป็นเจ้าทรงตั้งสาวกอื่นอีกเจ็ดสิบคนไว้และใช้เขาออกไปทีละสองคนๆ ให้ล่วงหน้าพระองค์ไปก่อน ให้เข้าไปทุกเมืองและทุกตําบลที่พระองค์จะเสด็จไปนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 2, 'พระองค์ตรัสกับเขาว่า “การเก็บเกี่ยวนั้นเป็นการใหญ่นักหนา แต่คนงานยังน้อยอยู่ เหตุฉะนั้นพวกท่านจงอ้อนวอนพระองค์ผู้ทรงเป็นเจ้าของการเก็บเกี่ยวนั้น ให้ส่งคนงานมาในการเก็บเกี่ยวของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 3, 'ไปเถอะ ดูเถิด เราใช้ท่านทั้งหลายไปดุจลูกแกะอยู่ท่ามกลางฝูงสุนัขป่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 4, 'อย่าเอาไถ้เงิน หรือย่าม หรือรองเท้าไป และอย่าคํานับผู้ใดตามทาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 5, 'ถ้าท่านจะเข้าไปในเรือนใดๆจงพูดก่อนว่า ‘ให้ความสุขมีแก่เรือนนี้เถิด’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 6, 'ถ้าลูกแห่งสันติสุขอยู่ที่นั่น สันติสุขของท่านจะอยู่กับเขา ถ้าหาไม่ สันติสุขของท่านจะกลับอยู่กับท่านอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 7, 'จงอาศัยอยู่ในเรือนนั้น กินและดื่มของซึ่งเขาจะให้นั้นด้วยว่าผู้ทํางานสมควรจะได้รับค่าจ้างของตน อย่าเที่ยวจากเรือนนี้ไปเรือนโน้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 8, 'ถ้าท่านจะเข้าไปในเมืองใดๆและเขารับรองท่านไว้ จงกินของที่เขาตั้งให้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 9, 'และจงรักษาคนป่วยในเมืองนั้นให้หาย และแจ้งแก่เขาว่า ‘อาณาจักรของพระเจ้ามาใกล้ท่านทั้งหลายแล้ว’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 10, 'ถ้าท่านจะเข้าไปในเมืองใดๆและเขาไม่รับรองท่านไว้ จงออกไปที่กลางถนนของเมืองนั้นกล่าวว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 11, '‘ถึงแม้ผงคลีดินแห่งเมืองของเจ้าทั้งหลายที่ติดอยู่กับเรา เราก็จะสะบัดออกเป็นที่แสดงว่า เราไม่เห็นพ้องกับเจ้า แต่เจ้าทั้งหลายจงเข้าใจความนี้เถิด คืออาณาจักรของพระเจ้ามาใกล้เจ้าทั้งหลายแล้ว’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 12, 'เราบอกท่านทั้งหลายว่า โทษของเมืองโสโดมในวันนั้นจะเบากว่าโทษของเมืองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 13, 'วิบัติแก่เจ้า เมืองโคราซิน วิบัติแก่เจ้า เมืองเบธไซดา เพราะถ้าการมหัศจรรย์ซึ่งได้กระทําท่ามกลางเจ้าได้กระทําในเมืองไทระและเมืองไซดอน คนในเมืองทั้งสองจะได้นุ่งห่มผ้ากระสอบ นั่งบนขี้เถ้า กลับใจเสียใหม่นานมาแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 14, 'แต่ในการพิพากษานั้น โทษของเมืองไทระและเมืองไซดอนจะเบากว่าโทษของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 15, 'ฝ่ายเจ้าเมืองคาเปอรนาอุม ซึ่งได้ถูกยกขึ้นเทียมฟ้า เจ้าจะต้องลงไปถึงนรกต่างหาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 16, 'ผู้ที่ฟังท่านทั้งหลายก็ได้ฟังเรา ผู้ที่เกลียดชังท่านทั้งหลายก็เกลียดชังเรา ผู้ที่เกลียดชังเราก็เกลียดชังผู้ที่ทรงใช้เรามา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 17, 'ฝ่ายสาวกเจ็ดสิบคนนั้นกลับมาด้วยความปรีดีทูลว่า “พระองค์เจ้าข้า ถึงผีทั้งหลายก็ได้อยู่ใต้บังคับของพวกข้าพระองค์โดยพระนามของพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 18, 'พระองค์ตรัสกับเขาทั้งหลายว่า “เราได้เห็นซาตานตกจากสวรรค์เหมือนฟ้าแลบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 19, 'ดูเถิด เราได้ให้พวกท่านมีอํานาจเหยียบงูร้ายและแมงป่อง และมีอํานาจใหญ่ยิ่งกว่ากําลังศัตรู ไม่มีสิ่งหนึ่งสิ่งใดจะทําอันตรายแก่ท่านได้เลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 20, 'แต่ว่าอย่าเปรมปรีดิ์ในสิ่งนี้ คือที่พวกผีอยู่ใต้บังคับของท่าน แต่จงเปรมปรีดิ์มากยิ่งกว่าเพราะชื่อของท่านจดไว้ในสวรรค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 21, 'ในโมงนั้นเอง พระเยซูทรงมีความเปรมปรีดิ์ในพระวิญญาณ จึงตรัสว่า “โอ ข้าแต่พระบิดา ผู้เป็นเจ้าแห่งฟ้าสวรรค์และแผ่นดินโลก ข้าพระองค์ขอบพระคุณพระองค์ที่พระองค์ได้ทรงปิดบังสิ่งเหล่านี้ไว้จากคนมีปัญญาและคนสุขุมรอบคอบ และได้ทรงเปิดเผยสิ่งเหล่านี้แก่ทารกน้อย ข้าแต่พระบิดา ที่เป็นอย่างนั้นก็เพราะเป็นที่ชอบพระทัยในสายพระเนตรของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 22, 'พระบิดาของเราได้ทรงมอบสิ่งสารพัดให้แก่เรา และไม่มีใครรู้ว่าพระบุตรเป็นผู้ใดนอกจากพระบิดา และไม่มีใครรู้ว่าพระบิดาเป็นผู้ใดนอกจากพระบุตร และผู้ที่พระบุตรประสงค์จะสําแดงให้รู้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 23, 'พระองค์ทรงเหลียวหลังไปทางเหล่าสาวกตรัสเฉพาะแก่พวกเขาว่า “นัยน์ตาทั้งหลายที่ได้เห็นการณ์ซึ่งพวกท่านได้เห็นก็เป็นสุข');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 24, 'เพราะเราบอกท่านทั้งหลายว่า ศาสดาพยากรณ์หลายคน และกษัตริย์หลายองค์ ปรารถนาจะเห็นซึ่งท่านทั้งหลายเห็นอยู่นี้ แต่เขามิเคยได้เห็น และอยากจะได้ยินซึ่งท่านทั้งหลายได้ยิน แต่เขามิเคยได้ยิน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 25, 'ดูเถิด มีนักกฎหมายคนหนึ่งยืนขึ้นทดลองพระองค์ทูลถามว่า “อาจารย์เจ้าข้า ข้าพเจ้าจะต้องทําประการใดเพื่อจะได้ชีวิตนิรันดร์เป็นมรดก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 26, 'พระองค์ตรัสตอบเขาว่า “ในพระราชบัญญัติมีคําเขียนว่าอย่างไร ท่านได้อ่านเข้าใจอย่างไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 27, 'เขาทูลตอบว่า “จงรักองค์พระผู้เป็นเจ้าผู้เป็นพระเจ้าของเจ้าด้วยสุดจิตสุดใจของเจ้า ด้วยสุดกําลังและสิ้นสุดความคิดของเจ้า และจงรักเพื่อนบ้านเหมือนรักตนเอง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 28, 'พระองค์จึงตรัสแก่เขาว่า “ท่านตอบถูกแล้ว จงกระทําอย่างนั้นแล้วท่านจะได้ชีวิต”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 29, 'แต่คนนั้นปรารถนาจะแก้ตัวจึงทูลพระเยซูว่า “แล้วใครเป็นเพื่อนบ้านของข้าพเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 30, 'พระเยซูตรัสตอบว่า “มีชายคนหนึ่งลงไปจากกรุงเยรูซาเล็มจะไปยังเมืองเยรีโค และเขาถูกพวกโจรปล้น โจรนั้นได้แย่งชิงเสื้อผ้าของเขาและทุบตี แล้วก็ละทิ้งเขาไว้เกือบจะตายแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 31, 'เผอิญปุโรหิตคนหนึ่งเดินลงไปทางนั้น เมื่อเห็นคนนั้นก็เดินเลยไปเสียอีกฟากหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 32, 'คนหนึ่งในพวกเลวีก็ทําเหมือนกัน เมื่อมาถึงที่นั่นและเห็นแล้วก็เลยไปเสียอีกฟากหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 33, 'แต่ชาวสะมาเรียคนหนึ่งเมื่อเดินมาถึงคนนั้น ครั้นเห็นแล้วก็มีใจเมตตา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 34, 'เข้าไปหาเขาเอาผ้าพันบาดแผลให้ พลางเอาน้ํามันกับน้ําองุ่นเทใส่บาดแผลนั้น แล้วให้เขาขึ้นขี่สัตว์ของตนเองพามาถึงโรงแรมแห่งหนึ่ง และรักษาพยาบาลเขาไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 35, 'วันรุ่งขึ้นเมื่อจะไป เขาก็เอาเงินสองเดนาริอันมอบให้เจ้าของโรงแรม บอกเขาว่า ‘จงรักษาเขาไว้เถิด และเงินที่จะเสียเกินนี้ เมื่อกลับมาฉันจะใช้ให้’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 36, 'ในสามคนนั้น ท่านคิดเห็นว่า คนไหนปรากฏว่าเป็นเพื่อนบ้านของคนที่ถูกพวกโจรปล้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 37, 'เขาทูลตอบว่า “คือคนนั้นแหละที่ได้แสดงความเมตตาแก่เขา” พระเยซูจึงตรัสกับเขาว่า “ท่านจงไปทําเหมือนอย่างนั้นเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 38, 'และต่อมาเมื่อพระองค์กับเหล่าสาวกกําลังเดินทางไป พระองค์จึงทรงเข้าไปในหมู่บ้านแห่งหนึ่ง มีผู้หญิงคนหนึ่งชื่อมารธาต้อนรับพระองค์ไว้ในเรือนของเธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 39, 'มารธามีน้องสาวชื่อมารีย์ มารีย์ก็นั่งใกล้พระบาทพระเยซูฟังถ้อยคําของพระองค์ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 40, 'แต่มารธายุ่งในการปรนนิบัติมากจึงมาทูลพระองค์ว่า “พระองค์เจ้าข้า พระองค์ไม่สนพระทัยหรือ ซึ่งน้องสาวของข้าพระองค์ปล่อยให้ข้าพระองค์ทําการปรนนิบัติแต่คนเดียว ขอพระองค์สั่งเขาให้มาช่วยข้าพระองค์เถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 41, 'แต่พระเยซูตรัสตอบเธอว่า “มารธา มารธา เอ๋ย เธอกระวนกระวายและร้อนใจด้วยหลายสิ่งนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 42, 'สิ่งซึ่งต้องการนั้นมีแต่สิ่งเดียว มารีย์ได้เลือกเอาส่วนดีนั้น ใครจะชิงเอาไปจากเธอไม่ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 1, 'ต่อมาเมื่อพระองค์ทรงอธิษฐานอยู่ในที่แห่งหนึ่ง พอจบแล้วสาวกของพระองค์คนหนึ่งทูลพระองค์ว่า “พระองค์เจ้าข้า ขอสอนพวกข้าพระองค์ให้อธิษฐาน เหมือนยอห์นได้สอนพวกศิษย์ของตน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 2, 'พระองค์จึงตรัสกับเขาว่า “เมื่อท่านอธิษฐานจงว่า ‘ข้าแต่พระบิดาของข้าพระองค์ทั้งหลาย ผู้สถิตในสวรรค์ ขอให้พระนามของพระองค์เป็นที่เคารพสักการะ ขอให้อาณาจักรของพระองค์มาตั้งอยู่ น้ําพระทัยของพระองค์สําเร็จในสวรรค์อย่างไร ก็ให้สําเร็จบนแผ่นดินโลกเหมือนกันอย่างนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 3, 'ขอทรงโปรดประทานอาหารประจําวันแก่ข้าพระองค์ทั้งหลายทุกๆวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 4, 'ขอทรงโปรดยกบาปผิดของข้าพระองค์ทั้งหลาย ด้วยว่าข้าพระองค์ยกความผิดของทุกคนที่ทําผิดต่อข้าพระองค์นั้น ขออย่าทรงนําข้าพระองค์เข้าไปในการทดลอง แต่ขอให้ข้าพระองค์พ้นจากความชั่วร้าย’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 5, 'พระองค์ตรัสแก่เขาว่า “ผู้ใดในพวกท่านมีมิตรสหายคนหนึ่ง และจะไปหามิตรสหายนั้นในเวลาเที่ยงคืนพูดกับเขาว่า ‘เพื่อนเอ๋ย ขอให้ฉันยืมขนมปังสามก้อนเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 6, 'เพราะเพื่อนของฉันคนหนึ่งเพิ่งเดินทางมาหาฉัน และฉันไม่มีอะไรจะให้เขารับประทาน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 7, 'ฝ่ายมิตรสหายที่อยู่ข้างในจะตอบว่า ‘อย่ารบกวนฉันเลย ประตูก็ปิดเสียแล้ว ทั้งพวกลูกก็นอนร่วมเตียงกับฉันแล้ว ฉันจะลุกขึ้นหยิบให้ท่านไม่ได้’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 8, 'เราบอกท่านทั้งหลายว่า แม้เขาจะไม่ลุกขึ้นหยิบให้คนนั้นเพราะเป็นมิตรสหายกัน แต่ว่าเพราะวิงวอนมากเข้า เขาจึงจะลุกขึ้นหยิบให้ตามที่เขาต้องการ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 9, 'เราบอกท่านทั้งหลายว่า จงขอแล้วจะได้ จงหาแล้วจะพบ จงเคาะแล้วจะเปิดให้แก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 10, 'เพราะว่าทุกคนที่ขอก็จะได้ ทุกคนที่แสวงหาก็จะพบ และทุกคนที่เคาะก็จะเปิดให้เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 11, 'มีผู้ใดในพวกท่านที่เป็นบิดา ถ้าบุตรขอขนมปังจะเอาก้อนหินให้เขาหรือ หรือถ้าขอปลาจะเอางูให้เขาแทนปลาหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 12, 'หรือถ้าเขาขอไข่จะเอาแมงป่องให้เขาหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 13, 'เพราะฉะนั้น ถ้าท่านทั้งหลายเองผู้เป็นคนชั่ว ยังรู้จักให้ของดีแก่บุตรของตน ยิ่งกว่านั้นสักเท่าใด พระบิดาของท่านผู้ทรงสถิตในสวรรค์ จะทรงประทานพระวิญญาณบริสุทธิ์แก่ผู้ที่ขอต่อพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 14, 'พระองค์ทรงขับผีใบ้อยู่ และต่อมาเมื่อผีออกแล้ว คนใบ้จึงพูดได้ และประชาชนก็ประหลาดใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 15, 'แต่บางคนในพวกเขาพูดว่า “คนนี้ขับผีออกได้โดยใช้อํานาจของเบเอลเซบูลนายผีนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 16, 'คนอื่นๆทดลองพระองค์ โดยขอจากพระองค์ให้เห็นหมายสําคัญจากสวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 17, 'แต่พระองค์ทรงทราบความคิดของเขา จึงตรัสกับเขาว่า “ราชอาณาจักรใดๆซึ่งแตกแยกกันเองก็จะรกร้างไป ครัวเรือนใดๆซึ่งแตกแยกกับครัวเรือนก็จะล่มสลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 18, 'และถ้าซาตานแก่งแย่งกันระหว่างมันเอง อาณาจักรของมันจะตั้งอยู่อย่างไรได้ เพราะท่านทั้งหลายว่าเราขับผีออกโดยเบเอลเซบูล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 19, 'ถ้าเราขับผีออกโดยเบเอลเซบูลนั้น พวกพ้องของท่านทั้งหลายขับมันออกโดยอํานาจของใครเล่า เหตุฉะนั้นพวกพ้องของท่านเองจะเป็นผู้ตัดสินกล่าวโทษพวกท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 20, 'แต่ถ้าเราขับผีออกด้วยนิ้วพระหัตถ์ของพระเจ้า อาณาจักรของพระเจ้าก็มาถึงท่านแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 21, 'เมื่อผู้มีกําลังมากคนหนึ่งถืออาวุธเฝ้าบ้านของตนอยู่ สิ่งของของเขาก็ปลอดภัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 22, 'แต่เมื่อคนมีกําลังมากกว่าเขามาต่อสู้ชนะเขา คนนั้นก็ชิงเอาเครื่องอาวุธที่เขาได้วางใจนั้นไปเสีย แล้วแบ่งปันของที่เขาได้ริบเอาไปนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 23, 'ผู้ที่ไม่อยู่ฝ่ายเราก็เป็นปฏิปักษ์ต่อเรา และผู้ที่ไม่รวบรวมไว้กับเราก็เป็นผู้กระทําให้กระจัดกระจายไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 24, 'เมื่อผีโสโครกออกมาจากผู้ใดแล้ว มันก็ท่องเที่ยวไปในที่กันดารเพื่อแสวงหาที่หยุดพัก และเมื่อไม่พบมันจึงกล่าวว่า ‘ข้าจะกลับไปยังเรือนของข้าที่ได้ออกมานั้น’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 25, 'และเมื่อมาถึงก็เห็นเรือนนั้นกวาดและตกแต่งไว้แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 26, 'มันจึงไปรับเอาผีอื่นอีกเจ็ดผีร้ายกว่ามันเอง แล้วก็เข้าไปอาศัยอยู่ที่นั่น และในที่สุดคนนั้นก็เลวร้ายกว่าตอนแรก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 27, 'ต่อมาเมื่อพระองค์ยังตรัสคําเหล่านั้น มีผู้หญิงคนหนึ่งในหมู่ประชาชนร้องทูลพระองค์ว่า “ครรภ์ซึ่งปฏิสนธิพระองค์และหัวนมที่พระองค์เสวยนั้นก็เป็นสุข”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 28, 'แต่พระองค์ตรัสว่า “มิใช่เช่นนั้น แต่คนทั้งหลายที่ได้ยินพระวจนะของพระเจ้า และได้ถือรักษาพระวจนะนั้นไว้ ก็เป็นสุข”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 29, 'เมื่อคนทั้งปวงประชุมแน่นขึ้น พระองค์ตั้งต้นตรัสว่า “คนยุคนี้เป็นคนชั่ว มีแต่แสวงหาหมายสําคัญ และจะไม่โปรดให้หมายสําคัญแก่เขา เว้นไว้แต่หมายสําคัญของโยนาห์ศาสดาพยากรณ์เท่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 30, 'ด้วยว่าโยนาห์ได้เป็นหมายสําคัญแก่ชาวนีนะเวห์ฉันใด บุตรมนุษย์จะเป็นหมายสําคัญแก่คนยุคนี้ฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 31, 'นางกษัตริย์ฝ่ายทิศใต้จะลุกขึ้นในวันพิพากษาพร้อมกับคนยุคนี้ และจะกล่าวโทษคนในยุคนี้ ด้วยว่าพระนางนั้นได้มาจากที่สุดปลายแผ่นดินโลกเพื่อจะฟังสติปัญญาของซาโลมอน และดูเถิด ซึ่งใหญ่กว่าซาโลมอนก็มีอยู่ที่นี่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 32, 'ชนชาวนีนะเวห์จะลุกขึ้นในวันพิพากษาพร้อมกับคนยุคนี้ และจะกล่าวโทษคนในยุคนี้ ด้วยว่าชาวนีนะเวห์ได้กลับใจใหม่เพราะคําประกาศของโยนาห์ และดูเถิด ซึ่งใหญ่กว่าโยนาห์มีอยู่ที่นี่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 33, 'ไม่มีผู้ใดเมื่อจุดเทียนแล้วจะตั้งไว้ในที่กําบัง หรือเอาถังครอบไว้ แต่ตั้งไว้บนเชิงเทียน เพื่อคนทั้งหลายที่เข้ามาจะเห็นแสงสว่างได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 34, 'ตาเป็นประทีปของร่างกาย เหตุฉะนั้นเมื่อตาของท่านดี ทั้งตัวก็เต็มไปด้วยความสว่าง แต่เมื่อตาของท่านชั่ว ทั้งตัวของท่านก็เต็มไปด้วยความมืด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 35, 'เหตุฉะนั้น จงระวังให้ดีไม่ให้ความสว่างซึ่งอยู่ในท่านเป็นความมืดนั่นเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 36, 'เหตุฉะนั้น ถ้ากายทั้งสิ้นของท่านเต็มด้วยความสว่าง ไม่มีที่มืดเลย ก็จะสว่างตลอด เหมือนอย่างแสงสว่างของเทียนที่ส่องมาให้ท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 37, 'เมื่อพระองค์ยังตรัสอยู่ คนหนึ่งในพวกฟาริสีอ้อนวอนพระองค์ให้เสวยกับเขา พระองค์จึงเสด็จเข้าไปทรงเอนพระกายลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 38, 'ฝ่ายคนฟาริสีเมื่อเห็นพระองค์มิได้ทรงล้างก่อนเสวยก็ประหลาดใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 39, 'องค์พระผู้เป็นเจ้าตรัสกับเขาว่า “เจ้าพวกฟาริสีย่อมชําระถ้วยชามภายนอก แต่ภายในของเจ้าเต็มไปด้วยความโลภและความชั่วร้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 40, 'คนโฉดเขลา ผู้ที่ได้สร้างภายนอกก็ได้สร้างภายในด้วยมิใช่หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 41, 'แต่จงให้ทานตามซึ่งเจ้ามีอยู่ภายใน และดูเถิด สิ่งสารพัดก็บริสุทธิ์แก่เจ้าทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 42, 'แต่วิบัติแก่เจ้า พวกฟาริสี ด้วยว่าพวกเจ้าถวายสิบชักหนึ่งของสะระแหน่และขมิ้นและผักทุกอย่าง และได้ละเว้นการพิพากษาและความรักของพระเจ้าเสีย สิ่งเหล่านั้นพวกเจ้าควรได้กระทําอยู่แล้ว แต่สิ่งอื่นนั้นก็ไม่ควรละเว้นด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 43, 'วิบัติแก่เจ้า พวกฟาริสี ด้วยว่าพวกเจ้าชอบที่นั่งอันมีเกียรติในธรรมศาลาและชอบให้เขาคํานับที่กลางตลาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 44, 'วิบัติแก่เจ้า พวกธรรมาจารย์และพวกฟาริสี คนหน้าซื่อใจคด ด้วยว่าเจ้าทั้งหลายเป็นเหมือนที่ฝังศพซึ่งมิได้ปรากฏ และคนที่เดินเหยียบที่นั่นก็ไม่รู้ว่ามีอะไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 45, 'นักกฎหมายคนหนึ่งทูลพระองค์ว่า “อาจารย์เจ้าข้า ซึ่งท่านว่าอย่างนั้น ท่านก็ติเตียนพวกเราด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 46, 'พระองค์ตรัสว่า “วิบัติแก่เจ้า พวกนักกฎหมายด้วย เพราะพวกเจ้าเอาของหนักที่แบกยากนักวางบนมนุษย์ แต่ส่วนพวกเจ้าเองก็ไม่จับต้องของหนักนั้นเลยแม้แต่นิ้วเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 47, 'วิบัติแก่เจ้าทั้งหลาย เพราะเจ้าก่ออุโมงค์ฝังศพของพวกศาสดาพยากรณ์ และบรรพบุรุษของเจ้าเองก็ได้ฆ่าศาสดาพยากรณ์นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 48, 'ดังนั้นพวกเจ้าจึงเป็นพยานว่าเจ้าเห็นชอบในการของบรรพบุรุษของเจ้า ด้วยว่าเขาได้ฆ่าพวกศาสดาพยากรณ์นั้น แล้วพวกเจ้าก็ก่ออุโมงค์ฝังศพให้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 49, 'เหตุฉะนั้น พระปัญญาของพระเจ้าก็ตรัสด้วยว่า ‘เราจะใช้พวกศาสดาพยากรณ์และอัครสาวกไปหาเขา และเขาจะฆ่าเสียบ้าง และข่มเหงบ้าง’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 50, 'เพื่อคนยุคนี้แหละจะต้องรับผิดชอบในเรื่องโลหิตของบรรดาศาสดาพยากรณ์ ซึ่งต้องไหลออกตั้งแต่แรกสร้างโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 51, 'คือตั้งแต่โลหิตของอาแบล จนถึงโลหิตของเศคาริยาห์ที่ถูกฆ่าตายระหว่างแท่นบูชากับพระวิหาร เราบอกความจริงแก่ท่านทั้งหลายว่า คนยุคนี้จะต้องรับผิดชอบในโลหิตนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 52, 'วิบัติแก่เจ้า พวกนักกฎหมาย ด้วยว่าเจ้าได้เอาลูกกุญแจแห่งความรู้ไปเสีย คือพวกเจ้าเองก็ไม่เข้าไป และคนที่กําลังเข้าไปนั้นเจ้าก็ได้ขัดขวางไว้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 53, 'เมื่อพระองค์ยังตรัสคําเหล่านั้นแก่เขา พวกธรรมาจารย์และพวกฟาริสีก็ตั้งต้นยั่วเย้าพระองค์อย่างรุนแรง หมายให้ตรัสต่อไปหลายประการ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 54, 'คอยหวังจับผิดในพระดํารัสของพระองค์ เพื่อเขาจะฟ้องพระองค์ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 1, 'ในระหว่างนั้นคนเป็นอันมากนับไม่ถ้วนชุมนุมเบียดเสียดกันอยู่ พระองค์ทรงตั้งต้นตรัสกับเหล่าสาวกของพระองค์ก่อนว่า “ท่านทั้งหลายจงระวังเชื้อของพวกฟาริสี ซึ่งเป็นความหน้าซื่อใจคด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 2, 'เพราะว่าไม่มีสิ่งใดปิดบังไว้ที่จะไม่ต้องเปิดเผย หรือการลับที่จะไม่เผยให้ประจักษ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 3, 'เหตุฉะนั้น สิ่งสารพัดซึ่งพวกท่านได้กล่าวในที่มืดจะได้ยินในที่สว่าง และซึ่งได้กระซิบในหูที่ห้องส่วนตัวจะต้องประกาศบนดาดฟ้าหลังคาบ้าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 4, 'มิตรสหายของเราเอ๋ย เราบอกท่านทั้งหลายว่า อย่ากลัวผู้ที่ฆ่าได้แต่กาย และภายหลังไม่มีอะไรที่จะทําได้อีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 5, 'แต่เราจะเตือนให้ท่านรู้ว่าควรจะกลัวผู้ใด จงกลัวพระองค์ผู้ทรงฆ่าแล้วก็ยังมีฤทธิ์อํานาจที่จะทิ้งลงในนรกได้ แท้จริงเราบอกท่านว่า จงกลัวพระองค์นั้นแหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 6, 'นกกระจอกห้าตัวเขาขายสองบาทมิใช่หรือ และนกนั้นแม้สักตัวเดียว พระเจ้ามิได้ทรงลืมเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 7, 'ถึงผมของท่านทั้งหลายก็ทรงนับไว้แล้วทุกเส้น เหตุฉะนั้น อย่ากลัวเลย ท่านทั้งหลายก็ประเสริฐกว่านกกระจอกหลายตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 8, 'และเราบอกท่านทั้งหลายด้วยว่า ผู้ใดที่จะรับเราต่อหน้ามนุษย์ บุตรมนุษย์ก็จะรับผู้นั้นต่อหน้าเหล่าทูตสวรรค์ของพระเจ้าด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 9, 'แต่ผู้ที่ปฏิเสธเราต่อหน้ามนุษย์ เราจะปฏิเสธผู้นั้นต่อหน้าเหล่าทูตสวรรค์ของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 10, 'ผู้ใดจะกล่าวร้ายต่อบุตรมนุษย์ จะทรงโปรดยกโทษให้ผู้นั้นได้ แต่ถ้าผู้ใดจะกล่าวหมิ่นประมาทต่อพระวิญญาณบริสุทธิ์ จะทรงโปรดยกโทษให้ผู้นั้นไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 11, 'เมื่อเขาพาพวกท่านเข้าในธรรมศาลา หรือต่อหน้าเจ้าเมือง และผู้ที่มีอํานาจ อย่ากระวนกระวายว่าจะตอบอย่างไรหรืออะไร หรือจะกล่าวอะไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 12, 'เพราะว่าพระวิญญาณบริสุทธิ์จะทรงโปรดสอนท่านในเวลาโมงนั้นเองว่า ท่านควรจะพูดอะไรบ้าง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 13, 'และมีผู้หนึ่งในหมู่คนทูลพระองค์ว่า “อาจารย์เจ้าข้า ขอสั่งพี่ชายของข้าพเจ้าให้แบ่งมรดกให้กับข้าพเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 14, 'แต่พระองค์ตรัสตอบเขาว่า “บุรุษเอ๋ย ใครได้ตั้งเราให้เป็นตุลาการ หรือเป็นผู้แบ่งมรดกให้ท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 15, 'แล้วพระองค์จึงตรัสแก่เขาทั้งหลายว่า “จงระวังและเว้นเสียจากความโลภ เพราะว่าชีวิตของบุคคลใดๆมิได้อยู่ในของบริบูรณ์ซึ่งเขามีอยู่นั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 16, 'และพระองค์จึงตรัสคําอุปมาเรื่องหนึ่งให้เขาฟังว่า “ไร่นาของเศรษฐีคนหนึ่งเกิดผลบริบูรณ์มาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 17, 'เศรษฐีคนนั้นจึงคิดในใจว่า ‘เราจะทําอย่างไรดี เพราะว่าเราไม่มีที่ที่จะเก็บผลของเรา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 18, 'เขาจึงคิดว่า ‘เราจะทําอย่างนี้ คือจะรื้อยุ้งฉางของเราเสีย และจะสร้างใหม่ให้โตขึ้น แล้วเราจะรวบรวมข้าวและสมบัติทั้งหมดของเราไว้ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 19, 'แล้วเราจะว่าแก่จิตใจของเราว่า “จิตใจเอ๋ย เจ้ามีทรัพย์สมบัติมากเก็บไว้พอหลายปี จงอยู่สบาย กิน ดื่ม และรื่นเริงเถิด”’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 20, 'แต่พระเจ้าตรัสแก่เขาว่า ‘เจ้าคนโง่ ในคืนวันนี้ชีวิตของเจ้าจะต้องเรียกเอาไปจากเจ้า แล้วของซึ่งเจ้าได้รวบรวมไว้นั้นจะเป็นของใครเล่า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 21, 'คนที่ส่ําสมทรัพย์สมบัติไว้สําหรับตัว และมิได้มั่งมีจําเพาะพระเจ้าก็เป็นเช่นนั้นแหละ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 22, 'และพระองค์ตรัสกับเหล่าสาวกของพระองค์ว่า “เหตุฉะนั้นเราบอกท่านทั้งหลายว่า อย่ากระวนกระวายถึงชีวิตของตนว่าจะเอาอะไรกิน และอย่ากระวนกระวายถึงร่างกายของตนว่าจะเอาอะไรนุ่งห่ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 23, 'เพราะว่าชีวิตสําคัญยิ่งกว่าอาหาร และร่างกายสําคัญยิ่งกว่าเครื่องนุ่งห่ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 24, 'จงพิจารณาดูนกกา มันมิได้หว่าน มิได้เกี่ยว และมิได้มียุ้งหรือฉาง แต่พระเจ้ายังทรงเลี้ยงมันไว้ ท่านทั้งหลายก็ประเสริฐกว่านกมากทีเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 25, 'มีใครในพวกท่าน โดยความกระวนกระวาย อาจต่อความสูงให้ยาวออกไปอีกศอกหนึ่งได้หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 26, 'เหตุฉะนั้น ถ้าสิ่งเล็กน้อยที่สุดยังทําไม่ได้ ท่านยังจะกระวนกระวายถึงสิ่งอื่นทําไมอีกเล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 27, 'จงพิจารณาดอกลิลลี่ว่ามันงอกเจริญขึ้นอย่างไร มันไม่ทํางาน มันไม่ปั่นด้าย แต่เราบอกท่านทั้งหลายว่า ซาโลมอนเมื่อบริบูรณ์ด้วยสง่าราศี ก็มิได้ทรงเครื่องงามเท่าดอกไม้นี้ดอกหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 28, 'แม้ว่าพระเจ้าทรงตกแต่งหญ้าที่ทุ่งนาอย่างนั้น ซึ่งเป็นอยู่วันนี้และรุ่งขึ้นต้องทิ้งในเตาไฟ โอ ผู้ที่มีความเชื่อน้อย พระองค์จะทรงตกแต่งท่านมากยิ่งกว่านั้นสักเท่าใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 29, 'ท่านทั้งหลายอย่าเสาะหาว่าจะกินอะไรดีหรือจะดื่มอะไรและอย่ามีใจสงสัยเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 30, 'เพราะว่าคนทุกประเทศทั่วโลกเสาะหาสิ่งของทั้งปวงนี้ แต่ว่าพระบิดาของท่านทั้งหลายทรงทราบแล้วว่าท่านต้องการสิ่งเหล่านี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 31, 'แต่ท่านทั้งหลายจงแสวงหาอาณาจักรของพระเจ้า แล้วจะทรงเพิ่มเติมสิ่งทั้งปวงเหล่านี้ให้แก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 32, 'ฝูงแกะเล็กน้อยเอ๋ย อย่ากลัวเลย เพราะว่าพระบิดาของท่านชอบพระทัยที่จะประทานอาณาจักรนั้นให้แก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 33, 'จงขายของที่ท่านมีอยู่และทําทาน จงกระทําถุงใส่เงินสําหรับตนซึ่งไม่รู้เก่า คือให้มีทรัพย์สมบัติไว้ในสวรรค์ซึ่งไม่เสื่อมสูญไป ที่ขโมยมิได้เข้ามาใกล้ และที่ตัวมอดมิได้ทําลายเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 34, 'เพราะว่าทรัพย์สมบัติของท่านอยู่ที่ไหน ใจของท่านก็อยู่ที่นั่นด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 35, 'ท่านทั้งหลายจงคาดเอวของท่านไว้ และให้ตะเกียงของท่านจุดอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 36, 'พวกท่านเองจงเหมือนคนที่คอยรับนายของตน เมื่อนายจะกลับมาจากงานสมรส เพื่อเมื่อนายมาเคาะประตูแล้ว เขาจะเปิดให้นายทันทีได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 37, 'ผู้รับใช้ซึ่งนายมาพบกําลังคอยเฝ้าอยู่ก็เป็นสุข เราบอกความจริงแก่ท่านทั้งหลายว่า นายนั้นจะคาดเอวไว้และให้ผู้รับใช้เหล่านั้นเอนกายลงและนายนั้นจะมาปรนนิบัติเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 38, 'ถ้านายมาเวลาสองยามหรือสามยาม และพบผู้รับใช้อยู่อย่างนั้น ผู้รับใช้เหล่านั้นก็จะเป็นสุข');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 39, 'ให้เข้าใจอย่างนี้เถอะว่า ถ้าเจ้าของบ้านล่วงรู้ได้ว่าขโมยจะมาเวลาไหน เขาจะตื่นอยู่และระวังไม่ให้ทะลวงเรือนของเขาได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 40, 'เหตุฉะนั้น ท่านทั้งหลายจงเตรียมตัวไว้ให้พร้อมด้วย เพราะบุตรมนุษย์เสด็จมาในโมงที่ท่านไม่คิดไม่ฝัน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 41, 'ฝ่ายเปโตรทูลพระองค์ว่า “พระองค์เจ้าข้า พระองค์ได้ตรัสคําอุปมานั้นแก่พวกข้าพระองค์หรือ หรือตรัสแก่คนทั้งปวง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 42, 'องค์พระผู้เป็นเจ้าตรัสว่า “ใครเป็นคนต้นเรือนสัตย์ซื่อและฉลาด ที่นายได้ตั้งไว้เหนือพวกคนใช้สําหรับแจกอาหารตามเวลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 43, 'เมื่อนายมาพบเขากระทําอยู่อย่างนั้น ผู้รับใช้ผู้นั้นก็จะเป็นสุข');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 44, 'เราบอกความจริงแก่ท่านทั้งหลายว่า นายจะตั้งเขาไว้ให้ดูแลบรรดาข้าวของทั้งสิ้นของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 45, 'แต่ถ้าผู้รับใช้นั้นจะคิดในใจว่า ‘นายของข้าคงจะมาช้า’ แล้วจะตั้งต้นโบยตีผู้รับใช้ชายหญิงและกินดื่มเมาไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 46, 'นายของผู้รับใช้ผู้นั้นจะมาในวันที่เขาไม่คิด ในโมงที่เขาไม่รู้ และจะทําโทษเขาถึงสาหัส ทั้งจะขับไล่เขาให้ไปอยู่กับคนที่ไม่เชื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 47, 'ผู้รับใช้นั้นที่ได้รู้น้ําใจของนาย และมิได้เตรียมตัวไว้ มิได้กระทําตามน้ําใจนาย จะต้องถูกเฆี่ยนมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 48, 'แต่ผู้ที่มิได้รู้ แล้วได้กระทําสิ่งซึ่งสมจะถูกเฆี่ยน ก็จะถูกเฆี่ยนน้อย ผู้ใดได้รับมาก จะต้องเรียกเอาจากผู้นั้นมาก และผู้ใดได้รับฝากไว้มาก ก็จะต้องทวงเอาจากผู้นั้นมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 49, 'เรามาเพื่อจะทิ้งไฟลงบนแผ่นดินโลก และเราจะปรารถนาอะไรเล่า ถ้าหากไฟนั้นได้ติดขึ้นแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 50, 'เราจะต้องรับบัพติศมาอย่างหนึ่ง เราเป็นทุกข์มากจนกว่าจะสําเร็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 51, 'ท่านทั้งหลายคิดว่า เรามาเพื่อจะให้เกิดสันติภาพในโลกหรือ เราบอกท่านว่า มิใช่ แต่จะให้แตกแยกกันต่างหาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 52, 'ด้วยว่าตั้งแต่นี้ไปห้าคนในเรือนหนึ่งก็จะแตกแยกกัน คือสามต่อสองและสองต่อสาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 53, 'พ่อจะแตกแยกจากลูกชาย และลูกชายจะแตกแยกจากพ่อ แม่จากลูกสาว และลูกสาวจากแม่ แม่สามีจากลูกสะใภ้ และลูกสะใภ้จากแม่สามี”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 54, 'และพระองค์ตรัสกับประชาชนอีกว่า “เมื่อท่านทั้งหลายเห็นเมฆเกิดขึ้นในทิศตะวันตก ท่านก็กล่าวทันทีว่า ‘ฝนจะตก’ และก็เป็นอย่างนั้นจริง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 55, 'เมื่อท่านเห็นลมพัดมาแต่ทิศใต้ ท่านก็ว่า ‘จะร้อนจัด’ และก็เป็นจริง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 56, 'เจ้าคนหน้าซื่อใจคด เจ้าทั้งหลายรู้จักวิจัยความเป็นไปของแผ่นดินและท้องฟ้า แต่เหตุไฉนพวกเจ้าวิจัยความเป็นไปของยุคนี้ไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 57, 'เหตุไฉนเจ้าทั้งหลายไม่ตัดสินเอาเองว่าสิ่งไรเป็นสิ่งที่ถูก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 58, 'เพราะเมื่อเจ้ากับโจทก์พากันไปหาผู้พิพากษา จงอุตส่าห์หาช่องที่จะปรองดองกับเขาเมื่อยังอยู่กลางทาง เกลือกว่าเขาจะฉุดลากเจ้าเข้าไปถึงผู้พิพากษา และผู้พิพากษาจะมอบเจ้าไว้กับผู้คุม และผู้คุมจะขังเจ้าไว้ในเรือนจํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 59, 'เราบอกเจ้าว่า เจ้าจะออกจากที่นั่นไม่ได้จนกว่าจะได้ใช้หนี้ครบทุกสตางค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 1, 'ขณะนั้น มีบางคนอยู่ที่นั่นเล่าเรื่องชาวกาลิลี ซึ่งปีลาตเอาโลหิตของเขาระคนกับเครื่องบูชาของเขา ให้พระองค์ฟัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 2, 'พระเยซูจึงตรัสตอบเขาว่า “ท่านทั้งหลายคิดว่าชาวกาลิลีเหล่านั้นเป็นคนบาปยิ่งกว่าชาวกาลิลีอื่นๆทั้งปวง เพราะว่าเขาได้ทุกข์ทรมานอย่างนั้นหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 3, 'เราบอกท่านทั้งหลายว่า มิใช่ แต่ถ้าท่านทั้งหลายมิได้กลับใจเสียใหม่ก็จะต้องพินาศเหมือนกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 4, 'หรือสิบแปดคนนั้นซึ่งหอรบที่สิโลอัมได้พังทับเขาตายเสียนั้น ท่านทั้งหลายคิดว่า เขาเป็นคนบาปยิ่งกว่าคนทั้งปวงที่อาศัยอยู่ในกรุงเยรูซาเล็มหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 5, 'เราบอกท่านทั้งหลายว่า มิใช่ แต่ถ้าท่านทั้งหลายมิได้กลับใจเสียใหม่จะต้องพินาศเหมือนกัน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 6, 'พระองค์ตรัสคําอุปมาต่อไปนี้ว่า “คนหนึ่งมีต้นมะเดื่อต้นหนึ่งปลูกไว้ในสวนองุ่นของตน และเขามาหาผลที่ต้นนั้นแต่ไม่พบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 7, 'เขาจึงว่าแก่คนที่รักษาสวนองุ่นว่า ‘ดูเถิด เรามาหาผลที่ต้นมะเดื่อนี้ได้สามปีแล้ว แต่ไม่พบ จงโค่นมันเสีย จะให้ดินรกไปเปล่าๆทําไม’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 8, 'แต่ผู้รักษาสวนองุ่นตอบเขาว่า ‘นายเจ้าข้า ขอเอาไว้ปีนี้อีก ให้ข้าพเจ้าพรวนดินเอาปุ๋ยใส่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 9, 'แล้วถ้ามันเกิดผลก็ดีอยู่ ถ้าไม่เกิดผล ภายหลังท่านจงโค่นมันเสีย’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 10, 'พระองค์ทรงสั่งสอนอยู่ที่ธรรมศาลาแห่งหนึ่งในวันสะบาโต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 11, 'และดูเถิด มีหญิงคนหนึ่งซึ่งมีผีเข้าสิงทําให้พิการมาสิบแปดปีแล้ว หลังโกง ยืดตัวขึ้นไม่ได้เลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 12, 'เมื่อพระเยซูทอดพระเนตรเห็นเขา จึงเรียกและตรัสกับเขาว่า “หญิงเอ๋ย ตัวเจ้าหายพ้นจากโรคของเจ้าแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 13, 'พระองค์ทรงวางพระหัตถ์บนเขา และในทันใดนั้นเขาก็ยืดตัวตรงได้ และสรรเสริญพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 14, 'แต่นายธรรมศาลาก็เคืองใจ เพราะพระเยซูได้ทรงรักษาโรคในวันสะบาโต จึงว่าแก่ประชาชนว่า “มีหกวันที่ควรจะทํางาน เหตุฉะนั้นในหกวันนั้นจงมาให้รักษาโรคเถิด แต่ในวันสะบาโตนั้นอย่าเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 15, 'แต่องค์พระผู้เป็นเจ้าตรัสตอบเขาว่า “คนหน้าซื่อใจคด เจ้าทั้งหลายทุกคนได้แก้วัวแก้ลาจากคอกมันพาไปให้กินน้ําในวันสะบาโตมิใช่หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 16, 'ดูเถิด ฝ่ายหญิงผู้นี้เป็นบุตรีของอับราฮัม ซึ่งซาตานได้ผูกมัดไว้สิบแปดปีแล้ว ไม่ควรหรือที่จะให้เขาหลุดพ้นจากเครื่องจองจําอันนี้ในวันสะบาโต”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 17, 'เมื่อพระองค์ตรัสคําเหล่านั้นแล้ว บรรดาคนที่เป็นปฏิปักษ์กับพระองค์ต้องขายหน้า และประชาชนทั้งหลายก็เปรมปรีดิ์เพราะสรรพคุณความดีที่พระองค์ได้ทรงกระทํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 18, 'พระองค์จึงตรัสว่า “อาณาจักรของพระเจ้าเหมือนสิ่งใด และเราจะเปรียบอาณาจักรนั้นกับอะไรดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 19, 'ก็เปรียบเหมือนเมล็ดมัสตาร์ดเมล็ดหนึ่ง ที่คนหนึ่งได้เอาไปปลูกในสวนของตน มันงอกขึ้นเป็นต้นใหญ่ และนกในอากาศมาอาศัยอยู่ตามกิ่งก้านของต้นนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 20, 'พระองค์ตรัสอีกว่า “เราจะเปรียบอาณาจักรของพระเจ้ากับสิ่งใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 21, 'ก็เปรียบเหมือนเชื้อ ซึ่งผู้หญิงคนหนึ่งเอาเจือลงในแป้งสามถังจนแป้งนั้นฟูขึ้นทั้งหมด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 22, 'พระองค์เสด็จไปตามบ้านตามเมืองสั่งสอนเขา และทรงดําเนินไปยังกรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 23, 'มีคนหนึ่งทูลถามพระองค์ว่า “พระองค์เจ้าข้า คนที่รอดนั้นน้อยหรือ” พระองค์ตรัสแก่เขาทั้งหลายว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 24, '“จงเพียรเข้าไปทางประตูคับแคบ เพราะเราบอกท่านทั้งหลายว่า คนเป็นอันมากจะพยายามเข้าไป แต่จะเข้าไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 25, 'เมื่อเจ้าบ้านลุกขึ้นปิดประตูแล้ว และท่านทั้งหลายเริ่มยืนอยู่ภายนอกเคาะที่ประตูว่า ‘นายเจ้าข้าๆ ขอเปิดให้ข้าพเจ้าเถิด’ และเจ้าบ้านนั้นจะตอบท่านทั้งหลายว่า ‘เราไม่รู้จักเจ้าว่าเจ้ามาจากไหน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 26, 'ขณะนั้นท่านทั้งหลายเริ่มจะว่า ‘ข้าพเจ้าได้กินได้ดื่มกับท่าน และท่านได้สั่งสอนที่ถนนของพวกข้าพเจ้า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 27, 'เจ้าบ้านนั้นจะว่า ‘เราบอกเจ้าทั้งหลายว่า เราไม่รู้จักเจ้าว่าเจ้ามาจากไหน เจ้าผู้กระทําความชั่วช้า จงไปเสียให้พ้นหน้าเรา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 28, 'เมื่อท่านทั้งหลายจะเห็นอับราฮัม อิสอัค ยาโคบ และบรรดาศาสดาพยากรณ์ในอาณาจักรของพระเจ้า แต่ตัวท่านเองถูกขับไล่ไสส่งออกไปภายนอก ที่นั่นจะมีการร้องไห้ขบเขี้ยวเคี้ยวฟัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 29, 'จะมีคนมาจากทิศตะวันออก ทิศตะวันตก ทิศเหนือ ทิศใต้ จะมาเอนกายลงในอาณาจักรของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 30, 'และดูเถิด จะมีผู้ที่เป็นคนสุดท้ายกลับเป็นคนต้น และผู้ที่เป็นคนต้นกลับเป็นคนสุดท้าย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 31, 'ในวันนั้นเอง มีพวกฟาริสีบางคนมาทูลพระองค์ว่า “ท่านจงไปจากที่นี่เถิด เพราะว่าเฮโรดใคร่จะประหารชีวิตของท่านเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 32, 'พระองค์จึงตรัสแก่เขาว่า “จงไปบอกสุนัขจิ้งจอกนั้นว่า ‘ดูเถิด เราขับผีออกและรักษาโรคในวันนี้และพรุ่งนี้ แล้ววันที่สามเราจะทําการให้สําเร็จ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 33, 'แต่ว่าจําเป็นซึ่งเราจะเดินไปวันนี้ พรุ่งนี้ และมะรืนนี้ เพราะว่าศาสดาพยากรณ์จะถูกฆ่านอกกรุงเยรูซาเล็มก็หามิได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 34, 'โอ เยรูซาเล็มๆ ที่ได้ฆ่าบรรดาศาสดาพยากรณ์และเอาหินขว้างผู้ที่ได้รับใช้มาหาเจ้าให้ถึงตาย เราใคร่จะรวบรวมลูกของเจ้าไว้เนืองๆ เหมือนแม่ไก่กกลูกอยู่ใต้ปีกของมัน แต่เจ้าไม่ยอมเลยหนอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 35, 'ดูเถิด ‘บ้านเมืองของเจ้าจะถูกละทิ้งให้รกร้างแก่เจ้า’ และเราบอกความจริงแก่เจ้าทั้งหลายว่า เจ้าจะไม่ได้เห็นเราอีกจนกว่าเวลานั้นจะมาถึงเมื่อเจ้าจะกล่าวว่า ‘ขอให้พระองค์ผู้เสด็จมาในพระนามขององค์พระผู้เป็นเจ้าทรงพระเจริญ’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 1, 'ต่อมาเมื่อพระองค์เสด็จเข้าไปในบ้านของขุนนางคนหนึ่งในพวกฟาริสีในวันสะบาโต จะเสวยพระกระยาหาร เขาทั้งหลายคอยมองดูพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 2, 'ดูเถิด มีชายคนหนึ่งเป็นโรคมานน้ําอยู่ต่อพระพักตร์พระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 3, 'พระเยซูจึงตรัสถามพวกนักกฎหมายและพวกฟาริสีว่า “ถ้าจะรักษาคนป่วยในวันสะบาโตจะผิดพระราชบัญญัติหรือไม่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 4, 'เขาทั้งหลายก็นิ่งอยู่ พระองค์ทรงรับและรักษาคนนั้นให้หาย แล้วก็ให้เขาไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 5, 'พระองค์จึงตรัสกับเขาทั้งหลายว่า “คนไหนในพวกท่าน ถ้าจะมีลาหรือวัวตกบ่อ จะไม่รีบฉุดลากมันออกในวันสะบาโตหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 6, 'เขาทั้งหลายตอบข้อนี้ไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 7, 'ฝ่ายพระองค์เมื่อทอดพระเนตรเห็นคนทั้งหลายที่รับเชิญนั้นได้เลือกเอาที่อันมีเกียรติ พระองค์จึงตรัสคําอุปมาแก่เขาว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 8, '“เมื่อผู้ใดเชิญท่านไปในการเลี้ยงสมรส อย่าเอนกายลงในที่อันมีเกียรติ เกลือกว่าเขาได้เชิญคนมีเกียรติมากกว่าท่านอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 9, 'และเจ้าภาพที่ได้เชิญท่านทั้งสองนั้นจะมาพูดกับท่านว่า ‘จงให้ที่นั่งแก่ท่านผู้นี้เถิด’ แล้วเมื่อนั้นท่านจะต้องเลื่อนลงมาที่ต่ําได้รับความอดสู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 10, 'แต่เมื่อท่านได้รับเชิญแล้ว จงไปเอนกายลงในที่ต่ําก่อน เพื่อว่าเมื่อเจ้าภาพที่ได้เชิญท่านมาพูดกับท่านว่า ‘สหายเอ๋ย เชิญเลื่อนไปนั่งที่อันมีเกียรติ’ แล้วท่านจะได้เกียรติต่อหน้าคนทั้งหลายที่เอนกายลงรับประทานด้วยกันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 11, 'เพราะว่าผู้ใดที่ได้ยกตัวขึ้นจะต้องถูกเหยียดลง และผู้ที่ถ่อมตัวลงนั้นจะได้รับการยกขึ้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 12, 'ฝ่ายพระองค์ตรัสกับคนที่เชิญพระองค์ว่า “เมื่อท่านจะทําการเลี้ยง จะเป็นกลางวันหรือเวลาเย็นก็ตาม อย่าเชิญเฉพาะเหล่ามิตรสหาย หรือพี่น้องหรือญาติหรือเพื่อนบ้านที่มั่งมี เกลือกว่าเขาจะเชิญท่านอีก และท่านจะได้รับการตอบแทน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 13, 'แต่เมื่อท่านทําการเลี้ยง จงเชิญคนจน คนพิการ คนง่อย คนตาบอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 14, 'และท่านจะเป็นสุขเพราะว่าเขาไม่มีอะไรจะตอบแทนท่าน ด้วยว่าท่านจะได้รับตอบแทนเมื่อคนชอบธรรมเป็นขึ้นมาจากความตายแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 15, 'ฝ่ายคนหนึ่งที่เอนกายลงรับประทานด้วยกัน เมื่อได้ยินคําเหล่านั้นจึงทูลพระองค์ว่า “ผู้ที่จะรับประทานอาหารในอาณาจักรของพระเจ้าก็เป็นสุข”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 16, 'พระองค์ตรัสกับเขาว่า “ยังมีชายคนหนึ่งได้ทําการเลี้ยงใหญ่ และได้เชิญคนเป็นอันมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 17, 'เมื่อถึงเวลาเลี้ยงแล้ว เขาก็ใช้ผู้รับใช้ของตนไปบอกคนทั้งหลายที่ได้รับเชิญไว้แล้วว่า ‘เชิญมาเถิด เพราะสิ่งสารพัดเตรียมไว้พร้อมแล้ว’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 18, 'บรรดาคนทั้งหลายก็เริ่มพากันขอตัว คนแรกบอกเขาว่า ‘ข้าพเจ้าได้ซื้อนาไว้และจะต้องไปดูนานั้น ข้าพเจ้าขอตัวเถอะ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 19, 'อีกคนหนึ่งว่า ‘ข้าพเจ้าได้ซื้อวัวไว้ห้าคู่และจะต้องไปลองดูวัวนั้น ข้าพเจ้าขอตัวเถอะ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 20, 'อีกคนหนึ่งว่า ‘ข้าพเจ้าพึ่งแต่งงานใหม่ เหตุฉะนั้นข้าพเจ้าไปไม่ได้’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 21, 'ผู้รับใช้นั้นจึงกลับมาเล่าเนื้อความให้เจ้านายฟัง นายเจ้าของบ้านก็โกรธ จึงสั่งผู้รับใช้ว่า ‘จงออกไปโดยเร็วตามถนนใหญ่และตรอกน้อยในเมือง พาคนจน คนพิการ คนง่อย และคนตาบอดเข้ามาที่นี่’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 22, 'แล้วผู้รับใช้จึงบอกว่า ‘นายเจ้าข้า ข้าพเจ้าได้กระทําตามท่านสั่งแล้ว และยังมีที่ว่างอยู่’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 23, 'เจ้านายจึงสั่งผู้รับใช้นั้นว่า ‘จงออกไปตามทางใหญ่และรั้วต้นไม้ทั้งหลาย และเร่งเร้าเขาให้เข้ามาเพื่อเรือนของเราจะเต็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 24, 'เพราะเราบอกเจ้าว่า ในพวกคนทั้งหลายที่ได้รับเชิญไว้นั้น ไม่มีสักคนหนึ่งจะได้ลิ้มเครื่องของเราเลย’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 25, 'คนเป็นอันมากได้ไปกับพระองค์ พระองค์จึงทรงเหลียวหลังตรัสกับเขาว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 26, '“ถ้าผู้ใดมาหาเรา และไม่ชังบิดามารดา บุตรภรรยา และพี่น้องชายหญิง แม้ทั้งชีวิตของตนเองด้วย ผู้นั้นจะเป็นสาวกของเราไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 27, 'ผู้ใดมิได้แบกกางเขนของตนตามเรามา ผู้นั้นจะเป็นสาวกของเราไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 28, 'ด้วยว่าในพวกท่านมีผู้ใดเมื่อปรารถนาจะสร้างป้อม จะไม่นั่งลงคิดราคาดูเสียก่อนว่า จะมีพอสร้างให้สําเร็จได้หรือไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 29, 'เกรงว่าเมื่อลงรากแล้ว และกระทําให้สําเร็จไม่ได้ คนทั้งปวงที่เห็นจะเริ่มเยาะเย้ยเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 30, 'ว่า ‘คนนี้ตั้งต้นก่อ แต่ทําให้สําเร็จไม่ได้’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 31, 'หรือมีกษัตริย์องค์ใดเมื่อจะยกกองทัพไปทําสงครามกับกษัตริย์อื่น จะมิได้นั่งลงคิดดูก่อนหรือว่า ที่ตนมีพลทหารหมื่นหนึ่งจะสู้กับกองทัพที่ยกมารบสองหมื่นนั้นได้หรือไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 32, 'ถ้าสู้ไม่ได้ เมื่อยังอยู่ห่างกันก็จะใช้พวกทูตไปขอเป็นไมตรีกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 33, 'ก็เช่นนั้นแหละ ผู้ใดในพวกท่านที่มิได้สละสิ่งสารพัดที่ตนมีอยู่ จะเป็นสาวกของเราไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 34, 'เกลือเป็นสิ่งดี แต่ถ้าแม้นว่าเกลือนั้นหมดรสเค็มไปแล้ว จะทําให้กลับเค็มอีกอย่างไรได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 35, 'จะใช้เป็นปุ๋ยใส่ดินก็ไม่ได้ จะหมักไว้กับกองขยะทําปุ๋ยก็ไม่ได้ แต่เขาก็ทิ้งเสียเท่านั้น ใครมีหู จงฟังเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 1, 'ครั้งนั้นบรรดาคนเก็บภาษีและพวกคนบาปก็เข้ามาใกล้เพื่อจะฟังพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 2, 'ฝ่ายพวกฟาริสีและพวกธรรมาจารย์บ่นว่า “คนนี้ต้อนรับคนบาปและกินด้วยกันกับเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 3, 'พระองค์จึงตรัสคําอุปมาให้เขาฟังดังต่อไปนี้ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 4, '“ในพวกท่านมีคนใดที่มีแกะร้อยตัว และตัวหนึ่งหายไป จะไม่ละเก้าสิบเก้าตัวนั้นไว้ที่กลางทุ่งหญ้า และไปเที่ยวหาตัวที่หายไปนั้นจนกว่าจะได้พบหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 5, 'เมื่อพบแล้วเขาก็ยกขึ้นใส่บ่าแบกมาด้วยความเปรมปรีดิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 6, 'เมื่อมาถึงบ้านแล้ว จึงเชิญพวกมิตรสหายและเพื่อนบ้านให้มาพร้อมกัน พูดกับเขาว่า ‘จงยินดีกับข้าพเจ้าเถิด เพราะข้าพเจ้าได้พบแกะของข้าพเจ้าที่หายไปนั้นแล้ว’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 7, 'เราบอกท่านทั้งหลายว่า เช่นนั้นแหละ จะมีความปรีดีในสวรรค์เพราะคนบาปคนเดียวที่กลับใจใหม่ มากกว่าคนชอบธรรมเก้าสิบเก้าคนที่ไม่ต้องการกลับใจใหม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 8, 'หญิงคนใดที่มีเหรียญเงินสิบเหรียญ และเหรียญหนึ่งหายไป จะไม่จุดเทียนกวาดเรือนค้นหาให้ละเอียดจนกว่าจะพบหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 9, 'เมื่อพบแล้ว จึงเชิญเหล่ามิตรสหายและเพื่อนบ้านให้มาพร้อมกัน พูดว่า ‘จงยินดีกับข้าพเจ้าเถิด เพราะข้าพเจ้าได้พบเหรียญเงินที่หายไปนั้นแล้ว’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 10, 'เช่นนั้นแหละ เราบอกท่านทั้งหลายว่า จะมีความปรีดีในพวกทูตสวรรค์ของพระเจ้า เพราะคนบาปคนเดียวที่กลับใจใหม่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 11, 'พระองค์ตรัสว่า “ชายคนหนึ่งมีบุตรชายสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 12, 'บุตรคนน้อยพูดกับบิดาว่า ‘บิดาเจ้าข้า ขอทรัพย์ที่ตกเป็นส่วนของข้าพเจ้าเถิด’ บิดาจึงแบ่งสมบัติให้แก่บุตรทั้งสอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 13, 'ต่อมาไม่กี่วัน บุตรคนน้อยนั้นก็รวบรวมทรัพย์ทั้งหมดแล้วไปเมืองไกล และได้ผลาญทรัพย์ของตนที่นั่นด้วยการเป็นนักเลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 14, 'เมื่อใช้ทรัพย์หมดแล้วก็เกิดกันดารอาหารยิ่งนักทั่วเมืองนั้น เขาจึงเริ่มขัดสน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 15, 'เขาไปอาศัยอยู่กับชาวเมืองนั้นคนหนึ่ง และคนนั้นก็ใช้เขาไปเลี้ยงหมูที่ทุ่งนา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 16, 'เขาใคร่จะได้อิ่มท้องด้วยฝักถั่วที่หมูกินนั้น แต่ไม่มีใครให้อะไรเขากิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 17, 'เมื่อเขารู้สํานึกตัวแล้วจึงพูดว่า ‘ลูกจ้างของบิดาเรามีมาก ยังมีอาหารกินอิ่มและเหลืออีก ส่วนเราจะมาตายเสียเพราะอดอาหาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 18, 'จําเราจะลุกขึ้นไปหาบิดาเรา และพูดกับท่านว่า “บิดาเจ้าข้า ข้าพเจ้าได้ทําผิดต่อสวรรค์และทําผิดต่อหน้าท่านด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 19, 'ข้าพเจ้าไม่สมควรจะได้ชื่อว่าเป็นลูกของท่านต่อไป ขอท่านให้ข้าพเจ้าเป็นเหมือนลูกจ้างของท่านคนหนึ่งเถิด”’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 20, 'แล้วเขาก็ลุกขึ้นไปหาบิดาของตน แต่เมื่อเขายังอยู่แต่ไกล บิดาแลเห็นเขาก็มีความเมตตา จึงวิ่งออกไปกอดคอจุบเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 21, 'ฝ่ายบุตรนั้นจึงกล่าวแก่บิดาว่า ‘บิดาเจ้าข้า ข้าพเจ้าได้ทําผิดต่อสวรรค์และต่อสายตาของท่านด้วย ข้าพเจ้าไม่สมควรจะได้ชื่อว่าเป็นลูกของท่านอีกต่อไป’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 22, 'แต่บิดาสั่งผู้รับใช้ของตนว่า ‘จงรีบไปเอาเสื้ออย่างดีที่สุดมาสวมให้เขา และเอาแหวนมาสวมนิ้วมือ กับเอารองเท้ามาสวมให้เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 23, 'จงเอาลูกวัวอ้วนพีมาฆ่าเลี้ยงกัน เพื่อความรื่นเริงยินดีเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 24, 'เพราะว่าลูกของเราคนนี้ตายแล้ว แต่กลับเป็นอีก หายไปแล้ว แต่ได้พบกันอีก’ เขาทั้งหลายต่างก็เริ่มมีความรื่นเริงยินดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 25, 'ฝ่ายบุตรคนใหญ่นั้นกําลังอยู่ที่ทุ่งนา เมื่อเขากลับมาใกล้บ้านแล้วก็ได้ยินเสียงมโหรีและเต้นรํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 26, 'เขาจึงเรียกผู้รับใช้คนหนึ่งมาถามว่า เขาทําอะไรกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 27, 'ผู้รับใช้จึงตอบเขาว่า ‘น้องของท่านกลับมาแล้ว และบิดาได้ให้ฆ่าลูกวัวอ้วนพี เพราะได้ลูกกลับมาโดยสวัสดิภาพ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 28, 'ฝ่ายพี่ชายก็โกรธไม่ยอมเข้าไป บิดาจึงออกมาชักชวนเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 29, 'แต่เขาบอกบิดาว่า ‘ดูเถิด ข้าพเจ้าได้ปรนนิบัติท่านกี่ปีมาแล้ว และมิได้ละเมิดคําบัญชาของท่านสักข้อหนึ่งเลย แม้แต่เพียงลูกแพะสักตัวหนึ่งท่านก็ยังไม่เคยให้ข้าพเจ้า เพื่อจะเลี้ยงกันเป็นที่รื่นเริงยินดีกับเพื่อนฝูงของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 30, 'แต่เมื่อลูกคนนี้ของท่าน ผู้ได้ผลาญสิ่งเลี้ยงชีพของท่านโดยคบหญิงโสเภณีมาแล้ว ท่านยังได้ฆ่าลูกวัวอ้วนพีเลี้ยงเขา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 31, 'บิดาจึงตอบเขาว่า ‘ลูกเอ๋ย เจ้าอยู่กับเราเสมอ และสิ่งของทั้งหมดของเราก็เป็นของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 32, 'แต่สมควรที่เราจะรื่นเริงและยินดี เพราะน้องของเจ้าคนนี้ตายแล้ว แต่กลับเป็นขึ้นอีก หายไปแล้วแต่ได้พบกันอีก’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 1, 'พระองค์ตรัสกับเหล่าสาวกของพระองค์อีกว่า “ยังมีเศรษฐีคนหนึ่งที่มีคนต้นเรือน และมีคนมาฟ้องเศรษฐีว่า คนต้นเรือนนั้นผลาญสมบัติของท่านเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 2, 'เศรษฐีจึงเรียกคนต้นเรือนนั้นมาว่าแก่เขาว่า ‘เรื่องราวที่เราได้ยินเกี่ยวกับเจ้านั้นเป็นอย่างไร จงส่งบัญชีหน้าที่ต้นเรือนของเจ้า เพราะว่าเจ้าจะเป็นคนต้นเรือนต่อไปไม่ได้’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 3, 'คนต้นเรือนนั้นคิดในใจว่า ‘เราจะทําอะไรดี เพราะนายจะถอดเราเสียจากหน้าที่ต้นเรือน จะขุดดินก็ไม่มีกําลัง จะขอทานก็อายเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 4, 'เรารู้แล้วว่าจะทําอะไรดี เพื่อเมื่อเราถูกถอดจากหน้าที่ต้นเรือนแล้ว เขาจะรับเราไว้ในเรือนของเขาได้’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 5, 'คนนั้นจึงเรียกลูกหนี้ของนายมาทุกคน แล้วถามคนแรกว่า ‘ท่านเป็นหนี้นายข้าพเจ้ากี่มากน้อย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 6, 'เขาตอบว่า ‘เป็นหนี้น้ํามันร้อยถัง’ คนต้นเรือนจึงบอกเขาว่า ‘เอาบัญชีของท่านนั่งลงเร็วๆแล้วแก้เป็นห้าสิบถัง’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 7, 'แล้วเขาก็ถามอีกคนหนึ่งว่า ‘ท่านเป็นหนี้กี่มากน้อย’ เขาตอบว่า ‘เป็นหนี้ข้าวสาลีร้อยกระสอบ’ คนต้นเรือนจึงบอกเขาว่า ‘จงเอาบัญชีของท่านแก้เป็นแปดสิบ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 8, 'แล้วเศรษฐีก็ชมคนต้นเรือนอธรรมนั้น เพราะเขาได้กระทําโดยความฉลาด ด้วยว่าลูกทั้งหลายของโลกนี้ ตามกาลสมัยเดียวกัน เขาใช้สติปัญญาฉลาดกว่าลูกของความสว่างอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 9, 'เราบอกท่านทั้งหลายว่า จงกระทําตัวให้มีมิตรสหายด้วยทรัพย์สมบัติอธรรม เพื่อเมื่อท่านพลาดไป เขาทั้งหลายจะได้ต้อนรับท่านไว้ในที่อาศัยอันถาวรเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 10, 'คนที่สัตย์ซื่อในของเล็กน้อยที่สุดจะสัตย์ซื่อในของมากด้วย และคนที่อสัตย์ในของเล็กน้อยที่สุดจะอสัตย์ในของมากเช่นกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 11, 'เหตุฉะนั้น ถ้าท่านทั้งหลายไม่สัตย์ซื่อในทรัพย์สมบัติอธรรม ใครจะมอบทรัพย์สมบัติอันแท้ให้แก่ท่านเล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 12, 'และถ้าท่านทั้งหลายมิได้สัตย์ซื่อในของของคนอื่น ใครจะมอบทรัพย์อันแท้ให้เป็นของของท่านเล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 13, 'ไม่มีผู้รับใช้ผู้ใดจะปรนนิบัตินายสองนายได้ เพราะว่าจะชังนายข้างหนึ่ง และจะรักนายอีกข้างหนึ่งหรือจะนับถือนายฝ่ายหนึ่ง และจะดูหมิ่นนายอีกฝ่ายหนึ่ง ท่านจะปรนนิบัติพระเจ้าและจะปรนนิบัติเงินทองพร้อมกันไม่ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 14, 'ฝ่ายพวกฟาริสีที่มีใจรักเงิน เมื่อได้ยินคําเหล่านั้นแล้วจึงเยาะเย้ยพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 15, 'แต่พระองค์ตรัสแก่เขาว่า “เจ้าทั้งหลายเป็นผู้ที่ทําทีดูเป็นคนชอบธรรมต่อหน้ามนุษย์ แต่พระเจ้าทรงทราบจิตใจของเจ้าทั้งหลาย ด้วยว่าซึ่งเป็นที่นับถือมากท่ามกลางมนุษย์ ก็ยังเป็นที่สะอิดสะเอียนในสายพระเนตรของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 16, 'มีพระราชบัญญัติและศาสดาพยากรณ์มาจนถึงยอห์น ตั้งแต่นั้นมาเขาก็ประกาศเรื่องอาณาจักรของพระเจ้า และคนทั้งปวงก็ชิงกันเข้าไปในอาณาจักรนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 17, 'ฟ้าและดินจะล่วงไปก็ง่ายกว่าที่พระราชบัญญัติสักจุดหนึ่งจะขาดตกไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 18, 'ผู้ใดหย่าภรรยาของตน แล้วไปมีภรรยาใหม่ก็ผิดประเวณี และผู้ใดรับหญิงที่สามีได้หย่าแล้วมาเป็นภรรยาของตนก็ผิดประเวณีด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 19, 'ยังมีเศรษฐีคนหนึ่งนุ่งห่มผ้าสีม่วงและผ้าป่านเนื้อละเอียด รับประทานอาหารอย่างประณีตทุกวันๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 20, 'และมีคนขอทานคนหนึ่งชื่อลาซารัส เป็นแผลทั้งตัว นอนอยู่ที่ประตูรั้วบ้านของเศรษฐี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 21, 'และเขาใคร่จะกินเศษอาหารที่ตกจากโต๊ะของเศรษฐีนั้น แม้สุนัขก็มาเลียแผลของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 22, 'อยู่มาคนขอทานนั้นตายและเหล่าทูตสวรรค์ได้นําเขาไปไว้ที่อกของอับราฮัม ฝ่ายเศรษฐีนั้นก็ตายด้วย และเขาก็ฝังไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 23, 'แล้วเมื่ออยู่ในนรกเป็นทุกข์ทรมานยิ่งนัก เศรษฐีนั้นจึงแหงนดูเห็นอับราฮัมอยู่แต่ไกล และลาซารัสอยู่ที่อกของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 24, 'เศรษฐีจึงร้องว่า ‘อับราฮัมบิดาเจ้าข้า ขอเอ็นดูข้าพเจ้าเถิด ขอใช้ลาซารัสมาเพื่อจะเอาปลายนิ้วจุ่มน้ํามาแตะลิ้นของข้าพเจ้าให้เย็น ด้วยว่าข้าพเจ้าตรําทุกข์ทรมานอยู่ในเปลวไฟนี้’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 25, 'แต่อับราฮัมตอบว่า ‘ลูกเอ๋ย เจ้าจงระลึกว่าเมื่อเจ้ายังมีชีวิตอยู่ เจ้าได้ของดีสําหรับตัว และลาซารัสได้ของเลว แต่เดี๋ยวนี้เขาได้รับความเล้าโลม แต่เจ้าได้รับความทุกข์ทรมาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 26, 'นอกจากนั้น ระหว่างพวกเรากับพวกเจ้ามีเหวใหญ่ตั้งขวางอยู่ เพื่อว่าถ้าผู้ใดปรารถนาจะข้ามไปจากที่นี่ถึงเจ้าก็ไม่ได้ หรือถ้าจะข้ามจากที่นั่นมาถึงเราก็ไม่ได้’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 27, 'เศรษฐีนั้นจึงว่า ‘บิดาเจ้าข้า ถ้าอย่างนั้นขอท่านใช้ลาซารัสไปยังบ้านบิดาของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 28, 'เพราะว่าข้าพเจ้ามีพี่น้องห้าคน ให้ลาซารัสเป็นพยานแก่เขา เพื่อมิให้เขามาถึงที่ทรมานนี้’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 29, 'แต่อับราฮัมตอบเขาว่า ‘เขามีโมเสสและพวกศาสดาพยากรณ์นั้นแล้ว ให้เขาฟังคนเหล่านั้นเถิด’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 30, 'เศรษฐีนั้นจึงว่า ‘มิได้ อับราฮัมบิดาเจ้าข้า แต่ถ้าคนหนึ่งจากหมู่คนตายไปหาเขา เขาจะกลับใจเสียใหม่’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 31, 'อับราฮัมจึงตอบเขาว่า ‘ถ้าเขาไม่ฟังโมเสสและพวกศาสดาพยากรณ์ แม้คนหนึ่งจะเป็นขึ้นมาจากความตาย เขาก็จะยังไม่เชื่อ’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 1, 'พระองค์ตรัสกับเหล่าสาวกอีกว่า “จําเป็นต้องมีเหตุให้หลงผิด แต่วิบัติแก่ผู้ที่ก่อเหตุให้เกิดความหลงผิดนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 2, 'ถ้าเอาหินโม่แป้งผูกคอคนนั้นถ่วงเสียที่ทะเล ก็ดีกว่าให้เขานําผู้เล็กน้อยเหล่านี้คนหนึ่งให้หลงผิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 3, 'จงระวังตัวให้ดี ถ้าพี่น้องทําการละเมิดต่อท่าน จงเตือนเขา และถ้าเขากลับใจแล้ว จงยกโทษให้เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 4, 'แม้เขาจะทําการละเมิดต่อท่านวันหนึ่งเจ็ดหน และจะกลับมาหาท่านทั้งเจ็ดหนในวันเดียวนั้น แล้วว่า ‘ฉันกลับใจแล้ว’ จงยกโทษให้เขาเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 5, 'ฝ่ายอัครสาวกทูลองค์พระผู้เป็นเจ้าว่า “ขอพระองค์โปรดให้ความเชื่อของพวกข้าพเจ้ามากยิ่งขึ้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 6, 'องค์พระผู้เป็นเจ้าจึงตรัสว่า “ถ้าพวกท่านมีความเชื่อเท่าเมล็ดมัสตาร์ดเมล็ดหนึ่ง ท่านก็จะสั่งต้นสุกะมินนี้ได้ว่า ‘จงถอนขึ้นออกไปปักในทะเล’ และมันจะเชื่อฟังท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 7, 'ในพวกท่านมีคนใดที่มีผู้รับใช้ไถนาหรือเลี้ยงแกะ เมื่อผู้รับใช้คนนั้นกลับมาจากทุ่งนาจะบอกเขาทีเดียวว่า ‘เชิญเอนกายลงรับประทานเถิด’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 8, 'หรือจะไม่บอกเขาว่า ‘จงหาให้เรารับประทานและคาดเอวไว้ปรนนิบัติเรา จนเราจะกินและดื่มอิ่มแล้ว และภายหลังเจ้าจงค่อยกินและดื่มเถิด’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 9, 'นายจะขอบใจผู้รับใช้นั้นเพราะผู้รับใช้ได้ทําสิ่งต่างๆตามคําสั่งหรือ เราคิดว่าไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 10, 'ฉันใดก็ดี เมื่อท่านทั้งหลายได้กระทําสิ่งสารพัดซึ่งทรงบัญชาไว้แก่ท่านนั้น ก็จงพูดด้วยว่า ‘ข้าพเจ้าทั้งหลายเป็นผู้รับใช้ที่ไม่มีบุญคุณต่อนาย ข้าพเจ้าได้กระทําตามหน้าที่ซึ่งข้าพเจ้าควรกระทําเท่านั้น’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 11, 'ต่อมาเมื่อพระองค์กําลังเสด็จไปยังกรุงเยรูซาเล็ม พระองค์จึงเสด็จเลียบระหว่างแคว้นสะมาเรียและกาลิลี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 12, 'เมื่อพระองค์เสด็จเข้าไปในหมู่บ้านแห่งหนึ่ง มีคนเป็นโรคเรื้อนสิบคนมาพบพระองค์ยืนอยู่แต่ไกล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 13, 'และส่งเสียงร้องว่า “เยซูนายเจ้าข้า โปรดได้เมตตาข้าพเจ้าทั้งหลายเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 14, 'เมื่อพระองค์ทอดพระเนตรเห็นแล้วจึงตรัสแก่เขาว่า “จงไปแสดงตัวแก่พวกปุโรหิตเถิด” ต่อมาเมื่อกําลังเดินไป เขาทั้งหลายก็หายสะอาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 15, 'ฝ่ายคนหนึ่งในพวกนั้น เมื่อเห็นว่าตัวหายโรคแล้ว จึงกลับมาสรรเสริญพระเจ้าด้วยเสียงดัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 16, 'และกราบลงที่พระบาทของพระองค์ ขอบพระคุณพระองค์ คนนั้นเป็นชาวสะมาเรีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 17, 'ฝ่ายพระเยซูตรัสว่า “มีสิบคนหายสะอาดมิใช่หรือ แต่เก้าคนนั้นอยู่ที่ไหน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 18, 'ไม่เห็นผู้ใดกลับมาสรรเสริญพระเจ้า เว้นไว้แต่คนต่างชาติคนนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 19, 'แล้วพระองค์ตรัสกับคนนั้นว่า “จงลุกขึ้นไปเถิด ความเชื่อของเจ้าได้กระทําให้ตัวเจ้าหายปกติ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 20, 'เมื่อพวกฟาริสีทูลถามพระองค์ว่า อาณาจักรของพระเจ้าจะมาถึงเมื่อไร พระองค์ตรัสตอบเขาว่า “อาณาจักรของพระเจ้าไม่มาโดยให้เป็นที่สังเกตได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 21, 'และเขาจะไม่พูดว่า ‘มาดูนี่’ หรือ ‘ไปดูโน่น’ เพราะ ดูเถิด อาณาจักรของพระเจ้าอยู่ภายในท่านทั้งหลาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 22, 'พระองค์ตรัสกับเหล่าสาวกว่า “วันนั้นจะมาถึงเมื่อท่านทั้งหลายใคร่จะเห็นวันของบุตรมนุษย์สักวันหนึ่ง แต่จะไม่เห็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 23, 'เขาจะพูดกับท่านทั้งหลายว่า ‘มาดูนี่’ หรือ ‘ไปดูโน่น’ อย่าออกไป อย่าตามเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 24, 'ด้วยว่าเปรียบเหมือนฟ้าแลบ เมื่อแลบออกจากฟ้าข้างหนึ่ง ก็ส่องสว่างไปถึงฟ้าอีกข้างหนึ่ง บุตรมนุษย์ก็จะเป็นอย่างนั้นแหละในวันของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 25, 'ก่อนนั้นจําเป็นที่พระองค์จะต้องทนทุกข์ทรมานหลายประการ และคนยุคนี้จะปฏิเสธพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 26, 'ในสมัยของโนอาห์เหตุการณ์ได้เป็นมาแล้วอย่างไร ในสมัยของบุตรมนุษย์ก็จะเป็นไปอย่างนั้นด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 27, 'เขาได้กินและดื่ม ได้สมรสกันและได้ยกให้เป็นสามีภรรยากัน จนถึงวันนั้นที่โนอาห์ได้เข้าในนาวา และน้ําได้มาท่วมล้างผลาญเขาเสียทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 28, 'ในสมัยของโลทก็เหมือนกัน เขาได้กินดื่ม ซื้อขาย หว่านปลูก ก่อสร้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 29, 'แต่ในวันนั้นที่โลทออกไปจากเมืองโสโดม ไฟและกํามะถันได้ตกจากฟ้ามาเผาผลาญเขาเสียทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 30, 'ในวันที่บุตรมนุษย์จะมาปรากฏก็เป็นเหมือนอย่างนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 31, 'ในวันนั้นคนที่อยู่บนดาดฟ้าหลังคาบ้าน และของของเขาอยู่ในบ้าน อย่าให้เขาลงมาเก็บของนั้นไป และคนที่อยู่ตามทุ่งนา อย่าให้เขากลับมาเหมือนกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 32, 'จงระลึกถึงภรรยาของโลทนั้นเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 33, 'ผู้ใดอุตส่าห์เอาชีวิตของตนรอด ผู้นั้นจะเสียชีวิต แต่ผู้ใดจะสู้เสียชีวิต ผู้นั้นจะได้ชีวิตรอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 34, 'เราบอกท่านทั้งหลายว่า ในคืนวันนั้นจะมีชายสองคนนอนในที่นอนอันเดียวกัน จะทรงรับคนหนึ่ง จะทรงละคนหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 35, 'ผู้หญิงสองคนจะโม่แป้งด้วยกัน จะทรงรับคนหนึ่ง จะทรงละคนหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 36, 'ชายสองคนจะอยู่ในทุ่งนา จะทรงรับคนหนึ่ง จะทรงละคนหนึ่ง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 37, 'เขาจึงทูลถามพระองค์ว่า “จะเกิดขึ้นที่ไหน พระองค์เจ้าข้า” พระองค์ตรัสตอบเขาว่า “ซากศพอยู่ที่ไหน ฝูงนกอินทรีจะตอมกันอยู่ที่นั่น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 1, 'พระองค์ตรัสคําอุปมาเรื่องหนึ่งให้เขาฟังเพื่อสอนว่า คนทั้งหลายควรอธิษฐานอยู่เสมอ ไม่อ่อนระอาใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 2, 'พระองค์ตรัสว่า “ในนครหนึ่งมีผู้พิพากษาคนหนึ่งที่มิได้เกรงกลัวพระเจ้า และมิได้เห็นแก่มนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 3, 'ในนครนั้นมีหญิงม่ายคนหนึ่งมาหาผู้พิพากษาผู้นั้นพูดว่า ‘ขอแก้แค้นศัตรูของข้าพเจ้าให้ข้าพเจ้าเถิด’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 4, 'ฝ่ายผู้พิพากษานั้นไม่ยอมทําจนช้านาน แต่ภายหลังเขานึกในใจว่า ‘แม้ว่าเราไม่เกรงกลัวพระเจ้าและไม่เห็นแก่มนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 5, 'แต่เพราะหญิงม่ายคนนี้มากวนเราให้ลําบาก เราจะแก้แค้นให้เขา เพื่อมิให้นางมารบกวนบ่อยๆให้เรารําคาญใจ’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 6, 'และองค์พระผู้เป็นเจ้าตรัสว่า “จงฟังคําที่ผู้พิพากษาอธรรมนี้ได้พูด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 7, 'พระเจ้าจะไม่ทรงแก้แค้นให้คนที่พระองค์ได้ทรงเลือกไว้ ผู้ร้องถึงพระองค์ทั้งกลางวันและกลางคืนหรือ พระองค์จะอดพระทัยไว้ช้านานหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 8, 'เราบอกท่านทั้งหลายว่า พระองค์จะทรงแก้แค้นให้เขาโดยเร็ว แต่เมื่อบุตรมนุษย์มา ท่านจะพบความเชื่อในแผ่นดินโลกหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 9, 'สําหรับบางคนที่ไว้ใจในตัวเองว่าเป็นคนชอบธรรม และได้ดูถูกคนอื่นนั้น พระองค์ตรัสคําอุปมานี้ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 10, '“มีชายสองคนขึ้นไปอธิษฐานในพระวิหาร คนหนึ่งเป็นพวกฟาริสี และคนหนึ่งเป็นพวกเก็บภาษี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 11, 'คนฟาริสีนั้นยืนนึกในใจของตนอธิษฐานว่า ‘ข้าแต่พระเจ้า ข้าพระองค์ขอบพระคุณพระองค์ ที่ข้าพระองค์ไม่เหมือนคนอื่นซึ่งเป็นคนฉ้อโกง คนอธรรม และคนล่วงประเวณี และไม่เหมือนคนเก็บภาษีคนนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 12, 'ในสัปดาห์หนึ่งข้าพระองค์ถืออดอาหารสองหน และของสารพัดซึ่งข้าพระองค์หาได้ ข้าพระองค์ได้เอาสิบชักหนึ่งมาถวาย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 13, 'ฝ่ายคนเก็บภาษีนั้นยืนอยู่แต่ไกล ไม่แหงนดูฟ้า แต่ตีอกของตนว่า ‘ข้าแต่พระเจ้า ขอทรงโปรดพระเมตตาแก่ข้าพระองค์ผู้เป็นคนบาปเถิด’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 14, 'เราบอกท่านทั้งหลายว่า คนนี้แหละเมื่อกลับลงไปยังบ้านของตนก็นับว่าชอบธรรมยิ่งกว่าอีกคนหนึ่งนั้น เพราะว่าทุกคนที่ยกตัวขึ้นจะต้องถูกเหยียดลง แต่ทุกคนที่ได้ถ่อมตัวลงจะต้องถูกยกขึ้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 15, 'แล้วเขาอุ้มทารกมาหาพระองค์ เพื่อจะให้พระองค์ทรงถูกต้องทารกนั้น แต่เหล่าสาวกเมื่อเห็นเข้าก็ห้ามเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 16, 'แต่พระเยซูทรงเรียกเขามา แล้วตรัสว่า “จงยอมให้เด็กเล็กๆเข้ามาหาเรา อย่าห้ามเขาเลย เพราะว่าอาณาจักรของพระเจ้าย่อมเป็นของคนเช่นเด็กเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 17, 'เราบอกความจริงแก่ท่านทั้งหลายว่า ผู้หนึ่งผู้ใดมิได้รับอาณาจักรของพระเจ้าเหมือนเด็กเล็กๆ ผู้นั้นจะเข้าในอาณาจักรนั้นไม่ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 18, 'มีขุนนางผู้หนึ่งทูลถามพระองค์ว่า “ท่านอาจารย์ผู้ประเสริฐ ข้าพเจ้าจะทําประการใดจึงจะได้ชีวิตนิรันดร์เป็นมรดก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 19, 'พระเยซูตรัสถามคนนั้นว่า “ท่านเรียกเราว่าประเสริฐทําไม ไม่มีใครประเสริฐเว้นแต่พระเจ้าองค์เดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 20, 'ท่านรู้จักพระบัญญัติแล้วซึ่งว่า ‘อย่าล่วงประเวณีผัวเมียเขา อย่าฆ่าคน อย่าลักทรัพย์ อย่าเป็นพยานเท็จ จงให้เกียรติแก่บิดามารดาของตน’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 21, 'คนนั้นจึงทูลว่า “ข้อเหล่านี้ข้าพเจ้าได้ถือรักษาไว้ตั้งแต่เป็นเด็กๆมา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 22, 'เมื่อพระเยซูทรงได้ยินอย่างนั้นพระองค์ตรัสแก่เขาว่า “ท่านยังขาดสิ่งหนึ่ง จงไปขายบรรดาสิ่งของซึ่งท่านมีอยู่และแจกจ่ายให้คนอนาถา ท่านจึงจะมีทรัพย์สมบัติในสวรรค์ แล้วจงตามเรามา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 23, 'แต่เมื่อเขาได้ยินอย่างนั้นก็เป็นทุกข์นัก เพราะเขาเป็นคนมั่งมีมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 24, 'เมื่อพระเยซูทอดพระเนตรเห็นเขาเป็นทุกข์นัก พระองค์จึงตรัสว่า “คนมั่งมีจะเข้าในอาณาจักรของพระเจ้าก็ยากจริงหนา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 25, 'เพราะว่าตัวอูฐจะรอดรูเข็มก็ง่ายกว่าคนมั่งมีจะเข้าในอาณาจักรของพระเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 26, 'ฝ่ายคนทั้งหลายที่ได้ยินจึงว่า “ถ้าอย่างนั้นใครจะรอดได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 27, 'แต่พระองค์ตรัสว่า “สิ่งที่มนุษย์ทําไม่ได้ พระเจ้าทรงกระทําได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 28, 'เปโตรจึงทูลว่า “ดูเถิด ข้าพระองค์ทั้งหลายได้สละทิ้งสิ่งสารพัด ติดตามพระองค์มา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 29, 'พระองค์จึงตรัสกับเขาว่า “เราบอกความจริงแก่ท่านทั้งหลายว่า ถ้าผู้ใดได้สละเรือน หรือบิดามารดา หรือพี่น้อง หรือภรรยา หรือบุตร เพราะเห็นแก่อาณาจักรของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 30, 'ในเวลานี้ผู้นั้นจะได้รับตอบแทนหลายเท่า และในโลกหน้าจะได้ชีวิตนิรันดร์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 31, 'พระองค์ทรงพาสาวกสิบสองคนไปกับพระองค์แล้วตรัสกับเขาว่า “ดูเถิด เราทั้งหลายจะขึ้นไปยังกรุงเยรูซาเล็ม และสิ่งสารพัดซึ่งเหล่าศาสดาพยากรณ์ได้เขียนไว้ว่าด้วยบุตรมนุษย์นั้นจะสําเร็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 32, 'ด้วยว่าบุตรมนุษย์นั้นจะต้องถูกมอบไว้กับคนต่างชาติ และเขาจะเยาะเย้ยท่าน กระทําหยาบคายแก่ท่าน ถ่มน้ําลายรดท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 33, 'เขาจะโบยตีและฆ่าท่านเสีย แล้วในวันที่สามท่านจะเป็นขึ้นมาใหม่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 34, 'ฝ่ายเหล่าสาวกมิได้เข้าใจในสิ่งเหล่านั้นเลย และคํานั้นก็ถูกซ่อนไว้จากเขา และเขาไม่รู้เนื้อความซึ่งพระองค์ตรัสนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 35, 'ต่อมาเมื่อพระองค์เสด็จมาใกล้เมืองเยรีโค มีคนตาบอดคนหนึ่งนั่งขอทานอยู่ริมหนทาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 36, 'เมื่อเขาได้ยินเสียงประชาชนเดินผ่านไป จึงถามว่าเรื่องอะไรกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 37, 'คนพวกนั้นจึงบอกเขาว่า พระเยซูชาวนาซาเร็ธเสด็จไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 38, 'คนตาบอดนั้นจึงร้องว่า “ท่านเยซู บุตรดาวิดเจ้าข้า ขอทรงเมตตาข้าพระองค์เถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 39, 'คนที่เดินไปข้างหน้านั้นจึงห้ามเขาให้นิ่ง แต่เขายิ่งร้องขึ้นว่า “บุตรดาวิดเจ้าข้า ขอทรงเมตตาข้าพระองค์เถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 40, 'พระเยซูทรงประทับยืนอยู่สั่งให้พาคนตาบอดมาหาพระองค์ เมื่อเขามาใกล้แล้ว พระองค์ทรงถามเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 41, 'ว่า “เจ้าปรารถนาจะให้เราทําอะไรให้เจ้า” เขาทูลว่า “พระองค์เจ้าข้า โปรดให้ข้าพระองค์เห็นได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 42, 'พระเยซูตรัสแก่เขาว่า “จงเห็นเถิด ความเชื่อของเจ้าได้กระทําให้ตัวเจ้าหายปกติ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 43, 'ในทันใดนั้นเขาก็เห็นได้ และตามพระองค์ไปพลางถวายเกียรติแด่พระเจ้า และเมื่อคนทั้งปวงได้เห็นเช่นนั้นก็สรรเสริญพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 1, 'ฝ่ายพระเยซูจึงเสด็จเข้าเมืองเยรีโคและกําลังจะทรงผ่านไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 2, 'ดูเถิด มีชายคนหนึ่งชื่อศักเคียส ผู้ซึ่งเป็นนายด่านภาษีและเป็นคนมั่งมี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 3, 'ศักเคียสพยายามจะดูให้เห็นพระเยซูว่าพระองค์เป็นผู้ใด แต่ดูไม่เห็นเพราะคนแน่น ด้วยเขาเป็นคนเตี้ย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 4, 'เขาจึงวิ่งไปข้างหน้าขึ้นต้นมะเดื่อเพื่อจะได้เห็นพระองค์ เพราะว่าพระองค์จะเสด็จไปทางนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 5, 'เมื่อพระเยซูเสด็จมาถึงที่นั่น พระองค์ทรงแหงนพระพักตร์ดูศักเคียสแล้วตรัสแก่เขาว่า “ศักเคียสเอ๋ย จงรีบลงมา เพราะว่าเราจะต้องพักอยู่ในบ้านของท่านวันนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 6, 'แล้วเขาก็รีบลงมาต้อนรับพระองค์ด้วยความปรีดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 7, 'เมื่อคนทั้งปวงเห็นแล้วเขาก็พากันบ่นว่า “พระองค์เข้าไปพักอยู่กับคนบาป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 8, 'ฝ่ายศักเคียสยืนทูลองค์พระผู้เป็นเจ้าว่า “ดูเถิด พระองค์เจ้าข้า ทรัพย์สิ่งของของข้าพระองค์ ข้าพระองค์ยอมให้คนอนาถาครึ่งหนึ่ง และถ้าข้าพระองค์ได้ฉ้อโกงของของผู้ใด ข้าพระองค์ยอมคืนให้เขาสี่เท่า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 9, 'พระเยซูตรัสกับเขาว่า “วันนี้ความรอดมาถึงครอบครัวนี้แล้ว เพราะคนนี้เป็นลูกของอับราฮัมด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 10, 'เพราะว่าบุตรมนุษย์ได้มาเพื่อจะแสวงหาและช่วยผู้ที่หลงหายไปนั้นให้รอด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 11, 'เมื่อเขาทั้งหลายได้ยินเหตุการณ์นั้น พระองค์ได้ตรัสคําอุปมาเรื่องหนึ่งให้เขาฟังต่อไป เพราะพระองค์เสด็จมาใกล้กรุงเยรูซาเล็มแล้ว และเพราะเขาทั้งหลายคิดว่าอาณาจักรของพระเจ้าจะปรากฏโดยพลัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 12, 'เหตุฉะนั้นพระองค์จึงตรัสว่า “มีเจ้านายองค์หนึ่งไปเมืองไกล เพื่อจะรับอํานาจมาครองอาณาจักรแล้วจะกลับมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 13, 'ท่านจึงเรียกผู้รับใช้ของท่านสิบคนมามอบเงินไว้แก่เขาสิบมินา สั่งเขาว่า ‘จงเอาไปค้าขายจนเราจะกลับมา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 14, 'แต่ชาวเมืองชังท่านผู้นั้น จึงใช้คณะทูตตามไปทูลท่านว่า ‘เราไม่ต้องการให้ผู้นี้ครอบครองเรา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 15, 'ต่อมาเมื่อท่านได้รับอํานาจครองอาณาจักรกลับมาแล้ว ท่านจึงสั่งให้เรียกผู้รับใช้ทั้งหลายที่ท่านได้ให้เงินไว้นั้นมา เพื่อจะได้รู้ว่าเขาทุกคนค้าขายได้กําไรกี่มากน้อย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 16, 'ฝ่ายคนแรกมาบอกว่า ‘ท่านเจ้าข้า เงินมินาหนึ่งของท่านได้กําไรสิบมินา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 17, 'ท่านจึงพูดกับเขาว่า ‘ดีแล้ว เจ้าเป็นผู้รับใช้ที่ดี เพราะเจ้าสัตย์ซื่อในของเล็กน้อย เจ้าจงมีอํานาจครอบครองสิบเมืองเถิด’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 18, 'คนที่สองมาบอกว่า ‘ท่านเจ้าข้า เงินมินาหนึ่งของท่านได้กําไรห้ามินา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 19, 'ท่านจึงพูดกับเขาเหมือนกันว่า ‘เจ้าจงครอบครองห้าเมืองเถิด’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 20, 'อีกคนหนึ่งมาบอกว่า ‘ท่านเจ้าข้า ดูเถิด นี่เงินมินาหนึ่งของท่าน ซึ่งข้าพเจ้าได้เอาผ้าห่อเก็บไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 21, 'เพราะข้าพเจ้ากลัวท่าน ด้วยว่าท่านเป็นคนเข้มงวด ท่านเก็บผลซึ่งท่านมิได้ลงแรง และเกี่ยวที่ท่านมิได้หว่าน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 22, 'ท่านจึงตอบเขาว่า ‘เจ้าผู้รับใช้ชั่ว เราจะปรับโทษเจ้าโดยคําของเจ้าเอง เจ้าก็รู้หรือว่าเราเป็นคนเข้มงวด เก็บผลซึ่งเรามิได้ลงแรง และเกี่ยวที่เรามิได้หว่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 23, 'ก็เหตุไฉนเจ้ามิได้ฝากเงินของเราไว้ที่ธนาคารเล่า เมื่อเรามาจะได้รับเงินของเรากับดอกเบี้ยด้วย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 24, 'แล้วท่านสั่งคนที่ยืนอยู่ที่นั่นว่า ‘จงเอาเงินมินาหนึ่งนั้นไปจากเขา ให้แก่คนที่มีสิบมินา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 25, '(คนเหล่านั้นบอกท่านว่า ‘ท่านเจ้าข้า เขามีสิบมินาแล้ว’)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 26, '‘เราบอกเจ้าทั้งหลายว่า ทุกคนที่มีอยู่แล้วจะเพิ่มเติมให้เขาอีก แต่ผู้ที่ไม่มีแม้ว่าซึ่งเขามีอยู่นั้นจะต้องเอาไปจากเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 27, 'ฝ่ายพวกศัตรูของเราที่ไม่ต้องการให้เราครอบครองเขานั้น จงพาเขามาที่นี่และฆ่าเสียต่อหน้าเรา’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 28, 'เมื่อพระองค์ตรัสคําเหล่านั้นแล้ว พระองค์ทรงดําเนินนําหน้าเขาไปจะขึ้นไปยังกรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 29, 'ต่อมาเมื่อพระองค์เสด็จมาใกล้หมู่บ้านเบธฟายีและหมู่บ้านเบธานีบนภูเขาซึ่งเรียกว่า มะกอกเทศ พระองค์ทรงใช้สาวกสองคนของพระองค์ไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 30, 'สั่งว่า “จงเข้าไปในหมู่บ้านที่อยู่ตรงหน้า เมื่อเข้าไปแล้วจะพบลูกลาตัวหนึ่งผูกอยู่ ที่ยังไม่เคยมีใครขึ้นขี่เลย จงแก้มันจูงมาเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 31, 'ถ้ามีผู้ใดถามท่านว่า ‘ท่านแก้มันทําไม’ จงบอกเขาว่า ‘เพราะองค์พระผู้เป็นเจ้าทรงประสงค์ลูกลานี้’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 32, 'สาวกที่รับใช้นั้นได้ไปพบเหมือนที่พระองค์ตรัสแก่เขาแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 33, 'เมื่อเขากําลังแก้ลูกลานั้น พวกเจ้าของก็ถามเขาว่า “ท่านแก้ลูกลาทําไม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 34, 'ฝ่ายเขาตอบว่า “องค์พระผู้เป็นเจ้าทรงประสงค์ลูกลานี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 35, 'แล้วเขาก็จูงลูกลามาถึงพระเยซูและเอาเสื้อของตนปูลงบนหลังลา และเชิญพระเยซูขึ้นทรงลานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 36, 'เมื่อพระองค์เสด็จไป เขาทั้งหลายก็เอาเสื้อผ้าของตนปูลงตามหนทาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 37, 'เมื่อพระองค์เสด็จมาใกล้ที่ซึ่งจะลงไปจากภูเขามะกอกเทศแล้ว เหล่าสาวกทุกคนมีความเปรมปรีดิ์เพราะบรรดามหกิจซึ่งเขาได้เห็นนั้น จึงเริ่มสรรเสริญพระเจ้าเสียงดัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 38, 'ว่า “ขอให้พระมหากษัตริย์ผู้ที่เสด็จมาในพระนามขององค์พระผู้เป็นเจ้าทรงพระเจริญ จงมีสันติสุขในสวรรค์ และทรงสง่าราศีในที่สูงสุด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 39, 'ฝ่ายฟาริสีบางคนในหมู่ประชาชนนั้นทูลพระองค์ว่า “อาจารย์เจ้าข้า จงห้ามเหล่าสาวกของท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 40, 'พระองค์ตรัสตอบเขาว่า “เราบอกท่านทั้งหลายว่า ถึงคนเหล่านี้จะนิ่งเสีย ศิลาทั้งหลายก็ยังจะส่งเสียงร้องทันที”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 41, 'ครั้นพระองค์เสด็จมาใกล้ทอดพระเนตรเห็นกรุงแล้ว ก็กันแสงสงสารกรุงนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 42, 'ตรัสว่า “ถ้าเจ้า คือเจ้าเอง รู้ในกาลวันนี้ว่า สิ่งอะไรจะให้สันติสุข แต่เดี๋ยวนี้สิ่งนั้นบังซ่อนไว้จากตาของเจ้าแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 43, 'ด้วยว่าเวลาจะมาถึงเจ้า เมื่อศัตรูของเจ้าจะก่อเชิงเทินต่อสู้เจ้า และล้อมขังเจ้าไว้ทุกด้าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 44, 'แล้วจะเหวี่ยงเจ้าลงให้ราบบนพื้นดิน กับลูกทั้งหลายของเจ้าซึ่งอยู่ในเจ้า และเขาจะไม่ปล่อยให้ศิลาซ้อนทับกันไว้ภายในเจ้าเลย เพราะเจ้าไม่ได้รู้เวลาที่พระองค์เสด็จมาเยี่ยมเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 45, 'ฝ่ายพระองค์เสด็จเข้าในพระวิหาร แล้วทรงเริ่มขับไล่คนทั้งหลายที่ซื้อขายอยู่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 46, 'ตรัสแก่เขาว่า “มีพระวจนะเขียนไว้ว่า ‘นิเวศของเราเป็นนิเวศสําหรับอธิษฐาน’ แต่เจ้าทั้งหลายมากระทําให้เป็น ‘ถ้ําของพวกโจร’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 47, 'พระองค์ทรงสั่งสอนในพระวิหารทุกวัน แต่พวกปุโรหิตใหญ่ พวกธรรมาจารย์ และคนสําคัญของพลเมืองได้หาช่องที่จะประหารพระองค์เสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 48, 'แต่เขาไม่พบช่องทางที่จะกระทําอะไรได้ เพราะว่าคนทั้งปวงชอบฟังพระองค์มาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 1, 'ต่อมาวันหนึ่งเมื่อพระองค์กําลังทรงสั่งสอนคนทั้งปวงในพระวิหารและประกาศข่าวประเสริฐ พวกปุโรหิตใหญ่ พวกธรรมาจารย์ และพวกผู้ใหญ่มาพบพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 2, 'และทูลพระองค์ว่า “จงบอกพวกเราเถิด ท่านกระทําการเหล่านี้โดยสิทธิอันใด หรือใครให้สิทธินี้แก่ท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 3, 'พระองค์ตรัสตอบเขาว่า “เราจะถามท่านทั้งหลายสักข้อหนึ่งด้วย จงตอบเราเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 4, 'คือบัพติศมาของยอห์นนั้นมาจากสวรรค์หรือมาจากมนุษย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 5, 'เขาจึงปรึกษากันว่า “ถ้าเราจะว่า ‘มาจากสวรรค์’ ท่านจะถามว่า ‘เหตุไฉนท่านจึงไม่เชื่อยอห์นเล่า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 6, 'แต่ถ้าเราจะว่า ‘มาจากมนุษย์’ คนทั้งปวงก็จะเอาหินขว้างเรา เพราะเขาทั้งหลายถือกันว่ายอห์นเป็นศาสดาพยากรณ์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 7, 'เขาจึงตอบว่าเขาไม่ทราบว่ามาจากไหน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 8, 'พระเยซูจึงตรัสกับเขาว่า “เราจะไม่บอกท่านทั้งหลายเหมือนกันว่า เรากระทําการเหล่านี้โดยสิทธิอันใด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 9, 'แล้วพระองค์ตั้งต้นตรัสคําอุปมาให้คนทั้งหลายฟังดังต่อไปนี้ว่า “ยังมีชายคนหนึ่งได้ทําสวนองุ่นและให้ชาวสวนเช่า แล้วก็ไปเมืองไกลเสียช้านาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 10, 'เมื่อถึงเวลาแล้วจึงใช้ผู้รับใช้คนหนึ่งไปหาคนเช่าสวนเหล่านั้น เพื่อเขาทั้งหลายจะได้มอบผลจากสวนองุ่นแก่เขาบ้าง แต่คนเช่าสวนนั้นได้เฆี่ยนตีผู้รับใช้คนนั้นและไล่ให้กลับไปมือเปล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 11, 'แล้วเจ้าของสวนจึงใช้ผู้รับใช้อีกคนหนึ่ง แต่คนเช่าสวนได้เฆี่ยนตีและทําการน่าอัปยศต่างๆแก่ผู้รับใช้นั้นด้วย และได้ไล่ให้กลับไปมือเปล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 12, 'แล้วเจ้าของสวนจึงใช้คนที่สามไปและคนเช่าสวนนั้นก็ทําให้เขาบาดเจ็บ แล้วผลักไสออกไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 13, 'ฝ่ายเจ้าของสวนองุ่นจึงว่า ‘เราจะทําอย่างไรดี เราจะใช้บุตรชายที่รักของเราไป เมื่อเห็นบุตรนั้นพวกเขาคงจะเคารพนับถือ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 14, 'แต่พวกคนเช่าสวนเมื่อเห็นบุตรนั้นก็ปรึกษากันว่า ‘คนนี้แหละเป็นผู้รับมรดก มาเถิด ให้เราฆ่าเขาเสีย เพื่อมรดกจะตกกับเรา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 15, 'แล้วเขาก็ผลักบุตรนั้นออกไปนอกสวนองุ่นฆ่าเสีย เหตุฉะนั้นเจ้าของสวนองุ่นจะทําอย่างไรกับเขาเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 16, 'ท่านจะมาฆ่าคนเช่าสวนเหล่านั้นเสีย แล้วจะเอาสวนองุ่นนั้นให้ผู้อื่นเช่า” คนทั้งหลายเมื่อได้ยินดังนั้นจึงว่า “ขอพระเจ้าอย่ายอมให้เป็นเช่นนั้นเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 17, 'ฝ่ายพระองค์ทรงเพ่งดูเขาและตรัสว่า “เหตุฉะนั้นพระวจนะซึ่งเขียนไว้นั้นหมายความอย่างไรกันซึ่งว่า ‘ศิลาซึ่งช่างก่อได้ปฏิเสธเสีย ได้กลับกลายเป็นศิลามุมเอกแล้ว’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 18, 'ผู้ใดล้มทับศิลานั้น ผู้นั้นจะต้องแตกหักไป แต่ศิลานั้นจะตกทับผู้ใด ก็จะบดขยี้ผู้นั้นจนแหลกเป็นผุยผง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 19, 'ฝ่ายพวกปุโรหิตใหญ่และพวกธรรมาจารย์รู้อยู่ว่า พระองค์ได้ตรัสคําอุปมานั้นกระทบพวกเขาเอง จึงอยากจะจับพระองค์ในเวลานั้นแต่เขากลัวประชาชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 20, 'เขาจึงตามดูพระองค์ และใช้คนให้ปลอมเป็นเหมือนคนชอบธรรมไปสอดแนม หวังจะจับผิดในพระดํารัสของพระองค์ เพื่อจะมอบพระองค์ไว้ในอํานาจและอาชญาของเจ้าเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 21, 'คนเหล่านั้นจึงทูลถามพระองค์ว่า “อาจารย์เจ้าข้า ข้าพเจ้าทั้งหลายทราบอยู่ว่า ท่านกล่าวและสั่งสอนล้วนแต่ความจริงและมิได้เลือกหน้าผู้ใด แต่สั่งสอนทางของพระเจ้าจริงๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 22, 'การที่จะส่งส่วยให้แก่ซีซาร์นั้นถูกต้องตามพระราชบัญญัติหรือไม่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 23, 'ฝ่ายพระองค์ทรงหยั่งรู้อุบายของเขาจึงตรัสแก่เขาว่า “ท่านทั้งหลายทดลองเราทําไม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 24, 'จงให้เราดูเงินตราเหรียญหนึ่งเถิด รูปและคําจารึกนี้เป็นของใคร” เขาทูลตอบว่า “ของซีซาร์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 25, 'แล้วพระองค์ตรัสกับเขาว่า “ของของซีซาร์จงถวายแก่ซีซาร์ และของของพระเจ้าจงถวายแด่พระเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 26, 'คนเหล่านั้นจับผิดในพระดํารัสของพระองค์ต่อหน้าประชาชนไม่ได้ และเขาก็ประหลาดใจในพระดํารัสตอบของพระองค์จึงนิ่งไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 27, 'ยังมีพวกสะดูสีบางคนมาหาพระองค์ ซึ่งเขาทั้งหลายว่าการฟื้นขึ้นมาจากความตายนั้นไม่มี เขาจึงทูลถามพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 28, 'ว่า “อาจารย์เจ้าข้า โมเสสได้เขียนสั่งข้าพเจ้าทั้งหลายไว้ว่า ‘ถ้าชายผู้ใดตายและมีภรรยา แต่ไม่มีบุตร ก็ให้น้องชายรับพี่สะใภ้นั้นไว้เป็นภรรยาของตน เพื่อสืบเชื้อสายของพี่ชายไว้’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 29, 'ยังมีพี่น้องผู้ชายเจ็ดคน พี่หัวปีมีภรรยาแล้วก็ตายไม่มีบุตร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 30, 'แล้วน้องที่สองก็รับหญิงนั้นเป็นภรรยา แล้วเขาก็ตายไม่มีบุตร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 31, 'ที่สามนั้นก็รับหญิงนั้นเป็นภรรยา ทั้งเจ็ดคนก็เหมือนกันไม่มีบุตร แล้วก็ตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 32, 'ที่สุดผู้หญิงนั้นก็ตายด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 33, 'เหตุฉะนั้น ในวันที่จะฟื้นขึ้นมาจากความตาย หญิงนั้นจะเป็นภรรยาของใคร ด้วยนางได้เป็นภรรยาของชายทั้งเจ็ดนั้นแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 34, 'พระเยซูตรัสตอบเขาว่า “คนในโลกนี้มีการสมรสกัน และยกให้เป็นสามีภรรยากัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 35, 'แต่เขาเหล่านั้นที่สมควรจะลุถึงโลกหน้า และลุถึงการฟื้นขึ้นมาจากความตาย ไม่มีการสมรสกัน หรือยกให้เป็นสามีภรรยากัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 36, 'และเขาจะตายอีกไม่ได้ เพราะเขาเป็นเหมือนทูตสวรรค์ เป็นบุตรของพระเจ้า ด้วยว่าเป็นลูกแห่งการฟื้นขึ้นมาจากความตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 37, 'แต่คนที่ตายจะถูกชุบให้เป็นขึ้นมาใหม่นั้น โมเสสก็ยังได้สําแดงในเรื่องพุ่มไม้ คือที่ได้เรียกองค์พระผู้เป็นเจ้าว่า ‘เป็นพระเจ้าของอับราฮัม เป็นพระเจ้าของอิสอัค และเป็นพระเจ้าของยาโคบ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 38, 'พระองค์มิได้ทรงเป็นพระเจ้าของคนตาย แต่ทรงเป็นพระเจ้าของคนเป็น ด้วยว่าจําเพาะพระเจ้าคนทุกคนเป็นอยู่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 39, 'ธรรมาจารย์บางคนจึงทูลว่า “อาจารย์เจ้าข้า ท่านพูดดีแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 40, 'หลังจากนั้น พวกเขาก็ไม่กล้าจะทูลถามพระองค์ต่อไปอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 41, 'พระองค์จึงตรัสถามเขาว่า “ที่คนทั้งหลายว่า พระคริสต์ทรงเป็นบุตรของดาวิดนั้นเป็นได้อย่างไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 42, 'ด้วยว่าท่านดาวิดเองได้กล่าวไว้ในหนังสือสดุดีว่า ‘องค์พระผู้เป็นเจ้าตรัสกับองค์พระผู้เป็นเจ้าของข้าพเจ้าว่า จงนั่งที่ขวามือของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 43, 'จนกว่าเราจะกระทําให้ศัตรูของท่านเป็นแท่นรองเท้าของท่าน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 44, 'ดาวิดยังได้ทรงเรียกท่านว่าเป็นองค์พระผู้เป็นเจ้า ท่านจะเป็นบุตรของดาวิดอย่างไรได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 45, 'เมื่อคนทั้งหลายกําลังฟังอยู่ พระองค์จึงตรัสกับเหล่าสาวกของพระองค์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 46, '“จงระวังพวกธรรมาจารย์ให้ดี ผู้ที่ชอบสวมเสื้อยาวเดินไปมา ชอบให้คนคํานับกลางตลาด ชอบนั่งที่สูงในธรรมศาลาและที่อันมีเกียรติในการเลี้ยง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 47, 'เขาริบเอาเรือนของหญิงม่าย และอธิษฐานโอ้อวดเสียยืดยาว เขาทั้งหลายนั้นจะได้รับพระอาชญามากยิ่งขึ้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 1, 'พระองค์เงยพระพักตร์ทอดพระเนตรเห็นคนมั่งมีทั้งหลายนําเงินมาใส่ในตู้เก็บเงินถวาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 2, 'พระองค์ทอดพระเนตรเห็นหญิงม่ายคนหนึ่งเป็นคนยากจนนําเหรียญทองแดงสองอันมาใส่ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 3, 'พระองค์ตรัสว่า “เราบอกความจริงแก่ท่านทั้งหลายว่า หญิงม่ายยากจนคนนี้ได้ใส่ไว้มากกว่าคนทั้งปวงนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 4, 'เพราะว่าคนทั้งปวงนี้ได้เอาเงินเหลือใช้ของเขามาใส่ถวายแด่พระเจ้า แต่ผู้หญิงนี้ขัดสนที่สุด ยังได้เอาเงินที่มีอยู่สําหรับเลี้ยงชีวิตของตนมาใส่จนหมด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 5, 'เมื่อบางคนพูดชมพระวิหารว่าได้ตกแต่งไว้ด้วยศิลางามและเครื่องถวาย พระองค์จึงตรัสว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 6, '“สิ่งเหล่านี้ที่ท่านทั้งหลายเห็น วันหนึ่งศิลาที่ซ้อนทับกันอยู่ที่นี่ซึ่งจะไม่ถูกทําลายลงก็หามิได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 7, 'เขาทั้งหลายทูลถามพระองค์ว่า “พระอาจารย์เจ้าข้า เหตุการณ์เหล่านี้จะบังเกิดขึ้นเมื่อไร สิ่งไรเป็นหมายสําคัญว่าการณ์ทั้งปวงนี้จวนจะบังเกิดขึ้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 8, 'พระองค์จึงตรัสว่า “ระวังให้ดี อย่าให้ผู้ใดล่อลวงท่านให้หลง ด้วยว่าจะมีหลายคนมาต่างอ้างนามของเราและว่า ‘เราเป็นพระคริสต์’ และว่า ‘เวลานั้นใกล้เข้ามาแล้ว’ เพราะฉะนั้นท่านทั้งหลายอย่าตามเขาไปเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 9, 'เมื่อท่านทั้งหลายจะได้ยินถึงการสงครามและการจลาจล อย่าตกใจกลัว เพราะว่าสิ่งเหล่านั้นจําต้องเกิดขึ้นก่อน แต่ที่สุดปลายยังจะไม่มาทันที”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 10, 'แล้วพระองค์ตรัสแก่เขาว่า “‘ประชาชาติจะลุกขึ้นต่อสู้ประชาชาติ ราชอาณาจักรต่อสู้ราชอาณาจักร’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 11, 'ทั้งจะเกิดแผ่นดินไหวใหญ่ในที่ต่างๆ และจะเกิดกันดารอาหารและโรคระบาดอย่างร้ายแรง และจะมีความวิบัติอันน่ากลัว และหมายสําคัญใหญ่ๆจากฟ้าสวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 12, 'แต่ก่อนเหตุการณ์เหล่านั้นเขาจะจับท่านไว้ และจะข่มเหงท่านและมอบท่านไว้ในธรรมศาลาและในคุก และพาท่านไปต่อหน้ากษัตริย์และเจ้าเมืองเพราะเหตุนามของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 13, 'การนั้นจะเกิดแก่ท่านเพื่อท่านจะได้เป็นพยาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 14, 'เหตุฉะนั้น ท่านทั้งหลายต้องปลงใจไว้ว่า จะไม่คิดคํานึงก่อนว่าจะแก้ตัวอย่างไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 15, 'ด้วยว่าเราจะให้ปากและปัญญาแก่ท่าน ซึ่งศัตรูทั้งหลายของท่านจะต่อต้านและคัดค้านไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 16, 'แม้แต่บิดามารดาญาติพี่น้องและมิตรสหายจะทรยศท่าน และพวกเขาจะฆ่าบางคนในพวกท่านเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 17, 'คนทั้งปวงจะเกลียดชังท่านเพราะเหตุนามของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 18, 'แต่ผมของท่านสักเส้นหนึ่งจะเสียไปก็หามิได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 19, 'ท่านจะได้ชีวิตรอดโดยความอดทนของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 20, 'เมื่อท่านเห็นกองทัพทั้งหลายมาตั้งล้อมรอบกรุงเยรูซาเล็ม เมื่อนั้นจงรู้ว่าวิบัติของกรุงนั้นก็ใกล้เข้ามาแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 21, 'เวลานั้นให้ผู้ที่อยู่ในแคว้นยูเดียหนีไปยังภูเขาและผู้ที่อยู่ในกรุงให้ออกไป และผู้ที่อยู่บ้านนอกอย่าให้เข้ามาในกรุง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 22, 'เพราะว่าเวลานั้นเป็นวันแห่งการแก้แค้นเพื่อจะให้สิ่งสารพัดที่เขียนไว้นั้นสําเร็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 23, 'แต่ในวันเหล่านั้นวิบัติแก่หญิงที่มีครรภ์หรือมีลูกอ่อนกินนมอยู่ เพราะว่าจะมีความทุกข์ร้อนใหญ่หลวงบนแผ่นดิน และจะทรงพระพิโรธแก่พลเมืองนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 24, 'เขาจะล้มลงด้วยคมดาบ และต้องถูกกวาดเอาไปเป็นเชลยทั่วทุกประชาชาติ และคนต่างชาติจะเหยียบย่ํากรุงเยรูซาเล็ม จนกว่าเวลากําหนดของคนต่างชาตินั้นจะครบถ้วน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 25, 'จะมีหมายสําคัญที่ดวงอาทิตย์ ที่ดวงจันทร์ และที่ดวงดาวทั้งปวง และบนแผ่นดินก็จะมีความทุกข์ร้อนตามชาติต่างๆ ซึ่งมีความพิศวงงงงวยเพราะเสียงกึกก้องของทะเลและคลื่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 26, 'จิตใจมนุษย์ก็จะสลบไสลไปเพราะความกลัว และเพราะสังหรณ์ถึงเหตุการณ์ซึ่งจะบังเกิดในโลก ด้วยว่า ‘บรรดาสิ่งที่มีอํานาจในท้องฟ้าจะสะเทือนสะท้านไป’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 27, 'เมื่อนั้นเขาจะเห็นบุตรมนุษย์เสด็จมาในเมฆ ทรงฤทธานุภาพและสง่าราศีเป็นอันมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 28, 'เมื่อเหตุการณ์ทั้งปวงนี้เริ่มจะบังเกิดขึ้นนั้น จงยืดตัวและผงกศีรษะขึ้น ด้วยการไถ่ท่านใกล้จะถึงแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 29, 'พระองค์ตรัสคําอุปมาแก่เขาว่า “จงดูต้นมะเดื่อและต้นไม้ทั้งปวงเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 30, 'เมื่อผลิใบออกแล้ว ท่านทั้งหลายก็เห็นและรู้อยู่เองว่าฤดูร้อนจวนจะถึงแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 31, 'เช่นนั้นแหละ เมื่อท่านทั้งหลายเห็นเหตุการณ์เหล่านั้นเกิดขึ้น ก็ให้รู้ว่าอาณาจักรของพระเจ้าใกล้จะถึงแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 32, 'เราบอกความจริงแก่ท่านทั้งหลายว่า คนในชั่วอายุนี้จะไม่ล่วงลับไปจนกว่าสิ่งทั้งปวงนี้จะสําเร็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 33, 'ฟ้าและดินจะล่วงไป แต่ถ้อยคําของเราจะสูญหายไปหามิได้เลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 34, 'แต่จงระวังตัวให้ดี เกลือกว่าในเวลาหนึ่งเวลาใดใจของท่านจะล้นไปด้วยอาการกินและดื่ม และด้วยการเมา และด้วยคิดกังวลถึงชีวิตนี้ แล้วเวลานั้นจะมาถึงท่านโดยไม่ทันรู้ตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 35, 'เพราะว่าวันนั้นจะมาดุจบ่วงแร้วถึงคนทั้งปวงที่อยู่ทั่วพื้นแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 36, 'เหตุฉะนั้นจงเฝ้าระวังและอธิษฐานอยู่ทุกเวลา เพื่อท่านทั้งหลายสมควรที่จะพ้นเหตุการณ์ทั้งปวงซึ่งจะบังเกิดมานั้น และจะยืนอยู่ต่อหน้าบุตรมนุษย์ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 37, 'กลางวันพระองค์ทรงสั่งสอนในพระวิหาร และกลางคืนก็เสด็จออกไปประทับที่ภูเขาชื่อมะกอกเทศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 38, 'คนทั้งปวงก็มาหาพระองค์ในพระวิหารแต่เช้าตรู่เพื่อจะฟังพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 1, 'เทศกาลเลี้ยงขนมปังไร้เชื้อที่เรียกว่าปัสกามาใกล้แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 2, 'พวกปุโรหิตใหญ่กับพวกธรรมาจารย์หาช่องทางว่าเขาจะฆ่าพระองค์ได้อย่างไร เพราะเขากลัวประชาชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 3, 'ฝ่ายซาตานเข้าดลใจยูดาสที่เรียกว่าอิสคาริโอทที่นับเข้าในพวกสาวกสิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 4, 'ยูดาสได้ไปปรึกษากับพวกปุโรหิตใหญ่และพวกนายทหารว่า จะทรยศพระองค์ให้เขาได้ด้วยวิธีใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 5, 'คนเหล่านั้นดีใจ และตกลงกับยูดาสว่าจะให้เงิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 6, 'ยูดาสจึงให้สัญญา และคอยหาโอกาสที่จะทรยศพระองค์ให้แก่เขาเมื่อว่างคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 7, 'พอถึงวันกินขนมปังไร้เชื้อ เมื่อเขาต้องฆ่าลูกแกะสําหรับปัสกา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 8, 'พระองค์จึงทรงใช้เปโตรและยอห์นไปสั่งว่า “จงไปจัดเตรียมปัสกาให้เราทั้งหลายกิน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 9, 'เขาทูลถามพระองค์ว่า “พระองค์ทรงปรารถนาจะให้ข้าพระองค์ทั้งหลายจัดเตรียมที่ไหน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 10, 'พระองค์ตรัสตอบเขาว่า “ดูเถิด เมื่อท่านเข้าไปในกรุงก็จะมีชายคนหนึ่งทูนหม้อน้ํามาพบท่าน เขาจะเข้าไปเรือนไหน จงตามเขาไปในเรือนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 11, 'จงพูดกับเจ้าของเรือนว่า ‘พระอาจารย์ให้ถามท่านว่า “ห้องที่เราจะกินปัสกากับเหล่าสาวกของเราได้นั้นอยู่ที่ไหน”’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 12, 'เจ้าของเรือนจะชี้ให้ท่านเห็นห้องใหญ่ชั้นบนที่ตกแต่งไว้แล้ว ที่นั่นแหละจงจัดเตรียมไว้เถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 13, 'เขาทั้งสองจึงไปและพบเหมือนคําที่พระองค์ได้ตรัสแก่เขา แล้วได้จัดเตรียมปัสกาไว้พร้อม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 14, 'เมื่อถึงเวลาพระองค์ทรงเอนพระกายลงเสวยพร้อมกับอัครสาวกสิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 15, 'พระองค์ตรัสกับเขาว่า “เรามีความปรารถนาอย่างยิ่งที่จะกินปัสกานี้กับพวกท่าน ก่อนเราจะต้องทนทุกข์ทรมาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 16, 'ด้วยเราบอกท่านทั้งหลายว่า เราจะไม่กินปัสกานี้อีกจนกว่าจะสําเร็จในอาณาจักรของพระเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 17, 'พระองค์ทรงหยิบถ้วย ขอบพระคุณแล้วตรัสว่า “จงรับถ้วยนี้แบ่งกันดื่ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 18, 'เพราะเราบอกท่านทั้งหลายว่า เราจะไม่ดื่มน้ําองุ่นจากเถาองุ่นต่อไปอีกจนกว่าอาณาจักรของพระเจ้าจะมา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 19, 'พระองค์ทรงหยิบขนมปัง ขอบพระคุณแล้วหักส่งให้แก่เขาทั้งหลายตรัสว่า “นี่เป็นกายของเรา ซึ่งได้ให้สําหรับท่านทั้งหลาย จงกระทําอย่างนี้ให้เป็นที่ระลึกถึงเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 20, 'เมื่อรับประทานแล้ว จึงทรงหยิบถ้วยกระทําเหมือนกันตรัสว่า “ถ้วยนี้เป็นพันธสัญญาใหม่โดยโลหิตของเราซึ่งเทออกเพื่อท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 21, 'แต่ดูเถิด มือของผู้ที่จะทรยศเราก็อยู่กับเราบนโต๊ะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 22, 'เพราะบุตรมนุษย์จะเสด็จไปเหมือนได้ทรงดําริไว้แต่ก่อนแล้ว แต่วิบัติแก่ผู้นั้นที่ทรยศพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 23, 'เหล่าสาวกจึงเริ่มถามกันและกันว่า จะเป็นใครในพวกเขาที่จะกระทําการนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 24, 'มีการเถียงกันด้วยว่าจะนับว่าใครในพวกเขาเป็นใหญ่ที่สุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 25, 'พระองค์จึงตรัสแก่เขาว่า “กษัตริย์ของคนต่างชาติย่อมเป็นเจ้าเหนือเขา และผู้ที่มีอํานาจเหนือเขานั้น เขาเรียกว่าเจ้าบุญนายคุณ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 26, 'แต่พวกท่านจะหาเป็นอย่างนั้นไม่ ผู้ใดในพวกท่านที่เป็นใหญ่ที่สุด ให้ผู้นั้นเป็นเหมือนผู้เล็กน้อยที่สุด และผู้ใดเป็นนาย ให้ผู้นั้นเป็นเหมือนคนรับใช้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 27, 'ด้วยว่าใครเป็นใหญ่กว่า ผู้ที่เอนกายลงรับประทานหรือผู้รับใช้ ผู้ที่เอนกายลงรับประทานมิใช่หรือ แต่ว่าเราอยู่ท่ามกลางท่านทั้งหลายเหมือนผู้รับใช้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 28, 'ฝ่ายท่านทั้งหลายเป็นคนที่ได้อยู่กับเราในเวลาที่เราถูกทดลอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 29, 'และพระบิดาของเราได้ทรงจัดเตรียมอาณาจักรมอบให้แก่เราอย่างไร เราก็จะจัดเตรียมอาณาจักรมอบให้แก่ท่านทั้งหลายเหมือนกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 30, 'คือท่านทั้งหลายจะกินและดื่มที่โต๊ะของเราในอาณาจักรของเรา และจะนั่งบนที่นั่งพิพากษาพวกอิสราเอลสิบสองตระกูล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 31, 'และองค์พระผู้เป็นเจ้าตรัสว่า “ซีโมน ซีโมนเอ๋ย ดูเถิด ซาตานได้ขอท่านไว้เพื่อจะฝัดร่อนท่านเหมือนฝัดข้าวสาลี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 32, 'แต่เราได้อธิษฐานเผื่อตัวท่าน เพื่อความเชื่อของท่านจะไม่ได้ขาด และเมื่อท่านได้หันกลับแล้ว จงชูกําลังพี่น้องทั้งหลายของท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 33, 'ฝ่ายเขาจึงทูลพระองค์ว่า “พระองค์เจ้าข้า ข้าพระองค์พร้อมแล้วที่จะไปกับพระองค์ ถึงจะต้องติดคุกและถึงความตายก็ดี”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 34, 'พระองค์ตรัสว่า “เปโตรเอ๋ย เราบอกท่านว่าวันนี้ก่อนไก่ขัน ท่านจะปฏิเสธว่าไม่รู้จักเราถึงสามครั้ง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 35, 'พระองค์จึงตรัสถามเหล่าสาวกว่า “เมื่อเราได้ใช้ท่านทั้งหลายออกไปโดยไม่มีถุงเงิน ไม่มีย่าม ไม่มีรองเท้านั้น ท่านขัดสนสิ่งใดบ้างหรือ” เขาทั้งหลายทูลตอบว่า “ไม่ขาดสิ่งใดเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 36, 'พระองค์จึงตรัสกับเขาว่า “แต่เดี๋ยวนี้ใครมีถุงเงินให้เอาไปด้วย และย่ามก็ให้เอาไปเหมือนกัน และผู้ใดที่ไม่มีดาบก็ให้ขายเสื้อคลุมของตนไปซื้อดาบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 37, 'ด้วยเราบอกท่านทั้งหลายว่า พระวจนะซึ่งเขียนไว้แล้วนั้นต้องสําเร็จในเรา คือว่า ‘ท่านถูกนับเข้ากับบรรดาผู้ละเมิด’ เพราะว่าคําพยากรณ์ที่เล็งถึงเรานั้นจะสําเร็จ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 38, 'เขาทูลตอบว่า “พระองค์เจ้าข้า ดูเถิด มีดาบสองเล่ม” พระองค์ตรัสกับเขาว่า “พอเสียทีเถอะ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 39, 'ฝ่ายพระองค์เสด็จออกไปยังภูเขามะกอกเทศตามเคย และเหล่าสาวกของพระองค์ก็ตามพระองค์ไปด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 40, 'เมื่อมาถึงที่นั่นแล้ว พระองค์ตรัสกับเขาทั้งหลายว่า “จงอธิษฐานเพื่อมิให้เข้าในการทดลอง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 41, 'แล้วพระองค์ดําเนินไปจากเขาไกลประมาณขว้างหินตกและทรงคุกเข่าลงอธิษฐาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 42, 'ว่า “พระบิดาเจ้าข้า ถ้าพระองค์พอพระทัย ขอให้ถ้วยนี้เลื่อนพ้นไปจากข้าพระองค์เถิด แต่อย่างไรก็ดีอย่าให้เป็นไปตามใจข้าพระองค์ แต่ให้เป็นไปตามพระทัยของพระองค์เถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 43, 'ทูตสวรรค์องค์หนึ่งจากสวรรค์มาปรากฏแก่พระองค์ช่วยชูกําลังพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 44, 'เมื่อพระองค์ทรงเป็นทุกข์มากนักพระองค์ยิ่งปลงพระทัยอธิษฐาน พระเสโทของพระองค์เป็นเหมือนโลหิตไหลหยดลงถึงดินเป็นเม็ดใหญ่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 45, 'เมื่อทรงอธิษฐานเสร็จและลุกขึ้นแล้ว พระองค์เสด็จมาถึงเหล่าสาวก พบเขานอนหลับอยู่ด้วยกําลังทุกข์โศก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 46, 'พระองค์จึงตรัสกับเขาว่า “นอนหลับทําไม จงลุกขึ้นอธิษฐานเพื่อท่านจะไม่เข้าในการทดลอง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 47, 'พระองค์ตรัสยังไม่ทันขาดคํา ดูเถิด มีคนเป็นอันมาก และผู้ที่ชื่อว่า ยูดาส เป็นคนหนึ่งในสาวกสิบสองคนนําหน้าเขามา ยูดาสเข้ามาใกล้พระเยซูเพื่อจุบพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 48, 'แต่พระเยซูตรัสถามเขาว่า “ยูดาส ท่านจะทรยศบุตรมนุษย์ด้วยการจุบหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 49, 'เมื่อคนทั้งปวงที่อยู่รอบพระองค์เห็นว่าจะเกิดเหตุอะไรต่อไป เขาจึงทูลถามพระองค์ว่า “พระองค์เจ้าข้า ให้เราเอาดาบฟันเขาหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 50, 'และมีคนหนึ่งในเหล่าสาวก ได้ฟันผู้รับใช้คนหนึ่งของมหาปุโรหิต ถูกหูข้างขวาของเขาขาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 51, 'แต่พระเยซูตรัสว่า “พอเสียทีเถอะ” แล้วพระองค์ทรงถูกต้องใบหูคนนั้นให้เขาหาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 52, 'ฝ่ายพระเยซูตรัสแก่พวกปุโรหิตใหญ่ พวกนายทหารรักษาพระวิหาร และพวกผู้ใหญ่ที่ออกมาจับพระองค์นั้นว่า “ท่านทั้งหลายเห็นเราเป็นโจรหรือจึงถือดาบถือตะบองออกมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 53, 'เมื่อเราอยู่กับท่านทั้งหลายในพระวิหารทุกๆวัน ท่านก็มิได้ยื่นมือออกจับเรา แต่เวลานี้เป็นทีของท่านและเป็นอํานาจแห่งความมืด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 54, 'เขาก็จับพระองค์พาเข้าไปในบ้านมหาปุโรหิต เปโตรติดตามไปห่างๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 55, 'เมื่อเขาก่อไฟที่กลางลานบ้านและนั่งลงด้วยกันแล้ว เปโตรก็นั่งอยู่ท่ามกลางเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 56, 'มีสาวใช้คนหนึ่งเห็นเปโตรนั่งอยู่ใกล้ไฟ จึงเพ่งดูแล้วว่า “คนนี้ได้อยู่กับผู้นั้นด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 57, 'แต่เปโตรปฏิเสธพระองค์ว่า “แม่เอ๋ย คนนั้นข้าไม่รู้จัก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 58, 'สักครู่หนึ่ง มีอีกคนหนึ่งเห็นเปโตรจึงว่า “เจ้าเป็นคนหนึ่งในพวกนั้นด้วย” เปโตรจึงว่า “พ่อเอ๋ย ข้ามิได้เป็น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 59, 'อยู่มาประมาณอีกชั่วโมงหนึ่งมีอีกคนหนึ่งยืนยันแข็งแรงว่า “แน่แล้ว คนนี้อยู่กับเขาด้วย เพราะเขาเป็นชาวกาลิลี”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 60, 'แต่เปโตรพูดว่า “พ่อเอ๋ย ที่ท่านว่านั้นข้าไม่รู้เรื่อง” เมื่อเปโตรกําลังพูดยังไม่ทันขาดคํา ในทันใดนั้นไก่ก็ขัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 61, 'องค์พระผู้เป็นเจ้าทรงเหลียวดูเปโตร แล้วเปโตรก็ระลึกถึงคําขององค์พระผู้เป็นเจ้าซึ่งพระองค์ได้ตรัสไว้แก่เขาว่า “ก่อนไก่ขัน ท่านจะปฏิเสธเราถึงสามครั้ง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 62, 'แล้วเปโตรก็ออกไปข้างนอกร้องไห้เป็นทุกข์นัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 63, 'ฝ่ายคนที่คุมพระเยซูก็เยาะเย้ยโบยตีพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 64, 'และเมื่อเขาเอาผ้าผูกปิดพระเนตรของพระองค์แล้ว เขาจึงตบพระพักตร์พระองค์และถามพระองค์ว่า “จงพยากรณ์เถอะว่า ใครตบเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 65, 'และเขาพูดคําหมิ่นประมาทแก่พระองค์อีกหลายประการ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 66, 'ครั้นรุ่งเช้าพวกผู้ใหญ่ของพลเมืองกับพวกปุโรหิตใหญ่ และพวกธรรมาจารย์ได้ประชุมกัน และเขาพาพระองค์เข้าไปในศาลสูงของเขา และพูดว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 67, '“ถ้าท่านเป็นพระคริสต์ จงบอกเราเถิด” แต่พระองค์ทรงตอบเขาว่า “ถึงเราจะบอกท่าน ท่านก็จะไม่เชื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 68, 'และเช่นเดียวกันถึงเราถามท่าน ท่านก็จะไม่ตอบเรา และจะไม่ปล่อยให้เราไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 69, 'แต่ตั้งแต่นี้ไปบุตรมนุษย์จะนั่งข้างขวาของพระเจ้าผู้ทรงฤทธานุภาพ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 70, 'คนทั้งปวงจึงถามว่า “ท่านเป็นบุตรของพระเจ้าหรือ” พระองค์ตรัสแก่เขาว่า “ก็ท่านว่าแล้วว่าเราเป็น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 71, 'เขาทั้งหลายจึงว่า “เราต้องการพยานอะไรอีกเล่า เพราะว่าพวกเราได้ยินจากปากของเขาเองแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 1, 'เขาทั้งปวงจึงลุกขึ้นพาพระองค์ไปหาปีลาต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 2, 'และเขาเริ่มฟ้องพระองค์ว่า “เราได้พบคนนี้ยุยงชนชาติของเราและห้ามมิให้ส่งส่วยแก่ซีซาร์ และว่าตัวเองเป็นพระคริสต์กษัตริย์องค์หนึ่ง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 3, 'ปีลาตจึงถามพระองค์ว่า “ท่านเป็นกษัตริย์ของพวกยิวหรือ” พระองค์ตรัสตอบท่านว่า “ก็ท่านว่าแล้วนี่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 4, 'ปีลาตจึงว่าแก่พวกปุโรหิตใหญ่กับประชาชนว่า “เราไม่เห็นว่าคนนี้มีความผิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 5, 'เขาทั้งหลายยิ่งกล่าวแข็งแรงว่า “คนนี้ยุยงพลเมืองให้วุ่นวาย และสั่งสอนทั่วตลอดยูเดีย ตั้งแต่กาลิลีจนถึงที่นี่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 6, 'เมื่อปีลาตได้ยินถึงแคว้นกาลิลี ท่านจึงถามว่าคนนี้เป็นชาวกาลิลีหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 7, 'เมื่อทราบแล้วว่าพระองค์ทรงเป็นคนอยู่ในท้องที่ของเฮโรด ท่านจึงส่งพระองค์ไปหาเฮโรด ผู้กําลังอยู่ในกรุงเยรูซาเล็มในเวลานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 8, 'เมื่อเฮโรดได้เห็นพระเยซูก็มีความยินดีมาก ด้วยนานมาแล้วท่านอยากจะพบพระองค์ เพราะได้ยินถึงพระองค์หลายประการ และหวังว่าคงจะได้เห็นพระองค์ทําการอัศจรรย์บ้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 9, 'ท่านจึงซักถามพระองค์เป็นหลายข้อ แต่พระองค์หาทรงตอบประการใดไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 10, 'ฝ่ายพวกปุโรหิตใหญ่และพวกธรรมาจารย์ก็ยืนขึ้นฟ้องพระองค์แข็งแรงมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 11, 'เฮโรดกับพวกทหารของท่านกระทําต่อพระองค์อย่างดูหมิ่น เยาะเย้ย เอาเสื้อที่งามยิ่งสวมให้พระองค์ และส่งกลับไปหาปีลาตอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 12, 'ฝ่ายปีลาตกับเฮโรดคืนดีกันในวันนั้น ด้วยแต่ก่อนเป็นศัตรูกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 13, 'ปีลาตจึงสั่งพวกปุโรหิตใหญ่ พวกขุนนางและประชาชนให้ประชุมพร้อมกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 14, 'จึงกล่าวแก่เขาว่า “ท่านทั้งหลายได้พาคนนี้มาหาเราฟ้องว่าเขาได้ยุยงประชาชน ดูเถิด เราได้สืบถามต่อหน้าท่านทั้งหลาย และไม่เห็นว่าคนนี้มีความผิดในข้อที่ท่านทั้งหลายฟ้องเขานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 15, 'และเฮโรดก็ไม่เห็นว่าเขามีความผิดด้วย เพราะเราได้ส่งพวกท่านทั้งหลายไปหาเฮโรด ดูเถิด คนนี้ไม่ได้ทําผิดอะไรซึ่งสมควรจะมีโทษถึงตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 16, 'เหตุฉะนั้น เมื่อเราเฆี่ยนเขาแล้ว เราก็จะปล่อยเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 17, '(เพราะท่านต้องปล่อยคนหนึ่งให้เขาทั้งหลายในเทศกาลเลี้ยงนั้น)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 18, 'แต่คนทั้งปวงร้องขึ้นพร้อมกันว่า “กําจัดคนนี้เสีย และจงปล่อยบารับบัสให้เราเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 19, '(บารับบัสนั้นติดคุกอยู่เพราะก่อการจลาจลที่เกิดขึ้นในกรุงและการฆาตกรรม)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 20, 'ฝ่ายปีลาตยังมีน้ําใจใคร่จะปล่อยพระเยซูจึงพูดกับเขาอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 21, 'แต่คนเหล่านั้นกลับตะโกนร้องว่า “ตรึงเขาเสีย ตรึงเขาเสียที่กางเขนเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 22, 'ปีลาตจึงถามเขาครั้งที่สามว่า “ตรึงทําไม เขาได้ทําผิดประการใด เราไม่เห็นเขาทําผิดอะไรที่สมควรจะมีโทษถึงตาย เหตุฉะนั้นเมื่อเราเฆี่ยนเขาแล้วก็จะปล่อยเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 23, 'ฝ่ายคนทั้งปวงก็เร่งเร้าเสียงดังให้ตรึงพระองค์เสียที่กางเขน และเสียงของพวกเขาและของพวกปุโรหิตใหญ่นั้นก็มีชัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 24, 'ปีลาตจึงสั่งให้เป็นไปตามที่เขาทั้งหลายปรารถนา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 25, 'ท่านจึงปล่อยคนที่เขาขอนั้นให้แก่พวกเขา ซึ่งติดคุกอยู่เพราะการจลาจลและการฆาตกรรม แต่ท่านได้มอบพระเยซูไว้ตามใจพวกเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 26, 'เมื่อเขาพาพระองค์ออกไป เขาเกณฑ์ซีโมนชาวไซรีนที่มาจากบ้านนอก แล้วเอากางเขนวางบนเขาให้แบกตามพระเยซูไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 27, 'มีคนเป็นอันมากตามพระองค์ไป ทั้งพวกผู้หญิงที่พิลาปและคร่ําครวญเพราะพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 28, 'พระเยซูจึงหันพระพักตร์มาทางเขาตรัสว่า “ธิดาเยรูซาเล็มเอ๋ย อย่าร้องไห้เพราะเราเลย แต่จงร้องไห้เพราะตนเอง และเพราะลูกทั้งหลายของตนเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 29, 'ด้วยว่า ดูเถิด จะมีเวลาหนึ่งที่เขาทั้งหลายจะว่า ‘ผู้หญิงเหล่านั้นที่เป็นหมัน และครรภ์ที่มิได้ปฏิสนธิ และหัวนมที่มิได้ให้ดูดเลย ก็เป็นสุข’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 30, 'คราวนั้นเขาจะเริ่มกล่าวแก่ภูเขาทั้งหลายว่า ‘จงล้มทับเราเถิด’ และแก่เนินเขาว่า ‘จงปกคลุมเราไว้’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 31, 'เพราะว่าถ้าเขาทําอย่างนี้เมื่อไม้สด อะไรจะเกิดขึ้นเมื่อไม้แห้งแล้วเล่า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 32, 'มีอีกสองคนที่เป็นผู้ร้ายซึ่งเขาได้พามาจะประหารเสียพร้อมกับพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 33, 'เมื่อมาถึงสถานที่แห่งหนึ่งซึ่งเรียกว่า กะโหลกศีรษะ เขาก็ตรึงพระองค์ไว้ที่กางเขนที่นั่น พร้อมกับผู้ร้ายสองคนนั้น ข้างขวาพระหัตถ์คนหนึ่ง และข้างซ้ายอีกคนหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 34, 'ฝ่ายพระเยซูจึงตรัสว่า “ข้าแต่พระบิดา ขอโปรดอภัยโทษพวกเขา เพราะว่าเขาไม่รู้ว่าเขาทําอะไร” และพวกเขาก็เอาฉลองพระองค์จับฉลากแบ่งปันกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 35, 'คนทั้งปวงก็ยืนมองดู พวกขุนนางก็เยาะเย้ยพระองค์ด้วยว่า “เขาช่วยคนอื่นให้รอดได้ ถ้าเขาเป็นพระคริสต์ของพระเจ้าที่ทรงเลือกไว้ ให้เขาช่วยตัวเองเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 36, 'พวกทหารก็เยาะเย้ยพระองค์ด้วย เข้ามาเอาน้ําองุ่นเปรี้ยวส่งให้พระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 37, 'แล้วว่า “ถ้าท่านเป็นกษัตริย์ของพวกยิว จงช่วยตัวเองให้รอดเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 38, 'และมีคําเขียนไว้เหนือพระองค์ด้วยเป็นอักษรกรีก ลาติน และฮีบรูว่า “ผู้นี้เป็นกษัตริย์ของพวกยิว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 39, 'ฝ่ายคนหนึ่งในผู้ร้ายที่ถูกตรึงไว้จึงพูดหยาบช้าต่อพระองค์ว่า “ถ้าท่านเป็นพระคริสต์ จงช่วยตัวเองกับเราให้รอดเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 40, 'แต่อีกคนหนึ่งห้ามปรามเขาว่า “เจ้าก็ไม่เกรงกลัวพระเจ้าหรือ เพราะเจ้าเป็นคนถูกโทษเหมือนกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 41, 'และเราก็สมกับโทษนั้นจริง เพราะเราได้รับสมกับการที่เราได้กระทํา แต่ท่านผู้นี้หาได้กระทําผิดประการใดไม่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 42, 'แล้วคนนั้นจึงทูลพระเยซูว่า “พระองค์เจ้าข้า ขอพระองค์ทรงระลึกถึงข้าพระองค์เมื่อพระองค์เสด็จเข้าในอาณาจักรของพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 43, 'ฝ่ายพระเยซูทรงตอบเขาว่า “เราบอกความจริงแก่เจ้าว่า วันนี้เจ้าจะอยู่กับเราในเมืองบรมสุขเกษม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 44, 'เวลานั้นประมาณเวลาเที่ยง ก็บังเกิดความมืดทั่วทั้งแผ่นดินจนถึงบ่ายสามโมง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 45, 'ดวงอาทิตย์ก็มืดไป ม่านในพระวิหารก็ขาดตรงกลาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 46, 'พระเยซูทรงร้องเสียงดังตรัสว่า “พระบิดาเจ้าข้า ข้าพระองค์ฝากจิตวิญญาณของข้าพระองค์ไว้ในพระหัตถ์ของพระองค์” ตรัสอย่างนั้นแล้ว จึงทรงปล่อยพระวิญญาณจิตออกไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 47, 'ฝ่ายนายร้อยเมื่อเห็นเหตุการณ์ซึ่งบังเกิดขึ้นนั้น จึงสรรเสริญพระเจ้าว่า “แท้จริงท่านผู้นี้เป็นคนชอบธรรม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 48, 'คนทั้งปวงที่มาชุมนุมกันเพื่อจะดูการณ์นี้ เมื่อเห็นแล้วก็พากันตีอกของตัวกลับไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 49, 'คนทั้งปวงที่รู้จักพระองค์และพวกผู้หญิงซึ่งได้ตามพระองค์มาจากกาลิลี ก็ยืนอยู่แต่ไกล มองดูเหตุการณ์เหล่านี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 50, 'และดูเถิด มีชายคนหนึ่งชื่อโยเซฟ ท่านเป็นสมาชิกสภา เป็นคนดีและชอบธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 51, '(ท่านมิได้ยอมเห็นด้วยในมติและการกระทําของเขาทั้งหลาย) ท่านเป็นชาวบ้านอาริมาเธียหมู่บ้านพวกยิว และเป็นผู้คอยท่าอาณาจักรของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 52, 'ชายคนนี้จึงเข้าไปหาปีลาตขอพระศพพระเยซู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 53, 'เมื่อเชิญพระศพลงแล้ว เขาจึงเอาผ้าป่านพันหุ้มไว้ แล้วเชิญพระศพไปประดิษฐานไว้ในอุโมงค์ ซึ่งเจาะไว้ในศิลาที่ยังมิได้วางศพผู้ใดเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 54, 'วันนั้นเป็นวันจัดเตรียม และวันสะบาโตก็เกือบจะถึงแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 55, 'ฝ่ายพวกผู้หญิงที่ตามพระองค์มาจากแคว้นกาลิลีก็ตามไปและได้เห็นอุโมงค์ ทั้งได้เห็นเขาวางพระศพของพระองค์ไว้อย่างไรด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 56, 'แล้วเขาก็กลับไปจัดแจงเครื่องหอมกับน้ํามันหอม ในวันสะบาโตนั้นเขาก็หยุดการไว้ตามพระบัญญัติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 1, 'และเช้ามืดในวันต้นสัปดาห์ ผู้หญิงเหล่านั้นจึงนําเครื่องหอมที่เขาได้จัดเตรียมไว้มาถึงอุโมงค์ และคนอื่นก็มาพร้อมกับเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 2, 'เขาเหล่านั้นเห็นก้อนหินกลิ้งออกพ้นจากปากอุโมงค์แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 3, 'และเมื่อเข้าไปมิได้เห็นพระศพของพระเยซูเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 4, 'ต่อมาเมื่อเขากําลังพิศวงงงงวยด้วยเหตุการณ์นั้น ดูเถิด มีชายสองคนยืนอยู่ใกล้เขา เครื่องนุ่งห่มแพรวพราว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 5, 'ฝ่ายผู้หญิงเหล่านั้นกลัวและซบหน้าลงถึงดิน ชายสองคนนั้นจึงพูดกับเขาว่า “พวกท่านแสวงหาคนเป็นในพวกคนตายทําไมเล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 6, 'พระองค์ไม่อยู่ที่นี่ แต่ทรงเป็นขึ้นมาแล้ว จงระลึกถึงคําที่พระองค์ได้ตรัสกับท่านทั้งหลายเมื่อพระองค์ยังอยู่ในแคว้นกาลิลี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 7, 'ว่า ‘บุตรมนุษย์จะต้องถูกมอบไว้ในมือของคนบาป และต้องถูกตรึงที่กางเขน และวันที่สามจะเป็นขึ้นมาใหม่’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 8, 'เขาจึงระลึกถึงพระดํารัสของพระองค์ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 9, 'และกลับไปจากอุโมงค์ แล้วบอกเหตุการณ์ทั้งปวงนั้นแก่สาวกสิบเอ็ดคน และคนอื่นๆทั้งหมดด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 10, 'ผู้ที่ได้บอกเหตุการณ์นั้นแก่อัครสาวก คือมารีย์ชาวมักดาลา โยอันนา มารีย์มารดาของยากอบ และหญิงอื่นๆที่อยู่กับเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 11, 'ฝ่ายอัครสาวกไม่เชื่อ ถือว่าเป็นคําเหลวไหล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 12, 'แต่เปโตรลุกขึ้นวิ่งไปถึงอุโมงค์ ก้มลงมองดูก็เห็นแต่ผ้าป่านวางอยู่ต่างหาก แล้วกลับไปคิดพิศวงถึงเหตุการณ์ซึ่งได้เป็นไปนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 13, 'ดูเถิด วันนั้นเองมีสาวกสองคนไปยังหมู่บ้านชื่อเอมมาอูส ไกลจากกรุงเยรูซาเล็มประมาณสิบเอ็ดกิโลเมตร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 14, 'เขาสนทนากันถึงเหตุการณ์ซึ่งได้เป็นไปนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 15, 'และต่อมาเมื่อเขากําลังพูดปรึกษากันอยู่ พระเยซูเองก็เสด็จเข้ามาใกล้ดําเนินไปกับเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 16, 'แต่ตาเขาฟางไปและจําพระองค์ไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 17, 'พระองค์ตรัสกับเขาว่า “เมื่อเดินมานี่ด้วยหน้าโศกเศร้า ท่านโต้ตอบกันถึงเรื่องอะไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 18, 'คนหนึ่งในพวกเขาชื่อเคลโอปัสจึงทูลถามพระองค์ว่า “ท่านเป็นเพียงแต่คนต่างถิ่นในกรุงเยรูซาเล็มหรือ ที่ไม่รู้เหตุการณ์ทั้งปวงซึ่งเป็นไปในวันเหล่านี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 19, 'พระองค์ตรัสถามเขาว่า “เหตุการณ์อะไร” เขาจึงตอบพระองค์ว่า “เหตุการณ์เรื่องพระเยซูชาวนาซาเร็ธ ผู้เป็นศาสดาพยากรณ์ ประกอบด้วยฤทธิ์เดชในการงานและในถ้อยคําจําเพาะพระพักตร์พระเจ้า และต่อหน้าประชาชนทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 20, 'และพวกปุโรหิตใหญ่กับขุนนางทั้งหลายของเรา ได้มอบพระองค์ไว้ให้ปรับโทษถึงตาย และตรึงพระองค์ที่กางเขน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 21, 'แต่เราทั้งหลายได้หวังใจว่าจะเป็นพระองค์ผู้นั้นที่จะไถ่ชนชาติอิสราเอล ยิ่งกว่านั้นอีก วันนี้เป็นวันที่สามตั้งแต่เหตุการณ์นั้นเกิดขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 22, 'และยังมีผู้หญิงบางคนในพวกเราที่ได้ทําให้เราประหลาดใจ นางได้ไปที่อุโมงค์เมื่อเวลาเช้ามืด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 23, 'แต่เมื่อไม่พบพระศพของพระองค์ จึงมาเล่าว่านางได้เห็นนิมิตเป็นทูตสวรรค์ และทูตนั้นบอกว่าพระองค์ทรงพระชนม์อยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 24, 'บางคนที่อยู่กับเราก็ไปจนถึงอุโมงค์ และได้พบเหมือนพวกผู้หญิงเหล่านั้นได้บอก แต่เขาหาได้เห็นพระองค์ไม่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 25, 'พระองค์ตรัสแก่สองคนนั้นว่า “โอ คนเขลา และมีใจเฉื่อยในการเชื่อบรรดาคําซึ่งพวกศาสดาพยากรณ์ได้กล่าวไว้นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 26, 'จําเป็นซึ่งพระคริสต์จะต้องทนทุกข์ทรมานอย่างนั้น แล้วเข้าในสง่าราศีของพระองค์มิใช่หรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 27, 'พระองค์จึงทรงเริ่มอธิบายพระคัมภีร์ที่เล็งถึงพระองค์ทุกข้อให้เขาฟัง เริ่มต้นตั้งแต่โมเสสและบรรดาศาสดาพยากรณ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 28, 'เมื่อเขามาใกล้หมู่บ้านที่จะไปนั้น พระองค์ทรงกระทําเหมือนจะทรงดําเนินเลยไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 29, 'เขาจึงพูดหน่วงเหนี่ยวพระองค์ว่า “เชิญหยุดพักกับเรา เพราะว่าจวนเย็นแล้ว และวันก็ล่วงไปมาก” พระองค์จึงเสด็จเข้าไปเพื่อพักอยู่กับเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 30, 'ต่อมาเมื่อพระองค์ทรงเอนพระกายลงเสวยกับเขา พระองค์ทรงหยิบขนมปัง ขอบพระคุณ แล้วหักส่งให้เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 31, 'ตาของเขาก็หายฟางและเขาก็รู้จักพระองค์ แล้วพระองค์ก็อันตรธานไปจากเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 32, 'เขาจึงพูดกันว่า “ใจเราเร่าร้อนภายใน เมื่อพระองค์ตรัสกับเราตามทาง เมื่อพระองค์ทรงอธิบายพระคัมภีร์ให้เราฟังมิใช่หรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 33, 'แล้วคนทั้งสองนั้นก็ลุกขึ้นในโมงนั้นเองกลับไปยังกรุงเยรูซาเล็ม และพบพวกสาวกสิบเอ็ดคนชุมนุมกันอยู่พร้อมทั้งพรรคพวก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 34, 'กําลังพูดกันว่า “องค์พระผู้เป็นเจ้าทรงเป็นขึ้นมาแล้วจริงๆ และได้ปรากฏแก่ซีโมน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 35, 'ฝ่ายสองคนนั้นจึงเล่าความซึ่งเกิดขึ้นที่กลางทาง และที่เขาได้รู้จักพระองค์โดยการหักขนมปังนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 36, 'เมื่อเขาทั้งสองกําลังเล่าเหตุการณ์เหล่านั้น พระเยซูเองทรงยืนอยู่ที่ท่ามกลางเขา และตรัสกับเขาว่า “ท่านทั้งหลายจงเป็นสุขเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 37, 'ฝ่ายเขาทั้งหลายสะดุ้งตกใจกลัวคิดว่าเห็นผี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 38, 'พระองค์จึงตรัสแก่เขาว่า “ท่านทั้งหลายวุ่นวายใจทําไม เหตุไฉนความคิดลังเลจึงบังเกิดขึ้นในใจของท่านทั้งหลายเล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 39, 'จงดูมือของเราและเท้าของเราว่า เป็นเราเอง จงคลําตัวเราดู เพราะว่าผีไม่มีเนื้อและกระดูกเหมือนท่านเห็นเรามีอยู่นั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 40, 'เมื่อตรัสอย่างนั้นแล้ว พระองค์ทรงสําแดงพระหัตถ์และพระบาทให้เขาเห็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 41, 'เมื่อเขาทั้งหลายยังไม่ปลงใจเชื่อ เพราะเป็นเรื่องน่ายินดีอย่างเหลือเชื่อ และกําลังประหลาดใจอยู่ พระองค์จึงตรัสถามเขาว่า “พวกท่านมีอาหารกินที่นี่บ้างไหม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 42, 'เขาก็เอาปลาย่างชิ้นหนึ่งกับรวงผึ้งชิ้นหนึ่งมาถวายพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 43, 'พระองค์ทรงรับมาเสวยต่อหน้าเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 44, 'พระองค์ตรัสกับเขาว่า “นี่เป็นถ้อยคําของเรา ซึ่งเราได้บอกไว้แก่ท่านทั้งหลายเมื่อเรายังอยู่กับท่านว่า บรรดาคําที่เขียนไว้ในพระราชบัญญัติของโมเสส และในคัมภีร์ศาสดาพยากรณ์ และในหนังสือสดุดีกล่าวถึงเรานั้น จําเป็นจะต้องสําเร็จ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 45, 'ครั้งนั้น พระองค์ทรงบันดาลให้ใจเขาทั้งหลายเกิดความสว่างขึ้นเพื่อจะได้เข้าใจพระคัมภีร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 46, 'พระองค์ตรัสกับเขาว่า “มีคําเขียนไว้อย่างนั้นว่า พระคริสต์จะต้องทนทุกข์ทรมาน และเป็นขึ้นมาจากความตายในวันที่สาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 47, 'และจะต้องประกาศในพระนามของพระองค์เรื่องการกลับใจใหม่ และเรื่องยกบาปทั่วทุกประเทศ ตั้งต้นที่กรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 48, 'ท่านทั้งหลายเป็นพยานด้วยข้อความเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 49, 'และดูเถิด เราจะส่งซึ่งพระบิดาของเราทรงสัญญานั้นมาเหนือท่านทั้งหลาย แต่ท่านทั้งหลายจงคอยอยู่ในกรุงเยรูซาเล็ม กว่าท่านจะได้ประกอบด้วยฤทธิ์เดชที่มาจากเบื้องบน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 50, 'พระองค์จึงพาเขาออกไปถึงหมู่บ้านเบธานี แล้วทรงยกพระหัตถ์ อวยพรเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 51, 'ต่อมาเมื่อทรงอวยพรอยู่นั้น พระองค์จึงไปจากเขา แล้วทรงถูกรับขึ้นไปสู่สวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 52, 'เขาทั้งหลายจึงนมัสการพระองค์ แล้วกลับไปยังกรุงเยรูซาเล็ม มีความยินดีเป็นอันมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 53, 'เขาทั้งหลายอยู่ในพระวิหารทุกวัน สรรเสริญและเทิดทูนพระเจ้า เอเมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 1, 'ในเริ่มแรกนั้นพระวาทะทรงเป็นอยู่แล้ว และพระวาทะทรงอยู่กับพระเจ้า และพระวาทะทรงเป็นพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 2, 'ในเริ่มแรกนั้นพระองค์นั้นทรงอยู่กับพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 3, 'พระองค์ทรงสร้างสิ่งทั้งปวงขึ้นมา และในบรรดาสิ่งที่เป็นมานั้น ไม่มีสักสิ่งเดียวที่ได้เป็นมานอกเหนือพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 4, 'ในพระองค์มีชีวิต และชีวิตนั้นเป็นความสว่างของมนุษย์ทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 5, 'ความสว่างนั้นส่องเข้ามาในความมืด และความมืดหาได้เข้าใจความสว่างไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 6, 'มีชายคนหนึ่งที่พระเจ้าทรงใช้มา ชื่อยอห์น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 7, 'ท่านผู้นี้มาเพื่อเป็นพยาน เพื่อเป็นพยานถึงความสว่างนั้น เพื่อคนทั้งปวงจะได้มีความเชื่อเพราะท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 8, 'ท่านไม่ใช่ความสว่างนั้น แต่ทรงใช้มาเพื่อเป็นพยานถึงความสว่างนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 9, 'เป็นความสว่างแท้นั้น ซึ่งส่องสว่างแก่ทุกคนที่เข้ามาในโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 10, 'พระองค์ทรงอยู่ในโลก และพระองค์ได้ทรงสร้างโลก และโลกหาได้รู้จักพระองค์ไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 11, 'พระองค์ได้เสด็จมายังพวกของพระองค์ และพวกของพระองค์นั้นหาได้ต้อนรับพระองค์ไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 12, 'แต่ส่วนบรรดาผู้ที่ต้อนรับพระองค์ พระองค์ทรงประทานอํานาจให้เป็นบุตรของพระเจ้า คือคนทั้งหลายที่เชื่อในพระนามของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 13, 'ซึ่งมิได้เกิดจากเลือด หรือความประสงค์ของเนื้อหนัง หรือความประสงค์ของมนุษย์ แต่เกิดจากพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 14, 'พระวาทะได้ทรงสภาพของเนื้อหนัง และทรงอยู่ท่ามกลางเรา (และเราทั้งหลายได้เห็นสง่าราศีของพระองค์ คือสง่าราศีอันสมกับพระบุตรองค์เดียวที่บังเกิดจากพระบิดา) บริบูรณ์ด้วยพระคุณและความจริง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 15, 'ยอห์นได้เป็นพยานถึงพระองค์และร้องประกาศว่า “นี่แหละคือพระองค์ผู้ที่ข้าพเจ้าได้กล่าวถึงว่า พระองค์ผู้เสด็จมาภายหลังข้าพเจ้าทรงเป็นใหญ่กว่าข้าพเจ้า เพราะว่าพระองค์ทรงดํารงอยู่ก่อนข้าพเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 16, 'และเราทั้งหลายได้รับจากความบริบูรณ์ของพระองค์ เป็นพระคุณซ้อนพระคุณ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 17, 'เพราะว่าได้ทรงประทานพระราชบัญญัตินั้นทางโมเสส ส่วนพระคุณและความจริงมาทางพระเยซูคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 18, 'ไม่มีใครเคยเห็นพระเจ้าในเวลาใดเลย พระบุตรองค์เดียวที่บังเกิดมา ผู้ทรงสถิตในพระทรวงของพระบิดา พระองค์ได้ทรงสําแดงพระเจ้าแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 19, 'นี่แหละเป็นคําพยานของยอห์น เมื่อพวกยิวส่งพวกปุโรหิตและพวกเลวีจากกรุงเยรูซาเล็มไปถามท่านว่า “ท่านคือผู้ใด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 20, 'ท่านได้ยอมรับ และมิได้ปฏิเสธ แต่ได้ยอมรับว่า “ข้าพเจ้าไม่ใช่พระคริสต์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 21, 'เขาทั้งหลายจึงถามท่านว่า “ถ้าเช่นนั้นท่านเป็นใครเล่า ท่านเป็นเอลียาห์หรือ” ท่านตอบว่า “ข้าพเจ้าไม่ใช่เอลียาห์” “ท่านเป็นศาสดาพยากรณ์ผู้นั้นหรือ” และท่านตอบว่า “มิได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 22, 'คนเหล่านั้นจึงถามท่านว่า “ท่านเป็นใคร เพื่อเราจะได้ตอบผู้ที่ใช้เรามา ท่านกล่าวว่าท่านเป็นใคร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 23, 'ท่านตอบว่า “เราเป็นเสียงของผู้ที่ร้องในถิ่นทุรกันดารว่า ‘จงกระทํามรรคาขององค์พระผู้เป็นเจ้าให้ตรงไป’ ตามที่อิสยาห์ศาสดาพยากรณ์ได้กล่าวไว้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 24, 'ฝ่ายผู้ที่ได้รับใช้มานั้นเป็นของพวกฟาริสี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 25, 'เขาเหล่านั้นก็ได้ถามท่านว่า “ถ้าท่านไม่ใช่พระคริสต์ หรือเอลียาห์ หรือศาสดาพยากรณ์ผู้นั้นแล้ว ทําไมท่านจึงทําพิธีบัพติศมา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 26, 'ยอห์นได้ตอบเขาเหล่านั้นว่า “ข้าพเจ้าให้บัพติศมาด้วยน้ํา แต่มีพระองค์หนึ่งซึ่งประทับอยู่ในหมู่พวกท่านนั้น ท่านไม่รู้จัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 27, 'พระองค์นั้นแหละ ผู้เสด็จมาภายหลังข้าพเจ้าทรงเป็นใหญ่กว่าข้าพเจ้า แม้สายรัดฉลองพระบาทของพระองค์ ข้าพเจ้าก็ไม่บังควรที่จะแก้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 28, 'เหตุการณ์นี้เกิดขึ้นที่เบธาบาราฟากแม่น้ําจอร์แดนข้างโน้น อันเป็นที่ซึ่งยอห์นกําลังให้บัพติศมาอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 29, 'วันรุ่งขึ้นยอห์นเห็นพระเยซูกําลังเสด็จมาทางท่าน ท่านจึงกล่าวว่า “จงดูพระเมษโปดกของพระเจ้า ผู้ทรงรับความผิดบาปของโลกไปเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 30, 'พระองค์นี้แหละที่ข้าพเจ้าได้กล่าวว่า ‘ภายหลังข้าพเจ้าจะมีผู้หนึ่งเสด็จมาเป็นใหญ่กว่าข้าพเจ้า เพราะว่าพระองค์ทรงดํารงอยู่ก่อนข้าพเจ้า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 31, 'ข้าพเจ้าเองก็ไม่ได้รู้จักพระองค์ แต่เพื่อให้พระองค์ทรงเป็นที่ประจักษ์แก่พวกอิสราเอล ข้าพเจ้าจึงได้มาให้บัพติศมาด้วยน้ํา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 32, 'และยอห์นกล่าวเป็นพยานว่า “ข้าพเจ้าเห็นพระวิญญาณเหมือนดังนกเขาเสด็จลงมาจากสวรรค์ และทรงสถิตบนพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 33, 'ข้าพเจ้าเองไม่รู้จักพระองค์ แต่พระองค์ ผู้ได้ทรงใช้ให้ข้าพเจ้าให้บัพติศมาด้วยน้ํา พระองค์นั้นได้ตรัสกับข้าพเจ้าว่า ‘เมื่อเจ้าเห็นพระวิญญาณเสด็จลงมาและสถิตอยู่บนผู้ใด ผู้นั้นแหละเป็นผู้ให้บัพติศมาด้วยพระวิญญาณบริสุทธิ์’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 34, 'และข้าพเจ้าก็ได้เห็นแล้ว และได้เป็นพยานว่า พระองค์นี้แหละ เป็นพระบุตรของพระเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 35, 'รุ่งขึ้นอีกวันหนึ่งยอห์นกําลังยืนอยู่กับสาวกของท่านสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 36, 'และท่านมองดูพระเยซูขณะที่พระองค์ทรงดําเนินและกล่าวว่า “จงดูพระเมษโปดกของพระเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 37, 'สาวกสองคนนั้นได้ยินท่านพูดเช่นนี้ เขาจึงติดตามพระเยซูไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 38, 'พระเยซูทรงเหลียวหลังและทอดพระเนตรเห็นเขาตามพระองค์มา จึงตรัสถามเขาว่า “ท่านหาอะไร” และเขาทั้งสองทูลพระองค์ว่า “รับบี” (ซึ่งแปลว่าอาจารย์) “ท่านอยู่ที่ไหน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 39, 'พระองค์ตรัสตอบเขาว่า “มาดูเถิด” เขาก็ไปและเห็นที่ซึ่งพระองค์ทรงอาศัยและวันนั้นเขาก็ได้พักอยู่กับพระองค์ เพราะขณะนั้นประมาณสี่โมงเย็นแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 40, 'คนหนึ่งในสองคนที่ได้ยินยอห์นพูด และได้ติดตามพระองค์ไปนั้น คืออันดรูว์น้องชายของซีโมนเปโตร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 41, 'แล้วอันดรูว์ก็ไปหาซีโมนพี่ชายของตนก่อน และบอกเขาว่า “เราได้พบพระเมสสิยาห์แล้ว” ซึ่งแปลว่าพระคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 42, 'อันดรูว์จึงพาซีโมนไปเฝ้าพระเยซู และเมื่อพระเยซูทรงทอดพระเนตรเขาแล้วจึงตรัสว่า “ท่านคือซีโมนบุตรชายโยนาห์ เขาจะเรียกท่านว่าเคฟาส” ซึ่งแปลว่าศิลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 43, 'วันรุ่งขึ้นพระเยซูตั้งพระทัยจะเสด็จไปยังแคว้นกาลิลี และพระองค์ทรงพบฟีลิปจึงตรัสกับเขาว่า “จงตามเรามา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 44, 'ฟีลิปมาจากเบธไซดา เมืองของอันดรูว์และเปโตร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 45, 'ฟีลิปไปหานาธานาเอลและบอกเขาว่า “เราได้พบพระองค์ผู้ที่โมเสสได้กล่าวถึงในพระราชบัญญัติ และที่พวกศาสดาพยากรณ์ได้กล่าวถึง คือพระเยซูชาวนาซาเร็ธบุตรชายโยเซฟ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 46, 'นาธานาเอลถามเขาว่า “สิ่งดีอันใดจะมาจากนาซาเร็ธได้หรือ” ฟีลิปตอบเขาว่า “มาดูเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 47, 'พระเยซูทอดพระเนตรเห็นนาธานาเอลมาหาพระองค์จึงตรัสถึงเรื่องตัวเขาว่า “ดูเถิด ชนอิสราเอลแท้ ในตัวเขาไม่มีอุบาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 48, 'นาธานาเอลทูลถามพระองค์ว่า “พระองค์ทรงรู้จักข้าพระองค์ได้อย่างไร” พระเยซูตรัสตอบเขาว่า “ก่อนที่ฟีลิปจะเรียกท่าน เมื่อท่านอยู่ที่ใต้ต้นมะเดื่อนั้น เราเห็นท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 49, 'นาธานาเอลทูลตอบพระองค์ว่า “รับบี พระองค์ทรงเป็นพระบุตรของพระเจ้า พระองค์ทรงเป็นกษัตริย์ของชนชาติอิสราเอล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 50, 'พระเยซูตรัสตอบเขาว่า “เพราะเราบอกท่านว่า เราเห็นท่านอยู่ใต้ต้นมะเดื่อนั้น ท่านจึงเชื่อหรือ ท่านจะได้เห็นเหตุการณ์ใหญ่กว่านั้นอีก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 51, 'และพระองค์ตรัสกับเขาว่า “เราบอกความจริงแก่ท่านทั้งหลายว่า ภายหลังท่านจะได้เห็นท้องฟ้าเปิดออก และเหล่าทูตสวรรค์ของพระเจ้าขึ้นและลงอยู่เหนือบุตรมนุษย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 1, 'วันที่สามมีงานสมรสที่หมู่บ้านคานาแคว้นกาลิลี และมารดาของพระเยซูก็อยู่ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 2, 'พระเยซูและสาวกของพระองค์ได้รับเชิญไปในงานนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 3, 'เมื่อน้ําองุ่นหมดแล้ว มารดาของพระเยซูทูลพระองค์ว่า “เขาไม่มีน้ําองุ่น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 4, 'พระเยซูตรัสกับนางว่า “หญิงเอ๋ย ข้าพเจ้าเกี่ยวข้องอะไรกับท่านเล่า เวลาของข้าพเจ้ายังไม่มาถึง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 5, 'มารดาของพระองค์จึงบอกพวกคนใช้ว่า “ท่านจะสั่งพวกเจ้าให้ทําสิ่งใด ก็จงกระทําตามเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 6, 'มีโอ่งหินตั้งอยู่ที่นั่นหกใบตามธรรมเนียมการชําระของพวกยิว จุน้ําใบละสี่ห้าถัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 7, 'พระเยซูตรัสสั่งเขาว่า “จงตักน้ําใส่โอ่งให้เต็มเถิด” และเขาก็ตักน้ําใส่โอ่งเต็มเสมอปาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 8, 'แล้วพระองค์ตรัสสั่งเขาว่า “จงตักเอาไปให้เจ้าภาพเถิด” เขาก็เอาไปให้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 9, 'เมื่อเจ้าภาพชิมน้ําที่กลายเป็นน้ําองุ่นแล้ว และไม่รู้ว่ามาจากไหน (แต่คนใช้ที่ตักน้ํานั้นรู้) เจ้าภาพจึงเรียกเจ้าบ่าวมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 10, 'และพูดกับเขาว่า “ใครๆเขาก็เอาน้ําองุ่นอย่างดีมาให้ก่อน และเมื่อได้ดื่มกันมากแล้วจึงเอาที่ไม่สู้ดีมา แต่ท่านเก็บน้ําองุ่นอย่างดีไว้จนถึงบัดนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 11, 'การอัศจรรย์ครั้งแรกนี้พระเยซูได้ทรงกระทําที่บ้านคานาแคว้นกาลิลี และได้ทรงสําแดงสง่าราศีของพระองค์ และสาวกของพระองค์ก็ได้เชื่อในพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 12, 'ภายหลังเหตุการณ์นี้พระองค์ก็เสด็จลงไปยังเมืองคาเปอรนาอุม พร้อมกับมารดาและน้องชายและสาวกของพระองค์ และอยู่ที่นั่นเพียงไม่กี่วัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 13, 'เทศกาลปัสกาของพวกยิวใกล้เข้ามาแล้ว และพระเยซูเสด็จขึ้นไปยังกรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 14, 'ในพระวิหารพระองค์ทรงพบคนขายวัว ขายแกะ ขายนกเขา และคนรับแลกเงินนั่งอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 15, 'เมื่อพระองค์ทรงเอาเชือกทําเป็นแส้ พระองค์ทรงไล่คนเหล่านั้น พร้อมกับแกะและวัวออกไปจากพระวิหาร และทรงเทเงินของคนรับแลกเงินและคว่ําโต๊ะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 16, 'และพระองค์ตรัสแก่บรรดาคนขายนกเขาว่า “จงเอาของเหล่านี้ไปเสีย อย่าทําพระนิเวศของพระบิดาเราให้เป็นที่ค้าขาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 17, 'พวกสาวกของพระองค์ก็ระลึกขึ้นได้ถึงคําที่เขียนไว้ว่า ‘ความร้อนใจในเรื่องพระนิเวศของพระองค์ได้ท่วมท้นข้าพระองค์’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 18, 'พวกยิวจึงทูลพระองค์ว่า “ท่านจะแสดงหมายสําคัญอะไรให้เราเห็น ว่าท่านมีอํานาจกระทําการเช่นนี้ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 19, 'พระเยซูจึงตรัสตอบเขาทั้งหลายว่า “ทําลายวิหารนี้เสีย แล้วเราจะยกขึ้นในสามวัน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 20, 'พวกยิวจึงทูลว่า “พระวิหารนี้เขาสร้างถึงสี่สิบหกปีจึงสําเร็จ และท่านจะยกขึ้นใหม่ในสามวันหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 21, 'แต่พระวิหารที่พระองค์ตรัสถึงนั้นคือพระกายของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 22, 'เหตุฉะนั้นเมื่อพระองค์ทรงเป็นขึ้นมาจากความตายแล้ว พวกสาวกของพระองค์ก็ระลึกได้ว่าพระองค์ได้ตรัสดังนี้ไว้แก่เขา และเขาก็เชื่อพระคัมภีร์และพระดํารัสที่พระเยซูได้ตรัสแล้วนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 23, 'เมื่อพระองค์ประทับ ณ กรุงเยรูซาเล็มในวันเลี้ยงเทศกาลปัสกานั้น มีคนเป็นอันมากได้เชื่อในพระนามของพระองค์ เมื่อเขาได้เห็นการอัศจรรย์ที่พระองค์ได้ทรงกระทํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 24, 'แต่พระเยซูมิได้ทรงวางพระทัยในคนเหล่านั้น เพราะพระองค์ทรงรู้จักมนุษย์ทุกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 25, 'และไม่มีความจําเป็นที่จะมีพยานในเรื่องมนุษย์ ด้วยพระองค์เองทรงทราบว่าอะไรมีอยู่ในมนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 1, 'มีชายคนหนึ่งในพวกฟาริสีชื่อนิโคเดมัสเป็นขุนนางของพวกยิว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 2, 'ชายผู้นี้ได้มาหาพระเยซูในเวลากลางคืนและทูลพระองค์ว่า “รับบี พวกข้าพเจ้าทราบอยู่ว่าท่านเป็นครูที่มาจากพระเจ้า เพราะไม่มีผู้ใดกระทําการอัศจรรย์ซึ่งท่านได้กระทํานั้นได้ นอกจากว่าพระเจ้าทรงสถิตอยู่กับเขาด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 3, 'พระเยซูตรัสตอบเขาว่า “เราบอกความจริงแก่ท่านว่า ถ้าผู้ใดไม่ได้บังเกิดใหม่ ผู้นั้นจะเห็นอาณาจักรของพระเจ้าไม่ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 4, 'นิโคเดมัสทูลพระองค์ว่า “คนชราแล้วจะบังเกิดใหม่อย่างไรได้ จะเข้าในครรภ์มารดาครั้งที่สองและบังเกิดใหม่ได้หรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 5, 'พระเยซูตรัสตอบว่า “เราบอกความจริงแก่ท่านว่า ถ้าผู้ใดไม่ได้บังเกิดจากน้ําและพระวิญญาณ ผู้นั้นจะเข้าในอาณาจักรของพระเจ้าไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 6, 'ซึ่งบังเกิดจากเนื้อหนังก็เป็นเนื้อหนัง และซึ่งบังเกิดจากพระวิญญาณก็คือจิตวิญญาณ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 7, 'อย่าประหลาดใจที่เราบอกท่านว่า ท่านต้องบังเกิดใหม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 8, 'ลมใคร่จะพัดไปข้างไหนก็พัดไปข้างนั้น และท่านได้ยินเสียงลมนั้น แต่ท่านไม่รู้ว่าลมมาจากไหนและไปที่ไหน คนที่บังเกิดจากพระวิญญาณก็เป็นอย่างนั้นทุกคน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 9, 'นิโคเดมัสทูลพระองค์ว่า “เหตุการณ์อย่างนี้จะเป็นไปอย่างไรได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 10, 'พระเยซูตรัสตอบเขาว่า “ท่านเป็นอาจารย์ของชนอิสราเอล และยังไม่เข้าใจสิ่งเหล่านี้หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 11, 'เราบอกความจริงแก่ท่านว่า พวกเราพูดสิ่งที่เรารู้ และเป็นพยานถึงสิ่งที่เราได้เห็น และท่านหาได้รับคําพยานของเราไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 12, 'ถ้าเราบอกท่านถึงสิ่งฝ่ายโลกและท่านไม่เชื่อ ถ้าเราบอกท่านถึงสิ่งฝ่ายสวรรค์ ท่านจะเชื่อได้อย่างไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 13, 'ไม่มีผู้ใดได้ขึ้นไปสู่สวรรค์นอกจากท่านที่ลงมาจากสวรรค์ คือบุตรมนุษย์ผู้ทรงสถิตในสวรรค์นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 14, 'โมเสสได้ยกงูขึ้นในถิ่นทุรกันดารฉันใด บุตรมนุษย์จะต้องถูกยกขึ้นฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 15, 'เพื่อผู้ใดที่เชื่อในพระองค์จะไม่พินาศ แต่มีชีวิตนิรันดร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 16, 'เพราะว่าพระเจ้าทรงรักโลก จนได้ทรงประทานพระบุตรองค์เดียวของพระองค์ที่บังเกิดมา เพื่อผู้ใดที่เชื่อในพระบุตรนั้นจะไม่พินาศ แต่มีชีวิตนิรันดร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 17, 'เพราะว่าพระเจ้าไม่ได้ทรงใช้พระบุตรของพระองค์เข้ามาในโลกเพื่อจะพิพากษาโลก แต่เพื่อช่วยโลกให้รอดโดยพระบุตรนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 18, 'ผู้ที่เชื่อในพระบุตรก็ไม่ต้องถูกพิพากษาลงโทษ แต่ผู้ที่มิได้เชื่อก็ต้องถูกพิพากษาลงโทษอยู่แล้ว เพราะเขามิได้เชื่อในพระนามพระบุตรองค์เดียวที่บังเกิดจากพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 19, 'หลักของการพิพากษามีอย่างนี้ คือความสว่างได้เข้ามาในโลกแล้ว แต่มนุษย์ได้รักความมืดมากกว่ารักความสว่าง เพราะกิจการของเขาชั่ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 20, 'เพราะทุกคนที่ประพฤติชั่วก็เกลียดความสว่าง และไม่มาถึงความสว่าง ด้วยกลัวว่าการกระทําของตนจะถูกตําหนิ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 21, 'แต่ผู้ที่ประพฤติตามความจริงก็มาสู่ความสว่าง เพื่อจะให้การกระทําของตนปรากฏว่า ได้กระทําการนั้นโดยพึ่งพระเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 22, 'ภายหลังเหตุการณ์เหล่านี้พระเยซูก็เสด็จเข้าไปในแคว้นยูเดียกับสาวกของพระองค์ และทรงประทับที่นั่นกับเขา และให้บัพติศมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 23, 'ยอห์นก็ให้บัพติศมาอยู่ที่อายโนนใกล้หมู่บ้านสาลิมเหมือนกัน เพราะที่นั่นมีน้ํามาก และผู้คนก็พากันมารับบัพติศมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 24, 'เพราะยอห์นยังไม่ติดคุก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 25, 'เกิดการโต้เถียงกันขึ้นระหว่างสาวกของยอห์นกับพวกยิวเรื่องการชําระ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 26, 'สาวกของยอห์นจึงไปหายอห์นและพูดว่า “รับบี ท่านที่อยู่กับอาจารย์ฟากแม่น้ําจอร์แดนข้างโน้น ผู้ที่อาจารย์เป็นพยานถึงนั้น ดูเถิด ท่านผู้นั้นให้บัพติศมาและคนทั้งปวงก็พากันไปหาท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 27, 'ยอห์นตอบว่า “มนุษย์จะรับสิ่งใดไม่ได้ นอกจากที่ทรงประทานจากสวรรค์ให้เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 28, 'ท่านทั้งหลายเองก็ได้เป็นพยานของข้าพเจ้าว่า ข้าพเจ้าได้พูดว่า ข้าพเจ้ามิใช่พระคริสต์ แต่ข้าพเจ้าได้รับพระบัญชาให้นําเสด็จพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 29, 'ท่านที่มีเจ้าสาวนั่นแหละคือเจ้าบ่าว แต่สหายของเจ้าบ่าวที่ยืนฟังเจ้าบ่าว ก็ชื่นชมยินดีอย่างยิ่งเมื่อได้ยินเสียงของเจ้าบ่าว ฉะนั้นความปีติยินดีของข้าพเจ้าจึงเต็มเปี่ยมแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 30, 'พระองค์ต้องทรงยิ่งใหญ่ขึ้น แต่ข้าพเจ้าต้องด้อยลง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 31, 'พระองค์ผู้เสด็จมาจากเบื้องบนทรงเป็นใหญ่เหนือทุกสิ่ง ผู้ที่มาจากโลกก็เป็นฝ่ายโลกและพูดตามอย่างโลก พระองค์ผู้เสด็จมาจากสวรรค์ทรงเป็นใหญ่เหนือทุกสิ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 32, 'พระองค์ทรงเป็นพยานถึงสิ่งซึ่งพระองค์ทอดพระเนตรเห็นและได้ยิน แต่ไม่มีผู้ใดรับคําพยานของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 33, 'ผู้ที่รับคําพยานของพระองค์ก็ประทับตราลงว่า พระเจ้าทรงสัตย์จริง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 34, 'เพราะพระองค์ ผู้ที่พระเจ้าทรงใช้มานั้น ทรงกล่าวพระวจนะของพระเจ้า เพราะพระเจ้าได้ทรงประทานพระวิญญาณอย่างไม่จํากัดแด่พระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 35, 'พระบิดาทรงรักพระบุตรและทรงมอบทุกสิ่งไว้ในพระหัตถ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 36, 'ผู้ที่เชื่อในพระบุตรก็มีชีวิตนิรันดร์ ผู้ที่ไม่เชื่อในพระบุตรก็จะไม่เห็นชีวิต แต่พระพิโรธของพระเจ้าตกอยู่กับเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 1, 'เหตุฉะนั้นเมื่อองค์พระผู้เป็นเจ้าทรงทราบว่า พวกฟาริสีได้ยินว่า พระเยซูทรงมีสาวกและให้บัพติศมามากกว่ายอห์น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 2, '(แม้ว่าพระเยซูไม่ได้ทรงให้บัพติศมาเอง แต่สาวกของพระองค์เป็นผู้ให้)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 3, 'พระองค์จึงเสด็จออกจากแคว้นยูเดียและกลับไปยังแคว้นกาลิลีอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 4, 'พระองค์จําต้องเสด็จผ่านแคว้นสะมาเรีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 5, 'พระองค์จึงเสด็จไปถึงเมืองหนึ่งชื่อสิคาร์ในแคว้นสะมาเรีย ใกล้ที่ดินซึ่งยาโคบให้แก่โยเซฟบุตรชายของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 6, 'บ่อน้ําของยาโคบอยู่ที่นั่น พระเยซูทรงดําเนินทางมาเหน็ดเหนื่อยจึงประทับบนขอบบ่อนั้น เป็นเวลาประมาณเที่ยง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 7, 'มีหญิงชาวสะมาเรียคนหนึ่งมาตักน้ํา พระเยซูตรัสกับนางว่า “ขอน้ําให้เราดื่มบ้าง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 8, '(ขณะนั้นสาวกของพระองค์เข้าไปซื้ออาหารในเมือง)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 9, 'หญิงชาวสะมาเรียทูลพระองค์ว่า “ไฉนท่านผู้เป็นยิวจึงขอน้ําดื่มจากดิฉันผู้เป็นหญิงสะมาเรีย เพราะพวกยิวไม่คบหาชาวสะมาเรียเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 10, 'พระเยซูตรัสตอบนางว่า “ถ้าเจ้าได้รู้จักของประทานของพระเจ้า และรู้จักผู้ที่พูดกับเจ้าว่า ‘ขอน้ําให้เราดื่มบ้าง’ เจ้าจะได้ขอจากท่านผู้นั้น และท่านผู้นั้นจะให้น้ําประกอบด้วยชีวิตแก่เจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 11, 'นางทูลพระองค์ว่า “ท่านเจ้าคะ ท่านไม่มีถังตัก และบ่อนี้ก็ลึก ท่านจะได้น้ําประกอบด้วยชีวิตนั้นมาจากไหน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 12, 'ท่านเป็นใหญ่กว่ายาโคบบรรพบุรุษของเรา ผู้ได้ให้บ่อน้ํานี้แก่เราหรือ และยาโคบเองก็ได้ดื่มจากบ่อนี้รวมทั้งบุตรและฝูงสัตว์ของท่านด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 13, 'พระเยซูตรัสตอบนางว่า “ผู้ใดที่ดื่มน้ํานี้จะกระหายอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 14, 'แต่ผู้ใดที่ดื่มน้ําซึ่งเราจะให้แก่เขานั้นจะไม่กระหายอีกเลย แต่น้ําซึ่งเราจะให้เขานั้นจะบังเกิดเป็นบ่อน้ําพุในตัวเขาพลุ่งขึ้นถึงชีวิตนิรันดร์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 15, 'นางทูลพระองค์ว่า “ท่านเจ้าคะ ขอน้ํานั้นให้ดิฉันเถิด เพื่อดิฉันจะได้ไม่กระหายอีกและจะได้ไม่ต้องมาตักที่นี่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 16, 'พระเยซูตรัสกับนางว่า “ไปเรียกสามีของเจ้ามานี่เถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 17, 'นางทูลตอบว่า “ดิฉันไม่มีสามีค่ะ” พระเยซูตรัสกับนางว่า “เจ้าพูดถูกแล้วว่า ‘ดิฉันไม่มีสามี’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 18, 'เพราะเจ้าได้มีสามีห้าคนแล้ว และคนที่เจ้ามีอยู่เดี๋ยวนี้ก็ไม่ใช่สามีของเจ้า เรื่องนี้เจ้าพูดจริง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 19, 'นางทูลพระองค์ว่า “ท่านเจ้าคะ ดิฉันเห็นจริงแล้วว่าท่านเป็นศาสดาพยากรณ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 20, 'บรรพบุรุษของพวกเรานมัสการที่ภูเขานี้ แต่พวกท่านว่าสถานที่ที่ควรนมัสการนั้นคือกรุงเยรูซาเล็ม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 21, 'พระเยซูตรัสกับนางว่า “หญิงเอ๋ย เชื่อเราเถิด จะมีเวลาหนึ่งที่พวกเจ้าจะมิได้ไหว้นมัสการพระบิดาเฉพาะที่ภูเขานี้ หรือที่กรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 22, 'ซึ่งพวกเจ้านมัสการนั้นเจ้าไม่รู้จัก ซึ่งพวกเรานมัสการเรารู้จัก เพราะความรอดนั้นเนื่องมาจากพวกยิว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 23, 'แต่เวลานั้นใกล้เข้ามาแล้ว และบัดนี้ก็ถึงแล้ว คือเมื่อผู้ที่นมัสการอย่างถูกต้อง จะนมัสการพระบิดาด้วยจิตวิญญาณและความจริง เพราะว่าพระบิดาทรงแสวงหาคนเช่นนั้นนมัสการพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 24, 'พระเจ้าทรงเป็นพระวิญญาณ และผู้ที่นมัสการพระองค์ต้องนมัสการด้วยจิตวิญญาณและความจริง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 25, 'นางทูลพระองค์ว่า “ดิฉันทราบว่าพระเมสสิยาห์ที่เรียกว่า พระคริสต์ จะเสด็จมา เมื่อพระองค์เสด็จมาพระองค์จะทรงชี้แจงทุกสิ่งแก่เรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 26, 'พระเยซูตรัสกับนางว่า “เราที่พูดกับเจ้าคือท่านผู้นั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 27, 'ขณะนั้นสาวกของพระองค์ก็มาถึง และเขาประหลาดใจที่พระองค์ทรงสนทนากับผู้หญิง แต่ไม่มีใครถามว่า “พระองค์ทรงประสงค์อะไร” หรือ “ทําไมพระองค์จึงทรงสนทนากับนาง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 28, 'หญิงนั้นจึงทิ้งหม้อน้ําไว้และเข้าไปในเมืองและบอกคนทั้งปวงว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 29, '“มาดูท่านผู้หนึ่งที่เล่าถึงสิ่งสารพัดซึ่งฉันได้กระทํา ท่านผู้นี้มิใช่พระคริสต์หรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 30, 'คนทั้งหลายจึงพากันออกจากเมืองไปหาพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 31, 'ในระหว่างนั้นพวกสาวกทูลเชิญพระองค์ว่า “พระอาจารย์เจ้าข้า เชิญรับประทานเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 32, 'แต่พระองค์ตรัสกับเขาว่า “เรามีอาหารรับประทานที่ท่านทั้งหลายไม่รู้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 33, 'พวกสาวกจึงถามกันว่า “มีใครเอาอาหารมาถวายพระองค์แล้วหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 34, 'พระเยซูตรัสกับเขาว่า “อาหารของเราคือการกระทําตามพระทัยของพระองค์ผู้ทรงใช้เรามา และทําให้งานของพระองค์สําเร็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 35, 'ท่านทั้งหลายว่า อีกสี่เดือนจะถึงฤดูเกี่ยวข้าวมิใช่หรือ ดูเถิด เราบอกท่านทั้งหลายว่า เงยหน้าขึ้นดูนาเถิด ว่าทุ่งนาก็ขาว ถึงเวลาเกี่ยวแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 36, 'คนที่เกี่ยวก็กําลังได้รับค่าจ้าง และกําลังส่ําสมพืชผลไว้สําหรับชีวิตนิรันดร์ เพื่อทั้งคนหว่านและคนเกี่ยวจะชื่นชมยินดีด้วยกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 37, 'เพราะในเรื่องนี้คําที่กล่าวไว้นี้เป็นความจริง คือ ‘คนหนึ่งหว่านและอีกคนหนึ่งเกี่ยว’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 38, 'เราใช้ท่านทั้งหลายไปเกี่ยวสิ่งที่ท่านมิได้ลงแรงทํา คนอื่นได้ลงแรงทํา และท่านได้ประโยชน์จากแรงของเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 39, 'ชาวสะมาเรียเป็นอันมากที่มาจากเมืองนั้นได้เชื่อในพระองค์ เพราะคําพยานของหญิงผู้นั้น ที่ว่า “ท่านเล่าถึงสิ่งสารพัดซึ่งฉันได้กระทํา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 40, 'ฉะนั้นเมื่อชาวสะมาเรียมาถึงพระองค์ เขาจึงทูลเชิญพระองค์ให้ประทับอยู่กับเขา และพระองค์ก็ประทับที่นั่นสองวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 41, 'และคนอื่นเป็นอันมากได้เชื่อเพราะพระดํารัสของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 42, 'เขาเหล่านั้นพูดกับหญิงนั้นว่า “ตั้งแต่นี้ไปที่เราเชื่อนั้นมิใช่เพราะคําของเจ้า แต่เพราะเราได้ยินเอง และเรารู้แน่ว่าท่านองค์นี้เป็นผู้ช่วยโลกให้รอด คือพระคริสต์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 43, 'ครั้นล่วงไปสองวัน พระองค์ก็เสด็จออกจากที่นั่นไปยังแคว้นกาลิลี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 44, 'เพราะพระเยซูเองทรงเป็นพยานว่า “ศาสดาพยากรณ์ไม่ได้รับเกียรติในบ้านเมืองของตน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 45, 'ฉะนั้นเมื่อพระองค์เสด็จไปถึงแคว้นกาลิลี ชาวกาลิลีได้ต้อนรับพระองค์ เพราะเขาได้เห็นทุกสิ่งซึ่งพระองค์ได้ทรงกระทําในเทศกาลเลี้ยง ณ กรุงเยรูซาเล็ม เพราะเขาทั้งหลายได้ไปในเทศกาลเลี้ยงนั้นด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 46, 'ฉะนั้นพระเยซูจึงได้เสด็จไปยังหมู่บ้านคานาแคว้นกาลิลีอีก อันเป็นที่ซึ่งพระองค์ทรงกระทําให้น้ํากลายเป็นน้ําองุ่น และที่เมืองคาเปอรนาอุมมีขุนนางคนหนึ่ง บุตรชายของท่านป่วยหนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 47, 'เมื่อท่านได้ยินข่าวว่า พระเยซูได้เสด็จมาจากแคว้นยูเดียไปยังแคว้นกาลิลีแล้ว ท่านจึงไปทูลอ้อนวอนพระองค์ให้เสด็จลงไปรักษาบุตรของตน เพราะบุตรจวนจะตายแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 48, 'พระเยซูจึงตรัสกับเขาว่า “ถ้าพวกท่านไม่เห็นหมายสําคัญและการมหัศจรรย์ ท่านก็จะไม่เชื่อ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 49, 'ขุนนางผู้นั้นทูลพระองค์ว่า “พระองค์เจ้าข้า ขอเสด็จไปก่อนที่บุตรของข้าพระองค์จะตาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 50, 'พระเยซูตรัสกับท่านว่า “กลับไปเถิด บุตรชายของท่านจะไม่ตาย” ท่านก็เชื่อพระดํารัสที่พระเยซูตรัสกับท่าน จึงทูลลาไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 51, 'ขณะที่ท่านกลับไปนั้น พวกผู้รับใช้ของท่านได้มาพบและเรียนท่านว่า “บุตรชายของท่านหายแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 52, 'ท่านจึงถามถึงเวลาที่บุตรค่อยทุเลาขึ้นนั้น และพวกผู้รับใช้ก็เรียนท่านว่า “ไข้หายเมื่อวานนี้เวลาบ่ายโมง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 53, 'บิดาจึงรู้ว่าชั่วโมงนั้นเป็นเวลาที่พระเยซูได้ตรัสกับตนว่า “บุตรชายของท่านจะไม่ตาย” และท่านเองก็เชื่อพร้อมทั้งครัวเรือนของท่านด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 54, 'นี่เป็นการอัศจรรย์ที่สองซึ่งพระเยซูทรงกระทํา เมื่อพระองค์เสด็จจากแคว้นยูเดียไปยังแคว้นกาลิลี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 1, 'หลังจากนั้นก็ถึงเทศกาลเลี้ยงของพวกยิว และพระเยซูก็เสด็จขึ้นไปยังกรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 2, 'ในกรุงเยรูซาเล็มที่ริมประตูแกะมีสระอยู่สระหนึ่ง ภาษาฮีบรูเรียกสระนั้นว่า เบธซาธา เป็นที่ซึ่งมีศาลาห้าหลัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 3, 'ในศาลาเหล่านั้นมีคนป่วยเป็นอันมากนอนอยู่ คนตาบอด คนง่อย คนผอมแห้ง กําลังคอยน้ํากระเพื่อม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 4, 'ด้วยมีทูตสวรรค์องค์หนึ่งลงมากวนน้ําในสระนั้นเป็นครั้งคราว เมื่อน้ํากระเพื่อมนั้น ผู้ใดก้าวลงไปในน้ําก่อน ก็จะหายจากโรคที่เขาเป็นอยู่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 5, 'ที่นั่นมีชายคนหนึ่งป่วยมาสามสิบแปดปีแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 6, 'เมื่อพระเยซูทอดพระเนตรคนนั้นนอนอยู่และทรงทราบว่า เขาป่วยอยู่อย่างนั้นนานแล้ว พระองค์ตรัสกับเขาว่า “เจ้าปรารถนาจะหายโรคหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 7, 'คนป่วยนั้นทูลตอบพระองค์ว่า “ท่านเจ้าข้า เมื่อน้ํากําลังกระเพื่อมนั้น ไม่มีผู้ใดที่จะเอาตัวข้าพเจ้าลงไปในสระ และเมื่อข้าพเจ้ากําลังไป คนอื่นก็ลงไปก่อนแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 8, 'พระเยซูตรัสกับเขาว่า “จงลุกขึ้นยกแคร่ของเจ้าและเดินไปเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 9, 'ในทันใดนั้นคนนั้นก็หายโรค และเขาก็ยกแคร่ของเขาเดินไป วันนั้นเป็นวันสะบาโต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 10, 'ดังนั้นพวกยิวจึงพูดกับชายที่หายโรคนั้นว่า “วันนี้เป็นวันสะบาโต ที่เจ้าแบกแคร่ไปนั้นก็ผิดพระราชบัญญัติ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 11, 'คนนั้นจึงตอบเขาเหล่านั้นว่า “ท่านที่รักษาข้าพเจ้าให้หายโรคได้สั่งข้าพเจ้าว่า ‘จงยกแคร่ของเจ้าแบกเดินไปเถิด’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 12, 'เขาเหล่านั้นถามคนนั้นว่า “คนที่สั่งเจ้าว่า ‘จงยกแคร่ของเจ้าแบกเดินไปเถิด’ นั้น เป็นผู้ใด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 13, 'คนที่ได้รับการรักษาให้หายโรคนั้นไม่รู้ว่าเป็นผู้ใด เพราะพระเยซูเสด็จหลบไปแล้ว เนื่องจากขณะนั้นมีคนอยู่ที่นั่นเป็นอันมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 14, 'ภายหลังพระเยซูได้ทรงพบคนนั้นในพระวิหารและตรัสกับเขาว่า “ดูเถิด เจ้าหายโรคแล้ว อย่าทําบาปอีก มิฉะนั้นเหตุร้ายกว่านั้นจะเกิดกับเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 15, 'ชายคนนั้นก็ได้ออกไปและบอกพวกยิวว่า ท่านที่ได้รักษาเขาให้หายโรคนั้นคือพระเยซู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 16, 'เหตุฉะนั้นพวกยิวจึงข่มเหงพระเยซู และแสวงหาโอกาสที่จะฆ่าพระองค์ เพราะพระองค์ทรงกระทําเช่นนั้นในวันสะบาโต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 17, 'แต่พระเยซูตรัสตอบเขาว่า “พระบิดาของเราก็ยังทรงกระทําการอยู่จนถึงบัดนี้ และเราก็ทําด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 18, 'เหตุฉะนั้นพวกยิวยิ่งแสวงหาโอกาสที่จะฆ่าพระองค์ มิใช่เพราะพระองค์ล่วงกฎวันสะบาโตเท่านั้น แต่ยังได้เรียกพระเจ้าว่าเป็นบิดาของตนด้วย ซึ่งเป็นการกระทําตนเสมอกับพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 19, 'ดังนั้นพระเยซูตรัสกับเขาว่า “เราบอกความจริงแก่ท่านทั้งหลายว่า พระบุตรจะกระทําสิ่งใดตามใจไม่ได้ นอกจากที่ได้เห็นพระบิดาทรงกระทํา เพราะสิ่งใดที่พระบิดาทรงกระทํา สิ่งนั้นพระบุตรจึงทรงกระทําด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 20, 'เพราะว่าพระบิดาทรงรักพระบุตร และทรงสําแดงให้พระบุตรเห็นทุกสิ่งที่พระองค์ทรงกระทํา และพระองค์จะทรงสําแดงให้พระบุตรเห็นการที่ยิ่งใหญ่กว่านั้นอีก เพื่อท่านทั้งหลายจะประหลาดใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 21, 'เพราะพระบิดาทรงทําให้คนที่ตายแล้วฟื้นขึ้นมาและมีชีวิตฉันใด ถ้าพระบุตรปรารถนาจะกระทําให้ผู้ใดมีชีวิตก็จะกระทําเหมือนกันฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 22, 'เพราะว่าพระบิดามิได้ทรงพิพากษาผู้ใด แต่พระองค์ได้ทรงมอบการพิพากษาทั้งสิ้นไว้กับพระบุตร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 23, 'เพื่อคนทั้งปวงจะได้ถวายเกียรติแด่พระบุตรเหมือนที่เขาถวายเกียรติแด่พระบิดา ผู้ใดไม่ถวายเกียรติแด่พระบุตร ผู้นั้นก็ไม่ถวายเกียรติแด่พระบิดาผู้ทรงใช้พระบุตรมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 24, 'เราบอกความจริงแก่ท่านทั้งหลายว่า ถ้าผู้ใดฟังคําของเราและเชื่อในพระองค์ผู้ทรงใช้เรามา ผู้นั้นก็มีชีวิตนิรันดร์ และไม่ถูกพิพากษา แต่ได้ผ่านพ้นความตายไปสู่ชีวิตแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 25, 'เราบอกความจริงแก่ท่านทั้งหลายว่า เวลาที่กําหนดนั้นใกล้จะถึงแล้ว และบัดนี้ก็ถึงแล้ว คือเมื่อผู้ที่ตายแล้วจะได้ยินพระสุรเสียงแห่งพระบุตรของพระเจ้า และบรรดาผู้ที่ได้ยินจะมีชีวิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 26, 'เพราะว่าพระบิดาทรงมีชีวิตในพระองค์เองฉันใด พระองค์ก็ได้ทรงประทานให้พระบุตรมีชีวิตในพระองค์ฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 27, 'และได้ทรงประทานให้พระบุตรมีสิทธิอํานาจที่จะพิพากษาด้วย เพราะพระองค์ทรงเป็นบุตรมนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 28, 'อย่าประหลาดใจในข้อนี้เลย เพราะใกล้จะถึงเวลาที่บรรดาผู้ที่อยู่ในอุโมงค์ฝังศพจะได้ยินพระสุรเสียงของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 29, 'และจะได้ออกมา คนทั้งหลายที่ได้ประพฤติดีก็ฟื้นขึ้นสู่ชีวิต และคนทั้งหลายที่ได้ประพฤติชั่วก็จะฟื้นขึ้นสู่การพิพากษา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 30, 'เราจะทําสิ่งใดตามอําเภอใจไม่ได้ เราได้ยินอย่างไร เราก็พิพากษาอย่างนั้น และการพิพากษาของเราก็ยุติธรรม เพราะเรามิได้มุ่งที่จะทําตามใจของเราเอง แต่ตามพระประสงค์ของพระบิดาผู้ทรงใช้เรามา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 31, 'ถ้าเราเป็นพยานถึงตัวเราเอง คําพยานของเราก็ไม่จริง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 32, 'มีอีกผู้หนึ่งที่เป็นพยานถึงเรา และเรารู้ว่าคําพยานที่พระองค์ทรงเป็นพยานถึงเรานั้น เป็นความจริง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 33, 'ท่านทั้งหลายได้ใช้คนไปหายอห์น และยอห์นก็ได้เป็นพยานถึงความจริง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 34, 'เรามิได้รับคําพยานจากมนุษย์ แต่ที่เรากล่าวสิ่งเหล่านี้ก็เพื่อให้ท่านทั้งหลายรอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 35, 'ยอห์นเป็นโคมที่จุดสว่างไสว และท่านทั้งหลายก็พอใจที่จะชื่นชมยินดีชั่วขณะหนึ่งในความสว่างของยอห์นนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 36, 'แต่คําพยานที่เรามีนั้นยิ่งใหญ่กว่าคําพยานของยอห์น เพราะว่างานที่พระบิดาทรงมอบให้เราทําให้สําเร็จ งานนี้แหละเรากําลังทําอยู่เป็นพยานถึงเราว่าพระบิดาทรงใช้เรามา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 37, 'และพระบิดาผู้ทรงใช้เรามา พระองค์เองก็ได้ทรงเป็นพยานถึงเรา ท่านทั้งหลายไม่เคยได้ยินพระสุรเสียงของพระองค์ และไม่เคยเห็นรูปร่างของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 38, 'และท่านทั้งหลายไม่มีพระดํารัสของพระองค์อยู่ในตัวท่าน เพราะว่าท่านทั้งหลายมิได้เชื่อในพระองค์ผู้ที่พระบิดาทรงใช้มานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 39, 'จงค้นดูในพระคัมภีร์ เพราะท่านคิดว่าในพระคัมภีร์นั้นมีชีวิตนิรันดร์ และพระคัมภีร์นั้นเป็นพยานถึงเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 40, 'แต่ท่านทั้งหลายไม่ยอมมาหาเราเพื่อจะได้ชีวิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 41, 'เราไม่รับเกียรติจากมนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 42, 'แต่เรารู้ว่าท่านไม่มีความรักพระเจ้าในตัวท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 43, 'เราได้มาในพระนามพระบิดาของเรา และท่านทั้งหลายมิได้รับเรา ถ้าผู้อื่นจะมาในนามของเขาเอง ท่านทั้งหลายก็จะรับผู้นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 44, 'ผู้ที่ได้รับยศศักดิ์จากกันเอง และมิได้แสวงหายศศักดิ์ซึ่งมาจากพระเจ้าเท่านั้น ท่านจะเชื่อผู้นั้นได้อย่างไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 45, 'อย่าคิดว่าเราจะฟ้องท่านทั้งหลายต่อพระบิดา มีผู้ฟ้องท่านแล้ว คือโมเสส ผู้ซึ่งท่านทั้งหลายหวังใจอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 46, 'ถ้าท่านทั้งหลายเชื่อโมเสส ท่านทั้งหลายก็จะเชื่อเรา เพราะโมเสสได้เขียนกล่าวถึงเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 47, 'แต่ถ้าท่านทั้งหลายไม่เชื่อเรื่องที่โมเสสเขียนแล้ว ท่านจะเชื่อถ้อยคําของเราอย่างไรได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 1, 'ภายหลังเหตุการณ์เหล่านี้พระเยซูก็เสด็จไปข้ามทะเลกาลิลี คือทะเลทิเบเรียส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 2, 'คนเป็นอันมากได้ตามพระองค์ไป เพราะเขาเหล่านั้นได้เห็นการอัศจรรย์ที่พระองค์ได้ทรงกระทําต่อบรรดาคนป่วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 3, 'พระเยซูเสด็จขึ้นไปบนภูเขาและประทับกับเหล่าสาวกของพระองค์ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 4, 'ขณะนั้นใกล้จะถึงปัสกาซึ่งเป็นเทศกาลเลี้ยงของพวกยิวแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 5, 'เมื่อพระเยซูทรงเงยพระพักตร์ทอดพระเนตรและเห็นคนเป็นอันมากพากันมาหาพระองค์ พระองค์จึงตรัสกับฟีลิปว่า “เราจะซื้ออาหารที่ไหนให้คนเหล่านี้กินได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 6, 'พระองค์ตรัสอย่างนั้นเพื่อจะลองใจฟีลิป เพราะพระองค์ทรงทราบแล้วว่าพระองค์จะทรงกระทําประการใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 7, 'ฟีลิปทูลตอบพระองค์ว่า “สองร้อยเหรียญเดนาริอันก็ไม่พอซื้ออาหารให้เขากินกันคนละเล็กละน้อย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 8, 'สาวกคนหนึ่งของพระองค์คืออันดรูว์น้องชายของซีโมนเปโตรทูลพระองค์ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 9, '“ที่นี่มีเด็กชายคนหนึ่งมีขนมข้าวบาร์เลย์ห้าก้อนกับปลาเล็กๆสองตัว แต่เท่านั้นจะพออะไรกับคนมากอย่างนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 10, 'พระเยซูตรัสว่า “ให้คนทั้งปวงนั่งลงเถิด” ที่นั่นมีหญ้ามาก คนเหล่านั้นจึงนั่งลง นับแต่ผู้ชายได้ประมาณห้าพันคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 11, 'แล้วพระเยซูก็ทรงหยิบขนมปังนั้น และเมื่อขอบพระคุณแล้ว ก็ทรงแจกแก่พวกสาวก และพวกสาวกแจกแก่บรรดาคนที่นั่งอยู่นั้น และให้ปลาด้วยตามที่เขาปรารถนา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 12, 'เมื่อเขาทั้งหลายกินอิ่มแล้วพระองค์ตรัสกับเหล่าสาวกของพระองค์ว่า “จงเก็บเศษอาหารที่เหลือไว้ เพื่อไม่ให้มีสิ่งใดเสียไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 13, 'เขาจึงเก็บเศษขนมข้าวบาร์เลย์ห้าก้อนซึ่งเหลือจากที่คนทั้งหลายได้กินแล้วนั้น ใส่กระบุงได้สิบสองกระบุงเต็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 14, 'เมื่อคนเหล่านั้นได้เห็นการอัศจรรย์ซึ่งพระเยซูได้ทรงกระทํา เขาก็พูดกันว่า “แท้จริงท่านผู้นี้เป็นศาสดาพยากรณ์นั้นที่ทรงกําหนดให้เข้ามาในโลก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 15, 'เมื่อพระเยซูทรงทราบว่า เขาทั้งหลายจะมาจับพระองค์ไปตั้งให้เป็นกษัตริย์ พระองค์ก็เสด็จไปที่ภูเขาอีกแต่ลําพัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 16, 'พอค่ําลงเหล่าสาวกของพระองค์ก็ได้ลงไปที่ทะเล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 17, 'แล้วลงเรือข้ามฟากไปยังเมืองคาเปอรนาอุม มืดแล้วแต่พระเยซูก็ยังมิได้เสด็จไปถึงเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 18, 'ทะเลก็กําเริบขึ้นเพราะลมพัดกล้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 19, 'เมื่อเขาทั้งหลายตีกรรเชียงไปได้ประมาณห้าหกกิโลเมตร เขาก็เห็นพระเยซูเสด็จดําเนินมาบนทะเลใกล้เรือ เขาต่างก็ตกใจกลัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 20, 'แต่พระองค์ตรัสแก่เขาว่า “นี่เป็นเราเอง อย่ากลัวเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 21, 'ดังนั้นเขาจึงรับพระองค์ขึ้นเรือด้วยความเต็มใจ แล้วทันใดนั้นเรือก็ถึงฝั่งที่เขาจะไปนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 22, 'วันรุ่งขึ้น เมื่อคนที่อยู่ฝั่งข้างโน้นเห็นว่าไม่มีเรืออื่นที่นั่น เว้นแต่ลําที่เหล่าสาวกของพระองค์ลงไปเพียงลําเดียว และเห็นว่าพระเยซูมิได้เสด็จลงเรือลํานั้นไปกับเหล่าสาวก แต่เหล่าสาวกของพระองค์ไปตามลําพังเท่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 23, '(แต่มีเรือลําอื่นมาจากทิเบเรียส ใกล้สถานที่ที่เขาได้กินขนมปัง หลังจากที่องค์พระผู้เป็นเจ้าได้ทรงขอบพระคุณแล้ว)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 24, 'เหตุฉะนั้นเมื่อประชาชนเห็นว่า พระเยซูและเหล่าสาวกไม่ได้อยู่ที่นั่น เขาจึงลงเรือไปและตามหาพระเยซูที่เมืองคาเปอรนาอุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 25, 'ครั้นเขาได้พบพระองค์ที่ฝั่งทะเลข้างโน้นแล้ว เขาทั้งหลายทูลพระองค์ว่า “รับบี ท่านมาที่นี่เมื่อไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 26, 'พระเยซูตรัสตอบเขาว่า “เราบอกความจริงแก่ท่านทั้งหลายว่า ท่านทั้งหลายตามหาเรามิใช่เพราะได้เห็นการอัศจรรย์นั้น แต่เพราะได้กินขนมปังอิ่ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 27, 'อย่าขวนขวายหาอาหารที่ย่อมเสื่อมสูญไป แต่จงหาอาหารที่ดํารงอยู่ถึงชีวิตนิรันดร์ซึ่งบุตรมนุษย์จะให้แก่ท่าน เพราะพระเจ้าคือพระบิดาได้ทรงประทับตรามอบอํานาจแก่พระบุตรแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 28, 'แล้วเขาทั้งหลายก็ทูลพระองค์ว่า “ข้าพเจ้าทั้งหลายจะต้องทําประการใด จึงจะทํางานของพระเจ้าได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 29, 'พระเยซูตรัสตอบเขาว่า “งานของพระเจ้านั้นคือการที่ท่านเชื่อในท่านที่พระองค์ทรงใช้มานั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 30, 'เขาทั้งหลายจึงทูลพระองค์ว่า “ถ้าเช่นนั้น ท่านจะกระทําหมายสําคัญอะไร เพื่อข้าพเจ้าทั้งหลายจะเห็นและเชื่อในท่าน ท่านจะกระทําการอะไรบ้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 31, 'บรรพบุรุษของข้าพเจ้าทั้งหลายได้กินมานาในถิ่นทุรกันดารนั้น ตามที่มีคําเขียนไว้ว่า ‘ท่านได้ให้เขากินอาหารจากสวรรค์’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 32, 'พระเยซูจึงตรัสกับเขาว่า “เราบอกความจริงแก่ท่านทั้งหลายว่า มิใช่โมเสสที่ให้อาหารจากสวรรค์นั้นแก่ท่าน แต่พระบิดาของเราประทานอาหารแท้ซึ่งมาจากสวรรค์ให้แก่ท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 33, 'เพราะว่าอาหารของพระเจ้านั้น คือท่านที่ลงมาจากสวรรค์ และประทานชีวิตให้แก่โลก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 34, 'เขาทั้งหลายจึงทูลพระองค์ว่า “พระองค์เจ้าข้า โปรดให้อาหารนั้นแก่ข้าพเจ้าทั้งหลายเสมอไปเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 35, 'พระเยซูตรัสกับเขาว่า “เราเป็นอาหารแห่งชีวิต ผู้ที่มาหาเราจะไม่หิวอีก และผู้ที่เชื่อในเราจะไม่กระหายอีกเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 36, 'แต่เราได้บอกท่านทั้งหลายแล้วว่า ท่านได้เห็นเราแล้วแต่ก็ไม่เชื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 37, 'สารพัดที่พระบิดาทรงประทานแก่เราจะมาสู่เรา และผู้ที่มาหาเรา เราก็จะไม่ทิ้งเขาเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 38, 'เพราะว่าเราได้ลงมาจากสวรรค์ มิใช่เพื่อกระทําตามความประสงค์ของเราเอง แต่เพื่อกระทําตามพระประสงค์ของพระองค์ผู้ทรงใช้เรามา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 39, 'และพระประสงค์ของพระบิดาผู้ทรงใช้เรามานั้น ก็คือให้เรารักษาบรรดาผู้ที่พระองค์ได้ทรงมอบไว้กับเรา มิให้หายไปสักคนเดียว แต่ให้ฟื้นขึ้นมาในวันที่สุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 40, 'เพราะนี่แหละเป็นพระประสงค์ของผู้ที่ทรงใช้เรามานั้น ที่จะให้ทุกคนที่เห็นพระบุตร และเชื่อในพระบุตรได้มีชีวิตนิรันดร์ และเราจะให้ผู้นั้นฟื้นขึ้นมาในวันสุดท้าย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 41, 'พวกยิวจึงบ่นพึมพํากันเรื่องพระองค์เพราะพระองค์ตรัสว่า “เราเป็นอาหารซึ่งลงมาจากสวรรค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 42, 'เขาทั้งหลายว่า “คนนี้เป็นเยซูลูกชายของโยเซฟมิใช่หรือ พ่อแม่ของเขาเราก็รู้จัก เหตุใดคนนี้จึงพูดว่า ‘เราได้ลงมาจากสวรรค์’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 43, 'พระเยซูจึงตรัสตอบเขาเหล่านั้นว่า “อย่าบ่นกันเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 44, 'ไม่มีผู้ใดมาถึงเราได้นอกจากพระบิดาผู้ทรงใช้เรามาจะทรงชักนําให้เขามา และเราจะให้ผู้นั้นฟื้นขึ้นมาในวันสุดท้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 45, 'มีคําเขียนไว้ในคัมภีร์ศาสดาพยากรณ์ว่า ‘ทุกคนจะเรียนรู้จากพระเจ้า’ เหตุฉะนั้นทุกคนที่ได้ยินได้ฟัง และได้เรียนรู้จากพระบิดาก็มาถึงเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 46, 'ไม่มีผู้ใดได้เห็นพระบิดา นอกจากท่านที่มาจากพระเจ้า ท่านนั้นแหละได้เห็นพระบิดาแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 47, 'เราบอกความจริงแก่ท่านทั้งหลายว่า ผู้ที่เชื่อในเราก็มีชีวิตนิรันดร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 48, 'เราเป็นอาหารแห่งชีวิตนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 49, 'บรรพบุรุษของท่านทั้งหลายได้กินมานาในถิ่นทุรกันดารและสิ้นชีวิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 50, 'แต่นี่เป็นอาหารที่ลงมาจากสวรรค์ เพื่อให้ผู้ที่ได้กินแล้วไม่ตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 51, 'เราเป็นอาหารที่ธํารงชีวิตซึ่งลงมาจากสวรรค์ ถ้าผู้ใดกินอาหารนี้ ผู้นั้นจะมีชีวิตนิรันดร์ และอาหารที่เราจะให้เพื่อเป็นชีวิตของโลกนั้นก็คือเนื้อของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 52, 'แล้วพวกยิวก็ทุ่มเถียงกันว่า “ผู้นี้จะเอาเนื้อของเขาให้เรากินได้อย่างไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 53, 'พระเยซูจึงตรัสกับเขาว่า “เราบอกความจริงแก่ท่านทั้งหลายว่า ถ้าท่านไม่กินเนื้อและดื่มโลหิตของบุตรมนุษย์ ท่านก็ไม่มีชีวิตในตัวท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 54, 'ผู้ที่กินเนื้อและดื่มโลหิตของเราก็มีชีวิตนิรันดร์ และเราจะให้ผู้นั้นฟื้นขึ้นมาในวันสุดท้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 55, 'เพราะว่าเนื้อของเราเป็นอาหารแท้และโลหิตของเราก็เป็นของดื่มแท้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 56, 'ผู้ที่กินเนื้อและดื่มโลหิตของเรา ผู้นั้นก็อยู่ในเราและเราอยู่ในเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 57, 'พระบิดาผู้ทรงดํารงพระชนม์ได้ทรงใช้เรามาและเรามีชีวิตเพราะพระบิดานั้นฉันใด ผู้ที่กินเรา ผู้นั้นก็จะมีชีวิตเพราะเราฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 58, 'นี่แหละเป็นอาหารซึ่งลงมาจากสวรรค์ ไม่เหมือนกับมานาที่พวกบรรพบุรุษของท่านได้กินและสิ้นชีวิต ผู้ที่กินอาหารนี้จะมีชีวิตนิรันดร์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 59, 'คําเหล่านี้พระองค์ได้ตรัสในธรรมศาลา ขณะที่พระองค์ทรงสั่งสอนอยู่ที่เมืองคาเปอรนาอุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 60, 'ดังนั้นเมื่อเหล่าสาวกของพระองค์หลายคนได้ฟังเช่นนั้นก็พูดว่า “ถ้อยคําเหล่านี้ยากนัก ใครจะฟังได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 61, 'เมื่อพระเยซูทรงทราบเองว่าเหล่าสาวกของพระองค์บ่นถึงเรื่องนั้น พระองค์จึงตรัสกับเขาว่า “เรื่องนี้ทําให้ท่านทั้งหลายลําบากใจหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 62, 'ถ้าท่านจะได้เห็นบุตรมนุษย์เสด็จขึ้นไปยังที่ที่ท่านอยู่แต่ก่อนนั้น ท่านจะว่าอย่างไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 63, 'จิตวิญญาณเป็นที่ให้มีชีวิต ส่วนเนื้อหนังไม่มีประโยชน์อันใด ถ้อยคําซึ่งเราได้กล่าวกับท่านทั้งหลายนั้น เป็นจิตวิญญาณและเป็นชีวิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 64, 'แต่ในพวกท่านมีบางคนที่ไม่เชื่อ” เพราะพระเยซูทรงทราบแต่แรกว่าผู้ใดไม่เชื่อ และเป็นผู้ใดที่จะทรยศพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 65, 'และพระองค์ตรัสว่า “เหตุฉะนั้นเราจึงได้บอกท่านทั้งหลายว่า ‘ไม่มีผู้ใดจะมาถึงเราได้ นอกจากพระบิดาของเราจะทรงโปรดประทานให้ผู้นั้น’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 66, 'ตั้งแต่นั้นมาสาวกของพระองค์หลายคนก็ท้อถอยไม่ติดตามพระองค์อีกต่อไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 67, 'พระเยซูตรัสกับสิบสองคนนั้นว่า “ท่านทั้งหลายก็จะจากเราไปด้วยหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 68, 'ซีโมนเปโตรทูลตอบพระองค์ว่า “พระองค์เจ้าข้า พวกข้าพระองค์จะจากไปหาผู้ใดเล่า พระองค์มีถ้อยคําซึ่งให้มีชีวิตนิรันดร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 69, 'และข้าพระองค์ทั้งหลายก็เชื่อและแน่ใจแล้วว่า พระองค์ทรงเป็นพระคริสต์พระบุตรของพระเจ้าผู้ทรงดํารงพระชนม์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 70, 'พระเยซูตรัสตอบเขาว่า “เราเลือกพวกท่านสิบสองคนมิใช่หรือ และคนหนึ่งในพวกท่านเป็นมารร้าย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 71, 'พระองค์ทรงหมายถึงยูดาสอิสคาริโอทบุตรชายซีโมน เพราะว่าเขาเป็นผู้ที่จะทรยศพระองค์ คือคนหนึ่งในอัครสาวกสิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 1, 'ภายหลังเหตุการณ์เหล่านี้พระเยซูก็ได้เสด็จไปในแคว้นกาลิลี ด้วยว่าพระองค์ไม่ประสงค์ที่จะเสด็จไปในแคว้นยูเดีย เพราะพวกยิวหาโอกาสที่จะฆ่าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 2, 'ขณะนั้นใกล้จะถึงเทศกาลอยู่เพิงของพวกยิวแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 3, 'พวกน้องๆของพระองค์จึงทูลพระองค์ว่า “จงออกจากที่นี่ไปยังแคว้นยูเดีย เพื่อเหล่าสาวกของท่านจะได้เห็นกิจการที่ท่านกระทํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 4, 'เพราะว่าไม่มีผู้ใดทําสิ่งใดลับๆ เมื่อผู้นั้นเองอยากให้ตัวปรากฏ ถ้าท่านกระทําการเหล่านี้ก็จงสําแดงตัวให้ปรากฏแก่โลกเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 5, 'แม้พวกน้องๆของพระองค์ก็มิได้เชื่อในพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 6, 'พระเยซูตรัสกับพวกเขาว่า “ยังไม่ถึงเวลาของเรา แต่เวลาของพวกท่านมีอยู่เสมอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 7, 'โลกจะเกลียดชังพวกท่านไม่ได้ แต่โลกเกลียดชังเรา เพราะเราเป็นพยานว่าการงานของโลกนั้นชั่ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 8, 'พวกท่านจงขึ้นไปในเทศกาลนั้นเถิด เราจะยังไม่ขึ้นไปในเทศกาลนั้น เพราะว่ายังไม่ถึงกําหนดเวลาของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 9, 'เมื่อพระองค์ตรัสเช่นนั้นแก่เขาแล้ว พระองค์ก็ยังประทับอยู่ในแคว้นกาลิลี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 10, 'แต่เมื่อพวกน้องๆของพระองค์ขึ้นไปในเทศกาลนั้นแล้ว พระองค์ก็เสด็จตามขึ้นไปด้วย แต่ไปอย่างลับๆ ไม่เปิดเผย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 11, 'พวกยิวจึงมองหาพระองค์ในเทศกาลนั้นและถามว่า “คนนั้นอยู่ที่ไหน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 12, 'และประชาชนก็ซุบซิบกันถึงพระองค์เป็นอันมาก บางคนว่า “เขาเป็นคนดี” คนอื่นๆว่า “มิใช่ แต่เขาหลอกลวงประชาชนต่างหาก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 13, 'แต่ไม่มีผู้ใดอาจพูดถึงพระองค์อย่างเปิดเผย เพราะกลัวพวกยิว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 14, 'ครั้นถึงวันกลางเทศกาลนั้น พระเยซูได้เสด็จขึ้นไปในพระวิหารและทรงสั่งสอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 15, 'พวกยิวคิดประหลาดใจและพูดว่า “คนนี้จะรู้ข้อความเหล่านี้ได้อย่างไร ในเมื่อไม่เคยเรียนเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 16, 'พระเยซูจึงตรัสตอบเขาว่า “คําสอนของเราไม่ใช่ของเราเอง แต่เป็นของพระองค์ผู้ทรงใช้เรามา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 17, 'ถ้าผู้ใดตั้งใจประพฤติตามพระประสงค์ของพระองค์ ผู้นั้นก็จะรู้ว่าคําสอนนั้นมาจากพระเจ้า หรือว่าเราพูดตามใจชอบของเราเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 18, 'ผู้ใดที่พูดตามใจชอบของตนเอง ผู้นั้นย่อมแสวงหาเกียรติสําหรับตนเอง แต่ผู้ที่แสวงหาเกียรติให้พระองค์ผู้ทรงใช้ตนมา ผู้นั้นแหละเป็นคนจริง ไม่มีอธรรมอยู่ในเขาเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 19, 'โมเสสได้ให้พระราชบัญญัติแก่ท่านทั้งหลายมิใช่หรือ และไม่มีผู้ใดในพวกท่านรักษาพระราชบัญญัตินั้น ท่านทั้งหลายหาโอกาสที่จะฆ่าเราทําไม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 20, 'คนเหล่านั้นตอบว่า “ท่านมีผีสิงอยู่ ใครเล่าหาโอกาสจะฆ่าท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 21, 'พระเยซูตรัสตอบเขาว่า “เราได้ทําสิ่งหนึ่งและท่านทั้งหลายประหลาดใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 22, 'โมเสสได้ให้ท่านทั้งหลายเข้าสุหนัต (มิใช่ได้มาจากโมเสส แต่มาจากบรรพบุรุษ) และในวันสะบาโตท่านทั้งหลายก็ยังให้คนเข้าสุหนัต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 23, 'ถ้าในวันสะบาโตคนยังเข้าสุหนัต เพื่อมิให้ละเมิดพระราชบัญญัติของโมเสสแล้ว ท่านทั้งหลายจะโกรธเรา เพราะเราทําให้ชายผู้หนึ่งหายโรคเป็นปกติในวันสะบาโตหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 24, 'อย่าตัดสินตามที่เห็นภายนอก แต่จงตัดสินตามชอบธรรมเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 25, 'เพราะฉะนั้นชาวกรุงเยรูซาเล็มบางคนจึงพูดว่า “คนนี้มิใช่หรือที่เขาหาโอกาสจะฆ่าเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 26, 'แต่ดูเถิด ท่านกําลังพูดอย่างกล้าหาญและเขาทั้งหลายก็ไม่ได้ว่าอะไรท่านเลย พวกขุนนางรู้แน่แล้วหรือว่า คนนี้เป็นพระคริสต์แท้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 27, 'แต่เรารู้ว่าคนนี้มาจากไหน แต่เมื่อพระคริสต์เสด็จมานั้น จะไม่มีผู้ใดรู้เลยว่า พระองค์มาจากไหน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 28, 'ดังนั้นพระเยซูจึงทรงประกาศขณะที่ทรงสั่งสอนอยู่ในพระวิหารว่า “ท่านทั้งหลายรู้จักเรา และรู้ว่าเรามาจากไหน แต่เรามิได้มาตามลําพังเราเอง แต่พระองค์ผู้ทรงใช้เรามานั้นทรงสัตย์จริง แต่ท่านทั้งหลายไม่รู้จักพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 29, 'แต่เรารู้จักพระองค์เพราะเรามาจากพระองค์และพระองค์ได้ทรงใช้เรามา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 30, 'เขาทั้งหลายจึงหาโอกาสที่จะจับพระองค์ แต่ไม่มีผู้ใดยื่นมือแตะต้องพระองค์ เพราะยังไม่ถึงกําหนดเวลาของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 31, 'และมีหลายคนในหมู่ประชาชนนั้นได้เชื่อในพระองค์และพูดว่า “เมื่อพระคริสต์เสด็จมานั้น พระองค์จะทรงกระทําอัศจรรย์มากยิ่งกว่าที่ผู้นี้ได้กระทําหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 32, 'เมื่อพวกฟาริสีได้ยินประชาชนซุบซิบกันเรื่องพระองค์อย่างนั้น พวกฟาริสีกับพวกปุโรหิตใหญ่จึงได้ใช้เจ้าหน้าที่ไปจับพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 33, 'พระเยซูจึงตรัสกับเขาทั้งหลายว่า “เราจะอยู่กับท่านทั้งหลายอีกหน่อยหนึ่ง แล้วจะกลับไปหาพระองค์ผู้ทรงใช้เรามา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 34, 'ท่านทั้งหลายจะแสวงหาเราแต่จะไม่พบเรา และที่ซึ่งเราอยู่นั้นท่านจะไปไม่ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 35, 'พวกยิวจึงพูดกันว่า “คนนี้จะไปไหน ที่เราจะหาเขาไม่พบ เขาจะไปหาคนที่กระจัดกระจายไปอยู่ในหมู่พวกต่างชาติและสั่งสอนพวกต่างชาติหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 36, 'เขาหมายความว่าอย่างไรที่พูดว่า ‘ท่านทั้งหลายจะแสวงหาเราแต่จะไม่พบเรา’ และ ‘ที่ซึ่งเราอยู่นั้นท่านจะไปไม่ได้’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 37, 'ในวันสุดท้ายของเทศกาลซึ่งเป็นวันใหญ่นั้น พระเยซูทรงยืนและประกาศว่า “ถ้าผู้ใดกระหาย ผู้นั้นจงมาหาเราและดื่ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 38, 'ผู้ที่เชื่อในเรา ตามที่พระคัมภีร์ได้กล่าวไว้แล้วว่า ‘แม่น้ําที่มีน้ําประกอบด้วยชีวิตจะไหลออกมาจากภายในผู้นั้น’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 39, '(สิ่งที่พระองค์ตรัสนั้นหมายถึงพระวิญญาณซึ่งผู้ที่เชื่อในพระองค์จะได้รับ เหตุว่ายังไม่ได้ประทานพระวิญญาณบริสุทธิ์ให้ เพราะพระเยซูยังมิได้รับสง่าราศี)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 40, 'เมื่อประชาชนได้ฟังดังนั้น หลายคนจึงพูดว่า “แท้จริง ท่านผู้นี้เป็นศาสดาพยากรณ์นั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 41, 'คนอื่นๆก็พูดว่า “ท่านผู้นี้เป็นพระคริสต์” แต่บางคนพูดว่า “พระคริสต์จะมาจากกาลิลีหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 42, 'พระคัมภีร์กล่าวไว้มิใช่หรือว่า พระคริสต์จะมาจากเชื้อสายของดาวิด และมาจากเมืองเบธเลเฮมซึ่งดาวิดเคยอยู่นั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 43, 'เหตุฉะนั้นประชาชนจึงมีความเห็นแตกแยกกันในเรื่องพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 44, 'บางคนใคร่จะจับพระองค์ แต่ไม่มีผู้ใดยื่นมือแตะต้องพระองค์เลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 45, 'เจ้าหน้าที่จึงกลับไปหาพวกปุโรหิตใหญ่และพวกฟาริสี และพวกนั้นกล่าวกับเจ้าหน้าที่ว่า “ทําไมเจ้าจึงไม่จับเขามา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 46, 'เจ้าหน้าที่ตอบว่า “ไม่เคยมีผู้ใดพูดเหมือนคนนั้นเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 47, 'พวกฟาริสีตอบเขาว่า “พวกเจ้าถูกหลอกไปด้วยแล้วหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 48, 'มีผู้ใดในพวกขุนนางหรือพวกฟาริสีเชื่อในผู้นั้นหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 49, 'แต่ประชาชนหมู่นี้ที่ไม่รู้พระราชบัญญัติก็ต้องถูกสาปแช่งอยู่แล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 50, 'นิโคเดมัส (ผู้ที่ได้มาหาพระเยซูในเวลากลางคืนนั้น และเป็นคนหนึ่งในพวกเขา) ได้กล่าวแก่พวกเขาว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 51, '“พระราชบัญญัติของเราตัดสินคนใดโดยที่ยังไม่ได้ฟังเขาก่อน และรู้ว่าเขาได้ทําอะไรบ้างหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 52, 'เขาทั้งหลายตอบนิโคเดมัสว่า “ท่านมาจากกาลิลีด้วยหรือ จงค้นหาดูเถิด เพราะว่าไม่มีศาสดาพยากรณ์เกิดขึ้นมาจากกาลิลี”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 53, 'ต่างคนต่างกลับไปบ้านของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 1, 'แต่พระเยซูเสด็จไปยังภูเขามะกอกเทศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 2, 'ในตอนเช้าตรู่พระองค์เสด็จเข้าในพระวิหารอีก และคนทั้งหลายพากันมาหาพระองค์ พระองค์ก็ประทับนั่งและสั่งสอนเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 3, 'พวกธรรมาจารย์และพวกฟาริสีได้พาผู้หญิงคนหนึ่งมาหาพระองค์ หญิงผู้นี้ถูกจับฐานล่วงประเวณี และเมื่อเขาให้หญิงผู้นี้ยืนอยู่ท่ามกลางฝูงชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 4, 'เขาทูลพระองค์ว่า “พระอาจารย์เจ้าข้า หญิงคนนี้ถูกจับเมื่อกําลังล่วงประเวณีอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 5, 'ในพระราชบัญญัตินั้นโมเสสสั่งให้เราเอาหินขว้างคนเช่นนี้ให้ตาย ส่วนท่านจะว่าอย่างไรในเรื่องนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 6, 'เขาพูดอย่างนี้เพื่อทดลองพระองค์ หวังจะหาเหตุฟ้องพระองค์ แต่พระเยซูทรงน้อมพระกายลงเอานิ้วพระหัตถ์เขียนที่ดิน เหมือนดั่งว่าพระองค์ไม่ได้ยินพวกเขาเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 7, 'และเมื่อพวกเขายังทูลถามพระองค์อยู่เรื่อยๆ พระองค์ก็ทรงลุกขึ้นและตรัสกับเขาว่า “ผู้ใดในพวกท่านที่ไม่มีบาป ก็ให้ผู้นั้นเอาหินขว้างเขาก่อน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 8, 'แล้วพระองค์ก็ทรงน้อมพระกายลงและเขียนที่ดินอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 9, 'และเมื่อเขาทั้งหลายได้ยินดังนั้น จึงรู้สํานึกโดยใจวินิจฉัยผิดชอบของตนเอง เขาทั้งหลายจึงออกไปทีละคนๆ เริ่มจากคนเฒ่าคนแก่จนหมด เหลือแต่พระเยซูตามลําพังกับหญิงที่ยังยืนอยู่ที่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 10, 'เมื่อพระเยซูทรงลุกขึ้นแล้ว และมิได้ทอดพระเนตรเห็นผู้ใด เห็นแต่หญิงผู้นั้น พระองค์ตรัสกับนางว่า “หญิงเอ๋ย พวกเขาที่ฟ้องเจ้าไปไหนหมด ไม่มีใครเอาโทษเจ้าหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 11, 'นางนั้นทูลว่า “พระองค์เจ้าข้า ไม่มีผู้ใดเลย” และพระเยซูตรัสกับนางว่า “เราก็ไม่เอาโทษเจ้าเหมือนกัน จงไปเถิด และอย่าทําบาปอีก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 12, 'อีกครั้งหนึ่งพระเยซูตรัสกับเขาทั้งหลายว่า “เราเป็นความสว่างของโลก ผู้ที่ตามเรามาจะไม่เดินในความมืด แต่จะมีความสว่างแห่งชีวิต”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 13, 'พวกฟาริสีจึงกล่าวกับพระองค์ว่า “ท่านเป็นพยานให้แก่ตัวเอง คําพยานของท่านไม่เป็นความจริง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 14, 'พระเยซูตรัสตอบเขาว่า “แม้เราเป็นพยานให้แก่ตัวเราเอง คําพยานของเราก็เป็นความจริง เพราะเรารู้ว่าเรามาจากไหนและจะไปที่ไหน แต่พวกท่านไม่รู้ว่าเรามาจากไหนและจะไปที่ไหน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 15, 'ท่านทั้งหลายย่อมพิพากษาตามเนื้อหนัง เรามิได้พิพากษาผู้ใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 16, 'แต่ถึงแม้ว่าเราจะพิพากษา การพิพากษาของเราก็ถูกต้อง เพราะเรามิได้พิพากษาโดยลําพัง แต่เราพิพากษาร่วมกับพระบิดาผู้ทรงใช้เรามา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 17, 'ในพระราชบัญญัติของท่านก็มีคําเขียนไว้ว่า ‘คําพยานของสองคนก็เป็นความจริง’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 18, 'เราเป็นพยานให้แก่ตัวเราเองและพระบิดาผู้ทรงใช้เรามาก็เป็นพยานให้แก่เรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 19, 'เหตุฉะนั้นเขาจึงทูลพระองค์ว่า “พระบิดาของท่านอยู่ที่ไหน” พระเยซูตรัสตอบว่า “ตัวเราก็ดี พระบิดาของเราก็ดี ท่านทั้งหลายไม่รู้จัก ถ้าท่านรู้จักเรา ท่านก็จะรู้จักพระบิดาของเราด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 20, 'พระเยซูตรัสคําเหล่านี้ที่คลังเงิน เมื่อกําลังทรงสั่งสอนอยู่ในพระวิหาร แต่ไม่มีผู้ใดจับกุมพระองค์ เพราะว่ายังไม่ถึงกําหนดเวลาของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 21, 'พระเยซูจึงตรัสกับเขาอีกว่า “เราจะจากไป และท่านทั้งหลายจะแสวงหาเรา และจะตายในการบาปของท่าน ที่ซึ่งเราจะไปนั้นท่านทั้งหลายจะไปไม่ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 22, 'พวกยิวจึงพูดกันว่า “เขาจะฆ่าตัวตายหรือ เพราะเขาพูดว่า ‘ที่ซึ่งเราจะไปนั้นท่านทั้งหลายจะไปไม่ได้’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 23, 'พระองค์ตรัสกับเขาว่า “ท่านทั้งหลายมาจากเบื้องล่าง เรามาจากเบื้องบน ท่านเป็นของโลกนี้ เราไม่ได้เป็นของโลกนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 24, 'เราจึงบอกท่านทั้งหลายว่า ท่านจะตายในการบาปของท่าน เพราะว่าถ้าท่านมิได้เชื่อว่าเราเป็นผู้นั้น ท่านจะต้องตายในการบาปของตัว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 25, 'เขาจึงถามพระองค์ว่า “ท่านคือใครเล่า” พระเยซูตรัสกับเขาว่า “เราเป็นดังที่เราได้บอกท่านทั้งหลายแต่แรกนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 26, 'เราก็ยังมีเรื่องอีกมากที่จะพูดและพิพากษาท่าน แต่พระองค์ผู้ทรงใช้เรามานั้นทรงเป็นสัตย์จริง และสิ่งที่เราได้ยินจากพระองค์ เรากล่าวแก่โลก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 27, 'เขาทั้งหลายไม่เข้าใจว่าพระองค์ตรัสกับเขาถึงเรื่องพระบิดา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 28, 'พระเยซูจึงตรัสกับเขาว่า “เมื่อท่านทั้งหลายจะได้ยกบุตรมนุษย์ขึ้นไว้แล้ว เมื่อนั้นท่านก็จะรู้ว่าเราคือผู้นั้น และรู้ว่าเรามิได้ทําสิ่งใดตามใจชอบ แต่พระบิดาของเราได้ทรงสอนเราอย่างไร เราจึงกล่าวอย่างนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 29, 'และพระองค์ผู้ทรงใช้เรามาก็ทรงสถิตอยู่กับเรา พระบิดามิได้ทรงทิ้งเราไว้ตามลําพัง เพราะว่าเราทําตามชอบพระทัยพระองค์เสมอ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 30, 'เมื่อพระองค์ตรัสดังนี้ก็มีคนเป็นอันมากเชื่อในพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 31, 'พระเยซูจึงตรัสกับพวกยิวที่เชื่อในพระองค์แล้วว่า “ถ้าท่านทั้งหลายดํารงอยู่ในคําของเรา ท่านก็เป็นสาวกของเราอย่างแท้จริง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 32, 'และท่านทั้งหลายจะรู้จักความจริง และความจริงนั้นจะทําให้ท่านทั้งหลายเป็นไทย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 33, 'เขาทั้งหลายทูลตอบพระองค์ว่า “เราสืบเชื้อสายมาจากอับราฮัมและไม่เคยเป็นทาสใครเลย เหตุไฉนท่านจึงกล่าวว่า ‘ท่านทั้งหลายจะเป็นไทย’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 34, 'พระเยซูตรัสตอบเขาทั้งหลายว่า “เราบอกความจริงแก่ท่านว่า ผู้ใดที่ทําบาปก็เป็นทาสของบาป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 35, 'ทาสนั้นมิได้อยู่ในครัวเรือนตลอดไป พระบุตรต่างหากอยู่ตลอดไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 36, 'เหตุฉะนั้นถ้าพระบุตรจะทรงกระทําให้ท่านทั้งหลายเป็นไทย ท่านก็จะเป็นไทยจริงๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 37, 'เรารู้ว่าท่านทั้งหลายเป็นเชื้อสายของอับราฮัม แต่ท่านก็หาโอกาสที่จะฆ่าเราเสีย เพราะคําของเราไม่มีโอกาสเข้าสู่ใจของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 38, 'เราพูดสิ่งที่เราได้เห็นจากพระบิดาของเรา และท่านทําสิ่งที่ท่านได้เห็นจากพ่อของท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 39, 'เขาทั้งหลายจึงทูลตอบพระองค์ว่า “อับราฮัมเป็นบิดาของเรา” พระเยซูตรัสกับเขาทั้งหลายว่า “ถ้าท่านทั้งหลายเป็นบุตรของอับราฮัมแล้ว ท่านก็จะทําสิ่งที่อับราฮัมได้กระทํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 40, 'แต่บัดนี้ท่านทั้งหลายหาโอกาสที่จะฆ่าเรา ซึ่งเป็นผู้ที่ได้บอกท่านถึงความจริงที่เราได้ยินมาจากพระเจ้า อับราฮัมมิได้กระทําอย่างนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 41, 'ท่านทั้งหลายย่อมทําสิ่งที่พ่อของท่านทํา” เขาจึงทูลพระองค์ว่า “เรามิได้เกิดจากการล่วงประเวณี เรามีพระบิดาองค์เดียวคือพระเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 42, 'พระเยซูตรัสกับเขาว่า “ถ้าพระเจ้าเป็นพระบิดาของท่านแล้ว ท่านก็จะรักเรา เพราะเรามาจากพระเจ้าและอยู่นี่แล้ว เรามิได้มาตามใจชอบของเราเอง แต่พระองค์นั้นทรงใช้เรามา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 43, 'เหตุไฉนท่านจึงไม่เข้าใจถ้อยคําที่เราพูด นั่นเป็นเพราะท่านทนฟังคําของเราไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 44, 'ท่านทั้งหลายมาจากพ่อของท่านคือพญามาร และท่านใคร่จะทําตามความปรารถนาของพ่อท่าน มันเป็นฆาตกรตั้งแต่เดิมมา และมิได้ตั้งอยู่ในความจริง เพราะความจริงมิได้อยู่ในมัน เมื่อมันพูดมุสามันก็พูดตามสันดานของมันเอง เพราะมันเป็นผู้มุสา และเป็นพ่อของการมุสา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 45, 'แต่ท่านทั้งหลายมิได้เชื่อเรา เพราะเราพูดความจริง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 46, 'มีผู้ใดในพวกท่านหรือที่ชี้ให้เห็นว่าเราได้ทําบาป และถ้าเราพูดความจริง ทําไมท่านจึงไม่เชื่อเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 47, 'ผู้ที่มาจากพระเจ้าก็ย่อมฟังพระวจนะของพระเจ้า เหตุฉะนั้นท่านจึงไม่ฟัง เพราะท่านทั้งหลายมิได้มาจากพระเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 48, 'พวกยิวจึงทูลตอบพระองค์ว่า “ที่เราพูดว่า ท่านเป็นชาวสะมาเรียและมีผีสิงนั้น ไม่จริงหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 49, 'พระเยซูตรัสตอบว่า “เราไม่มีผีสิง แต่ว่าเราถวายพระเกียรติแด่พระบิดาของเรา และท่านลบหลู่เกียรติเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 50, 'เรามิได้แสวงหาเกียรติของเราเอง แต่มีผู้หาให้ และพระองค์นั้นจะทรงพิพากษา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 51, 'เราบอกความจริงแก่ท่านว่า ถ้าผู้ใดรักษาคําของเรา ผู้นั้นจะไม่ประสบความตายเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 52, 'พวกยิวจึงทูลพระองค์ว่า “เดี๋ยวนี้เรารู้แล้วว่าท่านมีผีสิง อับราฮัมและพวกศาสดาพยากรณ์ก็ตายแล้ว และท่านพูดว่า ‘ถ้าผู้ใดรักษาคําของเรา ผู้นั้นจะไม่ชิมความตายเลย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 53, 'ท่านเป็นใหญ่กว่าอับราฮัมบิดาของเราที่ตายไปแล้วหรือ พวกศาสดาพยากรณ์นั้นก็ตายไปแล้วด้วย ท่านอวดอ้างว่าท่านเป็นผู้ใดเล่า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 54, 'พระเยซูตรัสตอบว่า “ถ้าเราให้เกียรติแก่ตัวเราเอง เกียรติของเราก็ไม่มีความหมาย พระองค์ผู้ทรงให้เกียรติแก่เรานั้นคือพระบิดาของเรา ผู้ซึ่งพวกท่านกล่าวว่าเป็นพระเจ้าของพวกท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 55, 'ท่านไม่รู้จักพระองค์ แต่เรารู้จักพระองค์ และถ้าเรากล่าวว่าเราไม่รู้จักพระองค์ เราก็เป็นคนมุสาเหมือนกับท่าน แต่เรารู้จักพระองค์ และรักษาพระดํารัสของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 56, 'อับราฮัมบิดาของท่านชื่นชมยินดีที่จะได้เห็นวันของเรา และท่านก็ได้เห็นแล้วและมีความยินดี”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 57, 'พวกยิวก็ทูลพระองค์ว่า “ท่านอายุยังไม่ถึงห้าสิบปี และท่านเคยเห็นอับราฮัมหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 58, 'พระเยซูตรัสกับเขาว่า “เราบอกความจริงแก่ท่านว่า ก่อนอับราฮัมบังเกิดมานั้นเราเป็น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 59, 'คนเหล่านั้นจึงหยิบก้อนหินจะขว้างพระองค์ แต่พระเยซูทรงหลบและเสด็จออกไปจากพระวิหาร และเสด็จผ่านท่ามกลางเขาเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 1, 'เมื่อพระเยซูเสด็จดําเนินไปนั้น พระองค์ทอดพระเนตรเห็นชายคนหนึ่งตาบอดแต่กําเนิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 2, 'และพวกสาวกของพระองค์ทูลถามพระองค์ว่า “พระอาจารย์เจ้าข้า ใครได้ทําผิดบาป ชายคนนี้หรือบิดามารดาของเขา เขาจึงเกิดมาตาบอด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 3, 'พระเยซูตรัสตอบว่า “มิใช่ชายคนนี้หรือบิดามารดาของเขาได้ทําบาป แต่เพื่อให้พระราชกิจของพระเจ้าปรากฏในตัวเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 4, 'เราต้องกระทําพระราชกิจของพระองค์ผู้ทรงใช้เรามาเมื่อยังวันอยู่ เมื่อถึงกลางคืนไม่มีผู้ใดทํางานได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 5, 'ตราบใดที่เรายังอยู่ในโลก เราเป็นความสว่างของโลก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 6, 'เมื่อตรัสดังนั้นแล้ว พระองค์ก็ทรงบ้วนน้ําลายลงที่ดิน แล้วทรงเอาน้ําลายนั้นทําเป็นโคลนทาที่ตาของคนตาบอดนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 7, 'แล้วตรัสสั่งเขาว่า “จงไปล้างออกเสียในสระสิโลอัมเถิด” (สิโลอัมแปลว่า ใช้ไป) เขาจึงไปล้างแล้วกลับเห็นได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 8, 'เพื่อนบ้านและคนทั้งหลายที่เคยเห็นชายคนนั้นเป็นคนตาบอดมาก่อน จึงพูดกันว่า “คนนี้มิใช่หรือที่เคยนั่งขอทาน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 9, 'บางคนก็พูดว่า “คนนั้นแหละ” คนอื่นว่า “เขาคล้ายคนนั้น” แต่เขาเองพูดว่า “ข้าพเจ้าคือคนนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 10, 'เขาทั้งหลายจึงถามเขาว่า “ตาของเจ้าหายบอดได้อย่างไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 11, 'เขาตอบว่า “ชายคนหนึ่งชื่อเยซู ได้ทําโคลนทาตาของข้าพเจ้า และบอกข้าพเจ้าว่า ‘จงไปที่สระสิโลอัมแล้วล้างออกเสีย’ ข้าพเจ้าก็ได้ไปล้างตาจึงมองเห็นได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 12, 'เขาทั้งหลายจึงถามเขาว่า “ผู้นั้นอยู่ที่ไหน” คนนั้นบอกว่า “ข้าพเจ้าไม่ทราบ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 13, 'เขาจึงพาคนที่แต่ก่อนตาบอดนั้นไปหาพวกฟาริสี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 14, 'วันที่พระเยซูทรงทําโคลนทาตาชายคนนั้นให้หายบอดเป็นวันสะบาโต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 15, 'พวกฟาริสีก็ได้ถามเขาอีกว่า ทําอย่างไรตาเขาจึงมองเห็น เขาบอกคนเหล่านั้นว่า “เขาเอาโคลนทาตาของข้าพเจ้า และข้าพเจ้าก็ล้างออกแล้วจึงมองเห็น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 16, 'ฉะนั้นพวกฟาริสีบางคนพูดว่า “ชายคนนี้ไม่ได้มาจากพระเจ้าเพราะเขามิได้รักษาวันสะบาโต” คนอื่นว่า “คนบาปจะทําการอัศจรรย์เช่นนั้นได้อย่างไร” พวกเขาก็แตกแยกกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 17, 'เขาจึงพูดกับคนตาบอดอีกว่า “เจ้าคิดอย่างไรเรื่องคนนั้น ในเมื่อเขาได้ทําให้ตาของเจ้าหายบอด” ชายคนนั้นตอบว่า “ท่านเป็นศาสดาพยากรณ์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 18, 'แต่พวกยิวไม่เชื่อเรื่องเกี่ยวกับชายคนนั้นว่า เขาตาบอดและกลับมองเห็น จนกระทั่งเขาได้เรียกบิดามารดาของคนที่ตากลับมองเห็นได้นั้นมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 19, 'แล้วพวกเขาถามเขาทั้งสองว่า “ชายคนนี้เป็นบุตรชายของเจ้าหรือที่เจ้าบอกว่าตาบอดมาแต่กําเนิด ทําไมเดี๋ยวนี้เขาจึงมองเห็น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 20, 'บิดามารดาของชายคนนั้นตอบเขาว่า “เราทราบว่าคนนี้เป็นบุตรชายของเรา และทราบว่าเขาเกิดมาตาบอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 21, 'แต่ไม่รู้ว่าทําไมเดี๋ยวนี้เขาจึงมองเห็น หรือใครทําให้ตาของเขาหายบอด เราก็ไม่ทราบ จงถามเขาเถิด เขาโตแล้ว เขาจะเล่าเรื่องของเขาเองได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 22, 'ที่บิดามารดาของเขาพูดอย่างนั้นก็เพราะกลัวพวกยิว เพราะพวกยิวตกลงกันแล้วว่า ถ้าผู้ใดยอมรับว่าผู้นั้นเป็นพระคริสต์ จะต้องไล่ผู้นั้นเสียจากธรรมศาลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 23, 'เหตุฉะนั้นบิดามารดาของเขาจึงพูดว่า “จงถามเขาเถิด เขาโตแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 24, 'คนเหล่านั้นจึงเรียกคนที่แต่ก่อนตาบอดนั้นมาอีกและบอกเขาว่า “จงสรรเสริญพระเจ้าเถิด เรารู้อยู่ว่าชายคนนั้นเป็นคนบาป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 25, 'เขาตอบว่า “ท่านนั้นเป็นคนบาปหรือไม่ข้าพเจ้าไม่ทราบ สิ่งเดียวที่ข้าพเจ้าทราบก็คือว่า ข้าพเจ้าเคยตาบอด แต่เดี๋ยวนี้ข้าพเจ้ามองเห็นได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 26, 'คนเหล่านั้นจึงถามเขาอีกว่า “เขาทําอะไรกับเจ้าบ้าง เขาทําอย่างไรตาของเจ้าจึงหายบอด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 27, 'ชายคนนั้นตอบเขาว่า “ข้าพเจ้าบอกท่านแล้ว และท่านไม่ฟัง ทําไมท่านจึงอยากฟังอีก ท่านอยากเป็นสาวกของท่านผู้นั้นด้วยหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 28, 'เขาทั้งหลายจึงเย้ยชายคนนั้นว่า “แกเป็นศิษย์ของเขา แต่เราเป็นศิษย์ของโมเสส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 29, 'เรารู้ว่าพระเจ้าได้ตรัสกับโมเสส แต่คนนั้นเราไม่รู้ว่าเขามาจากไหน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 30, 'ชายคนนั้นตอบเขาว่า “เออ ช่างประหลาดจริงๆที่พวกท่านไม่รู้ว่าท่านผู้นั้นมาจากไหน แต่ท่านผู้นั้นยังได้ทําให้ตาของข้าพเจ้าหายบอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 31, 'พวกเรารู้ว่าพระเจ้ามิได้ฟังคนบาป แต่ถ้าผู้ใดนมัสการพระเจ้า และกระทําตามพระทัยพระองค์ พระองค์ก็ทรงฟังผู้นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 32, 'ตั้งแต่เริ่มมีโลกมาแล้ว ไม่เคยมีใครได้ยินว่า มีผู้ใดทําให้ตาของคนที่บอดแต่กําเนิดมองเห็นได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 33, 'ถ้าท่านผู้นั้นไม่ได้มาจากพระเจ้าแล้ว ก็จะทําอะไรไม่ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 34, 'เขาทั้งหลายตอบคนนั้นว่า “แกเกิดมาในการบาปทั้งนั้น และแกจะมาสอนเราหรือ” แล้วเขาจึงไล่คนนั้นเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 35, 'พระเยซูทรงได้ยินว่าเขาได้ไล่คนนั้นเสียแล้ว และเมื่อพระองค์ทรงพบชายคนนั้นจึงตรัสกับเขาว่า “เจ้าเชื่อในพระบุตรของพระเจ้าหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 36, 'ชายคนนั้นทูลตอบว่า “ท่านเจ้าข้า ผู้ใดเป็นพระบุตรนั้น ซึ่งข้าพเจ้าจะเชื่อในพระองค์ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 37, 'พระเยซูตรัสกับเขาว่า “เจ้าได้เห็นท่านแล้ว ทั้งเป็นผู้นั้นเองที่กําลังพูดอยู่กับเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 38, 'เขาจึงทูลว่า “พระองค์เจ้าข้า ข้าพระองค์เชื่อ” แล้วเขาก็นมัสการพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 39, 'พระเยซูตรัสว่า “เราเข้ามาในโลกเพื่อการพิพากษา เพื่อให้คนทั้งหลายที่มองไม่เห็นกลับมองเห็น และคนที่มองเห็นกลับตาบอด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 40, 'เมื่อพวกฟาริสีบางคนที่อยู่กับพระองค์ได้ยินอย่างนั้น จึงกล่าวแก่พระองค์ว่า “เราตาบอดด้วยหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 41, 'พระเยซูตรัสกับเขาว่า “ถ้าพวกท่านตาบอด พวกท่านก็จะไม่มีความผิดบาป แต่บัดนี้ท่านพูดว่า ‘เรามองเห็น’ เหตุฉะนั้นความผิดบาปของท่านจึงยังมีอยู่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 1, '“เราบอกความจริงแก่ท่านว่า ผู้ที่มิได้เข้าไปในคอกแกะทางประตู แต่ปีนเข้าไปทางอื่นนั้นเป็นขโมยและโจร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 2, 'แต่ผู้ที่เข้าทางประตูก็เป็นผู้เลี้ยงแกะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 3, 'นายประตูจึงเปิดประตูให้ผู้นั้น และแกะย่อมฟังเสียงของท่าน ท่านเรียกชื่อแกะของท่าน และนําออกไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 4, 'เมื่อท่านต้อนแกะของท่านออกไปแล้วก็เดินนําหน้า และแกะก็ตามท่านไปเพราะรู้จักเสียงของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 5, 'คนแปลกหน้าแกะจะไม่ตามเลย แต่จะหนีไปจากเขา เพราะไม่รู้จักเสียงของคนแปลกหน้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 6, 'คําอุปมานั้นพระเยซูได้ตรัสกับเขาทั้งหลาย แต่เขาไม่เข้าใจความหมายของพระดํารัสที่พระองค์ตรัสกับเขาเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 7, 'พระเยซูจึงตรัสกับเขาอีกว่า “เราบอกความจริงแก่ท่านว่า เราเป็นประตูของแกะทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 8, 'บรรดาผู้ที่มาก่อนเรานั้นเป็นขโมยและโจร แต่ฝูงแกะก็มิได้ฟังเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 9, 'เราเป็นประตู ถ้าผู้ใดเข้าไปทางเรา ผู้นั้นจะรอด และเขาจะเข้าออก แล้วจะพบอาหาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 10, 'ขโมยนั้นย่อมมาเพื่อจะลักและฆ่าและทําลายเสีย เราได้มาเพื่อเขาทั้งหลายจะได้ชีวิต และจะได้อย่างครบบริบูรณ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 11, 'เราเป็นผู้เลี้ยงที่ดี ผู้เลี้ยงที่ดีนั้นย่อมสละชีวิตของตนเพื่อฝูงแกะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 12, 'แต่ผู้ที่รับจ้างมิได้เป็นผู้เลี้ยงแกะ และฝูงแกะไม่เป็นของเขา เมื่อเห็นสุนัขป่ามา เขาจึงละทิ้งฝูงแกะหนีไป สุนัขป่าก็ชิงเอาแกะไปเสีย และทําให้ฝูงแกะกระจัดกระจายไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 13, 'ผู้ที่รับจ้างนั้นหนีเพราะเขาเป็นลูกจ้างและไม่เป็นห่วงแกะเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 14, 'เราเป็นผู้เลี้ยงที่ดี และเรารู้จักแกะของเรา และแกะของเราก็รู้จักเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 15, 'เหมือนพระบิดาทรงรู้จักเรา เราก็รู้จักพระบิดาด้วย และชีวิตของเรา เราสละเพื่อฝูงแกะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 16, 'แกะอื่นซึ่งมิได้เป็นของคอกนี้เราก็มีอยู่ แกะเหล่านั้นเราก็ต้องพามาด้วย และแกะเหล่านั้นจะฟังเสียงของเรา แล้วจะรวมเป็นฝูงเดียว และมีผู้เลี้ยงเพียงผู้เดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 17, 'ด้วยเหตุนี้พระบิดาของเราจึงทรงรักเรา เพราะเราสละชีวิตของเรา เพื่อจะรับชีวิตนั้นคืนมาอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 18, 'ไม่มีผู้ใดชิงชีวิตไปจากเราได้ แต่เราสละชีวิตด้วยใจสมัครของเราเอง เรามีสิทธิที่จะสละชีวิตนั้น และมีสิทธิที่จะรับคืนอีก พระบัญชานี้เราได้รับมาจากพระบิดาของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 19, 'พระดํารัสนี้จึงทําให้พวกยิวแตกแยกกันอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 20, 'พวกเขาหลายคนพูดว่า “เขามีผีสิงและเป็นบ้า ท่านฟังเขาทําไม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 21, 'พวกอื่นก็พูดว่า “คําอย่างนี้ไม่เป็นคําของผู้ที่มีผีสิง ผีจะทําให้คนตาบอดมองเห็นได้หรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 22, 'ขณะนั้นเป็นเทศกาลเลี้ยงฉลองพระวิหารที่กรุงเยรูซาเล็ม และเป็นฤดูหนาว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 23, 'พระเยซูทรงดําเนินอยู่ในพระวิหารที่เฉลียงของซาโลมอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 24, 'แล้วพวกยิวก็พากันมาห้อมล้อมพระองค์ไว้และทูลพระองค์ว่า “จะทําให้เราสงสัยนานสักเท่าใด ถ้าท่านเป็นพระคริสต์ก็จงบอกเราให้ชัดแจ้งเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 25, 'พระเยซูตรัสตอบเขาทั้งหลายว่า “เราได้บอกท่านทั้งหลายแล้ว และท่านไม่เชื่อ การซึ่งเราได้กระทําในพระนามพระบิดาของเราก็เป็นพยานให้แก่เรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 26, 'แต่ท่านทั้งหลายไม่เชื่อ เพราะท่านมิได้เป็นแกะของเรา ตามที่เราได้บอกท่านแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 27, 'แกะของเราย่อมฟังเสียงของเรา และเรารู้จักแกะเหล่านั้น และแกะนั้นตามเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 28, 'เราให้ชีวิตนิรันดร์แก่แกะนั้น และแกะนั้นจะไม่พินาศเลย และจะไม่มีผู้ใดแย่งชิงแกะเหล่านั้นไปจากมือของเราได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 29, 'พระบิดาของเราผู้ประทานแกะนั้นให้แก่เราเป็นใหญ่กว่าทุกสิ่ง และไม่มีผู้ใดสามารถชิงแกะนั้นไปจากพระหัตถ์ของพระบิดาของเราได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 30, 'เรากับพระบิดาของเราเป็นอันหนึ่งอันเดียวกัน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 31, 'พวกยิวจึงหยิบก้อนหินขึ้นมาอีกจะขว้างพระองค์ให้ตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 32, 'พระเยซูจึงตรัสกับเขาว่า “เราได้สําแดงให้ท่านเห็นการดีหลายประการซึ่งมาจากพระบิดาของเรา ท่านทั้งหลายหยิบก้อนหินจะขว้างเราให้ตายเพราะการกระทําข้อใดเล่า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 33, 'พวกยิวทูลตอบพระองค์ว่า “เราจะขว้างท่านมิใช่เพราะการกระทําดี แต่เพราะการพูดหมิ่นประมาท เพราะท่านเป็นเพียงมนุษย์แต่ตั้งตัวเป็นพระเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 34, 'พระเยซูตรัสตอบเขาว่า “ในพระราชบัญญัติของท่านมีคําเขียนไว้มิใช่หรือว่า ‘เราได้กล่าวว่า ท่านทั้งหลายเป็นพระ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 35, 'ถ้าพระองค์ได้ทรงเรียกผู้ที่รับพระวจนะของพระเจ้าว่าเป็นพระ และจะฝ่าฝืนพระคัมภีร์ไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 36, 'ท่านทั้งหลายจะกล่าวหาท่านที่พระบิดาได้ทรงตั้งไว้ และทรงใช้เข้ามาในโลกว่า ‘ท่านกล่าวคําหมิ่นประมาท’ เพราะเราได้กล่าวว่า ‘เราเป็นบุตรของพระเจ้า’ อย่างนั้นหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 37, 'ถ้าเราไม่ปฏิบัติพระราชกิจของพระบิดาของเรา ก็อย่าเชื่อในเราเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 38, 'แต่ถ้าเราปฏิบัติพระราชกิจนั้น แม้ว่าท่านมิได้เชื่อในเรา ก็จงเชื่อเพราะพระราชกิจนั้นเถิด เพื่อท่านจะได้รู้และเชื่อว่าพระบิดาทรงอยู่ในเรา และเราอยู่ในพระบิดา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 39, 'พวกเขาจึงหาโอกาสจับพระองค์อีกครั้งหนึ่ง แต่พระองค์ทรงรอดพ้นจากมือเขาไปได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 40, 'พระองค์เสด็จไปฟากแม่น้ําจอร์แดนข้างโน้นอีก และไปถึงสถานที่ที่ยอห์นให้บัพติศมาเป็นครั้งแรก และพระองค์ทรงพักอยู่ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 41, 'คนเป็นอันมากพากันมาหาพระองค์ และกล่าวว่า “ยอห์นมิได้ทําการอัศจรรย์ใดๆเลย แต่ทุกสิ่งซึ่งยอห์นได้กล่าวถึงท่านผู้นี้เป็นความจริง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 42, 'และมีคนหลายคนที่นั่นได้เชื่อในพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 1, 'มีชายคนหนึ่งชื่อลาซารัสกําลังป่วยอยู่ที่หมู่บ้านเบธานี ซึ่งเป็นเมืองที่มารีย์และมารธาพี่สาวของเธออยู่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 2, '(มารีย์ผู้นี้คือหญิงที่เอาน้ํามันหอมชโลมองค์พระผู้เป็นเจ้า และเอาผมของเธอเช็ดพระบาทของพระองค์ ลาซารัสน้องชายของเธอกําลังป่วยอยู่)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 3, 'ดังนั้นพี่สาวทั้งสองนั้นจึงให้คนไปเฝ้าพระองค์ทูลว่า “พระองค์เจ้าข้า ดูเถิด ผู้ที่พระองค์ทรงรักนั้นกําลังป่วยอยู่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 4, 'เมื่อพระเยซูทรงได้ยินแล้วก็ตรัสว่า “โรคนั้นจะไม่ถึงตาย แต่เกิดขึ้นเพื่อเชิดชูพระเกียรติของพระเจ้า เพื่อพระบุตรของพระเจ้าจะได้รับเกียรติเพราะโรคนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 5, 'พระเยซูทรงรักมารธาและน้องสาวของเธอและลาซารัส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 6, 'ดังนั้นครั้นพระองค์ทรงได้ยินว่าลาซารัสป่วยอยู่ พระองค์ยังทรงพักอยู่ที่ที่พระองค์ทรงอยู่นั้นอีกสองวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 7, 'หลังจากนั้นพระองค์ก็ตรัสกับพวกสาวกว่า “ให้เราเข้าไปในแคว้นยูเดียกันอีกเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 8, 'พวกสาวกทูลพระองค์ว่า “พระอาจารย์เจ้าข้า เมื่อเร็วๆนี้พวกยิวหาโอกาสเอาหินขว้างพระองค์ให้ตาย แล้วพระองค์ยังจะเสด็จไปที่นั่นอีกหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 9, 'พระเยซูตรัสตอบว่า “วันหนึ่งมีสิบสองชั่วโมงมิใช่หรือ ถ้าผู้ใดเดินในตอนกลางวันเขาก็จะไม่สะดุด เพราะเขาเห็นความสว่างของโลกนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 10, 'แต่ถ้าผู้ใดเดินในตอนกลางคืนเขาก็จะสะดุด เพราะไม่มีความสว่างในตัวเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 11, 'พระองค์ตรัสดังนั้นแล้วจึงตรัสกับเขาว่า “ลาซารัสสหายของเราหลับไปแล้ว แต่เราไปเพื่อจะปลุกเขาให้ตื่น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 12, 'พวกสาวกของพระองค์ทูลว่า “พระองค์เจ้าข้า ถ้าเขาหลับอยู่เขาก็จะสบายดี”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 13, 'แต่พระเยซูตรัสถึงความตายของลาซารัส แต่พวกสาวกคิดว่าพระองค์ตรัสถึงการนอนหลับพักผ่อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 14, 'ฉะนั้นพระเยซูจึงตรัสกับเขาตรงๆว่า “ลาซารัสตายแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 15, 'เพื่อเห็นแก่ท่านทั้งหลายเราจึงยินดีที่เรามิได้อยู่ที่นั่น เพื่อท่านจะได้เชื่อ แต่ให้เราไปหาเขากันเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 16, 'โธมัสที่เรียกว่า ดิดุมัส จึงพูดกับเพื่อนสาวกว่า “ให้พวกเราไปด้วยเถิด เพื่อจะได้ตายด้วยกันกับพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 17, 'ครั้นพระเยซูเสด็จมาถึงก็ทรงทราบว่า เขาเอาลาซารัสไปไว้ในอุโมงค์ฝังศพสี่วันแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 18, 'หมู่บ้านเบธานีอยู่ใกล้กรุงเยรูซาเล็ม ห่างกันประมาณสามกิโลเมตร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 19, 'พวกยิวหลายคนได้มาหามารธาและมารีย์ เพื่อจะปลอบโยนเธอเรื่องน้องชายของเธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 20, 'ครั้นมารธารู้ข่าวว่าพระเยซูกําลังเสด็จมา เธอก็ออกไปต้อนรับพระองค์ แต่มารีย์นั่งอยู่ในเรือน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 21, 'มารธาจึงทูลพระเยซูว่า “พระองค์เจ้าข้า ถ้าพระองค์อยู่ที่นี่ น้องชายของข้าพระองค์คงไม่ตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 22, 'แต่ถึงแม้เดี๋ยวนี้ข้าพระองค์ก็ทราบว่า สิ่งใดๆที่พระองค์จะทูลขอจากพระเจ้า พระเจ้าจะทรงโปรดประทานแก่พระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 23, 'พระเยซูตรัสกับเธอว่า “น้องชายของเจ้าจะฟื้นขึ้นมาอีก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 24, 'มารธาทูลพระองค์ว่า “ข้าพระองค์ทราบแล้วว่า เขาจะฟื้นขึ้นมาอีกในวันสุดท้ายเมื่อคนทั้งปวงจะฟื้นขึ้นมา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 25, 'พระเยซูตรัสกับเธอว่า “เราเป็นเหตุให้คนทั้งปวงเป็นขึ้นและมีชีวิต ผู้ที่เชื่อในเรานั้น ถึงแม้ว่าเขาตายแล้วก็ยังจะมีชีวิตอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 26, 'และผู้ใดที่มีชีวิตและเชื่อในเราจะไม่ตายเลย เจ้าเชื่ออย่างนี้ไหม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 27, 'มารธาทูลพระองค์ว่า “เชื่อ พระองค์เจ้าข้า ข้าพระองค์เชื่อว่า พระองค์ทรงเป็นพระคริสต์ พระบุตรของพระเจ้า ที่จะเสด็จมาในโลก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 28, 'เมื่อเธอทูลดังนี้แล้ว เธอก็กลับไปและเรียกมารีย์น้องสาวกระซิบว่า “พระอาจารย์เสด็จมาแล้ว และทรงเรียกเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 29, 'เมื่อมารีย์ได้ยินแล้ว เธอก็รีบลุกขึ้นไปเฝ้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 30, 'ฝ่ายพระเยซูยังไม่เสด็จเข้าไปในเมือง แต่ยังประทับอยู่ ณ ที่ซึ่งมารธาพบพระองค์นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 31, 'พวกยิวที่อยู่กับมารีย์ในเรือนและกําลังปลอบโยนเธออยู่ เมื่อเห็นมารีย์รีบลุกขึ้นและเดินออกไปจึงตามเธอไปพูดกันว่า “เธอจะไปร้องไห้ที่อุโมงค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 32, 'ครั้นมารีย์มาถึงที่ซึ่งพระเยซูประทับอยู่และเห็นพระองค์แล้ว จึงกราบลงที่พระบาทของพระองค์ทูลว่า “พระองค์เจ้าข้า ถ้าพระองค์ประทับอยู่ที่นี่ น้องชายของข้าพระองค์คงไม่ตาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 33, 'ฉะนั้นเมื่อพระเยซูทอดพระเนตรเห็นเธอร้องไห้ และพวกยิวที่มากับเธอร้องไห้ด้วย พระองค์ก็ทรงคร่ําครวญร้อนพระทัยและทรงเป็นทุกข์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 34, 'และตรัสถามว่า “พวกเจ้าเอาศพเขาไปไว้ที่ไหน” เขาทูลพระองค์ว่า “พระองค์เจ้าข้า เชิญเสด็จมาดูเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 35, 'พระเยซูทรงพระกันแสง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 36, 'พวกยิวจึงกล่าวว่า “ดูเถิด พระองค์ทรงรักเขาเพียงไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 37, 'และบางคนก็พูดว่า “ท่านผู้นี้ทําให้คนตาบอดมองเห็น จะทําให้คนนี้ไม่ตายไม่ได้หรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 38, 'พระเยซูทรงคร่ําครวญร้อนพระทัยอีก จึงเสด็จมาถึงอุโมงค์ฝังศพ อุโมงค์ฝังศพนั้นเป็นถ้ํา มีศิลาวางปิดปากไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 39, 'พระเยซูตรัสว่า “จงเอาศิลาออกเสีย” มารธาพี่สาวของผู้ตายจึงทูลพระองค์ว่า “พระองค์เจ้าข้า ป่านนี้ศพมีกลิ่นเหม็นแล้ว เพราะว่าเขาตายมาสี่วันแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 40, 'พระเยซูตรัสกับเธอว่า “เราบอกเจ้าแล้วมิใช่หรือว่า ถ้าเจ้าเชื่อ เจ้าก็จะได้เห็นสง่าราศีของพระเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 41, 'พวกเขาจึงเอาศิลาออกเสียจากที่ซึ่งผู้ตายวางอยู่นั้น พระเยซูทรงแหงนพระพักตร์ขึ้นตรัสว่า “ข้าแต่พระบิดา ข้าพระองค์ขอบพระคุณพระองค์ที่พระองค์ทรงโปรดฟังข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 42, 'ข้าพระองค์ทราบว่า พระองค์ทรงฟังข้าพระองค์อยู่เสมอ แต่ที่ข้าพระองค์กล่าวอย่างนี้ก็เพราะเห็นแก่ประชาชนที่ยืนอยู่ที่นี่ เพื่อเขาจะได้เชื่อว่าพระองค์ทรงใช้ข้าพระองค์มา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 43, 'เมื่อพระองค์ตรัสดังนั้นแล้ว จึงเปล่งพระสุรเสียงตรัสว่า “ลาซารัสเอ๋ย จงออกมาเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 44, 'ผู้ตายนั้นก็ออกมา มีผ้าพันศพพันมือและเท้า และที่หน้าก็มีผ้าพันอยู่ด้วย พระเยซูตรัสกับเขาทั้งหลายว่า “จงแก้แล้วปล่อยเขาไปเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 45, 'ดังนั้นพวกยิวหลายคนที่มาหามารีย์และได้เห็นการกระทําของพระเยซู ก็เชื่อในพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 46, 'แต่พวกเขาบางคนไปหาพวกฟาริสี และเล่าเหตุการณ์ที่พระเยซูได้ทรงกระทําให้ฟัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 47, 'ฉะนั้นพวกปุโรหิตใหญ่และพวกฟาริสีก็เรียกประชุมสมาชิกสภาแล้วว่า “เราจะทําอย่างไรกัน เพราะว่าชายผู้นี้ทําการอัศจรรย์หลายประการ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 48, 'ถ้าเราปล่อยเขาไว้อย่างนี้ คนทั้งปวงจะเชื่อถือเขา แล้วพวกโรมก็จะมาริบเอาทั้งที่และชนชาติของเราไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 49, 'แต่คนหนึ่งในพวกเขา ชื่อคายาฟาสเป็นมหาปุโรหิตประจําการในปีนั้น กล่าวแก่เขาทั้งหลายว่า “ท่านทั้งหลายไม่รู้อะไรเสียเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 50, 'และไม่พิจารณาด้วยว่า จะเป็นประโยชน์แก่เราทั้งหลาย ถ้าจะให้คนตายเสียคนหนึ่งเพื่อประชาชน แทนที่จะให้คนทั้งชาติต้องพินาศ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 51, 'เขามิได้กล่าวอย่างนั้นตามใจชอบ แต่เพราะว่าเขาเป็นมหาปุโรหิตประจําการในปีนั้น จึงพยากรณ์ว่าพระเยซูจะสิ้นพระชนม์แทนชนชาตินั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 52, 'และมิใช่แทนชนชาตินั้นอย่างเดียว แต่เพื่อจะรวบรวมบุตรทั้งหลายของพระเจ้าที่กระจัดกระจายไปนั้น ให้เข้าเป็นพวกเดียวกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 53, 'ตั้งแต่วันนั้นเป็นต้นมา เขาทั้งหลายจึงปรึกษากันจะฆ่าพระองค์เสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 54, 'เหตุฉะนั้นพระเยซูจึงไม่เสด็จในหมู่พวกยิวอย่างเปิดเผยอีก แต่ได้เสด็จออกจากที่นั่นไปยังถิ่นที่อยู่ใกล้ถิ่นทุรกันดาร ถึงเมืองหนึ่งชื่อเอฟราอิม และทรงพักอยู่ที่นั่นกับพวกสาวกของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 55, 'ขณะนั้นใกล้จะถึงเทศกาลปัสกาของพวกยิวแล้ว และคนเป็นอันมากได้ออกจากหัวเมืองนั้นขึ้นไปยังกรุงเยรูซาเล็มก่อนเทศกาลปัสกาเพื่อจะชําระตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 56, 'เขาทั้งหลายจึงแสวงหาพระเยซู และเมื่อเขาทั้งหลายยืนอยู่ในพระวิหารเขาก็พูดกันว่า “ท่านทั้งหลายคิดเห็นอย่างไร พระองค์จะไม่เสด็จมาในงานเทศกาลนี้หรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 57, 'ฝ่ายพวกปุโรหิตใหญ่และพวกฟาริสีได้ออกคําสั่งไว้ว่า ถ้าผู้ใดรู้ว่าพระองค์อยู่ที่ไหน ก็ให้มาบอกพวกเขาเพื่อจะได้ไปจับพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 1, 'แล้วก่อนปัสกาหกวันพระเยซูเสด็จมาถึงหมู่บ้านเบธานี ซึ่งเป็นที่อยู่ของลาซารัสที่เคยตาย ผู้ซึ่งพระองค์ได้ทรงให้ฟื้นขึ้นจากตายแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 2, 'ที่นั่นเขาจัดงานเลี้ยงอาหารเย็นแก่พระองค์ มารธาก็ปรนนิบัติอยู่ และลาซารัสก็เป็นคนหนึ่งในพวกเขาที่เอนกายลงรับประทานกับพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 3, 'มารีย์จึงเอาน้ํามันหอมนาระดาบริสุทธิ์หนักประมาณครึ่งกิโลกรัม ซึ่งมีราคาแพงมากมาชโลมพระบาทของพระเยซู และเอาผมของเธอเช็ดพระบาทของพระองค์ เรือนก็หอมฟุ้งไปด้วยกลิ่นน้ํามันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 4, 'แต่สาวกคนหนึ่งของพระองค์ ชื่อยูดาสอิสคาริโอท บุตรชายของซีโมน คือคนที่จะทรยศพระองค์ พูดว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 5, '“เหตุไฉนจึงไม่ขายน้ํามันนั้นเป็นเงินสักสามร้อยเดนาริอัน แล้วแจกให้แก่คนจน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 6, 'เขาพูดอย่างนั้นมิใช่เพราะเขาเอาใจใส่คนจน แต่เพราะเขาเป็นขโมย และได้ถือย่าม และได้ยักยอกเงินที่ใส่ไว้ในย่ามนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 7, 'พระเยซูจึงตรัสว่า “ช่างเขาเถิด เขาทําอย่างนี้เพื่อแสดงถึงวันฝังศพของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 8, 'เพราะว่ามีคนจนอยู่กับท่านเสมอ แต่เราจะไม่อยู่กับท่านเสมอไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 9, 'ฝ่ายพวกยิวเป็นอันมากรู้ว่าพระองค์ประทับอยู่ที่นั่นจึงมาเฝ้าพระองค์ ไม่ใช่เพราะเห็นแก่พระเยซูเท่านั้น แต่อยากเห็นลาซารัสผู้ซึ่งพระองค์ได้ทรงให้ฟื้นขึ้นมาจากตายด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 10, 'แต่พวกปุโรหิตใหญ่จึงปรึกษากันจะฆ่าลาซารัสเสียด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 11, 'เพราะลาซารัสเป็นต้นเหตุที่ทําให้พวกยิวหลายคนออกจากพวกเขา และไปเชื่อพระเยซู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 12, 'วันรุ่งขึ้นเมื่อคนเป็นอันมากที่มาในเทศกาลเลี้ยงนั้นได้ยินว่า พระเยซูเสด็จมาถึงกรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 13, 'เขาก็พากันถือใบของต้นอินทผลัมออกไปต้อนรับพระองค์ร้องว่า “โฮซันนา ขอให้พระองค์ผู้เสด็จมาในพระนามขององค์พระผู้เป็นเจ้า คือพระมหากษัตริย์แห่งอิสราเอลทรงพระเจริญ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 14, 'และเมื่อพระเยซูทรงพบลูกลาตัวหนึ่งจึงทรงลานั้นเหมือนดังที่มีคําเขียนไว้ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 15, '‘ธิดาแห่งศิโยนเอ๋ย อย่ากลัวเลย ดูเถิด กษัตริย์ของเธอทรงลูกลาเสด็จมา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 16, 'ทีแรกพวกสาวกของพระองค์ไม่เข้าใจในเหตุการณ์เหล่านั้น แต่เมื่อพระเยซูทรงรับสง่าราศีแล้ว เขาจึงระลึกได้ว่า มีคําเช่นนั้นเขียนไว้กล่าวถึงพระองค์ และคนทั้งหลายได้กระทําอย่างนั้นถวายพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 17, 'เหตุฉะนั้นคนทั้งปวงซึ่งได้อยู่กับพระองค์ เมื่อพระองค์ได้ทรงเรียกลาซารัสให้ออกมาจากอุโมงค์ฝังศพ และทรงให้เขาฟื้นขึ้นมาจากความตาย ก็เป็นพยานในสิ่งเหล่านี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 18, 'เหตุที่ประชาชนพากันไปหาพระองค์ ก็เพราะเขาได้ยินว่าพระองค์ทรงกระทําการอัศจรรย์นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 19, 'พวกฟาริสีจึงพูดกันว่า “ท่านเห็นไหมว่า ท่านทําอะไรไม่ได้เลย ดูเถิด โลกตามเขาไปหมดแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 20, 'ในหมู่คนทั้งหลายที่ขึ้นไปนมัสการในเทศกาลเลี้ยงนั้นมีพวกกรีกบ้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 21, 'พวกกรีกนั้นจึงไปหาฟีลิปซึ่งมาจากหมู่บ้านเบธไซดาในแคว้นกาลิลี และพูดกับท่านว่า “ท่านเจ้าข้า พวกข้าพเจ้าใคร่จะเห็นพระเยซู”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 22, 'ฟีลิปจึงไปบอกอันดรูว์ และอันดรูว์กับฟีลิปจึงไปทูลพระเยซู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 23, 'และพระเยซูตรัสตอบเขาว่า “ถึงเวลาแล้วที่บุตรมนุษย์จะได้รับสง่าราศี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 24, 'เราบอกความจริงแก่ท่านว่า ถ้าเมล็ดข้าวไม่ได้ตกลงไปในดินและเปื่อยเน่าไป ก็จะอยู่เป็นเมล็ดเดียว แต่ถ้าเปื่อยเน่าไปแล้ว ก็จะงอกขึ้นเกิดผลมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 25, 'ผู้ใดที่รักชีวิตของตนก็ต้องเสียชีวิต และผู้ที่ชังชีวิตของตนในโลกนี้ ก็จะรักษาชีวิตนั้นไว้นิรันดร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 26, 'ถ้าผู้ใดจะปรนนิบัติเรา ให้ผู้นั้นตามเรามา และเราอยู่ที่ไหน ผู้ปรนนิบัติเราจะอยู่ที่นั่นด้วย ถ้าผู้ใดปรนนิบัติเรา พระบิดาของเราก็จะทรงประทานเกียรติแก่ผู้นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 27, 'บัดนี้จิตใจของเราเป็นทุกข์และเราจะพูดว่าอะไร จะว่า ‘ข้าแต่พระบิดา ขอทรงโปรดช่วยข้าพระองค์ให้พ้นเวลานี้’ อย่างนั้นหรือ หามิได้ เพราะด้วยความประสงค์นี้เองเราจึงมาถึงเวลานี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 28, 'ข้าแต่พระบิดา ขอให้พระนามของพระองค์ได้รับเกียรติ” แล้วก็มีพระสุรเสียงมาจากฟ้าว่า “เราได้ให้รับเกียรติแล้ว และจะให้รับเกียรติอีก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 29, 'ฉะนั้นคนทั้งหลายที่ยืนอยู่ที่นั่นเมื่อได้ยินเสียงนั้นก็พูดว่าฟ้าร้อง คนอื่นๆก็พูดว่า “ทูตสวรรค์องค์หนึ่งได้กล่าวกับพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 30, 'พระเยซูตรัสตอบว่า “เสียงนั้นเกิดขึ้นเพื่อท่านทั้งหลาย ไม่ใช่เพื่อเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 31, 'บัดนี้ถึงเวลาที่จะพิพากษาโลกนี้แล้ว เดี๋ยวนี้ผู้ครองโลกนี้จะถูกโยนทิ้งออกไปเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 32, 'และเรา ถ้าเราถูกยกขึ้นจากแผ่นดินโลกแล้ว เราก็จะชักชวนคนทั้งปวงให้มาหาเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 33, 'พระองค์ตรัสเช่นนั้นเพื่อสําแดงว่าพระองค์จะสิ้นพระชนม์อย่างไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 34, 'คนทั้งหลายจึงทูลพระองค์ว่า “พวกเราได้ยินจากพระราชบัญญัติว่า พระคริสต์จะอยู่เป็นนิตย์ เหตุไฉนท่านจึงว่า ‘บุตรมนุษย์จะต้องถูกยกขึ้น’ บุตรมนุษย์นั้นคือผู้ใดเล่า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 35, 'พระเยซูจึงตรัสกับเขาว่า “ความสว่างจะอยู่กับท่านทั้งหลายอีกหน่อยหนึ่ง เมื่อยังมีความสว่างอยู่ก็จงเดินไปเถิด เกรงว่าความมืดจะตามมาทันท่าน ผู้ที่เดินอยู่ในความมืด ย่อมไม่รู้ว่าตนไปทางไหน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 36, 'เมื่อท่านทั้งหลายมีความสว่าง ก็จงเชื่อในความสว่างนั้น เพื่อจะได้เป็นลูกแห่งความสว่าง” เมื่อพระเยซูตรัสดังนั้นแล้วก็เสด็จจากไป และซ่อนพระองค์ให้พ้นจากพวกเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 37, 'ถึงแม้ว่าพระองค์ได้ทรงกระทําการอัศจรรย์หลายประการทีเดียวต่อหน้าเขา เขาทั้งหลายก็ยังไม่เชื่อในพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 38, 'เพื่อคําของอิสยาห์ศาสดาพยากรณ์จะสําเร็จซึ่งว่า ‘พระองค์เจ้าข้า ใครเล่าได้เชื่อสิ่งที่เขาได้ยินจากเราทั้งหลาย และพระกรขององค์พระผู้เป็นเจ้าได้ทรงสําแดงแก่ผู้ใด’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 39, 'ฉะนั้นพวกเขาจึงเชื่อไม่ได้ เพราะอิสยาห์ได้กล่าวอีกว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 40, '‘พระองค์ได้ทรงปิดตาของเขาทั้งหลาย และทําใจของเขาให้แข็งกระด้างไป เกรงว่าเขาจะเห็นด้วยตาของเขา และเข้าใจด้วยจิตใจของเขา และหันกลับมาและเราจะรักษาเขาให้หาย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 41, 'อิสยาห์กล่าวดังนี้เมื่อท่านได้เห็นสง่าราศีของพระองค์ และได้กล่าวถึงพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 42, 'อย่างไรก็ดีแม้ในพวกขุนนางก็มีหลายคนเชื่อในพระองค์ด้วย แต่เขาไม่ยอมรับพระองค์อย่างเปิดเผยเพราะกลัวพวกฟาริสี เกรงว่าเขาจะถูกไล่ออกจากธรรมศาลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 43, 'เพราะว่าเขารักการสรรเสริญของมนุษย์มากกว่าการสรรเสริญของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 44, 'พระเยซูทรงประกาศว่า “ผู้ที่เชื่อในเรานั้น หาได้เชื่อในเราไม่ แต่เชื่อในพระองค์ผู้ทรงใช้เรามา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 45, 'และผู้ที่เห็นเราก็เห็นพระองค์ผู้ทรงใช้เรามา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 46, 'เราเข้ามาในโลกเป็นความสว่าง เพื่อผู้ใดที่เชื่อในเราจะมิได้อยู่ในความมืด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 47, 'ถ้าผู้ใดได้ยินถ้อยคําของเราและไม่เชื่อ เราก็ไม่พิพากษาผู้นั้น เพราะว่าเรามิได้มาเพื่อจะพิพากษาโลก แต่มาเพื่อจะช่วยโลกให้รอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 48, 'ผู้ใดที่ปฏิเสธเราและไม่รับคําของเรา ผู้นั้นจะมีสิ่งหนึ่งพิพากษาเขา คือคําที่เราได้กล่าวแล้ว นั้นแหละจะพิพากษาเขาในวันสุดท้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 49, 'เพราะเรามิได้กล่าวตามใจเราเอง แต่ซึ่งเรากล่าวและพูดนั้น พระบิดาผู้ทรงใช้เรามา พระองค์นั้นได้ทรงบัญชาให้แก่เรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 50, 'เรารู้ว่าพระบัญชาของพระองค์นั้นเป็นชีวิตนิรันดร์ เหตุฉะนั้นสิ่งที่เราพูดนั้น เราก็พูดตามที่พระบิดาทรงบัญชาเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 1, 'ก่อนถึงเทศกาลเลี้ยงปัสกา เมื่อพระเยซูทรงทราบว่า ถึงเวลาแล้วที่พระองค์จะทรงจากโลกนี้ไปหาพระบิดา พระองค์ทรงรักพวกของพระองค์ซึ่งอยู่ในโลกนี้ พระองค์ทรงรักเขาจนถึงที่สุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 2, 'ขณะเมื่อรับประทานอาหารเย็นเสร็จแล้ว พญามารได้ดลใจยูดาสอิสคาริโอท บุตรชายของซีโมน ให้ทรยศพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 3, 'พระเยซูทรงทราบว่าพระบิดาได้ประทานสิ่งทั้งปวงให้อยู่ในพระหัตถ์ของพระองค์ และทรงทราบว่าพระองค์มาจากพระเจ้า และจะไปหาพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 4, 'พระองค์ทรงลุกขึ้นจากการรับประทานอาหารเย็น ทรงถอดฉลองพระองค์ออกวางไว้ และทรงเอาผ้าเช็ดตัวคาดเอวพระองค์ไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 5, 'แล้วก็ทรงเทน้ําลงในอ่าง และทรงตั้งต้นเอาน้ําล้างเท้าของพวกสาวก และเช็ดด้วยผ้าที่ทรงคาดเอวไว้นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 6, 'แล้วพระองค์ทรงมาถึงซีโมนเปโตร และเปโตรทูลพระองค์ว่า “พระองค์เจ้าข้า พระองค์จะทรงล้างเท้าของข้าพระองค์หรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 7, 'พระเยซูตรัสตอบเขาว่า “สิ่งที่เรากระทําในขณะนี้ท่านยังไม่เข้าใจ แต่ภายหลังท่านจะเข้าใจ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 8, 'เปโตรทูลพระองค์ว่า “พระองค์จะทรงล้างเท้าของข้าพระองค์ไม่ได้” พระเยซูตรัสตอบเขาว่า “ถ้าเราไม่ล้างท่านแล้ว ท่านจะมีส่วนในเราไม่ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 9, 'ซีโมนเปโตรทูลพระองค์ว่า “พระองค์เจ้าข้า มิใช่แต่เท้าของข้าพระองค์เท่านั้น แต่ขอทรงโปรดล้างทั้งมือและศีรษะด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 10, 'พระเยซูตรัสกับเขาว่า “ผู้ที่อาบน้ําแล้วไม่จําเป็นต้องชําระกายอีก ล้างแต่เท้าเท่านั้น เพราะสะอาดหมดทั้งตัวแล้ว พวกท่านก็สะอาดแล้ว แต่ไม่ใช่ทุกคน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 11, 'เพราะพระองค์ทรงทราบว่า ใครจะเป็นผู้ทรยศพระองค์ เหตุฉะนั้นพระองค์จึงตรัสว่า “ท่านทั้งหลายไม่สะอาดทุกคน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 12, 'เมื่อพระองค์ทรงล้างเท้าเขาทั้งหลายแล้ว พระองค์ก็ทรงฉลองพระองค์ และเอนพระกายลงอีกตรัสกับเขาว่า “ท่านทั้งหลายเข้าใจในสิ่งที่เราได้กระทําแก่ท่านหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 13, 'ท่านทั้งหลายเรียกเราว่า พระอาจารย์และองค์พระผู้เป็นเจ้า ท่านเรียกถูกแล้ว เพราะเราเป็นเช่นนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 14, 'ฉะนั้นถ้าเราผู้เป็นองค์พระผู้เป็นเจ้าและพระอาจารย์ของท่าน ได้ล้างเท้าของพวกท่าน พวกท่านก็ควรจะล้างเท้าของกันและกันด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 15, 'เพราะว่าเราได้วางแบบแก่ท่านแล้ว เพื่อให้ท่านทําเหมือนดังที่เราได้กระทําแก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 16, 'เราบอกความจริงแก่ท่านว่า ทาสจะเป็นใหญ่กว่านายก็ไม่ได้ และทูตจะเป็นใหญ่กว่าผู้ที่ใช้เขาไปก็หามิได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 17, 'ถ้าท่านรู้ดังนี้แล้ว และท่านประพฤติตาม ท่านก็เป็นสุข');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 18, 'เรามิได้พูดถึงพวกท่านสิ้นทุกคน เรารู้จักผู้ที่เราได้เลือกไว้แล้ว แต่เพื่อพระคัมภีร์จะสําเร็จที่ว่า ‘ผู้ที่รับประทานอาหารกับเราได้ยกส้นเท้าต่อเรา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 19, 'เราบอกท่านทั้งหลายเดี๋ยวนี้ก่อนที่เรื่องนี้จะเกิดขึ้น เพื่อว่าเมื่อเรื่องนี้เกิดขึ้นแล้วท่านจะได้เชื่อว่าเราคือผู้นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 20, 'เราบอกความจริงแก่ท่านว่า ผู้ใดได้รับผู้ที่เราใช้ไป ผู้นั้นก็รับเราด้วย และผู้ใดได้รับเรา ผู้นั้นได้รับพระองค์ผู้ทรงใช้เรามา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 21, 'เมื่อพระเยซูตรัสดังนั้นแล้ว พระองค์ก็ทรงเป็นทุกข์ในพระทัย และตรัสเป็นพยานว่า “เราบอกความจริงแก่ท่านว่า คนหนึ่งในพวกท่านจะทรยศเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 22, 'เหล่าสาวกจึงมองหน้ากันและสงสัยว่าคนที่พระองค์ตรัสถึงนั้นคือผู้ใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 23, 'มีสาวกคนหนึ่งที่พระเยซูทรงรักได้เอนกายอยู่ที่พระทรวงของพระเยซู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 24, 'ซีโมนเปโตรจึงทําไม้ทํามือให้เขาทูลถามพระองค์ว่าคนที่พระองค์ตรัสถึงนั้นคือผู้ใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 25, 'ขณะที่ยังเอนกายอยู่ที่พระทรวงของพระเยซู สาวกคนนั้นก็ทูลถามพระองค์ว่า “พระองค์เจ้าข้า คนนั้นคือใคร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 26, 'พระเยซูตรัสตอบว่า “คนนั้นคือผู้ที่เราจะเอาอาหารนี้จิ้มแล้วยื่นให้” และเมื่อพระองค์ทรงเอาอาหารนั้นจิ้มแล้ว ก็ทรงยื่นให้แก่ยูดาสอิสคาริโอทบุตรชายซีโมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 27, 'เมื่อยูดาสรับประทานอาหารนั้นแล้ว ซาตานก็เข้าสิงในใจเขา พระเยซูจึงตรัสกับเขาว่า “ท่านจะทําอะไรก็จงทําเร็วๆเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 28, 'ไม่มีผู้ใดในพวกนั้นที่เอนกายลงรับประทานเข้าใจว่า เหตุใดพระองค์จึงตรัสกับเขาเช่นนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 29, 'บางคนคิดว่าเพราะยูดาสถือถุงเงิน พระเยซูจึงตรัสบอกเขาว่า “จงไปซื้อสิ่งที่เราต้องการสําหรับเทศกาลเลี้ยงนั้น” หรือตรัสบอกเขาว่า เขาควรจะให้ทานแก่คนจนบ้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 30, 'ดังนั้นเมื่อยูดาสรับประทานอาหารชิ้นนั้นแล้วเขาก็ออกไปทันที ขณะนั้นเป็นเวลากลางคืน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 31, 'เมื่อเขาออกไปแล้ว พระเยซูจึงตรัสว่า “บัดนี้บุตรมนุษย์ก็ได้รับเกียรติแล้ว และพระเจ้าทรงได้รับเกียรติเพราะบุตรมนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 32, 'ถ้าพระเจ้าได้รับเกียรติเพราะพระบุตร พระเจ้าก็จะทรงประทานให้พระบุตรมีเกียรติในพระองค์เอง และพระเจ้าจะทรงให้มีเกียรติเดี๋ยวนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 33, 'ลูกเล็กๆเอ๋ย เรายังจะอยู่กับเจ้าทั้งหลายอีกขณะหนึ่ง เจ้าจะเสาะหาเรา และดังที่เราได้พูดกับพวกยิวแล้ว บัดนี้เราจะพูดกับเจ้าคือ ‘ที่เราไปนั้นเจ้าทั้งหลายไปไม่ได้’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 34, 'เราให้บัญญัติใหม่ไว้แก่เจ้าทั้งหลายคือให้เจ้ารักซึ่งกันและกัน เรารักเจ้าทั้งหลายมาแล้วอย่างไร เจ้าจงรักกันและกันด้วยอย่างนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 35, 'ถ้าเจ้าทั้งหลายรักกันและกัน ดังนี้แหละคนทั้งปวงก็จะรู้ได้ว่าเจ้าทั้งหลายเป็นสาวกของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 36, 'ซีโมนเปโตรทูลพระองค์ว่า “พระองค์เจ้าข้า พระองค์จะเสด็จไปที่ไหน” พระเยซูตรัสตอบเขาว่า “ที่ซึ่งเราจะไปนั้นท่านจะตามเราไปเดี๋ยวนี้ไม่ได้ แต่ภายหลังท่านจะตามเราไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 37, 'เปโตรทูลพระองค์ว่า “พระองค์เจ้าข้า เหตุใดข้าพระองค์จึงตามพระองค์ไปเดี๋ยวนี้ไม่ได้ ข้าพระองค์จะสละชีวิตเพื่อพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 38, 'พระเยซูตรัสตอบเขาว่า “ท่านจะสละชีวิตของท่านเพื่อเราหรือ เราบอกความจริงแก่ท่านว่า ก่อนไก่ขัน ท่านจะปฏิเสธเราสามครั้ง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 1, '“อย่าให้ใจท่านทั้งหลายวิตกเลย ท่านเชื่อในพระเจ้า จงเชื่อในเราด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 2, 'ในพระนิเวศของพระบิดาเรามีคฤหาสน์หลายแห่ง ถ้าไม่มีเราคงได้บอกท่านแล้ว เราไปจัดเตรียมที่ไว้สําหรับท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 3, 'และถ้าเราไปจัดเตรียมที่ไว้สําหรับท่านแล้ว เราจะกลับมาอีกรับท่านไปอยู่กับเรา เพื่อว่าเราอยู่ที่ไหนท่านทั้งหลายจะอยู่ที่นั่นด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 4, 'ท่านทราบว่าเราจะไปที่ไหนและท่านก็รู้จักทางนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 5, 'โธมัสทูลพระองค์ว่า “พระองค์เจ้าข้า พวกข้าพระองค์ไม่ทราบว่าพระองค์จะเสด็จไปที่ไหน พวกข้าพระองค์จะรู้จักทางนั้นได้อย่างไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 6, 'พระเยซูตรัสกับเขาว่า “เราเป็นทางนั้น เป็นความจริง และเป็นชีวิต ไม่มีผู้ใดมาถึงพระบิดาได้นอกจากมาทางเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 7, 'ถ้าท่านทั้งหลายรู้จักเราแล้ว ท่านก็จะรู้จักพระบิดาของเราด้วย และตั้งแต่นี้ไปท่านก็รู้จักพระองค์และได้เห็นพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 8, 'ฟีลิปทูลพระองค์ว่า “พระองค์เจ้าข้า ขอสําแดงพระบิดาให้ข้าพระองค์ทั้งหลายเห็นและพวกข้าพระองค์จะพอใจ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 9, 'พระเยซูตรัสกับเขาว่า “ฟีลิปเอ๋ย เราได้อยู่กับท่านนานถึงเพียงนี้ และท่านยังไม่รู้จักเราหรือ ผู้ที่ได้เห็นเราก็ได้เห็นพระบิดา และท่านจะพูดได้อย่างไรว่า ‘ขอสําแดงพระบิดาให้ข้าพระองค์ทั้งหลายเห็น’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 10, 'ท่านไม่เชื่อหรือว่า เราอยู่ในพระบิดาและพระบิดาทรงอยู่ในเรา คําซึ่งเรากล่าวแก่ท่านทั้งหลายนั้น เรามิได้กล่าวตามใจชอบ แต่พระบิดาผู้ทรงสถิตอยู่ในเราได้ทรงกระทําพระราชกิจของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 11, 'จงเชื่อเราเถิดว่าเราอยู่ในพระบิดาและพระบิดาทรงอยู่ในเรา หรือมิฉะนั้นก็จงเชื่อเราเพราะกิจการเหล่านั้นเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 12, 'เราบอกความจริงแก่ท่านทั้งหลายว่า ผู้ที่เชื่อในเราจะกระทํากิจการซึ่งเราได้กระทํานั้นด้วย และเขาจะกระทํากิจการที่ยิ่งใหญ่กว่านั้นอีก เพราะว่าเราจะไปถึงพระบิดาของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 13, 'สิ่งใดที่ท่านทั้งหลายจะขอในนามของเรา เราจะกระทําสิ่งนั้น เพื่อว่าพระบิดาจะทรงได้รับเกียรติทางพระบุตร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 14, 'ถ้าท่านจะขอสิ่งใดในนามของเรา เราจะกระทําสิ่งนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 15, 'ถ้าท่านทั้งหลายรักเรา จงรักษาบัญญัติของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 16, 'เราจะทูลขอพระบิดา และพระองค์จะทรงประทานผู้ปลอบประโลมใจอีกผู้หนึ่งให้แก่ท่าน เพื่อพระองค์จะได้อยู่กับท่านตลอดไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 17, 'คือพระวิญญาณแห่งความจริง ผู้ซึ่งโลกรับไว้ไม่ได้ เพราะแลไม่เห็นพระองค์และไม่รู้จักพระองค์ แต่ท่านทั้งหลายรู้จักพระองค์ เพราะพระองค์ทรงสถิตอยู่กับท่านและจะประทับอยู่ในท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 18, 'เราจะไม่ละทิ้งท่านทั้งหลายไว้ให้เปล่าเปลี่ยว เราจะมาหาท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 19, 'อีกหน่อยหนึ่งโลกก็จะไม่เห็นเราอีกเลย แต่ท่านทั้งหลายจะเห็นเรา เพราะเราเป็นอยู่ ท่านทั้งหลายจะเป็นอยู่ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 20, 'ในวันนั้นท่านทั้งหลายจะรู้ว่า เราอยู่ในพระบิดาของเรา และท่านอยู่ในเรา และเราอยู่ในท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 21, 'ผู้ใดที่มีบัญญัติของเราและรักษาบัญญัตินั้น ผู้นั้นแหละเป็นผู้ที่รักเรา และผู้ที่รักเรานั้น พระบิดาของเราจะทรงรักเขา และเราจะรักเขา และจะสําแดงตัวของเราเองให้ปรากฏแก่เขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 22, 'ยูดาส มิใช่อิสคาริโอท ทูลพระองค์ว่า “พระองค์เจ้าข้า เหตุใดพระองค์จึงจะสําแดงพระองค์แก่พวกข้าพระองค์ และไม่ทรงสําแดงแก่โลก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 23, 'พระเยซูตรัสตอบเขาว่า “ถ้าผู้ใดรักเรา ผู้นั้นจะรักษาคําของเรา และพระบิดาของเราจะทรงรักเขา แล้วพระบิดากับเราจะมาหาเขาและจะอยู่กับเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 24, 'ผู้ที่ไม่รักเรา ก็ไม่รักษาคําของเรา และคําซึ่งท่านได้ยินนี้ไม่ใช่คําของเรา แต่เป็นของพระบิดาผู้ทรงใช้เรามา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 25, 'เราได้กล่าวคําเหล่านี้แก่ท่านทั้งหลายเมื่อเรายังอยู่กับท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 26, 'แต่พระองค์ผู้ปลอบประโลมใจนั้นคือพระวิญญาณบริสุทธิ์ ผู้ซึ่งพระบิดาจะทรงใช้มาในนามของเรา พระองค์นั้นจะทรงสอนท่านทั้งหลายทุกสิ่ง และจะให้ท่านระลึกถึงทุกสิ่งที่เราได้กล่าวไว้แก่ท่านแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 27, 'เรามอบสันติสุขไว้ให้แก่ท่านแล้ว สันติสุขของเราที่ให้แก่ท่านนั้น เราให้ท่านไม่เหมือนโลกให้ อย่าให้ใจของท่านวิตกและอย่ากลัวเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 28, 'ท่านได้ยินเรากล่าวแก่ท่านว่า ‘เราจะจากไปและจะกลับมาหาท่านอีก’ ถ้าท่านรักเรา ท่านก็จะชื่นชมยินดีเพราะเราบอกว่า ‘เราจะไปหาพระบิดา’ ด้วยว่าพระบิดาของเราทรงเป็นใหญ่กว่าเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 29, 'และบัดนี้เราได้บอกท่านทั้งหลายก่อนที่เหตุการณ์นั้นจะเกิดขึ้น เพื่อว่าเมื่อเหตุการณ์นั้นเกิดขึ้นแล้ว ท่านทั้งหลายจะได้เชื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 30, 'แต่นี้ไปเราจะไม่สนทนากับท่านทั้งหลายมากนัก เพราะว่าผู้ครองโลกนี้จะมาและไม่มีสิทธิอํานาจอะไรเหนือเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 31, 'แต่เราได้กระทําตามที่พระบิดาได้ทรงบัญชาเรา เพื่อโลกจะได้รู้ว่าเรารักพระบิดา จงลุกขึ้น ให้เราทั้งหลายไปกันเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 1, '“เราเป็นเถาองุ่นแท้ และพระบิดาของเราทรงเป็นผู้ดูแลรักษา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 2, 'กิ่งทุกกิ่งในเราที่ไม่ออกผล พระองค์ก็ทรงตัดทิ้งเสีย และกิ่งทุกกิ่งที่ออกผล พระองค์ก็ทรงลิดเพื่อให้ออกผลมากขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 3, 'ท่านทั้งหลายได้รับการชําระให้สะอาดแล้วด้วยถ้อยคําที่เราได้กล่าวแก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 4, 'จงเข้าสนิทอยู่ในเรา และเราเข้าสนิทอยู่ในท่าน กิ่งจะออกผลเองไม่ได้นอกจากจะติดอยู่กับเถาฉันใด ท่านทั้งหลายจะเกิดผลไม่ได้นอกจากท่านจะเข้าสนิทอยู่ในเราฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 5, 'เราเป็นเถาองุ่น ท่านทั้งหลายเป็นกิ่ง ผู้ที่เข้าสนิทอยู่ในเราและเราเข้าสนิทอยู่ในเขา ผู้นั้นจะเกิดผลมาก เพราะถ้าแยกจากเราแล้วท่านจะทําสิ่งใดไม่ได้เลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 6, 'ถ้าผู้ใดมิได้เข้าสนิทอยู่ในเรา ผู้นั้นก็ต้องถูกทิ้งเสียเหมือนกิ่ง แล้วก็เหี่ยวแห้งไป และเขารวบรวมไว้ทิ้งในไฟเผาเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 7, 'ถ้าท่านทั้งหลายเข้าสนิทอยู่ในเรา และถ้อยคําของเราฝังอยู่ในท่านแล้ว ท่านจะขอสิ่งใดซึ่งท่านปรารถนา ท่านก็จะได้สิ่งนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 8, 'พระบิดาของเราทรงได้รับเกียรติเพราะเหตุนี้ คือเมื่อท่านทั้งหลายเกิดผลมาก ท่านจึงเป็นสาวกของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 9, 'พระบิดาทรงรักเราฉันใด เราก็รักท่านทั้งหลายฉันนั้น จงยึดมั่นอยู่ในความรักของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 10, 'ถ้าท่านทั้งหลายรักษาบัญญัติของเรา ท่านก็จะยึดมั่นอยู่ในความรักของเรา เหมือนดังที่เรารักษาพระบัญญัติของพระบิดาเรา และยึดมั่นอยู่ในความรักของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 11, 'นี้คือสิ่งที่เราได้บอกแก่ท่านทั้งหลายแล้ว เพื่อให้ความยินดีของเราดํารงอยู่ในท่าน และให้ความยินดีของท่านเต็มเปี่ยม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 12, 'นี่แหละเป็นบัญญัติของเรา คือให้ท่านทั้งหลายรักซึ่งกันและกัน เหมือนดังที่เราได้รักท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 13, 'ไม่มีผู้ใดมีความรักที่ยิ่งใหญ่กว่านี้ คือการที่ผู้หนึ่งผู้ใดจะสละชีวิตของตนเพื่อมิตรสหายของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 14, 'ถ้าท่านทั้งหลายประพฤติตามที่เราสั่งท่าน ท่านก็จะเป็นมิตรสหายของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 15, 'เราไม่เรียกท่านทั้งหลายว่าทาสอีก เพราะทาสไม่ทราบว่านายของเขาทําอะไร แต่เราเรียกท่านว่ามิตรสหาย เพราะว่าทุกสิ่งที่เราได้ยินจากพระบิดาของเรา เราได้สําแดงแก่ท่านแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 16, 'ท่านทั้งหลายไม่ได้เลือกเรา แต่เราได้เลือกท่านทั้งหลาย และได้แต่งตั้งท่านทั้งหลายไว้ให้ท่านจะไปเกิดผล และเพื่อให้ผลของท่านอยู่ถาวร เพื่อว่าเมื่อท่านทูลขอสิ่งใดจากพระบิดาในนามของเรา พระองค์จะได้ประทานสิ่งนั้นให้แก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 17, 'สิ่งเหล่านี้เราสั่งท่านทั้งหลายไว้ว่า ท่านจงรักซึ่งกันและกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 18, 'ถ้าโลกนี้เกลียดชังท่านทั้งหลาย ท่านทั้งหลายก็รู้ว่าโลกได้เกลียดชังเราก่อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 19, 'ถ้าท่านทั้งหลายเป็นของโลก โลกก็จะรักท่านซึ่งเป็นของโลก แต่เพราะท่านไม่ใช่ของโลก แต่เราได้เลือกท่านออกจากโลก เหตุฉะนั้นโลกจึงเกลียดชังท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 20, 'จงระลึกถึงคําที่เราได้กล่าวแก่ท่านทั้งหลายแล้วว่า ‘ทาสมิได้เป็นใหญ่กว่านายของเขา’ ถ้าเขาข่มเหงเรา เขาก็จะข่มเหงท่านทั้งหลายด้วย ถ้าเขารักษาคําของเรา เขาก็จะรักษาคําของท่านทั้งหลายด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 21, 'แต่ทุกสิ่งที่เขาจะกระทําแก่พวกท่านนั้นก็เพราะนามของเรา เพราะเขาไม่รู้จักพระองค์ผู้ทรงใช้เรามา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 22, 'ถ้าเราไม่ได้มาประกาศแก่พวกเขา เขาก็คงจะไม่มีบาป แต่บัดนี้เขาไม่มีข้อแก้ตัวในเรื่องบาปของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 23, 'ผู้ที่เกลียดชังเราก็เกลียดชังพระบิดาของเราด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 24, 'ถ้า ณ ท่ามกลางพวกเขา เรามิได้กระทําสิ่งซึ่งไม่มีผู้อื่นได้กระทําเลย พวกเขาก็จะไม่มีบาป แต่เดี๋ยวนี้เขาก็ได้เห็นและเกลียดชังทั้งตัวเราและพระบิดาของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 25, 'แต่การนี้เกิดขึ้นเพื่อคําที่เขียนไว้ในพระราชบัญญัติของพวกเขาจะสําเร็จ ซึ่งว่า ‘เขาได้เกลียดชังเราโดยไร้เหตุ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 26, 'แต่เมื่อพระองค์ผู้ปลอบประโลมใจที่เราจะใช้มาจากพระบิดามาหาท่านทั้งหลาย คือพระวิญญาณแห่งความจริง ผู้ทรงมาจากพระบิดานั้นได้เสด็จมาแล้ว พระองค์นั้นจะทรงเป็นพยานถึงเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 27, 'และท่านทั้งหลายก็จะเป็นพยานด้วย เพราะว่าท่านได้อยู่กับเราตั้งแต่แรกแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 1, '“เราบอกสิ่งเหล่านี้แก่ท่านทั้งหลาย ก็เพื่อไม่ให้ท่านสะดุดใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 2, 'เขาจะไล่ท่านเสียจากธรรมศาลา แท้จริงวันหนึ่งคนใดที่ประหารชีวิตของท่านจะคิดว่า เขาทําการนั้นเป็นการปฏิบัติพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 3, 'เขาจะกระทําดังนั้นแก่ท่านเพราะเขาไม่รู้จักพระบิดาและไม่รู้จักเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 4, 'แต่ที่เราบอกสิ่งเหล่านี้แก่ท่านก็เพื่อว่าเมื่อถึงเวลานั้น ท่านจะได้ระลึกว่าเราได้บอกท่านไว้แล้ว และเรามิได้บอกเรื่องนี้แก่ท่านทั้งหลายแต่แรก เพราะว่าเรายังอยู่กับท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 5, 'แต่บัดนี้เรากําลังจะไปหาพระองค์ผู้ทรงใช้เรามา และไม่มีใครในพวกท่านถามเราว่า ‘พระองค์จะเสด็จไปที่ไหน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 6, 'แต่เพราะเราได้บอกเรื่องนี้แก่พวกท่าน จิตใจของท่านจึงเต็มด้วยความทุกข์โศก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 7, 'อย่างไรก็ตามเราบอกความจริงแก่ท่านทั้งหลาย คือการที่เราจากไปนั้นก็เพื่อประโยชน์ของท่าน เพราะถ้าเราไม่ไป พระองค์ผู้ปลอบประโลมใจก็จะไม่เสด็จมาหาท่าน แต่ถ้าเราไปแล้ว เราก็จะใช้พระองค์มาหาท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 8, 'เมื่อพระองค์นั้นเสด็จมาแล้ว พระองค์จะทรงกระทําให้โลกรู้สึกถึงความผิดบาป และถึงความชอบธรรม และถึงการพิพากษา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 9, 'ถึงความผิดบาปนั้น คือเพราะเขาไม่เชื่อในเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 10, 'ถึงความชอบธรรมนั้น คือเพราะเราไปหาพระบิดาของเรา และท่านทั้งหลายจะไม่เห็นเราอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 11, 'ถึงการพิพากษานั้น คือเพราะผู้ครองโลกนี้ถูกพิพากษาแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 12, 'เรายังมีอีกหลายสิ่งที่จะบอกท่านทั้งหลาย แต่เดี๋ยวนี้ท่านยังรับไว้ไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 13, 'เมื่อพระองค์ พระวิญญาณแห่งความจริงจะเสด็จมาแล้ว พระองค์จะนําท่านทั้งหลายไปสู่ความจริงทั้งมวล เพราะพระองค์จะไม่ตรัสโดยพระองค์เอง แต่พระองค์จะตรัสสิ่งที่พระองค์ทรงได้ยิน และพระองค์จะทรงแจ้งให้ท่านทั้งหลายรู้ถึงสิ่งเหล่านั้นที่จะเกิดขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 14, 'พระองค์จะทรงให้เราได้รับเกียรติ เพราะว่าพระองค์จะทรงเอาสิ่งที่เป็นของเรามาสําแดงแก่ท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 15, 'ทุกสิ่งที่พระบิดาทรงมีนั้นเป็นของเรา เหตุฉะนั้นเราจึงกล่าวว่า พระวิญญาณทรงเอาสิ่งซึ่งเป็นของเรานั้นมาสําแดงแก่ท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 16, 'อีกหน่อยท่านทั้งหลายก็จะไม่เห็นเรา และต่อไปอีกหน่อยท่านก็จะเห็นเรา เพราะเราไปถึงพระบิดา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 17, 'สาวกบางคนของพระองค์จึงพูดกันว่า “ที่พระองค์ตรัสกับเราว่า ‘อีกหน่อยท่านทั้งหลายก็จะไม่เห็นเรา และต่อไปอีกหน่อยท่านก็จะเห็นเรา’ และ ‘เพราะเราไปถึงพระบิดา’ เหล่านี้หมายความว่าอะไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 18, 'เขาจึงพูดกันว่า “นั้นหมายความว่าอะไรที่พระองค์ตรัสว่า ‘อีกหน่อย’ เราไม่ทราบว่า สิ่งที่พระองค์ตรัสนั้นหมายความว่าอะไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 19, 'พระเยซูทรงทราบว่าเขาอยากทูลถามพระองค์ จึงตรัสกับเขาว่า “ท่านทั้งหลายถามกันอยู่หรือว่า เราหมายความว่าอะไรที่พูดว่า ‘อีกหน่อยท่านก็จะไม่เห็นเรา และต่อไปอีกหน่อยท่านก็จะเห็นเรา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 20, 'เราบอกความจริงแก่ท่านทั้งหลายว่า ท่านจะร้องไห้และคร่ําครวญ แต่โลกจะชื่นชมยินดี และท่านทั้งหลายจะทุกข์โศก แต่ความทุกข์โศกของท่านจะกลับกลายเป็นความชื่นชมยินดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 21, 'เมื่อผู้หญิงกําลังจะคลอดบุตร นางก็มีความทุกข์ เพราะถึงกําหนดแล้ว แต่เมื่อคลอดบุตรแล้ว นางก็ไม่ระลึกถึงความเจ็บปวดนั้นเลย เพราะมีความชื่นชมยินดีที่คนหนึ่งเกิดมาในโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 22, 'ฉันใดก็ดีขณะนี้ท่านทั้งหลายมีความทุกข์โศก แต่เราจะเห็นท่านอีก และใจท่านจะชื่นชมยินดี และไม่มีผู้ใดช่วงชิงความชื่นชมยินดีไปจากท่านได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 23, 'ในวันนั้นท่านจะไม่ถามอะไรเราอีก เราบอกความจริงแก่ท่านทั้งหลายว่า ถ้าท่านจะขอสิ่งใดจากพระบิดาในนามของเรา พระองค์จะทรงประทานสิ่งนั้นให้แก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 24, 'แม้จนบัดนี้ท่านยังไม่ได้ขอสิ่งใดในนามของเรา จงขอเถิดแล้วจะได้ เพื่อความชื่นชมยินดีของท่านจะมีเต็มเปี่ยม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 25, 'เราพูดเรื่องนี้กับท่านเป็นคําอุปมา แต่วันหนึ่งเราจะไม่พูดกับท่านเป็นคําอุปมาอีก แต่จะบอกท่านถึงเรื่องพระบิดาอย่างแจ่มแจ้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 26, 'ในวันนั้นพวกท่านจะทูลขอในนามของเรา และเราจะไม่บอกท่านว่า เราจะอ้อนวอนพระบิดาเพื่อท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 27, 'เพราะว่าพระบิดาเองก็ทรงรักท่านทั้งหลาย เพราะท่านรักเราและเชื่อว่าเรามาจากพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 28, 'เรามาจากพระบิดาและได้เข้ามาในโลกแล้ว เราจะจากโลกนี้ไปถึงพระบิดาอีก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 29, 'เหล่าสาวกของพระองค์ทูลพระองค์ว่า “ดูเถิด บัดนี้พระองค์ตรัสอย่างแจ่มแจ้งแล้ว มิได้ตรัสเป็นคําอุปมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 30, 'เดี๋ยวนี้พวกข้าพระองค์รู้แน่ว่า พระองค์ทรงทราบทุกสิ่ง และไม่จําเป็นที่ผู้ใดจะทูลถามพระองค์อีก ด้วยเหตุนี้ข้าพระองค์เชื่อว่าพระองค์ทรงมาจากพระเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 31, 'พระเยซูตรัสตอบเขาว่า “เดี๋ยวนี้ท่านทั้งหลายเชื่อแล้วหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 32, 'ดูเถิด เวลาจะมา เวลานั้นก็ถึงแล้ว ที่ท่านจะต้องกระจัดกระจายไปยังที่ของท่านทุกคน และจะทิ้งเราไว้แต่ผู้เดียว แต่เราหาได้อยู่ผู้เดียวไม่ เพราะพระบิดาทรงสถิตอยู่กับเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 33, 'เราได้บอกเรื่องนี้แก่ท่าน เพื่อท่านจะได้มีสันติสุขในเรา ในโลกนี้ท่านจะประสบความทุกข์ยาก แต่จงชื่นใจเถิด เพราะว่าเราได้ชนะโลกแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 1, 'พระเยซูตรัสดังนั้นแล้ว พระองค์ก็ทรงแหงนพระพักตร์ขึ้นดูฟ้าและตรัสว่า “พระบิดาเจ้าข้า ถึงเวลาแล้ว ขอทรงโปรดให้พระบุตรของพระองค์ได้รับเกียรติ เพื่อพระบุตรจะได้ถวายเกียรติแด่พระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 2, 'ดังที่พระองค์ได้ทรงโปรดให้พระบุตรมีอํานาจเหนือเนื้อหนังทั้งสิ้น เพื่อให้พระบุตรประทานชีวิตนิรันดร์แก่คนทั้งปวงที่พระองค์ทรงมอบแก่พระบุตรนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 3, 'และนี่แหละคือชีวิตนิรันดร์ คือที่เขารู้จักพระองค์ ผู้ทรงเป็นพระเจ้าเที่ยงแท้องค์เดียว และรู้จักพระเยซูคริสต์ที่พระองค์ทรงใช้มา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 4, 'ข้าพระองค์ได้ถวายเกียรติแด่พระองค์ในโลก ข้าพระองค์ได้กระทําพระราชกิจที่พระองค์ทรงให้ข้าพระองค์กระทํานั้นสําเร็จแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 5, 'บัดนี้ โอ พระบิดาเจ้าข้า ขอทรงโปรดให้ข้าพระองค์ได้รับเกียรติต่อพระพักตร์ของพระองค์ คือเกียรติซึ่งข้าพระองค์ได้มีร่วมกับพระองค์ก่อนที่โลกนี้มีมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 6, 'ข้าพระองค์ได้สําแดงพระนามของพระองค์แก่คนทั้งหลายที่พระองค์ได้ประทานให้แก่ข้าพระองค์จากมวลมนุษย์โลก คนเหล่านั้นเป็นของพระองค์แล้ว และพระองค์ได้ประทานเขาให้แก่ข้าพระองค์ และเขาได้รักษาพระดํารัสของพระองค์แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 7, 'บัดนี้เขาทั้งหลายรู้ว่า ทุกสิ่งที่พระองค์ได้ประทานแก่ข้าพระองค์นั้นมาจากพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 8, 'เพราะว่าพระดํารัสที่พระองค์ตรัสประทานให้แก่ข้าพระองค์นั้น ข้าพระองค์ได้ให้เขาแล้ว และเขาได้รับไว้ และเขารู้แน่ว่าข้าพระองค์มาจากพระองค์ และเขาเชื่อว่า พระองค์ได้ทรงใช้ข้าพระองค์มา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 9, 'ข้าพระองค์อธิษฐานเพื่อเขา ข้าพระองค์มิได้อธิษฐานเพื่อโลก แต่เพื่อคนเหล่านั้นที่พระองค์ได้ประทานแก่ข้าพระองค์ เพราะว่าเขาเป็นของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 10, 'ทุกสิ่งซึ่งเป็นของข้าพระองค์ก็เป็นของพระองค์ และทุกสิ่งซึ่งเป็นของพระองค์ก็เป็นของข้าพระองค์ และข้าพระองค์มีเกียรติในสิ่งเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 11, 'บัดนี้ข้าพระองค์จะไม่อยู่ในโลกนี้อีก แต่พวกเขายังอยู่ในโลกนี้ และข้าพระองค์กําลังจะไปหาพระองค์ ข้าแต่พระบิดาผู้บริสุทธิ์ ขอพระองค์ทรงโปรดพิทักษ์รักษาบรรดาผู้ที่พระองค์ได้ประทานแก่ข้าพระองค์ไว้โดยพระนามของพระองค์ เพื่อเขาจะเป็นอันหนึ่งอันเดียวกัน เหมือนดังข้าพระองค์กับพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 12, 'เมื่อข้าพระองค์ยังอยู่กับคนเหล่านั้นในโลกนี้ ข้าพระองค์ก็ได้พิทักษ์รักษาพวกเขาไว้โดยพระนามของพระองค์ ผู้ซึ่งพระองค์ได้ประทานแก่ข้าพระองค์ ข้าพระองค์ได้ปกป้องเขาไว้และไม่มีผู้หนึ่งผู้ใดเสียไปนอกจากลูกของความพินาศ เพื่อพระคัมภีร์จะสําเร็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 13, 'และบัดนี้ข้าพระองค์กําลังจะไปหาพระองค์ และข้าพระองค์กล่าวถึงสิ่งเหล่านี้ในโลก เพื่อเขาจะได้รับความชื่นชมยินดีของข้าพระองค์อย่างเต็มเปี่ยม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 14, 'ข้าพระองค์ได้มอบพระดํารัสของพระองค์ให้แก่เขาแล้ว และโลกนี้ได้เกลียดชังเขา เพราะเขาไม่ใช่ของโลก เหมือนดังที่ข้าพระองค์ไม่ใช่ของโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 15, 'ข้าพระองค์ไม่ได้ขอให้พระองค์เอาเขาออกไปจากโลก แต่ขอปกป้องเขาไว้ให้พ้นจากความชั่วร้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 16, 'เขาไม่ใช่ของโลก เหมือนดังที่ข้าพระองค์ไม่ใช่ของโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 17, 'ขอทรงโปรดชําระเขาให้บริสุทธิ์ด้วยความจริงของพระองค์ พระวจนะของพระองค์เป็นความจริง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 18, 'พระองค์ทรงใช้ข้าพระองค์มาในโลกฉันใด ข้าพระองค์ก็ใช้เขาไปในโลกฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 19, 'ข้าพระองค์ถวายตัวของข้าพระองค์เพราะเห็นแก่เขา เพื่อให้เขารับการทรงชําระแต่งตั้งไว้โดยความจริงด้วยเช่นกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 20, 'ข้าพระองค์มิได้อธิษฐานเพื่อคนเหล่านี้พวกเดียว แต่เพื่อคนทั้งปวงที่จะเชื่อในข้าพระองค์เพราะถ้อยคําของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 21, 'เพื่อเขาทั้งหลายจะได้เป็นอันหนึ่งอันเดียวกัน ดังที่พระองค์คือพระบิดาทรงสถิตในข้าพระองค์ และข้าพระองค์ในพระองค์ เพื่อให้เขาเป็นอันหนึ่งอันเดียวกันกับพระองค์และกับข้าพระองค์ด้วย เพื่อโลกจะได้เชื่อว่าพระองค์ทรงใช้ข้าพระองค์มา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 22, 'เกียรติซึ่งพระองค์ได้ประทานแก่ข้าพระองค์ ข้าพระองค์ได้มอบให้แก่เขา เพื่อเขาจะได้เป็นอันหนึ่งอันเดียวกัน ดังที่พระองค์กับข้าพระองค์เป็นอันหนึ่งอันเดียวกันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 23, 'ข้าพระองค์อยู่ในเขา และพระองค์ทรงอยู่ในข้าพระองค์ เพื่อเขาทั้งหลายจะได้เป็นอันหนึ่งอันเดียวกันอย่างสมบูรณ์ และเพื่อโลกจะได้รู้ว่าพระองค์ทรงใช้ข้าพระองค์มา และพระองค์ทรงรักเขาเหมือนดังที่พระองค์ทรงรักข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 24, 'พระบิดาเจ้าข้า ข้าพระองค์ปรารถนาให้คนเหล่านั้นที่พระองค์ได้ประทานให้แก่ข้าพระองค์ อยู่กับข้าพระองค์ในที่ซึ่งข้าพระองค์อยู่นั้นด้วย เพื่อเขาจะได้เห็นสง่าราศีของข้าพระองค์ซึ่งพระองค์ได้ประทานแก่ข้าพระองค์ เพราะพระองค์ทรงรักข้าพระองค์ก่อนที่จะทรงสร้างโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 25, 'โอ ข้าแต่พระบิดาผู้ชอบธรรม โลกนี้ไม่รู้จักพระองค์ แต่ข้าพระองค์รู้จักพระองค์ และคนเหล่านี้รู้ว่าพระองค์ได้ทรงใช้ข้าพระองค์มา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 26, 'ข้าพระองค์ได้ประกาศให้เขารู้จักพระนามของพระองค์ และจะประกาศให้เขารู้อีก เพื่อความรักที่พระองค์ได้ทรงรักข้าพระองค์จะดํารงอยู่ในเขา และข้าพระองค์จะอยู่ในเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 1, 'เมื่อพระเยซูตรัสดังนี้แล้ว พระองค์ได้เสด็จออกไปกับเหล่าสาวกของพระองค์ข้ามลําธารขิดโรนไปยังสวนแห่งหนึ่ง พระองค์เสด็จเข้าไปในสวนนั้นกับเหล่าสาวก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 2, 'ยูดาสผู้ที่ทรยศพระองค์ก็รู้จักสวนนั้นด้วย เพราะว่าพระเยซูกับเหล่าสาวกของพระองค์เคยมาพบกันที่นั่นบ่อยๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 3, 'ยูดาสจึงพาพวกทหารกับเจ้าหน้าที่มาจากพวกปุโรหิตใหญ่และพวกฟาริสี ถือโคมถือไต้และเครื่องอาวุธไปที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 4, 'พระเยซูทรงทราบทุกสิ่งที่จะเกิดขึ้นกับพระองค์ พระองค์จึงเสด็จออกไปถามเขาว่า “ท่านทั้งหลายมาหาใคร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 5, 'เขาทูลตอบพระองค์ว่า “มาหาเยซูชาวนาซาเร็ธ” พระเยซูตรัสกับเขาว่า “เราคือผู้นั้นแหละ” ยูดาสผู้ทรยศพระองค์ก็ยืนอยู่กับคนเหล่านั้นด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 6, 'เมื่อพระองค์ตรัสกับเขาทั้งหลายว่า “เราคือผู้นั้นแหละ” เขาทั้งหลายได้ถอยหลังและล้มลงที่ดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 7, 'พระองค์จึงตรัสถามเขาอีกว่า “ท่านมาหาใคร” เขาทูลตอบว่า “มาหาเยซูชาวนาซาเร็ธ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 8, 'พระเยซูตรัสตอบว่า “เราบอกท่านแล้วว่าเราคือผู้นั้น เหตุฉะนั้นถ้าท่านแสวงหาเราก็จงปล่อยคนเหล่านี้ไปเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 9, 'ทั้งนี้ก็เพื่อพระดํารัสจะสําเร็จ ซึ่งพระเยซูตรัสไว้แล้วว่า “คนเหล่านั้นซึ่งพระองค์ได้ประทานแก่ข้าพระองค์ไม่ได้เสียไปสักคนเดียว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 10, 'ซีโมนเปโตรมีดาบ จึงชักออกและฟันผู้รับใช้คนหนึ่งของมหาปุโรหิต ถูกหูข้างขวาขาดไป ชื่อของผู้รับใช้คนนั้นคือมัลคัส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 11, 'พระเยซูจึงตรัสกับเปโตรว่า “จงเอาดาบใส่ฝักเสีย เราจะไม่ดื่มถ้วยซึ่งพระบิดาของเราประทานแก่เราหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 12, 'พวกพลทหารกับนายทหารและเจ้าหน้าที่ของพวกยิวจึงจับพระเยซูมัดไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 13, 'แล้วพาพระองค์ไปหาอันนาสก่อน เพราะอันนาสเป็นพ่อตาของคายาฟาสผู้ซึ่งเป็นมหาปุโรหิตประจําการในปีนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 14, 'คายาฟาสผู้นี้แหละที่แนะนําพวกยิวว่า ควรให้คนหนึ่งตายแทนพลเมืองทั้งหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 15, 'ซีโมนเปโตรได้ติดตามพระเยซูไป และสาวกอีกคนหนึ่งก็ติดตามไปด้วย สาวกคนนั้นเป็นที่รู้จักของมหาปุโรหิต และเขาได้เข้าไปกับพระเยซูถึงคฤหาสน์ของมหาปุโรหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 16, 'แต่เปโตรยืนอยู่ข้างนอกริมประตู สาวกอีกคนหนึ่งนั้นที่รู้จักกันกับมหาปุโรหิต จึงได้ออกไปและพูดกับหญิงที่เฝ้าประตู แล้วก็พาเปโตรเข้าไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 17, 'ผู้หญิงคนที่เฝ้าประตูจึงถามเปโตรว่า “ท่านเป็นสาวกของคนนั้นด้วยหรือ” เขาตอบว่า “ข้าไม่เป็น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 18, 'พวกผู้รับใช้กับเจ้าหน้าที่ก็ยืนอยู่ที่นั่นเอาถ่านมาก่อไฟเพราะอากาศหนาว แล้วก็ยืนผิงไฟกัน เปโตรก็ยืนผิงไฟอยู่กับเขาด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 19, 'มหาปุโรหิตจึงได้ถามพระเยซูถึงเหล่าสาวกของพระองค์ และคําสอนของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 20, 'พระเยซูตรัสตอบท่านว่า “เราได้กล่าวให้โลกฟังอย่างเปิดเผย เราสั่งสอนเสมอทั้งในธรรมศาลาและที่ในพระวิหารที่พวกยิวเคยชุมนุมกัน และเราไม่ได้กล่าวสิ่งใดอย่างลับๆเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 21, 'ท่านถามเราทําไม จงถามผู้ที่ได้ฟังเราว่า เราได้พูดอะไรกับเขา ดูเถิด เขารู้ว่าเรากล่าวอะไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 22, 'เมื่อพระองค์ตรัสดังนั้นแล้ว เจ้าหน้าที่คนหนึ่งซึ่งยืนอยู่ที่นั่นได้ตบพระเยซูด้วยฝ่ามือของเขาแล้วพูดว่า “เจ้าตอบมหาปุโรหิตอย่างนั้นหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 23, 'พระเยซูตรัสตอบเขาว่า “ถ้าเราพูดผิด จงเป็นพยานในสิ่งที่ผิดนั้น แต่ถ้าเราพูดถูก ท่านตบเราทําไม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 24, 'อันนาสจึงให้พาพระเยซูซึ่งถูกมัดอยู่ไปหาคายาฟาสผู้เป็นมหาปุโรหิตประจําการ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 25, 'ซีโมนเปโตรกําลังยืนผิงไฟอยู่ คนเหล่านั้นจึงถามเปโตรว่า “เจ้าเป็นสาวกของคนนั้นด้วยหรือ” เปโตรปฏิเสธว่า “ข้าไม่เป็น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 26, 'ผู้รับใช้คนหนึ่งของมหาปุโรหิตซึ่งเป็นญาติกับคนที่เปโตรฟันหูขาดก็กล่าวขึ้นว่า “ข้าเห็นเจ้ากับท่านผู้นั้นในสวนไม่ใช่หรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 27, 'เปโตรปฏิเสธอีกครั้งหนึ่ง และในทันใดนั้นไก่ก็ขัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 28, 'เขาจึงได้พาพระเยซูออกไปจากคายาฟาสไปยังศาลปรีโทเรียม เป็นเวลาเช้าตรู่ พวกเขาเองไม่ได้เข้าไปในศาลปรีโทเรียม เพื่อไม่ให้เป็นมลทิน แต่จะได้กินปัสกาได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 29, 'ปีลาตจึงออกมาหาเขาเหล่านั้นแล้วถามว่า “พวกท่านมีเรื่องอะไรมาฟ้องคนนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 30, 'เขาตอบท่านว่า “ถ้าเขาไม่ใช่ผู้ร้าย พวกข้าพเจ้าก็จะไม่มอบเขาไว้กับท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 31, 'ปีลาตจึงกล่าวแก่เขาว่า “พวกท่านจงเอาคนนี้ไปพิพากษาตามกฎหมายของท่านเถิด” พวกยิวจึงเรียนท่านว่า “การที่พวกข้าพเจ้าจะประหารชีวิตคนใดคนหนึ่งนั้นเป็นการผิดกฎหมาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 32, 'ทั้งนี้เพื่อพระดํารัสของพระเยซูจะสําเร็จ ซึ่งพระองค์ตรัสว่า พระองค์จะทรงสิ้นพระชนม์อย่างไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 33, 'ปีลาตจึงเข้าไปในศาลปรีโทเรียมอีก และเรียกพระเยซูมาทูลถามพระองค์ว่า “ท่านเป็นกษัตริย์ของพวกยิวหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 34, 'พระเยซูตรัสตอบท่านว่า “ท่านถามอย่างนั้นแต่ลําพังท่านเองหรือ หรือมีคนอื่นบอกท่านถึงเรื่องของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 35, 'ปีลาตทูลตอบว่า “เราเป็นยิวหรือ ชนชาติของท่านเองและพวกปุโรหิตใหญ่ได้มอบท่านไว้กับเรา ท่านทําผิดอะไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 36, 'พระเยซูตรัสตอบว่า “อาณาจักรของเรามิได้เป็นของโลกนี้ ถ้าอาณาจักรของเรามาจากโลกนี้ คนของเราก็จะได้ต่อสู้ไม่ให้เราตกในเงื้อมมือของพวกยิว แต่บัดนี้อาณาจักรของเรามิได้มาจากโลกนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 37, 'ปีลาตจึงทูลถามพระองค์ว่า “ถ้าเช่นนั้นท่านเป็นกษัตริย์หรือ” พระเยซูตรัสตอบว่า “ท่านพูดว่าเราเป็นกษัตริย์ เพราะเหตุนี้เราจึงเกิดมาและเข้ามาในโลก เพื่อเราจะเป็นพยานถึงความจริง คนทั้งปวงซึ่งอยู่ฝ่ายความจริงย่อมฟังเสียงของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 38, 'ปีลาตทูลถามพระองค์ว่า “ความจริงคืออะไร” เมื่อถามดังนั้นแล้วท่านก็ออกไปหาพวกยิวอีก และบอกเขาว่า “เราไม่เห็นคนนั้นมีความผิดแม้แต่น้อย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 39, 'แต่พวกท่านมีธรรมเนียมให้เราปล่อยคนหนึ่งให้แก่ท่านในเทศกาลปัสกา ฉะนั้นท่านจะให้เราปล่อยกษัตริย์ของพวกยิวให้แก่ท่านหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 40, 'คนทั้งหลายจึงร้องขึ้นอีกว่า “อย่าปล่อยคนนี้ แต่จงปล่อยบารับบัส” บารับบัสนั้นเป็นโจร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 1, 'ขณะนั้นปีลาตจึงให้เอาพระเยซูไปโบยตี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 2, 'และพวกทหารก็เอาหนามสานเป็นมงกุฎสวมพระเศียรของพระองค์ และให้พระองค์สวมเสื้อสีม่วง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 3, 'แล้วทูลว่า “ท่านกษัตริย์ของพวกยิว ขอทรงพระเจริญ” และเขาก็ตบพระองค์ด้วยฝ่ามือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 4, 'ปีลาตจึงออกไปอีกและกล่าวแก่คนทั้งหลายว่า “ดูเถิด เราพาคนนี้ออกมาให้ท่านทั้งหลายเพื่อให้ท่านรู้ว่า เราไม่เห็นว่าเขามีความผิดสิ่งใดเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 5, 'พระเยซูจึงเสด็จออกมาทรงมงกุฎทําด้วยหนามและทรงเสื้อสีม่วง และปีลาตกล่าวแก่เขาทั้งหลายว่า “ดูคนนี้ซิ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 6, 'ฉะนั้นเมื่อพวกปุโรหิตใหญ่และพวกเจ้าหน้าที่ได้เห็นพระองค์ เขาทั้งหลายร้องอึงว่า “ตรึงเขาเสีย ตรึงเขาเสีย” ปีลาตกล่าวแก่เขาว่า “พวกท่านเอาเขาไปตรึงเองเถิด เพราะเราไม่เห็นว่าเขามีความผิดเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 7, 'พวกยิวตอบท่านว่า “พวกเรามีกฎหมาย และตามกฎหมายนั้นเขาควรจะตาย เพราะเขาได้ตั้งตัวเป็นพระบุตรของพระเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 8, 'ฉะนั้นครั้นปีลาตได้ยินดังนั้น ท่านก็ตกใจกลัวมากขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 9, 'ท่านเข้าไปในศาลปรีโทเรียมอีกและทูลพระเยซูว่า “ท่านมาจากไหน” แต่พระเยซูมิได้ตรัสตอบประการใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 10, 'ปีลาตจึงทูลพระองค์ว่า “ท่านจะไม่พูดกับเราหรือ ท่านไม่รู้หรือว่าเรามีอํานาจที่จะตรึงท่านที่กางเขน และมีอํานาจที่จะปล่อยท่านได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 11, 'พระเยซูตรัสตอบว่า “ท่านจะมีอํานาจเหนือเราไม่ได้ นอกจากจะประทานจากเบื้องบนให้แก่ท่าน เหตุฉะนั้นผู้ที่มอบเราไว้กับท่านจึงมีความผิดบาปมากกว่าท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 12, 'ตั้งแต่นั้นไปปีลาตก็หาโอกาสที่จะปล่อยพระองค์ แต่พวกยิวร้องอึงว่า “ถ้าท่านปล่อยชายคนนี้ ท่านก็ไม่ใช่มิตรของซีซาร์ ผู้ใดที่ตั้งตัวเป็นกษัตริย์ก็พูดต่อสู้ซีซาร์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 13, 'เมื่อปีลาตได้ยินดังนั้น ท่านจึงพาพระเยซูออกมา แล้วนั่งบัลลังก์พิพากษา ณ ที่เรียกว่า ลานปูศิลา ภาษาฮีบรูเรียกว่า กับบาธา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 14, 'วันนั้นเป็นวันเตรียมปัสกา เวลาประมาณเที่ยง ท่านพูดกับพวกยิวว่า “ดูเถิด นี่คือกษัตริย์ของท่านทั้งหลาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 15, 'แต่เขาทั้งหลายร้องอึงว่า “เอาเขาไปเสีย เอาเขาไปเสีย ตรึงเขาเสียที่กางเขน” ปีลาตพูดกับเขาว่า “ท่านจะให้เราตรึงกษัตริย์ของท่านทั้งหลายที่กางเขนหรือ” พวกปุโรหิตใหญ่ตอบว่า “เว้นแต่ซีซาร์แล้ว เราไม่มีกษัตริย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 16, 'แล้วปีลาตจึงมอบพระองค์ให้เขาพาไปตรึงที่กางเขน และเขาพาพระเยซูไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 17, 'และพระองค์ทรงแบกกางเขนของพระองค์ไปยังสถานที่แห่งหนึ่งซึ่งเรียกว่า สถานที่กะโหลกศีรษะ ภาษาฮีบรูเรียกว่า กลโกธา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 18, 'ณ ที่นั้น เขาตรึงพระองค์ไว้ที่กางเขนกับคนอีกสองคน คนละข้างและพระเยซูทรงอยู่กลาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 19, 'ปีลาตให้เขียนคําประจานติดไว้บนกางเขน และคําประจานนั้นว่า “เยซูชาวนาซาเร็ธ กษัตริย์ของพวกยิว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 20, 'พวกยิวเป็นอันมากจึงได้อ่านคําประจานนี้ เพราะที่ซึ่งเขาตรึงพระเยซูนั้นอยู่ใกล้กับกรุง และคํานั้นเขียนไว้เป็นภาษาฮีบรู ภาษากรีก และภาษาลาติน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 21, 'ฉะนั้นพวกปุโรหิตใหญ่ของพวกยิวจึงเรียนปีลาตว่า “ขออย่าเขียนว่า ‘กษัตริย์ของพวกยิว’ แต่ขอเขียนว่า ‘คนนี้บอกว่า เราเป็นกษัตริย์ของพวกยิว’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 22, 'ปีลาตตอบว่า “สิ่งใดที่เราเขียนแล้วก็แล้วไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 23, 'ครั้นพวกทหารตรึงพระเยซูไว้ที่กางเขนแล้ว เขาทั้งหลายก็เอาฉลองพระองค์แบ่งออกเป็นสี่ส่วนให้ทหารทุกคนคนละส่วน และเอาฉลองพระองค์ชั้นในด้วย ฉลองพระองค์ชั้นในนั้นไม่มีตะเข็บ ทอตั้งแต่บนตลอดล่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 24, 'เหตุฉะนั้นเขาจึงพูดกันว่า “เราอย่าฉีกแบ่งกันเลย แต่ให้เราจับฉลากกันจะได้รู้ว่าใครจะได้” ทั้งนี้เพื่อพระคัมภีร์จะสําเร็จที่ว่า ‘เสื้อผ้าของข้าพระองค์ เขาแบ่งปันกัน ส่วนเสื้อของข้าพระองค์นั้น เขาก็จับฉลากกัน’ พวกทหารจึงได้กระทําดังนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 25, 'ผู้ที่ยืนอยู่ข้างกางเขนของพระเยซูนั้น มีมารดาของพระองค์กับน้าสาวของพระองค์ มารีย์ภรรยาของเคลโอฟัส และมารีย์ชาวมักดาลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 26, 'ฉะนั้นเมื่อพระเยซูทอดพระเนตรเห็นมารดาของพระองค์ และสาวกคนที่พระองค์ทรงรักยืนอยู่ใกล้ พระองค์ตรัสกับมารดาของพระองค์ว่า “หญิงเอ๋ย จงดูบุตรของท่านเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 27, 'แล้วพระองค์ตรัสกับสาวกคนนั้นว่า “จงดูมารดาของท่านเถิด” และตั้งแต่เวลานั้นมา สาวกคนนั้นก็รับนางมาอยู่ในบ้านของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 28, 'หลังจากนั้นพระเยซูทรงทราบว่า ทุกสิ่งสําเร็จแล้ว เพื่อพระคัมภีร์จะสําเร็จจึงตรัสว่า “เรากระหายน้ํา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 29, 'มีภาชนะใส่น้ําองุ่นเปรี้ยววางอยู่ที่นั่น เขาจึงเอาฟองน้ํา ชุบน้ําองุ่นเปรี้ยวใส่ปลายไม้หุสบชูขึ้นให้ถึงพระโอษฐ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 30, 'เมื่อพระเยซูทรงรับน้ําองุ่นเปรี้ยวแล้ว พระองค์ตรัสว่า “สําเร็จแล้ว” และทรงก้มพระเศียรลงปล่อยพระวิญญาณจิตออกไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 31, 'เพราะวันนั้นเป็นวันเตรียม พวกยิวจึงขอให้ปีลาตทุบขาของผู้ที่ถูกตรึงให้หัก และให้เอาศพไปเสีย เพื่อไม่ให้ศพค้างอยู่ที่กางเขนในวันสะบาโต (เพราะวันสะบาโตนั้นเป็นวันใหญ่)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 32, 'ดังนั้นพวกทหารจึงมาทุบขาของคนที่หนึ่ง และขาของอีกคนหนึ่งที่ถูกตรึงอยู่กับพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 33, 'แต่เมื่อเขามาถึงพระเยซูและเห็นว่าพระองค์สิ้นพระชนม์แล้ว เขาจึงมิได้ทุบขาของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 34, 'แต่ทหารคนหนึ่งเอาทวนแทงที่สีข้างของพระองค์ และโลหิตกับน้ําก็ไหลออกมาทันที');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 35, 'คนนั้นที่เห็นก็เป็นพยาน และคําพยานของเขาก็เป็นความจริง และเขาก็รู้ว่าเขาพูดความจริง เพื่อท่านทั้งหลายจะได้เชื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 36, 'เพราะสิ่งเหล่านี้เกิดขึ้นเพื่อข้อพระคัมภีร์จะสําเร็จซึ่งว่า ‘พระอัฐิของพระองค์จะไม่หักสักซี่เดียว’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 37, 'และมีข้อพระคัมภีร์อีกข้อหนึ่งว่า ‘เขาทั้งหลายจะมองดูพระองค์ผู้ซึ่งเขาเองได้แทง’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 38, 'หลังจากนี้โยเซฟชาวบ้านอาริมาเธีย ซึ่งเป็นสาวกลับๆของพระเยซูเพราะกลัวพวกยิว ก็ได้ขอพระศพพระเยซูจากปีลาต และปีลาตก็ยอมให้ โยเซฟจึงมาอัญเชิญพระศพพระเยซูไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 39, 'ฝ่ายนิโคเดมัส ซึ่งตอนแรกไปหาพระเยซูในเวลากลางคืนนั้นก็มาด้วย เขานําเครื่องหอมผสม คือมดยอบกับกฤษณาหนักประมาณสามสิบกว่ากิโลกรัมมาด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 40, 'พวกเขาอัญเชิญพระศพพระเยซู และเอาผ้าป่านกับเครื่องหอมพันพระศพนั้นตามธรรมเนียมฝังศพของพวกยิว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 41, 'ในสถานที่พระองค์ถูกตรึงที่กางเขนนั้นมีสวนแห่งหนึ่ง ในสวนนั้นมีอุโมงค์ฝังศพใหม่ที่ยังไม่ได้ฝังศพผู้ใดเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 42, 'เพราะวันนั้นเป็นวันเตรียมของพวกยิว และเพราะอุโมงค์นั้นอยู่ใกล้ เขาจึงบรรจุพระศพพระเยซูไว้ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 1, 'วันแรกของสัปดาห์เวลาเช้ามืด มารีย์ชาวมักดาลามาถึงอุโมงค์ฝังศพ เธอเห็นหินออกจากปากอุโมงค์อยู่แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 2, 'เธอจึงวิ่งไปหาซีโมนเปโตรและสาวกอีกคนหนึ่งที่พระเยซูทรงรักนั้น และพูดกับเขาว่า “เขาเอาองค์พระผู้เป็นเจ้าออกไปจากอุโมงค์แล้ว และพวกเราไม่รู้ว่าเขาเอาพระองค์ไปไว้ที่ไหน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 3, 'เปโตรจึงออกไปยังอุโมงค์กับสาวกคนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 4, 'เขาจึงวิ่งไปทั้งสองคน แต่สาวกคนนั้นวิ่งเร็วกว่าเปโตรจึงมาถึงอุโมงค์ก่อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 5, 'เขาก้มลงมองดูเห็นผ้าป่านวางอยู่ แต่เขาไม่ได้เข้าไปข้างใน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 6, 'ซีโมนเปโตรตามมาถึงภายหลัง แล้วเข้าไปในอุโมงค์เห็นผ้าป่านวางอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 7, 'และผ้าพันพระเศียรของพระองค์ไม่ได้วางอยู่กับผ้าอื่น แต่พับไว้ต่างหาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 8, 'แล้วสาวกคนนั้นที่มาถึงอุโมงค์ก่อนก็เข้าไปด้วย เขาได้เห็นและเชื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 9, 'เพราะว่าขณะนั้นเขายังไม่เข้าใจข้อพระคัมภีร์ที่ว่า พระองค์จะต้องฟื้นขึ้นมาจากความตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 10, 'แล้วสาวกทั้งสองก็กลับไปยังบ้านของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 11, 'แต่ฝ่ายมารีย์ยืนร้องไห้อยู่นอกอุโมงค์ ขณะที่ร้องไห้อยู่เธอก้มลงมองดูที่อุโมงค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 12, 'และได้เห็นทูตสวรรค์สององค์สวมเสื้อขาวนั่งอยู่ ณ ที่ซึ่งเขาวางพระศพพระเยซู องค์หนึ่งอยู่เบื้องพระเศียร และองค์หนึ่งอยู่เบื้องพระบาท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 13, 'ทูตทั้งสองพูดกับมารีย์ว่า “หญิงเอ๋ย ร้องไห้ทําไม” เธอตอบทูตทั้งสองว่า “เพราะเขาเอาองค์พระผู้เป็นเจ้าของข้าพเจ้าไปเสียแล้ว และข้าพเจ้าไม่ทราบว่าเขาเอาพระองค์ไปไว้ที่ไหน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 14, 'เมื่อมารีย์พูดอย่างนั้นแล้ว ก็หันกลับมาและเห็นพระเยซูประทับยืนอยู่ แต่ไม่ทราบว่าเป็นองค์พระเยซู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 15, 'พระเยซูตรัสถามเธอว่า “หญิงเอ๋ย ร้องไห้ทําไม เจ้าตามหาผู้ใด” มารีย์สําคัญว่าพระองค์เป็นคนทําสวนจึงตอบพระองค์ว่า “นายเจ้าข้า ถ้าท่านได้เอาพระองค์ไป ขอบอกให้ดิฉันรู้ว่าเอาพระองค์ไปไว้ที่ไหน และดิฉันจะรับพระองค์ไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 16, 'พระเยซูตรัสกับเธอว่า “มารีย์เอ๋ย” มารีย์จึงหันมาและทูลพระองค์ว่า “รับโบนี” ซึ่งแปลว่า อาจารย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 17, 'พระเยซูตรัสกับเธอว่า “อย่าแตะต้องเรา เพราะเรายังมิได้ขึ้นไปหาพระบิดาของเรา แต่จงไปหาพวกพี่น้องของเรา และบอกเขาว่า เราจะขึ้นไปหาพระบิดาของเราและพระบิดาของท่านทั้งหลาย และไปหาพระเจ้าของเราและพระเจ้าของท่านทั้งหลาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 18, 'มารีย์มักดาลาจึงไปบอกพวกสาวกว่า เธอได้เห็นองค์พระผู้เป็นเจ้าแล้ว และพระองค์ได้ตรัสคําเหล่านั้นกับเธอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 19, 'ค่ําวันนั้นซึ่งเป็นวันแรกของสัปดาห์ เมื่อปิดประตูห้องที่พวกสาวกชุมนุมกันอยู่แล้วเพราะกลัวพวกยิว พระเยซูได้เสด็จเข้ามาประทับยืนอยู่ท่ามกลางเขา และตรัสกับเขาว่า “สันติสุขจงดํารงอยู่กับท่านทั้งหลายเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 20, 'ครั้นพระองค์ตรัสอย่างนั้นแล้ว พระองค์ทรงให้เขาดูพระหัตถ์และสีข้างของพระองค์ เมื่อพวกสาวกเห็นองค์พระผู้เป็นเจ้าแล้ว เขาก็มีความยินดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 21, 'พระเยซูจึงตรัสกับเขาอีกว่า “สันติสุขจงดํารงอยู่กับท่านทั้งหลายเถิด พระบิดาของเราทรงใช้เรามาฉันใด เราก็ใช้ท่านทั้งหลายไปฉันนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 22, 'ครั้นพระองค์ตรัสดังนั้นแล้วจึงทรงระบายลมหายใจออกเหนือเขา และตรัสกับเขาว่า “ท่านทั้งหลายจงรับพระวิญญาณบริสุทธิ์เถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 23, 'ถ้าท่านจะยกความผิดบาปของผู้ใด ความผิดบาปนั้นก็จะถูกยกเสีย และถ้าท่านจะให้ความผิดบาปติดอยู่กับผู้ใด ความผิดบาปก็จะติดอยู่กับผู้นั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 24, 'แต่ฝ่ายโธมัสที่เขาเรียกกันว่า ดิดุมัส ซึ่งเป็นสาวกคนหนึ่งในสิบสองคนนั้น ไม่ได้อยู่กับพวกเขาเมื่อพระเยซูเสด็จมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 25, 'สาวกอื่นๆจึงบอกโธมัสว่า “เราได้เห็นองค์พระผู้เป็นเจ้าแล้ว” แต่โธมัสตอบเขาเหล่านั้นว่า “ถ้าข้าไม่เห็นรอยตะปูที่พระหัตถ์ของพระองค์ และไม่ได้เอานิ้วของข้าแยงเข้าไปที่รอยตะปูนั้น และไม่ได้เอามือของข้าแยงเข้าไปที่สีข้างของพระองค์แล้ว ข้าจะไม่เชื่อเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 26, 'ครั้นล่วงไปแปดวันแล้ว เหล่าสาวกของพระองค์อยู่ด้วยกันข้างในอีก และโธมัสก็อยู่กับพวกเขาด้วย ประตูปิดแล้ว พระเยซูเสด็จเข้ามาและประทับยืนอยู่ท่ามกลางเขาและตรัสว่า “สันติสุขจงดํารงอยู่กับท่านทั้งหลายเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 27, 'แล้วพระองค์ตรัสกับโธมัสว่า “จงยื่นนิ้วมาที่นี่และดูมือของเรา จงยื่นมือออกคลําที่สีข้างของเรา อย่าขาดความเชื่อเลย แต่จงเชื่อเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 28, 'โธมัสทูลตอบพระองค์ว่า “องค์พระผู้เป็นเจ้าของข้าพระองค์ และพระเจ้าของข้าพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 29, 'พระเยซูตรัสกับเขาว่า “โธมัสเอ๋ย เพราะท่านได้เห็นเราท่านจึงเชื่อ ผู้ที่ไม่เห็นเราแต่เชื่อก็เป็นสุข”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 30, 'พระเยซูได้ทรงกระทําหมายสําคัญอื่นๆอีกหลายประการต่อหน้าเหล่าสาวกของพระองค์ ซึ่งไม่ได้จดไว้ในหนังสือม้วนนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 31, 'แต่การที่ได้จดเหตุการณ์เหล่านี้ไว้ก็เพื่อท่านทั้งหลายจะได้เชื่อว่า พระเยซูทรงเป็นพระคริสต์พระบุตรของพระเจ้า และเมื่อมีความเชื่อแล้ว ท่านก็จะมีชีวิตโดยพระนามของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 1, 'ภายหลังเหตุการณ์เหล่านี้พระเยซูได้ทรงสําแดงพระองค์แก่เหล่าสาวกอีกครั้งหนึ่งที่ทะเลทิเบเรียส และพระองค์ทรงสําแดงพระองค์อย่างนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 2, 'คือ ซีโมนเปโตร โธมัสที่เรียกว่า ดิดุมัส และนาธานาเอลชาวบ้านคานาแคว้นกาลิลี และบุตรชายทั้งสองของเศเบดี และสาวกของพระองค์อีกสองคนกําลังอยู่ด้วยกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 3, 'ซีโมนเปโตรบอกเขาว่า “ข้าจะไปจับปลา” เขาทั้งหลายจึงพูดกับท่านว่า “เราจะไปกับท่านด้วย” เขาก็ออกไปลงเรือทันที แต่คืนนั้นเขาจับปลาไม่ได้เลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 4, 'แต่ครั้นรุ่งเช้าพระเยซูประทับยืนอยู่ที่ฝั่ง แต่เหล่าสาวกไม่รู้ว่าเป็นพระเยซู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 5, 'พระเยซูจึงตรัสถามเขาว่า “ลูกเอ๋ย มีอาหารบ้างหรือเปล่า” เขาทูลตอบพระองค์ว่า “ไม่มี”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 6, 'พระองค์ตรัสกับเขาทั้งหลายว่า “จงทอดอวนลงทางด้านขวาเรือเถิด แล้วจะได้ปลาบ้าง” เขาจึงทอดอวนลงและได้ปลาเป็นอันมากจนลากอวนขึ้นไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 7, 'สาวกคนที่พระเยซูทรงรักจึงบอกเปโตรว่า “เป็นองค์พระผู้เป็นเจ้า” เมื่อซีโมนเปโตรได้ยินว่าเป็นองค์พระผู้เป็นเจ้า เขาก็หยิบเสื้อคลุมชาวประมงของเขามาสวมรัดไว้ (เพราะเขาเปลือยเปล่าอยู่) แล้วก็กระโดดลงทะเล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 8, 'แต่สาวกอื่นๆนั้นนั่งเรือเล็กๆมา ลากอวนที่ติดปลาเต็มนั้นมาด้วย (เพราะเขาอยู่ไม่ห่างจากฝั่งนัก ไกลประมาณหนึ่งร้อยเมตรเท่านั้น)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 9, 'เมื่อเขาขึ้นมาบนฝั่ง เขาก็เห็นถ่านติดไฟอยู่ และมีปลาวางอยู่ข้างบนและมีขนมปัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 10, 'พระเยซูตรัสกับเขาทั้งหลายว่า “เอาปลาที่ได้เมื่อกี้นี้มาบ้าง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 11, 'ซีโมนเปโตรจึงไปลากอวนขึ้นฝั่ง อวนติดปลาใหญ่เต็ม มีหนึ่งร้อยห้าสิบสามตัว และถึงมากอย่างนั้นอวนก็ไม่ขาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 12, 'พระเยซูตรัสกับเขาทั้งหลายว่า “เชิญมารับประทานอาหารกันเถิด” และในพวกสาวกไม่มีใครกล้าถามพระองค์ว่า “ท่านคือผู้ใด” เพราะเขารู้อยู่ว่าเป็นองค์พระผู้เป็นเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 13, 'พระเยซูทรงเข้ามาหยิบขนมปังแจกให้เขาและทรงหยิบปลาแจกด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 14, 'นี่เป็นครั้งที่สามที่พระเยซูทรงสําแดงพระองค์แก่พวกสาวกของพระองค์ หลังจากที่พระองค์ทรงคืนพระชนม์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 15, 'เมื่อรับประทานอาหารเสร็จแล้วพระเยซูตรัสกับซีโมนเปโตรว่า “ซีโมนบุตรชายโยนาห์เอ๋ย ท่านรักเรามากกว่าพวกเหล่านี้หรือ” เขาทูลตอบพระองค์ว่า “ถูกแล้ว พระองค์เจ้าข้า พระองค์ทรงทราบว่าข้าพระองค์รักพระองค์” พระองค์ตรัสสั่งเขาว่า “จงเลี้ยงลูกแกะของเราเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 16, 'พระองค์ตรัสกับเขาครั้งที่สองอีกว่า “ซีโมนบุตรชายโยนาห์เอ๋ย ท่านรักเราหรือ” เขาทูลตอบพระองค์ว่า “ถูกแล้ว พระองค์เจ้าข้า พระองค์ทรงทราบว่าข้าพระองค์รักพระองค์” พระองค์ตรัสกับเขาว่า “จงเลี้ยงแกะของเราเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 17, 'พระองค์ตรัสกับเขาครั้งที่สามว่า “ซีโมนบุตรชายโยนาห์เอ๋ย ท่านรักเราหรือ” เปโตรก็เป็นทุกข์ใจที่พระองค์ตรัสถามเขาครั้งที่สามว่า “ท่านรักเราหรือ” และเขาทูลพระองค์ว่า “พระองค์เจ้าข้า พระองค์ทรงทราบทุกสิ่ง พระองค์ทรงทราบว่า ข้าพระองค์รักพระองค์” พระเยซูตรัสกับเขาว่า “จงเลี้ยงแกะของเราเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 18, 'เราบอกความจริงแก่ท่านว่า เมื่อท่านยังหนุ่มท่านคาดเอวเอง และเดินไปไหนๆตามที่ท่านปรารถนา แต่เมื่อท่านแก่แล้วท่านจะเหยียดมือของท่านออก และคนอื่นจะคาดเอวท่าน และพาท่านไปที่ที่ท่านไม่ปรารถนาจะไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 19, 'ที่พระองค์ตรัสอย่างนั้นเพื่อแสดงว่า เปโตรจะถวายเกียรติแด่พระเจ้าด้วยความตายอย่างไร ครั้นพระองค์ตรัสอย่างนั้นแล้วจึงสั่งเปโตรว่า “จงตามเรามาเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 20, 'เปโตรเหลียวหลังเห็นสาวกคนที่พระเยซูทรงรักตามมา คือสาวกที่เอนตัวลงที่พระทรวงของพระองค์เมื่อรับประทานอาหารเย็นอยู่นั้น และทูลถามว่า “พระองค์เจ้าข้า ผู้ที่จะทรยศพระองค์คือใคร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 21, 'เมื่อเปโตรเห็นสาวกคนนั้นจึงทูลถามพระเยซูว่า “พระองค์เจ้าข้า คนนี้จะเป็นอย่างไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 22, 'พระเยซูตรัสกับเขาว่า “ถ้าเราอยากจะให้เขาอยู่จนเรามานั้น จะเป็นเรื่องอะไรของท่านเล่า ท่านจงตามเรามาเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 23, 'เหตุฉะนั้นคําที่ว่า สาวกคนนั้นจะไม่ตาย จึงลือไปท่ามกลางพวกพี่น้อง แต่พระเยซูมิได้ตรัสแก่เขาว่า “สาวกคนนั้นจะไม่ตาย” แต่ตรัสว่า “ถ้าเราอยากจะให้เขาอยู่จนเรามานั้น จะเป็นเรื่องอะไรของท่านเล่า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 24, 'สาวกคนนี้แหละ ที่เป็นพยานถึงเหตุการณ์เหล่านี้และเป็นผู้ที่เขียนสิ่งเหล่านี้ไว้ และเราทราบว่าคําพยานของเขาเป็นความจริง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 25, 'มีอีกหลายสิ่งที่พระเยซูได้ทรงกระทํา ถ้าจะเขียนไว้ให้หมดทุกสิ่ง ข้าพเจ้าคาดว่า แม้หมดทั้งโลกก็น่าจะไม่พอไว้หนังสือที่จะเขียนนั้น เอเมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 1, 'โอ ท่านเธโอฟีลัส ในหนังสือเรื่องแรกนั้น ข้าพเจ้าได้กล่าวแล้วถึงบรรดาการซึ่งพระเยซูได้ทรงตั้งต้นกระทําและสั่งสอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 2, 'จนถึงวันที่พระองค์ทรงถูกรับขึ้นไป ในเมื่อได้ตรัสสั่งโดยเดชพระวิญญาณบริสุทธิ์แก่อัครสาวก ซึ่งพระองค์ทรงเลือกไว้แล้วนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 3, 'ครั้นพระองค์ทรงทนทุกข์ทรมานแล้ว ได้ทรงแสดงพระองค์แก่คนพวกนั้น ด้วยหลักฐานหลายอย่าง พิสูจน์อย่างแน่นอนที่สุดว่าพระองค์ทรงพระชนม์อยู่ และได้ทรงปรากฏแก่เขาทั้งหลายถึงสี่สิบวัน และได้ทรงกล่าวถึงเรื่องอาณาจักรของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 4, 'เมื่อพระองค์ได้ทรงชุมนุมกันกับอัครสาวก จึงกําชับเขามิให้ออกไปจากกรุงเยรูซาเล็ม แต่ให้คอยรับตามพระสัญญาของพระบิดา คือพระองค์ตรัสว่า “ตามที่ท่านทั้งหลายได้ยินจากเรานั่นแหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 5, 'เพราะว่ายอห์นให้รับบัพติศมาด้วยน้ําก็จริง แต่ไม่ช้าไม่นานท่านทั้งหลายจะรับบัพติศมาด้วยพระวิญญาณบริสุทธิ์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 6, 'เมื่อเขาทั้งหลายได้ประชุมพร้อมกัน เขาจึงทูลถามพระองค์ว่า “พระองค์เจ้าข้า พระองค์จะทรงตั้งราชอาณาจักรขึ้นใหม่ให้แก่อิสราเอลในครั้งนี้หรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 7, 'พระองค์ตรัสตอบเขาว่า “ไม่ใช่ธุระของท่านที่จะรู้เวลาและวาระซึ่งพระบิดาได้ทรงกําหนดไว้โดยสิทธิอํานาจของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 8, 'แต่ท่านทั้งหลายจะได้รับพระราชทานฤทธิ์เดช เมื่อพระวิญญาณบริสุทธิ์จะเสด็จมาเหนือท่าน และท่านทั้งหลายจะเป็นพยานฝ่ายเราทั้งในกรุงเยรูซาเล็ม ทั่วแคว้นยูเดีย แคว้นสะมาเรีย และจนถึงที่สุดปลายแผ่นดินโลก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 9, 'เมื่อพระองค์ตรัสเช่นนั้นแล้ว ในขณะที่เขาทั้งหลายกําลังพินิจดู พระองค์ก็ถูกรับขึ้นไป และมีเมฆคลุมพระองค์ให้พ้นสายตาของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 10, 'เมื่อเขากําลังเขม้นดูฟ้าเวลาที่พระองค์เสด็จขึ้นไปนั้น ดูเถิด มีชายสองคนสวมเสื้อขาวมายืนอยู่ข้างๆเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 11, 'สองคนนั้นกล่าวว่า “ชาวกาลิลีเอ๋ย เหตุไฉนท่านจึงยืนเขม้นดูฟ้าสวรรค์ พระเยซูองค์นี้ซึ่งทรงรับไปจากท่านขึ้นไปยังสวรรค์นั้น จะเสด็จมาอีกเหมือนอย่างที่ท่านทั้งหลายได้เห็นพระองค์เสด็จไปยังสวรรค์นั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 12, 'แล้วอัครสาวกจึงลงจากภูเขามะกอกเทศ ซึ่งอยู่ใกล้กรุงเยรูซาเล็มระยะทางเท่ากับระยะที่อนุญาตให้คนเดินในวันสะบาโต กลับไปกรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 13, 'เมื่อเข้ากรุงแล้วเขาเหล่านั้นจึงขึ้นไปยังห้องชั้นบน ซึ่งมีทั้งเปโตร ยากอบ ยอห์นกับอันดรูว์ ฟีลิปกับโธมัส บารโธโลมิวกับมัทธิว ยากอบบุตรชายอัลเฟอัส ซีโมนเศโลเท กับยูดาสน้องชายของยากอบ พักอยู่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 14, 'พวกเขาร่วมใจกันอธิษฐานอ้อนวอนต่อเนื่องพร้อมกับพวกผู้หญิง และมารีย์มารดาของพระเยซูและพวกน้องชายของพระองค์ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 15, 'คราวนั้นเปโตรจึงได้ยืนขึ้นท่ามกลางเหล่าสาวก (ที่ประชุมกันอยู่นั้นมีรวมทั้งสิ้นประมาณร้อยยี่สิบชื่อ) และกล่าวว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 16, '“ท่านพี่น้องทั้งหลาย จําเป็นจะต้องสําเร็จตามพระคัมภีร์ ซึ่งพระวิญญาณบริสุทธิ์ได้ตรัสไว้โดยโอษฐ์ของดาวิด ด้วยเรื่องยูดาส ซึ่งเป็นผู้นําทางคนที่ไปจับพระเยซู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 17, 'เพราะยูดาสนั้นได้นับเข้าในพวกเรา และได้รับส่วนในภารกิจนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 18, 'ฝ่ายผู้นี้ได้เอาบําเหน็จแห่งการชั่วช้าของตนไปซื้อที่ดิน แล้วก็ล้มคะมําลงแตกกลางตัวไส้พุงทะลักออกมาหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 19, 'เหตุการณ์นี้คนทั้งปวงที่อยู่ในกรุงเยรูซาเล็มก็รู้ เขาจึงเรียกที่ดินแปลงนั้นตามภาษาของเขาว่า อาเคลดามา คือทุ่งโลหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 20, 'ด้วยมีคําเขียนไว้ในหนังสือสดุดีว่า ‘ขอให้ที่อาศัยของเขารกร้างและอย่าให้ผู้ใดอาศัยอยู่ที่นั่น’ และ ‘ขอให้อีกผู้หนึ่งมายึดตําแหน่งของเขา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 21, 'เหตุฉะนั้นในบรรดาชายเหล่านี้ที่เป็นพวกเดียวกับเราเสมอตลอดเวลาที่พระเยซูเจ้าได้เสด็จเข้าออกกับเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 22, 'คือตั้งแต่บัพติศมาของยอห์น จนถึงวันที่พระองค์ทรงถูกรับขึ้นไปจากเรา คนหนึ่งในพวกนี้จะต้องตั้งไว้ให้เป็นพยานกับเราถึงการคืนพระชนม์ของพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 23, 'เขาทั้งหลายจึงเสนอชื่อคนสองคน คือโยเซฟที่เรียกว่าบารซับบาส มีนามสกุลว่ายุสทัส และมัทธีอัส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 24, 'แล้วพวกสาวกจึงอธิษฐานว่า “พระองค์เจ้าข้า ผู้ทรงทราบใจของมนุษย์ทั้งปวง ขอทรงสําแดงว่าในสองคนนี้พระองค์ทรงเลือกคนไหน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 25, 'ให้รับส่วนในการปรนนิบัตินี้ และรับตําแหน่งเป็นอัครสาวกแทนยูดาส ซึ่งโดยการละเมิดนั้นได้หลงจากหน้าที่ไปยังที่ของตน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 26, 'เขาทั้งหลายจึงจับฉลากกัน และฉลากนั้นได้แก่มัทธีอัสจึงนับเขาเข้ากับอัครสาวกสิบเอ็ดคนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 1, 'เมื่อวันเทศกาลเพ็นเทคอสต์มาถึง จําพวกสาวกจึงมาร่วมใจกันอยู่ในที่แห่งเดียวกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 2, 'ในทันใดนั้น มีเสียงดังมาจากฟ้าเหมือนเสียงพายุกล้าสั่นก้องทั่วบ้านที่เขานั่งอยู่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 3, 'มีเปลวไฟสัณฐานเหมือนลิ้นปรากฏแก่เขา และกระจายอยู่บนเขาสิ้นทุกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 4, 'เขาเหล่านั้นก็ประกอบด้วยพระวิญญาณบริสุทธิ์จึงตั้งต้นพูดภาษาต่างๆตามที่พระวิญญาณทรงโปรดให้พูด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 5, 'มีพวกยิวจากทุกประเทศทั่วใต้ฟ้า ซึ่งเป็นผู้เกรงกลัวพระเจ้ามาอยู่ในกรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 6, 'เมื่อมีเสียงอย่างนั้น เขาจึงพากันมาและสับสนเพราะต่างคนต่างได้ยินเขาพูดภาษาของตนเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 7, 'คนทั้งปวงจึงประหลาดและอัศจรรย์ใจพูดกันว่า “ดูเถิด คนทั้งหลายที่พูดกันนั้นเป็นชาวกาลิลีทุกคนไม่ใช่หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 8, 'เหตุไฉนเราทุกคนได้ยินเขาพูดภาษาของบ้านเกิดเมืองนอนของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 9, 'เช่นชาวปารเธียและมีเดีย ชาวเอลามและคนที่อยู่ในเขตแดนเมโสโปเตเมีย และแคว้นยูเดียและแคว้นคัปปาโดเซีย ในแคว้นปอนทัสและเอเชีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 10, 'ในแคว้นฟรีเจีย แคว้นปัมฟีเลียและประเทศอียิปต์ ในแคว้นเมืองลิเบียซึ่งขึ้นกับนครไซรีน และคนมาจากกรุงโรม ทั้งพวกยิวกับคนเข้าจารีตยิว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 11, 'ชาวเกาะครีตและชาวอาระเบีย เราทั้งหลายต่างก็ได้ยินคนเหล่านี้กล่าวถึงมหกิจของพระเจ้าตามภาษาของเราเอง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 12, 'เขาทั้งหลายจึงอัศจรรย์ใจและฉงนสนเท่ห์พูดกันว่า “นี่อะไรกัน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 13, 'แต่บางคนเยาะเย้ยว่า “คนเหล่านั้นเมาเหล้าองุ่นใหม่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 14, 'ฝ่ายเปโตรได้ยืนขึ้นกับอัครสาวกสิบเอ็ดคน และได้กล่าวแก่คนทั้งปวงด้วยเสียงอันดังว่า “ท่านชาวยูเดียและบรรดาคนที่อยู่ในกรุงเยรูซาเล็ม จงทราบเรื่องนี้ และฟังถ้อยคําของข้าพเจ้าเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 15, 'ด้วยว่าคนเหล่านี้มิได้เมาเหล้าองุ่นเหมือนอย่างที่ท่านคิดนั้น เพราะว่าเป็นเวลาสามโมงเช้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 16, 'แต่เหตุการณ์นี้เกิดขึ้นตามคําซึ่งโยเอลศาสดาพยากรณ์ได้กล่าวไว้ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 17, '‘พระเจ้าตรัสว่า ต่อมาในวันสุดท้าย เราจะเทพระวิญญาณของเรามาเหนือเนื้อหนังทั้งปวง บุตรชายบุตรสาวของท่านจะพยากรณ์ คนหนุ่มของท่านจะเห็นนิมิต และคนแก่จะฝันเห็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 18, 'ในคราวนั้นเราจะเทพระวิญญาณของเราบนทาสและทาสีของเรา และคนเหล่านั้นจะพยากรณ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 19, 'เราจะสําแดงการมหัศจรรย์ในอากาศเบื้องบนและหมายสําคัญที่แผ่นดินเบื้องล่างเป็นเลือด ไฟและไอควัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 20, 'ดวงอาทิตย์จะมืดไปและดวงจันทร์จะกลับเป็นเลือด ก่อนถึงวันใหญ่นั้น คือวันใหญ่ยิ่งขององค์พระผู้เป็นเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 21, 'และจะเป็นเช่นนี้คือผู้ใดที่จะร้องออกพระนามขององค์พระผู้เป็นเจ้าก็จะรอด’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 22, 'ท่านทั้งหลายผู้เป็นชนชาติอิสราเอล ขอฟังคําเหล่านี้เถิด คือพระเยซูชาวนาซาเร็ธ เป็นผู้ที่พระเจ้าทรงโปรดชี้แจงให้ท่านทั้งหลายทราบโดยการอัศจรรย์ การมหัศจรรย์และหมายสําคัญต่างๆ ซึ่งพระเจ้าได้ทรงกระทําโดยพระองค์นั้น ท่ามกลางท่านทั้งหลาย ดังที่ท่านทราบอยู่แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 23, 'พระองค์นี้ทรงถูกมอบไว้ตามที่พระเจ้าได้ทรงดําริแน่นอนล่วงหน้าไว้ก่อน ท่านทั้งหลายได้จับ และโดยมืออันชั่วร้ายได้ตรึงที่กางเขนและประหารชีวิตเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 24, 'พระเจ้าได้ทรงบันดาลให้พระองค์คืนพระชนม์ ด้วยทรงกําจัดความเจ็บปวดแห่งความตายเสีย เพราะว่าความตายจะครอบงําพระองค์ไว้ไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 25, 'เพราะดาวิดได้ทรงกล่าวถึงพระองค์ว่า ‘ข้าพเจ้าได้เห็นองค์พระผู้เป็นเจ้าตรงหน้าข้าพเจ้าเสมอ เพราะว่าพระองค์ประทับที่มือขวาของข้าพเจ้า เพื่อข้าพเจ้าจะมิได้หวั่นไหว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 26, 'เพราะฉะนั้นจิตใจของข้าพเจ้าจึงยินดี และลิ้นของข้าพเจ้าจึงเปรมปรีดิ์ ยิ่งกว่านี้เนื้อหนังของข้าพเจ้าจะพักพิงอยู่ในความหวังใจด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 27, 'เพราะพระองค์จะไม่ทรงทิ้งจิตวิญญาณของข้าพระองค์ไว้ในนรก ทั้งจะไม่ทรงให้องค์บริสุทธิ์ของพระองค์เปื่อยเน่าไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 28, 'พระองค์ได้ทรงโปรดให้ข้าพระองค์ทราบทางแห่งชีวิตแล้ว พระองค์จะทรงโปรดให้ข้าพระองค์มีความยินดีเต็มเปี่ยมด้วยสีพระพักตร์อันชอบพระทัยของพระองค์’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 29, 'ท่านพี่น้องทั้งหลาย ข้าพเจ้ามีใจกล้าที่จะกล่าวแก่ท่านทั้งหลายถึงดาวิดบรรพบุรุษของเราว่า ท่านสิ้นพระชนม์แล้วถูกฝังไว้ และอุโมงค์ฝังศพของท่านยังอยู่กับเราจนถึงทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 30, 'ท่านเป็นศาสดาพยากรณ์และทราบว่าพระเจ้าตรัสสัญญาไว้แก่ท่านด้วยพระปฏิญาณว่า พระองค์จะทรงประทานผู้หนึ่งจากบั้นเอวของท่าน และตามเนื้อหนังนั้น พระองค์จะทรงยกพระคริสต์ให้ประทับบนพระที่นั่งของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 31, 'ดาวิดก็ทรงล่วงรู้เหตุการณ์นี้ก่อน จึงทรงกล่าวถึงการคืนพระชนม์ของพระคริสต์ว่า จิตวิญญาณของพระองค์ไม่ต้องละไว้ในนรก ทั้งพระมังสะของพระองค์ก็ไม่เปื่อยเน่าไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 32, 'พระเยซูนี้พระเจ้าได้ทรงบันดาลให้คืนพระชนม์แล้ว ข้าพเจ้าทั้งหลายเป็นพยานในข้อนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 33, 'เหตุฉะนั้นเมื่อพระหัตถ์เบื้องขวาของพระเจ้าได้ทรงตั้งพระองค์ขึ้น และครั้นพระองค์ได้ทรงรับพระวิญญาณบริสุทธิ์จากพระบิดาตามพระสัญญา พระองค์ได้ทรงเทฤทธิ์เดชนี้ลงมา ซึ่งตอนนี้ท่านทั้งหลายได้ยินและเห็นแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 34, 'เหตุว่าท่านดาวิดไม่ได้ขึ้นไปยังสวรรค์ แต่ท่านได้กล่าวว่า ‘องค์พระผู้เป็นเจ้าตรัสกับองค์พระผู้เป็นเจ้าของข้าพเจ้าว่า จงนั่งที่ขวามือของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 35, 'จนกว่าเราจะกระทําให้ศัตรูของท่านเป็นแท่นรองเท้าของท่าน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 36, 'เหตุฉะนั้นให้วงศ์วานอิสราเอลทั้งปวงทราบแน่นอนว่า พระเจ้าได้ทรงยกพระเยซูนี้ ซึ่งท่านทั้งหลายได้ตรึงไว้ที่กางเขน ทรงตั้งขึ้นให้เป็นทั้งองค์พระผู้เป็นเจ้าและเป็นพระคริสต์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 37, 'เมื่อคนทั้งหลายได้ยินแล้วก็รู้สึกแปลบปลาบใจ จึงกล่าวแก่เปโตรและอัครสาวกอื่นๆว่า “ท่านพี่น้องทั้งหลาย เราจะทําอย่างไรดี”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 38, 'ฝ่ายเปโตรจึงกล่าวแก่เขาว่า “จงกลับใจเสียใหม่และรับบัพติศมาในพระนามแห่งพระเยซูคริสต์สิ้นทุกคน เพราะว่าพระเจ้าทรงยกความผิดบาปของท่านเสีย และท่านจะได้รับของประทานของพระวิญญาณบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 39, 'ด้วยว่าพระสัญญานั้นตกแก่ท่านทั้งหลายกับลูกหลานของท่านด้วย และแก่คนทั้งหลายที่อยู่ไกล คือทุกคนที่องค์พระผู้เป็นเจ้าพระเจ้าของเราทรงเรียกมาเฝ้าพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 40, 'เปโตรจึงกล่าวอีกหลายคําเป็นพยานและได้เตือนสติเขาว่า “จงเอาตัวรอดจากยุคที่คดโกงนี้เถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 41, 'คนทั้งหลายที่รับคําของเปโตรด้วยความยินดีก็รับบัพติศมา ในวันนั้นมีคนเข้าเป็นสาวกเพิ่มอีกประมาณสามพันคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 42, 'เขาทั้งหลายได้ตั้งมั่นคงอยู่ในคําสอนของจําพวกอัครสาวก และในการสามัคคีธรรม และในการหักขนมปัง และในการอธิษฐาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 43, 'เขามีความเกรงกลัวด้วยกันทุกคน และพวกอัครสาวกทําการมหัศจรรย์และหมายสําคัญหลายประการ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 44, 'บรรดาผู้ที่เชื่อถือนั้นก็อยู่พร้อมกัน ณ ที่แห่งเดียว และทรัพย์สิ่งของของเขาเหล่านั้นเขาเอามารวมกันเป็นของกลาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 45, 'เขาจึงได้ขายทรัพย์สมบัติและสิ่งของมาแบ่งให้แก่คนทั้งปวงตามซึ่งทุกคนต้องการ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 46, 'เขาได้ร่วมใจกันไปในพระวิหาร และหักขนมปังตามบ้านของเขาร่วมรับประทานอาหารด้วยความชื่นชมยินดีและด้วยจริงใจ ทุกวันเรื่อยไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 47, 'ทั้งได้สรรเสริญพระเจ้าและคนทั้งปวงก็ชอบใจ ฝ่ายองค์พระผู้เป็นเจ้าได้ทรงโปรดให้ผู้ที่กําลังจะรอด เข้าสมทบกับคริสตจักรทวีขึ้นทุกๆวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 1, 'ฝ่ายเปโตรกับยอห์นกําลังขึ้นไปจะเข้าพระวิหารในเวลาอธิษฐาน เป็นเวลาบ่ายสามโมง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 2, 'มีชายคนหนึ่งเป็นง่อยตั้งแต่ครรภ์มารดา ทุกวันคนเคยหามเขามาวางไว้ริมประตูพระวิหาร ซึ่งมีชื่อว่าประตูงาม เพื่อให้ขอทานจากคนที่จะเข้าไปในพระวิหาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 3, 'คนนั้นพอเห็นเปโตรกับยอห์นจะเข้าไปในพระวิหารก็ขอทาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 4, 'ฝ่ายเปโตรกับยอห์นเพ่งดูเขาบอกว่า “จงดูพวกเราเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 5, 'คนขอทานนั้นได้เขม้นดู คาดว่าจะได้อะไรจากท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 6, 'เปโตรกล่าวว่า “เงินและทองข้าพเจ้าไม่มี แต่ที่ข้าพเจ้ามีอยู่ข้าพเจ้าจะให้ท่าน คือในพระนามแห่งพระเยซูคริสต์ชาวนาซาเร็ธ จงลุกขึ้นเดินไปเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 7, 'แล้วเปโตรจับมือขวาของเขาพยุงขึ้น และในทันใดนั้นเท้าและข้อเท้าของเขาก็มีกําลัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 8, 'เขาจึงกระโดดขึ้นยืนและเดินเข้าไปในพระวิหารด้วยกันกับเปโตรและยอห์น เดินเต้นโลดสรรเสริญพระเจ้าไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 9, 'คนทั้งปวงเห็นเขาเดินและสรรเสริญพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 10, 'จึงรู้ว่าเป็นคนนั้นซึ่งนั่งขอทานอยู่ที่ประตูงามแห่งพระวิหาร เขาจึงพากันมีความประหลาดและอัศจรรย์ใจอย่างยิ่งในเหตุการณ์ที่เกิดแก่คนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 11, 'เมื่อคนง่อยที่หายนั้นยังยึดเปโตรและยอห์นอยู่ ฝูงคนก็วิ่งไปหาท่านที่เฉลียงพระวิหารซึ่งเรียกว่า เฉลียงของซาโลมอน ด้วยความอัศจรรย์ใจยิ่งนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 12, 'พอเปโตรแลเห็นก็กล่าวแก่คนเหล่านั้นว่า “ท่านชนชาติอิสราเอลทั้งหลาย ไฉนท่านพากันประหลาดใจด้วยคนนี้ เขม้นดูเราทําไมเล่า อย่างกับว่าเราทําให้คนนี้เดินได้โดยฤทธิ์หรือความบริสุทธิ์ของเราเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 13, 'พระเจ้าของอับราฮัม อิสอัค และยาโคบ คือพระเจ้าแห่งบรรพบุรุษของเรา ได้ทรงโปรดประทานพระเกียรติแด่พระเยซูพระบุตรของพระองค์ ผู้ซึ่งท่านทั้งหลายได้มอบไว้แล้ว และได้ปฏิเสธพระองค์ต่อหน้าปีลาต เมื่อเขาตั้งใจจะปล่อยพระองค์ไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 14, 'แต่ท่านทั้งหลายได้ปฏิเสธพระองค์ซึ่งเป็นองค์บริสุทธิ์และชอบธรรม และได้ขอให้เขาปล่อยฆาตกรให้ท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 15, 'จึงฆ่าพระองค์ผู้ทรงเป็นเจ้าชีวิตเสีย ผู้ซึ่งพระเจ้าได้ทรงโปรดให้เป็นขึ้นมาจากความตาย เราเป็นพยานในเรื่องนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 16, 'โดยความเชื่อในพระนามของพระองค์ พระนามนั้นจึงได้กระทําให้คนนี้ซึ่งท่านทั้งหลายเห็นและรู้จักมีกําลังขึ้น คือความเชื่อซึ่งเป็นไปโดยพระองค์ได้กระทําให้คนนี้หายปกติต่อหน้าท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 17, 'พี่น้องทั้งหลาย ข้าพเจ้าทราบว่าท่านทั้งหลายได้กระทําการนั้นเพราะไม่รู้เรื่องราวอะไร ทั้งคณะผู้ครอบครองของท่านก็ทําเหมือนกันด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 18, 'แต่ว่าเหตุการณ์เหล่านั้น ซึ่งพระเจ้าได้ทรงประกาศไว้ล่วงหน้าโดยปากของศาสดาพยากรณ์ทั้งหลายของพระองค์ว่า พระคริสต์ต้องทนทุกข์ทรมาน พระองค์จึงทรงให้สําเร็จตามนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 19, 'เหตุฉะนั้นท่านทั้งหลายจงหันกลับและตั้งใจใหม่ เพื่อจะทรงลบล้างความผิดบาปของท่านเสีย เพื่อเวลาชื่นใจยินดีจะได้มาจากพระพักตร์ขององค์พระผู้เป็นเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 20, 'และเพื่อพระองค์จะได้ทรงใช้พระเยซูคริสต์ ผู้ซึ่งเมื่อก่อนนั้นได้แจ้งไว้แก่ท่านทั้งหลายแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 21, 'พระองค์นั้น สวรรค์จะต้องรับไว้จนถึงวาระเมื่อสิ่งสารพัดจะตั้งขึ้นใหม่ ตามซึ่งพระเจ้าได้ตรัสไว้โดยปากบรรดาศาสดาพยากรณ์บริสุทธิ์ของพระองค์ ตั้งแต่เริ่มสร้างโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 22, 'ที่จริงโมเสสได้กล่าวไว้แก่บรรพบุรุษว่า ‘องค์พระผู้เป็นเจ้า ผู้เป็นพระเจ้าของท่านทั้งหลายจะทรงโปรดประทานศาสดาพยากรณ์ผู้หนึ่ง เหมือนอย่างเราให้แก่ท่านจากจําพวกพี่น้องของท่าน ท่านทั้งหลายจงตั้งใจฟังผู้นั้นในสิ่งสารพัดซึ่งพระองค์จะได้ตรัสแก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 23, 'และจะเป็นเช่นนี้คือถ้าผู้หนึ่งผู้ใดไม่ตั้งใจฟังศาสดาพยากรณ์ผู้นั้น เขาจะต้องถูกตัดขาดให้พินาศไปจากท่ามกลางประชาชน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 24, 'และบรรดาศาสดาพยากรณ์ ตั้งแต่ซามูเอลเป็นลําดับมาก็กล่าวเป็นเสียงเดียวกันพยากรณ์ถึงกาลครั้งนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 25, 'ท่านทั้งหลายเป็นลูกหลานของศาสดาพยากรณ์นั้น และของพันธสัญญาซึ่งพระเจ้าได้ทรงกระทําไว้กับบรรพบุรุษของเรา คือได้ตรัสแก่อับราฮัมว่า ‘บรรดาครอบครัวทั่วแผ่นดินโลกจะได้รับพระพรเพราะเชื้อสายของเจ้า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 26, 'ครั้นพระเจ้าทรงโปรดให้พระเยซูพระบุตรของพระองค์เป็นขึ้นแล้ว จึงทรงใช้พระองค์มายังท่านทั้งหลายก่อน เพื่ออวยพระพรแก่ท่านทั้งหลาย โดยให้ท่านทั้งหลายทุกคนกลับจากความชั่วช้าของตน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 1, 'ขณะที่เปโตรกับยอห์นยังกล่าวแก่คนทั้งปวงอยู่ ปุโรหิตทั้งหลายกับนายทหารรักษาพระวิหารและพวกสะดูสีมาหาท่านทั้งสอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 2, 'ด้วยเขาเป็นทุกข์ร้อนใจ เพราะท่านทั้งสองได้สั่งสอน และประกาศแก่คนทั้งหลายถึงเรื่องการเป็นขึ้นมาจากความตาย โดยทางพระเยซู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 3, 'เขาจึงจับท่านทั้งสองจําไว้ในคุกจนวันรุ่งขึ้น เพราะว่าเย็นแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 4, 'แต่คนเป็นอันมากที่ได้ฟังคําสอนนั้นก็เชื่อ ซึ่งนับแต่ผู้ชายได้ประมาณห้าพันคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 5, 'ต่อมาครั้นรุ่งขึ้นพวกผู้ครอบครองกับพวกผู้ใหญ่และพวกธรรมาจารย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 6, 'ทั้งอันนาสมหาปุโรหิต และคายาฟาส ยอห์น อเล็กซานเดอร์ กับคนอื่นๆที่เป็นญาติของมหาปุโรหิตนั้นด้วย ได้ประชุมกันในกรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 7, 'เมื่อเขาให้เปโตรและยอห์นยืนอยู่ท่ามกลางพวกเขาแล้วจึงถามว่า “ท่านทั้งสองได้ทําการนี้โดยฤทธิ์อํานาจหรือในนามของผู้ใด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 8, 'ขณะนั้นเปโตรประกอบด้วยพระวิญญาณบริสุทธิ์กล่าวแก่เขาว่า “ท่านผู้ครอบครองพลเมืองและพวกผู้ใหญ่ทั้งหลายของอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 9, 'ถ้าท่านทั้งหลายจะถามพวกเราในวันนี้ถึงการดีซึ่งได้ทําแก่คนป่วยนี้ว่า เขาหายเป็นปกติด้วยเหตุอันใดแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 10, 'ก็ให้ท่านทั้งหลายกับบรรดาชนอิสราเอลทราบเถิดว่า โดยพระนามของพระเยซูคริสต์ชาวนาซาเร็ธ ซึ่งท่านทั้งหลายได้ตรึงไว้ที่กางเขน และซึ่งพระเจ้าได้ทรงโปรดให้คืนพระชนม์ โดยพระองค์นั้นแหละชายคนนี้ได้หายโรคเป็นปกติแล้วจึงยืนอยู่ต่อหน้าท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 11, 'พระองค์เป็น ‘ศิลา’ ที่ท่านทั้งหลายผู้เป็น ‘ช่างก่อได้ปฏิเสธเสีย ได้กลับกลายเป็นศิลามุมเอกแล้ว’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 12, 'ในผู้อื่นความรอดไม่มีเลย ด้วยว่านามอื่นซึ่งให้เราทั้งหลายรอดได้ ไม่ทรงโปรดให้มีในท่ามกลางมนุษย์ทั่วใต้ฟ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 13, 'เมื่อเขาเห็นความกล้าหาญของเปโตรกับยอห์น และรู้ว่าท่านทั้งสองขาดการศึกษาและเป็นคนมีความรู้น้อยก็ประหลาดใจ แล้วสํานึกว่าคนทั้งสองเคยอยู่กับพระเยซู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 14, 'เมื่อเขาเห็นคนนั้นที่หายโรคยืนอยู่กับเปโตรและยอห์น เขาก็ไม่มีข้อคัดค้านที่จะพูดขึ้นได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 15, 'แต่เมื่อเขาสั่งให้เปโตรและยอห์นออกไปจากที่ประชุมสภาแล้ว เขาจึงปรึกษากัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 16, 'ว่า “เราจะทําอย่างไรกับคนทั้งสองนี้ เพราะการที่เขาได้กระทําการอัศจรรย์อันเด่นชัด ก็ได้ปรากฏแก่คนทั้งปวงที่อยู่ในกรุงเยรูซาเล็มแล้ว และเราปฏิเสธไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 17, 'แต่ให้เราขู่เขาอย่างแข็งแรงห้ามไม่ให้พูดอ้างชื่อนั้นกับผู้หนึ่งผู้ใดเลย เพื่อเรื่องนี้จะไม่ได้เลื่องลือแพร่หลายไปในหมู่คนทั้งปวง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 18, 'เขาจึงเรียกเปโตรและยอห์นมา แล้วห้ามปรามเด็ดขาดไม่ให้พูดหรือสอนออกพระนามของพระเยซูอีกเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 19, 'ฝ่ายเปโตรและยอห์นตอบเขาว่า “การที่จะฟังท่านมากกว่าฟังพระเจ้าจะเป็นการถูกต้องในสายพระเนตรของพระเจ้าหรือ ขอท่านทั้งหลายพิจารณาดูเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 20, 'ซึ่งข้าพเจ้าจะไม่พูดตามที่เห็นและได้ยินนั้นก็ไม่ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 21, 'เมื่อเขาขู่สําทับท่านทั้งสองนั้นอีกแล้วก็ปล่อยไป ไม่เห็นมีเหตุที่จะทําโทษท่านอย่างไรได้เพราะกลัวคนเหล่านั้น เหตุว่าคนทั้งหลายได้สรรเสริญพระเจ้าเนื่องด้วยเหตุการณ์ที่เกิดขึ้นนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 22, 'ด้วยว่าคนที่หายโรคโดยการอัศจรรย์นั้น มีอายุกว่าสี่สิบปีแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 23, 'เมื่อเขาปล่อยท่านทั้งสองแล้ว ท่านจึงไปหาพวกของท่าน เล่าเรื่องทั้งสิ้นที่พวกปุโรหิตใหญ่และพวกผู้ใหญ่ได้ว่าแก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 24, 'เมื่อเขาทั้งหลายได้ฟังจึงพร้อมใจกันเปล่งเสียงทูลพระเจ้าว่า “พระองค์เจ้าข้า ผู้เป็นพระเจ้าซึ่งได้ทรงสร้างฟ้าสวรรค์ แผ่นดินโลก ทะเล และสรรพสิ่งที่มีอยู่ในที่เหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 25, 'พระองค์ตรัสไว้ด้วยปากของดาวิดผู้รับใช้ของพระองค์ว่า ‘เหตุใดชนต่างชาติจึงกระทําโกลาหลขึ้น และชนชาติทั้งหลายคิดอ่านในการที่ไร้ประโยชน์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 26, 'บรรดากษัตริย์แห่งแผ่นดินโลกตั้งตนเองขึ้น และนักปกครองชุมนุมกันต่อสู้องค์พระผู้เป็นเจ้าและพระคริสต์ของพระองค์’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 27, 'ความจริงทั้งเฮโรดและปอนทิอัสปีลาต กับพวกต่างประเทศ และชนชาติอิสราเอลได้ชุมนุมกันต่อสู้พระเยซูพระบุตรผู้บริสุทธิ์ของพระองค์ ซึ่งทรงเจิมไว้แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 28, 'ให้กระทําสิ่งสารพัดตามที่พระหัตถ์ และพระดําริของพระองค์ได้กําหนดตั้งแต่ก่อนมาแล้วให้เกิดขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 29, 'บัดนี้พระองค์เจ้าข้า ขอโปรดทอดพระเนตรการขู่ของเขา และโปรดประทานให้ผู้รับใช้ของพระองค์กล่าวถ้อยคําของพระองค์ด้วยใจกล้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 30, 'เมื่อพระองค์ได้ทรงเหยียดพระหัตถ์ของพระองค์ออกรักษาโรคให้หาย และได้โปรดให้หมายสําคัญกับการมหัศจรรย์บังเกิดขึ้น โดยพระนามแห่งพระเยซูพระบุตรผู้บริสุทธิ์ของพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 31, 'เมื่อเขาอธิษฐานแล้ว ที่ซึ่งเขาประชุมอยู่นั้นได้หวั่นไหว และคนเหล่านั้นประกอบด้วยพระวิญญาณบริสุทธิ์ ได้กล่าวพระวจนะของพระเจ้าด้วยใจกล้าหาญ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 32, 'คนทั้งปวงที่เชื่อนั้นเป็นน้ําหนึ่งใจเดียวกัน และไม่มีใครอ้างว่าสิ่งของที่ตนมีอยู่เป็นของตน แต่ทั้งหมดเป็นของกลาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 33, 'อัครสาวกจึงเป็นพยานด้วยฤทธิ์เดชใหญ่ยิ่งถึงการคืนพระชนม์ของพระเยซูเจ้า และพระคุณอันใหญ่ยิ่งได้อยู่กับเขาทุกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 34, 'และในพวกศิษย์ไม่มีผู้ใดขัดสน เพราะผู้ใดมีไร่นาบ้านเรือนก็ขายเสีย และได้นําเงินค่าของที่ขายได้นั้นมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 35, 'วางไว้ที่เท้าของอัครสาวก อัครสาวกจึงแจกจ่ายให้ทุกคนตามที่ต้องการ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 36, 'ฝ่ายโยเสส ที่อัครสาวกเรียกว่า บารนาบัส (แปลว่าลูกแห่งการหนุนน้ําใจ) เป็นพวกเลวี ชาวเกาะไซปรัส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 37, 'มีที่ดินก็ขายเสียและนําเงินค่าที่นั้นมาวางไว้ที่เท้าของอัครสาวก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 1, 'แต่มีชายคนหนึ่งชื่ออานาเนียกับภรรยาชื่อสัปฟีราได้ขายที่ดินของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 2, 'และเงินค่าที่ดินส่วนหนึ่งเขายักเก็บไว้ ภรรยาของเขาก็รู้ด้วย และอีกส่วนหนึ่งเขานํามาวางไว้ที่เท้าของอัครสาวก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 3, 'ฝ่ายเปโตรจึงถามว่า “อานาเนีย เหตุไฉนซาตานจึงทําให้ใจของเจ้าเต็มไปด้วยการมุสาต่อพระวิญญาณบริสุทธิ์ และทําให้เจ้าเก็บค่าที่ดินส่วนหนึ่งไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 4, 'เมื่อที่ดินยังอยู่ก็เป็นของเจ้ามิใช่หรือ เมื่อขายแล้วเงินก็ยังอยู่ในอํานาจของเจ้ามิใช่หรือ มีเหตุอะไรเกิดขึ้นให้เจ้าคิดในใจเช่นนั้นเล่า เจ้ามิได้มุสาต่อมนุษย์แต่ได้มุสาต่อพระเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 5, 'เมื่ออานาเนียได้ยินคําเหล่านั้นก็ล้มลงตาย และเมื่อคนทั้งปวงได้ยินเรื่องก็พากันสะดุ้งตกใจกลัวอย่างยิ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 6, 'พวกคนหนุ่มก็ลุกขึ้นห่อศพเขาไว้แล้วหามเอาไปฝัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 7, 'หลังจากนั้นประมาณสามชั่วโมง ภรรยาของเขายังไม่ทราบเหตุการณ์ที่เกิดขึ้นจึงเข้าไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 8, 'ฝ่ายเปโตรถามนางว่า “เจ้าขายที่ดินได้ราคาเท่านั้นหรือ จงบอกเราเถิด” หญิงนั้นจึงตอบว่า “ได้เท่านั้นเจ้าค่ะ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 9, 'เปโตรจึงถามนางว่า “ไฉนเจ้าทั้งสองได้พร้อมใจกันทดลองพระวิญญาณขององค์พระผู้เป็นเจ้าเล่า จงดูเถิด เท้าของพวกคนที่ฝังศพสามีของเจ้าก็อยู่ที่ประตู และเขาจะหามศพของเจ้าออกไปด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 10, 'ในทันใดนั้นนางก็ล้มลงตายแทบเท้าของเปโตร และพวกคนหนุ่มได้เข้ามาเห็นว่าหญิงนั้นตายแล้ว จึงได้หามศพออกไปฝังไว้ข้างสามีของนาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 11, 'ความเกรงกลัวอย่างยิ่งเกิดขึ้นในคริสตจักร และในหมู่คนทั้งปวงที่ได้ยินเหตุการณ์นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 12, 'มีหมายสําคัญและการมหัศจรรย์หลายอย่างซึ่งอัครสาวกได้ทําด้วยมือของตนในหมู่ประชาชน (พวกสาวกอยู่พร้อมใจกันในเฉลียงของซาโลมอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 13, 'และคนอื่นๆไม่อาจเข้ามาอยู่ด้วย แต่ประชาชนเคารพพวกเขามาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 14, 'มีชายหญิงเป็นอันมากที่เชื่อถือ ได้เข้ามาเป็นสาวกขององค์พระผู้เป็นเจ้ามากกว่าก่อน)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 15, 'จนเขาหามคนเจ็บป่วยออกไปที่ถนนวางบนที่นอนและแคร่ เพื่อเมื่อเปโตรเดินผ่านไป อย่างน้อยเงาของท่านจะได้ถูกเขาบางคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 16, 'ประชาชนได้ออกมาจากเมืองที่อยู่ล้อมรอบกรุงเยรูซาเล็ม พาคนป่วยและคนที่มีผีโสโครกเบียดเบียนมาและทุกคนก็หาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 17, 'ฝ่ายมหาปุโรหิตและพรรคพวกของท่านก็ลุกขึ้น (คือพวกสะดูสี) มีความโกรธอย่างยิ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 18, 'จึงได้จับพวกอัครสาวกจําไว้ในคุกหลวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 19, 'แต่ในเวลากลางคืน ทูตสวรรค์ขององค์พระผู้เป็นเจ้าได้มาเปิดประตูคุก พาอัครสาวกออกไป บอกว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 20, '“จงไปยืนในพระวิหาร ประกาศบรรดาข้อความแห่งชีวิตนี้ให้ประชาชนฟัง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 21, 'เมื่ออัครสาวกได้ยินอย่างนั้น พอเวลารุ่งเช้าจึงเข้าไปสั่งสอนในพระวิหาร ฝ่ายมหาปุโรหิตกับพรรคพวกของท่านได้เรียกประชุมสภา พร้อมกับบรรดาผู้เฒ่าทั้งหมดของชนอิสราเอล แล้วใช้คนไปที่คุกให้พาอัครสาวกออกมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 22, 'แต่เมื่อเจ้าพนักงานไปถึงก็ไม่พบพวกอัครสาวกในคุก จึงกลับมารายงาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 23, 'ว่า “ข้าพเจ้าทั้งหลายเห็นคุกปิดอยู่มั่นคงและคนเฝ้าก็ยืนอยู่ข้างนอกหน้าประตู ครั้นเปิดประตูแล้วก็ไม่เห็นผู้ใดอยู่ข้างใน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 24, 'ตอนนี้เมื่อมหาปุโรหิตและนายทหารรักษาพระวิหารกับพวกปุโรหิตใหญ่ ได้ยินคําเหล่านี้ ก็ฉงนสนเท่ห์ในเรื่องของอัครสาวกว่าจะเป็นอย่างไรต่อไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 25, 'แล้วมีคนหนึ่งมาบอกเขาว่า “ดูเถิด คนเหล่านั้น ซึ่งท่านทั้งหลายได้จําไว้ในคุกกําลังยืนสั่งสอนคนทั้งปวงอยู่ในพระวิหาร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 26, 'แล้วนายทหารรักษาพระวิหารกับพวกเจ้าพนักงานจึงได้ไปพาพวกอัครสาวกมาโดยดี เพราะกลัวว่าคนทั้งปวงจะเอาหินขว้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 27, 'เมื่อเขาได้พาพวกอัครสาวกมาแล้วก็ให้ยืนหน้าสภา มหาปุโรหิตจึงถาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 28, 'ว่า “เราได้กําชับพวกเจ้าอย่างแข็งแรงมิให้สอนออกชื่อนี้ ก็ดูเถิด เจ้าได้ให้คําสอนของเจ้าแพร่ไปทั่วกรุงเยรูซาเล็ม และปรารถนาให้ความผิดเนื่องด้วยโลหิตของผู้นั้นตกอยู่กับเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 29, 'ฝ่ายเปโตรกับอัครสาวกอื่นๆตอบว่า “ข้าพเจ้าทั้งหลายจําต้องเชื่อฟังพระเจ้ายิ่งกว่าเชื่อฟังมนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 30, 'พระเยซูซึ่งท่านทั้งหลายได้ฆ่าเสียโดยแขวนไว้ที่ต้นไม้นั้น พระเจ้าแห่งบรรพบุรุษของเราได้ทรงบันดาลให้เป็นขึ้นมาใหม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 31, 'พระเจ้าได้ทรงตั้งพระองค์ไว้ด้วยพระหัตถ์เบื้องขวาของพระองค์ให้เป็นเจ้าชาย และองค์พระผู้ช่วยให้รอด เพื่อจะให้ชนอิสราเอลกลับใจใหม่ แล้วจะทรงโปรดยกความผิดบาปของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 32, 'เราทั้งหลายจึงเป็นพยานของพระองค์ถึงเรื่องเหล่านี้ และพระวิญญาณบริสุทธิ์ ซึ่งพระเจ้าได้ทรงประทานให้ทุกคนที่เชื่อฟังพระองค์นั้นก็เป็นพยานด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 33, 'เมื่อเขาทั้งหลายได้ยินอย่างนี้ ก็รู้สึกบาดใจ คิดกันว่าจะฆ่าพวกอัครสาวกเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 34, 'แต่คนหนึ่งชื่อกามาลิเอลเป็นพวกฟาริสี และเป็นธรรมาจารย์ฝ่ายพระราชบัญญัติ เป็นที่นับถือของประชาชน ได้ยืนขึ้นในสภาแล้วสั่งให้พาพวกอัครสาวกออกไปเสียภายนอกครู่หนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 35, 'ท่านจึงได้กล่าวแก่เขาว่า “ท่านชนชาติอิสราเอล ซึ่งท่านหวังจะทําแก่คนเหล่านี้ จงระวังตัวให้ดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 36, 'เมื่อคราวก่อนมีคนหนึ่งชื่อธุดาสอวดตัวว่าเป็นผู้วิเศษ มีผู้ชายติดตามประมาณสี่ร้อยคน แต่ธุดาสถูกฆ่าเสีย คนทั้งหลายซึ่งได้เชื่อฟังเขาก็กระจัดกระจายสาบสูญไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 37, 'ภายหลังผู้นี้มีอีกคนหนึ่งชื่อยูดาสเป็นชาวกาลิลี ได้ปรากฏขึ้นในคราวจดบัญชีสํามะโนครัว และได้เกลี้ยกล่อมผู้คนให้ติดตามตัวไปเป็นอันมาก ผู้นั้นก็พินาศด้วย และคนทั้งหลายที่ได้เชื่อฟังเขาก็กระจัดกระจายไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 38, 'ในกรณีนี้ ข้าพเจ้าจึงว่าแก่ท่านทั้งหลายว่า จงปล่อยคนเหล่านี้ไปตามเรื่อง อย่าทําอะไรแก่เขาเลย เพราะว่าถ้าความคิดหรือกิจการนี้มาจากมนุษย์ก็จะล้มละลายไปเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 39, 'แต่ถ้ามาจากพระเจ้า ท่านทั้งหลายจะทําลายเสียก็ไม่ได้ เกลือกว่าท่านกลับจะเป็นผู้สู้รบกับพระเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 40, 'เขาทั้งหลายจึงยอมเห็นด้วยกับกามาลิเอล และเมื่อได้เรียกพวกอัครสาวกเข้ามาแล้ว จึงเฆี่ยนและกําชับไม่ให้ออกพระนามของพระเยซู แล้วก็ปล่อยไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 41, 'พวกอัครสาวกจึงออกไปให้พ้นหน้าสภาด้วยความยินดีที่เห็นว่า ตนสมจะได้รับการหลู่เกียรติเพราะพระนามของพระองค์นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 42, 'ที่ในพระวิหารและตามบ้านเรือน เขาได้สั่งสอนและประกาศข่าวประเสริฐของพระเยซูคริสต์ ทุกๆวันมิได้ขาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 1, 'ในคราวนั้น เมื่อศิษย์กําลังทวีมากขึ้น พวกกรีกบ่นติเตียนพวกฮีบรูเพราะในการแจกทานทุกๆวันนั้น เขาเว้นไม่ได้แจกให้พวกแม่ม่ายชาวกรีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 2, 'ฝ่ายอัครสาวกทั้งสิบสองคนจึงเรียกบรรดาศิษย์ให้มาหาเขาแล้วกล่าวว่า “ซึ่งเราจะละเลยพระวจนะของพระเจ้ามัวไปแจกอาหารก็หาควรไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 3, 'เหตุฉะนั้นพี่น้องทั้งหลาย จงเลือกเจ็ดคนในพวกท่านที่มีชื่อเสียงดี ประกอบด้วยพระวิญญาณบริสุทธิ์และสติปัญญา เราจะตั้งเขาไว้ดูแลการงานนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 4, 'ฝ่ายพวกเราจะขะมักเขม้นอธิษฐานและสั่งสอนพระวจนะเสมอไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 5, 'คนทั้งหลายเห็นชอบกับคํานี้ จึงเลือกสเทเฟน ผู้ประกอบด้วยความเชื่อและพระวิญญาณบริสุทธิ์ กับฟีลิป โปรโครัส นิคาโนร์ ทิโมน ปารเมนัส และนิโคเลาส์ชาวเมืองอันทิโอก ซึ่งเป็นผู้เข้าจารีตฝ่ายศาสนายิว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 6, 'คนทั้งเจ็ดนี้เขาให้มาอยู่ต่อหน้าพวกอัครสาวก และเมื่อพวกอัครสาวกได้อธิษฐานแล้ว จึงได้วางมือบนเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 7, 'การประกาศพระวจนะของพระเจ้าได้เจริญขึ้น และจําพวกศิษย์ก็ทวีขึ้นเป็นอันมากในกรุงเยรูซาเล็ม และพวกปุโรหิตเป็นอันมากก็ได้เชื่อฟังในความเชื่อนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 8, 'ฝ่ายสเทเฟนประกอบด้วยความเชื่อและฤทธิ์เดช จึงกระทําการมหัศจรรย์และการอัศจรรย์ใหญ่ท่ามกลางประชาชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 9, 'แต่มีบางคนมาจากธรรมศาลาที่เรียกว่า ธรรมศาลาของพวกลิเบระติน มีทั้งชาวไซรีน ชาวอเล็กซานเดอร์ กับบางคนจากซีลีเซียและเอเชีย ได้ลุกขึ้นพากันมาไล่เลียงกับสเทเฟน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 10, 'คนเหล่านั้นสู้สติปัญญาและน้ําใจของท่านเมื่อท่านกล่าวแก่เขาไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 11, 'เขาจึงลอบปลุกพยานเท็จว่า “เราได้ยินคนนี้พูดหมิ่นประมาทต่อโมเสสและต่อพระเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 12, 'เขายุยงคนทั้งปวงและพวกผู้ใหญ่กับพวกธรรมาจารย์ แล้วเข้ามาจับสเทเฟนและนําไปยังสภา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 13, 'ให้พยานเท็จมากล่าวว่า “คนนี้พูดคําหมิ่นประมาทต่อสถานบริสุทธิ์นี้และพระราชบัญญัติไม่หยุดเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 14, 'เพราะเราได้ยินเขาว่า พระเยซูชาวนาซาเร็ธนี้จะทําลายสถานที่นี้ และจะเปลี่ยนธรรมเนียมซึ่งโมเสสให้ไว้แก่เรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 15, 'พวกสมาชิกสภาต่างเพ่งดูสเทเฟน เห็นหน้าของท่านเหมือนหน้าทูตสวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 1, 'มหาปุโรหิตจึงถามว่า “เรื่องนี้จริงหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 2, 'ฝ่ายสเทเฟนจึงตอบว่า “ท่านทั้งหลาย พี่น้องและบรรดาท่านผู้อาวุโส ขอฟังเถิด พระเจ้าแห่งสง่าราศีได้ปรากฏแก่อับราฮัมบิดาของเรา เมื่อท่านยังอยู่ในประเทศเมโสโปเตเมียก่อนที่ไปอาศัยอยู่ในเมืองฮาราน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 3, 'และได้ตรัสกับท่านว่า ‘เจ้าจงออกไปจากประเทศของเจ้า จากญาติพี่น้องของเจ้า ไปยังแผ่นดินที่เราจะชี้ให้เจ้าเห็น’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 4, 'อับราฮัมจึงออกจากแผ่นดินของชาวเคลเดียไปอาศัยอยู่ที่เมืองฮาราน หลังจากที่บิดาของท่านสิ้นชีพแล้ว พระองค์ทรงให้ท่านออกจากที่นั่น มาอยู่ในแผ่นดินนี้ที่ท่านทั้งหลายอาศัยอยู่ทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 5, 'แต่พระองค์ไม่ทรงโปรดให้อับราฮัมมีมรดกในแผ่นดินนี้แม้เท่าฝ่าเท้าก็ไม่ได้ และขณะเมื่อท่านยังไม่มีบุตร พระองค์ทรงสัญญาไว้ว่าจะให้แผ่นดินนี้เป็นกรรมสิทธิ์ของท่าน และเชื้อสายของท่านที่มาภายหลังท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 6, 'พระเจ้าตรัสดังนี้ว่า เชื้อสายของท่านจะไปอาศัยอยู่ในต่างประเทศ และชาวประเทศนั้นจะเอาเขาเป็นทาส และจะข่มเหงเขาเป็นเวลาสี่ร้อยปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 7, 'พระเจ้าตรัสว่า ‘และเราจะพิพากษาประเทศที่เขาจะเป็นทาสนั้น ภายหลังเขาจะออกมาและปรนนิบัติเรา ณ สถานที่นี้’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 8, 'พระองค์ได้ทรงตั้งพันธสัญญาแห่งการเข้าสุหนัตไว้กับอับราฮัม เหตุฉะนั้นเมื่ออับราฮัมให้กําเนิดบุตรชื่ออิสอัค จึงให้เข้าสุหนัตในวันที่แปด อิสอัคให้กําเนิดบุตรชื่อยาโคบ และยาโคบให้กําเนิดบุตรสิบสองคน ซึ่งเป็นบรรพบุรุษของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 9, 'ฝ่ายบรรพบุรุษเหล่านั้นคิดอิจฉาโยเซฟจึงขายเขาไปยังประเทศอียิปต์ แต่พระเจ้าทรงสถิตกับโยเซฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 10, 'ทรงโปรดช่วยโยเซฟให้พ้นจากความทุกข์ลําบากทั้งสิ้น และทรงให้ท่านเป็นที่โปรดปรานและมีสติปัญญาในสายพระเนตรของฟาโรห์ กษัตริย์ของประเทศอียิปต์ ท่านจึงตั้งโยเซฟให้เป็นผู้ปกครองประเทศอียิปต์กับทั้งพระราชสํานักของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 11, 'แล้วบังเกิดการกันดารอาหารทั่วแผ่นดินอียิปต์และแผ่นดินคานาอัน และมีความลําบากมาก บรรพบุรุษของเราจึงไม่มีอาหาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 12, 'ฝ่ายยาโคบเมื่อได้ยินว่ามีข้าวอยู่ในประเทศอียิปต์ จึงใช้บรรพบุรุษของเราไปเป็นครั้งแรก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 13, 'พอคราวที่สองโยเซฟก็สําแดงตัวให้พี่น้องรู้จัก และให้ฟาโรห์รู้จักวงศ์ญาติของตนด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 14, 'ฝ่ายโยเซฟจึงได้เชิญยาโคบบิดากับบรรดาญาติของตนเจ็ดสิบห้าคนให้มาหา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 15, 'ยาโคบได้ลงไปยังประเทศอียิปต์ แล้วท่านกับพวกบรรพบุรุษของเราได้สิ้นชีพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 16, 'เขาจึงได้นําศพไปฝังไว้ในเมืองเชเคมในอุโมงค์ที่อับราฮัมเอาเงินจํานวนหนึ่งซื้อจากบุตรชายของฮาโมร์บิดาของเชเคม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 17, 'เมื่อใกล้เวลาตามพระสัญญาซึ่งพระเจ้าได้ปฏิญาณไว้กับอับราฮัม ชนชาติอิสราเอลได้ทวีมากขึ้นในประเทศอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 18, 'จนกระทั่งกษัตริย์องค์หนึ่งซึ่งไม่รู้จักโยเซฟได้ขึ้นเสวยราชย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 19, 'กษัตริย์องค์นั้นได้ทรงออกอุบายทํากับญาติของเรา ข่มเหงบรรพบุรุษของเรา บังคับให้ทิ้งลูกอ่อนของเขาเสียไม่ให้มีชีวิตรอดอยู่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 20, 'คราวนั้นโมเสสเกิดมามีรูปร่างงดงาม เขาจึงได้เลี้ยงไว้ในบ้านบิดาจนครบสามเดือน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 21, 'และเมื่อลูกอ่อนนั้นถูกทิ้งไว้นอกบ้านแล้ว ราชธิดาของฟาโรห์จึงรับมาเลี้ยงไว้ต่างบุตรชายของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 22, 'ฝ่ายโมเสสจึงได้เรียนรู้ในวิชาการทุกอย่างของชาวอียิปต์ มีความเฉียบแหลมมากในการพูดและกิจการต่างๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 23, 'แต่ครั้นโมเสสมีอายุได้สี่สิบปีเต็มแล้ว ก็นึกอยากจะไปเยี่ยมญาติพี่น้องของตน คือชนชาติอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 24, 'เมื่อท่านได้เห็นคนหนึ่งถูกข่มเหงจึงเข้าไปช่วย โดยฆ่าชาวอียิปต์ซึ่งเป็นผู้กดขี่นั้นเป็นการแก้แค้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 25, 'ด้วยคาดว่าญาติพี่น้องคงเข้าใจว่า พระเจ้าจะทรงช่วยเขาให้รอดด้วยมือของตน แต่เขาหาเข้าใจดังนั้นไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 26, 'วันรุ่งขึ้นโมเสสได้เข้ามาพบเขาขณะวิวาทกัน ก็อยากจะให้เขากลับดีกันอีก จึงกล่าวว่า ‘เพื่อนเอ๋ย ท่านเป็นพี่น้องกัน ไฉนจึงทําร้ายกันเล่า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 27, 'ฝ่ายคนที่ข่มเหงเพื่อนนั้นจึงผลักโมเสสออกไปและกล่าวว่า ‘ใครแต่งตั้งเจ้าให้เป็นผู้ครอบครองและผู้พิพากษาพวกเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 28, 'เจ้าจะฆ่าเราเสียเหมือนฆ่าชาวอียิปต์เมื่อวานนี้หรือ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 29, 'เมื่อโมเสสได้ยินคํานั้นจึงหนีไปอาศัยอยู่ที่แผ่นดินมีเดียน และให้กําเนิดบุตรชายสองคนที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 30, 'ครั้นล่วงไปได้สี่สิบปีแล้ว ทูตสวรรค์องค์หนึ่งขององค์พระผู้เป็นเจ้ามาปรากฏแก่โมเสสในเปลวไฟที่พุ่มไม้ ในถิ่นทุรกันดารแห่งภูเขาซีนาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 31, 'เมื่อโมเสสเห็นก็ประหลาดใจด้วยเรื่องนิมิตนั้น ครั้นเข้าไปดูใกล้ๆก็มีพระสุรเสียงขององค์พระผู้เป็นเจ้าตรัสกับเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 32, 'ว่า ‘เราเป็นพระเจ้าของบรรพบุรุษของเจ้า เป็นพระเจ้าของอับราฮัม เป็นพระเจ้าของอิสอัค และเป็นพระเจ้าของยาโคบ’ โมเสสจึงกลัวจนตัวสั่นไม่อาจมองดู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 33, 'ฝ่ายองค์พระผู้เป็นเจ้าจึงตรัสกับโมเสสว่า ‘จงถอดรองเท้าของเจ้าออกเสีย เพราะว่าที่ซึ่งเจ้ายืนอยู่นี้เป็นที่บริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 34, 'ดูเถิด เราได้เห็นความทุกข์ของชนชาติของเราที่อยู่ในประเทศอียิปต์แล้ว และเราได้ยินเสียงคร่ําครวญของเขา และเราลงมาเพื่อจะช่วยเขาให้รอด จงมาเถิด เราจะใช้เจ้าไปยังประเทศอียิปต์’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 35, 'โมเสสผู้นี้ซึ่งถูกเขาปฏิเสธโดยกล่าวว่า ‘ใครแต่งตั้งเจ้าให้เป็นผู้ครอบครองและผู้พิพากษาพวกเรา’ โดยมือของทูตสวรรค์ซึ่งได้ปรากฏแก่ท่านที่พุ่มไม้ พระเจ้าทรงใช้โมเสสคนนี้แหละให้เป็นทั้งผู้ครอบครองและผู้ช่วยให้พ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 36, 'คนนี้แหละ เป็นผู้นําเขาทั้งหลายออกมา โดยที่ได้ทําการมหัศจรรย์และหมายสําคัญต่างๆในแผ่นดินอียิปต์ ที่ทะเลแดงและในถิ่นทุรกันดารสี่สิบปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 37, 'โมเสสคนนี้แหละได้กล่าวแก่ชนชาติอิสราเอลว่า ‘องค์พระผู้เป็นเจ้าผู้เป็นพระเจ้าของท่านทั้งหลายจะทรงโปรดประทานศาสดาพยากรณ์ผู้หนึ่ง เหมือนอย่างเราให้แก่ท่านจากจําพวกพี่น้องของท่าน ท่านทั้งหลายจงตั้งใจฟังผู้นั้น’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 38, 'โมเสสนี้แหละได้อยู่กับพลไพร่ในถิ่นทุรกันดารกับทูตสวรรค์ซึ่งได้ตรัสแก่ท่านที่ภูเขาซีนาย และอยู่กับบรรพบุรุษของเรา ที่ได้รับพระดํารัสอันทรงชีวิตมาให้เราทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 39, 'บรรพบุรุษของเราไม่ยอมเชื่อฟังโมเสสผู้นี้ แต่ได้ผลักไสท่านให้ไปจากเขา ด้วยมีใจปรารถนาจะกลับไปยังแผ่นดินอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 40, 'จึงกล่าวแก่อาโรนว่า ‘ขอสร้างพระให้แก่พวกข้าพเจ้า ซึ่งจะนําพวกข้าพเจ้าไป ด้วยว่าโมเสสคนนี้ที่ได้นําข้าพเจ้าออกมาจากประเทศอียิปต์เป็นอะไรไปเสียแล้ว ข้าพเจ้าไม่ทราบ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 41, 'ในคราวนั้นเขาทั้งหลายได้ทํารูปโคหนุ่ม และได้นําเครื่องสัตวบูชามาถวายแก่รูปนั้น และมีใจยินดีในสิ่งซึ่งมือของตนเองได้ทําขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 42, 'แต่พระเจ้าทรงหันพระพักตร์ไปเสียและปล่อยให้เขานมัสการหมู่ดาวในท้องฟ้า ตามที่มีเขียนไว้ในพระคัมภีร์แห่งศาสดาพยากรณ์ว่า ‘โอ วงศ์วานอิสราเอลเอ๋ย เจ้าได้ฆ่าสัตว์บูชาเราและถวายเครื่องบูชาให้แก่เราในถิ่นทุรกันดารถึงสี่สิบปีหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 43, 'แล้วเจ้าทั้งหลายได้หามพลับพลาของพระโมเลค และได้เอาดาวพระเรฟาน รูปพระที่เจ้าได้กระทําขึ้นเพื่อกราบนมัสการรูปนั้นต่างหาก เราจึงจะกวาดเจ้าทั้งหลายให้ไปอยู่พ้นเมืองบาบิโลนอีก’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 44, 'บรรพบุรุษของเราเมื่ออยู่ในถิ่นทุรกันดารก็มีพลับพลาแห่งสักขีพยาน ตามที่พระองค์ทรงสั่งไว้เมื่อตรัสกับโมเสสว่าให้ทําพลับพลาตามแบบที่ได้เห็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 45, 'ฝ่ายบรรพบุรุษของเราที่มาภายหลัง เมื่อได้รับพลับพลานั้นจึงขนตามเยซูไป เมื่อได้เข้ายึดแผ่นดินของบรรดาประชาชาติ ซึ่งพระเจ้าได้ทรงขับไล่ไปให้พ้นหน้าบรรพบุรุษของเรา พลับพลานั้นก็มีสืบมาจนถึงสมัยดาวิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 46, 'ดาวิดนั้นมีความชอบจําเพาะพระพักตร์พระเจ้า และมีใจปรารถนาที่จะหาพระนิเวศสําหรับพระเจ้าของยาโคบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 47, 'แต่ซาโลมอนเป็นผู้ได้สร้างพระนิเวศสําหรับพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 48, 'ถึงกระนั้นก็ดี องค์ผู้สูงสุดหาได้ประทับในพระวิหารซึ่งมือมนุษย์ได้ทําไว้ไม่ ตามที่ศาสดาพยากรณ์ได้กล่าวไว้ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 49, '‘องค์พระผู้เป็นเจ้าตรัสว่า สวรรค์เป็นบัลลังก์ของเรา และแผ่นดินโลกเป็นแท่นรองเท้าของเรา เจ้าจะสร้างนิเวศอะไรสําหรับเรา หรือที่พํานักของเราอยู่ที่ไหน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 50, 'สิ่งเหล่านี้มือของเราได้กระทําทั้งสิ้น มิใช่หรือ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 51, 'ท่านคนชาติคอแข็ง ที่ใจและหูไม่เข้าสุหนัต ท่านทั้งหลายขัดขวางพระวิญญาณบริสุทธิ์อยู่เสมอ บรรพบุรุษของท่านทําอย่างไร ท่านก็ทําอย่างนั้นด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 52, 'มีใครบ้างในพวกศาสดาพยากรณ์ซึ่งบรรพบุรุษของท่านมิได้ข่มเหง และเขาได้ฆ่าบรรดาคนที่พยากรณ์ถึงการเสด็จมาขององค์ผู้ชอบธรรม ซึ่งท่านทั้งหลายเป็นผู้ทรยศและผู้ฆาตกรรมพระองค์นั้นเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 53, 'คือท่านทั้งหลายผู้ที่ได้รับพระราชบัญญัติจากเหล่าทูตสวรรค์ แต่หาได้รักษาพระราชบัญญัตินั้นไม่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 54, 'เมื่อเขาทั้งหลายได้ยินดังนั้น ก็รู้สึกบาดใจ และขบเขี้ยวเคี้ยวฟันเข้าใส่สเทเฟน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 55, 'ฝ่ายสเทเฟนประกอบด้วยพระวิญญาณบริสุทธิ์ ได้เขม้นดูสวรรค์เห็นสง่าราศีของพระเจ้า และพระเยซูทรงยืนอยู่เบื้องขวาพระหัตถ์ของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 56, 'แล้วท่านได้กล่าวว่า “ดูเถิด ข้าพเจ้าเห็นท้องฟ้าแหวกเป็นช่อง และบุตรมนุษย์ยืนอยู่เบื้องขวาพระหัตถ์ของพระเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 57, 'แต่เขาทั้งปวงร้องเสียงดังและอุดหูวิ่งกรูกันเข้าไปยังสเทเฟน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 58, 'แล้วขับไล่ท่านออกจากกรุงและเอาหินขว้าง ฝ่ายคนที่เป็นพยานปรักปรําสเทเฟนได้ฝากเสื้อผ้าของตนวางไว้ที่เท้าของชายหนุ่มคนหนึ่งชื่อเซาโล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 59, 'เขาจึงเอาหินขว้างสเทเฟนเมื่อกําลังอ้อนวอนพระเจ้าอยู่ว่า “ข้าแต่พระเยซูเจ้า ขอทรงโปรดรับจิตวิญญาณของข้าพระองค์ด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 60, 'สเทเฟนก็คุกเข่าลงร้องเสียงดังว่า “พระองค์เจ้าข้า ขอโปรดอย่าทรงถือโทษเขาเพราะบาปนี้” เมื่อกล่าวเช่นนี้แล้วก็ล่วงหลับไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 1, 'การที่เขาฆ่าสเทเฟนเสียนั้นเซาโลก็เห็นชอบด้วย คราวนั้นเกิดการข่มเหงคริสตจักรครั้งใหญ่ในกรุงเยรูซาเล็ม และศิษย์ทั้งปวงนอกจากพวกอัครสาวกได้กระจัดกระจายไปทั่วแว่นแคว้นยูเดียกับสะมาเรีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 2, 'ผู้ที่เกรงกลัวพระเจ้าก็ฝังศพสเทเฟนไว้ แล้วคร่ําครวญอาลัยถึงท่านอย่างยิ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 3, 'ฝ่ายเซาโลพยายามทําลายคริสตจักร โดยเข้าไปฉุดลากชายหญิงจากทุกบ้านทุกเรือนเอาไปจําไว้ในคุก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 4, 'ฉะนั้นฝ่ายศิษย์ทั้งหลายซึ่งกระจัดกระจายไปก็เที่ยวประกาศพระวจนะนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 5, 'ส่วนฟีลิปจึงลงไปยังเมืองสะมาเรียและประกาศเรื่องพระคริสต์ให้ชาวเมืองนั้นฟัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 6, 'ประชาชนก็พร้อมใจกันฟังถ้อยคําที่ฟีลิปได้ประกาศ เพราะเขาได้ยินท่านพูด และได้เห็นการอัศจรรย์ซึ่งท่านได้กระทํานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 7, 'ด้วยว่าผีโสโครกที่สิงอยู่ในคนหลายคนได้พากันร้องด้วยเสียงดัง แล้วออกมาจากคนเหล่านั้น และคนที่เป็นโรคอัมพาตกับคนง่อยก็หายเป็นปกติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 8, 'จึงเกิดความปลื้มปีติอย่างยิ่งในเมืองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 9, 'ยังมีชายคนหนึ่งชื่อซีโมนเคยทําเวทมนตร์ในเมืองนั้นมาก่อน และได้ทําให้ชาวสะมาเรียพิศวงหลงใหล เขายกตัวว่าเป็นผู้วิเศษ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 10, 'ฝ่ายคนทั้งปวงทั้งผู้ใหญ่ผู้น้อยก็สนใจฟังคนนั้น แล้วว่า “ชายคนนี้เป็นมหิทธิฤทธิ์ของพระเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 11, 'คนทั้งหลายนับถือเขา เพราะเขาได้ทําเวทมนตร์ให้คนทั้งหลายพิศวงหลงใหลมานานแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 12, 'แต่เมื่อฟีลิปได้ประกาศเรื่องอาณาจักรของพระเจ้า และพระนามแห่งพระเยซูคริสต์แล้ว คนทั้งหลายก็เชื่อ และรับบัพติศมาทั้งชายและหญิง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 13, 'ฝ่ายซีโมนเองจึงเชื่อด้วย เมื่อรับบัพติศมาแล้วก็อยู่กับฟีลิปต่อไป และประหลาดใจที่เห็นการอัศจรรย์กับหมายสําคัญต่างๆซึ่งฟีลิปได้กระทํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 14, 'เมื่อพวกอัครสาวกซึ่งอยู่ในกรุงเยรูซาเล็มได้ยินว่า ชาวสะมาเรียได้รับพระวจนะของพระเจ้าแล้ว จึงให้เปโตรกับยอห์นไปหาเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 15, 'ครั้นเปโตรกับยอห์นลงไปถึงก็อธิษฐานเผื่อเขา เพื่อให้เขาได้รับพระวิญญาณบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 16, '(ด้วยว่าพระวิญญาณบริสุทธิ์ยังไม่ได้เสด็จลงมาสถิตกับผู้ใด เป็นแต่เขาได้รับบัพติศมาในพระนามแห่งพระเยซูเจ้าเท่านั้น)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 17, 'เปโตรกับยอห์นจึงวางมือบนเขา แล้วเขาทั้งหลายก็ได้รับพระวิญญาณบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 18, 'เมื่อซีโมนเห็นว่า คนเหล่านั้นได้รับพระวิญญาณบริสุทธิ์ด้วยการวางมือของอัครสาวก จึงนําเงินมาให้อัครสาวก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 19, 'และว่า “ขอให้ข้าพเจ้ามีฤทธิ์อย่างนี้ด้วย เพื่อว่าเมื่อข้าพเจ้าจะวางมือบนผู้ใด ผู้นั้นจะได้รับพระวิญญาณบริสุทธิ์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 20, 'ฝ่ายเปโตรจึงกล่าวแก่ซีโมนว่า “ให้เงินของเจ้าพินาศไปด้วยกันกับเจ้าเถิด เพราะเจ้าคิดว่าจะซื้อของประทานแห่งพระเจ้าด้วยเงินได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 21, 'เจ้าไม่มีส่วนหรือส่วนแบ่งในการนี้เลย เพราะใจของเจ้าไม่ซื่อตรงในสายพระเนตรของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 22, 'เหตุฉะนั้น จงกลับใจใหม่จากการชั่วร้ายของเจ้านี้ และอธิษฐานขอพระเจ้าชะรอยพระองค์จะทรงโปรดยกความผิดซึ่งเจ้าคิดในใจของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 23, 'ด้วยเราเห็นว่าเจ้าจะต้องรับความขมขื่นและติดพันธนะแห่งความชั่วช้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 24, 'ฝ่ายซีโมนจึงตอบว่า “ขอท่านอธิษฐานต่อองค์พระผู้เป็นเจ้าเผื่อข้าพเจ้าด้วย เพื่อเหตุการณ์ที่ท่านได้กล่าวแล้วนั้นจะไม่ได้อุบัติแก่ตัวข้าพเจ้าสักอย่างเดียว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 25, 'ครั้นพวกอัครสาวกเป็นพยานและประกาศพระวจนะขององค์พระผู้เป็นเจ้าแล้ว ก็กลับไปยังกรุงเยรูซาเล็ม และได้ประกาศข่าวประเสริฐตามทางในหมู่บ้านชาวสะมาเรียหลายแห่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 26, 'แต่ทูตสวรรค์ขององค์พระผู้เป็นเจ้าได้สั่งฟีลิปว่า “จงลุกขึ้นไปยังทิศใต้ตามทางที่ลงไปจากกรุงเยรูซาเล็มถึงเมืองกาซา ซึ่งเป็นทางป่าทราย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 27, 'ฝ่ายฟีลิปก็ลุกขึ้นไป และดูเถิด มีชาวเอธิโอเปียคนหนึ่งเป็นขันที เป็นข้าราชการของพระนางคานดาสี พระราชินีของชาวเอธิโอเปีย และเป็นนายคลังทรัพย์ทั้งหมดของพระราชินีนั้น ได้มานมัสการในกรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 28, 'ขณะนั่งรถม้ากลับไป ท่านอ่านหนังสืออิสยาห์ศาสดาพยากรณ์อยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 29, 'ฝ่ายพระวิญญาณตรัสสั่งฟีลิปว่า “จงเข้าไปให้ชิดรถม้านั้นเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 30, 'ฟีลิปจึงวิ่งเข้าไปใกล้ และได้ยินท่านอ่านหนังสืออิสยาห์ศาสดาพยากรณ์ จึงถามว่า “ซึ่งท่านอ่านนั้นท่านเข้าใจหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 31, 'ขันทีจึงตอบว่า “ถ้าไม่มีใครอธิบายให้ ที่ไหนจะเข้าใจได้” ท่านจึงเชิญฟีลิปขึ้นนั่งรถกับท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 32, 'พระคัมภีร์ตอนที่ท่านอ่านอยู่นั้นคือข้อเหล่านี้ ‘เขาได้นําท่านเหมือนแกะที่ถูกนําไปฆ่า และเหมือนลูกแกะที่เป็นใบ้อยู่หน้าผู้ตัดขนของมันฉันใด ท่านก็ไม่ปริปากของท่านเลยฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 33, 'ในคราวที่ท่านถูกเหยียดลงนั้น ท่านไม่ได้รับความยุติธรรมเสียเลย และผู้ใดเล่าจะประกาศเกี่ยวกับพงศ์พันธุ์ของท่าน เพราะว่าชีวิตของท่านต้องถูกตัดเสียจากแผ่นดินโลกแล้ว’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 34, 'ขันทีจึงถามฟีลิปว่า “ศาสดาพยากรณ์ได้กล่าวอย่างนั้นเล็งถึงผู้ใด เล็งถึงตัวท่านเอง หรือเล็งถึงผู้อื่น บอกข้าพเจ้าเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 35, 'ฝ่ายฟีลิปจึงเริ่มต้นเล่าเรื่องกล่าวตามพระคัมภีร์ข้อนั้น ชี้แจงถึงเรื่องพระเยซู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 36, 'ครั้นกําลังเดินทางไปก็มาถึงที่มีน้ําแห่งหนึ่ง ขันทีจึงบอกว่า “ดูเถิด มีน้ํา มีอะไรขัดข้องไม่ให้ข้าพเจ้ารับบัพติศมา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 37, 'และฟีลิปจึงตอบว่า “ถ้าท่านเต็มใจเชื่อท่านก็รับได้” และขันทีจึงตอบว่า “ข้าพเจ้าเชื่อว่า พระเยซูคริสต์เป็นพระบุตรของพระเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 38, 'แล้วท่านจึงสั่งให้หยุดรถม้า และคนทั้งสองลงไปในน้ําทั้งฟีลิปกับขันที ฟีลิปก็ให้ท่านรับบัพติศมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 39, 'เมื่อท่านทั้งสองขึ้นจากน้ําแล้ว พระวิญญาณขององค์พระผู้เป็นเจ้าทรงรับฟีลิปไปเสีย และขันทีนั้นไม่ได้เห็นท่านอีก จึงเดินทางต่อไปด้วยความยินดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 40, 'แต่มีผู้ได้พบฟีลิปที่เมืองอาโซทัส และเมื่อเดินทางมา ท่านได้ประกาศข่าวประเสริฐในทุกเมืองจนท่านมาถึงเมืองซีซารียา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 1, 'ฝ่ายเซาโลยังขู่คํารามกล่าวว่าจะฆ่าศิษย์ขององค์พระผู้เป็นเจ้าเสีย จึงไปหามหาปุโรหิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 2, 'ขอหนังสือไปยังธรรมศาลาในเมืองดามัสกัส เพื่อว่าถ้าพบผู้ใดถือทางนั้นไม่ว่าชายหรือหญิง จะได้จับมัดพามายังกรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 3, 'เมื่อเซาโลเดินทางไปใกล้จะถึงเมืองดามัสกัส ในทันใดนั้นมีแสงสว่างส่องมาจากฟ้าล้อมตัวเขาไว้รอบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 4, 'เซาโลจึงล้มลงถึงดินและได้ยินพระสุรเสียงตรัสแก่เขาว่า “เซาโล เซาโลเอ๋ย เจ้าข่มเหงเราทําไม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 5, 'เซาโลจึงทูลถามว่า “พระองค์เจ้าข้า พระองค์ทรงเป็นผู้ใด” องค์พระผู้เป็นเจ้าตรัสว่า “เราคือเยซู ที่เจ้าข่มเหง ซึ่งเจ้าถีบประตักก็ยากนัก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 6, 'เซาโลก็ตัวสั่นและรู้สึกประหลาดใจจึงถามว่า “พระองค์เจ้าข้า พระองค์ประสงค์จะให้ข้าพระองค์ทําอะไร” องค์พระผู้เป็นเจ้าตรัสแก่เขาว่า “เจ้าจงลุกขึ้นเข้าไปในเมือง และจะมีคนบอกให้รู้ว่า เจ้าจะต้องทําประการใด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 7, 'คนทั้งหลายที่เดินทางไปด้วยกันก็ยืนนิ่งพูดไม่ออก ได้ยินพระสุรเสียงนั้นแต่ไม่เห็นใคร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 8, 'ฝ่ายเซาโลได้ลุกขึ้นจากพื้นดิน เมื่อลืมตาแล้วก็มองอะไรไม่เห็น เขาจึงจูงมือท่านไปยังเมืองดามัสกัส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 9, 'ตาท่านก็มืดมัวไปถึงสามวันและท่านมิได้กินหรือดื่มอะไรเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 10, 'ในเมืองดามัสกัสมีศิษย์คนหนึ่งชื่ออานาเนีย องค์พระผู้เป็นเจ้าได้ตรัสกับผู้นั้นโดยนิมิตว่า “อานาเนียเอ๋ย” อานาเนียจึงทูลตอบว่า “พระองค์เจ้าข้า ดูเถิด ข้าพระองค์อยู่ที่นี่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 11, 'องค์พระผู้เป็นเจ้าจึงตรัสกับเขาว่า “จงลุกขึ้น ไปที่ถนนที่เรียกว่าถนนตรง ถามหาชายคนหนึ่งชื่อเซาโลชาวเมืองทาร์ซัสอยู่ในบ้านของยูดาส เพราะดูเถิด เขากําลังอธิษฐานอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 12, 'และในนิมิตเขาได้เห็นคนหนึ่งชื่ออานาเนียเข้ามาวางมือบนเขา เพื่อเขาจะเห็นได้อีก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 13, 'แต่อานาเนียทูลตอบว่า “พระองค์เจ้าข้า ข้าพระองค์ได้ยินหลายคนพูดถึงคนนั้นว่า เขาได้ทําร้ายวิสุทธิชนของพระองค์ในกรุงเยรูซาเล็มมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 14, 'และในที่นี่เขาได้อํานาจมาจากพวกปุโรหิตใหญ่ ให้ผูกมัดคนทั้งปวงที่ร้องออกพระนามของพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 15, 'ฝ่ายองค์พระผู้เป็นเจ้าได้ตรัสกับท่านว่า “จงไปเถิด เพราะว่าคนนั้นเป็นภาชนะที่เราได้เลือกสรรไว้ สําหรับจะนํานามของเราไปยังประชาชาติ กษัตริย์และชนชาติอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 16, 'เพราะว่าเราจะสําแดงให้เขาเห็นว่า เขาจะต้องทนทุกข์ลําบากมากเท่าใดเพราะนามของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 17, 'แล้วอานาเนียก็ไป และเข้าไปในบ้านวางมือบนเซาโลกล่าวว่า “พี่เซาโลเอ๋ย องค์พระผู้เป็นเจ้าคือพระเยซู ได้ทรงปรากฏแก่ท่านกลางทางที่ท่านมานั้น ได้ทรงใช้ข้าพเจ้ามาเพื่อท่านจะเห็นได้อีก และเพื่อท่านจะประกอบด้วยพระวิญญาณบริสุทธิ์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 18, 'และในทันใดนั้นมีอะไรเหมือนเกล็ดตกจากตาของเซาโล แล้วก็เห็นได้อีก ท่านจึงลุกขึ้นรับบัพติศมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 19, 'พอรับประทานอาหารแล้วก็มีกําลังขึ้น เซาโลพักอยู่กับพวกศิษย์ในเมืองดามัสกัสหลายวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 20, 'และโดยทันทีทันใดท่านประกาศตามธรรมศาลา กล่าวเรื่องพระคริสต์ว่า พระองค์ทรงเป็นพระบุตรของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 21, 'คนทั้งหลายที่ได้ยินก็พากันประหลาดใจแล้วว่า “คนนี้มิใช่หรือที่ได้ทําลายคนในกรุงเยรูซาเล็มที่ร้องออกพระนามนี้ และเขามาที่นี่หวังจะผูกมัดพวกนั้นส่งให้พวกปุโรหิตใหญ่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 22, 'แต่เซาโลยิ่งมีกําลังทวีขึ้น และทําให้พวกยิวในเมืองดามัสกัสนิ่งอึ้งอยู่ โดยพิสูจน์ให้เขาเห็นว่า พระเยซูทรงเป็นพระคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 23, 'ครั้นต่อมาอีกหลายวันพวกยิวได้ปรึกษากันจะฆ่าเซาโลเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 24, 'แต่เรื่องการปองร้ายของเขารู้ถึงเซาโล เขาทั้งหลายได้เฝ้าประตูเมือง คอยฆ่าเซาโลทั้งกลางวันและกลางคืน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 25, 'แต่เหล่าสาวกได้ให้เซาโลนั่งในเข่งใหญ่ แล้วหย่อนลงจากกําแพงเมืองในเวลากลางคืน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 26, 'ครั้นเซาโลไปถึงกรุงเยรูซาเล็มแล้ว ท่านใคร่จะคบให้สนิทกับพวกสาวก แต่เขาทั้งหลายกลัว เพราะไม่เชื่อว่าเซาโลเป็นสาวก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 27, 'แต่บารนาบัสได้พาท่านไปหาพวกอัครสาวก แล้วเล่าให้เขาฟังว่าเซาโลได้เห็นองค์พระผู้เป็นเจ้าที่กลางทาง และพระองค์ตรัสแก่ท่าน ท่านจึงประกาศออกพระนามพระเยซูโดยใจกล้าหาญในเมืองดามัสกัส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 28, 'แล้วเซาโลเข้านอกออกในอยู่กับพวกอัครสาวกในกรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 29, 'ประกาศออกพระนามของพระเยซูเจ้าด้วยใจกล้าหาญ ท่านพูดไล่เลียงกับพวกกรีก แต่พวกนั้นหาช่องที่จะฆ่าท่านเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 30, 'เมื่อพี่น้องรู้อย่างนั้นจึงพาท่านไปยังเมืองซีซารียา แล้วส่งไปยังเมืองทาร์ซัส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 31, 'เหตุฉะนั้น คริสตจักรตลอดทั่วแคว้นยูเดีย กาลิลี และสะมาเรีย จึงมีความสงบสุขและเจริญขึ้น ดําเนินชีวิตด้วยใจยําเกรงองค์พระผู้เป็นเจ้า และได้รับความปลอบประโลมใจจากพระวิญญาณบริสุทธิ์ คริสตสมาชิกก็ยิ่งทวีมากขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 32, 'ต่อมาเมื่อเปโตรเที่ยวไปตลอดทุกแห่งแล้ว ก็ลงมาหาพวกวิสุทธิชนซึ่งอาศัยอยู่ในเมืองลิดดาด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 33, 'เปโตรพบชายคนหนึ่งชื่อไอเนอัสที่นั่น เขาเป็นอัมพาตอยู่กับที่นอนแปดปีมาแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 34, 'เปโตรจึงกล่าวแก่เขาว่า “ไอเนอัสเอ๋ย พระเยซูคริสต์ทรงโปรดท่านให้หายโรค จงลุกขึ้นเก็บที่นอนของท่านเถิด” ในทันใดนั้นไอเนอัสได้ลุกขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 35, 'ฝ่ายคนทั้งปวงที่อยู่ในเมืองลิดดา และที่ราบชาโรนได้เห็นแล้วจึงกลับใจมาหาองค์พระผู้เป็นเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 36, 'ในเมืองยัฟฟามีหญิงคนหนึ่งเป็นศิษย์ชื่อทาบิธา ซึ่งแปลว่าโดรคัส หญิงคนนี้เคยกระทําการอันเป็นคุณประโยชน์และให้ทานมากมาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 37, 'ต่อมาระหว่างนั้นหญิงคนนี้ก็ป่วยลงจนถึงแก่ความตาย เขาจึงอาบน้ําศพวางไว้ในห้องชั้นบน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 38, 'เมืองลิดดาอยู่ใกล้กับเมืองยัฟฟา พวกสาวกได้ยินว่าเปโตรอยู่ที่นั่น จึงใช้ชายสองคนไปหาท่าน เชิญท่านมาหาเขาโดยเร็ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 39, 'ฝ่ายเปโตรจึงลุกขึ้นไปกับเขา เมื่อถึงแล้วเขาพาท่านขึ้นไปในห้องชั้นบน และบรรดาหญิงม่ายได้ยืนอยู่กับท่านพากันร้องไห้และชี้ให้ท่านดูเสื้อคลุมกับเสื้อผ้าต่างๆซึ่งโดรคัสทําเมื่อยังมีชีวิตอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 40, 'ฝ่ายเปโตรให้คนทั้งปวงออกไปข้างนอก และได้คุกเข่าลงอธิษฐาน แล้วหันมายังศพนั้นกล่าวว่า “ทาบิธาเอ๋ย จงลุกขึ้น” ทาบิธาก็ลืมตา เมื่อเห็นเปโตรจึงลุกขึ้นนั่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 41, 'ฝ่ายเปโตรยื่นมือออกพยุงเธอขึ้น จึงเรียกวิสุทธิชนทั้งหลายกับพวกหญิงม่ายเข้ามา แล้วมอบหญิงที่เป็นขึ้นนั้นให้กับเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 42, 'เหตุการณ์นั้นลือไปตลอดทั่วเมืองยัฟฟา คนเป็นอันมากมาเชื่อถือองค์พระผู้เป็นเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 43, 'ต่อมาฝ่ายเปโตรอาศัยอยู่ในเมืองยัฟฟาหลายวัน อยู่กับคนหนึ่งชื่อซีโมนเป็นช่างฟอกหนัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 1, 'ยังมีชายคนหนึ่งชื่อโครเนลิอัส อาศัยอยู่ในเมืองซีซารียา เป็นนายร้อยอยู่ในกองทหารที่เรียกว่ากองอิตาเลีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 2, 'เป็นคนมีศรัทธามาก คือท่านและทั้งครอบครัวเป็นคนยําเกรงพระเจ้า ท่านเคยให้ทานมากมายแก่ประชาชน และอธิษฐานต่อพระเจ้าเสมอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 3, 'เวลาประมาณบ่ายสามโมงนายร้อยนั้นเห็นนิมิตแจ่มกระจ่าง คือเห็นทูตสวรรค์องค์หนึ่งของพระเจ้า เข้ามาหาท่านและกล่าวแก่ท่านว่า “โครเนลิอัสเอ๋ย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 4, 'และเมื่อโครเนลิอัสเขม้นดูทูตสวรรค์องค์นั้นด้วยความตกใจกลัว จึงถามว่า “นี่เป็นประการใด พระองค์เจ้าข้า” ทูตสวรรค์จึงตอบท่านว่า “คําอธิษฐานและทานของท่านนั้น ได้ขึ้นไปเป็นที่ระลึกถึงจําเพาะพระพักตร์พระเจ้าแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 5, 'บัดนี้จงใช้คนไปยังเมืองยัฟฟาเชิญซีโมนที่เรียกว่าเปโตรมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 6, 'เปโตรอาศัยอยู่กับคนหนึ่งชื่อซีโมนเป็นช่างฟอกหนัง บ้านของเขาอยู่ริมฝั่งทะเล เปโตรจะบอกท่านว่าท่านควรจะทําอะไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 7, 'ครั้นทูตสวรรค์ที่ได้พูดกับโครเนลิอัสไปแล้ว ท่านได้เรียกคนใช้สองคนกับทหารคนหนึ่งซึ่งเป็นคนมีศรัทธามาก ที่เคยปรนนิบัติท่านเสมอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 8, 'และเมื่อโครเนลิอัสได้เล่าเหตุการณ์ทั้งปวงให้คนเหล่านั้นฟังแล้ว ท่านจึงใช้เขาไปยังเมืองยัฟฟา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 9, 'วันรุ่งขึ้นคนเหล่านั้นกําลังเดินทางไปใกล้เมืองยัฟฟาแล้ว ประมาณเวลาเที่ยงวันเปโตรก็ขึ้นไปบนหลังคาบ้านเพื่อจะอธิษฐาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 10, 'ก็หิวอยากจะรับประทานอาหาร แต่ในระหว่างที่เขายังจัดอาหารอยู่ เปโตรได้เคลิ้มไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 11, 'และได้เห็นท้องฟ้าแหวกออกเป็นช่อง มีภาชนะอย่างหนึ่งเหมือนผ้าผืนใหญ่ ผูกติดกันทั้งสี่มุมหย่อนลงมายังพื้นโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 12, 'ในนั้นมีสัตว์ทุกอย่างที่อยู่บนแผ่นดิน คือสัตว์สี่เท้า สัตว์ป่า สัตว์เลื้อยคลานและนกที่อยู่ในท้องฟ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 13, 'มีพระสุรเสียงมาว่าแก่ท่านว่า “เปโตรเอ๋ย จงลุกขึ้นฆ่ากินเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 14, 'ฝ่ายเปโตรจึงทูลว่า “มิได้ พระองค์เจ้าข้า เพราะว่าสิ่งซึ่งเป็นของต้องห้ามหรือของมลทินนั้น ข้าพระองค์ไม่เคยได้รับประทานเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 15, 'แล้วจึงมีพระสุรเสียงอีกเป็นครั้งที่สองว่าแก่ท่านว่า “ซึ่งพระเจ้าได้ทรงชําระแล้ว อย่าว่าเป็นของต้องห้าม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 16, 'เห็นอย่างนั้นถึงสามครั้ง แล้วสิ่งนั้นก็ถูกรับขึ้นไปอีกในท้องฟ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 17, 'เมื่อเปโตรยังคิดสงสัยเรื่องนิมิตที่เห็นนั้นว่ามีความหมายอย่างไร ดูเถิด คนที่โครเนลิอัสใช้ไปนั้น เมื่อถามหาและพบบ้านของซีโมนแล้วก็มายืนอยู่หน้าประตูรั้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 18, 'และร้องถามว่า ซีโมนที่เรียกว่าเปโตรอยู่ที่นั่นหรือไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 19, 'เมื่อเปโตรตริตรองเรื่องนิมิตนั้น พระวิญญาณก็ตรัสกับท่านว่า “ดูเถิด ชายสามคนตามหาเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 20, 'จงลุกขึ้นลงไปข้างล่างและไปกับเขาเถิด อย่าลังเลใจเลย เพราะว่าเราได้ใช้เขามา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 21, 'เปโตรจึงลงไปหาคนเหล่านั้นซึ่งโครเนลิอัสได้ใช้มากล่าวว่า “ดูเถิด ข้าพเจ้าเป็นคนที่ท่านมาหานั้น ท่านมาธุระอะไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 22, 'เขาจึงตอบว่า “นายร้อยโครเนลิอัส เป็นคนชอบธรรมและเกรงกลัวพระเจ้า และเป็นคนมีชื่อเสียงดีในบรรดาชาวยิว โครเนลิอัสผู้นั้นได้รับคําเตือนจากพระเจ้าโดยผ่านทูตสวรรค์บริสุทธิ์ ให้มาเชิญท่านไปที่บ้านเพื่อจะฟังถ้อยคําของท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 23, 'เปโตรจึงเชิญเขาให้เข้ามาหยุดพักอยู่ที่นั่น วันรุ่งขึ้นเปโตรก็ไปกับเขาและพวกพี่น้องบางคนที่เมืองยัฟฟาก็ไปด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 24, 'ล่วงมาอีกวันหนึ่งเขาก็ไปถึงเมืองซีซารียา โครเนลิอัสกําลังคอยรับรองอยู่ และเชิญญาติพี่น้องกับเพื่อนสนิทให้มาประชุมกันอยู่แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 25, 'ครั้นเปโตรเข้าไป โครเนลิอัสก็ต้อนรับเปโตร และหมอบที่เท้ากราบไหว้ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 26, 'ฝ่ายเปโตรจึงจับตัวโครเนลิอัสให้ลุกขึ้นและกล่าวว่า “จงยืนขึ้นเถิด ข้าพเจ้าก็เป็นแต่มนุษย์เหมือนกัน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 27, 'เมื่อกําลังสนทนากันอยู่ เปโตรจึงเข้าไปแลเห็นคนเป็นอันมากมาพร้อมกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 28, 'จึงกล่าวแก่คนเหล่านั้นว่า “ท่านทั้งหลายทราบแล้วว่า คนชาติยิวนั้นจะคบให้สนิทกับคนต่างชาติหรือเข้าเยี่ยมก็เป็นที่พระราชบัญญัติห้ามไว้ แต่พระเจ้าได้ทรงสําแดงแก่ข้าพเจ้าแล้วว่า ไม่ควรเรียกคนหนึ่งคนใดว่าเป็นที่ห้ามหรือมลทิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 29, 'เหตุฉะนั้น เมื่อท่านใช้คนไปเรียกข้าพเจ้า ข้าพเจ้าก็มาโดยไม่ขัด ข้าพเจ้าจึงขอถามว่าท่านเรียกข้าพเจ้ามาด้วยประสงค์อะไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 30, 'โครเนลิอัสจึงตอบว่า “สี่วันมาแล้ว ข้าพเจ้ากําลังถืออดอาหารอยู่จนถึงเวลานี้ และประมาณเวลาบ่ายสามโมงข้าพเจ้าได้อธิษฐานอยู่ในบ้านของข้าพเจ้า ดูเถิด มีชายคนหนึ่งยืนอยู่ตรงหน้าข้าพเจ้าสวมเสื้อมันระยับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 31, 'ผู้นั้นได้กล่าวว่า ‘โครเนลิอัสเอ๋ย คําอธิษฐานของท่านนั้นทรงสดับฟังแล้ว และทานของท่านนั้นก็เป็นที่ระลึกถึงในสายพระเนตรของพระเจ้าแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 32, 'เหตุฉะนั้น จงใช้คนไปยังเมืองยัฟฟา เชิญซีโมนที่เรียกว่าเปโตรมา ผู้นั้นอาศัยอยู่ในบ้านของซีโมนช่างฟอกหนังที่ฝั่งทะเล ผู้นั้นเมื่อมาถึงแล้วจะกล่าวแก่ท่าน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 33, 'ข้าพเจ้าจึงใช้คนไปเชิญท่านมาทันที ที่ท่านมาก็ดีแล้ว บัดนี้พวกข้าพเจ้าจึงอยู่พร้อมกันต่อพระพักตร์พระเจ้า เพื่อจะฟังสิ่งสารพัดซึ่งพระเจ้าได้ตรัสสั่งท่านไว้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 34, 'ฝ่ายเปโตรจึงกล่าวว่า “ข้าพเจ้าเห็นจริงแล้วว่า พระเจ้าไม่ทรงเลือกหน้าผู้ใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 35, 'แต่คนใดๆในทุกชาติที่เกรงกลัวพระองค์และประพฤติตามทางชอบธรรมก็เป็นที่ชอบพระทัยพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 36, 'พระดํารัสที่พระเจ้าได้ทรงฝากไว้กับชนชาติอิสราเอล คือการประกาศข่าวดีเรื่องสันติสุขโดยพระเยซูคริสต์ (ผู้เป็นองค์พระผู้เป็นเจ้าของคนทั้งปวง)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 37, 'ข้าพเจ้ากล่าวว่า พระดํารัสนั้นท่านทั้งหลายก็รู้ คือเรื่องที่ได้เล่ากันตั้งแต่ต้นที่แคว้นกาลิลี ไปจนตลอดทั่วแคว้นยูเดีย ภายหลังการบัพติศมาที่ยอห์นได้ประกาศนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 38, 'คือเรื่องพระเยซูชาวนาซาเร็ธว่า พระเจ้าได้ทรงเจิมพระองค์ด้วยพระวิญญาณบริสุทธิ์และด้วยฤทธานุภาพอย่างไร และพระเยซูเสด็จไปกระทําคุณประโยชน์และรักษาบรรดาคนซึ่งถูกพญามารเบียดเบียน ด้วยว่าพระเจ้าได้ทรงสถิตกับพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 39, 'เราทั้งหลายเป็นพยานถึงกิจการทั้งปวง ซึ่งพระองค์ทรงกระทําในแผ่นดินของชนชาติยิวและในกรุงเยรูซาเล็ม พระองค์นั้นเขาได้ฆ่าและแขวนไว้ที่ต้นไม้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 40, 'ในวันที่สามพระเจ้าได้ทรงให้พระองค์คืนพระชนม์และทรงให้ปรากฏ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 41, 'มิใช่ทรงให้ปรากฏแก่คนทั่วไป แต่ทรงปรากฏแก่เหล่าพวกพยานซึ่งพระเจ้าได้ทรงเลือกไว้แต่ก่อน คือทรงปรากฏแก่พวกเราที่ได้รับประทานและดื่มกับพระองค์ เมื่อพระองค์ทรงคืนพระชนม์แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 42, 'พระองค์ทรงสั่งให้เราทั้งหลายประกาศแก่คนทั้งปวง และเป็นพยานว่าพระเจ้าได้ทรงตั้งพระองค์ไว้เป็นผู้พิพากษาทั้งคนเป็นและคนตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 43, 'ศาสดาพยากรณ์ทั้งหลายย่อมเป็นพยานถึงพระองค์ว่า ผู้ใดที่เชื่อถือในพระองค์นั้นจะได้รับการทรงยกความผิดบาปของเขา เพราะพระนามของพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 44, 'เมื่อเปโตรยังกล่าวคําเหล่านั้นอยู่ พระวิญญาณบริสุทธิ์ก็เสด็จลงมาสถิตกับคนทั้งปวงที่ฟังพระวจนะนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 45, 'ฝ่ายพวกที่ได้เข้าสุหนัตซึ่งเชื่อถือแล้ว คือคนที่มาด้วยกันกับเปโตรก็ประหลาดใจ เพราะว่าของประทานแห่งพระวิญญาณบริสุทธิ์ได้ลงมาบนคนต่างชาติด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 46, 'เพราะเขาได้ยินคนเหล่านั้นพูดภาษาต่างๆและยกย่องสรรเสริญพระเจ้า เปโตรจึงย้อนถามว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 47, '“ใครอาจจะห้ามคนเหล่านี้ที่ได้รับพระวิญญาณบริสุทธิ์เหมือนเรา โดยมิให้เขารับบัพติศมาด้วยน้ําได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 48, 'เปโตรจึงสั่งให้เขารับบัพติศมาในพระนามขององค์พระผู้เป็นเจ้า และเขาทั้งหลายได้ขอให้เปโตรยับยั้งอยู่กับเขาอีกสองสามวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 1, 'ฝ่ายพวกอัครสาวกกับพี่น้องทั้งหลายที่อยู่ในแคว้นยูเดียได้ยินว่า คนต่างชาติได้รับพระวจนะของพระเจ้าเหมือนกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 2, 'เมื่อเปโตรขึ้นไปยังกรุงเยรูซาเล็มแล้ว พวกที่เข้าสุหนัตจึงต่อว่าท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 3, 'ว่า “ท่านไปหาคนที่ไม่ได้เข้าสุหนัต และรับประทานอาหารกับเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 4, 'แต่เปโตรได้อธิบายให้เขาฟังตั้งแต่ต้นเป็นลําดับมาว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 5, '“เมื่อข้าพเจ้าอยู่ในเมืองยัฟฟาและกําลังอธิษฐานก็เคลิ้มไป แล้วนิมิตเห็นภาชนะอย่างหนึ่ง เหมือนผ้าผืนใหญ่หย่อนลงมาทั้งสี่มุมจากฟ้ามายังข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 6, 'ครั้นข้าพเจ้าเขม้นดูผ้านั้น ข้าพเจ้าได้พินิจพิจารณาก็ได้เห็นสัตว์สี่เท้าของแผ่นดิน กับสัตว์ป่า สัตว์เลื้อยคลาน และนกที่อยู่ในท้องฟ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 7, 'แล้วข้าพเจ้าได้ยินพระสุรเสียงตรัสกับข้าพเจ้าว่า ‘เปโตรเอ๋ย จงลุกขึ้น ฆ่ากินเถิด’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 8, 'แต่ข้าพเจ้าทูลว่า ‘หามิได้ พระองค์เจ้าข้า เพราะว่าสิ่งของซึ่งต้องห้ามหรือซึ่งเป็นมลทินยังไม่ได้เข้าปากข้าพระองค์เลย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 9, 'แต่มีพระสุรเสียงตรัสจากฟ้าครั้งที่สองว่า ‘ซึ่งพระเจ้าได้ทรงชําระแล้ว เจ้าอย่าว่าเป็นของต้องห้าม’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 10, 'เป็นอย่างนั้นถึงสามครั้ง แล้วสิ่งนั้นทั้งสิ้นก็ถูกรับขึ้นไปบนฟ้าอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 11, 'ดูเถิด ในทันใดนั้นมีชายสามคนมายืนอยู่ตรงหน้าบ้านที่ข้าพเจ้าอยู่ รับใช้มาจากเมืองซีซารียามาหาข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 12, 'พระวิญญาณจึงสั่งให้ข้าพเจ้าไปกับเขาโดยไม่ลังเลใจเลย และพวกพี่น้องทั้งหกคนนี้ได้ไปกับข้าพเจ้าด้วย เราทั้งหลายจึงเข้าไปในบ้านของผู้นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 13, 'ผู้นั้นจึงกล่าวแก่พวกเราว่า ตัวท่านได้เห็นทูตสวรรค์องค์หนึ่งยืนอยู่ในบ้านของท่าน และบอกท่านว่า ‘จงใช้คนไปยังเมืองยัฟฟา เชิญซีโมนที่เรียกว่าเปโตรมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 14, 'เปโตรนั้นจะกล่าวให้ท่านฟังเป็นถ้อยคําซึ่งจะให้ท่านกับทั้งครอบครัวของท่านรอด’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 15, 'เมื่อข้าพเจ้าตั้งต้นกล่าวข้อความนั้น พระวิญญาณบริสุทธิ์ก็เสด็จมาสถิตกับเขาทั้งหลาย เหมือนได้เสด็จลงมาบนพวกเราในตอนต้นนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 16, 'แล้วข้าพเจ้าได้ระลึกถึงคําตรัสขององค์พระผู้เป็นเจ้า ซึ่งพระองค์ตรัสไว้ว่า ‘ยอห์นให้รับบัพติศมาด้วยน้ําก็จริง แต่ท่านทั้งหลายจะรับบัพติศมาด้วยพระวิญญาณบริสุทธิ์’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 17, 'เหตุฉะนั้น ถ้าพระเจ้าได้ทรงโปรดประทานของประทานแก่เขาเหมือนแก่เราทั้งหลาย ผู้ที่ได้เชื่อในพระเยซูคริสต์เจ้า ข้าพเจ้าเป็นผู้ใดเล่าที่จะขัดขืนพระเจ้าได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 18, 'ครั้นคนทั้งหลายได้ยินคําเหล่านั้นก็นิ่งอยู่ แล้วได้สรรเสริญพระเจ้าว่า “พระเจ้าได้ทรงโปรดแก่คนต่างชาติให้กลับใจใหม่จนได้ชีวิตรอดด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 19, 'ฝ่ายคนทั้งหลายที่กระจัดกระจายไปเพราะการเคี่ยวเข็ญเนื่องจากสเทเฟน ก็พากันไปยังเมืองฟีนิเซีย เกาะไซปรัส และเมืองอันทิโอก และไม่ได้กล่าวพระวจนะแก่ผู้ใดนอกจากแก่ยิวพวกเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 20, 'และมีบางคนในพวกเขาเป็นชาวเกาะไซปรัสกับชาวไซรีน เมื่อมายังเมืองอันทิโอก ก็ได้กล่าวประกาศข่าวประเสริฐเรื่องพระเยซูเจ้าแก่พวกกรีกด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 21, 'และพระหัตถ์ขององค์พระผู้เป็นเจ้าทรงอยู่กับเขา คนเป็นอันมากได้เชื่อและกลับมาหาองค์พระผู้เป็นเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 22, 'ข่าวนี้ก็เล่าลือไปยังคริสตจักรในกรุงเยรูซาเล็ม เขาจึงใช้บารนาบัสให้ไปยังเมืองอันทิโอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 23, 'เมื่อบารนาบัสมาถึงแล้ว และได้เห็นพระคุณของพระเจ้าก็ปีติยินดี จึงได้เตือนคนเหล่านั้นให้ตั้งมั่นคงติดสนิทอยู่กับองค์พระผู้เป็นเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 24, 'บารนาบัสเป็นคนดี ประกอบด้วยพระวิญญาณบริสุทธิ์และความเชื่อ จํานวนคนเป็นอันมากก็เพิ่มเข้ากับองค์พระผู้เป็นเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 25, 'บารนาบัสได้ไปที่เมืองทาร์ซัสเพื่อตามหาเซาโล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 26, 'เมื่อพบแล้วจึงพาเขามายังเมืองอันทิโอก ต่อมาท่านทั้งสองได้ประชุมกันกับคริสตจักรตลอดปีหนึ่ง ได้สั่งสอนคนเป็นอันมากและในเมืองอันทิโอกนั่นเอง พวกสาวกได้ชื่อว่าคริสเตียนเป็นครั้งแรก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 27, 'คราวนี้มีพวกศาสดาพยากรณ์ลงมาจากกรุงเยรูซาเล็มจะไปยังเมืองอันทิโอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 28, 'ฝ่ายผู้หนึ่งในจํานวนนั้นชื่ออากาบัส ได้ลุกขึ้นกล่าวโดยพระวิญญาณว่าจะบังเกิดการกันดารอาหารมากยิ่งทั่วแผ่นดินโลก การกันดารอาหารนั้นได้บังเกิดขึ้นในรัชสมัยคลาวดิอัส ซีซาร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 29, 'พวกสาวกทุกคนจึงตกลงใจกันว่า จะถวายตามกําลังฝากไปช่วยบรรเทาทุกข์พวกพี่น้องที่อยู่ในแคว้นยูเดีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 30, 'เขาจึงได้ทําดังนั้น และฝากไปกับบารนาบัสและเซาโลเพื่อนําไปให้พวกผู้ปกครอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 1, 'แล้วคราวนั้นกษัตริย์เฮโรดได้เหยียดพระหัตถ์ออกทําร้ายบางคนในคริสตจักร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 2, 'ท่านได้ฆ่ายากอบพี่ชายของยอห์นด้วยดาบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 3, 'เมื่อท่านเห็นว่าการนั้นเป็นที่ชอบใจพวกยิว ท่านก็จับเปโตรด้วย (นี่เป็นระหว่างเทศกาลขนมปังไร้เชื้อ)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 4, 'เมื่อจับเปโตรแล้วจึงให้จําคุก ให้ทหารสี่หมู่ๆละสี่คนคุมไว้ ตั้งใจว่าเมื่อสิ้นเทศกาลอีสเตอร์แล้วจะพาออกมาให้แก่คนทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 5, 'เพราะฉะนั้นเปโตรจึงถูกจําไว้ในคุก แต่ว่าคริสตจักรได้อธิษฐานต่อพระเจ้าเพื่อเปโตรโดยไม่หยุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 6, 'ในคืนวันนั้นเอง ครั้นเฮโรดจะพาเปโตรออกมา เปโตรนอนหลับอยู่ระหว่างทหารสองคน มีโซ่สองเส้นล่ามไว้ และคนยามเฝ้าอยู่หน้าประตูคุก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 7, 'ดูเถิด มีทูตสวรรค์ขององค์พระผู้เป็นเจ้ามาปรากฏ และมีแสงสว่างส่องเข้ามาในคุก ทูตองค์นั้นจึงกระตุ้นเปโตรที่สีข้างให้ตื่นขึ้นแล้วว่า “จงลุกขึ้นเร็วๆ” โซ่นั้นก็หลุดตกจากมือของเปโตร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 8, 'ทูตสวรรค์องค์นั้นจึงสั่งเปโตรว่า “จงคาดเอวและสวมรองเท้า” เปโตรก็ทําตาม ทูตองค์นั้นจึงสั่งเปโตรว่า “จงห่มผ้าและตามเรามาเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 9, 'เปโตรจึงตามออกไป และไม่รู้ว่าการซึ่งทูตสวรรค์ทํานั้นเป็นความจริง แต่คิดว่าได้เห็นนิมิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 10, 'เมื่อออกไปพ้นทหารยามชั้นที่หนึ่งและที่สองแล้ว ก็มาถึงประตูเหล็กที่จะเข้าไปในเมือง ประตูนั้นก็เปิดเองให้ท่านทั้งสอง ท่านจึงออกไปเดินตามถนนแห่งหนึ่ง และในทันใดนั้นทูตสวรรค์ก็ได้อันตรธานไปจากเปโตร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 11, 'ครั้นเปโตรรู้สึกตัวแล้วจึงว่า “เดี๋ยวนี้ข้าพเจ้ารู้แน่ว่า องค์พระผู้เป็นเจ้าได้ทรงใช้ทูตสวรรค์ของพระองค์มาช่วยข้าพเจ้าให้พ้นจากพระหัตถ์ของเฮโรด และพ้นจากการมุ่งร้ายของพวกยิว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 12, 'เมื่อเปโตรคิดอย่างนั้นแล้ว ก็มาถึงบ้านของมารีย์มารดาของยอห์นผู้มีชื่ออีกว่า มาระโก ที่นั่นมีหลายคนได้ประชุมอธิษฐานกันอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 13, 'พอเปโตรเคาะประตูรั้ว มีหญิงสาวคนหนึ่งชื่อโรดามาฟัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 14, 'เมื่อจําได้ว่าเป็นเสียงของเปโตร เพราะความยินดีก็ยังไม่เปิดประตู แต่วิ่งเข้าไปบอกว่า เปโตรยืนอยู่หน้าประตู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 15, 'คนทั้งหลายจึงพูดกับหญิงนั้นว่า “เจ้าเป็นบ้า” แต่หญิงคนนั้นยืนยันว่าเป็นอย่างนั้นจริง เขาทั้งหลายจึงว่า “เป็นทูตสวรรค์ประจําตัวเปโตร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 16, 'ฝ่ายเปโตรยังยืนเคาะประตูอยู่ เมื่อเขาเปิดประตูเห็นท่าน ก็อัศจรรย์ใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 17, 'แต่เปโตรโบกมือให้เขานิ่ง และเล่าให้เขาฟังถึงเรื่องที่องค์พระผู้เป็นเจ้าได้ทรงพาท่านออกจากคุกอย่างไร แล้วท่านสั่งว่า “จงไปบอกเรื่องนี้แก่ยากอบกับพวกพี่น้องให้ทราบ” เปโตรจึงออกไปเสียที่อื่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 18, 'แล้วครั้นรุ่งเช้า พวกทหารก็ขวัญหนีดีฝ่อมิใช่น้อย ว่าเปโตรหายไปไหน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 19, 'เมื่อเฮโรดหาตัวเปโตรไม่พบ จึงไต่สวนพวกทหารยามและรับสั่งให้ฆ่าเสีย ฝ่ายเฮโรดก็ออกจากแคว้นยูเดีย ลงไปพักอยู่ที่เมืองซีซารียา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 20, 'ฝ่ายเฮโรดกริ้วชาวเมืองไทระและเมืองไซดอน แต่ชาวเมืองนั้นได้พากันมาหาท่าน เมื่อได้เอาใจบลัสทัสกรมวังของกษัตริย์แล้ว จึงได้ขอกลับเป็นไมตรีกันอีก เพราะว่าเมืองของเขาต้องอาศัยอาหารเลี้ยงชีพจากแผ่นดินของกษัตริย์นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 21, 'เมื่อถึงวันนัด เฮโรดทรงเครื่องกษัตริย์เสด็จประทับบนราชบัลลังก์ แล้วมีพระราชดํารัสแก่เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 22, 'คนทั้งหลายจึงร้องขึ้นว่า “เป็นพระสุรเสียงของพระ มิใช่เสียงมนุษย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 23, 'ในทันใดนั้น ทูตสวรรค์ขององค์พระผู้เป็นเจ้าให้ท่านเกิดโรคร้าย เพราะท่านมิได้ถวายเกียรติยศแด่พระเจ้า แล้วก็มีตัวหนอนกัดกินร่างกายของท่านจนถึงแก่พิราลัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 24, 'แต่พระวจนะของพระเจ้าก็ยังแผ่เจริญมากขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 25, 'ฝ่ายบารนาบัสกับเซาโล เมื่อได้ทําภารกิจที่รับมอบหมายสําเร็จแล้ว จึงจากกรุงเยรูซาเล็มกลับไป พายอห์นผู้มีชื่ออีกว่ามาระโกไปด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 1, 'คราวนั้นในคริสตจักรที่อยู่ในเมืองอันทิโอก มีบางคนที่เป็นผู้พยากรณ์และอาจารย์ มีบารนาบัส สิเมโอนที่เรียกว่านิเกอร์ กับลูสิอัสชาวเมืองไซรีน มานาเอน ผู้ได้รับการเลี้ยงดูเติบโตขึ้นด้วยกันกับเฮโรดเจ้าเมือง และเซาโล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 2, 'เมื่อคนเหล่านั้นกําลังรับใช้องค์พระผู้เป็นเจ้า และถืออดอาหารอยู่ พระวิญญาณบริสุทธิ์ได้ตรัสสั่งว่า “จงตั้งบารนาบัสกับเซาโลไว้สําหรับการซึ่งเราเรียกให้เขาทํานั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 3, 'เมื่อถืออดอาหารและอธิษฐาน และวางมือบนบารนาบัสกับเซาโลแล้ว เขาก็ใช้ท่านไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 4, 'เหตุฉะนั้น ท่านทั้งสองที่ได้รับใช้จากพระวิญญาณบริสุทธิ์จึงลงไปเมืองเซลูเคีย และได้แล่นเรือจากที่นั่นไปยังเกาะไซปรัส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 5, 'ครั้นมาถึงเมืองซาลามิส ท่านได้ประกาศพระวจนะของพระเจ้าในธรรมศาลาของพวกยิว ยอห์นก็อยู่ช่วยด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 6, 'เมื่อได้เดินตลอดเกาะนั้นไปถึงเมืองปาโฟสแล้ว ก็ได้พบคนหนึ่งเป็นคนทําเวทมนตร์ เป็นผู้ทํานายเท็จ เป็นพวกยิวชื่อว่าบารเยซู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 7, 'อยู่กับผู้ว่าราชการเมืองชื่อเสอร์จีอัสเปาโล เป็นคนฉลาดรอบรู้ ผู้ว่าราชการเมืองจึงเชิญบารนาบัสกับเซาโลมา ปรารถนาจะฟังพระวจนะของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 8, 'แต่เอลีมาสคนทําเวทมนตร์ (เพราะชื่อของเขามีความหมายอย่างนั้น) ได้คัดค้านขัดขวางบารนาบัสกับเซาโล หวังจะไม่ให้ผู้ว่าราชการเมืองเชื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 9, 'แต่เซาโล (ที่มีชื่ออีกว่าเปาโล) ประกอบด้วยพระวิญญาณบริสุทธิ์เขม้นดูเอลีมาส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 10, 'และพูดว่า “โอ เจ้าเป็นคนเต็มไปด้วยอุบายและใจร้ายทุกอย่าง ลูกของพญามาร เป็นศัตรูต่อบรรดาความชอบธรรม เจ้าจะไม่หยุดพยายามทําทางตรงขององค์พระผู้เป็นเจ้าให้เขวไปหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 11, 'ดูเถิด บัดนี้พระหัตถ์ขององค์พระผู้เป็นเจ้าก็อยู่บนเจ้า เจ้าจะเป็นคนตาบอดไม่เห็นดวงอาทิตย์จนถึงเวลากําหนด” ทันใดนั้นความมืดมัวก็บังเกิดแก่เอลีมาส เอลีมาสจึงคลําหาคนให้จูงมือไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 12, 'ครั้นผู้ว่าราชการเมืองได้เห็นเหตุการณ์ที่เกิดขึ้นนั้นจึงเชื่อถือ และอัศจรรย์ใจด้วยพระดํารัสสอนขององค์พระผู้เป็นเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 13, 'แล้วเปาโลกับพวกของท่านก็แล่นเรือออกจากเมืองปาโฟสไปยังเมืองเปอร์กาในแคว้นปัมฟีเลีย ยอห์นได้ละพวกนั้นไว้แล้วกลับมายังกรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 14, 'แต่พวกนั้นเดินทางต่อไปจากเมืองเปอร์กาถึงเมืองอันทิโอกในแคว้นปิสิเดีย แล้วได้เข้าไปนั่งลงในธรรมศาลาในวันสะบาโต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 15, 'เมื่ออ่านพระราชบัญญัติกับคําของศาสดาพยากรณ์แล้ว บรรดานายธรรมศาลาจึงใช้คนไปบอกเปาโลกับบารนาบัสว่า “ท่านพี่น้องทั้งหลาย ถ้าท่านมีคํากล่าวเตือนสติแก่คนทั้งปวงก็เชิญกล่าวเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 16, 'ฝ่ายเปาโลจึงยืนขึ้นโบกมือแล้วกล่าวว่า “ท่านที่เป็นชนชาติอิสราเอลและท่านทั้งหลายที่เกรงกลัวพระเจ้า จงฟังเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 17, 'พระเจ้าของชนชาติอิสราเอลนี้ได้ทรงเลือกบรรพบุรุษของเราไว้ และได้ให้เขาเจริญขึ้นครั้งเมื่อยังเป็นคนต่างด้าวในประเทศอียิปต์ และได้ทรงนําเขาออกจากประเทศนั้นด้วยพระกรอันทรงฤทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 18, 'พระองค์ได้ทรงอดทนต่อความประพฤติของเขาในถิ่นทุรกันดารประมาณสี่สิบปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 19, 'เมื่อพระองค์ได้ทรงล้างผลาญชนเจ็ดชาติออกเสียจากแผ่นดินคานาอันแล้ว พระองค์ก็ทรงแบ่งแผ่นดินของชนชาติเหล่านั้นให้เขาโดยการจับฉลาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 20, 'ภายหลังพระองค์ทรงประทานพวกผู้วินิจฉัยแก่เขา เป็นเวลาประมาณสี่ร้อยห้าสิบปี จนถึงซามูเอลศาสดาพยากรณ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 21, 'คราวนั้นเขาทั้งหลายได้ขอให้มีกษัตริย์ พระเจ้าจึงได้ทรงประทานซาอูลบุตรชายคีชจากตระกูลเบนยามิน ให้เป็นกษัตริย์ครบสี่สิบปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 22, 'ครั้นถอดซาอูลแล้วพระองค์ได้ทรงตั้งดาวิดขึ้นเป็นกษัตริย์ของเขา และทรงเป็นพยานกล่าวถึงดาวิดว่า ‘เราได้พบดาวิดบุตรชายของเจสซีเป็นคนที่เราชอบใจ เป็นผู้ที่จะทําให้ความประสงค์ของเราสําเร็จทุกประการ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 23, 'จากเชื้อสายของดาวิด พระเจ้าได้ทรงโปรดให้ผู้ช่วยให้รอด คือพระเยซูเกิดขึ้นแก่ชาติอิสราเอลตามพระสัญญาของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 24, 'ก่อนที่พระองค์เสด็จมา ยอห์นได้ประกาศบัพติศมาอันสําแดงการกลับใจใหม่ให้แก่บรรดาชนชาติอิสราเอล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 25, 'เวลาที่ยอห์นทําการตามหน้าที่ของตนเกือบจะสําเร็จ ท่านจึงถามว่า ‘ท่านทั้งหลายคิดเห็นว่า ข้าพเจ้าคือผู้ใด ข้าพเจ้าเป็นพระองค์นั้นหามิได้ แต่ดูเถิด จะมีพระองค์ผู้หนึ่งมาภายหลังข้าพเจ้า ซึ่งข้าพเจ้าไม่คู่ควรจะแก้สายรัดฉลองพระบาทของพระองค์’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 26, 'ท่านพี่น้องทั้งหลาย ผู้สืบเชื้อสายของอับราฮัม และผู้ใดในพวกท่านซึ่งเกรงกลัวพระเจ้า ข่าวเรื่องความรอดนี้ได้ทรงประทานมาถึงท่านทั้งหลายแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 27, 'ฝ่ายชาวกรุงเยรูซาเล็มกับพวกขุนนางมิได้รู้จักพระองค์ หรือเข้าใจคําของศาสดาพยากรณ์ทั้งหลาย ซึ่งเคยอ่านกันทุกวันสะบาโต จึงทําให้สําเร็จตามคําเหล่านั้นโดยพิพากษาลงโทษพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 28, 'ถึงแม้ว่ามิได้พบความผิดประการใดในพระองค์ที่ควรจะให้ตาย พวกเขายังขอปีลาตให้ปลงพระชนม์พระองค์เสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 29, 'ครั้นทําจนสําเร็จทุกอย่างตามซึ่งมีเขียนไว้แล้วว่าด้วยพระองค์ เขาจึงเชิญพระศพของพระองค์ลงจากต้นไม้ไปประดิษฐานไว้ในอุโมงค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 30, 'แต่พระเจ้าได้ทรงให้พระองค์คืนพระชนม์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 31, 'พระองค์ทรงปรากฏแก่คนทั้งหลายที่ตามพระองค์จากแคว้นกาลิลีไปยังกรุงเยรูซาเล็มเป็นหลายวัน บัดนี้คนเหล่านั้นเป็นพยานข้างพระองค์แก่คนทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 32, 'เรานําข่าวประเสริฐนี้มาแจ้งแก่ท่านทั้งหลายว่า พระสัญญาซึ่งทรงประทานแก่บรรพบุรุษของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 33, 'พระเจ้าได้ทรงให้สําเร็จตามนั้นแก่เราผู้เป็นลูกหลานของคนเหล่านั้น คือในการที่พระองค์ทรงให้พระเยซูกลับคืนพระชนม์ เหมือนมีคําเขียนไว้ในหนังสือสดุดีบทที่สองว่า ‘ท่านเป็นบุตรของเรา วันนี้เราได้ให้กําเนิดแก่ท่านแล้ว’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 34, 'ส่วนข้อที่พระเจ้าได้ทรงให้พระองค์คืนพระชนม์ มิให้กลับเปื่อยเน่าอีกเลย พระองค์จึงตรัสอย่างนี้ว่า ‘เราจะให้ความเมตตาอันแน่นอนของเราซึ่งได้สัญญาไว้กับดาวิดให้แก่ท่าน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 35, 'เพราะพระองค์ตรัสไว้ในสดุดีอื่นว่า ‘พระองค์จะไม่ทรงให้องค์บริสุทธิ์ของพระองค์เปื่อยเน่าไป’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 36, 'ฝ่ายดาวิดเมื่อได้ปฏิบัติในคราวอายุของท่านตามพระทัยของพระเจ้า และได้ล่วงหลับไปแล้ว และต้องฝังไว้กับบรรพบุรุษของท่าน ก็เปื่อยเน่าไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 37, 'แต่พระองค์ซึ่งพระเจ้าได้ทรงให้เป็นขึ้นมานั้น มิได้ประสบความเปื่อยเน่าเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 38, 'เหตุฉะนั้นท่านพี่น้องทั้งหลาย จงเข้าใจเถิดว่า โดยพระองค์นั้นแหละจึงได้ประกาศการยกความผิดแก่ท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 39, 'และโดยพระองค์นั้น ทุกคนที่เชื่อจะพ้นโทษได้ทุกอย่าง ซึ่งจะพ้นไม่ได้โดยพระราชบัญญัติของโมเสส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 40, 'เหตุฉะนั้นจงระวังให้ดี เกลือกว่าคําซึ่งพวกศาสดาพยากรณ์ได้กล่าวไว้นั้นจะได้แก่ท่านทั้งหลาย คือว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 41, '‘ดูก่อนให้เจ้าทั้งหลายผู้ประมาทหมิ่น ประหลาดใจและถึงพินาศ ด้วยว่าเรากระทําการในกาลสมัยของเจ้า เป็นการที่แม้แต่มีผู้มาบอกแล้ว เจ้าก็จะไม่เชื่อเลย’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 42, 'เมื่อพวกยิวได้ออกไปจากธรรมศาลาแล้ว พวกคนต่างชาติก็อ้อนวอนให้ประกาศคําเหล่านั้นให้เขาฟังในวันสะบาโตหน้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 43, 'ครั้นคนที่ประชุมกันนั้นต่างคนต่างไปจากธรรมศาลาแล้ว พวกยิวหลายคนกับคนเข้าจารีตที่เกรงกลัวพระเจ้าได้ตามเปาโลและบารนาบัสไป ท่านทั้งสองจึงพูดกับเขา ชวนให้เขาตั้งมั่นคงอยู่ในพระคุณของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 44, 'ครั้นถึงวันสะบาโตหน้า คนเกือบสิ้นทั้งเมืองได้ประชุมกันฟังพระวจนะของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 45, 'แต่เมื่อพวกยิวเห็นคนมากมายก็มีใจอิจฉาอย่างยิ่ง ได้พูดคัดค้านคําของเปาโลถึงโต้แย้งกับพูดคําสบประมาท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 46, 'แล้วเปาโลกับบารนาบัสมีใจกล้า ได้กล่าวว่า “จําเป็นที่จะต้องกล่าวพระวจนะของพระเจ้าให้ท่านทั้งหลายฟังก่อน แต่เมื่อท่านทั้งหลายปัดเสีย และตัดสินว่าตนไม่สมควรที่จะได้ชีวิตนิรันดร์ ดูเถิด พวกเราจะบ่ายหน้าไปหาคนต่างชาติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 47, 'ด้วยองค์พระผู้เป็นเจ้าได้ตรัสสั่งเราอย่างนี้ว่า ‘เราได้ตั้งเจ้าไว้ให้เป็นความสว่างของคนต่างชาติ เพื่อเจ้าจะเป็นเหตุให้คนทั้งหลายรอด ถึงที่สุดปลายแผ่นดินโลก’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 48, 'ฝ่ายคนต่างชาติเมื่อได้ยินอย่างนั้นก็มีความยินดี และได้สรรเสริญพระวจนะขององค์พระผู้เป็นเจ้า และคนทั้งหลายที่ทรงหมายไว้แล้วเพื่อให้ได้ชีวิตนิรันดร์ก็ได้เชื่อถือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 49, 'พระวจนะขององค์พระผู้เป็นเจ้าจึงแพร่ไปตลอดทั่วเขตแดนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 50, 'แต่พวกยิวได้ยุยงพวกสตรีมีศักดิ์ที่ถือพระเจ้า กับทั้งผู้ชายที่เป็นใหญ่ในเมืองนั้นให้เคี่ยวเข็ญ และไล่เปาโลกับบารนาบัสออกจากเมืองของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 51, 'ฝ่ายเปาโลกับบารนาบัสจึงสะบัดผงคลีดินจากเท้าของท่านออกเพื่อต่อว่าพวกเขา แล้วก็ไปยังเขตเมืองอิโคนียูม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 52, 'แต่พวกสาวกก็เต็มไปด้วยความชื่นชมยินดี และด้วยพระวิญญาณบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 1, 'ต่อมาที่เมืองอิโคนียูม เปาโลกับบารนาบัสได้เข้าไปในธรรมศาลาของพวกยิว กล่าวสั่งสอนเป็นที่จับใจจนพวกยิวและชนชาติกรีกเป็นอันมากได้เชื่อถือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 2, 'แต่พวกยิวที่ไม่เชื่อก็ยุยงคนต่างชาติให้มีใจคิดร้ายต่อพวกพี่น้อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 3, 'เหตุฉะนั้นฝ่ายท่านทั้งสองคอยอยู่ที่นั่นนาน มีใจกล้ากล่าวในพระนามขององค์พระผู้เป็นเจ้า และพระองค์ได้ทรงรับรองพระดํารัสแห่งพระคุณของพระองค์ โดยทรงโปรดให้ท่านทั้งสองทําหมายสําคัญและการมหัศจรรย์ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 4, 'แต่พลเมืองส่วนใหญ่แตกเป็นสองพวก พวกหนึ่งอยู่ฝ่ายพวกยิว และอีกพวกหนึ่งอยู่ฝ่ายอัครสาวก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 5, 'เมื่อทั้งคนต่างชาติและพวกยิวพร้อมกับพวกผู้ปกครอง ได้ร่วมคิดกันจะทําการอัปยศ และเอาก้อนหินขว้างเปาโลกับบารนาบัส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 6, 'ท่านทั้งสองทราบแล้วจึงหนีไปยังเมืองที่อยู่ในแคว้นลิคาโอเนีย คือเมืองลิสตรา เมืองเดอร์บี กับชนบทที่อยู่ล้อมรอบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 7, 'และได้ประกาศข่าวประเสริฐที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 8, 'ที่เมืองลิสตรามีชายคนหนึ่งนั่งอยู่ใช้เท้าไม่ได้ เขาพิการตั้งแต่ครรภ์มารดา ยังไม่เคยเดินเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 9, 'คนนั้นได้ฟังเปาโลพูดอยู่ เปาโลจึงเขม้นดูเขา เห็นว่ามีความเชื่อพอจะหายโรคได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 10, 'จึงร้องสั่งด้วยเสียงอันดังว่า “จงลุกขึ้นยืนตรง” คนนั้นก็กระโดดขึ้นเดินไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 11, 'เมื่อหมู่ชนเห็นการซึ่งเปาโลได้กระทํานั้น จึงพากันร้องเป็นภาษาลิคาโอเนียว่า “พวกพระแปลงเป็นมนุษย์ลงมาหาเราแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 12, 'เขาจึงเรียกบารนาบัสว่า พระซุส และเรียกเปาโลว่า พระเฮอร์เมส เพราะเปาโลเป็นผู้นําในการพูด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 13, 'ปุโรหิตประจํารูปพระซุส ซึ่งตั้งอยู่หน้าเมืองได้จูงวัวและถือพวงมาลัยมายังประตูเมือง หมายจะถวายเครื่องบูชาด้วยกันกับประชาชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 14, 'แต่เมื่ออัครสาวกบารนาบัสกับเปาโลได้ยินดังนั้น จึงฉีกเสื้อผ้าของตนเสีย วิ่งเข้าไปท่ามกลางคนทั้งหลายร้องเสียงดัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 15, 'ว่า “ท่านทั้งหลาย เหตุไฉนท่านจึงทําการอย่างนี้ เราเป็นคนธรรมดาเช่นเดียวกันกับท่านทั้งหลาย และมาประกาศให้ท่านกลับจากสิ่งไร้ประโยชน์เหล่านี้ ให้มาหาพระเจ้าผู้ทรงพระชนม์ ผู้ได้ทรงสร้างฟ้าสวรรค์และแผ่นดินโลก ทะเลและสิ่งสารพัดซึ่งมีอยู่ในที่เหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 16, 'ในกาลก่อนพระองค์ได้ทรงยอมให้บรรดาประชาชาติดําเนินชีวิตตามชอบใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 17, 'แต่พระองค์มิได้ทรงให้ขาดพยาน คือพระองค์ได้ทรงกระทําคุณให้ฝนตกจากฟ้าและให้มีฤดูเกิดผล เราทั้งหลายจึงอิ่มใจด้วยอาหารและความยินดี”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 18, 'ถึงแม้ว่าได้กล่าวสิ่งนี้แล้วก็ดี อัครสาวกก็ยังห้ามประชาชนมิให้เขากระทําสักการบูชาถวายแก่ท่านทั้งสองนั้นได้โดยยาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 19, 'แต่มีพวกยิวบางคนมาจากเมืองอันทิโอกและเมืองอิโคนียูม เมื่อได้ชักชวนประชาชนแล้ว เขาก็ได้เอาหินขว้างเปาโลและลากท่านออกไปจากเมืองคิดว่าท่านตายแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 20, 'แต่พวกสาวกได้ล้อมท่านไว้แล้วท่านก็ลุกขึ้นเข้าไปในเมือง วันรุ่งขึ้นท่านจึงเลยไปยังเมืองเดอร์บีกับบารนาบัส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 21, 'และเมื่อท่านทั้งสองได้ประกาศข่าวประเสริฐในเมืองนั้น และได้สั่งสอนคนเป็นอันมาก จึงกลับไปยังเมืองลิสตรา เมืองอิโคนียูม และเมืองอันทิโอกอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 22, 'กระทําให้ใจของสาวกทั้งหลายถือมั่นขึ้น เตือนเขาให้ดํารงอยู่ในความเชื่อ และสอนว่า เราทั้งหลายจําต้องทนความยากลําบากมากจนกว่าจะได้เข้าในอาณาจักรของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 23, 'เมื่อท่านทั้งสองได้เลือกตั้งผู้ปกครองสาวกไว้ทุกคริสตจักร และได้อธิษฐานและถืออดอาหารฝากสาวกไว้กับองค์พระผู้เป็นเจ้าที่เขาเชื่อถือนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 24, 'และหลังจากท่านทั้งสองได้ข้ามแคว้นปิสิเดียก็มายังแคว้นปัมฟีเลีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 25, 'เมื่อได้กล่าวพระวจนะในเมืองเปอร์กาแล้ว จึงลงไปยังเมืองอัททาลิยา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 26, 'และแล่นจากที่นั่นไปยังเมืองอันทิโอก คือเมืองที่ท่านทั้งสองได้รับการฝากไว้ในพระคุณของพระเจ้า ให้กระทําการซึ่งท่านทั้งสองได้กระทําสําเร็จมาแล้วนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 27, 'เมื่อมาถึง ท่านทั้งสองได้เรียกประชุมคริสตจักร และได้เล่าให้เขาฟังถึงพระราชกิจทั้งปวงซึ่งพระเจ้าได้ทรงกระทําร่วมกับเขา กับซึ่งพระองค์ได้ทรงเปิดประตูให้คนต่างชาติเชื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 28, 'แล้วท่านทั้งสองจึงอยู่กับพวกสาวกที่นั่นช้านาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 1, 'มีบางคนลงมาจากแคว้นยูเดียได้สั่งสอนพวกพี่น้องว่า “ถ้าไม่เข้าสุหนัตตามจารีตของโมเสส ท่านจะรอดไม่ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 2, 'เหตุฉะนั้นเมื่อเกิดการโต้แย้งและไล่เลียงกันระหว่างเปาโลและบารนาบัสกับคนเหล่านั้นมากมายแล้ว เขาทั้งหลายได้ตั้งเปาโลและบารนาบัสกับคนอื่นๆในพวกนั้นให้ขึ้นไป หารือกับอัครสาวกและผู้ปกครองในกรุงเยรูซาเล็มในเรื่องที่เถียงกันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 3, 'คริสตจักรได้จัดส่งท่านเหล่านั้นไป และขณะเมื่อท่านกําลังข้ามแคว้นฟีนิเซียกับแคว้นสะมาเรีย ท่านได้กล่าวถึงเรื่องที่คนต่างชาติได้กลับใจใหม่ ทําให้พวกพี่น้องมีความยินดีอย่างยิ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 4, 'ครั้นมาถึงกรุงเยรูซาเล็ม คริสตจักรและอัครสาวกและผู้ปกครองทั้งหลายได้ต้อนรับท่าน แล้วท่านเหล่านั้นจึงเล่าให้เขาฟังถึงเหตุการณ์ทั้งปวงที่พระเจ้าได้ทรงกระทําร่วมกับเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 5, 'แต่มีบางคนในพวกฟาริสีที่มีความเชื่อได้ยืนขึ้นกล่าวว่า คนต่างชาตินั้นควรต้องให้เขาเข้าสุหนัต และสั่งให้เขาถือตามพระราชบัญญัติของโมเสส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 6, 'ฝ่ายอัครสาวกกับผู้ปกครองทั้งหลายจึงได้ประชุมปรึกษากันในเรื่องนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 7, 'เมื่อโต้แย้งกันมากแล้ว เปโตรจึงยืนขึ้นกล่าวแก่เขาว่า “ท่านพี่น้องทั้งหลาย ท่านทั้งหลายทราบอยู่ว่า คราวก่อนนั้นพระเจ้าได้ทรงเลือกข้าพเจ้าเองจากพวกท่านทั้งหลาย ให้เป็นผู้ประกาศพระวจนะแห่งข่าวประเสริฐให้คนต่างชาติฟังและเชื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 8, 'พระเจ้าผู้ทรงทราบจิตใจมนุษย์ได้ทรงรับรองคนต่างชาติ และทรงประทานพระวิญญาณบริสุทธิ์แก่เขาเหมือนได้ทรงประทานแก่พวกเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 9, 'พระองค์ไม่ทรงถือว่าเรากับเขาต่างกัน แต่ทรงชําระใจเขาให้บริสุทธิ์โดยความเชื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 10, 'ถ้าอย่างนั้นทําไมบัดนี้ท่านทั้งหลายจึงทดลองพระเจ้า โดยวางแอกบนคอของพวกสาวกซึ่งบรรพบุรุษของเราหรือตัวเราเองก็ดีแบกไม่ไหว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 11, 'แต่เราเชื่อว่า เราเองก็รอดโดยพระคุณของพระเยซูคริสต์เจ้าเหมือนอย่างเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 12, 'ฝ่ายคนทั้งหลายก็นิ่งฟังบารนาบัสกับเปาโลเล่าเรื่องการอัศจรรย์และการมหัศจรรย์ต่างๆ ซึ่งพระเจ้าได้ทรงกระทําโดยเขาในหมู่พวกต่างชาติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 13, 'ครั้นจบแล้วและนิ่งอยู่ ยากอบจึงกล่าวว่า “ท่านพี่น้องทั้งหลาย จงฟังข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 14, 'ซีโมนได้บอกแล้วว่า พระเจ้าได้ทรงเยี่ยมเยียนคนต่างชาติครั้งแรก เพื่อจะทรงเลือกชนกลุ่มหนึ่งออกจากเขาทั้งหลายเพื่อพระนามของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 15, 'คําของศาสดาพยากรณ์ก็สอดคล้องกับเรื่องนี้ ดังที่ได้เขียนไว้แล้วว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 16, '‘ภายหลังเราจะกลับมา และจะสร้างพลับพลาของดาวิดซึ่งพังลงแล้วขึ้นใหม่ ที่ร้างหักพังนั้นเราจะก่อขึ้นอีก และจะตั้งขึ้นใหม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 17, 'เพื่อคนอื่นๆจะได้แสวงหาองค์พระผู้เป็นเจ้า คือบรรดาคนต่างชาติซึ่งเขาเรียกด้วยนามของเรา องค์พระผู้เป็นเจ้าผู้ทรงกระทําสิ่งทั้งปวงเหล่านี้ได้ตรัสไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 18, 'พระเจ้าทรงทราบถึงกิจการทั้งปวงของพระองค์ตั้งแต่แรกสร้างโลกมาแล้ว’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 19, 'เหตุฉะนั้น ข้าพเจ้าตัดสินใจว่า อย่าให้เราวางเครื่องขัดขวางกีดกันคนต่างชาติซึ่งกลับมาหาพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 20, 'แต่เราจงเขียนหนังสือฝากไปถึงเขาว่า ให้งดเว้นเสียจากสิ่งที่มลทินเนื่องด้วยรูปเคารพ จากการล่วงประเวณี จากการรับประทานเนื้อสัตว์ที่รัดคอตาย และจากการรับประทานเลือด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 21, 'เพราะว่าตั้งแต่โบราณมาในทุกเมืองมีคนประกาศเรื่องของโมเสส เพราะคนได้อ่านพระราชบัญญัติของท่านในธรรมศาลาทุกวันสะบาโต”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 22, 'ขณะนั้น อัครสาวกและผู้ปกครองทั้งหลายกับทุกคนในคริสตจักร เห็นชอบที่จะเลือกบางคนในพวกเขาให้ไปยังเมืองอันทิโอก ด้วยกันกับเปาโลและบารนาบัส คือ ยูดาส ผู้ที่มีชื่ออีกว่า บารซับบาส และสิลาส ทั้งสองคนนี้เป็นคนสําคัญในพวกพี่น้อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 23, 'เขาได้เขียนจดหมายมอบให้ท่านถือไปว่า “อัครสาวกและผู้ปกครองและพวกพี่น้องของท่าน คํานับมายังท่าน ผู้เป็นพวกพี่น้องซึ่งเป็นคนต่างชาติ ซึ่งอยู่ในเมืองอันทิโอก แคว้นซีเรีย และแคว้นซีลีเซียทราบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 24, 'ด้วยพวกข้าพเจ้าได้ยินว่า มีบางคนในพวกข้าพเจ้าได้พูดให้ท่านทั้งหลายเกิดความไม่สบายใจ และทําให้ใจของท่านปั่นป่วนไป ด้วยสอนว่า ‘ท่านต้องเข้าสุหนัตและรักษาพระราชบัญญัติ’ แม้ว่าเขามิได้รับคําสั่งจากพวกข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 25, 'พวกข้าพเจ้าจึงพร้อมใจกันเห็นชอบที่จะเลือกคน และใช้เขามายังท่านทั้งหลายพร้อมกับบารนาบัสและเปาโล ผู้เป็นที่รักของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 26, 'และเป็นผู้อุทิศชีวิตของตน เพื่อพระนามของพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 27, 'เหตุฉะนั้น ข้าพเจ้าทั้งหลายจึงใช้ยูดาสกับสิลาสมาเป็นผู้ซึ่งจะเล่าข้อความนี้แก่ท่านทั้งหลายด้วยปากของเขาเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 28, 'เพราะว่า พระวิญญาณบริสุทธิ์และข้าพเจ้าทั้งหลายก็เห็นชอบที่จะไม่วางภาระบนท่านทั้งหลาย เว้นไว้แต่สิ่งเหล่านั้นที่จําเป็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 29, 'คือว่าให้ท่านทั้งหลายงดการรับประทานสิ่งของซึ่งเขาได้บูชาแก่รูปเคารพ และการรับประทานเลือด และการรับประทานเนื้อสัตว์ซึ่งถูกรัดคอตาย และการล่วงประเวณี ถ้าท่านทั้งหลายงดการเหล่านี้ก็จะเป็นการดี ขอให้อยู่เป็นสุขเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 30, 'เมื่อลาจากกันแล้ว ท่านเหล่านั้นก็ไปยังเมืองอันทิโอก และเมื่อได้เรียกคนทั้งปวงประชุมกันแล้ว จึงมอบจดหมายฉบับนั้นให้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 31, 'ครั้นอ่านแล้วต่างก็มีความชื่นชมยินดีในคําหนุนใจนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 32, 'ฝ่ายยูดาสกับสิลาสเป็นผู้พยากรณ์ด้วย จึงได้กล่าวหนุนใจพวกพี่น้องหลายประการให้มีกําลังขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 33, 'ครั้นพักอยู่ที่นั่นหน่อยหนึ่งแล้ว ก็ลาจากพวกพี่น้องไปถึงอัครสาวกโดยสันติภาพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 34, 'อย่างไรก็ตามสิลาสเห็นชอบที่จะอยู่ต่อไปที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 35, 'แต่เปาโลกับบารนาบัสยังอยู่ต่อไปในเมืองอันทิโอก สั่งสอนประกาศพระวจนะขององค์พระผู้เป็นเจ้าด้วยกันกับคนอื่นอีกหลายคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 36, 'ครั้นล่วงไปได้หลายวัน เปาโลจึงพูดกับบารนาบัสว่า “ให้เรากลับไปเยี่ยมพวกพี่น้องในทุกเมือง ที่เราได้ประกาศพระวจนะขององค์พระผู้เป็นเจ้าไว้ ดูว่าเขาเป็นอย่างไรกันบ้าง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 37, 'ฝ่ายบารนาบัสได้ตั้งใจว่าจะพายอห์นผู้มีอีกชื่อหนึ่งว่ามาระโกไปด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 38, 'แต่เปาโลไม่เห็นควรที่จะพายอห์นไปด้วย เพราะครั้งก่อนยอห์นได้ละท่านทั้งสองเสียที่แคว้นปัมฟีเลีย และมิได้ไปทําการด้วยกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 39, 'แล้วได้เกิดการขัดแย้งกันจนต้องแยกกัน บารนาบัสจึงพามาระโกลงเรือไปยังเกาะไซปรัส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 40, 'แต่เปาโลได้เลือกสิลาส และเมื่อพวกพี่น้องได้ฝากท่านทั้งสองไว้ในพระคุณของพระเจ้าแล้วท่านก็ไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 41, 'ท่านจึงไปตลอดแคว้นซีเรียกับแคว้นซีลีเซียหนุนใจคริสตจักรให้แข็งแรงขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 1, 'แล้วเปาโลไปยังเมืองเดอร์บีกับเมืองลิสตรา และดูเถิด ที่นั่นมีสาวกคนหนึ่งชื่อทิโมธี เป็นบุตรชายของหญิงชาติยิวคนหนึ่งที่เชื่อแล้ว แต่บิดาเป็นชาติกรีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 2, 'ทิโมธีมีชื่อเสียงดีในหมู่พวกพี่น้องที่อยู่ในเมืองลิสตรา และเมืองอิโคนียูม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 3, 'เปาโลใคร่จะพาทิโมธีไปด้วยกัน จึงให้เข้าสุหนัตเพราะเห็นแก่พวกยิวที่อยู่ในเมืองนั้นๆ เพราะคนเหล่านั้นทุกคนรู้ว่าบิดาของเขาเป็นชาติกรีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 4, 'เมื่อท่านเหล่านั้นได้เที่ยวไปตามเมืองต่างๆก็ได้ส่งหนังสือข้อตกลงของอัครสาวก และผู้ปกครองในกรุงเยรูซาเล็มมอบให้คนทั้งหลายทุกเมืองเพื่อให้รักษาไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 5, 'คริสตจักรทั้งปวงจึงเข้มแข็งในความเชื่อ และจํานวนคนได้ทวีขึ้นทุกๆวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 6, 'ครั้นท่านเหล่านั้นไปทั่วแว่นแคว้นฟรีเจียกับกาลาเทียแล้ว พระวิญญาณบริสุทธิ์ห้ามมิให้กล่าวพระวจนะในแคว้นเอเชีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 7, 'เมื่อไปยังแคว้นมิเซียแล้ว ก็พยายามจะไปยังแว่นแคว้นบิธีเนีย แต่พระวิญญาณไม่ทรงโปรดให้ไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 8, 'แล้วท่านเหล่านั้นได้เดินทางผ่านแคว้นมิเซียลงมายังเมืองโตรอัส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 9, 'ในเวลากลางคืนเปาโลได้นิมิตเห็นผู้ชายชาวมาซิโดเนียคนหนึ่งยืนอ้อนวอนว่า “ขอโปรดมาช่วยพวกข้าพเจ้าในแคว้นมาซิโดเนียเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 10, 'ครั้นท่านเห็นนิมิตนั้นแล้ว เราจึงหาโอกาสทันทีที่จะไปยังแคว้นมาซิโดเนีย ด้วยเห็นแน่ว่า องค์พระผู้เป็นเจ้าได้ทรงเรียกเราให้ไปประกาศข่าวประเสริฐแก่ชาวแคว้นนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 11, 'เหตุฉะนั้น เมื่อออกจากเมืองโตรอัสแล้ว ก็ตรงไปยังเกาะสาโมธรัสเซียและรุ่งขึ้นก็ถึงเมืองเนอาบุรี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 12, 'เมื่อออกจากที่นั่นแล้ว ก็ได้ไปยังเมืองฟีลิปปีซึ่งเป็นเมืองเอกในเขตแคว้นมาซิโดเนีย และเป็นเมืองขึ้น เราจึงพักอยู่ในเมืองนั้นหลายวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 13, 'ในวันสะบาโตเราได้ออกจากเมืองไปยังฝั่งแม่น้ํา เข้าใจว่ามีที่สําหรับอธิษฐาน จึงได้นั่งสนทนากับพวกผู้หญิงที่ประชุมกันที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 14, 'มีหญิงคนหนึ่งชื่อลิเดียมาจากเมืองธิยาทิราเป็นคนขายผ้าสีม่วง เป็นผู้นมัสการพระเจ้า หญิงนั้นได้ฟังเรา และองค์พระผู้เป็นเจ้าได้ทรงเปิดใจของเขาให้สนใจในถ้อยคําซึ่งเปาโลได้กล่าว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 15, 'เมื่อหญิงคนนั้นกับทั้งครอบครัวของเขาได้รับบัพติศมาแล้วจึงอ้อนวอนเราว่า “ถ้าท่านเห็นว่าข้าพเจ้าเป็นคนสัตย์ซื่อต่อองค์พระผู้เป็นเจ้า เชิญเข้ามาพักอาศัยในบ้านของข้าพเจ้าเถิด” และเขาได้วิงวอนจนเราขัดไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 16, 'ต่อมาเมื่อเรากําลังออกไปยังที่สําหรับอธิษฐาน มีหญิงสาวคนหนึ่งที่มีผีหมอดูเข้าสิงได้มาพบกับเรา เขาทําการทายให้พวกเจ้านายของเขาได้เงินเป็นอันมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 17, 'หญิงนั้นตามเปาโลกับพวกเราไปร้องว่า “คนเหล่านี้เป็นผู้รับใช้ของพระเจ้าผู้สูงสุด มากล่าวประกาศทางรอดแก่เราทั้งหลาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 18, 'เขาทําอย่างนั้นหลายวัน ฝ่ายเปาโลเป็นทุกข์มาก หันหน้าสั่งผีนั้นว่า “เราสั่งเจ้าว่า ในพระนามของพระเยซูคริสต์ เจ้าจงออกมาจากเขา” ผีนั้นก็ออกมาในเวลานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 19, 'ส่วนพวกนายของเขาเมื่อเห็นว่าหมดหวังที่จะได้เงินแล้ว เขาจึงจับเปาโลและสิลาสลากมาถึงพวกเจ้าหน้าที่ยังที่ว่าการเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 20, 'เมื่อนํามาถึงเจ้าเมืองแล้วจึงกล่าวว่า “คนเหล่านี้เป็นพวกยิว ก่อการวุ่นวายมากในเมืองของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 21, 'และสั่งสอนธรรมเนียม ซึ่งเราชาวโรมตามกฎหมายไม่ควรจะรับหรือถือเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 22, 'ประชาชนก็ได้ฮือกันขึ้นต่อสู้เปาโลและสิลาส เจ้าเมืองได้กระชากเสื้อของท่านทั้งสองออก แล้วสั่งให้โบยด้วยไม้เรียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 23, 'ครั้นโบยหลายทีแล้วจึงให้จําไว้ในคุก และกําชับนายคุกให้รักษาไว้ให้มั่นคง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 24, 'นายคุกเมื่อรับคําสั่งอย่างนั้นแล้วจึงพาเปาโลกับสิลาสไปจําไว้ในห้องชั้นใน เอาเท้าใส่ขื่อไว้แน่นหนา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 25, 'ประมาณเที่ยงคืนเปาโลกับสิลาสก็อธิษฐานและร้องเพลงสรรเสริญพระเจ้า นักโทษทั้งหลายก็ฟังอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 26, 'ในทันใดนั้นเกิดแผ่นดินไหวใหญ่จนรากคุกสะเทือนสะท้าน และประตูคุกเปิดหมดทุกบาน เครื่องจองจําก็หลุดจากเขาสิ้นทุกคนทันที');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 27, 'ฝ่ายนายคุกตื่นขึ้นเห็นประตูคุกเปิดอยู่ คาดว่านักโทษทั้งหลายหนีไปหมดแล้ว จึงชักดาบออกมาหมายว่าจะฆ่าตัวเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 28, 'แต่เปาโลได้ร้องเสียงดังว่า “อย่าทําร้ายตัวเองเลย เราทั้งหลายอยู่พร้อมด้วยกันทุกคน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 29, 'นายคุกจึงสั่งให้จุดไฟมา แล้ววิ่งเข้าไปตัวสั่นกราบลงที่เท้าของเปาโลกับสิลาส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 30, 'และพาท่านทั้งสองออกมาแล้วว่า “ท่านเจ้าข้า ข้าพเจ้าจะต้องทําอย่างไรจึงจะรอดได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 31, 'เปาโลกับสิลาสจึงกล่าวว่า “จงเชื่อวางใจในพระเยซูคริสต์เจ้า และท่านจะรอดได้ทั้งครอบครัวของท่านด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 32, 'ท่านทั้งสองจึงกล่าวสั่งสอนพระวจนะขององค์พระผู้เป็นเจ้าให้นายคุก และคนทั้งปวงที่อยู่ในบ้านของเขาฟัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 33, 'ในกลางคืนชั่วโมงเดียวกันนั้นเอง นายคุกจึงพาเปาโลกับสิลาสไปล้างแผลที่ถูกเฆี่ยน และในขณะนั้นนายคุกก็ได้รับบัพติศมาพร้อมทั้งครัวเรือนของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 34, 'แล้วได้พาท่านทั้งสองเข้าไปในบ้านของเขา จัดโต๊ะเลี้ยงท่านแสดงความยินดีอย่างยิ่ง เพราะได้เชื่อถือพระเจ้าพร้อมกับทั้งครอบครัวแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 35, 'ครั้นเวลาเช้าเจ้าเมืองจึงใช้พวกนักการไป สั่งว่า “จงปล่อยคนทั้งสองนั้นเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 36, 'นายคุกจึงบอกเปาโลว่า “เจ้าเมืองได้ใช้คนมาบอกให้ปล่อยท่านทั้งสอง ฉะนั้นบัดนี้เชิญท่านออกไปตามสบายเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 37, 'แต่เปาโลกล่าวแก่เขาทั้งหลายว่า “เขาได้เฆี่ยนเราผู้เป็นคนสัญชาติโรมต่อหน้าคนทั้งหลายก่อนได้ตัดสินความ และได้จําเราไว้ในคุก บัดนี้เขาจะเสือกไสให้เราออกไปเป็นการลับหรือ ทําอย่างนั้นไม่ได้ ให้เขาเองมาพาเราออกไปเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 38, 'พวกนักการจึงนําความไปแจ้งแก่เจ้าเมือง เมื่อเจ้าเมืองได้ยินว่าท่านทั้งสองเป็นคนสัญชาติโรมก็ตกใจกลัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 39, 'จึงมาวิงวอนท่านทั้งสอง ครั้นพาออกไปแล้วจึงขอให้ออกไปเสียจากเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 40, 'ท่านทั้งสองจึงออกจากคุก แล้วได้เข้าไปในบ้านของนางลิเดีย เมื่อพบพวกพี่น้องก็พูดจาหนุนใจเขาแล้วก็ลาไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 1, 'ครั้นเปาโลกับสิลาสข้ามเมืองอัมฟีบุรีและเมืองอปอลโลเนียแล้ว จึงมายังเมืองเธสะโลนิกา ที่นั่นมีธรรมศาลาของพวกยิว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 2, 'เปาโลจึงเข้าไปร่วมกับพวกเขาตามอย่างเคย และท่านได้อ้างข้อความในพระคัมภีร์โต้ตอบกับเขาทั้งสามวันสะบาโต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 3, 'และไขข้อความชี้แจงให้เห็นว่าจําเป็นที่พระคริสต์ต้องทนทุกข์ทรมาน แล้วทรงคืนพระชนม์และกล่าวต่อไปว่า “พระเยซูองค์นี้ที่เราประกาศแก่ท่านทั้งหลายคือพระคริสต์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 4, 'บางคนในพวกเขาก็เชื่อ และสมัครเข้าเป็นพรรคพวกกับเปาโลและสิลาส รวมทั้งชาวกรีกเป็นจํานวนมากที่เกรงกลัวพระเจ้าและสุภาพสตรีที่เป็นคนสําคัญๆก็ไม่น้อย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 5, 'แต่พวกยิวที่ไม่เชื่อก็อิจฉา ไปคบคิดกับคนพาลตามตลาดรวบรวมกันมาเป็นอันมาก ก่อการจลาจลในบ้านเมือง บุกเข้าบ้านของยาโสน ตั้งใจจะพาท่านทั้งสองออกมาให้คนทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 6, 'ครั้นไม่พบจึงฉุดลากยาโสนกับพวกพี่น้องบางคนไปหาเจ้าหน้าที่ผู้ครองเมืองร้องว่า “คนเหล่านั้นที่เป็นพวกคว่ําแผ่นดินได้มาที่นี่ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 7, 'ยาโสนรับรองเขาไว้ และบรรดาคนเหล่านี้ได้กระทําผิดคําสั่งของซีซาร์ โดยเขาสอนว่ามีกษัตริย์อีกองค์หนึ่งคือพระเยซู”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 8, 'เมื่อประชาชนและเจ้าหน้าที่ผู้ครองเมืองได้ยินดังนั้นก็ร้อนใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 9, 'จึงเรียกประกันตัวยาโสนกับคนอื่นๆแล้วก็ปล่อยไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 10, 'พอค่ําลงพวกพี่น้องจึงส่งเปาโลกับสิลาสไปยังเมืองเบโรอา ครั้นถึงแล้วท่านจึงเข้าไปในธรรมศาลาของพวกยิว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 11, 'ชาวเมืองนั้นสุภาพกว่าชาวเมืองเธสะโลนิกา ด้วยเขาได้รับพระวจนะด้วยความเต็มใจ และค้นดูพระคัมภีร์ทุกวัน หวังจะรู้ว่า ข้อความเหล่านั้นจะจริงดังกล่าวหรือไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 12, 'เหตุฉะนั้น มีหลายคนในพวกเขาได้เชื่อถือ กับสตรีผู้มีศักดิ์ชาติกรีก ทั้งผู้ชายไม่น้อย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 13, 'แต่เมื่อพวกยิวที่อยู่ในเมืองเธสะโลนิกาทราบว่า เปาโลได้กล่าวสั่งสอนพระวจนะของพระเจ้าในเมืองเบโรอาเหมือนกัน เขาก็มายุยงประชาชนที่นั่นด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 14, 'ขณะนั้นพวกพี่น้องจึงส่งเปาโลออกไปตามทางที่จะไปทะเล แต่สิลาสกับทิโมธียังอยู่ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 15, 'คนที่ไปส่งเปาโลนั้นได้ไปส่งท่านถึงกรุงเอเธนส์ และเมื่อได้รับคําสั่งของท่านให้บอกสิลาสกับทิโมธีให้รีบไปหาท่านแล้วเขาก็จากไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 16, 'เมื่อเปาโลกําลังคอยสิลาสกับทิโมธีอยู่ในกรุงเอเธนส์นั้น ท่านมีความเดือดร้อนวุ่นวายใจเพราะได้เห็นรูปเคารพเต็มไปทั้งเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 17, 'เหตุฉะนั้น ท่านจึงโต้ตอบในธรรมศาลากับพวกยิว และกับคนที่เกรงกลัวพระเจ้า และกับคนทั้งหลายซึ่งมาพบท่านที่ตลาดทุกวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 18, 'นักปรัชญาบางคนในพวกเอปีกูเรียวและในพวกสโตอิกได้มาพบท่าน บางคนกล่าวว่า “คนพูดเพ้อเจ้ออย่างนี้ใคร่จะมาพูดอะไรให้เราฟังอีกเล่า” คนอื่นกล่าวว่า “ดูเหมือนเขาเป็นคนนําพระต่างประเทศเข้ามาเผยแพร่” เพราะเปาโลได้ประกาศเรื่องพระเยซูและเรื่องการเป็นขึ้นมาจากความตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 19, 'เขาจึงจับเปาโลพาไปยังสภาอาเรโอปากัสแล้วถามว่า “เราขอรู้ได้หรือไม่ว่าคําสอนอย่างใหม่ที่ท่านกล่าวนั้นเป็นอย่างไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 20, 'เพราะว่าท่านนําเรื่องแปลกประหลาดมาถึงหูของเรา เหตุฉะนั้นเราอยากทราบว่าเรื่องเหล่านี้มีความหมายว่าอย่างไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 21, '(เพราะชาวเอเธนส์กับชาวต่างประเทศซึ่งอาศัยอยู่ที่นั่น ไม่ได้ใช้เวลาว่างในการอื่นนอกจากจะกล่าวหรือฟังสิ่งใหม่ๆ)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 22, 'ฝ่ายเปาโลจึงยืนขึ้นกลางเนินเขาอาเรโอแล้วกล่าวว่า “ท่านชาวกรุงเอเธนส์ ข้าพเจ้าเห็นว่าท่านทั้งหลายเชื่อถือโชคลางเกินไปในทุกเรื่อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 23, 'เพราะว่าเมื่อข้าพเจ้าเดินทางมาสังเกตดูสิ่งที่ท่านนมัสการนั้น ข้าพเจ้าได้พบแท่นแท่นหนึ่งมีคําจารึกไว้ว่า ‘แด่พระเจ้าที่ไม่รู้จัก’ เหตุฉะนั้นข้าพเจ้าจึงมาประกาศ และแสดงให้ท่านทั้งหลายทราบถึงพระเจ้าที่ท่านไม่รู้จักแต่ยังนมัสการอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 24, 'พระเจ้าผู้ทรงสร้างโลกกับสิ่งทั้งปวงที่มีอยู่ในนั้น พระองค์ทรงเป็นเจ้าแห่งฟ้าสวรรค์และแผ่นดินโลก มิได้ทรงสถิตในปูชนียสถานซึ่งมือมนุษย์ได้กระทําไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 25, 'การที่มือมนุษย์ปฏิบัตินมัสการพระองค์นั้นจะหมายว่า พระเจ้าต้องประสงค์สิ่งหนึ่งสิ่งใดจากเขาก็หามิได้ เพราะพระองค์ทรงเป็นผู้ประทานชีวิตและลมหายใจและสิ่งสารพัดแก่คนทั้งปวงต่างหาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 26, 'พระองค์ได้ทรงสร้างมนุษย์ทุกชาติสืบสายโลหิตอันเดียวกันให้อยู่ทั่วพื้นพิภพโลก และได้ทรงกําหนดเวลาและเขตแดนให้เขาอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 27, 'เพื่อเขาจะได้แสวงหาองค์พระผู้เป็นเจ้า และหากเขาจะคลําหาก็จะได้พบพระองค์ ด้วยพระองค์มิทรงอยู่ห่างไกลจากเราทุกคนเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 28, 'ด้วยว่า ‘เรามีชีวิตและไหวตัวและเป็นอยู่ในพระองค์’ ตามที่กวีบางคนในพวกท่านได้กล่าวว่า ‘เราทั้งหลายเป็นเชื้อสายของพระองค์’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 29, 'เหตุฉะนั้นเมื่อเราเป็นเชื้อสายของพระเจ้าแล้ว เราก็ไม่ควรถือว่าพระเจ้าทรงเป็นเหมือนทอง เงิน หรือหิน ซึ่งได้แกะสลักด้วยศิลปะและความคิดของมนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 30, 'ในเวลาเมื่อมนุษย์ยังโฉดเขลาอยู่พระเจ้าทรงมองข้ามไปเสีย แต่เดี๋ยวนี้พระองค์ได้ตรัสสั่งแก่มนุษย์ทั้งปวงทั่วทุกแห่งให้กลับใจใหม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 31, 'เพราะพระองค์ได้ทรงกําหนดวันหนึ่งไว้ ในวันนั้นพระองค์จะทรงพิพากษาโลกตามความชอบธรรม โดยให้ท่านองค์นั้นซึ่งพระองค์ได้ทรงเลือกไว้เป็นผู้พิพากษา และพระองค์ได้ให้พยานหลักฐานแก่คนทั้งปวงแล้วว่า ได้ทรงโปรดให้ท่านองค์นั้นคืนพระชนม์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 32, 'ครั้นคนทั้งหลายได้ยินถึงเรื่องการซึ่งเป็นขึ้นมาจากความตายแล้ว บางคนก็เยาะเย้ย แต่คนอื่นๆว่า “เราจะฟังท่านกล่าวเรื่องนี้อีกต่อไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 33, 'แล้วเปาโลจึงออกไปจากเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 34, 'แต่มีชายบางคนติดตามเปาโลไปและได้เชื่อถือ ในคนเหล่านั้นมีดิโอนิสิอัสผู้เป็นสมาชิกสภาอาเรโอปากัส กับหญิงคนหนึ่งชื่อดามาริส และคนอื่นๆด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 1, 'ภายหลังเหตุการณ์เหล่านี้เปาโลจึงออกจากกรุงเอเธนส์ไปยังเมืองโครินธ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 2, 'ท่านได้พบยิวคนหนึ่งชื่ออาควิลลา ซึ่งเกิดในแคว้นปอนทัส แต่พึ่งมาจากประเทศอิตาลีกับภรรยาชื่อปริสสิลลา (เพราะคลาวดิอัสมีรับสั่งให้พวกยิวทั้งปวงออกไปจากกรุงโรม) เปาโลจึงไปหาคนทั้งสองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 3, 'และเพราะเขามีอาชีพอย่างเดียวกันจึงได้อาศัยทําการอยู่กับเขา เพราะว่าทั้งสองฝ่ายเป็นช่างทําเต็นท์ด้วยกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 4, 'เปาโลได้โต้เถียงในธรรมศาลาทุกวันสะบาโต ได้ชักชวนทั้งพวกยิวและพวกกรีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 5, 'พอสิลาสกับทิโมธีมาจากแคว้นมาซิโดเนีย เปาโลก็ได้รับการดลใจ และเป็นพยานแก่พวกยิวว่าพระเยซูเป็นพระคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 6, 'แต่เมื่อพวกเหล่านั้นขัดขวางตัวเองและกล่าวคําหมิ่นประมาท เปาโลจึงได้สะบัดเสื้อผ้ากล่าวแก่เขาว่า “ให้เลือดของท่านทั้งหลายตกบนศีรษะของท่านเองเถิด ข้าพเจ้าก็ปราศจากเลือดนั้นแล้ว ตั้งแต่นี้ไปข้าพเจ้าจะไปหาคนต่างชาติ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 7, 'ท่านจึงออกจากที่นั่น แล้วเข้าไปในบ้านของชายคนหนึ่งชื่อยุสทัส ซึ่งเป็นผู้นมัสการพระเจ้า บ้านของเขาอยู่ติดกับธรรมศาลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 8, 'ฝ่ายคริสปัสนายธรรมศาลากับทั้งครัวเรือนของท่านได้เชื่อในองค์พระผู้เป็นเจ้า และชาวโครินธ์หลายคนเมื่อได้ฟังแล้วก็ได้เชื่อถือและรับบัพติศมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 9, 'และองค์พระผู้เป็นเจ้าได้ตรัสกับเปาโลทางนิมิตในคืนวันหนึ่งว่า “อย่ากลัวเลย แต่จงกล่าวต่อไป อย่านิ่งเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 10, 'เพราะว่าเราอยู่กับเจ้าและจะไม่มีผู้หนึ่งผู้ใดอาจต่อสู้ทําร้ายเจ้า ด้วยว่าคนของเราในนครนี้มีมาก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 11, 'เปาโลจึงยับยั้งอยู่กับเขาและสั่งสอนพระวจนะของพระเจ้าตลอดหนึ่งปีกับหกเดือน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 12, 'แต่คราวเมื่อกัลลิโอเป็นผู้สําเร็จราชการแคว้นอาคายา พวกยิวได้ฮือกันขึ้นต่อสู้เปาโล และพาท่านไปบัลลังก์พิพากษา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 13, 'ฟ้องว่า “คนนี้ชักชวนคนทั้งหลายให้นมัสการพระเจ้าตามทางที่ผิดกฎหมาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 14, 'เมื่อเปาโลจะอ้าปากพูด กัลลิโอก็กล่าวแก่พวกยิวว่า “โอ พวกยิว ถ้าเป็นเรื่องความชั่วหรือเป็นเรื่องอาชญากรรม สมควรเราจะฟังท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 15, 'แต่ถ้าเป็นการโต้แย้งกันถึงเรื่องถ้อยคํากับชื่อและพระราชบัญญัติของพวกท่านแล้ว ท่านทั้งหลายจงวินิจฉัยกันเอาเองเถิด เราไม่อยากเป็นผู้พิพากษาตัดสินข้อความเหล่านั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 16, 'ท่านจึงไล่พวกนั้นไปจากบัลลังก์พิพากษา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 17, 'บรรดาชาติกรีกจึงจับโสสเธเนสนายธรรมศาลา มาเฆี่ยนข้างหน้าบัลลังก์พิพากษา แต่กัลลิโอไม่เอาธุระเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 18, 'ต่อมาเปาโลได้พักอยู่ที่นั่นอีกหลายวัน แล้วท่านจึงลาพวกพี่น้องแล่นเรือไปยังแคว้นซีเรีย และปริสสิลลากับอาควิลลาก็ไปด้วย เปาโลได้โกนศีรษะที่เมืองเคนเครีย เพราะท่านได้ปฏิญาณตัวไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 19, 'ครั้นมายังเมืองเอเฟซัส เปาโลได้ละปริสสิลลากับอาควิลลาไว้ที่นั่น แต่ท่านเองได้เข้าไปโต้เถียงกับพวกยิวในธรรมศาลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 20, 'เมื่อคนเหล่านั้นขอให้ท่านอยู่กับเขาต่อไป ท่านก็ไม่ยอม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 21, 'แต่ได้ลาเขาไปกล่าวว่า “ข้าพเจ้าจะพยายามรักษาเทศกาลเลี้ยงที่จะถึงในกรุงเยรูซาเล็มโดยทุกวิถีทาง แต่ถ้าเป็นที่ชอบพระทัยพระเจ้า ข้าพเจ้าจะกลับมาหาท่านทั้งหลายอีก” แล้วเปาโลได้ลงเรือแล่นออกจากเมืองเอเฟซัส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 22, 'ครั้นมาถึงเมืองซีซารียา ท่านได้ขึ้นไปคํานับคริสตจักรแล้วลงไปยังเมืองอันทิโอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 23, 'ครั้นยับยั้งอยู่ที่นั่นหน่อยหนึ่ง ท่านจึงไปตลอดแว่นแคว้นกาลาเทียและฟรีเจียตามลําดับกันไปเรื่อยๆ เพื่อจะช่วยชูกําลังพวกสาวก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 24, 'มียิวคนหนึ่งชื่ออปอลโล เกิดในเมืองอเล็กซานเดรีย เป็นคนมีโวหารดี และชํานาญมากในทางพระคัมภีร์ ท่านมายังเมืองเอเฟซัส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 25, 'อปอลโลคนนี้ได้รับการอบรมในทางขององค์พระผู้เป็นเจ้า และมีใจร้อนรนกล่าวสั่งสอนโดยละเอียดถึงเรื่ององค์พระผู้เป็นเจ้า ถึงแม้ว่าท่านรู้แต่เพียงบัพติศมาของยอห์นเท่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 26, 'ท่านได้ตั้งต้นสั่งสอนโดยใจกล้าในธรรมศาลา แต่เมื่ออาควิลลากับปริสสิลลาได้ฟังท่านแล้ว เขาจึงรับท่านมาสั่งสอนให้รู้ทางของพระเจ้าให้ถูกต้องยิ่งขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 27, 'ครั้นอปอลโลใคร่จะไปยังแคว้นอาคายา พวกพี่น้องก็เขียนจดหมายฝากไปถึงสาวกที่นั่นให้เขารับรองท่านไว้ ครั้นท่านไปถึงแล้ว ท่านได้ช่วยเหลือคนทั้งหลายที่ได้เชื่อโดยพระคุณนั้นอย่างมากมาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 28, 'เพราะท่านโต้แย้งกับพวกยิวอย่างแข็งแรงต่อหน้าคนทั้งปวง และชี้แจงยกหลักในพระคัมภีร์อ้างให้เห็นว่า พระเยซูคือพระคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 1, 'ต่อมาขณะที่อปอลโลยังอยู่ในเมืองโครินธ์นั้น เปาโลได้ไปตามแว่นแคว้นฝ่ายเหนือ แล้วมายังเมืองเอเฟซัส และพบสาวกบางคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 2, 'จึงถามเขาว่า “ตั้งแต่ท่านทั้งหลายเชื่อนั้น ท่านได้รับพระวิญญาณบริสุทธิ์หรือเปล่า” เขาตอบเปาโลว่า “เปล่า เรื่องพระวิญญาณบริสุทธิ์นั้นเราก็ยังไม่เคยได้ยินเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 3, 'เปาโลจึงถามเขาว่า “ถ้าอย่างนั้นท่านได้รับบัพติศมาอันใดเล่า” เขาตอบว่า “บัพติศมาของยอห์น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 4, 'เปาโลจึงว่า “ยอห์นให้รับบัพติศมาสําแดงถึงการกลับใจใหม่ก็จริง แล้วบอกคนทั้งปวงให้เชื่อในพระองค์ผู้จะเสด็จมาภายหลังคือพระเยซูคริสต์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 5, 'เมื่อเขาได้ยินอย่างนั้น เขาจึงรับบัพติศมาในพระนามของพระเยซูเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 6, 'เมื่อเปาโลได้วางมือบนเขาแล้ว พระวิญญาณบริสุทธิ์ก็เสด็จลงมาบนเขา เขาจึงพูดภาษาต่างๆและได้พยากรณ์ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 7, 'คนเหล่านั้นมีผู้ชายประมาณสิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 8, 'เปาโลเข้าไปกล่าวโต้แย้งในธรรมศาลาด้วยใจกล้าสิ้นสามเดือน ชักชวนให้เชื่อในสิ่งที่กล่าวถึงอาณาจักรของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 9, 'แต่บางคนมีใจแข็งกระด้างไม่เชื่อและพูดหยาบช้าเรื่องทางนั้นต่อหน้าชุมนุมชน เปาโลจึงแยกไปจากเขาและพาพวกสาวกไปด้วย แล้วท่านได้ไปโต้แย้งกันทุกวันในห้องประชุมของท่านผู้หนึ่งชื่อ ทีรันนัส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 10, 'ท่านได้กระทําอย่างนั้นสิ้นสองปี จนชาวแคว้นเอเชียทั้งพวกยิวและพวกกรีกได้ยินพระวจนะของพระเยซูเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 11, 'พระเจ้าได้ทรงกระทําการอัศจรรย์อันพิสดารด้วยมือของเปาโล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 12, 'จนเขานําเอาผ้าเช็ดหน้ากับผ้ากันเปื้อนจากตัวเปาโลไปวางที่ตัวคนป่วยไข้ โรคนั้นก็หายและวิญญาณชั่วก็ออกจากคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 13, 'แต่พวกยิวบางคนที่เที่ยวไปเป็นหมอผีพยายามใช้พระนามของพระเยซูเจ้าขับวิญญาณชั่วว่า “เราสั่งเจ้าโดยพระเยซูซึ่งเปาโลได้ประกาศนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 14, 'พวกยิวคนหนึ่งชื่อเสวาเป็นปุโรหิตใหญ่มีบุตรชายเจ็ดคนซึ่งได้กระทําอย่างนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 15, 'ฝ่ายวิญญาณชั่วจึงตอบเขาว่า “พระเยซู ข้าก็รู้จัก และเปาโล ข้าก็รู้จัก แต่พวกเจ้าเป็นผู้ใดเล่า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 16, 'คนที่มีวิญญาณชั่วสิงอยู่จึงกระโดดใส่คนเหล่านั้นและเอาชนะเขา และปราบเขาลงได้ จนคนเหล่านั้นต้องหนีออกไปจากเรือนทั้งเปลือยกายและบาดเจ็บ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 17, 'เรื่องนั้นได้ลือกันไปถึงหูคนทั้งปวงที่อยู่ในเมืองเอเฟซัสทั้งพวกยิวกับพวกกรีก และคนทั้งปวงก็พากันมีความเกรงกลัว และพระนามของพระเยซูเจ้าก็เป็นที่ยกย่องสรรเสริญ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 18, 'มีหลายคนที่เชื่อแล้วได้มาสารภาพ และเล่าเรื่องการซึ่งเขาได้กระทําไปนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 19, 'และหลายคนที่ใช้เวทมนตร์ได้เอาตําราของตนมาเผาเสียต่อหน้าคนทั้งปวง ตําราเหล่านั้นคิดเป็นราคาถึงห้าหมื่นเหรียญเงิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 20, 'พระวจนะของพระเจ้าก็บังเกิดผลอย่างมากและมีชัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 21, 'ครั้นสิ้นเหตุการณ์เหล่านี้แล้วเปาโลได้ตั้งใจว่า เมื่อไปทั่วแคว้นมาซิโดเนียกับแคว้นอาคายาแล้วจะเลยไปยังกรุงเยรูซาเล็ม และพูดว่า “เมื่อข้าพเจ้าไปที่นั่นแล้ว ข้าพเจ้าจะต้องไปเห็นกรุงโรมด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 22, 'ท่านจึงใช้ผู้ช่วยของท่านสองคน คือทิโมธีกับเอรัสทัสไปยังแคว้นมาซิโดเนีย ฝ่ายท่านก็พักอยู่หน่อยหนึ่งในแคว้นเอเชีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 23, 'คราวนั้นเกิดการวุ่นวายมากเพราะเหตุทางนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 24, 'ด้วยมีชายคนหนึ่งชื่อเดเมตริอัส เป็นช่างเงินได้เอาเงินทําเป็นรูปพระอารเทมิสทําให้พวกช่างนั้นได้กําไรมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 25, 'เดเมตริอัสจึงประชุมช่างเหล่านั้นที่ทําการคล้ายกันแล้วว่า “ท่านทั้งหลาย ท่านทราบอยู่ว่าพวกเราได้ทรัพย์สินเงินทองมาก็เพราะทําการอันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 26, 'และท่านทั้งหลายได้ยินและได้เห็นอยู่ว่า ไม่ใช่เฉพาะในเมืองเอเฟซัสเมืองเดียว แต่เกือบทั่วแคว้นเอเชีย เปาโลคนนี้ได้ชักชวนคนเป็นอันมากให้เลิกทางเก่าเสีย โดยได้กล่าวว่าสิ่งที่มือมนุษย์ทํานั้นไม่ใช่พระ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 27, 'น่ากลัวว่าไม่ใช่แต่อาชีพของเราจะเสียไปอย่างเดียว แต่พระวิหารของพระแม่เจ้าอารเทมิสซึ่งเป็นใหญ่จะเป็นที่หมิ่นประมาทด้วย และสง่าราศีแห่งรูปของพระแม่เจ้านั้นซึ่งเป็นที่นับถือของบรรดาชาวแคว้นเอเชียกับสิ้นทั้งโลก จะเสื่อมลงไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 28, 'ครั้นคนทั้งหลายได้ยินดังนั้น ต่างก็โกรธแค้นและร้องว่า “พระอารเทมิสของชาวเอเฟซัสเป็นใหญ่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 29, 'แล้วก็เกิดการวุ่นวายใหญ่โตทั่วทั้งเมือง เขาจึงได้จับกายอัสกับอาริสทารคัสชาวมาซิโดเนียผู้เป็นเพื่อนเดินทางของเปาโล ลากวิ่งเข้าไปในโรงมหรสพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 30, 'ฝ่ายเปาโลใคร่จะเข้าไปในหมู่คนด้วย แต่พวกสาวกไม่ยอมให้ท่านเข้าไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 31, 'มีบางคนในพวกเจ้านายที่ประจําแคว้นเอเชียซึ่งเป็นสหายของเปาโล ได้ใช้คนไปวิงวอนขอเปาโลมิให้เข้าไปในโรงมหรสพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 32, 'บางคนจึงได้ร้องว่าอย่างนี้ บางคนได้ร้องว่าอย่างนั้น เพราะว่าที่ประชุมวุ่นวายมาก และคนโดยมากไม่รู้ว่าเขาประชุมกันด้วยเรื่องอะไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 33, 'พวกเหล่านั้นบางคนได้ดันอเล็กซานเดอร์ ซึ่งเป็นคนที่พวกยิวให้ออกมาข้างหน้า อเล็กซานเดอร์จึงโบกมือหมายจะกล่าวแก้แทนต่อหน้าคนทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 34, 'แต่เมื่อคนทั้งหลายรู้ว่าท่านเป็นคนยิว เขาก็ยิ่งส่งเสียงร้องพร้อมกันอยู่ประมาณสักสองชั่วโมงว่า “พระอารเทมิสของชาวเอเฟซัสเป็นใหญ่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 35, 'เมื่อเจ้าหน้าที่ทะเบียนของเมืองนั้นยอมคล้อยตามจนประชาชนสงบลงแล้วเขาก็กล่าวว่า “ท่านชาวเอเฟซัสทั้งหลาย มีผู้ใดบ้างซึ่งไม่ทราบว่า เมืองเอเฟซัสนี้เป็นเมืองที่นมัสการพระแม่เจ้าอารเทมิสผู้ยิ่งใหญ่ และนมัสการรูปจําลองซึ่งตกลงมาจากดาวพฤหัสบดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 36, 'เมื่อข้อนั้นกล่าวโต้แย้งไม่ได้แล้ว ท่านทั้งหลายควรจะนิ่งสงบสติอารมณ์ อย่าทําอะไรวู่วามไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 37, 'ท่านทั้งหลายได้พาคนเหล่านี้มา ซึ่งมิใช่เป็นคนปล้นพระวิหารหรือพูดหมิ่นประมาทพระแม่เจ้าของพวกท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 38, 'เหตุฉะนั้น ถ้าแม้เดเมตริอัสกับพวกช่างที่มีอาชีพอย่างเดียวกันเป็นความกับผู้ใด วันกําหนดที่จะว่าความก็มี ผู้พิพากษาก็มี ให้เขามาฟ้องกันเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 39, 'แต่ถ้าแม้ท่านมีข้อหาอะไรอีก ก็ให้ชําระกันในที่ประชุมตามกฎหมาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 40, 'ด้วยว่าน่ากลัวเราจะต้องถูกฟ้องว่าเป็นผู้ก่อการจลาจลวันนี้ เพราะเราทั้งหลายไม่อาจยกข้อใดขึ้นอ้างเป็นมูลเหตุพอแก่การจลาจลคราวนี้ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 41, 'ครั้นกล่าวอย่างนั้นแล้วท่านจึงให้เลิกชุมนุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 1, 'ครั้นการวุ่นวายนั้นสงบแล้ว เปาโลจึงให้ไปตามพวกสาวกมา กอดกันแล้วก็ลาเขาไปยังแคว้นมาซิโดเนีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 2, 'เมื่อได้ข้ามที่นั้นไปแล้วและได้สั่งเตือนสติเขามาก ท่านก็มายังประเทศกรีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 3, 'พักอยู่ที่นั่นสามเดือน และเมื่อท่านจวนจะลงเรือไปยังแคว้นซีเรีย พวกยิวก็คิดร้ายต่อท่าน ท่านจึงตั้งใจกลับไปทางแคว้นมาซิโดเนีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 4, 'คนที่ไปยังแคว้นเอเชียกับเปาโลคือโสปาเทอร์ชาวเมืองเบโรอา อาริสทารคัสกับเสคุนดัสชาวเมืองเธสะโลนิกา กายอัสชาวเมืองเดอร์บี และทิโมธี ทีคิกัสกับโตรฟีมัสชาวแคว้นเอเชีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 5, 'แต่คนเหล่านั้นได้เดินทางล่วงหน้าไปคอยพวกเราอยู่ที่เมืองโตรอัสก่อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 6, 'ครั้นวันเทศกาลขนมปังไร้เชื้อล่วงไปแล้ว เราทั้งหลายจึงลงเรือออกจากเมืองฟีลิปปี และต่อมาห้าวันก็มาถึงพวกนั้นที่เมืองโตรอัส และยับยั้งอยู่ที่นั่นเจ็ดวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 7, 'ในวันต้นสัปดาห์เมื่อพวกสาวกประชุมกันทําพิธีหักขนมปัง เปาโลก็กล่าวสั่งสอนเขา เพราะว่าวันรุ่งขึ้นจะลาไปจากเขาแล้ว ท่านได้กล่าวยืดยาวไปจนเที่ยงคืน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 8, 'มีตะเกียงหลายดวงในห้องชั้นบนที่เขาประชุมกันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 9, 'ชายหนุ่มคนหนึ่งชื่อยุทิกัสนั่งอยู่ที่หน้าต่างง่วงนอนเต็มที และเมื่อเปาโลสั่งสอนช้านานไปอีก คนนั้นก็โงกพลัดตกจากหน้าต่างชั้นที่สาม เมื่อยกขึ้นก็เห็นว่าตายเสียแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 10, 'ฝ่ายเปาโลจึงลงไป ก้มตัวกอดผู้นั้นไว้ แล้วว่า “อย่าตกใจเลย ด้วยว่าชีวิตยังอยู่ในตัวเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 11, 'ครั้นเปาโลขึ้นไปห้องชั้นบนหักขนมปังและรับประทานแล้ว ก็สนทนาต่อไปอีกช้านานจนสว่าง ท่านก็ลาเขาไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 12, 'คนทั้งหลายจึงพาคนหนุ่มผู้ยังเป็นอยู่ไป และก็ปลื้มใจยินดีไม่น้อยเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 13, 'ฝ่ายพวกเราก็ลงเรือแล่นไปยังเมืองอัสโสสก่อน ตั้งใจว่าจะรับเปาโลที่นั่น ด้วยท่านสั่งไว้อย่างนั้น เพราะท่านหมายว่าจะไปทางบก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 14, 'ครั้นท่านพบกับเราที่เมืองอัสโสส เราก็รับท่าน แล้วมายังเมืองมิทิเลนี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 15, 'ครั้นแล่นเรือออกจากที่นั่นได้วันหนึ่งก็มายังที่ตรงข้ามเกาะคิโอส วันที่สองก็มาถึงเกาะสามอส และหยุดพักที่โตรกิเลียม และอีกวันหนึ่งก็มาถึงเมืองมิเลทัส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 16, 'ด้วยว่าเปาโลได้ตั้งใจว่า จะแล่นเลยเมืองเอเฟซัสไป เพื่อจะไม่ต้องค้างอยู่นานในแคว้นเอเชีย เพราะท่านรีบให้ถึงกรุงเยรูซาเล็ม ถ้าเป็นได้ให้ทันวันเทศกาลเพ็นเทคอสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 17, 'เปาโลจึงใช้คนจากเมืองมิเลทัสไปยังเมืองเอเฟซัส ให้เชิญพวกผู้ปกครองในคริสตจักรนั้นมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 18, 'ครั้นเขาทั้งหลายมาถึงเปาโลแล้ว เปาโลจึงกล่าวแก่เขาว่า “ท่านทั้งหลายย่อมทราบอยู่เองว่า ข้าพเจ้าได้ประพฤติต่อท่านอย่างไรทุกเวลา ตั้งแต่วันแรกที่ข้าพเจ้าเข้ามาในแคว้นเอเชีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 19, 'ข้าพเจ้าได้ปรนนิบัติองค์พระผู้เป็นเจ้าด้วยความถ่อมใจ ด้วยน้ําตาไหลเป็นอันมาก และด้วยการถูกทดลอง ซึ่งมาถึงข้าพเจ้าเพราะพวกยิวคิดร้ายต่อข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 20, 'และสิ่งหนึ่งสิ่งใดซึ่งเป็นคุณประโยชน์แก่ท่านทั้งหลาย ข้าพเจ้ามิได้ปิดซ่อนไว้ แต่ได้ชี้แจงให้ท่านเห็นกับได้สั่งสอนท่านต่อหน้าคนทั้งปวงและตามบ้านเรือน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 21, 'ทั้งเป็นพยานแก่พวกยิวและพวกกรีก ถึงเรื่องการกลับใจใหม่เฉพาะพระเจ้า และความเชื่อในพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 22, 'ดูเถิด บัดนี้พระวิญญาณพันผูกข้าพเจ้า จึงจําเป็นจะต้องไปยังกรุงเยรูซาเล็ม ไม่ทราบว่าจะมีอะไรเกิดขึ้นกับข้าพเจ้าที่นั่นบ้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 23, 'เว้นไว้แต่พระวิญญาณบริสุทธิ์ทรงเป็นพยานในทุกบ้านทุกเมืองว่า เครื่องจองจําและความยากลําบากคอยท่าข้าพเจ้าอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 24, 'แต่สิ่งเหล่านี้ไม่ได้เปลี่ยนแปลงข้าพเจ้าเลย ข้าพเจ้ามิได้ถือว่าชีวิตของข้าพเจ้าเป็นสิ่งประเสริฐแก่ข้าพเจ้า แต่ในชีวิตของข้าพเจ้าขอทําหน้าที่ให้สําเร็จด้วยความปีติยินดี และทําการปรนนิบัติที่ได้รับมอบหมายจากพระเยซูเจ้า คือที่จะเป็นพยานถึงข่าวประเสริฐแห่งพระคุณของพระเจ้านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 25, 'ดูเถิด ข้าพเจ้าเที่ยวป่าวประกาศอาณาจักรของพระเจ้าในหมู่พวกท่าน บัดนี้ ข้าพเจ้าทราบอยู่ว่าท่านทั้งหลายจะไม่เห็นหน้าข้าพเจ้าอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 26, 'เหตุฉะนั้น วันนี้ข้าพเจ้ายืนยันต่อท่านทั้งหลายว่า ข้าพเจ้าหมดราคีจากโลหิตของทุกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 27, 'เพราะว่า ข้าพเจ้ามิได้ย่อท้อในการกล่าวเรื่องพระดําริของพระเจ้าทั้งสิ้น ให้ท่านทั้งหลายฟัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 28, 'เพราะฉะนั้นท่านทั้งหลายจงระวังตัวให้ดี และจงรักษาฝูงแกะทั้งหมดที่พระวิญญาณบริสุทธิ์ได้ทรงตั้งท่านไว้ให้เป็นผู้ดูแล และเพื่อจะได้บํารุงเลี้ยงคริสตจักรของพระเจ้า ที่พระองค์ทรงไถ่ด้วยพระโลหิตของพระองค์เอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 29, 'ข้าพเจ้าทราบอยู่ว่า เมื่อข้าพเจ้าไปแล้ว จะมีสุนัขป่าอันร้ายเข้ามาในหมู่พวกท่าน และจะไม่ละเว้นฝูงแกะไว้เลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 30, 'จะมีบางคนในหมู่พวกท่านเองขึ้นกล่าวบิดเบือนความจริง เพื่อจะชักชวนพวกสาวกให้หลงตามเขาไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 31, 'เหตุฉะนั้นจงตื่นตัวอยู่และจําไว้ว่า ข้าพเจ้าได้สั่งสอนเตือนสติท่านทุกคนด้วยน้ําตาไหล ทั้งกลางคืนและกลางวันตลอดสามปีมิได้หยุดหย่อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 32, 'พี่น้องทั้งหลาย บัดนี้ข้าพเจ้าฝากท่านไว้กับพระเจ้าและกับพระดํารัสแห่งพระคุณของพระองค์ ซึ่งมีฤทธิ์ก่อสร้างท่านขึ้นได้ และให้ท่านมีมรดกด้วยกันกับบรรดาผู้ที่ทรงแยกตั้งไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 33, 'ข้าพเจ้ามิได้โลภเงินหรือทองหรือเสื้อผ้าของผู้ใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 34, 'แท้จริง ท่านทั้งหลายทราบว่า มือของข้าพเจ้าเองนี้ ได้จัดหาสิ่งที่จําเป็นสําหรับตัวข้าพเจ้ากับคนที่อยู่กับข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 35, 'ข้าพเจ้าได้วางแบบอย่างไว้ให้ท่านทุกอย่างแล้ว ให้เห็นว่าโดยทํางานเช่นนี้ควรจะช่วยคนที่มีกําลังน้อย และให้ระลึกถึงพระวจนะของพระเยซูเจ้า ซึ่งพระองค์ตรัสว่า ‘การให้เป็นเหตุให้มีความสุขยิ่งกว่าการรับ’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 36, 'ครั้นเปาโลกล่าวอย่างนั้นแล้วจึงคุกเข่าลงอธิษฐานกับคนเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 37, 'เขาทั้งหลายจึงร้องไห้มากมาย และกอดคอของเปาโล จุบท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 38, 'เขาเป็นทุกข์มากที่สุดเพราะเหตุถ้อยคําที่ท่านกล่าวว่า เขาจะไม่เห็นหน้าท่านอีก แล้วเขาก็พาท่านไปส่งที่เรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 1, 'ต่อมาเมื่อพวกเราลาเขาเหล่านั้นแล้วก็แล่นเรือตรงไปยังเกาะโขส อีกวันหนึ่งก็มาถึงเกาะโรดส์ เมื่อออกจากที่นั่นก็มายังเมืองปาทารา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 2, 'เราพบเรือลําหนึ่งที่ไปเมืองฟินิเซีย จึงลงเรือลํานั้นแล่นต่อไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 3, 'ครั้นแลเห็นเกาะไซปรัสแล้ว เราก็ผ่านเกาะนั้นไปข้างขวา แล่นไปยังแคว้นซีเรีย จอดเรือที่ท่าเมืองไทระ เพราะจะเอาของบรรทุกขึ้นท่าที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 4, 'เมื่อไปหาพวกสาวกพบแล้ว เราจึงพักอยู่ที่นั่นเจ็ดวัน สาวกได้เตือนเปาโลโดยพระวิญญาณ มิให้ขึ้นไปยังกรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 5, 'แต่เมื่อวันเหล่านั้นล่วงไปแล้วพวกเราก็ลาไป สาวกทั้งหลายกับทั้งภรรยาและบุตรได้ส่งพวกเราออกจากเมือง แล้วเราทั้งหลายก็ได้คุกเข่าลงอธิษฐานที่ชายหาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 6, 'และคํานับลาซึ่งกันและกัน พวกเราก็ลงเรือและเขาก็กลับไปบ้านของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 7, 'ครั้นพวกเราแล่นเรือมาจากเมืองไทระถึงเมืองทอเลเมอิสแล้ว ก็สิ้นทางทะเล เราจึงคํานับพวกพี่น้องและพักอยู่กับเขาหนึ่งวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 8, 'ครั้นรุ่งขึ้นพวกเราที่เป็นเพื่อนเดินทางกับเปาโลก็ลาไป และมาถึงเมืองซีซารียา เราก็เข้าไปในบ้านของฟีลิป ผู้ประกาศข่าวประเสริฐ ซึ่งเป็นคนหนึ่งในจําพวกเจ็ดคนนั้น เราก็อาศัยอยู่กับท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 9, 'ฟีลิปมีบุตรสาวพรหมจารีสี่คนซึ่งได้พยากรณ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 10, 'ครั้นเราอยู่ที่นั่นหลายวันแล้ว มีผู้พยากรณ์คนหนึ่งลงมาจากแคว้นยูเดียชื่ออากาบัส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 11, 'ครั้นมาถึงเราเขาก็เอาเครื่องคาดเอวของเปาโลผูกมือและเท้าของตนกล่าวว่า “พระวิญญาณบริสุทธิ์ตรัสดังนี้ว่า ‘พวกยิวในกรุงเยรูซาเล็มจะผูกมัดคนที่เป็นเจ้าของเครื่องคาดเอวนี้ และจะมอบเขาไว้ในมือของคนต่างชาติ’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 12, 'ครั้นเราได้ยินดังนั้น เรากับคนทั้งหลายที่อยู่ที่นั่น จึงอ้อนวอนเปาโลมิให้ขึ้นไปยังกรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 13, 'ฝ่ายเปาโลตอบว่า “เหตุไฉนท่านทั้งหลายจึงร้องไห้และทําให้ข้าพเจ้าช้ําใจ ด้วยข้าพเจ้าเต็มใจพร้อมที่จะไปให้เขาผูกมัดไว้อย่างเดียวก็หามิได้ แต่เต็มใจพร้อมจะตายที่ในกรุงเยรูซาเล็มด้วยเพราะเห็นแก่พระนามของพระเยซูเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 14, 'เมื่อท่านไม่ยอมฟังตามคําชักชวน เราก็หยุดพูดและกล่าวว่า “ขอให้เป็นไปตามพระทัยองค์พระผู้เป็นเจ้าเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 15, 'ภายหลังวันเหล่านั้นเราก็จัดแจงข้าวของ และขึ้นไปยังกรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 16, 'สาวกบางคนที่มาจากเมืองซีซารียาก็ได้ไปกับเราด้วย เขานําเราไปหาคนหนึ่งชื่อมนาสันชาวเกาะไซปรัส เป็นสาวกเก่าแก่ ให้เราอาศัยอยู่กับคนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 17, 'เมื่อเรามาถึงกรุงเยรูซาเล็มแล้ว พวกพี่น้องก็รับรองเราไว้ด้วยความยินดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 18, 'ครั้นรุ่งขึ้น เปาโลกับเราทั้งหลายจึงเข้าไปหายากอบ และพวกผู้ปกครองก็อยู่พร้อมกันที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 19, 'เมื่อเปาโลคํานับท่านเหล่านั้นแล้ว จึงได้กล่าวถึงเหตุการณ์ทั้งปวงตามลําดับ ซึ่งพระเจ้าทรงโปรดกระทําในหมู่คนต่างชาติโดยการปรนนิบัติของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 20, 'ครั้นคนทั้งหลายได้ยินจึงสรรเสริญองค์พระผู้เป็นเจ้า และกล่าวแก่เปาโลว่า “พี่เอ๋ย ท่านเห็นว่ามีพวกยิวสักกี่พันคนที่เชื่อถือ และทุกคนยังมีใจร้อนรนในการถือพระราชบัญญัติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 21, 'เขาทั้งหลายได้ยินถึงท่านว่า ท่านได้สั่งสอนพวกยิวทั้งปวงที่อยู่ในหมู่ชนต่างชาติให้ละทิ้งโมเสส และว่าไม่ต้องให้บุตรของตนเข้าสุหนัตหรือประพฤติตามธรรมเนียมเก่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 22, 'เรื่องนั้นเป็นอย่างไร คนเป็นอันมากจะต้องมาประชุมกัน เพราะเขาทั้งหลายจะได้ยินว่าท่านมาแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 23, 'เหตุฉะนั้นจงทําอย่างนี้ตามที่เราจะบอกแก่ท่าน คือว่าเรามีชายสี่คนที่ได้ปฏิญาณตัวไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 24, 'ท่านจงพาคนเหล่านั้นไปชําระตัวด้วยกันกับเขาและเสียเงินแทนเขา เพื่อเขาจะได้โกนศีรษะ คนทั้งหลายจึงจะรู้ว่าความที่เขาได้ยินถึงท่านนั้นเป็นความเท็จ แต่ท่านเองดําเนินชีวิตให้มีระเบียบและรักษาพระราชบัญญัติอยู่ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 25, 'แต่ฝ่ายคนต่างชาติที่เชื่อนั้น เราได้เขียนจดหมายตัดสินมิให้เขาถือเช่นนั้น แต่ให้เขาทั้งหลายงดไม่รับประทานของซึ่งบูชาแก่รูปเคารพ ไม่รับประทานเลือด ไม่รับประทานเนื้อสัตว์ที่รัดคอตาย และไม่ล่วงประเวณี”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 26, 'เปาโลจึงพาสี่คนนั้นไป และวันรุ่งขึ้นได้ชําระตัวด้วยกันกับเขา แล้วจึงเข้าไปในพระวิหารประกาศวันที่การชําระนั้นจะสําเร็จ จนถึงวันที่จะนําเครื่องบูชามาถวายเพื่อคนเหล่านั้นทุกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 27, 'ครั้นเกือบจะสิ้นเจ็ดวันแล้ว พวกยิวที่มาจากแคว้นเอเชีย เมื่อเห็นเปาโลในพระวิหารจึงยุยงประชาชน แล้วจับเปาโล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 28, 'ร้องว่า “ชนชาติอิสราเอลเอ๋ย จงช่วยกันเถิด คนนี้เป็นผู้ที่ได้สอนคนทั้งปวงทุกตําบลให้เป็นศัตรูต่อชนชาติของเรา ต่อพระราชบัญญัติและต่อสถานที่นี้ และยิ่งกว่านั้นอีก เขาได้พาคนชาวกรีกเข้ามาในพระวิหารด้วย จึงทําให้ที่บริสุทธิ์นี้เป็นมลทิน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 29, '(เพราะแต่ก่อน คนเหล่านั้นเห็นโตรฟีมัสชาวเมืองเอเฟซัสอยู่กับเปาโลในเมือง เขาจึงคาดว่าเปาโลได้พาคนนั้นเข้ามาในพระวิหาร)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 30, 'แล้วคนทั้งเมืองก็ฮือกันขึ้น คนทั้งหลายก็วิ่งเข้าไปรวมกัน และจับเปาโลลากออกจากพระวิหาร แล้วก็ปิดประตูเสียทันที');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 31, 'เมื่อเขากําลังหาช่องจะฆ่าเปาโล ข่าวนั้นลือไปยังนายพันกองทัพว่า กรุงเยรูซาเล็มเกิดการวุ่นวายขึ้นทั้งเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 32, 'ในทันใดนั้น นายพันจึงคุมพวกทหารกับพวกนายร้อยวิ่งลงไปยังคนทั้งปวง เมื่อเขาทั้งหลายเห็นนายพันกับพวกทหารมาจึงหยุดตีเปาโล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 33, 'นายพันจึงเข้าไปใกล้แล้วจับเปาโลสั่งให้เอาโซ่สองเส้นล่ามไว้ แล้วถามว่า ท่านเป็นใครและได้ทําอะไรบ้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 34, 'บางคนในหมู่คนเหล่านั้นร้องว่าอย่างนี้ บางคนว่าอย่างนั้น เมื่อนายพันเอาความแน่นอนอะไรไม่ได้เพราะวุ่นวายมาก จึงสั่งให้พาเปาโลเข้าไปในกรมทหาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 35, 'ครั้นมาถึงบันไดแล้ว พวกทหารจึงยกเปาโลขึ้น เพราะคนทั้งปวงกําลังคอยทําร้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 36, 'ด้วยคนทั้งปวงเหล่านั้นตามไปร้องว่า “จงเอาเขาไปฆ่าเสีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 37, 'เมื่อพวกทหารจะพาเปาโลเข้าไปในกรมทหาร เปาโลจึงกล่าวแก่นายพันว่า “ข้าพเจ้าจะพูดกับท่านสักหน่อยได้หรือ” นายพันจึงถามว่า “เจ้าพูดภาษากรีกเป็นหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 38, 'เจ้าเป็นชาวอียิปต์ซึ่งได้ก่อการกบฏแต่ก่อน และพาพวกฆาตกรสี่พันคนเข้าไปในถิ่นทุรกันดารมิใช่หรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 39, 'แต่เปาโลตอบว่า “ข้าพเจ้าเป็นคนยิวซึ่งเกิดในเมืองทาร์ซัสแคว้นซีลีเซีย ไม่ใช่พลเมืองของเมืองย่อมๆ ข้าพเจ้าขอท่านอนุญาตให้พูดกับคนทั้งปวงสักหน่อย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 40, 'ครั้นนายพันอนุญาตแล้ว เปาโลจึงยืนอยู่ที่บันไดโบกมือให้คนทั้งปวง เมื่อคนทั้งปวงนิ่งเงียบลงแล้ว ท่านจึงกล่าวแก่เขาเป็นภาษาฮีบรูว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 1, '“ท่านทั้งหลาย พี่น้องและบรรดาท่านผู้อาวุโส ขอฟังคําให้การซึ่งข้าพเจ้าจะแก้คดีให้ท่านฟัง ณ บัดนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 2, '(ครั้นเขาทั้งหลายได้ยินท่านพูดภาษาฮีบรู เขาก็ยิ่งเงียบลงกว่าก่อน เปาโลจึงกล่าวว่า)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 3, '“ที่จริงข้าพเจ้าเป็นยิว เกิดในเมืองทาร์ซัสแคว้นซีลีเซีย แต่ได้เติบโตขึ้นในเมืองนี้ และได้เล่าเรียนกับท่านอาจารย์กามาลิเอล ตามพระราชบัญญัติของบรรพบุรุษของเราโดยถี่ถ้วนทุกประการ จึงมีใจร้อนรนในการปรนนิบัติพระเจ้า เหมือนอย่างท่านทั้งหลายในทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 4, 'ข้าพเจ้าได้ข่มเหงคนทั้งหลายที่ถือในทางนี้จนถึงตาย และได้ผูกมัดเขาจําไว้ในคุกทั้งชายและหญิง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 5, 'ตามที่มหาปุโรหิตกับสภาอาจเป็นพยานให้ข้าพเจ้าได้ เพราะข้าพเจ้าได้ถือหนังสือจากท่านผู้นั้นไปยังพวกพี่น้อง และได้เดินทางไปเมืองดามัสกัส เพื่อจับมัดคนทั้งหลายพามายังกรุงเยรูซาเล็มให้ทําโทษเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 6, 'ต่อมาเมื่อข้าพเจ้ากําลังเดินทางไปใกล้จะถึงเมืองดามัสกัส ประมาณเวลาเที่ยง ในทันใดนั้นมีแสงสว่างกล้ามาจากฟ้าล้อมข้าพเจ้าไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 7, 'ข้าพเจ้าจึงล้มลงที่ดินและได้ยินพระสุรเสียงตรัสกับข้าพเจ้าว่า ‘เซาโล เซาโลเอ๋ย เจ้าข่มเหงเราทําไม’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 8, 'ข้าพเจ้าจึงทูลตอบว่า ‘พระองค์เจ้าข้า พระองค์ทรงเป็นผู้ใด’ พระองค์จึงตรัสกับข้าพเจ้าว่า ‘เราคือเยซูชาวนาซาเร็ธซึ่งเจ้าข่มเหงนั้น’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 9, 'ฝ่ายคนทั้งหลายที่อยู่กับข้าพเจ้าได้เห็นแสงสว่างนั้นและตกใจกลัว แต่พระสุรเสียงที่ตรัสกับข้าพเจ้านั้นเขาหาได้ยินไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 10, 'ข้าพเจ้าจึงทูลถามว่า ‘พระองค์เจ้าข้า ข้าพเจ้าจะต้องทําประการใด’ องค์พระผู้เป็นเจ้าจึงตรัสแก่ข้าพเจ้าว่า ‘เจ้าจงลุกขึ้นเข้าไปในเมืองดามัสกัส และที่นั่นเขาจะบอกเจ้าให้รู้ถึงการทุกสิ่งซึ่งได้กําหนดไว้ให้เจ้าทํานั้น’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 11, 'เมื่อข้าพเจ้าเห็นอะไรไม่ได้เนื่องจากพระรัศมีอันแรงกล้านั้น คนที่มาด้วยกันกับข้าพเจ้าก็จูงมือพาข้าพเจ้าเข้าไปในเมืองดามัสกัส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 12, 'มีคนหนึ่งชื่ออานาเนีย เป็นคนมีศรัทธามากตามพระราชบัญญัติ และมีชื่อเสียงดีท่ามกลางพวกยิวทั้งปวงที่อยู่ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 13, 'ได้มาหาข้าพเจ้าและยืนอยู่ใกล้กล่าวแก่ข้าพเจ้าว่า ‘พี่เซาโลเอ๋ย จงเห็นได้อีกเถิด’ ข้าพเจ้าจึงเห็นท่านได้ในเวลานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 14, 'ท่านจึงกล่าวว่า ‘พระเจ้าแห่งบรรพบุรุษของเราได้ทรงเลือกท่านไว้ ประสงค์จะให้ท่านรู้จักน้ําพระทัยของพระองค์ ให้ท่านเห็นพระองค์ผู้ชอบธรรมและให้ได้ยินพระสุรเสียงจากพระโอษฐ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 15, 'เพราะว่าท่านจะเป็นพยานฝ่ายพระองค์ให้คนทั้งปวงทราบถึงเหตุการณ์ซึ่งท่านเห็นและได้ยินนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 16, 'เดี๋ยวนี้ท่านจะรอช้าอยู่ทําไม จงลุกขึ้นรับบัพติศมา ด้วยออกพระนามขององค์พระผู้เป็นเจ้า ลบล้างความผิดบาปของท่านเสีย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 17, 'ต่อมาเมื่อข้าพเจ้ากลับมายังกรุงเยรูซาเล็มและกําลังอธิษฐานอยู่ในพระวิหาร ข้าพเจ้าก็เคลิ้มไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 18, 'และได้เห็นพระองค์ตรัสกับข้าพเจ้าว่า ‘จงรีบออกไปจากกรุงเยรูซาเล็มโดยเร็ว ด้วยว่าเขาจะไม่รับคําของเจ้าซึ่งอ้างพยานถึงเรา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 19, 'ข้าพเจ้าจึงทูลว่า ‘พระองค์เจ้าข้า คนเหล่านั้นทราบอยู่ว่า ข้าพระองค์ได้จับคนทั้งหลายที่เชื่อในพระองค์ไปใส่คุกและเฆี่ยนตีตามธรรมศาลาทุกแห่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 20, 'และเมื่อเขาทําให้โลหิตของสเทเฟนพยานผู้ยอมตายเพื่อพระองค์ตกนั้น ข้าพระองค์ได้ยืนอยู่ใกล้และเห็นชอบในการประหารเขาเสียนั้นด้วย และข้าพระองค์เป็นคนเฝ้าเสื้อผ้าของคนที่ฆ่าสเทเฟนนั้น’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 21, 'แล้วพระองค์ตรัสกับข้าพเจ้าว่า ‘จงไปเถิด เราจะใช้ให้เจ้าไปไกล ไปหาคนต่างชาติ’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 22, 'เขาทั้งหลายได้ฟังเปาโลกล่าวแค่นี้ แล้วก็ร้องเสียงดังว่า “เอาคนเช่นนี้ไปจากแผ่นดินโลก ไม่ควรจะให้เขามีชีวิตอยู่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 23, 'เมื่อเขาทั้งหลายกําลังโห่ร้องและถอดเสื้อเอาผงคลีดินซัดขึ้นไปในอากาศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 24, 'นายพันจึงสั่งให้พาเปาโลเข้าไปในกรมทหาร และสั่งให้ไต่สวนโดยการเฆี่ยน เพื่อจะได้รู้ว่าเขาร้องปรักปรําท่านด้วยเหตุประการใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 25, 'ครั้นเอาเชือกหนังมัดเปาโล ท่านจึงถามนายร้อยซึ่งยืนอยู่ที่นั่นว่า “การที่จะเฆี่ยนคนสัญชาติโรมก่อนพิพากษาปรับโทษนั้นถูกต้องตามกฎหมายหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 26, 'เมื่อนายร้อยได้ยินแล้วจึงไปบอกนายพันว่า “ท่านจะทําอะไรนั่น คนนั้นเป็นคนสัญชาติโรม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 27, 'ฝ่ายนายพันจึงไปหาเปาโลถามว่า “ท่านเป็นคนสัญชาติโรมหรือ จงบอกเราเถิด” เปาโลจึงตอบว่า “ใช่แล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 28, 'นายพันจึงตอบว่า “ซึ่งเราเป็นคนสัญชาติโรมได้นั้น เราต้องเสียเงินมาก” เปาโลจึงตอบว่า “ข้าพเจ้าเป็นคนสัญชาติโรมโดยกําเนิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 29, 'ขณะนั้นคนทั้งหลายที่จะไต่สวนเปาโลก็ได้ละท่านไปทันที และนายพันเมื่อทราบว่า เปาโลเป็นคนสัญชาติโรมก็ตกใจกลัวเพราะได้มัดท่านไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 30, 'ครั้นวันรุ่งขึ้นนายพันอยากรู้แน่ว่าพวกยิวได้กล่าวหาเปาโลด้วยเหตุใด จึงได้ถอดเครื่องจําเปาโล สั่งให้พวกปุโรหิตใหญ่กับบรรดาสมาชิกสภาประชุมกัน แล้วพาเปาโลลงไปให้ยืนอยู่ต่อหน้าเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 1, 'ฝ่ายเปาโลจึงเพ่งดูพวกสมาชิกสภาแล้วกล่าวว่า “ท่านพี่น้องทั้งหลาย ข้าพเจ้าได้ประพฤติต่อพระพักตร์พระเจ้าล้วนแต่ตามใจวินิจฉัยผิดชอบอันดีจนถึงทุกวันนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 2, 'อานาเนียผู้เป็นมหาปุโรหิตจึงสั่งคนที่ยืนอยู่ใกล้ให้ตบปากเปาโล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 3, 'เปาโลจึงกล่าวแก่ท่านว่า “พระเจ้าจะทรงตบเจ้า ผู้เป็นผนังที่ฉาบด้วยปูนขาว เจ้านั่งพิพากษาข้าตามพระราชบัญญัติ และยังสั่งให้เขาตบข้าซึ่งเป็นการผิดพระราชบัญญัติหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 4, 'คนทั้งหลายที่ยืนอยู่ที่นั่นจึงถามว่า “เจ้าพูดหยาบคายต่อมหาปุโรหิตของพระเจ้าหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 5, 'เปาโลจึงตอบว่า “พี่น้องทั้งหลาย ข้าพเจ้าไม่ทราบว่าท่านเป็นมหาปุโรหิต ด้วยมีคําเขียนไว้แล้วว่า ‘อย่าพูดหยาบช้าต่อผู้ปกครองชนชาติของเจ้าเลย’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 6, 'ครั้นเปาโลเห็นว่า ผู้ที่อยู่ในประชุมสภานั้นเป็นพวกสะดูสีส่วนหนึ่งและพวกฟาริสีส่วนหนึ่ง ท่านจึงร้องขึ้นต่อหน้าที่ประชุมว่า “ท่านพี่น้องทั้งหลาย ข้าพเจ้าเป็นพวกฟาริสีและเป็นบุตรชายของพวกฟาริสี ที่ข้าพเจ้าถูกพิจารณาพิพากษานี้ก็เพราะเรื่องความหวังว่า มีการเป็นขึ้นมาจากความตาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 7, 'เมื่อท่านกล่าวอย่างนั้นแล้ว พวกฟาริสีกับพวกสะดูสีก็เกิดเถียงกันขึ้น และที่ประชุมก็แตกเป็นสองพวก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 8, 'ด้วยพวกสะดูสีถือว่า การที่เป็นขึ้นมาจากความตายนั้นไม่มีและทูตสวรรค์หรือวิญญาณก็ไม่มี แต่พวกฟาริสีถือว่ามีทั้งนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 9, 'แล้วก็อื้ออึงเกิดโกลาหล และพวกธรรมาจารย์บางคนที่อยู่ฝ่ายพวกฟาริสีก็ลุกขึ้นเถียงว่า “เราไม่เห็นว่าคนนี้มีความผิดอะไร แต่ถ้าวิญญาณก็ดีหรือทูตสวรรค์ก็ดีได้พูดกับเขา พวกเราอย่าต่อสู้กับพระเจ้าเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 10, 'เมื่อการโต้เถียงกันรุนแรงขึ้น นายพันกลัวว่าเขาจะยื้อแย่งจับเปาโลฉีกเสีย ท่านจึงสั่งพวกทหารให้ลงไปรับเปาโลออกจากหมู่พวกนั้นพาเข้าไปไว้ในกรมทหาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 11, 'ในเวลากลางคืนวันนั้นเอง องค์พระผู้เป็นเจ้าทรงยืนอยู่กับเปาโลตรัสว่า “เปาโลเอ๋ย เจ้าจงมีใจกล้าเถิด เพราะว่าเจ้าได้เป็นพยานฝ่ายเราในกรุงเยรูซาเล็มฉันใด เจ้าจะต้องเป็นพยานในกรุงโรมด้วยฉันนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 12, 'ครั้นเวลารุ่งเช้าพวกยิวบางคนได้สมทบกันสบถสาบานตัวว่า เขาทั้งหลายจะไม่กินจะไม่ดื่มอะไรกว่าจะได้ฆ่าเปาโลเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 13, 'คนที่ร่วมกันปองร้ายนั้นมีกว่าสี่สิบคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 14, 'คนเหล่านั้นจึงไปหาพวกปุโรหิตใหญ่กับพวกผู้ใหญ่กล่าวว่า “พวกข้าพเจ้าได้สบถสาบานตัวอย่างแข็งแรงว่าจะไม่รับประทานอาหารจนกว่าจะได้ฆ่าเปาโลเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 15, 'ฉะนั้น บัดนี้ท่านทั้งหลายกับพวกสมาชิกสภาจงพูดให้นายพันเข้าใจว่า พวกท่านต้องการให้พาเปาโลลงมาหาท่านทั้งหลายพรุ่งนี้ เพื่อจะได้ซักถามความให้ถ้วนถี่ยิ่งกว่าแต่ก่อน ฝ่ายพวกข้าพเจ้าจะได้เตรียมตัวไว้พร้อมที่จะฆ่าเปาโลเสียเมื่อยังไม่ทันจะมาถึง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 16, 'แต่บุตรชายของน้องสาวเปาโลได้ยินเรื่องซึ่งเขาคอยทําร้ายนั้น จึงเข้ามาในกรมทหารบอกแก่เปาโล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 17, 'เปาโลจึงเรียกนายร้อยคนหนึ่งมากล่าวว่า “ขอพาชายหนุ่มคนนี้ไปหานายพันด้วย เพราะเขามีเรื่องที่จะแจ้งให้ทราบ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 18, 'เหตุฉะนั้นนายร้อยจึงรับตัวชายหนุ่มคนนั้นไปหานายพันกล่าวว่า “เปาโลผู้ถูกขังอยู่นั้นเรียกข้าพเจ้า ขอให้พาชายหนุ่มคนนี้มาหาท่าน เพราะเขามีเรื่องที่จะแจ้งให้ท่านทราบ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 19, 'นายพันจึงจูงมือชายนั้นไปแต่ลําพัง แล้วถามว่า “เจ้าจะแจ้งความอะไรแก่เรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 20, 'เขาจึงตอบว่า “พวกยิวตกลงกันจะขอท่านให้พาเปาโลลงไปยังสภาเวลาพรุ่งนี้ ทําเสมือนว่าจะไต่สวนเรื่องเขาให้ถ้วนถี่ยิ่งกว่าแต่ก่อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 21, 'แต่ท่านอย่าฟังเขา เพราะว่าในพวกเขานั้นมีกว่าสี่สิบคนคอยปองร้ายต่อเปาโล และได้สบถสาบานตัวว่าจะไม่กินหรือดื่มอะไรจนกว่าจะได้ฆ่าเปาโลเสีย และเดี๋ยวนี้เขาพร้อมแล้ว กําลังคอยรับคําสัญญาจากท่าน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 22, 'นายพันจึงให้ชายหนุ่มนั้นไป กําชับว่า “อย่าบอกผู้ใดให้รู้ว่า เจ้าได้แจ้งความเรื่องนี้แก่เรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 23, 'ฝ่ายนายพันจึงเรียกนายร้อยสองคนมาสั่งว่า “จงจัดพลทหารสองร้อยกับทหารม้าเจ็ดสิบคน และทหารหอกสองร้อย ให้พร้อมในเวลาสามทุ่มคืนวันนี้จะไปยังเมืองซีซารียา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 24, 'และจงจัดสัตว์ให้เปาโลขี่ จะได้ป้องกันส่งไปยังเฟลิกส์ผู้ว่าราชการเมือง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 25, 'แล้วนายพันจึงเขียนจดหมายมีใจความดังต่อไปนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 26, '“คลาวดิอัสลีเซียสเรียนเจ้าคุณเฟลิกส์ ท่านผู้ว่าราชการทราบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 27, 'พวกยิวได้จับคนนี้ไว้และเกือบจะฆ่าเขาเสียแล้ว แต่ข้าพเจ้าพาพวกทหารไปช่วยเขาไว้ได้ ด้วยข้าพเจ้าได้เข้าใจว่าเขาเป็นคนสัญชาติโรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 28, 'ข้าพเจ้าอยากจะทราบเหตุที่พวกยิวฟ้องเขา ข้าพเจ้าจึงพาเขาไปยังสภาของพวกยิว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 29, 'ข้าพเจ้าเห็นว่าเขาถูกฟ้องในเรื่องอันเกี่ยวกับกฎหมายของพวกยิว แต่ไม่มีข้อหาที่เขาควรจะตายหรือควรจะต้องจําไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 30, 'เมื่อมีคนบอกข้าพเจ้าให้ทราบว่าพวกยิวมีการปองร้ายคนนี้ ข้าพเจ้าจึงส่งเขามาหาท่านทีเดียว แล้วได้สั่งให้พวกโจทก์ไปว่าความกับเขาต่อหน้าท่าน สวัสดี”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 31, 'ดังนั้นในเวลากลางคืนพวกทหารจึงพาเปาโลไปถึงเมืองอันทิปาตรีส์ตามคําสั่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 32, 'ครั้นรุ่งเช้าเขาให้ทหารม้าไปส่งเปาโล แล้วเขาก็กลับไปยังกรมทหาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 33, 'ครั้นทหารม้าไปถึงเมืองซีซารียาแล้ว จึงส่งจดหมายให้แก่ผู้ว่าราชการเมืองและได้มอบเปาโลไว้ให้ท่านด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 34, 'เมื่อผู้ว่าราชการเมืองได้อ่านจดหมายแล้ว จึงถามว่าเปาโลมาจากแคว้นไหน เมื่อท่านทราบว่ามาจากซีลีเซีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 35, 'ท่านจึงกล่าวว่า “เมื่อพวกโจทก์มาพร้อมกันแล้ว เราจะฟังคําให้การของเจ้า” ท่านจึงสั่งให้คุมเปาโลไปไว้ที่ศาลปรีโทเรียมของเฮโรด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 1, 'ครั้นล่วงไปได้ห้าวัน อานาเนียมหาปุโรหิตจึงลงไปกับพวกผู้ใหญ่ และนักพูดคนหนึ่งชื่อเทอร์ทูลลัส เขาเหล่านี้ได้ฟ้องเปาโลต่อหน้าผู้ว่าราชการเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 2, 'ครั้นเรียกเปาโลเข้ามาแล้ว เทอร์ทูลลัสจึงเริ่มฟ้องว่า “ท่านเจ้าคุณเฟลิกส์เจ้าข้า ข้าพเจ้าทั้งหลายได้มีความสงบสุขยิ่งนัก เพราะท่านให้มีการปรับปรุงอันเป็นคุณประโยชน์แก่ชาตินี้โดยการคุ้มครองของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 3, 'ข้าพเจ้าทั้งหลายรับอยู่ทุกประการทุกแห่งด้วยจิตกตัญญูเป็นที่ยิ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 4, 'แต่เพื่อมิให้ท่านป่วยการมากไป ข้าพเจ้าขอความกรุณาโปรดฟังข้าพเจ้าสักหน่อยหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 5, 'ด้วยข้าพเจ้าทั้งหลายเห็นว่า ชายคนนี้เป็นคนพาลยุยงพวกยิวทั้งหลายให้เกิดการวุ่นวายทั่วพิภพ และเป็นตัวการของพวกนาซาเร็ธนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 6, 'กับอีกนัยหนึ่งเขาหมายจะทําให้พระวิหารเป็นมลทิน ข้าพเจ้าทั้งหลายจึงจับเขาไว้ และก็คงจะได้พิพากษาเขาตามกฎหมายของพวกข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 7, 'แต่นายพันลีเซียสได้มาใช้อํานาจแย่งตัวเขาไปเสียจากมือของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 8, 'และสั่งให้โจทก์มาฟ้องเขาต่อหน้าท่าน ถ้าท่านเองจะไต่ถามเขา ท่านจะทราบได้ว่า ข้อกล่าวหาของพวกข้าพเจ้าจริงหรือไม่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 9, 'ฝ่ายพวกยิวจึงสนับสนุนคํากล่าวหาด้วยยืนยันว่าเป็นจริงอย่างนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 10, 'เมื่อผู้ว่าราชการเมืองทําสําคัญให้เปาโลพูด ท่านจึงเรียนว่า “เนื่องจากที่ข้าพเจ้าได้ทราบว่าท่านเป็นผู้พิพากษาแก่ชาตินี้หลายปีแล้ว ข้าพเจ้าก็จะขอแก้คดีของข้าพเจ้าด้วยความเบาใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 11, 'ท่านสืบทราบได้ว่า ตั้งแต่ข้าพเจ้าขึ้นไปนมัสการในกรุงเยรูซาเล็มนั้นยังไม่เกินสิบสองวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 12, 'เขาไม่ได้เห็นข้าพเจ้าเถียงกันกับผู้หนึ่งผู้ใด หรือยุยงประชาชนให้วุ่นวาย ไม่ว่าในพระวิหาร ในธรรมศาลาหรือในเมือง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 13, 'เหตุการณ์ทั้งปวงที่เขากําลังฟ้องข้าพเจ้านี้ เขาพิสูจน์ไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 14, 'แต่ว่าข้าพเจ้าขอรับต่อหน้าท่านอย่างหนึ่ง คือตามทางนั้นที่เขาถือว่าเป็นลัทธินอกรีต ข้าพเจ้านมัสการพระเจ้าแห่งบรรพบุรุษทั้งหลายของข้าพเจ้า ข้าพเจ้าได้เชื่อถือคําซึ่งมีเขียนไว้ในพระราชบัญญัติและในคัมภีร์ของศาสดาพยากรณ์ทั้งหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 15, 'ข้าพเจ้ามีความหวังใจในพระเจ้าตามซึ่งเขาเองก็มีความหวังใจด้วย คือหวังใจว่าคนทั้งปวงทั้งคนที่ชอบธรรมและคนที่ไม่ชอบธรรมจะเป็นขึ้นมาจากความตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 16, 'ในข้อนี้ ข้าพเจ้าอุตส่าห์ประพฤติตามใจวินิจฉัยผิดชอบที่ปราศจากผิดต่อพระเจ้าและต่อมนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 17, 'ครั้นล่วงมาหลายปีแล้ว ข้าพเจ้านําทานและเครื่องบูชามายังชนชาติของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 18, 'คราวนั้นมีพวกยิวบางคนที่มาจากแคว้นเอเชียได้พบข้าพเจ้าในพระวิหาร เมื่อข้าพเจ้าชําระตัวแล้ว เขามิได้พบข้าพเจ้าอยู่กับหมู่คนหรือทําวุ่นวาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 19, 'ถ้าคนเหล่านั้นมีเรื่องอะไรที่จะฟ้องข้าพเจ้า เขาควรจะมาฟ้องต่อหน้าท่านที่นี่แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 20, 'หรือขอให้คนเหล่านี้เองกล่าวเรื่องความผิดที่เขาเห็น เมื่อข้าพเจ้ายืนอยู่ต่อหน้าสภา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 21, 'เว้นไว้แต่ข้อเดียวซึ่งข้าพเจ้าได้ร้องขึ้นในท่ามกลางเขาว่า ‘วันนี้ข้าพเจ้าถูกพิจารณาพิพากษาต่อหน้าท่านทั้งหลาย เพราะเหตุเรื่องการเป็นขึ้นมาจากความตาย’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 22, 'เมื่อเฟลิกส์ได้ยินสิ่งเหล่านี้ ท่านก็เลื่อนการพิจารณาไว้ก่อน เพราะท่านได้รู้เรื่องของทางนั้นถี่ถ้วนแล้ว ท่านจึงกล่าวว่า “เมื่อลีเซียสนายพันลงมา เราจะชําระความของเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 23, 'เฟลิกส์สั่งนายร้อยให้คุมตัวเปาโลไว้ แต่ลดหย่อนการกวดขันบ้าง ไม่ให้ห้ามผู้ใดที่เป็นผู้ที่รู้จักกับท่านที่จะเข้ามาปรนนิบัติหรือเยี่ยมเยียน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 24, 'เมื่อล่วงมาได้หลายวันแล้วเฟลิกส์มากับภรรยาชื่อดรูสิลลาผู้เป็นชาติยิว ท่านให้เรียกเปาโลมา แล้วได้ฟังเปาโลกล่าวเรื่องความเชื่อในพระคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 25, 'ขณะเมื่อเปาโลอ้างถึงความชอบธรรม ความอดกลั้นใจทางกาม และการพิพากษาซึ่งจะมาเบื้องหน้านั้น เฟลิกส์ก็กลัวจนตัวสั่น จึงพูดว่า “คราวนี้จงไปก่อนเถอะ เมื่อเรามีโอกาส เราจะเรียกท่านมาอีก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 26, 'อีกนัยหนึ่งเฟลิกส์หวังใจว่า เปาโลจะให้เงินสินบนแก่ท่าน เพื่อท่านจะได้ปล่อยเปาโล เหตุฉะนั้นท่านจึงเรียกเปาโลมาสนทนากันบ่อยๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 27, 'แต่เมื่อสองปีล่วงไปแล้ว ปอรสิอัสเฟสทัสมารับราชการแทนเฟลิกส์ เฟลิกส์อยากจะได้ความชอบจากพวกยิวจึงทิ้งเปาโลไว้ในคุก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 1, 'เมื่อเฟสทัสเข้ารับตําแหน่งราชการได้สามวันแล้ว จึงออกจากเมืองซีซารียาขึ้นไปยังกรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 2, 'มหาปุโรหิตกับคนสําคัญๆในพวกยิวมาฟ้องเปาโลต่อท่าน และได้วิงวอนท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 3, 'ขอให้กรุณาเขาโดยสั่งให้ส่งเปาโลมายังกรุงเยรูซาเล็ม ด้วยเขาคิดจะซุ่มคอยฆ่าท่านเสียกลางทาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 4, 'ฝ่ายเฟสทัสจึงตอบว่า เปาโลนั้นควรจะถูกคุมไว้ในเมืองซีซารียา และอีกหน่อยหนึ่งท่านเองก็จะกลับไปยังเมืองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 5, 'ท่านจึงว่า “ถ้าเปาโลมีความผิดอย่างหนึ่งอย่างใด ให้ผู้ใดในพวกท่านที่สามารถลงไปด้วยกันกับเรายื่นฟ้องเอาเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 6, 'เมื่อท่านพักอยู่ที่นั่นเกินกว่าสิบวันแล้ว ก็ได้ลงไปยังเมืองซีซารียา ครั้นรุ่งขึ้นท่านจึงนั่งบัลลังก์พิพากษา และสั่งให้พาเปาโลเข้ามา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 7, 'ครั้นเปาโลเข้ามาแล้ว พวกยิวที่ลงมาจากกรุงเยรูซาเล็มก็ยืนล้อมไว้รอบ และกล่าวความอุกฉกรรจ์ใส่เปาโลหลายข้อ แต่พิสูจน์ไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 8, 'เปาโลจึงแก้คดีเองว่า “ข้าพเจ้าไม่ได้กระทําอะไรผิดกฎหมายของพวกยิว หรือต่อพระวิหาร หรือต่อซีซาร์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 9, 'ฝ่ายเฟสทัสอยากได้ความชอบจากพวกยิวจึงถามเปาโลว่า “เจ้าจะขึ้นไปยังกรุงเยรูซาเล็มให้เราชําระความเรื่องนี้ที่นั่นหรือ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 10, 'เปาโลตอบว่า “ข้าพเจ้าก็กําลังยืนอยู่ต่อหน้าบัลลังก์พิพากษาของซีซาร์อยู่แล้ว ก็สมควรจะพิพากษาข้าพเจ้าเสียที่นี่ตามที่ท่านทราบดีอยู่แล้วว่า ข้าพเจ้าไม่ได้กระทําผิดต่อพวกยิว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 11, 'เพราะถ้าข้าพเจ้าเป็นผู้กระทําผิด หรือได้กระทําอะไรที่ควรจะมีโทษถึงตาย ข้าพเจ้าก็ยอมตายไม่ขัดขืน แต่ถ้าเรื่องที่เขาฟ้องข้าพเจ้านั้นไม่จริงแล้ว ไม่มีผู้ใดมีอํานาจจะมอบข้าพเจ้าให้เขาได้ ข้าพเจ้าขออุทธรณ์ถึงซีซาร์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 12, 'ฝ่ายเฟสทัสเมื่อพูดกับที่ปรึกษาแล้วจึงตอบว่า “เจ้าได้ขออุทธรณ์ถึงซีซาร์แล้วหรือ เจ้าก็จะต้องไปเฝ้าซีซาร์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 13, 'ครั้นล่วงไปหลายวัน กษัตริย์อากริปปากับพระนางเบอร์นิสก็เสด็จมาเยี่ยมคํานับเฟสทัสยังเมืองซีซารียา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 14, 'ขณะที่ท่านค้างอยู่ที่นั่นหลายวัน เฟสทัสก็เล่าเรื่องคดีของเปาโลให้กษัตริย์ฟังว่า “มีชายคนหนึ่งซึ่งเฟลิกส์ได้ขังทิ้งไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 15, 'เมื่อข้าพเจ้าไปกรุงเยรูซาเล็ม พวกปุโรหิตใหญ่กับพวกผู้ใหญ่ของพวกยิวมาฟ้องขอให้ข้าพเจ้าตัดสินลงโทษเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 16, 'ข้าพเจ้าจึงตอบพวกเขาว่า ไม่ใช่ธรรมเนียมของชาวโรมที่จะมอบตัวจําเลยให้ตายก่อนที่โจทก์กับจําเลยมาพร้อมหน้ากัน และให้จําเลยมีโอกาสแก้คดีในข้อหานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 17, 'ครั้นพวกเขามาถึงที่นี่แล้ว ข้าพเจ้าจึงมิได้รอช้า ในวันรุ่งขึ้นข้าพเจ้าได้นั่งบัลลังก์พิพากษาและสั่งให้พาจําเลยเข้ามา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 18, 'เมื่อพวกโจทก์ยืนขึ้น เขามิได้กล่าวหาจําเลยเหมือนที่ข้าพเจ้าคาดไว้นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 19, 'เป็นแต่เพียงปัญหาเถียงกันด้วยเรื่องลัทธิศาสนาของเขาเอง และด้วยเรื่องคนหนึ่งที่ชื่อเยซูซึ่งตายแล้ว แต่เปาโลยืนยันว่ายังเป็นอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 20, 'เมื่อข้าพเจ้ายังสับสนอยู่ว่าจะพิจารณาปัญหานั้นอย่างไรดี จึงถามเปาโลว่า จะยอมขึ้นไปยังกรุงเยรูซาเล็มให้ชําระความนั้นที่นั่นหรือไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 21, 'แต่เมื่อเปาโลได้อุทธรณ์ขอให้ขังไว้เพื่อให้ออกัสตัสตัดสิน ข้าพเจ้าจึงสั่งให้คุมขังเขาไว้จนกว่าจะส่งตัวไปถึงซีซาร์ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 22, 'อากริปปาจึงกล่าวแก่เฟสทัสว่า “ข้าพเจ้าใคร่จะฟังคนนั้นด้วย” เฟสทัสจึงกล่าวว่า “พรุ่งนี้ท่านจะได้ฟังเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 23, 'ครั้นวันรุ่งขึ้นอากริปปากับเบอร์นิสเสด็จมาพร้อมด้วยราชบริพารเป็นที่สง่าผ่าเผยมาก จึงเข้าไปประทับในห้องพิจารณาพร้อมกับนายพันและคนสําคัญๆทั้งหลายในนครนั้น แล้วเฟสทัสจึงสั่งให้พาเปาโลเข้ามา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 24, 'เฟสทัสจึงกล่าวว่า “ท่านกษัตริย์อากริปปา และท่านทั้งหลายที่อยู่ด้วยกันที่นี่ ท่านทั้งหลายเห็นชายคนนี้ที่บรรดาพวกยิวได้วิงวอนข้าพเจ้าทั้งในกรุงเยรูซาเล็มและที่นี่ด้วยร้องว่าเขาไม่ควรจะมีชีวิตอยู่ต่อไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 25, 'แต่ข้าพเจ้าเห็นว่าเขาไม่ได้ทําผิดสิ่งไรที่ควรจะต้องตาย และเพราะเขาเองได้อุทธรณ์ถึงออกัสตัส ข้าพเจ้าตกลงใจว่าจะส่งเขาไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 26, 'ข้าพเจ้าไม่มีรายงานอะไรแน่ชัดเรื่องคนนี้ที่จะถวายเจ้านายของข้าพเจ้า เหตุฉะนั้นข้าพเจ้าจึงพาเขาออกมาต่อหน้าท่านทั้งหลาย และโดยเฉพาะอย่างยิ่งต่อพระพักตร์ของพระองค์ โอ กษัตริย์อากริปปา หวังว่าเมื่อไต่สวนแล้วข้าพเจ้าจะมีเรื่องพอที่จะถวายรายงานไปได้บ้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 27, 'เพราะข้าพเจ้าเห็นว่า ที่จะส่งแต่จําเลยไป และมิได้ส่งข้อหาไปด้วย ก็เป็นการเหลวไหลไม่ได้เรื่อง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 1, 'ฝ่ายอากริปปาจึงตรัสกับเปาโลว่า “เราอนุญาตให้เจ้าให้การแก้ข้อหาเองได้” เปาโลจึงยื่นมือออกกล่าวแก้คดีว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 2, '“ท่านกษัตริย์อากริปปาเจ้าข้า ข้าพระองค์ถือว่าเป็นโอกาสดีที่ได้แก้คดีต่อพระพักตร์พระองค์วันนี้ ในเรื่องข้อคดีทั้งปวงซึ่งพวกยิวกล่าวหาข้าพระองค์นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 3, 'โดยเฉพาะเพราะข้าพระองค์ทราบอยู่ว่าพระองค์มีความรู้ชํานาญยิ่งในบรรดาขนบธรรมเนียมและปัญหาต่างๆของพวกยิวแล้ว เหตุฉะนั้นขอพระองค์ได้โปรดทนฟังข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 4, 'พวกยิวทั้งหลายก็รู้จักความเป็นอยู่ของข้าพระองค์ตั้งแต่เป็นเด็กมาแล้ว คือตั้งแต่แรกข้าพระองค์ได้อยู่ท่ามกลางชนชาติของข้าพระองค์ในกรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 5, 'เขารู้จักข้าพระองค์แต่เดิมมา ถ้าเขาจะยอมเป็นพยานก็เป็นได้ว่าข้าพระองค์ดํารงชีวิตตามพวกที่ถือเคร่งครัดที่สุด คือเป็นพวกฟาริสี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 6, 'บัดนี้ข้าพระองค์ต้องมายืนให้พิจารณาพิพากษา ก็เนื่องด้วยเรื่องมีความหวังใจในพระสัญญาซึ่งพระเจ้าได้ตรัสแก่บรรพบุรุษของพวกข้าพระองค์นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 7, 'พวกข้าพระองค์สิบสองตระกูลได้อุตส่าห์ปรนนิบัติพระเจ้าทั้งกลางวันและกลางคืน ด้วยหวังใจว่าจะบรรลุถึงความสําเร็จตามพระสัญญานั้น ข้าแต่กษัตริย์อากริปปา เพราะความหวังใจอันนี้พวกยิวจึงฟ้องข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 8, 'เหตุไฉนท่านทั้งหลายจึงพากันถือว่า การที่พระเจ้าจะทรงให้คนตายเป็นขึ้นมาเป็นการที่เชื่อไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 9, 'ข้าพระองค์เคยได้คิดในใจของตนเองว่า สมควรจะทําหลายสิ่งซึ่งขัดขวางพระนามของพระเยซูชาวนาซาเร็ธนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 10, 'สิ่งเหล่านั้นข้าพระองค์ได้กระทําในกรุงเยรูซาเล็ม เมื่อข้าพระองค์รับอํานาจจากพวกปุโรหิตใหญ่แล้ว ข้าพระองค์ได้ขังวิสุทธิชนหลายคนไว้ในคุก และครั้นเขาถูกลงโทษถึงตาย ข้าพระองค์ก็เห็นดีด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 11, 'ข้าพระองค์ได้ทําโทษเขาบ่อยๆในธรรมศาลาทุกแห่ง และบังคับเขาให้กล่าวคําหมิ่นประมาท และเพราะข้าพระองค์โกรธเขายิ่งนัก ข้าพระองค์ได้ตามไปข่มเหงถึงเมืองในต่างประเทศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 12, 'ดังนั้นเมื่อข้าพระองค์กําลังไปยังเมืองดามัสกัส ได้ถืออํานาจและงานที่ได้รับมอบหมายจากพวกปุโรหิตใหญ่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 13, 'โอ ข้าแต่กษัตริย์ ในเวลาเที่ยงวันเมื่อกําลังเดินทางไป ข้าพระองค์ได้เห็นแสงสว่างกล้ายิ่งกว่าแสงอาทิตย์ส่องลงมาจากท้องฟ้า ล้อมรอบข้าพระองค์กับคนทั้งหลายที่ไปกับข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 14, 'ครั้นข้าพระองค์กับคนทั้งหลายล้มคะมําลงที่ดิน ข้าพระองค์ได้ยินพระสุรเสียงตรัสแก่ข้าพระองค์เป็นภาษาฮีบรูว่า ‘เซาโล เซาโลเอ๋ย เจ้าข่มเหงเราทําไม ซึ่งเจ้าถีบประตักก็ยากนัก’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 15, 'ข้าพระองค์ทูลถามว่า ‘พระองค์เจ้าข้า พระองค์ทรงเป็นผู้ใด’ พระองค์จึงตรัสว่า ‘เราคือเยซูซึ่งเจ้าข่มเหง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 16, 'แต่ว่าจงลุกขึ้นยืนเถิด ด้วยว่าเราได้ปรากฏแก่เจ้าเพื่อจะตั้งเจ้าไว้ให้เป็นผู้รับใช้และเป็นพยานถึงเหตุการณ์ซึ่งเจ้าเห็น และถึงเหตุการณ์ที่เราจะแสดงตัวเราเองแก่เจ้าในเวลาภายหน้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 17, 'เราจะช่วยเจ้าให้พ้นจากชนชาตินี้และจากคนต่างชาติที่เราจะใช้เจ้าไปหานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 18, 'เพื่อจะให้เจ้าเปิดตาของเขา เพื่อเขาจะกลับจากความมืดมาถึงความสว่าง และจากอํานาจของซาตานมาถึงพระเจ้า เพื่อเขาจะได้รับการยกโทษความผิดบาปของเขา และให้ได้รับมรดกด้วยกันกับคนทั้งหลายซึ่งถูกแยกตั้งไว้แล้วโดยความเชื่อในเรา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 19, 'โอ ข้าแต่กษัตริย์อากริปปา เมื่อเป็นเช่นนั้นแล้ว ข้าพระองค์จึงเชื่อฟังนิมิตซึ่งมาจากสวรรค์นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 20, 'แต่ข้าพระองค์ได้กล่าวสั่งสอนเขา ตั้งต้นที่เมืองดามัสกัสและในกรุงเยรูซาเล็ม ทั่วแว่นแคว้นยูเดีย และแก่ชาวต่างประเทศ ให้เขากลับใจใหม่ ให้หันมาหาพระเจ้าและกระทําการซึ่งสมกับที่กลับใจใหม่แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 21, 'เพราะเหตุนี้พวกยิวจึงจับข้าพระองค์ที่พระวิหาร และพยายามหาช่องที่จะฆ่าข้าพระองค์เสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 22, 'เป็นเพราะพระเจ้าได้ทรงโปรดช่วยข้าพระองค์ ข้าพระองค์จึงมีชีวิตอยู่จนถึงทุกวันนี้และเป็นพยานได้ต่อหน้าผู้ใหญ่ผู้น้อย ข้าพระองค์ไม่พูดเรื่องอื่นนอกจากเรื่องซึ่งบรรดาศาสดาพยากรณ์กับโมเสสได้กล่าวไว้ว่าจะมีขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 23, 'คือว่าพระคริสต์จะต้องทนทุกข์ทรมาน และพระองค์จะทรงแสดงความสว่างแก่ชนอิสราเอลและแก่คนต่างชาติ โดยที่ทรงเป็นผู้แรกซึ่งคืนพระชนม์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 24, 'ครั้นเปาโลกําลังพูดแก้คดีอย่างนั้น เฟสทัสจึงร้องเสียงดังว่า “เปาโลเอ๋ย เจ้าคลั่งไปเสียแล้ว เจ้าเรียนรู้วิชามากจึงทําให้เจ้าคลั่งไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 25, 'แต่เปาโลกล่าวว่า “ท่านเฟสทัสเจ้าข้า ข้าพระองค์ไม่คลั่งเลย แต่ว่าได้พูดคําแห่งความจริงและคําที่ปกติชนจะพูด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 26, 'ด้วยว่าท่านกษัตริย์ทรงทราบข้อความเหล่านี้ดีแล้ว ข้าพระองค์จึงกล้ากล่าวต่อพระพักตร์ของพระองค์ เพราะข้าพระองค์เชื่อแน่ว่า ไม่มีสักอย่างหนึ่งในบรรดาเหตุการณ์เหล่านั้นที่ได้พ้นพระเนตรของพระองค์ เพราะการเหล่านั้นมิได้กระทํากันในที่ลับลี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 27, 'ข้าแต่กษัตริย์อากริปปา พระองค์เชื่อพวกศาสดาพยากรณ์หรือไม่พระเจ้าข้า ข้าพระองค์ทราบว่าพระองค์เชื่อ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 28, 'อากริปปาจึงตรัสกับเปาโลว่า “เราเกือบจะเป็นคริสเตียนโดยคําชักชวนของเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 29, 'เปาโลจึงทูลว่า “จําเพาะพระพักตร์พระเจ้า ข้าพระองค์มีความปรารถนายิ่งนักที่จะให้เป็นเหมือนอย่างข้าพระองค์ มิใช่พระองค์องค์เดียว แต่คนทั้งปวงที่ฟังข้าพระองค์วันนี้ด้วย เว้นเสียแต่เครื่องจองจํานี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 30, 'และเมื่อเปาโลกล่าวสิ่งเหล่านี้แล้ว กษัตริย์กับผู้ว่าราชการเมืองและพระนางเบอร์นิส และคนทั้งปวงที่นั่งอยู่ด้วยกันจึงลุกขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 31, 'ครั้นออกไปแล้วจึงพากันพูดว่า “คนนี้มิได้ทําสิ่งใดที่สมควรจะถูกลงโทษถึงตายหรือจองจําไว้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 32, 'ฝ่ายอากริปปาจึงตรัสกับเฟสทัสว่า “ถ้าคนนี้มิได้อุทธรณ์ถึงซีซาร์แล้วจะปล่อยเขาก็ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 1, 'ครั้นตั้งใจว่าพวกเราจะต้องแล่นเรือไปยังประเทศอิตาลี เขาจึงมอบเปาโลกับนักโทษอื่นบางคนไว้กับนายร้อยคนหนึ่งชื่อยูเลียส เป็นนายทหารในกองของออกัสตัส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 2, 'เราทั้งหลายจึงลงเรือลําหนึ่งมาจากเมืองอัดรามิททิยุม ซึ่งจะออกไปยังตําบลที่อยู่ตามฝั่งแคว้นเอเชีย เรือก็ออกทะเล มีคนหนึ่งอยู่กับเราชื่ออาริสทารคัส ชาวมาซิโดเนียซึ่งมาจากเมืองเธสะโลนิกา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 3, 'วันรุ่งขึ้นเราได้แวะที่เมืองไซดอน ฝ่ายยูเลียสมีใจเมตตาปรานีแก่เปาโล ยอมให้เปาโลไปหามิตรสหายทั้งหลายเพื่อจะได้บรรเทาใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 4, 'ครั้นเรือออกจากที่นั่นแล้ว จึงแล่นไปทางด้านปลอดลมของเกาะไซปรัสเพราะทวนลม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 5, 'เมื่อแล่นข้ามทะเลที่อยู่ตรงแคว้นซีลีเซียกับแคว้นปัมฟีเลีย ก็มาถึงเมืองมิราที่อยู่ในแคว้นลีเซีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 6, 'ที่เมืองนั้นนายร้อยได้พบเรือลําหนึ่งมาจากเมืองอเล็กซานเดรียจะไปยังประเทศอิตาลี ท่านจึงให้พวกเราลงเรือลํานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 7, 'เราแล่นไปช้าๆหลายวันและได้มาถึงเมืองคนีดัสโดยยาก เมื่อแล่นทวนลมต่อไปไม่ไหว เราจึงแล่นไปทางด้านปลอดลมของเกาะครีตตรงเมืองสัลโมเน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 8, 'เมื่อเรือแล่นเลียบฝั่งเกาะนั้นอย่างยากเย็น เราจึงมายังตําบลหนึ่งชื่อว่า ท่างาม เมืองลาเซียอยู่ใกล้ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 9, 'ครั้นเสียเวลาไปมากแล้วและการที่จะเดินเรือก็มีอันตราย เพราะเทศกาลอดอาหารผ่านไปแล้ว เปาโลจึงเตือนสติเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 10, 'ว่า “ท่านทั้งหลาย ข้าพเจ้าเห็นว่าซึ่งเราจะแล่นไปคราวนี้จะมีอันตรายและเสียหายมาก มิใช่แต่ของบรรทุกกับเรือกําปั่นเท่านั้นแต่ชีวิตของเราทั้งหลายด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 11, 'แต่นายร้อยเชื่อกัปตันและเจ้าของกําปั่นมากกว่าเชื่อคําที่เปาโลกล่าวนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 12, 'และเพราะว่าท่างามนั้นไม่เหมาะพอที่จะจอดในฤดูหนาว คนส่วนมากจึงแนะนําให้ออกทะเลไปจากที่นั่น เพื่อถ้าเป็นได้จะได้ไปให้ถึงเมืองฟีนิกส์ แล้วจะจอดอยู่ที่นั่นตลอดฤดูหนาว เมืองฟีนิกส์นั้นเป็นท่าเรือแห่งเกาะครีต หันหน้าไปทางทิศตะวันตกเฉียงเหนือกับเฉียงใต้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 13, 'เมื่อลมทิศใต้พัดมาเบาๆ เขาก็คิดว่าสมความปรารถนาแล้ว จึงถอนสมอแล่นเลียบฝั่งไปตามเกาะครีต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 14, 'แต่แล่นไปไม่ช้าเรือกําปั่นก็ถูกลมพายุกล้าที่เขาเรียกว่า ยุระกิโล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 15, 'ครั้นเรือกําปั่นถูกพายุและต้านลมไม่ไหว เราจึงปล่อยไปตามลม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 16, 'เมื่อแล่นไปทางด้านปลอดลมของเกาะเล็กๆแห่งหนึ่งชื่อว่าคลาวดา เราจึงยกเรือเล็กขึ้นผูกไว้ได้แต่มีความลําบากมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 17, 'เมื่อยกเรือขึ้นแล้ว เราก็เอาเชือกผูกโอบรอบเรือกําปั่นไว้ และเพราะกลัวว่าจะเกยสันดอนทราย จึงลดใบลงแล้วก็ปล่อยให้ไปตามกระแสลม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 18, 'ครั้นรุ่งขึ้นเราก็ขนของบรรทุกทิ้งเสีย เพราะถูกพายุใหญ่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 19, 'พอถึงวันที่สามเราก็ทิ้งเครื่องใช้ในเรือกําปั่นออกเสียด้วยมือของเราเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 20, 'และเมื่อไม่เห็นดวงอาทิตย์หรือดวงดาวตั้งหลายวันแล้ว และยังถูกพายุใหญ่อยู่ ความหวังที่เราทั้งหลายจะรอดนั้นก็ล้มละลายไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 21, 'ครั้นเขาได้อดอาหารมานานแล้ว เปาโลจึงยืนอยู่ในหมู่เขากล่าวว่า “ท่านทั้งหลาย ท่านควรได้ฟังข้าพเจ้าและไม่ควรออกจากเกาะครีตเลย จะได้พ้นจากอันตรายนี้และไม่เสียสิ่งของ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 22, 'บัดนี้ข้าพเจ้าขอเตือนท่านทั้งหลายให้ทําใจดีๆไว้ ด้วยว่าในพวกท่านจะไม่มีผู้ใดเสียชีวิต จะเสียก็แต่เรือเท่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 23, 'เพราะว่า เมื่อคืนนี้เองทูตสวรรค์ของพระเจ้าผู้เป็นเจ้าของข้าพเจ้า ซึ่งข้าพเจ้าได้ปรนนิบัตินั้นได้มายืนอยู่ใกล้ข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 24, 'ทูตนั้นกล่าวว่า ‘เปาโลเอ๋ย อย่ากลัวเลย ท่านจะต้องเข้าเฝ้าซีซาร์ ส่วนคนทั้งปวงที่อยู่ในเรือกับท่านนั้น ดูเถิด พระเจ้าจะทรงโปรดให้รอดตายเพราะเห็นแก่ท่าน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 25, 'เพราะฉะนั้น ท่านทั้งหลายจงทําใจดีๆไว้ เพราะข้าพเจ้าเชื่อพระเจ้าว่า การณ์จะเป็นไปเหมือนอย่างที่พระองค์ได้ทรงกล่าวแก่ข้าพเจ้านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 26, 'แต่ว่าเราจะต้องเกยเกาะแห่งหนึ่ง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 27, 'จนถึงคืนที่สิบสี่แล้ว เราก็ยังถูกซัดไปซัดมาอยู่ในทะเลอาเดรีย ประมาณเที่ยงคืนพวกกะลาสีก็สําคัญว่ามาใกล้แผ่นดินแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 28, 'ครั้นหยั่งน้ําดูก็วัดได้ลึกสี่สิบเมตร เมื่อไปอีกหน่อยหนึ่งก็หยั่งน้ําวัดอีกได้สามสิบเมตร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 29, 'เขาก็กลัวว่าจะโดนฝั่งที่มีหิน จึงทอดสมอท้ายสี่ตัว แล้วตั้งหน้าคอยเวลารุ่งเช้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 30, 'เมื่อพวกกะลาสีหาช่องจะหนีจากกําปั่นและได้หย่อนเรือเล็กลงที่ทะเลแล้วทําทีว่าจะทอดสมอจากหัวเรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 31, 'เปาโลจึงกล่าวแก่นายร้อยและพวกทหารว่า “ถ้าคนเหล่านั้นไม่คงอยู่ในกําปั่น ท่านทั้งหลายจะรอดตายไม่ได้เลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 32, 'พวกทหารจึงตัดเชือกที่ผูกเรือเล็กให้เรือตกลงไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 33, 'เมื่อจวนรุ่งเช้าเปาโลจึงวิงวอนคนทั้งปวงให้รับประทานอาหารและกล่าวว่า “วันนี้เป็นวันที่สิบสี่ที่ท่านทั้งหลายต้องค้างอยู่ในเรือและอดอาหารมิได้รับประทานอะไรเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 34, 'ฉะนั้นข้าพเจ้าขอวิงวอนท่านทั้งหลายให้รับประทานอาหารเสียบ้าง เพื่อจะดํารงชีวิตอยู่ได้ เพราะเส้นผมของผู้หนึ่งผู้ใดในพวกท่านจะไม่เสียไปสักเส้นเดียว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 35, 'ครั้นกล่าวอย่างนั้นแล้ว ท่านจึงหยิบขนมปังขอบพระเดชพระคุณพระเจ้าต่อหน้าคนทั้งปวง เมื่อหักแล้วก็เริ่มรับประทาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 36, 'คนทั้งปวงก็มีกําลังใจขึ้นจึงรับประทานอาหารด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 37, 'เราทั้งหลายที่อยู่ในกําปั่นนั้นรวมสองร้อยเจ็ดสิบหกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 38, 'เมื่อรับประทานอาหารอิ่มแล้ว จึงขนข้าวสาลีในกําปั่นทิ้งเสียในทะเลเพื่อให้กําปั่นเบาขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 39, 'ครั้นสว่างแล้วเขาก็ไม่รู้ว่าเป็นแผ่นดินอะไร แต่เขาเห็นอ่าวแห่งหนึ่งที่มีหาด จึงตกลงกันว่า ถ้าเป็นได้จะให้เรือเข้าเกยหาดนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 40, 'เขาจึงตัดสายสมอทิ้งเสียในทะเล แล้วก็แก้เชือกที่มัดหางเสือ และชักใบหัวเรือขึ้นให้กินลมแล่นตรงเข้าไปหาฝั่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 41, 'ครั้นมาถึงตําบลหนึ่งที่ทะเลสองข้างบรรจบกัน กําปั่นก็เกยดิน หัวเรือติดแน่นออกไม่ได้ แต่ท้ายเรือนั้นก็แตกออกด้วยกําลังคลื่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 42, 'พวกทหารคิดจะฆ่านักโทษทั้งหลายเสีย กลัวว่าจะมีผู้ใดว่ายน้ําหนีไปได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 43, 'แต่นายร้อยปรารถนาจะให้เปาโลรอดตาย จึงห้ามพวกทหารมิให้ทําตามความคิดนั้น แล้วสั่งคนทั้งหลายที่ว่ายน้ําเป็นให้กระโดดน้ําว่ายไปหาฝั่งก่อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 44, 'ฝ่ายคนทั้งหลายที่เหลือนั้นก็เกาะกระดานไปบ้าง เกาะไม้กําปั่นที่หักไปบ้าง ดังนั้นเขาทั้งหลายก็ถึงฝั่งรอดตายหมดทุกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 1, 'ครั้นรอดพ้นภัยแล้ว พวกเขาจึงรู้ว่าเกาะนั้นชื่อมอลตา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 2, 'ฝ่ายชาวป่านั้นมีความกรุณาแก่พวกเราเป็นอันมาก เขาก่อไฟรับรองเราทุกคนเพราะฝนตกและหนาว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 3, 'เปาโลเก็บกิ่งไม้แห้งมัดหนึ่งมาใส่ไฟ มีงูพิษตัวหนึ่งออกมาเพราะถูกความร้อนกัดมือของเปาโลติดอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 4, 'เมื่อพวกชาวป่านั้นเห็นงูติดห้อยอยู่ที่มือของเปาโล จึงพูดกันว่า “คนนี้คงเป็นฆาตกรแน่นอน ถึงแม้ว่ารอดพ้นจากทะเลแล้ว พระผู้ทรงธรรมก็ยังไม่ยอมให้รอดตายไปได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 5, 'แต่เปาโลได้สะบัดมือให้งูตกลงไปในไฟ และหาเป็นอันตรายประการใดไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 6, 'ฝ่ายเขาทั้งหลายคอยดูอยู่ คิดว่าท่านจะบวมขึ้นหรือจะล้มลงตายทันที แต่ครั้นเขาคอยดูอยู่ช้านานมิได้เห็นท่านเป็นอะไร เขาจึงกลับถือว่าท่านเป็นพระ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 7, 'เจ้าแห่งเกาะนั้นชื่อปูบลิอัส มีไร่นาอยู่ใกล้ตําบลนั้น ท่านได้ต้อนรับเลี้ยงดูพวกเราไว้อย่างดีสามวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 8, 'ต่อมาบิดาของปูบลิอัสนั้นนอนป่วยอยู่ เป็นไข้และเป็นบิด เปาโลจึงเข้าไปหาท่านอธิษฐานแล้ววางมือบนท่านรักษาให้หาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 9, 'ครั้นทําอย่างนั้นแล้ว คนอื่นๆที่เกาะนั้นซึ่งมีโรคต่างๆก็มาหา และเขาก็หายด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 10, 'เขาทั้งหลายจึงให้เกียรติพวกเราหลายประการ เมื่อเราจะแล่นเรือไปจากที่นั่น เขาจึงนําสิ่งของที่เราต้องการมาใส่เรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 11, 'ครั้นล่วงไปสามเดือน พวกเราจึงลงในเรือกําปั่นซึ่งมาจากเมืองอเล็กซานเดรียและค้างอยู่ที่เกาะนั้นในฤดูหนาว เครื่องหมายของกําปั่นลํานั้น คือรูปแคสเตอร์และพอลลักซ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 12, 'พวกเราแวะที่เมืองไซราคิ้วส์จอดอยู่ที่นั่นสามวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 13, 'เราออกจากที่นั่นอ้อมไปยังเมืองเรยีอูม ครั้นรุ่งขึ้นลมทิศใต้ก็พัดมา วันที่สองจึงมาถึงเมืองโปทิโอลี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 14, 'เราพบพวกพี่น้องที่นั่น และเขาเชิญเราให้หยุดพักอาศัยอยู่กับเขาเจ็ดวัน แล้วเราจึงไปถึงกรุงโรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 15, 'ครั้นพวกพี่น้องในกรุงโรมได้ยินข่าวพวกเรา เขาจึงออกมาพบเราที่บ้านตลาดอัปปีอัสและที่บ้านสามร้าน เมื่อเปาโลเห็นเขาแล้ว จึงขอบพระเดชพระคุณพระเจ้าและมีกําลังใจดีขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 16, 'ครั้นพวกเรามาถึงกรุงโรม นายร้อยได้มอบพวกนักโทษให้กับผู้บัญชาการของค่ายนั้น แต่เขายอมให้เปาโลอยู่คนเดียวต่างหาก ให้ทหารคนหนึ่งคุมไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 17, 'ต่อมาครั้นล่วงไปสามวันแล้ว เปาโลจึงเชิญพวกผู้ใหญ่ในพวกยิวมาประชุมกัน เมื่อมาพร้อมหน้ากันแล้วท่านจึงกล่าวแก่เขาว่า “ท่านพี่น้องทั้งหลาย ถึงแม้ว่าข้าพเจ้ามิได้กระทําผิดสิ่งหนึ่งสิ่งใดต่อชนชาติ หรือผิดธรรมเนียมของบรรพบุรุษ ข้าพเจ้ายังต้องถูกมอบเป็นนักโทษมาจากกรุงเยรูซาเล็ม เป็นนักโทษให้อยู่ในมือของพวกโรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 18, 'ครั้นพวกนั้นได้ไต่สวนข้าพเจ้าแล้วก็ประสงค์จะปล่อยข้าพเจ้าเสีย เพราะไม่มีเหตุอะไรที่ข้าพเจ้าควรจะต้องตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 19, 'แต่ว่าเมื่อพวกยิวพูดคัดค้าน ข้าพเจ้าจึงจําต้องอุทธรณ์ถึงซีซาร์ แต่มิใช่ว่าข้าพเจ้ามีอะไรจะฟ้องชนร่วมชาติของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 20, 'เหตุฉะนั้นเพราะเหตุนี้ข้าพเจ้าจึงเชิญท่านทั้งหลายมา เพื่อจะได้เห็นหน้าและพูดกับท่าน เพราะที่ข้าพเจ้าถูกล่ามโซ่นี้ก็เนื่องด้วยความหวังของชนชาติอิสราเอล”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 21, 'เขาทั้งหลายจึงตอบท่านว่า “พวกเราหาได้รับจดหมายจากแคว้นยูเดียกล่าวถึงท่าน หรือหามีพวกพี่น้องผู้หนึ่งผู้ใดมารายงานหรือกล่าวร้ายถึงท่านไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 22, 'แต่ข้าพเจ้าทั้งหลายปรารถนาจะฟังท่านกล่าวว่าท่านคิดเห็นอย่างไร เพราะพวกข้าพเจ้าทราบว่า พวกที่ถือลัทธินี้ก็ถูกติเตียนทุกแห่ง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 23, 'เมื่อเขานัดวันพบกับท่าน คนเป็นอันมากก็พากันมาหายังที่อาศัยของท่าน ท่านจึงกล่าวแก่เขาตั้งแต่เช้าจนเย็น เป็นพยานถึงอาณาจักรของพระเจ้า และชักชวนให้เขาเชื่อถือในพระเยซู โดยใช้ข้อความจากพระราชบัญญัติของโมเสส และจากคัมภีร์ศาสดาพยากรณ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 24, 'คําที่ท่านกล่าวนั้นบางคนก็เชื่อ บางคนก็ไม่เชื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 25, 'และเมื่อเขาไม่เห็นพ้องกันจึงลาไป เมื่อเปาโลได้กล่าวข้อความแถมว่า “พระวิญญาณบริสุทธิ์ตรัสกับบรรพบุรุษของเราทั้งหลาย โดยอิสยาห์ศาสดาพยากรณ์ถูกต้องดีแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 26, 'ว่า ‘จงไปหาชนชาตินี้และกล่าวว่า พวกเจ้าจะได้ยินก็จริง แต่จะไม่เข้าใจ จะดูก็จริง แต่จะไม่สังเกต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 27, 'เพราะว่าจิตใจของชนชาตินี้ก็เฉื่อยชา หูก็ตึง และตาเขาเขาก็ปิด เกรงว่าเขาจะเห็นด้วยตาของเขา และได้ยินด้วยหูของเขา และเข้าใจด้วยจิตใจของเขา และจะหันกลับมา และเราจะรักษาเขาให้หาย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 28, 'เหตุฉะนั้นท่านทั้งหลายจงรู้ว่า ความรอดของพระเจ้าได้ไปถึงคนต่างชาติแล้ว และเขาจะฟังด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 29, 'เมื่อเปาโลได้กล่าวคําเหล่านี้เสร็จแล้ว พวกยิวก็ได้จากไป และได้เถียงกันเป็นการใหญ่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 30, 'เปาโลจึงได้อาศัยอยู่ครบสองปีในบ้านที่ท่านเช่า และได้ต้อนรับคนทั้งปวงที่มาหาท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 31, 'ทั้งประกาศอาณาจักรของพระเจ้า และสั่งสอนเรื่องพระเยซูคริสต์เจ้าโดยใจกล้า ไม่มีผู้หนึ่งผู้ใดขัดขวาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 1, 'เปาโล ผู้รับใช้ของพระเยซูคริสต์ ผู้ซึ่งพระองค์ทรงเรียกให้เป็นอัครสาวก และได้ถูกแยกตั้งไว้สําหรับข่าวประเสริฐของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 2, '(คือข่าวประเสริฐที่พระองค์ได้ทรงสัญญาไว้ล่วงหน้าโดยพวกศาสดาพยากรณ์ของพระองค์ในพระคัมภีร์อันบริสุทธิ์)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 3, 'เกี่ยวกับพระบุตรของพระองค์ คือพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเรา ผู้บังเกิดในเชื้อสายของดาวิดฝ่ายเนื้อหนัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 4, 'แต่ฝ่ายพระวิญญาณแห่งความบริสุทธิ์นั้นบ่งไว้ด้วยฤทธานุภาพ คือโดยการเป็นขึ้นมาจากความตายว่า เป็นพระบุตรของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 5, 'โดยทางพระองค์นั้นพวกข้าพเจ้าได้รับพระคุณและหน้าที่เป็นอัครสาวก เพื่อเห็นแก่พระนามของพระองค์ ให้ชนชาติต่างๆเชื่อฟังตามความเชื่อนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 6, 'รวมทั้งพวกท่านที่พระเจ้าทรงเรียกให้เป็นคนของพระเยซูคริสต์ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 7, 'เรียน บรรดาท่านที่อยู่ในกรุงโรม ผู้ซึ่งพระเจ้าทรงรักและทรงเรียกให้เป็นวิสุทธิชน ขอพระคุณและสันติสุขซึ่งมาจากพระเจ้าพระบิดาของเราทั้งหลาย และจากพระเยซูคริสต์เจ้า จงดํารงอยู่กับพวกท่านเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 8, 'ประการแรก ข้าพเจ้าขอขอบพระคุณพระเจ้าของข้าพเจ้าโดยทางพระเยซูคริสต์เหตุด้วยท่านทั้งหลาย เพราะว่าความเชื่อของพวกท่านเลื่องลือไปทั่วโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 9, 'เพราะพระเจ้าผู้ซึ่งข้าพเจ้าได้รับใช้ด้วยชีวิตจิตใจของข้าพเจ้าในข่าวประเสริฐแห่งพระบุตรของพระองค์นั้น ทรงเป็นพยานของข้าพเจ้าว่า เมื่อข้าพเจ้าอธิษฐานนั้น ข้าพเจ้าเอ่ยถึงท่านทั้งหลายเสมอไม่ว่างเว้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 10, 'ข้าพเจ้าทูลขอว่า ถ้าเป็นที่พอพระทัยพระเจ้าแล้วให้ข้าพเจ้าได้มีโอกาสไปเยี่ยมท่านทั้งหลาย โดยอย่างหนึ่งอย่างใดในที่สุดนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 11, 'เพราะข้าพเจ้าปรารถนาที่จะได้พบท่านทั้งหลาย เพื่อจะได้นําของประทานฝ่ายจิตวิญญาณมาให้แก่ท่านบ้าง เพื่อเสริมกําลังท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 12, 'คือเพื่อข้าพเจ้าและท่านทั้งหลายจะได้หนุนใจซึ่งกันและกัน โดยความเชื่อของเราทั้งสองฝ่าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 13, 'พี่น้องทั้งหลาย บัดนี้ข้าพเจ้าอยากให้ท่านทั้งหลายทราบว่า ข้าพเจ้าได้ตั้งใจไว้หลายครั้งแล้วว่าจะมาหาท่าน เพื่อข้าพเจ้าจะได้เก็บเกี่ยวผลในหมู่พวกท่านด้วย เช่นเดียวกับในหมู่ชนชาติอื่นๆ (แต่จนบัดนี้ก็ยังมีเหตุขัดข้องอยู่)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 14, 'ข้าพเจ้าเป็นหนี้ทั้งพวกกรีกและพวกชาวป่าด้วย เป็นหนี้ทั้งพวกนักปราชญ์และคนเขลาด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 15, 'ฉะนั้นข้าพเจ้าก็เต็มใจพร้อมที่จะประกาศข่าวประเสริฐแก่ท่านทั้งหลายที่อยู่ในกรุงโรมด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 16, 'ด้วยว่าข้าพเจ้าไม่มีความละอายในเรื่องข่าวประเสริฐของพระคริสต์ เพราะว่าข่าวประเสริฐนั้นเป็นฤทธิ์เดชของพระเจ้า เพื่อให้ทุกคนที่เชื่อได้รับความรอด พวกยิวก่อน และพวกกรีกด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 17, 'เพราะว่าในข่าวประเสริฐนั้นความชอบธรรมของพระเจ้าก็ได้แสดงออก โดยเริ่มต้นก็ความเชื่อ สุดท้ายก็ความเชื่อ ตามที่มีเขียนไว้แล้วว่า ‘คนชอบธรรมจะมีชีวิตดํารงอยู่โดยความเชื่อ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 18, 'เพราะว่า พระพิโรธของพระเจ้าทรงสําแดงจากสวรรค์ต่อความอธรรมและความไม่ชอบธรรมทั้งมวลของมนุษย์ ที่เอาความไม่ชอบธรรมนั้นขัดขวางความจริง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 19, 'เหตุว่าเท่าที่จะรู้จักพระเจ้าได้ก็แจ้งอยู่กับใจเขาทั้งหลาย เพราะว่าพระเจ้าได้ทรงโปรดสําแดงแก่เขาแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 20, 'ตั้งแต่เริ่มสร้างโลกมาแล้ว สภาพที่ไม่ปรากฏของพระองค์นั้น คือฤทธานุภาพอันนิรันดร์และเทวสภาพของพระเจ้า ก็ได้ปรากฏชัดในสรรพสิ่งที่พระองค์ได้ทรงสร้าง ฉะนั้นเขาทั้งหลายจึงไม่มีข้อแก้ตัวเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 21, 'เพราะถึงแม้ว่าเขาทั้งหลายได้รู้จักพระเจ้าแล้ว เขาก็มิได้ถวายพระเกียรติแด่พระองค์ให้สมกับที่ทรงเป็นพระเจ้า หรือหาได้ขอบพระคุณไม่ แต่เขากลับคิดในสิ่งที่ไม่เป็นสาระ และจิตใจโง่เขลาของเขาก็มืดมัวไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 22, 'เขาอ้างตัวว่าเป็นคนมีปัญญา เขาจึงกลายเป็นคนโง่เขลาไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 23, 'และเขาได้เอาสง่าราศีของพระเจ้าผู้เป็นอมตะ มาแลกกับรูปมนุษย์ที่ต้องตายหรือรูปนก รูปสัตว์สี่เท้า และรูปสัตว์เลื้อยคลาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 24, 'เหตุฉะนั้น พระเจ้าจึงทรงปล่อยเขาให้ประพฤติอุลามกตามราคะตัณหาในใจของเขา ให้เขากระทําสิ่งซึ่งน่าอัปยศทางกายต่อกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 25, 'เขาได้เปลี่ยนความจริงของพระเจ้าให้เป็นความเท็จ และได้นมัสการและปรนนิบัติสิ่งที่พระองค์ได้ทรงสร้างไว้แทนพระองค์ผู้ทรงสร้าง ผู้สมจะได้รับความสรรเสริญเป็นนิตย์ เอเมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 26, 'เพราะเหตุนี้พระเจ้าจึงทรงปล่อยให้เขามีราคะตัณหาอันน่าอัปยศ แม้แต่พวกผู้หญิงของเขาก็เปลี่ยนจากการสัมพันธ์ตามธรรมชาติ ให้ผิดธรรมชาติไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 27, 'ฝ่ายผู้ชายก็เลิกการสัมพันธ์กับผู้หญิงให้ถูกตามธรรมชาติเช่นกัน และเร่าร้อนด้วยไฟแห่งราคะตัณหาที่มีต่อกัน ผู้ชายกับผู้ชายด้วยกันประกอบกิจอันชั่วช้าอย่างน่าละอาย เขาจึงได้รับผลกรรมอันสมควรแก่ความผิดของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 28, 'และเพราะเขาไม่เห็นชอบที่จะรู้จักพระเจ้า พระเจ้าจึงทรงปล่อยให้เขามีใจเลวทรามและประพฤติสิ่งที่ไม่เหมาะสม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 29, 'พวกเขาเต็มไปด้วยสรรพการอธรรม การล่วงประเวณี ความชั่วร้าย ความโลภ ความมุ่งร้าย เต็มไปด้วยความอิจฉาริษยา การฆาตกรรม การวิวาท การล่อลวง การคิดร้าย พูดนินทา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 30, 'ส่อเสียด เกลียดชังพระเจ้า หยาบคาย จองหอง อวดตัว ริทําชั่วอย่างใหม่ ไม่เชื่อฟังบิดามารดา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 31, 'อปัญญา ไม่รักษาคําสัญญา ไม่มีความรักกัน ไม่ยอมคืนดีกัน ปราศจากความเมตตา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 32, 'แม้เขาจะรู้การพิพากษาของพระเจ้าที่ว่าคนทั้งปวงที่ประพฤติเช่นนั้นสมควรจะตาย เขาก็ไม่เพียงประพฤติเท่านั้น แต่ยังเห็นดีกับคนอื่นที่ประพฤติเช่นนั้นด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 1, 'เหตุฉะนั้น โอ มนุษย์เอ๋ย ไม่ว่าท่านจะเป็นใคร เมื่อท่านกล่าวโทษผู้อื่นนั้น ท่านไม่มีข้อแก้ตัวเลย เพราะเมื่อท่านกล่าวโทษผู้อื่น ท่านก็ได้กล่าวโทษตัวเองด้วย เพราะว่าท่านที่กล่าวโทษเขาก็ยังประพฤติอยู่อย่างเดียวกับเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 2, 'แต่เรารู้แน่ว่าการที่พระเจ้าทรงพิพากษาลงโทษคนที่ประพฤติเช่นนั้นก็เป็นตามความจริง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 3, 'โอ มนุษย์เอ๋ย ท่านที่กล่าวโทษคนที่ประพฤติเช่นนั้น และท่านเองยังประพฤติเช่นเดียวกับเขา ท่านคิดหรือว่าท่านจะพ้นจากการพิพากษาลงโทษของพระเจ้าได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 4, 'หรือว่าท่านประมาทพระกรุณาคุณอันอุดมและความอดกลั้นพระทัย และความอดทนของพระองค์ ท่านไม่รู้หรือว่า พระกรุณาคุณของพระเจ้านั้นมุ่งที่จะชักนําท่านให้กลับใจใหม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 5, 'แต่เพราะท่านใจแข็งกระด้างไม่ยอมกลับใจ ท่านจึงส่ําสมพระพิโรธให้แก่ตัวเองในวันแห่งพระพิโรธนั้น ซึ่งพระเจ้าจะทรงสําแดงการพิพากษาลงโทษที่เที่ยงธรรมให้ประจักษ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 6, 'พระองค์จะทรงประทานแก่ทุกคนตามควรแก่การกระทําของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 7, 'สําหรับคนที่พากเพียรทําความดี แสวงหาสง่าราศี เกียรติ และความเป็นอมตะนั้น พระองค์จะประทานชีวิตนิรันดร์ให้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 8, 'แต่พระองค์จะทรงพระพิโรธ และลงพระอาชญาแก่คนที่มักยกตนข่มท่านและไม่เชื่อฟังความจริง แต่เชื่อฟังความอธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 9, 'ความทุกข์เวทนาจะเกิดแก่จิตใจทุกคนที่ประพฤติชั่ว แก่พวกยิวก่อนและแก่พวกต่างชาติด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 10, 'แต่สง่าราศี เกียรติ และสันติสุขจะเกิดมีแก่ทุกคนที่ประพฤติดี แก่พวกยิวก่อนและแก่พวกต่างชาติด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 11, 'เพราะว่าพระเจ้าไม่ได้ทรงเห็นแก่หน้าผู้ใดเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 12, 'เพราะคนทั้งหลายที่ไม่มีพระราชบัญญัติและทําบาปจะต้องพินาศโดยไม่อ้างพระราชบัญญัติ และคนทั้งหลายที่มีพระราชบัญญัติและทําบาปก็จะต้องถูกพิพากษาตามพระราชบัญญัติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 13, '(เพราะว่าคนที่เพียงแต่ฟังพระราชบัญญัติเท่านั้น หาใช่ผู้ชอบธรรมจําเพาะพระพักตร์พระเจ้าไม่ แต่คนที่ประพฤติตามพระราชบัญญัติต่างหากเป็นผู้ชอบธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 14, 'เพราะเมื่อชนต่างชาติซึ่งไม่มีพระราชบัญญัติได้ประพฤติตามพระราชบัญญัติโดยปกติวิสัย คนเหล่านี้แม้ไม่มีพระราชบัญญัติก็เป็นพระราชบัญญัติแก่ตัวเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 15, 'คือแสดงให้เห็นการกระทําที่เป็นตามพระราชบัญญัตินั้นมีจารึกอยู่ในจิตใจของเขา และใจสํานึกผิดชอบของเขาก็เป็นพยานด้วย ความคิดขัดแย้งต่างๆของเขานั้นแหละ จะกล่าวโทษตัวหรืออาจจะแก้ตัวให้เขา)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 16, 'ในวันที่พระเจ้าจะทรงพิพากษาความลับของมนุษย์โดยพระเยซูคริสต์ ทั้งนี้ตามข่าวประเสริฐที่ข้าพเจ้าได้ประกาศนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 17, 'ดูเถิด ท่านเรียกตัวเองว่า ยิว และพึ่งพระราชบัญญัติและยกพระเจ้าขึ้นอวด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 18, 'และว่าท่านรู้จักพระทัยของพระองค์ และเห็นชอบในสิ่งที่ประเสริฐ เพราะว่าท่านได้เรียนรู้ในพระราชบัญญัติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 19, 'และท่านมั่นใจว่า ท่านเป็นผู้จูงคนตาบอด เป็นความสว่างให้แก่คนทั้งหลายที่อยู่ในความมืด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 20, 'เป็นผู้สอนคนโง่ เป็นครูของเด็ก เพราะท่านมีแบบอย่างของความรู้และความจริงในพระราชบัญญัตินั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 21, 'ฉะนั้นท่านซึ่งเป็นผู้สอนคนอื่นจะไม่สอนตัวเองหรือ เมื่อท่านเทศนาว่าไม่ควรลักทรัพย์ ตัวท่านเองลักหรือเปล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 22, 'ท่านผู้ที่สอนว่าไม่ควรล่วงประเวณี ตัวท่านเองล่วงประเวณีหรือเปล่า ท่านผู้รังเกียจรูปเคารพ ตัวท่านเองปล้นวิหารหรือเปล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 23, 'ท่านผู้โอ้อวดในพระราชบัญญัติ ตัวท่านเองยังลบหลู่พระเจ้าด้วยการละเมิดพระราชบัญญัติหรือเปล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 24, 'เพราะมีเขียนไว้แล้วว่า ‘คนต่างชาติพูดหมิ่นประมาทต่อพระนามของพระเจ้าก็เพราะท่านทั้งหลาย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 25, 'ถ้าท่านรักษาพระราชบัญญัติ การเข้าสุหนัตก็เป็นประโยชน์จริง แต่ถ้าท่านละเมิดพระราชบัญญัติ การที่ท่านเข้าสุหนัตนั้นก็เหมือนกับว่าไม่ได้เข้าสุหนัตเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 26, 'เหตุฉะนั้น ถ้าผู้ที่ไม่ได้เข้าสุหนัตยังรักษาความชอบธรรมแห่งพระราชบัญญัติแล้ว การที่เขาไม่ได้เข้าสุหนัตนั้นจะถือเหมือนกับว่าเขาได้เข้าสุหนัตแล้วไม่ใช่หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 27, 'และคนทั้งหลายที่ไม่เข้าสุหนัตซึ่งเป็นตามธรรมชาติอยู่แล้ว แต่ได้ทําตามพระราชบัญญัติ เขาจะปรับโทษท่านผู้มีประมวลพระราชบัญญัติและได้เข้าสุหนัตแล้ว แต่ยังละเมิดพระราชบัญญัตินั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 28, 'เพราะว่ายิวแท้ มิใช่คนที่เป็นยิวแต่ภายนอกเท่านั้น และการเข้าสุหนัตแท้ก็ไม่ใช่การเข้าสุหนัตซึ่งปรากฏที่เนื้อหนังเท่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 29, 'คนที่เป็นยิวแท้ คือคนที่เป็นยิวภายใน และการเข้าสุหนัตแท้นั้นเป็นเรื่องของจิตใจตามจิตวิญญาณ มิใช่ตามตัวบทบัญญัติ คนอย่างนั้นพระเจ้าสรรเสริญ มนุษย์ไม่สรรเสริญ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 1, 'ถ้าเช่นนั้น พวกยิวจะได้เปรียบคนอื่นอย่างไร และการเข้าสุหนัตนั้นจะมีประโยชน์อะไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 2, 'มีประโยชน์มากในทุกสถาน เป็นต้นว่าพวกยิวได้เป็นผู้รับมอบให้รักษาพระดํารัสของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 3, 'ถึงมีบางคนไม่เชื่อ ความไม่เชื่อของเขานั้นจะทําให้ความสัตย์ซื่อของพระเจ้าไร้ประโยชน์หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 4, 'ขอพระเจ้าอย่ายอมให้เป็นเช่นนั้นเลย ถึงแม้ทุกคนจะพูดมุสาก็ขอให้พระเจ้าทรงสัตย์จริงเถิด ตามที่มีเขียนไว้แล้วว่า ‘เพื่อพระองค์จะได้ปรากฏว่า ทรงเป็นผู้สัตย์ซื่อในพระดํารัสทั้งหลายของพระองค์ และทรงมีชัยเมื่อเขาวินิจฉัยพระองค์’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 5, 'แต่ถ้าความอธรรมของเราเป็นเหตุให้เห็นความชอบธรรมของพระเจ้า เราจะว่าอย่างไร จะว่าพระเจ้าทรงลงอาญาโดยไม่ยุติธรรมอย่างนั้นหรือ (ข้าพเจ้าพูดอย่างมนุษย์)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 6, 'พระเจ้าไม่ทรงโปรดให้เป็นเช่นนั้นเลย เพราะถ้าเป็นเช่นนั้นแล้วพระเจ้าจะทรงพิพากษาโลกได้อย่างไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 7, 'เพราะถ้าความจริงของพระเจ้าปรากฏมากยิ่งขึ้นเพราะเหตุความอสัตย์ของข้าพเจ้าเป็นที่ให้เกิดเกียรติยศแด่พระองค์แล้ว ทําไมเขาจึงยังลงโทษข้าพเจ้าว่าเป็นคนบาป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 8, 'และทําไมเราจึงไม่ทําความชั่วเพื่อความดีจะได้เกิดขึ้น (ตามที่เราได้ถูกกล่าวร้ายและตามที่บางคนยืนยันว่าเราได้กล่าวอย่างนั้น) พระอาชญาของคนเช่นนั้นก็ยุติธรรมแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 9, 'ถ้าเช่นนั้นจะเป็นอย่างไร พวกเราจะได้เปรียบกว่าพวกเขาหรือ เปล่าเลย เพราะเราได้ชี้แจงให้เห็นแล้วว่า ทั้งพวกยิวและพวกต่างชาติต่างก็อยู่ใต้อํานาจของบาปทุกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 10, 'ตามที่มีเขียนไว้แล้วว่า ‘ไม่มีผู้ใดเป็นคนชอบธรรมสักคนเดียว ไม่มีเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 11, 'ไม่มีคนที่เข้าใจ ไม่มีคนที่แสวงหาพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 12, 'เขาทุกคนหลงทางไปหมด เขาทั้งปวงเป็นคนไร้ค่าเหมือนกันทั้งสิ้น ไม่มีสักคนเดียวที่ทําดี ไม่มีเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 13, 'ลําคอของเขาคือหลุมฝังศพที่เปิดอยู่ เขาใช้ลิ้นของเขาในการล่อลวง ภายใต้ริมฝีปากของเขามีพิษของงูร้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 14, 'ปากของเขาเต็มด้วยคําแช่งด่าและคําขมขื่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 15, 'เท้าของเขาว่องไวในการทําให้นองเลือด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 16, 'ในทางเดินของเขามีความพินาศและความทุกข์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 17, 'และเขาไม่รู้จักทางแห่งสันติสุข');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 18, 'ในแววตาของเขาไม่มีความเกรงกลัวพระเจ้า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 19, 'บัดนี้ เรารู้แล้วว่าพระราชบัญญัติทุกข้อที่ได้กล่าวนั้น ก็ได้กล่าวแก่คนเหล่านั้นที่อยู่ใต้พระราชบัญญัติเพื่อปิดปากทุกคน และเพื่อให้มนุษย์ทุกคนในโลกมีความผิดจําเพาะพระพักตร์พระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 20, 'เพราะฉะนั้นจึงไม่มีเนื้อหนังคนหนึ่งคนใดเป็นผู้ชอบธรรมในสายพระเนตรของพระเจ้าได้โดยการประพฤติตามพระราชบัญญัติ เพราะว่าโดยพระราชบัญญัตินั้นเราจึงรู้จักบาปได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 21, 'แต่บัดนี้ได้ปรากฏแล้วว่าความชอบธรรมของพระเจ้านั้นปรากฏนอกเหนือพระราชบัญญัติ ซึ่งพระราชบัญญัติกับพวกศาสดาพยากรณ์เป็นพยานอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 22, 'คือความชอบธรรมของพระเจ้าซึ่งทรงประทานโดยความเชื่อในพระเยซูคริสต์สําหรับทุกคนและแก่ทุกคนที่เชื่อ เพราะว่าคนทั้งหลายไม่ต่างกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 23, 'เหตุว่าทุกคนทําบาป และเสื่อมจากสง่าราศีของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 24, 'แต่พระเจ้าทรงพระกรุณาให้เราเป็นผู้ชอบธรรม โดยไม่คิดมูลค่า โดยที่พระเยซูคริสต์ทรงไถ่เราให้พ้นบาปแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 25, 'พระเจ้าได้ทรงตั้งพระเยซูไว้ให้เป็นที่ลบล้างพระอาชญา โดยความเชื่อในพระโลหิตของพระองค์ เพื่อสําแดงให้เห็นความชอบธรรมของพระองค์ในการที่พระเจ้าได้ทรงอดกลั้นพระทัย และทรงยกบาปที่ได้ทําไปแล้วนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 26, 'และเพื่อจะสําแดงความชอบธรรมของพระองค์ในปัจจุบันนี้ว่าพระองค์ทรงเป็นผู้ชอบธรรม และทรงโปรดให้ผู้ที่เชื่อในพระเยซูเป็นผู้ชอบธรรมด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 27, 'เมื่อเป็นเช่นนั้นแล้วเราจะเอาอะไรมาอวด ก็หมดหนทาง จะอ้างหลักอะไรว่าหมดหนทาง อ้างหลักการประพฤติหรือ ไม่ใช่ แต่ต้องอ้างหลักของความเชื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 28, 'เหตุฉะนั้นเราทั้งหลายสรุปได้ว่า คนหนึ่งคนใดจะเป็นคนชอบธรรมได้ก็โดยอาศัยความเชื่อนอกเหนือการประพฤติตามพระราชบัญญัติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 29, 'หรือว่าพระเจ้านั้นทรงเป็นพระเจ้าของยิวพวกเดียวเท่านั้นหรือ พระองค์ไม่ทรงเป็นพระเจ้าของชนต่างชาติด้วยหรือ ถูกแล้วพระองค์ทรงเป็นพระเจ้าของชนต่างชาติด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 30, 'เพราะว่าพระเจ้าเป็นพระเจ้าองค์เดียว และพระองค์จะทรงโปรดให้คนที่เข้าสุหนัตเป็นคนชอบธรรมโดยความเชื่อ และจะทรงโปรดให้คนที่ไม่ได้เข้าสุหนัตเป็นคนชอบธรรมก็เพราะความเชื่อดุจกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 31, 'ถ้าเช่นนั้นเราลบล้างพระราชบัญญัติด้วยความเชื่อหรือ ขอพระเจ้าอย่ายอมให้เป็นเช่นนั้นเลย เรากลับสนับสนุนพระราชบัญญัติเสียอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 1, 'ถ้าเช่นนั้น เราจะว่าอับราฮัมบรรพบุรุษของเราได้ประโยชน์อะไรตามเนื้อหนังเล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 2, 'เพราะถ้าอับราฮัมเป็นผู้ชอบธรรมโดยการกระทํา ท่านก็มีทางที่จะอวดได้ แต่มิใช่จําเพาะพระพักตร์พระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 3, 'ด้วยว่าพระคัมภีร์ว่าอย่างไร ก็ว่า ‘อับราฮัมได้เชื่อพระเจ้า และพระองค์ทรงนับว่าเป็นความชอบธรรมแก่ท่าน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 4, 'ดังนั้นคนที่อาศัยการกระทําก็ไม่ถือว่าบําเหน็จที่ได้นั้นเป็นเพราะพระคุณ แต่ถือว่า บําเหน็จนั้นเป็นค่าแรงของงานที่ได้ทํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 5, 'ส่วนคนที่มิได้อาศัยการกระทํา แต่ได้เชื่อในพระองค์ ผู้ทรงโปรดให้คนอธรรมเป็นคนชอบธรรมได้ ความเชื่อของคนนั้นต้องนับว่าเป็นความชอบธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 6, 'ดังที่ดาวิดได้กล่าวถึงความสุขของคนที่พระเจ้าได้ทรงโปรดให้เป็นคนชอบธรรม โดยมิได้อาศัยการกระทํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 7, 'ว่า ‘คนทั้งหลายซึ่งพระเจ้าทรงโปรดยกความชั่วช้าของเขาแล้ว และพระเจ้าทรงกลบเกลื่อนบาปของเขาแล้วก็เป็นสุข');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 8, 'บุคคลที่องค์พระผู้เป็นเจ้ามิได้ทรงถือโทษบาปของเขาก็เป็นสุข’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 9, 'ถ้าเช่นนั้นความสุขมีแก่คนที่เข้าสุหนัตพวกเดียวหรือ หรือว่ามีแก่พวกที่มิได้เข้าสุหนัตด้วย เพราะเรากล่าวว่า “เพราะความเชื่อนั้นเองทรงถือว่าอับราฮัมเป็นคนชอบธรรม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 10, 'แต่พระเจ้าทรงถืออย่างไร เมื่อท่านเข้าสุหนัตแล้วหรือ หรือเมื่อยังไม่ได้เข้าสุหนัต มิใช่เมื่อท่านเข้าสุหนัตแล้วแต่เมื่อท่านยังไม่ได้เข้าสุหนัต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 11, 'และท่านได้เข้าสุหนัตเป็นเครื่องหมายสําคัญ เป็นตราแห่งความชอบธรรม ซึ่งเกิดโดยความเชื่อที่ท่านได้มีอยู่เมื่อท่านยังไม่ได้เข้าสุหนัต เพื่อท่านจะได้เป็นบิดาของคนทั้งปวงที่เชื่อ ทั้งที่เมื่อเขายังไม่ได้เข้าสุหนัต เพื่อจะถือว่าเป็นผู้ชอบธรรมด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 12, 'และเพื่อท่านจะเป็นบิดาของคนเหล่านั้นที่เข้าสุหนัต ที่มิได้เพียงแต่เข้าสุหนัตเท่านั้น แต่มีความเชื่อตามแบบของอับราฮัมบิดาของเราทั้งหลาย ซึ่งท่านมีอยู่เมื่อท่านยังไม่ได้เข้าสุหนัต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 13, 'เพราะว่าพระสัญญาที่ประทานแก่อับราฮัมและผู้สืบเชื้อสายของท่าน ที่ว่าจะได้ทั้งพิภพเป็นมรดกนั้นไม่ได้มีมาโดยพระราชบัญญัติ แต่มีมาโดยความชอบธรรมที่เกิดจากความเชื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 14, 'เพราะถ้าเขาเหล่านั้นที่ถือตามพระราชบัญญัติจะเป็นผู้รับมรดก ความเชื่อก็ไม่มีประโยชน์อะไร และพระสัญญาก็เป็นอันไร้ประโยชน์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 15, 'เพราะพระราชบัญญัตินั้นกระทําให้ทรงพระพิโรธ แต่ที่ใดไม่มีพระราชบัญญัติ ที่นั่นก็ไม่มีการละเมิดพระราชบัญญัติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 16, 'ด้วยเหตุนี้เองการที่ได้รับมรดกนั้นจึงขึ้นอยู่กับความเชื่อ เพื่อจะได้เป็นตามพระคุณ เพื่อพระสัญญานั้นจะเป็นที่แน่ใจแก่ผู้สืบเชื้อสายของท่านทุกคน มิใช่แก่ผู้สืบเชื้อสายที่ถือพระราชบัญญัติพวกเดียว แต่แก่คนที่มีความเชื่อเช่นเดียวกับอับราฮัมผู้เป็นบิดาของพวกเราทุกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 17, '(ตามที่มีเขียนไว้แล้วว่า ‘เราได้ให้เจ้าเป็นบิดาของประชาชาติมากมาย’) ต่อพระพักตร์พระองค์ที่ท่านเชื่อ คือพระเจ้าผู้ทรงให้คนที่ตายแล้วฟื้นชีวิตขึ้นมา และทรงเรียกสิ่งของที่ยังมิได้เป็นให้เป็นขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 18, 'ฝ่ายอับราฮัมนั้นเมื่อไม่มีหวังซึ่งเป็นที่น่าไว้ใจก็ยังได้เชื่อไว้ใจ มีความหวังว่าจะได้เป็นบิดาของประชาชาติมากมาย ตามคําที่ได้ตรัสไว้แล้วว่า ‘เชื้อสายของเจ้าจะเป็นเช่นนั้น’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 19, 'และความเชื่อของท่านมิได้หย่อนถอยลง ถึงแม้อายุของท่านได้ประมาณร้อยปีแล้ว ท่านก็มิได้คิดว่าร่างกายของท่านเปรียบเหมือนตายแล้ว และมิได้คิดว่าครรภ์นางซาราห์เป็นหมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 20, 'ท่านมิได้หวั่นไหวแคลงใจในพระสัญญาของพระเจ้า แต่ท่านมีความเชื่อมั่นคงยิ่งขึ้น จึงถวายเกียรติยศแด่พระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 21, 'ท่านเชื่อมั่นว่า พระองค์ทรงฤทธิ์สามารถกระทําให้สําเร็จได้ตามที่พระองค์ตรัสสัญญาไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 22, 'ด้วยเหตุนี้เอง พระเจ้าทรงถือว่าความเชื่อของท่านเป็นความชอบธรรมแก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 23, 'แต่คําว่า ‘ทรงนับว่าเป็นความชอบธรรมแก่ท่าน’ นั้น มิได้เขียนไว้สําหรับท่านแต่ผู้เดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 24, 'แต่สําหรับพวกเราด้วย จะทรงถือว่าเราเป็นคนชอบธรรม คือเราที่เชื่อวางใจในพระองค์ผู้ทรงให้พระเยซูองค์พระผู้เป็นเจ้าของเราฟื้นขึ้นจากความตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 25, 'คือพระองค์ผู้ทรงถูกมอบไว้เพราะการละเมิดของเรา และได้ทรงฟื้นขึ้นจากความตายเพื่อให้เราเป็นคนชอบธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 1, 'เหตุฉะนั้นเมื่อเราเป็นคนชอบธรรมเพราะความเชื่อแล้ว เราจึงมีสันติสุขกับพระเจ้าทางพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 2, 'โดยทางพระองค์ เราจึงได้เข้าในร่มพระคุณที่เรายืนอยู่โดยความเชื่อ และเราชื่นชมยินดีในความหวังใจว่าจะได้มีส่วนในสง่าราศีของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 3, 'ยิ่งกว่านั้น เราชื่นชมยินดีในความทุกข์ยากด้วย เพราะเรารู้ว่าความทุกข์ยากนั้นทําให้เกิดความอดทน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 4, 'และความอดทนทําให้เกิดมีประสบการณ์ และประสบการณ์ทําให้เกิดมีความหวังใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 5, 'และความหวังใจมิได้ทําให้เกิดความละอาย เพราะเหตุว่าความรักของพระเจ้าได้หลั่งไหลเข้าสู่จิตใจของเรา โดยทางพระวิญญาณบริสุทธิ์ ซึ่งพระองค์ได้ประทานให้แก่เราแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 6, 'ขณะเมื่อเรายังขาดกําลัง พระคริสต์ก็ได้ทรงสิ้นพระชนม์เพื่อช่วยคนอธรรมในเวลาที่เหมาะสม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 7, 'ไม่ใคร่จะมีใครตายเพื่อคนชอบธรรม แต่บางทีจะมีคนอาจตายเพื่อคนดีก็ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 8, 'แต่พระเจ้าทรงสําแดงความรักของพระองค์แก่เราทั้งหลาย คือขณะที่เรายังเป็นคนบาปอยู่นั้น พระคริสต์ได้ทรงสิ้นพระชนม์เพื่อเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 9, 'บัดนี้เราจึงเป็นคนชอบธรรมแล้วโดยพระโลหิตของพระองค์ ยิ่งกว่านั้น เราจะพ้นจากพระพิโรธโดยพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 10, 'เพราะว่าถ้าขณะที่เรายังเป็นศัตรู เราได้กลับคืนดีกับพระเจ้าโดยที่พระบุตรของพระองค์สิ้นพระชนม์ ยิ่งกว่านั้นอีกเมื่อเรากลับคืนดีแล้ว เราก็จะรอดโดยพระชนม์ชีพของพระองค์แน่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 11, 'มิใช่เพียงเท่านั้น แต่เราทั้งหลายยังชื่นชมยินดีในพระเจ้าโดยทางพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเรา เพราะโดยพระองค์นั้นเดี๋ยวนี้เราจึงได้กลับคืนดีกับพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 12, 'เหตุฉะนั้นเช่นเดียวกับที่บาปได้เข้ามาในโลกเพราะคนๆเดียว และความตายก็เกิดมาเพราะบาปนั้น และความตายก็ได้แผ่ไปถึงมวลมนุษย์ทุกคน เพราะมนุษย์ทุกคนทําบาป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 13, '(บาปได้มีอยู่ในโลกแล้วก่อนมีพระราชบัญญัติ แต่ที่ใดไม่มีพระราชบัญญัติก็ไม่ถือว่ามีบาป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 14, 'อย่างไรก็ตามความตายก็ได้ครอบงําตลอดมาตั้งแต่อาดัมจนถึงโมเสส แม้คนที่มิได้ทําบาปอย่างเดียวกับการละเมิดของอาดัม ผู้ซึ่งเป็นแบบของผู้ที่จะเสด็จมาภายหลัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 15, 'แต่ของประทานแห่งพระคุณนั้นหาเป็นเช่นความละเมิดนั้นไม่ เพราะว่าถ้าคนเป็นอันมากต้องตายเพราะการละเมิดของคนๆเดียว มากยิ่งกว่านั้น พระคุณของพระเจ้าและของประทานโดยพระคุณของพระองค์ผู้เดียวนั้น คือพระเยซูคริสต์ ก็มีบริบูรณ์แก่คนเป็นอันมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 16, 'และของประทานนั้นก็ไม่เหมือนกับผลซึ่งเกิดจากบาปของคนนั้นคนเดียว เพราะว่าการพิพากษาที่เกิดขึ้นเนื่องจากการละเมิดเพียงครั้งเดียวนั้น ได้นําไปสู่การลงโทษ แต่ของประทานภายหลังการละเมิดหลายครั้งนั้นนําไปสู่ความชอบธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 17, 'เพราะว่าถ้าโดยการละเมิดของคนนั้นคนเดียว เป็นเหตุให้ความตายครอบงําอยู่โดยคนนั้นคนเดียว มากยิ่งกว่านั้นคนทั้งหลายที่รับพระคุณอันไพบูลย์และรับของประทานแห่งความชอบธรรม ก็จะดํารงชีวิตและครอบครองโดยพระองค์ผู้เดียว คือพระเยซูคริสต์)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 18, 'ฉะนั้นการพิพากษาลงโทษได้มาถึงคนทั้งปวงเพราะการละเมิดของคนๆเดียวฉันใด ความชอบธรรมของพระองค์ผู้เดียวก็นําของประทานแห่งพระคุณมาถึงทุกคนฉันนั้น คือความชอบธรรมแห่งชีวิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 19, 'เพราะว่าคนเป็นอันมากเป็นคนบาปเพราะคนๆเดียวที่มิได้เชื่อฟังฉันใด คนเป็นอันมากก็เป็นคนชอบธรรมเพราะพระองค์ผู้เดียวที่ได้ทรงเชื่อฟังฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 20, 'เมื่อมีพระราชบัญญัติก็ทําให้มีการละเมิดพระราชบัญญัติปรากฏมากขึ้น แต่ที่ใดมีบาปปรากฏมากขึ้น ที่นั่นพระคุณก็จะไพบูลย์ยิ่งขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 21, 'เพื่อว่าบาปได้ครอบงําทําให้ถึงซึ่งความตายฉันใด พระคุณก็ครอบงําด้วยความชอบธรรมให้ถึงซึ่งชีวิตนิรันดร์ โดยทางพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเราฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 1, 'ถ้าเช่นนั้นแล้วเราจะว่าอย่างไร ควรเราจะอยู่ในบาปต่อไปเพื่อให้พระคุณมีมากยิ่งขึ้นหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 2, 'ขอพระเจ้าอย่ายอมให้เป็นเช่นนั้นเลย พวกเราที่ตายต่อบาปแล้ว จะมีชีวิตในบาปต่อไปอย่างไรได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 3, 'ท่านไม่รู้หรือว่า เราทั้งหลายที่ได้รับบัพติศมาเข้าในพระเยซูคริสต์ ก็ได้รับบัพติศมานั้นเข้าในความตายของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 4, 'เหตุฉะนั้นเราจึงถูกฝังไว้กับพระองค์แล้วโดยการรับบัพติศมาเข้าส่วนในความตายนั้น เหมือนกับที่พระคริสต์ได้ทรงถูกชุบให้เป็นขึ้นมาจากความตาย โดยเดชพระรัศมีของพระบิดาอย่างไร เราก็จะได้ดําเนินตามชีวิตใหม่ด้วยอย่างนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 5, 'เพราะว่าถ้าเราเข้าสนิทกับพระองค์แล้วในการตายอย่างพระองค์ เราก็จะเป็นขึ้นมาอย่างพระองค์ได้ทรงเป็นขึ้นมาจากความตายด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 6, 'เราทั้งหลายรู้แล้วว่า มนุษย์เก่าของเรานั้นได้ถูกตรึงไว้กับพระองค์แล้ว เพื่อตัวที่บาปนั้นจะถูกทําลายให้สิ้นไป เพื่อเราจะไม่เป็นทาสของบาปอีกต่อไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 7, 'เพราะว่าผู้ที่ตายแล้วก็พ้นจากบาป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 8, 'แต่ถ้าเราตายแล้วกับพระคริสต์ เราเชื่อว่าเราจะมีชีวิตอยู่กับพระองค์ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 9, 'เราทั้งหลายรู้อยู่ว่า พระคริสต์ที่ทรงถูกชุบให้เป็นขึ้นมาจากตายแล้วนั้นจะหาตายอีกไม่ ความตายหาครอบงําพระองค์ต่อไปไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 10, 'ด้วยว่าซึ่งพระองค์ได้ทรงตายนั้น พระองค์ได้ทรงตายต่อบาปหนเดียว แต่ซึ่งพระองค์ทรงมีชีวิตอยู่นั้น พระองค์ทรงมีชีวิตเพื่อพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 11, 'เหมือนกันเช่นนั้นแหละ ท่านทั้งหลายจงถือว่า ท่านได้ตายต่อบาปและมีชีวิตอยู่เพื่อพระเจ้า ในพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 12, 'เหตุฉะนั้นอย่าให้บาปครอบงํากายที่ต้องตายของท่าน ซึ่งทําให้ต้องเชื่อฟังตัณหาของกายนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 13, 'อย่ายกอวัยวะของท่านให้แก่บาป ให้เป็นเครื่องใช้ในการอธรรม แต่จงถวายตัวของท่านแด่พระเจ้า เหมือนหนึ่งคนที่เป็นขึ้นมาจากความตายแล้ว และจงให้อวัยวะของท่านเป็นเครื่องใช้ในการชอบธรรมถวายแด่พระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 14, 'เพราะว่าบาปจะมีอํานาจเหนือท่านทั้งหลายต่อไปก็หามิได้ เพราะว่าท่านทั้งหลายมิได้อยู่ใต้พระราชบัญญัติ แต่อยู่ใต้พระคุณ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 15, 'ถ้าเช่นนั้นจะเป็นอย่างไรต่อไป เราจะทําบาปเพราะมิได้อยู่ใต้พระราชบัญญัติแต่อยู่ใต้พระคุณกระนั้นหรือ ขอพระเจ้าอย่ายอมให้เป็นเช่นนั้นเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 16, 'ท่านทั้งหลายไม่รู้หรือว่า ท่านจะยอมตัวรับใช้เชื่อฟังคําของผู้ใด ท่านก็เป็นทาสของผู้ที่ท่านเชื่อฟังนั้น คือเป็นทาสของบาปซึ่งนําไปสู่ความตาย หรือเป็นทาสของการเชื่อฟังซึ่งนําไปสู่ความชอบธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 17, 'แต่จงขอบพระคุณพระเจ้าเพราะว่าเมื่อก่อนนั้นท่านเป็นทาสของบาป แต่บัดนี้ท่านมีใจเชื่อฟังหลักคําสอนนั้นซึ่งทรงมอบไว้แก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 18, 'เมื่อท่านพ้นจากบาปแล้ว ท่านก็ได้กลายเป็นทาสของความชอบธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 19, 'ข้าพเจ้ายกเอาตัวอย่างมนุษย์มาพูด เพราะเหตุเนื้อหนังของท่านอ่อนกําลัง เพราะท่านเคยให้อวัยวะของท่านเป็นทาสของการโสโครกและของความชั่วช้าซ้อนชั่วช้าฉันใด บัดนี้ท่านจงให้อวัยวะของท่านเป็นทาสของความชอบธรรม เพื่อให้ถึงความบริสุทธิ์ฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 20, 'เพราะเมื่อท่านทั้งหลายเป็นทาสของบาป ความชอบธรรมก็ไม่ได้ครอบครองท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 21, 'ขณะนั้นท่านได้ผลประโยชน์อะไรในการเหล่านั้น ซึ่งบัดนี้ท่านทั้งหลายก็ละอาย ด้วยว่าที่สุดท้ายของการเหล่านั้นก็คือความตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 22, 'แต่เดี๋ยวนี้ท่านทั้งหลายพ้นจากการเป็นทาสของบาป และกลับมาเป็นผู้รับใช้ของพระเจ้าแล้ว ผลที่ท่านได้รับก็คือความบริสุทธิ์ และผลสุดท้ายคือชีวิตนิรันดร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 23, 'เพราะว่าค่าจ้างของความบาปคือความตาย แต่ของประทานของพระเจ้าคือชีวิตนิรันดร์ในพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 1, 'พี่น้องทั้งหลาย ท่านไม่รู้หรือ (ข้าพเจ้าพูดกับคนที่รู้พระราชบัญญัติแล้ว) ว่าพระราชบัญญัตินั้นมีอํานาจเหนือมนุษย์เฉพาะในขณะที่ยังมีชีวิตอยู่เท่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 2, 'เพราะว่า ผู้หญิงที่สามียังมีชีวิตอยู่นั้นต้องอยู่ใต้พระราชบัญญัติว่าด้วยประเพณีสามีภรรยา แต่ถ้าสามีตาย ผู้หญิงนั้นก็พ้นจากพระราชบัญญัติว่าด้วยประเพณีสามีภรรยา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 3, 'ฉะนั้น ถ้าผู้หญิงนั้นไปแต่งงานกับชายอื่นในเมื่อสามียังมีชีวิตอยู่ นางก็ได้ชื่อว่าเป็นหญิงล่วงประเวณี แต่ถ้าสามีตายแล้ว นางก็พ้นจากพระราชบัญญัตินั้น แม้นางไปแต่งงานกับชายอื่นก็หาผิดประเวณีไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 4, 'เช่นนั้นแหละ พี่น้องทั้งหลายของข้าพเจ้า ท่านทั้งหลายได้ตายจากพระราชบัญญัติทางพระกายของพระคริสต์ด้วย เพื่อท่านจะตกเป็นของผู้อื่น คือของพระองค์ผู้ทรงฟื้นขึ้นมาจากความตายแล้ว เพื่อเราทั้งหลายจะได้เกิดผลถวายแด่พระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 5, 'เพราะว่าเมื่อเราเคยมีชีวิตตามเนื้อหนัง ตัณหาชั่วซึ่งเป็นมาโดยพระราชบัญญัติได้ทําให้อวัยวะของเราเกิดผลนําไปสู่ความตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 6, 'แต่บัดนี้เราได้พ้นจากพระราชบัญญัติ คือได้ตายจากพระราชบัญญัติที่ได้ผูกมัดเราไว้ เพื่อเราจะได้ไม่ประพฤติตามตัวอักษรในประมวลพระราชบัญญัติเก่า แต่จะดําเนินชีวิตใหม่ตามลักษณะจิตวิญญาณ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 7, 'ถ้าเช่นนั้นเราจะว่าอย่างไร ว่าพระราชบัญญัติคือบาปหรือ ขอพระเจ้าอย่ายอมให้เป็นเช่นนั้นเลย แต่ว่าถ้ามิใช่เพราะพระราชบัญญัติแล้ว ข้าพเจ้าก็จะไม่รู้จักบาป เพราะว่าถ้าพระราชบัญญัติมิได้ห้ามว่า “อย่าโลภ” ข้าพเจ้าก็จะไม่รู้ว่าอะไรคือความโลภ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 8, 'แต่ว่าบาปได้ถือเอาพระบัญญัตินั้นเป็นช่อง ทําให้ตัณหาชั่วทุกอย่างเกิดขึ้นในตัวข้าพเจ้า เพราะว่าถ้าไม่มีพระราชบัญญัติ บาปก็ตายเสียแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 9, 'เพราะครั้งหนึ่งข้าพเจ้าดํารงชีวิตอยู่โดยปราศจากพระราชบัญญัติ แต่เมื่อมีพระบัญญัติบาปก็กลับมีขึ้นอีกและข้าพเจ้าก็ตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 10, 'พระบัญญัตินั้นซึ่งมีขึ้นเพื่อให้มีชีวิต ข้าพเจ้าเห็นว่ากลับเป็นเหตุที่ทําให้ถึงความตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 11, 'เพราะว่าบาปได้ถือเอาพระบัญญัตินั้นเป็นช่องทางล่อลวงข้าพเจ้า และประหารข้าพเจ้าให้ตายด้วยพระบัญญัตินั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 12, 'เหตุฉะนั้นพระราชบัญญัติจึงเป็นสิ่งบริสุทธิ์ และพระบัญญัติก็บริสุทธิ์ ยุติธรรม และดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 13, 'ถ้าเช่นนั้น สิ่งที่ดีกลับทําให้ข้าพเจ้าต้องตายหรือ ขอพระเจ้าอย่ายอมให้เป็นเช่นนั้นเลย บาปต่างหาก คือบาปซึ่งอาศัยสิ่งที่ดีนั้นทําให้ข้าพเจ้าต้องตาย เพื่อจะให้ปรากฏว่าบาปนั้นเป็นบาปจริงและโดยอาศัยพระบัญญัตินั้น บาปก็ปรากฏว่าชั่วร้ายยิ่งนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 14, 'เพราะเรารู้ว่าพระราชบัญญัตินั้นเป็นโดยฝ่ายจิตวิญญาณ แต่ว่าข้าพเจ้าเป็นแต่เนื้อหนังถูกขายไว้ให้อยู่ใต้บาป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 15, 'ข้าพเจ้าไม่เข้าใจการกระทําของข้าพเจ้าเอง เพราะว่าข้าพเจ้าไม่ทําสิ่งที่ข้าพเจ้าปรารถนาที่จะทํา แต่กลับทําสิ่งที่ข้าพเจ้าเกลียดชังนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 16, 'เหตุฉะนั้นถ้าข้าพเจ้าทําสิ่งที่ข้าพเจ้าไม่ปรารถนาที่จะทํา ข้าพเจ้าก็ยอมรับว่าพระราชบัญญัตินั้นดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 17, 'ฉะนั้นข้าพเจ้าจึงมิใช่ผู้กระทํา แต่ว่าบาปซึ่งอยู่ในตัวข้าพเจ้านั่นเองเป็นผู้ทํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 18, 'ด้วยว่าข้าพเจ้ารู้ว่าในตัวข้าพเจ้า (คือในเนื้อหนังของข้าพเจ้า) ไม่มีความดีประการใดอยู่เลย เพราะว่าเจตนาดีข้าพเจ้าก็มีอยู่ แต่ซึ่งจะกระทําการดีนั้นข้าพเจ้าหาได้กระทําไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 19, 'ด้วยว่าการดีนั้นซึ่งข้าพเจ้าปรารถนาทํา ข้าพเจ้าไม่ได้กระทํา แต่การชั่วซึ่งข้าพเจ้ามิได้ปรารถนาทํา ข้าพเจ้ายังทําอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 20, 'ถ้าแม้ข้าพเจ้ายังทําสิ่งซึ่งข้าพเจ้าไม่ปรารถนาจะทํา ก็ไม่ใช่ตัวข้าพเจ้าเป็นผู้กระทํา แต่บาปซึ่งอยู่ในตัวข้าพเจ้านั่นเองเป็นผู้กระทํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 21, 'ดังนั้นข้าพเจ้าจึงเห็นว่าเป็นกฎอย่างหนึ่ง คือเมื่อใดข้าพเจ้าตั้งใจจะกระทําความดี ความชั่วก็ยังติดอยู่ในตัวข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 22, 'เพราะว่าส่วนลึกในใจของข้าพเจ้านั้น ข้าพเจ้าชื่นชมในพระราชบัญญัติของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 23, 'แต่ข้าพเจ้าเห็นมีกฎอีกอย่างหนึ่งอยู่ในอวัยวะของข้าพเจ้า ซึ่งต่อสู้กับกฎแห่งจิตใจของข้าพเจ้า และชักนําให้ข้าพเจ้าอยู่ใต้บังคับกฎแห่งบาปซึ่งอยู่ในอวัยวะของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 24, 'โอ ข้าพเจ้าเป็นคนเข็ญใจจริง ใครจะช่วยข้าพเจ้าให้พ้นจากร่างกายแห่งความตายนี้ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 25, 'ข้าพเจ้าขอบพระคุณพระเจ้า โดยทางพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเรา ฉะนั้นทางด้านจิตใจข้าพเจ้ารับใช้พระราชบัญญัติของพระเจ้า แต่ด้านฝ่ายเนื้อหนังข้าพเจ้ารับใช้กฎแห่งบาป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 1, 'เหตุฉะนั้นบัดนี้การปรับโทษจึงไม่มีแก่คนทั้งหลายที่อยู่ในพระเยซูคริสต์ ผู้ไม่ดําเนินตามฝ่ายเนื้อหนัง แต่ตามฝ่ายพระวิญญาณ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 2, 'เพราะว่ากฎของพระวิญญาณแห่งชีวิตในพระเยซูคริสต์ ได้ทําให้ข้าพเจ้าพ้นจากกฎแห่งบาปและความตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 3, 'เพราะสิ่งซึ่งพระราชบัญญัติทําไม่ได้เพราะเนื้อหนังทําให้อ่อนกําลังไปนั้น พระเจ้าทรงใช้พระบุตรของพระองค์มาในสภาพเสมือนเนื้อหนังที่บาปและเพื่อไถ่บาป พระองค์จึงได้ทรงปรับโทษบาปที่อยู่ในเนื้อหนัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 4, 'เพื่อความชอบธรรมของพระราชบัญญัติจะได้สําเร็จในพวกเรา ผู้ไม่ดําเนินตามฝ่ายเนื้อหนัง แต่ตามฝ่ายพระวิญญาณ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 5, 'เพราะว่า คนทั้งหลายที่อยู่ฝ่ายเนื้อหนังก็ปักใจในสิ่งของต่างๆซึ่งเป็นของเนื้อหนัง แต่คนทั้งหลายที่อยู่ฝ่ายพระวิญญาณก็ปักใจในสิ่งของต่างๆซึ่งเป็นของพระวิญญาณ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 6, 'ด้วยว่าซึ่งปักใจอยู่กับเนื้อหนังก็คือความตาย และซึ่งปักใจอยู่กับพระวิญญาณก็คือชีวิตและสันติสุข');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 7, 'เหตุว่าใจซึ่งปักอยู่กับเนื้อหนังนั้นก็เป็นศัตรูต่อพระเจ้า เพราะหาได้อยู่ใต้บังคับพระราชบัญญัติของพระเจ้าไม่ และที่จริงจะอยู่ใต้บังคับพระราชบัญญัตินั้นไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 8, 'เพราะฉะนั้นคนทั้งหลายที่อยู่ฝ่ายเนื้อหนังจะเป็นที่ชอบพระทัยพระเจ้าก็หามิได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 9, 'ถ้าพระวิญญาณของพระเจ้าทรงสถิตอยู่ในท่านทั้งหลายจริงๆแล้ว ท่านก็มิได้อยู่ฝ่ายเนื้อหนัง แต่อยู่ฝ่ายพระวิญญาณ แต่ถ้าผู้ใดไม่มีพระวิญญาณของพระคริสต์ ผู้นั้นก็ไม่เป็นของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 10, 'และถ้าพระคริสต์อยู่ในท่านทั้งหลายแล้ว ร่างกายก็ตายไปเพราะบาป แต่จิตวิญญาณก็มีชีวิตเพราะความชอบธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 11, 'แต่ถ้าพระวิญญาณของพระองค์ ผู้ทรงชุบให้พระเยซูเป็นขึ้นมาจากความตายทรงสถิตอยู่ในท่านทั้งหลาย พระองค์ผู้ทรงชุบให้พระคริสต์เป็นขึ้นมาจากความตายแล้วนั้น จะทรงกระทําให้กายซึ่งต้องตายของท่าน เป็นขึ้นมาใหม่ด้วย โดยพระวิญญาณของพระองค์ซึ่งทรงสถิตอยู่ในท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 12, 'ท่านพี่น้องทั้งหลาย เหตุฉะนั้นเราทั้งหลายเป็นหนี้ แต่มิใช่เป็นหนี้ฝ่ายเนื้อหนังที่จะดําเนินชีวิตตามเนื้อหนัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 13, 'เพราะว่าถ้าท่านทั้งหลายดําเนินชีวิตตามฝ่ายเนื้อหนังแล้ว ท่านจะต้องตาย แต่ถ้าโดยฝ่ายพระวิญญาณท่านได้ทําลายการของฝ่ายกายเสีย ท่านก็จะดํารงชีวิตได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 14, 'ด้วยว่าพระวิญญาณของพระเจ้าได้ทรงนําพาคนหนึ่งคนใด คนเหล่านั้นก็เป็นบุตรของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 15, 'เหตุว่าท่านไม่ได้รับนิสัยอย่างทาสซึ่งทําให้ตกในความกลัวอีก แต่ท่านได้รับพระวิญญาณผู้ทรงให้เป็นบุตรซึ่งให้เราทั้งหลายร้องเรียกพระเจ้าว่า “อับบา” คือพระบิดา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 16, 'พระวิญญาณนั้นเป็นพยานร่วมกับจิตวิญญาณของเราทั้งหลายว่า เราทั้งหลายเป็นบุตรของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 17, 'และถ้าเราทั้งหลายเป็นบุตรแล้ว เราก็เป็นผู้รับมรดกคือเป็นผู้รับมรดกของพระเจ้า และเป็นผู้รับมรดกร่วมกับพระคริสต์ เมื่อเราทั้งหลายทนทุกข์ทรมานด้วยกันกับพระองค์นั้น ก็เพื่อเราทั้งหลายจะได้สง่าราศีด้วยกันกับพระองค์ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 18, 'เพราะข้าพเจ้าเห็นว่า ความทุกข์ลําบากแห่งสมัยปัจจุบันนี้ ไม่สมควรที่จะเอาไปเปรียบกับสง่าราศีซึ่งจะเผยในเราทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 19, 'ด้วยว่าสรรพสิ่งที่ทรงสร้างแล้ว มีความเพียรคอยท่าปรารถนาให้บุตรทั้งหลายของพระเจ้าปรากฏ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 20, 'เพราะว่าสรรพสิ่งเหล่านั้นต้องเข้าอยู่ในอํานาจของอนิจจัง ไม่ใช่ตามใจชอบของตนเอง แต่เป็นไปตามพระองค์ผู้ทรงบันดาลให้เข้าอยู่นั้นด้วยมีความหวังใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 21, 'ว่าสรรพสิ่งเหล่านั้นจะได้รอดจากอํานาจแห่งความเปื่อยเน่า และจะเข้าในเสรีภาพซึ่งมีสง่าราศีแห่งบุตรทั้งหลายของพระเจ้าด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 22, 'เรารู้อยู่ว่า บรรดาสรรพสิ่งที่ทรงสร้างนั้น กําลังคร่ําครวญและผจญความทุกข์ลําบากเจ็บปวดด้วยกันมาจนทุกวันนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 23, 'และไม่ใช่สรรพสิ่งทั้งปวงเท่านั้น แต่เราทั้งหลายเองด้วย ผู้ได้รับผลแรกของพระวิญญาณ ตัวเราเองก็ยังคร่ําครวญคอยจะเป็นอย่างบุตร คือที่จะทรงไถ่กายของเราทั้งหลายไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 24, 'เหตุว่าเราทั้งหลายรอดได้เพราะความหวังใจ แต่ความหวังใจในสิ่งที่เราเห็นได้หาได้เป็นความหวังใจไม่ ด้วยว่าใครเล่าจะยังหวังในสิ่งที่เขาเห็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 25, 'แต่ถ้าเราทั้งหลายคอยหวังใจในสิ่งที่เรายังไม่ได้เห็น เราจึงมีความเพียรคอยสิ่งนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 26, 'พระวิญญาณก็ทรงช่วยเราเมื่อเราอ่อนกําลังด้วยเช่นกัน เพราะเราไม่รู้ว่าเราควรจะอธิษฐานขอสิ่งใดอย่างไร แต่พระวิญญาณเองทรงช่วยขอเพื่อเราด้วยความคร่ําครวญซึ่งเหลือที่จะพูดได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 27, 'และพระองค์ ผู้ทรงตรวจค้นใจมนุษย์ ก็ทรงทราบความหมายของพระวิญญาณ เพราะว่าพระองค์ทรงอธิษฐานขอเพื่อวิสุทธิชนตามที่ชอบพระทัยพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 28, 'และเรารู้ว่า ทุกสิ่งต่างร่วมมือกันเพื่อให้เกิดผลดีแก่คนทั้งหลายที่รักพระเจ้า คือคนทั้งปวงที่พระองค์ได้ทรงเรียกตามพระประสงค์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 29, 'เพราะว่าผู้หนึ่งผู้ใดที่พระองค์ได้ทรงทราบอยู่แล้ว ผู้นั้นพระองค์ได้ทรงตั้งไว้ให้เป็นตามลักษณะพระฉายแห่งพระบุตรของพระองค์ เพื่อพระบุตรนั้นจะได้เป็นบุตรหัวปีท่ามกลางพวกพี่น้องเป็นอันมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 30, 'ยิ่งกว่านั้นบรรดาผู้ที่พระองค์ได้ทรงตั้งไว้นั้น พระองค์ได้ทรงเรียกมาด้วย และผู้ที่พระองค์ได้ทรงเรียกมานั้น พระองค์ได้ทรงโปรดให้เป็นผู้ชอบธรรม และผู้ที่พระองค์ทรงโปรดให้เป็นผู้ชอบธรรม พระองค์ก็ทรงโปรดให้มีสง่าราศีด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 31, 'ถ้าเช่นนั้นเราจะว่าอย่างไร ถ้าพระเจ้าทรงอยู่ฝ่ายเรา ใครจะขัดขวางเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 32, 'พระองค์ผู้มิได้ทรงหวงพระบุตรของพระองค์เอง แต่ได้ทรงโปรดประทานพระบุตรนั้นเพื่อเราทั้งหลาย ถ้าเช่นนั้นพระองค์จะไม่ทรงโปรดประทานสิ่งสารพัดให้เราทั้งหลาย ด้วยกันกับพระบุตรนั้นหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 33, 'ใครจะฟ้องคนเหล่านั้นที่พระเจ้าได้ทรงเลือกไว้ พระเจ้าทรงเป็นผู้ที่ทําให้เราเป็นคนชอบธรรมแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 34, 'ใครเล่าจะเป็นผู้ปรับโทษอีก ก็คือพระคริสต์ผู้ทรงสิ้นพระชนม์แล้ว และยิ่งกว่านั้นอีกได้ทรงคืนพระชนม์ ทรงสถิต ณ เบื้องขวาพระหัตถ์ของพระเจ้า และทรงอธิษฐานขอเพื่อเราทั้งหลายด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 35, 'แล้วใครจะให้เราทั้งหลายขาดจากความรักของพระคริสต์ได้เล่า จะเป็นความยากลําบาก หรือความทุกข์ หรือการข่มเหง หรือการกันดารอาหาร หรือการเปลือยกาย หรือการถูกโพยภัย หรือการถูกคมดาบหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 36, 'ตามที่เขียนไว้แล้วว่า ‘เพราะเห็นแก่พระองค์ ข้าพระองค์ทั้งหลายจึงถูกประหารวันยังค่ํา และนับว่าเป็นเหมือนแกะสําหรับจะเอาไปฆ่า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 37, 'แต่ว่าในเหตุการณ์ทั้งปวงเหล่านี้ เรามีชัยยิ่งกว่าผู้พิชิตโดยพระองค์ผู้ได้ทรงรักเราทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 38, 'เพราะข้าพเจ้าเชื่อมั่นว่า แม้ความตาย หรือชีวิต หรือทูตสวรรค์ หรือผู้มีบรรดาศักดิ์ หรือฤทธิ์เดชทั้งหลาย หรือสิ่งซึ่งมีอยู่ในปัจจุบันนี้ หรือสิ่งซึ่งจะมีในภายหน้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 39, 'หรือซึ่งสูง หรือซึ่งลึก หรือสิ่งอื่นใดๆที่ได้ทรงสร้างแล้วนั้น จะไม่สามารถกระทําให้เราทั้งหลายขาดจากความรักของพระเจ้า ซึ่งมีอยู่ในพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเราได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 1, 'ข้าพเจ้าพูดตามความจริงในพระคริสต์ ข้าพเจ้าไม่ได้มุสา ใจสํานึกผิดชอบของข้าพเจ้าเป็นพยานฝ่ายข้าพเจ้าโดยพระวิญญาณบริสุทธิ์ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 2, 'ว่า ข้าพเจ้ามีความทุกข์หนักและเสียใจเสมอมิได้ขาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 3, 'เพราะว่าข้าพเจ้าปรารถนาจะให้ข้าพเจ้าเองถูกสาปให้ตัดขาดจากพระคริสต์ เพราะเห็นแก่พี่น้องของข้าพเจ้า คือญาติของข้าพเจ้าตามเนื้อหนัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 4, 'พวกเขาเป็นคนอิสราเอล ได้รับการทรงให้เป็นบุตรของพระเจ้าและสง่าราศี และบรรดาพันธสัญญา และการทรงประทานพระราชบัญญัติ และการปรนนิบัติพระเจ้าและพระสัญญาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 5, 'ทั้งบรรพบุรุษก็เป็นของเขาด้วย และพระคริสต์ก็ได้ทรงถือกําเนิดตามเนื้อหนังในเชื้อชาติของเขา พระองค์ผู้ทรงอยู่เหนือสารพัด ผู้ซึ่งพระเจ้าจะทรงโปรดอวยพระพรเป็นนิตย์ เอเมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 6, 'แต่มิใช่ว่าพระวจนะของพระเจ้าได้ไร้ประโยชน์ไป เพราะว่าเขาทั้งหลายที่เกิดมาจากอิสราเอลนั้นหาได้เป็นคนอิสราเอลแท้ทุกคนไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 7, 'และมิใช่ว่าทุกคนที่เป็นเชื้อสายของอับราฮัมเป็นบุตรแท้ของท่าน แต่ว่า ‘เขาจะเรียกเชื้อสายของเจ้าทางสายอิสอัค’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 8, 'คือว่าเขาเหล่านั้นที่เป็นบุตรตามเนื้อหนังจะนับเป็นบุตรของพระเจ้าไม่ได้ แต่บุตรแห่งพระสัญญานั้นจึงจะนับเป็นเชื้อสายได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 9, 'เพราะพระวจนะแห่งพระสัญญามีว่าดังนี้ ‘คราวนี้เราจะมาและนางซาราห์จะมีบุตรชาย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 10, 'และมิใช่เท่านั้น แต่ว่านางเรเบคาห์ก็ได้มีครรภ์กับชายคนหนึ่งด้วย คืออิสอัคบรรพบุรุษของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 11, '(แม้ก่อนบุตรนั้นบังเกิดมา และยังไม่ได้กระทําดีหรือชั่ว เพื่อพระดําริของพระเจ้าในการทรงเลือกนั้นจะตั้งมั่นคงอยู่ ไม่ใช่ตามการกระทํา แต่ตามซึ่งพระองค์ทรงเรียก)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 12, 'พระองค์จึงตรัสแก่นางนั้นว่า ‘พี่จะปรนนิบัติน้อง’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 13, 'ตามที่มีคําเขียนไว้แล้วว่า ‘เราก็ยังรักยาโคบ แต่เราได้เกลียดเอซาว’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 14, 'ถ้าเช่นนั้นเราจะว่าอย่างไร พระเจ้าไม่ทรงยุติธรรมหรือ ขอพระเจ้าอย่ายอมให้เป็นเช่นนั้นเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 15, 'เพราะพระองค์ตรัสกับโมเสสว่า ‘เราประสงค์จะกรุณาผู้ใด เราก็จะกรุณาผู้นั้น และเราประสงค์จะเมตตาผู้ใด เราก็จะเมตตาผู้นั้น’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 16, 'เพราะฉะนั้นจึงไม่ขึ้นแก่ความตั้งใจหรือการตะเกียกตะกายของเขา แต่ขึ้นอยู่กับพระเจ้าผู้ทรงสําแดงพระกรุณา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 17, 'เพราะมีข้อพระคัมภีร์ที่กล่าวแก่ฟาโรห์ว่า ‘เพราะเหตุนี้เองเราให้เจ้ามีตําแหน่งสูง ก็เพื่อจะแสดงฤทธานุภาพของเราโดยเจ้าและเพื่อให้นามของเราถูกประกาศออกไปทั่วโลก’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 18, 'เหตุฉะนั้นพระองค์จะทรงพระกรุณาแก่ผู้ใด ก็จะทรงพระกรุณาผู้นั้น และพระองค์จะทรงให้ผู้ใดมีใจแข็งกระด้าง ก็จะทรงให้ผู้นั้นมีใจแข็งกระด้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 19, 'แล้วท่านก็จะกล่าวแก่ข้าพเจ้าว่า “ถ้าเช่นนั้น ทําไมพระองค์จึงยังทรงติเตียน เพราะว่าผู้ใดจะขัดขืนพระทัยของพระองค์ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 20, 'โอ มนุษย์เอ๋ย ดูก่อน ท่านคือผู้ใดเล่าซึ่งท่านจะโต้ตอบกับพระเจ้าได้ สิ่งซึ่งถูกทําขึ้นแล้วนั้นจะกลับว่าแก่ผู้ทําได้หรือว่า “ท่านได้กระทําข้าพเจ้าอย่างนี้ทําไม”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 21, 'ส่วนช่างปั้นหม้อ ไม่มีสิทธิ์ที่จะเอาดินก้อนเดียวกันมาปั้นเป็นภาชนะอันมีเกียรติอันหนึ่ง และภาชนะอันไม่มีเกียรติอันหนึ่งหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 22, 'แล้วถ้าโดยทรงประสงค์จะสําแดงการลงพระอาชญา และทรงให้ฤทธิ์เดชของพระองค์ปรากฏ พระเจ้าได้ทรงอดกลั้นพระทัยไว้ช้านานต่อผู้เหล่านั้น ที่เป็นภาชนะอันสมควรแก่พระอาชญา ซึ่งเตรียมไว้สําหรับความพินาศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 23, 'เพื่อจะได้ทรงสําแดงสง่าราศีอันอุดมของพระองค์แก่บรรดาผู้ที่เป็นภาชนะแห่งพระเมตตา ซึ่งพระองค์ได้ทรงจัดเตรียมไว้ก่อนให้สมกับสง่าราศี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 24, 'คือเราทั้งหลายที่พระองค์ได้ทรงเรียกมาแล้ว มิใช่จากยิวพวกเดียว แต่จากพวกต่างชาติด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 25, 'ดังที่พระองค์ตรัสไว้ในพระคัมภีร์โฮเชยาว่า ‘เราจะเรียกเขาเหล่านั้นว่าเป็นชนชาติของเรา ซึ่งเมื่อก่อนเขาหาได้เป็นชนชาติของเราไม่ และจะเรียกเขาว่าเป็นที่รัก ซึ่งเมื่อก่อนเขาหาได้เป็นที่รักไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 26, 'และต่อมาในสถานที่ซึ่งทรงกล่าวแก่เขาว่า “เจ้าทั้งหลายไม่ใช่ชนชาติของเรา” ในที่นั้นเองเขาจะได้ชื่อว่า เป็นบุตรของพระเจ้าผู้ทรงพระชนม์อยู่’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 27, 'และท่านอิสยาห์ได้ร้องประกาศเรื่องพวกอิสราเอลด้วยว่า ‘แม้พวกลูกอิสราเอลจะมากเหมือนเม็ดทรายที่ทะเล แต่คนที่เหลืออยู่จะรอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 28, 'ด้วยว่าพระองค์จะทรงให้การนั้นสําเร็จ และจะให้สําเร็จโดยเร็วพลันในความชอบธรรม เพราะว่าองค์พระผู้เป็นเจ้าจะทรงให้การนั้นสําเร็จโดยเร็วพลันบนพิภพนี้’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 29, 'และตามที่ท่านอิสยาห์ได้กล่าวไว้ก่อนว่า ‘ถ้าองค์พระผู้เป็นเจ้าแห่งจอมโยธามิได้ทรงเหลือเชื้อสายไว้ให้เราบ้าง เราก็จะได้เป็นเหมือนเมืองโสโดม และจะเป็นเหมือนเมืองโกโมราห์’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 30, 'ถ้าเช่นนั้นเราจะว่าอย่างไร จะว่าพวกต่างชาติที่ไม่ได้ใฝ่หาความชอบธรรม ก็ยังได้รับความชอบธรรมคือความชอบธรรมที่เกิดขึ้นโดยความเชื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 31, 'แต่พวกอิสราเอลซึ่งใฝ่หาพระราชบัญญัติแห่งความชอบธรรม ก็ยังไม่ได้บรรลุตามพระราชบัญญัติแห่งความชอบธรรมนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 32, 'เพราะอะไร เพราะเหตุที่เขามิได้แสวงหาโดยความเชื่อแต่แสวงหาโดยการกระทําตามพระราชบัญญัติ เขาจึงสะดุดก้อนหินที่ให้สะดุดนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 33, 'ดังที่มีคําเขียนไว้แล้วว่า ‘จงดูเถิด เราได้วางศิลาก้อนหนึ่งไว้ในศิโยนซึ่งจะทําให้สะดุด และก้อนหินที่ทําให้ขุ่นเคืองใจ แต่ผู้ใดที่เชื่อในพระองค์นั้นก็จะไม่ได้รับความอับอาย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 1, 'พี่น้องทั้งหลาย ความปรารถนาในจิตใจของข้าพเจ้าและคําวิงวอนขอต่อพระเจ้าเพื่อคนอิสราเอลนั้น คือขอให้เขารอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 2, 'ข้าพเจ้าเป็นพยานให้เขาว่า เขามีความกระตือรือร้นที่จะปรนนิบัติพระเจ้า แต่หาได้เป็นตามปัญญาไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 3, 'เพราะว่าเขาไม่รู้จักความชอบธรรมของพระเจ้า แต่อุตส่าห์จะตั้งความชอบธรรมของตนขึ้น เขาจึงไม่ได้ยอมอยู่ในความชอบธรรมของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 4, 'เพราะว่าพระคริสต์ทรงเป็นจุดจบของพระราชบัญญัติ เพื่อให้ทุกคนที่มีความเชื่อได้รับความชอบธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 5, 'โมเสสได้เขียนเรื่องความชอบธรรมซึ่งมีพระราชบัญญัติเป็นมูลฐานว่า ‘คนใดที่ประพฤติตามสิ่งเหล่านั้นจะได้ชีวิตโดยการประพฤตินั้น’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 6, 'แต่ความชอบธรรมที่มีความเชื่อเป็นมูลฐานว่าอย่างนี้ว่า “อย่านึกในใจของตัวว่า ใครจะขึ้นไปบนสวรรค์” (คือจะเชิญพระคริสต์ลงมาจากเบื้องบน)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 7, 'หรือ “ใครจะลงไปยังที่ลึก” (คือจะเชิญพระคริสต์ขึ้นมาจากความตายอีก)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 8, 'แต่ความชอบธรรมนั้นว่าอย่างไร ก็ว่า “ถ้อยคํานั้นอยู่ใกล้ท่าน อยู่ในปากของท่านและอยู่ในใจของท่าน” คือคําแห่งความเชื่อที่เราทั้งหลายประกาศอยู่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 9, 'คือว่าถ้าท่านจะยอมรับด้วยปากของท่านว่า พระเยซูทรงเป็นองค์พระผู้เป็นเจ้า และเชื่อในจิตใจของท่านว่าพระเจ้าได้ทรงชุบพระองค์ให้เป็นขึ้นมาจากความตาย ท่านจะรอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 10, 'ด้วยว่าความเชื่อด้วยใจก็นําไปสู่ความชอบธรรม และการยอมรับด้วยปากก็นําไปสู่ความรอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 11, 'เพราะมีข้อพระคัมภีร์ว่า ‘ผู้ใดที่เชื่อในพระองค์นั้นก็จะไม่ได้รับความอับอาย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 12, 'เพราะว่าพวกยิวและพวกกรีก ไม่ทรงถือว่าต่างกัน ด้วยว่าทรงเป็นองค์พระผู้เป็นเจ้าองค์เดียวกันของคนทั้งปวง ซึ่งทรงโปรดอย่างบริบูรณ์แก่คนทั้งปวงที่ทูลขอต่อพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 13, 'เพราะว่า ‘ผู้ใดที่จะร้องออกพระนามขององค์พระผู้เป็นเจ้าก็จะรอด’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 14, 'แต่ผู้ที่ยังไม่เชื่อในพระองค์จะทูลขอต่อพระองค์อย่างไรได้ และผู้ที่ยังไม่ได้ยินถึงพระองค์จะเชื่อในพระองค์อย่างไรได้ และเมื่อไม่มีผู้ใดประกาศให้เขาฟัง เขาจะได้ยินอย่างไรได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 15, 'และถ้าไม่มีใครใช้เขาไป เขาจะไปประกาศอย่างไรได้ ตามที่มีคําเขียนไว้แล้วว่า ‘เท้าของคนเหล่านั้นที่ประกาศข่าวประเสริฐแห่งสันติสุข และประกาศข่าวประเสริฐแห่งสิ่งอันประเสริฐ ก็งามสักเท่าใด’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 16, 'แต่มิใช่ทุกคนได้เชื่อฟังข่าวประเสริฐนั้น เพราะอิสยาห์ได้กล่าวไว้ว่า ‘พระองค์เจ้าข้า ใครเล่าได้เชื่อสิ่งที่เขาได้ยินจากเราทั้งหลาย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 17, 'ฉะนั้นความเชื่อเกิดขึ้นได้ก็เพราะการได้ยิน และการได้ยินเกิดขึ้นได้ก็เพราะการประกาศพระวจนะของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 18, 'ข้าพเจ้าถามว่า “เขาทั้งหลายไม่ได้ยินหรือ” เขาได้ยินแล้วจริงๆ ‘เสียงของพวกเขากระจายออกไปทั่วแผ่นดินโลก และถ้อยคําของพวกเขาประกาศออกไปถึงที่สุดปลายพิภพ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 19, 'ข้าพเจ้าจึงถามว่า “พลอิสราเอลไม่เข้าใจหรือ” ตอนแรกโมเสสกล่าวว่า ‘เราจะให้เจ้าทั้งหลายอิจฉาผู้ที่ไม่ใช่ชนชาติ เราจะยั่วโทสะเจ้าด้วยประชาชาติที่เขลาชาติหนึ่ง’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 20, 'แล้วอิสยาห์กล้ากล่าวว่า ‘คนเหล่านั้นที่มิได้แสวงหาเราได้พบเรา เราได้ปรากฏแก่คนที่มิได้ถามหาเรา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 21, 'แต่ท่านได้กล่าวถึงพวกอิสราเอลว่า ‘เรายื่นมือของเราออกตลอดวันต่อชนชาติหนึ่งซึ่งไม่เชื่อฟังและดื้อรั้น’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 1, 'เมื่อเป็นเช่นนี้แล้ว ข้าพเจ้าจึงถามว่า “พระเจ้าทรงทอดทิ้งชนชาติของพระองค์แล้วหรือ” ขอพระเจ้าอย่ายอมให้เป็นเช่นนั้นเลย ข้าพเจ้าเองก็เป็นชนชาติอิสราเอล เป็นเชื้อสายของอับราฮัม เป็นตระกูลเบนยามิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 2, 'พระเจ้ามิได้ทรงทอดทิ้งชนชาติของพระองค์นั้นที่พระองค์ทรงทราบล่วงหน้าแล้ว ท่านไม่รู้เรื่องซึ่งเขียนไว้แล้วในพระคัมภีร์กล่าวถึงท่านเอลียาห์หรือ ท่านได้กล่าวโทษพวกอิสราเอลต่อพระเจ้าว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 3, '‘พระองค์เจ้าข้า พวกเขาได้ฆ่าพวกศาสดาพยากรณ์ของพระองค์ แท่นบูชาของพระองค์เขาก็ได้ขุดทําลายลงเสีย เหลืออยู่แต่ข้าพระองค์คนเดียวและเขาแสวงหาช่องทางที่จะประหารชีวิตของข้าพระองค์’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 4, 'แล้วพระเจ้าทรงตอบท่านว่าอย่างไร ว่าดังนี้ ‘เราได้เหลือคนไว้สําหรับเราเจ็ดพันคน ซึ่งเป็นผู้ที่มิได้คุกเข่าลงต่อรูปพระบาอัล’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 5, 'เช่นนั้นแหละบัดนี้ก็ยังมีพวกที่เหลืออยู่ตามที่ได้ทรงเลือกไว้โดยพระคุณ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 6, 'แต่ถ้าเป็นทางพระคุณก็หาได้เป็นเพราะทางการกระทําไม่ ฉะนั้นแล้ว พระคุณก็ไม่เป็นพระคุณอีกต่อไป แต่ถ้าเป็นทางการกระทําก็หาได้เป็นเพราะทางพระคุณไม่ ฉะนั้นแล้ว การกระทําก็ไม่เป็นการกระทําอีกต่อไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 7, 'ถ้าเช่นนั้นจะเป็นอย่างไร พวกอิสราเอลไม่พบสิ่งที่เขาแสวงหา แต่คนที่พระเจ้าได้ทรงเลือกไว้นั้นเป็นผู้ได้พบ และคนนอกนั้นก็มีใจแข็งกระด้างไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 8, '(ตามที่มีคําเขียนไว้แล้วว่า ‘พระเจ้าได้ทรงประทานใจที่เซื่องซึม ประทานตาที่มองไม่เห็น หูที่ฟังไม่ได้ยินให้แก่เขา) จนทุกวันนี้’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 9, 'ดาวิดทรงกล่าวว่า ‘ขอให้สํารับของเขากลายเป็นบ่วงแร้ว และเครื่องดัก และเป็นสิ่งให้สะดุด และเป็นสิ่งสนองเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 10, 'ขอให้ตาของเขามืดไปเพื่อเขาจะได้มองไม่เห็น และให้หลังของเขางอค่อมตลอดไป’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 11, 'ข้าพเจ้าจึงถามว่า “พวกอิสราเอลสะดุดจนหกล้มทีเดียวหรือ” ขอพระเจ้าอย่ายอมให้เป็นเช่นนั้นเลย แต่การที่เขาละเมิดนั้นเป็นเหตุให้ความรอดแผ่มาถึงพวกต่างชาติ เพื่อจะให้พวกอิสราเอลมีใจมานะขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 12, 'แต่ถ้าการที่พวกอิสราเอลละเมิดนั้นเป็นเหตุให้ทั้งโลกบริบูรณ์ และถ้าการพ่ายแพ้ของเขาเป็นเหตุให้คนต่างชาติบริบูรณ์ เขาจะยิ่งบริบูรณ์มากสักเท่าใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 13, 'แต่ข้าพเจ้ากล่าวแก่พวกท่านที่เป็นคนต่างชาติ เพราะข้าพเจ้าเป็นอัครสาวกมายังพวกต่างชาติ ข้าพเจ้าจึงยกย่องหน้าที่ของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 14, 'เพื่อด้วยวิธีใดก็ตามข้าพเจ้าจะได้เร้าใจพี่น้องร่วมชาติของข้าพเจ้าให้เขาเอาอย่าง เพื่อให้เขารอดได้บ้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 15, 'เพราะว่า ถ้าการที่พี่น้องร่วมชาติของข้าพเจ้าถูกพระเจ้าทรงทอดทิ้งเสียแล้วเป็นเหตุให้คนทั้งโลกกลับคืนดีกับพระองค์ การที่พระองค์ทรงรับเขากลับมาอีกนั้น ก็เป็นอย่างไร ก็เป็นเหมือนกับว่าเขาได้ตายไปแล้วและกลับฟื้นขึ้นใหม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 16, 'เพราะถ้าแป้งก้อนแรกบริสุทธิ์ ทั้งอ่างก็บริสุทธิ์ด้วย และถ้ารากบริสุทธิ์ กิ่งทั้งหมดก็บริสุทธิ์ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 17, 'แต่ถ้าทรงหักกิ่งบางกิ่งออกเสียแล้ว และได้ทรงนําท่านผู้เป็นกิ่งมะกอกป่ามาต่อกิ่งไว้แทนกิ่งเหล่านั้น เพื่อให้เข้าเป็นส่วนได้รับน้ําเลี้ยงจากรากต้นมะกอกเทศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 18, 'ท่านก็อย่าอวดดีต่อกิ่งเหล่านั้น แต่ถ้าท่านอวดดี ใช่ว่าท่านได้เลี้ยงรากนั้นก็หาไม่ แต่รากต่างหากเลี้ยงท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 19, 'ท่านอาจจะแย้งว่า “กิ่งเหล่านั้นได้ทรงหักออกเสียแล้วก็เพื่อจะได้ต่อกิ่งข้าไว้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 20, 'ถูกแล้ว เขาถูกหักออกก็เพราะเขาไม่เชื่อ แต่ที่ท่านอยู่ได้ก็เพราะความเชื่อเท่านั้น อย่าเย่อหยิ่งไปเลย แต่จงเกรงกลัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 21, 'เพราะว่าถ้าพระเจ้ามิได้ทรงงดโทษกิ่งเหล่านั้นที่เป็นกิ่งเดิม ก็เกรงว่าพระองค์จะไม่ทรงงดโทษท่านเหมือนกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 22, 'เหตุฉะนั้นจงพิจารณาดูทั้งพระกรุณาและความเข้มงวดของพระเจ้า กับคนเหล่านั้นที่หลงผิดไปก็ทรงเข้มงวด แต่สําหรับท่านก็ทรงพระกรุณา ถ้าท่านจะดํารงอยู่ในพระกรุณาของพระองค์นั้นต่อไป มิฉะนั้นท่านก็จะถูกตัดออกเสียด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 23, 'ส่วนเขาทั้งหลายด้วย ถ้าเขาไม่ดํารงอยู่ในความไม่เชื่อสืบไป เขาก็จะได้รับการต่อกิ่งเข้าไปใหม่ เพราะว่าพระเจ้าทรงฤทธิ์ที่จะทรงให้เขาต่อกิ่งเข้าอีกได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 24, 'เพราะว่าถ้าพระเจ้าทรงตัดท่านออกจากต้นมะกอกป่าซึ่งเป็นต้นไม้ตามธรรมชาติ และทรงนํามาต่อกิ่งกับต้นมะกอกเทศพันธุ์ดีซึ่งผิดธรรมชาติของมันแล้ว การที่จะเอากิ่งเหล่านั้น ซึ่งเป็นกิ่งเดิมมาต่อกิ่งเข้ากับต้นของมันเอง ก็จะง่ายยิ่งกว่านั้นสักเท่าใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 25, 'เหตุฉะนั้น พี่น้องทั้งหลาย ข้าพเจ้าไม่อยากให้ท่านทั้งหลายเขลาในข้อความลึกลับนี้ เกลือกว่าท่านจะอวดรู้ คือเรื่องที่บางคนในพวกอิสราเอลได้มีใจแข็งกระด้างไป จนถึงพวกต่างชาติได้เข้ามาครบจํานวน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 26, 'และเมื่อเป็นดังนั้น พวกอิสราเอลทั้งปวงก็จะได้รับความรอด ตามที่มีคําเขียนไว้แล้วว่า ‘พระผู้ช่วยให้รอดจะเสด็จมาจากเมืองศิโยน และจะทรงกําจัดอธรรมให้สูญสิ้นไปจากยาโคบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 27, 'นี่แหละเป็นพันธสัญญาของเรากับเขาทั้งหลาย เมื่อเราจะยกโทษบาปของเขา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 28, 'ในเรื่องข่าวประเสริฐนั้น เขาเหล่านั้นก็เป็นศัตรูเพื่อประโยชน์ของพวกท่าน แต่ถ้าว่าตามที่ได้ทรงเลือกไว้ เขาทั้งหลายก็เป็นที่รักเนื่องจากบรรพบุรุษของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 29, 'เพราะว่าพระเจ้ามิได้ทรงกลับพระทัยในการที่ได้ทรงให้ของประทานและทรงเรียกไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 30, 'ท่านทั้งหลายเมื่อก่อนมิได้เชื่อพระเจ้า แต่บัดนี้ได้รับพระกรุณาเพราะความไม่เชื่อของพวกเขาเหล่านั้นฉันใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 31, 'บัดนี้เขาเหล่านั้นก็มิได้เชื่อ เพื่อว่าเขาจะได้รับพระกรุณาโดยพระกรุณาที่ได้ประทานแก่ท่านทั้งหลายฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 32, 'เพราะว่าพระเจ้าทรงปล่อยให้คนทุกคนอยู่ในฐานะที่ไม่เชื่อ เพื่อพระองค์จะได้ทรงพระกรุณาแก่เขาทั้งหลายทุกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 33, 'โอ พระปัญญาและความรอบรู้ของพระเจ้านั้นล้ําลึกเท่าใด คําตัดสินของพระองค์นั้นเหลือที่จะหยั่งรู้ได้ และทางของพระองค์ก็เหลือที่จะสืบเสาะได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 34, 'เพราะว่า ‘ใครเล่ารู้จักพระทัยขององค์พระผู้เป็นเจ้า หรือใครเล่าเป็นที่ปรึกษาพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 35, 'หรือใครเล่าได้ถวายสิ่งหนึ่งสิ่งใดแด่พระองค์ ที่พระองค์จะต้องประทานตอบแทนให้แก่เขา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 36, 'เพราะสิ่งสารพัดมาจากพระองค์ โดยพระองค์และเพื่อพระองค์ ขอสง่าราศีจงมีแด่พระองค์สืบๆไปเป็นนิตย์ เอเมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 1, 'พี่น้องทั้งหลาย ด้วยเหตุนี้โดยเห็นแก่ความเมตตากรุณาของพระเจ้า ข้าพเจ้าจึงวิงวอนท่านทั้งหลายให้ถวายตัวของท่านแด่พระองค์ เพื่อเป็นเครื่องบูชาที่มีชีวิต อันบริสุทธิ์ และเป็นที่พอพระทัยพระเจ้า ซึ่งเป็นการปรนนิบัติอันสมควรของท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 2, 'อย่าทําตามอย่างชาวโลกนี้ แต่จงรับการเปลี่ยนแปลงจิตใจเสียใหม่ เพื่อท่านจะได้ทราบพระประสงค์ของพระเจ้าว่าอะไรดี อะไรเป็นที่ชอบพระทัย และอะไรดียอดเยี่ยม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 3, 'ข้าพเจ้าขอกล่าวแก่ท่านทั้งหลายทุกคน โดยพระคุณซึ่งทรงประทานแก่ข้าพเจ้าแล้วว่า อย่าคิดถือตัวเกินที่ตนควรจะคิดนั้น แต่จงคิดให้ถ่อมสุขุมสมกับขนาดความเชื่อที่พระเจ้าได้ทรงโปรดประทานแก่มนุษย์ทุกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 4, 'เพราะว่าในร่างกายอันเดียวนั้นเรามีอวัยวะหลายอย่าง และอวัยวะนั้นๆมิได้มีหน้าที่เหมือนกันฉันใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 5, 'พวกเราผู้เป็นหลายคนยังเป็นกายอันเดียวในพระคริสต์ และเป็นอวัยวะแก่กันและกันฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 6, 'และเราทุกคนมีของประทานที่ต่างกันตามพระคุณที่ได้ทรงประทานให้แก่เรา คือถ้าเป็นการพยากรณ์ ก็จงพยากรณ์ตามกําลังของความเชื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 7, 'ถ้าเป็นการปรนนิบัติก็จงปรนนิบัติ ถ้าเป็นการสั่งสอนก็จงสั่งสอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 8, 'ถ้าเป็นการเตือนสติก็จงเตือนสติ ถ้าเป็นการบริจาคก็จงให้โดยเต็มใจ ผู้ที่ครอบครองก็จงครอบครองด้วยเอาใจใส่ ผู้ที่แสดงความเมตตาก็จงแสดงด้วยใจยินดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 9, 'จงให้ความรักปราศจากมารยา จงเกลียดชังสิ่งที่ชั่ว จงยึดมั่นในสิ่งที่ดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 10, 'จงรักกันฉันพี่น้อง ส่วนการที่ให้เกียรติแก่กันและกันนั้น จงถือว่าผู้อื่นดีกว่าตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 11, 'อย่าเกียจคร้านในการงาน จงมีจิตใจกระตือรือร้น จงปรนนิบัติองค์พระผู้เป็นเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 12, 'จงชื่นชมยินดีในความหวัง จงอดทนต่อความยากลําบาก จงขะมักเขม้นอธิษฐาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 13, 'จงช่วยวิสุทธิชนเมื่อเขาขัดสน จงมีน้ําใจอัธยาศัยไมตรี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 14, 'จงอวยพรแก่คนที่ข่มเหงท่าน จงอวยพร อย่าแช่งด่าเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 15, 'จงชื่นชมยินดีกับผู้ที่มีความชื่นชมยินดี จงร้องไห้กับผู้ที่ร้องไห้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 16, 'จงเป็นน้ําหนึ่งใจเดียวกัน อย่าใฝ่สูง แต่จงถ่อมใจลงมาหาคนที่ต่ําต้อย อย่าถือว่าตัวฉลาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 17, 'อย่าทําชั่วตอบแทนชั่วแก่ผู้หนึ่งผู้ใดเลย ‘แต่จงมุ่งกระทําสิ่งที่ซื่อสัตย์ในสายตาของคนทั้งปวง’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 18, 'ถ้าเป็นได้คือเรื่องที่ขึ้นอยู่กับท่าน จงอยู่อย่างสงบสุขกับทุกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 19, 'ท่านผู้เป็นที่รักของข้าพเจ้า อย่าทําการแก้แค้น แต่จงมอบการนั้นไว้แล้วแต่พระเจ้าจะทรงลงพระอาชญา เพราะมีคําเขียนไว้แล้วว่า ‘องค์พระผู้เป็นเจ้าตรัสว่า “การแก้แค้นเป็นของเรา เราเองจะตอบสนอง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 20, 'เหตุฉะนั้น ถ้าศัตรูของท่านหิว จงให้อาหารเขารับประทาน ถ้าเขากระหาย จงให้น้ําเขาดื่ม เพราะว่าการทําอย่างนั้นเป็นการสุมถ่านที่ลุกโพลงไว้บนศีรษะของเขา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 21, 'อย่าให้ความชั่วชนะท่านได้ แต่จงชนะความชั่วด้วยความดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 1, 'ทุกคนจงยอมอยู่ใต้บังคับของผู้ที่มีอํานาจ เพราะว่าไม่มีอํานาจใดเลยที่มิได้มาจากพระเจ้า และผู้ที่ทรงอํานาจนั้นพระเจ้าทรงแต่งตั้งขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 2, 'เหตุฉะนั้นผู้ใดก็ตามที่ขัดขืนอํานาจนั้นก็ขัดขืนผู้ซึ่งพระเจ้าทรงแต่งตั้งขึ้น และผู้ที่ขัดขืนนั้นจะนําพระอาชญามาสู่ตนเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 3, 'เพราะว่าผู้ครอบครองนั้นไม่น่ากลัวเลยสําหรับคนที่ทําความดี แต่ว่าเป็นที่น่ากลัวสําหรับคนที่ทําความชั่ว ท่านไม่อยากจะกลัวผู้มีอํานาจหรือ ถ้าเช่นนั้นก็จงประพฤติแต่ความดี แล้วท่านจะได้รับการสรรเสริญจากผู้มีอํานาจนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 4, 'เพราะว่าผู้ครอบครองนั้นเป็นผู้รับใช้ของพระเจ้าเพื่อให้ประโยชน์แก่ท่าน แต่ถ้าท่านทําการชั่วก็จงกลัวเถิด เพราะว่าผู้ครอบครองนั้นหาได้ถือดาบไว้เฉยๆไม่ ด้วยว่าท่านเป็นผู้รับใช้ของพระเจ้า เป็นผู้กระทําการแก้แค้นแก่ทุกคนที่ประพฤติชั่ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 5, 'เหตุฉะนั้นท่านจะต้องอยู่ในบังคับบัญชา มิใช่เพราะเกรงพระอาชญาสิ่งเดียว แต่เพราะจิตที่สํานึกผิดและชอบด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 6, 'เพราะเหตุผลอันเดียวกันท่านจึงได้เสียส่วยอากรด้วย เพราะว่าผู้มีอํานาจนั้นเป็นผู้รับใช้ของพระเจ้า และปฏิบัติหน้าที่นี้อยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 7, 'เหตุฉะนั้นท่านทั้งหลายจงให้แก่ทุกคนตามที่เขาควรจะได้รับ ส่วยอากรควรจะให้แก่ผู้ใด จงให้แก่ผู้นั้น ภาษีควรจะให้แก่ผู้ใด จงให้แก่ผู้นั้น ความยําเกรงควรจะให้แก่ผู้ใด จงให้แก่ผู้นั้น เกียรติยศควรจะให้แก่ผู้ใด จงให้แก่ผู้นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 8, 'อย่าเป็นหนี้อะไรใคร นอกจากความรักซึ่งมีต่อกัน เพราะว่าผู้ที่รักคนอื่นก็ทําให้พระราชบัญญัติสําเร็จแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 9, 'พระบัญญัติกล่าวว่า ‘อย่าล่วงประเวณีผัวเมียเขา อย่าฆ่าคน อย่าลักทรัพย์ อย่าเป็นพยานเท็จ อย่าโลภ’ ทั้งพระบัญญัติอื่นๆก็รวมอยู่ในข้อนี้คือ ‘ท่านจงรักเพื่อนบ้านเหมือนรักตนเอง’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 10, 'ความรักไม่ทําอันตรายเพื่อนบ้านเลย เหตุฉะนั้นความรักจึงเป็นที่ให้พระราชบัญญัติสําเร็จแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 11, 'นอกจากนี้ท่านควรจะรู้กาลสมัยว่า เดี๋ยวนี้เป็นเวลาที่เราควรจะตื่นจากหลับแล้ว เพราะว่าบัดนี้เวลาที่เราจะรอดนั้นใกล้กว่าเวลาที่เราได้เริ่มเชื่อนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 12, 'กลางคืนล่วงไปมากแล้ว และรุ่งเช้าก็ใกล้เข้ามา เหตุฉะนั้นเราจงเลิกการกระทําของความมืด และจงสวมเครื่องอาวุธของความสว่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 13, 'เราจงดําเนินชีวิตให้เหมาะสมกับเวลากลางวัน มิใช่เลี้ยงเสพสุราเมามาย มิใช่หยาบโลนลามก มิใช่วิวาทริษยากัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 14, 'แต่ท่านทั้งหลายจงประดับตัวด้วยพระเยซูคริสต์เจ้า และอย่าจัดเตรียมอะไรไว้บําเรอเนื้อหนัง เพื่อจะให้สําเร็จตามความปรารถนาของเนื้อหนังนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 1, 'ส่วนคนที่ยังอ่อนในความเชื่อนั้น จงรับเขาไว้ แต่มิใช่เพื่อให้โต้เถียงกันในเรื่องความเชื่อที่แตกต่างกันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 2, 'คนหนึ่งถือว่าจะกินอะไรก็ได้ทั้งนั้น แต่อีกคนหนึ่งที่ยังอ่อนในความเชื่ออยู่ก็กินแต่ผักเท่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 3, 'อย่าให้คนที่กินนั้นดูหมิ่นคนที่ไม่ได้กิน และอย่าให้คนที่มิได้กินกล่าวโทษคนที่ได้กิน เหตุว่าพระเจ้าได้ทรงโปรดรับเขาไว้แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 4, 'ท่านเป็นใครเล่าจึงกล่าวโทษผู้รับใช้ของคนอื่น ผู้รับใช้คนนั้นจะได้ดีหรือจะล่มจมก็สุดแล้วแต่นายของเขา และเขาก็จะได้ดีแน่นอน เพราะว่าพระเจ้าทรงฤทธิ์สามารถให้เขาได้ดีได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 5, 'คนหนึ่งถือว่าวันหนึ่งดีกว่าอีกวันหนึ่ง แต่อีกคนหนึ่งถือว่าทุกวันเหมือนกัน ขอให้ทุกคนมีความแน่ใจในความคิดเห็นของตนเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 6, 'ผู้ที่ถือวันก็ถือเพื่อถวายเกียรติแด่องค์พระผู้เป็นเจ้า และผู้ที่ไม่ถือวันก็ไม่ถือเพื่อถวายเกียรติแด่องค์พระผู้เป็นเจ้า ผู้ที่กินก็กินเพื่อถวายเกียรติแด่องค์พระผู้เป็นเจ้า เพราะเขาขอบพระคุณพระเจ้า และผู้ที่มิได้กินก็มิได้กินเพื่อถวายเกียรติแด่องค์พระผู้เป็นเจ้า และยังขอบพระคุณพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 7, 'เพราะในพวกเราไม่มีผู้ใดมีชีวิตอยู่เพื่อตนเองฝ่ายเดียว และไม่มีผู้ใดตายเพื่อตนเองฝ่ายเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 8, 'ถ้าเรามีชีวิตอยู่ก็มีชีวิตอยู่เพื่อองค์พระผู้เป็นเจ้า และถ้าเราตายก็ตายเพื่อองค์พระผู้เป็นเจ้า เหตุฉะนั้นไม่ว่าเรามีชีวิตอยู่หรือตายไปก็ตาม เราก็เป็นคนขององค์พระผู้เป็นเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 9, 'เพราะเหตุนี้เองพระคริสต์จึงได้ทรงสิ้นพระชนม์และได้ทรงเป็นขึ้นมาและทรงพระชนม์อีก เพื่อจะได้เป็นองค์พระผู้เป็นเจ้าของทั้งคนตายและคนเป็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 10, 'แต่ตัวท่านเล่า เหตุไฉนท่านจึงกล่าวโทษพี่น้องของท่าน หรือเหตุไฉนท่านจึงดูหมิ่นพี่น้องของท่าน เพราะว่าเราทุกคนต้องยืนอยู่หน้าบัลลังก์พิพากษาของพระคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 11, 'เพราะมีคําเขียนไว้ว่า ‘องค์พระผู้เป็นเจ้าได้ตรัสว่า “เรามีชีวิตอยู่ฉันใด หัวเข่าทุกหัวเข่าจะต้องคุกกราบลงต่อเรา และลิ้นทุกลิ้นจะต้องร้องสรรเสริญพระเจ้า”’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 12, 'ฉะนั้นเราทุกคนจะต้องทูลเรื่องราวของตัวเองต่อพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 13, 'ดังนั้นเราอย่ากล่าวโทษกันและกันอีกเลย แต่จงตัดสินใจเสียดีกว่า คืออย่าให้ผู้หนึ่งผู้ใดวางสิ่งซึ่งให้สะดุด หรือสิ่งซึ่งเป็นเหตุให้ล้มลงไว้ต่อหน้าพี่น้อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 14, 'ข้าพเจ้ารู้และปลงใจเชื่อเป็นแน่ในองค์พระเยซูเจ้าว่า ไม่มีสิ่งหนึ่งสิ่งใดที่เป็นมลทินในตัวเองเลย แต่ถ้าผู้ใดถือว่าสิ่งใดเป็นมลทิน สิ่งนั้นก็เป็นมลทินสําหรับคนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 15, 'แต่ถ้าพี่น้องของท่านไม่สบายใจเพราะอาหารที่ท่านกิน ท่านก็ไม่ได้ดําเนินตามทางแห่งความรักเสียแล้ว พระคริสต์ทรงสิ้นพระชนม์เพื่อผู้ใด ก็อย่าให้คนนั้นพินาศเพราะอาหารที่ท่านกินเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 16, 'ฉะนั้นอย่าให้การดีของท่านเป็นที่ให้เขาติเตียนได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 17, 'เพราะว่าอาณาจักรของพระเจ้านั้นไม่ใช่การกินและการดื่ม แต่เป็นความชอบธรรมและสันติสุขและความชื่นชมยินดีในพระวิญญาณบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 18, 'ผู้ที่ปรนนิบัติพระคริสต์ในการเหล่านั้นก็เป็นที่พอพระทัยพระเจ้า และเป็นที่พอใจของมนุษย์ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 19, 'เหตุฉะนั้นให้เรามุ่งกระทําในสิ่งซึ่งทําให้เกิดความสงบสุขแก่กันและกัน และสิ่งเหล่านั้นซึ่งทําให้เกิดความเจริญแก่กันและกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 20, 'อย่าทําลายงานของพระเจ้าเพราะเรื่องอาหารเลย ทุกสิ่งทุกอย่างปราศจากมลทินก็จริง แต่ผู้ใดที่กินอาหารซึ่งเป็นเหตุให้ผู้อื่นหลงผิด ก็มีความผิดด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 21, 'เป็นการดีที่จะไม่กินเนื้อสัตว์หรือดื่มน้ําองุ่นหรือทําสิ่งใดๆที่เป็นเหตุให้พี่น้องสะดุด หรือสะดุดใจหรือทําให้อ่อนกําลัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 22, 'ท่านมีความเชื่อหรือ จงยึดไว้ให้มั่นต่อพระพักตร์พระเจ้า ผู้ใดไม่มีเหตุที่จะติเตียนตัวเองในสิ่งที่ตนเห็นชอบแล้วนั้นก็เป็นสุข');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 23, 'แต่ผู้ที่ยังสงสัยอยู่นั้น ถ้าเขากินก็จะถูกลงพระอาชญา เพราะเขามิได้กินด้วยความเชื่อ ทั้งนี้เพราะการกระทําใดๆก็ตามที่มิได้กระทําด้วยความเชื่อก็เป็นบาปทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 1, 'พวกเราที่มีความเชื่อเข้มแข็งควรจะอดทนในข้อเคร่งหยุมๆหยิมๆของคนที่อ่อนในความเชื่อ และไม่ควรกระทําสิ่งใดตามความพอใจของตัวเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 2, 'เราทุกคนจงกระทําให้เพื่อนบ้านพอใจ เพื่อนําประโยชน์และความเจริญมาให้เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 3, 'เพราะว่าพระคริสต์ก็มิได้ทรงกระทําสิ่งที่พอพระทัยพระองค์ ตามที่มีคําเขียนไว้แล้วว่า ‘คําพูดเยาะเย้ยของบรรดาผู้ที่เยาะเย้ยพระองค์ ตกอยู่แก่ข้าพระองค์’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 4, 'เพราะว่าสิ่งที่เขียนไว้ในสมัยก่อนนั้นก็เขียนไว้เพื่อสั่งสอนเรา เพื่อเราจะได้มีความหวังโดยความเพียรและความชูใจด้วยพระคัมภีร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 5, 'ขอพระเจ้าแห่งความเพียรและความชูใจทรงโปรดช่วยให้ท่านมีน้ําหนึ่งใจเดียวกันตามอย่างพระเยซูคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 6, 'เพื่อท่านทั้งหลายจะได้มีใจและปากพร้อมเพรียงกันสรรเสริญพระเจ้า ผู้เป็นพระบิดาของพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 7, 'เหตุฉะนั้นจงต้อนรับกันและกัน เช่นเดียวกับที่พระคริสต์ได้ทรงต้อนรับเราทั้งหลายเพื่อพระเกียรติของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 8, 'บัดนี้ข้าพเจ้าขอบอกว่า พระเยซูคริสต์ได้ทรงเป็นผู้รับใช้สําหรับพวกที่เข้าสุหนัตในเรื่องเกี่ยวกับความจริงของพระเจ้า เพื่อยืนยันถึงพระสัญญาเหล่านั้นที่ได้ทรงกระทําไว้กับบรรพบุรุษทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 9, 'และเพื่อให้คนต่างชาติได้ถวายพระเกียรติยศแด่พระเจ้าเพราะพระเมตตาของพระองค์ ตามที่มีคําเขียนไว้แล้วว่า ‘เพราะเหตุนี้ข้าพระองค์ขอสรรเสริญพระองค์ท่ามกลางประชาชาติทั้งหลาย และร้องเพลงสรรเสริญพระนามของพระองค์’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 10, 'และมีคํากล่าวอีกว่า ‘ประชาชาติทั้งหลายเอ๋ย จงชื่นชมยินดีกับประชาชนของพระองค์’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 11, 'แล้วยังมีคํากล่าวอีกว่า ‘ประชาชาติทั้งปวงเอ๋ย จงสรรเสริญองค์พระผู้เป็นเจ้าเถิด และให้ชนชาติทั้งหลายยกย่องพระองค์’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 12, 'และอิสยาห์กล่าวอีกว่า ‘รากแห่งเจสซีจะมา คือผู้จะทรงบังเกิดมาครอบครองบรรดาประชาชาติ ประชาชาติทั้งหลายจะวางใจในพระองค์’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 13, 'ขอพระเจ้าแห่งความหวังทรงโปรดให้ท่านบริบูรณ์ด้วยความชื่นชมยินดีและสันติสุขในความเชื่อ เพื่อท่านจะได้เปี่ยมด้วยความหวังโดยฤทธิ์เดชแห่งพระวิญญาณบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 14, 'พี่น้องทั้งหลายของข้าพเจ้า ข้าพเจ้าเชื่อแน่ว่าท่านบริบูรณ์ด้วยการดีและเปี่ยมด้วยความรู้ทุกอย่าง สามารถเตือนสติกันและกันได้ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 15, 'แต่พี่น้องทั้งหลาย การที่ข้าพเจ้ากล้าเขียนบางเรื่องถึงท่านเพื่อเตือนความจําของท่าน ก็เพราะเหตุพระคุณที่พระเจ้าได้ทรงประทานแก่ข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 16, 'เพื่อให้ข้าพเจ้าเป็นผู้รับใช้ของพระเยซูคริสต์ไปยังคนต่างชาติ โดยรับใช้ฝ่ายข่าวประเสริฐของพระเจ้า เพื่อการถวายพวกต่างชาติทั้งหลายนั้นจะได้เป็นที่ชอบพระทัย คือเป็นที่แยกตั้งไว้โดยพระวิญญาณบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 17, 'เหตุฉะนั้นในพระเยซูคริสต์ข้าพเจ้ามีสิ่งที่จะอวดได้ฝ่ายพระราชกิจของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 18, 'เพราะว่าข้าพเจ้าไม่กล้าจะอ้างสิ่งใดนอกจากสิ่งซึ่งพระคริสต์ได้ทรงกระทํา โดยทรงใช้ข้าพเจ้าทางคําสอนและกิจการ เพื่อจะให้คนต่างชาติเชื่อฟัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 19, 'คือด้วยหมายสําคัญและการมหัศจรรย์อันทรงฤทธิ์ ในฤทธิ์เดชแห่งพระวิญญาณของพระเจ้า จนข้าพเจ้าได้ประกาศข่าวประเสริฐของพระคริสต์อย่างถ้วนถี่ ตั้งแต่กรุงเยรูซาเล็มอ้อมไปยังเมืองอิลลีริคุม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 20, 'อันที่จริงข้าพเจ้าได้ตั้งเป้าไว้อย่างนี้ว่า จะประกาศข่าวประเสริฐในที่ซึ่งไม่เคยมีใครออกพระนามพระคริสต์มาก่อน เพื่อข้าพเจ้าจะได้ไม่ก่อขึ้นบนรากฐานที่คนอื่นได้วางไว้ก่อนแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 21, 'ตามที่มีคําเขียนไว้ว่า ‘คนที่ไม่เคยได้รับคําบอกเล่าเรื่องพระองค์ก็จะได้เห็น และคนที่ไม่เคยได้ฟังจะได้เข้าใจ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 22, 'นี่คือเหตุที่ขัดขวางข้าพเจ้าไว้ไม่ให้มาหาท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 23, 'แต่เดี๋ยวนี้ข้าพเจ้าไม่มีกิจที่จะต้องอยู่ในแว่นแคว้นเหล่านี้ต่อไป ข้าพเจ้ามีความปรารถนาหลายปีแล้วที่จะมาหาท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 24, 'เมื่อข้าพเจ้าจะไปประเทศสเปน ข้าพเจ้าจะแวะมาหาท่านทั้งหลาย เพราะข้าพเจ้าหวังว่าจะได้พบท่านขณะที่ไปตามทางนั้น และเมื่อได้รับความบันเทิงใจกับท่านทั้งหลายบ้างแล้ว ข้าพเจ้าจะได้ลาท่านไปตามทาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 25, 'ขณะนี้ข้าพเจ้าจะขึ้นไปยังกรุงเยรูซาเล็ม เพื่อช่วยสงเคราะห์วิสุทธิชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 26, 'เพราะว่าพวกศิษย์ในแคว้นมาซิโดเนียและแคว้นอาคายาเห็นชอบที่จะถวายทรัพย์ ส่งไปให้แก่วิสุทธิชนที่ยากจนในกรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 27, 'พวกศิษย์เหล่านั้นพอใจที่จะทําเช่นนั้นจริงๆและพวกเขาก็เป็นหนี้วิสุทธิชนเหล่านั้นด้วย เพราะว่าถ้าเขาได้รับคนต่างชาติเข้าส่วนในการฝ่ายจิตวิญญาณ ก็เป็นการสมควรที่พวกต่างชาตินั้นจะได้ปรนนิบัติศิษย์เหล่านั้นด้วยสิ่งของฝ่ายเนื้อหนัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 28, 'เหตุฉะนั้น เมื่อข้าพเจ้าไปส่งผลทานนั้นมอบให้แก่พวกเขาเสร็จเรียบร้อยแล้ว ข้าพเจ้าก็จะไปประเทศสเปนผ่านตําบลที่ท่านอยู่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 29, 'และข้าพเจ้ารู้แน่ว่าเมื่อข้าพเจ้ามาหาท่านนั้น ข้าพเจ้าจะมาพร้อมด้วยพระพรอันบริบูรณ์ของข่าวประเสริฐแห่งพระคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 30, 'พี่น้องทั้งหลาย โดยเห็นแก่พระเยซูคริสต์เจ้าและโดยเห็นแก่ความรักของพระวิญญาณ ข้าพเจ้าจึงวิงวอนขอให้ท่านช่วยอธิษฐานพระเจ้าด้วยใจร้อนรนเพื่อข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 31, 'เพื่อให้ข้าพเจ้าพ้นจากมือคนในประเทศยูเดียที่ไม่เชื่อ และเพื่อให้การปรนนิบัติเนื่องด้วยผลทานซึ่งข้าพเจ้านําไปยังกรุงเยรูซาเล็มเป็นที่พอใจของวิสุทธิชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 32, 'เพื่อข้าพเจ้าจะได้มาหาท่านตามชอบพระทัยพระเจ้า ด้วยความชื่นชมยินดีและมีความเบิกบานแจ่มใสที่ได้พบท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 33, 'บัดนี้ขอพระเจ้าแห่งสันติสุขจงสถิตอยู่กับท่านทั้งหลายเถิด เอเมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 1, 'ข้าพเจ้าขอฝากน้องสาวของเราไว้กับท่าน คือเฟบีผู้เป็นผู้รับใช้ในคริสตจักรที่อยู่เมืองเคนเครีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 2, 'ขอท่านรับนางไว้ในองค์พระผู้เป็นเจ้าตามสมควรแก่วิสุทธิชน และขอให้ท่านช่วยนางในทุกสิ่งที่นางต้องการ เพราะนางได้ช่วยสงเคราะห์คนหลายคนรวมทั้งข้าพเจ้าด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 3, 'ขอฝากความคิดถึงมายังปริสสิลลาและอาควิลลา ผู้ร่วมงานกับข้าพเจ้าในพระเยซูคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 4, 'ผู้ซึ่งได้ยอมพลีชีวิตของเขาเพื่อป้องกันชีวิตของข้าพเจ้า ข้าพเจ้าขอขอบคุณเขาทั้งสองและมิใช่ข้าพเจ้าคนเดียว แต่คริสตจักรทุกแห่งของพวกต่างชาติก็ขอบคุณเขาด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 5, 'และขอฝากความคิดถึงมายังคริสตจักรที่อยู่ในบ้านเขาด้วย ขอฝากความคิดถึงมายังเอเปเนทัสที่รักของข้าพเจ้า ผู้เป็นคนแรกที่เข้ามาเชื่อในพระคริสต์ในแคว้นอาคายา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 6, 'ขอฝากความคิดถึงมายังมารีย์ผู้ได้ตรากตรําทํางานหนักเพื่อเราทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 7, 'ขอฝากความคิดถึงมายังอันโดรนิคัสกับยูนีอัสผู้เป็นญาติของข้าพเจ้า และได้ถูกจองจําร่วมกับข้าพเจ้า เขาเป็นคนมีชื่อเสียงดีในหมู่อัครสาวก ทั้งได้อยู่ในพระคริสต์ก่อนข้าพเจ้าด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 8, 'ขอฝากความคิดถึงมายังอัมพลีอัสที่รักของข้าพเจ้าในองค์พระผู้เป็นเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 9, 'ขอฝากความคิดถึงมายังอูรบานัสผู้ร่วมงานกับเราในพระคริสต์ และมายังสทาคิสที่รักของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 10, 'ขอฝากความคิดถึงมายังอาเป็ลเลสผู้เป็นที่พอพระทัยของพระคริสต์ ขอฝากความคิดถึงมายังคนในครัวเรือนของอาริสโทบูลัส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 11, 'ขอฝากความคิดถึงมายังเฮโรดิโอนญาติของข้าพเจ้า ขอฝากความคิดถึงมายังคนในครัวเรือนนารซิสสัสที่อยู่ในองค์พระผู้เป็นเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 12, 'ขอฝากความคิดถึงมายังตรีเฟนาและตรีโฟสาผู้ปฏิบัติงานในฝ่ายองค์พระผู้เป็นเจ้า ขอฝากความคิดถึงมายังเปอร์ซิสที่รักผู้ได้ปฏิบัติงานมากมายฝ่ายองค์พระผู้เป็นเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 13, 'ขอฝากความคิดถึงมายังรูฟัสผู้ที่ทรงเลือกไว้ในฝ่ายองค์พระผู้เป็นเจ้า และมารดาของเขาและมารดาข้าพเจ้าด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 14, 'ขอฝากความคิดถึงมายังอาสินครีทัส ฟเลโกน เฮอร์มาส ปัทโรบัส เฮอร์เมส และบรรดาพี่น้องที่อยู่กับเขาเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 15, 'ขอฝากความคิดถึงมายังฟีโลโลกัส ยูเลีย และเนเรอัสกับน้องสาวของเขาและโอลิมปัสกับบรรดาวิสุทธิชนที่อยู่กับคนเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 16, 'จงต้อนรับกันด้วยธรรมเนียมจุบอันบริสุทธิ์ บรรดาคริสตจักรของพระคริสต์ขอฝากความคิดถึงมายังท่านทั้งหลายด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 17, 'พี่น้องทั้งหลาย ข้าพเจ้าจึงขอวิงวอนท่าน ให้สังเกตดูคนเหล่านั้นที่ก่อเหตุทะเลาะวิวาทกันและทําให้คนอื่นหลงไป ซึ่งเป็นการผิดคําสอนที่ท่านทั้งหลายได้เรียนมา จงเมินหน้าจากคนเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 18, 'เพราะว่าคนเหล่านั้นไม่ได้ปรนนิบัติพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเรา แต่ได้ปรนนิบัติท้องของตัวเอง และได้ล่อลวงคนซื่อให้หลงด้วยคําดีคําอ่อนหวาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 19, 'การซึ่งท่านทั้งหลายได้เชื่อฟังก็เลื่องลือไปถึงคนทั้งปวงแล้ว ข้าพเจ้าจึงมีความยินดีเพราะท่านทั้งหลาย แต่ข้าพเจ้าใคร่ให้ท่านทั้งหลายเป็นคนฉลาดฝ่ายการดี และให้เป็นคนโง่ฝ่ายการชั่ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 20, 'ไม่ช้าพระเจ้าแห่งสันติสุขจะทรงปราบซาตานให้ยับเยินลงใต้ฝ่าเท้าของท่านทั้งหลาย ขอพระคุณของพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเราจงอยู่กับท่านทั้งหลายเถิด เอเมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 21, 'ทิโมธีผู้ร่วมงานกับข้าพเจ้า ลูสิอัส ยาโสน และโสสิปาเทอร์ บรรดาญาติของข้าพเจ้า ฝากความคิดถึงมายังท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 22, 'ข้าพเจ้าเทอร์ทีอัส ผู้เขียนจดหมายฉบับนี้ ขอฝากความคิดถึงมายังท่านทั้งหลายในองค์พระผู้เป็นเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 23, 'กายอัสเจ้าของบ้านผู้เลี้ยงดูข้าพเจ้า และเป็นผู้บํารุงคริสตจักรทั้งหมดฝากความคิดถึงมายังท่าน เอรัสทัสสมุหบัญชีของเมือง และควารทัสซึ่งเป็นพี่น้องฝากความคิดถึงมายังท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 24, 'ขอพระคุณแห่งพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเรา จงอยู่กับท่านทั้งหลายเถิด เอเมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 25, 'บัดนี้จงถวายพระเกียรติแด่พระองค์ผู้ทรงฤทธิ์สามารถให้ท่านทั้งหลายตั้งมั่นคง ตามข่าวประเสริฐซึ่งข้าพเจ้าได้ประกาศนั้น และตามที่ได้ประกาศเรื่องพระเยซูคริสต์ ตามการเปิดเผยข้อความอันลึกลับซึ่งได้ปิดบังไว้ตั้งแต่สร้างโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 26, 'แต่มาบัดนี้ได้เปิดเผยให้ปรากฏแล้ว และโดยพระคัมภีร์ของพวกศาสดาพยากรณ์ ตามซึ่งพระเจ้าผู้ทรงดํารงถาวรได้ทรงบัญญัติไว้ ได้เปิดเผยออกให้ประชาชาติทั้งปวงเห็นแจ้งเพื่อเขาจะได้เชื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 27, 'โดยพระเยซูคริสต์ ขอสง่าราศีมีแด่พระเจ้าผู้ทรงสัพพัญญูแต่องค์เดียว สืบๆไปเป็นนิตย์ เอเมน [เขียนถึงชาวโรมจากเมืองโครินธ์ และส่งโดยเฟบี ผู้เป็นผู้รับใช้ในคริสตจักรที่อยู่เมืองเคนเครีย]');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 1, 'เปาโล ผู้ซึ่งพระเจ้าได้ทรงเรียกให้เป็นอัครสาวกของพระเยซูคริสต์ตามพระประสงค์ของพระเจ้า และโสสเธเนสผู้เป็นพี่น้องของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 2, 'เรียน คริสตจักรของพระเจ้าที่เมืองโครินธ์ ผู้ได้รับการชําระให้บริสุทธิ์แล้วในพระเยซูคริสต์ ซึ่งพระองค์ได้ทรงเรียกให้เป็นวิสุทธิชน ด้วยกันกับคนทั้งปวงในทุกตําบลที่ออกพระนามพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเราและของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 3, 'ขอพระคุณและสันติสุขจากพระเจ้าพระบิดาของเราและจากพระเยซูคริสต์เจ้า จงดํารงอยู่กับท่านทั้งหลายเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 4, 'ข้าพเจ้าขอบพระคุณพระเจ้าของข้าพเจ้าในเรื่องท่านทั้งหลายเสมอ เพราะพระคุณของพระเจ้าซึ่งทรงประทานแก่ท่านทั้งหลายโดยพระเยซูคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 5, 'เพราะท่านทั้งหลายพรั่งพร้อมด้วยทุกสิ่งทุกอย่างโดยพระองค์ คือพร้อมด้วยวาจาและความรู้ทุกอย่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 6, 'ด้วยว่าพยานเรื่องพระคริสต์นั้นเป็นที่รับรองแน่นอนในพวกท่านแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 7, 'เพื่อว่าท่านทั้งหลายจึงมิได้ขาดของประทานเลย ในขณะที่ท่านรอคอยการเสด็จมาของพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 8, 'พระองค์จะทรงให้ท่านมั่นคงอยู่จนถึงที่สุด เพื่อให้ท่านปราศจากที่ติในวันของพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 9, 'พระเจ้าทรงสัตย์ซื่อ พระองค์ได้ทรงเรียกท่านให้สัมพันธ์สนิทกับพระบุตรของพระองค์ คือพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 10, 'พี่น้องทั้งหลาย ข้าพเจ้าจึงวิงวอนท่านในพระนามของพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเรา ขอให้ท่านเห็นพร้อมกันในทางวาจา และไม่มีการแตกแยกกันระหว่างพวกท่าน แต่ขอให้ท่านเป็นน้ําหนึ่งใจเดียวกันในทางความคิดและตัดสินอย่างเดียวกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 11, 'พี่น้องทั้งหลายของข้าพเจ้า คนในครอบครัวของนางคะโลเอได้เล่าเรื่องของท่านให้ข้าพเจ้าฟังว่า เกิดมีการทุ่มเถียงกันในระหว่างพวกท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 12, 'เดี๋ยวนี้ข้าพเจ้าหมายความว่า พวกท่านต่างก็กล่าวว่า “ข้าพเจ้าเป็นศิษย์เปาโล” หรือ “ข้าพเจ้าเป็นศิษย์อปอลโล” หรือ “ข้าพเจ้าเป็นศิษย์เคฟาส” หรือ “ข้าพเจ้าเป็นศิษย์พระคริสต์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 13, 'พระคริสต์แบ่งออกเป็นหลายองค์แล้วหรือ เขาได้ตรึงเปาโลเพื่อท่านทั้งหลายหรือ ท่านได้รับบัพติศมาในนามของเปาโลหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 14, 'ข้าพเจ้าขอบพระคุณพระเจ้าที่ข้าพเจ้ามิได้ให้บัพติศมาแก่ผู้หนึ่งผู้ใดในพวกท่าน เว้นแต่คริสปัสและกายอัส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 15, 'ดังนั้น จึงไม่มีผู้ใดกล่าวได้ว่า ข้าพเจ้าได้ทําพิธีบัพติศมาในนามของข้าพเจ้าเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 16, 'ข้าพเจ้าได้ให้บัพติศมาแก่ครอบครัวของสเทฟานัสด้วย แต่นอกจากคนเหล่านั้นแล้ว ข้าพเจ้าไม่ทราบว่าข้าพเจ้าได้ให้บัพติศมาแก่ผู้ใดอีกบ้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 17, 'เพราะว่าพระคริสต์มิได้ทรงใช้ข้าพเจ้าไปเพื่อให้เขารับบัพติศมา แต่เพื่อให้ประกาศข่าวประเสริฐ แต่มิใช่ด้วยชั้นเชิงฉลาดในการพูด เกรงว่าเรื่องกางเขนของพระคริสต์จะหมดฤทธิ์เดช');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 18, 'คนทั้งหลายที่กําลังจะพินาศก็เห็นว่าการประกาศเรื่องกางเขนเป็นเรื่องโง่ แต่พวกเราที่รอดเห็นว่าเป็นฤทธานุภาพของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 19, 'เพราะมีคําเขียนไว้แล้วว่า ‘เราจะทําลายสติปัญญาของคนมีปัญญา และจะทําให้ความเข้าใจของคนที่เข้าใจสูญสิ้นไป’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 20, 'คนมีปัญญาอยู่ที่ไหน บัณฑิตอยู่ที่ไหน นักโต้ปัญหาแห่งยุคนี้อยู่ที่ไหน พระเจ้ามิได้ทรงกระทําปัญญาของโลกนี้ให้โฉดเขลาไปแล้วหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 21, 'เพราะตามเรื่องที่เป็นพระสติปัญญาของพระเจ้าแล้ว โลกจะรู้จักพระเจ้าโดยปัญญาไม่ได้ พระเจ้าทรงพอพระทัยที่จะช่วยคนที่เชื่อให้รอดโดยการเทศนาที่โง่เขลานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 22, 'ด้วยว่าพวกยิวเรียกร้องหมายสําคัญและพวกกรีกเสาะหาปัญญา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 23, 'แต่พวกเราประกาศเรื่องพระคริสต์ผู้ทรงถูกตรึงที่กางเขนนั้น อันเป็นสิ่งที่ให้พวกยิวสะดุด และพวกกรีกถือว่าเป็นเรื่องโง่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 24, 'แต่สําหรับผู้ที่พระเจ้าทรงเรียกนั้น ทั้งพวกยิวและพวกกรีกต่างถือว่า พระคริสต์ทรงเป็นฤทธานุภาพและพระปัญญาของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 25, 'เพราะความเขลาของพระเจ้ายังมีปัญญายิ่งกว่าปัญญาของมนุษย์ และความอ่อนแอของพระเจ้าก็ยังเข้มแข็งยิ่งกว่ากําลังของมนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 26, 'พี่น้องทั้งหลาย จงพิจารณาดูว่า พวกท่านที่พระเจ้าได้ทรงเรียกมานั้นเป็นคนพวกไหน มีน้อยคนที่โลกนิยมว่ามีปัญญา มีน้อยคนที่มีอํานาจ มีน้อยคนที่มีตระกูลสูง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 27, 'แต่พระเจ้าได้ทรงเลือกสิ่งที่โลกถือว่าโง่เขลา เพื่อจะทําให้คนมีปัญญาอับอาย และพระเจ้าได้ทรงเลือกสิ่งที่โลกถือว่าอ่อนแอ เพื่อทําให้คนที่แข็งแรงอับอาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 28, 'พระเจ้าได้ทรงเลือกสิ่งที่โลกถือว่าต่ําต้อย และสิ่งที่ถูกดูหมิ่น ทั้งทรงเลือกสิ่งเหล่านั้นซึ่งยังมิได้เกิดเป็นตัวจริงด้วย เพื่อจะได้ทําลายสิ่งซึ่งเป็นตัวจริงอยู่แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 29, 'เพื่อมิให้เนื้อหนังใดๆอวดต่อพระพักตร์พระองค์ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 30, 'โดยพระองค์ท่านจึงอยู่ในพระเยซูคริสต์ เพราะพระเจ้าทรงตั้งพระองค์ให้เป็นปัญญา ความชอบธรรม การแยกตั้งไว้ และการไถ่โทษ สําหรับเราทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 31, 'เพื่อให้เป็นไปตามที่เขียนว่า ‘ให้ผู้โอ้อวด อวดองค์พระผู้เป็นเจ้า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 1, 'พี่น้องทั้งหลาย เมื่อข้าพเจ้ามาหาท่าน ข้าพเจ้ามิได้มาเพื่อประกาศสักขีพยานของพระเจ้าแก่ท่านทั้งหลาย ด้วยถ้อยคําอันไพเราะหรือด้วยสติปัญญา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 2, 'เพราะข้าพเจ้าตั้งใจว่าจะไม่แสดงความรู้เรื่องใดๆในหมู่พวกท่านเลยเว้นแต่เรื่องพระเยซูคริสต์ และการที่พระองค์ทรงถูกตรึงที่กางเขน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 3, 'และเมื่อข้าพเจ้าอยู่กับท่านทั้งหลาย ข้าพเจ้าก็อ่อนกําลัง มีความกลัวและตัวสั่นเป็นอันมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 4, 'คําพูดและคําเทศนาของข้าพเจ้า ไม่ใช่คําที่เกลี้ยกล่อมด้วยสติปัญญาของมนุษย์ แต่เป็นคําซึ่งได้แสดงพระวิญญาณและพระเดชานุภาพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 5, 'เพื่อความเชื่อของท่านจะไม่ได้อาศัยสติปัญญาของมนุษย์ แต่อาศัยฤทธิ์เดชของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 6, 'เรากล่าวถึงเรื่องปัญญาในหมู่คนที่เป็นผู้ใหญ่แล้วก็จริง แต่มิใช่เรื่องปัญญาของโลกนี้ หรือเรื่องปัญญาของอํานาจครอบครองในโลกนี้ซึ่งจะเสื่อมสูญไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 7, 'แต่เรากล่าวถึงเรื่องพระปัญญาของพระเจ้าซึ่งเป็นข้อลึกลับ คือพระปัญญาซึ่งทรงซ่อนไว้นั้น ซึ่งพระเจ้าได้ทรงกําหนดไว้ก่อนสร้างโลกให้เป็นสง่าราศีแก่เรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 8, 'ไม่มีอํานาจครอบครองใดๆในโลกนี้ได้รู้จักพระปัญญานั้น เพราะว่าถ้ารู้แล้วจะมิได้เอาองค์พระผู้เป็นเจ้าแห่งสง่าราศีตรึงไว้ที่กางเขน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 9, 'ดังที่มีเขียนไว้แล้วว่า ‘สิ่งที่ตาไม่เห็น หูไม่ได้ยิน และไม่เคยได้เข้าไปในใจมนุษย์ คือสิ่งที่พระเจ้าได้ทรงจัดเตรียมไว้สําหรับคนที่รักพระองค์’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 10, 'พระเจ้าได้ทรงสําแดงสิ่งเหล่านั้นแก่เราทางพระวิญญาณของพระองค์ เพราะว่าพระวิญญาณทรงหยั่งรู้ทุกสิ่ง แม้เป็นความล้ําลึกของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 11, 'อันความคิดของมนุษย์นั้นไม่มีผู้ใดหยั่งรู้ได้ เว้นแต่จิตวิญญาณของมนุษย์ผู้นั้นเองฉันใด พระดําริของพระเจ้าก็ไม่มีใครหยั่งรู้ได้ เว้นแต่พระวิญญาณของพระเจ้าฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 12, 'บัดนี้เราทั้งหลายจึงไม่ได้รับวิญญาณของโลก แต่ได้รับพระวิญญาณซึ่งมาจากพระเจ้า เพื่อเราทั้งหลายจะได้รู้ถึงสิ่งต่างๆที่พระเจ้าได้ทรงโปรดประทานแก่เรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 13, 'คือสิ่งเหล่านั้นที่เราได้กล่าวด้วยถ้อยคําซึ่งมิใช่ปัญญาของมนุษย์สอนไว้ แต่ด้วยถ้อยคําซึ่งพระวิญญาณบริสุทธิ์ได้ทรงสั่งสอน ซึ่งเปรียบเทียบสิ่งที่อยู่ฝ่ายจิตวิญญาณกับสิ่งซึ่งเป็นของจิตวิญญาณ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 14, 'แต่มนุษย์ธรรมดาจะรับสิ่งเหล่านั้นซึ่งเป็นของพระวิญญาณแห่งพระเจ้าไม่ได้ เพราะเขาเห็นว่าเป็นสิ่งโง่เขลา และเขาไม่สามารถเข้าใจได้ เพราะว่าจะเข้าใจสิ่งเหล่านั้นได้ก็ต้องสังเกตด้วยจิตวิญญาณ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 15, 'แต่มนุษย์ฝ่ายจิตวิญญาณสังเกตสิ่งสารพัดได้ แต่ไม่มีผู้ใดจะรู้จักใจคนนั้นได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 16, 'เพราะว่า ‘ใครเล่ารู้จักพระทัยขององค์พระผู้เป็นเจ้าเพื่อจะแนะนําสั่งสอนพระองค์ได้’ แต่เราก็มีพระทัยของพระคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 1, 'พี่น้องทั้งหลาย ข้าพเจ้าไม่อาจจะพูดกับท่านเหมือนพูดกับผู้ที่อยู่ฝ่ายจิตวิญญาณแล้วได้ แต่ต้องพูดกับท่านเหมือนคนที่อยู่ฝ่ายเนื้อหนัง เหมือนกับท่านเป็นทารกในพระคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 2, 'ข้าพเจ้าเลี้ยงท่านด้วยน้ํานมมิใช่ด้วยอาหารแข็ง เพราะว่าเมื่อก่อนนั้นท่านยังไม่สามารถรับและถึงแม้เดี๋ยวนี้ท่านก็ยังไม่สามารถ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 3, 'ด้วยว่าท่านยังอยู่ฝ่ายเนื้อหนัง เพราะว่าเมื่อท่านยังอิจฉากัน โต้เถียงกัน และแตกแยกกัน ท่านไม่ได้อยู่ฝ่ายเนื้อหนังหรือ และไม่ได้ดําเนินตามมนุษย์สามัญดอกหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 4, 'เพราะเมื่อคนหนึ่งกล่าวว่า “ข้าพเจ้าเป็นศิษย์ของเปาโล” และอีกคนหนึ่งกล่าวว่า “ข้าพเจ้าเป็นศิษย์ของอปอลโล” ท่านทั้งหลายมิได้อยู่ฝ่ายเนื้อหนังหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 5, 'เปาโลคือผู้ใด อปอลโลคือผู้ใด เขาเป็นผู้รับใช้มาแจ้งให้ท่านทั้งหลายเชื่อ ตามซึ่งองค์พระผู้เป็นเจ้าได้ทรงโปรดประทานแก่ทุกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 6, 'ข้าพเจ้าได้ปลูก อปอลโลได้รดน้ํา แต่พระเจ้าทรงทําให้เติบโต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 7, 'เพราะฉะนั้น คนที่ปลูกและคนที่รดน้ําไม่สําคัญอะไร แต่พระเจ้าผู้ทรงโปรดให้เติบโตนั้นต่างหากที่สําคัญ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 8, 'ดังนั้นคนที่ปลูกและคนที่รดน้ําก็เป็นพวกเดียวกัน แต่ทุกคนก็จะได้ค่าจ้างของตนตามการที่ตนได้กระทําไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 9, 'เพราะว่าเราทั้งหลายเป็นผู้ร่วมทําการด้วยกันกับพระเจ้า ท่านทั้งหลายเป็นไร่นาของพระเจ้า และเป็นตึกของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 10, 'โดยพระคุณของพระเจ้าซึ่งได้ทรงโปรดประทานแก่ข้าพเจ้า ข้าพเจ้าได้วางรากลงแล้วเหมือนนายช่างผู้ชํานาญ และอีกคนหนึ่งก็มาก่อขึ้น ขอทุกคนจงระวังให้ดีว่าเขาจะก่อขึ้นมาอย่างไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 11, 'เพราะว่าผู้ใดจะวางรากอื่นอีกไม่ได้แล้ว นอกจากที่วางไว้แล้วคือพระเยซูคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 12, 'แล้วบนรากนั้นถ้าผู้ใดจะก่อขึ้นด้วยทองคํา เงิน เพชรพลอย ไม้ หญ้าแห้งหรือฟาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 13, 'การงานของแต่ละคนก็จะได้ปรากฏให้เห็น เพราะเวลาวันนั้นจะให้เห็นได้ชัดเจน เพราะว่าจะเห็นชัดได้ด้วยไฟ ไฟนั้นจะพิสูจน์ให้เห็นการงานของแต่ละคนว่าเป็นอย่างไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 14, 'ถ้าการงานของผู้ใดที่ก่อขึ้นทนอยู่ได้ ผู้นั้นก็จะได้ค่าตอบแทน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 15, 'ถ้าการงานของผู้ใดถูกเผาไหม้ไป ผู้นั้นก็จะขาดค่าตอบแทนแต่ตัวเขาเองจะรอด แต่เหมือนดังรอดจากไฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 16, 'ท่านทั้งหลายไม่รู้หรือว่าท่านเป็นวิหารของพระเจ้า และพระวิญญาณของพระเจ้าสถิตอยู่ในท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 17, 'ถ้าผู้ใดทําลายวิหารของพระเจ้า พระเจ้าจะทรงทําลายผู้นั้น เพราะวิหารของพระเจ้าเป็นที่บริสุทธิ์และท่านทั้งหลายเป็นวิหารนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 18, 'อย่าให้ผู้ใดหลอกลวงตัวเอง ถ้าผู้ใดในพวกท่านคิดว่าตัวเป็นคนมีปัญญาตามหลักของยุคนี้ จงให้ผู้นั้นยอมเป็นคนโง่จึงจะเป็นคนมีปัญญาได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 19, 'เพราะว่าปัญญาของโลกนี้เป็นความโง่เขลาจําเพาะพระเจ้า ด้วยมีคําเขียนไว้แล้วว่า ‘พระองค์ทรงจับคนที่มีปัญญาด้วยอุบายของเขาเอง’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 20, 'และยังมีอีกว่า ‘องค์พระผู้เป็นเจ้าทรงทราบความคิดของคนมีปัญญาว่าเป็นเพียงแต่ไร้สาระ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 21, 'เหตุฉะนั้นอย่าให้ผู้ใดยกมนุษย์ขึ้นอวด ด้วยว่าสิ่งสารพัดเป็นของท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 22, 'จะเป็นเปาโล อปอลโล เคฟาส โลก ชีวิต ความตาย สิ่งในปัจจุบันนี้ หรือสิ่งในอนาคต สิ่งสารพัดนั้นเป็นของท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 23, 'และท่านทั้งหลายเป็นของพระคริสต์ และพระคริสต์ทรงเป็นของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 1, 'ให้ทุกคนถือว่าเราเป็นผู้รับใช้ของพระคริสต์ และเป็นผู้อารักขาสิ่งลึกลับของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 2, 'ยิ่งกว่านี้ฝ่ายผู้อารักขาเหล่านั้นต้องเป็นคนที่สัตย์ซื่อทุกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 3, 'สําหรับข้าพเจ้าการที่ท่านทั้งหลายหรือมนุษย์ผู้ใดจะตัดสินตัวข้าพเจ้า ข้าพเจ้าถือว่าเป็นเรื่องเล็กน้อย ถึงแม้ข้าพเจ้าเองก็มิได้ตัดสินตัวข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 4, 'เพราะข้าพเจ้าไม่รู้ว่าข้าพเจ้ามีความผิดสถานใด ถึงกระนั้นข้าพเจ้าก็ไม่พ้นการพิพากษา ท่านผู้ทรงพิพากษาตัวข้าพเจ้าคือองค์พระผู้เป็นเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 5, 'เหตุฉะนั้นท่านอย่าตัดสินสิ่งใดก่อนที่จะถึงเวลาจนกว่าองค์พระผู้เป็นเจ้าจะเสด็จมา พระองค์จะทรงเปิดเผยความลับที่ซ่อนอยู่ในความมืดให้แจ่มกระจ่าง และจะทรงเผยความในใจของคนทั้งปวงด้วย เมื่อนั้นทุกคนจะได้รับคําชมเชยจากพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 6, 'พี่น้องทั้งหลาย สิ่งเหล่านั้นที่ข้าพเจ้าได้นํามากล่าวเปรียบเทียบถึงตัวข้าพเจ้าและอปอลโล ก็เพื่อประโยชน์ของท่านทั้งหลาย เพื่อให้ท่านทั้งหลายเรียนแบบของเรา มิให้ยกย่องคนหนึ่งคนใดเกินกว่าที่เขียนบอกไว้แล้ว มิให้ยกคนหนึ่งคนใดข่มผู้อื่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 7, 'ผู้ใดเล่ากระทําให้ท่านวิเศษกว่าคนอื่น ท่านมีอะไรที่ท่านมิได้รับมา ก็เมื่อท่านได้รับมา เหตุไฉนท่านจึงโอ้อวดเหมือนกับว่าท่านมิได้รับเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 8, 'ท่านทั้งหลายอิ่มหนําแล้วหนอ ท่านมั่งมีแล้วหนอ ท่านได้ครองเหมือนกษัตริย์โดยไม่มีเราร่วมด้วยแล้วหนอ ข้าพเจ้ามีความปรารถนาให้ท่านทั้งหลายได้ขึ้นครองจริงๆเพื่อเราจะได้ขึ้นครองกับท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 9, 'เพราะข้าพเจ้าเห็นว่าพระเจ้าได้ทรงตั้งเราผู้เป็นอัครสาวกไว้ในที่สุดปลาย เหมือนผู้ที่ได้ถูกปรับโทษให้ถึงตาย เพราะว่าโลกคือทั้งทูตสวรรค์และมนุษย์มองดูเราด้วยความพิศวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 10, 'เราทั้งหลายเป็นคนเขลาเพราะเห็นแก่พระคริสต์ และท่านทั้งหลายเป็นคนมีปัญญาในพระคริสต์ เราทั้งหลายมีกําลังน้อยแต่ท่านทั้งหลายมีกําลังมาก ท่านทั้งหลายมีเกียรติยศแต่เราทั้งหลายเป็นคนอัปยศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 11, 'จนถึงเวลานี้เราก็ทั้งหิวและกระหาย เปลือยเปล่าและถูกโบยตี และไม่มีที่อาศัยเป็นหลักแหล่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 12, 'เราทําการหนักด้วยมือของเราเอง เมื่อถูกด่าเราก็อวยพร เมื่อถูกข่มเหงเราก็ทนเอา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 13, 'เมื่อถูกใส่ร้ายเราก็อ้อนวอน เรากลายเป็นเหมือนกากเดนของโลกและเหมือนราคีของสิ่งสารพัดจนถึงบัดนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 14, 'ข้าพเจ้ามิได้เขียนข้อความเหล่านี้เพื่อจะให้ท่านได้อาย แต่เขียนเพื่อเตือนสติในฐานะที่ท่านเป็นลูกที่รักของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 15, 'เพราะในพระคริสต์ถึงแม้ท่านมีครูสักหมื่นคนแต่ท่านจะมีบิดาหลายคนก็หามิได้ เพราะว่าในพระเยซูคริสต์ข้าพเจ้าได้ให้กําเนิดแก่ท่านโดยข่าวประเสริฐ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 16, 'เหตุฉะนั้น ข้าพเจ้าจึงขอให้ท่านทําตามอย่างข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 17, 'เพราะเหตุนี้ข้าพเจ้าจึงได้ใช้ทิโมธีลูกที่รักของข้าพเจ้า ซึ่งเป็นคนสัตย์ซื่อในองค์พระผู้เป็นเจ้าให้มาหาท่าน เพื่อนําท่านให้ระลึกถึงแบบการประพฤติของข้าพเจ้าในพระคริสต์ ตามที่ข้าพเจ้าสอนอยู่ในทุกคริสตจักร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 18, 'แต่บางคนทําผยองราวกับข้าพเจ้าจะไม่มาหาท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 19, 'แต่ถ้าองค์พระผู้เป็นเจ้าทรงโปรด ข้าพเจ้าจะมาหาท่านในไม่ช้านี้ และข้าพเจ้าจะหยั่งดู มิใช่ถ้อยคําของคนที่ผยองเหล่านั้นแต่จะหยั่งดูฤทธิ์อํานาจของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 20, 'เพราะว่าอาณาจักรของพระเจ้ามิใช่เรื่องของคําพูดแต่เป็นเรื่องฤทธิ์เดช');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 21, 'ท่านจะเอาอย่างไร จะให้ข้าพเจ้าถือไม้เรียวมาหาท่าน หรือจะให้ข้าพเจ้ามาด้วยความรักและด้วยใจอ่อนสุภาพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 1, 'มีข่าวเล่าลือว่าในพวกท่านมีการผิดประเวณี และการผิดประเวณีนั้นถึงแม้ในพวกต่างชาติก็ไม่มีเลย คือเรื่องมีว่าคนหนึ่งได้เอาภรรยาของบิดามาเป็นภรรยาของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 2, 'และพวกท่านยังผยองแทนที่จะเป็นทุกข์เป็นร้อน ที่จะตัดคนที่กระทําผิดเช่นนี้ออกเสียจากพวกท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 3, 'แม้ว่าตัวข้าพเจ้าไม่ได้อยู่กับพวกท่าน แต่ใจของข้าพเจ้าก็อยู่ด้วย ข้าพเจ้าได้ตัดสินลงโทษคนที่ได้กระทําผิดเช่นนั้นเสมือนว่าข้าพเจ้าได้อยู่ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 4, 'ในพระนามของพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเรา เมื่อท่านทั้งหลายประชุมกันและใจของข้าพเจ้าร่วมอยู่ด้วย พร้อมทั้งฤทธิ์เดชของพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 5, 'พวกท่านจงมอบคนนั้นไว้ให้ซาตานทําลายเนื้อหนังเสีย เพื่อให้จิตวิญญาณของเขารอดในวันของพระเยซูเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 6, 'การที่ท่านอวดอ้างนั้นไม่ดีเลย ท่านไม่รู้หรือว่าเชื้อขนมเพียงนิดเดียวย่อมทําให้แป้งดิบฟูทั้งก้อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 7, 'ดังนั้นจงชําระเชื้อเก่าเสียเพื่อท่านจะได้เป็นแป้งดิบก้อนใหม่เหมือนขนมปังไร้เชื้อ เพราะพระคริสต์ผู้ทรงเป็นปัสกาของเรา ได้ถูกฆ่าบูชาเพื่อเราเสียแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 8, 'เหตุฉะนั้นให้เราถือปัสกานั้น มิใช่ด้วยเชื้อเก่าหรือด้วยเชื้อของความชั่วช้าเลวทราม แต่ด้วยขนมปังไร้เชื้อคือความจริงใจและความจริง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 9, 'ข้าพเจ้าได้เขียนจดหมายถึงท่านว่า อย่าคบกับคนที่ล่วงประเวณี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 10, 'แต่ซึ่งท่านจะคบคนชาวโลกนี้ที่เป็นคนล่วงประเวณี คนโลภ คนฉ้อโกง หรือคนถือรูปเคารพ ข้าพเจ้ามิได้ห้ามเสียทีเดียวเพราะว่าถ้าห้ามอย่างนั้นแล้ว ท่านก็ต้องออกไปเสียจากโลกนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 11, 'แต่บัดนี้ข้าพเจ้าเขียนบอกท่านว่าถ้าผู้ใดได้ชื่อว่าเป็นพี่น้องแล้ว แต่ยังล่วงประเวณี เป็นคนโลภ เป็นคนถือรูปเคารพ เป็นคนปากร้าย เป็นคนขี้เมา หรือเป็นคนฉ้อโกง อย่าคบกับคนอย่างนั้นแม้จะกินด้วยกันก็อย่าเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 12, 'ไม่ใช่หน้าที่ของข้าพเจ้าที่จะไปตัดสินลงโทษคนภายนอก ท่านจะต้องตัดสินลงโทษคนภายในมิใช่หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 13, 'ส่วนคนภายนอกนั้นพระเจ้าจะทรงตัดสินลงโทษ เหตุฉะนั้นจงกําจัดคนชั่วช้านั้นออกจากพวกท่านเสียเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 1, 'ในพวกท่านมีผู้ใดหรือ ถ้าเป็นความกับคนอื่น จะอาจไปว่าความกันต่อหน้าคนอธรรม และไม่ไปว่าต่อหน้าวิสุทธิชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 2, 'ท่านไม่รู้หรือว่าวิสุทธิชนจะพิพากษาโลก และถ้าพวกท่านจะพิพากษาโลก ท่านไม่สมควรจะพิพากษาความเรื่องเล็กน้อยที่สุดหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 3, 'ท่านไม่รู้หรือว่า เราจะต้องพิพากษาพวกทูตสวรรค์ ถ้าเช่นนั้นจะยิ่งเป็นการสมควรสักเท่าใดที่เราจะพิพากษาตัดสินความเรื่องของชีวิตนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 4, 'ฉะนั้นถ้าพวกท่านเป็นความกันเรื่องชีวิตนี้ ท่านจะตั้งคนที่คริสตจักรนับถือน้อยที่สุดให้ตัดสินหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 5, 'ข้าพเจ้ากล่าวดังนี้ก็เพื่อให้ท่านละอายใจ ในพวกท่านไม่มีสักคนหนึ่งหรือที่มีสติปัญญาสามารถชําระความระหว่างพี่น้อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 6, 'แต่พี่น้องกับพี่น้องต้องไปว่าความกันต่อหน้าคนที่ไม่เชื่ออย่างนั้นหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 7, 'เหตุฉะนั้นเพราะพวกท่านไปเป็นความกัน บัดนี้ท่านก็ตกจากระดับที่ควรแล้ว ทําไมท่านจึงไม่ทนต่อการร้ายซึ่งเขาทําแก่ท่าน ทําไมท่านจึงไม่ยอมถูกโกง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 8, 'แต่ท่านเองกลับทําร้ายกัน และโกงกันในระหว่างพวกพี่น้องของท่านเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 9, 'ท่านไม่รู้หรือว่าคนอธรรมจะไม่ได้รับอาณาจักรของพระเจ้าเป็นมรดก อย่าหลงเลย คนล่วงประเวณี คนถือรูปเคารพ คนผิดผัวเมียเขา คนนิสัยเหมือนผู้หญิงหรือคนที่เป็นกะเทย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 10, 'คนขโมย คนโลภ คนขี้เมา คนปากร้าย คนฉ้อโกง จะไม่ได้รับอาณาจักรของพระเจ้าเป็นมรดก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 11, 'แต่ก่อนมีบางคนในพวกท่านเป็นคนอย่างนั้น แต่ท่านได้รับทรงชําระแล้ว และได้ทรงแยกตั้งท่านไว้แล้ว แต่พระวิญญาณแห่งพระเจ้าของเราได้ทรงตั้งท่านให้เป็นผู้ชอบธรรมในพระนามของพระเยซูเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 12, 'ข้าพเจ้าทําสิ่งสารพัดได้ แต่ไม่ใช่ทุกสิ่งที่จะทําได้นั้นเป็นประโยชน์ ข้าพเจ้าทําสิ่งสารพัดได้ แต่ข้าพเจ้าไม่ยอมอยู่ใต้อํานาจของสิ่งใดเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 13, 'อาหารมีไว้สําหรับท้อง และท้องก็สําหรับอาหาร แต่พระเจ้าจะทรงให้ทั้งท้องและอาหารสิ้นสูญไป แล้วร่างกายนั้นไม่ได้มีไว้สําหรับการล่วงประเวณี แต่มีไว้สําหรับองค์พระผู้เป็นเจ้า และองค์พระผู้เป็นเจ้ามีไว้สําหรับร่างกาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 14, 'พระเจ้าได้ทรงชุบให้องค์พระผู้เป็นเจ้าเป็นขึ้นมาใหม่ และพระองค์จะทรงชุบให้เราทั้งหลายเป็นขึ้นมาใหม่โดยฤทธิ์เดชของพระองค์ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 15, 'ท่านไม่รู้หรือว่า ร่างกายของท่านเป็นอวัยวะของพระคริสต์ เมื่อเป็นเช่นนั้น จะให้ข้าพเจ้าเอาอวัยวะของพระคริสต์มาเป็นอวัยวะของหญิงแพศยาได้หรือ ขอพระเจ้าอย่ายอมให้เป็นเช่นนั้นเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 16, 'ท่านไม่รู้หรือว่าคนที่ผูกพันกับหญิงแพศยาก็เป็นกายอันเดียวกันกับหญิงนั้น เพราะพระองค์ได้ตรัสว่า ‘เขาทั้งสองจะเป็นเนื้ออันเดียวกัน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 17, 'แต่ส่วนคนที่ผูกพันกับองค์พระผู้เป็นเจ้า ก็เป็นอันเดียวกันกับพระองค์ฝ่ายจิตวิญญาณ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 18, 'จงหลีกเลี่ยงเสียจากการล่วงประเวณี ความบาปทุกอย่างที่มนุษย์กระทํานั้นเป็นบาปนอกกาย แต่คนที่ล่วงประเวณีนั้นทําผิดต่อร่างกายของตนเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 19, 'ท่านไม่รู้หรือว่า ร่างกายของท่านเป็นวิหารของพระวิญญาณบริสุทธิ์ ซึ่งสถิตอยู่ในท่าน ซึ่งท่านได้รับจากพระเจ้า ท่านไม่ใช่เจ้าของตัวท่านเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 20, 'พระเจ้าได้ทรงซื้อท่านไว้แล้วตามราคา เหตุฉะนั้นท่านจงถวายพระเกียรติแด่พระเจ้าด้วยร่างกายของท่าน และด้วยจิตวิญญาณของท่าน ซึ่งเป็นของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 1, 'แล้วเรื่องที่พวกท่านเขียนมาถึงข้าพเจ้านั้น ขอตอบว่า การที่ผู้ชายไม่ยุ่งเกี่ยวกับผู้หญิงเลยก็ดีแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 2, 'แต่เพื่อป้องกันการล่วงประเวณี ผู้ชายทุกคนควรมีภรรยาเป็นของตนและผู้หญิงทุกคนมีสามีเป็นของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 3, 'สามีพึงประพฤติต่อภรรยาตามควร และภรรยาก็พึงประพฤติต่อสามีตามควรเช่นเดียวกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 4, 'ภรรยาไม่มีอํานาจเหนือร่างกายของตน แต่สามีมีอํานาจเหนือร่างกายของภรรยา ทํานองเดียวกันสามีไม่มีอํานาจเหนือร่างกายของตน แต่ภรรยามีอํานาจเหนือร่างกายของสามี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 5, 'อย่าปฏิเสธการอยู่ร่วมกันเว้นแต่ได้ตกลงกันเป็นการชั่วคราว เพื่ออุทิศตัวในการถืออดอาหารและการอธิษฐาน แล้วจึงค่อยมาอยู่ร่วมกันอีก เพื่อมิให้ซาตานชักจูงให้ทําผิด เพราะตัวอดไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 6, 'ข้าพเจ้ากล่าวเช่นนี้โดยได้รับอนุญาต มิใช่เป็นพระบัญชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 7, 'ข้าพเจ้าปรารถนาที่จะให้ทุกคนเป็นเหมือนข้าพเจ้า แต่ทุกคนก็ได้รับของประทานจากพระเจ้าเหมาะกับตัว คนหนึ่งได้รับอย่างนี้ และอีกคนหนึ่งได้รับอย่างนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 8, 'เหตุฉะนั้นข้าพเจ้าขอกล่าวแก่คนที่ยังเป็นโสดและพวกหญิงม่ายว่า การที่เขาจะอยู่เหมือนข้าพเจ้าก็ดีแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 9, 'แต่ถ้าเขายั้งใจไม่ได้ก็จงแต่งงานเสียเถิด เพราะแต่งงานเสียก็ดีกว่ามีใจเร่าร้อนด้วยกามราคะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 10, 'ส่วนคนที่แต่งงานแล้วข้าพเจ้าขอสั่ง มิใช่ข้าพเจ้าสั่งเอง แต่องค์พระผู้เป็นเจ้าทรงบัญชาว่า อย่าให้ภรรยาทิ้งสามี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 11, 'แต่ถ้านางทิ้งสามีไปอย่าให้นางไปมีสามีใหม่ หรือไม่ก็ให้นางกลับมาคืนดีกับสามีเก่า และขออย่าให้สามีหย่าร้างภรรยาเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 12, 'ข้าพเจ้าขอกล่าวแก่คนอื่นๆนอกจากพวกนี้ (องค์พระผู้เป็นเจ้ามิได้ตรัส) ว่า ถ้าพี่น้องคนใดมีภรรยาที่ไม่เชื่อและนางพอใจที่จะอยู่กับสามี สามีก็ไม่ควรหย่านาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 13, 'ถ้าหญิงคนใดมีสามีที่ไม่เชื่อและสามีพอใจที่จะอยู่กับนาง นางก็ไม่ควรหย่าสามีนั้นเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 14, 'ด้วยว่าสามีที่ไม่เชื่อนั้นได้รับการทรงชําระให้บริสุทธิ์ทางภรรยา และภรรยาที่ไม่เชื่อก็ได้รับการทรงชําระให้บริสุทธิ์ทางสามี มิฉะนั้นลูกของท่านก็เป็นมลทิน แต่บัดนี้ลูกเหล่านั้นก็บริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 15, 'แต่ถ้าคนที่ไม่เชื่อจะแยกไป ก็จงให้เขาไปเถิด เรื่องเช่นนี้ไม่จําเป็นที่พี่น้องชายหญิงจะผูกมัดให้จําใจอยู่ด้วยกัน เพราะว่าพระเจ้าได้ทรงเรียกเราให้อยู่อย่างสงบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 16, 'โอ ท่านผู้เป็นภรรยา ไฉนท่านจะรู้ได้ว่าท่านจะช่วยสามีให้รอดได้หรือไม่ โอ ท่านผู้เป็นสามี ไฉนท่านจะรู้ได้ว่าท่านจะช่วยภรรยาให้รอดได้หรือไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 17, 'แต่ตามที่พระเจ้าได้ทรงประทานฐานะแก่แต่ละคนอย่างไร เมื่อองค์พระผู้เป็นเจ้าได้ทรงเรียกให้เขามาแล้ว ก็ให้เขาดํารงอยู่ในฐานะนั้น ข้าพเจ้าขอสั่งให้คริสตจักรทั้งหมดทําตามดังนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 18, 'มีชายคนใดที่พระเจ้าทรงเรียกเมื่อเขาได้เข้าสุหนัตแล้วหรือ อย่าให้เขากลับเป็นเหมือนคนที่ไม่ได้เข้าสุหนัต หรือมีชายคนใดที่พระเจ้าทรงเรียกเมื่อเขามิได้เข้าสุหนัตหรือ อย่าให้เขาเข้าสุหนัตเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 19, 'การเข้าสุหนัตไม่สําคัญอะไร และการไม่เข้าสุหนัตไม่สําคัญอะไร แต่การรักษาพระบัญญัติของพระเจ้านั้นสําคัญ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 20, 'ให้ทุกคนอยู่ในฐานะที่เขาอยู่เมื่อพระเจ้าทรงเรียกนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 21, 'พระเจ้าทรงเรียกท่านเมื่อยังเป็นทาสอยู่หรือ ก็อย่ากระวนกระวายเพราะการเป็นทาสนั้น แต่ถ้าท่านสามารถไถ่ตัวออกได้ก็ควรไถ่ดีกว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 22, 'เพราะผู้ใดที่องค์พระผู้เป็นเจ้าทรงเรียกเมื่อยังเป็นทาสอยู่ ผู้นั้นเป็นเสรีชนขององค์พระผู้เป็นเจ้า เช่นเดียวกันคนที่รับการทรงเรียกเมื่อเป็นเสรีชน คนนั้นเป็นผู้รับใช้ของพระคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 23, 'พระเจ้าทรงซื้อท่านไว้แล้วตามราคา อย่าเข้าเป็นทาสของมนุษย์เลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 24, 'พี่น้องทั้งหลาย ท่านทุกคนดํารงอยู่ในฐานะอันใดเมื่อพระเจ้าทรงเรียก ก็ให้ผู้นั้นอยู่กับพระเจ้าในฐานะนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 25, 'แล้วเรื่องหญิงสาวพรหมจารีนั้น ข้าพเจ้าไม่ได้รับพระบัญชาจากองค์พระผู้เป็นเจ้า แต่ข้าพเจ้าก็ขอออกความเห็นในฐานะที่เป็นผู้ได้รับพระเมตตาจากองค์พระผู้เป็นเจ้าให้เป็นผู้ที่ไว้ใจได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 26, 'ฉะนั้นเพราะเหตุความยากลําบากที่มีอยู่ในเวลานี้ ข้าพเจ้าเห็นว่า ทุกคนควรจะอยู่อย่างที่เขาอยู่เดี๋ยวนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 27, 'ท่านมีภรรยาแล้วหรือ อย่าหาช่องที่จะหย่าภรรยาเลย ท่านหย่าจากภรรยาแล้วหรือ อย่าหาภรรยาเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 28, 'ถ้าท่านจะแต่งงานก็ไม่มีความผิด และถ้าหญิงสาวพรหมจารีจะแต่งงานก็ไม่มีความผิด แต่คนที่แต่งงานนั้นคงจะต้องยุ่งยากลําบากในฝ่ายเนื้อหนัง แต่ข้าพเจ้าปรารถนาที่จะให้ท่านพ้นจากความยุ่งยากนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 29, 'พี่น้องทั้งหลาย ข้าพเจ้าหมายความว่ายุคนี้ก็สั้นมากแล้ว ตั้งแต่นี้ไปให้คนเหล่านั้นที่มีภรรยาดําเนินชีวิตเหมือนกับไม่มีภรรยา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 30, 'และให้คนที่เศร้าโศกเป็นเหมือนกับมิได้เศร้าโศก และผู้ที่ชื่นชมยินดีให้ได้เป็นเหมือนกับมิได้ชื่นชมยินดี และผู้ที่ซื้อก็ให้ดําเนินชีวิตเหมือนกับว่าเขาไม่มีกรรมสิทธิ์เหนืออะไรเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 31, 'และคนที่ใช้ของโลกนี้ให้เป็นเหมือนกับมิได้ใช้อย่างเต็มที่เลย เพราะความนิยมของโลกนี้กําลังล่วงไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 32, 'ข้าพเจ้าอยากให้ท่านพ้นจากความสาละวนวุ่นวาย ฝ่ายคนที่ไม่มีภรรยาก็สาละวนในการงานขององค์พระผู้เป็นเจ้า เพื่อจะทําสิ่งซึ่งเป็นที่พอพระทัยองค์พระผู้เป็นเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 33, 'แต่คนที่มีภรรยาแล้วก็สาละวนในการงานของโลกนี้เพื่อจะทําสิ่งที่พอใจของภรรยา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 34, 'มีความแตกต่างกันด้วยระหว่างภรรยาและสาวพรหมจารี หญิงที่ยังไม่แต่งงานก็สาละวนในการงานขององค์พระผู้เป็นเจ้า เพื่อจะได้เป็นคนบริสุทธิ์ทั้งกายและจิตใจ แต่หญิงที่มีสามีแล้วก็สาละวนในการงานของโลกนี้เพื่อจะทําสิ่งซึ่งเป็นที่พอใจของสามี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 35, 'ข้าพเจ้าว่าอย่างนี้ก็เพื่อเป็นประโยชน์ของท่าน มิใช่จะเอาบ่วงบาศคล้องท่านแต่เพื่อความเป็นระเบียบ ให้ท่านปฏิบัติองค์พระผู้เป็นเจ้าโดยปราศจากใจสองฝักสองฝ่าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 36, 'แต่ถ้าชายใดคิดว่าเขาปฏิบัติต่อสาวพรหมจารีของเขาอย่างสมควรไม่ได้ และถ้าหญิงนั้นมีอายุผ่านวัยหนุ่มสาวแล้ว และต้องทําอย่างใดอย่างหนึ่งก็ให้เขาทําตามปรารถนา จงให้เขาแต่งงานเสีย เขาไม่ได้ทําผิดสิ่งใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 37, 'แต่ชายใดที่ตั้งใจแน่วแน่และเห็นว่าไม่มีความจําเป็น แต่เขาบังคับใจตนเองได้ และตั้งใจว่าจะให้หญิงนั้นเป็นพรหมจารีต่อไป เขาก็กระทําดีแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 38, 'เหตุฉะนั้นผู้ใดที่ให้หญิงนั้นแต่งงานก็ทําดีอยู่ แต่ผู้ที่ไม่ให้แต่งงานก็ทําดีกว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 39, 'ตราบใดที่สามียังมีชีวิตอยู่ ภรรยาก็ต้องอยู่กับสามีตามกฎหมาย แต่ถ้าสามีตาย นางก็เป็นอิสระจะแต่งงานกับชายใดก็ได้ตามใจ ในองค์พระผู้เป็นเจ้าเท่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 40, 'แต่ตามความเห็นของข้าพเจ้าก็เห็นว่าถ้านางอยู่คนเดียวจะเป็นสุขกว่า และข้าพเจ้าคิดว่าพระวิญญาณของพระเจ้าทรงสถิตอยู่ฝ่ายข้าพเจ้าด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 1, 'แล้วเรื่องของที่เขาบูชาแก่รูปเคารพนั้น เราทั้งหลายทราบแล้วว่าเราทุกคนต่างก็มีความรู้ ความรู้นั้นทําให้ลําพอง แต่ความรักเสริมสร้างขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 2, 'ถ้าผู้ใดถือว่าตัวรู้สิ่งใดแล้ว ผู้นั้นยังไม่รู้ตามที่ตนควรจะรู้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 3, 'แต่ถ้าผู้ใดรักพระเจ้า พระองค์ก็ทรงรู้จักผู้นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 4, 'ฉะนั้นเรื่องการกินอาหารที่เขาได้บูชาแก่รูปเคารพนั้น เรารู้อยู่แล้วว่ารูปนั้นไม่มีตัวมีตนเลยในโลกและพระเจ้าองค์อื่นไม่มี มีแต่พระเจ้าองค์เดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 5, 'ถึงแม้จะมีสิ่งต่างๆในสวรรค์และในแผ่นดินโลกที่เขาเรียกว่า “พระ” (ก็เป็นเหมือนมีพระมากและเจ้ามาก)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 6, 'แต่ว่าสําหรับพวกเรานั้นมีพระเจ้าองค์เดียวคือพระบิดา และสิ่งสารพัดทั้งปวงบังเกิดขึ้นจากพระองค์ และเราอยู่ในพระองค์ และเรามีพระเยซูคริสต์เจ้าองค์เดียว และสิ่งสารพัดก็เกิดขึ้นโดยพระองค์ และเราก็เป็นมาโดยพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 7, 'มิใช่ว่าทุกคนมีความรู้อย่างนี้ เพราะมีบางคนมีจิตสํานึกผิดชอบเรื่องรูปเคารพว่า เมื่อได้กินอาหารนั้นก็ถือว่าเป็นของบูชาแก่รูปเคารพจริงๆ และจิตสํานึกผิดชอบของเขายังอ่อนอยู่จึงเป็นมลทิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 8, 'อาหารไม่เป็นเครื่องที่ทําให้พระเจ้าทรงโปรดปรานเรา ถ้าเรากิน เราก็ไม่ได้อะไรเป็นพิเศษ ถ้าเราไม่กิน เราก็ไม่ขาดอะไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 9, 'แต่จงระวัง อย่าให้เสรีภาพของท่านนั้นทําให้คนที่อ่อนในความเชื่อหลงผิดไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 10, 'เพราะว่า ถ้าผู้ใดเห็นท่านที่มีความรู้เอนกายลงรับประทานในวิหารของรูปเคารพ จิตสํานึกผิดชอบที่อ่อนของคนนั้น จะไม่เหิมขึ้นทําให้เขาบังอาจกินของที่ได้บูชาแก่รูปเคารพนั้นหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 11, 'โดยความรู้ของท่าน พี่น้องที่มีความเชื่ออ่อน ซึ่งพระคริสต์ได้ทรงยอมวายพระชนม์เพื่อเขา จะต้องพินาศไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 12, 'เมื่อท่านทําผิดเช่นนั้นต่อพวกพี่น้อง และทําร้ายจิตสํานึกผิดชอบที่อ่อนของเขา ท่านก็ได้ทําผิดต่อพระคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 13, 'เหตุฉะนั้นถ้าอาหารเป็นเหตุที่ทําให้พี่น้องของข้าพเจ้าหลงผิดไป ข้าพเจ้าจะไม่กินเนื้อสัตว์อีกต่อไป เพราะเกรงว่าข้าพเจ้าจะทําให้พี่น้องต้องหลงผิดไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 1, 'ข้าพเจ้ามิได้เป็นอัครสาวกหรือ ข้าพเจ้ามิได้มีเสรีภาพหรือ ข้าพเจ้ามิได้เห็นพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเราหรือ ท่านทั้งหลายมิได้เป็นผลงานของข้าพเจ้าในองค์พระผู้เป็นเจ้าหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 2, 'ถ้าข้าพเจ้ามิได้เป็นอัครสาวกในสายตาของคนอื่น ข้าพเจ้าก็ยังคงเป็นอัครสาวกในสายตาของท่านอย่างไม่ต้องสงสัย เพราะพวกท่านคือตราตําแหน่งอัครสาวกของข้าพเจ้าในองค์พระผู้เป็นเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 3, 'ถ้าผู้ใดสอบสวนข้าพเจ้า ข้าพเจ้าก็จะบอกว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 4, 'เราไม่มีสิทธิ์ที่จะกินและดื่มหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 5, 'เราไม่มีสิทธิ์ที่จะพาพี่น้องซึ่งเป็นภรรยาไปไหนๆด้วยกัน เหมือนอย่างอัครสาวกอื่นๆ และบรรดาน้องชายขององค์พระผู้เป็นเจ้าและเคฟาสหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 6, 'เฉพาะข้าพเจ้าและบารนาบัสเท่านั้นหรือที่ไม่มีสิทธิ์จะเลิกทํางานหาเลี้ยงชีพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 7, 'ใครบ้างที่เป็นทหารไปในการศึกสงคราม และต้องกินเสบียงของตัวเอง หรือใครบ้างที่ทําสวนปลูกต้นองุ่น และมิได้กินผลองุ่นในสวนนั้น หรือใครบ้างที่เลี้ยงสัตว์และมิได้กินน้ํานมของฝูงสัตว์นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 8, 'ข้าพเจ้ากล่าวอย่างนี้ตามอย่างมนุษย์หรือ พระราชบัญญัติมิได้กล่าวอย่างนี้เหมือนกันหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 9, 'เพราะว่าในพระราชบัญญัติของโมเสสเขียนไว้ว่า ‘อย่าเอาตะกร้าครอบปากวัว เมื่อมันกําลังนวดข้าวอยู่’ พระเจ้าทรงเป็นห่วงวัวหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 10, 'หรือพระองค์ได้ตรัสเพื่อประโยชน์ของเราทั้งหลาย แท้จริงคํานั้นท่านเขียนไว้เพื่อประโยชน์ของเราทั้งหลาย ให้คนที่ไถนาไถด้วยความหวังใจ และให้คนที่นวดข้าวนวดด้วยความหวังใจว่าจะได้ประโยชน์ตามที่เขาหวัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 11, 'ถ้าเราได้หว่านของสําหรับจิตวิญญาณให้แก่ท่าน แล้วจะมากไปหรือ ที่เราจะเกี่ยวของสําหรับเนื้อหนังจากท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 12, 'ถ้าคนอื่นมีสิทธิ์ที่จะได้รับประโยชน์จากท่าน เราไม่มีสิทธิ์ที่จะได้รับยิ่งกว่าเขาอีกหรือ ถึงกระนั้นเราก็มิได้ใช้สิทธิ์นี้เลย แต่ยอมทนทุกข์ยากสารพัด เพื่อเราจะไม่เป็นอุปสรรคขัดขวางข่าวประเสริฐของพระคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 13, 'ท่านไม่รู้หรือว่าคนที่ปรนนิบัติเรื่องสิ่งบริสุทธิ์ ก็กินอาหารของพระวิหาร และคนปรนนิบัติที่แท่นบูชาก็รับส่วนแบ่งจากแท่นบูชานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 14, 'ทํานองเดียวกัน องค์พระผู้เป็นเจ้าได้ทรงบัญชาไว้ว่า คนที่ประกาศข่าวประเสริฐควรได้รับการเลี้ยงชีพด้วยข่าวประเสริฐนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 15, 'แต่ข้าพเจ้าไม่ได้ใช้สิทธิ์เหล่านี้เลย ที่ข้าพเจ้าเขียนเรื่องนี้ ก็มิใช่เพื่อจะให้เขากระทําอย่างนั้นแก่ข้าพเจ้า เพราะข้าพเจ้ายอมตายเสียดีกว่าที่จะให้ผู้ใดทําลายเกียรติอันนี้ของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 16, 'เพราะถึงแม้ว่าข้าพเจ้าประกาศข่าวประเสริฐนั้นข้าพเจ้าไม่มีเหตุที่จะอวดได้ เพราะจําเป็นที่ข้าพเจ้าจะต้องประกาศ ถ้าข้าพเจ้าไม่ประกาศข่าวประเสริฐวิบัติจะเกิดแก่ข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 17, 'เพราะถ้าข้าพเจ้าประกาศอย่างเต็มใจ ข้าพเจ้าก็จะได้บําเหน็จ แต่ถ้ากระทําการประกาศนั้นโดยฝืนใจ ก็ยังเป็นการที่ทรงมอบหน้าที่ประกาศข่าวประเสริฐไว้ให้ข้าพเจ้ากระทํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 18, 'แล้วอะไรเล่าจะเป็นบําเหน็จของข้าพเจ้า คือเมื่อข้าพเจ้าประกาศข่าวประเสริฐ ข้าพเจ้าได้ประกาศข่าวประเสริฐของพระคริสต์โดยไม่คิดค่าจ้าง เพื่อจะไม่ได้ใช้สิทธิ์ในข่าวประเสริฐนั้นอย่างเต็มที่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 19, 'เพราะถึงแม้ว่าข้าพเจ้ามิได้อยู่ในบังคับของผู้ใด ข้าพเจ้าก็ยังยอมตัวเป็นทาสคนทั้งปวงเพื่อจะได้ชนะใจคนมากยิ่งขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 20, 'ต่อพวกยิว ข้าพเจ้าก็ทําตัวเหมือนยิว เพื่อจะได้พวกยิว ต่อพวกที่อยู่ใต้พระราชบัญญัติ ข้าพเจ้าก็เป็นเหมือนคนอยู่ใต้พระราชบัญญัติ เพื่อจะได้คนที่อยู่ใต้พระราชบัญญัตินั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 21, 'ต่อคนที่อยู่นอกพระราชบัญญัติ ข้าพเจ้าก็ทําตัวเหมือนคนนอกพระราชบัญญัติ เพื่อจะได้คนที่อยู่นอกพระราชบัญญัตินั้น (แต่ข้าพเจ้ามิได้อยู่นอกพระราชบัญญัติของพระเจ้า แต่อยู่ใต้พระราชบัญญัติแห่งพระคริสต์)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 22, 'ต่อคนอ่อนแอ ข้าพเจ้าก็ทําตัวเหมือนคนอ่อนแอ เพื่อจะได้คนอ่อนแอ ข้าพเจ้ายอมเป็นคนทุกชนิดต่อคนทั้งปวง เพื่อจะช่วยเขาให้รอดได้บ้างโดยทุกวิถีทาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 23, 'ข้าพเจ้าทําอย่างนี้เพราะเห็นแก่ข่าวประเสริฐ เพื่อข้าพเจ้าจะได้มีส่วนกับท่านในข่าวประเสริฐนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 24, 'ท่านไม่รู้หรือว่าคนเหล่านั้นที่วิ่งแข่งกัน ก็วิ่งด้วยกันทุกคน แต่คนที่ได้รับรางวัลมีคนเดียว เหตุฉะนั้นจงวิ่งเพื่อชิงรางวัลให้ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 25, 'ฝ่ายนักกีฬาทุกคนก็เคร่งครัดในระเบียบทุกอย่าง แล้วเขากระทําอย่างนั้นเพื่อจะได้มงกุฎใบไม้ซึ่งร่วงโรยได้ แต่เรากระทําเพื่อจะได้มงกุฎที่ไม่มีวันร่วงโรยเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 26, 'ดังนั้นส่วนข้าพเจ้าวิ่งแข่งอย่างนี้โดยมีเป้าหมาย ข้าพเจ้าได้ต่อสู้อย่างนี้ ไม่ใช่อย่างนักมวยที่ชกลม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 27, 'แต่ข้าพเจ้าระงับความปรารถนาฝ่ายเนื้อหนังให้อยู่ใต้บังคับ เพราะเกรงว่าโดยทางหนึ่งทางใดเมื่อข้าพเจ้าได้ประกาศแก่คนอื่นแล้ว ตัวข้าพเจ้าเองจะเป็นคนที่ใช้การไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 1, 'พี่น้องทั้งหลาย ยิ่งกว่านี้ข้าพเจ้าอยากให้ท่านทั้งหลายเข้าใจว่าบรรพบุรุษของเราทั้งสิ้นได้อยู่ใต้เมฆ และได้ผ่านทะเลไปทุกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 2, 'ได้รับบัพติศมาในเมฆและในทะเลเข้าส่วนกับโมเสสทุกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 3, 'และได้รับประทานอาหารฝ่ายจิตวิญญาณอันเดียวกันทุกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 4, 'และได้ดื่มน้ําฝ่ายจิตวิญญาณอันเดียวกันทุกคน เพราะว่าเขาได้ดื่มน้ําซึ่งไหลออกมาจากศิลาฝ่ายจิตวิญญาณที่ติดตามเขามา ศิลานั้นคือพระคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 5, 'แต่ถึงกระนั้นก็ดีมีคนส่วนมากในพวกนั้นที่พระเจ้าไม่ทรงพอพระทัย เพราะว่าเขาล้มตายกันเกลื่อนกลาดในถิ่นทุรกันดาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 6, 'แล้วเหตุการณ์เหล่านี้จึงเป็นแบบอย่างสําหรับพวกเรา ไม่ให้เรามีใจโลภปรารถนาสิ่งที่ชั่วเหมือนเขาเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 7, 'ท่านทั้งหลายอย่านับถือรูปเคารพ เหมือนอย่างที่บางคนในพวกเขาได้กระทํา ตามที่มีเขียนไว้แล้วว่า ‘ประชาชนก็นั่งลงกินและดื่ม แล้วก็ลุกขึ้นเล่นสนุกกัน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 8, 'อย่าให้เรากระทําล่วงประเวณี เหมือนอย่างที่บางคนในพวกเขาได้กระทํา แล้วก็ล้มลงตายในวันเดียวสองหมื่นสามพันคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 9, 'อย่าให้เราลองดีพระคริสต์เหมือนอย่างที่บางคนในพวกเขาได้กระทํา แล้วก็ต้องพินาศด้วยงูร้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 10, 'ท่านทั้งหลายอย่าบ่นเหมือนอย่างที่บางคนในพวกเขาได้บ่น แล้วก็ต้องพินาศด้วยองค์เพชฌฆาต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 11, 'แต่บรรดาเหตุการณ์เหล่านี้จึงได้บังเกิดแก่เขาเพื่อเป็นตัวอย่าง และได้บันทึกไว้เพื่อเตือนสติเราทั้งหลาย ผู้ซึ่งกําลังอยู่ในกาลสุดปลายของแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 12, 'เหตุฉะนั้นคนที่คิดว่าตัวเองมั่นคงดีแล้ว ก็จงระวังให้ดี กลัวว่าจะล้มลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 13, 'ไม่มีการทดลองใดๆเกิดขึ้นกับท่าน นอกเหนือจากการทดลองซึ่งเคยเกิดกับมนุษย์ทั้งหลาย แต่พระเจ้าทรงสัตย์ซื่อ พระองค์จะไม่ทรงให้ท่านต้องถูกทดลองเกินกว่าที่ท่านจะทนได้ แต่เมื่อท่านถูกทดลองนั้น พระองค์จะทรงโปรดให้ท่านมีทางที่จะหลีกเลี่ยงได้ด้วย เพื่อท่านจะมีกําลังทนได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 14, 'พวกที่รักของข้าพเจ้า เหตุฉะนั้นท่านจงหลีกเลี่ยงเสียจากการนับถือรูปเคารพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 15, 'ข้าพเจ้าพูดกับท่านอย่างพูดกับคนที่มีปัญญา ท่านจงพิจารณาถ้อยคําที่ข้าพเจ้าพูดนั้นเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 16, 'ถ้วยแห่งพระพรซึ่งเราได้ขอพระพรนั้นเป็นที่ทําให้เรามีส่วนร่วมในพระโลหิตของพระคริสต์มิใช่หรือ ขนมปังซึ่งเราหักนั้นเป็นที่ทําให้เรามีส่วนร่วมในพระกายของพระคริสต์มิใช่หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 17, 'แม้เราซึ่งเป็นบุคคลหลายคน เราก็ยังเป็นขนมปังก้อนเดียวและเป็นร่างกายเดียว เพราะว่าเราทุกคนรับประทานขนมปังก้อนเดียวกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 18, 'จงพิจารณาดูพวกอิสราเอลตามเนื้อหนัง คนที่รับประทานของที่บูชาแล้วนั้น ก็มีส่วนร่วมในแท่นบูชานั้นมิใช่หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 19, 'ถ้าอย่างนั้นแล้วจะให้ข้าพเจ้าว่าอย่างไร รูปเคารพนั้นศักดิ์สิทธิ์หรือ เครื่องบูชาที่ถวายแก่รูปเคารพนั้นเป็นของศักดิ์สิทธิ์หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 20, 'แต่ข้าพเจ้าว่า เครื่องบูชาที่พวกต่างชาติถวายนั้น เขาถวายบูชาแก่พวกปีศาจ และไม่ได้ถวายแด่พระเจ้า ข้าพเจ้าไม่ปรารถนาให้ท่านมีส่วนร่วมกับพวกปีศาจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 21, 'ท่านจะดื่มจากถ้วยขององค์พระผู้เป็นเจ้าและจากถ้วยของพวกปีศาจด้วยไม่ได้ ท่านจะรับประทานที่โต๊ะขององค์พระผู้เป็นเจ้าและที่โต๊ะของพวกปีศาจด้วยก็ไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 22, 'เราจะยั่วยุให้องค์พระผู้เป็นเจ้าทรงอิจฉาหรือ เรามีฤทธิ์มากกว่าพระองค์หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 23, 'ข้าพเจ้าทําสิ่งสารพัดได้ แต่ไม่ใช่ทุกสิ่งที่จะทําได้นั้นเป็นประโยชน์ ข้าพเจ้าทําสิ่งสารพัดได้ แต่ไม่ใช่ทุกสิ่งจะทําให้เจริญขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 24, 'อย่าให้ผู้ใดเห็นแก่ประโยชน์ส่วนตัว แต่จงเห็นแก่ประโยชน์ของคนอื่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 25, 'ทุกสิ่งที่เขาขายตามตลาดเนื้อนั้นรับประทานได้ ไม่ต้องถามอะไรโดยเห็นแก่ใจสํานึกผิดชอบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 26, 'เพราะว่า ‘แผ่นดินโลกกับสรรพสิ่งในโลกนั้นเป็นขององค์พระผู้เป็นเจ้า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 27, 'ถ้าคนที่ไม่มีความเชื่อจะเชิญท่านไปในงานเลี้ยงและท่านเต็มใจไป สิ่งที่เขาตั้งให้รับประทานก็รับประทานได้ ไม่ต้องถามอะไรโดยเห็นแก่ใจสํานึกผิดชอบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 28, 'แต่ถ้ามีใครมาบอกท่านว่า “ของนี้เขาถวายแก่รูปเคารพแล้ว” ท่านอย่ารับประทาน เพราะเห็นแก่คนที่บอกนั้นและเพราะเห็นแก่ใจสํานึกผิดชอบด้วย เพราะว่า ‘แผ่นดินโลกกับสรรพสิ่งในโลกนั้นเป็นขององค์พระผู้เป็นเจ้า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 29, 'ข้าพเจ้ามิได้หมายถึงใจสํานึกผิดชอบของท่าน แต่หมายถึงใจสํานึกผิดชอบของคนที่บอกนั้น ทําไมใจสํานึกผิดชอบของผู้อื่นจะต้องมาขัดขวางเสรีภาพของข้าพเจ้าเล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 30, 'เพราะถ้าข้าพเจ้ารับประทานโดยพระคุณ ทําไมเขาติเตียนข้าพเจ้าเพราะสิ่งที่ข้าพเจ้าได้ขอบพระคุณแล้วเล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 31, 'เหตุฉะนั้นเมื่อท่านจะรับประทาน จะดื่ม หรือจะทําอะไรก็ตาม จงกระทําเพื่อเป็นการถวายพระเกียรติแด่พระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 32, 'อย่าเป็นต้นเหตุที่ทําให้พวกยิว หรือพวกต่างชาติ หรือคริสตจักรของพระเจ้าหลงผิดไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 33, 'เหมือนที่ข้าพเจ้าเองได้พยายามกระทําทุกสิ่งเพื่อให้เป็นที่พอใจของคนทั้งปวง มิได้เห็นแก่ประโยชน์ส่วนตัว แต่เห็นแก่ประโยชน์ของคนทั้งหลาย เพื่อให้เขารอดได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 1, 'ท่านทั้งหลายก็จงปฏิบัติตามอย่างข้าพเจ้า เหมือนอย่างที่ข้าพเจ้าปฏิบัติตามอย่างพระคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 2, 'พี่น้องทั้งหลาย บัดนี้ข้าพเจ้าขอชมท่านทั้งหลายเพราะท่านได้ระลึกถึงข้าพเจ้าทุกประการ และท่านได้รักษากฎที่ข้าพเจ้าได้มอบไว้กับท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 3, 'แต่ข้าพเจ้าใคร่ให้ท่านทั้งหลายเข้าใจว่า พระคริสต์ทรงเป็นศีรษะของชายทุกคน และชายเป็นศีรษะของหญิง และพระเจ้าทรงเป็นพระเศียรของพระคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 4, 'ชายทุกคนที่กําลังอธิษฐานหรือพยากรณ์โดยคลุมศีรษะอยู่ ก็ทําความอัปยศแก่ศีรษะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 5, 'แต่หญิงทุกคนที่กําลังอธิษฐานหรือพยากรณ์ ถ้าไม่คลุมศีรษะ ก็ทําความอัปยศแก่ศีรษะ เพราะเหมือนกับว่านางได้โกนผมเสียแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 6, 'เพราะถ้าผู้หญิงไม่ได้คลุมศีรษะ ก็ควรจะตัดผมเสีย แต่ถ้าการที่ผู้หญิงจะตัดผมหรือโกนผมนั้นเป็นสิ่งที่น่าอับอาย จงคลุมศีรษะเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 7, 'เพราะการที่ผู้ชายไม่สมควรจะคลุมศีรษะนั้น ก็เพราะว่าผู้ชายเป็นพระฉายาและสง่าราศีของพระเจ้า ส่วนผู้หญิงนั้นเป็นสง่าราศีของผู้ชาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 8, 'เพราะว่าไม่ได้ทรงสร้างผู้ชายจากผู้หญิง แต่ได้ทรงสร้างผู้หญิงจากผู้ชาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 9, 'และไม่ได้ทรงสร้างผู้ชายไว้สําหรับผู้หญิง แต่ทรงสร้างผู้หญิงไว้สําหรับผู้ชาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 10, 'ด้วยเหตุนี้เอง ผู้หญิงจึงควรจะเอาสัญญลักษณ์แห่งอํานาจนี้คลุมศีรษะ เพราะเห็นแก่พวกทูตสวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 11, 'ถึงกระนั้นก็ดี ในองค์พระผู้เป็นเจ้า ผู้ชายก็ต้องพึ่งผู้หญิงและผู้หญิงก็ต้องพึ่งผู้ชาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 12, 'เพราะว่าผู้หญิงนั้นทรงสร้างมาจากผู้ชายฉันใด ต่อมาผู้ชายก็เกิดมาจากผู้หญิงฉันนั้น แต่สิ่งสารพัดก็มีมาจากพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 13, 'ท่านทั้งหลายจงตัดสินเองเถิดว่า เป็นการสมควรหรือไม่ที่ผู้หญิงจะไม่คลุมศีรษะเมื่ออธิษฐานต่อพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 14, 'ธรรมชาติเองไม่ได้สอนท่านหรือว่า ถ้าผู้ชายไว้ผมยาวก็เป็นที่น่าอายแก่ตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 15, 'แต่ถ้าผู้หญิงไว้ผมยาวก็เป็นสง่าราศีแก่ตัว เพราะว่าผมเป็นสิ่งที่ประทานให้แก่เขาเพื่อคลุมศีรษะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 16, 'แต่ถ้าผู้ใดจะโต้แย้ง เราและคริสตจักรของพระเจ้าไม่รับธรรมเนียมอย่างที่โต้แย้งนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 17, 'แล้วในการให้คําสั่งต่อไปนี้ ข้าพเจ้าชมท่านไม่ได้ คือว่าการประชุมของท่านนั้นมักจะได้ผลเสียมากกว่าผลดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 18, 'ประการแรกข้าพเจ้าได้ยินว่า เมื่อท่านประชุมคริสตจักรนั้น มีการแตกก๊กแตกเหล่าในพวกท่าน และข้าพเจ้าเชื่อว่าคงมีความจริงอยู่บ้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 19, 'เพราะจะต้องมีการขัดแย้งกันบ้างในพวกท่าน เพื่อคนฝ่ายถูกในพวกท่านจะได้ปรากฏเด่นขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 20, 'เมื่อท่านทั้งหลายประชุมพร้อมกันนั้น ท่านจึงประชุมรับประทานเป็นที่ระลึกถึงองค์พระผู้เป็นเจ้าไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 21, 'เพราะว่าเมื่อท่านรับประทาน บ้างก็รับประทานอาหารของตนก่อนคนอื่น บ้างก็ยังหิวอยู่ และบ้างก็เมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 22, 'อะไรกันนี่ ท่านไม่มีเรือนที่จะกินและดื่มหรือ หรือว่าท่านดูหมิ่นคริสตจักรของพระเจ้า และทําให้คนที่ขัดสนได้รับความอับอาย จะให้ข้าพเจ้าว่าอย่างไรแก่ท่าน จะให้ชมท่านหรือ ในเรื่องนี้ข้าพเจ้าจะไม่ขอชมท่านเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 23, 'เพราะว่าเรื่องซึ่งข้าพเจ้าได้มอบไว้กับท่านแล้วนั้น ข้าพเจ้าได้รับจากองค์พระผู้เป็นเจ้า คือในคืนที่เขาทรยศพระเยซูเจ้านั้น พระองค์ทรงหยิบขนมปัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 24, 'ครั้นขอบพระคุณแล้ว จึงทรงหักแล้วตรัสว่า “จงรับไปกินเถิด นี่เป็นกายของเรา ซึ่งหักออกเพื่อท่านทั้งหลาย จงกระทําอย่างนี้ให้เป็นที่ระลึกถึงเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 25, 'เมื่อรับประทานแล้ว พระองค์จึงทรงหยิบถ้วยด้วยอาการอย่างเดียวกัน ตรัสว่า “ถ้วยนี้คือพันธสัญญาใหม่ด้วยโลหิตของเรา เมื่อท่านดื่มจากถ้วยนี้เวลาใด จงดื่มให้เป็นที่ระลึกถึงเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 26, 'เพราะว่าเมื่อท่านทั้งหลายกินขนมปังนี้และดื่มจากถ้วยนี้เวลาใด ท่านก็ประกาศการวายพระชนม์ขององค์พระผู้เป็นเจ้าจนกว่าพระองค์จะเสด็จมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 27, 'เหตุฉะนั้น ถ้าผู้ใดกินขนมปังนี้และดื่มจากถ้วยขององค์พระผู้เป็นเจ้าอย่างไม่สมควร ผู้นั้นก็ทําผิดต่อพระกายและพระโลหิตขององค์พระผู้เป็นเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 28, 'ขอให้ทุกคนพิจารณาตนเอง แล้วจึงกินขนมปังและดื่มจากถ้วยนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 29, 'เพราะว่าคนที่กินและดื่มอย่างไม่สมควร ก็กินและดื่มเพื่อนําพระอาชญามาสู่ตนเอง เพราะมิได้พินิจดูพระกายขององค์พระผู้เป็นเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 30, 'ด้วยเหตุนี้พวกท่านหลายคนจึงอ่อนกําลังและป่วยอยู่และที่ล่วงหลับไปแล้วก็มีมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 31, 'เพราะถ้าเราจะพิจารณาตัวเราเอง เราจะไม่ต้องถูกทําโทษ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 32, 'แต่เมื่อองค์พระผู้เป็นเจ้าทรงทําโทษเรานั้น พระองค์ทรงตีสอนเรา เพื่อมิให้เราถูกพิพากษาลงโทษด้วยกันกับโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 33, 'พี่น้องของข้าพเจ้า ด้วยเหตุนี้เมื่อท่านมาร่วมประชุมรับประทานอาหารนั้น จงคอยซึ่งกันและกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 34, 'ถ้ามีใครหิวก็ให้เขากินที่บ้านเสียก่อน เพื่อเมื่อมาประชุมกันท่านจะได้ไม่ถูกพิพากษาลงโทษ ส่วนเรื่องอื่นๆนั้นเมื่อข้าพเจ้ามาข้าพเจ้าจะแนะนําให้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 1, 'พี่น้องทั้งหลาย บัดนี้ข้าพเจ้าอยากให้ท่านเข้าใจเรื่องของประทานฝ่ายจิตวิญญาณนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 2, 'ท่านรู้แล้วว่า แต่ก่อนท่านยังเป็นคนไม่เชื่อนั้น ท่านถูกชักนําให้หลงไปนับถือรูปเคารพซึ่งพูดไม่ได้ตามแต่ท่านจะถูกนําไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 3, 'เหตุฉะนั้นข้าพเจ้าจึงบอกท่านทั้งหลายให้ทราบว่า ไม่มีผู้ใดซึ่งพูดโดยพระวิญญาณของพระเจ้าจะเรียกพระเยซูว่า ผู้ที่ถูกสาปแช่ง และไม่มีผู้ใดอาจพูดว่าพระเยซูเป็นองค์พระผู้เป็นเจ้า นอกจากผู้ที่พูดโดยพระวิญญาณบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 4, 'แล้วของประทานนั้นมีต่างๆกัน แต่มีพระวิญญาณองค์เดียวกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 5, 'งานรับใช้มีต่างๆกัน แต่มีองค์พระผู้เป็นเจ้าองค์เดียวกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 6, 'กิจกรรมมีต่างๆกัน แต่มีพระเจ้าองค์เดียวกันที่ทรงกระทําสารพัดในทุกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 7, 'การสําแดงของพระวิญญาณนั้นมีแก่ทุกคนเพื่อประโยชน์ร่วมกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 8, 'ด้วยพระวิญญาณทรงโปรดประทานให้คนหนึ่งมีถ้อยคําประกอบด้วยสติปัญญา และให้อีกคนหนึ่งมีถ้อยคําอันประกอบด้วยความรู้ แต่เป็นโดยพระวิญญาณองค์เดียวกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 9, 'และให้อีกคนหนึ่งมีความเชื่อ แต่เป็นโดยพระวิญญาณองค์เดียวกัน และให้อีกคนหนึ่งมีความสามารถรักษาคนป่วยได้ แต่เป็นโดยพระวิญญาณองค์เดียวกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 10, 'และให้อีกคนหนึ่งทําการอัศจรรย์ต่างๆ และให้อีกคนหนึ่งพยากรณ์ได้ และให้อีกคนหนึ่งรู้จักสังเกตวิญญาณต่างๆ และให้อีกคนหนึ่งพูดภาษาต่างๆ และให้อีกคนหนึ่งแปลภาษานั้นๆได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 11, 'สิ่งสารพัดเหล่านี้ พระวิญญาณองค์เดียวกันทรงบันดาลและประทานแก่แต่ละคนตามชอบพระทัยพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 12, 'ถึงกายนั้นเป็นกายเดียว ก็ยังมีอวัยวะหลายส่วน และบรรดาอวัยวะต่างๆของกายเดียวนั้นแม้จะมีหลายส่วนก็ยังเป็นกายเดียวกันฉันใด พระคริสต์ก็ทรงเป็นฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 13, 'เพราะว่าถึงเราจะเป็นพวกยิวหรือพวกต่างชาติ เป็นทาสหรือมิใช่ทาสก็ตาม เราทั้งหลายได้รับบัพติศมาโดยพระวิญญาณองค์เดียวเข้าเป็นกายอันเดียวกัน และเราทั้งหลายได้เต็มล้นอยู่ด้วยพระวิญญาณองค์เดียวนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 14, 'เพราะว่าร่างกายมิได้ประกอบด้วยอวัยวะเดียวแต่ด้วยหลายอวัยวะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 15, 'ถ้าเท้าจะพูดว่า “เพราะข้าพเจ้ามิได้เป็นมือ ข้าพเจ้าจึงไม่ได้เป็นอวัยวะของร่างกายนั้น” เท้าจะไม่เป็นอวัยวะของร่างกายเพราะเหตุนั้นหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 16, 'และถ้าหูจะพูดว่า “เพราะข้าพเจ้ามิได้เป็นตา ข้าพเจ้าจึงมิได้เป็นอวัยวะของร่างกายนั้น” หูจะไม่เป็นอวัยวะของร่างกายเพราะเหตุนั้นหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 17, 'ถ้าอวัยวะทั้งหมดในร่างกายเป็นตา การได้ยินจะอยู่ที่ไหน ถ้าทั้งร่างกายเป็นหู การดมกลิ่นจะอยู่ที่ไหน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 18, 'แต่บัดนี้พระเจ้าได้ทรงตั้งอวัยวะทุกส่วนไว้ในร่างกายตามชอบพระทัยของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 19, 'ถ้าอวัยวะทั้งหมดเป็นอวัยวะเดียว ร่างกายจะมีที่ไหน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 20, 'แต่บัดนี้มีหลายอวัยวะแต่ก็ยังเป็นร่างกายเดียวกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 21, 'และตาจะว่าแก่มือว่า “ข้าพเจ้าไม่ต้องการเจ้า” ก็ไม่ได้ หรือศีรษะจะว่าแก่เท้าว่า “ข้าพเจ้าไม่ต้องการเจ้า” ก็ไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 22, 'แต่ยิ่งกว่านี้อวัยวะของร่างกายที่เราเห็นว่าอ่อนแอ เราก็ขาดเสียไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 23, 'และอวัยวะของร่างกายที่เราถือว่ามีเกียรติน้อย เราก็ยังทําให้มีเกียรติยิ่งขึ้น และอวัยวะที่ไม่น่าดูนั้น เราก็ทําให้น่าดูยิ่งขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 24, 'เพราะว่าอวัยวะที่น่าดูแล้ว ก็ไม่จําเป็นที่จะต้องตกแต่งอีก แต่พระเจ้าได้ทรงให้อวัยวะของร่างกายเสมอภาคกัน ทรงให้อวัยวะที่ต่ําต้อยเป็นที่นับถือมากขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 25, 'เพื่อไม่ให้มีการแก่งแย่งกันในร่างกาย แต่ให้อวัยวะทุกส่วนมีความห่วงใยซึ่งกันและกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 26, 'ถ้าอวัยวะอันหนึ่งเจ็บ อวัยวะทั้งหมดก็พลอยเจ็บด้วย ถ้าอวัยวะอันหนึ่งได้รับเกียรติ อวัยวะทั้งหมดก็พลอยชื่นชมยินดีด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 27, 'บัดนี้ฝ่ายท่านทั้งหลายเป็นกายของพระคริสต์ และต่างก็เป็นอวัยวะของพระกายนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 28, 'และพระเจ้าได้ทรงโปรดตั้งบางคนไว้ในคริสตจักร คือหนึ่งอัครสาวก สองผู้พยากรณ์ สามครูบาอาจารย์ แล้วต่อจากนั้นก็มีการอัศจรรย์ ของประทานในการรักษาโรค การช่วยเหลือ การครอบครอง การพูดภาษาต่างๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 29, 'ทุกคนเป็นอัครสาวกหรือ ทุกคนเป็นผู้พยากรณ์หรือ ทุกคนเป็นครูบาอาจารย์หรือ ทุกคนกระทําการอัศจรรย์หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 30, 'ทุกคนได้รับของประทานให้รักษาโรคหรือ ทุกคนพูดภาษาต่างๆหรือ ทุกคนแปลได้หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 31, 'แต่ท่านทั้งหลายจงกระตือรือร้นอย่างจริงจังบรรดาของประทานอันดีที่สุดนั้น และข้าพเจ้ายังคงแสดงทางที่ยอดเยี่ยมกว่าแก่ท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 1, 'แม้ข้าพเจ้าพูดภาษาของมนุษย์ก็ดี และภาษาของทูตสวรรค์ก็ดี แต่ไม่มีความรัก ข้าพเจ้าเป็นเหมือนฆ้องหรือฉาบที่กําลังส่งเสียง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 2, 'แม้ข้าพเจ้ามีของประทานแห่งการพยากรณ์ และเข้าใจในความลึกลับทั้งปวงและมีความรู้ทั้งสิ้น และแม้ข้าพเจ้ามีความเชื่อทั้งหมดพอจะยกภูเขาไปได้ แต่ไม่มีความรัก ข้าพเจ้าก็ไม่มีค่าอะไรเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 3, 'แม้ข้าพเจ้ามอบของสารพัดเพื่อเลี้ยงคนยากจน และแม้ข้าพเจ้ายอมให้เอาตัวข้าพเจ้าไปเผาไฟเสีย แต่ไม่มีความรัก จะหาเป็นประโยชน์แก่ข้าพเจ้าไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 4, 'ความรักนั้นก็อดทนนานและกระทําคุณให้ ความรักไม่อิจฉา ความรักไม่อวดตัว ไม่หยิ่งผยอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 5, 'ไม่ทําสิ่งที่ไม่บังควร ไม่คิดเห็นแก่ตนเองฝ่ายเดียว ไม่ฉุนเฉียว ไม่ช่างจดจําความผิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 6, 'ไม่ชื่นชมยินดีในความชั่วช้า แต่ชื่นชมยินดีในความจริง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 7, 'ไม่แคะไค้คุ้ยเขี่ยความผิดของเขา และเชื่อในส่วนดีของเขาอยู่เสมอ และมีความหวังอยู่เสมอ และเพียรทนเอาทุกอย่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 8, 'ความรักไม่มีวันสูญสิ้น แม้คําพยากรณ์ก็จะเสื่อมสูญไป แม้การพูดภาษาต่างๆนั้นก็จะมีเวลาเลิกไป แม้ความรู้ก็จะเสื่อมสูญไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 9, 'เพราะที่เรารู้นั้นก็รู้แต่ส่วนหนึ่ง และที่เราพยากรณ์นั้นก็พยากรณ์แต่ส่วนหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 10, 'แต่เมื่อความสมบูรณ์มาถึงแล้ว ความบกพร่องนั้นก็จะสูญไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 11, 'เมื่อข้าพเจ้ายังเป็นเด็ก ข้าพเจ้าพูดอย่างเด็ก คิดอย่างเด็ก ใคร่ครวญหาเหตุผลอย่างเด็ก แต่เมื่อข้าพเจ้าเป็นผู้ใหญ่ ข้าพเจ้าก็เลิกอาการเด็กเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 12, 'เพราะว่าบัดนี้เราเห็นสลัวๆเหมือนดูในกระจก แต่เวลานั้นจะได้เห็นหน้ากันชัดเจน เดี๋ยวนี้ข้าพเจ้ารู้แต่ส่วนหนึ่ง แต่เวลานั้นข้าพเจ้าจะรู้แจ้งเหมือนได้รู้จักข้าพเจ้าแล้วด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 13, 'ดังนั้นยังตั้งอยู่สามสิ่ง คือความเชื่อ ความหวังใจ ความรัก แต่ความรักใหญ่ที่สุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 1, 'จงมุ่งหาความรัก และจงปรารถนาของประทานฝ่ายจิตวิญญาณ เฉพาะอย่างยิ่งการพยากรณ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 2, 'เพราะว่าผู้หนึ่งผู้ใดที่พูดภาษาต่างๆได้ ไม่ได้พูดกับมนุษย์ แต่ทูลต่อพระเจ้า เพราะว่าไม่มีมนุษย์คนใดเข้าใจได้ แต่เขาพูดเป็นความลึกลับฝ่ายจิตวิญญาณ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 3, 'ฝ่ายผู้ที่พยากรณ์นั้นพูดกับมนุษย์ทําให้เขาเจริญขึ้น เป็นที่เตือนสติและหนุนใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 4, 'ฝ่ายคนที่พูดภาษาต่างๆนั้นก็ทําให้ตนเองเจริญฝ่ายเดียว แต่ผู้ที่พยากรณ์นั้นย่อมทําให้คริสตจักรจําเริญขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 5, 'ข้าพเจ้าใคร่ให้ท่านทั้งหลายพูดภาษาต่างๆได้ แต่ยิ่งกว่านั้นอีกข้าพเจ้าปรารถนาจะให้ท่านทั้งหลายพยากรณ์ได้ เพราะว่าผู้ที่พยากรณ์ได้นั้นก็ใหญ่กว่าคนที่พูดภาษาต่างๆได้ เว้นแต่เขาสามารถแปลภาษานั้นๆออก เพื่อคริสตจักรจะได้รับความจําเริญขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 6, 'นี่แหละพี่น้องทั้งหลาย ถ้าข้าพเจ้ามาหาท่านและพูดภาษาต่างๆ จะเป็นประโยชน์อะไรแก่ท่านเล่า เว้นเสียแต่ข้าพเจ้าจะพูดกับท่านโดยคําวิวรณ์ หรือโดยความรู้ หรือโดยคําพยากรณ์ หรือโดยการสั่งสอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 7, 'แม้เป็นสิ่งที่ไม่มีชีวิตก็ยังกระทําเสียงได้ เช่นปี่หรือพิณเขาคู่ ถ้าเสียงนั้นไม่ต่างกัน ใครจะรู้ได้อย่างไรว่า เขาเป่าหรือดีดอะไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 8, 'เพราะถ้าแตรเปล่งเสียงไม่ชัดเจน ใครเล่าจะเตรียมตัวเข้าประจัญบานได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 9, 'ท่านทั้งหลายก็เป็นเช่นนั้น ถ้าท่านไม่ใช้ภาษาพูดที่เข้าใจได้ง่าย เขาจะเข้าใจคําพูดนั้นได้อย่างไร ท่านก็จะพูดเพ้อตามลมไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 10, 'ในโลกนี้มีภาษาเป็นอันมาก และไม่มีภาษาใดๆที่ปราศจากเนื้อความ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 11, 'เหตุฉะนั้นถ้าข้าพเจ้าไม่เข้าใจเนื้อความของภาษานั้นๆ ข้าพเจ้าจะเป็นคนต่างภาษากับคนที่พูด และคนที่พูดนั้นจะเป็นคนต่างภาษากับข้าพเจ้าด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 12, 'เช่นเดียวกัน เมื่อท่านทั้งหลายกําลังร้อนใจแสวงหาของประทานฝ่ายจิตวิญญาณแล้ว ก็จงอุตส่าห์กระทําตัวของท่านให้สามารถที่จะทําให้คริสตจักรจําเริญขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 13, 'เหตุฉะนั้นให้คนที่พูดภาษาต่างๆอธิษฐานว่า เขาจะสามารถแปลได้ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 14, 'เพราะถ้าข้าพเจ้าอธิษฐานเป็นภาษาต่างๆ จิตวิญญาณของข้าพเจ้าอธิษฐานก็จริง แต่ข้าพเจ้าเองก็ไม่เข้าใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 15, 'ถ้าเช่นนั้นข้าพเจ้าควรจะทําประการใด ข้าพเจ้าจะอธิษฐานด้วยจิตวิญญาณและจะอธิษฐานด้วยความเข้าใจด้วย และจะร้องเพลงด้วยจิตวิญญาณและจะร้องเพลงด้วยความเข้าใจด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 16, 'มิฉะนั้นเมื่อท่านขอบพระคุณด้วยจิตวิญญาณแล้ว คนที่อยู่ในพวกที่รู้ไม่ถึงจะว่า “เอเมน” เมื่อท่านขอบพระคุณอย่างไรได้ ในเมื่อเขาไม่เข้าใจสิ่งที่ท่านพูด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 17, 'แม้ท่านขอบพระคุณอย่างไพเราะก็ตาม แต่คนอื่นนั้นจะไม่จําเริญขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 18, 'ข้าพเจ้าขอบพระคุณพระเจ้าของข้าพเจ้า ข้าพเจ้าพูดภาษาต่างๆมากกว่าท่านทั้งหลายอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 19, 'แต่ว่าในคริสตจักร ข้าพเจ้าพอใจที่จะพูดสักห้าคําด้วยความเข้าใจ เพื่อเสียงของข้าพเจ้าจะสั่งสอนคนอื่นด้วย ดีกว่าที่จะพูดหมื่นคําเป็นภาษาต่างๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 20, 'พี่น้องทั้งหลาย ความเข้าใจของท่านอย่าให้เป็นอย่างเด็ก อย่างไรก็ตามในเรื่องความชั่วร้ายจงเป็นอย่างเด็ก แต่ฝ่ายความเข้าใจจงให้เป็นอย่างผู้ใหญ่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 21, 'ในพระราชบัญญัติมีคําเขียนไว้แล้วว่า ‘องค์พระผู้เป็นเจ้าตรัสว่า “เราจะพูดกับชนชาตินี้โดยคนต่างภาษาและโดยริมฝีปากของคนต่างด้าว ถึงกระนั้นเขาก็จะไม่ฟังเรา”’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 22, 'เหตุฉะนั้นการพูดภาษาต่างๆจึงไม่เป็นหมายสําคัญแก่คนที่เชื่อ แต่เป็นหมายสําคัญแก่คนที่ไม่เชื่อ แต่การพยากรณ์นั้นไม่ใช่สําหรับคนที่ไม่เชื่อ แต่สําหรับคนที่เชื่อแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 23, 'เหตุฉะนั้นถ้าทั้งคริสตจักรมีการประชุมพร้อมกัน แล้วคนทั้งปวงต่างก็พูดภาษาต่างๆ และมีคนที่รู้ไม่ถึงหรือคนที่ไม่เชื่อเข้ามา เขาจะมิเห็นไปว่าท่านทั้งหลายคลั่งไปแล้วหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 24, 'แต่ถ้าทุกคนพยากรณ์ คนที่ไม่เชื่อหรือคนที่รู้ไม่ถึงเข้ามา ทุกคนก็จะทําให้เขารู้สํานึก และทําให้เขาพิจารณาใจของตนเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 25, 'ดังนั้นแหละความลับที่ซ่อนอยู่ในใจของเขาจะเด่นชัดขึ้น เขาก็จะกราบลงนมัสการพระเจ้ากล่าวว่า พระเจ้าทรงสถิตอยู่ท่ามกลางพวกท่านอย่างแน่นอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 26, 'พี่น้องทั้งหลาย เมื่อท่านประชุมกัน ทุกคนก็มีเพลงสดุดี ทุกคนก็มีคําสั่งสอน ทุกคนก็พูดภาษาต่างๆ ทุกคนก็มีคําวิวรณ์ ทุกคนก็แปลข้อความ จะว่าอย่างไรกัน ท่านจงกระทําทุกสิ่งทุกอย่างเพื่อให้จําเริญขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 27, 'ถ้าผู้ใดจะพูดภาษาต่างๆ จงให้พูดเพียงสองคนหรืออย่างมากที่สุดก็สามคน และให้พูดทีละคน และให้อีกคนหนึ่งแปล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 28, 'แต่ถ้าไม่มีผู้ใดแปลก็ให้คนเหล่านั้นอยู่เงียบๆในที่ประชุมคริสตจักร และให้พูดกับตัวเอง และทูลต่อพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 29, 'ฝ่ายพวกผู้พยากรณ์นั้นให้พูดสองหรือสามคน และให้คนอื่นวินิจฉัยข้อความที่เขาพูดนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 30, 'ถ้ามีสิ่งใดทรงสําแดงแก่คนอื่นที่นั่งอยู่ด้วยกัน ให้คนแรกนั้นนิ่งเสียก่อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 31, 'เพราะว่าท่านทั้งหลายพยากรณ์ได้ทีละคน เพื่อให้ทุกคนได้ความรู้ และได้รับการปลอบประโลมใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 32, 'วิญญาณของพวกผู้พยากรณ์นั้นย่อมอยู่ในบังคับพวกผู้พยากรณ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 33, 'เพราะว่าพระเจ้าไม่ใช่ผู้ก่อให้เกิดความสับสนวุ่นวาย แต่ทรงเป็นผู้ก่อให้เกิดสันติสุข เหมือนที่ได้เกิดขึ้นในบรรดาคริสตจักรแห่งวิสุทธิชนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 34, 'จงให้พวกผู้หญิงทั้งหลายของท่านนิ่งเสียในที่ประชุมคริสตจักร เพราะไม่ได้รับอนุญาตให้พูด แต่ให้เขาอยู่ใต้บังคับบัญชา เหมือนที่พระราชบัญญัติสั่งไว้นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 35, 'ถ้าเขาอยากรู้สิ่งใด ก็ให้เขาถามสามีที่บ้าน เพราะว่าการที่ผู้หญิงจะพูดในที่ประชุมคริสตจักรนั้นก็เป็นสิ่งที่น่าอาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 36, 'อะไรกัน พระวจนะของพระเจ้าเกิดมาจากพวกท่านหรือ ได้ประทานมาถึงท่านแต่พวกเดียวหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 37, 'ถ้าผู้ใดถือว่าตนเป็นผู้พยากรณ์หรืออยู่ฝ่ายจิตวิญญาณ ก็ให้เขายอมรับว่า ข้อความซึ่งข้าพเจ้าเขียนมาถึงท่านนั้นเป็นพระบัญญัติขององค์พระผู้เป็นเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 38, 'แต่ถ้าผู้ใดเฉยเมยต่อข้อความนี้ ก็ให้เขาเฉยเมยต่อไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 39, 'เหตุฉะนั้นพี่น้องทั้งหลาย จงตั้งใจปรารถนาที่จะพยากรณ์ ที่เขาพูดภาษาต่างๆก็อย่าห้ามเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 40, 'แต่สิ่งสารพัดซึ่งจะกระทํานั้น จงกระทําตามสมควร และให้เป็นระเบียบเรียบร้อย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 1, 'ยิ่งกว่านี้ พี่น้องทั้งหลาย ข้าพเจ้าขอให้ท่านคํานึงถึงข่าวประเสริฐที่ข้าพเจ้าเคยประกาศแก่ท่านทั้งหลาย ซึ่งท่านได้ยอมรับไว้ อันเป็นฐานซึ่งท่านทั้งหลายตั้งมั่นอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 2, 'และซึ่งทําให้ท่านรอดด้วย ถ้าท่านยึดหลักคําสอนที่ข้าพเจ้าได้ประกาศไว้แก่ท่านทั้งหลายนั้น เว้นเสียแต่ท่านได้เชื่ออย่างไร้ประโยชน์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 3, 'เรื่องซึ่งข้าพเจ้ารับไว้นั้น ข้าพเจ้าได้ประกาศแก่ท่านทั้งหลายก่อน คือว่าพระคริสต์ได้ทรงวายพระชนม์เพราะบาปของเราทั้งหลาย ตามที่เขียนไว้ในพระคัมภีร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 4, 'และทรงถูกฝังไว้ แล้ววันที่สามพระองค์ทรงเป็นขึ้นมาใหม่ตามที่มีเขียนไว้ในพระคัมภีร์นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 5, 'พระองค์ทรงปรากฏแก่เคฟาส แล้วแก่อัครสาวกสิบสองคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 6, 'ภายหลังพระองค์ทรงปรากฏแก่พวกพี่น้องกว่าห้าร้อยคนในคราวเดียว ซึ่งส่วนมากยังอยู่จนถึงทุกวันนี้ แต่บางคนก็ล่วงหลับไปแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 7, 'ภายหลังพระองค์ทรงปรากฏแก่ยากอบ แล้วแก่อัครสาวกทั้งหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 8, 'ครั้นหลังที่สุดพระองค์ทรงปรากฏแก่ข้าพเจ้าด้วย ผู้เป็นเสมือนเด็กที่คลอดก่อนกําหนด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 9, 'เพราะว่าข้าพเจ้าเป็นผู้น้อยที่สุดในพวกอัครสาวก และไม่สมควรจะได้ชื่อว่าเป็นอัครสาวก เพราะว่าข้าพเจ้าได้ข่มเหงคริสตจักรของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 10, 'แต่ว่าข้าพเจ้าเป็นอยู่อย่างที่เป็นอยู่นี้ก็เนื่องด้วยพระคุณของพระเจ้า และพระคุณของพระองค์ซึ่งได้ทรงประทานแก่ข้าพเจ้านั้นมิได้ไร้ประโยชน์ แต่ข้าพเจ้ากลับทํางานมากกว่าพวกเขาเสียอีก มิใช่ตัวข้าพเจ้าเองทํา แต่เป็นด้วยพระคุณของพระเจ้าซึ่งดํารงอยู่กับข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 11, 'เหตุฉะนั้นแม้ตัวข้าพเจ้าก็ดี หรือพวกเขาก็ดี เราทั้งหลายก็ได้ประกาศอย่างที่กล่าวมานั้น และท่านทั้งหลายก็ได้เชื่ออย่างนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 12, 'แต่ถ้าเทศนาว่าพระคริสต์ได้ทรงฟื้นขึ้นมาจากตายแล้ว เหตุใดพวกท่านบางคนยังกล่าวว่า การฟื้นขึ้นมาจากตายไม่มี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 13, 'แต่ถ้าการฟื้นขึ้นมาจากตายไม่มี พระคริสต์ก็หาได้ทรงเป็นขึ้นมาไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 14, 'ถ้าพระคริสต์มิได้ทรงเป็นขึ้นมา การเทศนาของเรานั้นก็เปล่าประโยชน์ ทั้งความเชื่อของท่านทั้งหลายก็เปล่าประโยชน์ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 15, 'และก็จะปรากฏว่าเราอ้างพยานเท็จในเรื่องพระเจ้า เพราะเราอ้างพยานถึงพระเจ้าว่าพระองค์ได้ทรงบันดาลให้พระคริสต์เป็นขึ้นมา แต่ถ้าคนตายไม่เป็นขึ้นมาแล้ว พระองค์ก็ไม่ได้ทรงบันดาลให้พระคริสต์เป็นขึ้นมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 16, 'เพราะว่าถ้าคนตายไม่เป็นขึ้นมา พระคริสต์ก็ไม่ได้ทรงเป็นขึ้นมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 17, 'และถ้าพระคริสต์ไม่ได้ทรงเป็นขึ้นมา ความเชื่อของท่านก็ไร้ประโยชน์ ท่านก็ยังตกอยู่ในบาปของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 18, 'และคนทั้งหลายที่ล่วงหลับในพระคริสต์ ก็พินาศไปด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 19, 'ถ้าพวกเรามีความหวังใจในพระคริสต์ในชีวิตนี้เท่านั้น เราก็เป็นพวกที่น่าสังเวชที่สุดในบรรดาคนทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 20, 'แต่บัดนี้พระคริสต์ทรงเป็นขึ้นมาจากความตายแล้ว และทรงเป็นผลแรกในพวกคนทั้งหลายที่ได้ล่วงหลับไปแล้วนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 21, 'เพราะว่าความตายได้อุบัติขึ้นเพราะมนุษย์คนหนึ่งเป็นเหตุฉันใด การเป็นขึ้นมาจากความตายก็ได้อุบัติขึ้นเพราะมนุษย์ผู้หนึ่งเป็นเหตุฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 22, 'เพราะว่าคนทั้งปวงต้องตายเกี่ยวเนื่องกับอาดัมฉันใด คนทั้งปวงก็จะกลับได้ชีวิตเกี่ยวเนื่องกับพระคริสต์ฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 23, 'แต่ว่าทุกคนจะเป็นไปตามลําดับ คือพระคริสต์ทรงเป็นผลแรก แล้วภายหลังก็คือคนทั้งหลายที่เป็นของพระคริสต์ ในเมื่อพระองค์จะเสด็จมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 24, 'ต่อจากนั้นจะเป็นวาระที่สุด เมื่อพระองค์จะทรงมอบอาณาจักรไว้แด่พระเจ้าคือพระบิดา เมื่อพระองค์จะได้ทรงทําลายการปกครอง และสิทธิอํานาจและอานุภาพหมดแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 25, 'เพราะว่าพระองค์จะต้องทรงปกครองอยู่ก่อน จนกว่าพระองค์จะได้ทรงปราบศัตรูทั้งสิ้นให้อยู่ใต้พระบาทของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 26, 'ศัตรูตัวสุดท้ายที่จะทรงทําลายนั้นก็คือความตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 27, 'เพราะว่าพระองค์ทรงปราบสิ่งสารพัดลงใต้พระบาทของพระองค์แล้ว แต่เมื่อพระองค์ตรัสว่าทรงปราบสิ่งสารพัดลงนั้น ก็เป็นที่ทราบชัดว่ายกเว้นองค์พระเจ้าผู้ทรงปราบสิ่งสารพัดให้อยู่ใต้พระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 28, 'เมื่อสิ่งสารพัดถูกปราบให้อยู่ใต้พระองค์แล้ว เมื่อนั้นองค์พระบุตรก็จะอยู่ใต้พระเจ้าผู้ทรงปราบสิ่งสารพัดให้อยู่ใต้พระองค์ เพื่อพระเจ้าจะทรงเป็นเอกเป็นใหญ่ในสิ่งสารพัดทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 29, 'มิฉะนั้น คนเหล่านั้นที่รับบัพติศมาสําหรับคนตายเขาทําอะไรกัน ถ้าคนตายจะไม่เป็นขึ้นมา เหตุไฉนจึงมีคนรับบัพติศมาสําหรับคนตายเล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 30, 'และเหตุไฉนเราจึงต้องเผชิญกับภัยอันตรายตลอดเวลาเล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 31, 'ข้าพเจ้าขอยืนยันโดยอ้างความภูมิใจซึ่งข้าพเจ้ามีอยู่ในท่านทั้งหลายโดยพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเราว่า ข้าพเจ้าตายทุกวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 32, 'ถ้าตามลักษณะของมนุษย์ ข้าพเจ้าต่อสู้กับสัตว์ป่าในเมืองเอเฟซัสนั้น จะเป็นประโยชน์อะไรแก่ข้าพเจ้า ถ้าคนตายไม่ได้เป็นขึ้นมาอีก ‘ให้เรากินและดื่มเถิด เพราะว่าพรุ่งนี้เราจะตาย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 33, 'อย่าหลงเลย การคบกับคนชั่วย่อมทําให้นิสัยที่ดีเสียไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 34, 'จงตื่นขึ้นสู่ความชอบธรรมและอย่าทําผิดอีกเลย เพราะว่าบางคนไม่มีความรู้เรื่องพระเจ้าเสียเลย ที่ข้าพเจ้าว่านี้ก็ให้ท่านมีความละอาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 35, 'แต่บางคนจะถามว่า “คนตายจะเป็นขึ้นมาอย่างไรได้ เมื่อเขาเป็นขึ้นมาจะมีรูปกายเป็นอย่างไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 36, 'ท่านคนเขลา เมล็ดที่ท่านหว่านลงนั้น ถ้าไม่ตายเสียก่อนแล้วจะงอกขึ้นใหม่ไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 37, 'เมล็ดข้าวที่ท่านหว่านนั้น จะเป็นข้าวสาลีหรือพืชอื่นๆก็ดี ท่านมิได้หว่านสิ่งที่เป็นรูปร่างของต้นที่จะงอกขึ้นมา แต่ได้หว่านเมล็ดเท่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 38, 'แต่พระเจ้าทรงประทานรูปร่างต้นของเมล็ดนั้นตามที่พระองค์ทรงเห็นชอบ และทรงประทานรูปร่างแก่เมล็ดพืชทุกพรรณตามชนิดของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 39, 'เพราะว่าเนื้อนั้นไม่เหมือนกันหมดทุกอย่าง เนื้อมนุษย์ก็อย่างหนึ่ง เนื้อสัตว์สี่เท้าก็อย่างหนึ่ง เนื้อปลาก็อย่างหนึ่ง เนื้อนกก็อย่างหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 40, 'ร่างกายสําหรับสวรรค์ก็มี และร่างกายสําหรับโลกก็มี แต่ว่าสง่าราศีของร่างกายสําหรับสวรรค์ก็อย่างหนึ่ง และสง่าราศีของร่างกายสําหรับโลกก็อย่างหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 41, 'สง่าราศีของดวงอาทิตย์ก็อย่างหนึ่ง สง่าราศีของดวงจันทร์ก็อย่างหนึ่ง สง่าราศีของดวงดาวก็อย่างหนึ่ง แท้ที่จริงสง่าราศีของดาวดวงหนึ่งก็ต่างกันกับสง่าราศีของดาวดวงอื่นๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 42, 'การซึ่งจะเป็นขึ้นมาจากความตายนั้นก็เหมือนกัน สิ่งที่หว่านลงนั้นเป็นของที่จะเปื่อยเน่า สิ่งที่เป็นขึ้นมาใหม่นั้นก็จะไม่รู้จักเปื่อยเน่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 43, 'สิ่งที่หว่านลงนั้นไร้เกียรติ สิ่งที่เป็นขึ้นมาใหม่ก็จะมีสง่าราศี สิ่งที่หว่านลงนั้นอ่อนกําลัง สิ่งที่เป็นขึ้นมาใหม่ก็จะมีอํานาจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 44, 'สิ่งที่หว่านลงนั้นก็เป็นกายธรรมดา สิ่งที่เป็นขึ้นมาก็จะเป็นกายวิญญาณ กายธรรมดามี และกายวิญญาณก็มี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 45, 'เหมือนมีเขียนไว้แล้วว่า ‘ทรงสร้างมนุษย์คนเดิมคืออาดัมเป็นจิตวิญญาณมีชีวิตอยู่’ แต่อาดัมผู้ซึ่งมาภายหลังนั้นเป็นวิญญาณผู้ประสาทชีวิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 46, 'แต่ร่างกายซึ่งเกิดก่อนนั้นหาใช่เป็นกายวิญญาณไม่ แต่เป็นกายธรรมดา แล้วภายหลังจึงเป็นกายวิญญาณ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 47, 'มนุษย์เดิมนั้นกําเนิดจากดินและเป็นมนุษย์ดิน มนุษย์ที่สองเป็นองค์พระผู้เป็นเจ้าเสด็จมาจากสวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 48, 'มนุษย์ดินผู้นั้นเป็นอย่างไร มนุษย์ดินทุกคนก็เป็นอย่างนั้น มนุษย์สวรรค์ผู้นั้นเป็นอย่างไร มนุษย์สวรรค์ทุกคนก็เป็นอย่างนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 49, 'และเมื่อเราเกิดมามีลักษณะสมกับมนุษย์ดินแล้ว เราก็จะมีลักษณะสมกับมนุษย์สวรรค์ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 50, 'แต่พี่น้องทั้งหลาย ข้าพเจ้าหมายความว่า เนื้อและเลือดจะรับอาณาจักรของพระเจ้าเป็นมรดกไม่ได้ และสิ่งซึ่งเปื่อยเน่าจะรับสิ่งซึ่งไม่รู้จักเปื่อยเน่าเป็นมรดกก็ไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 51, 'ดูก่อน ข้าพเจ้ามีความลึกลับที่จะบอกแก่ท่าน คือว่าเราจะไม่ล่วงหลับหมดทุกคน แต่เราจะถูกเปลี่ยนแปลงใหม่หมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 52, 'ในชั่วขณะเดียว ในพริบตาเดียว เมื่อเป่าแตรครั้งสุดท้าย เพราะว่าจะมีเสียงแตร และคนที่ตายแล้วจะเป็นขึ้นมาปราศจากเปื่อยเน่า แล้วเราทั้งหลายจะถูกเปลี่ยนแปลงใหม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 53, 'เพราะว่าสิ่งซึ่งเปื่อยเน่านี้ต้องสวมซึ่งไม่เปื่อยเน่า และซึ่งจะตายนี้ต้องสวมซึ่งจะไม่รู้ตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 54, 'เมื่อสิ่งซึ่งเปื่อยเน่านี้จะสวมซึ่งไม่เปื่อยเน่า และซึ่งจะตายนี้จะสวมซึ่งไม่รู้จักตาย เมื่อนั้นตามซึ่งเขียนไว้แล้วจะสําเร็จว่า ‘ความตายก็ถูกกลืนไปด้วยการมีชัย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 55, 'โอ ความตาย เหล็กในของเจ้าอยู่ที่ไหน โอ หลุมฝังศพ ชัยชนะของเจ้าอยู่ที่ไหน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 56, 'เหล็กในของความตายนั้นคือบาป และฤทธิ์ของบาปคือพระราชบัญญัติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 57, 'แต่จงขอบพระคุณแด่พระเจ้า ผู้ทรงประทานชัยชนะแก่เราทั้งหลายโดยพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 58, 'เหตุฉะนั้นพี่น้องที่รักของข้าพเจ้า ท่านจงตั้งมั่นอยู่ อย่าหวั่นไหว จงปฏิบัติงานขององค์พระผู้เป็นเจ้าให้บริบูรณ์ทุกเวลา ด้วยว่าท่านทั้งหลายรู้ว่า โดยองค์พระผู้เป็นเจ้าการของท่านจะไร้ประโยชน์ก็หามิได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 1, 'แล้วเรื่องการถวายทรัพย์เพื่อช่วยวิสุทธิชนนั้น ข้าพเจ้าได้สั่งคริสตจักรที่แคว้นกาลาเทียไว้อย่างไร ก็ขอให้ท่านจงกระทําเหมือนกันด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 2, 'ทุกวันต้นสัปดาห์ให้พวกท่านทุกคนเก็บผลประโยชน์ที่ได้รับไว้บ้าง ตามที่พระเจ้าได้ทรงให้ท่านจําเริญ เพื่อจะไม่ต้องถวายทรัพย์เมื่อข้าพเจ้ามา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 3, 'เมื่อข้าพเจ้ามาถึงแล้ว พวกท่านเห็นชอบจะรับรองผู้ใดโดยจดหมายของท่าน ข้าพเจ้าจะใช้ผู้นั้นถือของถวายของท่านไปยังกรุงเยรูซาเล็ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 4, 'และถ้าสมควรข้าพเจ้าจะไปด้วย คนเหล่านั้นก็จะไปพร้อมกับข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 5, 'เพราะเมื่อข้าพเจ้าข้ามแคว้นมาซิโดเนียแล้วข้าพเจ้าจะมาหาท่าน เพราะข้าพเจ้าตั้งใจว่าจะไปทางมาซิโดเนีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 6, 'และข้าพเจ้าอาจจะพักอยู่กับท่าน บางทีอาจจะอยู่จนถึงสิ้นฤดูหนาวก็เป็นได้ แล้วข้าพเจ้าจะไปทางไหน พวกท่านจะได้ส่งข้าพเจ้าไปทางนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 7, 'เพราะว่าข้าพเจ้าไม่อยากจะพบท่านเมื่อผ่านไปเท่านั้น แต่ข้าพเจ้าหวังใจว่า ถ้าองค์พระผู้เป็นเจ้าทรงโปรด ข้าพเจ้าจะค้างอยู่กับท่านนานๆหน่อย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 8, 'แต่ข้าพเจ้าจะอยู่ที่เมืองเอเฟซัสจนถึงเทศกาลเพ็นเทคอสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 9, 'เพราะว่าที่นี่มีประตูเปิดให้ข้าพเจ้าอย่างกว้างขวางน่าจะเกิดผล ทั้งผู้ขัดขวางก็มีเป็นอันมากด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 10, 'แล้วถ้าทิโมธีมาหาท่านจงให้เขาอยู่กับท่านโดยปราศจากความกลัว เพราะว่าเขาทํางานขององค์พระผู้เป็นเจ้าเหมือนกับข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 11, 'เหตุฉะนั้นอย่าให้ผู้ใดประมาทเขา แต่จงช่วยให้เขาเดินทางไปโดยสันติสุขเพื่อเขาจะมาถึงข้าพเจ้าได้ เพราะข้าพเจ้ากําลังคอยเขากับพวกพี่น้องอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 12, 'อปอลโล ซึ่งเป็นพี่น้องของเรานั้น ข้าพเจ้าได้คะยั้นคะยอให้ไปเยี่ยมท่านทั้งหลายพร้อมกับพวกพี่น้อง แต่ท่านไม่จุใจที่จะไปเดี๋ยวนี้ เมื่อมีโอกาสท่านจึงจะไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 13, 'ท่านทั้งหลายจงระมัดระวัง จงมั่นคงในความเชื่อ จงเป็นลูกผู้ชายแท้ จงเข้มแข็ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 14, 'ทุกสิ่งซึ่งท่านกระทํานั้น จงกระทําด้วยความรัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 15, 'พี่น้องทั้งหลาย (ท่านรู้ว่าครอบครัวของสเทฟานัส เป็นผลแรกในแคว้นอาคายา และพวกเขาได้ถวายตัวไว้ในการปรนนิบัติวิสุทธิชนทั้งปวง)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 16, 'ข้าพเจ้าขอให้ท่านทั้งหลายอยู่ใต้บังคับคนเช่นนั้น และคนทั้งปวงที่ช่วยทําการด้วยกันนั้นกับเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 17, 'ที่สเทฟานัส และฟอร์ทูนาทัส และอาคายคัสมาแล้วนั้น ข้าพเจ้าก็ชื่นชมยินดี เพราะว่าสิ่งซึ่งท่านทั้งหลายขาดนั้น เขาเหล่านั้นได้มาทําให้ครบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 18, 'เพราะเขาทําให้จิตใจของข้าพเจ้าและของท่านทั้งหลายชุ่มชื่น ฉะนั้นท่านทั้งหลายจงรับรองคนเช่นนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 19, 'คริสตจักรทั้งหลายในแคว้นเอเชียฝากความคิดถึงมายังท่านทั้งหลาย อาควิลลาและปริสสิลลากับคริสตจักรที่อยู่ในบ้านของเขา ฝากความคิดถึงมากมายในองค์พระผู้เป็นเจ้ามายังท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 20, 'พี่น้องทุกคนฝากความคิดถึงมายังท่าน ท่านจงทักทายปราศรัยกันด้วยธรรมเนียมจุบอันบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 21, 'คําแสดงความนับถือนี้เป็นลายมือของข้าพเจ้า เปาโล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 22, 'ถ้าผู้ใดไม่รักพระเยซูคริสต์เจ้า ก็ขอให้ผู้นั้นถูกสาปแช่ง องค์พระผู้เป็นเจ้าจะเสด็จมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 23, 'ขอพระคุณของพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเราสถิตอยู่กับท่านทั้งหลายเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 24, 'ความรักของข้าพเจ้ามีอยู่ต่อท่านทั้งหลายในพระเยซูคริสต์เสมอ เอเมน [จดหมายฉบับแรกถึงชาวโครินธ์ เขียนจากเมืองฟีลิปปี และส่งโดยสเทฟานัส ฟอร์ทูนาทัส อาคายคัสและทิโมธี]');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 1, 'เปาโล ผู้เป็นอัครสาวกของพระเยซูคริสต์ตามพระประสงค์ของพระเจ้า และทิโมธีน้องของเรา เรียน คริสตจักรของพระเจ้าที่เมืองโครินธ์ และบรรดาวิสุทธิชนที่อยู่ทั่วแคว้นอาคายา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 2, 'ขอพระคุณและสันติสุขซึ่งมาจากพระเจ้าพระบิดาของเรา และจากพระเยซูคริสต์เจ้า จงมีแก่ท่านทั้งหลายเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 3, 'จงสรรเสริญพระเจ้า พระบิดาแห่งพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเรา พระบิดาผู้ทรงความเมตตา พระเจ้าแห่งการปลอบประโลมใจทุกอย่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 4, 'พระองค์ผู้ทรงปลอบประโลมใจเราในการทุกข์ยากทั้งสิ้นของเรา เพื่อเราจะสามารถปลอบประโลมใจคนเหล่านั้นที่มีความทุกข์ยากอย่างใดอย่างหนึ่งได้ ด้วยการปลอบประโลมใจซึ่งตัวเราเองได้รับจากพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 5, 'เพราะว่าเรามีส่วนทนทุกข์กับพระคริสต์มากฉันใด การปลอบประโลมใจของเราเนื่องจากพระคริสต์ก็มากฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 6, 'ที่เราทนความทุกข์ยากนั้น ก็เพื่อให้ท่านทั้งหลายได้ความชูใจและความรอด หรือที่เราได้รับการปลอบประโลมใจนั้น ก็เพื่อให้ท่านทั้งหลายได้รับความชูใจและความรอด ซึ่งทําให้ท่านทั้งหลายเพียรสู้ทนความทุกข์เหมือนอย่างเราได้ทนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 7, 'เราจึงมีความหวังแน่นอนในท่านทั้งหลาย เพราะเรารู้ว่าท่านทั้งหลายได้มีส่วนในความทุกข์ยากฉันใด ท่านทั้งหลายจะได้มีส่วนในการปลอบประโลมใจฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 8, 'พี่น้องทั้งหลาย เราอยากให้ท่านทราบถึงความทุกข์ยากที่เกิดแก่เราในแคว้นเอเชีย ซึ่งทําให้เราหนักใจจนเหลือกําลัง จนเราเกือบหมดหวังที่จะเอาชีวิตรอดมาได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 9, 'ที่จริงเราคาดว่าเราถึงที่ตายแล้ว แต่ที่เป็นเช่นนี้ก็เพื่อมิให้เราไว้ใจในตนเอง แต่ให้ไว้ใจในพระเจ้าผู้ทรงโปรดให้คนทั้งปวงฟื้นจากความตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 10, 'พระองค์ทรงช่วยเราให้พ้นจากความตายอันใหญ่หลวง และพระองค์กําลังทรงช่วยเราให้พ้น เราไว้ใจพระองค์ว่า พระองค์จะทรงช่วยเราให้พ้นต่อไปอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 11, 'ท่านทั้งหลายจะช่วยเราได้ด้วยการอธิษฐานเพื่อเรา เพื่อว่าคนเป็นอันมากจะได้ขอบพระคุณเพราะเรา เนื่องจากของประทานที่ทรงประทานแก่เรา อันเป็นการทรงตอบคําอธิษฐานของคนเป็นอันมากนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 12, 'นี่เป็นสิ่งที่เราชื่นชมยินดีได้ คือใจสํานึกผิดชอบของเราเป็นพยานว่าเราได้ประพฤติตนเป็นที่ประจักษ์แก่โลก และยิ่งกว่านั้นก็คือการประพฤติต่อท่านทั้งหลาย ด้วยน้ําใจบริสุทธิ์ และด้วยความจริงใจซึ่งมาจากพระเจ้า และมิใช่ตามปัญญาฝ่ายเนื้อหนัง แต่ตามพระคุณของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 13, 'เพราะว่าเราไม่ได้เขียนเรื่องอื่นถึงท่าน นอกจากเรื่องซึ่งท่านได้อ่านและยอมรับแล้ว และข้าพเจ้าก็หวังว่าท่านจะยอมรับโดยตลอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 14, 'ตามที่พวกท่านยอมรับเราบ้างแล้วว่า ในวันของพระเยซูเจ้าท่านก็ภูมิใจในเราได้ เช่นเดียวกับที่เราจะภูมิใจในท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 15, 'และในความไว้ใจนี้ ข้าพเจ้าได้ประสงค์ว่าจะไปเยี่ยมพวกท่านก่อน เพื่อท่านจะได้ประโยชน์สองเท่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 16, 'ข้าพเจ้าใคร่จะแวะเยี่ยมพวกท่านระหว่างที่เดินทางไปยังแคว้นมาซิโดเนีย และเมื่อข้าพเจ้ากลับจากแคว้นมาซิโดเนีย ก็จะแวะเยี่ยมท่านอีก ท่านก็จะได้ส่งให้ข้าพเจ้าออกเดินทางไปยังแคว้นยูเดีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 17, 'ฉะนั้นเมื่อข้าพเจ้าหมายที่จะทําอย่างนั้น ข้าพเจ้าโลเลหรือ หรือสิ่งที่ข้าพเจ้ามุ่งหมายไว้ข้าพเจ้ากะโครงการอย่างเนื้อหนังหรือ ซึ่งพร้อมที่จะกล่าวว่า มา ไม่มา ส่งๆไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 18, 'แต่พระเจ้าทรงสัตย์จริงแน่ฉันใด คําของเราที่กล่าวกับท่านก็มิใช่เป็นคํารับ หรือปฏิเสธ ส่งๆไปแน่ฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 19, 'เพราะว่าพระบุตรของพระเจ้าคือพระเยซูคริสต์ ผู้ซึ่งพวกเรา คือข้าพเจ้ากับสิลวานัสและทิโมธี ได้ประกาศแก่พวกท่านนั้น ไม่ใช่ จริง ไม่จริง ส่งๆไป แต่โดยพระองค์นั้นล้วนแต่จริงทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 20, 'บรรดาพระสัญญาของพระเจ้าก็เป็นจริงโดยพระเยซู เพราะเหตุนี้เราจึงพูดว่าเอเมนโดยพระองค์ เป็นที่ถวายเกียรติยศแด่พระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 21, 'บัดนี้ผู้ซึ่งทรงตั้งเรากับท่านทั้งหลายไว้ในพระคริสต์ และได้ทรงเจิมเราไว้นั้น ก็คือพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 22, 'และพระองค์ทรงประทับตราเรา และประทานพระวิญญาณไว้ในใจของเราเป็นมัดจําด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 23, 'ยิ่งกว่านั้นขอพระเจ้าทรงเป็นพยานฝ่ายจิตใจของข้าพเจ้าว่า ที่ข้าพเจ้ายังไม่ได้ไปถึงเมืองโครินธ์นั้น ก็เพื่อจะงดโทษพวกท่านไว้ก่อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 24, 'เราไม่ใช่เป็นนายบังคับความเชื่อของพวกท่าน แต่ว่าเราเป็นผู้อุปการะความยินดีของท่าน เพราะท่านตั้งมั่นอยู่โดยความเชื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 1, 'แต่ข้าพเจ้าได้ตั้งใจไว้ว่า เมื่อมีความทุกข์อยู่ จะไม่มาหาพวกท่านอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 2, 'เพราะถ้าข้าพเจ้าทําให้พวกท่านเป็นทุกข์ ใครเล่าจะทําให้ข้าพเจ้ามีความยินดี ก็คือคนที่ข้าพเจ้าทําให้มีความทุกข์นั่นแหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 3, 'และข้าพเจ้าได้เขียนข้อความนั้นมาถึงท่าน เพื่อว่าเมื่อข้าพเจ้ามา ข้าพเจ้าจะไม่ได้รับความทุกข์จากคนเหล่านั้น ที่ควรจะทําให้ข้าพเจ้ามีความชื่นชมยินดี ข้าพเจ้าไว้ใจในพวกท่านว่า ความยินดีของข้าพเจ้าก็เป็นความยินดีของท่านด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 4, 'เพราะว่าข้าพเจ้าเขียนถึงท่านเพราะข้าพเจ้ามีความทุกข์ระทมใจมาก และน้ําตาไหลมากมาย มิใช่เพื่อจะทําให้ท่านเป็นทุกข์ แต่เพื่อจะให้ท่านรู้จักความรักอย่างมากมายซึ่งข้าพเจ้ามีต่อท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 5, 'แต่ถ้าผู้ใดเป็นต้นเหตุทําให้เกิดความทุกข์ ผู้นั้นก็มิได้ทําให้ข้าพเจ้าเป็นทุกข์แต่คนเดียว แต่ได้ทําให้พวกท่านเป็นทุกข์บ้างด้วย เพราะข้าพเจ้าไม่อยากจะปรักปรําพวกท่านจนเหลือเกิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 6, 'ที่คนส่วนมากได้ลงโทษคนเช่นนั้นก็พอสมควรแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 7, 'ฉะนั้นท่านทั้งหลายควรจะยกโทษให้ผู้นั้น และปลอบประโลมใจเขาต่างหาก กลัวว่าคนเช่นนั้นจะจมลงในความทุกข์เหลือล้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 8, 'ดังนั้นข้าพเจ้าขอวิงวอนท่านให้ยืนยันความรักต่อคนนั้นใหม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 9, 'นี่คือเหตุที่ข้าพเจ้าได้เขียนถึงท่าน หวังจะลองใจท่านดูว่า ท่านจะยอมเชื่อฟังทุกประการหรือไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 10, 'ถ้าพวกท่านจะยกโทษให้ผู้ใด ข้าพเจ้าก็ยกโทษให้ผู้นั้นด้วย เพราะถ้าข้าพเจ้ายกโทษให้คนใดๆ ข้าพเจ้าได้ยกโทษให้ผู้นั้นเพราะเห็นแก่ท่านทั้งหลายต่อพระพักตร์พระคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 11, 'เพื่อไม่ให้ซาตานมีชัยเหนือเรา เพราะเรารู้กลอุบายของมันแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 12, 'นอกจากนี้เมื่อข้าพเจ้าไปถึงเมืองโตรอัสเพื่อประกาศข่าวประเสริฐของพระคริสต์นั้น มีประตูเปิดให้แก่ข้าพเจ้าโดยองค์พระผู้เป็นเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 13, 'ข้าพเจ้ายังไม่มีความสบายใจเลย เพราะข้าพเจ้าไม่ได้พบทิตัสน้องของข้าพเจ้าที่นั่น ข้าพเจ้าจึงลาพวกนั้นเดินทางไปยังแคว้นมาซิโดเนีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 14, 'แต่ขอบพระคุณพระเจ้าผู้ทรงให้เรามีชัยเสมอโดยพระคริสต์ และทรงโปรดประทานกลิ่นหอมแห่งความรู้ของพระองค์ให้ปรากฏด้วยตัวเราทุกแห่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 15, 'เพราะว่าเราเป็นกลิ่นอันหอมหวานของพระคริสต์จําเพาะพระเจ้า ในหมู่คนที่รอด และในหมู่คนที่พินาศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 16, 'ฝ่ายหนึ่งเป็นกลิ่นแห่งความตายซึ่งนําไปสู่ความตาย และอีกฝ่ายหนึ่งเป็นกลิ่นหอมแห่งชีวิตซึ่งนําไปสู่ชีวิต ใครเล่าจะมีความสามารถเหมาะสมกับพันธกิจเหล่านี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 17, 'เพราะว่า เราไม่เหมือนคนเป็นอันมากที่ทําให้พระวจนะของพระเจ้าเสื่อมเสีย แต่ว่าเราประกาศโดยอาศัยพระคริสต์ด้วยความจริงใจ อย่างคนที่มาจากพระเจ้าและอยู่ในสายพระเนตรของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 1, 'เรากําลังจะแนะนําตัวเราเองหรือ หรือว่าเราต้องการหนังสือแนะนําตัวให้แก่พวกท่านเหมือนอย่างคนบางคนหรือ เราต้องการหนังสือแนะนําตัวจากพวกท่านหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 2, 'ท่านเองเป็นหนังสือของเราจารึกไว้ที่ดวงใจของเรา ให้คนทั้งปวงได้รู้และได้อ่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 3, 'ท่านปรากฏเป็นหนังสือของพระคริสต์ซึ่งเราเป็นผู้ปรนนิบัติ และได้เขียนไว้ มิใช่ด้วยน้ําหมึก แต่ด้วยพระวิญญาณของพระเจ้าผู้ทรงพระชนม์ และมิได้เขียนไว้ที่แผ่นศิลา แต่เขียนไว้ที่แผ่นดวงใจมนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 4, 'และเรามีความไว้ใจในพระเจ้าโดยพระคริสต์อย่างนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 5, 'มิใช่เราจะคิดถือว่าสิ่งหนึ่งสิ่งใดเกิดจากความสามารถของเราเอง แต่ว่าความสามารถของเรามาจากพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 6, 'พระองค์จึงทรงโปรดประทานให้เราสามารถเป็นผู้ปฏิบัติได้ตามพันธสัญญาใหม่ มิใช่ตามตัวอักษร แต่ตามพระวิญญาณ ด้วยว่าตัวอักษรนั้นประหารให้ตาย แต่พระวิญญาณนั้นประทานชีวิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 7, 'แต่ถ้าการปฏิบัติที่นําไปถึงความตายตามตัวอักษรซึ่งได้เขียนและจารึกไว้ที่แผ่นศิลานั้น ยังมีรัศมี จนชนชาติอิสราเอลไม่สามารถจ้องมองหน้าของโมเสสได้เพราะรัศมีจากใบหน้าของท่านซึ่งเป็นรัศมีที่กําลังเสื่อมสูญไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 8, 'ดังนั้นการปฏิบัติตามพระวิญญาณจะไม่มีรัศมียิ่งกว่านั้นอีกหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 9, 'เพราะว่าถ้าการรับใช้สําหรับปรับโทษยังมีรัศมี การรับใช้สําหรับความชอบธรรมก็ยิ่งมีรัศมีมากกว่านั้นอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 10, 'อันที่จริงรัศมีซึ่งได้ทรงประทานให้นั้นก็อับแสงไปแล้ว เพราะถูกรัศมีอันเลิศประเสริฐนั้นได้ส่องข่มเสียหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 11, 'เพราะถ้าสิ่งที่ได้จางไปยังเคยมีรัศมีถึงเพียงนั้น สิ่งซึ่งจะดํารงอยู่ก็จะมีรัศมีมากยิ่งกว่านั้นอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 12, 'เมื่อเรามีความหวังอย่างนั้นแล้ว เราจึงกล้ามากขึ้นที่จะพูด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 13, 'และไม่เหมือนโมเสสที่เอาผ้าคลุมหน้าไว้ เพื่อไม่ให้ชนอิสราเอลเพ่งดูความเสื่อมของรัศมีที่ค่อยๆจางไปนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 14, 'แต่จิตใจของเขาก็มืดบอดไป เพราะตลอดมาจนถึงทุกวันนี้ เมื่อเขาอ่านพันธสัญญาเดิม ผ้าคลุมนั้นยังคงอยู่มิได้เปิดออก แต่ผ้าคลุมนั้นได้เปิดออกแล้วโดยพระคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 15, 'แต่ว่าตลอดมาถึงทุกวันนี้ ขณะใดที่เขาอ่านคําของโมเสส ผ้าคลุมนั้นก็ยังปิดบังใจของเขาไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 16, 'แต่เมื่อผู้ใดหันกลับมาหาองค์พระผู้เป็นเจ้า ผ้าคลุมนั้นก็จะเปิดออก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 17, 'บัดนี้องค์พระผู้เป็นเจ้าทรงเป็นพระวิญญาณนั้น และพระวิญญาณขององค์พระผู้เป็นเจ้าทรงอยู่ที่ไหน เสรีภาพก็มีอยู่ที่นั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 18, 'แต่เราทั้งหลายไม่มีผ้าคลุมหน้าไว้ จึงแลดูสง่าราศีขององค์พระผู้เป็นเจ้าเหมือนมองดูในกระจก และตัวเราก็เปลี่ยนไปเป็นเหมือนพระฉายขององค์พระผู้เป็นเจ้าคือมีสง่าราศีเป็นลําดับขึ้นไป เช่นอย่างสง่าราศีที่มาจากพระวิญญาณขององค์พระผู้เป็นเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 1, 'เพราะเหตุที่เรามีการรับใช้นี้โดยได้รับพระกรุณา เราจึงไม่ย่อท้อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 2, 'แต่ว่าเราได้สละทิ้งกิจการต่างๆที่ไม่ซื่อสัตย์ซึ่งปิดบังซ่อนเร้นไว้ คือไม่ได้ดําเนินอย่างมีเล่ห์เหลี่ยมและไม่ได้พลิกแพลงพระวจนะของพระเจ้าด้วยวิธีการอันล่อลวง แต่เราได้มอบตัวของเราไว้กับจิตสํานึกผิดชอบของคนทั้งปวง โดยสําแดงความจริงในสายพระเนตรของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 3, 'แต่ถ้าข่าวประเสริฐของเราถูกบังไว้จากใคร ก็จากคนเหล่านั้นที่กําลังจะพินาศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 4, 'ส่วนคนที่ไม่เชื่อนั้น พระของยุคนี้ได้กระทําใจของเขาให้มืดไป เพื่อไม่ให้ความสว่างของข่าวประเสริฐอันมีสง่าราศีของพระคริสต์ ผู้เป็นพระฉายของพระเจ้า ส่องแสงถึงพวกเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 5, 'ด้วยว่าเราไม่ได้ประกาศตัวเราเอง แต่ได้ประกาศพระเยซูคริสต์ว่าทรงเป็นองค์พระผู้เป็นเจ้า และได้ประกาศตัวเราเองเป็นผู้รับใช้ของท่านทั้งหลายเพราะเห็นแก่พระเยซู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 6, 'เพราะว่าพระเจ้าองค์นั้น ผู้ได้ตรัสสั่งให้ความสว่างออกมาจากความมืด ได้ทรงส่องสว่างเข้ามาในจิตใจของเรา เพื่อให้เรามีความสว่างแห่งความรู้ถึงสง่าราศีของพระเจ้าปรากฏในพระพักตร์ของพระเยซูคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 7, 'แต่ว่าเรามีทรัพย์สมบัตินี้อยู่ในภาชนะดิน เพื่อให้เห็นว่าฤทธิ์เดชอันเลิศนั้นเป็นของพระเจ้า ไม่ได้มาจากตัวเราเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 8, 'เราถูกขนาบรอบข้าง แต่ก็ไม่ถึงกับกระดิกไม่ไหว เราจนปัญญา แต่ก็ไม่ถึงกับหมดหวัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 9, 'เราถูกข่มเหง แต่ก็ไม่ถูกทอดทิ้ง เราถูกตีลงแล้ว แต่ก็ไม่ถึงตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 10, 'เราแบกความตายของพระเยซูเจ้าไว้ที่กายเราเสมอ เพื่อว่าชีวิตของพระเยซูจะปรากฏในกายของเราด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 11, 'เพราะว่าพวกเราที่มีชีวิตอยู่นั้นต้องถูกมอบไว้แก่ความตายอยู่เสมอเพราะเห็นแก่พระเยซู เพื่อว่าพระชนม์ชีพของพระเยซูจะได้ปรากฏในเนื้อหนังของเราซึ่งจะต้องตายนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 12, 'เหตุฉะนั้นความตายจึงกําลังออกฤทธิ์อยู่ในเรา แต่ชีวิตกําลังออกฤทธิ์อยู่ในท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 13, 'เพราะเรามีใจเชื่อเช่นเดียวกัน ตามที่เขียนไว้ว่า ‘ข้าพเจ้าเชื่อแล้ว เหตุฉะนั้นข้าพเจ้าจึงพูด’ เราก็เชื่อเหมือนกัน เพราะฉะนั้นเราจึงพูด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 14, 'เรารู้ว่าพระองค์ผู้ทรงให้พระเยซูเจ้าคืนพระชนม์ จะทรงโปรดให้เราเป็นขึ้นมาเช่นกันโดยพระเยซู และจะทรงพาเราเข้ามาเฝ้าพร้อมกับท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 15, 'เพราะว่าสิ่งสารพัดนั้นเป็นไปเพื่อประโยชน์ของท่านทั้งหลาย เพื่อว่าเมื่อพระคุณมาถึงคนเป็นจํานวนมากขึ้น ก็จะมีการขอบพระคุณมากยิ่งขึ้นเป็นการถวายพระเกียรติแด่พระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 16, 'เหตุฉะนั้นเราจึงไม่ย่อท้อ ถึงแม้ว่ากายภายนอกของเรากําลังทรุดโทรมไป แต่จิตใจภายในนั้นก็ยังคงจําเริญขึ้นใหม่ทุกวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 17, 'เพราะว่าการทุกข์ยากเล็กๆน้อยๆของเรา ซึ่งเรารับอยู่ประเดี๋ยวเดียวนั้นจะทําให้เรามีสง่าราศีใหญ่ยิ่งนิรันดร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 18, 'ด้วยว่าเราไม่ได้เห็นแก่สิ่งของที่เรามองเห็นอยู่ แต่เห็นแก่สิ่งของที่มองไม่เห็น เพราะว่าสิ่งของซึ่งมองเห็นอยู่นั้นเป็นของไม่ยั่งยืน แต่สิ่งซึ่งมองไม่เห็นนั้นก็ถาวรนิรันดร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 1, 'เพราะเรารู้ว่า ถ้าเรือนดินแห่งพลับพลาของเรานี้จะพังทําลายเสีย เราก็ยังมีที่อาศัยซึ่งพระเจ้าทรงโปรดประทานให้ ที่มิได้สร้างด้วยมือมนุษย์ และตั้งอยู่เป็นนิตย์ในสวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 2, 'เพราะว่าในร่างกายนี้เรายังครวญคร่ําอยู่ มีความปรารถนาอย่างยิ่งที่จะสวมที่อาศัยของเราที่มาจากสวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 3, 'ถ้าได้สวมเช่นนั้นแล้ว เราก็จะมิได้ถูกพบเห็นว่าเปลือยเปล่าอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 4, 'เพราะว่าเราผู้อาศัยในพลับพลานี้จึงครวญคร่ําเป็นทุกข์ มิใช่เพราะปรารถนาที่จะอยู่ตัวเปล่า แต่ปรารถนาจะสวมกายใหม่นั้น เพื่อว่าร่างกายของเราซึ่งจะต้องตายนั้นจะได้ถูกชีวิตอมตะกลืนเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 5, 'แต่พระเจ้าทรงเป็นผู้เตรียมเราไว้สําหรับการเปลี่ยนแปลงนี้ และพระองค์ได้ทรงโปรดประทานพระวิญญาณเป็นมัดจําไว้กับเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 6, 'เหตุฉะนั้นเรามั่นใจอยู่เสมอรู้อยู่แล้วว่า ขณะที่เราอยู่ในร่างกายนี้ เราอยู่ปราศจากองค์พระผู้เป็นเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 7, '(เพราะเราดําเนินโดยความเชื่อ มิใช่ตามที่ตามองเห็น)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 8, 'เรามีความมั่นใจ และเราปรารถนาจะอยู่กับองค์พระผู้เป็นเจ้ามากกว่าอยู่ในร่างกายนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 9, 'เหตุฉะนั้นเราตั้งเป้าของเราว่า จะอยู่ในกายนี้ก็ดี หรือไม่อยู่ก็ดี เราก็จะเป็นที่พอพระทัยของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 10, 'เพราะว่าจําเป็นที่เราทุกคนจะต้องปรากฏตัวที่หน้าบัลลังก์พิพากษาของพระคริสต์ เพื่อทุกคนจะได้รับสมกับการที่ได้ประพฤติในร่างกายนี้ แล้วแต่จะดีหรือชั่ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 11, 'เพราะเหตุที่เรารู้จักความน่าเกรงขามขององค์พระผู้เป็นเจ้า เราจึงชักชวนคนทั้งหลาย แต่เราเป็นที่ประจักษ์แก่พระเจ้า และข้าพเจ้าหวังว่า เราได้ปรากฏประจักษ์แก่จิตสํานึกผิดและชอบของท่านด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 12, 'เพราะเราไม่ได้ยกย่องตัวเองกับท่านทั้งหลายอีก แต่เราให้ท่านมีโอกาสที่จะนําเราออกอวดได้ เพื่อท่านจะได้มีข้อโต้ตอบคนเหล่านั้นที่ชอบอวดในสิ่งซึ่งปรากฏ แต่มิได้อวดในสิ่งซึ่งอยู่ในจิตใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 13, 'เพราะว่าถ้าเราได้ประพฤติอย่างคนเสียจริต เราก็ได้ประพฤติเพราะเห็นแก่พระเจ้า หรือถ้าเราประพฤติอย่างคนปกติ ก็เพื่อประโยชน์แก่ท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 14, 'เพราะว่าความรักของพระคริสต์ได้ครอบครองเราอยู่ เพราะเราคิดเห็นอย่างนี้ว่า ถ้าผู้หนึ่งได้ตายเพื่อคนทั้งปวง เหตุฉะนั้นคนทั้งปวงจึงตายแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 15, 'และพระองค์ได้ทรงวายพระชนม์เพื่อคนทั้งปวง เพื่อคนเหล่านั้นที่มีชีวิตอยู่จะมิได้เป็นอยู่เพื่อประโยชน์แก่ตัวเองอีกต่อไป แต่จะอยู่เพื่อพระองค์ผู้ทรงสิ้นพระชนม์ และทรงเป็นขึ้นมาเพราะเห็นแก่เขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 16, 'เหตุฉะนั้นตั้งแต่นี้ไปเราจะไม่พิจารณาผู้ใดตามเนื้อหนัง แม้ว่าเมื่อก่อนเราเคยพิจารณาพระคริสต์ตามเนื้อหนังก็จริง แต่เดี๋ยวนี้เราจะไม่พิจารณาพระองค์เช่นนั้นอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 17, 'เหตุฉะนั้นถ้าผู้ใดอยู่ในพระคริสต์ ผู้นั้นก็เป็นคนที่ถูกสร้างใหม่แล้ว สิ่งเก่าๆก็ล่วงไป ดูเถิด สิ่งสารพัดกลายเป็นสิ่งใหม่ทั้งนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 18, 'ทั้งสิ้นนี้เกิดมาจากพระเจ้า ผู้ทรงให้เราคืนดีกันกับพระองค์ทางพระเยซูคริสต์ และทรงโปรดประทานให้เรารับใช้ในเรื่องการคืนดีกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 19, 'คือพระเจ้าผู้สถิตในองค์พระคริสต์ทรงให้โลกนี้คืนดีกันกับพระองค์เอง มิได้ทรงถือโทษในการละเมิดของเขา และทรงมอบพระวจนะแห่งการคืนดีกันนั้นไว้กับเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 20, 'บัดนี้เราจึงเป็นราชทูตของพระคริสต์ โดยที่พระเจ้าทรงขอร้องท่านทั้งหลายทางเรา เราผู้แทนของพระคริสต์จึงขอร้องท่านให้คืนดีกันกับพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 21, 'เพราะว่าพระเจ้าได้ทรงกระทําพระองค์ผู้ทรงไม่มีบาป ให้เป็นความบาปเพราะเห็นแก่เรา เพื่อเราจะได้เป็นคนชอบธรรมของพระเจ้าทางพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 1, 'ฉะนั้นเราผู้เป็นคนทําการร่วมกับพระองค์ขอวิงวอนท่านว่า อย่าสักแต่รับพระคุณของพระเจ้าเป็นการหาประโยชน์มิได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 2, '(เพราะพระองค์ตรัสว่า ‘ในเวลาอันชอบ เราได้ฟังเจ้า ในวันแห่งความรอด เราได้ช่วยเจ้า’ ดูเถิด บัดนี้เป็นเวลาอันชอบ ดูเถิด บัดนี้เป็นวันแห่งความรอด)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 3, 'เรามิได้ให้ผู้ใดมีเหตุสะดุดในสิ่งหนึ่งสิ่งใดเลย เพื่อมิให้การที่เรารับใช้ปฏิบัตินั้นเป็นที่เขาจะติเตียนได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 4, 'แต่ว่าในการทั้งปวงเราได้กระทําตัวให้เป็นที่ชอบ เหมือนผู้รับใช้ของพระเจ้า โดยความเพียรอดทนเป็นอันมาก ในความทุกข์ ในความขัดสน ในเหตุวิบัติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 5, 'ในการถูกเฆี่ยน ในการที่ถูกจําคุก ในการวุ่นวาย ในการงานต่างๆ ในการอดหลับอดนอน ในการอดอาหาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 6, 'โดยความบริสุทธิ์ โดยความรู้ โดยความอดกลั้นไว้นาน โดยใจกรุณา โดยพระวิญญาณบริสุทธิ์ โดยความรักแท้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 7, 'โดยพระวจนะแห่งความจริง โดยฤทธิ์เดชของพระเจ้า โดยใช้เครื่องอาวุธแห่งความชอบธรรมด้วยมือขวาและมือซ้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 8, 'โดยมีเกียรติยศและไร้เกียรติยศ โดยเล่าลือกันว่าชั่วและเล่าลือกันว่าดี เหมือนถูกเขาหาว่าเป็นคนที่ล่อลวงเขาให้หลง แต่ยังเป็นคนสัตย์จริง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 9, 'เหมือนถูกเขาหาว่าเป็นคนไม่มีใครรู้จัก แต่ยังเป็นคนที่เขาทั้งหลายรู้จักดี เหมือนคนตาย แต่ดูเถิด เรายังเป็นอยู่ เหมือนคนถูกเฆี่ยน แต่ยังไม่ตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 10, 'เหมือนคนที่มีความทุกข์ แต่ยังมีความชื่นชมยินดีอยู่เสมอ เหมือนคนยากจน แต่ยังทําให้คนเป็นอันมากมั่งมี เหมือนคนไม่มีอะไรเลย แต่ยังมีสิ่งสารพัดบริบูรณ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 11, 'โอ ท่านชาวโครินธ์ เราพูดกับท่านอย่างไม่ปิดบังเลย และใจของเราก็เปิดกว้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 12, 'ใจของท่านทั้งหลายไม่ได้ปิดเพราะเรา แต่ปิดเพราะความรู้สึกของตนเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 13, 'ดังนั้นในการตอบสนองอย่างเดียวกัน (ข้าพเจ้าขอพูดกับท่านเหมือนอย่างพูดกับบุตร) คือจงเปิดใจของท่านให้กว้างด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 14, 'ท่านอย่าเข้าเทียมแอกกับคนที่ไม่เชื่อ เพราะว่าความชอบธรรมจะมีหุ้นส่วนอะไรกับความอธรรม และความสว่างจะเข้าสนิทกับความมืดได้อย่างไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 15, 'พระคริสต์กับเบลีอัลจะลงรอยกันอย่างไรได้ หรือคนที่เชื่อจะมีส่วนอะไรกับคนที่ไม่เชื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 16, 'วิหารของพระเจ้าจะตกลงอะไรกับรูปเคารพได้ เพราะว่าท่านเป็นวิหารของพระเจ้าผู้ทรงดํารงพระชนม์ ดังที่พระเจ้าตรัสไว้ว่า ‘เราจะอยู่ในเขาทั้งหลาย และจะดําเนินในหมู่พวกเขา และเราจะเป็นพระเจ้าของเขา และเขาจะเป็นประชาชนของเรา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 17, 'องค์พระผู้เป็นเจ้าตรัสว่า ‘เหตุฉะนั้นเจ้าจงออกจากหมู่พวกเขาเหล่านั้น และจงแยกตัวออกจากเขาทั้งหลาย อย่าแตะต้องสิ่งซึ่งไม่สะอาด แล้วเราจึงจะรับพวกเจ้าทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 18, 'เราจะเป็นบิดาของพวกเจ้าและพวกเจ้าจะเป็นบุตรชายบุตรสาวของเรา’ องค์พระผู้เป็นเจ้าผู้ทรงฤทธานุภาพทั้งสิ้นได้ตรัสดังนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 1, 'ท่านที่รัก เมื่อเรามีพระสัญญาเช่นนี้แล้ว ให้เราชําระตัวเราให้ปราศจากมลทินทุกอย่างของเนื้อหนังและจิตวิญญาณ และจงทําให้มีความบริสุทธิ์ครบถ้วนโดยความเกรงกลัวพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 2, 'ขอรับเราเถิด เรามิได้ทําร้ายผู้ใด เรามิได้ชวนผู้ใดให้ทําชั่ว เรามิได้โกงผู้ใดเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 3, 'ข้าพเจ้าพูดเช่นนี้มิใช่เพื่อจะปรักปรําท่าน เพราะข้าพเจ้าบอกแล้วว่า ท่านทั้งหลายอยู่ในใจของเราทีเดียว จะตายหรือจะเป็นก็อยู่ด้วยกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 4, 'ข้าพเจ้าพูดอย่างไว้ใจท่านมาก และข้าพเจ้าภูมิใจเพราะท่านทั้งหลายอย่างมาก ข้าพเจ้าได้รับความชูใจอย่างบริบูรณ์ และในความยากลําบากของเราทุกอย่าง ข้าพเจ้าก็ยังมีความปีติยินดีอย่างเหลือล้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 5, 'เพราะแม้ว่าเมื่อเรามาถึงแคว้นมาซิโดเนียแล้ว เนื้อหนังของเราไม่ได้พักผ่อนเลย เรามีความลําบากอยู่รอบข้าง ภายนอกมีการต่อสู้ ภายในมีความกลัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 6, 'แต่ถึงกระนั้นก็ดี พระเจ้าผู้ทรงหนุนน้ําใจคนที่ท้อใจ ได้ทรงหนุนน้ําใจเราโดยทรงให้ทิตัสมาหาเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 7, 'และมิใช่เพียงการมาของทิตัสเท่านั้น แต่โดยการที่ท่านได้หนุนน้ําใจทิตัสด้วย ตามที่ทิตัสได้มาบอกเราถึงความปรารถนาอย่างยิ่งและความโศกเศร้าของท่าน และใจจดจ่อของท่านที่มีต่อข้าพเจ้า ทําให้ข้าพเจ้ามีความชื่นชมยินดีมากยิ่งขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 8, 'เพราะถึงแม้ว่าข้าพเจ้าได้ทําให้ท่านเสียใจเพราะจดหมายฉบับนั้น ข้าพเจ้าก็ไม่เสียใจ ถึงแม้ว่าเมื่อก่อนนั้นข้าพเจ้าจะเสียใจบ้าง เพราะข้าพเจ้าเห็นว่า จดหมายฉบับนั้นทําให้ท่านมีความเสียใจเพียงชั่วขณะเท่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 9, 'แต่บัดนี้ข้าพเจ้ามีความชื่นชมยินดี มิใช่เพราะท่านเสียใจ แต่เพราะความเสียใจนั้นทําให้ท่านกลับใจใหม่ เพราะว่าท่านได้รับความเสียใจอย่างที่ชอบพระทัยพระเจ้า ท่านจึงไม่ได้ผลร้ายจากเราเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 10, 'เพราะว่าความเสียใจอย่างที่ชอบพระทัยพระเจ้าย่อมกระทําให้กลับใจใหม่ ซึ่งนําไปถึงความรอดและไม่เป็นที่น่าเสียใจ แต่ความเสียใจอย่างโลกนั้นย่อมนําไปถึงความตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 11, 'จงพิจารณาดูว่าความเสียใจอย่างที่ชอบพระทัยพระเจ้ากระทําให้เกิดความกระตือรือร้นมากทีเดียว ทําให้เกิดความขวนขวายที่จะแก้ตัวใหม่ และการโกรธแทน ความกลัว ความปรารถนาอย่างยิ่ง ความกระตือรือร้น การแก้แค้น ในทุกสิ่งเหล่านั้นท่านได้พิสูจน์ให้เห็นแล้วว่าท่านก็หมดจดในการนี้แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 12, 'เหตุฉะนี้ที่ข้าพเจ้าเขียนถึงท่านก็มิใช่เพราะเห็นแก่คนที่ได้ทําผิด หรือเพราะเห็นแก่คนที่ต้องทนต่อการร้าย แต่เพื่อให้ความห่วงใยของเราที่มีต่อท่านปรากฏแก่ท่านในสายพระเนตรพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 13, 'โดยเหตุนี้ เราจึงมีความชูใจเมื่อเห็นว่าพวกท่านได้รับความชูใจ เรามีความชื่นชมยินดีมากยิ่งขึ้นเพราะความยินดีของทิตัส ในการที่พวกท่านได้กระทําให้จิตใจของทิตัสชื่นบาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 14, 'เพราะถ้าข้าพเจ้าได้อวดเรื่องพวกท่านแก่ทิตัส ข้าพเจ้าก็ไม่ต้องละอายใจเลย ทุกสิ่งที่เราได้กล่าวแก่ท่านเป็นความจริงฉันใด สิ่งที่เราได้อวดเรื่องพวกท่านแก่ทิตัสเมื่อก่อนนั้น ก็ปรากฏเป็นจริงเหมือนกันฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 15, 'และเมื่อทิตัสระลึกถึงความเชื่อฟังของพวกท่านทั้งหลาย และการที่พวกท่านต้อนรับเขาด้วยความเกรงกลัวจนตัวสั่น เขาก็เพิ่มความรักในพวกท่านมากยิ่งขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 16, 'ข้าพเจ้าชื่นชมยินดี เพราะว่าข้าพเจ้าไว้ใจท่านได้ทุกอย่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 1, 'ยิ่งกว่านี้ พี่น้องทั้งหลาย เราใคร่ให้ท่านทราบถึงพระคุณของพระเจ้า โดยที่พระองค์ได้ทรงโปรดประทานแก่คริสตจักรต่างๆในแคว้นมาซิโดเนีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 2, 'เพราะว่าเมื่อคราวที่พวกเขาถูกทดลองอย่างหนักได้รับความทุกข์ยาก ความยินดีล้นพ้นของเขาและความยากจนแสนเข็ญของเขานั้น ก็ล้นออกมาเป็นใจโอบอ้อมอารีของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 3, 'เพราะข้าพเจ้าเป็นพยานได้ว่า เขาถวายโดยสุดความสามารถของเขา ที่จริงก็เกินความสามารถของเขาเสียอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 4, 'และเขายังได้วิงวอนเรามากมายขอให้เรายอมรับของถวายนั้น และให้เขามีส่วนในการช่วยวิสุทธิชนด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 5, 'ไม่เหมือนที่เราได้คาดหมายไว้ แต่ได้ถวายตัวเขาเองแด่องค์พระผู้เป็นเจ้าก่อน แล้วได้มอบตัวให้เราตามพระประสงค์ของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 6, 'จนถึงกับเราได้เตือนทิตัสว่า เมื่อเขาได้เริ่มแล้วฉันใด ก็ให้เขาทําให้สําเร็จกับท่านทั้งหลายในพระคุณนี้ด้วยเช่นกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 7, 'เหตุฉะนั้นเมื่อท่านมีพร้อมบริบูรณ์ทุกสิ่ง คือความเชื่อ ถ้อยคํา ความรู้ ความกระตือรือร้นทั้งปวง และความรักต่อเรา ท่านทั้งหลายก็จงประกอบพระคุณนี้อย่างบริบูรณ์เหมือนกันเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 8, 'ข้าพเจ้าพูดอย่างนี้มิได้หมายว่าให้เป็นคําบัญชา แต่ได้นําเรื่องของคนอื่นที่มีความกระตือรือร้นมาทดลองความรักของท่าน ดูว่าแท้หรือไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 9, 'เพราะท่านทั้งหลายรู้จักพระคุณของพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเราว่า แม้พระองค์มั่งคั่ง พระองค์ก็ยังทรงยอมเป็นคนยากจน เพราะเห็นแก่ท่านทั้งหลายเพื่อท่านทั้งหลายจะได้เป็นคนมั่งมี เนื่องจากความยากจนของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 10, 'และข้าพเจ้าจะออกความเห็นในเรื่องนี้ เพราะจะเป็นประโยชน์แก่ท่าน เรื่องที่ท่านได้ตั้งต้นเมื่อปีกลายนี้ และมิใช่ตั้งต้นจะกระทําเท่านั้น แต่ว่ามีน้ําใจจะกระทําด้วยนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 11, 'ฉะนั้นบัดนี้ก็ควรแล้วที่ท่านจะกระทําเรื่องนั้นให้สําเร็จเสีย เพื่อว่าเมื่อท่านมีใจพร้อมอยู่แล้ว ท่านก็จะได้ทําให้สําเร็จตามความสามารถของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 12, 'เพราะว่าถ้ามีน้ําใจพร้อมอยู่แล้ว พระเจ้าก็พอพระทัยที่จะทรงรับตามที่ทุกคนมีอยู่ มิใช่ตามที่เขาไม่มี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 13, 'ข้าพเจ้าไม่ได้หมายความว่า ให้การงานของคนอื่นเบาลงและให้การงานของพวกท่านหนักขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 14, 'แต่เป็นการให้กันไปให้กันมา ในยามที่พวกท่านมีบริบูรณ์เช่นเวลานี้ ท่านก็ควรจะช่วยคนเหล่านั้นที่ขัดสน และในยามที่เขามีบริบูรณ์ เขาก็จะได้ช่วยพวกท่านเมื่อขัดสน เพื่อเป็นการให้กันไปให้กันมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 15, 'ตามที่มีเขียนไว้ว่า ‘คนที่เก็บได้มากก็ไม่มีเหลือ และคนที่เก็บได้น้อยก็หาขาดไม่’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 16, 'แต่ขอขอบพระคุณพระเจ้า ผู้ทรงโปรดให้ทิตัสมีใจกระตือรือร้นอย่างนั้นเพื่อท่านทั้งหลายเหมือนกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 17, 'เพราะไม่เพียงแต่เขาได้รับคําเตือนเท่านั้น แต่เขาได้ไปหาท่านเพราะเขาเองมีใจพร้อมอยู่แล้วด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 18, 'เราให้พี่น้องคนหนึ่งที่มีชื่อเสียงในการประกาศข่าวประเสริฐตามคริสตจักรทั้งหลายไปกับทิตัสด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 19, 'และมิใช่แต่เท่านั้น คริสตจักรได้ตั้งคนนั้นไว้ให้เป็นเพื่อนเดินทางด้วยกันกับเราในพระคุณนี้ซึ่งเราได้รับใช้อยู่ เพื่อให้เป็นที่ถวายเกียรติยศแด่องค์พระผู้เป็นเจ้า และเป็นที่แสดงน้ําใจพรักพร้อมของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 20, 'เราเจตนาจะไม่ให้คนหนึ่งคนใดติเตียนเราได้ ในเรื่องของถวายเป็นอันมากซึ่งเรารับมาแจกนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 21, 'เพราะเรามุ่งที่จะกระทําสิ่งที่ซื่อสัตย์ มิใช่เฉพาะแต่ในสายพระเนตรขององค์พระผู้เป็นเจ้าเท่านั้น แต่ในสายตาของมนุษย์ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 22, 'เราได้ส่งพี่น้องอีกคนหนึ่งไปกับเขาทั้งสองด้วย ผู้ซึ่งเราได้ทดสอบแล้วว่า มีความกระตือรือร้นในหลายสิ่ง และเดี๋ยวนี้เขามีความกระตือรือร้นมากยิ่งขึ้น เพราะเรามีความไว้ใจในท่านมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 23, 'ถ้ามีคนใดถามถึงทิตัส ทิตัสก็เป็นเพื่อนร่วมงานของข้าพเจ้า และเป็นผู้ช่วยในการของท่านทั้งหลาย หรือถ้ามีคนใดถามถึงพี่น้องสองคนนั้น เขาก็เป็นทูตรับใช้ของคริสตจักรทั้งหลายและเป็นสง่าราศีของพระคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 24, 'เหตุฉะนั้นจงให้ความรักของท่านประจักษ์แก่คนเหล่านั้น และแสดงให้แก่คริสตจักรทั้งหลายด้วย ให้สมกับที่ข้าพเจ้าได้อวดเรื่องพวกท่านให้เขาฟัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 1, 'ข้าพเจ้าไม่จําเป็นต้องเขียนถึงท่านในเรื่องการสงเคราะห์วิสุทธิชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 2, 'เพราะข้าพเจ้ารู้ว่าใจของท่านพร้อมอยู่แล้ว ข้าพเจ้าจึงพูดอวดเรื่องพวกท่านกับพวกมาซิโดเนียว่า พวกอาคายาได้จัดเตรียมไว้พร้อมแล้วตั้งแต่ปีกลาย และความกระตือรือร้นของพวกท่านก็เร้าใจคนเป็นอันมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 3, 'แต่ข้าพเจ้าได้ให้พี่น้องเหล่านั้นไป เพื่อมิให้การอวดของเราเรื่องท่านในข้อนั้นเป็นการเปล่าประโยชน์ และเพื่อให้ท่านจัดเตรียมไว้ให้พร้อมตามที่ข้าพเจ้าได้กล่าวแล้วนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 4, 'มิฉะนั้นแล้ว ถ้าชาวมาซิโดเนียบางคนมากับข้าพเจ้า และเห็นว่าท่านมิได้เตรียมพร้อมตามที่เราได้อวดไว้นั้น (อย่าว่าแต่ท่านจะขายหน้าเลย) เราเองก็จะขายหน้าด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 5, 'เหตุฉะนั้นข้าพเจ้าจึงเห็นว่า สมควรจะวิงวอนให้พี่น้องเหล่านั้นไปหาท่านก่อนข้าพเจ้า และให้จัดเตรียมของถวายของท่านไว้ ตามที่ท่านได้สัญญาไว้แล้ว เพื่อของถวายนั้นจะมีอยู่พร้อม และจะเป็นของถวายที่ให้ด้วยใจศรัทธา มิใช่ให้ด้วยการฝืนใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 6, 'นี่แหละ คนที่หว่านเพียงเล็กน้อยก็จะเกี่ยวเก็บได้เพียงเล็กน้อย คนที่หว่านมากก็จะเกี่ยวเก็บได้มาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 7, 'ทุกคนจงให้ตามที่เขาได้คิดหมายไว้ในใจ มิใช่ให้ด้วยนึกเสียดาย มิใช่ให้ด้วยการฝืนใจ เพราะว่าพระเจ้าทรงรักคนนั้นที่ให้ด้วยใจยินดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 8, 'และพระเจ้าทรงฤทธิ์สามารถประทานพระคุณอันอุดมทุกอย่างแก่ท่านทั้งหลาย เพื่อให้ท่านมีทุกสิ่งทุกอย่างเพียงพอสําหรับตัวเสมอ ทั้งจะมีสิ่งของบริบูรณ์สําหรับงานที่ดีทุกอย่างด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 9, '(ตามที่เขียนไว้ว่า ‘เขาแจกจ่าย เขาได้ให้แก่คนยากจน ความชอบธรรมของเขาดํารงเป็นนิตย์’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 10, 'เดี๋ยวนี้พระองค์ผู้ประทานพืชแก่คนที่หว่าน ทั้งประทานขนมปังเป็นอาหารของท่าน และทรงโปรดให้พืชของท่านที่หว่านนั้นทวีขึ้นเป็นอันมาก และทรงให้ผลแห่งความชอบธรรมของท่านเจริญยิ่งขึ้น)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 11, 'โดยทรงให้ท่านทั้งหลายมีสิ่งสารพัดมั่งคั่งบริบูรณ์ขึ้น เพื่อให้ท่านมีแจกจ่ายอย่างใจกว้างขวาง ซึ่งจะให้เกิดการขอบพระคุณพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 12, 'เพราะว่าการรับใช้ในการปรนนิบัตินั้นมิใช่จะช่วยวิสุทธิชนซึ่งขัดสนเท่านั้น แต่ยังเป็นเหตุให้มีการขอบพระคุณพระเจ้าเป็นอันมากด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 13, 'และเนื่องจากผลแห่งการรับใช้นั้น เขาจึงถวายเกียรติยศแด่พระเจ้า โดยเหตุที่ท่านทั้งหลายยอมฟังและตั้งใจอยู่ในอํานาจข่าวประเสริฐของพระคริสต์ และเพราะเหตุท่านได้แจกจ่ายแก่เขาและแก่คนทั้งปวงด้วยใจกว้างขวาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 14, 'เขาก็จะวิงวอนขอพระพรให้แก่ท่านทั้งหลายและปรารถนาท่านเป็นอันมาก เพราะเหตุพระคุณของพระเจ้าซึ่งสถิตอยู่ในท่านอย่างเหลือล้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 15, 'จงขอบพระคุณพระเจ้าเพราะของประทานซึ่งพระองค์ทรงประทานนั้นที่เหลือจะพรรณนาได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 1, 'บัดนี้ข้าพเจ้า เปาโล ขอวิงวอนต่อท่านเป็นส่วนตัว โดยเห็นแก่ความอ่อนสุภาพและพระทัยกรุณาของพระคริสต์ ข้าพเจ้าผู้ซึ่งท่านว่า เป็นคนสุภาพถ่อมตนเมื่ออยู่กับท่านทั้งหลาย แต่เมื่ออยู่ต่างหากก็เป็นคนใจกล้าต่อท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 2, 'คือข้าพเจ้าขอร้องท่านว่า เมื่อข้าพเจ้ามาอยู่กับท่านอย่าให้ข้าพเจ้าต้องแสดงความกล้าหาญด้วยความแน่ใจ อย่างที่ข้าพเจ้าคิดสําแดงต่อบางคนที่นึกเห็นว่าเรายังดําเนินตามเนื้อหนังนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 3, 'เพราะว่า ถึงแม้เรายังดําเนินอยู่ในเนื้อหนังก็จริง แต่เราก็ไม่ได้สู้รบตามฝ่ายเนื้อหนัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 4, '(เพราะว่าศาสตราวุธแห่งการสงครามของเราไม่เป็นฝ่ายเนื้อหนัง แต่มีอานุภาพอันยิ่งใหญ่จากพระเจ้าที่จะทลายป้อมอันแข็งแกร่งลงได้)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 5, 'คือทําลายความคิด และทิฐิมานะทุกประการที่ตั้งตัวขึ้นขัดขวางความรู้ของพระเจ้า และน้อมนําความคิดทุกประการให้เข้าอยู่ใต้บังคับจนถึงเชื่อฟังพระคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 6, 'และพร้อมที่จะแก้แค้นการไม่เชื่อฟังทุกอย่าง ในเมื่อความเชื่อฟังของท่านทั้งหลายจะสําเร็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 7, 'ท่านแลดูสิ่งที่ปรากฏภายนอกหรือ ถ้าผู้ใดมั่นใจว่าตนเป็นคนของพระคริสต์ ก็ให้ผู้นั้นคํานึงถึงตนเองอีกว่า เมื่อเขาเป็นคนของพระคริสต์ เราก็เป็นคนของพระคริสต์เหมือนกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 8, 'ถึงแม้ข้าพเจ้าจะโอ้อวดมากไปสักหน่อยในเรื่องอํานาจของเรา ซึ่งองค์พระผู้เป็นเจ้าทรงประทานให้ไว้แก่เราเพื่อสร้างท่าน และมิใช่เพื่อทําลายท่าน ข้าพเจ้าก็จะไม่ละอาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 9, 'เพื่อท่านทั้งหลายจะไม่คิดเห็นว่า ข้าพเจ้าอยากให้ท่านกลัวเพราะจดหมายของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 10, 'เพราะมีบางคนพูดว่า “จดหมายของเปาโลนั้นมีน้ําหนักและมีอํานาจมากก็จริง แต่ว่าตัวเขาดูอ่อนกําลัง และคําพูดของเขาก็ใช้ไม่ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 11, 'จงให้คนเหล่านั้นเข้าใจอย่างนี้ว่า เมื่อเราไม่อยู่เราพูดไว้ในจดหมายของเราว่าอย่างไร เมื่อเรามาแล้วเราก็จะกระทําอย่างนั้นด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 12, 'เราไม่ต้องการที่จะจัดอันดับหรือเปรียบเทียบตัวเราเองกับบางคนที่ยกย่องตัวเอง แต่เมื่อเขาเอาตัวของเขาเป็นเครื่องวัดกันและกัน และเอาตัวเปรียบเทียบกันและกัน เขาก็เป็นคนขาดปัญญา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 13, 'ฝ่ายเราจะไม่โอ้อวดในสิ่งใดเกินขอบเขต แต่ว่าจะอวดในขอบเขตที่พระเจ้าทรงจัดไว้ให้เรา และพวกท่านก็อยู่ในขอบเขตนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 14, 'การที่มาถึงท่านนั้น มิใช่โดยการล่วงขอบเขตอันควร เรามาจนถึงท่านทั้งหลายเพื่อประกาศข่าวประเสริฐของพระคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 15, 'เรามิได้โอ้อวดเกินขอบเขต ไม่ได้อวดในการงานที่คนอื่นได้กระทํา แต่เราหวังใจว่า เมื่อความเชื่อของท่านจําเริญมากขึ้นแล้ว ท่านจะช่วยเราให้ขยายเขตกว้างขวางออกไปอีกเป็นอันมากตามขนาดของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 16, 'เพื่อเราจะได้ประกาศข่าวประเสริฐในเขตที่อยู่นอกท้องถิ่นของพวกท่าน โดยไม่โอ้อวดเรื่องการงานที่คนอื่นได้ทําไว้พร้อมแล้วนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 17, 'ถ้าผู้ใดจะอวด ก็จงอวดองค์พระผู้เป็นเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 18, 'เพราะคนที่ยกย่องตัวเองไม่เป็นที่นับถือของผู้ใด คนที่น่านับถือนั้นคือคนที่องค์พระผู้เป็นเจ้าทรงยกย่อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 1, 'ข้าพเจ้าอยากจะขอให้ท่านทนฟังความเขลาของข้าพเจ้าสักหน่อยหนึ่ง และให้ทนกับข้าพเจ้าจริงๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 2, 'เพราะว่าข้าพเจ้าหวงแหนท่านอย่างที่พระเจ้าทรงหวงแหน เพราะว่าข้าพเจ้าได้หมั้นพวกท่านไว้สําหรับสามีผู้เดียว เพื่อถวายพวกท่านให้แด่พระคริสต์เป็นพรหมจารีบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 3, 'แต่ข้าพเจ้าเกรงว่างูนั้นได้ล่อลวงนางเอวาด้วยอุบายของมันฉันใด จิตใจของท่านก็จะถูกล่อลวงให้หลงไปจากความบริสุทธิ์ ซึ่งมีอยู่ในพระคริสต์โดยวิธีหนึ่งวิธีใดฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 4, 'เพราะว่าถ้าคนใดจะมาเทศนาสั่งสอนถึงพระเยซูอีกองค์หนึ่ง ซึ่งแตกต่างกับที่เราได้เทศนาสั่งสอนนั้น หรือถ้าท่านจะรับวิญญาณอื่นซึ่งแตกต่างกับที่ท่านได้รับแต่ก่อน หรือรับข่าวประเสริฐอื่นซึ่งแตกต่างกับที่ท่านได้รับไว้แล้ว แหมท่านทั้งหลายช่างอดทนสนใจฟังเขาเสียจริงๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 5, 'เพราะข้าพเจ้าคิดว่า ข้าพเจ้าไม่ด้อยกว่าอัครสาวกชั้นผู้ใหญ่เหล่านั้นแม้แต่น้อยเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 6, 'แต่ถึงแม้ว่าข้าพเจ้าพูดไม่เก่ง ข้าพเจ้าก็ยังมีความรู้ แต่เราเป็นที่เข้าใจแจ่มแจ้งท่ามกลางพวกท่านในสิ่งสารพัดแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 7, 'ข้าพเจ้าได้กระทําผิดหรือในการที่ข้าพเจ้าได้ถ่อมใจลงเพื่อยกชูท่านขึ้น เพราะข้าพเจ้าได้ประกาศข่าวประเสริฐของพระเจ้าแก่พวกท่านโดยไม่ได้คิดค่าหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 8, 'ข้าพเจ้าได้ปล้นคริสตจักรอื่นด้วยการรับเงินบํารุงจากเขา เพื่อจะได้ปรนนิบัติพวกท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 9, 'และเมื่อข้าพเจ้าอยู่กับพวกท่านและกําลังขาดแคลนนั้น ข้าพเจ้าก็มิได้เป็นภาระแก่ผู้ใด เพราะว่า พี่น้องที่มาจากแคว้นมาซิโดเนียได้เจือจานให้พอแก่ความต้องการของข้าพเจ้า ข้าพเจ้าระวังตัวไม่ให้เป็นภาระแก่พวกท่านในทางหนึ่งทางใดทุกประการ และข้าพเจ้าจะระวังตัวเช่นนั้นต่อไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 10, 'ความจริงของพระคริสต์มีอยู่ในข้าพเจ้าแน่ฉันใด จึงไม่มีผู้ใดในเขตแคว้นอาคายาสามารถที่จะห้ามข้าพเจ้าไม่ให้อวดเรื่องนี้ได้ฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 11, 'เพราะเหตุใด เพราะข้าพเจ้าไม่รักพวกท่านหรือ พระเจ้าทรงทราบดีว่าข้าพเจ้ารักพวกท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 12, 'แต่สิ่งที่ข้าพเจ้ากระทํานั้น ข้าพเจ้าจะกระทําต่อไป เพื่อข้าพเจ้าจะตัดโอกาสคนเหล่านั้นที่คอยหาโอกาส เพื่อว่าเมื่อเขาโอ้อวดนั้นเขาจะได้ปรากฏว่ามีสภาพเหมือนกับเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 13, 'เพราะคนอย่างนั้นเป็นอัครสาวกเทียม เป็นคนงานที่หลอกลวง ปลอมตัวเป็นอัครสาวกของพระคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 14, 'การกระทําเช่นนั้นไม่แปลกประหลาดเลย ถึงซาตานเองก็ยังปลอมตัวเป็นทูตสวรรค์แห่งความสว่างได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 15, 'เหตุฉะนั้นจึงไม่เป็นการแปลกอะไรที่ผู้รับใช้ของซาตานจะปลอมตัวเป็นผู้รับใช้ของความชอบธรรม ท้ายที่สุดของเขาจะเป็นไปตามการกระทําของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 16, 'ข้าพเจ้าขอกล่าวซ้ําอีกว่า อย่าให้ใครเห็นไปว่าข้าพเจ้าเป็นคนเขลา แต่ถ้ามี ก็ให้เขาต้อนรับข้าพเจ้าอย่างต้อนรับคนเขลาเถิด เพื่อข้าพเจ้าจะได้อวดตัวเองได้บ้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 17, 'การที่ข้าพเจ้าพูดอย่างนั้น ข้าพเจ้ามิได้พูดตามอย่างองค์พระผู้เป็นเจ้า แต่พูดอย่างคนเขลา ด้วยไว้ใจตัวในการอวดนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 18, 'เพราะเมื่อเห็นว่าหลายคนเคยอวดตามเนื้อหนัง ข้าพเจ้าก็จะอวดบ้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 19, 'เพราะว่าการที่ท่านทนฟังคนเขลาพูดด้วยความยินดีนั้น น่าจะเป็นเพราะท่านช่างฉลาดเสียนี่กระไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 20, 'เพราะท่านทนเอา ถ้ามีผู้นําท่านไปเป็นทาส ถ้ามีผู้ล้างผลาญท่าน ถ้ามีผู้มายึดของของท่านไป ถ้ามีผู้ยกตัวเองเป็นใหญ่ ถ้ามีผู้ตบหน้าท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 21, 'ข้าพเจ้าต้องพูดด้วยความละอายว่า ดูเหมือนเราอ่อนแอเกินไปในเรื่องนี้ ไม่ว่าใครกล้าอวดในเรื่องใด (ข้าพเจ้าพูดอย่างคนเขลา) ข้าพเจ้าก็กล้าอวดเรื่องนั้นเหมือนกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 22, 'เขาเป็นชาติฮีบรูหรือ ข้าพเจ้าก็เป็นเหมือนกัน เขาเป็นชนชาติอิสราเอลหรือ ข้าพเจ้าก็เป็นเหมือนกัน เขาเป็นเชื้อสายของอับราฮัมหรือ ข้าพเจ้าก็เป็นเหมือนกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 23, 'เขาเป็นผู้รับใช้ของพระคริสต์หรือ ข้าพเจ้าเป็นดีกว่าเขาเสียอีก (ข้าพเจ้าพูดอย่างคนโง่) ข้าพเจ้าทํางานมากยิ่งกว่าเขาอีก ข้าพเจ้าถูกโบยตีเกินขนาด ข้าพเจ้าติดคุกมากกว่าเขา ข้าพเจ้าหวิดตายบ่อยๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 24, 'พวกยิวเฆี่ยนข้าพเจ้าห้าครั้งๆละสามสิบเก้าที');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 25, 'เขาตีข้าพเจ้าด้วยไม้เรียวสามครั้ง เขาเอาก้อนหินขว้างข้าพเจ้าครั้งหนึ่ง ข้าพเจ้าเผชิญภัยเรือแตกสามครั้ง ข้าพเจ้าลอยอยู่ในทะเลคืนหนึ่งกับวันหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 26, 'ข้าพเจ้าต้องเดินทางบ่อยๆ เผชิญภัยอันน่ากลัวในแม่น้ํา เผชิญโจรภัย เผชิญภัยจากชนชาติของข้าพเจ้าเอง เผชิญภัยจากคนต่างชาติ เผชิญภัยในนคร เผชิญภัยในป่า เผชิญภัยในทะเล เผชิญภัยจากพี่น้องเทียม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 27, 'ต้องทํางานเหน็ดเหนื่อยและยากลําบาก ต้องอดหลับอดนอนบ่อยๆ ต้องหิวและกระหาย ต้องอดข้าวบ่อยๆ ต้องทนหนาวและเปลือยกาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 28, 'และนอกจากสิ่งเหล่านั้นที่อยู่ภายนอกแล้ว ยังมีการอื่นที่บีบข้าพเจ้าอยู่ทุกวันๆ คือการดูแลคริสตจักรทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 29, 'มีใครบ้างเป็นคนอ่อนกําลังและข้าพเจ้าไม่อ่อนกําลังด้วย มีใครบ้างที่ถูกทําให้สะดุดและข้าพเจ้าไม่เป็นทุกข์เป็นร้อนด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 30, 'ถ้าข้าพเจ้าจําเป็นต้องอวด ข้าพเจ้าก็จะอวดสิ่งที่แสดงว่า ข้าพเจ้าเป็นคนอ่อนกําลัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 31, 'พระเจ้าทรงเป็นพระบิดาของพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเรา พระองค์ทรงเป็นผู้ที่ควรแก่การสรรเสริญเป็นนิตย์ พระองค์ทรงทราบว่า ข้าพเจ้าไม่ได้มุสา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 32, 'ผู้ว่าราชการเมืองของกษัตริย์อาเรทัสในนครดามัสกัส ให้ทหารเฝ้านครดามัสกัสไว้ เพื่อจะจับตัวข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 33, 'แต่เขาเอาตัวข้าพเจ้าใส่กระบุงใหญ่หย่อนลงทางช่องที่กําแพงนคร ข้าพเจ้าจึงพ้นจากเงื้อมมือของท่านผู้ว่าราชการ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 1, 'ข้าพเจ้าจําจะต้องอวด ถึงแม้จะไม่มีประโยชน์อะไร แต่ข้าพเจ้าจะเล่าต่อไปถึงนิมิตและการสําแดงต่างๆซึ่งมาจากองค์พระผู้เป็นเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 2, 'สิบสี่ปีมาแล้วข้าพเจ้าได้รู้จักชายคนหนึ่งในพระคริสต์ เขาถูกรับขึ้นไปยังสวรรค์ชั้นที่สาม (แต่จะไปทั้งกาย ข้าพเจ้าไม่ทราบ หรือไปโดยไม่มีกาย ข้าพเจ้าไม่ทราบ พระเจ้าทรงทราบ)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 3, 'ข้าพเจ้ารู้จักชายผู้นั้น (แต่จะไปทั้งกายหรือไม่มีกาย ข้าพเจ้าไม่ทราบ พระเจ้าทรงทราบ)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 4, 'คือว่าคนนั้นถูกรับขึ้นไปยังเมืองบรมสุขเกษม และได้ยินวาจาซึ่งจะพูดเป็นคําไม่ได้ และมนุษย์จะพูดออกมาก็ต้องห้าม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 5, 'สําหรับชายนั้นข้าพเจ้าอวดได้ แต่สําหรับตัวข้าพเจ้าเอง ข้าพเจ้าจะไม่อวดเลย นอกจากจะอวดถึงเรื่องการอ่อนแอของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 6, 'เพราะถึงแม้ว่าข้าพเจ้าอยากจะอวด ข้าพเจ้าก็ไม่ใช่คนเขลา เพราะข้าพเจ้าพูดตามความจริง แต่ข้าพเจ้าระงับไว้ ก็เพราะเกรงว่า บางคนจะยกข้าพเจ้าเกินกว่าที่เขาได้เห็นและได้ฟังเกี่ยวกับข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 7, 'และเพื่อไม่ให้ข้าพเจ้ายกตัวจนเกินไป เนื่องจากที่ได้เห็นการสําแดงมากมายนั้น ก็ทรงให้มีหนามในเนื้อของข้าพเจ้า หนามนั้นเป็นทูตของซาตานคอยทุบตีข้าพเจ้า เพื่อไม่ให้ข้าพเจ้ายกตัวเกินไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 8, 'เรื่องหนามนั้น ข้าพเจ้าวิงวอนองค์พระผู้เป็นเจ้าถึงสามครั้ง เพื่อขอให้มันหลุดไปจากข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 9, 'แต่พระองค์ตรัสกับข้าพเจ้าว่า “พระคุณของเราก็มีพอสําหรับเจ้าแล้ว เพราะความอ่อนแอมีที่ไหน เดชของเราก็มีฤทธิ์ขึ้นเต็มขนาดที่นั่น” เหตุฉะนั้นข้าพเจ้าจึงยินดีโอ้อวดในบรรดาความอ่อนแอของข้าพเจ้า เพื่อฤทธิ์เดชของพระคริสต์จะได้อยู่ในข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 10, 'เหตุฉะนั้นเพราะเห็นแก่พระคริสต์ ข้าพเจ้าจึงชื่นใจในความอ่อนแอของข้าพเจ้า ในการถูกว่ากล่าวต่างๆ ในการขัดสน ในการถูกข่มเหง ในการยากลําบาก เพราะว่าข้าพเจ้าอ่อนแอเมื่อใด ข้าพเจ้าก็จะแข็งแรงมากเมื่อนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 11, 'ในการอวดนั้นข้าพเจ้าก็เป็นคนเขลาไปแล้วซี ท่านบังคับข้าพเจ้าให้เป็น เพราะว่าสมควรแล้วที่ท่านจะยกย่องข้าพเจ้า เพราะว่าข้าพเจ้าไม่ด้อยกว่าอัครสาวกชั้นผู้ใหญ่เหล่านั้นแต่ประการใดเลย ถึงแม้ข้าพเจ้าจะไม่วิเศษอะไรเลยก็จริง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 12, 'แท้จริงหมายสําคัญต่างๆของอัครสาวกก็ได้สําแดงให้ประจักษ์แจ้งในหมู่พวกท่านแล้ว ด้วยบรรดาความเพียร โดยหมายสําคัญ โดยการมหัศจรรย์ และโดยการอิทธิฤทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 13, 'เพราะว่าพวกท่านเสียเปรียบคริสตจักรอื่นๆในข้อใดเล่า เว้นไว้ในข้อนี้ คือที่ข้าพเจ้าไม่ได้เป็นภาระแก่พวกท่าน การผิดนั้นขอท่านให้อภัยแก่ข้าพเจ้าเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 14, 'ดูเถิด ข้าพเจ้าเตรียมพร้อมที่จะมาเยี่ยมพวกท่านเป็นครั้งที่สาม และข้าพเจ้าจะไม่เป็นภาระแก่พวกท่าน เพราะว่าข้าพเจ้าไม่ต้องการสิ่งใดจากท่าน แต่ต้องการตัวท่าน เพราะว่าที่ลูกจะสะสมไว้สําหรับพ่อแม่ก็ไม่สมควร แต่พ่อแม่ควรสะสมไว้สําหรับลูก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 15, 'และข้าพเจ้ามีความยินดีที่จะเสียและสละแรงหมดเพื่อท่านทั้งหลาย แม้ว่าข้าพเจ้ารักท่านมากขึ้นๆ ท่านกลับรักข้าพเจ้าน้อยลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 16, 'ถึงแม้เป็นเช่นนั้น ข้าพเจ้าก็มิได้เป็นภาระแก่พวกท่าน แต่เหมือนเป็นผู้ชาญฉลาด ข้าพเจ้าใช้อุบายดักจับท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 17, 'ข้าพเจ้าได้ผลประโยชน์อะไรจากพวกท่านในการที่ส่งคนเหล่านั้นไปเยี่ยมพวกท่านหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 18, 'ข้าพเจ้าขอให้ทิตัสไป และพี่น้องอีกคนหนึ่งไปด้วย ทิตัสได้ผลประโยชน์จากพวกท่านบ้างหรือ เราทั้งสองมิได้ดําเนินการด้วยน้ําใจอย่างเดียวกันหรือ เรามิได้เดินตามรอยเดียวกันหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 19, 'ท่านทั้งหลายยังคิดว่าเรากําลังกล่าวแก้ตัวต่อท่านอีกหรือ ที่จริงเราพูดในพระคริสต์ดังเราอยู่ต่อพระพักตร์พระเจ้า และท่านที่รัก สิ่งสารพัดที่เราได้กระทํานั้น เรากระทําเพื่อท่านจะจําเริญขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 20, 'เพราะว่าข้าพเจ้าเกรงว่าเมื่อข้าพเจ้ามาถึง ข้าพเจ้าอาจจะไม่เห็นพวกท่านเป็นเหมือนอย่างที่ข้าพเจ้าอยากเห็น และท่านจะไม่เห็นข้าพเจ้าเหมือนอย่างที่ท่านอยากเห็น คือเกรงว่าไม่เหตุใดก็เหตุหนึ่ง จะมีการวิวาทกัน ริษยากัน โกรธกัน มักใหญ่ใฝ่สูง นินทากัน ซุบซิบส่อเสียดกัน จองหองพองตัว และเกะกะวุ่นวายกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 21, 'ข้าพเจ้าเกรงว่า เมื่อข้าพเจ้ากลับมา พระเจ้าของข้าพเจ้าจะทรงให้ข้าพเจ้าต่ําต้อยในหมู่พวกท่าน และข้าพเจ้าจะต้องเศร้าใจ เพราะเหตุหลายคนที่ได้ทําผิดมาก่อนแล้ว และมิได้กลับใจทิ้งการโสโครก การผิดประเวณี และการลามก ซึ่งเขาได้กระทําอยู่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 1, 'ครั้งนี้จะเป็นครั้งที่สามที่ข้าพเจ้ามาเยี่ยมพวกท่าน ‘คําพูดทุกๆคําต้องมีพยานสองหรือสามปาก จึงจะเป็นที่เชื่อถือได้’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 2, 'ข้าพเจ้าได้บอกท่านแต่ก่อน และข้าพเจ้าจึงบอกท่านอีกเหมือนเมื่อข้าพเจ้าได้อยู่กับท่านครั้งที่สองนั้น เดี๋ยวนี้ถึงข้าพเจ้าไม่ได้อยู่กับท่าน ข้าพเจ้าก็ยังเขียนฝากถึงเขาเหล่านั้นซึ่งได้กระทําผิดแต่ก่อน และถึงคนอื่นทั้งปวงว่า ถ้าข้าพเจ้ามาอีก ข้าพเจ้าจะไม่เว้นการติโทษใครเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 3, 'เพราะว่าท่านทั้งหลายต้องการที่จะเห็นหลักฐานว่าพระคริสต์ตรัสทางข้าพเจ้า พระองค์มิได้ทรงอ่อนกําลังต่อท่าน แต่ทรงฤทธิ์มากในหมู่พวกท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 4, 'เพราะถึงแม้ว่าพระองค์ทรงถูกตรึงโดยทรงอ่อนกําลัง พระองค์ยังทรงพระชนม์อยู่โดยฤทธิ์เดชของพระเจ้า เพราะว่าเราก็อ่อนกําลังด้วยกันกับพระองค์ แต่เราจะยังมีชีวิตเป็นอยู่กับพระองค์โดยฤทธิ์เดชของพระเจ้าที่มีต่อท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 5, 'ท่านจงพิจารณาดูตัวของท่านว่า ท่านตั้งอยู่ในความเชื่อหรือไม่ จงพิสูจน์ตัวของท่านเองเถิด ท่านไม่รู้เองหรือว่า พระเยซูคริสต์ทรงสถิตอยู่ในท่านทั้งหลาย นอกจากท่านจะเป็นผู้ถูกทอดทิ้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 6, 'แต่ข้าพเจ้าหวังว่าท่านคงรู้ว่าเรามิได้เป็นผู้ถูกทอดทิ้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 7, 'บัดนี้ข้าพเจ้าอธิษฐานต่อพระเจ้าเพื่อท่านทั้งหลายจะไม่กระทําชั่วใดๆ มิใช่ว่าเราจะให้ปรากฏว่าเราเป็นที่ทรงชอบพระทัย แต่เพื่อท่านจะประพฤติเป็นที่ชอบ ถึงแม้จะดูเหมือนเราเองเป็นผู้ถูกทอดทิ้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 8, 'เพราะว่าเราจะกระทําสิ่งใดขัดกับความจริงไม่ได้ ได้แต่ทําเพื่อความจริงเท่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 9, 'เพราะว่าเมื่อเราอ่อนแอ และท่านเข้มแข็ง เราก็ยินดี เราปรารถนาสิ่งนี้ด้วย คือขอให้ท่านทั้งหลายบรรลุถึงความบริบูรณ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 10, 'เหตุฉะนั้นข้าพเจ้าจึงเขียนข้อความนี้เมื่อข้าพเจ้าไม่อยู่ ด้วยเพื่อเมื่อข้าพเจ้ามาแล้ว จะได้ไม่ต้องกวดขันท่านโดยใช้อํานาจ ซึ่งองค์พระผู้เป็นเจ้าทรงโปรดประทานให้แก่ข้าพเจ้า เพื่อการก่อขึ้นมิใช่เพื่อการทําลายลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 11, 'ในที่สุดนี้ พี่น้องทั้งหลาย ขอลาก่อน ท่านจงปรับปรุงตัวให้ดี จงมีกําลังใจอันดี จงเป็นน้ําหนึ่งใจเดียวกัน จงอยู่ร่วมกันอย่างสันติ และพระเจ้าแห่งความรักและสันติสุขจะทรงสถิตอยู่กับท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 12, 'จงทักทายปราศรัยกันด้วยธรรมเนียมจุบอันบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 13, 'วิสุทธิชนทุกคนฝากความคิดถึงมายังท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 14, 'ขอให้พระคุณของพระเยซูคริสต์เจ้า ความรักแห่งพระเจ้า และความสนิทสนมซึ่งมาจากพระวิญญาณบริสุทธิ์ จงดํารงอยู่กับท่านทั้งหลายเถิด เอเมน [จดหมายฉบับที่สองถึงชาวโครินธ์ เขียนจากเมืองฟีลิปปี แคว้นมาซิโดเนีย และส่งโดยทิตัสและลูกา]');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 1, 'เปาโล ผู้เป็นอัครสาวก (มิใช่มนุษย์แต่งตั้ง หรือมนุษย์เป็นตัวแทนแต่งตั้ง แต่พระเยซูคริสต์และพระเจ้าพระบิดา ผู้ได้ทรงโปรดให้พระเยซูเป็นขึ้นมาจากความตายได้ทรงแต่งตั้ง)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 2, 'และบรรดาพี่น้องที่อยู่กับข้าพเจ้า เรียน คริสตจักรทั้งหลายแห่งแคว้นกาลาเทีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 3, 'ขอให้พระคุณและสันติสุขจากพระเจ้าพระบิดา และพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเรา ดํารงอยู่กับท่านทั้งหลายเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 4, 'พระเยซูทรงสละพระองค์เองเพราะบาปของเราทั้งหลาย เพื่อช่วยเราให้พ้นจากยุคปัจจุบันอันชั่วร้ายตามน้ําพระทัยพระเจ้าผู้เป็นพระบิดาของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 5, 'ขอให้พระองค์ทรงมีสง่าราศีตลอดไปเป็นนิตย์ เอเมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 6, 'ข้าพเจ้าประหลาดใจนักที่ท่านทั้งหลายได้ผินหน้าหนีโดยเร็วจากพระองค์ ผู้ได้ทรงเรียกท่านให้เข้าในพระคุณของพระคริสต์ และได้ไปหาข่าวประเสริฐอื่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 7, 'ซึ่งมิใช่อย่างอื่นดอก แต่ว่ามีบางคนที่ทําให้ท่านยุ่งยาก และปรารถนาที่จะบิดเบือนข่าวประเสริฐของพระคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 8, 'แต่แม้ว่าเราเองหรือทูตสวรรค์ ถ้าประกาศข่าวประเสริฐอื่นแก่ท่าน ซึ่งขัดกับข่าวประเสริฐที่เราได้ประกาศแก่ท่านไปแล้วก็ให้ผู้นั้นถูกสาปแช่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 9, 'ตามที่เราได้พูดไว้ก่อนแล้ว บัดนี้ข้าพเจ้าพูดอีกว่า ถ้าผู้ใดประกาศข่าวประเสริฐอื่นแก่ท่านที่ขัดกับข่าวประเสริฐซึ่งท่านได้รับไว้แล้ว ผู้นั้นจะต้องถูกสาปแช่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 10, 'บัดนี้ข้าพเจ้ากําลังพูดเอาใจมนุษย์หรือ หรือให้เป็นที่ชอบพระทัยพระเจ้า ข้าพเจ้าอุตส่าห์ประจบประแจงมนุษย์หรือ เพราะถ้าข้าพเจ้ากําลังประจบประแจงมนุษย์อยู่ข้าพเจ้าก็ไม่ใช่ผู้รับใช้ของพระคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 11, 'พี่น้องทั้งหลาย ข้าพเจ้าอยากให้ท่านทราบว่า ข่าวประเสริฐที่ข้าพเจ้าได้ประกาศไปแล้วนั้นไม่ใช่ของมนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 12, 'เพราะว่าข้าพเจ้าไม่ได้รับข่าวประเสริฐนั้นจากมนุษย์ ไม่มีมนุษย์คนใดสอนข้าพเจ้า แต่ข้าพเจ้าได้รับข่าวประเสริฐนั้นโดยพระเยซูคริสต์ทรงสําแดงแก่ข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 13, 'เพราะท่านก็ได้ยินถึงชีวิตในหนหลังของข้าพเจ้า เมื่อข้าพเจ้ายังอยู่ในลัทธิยิวแล้วว่า ข้าพเจ้าได้ข่มเหงคริสตจักรของพระเจ้าอย่างร้ายแรงเหลือเกิน และพยายามที่จะทําลายเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 14, 'และเมื่อข้าพเจ้าอยู่ในลัทธิยิวนั้น ข้าพเจ้าได้ก้าวหน้าเกินกว่าเพื่อนหลายคนที่มีอายุรุ่นราวคราวเดียวกัน และที่เป็นชนชาติเดียวกัน เพราะเหตุที่ข้าพเจ้ามีใจร้อนรนมากกว่าเขาในเรื่องขนบธรรมเนียมของบรรพบุรุษของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 15, 'แต่เมื่อเป็นที่ชอบพระทัยพระเจ้า ผู้ได้ทรงสรรข้าพเจ้าไว้แต่ครรภ์มารดาของข้าพเจ้า และได้ทรงเรียกข้าพเจ้าโดยพระคุณของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 16, 'ที่จะทรงสําแดงพระบุตรของพระองค์ในตัวข้าพเจ้า เพื่อให้ข้าพเจ้าประกาศพระบุตรแก่ชนต่างชาตินั้น ในทันทีนั้นข้าพเจ้าก็ไม่ได้ปรึกษากับเนื้อหนังและเลือดเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 17, 'และข้าพเจ้าก็ไม่ได้ขึ้นไปยังกรุงเยรูซาเล็มเพื่อพบกับผู้ที่เป็นอัครสาวกก่อนข้าพเจ้า แต่ข้าพเจ้าได้ออกไปยังประเทศอาระเบีย แล้วก็กลับมายังเมืองดามัสกัสอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 18, 'แล้วสามปีต่อมา ข้าพเจ้าขึ้นไปหาเปโตรที่กรุงเยรูซาเล็ม และพักอยู่กับท่านสิบห้าวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 19, 'แต่ว่าข้าพเจ้าไม่ได้พบอัครสาวกคนอื่นเลย นอกจากยากอบน้องชายขององค์พระผู้เป็นเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 20, 'แต่เรื่องที่ข้าพเจ้าเขียนมาถึงท่านนี้ ดูเถิด ต่อพระพักตร์พระเจ้า ข้าพเจ้าไม่มุสาเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 21, 'หลังจากนั้นข้าพเจ้าก็เข้าไปในเขตแดนซีเรียและซีลีเซีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 22, 'และคริสตจักรทั้งหลายในแคว้นยูเดียซึ่งอยู่ในพระคริสต์ก็ยังไม่รู้จักหน้าข้าพเจ้าเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 23, 'เขาเพียงแต่ได้ยินว่า “ผู้ที่แต่ก่อนเคยข่มเหงเรา บัดนี้ได้ประกาศความเชื่อซึ่งเขาได้เคยพยายามทําลาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 24, 'พวกเขาได้สรรเสริญพระเจ้าก็เพราะข้าพเจ้าเป็นเหตุ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 1, 'แล้วสิบสี่ปีต่อมา ข้าพเจ้ากับบารนาบัสได้ขึ้นไปยังกรุงเยรูซาเล็มอีกและพาทิตัสไปด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 2, 'ข้าพเจ้าขึ้นไปตามที่พระเจ้าได้ทรงสําแดงแก่ข้าพเจ้า และข้าพเจ้าได้เล่าข่าวประเสริฐที่ข้าพเจ้าประกาศแก่ชนต่างชาติให้เขาฟัง แต่ได้เล่าให้คนสําคัญฟังเป็นส่วนตัวเกรงว่าข้าพเจ้าอาจจะวิ่งแข่งกัน หรือวิ่งแล้วโดยไร้ประโยชน์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 3, 'แต่ถึงแม้ทิตัสซึ่งอยู่กับข้าพเจ้าจะเป็นชาวกรีก เขาก็ไม่ได้ถูกบังคับให้เข้าสุหนัต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 4, 'เพราะเหตุของพี่น้องจอมปลอมที่ได้ลอบเข้ามา เพื่อจะสอดแนมดูเสรีภาพซึ่งเรามีในพระเยซูคริสต์ เพราะพวกเขาหวังจะเอาเราไปเป็นทาส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 5, 'แต่เราไม่ได้ยอมอ่อนข้อให้กับเขาแม้สักชั่วโมงเดียว เพื่อให้ความจริงของข่าวประเสริฐนั้นดํารงอยู่กับท่านทั้งหลายต่อไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 6, 'แต่จากพวกเหล่านั้นที่เขาถือว่าเป็นคนสําคัญ (เขาจะเคยเป็นอะไรมาก่อนก็ตาม ก็ไม่สําคัญอะไรสําหรับข้าพเจ้าเลย พระเจ้ามิได้ทรงเห็นแก่หน้าผู้ใด) คนเหล่านั้นซึ่งเขาถือว่าเป็นคนสําคัญ ไม่ได้เพิ่มเติมสิ่งหนึ่งสิ่งใดให้แก่ข้าพเจ้าเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 7, 'แต่ตรงกันข้าม เมื่อเขาเห็นว่า ข้าพเจ้าได้รับมอบให้ประกาศข่าวประเสริฐแก่คนเหล่านั้นที่ไม่ถือพิธีเข้าสุหนัต เช่นเดียวกับเปโตรได้รับมอบให้ประกาศข่าวประเสริฐแก่คนที่ถือพิธีเข้าสุหนัต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 8, '(เพราะว่า พระองค์ผู้ได้ทรงดลใจเปโตรให้เป็นอัครสาวกไปหาพวกที่ถือพิธีเข้าสุหนัต ก็ได้ทรงดลใจข้าพเจ้าให้ไปหาคนต่างชาติเหมือนกัน)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 9, 'เมื่อยากอบ เคฟาสและยอห์น ผู้ที่เขานับถือว่าเป็นหลักได้เห็นพระคุณซึ่งประทานแก่ข้าพเจ้าแล้ว ก็ได้จับมือขวาของข้าพเจ้ากับบารนาบัสแสดงว่าเราเป็นเพื่อนร่วมงานกัน เพื่อให้เราไปหาคนต่างชาติ และท่านเหล่านั้นจะไปหาพวกที่ถือพิธีเข้าสุหนัต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 10, 'ท่านเหล่านั้นขอแต่เพียงไม่ให้เราลืมนึกถึงคนจน ซึ่งเป็นสิ่งที่ข้าพเจ้ากระตือรือร้นที่จะกระทํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 11, 'แต่เมื่อเปโตรมาถึงอันทิโอกแล้ว ข้าพเจ้าก็ได้คัดค้านท่านซึ่งๆหน้า เพราะว่าท่านทําผิดแน่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 12, 'ด้วยว่าก่อนที่คนของยากอบมาถึงนั้น ท่านได้กินอยู่ด้วยกันกับคนต่างชาติ แต่พอคนพวกนั้นมาถึง ท่านก็ปลีกตัวออกไปอยู่เสียต่างหาก เพราะกลัวพวกที่ถือพิธีเข้าสุหนัต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 13, 'และพวกยิวคนอื่นๆก็ได้แสร้งทําตามท่านเช่นกัน แม้แต่บารนาบัสก็หลงแสร้งทําตามคนเหล่านั้นไปด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 14, 'แต่เมื่อข้าพเจ้าเห็นว่าเขาไม่ได้ดําเนินในความเที่ยงธรรมตามความจริงของข่าวประเสริฐนั้น ข้าพเจ้าจึงว่าแก่เปโตรต่อหน้าคนทั้งปวงว่า “ถ้าท่านเองซึ่งเป็นพวกยิวประพฤติตามอย่างคนต่างชาติ มิใช่ตามอย่างพวกยิว เหตุไฉนท่านจึงบังคับคนต่างชาติให้ประพฤติตามอย่างพวกยิวเล่า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 15, 'เราผู้มีสัญชาติเป็นยิว และไม่ใช่คนบาปในพวกชนต่างชาติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 16, 'ก็ยังรู้ว่าไม่มีผู้ใดเป็นคนชอบธรรมได้โดยการกระทําตามพระราชบัญญัติ แต่โดยความเชื่อในพระเยซูคริสต์เท่านั้น ถึงเราเองก็มีความเชื่อในพระเยซูคริสต์ เพื่อเราจะได้เป็นคนชอบธรรมโดยความเชื่อในพระคริสต์ ไม่ใช่โดยการกระทําตามพระราชบัญญัติ เพราะว่าโดยการกระทําตามพระราชบัญญัตินั้น ‘ไม่มีผู้หนึ่งผู้ใดเป็นคนชอบธรรมได้เลย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 17, 'แต่ถ้าในขณะที่เรากําลังขวนขวายจะเป็นคนชอบธรรมโดยพระคริสต์นั้น เราเองยังปรากฏเป็นคนบาปอยู่ พระคริสต์จึงทรงเป็นผู้ส่งเสริมบาปหรือ ขอพระเจ้าอย่ายอมให้เป็นเช่นนั้นเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 18, 'เพราะว่าถ้าข้าพเจ้าก่อสิ่งซึ่งข้าพเจ้าได้รื้อทําลายลงแล้วขึ้นมาอีก ข้าพเจ้าก็ส่อตัวเองว่าเป็นผู้ละเมิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 19, 'เหตุว่าโดยพระราชบัญญัตินั้นข้าพเจ้าได้ตายจากพระราชบัญญัติแล้ว เพื่อข้าพเจ้าจะได้มีชีวิตอยู่เพื่อพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 20, 'ข้าพเจ้าถูกตรึงไว้กับพระคริสต์แล้ว แต่ข้าพเจ้าก็ยังมีชีวิตอยู่ ไม่ใช่ข้าพเจ้าเองมีชีวิตอยู่ต่อไป แต่พระคริสต์ต่างหากที่ทรงมีชีวิตอยู่ในข้าพเจ้า และชีวิตซึ่งข้าพเจ้าดําเนินอยู่ในร่างกายขณะนี้ ข้าพเจ้าดําเนินอยู่โดยความเชื่อในพระบุตรของพระเจ้า ผู้ได้ทรงรักข้าพเจ้า และได้ทรงสละพระองค์เองเพื่อข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 21, 'ข้าพเจ้าไม่ได้กระทําให้พระคุณของพระเจ้าไร้ประโยชน์ เพราะว่าถ้าความชอบธรรมเกิดจากพระราชบัญญัติแล้ว พระคริสต์ก็ทรงสิ้นพระชนม์โดยเปล่าประโยชน์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 1, 'โอ ชาวกาลาเทียคนเขลา ใครสะกดดวงจิตของท่านเพื่อท่านจะไม่เชื่อฟังความจริง พระเยซูคริสต์ปรากฏอยู่อย่างชัดเจนต่อหน้าต่อตาท่านแล้ว ทั้งถูกตรึงไว้ท่ามกลางพวกท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 2, 'ข้าพเจ้าใคร่รู้ข้อเดียวจากท่านว่า ท่านได้รับพระวิญญาณโดยการกระทําตามพระราชบัญญัติหรือ หรือได้รับโดยการฟังด้วยความเชื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 3, 'ท่านเขลาถึงเพียงนั้นทีเดียวหรือ เมื่อท่านเริ่มต้นด้วยพระวิญญาณแล้ว บัดนี้ท่านจะให้สําเร็จด้วยเนื้อหนังหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 4, 'ท่านได้ทนทุกข์มากมายโดยไร้ประโยชน์หรือ ถ้าเป็นการไร้ประโยชน์จริงๆแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 5, 'เหตุฉะนั้นพระองค์ผู้ทรงประทานพระวิญญาณแก่ท่าน และทรงกระทําการอัศจรรย์ท่ามกลางพวกท่าน ทรงกระทําการเช่นนั้นโดยการกระทําตามพระราชบัญญัติหรือ หรือโดยการฟังด้วยความเชื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 6, 'ดังที่อับราฮัม ‘ได้เชื่อพระเจ้า’ และ ‘พระองค์ทรงนับว่าเป็นความชอบธรรมแก่ท่าน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 7, 'เหตุฉะนั้นท่านจงรู้เถิดว่า คนที่เชื่อนั่นแหละก็เป็นบุตรของอับราฮัม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 8, 'และพระคัมภีร์นั้นรู้ล่วงหน้าว่า พระเจ้าจะทรงให้คนต่างชาติเป็นคนชอบธรรมโดยความเชื่อ จึงได้ประกาศข่าวประเสริฐแก่อับราฮัมล่วงหน้าว่า ‘ชนชาติทั้งหลายจะได้รับพระพรเพราะเจ้า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 9, 'เหตุฉะนั้นคนที่เชื่อจึงได้รับพระพรร่วมกับอับราฮัมผู้ซึ่งเชื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 10, 'เพราะว่าคนทั้งหลายซึ่งพึ่งการกระทําตามพระราชบัญญัติก็ถูกสาปแช่ง เพราะมีคําเขียนไว้ว่า ‘ทุกคนที่มิได้ประพฤติตามทุกข้อความที่เขียนไว้ในหนังสือพระราชบัญญัติก็ต้องถูกสาปแช่ง’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 11, 'แต่เป็นที่ประจักษ์ชัดอยู่แล้วว่า ไม่มีมนุษย์คนใดเป็นผู้ชอบธรรมในสายพระเนตรของพระเจ้าด้วยพระราชบัญญัติได้เลย เพราะว่า ‘คนชอบธรรมจะมีชีวิตดํารงอยู่โดยความเชื่อ’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 12, 'แต่พระราชบัญญัติไม่ได้อาศัยความเชื่อ เพราะ ‘ผู้ที่ประพฤติตามพระราชบัญญัติ ก็จะได้ชีวิตดํารงอยู่โดยพระราชบัญญัตินั้น’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 13, 'พระคริสต์ทรงไถ่เราให้พ้นความสาปแช่งแห่งพระราชบัญญัติ โดยการที่พระองค์ทรงยอมถูกสาปแช่งเพื่อเรา เพราะมีคําเขียนไว้ว่า ‘ทุกคนที่ต้องถูกแขวนไว้บนต้นไม้ก็ต้องถูกสาปแช่ง’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 14, 'เพื่อพระพรของอับราฮัมจะได้มาถึงคนต่างชาติทั้งหลายเพราะพระเยซูคริสต์ เพื่อเราจะได้รับพระสัญญาแห่งพระวิญญาณโดยความเชื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 15, 'พี่น้องทั้งหลาย ข้าพเจ้าขอพูดตามอย่างมนุษย์ ถึงแม้เป็นคําสัญญาของมนุษย์ เมื่อได้รับรองกันแล้วไม่มีผู้ใดจะล้มเลิกหรือเพิ่มเติมขึ้นอีกได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 16, 'แล้วบรรดาพระสัญญาที่ได้ประทานไว้แก่อับราฮัมและเชื้อสายของท่านนั้น พระองค์มิได้ตรัสว่า ‘และแก่เชื้อสายทั้งหลาย’ เหมือนอย่างกับว่าแก่คนมากคน แต่เหมือนกับว่าแก่คนผู้เดียว ‘และแก่เชื้อสายของท่าน’ ซึ่งเป็นพระคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 17, 'แต่ข้าพเจ้าว่าอย่างนี้ว่า พระราชบัญญัติซึ่งมาภายหลังถึงสี่ร้อยสามสิบปี จะทําลายพันธสัญญาซึ่งพระเจ้าได้ทรงตั้งไว้ในพระคริสต์เมื่อก่อนนั้น ให้พระสัญญานั้นขาดจากประโยชน์ไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 18, 'เพราะว่าถ้าได้รับมรดกโดยพระราชบัญญัติ ก็ไม่ใช่ได้โดยพระสัญญาอีกต่อไป แต่พระเจ้าทรงโปรดประทานมรดกนั้นให้แก่อับราฮัมโดยพระสัญญา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 19, 'ถ้าเช่นนั้นมีพระราชบัญญัติไว้ทําไม ที่เพิ่มพระราชบัญญัติไว้ก็เพราะเหตุจากการละเมิด จนกว่าเชื้อสายที่ได้รับพระสัญญานั้นจะมาถึง และพวกทูตสวรรค์ได้ตั้งพระราชบัญญัตินั้นไว้โดยมือของคนกลาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 20, 'เพราะฉะนั้นคนที่เป็นคนกลางก็ไม่ได้เป็นคนกลางของฝ่ายเดียว แต่พระเจ้านั้นทรงเป็นเอกพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 21, 'ถ้าเช่นนั้นพระราชบัญญัติขัดแย้งกับพระสัญญาของพระเจ้าหรือ พระเจ้าไม่ยอมให้เป็นเช่นนั้นเลย เพราะว่าถ้าทรงตั้งพระราชบัญญัติอันสามารถทําให้คนมีชีวิตอยู่ได้ ความชอบธรรมก็จะมีได้โดยพระราชบัญญัตินั้นจริง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 22, 'แต่พระคัมภีร์ได้บ่งว่า ทุกคนอยู่ในความบาป เพื่อจะประทานตามพระสัญญาแก่คนทั้งปวงที่เชื่อ โดยอาศัยความเชื่อในพระเยซูคริสต์เป็นหลัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 23, 'แต่ก่อนที่ความเชื่อมานั้น เราถูกพระราชบัญญัติกักตัวไว้ ถูกกั้นเขตไว้จนความเชื่อจะปรากฏภายหลัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 24, 'เพราะฉะนั้น พระราชบัญญัติจึงเป็นครูของเราซึ่งนําเรามาถึงพระคริสต์ เพื่อเราจะได้เป็นคนชอบธรรมโดยความเชื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 25, 'แต่หลังจากความเชื่อนั้นได้มาแล้ว เราจึงมิได้อยู่ใต้บังคับครูนั้นอีกต่อไปแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 26, 'เพราะว่าท่านทั้งหลายเป็นบุตรของพระเจ้าโดยความเชื่อในพระเยซูคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 27, 'เพราะเหตุว่า ทุกคนในพวกท่านที่รับบัพติศมาเข้าร่วมในพระคริสต์แล้ว ก็ได้สวมชีวิตพระคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 28, 'จะไม่เป็นยิวหรือกรีก จะไม่เป็นทาสหรือไทย จะไม่เป็นชายหรือหญิง เพราะว่าท่านทั้งหลายเป็นอันหนึ่งอันเดียวกันในพระเยซูคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 29, 'และถ้าท่านเป็นของพระคริสต์แล้ว ท่านก็เป็นเชื้อสายของอับราฮัม คือเป็นผู้รับมรดกตามพระสัญญา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 1, 'แล้วข้าพเจ้าขอพูดว่า ตราบใดที่ผู้รับมรดกยังเป็นเด็กอยู่เขาก็ไม่ต่างอะไรกับทาสเลย ถึงแม้เขาจะเป็นเจ้าของทรัพย์สมบัติทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 2, 'แต่เขาก็อยู่ใต้บังคับของผู้ปกครองและผู้ดูแล จนถึงเวลาที่บิดาได้กําหนดไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 3, 'ฝ่ายเราก็เหมือนกัน เมื่อเป็นเด็กอยู่ เราก็เป็นทาสอยู่ใต้บังคับโลกธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 4, 'แต่เมื่อครบกําหนดแล้ว พระเจ้าก็ทรงใช้พระบุตรของพระองค์มาประสูติจากสตรีเพศ และทรงถือกําเนิดใต้พระราชบัญญัติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 5, 'เพื่อจะทรงไถ่คนเหล่านั้นที่อยู่ใต้พระราชบัญญัติ เพื่อให้เราได้รับฐานะเป็นบุตร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 6, 'และเพราะท่านเป็นบุตรแล้ว พระเจ้าจึงทรงใช้พระวิญญาณแห่งพระบุตรของพระองค์เข้ามาในใจของท่าน ร้องว่า “อับบา” คือพระบิดา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 7, 'เหตุฉะนั้นท่านจึงไม่ใช่ทาสอีกต่อไป แต่เป็นบุตร และถ้าเป็นบุตรแล้วท่านก็เป็นผู้รับมรดกของพระเจ้าโดยทางพระคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 8, 'แต่ก่อนนี้เมื่อท่านทั้งหลายยังไม่รู้จักพระเจ้า ท่านเป็นทาสของสิ่งซึ่งโดยสภาพแล้วไม่ใช่พระเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 9, 'แต่บัดนี้เมื่อท่านรู้จักพระเจ้าแล้ว หรือที่ถูกก็คือพระเจ้าทรงรู้จักท่านแล้ว เหตุไฉนท่านจึงจะกลับไปหาโลกธรรมซึ่งอ่อนแอและอนาถา และอยากจะเป็นทาสของสิ่งเหล่านั้นอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 10, 'ท่านถือวัน เดือน ฤดู และปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 11, 'ข้าพเจ้าเกรงว่าการที่ข้าพเจ้าได้ทําเพื่อท่านนั้นจะไร้ประโยชน์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 12, 'พี่น้องทั้งหลาย ข้าพเจ้าวิงวอนให้ท่านเป็นเหมือนข้าพเจ้า เพราะว่าข้าพเจ้าก็ได้เป็นอย่างท่านแล้วเหมือนกัน ท่านไม่ได้ทําผิดต่อข้าพเจ้าเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 13, 'ท่านรู้ว่าตอนแรกที่ข้าพเจ้าประกาศข่าวประเสริฐแก่ท่านนั้น ก็ทําโดยความอ่อนกําลังแห่งเนื้อหนัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 14, 'และการทดลองของข้าพเจ้าซึ่งอยู่ในเนื้อหนังของข้าพเจ้า ท่านก็ไม่ได้ดูหมิ่นหรือปฏิเสธ แต่ได้ต้อนรับข้าพเจ้าเหมือนกับว่าเป็นทูตสวรรค์องค์หนึ่งของพระเจ้า หรือเหมือนกับพระเยซูคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 15, 'ความปลื้มใจที่ท่านได้กล่าวไว้ไปอยู่ที่ไหนเสียแล้ว เพราะข้าพเจ้าเป็นพยานให้ท่านได้ว่า ถ้าเป็นไปได้ท่านก็คงจะควักตาของท่านออกให้ข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 16, 'ข้าพเจ้าจึงได้กลายเป็นศัตรูของท่านเพราะข้าพเจ้าบอกความจริงแก่ท่านหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 17, 'คนเหล่านั้นเอาอกเอาใจท่าน แต่ไม่ใช่ด้วยความหวังดีเลย เขาอยากจะกีดกันพวกท่านเพื่อท่านจะได้เอาอกเอาใจพวกเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 18, 'การเอาอกเอาใจด้วยความหวังดีก็เป็นการดีตลอดไป ไม่ใช่เฉพาะแต่เมื่อข้าพเจ้าอยู่กับพวกท่านเท่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 19, 'ลูกน้อยของข้าพเจ้าเอ๋ย ข้าพเจ้าต้องเจ็บปวดเพราะท่านอีกจนกว่าพระคริสต์จะได้ทรงก่อร่างขึ้นในตัวท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 20, 'ข้าพเจ้าปรารถนาจะอยู่กับพวกท่านเดี๋ยวนี้ และเปลี่ยนน้ําเสียงของข้าพเจ้า เพราะว่าข้าพเจ้ามีข้อสงสัยในตัวท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 21, 'ท่านที่อยากอยู่ใต้พระราชบัญญัติ ท่านไม่ได้ฟังพระราชบัญญัติหรือ จงบอกข้าพเจ้าเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 22, 'เพราะมีเขียนไว้ว่า อับราฮัมมีบุตรชายสองคน คนหนึ่งเกิดจากหญิงทาสี อีกคนหนึ่งเกิดจากหญิงที่เป็นไทย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 23, 'บุตรที่เกิดจากหญิงทาสีนั้นก็เกิดตามเนื้อหนัง แต่ส่วนบุตรที่เกิดจากหญิงที่เป็นไทยนั้นเกิดตามพระสัญญา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 24, 'ข้อความนี้เป็นอุปไมย ผู้หญิงสองคนนั้นได้แก่พันธสัญญาสองอย่าง คนหนึ่งมาจากภูเขาซีนาย คลอดลูกเป็นทาส คือ นางฮาการ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 25, 'นางฮาการ์นั้นได้แก่ภูเขาซีนายในประเทศอาระเบีย ตรงกับกรุงเยรูซาเล็มปัจจุบัน เพราะกรุงนี้กับพลเมืองเป็นทาสอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 26, 'แต่ว่ากรุงเยรูซาเล็มซึ่งอยู่เบื้องบนนั้นเป็นไทย เป็นมารดาของเราทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 27, 'เพราะมีคําเขียนไว้แล้วว่า ‘จงชื่นชมยินดีเถิด หญิงหมันผู้ไม่คลอดบุตร จงเปล่งเสียงโห่ร้อง เจ้าผู้ไม่ได้เจ็บครรภ์ ด้วยว่าหญิงที่ต้องอยู่อย่างโดดเดี่ยวก็ยังมีบุตรมากกว่าหญิงที่ยังมีสามีอยู่กับนางมากมายนัก’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 28, 'พี่น้องทั้งหลาย บัดนี้เราเป็นบุตรแห่งพระสัญญาเช่นเดียวกับอิสอัค');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 29, 'แต่ในครั้งนั้นผู้ที่เกิดตามเนื้อหนังได้ข่มเหงผู้ที่เกิดตามพระวิญญาณฉันใด ปัจจุบันนี้ก็เหมือนกันฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 30, 'แต่พระคัมภีร์ว่าอย่างไร ก็ว่า ‘จงไล่หญิงทาสีกับบุตรชายของนางไปเสียเถิด เพราะว่าบุตรชายของหญิงทาสีจะเป็นผู้รับมรดกร่วมกับบุตรชายของหญิงที่เป็นไทยไม่ได้’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 31, 'เหตุฉะนั้น พี่น้องทั้งหลาย เราไม่ใช่บุตรของหญิงทาสี แต่เป็นบุตรของหญิงที่เป็นไทย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 1, 'เพื่อเสรีภาพนั้นเองพระคริสต์จึงได้ทรงโปรดให้เราเป็นไทย เหตุฉะนั้นจงตั้งมั่นและอย่าเข้าเทียมแอกเป็นทาสอีกเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 2, 'ดูเถิด ข้าพเจ้าเปาโลขอบอกท่านว่า ถ้าท่านเข้าสุหนัตพระคริสต์จะทรงทําประโยชน์อะไรให้แก่ท่านไม่ได้เลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 3, 'ข้าพเจ้าเป็นพยานให้ทุกคนที่เข้าสุหนัตทราบอีกว่า เขาถูกผูกมัดให้ประพฤติตามพระราชบัญญัติทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 4, 'ผู้ใดในหมู่พวกท่านที่เห็นว่าตัวเองเป็นคนชอบธรรมโดยพระราชบัญญัติ ท่านก็หล่นจากพระคุณไปเสียแล้ว พระคริสต์ย่อมไม่ได้มีผลอันใดต่อท่านเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 5, 'เพราะว่า โดยพระวิญญาณและความเชื่อ เราก็รอคอยความชอบธรรมที่เราหวังว่าจะได้รับ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 6, 'เพราะว่าในพระเยซูคริสต์นั้น การเข้าสุหนัตหรือไม่เข้าสุหนัต ก็หาเกิดประโยชน์อันใดไม่ แต่ความเชื่อต่างหากซึ่งกระทํากิจด้วยความรัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 7, 'ท่านวิ่งแข่งดีอยู่แล้ว ใครเล่าขัดขวางท่านไม่ให้เชื่อฟังความจริง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 8, 'การเกลี้ยกล่อมอย่างนี้ไม่ได้มาจากพระองค์ผู้ทรงเรียกท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 9, 'เชื้อขนมเพียงนิดหน่อยย่อมทําให้แป้งดิบฟูขึ้นได้ทั้งก้อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 10, 'ข้าพเจ้าไว้ใจท่านในองค์พระผู้เป็นเจ้าว่า ท่านจะไม่เชื่อถืออย่างอื่นเลย ฝ่ายผู้ที่มารบกวนท่านนั้น จะเป็นใครก็ตามจะต้องได้รับโทษ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 11, 'พี่น้องทั้งหลาย ถ้าข้าพเจ้ายังเทศนาชักชวนให้เข้าสุหนัต เหตุใดข้าพเจ้าจึงยังถูกข่มเหงอยู่อีกเล่า ถ้าเช่นนั้นกางเขนก็ไม่ใช่สิ่งที่ให้สะดุดแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 12, 'ข้าพเจ้าอยากให้คนเหล่านั้นที่รบกวนท่านถูกตัดออกเสียเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 13, 'พี่น้องทั้งหลาย ที่ทรงเรียกท่านก็เพื่อให้มีเสรีภาพ อย่าเอาเสรีภาพของท่านเป็นช่องทางที่จะปล่อยตัวไปตามเนื้อหนัง แต่จงรับใช้ซึ่งกันและกันด้วยความรักเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 14, 'เพราะว่า พระราชบัญญัติทั้งสิ้นนั้นสรุปได้เป็นคําเดียว คือว่า ‘จงรักเพื่อนบ้านเหมือนรักตนเอง’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 15, 'แต่ถ้าท่านกัดและกินเนื้อกันและกัน จงระวังให้ดีเกรงว่าท่านจะทําให้กันและกันย่อยยับไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 16, 'แต่ข้าพเจ้าขอบอกว่า จงดําเนินชีวิตตามพระวิญญาณและท่านจะไม่สนองความต้องการของเนื้อหนัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 17, 'เพราะว่าความต้องการของเนื้อหนังต่อสู้พระวิญญาณ และพระวิญญาณก็ต่อสู้เนื้อหนัง เพราะทั้งสองฝ่ายเป็นศัตรูกัน ดังนั้นสิ่งที่ท่านทั้งหลายปรารถนาทําจึงกระทําไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 18, 'แต่ถ้าพระวิญญาณทรงนําท่าน ท่านก็ไม่อยู่ใต้พระราชบัญญัติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 19, 'แล้วการงานของเนื้อหนังนั้นเห็นได้ชัด คือการเล่นชู้ การล่วงประเวณี การโสโครก การลามก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 20, 'การนับถือรูปเคารพ การนับถือพ่อมดหมอผี การเป็นศัตรูกัน การวิวาทกัน การอิจฉาริษยากัน การโกรธกัน การทุ่มเถียงกัน การใฝ่สูง การแตกก๊กกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 21, 'การอิจฉากัน การฆาตกรรม การเมาเหล้า การเล่นเป็นพาลเกเร และการอื่นๆในทํานองนี้อีก เหมือนที่ข้าพเจ้าได้เตือนท่านมาก่อน บัดนี้ข้าพเจ้าขอเตือนท่านเหมือนกับที่เคยเตือนมาแล้วว่า คนที่ประพฤติเช่นนั้นจะไม่ได้รับอาณาจักรของพระเจ้าเป็นมรดก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 22, 'ฝ่ายผลของพระวิญญาณนั้นคือ ความรัก ความปลาบปลื้มใจ สันติสุข ความอดกลั้นใจ ความปรานี ความดี ความเชื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 23, 'ความสุภาพอ่อนน้อม การรู้จักบังคับตน เรื่องอย่างนี้ไม่มีพระราชบัญญัติห้ามไว้เลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 24, 'ผู้ที่เป็นของพระคริสต์ได้เอาเนื้อหนังกับความอยากและราคะตัณหาของเนื้อหนังตรึงไว้ที่กางเขนเสียแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 25, 'ถ้าเรามีชีวิตอยู่โดยพระวิญญาณ ก็จงดําเนินชีวิตตามพระวิญญาณด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 26, 'เราอย่าถือตัว อย่ายั่วโทสะกัน และอย่าอิจฉาริษยากันเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 1, 'พี่น้องทั้งหลาย ถ้าผู้ใดถูกครอบงําอยู่ในความผิดบาป ท่านซึ่งอยู่ฝ่ายพระวิญญาณ จงช่วยผู้นั้นด้วยใจอ่อนสุภาพให้เขากลับตั้งตัวใหม่ โดยคิดถึงตัวเอง เกรงว่าท่านจะถูกชักจูงให้หลงไปด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 2, 'จงช่วยรับภาระของกันและกัน ท่านจึงจะทําให้พระราชบัญญัติของพระคริสต์สําเร็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 3, 'เพราะว่าถ้าผู้ใดถือตัวว่าเป็นคนสําคัญ ทั้งๆที่เขาไม่สําคัญอะไรเลย ผู้นั้นก็หลอกตัวเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 4, 'แต่ให้ทุกคนสํารวจกิจการของตนเองจึงจะมีอะไรๆที่จะอวดได้ในตนเองผู้เดียว ไม่ใช่เปรียบกับผู้อื่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 5, 'เพราะว่าทุกคนต้องแบกภาระของตนเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 6, 'ส่วนผู้ที่รับคําสอนในพระวจนะแล้ว จงแบ่งสิ่งที่ดีทุกอย่างให้แก่ผู้ที่สอนตนเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 7, 'อย่าหลงเลย ท่านจะหลอกลวงพระเจ้าไม่ได้ เพราะว่าผู้ใดหว่านอะไรลง ก็จะเกี่ยวเก็บสิ่งนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 8, 'ผู้ที่หว่านในย่านเนื้อหนังของตน ก็จะเกี่ยวเก็บความเปื่อยเน่าจากเนื้อหนังนั้น แต่ผู้ที่หว่านในย่านพระวิญญาณ ก็จะเกี่ยวเก็บชีวิตนิรันดร์จากพระวิญญาณนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 9, 'อย่าให้เราเมื่อยล้าในการทําดี เพราะว่าถ้าเราไม่ท้อใจแล้ว เราก็จะเกี่ยวเก็บในเวลาอันสมควร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 10, 'เหตุฉะนั้นเมื่อเรามีโอกาสให้เราทําดีต่อคนทั้งปวง และเฉพาะอย่างยิ่งต่อคนที่อยู่ในครอบครัวของความเชื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 11, 'ท่านจงสังเกตดูตัวอักษรที่ข้าพเจ้าเขียนถึงท่านด้วยมือของข้าพเจ้าเองว่า ตัวโตเพียงใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 12, 'คนที่ปรารถนาได้หน้าตามเนื้อหนัง เขาบังคับให้ท่านเข้าสุหนัต เพื่อเขาจะได้ไม่ถูกข่มเหงเพราะเรื่องกางเขนของพระคริสต์เท่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 13, 'ถึงแม้คนที่เข้าสุหนัตแล้วก็มิได้รักษาพระราชบัญญัติ แต่เขาปรารถนาที่จะให้ท่านเข้าสุหนัต เพื่อเขาจะได้เอาเนื้อหนังของท่านไปอวด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 14, 'แต่พระเจ้าไม่ทรงโปรดให้ข้าพเจ้าอวดตัวนอกจากเรื่องกางเขนของพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเรา ซึ่งโดยกางเขนนั้นโลกตรึงไว้แล้วจากข้าพเจ้า และข้าพเจ้าก็ตรึงไว้แล้วจากโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 15, 'เพราะว่าในพระเยซูคริสต์ การเข้าสุหนัตหรือไม่เข้าสุหนัต ไม่เป็นของสําคัญอะไร แต่การที่ถูกสร้างใหม่นั้นสําคัญ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 16, 'สันติสุขและพระกรุณาจงมีแก่ทุกคนที่ดําเนินตามกฎนี้ และแก่ชนอิสราเอลของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 17, 'ตั้งแต่นี้ไป ขออย่าให้ผู้ใดมารบกวนข้าพเจ้าเลย เพราะว่าข้าพเจ้ามีรอยประทับตราของพระเยซูเจ้าติดอยู่ที่กายของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 18, 'พี่น้องทั้งหลาย ขอให้พระคุณของพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเรา จงสถิตอยู่กับจิตวิญญาณของท่านทั้งหลายด้วยเถิด เอเมน [เขียนถึงชาวกาลาเทียจากกรุงโรม]');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 1, 'เปาโล ผู้เป็นอัครสาวกของพระเยซูคริสต์ตามน้ําพระทัยของพระเจ้า เรียน วิสุทธิชนซึ่งอยู่ที่เมืองเอเฟซัส และผู้สัตย์ซื่อในพระเยซูคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 2, 'ขอให้พระคุณและสันติสุขจากพระเจ้าพระบิดาของเราและจากพระเยซูคริสต์เจ้า ดํารงอยู่กับท่านทั้งหลายด้วยเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 3, 'จงถวายสรรเสริญแด่พระเจ้า พระบิดาแห่งพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเรา ผู้ทรงโปรดประทานพระพรฝ่ายวิญญาณแก่เราทุกๆประการในสวรรคสถานโดยพระคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 4, 'ในพระเยซูคริสต์นั้นพระองค์ได้ทรงเลือกเราไว้ ตั้งแต่ก่อนที่จะทรงเริ่มสร้างโลก เพื่อเราจะบริสุทธิ์และปราศจากตําหนิต่อพระพักตร์ของพระองค์ด้วยความรัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 5, 'พระองค์ทรงกําหนดเราไว้ก่อนตามที่ชอบพระทัยพระองค์ให้เป็นบุตรโดยพระเยซูคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 6, 'เพื่อจะให้เป็นที่สรรเสริญสง่าราศีแห่งพระคุณของพระองค์ ซึ่งโดยพระคุณนั้นพระองค์ทรงบันดาลให้เราเป็นที่ชอบพระทัย ในผู้ทรงเป็นที่รักของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 7, 'ในพระเยซูนั้น เราได้รับการไถ่โดยพระโลหิตของพระองค์ คือได้รับการอภัยโทษบาปของเรา โดยพระคุณอันอุดมของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 8, 'ซึ่งได้ทรงประทานแก่เราอย่างเหลือล้น ให้มีปัญญาสุขุมและมีความรู้รอบคอบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 9, 'พระองค์ได้ทรงโปรดให้เรารู้ความลึกลับในพระทัยของพระองค์ ตามพระเจตนารมณ์ของพระองค์ซึ่งพระองค์ทรงดําริไว้ในพระองค์เอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 10, 'ประสงค์ว่าเมื่อเวลากําหนดครบบริบูรณ์แล้ว พระองค์จะทรงรวบรวมทุกสิ่งทั้งที่อยู่ในสวรรค์และในแผ่นดินโลกไว้ในพระคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 11, 'และในพระองค์นั้นเราได้รับมรดกที่ทรงดําริไว้ตามพระประสงค์ของพระองค์ ผู้ทรงกระทําทุกสิ่งตามที่ได้ทรงตริตรองไว้สมกับพระทัยของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 12, 'เพื่อเราทั้งหลายผู้ได้วางใจในพระคริสต์ก่อนจะได้รับการแต่งตั้งให้เป็นที่สรรเสริญแก่สง่าราศีของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 13, 'และในพระองค์นั้นท่านทั้งหลายก็ได้วางใจเช่นเดียวกัน เมื่อท่านได้ฟังพระวจนะแห่งความจริงคือข่าวประเสริฐเรื่องความรอดของท่าน และได้เชื่อในพระองค์แล้วด้วย ท่านก็ได้รับการผนึกตราไว้ด้วยพระวิญญาณบริสุทธิ์แห่งพระสัญญา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 14, 'ผู้ทรงเป็นมัดจําแห่งมรดกของเรา จนกว่าเราจะได้รับการที่พระองค์ทรงไถ่ไว้แล้วนั้น มาเป็นกรรมสิทธิ์เป็นที่ถวายสรรเสริญแด่สง่าราศีของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 15, 'เหตุฉะนั้นเช่นกันครั้นข้าพเจ้าได้ยินถึงความเชื่อของท่านในพระเยซูเจ้า และความรักใคร่ต่อวิสุทธิชนทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 16, 'ข้าพเจ้าจึงได้ขอบพระคุณเพราะท่านทั้งหลายไม่หยุดเลย คือเอ่ยถึงท่านในคําอธิษฐานของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 17, 'เพื่อพระเจ้าแห่งพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเรา คือพระบิดาผู้ทรงสง่าราศี จะทรงโปรดประทานให้ท่านทั้งหลายมีจิตใจอันประกอบด้วยสติปัญญา และความประจักษ์แจ้งในเรื่องความรู้ถึงพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 18, 'ขอให้ตาแห่งความเข้าใจของท่านสว่างขึ้นเพื่อท่านจะได้รู้ว่า ในการที่พระองค์ทรงเรียกท่านนั้น พระองค์ได้ประทานความหวังอะไรแก่ท่าน และรู้ว่ามรดกของพระองค์สําหรับวิสุทธิชนมีสง่าราศีอันอุดมบริบูรณ์เพียงไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 19, 'และรู้ว่าฤทธานุภาพอันใหญ่ของพระองค์มีมากยิ่งเพียงไรสําหรับเราทั้งหลายที่เชื่อ ตามการกระทําแห่งฤทธานุภาพอันใหญ่ยิ่งของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 20, 'ซึ่งพระองค์ได้ทรงกระทําในพระคริสต์ เมื่อทรงบันดาลให้พระองค์เป็นขึ้นมาจากความตาย และให้สถิตเบื้องขวาพระหัตถ์ของพระองค์เองในสวรรคสถาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 21, 'สูงยิ่งเหนือบรรดาเทพผู้ครอบครอง เหนือศักดิเทพ เหนืออิทธิเทพ เหนือเทพอาณาจักร และเหนือนามทั้งปวงที่เขาเอ่ยขึ้น มิใช่ในยุคนี้เท่านั้นแต่ในยุคที่จะมาถึงด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 22, 'พระเจ้าได้ทรงปราบสิ่งสารพัดลงไว้ใต้พระบาทของพระคริสต์ และได้ทรงตั้งพระองค์ไว้เป็นประมุขเหนือสิ่งสารพัดแห่งคริสตจักร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 23, 'ซึ่งเป็นพระกายของพระองค์ คือซึ่งเต็มบริบูรณ์ด้วยพระองค์ ผู้ทรงอยู่เต็มทุกอย่างทุกแห่งหน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 1, 'พระองค์ทรงกระทําให้ท่านทั้งหลายมีชีวิตอยู่ แม้ว่าท่านตายแล้วโดยการละเมิดและการบาป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 2, 'ครั้งเมื่อก่อนท่านเคยดําเนินตามวิถีของโลกนี้ตามเจ้าแห่งอํานาจในย่านอากาศ คือวิญญาณที่ครอบครองอยู่ในบุตรแห่งการไม่เชื่อฟัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 3, 'เมื่อก่อนเราทั้งปวงเคยประพฤติเป็นพรรคพวกกับคนเหล่านั้นที่ประพฤติตามตัณหาของเนื้อหนังเช่นกัน คือกระทําตามความปรารถนาของเนื้อหนังและความคิดในใจ ตามสันดานเราจึงเป็นบุตรแห่งพระอาชญาเหมือนอย่างคนอื่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 4, 'แต่พระเจ้า ผู้ทรงเปี่ยมด้วยพระกรุณา เพราะเหตุความรักอันใหญ่หลวง ซึ่งพระองค์ทรงรักเรานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 5, 'ถึงแม้ว่าเมื่อเราตายไปแล้วในการบาป พระองค์ยังทรงกระทําให้เรามีชีวิตอยู่กับพระคริสต์ (ซึ่งท่านทั้งหลายรอดนั้นก็รอดโดยพระคุณ)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 6, 'และพระองค์ทรงให้เราเป็นขึ้นมากับพระองค์ และทรงโปรดให้เรานั่งในสวรรคสถานกับพระองค์ในพระเยซูคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 7, 'เพื่อว่าในยุคต่อๆไป พระองค์จะได้ทรงสําแดงพระคุณของพระองค์อันอุดมเหลือล้น ในการซึ่งพระองค์ได้ทรงเมตตาเราในพระเยซูคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 8, 'ด้วยว่าซึ่งท่านทั้งหลายรอดนั้นก็รอดโดยพระคุณเพราะความเชื่อ และมิใช่โดยตัวท่านทั้งหลายเอง แต่พระเจ้าทรงประทานให้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 9, 'ความรอดนั้นจะเนื่องด้วยการกระทําก็หามิได้เพื่อมิให้คนหนึ่งคนใดอวดได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 10, 'เพราะว่าเราเป็นฝีพระหัตถ์ของพระองค์ ที่ทรงสร้างขึ้นในพระเยซูคริสต์ เพื่อให้ประกอบการดีซึ่งพระเจ้าได้ทรงดําริไว้ล่วงหน้าเพื่อให้เราดําเนินตามนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 11, 'เหตุฉะนั้นท่านจงระลึกว่า เมื่อก่อนท่านเคยเป็นคนต่างชาติตามเนื้อหนัง และพวกที่ถือพิธีเข้าสุหนัตซึ่งกระทําแก่เนื้อหนังด้วยมือเคยเรียกท่านว่า เป็นพวกที่มิได้เข้าสุหนัต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 12, 'จงระลึกว่า ครั้งนั้นท่านทั้งหลายเป็นคนอยู่นอกพระคริสต์ ขาดจากการเป็นพลเมืองอิสราเอลและไม่มีส่วนในบรรดาพันธสัญญาซึ่งทรงสัญญาไว้นั้น ไม่มีที่หวัง และอยู่ในโลกปราศจากพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 13, 'แต่บัดนี้ในพระเยซูคริสต์ ท่านทั้งหลายซึ่งเมื่อก่อนอยู่ไกลได้เข้ามาใกล้โดยพระโลหิตของพระคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 14, 'เพราะว่าพระองค์ทรงเป็นสันติสุขของเรา เป็นผู้ทรงกระทําให้ทั้งสองฝ่ายเป็นอันหนึ่งอันเดียวกัน และทรงรื้อกําแพงที่กั้นระหว่างสองฝ่ายลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 15, 'และได้ทรงกําจัดการซึ่งเป็นปฏิปักษ์กันในเนื้อหนังของพระองค์ คือกฎของพระบัญญัติซึ่งให้ถือศีลต่างๆนั้น เพื่อจะกระทําให้ทั้งสองฝ่ายเป็นคนใหม่คนเดียวในพระองค์ เช่นนั้นแหละจึงทรงกระทําให้เกิดสันติสุข');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 16, 'และเพื่อพระองค์จะทรงกระทําให้ทั้งสองพวกคืนดีกับพระเจ้า เป็นกายเดียวโดยกางเขนซึ่งเป็นการทําให้การเป็นปฏิปักษ์ต่อกันหมดสิ้นไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 17, 'และพระองค์ได้เสด็จมาประกาศสันติสุขแก่ท่านที่อยู่ไกล และแก่คนที่อยู่ใกล้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 18, 'เพราะว่าพระองค์ทรงทําให้เราทั้งสองพวกมีโอกาสเข้าเฝ้าพระบิดา โดยพระวิญญาณองค์เดียวกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 19, 'เหตุฉะนั้นบัดนี้ท่านจึงไม่ใช่คนต่างด้าวต่างแดนอีกต่อไป แต่ว่าเป็นพลเมืองเดียวกันกับวิสุทธิชนและเป็นครอบครัวของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 20, 'ท่านได้ถูกประดิษฐานขึ้นบนรากแห่งพวกอัครสาวกและพวกศาสดาพยากรณ์ พระเยซูคริสต์เองทรงเป็นศิลามุมเอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 21, 'ในพระองค์นั้น ทุกส่วนของโครงร่างต่อกันสนิท และเจริญขึ้นเป็นวิหารอันบริสุทธิ์ในองค์พระผู้เป็นเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 22, 'และในพระองค์นั้น ท่านก็กําลังจะถูกก่อขึ้นให้เป็นที่สถิตของพระเจ้าในฝ่ายพระวิญญาณด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 1, 'เพราะเหตุนี้ข้าพเจ้าเปาโล ผู้ที่ถูกจองจําเพราะเห็นแก่พระเยซูคริสต์เพื่อท่านซึ่งเป็นคนต่างชาติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 2, 'ถ้าแม้ท่านทั้งหลายได้ยินถึงพระคุณของพระเจ้าอันเป็นพันธกิจ ซึ่งทรงโปรดประทานแก่ข้าพเจ้าเพื่อท่านทั้งหลายแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 3, 'และรู้ว่าพระองค์ได้ทรงสําแดงให้ข้าพเจ้ารู้ข้อลึกลับ (ตามที่ข้าพเจ้าได้เขียนไว้แล้วอย่างย่อๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 4, 'และโดยคําเหล่านั้น เมื่อท่านอ่านแล้ว ท่านก็รู้ถึงความเข้าใจของข้าพเจ้าในเรื่องความลึกลับของพระคริสต์)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 5, 'ซึ่งในสมัยก่อน ไม่ได้ทรงโปรดสําแดงแก่บุตรทั้งหลายของมนุษย์ เหมือนอย่างบัดนี้ซึ่งทรงโปรดเผยแก่พวกอัครสาวกผู้บริสุทธิ์ และพวกศาสดาพยากรณ์ของพระองค์โดยพระวิญญาณ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 6, 'คือว่าคนต่างชาติจะเป็นผู้รับมรดกร่วมกัน และเป็นอวัยวะของกายอันเดียวกัน และมีส่วนได้รับพระสัญญาของพระองค์ในพระคริสต์โดยข่าวประเสริฐนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 7, 'ข้าพเจ้าได้รับการแต่งตั้งให้เป็นผู้รับใช้แห่งข่าวประเสริฐ ตามพระคุณซึ่งเป็นของประทานจากพระเจ้า ซึ่งทรงโปรดประทานแก่ข้าพเจ้าโดยการกระทําแห่งฤทธิ์เดชของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 8, 'ทรงโปรดประทานพระคุณนี้แก่ข้าพเจ้า ผู้เป็นคนเล็กน้อยกว่าคนเล็กน้อยที่สุดในพวกวิสุทธิชนทั้งหมด ทรงให้ข้าพเจ้าประกาศแก่คนต่างชาติถึงความไพบูลย์ของพระคริสต์ อันหาที่สุดมิได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 9, 'และทําให้คนทั้งปวงเห็นว่า อะไรคือความเป็นอันหนึ่งอันเดียวกันแห่งความลึกลับ ซึ่งตั้งแต่แรกสร้างโลกทรงปิดบังไว้ที่พระเจ้า ผู้ทรงสร้างสารพัดทั้งปวงโดยพระเยซูคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 10, 'ประสงค์จะให้เทพผู้ปกครองและศักดิเทพในสวรรคสถานรู้จักปัญญาอันซับซ้อนของพระเจ้าทางคริสตจักร ณ บัดนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 11, 'ทั้งนี้ก็เป็นไปตามพระประสงค์นิรันดร์ ซึ่งพระองค์ได้ทรงตั้งไว้ในพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 12, 'ในพระองค์นั้น เราจึงมีใจกล้า และมีโอกาสที่จะเข้าไปถึงพระองค์ด้วยความมั่นใจเพราะความเชื่อในพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 13, 'เหตุฉะนั้นข้าพเจ้าจึงขอร้องท่านว่า อย่าท้อถอย เพราะความยากลําบากของข้าพเจ้าเพราะเห็นแก่ท่านซึ่งเป็นสง่าราศีของท่านเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 14, 'เพราะเหตุนี้ ข้าพเจ้าจึงคุกเข่าต่อพระบิดาของพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 15, 'ครอบครัวทั้งหมดในสวรรค์และแผ่นดินโลกก็ได้ชื่อมาจากพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 16, 'ขอให้พระองค์ทรงโปรดประทานกําลังเรี่ยวแรงมากฝ่ายจิตใจแก่ท่าน โดยเดชพระวิญญาณของพระองค์ตามความไพบูลย์แห่งสง่าราศีของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 17, 'เพื่อพระคริสต์จะทรงสถิตในใจของท่านโดยความเชื่อ เนื่องด้วยว่าท่านมีรากมีพื้นฐานที่ทรงวางไว้อย่างมั่นคงในความรักแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 18, 'ท่านก็จะหยั่งรู้ได้ว่าอะไรคือความกว้าง ความยาว ความลึก และความสูงพร้อมกับบรรดาวิสุทธิชนทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 19, 'และให้เข้าใจถึงความรักของพระคริสต์ซึ่งเกินความรู้ เพื่อท่านจะได้รับความไพบูลย์ของพระเจ้าอย่างเต็มเปี่ยม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 20, 'บัดนี้ ขอให้พระเกียรติจงมีแด่พระองค์ผู้ทรงฤทธิ์สามารถกระทําสารพัดมากยิ่งกว่าที่เราจะทูลขอหรือคิดได้ ตามฤทธิ์เดชที่ประกอบกิจอยู่ภายในตัวเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 21, 'ขอให้พระเกียรติจงมีแด่พระองค์ในคริสตจักร โดยพระเยซูคริสต์ตลอดทุกชั่วอายุคนเป็นนิตย์ เอเมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 1, 'เหตุฉะนั้นข้าพเจ้าผู้ถูกจองจําเพราะเห็นแก่องค์พระผู้เป็นเจ้า ขอวิงวอนท่านให้ดําเนินชีวิตสมกับที่ท่านทั้งหลายถูกเรียกแล้วนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 2, 'คือจงมีใจถ่อมลงทุกอย่างและใจอ่อนสุภาพ อดกลั้นไว้นาน และอดทนต่อกันและกันด้วยความรัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 3, 'จงเพียรพยายามเอาสันติสุขผูกมัดความเป็นน้ําหนึ่งใจเดียวของพระวิญญาณ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 4, 'มีกายเดียวและมีพระวิญญาณองค์เดียว เหมือนมีความหวังใจอันเดียวที่เนื่องในการที่ทรงเรียกท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 5, 'มีองค์พระผู้เป็นเจ้าองค์เดียว ความเชื่อเดียว บัพติศมาเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 6, 'พระเจ้าองค์เดียวผู้เป็นพระบิดาของคนทั้งปวง ผู้ทรงอยู่เหนือคนทั้งปวง และทั่วคนทั้งปวง และในท่านทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 7, 'แต่ว่าพระคุณนั้นทรงโปรดประทานแก่เราทุกๆคนตามขนาดที่พระคริสต์ทรงประทานให้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 8, 'เหตุฉะนั้นพระองค์ตรัสไว้แล้วว่า ‘ครั้นพระองค์เสด็จขึ้นสู่เบื้องสูง พระองค์ทรงนําพวกเชลยไปเป็นเชลยอีก และประทานของประทานแก่มนุษย์’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 9, '(ที่กล่าวว่าพระองค์เสด็จขึ้นไปนั้น จะหมายความอย่างอื่นประการใดเล่า นอกจากว่าพระองค์ได้เสด็จลงไปสู่เบื้องต่ําของแผ่นดินโลกก่อนด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 10, 'พระองค์ผู้เสด็จลงไปนั้น ก็คือพระองค์ผู้ที่เสด็จขึ้นไปสู่เบื้องสูงเหนือฟ้าสวรรค์ทั้งปวงนั่นเอง เพื่อจะได้ทําให้สิ่งสารพัดสําเร็จ)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 11, 'พระองค์จึงให้บางคนเป็นอัครสาวก บางคนเป็นศาสดาพยากรณ์ บางคนเป็นผู้ประกาศข่าวประเสริฐ บางคนเป็นศิษยาภิบาล และอาจารย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 12, 'เพื่อเตรียมวิสุทธิชนให้ดีรอบคอบ เพื่อช่วยในการรับใช้ เพื่อเสริมสร้างพระกายของพระคริสต์ให้จําเริญขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 13, 'จนกว่าเราทุกคนจะบรรลุถึงความเป็นน้ําหนึ่งใจเดียวกันในความเชื่อและในความรู้ถึงพระบุตรของพระเจ้า จนกว่าเราจะโตเป็นผู้ใหญ่เต็มที่คือเต็มถึงขนาดความไพบูลย์ของพระคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 14, 'เพื่อเราจะไม่เป็นเด็กอีกต่อไปถูกซัดไปซัดมาและหันไปเหมาด้วยลมปากแห่งคําสั่งสอนทุกอย่าง และด้วยเล่ห์กลของมนุษย์ตามอุบายฉลาดอันเป็นการล่อลวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 15, 'แต่ให้เราพูดความจริงด้วยใจรักเพื่อจะจําเริญขึ้นทุกอย่างสู่พระองค์ผู้เป็นศีรษะคือพระคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 16, 'คือเนื่องจากพระองค์นั้น ร่างกายทั้งสิ้นที่ติดต่อสนิทและผูกพันกันโดยที่ทุกๆข้อต่อได้ช่วยชูกําลังตามขนาดแห่งอวัยวะทุกส่วน ร่างกายนั้นจึงได้จําเริญเติบโตขึ้นเองด้วยความรัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 17, 'เหตุฉะนั้นข้าพเจ้าจึงขอยืนยันและเป็นพยานในองค์พระผู้เป็นเจ้าว่า ตั้งแต่บัดนี้ เป็นต้นไป ท่านอย่าดําเนินตามอย่างคนต่างชาติอื่นๆ ที่เขาดําเนินกันนั้นคือมีใจจดจ่ออยู่กับสิ่งที่ไม่มีสาระ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 18, 'โดยที่ความเข้าใจของเขามืดมนไปและเขาอยู่ห่างจากชีวิตซึ่งมาจากพระเจ้า เพราะเหตุความโง่ซึ่งอยู่ในตัวเขา อันเนื่องจากใจที่แข็งกระด้างของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 19, 'เขามีใจปราศจากความสะดุ้งต่อบาป ปล่อยตัวทําการลามก ทําการโสโครกทุกอย่างด้วยความละโมบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 20, 'แต่ว่าท่านไม่ได้เรียนรู้จักพระคริสต์อย่างนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 21, 'ถ้าแม้ท่านได้ฟังเรื่องพระองค์ และได้รับการสอนโดยพระองค์ตามความจริงซึ่งมีอยู่ในพระเยซูแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 22, 'ท่านจงทิ้งมนุษย์เก่าของท่านซึ่งคู่กับวิถีชีวิตเดิมนั้นเสีย อันจะเสื่อมเสียไปตามตัณหาอันเป็นที่หลอกลวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 23, 'และจงให้จิตใจของท่านเปลี่ยนใหม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 24, 'และให้ท่านสวมมนุษย์ใหม่ซึ่งทรงสร้างขึ้นใหม่ตามแบบอย่างของพระเจ้า ในความชอบธรรมและความบริสุทธิ์ที่แท้จริง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 25, 'เหตุฉะนั้นท่านจงเลิกพูดมุสาเสีย และ ‘จงต่างคนต่างพูดความจริงกับเพื่อนบ้าน’ เพราะว่าเราต่างก็เป็นอวัยวะของกันและกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 26, 'โกรธก็โกรธเถิด แต่อย่าทําบาป อย่าให้ถึงตะวันตกท่านยังโกรธอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 27, 'และอย่าให้โอกาสแก่พญามาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 28, 'คนที่เคยขโมยก็อย่าขโมยอีก แต่จงใช้มือทํางานที่ดีๆกว่า เพื่อจะได้มีอะไรๆแจกให้แก่คนที่ขัดสน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 29, 'อย่าให้คําหยาบคายออกมาจากปากท่านเลย แต่จงกล่าวคําที่ดี และเป็นประโยชน์ให้เกิดความจําเริญเพื่อจะได้เป็นคุณแก่คนที่ได้ยินได้ฟัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 30, 'และอย่าทําให้พระวิญญาณบริสุทธิ์ของพระเจ้าเสียพระทัย เพราะโดยพระวิญญาณนั้นท่านได้ถูกประทับตราหมายท่านไว้จนถึงวันที่ทรงไถ่ให้รอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 31, 'จงให้ใจขมขื่น และใจขัดเคือง และใจโกรธ และการทะเลาะเถียงกัน และการพูดเสียดสี กับการคิดปองร้ายทุกอย่าง อยู่ห่างไกลจากท่านเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 32, 'และท่านจงเมตตาต่อกัน มีใจเอ็นดูต่อกัน และอภัยโทษให้กันเหมือนดังที่พระเจ้าได้ทรงโปรดอภัยโทษให้ท่าน เพราะเห็นแก่พระคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 1, 'เหตุฉะนั้นท่านจงเลียนแบบของพระเจ้า ให้สมกับเป็นบุตรที่รัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 2, 'และจงดําเนินชีวิตในความรักเหมือนดังที่พระคริสต์ได้ทรงรักเรา และทรงประทานพระองค์เองเพื่อเราให้เป็นเครื่องถวาย และเครื่องบูชาแด่พระเจ้าเพื่อเป็นกลิ่นสุคนธรสอันหอมหวาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 3, 'แต่การเอ่ยถึงการล่วงประเวณี การลามกต่างๆและความโลภ อย่าให้มีขึ้นในพวกท่านเลยจะได้สมกับที่ท่านเป็นวิสุทธิชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 4, 'ทั้งอย่าพูดหยาบคาย พูดเล่นไม่เป็นเรื่อง และพูดตลกหยาบโลนเกเร ซึ่งเป็นการไม่สมควร แต่ให้ขอบพระคุณดีกว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 5, 'เพราะท่านรู้แน่ว่า คนล่วงประเวณี คนโสโครก คนโลภ ที่เป็นคนไหว้รูปเคารพ จะได้อาณาจักรของพระคริสต์และของพระเจ้าเป็นมรดกก็หามิได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 6, 'อย่าให้ผู้ใดล่อลวงท่านด้วยคําที่ไม่มีสาระ เพราะการกระทําเหล่านั้นเอง พระเจ้าจึงทรงลงพระอาชญาแก่บุตรแห่งการไม่เชื่อฟัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 7, 'เหตุฉะนั้นท่านอย่าคบหาสมาคมกับคนเหล่านั้นเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 8, 'เพราะว่าเมื่อก่อนท่านเป็นความมืด แต่บัดนี้ท่านเป็นความสว่างแล้วในองค์พระผู้เป็นเจ้า จงดําเนินชีวิตอย่างลูกของความสว่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 9, '(ด้วยว่าผลของพระวิญญาณคือ ความดีทุกอย่างและความชอบธรรมทั้งมวลและความจริงทั้งสิ้น)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 10, 'ท่านจงพิสูจน์ดูว่า ทําประการใดจึงจะเป็นที่ชอบพระทัยองค์พระผู้เป็นเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 11, 'และอย่าเข้าส่วนกับกิจการของความมืดอันไร้ผล แต่จงติเตียนกิจการเหล่านั้นดีกว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 12, 'เพราะว่าแม้แต่จะพูดถึงการเหล่านั้น ซึ่งพวกเขากระทําในที่ลับก็ยังเป็นที่น่าละอาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 13, 'แต่สิ่งสารพัดที่ถูกติเตียนแล้ว ก็จะปรากฏแจ้งโดยความสว่าง เพราะว่าทุกๆสิ่งที่ให้ปรากฏแจ้งก็คือความสว่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 14, 'เหตุฉะนั้นพระองค์ตรัสแล้วว่า ‘คนที่หลับอยู่จงตื่นขึ้นและจงฟื้นขึ้นมาจากความตาย และพระคริสต์จะทรงส่องสว่างแก่ท่าน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 15, 'เหตุฉะนั้นท่านจงระมัดระวังในการดําเนินชีวิตให้ดี อย่าให้เหมือนคนไร้ปัญญา แต่ให้เหมือนคนมีปัญญา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 16, 'จงฉวยโอกาสเพราะว่าทุกวันนี้เป็นกาลที่ชั่ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 17, 'เหตุฉะนั้นอย่าเป็นคนโง่เขลา แต่จงเข้าใจน้ําพระทัยขององค์พระผู้เป็นเจ้าว่าเป็นอย่างไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 18, 'และอย่าเมาเหล้าองุ่นซึ่งจะทําให้เสียคน แต่จงประกอบด้วยพระวิญญาณ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 19, 'จงปราศรัยกันด้วยเพลงสดุดี เพลงนมัสการและเพลงฝ่ายจิตวิญญาณ คือร้องเพลงสรรเสริญและสดุดีจากใจของท่านถวายองค์พระผู้เป็นเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 20, 'จงขอบพระคุณพระเจ้าคือพระบิดาสําหรับสิ่งสารพัดเสมอ ในพระนามพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 21, 'จงยอมฟังกันและกันด้วยความเกรงกลัวพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 22, 'ฝ่ายภรรยาจงยอมฟังสามีของตนเหมือนยอมฟังองค์พระผู้เป็นเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 23, 'เพราะว่าสามีเป็นศีรษะของภรรยา เหมือนพระคริสต์ทรงเป็นศีรษะของคริสตจักร และพระองค์ทรงเป็นพระผู้ช่วยให้รอดของกายนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 24, 'เหตุฉะนั้นคริสตจักรยอมฟังพระคริสต์ฉันใด ภรรยาก็ควรยอมฟังสามีทุกประการฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 25, 'ฝ่ายสามีก็จงรักภรรยาของตน เหมือนอย่างที่พระคริสต์ทรงรักคริสตจักร และทรงประทานพระองค์เองเพื่อคริสตจักร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 26, 'เพื่อพระองค์จะได้ทรงแยกตั้งไว้ และชําระคริสตจักรนั้นให้บริสุทธิ์โดยการล้างด้วยน้ําโดยพระวจนะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 27, 'เพื่อพระองค์จะได้ทรงมอบคริสตจักรที่มีสง่าราศีแด่พระองค์เอง ไม่มีจุดด่างพร้อย ริ้วรอย หรือมลทินใดๆเลย แต่บริสุทธิ์ปราศจากตําหนิ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 28, 'เช่นนั้นแหละ สามีจึงควรจะรักภรรยาของตนเหมือนรักกายของตนเอง ผู้ที่รักภรรยาของตนก็รักตนเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 29, 'เพราะว่าไม่มีผู้ใดเกลียดชังเนื้อหนังของตนเอง มีแต่เลี้ยงดูและทะนุถนอม เหมือนองค์พระผู้เป็นเจ้าทรงกระทําแก่คริสตจักร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 30, 'เพราะว่าเราเป็นอวัยวะแห่งพระกายของพระองค์ แห่งเนื้อหนังของพระองค์ และแห่งกระดูกของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 31, '‘เพราะเหตุนี้ผู้ชายจะจากบิดามารดาของเขา และจะไปผูกพันอยู่กับภรรยา และเขาทั้งสองจะเป็นเนื้ออันเดียวกัน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 32, 'ข้อนี้เป็นข้อลึกลับที่สําคัญมาก แต่ว่าข้าพเจ้าพูดถึงพระคริสต์กับคริสตจักร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 33, 'ถึงอย่างไรก็ดี ท่านทุกคนจงต่างก็รักภรรยาของตนเหมือนรักตนเอง และภรรยาก็จงยําเกรงสามีของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 1, 'ฝ่ายบุตรจงนบนอบเชื่อฟังบิดามารดาของตนในองค์พระผู้เป็นเจ้า เพราะกระทําอย่างนั้นเป็นการถูก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 2, '‘จงให้เกียรติแก่บิดามารดาของเจ้า’ (นี่เป็นพระบัญญัติข้อแรกที่มีพระสัญญาไว้ด้วย)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 3, '‘เพื่อเจ้าจะอยู่เย็นเป็นสุข และมีอายุยืนนานที่แผ่นดินโลก’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 4, 'ฝ่ายท่านผู้เป็นบิดาอย่ายั่วบุตรของตนให้เกิดโทสะ แต่จงอบรมบุตรด้วยการสั่งสอนและการตักเตือนตามหลักขององค์พระผู้เป็นเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 5, 'ฝ่ายพวกทาสจงเชื่อฟังผู้ที่เป็นนายฝ่ายเนื้อหนังด้วยใจเกรงกลัวจนตัวสั่น ด้วยน้ําใสใจจริงเหมือนกระทําแก่พระคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 6, 'ไม่เหมือนอย่างคนที่ทําแต่ต่อหน้า อย่างคนที่ทําให้ชอบใจคน แต่จงทําเหมือนอย่างทาสของพระคริสต์คือกระทําตามชอบพระทัยพระเจ้าด้วยความเต็มใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 7, 'จงปรนนิบัตินายด้วยจิตใจชื่นบาน เหมือนกับปรนนิบัติองค์พระผู้เป็นเจ้า ไม่ใช่ปรนนิบัติมนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 8, 'เพราะท่านรู้อยู่แล้วว่าผู้ใดกระทําความดีประการใด ผู้นั้นก็จะได้รับบําเหน็จอย่างนั้นจากองค์พระผู้เป็นเจ้าอีก ไม่ว่าเขาจะเป็นทาสหรือเป็นไทย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 9, 'ฝ่ายนายจงกระทําต่อทาสในทํานองเดียวกัน คืออย่าขู่เข็ญเขา เพราะท่านก็รู้แล้วว่านายของท่านทรงประทับอยู่ในสวรรค์ และพระองค์ไม่ทรงเลือกหน้าผู้ใดเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 10, 'พี่น้องทั้งหลายของข้าพเจ้า สุดท้ายนี้ขอท่านจงมีกําลังขึ้นในองค์พระผู้เป็นเจ้า และในฤทธิ์เดชอันมหันต์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 11, 'จงสวมยุทธภัณฑ์ทั้งชุดของพระเจ้าเพื่อจะต่อต้านยุทธอุบายของพญามารได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 12, 'เพราะว่าเราไม่ได้ต่อสู้กับเนื้อหนังและเลือดแต่ต่อสู้กับเทพผู้ครอบครอง ศักดิเทพ เทพผู้ครองพิภพในโมหะความมืดแห่งโลกนี้ ต่อสู้กับเหล่าวิญญาณที่ชั่วในสถานฟ้าอากาศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 13, 'เหตุฉะนั้นจงรับยุทธภัณฑ์ทั้งชุดของพระเจ้าไว้ เพื่อท่านจะได้ต่อต้านในวันอันชั่วร้ายนั้นและเมื่อเสร็จแล้วจะยืนมั่นได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 14, 'เหตุฉะนั้นท่านจงยืนมั่น เอาความจริงคาดเอว เอาความชอบธรรมเป็นทับทรวงเครื่องป้องกันอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 15, 'และเอาข่าวประเสริฐแห่งสันติสุข ซึ่งเป็นเหตุให้เกิดความพรั่งพร้อมมาสวมเป็นรองเท้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 16, 'และพร้อมกับสิ่งทั้งหมดนี้ จงเอาความเชื่อเป็นโล่ ด้วยโล่นั้นท่านจะได้ดับลูกศรเพลิงของผู้ชั่วร้ายนั้นเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 17, 'จงเอาความรอดเป็นหมวกเหล็กป้องกันศีรษะและจงถือพระแสงของพระวิญญาณ คือพระวจนะของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 18, 'จงอธิษฐานวิงวอนทุกอย่างและจงขอโดยพระวิญญาณทุกเวลา ทั้งนี้จงระวังตัวด้วยความเพียรทุกอย่าง จงอธิษฐานเพื่อวิสุทธิชนทุกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 19, 'และอธิษฐานเพื่อข้าพเจ้าด้วย เพื่อจะทรงประทานให้ข้าพเจ้ามีคําพูดและเกิดใจกล้าประกาศถึงข้อลึกลับแห่งข่าวประเสริฐได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 20, 'เพราะข่าวประเสริฐนี้เองทําให้ข้าพเจ้าเป็นทูตผู้ต้องติดโซ่อยู่ เพื่อข้าพเจ้าจะเล่าข่าวประเสริฐด้วยใจกล้าตามที่ข้าพเจ้าควรจะกล่าว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 21, 'แต่เพื่อให้ท่านได้รู้เหตุการณ์ทั้งปวงของข้าพเจ้าว่า ข้าพเจ้าเป็นอยู่อย่างไร ทีคิกัส ซึ่งเป็นน้องที่รักและเป็นผู้รับใช้อันสัตย์ซื่อในองค์พระผู้เป็นเจ้า จะได้บอกท่านให้ทราบถึงเหตุการณ์ทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 22, 'ข้าพเจ้าให้ผู้นี้ไปหาท่าน ก็เพราะเหตุนี้เอง คือให้ท่านได้ทราบถึงเหตุการณ์ทั้งปวงของเรา และเพื่อให้เขาหนุนน้ําใจของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 23, 'ขอให้พวกพี่น้องได้รับสันติสุขและความรักโดยความเชื่อมาจากพระเจ้าพระบิดาและจากพระเยซูคริสต์เจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 24, 'ขอพระคุณดํารงอยู่กับบรรดาคนที่รักพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเราด้วยความจริงใจ เอเมน [เขียนถึงชาวเอเฟซัสจากกรุงโรม และส่งโดยทีคิกัส]');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 1, 'เปาโลและทิโมธี ผู้รับใช้ของพระเยซูคริสต์ เรียน บรรดาวิสุทธิชนในพระเยซูคริสต์ ซึ่งอยู่ในเมืองฟีลิปปี ทั้งบรรดาผู้ดูแลและผู้ช่วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 2, 'ขอให้พระคุณและสันติสุขจากพระเจ้าพระบิดาของเราและจากพระเยซูคริสต์เจ้า จงดํารงอยู่กับท่านเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 3, 'ข้าพเจ้าระลึกถึงท่านเมื่อใด ข้าพเจ้าก็ขอบพระคุณพระเจ้าของข้าพเจ้าทุกครั้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 4, 'และทุกเวลาที่ข้าพเจ้าอธิษฐานเพื่อท่านทุกคน ข้าพเจ้าก็ทูลขอด้วยความยินดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 5, 'เพราะเหตุที่ท่านทั้งหลายมีส่วนในข่าวประเสริฐด้วยกัน ตั้งแต่วันแรกมาจนกระทั่งบัดนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 6, 'ข้าพเจ้าแน่ใจในสิ่งนี้ว่า พระองค์ผู้ทรงตั้งต้นการดีไว้ในพวกท่านแล้ว จะทรงกระทําให้สําเร็จจนถึงวันแห่งพระเยซูคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 7, 'การที่ข้าพเจ้าคิดอย่างนั้นเนื่องด้วยท่านทั้งหลายก็สมควรแล้ว เพราะว่าข้าพเจ้ามีท่านในใจของข้าพเจ้า ท่านทั้งหลายได้รับส่วนในพระคุณด้วยกันกับข้าพเจ้า ในการที่ข้าพเจ้าถูกจองจํา และในการกล่าวแก้ และหนุนให้ข่าวประเสริฐนั้นตั้งมั่นคงอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 8, 'เพราะว่าพระเจ้าทรงเป็นพยานของข้าพเจ้าว่า ข้าพเจ้าเป็นห่วงท่านทั้งหลายเพียงไรตามพระทัยเมตตาของพระเยซูคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 9, 'และข้าพเจ้าอธิษฐานขอให้ความรักของท่านจําเริญยิ่งๆขึ้นในความรู้และในวิจารณญาณทุกอย่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 10, 'เพื่อท่านทั้งหลายจะสังเกตได้ว่าสิ่งใดประเสริฐที่สุด และเพื่อท่านจะได้เป็นคนซื่อสัตย์ และไม่เป็นที่ติได้ จนถึงวันของพระคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 11, 'จะได้เป็นผู้ที่บริบูรณ์ด้วยผลของความชอบธรรม ซึ่งเกิดขึ้นโดยพระเยซูคริสต์ เพื่อถวายพระเกียรติและความสรรเสริญแด่พระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 12, 'พี่น้องทั้งหลาย ข้าพเจ้าปรารถนาให้ท่านทราบว่า การทั้งปวงที่อุบัติขึ้นกับข้าพเจ้านั้น ได้กลับเป็นเหตุให้ข่าวประเสริฐแผ่แพร่กว้างออกไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 13, 'จนการที่ข้าพเจ้าถูกพันธนาการเพราะพระคริสต์นั้น ก็ปรากฏทั่วตลอดกองผู้คุมและทั่วสถานที่แห่งอื่นๆทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 14, 'และพี่น้องมากมายในองค์พระผู้เป็นเจ้าที่ได้เกิดความเชื่อมั่นเนื่องด้วยเครื่องพันธนาการทั้งหลายของข้าพเจ้า และพวกเขาก็มีใจกล้าขึ้นที่จะกล่าวพระวจนะนั้นโดยปราศจากความกลัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 15, 'ความจริงมีบางคนประกาศพระคริสต์ด้วยจิตใจริษยาและทุ่มเถียงกัน แต่ก็มีคนอื่นที่ประกาศด้วยใจหวังดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 16, 'ฝ่ายหนึ่งประกาศพระคริสต์ด้วยการชิงดีชิงเด่นกัน ไม่ใช่ด้วยความจริงใจ จงใจจะเพิ่มความทุกข์ยากให้แก่เครื่องพันธนาการของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 17, 'แต่ฝ่ายหนึ่งประกาศด้วยใจรัก โดยรู้แล้วว่าทรงตั้งข้าพเจ้าไว้ป้องกันข่าวประเสริฐนั้นไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 18, 'ถ้าเช่นนั้นจะแปลกอะไร แม้เขาจะประกาศด้วยประการใดก็ตาม จะเป็นด้วยการแกล้งทําก็ดี หรือด้วยใจจริงก็ดี แต่เขาก็ได้ประกาศพระคริสต์ ในการนี้ทําให้ข้าพเจ้ามีความยินดี และจะมีความชื่นชมยินดีต่อไปด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 19, 'เพราะข้าพเจ้ารู้ว่า โดยคําอธิษฐานของท่าน และโดยการช่วยเหลือของพระวิญญาณแห่งพระเยซูคริสต์นี้ จะเป็นเหตุให้ข้าพเจ้ารับการช่วยให้พ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 20, 'เพราะว่าเป็นความมุ่งมาดปรารถนาและความหวังของข้าพเจ้าว่า ข้าพเจ้าจะไม่ได้รับความละอายใดๆเลย แต่เมื่อก่อนทุกครั้งมีใจกล้าเสมอฉันใด บัดนี้ก็ขอให้เป็นเช่นเดียวกันฉันนั้น พระคริสต์จะได้ทรงรับเกียรติในร่างกายของข้าพเจ้าเสมอ แม้จะโดยชีวิตหรือโดยความตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 21, 'เพราะว่าสําหรับข้าพเจ้านั้น การมีชีวิตอยู่ก็เพื่อพระคริสต์ และการตายก็ได้กําไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 22, 'แต่ถ้าข้าพเจ้ายังจะมีชีวิตอยู่ในร่างกาย ข้าพเจ้าก็จะทํางานให้เกิดผล แต่ข้าพเจ้าบอกไม่ได้ว่าจะเลือกฝ่ายไหนดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 23, 'ข้าพเจ้าลังเลใจอยู่ในระหว่างสองฝ่ายนี้ คือว่า ข้าพเจ้ามีความปรารถนาที่จะจากไปเพื่ออยู่กับพระคริสต์ ซึ่งประเสริฐกว่ามากนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 24, 'แต่การที่ข้าพเจ้ายังมีชีวิตอยู่ในร่างกายนี้ ก็มีความจําเป็นสําหรับพวกท่านมากกว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 25, 'เมื่อข้าพเจ้าแน่ใจอย่างนี้แล้ว ข้าพเจ้าก็ทราบว่าข้าพเจ้าจะยังอยู่ และคงอยู่กับท่านทั้งหลายเพื่อให้ท่านจําเริญขึ้นและชื่นชมยินดีในความเชื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 26, 'เพื่อความปลาบปลื้มของท่านจะมากยิ่งขึ้นในพระเยซูคริสต์เนื่องด้วยข้าพเจ้า เพราะข้าพเจ้าจะมาหาท่านอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 27, 'ขอแต่เพียงให้ท่านดําเนินชีวิตให้สมกับข่าวประเสริฐของพระคริสต์ เพื่อว่าแม้ข้าพเจ้าจะมาหาท่านหรือไม่ก็ตาม ข้าพเจ้าก็จะได้รู้ข่าวของท่านว่า ท่านตั้งมั่นคงอยู่ เป็นน้ําหนึ่งใจเดียวกัน ต่อสู้เหมือนอย่างเป็นคนเดียวเพื่อความเชื่อแห่งข่าวประเสริฐนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 28, 'และไม่เกรงกลัวผู้ที่ขัดขวางท่านแต่ประการใดเลย เมื่อเป็นเช่นนี้ก็จะเป็นที่ประจักษ์แก่เขาว่า พวกเขาจะถึงซึ่งความพินาศ แต่พวกท่านก็จะถึงซึ่งความรอด และการนั้นมาจากพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 29, 'เพราะว่าได้ทรงโปรดแก่ท่านเพราะเห็นแก่พระคริสต์ มิใช่ให้ท่านเชื่อถือในพระองค์เท่านั้น แต่ให้ท่านทนความทุกข์ยากเพราะเห็นแก่พระองค์ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 30, 'คือให้ท่านต้องต่อสู้เช่นเดียวกับที่ท่านได้เห็นข้าพเจ้าต่อสู้ และซึ่งท่านได้ยินว่าข้าพเจ้ากําลังสู้อยู่ในขณะนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 1, 'เหตุฉะนั้นถ้าได้รับการเร้าใจประการใดในพระคริสต์ ถ้ามีการหนุนใจประการใดในความรัก ถ้ามีส่วนประการใดกับพระวิญญาณ ถ้ามีการรักใคร่เอ็นดูและเห็นอกเห็นใจประการใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 2, 'ก็ขอให้ท่านทําให้ความยินดีของข้าพเจ้าเต็มเปี่ยม ด้วยการมีความคิดอย่างเดียวกัน มีความรักอย่างเดียวกัน มีใจรู้สึกและคิดพร้อมเพรียงกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 3, 'อย่าทําสิ่งใดในทางทุ่มเถียงกันหรืออวดดี แต่จงมีใจถ่อมถือว่าคนอื่นดีกว่าตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 4, 'อย่าให้ต่างคนต่างเห็นแก่ประโยชน์ของตนฝ่ายเดียว แต่จงเห็นแก่ประโยชน์ของคนอื่นๆด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 5, 'ท่านจงมีน้ําใจอย่างนี้ เหมือนอย่างที่พระเยซูคริสต์ทรงมีด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 6, 'พระองค์ผู้ทรงอยู่ในสภาพพระเจ้ามิได้ทรงเห็นว่าการเท่าเทียมกับพระเจ้านั้นเป็นการแย่งชิงเอาไปเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 7, 'แต่ได้ทรงกระทําพระองค์เองให้ไม่มีชื่อเสียงใดๆ และทรงรับสภาพอย่างผู้รับใช้ ทรงถือกําเนิดในลักษณะของมนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 8, 'และเมื่อทรงปรากฏพระองค์ในสภาพมนุษย์แล้ว พระองค์ก็ทรงถ่อมพระองค์ลง ยอมเชื่อฟังจนถึงความมรณา กระทั่งความมรณาที่กางเขน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 9, 'เหตุฉะนั้นพระเจ้าจึงได้ทรงยกพระองค์ขึ้นอย่างสูงที่สุดด้วย และได้ทรงประทานพระนามเหนือนามทั้งปวงให้แก่พระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 10, 'เพื่อ ‘หัวเข่าทุกหัวเข่า’ ในสวรรค์ก็ดี ที่แผ่นดินโลกก็ดี ใต้พื้นแผ่นดินโลกก็ดี ‘จะต้องคุกกราบลง’ นมัสการในพระนามแห่งพระเยซูนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 11, 'และเพื่อ ‘ลิ้นทุกลิ้นจะยอมรับ’ ว่าพระเยซูคริสต์ทรงเป็นองค์พระผู้เป็นเจ้า อันเป็นการถวายพระเกียรติแด่พระเจ้าพระบิดา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 12, 'เหตุฉะนี้พวกที่รักของข้าพเจ้า เหมือนท่านทั้งหลายได้ยอมเชื่อฟังทุกเวลา และไม่ใช่เมื่อข้าพเจ้าอยู่ด้วยเท่านั้น แต่เดี๋ยวนี้เมื่อข้าพเจ้าไม่อยู่ด้วย ท่านทั้งหลายจงให้ความรอดของตนเกิดผลด้วยความเกรงกลัวตัวสั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 13, 'เพราะว่าพระเจ้าเป็นผู้ทรงกระทํากิจอยู่ภายในท่าน ทั้งให้ท่านมีใจปรารถนาและให้ประพฤติตามชอบพระทัยของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 14, 'จงกระทําสิ่งสารพัดโดยปราศจากการบ่นและการทุ่มเถียงกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 15, 'เพื่อท่านทั้งหลายจะปราศจากตําหนิและไม่มีความผิด เป็น ‘บุตรที่ปราศจากตําหนิของพระเจ้า’ ในท่ามกลาง ‘ยุคที่คดโกงและวิปลาส’ ท่านปรากฏในหมู่พวกเขาดุจดวงสว่างต่างๆในโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 16, 'โดยการป่าวประกาศยกพระวจนะอันมีชีวิตไว้อยู่เสมอ เพื่อข้าพเจ้าจะได้ชื่นชมยินดีในวันของพระคริสต์ว่า ข้าพเจ้าไม่ได้วิ่งเปล่าๆ และไม่ได้ทํางานโดยเปล่าประโยชน์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 17, 'แท้จริงถ้าแม้ข้าพเจ้าต้องถวายตัวเป็นเครื่องบูชา และเป็นการปรนนิบัติเพราะความเชื่อของท่านทั้งหลาย ข้าพเจ้ายังจะมีความชื่นชมยินดีด้วยกันกับท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 18, 'ซึ่งท่านก็ควรจะยินดีและชื่นชมด้วยกันกับข้าพเจ้าด้วยเช่นเดียวกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 19, 'แต่ข้าพเจ้าหวังใจในพระเยซูเจ้าว่า ในไม่ช้าข้าพเจ้าจะให้ทิโมธีไปหาพวกท่าน เพื่อข้าพเจ้าจะได้รับความชูใจเช่นกันเมื่อได้รับข่าวของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 20, 'เพราะว่าข้าพเจ้าไม่มีผู้ใดที่มีน้ําใจเหมือนทิโมธี ซึ่งจะเอาใจใส่ในทุกข์สุขของท่านอย่างแท้จริง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 21, 'เพราะว่าคนทั้งหลายย่อมแสวงหาประโยชน์ของตนเอง ไม่ได้แสวงหาประโยชน์ของพระเยซูคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 22, 'แต่ท่านก็รู้ถึงคุณค่าของทิโมธีแล้วว่า เขาได้รับใช้ร่วมกับข้าพเจ้าในการประกาศข่าวประเสริฐ เสมือนบุตรรับใช้บิดา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 23, 'เหตุฉะนั้นข้าพเจ้าหวังใจว่า พอจะเห็นได้ว่าจะเกิดการอย่างไรแก่ข้าพเจ้า ข้าพเจ้าจะใช้เขาไปโดยเร็ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 24, 'แต่ข้าพเจ้าไว้วางใจในองค์พระผู้เป็นเจ้าว่า ในไม่ช้าข้าพเจ้าเองจะมาหาท่านด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 25, 'ข้าพเจ้าคิดแล้วว่า จะต้องให้เอปาโฟรดิทัสน้องชายของข้าพเจ้า ซึ่งเป็นเพื่อนร่วมงานและเพื่อนทหารของข้าพเจ้า และเป็นผู้นําข่าวของพวกท่าน และได้ปรนนิบัติข้าพเจ้าในยามขัดสน มาหาท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 26, 'เพราะว่าเขาคิดถึงท่านทุกคน และเป็นทุกข์มากเพราะท่านได้ข่าวว่าเขาป่วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 27, 'เขาป่วยจริงๆ ป่วยจนเกือบจะตาย แต่พระเจ้าทรงพระกรุณาโปรดเขา และไม่ใช่ทรงโปรดเขาคนเดียว แต่ทรงโปรดข้าพเจ้าด้วย เพื่อไม่ให้ข้าพเจ้ามีความทุกข์ซ้อนทุกข์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 28, 'เหตุฉะนั้นข้าพเจ้าจึงรีบร้อนใช้เขาไป หวังว่าเมื่อท่านทั้งหลายได้เห็นเขาอีก ท่านจะได้ชื่นชมยินดี และความทุกข์ของข้าพเจ้าจะเบาบางไปสักหน่อย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 29, 'เหตุฉะนั้นท่านจงต้อนรับเขาไว้ในองค์พระผู้เป็นเจ้าด้วยความยินดีทุกอย่าง และจงนับถือคนอย่างนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 30, 'ด้วยว่าเขาเกือบจะตายเสียแล้วเพราะเห็นแก่การของพระคริสต์ คือได้เสี่ยงชีวิตของตน เพื่อการปรนนิบัติของท่านทั้งหลายที่บกพร่องต่อข้าพเจ้าอยู่นั้นจะได้เต็มบริบูรณ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 1, 'สุดท้ายนี้ พวกพี่น้องของข้าพเจ้า จงชื่นชมยินดีในองค์พระผู้เป็นเจ้า การที่ข้าพเจ้าเขียนข้อความเหล่านี้ถึงท่านซ้ําอีก ก็หาเป็นการลําบากแก่ข้าพเจ้าไม่ แต่เป็นการปลอดภัยสําหรับท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 2, 'จงระวังพวกสุนัข จงระวังบรรดาคนที่ทําชั่ว จงระวังพวกถือการเชือดเนื้อเถือหนัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 3, 'เพราะว่าเราทั้งหลายเป็นพวกถือพิธีเข้าสุหนัต คือเป็นผู้นมัสการพระเจ้าด้วยจิตวิญญาณ และชื่นชมยินดีในพระเยซูคริสต์ และไม่ได้ไว้ใจในเนื้อหนัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 4, 'ถึงแม้ว่าข้าพเจ้าเองมีเหตุที่จะไว้ใจในเนื้อหนัง ถ้าผู้อื่นคิดว่าเขามีเหตุผลที่จะไว้ใจในเนื้อหนัง ข้าพเจ้าก็มีมากกว่าเขาเสียอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 5, 'คือเมื่อข้าพเจ้าเกิดมาได้แปดวันก็ได้เข้าสุหนัต ข้าพเจ้าเป็นชนชาติอิสราเอล ตระกูลเบนยามิน เป็นชาติฮีบรูเกิดจากชาวฮีบรู ในด้านพระราชบัญญัติก็อยู่ในคณะฟาริสี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 6, 'ในด้านความกระตือรือร้นก็ได้ข่มเหงคริสตจักร ในด้านความชอบธรรมซึ่งมีอยู่โดยพระราชบัญญัติ ข้าพเจ้าก็ไม่มีที่ติได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 7, 'แต่ว่าสิ่งใดที่เคยเป็นคุณประโยชน์แก่ข้าพเจ้า ข้าพเจ้าถือว่าสิ่งนั้นไร้ประโยชน์แล้วเพื่อเห็นแก่พระคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 8, 'ที่จริงข้าพเจ้าถือว่าสิ่งสารพัดไร้ประโยชน์เพราะเห็นแก่ความประเสริฐแห่งความรู้ถึงพระเยซูคริสต์องค์พระผู้เป็นเจ้าของข้าพเจ้า เพราะเหตุพระองค์ ข้าพเจ้าจึงได้ยอมสละสิ่งสารพัด และถือว่าสิ่งเหล่านั้นเป็นเหมือนหยากเยื่อ เพื่อข้าพเจ้าจะได้พระคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 9, 'และจะได้ปรากฏอยู่ในพระองค์ ไม่มีความชอบธรรมของข้าพเจ้าเองซึ่งได้มาโดยพระราชบัญญัติ แต่มีมาโดยความเชื่อในพระคริสต์ เป็นความชอบธรรมซึ่งมาจากพระเจ้าโดยความเชื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 10, 'เพื่อข้าพเจ้าจะได้รู้จักพระองค์ และฤทธิ์เดชแห่งการฟื้นคืนพระชนม์ของพระองค์ และร่วมทุกข์กับพระองค์ คือยอมตั้งอารมณ์ตายเหมือนพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 11, 'ถ้าโดยวิธีหนึ่งวิธีใดข้าพเจ้าก็จะได้เป็นขึ้นมาจากความตายด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 12, 'มิใช่ว่าข้าพเจ้าได้แล้ว หรือสําเร็จแล้ว แต่ข้าพเจ้ากําลังบากบั่นมุ่งไป เพื่อข้าพเจ้าจะได้ฉวยเอาตามอย่างที่พระเยซูคริสต์ได้ทรงฉวยข้าพเจ้าไว้เป็นของพระองค์แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 13, 'พี่น้องทั้งหลาย ข้าพเจ้าไม่ถือว่าข้าพเจ้าได้ฉวยไว้ได้แล้ว แต่ข้าพเจ้าทําอย่างหนึ่ง คือลืมสิ่งที่ผ่านพ้นมาแล้วเสีย และโน้มตัวออกไปหาสิ่งที่อยู่ข้างหน้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 14, 'ข้าพเจ้ากําลังบากบั่นมุ่งไปสู่หลักชัย เพื่อจะได้รับรางวัลซึ่งพระเจ้าได้ทรงเรียกจากเบื้องบนให้เราไปรับในพระเยซูคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 15, 'เหตุฉะนั้นให้เราซึ่งเป็นผู้ใหญ่แล้วมีใจคิดอย่างนั้น และถ้าท่านคิดอย่างอื่น พระเจ้าก็จะทรงโปรดสําแดงสิ่งนี้ให้แก่ท่านด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 16, 'แต่เราได้แค่ไหนแล้ว ก็ให้เราดําเนินตรงตามนั้นต่อไป คือให้เราคิดเห็นอย่างเดียวกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 17, 'พี่น้องทั้งหลาย ท่านจงดําเนินตามอย่างข้าพเจ้า และคอยดูคนทั้งหลายเหล่านั้นที่ดําเนินตามอย่างเดียวกัน เหมือนท่านทั้งหลายได้พวกเราเป็นตัวอย่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 18, '(เพราะว่ามีคนหลายคนที่ประพฤติตัวเป็นศัตรูต่อกางเขนของพระคริสต์ ซึ่งข้าพเจ้าได้บอกท่านถึงเรื่องของเขาหลายครั้งแล้ว และบัดนี้ยังบอกท่านอีกด้วยน้ําตาไหล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 19, 'ปลายทางของคนเหล่านั้นคือความพินาศ พระของเขาคือกระเพาะ เขายกความที่น่าอับอายของเขาขึ้นมาโอ้อวด เขาสนใจในวัตถุทางโลก)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 20, 'ฝ่ายเราเป็นชาวสวรรค์ เรารอคอยพระผู้ช่วยให้รอดซึ่งจะเสด็จมาจากสวรรค์ คือพระเยซูคริสต์เจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 21, 'พระองค์จะทรงเปลี่ยนแปลงกายอันต่ําต้อยของเรา ให้เหมือนพระกายอันทรงสง่าราศีของพระองค์ ด้วยฤทธานุภาพซึ่งพระองค์ทรงสามารถปราบสิ่งสารพัดลงใต้อํานาจของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 1, 'เหตุฉะนั้นพี่น้องทั้งหลายของข้าพเจ้า ผู้เป็นที่รัก เป็นที่ปรารถนา เป็นที่ยินดี และเป็นมงกุฎของข้าพเจ้า พวกที่รักของข้าพเจ้า จงยืนมั่นในองค์พระผู้เป็นเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 2, 'ข้าพเจ้าขอเตือนนางยูโอเดีย และขอเตือนนางสินทิเคให้มีจิตใจปรองดองกันในองค์พระผู้เป็นเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 3, 'ข้าพเจ้าขอร้องท่านด้วย ผู้เป็นเพื่อนร่วมแอกแท้ๆของข้าพเจ้า ให้ท่านช่วยผู้หญิงเหล่านั้น ผู้ซึ่งได้ทํางานในข่าวประเสริฐด้วยกันกับข้าพเจ้าและกับเคลเมด้วย รวมทั้งคนอื่นที่เป็นเพื่อนร่วมงานของข้าพเจ้า ซึ่งชื่อของเขาเหล่านั้นมีอยู่ในหนังสือแห่งชีวิตแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 4, 'จงชื่นชมยินดีในองค์พระผู้เป็นเจ้าทุกเวลา ข้าพเจ้าขอย้ําอีกครั้งว่า จงชื่นชมยินดีเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 5, 'จงให้ความอ่อนสุภาพของท่านประจักษ์แก่คนทั้งปวง องค์พระผู้เป็นเจ้าทรงอยู่ใกล้แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 6, 'อย่าทุกข์ร้อนในสิ่งใดๆเลย แต่จงทูลเรื่องความปรารถนาของท่านทุกอย่างต่อพระเจ้า ด้วยการอธิษฐาน การวิงวอน กับการขอบพระคุณ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 7, 'แล้วสันติสุขแห่งพระเจ้า ซึ่งเกินความเข้าใจทุกอย่าง จะคุ้มครองจิตใจและความคิดของท่านไว้ในพระเยซูคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 8, 'พี่น้องทั้งหลาย ในที่สุดนี้ สิ่งใดที่จริง สิ่งใดที่น่านับถือ สิ่งใดที่ยุติธรรม สิ่งใดที่บริสุทธิ์ สิ่งใดที่น่ารัก สิ่งใดที่น่าฟัง คือถ้ามีสิ่งใดที่ล้ําเลิศ สิ่งใดที่ควรแก่การสรรเสริญ ก็ขอจงใคร่ครวญดูสิ่งเหล่านี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 9, 'จงกระทําทุกสิ่งที่ท่านได้เรียนรู้ และได้รับไว้ ได้ยินและได้เห็นในข้าพเจ้าแล้ว และพระเจ้าแห่งสันติสุขจะทรงสถิตกับท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 10, 'แต่ข้าพเจ้ามีใจชื่นชมยินดีในองค์พระผู้เป็นเจ้าอย่างยิ่ง เพราะว่าในที่สุดท่านก็ได้ฟื้นการระลึกถึงข้าพเจ้าอีก ท่านคิดถึงข้าพเจ้าจริงๆ แต่ยังหาโอกาสไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 11, 'ข้าพเจ้าไม่ได้กล่าวถึงเรื่องความขัดสน เพราะข้าพเจ้าจะมีฐานะอย่างไรก็ตาม ข้าพเจ้าก็เรียนรู้แล้วที่จะพอใจอยู่อย่างนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 12, 'ข้าพเจ้ารู้จักที่จะเผชิญกับความตกต่ํา และรู้จักที่จะเผชิญกับความอุดมสมบูรณ์ ไม่ว่าที่ไหนหรือในกรณีใดๆ ข้าพเจ้าได้รับการสั่งสอนให้เผชิญกับความอิ่มท้องและความอดอยาก ทั้งความสมบูรณ์พูนสุขและความขัดสน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 13, 'ข้าพเจ้ากระทําทุกสิ่งได้โดยพระคริสต์ผู้ทรงเสริมกําลังข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 14, 'ถึงกระนั้นท่านทั้งหลายได้กระทําดีอยู่แล้ว ที่ท่านได้ร่วมทุกข์กับข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 15, 'และพวกท่านชาวฟีลิปปีก็ทราบอยู่แล้วว่า การประกาศข่าวประเสริฐในเวลาเริ่มแรกนั้น เมื่อข้าพเจ้าออกไปจากแคว้นมาซิโดเนีย ไม่มีคริสตจักรใดมีส่วนร่วมกับข้าพเจ้าในการให้ทานและรับทานนั้นเลย นอกจากพวกท่านพวกเดียวเท่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 16, 'เพราะเมื่อข้าพเจ้าอยู่ที่เมืองเธสะโลนิกา พวกท่านก็ได้ฝากของมาช่วยหลายครั้งหลายหน สําหรับความขัดสนของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 17, 'มิใช่ว่าข้าพเจ้าปรารถนาจะได้รับของให้ แต่ว่าข้าพเจ้าอยากให้ท่านได้ผลกําไรในบัญชีของท่านมากขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 18, 'แต่ข้าพเจ้ามีของสารพัด และมีบริบูรณ์อยู่แล้ว ข้าพเจ้าก็อิ่มอยู่เพราะได้รับของซึ่งเอปาโฟรดิทัสได้นํามาจากพวกท่าน เป็นกลิ่นหอม เป็นเครื่องบูชาที่ทรงโปรดและพอพระทัยของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 19, 'และพระเจ้าของข้าพเจ้าจะประทานสิ่งสารพัดตามที่ท่านต้องการนั้นจากทรัพย์อันรุ่งเรืองของพระองค์โดยพระเยซูคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 20, 'บัดนี้ขอให้สง่าราศีจงมีแด่พระเจ้าพระบิดาของเราสืบๆไปเป็นนิตย์ เอเมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 21, 'ข้าพเจ้าขอฝากความคิดถึงมายังวิสุทธิชนทุกคนในพระเยซูคริสต์ พี่น้องทั้งหลายที่อยู่กับข้าพเจ้าก็ฝากความคิดถึงมายังท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 22, 'พวกวิสุทธิชนทั้งปวงฝากความคิดถึงมายังท่านทั้งหลาย โดยเฉพาะอย่างยิ่งพวกข้าราชการของซีซาร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 23, 'ขอให้พระคุณแห่งพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเรา ดํารงอยู่กับท่านทั้งหลายเถิด เอเมน [เขียนถึงชาวฟีลิปปีจากกรุงโรม และส่งโดยเอปาโฟรดิทัส]');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 1, 'เปาโล อัครสาวกของพระเยซูคริสต์ตามพระประสงค์ของพระเจ้า และทิโมธีน้องชายของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 2, 'เรียน วิสุทธิชนและพี่น้องที่สัตย์ซื่อในพระคริสต์ ณ เมืองโคโลสี ขอให้พระคุณและสันติสุขจากพระเจ้าพระบิดาของเรา และพระเยซูคริสต์เจ้าดํารงอยู่กับท่านเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 3, 'เราขอบพระคุณพระเจ้าพระบิดาของพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเรา เราอธิษฐานเพื่อท่านทั้งหลายเสมอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 4, 'ตั้งแต่เราได้ยินถึงความเชื่อของท่านในพระเยซูคริสต์และเรื่องความรักซึ่งท่านมีต่อวิสุทธิชนทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 5, 'โดยเหตุซึ่งมีความหวังอันสะสมไว้สําหรับท่านในสวรรค์ซึ่งเมื่อก่อนท่านเคยได้ยินมาแล้วในพระวจนะแห่งความจริงของข่าวประเสริฐ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 6, 'ซึ่งแผ่แพร่มาถึงท่านดังที่กําลังเกิดผลและทวีขึ้นทั่วโลก เช่นเดียวกับที่กําลังเป็นอยู่ในตัวท่านทั้งหลายด้วย ตั้งแต่วันที่ท่านได้ยินและได้รู้จักพระคุณของพระเจ้าตามความจริง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 7, 'ดังที่ท่านได้เรียนจากเอปาฟรัสซึ่งเป็นเพื่อนร่วมงานที่รักของเรา เขาเป็นผู้รับใช้อันสัตย์ซื่อของพระคริสต์เพื่อพวกท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 8, 'ผู้ได้เล่าให้เราฟังถึงความรักที่ท่านมีอยู่ในพระวิญญาณด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 9, 'เพราะเหตุนี้พวกเราเหมือนกัน นับตั้งแต่วันที่เราได้ยิน ก็ไม่ได้หยุดในการที่จะอธิษฐานขอเพื่อท่าน และปรารถนาให้ท่านเต็มไปด้วยความรู้ถึงพระประสงค์ของพระองค์ในสรรพปัญญาและในความเข้าใจฝ่ายจิตวิญญาณ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 10, 'เพื่อท่านจะได้ดําเนินชีวิตอย่างสมควรต่อองค์พระผู้เป็นเจ้า ตามบรรดาความชอบ ให้เกิดผลในการดีทุกอย่าง และจําเริญขึ้นในความรู้ถึงพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 11, 'มีกําลังมากขึ้นทุกอย่างโดยฤทธิ์เดชแห่งสง่าราศีของพระองค์ ให้มีบรรดาความเพียร และความอดทนไว้นานด้วยความยินดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 12, 'ให้ขอบพระคุณพระบิดา ผู้ทรงทําให้เราทั้งหลายสมกับที่จะเข้าส่วนได้รับมรดกด้วยกันกับวิสุทธิชนในความสว่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 13, 'พระองค์ได้ทรงช่วยเราให้พ้นจากอํานาจของความมืด และได้ทรงย้ายเรามาตั้งไว้ในอาณาจักรแห่งพระบุตรที่รักของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 14, 'ในพระบุตรนั้นเราจึงได้รับการไถ่โดยพระโลหิตของพระองค์ คือเป็นการทรงโปรดยกบาปทั้งหลายของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 15, 'พระองค์ทรงเป็นพระฉายของพระเจ้า ผู้ซึ่งไม่ประจักษ์แก่ตา ทรงเป็นบุตรหัวปีเหนือสรรพสิ่งทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 16, 'เพราะว่าโดยพระองค์สรรพสิ่งได้ถูกสร้างขึ้น ทั้งในท้องฟ้าและที่แผ่นดินโลก สิ่งซึ่งประจักษ์แก่ตาและซึ่งไม่ประจักษ์แก่ตา ไม่ว่าจะเป็นเทวบัลลังก์ หรือเป็นเทพอาณาจักร หรือเป็นเทพผู้ครอบครอง หรือศักดิเทพ สรรพสิ่งทั้งสิ้นถูกสร้างขึ้นโดยพระองค์และเพื่อพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 17, 'พระองค์ทรงดํารงอยู่ก่อนสรรพสิ่งทั้งปวง และสรรพสิ่งทั้งปวงเป็นระเบียบอยู่โดยพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 18, 'พระองค์ทรงเป็นศีรษะของกายคือคริสตจักร พระองค์ทรงเป็นที่เริ่มต้น เป็นบุตรหัวปีที่ทรงเป็นขึ้นมาจากความตาย เพื่อพระองค์จะได้ทรงเป็นเอกในสรรพสิ่งทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 19, 'ด้วยว่าเป็นที่ชอบพระทัยพระบิดาที่จะให้ความบริบูรณ์ทั้งสิ้นมีอยู่ในพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 20, 'และโดยพระองค์นั้นให้สิ่งสารพัดกลับคืนดีกับพระองค์เอง โดยพระองค์นั้นข้าพเจ้าพูดได้ว่า ไม่ว่าสิ่งนั้นจะอยู่ในแผ่นดินโลกหรือในท้องฟ้า พระองค์ทรงทําให้มีสันติภาพโดยพระโลหิตแห่งกางเขนของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 21, 'และพวกท่านซึ่งเมื่อก่อนนี้ไม่ถูกกันและเป็นศัตรูในใจด้วยการชั่วต่างๆ บัดนี้ พระองค์ทรงโปรดให้คืนดีกับพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 22, 'โดยความตายแห่งพระกายเนื้อหนังของพระองค์เพื่อจะได้ถวายท่านให้เป็นผู้บริสุทธิ์ ไร้ตําหนิและไร้ข้อกล่าวหาในสายพระเนตรของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 23, 'คือถ้าท่านดํารงและตั้งมั่นอยู่ในความเชื่อ และไม่โยกย้ายไปจากความหวังในข่าวประเสริฐซึ่งท่านได้ยินแล้ว และที่ได้ประกาศแล้วแก่มนุษย์ทุกคนที่อยู่ใต้ฟ้า ซึ่งข้าพเจ้าเปาโลเป็นผู้รับใช้ในการนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 24, 'บัดนี้ข้าพเจ้ามีความยินดีในการที่ได้รับความทุกข์ยากเพื่อท่าน ส่วนการทนทุกข์ของพระคริสต์ที่ยังขาดอยู่นั้น ข้าพเจ้าก็รับทนจนสําเร็จในเนื้อหนังของข้าพเจ้าเพราะเห็นแก่พระกายของพระองค์คือคริสตจักร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 25, 'ข้าพเจ้าได้ถูกตั้งให้เป็นผู้รับใช้ตามที่พระเจ้าได้ทรงโปรดมอบภาระให้ข้าพเจ้าเพื่อท่าน เพื่อจะให้พระวจนะของพระเจ้าสําเร็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 26, 'คือข้อความลึกลับซึ่งซ่อนเร้นอยู่หลายยุคและหลายชั่วอายุนั้น แต่บัดนี้ได้ทรงโปรดให้เป็นที่ประจักษ์แก่วิสุทธิชนของพระองค์แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 27, 'พระเจ้าทรงชอบพระทัยที่จะสําแดงให้คนต่างชาติรู้ว่า อะไรเป็นความมั่งคั่งของสง่าราศีแห่งข้อลึกลับนี้คือที่พระคริสต์ทรงสถิตในท่านอันเป็นที่หวังแห่งสง่าราศี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 28, 'พระองค์นั้นแหละเราประกาศอยู่ โดยเตือนสติทุกคนและสั่งสอนทุกคนโดยใช้สติปัญญาทุกอย่าง เพื่อเราจะได้ถวายทุกคนให้เป็นผู้ใหญ่แล้วในพระเยซูคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 29, 'เพราะเหตุนั้นข้าพเจ้าจึงกระทําการงานด้วย โดยความอุตสาหะตามการกระทําของพระองค์ผู้ทรงออกฤทธิ์กระทําอยู่ในตัวข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 1, 'เพราะข้าพเจ้าใคร่ให้ท่านรู้ว่า ข้าพเจ้าสู้อุตส่าห์มากเพียงไรเพื่อท่าน เพื่อชาวเมืองเลาดีเซียและเพื่อคนทั้งปวงที่ยังไม่เห็นหน้าของข้าพเจ้าในฝ่ายเนื้อหนัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 2, 'เพื่อเขาจะได้รับความชูใจ และเข้าติดสนิทกันในความรัก และมั่นใจในความอุดมสมบูรณ์แห่งความเข้าใจ และเข้าในความรู้ความลึกลับของพระเจ้าและของพระบิดาและของพระคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 3, 'ซึ่งคลังสติปัญญาและความรู้ทุกอย่างทรงปิดซ่อนไว้ในพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 4, 'ข้าพเจ้ากล่าวเช่นนี้เพื่อมิให้ผู้ใดล่อลวงท่านด้วยคําชักชวนอันน่าฟัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 5, 'เพราะถึงแม้ว่าตัวของข้าพเจ้าไม่อยู่กับท่าน แต่ใจของข้าพเจ้ายังอยู่กับท่าน และมีความชื่นชมยินดีที่ได้เห็นท่านอยู่กันอย่างเรียบร้อย และเห็นความเชื่อมั่นคงของท่านในพระคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 6, 'เหตุฉะนั้นตามที่ท่านได้ต้อนรับเอาพระเยซูคริสต์เจ้ามาแล้วอย่างไร ก็ให้ดําเนินชีวิตในพระองค์อย่างนั้นต่อไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 7, 'โดยท่านได้ถูกวางรากลงไว้แล้ว และถูกก่อร่างสร้างขึ้นในพระองค์ให้สมบูรณ์ และถูกตั้งให้มั่นคงอยู่ในความเชื่อตามที่ท่านได้รับการสอนมาแล้วนั้น จึงเต็มล้นด้วยการขอบพระคุณอยู่ในนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 8, 'จงระวังให้ดี เกรงว่าจะมีผู้ใดทําให้ท่านตกเป็นเหยื่อด้วยหลักปรัชญาและด้วยคําล่อลวงอันไม่มีสาระ ตามธรรมเนียมของมนุษย์ ตามหลักการต่างๆที่เป็นของโลก ไม่ใช่ตามพระคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 9, 'เพราะว่าในพระองค์นั้นสภาพของพระเจ้าดํารงอยู่อย่างบริบูรณ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 10, 'และท่านได้ความครบบริบูรณ์ในพระองค์ ผู้เป็นศีรษะแห่งปวงเทพผู้ครอบครองและศักดิเทพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 11, 'ในพระองค์นั้น ท่านได้รับเข้าสุหนัต ซึ่งเป็นการเข้าสุหนัตที่มือมนุษย์มิได้กระทํา โดยที่ท่านได้สละกายแห่งความบาปของเนื้อหนังเสีย โดยการเข้าสุหนัตแห่งพระคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 12, 'ได้ถูกฝังไว้กับพระองค์ในบัพติศมา ซึ่งท่านได้เป็นขึ้นมากับพระองค์ด้วย โดยความเชื่อในการกระทําของพระเจ้า ผู้ได้ทรงบันดาลให้พระองค์เป็นขึ้นมาจากความตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 13, 'และท่านที่ตายแล้วด้วยความบาปทั้งหลายของท่านและด้วยเหตุที่เนื้อหนังของท่านมิได้เข้าสุหนัต พระองค์ได้ทรงให้ท่านมีชีวิตด้วยกันกับพระองค์และทรงโปรดยกโทษการละเมิดทั้งหลายของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 14, 'พระองค์ทรงลบกรมธรรม์ในข้อบัญญัติต่างๆที่ต่อต้านเราอยู่ ซึ่งขัดขวางเราและได้ทรงหยิบเอาไปเสียให้พ้น โดยทรงตรึงไว้ที่กางเขนของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 15, 'พระองค์ทรงปลดเทพผู้ครอบครองและศักดิเทพเสีย พระองค์ได้ทรงประจานเขาและชนะเขาโดยกางเขนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 16, 'เหตุฉะนั้นอย่าให้ผู้ใดพิพากษาปรักปรําท่านในเรื่องการกินการดื่ม ในเรื่องการถือเทศกาล วันขึ้นหนึ่งค่ํา หรือวันสะบาโต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 17, 'สิ่งเหล่านี้เป็นเพียงเงาของเหตุการณ์ที่จะมีมาในภายหลัง แต่กายนั้นเป็นของพระคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 18, 'อย่าให้ผู้ใดโกงบําเหน็จของท่านด้วยการจงใจถ่อมตัวลงและกราบไหว้ทูตสวรรค์ ใฝ่ฝันในสิ่งเหล่านั้นที่เขาไม่ได้เห็น ผยองขึ้นเปล่าๆตามความคิดของเนื้อหนัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 19, 'และไม่ได้ยึดมั่นในพระองค์ผู้ทรงเป็นศีรษะ ศีรษะนั้นเป็นเหตุให้กายทั้งหมดได้รับการบํารุงเลี้ยงและติดต่อกันด้วยข้อและเอ็นต่างๆ จึงได้เจริญขึ้นตามที่พระเจ้าทรงโปรดให้เจริญขึ้นนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 20, 'ดังนั้นถ้าท่านตายกับพระคริสต์พ้นจากหลักการต่างๆที่เป็นของโลกแล้ว เหตุไฉนท่านจึงมีชีวิตอยู่เหมือนกับว่าท่านยังอยู่ฝ่ายโลก ยอมอยู่ใต้กฎต่างๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 21, '(เช่น “อย่าแตะต้อง” “อย่าชิม” “อย่าเอามือหยิบ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 22, 'ซึ่งทั้งหมดจะพินาศเมื่อทําดังนั้น) อันเป็นหลักธรรมและคําสอนของมนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 23, 'จริงอยู่สิ่งเหล่านี้ดูท่าทีมีปัญญา คือการเต็มใจนมัสการ การถ่อมตัวลง และการทรมานกาย แต่ไม่มีประโยชน์อะไรในการต่อสู้กับความต้องการของเนื้อหนัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 1, 'ถ้าท่านรับการทรงชุบให้เป็นขึ้นมาด้วยกันกับพระคริสต์แล้ว ก็จงแสวงหาสิ่งซึ่งอยู่เบื้องบนในที่ซึ่งพระคริสต์ทรงประทับข้างขวาพระหัตถ์ของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 2, 'จงฝังความคิดของท่านไว้กับสิ่งทั้งหลายที่อยู่เบื้องบน ไม่ใช่กับสิ่งทั้งหลายซึ่งอยู่ที่แผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 3, 'เพราะว่าท่านได้ตายแล้วและชีวิตของท่านซ่อนไว้กับพระคริสต์ในพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 4, 'เมื่อพระคริสต์ผู้ทรงเป็นชีวิตของเราจะทรงปรากฏ ขณะนั้นท่านก็จะปรากฏพร้อมกับพระองค์ในสง่าราศีด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 5, 'เหตุฉะนั้นจงประหารอวัยวะของท่านซึ่งอยู่ฝ่ายโลกนี้ คือการล่วงประเวณี การโสโครก ราคะตัณหา ความปรารถนาชั่ว และความโลภ ซึ่งเป็นการนับถือรูปเคารพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 6, 'เพราะสิ่งเหล่านี้ พระอาชญาของพระเจ้าก็ลงมาแก่บุตรแห่งการไม่เชื่อฟัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 7, 'ครั้งหนึ่งท่านเคยดําเนินตามสิ่งเหล่านี้ด้วย ครั้งเมื่อท่านยังดํารงชีวิตอยู่กับสิ่งเหล่านี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 8, 'แต่บัดนี้สารพัดสิ่งเหล่านี้ท่านจงเปลื้องทิ้งเสียด้วย คือความโกรธ ความขัดเคือง การคิดปองร้าย การหมิ่นประมาท คําพูดหยาบโลนจากปากของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 9, 'อย่าพูดมุสาต่อกันเพราะว่าท่านได้ถอดทิ้งมนุษย์เก่ากับการปฏิบัติของมนุษย์นั้นเสียแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 10, 'และได้สวมมนุษย์ใหม่ที่กําลังทรงสร้างขึ้นใหม่ในความรู้ตามแบบพระฉายของพระองค์ผู้ได้ทรงสร้างขึ้นนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 11, 'อย่างนี้ไม่เป็นพวกกรีกหรือพวกยิว ไม่เป็นผู้ที่เข้าสุหนัตหรือไม่ได้เข้าสุหนัต พวกคนต่างชาติหรือชาวสิเธีย ทาสหรือไทยก็ไม่เป็น แต่ว่าพระคริสต์ทรงเป็นสารพัดและทรงดํารงอยู่ในสารพัด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 12, 'เหตุฉะนั้นในฐานะที่เป็นพวกซึ่งพระเจ้าทรงเลือกไว้ เป็นพวกที่บริสุทธิ์และเป็นพวกที่ทรงรัก จงสวมใจเมตตา ใจปรานี ใจถ่อม ใจอ่อนสุภาพ ใจอดทนไว้นาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 13, 'จงผ่อนหนักผ่อนเบาซึ่งกันและกัน และถ้าแม้ว่าผู้ใดมีเรื่องราวต่อกันก็จงยกโทษให้กันและกัน พระคริสต์ได้ทรงโปรดยกโทษให้ท่านฉันใด ท่านจงกระทําอย่างนั้นเหมือนกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 14, 'แล้วจงสวมความรักทับสิ่งเหล่านี้ทั้งหมด เพราะความรักย่อมผูกพันทุกสิ่งไว้ให้ถึงซึ่งความสมบูรณ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 15, 'และจงให้สันติสุขแห่งพระเจ้าครอบครองอยู่ในใจของท่านทั้งหลาย ในสันติสุขนั้นทรงเรียกท่านทั้งหลายไว้ให้เป็นกายอันเดียวด้วย และท่านทั้งหลายจงขอบพระคุณ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 16, 'จงให้พระวาทะของพระคริสต์ดํารงอยู่ในตัวท่านอย่างบริบูรณ์ด้วยปัญญาทั้งสิ้น จงสั่งสอนและเตือนสติกันด้วยเพลงสดุดี เพลงสรรเสริญและเพลงฝ่ายจิตวิญญาณด้วย จงร้องเพลงด้วยพระคุณจากใจของท่านถวายองค์พระผู้เป็นเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 17, 'และเมื่อท่านจะกระทําสิ่งใดด้วยวาจาหรือด้วยการประพฤติก็ตาม จงกระทําทุกสิ่งในพระนามของพระเยซูเจ้าและขอบพระคุณพระเจ้าพระบิดาโดยพระองค์นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 18, 'ฝ่ายภรรยาจงยอมฟังสามีของตน ซึ่งเป็นการสมควรในองค์พระผู้เป็นเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 19, 'ฝ่ายสามีก็จงรักภรรยาของตนและอย่ามีใจขมขื่นต่อนาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 20, 'ฝ่ายบุตรทั้งหลายจงเชื่อฟังบิดามารดาของตนทุกอย่าง เพราะการนี้เป็นที่ชอบพระทัยขององค์พระผู้เป็นเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 21, 'ฝ่ายบิดาก็อย่ายั่วบุตรของตนให้ขัดเคืองใจ เกรงว่าเขาจะท้อใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 22, 'ฝ่ายพวกทาสจงเชื่อฟังผู้ที่เป็นนายของตนตามเนื้อหนังทุกอย่าง ไม่ใช่ตามอย่างคนที่ทําแต่ต่อหน้า อย่างคนประจบสอพลอ แต่ทําด้วยน้ําใสใจจริงด้วยความเกรงกลัวพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 23, 'ไม่ว่าท่านจะทําสิ่งใดก็จงทําด้วยความเต็มใจ เหมือนกระทําถวายองค์พระผู้เป็นเจ้า ไม่ใช่เหมือนกระทําแก่มนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 24, 'ด้วยรู้แล้วว่าท่านจะได้รับมรดกจากองค์พระผู้เป็นเจ้าเป็นบําเหน็จเพราะท่านปรนนิบัติพระคริสต์เจ้าอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 25, 'ส่วนผู้ที่ทําความผิดก็จะได้รับผลตามความผิดที่เขาได้ทํานั้นและไม่มีการทรงเห็นแก่หน้าผู้ใดเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 1, 'ฝ่ายนายก็จงทําแก่เหล่าทาสของตนตามความยุติธรรมและสม่ําเสมอกัน เพราะท่านรู้ว่าท่านก็มีนายองค์หนึ่งในสวรรค์ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 2, 'จงขะมักเขม้นในการอธิษฐาน จงเฝ้าระวังอยู่ในการนั้นด้วยขอบพระคุณ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 3, 'และอธิษฐานเผื่อเราด้วย เพื่อพระเจ้าจะได้ทรงโปรดเปิดประตูไว้ให้เราสําหรับพระวาทะนั้น ให้เรากล่าวความลึกลับของพระคริสต์ ที่ข้าพเจ้าถูกจองจําอยู่ก็เพราะเหตุนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 4, 'เพื่อข้าพเจ้าจะได้กล่าวชี้แจงข้อความตามสมควรที่ข้าพเจ้าควรจะกล่าวนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 5, 'จงดําเนินชีวิตกับคนภายนอกด้วยใช้สติปัญญา จงฉวยโอกาส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 6, 'จงให้วาจาของท่านประกอบด้วยเมตตาคุณเสมอ ปรุงด้วยเกลือให้มีรส เพื่อท่านจะได้รู้ว่าควรตอบทุกคนอย่างไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 7, 'ทีคิกัส ผู้เป็นน้องชายที่รัก และเป็นผู้รับใช้ที่สัตย์ซื่อ และเป็นเพื่อนร่วมงานกับข้าพเจ้าในองค์พระผู้เป็นเจ้า จะบอกให้ท่านทราบถึงเหตุการณ์ทั้งปวงของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 8, 'ข้าพเจ้าใช้ผู้นี้ไปหาท่านก็เพราะเหตุนี้เอง คือให้เขาทราบถึงความเป็นอยู่ของท่าน และเพื่อให้เขาหนุนน้ําใจของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 9, 'ให้โอเนสิมัส ผู้เป็นน้องชายที่รักและสัตย์ซื่อ ซึ่งเป็นคนหนึ่งในพวกท่านไปด้วย เขาทั้งสองจะเล่าให้ท่านทราบถึงเหตุการณ์ทั้งปวงที่นี่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 10, 'อาริสทารคัส เพื่อนร่วมในการถูกจองจํากับข้าพเจ้าและมาระโก ลูกชายของน้องสาวบารนาบัส ฝากความคิดถึงมายังท่านทั้งหลาย (ท่านก็ได้รับคําสั่งถึงเรื่องมาระโกแล้วว่า ถ้าเขามาหาท่าน ก็จงรับรองเขา)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 11, 'และเยซูซึ่งมีชื่ออีกว่า ยุสทัส ก็เช่นกัน ซึ่งอยู่ในคณะที่เข้าสุหนัต จําเพาะคนเหล่านี้เท่านั้นเป็นเพื่อนร่วมการกับข้าพเจ้าในอาณาจักรของพระเจ้า ซึ่งเป็นที่หนุนใจของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 12, 'เอปาฟรัส คนหนึ่งในพวกท่านและเป็นผู้รับใช้ของพระคริสต์ ฝากความคิดถึงมายังท่าน ด้วยเขาสู้อธิษฐานเผื่อท่านอยู่เสมอ หวังจะให้ท่านเจริญเป็นผู้ใหญ่และบริบูรณ์ในการซึ่งชอบพระทัยของพระเจ้าทุกสิ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 13, 'ข้าพเจ้าเป็นพยานให้เขาว่า เขาตรากตรําทํางานมากเพื่อท่านและเพื่อคนที่อยู่ในเมืองเลาดีเซียและเพื่อคนที่อยู่ในเมืองฮิเอราบุรี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 14, 'ลูกาแพทย์ที่รักกับเดมาสฝากความคิดถึงมายังพวกท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 15, 'ขอฝากความคิดถึงมายังพวกพี่น้องที่อยู่ในเมืองเลาดีเซียกับนิมฟัสและคริสตจักรที่อยู่ในเรือนของเขาด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 16, 'และเมื่อพวกท่านได้อ่านจดหมายฉบับนี้แล้ว จงส่งไปให้อ่านในคริสตจักรที่อยู่เมืองเลาดีเซียด้วย และจดหมายที่มาจากเมืองเลาดีเซียฉบับนั้น ท่านก็จงอ่านด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 17, 'และจงบอกอารคิปปัสว่า “การรับใช้ซึ่งท่านได้รับในองค์พระผู้เป็นเจ้านั้น จงระวังกระทําให้สําเร็จ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 18, 'คําแสดงความคิดถึงนี้เป็นลายมือของข้าพเจ้า เปาโล ขอท่านจงระลึกถึงโซ่ตรวนของข้าพเจ้า ขอให้พระคุณดํารงอยู่กับท่านด้วยเถิด เอเมน [เขียนจากกรุงโรมถึงชาวโคโลสี และส่งโดยทีคิกัสและโอเนสิมัส]');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 1, 'เปาโล สิลวานัส และทิโมธี เรียน คริสตจักรของชาวเมืองเธสะโลนิกา ในพระเจ้าพระบิดาและพระเยซูคริสต์เจ้า ขอให้พระคุณและสันติสุขจากพระเจ้าพระบิดาของเราและจากพระเยซูคริสต์เจ้า ดํารงอยู่กับท่านทั้งหลายเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 2, 'เราขอบพระคุณพระเจ้าเพราะท่านทั้งหลายเสมอ และเมื่ออธิษฐานเราก็เอ่ยถึงท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 3, 'ในสายพระเนตรของพระเจ้าและพระบิดาของเรา เราระลึกถึงอย่างไม่หยุดหย่อนในกิจการที่เกิดจากความเชื่อของท่าน และการงานที่เนื่องมาจากความรัก และความพากเพียรซึ่งเกิดจากความหวังในพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 4, 'พี่น้องทั้งหลาย ผู้เป็นที่รัก เราทราบแน่ว่าพระเจ้าได้ทรงสรรท่านทั้งหลายไว้แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 5, 'เพราะข่าวประเสริฐของเรามิได้มาถึงท่านด้วยถ้อยคําเท่านั้น แต่ด้วยฤทธิ์เดช และด้วยพระวิญญาณบริสุทธิ์ และด้วยความไว้ใจอันเต็มเปี่ยม ตามที่ท่านทั้งหลายรู้อยู่แล้วว่า เราเป็นคนอย่างไรในหมู่พวกท่านเพราะเห็นแก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 6, 'และท่านก็ทําตามอย่างของเรา และขององค์พระผู้เป็นเจ้า โดยที่ท่านได้รับถ้อยคํานั้นด้วยความยากลําบากเป็นอันมาก พร้อมด้วยความยินดีในพระวิญญาณบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 7, 'เพราะเหตุนั้นท่านจึงเป็นแบบอย่างแก่ทุกคนที่เชื่อแล้วในแคว้นมาซิโดเนียและแคว้นอาคายา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 8, 'เพราะว่าพระวจนะขององค์พระผู้เป็นเจ้าได้เลื่องลือออกไปจากพวกท่าน ไม่ใช่แต่ในแคว้นมาซิโดเนียและแคว้นอาคายาเท่านั้น แต่ความเชื่อของท่านในพระเจ้าได้เลื่องลือไปทุกแห่งหน จนเราไม่จําเป็นต้องพูดอะไรอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 9, 'เพราะคนเหล่านั้นก็ได้รายงานเกี่ยวกับเราว่า ที่เราได้เข้ามาหาท่านทั้งหลายนั้นเป็นอย่างไร และกล่าวถึงการที่ท่านได้ละทิ้งรูปเคารพและหันมาหาพระเจ้า เพื่อรับใช้พระเจ้าผู้ทรงพระชนม์อยู่และเที่ยงแท้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 10, 'และรอคอยพระบุตรของพระองค์จากสวรรค์ ซึ่งพระองค์ทรงให้เป็นขึ้นมาจากความตาย คือพระเยซูผู้ทรงช่วยให้เราพ้นจากพระอาชญาที่จะมีมาภายหน้านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 1, 'พี่น้องทั้งหลาย ท่านเองก็ทราบว่า การที่เรามาหาท่านนั้นไม่ได้ไร้ประโยชน์เลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 2, 'แต่ถึงแม้ว่าเราต้องทนการยากลําบากและได้รับการอัปยศต่างๆมาแล้วที่เมืองฟีลิปปี ซึ่งท่านก็ทราบอยู่ เราก็ยังมีใจกล้าในพระเจ้าของเราที่ได้ประกาศข่าวประเสริฐของพระเจ้าแก่ท่านทั้งหลาย โดยเผชิญกับอุปสรรคมากมาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 3, 'เพราะว่า คําเตือนสติของเรามิได้เกิดมาจากการหลอกลวง หรือการโสโครก หรืออุบายใดๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 4, 'แต่ว่าพระเจ้าทรงเห็นชอบที่จะมอบข่าวประเสริฐไว้กับเรา เราจึงประกาศไป ไม่ใช่เพื่อให้เป็นที่พอใจของมนุษย์ แต่ให้เป็นที่พอพระทัยของพระเจ้า ผู้ทรงชันสูตรใจเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 5, 'เพราะว่าเราไม่ได้ใช้คํายกยอในเวลาใดเลย ซึ่งท่านก็รู้อยู่ หรือมิได้ใช้คําพูดเคลือบคลุมเพื่อความโลภเลย พระเจ้าทรงเป็นพยานฝ่ายเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 6, 'และแม้ในฐานะเป็นอัครสาวกของพระคริสต์ เราจะเรียกร้องให้เป็นภาระก็ได้ แต่เราก็ไม่แสวงหาสง่าราศีจากมนุษย์ ไม่ว่าจะเป็นจากท่านหรือจากคนอื่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 7, 'แต่ว่าเราอยู่ในหมู่พวกท่านด้วยความสุภาพอ่อนโยน เหมือนพี่เลี้ยงที่เลี้ยงดูลูกของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 8, 'เมื่อเรารักท่านอย่างนี้แล้ว เราก็มีใจพร้อมที่จะเผื่อแผ่เจือจาน มิใช่แต่เพียงข่าวประเสริฐของพระเจ้าเท่านั้น แต่อุทิศจิตใจเราให้แก่ท่านด้วย เพราะท่านเป็นที่รักยิ่งของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 9, 'พี่น้องทั้งหลาย ท่านคงจําได้ถึงการทํางานอันเหน็ดเหนื่อย และความยากลําบากของเราเมื่อเราประกาศข่าวประเสริฐของพระเจ้าให้แก่ท่าน เราทํางานทั้งกลางคืนและกลางวัน เพื่อเราจะไม่เป็นภาระแก่ผู้ใดในพวกท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 10, 'ท่านทั้งหลายเป็นพยานฝ่ายเรา และพระเจ้าก็ทรงเป็นพยานด้วยว่าเราได้ประพฤติตัวบริสุทธิ์ เที่ยงธรรม และปราศจากข้อตําหนิในหมู่พวกท่านที่เชื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 11, 'ดังที่ท่านรู้แล้วว่า เราได้เตือนสติ หนุนใจและกําชับท่านทุกคน ดังบิดากระทําต่อบุตร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 12, 'เพื่อให้ท่านดําเนินชีวิตอย่างสมควรต่อพระเจ้า ผู้ทรงเรียกท่านให้เข้ามาในอาณาจักรและสง่าราศีของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 13, 'เพราะเหตุนี้เราจึงขอบพระคุณพระเจ้าไม่หยุดหย่อน เพราะว่าเมื่อท่านทั้งหลายได้รับพระวจนะของพระเจ้าซึ่งท่านได้ยินจากเรา ท่านไม่ได้รับไว้อย่างเป็นคําของมนุษย์ แต่ได้รับไว้ตามความเป็นจริง คือเป็นพระวจนะของพระเจ้า ซึ่งกําลังทํางานอยู่ภายในท่านทั้งหลายที่เชื่อด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 14, 'ด้วยว่า พี่น้องทั้งหลาย ท่านได้ปฏิบัติตามอย่างคริสตจักรของพระเจ้าในแคว้นยูเดียที่อยู่ฝ่ายพระเยซูคริสต์ เพราะว่าท่านได้รับความลําบากจากพลเมืองของตนเหมือนอย่างที่เขาเหล่านั้นได้รับจากพวกยิว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 15, 'พวกยิวได้ปลงพระชนม์พระเยซูเจ้า และได้ประหารชีวิตพวกศาสดาพยากรณ์ของเขาเอง และได้ข่มเหงพวกเรา และขัดพระทัยพระเจ้า และเป็นปฏิปักษ์ต่อคนทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 16, 'โดยที่ขัดขวางไม่ให้เราประกาศแก่คนต่างชาติเพื่อจะให้พวกนั้นรอดได้ เพื่อ ‘ให้การบาปของเขาเต็มเปี่ยมเสมอ’ แต่ในที่สุดพระพิโรธได้ตกลงบนเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 17, 'พี่น้องทั้งหลาย แต่เมื่อเราถูกพรากไปจากท่านชั่วระยะเวลาหนึ่ง พรากไปแต่กายเท่านั้น ไม่ใช่จิตใจ เราจึงขวนขวายปรารถนาอย่างยิ่งที่จะเห็นหน้าท่านอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 18, 'เพราะเหตุนั้นเราอยากมาหาท่านทั้งหลาย ข้าพเจ้าคือเปาโลอยากมาหนแล้วหนเล่า แต่ซาตานได้ขัดขวางเราไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 19, 'เพราะอะไรเล่าจะเป็นความหวัง หรือความยินดี หรือมงกุฎแห่งความชื่นชมยินดีของเรา จําเพาะพระพักตร์พระเยซูคริสต์องค์พระผู้เป็นเจ้าของเรา เมื่อพระองค์จะเสด็จมา ก็มิใช่ท่านทั้งหลายดอกหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 20, 'เพราะว่าท่านทั้งหลายเป็นสง่าราศีและความยินดีของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 1, 'เหตุฉะนั้นเมื่อเราทนอยู่ต่อไปอีกไม่ได้แล้ว เราจึงเห็นชอบที่จะถูกปล่อยไว้ที่กรุงเอเธนส์ตามลําพัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 2, 'และได้ให้ทิโมธีน้องชายของเรา ซึ่งเป็นผู้รับใช้ของพระเจ้า และเป็นเพื่อนร่วมงานของเราในเรื่องข่าวประเสริฐของพระคริสต์ไปหาพวกท่าน เพื่อจะได้ตั้งพวกท่านไว้ให้มั่นคง และเพื่อจะได้ปลอบประโลมใจพวกท่านในเรื่องความเชื่อของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 3, 'เพื่อจะได้ไม่มีใครหวั่นไหวด้วยการยากลําบากเหล่านี้ ท่านเองก็รู้แล้วว่า เราทรงถูกกําหนดไว้แล้วสําหรับการนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 4, 'ด้วยว่าเมื่อเราได้อยู่กับท่านทั้งหลาย เราได้บอกท่านไว้ก่อนแล้วว่า เราจะต้องทนการยากลําบาก แล้วก็เป็นจริงอย่างนั้น ตามที่ท่านก็รู้อยู่แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 5, 'เพราะเหตุนี้ เมื่อข้าพเจ้าอดทนต่อไปอีกไม่ได้ ข้าพเจ้าจึงได้ใช้คนไปเพื่อจะได้รู้ถึงความเชื่อของท่าน เกรงว่าผู้ทดลองนั้นได้ทดลองท่านด้วยประการหนึ่งประการใด แล้วงานของเราก็จะเป็นการเสียเปล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 6, 'แต่บัดนี้เมื่อทิโมธีได้จากพวกท่านมาถึงพวกเราแล้ว และได้นําข่าวดีมาบอกเราเรื่องความเชื่อและความรักของท่านทั้งหลาย และว่าท่านได้ระลึกถึงเราอยู่เสมอด้วยความหวังดี และใฝ่ฝันจะเห็นเราเหมือนอย่างเราใฝ่ฝันจะเห็นท่านดุจกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 7, 'พี่น้องทั้งหลาย โดยเหตุนี้ความเชื่อของท่านได้ทําให้เราบรรเทาจากความทุกข์ยากและความลําบากของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 8, 'เพราะว่าถ้าท่านมั่นคงอยู่ในองค์พระผู้เป็นเจ้า ชีวิตของเราก็สดชื่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 9, 'เราจะขอบพระคุณพระเจ้าเพราะท่านอย่างไรอีกจึงจะเหมาะ สําหรับบรรดาความชื่นชมยินดีซึ่งเรามีอยู่เพราะท่าน จําเพาะพระพักตร์พระเจ้าของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 10, 'เราอธิษฐานมากมายทั้งกลางคืนและกลางวัน เพื่อจะได้เห็นหน้าท่านอีก และจะได้เพิ่มเติมความเชื่อของท่านส่วนที่ยังบกพร่องอยู่ให้บริบูรณ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 11, 'บัดนี้ขอพระเจ้าเองและพระบิดาของเรา และพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเรา ทรงนําทางเราไปถึงท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 12, 'และขอองค์พระผู้เป็นเจ้าทรงให้ท่านทั้งหลายจําเริญและบริบูรณ์ไปด้วยความรักซึ่งกันและกัน และแก่คนทั้งปวง เหมือนเรารักท่านทั้งหลายดุจกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 13, 'เพื่อในที่สุดพระองค์จะทรงให้ใจของท่านตั้งมั่นคงอยู่ในความบริสุทธิ์ ปราศจากข้อตําหนิต่อพระพักตร์พระเจ้าคือพระบิดาของเรา ในเมื่อพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเราจะเสด็จมากับวิสุทธิชนทั้งปวงของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 1, 'พี่น้องทั้งหลาย ในที่สุดนี้ เราขอวิงวอนและเตือนสติท่านในพระเยซูเจ้าว่า ท่านได้เรียนจากเราแล้วว่าควรจะดําเนินชีวิตอย่างไร จึงจะเป็นที่ชอบพระทัยพระเจ้า ขอให้ท่านดําเนินตามอย่างนั้นยิ่งๆขึ้นไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 2, 'เพราะท่านทั้งหลายทราบคําบัญชาซึ่งเราได้ให้ไว้กับท่านโดยพระเยซูเจ้าแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 3, 'เพราะนี่แหละเป็นพระประสงค์ของพระเจ้า คือให้ท่านเป็นคนบริสุทธิ์ เว้นเสียจากการล่วงประเวณี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 4, 'เพื่อให้ทุกคนในพวกท่านรู้จักที่จะรักษาภาชนะของตนในทางบริสุทธิ์ และในทางที่มีเกียรติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 5, 'มิใช่ด้วยราคะตัณหาเหมือนอย่างคนต่างชาติที่ไม่รู้จักพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 6, 'เพื่อไม่ให้ผู้ใดทําล่วงเกินและลักลอบต่อพี่น้องในเรื่องใดๆเลย เพราะว่าองค์พระผู้เป็นเจ้าทรงเป็นผู้ทรงสนองโทษต่อบรรดาคนที่กระทําอย่างนั้น เหมือนอย่างที่เราได้บอกไว้ก่อนแล้วและได้เป็นพยานแล้วด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 7, 'เพราะพระเจ้ามิได้ทรงเรียกเราให้เป็นคนลามก แต่ทรงเรียกเราให้เป็นคนบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 8, 'เหตุฉะนั้นคนที่ปัดทิ้ง มิได้ปัดทิ้งมนุษย์ แต่ได้ปัดทิ้งพระเจ้า ผู้ทรงโปรดประทานพระวิญญาณบริสุทธิ์ของพระองค์ให้แก่เราทั้งหลายด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 9, 'ส่วนเรื่องการรักพี่น้องทั้งหลายนั้น ไม่จําเป็นที่จะให้ข้าพเจ้าเขียนถึงท่าน เพราะว่าตัวท่านเองก็รับคําสอนจากพระเจ้าแล้วว่าให้รักซึ่งกันและกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 10, 'ความจริงท่านได้ประพฤติต่อบรรดาพี่น้องทั่วแคว้นมาซิโดเนียเช่นนั้นอยู่ แต่พี่น้องทั้งหลาย เราขอวิงวอนท่านให้มีความรักทวีขึ้นอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 11, 'และจงตั้งเป้าว่าจะอยู่อย่างสงบ และทํากิจธุระส่วนของตน และทําการงานด้วยมือของตนเอง เหมือนอย่างที่เรากําชับท่านแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 12, 'เพื่อท่านจะได้ดําเนินชีวิตตามอย่างที่สมควรต่อหน้าคนเหล่านั้นที่อยู่ภายนอก และเพื่อท่านจะไม่ขาดสิ่งใดเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 13, 'แต่พี่น้องทั้งหลาย ข้าพเจ้าไม่อยากให้ท่านไม่ทราบถึงเรื่องคนเหล่านั้นที่ล่วงหลับไปแล้ว เพื่อท่านจะไม่เป็นทุกข์โศกเศร้าอย่างคนอื่นๆที่ไม่มีความหวัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 14, 'เพราะถ้าเราเชื่อว่าพระเยซูทรงสิ้นพระชนม์ และทรงคืนพระชนม์แล้ว เช่นเดียวกันบรรดาคนที่ล่วงหลับไปในพระเยซูนั้น พระเจ้าจะทรงนําคนเหล่านั้นมากับพระองค์ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 15, 'ในข้อนี้เราขอบอกให้ท่านทราบตามพระวจนะขององค์พระผู้เป็นเจ้าว่า เราผู้ยังเป็นอยู่และเหลืออยู่จนถึงองค์พระผู้เป็นเจ้าเสด็จมา จะล่วงหน้าไปก่อนคนเหล่านั้นที่ล่วงหลับไปแล้วก็หามิได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 16, 'ด้วยว่าองค์พระผู้เป็นเจ้าเองจะเสด็จมาจากสวรรค์ ด้วยเสียงกู่ก้อง ด้วยสําเนียงของเทพบดี และด้วยเสียงแตรของพระเจ้า และคนทั้งปวงที่ตายแล้วในพระคริสต์จะเป็นขึ้นมาก่อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 17, 'หลังจากนั้นเราทั้งหลายซึ่งยังเป็นอยู่และเหลืออยู่ จะถูกรับขึ้นไปในเมฆพร้อมกับคนเหล่านั้น เพื่อจะได้พบองค์พระผู้เป็นเจ้าในฟ้าอากาศ อย่างนั้นแหละเราก็จะอยู่กับองค์พระผู้เป็นเจ้าเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 18, 'เหตุฉะนั้นจงปลอบใจกันและกันด้วยถ้อยคําเหล่านี้เถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 1, 'แต่พี่น้องทั้งหลาย เรื่องวันและเวลาที่ทรงกําหนดไว้นั้น ไม่จําเป็นจะต้องเขียนบอกให้ท่านรู้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 2, 'เพราะท่านเองก็รู้ดีแล้วว่า วันขององค์พระผู้เป็นเจ้าจะมาเหมือนอย่างขโมยที่มาในเวลากลางคืน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 3, 'เมื่อเขาพูดว่า “สงบสุขและปลอดภัยแล้ว” เมื่อนั้นแหละความพินาศก็จะมาถึงเขาทันที เหมือนกับความเจ็บปวดมาถึงหญิงที่มีครรภ์ เขาจะหนีก็ไม่พ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 4, 'แต่พี่น้องทั้งหลาย ท่านไม่ได้อยู่ในความมืดแล้ว เพื่อวันนั้นจะไม่มาถึงท่านอย่างขโมยมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 5, 'ท่านทั้งหลายเป็นบุตรของความสว่าง และเป็นบุตรของกลางวัน เราทั้งหลายไม่ได้เป็นของกลางคืน หรือของความมืด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 6, 'เหตุฉะนั้นอย่าให้เราหลับเหมือนอย่างคนอื่น แต่ให้เราเฝ้าระวังและไม่เมามาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 7, 'เพราะว่าคนนอนหลับก็ย่อมหลับในเวลากลางคืน และคนเมาก็ย่อมเมาในเวลากลางคืน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 8, 'แต่เมื่อเราเป็นของกลางวันแล้ว ก็อย่าให้เราเมามาย จงสวมความเชื่อกับความรักเป็นเกราะป้องกันอก และสวมความหวังที่จะได้ความรอดเป็นหมวกเหล็ก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 9, 'เพราะว่าพระเจ้ามิได้ทรงกําหนดเราไว้สําหรับพระอาชญา แต่สําหรับให้ได้รับความรอดโดยพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 10, 'ผู้ทรงสิ้นพระชนม์เพื่อเรา เพื่อว่าถึงเราจะตื่นอยู่หรือจะหลับ เราจะได้มีชีวิตกับพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 11, 'เหตุฉะนั้นจงหนุนใจกัน และต่างคนต่างจงก่อกันขึ้น ตามอย่างที่ท่านกําลังทําอยู่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 12, 'พี่น้องทั้งหลาย เราขอวิงวอนท่านให้รู้จักคนที่ทํางานอยู่ในพวกท่าน และปกครองท่านในองค์พระผู้เป็นเจ้า และตักเตือนท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 13, 'จงเคารพเขาให้มากในความรักเพราะงานที่เขาได้กระทํา และจงอยู่อย่างสงบสุขด้วยกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 14, 'แต่พี่น้องทั้งหลาย เราขอเตือนสติพวกท่านให้ตักเตือนคนที่เกะกะ หนุนน้ําใจผู้ที่ท้อใจ ชูกําลังคนที่อ่อนกําลัง และมีใจอดเอาเบาสู้ต่อคนทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 15, 'ระวังให้ดีอย่าให้คนใดทําชั่วตอบแทนการชั่วต่อคนอื่น แต่จงหาทางทําดีเสมอต่อพวกท่านเอง และต่อคนทั้งปวงด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 16, 'จงชื่นบานอยู่เสมอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 17, 'จงอธิษฐานอย่างสม่ําเสมอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 18, 'จงขอบพระคุณในทุกกรณี เพราะนี่แหละเป็นน้ําพระทัยของพระเจ้าในพระเยซูคริสต์เพื่อท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 19, 'อย่าดับพระวิญญาณ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 20, 'อย่าประมาทคําพยากรณ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 21, 'จงพิสูจน์ทุกสิ่ง สิ่งที่ดีนั้นจงยึดถือไว้ให้มั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 22, 'จงเว้นเสียจากสิ่งที่ดูเหมือนชั่วทุกอย่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 23, 'และขอให้องค์พระเจ้าแห่งสันติสุขทรงตั้งท่านเป็นคนบริสุทธิ์หมดจด และข้าพเจ้าอธิษฐานต่อพระเจ้าให้ทรงรักษาทั้งวิญญาณ จิตใจและร่างกายของท่านไว้ให้ปราศจากการติเตียน จนถึงวันที่พระเยซูคริสต์องค์พระผู้เป็นเจ้าของเราเสด็จมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 24, 'พระองค์ผู้ทรงเรียกท่านนั้นสัตย์ซื่อ และพระองค์จะทรงทําให้สําเร็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 25, 'พี่น้องทั้งหลาย จงอธิษฐานเพื่อเราด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 26, 'จงทักทายปราศรัยพวกพี่น้องด้วยธรรมเนียมจุบอันบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 27, 'ข้าพเจ้าบัญชาท่านทั้งหลายโดยองค์พระผู้เป็นเจ้า ให้ท่านอ่านจดหมายฉบับนี้ให้บรรดาพี่น้องอันบริสุทธิ์ฟัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 28, 'ขอให้พระคุณของพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเรา ดํารงอยู่กับท่านทั้งหลายเถิด เอเมน [จดหมายฉบับแรกถึงชาวเธสะโลนิกา เขียนจากกรุงเอเธนส์]');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 1, 'เปาโล สิลวานัส และทิโมธี เรียน คริสตจักรของชาวเมืองเธสะโลนิกาในพระเจ้าพระบิดาของเราและพระเยซูคริสต์เจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 2, 'ขอให้พระคุณและสันติสุขจากพระเจ้าพระบิดาของเรา และพระเยซูคริสต์เจ้า ดํารงอยู่กับท่านทั้งหลายเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 3, 'พี่น้องทั้งหลาย เราต้องขอบพระคุณพระเจ้าเพราะท่านทั้งหลายอยู่เสมอ และเป็นการสมควร เพราะความเชื่อของท่านก็จําเริญยิ่งขึ้น และความรักของท่านทุกคนที่มีต่อกันทวีขึ้นมากด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 4, 'ฉะนั้นเราเองจึงอวดท่านทั้งหลายต่อบรรดาคริสตจักรของพระเจ้าในเรื่องความเพียรและความเชื่อของท่าน ในการที่ท่านถูกข่มเหงทุกอย่างและการยากลําบากที่ท่านอดทนอยู่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 5, 'ซึ่งเป็นที่แสดงให้เห็นชัดถึงการพิพากษาอันชอบธรรมของพระเจ้า ซึ่งจะพิสูจน์ว่าท่านเป็นผู้สมควรกับอาณาจักรของพระเจ้า ด้วยเหตุนั้นท่านทั้งหลายจึงกําลังทนทุกข์อยู่ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 6, 'เพราะว่าเป็นการยุติธรรมแล้วซึ่งพระเจ้าจะทรงเอาความยากลําบาก ไปตอบแทนให้กับคนเหล่านั้นที่ก่อความยากลําบากให้กับท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 7, 'และที่จะทรงให้ท่านทั้งหลายที่รับความยากลําบากนั้น ได้รับความบรรเทาด้วยกันกับเรา เมื่อพระเยซูเจ้าจะปรากฏองค์จากสวรรค์ พร้อมกับหมู่ทูตสวรรค์ผู้มีฤทธิ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 8, 'ในเปลวเพลิงจะลงโทษสนองคนเหล่านั้นที่ไม่รู้จักพระเจ้า และแก่คนที่ไม่เชื่อฟังข่าวประเสริฐของพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 9, 'คนเหล่านั้นจะได้รับโทษอันเป็นความพินาศนิรันดร์ พ้นไปจากพระพักตร์องค์พระผู้เป็นเจ้า และจากสง่าราศีแห่งพระอานุภาพของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 10, 'ในวันนั้น เมื่อพระองค์จะเสด็จมาเพื่อรับเกียรติในพวกวิสุทธิชนของพระองค์ และเพื่อให้เป็นที่อัศจรรย์ใจแก่คนทั้งปวงที่เชื่อ (เพราะท่านก็ได้เชื่อคําพยานของเรา)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 11, 'เหตุฉะนั้นเราจึงอธิษฐานเพื่อท่านทั้งหลายเสมอ ว่าพระเจ้าของเราจะทรงถือว่าท่านเป็นผู้ที่สมควรแก่การที่พระองค์ได้ทรงเรียกนั้น และทรงบันดาลด้วยฤทธิ์เดชของพระองค์ให้ความประสงค์ดีทุกประการ และกิจการแห่งความเชื่อทุกอย่างสําเร็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 12, 'เพื่อพระนามของพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเราจะได้เกียรติเพราะท่านทั้งหลาย และท่านจะได้รับเกียรติเพราะพระองค์ ตามพระคุณแห่งพระเจ้าของเราและแห่งพระเยซูคริสต์เจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 1, 'บัดนี้ พี่น้องทั้งหลาย เรื่องการซึ่งพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเราจะเสด็จมา และที่พระองค์จะทรงรวบรวมเราทั้งหลายไปเป็นของพระองค์นั้น เราขอวิงวอนท่านว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 2, 'อย่าให้ใจของท่านหวั่นไหวง่าย หรือเป็นทุกข์ร้อนไป ไม่ว่าจะเป็นโดยทางวิญญาณ หรือโดยทางคําพูด หรือโดยทางจดหมายเป็นเชิงว่ามาจากเรา อ้างว่าวันของพระคริสต์มาถึงแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 3, 'อย่าให้ผู้หนึ่งผู้ใดล่อลวงท่านโดยทางหนึ่งทางใดเลย เพราะว่าวันนั้นจะไม่มาถึง เว้นแต่จะมีการล้มลงเสียก่อน และคนแห่งการบาปนั้นจะประจักษ์แจ้ง คือลูกแห่งความพินาศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 4, 'ผู้กีดกั้นขัดขวางและยกตัวขึ้นต่อสู้อะไรๆที่ได้ชื่อว่าเป็นพระเจ้า หรืออะไรๆที่เขาไหว้นมัสการนั้น แล้วมันก็นั่งในพระวิหารของพระเจ้าเหมือนอย่างพระเจ้า ประกาศตัวว่าเป็นพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 5, 'ท่านทั้งหลายจําไม่ได้หรือว่าเมื่อข้าพเจ้ายังอยู่กับท่าน ข้าพเจ้าได้บอกเรื่องนี้ให้ท่านทราบแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 6, 'และท่านก็รู้จักผู้นั้นที่กําลังหน่วงเหนี่ยวมันไว้ในขณะนี้ เพื่อมันจะปรากฏออกมาได้ต่อเมื่อถึงเวลาของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 7, 'เพราะว่าอํานาจลึกลับนอกกฎหมายนั้นก็เริ่มทํางานอยู่แล้ว เพียงแต่ผู้ที่คอยหน่วงเหนี่ยวเดี๋ยวนี้นั้นจะยังหน่วงเหนี่ยวอยู่ จนกว่าผู้ที่คอยหน่วงเหนี่ยวนั้นจะถูกพาออกไปเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 8, 'ขณะนั้นคนนอกกฎหมายนั้นจะปรากฏตัวขึ้น และองค์พระผู้เป็นเจ้าจะทรงประหารมันด้วยลมพระโอษฐ์ของพระองค์ และจะทรงผลาญให้สูญไปด้วยการปรากฏแห่งการเสด็จมาของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 9, 'คือผู้นั้นที่มาโดยการดลบันดาลของซาตาน พร้อมกับบรรดาการอิทธิฤทธิ์และหมายสําคัญ และการมหัศจรรย์แห่งความเท็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 10, 'และอุบายอธรรมทั้งหลายสําหรับคนเหล่านั้นที่พินาศอยู่ เพราะเขาทั้งหลายไม่ได้รับความรักแห่งความจริงไว้เพื่อจะรอดได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 11, 'เพราะเหตุนี้พระเจ้าจึงทรงให้ความลุ่มหลงมาครอบงําเขา ให้เขาเชื่อสิ่งที่เท็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 12, 'เพื่อคนทั้งหลายที่ไม่เชื่อความจริง แต่ยินดีในการไม่ชอบธรรม จะได้ถูกลงพระอาชญาทุกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 13, 'พี่น้องทั้งหลาย ผู้เป็นที่รักขององค์พระผู้เป็นเจ้า เราจําเป็นต้องขอบพระคุณพระเจ้าเพราะท่านอยู่เสมอ เพราะว่าพระเจ้าได้ทรงเลือกท่านไว้ตั้งแต่เริ่มแรกให้ถึงที่รอด โดยพระวิญญาณทรงชําระตั้งท่านไว้ให้บริสุทธิ์ และโดยท่านได้เชื่อความจริง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 14, 'พระองค์ได้ทรงเรียกท่านทั้งหลายโดยทางข่าวประเสริฐของเรา เพื่อจะได้รับสง่าราศีของพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 15, 'เหตุฉะนั้น พี่น้องทั้งหลาย จงมั่นคงไว้ และยึดถือโอวาทที่ท่านได้เรียนแล้ว ไม่ว่าจะด้วยคําพูด หรือด้วยจดหมายของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 16, 'บัดนี้ ขอให้พระเยซูคริสต์องค์พระผู้เป็นเจ้าของเรา และพระเจ้าคือพระบิดาของเรา ผู้ทรงรักเรา และประทานให้เรามีความชูใจนิรันดร์ และความหวังอันดีโดยพระคุณ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 17, 'ทรงชูใจและตั้งใจของท่านไว้ให้มั่นคง ในวาจาและในการกระทําอันดีทุกอย่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 1, 'พี่น้องทั้งหลาย ในที่สุดนี้จงอธิษฐานเพื่อเรา เพื่อว่าพระวจนะขององค์พระผู้เป็นเจ้าจะได้แผ่ไป และจะได้รับเกียรติยศเหมือนอย่างที่ได้เป็นไปในหมู่พวกท่านแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 2, 'และเพื่อเราจะได้พ้นจากคนพาลชั่วร้าย เพราะว่าไม่ใช่ทุกคนมีความเชื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 3, 'แต่ว่าองค์พระผู้เป็นเจ้าทรงสัตย์ซื่อ จะทรงเสริมกําลังท่านทั้งหลาย และทรงป้องกันท่านไว้ให้พ้นจากการชั่วร้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 4, 'เรามีความมั่นใจในองค์พระผู้เป็นเจ้าเกี่ยวกับท่านว่า ท่านกําลังประพฤติและจะประพฤติต่อไปตามที่เรากําชับท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 5, 'ขอองค์พระผู้เป็นเจ้าทรงนําใจของท่านทั้งหลายให้เข้าในความรักของพระเจ้า และอดทนในการรอคอยพระคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 6, 'บัดนี้ พี่น้องทั้งหลาย เราขอกําชับท่านในพระนามของพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเราว่า จงปลีกตัวของท่านออกไปจากพี่น้องทุกคนที่อยู่อย่างเกะกะ และไม่ดําเนินตามโอวาทซึ่งเขาได้รับจากเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 7, 'เพราะว่าตัวท่านเองก็รู้อยู่ว่าท่านควรจะทําตามเราอย่างไร เพราะเรามิได้ประพฤติเกะกะเลยเมื่อเราอยู่ในหมู่พวกท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 8, 'และเรามิได้ทานอาหารผู้ใดเปล่าๆ แต่เราได้ทําการหนักด้วยความพากเพียรทั้งกลางคืนและกลางวัน เพื่อเราจะไม่เป็นภาระแก่คนหนึ่งคนใดในพวกท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 9, 'มิใช่เพราะเราไม่มีสิทธิ์ แต่ว่าเพื่อทําตัวเป็นแบบอย่างให้ท่านทั้งหลายทําตามเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 10, 'แม้เมื่อเราอยู่กับพวกท่าน เราก็ได้กําชับท่านอย่างนี้ว่า ถ้าผู้ใดไม่ยอมทํางาน ก็อย่าให้เขากิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 11, 'เพราะเราได้ยินว่า มีบางคนในพวกท่านอยู่อย่างเกะกะ ไม่ทํางานอะไรเลย แต่ชอบยุ่งกับธุระของคนอื่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 12, 'เราจึงกําชับและเตือนสติคนเช่นนั้นโดยพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเราว่า ให้เขาทํางานด้วยใจสงบ และกินอาหารของตนเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 13, 'พี่น้องทั้งหลาย ท่านอย่าอ่อนใจที่จะกระทําการดีเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 14, 'ถ้าผู้ใดไม่เชื่อฟังถ้อยคําของเราในจดหมายฉบับนี้ จงจดจําคนนั้นไว้ อย่าสมาคมกับเขาเลย เพื่อเขาจะได้อาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 15, 'อย่าถือว่าเขาเป็นศัตรู แต่จงเตือนสติเขาฉันพี่น้องคนหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 16, 'บัดนี้ ขอให้องค์พระผู้เป็นเจ้าแห่งสันติสุข ทรงโปรดประทานสันติสุขให้แก่ท่านทั้งหลายทุกเวลาและทุกทาง ขอให้องค์พระผู้เป็นเจ้าดํารงอยู่กับท่านทุกคนเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 17, 'นี่แหละเป็นคําคํานับของข้าพเจ้าคือ เปาโล ที่เขียนด้วยมือของข้าพเจ้าเอง ซึ่งเป็นเครื่องหมายในจดหมายทุกฉบับ ข้าพเจ้าจึงเขียนเช่นนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 18, 'ขอให้พระคุณของพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเรา ดํารงอยู่กับท่านทั้งหลายเถิด เอเมน [จดหมายฉบับที่สองถึงชาวเธสะโลนิกา เขียนจากกรุงเอเธนส์]');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 1, 'เปาโล อัครสาวกของพระเยซูคริสต์ ตามพระบัญชาของพระเจ้าผู้ทรงเป็นพระผู้ช่วยให้รอดของเรา และพระเยซูคริสต์เจ้าผู้ทรงเป็นความหวังของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 2, 'ถึง ทิโมธี ผู้เป็นบุตรแท้ของข้าพเจ้าในความเชื่อ ขอพระคุณและพระกรุณาและสันติสุขจากพระเจ้าพระบิดาของเราและจากพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเรา จงดํารงอยู่กับท่านเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 3, 'เมื่อข้าพเจ้าได้ไปยังแคว้นมาซิโดเนีย ตามที่ข้าพเจ้าได้ขอร้องให้ท่านคอยอยู่ในเมืองเอเฟซัส เพื่อท่านจะได้กําชับบางคนไม่ให้เขาสอนคําสอนอื่นๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 4, 'ทั้งไม่ให้เขาใส่ใจในเรื่องนิยายต่างๆและเรื่องลําดับวงศ์ตระกูลอันไม่รู้จบ ซึ่งเป็นเหตุให้เกิดปัญหามากกว่าให้เกิดความจําเริญในทางของพระเจ้า อันดําเนินไปด้วยความเชื่อ ก็จงกระทําดังนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 5, 'แต่จุดประสงค์แห่งพระบัญญัตินั้นก็คือ ความรักซึ่งเกิดจากใจอันบริสุทธิ์ และจากจิตสํานึกอันดี และจากความเชื่ออันจริงใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 6, 'บางคนก็ได้ผิดจุดประสงค์เลี่ยงไปจากสิ่งเหล่านี้หลงไปในทางพูดเหลวไหล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 7, 'และแม้ว่าเขาไม่เข้าใจคําที่เขากล่าวทั้งสิ่งที่เขายืนยัน เขาก็ยังปรารถนาเป็นอาจารย์ฝ่ายพระราชบัญญัติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 8, 'แต่เราทั้งหลายรู้อยู่ว่าพระราชบัญญัตินั้นดี ถ้าผู้ใดใช้ให้ถูกต้อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 9, 'คือโดยรู้ว่าพระราชบัญญัตินั้นมิได้ทรงบัญญัติไว้สําหรับคนชอบธรรม แต่ทรงบัญญัติไว้สําหรับคนอยู่นอกพระราชบัญญัติและคนดื้อด้าน คนอธรรมและคนบาป คนไม่บริสุทธิ์และคนหมิ่นประมาท คนฆาตกรรมพ่อ คนฆาตกรรมแม่ คนฆ่าคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 10, 'คนล่วงประเวณี พวกกะเทย ผู้ร้ายลักคน คนโกหก คนทวนสบถ และอะไรๆที่ขัดกับคําสอนอันถูกต้อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 11, 'ตามที่มีอยู่ในข่าวประเสริฐอันมีสง่าราศีของพระเจ้าผู้เสวยสุข คือข่าวประเสริฐที่ได้ทรงมอบไว้กับข้าพเจ้านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 12, 'ข้าพเจ้าขอบพระคุณพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเรา ผู้ทรงชูกําลังข้าพเจ้า ด้วยว่าพระองค์ทรงถือว่าข้าพเจ้าเป็นคนสัตย์ซื่อ จึงทรงตั้งข้าพเจ้าให้ปฏิบัติพระราชกิจของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 13, 'ถึงแม้ว่าเมื่อก่อนนั้นข้าพเจ้าเป็นคนหมิ่นประมาท ข่มเหง และเป็นผู้ปฏิบัติอย่างหยาบช้า แต่ข้าพเจ้าได้รับพระกรุณา เพราะว่าที่ข้าพเจ้าได้กระทําอย่างนั้นก็ได้กระทําไปโดยความเขลาเพราะความไม่เชื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 14, 'และพระคุณแห่งองค์พระผู้เป็นเจ้าของเรานั้นมีมากเหลือล้น พร้อมด้วยความเชื่อและความรักซึ่งมีอยู่ในพระเยซูคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 15, 'คํานี้เป็นคําสัตย์จริงและสมควรที่คนทั้งปวงจะรับไว้ คือว่าพระเยซูคริสต์ได้เสด็จมาในโลกเพื่อจะได้ทรงช่วยคนบาปให้รอด และในพวกคนบาปนั้นข้าพเจ้าเป็นตัวเอก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 16, 'แต่ว่าเพราะเหตุนี้เองข้าพเจ้าจึงได้รับพระกรุณา คือว่าเพื่อพระเยซูคริสต์จะได้ทรงสําแดงความอดกลั้นพระทัยทุกอย่างให้เห็นในตัวข้าพเจ้าซึ่งเป็นตัวเอกนั้น ให้เป็นแบบอย่างแก่คนทั้งปวงที่ภายหลังจะเชื่อวางใจในพระองค์แล้วรับชีวิตนิรันดร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 17, 'บัดนี้ พระเกียรติและสง่าราศีจงมีแด่พระมหากษัตริย์ผู้ทรงพระเจริญอยู่นิรันดร์ ผู้ทรงเป็นองค์อมตะ ซึ่งมิได้ปรากฏแก่ตา พระเจ้าผู้ทรงพระปัญญาแต่พระองค์เดียว สืบๆไปเป็นนิตย์ เอเมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 18, 'ทิโมธีบุตรเอ๋ย คํากําชับนี้ข้าพเจ้าได้ให้ไว้กับท่านตามคําพยากรณ์ซึ่งมาล่วงหน้าเล็งถึงท่าน เพื่อข้อความเหล่านั้นท่านจะได้เข้าสู้รบได้ดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 19, 'จงยึดความเชื่อไว้และมีจิตสํานึกอันดี ซึ่งข้อนี้บางคนได้ละทิ้งเสีย ความเชื่อของเขาจึงอับปางลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 20, 'ในคนเหล่านั้นมีฮีเมเนอัสและอเล็กซานเดอร์ ซึ่งข้าพเจ้าได้มอบไว้แก่ซาตานแล้ว เพื่อเขาจะได้เรียนรู้ที่จะไม่หมิ่นประมาท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 1, 'เหตุฉะนั้นก่อนสิ่งอื่นใด ข้าพเจ้าขอเตือนสติท่านทั้งหลายให้วิงวอนอธิษฐานทูลขอ และขอบพระคุณเพื่อคนทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 2, 'เพื่อกษัตริย์ทั้งหลายและคนทั้งปวงที่มีตําแหน่งสูง เพื่อเราจะได้ดําเนินชีวิตอย่างเงียบๆและสงบสุข ในทางที่เป็นอย่างพระเจ้าและอย่างซื่อสัตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 3, 'การเช่นนี้เป็นการดีและเป็นที่ชอบในสายพระเนตรของพระเจ้า พระผู้ช่วยให้รอดของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 4, 'ผู้ทรงมีพระประสงค์ให้คนทั้งปวงรอด และให้มาถึงความรู้ในความจริงนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 5, 'ด้วยเหตุว่า มีพระเจ้าองค์เดียวและมีคนกลางแต่ผู้เดียวระหว่างพระเจ้ากับมนุษย์ คือพระเยซูคริสต์ผู้ทรงสภาพเป็นมนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 6, 'ผู้ทรงประทานพระองค์เองเป็นค่าไถ่สําหรับคนทั้งปวง เหตุการณ์นี้เป็นพยานในเวลาอันเหมาะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 7, 'และสําหรับการนี้ ข้าพเจ้าจึงได้ถูกตั้งไว้เป็นนักเทศน์และเป็นอัครสาวก (ข้าพเจ้าพูดความจริงในพระคริสต์และไม่ปดเลย) และเป็นครูสอนความเชื่อและความจริงแก่คนต่างชาติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 8, 'เหตุฉะนั้น ข้าพเจ้าปรารถนาให้ผู้ชายทั้งหลายอธิษฐานในที่ทุกแห่ง โดยยกมืออันบริสุทธิ์ปราศจากโทโสและการเถียงกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 9, 'ฝ่ายพวกผู้หญิงก็เหมือนกันให้แต่งตัวสุภาพเรียบร้อยพร้อมด้วยความรู้จักละอาย และความมีสติสัมปชัญญะ ไม่ใช่ถักผมหรือประดับกายด้วยเครื่องทองและไข่มุกหรือเสื้อผ้าราคาแพง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 10, 'แต่ให้ประดับด้วยการกระทําดี (ซึ่งสมกับหญิงที่ประกาศตัวว่าถือพระเจ้า)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 11, 'ให้ผู้หญิงเรียนอย่างเงียบๆและด้วยใจนอบน้อมทุกอย่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 12, 'ข้าพเจ้าไม่อนุญาตให้ผู้หญิงสั่งสอนหรือใช้อํานาจเหนือผู้ชาย แต่ให้เขานิ่งๆอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 13, 'ด้วยว่าพระเจ้าทรงเนรมิตสร้างอาดัมก่อน แล้วจึงทรงสร้างเอวา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 14, 'และอาดัมไม่ได้ถูกหลอกลวง แต่ผู้หญิงนั้นได้ถูกหลอกลวงจึงได้ละเมิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 15, 'แต่ถึงกระนั้นเธอก็จะรอดได้ด้วยการคลอดบุตร ถ้าเขาทั้งหลายยังดํารงอยู่ในความเชื่อ ในความรัก และในความบริสุทธิ์ ด้วยความมีสติสัมปชัญญะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 1, 'คํานี้เป็นคําจริง คือว่าถ้าชายคนใดปรารถนาหน้าที่ผู้ดูแล คนนั้นก็ปรารถนากิจการงานที่ประเสริฐ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 2, 'ผู้ดูแลนั้นจึงต้องเป็นคนที่ไม่มีใครติได้ เป็นสามีของหญิงคนเดียว เป็นคนรอบคอบ เป็นคนรู้จักประมาณตน เป็นคนมีความประพฤติดี มีอัชฌาสัยรับแขกดี เหมาะที่จะเป็นครู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 3, 'ไม่ดื่มเหล้าองุ่น ไม่เป็นนักเลง ไม่เป็นคนโลภมักได้ แต่เป็นคนสุภาพ ไม่เป็นคนชอบวิวาท ไม่เป็นคนเห็นแก่เงิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 4, 'ต้องเป็นคนครอบครองบ้านเรือนของตนได้ดี บังคับบัญชาบุตรทั้งหลายของตนด้วยความสง่าผ่าเผยทุกอย่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 5, '(เพราะว่าถ้าชายคนใดไม่รู้จักครอบครองบ้านเรือนของตน คนนั้นจะดูแลคริสตจักรของพระเจ้าอย่างไรได้)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 6, 'อย่าให้ผู้ที่กลับใจใหม่ๆเป็นผู้ดูแล เกรงว่าเขาอาจจะเย่อหยิ่ง และก็จะถูกปรับโทษเหมือนอย่างพญามาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 7, 'นอกนั้นเขาจะต้องมีชื่อเสียงดีในคนภายนอก เกรงว่าเขาจะเป็นที่ติเตียน และจะติดบ่วงแร้วของพญามาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 8, 'ฝ่ายผู้ช่วยนั้นก็เช่นเดียวกัน คือต้องเป็นคนสง่าผ่าเผย ไม่เป็นคนสองลิ้น ไม่สนใจเหล้าองุ่นมาก ไม่เป็นคนโลภมักได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 9, 'และเป็นคนยึดมั่นในข้อลึกลับแห่งความเชื่อด้วยจิตสํานึกผิดและชอบอันบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 10, 'จงลองดูคนเหล่านี้เสียก่อนด้วย และเมื่อเห็นว่าไม่มีข้อตําหนิแล้ว จึงตั้งเขาไว้ในตําแหน่งผู้ช่วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 11, 'ฝ่ายพวกภรรยาของเขาก็เหมือนกัน ต้องเป็นคนสง่าผ่าเผย ไม่ใส่ร้ายผู้อื่น เป็นคนรู้จักประมาณตน และเป็นคนสัตย์ซื่อในสิ่งทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 12, 'จงให้ผู้ช่วยนั้นเป็นสามีของหญิงคนเดียว และบังคับบัญชาบุตรของตน และปกครองบ้านเรือนของตนได้ดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 13, 'เพราะว่าคนที่กระทําการในหน้าที่ผู้ช่วยได้ดี ก็ได้ตําแหน่งอันมีหน้ามีตา และมีใจกล้าเป็นอันมากในความเชื่อซึ่งมีในพระเยซูคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 14, 'ข้อความเหล่านี้ข้าพเจ้าเขียนฝากมายังท่าน หวังใจว่าไม่ช้าไม่นานข้าพเจ้าจะมาหาท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 15, 'แต่หากว่าข้าพเจ้ามาช้า ท่านก็จะได้รู้ว่าควรประพฤติอย่างไรในครอบครัวของพระเจ้า คือคริสตจักรของพระเจ้าผู้ดํารงพระชนม์ เป็นหลักและรากแห่งความจริง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 16, 'ทางของพระเจ้าอันยิ่งใหญ่และลึกลับซึ่งไม่มีใครปฏิเสธได้ก็คือ พระเจ้าทรงปรากฏในเนื้อหนัง พระวิญญาณได้ทรงพิสูจน์แล้ว หมู่ทูตสวรรค์ก็เห็น และมีผู้ประกาศพระองค์แก่ชนต่างชาติ มีชาวโลกเชื่อถือพระองค์ และพระองค์ทรงถูกรับขึ้นไปในสง่าราศี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 1, 'บัดนี้ พระวิญญาณได้ตรัสไว้อย่างชัดแจ้งว่า ในกาลภายหลังจะมีบางคนละทิ้งความเชื่อ โดยหันไปเชื่อฟังวิญญาณที่ล่อลวง และฟังคําสอนของพวกผีปีศาจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 2, 'การหน้าซื่อใจคดของคนที่พูดโกหก คือทําไปทั้งรู้ๆเหมือนอย่างกับเอาเหล็กแดงนาบลงไปบนจิตสํานึกผิดชอบของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 3, 'เขาห้ามไม่ให้ทําการสมรส ไม่ให้รับประทานอาหารซึ่งพระเจ้าทรงสร้างไว้ให้ผู้ที่เชื่อและรู้จักความจริงรับประทานด้วยขอบพระคุณ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 4, 'ด้วยว่าสิ่งสารพัดซึ่งพระเจ้าได้ทรงสร้างไว้นั้นเป็นของดี ถ้าแม้รับประทานด้วยขอบพระคุณ ก็ไม่ห้ามเลยสักสิ่งเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 5, 'เพราะว่าสิ่งเหล่านั้นเป็นของที่ชําระไว้แล้วโดยพระวจนะของพระเจ้าและคําอธิษฐาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 6, 'ถ้าท่านจะให้พวกพี่น้องระลึกถึงสิ่งเหล่านี้ ท่านก็จะเป็นผู้รับใช้ที่ดีของพระเยซูคริสต์ เจริญด้วยพระวจนะแห่งความเชื่อ และด้วยหลักคําสั่งสอนอันดีที่ท่านได้ประพฤติตามนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 7, 'แต่จงหลีกเลี่ยงจากนิยายอันหยาบคาย และนิยายซึ่งยายเคยเล่าให้ฟังนั้น จงฝึกตนในทางที่เป็นอย่างพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 8, 'เพราะว่าการฝึกทางกายนั้นมีประโยชน์อยู่บ้าง แต่ทางของพระเจ้าก็มีประโยชน์ในทุกทาง คือมีพระสัญญาสําหรับชีวิตปัจจุบันและชีวิตอนาคตด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 9, 'คํานี้เป็นคําสัตย์จริงและสมควรที่คนทั้งปวงจะรับไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 10, 'ด้วยเหตุนี้ เราจึงตรากตรําทํางานและทนสู้ ก็เพราะเรามีความหวังใจในพระเจ้าผู้ดํารงพระชนม์ ผู้ทรงเป็นพระผู้ช่วยให้รอดของคนทั้งปวง โดยเฉพาะของผู้ที่เชื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 11, 'จงบัญชาและสั่งสอนสิ่งเหล่านี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 12, 'อย่าให้ผู้ใดดูหมิ่นความหนุ่มแน่นของท่าน แต่จงเป็นแบบอย่างของคนทั้งหลายที่เชื่อ ทั้งในทางวาจา ในการประพฤติ ในความรัก ในน้ําใจ ในความเชื่อ และในความบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 13, 'จงใฝ่ใจในการอ่าน ในการเทศนา และในการสั่งสอน จนกว่าเราจะมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 14, 'อย่าละเลยของประทานที่มีอยู่ในตัวท่าน ซึ่งได้ทรงประทานแก่ท่านตามคําพยากรณ์ เมื่อพวกผู้ปกครองได้เอามือวางบนท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 15, 'จงไตร่ตรองในข้อความเหล่านี้ ฝังตัวท่านไว้ในการนี้ทีเดียว เพื่อความจําเริญของท่านจะได้ปรากฏแจ้งแก่คนทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 16, 'จงระวังตัวท่านและคําสอนของท่าน จงยึดข้อที่กล่าวนี้ให้มั่น เพราะเมื่อกระทําดังนั้น ท่านจะช่วยทั้งตัวท่านเองและคนทั้งปวงที่ฟังท่านให้รอดได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 1, 'อย่าพูดสบประมาทคนมีอาวุโส แต่จงตักเตือนเขาเสมือนเป็นบิดา และคนหนุ่มๆทั้งหลายเป็นเสมือนพี่หรือน้อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 2, 'และผู้หญิงผู้มีอาวุโสเป็นเสมือนมารดา และส่วนหญิงสาวๆก็ให้เป็นเสมือนพี่สาวน้องสาว ด้วยความบริสุทธิ์ทั้งหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 3, 'จงให้เกียรติแก่หญิงม่ายไร้ที่พึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 4, 'แต่ถ้าหญิงม่ายคนใดมีลูกหลานก็ให้ลูกหลานนั้นเรียนเพื่อให้รู้จักที่จะปฏิบัติกับครอบครัวของตนก่อน และให้ตอบแทนคุณบิดามารดาของตน เพราะว่าการกระทําเช่นนี้เป็นการดีและเป็นที่ชอบต่อพระพักตร์พระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 5, 'ฝ่ายผู้หญิงที่เป็นหญิงม่ายอย่างแท้จริง และอยู่ตามลําพังแต่ผู้เดียวนั้น จงวางใจในพระเจ้า และดํารงอยู่ในการวิงวอนและการอธิษฐานทั้งกลางคืนและกลางวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 6, 'ส่วนผู้หญิงที่ปล่อยตัวในการสนุกสนานนั้น ก็ตายแล้วทั้งเป็นๆอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 7, 'จงกําชับข้อความเหล่านี้ เพื่อเขาจะไม่ถูกตําหนิ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 8, 'แต่ถ้าแม้ผู้ใดไม่เลี้ยงดูวงศ์ญาติของตน และโดยเฉพาะอย่างยิ่งคนในบ้านเรือนของตน ผู้นั้นก็ได้ปฏิเสธความเชื่อเสียแล้ว และชั่วยิ่งกว่าคนที่ไม่ได้เชื่อเสียอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 9, 'อย่าให้หญิงม่ายคนใดที่อายุต่ํากว่าหกสิบปี ลงชื่อในทะเบียนหญิงม่าย จะต้องเป็นภรรยาของชายคนเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 10, 'และจะต้องเป็นผู้ที่ได้ชื่อว่าได้กระทําดี เช่นได้เอาใจใส่เลี้ยงดูลูก ได้มีน้ําใจรับรองแขก ได้ล้างเท้าวิสุทธิชน ได้สงเคราะห์คนที่มีความทุกข์ยาก และได้บําเพ็ญคุณความดีทุกอย่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 11, 'แต่หญิงม่ายสาวๆนั้นอย่ารับขึ้นทะเบียน เพราะว่าเมื่อเขาหลงระเริงห่างจากพระคริสต์ไปแล้ว ก็ใคร่จะสมรสอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 12, 'เขาจะต้องได้รับพระอาชญา เพราะเขาได้ทิ้งความเชื่อเดิมของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 13, 'นอกจากนั้นเขาก็จะกลายเป็นคนเกียจคร้าน เที่ยวไปบ้านนี้บ้านนั้น และมิใช่แต่เกียจคร้านเท่านั้น แต่ปากบอนด้วย และเที่ยวยุ่งกับเรื่องของผู้อื่น พูดสิ่งซึ่งไม่ควรจะพูด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 14, 'เหตุฉะนั้นข้าพเจ้าปรารถนาให้พวกหญิงม่ายสาวๆนั้นมีสามี มีบุตร และดูแลบ้านเรือน เพื่อมิให้ศัตรูมีช่องทางนินทาได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 15, 'ด้วยว่ามีบางคนได้หลงตามซาตานไปแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 16, 'ถ้าชายหรือหญิงผู้มีความเชื่อคนใดมีหญิงม่าย ก็ให้เขาช่วยเลี้ยงดู อย่าให้เป็นภาระของคริสตจักรเลย เพื่อคริสตจักรจะได้สงเคราะห์คนที่เป็นหญิงม่ายไร้ที่พึ่งจริงๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 17, 'จงถือว่าผู้ปกครองที่ปกครองดีนั้นสมควรได้รับเกียรติสองเท่า โดยเฉพาะอย่างยิ่งผู้ปกครองที่ทํางานหนักในการเทศนาและสั่งสอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 18, 'เพราะพระคัมภีร์กล่าวว่า ‘อย่าเอาตะกร้าครอบปากวัว เมื่อมันกําลังนวดข้าวอยู่’ และ ‘ผู้ทํางานสมควรจะได้รับค่าจ้างของตน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 19, 'อย่ายอมรับคํากล่าวหาผู้ปกครองคนใด เว้นเสียแต่จะมีพยานสองสามคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 20, 'สําหรับผู้ปกครองที่ยังคงกระทําบาป จงว่ากล่าวเขาต่อหน้าคนทั้งปวง เพื่อผู้อื่นจะได้เกรงกลัวด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 21, 'ข้าพเจ้ากําชับท่านต่อพระพักตร์พระเจ้าและต่อพระเยซูคริสต์เจ้า และต่อเหล่าทูตสวรรค์ที่ทรงเลือกสรรไว้แล้วนั้น ให้ท่านรักษาข้อความเหล่านี้ไว้โดยไม่เห็นแก่หน้าผู้ใด และไม่กระทําการใดๆด้วยใจลําเอียง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 22, 'อย่าด่วนวางมือเจิมผู้ใด และอย่ามีส่วนร่วมในการกระทําบาปของผู้อื่นเลย จงรักษาตัวให้บริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 23, 'อย่าดื่มแต่น้ําอีกต่อไป แต่จงใช้น้ําองุ่นบ้างเล็กน้อย เพื่อประโยชน์แก่กระเพาะอาหารของท่านและโรคที่บังเกิดแก่ท่านเนืองๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 24, 'การผิดของบางคนย่อมปรากฏเด่นขึ้นก่อน แล้วก็นําเขาไปถึงที่พิพากษา แต่การผิดของบางคนนั้นจะตามหลังเขาไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 25, 'ฝ่ายการดีของบางคนก็ปรากฏเด่นขึ้นก่อนด้วยเหมือนกัน และการนอกนั้นจะปิดบังไว้ก็ไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 1, 'จงให้คนทั้งหลายที่อยู่ใต้แอกแห่งความเป็นทาส ถือว่านายของตนเป็นผู้สมควรแก่การได้รับเกียรติยศทุกสถาน เพื่อพระนามของพระเจ้าและคําสอนของพระองค์จะมิได้ถูกหมิ่นประมาท');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 2, 'ฝ่ายคนเหล่านั้นผู้มีนายเป็นผู้มีความเชื่อก็อย่าให้เขาประมาทนาย เพราะว่าเหตุที่ได้มาเป็นพี่น้องกันแล้ว แต่ยิ่งกว่านั้นเขาต้องรับใช้นายให้ดีขึ้น เพราะเหตุว่านายผู้ที่จะได้รับประโยชน์เป็นผู้สัตย์ซื่อและเป็นที่รัก ข้อความเหล่านี้จงสั่งสอนและตักเตือนกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 3, 'ถ้าผู้ใดสอนผิดไปจากนี้ และไม่ยอมเห็นด้วยกับพระวจนะอันมีหลัก คือพระวจนะของพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเรา และคําสอนที่สมกับทางของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 4, 'ผู้นั้นก็เป็นคนทะนงตัวและไม่รู้อะไร แต่ชอบทุ่มเถียงและโต้แย้งในเรื่องคํา ซึ่งเป็นเหตุให้เกิดการอิจฉากัน การทะเลาะวิวาทกัน การกล่าวร้ายกัน การไม่ไว้วางใจกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 5, 'และการวิวาทที่ดื้อดึงของผู้มีใจทรามและไร้ความจริง ที่คาดว่าการได้กําไรนั้นเป็นทางของพระเจ้า จงถอนตัวไปเสียจากคนเช่นนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 6, 'แต่ว่าทางของพระเจ้าพร้อมทั้งความสุขใจก็เป็นกําไรมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 7, 'เพราะว่าเราไม่ได้เอาอะไรเข้ามาในโลกฉันใด เราก็เอาอะไรออกไปจากโลกไม่ได้ฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 8, 'แต่ถ้าเรามีอาหารและเสื้อผ้า ก็ให้เราพอใจด้วยของเหล่านั้นเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 9, 'ส่วนคนเหล่านั้นที่อยากร่ํารวยก็ตกอยู่ในการทดลองและติดบ่วงแร้ว และในตัณหาหลายอย่างอันโฉดเขลาและเป็นภัยแก่ตัว ซึ่งทําให้คนเราต้องจมลงถึงความพินาศเสื่อมสูญไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 10, 'ด้วยว่าการรักเงินนั้นเป็นรากเหง้าแห่งความชั่วทั้งสิ้น ขณะที่บางคนโลภสิ่งเหล่านี้จึงได้หลงไปจากความเชื่อนั้น และทิ่มแทงตัวของเขาเองให้ทะลุด้วยความทุกข์ใจเป็นอันมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 11, 'โอ ผู้เป็นคนของพระเจ้า แต่ท่านจงหลีกหนีเสียจากสิ่งเหล่านี้ จงมุ่งมั่นในความชอบธรรม ในทางของพระเจ้า ความเชื่อ ความรัก ความอดทน และความอ่อนสุภาพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 12, 'จงต่อสู้อย่างเต็มกําลังเพื่อความเชื่อ จงยึดชีวิตนิรันดร์ไว้ ซึ่งพระเจ้าทรงเรียกให้ท่านรับในเมื่อท่านได้รับเชื่ออย่างดีต่อหน้าพยานหลายคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 13, 'ข้าพเจ้ากําชับท่านต่อพระเนตรพระเจ้า ผู้ทรงประทานชีวิตแก่สิ่งทั้งปวง และต่อพระเยซูคริสต์ ผู้ได้ทรงเป็นพยานอันดีต่อหน้าปอนทิอัสปีลาต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 14, 'ให้ท่านรักษาคําบัญชานี้ไว้อย่าให้ด่างพร้อย และอย่าให้มีที่ติได้ จนถึงเวลาที่พระเยซูคริสต์องค์พระผู้เป็นเจ้าของเราจะเสด็จมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 15, 'ซึ่งพระองค์จะทรงสําแดงให้ปรากฏในเวลาของพระองค์ คือพระองค์ผู้เสวยสุขและทรงฤทธิ์สูงสุดแต่พระองค์เดียว พระมหากษัตริย์เหนือกษัตริย์ทั้งปวง และองค์พระผู้เป็นเจ้าเหนือเจ้านายทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 16, 'พระองค์ผู้เดียวทรงอมตะ และทรงสถิตในความสว่างที่ซึ่งไม่มีคนใดจะเข้าไปถึง ผู้ซึ่งมนุษย์ไม่เคยเห็น และจะเห็นไม่ได้ พระเกียรติและฤทธานุภาพจงมีแด่พระองค์นั้นสืบๆไปเป็นนิตย์ เอเมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 17, 'จงกําชับคนเหล่านั้นที่มั่งมีฝ่ายโลก อย่าให้มีใจถือมานะทิฐิ อย่าให้ความหวังของเขาอิงอยู่กับทรัพย์อนิจจัง แต่ให้หวังในพระเจ้าผู้ทรงพระชนม์อยู่ ผู้ทรงประทานสิ่งสารพัดให้แก่เราอย่างบริบูรณ์ เพื่อจะให้เราใช้ด้วยความปีติยินดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 18, 'จงกําชับเขาให้กระทําการดี ให้ร่ํารวยในการดีนั้น ให้มีใจพร้อมที่จะให้ทาน ให้มีใจกว้างขวาง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 19, 'และส่ําสมไว้เป็นรากอันดีสําหรับตัวของตนเผื่อเวลาข้างหน้า เพื่อว่าเขาจะยึดชีวิตนิรันดร์ไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 20, 'โอ ทิโมธีเอ๋ย จงรักษาสิ่งที่ได้ฝากไว้กับความไว้วางใจของท่าน จงหลีกเลี่ยงคําพูดที่ลบหลู่และไร้ประโยชน์ และการคัดค้านของสิ่งที่เรียกกันอย่างผิดๆว่าเป็นศาสตร์ความรู้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 21, 'ซึ่งบางคนสําคัญผิดอย่างนั้น จึงได้พลาดไปจากความเชื่อ ขอพระคุณจงดํารงอยู่กับท่านเถิด เอเมน [จดหมายฉบับแรกถึงทิโมธี เขียนจากเมืองเลาดีเซีย ซึ่งเป็นนครหลวงในแคว้นฟรีเจีย ปาคาทีอานา]');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 1, 'เปาโล อัครสาวกของพระเยซูคริสต์ ตามพระประสงค์ของพระเจ้า ตามพระสัญญาแห่งชีวิต ซึ่งมีในพระเยซูคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 2, 'ถึง ทิโมธี บุตรที่รักของข้าพเจ้า ขอพระคุณและพระเมตตาและสันติสุขจากพระเจ้าพระบิดา และพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเรา จงดํารงอยู่กับท่านเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 3, 'ข้าพเจ้าขอบพระคุณพระเจ้าผู้ซึ่งข้าพเจ้าได้รับใช้ ด้วยจิตสํานึกอันบริสุทธิ์สืบมาตั้งแต่บรรพบุรุษของข้าพเจ้า เพราะข้าพเจ้าได้ระลึกถึงท่านในคําอธิษฐานของข้าพเจ้ามิได้หยุดหย่อนทั้งกลางคืนและกลางวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 4, 'ก็ได้ปรารถนาเป็นอันมากที่จะเห็นท่าน ระลึกถึงน้ําตาของท่าน เพื่อข้าพเจ้าจะได้เต็มไปด้วยความยินดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 5, 'ข้าพเจ้าระลึกถึงความเชื่ออันแท้นั้นซึ่งมีอยู่ในท่าน และซึ่งเมื่อก่อนได้มีอยู่ในโลอิสยายของท่าน และซึ่งได้มีอยู่ในยูนีสมารดาของท่าน และซึ่งข้าพเจ้าเชื่อมั่นคงว่ามีอยู่ในท่านด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 6, 'เหตุฉะนั้นข้าพเจ้าจึงสะกิดใจท่านให้ใช้ของประทานของพระเจ้าที่มีอยู่ในท่าน โดยการวางมือของข้าพเจ้านั้นให้รุ่งเรืองขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 7, 'เพราะว่าพระเจ้ามิได้ทรงประทานจิตที่ขลาดกลัวให้เรา แต่ได้ทรงประทานจิตที่กอปรด้วยฤทธิ์ ความรัก และการบังคับตนเองให้แก่เรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 8, 'เหตุฉะนั้นอย่าละอายคําพยานแห่งองค์พระผู้เป็นเจ้าของเรา หรือของตัวข้าพเจ้าที่ถูกจองจําอยู่เพราะเห็นแก่พระองค์ แต่จงมีส่วนในการยากลําบาก เพื่อเห็นแก่ข่าวประเสริฐ โดยอาศัยฤทธิ์เดชแห่งพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 9, 'ผู้ทรงช่วยเราให้รอด และได้ทรงเรียกเราด้วยคําทรงเรียกอันบริสุทธิ์ ไม่ใช่เพราะเห็นแก่การกระทําของเรา แต่เพราะเห็นแก่พระประสงค์ของพระองค์เองและพระคุณซึ่งทรงประทานแก่เราในพระเยซูคริสต์ตั้งแต่ก่อนสร้างโลกมานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 10, 'แต่บัดนี้ได้ทรงสําแดงให้ประจักษ์โดยการที่พระเยซูคริสต์พระผู้ช่วยให้รอดของเราเสด็จมา ผู้ได้ทรงกําจัดความตายให้สูญสิ้น และได้ทรงนําชีวิตและสภาพอมตะให้กระจ่างแจ้งโดยข่าวประเสริฐ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 11, 'สําหรับข่าวประเสริฐนั้น ข้าพเจ้าได้รับแต่งตั้งให้เป็นนักเทศน์และเป็นอัครสาวก และเป็นครูของพวกต่างชาติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 12, 'เพราะเหตุนั้นเองข้าพเจ้าจึงได้ทนทุกข์ลําบากเช่นนี้ ถึงกระนั้นข้าพเจ้าก็ไม่ละอาย เพราะว่าข้าพเจ้ารู้จักพระองค์ที่ข้าพเจ้าได้เชื่อ และข้าพเจ้าเชื่อมั่นว่าพระองค์ทรงฤทธิ์สามารถรักษาซึ่งข้าพเจ้าได้มอบไว้กับพระองค์จนถึงวันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 13, 'จงถือไว้เป็นแบบแห่งคําสอนอันถูกต้องที่ท่านได้ยินจากข้าพเจ้า ในความเชื่อและความรักซึ่งมีอยู่ในพระเยซูคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 14, 'ข้อความอันดีนั้นซึ่งทรงฝากไว้กับท่าน ท่านจงรักษาโดยเดชพระวิญญาณบริสุทธิ์ที่สถิตอยู่ในเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 15, 'ท่านก็ทราบแล้วว่า คนทั้งปวงที่อยู่ในแคว้นเอเชียนั้นต่างก็ผละไปจากข้าพเจ้า ในพวกนั้นมีฟีเจลัสและเฮอร์โมเกเนสรวมอยู่ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 16, 'ขอองค์พระผู้เป็นเจ้าทรงพระเมตตาแก่ครอบครัวของโอเนสิโฟรัสด้วยเถิด เพราะเขาได้กระทําให้ข้าพเจ้าชื่นใจบ่อยๆ และเขาไม่ละอายต่อโซ่ตรวนของข้าพเจ้าเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 17, 'แต่ขณะเมื่อเขาอยู่ในกรุงโรม เขาได้อุตส่าห์สืบหาข้าพเจ้าจนพบข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 18, 'และเขาได้ปรนนิบัติข้าพเจ้าที่เมืองเอเฟซัสมากเพียงใด ท่านก็รู้ดีอยู่แล้ว ขอองค์พระผู้เป็นเจ้าทรงโปรดประทานพระเมตตาขององค์พระผู้เป็นเจ้าแก่เขาในวันนั้นด้วยเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 1, 'เหตุฉะนั้นบุตรของข้าพเจ้าเอ๋ย จงเข้มแข็งขึ้นในพระคุณซึ่งมีอยู่ในพระเยซูคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 2, 'จงมอบคําสอนเหล่านั้นซึ่งท่านได้ยินจากข้าพเจ้าต่อหน้าพยานหลายคนไว้กับคนที่สัตย์ซื่อ ที่สามารถสอนคนอื่นได้ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 3, 'ฉะนั้นท่านจงทนการยากลําบากดุจทหารที่ดีของพระเยซูคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 4, 'ไม่มีทหารคนใด เมื่อเข้าประจําการแล้ว จะไปห่วงใยกับการทํามาหากินของเขาในชีวิตนี้ เพื่อผู้ที่ได้เลือกเขาให้เป็นทหารนั้นจะได้ชอบใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 5, 'และถ้าผู้ใดจะเข้าแข่งขันกัน เขาก็คงมิได้สวมมงกุฎ เว้นเสียแต่เขาได้ปฏิบัติตามกฎ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 6, 'กสิกรผู้ตรากตรําทํางานก็ต้องเป็นคนแรกที่ได้รับผล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 7, 'จงใคร่ครวญถึงสิ่งที่ข้าพเจ้าได้พูดเถิด ด้วยองค์พระผู้เป็นเจ้าจะทรงประทานความเข้าใจให้แก่ท่านในทุกสิ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 8, 'จงระลึกถึงพระเยซูคริสต์ ผู้ทรงสืบเชื้อสายจากดาวิด ได้ทรงถูกชุบให้เป็นขึ้นมาจากความตาย ตามข่าวประเสริฐที่ข้าพเจ้าประกาศนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 9, 'และเพราะเหตุข่าวประเสริฐนั้น ข้าพเจ้าจึงทนทุกข์ ถูกล่ามโซ่ดังผู้ร้าย แต่พระวจนะของพระเจ้านั้นไม่มีผู้ใดเอาโซ่ล่ามไว้ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 10, 'เหตุฉะนั้นข้าพเจ้าจึงยอมทนทุกอย่าง เพราะเห็นแก่ผู้ที่ทรงเลือกสรรไว้นั้น เพื่อเขาจะได้รับความรอดด้วย ซึ่งมีอยู่ในพระเยซูคริสต์ พร้อมทั้งสง่าราศีนิรันดร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 11, 'คํานี้เป็นคําสัตย์จริง คือถ้าเราตายกับพระองค์ เราก็จะมีชีวิตอยู่กับพระองค์เช่นกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 12, 'ถ้าเราทนความทุกข์ทรมาน เราก็จะได้ครองร่วมกับพระองค์ด้วย ถ้าเราปฏิเสธพระองค์ พระองค์ก็จะปฏิเสธเราเช่นเดียวกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 13, 'ถ้าเราไม่เชื่อ พระองค์ก็ยังทรงไว้ซึ่งความสัตย์ซื่อ เพราะพระองค์จะปฏิเสธพระองค์เองไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 14, 'จงเตือนเขาทั้งหลายให้ระลึกถึงข้อความเหล่านี้ และกําชับเขาต่อพระพักตร์องค์พระผู้เป็นเจ้า ไม่ให้เขาโต้เถียงกันในเรื่องถ้อยคํา ซึ่งไม่เป็นประโยชน์เลย แต่กลับเป็นเหตุให้คนที่ฟังเขวไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 15, 'จงหมั่นศึกษาค้นคว้าเพื่อสําแดงตนเองให้เป็นที่ชอบพระทัยพระเจ้า เป็นคนงานที่ไม่ต้องละอาย แยกแยะพระวจนะแห่งความจริงนั้นได้อย่างถูกต้อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 16, 'แต่จงหลีกไปเสียจากถ้อยคําหมิ่นประมาทและไร้ประโยชน์ เพราะคําอย่างนั้นย่อมก่อให้เกิดอธรรมมากยิ่งขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 17, 'และคําพูดของเขาจะแพร่ออกไปเหมือนแผลเนื้อร้าย ในพวกนั้นมีฮีเมเนอัสกับฟิเลทัสเป็นต้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 18, 'คนทั้งสองนั้นได้หลงจากความจริง โดยพูดว่าการฟื้นจากความตายนั้นได้ผ่านพ้นไปแล้ว และได้ทําลายความเชื่อของบางคนเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 19, 'แต่ว่ารากฐานแห่งพระเจ้านั้นอยู่อย่างมั่นคง โดยมีตราประทับไว้ว่า ‘องค์พระผู้เป็นเจ้าทรงรู้จักคนเหล่านั้นที่เป็นของพระองค์’ และ ‘ให้ทุกคนซึ่งออกพระนามของพระคริสต์ละทิ้งความชั่วช้าเสีย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 20, 'แต่ว่าในบ้านใหญ่หลังหนึ่งๆมิได้มีแต่ภาชนะทองและเงินเท่านั้น แต่มีภาชนะไม้และภาชนะดินด้วย บ้างก็มีเกียรติ และบ้างก็ไร้เกียรติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 21, 'เหตุฉะนั้นถ้าผู้ใดชําระตัวให้พ้นจากสิ่งเหล่านี้ เขาก็จะเป็นภาชนะที่มีเกียรติ ซึ่งคัดไว้แล้ว เหมาะที่นายจะใช้ให้เป็นประโยชน์ และถูกเตรียมไว้พร้อมสําหรับการดีทุกอย่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 22, 'จงหลีกหนีเสียจากราคะตัณหาของคนหนุ่ม แต่จงใฝ่ในความชอบธรรม ในความเชื่อ ความรัก และสันติสุข ร่วมกับผู้ที่ออกพระนามขององค์พระผู้เป็นเจ้าด้วยใจบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 23, 'จงหลีกเลี่ยงจากปัญหาอันโง่เขลาและไม่เป็นสาระ ด้วยรู้แล้วว่าปัญหาเหล่านั้นก่อให้เกิดการทะเลาะวิวาทกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 24, 'ฝ่ายผู้รับใช้ขององค์พระผู้เป็นเจ้าต้องไม่เป็นคนที่ชอบการทะเลาะวิวาท แต่ต้องมีใจสุภาพต่อคนทั้งปวง เหมาะที่จะเป็นครูและมีความอดทน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 25, 'ด้วยความอ่อนสุภาพจงสอนคนเหล่านั้นที่ต่อสู้กับตัวเอง บางทีพระเจ้าอาจจะทรงโปรดให้เขากลับใจเสียใหม่มารับความจริง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 26, 'และเขาอาจหลุดพ้นบ่วงของพญามาร ผู้ซึ่งดักจับเขาไว้ให้ทําตามความประสงค์ของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 1, 'แต่จงเข้าใจข้อนี้ด้วย คือว่าในวันสุดท้ายนั้น จะเกิดเหตุการณ์กลียุค');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 2, 'เหตุว่าคนจะเป็นคนรักตัวเอง เป็นคนเห็นแก่เงิน เป็นคนอวดตัว เป็นคนจองหอง เป็นคนพูดหมิ่นประมาท เป็นคนไม่เชื่อฟังคําบิดามารดา เป็นคนอกตัญญู เป็นคนไร้ศีลธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 3, 'เป็นคนไม่รักซึ่งกันและกัน เป็นคนไม่ทําตามสัญญา เป็นคนหาความใส่เขา เป็นคนไม่มีสติรั้งใจ เป็นคนดุร้าย เป็นคนชังคนดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 4, 'เป็นคนทรยศ เป็นคนมุทะลุ เป็นคนหัวสูง เป็นคนรักความสนุกสนานยิ่งกว่ารักพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 5, 'เขามีสภาพทางของพระเจ้าภายนอก แต่ฤทธิ์ของทางนั้นเขาปฏิเสธเสีย คนอย่างนี้ท่านจงผินหน้าหนีจากเขาเสียด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 6, 'เพราะในบรรดาคนเหล่านั้น มีคนที่แอบไปตามบ้าน แล้วนําหญิงที่เบาปัญญาหนาด้วยบาปไปเป็นเชลย แล้วพากันหลงใหลไปด้วยตัณหาต่างๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 7, 'ถึงจะเรียนกันอยู่เสมอ แต่ก็ไม่อาจเรียนรู้ถึงความจริงเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 8, 'แล้วยันเนสกับยัมเบรส์ได้ต่อต้านโมเสสฉันใด คนเหล่านี้ก็ต่อต้านความจริงฉันนั้น เขาเป็นคนใจทราม และในเรื่องความเชื่อนั้นเขาใช้ไม่ได้เลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 9, 'แต่เขาจะก้าวหน้าไปอีกไม่ได้ เพราะความโง่ของเขาจะปรากฏแก่คนทั้งปวง เช่นเดียวกับความโง่ของชายสองคนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 10, 'แต่ท่านก็ประจักษ์ชัดแล้วซึ่งคําสอน การประพฤติ ความมุ่งหมาย ความเชื่อ ความอดทน ความรัก ความเพียร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 11, 'การถูกข่มเหง การทนทุกข์ยากลําบากของข้าพเจ้า ซึ่งได้เกิดขึ้นกับข้าพเจ้า ณ เมืองอันทิโอก เมืองอิโคนียูม และเมืองลิสตรา การกดขี่ข่มเหงที่ข้าพเจ้าได้ทนเอา ถึงกระนั้นก็ดีองค์พระผู้เป็นเจ้าได้ทรงโปรดให้ข้าพเจ้ารอดพ้นจากสิ่งเหล่านั้นทั้งหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 12, 'แท้จริงทุกคนที่ปรารถนาจะดําเนินชีวิตตามทางของพระเจ้าในพระเยซูคริสต์จะถูกกดขี่ข่มเหง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 13, 'แต่คนชั่วและคนเจ้าเล่ห์จะชั่วร้ายมากยิ่งขึ้น ทั้งล่อลวงคนอื่น และก็ถูกคนอื่นล่อลวงด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 14, 'แต่ฝ่ายท่านจงดําเนินต่อไปในสิ่งที่ท่านเรียนรู้แล้ว และได้เชื่ออย่างมั่นคง ท่านก็รู้ว่าท่านได้เรียนมาจากผู้ใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 15, 'และตั้งแต่เด็กมาแล้ว ที่ท่านได้รู้พระคัมภีร์อันบริสุทธิ์ ซึ่งมีฤทธิ์สอนท่านให้ได้ปัญญาถึงความรอดโดยความเชื่อในพระเยซูคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 16, 'พระคัมภีร์ทุกตอนได้รับการดลใจจากพระเจ้า และเป็นประโยชน์ในการสอน การตักเตือนว่ากล่าว การปรับปรุงแก้ไขคนให้ดี และการอบรมในเรื่องความชอบธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 17, 'เพื่อคนของพระเจ้าจะดีรอบคอบ พรักพร้อมที่จะกระทําการดีทุกอย่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 1, 'เหตุฉะนั้นข้าพเจ้ากําชับท่านต่อพระพักตร์พระเจ้า และพระเยซูคริสต์เจ้า ผู้จะทรงพิพากษาคนเป็นและคนตาย เมื่อพระองค์เสด็จมาปรากฏและตั้งอาณาจักรของพระองค์ ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 2, 'จงประกาศพระวจนะ ให้ขะมักเขม้นที่จะทําการทั้งในขณะที่มีโอกาสและไม่มีโอกาส จงว่ากล่าว ห้ามปราม และตักเตือนด้วยความอดทนทุกอย่างและการสั่งสอน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 3, 'เพราะจะถึงเวลาที่คนจะทนต่อคําสอนอันถูกต้องไม่ได้ แต่เขาจะรวบรวมครูไว้ให้สอนในสิ่งที่เขาชอบฟัง ตามความปรารถนาของตนเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 4, 'และเขาจะบ่ายหูจากความจริง หันไปฟังเรื่องนิยายต่างๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 5, 'ฝ่ายท่านจงระวังระไวอยู่ในการทั้งปวง จงอดทนต่อความทุกข์ยากลําบาก จงทําหน้าที่ของผู้ประกาศข่าวประเสริฐ และจงกระทําการรับใช้ของท่านให้สําเร็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 6, 'เพราะว่าบัดนี้ข้าพเจ้าพร้อมที่จะเป็นเครื่องบูชาแล้ว และเวลาที่ข้าพเจ้าจะจากไปนั้นก็ใกล้จะถึงแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 7, 'ข้าพเจ้าได้ต่อสู้อย่างเต็มกําลัง ข้าพเจ้าได้แข่งขันจนถึงที่สุด ข้าพเจ้าได้รักษาความเชื่อไว้แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 8, 'ตั้งแต่นี้ไป มงกุฎแห่งความชอบธรรมก็เตรียมไว้สําหรับข้าพเจ้าแล้ว ซึ่งองค์พระผู้เป็นเจ้า ผู้พิพากษาอันชอบธรรม จะทรงประทานแก่ข้าพเจ้าในวันนั้น และมิใช่แก่ข้าพเจ้าผู้เดียวเท่านั้น แต่จะทรงประทานแก่คนทั้งปวงที่รักการเสด็จมาของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 9, 'จงพยายามมาหาข้าพเจ้าโดยเร็ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 10, 'เพราะว่าเดมาสได้หลงรักโลกปัจจุบันนี้เสียแล้ว และได้ทิ้งข้าพเจ้าไปยังเมืองเธสะโลนิกา เครสเซนส์ได้ไปยังแคว้นกาลาเทีย ทิตัสได้ไปยังเมืองดาลมาเทีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 11, 'ลูกาคนเดียวเท่านั้นที่อยู่กับข้าพเจ้า จงไปตามมาระโกและพาเขามาด้วย เพราะเขาเป็นประโยชน์แก่ข้าพเจ้าสําหรับการรับใช้นี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 12, 'ข้าพเจ้าได้ส่งทีคิกัสไปยังเมืองเอเฟซัสแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 13, 'เมื่อท่านมาจงเอาเสื้อคลุมซึ่งข้าพเจ้าได้ฝากไว้กับคารปัสที่เมืองโตรอัสมาด้วย พร้อมกับหนังสือต่างๆ และสิ่งที่สําคัญที่สุดคือหนังสือที่เขียนบนแผ่นหนัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 14, 'อเล็กซานเดอร์ช่างทองแดงนั้นได้ประทุษร้ายข้าพเจ้าอย่างสาหัส ‘องค์พระผู้เป็นเจ้าจะทรงตอบแทนเขาให้สมกับการกระทําของเขา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 15, 'ท่านจงระวังเขาให้ดีด้วย เพราะเขาได้คัดค้านถ้อยคําของเราอย่างรุนแรง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 16, 'ในการแก้คดีครั้งแรกของข้าพเจ้านั้น ไม่มีใครเข้าข้างข้าพเจ้าสักคนเดียว เขาได้ละทิ้งข้าพเจ้าไปหมด ข้าพเจ้าอธิษฐานต่อพระเจ้าว่า ขอโปรดอย่าให้พวกเขาต้องได้รับโทษเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 17, 'แต่องค์พระผู้เป็นเจ้าทรงประทับอยู่กับข้าพเจ้า และได้ทรงประทานกําลังให้ข้าพเจ้า ข้าพเจ้าจึงประกาศพระวจนะได้อย่างเต็มที่ เพื่อให้คนต่างชาติทั้งปวงได้ยิน ดังนั้นข้าพเจ้าจึงรอดพ้นจากปากสิงโตนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 18, 'องค์พระผู้เป็นเจ้าจะทรงโปรดช่วยข้าพเจ้าให้พ้นจากการร้ายทุกอย่าง และจะทรงคุ้มครองข้าพเจ้าไว้จนถึงอาณาจักรสวรรค์ของพระองค์ สง่าราศีจงมีแด่พระองค์สืบๆไปเป็นนิตย์ เอเมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 19, 'ขอฝากความคิดถึงมายังปริสคากับอาควิลลา และคนในครัวเรือนของโอเนสิโฟรัสด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 20, 'เอรัสทัสยังค้างอยู่ที่เมืองโครินธ์ แต่เมื่อข้าพเจ้าจากโตรฟีมัสที่เมืองมิเลทัสนั้น เขายังป่วยอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 21, 'ท่านจงพยายามมาให้ถึงก่อนฤดูหนาว ยูบูลัส ปูเดนส์ ลีนัส คลาวเดีย และพี่น้องทั้งหลายฝากความคิดถึงมายังท่านด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 22, 'ขอพระเยซูคริสต์เจ้าทรงสถิตอยู่กับจิตวิญญาณของท่าน ขอพระคุณจงดํารงอยู่กับท่านเถิด เอเมน [จดหมายฉบับที่สองถึงทิโมธี ผู้ได้รับการเจิมให้เป็นผู้ดูแลคนแรกแห่งคริสตจักรชาวเอเฟซัส เขียนจากกรุงโรม เมื่อเปาโลถูกพิพากษาต่อหน้าจักรพรรดินีโรเป็นครั้งที่สอง]');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 1, 'เปาโล ผู้รับใช้ของพระเจ้า และอัครสาวกของพระเยซูคริสต์ เนื่องด้วยความเชื่อของผู้ที่พระเจ้าได้ทรงเลือกสรรไว้ และให้รู้จักความจริงตามทางของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 2, 'ด้วยหวังว่าจะได้ชีวิตนิรันดร์ ซึ่งพระเจ้าผู้ไม่สามารถตรัสมุสา ได้ทรงสัญญาไว้ตั้งแต่ก่อนสร้างโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 3, 'แต่ในเวลาที่พระเจ้าทรงกําหนดไว้ ก็ได้ทรงโปรดให้พระวจนะของพระองค์ปรากฏด้วยการเทศนา ซึ่งข้าพเจ้าได้รับมอบไว้ ตามพระบัญญัติของพระเจ้าผู้ทรงช่วยเราทั้งหลายให้รอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 4, 'ถึง ทิตัส ผู้เป็นบุตรแท้ของข้าพเจ้าในความเชื่อเดียวกัน ขอพระคุณ พระเมตตา และสันติสุขจากพระเจ้าพระบิดา และพระเยซูคริสต์เจ้าพระผู้ช่วยให้รอดของเรา จงดํารงอยู่กับท่านเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 5, 'เพราะเหตุนี้เองข้าพเจ้าจึงละท่านไว้ที่เกาะครีต ก็เพื่อท่านจะได้แก้ไขสิ่งที่ยังบกพร่องให้เรียบร้อย และตั้งผู้ปกครองไว้ทุกเมืองตามที่ข้าพเจ้าได้กําชับท่านแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 6, 'คือถ้ามีใครไม่มีข้อตําหนิ เป็นสามีของหญิงคนเดียว มีบุตรสัตย์ซื่อ และไม่มีใครกล่าวหาว่าบุตรนั้นเป็นนักเลงหรือเป็นคนดื้อกระด้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 7, 'เพราะว่าผู้ดูแลนั้น ในฐานะที่เป็นผู้รับมอบฉันทะจากพระเจ้า ต้องเป็นคนที่ไม่มีข้อตําหนิ ไม่เป็นคนเย่อหยิ่ง ไม่เป็นคนเลือดร้อน ไม่เป็นนักเลงสุรา ไม่เป็นนักเลงหัวไม้ และไม่เป็นคนโลภมักได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 8, 'แต่เป็นคนมีอัชฌาสัยรับแขกดี เป็นผู้รักคนดี เป็นคนมีสติสัมปชัญญะ เป็นคนชอบธรรม เป็นคนบริสุทธิ์ รู้จักบังคับใจตนเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 9, 'และเป็นคนยึดมั่นในหลักคําสอนอันสัตย์ซื่อตามที่ได้เรียนมาแล้ว เพื่อเขาจะสามารถเตือนสติด้วยคําสอนอันถูกต้อง และชี้แจงแก่ผู้ที่คัดค้านคําสอนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 10, 'เพราะว่ามีคนเป็นอันมากที่ดื้อกระด้าง พูดมากไม่เป็นสาระ และหลอกลวง โดยเฉพาะบรรดาผู้ที่เข้าสุหนัต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 11, 'จําเป็นต้องให้เขาสงบปากเสีย ด้วยเขาพลิกบ้านคว่ําทั้งครัวเรือนให้เสียไป โดยสอนสิ่งที่ไม่ควรจะสอนเลย เพราะเห็นแก่เล็กแก่น้อย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 12, 'ในพวกเขาเองมีคนหนึ่งเป็นผู้พยากรณ์ได้กล่าวว่า “ชาวครีตเป็นคนพูดปดเสมอ เป็นเหมือนอย่างสัตว์ร้าย เป็นคนเกียจคร้านกินเติบ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 13, 'คําที่เขาอ้างนี้เป็นความจริง เหตุฉะนั้นท่านจงต่อว่าเขาให้แรงๆเพื่อเขาจะได้มีความเชื่ออันถูกต้อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 14, 'และจะมิได้สนใจในนิยายของพวกยิว และในบทบัญญัติของมนุษย์ซึ่งให้หันไปเสียจากความจริง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 15, 'สําหรับคนบริสุทธิ์นั้น ทุกสิ่งก็บริสุทธิ์ แต่สําหรับคนชั่วช้า และคนที่ไม่เชื่อนั้น ก็ไม่มีสิ่งใดบริสุทธิ์เลย แต่จิตใจและจิตสํานึกผิดชอบของเขาก็ชั่วมลทินไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 16, 'เขาออกปากยอมรับว่าเขารู้จักพระเจ้า แต่ว่าในการกระทําของเขา เขาก็ปฏิเสธพระองค์ โดยการประพฤติตัวน่ารังเกียจ และไม่เชื่อฟัง และไม่เหมาะที่จะกระทําการดีใดๆเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 1, 'ฝ่ายท่านจงสั่งสอนให้สอดคล้องกับคําสอนอันถูกต้อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 2, 'พึงสอนชายที่สูงอายุให้รู้จักประมาณตนในการกินดื่ม ให้เอาจริงเอาจัง ให้มีสติสัมปชัญญะ ให้มีความเชื่อ ความรัก และความอดทนอันถูกต้อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 3, 'ส่วนผู้หญิงที่สูงอายุก็เหมือนกัน ให้เขามีการประพฤติอย่างบริสุทธิ์ อย่าให้เป็นคนใส่ความเท็จ ไม่เป็นคนที่สนใจเหล้าองุ่นมาก แต่ให้เป็นผู้สอนสิ่งที่ดีงาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 4, 'เพื่อเขาจะได้ฝึกสอนพวกผู้หญิงสาวๆให้รู้จักประมาณตนในการกินดื่ม ให้รักสามีและรักบุตรของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 5, 'ให้มีสติสัมปชัญญะ เป็นคนบริสุทธิ์ เอาใจใส่ในบ้านเรือน เป็นคนดี และเชื่อฟังสามีของตน เช่นนี้จึงจะไม่มีผู้ใดลบหลู่พระวจนะของพระเจ้าได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 6, 'ส่วนผู้ชายหนุ่มก็เหมือนกัน จงเตือนเขาให้ใช้สติสัมปชัญญะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 7, 'ท่านจงสําแดงตนให้เป็นแบบอย่างในการดีทุกสิ่ง ในคําสอนจงแสดงความสุจริต ให้เอาจริงเอาจัง ให้จริงใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 8, 'และใช้คําพูดอันถูกต้อง ซึ่งไม่มีผู้ใดจะตําหนิได้ เพื่อฝ่ายปฏิปักษ์จะได้อาย ไม่มีสิ่งใดจะติท่านได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 9, 'จงตักเตือนพวกทาสให้เชื่อฟังนายของตน และให้กระทําสิ่งที่ถูกใจนายทุกประการ อย่าให้เถียงเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 10, 'อย่าให้ยักยอก แต่ให้สัตย์ซื่อหมดทุกอย่าง เพื่อว่าในการทั้งปวงนั้น เขาจะได้เทิดเกียรติพระดํารัสสอนของพระเจ้า ผู้ทรงเป็นพระผู้ช่วยให้รอดของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 11, 'เพราะว่าพระคุณของพระเจ้าที่นําไปถึงความรอดได้ปรากฏแก่คนทั้งปวงแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 12, 'สอนให้เราละทิ้งความอธรรมและโลกียตัณหา และดําเนินชีวิตในโลกปัจจุบันนี้อย่างมีสติสัมปชัญญะ อย่างชอบธรรม และตามทางพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 13, 'คอยความหวังอันมีสุข และการปรากฏอันทรงสง่าราศีของพระเจ้าใหญ่ยิ่ง และพระเยซูคริสต์พระผู้ช่วยให้รอดของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 14, 'ผู้ได้ทรงโปรดประทานพระองค์เองให้เรา เพื่อไถ่เราให้พ้นจากความชั่วช้าทุกอย่าง และทรงชําระเราให้บริสุทธิ์ เพื่อให้เป็นหมู่ชนพิเศษเฉพาะของพระองค์ และเป็นคนที่ขวนขวายกระทําการดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 15, 'ข้อความเหล่านี้ ท่านจงใช้พูด ตักเตือน และว่ากล่าวเขาด้วยสิทธิอํานาจทุกอย่าง อย่าให้ผู้ใดประมาทท่านได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 1, 'จงเตือนเขาให้นอบน้อมต่อผู้ปกครองบ้านเมืองและผู้มีอํานาจ ให้เชื่อฟังบรรดาพนักงานฝ่ายปกครอง และพร้อมที่จะปฏิบัติการดีทุกอย่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 2, 'อย่าว่าร้ายผู้ใด อย่าให้เป็นคนมักทะเลาะวิวาทกัน แต่ให้เป็นคนสุภาพ แสดงความอ่อนสุภาพต่อคนทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 3, 'เพราะว่าเมื่อก่อนนั้นบางครั้งเราเองก็โง่เช่นกัน ไม่เชื่อฟัง หลงผิด เป็นทาสของกิเลสตัณหาและการเริงสําราญต่างๆ ใช้ชีวิตอย่างเลวร้าย ริษยา น่าชัง และเกลียดชังกันและกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 4, 'แต่ว่าเมื่อพระเจ้าผู้เป็นพระผู้ช่วยให้รอดของเราทรงพระกรุณาโปรด และประทานความรักแก่มนุษย์ปรากฏแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 5, 'พระองค์ได้ทรงช่วยเราให้รอด มิใช่ด้วยการกระทําที่ชอบธรรมของเราเอง แต่พระองค์ทรงพระกรุณาชําระให้เรามีใจบังเกิดใหม่ และทรงสร้างเราขึ้นมาใหม่โดยพระวิญญาณบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 6, 'พระองค์นั้นได้ทรงประทานแก่เราทั้งหลายอย่างบริบูรณ์ โดยพระเยซูคริสต์พระผู้ช่วยให้รอดของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 7, 'เพื่อว่าเมื่อเราได้เป็นคนชอบธรรมแล้วโดยพระคุณของพระองค์ เราจะได้เป็นผู้ได้รับมรดกที่มุ่งหวังคือชีวิตนิรันดร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 8, 'คํานี้เป็นคําสัตย์จริง ข้าพเจ้าปรารถนาให้ท่านเน้นเรื่องเหล่านี้ เพื่อคนทั้งหลายที่เชื่อในพระเจ้าแล้วจะได้อุตส่าห์กระทําการดี การเหล่านี้ดีและเป็นประโยชน์แก่คนทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 9, 'แต่จงหลีกเสียจากปัญหาโฉดเขลาที่เถียงกัน จากการลําดับวงศ์ตระกูลและการเถียง และการทะเลาะกันเรื่องพระราชบัญญัติ เพราะว่าการอย่างนั้นไร้ประโยชน์และไม่เป็นเรื่องเป็นราว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 10, 'คนใดๆที่ยุให้แตกนิกายกัน เมื่อได้ตักเตือนเขาหนหนึ่งและสองหนแล้ว ก็จงปฏิเสธ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 11, 'ด้วยรู้แล้วว่าคนเช่นนั้นเป็นคนนอกลู่นอกทางและบาปหนา เขาปรับโทษตัวเขาเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 12, 'เมื่อข้าพเจ้าจะใช้อารเทมาสหรือทีคิกัสมาหาท่าน ท่านจงรีบไปหาข้าพเจ้าที่เมืองนิโคบุรี เพราะข้าพเจ้าตั้งใจแล้วว่าจะค้างอยู่ที่นั่นจนสิ้นฤดูหนาว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 13, 'ท่านจงอุตส่าห์ส่งเศนาสผู้เป็นทนายความกับอปอลโลไปตามทางของเขา อย่าให้เขาขาดสิ่งใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 14, 'ให้พวกเราเรียนรู้ที่จะกระทําการดีด้วยสําหรับความจําเป็นต่างๆ เพื่อพวกเขาจะไม่เป็นคนที่ไร้ผล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 15, 'คนทั้งหลายที่อยู่กับข้าพเจ้าฝากความคิดถึงมายังท่าน ขอฝากความคิดถึงมายังคนทั้งปวงที่รักเราในความเชื่อ ขอพระคุณดํารงอยู่กับท่านทั้งหลายเถิด เอเมน [เขียนถึงทิตัส ผู้ได้รับการเจิมให้เป็นผู้ดูแลคนแรกแห่งคริสตจักรชาวครีต จากเมืองนิโคบุรี แคว้นมาซิโดเนีย]');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 1, 'เปาโล ผู้ถูกจองจําเพื่อพระเยซูคริสต์ กับทิโมธีน้องชายของเรา ถึง ฟีเลโมน เพื่อนร่วมงานที่รักของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 2, 'และถึงนางอัปเฟียผู้เป็นที่รัก และอารคิปปัสผู้เป็นเพื่อนทหารด้วยกันกับเรา และถึงคริสตจักรที่อยู่ในบ้านของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 3, 'ขอพระคุณและสันติสุขจากพระเจ้าพระบิดาของเรา และจากพระเยซูคริสต์เจ้า จงดํารงอยู่กับท่านทั้งหลายเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 4, 'ข้าพเจ้าขอบพระคุณพระเจ้าของข้าพเจ้า โดยได้เอ่ยถึงท่านเสมอเมื่อข้าพเจ้าอธิษฐาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 5, 'เพราะข้าพเจ้าได้ยินถึงความรักและความเชื่อของท่านที่มีต่อพระเยซูเจ้าและต่อบรรดาวิสุทธิชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 6, 'เพื่อการเป็นพยานถึงความเชื่อของท่านจะได้เกิดผลโดยการรู้ถึงสิ่งดีทุกอย่าง ซึ่งมีอยู่ในท่านโดยทางพระเยซูคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 7, 'น้องเอ๋ย ความรักของท่านทําให้เรามีความยินดีและความชูใจเป็นอย่างยิ่ง เพราะจิตใจของพวกวิสุทธิชนแช่มชื่นขึ้นเพราะท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 8, 'เหตุฉะนั้น แม้ว่าโดยพระคริสต์ ข้าพเจ้ามีใจกล้าพอที่จะสั่งให้ท่านทําสิ่งที่ควรกระทําได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 9, 'แต่เพราะเห็นแก่ความรัก ข้าพเจ้าขออ้อนวอนท่านดีกว่า คืออ้อนวอนอย่างเปาโล ผู้ชราแล้ว และบัดนี้เป็นผู้ถูกจองจําอยู่ เพราะเห็นแก่พระเยซูคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 10, 'ข้าพเจ้าขออ้อนวอนท่านด้วยเรื่องโอเนสิมัส ลูกของข้าพเจ้าซึ่งข้าพเจ้าได้ให้กําเนิดเมื่อข้าพเจ้าถูกจองจําอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 11, 'เมื่อก่อนนั้นเขาไม่เป็นประโยชน์แก่ท่าน แต่เดี๋ยวนี้เขาเป็นประโยชน์ทั้งแก่ท่านและแก่ข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 12, 'ข้าพเจ้าจึงส่งเขาผู้เป็นดวงจิตของข้าพเจ้าทีเดียวกลับไปหาท่านอีก เหตุฉะนั้นท่านจงรับเขาไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 13, 'ข้าพเจ้าใคร่จะให้เขาอยู่กับข้าพเจ้า เพื่อเขาจะได้ปรนนิบัติข้าพเจ้าแทนท่าน ในระหว่างที่ข้าพเจ้าถูกจองจําเพราะข่าวประเสริฐนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 14, 'แต่ว่าข้าพเจ้าจะไม่ปฏิบัติสิ่งใดลงไปนอกจากท่านจะเห็นชอบด้วย เพื่อว่าคุณความดีที่ท่านกระทํานั้นจะไม่เป็นการฝืนใจ แต่จะเป็นความประสงค์ของท่านเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 15, 'อาจจะเป็นเพราะเหตุนี้ที่ทําให้เขาต้องจากท่านไปชั่วระยะเวลาหนึ่ง เพื่อท่านจะได้เขากลับคืนมาตลอดไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 16, 'บัดนี้เขามิใช่เป็นทาสอีกต่อไป แต่ดียิ่งกว่าทาส คือเป็นพี่น้องที่รัก เขาเป็นที่รักมากของข้าพเจ้า แต่คงจะเป็นที่รักของท่านมากยิ่งกว่านั้นอีก ทั้งในเนื้อหนังและในองค์พระผู้เป็นเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 17, 'เหตุฉะนั้นถ้าท่านถือว่าข้าพเจ้าเป็นเพื่อนร่วมงานของท่าน ก็จงรับเขาไว้เหมือนรับตัวข้าพเจ้าเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 18, 'ถ้าเขาได้กระทําผิดต่อท่านประการใด หรือเป็นหนี้อะไรท่าน ท่านจงคิดเอาจากข้าพเจ้าเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 19, 'ข้าพเจ้า เปาโล ได้เขียนไว้ด้วยมือของข้าพเจ้าเองว่า ข้าพเจ้าจะใช้ให้ ข้าพเจ้าจะไม่อ้างถึงเรื่องที่ท่านเป็นหนี้ข้าพเจ้า และแม้แต่ตัวของท่านเองด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 20, 'แท้จริง น้องเอ๋ย จงให้ข้าพเจ้ามีความยินดีในองค์พระผู้เป็นเจ้าเพราะท่านเถิด จงให้ข้าพเจ้าชื่นใจในองค์พระผู้เป็นเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 21, 'ข้าพเจ้ามั่นใจท่านจะเชื่อฟัง จึงได้เขียนมาถึงท่าน เพราะรู้อยู่ว่าท่านจะกระทํายิ่งกว่าที่ข้าพเจ้าขอเสียอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 22, 'อีกประการหนึ่ง ขอท่านได้จัดเตรียมที่พักไว้สําหรับข้าพเจ้าด้วย เพราะข้าพเจ้าหวังว่าจะมาหาท่านอีกตามคําอธิษฐานของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 23, 'เอปาฟรัส ผู้ซึ่งถูกจองจําอยู่ด้วยกันกับข้าพเจ้าเพื่อพระเยซูคริสต์ ได้ฝากความคิดถึงมายังท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 24, 'มาระโก อาริสทารคัส เดมาส และลูกา ผู้เป็นเพื่อนร่วมงานกับข้าพเจ้า ก็ฝากความคิดถึงมายังท่านด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 25, 'ขอพระคุณของพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเรา จงดํารงอยู่กับจิตวิญญาณของท่านเถิด เอเมน [เขียนจากกรุงโรมถึงฟีเลโมน และส่งโดยโอเนสิมัส ผู้เป็นทาสรับใช้]');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 1, 'ในโบราณกาลพระเจ้าได้ตรัสด้วยวิธีต่างๆมากมายแก่บรรพบุรุษทางพวกศาสดาพยากรณ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 2, 'แต่ในวันสุดท้ายเหล่านี้พระองค์ได้ตรัสแก่เราทั้งหลายทางพระบุตร ผู้ซึ่งพระองค์ได้ทรงตั้งให้เป็นผู้รับสรรพสิ่งทั้งปวงเป็นมรดก พระองค์ได้ทรงสร้างกัลปจักรวาลโดยพระบุตร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 3, 'พระบุตรทรงเป็นแสงสะท้อนสง่าราศีของพระเจ้า และทรงมีสภาวะเป็นพิมพ์เดียวกันกับพระองค์ และทรงผดุงสรรพสิ่งไว้โดยพระดํารัสอันทรงฤทธิ์ของพระองค์ เมื่อพระบุตรได้ทรงชําระบาปของเราด้วยพระองค์เองแล้ว ก็ได้ทรงประทับนั่ง ณ เบื้องขวาพระหัตถ์ของผู้ทรงเดชานุภาพเบื้องบน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 4, 'พระองค์ทรงเป็นผู้เยี่ยมกว่าเหล่าทูตสวรรค์มากนัก ด้วยว่าพระองค์ทรงรับพระนามที่ประเสริฐกว่านามของทูตสวรรค์นั้นเป็นมรดก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 5, 'เพราะว่ามีผู้ใดบ้างในบรรดาทูตสวรรค์ที่พระองค์ได้ตรัสแก่เขาในเวลาใดว่า ‘ท่านเป็นบุตรของเรา วันนี้เราได้ให้กําเนิดแก่ท่านแล้ว’ และยังตรัสอีกว่า ‘เราจะเป็นบิดาของเขา และเขาจะเป็นบุตรของเรา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 6, 'และอีกครั้งหนึ่งเมื่อพระองค์ทรงนําพระบุตรหัวปีองค์ที่ได้บังเกิดนั้นให้เสด็จเข้ามาในโลก พระองค์ก็ตรัสว่า ‘ให้บรรดาพวกทูตสวรรค์ทั้งสิ้นของพระเจ้านมัสการท่าน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 7, 'ส่วนพวกทูตสวรรค์นั้น พระองค์ตรัสว่า ‘พระองค์ทรงบันดาลพวกทูตสวรรค์ของพระองค์ให้เป็นดุจวิญญาณ และทรงบันดาลผู้รับใช้ของพระองค์ให้เป็นดุจเปลวเพลิง’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 8, 'แต่ส่วนพระบุตรนั้น พระองค์ตรัสว่า ‘โอ พระเจ้าข้า พระที่นั่งของพระองค์ดํารงเป็นนิตย์และเป็นนิตย์ ธารพระกรแห่งอาณาจักรของพระองค์ก็เป็นธารพระกรเที่ยงธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 9, 'พระองค์ทรงรักความชอบธรรม และทรงเกลียดชังความชั่วช้า ฉะนั้นพระเจ้า คือ พระเจ้าของพระองค์ ได้ทรงเจิมพระองค์ไว้ด้วยน้ํามันแห่งความยินดียิ่งกว่าพระสหายทั้งปวงของพระองค์’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 10, 'และ ‘องค์พระผู้เป็นเจ้าเจ้าข้า เมื่อเดิมพระองค์ทรงวางรากฐานของแผ่นดินโลก และฟ้าสวรรค์เป็นพระหัตถกิจของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 11, 'สิ่งเหล่านี้จะพินาศไป แต่พระองค์ทรงดํารงอยู่ สิ่งเหล่านี้จะเก่าไปเหมือนเครื่องนุ่งห่ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 12, 'พระองค์จะทรงม้วนสิ่งเหล่านี้ไว้ดุจเสื้อคลุม และสิ่งเหล่านั้นก็จะเปลี่ยนแปลงไป แต่พระองค์ยังทรงเป็นเหมือนเดิม และปีเดือนของพระองค์จะไม่สิ้นสุด’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 13, 'แต่แก่ทูตสวรรค์องค์ใดเล่าที่พระองค์ได้ตรัสในเวลาใดว่า ‘จงนั่งที่ขวามือของเรา จนกว่าเราจะกระทําให้ศัตรูของท่านเป็นแท่นรองเท้าของท่าน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 14, 'ทูตสวรรค์ทั้งปวงเป็นแต่เพียงวิญญาณผู้ปรนนิบัติ ที่พระองค์ทรงส่งไปช่วยเหลือบรรดาผู้ที่จะได้รับความรอดเป็นมรดกมิใช่หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 1, 'เหตุฉะนั้นเราควรจะสนใจในข้อความเหล่านั้นที่เราได้ยินได้ฟังให้มากขึ้นอีก เพราะมิฉะนั้นในเวลาหนึ่งเวลาใดเราจะห่างไกลไปจากข้อความเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 2, 'ด้วยว่าถ้าถ้อยคําซึ่งทูตสวรรค์ได้กล่าวไว้นั้นมั่นคง และการละเมิดกับการไม่เชื่อฟังทุกอย่างได้รับผลตอบสนองตามความยุติธรรมแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 3, 'ดังนั้นถ้าเราละเลยความรอดอันยิ่งใหญ่แล้ว เราจะรอดพ้นไปอย่างไรได้ ความรอดนั้นได้เริ่มขึ้นโดยการประกาศขององค์พระผู้เป็นเจ้าเอง และบรรดาผู้ที่ได้ยินพระองค์ ก็ได้รับรองแก่เราว่าเป็นความจริง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 4, 'ทั้งนี้พระเจ้าก็ทรงเป็นพยานด้วย โดยทรงแสดงหมายสําคัญและการมหัศจรรย์ และโดยการอัศจรรย์ต่างๆ และโดยของประทานจากพระวิญญาณบริสุทธิ์ ซึ่งทรงประทานตามพระประสงค์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 5, 'เพราะว่าพระองค์ไม่ได้ทรงมอบโลกใหม่ซึ่งเรากล่าวถึงนั้นให้อยู่ใต้บังคับของเหล่าทูตสวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 6, 'แต่มีอยู่แห่งหนึ่งที่คนเป็นพยานถึงเรื่องนี้ว่า ‘มนุษย์เป็นผู้ใดเล่าซึ่งพระองค์ทรงระลึกถึงเขา และบุตรมนุษย์เป็นผู้ใดซึ่งพระองค์ทรงเยี่ยมเยียนเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 7, 'พระองค์ทรงทําให้เขาต่ํากว่าพวกทูตสวรรค์แต่หน่อยเดียว และพระองค์ทรงประทานสง่าราศีกับเกียรติเป็นมงกุฎให้แก่เขา และได้ทรงตั้งเขาไว้ให้อยู่เหนือบรรดาพระหัตถกิจของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 8, 'พระองค์ทรงมอบสิ่งทั้งปวงให้อยู่ภายใต้เท้าของเขา’ ในการซึ่งพระองค์ทรงมอบสิ่งทั้งปวงให้อยู่ใต้อํานาจของเขานั้น ไม่มีสิ่งใดเลยที่ไม่อยู่ใต้อํานาจของเขา แต่ขณะนี้ เรายังไม่เห็นว่าทุกสิ่งอยู่ใต้อํานาจของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 9, 'แต่เราก็เห็นพระเยซู ผู้ซึ่งพระองค์ทรงทําให้ต่ํากว่าทูตสวรรค์แต่หน่อยเดียวนั้น ทรงได้รับสง่าราศีและพระเกียรติเป็นมงกุฎ เพราะที่พระองค์ทรงสิ้นพระชนม์ด้วยความทุกข์ทรมาน ทั้งนี้โดยพระคุณของพระเจ้า พระองค์จะได้ทรงชิมความตายเพื่อมนุษย์ทุกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 10, 'ด้วยว่าในการที่พระเจ้าจะทรงพาบุตรเป็นอันมากถึงสง่าราศีนั้น ก็สมอยู่แล้วที่พระองค์ผู้เป็นเจ้าของสิ่งสารพัด และผู้ทรงบันดาลให้สิ่งสารพัดบังเกิดขึ้น จะให้ผู้ที่เป็นนายแห่งความรอดของเขานั้นได้ถึงที่สําเร็จโดยการทนทุกข์ทรมาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 11, 'เพื่อว่าทั้งพระองค์ผู้ชําระคนทั้งหลายให้บริสุทธิ์ และคนเหล่านั้นที่ได้รับการชําระ ก็มาจากแหล่งเดียวกัน เพราะเหตุนั้นพระองค์จึงไม่ทรงละอายที่จะทรงเรียกเขาเหล่านั้นว่า เป็นพี่น้องกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 12, 'ดังที่พระองค์ตรัสว่า ‘เราจะประกาศพระนามของพระองค์แก่พี่น้องของเรา เราจะร้องเพลงสรรเสริญพระองค์ในท่ามกลางที่ชุมนุมชน’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 13, 'และตรัสอีกว่า ‘เราจะไว้วางใจในพระองค์’ ทั้งตรัสอีกว่า ‘ดูเถิด ตัวเรากับบุตรซึ่งพระเจ้าทรงประทานแก่เรา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 14, 'เหตุฉะนั้นครั้นบุตรทั้งหลายมีส่วนในเนื้อและเลือดอยู่แล้ว พระองค์ก็ได้ทรงรับเนื้อและเลือดเหมือนกัน เพื่อโดยความตายพระองค์จะได้ทรงทําลายผู้นั้นที่มีอํานาจแห่งความตาย คือพญามาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 15, 'และจะได้ทรงช่วยเขาเหล่านั้นให้พ้นจากการเป็นทาสชั่วชีวิต เพราะเหตุกลัวความตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 16, 'ความจริง พระองค์มิได้ทรงรับสภาพของทูตสวรรค์ แต่ทรงรับสภาพของเชื้อสายของอับราฮัม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 17, 'เหตุฉะนั้นพระองค์จึงทรงต้องเป็นเหมือนกับพี่น้องทุกอย่าง เพื่อว่าพระองค์จะได้ทรงเป็นมหาปุโรหิต ผู้กอปรด้วยพระเมตตาและความสัตย์ซื่อในการทุกอย่างซึ่งเกี่ยวกับพระเจ้า เพื่อลบล้างบาปทั้งหลายของประชาชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 18, 'เพราะเหตุที่พระองค์ได้ทรงทนทุกข์ทรมานโดยถูกทดลองนั้น พระองค์จึงทรงสามารถช่วยผู้ที่ถูกทดลองนั้นได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 1, 'เหตุฉะนั้นท่านพี่น้องอันบริสุทธิ์ ผู้เข้าส่วนด้วยกันในการทรงเรียกซึ่งมาจากสวรรค์นั้น จงพิจารณาอัครสาวกและมหาปุโรหิตซึ่งเรารับเชื่ออยู่นั้น คือพระเยซูคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 2, 'ผู้ทรงสัตย์ซื่อต่อพระเจ้าผู้ได้ทรงแต่งตั้งพระองค์ไว้ เหมือนอย่างโมเสสได้สัตย์ซื่อในพรรคพวกของพระองค์ทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 3, 'แต่ถึงกระนั้นพระองค์ก็ทรงสมควรได้รับพระเกียรติมากกว่าโมเสสมากนัก เช่นเดียวกับผู้สร้างบ้านย่อมมีเกียรติยศมากกว่าบ้านนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 4, 'ด้วยว่าบ้านทุกหลังต้องมีผู้สร้าง แต่ว่าผู้ทรงสร้างสรรพสิ่งทั้งปวงก็คือพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 5, 'ฝ่ายโมเสสนั้นสัตย์ซื่อในพรรคพวกของพระองค์ทั้งสิ้นก็อย่างคนรับใช้ เพื่อจะได้เป็นพยานถึงเหตุการณ์เหล่านั้นซึ่งจะกล่าวต่อภายหลัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 6, 'แต่พระคริสต์นั้นในฐานะพระบุตรที่ทรงอํานาจเหนือครอบครัวของพระองค์ และเราทั้งหลายเป็นครอบครัวนั้นแหละ หากเราจะยึดความมั่นใจและความชื่นชมยินดีในความหวังนั้นไว้ให้มั่นคงจนถึงที่สุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 7, 'เหตุฉะนั้น (ตามที่พระวิญญาณบริสุทธิ์ตรัสว่า ‘วันนี้ ถ้าท่านทั้งหลายจะฟังพระสุรเสียงของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 8, 'อย่าให้จิตใจของท่านแข็งกระด้างไปอย่างในครั้งกบฏนั้น เหมือนอย่างในวันที่ถูกทดลองในถิ่นทุรกันดาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 9, 'เมื่อบรรพบุรุษของท่านทดลองเราโดยเอาเราเข้าพิสูจน์ และได้เห็นกิจการของเราถึงสี่สิบปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 10, 'เพราะเหตุนั้นเราจึงเคืองคนชั่วอายุนั้น และว่า “ใจของเขาหลงผิดอยู่เสมอ เขาไม่รู้จักทางทั้งหลายของเรา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 11, 'ดังนั้นเราจึงปฏิญาณด้วยความพิโรธของเราว่า “เขาจะไม่ได้เข้าสู่ที่สงบสุขของเรา”’)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 12, 'ท่านพี่น้องทั้งหลาย จงระวังให้ดี เพื่อจะไม่มีผู้หนึ่งผู้ใดในพวกท่านมีใจชั่วและไม่เชื่อ แล้วก็หลงไปจากพระเจ้าผู้ทรงพระชนม์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 13, 'ท่านจงเตือนสติกันและกันทุกวัน ตลอดเวลาที่เรียกว่า “วันนี้” เพื่อว่าจะไม่มีผู้ใดในพวกท่านมีใจแข็งกระด้างไปเพราะเล่ห์กลของบาป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 14, 'เพราะว่าถ้าเรายึดความไว้วางใจที่เรามีอยู่ตอนต้นไว้ให้มั่นคงจนถึงที่สุด เราก็กลายมาเป็นผู้มีส่วนกับพระคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 15, 'เมื่อมีคํากล่าวไว้ว่า ‘วันนี้ ถ้าท่านทั้งหลายจะฟังพระสุรเสียงของพระองค์ อย่าให้จิตใจของท่านแข็งกระด้างไปอย่างในครั้งกบฏนั้น’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 16, 'เพราะบางคน เมื่อเขาได้ยินแล้ว ก็ยังได้กบฏอยู่ แต่มิใช่ทุกคนที่โมเสสได้นําออกจากประเทศอียิปต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 17, 'และใครหนอที่พระองค์ได้ทรงโทมนัสตลอดสี่สิบปีนั้น ก็คนเหล่านั้นที่กระทําบาป และซากศพของเขาทิ้งอยู่ในถิ่นทุรกันดารมิใช่หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 18, 'และแก่ใครหนอที่พระองค์ได้ทรงปฏิญาณว่า เขาจะไม่ได้เข้าสู่ที่สงบสุขของพระองค์ ก็คนเหล่านั้นที่ไม่เชื่อมิใช่หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 19, 'ฉะนั้นเราจึงรู้ว่า เขาไม่สามารถเข้าไปสู่ที่สงบสุขนั้นได้เพราะเขาไม่ได้เชื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 1, 'เหตุฉะนั้น เมื่อมีพระสัญญาทรงประทานไว้แล้วว่า จะให้เข้าในที่สงบสุขของพระองค์ ให้เราทั้งหลายมีความยําเกรงว่า ในพวกท่านอาจจะมีผู้หนึ่งผู้ใดเหมือนไปไม่ถึง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 2, 'เพราะว่าเราได้มีผู้ประกาศข่าวประเสริฐให้แก่เราแล้ว เหมือนแก่เขาเหล่านั้นด้วย แต่ว่าถ้อยคําซึ่งเขาได้ยินนั้นไม่ได้เป็นประโยชน์แก่เขา เพราะว่าเขาไม่มีความเชื่อร่วมกันกับผู้ที่ได้ยิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 3, 'เพราะว่าเราทั้งหลายที่เชื่อแล้วก็เข้าในที่สงบสุขนั้น เหมือนพระองค์ได้ตรัสไว้แล้วว่า ‘ตามที่เราได้ปฏิญาณด้วยความพิโรธของเราว่า “ถ้าเขาจะเข้าสู่ที่สงบสุขของเรา”’ แม้ว่างานนั้นสําเร็จแล้วตั้งแต่วางรากสร้างโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 4, 'และมีข้อหนึ่งที่พระองค์ได้ตรัสถึงวันที่เจ็ดดังนี้ว่า ‘ในวันที่เจ็ดพระเจ้าทรงพักการงานทั้งสิ้นของพระองค์’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 5, 'และแห่งเดียวกันนั้นได้ตรัสอีกว่า ‘ถ้าเขาจะเข้าสู่ที่สงบสุขของเรา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 6, 'ครั้นเห็นแล้วว่ายังมีช่องให้บางคนเข้าในที่สงบสุขนั้น และคนเหล่านั้นที่ได้ยินข่าวประเสริฐคราวก่อนไม่ได้เข้าเพราะเขาไม่เชื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 7, 'พระองค์จึงได้ทรงกําหนดวันหนึ่งไว้อีก คือกล่าวในคัมภีร์ของดาวิดซึ่งล่วงไปช้านานแล้วว่า “วันนี้” เหมือนตรัสเมื่อคราวก่อนแล้วว่า ‘วันนี้ ถ้าท่านทั้งหลายจะฟังพระสุรเสียงของพระองค์ อย่าให้จิตใจของท่านแข็งกระด้างไป’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 8, 'เพราะว่าถ้าเยซูได้พาเขาเข้าสู่ที่สงบสุขนั้นแล้ว พระองค์ก็คงมิได้ตรัสในภายหลังถึงวันอื่นอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 9, 'ฉะนั้นจึงยังมีสะบาโตสําหรับชนชาติของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 10, 'ด้วยว่าคนใดที่ได้เข้าไปในที่สงบสุขของตนแล้ว ก็ได้หยุดการงานของตน เหมือนพระเจ้าได้ทรงหยุดจากพระราชกิจของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 11, 'เหตุฉะนั้นให้เราทั้งหลายอุตส่าห์เข้าในที่สงบสุขนั้น เพื่อมิให้ผู้หนึ่งผู้ใดล้มลงไปในการไม่เชื่อเช่นเขาเหล่านั้นซึ่งเป็นตัวอย่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 12, 'เพราะว่าพระวจนะของพระเจ้านั้นมีชีวิต และทรงพลานุภาพอยู่เสมอ คมยิ่งกว่าดาบสองคมใดๆ แทงทะลุกระทั่งจิตและวิญญาณ ตลอดข้อกระดูกและไขในกระดูก และสามารถวินิจฉัยความคิดและความมุ่งหมายในใจด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 13, 'ไม่มีสิ่งเนรมิตสร้างใดๆ ที่ไม่ได้ปรากฏในสายพระเนตรของพระองค์ แต่สิ่งสารพัดก็เปลือยเปล่าและปรากฏแจ้งต่อพระเนตรของพระองค์ผู้ซึ่งเราต้องเกี่ยวข้องด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 14, 'เหตุฉะนั้นเมื่อเรามีมหาปุโรหิตผู้เป็นใหญ่ที่ผ่านฟ้าสวรรค์ไปแล้ว คือพระเยซูพระบุตรของพระเจ้า ขอให้เราทั้งหลายมั่นคงในการยอมรับของเราไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 15, 'เพราะว่าเรามิได้มีมหาปุโรหิตที่ไม่สามารถจะเห็นใจในความอ่อนแอของเรา แต่ได้ทรงถูกทดลองเหมือนอย่างเราทุกประการ ถึงกระนั้นพระองค์ก็ยังปราศจากบาป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 16, 'ฉะนั้นขอให้เราทั้งหลายจงมีใจกล้าเข้ามาถึงพระที่นั่งแห่งพระคุณ เพื่อเราจะได้รับพระเมตตา และจะได้พบพระคุณที่จะช่วยเราในขณะที่ต้องการ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 1, 'ฝ่ายมหาปุโรหิตทุกคนที่เลือกมาจากมนุษย์ได้แต่งตั้งไว้ให้สําหรับมนุษย์ในบรรดาการซึ่งเกี่ยวกับพระเจ้า เพื่อท่านจะได้นําเครื่องบรรณาการและเครื่องบูชามาถวายเพราะความบาป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 2, 'ท่านนั้นมีใจเมตตากรุณาคนโง่และคนหลงผิดได้ เพราะท่านเองก็มีความอ่อนกําลังอยู่รอบตัวด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 3, 'เหตุฉะนั้นท่านต้องถวายเครื่องบูชาเพราะความบาปเพื่อคนทั้งปวงฉันใด ท่านจึงต้องถวายเพื่อตัวเองด้วยฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 4, 'และไม่มีผู้ใดตั้งตนเองสําหรับเกียรตินี้ได้ เว้นแต่พระเจ้าทรงเรียกเหมือนอย่างทรงเรียกอาโรน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 5, 'ในทํานองเดียวกัน พระคริสต์ก็ไม่ได้ทรงยกย่องพระองค์เองขึ้นเป็นมหาปุโรหิต แต่เป็นโดยพระเจ้า ผู้ได้ตรัสกับพระองค์ว่า ‘ท่านเป็นบุตรของเรา วันนี้เราได้ให้กําเนิดแก่ท่านแล้ว’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 6, 'เหมือนพระองค์ได้ตรัสอีกแห่งหนึ่งว่า ‘ท่านเป็นปุโรหิตเป็นนิตย์ตามอย่างของเมลคีเซเดค’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 7, 'ฝ่ายพระเยซู ขณะเมื่อพระองค์ดํารงอยู่ในเนื้อหนังนั้น พระองค์ได้ถวายคําอธิษฐาน และทูลวิงวอนด้วยทรงกันแสงมากมายและน้ําพระเนตรไหล ต่อพระเจ้าผู้ทรงสามารถช่วยพระองค์ให้พ้นจากความตายได้ และพระเจ้าได้ทรงสดับเพราะพระองค์นั้นได้ยําเกรง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 8, 'ถึงแม้ว่าพระองค์ทรงเป็นพระบุตร พระองค์ก็ทรงเรียนรู้ที่จะนอบน้อมยอมเชื่อฟัง โดยความทุกข์ลําบากที่พระองค์ได้ทรงทนเอา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 9, 'และเมื่อทรงถูกทําให้เพียบพร้อมทุกประการแล้ว พระองค์ก็ทรงกลายเป็นผู้จัดความรอดนิรันดร์สําหรับคนทั้งปวงที่เชื่อฟังพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 10, 'โดยพระเจ้าได้ทรงตั้งพระองค์ให้เป็นมหาปุโรหิตตามอย่างของเมลคีเซเดค');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 11, 'เรื่องเกี่ยวกับพระองค์นั้นมีมากและยากที่จะอธิบายให้เข้าใจได้ เพราะว่าท่านทั้งหลายกลายเป็นคนหูตึงเสียแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 12, 'ถึงแม้ว่าขณะนี้ท่านทั้งหลายควรจะเป็นครูได้แล้ว แต่ท่านก็ต้องให้คนอื่นสอนท่านอีกในเรื่องหลักเบื้องต้นแห่งพระวจนะของพระเจ้า และท่านทั้งหลายกลายเป็นคนที่ยังต้องกินน้ํานม ไม่ใช่อาหารแข็ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 13, 'เพราะว่าทุกคนที่ยังกินน้ํานมนั้นก็ยังไม่ชํานาญในพระวจนะแห่งความชอบธรรม เพราะเขายังเป็นทารกอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 14, 'แต่อาหารแข็งนั้นเป็นอาหารสําหรับผู้ใหญ่ คือผู้ที่เคยฝึกหัดความคิดของเขาจนสังเกตได้ว่าไหนดีไหนชั่ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 1, 'เหตุฉะนั้นให้เราละประถมโอวาทของพระคริสต์ไว้ และให้เราก้าวหน้าไปถึงความบริบูรณ์ อย่าเอาสิ่งเหล่านี้มาวางเป็นรากอีกเลย คือการกลับใจเสียใหม่จากการกระทําที่ตายแล้ว และความเชื่อในพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 2, 'และคําสอนว่าด้วยพิธีบัพติศมา และการวางมือ และการเป็นขึ้นมาจากตาย และการพิพากษาลงโทษเป็นนิตย์นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 3, 'ถ้าพระเจ้าจะทรงโปรดอนุญาต เราก็จะกระทําอย่างนี้ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 4, 'เพราะว่าคนเหล่านั้นที่ได้รับความสว่างมาครั้งหนึ่งแล้ว และได้รู้รสของประทานจากสวรรค์ ได้มีส่วนในพระวิญญาณบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 5, 'และได้ชิมความดีงามแห่งพระวจนะของพระเจ้า และฤทธิ์เดชแห่งยุคที่จะมานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 6, 'ถ้าเขาเหล่านั้นจะหลงอยู่อย่างนี้ ก็เหลือวิสัยที่จะให้เขากลับใจเสียใหม่อีกได้ เพราะตัวเขาเองได้ตรึงพระบุตรของพระเจ้าเสียอีกแล้ว และได้ทําให้พระองค์ขายหน้าต่อธารกํานัล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 7, 'ด้วยว่าพื้นแผ่นดินที่ได้ดูดดื่มน้ําฝนที่ตกลงมาเนืองๆและงอกขึ้นมาเป็นต้นผักให้ประโยชน์แก่คนทั้งหลายที่ได้พรวนดินด้วยนั้น ก็รับพระพรมาจากพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 8, 'แต่ดินที่งอกหนามใหญ่และหนามย่อยก็ถูกทอดทิ้ง และเกือบจะถึงที่สาปแช่งแล้ว ซึ่งในที่สุดก็จะถูกเผาไฟเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 9, 'แต่ดูก่อนพวกที่รัก แม้เราพูดอย่างนั้น เราก็เชื่อแน่ว่าท่านทั้งหลายคงจะได้สิ่งที่ดีกว่านั้น และสิ่งซึ่งเกี่ยวกับความรอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 10, 'เพราะว่าพระเจ้าไม่ทรงอธรรมที่จะทรงลืมการงานและการทํางานหนักด้วยความรักซึ่งท่านได้แสดงต่อพระนามของพระองค์ คือการรับใช้วิสุทธิชนนั้นและยังรับใช้อยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 11, 'และเราปรารถนาให้ท่านทั้งหลายทุกคนแสดงความตั้งใจจริงให้ถึงความมั่นใจอย่างเต็มที่แห่งความหวังนั้นจนถึงที่สุดปลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 12, 'เพื่อท่านจะไม่เป็นคนเฉื่อยช้า แต่ให้ตามเยี่ยงอย่างแห่งคนเหล่านั้นที่อาศัยความเชื่อและความเพียร จึงได้รับตามพระสัญญาเป็นมรดก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 13, 'เพราะว่าเมื่อพระเจ้าได้ทรงทําพระสัญญาไว้กับอับราฮัมนั้น โดยเหตุที่ไม่มีใครเป็นใหญ่กว่าพระองค์ที่พระองค์จะทรงให้คําปฏิญาณได้นั้น พระองค์ก็ได้ทรงให้คําปฏิญาณแก่พระองค์เอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 14, 'คือตรัสว่า ‘เราจะอวยพรท่านแน่ เราจะทวีเชื้อสายของท่านให้มากขึ้น’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 15, 'เช่นนั้นแหละ เมื่ออับราฮัมได้ทนคอยด้วยความเพียรแล้ว ท่านก็ได้รับตามพระสัญญานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 16, 'ส่วนมนุษย์นั้นต้องสาบานต่อหน้าผู้ที่เป็นใหญ่กว่าตน และเมื่อเกิดข้อทุ่มเถียงอะไรกันขึ้น ก็ต้องถือคําสาบานนั้นเป็นคํายืนยันขั้นเด็ดขาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 17, 'ฝ่ายพระเจ้าเมื่อพระองค์ทรงหมายพระทัยจะสําแดงให้ผู้ที่รับคําทรงสัญญานั้นเป็นมรดกรู้ให้แน่ใจยิ่งขึ้นว่า พระดําริของพระองค์จะแปรปรวนไม่ได้ พระองค์จึงได้ทรงให้คําปฏิญาณไว้ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 18, 'เพื่อด้วยสองประการนั้นที่เปลี่ยนแปลงไม่ได้ ในที่ซึ่งพระองค์จะตรัสมุสาไม่ได้นั้น เราซึ่งได้หนีมาหาที่ลี้ภัยนั้นจึงจะได้รับการหนุนน้ําใจอย่างจริงจัง ที่จะฉวยเอาความหวังซึ่งมีอยู่ตรงหน้าเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 19, 'ความหวังนั้นเรายึดไว้ต่างสมอของจิตวิญญาณ เป็นความหวังทั้งแน่และมั่นคง และได้ทอดไว้ภายในม่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 20, 'ที่ผู้นําหน้าได้เสด็จเข้าไปเผื่อเราแล้ว คือพระเยซูผู้ทรงได้รับการแต่งตั้งเป็นมหาปุโรหิตเป็นนิตย์ตามอย่างเมลคีเซเดค');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 1, 'เพราะเมลคีเซเดคผู้นี้คือกษัตริย์เมืองซาเล็ม เป็นปุโรหิตของพระเจ้าผู้สูงสุด ผู้ได้พบอับราฮัมขณะที่กําลังกลับมาจากการฆ่าฟันกษัตริย์ทั้งหลาย และได้อวยพรแก่อับราฮัม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 2, 'อับราฮัมก็ได้ถวายของหนึ่งในสิบจากของทั้งปวงแก่ท่านผู้นี้ ตอนแรกท่านผู้นี้แปลว่ากษัตริย์แห่งความชอบธรรม แล้วหลังจากนั้นก็แปลว่ากษัตริย์เมืองซาเล็มด้วย ซึ่งหมายถึงกษัตริย์แห่งสันติสุข');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 3, 'บิดามารดาและตระกูลของท่านก็ไม่มี วันเริ่มต้นและวันสิ้นสุดของชีวิตก็ไม่มีเช่นกัน แต่เป็นเหมือนพระบุตรของพระเจ้า ซึ่งดํารงตําแหน่งปุโรหิตอยู่ตลอดเวลา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 4, 'แล้วจงคิดดูเถิดว่า ท่านผู้นี้ยิ่งใหญ่เพียงไร ซึ่งแม้แต่อับราฮัมผู้เป็นต้นตระกูลของเรานั้นยังได้ชักหนึ่งในสิบจากของริบนั้นมาถวายแก่ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 5, 'และแท้จริงบรรดาบุตรของเลวี ซึ่งได้รับตําแหน่งปุโรหิตนั้น ถึงแม้ว่าท่านเหล่านั้นได้บังเกิดจากเอวของอับราฮัม ก็ยังมีพระบัญชาสั่งให้รับสิบชักหนึ่งจากประชาชนตามพระราชบัญญัติ คือจากพวกพี่น้องของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 6, 'แต่ท่านผู้นี้ไม่ใช่เชื้อสายพวกเขา แต่ก็ยังได้รับสิบชักหนึ่งจากอับราฮัม และได้อวยพรให้อับราฮัมผู้ที่ได้รับพระสัญญาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 7, 'สิ่งที่ค้านไม่ได้ คือผู้น้อยต้องรับพรจากผู้ใหญ่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 8, 'ฝ่ายข้างนี้มนุษย์ที่ต้องตายยังได้รับสิบชักหนึ่ง แต่ฝ่ายข้างโน้นท่านผู้เดียวได้รับ และมีพยานกล่าวถึงท่านว่าท่านยังมีชีวิตอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 9, 'ถ้าจะพูดไปอีกอย่างหนึ่งก็ว่า เลวีนั้นที่รับสิบชักหนึ่งก็ยังได้ถวายสิบชักหนึ่งทางอับราฮัม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 10, 'เพราะว่าขณะนั้นเขายังอยู่ในเอวของบรรพบุรุษ ขณะที่เมลคีเซเดคได้พบกับอับราฮัม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 11, 'เหตุฉะนั้นถ้าเมื่อจะถึงความสําเร็จได้ในทางตําแหน่งปุโรหิตที่สืบมาจากตระกูลเลวี (ด้วยว่าประชาชนได้รับพระราชบัญญัติโดยทางตําแหน่งนี้) ที่ไหนจะต้องการให้มีปุโรหิตอีกตามอย่างเมลคีเซเดคเล่า ซึ่งมิได้เรียกตามอย่างอาโรน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 12, 'เพราะเมื่อตําแหน่งปุโรหิตเปลี่ยนแปลงไปแล้ว พระราชบัญญัติก็จําเป็นจะต้องเปลี่ยนแปลงไปด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 13, 'เพราะว่าท่านที่เรากล่าวถึงนั้นมาจากตระกูลอื่น ซึ่งเป็นตระกูลที่ยังไม่มีผู้ใดเคยทําหน้าที่ปรนนิบัติที่แท่นบูชาเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 14, 'เพราะเป็นที่ประจักษ์ชัดแล้วว่า องค์พระผู้เป็นเจ้าของเรานั้นได้ทรงสืบเชื้อสายมาจากตระกูลยูดาห์ โมเสสไม่ได้ว่าจะมีปุโรหิตมาจากตระกูลนั้นเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 15, 'และข้อนี้ประจักษ์ชัดยิ่งขึ้นอีก เมื่อปรากฏว่ามีปุโรหิตอีกผู้หนึ่งเกิดขึ้นตามอย่างของเมลคีเซเดค');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 16, 'ซึ่งไม่ได้ทรงตั้งขึ้นตามพระราชบัญญัติซึ่งเป็นบทบัญญัติสําหรับเนื้อหนัง แต่ตามฤทธิ์เดชแห่งชีวิตอันไม่รู้สิ้นสุดเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 17, 'เพราะมีพยานกล่าวถึงท่านว่า ‘ท่านเป็นปุโรหิตเป็นนิตย์ตามอย่างของเมลคีเซเดค’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 18, 'ด้วยว่าจริงๆแล้วพระบัญญัติที่มีอยู่เดิมนั้น ก็ได้ยกเลิกไป เพราะขาดฤทธิ์และไร้ประโยชน์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 19, 'เพราะว่าพระราชบัญญัตินั้นไม่ได้ทําอะไรให้ถึงความสําเร็จ แต่ได้นําความหวังอันดีกว่าเข้ามา และโดยความหวังนั้นเราทั้งหลายจึงเข้ามาใกล้พระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 20, 'ที่ว่าดีกว่านั้นก็เพราะว่า ปุโรหิตคนนั้นได้ทรงตั้งขึ้นโดยทรงปฏิญาณไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 21, '(บรรดาปุโรหิตเหล่านั้นไม่มีการกล่าวปฏิญาณเมื่อเขาเข้ารับตําแหน่ง แต่ส่วนปุโรหิตนี้มีคํากล่าวปฏิญาณจากพระองค์ว่า ‘องค์พระผู้เป็นเจ้าทรงปฏิญาณแล้ว และจะไม่เปลี่ยนพระทัยของพระองค์ว่า “ท่านเป็นปุโรหิตเป็นนิตย์ตามอย่างของเมลคีเซเดค”’)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 22, 'พระเยซูก็ได้ทรงเป็นผู้รับประกันแห่งพันธสัญญาอันดีกว่าสักเพียงใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 23, 'แท้จริงส่วนปุโรหิตเหล่านั้นก็ได้ทรงตั้งขึ้นไว้หลายคน เพราะว่าความตายได้ขัดขวางไม่ให้ดํารงอยู่ในตําแหน่งเรื่อยไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 24, 'แต่ฝ่ายพระองค์นี้ โดยเหตุที่พระองค์ดํารงอยู่เป็นนิตย์ ตําแหน่งปุโรหิตของพระองค์จึงไม่แปรปรวน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 25, 'ด้วยเหตุนี้ พระองค์จึงทรงสามารถเป็นนิตย์ที่จะช่วยคนทั้งปวงที่ได้เข้ามาถึงพระเจ้าโดยทางพระองค์นั้นให้ได้รับความรอด เพราะว่าพระองค์ทรงพระชนม์อยู่เป็นนิตย์เพื่อเสนอความให้คนเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 26, 'มหาปุโรหิตเช่นนี้แหละที่เหมาะสําหรับเรา คือเป็นผู้บริสุทธิ์ ปราศจากอุบาย ไร้มลทิน แยกจากคนบาปทั้งปวง ประทับอยู่สูงกว่าฟ้าสวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 27, 'พระองค์ไม่ต้องทรงนําเครื่องบูชามาทุกวันๆดังเช่นมหาปุโรหิตอื่นๆ ผู้ซึ่งถวายสําหรับความผิดของตัวเองก่อน แล้วจึงถวายสําหรับความผิดของประชาชน ส่วนพระองค์ได้ทรงถวายเครื่องบูชาเพียงครั้งเดียว คือเมื่อพระองค์ได้ทรงถวายพระองค์เอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 28, 'ด้วยว่าพระราชบัญญัตินั้นได้แต่งตั้งมนุษย์ที่อ่อนกําลังขึ้นเป็นมหาปุโรหิต แต่คําทรงปฏิญาณนั้นซึ่งมาภายหลังพระราชบัญญัติ ได้ทรงแต่งตั้งพระบุตรขึ้น ผู้ถึงความสําเร็จเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 1, 'บัดนี้ ในเรื่องที่เราพูดมาแล้วนั้น ข้อสรุปนั้นคือว่า เรามีมหาปุโรหิตอย่างนี้เอง ผู้ได้ประทับเบื้องขวาพระที่นั่งแห่งผู้ทรงเดชานุภาพในฟ้าสวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 2, 'เป็นผู้ปฏิบัติกิจในสถานบริสุทธิ์ และในพลับพลาแท้ซึ่งองค์พระผู้เป็นเจ้าได้ทรงตั้งไว้ ไม่ใช่มนุษย์ตั้ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 3, 'เพราะว่าทรงตั้งมหาปุโรหิตทุกคนขึ้นเพื่อให้ถวายของกํานัลและเครื่องบูชา ด้วยเหตุนี้จึงจําเป็นที่มหาปุโรหิตผู้นี้ต้องมีสิ่งหนึ่งสิ่งใดถวายด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 4, 'เพราะถ้าพระองค์ทรงอยู่ในโลก พระองค์ก็จะไม่ได้ทรงเป็นปุโรหิต เพราะว่ามีปุโรหิตที่ถวายของกํานัลตามพระราชบัญญัติอยู่แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 5, 'ปุโรหิตเหล่านั้นปฏิบัติตามแบบและเงาแห่งสิ่งเหล่านั้นที่อยู่ในสวรรค์ เหมือนพระเจ้าได้ทรงสั่งแก่โมเสสครั้นเมื่อท่านจะสร้างพลับพลานั้นว่า ‘ดูเถิด จงทําทุกสิ่งตามแบบอย่างที่เราแจ้งแก่ท่านบนภูเขา’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 6, 'แต่ว่าพระองค์ได้ทรงเป็นคนกลางแห่งพันธสัญญาอันประเสริฐกว่าเก่า เพราะได้ทรงตั้งขึ้นโดยพระสัญญาอันดีกว่าเก่าเท่าใด บัดนี้พระองค์ก็ได้ตําแหน่งอันเลิศกว่าเก่าเท่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 7, 'เพราะว่าถ้าพันธสัญญาเดิมนั้นไม่มีข้อบกพร่องแล้ว ก็ไม่จําเป็นที่จะต้องมีพันธสัญญาที่สองอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 8, 'ด้วยว่าพระเจ้าตรัสติเขาว่า ‘องค์พระผู้เป็นเจ้าตรัสว่า “ดูเถิด วันเวลาจะมาถึง ซึ่งเราจะทําพันธสัญญาใหม่กับวงศ์วานอิสราเอล และวงศ์วานยูดาห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 9, 'ไม่เหมือนกับพันธสัญญาซึ่งเราได้กระทํากับบรรพบุรุษของเขาทั้งหลาย เมื่อเราจูงมือเขาเพื่อนําเขาออกจากแผ่นดินอียิปต์ เพราะว่าเขาเหล่านั้นไม่ได้ยึดมั่นอยู่ในพันธสัญญาของเราอีกต่อไปแล้ว เราจึงได้ละเขาไว้” องค์พระผู้เป็นเจ้าตรัสดังนี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 10, '“นี่คือพันธสัญญาซึ่งเราจะกระทํากับวงศ์วานอิสราเอลภายหลังสมัยนั้น” องค์พระผู้เป็นเจ้าตรัส “เราจะบรรจุราชบัญญัติของเราไว้ในจิตใจของเขาทั้งหลาย และจะจารึกมันไว้ที่ในดวงใจของเขาทั้งหลาย และเราจะเป็นพระเจ้าของเขา และเขาจะเป็นประชาชนของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 11, 'และทุกคนจะไม่สอนเพื่อนบ้านของตนและพี่น้องของตนแต่ละคนอีกว่า ‘จงรู้จักองค์พระผู้เป็นเจ้า’ เพราะเขาทั้งหลายจะรู้จักเราหมด ตั้งแต่คนต่ําต้อยที่สุดถึงคนใหญ่โตที่สุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 12, 'เพราะเราจะกรุณาต่อการอธรรมของเขา และจะไม่จดจําบาปและความชั่วช้าของเขาอีกต่อไป”’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 13, 'เมื่อพระองค์ตรัสถึง “พันธสัญญาใหม่” พระองค์ทรงถือว่า พันธสัญญาเดิมนั้นพ้นสมัยไปแล้ว และสิ่งที่พ้นสมัยและเก่าไปแล้วนั้น ก็พร้อมที่จะเสื่อมสูญไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 1, 'แท้จริงถึงแม้พันธสัญญาเดิมนั้นก็ยังได้มีกฎสําหรับการปรนนิบัติในพิธีนมัสการ และได้มีสถานอันบริสุทธิ์สําหรับโลกนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 2, 'เพราะว่าได้มีพลับพลาสร้างขึ้นตกแต่งเสร็จแล้ว คือห้องชั้นนอก ซึ่งมีคันประทีป โต๊ะ และขนมปังหน้าพระพักตร์ ห้องนี้เรียกว่าที่บริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 3, 'และภายในม่านชั้นที่สองมีห้องพลับพลาซึ่งเรียกว่า ที่บริสุทธิ์ที่สุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 4, 'ห้องนั้นมีแท่นทองคําสําหรับถวายเครื่องหอม และมีหีบพันธสัญญาหุ้มด้วยทองคําทุกด้าน ในหีบนั้นมีโถทองคําใส่มานา และมีไม้เท้าของอาโรนที่ออกช่อ และมีแผ่นศิลาพันธสัญญา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 5, 'และเหนือหีบนั้นมีรูปเครูบแห่งสง่าราศีคลุมพระที่นั่งกรุณานั้น สิ่งเหล่านี้เราจะพรรณนาให้ละเอียดในที่นี้ไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 6, 'แล้วเมื่อจัดตั้งสิ่งเหล่านี้ไว้อย่างนั้นแล้ว พวกปุโรหิตก็เข้าไปในพลับพลาห้องที่หนึ่งทุกครั้งที่ปรนนิบัติพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 7, 'แต่ในห้องที่สองนั้นมีมหาปุโรหิตผู้เดียวเท่านั้นที่เข้าไปได้ปีละครั้ง และต้องนําเลือดเข้าไปถวายเพื่อตัวเอง และเพื่อความผิดของประชาชนด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 8, 'อย่างนั้นแหละ พระวิญญาณบริสุทธิ์ได้ทรงสําแดงว่า ทางซึ่งจะเข้าไปในที่บริสุทธิ์ที่สุดนั้นไม่ได้ปรากฏแจ้ง คราวเมื่อพลับพลาเดิมยังตั้งอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 9, 'พลับพลาเดิมเป็นเครื่องเปรียบสําหรับในเวลานั้น คือมีการถวายของให้และเครื่องบูชา ซึ่งจะกระทําให้ใจวินิจฉัยผิดและชอบของผู้ถวายนั้นถึงที่สําเร็จไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 10, 'ซึ่งเป็นแต่เพียงของกินของดื่ม และพิธีชําระล้างต่างๆ และเป็นพิธีสําหรับเนื้อหนังที่ได้บัญญัติไว้จนกว่าจะถึงเวลาที่จะต้องเปลี่ยนแปลงใหม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 11, 'แต่เมื่อพระคริสต์ได้เสด็จมาเป็นมหาปุโรหิตแห่งสิ่งประเสริฐซึ่งจะมาถึงโดยทางพลับพลาอันใหญ่ยิ่งกว่าและสมบูรณ์ยิ่งกว่าแต่ก่อน ที่ไม่ได้สร้างขึ้นด้วยมือ และพูดได้ว่ามิได้เป็นอย่างของโลกนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 12, 'พระองค์เสด็จเข้าไปในที่บริสุทธิ์เพียงครั้งเดียวเท่านั้น และพระองค์ไม่ได้ทรงนําเลือดแพะและเลือดลูกวัวเข้าไป แต่ทรงนําพระโลหิตของพระองค์เองเข้าไป และทรงสําเร็จการไถ่บาปชั่วนิรันดร์แก่เรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 13, 'เพราะถ้าเลือดวัวตัวผู้และเลือดแพะ และเถ้าของลูกโคตัวเมีย ที่ประพรมลงบนคนบาป สามารถชําระเนื้อหนังให้บริสุทธิ์ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 14, 'มากยิ่งกว่านั้นสักเท่าไรพระโลหิตของพระคริสต์ โดยพระวิญญาณนิรันดร์ได้ทรงถวายพระองค์เองแด่พระเจ้าเป็นเครื่องบูชาอันปราศจากตําหนิ จะได้ทรงชําระใจวินิจฉัยผิดและชอบของท่านทั้งหลายให้พ้นจากการกระทําที่ตายแล้ว เพื่อจะได้ปฏิบัติพระเจ้าผู้ทรงพระชนม์อยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 15, 'เพราะเหตุนี้พระองค์จึงทรงเป็นคนกลางแห่งพันธสัญญาใหม่ เพื่อเมื่อมีผู้หนึ่งตายสําหรับที่จะไถ่การละเมิดของคนที่ได้ละเมิดต่อพันธสัญญาเดิมนั้นแล้ว คนทั้งหลายที่ถูกเรียกแล้วนั้นจะได้รับมรดกอันนิรันดร์ตามพระสัญญา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 16, 'เพราะว่าในกรณีที่เกี่ยวกับหนังสือพินัยกรรม ผู้ทําหนังสือนั้นก็ต้องถึงแก่ความตายแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 17, 'เพราะว่าเมื่อคนตายแล้วหนังสือพินัยกรรมนั้นจึงใช้ได้ มิฉะนั้นเมื่อผู้ทํายังมีชีวิตอยู่ หนังสือพินัยกรรมนั้นก็ใช้ไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 18, 'เหตุฉะนั้นพันธสัญญาเดิมก็ไม่ได้ทรงตั้งขึ้นไว้โดยปราศจากเลือด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 19, 'เพราะว่าเมื่อโมเสสประกาศข้อบังคับทุกข้อแก่บรรดาพลไพร่ตามพระราชบัญญัติแล้ว ท่านจึงได้เอาเลือดลูกวัวและเลือดลูกแพะกับน้ํา และเอาขนแกะสีแดงและต้นหุสบมาประพรมหนังสือม้วนนั้นกับทั้งบรรดาคนทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 20, 'กล่าวว่า ‘นี่เป็นเลือดแห่งพันธสัญญา ซึ่งพระเจ้าทรงบัญญัติไว้แก่ท่านทั้งหลาย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 21, 'แล้วท่านก็เอาเลือดประพรมพลับพลากับเครื่องใช้ทุกชนิดในการปฏิบัตินั้นเช่นเดียวกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 22, 'และตามพระราชบัญญัติถือว่า เกือบทุกสิ่งจะถูกชําระด้วยโลหิต และถ้าไม่มีโลหิตไหลออกแล้ว ก็จะไม่มีการอภัยบาปเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 23, 'เหตุฉะนั้นจึงจําเป็นต้องชําระแบบจําลองของสวรรค์ โดยใช้เครื่องบูชาอย่างนี้ แต่ว่าของจริงในสวรรค์นั้น ต้องชําระด้วยเครื่องบูชาอันประเสริฐกว่าเครื่องบูชาเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 24, 'เพราะว่าพระคริสต์ไม่ได้เสด็จเข้าในสถานที่บริสุทธิ์ซึ่งสร้างขึ้นด้วยมือมนุษย์ อันเป็นแบบจําลองจากของจริง แต่พระองค์ได้เสด็จเข้าไปในสวรรค์นั้นเอง และบัดนี้ทรงปรากฏจําเพาะพระพักตร์พระเจ้าเพื่อเราทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 25, 'พระองค์ไม่ต้องทรงถวายพระองค์เองซ้ําอีก เหมือนอย่างมหาปุโรหิตที่เข้าไปในที่บริสุทธิ์ทุกปีๆ นําเอาเลือดซึ่งไม่ใช่โลหิตของตัวเองเข้าไปด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 26, 'มิฉะนั้นพระองค์คงต้องทนทุกข์ทรมานบ่อยๆตั้งแต่สร้างโลกมา แต่ว่าเดี๋ยวนี้พระองค์ได้ทรงปรากฏในเวลาที่สุดนี้ครั้งเดียว เพื่อจะได้กําจัดความบาปได้โดยถวายพระองค์เองเป็นเครื่องบูชา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 27, 'มีข้อกําหนดสําหรับมนุษย์ไว้แล้วว่าจะต้องตายหนหนึ่ง และหลังจากนั้นก็จะมีการพิพากษาฉันใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 28, 'ดังนั้นพระคริสต์ได้ทรงถวายพระองค์เองหนหนึ่ง เพื่อจะได้ทรงรับเอาความบาปของคนเป็นอันมาก แล้วพระองค์จะทรงปรากฏครั้งที่สองปราศจากความบาปแก่บรรดาคนที่คอยพระองค์ให้เขาถึงความรอดฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 1, 'โดยเหตุที่พระราชบัญญัตินั้นได้เป็นแต่เงาของสิ่งดีที่จะมาภายหน้า มิใช่ตัวจริงของสิ่งนั้นทีเดียว พระราชบัญญัตินั้นจะใช้เครื่องบูชาที่เขาถวายทุกปีๆเสมอมากระทําให้ผู้ถวายสักการบูชานั้นถึงที่สําเร็จไม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 2, 'เพราะถ้าเป็นเช่นนั้นได้ เขาคงได้หยุดการถวายเครื่องบูชาแล้วมิใช่หรือ เพราะถ้าผู้นมัสการนั้นได้รับการชําระให้บริสุทธิ์ครั้งหนึ่งแล้ว เขาคงจะไม่รู้สึกว่ามีบาปอีกต่อไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 3, 'แต่การถวายเครื่องบูชานั้นเป็นเหตุให้ระลึกถึงความบาปทุกปีๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 4, 'เพราะเลือดวัวผู้และเลือดแพะไม่สามารถชําระความบาปได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 5, 'ดังนั้นเมื่อพระองค์เสด็จเข้ามาในโลกแล้ว พระองค์ได้ตรัสว่า ‘เครื่องสัตวบูชาและเครื่องบูชาพระองค์ไม่ทรงประสงค์ แต่พระองค์ได้ทรงจัดเตรียมกายสําหรับข้าพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 6, 'เครื่องเผาบูชาและเครื่องบูชาไถ่บาป พระองค์ไม่ทรงพอพระทัย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 7, 'แล้วข้าพระองค์ทูลว่า “ดูเถิด ข้าพระองค์มาแล้ว โอ พระเจ้าข้า เพื่อจะกระทําตามน้ําพระทัยพระองค์” (ในหนังสือม้วนก็มีเขียนเรื่องข้าพระองค์)’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 8, 'เมื่อพระองค์ตรัสดังนี้แล้วว่า “เครื่องสัตวบูชาและเครื่องบูชาและเครื่องเผาบูชาและเครื่องบูชาไถ่บาป พระองค์ไม่ทรงประสงค์และไม่ทรงพอพระทัย” ซึ่งเขาได้บูชาตามพระราชบัญญัตินั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 9, 'แล้วพระองค์จึงตรัสว่า “ดูเถิด ข้าพระองค์มาแล้ว โอ พระเจ้าข้า เพื่อจะกระทําตามน้ําพระทัยพระองค์” พระองค์ทรงยกเลิกระบบเดิมนั้นเสีย เพื่อจะทรงตั้งระบบใหม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 10, 'โดยน้ําพระทัยนั้นเองที่เราทั้งหลายได้รับการทรงชําระให้บริสุทธิ์ โดยการถวายพระกายของพระเยซูคริสต์เพียงครั้งเดียวเท่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 11, 'ฝ่ายปุโรหิตทุกคนก็ยืนปฏิบัติอยู่ทุกวันๆและนําเอาเครื่องบูชาอย่างเดียวกันมาถวายเนืองๆ เครื่องบูชานั้นจะยกเอาความบาปไปเสียไม่ได้เลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 12, 'ฝ่ายพระองค์นี้ ครั้นทรงถวายเครื่องบูชาเพราะความบาปเพียงหนเดียวซึ่งใช้ได้เป็นนิตย์ ก็เสด็จประทับเบื้องขวาพระหัตถ์ของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 13, 'ตั้งแต่นี้ไปพระองค์คอยอยู่จนถึงบรรดาศัตรูของพระองค์จะถูกปราบลงเป็นที่รองพระบาทของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 14, 'เพราะว่าโดยการทรงถวายบูชาหนเดียว พระองค์ได้ทรงกระทําให้คนทั้งหลายที่ถูกชําระแล้วถึงที่สําเร็จเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 15, 'และพระวิญญาณบริสุทธิ์ก็ทรงเป็นพยานให้แก่เราด้วย เพราะว่าพระองค์ได้ตรัสไว้แล้วว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 16, '‘“นี่คือพันธสัญญาซึ่งเราจะกระทํากับเขาทั้งหลายภายหลังสมัยนั้น” องค์พระผู้เป็นเจ้าตรัส “เราจะบรรจุราชบัญญัติของเราไว้ในจิตใจของเขาทั้งหลาย และจะจารึกมันไว้ที่ในดวงใจของเขาทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 17, 'และจะไม่จดจําบาปและความชั่วช้าของเขาอีกต่อไป”’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 18, 'ดังนั้นเมื่อมีการลบบาปแล้วก็ไม่มีการถวายเครื่องบูชาไถ่บาปอีกต่อไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 19, 'เหตุฉะนั้นพี่น้องทั้งหลาย เมื่อเรามีใจกล้าที่จะเข้าไปในที่บริสุทธิ์ที่สุดโดยพระโลหิตของพระเยซู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 20, 'ตามทางใหม่และเป็นทางที่มีชีวิต ซึ่งพระองค์ได้ทรงเปิดออกสําหรับเราทั้งหลายโดยม่านนั้น คือเนื้อหนังของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 21, 'และครั้นเรามีมหาปุโรหิตสําหรับครอบครัวของพระเจ้าแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 22, 'ก็ให้เราเข้ามาใกล้ด้วยใจจริง ด้วยความเชื่ออันเต็มเปี่ยม มีใจที่ถูกประพรมชําระพ้นจากการวินิจฉัยผิดและชอบที่ชั่วร้าย และมีกายล้างชําระด้วยน้ําอันใสบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 23, 'ให้เรายึดมั่นในความเชื่อที่เราทั้งหลายรับไว้นั้น โดยไม่หวั่นไหว (เพราะว่าพระองค์ผู้ทรงประทานพระสัญญานั้นทรงสัตย์ซื่อ)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 24, 'และให้เราพิจารณาดูกันและกัน เพื่อเป็นเหตุให้มีความรักและกระทําการดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 25, 'ซึ่งเราเคยประชุมกันนั้นอย่าให้หยุด เหมือนอย่างบางคนเคยกระทํานั้น แต่จงเตือนสติกันและกัน และให้มากยิ่งขึ้นเมื่อท่านทั้งหลายเห็นวันเวลานั้นใกล้เข้ามาแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 26, 'เมื่อเราได้รับความรู้เรื่องความจริงแล้ว แต่เรายังขืนทําผิดอีก เครื่องบูชาไถ่บาปก็จะไม่มีเหลืออยู่เลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 27, 'แต่จะมีความหวาดกลัวในการรอคอยการพิพากษาโทษและไฟอันร้ายแรง ซึ่งจะกินเอาบรรดาคนที่ขัดขวางนั้นเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 28, 'คนที่ได้ฝ่าฝืนพระราชบัญญัติของโมเสสนั้น ถ้ามีพยานสักสองสามปาก ก็จะต้องตายโดยปราศจากความเมตตา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 29, 'ท่านทั้งหลายคิดดูซิว่าคนที่เหยียบย่ําพระบุตรของพระเจ้า และดูหมิ่นพระโลหิตแห่งพันธสัญญาซึ่งชําระเขาให้บริสุทธิ์ว่าเป็นสิ่งชั่วช้า และประมาทต่อพระวิญญาณผู้ทรงพระคุณ ควรจะถูกลงโทษมากยิ่งกว่านั้นสักเท่าใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 30, 'เพราะเรารู้จักพระองค์ผู้ได้ตรัสว่า ‘การแก้แค้นเป็นของเรา เราจะตอบสนอง องค์พระผู้เป็นเจ้าได้ตรัส’ และได้ตรัสอีกว่า ‘องค์พระผู้เป็นเจ้าจะทรงพิพากษาประชาชนของพระองค์’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 31, 'การตกอยู่ในอุ้งพระหัตถ์ของพระเจ้าผู้ทรงพระชนม์นั้นเป็นที่น่าหวาดกลัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 32, 'แต่ท่านทั้งหลายจงระลึกถึงคราวก่อนนั้น หลังจากที่ท่านได้รับความสว่างแล้ว ท่านได้อดทนต่อความยากลําบากอย่างใหญ่หลวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 33, 'บางทีท่านก็ถูกประจานให้อับอายขายหน้าและถูกข่มเหง บางทีท่านก็ร่วมทุกข์กับคนที่ถูกข่มเหงนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 34, 'เพราะว่าท่านทั้งหลายมีใจเมตตาต่อข้าพเจ้าในเมื่อข้าพเจ้าต้องถูกขังไว้ และเมื่อมีคนปล้นชิงเอาทรัพย์สิ่งของของท่านไป ท่านก็ยอมให้ด้วยใจยินดี เพราะท่านรู้แล้วว่า ท่านมีทรัพย์สมบัติที่ประเสริฐกว่าและถาวรกว่านั้นอีกในสวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 35, 'เหตุฉะนั้นขออย่าได้ละทิ้งความไว้วางใจของท่าน ซึ่งมีบําเหน็จอันยิ่งใหญ่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 36, 'ด้วยว่าท่านทั้งหลายต้องการความเพียร เพื่อว่าครั้นท่านกระทําให้น้ําพระทัยของพระเจ้าสําเร็จได้ ท่านจะได้รับตามคําทรงสัญญา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 37, '‘เพราะอีกไม่นานพระองค์ผู้จะเสด็จมาก็จะเสด็จมาและจะไม่ทรงชักช้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 38, 'แต่คนชอบธรรมจะมีชีวิตดํารงอยู่โดยความเชื่อ แต่ถ้าผู้ใดเสื่อมถอย ใจของเราจะไม่มีความพอใจในคนนั้นเลย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 39, 'แต่เราทั้งหลายไม่อยู่ฝ่ายคนเหล่านั้นที่กลับถอยหลังถึงความพินาศ แต่อยู่ฝ่ายคนเหล่านั้นที่เชื่อจนให้จิตวิญญาณถึงที่รอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 1, 'บัดนี้ความเชื่อคือความแน่ใจในสิ่งที่เราหวังไว้ เป็นหลักฐานมั่นใจว่า สิ่งที่ยังไม่ได้เห็นนั้นมีจริง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 2, 'โดยความเชื่อนี้เอง พวกบรรพบุรุษก็ได้รับการรับรอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 3, 'โดยความเชื่อนี้เอง เราจึงเข้าใจว่า พระเจ้าได้ทรงสร้างกัลปจักรวาลด้วยพระดํารัสของพระองค์ ดังนั้นสิ่งที่มองเห็นจึงเป็นสิ่งที่เกิดจากสิ่งที่ไม่ปรากฏให้เห็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 4, 'โดยความเชื่อ อาแบลนั้นจึงได้นําเครื่องบูชาอันประเสริฐกว่าเครื่องบูชาของคาอินมาถวายแด่พระเจ้า เพราะเหตุเครื่องบูชานั้นจึงมีพยานว่าท่านเป็นคนชอบธรรม คือพระเจ้าทรงเป็นพยานแก่ของถวายของท่าน โดยความเชื่อนั้น แม้ว่าอาแบลตายแล้วท่านก็ยังพูดอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 5, 'โดยความเชื่อ เอโนคจึงถูกรับขึ้นไป เพื่อไม่ให้ท่านประสบกับความตาย ไม่มีผู้ใดพบท่าน เพราะพระเจ้าทรงรับท่านไปแล้ว ก่อนที่ทรงรับท่านขึ้นไปนั้นมีพยานว่า ท่านเป็นที่พอพระทัยของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 6, 'แต่ถ้าไม่มีความเชื่อแล้ว จะเป็นที่พอพระทัยของพระองค์ก็ไม่ได้เลย เพราะว่าผู้ที่จะมาหาพระเจ้าได้นั้นต้องเชื่อว่าพระองค์ทรงดํารงพระชนม์อยู่ และพระองค์ทรงเป็นผู้ประทานบําเหน็จให้แก่ทุกคนที่ขยันหมั่นเพียรแสวงหาพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 7, 'โดยความเชื่อ เมื่อพระเจ้าทรงเตือนโนอาห์ถึงเหตุการณ์ที่ยังไม่ปรากฏ ท่านมีใจเกรงกลัวจัดแจงต่อนาวา เพื่อช่วยครอบครัวของท่านให้รอด และด้วยเหตุนี้เอง ท่านจึงได้ปรับโทษแก่โลก และได้เป็นผู้รับมรดกแห่งความชอบธรรม ซึ่งบังเกิดมาจากความเชื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 8, 'โดยความเชื่อ เมื่อทรงเรียกให้อับราฮัมออกเดินทางไปยังที่ซึ่งท่านจะรับเป็นมรดก ท่านได้เชื่อฟังและได้เดินทางออกไปโดยหารู้ไม่ว่าจะไปทางไหน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 9, 'โดยความเชื่อ ท่านได้พํานักในแผ่นดินแห่งพระสัญญานั้น เหมือนอยู่ในดินแดนแปลกถิ่น คืออาศัยอยู่ในเต็นท์กับอิสอัคและยาโคบซึ่งเป็นผู้รับมรดกด้วยกันกับท่านในพระสัญญาอันเดียวกันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 10, 'เพราะว่าท่านได้คอยอยู่เพื่อจะได้เมืองที่มีราก ซึ่งพระเจ้าเป็นนายช่างและเป็นผู้ทรงสร้างขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 11, 'โดยความเชื่อ นางซาราห์เองเช่นกันจึงได้รับพลังตั้งครรภ์และได้คลอดบุตรเมื่อชรามากแล้ว เพราะนางถือว่าพระองค์ผู้ได้ทรงประทานพระสัญญานั้นทรงเป็นผู้สัตย์ซื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 12, 'เหตุฉะนั้น คนเป็นอันมากดุจดาวในท้องฟ้า และดุจเม็ดทรายที่ทะเลซึ่งนับไม่ได้ได้บังเกิดแต่ชายคนเดียว และชายคนนั้นก็เท่ากับคนที่ตายแล้วด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 13, 'บรรดาคนเหล่านี้ได้ตายไปในระหว่างที่เชื่ออยู่ ยังไม่ได้รับผลตามพระสัญญาทั้งหลายนั้น แต่ได้แลเห็นพระสัญญาแต่ไกล ก็เชื่อมั่นและต้อนรับพระสัญญาเหล่านั้นไว้ และได้ยอมรับว่าเขาทั้งหลายเป็นคนต่างด้าวและเป็นผู้สัญจรอยู่ในแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 14, 'เพราะคนที่พูดอย่างนี้ก็แสดงให้เห็นชัดแล้วว่า เขากําลังแสวงหาเมืองที่จะได้เป็นของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 15, 'และแท้จริงถ้าเขาคิดถึงบ้านเมืองที่เขาจากมานั้น เขาก็คงจะมีโอกาสกลับไปได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 16, 'แต่บัดนี้เขาปรารถนาที่จะอยู่ในเมืองที่ประเสริฐกว่านั้น คือเมืองสวรรค์ เหตุฉะนั้นพระเจ้าจึงมิได้ทรงละอายเมื่อเขาเรียกพระองค์ว่าเป็นพระเจ้าของเขา เพราะพระองค์ได้ทรงจัดเตรียมเมืองหนึ่งไว้สําหรับเขาแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 17, 'โดยความเชื่อ เมื่ออับราฮัมถูกลองใจก็ได้ถวายอิสอัคเป็นเครื่องบูชา นี่แหละท่านผู้ได้รับพระสัญญาเหล่านั้นก็ได้ถวายบุตรชายคนเดียวของตนที่ได้ให้กําเนิดมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 18, 'คือบุตรที่มีพระดํารัสไว้ว่า ‘เขาจะเรียกเชื้อสายของเจ้าทางสายอิสอัค’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 19, 'ท่านเชื่อว่าพระเจ้าทรงฤทธิ์สามารถให้อิสอัคเป็นขึ้นมาจากความตายได้ และท่านได้รับบุตรนั้นกลับคืนมาอีก ประหนึ่งว่าบุตรนั้นเป็นขึ้นมาจากตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 20, 'โดยความเชื่อ อิสอัคได้อวยพรแก่ยาโคบและเอซาว คือเกี่ยวกับเหตุการณ์ซึ่งจะบังเกิดภายหน้านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 21, 'โดยความเชื่อ ยาโคบเมื่อจะตายได้อวยพรแก่บุตรชายทั้งสองของโยเซฟ และได้นมัสการขณะที่ค้ําอยู่บนหัวไม้เท้าของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 22, 'โดยความเชื่อ โยเซฟเมื่อกําลังจะตายได้กล่าวถึงการที่ชนชาติอิสราเอลจะออกไป และได้มีคําสั่งไว้เรื่องกระดูกของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 23, 'โดยความเชื่อ เมื่อโมเสสบังเกิดมาแล้ว บิดามารดาได้ซ่อนท่านไว้ถึงสามเดือน เพราะเห็นว่าเป็นเด็กรูปงาม และไม่ได้กลัวคําสั่งของกษัตริย์นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 24, 'โดยความเชื่อ ครั้นโมเสสวัฒนาโตขึ้นแล้ว ไม่ยอมให้เรียกว่าเป็นบุตรชายของธิดากษัตริย์ฟาโรห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 25, 'ท่านเลือกการร่วมทุกข์กับชนชาติของพระเจ้า แทนการเริงสําราญในความบาปสักเวลาหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 26, 'ท่านถือว่าความอัปยศของพระคริสต์ประเสริฐกว่าคลังทรัพย์ในประเทศอียิปต์ เพราะท่านหวังบําเหน็จที่จะได้รับนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 27, 'โดยความเชื่อ ท่านได้ออกจากประเทศอียิปต์ โดยมิได้เกรงกลัวความกริ้วของกษัตริย์ เพราะท่านยอมทนอยู่เหมือนประหนึ่งได้เห็นพระองค์ผู้ไม่ทรงปรากฏแก่ตา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 28, 'โดยความเชื่อ ท่านได้ถือเทศกาลปัสกาและพิธีประพรมเลือด เพื่อมิให้องค์เพชฌฆาตผู้ประหารบุตรหัวปีมาถูกต้องพวกอิสราเอลได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 29, 'โดยความเชื่อ พวกอิสราเอลได้ข้ามทะเลแดงเหมือนกับว่าเดินบนดินแห้ง แต่เมื่อพวกอียิปต์ได้ลองเดินข้ามดูบ้าง ก็จมน้ําตายหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 30, 'โดยความเชื่อ เมื่อพวกอิสราเอลล้อมกําแพงเมืองเยรีโคไว้ถึงเจ็ดวันแล้ว กําแพงเมืองก็พังลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 31, 'โดยความเชื่อ ราหับหญิงแพศยาจึงมิได้พินาศไปพร้อมกับคนเหล่านั้นที่มิได้เชื่อ เมื่อนางได้ต้อนรับคนสอดแนมนั้นไว้อย่างสันติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 32, 'และข้าพเจ้าจะกล่าวอะไรต่อไปอีกเล่า เพราะไม่มีเวลาพอที่จะกล่าวถึงกิเดโอน บาราค แซมสัน เยฟธาห์ ดาวิด และซามูเอล และศาสดาพยากรณ์ทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 33, 'โดยความเชื่อ ท่านเหล่านั้นจึงได้มีชัยเหนืออาณาจักรต่างๆ ได้กระทําการชอบธรรม ได้รับพระสัญญา ได้ปิดปากสิงโต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 34, 'ได้ดับไฟที่ไหม้อย่างรุนแรง ได้พ้นจากคมดาบ ความอ่อนแอของท่านก็กลับเป็นความเข้มแข็ง มีกําลังความสามารถในการทําสงคราม ได้ตีกองทัพประเทศอื่นๆแตกพ่ายไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 35, 'พวกผู้หญิงก็ได้รับคนพวกของนางที่ตายแล้วกลับฟื้นคืนชีวิตขึ้นมาอีก บางคนก็ถูกทรมาน แต่ก็ไม่ยอมรับการปลดปล่อย เพื่อเขาจะได้รับการเป็นขึ้นมาจากความตายอันประเสริฐกว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 36, 'บางคนถูกทดลองโดยคําเยาะเย้ยและการถูกโบยตี และยังถูกล่ามโซ่และถูกขังคุกด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 37, 'บางคนถูกหินขว้าง บางคนก็ถูกเลื่อยเป็นท่อนๆ บางคนถูกทดลอง บางคนก็ถูกฆ่าด้วยดาบ บางคนเที่ยวสัญจรไปนุ่งห่มหนังแกะและหนังแพะ อดอยาก ทนทุกข์เวทนาและทนการเคี่ยวเข็ญ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 38, '(โลกไม่สมกับคนเช่นนั้นเลย) เขาพเนจรไปในถิ่นทุรกันดารและตามภูเขา และอยู่ตามถ้ําและตามโพรง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 39, 'คนเหล่านั้นทุกคนมีชื่อเสียงดีโดยความเชื่อของเขา แต่เขาก็ยังไม่ได้รับสิ่งที่ทรงสัญญาไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 40, 'ด้วยว่าพระเจ้าทรงจัดเตรียมการอย่างดีกว่าไว้สําหรับเราทั้งหลาย เพื่อไม่ให้เขาทั้งหลายถึงที่สําเร็จนอกจากเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 1, 'เหตุฉะนั้น ครั้นเรามีพยานหมู่ใหญ่อย่างนั้นอยู่รอบข้าง ให้เราทิ้งของหนักทุกสิ่งที่ขัดข้องอยู่ และการผิดที่เรามักง่ายกระทํานั้น และการวิ่งแข่งกันที่กําหนดไว้สําหรับเรานั้น ให้เราวิ่งด้วยความเพียรพยายาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 2, 'หมายเอาพระเยซูเป็นผู้ริเริ่มความเชื่อ และผู้ทรงทําให้ความเชื่อของเราสําเร็จ เพราะเห็นแก่ความยินดีที่มีอยู่ตรงหน้านั้น พระองค์ได้ทรงทนเอากางเขน ทรงถือว่าความละอายไม่เป็นสิ่งสําคัญอะไร และได้เสด็จประทับเบื้องขวาพระที่นั่งของพระเจ้าแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 3, 'ด้วยว่าท่านทั้งหลายจงพินิจคิดถึงพระองค์ ผู้ได้ทรงทนเอาการติเตียนนินทาของคนบาปต่อพระองค์มากเท่าใด เพื่อท่านทั้งหลายจะไม่อ่อนระอาใจไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 4, 'ท่านทั้งหลายยังไม่ได้สู้รบกับความบาปจนถึงโลหิตตก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 5, 'และท่านได้ลืมคําเตือนนั้นเสีย ซึ่งได้เตือนท่านเหมือนกับเตือนบุตรว่า ‘บุตรชายของเราเอ๋ย อย่าดูหมิ่นการตีสอนขององค์พระผู้เป็นเจ้า และอย่าระอาใจเมื่อพระองค์ทรงติเตียนท่านนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 6, 'เพราะองค์พระผู้เป็นเจ้าทรงตีสอนผู้ที่พระองค์ทรงรัก และเมื่อพระองค์ทรงรับผู้ใดเป็นบุตร พระองค์ก็ทรงเฆี่ยนตีผู้นั้น’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 7, 'ถ้าท่านทั้งหลายทนเอาการตีสอน พระเจ้าย่อมทรงปฏิบัติต่อท่านเหมือนท่านเป็นบุตร ด้วยว่ามีบุตรคนใดเล่าที่บิดาไม่ได้ตีสอนเขาบ้าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 8, 'แต่ถ้าท่านทั้งหลายไม่ได้ถูกตีสอนเช่นเดียวกับคนทั้งปวง ท่านก็ไม่ได้เป็นบุตร แต่เป็นลูกที่ไม่มีพ่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 9, 'อีกประการหนึ่ง เราทั้งหลายได้มีบิดาตามเนื้อหนังที่ได้ตีสอนเรา และเราจึงได้นับถือบิดานั้น ยิ่งกว่านั้นอีก เราควรจะได้ยําเกรงนบนอบต่อพระบิดาแห่งจิตวิญญาณและจําเริญชีวิตมิใช่หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 10, 'เพราะแท้จริงบิดาเหล่านั้นตีสอนเราเพียงชั่วเวลาเล็กน้อย ตามความเห็นดีเห็นชอบของเขาเท่านั้น แต่พระองค์ได้ทรงตีสอนเราเพื่อประโยชน์ของเรา เพื่อให้เราได้เข้าส่วนในความบริสุทธิ์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 11, 'ดังนั้นการตีสอนทุกอย่างเมื่อกําลังถูกอยู่นั้นไม่เป็นการชื่นใจเลย แต่เป็นการเศร้าใจ แต่ภายหลังก็กระทําให้เกิดผลเป็นความสุขสําราญแก่บรรดาคนที่ต้องทนอยู่นั้น คือความชอบธรรมนั้นเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 12, 'เพราะเหตุนั้น จงยกมือที่อ่อนแรงขึ้น และจงให้หัวเข่าที่อ่อนล้ามีกําลังขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 13, 'และจงกระทําทางที่เท้าของท่านจะเดินไปนั้นให้ตรงไป เพื่ออาการที่ทําให้ง่อยจะมิได้กําเริบขึ้น แต่จะได้หายเป็นปกติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 14, 'จงอุตส่าห์ที่จะสงบสุขอยู่กับคนทั้งปวง และที่จะได้ใจบริสุทธิ์ ด้วยว่านอกจากนั้นไม่มีใครจะได้เห็นองค์พระผู้เป็นเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 15, 'และจงระวังให้ดีเกรงว่าจะมีบางคนกําลังเสื่อมจากพระกรุณาคุณของพระเจ้า และเกรงว่าจะมีรากขมขื่นแซมขึ้นมาทําให้เกิดความยุ่งยากแก่ท่าน และเป็นเหตุให้คนเป็นอันมากมลทินไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 16, 'และเกรงว่าจะมีคนกระทําผิดประเวณีหรือคนประมาทเหมือนอย่างเอซาว ผู้ได้เอาสิทธิของบุตรหัวปีนั้นขายเสียเพราะเห็นแก่อาหารคําเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 17, 'เพราะท่านทั้งหลายก็รู้อยู่แล้วว่า ต่อมาภายหลังเมื่อเอซาวอยากได้รับพรนั้นเป็นมรดก เขาก็ได้รับคําปฏิเสธ เพราะเขาไม่มีหนทางแก้ไขเลย ถึงแม้ว่าได้กลับใจแสวงหาจนน้ําตาไหล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 18, 'ท่านทั้งหลายไม่ได้มาถึงภูเขาที่จะถูกต้องได้ และที่ได้ไหม้ไฟแล้ว และถึงที่ดํา ถึงที่มืดมิด และถึงที่ลมพายุ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 19, 'และถึงเสียงแตร และถึงพระสุรเสียงตรัส ซึ่งคนเหล่านั้นที่ได้ยินแล้วได้อ้อนวอนขอไม่ให้ตรัสแก่เขาอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 20, '(เพราะว่าข้อความที่ทรงบัญญัติไว้นั้นเขาทนไม่ได้ คือที่ว่า “แม้แต่สัตว์ถ้าแตะต้องภูเขานั้นก็จะต้องถูกขว้างด้วยก้อนหินให้ตาย หรือแทงทะลุด้วยแหลนให้ตาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 21, 'สิ่งที่เห็นนั้นน่ากลัวจริงๆจนโมเสสเองก็กล่าวว่า “ข้าพเจ้ากลัวจนตัวสั่น”)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 22, 'แต่ท่านทั้งหลายได้มาถึงภูเขาศิโยน และมาถึงเมืองของพระเจ้าผู้ทรงดํารงพระชนม์อยู่ คือกรุงเยรูซาเล็มแห่งสวรรค์ และมาถึงที่ชุมนุมทูตสวรรค์มากมายเหลือที่จะนับได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 23, 'และมาถึงที่ชุมนุมอันใหญ่และมาถึงคริสตจักรของบุตรหัวปี ซึ่งมีชื่อจารึกไว้ในสวรรค์แล้ว และมาถึงพระเจ้าผู้ทรงพิพากษาคนทั้งปวง และมาถึงจิตวิญญาณของคนชอบธรรมซึ่งถึงความสมบูรณ์แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 24, 'และมาถึงพระเยซูผู้กลางแห่งพันธสัญญาใหม่ และมาถึงพระโลหิตประพรมที่มีเสียงร้องอันประเสริฐกว่าเสียงโลหิตของอาแบล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 25, 'จงระวังให้ดี อย่าปฏิเสธไม่ยอมฟังพระองค์ผู้ตรัสนั้น เพราะว่าถ้าเขาเหล่านั้นที่ปฏิเสธไม่ยอมฟังคําเตือนของพระองค์ที่พื้นแผ่นดินโลกไม่ได้พ้นโทษ ถ้าเราเมินหน้าจากพระองค์ผู้ทรงเตือนจากสวรรค์ เราทั้งหลายก็จะไม่ได้พ้นโทษมากยิ่งกว่านั้นอีก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 26, 'พระสุรเสียงของพระองค์คราวนั้นได้บันดาลให้แผ่นดินหวั่นไหว แต่บัดนี้พระองค์ได้ตรัสสัญญาไว้ว่า “อีกครั้งหนึ่งเราจะกระทําให้หวาดหวั่นไหว มิใช่แผ่นดินโลกแห่งเดียว แต่ทั้งสวรรค์ด้วย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 27, 'และพระดํารัสที่ตรัสไว้ว่า ‘อีกครั้งหนึ่ง’ นั้น แสดงว่าสิ่งที่หวั่นไหวนั้นจะถูกกําจัดเสีย เหมือนกับสิ่งที่ทรงสร้างให้มีขึ้น เพื่อให้สิ่งที่ไม่หวั่นไหวคงเหลืออยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 28, 'เหตุฉะนั้น ครั้นเราได้อาณาจักรที่ไม่หวั่นไหวมาแล้ว ก็ให้เรารับพระคุณ เพื่อเราจะได้ปฏิบัติพระเจ้าตามชอบพระทัยของพระองค์ ด้วยความเคารพและยําเกรง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 29, 'เพราะว่าพระเจ้าของเรานั้นทรงเป็นเพลิงที่เผาผลาญ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 1, 'จงให้ความรักฉันพี่น้องมีอยู่ต่อกันเสมอไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 2, 'อย่าละเลยที่จะต้อนรับแขกแปลกหน้า เพราะว่าโดยการกระทําเช่นนั้น บางคนก็ได้ต้อนรับทูตสวรรค์โดยไม่รู้ตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 3, 'จงระลึกถึงคนเหล่านั้นที่ถูกจองจําอยู่ เหมือนหนึ่งว่าท่านทั้งหลายก็ถูกจองจําอยู่กับเขา จงระลึกถึงคนทั้งหลายที่ประสบความทุกข์ยาก เหมือนหนึ่งว่าตัวของท่านเองประสบเช่นกันในร่างกายของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 4, 'การสมรสเป็นที่นับถือแก่คนทั้งปวง และที่นอนก็ปราศจากมลทิน แต่คนที่ล่วงประเวณีและคนเล่นชู้นั้น พระเจ้าจะทรงพิพากษาโทษเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 5, 'ท่านจงพ้นจากการรักเงิน จงพอใจในสิ่งที่ท่านมีอยู่ เพราะว่าพระองค์ได้ตรัสไว้แล้วว่า “เราจะไม่ละท่านหรือทอดทิ้งท่านเลย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 6, 'เพื่อว่าเราทั้งหลายจะกล่าวด้วยใจกล้าว่า ‘องค์พระผู้เป็นเจ้าทรงเป็นพระผู้ช่วยของข้าพเจ้า ข้าพเจ้าจะไม่กลัว มนุษย์จะทําอะไรแก่ข้าพเจ้าได้เล่า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 7, 'ท่านทั้งหลายจงระลึกถึงคนเหล่านั้นที่ปกครองท่าน ผู้ซึ่งได้ประกาศพระวจนะของพระเจ้าแก่ท่าน และจงพิจารณาดูผลปลายทางของเขา แล้วจงตามอย่างความเชื่อของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 8, 'พระเยซูคริสต์ยังทรงเหมือนเดิมในเวลาวานนี้ และเวลาวันนี้ และต่อๆไปเป็นนิจกาล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 9, 'อย่าหลงไปตามคําสอนต่างๆที่แปลกๆ เพราะว่าเป็นการดีอยู่แล้วที่จะให้กําลังใจเข้มแข็งขึ้นด้วยพระคุณ ไม่ใช่ด้วยอาหารการกิน ซึ่งไม่เคยเป็นประโยชน์แก่คนที่หลงติดอยู่เลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 10, 'เรามีแท่นบูชาแท่นหนึ่ง และคนที่ปรนนิบัติในพลับพลานั้นไม่มีสิทธิ์ที่จะรับประทานของจากแท่นนั้นได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 11, 'เพราะร่างของสัตว์เหล่านั้นที่มหาปุโรหิตได้เอาเลือดเข้าไปในสถานบริสุทธิ์เพื่อเป็นเครื่องบูชาไถ่บาปนั้น ก็ต้องเอาไปเผาเสียนอกค่าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 12, 'เหตุฉะนั้น พระเยซูก็ได้ทรงทนทุกข์ทรมานภายนอกประตูเมืองเช่นเดียวกัน เพื่อทรงชําระประชาชนให้บริสุทธิ์ด้วยพระโลหิตของพระองค์เอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 13, 'เพราะฉะนั้น ให้เราทั้งหลายออกไปหาพระองค์ภายนอกค่ายนั้น และยอมรับคําดูหมิ่นเหยียดหยามเพื่อพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 14, 'เพราะว่าที่นี่เราไม่มีเมืองที่ถาวร แต่ว่าเราแสวงหาเมืองที่จะมีในภายหน้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 15, 'เหตุฉะนั้น ให้เราถวายคําสรรเสริญเป็นเครื่องบูชาแด่พระเจ้าตลอดไปโดยทางพระองค์นั้น คือผลแห่งริมฝีปากที่ขอบพระคุณพระนามของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 16, 'แต่อย่าลืมที่จะกระทําการดี และที่จะแบ่งปันข้าวของซึ่งกันและกัน เพราะเครื่องบูชาอย่างนั้นเป็นที่พอพระทัยพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 17, 'ท่านทั้งหลายจงเชื่อฟังและยอมอยู่ในโอวาทของคนเหล่านั้นที่ปกครองท่าน ด้วยว่าท่านเหล่านั้นคอยระวังดูจิตวิญญาณของท่าน เหมือนกับผู้ที่จะต้องรายงาน เพื่อเขาจะได้ทําการนี้ด้วยความชื่นใจ ไม่ใช่ด้วยความเศร้าใจ เพราะที่ทําดังนั้นก็จะไม่เป็นประโยชน์อะไรแก่ท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 18, 'จงอธิษฐานเพื่อเรา เพราะเราแน่ใจว่า เรามีใจวินิจฉัยผิดและชอบดีอยู่แล้ว และปรารถนาที่จะปฏิบัติอย่างซื่อสัตย์ในทุกอย่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 19, 'และข้าพเจ้าวิงวอนท่านมากยิ่งให้กระทําเช่นนั้น เพื่อข้าพเจ้าจะได้กลับคืนไปอยู่กับท่านโดยเร็ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 20, 'บัดนี้ขอพระเจ้าแห่งสันติสุข ผู้ทรงบันดาลให้พระเยซูเจ้าของเราเป็นขึ้นมาจากความตาย คือผู้ทรงเป็นผู้เลี้ยงแกะที่ยิ่งใหญ่ โดยพระโลหิตแห่งพันธสัญญานิรันดร์นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 21, 'ทรงกระทําให้ท่านทั้งหลายสมบูรณ์ในการดีทุกอย่าง เพื่อจะได้ปฏิบัติตามน้ําพระทัยของพระองค์ และทรงทํางานในท่านทั้งหลายให้เป็นที่ชอบในสายพระเนตรของพระองค์โดยพระเยซูคริสต์ ขอสง่าราศีจงมีแด่พระองค์สืบๆไปเป็นนิตย์ เอเมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 22, 'พี่น้องทั้งหลาย ข้าพเจ้าขอวิงวอนท่านให้เพียรฟังคําเตือนสตินี้ เพราะข้าพเจ้าได้เขียนจดหมายมาถึงท่านทั้งหลายเพียงไม่กี่คําเท่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 23, 'ท่านทั้งหลายจงรู้ด้วยว่า ทิโมธีน้องชายของเรา ได้รับการปล่อยเป็นอิสระแล้ว ถ้าเขามาถึงเร็ว ข้าพเจ้าก็จะมาพบท่านทั้งหลายพร้อมกับเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 24, 'ขอฝากความคิดถึงมายังท่านเหล่านั้นที่ปกครองท่าน และวิสุทธิชนทั้งปวง พวกพี่น้องที่เป็นชาวอิตาลีก็ฝากความคิดถึงมายังท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 25, 'ขอพระคุณจงดํารงอยู่กับท่านทั้งหลายเถิด เอเมน [เขียนถึงชาวฮีบรูจากประเทศอิตาลี และส่งโดยทิโมธี]');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 1, 'ยากอบ ผู้รับใช้ของพระเจ้าและของพระเยซูคริสต์เจ้า คํานับพงศ์พันธุ์สิบสองตระกูลที่กระจัดกระจายอยู่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 2, 'พี่น้องของข้าพเจ้า เมื่อท่านทั้งหลายตกอยู่ในการทดลองต่างๆก็จงถือว่าเป็นเรื่องน่ายินดีทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 3, 'เพราะท่านทั้งหลายรู้ว่า การทดลองความเชื่อของท่านนั้น ทําให้เกิดความเพียร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 4, 'และจงให้ความเพียรนั้นกระทําการจนสําเร็จ เพื่อท่านทั้งหลายจะสมบูรณ์ครบถ้วนไม่ขาดสิ่งใดเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 5, 'ถ้าผู้ใดในพวกท่านขาดสติปัญญา ก็ให้ผู้นั้นทูลขอจากพระเจ้า ผู้ทรงโปรดประทานให้แก่คนทั้งปวงอย่างเหลือล้นและมิได้ทรงตําหนิ และจะทรงประทานให้แก่ผู้นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 6, 'แต่จงให้ผู้นั้นทูลขอด้วยความเชื่อ อย่าหวั่นไหวเลย เพราะว่าผู้ที่หวั่นไหวก็เป็นเหมือนคลื่นในทะเลซึ่งถูกลมพัดซัดไปมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 7, 'ผู้นั้นจงอย่าคิดว่าจะได้รับสิ่งใดจากองค์พระผู้เป็นเจ้าเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 8, 'คนสองใจเป็นคนไม่มั่นคงในบรรดาทางทั้งหลายที่ตนประพฤตินั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 9, 'ให้พี่น้องที่ต่ําต้อยชื่นชมยินดีในการที่ทรงเชิดชูเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 10, 'และคนมั่งมีก็จงชื่นชมยินดีเมื่อถูกทําให้ต่ําลง เพราะว่าเขาจะต้องล่วงลับไปดุจดอกหญ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 11, 'เพราะทันทีที่ตะวันขึ้นพร้อมด้วยความร้อนอันแรงกล้า มันก็กระทําให้หญ้าเหี่ยวแห้งไป และดอกหญ้าก็ร่วงลง และความงามของมันสูญสิ้นไป คนมั่งมีจะเสื่อมสูญไปตามทางทั้งหลายของเขาเช่นนั้นด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 12, 'ความสุขย่อมมีแก่คนนั้นที่สู้ทนการทดลอง เพราะเมื่อปรากฏว่าผู้นั้นทนได้แล้ว เขาจะได้รับมงกุฎแห่งชีวิต ซึ่งองค์พระผู้เป็นเจ้าได้ทรงสัญญาไว้แก่คนทั้งหลายที่รักพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 13, 'เมื่อผู้ใดถูกล่อลวงให้หลง อย่าให้ผู้นั้นพูดว่า “พระเจ้าทรงล่อลวงข้าพเจ้าให้หลง” เพราะว่าความชั่วจะมาล่อลวงพระเจ้าให้หลงไม่ได้ และพระองค์เองก็ไม่ทรงล่อลวงผู้ใดให้หลงเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 14, 'แต่ว่าทุกคนก็ถูกล่อลวง เมื่อตัณหาของตนเองชักนําให้กระทําผิด แล้วตัวก็กระทําตาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 15, 'ครั้นตัณหาเกิดขึ้นแล้ว ก็ทําให้เกิดบาป และเมื่อบาปโตเต็มที่แล้ว ก็นําไปสู่ความตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 16, 'พี่น้องที่รักของข้าพเจ้า อย่าหลงผิดเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 17, 'ของประทานอันดีทุกอย่าง และของประทานอันเลิศทุกอย่างย่อมมาจากเบื้องบน และส่งลงมาจากพระบิดาแห่งบรรดาดวงสว่าง ในพระบิดาไม่มีการแปรปรวน หรือไม่มีเงาอันเนื่องจากการเปลี่ยนแปลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 18, 'พระองค์ได้ทรงให้เราทั้งหลายบังเกิดโดยพระวจนะแห่งความจริงตามน้ําพระทัยของพระองค์ เพื่อเราทั้งหลายจะได้เป็นอย่างผลแรกแห่งสรรพสิ่งซึ่งพระองค์ทรงสร้างนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 19, 'ดังนั้น พี่น้องที่รักของข้าพเจ้า จงให้ทุกคนไวในการฟัง ช้าในการพูด ช้าในการโกรธ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 20, 'เพราะว่าความโกรธของมนุษย์ไม่ได้กระทําให้เกิดความชอบธรรมอย่างพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 21, 'เหตุฉะนั้น จงถอดทิ้งการโสโครกทุกอย่าง และการชั่วร้ายอันดาษดื่น และจงน้อมใจรับพระวจนะที่ทรงปลูกฝังไว้แล้วนั้น ซึ่งสามารถช่วยจิตใจของท่านทั้งหลายให้รอดได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 22, 'แต่ท่านทั้งหลายจงเป็นคนที่ประพฤติตามพระวจนะนั้น ไม่ใช่เป็นแต่เพียงผู้ฟังเท่านั้น ซึ่งเป็นการล่อลวงตนเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 23, 'เพราะว่าถ้าผู้ใดฟังพระวจนะ และไม่ได้ประพฤติตาม ผู้นั้นก็เป็นเหมือนคนที่ดูหน้าของตัวในกระจกเงา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 24, 'ด้วยว่าคนนั้นแลดูตัวเองแล้วไปเสีย แล้วในทันใดนั้นก็ลืมว่าตัวเป็นอย่างไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 25, 'ฝ่ายผู้ใดที่พิจารณาดูในพระราชบัญญัติแห่งเสรีภาพอันดีเลิศ และดํารงอยู่ในพระราชบัญญัตินั้น ผู้นั้นไม่ได้เป็นผู้ฟังแล้วหลงลืม แต่เป็นผู้ประพฤติตามกิจการนั้น คนนั้นจะได้ความสุขในการของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 26, 'ถ้าผู้ใดในพวกท่านดูเหมือนว่าเคร่งครัดในความเชื่อ และมิได้เหนี่ยวรั้งลิ้นของตนไว้ แต่ล่อลวงใจของตนเอง การเคร่งครัดในความเชื่อของผู้นั้นก็ไร้ประโยชน์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 27, 'การเคร่งครัดในความเชื่ออย่างบริสุทธิ์ไร้มลทินต่อพระพักตร์พระเจ้าและพระบิดานั้น คือการเยี่ยมเยียนเด็กกําพร้าพ่อและหญิงม่ายที่มีความทุกข์ร้อน และการรักษาตัวให้พ้นจากราคีของโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 1, 'พี่น้องทั้งหลายของข้าพเจ้า การเชื่อในพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเรา ผู้ทรงสง่าราศีนั้น อย่าให้เป็นด้วยการเลือกหน้าคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 2, 'เพราะว่าถ้ามีคนหนึ่งสวมแหวนทองคําและแต่งตัวด้วยเครื่องแต่งกายอย่างดีเข้ามาในที่ประชุมของท่าน และมีคนจนคนหนึ่งแต่งตัวด้วยเสื้อผ้าซอมซ่อเข้ามาด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 3, 'และท่านสนใจคนที่สวมใส่เครื่องแต่งกายอย่างดี และกล่าวแก่เขาว่า “เชิญท่านนั่งที่นี่ในที่อันดีเถิด” และท่านก็พูดกับคนจนนั้นว่า “แกจงยืนอยู่ที่นั่น” หรือ “จงนั่งแทบที่รองเท้าของเราเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 4, 'พวกท่านเองมิได้ลําเอียง และกลายเป็นผู้วินิจฉัยด้วยใจชั่วหรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 5, 'พี่น้องที่รักของข้าพเจ้า จงฟังเถิด พระเจ้าทรงเลือกคนยากจนในโลกนี้ให้เป็นคนมั่งมีในความเชื่อ และให้เป็นผู้รับมรดกแห่งอาณาจักร ซึ่งพระองค์ทรงสัญญาไว้แก่ผู้ที่รักพระองค์มิใช่หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 6, 'แต่ท่านทั้งหลายได้ดูถูกคนจน ไม่ใช่คนมั่งมีหรือที่กดขี่ท่านและลากตัวท่านไปขึ้นศาล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 7, 'ไม่ใช่เขาเหล่านั้นหรือที่สบประมาทพระนามอันประเสริฐซึ่งใช้เรียกท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 8, 'ถ้าท่านทั้งหลายกระทําให้สําเร็จตามพระราชบัญญัติแห่งพระมหากษัตริย์ตามพระคัมภีร์ที่ว่า ‘จงรักเพื่อนบ้านเหมือนรักตนเอง’ แล้ว ท่านทั้งหลายก็ประพฤติดีอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 9, 'แต่ถ้าท่านทั้งหลายเลือกหน้าคน ท่านก็กระทําบาป และตามพระราชบัญญัติ ท่านก็เป็นผู้ละเมิดแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 10, 'เพราะว่าผู้ใดรักษาพระราชบัญญัติได้ทั้งหมด แต่ผิดอยู่ข้อเดียว ผู้นั้นก็เป็นผู้ผิดพระราชบัญญัติทั้งหมด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 11, 'ด้วยว่าพระองค์ผู้ได้ตรัสว่า ‘อย่าล่วงประเวณีผัวเมียเขา’ ก็ได้ตรัสไว้ด้วยว่า ‘อย่าฆ่าคน’ แม้ท่านไม่ได้ล่วงประเวณีผัวเมียเขาแต่ได้ฆ่าคน ท่านก็เป็นผู้ละเมิดพระราชบัญญัติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 12, 'ท่านทั้งหลายจงพูดและจงกระทําเช่นผู้ที่จะได้รับการพิพากษาด้วยพระราชบัญญัติแห่งเสรีภาพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 13, 'เพราะว่าผู้ที่ไม่แสดงความเมตตาย่อมจะได้รับการพิพากษาโดยปราศจากความเมตตา แต่ความเมตตาย่อมก่อให้เกิดความชื่นชมยินดีมากกว่าการพิพากษา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 14, 'พี่น้องของข้าพเจ้า แม้ผู้ใดจะว่าตนมีความเชื่อ แต่ไม่มีการกระทํา จะได้ประโยชน์อะไร ความเชื่อจะช่วยผู้นั้นให้รอดได้หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 15, 'ถ้าพี่น้องชายหญิงคนใดเปลือยเปล่าและขาดแคลนอาหารประจําวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 16, 'และมีคนใดในพวกท่านกล่าวแก่เขาว่า “เชิญไปเป็นสุขเถิด ขอให้อบอุ่นและอิ่มเถิด” และไม่ได้ให้สิ่งซึ่งจําเป็นต่อร่างกายแก่เขา จะเป็นประโยชน์อะไรเล่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 17, 'ความเชื่อก็เช่นเดียวกัน ถ้าปราศจากการกระทํา ก็ตายโดยลําพังแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 18, 'แต่คงมีผู้ค้านว่า “ท่านมีความเชื่อ และข้าพเจ้ามีการกระทํา” จงแสดงความเชื่อของท่านที่ปราศจากการกระทําให้ข้าพเจ้าเห็น และข้าพเจ้าจะแสดงให้ท่านเห็นความเชื่อของข้าพเจ้าโดยการกระทําของข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 19, 'ท่านเชื่อว่ามีพระเจ้าองค์เดียว นั่นก็ดีอยู่แล้ว แม้พวกปีศาจก็เชื่อเช่นกัน และกลัวจนตัวสั่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 20, 'โอ คนไร้ค่า ท่านอยากจะรู้หรือว่า ความเชื่อที่ปราศจากการกระทําก็ตายแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 21, 'เมื่ออับราฮัมบิดาของเราได้ถวายอิสอัคบุตรชายของท่านบนแท่นบูชา จึงได้ความชอบธรรมโดยการกระทําไม่ใช่หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 22, 'ท่านคงเห็นแล้วว่า ความเชื่อได้กระทํากิจร่วมกับการกระทําของท่าน และความเชื่อก็สมบูรณ์ได้โดยการกระทํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 23, 'และพระคัมภีร์ก็สําเร็จที่ว่า ‘อับราฮัมได้เชื่อพระเจ้า และพระองค์ทรงนับว่าเป็นความชอบธรรมแก่ท่าน’ และท่านได้ชื่อว่า เป็น ‘สหายของพระเจ้า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 24, 'ท่านทั้งหลายก็เห็นแล้วว่า ผู้ใดจะเป็นคนชอบธรรมได้ ก็เนื่องด้วยการกระทํา และมิใช่ด้วยความเชื่อเพียงอย่างเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 25, 'เช่นเดียวกันราหับหญิงแพศยาก็ได้ความชอบธรรมเนื่องด้วยการกระทําด้วยมิใช่หรือ เมื่อนางได้รับรองผู้ส่งข่าวเหล่านั้น และส่งเขาไปเสียทางอื่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 26, 'เพราะกายที่ปราศจากจิตวิญญาณนั้นตายแล้วฉันใด ความเชื่อที่ปราศจากการกระทําก็ตายแล้วฉันนั้นเช่นเดียวกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 1, 'พี่น้องทั้งหลายของข้าพเจ้า อย่าเป็นอาจารย์กันมากมายหลายคนนักเลย เพราะท่านก็รู้ว่าเราทั้งหลายจะได้รับการพิพากษาที่เข้มงวดกว่าผู้อื่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 2, 'เพราะเราทุกคนทําผิดพลาดกันไปหลายๆอย่าง ถ้าผู้ใดมิได้ทําผิดทางวาจา ผู้นั้นก็เป็นคนดีรอบคอบแล้ว และสามารถบังคับทั้งตัวไว้ได้ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 3, 'ดูเถิด เราเอาเหล็กบังเหียนใส่ปากม้าเพื่อให้มันเชื่อฟังเรา เราก็บังคับมันให้ไปไหนๆได้ทั้งตัว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 4, 'จงดูเรือด้วยเช่นกัน ถึงแม้ว่าเป็นเรือใหญ่ และถูกลมแรงพัดแล่นไป เรือก็ยังหันไปมาด้วยหางเสือเล็กๆตามใจนายท้ายที่จะให้ไปทางไหน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 5, 'เช่นนั้นแหละลิ้นก็เป็นอวัยวะเล็กๆด้วย และพูดโอ้อวดอ้างการใหญ่ จงดูเถิด ไฟนิดเดียวอาจเผาไหม้มากเท่าใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 6, 'และลิ้นนั้นก็เป็นไฟ เป็นโลกแห่งการชั่วช้าซึ่งตั้งอยู่ในบรรดาอวัยวะของเรา เป็นเหตุให้ทั้งกายเป็นมลทินไป ทําให้วิถีแห่งธรรมชาติเผาไหม้ และมันเองก็ติดไฟจากนรก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 7, 'เพราะสัตว์เดียรัจฉานทุกชนิด ทั้งนก งู และสัตว์ในทะเลก็เลี้ยงให้เชื่องได้ และมนุษย์ก็ได้เลี้ยงให้เชื่องแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 8, 'แต่ลิ้นนั้นไม่มีมนุษย์คนใดสามารถทําให้เชื่องได้ ลิ้นเป็นสิ่งชั่วซึ่งยับยั้งไม่ได้ และเต็มไปด้วยพิษร้ายถึงตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 9, 'เราทั้งหลายสรรเสริญพระเจ้าคือพระบิดาด้วยลิ้นนั้น และด้วยลิ้นนั้นเราก็แช่งด่ามนุษย์ ซึ่งถูกสร้างขึ้นตามพระฉายาของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 10, 'คําสรรเสริญและคําแช่งด่าก็ออกมาจากปากอันเดียวกัน พี่น้องทั้งหลายของข้าพเจ้า ไม่ควรให้เป็นเช่นนั้นเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 11, 'บ่อน้ําพุจะมีน้ําจืดและน้ํากร่อยพุ่งออกมาจากช่องเดียวกันได้หรือ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 12, 'พี่น้องทั้งหลายของข้าพเจ้า ต้นมะเดื่อจะออกผลเป็นมะกอกเทศได้หรือ หรือเถาองุ่นจะออกผลเป็นมะเดื่อได้หรือ เช่นเดียวกันไม่มีบ่อน้ําพุใดจะให้ทั้งน้ําเค็มและน้ําจืดได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 13, 'ในพวกท่าน ผู้ใดมีสติปัญญาและประกอบด้วยความรู้ ก็ให้ผู้นั้นแสดงการประพฤติของตนด้วยกริยาอันดี มีใจอ่อนสุภาพประกอบด้วยปัญญา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 14, 'แต่ถ้าท่านทั้งหลายมีใจอิจฉาอันขมขื่นและอาการแก่งแย่งกันในใจของท่าน อย่าอวดเลยและอย่าพูดมุสาต่อความจริง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 15, 'ปัญญาเช่นนี้ไม่ได้มาจากเบื้องบน แต่เป็นปัญญาอย่างโลก และเป็นเดียรัจฉานตัณหา และเป็นเช่นปีศาจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 16, 'เพราะว่าที่ใดมีความอิจฉาและการแก่งแย่งกัน ที่นั่นก็วุ่นวายและมีการกระทําชั่วช้าเลวทรามทุกอย่าง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 17, 'แต่ปัญญาจากเบื้องบนนั้นบริสุทธิ์เป็นประการแรก แล้วจึงเป็นความสงบสุข สุภาพและว่าง่าย เปี่ยมด้วยความเมตตาและผลอันดี ไม่มีความลําเอียง ไม่หน้าซื่อใจคด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 18, 'และผลแห่งความชอบธรรมก็หว่านลงในสันติสุขของคนเหล่านั้นที่ก่อให้เกิดสันติสุข');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 1, 'อะไรเป็นสาเหตุของสงครามและการทะเลาะวิวาทกันในพวกท่าน มิใช่ราคะตัณหาของท่านหรือที่ต่อสู้กันในอวัยวะของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 2, 'ท่านทั้งหลายอยากได้ แต่ไม่ได้ ท่านก็ฆ่ากัน ท่านโลภแต่ไม่ได้ ท่านก็ทะเลาะและทําสงครามกัน ที่ท่านไม่มีเพราะท่านไม่ได้ขอ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 3, 'ท่านขอและไม่ได้รับ เพราะท่านขอผิด หวังได้ไปเพื่อสนองราคะตัณหาของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 4, 'ท่านทั้งหลายผู้ล่วงประเวณีชายหญิงเอ๋ย ท่านไม่รู้หรือว่า การเป็นมิตรกับโลกนั้นคือการเป็นศัตรูกับพระเจ้า เหตุฉะนั้นผู้ใดใคร่เป็นมิตรกับโลก ผู้นั้นก็เป็นศัตรูของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 5, 'ท่านคิดว่าพระคัมภีร์กล่าวไว้อย่างเปล่าประโยชน์หรือที่ว่า ‘พระวิญญาณที่สถิตอยู่ในเราทั้งหลายมีความรู้สึกหึงหวง’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 6, 'แต่พระองค์ได้ทรงประทานพระคุณเพิ่มขึ้นอีก เหตุฉะนั้นพระองค์จึงตรัสว่า ‘พระเจ้าทรงต่อสู้ผู้ที่หยิ่งจองหอง แต่ทรงประทานพระคุณแก่คนที่ใจถ่อม’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 7, 'เหตุฉะนั้น ท่านทั้งหลายจงยอมน้อมกายต่อพระเจ้า จงต่อสู้กับพญามาร และมันจะหนีไปจากท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 8, 'จงเข้าใกล้พระเจ้า และพระองค์จะสถิตอยู่ใกล้ท่าน คนบาปทั้งหลายเอ๋ย จงชําระมือให้สะอาด และคนสองใจเอ๋ย จงชําระใจของตนให้บริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 9, 'จงเป็นทุกข์โศกเศร้าและคร่ําครวญ จงให้การหัวเราะของตนกลับกลายเป็นการคร่ําครวญ และความปีติยินดีของตนกลับกลายเป็นความเศร้าสลด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 10, 'ท่านทั้งหลายจงถ่อมตัวในสายพระเนตรขององค์พระผู้เป็นเจ้า และพระองค์จะทรงยกชูท่านขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 11, 'พี่น้องทั้งหลาย อย่าใส่ร้ายซึ่งกันและกัน ผู้ใดที่พูดใส่ร้ายพี่น้องและตัดสินพี่น้องของตน ผู้นั้นก็กล่าวร้ายต่อพระราชบัญญัติ และตัดสินพระราชบัญญัติ แต่ถ้าท่านตัดสินพระราชบัญญัติ ท่านก็ไม่ใช่ผู้ที่ประพฤติตามพระราชบัญญัติ แต่เป็นผู้ตัดสิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 12, 'มีผู้ทรงตั้งพระราชบัญญัติแต่เพียงองค์เดียว คือพระองค์ผู้ทรงสามารถช่วยให้รอดได้ และทรงสามารถทําลายเสียได้ แต่ท่านเป็นผู้ใดเล่า ท่านจึงตัดสินผู้อื่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 13, 'ดูเถิด ท่านที่พูดว่า “วันนี้หรือพรุ่งนี้เราจะเข้าไปในเมืองนั้นเมืองนี้ และจะอยู่ที่นั่นปีหนึ่ง และจะค้าขายได้กําไร”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 14, 'แต่ว่าท่านทั้งหลายไม่รู้ว่าจะมีเหตุอะไรเกิดขึ้นในวันพรุ่งนี้ ชีวิตของท่านเป็นอะไรเล่า ก็เป็นเหมือนหมอกที่ปรากฏอยู่แต่ประเดี๋ยวหนึ่งแล้วก็หายไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 15, 'ท่านทั้งหลายควรจะพูดว่า “ถ้าองค์พระผู้เป็นเจ้าทรงโปรด เราจะมีชีวิตอยู่ และจะกระทําสิ่งนี้หรือสิ่งนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 16, 'แต่เดี๋ยวนี้ท่านทั้งหลายยินดีในการโอ้อวดของตน ความยินดีอย่างนี้เป็นความชั่วทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 17, 'เหตุฉะนั้น คนใดที่รู้จักกระทําการดี และไม่ได้กระทํา บาปจึงมีแก่คนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 1, 'ดูเถิด ท่านผู้มั่งมี จงร้องไห้โอดครวญเพราะความวิบัติซึ่งจะเกิดขึ้นกับท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 2, 'ทรัพย์สมบัติของท่านก็ผุพังไป และมอดก็กัดกินเสื้อผ้าของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 3, 'ทองและเงินของท่านก็เกิดสนิม และสนิมนั้นจะเป็นพยานหลักฐานต่อท่าน และจะกินเนื้อท่านดุจไฟ ท่านได้ส่ําสมสมบัติไว้แล้วสําหรับวันสุดท้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 4, 'ดูเถิด ค่าจ้างของคนงานที่ได้เกี่ยวข้าวในนาของท่าน ซึ่งท่านได้ฉ้อโกงไว้นั้น ก็ร่ําร้องขึ้น และเสียงร้องของคนที่เกี่ยวข้าวนั้น ได้ทราบถึงพระกรรณขององค์พระผู้เป็นเจ้าแห่งจอมโยธาแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 5, 'ท่านมีชีวิตอยู่ในโลกอย่างฟุ่มเฟือยและสนุกสนาน ท่านได้บํารุงเลี้ยงจิตใจของท่านเหมือนอย่างในวันประหาร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 6, 'ท่านได้ตัดสินลงโทษ และได้ฆ่าคนชอบธรรม เขาก็ไม่ได้ต่อสู้ท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 7, 'เหตุฉะนั้นพี่น้องทั้งหลาย จงอดทนจนกว่าองค์พระผู้เป็นเจ้าจะเสด็จมา ดูเถิด ชาวนารอคอยผลอันล้ําค่าที่จะได้จากแผ่นดิน และเพียรคอยจนกระทั่งมีฝนต้นฤดูและฝนปลายฤดู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 8, 'ท่านทั้งหลายก็จงอดทนเช่นนั้นเหมือนกัน จงตั้งอกตั้งใจให้ดี ด้วยว่าการเสด็จมาขององค์พระผู้เป็นเจ้าก็จวนจะถึงอยู่แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 9, 'พี่น้องทั้งหลาย จงอย่าขุ่นเคืองใจต่อกัน เกรงว่าท่านจะถูกพิพากษา ดูเถิด องค์พระผู้พิพากษาทรงประทับยืนอยู่หน้าประตูแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 10, 'พี่น้องทั้งหลายของข้าพเจ้า จงเอาแบบอย่างในการทนทุกข์และการอดทนของพวกศาสดาพยากรณ์ ผู้ได้กล่าวในพระนามขององค์พระผู้เป็นเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 11, 'ดูเถิด เราถือว่าผู้ที่อดทนก็เป็นสุข ท่านได้ยินเกี่ยวกับความอดทนของโยบ และได้เห็นที่สุดปลายแห่งองค์พระผู้เป็นเจ้าแล้วว่า องค์พระผู้เป็นเจ้านั้นทรงเปี่ยมไปด้วยพระเมตตาและความกรุณาปรานีสักเท่าใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 12, 'พี่น้องทั้งหลายของข้าพเจ้า ที่สําคัญเหนือสิ่งอื่นใดทั้งหมดก็คือ จงอย่าสาบาน ไม่ว่าจะโดยอ้างฟ้าสวรรค์หรือแผ่นดินโลก และไม่ว่าจะโดยคําสาบานอื่นใดก็ตาม แต่ที่ควรว่าใช่ก็จงว่าใช่ ที่ควรว่าไม่ก็จงว่าไม่ เกรงว่าท่านจะต้องถูกลงโทษ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 13, 'มีผู้ใดในพวกท่านทนทุกข์หรือ จงให้ผู้นั้นอธิษฐาน มีผู้ใดร่าเริงยินดีหรือ จงให้ผู้นั้นร้องเพลงสรรเสริญ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 14, 'มีผู้ใดในพวกท่านเจ็บป่วยหรือ จงให้ผู้นั้นเชิญบรรดาผู้ปกครองของคริสตจักรมา และให้ท่านเหล่านั้นอธิษฐานเพื่อเขา และเจิมเขาด้วยน้ํามันในพระนามขององค์พระผู้เป็นเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 15, 'และการอธิษฐานด้วยความเชื่อจะช่วยให้ผู้ป่วยรอดชีวิต และองค์พระผู้เป็นเจ้าจะทรงโปรดให้เขาหายโรค และถ้าเขาได้กระทําบาป ก็จะทรงโปรดอภัยให้แก่เขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 16, 'ท่านทั้งหลายจงสารภาพความผิดต่อกันและกัน และจงอธิษฐานเพื่อกันและกัน เพื่อท่านทั้งหลายจะได้หายโรค คําอธิษฐานด้วยใจร้อนรนอย่างเอาจริงเอาจังของผู้ชอบธรรมนั้นมีพลังมากทําให้เกิดผล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 17, 'ท่านเอลียาห์ก็เป็นมนุษย์ที่มีสภาพอารมณ์เช่นเดียวกับเราทั้งหลาย และท่านได้อธิษฐานอย่างจริงจังเพื่อไม่ให้ฝนตก และฝนก็ไม่ตกต้องแผ่นดินเป็นเวลาถึงสามปีกับหกเดือน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 18, 'และท่านได้อธิษฐานอีกครั้งหนึ่ง และฟ้าสวรรค์ได้ประทานฝนให้ และแผ่นดินจึงได้งอกพืชผลต่างๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 19, 'พี่น้องทั้งหลาย ถ้าคนใดในพวกท่านหลงผิดไปจากความจริง และผู้ใดชักจูงเขาให้เขากลับใจเสียใหม่ได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 20, 'จงให้ผู้นั้นรู้เถิดว่า ผู้ที่ช่วยคนบาปคนนั้นให้พ้นจากทางผิดของเขา ก็ได้ช่วยชีวิตหนึ่งให้รอดพ้นจากความตาย และได้ปกปิดการบาปเป็นอันมากไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 1, 'เปโตร อัครสาวกของพระเยซูคริสต์ เรียน พวกที่กระจัดกระจายไปอยู่ในแคว้นปอนทัส แคว้นกาลาเทีย แคว้นคัปปาโดเซีย แคว้นเอเชีย และแคว้นบิธีเนีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 2, 'ซึ่งทรงเลือกไว้แล้วตามที่พระเจ้าพระบิดาได้ทรงล่วงรู้ไว้ก่อน โดยพระวิญญาณได้ทรงชําระ ให้บังเกิดความนบนอบเชื่อฟัง และให้รับการประพรมด้วยพระโลหิตของพระเยซูคริสต์ ขอให้พระคุณและสันติสุขบังเกิดทวีคูณแก่ท่านทั้งหลายเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 3, 'จงถวายสรรเสริญแด่พระเจ้าพระบิดาแห่งพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเรา ผู้ได้ทรงพระมหากรุณาแก่เรา ทรงโปรดให้เราบังเกิดใหม่ เข้าสู่ความหวังใจอันมีชีวิตอยู่ โดยการคืนพระชนม์จากความตายของพระเยซูคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 4, 'และเพื่อให้ได้รับมรดกซึ่งไม่รู้เปื่อยเน่า ปราศจากมลทินและไม่ร่วงโรย ซึ่งได้รักษาไว้ในสวรรค์เพื่อท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 5, 'ซึ่งเป็นผู้ที่ฤทธิ์เดชของพระเจ้าได้ทรงคุ้มครองไว้ด้วยความเชื่อให้ถึงความรอด ซึ่งพร้อมแล้วที่จะปรากฏในวาระสุดท้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 6, 'ในความรอดนั้นท่านทั้งหลายชื่นชมยินดีเป็นอย่างยิ่ง ถึงแม้ว่าเดี๋ยวนี้จําเป็นที่ท่านจะต้องเป็นทุกข์ใจชั่วขณะหนึ่ง ด้วยการถูกทดลองต่างๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 7, 'เพื่อการลองดูความเชื่อของท่าน อันประเสริฐยิ่งกว่าทองคําซึ่งพินาศไปได้ ถึงแม้ว่าความเชื่อนั้นถูกลองด้วยไฟ จะได้เป็นเหตุให้เกิดความสรรเสริญ เกิดเกียรติและสง่าราศี ในเวลาที่พระเยซูคริสต์จะเสด็จมาปรากฏ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 8, 'พระองค์ผู้ที่ท่านทั้งหลายยังไม่ได้เห็น แต่ท่านยังรักพระองค์อยู่ แม้ว่าขณะนี้ท่านไม่เห็นพระองค์ แต่ท่านยังเชื่อและชื่นชม ด้วยความปีติยินดีเป็นล้นพ้นเหลือที่จะกล่าวได้ และเต็มเปี่ยมด้วยสง่าราศี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 9, 'แล้วจิตวิญญาณของท่านทั้งหลายจึงได้รับความรอดเป็นผลสุดท้ายแห่งความเชื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 10, 'พวกศาสดาพยากรณ์ก็ได้อุตส่าห์สืบค้นหาในความรอดนั้น และได้พยากรณ์ถึงพระคุณซึ่งจะบังเกิดแก่ท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 11, 'เขาได้สืบค้นหาสิ่งใดหรือลักษณะแห่งเวลาซึ่งพระวิญญาณของพระคริสต์ ผู้ทรงสถิตอยู่ในตัวเขา ได้ทรงบ่งไว้ เมื่อพระวิญญาณนั้นได้พยากรณ์ล่วงหน้าถึงความทุกข์ทรมานของพระคริสต์ และถึงสง่าราศีที่จะมาภายหลัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 12, 'ก็ทรงโปรดเผยให้พวกศาสดาพยากรณ์เหล่านั้นทราบว่า ที่เขาเหล่านั้นได้ปรนนิบัติในเหตุการณ์ทั้งปวงนั้น ไม่ใช่สําหรับเขาเอง แต่สําหรับเราทั้งหลาย บัดนี้คนเหล่านั้นที่ประกาศข่าวประเสริฐแก่ท่านทั้งหลาย ก็ได้กล่าวสิ่งเหล่านั้นแก่ท่านแล้วโดยพระวิญญาณบริสุทธิ์ ที่ทรงโปรดประทานจากสวรรค์ เป็นสิ่งซึ่งพวกทูตสวรรค์ปรารถนาจะได้ดู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 13, 'เหตุฉะนั้น ท่านทั้งหลายจงเตรียมตัวเตรียมใจของท่านไว้ให้ดี และจงข่มใจ ตั้งความหวังให้เต็มเปี่ยมในพระคุณซึ่งจะทรงโปรดประทานแก่ท่านเมื่อพระเยซูคริสต์จะทรงสําแดงพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 14, 'ดุจดังเป็นบุตรที่เชื่อฟัง ขออย่าได้ประพฤติตามราคะตัณหาอย่างที่เกิดจากความโง่เขลาของท่านในกาลก่อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 15, 'แต่พระองค์ผู้ได้ทรงเรียกท่านทั้งหลายนั้นบริสุทธิ์ฉันใด ท่านทั้งหลายจงเป็นคนบริสุทธิ์ในบรรดาการประพฤติทุกอย่างด้วยฉันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 16, 'ดังที่มีคําเขียนไว้แล้วว่า ‘ท่านทั้งหลายจงเป็นคนบริสุทธิ์ เพราะเราเป็นผู้บริสุทธิ์’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 17, 'และถ้าท่านอธิษฐานขอต่อพระบิดา ผู้ทรงพิพากษาทุกคนตามการกระทําของเขาโดยไม่เห็นแก่หน้าคนใดเลย จงประพฤติตนด้วยความยําเกรงตลอดเวลาที่ท่านอยู่ในโลกนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 18, 'ท่านรู้ว่า พระองค์ได้ทรงไถ่ท่านทั้งหลายออกจากการประพฤติอันหาสาระมิได้ ซึ่งท่านได้รับเป็นประเพณีต่อจากบรรพบุรุษของท่าน มิได้ไถ่ไว้ด้วยสิ่งที่เสื่อมสลายได้ เช่นเงินและทอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 19, 'แต่ทรงไถ่ด้วยพระโลหิตอันมีราคามากของพระคริสต์ ดังเลือดลูกแกะที่ปราศจากตําหนิหรือจุดด่างพร้อย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 20, 'แท้จริงพระเจ้าได้ทรงดําริพระคริสต์นั้นไว้ก่อนทรงสร้างโลก แต่ทรงให้พระคริสต์ปรากฏพระองค์ในวาระสุดท้ายนี้ เพื่อท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 21, 'เพราะพระคริสต์ท่านจึงเชื่อในพระเจ้า ผู้ทรงบันดาลพระคริสต์ให้ฟื้นจากความตาย และทรงประทานสง่าราศีแก่พระองค์ เพื่อให้ความเชื่อและความหวังใจของท่านดํารงอยู่ในพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 22, 'ที่ท่านทั้งหลายได้ชําระจิตใจของท่านให้บริสุทธิ์แล้ว ด้วยการเชื่อฟังความจริงโดยพระวิญญาณ จนมีใจรักพวกพี่น้องอย่างจริงใจ ท่านทั้งหลายจงรักกันให้มากด้วยน้ําใสใจจริง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 23, 'ด้วยว่าท่านทั้งหลายได้บังเกิดใหม่ ไม่ใช่จากพืชที่จะเปื่อยเน่าเสีย แต่จากพืชอันไม่รู้เปื่อยเน่า คือด้วยพระวจนะของพระเจ้าอันทรงชีวิตและดํารงอยู่เป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 24, 'เพราะว่า ‘บรรดาเนื้อหนังก็เป็นเสมือนต้นหญ้า และบรรดาสง่าราศีของมนุษย์ก็เป็นเสมือนดอกหญ้า ต้นหญ้าเหี่ยวแห้งไป และดอกก็ร่วงโรยไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 25, 'แต่พระวจนะขององค์พระผู้เป็นเจ้ายั่งยืนอยู่เป็นนิตย์’ พระวจนะนั้นคือข่าวประเสริฐที่ได้ประกาศให้ท่านทั้งหลายทราบแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 1, 'เหตุฉะนั้น ท่านทั้งหลายจงละการปองร้ายทั้งปวง บรรดาการอุบาย การหน้าซื่อใจคด ความอิจฉาริษยา และคําพูดส่อเสียดทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 2, 'เช่นเดียวกับทารกแรกเกิด จงปรารถนาน้ํานมอันบริสุทธิ์แห่งพระวจนะ เพื่อจะทําให้ท่านทั้งหลายเติบโตขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 3, 'หากว่าท่านได้ชิมดูรู้แล้วว่าองค์พระผู้เป็นเจ้าประกอบด้วยพระกรุณา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 4, 'จงมาหาพระองค์ เหมือนมาถึงศิลาอันมีชีวิตอยู่ ซึ่งมนุษย์ได้ปฏิเสธไม่ยอมรับแล้ว แต่ว่าพระเจ้าทรงเลือกไว้ และทรงค่าอันประเสริฐ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 5, 'และท่านทั้งหลายก็เสมือนศิลาที่มีชีวิต ที่กําลังก่อขึ้นเป็นพระนิเวศฝ่ายวิญญาณ เป็นปุโรหิตบริสุทธิ์ เพื่อถวายสักการบูชาฝ่ายจิตวิญญาณ ที่ชอบพระทัยของพระเจ้าโดยทางพระเยซูคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 6, 'เพราะมีคําเขียนไว้ในพระคัมภีร์ด้วยว่า ‘ดูเถิด เราวางศิลาก้อนหนึ่งลงในศิโยน เป็นศิลามุมเอกที่ทรงเลือกแล้ว และเป็นศิลาที่มีค่าอันประเสริฐ และผู้ใดที่เชื่อในพระองค์นั้นก็จะไม่ได้รับความอับอาย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 7, 'เหตุฉะนั้นพระองค์ทรงมีค่าอันประเสริฐสําหรับท่านทั้งหลายที่เชื่อ แต่สําหรับคนทั้งหลายที่ไม่เชื่อฟังนั้น ‘ศิลาซึ่งช่างก่อได้ปฏิเสธเสีย ได้กลับกลายเป็นศิลามุมเอกแล้ว’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 8, 'และ ‘เป็นศิลาที่ทําให้สะดุด และเป็นก้อนหินที่ทําให้ขุ่นเคืองใจ’ ที่เขาสะดุดนั้นเพราะเขาไม่เชื่อฟังพระวจนะ ตามที่เขาถูกกําหนดไว้เช่นนั้นด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 9, 'แต่ท่านทั้งหลายเป็นชาติที่พระองค์ทรงเลือกไว้แล้ว เป็นพวกปุโรหิตหลวง เป็นประชาชาติบริสุทธิ์ เป็นชนชาติของพระองค์โดยเฉพาะ เพื่อท่านทั้งหลายจะได้สําแดงพระบารมีของพระองค์ ผู้ได้ทรงเรียกท่านทั้งหลายให้ออกมาจากความมืด เข้าไปสู่ความสว่างอันมหัศจรรย์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 10, 'เมื่อก่อนท่านทั้งหลายหาเป็นชนชาติไม่ แต่บัดนี้ท่านเป็นชนชาติของพระเจ้าแล้ว เมื่อก่อนท่านทั้งหลายหาได้รับพระกรุณาไม่ แต่บัดนี้ท่านได้รับพระกรุณาแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 11, 'พวกที่รัก ข้าพเจ้าวิงวอนท่านทั้งหลายเหมือนท่านเป็นคนต่างด้าวและเป็นผู้สัญจร ให้ท่านละเว้นจากตัณหาของเนื้อหนัง ซึ่งทําศึกกับจิตวิญญาณ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 12, 'จงให้การประพฤติของท่านทั้งหลายเป็นที่น่านับถือท่ามกลางคนต่างชาตินั้น เพื่อว่าในข้อที่เขาติเตียนท่านว่าเป็นคนทําชั่วนั้น เมื่อเขาเห็นการดีของท่านแล้ว เขาจะได้สรรเสริญพระเจ้าในวันซึ่งพระองค์จะทรงเยี่ยมเยียนเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 13, 'ท่านทั้งหลายจงยอมฟังการบังคับบัญชาที่มนุษย์ตั้งไว้ทุกอย่าง เพราะเห็นแก่องค์พระผู้เป็นเจ้า ไม่ว่าผู้นั้นเป็นกษัตริย์ผู้มีอํานาจยิ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 14, 'หรือจะเป็นเจ้าเมืองผู้ที่ได้รับคําสั่งจากกษัตริย์นั้น ให้ลงโทษผู้กระทําชั่ว และยกย่องคนที่ประพฤติดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 15, 'เพราะเป็นพระประสงค์ของพระเจ้า ที่จะให้ท่านทั้งหลายระงับความโง่ของคนโฉดเขลาให้สงบด้วยการประพฤติดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 16, 'จงเป็นเหมือนคนที่มีเสรีภาพ แต่ท่านอย่าใช้เสรีภาพนั้นให้เป็นที่ปกปิดความชั่วไว้ แต่จงใช้เหมือนเป็นทาสของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 17, 'จงให้เกียรติแก่ทุกคน จงรักบรรดาพี่น้อง จงยําเกรงพระเจ้า จงถวายเกียรติแด่กษัตริย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 18, 'ท่านทั้งหลายที่เป็นผู้รับใช้ จงเชื่อฟังนายของท่านด้วยความยําเกรงทุกอย่าง ไม่ใช่เฉพาะนายที่เป็นคนใจดีและสุภาพเท่านั้น แต่ทั้งนายที่ร้ายด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 19, 'ด้วยว่าถ้าผู้ใด เพราะเห็นแก่ใจวินิจฉัยผิดชอบจําเพาะพระเจ้า ยอมอดทนต่อความทุกข์โศกเศร้าอย่างไม่ยุติธรรม นี่แหละเป็นความชอบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 20, 'ด้วยว่าถ้าท่านทําการชั่ว แล้วถูกเฆี่ยนเพราะการชั่วนั้น แม้ท่านทนถูกเฆี่ยนด้วยอดกลั้นใจ จะเป็นที่สรรเสริญอะไรแก่ท่าน แต่ว่าถ้าท่านทั้งหลายกระทําการดี และทนเอาการข่มเหงด้วยอดกลั้นใจเพราะการดีนั้น เช่นนี้แหละเป็นการชอบพระทัยพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 21, 'ด้วยว่าท่านทั้งหลายทรงถูกเรียกไว้สําหรับเหตุการณ์นั้น เพราะว่าพระคริสต์ได้ทรงรับทนทุกข์ทรมานเพื่อเราทั้งหลาย ให้เป็นแบบอย่างแก่เรา เพื่อท่านจะได้ตามรอยพระบาทของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 22, 'พระองค์ไม่ได้ทรงกระทําบาปเลย และไม่ได้พบอุบายในพระโอษฐ์ของพระองค์เลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 23, 'เมื่อเขากล่าวคําหยาบคายต่อพระองค์ พระองค์ไม่ได้ทรงกล่าวตอบเขาด้วยคําหยาบคายเลย เมื่อพระองค์ทรงทนทุกข์ พระองค์ไม่ได้ทรงมาดร้าย แต่ทรงมอบเรื่องของพระองค์ไว้แด่พระเจ้าผู้ทรงพิพากษาอย่างชอบธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 24, 'พระองค์เองได้ทรงรับแบกบาปของเราไว้ในพระกายของพระองค์ที่ต้นไม้นั้น เพื่อว่าเราทั้งหลายซึ่งตายจากบาปแล้ว จะได้ดําเนินชีวิตตามความชอบธรรม ด้วยรอยเฆี่ยนของพระองค์ ท่านทั้งหลายจึงได้รับการรักษาให้หาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 25, 'เพราะว่าท่านทั้งหลายเป็นเหมือนแกะที่พลัดฝูงไป แต่บัดนี้ได้กลับมาหาพระผู้เลี้ยง และผู้ดูแลแห่งจิตวิญญาณของท่านทั้งหลายแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 1, 'ฝ่ายท่านทั้งหลายที่เป็นภรรยาก็เช่นกัน จงเชื่อฟังสามีของท่าน เพื่อว่าแม้สามีบางคนจะไม่เชื่อฟังพระวจนะ แต่ความประพฤติของภรรยาก็อาจจะจูงใจเขาได้ด้วยโดยไม่ต้องใช้พระวจนะนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 2, 'คือเมื่อเขาเห็นการประพฤติอันบริสุทธิ์ของท่านทั้งหลาย ผู้เป็นภรรยาประกอบกับความยําเกรง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 3, 'การประดับกายของท่านนั้น อย่าให้เป็นการประดับภายนอก คือการถักผม ประดับด้วยเครื่องทองคํา และนุ่งห่มเสื้อผ้าสวยงาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 4, 'แต่จงให้เป็นอย่างคนที่ซ่อนไว้ในจิตใจ ด้วยสิ่งที่ไม่รู้เสื่อมสลาย คือเครื่องประดับแห่งจิตใจที่อ่อนสุภาพและสงบเสงี่ยม ซึ่งเป็นสิ่งที่มีค่ามากในสายพระเนตรพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 5, 'บรรดาสตรีบริสุทธิ์ในครั้งโบราณนั้นเช่นกัน ผู้ซึ่งวางใจในพระเจ้า ก็ได้ประดับกายเช่นกันและเชื่อฟังสามีของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 6, 'เช่นนางซาราห์เชื่อฟังอับราฮัมและเรียกท่านว่านาย ท่านก็เป็นลูกหลานของนาง ถ้าท่านทั้งหลายประพฤติดี และไม่มีความหวาดกลัวพร้อมด้วยตกตะลึงสิ่งใด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 7, 'ฝ่ายท่านทั้งหลายที่เป็นสามีก็เหมือนกัน จงอยู่กินกับภรรยาโดยใช้ความรู้ จงให้เกียรติแก่ภรรยาเหมือนหนึ่งเป็นภาชนะที่อ่อนแอกว่า และเหมือนเป็นคู่รับมรดกพระคุณแห่งชีวิตด้วยกัน เพื่อจะได้ไม่มีสิ่งหนึ่งสิ่งใดขัดขวางคําอธิษฐานของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 8, 'ในที่สุดนี้ ท่านทั้งหลายจงเป็นน้ําหนึ่งใจเดียวกัน เห็นอกเห็นใจกัน รักกันฉันพี่น้อง มีจิตใจอ่อนโยน มีใจสุภาพ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 9, 'อย่าทําการร้ายตอบแทนการร้าย อย่าด่าตอบการด่า แต่ตรงกันข้ามจงอวยพรแก่เขา โดยรู้อยู่ว่าพระองค์ได้ทรงเรียกท่านกระทําเช่นนั้น เพื่อท่านจะได้รับพระพรเป็นมรดก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 10, 'เพราะว่า ‘ผู้ที่จะรักชีวิตและปรารถนาที่จะเห็นวันดี ก็ให้ผู้นั้นบังคับลิ้นของตนจากความชั่ว และห้ามริมฝีปากไม่พูดเป็นอุบายล่อลวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 11, 'ให้เขาละความชั่วและกระทําความดี แสวงหาความสงบสุขและดําเนินตามนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 12, 'เพราะว่าพระเนตรขององค์พระผู้เป็นเจ้าทรงเฝ้าดูคนชอบธรรม และพระกรรณของพระองค์ทรงสดับฟังคําอธิษฐานของเขา แต่พระพักตร์ขององค์พระผู้เป็นเจ้าทรงตั้งต่อสู้กับคนทั้งหลายที่ทําความชั่ว’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 13, 'ถ้าท่านทั้งหลายใฝ่ใจประพฤติความดี ใครผู้ใดจะทําร้ายท่านได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 14, 'แต่ถ้าท่านทั้งหลายต้องทนทุกข์ เพราะเหตุการชอบธรรม ท่านก็เป็นสุข อย่ากลัวคําขู่ของเขา และอย่าคิดวิตกไปเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 15, 'แต่ในใจของท่าน จงเคารพนับถือพระเจ้าซึ่งเป็นองค์พระผู้เป็นเจ้า และจงเตรียมตัวไว้ให้พร้อมเสมอ เพื่อท่านจะสามารถตอบทุกคนที่ถามท่านว่า ท่านมีความหวังใจเช่นนี้ด้วยเหตุผลประการใด แต่จงตอบด้วยใจสุภาพและด้วยความยําเกรง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 16, 'มีใจวินิจฉัยผิดและชอบอันดี เพื่อในข้อความที่เขาทั้งหลายได้พูดใส่ร้ายท่านเหมือนเป็นผู้ประพฤติชั่ว เขาที่ใส่ร้ายการประพฤติดีของท่านในพระคริสต์จะได้มีความละอาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 17, 'เพราะว่า การได้รับความทุกข์เพราะทําความดี ถ้าเป็นที่ชอบพระทัยพระเจ้า ก็ดีกว่าจะต้องทนอยู่เพราะการประพฤติชั่ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 18, 'ด้วยว่า พระคริสต์เช่นกันก็ได้ทนทุกข์ครั้งเดียวเท่านั้น เพราะความผิดบาป คือพระองค์ผู้ชอบธรรมเพื่อผู้ไม่ชอบธรรม เพื่อพระองค์จะได้ทรงนําเราทั้งหลายไปถึงพระเจ้า ฝ่ายเนื้อหนังพระองค์ก็ทรงสิ้นพระชนม์ แต่ทรงมีชีวิตขึ้นโดยพระวิญญาณ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 19, 'และโดยพระวิญญาณเช่นกัน พระองค์ได้เสด็จไปประกาศแก่วิญญาณที่ติดคุกอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 20, 'ซึ่งแต่ก่อนไม่ได้เชื่อฟัง คราวเมื่อพระเจ้าทรงโปรดงดโทษไว้นาน คือครั้งโนอาห์ เมื่อกําลังจัดแจงต่อนาวา ในนาวานั้นได้รอดจากน้ําน้อยคน คือแปดคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 21, 'เช่นเดียวกัน บัดนี้พิธีบัพติศมาก็เป็นภาพที่รอดแก่เราทั้งหลาย (ไม่ใช่ด้วยชําระราคีแห่งเนื้อหนัง แต่โดยให้มีใจวินิจฉัยผิดและชอบอันดีจําเพาะพระเจ้า) โดยซึ่งพระเยซูคริสต์ได้ทรงเป็นขึ้นมาจากตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 22, 'พระองค์ได้เสด็จเข้าในสวรรค์แล้ว และสถิตอยู่เบื้องขวาพระหัตถ์ของพระเจ้า พวกทูตสวรรค์และผู้มีอํานาจและผู้มีฤทธิ์เดชทั้งหลาย ทรงมอบไว้ให้อยู่ใต้อํานาจของพระองค์แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 1, 'ฉะนั้น โดยเหตุที่พระคริสต์ได้ทรงทนทุกข์ทรมานในเนื้อหนังเพื่อเราทั้งหลายแล้ว ท่านทั้งหลายก็จงมีความคิดอย่างเดียวกันไว้เป็นเครื่องอาวุธด้วย เพราะว่าผู้ที่ได้ทนทุกข์ทรมานในเนื้อหนังก็ไม่สัมพันธ์กับบาปแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 2, 'เพื่อเขาจะได้ไม่ดําเนินชีวิตที่ยังเหลืออยู่ในเนื้อหนังตามใจปรารถนาของมนุษย์ แต่ตามพระประสงค์ของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 3, 'ด้วยว่าเวลาที่ผ่านไปในชีวิตของเราแล้วนั้น น่าจะเพียงพอสําหรับการกระทําสิ่งที่คนต่างชาติชอบกระทํา คราวเมื่อเราได้ดําเนินตามกิเลสตัณหา ตามใจปรารถนาอันชั่ว เมาเหล้าองุ่น เฮฮาเอะอะเอ็ดตะโรกัน เลี้ยงกันอย่างหรูหราฟุ่มเฟือย และการไหว้รูปเคารพอันเป็นที่น่าเกลียด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 4, 'เขาประหลาดใจที่บัดนี้ท่านทั้งหลายไม่ได้ประพฤติเหลวไหลมากเหมือนอย่างเขา เขาก็กล่าวร้ายท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 5, 'คนเหล่านั้นจะต้องให้การแก่พระองค์ผู้พร้อมแล้วที่จะทรงพิพากษาทั้งคนเป็นและคนตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 6, 'ด้วยเหตุนี้เอง ข่าวประเสริฐจึงได้ประกาศแม้แก่คนที่ตายไปแล้ว เพื่อเขาจะได้ถูกพิพากษาตามอย่างมนุษย์ในเนื้อหนัง แต่มีชีวิตอยู่ตามอย่างพระเจ้าฝ่ายจิตวิญญาณ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 7, 'แต่สิ่งทั้งปวงใกล้จะถึงวาระที่สุดแล้ว เหตุฉะนั้นท่านทั้งหลายจงสําแดงกิริยาเสงี่ยมเจียมตัว และจงเฝ้าระวังในการอธิษฐาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 8, 'ยิ่งกว่าอะไรทั้งหมดก็จงรักซึ่งกันและกันให้มาก ด้วยว่าความรักก็ปกปิดความผิดไว้มากหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 9, 'ท่านทั้งหลายจงต้อนรับเลี้ยงดูซึ่งกันและกันโดยไม่บ่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 10, 'ตามซึ่งทุกคนได้รับของประทานแล้ว ก็ให้เจือจานของประทานนั้นแก่กันและกัน เหมือนอย่างเจ้าหน้าที่อันดีสําหรับพระคุณต่างๆของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 11, 'ถ้าผู้หนึ่งผู้ใดจะกล่าวสั่งสอน ก็ให้กล่าวตามพระโอวาทของพระเจ้า ถ้าคนใดรับการปรนนิบัติ ก็ให้ปรนนิบัติตามกําลังซึ่งพระเจ้าทรงโปรดประทานนั้น เพื่อว่าพระเจ้าจะทรงได้รับเกียรติในการทั้งปวงโดยพระเยซูคริสต์ การสรรเสริญและไอศวรรยานุภาพจงมีแด่พระองค์ตลอดไปเป็นนิตย์ เอเมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 12, 'ท่านที่รัก อย่าประหลาดใจที่ท่านต้องได้รับความทุกข์ยากอย่างแสนสาหัสเป็นการลองใจ เหมือนหนึ่งว่าเหตุการณ์อันประหลาดได้เกิดขึ้นกับท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 13, 'แต่ว่าท่านทั้งหลายจงชื่นชมยินดีในการที่ท่านได้มีส่วนร่วมในความทุกข์ยากของพระคริสต์ เพื่อว่าเมื่อสง่าราศีของพระองค์ปรากฏขึ้น ท่านทั้งหลายก็จะได้ชื่นชมยินดีเป็นอันมากด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 14, 'ถ้าท่านถูกด่าว่าเพราะพระนามของพระคริสต์ ท่านก็เป็นสุข ด้วยว่าพระวิญญาณแห่งสง่าราศีและของพระเจ้าทรงสถิตอยู่กับท่าน ฝ่ายเขาก็กล่าวร้ายพระองค์ แต่ฝ่ายท่านก็ถวายเกียรติยศแด่พระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 15, 'แต่ว่าอย่าให้มีผู้ใดในพวกท่านได้รับโทษฐานเป็นฆาตกร หรือเป็นขโมย หรือเป็นคนทําร้าย หรือเป็นคนที่เที่ยวยุ่งกับธุระของคนอื่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 16, 'แต่ถ้าผู้ใดถูกการร้ายเพราะเป็นคริสเตียน ก็อย่าให้ผู้นั้นมีความละอายเลย แต่ให้เขาถวายพระเกียรติแด่พระเจ้าเพราะเหตุนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 17, 'ด้วยว่าถึงเวลาแล้วที่การพิพากษาจะต้องเริ่มตั้งต้นที่ครอบครัวของพระเจ้า และถ้าการพิพากษานั้นเริ่มต้นที่พวกเราก่อน ปลายทางของคนเหล่านั้นที่ไม่เชื่อฟังข่าวประเสริฐของพระเจ้าจะเป็นอย่างไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 18, 'และถ้าคนชอบธรรมจะรอดพ้นไปได้อย่างยากเย็นแล้ว คนอธรรมและคนบาปจะไปอยู่ที่ไหน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 19, 'เหตุฉะนั้น ให้คนทั้งหลายที่ทนความทุกข์ยากตามพระประสงค์ของพระเจ้า ฝากจิตใจของตนไว้กับพระองค์ด้วยการประพฤติดี เหมือนหนึ่งฝากไว้กับพระองค์ผู้ทรงสร้างอันสัตย์ซื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 1, 'ข้าพเจ้าจึงตักเตือนบรรดาผู้ปกครองในพวกท่านทั้งหลาย ในฐานะที่ข้าพเจ้าก็เป็นผู้ปกครองคนหนึ่งเช่นกัน และเป็นพยานถึงความทุกข์ทรมานของพระคริสต์ และมีส่วนที่จะรับสง่าราศีอันจะมาปรากฏภายหลังด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 2, 'จงเลี้ยงฝูงแกะของพระเจ้าที่อยู่กับท่าน จงเอาใจใส่ดูแล ไม่ใช่ด้วยความฝืนใจ แต่ด้วยความเต็มใจ ไม่ใช่ด้วยการเห็นแก่ทรัพย์สิ่งของอันเป็นมลทิน แต่ด้วยใจพร้อม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 3, 'และไม่ใช่เหมือนเป็นเจ้านายที่ข่มขี่ผู้รับมรดกของพระเจ้า แต่เป็นแบบอย่างแก่ฝูงแกะนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 4, 'และเมื่อพระผู้เลี้ยงใหญ่จะเสด็จมาปรากฏ ท่านทั้งหลายจะรับมงกุฎแห่งสง่าราศีที่ร่วงโรยไม่ได้เลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 5, 'ในทํานองเดียวกัน ท่านที่อ่อนอาวุโส ก็จงยอมตามผู้อาวุโส อันที่จริงให้ท่านทุกคนคาดเอวไว้ด้วยความถ่อมใจในการปฏิบัติต่อกันและกัน ด้วยว่าพระเจ้าทรงต่อสู้คนเหล่านั้นที่ถือตัวจองหอง แต่พระองค์ทรงประทานพระคุณแก่คนทั้งหลายที่ถ่อมใจลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 6, 'เหตุฉะนั้น ท่านทั้งหลายจงถ่อมใจลงภายใต้พระหัตถ์อันทรงฤทธิ์ของพระเจ้า เพื่อพระองค์จะได้ทรงยกท่านขึ้นเมื่อถึงเวลาอันควร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 7, 'จงละบรรดาความกระวนกระวายของท่านไว้กับพระองค์ เพราะว่าพระองค์ทรงห่วงใยท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 8, 'ท่านทั้งหลายจงเป็นคนใจหนักแน่น จงระวังระไวให้ดี ด้วยว่าศัตรูของท่าน คือพญามาร วนเวียนอยู่รอบๆดุจสิงโตคําราม เที่ยวไปเสาะหาคนที่มันจะกัดกินได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 9, 'จงต่อสู้กับศัตรูนั้นด้วยตั้งใจมั่นคงในความเชื่อ โดยรู้อยู่ว่าความยากลําบากอย่างนั้นก็มีแก่พวกพี่น้องทั้งหลายของท่านที่อยู่ในโลกเช่นเดียวกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 10, 'แต่พระเจ้าแห่งบรรดาพระคุณทั้งปวง ผู้ได้ทรงเรียกให้เราทั้งหลายเข้าในสง่าราศีนิรันดร์ของพระองค์โดยพระเยซูคริสต์ ครั้นท่านทั้งหลายทนทุกข์อยู่หน่อยหนึ่งแล้ว พระองค์เองจะทรงโปรดให้ท่านทั้งหลายถึงที่สําเร็จ ให้ตั้งมั่นคง ให้ท่านมีกําลังมากขึ้น และทรงให้ท่านมีพื้นฐานมั่นคง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 11, 'ขอสง่าราศีและไอศวรรยานุภาพจงมีแด่พระองค์ตลอดไปเป็นนิตย์ เอเมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 12, 'ข้าพเจ้าได้เขียนอย่างย่อๆมาถึงท่านทั้งหลายผ่านทางสิลวานัส ซึ่งข้าพเจ้าถือว่าเป็นพี่น้องที่สัตย์ซื่อคนหนึ่ง เมื่อเตือนสติและเป็นพยานแก่ท่านทั้งหลายว่า พระคุณนั้นเป็นพระคุณที่แท้จริงของพระเจ้า ซึ่งท่านทั้งหลายก็ยืนหยัดอยู่ในพระคุณนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 13, 'คริสตจักรที่เมืองบาบิโลน ซึ่งทรงเลือกไว้เช่นเดียวกันกับท่านทั้งหลาย ฝากความคิดถึงมายังท่าน และมาระโกบุตรชายของข้าพเจ้าก็ฝากความคิดถึงมายังท่านด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 14, 'จงทักทายกันด้วยธรรมเนียมจุบอันแสดงความรักต่อกัน ขอสันติสุขดํารงอยู่กับท่านทั้งหลายที่อยู่ในพระเยซูคริสต์ เอเมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 1, 'ซีโมนเปโตร ผู้รับใช้และอัครสาวกของพระเยซูคริสต์ เรียน ท่านทั้งหลายที่ได้รับความเชื่ออันประเสริฐอย่างเดียวกันกับเรา โดยความชอบธรรมของพระเจ้าและพระเยซูคริสต์พระผู้ช่วยให้รอดของเราทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 2, 'ขอพระคุณและสันติสุขจงเพิ่มพูนแก่ท่านทั้งหลาย โดยรู้จักพระเจ้าและพระเยซูองค์พระผู้เป็นเจ้าของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 3, 'ด้วยเห็นแล้วว่าฤทธิ์เดชอันศักดิ์สิทธิ์ของพระองค์ ได้ให้สิ่งสารพัดแก่เราที่จะให้มีชีวิตและทางที่เป็นอย่างพระเจ้า โดยรู้จักพระองค์ผู้ได้ทรงเรียกเราให้ถึงสง่าราศีและคุณธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 4, 'ด้วยเหตุเหล่านี้พระองค์จึงได้ทรงประทานพระสัญญาอันประเสริฐและใหญ่ยิ่งแก่เรา เพื่อว่าด้วยพระสัญญาเหล่านี้ ท่านทั้งหลายจะพ้นจากความเสื่อมโทรมที่มีอยู่ในโลกนี้เพราะตัณหา และจะได้รับส่วนในสภาพของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 5, 'เพราะเหตุนี้เองท่านจงอุตส่าห์จนสุดกําลังที่จะเอาคุณธรรมเพิ่มความเชื่อ เอาความรู้เพิ่มคุณธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 6, 'เอาความเหนี่ยวรั้งตนเพิ่มความรู้ เอาความอดทนเพิ่มความเหนี่ยวรั้งตน เอาการที่เป็นอย่างพระเจ้าเพิ่มความอดทน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 7, 'เอาความรักฉันพี่น้องเพิ่มการที่เป็นอย่างพระเจ้า และเอาความรักคนทั่วไปเพิ่มความรักฉันพี่น้อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 8, 'เพราะถ้ามีใจอย่างนั้นอยู่ในท่านทั้งหลายพร้อมบริบูรณ์แล้ว ก็จะกระทําให้ท่านไม่เกียจคร้านหรือไร้ผลในความรู้แห่งพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 9, 'เพราะว่าผู้ใดที่ขาดสิ่งเหล่านี้ก็เป็นคนตาบอดตาสั้น และลืมไปว่าตนได้รับการชําระจากความผิดบาปเมื่อก่อนนั้นเสียแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 10, 'เพราะฉะนั้น พี่น้องทั้งหลาย จงยิ่งอุตส่าห์กระทําตนให้เป็นไปตามที่พระเจ้าทรงเรียก และทรงเลือกท่านไว้แล้วนั้น เพราะว่าถ้าท่านประพฤติเช่นนั้น ท่านจะไม่สะดุดล้มเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 11, 'ด้วยว่าอย่างนั้นท่านทั้งหลายจะมีสิทธิสมบูรณ์ที่จะเข้าในอาณาจักรนิรันดร์ของพระเยซูคริสต์องค์พระผู้เป็นเจ้า และพระผู้ช่วยให้รอดของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 12, 'เหตุฉะนั้น ถึงแม้ว่าท่านจะรู้และตั้งมั่นคงอยู่ในความจริงที่ท่านรับแล้วนั้นก็ดี ข้าพเจ้าก็ไม่ละเลยที่จะเตือนสติท่านทั้งหลายเสมอให้ระลึกถึงสิ่งเหล่านี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 13, 'ตราบใดที่ข้าพเจ้ายังอาศัยอยู่ในพลับพลานี้ ข้าพเจ้าเห็นสมควรที่จะเตือนสติท่านทั้งหลายให้ระลึกถึงข้อความเหล่านี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 14, 'เพราะข้าพเจ้ารู้ว่า อีกไม่ช้าข้าพเจ้าก็จะต้องสละทิ้งพลับพลาของข้าพเจ้าไป ดังที่พระเยซูคริสต์องค์พระผู้เป็นเจ้าของเราได้ทรงสําแดงแก่ข้าพเจ้าแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 15, 'ยิ่งกว่านั้นข้าพเจ้าจะอุตส่าห์กระทําให้ท่านทั้งหลายระลึกถึงสิ่งเหล่านี้เสมอเมื่อข้าพเจ้าตายแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 16, 'เพราะว่าเมื่อเราได้สําแดงให้ท่านทั้งหลายทราบถึงฤทธิ์เดชของพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเรา และการที่พระองค์จะเสด็จมานั้น เราไม่ได้คล้อยตามนิยายที่เขาคิดแต่งไว้ด้วยความเฉลียวฉลาด แต่เราได้เห็นอานุภาพของพระองค์ด้วยตาของเราเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 17, 'เพราะว่าคราวเมื่อพระองค์ได้ทรงรับเกียรติและสง่าราศีจากพระเจ้าพระบิดา เมื่อพระสุรเสียงจากสง่าราศีอันยิ่งใหญ่ได้มาถึงพระองค์ ตรัสแก่พระองค์ว่า “ท่านผู้นี้เป็นบุตรที่รักของเรา เราชอบใจท่านผู้นี้มาก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 18, 'และเราก็ได้ยินพระสุรเสียงนี้มาจากสวรรค์ ในครั้งที่เราได้อยู่กับพระองค์ที่ภูเขาอันบริสุทธิ์นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 19, 'และเรามีคําพยากรณ์ที่แน่นอนยิ่งกว่านั้นอีก จะเป็นการดีถ้าท่านทั้งหลายจะถือตามคํานั้น เสมือนแสงประทีปที่ส่องสว่างในที่มืด จนกว่าแสงอรุณจะขึ้น และดาวประจํารุ่งจะผุดขึ้นในใจของท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 20, 'จงรู้ข้อนี้ก่อน คือว่าคําพยากรณ์ทุกคําที่จารึกไว้ในพระคัมภีร์แล้ว ไม่มีใครตีความได้ตามลําพังใจของตนเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 21, 'ด้วยว่าคําพยากรณ์ในอดีตนั้นไม่ได้มาจากความประสงค์ของมนุษย์ แต่พวกผู้บริสุทธิ์ของพระเจ้าได้กล่าวคําตามที่พระวิญญาณบริสุทธิ์ได้ทรงดลใจเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 1, 'แต่ว่าได้มีผู้พยากรณ์เท็จท่ามกลางประชาชนทั้งหลายด้วย เช่นเดียวกับที่จะมีอาจารย์เท็จท่ามกลางท่านทั้งหลาย ผู้ซึ่งจะแอบเอาลัทธิที่ออกนอกลู่นอกทางอันจะนําไปสู่ความหายนะเข้ามาด้วย และจะปฏิเสธองค์พระผู้เป็นเจ้าผู้ได้ทรงไถ่เขาไว้ และจะนําความพินาศอย่างฉับพลันมาถึงตนเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 2, 'จะมีหลายคนประพฤติตามทางแห่งการสาปแช่งของเขา และเพราะคนเหล่านั้นเป็นเหตุ ทางแห่งความจริงจะถูกกล่าวร้าย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 3, 'และด้วยความโลภเขาจะกล่าวคําตลบตะแลงเพื่อค้ากําไรจากท่านทั้งหลาย การลงโทษคนเหล่านั้นที่ได้ถูกพิพากษานานมาแล้วจะไม่เนินช้า และความหายนะของเขาก็จะไม่หลับใหลไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 4, 'เพราะว่า ถ้าพระเจ้าไม่ได้ทรงยกเว้นพวกทูตสวรรค์ที่ได้ทําบาปนั้น แต่ได้ทรงผลักเขาลงไปสู่นรก และได้มัดเขาไว้ด้วยเครื่องจองจําแห่งความมืด คุมไว้จนกว่าจะถึงเวลาทรงพิพากษา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 5, 'และไม่ได้ทรงยกเว้นมนุษย์โลกครั้งโบราณ แต่ได้ทรงช่วยโนอาห์ผู้ประกาศความชอบธรรมกับคนอื่นอีกเจ็ดคนให้รอด เมื่อคราวที่พระองค์ได้ทรงบันดาลให้น้ําท่วมโลกของคนอธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 6, 'และได้ทรงลงโทษเมืองโสโดมและเมืองโกโมราห์ให้พินาศเป็นเถ้าถ่าน เพื่อให้เป็นตัวอย่างแก่คนต่อไปที่จะประพฤติชั่ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 7, 'และได้ทรงช่วยโลทผู้ชอบธรรมให้รอด ผู้มีความทุกข์ใหญ่หลวงเพราะการประพฤติลามกของคนชั่วเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 8, '(ด้วยว่าคนชอบธรรมนั้น ซึ่งได้อาศัยอยู่ในท่ามกลางเขาเหล่านั้น เมื่อท่านได้เห็นและได้ยิน จิตใจที่ชอบธรรมของท่านก็เป็นทุกข์เป็นร้อนทุกวันๆเพราะการประพฤติชั่วของคนเหล่านั้น)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 9, 'องค์พระผู้เป็นเจ้าทรงทราบวิธีที่จะช่วยคนที่ตามทางของพระเจ้าให้รอดพ้นจากการทดลองต่างๆ และทรงทราบวิธีที่จะรักษาคนอธรรมไว้จนถึงวันพิพากษาเพื่อจะได้ลงโทษเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 10, 'โดยเฉพาะคนเหล่านั้นที่ปล่อยตัวไปตามเนื้อหนัง ในราคะตัณหาแห่งความโสโครก และหมิ่นประมาทผู้ใหญ่ที่มีอํานาจ คนเหล่านี้ทะนงตนและประพฤติตามอําเภอใจ เขาไม่สะทกสะท้านที่จะกล่าวประณามผู้ที่มีบรรดาศักดิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 11, 'แต่ฝ่ายทูตสวรรค์แม้ว่ามีฤทธิ์และกําลังมากกว่า ก็หาได้กล่าวประณามคนเหล่านั้นหน้าพระพักตร์ขององค์พระผู้เป็นเจ้าไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 12, 'แต่ว่าคนเหล่านั้นเป็นเหมือนสัตว์เดียรัจฉานที่ปราศจากความคิด เป็นสัตว์ที่ทําตามสัญชาตญาณ เกิดมาเพื่อถูกจับและถูกฆ่า เขากล่าวประณามสิ่งที่เขาไม่เข้าใจเลย เขาจะต้องพินาศในการชั่วร้ายของตนเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 13, 'และจะรับบําเหน็จแห่งการอธรรม เหมือนคนที่ถือการเสเพลเฮฮาในเวลากลางวันเป็นความเพลิดเพลิน เขาด่างพร้อยและมลทิน และประพฤติการเสเพลเฮฮาด้วยการหลอกลวงของตนเอง เมื่อกําลังกินเลี้ยงรวมกับท่านทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 14, 'ตาเขาเต็มไปด้วยความปรารถนาแห่งการล่วงประเวณี และเขาหยุดกระทําบาปไม่ได้เลย เขาวางกับดักคนที่มีจิตใจไม่มั่นคง เขามีใจชินกับการโลภ เขาเป็นลูกแห่งความสาปแช่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 15, 'เขาสละทิ้งทางถูกต้อง หลงไปในทางผิด ดําเนินตามทางของบาลาอัมบุตรชายเบโอร์ ผู้ที่ชอบบําเหน็จแห่งการอธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 16, 'แต่บาลาอัมก็ได้ถูกติเพราะการที่เขาได้กระทําความชั่วช้านั้น ลาใบ้ตัวนั้นพูดเป็นภาษามนุษย์ และได้ยับยั้งอาการคลุ้มคลั่งของศาสดาพยากรณ์คนนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 17, 'คนเหล่านี้เป็นบ่อที่ไร้น้ํา เป็นเมฆที่ถูกพายุพัดไป ทรงเตรียมหมอกแห่งความมืดทึบไว้แล้วสําหรับคนเหล่านั้นเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 18, 'เพราะว่าเขาพูดเย่อหยิ่งอวดตัว และเขาใช้ความปรารถนาแห่งเนื้อหนังกับความกําหนัด เพื่อจะล่อลวงคนทั้งหลายที่กําลังหนีไปจากคนเหล่านั้นที่หลงประพฤติผิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 19, 'เขาสัญญาว่าจะให้คนเหล่านั้นพ้นจากการเป็นทาส แต่ตัวเขาเองยังเป็นทาสของความหายนะ เพราะว่ามนุษย์พ่ายแพ้แก่สิ่งใด เขาก็เป็นทาสของสิ่งนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 20, 'เพราะว่าถ้าหลังจากที่เขาพ้นจากสรรพมลทินของโลกนี้แล้ว ด้วยการที่เขารู้เกี่ยวกับพระเยซูคริสต์องค์พระผู้เป็นเจ้า และพระผู้ช่วยให้รอด เขากลับเกี่ยวข้องและพ่ายแพ้แก่การชั่วนั้นอีก บั้นปลายของเขาก็กลับชั่วร้ายยิ่งกว่าตอนต้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 21, 'เพราะว่าถ้าเขาไม่ได้รู้จักทางชอบธรรมนั้นเสียเลยก็ยังจะดีกว่าที่เขาได้รู้แล้ว แต่กลับหันหลังให้พระบัญญัติอันบริสุทธิ์ที่ได้ทรงโปรดประทานให้แก่เขานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 22, 'พฤติกรรมได้เกิดกับเขาตามสุภาษิตซึ่งเป็นความจริงว่า “สุนัขได้กลับกินสิ่งที่มันสํารอกออกมาแล้ว และสุกรที่ได้ชําระล้างตัวแล้วก็กลับลุยลงไปนอนในปลักอีก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 1, 'บัดนี้ พวกที่รัก นี่เป็นจดหมายฉบับที่สองที่ข้าพเจ้าได้เขียนถึงท่านทั้งหลาย และในจดหมายทั้งสองฉบับนั้น ข้าพเจ้าได้สะกิดใจอันบริสุทธิ์ของท่านให้ระลึก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 2, 'เพื่อท่านทั้งหลายจะได้ใส่ใจถ้อยคําทั้งหลายที่พวกศาสดาพยากรณ์อันบริสุทธิ์ได้กล่าวไว้เมื่อก่อน และคําบัญชาของเราทั้งหลายพวกอัครสาวกขององค์พระผู้เป็นเจ้าและพระผู้ช่วยให้รอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 3, 'จงรู้ข้อนี้ก่อน คือในวันสุดท้ายคนที่ชอบเยาะเย้ยจะเกิดขึ้นและดําเนินตามใจปรารถนาชั่วของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 4, 'และจะถามว่า “คําที่ทรงสัญญาไว้ว่าพระองค์จะเสด็จมานั้นอยู่ที่ไหน เพราะว่าตั้งแต่บรรพบุรุษหลับล่วงไปแล้ว สิ่งทั้งปวงก็เป็นอยู่เหมือนที่ได้เป็นอยู่ตั้งแต่เดิมทรงสร้างโลก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 5, 'เพราะว่าเขาแกล้งลืมข้อนี้เสีย คือโดยคําตรัสของพระเจ้า ฟ้าสวรรค์ได้อุบัติขึ้นตั้งแต่โบราณ และแผ่นดินโลกจึงได้บังเกิดขึ้นแยกออกจากน้ําและท่ามกลางน้ํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 6, 'โดยเหตุเหล่านั้น พระองค์จึงได้ทรงบันดาลให้น้ํามาท่วมทําลายโลกที่มีอยู่ในเวลานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 7, 'แต่ว่าท้องฟ้าอากาศและแผ่นดินโลกที่อยู่เดี๋ยวนี้ พระองค์ทรงเก็บงําไว้โดยคําตรัสนั้นสําหรับให้ไฟเผา คือเก็บไว้จนถึงวันทรงพิพากษาและวันพินาศแห่งบรรดาคนอธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 8, 'แต่พวกที่รัก อย่าลืมข้อนี้เสีย คือวันเดียวขององค์พระผู้เป็นเจ้าเป็นเหมือนกับพันปี และพันปีก็เป็นเหมือนกับวันเดียว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 9, 'องค์พระผู้เป็นเจ้าไม่ได้ทรงเฉื่อยช้าในเรื่องพระสัญญาของพระองค์ ตามที่บางคนคิดนั้น แต่พระองค์ได้ทรงอดกลั้นพระทัยไว้ เพราะเห็นแก่เราทั้งหลายมาช้านาน ไม่ทรงประสงค์ที่จะให้ผู้หนึ่งผู้ใดพินาศเลย แต่ทรงปรารถนาที่จะให้คนทั้งปวงกลับใจเสียใหม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 10, 'แต่ว่าวันขององค์พระผู้เป็นเจ้านั้นจะมาถึงเหมือนอย่างขโมยแอบย่องมาในเวลากลางคืน และในวันนั้นท้องฟ้าจะล่วงเสียไปด้วยเสียงที่ดังกึกก้อง และโลกธาตุจะสลายไปด้วยความร้อนอันแรงกล้า และแผ่นดินโลกกับการงานทั้งปวงที่มีอยู่ในนั้นจะต้องไหม้เสียสิ้นด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 11, 'เมื่อเห็นแล้วว่าสิ่งทั้งปวงจะต้องสลายไปหมดสิ้นเช่นนี้ ท่านทั้งหลายควรจะเป็นคนเช่นใดในชีวิตที่บริสุทธิ์และที่เป็นอย่างพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 12, 'คอยท่าและเร่งที่จะให้วันของพระเจ้ามาถึง เมื่อไฟจะติดท้องฟ้าอากาศให้ละลายไป และโลกธาตุจะละลายไปด้วยไฟอันร้อนยิ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 13, 'แต่ว่าตามพระสัญญาของพระองค์นั้น เราจึงคอยท้องฟ้าอากาศใหม่และแผ่นดินโลกใหม่ ที่ซึ่งความชอบธรรมจะดํารงอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 14, 'เหตุฉะนั้นพวกที่รัก เมื่อท่านทั้งหลายยังคอยสิ่งเหล่านี้อยู่ ท่านก็จงอุตส่าห์ให้พระองค์ทรงพบท่านทั้งหลายอยู่เป็นสุข ปราศจากมลทินและข้อตําหนิ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 15, 'และจงถือว่า การที่องค์พระผู้เป็นเจ้าของเราทรงอดกลั้นพระทัยไว้นานนั้นเป็นการช่วยให้รอด ดังที่เปาโลน้องที่รักของเราได้เขียนจดหมายถึงท่านทั้งหลายด้วย ตามสติปัญญาซึ่งพระองค์ได้ทรงโปรดประทานแก่ท่านนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 16, 'เหมือนในจดหมายของท่านทุกฉบับ ท่านได้กล่าวถึงเหตุการณ์เหล่านั้น และในจดหมายนั้นมีบางข้อที่เข้าใจยาก ซึ่งคนทั้งหลายที่ไม่ได้เรียนรู้และไม่แน่นอนมั่นคงนั้นได้เปลี่ยนแปลงเสีย เหมือนเขาได้เปลี่ยนแปลงข้ออื่นๆในพระคัมภีร์ จึงเป็นเหตุกระทําให้ตัวพินาศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 17, 'เพราะเหตุนั้น พวกที่รัก เมื่อท่านทั้งหลายรู้เรื่องนี้ก่อนแล้ว ท่านก็จงระวังให้ดี เกรงว่าท่านอาจจะหลงไปกระทําผิดตามการผิดของคนชั่ว และท่านทั้งหลายจะสูญเสียความหนักแน่นมั่นคงของท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 18, 'แต่ขอท่านทั้งหลายจงเจริญขึ้นในพระคุณ และในความรู้เกี่ยวกับพระเยซูคริสต์องค์พระผู้เป็นเจ้าและพระผู้ช่วยให้รอดของเรา สง่าราศีจงมีแด่พระองค์ทั้งในปัจจุบันนี้และตลอดไปเป็นนิตย์ เอเมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 1, 'ซึ่งได้ทรงเป็นอยู่ตั้งแต่เริ่มแรก ซึ่งเราทั้งหลายได้ยิน ซึ่งเราได้เห็นกับตา ซึ่งเราได้พินิจดู และจับต้องด้วยมือของเรา เกี่ยวกับพระวาทะแห่งชีวิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 2, '(และชีวิตนั้นได้ปรากฏ และเราได้เห็นและเป็นพยาน และประกาศชีวิตนิรันดร์นั้นแก่ท่านทั้งหลาย ชีวิตนั้นได้ดํารงอยู่กับพระบิดา และได้ปรากฏแก่เราทั้งหลาย)');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 3, 'ซึ่งเราได้เห็นและได้ยินนั้นเราก็ได้ประกาศแก่ท่านทั้งหลาย เพื่อท่านทั้งหลายจะได้ร่วมสามัคคีธรรมกับเรา แท้จริงเราทั้งหลายก็ร่วมสามัคคีธรรมกับพระบิดา และกับพระเยซูคริสต์พระบุตรของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 4, 'และเราเขียนข้อความเหล่านี้ถึงท่านทั้งหลาย เพื่อความยินดีของท่านจะได้เต็มเปี่ยม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 5, 'แล้วนี่เป็นข้อความที่เราได้ยินจากพระองค์ และประกาศแก่ท่านทั้งหลาย คือว่าพระเจ้าทรงเป็นความสว่าง และไม่มีความมืดอยู่ในพระองค์เลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 6, 'ถ้าเราจะว่าเราร่วมสามัคคีธรรมกับพระองค์ และยังดําเนินอยู่ในความมืด เราก็พูดมุสา และไม่ได้ดําเนินชีวิตตามความจริง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 7, 'แต่ถ้าเราดําเนินอยู่ในความสว่าง เหมือนอย่างพระองค์ทรงสถิตในความสว่าง เราก็ร่วมสามัคคีธรรมซึ่งกันและกัน และพระโลหิตของพระเยซูคริสต์พระบุตรของพระองค์ ก็ชําระเราทั้งหลายให้ปราศจากบาปทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 8, 'ถ้าเราทั้งหลายจะว่าเราไม่มีบาป เราก็หลอกตัวเอง และความจริงไม่ได้อยู่ในเราเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 9, 'ถ้าเราสารภาพบาปของเรา พระองค์ทรงสัตย์ซื่อและเที่ยงธรรม ก็จะทรงโปรดยกบาปของเรา และจะทรงชําระเราให้พ้นจากการอธรรมทั้งสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 10, 'ถ้าเรากล่าวว่าเราไม่ได้ทําบาป ก็เท่ากับว่าเราทําให้พระองค์เป็นผู้ตรัสมุสา และพระดํารัสของพระองค์ก็มิได้อยู่ในเราทั้งหลายเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 1, 'ลูกเล็กๆของข้าพเจ้าเอ๋ย ข้าพเจ้าเขียนข้อความเหล่านี้ถึงท่านทั้งหลาย เพื่อท่านจะได้ไม่ทําบาป และถ้าผู้ใดทําบาป เราก็มีพระองค์ผู้ช่วยเหลือสถิตอยู่กับพระบิดา คือพระเยซูคริสต์ผู้ทรงชอบธรรมนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 2, 'และพระองค์ทรงเป็นผู้ลบล้างพระอาชญาที่ตกกับเราทั้งหลายเพราะบาปของเรา และไม่ใช่แต่บาปของเราพวกเดียว แต่บาปของมนุษย์ทั้งปวงในโลกด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 3, 'เราจะมั่นใจได้ว่าเรารู้จักพระองค์โดยข้อนี้ คือถ้าเรารักษาพระบัญญัติของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 4, 'คนใดที่กล่าวว่า “ข้าพเจ้ารู้จักพระองค์” แต่มิได้รักษาพระบัญญัติของพระองค์ คนนั้นก็เป็นคนพูดมุสา และความจริงไม่ได้อยู่ในคนนั้นเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 5, 'แต่ผู้ใดที่รักษาพระวจนะของพระองค์ ความรักของพระเจ้าก็สมบูรณ์อยู่ในคนนั้นอย่างแท้จริง ด้วยอาการอย่างนี้แหละเราทั้งหลายจึงรู้ว่าเราอยู่ในพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 6, 'ผู้ใดกล่าวว่าตนอยู่ในพระองค์ ผู้นั้นก็ควรดําเนินตามทางที่พระองค์ทรงดําเนินนั้นด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 7, 'พี่น้องทั้งหลาย ข้าพเจ้าไม่ได้เขียนพระบัญญัติใหม่ถึงท่านทั้งหลาย แต่เป็นพระบัญญัติเก่าซึ่งท่านทั้งหลายได้มีอยู่ตั้งแต่เริ่มแรก พระบัญญัติเก่านั้นคือพระดํารัสซึ่งท่านทั้งหลายได้ยินตั้งแต่เริ่มแรกแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 8, 'อีกนัยหนึ่ง ข้าพเจ้าเขียนพระบัญญัติใหม่ถึงท่านทั้งหลาย และข้อความนั้นก็เป็นความจริงทั้งฝ่ายพระองค์และฝ่ายท่านทั้งหลาย เพราะว่าความมืดนั้นล่วงไปแล้ว และบัดนี้ความสว่างแท้ก็ส่องอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 9, 'ผู้ใดที่กล่าวว่าตนอยู่ในความสว่าง และยังเกลียดชังพี่น้องของตน ผู้นั้นก็ยังอยู่ในความมืดจนถึงบัดนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 10, 'ผู้ที่รักพี่น้องของตนก็อยู่ในความสว่าง และไม่มีโอกาสที่จะสะดุดสําหรับผู้นั้นเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 11, 'แต่ผู้ที่เกลียดชังพี่น้องของตนก็อยู่ในความมืด และเดินในความมืด และไม่รู้ว่าตนกําลังไปทางไหน เพราะว่าความมืดนั้นได้ทําให้ตาของเขาบอดไปเสียแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 12, 'ลูกเล็กๆทั้งหลายเอ๋ย ข้าพเจ้าเขียนจดหมายถึงท่าน เพราะว่าบาปของท่านได้รับการอภัยแล้วเพราะเห็นแก่พระนามของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 13, 'ท่านทั้งหลายที่เป็นบิดา ข้าพเจ้าเขียนจดหมายถึงท่าน เพราะท่านทั้งหลายได้รู้จักกับพระองค์ผู้ทรงดํารงอยู่ตั้งแต่เริ่มแรก ท่านทั้งหลายที่เป็นคนหนุ่มๆ ข้าพเจ้าเขียนจดหมายถึงท่าน เพราะท่านทั้งหลายได้ชัยชนะแก่มารร้าย ท่านทั้งหลายผู้เป็นลูกเล็กๆ ข้าพเจ้าเขียนจดหมายถึงท่าน เพราะท่านทั้งหลายได้รู้จักกับพระบิดา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 14, 'ท่านทั้งหลายที่เป็นบิดา ข้าพเจ้าเขียนจดหมายถึงท่าน เพราะท่านทั้งหลายได้รู้จักกับพระองค์ผู้ทรงดํารงอยู่ตั้งแต่เริ่มแรก ท่านทั้งหลายที่เป็นคนหนุ่มๆ ข้าพเจ้าเขียนจดหมายถึงท่าน เพราะท่านทั้งหลายมีกําลังมาก และพระวจนะของพระเจ้าดํารงอยู่ในท่านทั้งหลาย และท่านได้ชัยชนะแก่มารร้ายแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 15, 'อย่ารักโลกหรือสิ่งของในโลก ถ้าผู้ใดรักโลก ความรักของพระบิดาไม่ได้อยู่ในผู้นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 16, 'เพราะว่าสารพัดซึ่งมีอยู่ในโลก คือตัณหาของเนื้อหนัง และตัณหาของตา และความเย่อหยิ่งในชีวิตไม่ได้เกิดจากพระบิดา แต่เกิดจากโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 17, 'และโลกกับสิ่งยั่วยวนของโลกกําลังผ่านพ้นไป แต่ผู้ที่ประพฤติตามพระทัยของพระเจ้าก็ดํารงอยู่เป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 18, 'ลูกเล็กๆทั้งหลายเอ๋ย บัดนี้เป็นวาระสุดท้ายแล้ว และตามที่ท่านทั้งหลายได้ยินได้ฟังมาว่า ปฏิปักษ์ต่อพระคริสต์จะมา บัดนี้ปฏิปักษ์ต่อพระคริสต์ก็มีอยู่มากแล้ว ฉะนั้นเราจึงรู้ว่าบัดนี้เป็นวาระสุดท้ายแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 19, 'เขาเหล่านั้นได้ออกไปจากพวกเรา แต่เขาเหล่านั้นก็ไม่ใช่พวกเรา เพราะว่าถ้าเขาเป็นพวกของเรา เขาจะอยู่กับเราต่อไป แต่เขาได้ออกไปแล้ว ซึ่งก็เป็นที่ปรากฏชัดแล้วว่า เขาเหล่านั้นหาใช่พวกของเราทุกคนไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 20, 'ท่านทั้งหลายได้รับการทรงเจิมจากพระองค์ผู้บริสุทธิ์แล้ว และท่านก็รู้ทุกสิ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 21, 'ข้าพเจ้าเขียนมายังท่านทั้งหลายมิใช่เพราะท่านไม่รู้ความจริง แต่เพราะท่านทั้งหลายรู้แล้ว และรู้ว่าคํามุสาไม่ได้มาจากความจริงเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 22, 'ใครเล่าเป็นผู้ที่พูดมุสา ไม่ใช่ใครอื่น แต่เป็นผู้ที่ปฏิเสธว่าพระเยซูมิใช่พระคริสต์ ผู้ใดที่ปฏิเสธพระบิดาและพระบุตร ผู้นั้นแหละเป็นปฏิปักษ์ต่อพระคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 23, 'ผู้ใดที่ปฏิเสธพระบุตร ผู้นั้นก็ไม่มีพระบิดา แต่ผู้ใดที่รับพระบุตร ผู้นั้นก็มีพระบิดาด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 24, 'เหตุฉะนั้น จงให้ข้อความที่ท่านได้ยินมาตั้งแต่ต้นนั้นดํารงอยู่กับท่านเถิด ถ้าข้อความที่ท่านได้ยินตั้งแต่ต้นนั้นดํารงอยู่กับท่าน ท่านจะตั้งมั่นคงอยู่ในพระบุตรและในพระบิดาด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 25, 'นี่แหละเป็นพระสัญญาซึ่งพระองค์ได้ทรงสัญญาไว้แก่เรา คือชีวิตนิรันดร์นั่นเอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 26, 'ข้าพเจ้าเขียนข้อความนี้ถึงท่าน เกี่ยวกับคนเหล่านั้นที่ล่อลวงท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 27, 'แต่การเจิมซึ่งท่านทั้งหลายได้รับจากพระองค์นั้นดํารงอยู่กับท่าน และท่านไม่จําเป็นต้องให้ใครมาสอนท่านทั้งหลาย เพราะว่าการเจิมนั้นสอนท่านให้รู้ทุกสิ่ง และเป็นความจริง ไม่ใช่ความเท็จ การเจิมนั้นได้สอนท่านทั้งหลายมาแล้วอย่างไร ท่านก็จงตั้งมั่นคงอยู่ในพระองค์อย่างนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 28, 'และบัดนี้ลูกเล็กๆทั้งหลายเอ๋ย จงดํารงอยู่ในพระองค์ เพื่อว่าเมื่อพระองค์ทรงมาปรากฏ เราทั้งหลายจะได้มีใจกล้า และไม่มีความละอายจําเพาะพระองค์เมื่อพระองค์เสด็จมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 29, 'ถ้าท่านทั้งหลายรู้ว่าพระองค์ทรงเป็นผู้ชอบธรรม ท่านก็รู้ว่าทุกคนที่ประพฤติตามความชอบธรรมก็บังเกิดจากพระองค์ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 1, 'จงดูเถิด พระบิดาทรงโปรดประทานความรักแก่เราทั้งหลายเพียงไร ที่เราจะได้ชื่อว่าเป็นบุตรของพระเจ้า เหตุที่โลกไม่รู้จักเราทั้งหลาย ก็เพราะเขาไม่รู้จักพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 2, 'ท่านที่รักทั้งหลาย บัดนี้เราทั้งหลายเป็นบุตรของพระเจ้า และยังไม่ปรากฏว่าต่อไปเบื้องหน้าเราจะเป็นอย่างไร แต่เรารู้ว่าเมื่อพระองค์เสด็จมาปรากฏนั้น เราทั้งหลายจะเป็นเหมือนพระองค์ เพราะว่าเราจะเห็นพระองค์อย่างที่พระองค์ทรงเป็นอยู่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 3, 'และทุกคนที่มีความหวังเช่นนี้ในพระองค์ ก็ย่อมชําระตนให้บริสุทธิ์เหมือนอย่างที่พระองค์ทรงบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 4, 'ผู้ใดที่กระทําบาปก็ละเมิดพระราชบัญญัติด้วย เพราะความบาปเป็นสิ่งที่ละเมิดพระราชบัญญัติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 5, 'ท่านทั้งหลายก็รู้อยู่แล้วว่า พระองค์ได้ทรงปรากฏเพื่อนําบาปทั้งหลายของเราไปเสีย และบาปในพระองค์ไม่มีเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 6, 'คนใดที่อาศัยอยู่ในพระองค์ คนนั้นไม่กระทําบาป ผู้ใดที่กระทําบาป ผู้นั้นยังไม่ได้เห็นพระองค์ และยังไม่ได้รู้จักพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 7, 'ลูกเล็กๆทั้งหลายเอ๋ย อย่าให้ใครชักจูงท่านให้หลง ผู้ที่ประพฤติการชอบธรรมก็เป็นผู้ชอบธรรม เหมือนอย่างพระองค์ทรงเป็นผู้ชอบธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 8, 'ผู้ที่กระทําบาปก็มาจากพญามาร เพราะว่าพญามารได้กระทําบาปตั้งแต่เริ่มแรก พระบุตรของพระเจ้าได้เสด็จมาปรากฏก็เพราะเหตุนี้ คือเพื่อทรงทําลายกิจการของพญามารเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 9, 'ผู้ใดบังเกิดจากพระเจ้า ผู้นั้นไม่กระทําบาป เพราะเมล็ดของพระองค์ดํารงอยู่ในผู้นั้น และเขากระทําบาปไม่ได้ เพราะเขาบังเกิดจากพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 10, 'ดังนี้แหละจึงเห็นได้ว่าผู้ใดเป็นบุตรของพระเจ้า และผู้ใดเป็นลูกของพญามาร คือว่าผู้ใดที่มิได้ประพฤติตามความชอบธรรม และไม่รักพี่น้องของตน ผู้นั้นก็มิได้มาจากพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 11, 'นี่เป็นคําสั่งสอนที่ท่านทั้งหลายได้ยินมาตั้งแต่เริ่มแรก คือให้เราทั้งหลายรักซึ่งกันและกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 12, 'อย่าเป็นเหมือนคาอินที่มาจากมารร้ายนั้น และได้ฆ่าน้องชายของตนเอง และเหตุใดเขาจึงฆ่าน้องชาย ก็เพราะการกระทําของเขาชั่ว และการกระทําของน้องชายนั้นชอบธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 13, 'พี่น้องทั้งหลายของข้าพเจ้าเอ๋ย อย่าประหลาดใจถ้าโลกนี้เกลียดชังท่าน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 14, 'เราทั้งหลายรู้ว่า เราได้พ้นจากความตายไปสู่ชีวิตแล้ว ก็เพราะเรารักพี่น้อง ผู้ใดที่ไม่รักพี่น้องของตน ผู้นั้นก็ยังอยู่ในความตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 15, 'ผู้ใดเกลียดชังพี่น้องของตน ผู้นั้นก็เป็นฆาตกร และท่านทั้งหลายก็รู้แล้วว่า ไม่มีฆาตกรคนใดที่มีชีวิตนิรันดร์ดํารงอยู่ในเขาเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 16, 'ดังนี้แหละเราจึงรู้จักความรักของพระเจ้า เพราะว่าพระองค์ได้ทรงยอมปล่อยวางชีวิตของพระองค์เพื่อเราทั้งหลาย และเราทั้งหลายก็ควรจะปล่อยวางชีวิตของเราเพื่อพี่น้อง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 17, 'แต่ถ้าผู้ใดมีทรัพย์สมบัติในโลกนี้ และเห็นพี่น้องของตนขัดสน และยังใจจืดใจดําไม่สงเคราะห์เขา ความรักของพระเจ้าจะดํารงอยู่ในผู้นั้นอย่างไรได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 18, 'ลูกเล็กๆทั้งหลายของข้าพเจ้าเอ๋ย อย่าให้เรารักกันด้วยคําพูดและด้วยลิ้นเท่านั้น แต่จงรักกันด้วยการกระทําและด้วยความจริง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 19, 'และโดยเหตุนี้เราจึงรู้ว่าเราอยู่ฝ่ายความจริง และจะได้ตั้งใจของเราให้แน่วแน่จําเพาะพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 20, 'เพราะถ้าใจของเรากล่าวโทษตัวเรา พระเจ้าทรงเป็นใหญ่กว่าใจของเรา และพระองค์ทรงทราบทุกสิ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 21, 'ท่านที่รักทั้งหลาย ถ้าใจของเราไม่ได้กล่าวโทษเรา เราก็มีความมั่นใจจําเพาะพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 22, 'และเราขอสิ่งใดก็ตามเราก็จะได้สิ่งนั้นจากพระองค์ เพราะเรารักษาพระบัญญัติของพระองค์ และปฏิบัติสิ่งเหล่านั้นซึ่งเป็นที่พอพระทัยในสายพระเนตรของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 23, 'และนี่เป็นพระบัญญัติของพระองค์ คือให้เราทั้งหลายเชื่อในพระนามของพระเยซูคริสต์พระบุตรของพระองค์ และให้เรารักซึ่งกันและกัน ตามที่พระองค์ได้ทรงบัญญัติไว้แก่เราแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 24, 'และทุกคนที่รักษาพระบัญญัติของพระองค์ก็อยู่ในพระองค์ และพระองค์ทรงสถิตอยู่ในคนนั้น ด้วยเหตุนี้เราจึงรู้ว่าพระองค์ทรงสถิตอยู่ในเราโดยพระวิญญาณซึ่งพระองค์ได้ทรงโปรดประทานแก่เราแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 1, 'ท่านที่รักทั้งหลาย อย่าเชื่อวิญญาณเสียทุกๆวิญญาณ แต่จงพิสูจน์วิญญาณเหล่านั้นว่ามาจากพระเจ้าหรือไม่ เพราะว่ามีผู้พยากรณ์เท็จเป็นอันมากออกเที่ยวไปในโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 2, 'โดยข้อนี้ท่านทั้งหลายก็จะรู้จักพระวิญญาณของพระเจ้า คือวิญญาณทั้งปวงที่ยอมรับว่าพระเยซูคริสต์ได้เสด็จมาเป็นมนุษย์ วิญญาณนั้นก็มาจากพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 3, 'และวิญญาณทั้งปวงที่ไม่ยอมรับว่าพระเยซูคริสต์ได้เสด็จมาเป็นมนุษย์ วิญญาณนั้นก็ไม่ได้มาจากพระเจ้า วิญญาณนั้นแหละเป็นปฏิปักษ์ต่อพระคริสต์ ซึ่งท่านทั้งหลายได้ยินว่าจะมา และบัดนี้ก็อยู่ในโลกแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 4, 'ลูกเล็กๆทั้งหลายเอ๋ย ท่านเป็นฝ่ายพระเจ้า และได้ชนะเขาเหล่านั้น เพราะว่าพระองค์ผู้สถิตอยู่ในท่านทั้งหลายเป็นใหญ่กว่าผู้นั้นที่อยู่ในโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 5, 'เขาเหล่านั้นเป็นฝ่ายโลก เหตุฉะนั้นเขาจึงพูดตามโลก และโลกก็ฟังเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 6, 'เราทั้งหลายเป็นฝ่ายพระเจ้า ผู้ที่รู้จักพระเจ้าก็ฟังเรา และผู้ที่ไม่ได้อยู่ฝ่ายพระเจ้าก็ไม่ฟังเรา ดังนี้แหละเราทั้งหลายจึงรู้จักวิญญาณแห่งความจริงและวิญญาณแห่งความเท็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 7, 'ท่านที่รักทั้งหลาย ขอให้เรารักซึ่งกันและกัน เพราะว่าความรักมาจากพระเจ้า และทุกคนที่รักก็บังเกิดจากพระเจ้า และรู้จักพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 8, 'ผู้ที่ไม่รักก็ไม่รู้จักพระเจ้า เพราะว่าพระเจ้าทรงเป็นความรัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 9, 'โดยข้อนี้ความรักของพระเจ้าที่มีต่อเราทั้งหลายก็เป็นที่ประจักษ์แล้ว เพราะว่าพระเจ้าทรงใช้พระบุตรองค์เดียวของพระองค์ที่บังเกิดมาให้เสด็จเข้ามาในโลก เพื่อเราทั้งหลายจะได้ดํารงชีวิตโดยพระบุตรนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 10, 'ในข้อนี้แหละเป็นความรัก มิใช่ที่เรารักพระเจ้า แต่ที่พระองค์ทรงรักเรา และทรงใช้พระบุตรของพระองค์ให้เป็นผู้ลบล้างพระอาชญาที่ตกกับเราทั้งหลาย เพราะบาปของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 11, 'ท่านที่รักทั้งหลาย ถ้าพระเจ้าทรงรักเราทั้งหลายเช่นนี้ เราก็ควรจะรักซึ่งกันและกันด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 12, 'ไม่มีผู้ใดเคยเห็นพระเจ้าไม่ว่าเวลาใด ถ้าเราทั้งหลายรักซึ่งกันและกัน พระเจ้าก็ทรงสถิตอยู่ในเราทั้งหลาย และความรักของพระองค์ก็สมบูรณ์อยู่ในเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 13, 'ดังนี้แหละเราทั้งหลายจึงรู้ว่า เราอยู่ในพระองค์และพระองค์ทรงสถิตอยู่ในเรา เพราะพระองค์ได้ทรงโปรดประทานพระวิญญาณของพระองค์แก่เรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 14, 'และเราทั้งหลายได้เห็นและเป็นพยานว่า พระบิดาได้ทรงใช้พระบุตรให้เสด็จมาเป็นพระผู้ช่วยให้รอดของโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 15, 'ผู้ใดยอมรับว่า พระเยซูทรงเป็นพระบุตรของพระเจ้า พระเจ้าก็ทรงสถิตอยู่ในคนนั้น และคนนั้นอยู่ในพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 16, 'เราทั้งหลายจึงรู้และเชื่อในความรักที่พระเจ้าทรงมีต่อเรา พระเจ้าทรงเป็นความรัก และผู้ใดที่อยู่ในความรักก็อยู่ในพระเจ้า และพระเจ้าก็ทรงสถิตอยู่ในผู้นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 17, 'ในข้อนี้แหละความรักของเราจึงสมบูรณ์ เพื่อเราทั้งหลายจะได้มีความกล้าในวันพิพากษา เพราะว่าพระองค์ทรงเป็นอย่างไร เราทั้งหลายก็เป็นอย่างนั้นในโลกนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 18, 'ในความรักนั้นไม่มีความกลัว แต่ความรักที่สมบูรณ์นั้นก็ได้ขจัดความกลัวเสีย ด้วยว่าความกลัวทําให้ทุกข์ทรมาน และผู้ที่มีความกลัวก็ยังไม่มีความรักที่สมบูรณ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 19, 'เราทั้งหลายรักพระองค์ ก็เพราะพระองค์ทรงรักเราก่อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 20, 'ถ้าผู้ใดว่า “ข้าพเจ้ารักพระเจ้า” และยังเกลียดชังพี่น้องของตน ผู้นั้นก็เป็นคนพูดมุสา เพราะว่าผู้ที่ไม่รักพี่น้องของตนที่แลเห็นแล้ว เขาจะรักพระเจ้าที่ไม่เคยเห็นอย่างไรได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 21, 'พระบัญญัตินี้เราทั้งหลายก็ได้มาจากพระองค์ คือว่าให้คนที่รักพระเจ้านั้นรักพี่น้องของตนด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 1, 'ผู้ใดเชื่อว่าพระเยซูทรงเป็นพระคริสต์ ผู้นั้นก็บังเกิดจากพระเจ้า และทุกคนที่รักพระองค์ผู้ทรงให้กําเนิดนั้นก็รักคนที่บังเกิดจากพระองค์ด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 2, 'เมื่อเราทั้งหลายรักพระเจ้าและได้รักษาพระบัญญัติของพระองค์ เราจึงรู้ว่าเรารักคนทั้งหลายที่เป็นบุตรของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 3, 'เพราะนี่แหละเป็นความรักของพระเจ้า คือที่เราทั้งหลายรักษาพระบัญญัติของพระองค์ และพระบัญญัติของพระองค์นั้นไม่เป็นที่หนักใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 4, 'ด้วยว่าผู้ใดที่บังเกิดจากพระเจ้า ก็มีชัยชนะต่อโลก และนี่แหละเป็นชัยชนะซึ่งได้มีชัยต่อโลก คือความเชื่อของเราทั้งหลายนี่เอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 5, 'ใครเล่าชนะโลก เว้นไว้แต่ผู้ที่เชื่อว่าพระเยซูทรงเป็นพระบุตรของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 6, 'นี่แหละคือผู้ที่ได้เสด็จมาด้วยน้ําและพระโลหิต คือพระเยซูคริสต์ ไม่ใช่ด้วยน้ําอย่างเดียว แต่ด้วยน้ําและพระโลหิต และพระวิญญาณทรงเป็นพยานเพราะพระวิญญาณทรงเป็นความจริง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 7, 'เพราะมีพยานอยู่สามพยานในสวรรค์ คือพระบิดา พระวาทะ และพระวิญญาณบริสุทธิ์ และพยานทั้งสามนี้เป็นองค์เดียวกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 8, 'มีพยานอยู่สามพยานในแผ่นดินโลก คือพระวิญญาณ น้ํา และพระโลหิต และพยานทั้งสามนี้สอดคล้องกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 9, 'ถ้าเรายังรับพยานหลักฐานของมนุษย์ พยานหลักฐานของพระเจ้าก็ยิ่งใหญ่กว่า เพราะนี่คือพยานหลักฐานของพระเจ้าซึ่งพระองค์ได้ทรงเป็นพยานถึงพระบุตรของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 10, 'ผู้ที่เชื่อในพระบุตรของพระเจ้าก็มีพยานอยู่ในตัวเอง ผู้ที่ไม่เชื่อพระเจ้าก็ได้กระทําให้พระองค์เป็นผู้ตรัสมุสา เพราะเขามิได้เชื่อพยานหลักฐานที่พระเจ้าได้ทรงเป็นพยานถึงพระบุตรของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 11, 'และพยานหลักฐานนั้นก็คือว่า พระเจ้าได้ทรงโปรดประทานชีวิตนิรันดร์แก่เราทั้งหลาย และชีวิตนี้มีอยู่ในพระบุตรของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 12, 'ผู้ที่มีพระบุตรก็มีชีวิต ผู้ที่ไม่มีพระบุตรของพระเจ้าก็ไม่มีชีวิต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 13, 'ข้อความเหล่านี้ข้าพเจ้าได้เขียนมาถึงท่านทั้งหลายที่เชื่อในพระนามของพระบุตรของพระเจ้า เพื่อท่านทั้งหลายจะได้รู้ว่าท่านมีชีวิตนิรันดร์ และเพื่อท่านจะได้เชื่อในพระนามของพระบุตรของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 14, 'และนี่คือความมั่นใจที่เรามีต่อพระองค์ คือถ้าเราทูลขอสิ่งใดตามพระประสงค์ของพระองค์ พระองค์ก็ทรงโปรดฟังเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 15, 'และถ้าเรารู้ว่า พระองค์ทรงโปรดฟังเรา เมื่อเราทูลขอสิ่งใดๆ เราก็รู้ว่าเราได้รับตามที่เราทูลขอจากพระองค์นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 16, 'ถ้าผู้ใดเห็นพี่น้องของตนกระทําบาปอย่างหนึ่งอย่างใดที่ไม่นําไปสู่ความตาย ผู้นั้นจงทูลขอ และพระองค์ก็จะทรงประทานชีวิตแก่ผู้นั้นที่ได้กระทําบาปซึ่งไม่ได้นําไปสู่ความตาย บาปที่นําไปสู่ความตายก็มี ข้าพเจ้ามิได้ว่าให้เขาอธิษฐานสําหรับบาปอย่างนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 17, 'การอธรรมทุกอย่างเป็นบาป แต่บาปที่ไม่ได้นําไปสู่ความตายก็มี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 18, 'เราทั้งหลายรู้ว่า คนใดที่บังเกิดจากพระเจ้าก็ไม่กระทําบาป แต่ว่าคนที่บังเกิดจากพระเจ้าก็ระวังรักษาตัว และมารร้ายนั้นไม่แตะต้องเขาเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 19, 'เราทั้งหลายรู้ว่าเราเป็นของพระเจ้า และชาวโลกทั้งสิ้นตกอยู่ใต้อํานาจของความชั่ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 20, 'และเราทั้งหลายรู้ว่าพระบุตรของพระเจ้าเสด็จมาแล้ว และได้ทรงประทานความเข้าใจแก่เรา เพื่อให้เรารู้จักพระองค์ผู้เที่ยงแท้ และเราทั้งหลายอยู่ในพระองค์ผู้เที่ยงแท้นั้น คืออยู่ในพระเยซูคริสต์พระบุตรของพระองค์ นี่แหละเป็นพระเจ้าเที่ยงแท้ และเป็นชีวิตนิรันดร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 21, 'ลูกเล็กๆทั้งหลายเอ๋ย จงระวังรักษาตัวไว้ให้พ้นจากรูปเคารพ เอเมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 1, 'ข้าพเจ้าผู้ปกครอง เรียน มายังท่านสุภาพสตรีที่ทรงเลือกสรรไว้ และบรรดาบุตรของเธอ ผู้ซึ่งข้าพเจ้ารักเนื่องด้วยความจริงนั้น และมิใช่แต่ข้าพเจ้าเท่านั้น แต่คนทั้งปวงที่ได้รู้จักความจริงก็รักด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 2, 'เพราะเห็นแก่ความจริงที่อยู่ในเราทั้งหลาย และซึ่งจะดํารงอยู่กับเราเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 3, 'ขอพระกรุณาธิคุณ พระเมตตาคุณ และสันติสุขจากพระเจ้าพระบิดา และจากพระเยซูคริสต์เจ้าพระบุตรแห่งพระบิดา สถิตอยู่กับท่านทั้งหลายในความจริงและในความรัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 4, 'ข้าพเจ้าชื่นชมยินดีเป็นอย่างยิ่งที่ได้เห็นบุตรของท่านดําเนินตามความจริง ตามที่เราได้รับพระบัญญัติจากพระบิดา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 5, 'และท่านสุภาพสตรี บัดนี้ข้าพเจ้าขอวิงวอนท่าน มิใช่เสมือนหนึ่งว่าข้าพเจ้าเขียนพระบัญญัติใหม่ให้แก่ท่าน แต่เป็นพระบัญญัติที่เราได้มีมาแล้วตั้งแต่เริ่มแรก นั่นก็คือให้เราทั้งหลายรักซึ่งกันและกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 6, 'และความรักนั้นก็คือ การที่เราทั้งหลายดําเนินตามพระบัญญัติของพระองค์ นี่เป็นพระบัญญัตินั้นซึ่งท่านทั้งหลายได้ยินได้ฟังมาตั้งแต่เริ่มแรก เพื่อท่านทั้งหลายจะดําเนินตาม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 7, 'เพราะว่ามีผู้ล่อลวงเป็นอันมากออกเที่ยวไปในโลก คือคนที่ไม่รับว่าพระเยซูคริสต์ได้เสด็จมาเป็นมนุษย์ คนนั้นแหละเป็นผู้ล่อลวงและเป็นปฏิปักษ์ต่อพระคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 8, 'ท่านทั้งหลายจงระวังตัวให้ดี เพื่อเราจะได้ไม่สูญเสียสิ่งที่เราได้กระทํามาแล้ว แต่จะได้รับบําเหน็จเต็มที่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 9, 'ผู้ใดละเมิดและไม่อยู่ในพระโอวาทของพระคริสต์ ผู้นั้นก็ไม่มีพระเจ้า ผู้ใดอยู่ในพระโอวาทของพระคริสต์ ผู้นั้นก็มีทั้งพระบิดาและพระบุตร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 10, 'ถ้าผู้ใดมาหาท่านและไม่นําพระโอวาทนี้มาด้วย อย่ารับเขาไว้ในเรือน และอย่าขอพรให้เขาเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 11, 'เพราะว่าผู้ที่ขอพรให้เขา ก็เข้าส่วนในการกระทําชั่วของเขานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 12, 'ข้าพเจ้ายังมีข้อความอีกหลายข้อที่จะเขียนมาถึงท่าน แต่ก็ไม่อยากจะเขียนด้วยกระดาษและน้ําหมึก ข้าพเจ้าหวังใจว่าจะมาหาท่าน และสนทนากันต่อหน้า เพื่อความปีติยินดีของเราจะได้เต็มเปี่ยม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 13, 'บรรดาบุตรของน้องสาวของท่านที่ได้ทรงเลือกสรรไว้ ฝากความระลึกถึงมายังท่าน เอเมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 1, 'ข้าพเจ้าผู้ปกครอง เรียน กายอัสที่รัก ผู้ซึ่งข้าพเจ้ารักเนื่องด้วยความจริงนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 2, 'ท่านที่รัก ข้าพเจ้าปรารถนามากกว่าทุกสิ่งที่จะให้ท่านจําเริญขึ้นและมีสุขภาพดี เหมือนอย่างที่จิตวิญญาณของท่านจําเริญอยู่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 3, 'เพราะว่าข้าพเจ้าชื่นชมยินดีเป็นอย่างยิ่ง เมื่อพวกพี่น้องได้มา และเป็นพยานถึงความจริงที่อยู่ในตัวท่าน ตามที่ท่านได้ดําเนินตามความจริงนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 4, 'ไม่มีสิ่งใดที่จะทําให้ข้าพเจ้ายินดียิ่งกว่านี้ คือที่ได้ยินว่า บุตรทั้งหลายของข้าพเจ้าดําเนินตามความจริง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 5, 'ท่านที่รัก เมื่อท่านกระทําสิ่งใดแก่พี่น้องและแก่คนแปลกถิ่น ท่านก็กระทําอย่างสัตย์ซื่อ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 6, 'เขาเหล่านั้นได้เป็นพยานต่อหน้าคริสตจักรถึงความรักของท่าน ถ้าท่านจะช่วยจัดส่งเขาเหล่านั้นในการเดินทางของเขา ตามที่สมควรตามแบบอย่างของพระเจ้า ท่านก็จะกระทําดี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 7, 'เขาเหล่านั้นได้ออกไปเพราะเห็นแก่พระนามของพระองค์ และไม่ได้รับสิ่งใดจากพวกต่างชาติเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 8, 'ฉะนั้นเราควรต้อนรับคนอย่างนั้น เพื่อเราจะได้เป็นผู้ร่วมงานกับความจริง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 9, 'ข้าพเจ้าได้เขียนถึงคริสตจักร แต่ดิโอเตรเฟส ผู้อยากจะเป็นใหญ่เป็นโตท่ามกลางพวกเขาหาได้รับรองเราไว้ไม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 10, 'เหตุฉะนั้นถ้าข้าพเจ้ามา ข้าพเจ้าจะจดจําการกระทําทั้งหลายของเขา คือที่เขาพร่ํากล่าวใส่ความเราด้วยถ้อยคําประสงค์ร้าย และเท่านั้นก็ยังไม่สาแก่ใจ เขาเองไม่ยอมรับรองพี่น้องเหล่านั้น และหนําซ้ํายังกีดกันคนที่ใคร่จะรับรองเขา และไล่เขาออกจากคริสตจักรไปเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 11, 'ท่านที่รัก อย่าเอาเยี่ยงสิ่งที่ชั่ว แต่จงเอาอย่างสิ่งที่ดี ผู้ที่ทําดีก็มาจากพระเจ้า ผู้ที่ทําชั่วก็ไม่เห็นพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 12, 'เดเมตริอัสได้รับการชื่นชมจากคนทั้งปวง และความจริงเองก็เป็นพยานอยู่ในตัวของมันเองอยู่แล้ว ใช่แล้ว เราเองก็เป็นพยานด้วย และท่านก็รู้ว่าคําพยานของเราเป็นความจริง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 13, 'ข้าพเจ้ามีหลายเรื่องที่จะเขียน แต่ไม่อยากจะเขียนถึงท่านด้วยน้ําหมึกและปากกา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 14, 'แต่ข้าพเจ้าหวังใจว่าจะได้พบท่านในเร็วๆนี้ และจะได้พูดกันต่อหน้า ขอสันติสุขจงมีแก่ท่าน บรรดาสหายของเราฝากคําคํานับมายังท่าน ขอฝากความระลึกถึงมายังบรรดาสหายแต่ละคนตามชื่อของเขานั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 1, 'ยูดาส ผู้รับใช้ของพระเยซูคริสต์ และเป็นน้องชายของยากอบ เรียน คนทั้งหลายที่ทรงชําระตั้งไว้ให้บริสุทธิ์โดยพระเจ้าพระบิดา และที่ทรงคุ้มครองรักษาไว้ในพระเยซูคริสต์ และที่ทรงเรียกไว้แล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 2, 'ขอพระเมตตาคุณ สันติสุข และความรักจงเพิ่มทวียิ่งขึ้นแก่ท่านทั้งหลายเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 3, 'ท่านที่รักทั้งหลาย เมื่อข้าพเจ้าพากเพียรเขียนถึงท่านทั้งหลายในเรื่องเกี่ยวกับความรอดสําหรับคนทั่วไปนั้น ข้าพเจ้าก็เห็นว่า ข้าพเจ้าจําเป็นต้องเขียนเตือนสติท่านให้ต่อสู้อย่างจริงจังเพื่อความเชื่อซึ่งครั้งหนึ่งได้ทรงโปรดมอบไว้แก่วิสุทธิชนแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 4, 'เพราะว่ามีบางคนได้เล็ดลอดเข้ามาอย่างไม่รู้ตัว ซึ่งเป็นผู้ที่ถูกเล็งไว้ล่วงหน้ามานานแล้วว่าจะได้รับการพิพากษาลงโทษอย่างนี้ เป็นคนอธรรม ที่ได้บิดเบือนพระคุณของพระเจ้าของเราไปเป็นการกระทําความชั่วช้าลามก และได้ปฏิเสธพระเจ้าคือองค์พระผู้เป็นเจ้าแต่เพียงพระองค์เดียว และพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 5, 'ถึงแม้ว่าท่านเคยรู้เรื่องเหล่านี้มาแล้วก็ตาม ข้าพเจ้าก็ยังปรารถนาให้ท่านทั้งหลายระลึกว่า องค์พระผู้เป็นเจ้าได้ทรงโปรดช่วยให้พลไพร่นั้นรอดจากแผ่นดินอียิปต์แล้ว ภายหลังพระองค์ได้ทรงทําลายคนเหล่านั้นที่ไม่เชื่อพระองค์เสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 6, 'และเหล่าทูตสวรรค์ที่ไม่ได้รักษาเทวสภาพของตน แต่ได้ละทิ้งถิ่นฐานของตนนั้น พระองค์ก็ได้ทรงจองจําไว้ด้วยโซ่ตรวนอันเป็นนิรันดร์ ขังไว้ในที่มืดจนกว่าจะถึงการพิพากษาในวันสําคัญยิ่งนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 7, 'เช่นเดียวกับเมืองโสโดมและเมืองโกโมราห์และเมืองที่อยู่รอบๆนั้นที่ทําในทํานองเดียวกัน ได้หลงตัวไปกับการผิดประเวณี และมัวเมาในกามวิตถาร ก็ได้ทรงบัญญัติไว้เป็นตัวอย่างของการที่จะต้องได้รับพระอาชญาในไฟนิรันดร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 8, 'เช่นเดียวกัน คนเพ้อฝันแต่เรื่องสกปรกโสโครกเหล่านี้ได้กระทําให้เนื้อหนังเป็นมลทิน ดูหมิ่นผู้มีอํานาจ และพูดจาให้ร้ายต่อผู้มีบรรดาศักดิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 9, 'ฝ่ายอัครเทวทูตาธิบดีมีคาเอล ครั้นเมื่อท่านโต้เถียงกับพญามารเรื่องศพของโมเสส ท่านเองก็ยังไม่บังอาจตั้งข้อกล่าวหาอย่างเย้ยหยันต่อมารเลย ได้แต่เพียงกล่าวว่า “ขอให้องค์พระผู้เป็นเจ้าทรงห้ามเจ้าเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 10, 'แต่ว่าคนเหล่านี้พูดให้ร้ายถึงสิ่งที่เขาเองไม่รู้จัก แต่ได้กระทําตามสิ่งที่ตนเองรู้จักตามสัญชาตญาณ เหมือนสัตว์เดียรัจฉานที่ไม่มีความคิด เขาได้กระทําให้ตนเองเสื่อมทรามไปด้วยการนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 11, 'วิบัติจงมีแก่เขา เพราะเขาได้ดําเนินในทางของคาอิน และได้วิ่งพล่านไปตามความผิดพลาดของบาลาอัมเพราะเห็นแก่สินจ้าง และได้พินาศไปในการกบฏอย่างโคราห์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 12, 'คนเหล่านี้เป็นรอยด่างในการประชุมเลี้ยงผูกรักของท่านทั้งหลาย ขณะเขาร่วมการเลี้ยงกับท่าน เขาเลี้ยงแต่ตนเองโดยไม่เกรงกลัวเลย เขาเป็นเมฆที่ปราศจากน้ําที่ถูกพัดลอยไปตามลม เป็นต้นไม้ที่ผลของมันเหี่ยวแห้งไปจึงไม่มีผลอยู่เลย และตายมาสองหนแล้ว เพราะถูกถอนออกทั้งราก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 13, 'เป็นคลื่นที่บ้าคลั่งในมหาสมุทร ที่ซัดฟองของความบัดสีของตนเองขึ้นมา เขาเป็นดาวที่ลอยลับไป เป็นผู้ที่ตกอยู่ในความมืดทึบตลอดกาล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 14, 'เอโนคคนที่เจ็ดนับแต่อาดัมได้พยากรณ์ถึงคนเหล่านี้ด้วยว่า “ดูเถิด องค์พระผู้เป็นเจ้าได้เสด็จมาพร้อมกับพวกวิสุทธิชนของพระองค์หลายหมื่น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 15, 'เพื่อทรงพิพากษาปรับโทษคนทั้งปวง และทรงกระทําให้ทุรชนทั้งปวงรู้สึกตัวถึงการอธรรมที่เขาได้กระทําด้วยใจชั่ว และรู้สึกตัวถึงการหยาบช้าทั้งหมดที่ทุรชนคนบาปเหล่านั้นได้กล่าวร้ายต่อพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 16, 'คนเหล่านี้มักเป็นคนบ่น เป็นคนโพนทะนา เป็นคนดําเนินตามตัณหาอันชั่วของตัว และปากเขากล่าวคําโอ้อวดต่างๆ เป็นคนยกยอผู้อื่นเพื่อหวังประโยชน์ของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 17, 'แต่ว่าท่านที่รักทั้งหลาย ท่านจงระลึกถึงคําพยากรณ์เมื่อก่อนของเหล่าอัครสาวกของพระเยซูคริสต์ องค์พระผู้เป็นเจ้าของเราที่ได้กล่าวไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 18, 'คือว่า พวกอัครสาวกนั้นได้บอกท่านทั้งหลายว่า “ในสมัยสุดท้ายจะมีคนเยาะเย้ยบังเกิดขึ้น เขาเป็นคนที่ดําเนินตามตัณหาอันชั่วของตัว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 19, 'คนเหล่านี้คือคนที่แยกตัวออกมาและประพฤติตัวตามโลกียวิสัย และปราศจากพระวิญญาณ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 20, 'แต่ท่านทั้งหลายผู้เป็นที่รัก จงก่อสร้างตัวของท่านขึ้นบนความเชื่ออันบริสุทธิ์ยิ่งของท่าน โดยการอธิษฐานด้วยพระวิญญาณบริสุทธิ์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 21, 'จงรักษาตัวไว้ในความรักของพระเจ้า คอยพระกรุณาของพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเราจนถึงชีวิตนิรันดร์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 22, 'และจงแสดงความเมตตาต่อบางคน โดยรู้ความต่างกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 23, 'และจงช่วยคนอื่นๆให้รอดโดยความกลัวด้วยการฉุดเขาออกมาจากไฟ จงเกลียดชังแม้แต่เสื้อผ้าที่เปรอะเปื้อนด้วยเนื้อหนังเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 24, 'บัดนี้แด่พระองค์ผู้ทรงสามารถคุ้มครองรักษาท่านมิให้ล้มลง และทรงนําท่านให้ตั้งอยู่จําเพาะสง่าราศีของพระองค์โดยปราศจากตําหนิ และมีความร่าเริงยินดีอย่างเหลือล้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 25, 'สง่าราศี พระอานุภาพ การครอบครอง และศักดานุภาพจงมีแด่พระเจ้าผู้ทรงพระปัญญาแต่เพียงพระองค์เดียว พระผู้ช่วยให้รอดของเรา ทั้งปัจจุบันกาล และในกาลต่อๆไปเป็นนิตย์ เอเมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 1, 'วิวรณ์ของพระเยซูคริสต์ซึ่งพระเจ้าได้ทรงประทานแก่พระองค์ เพื่อชี้แจงให้ผู้รับใช้ทั้งหลายของพระองค์รู้ถึงสิ่งที่จะต้องอุบัติขึ้นในไม่ช้า และพระองค์ได้ทรงใช้ทูตสวรรค์ของพระองค์ไปสําแดงแก่ยอห์นผู้รับใช้ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 2, 'ยอห์นเป็นพยานฝ่ายพระวจนะของพระเจ้า และเป็นพยานฝ่ายคําพยานของพระเยซูคริสต์ และเป็นพยานในเหตุการณ์ทั้งสิ้นซึ่งท่านได้เห็นนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 3, 'ขอความสุขจงมีแก่บรรดาผู้อ่านและผู้ฟังคําพยากรณ์เหล่านี้ และถือรักษาข้อความที่เขียนไว้ในคําพยากรณ์นี้ เพราะว่าเวลานั้นใกล้เข้ามาแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 4, 'ยอห์นเรียนมายังคริสตจักรทั้งเจ็ดที่อยู่ในแคว้นเอเชีย ขอให้ท่านทั้งหลายจงได้รับพระคุณและสันติสุขจากพระองค์ผู้ทรงเป็นอยู่เดี๋ยวนี้ และผู้ทรงเป็นอยู่ในกาลก่อน และผู้จะเสด็จมานั้น และจากพระวิญญาณทั้งเจ็ดที่อยู่หน้าพระที่นั่งของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 5, 'และจากพระเยซูคริสต์ผู้ทรงเป็นพยานที่สัตย์ซื่อ และทรงเป็นผู้แรกที่ได้ฟื้นจากความตาย และผู้ทรงครอบครองกษัตริย์ทั้งปวงในโลก แด่พระองค์ผู้ทรงรักเราทั้งหลาย และได้ทรงชําระบาปของเราด้วยพระโลหิตของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 6, 'และทรงตั้งเราไว้ให้เป็นกษัตริย์และเป็นปุโรหิตของพระเจ้าพระบิดาของพระองค์ พระเกียรติและไอศวรรย์จงมีแด่พระองค์สืบๆไปเป็นนิตย์ เอเมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 7, '‘ดูเถิด พระองค์จะเสด็จมาในเมฆ และนัยน์ตาทุกดวงและคนเหล่านั้นที่ได้แทงพระองค์จะเห็นพระองค์ และมนุษย์ทุกชาติทั่วโลกจะร่ําไห้เพราะพระองค์’ จงเป็นไปอย่างนั้น เอเมน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 8, 'องค์พระผู้เป็นเจ้าได้ตรัสว่า “เราเป็นอัลฟาและโอเมกา เป็นปฐมและเป็นอวสาน ผู้ทรงเป็นอยู่เดี๋ยวนี้ ผู้ได้ทรงเป็นอยู่ในกาลก่อน ผู้จะเสด็จมานั้น และผู้ทรงฤทธานุภาพสูงสุด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 9, 'ข้าพเจ้า ยอห์น พี่น้องของท่านทั้งหลาย ผู้เป็นเพื่อนร่วมการยากลําบาก และร่วมราชอาณาจักร และร่วมความอดทนของพระเยซูคริสต์ ข้าพเจ้าจึงได้มาอยู่ที่เกาะปัทมอส เนื่องด้วยพระวจนะของพระเจ้า และเนื่องด้วยคําพยานของพระเยซูคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 10, 'พระวิญญาณได้ทรงดลใจข้าพเจ้าในวันขององค์พระผู้เป็นเจ้า และข้าพเจ้าได้ยินพระสุรเสียงดังมาจากเบื้องหลังข้าพเจ้าดุจเสียงแตร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 11, 'ตรัสว่า “เราเป็นอัลฟาและโอเมกา เป็นเบื้องต้นและเป็นเบื้องปลาย และสิ่งซึ่งท่านได้เห็นจงเขียนไว้ในหนังสือ และฝากไปให้คริสตจักรทั้งเจ็ดที่อยู่ในแคว้นเอเชีย คือคริสตจักรที่เมืองเอเฟซัส เมืองสเมอร์นา เมืองเปอร์กามัม เมืองธิยาทิรา เมืองซาร์ดิส เมืองฟีลาเดลเฟีย และเมืองเลาดีเซีย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 12, 'ข้าพเจ้าจึงเหลียวมาทางพระสุรเสียงที่ตรัสแก่ข้าพเจ้านั้น ครั้นเหลียวแล้วข้าพเจ้าก็เห็นคันประทีปทองคําเจ็ดคัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 13, 'และในท่ามกลางคันประทีปทั้งเจ็ดคันนั้น มีผู้หนึ่งเหมือนกับบุตรมนุษย์ ทรงฉลองพระองค์กรอมพระบาท และทรงคาดผ้ารัดประคดทองคําที่พระอุระ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 14, 'พระเศียรและพระเกศาของพระองค์ขาวดุจขนแกะสีขาว และขาวดุจหิมะ และพระเนตรของพระองค์ดุจเปลวเพลิง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 15, 'พระบาทของพระองค์ดุจทองเหลืองเงางาม ราวกับว่าได้ถูกหลอมในเตาไฟ พระสุรเสียงของพระองค์ดุจเสียงน้ํามากหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 16, 'พระองค์ทรงถือดวงดาวเจ็ดดวงไว้ในพระหัตถ์เบื้องขวาของพระองค์ และมีพระแสงสองคมที่คมกริบออกมาจากพระโอษฐ์ของพระองค์ และสีพระพักตร์ของพระองค์ดุจดังดวงอาทิตย์ที่ฉายแสงด้วยฤทธานุภาพของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 17, 'เมื่อข้าพเจ้าได้เห็นพระองค์ ข้าพเจ้าก็ล้มลงแทบพระบาทของพระองค์เหมือนกับคนที่ตายแล้ว แต่พระองค์ทรงแตะตัวข้าพเจ้าด้วยพระหัตถ์เบื้องขวา แล้วตรัสแก่ข้าพเจ้าว่า “อย่ากลัวเลย เราเป็นเบื้องต้นและเป็นเบื้องปลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 18, 'และเป็นผู้ที่ดํารงชีวิตอยู่ เราได้ตายแล้ว แต่ ดูเถิด เราก็ยังดํารงชีวิตอยู่ตลอดไปเป็นนิตย์ เอเมน และเราถือลูกกุญแจแห่งนรกและแห่งความตาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 19, 'จงเขียนเหตุการณ์ซึ่งเจ้าได้เห็น และเหตุการณ์ที่กําลังเป็นอยู่ขณะนี้ กับทั้งเหตุการณ์ซึ่งจะเกิดขึ้นในภายหน้าด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 20, 'ส่วนความลึกลับของดาวทั้งเจ็ดดวงซึ่งเจ้าได้เห็นในมือข้างขวาของเรา และแห่งคันประทีปทองคําทั้งเจ็ดนั้น ก็คือ ดาวทั้งเจ็ดดวงได้แก่ทูตสวรรค์ของคริสตจักรทั้งเจ็ด และคันประทีปเจ็ดคันซึ่งเจ้าได้เห็นแล้วนั้นได้แก่คริสตจักรทั้งเจ็ด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 1, '“จงเขียนถึงทูตสวรรค์แห่งคริสตจักรที่เมืองเอเฟซัสว่า ‘พระองค์ผู้ทรงถือดาวทั้งเจ็ดไว้ในพระหัตถ์เบื้องขวาของพระองค์ และดําเนินอยู่ท่ามกลางคันประทีปทองคําทั้งเจ็ดนั้นตรัสดังนี้ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 2, 'เรารู้จักแนวการกระทําของเจ้า รู้ความเหนื่อยยากและความอดทนของเจ้า และรู้ว่าเจ้าไม่สามารถทนต่อทุรชนได้ เจ้าได้ลองใจคนเหล่านั้นที่กล่าวว่าเขาเป็นอัครสาวก และหาได้เป็นไม่ และเจ้าก็เห็นว่าเขาเป็นคนมุสา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 3, 'เรารู้ว่าพวกเจ้าได้ทนและมีความเพียร และเหนื่อยยากเพราะเห็นแก่นามของเรา และมิได้อ่อนระอาไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 4, 'แต่เรามีข้อที่จะต่อว่าเจ้าบ้าง คือว่าเจ้าละทิ้งความรักดั้งเดิมของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 5, 'เหตุฉะนั้น จงระลึกถึงสภาพเดิมที่เจ้าได้หล่นจากมาแล้วนั้น จงกลับใจเสียใหม่ และประพฤติตามอย่างเดิม มิฉะนั้นเราจะรีบมาหาเจ้า และจะยกคันประทีปของเจ้าออกจากที่ เว้นไว้แต่เจ้าจะกลับใจใหม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 6, 'แต่ว่าพวกเจ้ายังมีความดีอยู่บ้าง คือว่าเจ้าเกลียดชังกิจการของพวกนิโคเลาส์นิยมที่เราเองก็เกลียดชังเช่นกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 7, 'ใครมีหูก็ให้ฟังข้อความซึ่งพระวิญญาณตรัสไว้แก่คริสตจักรทั้งหลาย ผู้ใดมีชัยชนะ เราจะให้ผู้นั้นกินผลจากต้นไม้แห่งชีวิต ที่อยู่ในท่ามกลางอุทยานสวรรค์ของพระเจ้า’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 8, 'จงเขียนถึงทูตสวรรค์แห่งคริสตจักรที่เมืองสเมอร์นาว่า ‘พระองค์ผู้ทรงเป็นเบื้องต้นและเป็นเบื้องปลาย ผู้ซึ่งสิ้นพระชนม์แล้ว และกลับฟื้นขึ้นอีก ได้ตรัสดังนี้ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 9, 'เรารู้จักแนวการกระทําของเจ้า และเรารู้ว่าพวกเจ้ามีความทุกข์ลําบากและยากจน (แต่ว่าเจ้าก็มั่งมี) และรู้เรื่องการหมิ่นประมาทของคนเหล่านั้นที่กล่าวว่า เขาเป็นพวกยิวและหาได้เป็นไม่ แต่พวกเขาเป็นธรรมศาลาของซาตาน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 10, 'อย่ากลัวความทุกข์ทรมานต่างๆซึ่งเจ้าจะได้รับนั้น ดูเถิด พญามารจะขังพวกเจ้าบางคนไว้ในคุกเพื่อจะลองใจเจ้า และเจ้าทั้งหลายจะได้รับความทุกข์ทรมานถึงสิบวัน แต่เจ้าจงสัตย์ซื่อจนถึงความตาย และเราจะมอบมงกุฎแห่งชีวิตให้แก่เจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 11, 'ใครมีหูก็ให้ฟังข้อความซึ่งพระวิญญาณตรัสไว้แก่คริสตจักรทั้งหลาย ผู้ที่มีชัยชนะจะไม่ได้รับอันตรายจากความตายครั้งที่สองเลย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 12, 'จงเขียนถึงทูตสวรรค์แห่งคริสตจักรที่เมืองเปอร์กามัมว่า ‘พระองค์ผู้ทรงถือดาบสองคมที่คมกริบตรัสดังนี้ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 13, 'เรารู้จักแนวการกระทําของเจ้า เรารู้จักที่อยู่ของเจ้าคือเป็นที่นั่งของซาตาน เจ้ายึดนามของเราไว้มั่น และไม่ปฏิเสธความเชื่อในเรา แม้ในเวลาที่อันทีพาผู้เป็นพยานที่สัตย์ซื่อของเรา ต้องถูกฆ่าในท่ามกลางพวกเจ้าในที่ซึ่งซาตานอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 14, 'แต่เรามีข้อที่จะต่อว่าเจ้าบ้างเล็กน้อย คือพวกเจ้าบางคนถือตามคําสอนของบาลาอัม ซึ่งสอนบาลาคให้ก่อเหตุเพื่อให้ชนชาติอิสราเอลสะดุด คือให้เขากินของที่ได้บูชาแก่รูปเคารพแล้วและให้เขาล่วงประเวณี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 15, 'และมีพวกเจ้าบางคนที่ถือคําสอนของพวกนิโคเลาส์นิยมด้วยเหมือนกัน ที่เราเองก็เกลียดชัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 16, 'จงกลับใจเสียใหม่ มิฉะนั้นเราจะรีบมาหาเจ้า และจะสู้กับเขาเหล่านั้นด้วยดาบแห่งปากของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 17, 'ใครมีหูก็ให้ฟังข้อความซึ่งพระวิญญาณตรัสไว้แก่คริสตจักรทั้งหลาย ผู้ที่มีชัยชนะ เราจะให้ผู้นั้นกินมานาที่ซ่อนอยู่ และจะให้หินขาวแก่ผู้นั้นด้วย ที่หินนั้นมีชื่อใหม่จารึกไว้ซึ่งไม่มีผู้ใดรู้เลยนอกจากผู้ที่รับเท่านั้น’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 18, 'จงเขียนถึงทูตสวรรค์แห่งคริสตจักรที่เมืองธิยาทิรา ว่า ‘พระองค์ผู้ซึ่งเป็นพระบุตรของพระเจ้า ผู้ทรงมีพระเนตรดุจเปลวไฟ และมีพระบาทดุจทองเหลืองเงางาม ได้ตรัสดังนี้ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 19, 'เรารู้จักแนวการกระทําของเจ้า ความรัก การปรนนิบัติ ความเชื่อ และความเพียรของเจ้า และแนวการกระทําของเจ้า และรู้ว่าการเบื้องปลายของเจ้ามีมากกว่าการเบื้องต้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 20, 'แต่เรามีข้อที่จะต่อว่าเจ้าบ้างเล็กน้อย คือพวกเจ้ายอมให้ผู้หญิงชื่อเยเซเบล ที่ยกตัวขึ้นเป็นผู้พยากรณ์หญิง หญิงนั้นสอนและล่อลวงพวกผู้รับใช้ของเรา ให้ล่วงประเวณีและให้กินของที่บูชาแก่รูปเคารพแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 21, 'เราได้ให้โอกาสหญิงนั้นกลับใจจากการล่วงประเวณีของนาง แต่นางก็ไม่ได้กลับใจเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 22, 'ดูเถิด เราจะทิ้งหญิงนั้นไว้บนเตียง และคนทั้งหลายที่ล่วงประเวณีกับนาง เราก็จะทิ้งไว้ให้ผจญกับความระทมทุกข์ เว้นไว้แต่ว่าคนเหล่านั้นจะกลับใจจากการกระทําของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 23, 'เราจะประหารลูกทั้งหลายของหญิงนั้นเสียให้ตาย และคริสตจักรทั้งหลายจะได้รู้ว่าเราเป็นผู้พินิจพิจารณาจิตใจ และเราจะให้สิ่งตอบแทนแก่เจ้าทั้งหลายทุกคนให้เหมาะสมกับการงานของเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 24, 'สําหรับพวกเจ้า และคนอื่นที่เหลืออยู่ที่เมืองธิยาทิรา ผู้ไม่ถือคําสอนนี้ และไม่รู้จักสิ่งที่เขาเรียกว่า ความล้ําลึกของซาตานนั้น เราขอบอกว่า เราจะไม่มอบภาระอื่นให้เจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 25, 'แต่สิ่งที่เจ้ามีอยู่แล้วนั้น จงยึดไว้ให้มั่นจนกว่าเราจะมา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 26, 'ผู้ใดมีชัยชนะและถือรักษากิจการของเราไว้จนถึงที่สุด ‘เราจะให้ผู้นั้นมีอํานาจครอบครองบรรดาประชาชาติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 27, 'และผู้นั้นจะบังคับบัญชาคนทั้งหลายด้วยคทาเหล็ก เหมือนกับเมื่อหม้อดินของช่างหม้อที่แตกออกเป็นเสี่ยงๆ’ ตามที่เราได้รับจากพระบิดาของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 28, 'และเราจะมอบดาวประจํารุ่งให้แก่ผู้นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 29, 'ใครมีหูก็ให้ฟังข้อความซึ่งพระวิญญาณตรัสไว้แก่คริสตจักรทั้งหลายเถิด’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 1, '“จงเขียนถึงทูตสวรรค์แห่งคริสตจักรที่เมืองซาร์ดิสว่า ‘พระองค์ผู้ทรงมีพระวิญญาณทั้งเจ็ดของพระเจ้า และทรงมีดาราเจ็ดดวงนั้น ได้ตรัสดังนี้ว่า เรารู้จักแนวการกระทําของเจ้า เจ้าได้ชื่อว่ามีชีวิตอยู่ แต่ว่าเจ้าได้ตายเสียแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 2, 'เจ้าจงระแวดระวังให้ดี และกระตุ้นส่วนที่เหลืออยู่ซึ่งจวนจะตายอยู่แล้วนั้นให้แข็งแรงขึ้น เพราะว่าเราไม่พบการประพฤติของเจ้าดีพร้อมต่อพระพักตร์พระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 3, 'เหตุฉะนั้น เจ้าจงระลึกว่าเจ้าได้รับและได้ยินอะไร จงยึดไว้ให้มั่นและกลับใจเสียใหม่ ฉะนั้นถ้าเจ้าไม่เฝ้าระวัง เราจะมาหาเจ้าเหมือนอย่างขโมย และเจ้าจะไม่รู้ว่าเราจะมาหาเจ้าเมื่อไร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 4, 'แต่ก็มีพวกเจ้าสองสามชื่อที่เมืองซาร์ดิส ที่ไม่ได้กระทําให้เสื้อผ้าของตนมีมลทิน และเขาเหล่านั้นจะแต่งตัวสีขาวเดินไปกับเรา เพราะว่าเขาเป็นคนที่สมควรแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 5, 'ผู้ใดมีชัยชนะ ผู้นั้นจะสวมเสื้อสีขาว และเราจะไม่ลบชื่อผู้นั้นออกจากหนังสือแห่งชีวิต แต่เราจะรับรองชื่อผู้นั้นต่อพระพักตร์พระบิดาของเรา และต่อหน้าเหล่าทูตสวรรค์ของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 6, 'ใครมีหูก็ให้ฟังข้อความซึ่งพระวิญญาณตรัสไว้แก่คริสตจักรทั้งหลายเถิด’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 7, 'จงเขียนถึงทูตสวรรค์แห่งคริสตจักรที่เมืองฟีลาเดลเฟีย ว่า ‘พระองค์ผู้บริสุทธิ์ ผู้สัตย์จริง ผู้ทรงถือลูกกุญแจของดาวิด ผู้ทรงเปิดแล้วจะไม่มีผู้ใดปิด ผู้ทรงปิดแล้วจะไม่มีผู้ใดเปิด ได้ตรัสดังนี้ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 8, 'เรารู้จักแนวการกระทําของเจ้า ดูเถิด เราได้ตั้งประตูซึ่งเปิดไว้ตรงหน้าพวกเจ้า ประตูนี้ไม่มีใครปิดได้ เพราะว่าเจ้ามีกําลังเพียงเล็กน้อย แต่กระนั้นเจ้าก็ได้รักษาคําของเราและไม่ได้ปฏิเสธนามของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 9, 'ดูเถิด เราจะทําให้พวกธรรมศาลาของซาตานที่พูดมุสาว่าเขาเป็นพวกยิวและไม่ได้เป็นนั้น ดูเถิด เราจะทําให้เขามากราบลงแทบเท้าของเจ้า และให้เขารู้ว่า เราได้รักพวกเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 10, 'เพราะเหตุเจ้าได้รักษาคําของเราด้วยความเพียร เราจะรักษาเจ้าจากเวลาแห่งการทดลองนั้นด้วย ซึ่งจะบังเกิดขึ้นทั่วทั้งโลก เพื่อจะลองดูใจคนทั้งปวงที่อยู่ทั่วแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 11, 'ดูเถิด เราจะมาโดยเร็ว จงยึดมั่นในสิ่งที่เจ้ามี เพื่อไม่ให้ผู้ใดชิงเอามงกุฎของเจ้าไปได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 12, 'ผู้ใดมีชัยชนะ เราจะกระทําให้ผู้นั้นเป็นเสาในพระวิหารแห่งพระเจ้าของเรา และผู้นั้นจะไม่ออกไปภายนอกอีกเลย และเราจะจารึกพระนามพระเจ้าของเราไว้ที่ผู้นั้น และชื่อเมืองของพระเจ้าของเรา คือกรุงเยรูซาเล็มใหม่ ที่ลงมาจากสวรรค์จากพระเจ้าของเรา และเราจะจารึกนามใหม่ของเราไว้ที่ผู้นั้นด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 13, 'ใครมีหูก็ให้ฟังข้อความซึ่งพระวิญญาณตรัสไว้แก่คริสตจักรทั้งหลายเถิด’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 14, 'จงเขียนถึงทูตสวรรค์แห่งคริสตจักรที่เมืองเลาดีเซีย ว่า ‘พระองค์ผู้ทรงเป็นพระเอเมน ทรงเป็นพยานที่สัตย์ซื่อและสัตย์จริง และทรงเป็นปฐมเหตุแห่งสิ่งสารพัดซึ่งพระเจ้าทรงสร้าง ได้ตรัสดังนี้ว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 15, 'เรารู้จักแนวการกระทําของเจ้าว่า เจ้าไม่เย็นไม่ร้อน เราใคร่ให้เจ้าเย็นหรือร้อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 16, 'ดังนั้น เพราะเหตุที่เจ้าเป็นแต่อุ่นๆไม่เย็นและไม่ร้อน เราจะคายเจ้าออกจากปากของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 17, 'เพราะเจ้าพูดว่า “เราเป็นคนมั่งมี ได้ทรัพย์สมบัติทวีมากขึ้น และเราไม่ต้องการสิ่งใดเลย” เจ้าไม่รู้ว่าเจ้าเป็นคนแร้นแค้นเข็ญใจ เป็นคนน่าสังเวช เป็นคนขัดสน เป็นคนตาบอด และเปลือยกายอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 18, 'เราเตือนสติเจ้าให้ซื้อทองคําที่หลอมให้บริสุทธิ์ในไฟแล้วจากเรา เพื่อเจ้าจะได้เป็นคนมั่งมี และเสื้อผ้าขาวเพื่อจะนุ่งห่มได้ และเพื่อความละอายแห่งกายเปลือยเปล่าของเจ้าจะไม่ได้ปรากฏ และเอายาทาตาของเจ้าเพื่อเจ้าจะแลเห็นได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 19, 'เรารักผู้ใด เราก็ตักเตือนและตีสอนผู้นั้น เหตุฉะนั้นจงมีความกระตือรือร้น และกลับใจเสียใหม่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 20, 'ดูเถิด เรายืนเคาะอยู่ที่ประตู ถ้าผู้ใดได้ยินเสียงของเรา และเปิดประตู เราจะเข้าไปหาผู้นั้น และจะรับประทานอาหารร่วมกับเขา และเขาจะรับประทานอาหารร่วมกับเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 21, 'ผู้ใดมีชัยชนะ เราจะให้ผู้นั้นนั่งกับเราบนพระที่นั่งของเรา เหมือนกับที่เรามีชัยชนะแล้ว และได้นั่งกับพระบิดาของเราบนพระที่นั่งของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 22, 'ใครมีหูก็ให้ฟังข้อความซึ่งพระวิญญาณตรัสไว้แก่คริสตจักรทั้งหลายเถิด’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 1, 'ต่อจากนั้น ดูเถิด ข้าพเจ้าได้เห็นประตูสวรรค์เปิดอ้าอยู่ และพระสุรเสียงแรกซึ่งข้าพเจ้าได้ยินนั้นได้ตรัสกับข้าพเจ้าดุจเสียงแตรว่า “จงขึ้นมาบนนี้เถิด และเราจะสําแดงให้เจ้าเห็นเหตุการณ์ที่จะต้องเกิดขึ้นในภายหน้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 2, 'ในทันใดนั้น พระวิญญาณก็ทรงดลใจข้าพเจ้า และดูเถิด มีพระที่นั่งตั้งอยู่ในสวรรค์ และมีท่านองค์หนึ่งประทับบนพระที่นั่งนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 3, 'และพระองค์ผู้ประทับบนพระที่นั่งนั้นปรากฏประดุจพลอยหยกและพลอยทับทิม และมีรุ้งล้อมรอบพระที่นั่งนั้น ดูประหนึ่งพลอยมรกต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 4, 'และล้อมรอบพระที่นั่งนั้นมีที่นั่งอีกยี่สิบสี่ที่นั่ง และข้าพเจ้าได้เห็นผู้อาวุโสยี่สิบสี่คนนั่งอยู่บนที่นั่งเหล่านั้น ทุกคนนุ่งห่มเสื้อสีขาว และสวมมงกุฎทองคําบนศีรษะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 5, 'มีฟ้าแลบฟ้าร้อง และเสียงต่างๆดังออกมาจากพระที่นั่งนั้น และมีประทีปเจ็ดดวงจุดไว้ตรงหน้าพระที่นั่ง ซึ่งเป็นพระวิญญาณทั้งเจ็ดของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 6, 'และตรงหน้าพระที่นั่งนั้นมีทะเลแก้วดูเหมือนแก้วผลึก และท่ามกลางพระที่นั่งและล้อมรอบพระที่นั่งนั้นมีสัตว์สี่ตัว ซึ่งมีตาเต็มทั้งข้างหน้าและข้างหลัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 7, 'สัตว์ตัวที่หนึ่งนั้นเหมือนสิงโต สัตว์ตัวที่สองนั้นเหมือนลูกโค สัตว์ตัวที่สามนั้นมีหน้าเหมือนมนุษย์ และสัตว์ตัวที่สี่เหมือนนกอินทรีกําลังบิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 8, 'สัตว์ทั้งสี่นั้นแต่ละตัวมีปีกหกปีกอยู่รอบตัว และมีตาเต็มข้างใน และสัตว์เหล่านั้นร้องตลอดวันตลอดคืนไม่ได้หยุดเลยว่า “บริสุทธิ์ บริสุทธิ์ บริสุทธิ์ องค์พระผู้เป็นเจ้า พระเจ้า ผู้ทรงฤทธานุภาพสูงสุด ผู้ได้ทรงสภาพอยู่ในกาลก่อน ผู้ทรงสภาพอยู่ในปัจจุบัน และผู้ซึ่งจะเสด็จมา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 9, 'เมื่อสัตว์เหล่านั้นถวายคําสรรเสริญ ถวายพระเกียรติ และคําขอบพระคุณแด่พระองค์ผู้ประทับบนพระที่นั่ง ผู้ทรงพระชนม์อยู่ตลอดไปเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 10, 'ผู้อาวุโสทั้งยี่สิบสี่นั้นก็ทรุดตัวลงจําเพาะพระพักตร์พระองค์ ผู้ประทับบนพระที่นั่งนั้น และนมัสการพระองค์ผู้ทรงพระชนม์อยู่ตลอดไปเป็นนิตย์ และถอดมงกุฎออกวางตรงหน้าพระที่นั่งร้องว่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 11, '“โอ ข้าแต่องค์พระผู้เป็นเจ้า พระองค์ทรงสมควรที่จะได้รับคําสรรเสริญ พระเกียรติ และฤทธิ์เดช เพราะว่าพระองค์ได้ทรงสร้างสรรพสิ่งทั้งปวง และสรรพสิ่งทั้งปวงนั้นก็ทรงสร้างขึ้นแล้วและดํารงอยู่ตามชอบพระทัยของพระองค์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 1, 'และในพระหัตถ์เบื้องขวาของพระองค์ผู้ทรงประทับบนพระที่นั่งนั้น ข้าพเจ้าได้เห็นหนังสือม้วนหนึ่งเขียนไว้ทั้งข้างในและข้างนอก มีตราประทับอยู่เจ็ดดวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 2, 'และข้าพเจ้าได้เห็นทูตสวรรค์ที่มีฤทธิ์องค์หนึ่ง ประกาศด้วยเสียงอันดังว่า “ใครเป็นผู้ที่สมควรจะแกะตราและคลี่หนังสือม้วนนั้นออก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 3, 'และไม่มีผู้ใดในสวรรค์ บนแผ่นดินโลก หรือใต้แผ่นดินที่สามารถคลี่หนังสือม้วนนั้นออก หรือดูหนังสือนั้นได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 4, 'และข้าพเจ้าก็ร่ําไห้มากมาย เพราะไม่มีผู้ใดสมควรจะคลี่หนังสือม้วนนั้นออกและอ่านหนังสือนั้น หรือดูหนังสือนั้นได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 5, 'และมีผู้หนึ่งในพวกผู้อาวุโสนั้น บอกแก่ข้าพเจ้าว่า “อย่าร้องไห้เลย ดูเถิด สิงโตแห่งตระกูลยูดาห์ เป็นมูลรากของดาวิด พระองค์ทรงมีชัยแล้ว พระองค์จึงทรงสามารถแกะตราทั้งเจ็ดดวงและคลี่หนังสือม้วนนั้นออกได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 6, 'และในท่ามกลางพระที่นั่งกับสัตว์ทั้งสี่นั้น และท่ามกลางพวกผู้อาวุโส ดูเถิด ข้าพเจ้าแลเห็นพระเมษโปดกประทับยืนอยู่ประหนึ่งทรงถูกปลงพระชนม์ ทรงมีเขาเจ็ดเขาและมีตาเจ็ดดวง ซึ่งเป็นพระวิญญาณทั้งเจ็ดของพระเจ้า ที่ทรงส่งออกไปทั่วแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 7, 'และพระเมษโปดกนั้นได้เข้ามารับม้วนหนังสือจากพระหัตถ์เบื้องขวาของพระองค์ ผู้ทรงประทับบนพระที่นั่งนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 8, 'เมื่อพระองค์ทรงรับหนังสือม้วนนั้นแล้ว สัตว์ทั้งสี่กับผู้อาวุโสยี่สิบสี่คนนั้นก็ทรุดตัวลงจําเพาะพระพักตร์พระเมษโปดก ทุกคนถือพิณเขาคู่และถือขันทองคําบรรจุเครื่องหอม ซึ่งเป็นคําอธิษฐานของพวกวิสุทธิชนทั้งปวง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 9, 'และเขาทั้งหลายก็ร้องเพลงใหม่ ว่าดังนี้ “พระองค์ทรงเป็นผู้ที่สมควรจะทรงรับม้วนหนังสือ และแกะตราม้วนหนังสือนั้นออก เพราะว่าพระองค์ทรงถูกปลงพระชนม์แล้ว และด้วยพระโลหิตของพระองค์นั้น พระองค์ได้ทรงไถ่เราทั้งหลายซึ่งมาจากทุกตระกูล ทุกภาษาทุกชาติและทุกประเทศ ให้ไปถึงพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 10, 'พระองค์ได้ทรงโปรดให้เราทั้งหลายเป็นกษัตริย์และเป็นปุโรหิตของพระเจ้าของเรา และเราทั้งหลายจะได้ครอบครองแผ่นดินโลก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 11, 'แล้วข้าพเจ้าก็มองดู และข้าพเจ้าได้ยินเสียงทูตสวรรค์เป็นอันมากนับเป็นโกฏิๆเป็นแสนๆ ซึ่งอยู่ล้อมรอบพระที่นั่งรอบสัตว์และผู้อาวุโสทั้งหลายนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 12, 'ร้องเสียงดังว่า “พระเมษโปดกผู้ทรงถูกปลงพระชนม์แล้วนั้น เป็นผู้ที่สมควรได้รับฤทธิ์เดช ทรัพย์สมบัติ ปัญญา อานุภาพ เกียรติ สง่าราศี และคําสดุดี”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 13, 'และข้าพเจ้าได้ยินเสียงสิ่งมีชีวิตทั้งหมด ทั้งในสวรรค์ ในแผ่นดินโลก ใต้แผ่นดินโลก ในมหาสมุทร และบรรดาที่อยู่ในที่เหล่านั้น ร้องว่า “ขอให้คําสดุดีและเกียรติ และสง่าราศีและฤทธิ์เดช จงมีแด่พระองค์ผู้ประทับบนพระที่นั่ง และแด่พระเมษโปดกตลอดไปเป็นนิตย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 14, 'และสัตว์ทั้งสี่นั้นก็ร้องว่า “เอเมน” และผู้อาวุโสทั้งยี่สิบสี่ก็ทรุดตัวลงนมัสการพระองค์ ผู้ทรงพระชนม์อยู่ตลอดไปเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 1, 'เมื่อพระเมษโปดกทรงแกะตราดวงหนึ่งนั้นออกแล้ว ข้าพเจ้าก็แลเห็น และได้ยินสัตว์ตัวหนึ่งในสัตว์สี่ตัวนั้นร้องดุจเสียงฟ้าร้องว่า “มาดูเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 2, 'ข้าพเจ้าก็แลเห็น และดูเถิด มีม้าขาวตัวหนึ่ง และผู้ที่ขี่ม้านั้นถือธนู และได้รับมงกุฎ และผู้นั้นก็ออกไปอย่างมีชัย และเพื่อได้ชัยชนะ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 3, 'เมื่อพระองค์ทรงแกะตราดวงที่สองนั้นแล้ว ข้าพเจ้าก็ได้ยินสัตว์ตัวที่สองร้องว่า “มาดูเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 4, 'และมีม้าอีกตัวหนึ่งออกไปเป็นม้าสีแดงสด ผู้ที่ขี่ม้าตัวนี้ได้รับอนุญาตให้นําสันติสุขไปจากแผ่นดินโลก เพื่อให้คนทั้งปวงรบราฆ่าฟันกัน และผู้นี้ได้รับดาบใหญ่เล่มหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 5, 'เมื่อพระองค์ทรงแกะตราดวงที่สามนั้นแล้ว ข้าพเจ้าก็ได้ยินสัตว์ตัวที่สามร้องว่า “มาดูเถิด” แล้วข้าพเจ้าก็แลเห็น และดูเถิด มีม้าดําตัวหนึ่ง และผู้ที่ขี่ม้านั้นถือตราชู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 6, 'แล้วข้าพเจ้าก็ได้ยินเสียงออกมาจากท่ามกลางสัตว์ทั้งสี่นั้นว่า “ข้าวสาลีราคาทะนานละหนึ่งเดนาริอัน ข้าวบาร์เลย์สามทะนานต่อหนึ่งเดนาริอัน และเจ้าอย่าทําอันตรายแก่น้ํามันและน้ําองุ่น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 7, 'เมื่อพระองค์ทรงแกะตราดวงที่สี่นั้นแล้ว ข้าพเจ้าก็ได้ยินเสียงสัตว์ตัวที่สี่ร้องว่า “มาดูเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 8, 'แล้วข้าพเจ้าก็แลเห็น และดูเถิด มีม้าสีกะเลียวตัวหนึ่ง ผู้ที่นั่งบนหลังม้านั้นมีชื่อว่าความตาย และนรกก็ติดตามเขามาด้วย และได้ให้ทั้งสองนี้มีอํานาจล้างผลาญแผ่นดินโลกได้หนึ่งในสี่ส่วน ด้วยดาบ ด้วยความอดอยาก ด้วยความตาย และด้วยสัตว์ร้ายแห่งแผ่นดิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 9, 'เมื่อพระองค์ทรงแกะตราดวงที่ห้านั้นแล้ว ข้าพเจ้าก็แลเห็นดวงวิญญาณใต้แท่นบูชา เป็นวิญญาณของคนทั้งหลายที่ถูกฆ่าเพราะพระวจนะของพระเจ้า และเพราะคําพยานที่เขายึดถือนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 10, 'เขาเหล่านั้นร้องเสียงดังว่า “โอ ข้าแต่องค์พระผู้เป็นเจ้า ผู้บริสุทธิ์และสัตย์จริง อีกนานเท่าใดพระองค์จึงจะทรงพิพากษา และตอบสนองให้เลือดของเราต่อคนทั้งหลายที่อยู่ในโลก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 11, 'แล้วพระองค์ทรงประทานเสื้อสีขาวแก่คนเหล่านั้นทุกคน และทรงกําชับเขาให้หยุดพักต่อไปอีกหน่อย จนกว่าเพื่อนผู้รับใช้ของเขา และพวกพี่น้องของเขาจะถูกฆ่าเหมือนกับเขานั้นจะครบจํานวน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 12, 'เมื่อพระองค์ทรงแกะตราดวงที่หกนั้นแล้ว ดูเถิด ข้าพเจ้าก็ได้เห็นแผ่นดินไหวใหญ่โต ดวงอาทิตย์ก็กลายเป็นมืดดําดุจผ้ากระสอบขนสัตว์ และดวงจันทร์ก็กลายเป็นสีเลือด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 13, 'และดวงดาวทั้งหลายในท้องฟ้าก็ตกลงบนแผ่นดิน เหมือนต้นมะเดื่ออันหวั่นไหวด้วยลมกล้าจนทําให้ผลหล่นลงไม่ทันสุก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 14, 'ท้องฟ้าก็หายไปเหมือนกับหนังสือที่เขาม้วนขึ้นไปหมด และภูเขาทุกลูกและเกาะทุกเกาะก็เลื่อนไปจากที่เดิม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 15, 'แล้วกษัตริย์ทั้งหลายในโลก พวกคนใหญ่คนโต เศรษฐี นายทหารใหญ่ ผู้มีอํานาจ และทุกคนทั้งที่เป็นทาสและเป็นอิสระ ก็ซ่อนตัวอยู่ในถ้ําและโขดหินตามภูเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 16, 'พวกเขาร้องบอกกับภูเขาและโขดหินว่า “จงล้มทับเราเถิด จงซ่อนเราไว้ให้พ้นจากพระพักตร์ของพระองค์ ผู้ประทับอยู่บนพระที่นั่ง และให้พ้นจากพระพิโรธของพระเมษโปดกนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 17, 'เพราะว่าวันสําคัญแห่งพระพิโรธของพระองค์มาถึงแล้ว และผู้ใดจะทนอยู่ได้เล่า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 1, 'ภายหลังเหตุการณ์เหล่านี้ ข้าพเจ้าได้เห็นทูตสวรรค์สี่องค์ยืนอยู่ที่มุมทั้งสี่ของแผ่นดินโลก ห้ามลมในแผ่นดินโลกทั้งสี่ทิศไว้ เพื่อไม่ให้ลมพัดบนบก ในทะเล หรือที่ต้นไม้ใดๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 2, 'แล้วข้าพเจ้าก็เห็นทูตสวรรค์อีกองค์หนึ่งปรากฏขึ้นมาจากทิศตะวันออก ถือดวงตราของพระเจ้าผู้ทรงพระชนม์อยู่ และท่านได้ร้องประกาศด้วยเสียงอันดังแก่ทูตสวรรค์ทั้งสี่ ผู้ได้รับมอบอํานาจให้ทําอันตรายแก่แผ่นดินและทะเลนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 3, 'ว่า “จงอย่าทําอันตรายแผ่นดิน ทะเลหรือต้นไม้ จนกว่าเราจะได้ประทับตราไว้ที่หน้าผากผู้รับใช้ทั้งหลายของพระเจ้าของเราเสียก่อน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 4, 'และข้าพเจ้าได้ยินจํานวนของผู้ที่ได้การประทับตรา คือผู้ที่ได้การประทับตรานั้น ก็มาจากทุกตระกูลในชนชาติอิสราเอลได้แสนสี่หมื่นสี่พันคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 5, 'ผู้ที่มาจากตระกูลยูดาห์ได้การประทับตราหมื่นสองพันคน ผู้ที่มาจากตระกูลรูเบนได้การประทับตราหมื่นสองพันคน ผู้ที่มาจากตระกูลกาดได้การประทับตราหมื่นสองพันคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 6, 'ผู้ที่มาจากตระกูลอาเชอร์ได้การประทับตราหมื่นสองพันคน ผู้ที่มาจากตระกูลนัฟทาลีได้การประทับตราหมื่นสองพันคน ผู้ที่มาจากตระกูลมนัสเสห์ได้การประทับตราหมื่นสองพันคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 7, 'ผู้ที่มาจากตระกูลสิเมโอนได้การประทับตราหมื่นสองพันคน ผู้ที่มาจากตระกูลเลวีได้การประทับตราหมื่นสองพันคน ผู้ที่มาจากตระกูลอิสสาคาร์ได้การประทับตราหมื่นสองพันคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 8, 'ผู้ที่มาจากตระกูลเศบูลุนได้การประทับตราหมื่นสองพันคน ผู้ที่มาจากตระกูลโยเซฟได้การประทับตราหมื่นสองพันคน ผู้ที่มาจากตระกูลเบนยามินได้การประทับตราหมื่นสองพันคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 9, 'ต่อจากนั้นมา ข้าพเจ้าก็มองดู และดูเถิด คนมากมาย ถ้ามีผู้ใดจะนับประมาณมิได้เลย มาจากทุกชาติ ทุกตระกูล ประชากร และทุกภาษา คนเหล่านั้นสวมเสื้อสีขาว ถือใบตาลยืนอยู่หน้าพระที่นั่ง และต่อพระพักตร์พระเมษโปดก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 10, 'คนเหล่านั้นร้องเสียงดังว่า “ความรอดมีอยู่ที่พระเจ้าของเราผู้ประทับบนพระที่นั่ง และมีอยู่ที่พระเมษโปดก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 11, 'และทูตสวรรค์ทั้งปวงที่ยืนรอบพระที่นั่ง รอบผู้อาวุโส และรอบสัตว์ทั้งสี่นั้น ก้มลงกราบหน้าพระที่นั่ง และนมัสการพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 12, 'กล่าวว่า “เอเมน ความสรรเสริญ สง่าราศี ปัญญา การขอบพระคุณ พระเกียรติ อํานาจ และฤทธิ์เดช จงมีแด่พระเจ้าของเราตลอดไปเป็นนิตย์ เอเมน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 13, 'และคนหนึ่งในพวกผู้อาวุโสนั้นถามข้าพเจ้าว่า “คนที่สวมเสื้อสีขาวเหล่านี้คือใคร และมาจากไหน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 14, 'ข้าพเจ้าตอบท่านว่า “ท่านเจ้าข้า ท่านก็ทราบอยู่แล้ว” ท่านจึงบอกข้าพเจ้าว่า “คนเหล่านี้คือคนที่มาจากความทุกข์เวทนาครั้งใหญ่ พวกเขาได้ชําระล้างเสื้อผ้าของเขาในพระโลหิตของพระเมษโปดกจนเสื้อผ้านั้นขาวสะอาด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 15, 'เพราะเหตุนั้นเขาทั้งหลายจึงได้อยู่หน้าพระที่นั่งของพระเจ้า และปรนนิบัติพระองค์ในพระวิหารของพระองค์ทั้งกลางวันและกลางคืน และพระองค์ผู้ประทับบนพระที่นั่งจะสถิตอยู่ท่ามกลางเขาเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 16, 'พวกเขาจะไม่หิวกระหายอีกเลย แสงแดดและความร้อนจะไม่ส่องต้องเขาอีกต่อไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 17, 'เพราะว่าพระเมษโปดกผู้ทรงอยู่กลางพระที่นั่งนั้นจะทรงเลี้ยงดูเขาไว้ และจะทรงนําเขาไปให้ถึงน้ําพุแห่งชีวิต และพระเจ้าจะทรงเช็ดน้ําตาทุกหยดจากตาของเขาเหล่านั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 1, 'เมื่อพระองค์ทรงแกะตราดวงที่เจ็ด ความเงียบก็ครอบคลุมสวรรค์อยู่ประมาณครึ่งชั่วโมง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 2, 'แล้วข้าพเจ้าก็เห็นทูตสวรรค์ทั้งเจ็ดองค์ที่ยืนอยู่เฉพาะพระพักตร์พระเจ้านั้น ได้รับพระราชทานแตรเจ็ดคัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 3, 'และทูตสวรรค์อีกองค์หนึ่งถือกระถางไฟทองคําออกมายืนอยู่ที่แท่น และทรงประทานเครื่องหอมเป็นอันมากแก่ทูตองค์นั้น เพื่อให้ถวายร่วมกับคําอธิษฐานของวิสุทธิชนทั้งปวงบนแท่นทองคําที่อยู่หน้าพระที่นั่งนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 4, 'และควันเครื่องหอมนั้นก็ลอยขึ้นไปพร้อมกับคําอธิษฐานของวิสุทธิชนทั้งหลาย จากมือทูตสวรรค์สู่เบื้องพระพักตร์ของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 5, 'แล้วทูตสวรรค์องค์นั้นก็นํากระถางไปบรรจุไฟจากแท่นจนเต็ม และโยนกระถางนั้นลงบนแผ่นดินโลก และมีเสียงต่างๆ ฟ้าร้อง ฟ้าแลบ และแผ่นดินไหว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 6, 'และทูตสวรรค์เจ็ดองค์ที่ถือแตรทั้งเจ็ดนั้นต่างก็เตรียมพร้อมที่จะเป่า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 7, 'เมื่อทูตสวรรค์องค์แรกเป่าแตรขึ้น ลูกเห็บและไฟปนด้วยเลือดก็ถูกทิ้งลงบนแผ่นดิน ต้นไม้ไหม้ไปหนึ่งในสามส่วน และหญ้าเขียวสดไหม้ไปหมดสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 8, 'เมื่อทูตสวรรค์องค์ที่สองเป่าแตรขึ้น ก็มีสิ่งหนึ่งเหมือนภูเขาใหญ่กําลังลุกไหม้ถูกทิ้งลงไปในทะเล และทะเลนั้นได้กลายเป็นเลือดเสียหนึ่งในสามส่วน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 9, 'สัตว์ทั้งปวงที่มีชีวิตอยู่ในทะเลนั้นตายเสียหนึ่งในสามส่วน และบรรดาเรือกําปั่นแตกเสียหนึ่งในสามส่วน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 10, 'เมื่อทูตสวรรค์องค์ที่สามเป่าแตรขึ้น ก็มีดาวใหญ่ดวงหนึ่งเป็นเปลวไฟลุกโพลงดุจโคมไฟตกจากท้องฟ้า ดาวนั้นตกลงบนแม่น้ําหนึ่งในสามส่วน และตกที่บ่อน้ําพุทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 11, 'ดาวดวงนี้มีชื่อว่าบอระเพ็ด รสของน้ํากลายเป็นรสขมเสียหนึ่งในสามส่วน และคนเป็นอันมากก็ได้ตายไปเพราะน้ํานั้นกลายเป็นน้ํารสขมไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 12, 'เมื่อทูตสวรรค์องค์ที่สี่เป่าแตรขึ้น ดวงอาทิตย์ก็ถูกทําลายไปหนึ่งในสามส่วน ดวงจันทร์และดวงดาวทั้งหลายก็เช่นเดียวกันจึงมืดไปหนึ่งในสามส่วน กลางวันก็ไม่สว่างเสียหนึ่งในสามส่วน และกลางคืนก็เช่นเดียวกับกลางวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 13, 'แล้วข้าพเจ้าก็มองดูและได้ยินทูตสวรรค์องค์หนึ่งที่บินอยู่ในท้องฟ้า ร้องประกาศเสียงดังว่า “วิบัติ วิบัติ วิบัติ จะมีแก่คนทั้งหลายที่อยู่บนแผ่นดินโลก เพราะเสียงแตรของทูตสวรรค์ทั้งสามองค์กําลังจะเป่าอยู่แล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 1, 'เมื่อทูตสวรรค์องค์ที่ห้าเป่าแตรขึ้น ข้าพเจ้าก็เห็นดาวดวงหนึ่งตกจากฟ้าลงมาที่แผ่นดินโลก และประทานลูกกุญแจสําหรับเหวที่ไม่มีก้นเหวให้แก่ดาวดวงนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 2, 'เมื่อเขาเปิดเหวที่ไม่มีก้นเหวนั้น ก็มีควันพลุ่งขึ้นมาจากเหวนั้นดุจควันที่เตาใหญ่ และดวงอาทิตย์และอากาศก็มืดไป เพราะเหตุควันที่ขึ้นมาจากเหวนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 3, 'มีฝูงตั๊กแตนบินออกจากควันนั้นมายังแผ่นดินโลก ได้ประทานอํานาจแก่ตั๊กแตนนั้น เหมือนกับอํานาจของแมงป่องแห่งแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 4, 'และมีคําสั่งแก่มันไม่ให้ทําร้ายหญ้าบนแผ่นดินโลก หรือพืชเขียว หรือต้นไม้ แต่ให้ทําร้ายคนเหล่านั้นที่ไม่มีตราของพระเจ้าบนหน้าผากของเขาเท่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 5, 'และไม่ให้ฆ่าคนเหล่านั้น แต่ให้ทรมานเขาห้าเดือน การทรมานนั้นเป็นการทรมานที่เหมือนกับถูกแมงป่องต่อย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 6, 'ตลอดเวลาเหล่านั้น คนทั้งหลายจะแสวงหาความตายแต่จะไม่พบ เขาอยากจะตาย แต่ความตายจะหนีไปจากเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 7, 'ตั๊กแตนนั้นมีรูปร่างเหมือนม้าที่ผูกเครื่องพร้อมสําหรับออกศึก บนหัวมีสิ่งหนึ่งที่ดูเหมือนมงกุฎทองคํา หน้ามันเหมือนหน้ามนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 8, 'ผมมันเหมือนผมผู้หญิง ฟันมันเหมือนฟันสิงโต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 9, 'มันมีทับทรวงเหมือนกับทับทรวงเหล็ก เสียงปีกมันเหมือนเสียงรถม้าเป็นอันมากกรูเข้ารบข้าศึก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 10, 'มันมีหางเหมือนหางแมงป่อง และหางมันนั้นมีเหล็กใน มันมีอํานาจที่จะทําร้ายมนุษย์ตลอดห้าเดือน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 11, 'มันมีทูตแห่งเหวที่ไม่มีก้นเหวนั้นเป็นกษัตริย์ปกครองมัน ที่มีชื่อเรียกในภาษาฮีบรูว่า อาบัดโดน แต่ในภาษากรีกเรียกว่า อปอลลิโยน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 12, 'วิบัติอย่างที่หนึ่งผ่านไปแล้ว ดูเถิด ยังมีวิบัติอีกสองอย่างที่จะเกิดขึ้นในภายหน้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 13, 'เมื่อทูตสวรรค์องค์ที่หกเป่าแตรขึ้น ข้าพเจ้าได้ยินเสียงออกมาจากเชิงงอนมุมทั้งสี่ของแท่นทองคําที่อยู่เบื้องพระพักตร์พระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 14, 'เสียงนั้นสั่งทูตสวรรค์องค์ที่หกที่ถือแตรนั้นว่า “จงแก้มัดทูตสวรรค์ทั้งสี่ที่ถูกมัดไว้ที่แม่น้ําใหญ่นั้น คือแม่น้ํายูเฟรติส”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 15, 'ทูตสวรรค์ทั้งสี่ก็ถูกแก้ปล่อยไป ซึ่งทรงเตรียมไว้สําหรับชั่วโมง วัน เดือน และปี ที่จะให้ฆ่ามนุษย์เสียหนึ่งในสามส่วน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 16, 'และจํานวนพลทหารม้ามีสองร้อยล้าน นี่คือจํานวนที่ข้าพเจ้าได้ยิน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 17, 'ในนิมิตนั้นข้าพเจ้าสังเกตเห็นม้าเป็นดังนี้คือ ผู้ที่นั่งบนหลังม้านั้น ก็มีทับทรวงสีไฟ สีพลอยสีแดง และสีกํามะถัน หัวม้าทั้งหลายนั้นเหมือนหัวสิงโต มีไฟและควันและกํามะถันพลุ่งออกมาจากปากของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 18, 'มนุษย์ถูกฆ่าเสียหนึ่งในสามส่วนด้วยภัยพิบัติสามอย่างนี้ คือ ไฟและควันและกํามะถันที่พลุ่งออกมาจากปากมันนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 19, 'เพราะว่าฤทธิ์ของม้านั้นอยู่ที่ปากและหาง หางของมันเหมือนงูและมีหัว สิ่งเหล่านี้ทําให้มันทําร้ายคนได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 20, 'มนุษย์ทั้งหลายที่เหลืออยู่ ที่มิได้ถูกฆ่าด้วยภัยพิบัติเหล่านี้ ยังไม่ได้กลับใจเสียใหม่จากงานที่มือเขาได้กระทํา ไม่ได้เลิกบูชาผี บูชา ‘รูปเคารพที่ทําด้วยทองคํา เงิน ทองเหลือง หินและไม้ รูปเคารพเหล่านั้นจะดูหรือฟังหรือเดินก็ไม่ได้’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 21, 'และเขาก็มิได้กลับใจเสียใหม่จากการฆาตกรรม และการเวทมนตร์ การล่วงประเวณี และการลักขโมย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 1, 'และข้าพเจ้าได้เห็นทูตสวรรค์ที่มีฤทธิ์มากอีกองค์หนึ่งลงมาจากสวรรค์ มีเมฆคลุมตัวท่าน และมีรุ้งบนศีรษะท่าน และหน้าท่านเหมือนดวงอาทิตย์ และเท้าท่านเหมือนเสาไฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 2, 'ท่านถือหนังสือเล็กๆม้วนหนึ่งซึ่งคลี่อยู่ในมือของท่าน ท่านวางเท้าขวาของท่านบนทะเล และเท้าซ้ายของท่านบนบก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 3, 'ท่านร้องเสียงดังดุจเสียงสิงโตคําราม เมื่อท่านร้องแล้ว เสียงฟ้าร้องทั้งเจ็ดเสียงก็ดังขึ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 4, 'เมื่อเสียงฟ้าร้องทั้งเจ็ดดังขึ้นแล้ว ข้าพเจ้าจึงลงมือจะเขียน แต่ข้าพเจ้าได้ยินพระสุรเสียงจากสวรรค์ตรัสแก่ข้าพเจ้าว่า “จงประทับตราปิดข้อความซึ่งฟ้าร้องทั้งเจ็ดได้ร้องนั้น จงอย่าเขียนข้อความเหล่านั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 5, 'ฝ่ายทูตสวรรค์องค์ที่ข้าพเจ้าเห็นยืนอยู่ทั้งบนทะเลและบนบกนั้นได้ชูมือขึ้นสู่ท้องฟ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 6, 'และปฏิญาณโดยอ้างพระนามของพระองค์ผู้ทรงพระชนม์อยู่เป็นนิตย์ ผู้ได้ ‘ทรงสร้างฟ้าสวรรค์ และสรรพสิ่งซึ่งมีอยู่ในฟ้าสวรรค์นั้น ทรงสร้างแผ่นดินโลก และสรรพสิ่งซึ่งมีอยู่ในแผ่นดินโลกนั้น และทรงสร้างทะเล กับสรรพสิ่งซึ่งมีอยู่ในทะเลนั้น’ ว่า จะไม่มีการเนิ่นช้าอีกต่อไปแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 7, 'แต่ว่าในวันแห่งเสียงของทูตสวรรค์องค์ที่เจ็ดนั้น คือเมื่อท่านจะเป่าแตรขึ้น ความลึกลับของพระเจ้าที่พระองค์ได้ตรัสไว้แก่พวกศาสดาพยากรณ์ ซึ่งเป็นผู้รับใช้ของพระองค์นั้นก็จะสําเร็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 8, 'และพระสุรเสียงที่ข้าพเจ้าได้ยินจากสวรรค์นั้นตรัสกับข้าพเจ้าอีกว่า “จงไปรับหนังสือเล็กๆม้วนนั้นที่คลี่อยู่ในมือของทูตสวรรค์องค์ที่ยืนอยู่ทั้งบนทะเลและบนบกนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 9, 'ข้าพเจ้าจึงไปหาทูตสวรรค์องค์นั้นและกล่าวแก่ท่านว่า “ขอหนังสือม้วนเล็กนั้นเถิด” ท่านจึงตอบข้าพเจ้าว่า “เอาไปเถิด และกินมันเสีย มันจะทําให้ท้องเจ้าขม แต่เมื่ออยู่ในปากของเจ้า มันจะหวานเหมือนน้ําผึ้ง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 10, 'ข้าพเจ้ารับหนังสือม้วนเล็กนั้นจากมือทูตสวรรค์แล้วก็กินเข้าไป ขณะที่มันอยู่ในปากของข้าพเจ้านั้นมันก็หวานเหมือนน้ําผึ้ง แต่เมื่อข้าพเจ้ากินมันเข้าไปแล้วท้องข้าพเจ้าก็ขม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 11, 'และท่านบอกข้าพเจ้าว่า “เจ้าต้องพยากรณ์อีก ต่อชนชาติทั้งหลาย บรรดาประชาชาติ ภาษา และกษัตริย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 1, 'ท่านผู้หนึ่งจึงเอาไม้อ้อท่อนหนึ่งให้ข้าพเจ้ารูปร่างเหมือนไม้เรียว และทูตสวรรค์องค์นั้นยืนอยู่กล่าวว่า “จงลุกขึ้นไปวัดพระวิหารของพระเจ้า และแท่นบูชา และคํานวณคนทั้งหลายซึ่งนมัสการในนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 2, 'แต่ไม่ต้องวัดลานชั้นนอกพระวิหารนั้น เพราะว่าที่นั่นได้มอบไว้แก่คนต่างชาติแล้ว และเขาจะเหยียบย่ําเมืองบริสุทธิ์ลงใต้เท้าตลอดสี่สิบสองเดือน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 3, 'และเราจะให้ฤทธิ์อํานาจแก่พยานทั้งสองของเรา และเขาจะพยากรณ์ตลอดพันสองร้อยหกสิบวัน นุ่งห่มด้วยผ้ากระสอบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 4, 'พยานทั้งสองนั้นคือต้นมะกอกเทศสองต้น และคันประทีปสองคันที่ตั้งอยู่เบื้องพระพักตร์พระเจ้า ผู้ทรงเป็นเจ้าแห่งแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 5, 'ถ้าผู้ใดประสงค์จะทําร้ายพยานทั้งสองนั้น ไฟก็จะพลุ่งออกจากปากเขาเผาผลาญศัตรูผู้นั้น ถ้าผู้ใดจะทําร้ายพยานทั้งสอง ผู้นั้นก็จะต้องตายในลักษณะนี้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 6, 'พยานทั้งสองมีฤทธิ์ปิดท้องฟ้าได้ เพื่อไม่ให้ฝนตกในระหว่างวันเหล่านั้นที่เขากําลังพยากรณ์ และมีฤทธิ์อํานาจเหนือน้ําทําให้กลายเป็นเลือดได้ และมีฤทธิ์บันดาลให้ภัยพิบัติต่างๆกระหน่ําโลก กี่ครั้งก็ได้ตามความปรารถนาของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 7, 'และเมื่อเสร็จสิ้นการเป็นพยานแล้ว สัตว์ร้ายที่ขึ้นมาจากเหวที่ไม่มีก้นเหวก็จะสู้รบกับเขา จะชนะเขาและจะฆ่าเขาเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 8, 'และศพของเขาจะอยู่ที่ถนนในเมืองใหญ่นั้น ซึ่งตามฝ่ายจิตวิญญาณเรียกว่า เมืองโสโดมและอียิปต์ อันเป็นเมืองซึ่งองค์พระผู้เป็นเจ้าของเราถูกตรึงด้วย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 9, 'คนหลายชาติ หลายตระกูล หลายภาษา หลายประชาชาติ จะเพ่งดูศพเขาตลอดสามวันครึ่ง และจะไม่ยอมให้เอาศพนั้นใส่อุโมงค์เลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 10, 'คนทั้งหลายซึ่งอยู่ในแผ่นดินโลกจะยินดีเพราะเขา และจะสนุกสนานรื่นเริง จะให้ของขวัญแก่กัน เพราะว่าผู้พยากรณ์ทั้งสองนี้ได้ทรมานคนเหล่านั้นที่อาศัยอยู่ในโลก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 11, 'เมื่อเวลาผ่านไปสามวันครึ่งแล้ว ลมปราณแห่งชีวิตจากพระเจ้าก็เข้าสู่ศพของเขาอีก และเขาก็ลุกขึ้นยืน คนทั้งหลายที่ได้เห็นเขาก็มีความหวาดกลัวเป็นอันมาก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 12, 'คนทั้งหลายได้ยินพระสุรเสียงดังมาจากสวรรค์ ตรัสแก่เขาว่า “จงขึ้นมาที่นี่เถิด” และพวกศัตรูก็เห็นเขาขึ้นไปในหมู่เมฆสู่สวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 13, 'และในเวลานั้นก็เกิดแผ่นดินไหวใหญ่ และเมืองนั้นก็ถล่มลงเสียหนึ่งในสิบส่วน มีคนตายเพราะแผ่นดินไหวเจ็ดพันคน และคนที่เหลืออยู่นั้นมีความหวาดกลัวยิ่ง และได้ถวายพระเกียรติแด่พระเจ้าแห่งสวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 14, 'วิบัติอย่างที่สองก็ผ่านไปแล้ว ดูเถิด วิบัติอย่างที่สามก็จะมาถึงในไม่ช้านี้แหละ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 15, 'และทูตสวรรค์องค์ที่เจ็ดก็เป่าแตรขึ้น และมีเสียงหลายๆเสียงกล่าวขึ้นดังๆในสวรรค์ว่า “ราชอาณาจักรทั้งหลายแห่งพิภพนี้ได้กลับเป็นราชอาณาจักรทั้งหลายขององค์พระผู้เป็นเจ้าของเรา และเป็นของพระคริสต์ของพระองค์ และพระองค์จะทรงครอบครองตลอดไปเป็นนิตย์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 16, 'และผู้อาวุโสยี่สิบสี่คนซึ่งนั่งในที่นั่งของตนเบื้องพระพักตร์พระเจ้าก็ทรุดตัวลงกราบนมัสการพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 17, 'และทูลว่า “โอ ข้าแต่พระเจ้า องค์พระผู้เป็นเจ้า ผู้ทรงฤทธานุภาพสูงสุด ผู้ทรงดํารงอยู่บัดนี้ และผู้ได้ทรงดํารงอยู่ในกาลก่อน และผู้จะเสด็จมาในอนาคต ข้าพระองค์ทั้งหลายขอบพระคุณพระองค์ ที่พระองค์ได้ทรงใช้ฤทธานุภาพอันใหญ่ยิ่งของพระองค์ และได้ทรงครอบครอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 18, 'เหล่าประชาชาติมีความโกรธแค้น แต่พระพิโรธของพระองค์ก็มาถึงแล้ว ถึงเวลาที่พระองค์จะทรงพิพากษาคนทั้งหลายที่ตายไปแล้ว และถึงเวลาที่พระองค์จะทรงประทานบําเหน็จแก่ผู้รับใช้ของพระองค์ คือพวกศาสดาพยากรณ์ และวิสุทธิชนทั้งปวง และแก่คนทั้งหลายที่ยําเกรงพระนามของพระองค์ทั้งผู้ใหญ่ผู้น้อย และถึงเวลาแล้วที่พระองค์จะทรงทําลายคนที่ทําลายแผ่นดินโลก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 19, 'แล้วพระวิหารของพระเจ้าในสวรรค์ก็เปิดออก ในพระวิหารนั้นเห็นมีหีบพันธสัญญาของพระองค์ แล้วก็มีฟ้าแลบ และเสียงต่างๆ ฟ้าร้อง แผ่นดินไหว ลูกเห็บก็ตกอย่างหนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 1, 'มีการมหัศจรรย์ใหญ่ยิ่งปรากฏในสวรรค์ คือผู้หญิงคนหนึ่งมีดวงอาทิตย์เป็นอาภรณ์ มีดวงจันทร์อยู่ใต้เท้า และบนศีรษะมีดวงดาวสิบสองดวงเป็นมงกุฎ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 2, 'ผู้หญิงนั้นตั้งครรภ์ และร้องครวญด้วยความเจ็บครรภ์ที่ใกล้จะคลอด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 3, 'และมีการมหัศจรรย์อีกอย่างหนึ่งปรากฏในสวรรค์ ดูเถิด มีพญานาคใหญ่สีแดงตัวหนึ่ง มีเจ็ดหัวและมีสิบเขา และที่หัวเหล่านั้นมีมงกุฎเจ็ดอัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 4, 'หางพญานาคตวัดดวงดาวในท้องฟ้าทิ้งลงมาที่แผ่นดินโลกเสียหนึ่งในสามส่วน และพญานาคนั้นยืนอยู่เบื้องหน้าผู้หญิงที่กําลังจะคลอดบุตร เพื่อจะกินบุตรเมื่อคลอดออกมาแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 5, 'หญิงนั้นคลอดบุตรชาย ผู้ซึ่งจะครอบครองประชาชาติทั้งปวงด้วยคทาเหล็ก และบุตรนั้นได้ขึ้นไปถึงพระเจ้า ถึงพระที่นั่งของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 6, 'และหญิงนั้นก็หนีเข้าไปในถิ่นทุรกันดาร ที่นางมีสถานที่ซึ่งพระเจ้าได้ทรงจัดเตรียมไว้ให้ เพื่อนางจะได้รับการเลี้ยงดูอยู่ที่นั่นตลอดพันสองร้อยหกสิบวัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 7, 'และมีสงครามเกิดขึ้นในสวรรค์ มีคาเอลและพวกทูตสวรรค์ของท่านได้ต่อสู้กับพญานาค และพญานาคกับพวกทูตของมันก็ต่อสู้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 8, 'แต่ฝ่ายพญานาคแพ้ และพวกพญานาคไม่มีที่อยู่ในสวรรค์อีกเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 9, 'พญานาคใหญ่ซึ่งเป็นงูดึกดําบรรพ์ ที่เขาเรียกกันว่า พญามารและซาตาน ผู้ล่อลวงมนุษย์ทั้งโลก พญานาคและพวกทูตของมันก็ถูกผลักทิ้งลงมาในแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 10, 'และข้าพเจ้าได้ยินเสียงดังขึ้นในสวรรค์ว่า “บัดนี้ความรอด และฤทธิ์เดช และราชอาณาจักรแห่งพระเจ้าของเรา และอํานาจพระคริสต์ของพระองค์ได้มาถึงแล้ว เพราะว่าผู้ที่กล่าวโทษพวกพี่น้องของเราต่อพระพักตร์พระเจ้าของเรา ทั้งกลางวันและกลางคืนนั้น ก็ได้ถูกผลักทิ้งลงมาแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 11, 'เขาเหล่านั้นชนะพญามารด้วยพระโลหิตของพระเมษโปดก และโดยคําพยานของพวกเขาเอง และเขาไม่ได้เสียดายที่จะพลีชีพของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 12, 'ฉะนั้นสวรรค์และบรรดาผู้ที่อยู่ในสวรรค์จงรื่นเริงยินดีเถิด แต่วิบัติจะมีแก่ผู้ที่อยู่ในแผ่นดินโลกและทะเล เพราะว่าพญามารได้ลงมาหาเจ้าด้วยความโกรธยิ่งนัก เพราะมันรู้ว่าเวลาของมันมีน้อย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 13, 'เมื่อพญานาคนั้นเห็นว่ามันถูกผลักทิ้งลงมาในแผ่นดินโลกแล้ว มันก็ข่มเหงหญิงที่คลอดบุตรชายนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 14, 'แต่ทรงประทานปีกนกอินทรีใหญ่สองปีกแก่หญิงนั้น เพื่อให้นางบินหนีหน้างูเข้าไปในถิ่นทุรกันดารในสถานที่ของนาง จนถึงที่ซึ่งนางจะได้รับการเลี้ยงดู ตลอดวาระหนึ่งและสองวาระและครึ่งวาระ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 15, 'งูนั้นก็พ่นน้ําออกจากปากเหมือนน้ําท่วมไหลตามหญิงนั้น เพื่อจะให้พัดหญิงนั้นไปกับน้ําท่วม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 16, 'แต่แผ่นดินก็ได้ช่วยหญิงนั้นไว้ได้ โดยแยกออกเป็นช่องแล้วสูบน้ําท่วมนั้นที่พ่นออกจากปากพญานาคนั้นลงไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 17, 'พญานาคโกรธแค้นหญิงนั้น มันจึงออกไปทําสงครามกับเชื้อสายของนางที่เหลืออยู่นั้น คือผู้ที่รักษาพระบัญญัติของพระเจ้า และยึดถือคําพยานของพระเยซูคริสต์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 1, 'และข้าพเจ้าได้ยืนอยู่ที่หาดทรายชายทะเล และเห็นสัตว์ร้ายตัวหนึ่งขึ้นมาจากทะเล มันมีเจ็ดหัวและสิบเขา ที่เขาทั้งสิบนั้นมีมงกุฎสิบอัน และมีชื่อที่เป็นคําหมิ่นประมาทจารึกไว้ที่หัวทั้งหลายของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 2, 'สัตว์ร้ายที่ข้าพเจ้าได้เห็นนั้น เหมือนเสือดาว และเท้าเหมือนเท้าหมี และปากเหมือนปากสิงโต และพญานาคได้ให้ฤทธิ์ของมัน และที่นั่งของมัน และสิทธิอํานาจอันใหญ่ยิ่งแก่สัตว์ร้ายนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 3, 'ข้าพเจ้าได้เห็นว่าหัวๆหนึ่งของสัตว์ร้ายดูเหมือนถูกฟันปางตาย แต่แผลที่ถูกฟันนั้นรักษาหายแล้ว คนทั้งโลกติดตามสัตว์ร้ายนั้นไปด้วยความอัศจรรย์ใจ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 4, 'เขาทั้งหลายได้บูชาพญานาคที่ได้ให้อํานาจแก่สัตว์ร้ายนั้น เขาได้บูชาสัตว์ร้ายนั้น กล่าวว่า “ใครจะเปรียบปานสัตว์นี้ได้ และใครสามารถจะทําสงครามกับสัตว์นี้ได้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 5, 'และยอมให้สัตว์ร้ายนั้นมีปากที่พูดคํากล่าวร้ายและหมิ่นประมาท และยอมให้มันใช้อํานาจกระทําอย่างนั้นตลอดสี่สิบสองเดือน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 6, 'มันกล่าวคําหมิ่นประมาทต่อพระเจ้า เพื่อหมิ่นประมาทต่อพระนามของพระองค์ ต่อพลับพลาของพระองค์ และต่อผู้ที่อยู่ในสวรรค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 7, 'และยอมให้มันทําสงครามกับพวกวิสุทธิชน และชนะเขา และให้มันมีอํานาจเหนือชนทุกตระกูล ทุกภาษา และทุกประชาชาติ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 8, 'และบรรดาคนที่อยู่ในแผ่นดินโลกจะบูชาสัตว์ร้ายนั้น คือคนทั้งปวงที่ไม่มีชื่อจดไว้ในหนังสือแห่งชีวิตของพระเมษโปดก ผู้ทรงถูกปลงพระชนม์ตั้งแต่แรกทรงสร้างโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 9, 'ใครมีหูก็ให้ฟังเอาเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 10, 'ผู้ใดที่กําหนดไว้ให้ไปเป็นเชลยผู้นั้นก็จะต้องไปเป็นเชลย ผู้ใดฆ่าเขาด้วยดาบผู้นั้นก็ต้องถูกฆ่าด้วยดาบ นี่แหละคือความอดทนและความเชื่อของพวกวิสุทธิชน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 11, 'และข้าพเจ้าเห็นสัตว์ร้ายอีกตัวหนึ่งขึ้นมาจากแผ่นดิน มีสองเขาเหมือนลูกแกะ และพูดเหมือนพญานาค');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 12, 'มันใช้อํานาจของสัตว์ร้ายตัวเดิมนั้นอย่างครบถ้วนต่อหน้าสัตว์ร้ายตัวเดิมนั้น มันทําให้โลกและคนที่อยู่ในโลกบูชาสัตว์ร้ายตัวเดิมนั้น ที่มีแผลปางตายแต่รักษาหายแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 13, 'สัตว์ร้ายนี้แสดงการมหัศจรรย์ใหญ่ จนกระทําให้ไฟตกลงมาจากฟ้าสู่แผ่นดินโลกประจักษ์แก่ตามนุษย์ทั้งหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 14, 'มันล่อลวงคนทั้งหลายที่อยู่ในโลกด้วยการอัศจรรย์นั้น ซึ่งมันมีอํานาจกระทําท่ามกลางสายตาของสัตว์ร้ายตัวเดิมนั้น และมันสั่งให้คนทั้งหลายที่อยู่ในโลกสร้างรูปจําลองให้แก่สัตว์ร้าย ที่ถูกฟันด้วยดาบแต่ยังมีชีวิตอยู่นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 15, 'และมันมีอํานาจที่จะให้ลมหายใจแก่รูปสัตว์นั้น เพื่อให้รูปสัตว์ร้ายนั้นทั้งพูดได้ และกระทําให้บรรดาคนที่ไม่ยอมบูชารูปสัตว์ร้ายนั้นถึงแก่ความตายได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 16, 'และมันยังได้บังคับคนทั้งปวง ทั้งผู้ใหญ่ผู้น้อย คนมั่งมีและคนจน ไทยและทาส ให้รับเครื่องหมายไว้ที่มือขวาหรือที่หน้าผากของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 17, 'เพื่อไม่ให้ผู้ใดทําการซื้อขายได้ นอกจากผู้ที่มีเครื่องหมายนั้น หรือชื่อของสัตว์ร้ายนั้น หรือเลขชื่อของมัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 18, 'ในเรื่องนี้จงใช้สติปัญญา ถ้าผู้ใดมีความเข้าใจก็ให้คิดตรึกตรองเลขของสัตว์ร้ายนั้น เพราะว่าเป็นเลขของบุคคลผู้หนึ่ง เลขของมันคือหกร้อยหกสิบหก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 1, 'ข้าพเจ้าได้แลเห็น และดูเถิด พระเมษโปดกทรงยืนอยู่ที่ภูเขาศิโยน และผู้ที่อยู่กับพระองค์มีจํานวนแสนสี่หมื่นสี่พันคน ซึ่งเป็นผู้ที่มีพระนามของพระบิดาของพระองค์เขียนไว้ที่หน้าผากของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 2, 'และข้าพเจ้าได้ยินเสียงจากสวรรค์ดุจเสียงน้ํามากหลาย และดุจเสียงฟ้าร้องสนั่น และข้าพเจ้าได้ยินเสียงพวกดีดพิณเขาคู่กําลังบรรเลงอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 3, 'คนเหล่านั้นร้องเพลงราวกับว่า เป็นเพลงบทใหม่ต่อหน้าพระที่นั่ง หน้าสัตว์ทั้งสี่นั้น และหน้าพวกผู้อาวุโส ไม่มีใครสามารถเรียนรู้เพลงบทนั้นได้ นอกจากคนแสนสี่หมื่นสี่พันคนนั้น ที่ได้ทรงไถ่ไว้แล้วจากแผ่นดินโลก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 4, 'คนเหล่านี้เป็นคนที่มิได้มีมลทินกับผู้หญิง เพราะว่าเขาเป็นพวกพรหมจารี พระเมษโปดกเสด็จไปที่ใด คนเหล่านี้ก็ตามเสด็จไปด้วย พวกเขาเป็นผู้ที่ทรงไถ่จากมวลมนุษย์ เป็นผลแรกถวายแด่พระเจ้าและแด่พระเมษโปดก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 5, 'ปากเขาไม่กล่าวคําอุบายเลย เพราะเขาไม่มีความผิดต่อหน้าพระที่นั่งของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 6, 'แล้วข้าพเจ้าได้เห็นทูตสวรรค์อีกองค์หนึ่งที่บินอยู่ในท้องฟ้า เพื่อประกาศข่าวประเสริฐอันเป็นอมตะแก่คนทั้งหลายที่อยู่ในโลก แก่ทุกชาติ ทุกตระกูล ทุกภาษา และประชากร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 7, 'ท่านประกาศด้วยเสียงอันดังว่า “จงยําเกรงพระเจ้า และถวายสง่าราศีแด่พระองค์ เพราะถึงเวลาที่พระองค์จะทรงพิพากษาแล้ว และจงนมัสการพระองค์ ‘ผู้ได้ทรงสร้างฟ้าสวรรค์ แผ่นดินโลก ทะเล’ และบ่อน้ําพุทั้งหลาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 8, 'ทูตสวรรค์อีกองค์หนึ่งตามไปประกาศว่า “บาบิโลนมหานครนั้นล่มจมแล้ว ล่มจมแล้ว เพราะว่านครนั้นทําให้ประชาชาติทั้งปวงดื่มเหล้าองุ่นแห่งความเดือดดาลของเธอในการล่วงประเวณี”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 9, 'และทูตสวรรค์ซึ่งเป็นองค์ที่สามตามไปประกาศด้วยเสียงอันดังว่า “ถ้าผู้ใดบูชาสัตว์ร้ายและรูปของมัน และรับเครื่องหมายของมันไว้ที่หน้าผากหรือที่มือของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 10, 'ผู้นั้นจะต้องดื่มเหล้าองุ่นแห่งพระพิโรธของพระเจ้า ซึ่งไม่ได้ระคนกับสิ่งใด ที่ได้เทลงในถ้วยพระพิโรธของพระองค์ และเขาจะต้องถูกทรมานด้วยไฟและกํามะถันต่อหน้าทูตสวรรค์ผู้บริสุทธิ์ทั้งหลาย และต่อพระพักตร์พระเมษโปดก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 11, 'และควันแห่งการทรมานของเขาพลุ่งขึ้นตลอดไปเป็นนิตย์ และผู้ที่บูชาสัตว์ร้ายและรูปของมัน และผู้ใดก็ตามที่รับเครื่องหมายชื่อของมันจะไม่มีการพักผ่อนเลยทั้งกลางวันและกลางคืน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 12, 'นี่แหละคือความอดทนของพวกวิสุทธิชน คือผู้ที่รักษาพระบัญญัติของพระเจ้า และความเชื่อของพระเยซูไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 13, 'และข้าพเจ้าได้ยินพระสุรเสียงจากสวรรค์สั่งข้าพเจ้าว่า “จงเขียนไว้เถิดว่า ตั้งแต่นี้สืบไปคนทั้งหลายที่ตายในองค์พระผู้เป็นเจ้าจะเป็นสุข” และพระวิญญาณตรัสว่า “จริงอย่างนั้น เพื่อเขาจะได้หยุดพักจากความเหนื่อยยากของเขา และการงานที่เขาได้กระทํานั้นจะติดตามเขาไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 14, 'ข้าพเจ้าได้แลเห็น และดูเถิด มีเมฆขาว และมีผู้หนึ่งประทับบนเมฆนั้นเหมือนกับบุตรมนุษย์ สวมมงกุฎทองคําบนพระเศียร และพระหัตถ์ถือเคียวอันคม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 15, 'และมีทูตสวรรค์อีกองค์หนึ่งออกมาจากพระวิหารร้องทูลพระองค์ ผู้ประทับบนเมฆนั้นด้วยเสียงอันดังว่า “จงใช้เคียวของพระองค์เกี่ยวไปเถิด เพราะว่าถึงเวลาที่พระองค์จะเกี่ยวแล้ว เพราะว่าผลที่จะต้องเก็บเกี่ยวในแผ่นดินโลกนั้นสุกแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 16, 'และพระองค์ผู้ประทับบนเมฆนั้น ได้ทรงตวัดเคียวนั้นบนแผ่นดินโลก และแผ่นดินโลกก็ได้ถูกเกี่ยวแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 17, 'และทูตสวรรค์อีกองค์หนึ่งก็ออกมาจากพระวิหารบนสวรรค์ ถือเคียวอันคมเช่นเดียวกัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 18, 'และทูตสวรรค์อีกองค์หนึ่งผู้มีฤทธิ์เหนือไฟ ได้ออกมาจากแท่นบูชา และร้องบอกทูตองค์นั้นที่ถือเคียวคมนั้นด้วยเสียงอันดังว่า “ท่านจงใช้เคียวคมของท่านเกี่ยวเก็บพวงองุ่นแห่งแผ่นดินโลก เพราะลูกองุ่นนั้นสุกดีแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 19, 'ทูตสวรรค์นั้นก็ตวัดเคียวบนแผ่นดินโลก และเก็บเกี่ยวผลองุ่นแห่งแผ่นดินโลก และขว้างลงไปในบ่อย่ําองุ่นอันใหญ่แห่งพระพิโรธของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 20, 'บ่อย่ําองุ่นถูกย่ําภายนอกเมือง และโลหิตไหลออกจากบ่อย่ําองุ่นนั้นสูงถึงบังเหียนม้า ไหลนองไปประมาณสามร้อยกิโลเมตร');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 1, 'ข้าพเจ้าเห็นหมายสําคัญในสวรรค์อีกประการหนึ่ง ใหญ่ยิ่งและน่าประหลาด คือมีทูตสวรรค์เจ็ดองค์ถือภัยพิบัติเจ็ดอย่าง อันเป็นภัยพิบัติครั้งสุดท้าย เพราะว่าพระพิโรธของพระเจ้าสิ้นสุดลงด้วยภัยพิบัติเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 2, 'ข้าพเจ้าเห็นเป็นเหมือนทะเลแก้วปนไฟ และบรรดาคนที่มีชัยต่อสัตว์ร้าย และรูปของมัน และเครื่องหมายของมัน และเลขประจําชื่อของมัน ยืนอยู่บนทะเลแก้วนั้น พวกเขาถือพิณเขาคู่ของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 3, 'เขาร้องเพลงของโมเสส ซึ่งเป็นผู้รับใช้ของพระเจ้า และเพลงของพระเมษโปดกว่า “ข้าแต่พระเจ้า องค์พระผู้เป็นเจ้า ผู้ทรงฤทธานุภาพสูงสุด พระราชกิจของพระองค์ใหญ่ยิ่งและมหัศจรรย์นัก ข้าแต่องค์พระมหากษัตริย์แห่งวิสุทธิชนทั้งปวง วิถีทางทั้งหลายของพระองค์ยุติธรรมและเที่ยงตรง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 4, 'โอ ข้าแต่องค์พระผู้เป็นเจ้า มีผู้ใดบ้างที่จะไม่ยําเกรงพระองค์ และไม่ถวายพระเกียรติแด่พระนามของพระองค์ เพราะว่าพระองค์ผู้เดียวทรงเป็นผู้บริสุทธิ์ ประชาชาติทั้งปวงจะมานมัสการจําเพาะพระพักตร์พระองค์ เพราะว่าการพิพากษาของพระองค์ปรากฏแจ้งแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 5, 'ต่อจากนี้ข้าพเจ้าได้แลเห็น และดูเถิด พระวิหารของพลับพลาแห่งสักขีพยานในสวรรค์เปิดออก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 6, 'และทูตสวรรค์ทั้งเจ็ดองค์ที่ถือภัยพิบัติทั้งเจ็ด ได้ออกมาจากพระวิหารนั้น นุ่งห่มผ้าป่านสีขาวและบริสุทธิ์ และคาดรัดประคดทองคํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 7, 'และสัตว์ตัวหนึ่งในสี่ตัวนั้นได้เอาขันทองคําเจ็ดใบเต็มด้วยพระพิโรธของพระเจ้า ผู้ทรงพระชนม์อยู่เป็นนิตย์ ส่งให้แก่ทูตสวรรค์ทั้งเจ็ดองค์นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 8, 'และพระวิหารก็เต็มไปด้วยควันซึ่งมาจากสง่าราศีของพระเจ้า และจากฤทธานุภาพของพระองค์ และไม่มีผู้ใดสามารถเข้าไปในพระวิหารนั้นได้ จนกว่าภัยพิบัติทั้งเจ็ดของทูตสวรรค์เจ็ดองค์นั้นจะได้สิ้นสุดลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 1, 'แล้วข้าพเจ้าก็ได้ยินเสียงดังออกมาจากพระวิหาร สั่งทูตสวรรค์ทั้งเจ็ดองค์นั้นว่า “จงไปเถิด เอาขันทั้งเจ็ดใบ ที่เต็มไปด้วยพระพิโรธของพระเจ้า เทลงบนแผ่นดินโลก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 2, 'ทูตสวรรค์องค์แรกจึงออกไปและเทขันของตนลงบนแผ่นดินโลก และคนทั้งหลายที่มีเครื่องหมายของสัตว์ร้าย และบูชารูปของมัน ก็เกิดเป็นแผลร้ายที่เป็นหนองมีทุกข์เวทนาแสนสาหัส');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 3, 'ทูตสวรรค์องค์ที่สองก็เทขันของตนลงในทะเล และทะเลก็กลายเป็นเหมือนเลือดของคนตาย และบรรดาสิ่งที่มีชีวิตอยู่ในทะเลนั้นก็ตายหมดสิ้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 4, 'ทูตสวรรค์องค์ที่สามเทขันของตนลงที่แม่น้ําและบ่อน้ําพุทั้งปวง และน้ําเหล่านั้นก็กลายเป็นเลือด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 5, 'และข้าพเจ้าได้ยินทูตสวรรค์แห่งน้ําร้องว่า “โอ ข้าแต่องค์พระผู้เป็นเจ้า ผู้ดํารงอยู่บัดนี้ และผู้ได้ทรงดํารงอยู่ในกาลก่อน และผู้จะทรงดํารงอยู่ในอนาคต พระองค์ทรงเป็นผู้ชอบธรรม เพราะพระองค์ทรงพิพากษาอย่างนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 6, 'เพราะเขาทั้งหลายได้กระทําให้โลหิตของพวกวิสุทธิชนและของพวกศาสดาพยากรณ์ไหลออก และพระองค์ได้ประทานโลหิตให้เขาดื่ม ด้วยเขาทั้งหลายก็สมควรอยู่แล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 7, 'และข้าพเจ้าได้ยินทูตสวรรค์อีกองค์หนึ่งซึ่งอยู่ที่แท่นบูชาร้องว่า “จริงอย่างนั้น พระเจ้า องค์พระผู้เป็นเจ้า ผู้ทรงฤทธานุภาพสูงสุด การพิพากษาของพระองค์เที่ยงตรงและชอบธรรมแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 8, 'ทูตสวรรค์องค์ที่สี่เทขันของตนลงที่ดวงอาทิตย์ และทรงให้อํานาจแก่ดวงอาทิตย์นั้นที่จะคลอกมนุษย์ด้วยไฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 9, 'ความร้อนแรงกล้าได้คลอกคนทั้งหลาย และพวกเขาพูดหมิ่นประมาทพระนามของพระเจ้า ผู้ซึ่งมีฤทธิ์เหนือภัยพิบัติเหล่านั้น และพวกเขาไม่ได้กลับใจและไม่ได้ถวายพระเกียรติแด่พระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 10, 'ทูตสวรรค์องค์ที่ห้าเทขันของตนลงบนที่นั่งของสัตว์ร้ายนั้น และอาณาจักรของมันก็มืดไป คนเหล่านั้นได้กัดลิ้นของตนด้วยความเจ็บปวด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 11, 'และพูดหมิ่นประมาทพระเจ้าแห่งสวรรค์ เพราะความเจ็บปวดและเพราะแผลที่มีหนองตามตัวของเขา แต่เขาไม่ได้กลับใจเสียใหม่จากการประพฤติของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 12, 'ทูตสวรรค์องค์ที่หกเทขันของตนลงที่แม่น้ําใหญ่ คือแม่น้ํายูเฟรติส ทําให้น้ําในแม่น้ํานั้นแห้งไป เพื่อเตรียมมรรคาไว้สําหรับบรรดากษัตริย์ที่มาจากทิศตะวันออก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 13, 'และข้าพเจ้าเห็นผีโสโครกสามตนรูปร่างคล้ายกบออกมาจากปากพญานาค และออกจากปากสัตว์ร้ายนั้น และออกจากปากของผู้พยากรณ์เท็จ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 14, 'ด้วยว่าผีเหล่านั้นเป็นผีร้ายกระทําการอัศจรรย์ มันออกไปหากษัตริย์ทั้งปวงแห่งแผ่นดินโลกคือทั่วพิภพ เพื่อให้บรรดากษัตริย์เหล่านั้นร่วมกันทําสงครามในวันยิ่งใหญ่ของพระเจ้า ผู้ทรงฤทธานุภาพสูงสุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 15, '“จงดูเถิด เราจะมาเหมือนขโมย ผู้ที่เฝ้าระวังให้ดีและรักษาเสื้อผ้าของตนจะเป็นสุข เกลือกว่าผู้นั้นจะเดินเปลือยกาย และคนทั้งหลายจะได้เห็นความน่าละอายของเขา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 16, 'และมันให้เขาทั้งหลายชุมนุมที่ตําบลหนึ่ง ซึ่งภาษาฮีบรูเรียกว่า อารมาเกดโดน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 17, 'ทูตสวรรค์องค์ที่เจ็ดได้เทขันของตนลงในอากาศ และมีพระสุรเสียงดังออกมาจากพระที่นั่งในพระวิหารแห่งสวรรค์ว่า “สําเร็จแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 18, 'และเกิดมีเสียงต่างๆ มีฟ้าร้อง มีฟ้าแลบ และเกิดแผ่นดินไหวครั้งใหญ่ ซึ่งตั้งแต่มีมนุษย์เกิดมาบนแผ่นดินโลก ไม่เคยมีแผ่นดินไหวร้ายแรงและยิ่งใหญ่เช่นนี้เลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 19, 'มหานครนั้นก็แยกออกเป็นสามส่วน และบ้านเมืองของนานาประชาชาติก็ล่มจม มหานครบาบิโลนนั้นก็อยู่ในความทรงจําต่อเบื้องพระพักตร์พระเจ้า เพื่อจะให้นครนั้นดื่มถ้วยเหล้าองุ่นแห่งพระพิโรธอันใหญ่หลวงของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 20, 'และบรรดาเกาะต่างๆก็หนีหายไป และภูเขาทั้งหลายก็ไม่มีผู้ใดพบ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 21, 'และมีลูกเห็บใหญ่ตกลงมาจากฟ้าถูกคนทั้งปวง แต่ละก้อนหนักประมาณห้าสิบกิโลกรัม คนทั้งหลายจึงพูดหมิ่นประมาทพระเจ้า เพราะภัยพิบัติที่เกิดจากลูกเห็บนั้น เพราะว่าภัยพิบัติจากลูกเห็บนั้นร้ายแรงยิ่งนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 1, 'ทูตสวรรค์องค์หนึ่งในเจ็ดองค์ที่ถือขันเจ็ดใบนั้น มาหาข้าพเจ้าและพูดว่า “เชิญมาที่นี่เถิด ข้าพเจ้าจะให้ท่านดูการพิพากษาลงโทษหญิงแพศยาคนสําคัญที่นั่งอยู่บนน้ํามากหลาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 2, 'คือหญิงที่บรรดากษัตริย์ทั่วแผ่นดินโลกได้ล่วงประเวณีด้วย และคนทั้งหลายที่อยู่ในแผ่นดินโลกก็ได้มัวเมาด้วยเหล้าองุ่นแห่งการล่วงประเวณีของเธอ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 3, 'ทูตสวรรค์องค์นั้นได้นําข้าพเจ้าเข้าไปในถิ่นทุรกันดารโดยพระวิญญาณ และข้าพเจ้าได้เห็นผู้หญิงคนหนึ่งนั่งอยู่บนสัตว์ร้ายสีแดงเข้มตัวหนึ่ง ซึ่งมีชื่อหลายชื่อเป็นคําหมิ่นประมาทเต็มไปทั้งตัว มันมีเจ็ดหัวและสิบเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 4, 'หญิงนั้นนุ่งห่มด้วยผ้าสีม่วงและสีแดงเข้ม และประดับด้วยเครื่องทองคํา เพชรพลอยต่างๆและไข่มุก หญิงนั้นถือถ้วยทองคําที่เต็มด้วยสิ่งน่าสะอิดสะเอียนและของโสโครกแห่งการล่วงประเวณีของตน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 5, 'และที่หน้าผากของหญิงนั้นเขียนชื่อไว้ว่า “ความลึกลับ บาบิโลนมหานคร แม่ของหญิงแพศยาทั้งหลาย และแม่แห่งสิ่งทั้งปวงที่น่าสะอิดสะเอียนแห่งแผ่นดินโลก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 6, 'และข้าพเจ้าเห็นหญิงนั้นเมามายด้วยโลหิตของพวกวิสุทธิชน และโลหิตของคนทั้งหลายที่พลีชีพเพื่อเป็นพยานของพระเยซู เมื่อข้าพเจ้าเห็นหญิงนั้นแล้ว ข้าพเจ้าก็อัศจรรย์ใจยิ่งนัก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 7, 'ทูตสวรรค์องค์นั้นจึงถามข้าพเจ้าว่า “เหตุไฉนท่านจึงอัศจรรย์ใจ ข้าพเจ้าจะบอกให้ท่านรู้ถึงความลึกลับของหญิงนั้น และของสัตว์ร้ายที่มีเจ็ดหัวและสิบเขาที่เป็นพาหนะของหญิงนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 8, 'สัตว์ร้ายที่ท่านได้เห็นนั้นเป็นอยู่ในกาลก่อน แต่บัดนี้มิได้เป็น และมันจะขึ้นมาจากเหวที่ไม่มีก้นเหวเพื่อไปสู่ความพินาศแล้ว และคนทั้งหลายที่อยู่ในโลก ซึ่งไม่มีชื่อจดไว้ในหนังสือแห่งชีวิตตั้งแต่แรกทรงสร้างโลกนั้น ก็จะอัศจรรย์ใจ เมื่อเขาเห็นสัตว์ร้าย ซึ่งได้เป็นอยู่ในกาลก่อน แต่บัดนี้มิได้เป็น และกําลังจะเป็น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 9, 'นี่ต้องใช้สติปัญญา หัวทั้งเจ็ดนั้นคือภูเขาเจ็ดยอดที่หญิงนั้นนั่งอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 10, 'และมีกษัตริย์เจ็ดองค์ ซึ่งห้าองค์ได้ล่วงไปแล้ว องค์หนึ่งกําลังเป็นอยู่ และอีกองค์หนึ่งนั้นยังไม่ได้เป็นขึ้น และเมื่อเป็นขึ้นมาแล้ว จะต้องดํารงอยู่ชั่วขณะหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 11, 'สัตว์ร้ายที่เป็นแล้วเมื่อก่อน แต่เดี๋ยวนี้ไม่ได้เป็นนั้นก็เป็นที่แปด แต่ก็ยังเป็นองค์หนึ่งในเจ็ดองค์นั้น และจะไปสู่ความพินาศ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 12, 'เขาทั้งสิบเขาที่ท่านได้เห็นนั้นคือกษัตริย์สิบองค์ที่ยังไม่ได้เสวยราชสมบัติ แต่จะรับอํานาจอย่างกษัตริย์ด้วยกันกับสัตว์ร้ายนั้นหนึ่งชั่วโมง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 13, 'กษัตริย์ทั้งหลายนั้นมีน้ําพระทัยอย่างเดียวกัน และทรงมอบฤทธิ์และอํานาจของตนไว้แก่สัตว์ร้ายนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 14, 'กษัตริย์เหล่านี้จะกระทําสงครามกับพระเมษโปดก และพระเมษโปดกจะทรงชนะพวกเขา เพราะว่าพระองค์ทรงเป็นเจ้านายเหนือเจ้านายทั้งหลาย และทรงเป็นพระมหากษัตริย์เหนือกษัตริย์ทั้งหลาย และผู้ที่อยู่กับพระองค์นั้นเป็นผู้ที่พระองค์ได้ทรงเรียก และทรงเลือกไว้ และเป็นผู้ที่สัตย์ซื่อ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 15, 'และทูตสวรรค์นั้นบอกข้าพเจ้าว่า “น้ํามากหลายที่ท่านได้เห็นหญิงแพศยานั่งอยู่นั้น ก็คือชนชาติ มวลชน ประชาชาติ และภาษาต่างๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 16, 'เขาสิบเขาที่ท่านได้เห็นอยู่บนสัตว์ร้าย จะพากันเกลียดชังหญิงแพศยานั้น จะกระทําให้นางโดดเดี่ยวอ้างว้างและเปลือยกาย และจะกินเนื้อของหญิงนั้น และเผานางเสียด้วยไฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 17, 'เพราะว่าพระเจ้าทรงดลใจเขาให้กระทําตามพระทัยของพระองค์ โดยการทรงทําให้พวกเขามีความคิดอย่างเดียวกัน และมอบอาณาจักรของเขาให้แก่สัตว์ร้ายนั้น จนถึงจะสําเร็จตามพระวจนะของพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 18, 'และผู้หญิงที่ท่านเห็นนั้นก็คือนครใหญ่ ที่มีอํานาจเหนือกษัตริย์ทั้งหลายทั่วแผ่นดินโลก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 1, 'ภายหลังเหตุการณ์เหล่านี้ข้าพเจ้าก็ได้เห็นทูตสวรรค์อีกองค์หนึ่งลงมาจากสวรรค์ ท่านมีอํานาจใหญ่ยิ่ง และรัศมีของท่านได้ทําให้แผ่นดินโลกสว่างไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 2, 'ท่านได้ร้องประกาศด้วยเสียงกึกก้องว่า “บาบิโลนมหานครล่มจมแล้ว ล่มจมแล้ว กลายเป็นที่อาศัยของผีปีศาจ เป็นที่คุมขังของผีโสโครกทุกอย่าง และเป็นกรงของนกทุกอย่างที่ไม่สะอาดและน่าเกลียด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 3, 'เพราะว่าประชาชาติทั้งปวงได้ดื่มเหล้าองุ่นแห่งความเดือดดาลในการล่วงประเวณีของนครนั้น และบรรดากษัตริย์บนแผ่นดินโลกได้ล่วงประเวณีกับนครนั้น และพ่อค้าทั้งหลายแห่งแผ่นดินโลกก็ได้มั่งมีขึ้นด้วยทรัพย์ฟุ่มเฟือยของนครนั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 4, 'และข้าพเจ้าได้ยินเสียงอีกเสียงหนึ่งประกาศมาจากสวรรค์ว่า “ชนชาติของเรา จงออกมาจากนครนั้นเถิด เพื่อท่านทั้งหลายจะไม่มีส่วนในการบาปของนครนั้น และเพื่อท่านจะไม่ต้องรับภัยพิบัติที่จะเกิดแก่นครนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 5, 'เพราะว่าบาปของนครนั้นกองสูงขึ้นถึงสวรรค์แล้ว และพระเจ้าได้ทรงจําความชั่วช้าแห่งนครนั้นได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 6, 'นครนั้นได้ให้ผลอย่างไร ก็จงให้ผลแก่นครนั้นอย่างนั้น และจงตอบแทนการกระทําของนครนั้นเป็นสองเท่า ในถ้วยที่นครนั้นได้ผสมไว้ก็จงผสมลงเป็นสองเท่าให้นครนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 7, 'นครนั้นได้เย่อหยิ่งจองหองและมีชีวิตอย่างหรูหรามากเท่าใด ก็จงให้นครนั้นได้รับการทรมานและความระทมทุกข์มากเท่านั้น เพราะว่านครนั้นทะนงใจว่า ‘เราดํารงอยู่ในตําแหน่งราชินี ไม่ใช่หญิงม่าย เราจะไม่ประสบความระทมทุกข์เลย’');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 8, 'เหตุฉะนั้น ภัยพิบัติต่างๆของนครนั้นจะเกิดขึ้นในวันเดียว ความตาย และความระทมทุกข์ การกันดารอาหาร และไฟจะเผานครนั้นให้พินาศหมดสิ้น เพราะว่าองค์พระผู้เป็นเจ้า พระเจ้า ผู้ทรงพิพากษานครนั้น ทรงอานุภาพยิ่งใหญ่”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 9, 'บรรดากษัตริย์แห่งแผ่นดินโลกที่ได้ล่วงประเวณีกับนครนั้น และได้มีชีวิตอย่างหรูหราร่วมกันนั้น เมื่อได้เห็นควันไฟที่ไหม้นครนั้น ก็จะพิลาปร่ําไห้คร่ําครวญเพราะนครนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 10, 'พวกกษัตริย์จะยืนอยู่แต่ห่างๆเพราะกลัวภัยแห่งการทรมานของนครนั้น และจะกล่าวว่า “อนิจจาเอ๋ย อนิจจาเอ๋ย บาบิโลนมหานครที่ยิ่งใหญ่ นครที่แข็งแรง เพราะเจ้าได้รับการพิพากษาโทษให้พินาศไปภายในชั่วโมงเดียวเท่านั้น”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 11, 'บรรดาพ่อค้าในแผ่นดินโลกจะร่ําไห้คร่ําครวญเพราะนครนั้น เพราะว่าไม่มีใครซื้อสินค้าของเขาอีกต่อไปแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 12, 'สินค้าเหล่านั้นคือ ทองคํา เงิน เพชรพลอยต่างๆ ไข่มุก ผ้าป่านเนื้อละเอียด ผ้าสีม่วง ผ้าไหม ผ้าสีแดงเข้ม ไม้หอมทุกชนิด บรรดาภาชนะที่ทําด้วยงา บรรดาภาชนะไม้ที่มีราคามาก ภาชนะทองเหลือง ภาชนะเหล็ก ภาชนะหินอ่อน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 13, 'อบเชย เครื่องเทศ เครื่องหอม กํายาน เหล้าองุ่น น้ํามัน ยอดแป้ง ข้าวสาลี สัตว์ต่างๆ แกะ ม้า รถรบ และทาส และชีวิตมนุษย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 14, 'และผลซึ่งจิตของเจ้ากระหายใคร่ได้นั้นก็ล่วงพ้นไปจากเจ้าแล้ว สิ่งสารพัดอันวิเศษยิ่งและหรูหราก็พินาศไปจากเจ้าแล้ว และเจ้าจะไม่ได้พบมันอีกเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 15, 'บรรดาพ่อค้าที่ได้ขายสิ่งของเหล่านั้น จนเป็นคนมั่งมีเพราะนครนั้น จะยืนอยู่แต่ไกลเพราะกลัวภัยจากการทรมานของนครนั้น พวกเขาจะร้องไห้คร่ําครวญด้วยเสียงดัง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 16, 'ว่า “อนิจจาเอ๋ย อนิจจาเอ๋ย มหานครนั้น ที่ได้นุ่งห่มผ้าป่านเนื้อละเอียด ผ้าสีม่วง และผ้าสีแดงเข้ม ที่ได้ประดับด้วยทองคํา เพชรพลอยต่างๆและไข่มุกนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 17, 'เพียงในชั่วโมงเดียว ทรัพย์สมบัติอันยิ่งใหญ่นั้นก็พินาศสูญไปสิ้น” และนายเรือทุกคน คนที่โดยสารเรือ พวกลูกเรือ และคนทั้งหลายที่มีอาชีพทางทะเล ก็ได้ยืนอยู่แต่ห่างๆ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 18, 'และเมื่อคนเหล่านั้นได้เห็นควันไฟที่ไหม้นครนั้นก็ร้องว่า “นครใดเล่าจะเป็นเหมือนมหานครนี้”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 19, 'และเขาทั้งหลายก็โปรยผงคลีลงบนศีรษะของตน พลางร้องไห้คร่ําครวญว่า “อนิจจาเอ๋ย อนิจจาเอ๋ย มหานครนั้น อันเป็นที่ซึ่งคนทั้งปวงที่มีเรือกําปั่นเดินทะเลได้กลายเป็นคนมั่งมีด้วยเหตุจากสิ่งของมีค่าของนครนั้น เพราะภายในชั่วโมงเดียวนครนั้นก็เป็นที่รกร้างไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 20, 'เมืองสวรรค์ พวกอัครสาวกอันบริสุทธิ์ และพวกศาสดาพยากรณ์ทั้งหลาย จงร่าเริงยินดีเพราะนครนั้นเถิด เพราะพระเจ้าทรงแก้แค้นต่อนครนั้นให้ท่านทั้งหลายแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 21, 'แล้วทูตสวรรค์องค์หนึ่งที่มีฤทธิ์มาก ก็ได้ยกหินก้อนหนึ่งเหมือนหินโม่ใหญ่ทุ่มลงไปในทะเลแล้วว่า “บาบิโลนมหานครนั้นจะถูกทุ่มลงโดยแรงอย่างนี้แหละ และจะไม่มีใครเห็นนครนั้นอีกต่อไปเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 22, 'และจะไม่มีใครได้ยินเสียงนักดีดพิณเขาคู่ นักเล่นมโหรี นักเป่าปี่ และนักเป่าแตร ในเจ้าอีกต่อไป และในเจ้าจะไม่มีช่างในวิชาช่างต่างๆอีกต่อไป และจะไม่มีใครได้ยินเสียงโม่แป้งในเจ้าอีกต่อไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 23, 'และในเจ้าจะไม่มีแสงประทีปส่องสว่างอีกต่อไป และจะไม่มีใครได้ยินเสียงเจ้าบ่าวเจ้าสาวในเจ้าอีกต่อไป เพราะว่าบรรดาพ่อค้าของเจ้าได้เป็นคนใหญ่โตแห่งแผ่นดินโลกแล้ว และโดยวิทยาคมของเจ้าได้ล่อลวงบรรดาประชาชาติให้ลุ่มหลง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 24, 'และในนครนั้นเขาได้พบโลหิตของพวกศาสดาพยากรณ์และพวกวิสุทธิชน และบรรดาคนที่ถูกฆ่าบนแผ่นดินโลก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 1, 'ภายหลังเหตุการณ์เหล่านี้ข้าพเจ้าได้ยินเสียงดังกึกก้องของฝูงชนจํานวนมากในสวรรค์ร้องว่า “อาเลลูยา ความรอด สง่าราศี พระเกียรติ และฤทธิ์เดชจงมีแด่องค์พระผู้เป็นเจ้า พระเจ้าของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 2, '‘เพราะว่าการพิพากษาของพระองค์เที่ยงตรงและชอบธรรม’ พระองค์ได้ทรงพิพากษาลงโทษหญิงแพศยาคนสําคัญนั้น ที่ได้กระทําให้แผ่นดินโลกชั่วไปด้วยการล่วงประเวณีของนาง และ ‘พระองค์ได้ทรงแก้แค้นผู้หญิงนั้นเพื่อทดแทนโลหิตแห่งพวกผู้รับใช้ของพระองค์’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 3, 'คนเหล่านั้นร้องอีกครั้งว่า “อาเลลูยา ‘ควันไฟที่เกิดจากนครนั้นพลุ่งขึ้นตลอดไปเป็นนิตย์’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 4, 'และพวกผู้อาวุโสทั้งยี่สิบสี่คนกับสัตว์ทั้งสี่นั้น ก็ได้ทรุดตัวลงนมัสการพระเจ้า ผู้ประทับบนพระที่นั่งนั้นและร้องว่า “เอเมน อาเลลูยา”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 5, 'และมีเสียงออกมาจากพระที่นั่งว่า “‘ท่านทั้งหลายที่เป็นผู้รับใช้ของพระองค์ และผู้ที่ยําเกรงพระองค์ ทั้งผู้ใหญ่และผู้น้อย จงสรรเสริญพระเจ้าของเรา’”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 6, 'แล้วข้าพเจ้าได้ยินเสียงดุจเสียงฝูงชนเป็นอันมาก ดุจเสียงน้ํามากหลาย และดุจเสียงฟ้าร้องสนั่นว่า “อาเลลูยา เพราะว่าองค์พระผู้เป็นเจ้า พระเจ้า ผู้ทรงฤทธานุภาพสูงสุด ทรงครอบครองอยู่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 7, 'ขอให้เราทั้งหลายร่าเริงยินดีและถวายพระเกียรติแด่พระองค์ เพราะว่าถึงเวลามงคลสมรสของพระเมษโปดกแล้ว และมเหสีของพระองค์ได้เตรียมตัวพร้อมแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 8, 'และทรงโปรดให้เธอสวมผ้าป่านเนื้อละเอียด สะอาดและขาว เพราะผ้าป่านเนื้อละเอียดนั้นเป็นความชอบธรรมของพวกวิสุทธิชน”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 9, 'และทูตสวรรค์องค์นั้นสั่งข้าพเจ้าว่า “จงเขียนไว้เถิดว่า ความสุขมีแก่คนทั้งหลายที่ได้รับเชิญมาในการมงคลสมรสของพระเมษโปดก” และท่านบอกข้าพเจ้าว่า “ถ้อยคําเหล่านี้เป็นพระดํารัสแท้ของพระเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 10, 'แล้วข้าพเจ้าได้ทรุดตัวลงแทบเท้าของท่านเพื่อจะนมัสการท่าน แต่ท่านได้กล่าวแก่ข้าพเจ้าว่า “อย่าเลย ข้าพเจ้าเป็นเพื่อนผู้รับใช้เหมือนกับท่าน และพวกพี่น้องของท่านที่ยึดถือคําพยานของพระเยซู จงนมัสการพระเจ้าเถิด เพราะว่าคําพยานของพระเยซูนั้นเป็นหัวใจของการพยากรณ์”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 11, 'แล้วข้าพเจ้าได้เห็นสวรรค์เปิดออก และดูเถิด มีม้าขาวตัวหนึ่ง พระองค์ผู้ทรงม้านั้นมีพระนามว่า “สัตย์ซื่อและสัตย์จริง” พระองค์ทรงพิพากษาและกระทําสงครามด้วยความชอบธรรม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 12, 'พระเนตรของพระองค์ดุจเปลวไฟ และบนพระเศียรของพระองค์มีมงกุฎหลายอัน และพระองค์ทรงมีพระนามจารึกไว้ซึ่งไม่มีผู้ใดรู้จักเลย นอกจากพระองค์เอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 13, 'พระองค์ทรงฉลองพระองค์ที่จุ่มเลือด และพระนามที่เรียกพระองค์นั้นคือ “พระวาทะของพระเจ้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 14, 'เหล่าพลโยธาในสวรรค์สวมอาภรณ์ผ้าป่านเนื้อละเอียด ขาวและสะอาด ได้นั่งบนหลังม้าขาวตามเสด็จพระองค์ไป');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 15, 'มีพระแสงคมออกมาจากพระโอษฐ์ของพระองค์ เพื่อพระองค์จะได้ทรงฟันฟาดบรรดานานาประชาชาติด้วยพระแสงนั้น และพระองค์จะทรงครอบครองเขาด้วยคทาเหล็ก พระองค์จะทรงเหยียบบ่อย่ําองุ่นแห่งพระพิโรธอันเฉียบขาดของพระเจ้า ผู้ทรงฤทธานุภาพสูงสุด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 16, 'พระองค์ทรงมีพระนามจารึกที่ฉลองพระองค์ และที่ต้นพระอูรุของพระองค์ว่า “พระมหากษัตริย์แห่งมหากษัตริย์ทั้งปวงและเจ้านายแห่งเจ้านายทั้งปวง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 17, 'แล้วข้าพเจ้าเห็นทูตสวรรค์องค์หนึ่งยืนอยู่บนดวงอาทิตย์ ท่านร้องประกาศแก่นกทั้งปวงที่บินอยู่ในท้องฟ้าด้วยเสียงอันดังว่า “จงมาประชุมกันในการเลี้ยงของพระเจ้ายิ่งใหญ่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 18, 'เพื่อจะได้กินเนื้อกษัตริย์ เนื้อนายทหาร เนื้อคนมีบรรดาศักดิ์ เนื้อม้า และเนื้อคนที่นั่งบนม้า และเนื้อประชาชน ทั้งไทยและทาส ทั้งผู้ใหญ่และผู้น้อย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 19, 'และข้าพเจ้าเห็นสัตว์ร้ายนั้น และบรรดากษัตริย์บนแผ่นดินโลก พร้อมทั้งพลรบของกษัตริย์เหล่านั้น มาประชุมกันจะทําสงครามกับพระองค์ผู้ทรงม้า และกับพลโยธาของพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 20, 'สัตว์ร้ายนั้นถูกจับพร้อมด้วยผู้พยากรณ์เท็จ ที่ได้กระทําการอัศจรรย์ต่อหน้าสัตว์ร้ายนั้น และใช้การอัศจรรย์นั้นล่อลวงคนทั้งหลายที่ได้รับเครื่องหมายของสัตว์ร้ายนั้น และบูชารูปของมัน สัตว์ร้ายและผู้พยากรณ์เท็จถูกทิ้งทั้งเป็นลงในบึงไฟที่ไหม้ด้วยกํามะถัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 21, 'และคนที่เหลืออยู่นั้น ก็ถูกฆ่าด้วยพระแสงที่ออกมาจากพระโอษฐ์ของพระองค์ผู้ทรงม้านั้นเสีย และนกทั้งปวงก็กินเนื้อของคนเหล่านั้นจนอิ่ม');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 1, 'แล้วข้าพเจ้าเห็นทูตสวรรค์องค์หนึ่งลงมาจากสวรรค์ ท่านถือลูกกุญแจของเหวที่ไม่มีก้นเหวนั้นและถือโซ่ใหญ่');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 2, 'และท่านได้จับพญานาค ซึ่งเป็นงูดึกดําบรรพ์ ผู้ซึ่งเป็นพญามารและซาตาน และล่ามมันไว้พันปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 3, 'แล้วทิ้งมันลงไปในเหวที่ไม่มีก้นเหวนั้น แล้วได้ลั่นกุญแจประทับตรา เพื่อไม่ให้มันล่อลวงบรรดาประชาชาติได้อีกต่อไป จนครบกําหนดพันปีแล้วหลังจากนั้นจะต้องปล่อยมันออกไปชั่วขณะหนึ่ง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 4, 'ข้าพเจ้าได้เห็นบัลลังก์หลายบัลลังก์ และผู้ที่นั่งบนบัลลังก์นั้น ทรงมอบให้เป็นผู้ที่จะพิพากษา และข้าพเจ้ายังได้เห็นดวงวิญญาณของคนทั้งปวงที่ถูกตัดศีรษะ เพราะเป็นพยานของพระเยซู และเพราะพระวจนะของพระเจ้า และเป็นผู้ที่ไม่ได้บูชาสัตว์ร้ายนั้นหรือรูปของมัน และไม่ได้รับเครื่องหมายของมันไว้ที่หน้าผากหรือที่มือของเขา คนเหล่านั้นกลับมีชีวิตขึ้นมาใหม่ และได้ครอบครองร่วมกับพระคริสต์เป็นเวลาพันปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 5, 'แต่คนอื่นๆที่ตายแล้วไม่ได้กลับมีชีวิตอีกจนกว่าจะครบกําหนดพันปี นี่แหละคือการฟื้นจากความตายครั้งแรก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 6, 'ผู้ใดที่ได้มีส่วนในการฟื้นจากความตายครั้งแรกก็เป็นสุขและบริสุทธิ์ ความตายครั้งที่สองจะไม่มีอํานาจเหนือคนเหล่านั้น แต่เขาจะเป็นปุโรหิตของพระเจ้าและของพระคริสต์ และจะครอบครองร่วมกับพระองค์ตลอดเวลาพันปี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 7, 'ครั้นพันปีล่วงไปแล้ว ก็จะปล่อยซาตานออกจากคุกที่ขังมันไว้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 8, 'และมันจะออกไปล่อลวงบรรดาประชาชาติทั้งสี่ทิศของแผ่นดินโลก คือโกกและมาโกก ให้คนมาชุมนุมกันทําศึกสงคราม จํานวนคนเหล่านั้นมากมายดุจเม็ดทรายที่ทะเล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 9, 'และคนเหล่านั้นยกขบวนออกไปทั่วแผ่นดินโลก และล้อมกองทัพของพวกวิสุทธิชน และเมืองอันเป็นที่รักนั้นไว้ แต่ไฟได้ตกลงมาจากพระเจ้าออกจากสวรรค์ เผาผลาญคนเหล่านั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 10, 'ส่วนพญามารที่ล่อลวงเขาเหล่านั้นก็ถูกโยนลงไปในบึงไฟและกํามะถัน ที่สัตว์ร้ายและผู้พยากรณ์เท็จอยู่นั้น และมันต้องทนทุกข์ทรมานทั้งกลางวันและกลางคืนตลอดไปเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 11, 'ข้าพเจ้าได้เห็นพระที่นั่งใหญ่สีขาว และเห็นพระองค์ผู้ประทับบนพระที่นั่งนั้น และแผ่นดินโลกและฟ้าอากาศก็อันตรธานไปจากพระพักตร์พระองค์ และไม่มีที่อยู่สําหรับแผ่นดินโลกและฟ้าอากาศนั้นต่อไปเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 12, 'ข้าพเจ้าได้เห็นบรรดาผู้ที่ตายแล้ว ทั้งผู้ใหญ่และผู้น้อย ยืนอยู่จําเพาะพระพักตร์พระเจ้า และหนังสือต่างๆก็เปิดออก หนังสืออีกม้วนหนึ่งก็เปิดออกด้วย คือหนังสือแห่งชีวิต และผู้ที่ตายไปแล้วก็ถูกพิพากษาตามข้อความที่จารึกไว้ในหนังสือเหล่านั้น ตามที่เขาได้กระทํา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 13, 'ทะเลก็ส่งคืนคนทั้งหลายที่ตายในทะเล ความตายและนรกก็ส่งคืนคนทั้งหลายที่อยู่ในที่เหล่านั้น และคนทั้งหลายก็ถูกพิพากษาตามการกระทําของตนหมดทุกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 14, 'แล้วความตายและนรกก็ถูกผลักทิ้งลงไปในบึงไฟ นี่แหละเป็นความตายครั้งที่สอง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 15, 'และผู้ใดที่ไม่มีชื่อจดไว้ในหนังสือแห่งชีวิต ผู้นั้นก็ถูกทิ้งลงไปในบึงไฟ');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 1, 'ข้าพเจ้าได้เห็นท้องฟ้าใหม่และแผ่นดินโลกใหม่ เพราะท้องฟ้าเดิมและแผ่นดินโลกเดิมนั้นหายไปหมดสิ้นแล้ว และทะเลก็ไม่มีอีกแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 2, 'ข้าพเจ้า คือยอห์น ได้เห็นเมืองบริสุทธิ์ คือกรุงเยรูซาเล็มใหม่ เลื่อนลอยลงมาจากพระเจ้าและจากสวรรค์ กรุงนี้ได้จัดเตรียมไว้พร้อมแล้ว เหมือนอย่างเจ้าสาวแต่งตัวไว้สําหรับสามี');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 3, 'ข้าพเจ้าได้ยินเสียงดังมาจากสวรรค์ว่า “ดูเถิด พลับพลาของพระเจ้าอยู่กับมนุษย์แล้ว พระองค์จะทรงสถิตกับเขา เขาจะเป็นชนชาติของพระองค์ และพระเจ้าเองจะประทับอยู่กับเขา และจะทรงเป็นพระเจ้าของเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 4, 'พระเจ้าจะทรงเช็ดน้ําตาทุกๆหยดจากตาของเขา ความตายจะไม่มีอีกต่อไป ความคร่ําครวญ การร้องไห้ และการเจ็บปวดจะไม่มีอีกต่อไป เพราะยุคเดิมนั้นได้ผ่านพ้นไปแล้ว”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 5, 'พระองค์ผู้ประทับบนพระที่นั่งตรัสว่า “ดูเถิด เราสร้างสิ่งสารพัดขึ้นใหม่” และพระองค์ตรัสกับข้าพเจ้าว่า “จงเขียนไว้เถิด เพราะว่าถ้อยคําเหล่านี้เป็นคําสัตย์จริงและสัตย์ซื่อ”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 6, 'พระองค์ตรัสกับข้าพเจ้าว่า “สําเร็จแล้ว เราเป็นอัลฟาและโอเมกา เป็นปฐมและอวสาน ผู้ใดกระหาย เราจะให้ผู้นั้นดื่มจากบ่อน้ําพุแห่งชีวิตโดยไม่ต้องเสียอะไรเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 7, 'ผู้ใดมีชัยชนะ ผู้นั้นจะได้รับสิ่งสารพัดเป็นมรดก และเราจะเป็นพระเจ้าของเขา และเขาจะเป็นบุตรของเรา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 8, 'แต่คนขลาด คนไม่เชื่อ คนที่น่าสะอิดสะเอียน ฆาตกร คนล่วงประเวณี คนใช้เวทมนตร์ คนไหว้รูปเคารพ และคนทั้งปวงที่พูดมุสานั้น จะได้รับส่วนของตนในบึงที่เผาไหม้ด้วยไฟและกํามะถัน นั่นคือความตายครั้งที่สอง”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 9, 'ทูตสวรรค์องค์หนึ่งในบรรดาทูตสวรรค์เจ็ดองค์ที่ถือขันเจ็ดใบ อันเต็มด้วยภัยพิบัติสุดท้ายทั้งเจ็ดประการนั้น ได้มาพูดกับข้าพเจ้าว่า “เชิญมานี่เถิด ข้าพเจ้าจะให้ท่านดูเจ้าสาวที่เป็นมเหสีของพระเมษโปดก”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 10, 'ท่านได้นําข้าพเจ้าโดยพระวิญญาณขึ้นไปบนภูเขาสูงใหญ่ และได้สําแดงให้ข้าพเจ้าเห็นเมืองใหญ่นั้น คือกรุงเยรูซาเล็มอันบริสุทธิ์ ซึ่งกําลังลอยลงมาจากสวรรค์และจากพระเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 11, 'เมืองนั้นประกอบด้วยสง่าราศีของพระเจ้า ใสสว่างดุจพลอยมณีอันหาค่ามิได้ เช่นเดียวกับพลอยหยกอันสุกใสเหมือนแก้วผลึก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 12, 'เมืองนั้นมีกําแพงสูงใหญ่ มีประตูสิบสองประตู และที่ประตูมีทูตสวรรค์สิบสององค์ และที่ประตูนั้นจารึกเป็นชื่อตระกูลของชนชาติอิสราเอลสิบสองตระกูล');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 13, 'ทางด้านตะวันออกมีสามประตู ทางด้านเหนือมีสามประตู ทางด้านใต้มีสามประตู ทางด้านตะวันตกมีสามประตู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 14, 'และกําแพงเมืองนั้นมีฐานสิบสองฐาน และที่ฐานนั้นจารึกชื่ออัครสาวกสิบสองคนของพระเมษโปดก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 15, 'ทูตสวรรค์องค์ที่พูดกับข้าพเจ้านั้น ถือไม้วัดทองคําเพื่อจะวัดเมือง และวัดประตูและกําแพงของเมืองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 16, 'เมืองนั้นเป็นสี่เหลี่ยมจัตุรัส กว้างยาวเท่ากันและท่านเอาไม้วัดเมืองนั้น ได้สองพันสี่ร้อยกิโลเมตร กว้างยาวและสูงเท่ากัน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 17, 'ท่านวัดกําแพงเมืองนั้น ได้เจ็ดสิบสองเมตร ตามมาตรวัดของมนุษย์ ซึ่งคือมาตรวัดของทูตสวรรค์องค์นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 18, 'กําแพงเมืองนั้นก่อด้วยพลอยหยก และเมืองนั้นเป็นทองคําบริสุทธิ์ สุกใสดุจแก้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 19, 'ฐานของกําแพงเมืองนั้นประดับด้วยเพชรพลอยทุกชนิด ฐานที่หนึ่งเป็นพลอยหยก ที่สองไพทูรย์ ที่สามหินคว๊อตซ์โปร่งแสง ที่สี่มรกต');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 20, 'ที่ห้าโกเมน ที่หกทับทิม ที่เจ็ดเพชรสีเขียว ที่แปดพลอยเขียว ที่เก้าบุษราคัม ที่สิบหยก ที่สิบเอ็ดพลอยสีแดง ที่สิบสองเป็นพลอยสีม่วง');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 21, 'ประตูทั้งสิบสองประตูนั้นเป็นไข่มุกสิบสองเม็ด ประตูละเม็ด และถนนในเมืองนั้นเป็นทองคําบริสุทธิ์ ใสราวกับแก้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 22, 'ข้าพเจ้าไม่เห็นมีพระวิหารในเมืองนั้นเลย เพราะองค์พระผู้เป็นเจ้า พระเจ้า ผู้ทรงฤทธานุภาพสูงสุด และพระเมษโปดกทรงเป็นพระวิหารในเมืองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 23, 'เมืองนั้นไม่ต้องการแสงของดวงอาทิตย์และดวงจันทร์ เพราะว่าสง่าราศีของพระเจ้าเป็นแสงสว่างของเมืองนั้น และพระเมษโปดกทรงเป็นความสว่างของเมืองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 24, 'บรรดาประชาชาติที่รอดแล้วจะเดินไปในท่ามกลางแสงสว่างของเมืองนั้น และบรรดากษัตริย์ในแผ่นดินโลกจะนําสง่าราศีและเกียรติของตนเข้ามาในเมืองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 25, 'ประตูเมืองทุกประตูจะไม่ปิดเลยในเวลากลางวัน ด้วยว่าจะไม่มีเวลากลางคืนในเมืองนั้นเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 26, 'และคนทั้งหลายจะนําสง่าราศีและเกียรติของบรรดาประชาชาติเข้ามาในเมืองนั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 27, 'สิ่งใดที่เป็นมลทิน หรือผู้ใดก็ตามที่กระทําสิ่งที่น่าสะอิดสะเอียน หรือพูดมุสาจะเข้าไปในเมืองไม่ได้เลย เว้นแต่เฉพาะคนที่มีชื่อจดไว้ในหนังสือแห่งชีวิตของพระเมษโปดกเท่านั้นจึงจะเข้าไปได้');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 1, 'ท่านได้ชี้ให้ข้าพเจ้าดูแม่น้ําบริสุทธิ์ที่มีน้ําแห่งชีวิต ใสเหมือนแก้วผลึก ไหลออกมาจากพระที่นั่งของพระเจ้า และของพระเมษโปดก');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 2, 'ท่ามกลางถนนในเมืองนั้นและริมแม่น้ําทั้งสองฟากมีต้นไม้แห่งชีวิต ซึ่งออกผลสิบสองชนิด ออกผลทุกๆเดือน และใบของต้นไม้นั้นสําหรับรักษาบรรดาประชาชาติให้หาย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 3, 'จะไม่มีการสาปแช่งใดๆอีกต่อไป พระที่นั่งของพระเจ้าและของพระเมษโปดกจะตั้งอยู่ในเมืองนั้น และบรรดาผู้รับใช้ของพระองค์จะปรนนิบัติพระองค์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 4, 'เขาเหล่านั้นจะเห็นพระพักตร์พระองค์ และพระนามของพระองค์จะประทับอยู่ที่หน้าผากเขา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 5, 'กลางคืนจะไม่มีที่นั่น เขาไม่ต้องการแสงเทียนหรือแสงอาทิตย์ เพราะว่าองค์พระผู้เป็นเจ้าคือพระเจ้าทรงประทานแสงสว่างแก่เขา และเขาจะครอบครองอยู่ตลอดไปเป็นนิตย์');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 6, 'และทูตสวรรค์องค์นั้นบอกข้าพเจ้าว่า “ถ้อยคําเหล่านี้เป็นคําสัตย์ซื่อและสัตย์จริง และองค์พระผู้เป็นเจ้า พระเจ้าแห่งพวกศาสดาพยากรณ์อันบริสุทธิ์ ได้ทรงใช้ทูตสวรรค์ของพระองค์สําแดงแก่บรรดาผู้รับใช้ของพระองค์ ถึงเหตุการณ์ทั้งปวงซึ่งจะอุบัติขึ้นในไม่ช้า”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 7, '“ดูเถิด เราจะมาโดยเร็ว ผู้ใดที่ถือรักษาคําพยากรณ์ในหนังสือนี้ก็เป็นสุข”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 8, 'ข้าพเจ้า คือยอห์น เป็นผู้ได้เห็นและได้ยินเหตุการณ์เหล่านี้ และครั้นข้าพเจ้าได้ยินและได้เห็นแล้ว ข้าพเจ้าก็ทรุดตัวลงจะนมัสการแทบเท้าทูตสวรรค์ที่ได้สําแดงเหตุการณ์เหล่านี้แก่ข้าพเจ้า');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 9, 'แต่ท่านห้ามข้าพเจ้าว่า “อย่าเลย ด้วยว่าข้าพเจ้าเป็นเพื่อนผู้รับใช้เช่นเดียวกับท่าน และพวกพี่น้องของท่านคือพวกศาสดาพยากรณ์ และพวกที่ถือรักษาถ้อยคําในหนังสือนี้ จงนมัสการพระเจ้าเถิด”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 10, 'และท่านบอกข้าพเจ้าว่า “อย่าประทับตราปิดคําพยากรณ์ในหนังสือนี้ เพราะว่าใกล้จะถึงเวลานั้นแล้ว');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 11, 'ผู้ที่เป็นคนอธรรมก็ให้เขาอธรรมต่อไป ผู้ที่เป็นคนลามกก็ให้เขาลามกต่อไป ผู้ที่เป็นคนชอบธรรมก็ให้เขาชอบธรรมต่อไป และผู้ที่เป็นคนบริสุทธิ์ก็ให้เขาเป็นคนบริสุทธิ์ต่อไป”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 12, '“ดูเถิด เราจะมาโดยเร็ว และจะนําบําเหน็จของเรามาด้วย เพื่อตอบแทนการกระทําของทุกคน');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 13, 'เราคืออัลฟาและโอเมกา เป็นปฐมและเป็นอวสาน เป็นเบื้องต้นและเบื้องปลาย”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 14, 'คนทั้งหลายที่ประพฤติตามพระบัญญัติของพระองค์ก็เป็นสุข เพื่อว่าเขาจะได้มีสิทธิ์ในต้นไม้แห่งชีวิต และเพื่อเขาจะได้เข้าไปในเมืองนั้นโดยทางประตู');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 15, 'ด้วยว่าภายนอกนั้นมีสุนัข คนใช้เวทมนตร์ คนล่วงประเวณี ฆาตกร คนไหว้รูปเคารพ คนใดที่รักและกระทําการมุสา');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 16, '“เราคือเยซูผู้ใช้ให้ทูตสวรรค์ของเราไปเป็นพยานสําแดงเหตุการณ์เหล่านี้แก่ท่านเพื่อคริสตจักรทั้งหลาย เราเป็นรากและเป็นเชื้อสายของดาวิด และเป็นดาวประจํารุ่งอันสุกใส”');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 17, 'พระวิญญาณและเจ้าสาวตรัสว่า “เชิญมาเถิด” และให้ผู้ที่ได้ยินกล่าวว่า “เชิญมาเถิด” และให้ผู้ที่กระหายเข้ามา ผู้ใดมีใจปรารถนา ก็ให้ผู้นั้นมารับน้ําแห่งชีวิตโดยไม่ต้องเสียอะไรเลย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 18, 'ข้าพเจ้าเป็นพยานแก่ทุกคนที่ได้ยินคําพยากรณ์ในหนังสือนี้ว่า ถ้าผู้ใดจะเพิ่มเติมคําเข้าไปในหนังสือนี้ พระเจ้าก็จะทรงเพิ่มภัยพิบัติที่เขียนไว้ในหนังสือม้วนนี้แก่ผู้นั้น');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 19, 'และถ้าผู้ใดตัดข้อความออกจากหนังสือพยากรณ์นี้ พระเจ้าก็จะทรงเอาส่วนแบ่งของผู้นั้นที่มีอยู่ในหนังสือแห่งชีวิต และที่มีอยู่ในเมืองบริสุทธิ์นั้น และจากสิ่งที่มีเขียนไว้ในหนังสือม้วนนี้ไปเสีย');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 20, 'พระองค์ผู้ทรงเป็นพยานในเหตุการณ์ทั้งปวงนี้ ตรัสว่า “แน่นอน เราจะมาโดยเร็ว” เอเมน พระเยซูเจ้า ขอให้เป็นเช่นนั้น เชิญเสด็จมาเถิด');
INSERT INTO `ThaiKJV_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 21, 'ขอให้พระคุณแห่งพระเยซูคริสต์องค์พระผู้เป็นเจ้าของเรา จงดํารงอยู่กับท่านทั้งหลายเถิด เอเมน');
